namespace Polyglot

module spiral_compiler =
    type CompilerRuntimeActivationSource =
        | CompilerRuntimeStandaloneMain
        | CompilerRuntimeBuildFile

    type CompilerRuntimeActivationPhase =
        | CompilerRuntimeCold
        | CompilerRuntimeInProcess of source:CompilerRuntimeActivationSource * enteredAtMs:int64

    module CompilerRuntimeActivation =
        let private gate = obj()
        let mutable private phase = CompilerRuntimeCold

        let private sourceText = function
            | CompilerRuntimeStandaloneMain -> "standalone_main"
            | CompilerRuntimeBuildFile -> "build_file"

        let markInProcessEntered source =
            lock gate (fun () ->
                match phase with
                | CompilerRuntimeCold ->
                    phase <- CompilerRuntimeInProcess(source, System.Environment.TickCount64)
                | CompilerRuntimeInProcess _ -> ())

        let isInProcessEntered () =
            lock gate (fun () ->
                match phase with
                | CompilerRuntimeInProcess _ -> true
                | CompilerRuntimeCold -> false)

        let currentSourceText () =
            lock gate (fun () ->
                match phase with
                | CompilerRuntimeInProcess(source, _) -> sourceText source
                | CompilerRuntimeCold -> "cold")

        let requireInProcessEntered consumer =
            if not (isInProcessEntered ()) then
                invalidOp ("compiler_runtime_activation_before_in_process_session|consumer=" + consumer)

    module FastRuntimeFormat =

        // Boundary-only replacement for high-arity PrintfFormat sites.
        // The literal is unchanged; boxing removes formatting arity from the F# type graph.
        let private invariantCulture = System.Globalization.CultureInfo.InvariantCulture

        let private appendInvariant (builder:System.Text.StringBuilder) (format:string) (value:obj) =
            if isNull value then ()
            else
                match value with
                | :? System.IFormattable as formattable ->
                    builder.Append(formattable.ToString(format, invariantCulture)) |> ignore
                | _ ->
                    builder.Append(value.ToString()) |> ignore

        // Keep object formatting behind an explicit render boundary, but avoid
        // F# structural %A reflection as a hidden domain serializer.
        let pretty (value:obj) = if isNull value then "null" else value.ToString()
        let objectText (value:obj) = if isNull value then "null" else value.ToString()

        let format (template:string) (args:obj array) =
            let builder = System.Text.StringBuilder(template.Length + (args.Length * 8))
            let mutable templateIndex = 0
            let mutable argumentIndex = 0
            let nextArgument () =
                if argumentIndex >= args.Length then
                    box "<missing-fast-runtime-format-argument>"
                else
                    let value = args.[argumentIndex]
                    argumentIndex <- argumentIndex + 1
                    value
            while templateIndex < template.Length do
                let mutable marker = templateIndex
                while marker < template.Length && template.[marker] <> '%' do marker <- marker + 1
                if marker >= template.Length then
                    builder.Append(template, templateIndex, template.Length - templateIndex) |> ignore
                    templateIndex <- template.Length
                else
                    if marker > templateIndex then
                        builder.Append(template, templateIndex, marker - templateIndex) |> ignore
                    if marker + 1 < template.Length && template.[marker + 1] = '%' then
                        builder.Append('%') |> ignore
                        templateIndex <- marker + 2
                    else
                        let mutable cursor = marker + 1
                        let mutable unsupportedWidthOrFlags = false
                        while cursor < template.Length
                              && (template.[cursor] = '-' || template.[cursor] = '+' || template.[cursor] = ' '
                                  || template.[cursor] = '0' || template.[cursor] = '#') do
                            unsupportedWidthOrFlags <- true
                            cursor <- cursor + 1
                        while cursor < template.Length && System.Char.IsDigit(template.[cursor]) do
                            unsupportedWidthOrFlags <- true
                            cursor <- cursor + 1
                        let mutable precision = -1
                        if cursor < template.Length && template.[cursor] = '.' then
                            cursor <- cursor + 1
                            let precisionStart = cursor
                            while cursor < template.Length && System.Char.IsDigit(template.[cursor]) do cursor <- cursor + 1
                            if cursor = precisionStart then invalidArg "template" "FastRuntimeFormat precision requires digits."
                            precision <- System.Int32.Parse(template.Substring(precisionStart, cursor - precisionStart), invariantCulture)
                        if unsupportedWidthOrFlags then invalidArg "template" "FastRuntimeFormat width/flags are outside the mechanical migration."
                        if cursor >= template.Length then invalidArg "template" "FastRuntimeFormat dangling percent marker."
                        let value = nextArgument ()
                        match template.[cursor] with
                        | 's' -> if not (isNull value) then builder.Append(value.ToString()) |> ignore
                        | 'b' ->
                            match value with
                            | null -> builder.Append("null") |> ignore
                            | :? bool as boolValue -> builder.Append(if boolValue then "true" else "false") |> ignore
                            | :? string as text ->
                                if System.String.Equals(text, "true", System.StringComparison.OrdinalIgnoreCase)
                                   || System.String.Equals(text, "false", System.StringComparison.OrdinalIgnoreCase) then
                                    builder.Append(text.ToLowerInvariant()) |> ignore
                                else
                                    builder.Append(text) |> ignore
                            | _ -> builder.Append(value.ToString()) |> ignore
                        | 'c' ->
                            match value with
                            | null -> builder.Append("null") |> ignore
                            | :? char as charValue -> builder.Append(charValue) |> ignore
                            | _ -> builder.Append(value.ToString()) |> ignore
                        | 'd' | 'i' | 'u' -> appendInvariant builder null value
                        | 'f' ->
                            let digits = if precision < 0 then 6 else precision
                            appendInvariant builder ("F" + System.Convert.ToString(digits, invariantCulture)) value
                        | other -> invalidArg "template" ("FastRuntimeFormat unsupported specifier %" + string other)
                        templateIndex <- cursor + 1
            // Telemetry rendering must never become terminal authority. If a
            // mechanically migrated callsite still supplies extra values, keep
            // the durable row alive and let explicit fields expose the drift.
            builder.ToString()

