    module CompilerIdentityKernel =
        [<Struct>]
        type ContentDigest = private | ContentDigest of string

        module ContentDigest =
            // Digests identify things inside one compile (work units, receipts, refs); nothing outside the
            // process checks them. SHA-256 (with the UTF-8 encoding, concatenations and a memo whose key hashing
            // cost as much) was ~25% of a large compile (FRONTIER.md fix 39), so this is a fast non-cryptographic
            // 256-bit hash: four independently seeded 64-bit lanes over the UTF-16 text, each finished with
            // MurmurHash3's fmix64. The format is unchanged: 64 lowercase hex digits, ':', the label.
            let inline private fmix64 (k0: uint64) =
                let mutable k = k0
                k <- k ^^^ (k >>> 33)
                k <- k * 0xff51afd7ed558ccdUL
                k <- k ^^^ (k >>> 33)
                k <- k * 0xc4ceb9fe1a85ec53UL
                k ^^^ (k >>> 33)

            let private lanes (label:string) (text:string) =
                let mutable h1 = 0x9E3779B97F4A7C15UL
                let mutable h2 = 0xC2B2AE3D27D4EB4FUL
                let mutable h3 = 0x165667B19E3779F9UL
                let mutable h4 = 0x27D4EB2F165667C5UL
                let labelLength = label.Length
                for i = 0 to labelLength + text.Length do
                    let ch = if i < labelLength then label.[i] elif i = labelLength then '|' else text.[i - labelLength - 1]
                    let v = uint64 ch
                    h1 <- (h1 ^^^ v) * 0x100000001B3UL
                    h2 <- ((h2 + v) * 0x9E3779B97F4A7C15UL) ^^^ (h2 >>> 29)
                    h3 <- ((h3 ^^^ (v <<< 17)) * 0xFF51AFD7ED558CCDUL) + 0x9E3779B97F4A7C15UL
                    let r = h4 + (v * 0xC2B2AE3D27D4EB4FUL)
                    h4 <- ((r <<< 31) ||| (r >>> 33)) * 0x9E3779B185EBCA87UL
                let len = uint64 (label.Length + text.Length)
                let a = fmix64 (h1 ^^^ len)
                let b = fmix64 (h2 + a)
                let c = fmix64 (h3 ^^^ b)
                let d = fmix64 (h4 + c)
                struct (a, b, c, d)

            let private hexOf (struct (a: uint64, b: uint64, c: uint64, d: uint64)) =
                a.ToString("x16") + b.ToString("x16") + c.ToString("x16") + d.ToString("x16")

            let ofText label (text:string) =
                ContentDigest(hexOf (lanes label (if isNull text then "<null>" else text)) + ":" + label)

            /// The same fast hash for other in-process identity refs (was SHA-256 at each site).
            let hash64 (text:string) =
                let struct (a, _, _, _) = lanes "" (if isNull text then "" else text)
                a

            /// 64 lowercase hex digits of the fast hash, where a SHA-256 hex string was the identity.
            let hex256 (text:string) = hexOf (lanes "" (if isNull text then "" else text))

            let text (ContentDigest value) = value

            let tryParse (value:string) =
                if System.String.IsNullOrWhiteSpace value then None
                else
                    let separator = 64
                    if value.Length <= separator + 1 || value.[separator] <> ':' then None
                    else
                        let hex = value.Substring(0, separator)
                        let label = value.Substring(separator + 1)
                        let validHex =
                            hex
                            |> Seq.forall (fun c ->
                                (c >= '0' && c <= '9')
                                || (c >= 'a' && c <= 'f'))
                        if validHex && not (System.String.IsNullOrWhiteSpace label) then Some(ContentDigest value)
                        else None

            let requireParsed field value =
                match tryParse value with
                | Some digest -> digest
                | None -> invalidArg field ("invalid content digest: " + value)

        type WorkSiteKind private () =
            static member InternedKindTag () = 0x100001u
        type WorkShapeKind private () =
            static member InternedKindTag () = 0x100002u
        type InstantiationKind private () =
            static member InternedKindTag () = 0x100003u
        type BackendKind private () =
            static member InternedKindTag () = 0x100004u
        type OperationalReasonKind private () =
            static member InternedKindTag () = 0x100005u
        type CicScopeKind private () =
            static member InternedKindTag () = 0x100020u
        type CicBinderKind private () =
            static member InternedKindTag () = 0x100021u
        type CicConstantNameKind private () =
            static member InternedKindTag () = 0x100022u
        type CicMetaNameKind private () =
            static member InternedKindTag () = 0x100023u
        type CicDefinitionNameKind private () =
            static member InternedKindTag () = 0x100024u
        type CicInvariantNameKind private () =
            static member InternedKindTag () = 0x100025u
        type CicUniverseNameKind private () =
            static member InternedKindTag () = 0x100026u

        [<Struct; CustomEquality; CustomComparison>]
        type InternedTextId<'Kind> = private {
            slot : int64
            digest : ContentDigest
        }
        with
            override this.Equals(other:obj) =
                match other with
                | :? InternedTextId<'Kind> as other -> this.slot = other.slot
                | _ -> false
            override this.GetHashCode() = this.slot.GetHashCode()
            interface System.IEquatable<InternedTextId<'Kind>> with
                member this.Equals(other:InternedTextId<'Kind>) = this.slot = other.slot
            interface System.IComparable with
                member this.CompareTo(other:obj) =
                    match other with
                    | :? InternedTextId<'Kind> as other -> compare this.slot other.slot
                    | _ -> invalidArg "other" "cannot compare interned ids of different types"
            interface System.IComparable<InternedTextId<'Kind>> with
                member this.CompareTo(other:InternedTextId<'Kind>) = compare this.slot other.slot

        module InternedTextIdOps =
            [<StructuralEquality; NoComparison>]
            type private InternedTextIdentity = {
                kindTag : uint32
                value : string
            }

            let private gate = obj()
            let private slotByIdentity = System.Collections.Generic.Dictionary<InternedTextIdentity,int64>()
            let private textBySlot = System.Collections.Generic.Dictionary<int64,string>()
            let mutable private nextSlot = 0L

            let intern<'Kind> kindTag (value:string) : InternedTextId<'Kind> =
                let normalized = if isNull value then "<null>" else value
                let identity : InternedTextIdentity =
                    { kindTag = kindTag
                      value = normalized }
                lock gate (fun () ->
                    let slot =
                        match slotByIdentity.TryGetValue identity with
                        | true, existing -> existing
                        | false, _ ->
                            nextSlot <- nextSlot + 1L
                            slotByIdentity.[identity] <- nextSlot
                            textBySlot.[nextSlot] <- normalized
                            nextSlot
                    { slot = slot
                      digest = ContentDigest.ofText (FastRuntimeFormat.format "interned-kind:%u" [| box kindTag |]) normalized })

            let slot (identity:InternedTextId<'Kind>) = identity.slot
            let digest (identity:InternedTextId<'Kind>) = identity.digest
            let text (identity:InternedTextId<'Kind>) =
                lock gate (fun () ->
                    match textBySlot.TryGetValue identity.slot with
                    | true, value -> value
                    | false, _ -> ContentDigest.text identity.digest)

        module InternedTextId =
            let inline create< ^Kind when ^Kind : (static member InternedKindTag : unit -> uint32)> value : InternedTextId< ^Kind> =
                let kindTag = ((^Kind) : (static member InternedKindTag : unit -> uint32) ())
                InternedTextIdOps.intern< ^Kind> kindTag value

