    module NativeCutoverStableRef =
        let private gate = obj()
        let private byPayload : System.Collections.Generic.Dictionary<CompilerIdentityKernel.ContentDigest,uint32> =
            System.Collections.Generic.Dictionary<CompilerIdentityKernel.ContentDigest,uint32>()
        let private byValue : System.Collections.Generic.Dictionary<uint32,string> =
            System.Collections.Generic.Dictionary<uint32,string>()

        // In-process identity refs: the fast hash of ContentDigest (fix 39), not SHA-256.
        let private identityOf label (parts:seq<string>) = label + "|" + (parts |> String.concat "|")

        let digest64 label parts = CompilerIdentityKernel.ContentDigest.hash64 (identityOf label parts)

        let ref32 label parts =
            let identity = identityOf label parts
            let identityRef = CompilerIdentityKernel.ContentDigest.ofText "native-cutover-stable-ref" identity
            lock gate (fun () ->
                match byPayload.TryGetValue identityRef with
                | true, existing -> existing
                | false, _ ->
                    let mutable salt = 0
                    let mutable candidate = 0u
                    let mutable accepted = false
                    while not accepted do
                        let saltedIdentity = if salt = 0 then identity else identity + "#" + string salt
                        candidate <- uint32 (CompilerIdentityKernel.ContentDigest.hash64 saltedIdentity >>> 32)
                        if candidate = 0u then
                            salt <- salt + 1
                        else
                            match byValue.TryGetValue candidate with
                            | false, _ -> accepted <- true
                            | true, prior when prior = identity -> accepted <- true
                            | true, _ -> salt <- salt + 1
                    byPayload.[identityRef] <- candidate
                    byValue.[candidate] <- identity
                    candidate)

    [<Struct>]
    type NativeCutoverCicArenaGenerationId = private NativeCutoverCicArenaGenerationId of uint64

    [<Struct>]
    type NativeCutoverCicEnvironmentRevision = private NativeCutoverCicEnvironmentRevision of uint64

    type NativeCutoverCicKernelCommitDisposition =
        | NativeCutoverCicKernelCommitAccepted
        | NativeCutoverCicKernelCommitDuplicate
        | NativeCutoverCicKernelCommitRejectedMetavariableLeak of metavariableCount:int64
        | NativeCutoverCicKernelCommitRejectedCounterRegression

    let private nativeCutoverCicKernelCommitDispositionText = function
        | NativeCutoverCicKernelCommitAccepted -> "accepted"
        | NativeCutoverCicKernelCommitDuplicate -> "duplicate"
        | NativeCutoverCicKernelCommitRejectedMetavariableLeak count -> "metavariable-leak:" + string count
        | NativeCutoverCicKernelCommitRejectedCounterRegression -> "counter-regression"

    type NativeCutoverCicKernelCommitReceipt = private {
        receiptRef : uint32
        parentGeneration : NativeCutoverCicArenaGenerationId
        childGeneration : NativeCutoverCicArenaGenerationId
        environmentBefore : NativeCutoverCicEnvironmentRevision
        environmentAfter : NativeCutoverCicEnvironmentRevision
        disposition : NativeCutoverCicKernelCommitDisposition
        counterDigest : uint64
        weightedCostDelta : int64
        declarationDelta : int64
        checkDelta : int64
        exactOnceRef : uint32
        reducerSequence : int64
    }

    type NativeCutoverCicKernelAuthority = private {
        generation : NativeCutoverCicArenaGenerationId
        environmentRevision : NativeCutoverCicEnvironmentRevision
        lastCounters : NativeCutoverCicKernelCounters
        retiredWeightedCost : int64
        committedDeclarationCount : int64
        committedCheckCount : int64
        exactOnceRefs : Set<uint32>
        lastCommit : NativeCutoverCicKernelCommitReceipt option
    }

    let private nativeCutoverCicWeightedCost counters =
        max 0L counters.kernelCheckCount
        + max 0L counters.whnfCacheMisses * 2L
        + max 0L counters.defeqSolvedCount * 4L
        + max 0L counters.defeqBlockedCount * 8L
        + max 0L counters.universeSolverIterations * 3L
        + max 0L counters.recursorReductionCount * 2L

    let private nativeCutoverCicKernelCountersZero : NativeCutoverCicKernelCounters =
        { kernelTermCount = 0L
          kernelLevelCount = 0L
          kernelDeclarationCount = 0L
          kernelCheckCount = 0L
          whnfQueries = 0L
          whnfCacheHits = 0L
          whnfCacheMisses = 0L
          defeqQueries = 0L
          defeqCacheHits = 0L
          defeqSolvedCount = 0L
          defeqBlockedCount = 0L
          universeConstraintCount = 0L
          universeSolverIterations = 0L
          recursorReductionCount = 0L
          maxContextDepth = 0L
          arenaBytes = 0L
          hashconsHits = 0L
          hashconsMisses = 0L
          metavarsInKernel = 0L }

    let private nativeCutoverCicKernelAuthorityInitial : NativeCutoverCicKernelAuthority =
        { generation = NativeCutoverCicArenaGenerationId 0UL
          environmentRevision = NativeCutoverCicEnvironmentRevision 0UL
          lastCounters = nativeCutoverCicKernelCountersZero
          retiredWeightedCost = 0L
          committedDeclarationCount = 0L
          committedCheckCount = 0L
          exactOnceRefs = Set.empty
          lastCommit = None }

    let private nativeCutoverCicCounterDigest (counters:NativeCutoverCicKernelCounters) =
        NativeCutoverStableRef.digest64
            "native-cic-kernel-counters"
            [ string counters.kernelTermCount
              string counters.kernelLevelCount
              string counters.kernelDeclarationCount
              string counters.kernelCheckCount
              string counters.whnfQueries
              string counters.whnfCacheHits
              string counters.whnfCacheMisses
              string counters.defeqQueries
              string counters.defeqCacheHits
              string counters.defeqSolvedCount
              string counters.defeqBlockedCount
              string counters.universeConstraintCount
              string counters.universeSolverIterations
              string counters.recursorReductionCount
              string counters.arenaBytes
              string counters.hashconsHits
              string counters.hashconsMisses
              string counters.metavarsInKernel ]

    let private nativeCutoverCicKernelCommit
        reducerSequence
        (counters:NativeCutoverCicKernelCounters)
        (authority:NativeCutoverCicKernelAuthority)
        : NativeCutoverCicKernelAuthority * NativeCutoverCicKernelCommitReceipt =
        let (NativeCutoverCicArenaGenerationId parentGenerationValue) = authority.generation
        let (NativeCutoverCicEnvironmentRevision environmentBeforeValue) = authority.environmentRevision
        let weightedCost = nativeCutoverCicWeightedCost counters
        let weightedCostDelta = max 0L (weightedCost - nativeCutoverCicWeightedCost authority.lastCounters)
        let declarationDelta = counters.kernelDeclarationCount - authority.lastCounters.kernelDeclarationCount
        let checkDelta = counters.kernelCheckCount - authority.lastCounters.kernelCheckCount
        let counterRegression =
            counters.kernelTermCount < authority.lastCounters.kernelTermCount
            || counters.kernelLevelCount < authority.lastCounters.kernelLevelCount
            || declarationDelta < 0L
            || checkDelta < 0L
            || counters.arenaBytes < authority.lastCounters.arenaBytes
        let disposition =
            if counters.metavarsInKernel > 0L then
                NativeCutoverCicKernelCommitRejectedMetavariableLeak counters.metavarsInKernel
            elif counterRegression then
                NativeCutoverCicKernelCommitRejectedCounterRegression
            elif nativeCutoverCicCounterDigest counters = nativeCutoverCicCounterDigest authority.lastCounters then
                NativeCutoverCicKernelCommitDuplicate
            else
                NativeCutoverCicKernelCommitAccepted
        let advances = disposition = NativeCutoverCicKernelCommitAccepted
        let childGenerationValue = if advances then parentGenerationValue + 1UL else parentGenerationValue
        let environmentAfterValue =
            if advances && declarationDelta > 0L then environmentBeforeValue + uint64 declarationDelta
            else environmentBeforeValue
        let counterDigest = nativeCutoverCicCounterDigest counters
        let exactOnceRef =
            NativeCutoverStableRef.ref32
                "native-cic-kernel-commit"
                [ string parentGenerationValue
                  string childGenerationValue
                  string environmentBeforeValue
                  string environmentAfterValue
                  string counterDigest
                  nativeCutoverCicKernelCommitDispositionText disposition ]
        let receipt =
            { receiptRef = NativeCutoverStableRef.ref32 "native-cic-kernel-commit-receipt" [string exactOnceRef; string reducerSequence]
              parentGeneration = authority.generation
              childGeneration = NativeCutoverCicArenaGenerationId childGenerationValue
              environmentBefore = authority.environmentRevision
              environmentAfter = NativeCutoverCicEnvironmentRevision environmentAfterValue
              disposition = disposition
              counterDigest = counterDigest
              weightedCostDelta = if advances then weightedCostDelta else 0L
              declarationDelta = if advances then max 0L declarationDelta else 0L
              checkDelta = if advances then max 0L checkDelta else 0L
              exactOnceRef = exactOnceRef
              reducerSequence = reducerSequence }
        if advances && not (authority.exactOnceRefs.Contains exactOnceRef) then
            { generation = receipt.childGeneration
              environmentRevision = receipt.environmentAfter
              lastCounters = counters
              retiredWeightedCost = authority.retiredWeightedCost + receipt.weightedCostDelta
              committedDeclarationCount = authority.committedDeclarationCount + receipt.declarationDelta
              committedCheckCount = authority.committedCheckCount + receipt.checkDelta
              exactOnceRefs = authority.exactOnceRefs.Add exactOnceRef
              lastCommit = Some receipt }, receipt
        else
            { authority with lastCommit = Some receipt }, receipt

    type NativeCutoverKernelWork<'Context,'Sort> =
        | NativeCutoverWhnf of NativeCutoverKernelTermRef<'Context,'Sort>
        | NativeCutoverDefEq of NativeCutoverDefEqKey<'Context>
        | NativeCutoverUniverseSolve of NativeCutoverKernelLevelRef * NativeCutoverKernelLevelRef
        | NativeCutoverDeclarationCommit of declarationHash:uint64 * dependencyHash:uint64

