        | NativeCutoverFunctionNode of functionId:uint32 * ports:NativeCutoverPortId array
        | NativeCutoverDupNode of NativeCutoverDupLabel * source:NativeCutoverPortId * left:NativeCutoverPortId * right:NativeCutoverPortId
        | NativeCutoverEraseNode of NativeCutoverPortId
        | NativeCutoverNumericNode of uint64

    type NativeCutoverLoweringTargetId =
        | NativeCutoverRustNativeTarget
        | NativeCutoverGleamBeamTarget
        | NativeCutoverHvmInteractionNetTarget
        | NativeCutoverKindProofExportTarget

    let private nativeCutoverLoweringTargetText = function
        | NativeCutoverRustNativeTarget -> "rust-native"
        | NativeCutoverGleamBeamTarget -> "gleam-beam"
        | NativeCutoverHvmInteractionNetTarget -> "hvm-interaction-net"
        | NativeCutoverKindProofExportTarget -> "kind-proof-export"

    [<StructuralEquality; NoComparison>]
    type NativeCutoverRuntimeLawId =
        | NativeRuntimeExactOnceFill
        | NativeRuntimeAtMostOnceConsumption
        | NativeRuntimeFairAlt
        | NativeRuntimeCancellationPropagation
        | NativeRuntimeNoLostWakeup
        | NativeRuntimeGenerationSafeTimeout
        | NativeRuntimeDeterministicReducerOutcome

    [<StructuralEquality; NoComparison>]
