        | NativeRuntimeChannel
        | NativeRuntimePromise
        | NativeRuntimeAlt
        | NativeRuntimeTask
        | NativeRuntimeClock
        | NativeRuntimeCancel
        | NativeRuntimeAtomic
        | NativeRuntimeScheduler

    type NativeCutoverRuntimeVerificationDisposition =
        | NativeCutoverRuntimeVerificationNotRequired
        | NativeCutoverRuntimeVerificationPending
        | NativeCutoverRuntimeVerificationRejected
        | NativeCutoverRuntimeVerificationVerified

    let private nativeCutoverRuntimeVerificationDispositionText = function
        | NativeCutoverRuntimeVerificationNotRequired -> "not-required"
        | NativeCutoverRuntimeVerificationPending -> "pending"
        | NativeCutoverRuntimeVerificationRejected -> "rejected"
        | NativeCutoverRuntimeVerificationVerified -> "verified"

    type NativeCutoverBackendRuntimeWitness = private {
        witnessRef : uint32
        target : NativeCutoverLoweringTargetId
        declaredLaws : NativeCutoverRuntimeLawId list
        declaredPrimitives : NativeCutoverRuntimePrimitiveId list
        runtimeVerification : NativeCutoverRuntimeVerificationDisposition
        runtimeVerificationReceiptRef : uint32 option
        semanticCoreShared : bool
        backendSwitchRestrictedToRuntimePorts : bool
        proofReceiptRef : uint32
        reducerSequence : int64
    }

    type NativeCutoverLoweringPipeline = private {
        semanticIrRef : uint32
        closureConversionRef : uint32
        defunctionalizationRef : uint32
        proofErasureRef : uint32
        linearityRef : uint32
        interactionGraphRef : uint32
        backendTargetRef : uint32
        target : NativeCutoverLoweringTargetId
        proofCheckReceiptRef : uint32
        loweringReceiptRef : uint32
        semanticNodeCount : int64
        interactionNodeCount : int64
        explicitDupCount : int64
        explicitEraseCount : int64
        reducerSequence : int64
    }

    let private nativeCutoverBackendRuntimeWitnessFor
        reducerSequence
        runtimeVerification
        runtimeVerificationReceiptRef
        (lowering:NativeCutoverLoweringPipeline)
        : NativeCutoverBackendRuntimeWitness =
        let allLaws =
            [ NativeRuntimeExactOnceFill
              NativeRuntimeAtMostOnceConsumption
              NativeRuntimeFairAlt
              NativeRuntimeCancellationPropagation
              NativeRuntimeNoLostWakeup
              NativeRuntimeGenerationSafeTimeout
              NativeRuntimeDeterministicReducerOutcome ]
        let runtimePrimitives =
            [ NativeRuntimeChannel
              NativeRuntimePromise
              NativeRuntimeAlt
              NativeRuntimeTask
              NativeRuntimeClock
              NativeRuntimeCancel
              NativeRuntimeAtomic
              NativeRuntimeScheduler ]
        let laws, primitives =
            match lowering.target with
            | NativeCutoverRustNativeTarget
            | NativeCutoverGleamBeamTarget -> allLaws, runtimePrimitives
            | NativeCutoverHvmInteractionNetTarget
            | NativeCutoverKindProofExportTarget ->
                [ NativeRuntimeDeterministicReducerOutcome ], []
        let witnessRef =
            NativeCutoverStableRef.ref32
                "native-backend-runtime-witness"
                [ nativeCutoverLoweringTargetText lowering.target
                  string lowering.semanticIrRef
                  string lowering.proofCheckReceiptRef
                  string lowering.loweringReceiptRef
                  string lowering.linearityRef
                  nativeCutoverRuntimeVerificationDispositionText runtimeVerification
                  string (runtimeVerificationReceiptRef |> Option.defaultValue 0u)
                  string lowering.reducerSequence ]
        { witnessRef = witnessRef
          target = lowering.target
          declaredLaws = laws
          declaredPrimitives = primitives
          runtimeVerification = runtimeVerification
          runtimeVerificationReceiptRef = runtimeVerificationReceiptRef
          semanticCoreShared = true
          backendSwitchRestrictedToRuntimePorts = true
          proofReceiptRef = lowering.proofCheckReceiptRef
          reducerSequence = reducerSequence }

    let private nativeCutoverMintSemanticFact workUnitId factKind semanticDigest materialEpoch producerRef exactOnceRef payloadRef baselineCost actualCost criticalPathCost dependencyFanout producerGeneration =
        { factId = NativeCutoverSemanticFactId(semanticDigest ^^^ uint64 exactOnceRef ^^^ producerGeneration)
          workUnitId = workUnitId
          factKind = factKind
          semanticDigest = semanticDigest
          materialEpoch = materialEpoch
          producerRef = producerRef
          exactOnceRef = exactOnceRef
          payloadRef = payloadRef
          cost =
            { baselineCost = max 1L baselineCost
              actualCost = max 1L actualCost
              criticalPathCost = max 0L criticalPathCost
              dependencyFanout = max 0 dependencyFanout
              producerGeneration = producerGeneration } }

    let private nativeCutoverRejectNoFact workUnitId rejectionRef requiredFactKind =
        NativeCutoverReturnedNoFactRejected(workUnitId,rejectionRef,requiredFactKind)

    let private nativeCutoverShimOnly shimRef adapterRef =
        { shimRef = shimRef
          acceptedLegacyEvents = 0L
          emittedNativeEvents = 0L
          authority = NativeCutoverAdapterOnly
          eventAdapterRef = adapterRef }

    let private nativeCutoverLegacyAuthorityExclusionProof shimRef =
        { proofRef = NativeCutoverStableRef.ref32 "legacy-eval-authority-excluded" [string shimRef]
          rootSelectionExcluded = true
          qapMutationExcluded = true
          outcomeMutationExcluded = true
          actorMutationExcluded = true
          terminalCommitExcluded = true
          runEndExcluded = true
          physicalExitExcluded = true
          schedulerSpawnExcluded = true
          progressCreditExcluded = true }

    let private nativeCutoverReducerEvalAuthorityInitial<'Kind> () : NativeCutoverReducerEvalAuthority<'Kind> =
        { shim = nativeCutoverShimOnly 0u 0u
          exclusionProof = nativeCutoverLegacyAuthorityExclusionProof 0u
          semanticFactCount = 0L
          semanticRetiredCost = 0L
          criticalPathRetiredCost = 0L
          duplicateSemanticFactCount = 0L
          retiredFactExactOnceRefs = Set.empty
          rejectedNoFactCount = 0L
          typedPoisonCount = 0L
          lastSemanticFactRef = None
          lastRejectionRef = None
          lastSpawnGrantRef = None
          reducerSequence = 0L }

    let private nativeCutoverReducerEvalAuthorityDemote
        reducerSequence
        (shim:NativeCutoverLegacyEvalWorklistShim<'Kind>)
        (authority:NativeCutoverReducerEvalAuthority<'Kind>) =
        { authority with
            shim =
                { shim with
                    acceptedLegacyEvents = max authority.shim.acceptedLegacyEvents shim.acceptedLegacyEvents
                    emittedNativeEvents = max authority.shim.emittedNativeEvents shim.emittedNativeEvents
                    authority = NativeCutoverAdapterOnly }
            exclusionProof = nativeCutoverLegacyAuthorityExclusionProof shim.shimRef
            reducerSequence = reducerSequence }

    let private nativeCutoverReducerEvalAuthorityRecordFact
        reducerSequence
        (fact:NativeCutoverSemanticFact<'Kind,NativeCutoverSemanticFactStage>)
        (authority:NativeCutoverReducerEvalAuthority<'Kind>) =
        if authority.retiredFactExactOnceRefs.Contains fact.exactOnceRef then
            { authority with
                duplicateSemanticFactCount = authority.duplicateSemanticFactCount + 1L
                reducerSequence = reducerSequence }
        else
            { authority with
                semanticFactCount = authority.semanticFactCount + 1L
                semanticRetiredCost = authority.semanticRetiredCost + max 1L fact.cost.actualCost
                criticalPathRetiredCost = authority.criticalPathRetiredCost + max 0L fact.cost.criticalPathCost
                retiredFactExactOnceRefs = authority.retiredFactExactOnceRefs.Add fact.exactOnceRef
                lastSemanticFactRef = Some fact.payloadRef
                reducerSequence = reducerSequence }

    let private nativeCutoverReducerEvalAuthorityReject
        reducerSequence
        (result:NativeCutoverNativeEvalReturn<'Kind>)
        (authority:NativeCutoverReducerEvalAuthority<'Kind>) =
        match result with
        | NativeCutoverReturnedSemanticFact fact ->
            nativeCutoverReducerEvalAuthorityRecordFact reducerSequence fact authority
        | NativeCutoverReturnedTypedPoison(_, poisonRef, _) ->
            { authority with
                typedPoisonCount = authority.typedPoisonCount + 1L
                lastRejectionRef = Some poisonRef
                reducerSequence = reducerSequence }
        | NativeCutoverReturnedNoFactRejected(_, rejectionRef, _) ->
            { authority with
                rejectedNoFactCount = authority.rejectedNoFactCount + 1L
                lastRejectionRef = Some rejectionRef
                reducerSequence = reducerSequence }

    let private nativeCutoverReducerEvalAuthorityGrant
        reducerSequence
        (grant:NativeCutoverSchedulerSpawnGrant<'Kind>)
        (authority:NativeCutoverReducerEvalAuthority<'Kind>) =
        { authority with
            lastSpawnGrantRef = Some grant.grantRef
            reducerSequence = reducerSequence }

