        let private graphProgressEwmaLedger =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, GraphProgressEwmaState>()

        let private graphProgressObserveRate (key:string) (nowMs:int64) (model:ProgressEstimatorModelId) (poisonTail:string) (phase:GraphProgressPhaseId) (deltaCost:int64) (windowS:float) =
            let sampleRate =
                if deltaCost <= 0L || windowS <= 0.0 then 0.0
                else (float deltaCost) / windowS
            let seed () = { lastTsMs = nowMs; ewmaRate = sampleRate; variance = 0.0; lastModel = model; lastPoisonTail = poisonTail }
            let keyRef = CompilerIdentityKernel.ContentDigest.ofText "graph-progress-ewma" key
            let state = graphProgressEwmaLedger.GetOrAdd(keyRef, fun _ -> seed())
            let phaseReset = state.lastModel <> model || state.lastPoisonTail <> poisonTail
            let oldRate = max 0.0 state.ewmaRate
            let alpha = if phaseReset then 0.55 else 0.30
            let nextRate =
                match phase with
                | GraphProgressTopologyPause -> oldRate
                | GraphProgressRescueInProgress when sampleRate <= 0.0 -> oldRate
                | GraphProgressTerminalExhausted -> max oldRate sampleRate
                | _ -> (alpha * sampleRate) + ((1.0 - alpha) * oldRate)
            let diff = sampleRate - nextRate
            let nextVariance =
                match phase with
                | GraphProgressTopologyPause -> state.variance * 0.90
                | GraphProgressRescueInProgress when sampleRate <= 0.0 -> state.variance + max 1.0 (oldRate * 0.25)
                | _ -> (alpha * diff * diff) + ((1.0 - alpha) * max 0.0 state.variance)
            state.lastTsMs <- nowMs
            state.ewmaRate <- nextRate
            state.variance <- nextVariance
            state.lastModel <- model
            state.lastPoisonTail <- poisonTail
            nextRate, nextVariance, System.Math.Sqrt(max 0.0 nextVariance), phaseReset

        // MIGRATION: multi-horizon ETA authority.  The single EWMA remains as a
        // backwards-compatible field, but terminal/success ETA now prefers a
        // fused short/medium/session rate.  Topology pauses freeze decay, rescue
        // with zero work keeps the last physical rate and lowers confidence, and
        // model/poison-tail transitions reset the responsive horizon instead of
        // blindly carrying stale slope.
        type GraphProgressHorizonState = {
            mutable lastTsMs : int64
            mutable shortRate : float
            mutable mediumRate : float
            mutable sessionRate : float
            mutable variance : float
            mutable lastPhase : GraphProgressPhaseId
            mutable lastPoisonTail : string
            mutable samples : int64
        }

        type GraphProgressHorizonSnapshot = {
            shortRate : float
            mediumRate : float
            sessionRate : float
            fusedRate : float
            variance : float
            sigma : float
            confidenceProbability : float
            samples : int64
            phaseTransitionReset : bool
            topologyClockPaused : bool
            rescueUnknownButLive : bool
        }

        let private graphProgressHorizonSnapshotText (x:GraphProgressHorizonSnapshot) =
            FastRuntimeFormat.format "GraphProgressHorizon(short=%.4f|medium=%.4f|session=%.4f|fused=%.4f|variance=%.4f|sigma=%.4f|confidence=%.4f|samples=%d|phase_reset=%b|topology_pause=%b|rescue_unknown_live=%b)" [| box x.shortRate; box x.mediumRate; box x.sessionRate; box x.fusedRate; box x.variance; box x.sigma; box x.confidenceProbability; box x.samples; box x.phaseTransitionReset; box x.topologyClockPaused; box x.rescueUnknownButLive |]

        // MIGRATION: close out the assessment contract by making the JSON/HUD expose
        // a conservative exact-once work ledger contract instead of another score field.
        type WorkLedgerExactOnceDisposition =
            | WorkLedgerExactOncePending
            | WorkLedgerExactOnceRunning
            | WorkLedgerExactOnceBlocked
            | WorkLedgerExactOnceCompleted
            | WorkLedgerExactOnceTerminalNoResult
            | WorkLedgerExactOnceCancelled

        type WorkLedgerDenominatorSource =
            | DenominatorAstPreHopac
            | DenominatorSchedulerDiscovered
            | DenominatorProbabilisticReserve
            | DenominatorClosedExact

        type CriticalPathEtaAuthority =
            | CriticalPathEtaUnavailable
            | CriticalPathEtaGraphRateP50P90
            | CriticalPathEtaTerminalOnly
            | CriticalPathEtaSuccessUnavailableTerminalFailure

        let private workLedgerExactOnceDispositionText = function
            | WorkLedgerExactOncePending -> "pending"
            | WorkLedgerExactOnceRunning -> "running"
            | WorkLedgerExactOnceBlocked -> "blocked"
            | WorkLedgerExactOnceCompleted -> "completed_exact_once"
            | WorkLedgerExactOnceTerminalNoResult -> "terminal_no_result"
            | WorkLedgerExactOnceCancelled -> "cancelled"

        let private workLedgerDenominatorSourceText = function
            | DenominatorAstPreHopac -> "ast_pre_hopac_denominator"
            | DenominatorSchedulerDiscovered -> "scheduler_discovered_work_cost"
            | DenominatorProbabilisticReserve -> "probabilistic_undiscovered_reserve"
            | DenominatorClosedExact -> "discovery_closed_exact_denominator"

        let private criticalPathEtaAuthorityText = function
            | CriticalPathEtaUnavailable -> "critical_path_eta_unavailable"
            | CriticalPathEtaGraphRateP50P90 -> "critical_path_eta_graph_rate_p50_p90"
            | CriticalPathEtaTerminalOnly -> "eta_terminal_only_success_unavailable"
            | CriticalPathEtaSuccessUnavailableTerminalFailure -> "eta_success_unavailable_terminal_failure"

        let private graphProgressHorizonLedger =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, GraphProgressHorizonState>()

        let private graphProgressObserveHorizonRate (key:string) (nowMs:int64) (poisonTail:string) (phase:GraphProgressPhaseId) (deltaCost:int64) (windowS:float) =
            let sampleRate =
                if deltaCost <= 0L || windowS <= 0.0 then 0.0
                else (float deltaCost) / windowS
            let seed () = { lastTsMs = nowMs; shortRate = sampleRate; mediumRate = sampleRate; sessionRate = sampleRate; variance = 0.0; lastPhase = phase; lastPoisonTail = poisonTail; samples = 0L }
            let keyRef = CompilerIdentityKernel.ContentDigest.ofText "graph-progress-horizon" key
            let state = graphProgressHorizonLedger.GetOrAdd(keyRef, fun _ -> seed())
            let phaseReset = state.lastPhase <> phase || state.lastPoisonTail <> poisonTail
            let topologyPaused = phase = GraphProgressTopologyPause
            let rescueUnknownButLive = phase = GraphProgressRescueInProgress && sampleRate <= 0.0
            let observe alpha oldRate =
                if topologyPaused || rescueUnknownButLive then oldRate
                elif phaseReset then (0.70 * sampleRate) + (0.30 * oldRate)
                else (alpha * sampleRate) + ((1.0 - alpha) * oldRate)
            let nextShort = observe 0.55 (max 0.0 state.shortRate)
            let nextMedium = observe 0.18 (max 0.0 state.mediumRate)
            let nextSession = observe 0.045 (max 0.0 state.sessionRate)
            let priorSigma = System.Math.Sqrt(max 0.0 state.variance)
            let volatility = min 1.0 (priorSigma / max 1.0 (nextShort + nextMedium + nextSession))
            let shortWeight = 0.55 - (0.35 * volatility)
            let mediumWeight = 0.30 + (0.15 * volatility)
            let sessionWeight = max 0.10 (1.0 - shortWeight - mediumWeight)
            let weightTotal = shortWeight + mediumWeight + sessionWeight
            let fused =
                if nextShort <= 0.0 && nextMedium <= 0.0 then nextSession
                elif rescueUnknownButLive then max nextMedium nextSession
                else ((shortWeight * nextShort) + (mediumWeight * nextMedium) + (sessionWeight * nextSession)) / max 0.000001 weightTotal
            let diff = sampleRate - fused
            let nextVariance =
                if topologyPaused then state.variance * 0.92
                elif rescueUnknownButLive then state.variance + max 1.0 (fused * 0.35)
                else (0.25 * diff * diff) + (0.75 * max 0.0 state.variance)
            let sigma = System.Math.Sqrt(max 0.0 nextVariance)
            let evidence = min 1.0 (float (state.samples + 1L) / 12.0)
            let stability = 1.0 / (1.0 + (sigma / max 1.0 fused))
            let confidence =
                if fused <= 0.0 || rescueUnknownButLive then max 0.05 (0.35 * evidence * stability)
                elif topologyPaused then max 0.15 (0.50 * evidence * stability)
                else min 0.98 (max 0.05 (0.70 * evidence + 0.30 * stability))
            state.lastTsMs <- nowMs
            state.shortRate <- nextShort
            state.mediumRate <- nextMedium
            state.sessionRate <- nextSession
            state.variance <- nextVariance
            state.lastPhase <- phase
            state.lastPoisonTail <- poisonTail
            state.samples <- state.samples + 1L
            { shortRate = nextShort; mediumRate = nextMedium; sessionRate = nextSession; fusedRate = fused; variance = nextVariance; sigma = sigma; confidenceProbability = confidence; samples = state.samples; phaseTransitionReset = phaseReset; topologyClockPaused = topologyPaused; rescueUnknownButLive = rescueUnknownButLive }

        let private findCharFrom (text:string) startIndex expected =
            let mutable found = -1
            let mutable i = max 0 startIndex
            while found < 0 && i < text.Length do
                if text.[i] = expected then found <- i
                else i <- i + 1
            found

        let private findTextFrom
            (comparison:StringComparison)
            (text:string)
            startIndex
            (needle:string) =
            if String.IsNullOrEmpty needle then max 0 startIndex
            else
                let mutable found = -1
                let mutable i = max 0 startIndex
                let last = text.Length - needle.Length
                while found < 0 && i <= last do
                    if String.Compare(text, i, needle, 0, needle.Length, comparison) = 0 then
                        found <- i
                    else
                        i <- i + 1
                found

        type HudSourceExtensionId =
            | HudSourceSpiral
            | HudSourceFSharp
            | HudSourceFSharpScript
            | HudSourceFSharpYacc
            | HudSourceFSharpSignature

        let private hudSourceExtensionText = function
            | HudSourceSpiral -> ".spi"
            | HudSourceFSharp -> ".fs"
            | HudSourceFSharpScript -> ".fsx"
            | HudSourceFSharpYacc -> ".fsy"
            | HudSourceFSharpSignature -> ".fsi"

        let private hudSourceExtensions =
            [| HudSourceSpiral
               HudSourceFSharp
               HudSourceFSharpScript
               HudSourceFSharpYacc
               HudSourceFSharpSignature |]

        let private hudFileFromSite (site: string) =
            try
                let s = cleanText site
                if String.IsNullOrWhiteSpace s then "-"
                else
                    let at = findCharFrom s 0 '@'
                    let start = if at >= 0 then at + 1 else 0
                    let mutable endi = s.Length
                    let mutable found = false
                    for extensionId in hudSourceExtensions do
                        if not found then
                            let extensionText = hudSourceExtensionText extensionId
                            let j = findTextFrom StringComparison.OrdinalIgnoreCase s start extensionText
                            if j >= 0 then
                                endi <- j + extensionText.Length
                                found <- true
                    let raw =
                        if found && endi > start then s.Substring(start, endi - start)
                        else
                            let stopTokens = [| "|"; " "; ","; "\"" |]
                            for token in stopTokens do
                                let j = findTextFrom StringComparison.Ordinal s start token
                                if j >= 0 && j < endi then endi <- j
                            if endi > start then s.Substring(start, endi - start) else s
                    let norm = raw.Replace('\\','/')
                    let parts = norm.Split([|'/'|], StringSplitOptions.RemoveEmptyEntries)
                    if parts.Length >= 2 then parts.[parts.Length - 2] + "/" + parts.[parts.Length - 1]
                    elif parts.Length = 1 then parts.[0]
                    else norm
            with _ -> "-"


        type HudFileGridDispositionId =
            | HudFileGridAcceptedSpiralSource
            | HudFileGridRejectedEmpty
            | HudFileGridRejectedPlaceholder
            | HudFileGridRejectedNonSpiralSource

        let private hudFileGridDispositionFor (file:string) =
            let f = cleanText file
            if String.IsNullOrWhiteSpace f || f = "-" then
                HudFileGridRejectedEmpty
            else
                let head =
                    f.Split([|':'|], 2, StringSplitOptions.None)
                    |> Array.tryHead
                    |> Option.defaultValue f
                match head.ToLowerInvariant() with
                | "child"
                | "cache_handoff@child" -> HudFileGridRejectedPlaceholder
                | _ when f.EndsWith(".spi", StringComparison.OrdinalIgnoreCase) ->
                    HudFileGridAcceptedSpiralSource
                | _ -> HudFileGridRejectedNonSpiralSource

        let private hudFileGridAccepts (file:string) =
            hudFileGridDispositionFor file = HudFileGridAcceptedSpiralSource

        let private rememberHudFileSiteUnlocked (kind: string) (site: string) =
            let file = hudFileFromSite site
            if hudFileGridAccepts file then
                let fileId = CompilerIdentityKernel.WorkSiteIdOps.create file
                let mutable n = 0L
                if hudFileHeat.TryGetValue(fileId, &n) then hudFileHeat.[fileId] <- n + 1L
                else hudFileHeat.[fileId] <- 1L
                hudFileKinds.[fileId] <- (if String.IsNullOrWhiteSpace kind then "unknown" else cleanText kind)
                hudFileHeatTotal <- hudFileHeatTotal + 1L

        let private hudBar width value maxValue =
            let maxValue = max 1L maxValue
            let filled = int (min (int64 width) ((value * int64 width) / maxValue))
            let filled = max 0 (min width filled)
            String('#', filled) + String('.', max 0 (width - filled))

        let private hudFileCell (file: string) (count: int64) (kind: string) (maxValue: int64) =
            let bar = hudBar 10 count maxValue
            let shortKind = hudKindShort kind
            FastRuntimeFormat.format "%s %s %s %s" [| box (colR 4 (string count)); box (colL 10 bar); box (colL 8 shortKind); box (trimTo 30 file) |]

        let private hudFileGridActiveKind (kind: string) =
            match hudKindId kind with
            | HudKindTerminal
            | HudKindCycle
            | HudKindParentReplay
            | HudKindReplayDriver
            | HudKindReplay
            | HudKindWork
            | HudKindSemantic
            | HudKindSourceValue -> true
            | HudKindEmpty
            | HudKindProgressTick
            | HudKindSpiralHud
            | HudKindOther _ -> false

        let private hudTopFiles limit =
            try
                hudFileHeat
                |> Seq.choose (fun kv ->
                    let mutable kind = ""
                    let mutable previous = 0L
                    let k = if hudFileKinds.TryGetValue(kv.Key, &kind) then kind else "-"
                    let oldValue = if hudFileHeatLast.TryGetValue(kv.Key, &previous) then previous else 0L
                    let delta = kv.Value - oldValue
                    hudFileHeatLast.[kv.Key] <- kv.Value
                    if delta > 0L && hudFileGridActiveKind k then
                        Some (CompilerIdentityKernel.WorkSiteIdOps.text kv.Key, delta, k)
                    else None)
                |> Seq.sortByDescending (fun (_, v, _) -> v)
                |> Seq.truncate limit
                |> Seq.toArray
            with _ -> [||]

        type private HudAuthorityModelSignalId =
            | HudAuthorityModelSparseRoot
            | HudAuthorityModelDriverOrRoot
            | HudAuthorityModelReplay

        let private hudAuthorityModelSignals model =
            let atoms = hudStructuredAtoms model
            [ if hudAtomsContainPair "sparse" "root" atoms then HudAuthorityModelSparseRoot
              if List.contains "driver" atoms && List.contains "root" atoms then HudAuthorityModelDriverOrRoot
              if List.contains "replay" atoms then HudAuthorityModelReplay ]
            |> Set.ofList

        let private hudAuthorityDisplayFor (model: string) (roots: string) (terms: string) (sem: string) =
            let modelSignals = hudAuthorityModelSignals model
            let r = parseInt64Safe roots
            let t = parseInt64Safe terms
            let s = parseInt64Safe sem
            if t > 0L || s > 0L then HudAuthorityTerminalOrSemantic
            elif r > 0L && Set.contains HudAuthorityModelSparseRoot modelSignals then HudAuthoritySparseRootNoSemantic
            elif r > 0L || Set.contains HudAuthorityModelDriverOrRoot modelSignals then HudAuthorityRootOrDriver
            elif Set.contains HudAuthorityModelReplay modelSignals then HudAuthorityReplayNoRoot
            else HudAuthorityCold

        let private hudReplayRootFinalizationStateFor replayCompleteText writeWitnessText rootsText queueDepthText activeDepthText codegenBytesText =
            let truthy (s: string) =
                let x = if isNull s then "" else s.Trim()
                x.Equals("true", StringComparison.OrdinalIgnoreCase) || x = "1"
            let roots = parseInt64Safe rootsText
            let queueDepth = parseInt64Safe queueDepthText
            let activeDepth = parseInt64Safe activeDepthText
            let codegenBytes = parseInt64Safe codegenBytesText
            let replayDone = truthy replayCompleteText
            let writeWitness = truthy writeWitnessText
            if codegenBytes > 0L then ReplayRootFinalizationHandoffReady
            elif replayDone && writeWitness && (queueDepth > 0L || activeDepth > 0L) then ReplayRootFinalizationDraining
            elif replayDone && writeWitness then ReplayRootFinalizationHandoffReady
            elif roots > 0L && (queueDepth > 0L || activeDepth > 0L) then ReplayRootFinalizationDraining
            elif roots > 0L || replayDone || writeWitness then ReplayRootFinalizationRequested
            elif queueDepth = 0L && activeDepth = 0L then ReplayRootFinalizationCold
            else ReplayRootFinalizationExhausted

        let private installSplitUnlocked () =
            if supportsHud() then
                let width = safeWidth()
                let height = safeHeight()
                let logBottom = logBottomRow0()
                if (not splitInstalled) || width <> lastWindowWidth || height <> lastWindowHeight || logBottom <> lastLogBottomRow then
                    // ANSI scroll-region split:
                    // rows 1..logBottom+1 are the normal append-only log stream;
                    // the last hudRows rows are outside the scroll region and are redrawn as a HUD.
                    ansi (sprintf "%s1;%dr" esc (logBottom + 1))
                    ansi (sprintf "%s%d;1H" esc (logBottom + 1))
                    splitInstalled <- true
                    lastWindowWidth <- width
                    lastWindowHeight <- height
                    lastLogBottomRow <- logBottom

        let private clearHudRowsUnlocked () =
            if supportsHud() then
                installSplitUnlocked()
                let width = safeWidth()
                let start = hudStartRow0()
                for i = 0 to hudRows - 1 do
                    let row1 = start + i + 1
                    ansi (FastRuntimeFormat.format "%s%d;1H%s2K%s" [| box esc; box row1; box esc; box (String(' ', width)) |])
                    ansi (sprintf "%s%d;1H" esc row1)

        let private resetSplitUnlocked () =
            if splitInstalled then
                try
                    clearHudRowsUnlocked()
                    ansi (sprintf "%sr" esc)
                    ansi (sprintf "%s0m" esc)
                    ansi (sprintf "%s%d;1H" esc (safeHeight()))
                    splitInstalled <- false
                with _ -> ()

        let private renderHudUnlocked () =
            if supportsHud() && hudLines.Length > 0 then
                installSplitUnlocked()
                let width = safeWidth()
                let start = hudStartRow0()
                // Save/restore keeps the active log cursor inside the scroll region,
                // so log lines keep appending above the HUD instead of fighting it.
                ansi (sprintf "%ss" esc)
                for i = 0 to hudRows - 1 do
                    let row1 = start + i + 1
                    let text = if i < hudLines.Length then hudLines.[i] else ""
                    ansi (FastRuntimeFormat.format "%s%d;1H%s2K" [| box esc; box row1; box esc |])
                    Console.Error.Write(fitLine width text)
                ansi (sprintf "%su" esc)

        let private flushFinalRowDurablyUnlocked () =
            // `fileLogState` owns one shared FileStream. Flush is an operation on
            // that same mutable instance, so it must share the physical writer gate
            // with Seek/Write; a separate HUD lock is not sufficient serialization.
            lock fileLogWriteGate (fun () ->
                match fileLogState with
                | Some (CompilerFileLogOpen fs) ->
                    try
                        fs.Flush(true)
                        fileLogPendingLineCount <- 0
                        fileLogLastFlushMs <- DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                        true
                    with _ -> false
                | _ -> false)

        // The reducer snapshot remains authoritative for compiler state, while the physical-boundary
        // observation is an observer-only overlay carrying receipts that may be committed after the
        // last reducer HUD publication but before Environment.Exit.
        let mutable private terminalPresentationPhysicalBoundaryObservation : (string * string * int) option = None

        // Final console, footer and shutdown diagnostics prefer one immutable ReducerHudSnapshot.
        // If shutdown races before the reducer publishes one, persist the last rendered HUD rows
        // as an observer-only fallback so the JSONL always ends with a reconstructable board.
        let private emitFinalHudSnapshotUnlocked () =
            if not (finalHudCommitted()) then
                let finalRowCapability = tryAcquireTerminalFinalRowCapability ()
                let finalRowCapabilityAuthorized = finalRowCapability |> Option.isSome
                let physicalBoundaryFinalRowAuthorized = terminalPresentationPhysicalBoundaryObservation |> Option.isSome
                let finalRowAuthorized = finalRowCapabilityAuthorized || physicalBoundaryFinalRowAuthorized
                let finalRowCapabilityRef =
                    finalRowCapability
                    |> Option.map terminalFinalRowCapabilityRefText
                    |> Option.defaultValue ""
                let commitFinalRowIfAuthorized () =
                    if not (flushFinalRowDurablyUnlocked ()) then
                        invalidOp "terminal final-row HUD could not be forced to durable storage"
                    else
                        match finalRowCapability with
                        | Some capability ->
                            if commitTerminalFinalRowCapability capability then
                                finalHudPersistenceState <- FinalHudCommitted
                            else
                                invalidOp "terminal final-row capability could not be committed after durable HUD emission"
                        | None when physicalBoundaryFinalRowAuthorized ->
                            // The process has already crossed the typed physical-boundary authority.
                            // This only closes presentation persistence; it cannot authorize compiler exit.
                            finalHudPersistenceState <- FinalHudCommitted
                        | None -> ()
                appendFileLogLineSerialized (
                    FastRuntimeFormat.format "{\"v\":2,\"kind\":\"terminal_final_row_capability_observed\",\"authorized\":%b,\"capability_authorized\":%b,\"physical_boundary_authorized\":%b,\"closure_proof_ref\":%s,\"authority\":\"indexed_terminal_closure_capability_or_committed_physical_boundary_observation\"}" [| box finalRowAuthorized; box finalRowCapabilityAuthorized; box physicalBoundaryFinalRowAuthorized; box (fileLogEscJson finalRowCapabilityRef) |])
                let nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                let monotonicNowMs = Environment.TickCount64
                let pid = try Diagnostics.Process.GetCurrentProcess().Id with _ -> -1
                let tid = try Threading.Thread.CurrentThread.ManagedThreadId with _ -> -1
                match readReducerHudSnapshot () with
                | None when hudLines.Length > 0 ->
                    let rows =
                        Array.init hudRows (fun i ->
                            if i < hudLines.Length then hudLines.[i] |> cleanText |> fitLine (safeWidth())
                            else
                                hudFlex4
                                    (hudKv "hud_contract" "50_rows_no_prune")
                                    (hudKv "row" (sprintf "%d/%d" (i + 1) hudRows))
                                    (hudKv "authority" "last_rendered_fallback")
                                    (hudKv "shutdown" "interrupted"))
                    rows
                    |> Array.iteri (fun i clean ->
                        (if System.Environment.GetEnvironmentVariable "SPIRAL_DIAG_QUIET" <> "1" then Console.Error.WriteLine("[spiral_hud_final] " + clean))
                        appendFileLogLineSerialized (
                            FastRuntimeFormat.format "{\"v\":2,\"ts_ms\":%d,\"pid\":%d,\"tid\":%d,\"kind\":\"spiral_hud_final\",\"line_index\":%d,\"row_count\":%d,\"final_row\":false,\"snapshot_available\":false,\"text\":%s,\"authority\":\"last_rendered_hud_fallback\",\"hud_contract_du\":\"DetailedFlex50NoPrune\",\"row_compaction_du\":\"complete_50_row_final_hud_snapshot\"}" [| box nowMs; box pid; box tid; box i; box rows.Length; box (fileLogEscJson clean) |]))
                    appendFileLogLineSerialized (
                        sprintf "{\"v\":2,\"kind\":\"terminal_final_row_blocked\",\"closure_proof_ref\":%s,\"reason_du\":\"ReducerSnapshotUnavailable\",\"final_row_emitted\":false,\"authority\":\"terminal_final_row_capability_gate\"}"
                            (fileLogEscJson finalRowCapabilityRef))
                | None ->
                    let rows =
                        Array.init hudRows (fun i ->
                            hudFlex4
                                (hudKv "hud_contract" "50_rows_no_prune")
                                (hudKv "row" (sprintf "%d/%d" (i + 1) hudRows))
                                (hudKv "authority" "shutdown_without_live_snapshot")
                                (hudKv "shutdown" "terminal_epilogue"))
                    rows
                    |> Array.iteri (fun i clean ->
                        (if System.Environment.GetEnvironmentVariable "SPIRAL_DIAG_QUIET" <> "1" then Console.Error.WriteLine("[spiral_hud_final] " + clean))
                        appendFileLogLineSerialized (
                            FastRuntimeFormat.format "{\"v\":2,\"ts_ms\":%d,\"pid\":%d,\"tid\":%d,\"kind\":\"spiral_hud_final\",\"line_index\":%d,\"row_count\":%d,\"final_row\":false,\"snapshot_available\":false,\"text\":%s,\"authority\":\"shutdown_without_live_hud_snapshot\",\"hud_contract_du\":\"DetailedFlex50NoPrune\",\"row_compaction_du\":\"complete_50_row_final_hud_snapshot\"}" [| box nowMs; box pid; box tid; box i; box rows.Length; box (fileLogEscJson clean) |]))
                    appendFileLogLineSerialized (
                        sprintf "{\"v\":2,\"kind\":\"terminal_final_row_blocked\",\"closure_proof_ref\":%s,\"reason_du\":\"ReducerSnapshotUnavailable\",\"final_row_emitted\":false,\"authority\":\"terminal_final_row_capability_gate\"}"
                            (fileLogEscJson finalRowCapabilityRef))
                | Some snapshot ->
                    let possession = reducerHudPossessionText snapshot.possession
                    let phase = reducerHudProgressPhaseText snapshot.phase
                    let boundaryRunEndReceiptRef, boundaryPhysicalExitReceiptRef, boundaryExitCode =
                        match terminalPresentationPhysicalBoundaryObservation with
                        | Some(runEndReceiptRef, physicalExitReceiptRef, exitCode) ->
                            runEndReceiptRef, physicalExitReceiptRef, Some exitCode
                        | None -> "", "", None
                    let snapshotRunEndReceiptObserved = not (String.IsNullOrWhiteSpace snapshot.runEndReceiptRef)
                    let snapshotPhysicalExitReceiptObserved = not (String.IsNullOrWhiteSpace snapshot.physicalExitReceiptRef)
                    let boundaryRunEndReceiptObserved = not (String.IsNullOrWhiteSpace boundaryRunEndReceiptRef)
                    let boundaryPhysicalExitReceiptObserved = not (String.IsNullOrWhiteSpace boundaryPhysicalExitReceiptRef)
                    let durableRunEndObserved = terminalDurableRunEndObservedNow()
                    let runEndReceiptObserved = snapshotRunEndReceiptObserved || boundaryRunEndReceiptObserved
                    let physicalExitReceiptObserved = snapshotPhysicalExitReceiptObserved || boundaryPhysicalExitReceiptObserved
                    let runEndObserved = durableRunEndObserved || runEndReceiptObserved
                    let finalRowPhysicallyAuthorized = finalRowAuthorized && runEndReceiptObserved && physicalExitReceiptObserved
                    // The physical-boundary observation is populated only after the typed exit
                    // boundary is selected. It may therefore complete a stale reducer HUD snapshot,
                    // but it remains observer-only and cannot authorize compiler control flow.
                    // Durable run_end observation is independently truthful even when the physical
                    // boundary has not yet been selected; do not erase that fact from the final HUD.
                    let physicalExitObserved = finalRowPhysicallyAuthorized
                    let reportedRunEndReceiptRef =
                        if boundaryRunEndReceiptObserved then boundaryRunEndReceiptRef
                        else snapshot.runEndReceiptRef
                    let reportedPhysicalExitReceiptRef =
                        if not finalRowPhysicallyAuthorized then ""
                        elif boundaryPhysicalExitReceiptObserved then boundaryPhysicalExitReceiptRef
                        else snapshot.physicalExitReceiptRef
                    let reportedSealedAtMs = if finalRowPhysicallyAuthorized then snapshot.sealedAtMs else None
                    let reportedExitCode =
                        if finalRowPhysicallyAuthorized then
                            match boundaryExitCode with
                            | Some exitCode -> Some exitCode
                            | None -> snapshot.exitCode
                        elif runEndObserved then snapshot.exitCode
                        else None
                    let outcomeId =
                        match snapshot.possession with
                        | ReducerHudPossessionFailedClosed -> ReducerHudOutcomeFailedClosed
                        | _ -> reducerHudOutcomeId runEndObserved reportedExitCode
                    let failedClosed = reducerHudOutcomeIsFailedClosed outcomeId
                    let reportedProgressLowBp : int64 = snapshot.work.lowBp
                    let reportedProgressMidBp : int64 = snapshot.work.midBp
                    let reportedProgressHighBp : int64 = snapshot.work.highBp
                    let outcomeDu = reducerHudOutcomeText outcomeId
                    let terminalProtocolOpen = not finalRowPhysicallyAuthorized
                    let reportedBlockerCount, blockerCountAuthority =
                        match snapshot.blockers.Length, terminalProtocolOpen with
                        | count, _ when count > 0 -> count, ReducerHudFinalBlockerRows
                        | 0, true -> 1, ReducerHudFinalTerminalProtocolResidual
                        | _ -> 0, ReducerHudFinalNoBlocker
                    let blockerCountAuthorityDu = reducerHudFinalBlockerCountAuthorityText blockerCountAuthority
                    let reportedEtaP50S : int64 = if failedClosed || terminalProtocolOpen then -1L else reducerHudEtaP50Seconds snapshot
                    let reportedEtaP90S : int64 = if failedClosed || terminalProtocolOpen then -1L else reducerHudEtaP90Seconds snapshot
                    let reportedEtaSigmaS : int64 = if failedClosed || terminalProtocolOpen then -1L else reducerHudEtaSigmaSeconds snapshot
                    let criticalPathRemainingCostJson =
                        reducerHudCriticalPathRemainingCost snapshot.eta.criticalPath
                        |> Option.map string
                        |> Option.defaultValue "null"
                    let criticalPathStateJson = fileLogEscJson (reducerHudCriticalPathText snapshot.eta.criticalPath)
                    let scopeInvariantSatisfied = snapshot.work.semantic.retiredCost <= snapshot.work.semantic.totalMid
                    // Denominator exactness is a discovery property, not a completion property.
                    // Remaining known work may be non-zero while the total is already exact; requiring
                    // retired=total conflated "finished" with "we know how much exists" and made the
                    // final HUD claim an inexact denominator for the 7651/7653 case.
                    let semanticDenominatorExact =
                        scopeInvariantSatisfied
                        && snapshot.work.semantic.totalHigh = snapshot.work.semantic.totalMid
                        && snapshot.work.semantic.reserveP50Cost = 0L
                        && snapshot.work.semantic.reserveP90Cost = 0L
                    let exactDenominator = semanticDenominatorExact
                    let exactDenominatorAuthority =
                        if semanticDenominatorExact then ReducerHudFinalSemanticGapExact
                        else ReducerHudFinalSemanticGapInexact
                    let exactDenominatorAuthorityDu =
                        reducerHudFinalExactDenominatorAuthorityText exactDenominatorAuthority
                    let observedSnapshot =
                        if finalRowPhysicallyAuthorized then
                            { snapshot with
                                runEndReceiptRef = reportedRunEndReceiptRef
                                physicalExitReceiptRef = reportedPhysicalExitReceiptRef
                                exitCode = reportedExitCode }
                        else
                            { snapshot with
                                runEndReceiptRef = ""
                                physicalExitReceiptRef = ""
                                exitCode = None
                                sealedAtMs = None }
                    let reducerRows = reducerHudLines monotonicNowMs observedSnapshot
                    // The final board has two authority bands: rows 1..33 are the immutable
                    // semantic/detail projection, while rows 34..50 are replaced by the final
                    // reducer generation.  Terminal phase/receipt authority therefore remains
                    // snapshot-pure without duplicating the reducer band at both ends.
                    let liveRows =
                        if finalRowPhysicallyAuthorized then
                            // Preserve the immutable semantic/detail band in rows 1..33 and
                            // replace only the terminal authority band in rows 34..50.  Using
                            // reducerRows as both sources duplicated the same seventeen rows.
                            progressHudSemanticBoardRead ()
                        elif hudLines.Length > 0 then
                            Array.copy hudLines
                        else Array.copy reducerRows
                    let reducerStart = max 0 (hudRows - reducerRows.Length)
                    let rows =
                        Array.init hudRows (fun i ->
                            if i >= reducerStart then
                                reducerRows.[i - reducerStart] |> cleanText |> fitLine (safeWidth())
                            elif i < liveRows.Length then
                                liveRows.[i] |> cleanText |> fitLine (safeWidth())
                            else
                                hudFlex4
                                    (hudKv "hud_contract" "50_rows_no_prune")
                                    (hudKv "row" (sprintf "%d/%d" (i + 1) hudRows))
                                    (hudKv "phase" phase)
                                    (hudKv "possession" possession))
                    // Quiet mode (tests, probes, apps builds) keeps stderr for the result and the error: the 50-row final HUD buried it.
                    if System.Environment.GetEnvironmentVariable "SPIRAL_DIAG_QUIET" <> "1" then
                        rows |> Array.iter (fun row -> Console.Error.WriteLine("[spiral_hud_final] " + row))
                    appendFileLogLineSerialized (
                        FastRuntimeFormat.format "{\"v\":2,\"ts_ms\":%d,\"pid\":%d,\"tid\":%d,\"kind\":\"reducer_hud_final_snapshot\",\"snapshot_available\":true,\"generation\":%d,\"snapshot_ms\":%d,\"elapsed_ms\":%d,\"phase_du\":%s,\"possession_stage_du\":%s,\"outcome_du\":%s,\"completed_cost\":%d,\"total_cost\":%d,\"progress_low_bp\":%d,\"progress_mid_bp\":%d,\"progress_high_bp\":%d,\"exact_denominator\":%b,\"exact_denominator_authority_du\":%s,\"numerator_scope_du\":\"kernel_cost_projection\",\"denominator_scope_du\":\"kernel_cost_projection\",\"scope_invariant_satisfied\":%b,\"eta_p50_s\":%d,\"eta_p90_s\":%d,\"eta_sigma_s\":%d,\"critical_path_remaining_cost\":%s,\"critical_path_du\":%s,\"actor_ref\":%s,\"stage_token_ref\":%s,\"fill_receipt_ref\":%s,\"run_end_receipt_ref\":%s,\"physical_exit_receipt_ref\":%s,\"run_end_emitted\":%b,\"exit_code\":%s,\"sealed_at_ms\":%s,\"blocker_count\":%d,\"blocker_count_authority_du\":%s,\"physical_boundary_overlay_applied\":%b,\"authority\":\"reducer_snapshot_with_optional_physical_boundary_overlay\",\"legacy_cache_authority\":false,\"hud_contract_du\":\"DetailedFlex50NoPrune\",\"row_count\":%d}" [| box nowMs; box pid; box tid; box snapshot.generation; box snapshot.snapshotMs; box snapshot.elapsedMsAtSnapshot; box (fileLogEscJson phase); box (fileLogEscJson possession); box (fileLogEscJson outcomeDu); box snapshot.work.semantic.retiredCost; box snapshot.work.semantic.totalMid; box reportedProgressLowBp; box reportedProgressMidBp; box reportedProgressHighBp; box exactDenominator; box (fileLogEscJson exactDenominatorAuthorityDu); box scopeInvariantSatisfied; box reportedEtaP50S; box reportedEtaP90S; box reportedEtaSigmaS; box criticalPathRemainingCostJson; box criticalPathStateJson; box (fileLogEscJson snapshot.actorRef); box (fileLogEscJson snapshot.stageTokenRef); box (fileLogEscJson snapshot.fillReceiptRef); box (fileLogEscJson reportedRunEndReceiptRef); box (fileLogEscJson reportedPhysicalExitReceiptRef); box runEndObserved; box (fileLogEscJson (reportedExitCode |> Option.map string |> Option.defaultValue "")); box (fileLogEscJson (reportedSealedAtMs |> Option.map string |> Option.defaultValue "")); box reportedBlockerCount; box (fileLogEscJson blockerCountAuthorityDu); box physicalBoundaryFinalRowAuthorized; box rows.Length |])
                    rows
                    |> Array.iteri (fun i row ->
                        let clean = cleanText row
                        let isFinalRow = finalRowPhysicallyAuthorized && i = rows.Length - 1
                        // Persist the receipt-pair audit immediately before the unique final row.
                        // This ordering makes the receipt impossible to lose behind an earlier HUD
                        // flush while keeping `final_row=true` as the physical tail of the JSONL.
                        if isFinalRow then
                            appendFileLogLineSerialized (
                                FastRuntimeFormat.format "{\"v\":2,\"ts_ms\":%d,\"pid\":%d,\"tid\":%d,\"kind\":\"terminal_durable_receipt_pair_observed\",\"generation\":%d,\"possession_stage_du\":%s,\"outcome_du\":%s,\"run_end_receipt_ref\":%s,\"physical_exit_receipt_ref\":%s,\"exit_code\":%s,\"closure_proof_ref\":%s,\"final_row_capability_observed\":%b,\"authority\":\"physical_boundary_receipt_pair_plus_optional_final_row_capability\",\"control_authority\":false,\"next\":\"persist_unique_final_row_then_process_exit\"}" [| box nowMs; box pid; box tid; box snapshot.generation; box (fileLogEscJson possession); box (fileLogEscJson outcomeDu); box (fileLogEscJson reportedRunEndReceiptRef); box (fileLogEscJson reportedPhysicalExitReceiptRef); box (fileLogEscJson (reportedExitCode |> Option.map string |> Option.defaultValue "")); box (fileLogEscJson finalRowCapabilityRef); box finalRowCapabilityAuthorized |])
                        appendFileLogLineSerialized (
                            FastRuntimeFormat.format "{\"v\":2,\"ts_ms\":%d,\"pid\":%d,\"tid\":%d,\"kind\":\"spiral_hud_final\",\"line_index\":%d,\"row_count\":%d,\"final_row\":%b,\"snapshot_available\":true,\"generation\":%d,\"phase_du\":%s,\"possession_stage_du\":%s,\"outcome_du\":%s,\"progress_mid_bp\":%d,\"run_end_emitted\":%b,\"physical_exit_receipt_ref\":%s,\"exit_code\":%s,\"text\":%s,\"physical_boundary_overlay_applied\":%b,\"authority\":\"reducer_snapshot_with_optional_physical_boundary_overlay\",\"hud_contract_du\":\"DetailedFlex50NoPrune\",\"row_compaction_du\":\"complete_50_row_final_hud_snapshot\"}" [| box nowMs; box pid; box tid; box i; box rows.Length; box isFinalRow; box snapshot.generation; box (fileLogEscJson phase); box (fileLogEscJson possession); box (fileLogEscJson outcomeDu); box reportedProgressMidBp; box runEndObserved; box (fileLogEscJson reportedPhysicalExitReceiptRef); box (fileLogEscJson (reportedExitCode |> Option.map string |> Option.defaultValue "")); box (fileLogEscJson clean); box physicalBoundaryFinalRowAuthorized |]))
                    if finalRowPhysicallyAuthorized then
                        commitFinalRowIfAuthorized ()
                    else
                        appendFileLogLineSerialized (
                            FastRuntimeFormat.format "{\"v\":2,\"kind\":\"terminal_final_row_blocked\",\"closure_proof_ref\":%s,\"reason_du\":\"RunEndAndPhysicalExitReceiptsRequired\",\"run_end_observed\":%b,\"physical_exit_observed\":%b,\"final_row_emitted\":false,\"authority\":\"terminal_final_row_capability_gate\"}" [| box (fileLogEscJson finalRowCapabilityRef); box runEndObserved; box physicalExitObserved |])

        let mutable private finalHudFileHandlersInstalled = false

        let private flushFileLogUnlocked () =
            // The name means "not under the HUD gate"; the shared FileStream itself
            // still has exactly one physical authority for Seek/Write/Flush.
            lock fileLogWriteGate (fun () ->
                match fileLogState with
                | Some (CompilerFileLogOpen fs) ->
                    try
                        fs.Flush(true)
                        fileLogPendingLineCount <- 0
                        fileLogLastFlushMs <- DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                    with _ -> ()
                | _ -> ())

        let private tryEmitFinalHudSnapshotForExit () =
            terminalShutdownRequested <- true
            requestObserverDrain TerminalObserverDrainProcessExit
            try
                lock gate (fun () ->
                    lock progressHudConsoleWriteGate (fun () ->
                        if supportsHud() then resetSplitUnlocked())
                    emitFinalHudSnapshotUnlocked()
                    flushFileLogUnlocked())
            with _ -> ()

        let emitFinalHudSnapshotNow () =
            tryEmitFinalHudSnapshotForExit()

        let private emitFinalHudSnapshotForRequestCompletion () =
            terminalShutdownRequested <- true
            requestObserverDrain TerminalObserverDrainSupervisorRequestCompletion
            try
                lock gate (fun () ->
                    lock progressHudConsoleWriteGate (fun () ->
                        if supportsHud() then resetSplitUnlocked())
                    if not (finalHudCommitted()) then
                        appendFileLogLineSerialized (
                            "{\"v\":2,\"kind\":\"terminal_presentation_epilogue\",\"boundary_du\":\"supervisor_request_completion\",\"taskbar_state_du\":\"NoProgress\",\"taskbar_shutdown_latched\":false,\"hud_tail_required\":false,\"next\":\"commit_final_hud_under_single_writer_gate\"}")
                    emitFinalHudSnapshotUnlocked()
                    flushFileLogUnlocked())
            with _ -> ()

        let private resetFinalHudForSupervisorRequest () =
            lock gate (fun () ->
                terminalShutdownRequested <- false
                finalHudPersistenceState <- FinalHudPending
                lock reducerHudProjectionGate (fun () ->
                    reducerHudProjection <- Some (reducerHudBootstrapSnapshot()))
                resetTerminalFinalRowCapability ())

        do
            requestFooterCommit <- emitFinalHudSnapshotForRequestCompletion
            requestFooterReset <- resetFinalHudForSupervisorRequest

        type private TerminalPresentationExitBoundary =
            | TerminalPresentationPhysicalBoundary
            | TerminalPresentationHostReturn
            | TerminalPresentationFailsafe

        let private terminalPresentationExitBoundaryText = function
            | TerminalPresentationPhysicalBoundary -> "physical_boundary"
            | TerminalPresentationHostReturn -> "host_return"
            | TerminalPresentationFailsafe -> "failsafe"

        let private terminalObserverDrainRequestReasonOfBoundary = function
            | TerminalPresentationPhysicalBoundary -> TerminalObserverDrainPhysicalBoundary
            | TerminalPresentationHostReturn -> TerminalObserverDrainHostReturn
            | TerminalPresentationFailsafe -> TerminalObserverDrainFailsafe

        let private completeTerminalPresentationForExit boundary exitCode =
            terminalShutdownRequested <- true
            requestObserverDrain (terminalObserverDrainRequestReasonOfBoundary boundary)
            completeWindowsTaskbarForExit exitCode
            try
                lock gate (fun () ->
                    lock progressHudConsoleWriteGate (fun () ->
                        if supportsHud() then resetSplitUnlocked())
                    if not (finalHudCommitted()) then
                        appendFileLogLineSerialized (
                            sprintf "{\"v\":2,\"kind\":\"terminal_presentation_epilogue\",\"boundary_du\":%s,\"exit_code\":%d,\"taskbar_state_du\":\"NoProgress\",\"taskbar_shutdown_latched\":true,\"hud_tail_required\":false,\"next\":\"commit_final_hud_under_single_writer_gate\"}"
                                (fileLogEscJson (terminalPresentationExitBoundaryText boundary))
                                exitCode)
                    emitFinalHudSnapshotUnlocked()
                    flushFileLogUnlocked())
            with _ -> ()

        let completeTerminalPresentationForPhysicalExit exitCode runEndReceiptRef physicalExitReceiptRef =
            terminalPresentationPhysicalBoundaryObservation <-
                Some(string runEndReceiptRef, string physicalExitReceiptRef, exitCode)
            completeTerminalPresentationForExit TerminalPresentationPhysicalBoundary exitCode

        let completeTerminalPresentationForHostReturn exitCode =
            completeTerminalPresentationForExit TerminalPresentationHostReturn exitCode

        let completeTerminalPresentationForFailsafe exitCode =
            completeTerminalPresentationForExit TerminalPresentationFailsafe exitCode

        let private installFinalHudFileHandlersUnlocked () =
            installRuntimeExceptionCaptureHooks()
            if not finalHudFileHandlersInstalled then
                finalHudFileHandlersInstalled <- true
                try
                    AppDomain.CurrentDomain.ProcessExit.AddHandler(EventHandler(fun _ _ ->
                        // ProcessExit runs inside Environment.Exit and must never wait for HUD/file gates.
                        // Normal host return and cancel paths already commit presentation before teardown;
                        // the emergency deadman emits only best-effort breadcrumbs before invoking exit.
                        terminalShutdownRequested <- true))
                with _ -> ()
                try
                    Console.CancelKeyPress.AddHandler(ConsoleCancelEventHandler(fun _ args ->
                        // Hold the default SIGINT for one bounded in-process footer transaction.
                        // No helper process or sidecar owns recovery; the durable writer gets
                        // up to one second to seal the fifty-row JSONL tail before termination.
                        args.Cancel <- true
                        terminalShutdownRequested <- true
                        // Neutralize before contending on the HUD/file gate. Background
                        // progress frames are shutdown-latched and cannot repaint green.
                        tryApplyWindowsTaskbarShutdownReason TaskbarCancelKeyPress
                        let mutable taken = false
                        try
                            System.Threading.Monitor.TryEnter(gate, 1000, &taken) |> ignore
                            if taken then
                                if not (finalHudCommitted()) then
                                    appendFileLogLineSerialized (
                                        "{\"v\":2,\"kind\":\"terminal_presentation_epilogue\",\"boundary_du\":\"cancel_key_press\",\"exit_code\":130,\"taskbar_state_du\":\"NoProgress\",\"taskbar_shutdown_latched\":true,\"hud_tail_required\":false,\"next\":\"commit_final_hud_under_single_writer_gate\"}")
                                emitFinalHudSnapshotUnlocked()
                                flushFileLogUnlocked()
                        finally
                            if taken then System.Threading.Monitor.Exit(gate)
                            args.Cancel <- false))
                with _ -> ()

        let private installHudSmoothFrameLinesUnlocked (raw: string array) =
            // Kept for bounded semantic installs. The 20 FPS painter no longer
            // acquires the durable HUD gate or mutates semantic revision state.
            let bounded =
                if raw.Length <= hudRows then raw
                else raw.[0 .. hudRows - 1]
            hudLines <- bounded
            progressHudSemanticBoardWrite bounded

        let private installHudLinesUnlocked (raw: string array) =
            let cleaned =
                raw
                |> Array.map cleanText
                |> Array.filter (fun x -> not (String.IsNullOrWhiteSpace x))
            let bounded =
                if cleaned.Length <= hudRows then cleaned
                else cleaned.[0 .. hudRows - 1]
            hudLines <- bounded
            progressHudSemanticBoardWrite bounded
            if not terminalShutdownRequested then
                finalHudPersistenceState <- FinalHudPending
            hudRevision <- hudRevision + 1L

        let withLock (f: unit -> unit) =
            lock gate (fun () ->
                f()
                try Console.Error.Flush() with _ -> ()
            )

        type HudMuxAcquireDecision =
            | HudMuxAcquired
            | HudMuxBusy
            | HudMuxInterrupted

        // Heartbeat/HUD refresh must never wait behind replay-log flush storms.
        // A thread interruption while attempting the mux is a shutdown/control
        // observation, not a formatter failure.  Convert it to a typed miss so the
        // caller can skip the optional projection without emitting an exception row.
        let tryWithLock (waitMs: int) (f: unit -> unit) =
            let mutable taken = false
            let decision =
                try
                    taken <- Monitor.TryEnter(gate, waitMs)
                    if taken then HudMuxAcquired else HudMuxBusy
                with :? System.Threading.ThreadInterruptedException ->
                    HudMuxInterrupted
            match decision with
            | HudMuxAcquired ->
                try
                    f()
                    try Console.Error.Flush() with _ -> ()
                    true
                finally
                    if taken then Monitor.Exit(gate)
            | HudMuxBusy
            | HudMuxInterrupted -> false

        type AdvancedConsoleTerminalEnvelopeId =
            | AdvancedConsoleHeartbeatHardAbort
            | AdvancedConsoleRootPromiseFailedSemanticExit
            | AdvancedConsoleNativeClosureFailureLedgerTerminal
            | AdvancedConsoleBuildOk
            | AdvancedConsoleBuildFatalError
            | AdvancedConsoleBuildErrorTrace
            | AdvancedConsoleGlobalCommitExitReady
            | AdvancedConsoleGlobalArmFailClosedExitWitness
            | AdvancedConsolePhysicalBoundary
            | AdvancedConsolePhysicalExitReceipt
            | AdvancedConsoleRunEnd
            | AdvancedConsoleWriteAbort
            | AdvancedConsoleNonTerminal

        type AdvancedConsoleRawLineId =
            | AdvancedConsoleRawWriteAbort
            | AdvancedConsoleRawOther

        let private advancedConsoleRawLineId (line:string) =
            if String.IsNullOrWhiteSpace line then AdvancedConsoleRawOther
            else
                let head =
                    line.TrimStart().Split([|' '; '\t'; ':'|], 2, StringSplitOptions.RemoveEmptyEntries)
                    |> Array.tryHead
                    |> Option.defaultValue ""
                if head = "WRITE_ABORT" then AdvancedConsoleRawWriteAbort
                else AdvancedConsoleRawOther

        type AdvancedConsoleEnvelopeFieldId =
            | AdvancedConsoleEventField
            | AdvancedConsoleKindField
            | AdvancedConsoleStateHashField
            | AdvancedConsoleGraphStateHashField
            | AdvancedConsoleQapGenerationField
            | AdvancedConsoleActorPhaseField
            | AdvancedConsoleActorStateField
            | AdvancedConsolePossessionField
            | AdvancedConsoleDecisionField
            | AdvancedConsoleStatusField
            | AdvancedConsolePendingField
            | AdvancedConsoleQueueField
            | AdvancedConsoleActiveField
            | AdvancedConsoleBlockedField
            | AdvancedConsoleTerminalOutcomeRefField
            | AdvancedConsoleFinalOutcomeField
            | AdvancedConsoleQapPostCommitField

        let private advancedConsoleEnvelopeFieldName = function
            | AdvancedConsoleEventField -> "event"
            | AdvancedConsoleKindField -> "kind"
            | AdvancedConsoleStateHashField -> "state_hash"
            | AdvancedConsoleGraphStateHashField -> "graph_state_hash"
            | AdvancedConsoleQapGenerationField -> "qap_generation_id"
            | AdvancedConsoleActorPhaseField -> "actor_phase"
            | AdvancedConsoleActorStateField -> "actor_state_du"
            | AdvancedConsolePossessionField -> "possession_du"
            | AdvancedConsoleDecisionField -> "decision_du"
            | AdvancedConsoleStatusField -> "status_du"
            | AdvancedConsolePendingField -> "pending"
            | AdvancedConsoleQueueField -> "queue"
            | AdvancedConsoleActiveField -> "active"
            | AdvancedConsoleBlockedField -> "blocked"
            | AdvancedConsoleTerminalOutcomeRefField -> "terminal_outcome_ref"
            | AdvancedConsoleFinalOutcomeField -> "final_outcome_du"
            | AdvancedConsoleQapPostCommitField -> "qap_post_commit_du"

        let private advancedConsoleEnvelopeScalar (fieldId:AdvancedConsoleEnvelopeFieldId) (line:string) =
            if String.IsNullOrWhiteSpace line then ""
            else
                let marker = "\"" + advancedConsoleEnvelopeFieldName fieldId + "\":"
                let parts = line.Split([|marker|], 2, StringSplitOptions.None)
                if parts.Length <> 2 then ""
                else
                    let rest = parts.[1].TrimStart()
                    if String.IsNullOrEmpty rest then ""
                    elif rest.[0] = '"' then
                        let mutable valueEnd = 1
                        let mutable finished = false
                        while valueEnd < rest.Length && not finished do
                            if rest.[valueEnd] = '"' && rest.[valueEnd - 1] <> '\\' then finished <- true
                            else valueEnd <- valueEnd + 1
                        if valueEnd < rest.Length then rest.Substring(1, valueEnd - 1) else ""
                    else
                        let mutable valueEnd = 0
                        while valueEnd < rest.Length && rest.[valueEnd] <> ',' && rest.[valueEnd] <> '}' do
                            valueEnd <- valueEnd + 1
                        if valueEnd > 0 then rest.Substring(0, valueEnd).Trim() else ""

        let private advancedConsoleTerminalEnvelopeId (line:string) =
            let eventId = advancedConsoleEnvelopeScalar AdvancedConsoleEventField line
            let kindId = advancedConsoleEnvelopeScalar AdvancedConsoleKindField line
            match eventId, kindId with
            | "heartbeat_hard_abort", _ -> AdvancedConsoleHeartbeatHardAbort
            | _, "root_promise_failed_semantic_exit" -> AdvancedConsoleRootPromiseFailedSemanticExit
            | _, "native_closure_failure_ledger_terminal" -> AdvancedConsoleNativeClosureFailureLedgerTerminal
            | _, "BuildOk" -> AdvancedConsoleBuildOk
            | _, "BuildFatalError" -> AdvancedConsoleBuildFatalError
            | _, "BuildErrorTrace" -> AdvancedConsoleBuildErrorTrace
            | _, "terminal_flow_global_commit_exit_ready" -> AdvancedConsoleGlobalCommitExitReady
            | _, "terminal_flow_global_arm_failclosed_exit_witness" -> AdvancedConsoleGlobalArmFailClosedExitWitness
            | _, "native_terminal_exit_contract_physical_boundary" -> AdvancedConsolePhysicalBoundary
            | _, "physical_exit_receipt" -> AdvancedConsolePhysicalExitReceipt
            | _, "run_end" -> AdvancedConsoleRunEnd
            | _ when advancedConsoleRawLineId line = AdvancedConsoleRawWriteAbort -> AdvancedConsoleWriteAbort
            | _ -> AdvancedConsoleNonTerminal

        let private terminalLine (s: string) =
            match advancedConsoleTerminalEnvelopeId s with
            | AdvancedConsoleHeartbeatHardAbort
            | AdvancedConsoleRootPromiseFailedSemanticExit
            | AdvancedConsoleNativeClosureFailureLedgerTerminal
            | AdvancedConsoleBuildFatalError
            | AdvancedConsolePhysicalExitReceipt
            | AdvancedConsoleRunEnd
            | AdvancedConsoleWriteAbort -> true
            | _ -> false

        type AdvancedConsoleProjectionFamilyId =
            | AdvancedConsoleFairnessProjection
            | AdvancedConsoleSchedulerFairnessProjection
            | AdvancedConsoleProgressAuthorityProjection
            | AdvancedConsoleCicKernelProjection
            | AdvancedConsoleWaitGraphProjection
            | AdvancedConsoleWorkLedgerProjection
            | AdvancedConsoleGenericProjection

        type AdvancedConsoleProjectionCompactionDecision =
            | AdvancedConsoleProjectionPassThrough
            | AdvancedConsoleProjectionEmit of family:AdvancedConsoleProjectionFamilyId * repeatCount:int64 * stateRef:uint32
            | AdvancedConsoleProjectionSuppress of family:AdvancedConsoleProjectionFamilyId * repeatCount:int64 * stateRef:uint32

        let private advancedConsoleProjectionStateByKind = Dictionary<AdvancedConsoleProjectionFamilyId, CompilerIdentityKernel.ContentDigest>()
        let private advancedConsoleProjectionRepeatByKind = Dictionary<AdvancedConsoleProjectionFamilyId, int64>()

        let private advancedConsoleProjectionFamilyId = function
            | "terminal_fairness_projection" -> Some AdvancedConsoleFairnessProjection
            | "terminal_scheduler_fairness_projection"
            | "scheduler_replay_fairness_projection" -> Some AdvancedConsoleSchedulerFairnessProjection
            | "terminal_progress_authority_projection" -> Some AdvancedConsoleProgressAuthorityProjection
            | "terminal_cic_kernel_profile" -> Some AdvancedConsoleCicKernelProjection
            | "terminal_wait_graph_projection" -> Some AdvancedConsoleWaitGraphProjection
            | "terminal_work_unit_ledger" -> Some AdvancedConsoleWorkLedgerProjection
            | "advanced_console_projection" -> Some AdvancedConsoleGenericProjection
            | _ -> None

        let private advancedConsoleProjectionStateRef (signature:string) =
            let mutable hash = 2166136261u
            for ch in signature do
                hash <- (hash ^^^ uint32 (int ch)) * 16777619u
            if hash = 0u then 1u else hash

        let private advancedConsoleProjectionMilestone repeatCount =
            repeatCount <= 3L
            || (repeatCount > 0L && (repeatCount &&& (repeatCount - 1L)) = 0L)
            || repeatCount % 64L = 0L

        let private migrationTerminalEnvelopeFixtureMatrix =
            [ "{\"event\":\"heartbeat_hard_abort\"}", AdvancedConsoleHeartbeatHardAbort
              "{\"kind\":\"BuildOk\"}", AdvancedConsoleBuildOk
              "{\"kind\":\"terminal_flow_global_commit_exit_ready\"}", AdvancedConsoleGlobalCommitExitReady
              "{\"kind\":\"run_end\"}", AdvancedConsoleRunEnd
              "{\"kind\":\"physical_exit_receipt\"}", AdvancedConsolePhysicalExitReceipt
              "{\"kind\":\"terminal_wait_graph_projection\"}", AdvancedConsoleNonTerminal ]

        let private migrationProjectionMilestoneFixtureMatrix =
            [ 1L, true; 2L, true; 3L, true; 4L, true; 5L, false; 8L, true; 63L, false; 64L, true; 65L, false ]

        let private migrationProjectionCompactionFixturePass =
            (migrationTerminalEnvelopeFixtureMatrix
             |> List.forall (fun (line, expected) -> advancedConsoleTerminalEnvelopeId line = expected))
            && (migrationProjectionMilestoneFixtureMatrix
                |> List.forall (fun (repeatCount, expected) -> advancedConsoleProjectionMilestone repeatCount = expected))

        let private advancedConsoleProjectionCompactionDecision (line:string) =
            let kind = advancedConsoleEnvelopeScalar AdvancedConsoleKindField line
            match advancedConsoleProjectionFamilyId kind with
            | None -> AdvancedConsoleProjectionPassThrough
            | Some family ->
                // MIGRATION: projection identity must describe semantic state, not
                // freshly minted receipt/revision ids. Volatile refs defeated compaction
                // and produced more than 84k duplicate projections in historical runtime.
                let signature =
                    [ AdvancedConsoleStateHashField
                      AdvancedConsoleGraphStateHashField
                      AdvancedConsoleQapGenerationField
                      AdvancedConsoleActorPhaseField
                      AdvancedConsoleActorStateField
                      AdvancedConsolePossessionField
                      AdvancedConsoleDecisionField
                      AdvancedConsoleStatusField
                      AdvancedConsolePendingField
                      AdvancedConsoleQueueField
                      AdvancedConsoleActiveField
                      AdvancedConsoleBlockedField
                      AdvancedConsoleTerminalOutcomeRefField
                      AdvancedConsoleFinalOutcomeField
                      AdvancedConsoleQapPostCommitField ]
                    |> List.map (fun fieldId -> advancedConsoleEnvelopeScalar fieldId line)
                    |> String.concat "|"
                if signature.Replace("|", "").Length = 0 then AdvancedConsoleProjectionPassThrough
                else
                    let stateRef = advancedConsoleProjectionStateRef signature
                    let signatureRef = CompilerIdentityKernel.ContentDigest.ofText "advanced-console-projection-state" signature
                    match advancedConsoleProjectionStateByKind.TryGetValue family with
                    | true, previous when previous = signatureRef ->
                        let repeatCount =
                            match advancedConsoleProjectionRepeatByKind.TryGetValue family with
                            | true, count -> count + 1L
                            | _ -> 2L
                        advancedConsoleProjectionRepeatByKind.[family] <- repeatCount
                        if advancedConsoleProjectionMilestone repeatCount then
                            AdvancedConsoleProjectionEmit(family, repeatCount, stateRef)
                        else AdvancedConsoleProjectionSuppress(family, repeatCount, stateRef)
                    | _ ->
                        advancedConsoleProjectionStateByKind.[family] <- signatureRef
                        advancedConsoleProjectionRepeatByKind.[family] <- 1L
                        AdvancedConsoleProjectionEmit(family, 1L, stateRef)

        let private advancedConsoleCompactedProjectionLine (line:string) repeatCount stateRef =
            if repeatCount <= 1L || String.IsNullOrWhiteSpace line || not (line.EndsWith("}", StringComparison.Ordinal)) then line
            else
                line.Substring(0, line.Length - 1)
                + FastRuntimeFormat.format ",\"projection_repeat_count\":%d,\"projection_state_ref\":%u,\"projection_compaction_policy_du\":\"FirstThreePowerTwoThen64\",\"projection_compaction_fixture_pass\":%b}" [| box repeatCount; box stateRef; box migrationProjectionCompactionFixturePass |]

        type private CompilerConsoleProjectionDisposition =
            | CompilerConsoleProjectionFileOnly
            | CompilerConsoleProjectionHuman
            | CompilerConsoleProjectionTerminal

        let private compilerConsoleProjectionDispositionFor (line:string) isTerminal =
            if isTerminal then CompilerConsoleProjectionTerminal
            else
                match advancedConsoleEnvelopeScalar AdvancedConsoleKindField line with
                | "advanced_console_projection"
                | "spiral_hud_format_exception"
                | "runtime_exception"
                | "progress_hud_ticker_faulted"
                | "progress_hud_bootstrap_paint_failed"
                | "build_error_trace" -> CompilerConsoleProjectionHuman
                | _ -> CompilerConsoleProjectionFileOnly

        let private writeLineUnlocked (s: string) =
            installFinalHudFileHandlersUnlocked()
            let compactionDecision = advancedConsoleProjectionCompactionDecision s
            let shouldWrite, lineToWrite =
                match compactionDecision with
                | AdvancedConsoleProjectionSuppress _ -> false, s
                | AdvancedConsoleProjectionEmit(_, repeatCount, stateRef) ->
                    true, advancedConsoleCompactedProjectionLine s repeatCount stateRef
                | AdvancedConsoleProjectionPassThrough -> true, s
            let isTerminal = terminalLine lineToWrite
            if not shouldWrite then ()
            elif terminalShutdownRequested && (finalHudCommitted() || not isTerminal) then
                // The physical presentation epilogue owns shutdown. Intermediate terminal
                // receipts remain appendable until that epilogue starts, preserving the full
                // JSONL transaction before the final HUD tail is committed.
                flushFileLogUnlocked()
            else
                appendFileLogLineSerialized lineToWrite
                match compilerConsoleProjectionDispositionFor lineToWrite isTerminal with
                | CompilerConsoleProjectionFileOnly -> ()
                | disposition ->
                    // JSONL remains complete. The interactive console receives only
                    // human-facing projections and terminal receipts, so machine telemetry
                    // cannot invalidate the 50-row diff cache or monopolize the HUD lane.
                    let consoleLine =
                        if lineToWrite.Length <= 2048 then lineToWrite
                        else lineToWrite.Substring(0, 1792) + sprintf " … [console projection truncated; full_jsonl_chars=%d]" lineToWrite.Length
                    lock progressHudConsoleWriteGate (fun () ->
                        if supportsHud() then
                            installSplitUnlocked()
                            try
                                let top = Console.CursorTop
                                let bottom = logBottomRow0()
                                if top > bottom then
                                    ansi (sprintf "%s%d;1H" esc (bottom + 1))
                            with _ -> ()
                            Console.Error.WriteLine(consoleLine)
                            invalidateProgressHudDiffCache()
                        else
                            Console.Error.WriteLine(consoleLine)
                        match disposition with
                        | CompilerConsoleProjectionTerminal -> Console.Error.Flush()
                        | _ -> ())

        let writeLine (s: string) =
            if not (Object.ReferenceEquals(s, null)) then
                try withLock (fun () -> writeLineUnlocked s)
                with _ ->
                    // A failed mux may preserve ordinary narration, but never append
                    // beneath a committed footer. The final HUD remains the last JSONL
                    // transaction even when a writer is interrupted while acquiring it.
                    if not (terminalShutdownRequested && finalHudCommitted()) then
                        appendFileLogLineSerialized s

        let writeLineAnsi (s: string) = writeLine s

        let private jsonScalarField (key: string) (line: string) =
            try
                let needle = "\"" + key + "\":"
                let parts = line.Split([|needle|], 2, StringSplitOptions.None)
                if parts.Length <> 2 then ""
                else
                    let rest = parts.[1].TrimStart()
                    if String.IsNullOrEmpty rest then ""
                    elif rest.[0] = '"' then
                        let mutable endi = 1
                        let mutable finished = false
                        while endi < rest.Length && not finished do
                            if rest.[endi] = '"' && rest.[endi - 1] <> '\\' then
                                finished <- true
                            else
                                endi <- endi + 1
                        if endi < rest.Length then rest.Substring(1, endi - 1) else ""
                    else
                        let mutable endi = 0
                        while endi < rest.Length && rest.[endi] <> ',' && rest.[endi] <> '}' do
                            endi <- endi + 1
                        if endi > 0 then rest.Substring(0, endi).Trim().Trim([|'"'|]) else ""
            with _ -> ""

        let private jsonHasField (key:string) (line:string) =
            not (System.Object.ReferenceEquals(line, null))
            && line.IndexOf("\"" + key + "\":", StringComparison.Ordinal) >= 0

        type JsonFieldPresenceId =
            | JsonFieldPresent
            | JsonFieldAbsent

        let private jsonFieldPresenceId (key:string) (line:string) =
            if jsonHasField key line then JsonFieldPresent else JsonFieldAbsent

        let private firstField (keys: string list) (line: string) =
            keys
            |> List.tryPick (fun key ->
                let v = jsonScalarField key line
                if String.IsNullOrWhiteSpace v then None else Some v)
            |> function
               | Some v -> v
               | None -> ""

        type TerminalFlowHudNativeEvidence =
            | TerminalFlowHudNativeEvidenceNone
            | TerminalFlowHudNativeCallback
            | TerminalFlowHudNativeRunQueue
            | TerminalFlowHudNativeIvarFill
            | TerminalFlowHudNativeJobBind

        type TerminalFlowHudStuckEvidence =
            | TerminalFlowHudStuckEvidenceNone
            | TerminalFlowHudFatalPromiseFailure
            | TerminalFlowHudPlateauPoison
            | TerminalFlowHudParentReplayPoisonTail

        type TerminalFlowHudLineEvidence = {
            nativeEvidence : TerminalFlowHudNativeEvidence
            stuckEvidence : TerminalFlowHudStuckEvidence
        }

        type TerminalFlowHudWorkerDirective =
            | TerminalFlowHudBindRootToWriter
            | TerminalFlowHudDurableTerminalExit
            | TerminalFlowHudCascadeOwnerDebtDrain
            | TerminalFlowHudScheduleParentPoisonDrain
            | TerminalFlowHudExecuteNativeInlineBeforeLegacyBoundary
            | TerminalFlowHudPreserveWorkerDecision of decision:string
            | TerminalFlowHudPreserveWorkerDecisionWithDefer of decision:string * deferDecision:string

        let private terminalFlowHudWorkerDirectiveText = function
            | TerminalFlowHudBindRootToWriter -> "native_job_bind_root_capability_to_terminal_outcome_to_writer_capability"
            | TerminalFlowHudDurableTerminalExit -> "durable_terminal_exit_1_now"
            | TerminalFlowHudCascadeOwnerDebtDrain -> "cascade_owner_debt_drain_after_material_delta"
            | TerminalFlowHudScheduleParentPoisonDrain -> "schedule_parent_poison_owner_drain_before_terminal"
            | TerminalFlowHudExecuteNativeInlineBeforeLegacyBoundary -> "execute_native_inline_callback_before_eval_worklist_boundary (terminal_payload_outranks_qap)"
            | TerminalFlowHudPreserveWorkerDecision decision -> decision
            | TerminalFlowHudPreserveWorkerDecisionWithDefer(decision, deferDecision) -> decision + " (defer: " + deferDecision + ")"

        [<Struct>]
        type TerminalFlowHudSymbol =
            private TerminalFlowHudSymbol of string

        let private terminalFlowHudSymbolText (TerminalFlowHudSymbol value) = value

        let private terminalFlowHudSymbols (value:string) =
            if String.IsNullOrWhiteSpace value then [||]
            else
                value.Split(
                    [| ' '; '\t'; '\r'; '\n'; '('; ')'; '['; ']'; '{'; '}'; ','; ';'; '|'; ':'; '='; '"'; '\''; '<'; '>'; '/'; '\\' |],
                    StringSplitOptions.RemoveEmptyEntries)
                |> Array.map (fun symbol -> TerminalFlowHudSymbol(symbol.Trim()))

        let private terminalFlowHudTokenPresent (token:string) (value:string) =
            if String.IsNullOrWhiteSpace token || String.IsNullOrWhiteSpace value then false
            else
                terminalFlowHudSymbols value
                |> Array.exists (fun symbol ->
                    (terminalFlowHudSymbolText symbol).Equals(token, StringComparison.OrdinalIgnoreCase))

        type TerminalFlowHopacShadowBreach =
            | TerminalFlowHopacShadowNoBreach
            | TerminalFlowHopacShadowBannerBreach
            | TerminalFlowHopacShadowAltTimeoutLegacyIgnored

        let private terminalFlowHopacShadowBreachOfHud (value:string) =
            let has token = terminalFlowHudTokenPresent token value
            if has "SHADOW" && has "TIMEOUT" && has "BREACHED!" then TerminalFlowHopacShadowBannerBreach
            elif has "alt" && has "timeout_1500ms" && has "legacy_loop" && has "ignoring_timeout" then TerminalFlowHopacShadowAltTimeoutLegacyIgnored
            else TerminalFlowHopacShadowNoBreach

        let private terminalFlowHopacShadowBreachActive = function
            | TerminalFlowHopacShadowNoBreach -> false
            | TerminalFlowHopacShadowBannerBreach
            | TerminalFlowHopacShadowAltTimeoutLegacyIgnored -> true

        let private terminalFlowHudLineEvidenceOfLine (line:string) =
            let values =
                [ firstField ["kind"] line
                  firstField ["event"] line
                  firstField ["native_job_graph"] line
                  firstField ["root_promise_status_du"; "root_status_du"] line
                  firstField ["status_du"; "reason_du"; "blocker_du"] line
                  firstField ["semantic_parent_replay_du"; "native_closure_semantic_delta_du"] line ]
            let has token = values |> List.exists (terminalFlowHudTokenPresent token)
            let nativeEvidence =
                if has "ActiveNativeCallbackClosureExecutedBeforeEvalWorklistBoundary" then TerminalFlowHudNativeCallback
                elif has "native_hopac_run_queue" then TerminalFlowHudNativeRunQueue
                elif has "IVar.fill" then TerminalFlowHudNativeIvarFill
                elif has "Job.bind" then TerminalFlowHudNativeJobBind
                else TerminalFlowHudNativeEvidenceNone
            let stuckEvidence =
                if has "FatalPromiseFailure" || has "RootPromiseFailed" then TerminalFlowHudFatalPromiseFailure
                elif has "PlateauPoison" then TerminalFlowHudPlateauPoison
                elif has "parent_replay_poison_tiny_tail" || has "semantic_parent_replay_cycle_break_poisoned" then TerminalFlowHudParentReplayPoisonTail
                else TerminalFlowHudStuckEvidenceNone
            { nativeEvidence = nativeEvidence; stuckEvidence = stuckEvidence }

        // MIGRATION: the MIGRATION assessment asked for Phase 2 counters in the live HUD/ticks,
        // but MIGRATION only remembered them when a sweep receipt happened.  The
        // metronomes now carry the last observed numeric values forward so holes/mono/codegen
        // stay visible during the exact no-work tail where the operator needs them.
        let private cachedHudNumberOrZeroUnlocked (key: string) =
            match observerHudTelemetryCache.TryGetValue(observerHudTelemetryKey key) with
            | true, v ->
                let mutable parsed = 0L
                if Int64.TryParse(v, &parsed) then v else "0"
            | _ -> "0"

        // MIGRATION: DiagJson lives outside the HUD module, so the Phase 2
        // counters need a typed exported seam instead of calling the private
        // unlocked cache helper directly.  The lookup still locks the HUD
        // state and returns a JSON-ready numeric string.
        type Phase2HudCounterId =
            | Phase2HudCounterHolesPatchedTotal
            | Phase2HudCounterMonoQueueDepth
            | Phase2HudCounterCodegenBytesWritten

        let private phase2HudCounterKey = function
            | Phase2HudCounterHolesPatchedTotal -> "holes_patched_total"
            | Phase2HudCounterMonoQueueDepth -> "mono_queue_depth"
            | Phase2HudCounterCodegenBytesWritten -> "codegen_bytes_written"

        let cachedHudNumberOrZero (counterId: Phase2HudCounterId) =
            lock gate (fun () -> cachedHudNumberOrZeroUnlocked (phase2HudCounterKey counterId))

        let cachedHudTextOrDash (keys: string list) =
            lock gate (fun () ->
                keys
                |> List.tryPick (fun key ->
                    match observerHudTelemetryCache.TryGetValue(observerHudTelemetryKey key) with
                    | true, v when not (String.IsNullOrWhiteSpace v) -> Some v
                    | _ -> None)
                |> function
                   | Some v -> cleanText v
                   | None -> "-")

        let private rememberFieldUnlocked (key: string) (value: string) =
            if not (String.IsNullOrWhiteSpace key) && not (String.IsNullOrWhiteSpace value) then
                observerHudTelemetryCache.[observerHudTelemetryKey key] <- cleanText value

        // MIGRATION: MIGRATION assessment asked for strongest terminal pinning immune
        // to chatter plus an aggregate hard semantic blocker list.  MIGRATION
        // emitted the fields, but the HUD still treated them like ordinary last-line
        // cache entries.  Move the retention policy into typed HUD decisions.
        type StrongestTerminalPinDecisionId =
            | StrongestTerminalPinNoCandidate
            | StrongestTerminalPinPromote
            | StrongestTerminalPinKeepExisting

        let private strongestTerminalPinDecisionText = function
            | StrongestTerminalPinNoCandidate -> "no_candidate"
            | StrongestTerminalPinPromote -> "promote_strongest_terminal"
            | StrongestTerminalPinKeepExisting -> "keep_existing_strongest_terminal"

        type HardSemanticImplAggregationDecisionId =
            | HardSemanticImplAggregationNoCandidate
            | HardSemanticImplAggregationSeed
            | HardSemanticImplAggregationAppend
            | HardSemanticImplAggregationAlreadyKnown

        let private hardSemanticImplAggregationDecisionText = function
            | HardSemanticImplAggregationNoCandidate -> "no_candidate"
            | HardSemanticImplAggregationSeed -> "seed_missing_hard_semantic_impls"
            | HardSemanticImplAggregationAppend -> "append_missing_hard_semantic_impl"
            | HardSemanticImplAggregationAlreadyKnown -> "already_known_missing_hard_semantic_impl"

        // MIGRATION / destructive migration migration phase:
        // Semantic ingress can no longer leak raw console-string matches into HUD
        // authority decisions.  The parser boundary may still inspect legacy text,
        // but every downstream decision consumes this DU, making the not-armed
        // failure a typed payload rather than a textual-contains branch.
        type TerminalFlowIngressLegacyParsed = class end
        type TerminalFlowIngressReducerAdmitted = class end
        type TerminalFlowIngressProjectionRejected = class end

        type TerminalFlowTypedSemanticIngressSurface =
            | TerminalFlowIngressSurfaceRawLegacyJson
            | TerminalFlowIngressSurfaceHudCacheProjection
            | TerminalFlowIngressSurfaceReducerReceipt
            | TerminalFlowIngressSurfaceSyntheticHarness

        type TerminalFlowIngressDecisionReasonId =
            | TerminalFlowIngressNoSemanticIngressPayload
            | TerminalFlowIngressNotArmedWithoutEdgeRef
            | TerminalFlowIngressNotArmedWithoutLiveEdge
            | TerminalFlowIngressNotArmedWithoutQueueEvidence

        type TerminalFlowTypedSemanticIngressDecision =
            | TerminalFlowIngressAdmitToReducer of authorityRef:uint32
            | TerminalFlowIngressKeepProjectionOnly of reason:TerminalFlowIngressDecisionReasonId
            | TerminalFlowIngressRejectAmbiguous of reason:TerminalFlowIngressDecisionReasonId

        type TerminalFlowSemanticIngressEdgeEvidence =
            | TerminalFlowIngressEdgeMissing
            | TerminalFlowIngressEdgeExplicitlyAbsent
            | TerminalFlowIngressEdgeLive of edgeRef:string

        let private terminalFlowSemanticIngressEdgeEvidenceOf (edgeRef:string) =
            if System.String.IsNullOrWhiteSpace edgeRef then TerminalFlowIngressEdgeMissing
            elif System.String.Equals(edgeRef, "Absent", System.StringComparison.OrdinalIgnoreCase)
                 || edgeRef.EndsWith("(Absent)", System.StringComparison.OrdinalIgnoreCase)
                 || edgeRef.EndsWith("=Absent", System.StringComparison.OrdinalIgnoreCase) then
                TerminalFlowIngressEdgeExplicitlyAbsent
            else TerminalFlowIngressEdgeLive edgeRef

        let terminalFlowSemanticIngressEdgeEvidenceText = function
            | TerminalFlowIngressEdgeMissing -> "Missing"
            | TerminalFlowIngressEdgeExplicitlyAbsent -> "ExplicitlyAbsent"
            | TerminalFlowIngressEdgeLive edgeRef -> "Live(" + cleanText edgeRef + ")"

        type TerminalFlowSemanticIngressOwnerAxisId =
            | TerminalFlowIngressOwnerAxisCrossKind

        let terminalFlowSemanticIngressOwnerAxisText = function
            | TerminalFlowIngressOwnerAxisCrossKind -> "cross_kind"

        type TerminalFlowSemanticIngressPhaseId =
            | TerminalFlowIngressPhaseTerminalEligible

        let terminalFlowSemanticIngressPhaseText = function
            | TerminalFlowIngressPhaseTerminalEligible -> "TerminalEligible"

        type TerminalFlowTypedSemanticIngressPayload =
            | TerminalFlowSemanticIngressNone
            | TerminalFlowSemanticIngressNotArmed of edgeEvidence:TerminalFlowSemanticIngressEdgeEvidence * queueDepth:string * ownerAxis:TerminalFlowSemanticIngressOwnerAxisId
            | TerminalFlowSemanticIngressPureTopologyStasis of repeatFloor:int * semanticReceiptId:string
            | TerminalFlowSemanticIngressTerminalEligibleOwnerLatch of phase:TerminalFlowSemanticIngressPhaseId
            | TerminalFlowSemanticIngressOwnerQuorumClosed of quorumRef:string

        type TerminalFlowTypedSemanticIngressEffectPlan =
            | TerminalFlowIngressNoAuthorityMutation
            | TerminalFlowIngressObserveWakerRegistrationDebt of edgeEvidence:TerminalFlowSemanticIngressEdgeEvidence * queueDepth:string * ownerAxis:TerminalFlowSemanticIngressOwnerAxisId
            | TerminalFlowIngressSealTopologyStasis of repeatFloor:int * semanticReceiptId:string
            | TerminalFlowIngressLatchTerminalEligibility of phase:TerminalFlowSemanticIngressPhaseId
            | TerminalFlowIngressCloseOwnerQuorum of quorumRef:string

        let private terminalFlowSemanticIngressEffectPlanOf = function
            | TerminalFlowSemanticIngressNone -> TerminalFlowIngressNoAuthorityMutation
            | TerminalFlowSemanticIngressNotArmed(edgeEvidence, queueDepth, ownerAxis) -> TerminalFlowIngressObserveWakerRegistrationDebt(edgeEvidence, queueDepth, ownerAxis)
            | TerminalFlowSemanticIngressPureTopologyStasis(repeatFloor, semanticReceiptId) -> TerminalFlowIngressSealTopologyStasis(repeatFloor, semanticReceiptId)
            | TerminalFlowSemanticIngressTerminalEligibleOwnerLatch phase -> TerminalFlowIngressLatchTerminalEligibility phase
            | TerminalFlowSemanticIngressOwnerQuorumClosed quorumRef -> TerminalFlowIngressCloseOwnerQuorum quorumRef

        let terminalFlowSemanticIngressEffectPlanText = function
            | TerminalFlowIngressNoAuthorityMutation -> "IngressEffect(NoAuthorityMutation)"
            | TerminalFlowIngressObserveWakerRegistrationDebt(edgeEvidence, queueDepth, ownerAxis) -> FastRuntimeFormat.format "IngressEffect(ObserveWakerRegistrationDebt|edge=%s|queue=%s|axis=%s)" [| box (terminalFlowSemanticIngressEdgeEvidenceText edgeEvidence); box (cleanText queueDepth); box (terminalFlowSemanticIngressOwnerAxisText ownerAxis) |]
            | TerminalFlowIngressSealTopologyStasis(repeatFloor, semanticReceiptId) -> sprintf "IngressEffect(SealTopologyStasis|repeat_floor=%d|semantic_receipt=%s)" repeatFloor (cleanText semanticReceiptId)
            | TerminalFlowIngressLatchTerminalEligibility phase -> sprintf "IngressEffect(LatchTerminalEligibility|phase=%s)" (terminalFlowSemanticIngressPhaseText phase)
            | TerminalFlowIngressCloseOwnerQuorum quorumRef -> sprintf "IngressEffect(CloseOwnerQuorum|quorum=%s)" (cleanText quorumRef)

        let terminalFlowTypedSemanticIngressText = function
            | TerminalFlowSemanticIngressNone -> "SemanticIngress(None)"
            | TerminalFlowSemanticIngressNotArmed(edgeEvidence, queueDepth, ownerAxis) ->
                FastRuntimeFormat.format "SemanticIngress(NotArmed|edge=%s|queue=%s|axis=%s)" [| box (terminalFlowSemanticIngressEdgeEvidenceText edgeEvidence); box (cleanText queueDepth); box (terminalFlowSemanticIngressOwnerAxisText ownerAxis) |]
            | TerminalFlowSemanticIngressPureTopologyStasis(repeatFloor, semanticReceiptId) ->
                sprintf "SemanticIngress(PureTopologyStasis|repeat_floor=%d|semantic_receipt=%s)" repeatFloor (cleanText semanticReceiptId)
            | TerminalFlowSemanticIngressTerminalEligibleOwnerLatch phase ->
                sprintf "SemanticIngress(TerminalEligibleOwnerLatch|phase=%s)" (terminalFlowSemanticIngressPhaseText phase)
            | TerminalFlowSemanticIngressOwnerQuorumClosed quorumRef ->
                sprintf "SemanticIngress(OwnerQuorumClosed|quorum=%s)" (cleanText quorumRef)

        let private terminalFlowLegacyMintedRefOf (kind:string) (payload:string) =
            let value = uint32 (CompilerIdentityKernel.ContentDigest.hash64 (kind + "|" + payload) >>> 32)
            if value = 0u then 1u else value

        let private terminalFlowSemanticIngressRef payload =
            terminalFlowLegacyMintedRefOf
                "terminal_flow_semantic_ingress"
                (terminalFlowTypedSemanticIngressText payload)

        type TerminalFlowTypedSemanticIngressEnvelope<'IngressState> = {
            payload : TerminalFlowTypedSemanticIngressPayload
            ingressRef : uint32
            rawLineRef : uint32
            surface : TerminalFlowTypedSemanticIngressSurface
            decision : TerminalFlowTypedSemanticIngressDecision
            effectPlan : TerminalFlowTypedSemanticIngressEffectPlan
            authorityWitnessRef : uint32
            observedAtMs : int64
        }

        let private terminalFlowIngressDecisionReasonText = function
            | TerminalFlowIngressNoSemanticIngressPayload -> "no_semantic_ingress_payload"
            | TerminalFlowIngressNotArmedWithoutEdgeRef -> "not_armed_without_edge_ref"
            | TerminalFlowIngressNotArmedWithoutLiveEdge -> "not_armed_without_live_edge"
            | TerminalFlowIngressNotArmedWithoutQueueEvidence -> "not_armed_without_queue_evidence"

        let terminalFlowSemanticIngressDecisionText = function
            | TerminalFlowIngressAdmitToReducer authorityRef -> sprintf "IngressDecision(AdmitToReducer|authority_ref=%u)" authorityRef
            | TerminalFlowIngressKeepProjectionOnly reason -> sprintf "IngressDecision(ProjectionOnly|reason=%s)" (terminalFlowIngressDecisionReasonText reason)
            | TerminalFlowIngressRejectAmbiguous reason -> sprintf "IngressDecision(RejectAmbiguous|reason=%s)" (terminalFlowIngressDecisionReasonText reason)

        let terminalFlowSemanticIngressSurfaceText = function
            | TerminalFlowIngressSurfaceRawLegacyJson -> "raw_legacy_json"
            | TerminalFlowIngressSurfaceHudCacheProjection -> "hud_cache_projection"
            | TerminalFlowIngressSurfaceReducerReceipt -> "reducer_receipt"
            | TerminalFlowIngressSurfaceSyntheticHarness -> "synthetic_harness"

        let private terminalFlowIngressEnvelopeDecision payload =
            match payload with
            | TerminalFlowSemanticIngressNone -> TerminalFlowIngressKeepProjectionOnly TerminalFlowIngressNoSemanticIngressPayload
            | TerminalFlowSemanticIngressNotArmed(edgeEvidence, queueDepth, _) ->
                match edgeEvidence with
                | TerminalFlowIngressEdgeMissing -> TerminalFlowIngressRejectAmbiguous TerminalFlowIngressNotArmedWithoutEdgeRef
                | TerminalFlowIngressEdgeExplicitlyAbsent -> TerminalFlowIngressKeepProjectionOnly TerminalFlowIngressNotArmedWithoutLiveEdge
                | TerminalFlowIngressEdgeLive _ when System.String.IsNullOrWhiteSpace queueDepth -> TerminalFlowIngressKeepProjectionOnly TerminalFlowIngressNotArmedWithoutQueueEvidence
                | TerminalFlowIngressEdgeLive _ -> TerminalFlowIngressAdmitToReducer (terminalFlowSemanticIngressRef payload)
            | TerminalFlowSemanticIngressPureTopologyStasis _ -> TerminalFlowIngressAdmitToReducer (terminalFlowSemanticIngressRef payload)
            | TerminalFlowSemanticIngressTerminalEligibleOwnerLatch _ -> TerminalFlowIngressAdmitToReducer (terminalFlowSemanticIngressRef payload)
            | TerminalFlowSemanticIngressOwnerQuorumClosed _ -> TerminalFlowIngressAdmitToReducer (terminalFlowSemanticIngressRef payload)

        type TerminalFlowLegacySemanticProjection = private {
            semanticErrorPayload : string
            edgeRef : string
            queueDepth : string
            semanticReceiptId : string
            repeatCount : int
            factCount : int
            phase : string
            liveGraphPhase : string
            rootPromiseStatus : string
            status : string
            next : string
            openOwnersCount : int option
            ownerDeadlockClosed : bool
            parentContinuationFilled : bool
            parentContinuationFillResult : string
            rootWitnessRecorded : bool
            semanticReceiptBridgeReady : bool
            terminalQuorum : string
            kind : string
        }

        type TerminalFlowLegacyOwnerDebtDeadlineProjection =
            | TerminalFlowOwnerDebtDeadlineNotObserved
            | TerminalFlowOwnerDebtDeadlinePevalTimeout
            | TerminalFlowOwnerDebtDeadlineTieBreakerExhausted

        type TerminalFlowLegacyParentContinuationProjection =
            | TerminalFlowParentContinuationNotObserved
            | TerminalFlowParentContinuationRequired
            | TerminalFlowParentContinuationFilledAwaitingRootWitness
            | TerminalFlowParentContinuationCommitted

        type TerminalFlowOwnerQuorumClosureReasonId =
            | TerminalFlowOwnerQuorumOwnerDeadlockClosedTerminalPrerequisites
            | TerminalFlowOwnerQuorumSemanticDebtQuarantined
            | TerminalFlowOwnerQuorumParentPoisonClosed
            | TerminalFlowOwnerQuorumTerminalClosureRepeatDeadlock
            | TerminalFlowOwnerQuorumDebtDrainZeroDeltaQuarantine
            | TerminalFlowOwnerQuorumDebtDrainZeroDeltaQuarantineExit

        type TerminalFlowLegacyOwnerQuorumProjection =
            | TerminalFlowOwnerQuorumOpen
            | TerminalFlowOwnerQuorumClosed of TerminalFlowOwnerQuorumClosureReasonId

        let private terminalFlowOwnerQuorumClosureReasonText = function
            | TerminalFlowOwnerQuorumOwnerDeadlockClosedTerminalPrerequisites -> "owner_deadlock_closed_terminal_prerequisites"
            | TerminalFlowOwnerQuorumSemanticDebtQuarantined -> "semantic_debt_quarantined"
            | TerminalFlowOwnerQuorumParentPoisonClosed -> "parent_poison_closed"
            | TerminalFlowOwnerQuorumTerminalClosureRepeatDeadlock -> "terminal_closure_repeat_deadlock"
            | TerminalFlowOwnerQuorumDebtDrainZeroDeltaQuarantine -> "owner_debt_drain_zero_delta_quarantine"
            | TerminalFlowOwnerQuorumDebtDrainZeroDeltaQuarantineExit -> "owner_debt_drain_zero_delta_quarantine_exit"

        type TerminalFlowLegacyOwnerDebtProjection = private {
            deadline : TerminalFlowLegacyOwnerDebtDeadlineProjection
            parentContinuation : TerminalFlowLegacyParentContinuationProjection
            ownerQuorum : TerminalFlowLegacyOwnerQuorumProjection
            semanticBridgeCandidate : bool
            projectionRef : uint32
        }

        type TerminalFlowLegacyProjectionHeadId =
            | TerminalFlowLegacyProjectionPevalTimeoutQuorum
            | TerminalFlowLegacyProjectionTieBreakerExhaustedQuorum
            | TerminalFlowLegacyProjectionSemanticDebtQuarantinedQuorum
            | TerminalFlowLegacyProjectionParentPoisonClosedQuorum
            | TerminalFlowLegacyProjectionTerminalClosureRepeatDeadlockQuorum
            | TerminalFlowLegacyProjectionOwnerDebtDrainZeroDeltaQuarantineQuorum
            | TerminalFlowLegacyProjectionOwnerDebtLiveWorkTieBreaker
            | TerminalFlowLegacyProjectionMaterialDeltaLiveGraphDrain
            | TerminalFlowLegacyProjectionRootComplete
            | TerminalFlowLegacyProjectionFillSuccess
            | TerminalFlowLegacyProjectionParentContinuationFillRequired
            | TerminalFlowLegacyProjectionPureTopologyConsumerResult
            | TerminalFlowLegacyProjectionPureTopologyFrontierAdvance
            | TerminalFlowLegacyProjectionRootPromiseResolved
            | TerminalFlowLegacyProjectionOtherHead

        let private terminalFlowLegacyProjectionHeadFor (value:string) =
            let safe = if System.Object.ReferenceEquals(value, null) then "" else value
            let hasHead (head:string) =
                safe.Length >= head.Length
                && System.String.Equals(
                    safe.Substring(0, head.Length),
                    head,
                    System.StringComparison.OrdinalIgnoreCase)
            if hasHead "TerminalQuorum(peval_timeout_after_owner_debt_drain_deadline" then
                TerminalFlowLegacyProjectionPevalTimeoutQuorum
            elif hasHead "TerminalQuorum(owner_debt_live_work_tie_breaker_exhausted" then
                TerminalFlowLegacyProjectionTieBreakerExhaustedQuorum
            elif hasHead "TerminalQuorum(semantic_debt_quarantined" then
                TerminalFlowLegacyProjectionSemanticDebtQuarantinedQuorum
            elif hasHead "TerminalQuorum(parent_poison_closed" then
                TerminalFlowLegacyProjectionParentPoisonClosedQuorum
            elif hasHead "TerminalQuorum(terminal_closure_repeat_deadlock" then
                TerminalFlowLegacyProjectionTerminalClosureRepeatDeadlockQuorum
            elif hasHead "TerminalQuorum(owner_debt_drain_zero_delta_quarantine" then
                TerminalFlowLegacyProjectionOwnerDebtDrainZeroDeltaQuarantineQuorum
            elif hasHead "owner_debt_live_work_tie_breaker" then
                TerminalFlowLegacyProjectionOwnerDebtLiveWorkTieBreaker
            elif hasHead "material_delta_live_graph_drain" then
                TerminalFlowLegacyProjectionMaterialDeltaLiveGraphDrain
            elif hasHead "RootComplete" then
                TerminalFlowLegacyProjectionRootComplete
            elif hasHead "Success" then
                TerminalFlowLegacyProjectionFillSuccess
            elif hasHead "RootPromiseWaiting(parent_continuation_ivar_fill_required" then
                TerminalFlowLegacyProjectionParentContinuationFillRequired
            elif hasHead "ConsumerResultVerdict(RealDelta|fact_kind=pure_topology_witness_semantic_receipt" then
                TerminalFlowLegacyProjectionPureTopologyConsumerResult
            elif hasHead "SemanticFrontierAdvance(Advanced|fact_kind=pure_topology_witness" then
                TerminalFlowLegacyProjectionPureTopologyFrontierAdvance
            elif hasHead "RootPromiseResolved" then
                TerminalFlowLegacyProjectionRootPromiseResolved
            else
                TerminalFlowLegacyProjectionOtherHead

        let private terminalFlowLegacySemanticProjectionOfLine (line:string) =
            let field keys = firstField keys line
            let intField keys =
                match System.Int32.TryParse(field keys : string) with
                | true, value -> value
                | _ -> 0
            let boolField keys =
                match System.Boolean.TryParse(field keys : string) with
                | true, value -> value
                | _ -> false
            let openOwners =
                match System.Int32.TryParse(field ["open_owners_count"] : string) with
                | true, value -> Some value
                | _ -> None
            { semanticErrorPayload = field ["semantic_error_payload"]
              edgeRef = field ["cross_kind_obligation_id"; "cross_kind_close_key"; "native_hopac_waiter_key"]
              queueDepth = field ["queue_depth"; "front_replay_queue"]
              semanticReceiptId = field ["semantic_receipt_id"; "semantic_receipt"; "receipt_id"]
              repeatCount = intField ["same_graph_repeat_count"; "count"]
              factCount = intField ["facts"; "semantic_fact_count"]
              phase = field ["phase"]
              liveGraphPhase = field ["live_graph_phase_du"]
              rootPromiseStatus = field ["root_promise_status_du"; "root_promise_status"]
              status = field ["status"]
              next = field ["next"]
              openOwnersCount = openOwners
              ownerDeadlockClosed = boolField ["owner_deadlock_closed_terminal_prerequisites"]
              parentContinuationFilled = boolField ["parent_continuation_filled"]
              parentContinuationFillResult = field ["parent_continuation_ivar_fill_result_du"]
              rootWitnessRecorded = boolField ["root_witness_recorded"; "root_witness_activity"]
              semanticReceiptBridgeReady = boolField ["semantic_receipt_bridge_ready"]
              terminalQuorum = field ["terminal_quorum_du"; "terminal_quorum"; "owner_close_decision_du"]
              kind = field ["kind"; "event"] }

        let private terminalFlowLegacyOwnerDebtProjectionOfLine (line:string) =
            let projection = terminalFlowLegacySemanticProjectionOfLine line
            let equals expected actual = System.String.Equals(expected, actual, System.StringComparison.OrdinalIgnoreCase)
            let terminalQuorumHead = terminalFlowLegacyProjectionHeadFor projection.terminalQuorum
            let rootPromiseHead = terminalFlowLegacyProjectionHeadFor projection.rootPromiseStatus
            let parentFillHead = terminalFlowLegacyProjectionHeadFor projection.parentContinuationFillResult
            let deadline =
                if equals "terminal_peval_timeout_owner_debt_drain_deadline_exit" projection.kind
                   || terminalQuorumHead = TerminalFlowLegacyProjectionPevalTimeoutQuorum then
                    TerminalFlowOwnerDebtDeadlinePevalTimeout
                elif equals "terminal_owner_debt_live_work_tie_breaker_exhausted_exit" projection.kind
                     || terminalQuorumHead = TerminalFlowLegacyProjectionTieBreakerExhaustedQuorum then
                    TerminalFlowOwnerDebtDeadlineTieBreakerExhausted
                else TerminalFlowOwnerDebtDeadlineNotObserved
            let terminalEligible =
                projection.openOwnersCount = Some 0
                || equals "TerminalEligible" projection.phase
                || equals "TerminalEligible" projection.liveGraphPhase
                || rootPromiseHead = TerminalFlowLegacyProjectionRootComplete
            let parentFillObserved =
                projection.parentContinuationFilled
                || parentFillHead = TerminalFlowLegacyProjectionFillSuccess
                || equals "owner_debt_parent_continuation_filled" projection.kind
            let parentRequired =
                equals "semantic_parent_continuation_cycle_deferred" projection.kind
                || equals "fill_parent_continuation_ivar_immediately" projection.kind
                || equals "parent_continuation_immediate_fill" projection.kind
                || equals "parent_continuation_ivar_fill_required" projection.kind
                || rootPromiseHead = TerminalFlowLegacyProjectionParentContinuationFillRequired
            let rootWitness =
                projection.rootWitnessRecorded
                || equals "root_witness_recorded" projection.kind
                || equals "root_witness_activity" projection.kind
                || terminalEligible
            let parentContinuation =
                if parentFillObserved && rootWitness then TerminalFlowParentContinuationCommitted
                elif parentFillObserved then TerminalFlowParentContinuationFilledAwaitingRootWitness
                elif parentRequired then TerminalFlowParentContinuationRequired
                else TerminalFlowParentContinuationNotObserved
            let ownerQuorum =
                if projection.ownerDeadlockClosed then TerminalFlowOwnerQuorumClosed TerminalFlowOwnerQuorumOwnerDeadlockClosedTerminalPrerequisites
                elif terminalQuorumHead = TerminalFlowLegacyProjectionSemanticDebtQuarantinedQuorum then TerminalFlowOwnerQuorumClosed TerminalFlowOwnerQuorumSemanticDebtQuarantined
                elif terminalQuorumHead = TerminalFlowLegacyProjectionParentPoisonClosedQuorum then TerminalFlowOwnerQuorumClosed TerminalFlowOwnerQuorumParentPoisonClosed
                elif terminalQuorumHead = TerminalFlowLegacyProjectionTerminalClosureRepeatDeadlockQuorum then TerminalFlowOwnerQuorumClosed TerminalFlowOwnerQuorumTerminalClosureRepeatDeadlock
                elif terminalQuorumHead = TerminalFlowLegacyProjectionOwnerDebtDrainZeroDeltaQuarantineQuorum then TerminalFlowOwnerQuorumClosed TerminalFlowOwnerQuorumDebtDrainZeroDeltaQuarantine
                elif equals "terminal_owner_debt_drain_zero_delta_quarantine_exit" projection.kind then TerminalFlowOwnerQuorumClosed TerminalFlowOwnerQuorumDebtDrainZeroDeltaQuarantineExit
                else TerminalFlowOwnerQuorumOpen
            let semanticBridgeCandidate =
                projection.semanticReceiptBridgeReady
                || equals "pure_sidecar_semantic_receipt" projection.kind
                || equals "root_promise_resolved" projection.kind
                || equals "semantic_receipt_live_qap" projection.kind
                || rootPromiseHead = TerminalFlowLegacyProjectionRootPromiseResolved
                || rootPromiseHead = TerminalFlowLegacyProjectionOwnerDebtLiveWorkTieBreaker
                || rootPromiseHead = TerminalFlowLegacyProjectionMaterialDeltaLiveGraphDrain
            let deadlineText =
                match deadline with
                | TerminalFlowOwnerDebtDeadlineNotObserved -> "NotObserved"
                | TerminalFlowOwnerDebtDeadlinePevalTimeout -> "PevalTimeout"
                | TerminalFlowOwnerDebtDeadlineTieBreakerExhausted -> "TieBreakerExhausted"
            let parentContinuationText =
                match parentContinuation with
                | TerminalFlowParentContinuationNotObserved -> "NotObserved"
                | TerminalFlowParentContinuationRequired -> "Required"
                | TerminalFlowParentContinuationFilledAwaitingRootWitness -> "FilledAwaitingRootWitness"
                | TerminalFlowParentContinuationCommitted -> "Committed"
            let ownerQuorumText =
                match ownerQuorum with
                | TerminalFlowOwnerQuorumOpen -> "Open"
                | TerminalFlowOwnerQuorumClosed reason -> "Closed(" + terminalFlowOwnerQuorumClosureReasonText reason + ")"
            { deadline = deadline
              parentContinuation = parentContinuation
              ownerQuorum = ownerQuorum
              semanticBridgeCandidate = semanticBridgeCandidate
              projectionRef =
                terminalFlowLegacyMintedRefOf
                    "terminal_flow_legacy_owner_debt_projection"
                    (deadlineText
                     + "|parent=" + parentContinuationText
                     + "|quorum=" + ownerQuorumText
                     + "|bridge=" + string semanticBridgeCandidate
                     + "|kind=" + cleanText projection.kind
                     + "|terminal_quorum=" + cleanText projection.terminalQuorum) }

        type TerminalFlowLegacyBreakthroughAxesProjection = private {
            ownerClosure : bool
            semanticFactDebt : bool
            projectionRef : uint32
        }

        let private terminalFlowLegacyBreakthroughAxesProjectionOfText (text:string) =
            let equals expected actual = System.String.Equals(expected, actual, System.StringComparison.OrdinalIgnoreCase)
            let tokens =
                if System.String.IsNullOrWhiteSpace text then [||]
                else text.Replace("|", ";").Replace(",", ";").Split([|';'|], System.StringSplitOptions.RemoveEmptyEntries)
            let flag key =
                tokens
                |> Array.exists (fun token ->
                    let parts = token.Trim().Split([|'='|], 2)
                    parts.Length = 2 && equals key (parts.[0].Trim()) && equals "true" (parts.[1].Trim()))
            let ownerClosure = flag "owner_closure"
            let semanticFactDebt = flag "semantic_fact_debt"
            { ownerClosure = ownerClosure
              semanticFactDebt = semanticFactDebt
              projectionRef =
                terminalFlowLegacyMintedRefOf
                    "terminal_flow_legacy_breakthrough_axes"
                    (sprintf "owner_closure=%b|semantic_fact_debt=%b" ownerClosure semanticFactDebt) }

        type TerminalFlowLegacyOwnerDebtBridgeSourceId =
            | TerminalFlowLegacyOwnerDebtLiveWorkTieBreaker
            | TerminalFlowLegacyMaterialDeltaLiveGraphDrain
            | TerminalFlowLegacyRootPromiseResolved
            | TerminalFlowLegacyOwnerDebtBridgeOther

        let private terminalFlowLegacyOwnerDebtBridgeSourceFor (text:string) =
            let head =
                if System.String.IsNullOrWhiteSpace text then ""
                else
                    text.Split([|'|'; ':'; '('|], 2, System.StringSplitOptions.RemoveEmptyEntries)
                    |> Array.tryHead
                    |> Option.defaultValue ""
                    |> fun value -> value.Trim()
            if System.String.Equals(head, "owner_debt_live_work_tie_breaker", System.StringComparison.OrdinalIgnoreCase) then
                TerminalFlowLegacyOwnerDebtLiveWorkTieBreaker
            elif System.String.Equals(head, "material_delta_live_graph_drain", System.StringComparison.OrdinalIgnoreCase) then
                TerminalFlowLegacyMaterialDeltaLiveGraphDrain
            elif System.String.Equals(head, "RootPromiseResolved", System.StringComparison.OrdinalIgnoreCase) then
                TerminalFlowLegacyRootPromiseResolved
            else
                TerminalFlowLegacyOwnerDebtBridgeOther

        let private terminalFlowLegacyOwnerDebtStatusBridgeCandidate (text:string) =
            match terminalFlowLegacyOwnerDebtBridgeSourceFor text with
            | TerminalFlowLegacyOwnerDebtLiveWorkTieBreaker
            | TerminalFlowLegacyMaterialDeltaLiveGraphDrain
            | TerminalFlowLegacyRootPromiseResolved -> true
            | TerminalFlowLegacyOwnerDebtBridgeOther -> false

        let private terminalFlowTypedSemanticIngressOfLine (line:string) =
            if isNull line then TerminalFlowSemanticIngressNone
            else
                let projection = terminalFlowLegacySemanticProjectionOfLine line
                let equals expected actual = System.String.Equals(expected, actual, System.StringComparison.OrdinalIgnoreCase)
                let topologyStasis =
                    equals "pure_topology_witness_semantic_receipt" projection.semanticReceiptId
                    && max projection.repeatCount projection.factCount >= 4
                let terminalEligible =
                    projection.openOwnersCount = Some 0
                    || equals "TerminalEligible" projection.phase
                    || equals "TerminalEligible" projection.liveGraphPhase
                    || equals "RootComplete" projection.rootPromiseStatus
                let ownerQuorumClosed =
                    projection.ownerDeadlockClosed
                    || not (System.String.IsNullOrWhiteSpace projection.terminalQuorum)
                    || equals "terminal_owner_debt_drain_zero_delta_quarantine_exit" projection.kind
                if equals "not_armed" projection.semanticErrorPayload then
                    TerminalFlowSemanticIngressNotArmed(terminalFlowSemanticIngressEdgeEvidenceOf projection.edgeRef, projection.queueDepth, TerminalFlowIngressOwnerAxisCrossKind)
                elif topologyStasis then
                    TerminalFlowSemanticIngressPureTopologyStasis(4, projection.semanticReceiptId)
                elif terminalEligible then
                    TerminalFlowSemanticIngressTerminalEligibleOwnerLatch TerminalFlowIngressPhaseTerminalEligible
                elif ownerQuorumClosed then
                    TerminalFlowSemanticIngressOwnerQuorumClosed (if System.String.IsNullOrWhiteSpace projection.terminalQuorum then "typed-owner-quorum" else projection.terminalQuorum)
                else TerminalFlowSemanticIngressNone

        let private terminalFlowTypedSemanticIngressEnvelopeOfLine line : TerminalFlowTypedSemanticIngressEnvelope<TerminalFlowIngressLegacyParsed> =
            let payload = terminalFlowTypedSemanticIngressOfLine line
            let ingressRef = terminalFlowSemanticIngressRef payload
            let rawLineRef =
                terminalFlowLegacyMintedRefOf
                    "terminal_flow_legacy_raw_line"
                    (if isNull line then "" else line)
            let decision = terminalFlowIngressEnvelopeDecision payload
            let effectPlan = terminalFlowSemanticIngressEffectPlanOf payload
            { payload = payload
              ingressRef = ingressRef
              rawLineRef = rawLineRef
              surface = TerminalFlowIngressSurfaceRawLegacyJson
              decision = decision
              effectPlan = effectPlan
              authorityWitnessRef =
                terminalFlowLegacyMintedRefOf
                    "terminal_flow_semantic_ingress_authority_witness"
                    (terminalFlowTypedSemanticIngressText payload
                     + ":" + terminalFlowSemanticIngressDecisionText decision
                     + ":" + terminalFlowSemanticIngressEffectPlanText effectPlan)
              observedAtMs = System.Environment.TickCount64 }

        let terminalFlowTypedSemanticIngressEnvelopeText (envelope:TerminalFlowTypedSemanticIngressEnvelope<_>) =
            FastRuntimeFormat.format "SemanticIngressEnvelope(ref=%u|raw=%u|surface=%s|decision=%s|effect=%s|authority_ref=%u|observed_at_ms=%d|payload=%s)" [| box envelope.ingressRef; box envelope.rawLineRef; box (terminalFlowSemanticIngressSurfaceText envelope.surface); box (terminalFlowSemanticIngressDecisionText envelope.decision); box (terminalFlowSemanticIngressEffectPlanText envelope.effectPlan); box envelope.authorityWitnessRef; box envelope.observedAtMs; box (terminalFlowTypedSemanticIngressText envelope.payload) |]

        let private typedSemanticIngressPublisherGate = obj()
        let mutable private typedSemanticIngressPublisher : (TerminalFlowTypedSemanticIngressEnvelope<TerminalFlowIngressLegacyParsed> -> unit) option = None
        let private typedSemanticIngressBacklog = ResizeArray<TerminalFlowTypedSemanticIngressEnvelope<TerminalFlowIngressLegacyParsed>>()
        let private typedSemanticIngressExactOnce = System.Collections.Generic.HashSet<uint32>()
        let private typedSemanticIngressWakerObservationWindow = System.Collections.Generic.Dictionary<uint32, int64 * uint32>()

        let installTypedSemanticIngressPublisher publisher =
            let backlog =
                lock typedSemanticIngressPublisherGate (fun () ->
                    typedSemanticIngressPublisher <- Some publisher
                    let pending = typedSemanticIngressBacklog.ToArray()
                    typedSemanticIngressBacklog.Clear()
                    pending)
            backlog |> Array.iter publisher

        let private publishTypedSemanticIngressEnvelope (envelope:TerminalFlowTypedSemanticIngressEnvelope<TerminalFlowIngressLegacyParsed>) =
            match envelope.decision with
            | TerminalFlowIngressAdmitToReducer _ ->
                let shouldPublish =
                    lock typedSemanticIngressPublisherGate (fun () ->
                        match envelope.effectPlan with
                        | TerminalFlowIngressObserveWakerRegistrationDebt _ ->
                            match typedSemanticIngressWakerObservationWindow.TryGetValue envelope.authorityWitnessRef with
                            | true, (lastObservedAtMs, lastRawLineRef)
                                when lastRawLineRef = envelope.rawLineRef
                                  || envelope.observedAtMs - lastObservedAtMs < 30000L -> false
                            | _ ->
                                typedSemanticIngressWakerObservationWindow.[envelope.authorityWitnessRef] <- (envelope.observedAtMs, envelope.rawLineRef)
                                true
                        | _ -> typedSemanticIngressExactOnce.Add envelope.authorityWitnessRef)
                if shouldPublish then
                    let publisher =
                        lock typedSemanticIngressPublisherGate (fun () ->
                            match typedSemanticIngressPublisher with
                            | Some publisher -> Some publisher
                            | None ->
                                typedSemanticIngressBacklog.Add envelope
                                None)
                    match publisher with
                    | Some publisher -> publisher envelope
                    | None ->
                        rememberFieldUnlocked "semantic_ingress_reducer_buffered" "true"
                        rememberFieldUnlocked "semantic_ingress_reducer_buffered_ref" (string envelope.authorityWitnessRef)
                else
                    rememberFieldUnlocked "semantic_ingress_reducer_coalesced" "true"
                    rememberFieldUnlocked "semantic_ingress_reducer_coalesced_ref" (string envelope.authorityWitnessRef)
            | _ -> ()

        let rec private rememberTypedSemanticIngressEnvelopeUnlocked (envelope:TerminalFlowTypedSemanticIngressEnvelope<TerminalFlowIngressLegacyParsed>) =
            match envelope.decision with
            | TerminalFlowIngressAdmitToReducer authorityRef ->
                rememberFieldUnlocked "semantic_ingress_envelope_du" (terminalFlowTypedSemanticIngressEnvelopeText envelope)
                rememberFieldUnlocked "semantic_ingress_decision_du" (terminalFlowSemanticIngressDecisionText envelope.decision)
                rememberFieldUnlocked "semantic_ingress_effect_du" (terminalFlowSemanticIngressEffectPlanText envelope.effectPlan)
                rememberFieldUnlocked "semantic_ingress_authority_ref" (string authorityRef)
                rememberFieldUnlocked "semantic_ingress_raw_line_ref" (string envelope.rawLineRef)
                rememberFieldUnlocked "semantic_ingress_surface_du" (terminalFlowSemanticIngressSurfaceText envelope.surface)
            | TerminalFlowIngressKeepProjectionOnly reason ->
                rememberFieldUnlocked "semantic_ingress_decision_du" (terminalFlowSemanticIngressDecisionText envelope.decision)
                rememberFieldUnlocked "semantic_ingress_projection_only_reason" (terminalFlowIngressDecisionReasonText reason)
            | TerminalFlowIngressRejectAmbiguous reason ->
                rememberFieldUnlocked "semantic_ingress_decision_du" (terminalFlowSemanticIngressDecisionText envelope.decision)
                rememberFieldUnlocked "semantic_ingress_rejection_reason" (terminalFlowIngressDecisionReasonText reason)
            publishTypedSemanticIngressEnvelope envelope
            rememberTypedSemanticIngressUnlocked envelope.payload

        and rememberTypedSemanticIngressUnlocked payload =
            match payload with
            | TerminalFlowSemanticIngressNone -> ()
            | TerminalFlowSemanticIngressNotArmed(edgeEvidence, queueDepth, ownerAxis) ->
                rememberFieldUnlocked "semantic_ingress_payload_du" (terminalFlowTypedSemanticIngressText payload)
                rememberFieldUnlocked "semantic_ingress_ref" (string (terminalFlowSemanticIngressRef payload))
                rememberFieldUnlocked "hopac_ivar_registry_state" "IvarRegistry(NotArmed|typed_ingress_authority_violation|requires_registered_waker_before_wait_or_typed_quarantine)"
                rememberFieldUnlocked "cross_kind_waker_edge" (terminalFlowSemanticIngressEdgeEvidenceText edgeEvidence)
                rememberFieldUnlocked "qap_queue_depth" queueDepth
                rememberFieldUnlocked "owner_axis_id" (terminalFlowSemanticIngressOwnerAxisText ownerAxis)
                rememberFieldUnlocked "owner_axis_authority_violation_du" "OwnerDrainAuthorityViolation(WaitWithoutRegisteredWaker|edge=cross_kind|source=typed_semantic_ingress)"
                rememberFieldUnlocked "owner_axis_receipt_consumption_du" "OwnerAxisReceiptConsumption(RejectedByLease|lease=missing_waker_edge|reason=not_armed|source=typed_semantic_ingress)"
                rememberFieldUnlocked "root_writer_handoff_instruction_du" "RootWriterFailClosedAfterViolation(WaitWithoutRegisteredWaker)"
                rememberFieldUnlocked "scheduler_owned_root_transition_du" "SchedulerRootFailClosedAfterOwnerDeadlock(axis=cross_kind|missing_waker=true)"
                rememberFieldUnlocked "root_complete_alt_authority_du" "RootCompleteAltAuthority(id=root-complete-alt:not-armed-cross-kind|receipt=terminal-root-receipt:not-armed-cross-kind|kind=owner_deadlock|writer_required=false|owner_blocker=cross_kind)"
                rememberFieldUnlocked "terminal_root_receipt_gate_du" "TerminalRootReceiptGate(id=terminal-root-gate:not-armed-cross-kind|root_consumed=true|writer_consumed=true|commit_allowed=true|fail_closed_ms=0)"
                rememberFieldUnlocked "build_error_trace_authority_du" "BuildErrorTraceAuthority(trace=not-armed-cross-kind|code=EJP0032|root_owned=true|durable_before_exit=true|raw_console_suppressed=true)"
                rememberFieldUnlocked "root_terminal_outcome_du" "RootTerminalOutcome(FailedClosed|reason=WaitWithoutRegisteredWaker)"
                rememberFieldUnlocked "owner_axis_drain_decision_du" "OwnerAxisDrainDecision(ForceCloseResidualUnderBoundWriter|source=live_owner_ledger|authoritative=true|requires_owner_close_receipt=true)"
                rememberFieldUnlocked "owner_debt_still_open_reason_du" "OwnerDebtStillOpen(NotArmedCrossKindWaker|axis=cross_kind|round2_typed_ingress_requires_waker_registration)"
            | TerminalFlowSemanticIngressPureTopologyStasis(_, semanticReceiptId) ->
                rememberFieldUnlocked "semantic_ingress_payload_du" (terminalFlowTypedSemanticIngressText payload)
                rememberFieldUnlocked "semantic_ingress_ref" (string (terminalFlowSemanticIngressRef payload))
                rememberFieldUnlocked "topology_stasis_seal_du" "PureSidecarTopologyStasisSeal(axis=sidecar_drain|threshold=4|debt_payment_allowed=true|waker=registered_before_yield|authority=scheduler_owned_not_renderer)"
                rememberFieldUnlocked "same_topology_repeat_count" "4_plus"
                rememberFieldUnlocked "topology_stasis_threshold" "4"
                rememberFieldUnlocked "material_delta_vs_topology_only" "topology_stasis_sealed_semantic_debt_payment"
                rememberFieldUnlocked "owner_axis_id" "sidecar_drain"
                rememberFieldUnlocked "semantic_receipt_id" semanticReceiptId
                rememberFieldUnlocked "cross_kind_waker_edge" "semantic-sidecar-waker:sidecar_drain:registered_before_yield"
                rememberFieldUnlocked "hopac_ivar_registry_state" "IvarRegistry(ArmedByTopologyStasisSeal|state=FullOrAwaitingWriterCapability)"
            | TerminalFlowSemanticIngressTerminalEligibleOwnerLatch phase ->
                rememberFieldUnlocked "semantic_ingress_payload_du" (terminalFlowTypedSemanticIngressText payload)
                rememberFieldUnlocked "semantic_ingress_ref" (string (terminalFlowSemanticIngressRef payload))
                rememberFieldUnlocked "owner_terminal_eligible_latched" "true"
                rememberFieldUnlocked "live_graph_phase_du" (terminalFlowSemanticIngressPhaseText phase + "StickyLatch")
                rememberFieldUnlocked "owner_debt_still_open_reason_du" "OwnerDebtNotOpen(TerminalEligibleLatchSticky|source=typed_semantic_ingress)"
            | TerminalFlowSemanticIngressOwnerQuorumClosed quorumRef ->
                rememberFieldUnlocked "semantic_ingress_payload_du" (terminalFlowTypedSemanticIngressText payload)
                rememberFieldUnlocked "semantic_ingress_ref" (string (terminalFlowSemanticIngressRef payload))
                rememberFieldUnlocked "typed_owner_quorum_closed_ref" quorumRef
                rememberFieldUnlocked "typed_owner_quorum_closed_authority" "typed_semantic_ingress"

