        let private replayAmplificationVerdictFor sampledWork replayScheduled replayDelta frontierAuthority =
            if frontierAuthority = PendingFrontierUnavailableQuarantined && replayDelta > 0L then ReplayAmplificationFrontierUnavailable
            elif replayScheduled > max 256L (sampledWork * 2L) then ReplayAmplificationProceduralDominant
            else ReplayAmplificationNominal

