        let private hudRankOrZero (value: string) =
            let mutable parsed = 0L
            if Int64.TryParse(value, &parsed) then parsed else 0L

        let private rememberStrongestTerminalUnlocked (line: string) =
            let rankText = firstField ["strongest_terminal_rank"; "terminal_rank"; "rank"] line
            let statusText = firstField ["strongest_terminal_status"; "terminal_status"; "status"] line
            let decisionId =
                if String.IsNullOrWhiteSpace rankText || String.IsNullOrWhiteSpace statusText then StrongestTerminalPinNoCandidate
                else
                    let nextRank = hudRankOrZero rankText
                    let currentRank =
                        match observerHudTelemetryCache.TryGetValue(observerHudTelemetryKey "strongest_terminal_rank") with
                        | true, v -> hudRankOrZero v
                        | _ -> 0L
                    if nextRank >= currentRank then StrongestTerminalPinPromote else StrongestTerminalPinKeepExisting
            match decisionId with
            | StrongestTerminalPinPromote ->
                rememberFieldUnlocked "strongest_terminal_rank" rankText
                rememberFieldUnlocked "strongest_terminal_status" statusText
                rememberFieldUnlocked "strongest_terminal_reason" (firstField ["strongest_terminal_reason"; "reason"] line)
                rememberFieldUnlocked "strongest_terminal_site" (firstField ["strongest_terminal_site"; "terminal_site"; "site"] line)
            | _ -> ()
            rememberFieldUnlocked "strongest_terminal_pin_decision_du" (strongestTerminalPinDecisionText decisionId)

        let private rememberHardSemanticImplsUnlocked (line: string) =
            let semanticPolicy = firstField ["semantic_terminal_policy_du"] line
            let eligibility = firstField ["terminal_deferral_eligibility_du"] line
            let opName = firstField ["op_impl_name"; "missing_dependency_target"] line
            let opSig = firstField ["op_impl_signature"; "missing_hard_semantic_impls"] line
            let isHard =
                semanticPolicy = "hard_authoring_blocker"
                || eligibility = "hard_semantic_terminal_not_deferrable_by_live_replay"
            let candidate =
                if not (String.IsNullOrWhiteSpace opSig) then opSig
                elif not (String.IsNullOrWhiteSpace opName) then opName
                else ""
            let candidateWasAdded =
                isHard
                && not (String.IsNullOrWhiteSpace candidate)
                && hardSemanticImplSet.Add(
                    CompilerIdentityKernel.ContentDigest.ofText "hard-semantic-impl" candidate)
            let decisionId =
                if not isHard || String.IsNullOrWhiteSpace candidate then HardSemanticImplAggregationNoCandidate
                elif not candidateWasAdded then HardSemanticImplAggregationAlreadyKnown
                else
                    match observerHudTelemetryCache.TryGetValue(observerHudTelemetryKey "missing_hard_semantic_impls") with
                    | false, _ -> HardSemanticImplAggregationSeed
                    | true, current when String.IsNullOrWhiteSpace current -> HardSemanticImplAggregationSeed
                    | true, _ -> HardSemanticImplAggregationAppend
            match decisionId with
            | HardSemanticImplAggregationSeed ->
                rememberFieldUnlocked "missing_hard_semantic_impls" candidate
            | HardSemanticImplAggregationAppend ->
                let current =
                    match observerHudTelemetryCache.TryGetValue(observerHudTelemetryKey "missing_hard_semantic_impls") with
                    | true, v -> v
                    | _ -> ""
                let next = if current.Length > 180 then current else current + " + " + candidate
                rememberFieldUnlocked "missing_hard_semantic_impls" next
            | _ -> ()
            rememberFieldUnlocked "hard_semantic_impl_aggregation_du" (hardSemanticImplAggregationDecisionText decisionId)

        let private renderHudPhaseUnlocked (phaseId: HudPaintPhaseId) =
            if supportsHud() && hudLines.Length > 0 then
                rememberFieldUnlocked "hud_paint_phase_du" (hudPaintPhaseText phaseId)
                renderHudUnlocked()

