                let nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                let cpuMs = p.TotalProcessorTime.TotalMilliseconds
                let wallDeltaMs =
                    if hudRealtimeLastMs > 0L then max 1L (nowMs - hudRealtimeLastMs)
                    else 0L
                let cpuDeltaMs =
                    if hudRealtimeLastMs > 0L then max 0.0 (cpuMs - hudRealtimeLastCpuMs)
                    else 0.0
                hudRealtimeLastMs <- nowMs
                hudRealtimeLastCpuMs <- cpuMs
                let procPct =
                    if wallDeltaMs > 0L then (cpuDeltaMs / float wallDeltaMs) * 100.0
                    else 0.0
                let machinePct =
                    let cores = max 1 Environment.ProcessorCount
                    procPct / float cores
                rememberFieldUnlocked "hud_cpu_core_equiv" ((procPct / 100.0).ToString("F3", CultureInfo.InvariantCulture))
                rememberFieldUnlocked "hud_proc_cpu_pct" (procPct.ToString("F2", CultureInfo.InvariantCulture))
                rememberFieldUnlocked "hud_proc_cpu_machine_pct" (machinePct.ToString("F2", CultureInfo.InvariantCulture))
                rememberFieldUnlocked "hud_mem_ws_bytes" (string p.WorkingSet64)
                rememberFieldUnlocked "hud_mem_private_bytes" (string p.PrivateMemorySize64)
                rememberFieldUnlocked "hud_mem_managed_bytes" (string (GC.GetTotalMemory(false)))
            with _ -> ()


        let private appendHudSummaryUnlocked (rows: string array) =
            if appendHudEnabled() && rows.Length > 0 then
                let summary =
                    rows
                    |> Array.map cleanText
                    |> String.concat " || "
                    |> trimTo 2048
                Console.Error.WriteLine("[spiral_hud] " + summary)

        let updateHudText (line: string) (panel: string) =
            try
                let panelLines =
                    if String.IsNullOrWhiteSpace panel then [||]
                    else panel.Replace("\r", "").Split('\n') |> Array.filter (fun x -> not (String.IsNullOrWhiteSpace x))
                let rows = ResizeArray<string>()
                rows.Add(line)
                for p in panelLines do
                    if rows.Count < hudRows then rows.Add("[spiral] | " + p)
                withLock (fun () ->
                    installHudLinesUnlocked (rows.ToArray())
                    renderHudUnlocked())
            with ex -> emitHudExceptionUnlocked "updateHudText" line ex

        let refreshProgressJsonLine (line: string) =
            if not (Object.ReferenceEquals(line, null)) then
                try
                    withLock (fun () ->
                        rememberFieldUnlocked "hud_paint_phase_du" (hudPaintPhaseText HudPaintPreLogAppend)
                        if supportsHud() && hudLines.Length > 0 then
                            renderHudPhaseUnlocked HudPaintPreLogAppend)
                with ex -> emitHudExceptionUnlocked "refreshProgressJsonLine" line ex

        let writeProgressJsonLine (line: string) =
            if not (Object.ReferenceEquals(line, null)) then
                try
                    withLock (fun () ->
                        let kind = jsonScalarField "kind" line
                        // Canonical JSONL is a sink only.  It cannot install HUD rows,
                        // update cached fields or reconstruct any terminal predecessor.
                        writeLineUnlocked line
                        if kind = "run_end" then
                            completeWindowsTaskbarForRequest (TaskbarRequestSucceeded(TaskbarRunEndBoundary, 0))
                            requestFooterCommit ())
                with ex ->
                    emitHudExceptionUnlocked "writeProgressJsonLine" line ex

        // MIGRATION: smooth frames repaint the 15 typed authority rows while
        // semantic events refresh the aligned lower flex-grid. JSON never owns
        // progress or terminal completion.
        type private ProgressHudVisibleFrameHealth =
            | ProgressHudVisibleFrameHealthy
            | ProgressHudVisibleFrameFaulted of
                exceptionType:string *
                message:string

        type private ProgressHudVisibleFrameObservation =
            | ProgressHudVisibleFramePainted
            | ProgressHudVisibleFrameNoVisualDelta
            | ProgressHudVisibleFramePaintFailed of
                exceptionType:string *
                message:string

        let private progressHudVisibleFrameHealthText = function
            | ProgressHudVisibleFrameHealthy -> "none"
            | ProgressHudVisibleFrameFaulted(exceptionType, message) ->
                exceptionType + ":" + message

        let private progressHudVisibleFrameGate = obj()
        let mutable private progressHudVisibleFrameCount = 0L
        let mutable private progressHudNoVisualDeltaFrameCount = 0L
        let mutable private progressHudVisibleFrameLastMs = 0L
        let mutable private progressHudEffectiveFrameLastMs = 0L
        let mutable private progressHudVisibleFrameHealth =
            ProgressHudVisibleFrameHealthy
        // Diff state is declared beside the shared console compositor so log writes
        // can invalidate stale row caches before the next smooth frame.

        let private recordProgressHudVisibleFrame observation =
            lock progressHudVisibleFrameGate (fun () ->
                let observedAtMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                match observation with
                | ProgressHudVisibleFramePainted ->
                    progressHudVisibleFrameCount <- progressHudVisibleFrameCount + 1L
                    progressHudVisibleFrameLastMs <- observedAtMs
                    progressHudEffectiveFrameLastMs <- observedAtMs
                    progressHudVisibleFrameHealth <- ProgressHudVisibleFrameHealthy
                | ProgressHudVisibleFrameNoVisualDelta ->
                    progressHudNoVisualDeltaFrameCount <- progressHudNoVisualDeltaFrameCount + 1L
                    progressHudEffectiveFrameLastMs <- observedAtMs
                    progressHudVisibleFrameHealth <- ProgressHudVisibleFrameHealthy
                | ProgressHudVisibleFramePaintFailed(exceptionType, message) ->
                    progressHudVisibleFrameHealth <-
                        ProgressHudVisibleFrameFaulted(exceptionType, message))

        let progressHudVisibleFrameSnapshot () =
            lock progressHudVisibleFrameGate (fun () ->
                progressHudVisibleFrameCount,
                progressHudNoVisualDeltaFrameCount,
                progressHudVisibleFrameLastMs,
                progressHudEffectiveFrameLastMs,
                progressHudVisibleFrameHealthText progressHudVisibleFrameHealth)

        let private writeProgressHudVisible (text: string) =
            try
                let writer, lane = progressHudWriterAndLane()
                let flushPolicy = progressHudFlushPolicyFor lane
                lock progressHudConsoleWriteGate (fun () ->
                    // The split and frame are one transaction on stderr. Console
                    // diagnostics cannot interleave with cursor movement anymore.
                    if supportsHud() then installSplitUnlocked()
                    writer.Write(text)
                    match flushPolicy with
                    | ProgressHudFlushRedirectedEachFrame -> writer.Flush()
                    | ProgressHudFlushBuffered -> ())
                recordProgressHudVisibleFrame ProgressHudVisibleFramePainted
                true
            with ex ->
                recordProgressHudVisibleFrame (
                    ProgressHudVisibleFramePaintFailed(
                        ex.GetType().Name,
                        ex.Message))
                false

        let private reducerHudFlexLines nowMs (snapshot:ReducerHudSnapshot) =
            let ageMs = max 0L (nowMs - snapshot.snapshotMs)
            let elapsedMs = max 0L (snapshot.elapsedMsAtSnapshot + ageMs)
            let etaP50AtSnapshotMs = reducerHudEtaP50Ms snapshot
            let etaMs = if etaP50AtSnapshotMs < 0L then -1L else max 0L (etaP50AtSnapshotMs - ageMs)
            let compileProgressPct = if snapshot.work.semantic.totalMid <= 0L then 0.0 else 100.0 * float snapshot.work.semantic.retiredCost / float snapshot.work.semantic.totalMid
            let outcomeId =
                match snapshot.possession with
                | ReducerHudPossessionFailedClosed -> ReducerHudOutcomeFailedClosed
                | _ -> reducerHudOutcomeId (not (String.IsNullOrWhiteSpace snapshot.runEndReceiptRef)) snapshot.exitCode
            let terminalProtocolOpen =
                outcomeId = ReducerHudOutcomeOpen
                && snapshot.phase = ReducerHudTerminalizing
                && (match snapshot.possession with
                    | ReducerHudPossessionSealed
                    | ReducerHudPossessionFailedClosed -> false
                    | _ -> true)
            let terminalProgressPct =
                match snapshot.phase with
                | ReducerHudComplete -> 100.0
                | _ -> min 99.0 (max compileProgressPct (float snapshot.work.midBp / 100.0))
            let elapsedText = sprintf "%.3fs" (float elapsedMs / 1000.0)
            let etaText =
                if terminalProtocolOpen then "terminal_protocol_open"
                elif etaMs < 0L then "unavailable"
                else sprintf "%.3fs" (float etaMs / 1000.0)
            let totalText =
                if terminalProtocolOpen then "terminal_protocol_open"
                elif etaMs < 0L then "unavailable"
                else sprintf "%.3fs" (float (elapsedMs + etaMs) / 1000.0)
            let blockers =
                if List.isEmpty snapshot.blockers && terminalProtocolOpen then "terminal_protocol_open"
                elif List.isEmpty snapshot.blockers then "none"
                else snapshot.blockers |> List.map reducerHudBlockerText |> String.concat ","
            let discoveryText = match snapshot.discovery with | ReducerHudDiscoveryClosed -> "closed" | ReducerHudDiscoveryOpen reserve -> sprintf "open:%d" reserve
            let crossKindText = match snapshot.crossKind with | ReducerHudCrossKindClear -> "clear" | ReducerHudCrossKindLive count -> sprintf "live:%d" count
            let poisonText = match snapshot.cyclePoison with | ReducerHudCyclePoisonClear -> "clear" | ReducerHudCyclePoisonSuspected repeats -> sprintf "suspected:%d" repeats | ReducerHudCyclePoisonQuarantined receipt -> sprintf "quarantined:%u" receipt
            let hotNodeText = match snapshot.hotNode with | ReducerHudHotNodeUnknown -> "unknown" | ReducerHudHotNodeKnown(nodeId,path,line,kind,queue) -> FastRuntimeFormat.format "%s:%d %s %s q=%d" [| box path; box line; box nodeId; box kind; box queue |]
            let core = [|
                hudRule "SPIRAL LIVE FLEX-GRID / REDUCER AUTHORITY"
                hudFlex4 (hudKv "terminal" (sprintf "%.6f%%" terminalProgressPct)) (hudKv "work" (sprintf "%.6f%%" compileProgressPct)) (hudKv "elapsed" elapsedText) (hudKv "eta" etaText)
                hudFlex4 (hudKv "sem_retired" (string snapshot.work.semantic.retiredCost)) (hudKv "sem_total_mid" (string snapshot.work.semantic.totalMid)) (hudKv "sem_discovered" (string snapshot.work.semantic.discoveredCost)) (hudKv "sem_reserve_p50" (string snapshot.work.semantic.reserveP50Cost))
                hudFlex4 (hudKv "ast_completed" (string snapshot.work.ast.completedCost)) (hudKv "ast_total" (string snapshot.work.ast.totalCost)) (hudKv "ast_discovered" (string snapshot.work.ast.discoveredCost)) (hudKv "ast_exact" (string snapshot.work.ast.exact))
                hudFlex4 (hudKv "known_rem" (string snapshot.work.semantic.knownRemainingCost)) (hudKv "blocked" (string snapshot.work.semantic.blockedCost)) (hudKv "seed_gap" (string snapshot.work.semantic.reserveP50Cost)) (hudKv "band" (sprintf "%.2f..%.2f" (float snapshot.work.lowBp / 100.0) (float snapshot.work.highBp / 100.0)))
                hudFlex4 (hudKv "rate_phase" (reducerHudProgressPhaseText snapshot.rates.phase)) (hudKv "rate_short" (sprintf "%.3f" snapshot.rates.shortSemanticCostPerSecond)) (hudKv "rate_medium" (sprintf "%.3f" snapshot.rates.mediumSemanticCostPerSecond)) (hudKv "rate_session" (sprintf "%.3f" snapshot.rates.sessionSemanticCostPerSecond))
                hudFlex4
                    (hudKv "eta_p50_ms" (if terminalProtocolOpen then "unavailable_terminal_protocol" else string (reducerHudEtaP50Ms snapshot)))
                    (hudKv "eta_p90_ms" (if terminalProtocolOpen then "unavailable_terminal_protocol" else string (reducerHudEtaP90Ms snapshot)))
                    (hudKv "sigma_ms" (if terminalProtocolOpen then "unavailable_terminal_protocol" else string (reducerHudEtaSigmaMs snapshot)))
                    (hudKv "confidence" (if terminalProtocolOpen then "unavailable" else sprintf "%.3f" snapshot.rates.confidence))
                hudFlex4
                    (hudKv "cpu_exclusive_ms"
                        ((snapshot.timing.cpuExclusiveMs |> Option.map string |> Option.defaultValue "unavailable")
                         + "|" + reducerHudCpuAuthorityText snapshot.timing.cpuAuthority))
                    (hudKv "wall_inclusive_ms" (string snapshot.timing.wallInclusiveMs))
                    (hudKv "queue_ms" (string snapshot.timing.queueDelayMs))
                    (hudKv "blocked_child_ms" (string snapshot.timing.blockedOnChildMs))
                hudFlex4 (hudKv "phase" (reducerHudProgressPhaseText snapshot.phase)) (hudKv "discovery" discoveryText) (hudKv "age_ms" (string ageMs)) (hudKv "generation" (string snapshot.generation))
                hudFlex4 (hudKv "possession" (reducerHudPossessionText snapshot.possession)) (hudKv "actor" snapshot.actorRef) (hudKv "stage_token" snapshot.stageTokenRef) (hudKv "fill" snapshot.fillReceiptRef)
                hudFlex2 ("run_end=" + trimTo 48 snapshot.runEndReceiptRef) ("blockers=" + trimTo 55 blockers)
                hudFlex2
                    ("hot_node=" + trimTo 48 hotNodeText)
                    (sprintf "critical=%s parallel=%.2f"
                        (reducerHudCriticalPathText snapshot.eta.criticalPath)
                        snapshot.eta.effectiveParallelism)
                hudFlex4 (hudKv "cross_kind" crossKindText) (hudKv "cycle_poison" poisonText) (hudKv "variance" (sprintf "%.4f" snapshot.rates.variance)) (hudKv "samples" (string snapshot.rates.samples))
                hudFlex4
                    (hudKv "taskbar" (
                        windowsTaskbarOperationalStatusText windowsTaskbarStatus
                        + "|presentation_owner="
                        + windowsTaskbarPresentationOwnerText windowsTaskbarPresentationOwnerStatus))
                    (hudKv "authority" "reducer_snapshot")
                    (hudKv "denominator" (match snapshot.discovery with | ReducerHudDiscoveryClosed -> "exact" | _ -> "open"))
                    (hudKv "cadence" "50ms")
                hudRule "SEMANTIC / SCHEDULER / GRAPH FLEX-GRID"
                hudFlex2 "upper_rows=typed_non_reparsed" "lower_rows=semantic_observer_only_no_completion_authority"
                hudRule "LIVE DIAGNOSTIC BOARD"
                hudFlex2 ("terminal_snapshot=" + trimTo 46 snapshot.terminalSnapshotRef) ("operational_graph=" + trimTo 46 snapshot.operationalGraphRef)
                hudFlex2 ("runtime_authority=" + trimTo 46 snapshot.runtimeAuthorityRef) "qap_runtime_contract=bound"
                hudFlex4 (hudKv "operational_rev" (string snapshot.operationalRevision)) (hudKv "semantic_epoch" (string snapshot.semanticEpoch)) (hudKv "qap_generation" snapshot.qapGenerationRef) (hudKv "qap_stage" (reducerHudQapStageText snapshot.qapStage))
                hudFlex4 (hudKv "commit" snapshot.commitReceiptRef) (hudKv "done" snapshot.doneReceiptRef) (hudKv "run_end" snapshot.runEndReceiptRef) (hudKv "physical_exit" snapshot.physicalExitReceiptRef)
                hudFlex4 (hudKv "exit_code" (snapshot.exitCode |> Option.map string |> Option.defaultValue "open")) (hudKv "sealed_at_ms" (snapshot.sealedAtMs |> Option.map string |> Option.defaultValue "open")) (hudKv "snapshot_age_ms" (string ageMs)) (hudKv "snapshot_generation" (string snapshot.generation))
                hudRule "SINGLE IMMUTABLE TERMINAL SNAPSHOT"
                hudFlex2 "jsonl=sink_only" "hud=no_json_reparse"
                hudFlex2 "writer=derived_from_reducer" "artifact=derived_from_reducer"
                hudFlex2 "run_end=typed_total_order" "physical_exit=typed_total_order"
                hudFlex2 "qap=bound_to_operational_revision" "progress=bound_to_semantic_epoch"
                hudRule "MIGRATION DEBT CLOSED AT LIVE AUTHORITY"
            |]
            Array.init hudRows (fun index ->
                if index < core.Length then core.[index]
                else
                    hudFlex4
                        (hudKv "slot" (string index))
                        (hudKv "terminal_snapshot" (trimTo 18 snapshot.terminalSnapshotRef))
                        (hudKv "qap" (reducerHudQapStageText snapshot.qapStage))
                        (hudKv "authority" "immutable_reducer"))

        let private paintReducerHudSnapshotDirect nowMs =
            // Restore the proven smooth-clock contract: the dedicated 50ms ticker
            // renders against the immutable reducer snapshot on every frame. The
            // row diff keeps terminal IO proportional to what changed, so elapsed
            // and ETA remain visibly live without repainting the full 50-row board.
            match readReducerHudProjection () with
            | None -> false
            | Some snapshot ->
                let width = safeWidth()
                let start = hudStartRow0()
                let renderedLines =
                    reducerHudFlexLines nowMs snapshot
                    |> Array.map (fitLine width)
                let frame, changedCount =
                    lock progressHudDiffGate (fun () ->
                        let invalidate =
                            progressHudLastRenderedWidth <> width
                            || progressHudLastRenderedStart <> start
                            || progressHudLastRenderedLines.Length <> renderedLines.Length
                        let changed = ResizeArray<int * string>()
                        for i = 0 to renderedLines.Length - 1 do
                            if invalidate || progressHudLastRenderedLines.[i] <> renderedLines.[i] then
                                changed.Add((i, renderedLines.[i]))
                        progressHudLastRenderedLines <- Array.copy renderedLines
                        progressHudLastRenderedWidth <- width
                        progressHudLastRenderedStart <- start
                        let paintRow (i, text) = FastRuntimeFormat.format "%s%d;1H%s2K%s" [| box esc; box (start + i + 1); box esc; box text |]
                        let body = changed |> Seq.map paintRow |> String.concat ""
                        let frame = esc + "?25l" + esc + "s" + body + esc + "u" + esc + "?25h"
                        frame, changed.Count)
                if changedCount = 0 then
                    recordProgressHudVisibleFrame ProgressHudVisibleFrameNoVisualDelta
                    true
                else
                    let painted = writeProgressHudVisible frame
                    if not painted then
                        invalidateProgressHudDiffCache ()
                    painted

        let tryPaintReducerHudSnapshotNow () =
            let nowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            try paintReducerHudSnapshotDirect nowMs
            with ex ->
                recordProgressHudVisibleFrame (
                    ProgressHudVisibleFramePaintFailed(
                        ex.GetType().Name,
                        ex.Message))
                false

        let refreshProgressJsonLineNonBlocking (_line: string) =
            // Semantic JSON publishers are observer-only and never trigger console paint.
            // The dedicated 50 ms ticker is the sole visible-frame authority and renders
            // directly from the immutable reducer projection.
            ()

        let writeProgressJsonLineNonBlocking (line: string) =
            if not (Object.ReferenceEquals(line, null)) then
                try
                    let wrote =
                        tryWithLock 1 (fun () ->
                            // Health/start receipts are JSONL telemetry only. They never
                            // replace the typed authority rows or mint flex-grid completion.
                            writeLineUnlocked line)
                    if not wrote then
                        // A busy semantic gate may delay heartbeat narration, but it must
                        // never bypass the shared console compositor and overwrite HUD rows.
                        // Preserve the evidence in the one durable JSONL only.
                        appendFileLogLineSerialized line
                with ex ->
                    emitHudExceptionUnlocked "writeProgressJsonLineNonBlocking" line ex

        // Destructive migration: one actor owns every durable JSONL
        // append. The old busy-mux fallback opened a second FileStream and could
        // interleave bytes with the primary StreamWriter. That state is now
        // unrepresentable: callers submit a request and receive one durable ack.
        type DurableJsonWriteKind =
            | DurableTerminalReceipt
            | DurableRunEndReceipt

        [<Struct>]
        type DurableJsonLineRef = private DurableJsonLineRef of string

        type DurableJsonCompletionIntent =
            | DurableNoCompletion
            | DurableRunEndCompletion of exitCode:int
            | DurableTerminalFailureCompletion of exitCode:int

        type DurableJsonWriteOutcome =
            | DurableWritePersisted of DurableJsonLineRef
            | DurableWriteDuplicate of DurableJsonLineRef
            | DurableWriteRunEndAlreadyCommitted of DurableJsonLineRef
            | DurableWriteFaulted of DurableJsonLineRef * exceptionType:string

        type private DurableJsonRunEndCommitState =
            | DurableRunEndOpen
            | DurableRunEndCommitted

        type DurableJsonWriteCandidate = private {
            kind : DurableJsonWriteKind
            completion : DurableJsonCompletionIntent
            line : string
            lineRef : DurableJsonLineRef
            sourceLength : int
            sourceUtf8Bytes : int
        }

        [<Struct>]
        type private DurableJsonHopacCaptureState =
            | DurableJsonCaptureInactive
            | DurableJsonCaptureActive of buffer:System.Collections.Generic.List<DurableJsonWriteCandidate>

        type private DurableJsonWriterState = {
            nextSequence : int64
            committedLineRefs : Set<DurableJsonLineRef>
            runEndState : DurableJsonRunEndCommitState
        }

        let private durableJsonLineRef (line:string) =
            line
            |> CompilerIdentityKernel.ContentDigest.hex256
            |> DurableJsonLineRef

        let durableJsonLineRefText (DurableJsonLineRef value) = value

        let private durableJsonWriterEnvelope (sequence:int64) (candidate:DurableJsonWriteCandidate) =
            let line = candidate.line
            let lineRefText = durableJsonLineRefText candidate.lineRef
            let suffix =
                sprintf ",\"durable_writer_sequence\":%d,\"durable_writer_receipt_ref\":\"%s\",\"durable_writer_source_length\":%d,\"durable_writer_source_utf8_bytes\":%d,\"durable_writer_du\":\"SingleWriterActor\"}"
                    sequence lineRefText candidate.sourceLength candidate.sourceUtf8Bytes
            if System.String.IsNullOrWhiteSpace line then
                sprintf "{\"kind\":\"durable_empty_line_rejected\",\"durable_writer_sequence\":%d,\"durable_writer_receipt_ref\":\"%s\",\"durable_writer_source_length\":%d,\"durable_writer_source_utf8_bytes\":%d,\"durable_writer_du\":\"SingleWriterActor\"}"
                    sequence lineRefText candidate.sourceLength candidate.sourceUtf8Bytes
            elif line.EndsWith("}", StringComparison.Ordinal) then
                line.Substring(0, line.Length - 1) + suffix
            else
                FastRuntimeFormat.format "{\"kind\":\"durable_non_json_line\",\"payload\":%s,\"durable_writer_sequence\":%d,\"durable_writer_receipt_ref\":\"%s\",\"durable_writer_source_length\":%d,\"durable_writer_source_utf8_bytes\":%d,\"durable_writer_du\":\"SingleWriterActor\"}" [| box (fileLogEscJson line); box sequence; box lineRefText; box candidate.sourceLength; box candidate.sourceUtf8Bytes |]

        type private DurableTaskbarCompletion =
            | DurableTaskbarNoCompletion
            | DurableTaskbarRunEndCommitted of exitCode:int
            | DurableTaskbarTerminalFailureCommitted of exitCode:int

        let private durableTaskbarCompletionFor (candidate:DurableJsonWriteCandidate) =
            match candidate.completion with
            | DurableRunEndCompletion exitCode ->
                DurableTaskbarRunEndCommitted exitCode
            | DurableTerminalFailureCompletion exitCode ->
                DurableTaskbarTerminalFailureCommitted exitCode
            | DurableNoCompletion ->
                DurableTaskbarNoCompletion

        let private applyDurableTaskbarCompletionAfterPersistence
            (candidate:DurableJsonWriteCandidate)
            outcome =
            match outcome with
            | DurableWritePersisted _ ->
                match durableTaskbarCompletionFor candidate with
                | DurableTaskbarRunEndCommitted exitCode ->
                    completeWindowsTaskbarForDurableRunEnd exitCode
                | DurableTaskbarTerminalFailureCommitted exitCode ->
                    completeWindowsTaskbarForDurableTerminalFailure exitCode
                | DurableTaskbarNoCompletion -> ()
            | DurableWriteDuplicate _
            | DurableWriteRunEndAlreadyCommitted _
            | DurableWriteFaulted _ -> ()

        let private durableJsonRunEndCommitStateFor observed =
            if observed then DurableRunEndCommitted else DurableRunEndOpen

        let private durableJsonRunEndAlreadyCommitted kind state =
            match kind, state with
            | DurableRunEndReceipt, DurableRunEndCommitted -> true
            | _ -> false

        let private durableJsonRunEndCommitAfter kind state =
            match kind, state with
            | DurableRunEndReceipt, DurableRunEndOpen -> DurableRunEndCommitted
            | _ -> state

        // The durable writer is a lock-serialized synchronous append. It used to be a Hopac actor (a mailbox
        // served on the Hopac pool) that synchronous callers waited on through a bridge thread. The evaluator
        // writes durable rows from Hopac workers, so each such write parked a worker until another worker ran
        // the actor: with one worker every build deadlocked in partial evaluation, and with N workers builds
        // stalled at random once N writes were in flight. The actor body was already a locked write; the lock
        // is now the whole writer, with the same sequence numbers, dedupe, run-end transition and outcomes.
        let mutable private durableJsonWriterState : DurableJsonWriterState option = None

        let private ensureDurableJsonWriterStarted () =
            CompilerRuntimeActivation.requireInProcessEntered "durable_json_writer"

        let private durableJsonWriteNow (candidate:DurableJsonWriteCandidate) : DurableJsonWriteOutcome =
            ensureDurableJsonWriterStarted()
            let outcome, runEndCommitted =
                lock gate (fun () ->
                    let state =
                        match durableJsonWriterState with
                        | Some state -> state
                        | None ->
                            { nextSequence = 1L
                              committedLineRefs = Set.empty
                              runEndState = terminalDurableRunEndObservedNow() |> durableJsonRunEndCommitStateFor }
                    if Set.contains candidate.lineRef state.committedLineRefs then
                        DurableWriteDuplicate candidate.lineRef, false
                    elif durableJsonRunEndAlreadyCommitted candidate.kind state.runEndState then
                        DurableWriteRunEndAlreadyCommitted candidate.lineRef, false
                    else
                        let sequence = state.nextSequence
                        let line = durableJsonWriterEnvelope sequence candidate
                        try
                            rememberFieldUnlocked "hud_paint_phase_du" (hudPaintPhaseText HudPaintPreLogAppend)
                            writeLineUnlocked line
                            flushFileLogUnlocked()
                            let nextRunEndState = durableJsonRunEndCommitAfter candidate.kind state.runEndState
                            durableJsonWriterState <-
                                Some { nextSequence = sequence + 1L
                                       committedLineRefs = Set.add candidate.lineRef state.committedLineRefs
                                       runEndState = nextRunEndState }
                            let committedNow =
                                match state.runEndState, nextRunEndState with
                                | DurableRunEndOpen, DurableRunEndCommitted -> true
                                | _ -> false
                            DurableWritePersisted candidate.lineRef, committedNow
                        with ex ->
                            DurableWriteFaulted(candidate.lineRef, ex.GetType().FullName), false)
            match outcome with
            | DurableWriteFaulted(lineRef, exceptionType) ->
                appendFileLogLineSerialized (
                    sprintf "{\"kind\":\"durable_json_writer_fault\",\"line_ref\":\"%s\",\"exception_type\":%s,\"durable_writer_du\":\"SingleWriterLock\",\"console_policy_du\":\"DurableFileOnlyOnMuxFailure\"}"
                        (durableJsonLineRefText lineRef) (fileLogEscJson exceptionType))
            | _ -> ()
            // Filling the run-end IVar only wakes readers; it never blocks the writer.
            if runEndCommitted then startHopacJob (terminalDurableRunEndObserveJob())
            outcome

        // Durable writes have two call surfaces. Host threads may synchronously wait for
        // the receipt. A Hopac reducer transition captures typed candidates synchronously,
        // then the surrounding job submits and acknowledges them in order through the actor.
        let private durableJsonHopacJobCapture =
            System.Threading.AsyncLocal<DurableJsonHopacCaptureState>()

        let withDurableJsonHopacJobContext (run: unit -> 'a) =
            let previous = durableJsonHopacJobCapture.Value
            match previous with
            | DurableJsonCaptureActive _ ->
                run(), []
            | DurableJsonCaptureInactive ->
                let current = System.Collections.Generic.List<DurableJsonWriteCandidate>()
                durableJsonHopacJobCapture.Value <- DurableJsonCaptureActive current
                try
                    let result = run()
                    result, (current |> Seq.toList)
                finally
                    durableJsonHopacJobCapture.Value <- previous

        let private durableJsonWriteCandidateFor (kind:DurableJsonWriteKind) (completion:DurableJsonCompletionIntent) (line:string) : DurableJsonWriteCandidate =
            { kind = kind
              completion = completion
              line = line
              lineRef = durableJsonLineRef line
              sourceLength = line.Length
              sourceUtf8Bytes = System.Text.Encoding.UTF8.GetByteCount line }

        let private durableJsonWriteOutcomeAccepted = function
            | DurableWritePersisted _
            | DurableWriteDuplicate _
            | DurableWriteRunEndAlreadyCommitted _ -> true
            | DurableWriteFaulted _ -> false

        let private submitDurableJsonCandidateJob (candidate:DurableJsonWriteCandidate) =
            Job.thunk (fun () -> durableJsonWriteNow candidate)

        let submitProgressJsonLinesTerminalDurableJob (candidates:DurableJsonWriteCandidate list) =
            job {
                let completions = System.Collections.Generic.List<DurableJsonWriteCandidate * DurableJsonWriteOutcome>()
                for candidate in candidates do
                    let! outcome = submitDurableJsonCandidateJob candidate
                    completions.Add(candidate, outcome)
                    match outcome with
                    | DurableWriteFaulted(lineRef, exceptionType) ->
                        appendFileLogLineSerialized (
                            sprintf "{\"kind\":\"durable_json_writer_job_submission_failed\",\"line_ref\":\"%s\",\"exception_type\":%s,\"submission_du\":\"HopacJobComposedOrdered\",\"authority\":\"single_writer_actor_receipt\"}"
                                (durableJsonLineRefText lineRef) (fileLogEscJson exceptionType))
                    | DurableWritePersisted _
                    | DurableWriteDuplicate _
                    | DurableWriteRunEndAlreadyCommitted _ -> ()
                // Apply presentation only after every ordered receipt in this reducer
                // batch has persisted. A taskbar/UI lock can no longer split the
                // run_end -> physical_exit -> total_order_chain durable sequence.
                for completion in completions do
                    let candidate, outcome = completion
                    applyDurableTaskbarCompletionAfterPersistence candidate outcome
            }

        let private submitDurableJsonCandidateSynchronously (candidate:DurableJsonWriteCandidate) =
            let result = durableJsonWriteNow candidate
            applyDurableTaskbarCompletionAfterPersistence candidate result
            result

        let private tryWriteProgressJsonLineDurable (kind:DurableJsonWriteKind) (completion:DurableJsonCompletionIntent) (line:string) =
            if Object.ReferenceEquals(line, null) then false
            else
                ensureDurableJsonWriterStarted()
                let candidate = durableJsonWriteCandidateFor kind completion line
                match durableJsonHopacJobCapture.Value with
                | DurableJsonCaptureActive buffer ->
                    buffer.Add candidate
                    true
                | DurableJsonCaptureInactive ->
                    candidate
                    |> submitDurableJsonCandidateSynchronously
                    |> durableJsonWriteOutcomeAccepted

        let private tryWriteProgressJsonLineDurableJob kind completion (line:string) =
            job {
                if Object.ReferenceEquals(line, null) then return false
                else
                    let candidate = durableJsonWriteCandidateFor kind completion line
                    let! outcome = submitDurableJsonCandidateJob candidate
                    applyDurableTaskbarCompletionAfterPersistence candidate outcome
                    return durableJsonWriteOutcomeAccepted outcome
            }

        let tryWriteProgressJsonLineTerminalDurable (line:string) =
            tryWriteProgressJsonLineDurable DurableTerminalReceipt DurableNoCompletion line

        let tryWriteProgressJsonLineTerminalDurableJob (line:string) =
            tryWriteProgressJsonLineDurableJob DurableTerminalReceipt DurableNoCompletion line

        let tryWriteProgressJsonLineTerminalFailureDurableJob exitCode (line:string) =
            tryWriteProgressJsonLineDurableJob DurableTerminalReceipt (DurableTerminalFailureCompletion exitCode) line

        let tryWriteProgressJsonLineTerminalFailureDurable exitCode (line:string) =
            tryWriteProgressJsonLineDurable DurableTerminalReceipt (DurableTerminalFailureCompletion exitCode) line

        let tryWriteProgressJsonLineRunEndDurableJob exitCode (line:string) =
            tryWriteProgressJsonLineDurableJob DurableRunEndReceipt (DurableRunEndCompletion exitCode) line

        let tryWriteProgressJsonLineRunEndDurable exitCode (line:string) =
            tryWriteProgressJsonLineDurable DurableRunEndReceipt (DurableRunEndCompletion exitCode) line

        let writeProgressJsonLineTerminalDurable (line:string) =
            tryWriteProgressJsonLineTerminalDurable line |> ignore

    module ReducerHudAuthorityBridge =
        open CompilerConsoleHud88

        type Snapshot = CompilerConsoleHud88.ReducerHudSnapshot

        let private empty : Snapshot =
            { generation = 0L
              snapshotMs = 0L
              elapsedMsAtSnapshot = 0L
              phase = ReducerHudDiscovering
              discovery = CompilerConsoleHud88.ReducerHudDiscoveryOpen 0L
              work =
                { ast =
                    { completedCost = 0L
                      discoveredCost = 0L
                      totalCost = 0L
                      exact = false
                      sourceRef = "" }
                  semantic =
                    { retiredCost = 0L
                      discoveredCost = 0L
                      knownRemainingCost = 0L
                      blockedCost = 0L
                      provenDeadCost = 0L
                      reserveP50Cost = 0L
                      reserveP90Cost = 0L
                      totalLow = 0L
                      totalMid = 0L
                      totalHigh = 0L
                      exact = false
                      revision = 0L }
                  lowBp = 0L
                  midBp = 0L
                  highBp = 0L }
              rates =
                { phase = ReducerHudDiscovering
                  shortSemanticCostPerSecond = 0.0
                  mediumSemanticCostPerSecond = 0.0
                  sessionSemanticCostPerSecond = 0.0
                  fusedSemanticCostPerSecond = 0.0
                  variance = 0.0
                  confidence = 0.0
                  samples = 0L
                  rateAuthorityRef = "" }
              timing =
                { cpuExclusiveMs = None
                  cpuAuthority = ReducerHudCpuUnavailable (ReducerHudCpuUnavailableReasonIdOps.create "bootstrap")
                  wallInclusiveMs = 0L
                  queueDelayMs = 0L
                  blockedOnChildMs = 0L
                  timingReceiptRef = "" }
              eta =
                { phase = ReducerHudDiscovering
                  terminalP50Ms = None
                  terminalP90Ms = None
                  confidenceSigmaMs = None
                  criticalPath = ReducerHudCriticalPathUnknown (ReducerHudCriticalPathUnknownReasonIdOps.create "bootstrap")
                  effectiveParallelism = 1.0
                  rateAuthorityRef = "" }
              possession = CompilerConsoleHud88.ReducerHudPossessionVacant
              actorRef = ""
              stageTokenRef = ""
              fillReceiptRef = ""
              runEndReceiptRef = ""
              physicalExitReceiptRef = ""
              terminalSnapshotRef = ""
              operationalRevision = 0L
              operationalGraphRef = ""
              runtimeAuthorityRef = ""
              semanticEpoch = 0L
              qapGenerationRef = ""
              qapStage = ReducerHudQapAwaiting
              commitReceiptRef = ""
              doneReceiptRef = ""
              exitCode = None
              sealedAtMs = None
              blockers = []
              hotNode = CompilerConsoleHud88.ReducerHudHotNodeUnknown
              crossKind = CompilerConsoleHud88.ReducerHudCrossKindClear
              cyclePoison = CompilerConsoleHud88.ReducerHudCyclePoisonClear }

        let read () =
            if CompilerRuntimeActivation.isInProcessEntered () then
                CompilerConsoleHud88.readReducerHudSnapshot()
                |> Option.defaultValue empty
            else
                empty

        let update (snapshot:Snapshot) =
            let semantic = snapshot.work.semantic
            if semantic.retiredCost > semantic.totalHigh then
                invalidOp (sprintf "semantic progress scope violation: retired=%d > total_high=%d" semantic.retiredCost semantic.totalHigh)
            if snapshot.work.ast.completedCost > snapshot.work.ast.totalCost then
                invalidOp (sprintf "ast progress scope violation: completed=%d > total=%d" snapshot.work.ast.completedCost snapshot.work.ast.totalCost)
            if snapshot.work.lowBp < 0L || snapshot.work.lowBp > 10000L
               || snapshot.work.midBp < 0L || snapshot.work.midBp > 10000L
               || snapshot.work.highBp < 0L || snapshot.work.highBp > 10000L then
                invalidOp "progress basis points must remain inside 0..10000"
            match snapshot.timing.cpuExclusiveMs, snapshot.timing.cpuAuthority with
            | None, ReducerHudCpuUnavailable _ -> ()
            | Some cpuMs, CompilerConsoleHud88.ReducerHudCpuExclusiveWorker _
                when cpuMs >= 0L && cpuMs <= snapshot.timing.wallInclusiveMs -> ()
            | None, CompilerConsoleHud88.ReducerHudCpuExclusiveWorker _ ->
                invalidOp "HUD exclusive CPU authority requires a measurement"
            | Some _, ReducerHudCpuUnavailable _ ->
                invalidOp "HUD unavailable CPU authority cannot accompany a measurement"
            | Some _, CompilerConsoleHud88.ReducerHudCpuExclusiveWorker _ ->
                invalidOp "HUD exclusive CPU cannot exceed inclusive wall time"
            if snapshot.timing.wallInclusiveMs < 0L
               || snapshot.timing.queueDelayMs < 0L
               || snapshot.timing.blockedOnChildMs < 0L then
                invalidOp "HUD timing quantities must be non-negative"
            if snapshot.timing.queueDelayMs > snapshot.timing.wallInclusiveMs
               || snapshot.timing.blockedOnChildMs > snapshot.timing.wallInclusiveMs - snapshot.timing.queueDelayMs then
                invalidOp "HUD queue plus blocked-on-child time exceeds inclusive wall time"
            if snapshot.eta.phase <> snapshot.rates.phase then
                invalidOp "HUD ETA phase must match the rate authority phase"
            if CompilerRuntimeActivation.isInProcessEntered () then
                CompilerConsoleHud88.publishReducerHudSnapshot snapshot |> ignore

        type ReducerHudUpdateDisposition =
            | ReducerHudSnapshotPublished
            | ReducerHudSnapshotRejectedObserverOnly

        let tryUpdate snapshot =
            try
                update snapshot
                ReducerHudSnapshotPublished
            with _ ->
                ReducerHudSnapshotRejectedObserverOnly

