#if !INTERACTIVE
namespace Polyglot
#endif

module spiral_compiler =

#endif
#if SPIRAL_CORE_HOPAC
    /// ## spiral_compiler
    module Progress88 =
        open System
        open System.Threading
        open System.Diagnostics
        open System.Text

        /// [CONSOLE-176-001] Serialize stderr writes to avoid Hopac interleaving.
        module ConsoleMux88 =
            let withLock (f: unit -> unit) = CompilerConsoleHud88.withLock f
            let writeLine (s: string) = CompilerConsoleHud88.writeLine s
            let writeLineAnsi (s: string) = CompilerConsoleHud88.writeLineAnsi s

        type ConsoleEncodingFamilyId =
            | ConsoleEncodingUtfFamily
            | ConsoleEncodingOtherFamily

        type ConsoleEncodingCapabilityId =
            | ConsoleEncodingUnicodeInteractive
            | ConsoleEncodingNonUnicodeOrRedirected
            | ConsoleEncodingUnavailable

        let private consoleEncodingFamilyId (encoding:Encoding) =
            match encoding.CodePage with
            | 65000
            | 65001
            | 1200
            | 1201
            | 12000
            | 12001 -> ConsoleEncodingUtfFamily
            | _ -> ConsoleEncodingOtherFamily

        let private consoleEncodingCapabilityId () =
            try
                match consoleEncodingFamilyId Console.OutputEncoding, Console.IsErrorRedirected with
                | ConsoleEncodingUtfFamily, false -> ConsoleEncodingUnicodeInteractive
                | ConsoleEncodingUtfFamily, true
                | ConsoleEncodingOtherFamily, _ -> ConsoleEncodingNonUnicodeOrRedirected
            with _ ->
                ConsoleEncodingUnavailable

        let private ui_supports_unicode =
            match consoleEncodingCapabilityId () with
            | ConsoleEncodingUnicodeInteractive -> true
            | ConsoleEncodingNonUnicodeOrRedirected
            | ConsoleEncodingUnavailable -> false

        let bar_fill = if ui_supports_unicode then "█" else "#"
        let bar_empty = if ui_supports_unicode then "·" else "-"

        do
            if ui_supports_unicode then
                try Console.OutputEncoding <- Encoding.UTF8 with _ -> ()


        /// [CONSOLE-VT-245-001] Try enabling ANSI/VT processing on Windows consoles.
        module ConsoleVT88 =
            // MIGRATION: stop using Win32 console APIs. Keep logs append-only and let the host decide VT.
            // We still keep ANSI escapes as plain text when present; this function is a no-op.
            let tryEnableVTOnStderr () = false

        type ProgressHeartbeatTag =
            | ProgressHeartbeatBoot
            | ProgressHeartbeatStart
            | ProgressHeartbeatDone
            | ProgressHeartbeatStage of index:int * total:int
            | ProgressHeartbeatJpWorkLedgerProgress
            | ProgressHeartbeatWait of detail:string

        let private progressHeartbeatTagText = function
            | ProgressHeartbeatBoot -> "boot"
            | ProgressHeartbeatStart -> "start"
            | ProgressHeartbeatDone -> "done"
            | ProgressHeartbeatStage(index, total) ->
                sprintf "stage %d/%d" index total
            | ProgressHeartbeatJpWorkLedgerProgress ->
                "progress:jp_note_progress"
            | ProgressHeartbeatWait detail ->
                "wait:" + detail

        let sw = Stopwatch.StartNew()
        let mutable tag = ProgressHeartbeatBoot
        let mutable gen = 0L
        let mutable stage_i = 0
        let mutable stage_n = 4
        let mutable sub_i = 0L
        let mutable sub_n = 1L
        let mutable last_touch_ms = 0L
        let mutable ticks = 0L
        let private progressStateGate = obj()

        // [CONSOLE-193-001] Rate/ETA snapshots (heartbeat-local moving estimate).
        let mutable last_subi_snap = 0L
        let mutable last_sub_ms_snap = 0L
        let mutable last_rate_per_s = 0.0


        // [CONSOLE-195-001] Detect progress counter resets inside the same gen and mark epochs.
        let mutable epoch = 0
        let mutable last_seen_gen = Int64.MinValue
        let mutable last_overall_raw = -1.0
        type Providers =
            { mutable genf: unit -> int64
              mutable extraf: unit -> string
              mutable panelf: unit -> string
              mutable statsf: unit -> string }

        type ProgressStatsSuffixId =
            | ProgressStatsSuffixEmpty
            | ProgressStatsSuffixAlreadyDelimited of value:string
            | ProgressStatsSuffixNeedsDelimiter of value:string

        let private progressStatsSuffixId (value:string) =
            if String.IsNullOrWhiteSpace value then ProgressStatsSuffixEmpty
            elif value.Length > 0 && value.[0] = ',' then ProgressStatsSuffixAlreadyDelimited value
            else ProgressStatsSuffixNeedsDelimiter value

        let private progressStatsSuffixText = function
            | ProgressStatsSuffixEmpty -> ""
            | ProgressStatsSuffixAlreadyDelimited value -> value
            | ProgressStatsSuffixNeedsDelimiter value -> "," + value

        let providers : Providers =
            { genf = (fun () -> gen)
              extraf = (fun () -> "")
              panelf = (fun () -> "")
              statsf = (fun () -> "") }

        // [CONSOLE-377-001] JSON mode must be machine-parseable even when tags/panels
        // contain quotes, backslashes or multiline frontier dumps. Keep this local and
        // allocation-bounded; heartbeat cadence is seconds, not inner-loop hot path.
        let private json_escape (s: string) =
            if obj.ReferenceEquals(s, null) then ""
            else
                s.Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("\r", "\\r").Replace("\n", "\\n").Replace("\t", "\\t")

        // MIGRATION: compact console capability snapshot.  This keeps append-only logs
        // useful for UI/CI reconstruction without reintroducing cursor-mutating TUI output.
        let private console_caps () =
            let safe (f: unit -> string) =
                try f() with _ -> "?"
            let ansi =
                try
                    if Console.IsErrorRedirected then false
                    else
                        let _ = Console.CursorTop
                        let _ = Console.BufferWidth
                        true
                with _ -> false
            let width = safe (fun () -> if Console.IsErrorRedirected then "redir" else string Console.BufferWidth)
            let enc = safe (fun () -> Console.OutputEncoding.WebName)
            FastRuntimeFormat.format "unicode=%b;ansi=%b;stderr_redirected=%b;width=%s;enc=%s" [| box ui_supports_unicode; box ansi; box Console.IsErrorRedirected; box width; box enc |]
        let mutable predictionTickSink : string -> unit = fun _ -> ()

        let set_gen_provider (f: unit -> int64) = providers.genf <- f
        let set_extra_provider (f: unit -> string) = providers.extraf <- f
        let set_panel_provider (f: unit -> string) = providers.panelf <- f
        let set_stats_provider (f: unit -> string) = providers.statsf <- f
        let set_prediction_tick_sink (f: string -> unit) = predictionTickSink <- f

        let touch (t: ProgressHeartbeatTag) (g: int64) =
            tag <- t
            gen <- g
            last_touch_ms <- sw.ElapsedMilliseconds

        let stage (i: int) (n: int) =
            stage_i <- i
            stage_n <- (if n <= 0 then 1 else n)
            if stage_i < 0 then stage_i <- 0
            if stage_i > stage_n then stage_i <- stage_n
            last_touch_ms <- sw.ElapsedMilliseconds
            // SOTA: avoid newline spam; stage transitions are reflected by the heartbeat UI.
            touch (ProgressHeartbeatStage(stage_i, stage_n)) (providers.genf())

        let sub (i: int64) (n: int64) =
            sub_i <- i
            sub_n <- (if n <= 0L then 1L else n)
            if sub_i < 0L then sub_i <- 0L
            if sub_i > sub_n then sub_i <- sub_n
            last_touch_ms <- sw.ElapsedMilliseconds

        let pulse (t: ProgressHeartbeatTag) (g: int64) =
            let tks = lock progressStateGate (fun () -> ticks <- ticks + 1L; ticks)
            if (tks &&& 255L) = 0L then touch t g

        let tick0 (t: ProgressHeartbeatTag) : unit =
            pulse t (providers.genf())
        let private ui_supports_ansi =
            try
                if Console.IsErrorRedirected then false
                else
                    // If any cursor API throws, assume no TTY.
                    let _ = Console.CursorTop
                    let _ = Console.BufferWidth
                    true
            with _ -> false

        // [CONSOLE-198-001] UI mode selection (deterministic; no env var reads):
        // - "off" when stderr redirected (CI/logs)
        // - "ansi_tui" when cursor controls are available
        // - "ansi_line" when we can color but not safely reposition
        // - "line" fallback
        // [CONSOLE-202-002] Re-enable ANSI modes (still append-only; no cursor moves).
        type ConsoleUiMode =
            | ConsoleUiOff
            | ConsoleUiAnsiLine
            | ConsoleUiAnsiMulti
            | ConsoleUiAnsiTui
            | ConsoleUiLine
            | ConsoleUiJson

        let private consoleUiModeText = function
            | ConsoleUiOff -> "off"
            | ConsoleUiAnsiLine -> "ansi_line"
            | ConsoleUiAnsiMulti -> "ansi_multi"
            | ConsoleUiAnsiTui -> "ansi_tui"
            | ConsoleUiLine -> "line"
            | ConsoleUiJson -> "json"

        let get_ui_mode () =
            // MIGRATION: no env-var UI policy. Console mode is a closed runtime capability.
            if Console.IsErrorRedirected then ConsoleUiOff
            elif ui_supports_unicode && ui_supports_ansi then ConsoleUiAnsiLine
            elif ui_supports_unicode then ConsoleUiAnsiLine
            else ConsoleUiLine


        // TUI keeps a fixed height to avoid scroll spam.
        let tui_height = 1 + 6
        let mutable tui_started = false

        let ui_keep_log = false

        // MIGRATION: advanced console logging without cursor mutation.  Panels are
        // typed before rendering so future modes can extend the contract without
        // reintroducing stringly if/else ladders or CI newline spam.
        type ConsolePanelPolicy =
            | ConsolePanelOff
            | ConsolePanelInlineFirstLine
            | ConsolePanelAppendLines of int

        let private activeConsolePanelPolicy () =
            if Console.IsErrorRedirected then ConsolePanelOff
            elif ui_supports_unicode then ConsolePanelInlineFirstLine
            else ConsolePanelOff

        let private consolePanelPolicyToString policy =
            match policy with
            | ConsolePanelOff -> "off"
            | ConsolePanelInlineFirstLine -> "inline_first_line"
            | ConsolePanelAppendLines n -> sprintf "append_lines_%d" n

        let private clipConsoleField (limit: int) (value: string) =
            if System.String.IsNullOrEmpty value then ""
            elif value.Length <= limit then value
            else value.Substring(0, limit) + sprintf "…[+%d chars]" (value.Length - limit)

        let private normalizedConsolePanelLines (panel: string) =
            if System.String.IsNullOrWhiteSpace panel then [||]
            else
                panel.Replace("\r", "").Split('\n')
                |> Array.map (fun line -> line.TrimEnd())
                |> Array.filter (fun line -> not (System.String.IsNullOrWhiteSpace line))

        let private renderConsolePanelInline (panel: string) =
            match activeConsolePanelPolicy() with
            | ConsolePanelInlineFirstLine ->
                let lines = normalizedConsolePanelLines panel
                if lines.Length = 0 then ""
                else sprintf " panel_policy=%s panel=%s" (consolePanelPolicyToString ConsolePanelInlineFirstLine) (clipConsoleField 240 lines.[0])
            | ConsolePanelAppendLines _
            | ConsolePanelOff -> ""

        let mutable started = 0
        let private heartbeat () =
            while true do
                // MIGRATION: prediction ticks are emitted from this background heartbeat,
                // not from the evaluator/join hot path.
                Thread.Sleep 1000
                let now = sw.ElapsedMilliseconds
                let g = providers.genf()
                let ui_mode = get_ui_mode ()
                // Snapshot all mutable counters so each line is internally consistent.
                let si = stage_i
                let sn = stage_n
                let subi = sub_i
                let subn = sub_n
                let tks = ticks
                let ttag = progressHeartbeatTagText tag
                let silentRaw = now - last_touch_ms
                let silent = if silentRaw < 0L then 0L else silentRaw
                let p = Process.GetCurrentProcess()
                let privateMb = float p.PrivateMemorySize64 / (1024.0 * 1024.0)
                let gcMb = float (GC.GetTotalMemory(false)) / (1024.0 * 1024.0)
                let _stageBasePct = if sn > 0 then (float (max 0 (si - 1)) / float sn) * 100.0 else Double.NaN
                let subpct = if subn > 0L then (float subi / float subn) * 100.0 else Double.NaN

                // [CONSOLE-193-001] Update moving rate estimate and compute ETA.
                let dt = now - last_sub_ms_snap
                let dsub = subi - last_subi_snap
                if last_sub_ms_snap = 0L then
                    last_sub_ms_snap <- now
                    last_subi_snap <- subi
                elif dt > 0L && dsub > 0L then
                    last_rate_per_s <- (float dsub) * 1000.0 / (float dt)
                    last_sub_ms_snap <- now
                    last_subi_snap <- subi
                elif dt > 15000L && dsub = 0L && last_rate_per_s > 0.0 then
                    // [CONSOLE-195-002] Decay rate during stalls so ETA expands instead of lying.
                    last_rate_per_s <- last_rate_per_s * 0.5
                    last_sub_ms_snap <- now
                    last_subi_snap <- subi
                let etaSec =
                    if last_rate_per_s > 0.0 && subn > subi then
                        int64 (Math.Ceiling (float (subn - subi) / last_rate_per_s))
                    else -1L
                let etaStr =
                    if etaSec < 0L then "?"
                    elif etaSec < 120L then sprintf "%ds" etaSec
                    elif etaSec < 7200L then sprintf "%dm%ds" (etaSec/60L) (etaSec%60L)
                    else sprintf "%dh%dm" (etaSec/3600L) ((etaSec%3600L)/60L)
                // SOTA: stage 3 dominates wall time; weight it so overall keeps moving instead of plateauing at 75%.
                let stageW =
                    if sn = 4 then [| 0.05; 0.05; 0.85; 0.05 |]
                    else Array.init (max 1 sn) (fun _ -> 1.0 / float (max 1 sn))
                let stageIdx0 = max 0 (min (stageW.Length - 1) (si - 1))
                let subFrac =
                    if subn > 0L then
                        let v = float subi / float subn
                        if v < 0.0 then 0.0 elif v > 1.0 then 1.0 else v
                    else 0.0
                let mutable acc = 0.0
                for j = 0 to stageIdx0 - 1 do acc <- acc + stageW.[j]
                let overallPctRaw = (acc + stageW.[stageIdx0] * subFrac) * 100.0

                // [CONSOLE-195-003] Detect regressions in overallPct when sub counters restart inside the same gen.
                let mutable did_reset = false
                if g <> last_seen_gen then
                    last_seen_gen <- g
                    epoch <- 0
                    last_overall_raw <- overallPctRaw
                elif last_overall_raw >= 0.0 && overallPctRaw < (last_overall_raw - 1.0) then
                    epoch <- epoch + 1
                    did_reset <- true
                    last_overall_raw <- overallPctRaw
                    // Reset snapshots so rate/ETA does not carry across unrelated phases.
                    last_sub_ms_snap <- now
                    last_subi_snap <- subi
                    last_rate_per_s <- 0.0
                else
                    last_overall_raw <- overallPctRaw

                let epStr = if epoch > 0 then sprintf " ep=%d" epoch else ""
                let resetStr = if did_reset then " rst=1" else ""

                let overallPct = overallPctRaw
                let overallCapPct = (acc + stageW.[stageIdx0]) * 100.0
                let capRemPct = overallCapPct - overallPct
                let subRem = subn - subi
                let extra = providers.extraf()
                let panel = providers.panelf()
                let panelSuffix = renderConsolePanelInline panel
                let barLen = 20
                let  clamp01 (x: float) = if x < 0.0 then 0.0 elif x > 1.0 then 1.0 else x
                let mkBar (p: float) =
                    let f = int (clamp01 (p / 100.0) * float barLen + 0.5)
                    let e = barLen - f
                    let fill = Microsoft.FSharp.Core.String.replicate f bar_fill
                    let empty = Microsoft.FSharp.Core.String.replicate e bar_empty
                    if ui_mode = ConsoleUiAnsiLine || ui_mode = ConsoleUiAnsiTui then
                        // [CONSOLE-176-002] ANSI-safe, newline-based bars (no in-place refresh).
                        $"\u001b[32m{fill}\u001b[0m\u001b[2m{empty}\u001b[0m"
                    else
                        fill + empty
                let barS = mkBar overallPct
                let barSub = mkBar subpct
                let phase =
                    (match si with
                     | 0 -> "boot"
                     | 1 -> "setup"
                     | 2 -> "front"
                     | 3 -> "peval"
                     | 4 -> "emit"
                     | _ -> sprintf "stage%d" si)
                let statsRaw =
                    try providers.statsf() with _ -> ""
                let statsSuffix =
                    statsRaw
                    |> progressStatsSuffixId
                    |> progressStatsSuffixText
                let elapsedSec = now / 1000L
                let predictionTotalSec = if etaSec < 0L then -1L else elapsedSec + etaSec
                let predictionJson =
                    FastRuntimeFormat.format "{\"kind\":\"compile_progress_prediction_tick\",\"event\":\"progress_heartbeat\",\"cadence_ms\":1000,\"source\":\"Progress88.heartbeat\",\"sink\":\"DiagJson.emit\",\"outside_hot_path\":true,\"phase\":\"%s\",\"gen\":%d,\"elapsed_s\":%d,\"progress_pct\":%.4f,\"stage_pct\":%.4f,\"prediction_eta_s\":%d,\"prediction_total_s\":%d,\"stage_i\":%d,\"stage_n\":%d,\"sub_i\":%d,\"sub_n\":%d,\"sub_rem\":%d,\"rate_per_s\":%.4f,\"tick\":%d,\"silent_ms\":%d,\"tag\":\"%s\",\"extra\":\"%s\",\"mem_private_mb\":%.0f,\"mem_gc_mb\":%.0f%s}" [| box (json_escape phase); box g; box elapsedSec; box overallPct; box subpct; box etaSec; box predictionTotalSec; box si; box sn; box subi; box subn; box subRem; box last_rate_per_s; box tks; box silent; box (json_escape ttag); box (json_escape extra); box privateMb; box gcMb; box statsSuffix |]
                try predictionTickSink predictionJson with _ -> ()
                ConsoleMux88.writeLine predictionJson
                let line =
                    match ui_mode with
                    | ConsoleUiJson ->
                        // JSONL (one object per refresh) for machine-readable profiling.
                        // MIGRATION: include escaped extra/panel so Hopac/frontier state can be consumed by tools.
                        FastRuntimeFormat.format "{\"app\":\"spiral\",\"phase\":\"%s\",\"ui\":\"%s\",\"gen\":%d,\"overall_pct\":%.4f,\"overall_cap_pct\":%.4f,\"overall_rem_pct\":%.4f,\"stage_i\":%d,\"stage_n\":%d,\"sub_i\":%d,\"sub_n\":%d,\"sub_pct\":%.4f,\"sub_rem\":%d,\"t_s\":%d,\"mem_private_mb\":%.0f,\"mem_gc_mb\":%.0f,\"tick\":%d,\"silent_ms\":%d,\"rate_per_s\":%.4f,\"eta\":\"%s\",\"tag\":\"%s\",\"extra\":\"%s\",\"panel\":\"%s\",\"caps\":\"%s\"}" [| box phase; box (consoleUiModeText ui_mode); box g; box overallPct; box overallCapPct; box capRemPct; box si; box sn; box subi; box subn; box subpct; box subRem; box (now/1000L); box privateMb; box gcMb; box tks; box silent; box last_rate_per_s; box (json_escape etaStr); box (json_escape ttag); box (json_escape extra); box (json_escape panel); box (json_escape (console_caps())) |]
                    | ConsoleUiOff
                    | ConsoleUiAnsiLine
                    | ConsoleUiAnsiMulti
                    | ConsoleUiAnsiTui
                    | ConsoleUiLine ->
                        // Append-only compact bars (default).
                        FastRuntimeFormat.format "[spiral] %s %.1f%% phase=%s sub=%.1f%% eta=%s gen=%d%s tag=%s %s%s" [| box barS; box overallPct; box phase; box subpct; box etaStr; box g; box epStr; box ttag; box extra; box panelSuffix |]

                if ui_mode <> ConsoleUiOff then
                    CompilerConsoleHud88.updateHudText line panel

                // [CONSOLE-208-001] TUI/in-place refresh disabled (paste-friendly, append-only logs).
                // Restore the commented block when we reach 100% SOTA interactive console.
                (*
                match ui_mode with
                | "ansi_tui" ->
                    let panelLines =
                        if System.String.IsNullOrEmpty panel then [||]
                        else panel.Replace("\r","").Split('\n') |> Array.filter (fun pl -> not (System.String.IsNullOrEmpty pl))
                    let lines = ResizeArray<string>(tui_height)
                    lines.Add(line)
                    for i = 0 to panelLines.Length - 1 do
                        if lines.Count < tui_height then
                            lines.Add($"\u001b[2m[spiral] | {panelLines.[i]}\u001b[0m")
                    while lines.Count < tui_height do lines.Add("")
                    ConsoleMux88.withLock (fun () ->
                        if tui_started then
                            Console.Error.Write($"\u001b[{tui_height}F")
                        else
                            tui_started <- true
