                                ConsoleMux88.writeLineAnsi ($"\u001b[2m[spiral] | {pl}\u001b[0m")
                | "line" ->
                    ConsoleMux88.writeLine line
                    if not (System.String.IsNullOrEmpty panel) then
                        for pl in panel.Replace("\r","").Split('\n') do
                            if not (System.String.IsNullOrEmpty pl) then
                                ConsoleMux88.writeLine ($"[spiral] | {pl}")
                | _ -> ()
                *)
                match ui_mode with
                | ConsoleUiAnsiMulti
                | ConsoleUiAnsiTui ->
                    ConsoleMux88.writeLineAnsi line
                    if not (System.String.IsNullOrEmpty panel) then
                        for pl in panel.Replace("\r","").Split('\n') do
                            if not (System.String.IsNullOrEmpty pl) then
                                ConsoleMux88.writeLineAnsi ($"\u001b[2m[spiral] | {pl}\u001b[0m")
                | ConsoleUiAnsiLine ->
                    ConsoleMux88.writeLineAnsi line
                | ConsoleUiLine
                | ConsoleUiJson ->
                    ConsoleMux88.writeLine line
                | ConsoleUiOff -> ()

        let start () =
            if lock progressStateGate (fun () -> if started = 0 then started <- 1; true else false) then
                stage 0 4
                sub 0L 1L
                touch ProgressHeartbeatStart (providers.genf())
                // [CONSOLE-283-002] Emit console capability snapshot once (append-only).
                let ui = get_ui_mode ()
                if ui <> ConsoleUiOff then
                    ConsoleMux88.writeLine (
                        FastRuntimeFormat.format "[spiral_compiler] console ui=%s unicode=%b ansi=%b err_redirected=%b caps=%s" [| box (consoleUiModeText ui); box ui_supports_unicode; box ui_supports_ansi; box Console.IsErrorRedirected; box (console_caps()) |])
                let th = Thread(ThreadStart(heartbeat))
                th.IsBackground <- true
                th.Start()

    open FSharp.Core

    /// [JP-TIME-245-001] Global JP progress clock hook.
    /// MIGRATION: replay helpers are defined outside the lexical scope where BuildFile
    /// binds peval_sw, so watchdog progress must go through an early, swappable clock
    /// instead of referencing peval_sw directly. BuildFile installs the peval-relative
    /// clock immediately after creating peval_sw. Until then, this is inert and preserves
    /// compile order.
    type JpProgressClockStamp =
        | JpProgressClockDormant
        | JpProgressClockObserved of int64

    type JpProgressClockState = private { stamp : JpProgressClockStamp }

    let private jp_progress_clock_gate = obj()
    let mutable private jp_progress_clock_state = { stamp = JpProgressClockDormant }
    let mutable jp_progress_clock : unit -> int64 = fun () -> 0L

    let jp_progress_clock_read () =
        lock jp_progress_clock_gate (fun () ->
            match jp_progress_clock_state.stamp with
            | JpProgressClockDormant -> 0L
            | JpProgressClockObserved atMs -> atMs)

    let jp_progress_clock_mark (atMs: int64) =
        if atMs > 0L then
            lock jp_progress_clock_gate (fun () ->
                let next =
                    match jp_progress_clock_state.stamp with
                    | JpProgressClockDormant -> JpProgressClockObserved atMs
                    | JpProgressClockObserved previous -> JpProgressClockObserved (max previous atMs)
                jp_progress_clock_state <- { stamp = next })

    let jp_mark_progress () =
        jp_progress_clock() |> jp_progress_clock_mark

    [<StructuralEquality; NoComparison>]
    type JpRequiredWorkSliceProgressKey = private | JpRequiredWorkSliceProgressKey of generation:int64 * commitOrdinal:int64

    [<NoComparison>]
    type JpRequiredWorkSliceProgressState = private {
        progressFingerprint : CompilerIdentityKernel.ContentDigest
        sameContinuationYieldCount : int
    }

    [<StructuralEquality; NoComparison>]
    type JpDeclaredBodyFinishThroughClaimId =
        | JpDeclaredBodyFinishThroughNotEligible of repeatCount:int
        | JpDeclaredBodyFinishThroughAcquired of repeatCount:int
        | JpDeclaredBodyFinishThroughOwned of repeatCount:int
        | JpDeclaredBodyFinishThroughHeldByOther of repeatCount:int

    let jpDeclaredBodyFinishThroughClaimText = function
        | JpDeclaredBodyFinishThroughNotEligible repeatCount -> sprintf "NotEligible(repeat=%d)" repeatCount
        | JpDeclaredBodyFinishThroughAcquired repeatCount -> sprintf "Acquired(repeat=%d|mode=bounded_recovery_slice)" repeatCount
        | JpDeclaredBodyFinishThroughOwned repeatCount -> sprintf "Owned(repeat=%d|mode=bounded_recovery_slice)" repeatCount
        | JpDeclaredBodyFinishThroughHeldByOther repeatCount -> sprintf "HeldByOther(repeat=%d)" repeatCount

    let private jp_required_work_slice_progress_gate = obj()
    let private jp_required_work_slice_progress_continuations =
        System.Collections.Generic.Dictionary<JpRequiredWorkSliceProgressKey, JpRequiredWorkSliceProgressState>()
    let mutable private jp_required_work_slice_progress_sequence = 0L
    // Re-entering a declared body is currently much more expensive than extending a
    // materialized continuation: runtime profiles show the 4x recovery slice retiring
    // roughly four times the operations at comparable active wall time. Snapshot refs
    // are affine/unique, so stability is measured by the ordinal-free semantic-position
    // fingerprint, never by snapshot identity. Claim the single-owner recovery lane
    // after four stable-position yields instead of paying repeated root re-entry.
    let private jp_declared_body_finish_through_threshold = 4
    let private jp_declared_body_finish_through_budget_multiplier = 4
    // Long-lived declared bodies can make real semantic-position progress while paying
    // repeated 256-op resume overhead.  Grant a smaller 2x slice before the 4x
    // single-owner finish-through lane, but only while operation progress is recent and
    // queue pressure is bounded.  These thresholds are structural scheduler policy;
    // source path, symbol, span, and diagnostic text never participate.
    let private jp_declared_body_progressing_recovery_age_ms = 30000L
    let private jp_declared_body_progressing_recovery_min_operations = 1024L
    let private jp_declared_body_progressing_recovery_idle_guard_ms = 5000L
    let private jp_declared_body_progressing_recovery_queue_cap = 8
    let private jp_declared_body_progressing_recovery_multiplier = 2
    // Once a declared body has proved sustained operation progress and no semantic
    // work is queued behind it, use the already-established 4x bounded-slice ceiling.
    // This is still cooperative: bounded queue pressure drops back to the 2x
    // progressing policy and larger pressure to the normal slice, while checkpoint
    // freshness remains independent liveness evidence.
    let private jp_declared_body_progressing_exclusive_age_ms = jp_declared_body_progressing_recovery_age_ms * 2L
    let private jp_declared_body_progressing_exclusive_min_operations = jp_declared_body_progressing_recovery_min_operations * 2L
    let private jp_declared_body_progressing_exclusive_multiplier = jp_declared_body_finish_through_budget_multiplier

    type JpDeclaredBodyRecoverySlicePolicyId =
        | JpDeclaredBodyRecoveryNormal
        | JpDeclaredBodyRecoveryProgressingLongLived
        | JpDeclaredBodyRecoveryProgressingExclusive
        | JpDeclaredBodyRecoverySingleOwnerFinishThrough

    let jpDeclaredBodyRecoverySlicePolicyText = function
        | JpDeclaredBodyRecoveryNormal -> "NormalSlice"
        | JpDeclaredBodyRecoveryProgressingLongLived ->
            sprintf "ProgressingLongLivedSlice(multiplier=%d)" jp_declared_body_progressing_recovery_multiplier
        | JpDeclaredBodyRecoveryProgressingExclusive ->
            sprintf "ProgressingExclusiveSlice(multiplier=%d)" jp_declared_body_progressing_exclusive_multiplier
        | JpDeclaredBodyRecoverySingleOwnerFinishThrough ->
            sprintf "SingleOwnerFinishThrough(multiplier=%d)" jp_declared_body_finish_through_budget_multiplier

    let jpDeclaredBodyRecoverySlicePolicyFor finishThroughOwned semanticQueueDepth lifetimeAgeMs observedOperations operationIdleMs =
        if finishThroughOwned && semanticQueueDepth = 0 then
            JpDeclaredBodyRecoverySingleOwnerFinishThrough
        elif semanticQueueDepth = 0
             && lifetimeAgeMs >= jp_declared_body_progressing_exclusive_age_ms
             && observedOperations >= jp_declared_body_progressing_exclusive_min_operations
             && operationIdleMs <= jp_declared_body_progressing_recovery_idle_guard_ms then
            JpDeclaredBodyRecoveryProgressingExclusive
        elif lifetimeAgeMs >= jp_declared_body_progressing_recovery_age_ms
             && observedOperations >= jp_declared_body_progressing_recovery_min_operations
             && operationIdleMs <= jp_declared_body_progressing_recovery_idle_guard_ms
             && semanticQueueDepth <= jp_declared_body_progressing_recovery_queue_cap then
            JpDeclaredBodyRecoveryProgressingLongLived
        else
            JpDeclaredBodyRecoveryNormal

    let jpDeclaredBodyRecoverySliceMultiplier = function
        | JpDeclaredBodyRecoverySingleOwnerFinishThrough -> jp_declared_body_finish_through_budget_multiplier
        | JpDeclaredBodyRecoveryProgressingExclusive -> jp_declared_body_progressing_exclusive_multiplier
        | JpDeclaredBodyRecoveryProgressingLongLived -> jp_declared_body_progressing_recovery_multiplier
        | JpDeclaredBodyRecoveryNormal -> 1

    let mutable private jp_declared_body_finish_through_owner : int64 option = None

    let jp_note_required_work_slice_progress generation commitOrdinal progressFingerprint =
        lock jp_required_work_slice_progress_gate (fun () ->
            let key = JpRequiredWorkSliceProgressKey(generation, commitOrdinal)
            match jp_required_work_slice_progress_continuations.TryGetValue key with
            | true, previous when previous.progressFingerprint = progressFingerprint ->
                let repeatCount = previous.sameContinuationYieldCount + 1
                jp_required_work_slice_progress_continuations[key] <-
                    { previous with sameContinuationYieldCount = repeatCount }
                false, repeatCount
            | _ ->
                jp_required_work_slice_progress_continuations[key] <-
                    { progressFingerprint = progressFingerprint
                      sameContinuationYieldCount = 0 }
                jp_required_work_slice_progress_sequence <- jp_required_work_slice_progress_sequence + 1L
                true, 0)

    let jp_declared_body_finish_through_claim commitOrdinal repeatCount =
        lock jp_required_work_slice_progress_gate (fun () ->
            if repeatCount < jp_declared_body_finish_through_threshold then
                JpDeclaredBodyFinishThroughNotEligible repeatCount
            else
                match jp_declared_body_finish_through_owner with
                | None ->
                    jp_declared_body_finish_through_owner <- Some commitOrdinal
                    JpDeclaredBodyFinishThroughAcquired repeatCount
                | Some owner when owner = commitOrdinal ->
                    JpDeclaredBodyFinishThroughOwned repeatCount
                | Some _ -> JpDeclaredBodyFinishThroughHeldByOther repeatCount)

    let jp_declared_body_finish_through_owns commitOrdinal =
        lock jp_required_work_slice_progress_gate (fun () ->
            jp_declared_body_finish_through_owner = Some commitOrdinal)

    let jp_declared_body_finish_through_owner_snapshot () =
        lock jp_required_work_slice_progress_gate (fun () -> jp_declared_body_finish_through_owner)

    let jp_declared_body_finish_through_release commitOrdinal =
        lock jp_required_work_slice_progress_gate (fun () ->
            if jp_declared_body_finish_through_owner = Some commitOrdinal then
                jp_declared_body_finish_through_owner <- None)

    let jp_required_work_slice_progress_read () =
        lock jp_required_work_slice_progress_gate (fun () -> jp_required_work_slice_progress_sequence)

    let jp_required_work_slice_progress_forget generation commitOrdinal =
        lock jp_required_work_slice_progress_gate (fun () ->
            let key = JpRequiredWorkSliceProgressKey(generation, commitOrdinal)
            jp_required_work_slice_progress_continuations.Remove key |> ignore
            if jp_declared_body_finish_through_owner = Some commitOrdinal then
                jp_declared_body_finish_through_owner <- None)

    let jp_required_work_slice_progress_forget_continuations () =
        lock jp_required_work_slice_progress_gate (fun () ->
            jp_required_work_slice_progress_continuations.Clear()
            jp_declared_body_finish_through_owner <- None)

    // MIGRATION: root-witness/global-fuse partial-current deferrals are valid
    // only while they expose fresh work. If the same partial current keeps
    // looping under the same preserved root witness, terminalize the liveness
    // bug instead of requiring a manual interrupt.
    // MIGRATION: this helper must stay non-inline. F# inline expansion cannot
    // legally capture the private ConcurrentDictionary across the generated
    // module boundary, which produced FS1113 at the helper definition.
    let private jp_global_fuse_partial_current_counts =
        System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,int>()
    let jp_note_global_fuse_partial_current (key: string) =
        if System.String.IsNullOrWhiteSpace key then 0
        else
            let keyRef = CompilerIdentityKernel.ContentDigest.ofText "jp-global-fuse-partial-current" key
            jp_global_fuse_partial_current_counts.AddOrUpdate(keyRef, 1, fun _ old -> old + 1)

    // MIGRATION: the historical runtime log was truncated by thousands of identical
    // semantic_root_complete source-value store receipts for the same type key.
    // Keep the semantic store and JP progress heartbeat on every occurrence, but
    // sample the diagnostic stream so the next frontier remains visible.
    let private jp_source_value_store_counts =
        System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,int>()

    let jp_note_source_value_store (key: string) =
        if System.String.IsNullOrWhiteSpace key then 0
        else
            let keyRef = CompilerIdentityKernel.ContentDigest.ofText "jp-source-value-store" key
            jp_source_value_store_counts.AddOrUpdate(keyRef, 1, fun _ old -> old + 1)

    let jp_unique_source_value_store_count () =
        jp_source_value_store_counts.Count

    // MIGRATION: each exact semantic epoch may request at most one owner-debt
    // cascade. Repeated drain observations of the same fact are procedural.
    let private jp_owner_debt_cascade_epochs =
        System.Collections.Concurrent.ConcurrentDictionary<int64,byte>()

    let jp_try_claim_owner_debt_cascade_epoch (epoch: int64) =
        epoch > 0L && jp_owner_debt_cascade_epochs.TryAdd(epoch, 0uy)

    let private jp_sparse_counts =
        System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,int64>()

    let jp_sparse_decision (key: string) (stride: int64) =
        let keyRef = CompilerIdentityKernel.ContentDigest.ofText "jp-sparse-key" key
        let occurrence = jp_sparse_counts.AddOrUpdate(keyRef, 1L, fun _ current -> current + 1L)
        let powerOfTwo = occurrence > 0L && (occurrence &&& (occurrence - 1L)) = 0L
        occurrence, (occurrence <= 3L || powerOfTwo || (stride > 0L && occurrence % stride = 0L))

    let jp_should_emit_source_value_store (repeat: int) =
        repeat <= 3
        || repeat = 8
        || repeat = 16
        || repeat = 32
        || repeat = 64
        || repeat = 128
        || repeat = 256
        || repeat % 512 = 0


