    /// ## HopacRuntimeHelpers
    // Hopac-only helpers the rest of hopac's core relies on (diagnostics sidecar, Interlocked wrappers).
    open System
    open System.Threading
    

    /// ### InterlockedEx
    /// Helpers to avoid inref/byref overload friction (especially with F# ref cells).
        
    
    



    /// ### DiagSidecar
    /// Best-effort, non-blocking telemetry buffer for diagnostics.
    /// Always enabled in MIGRATION+ for better parallel debugging. Lightweight enough to leave on.
    module DiagSidecar =
        open System
        open System.Collections.Concurrent
    

        let private maxItems = 512  // Increased buffer
        let private q = ConcurrentQueue<string>()

        type DiagSidecarKeyKind private () =
            static member InternedKindTag () = 0x120004u
        type private DiagSidecarKeyId = CompilerIdentityKernel.InternedTextId<DiagSidecarKeyKind>

        module private DiagSidecarKeyIdOps =
            let create value : DiagSidecarKeyId =
                CompilerIdentityKernel.InternedTextId.create<DiagSidecarKeyKind> value
            let text (value:DiagSidecarKeyId) = CompilerIdentityKernel.InternedTextIdOps.text value

        let private keyedCounts = System.Collections.Concurrent.ConcurrentDictionary<DiagSidecarKeyId,int>()
        let  private isPow2 (x:int) = x > 0 && (x &&& (x-1)) = 0

        // MIGRATION: keep the hot re-entry key classifier as a closed DU.
        // The sidecar still emits readable text, but the accounting path no longer
        // routes term/ty hotness by ad-hoc duplicated string branches.
        type DiagReentryHotKindId =
            | DiagReentryHotTerm
            | DiagReentryHotTy

        let private reentryHotPrefix = function
            | DiagReentryHotTerm -> "[spiral_compiler] EJP0011W|term_hot|"
            | DiagReentryHotTy -> "[spiral_compiler] EJP0011W|ty_hot|"

        let private tryReentryHotKind (msg: string) =
            if String.IsNullOrEmpty msg then None
            else
                let tokens = msg.Split([|' '; '\t'; '\r'; '\n'|], StringSplitOptions.RemoveEmptyEntries)
                match tokens |> Array.tryFindIndex ((=) "EJP0011W") with
                | Some index when index + 2 < tokens.Length && tokens.[index + 2] = "re-entry" ->
                    match tokens.[index + 1] with
                    | "term" -> Some DiagReentryHotTerm
                    | "ty" -> Some DiagReentryHotTy
                    | _ -> None
                | _ -> None


        let enabled () = true  // MIGRATION: always on
    

        let private enqueueRaw (msg: string) =
            q.Enqueue msg
            // best-effort trim: we prefer losing oldest telemetry to blocking the compiler.
            while q.Count > maxItems do
                let mutable v = Unchecked.defaultof<string>
                q.TryDequeue(&v) |> ignore

        let private sanitize (s: string) =
            let s =
                if String.IsNullOrEmpty s then ""
                else s.Replace("\r", "").Replace("\n", " ⏎ ")
            if s.Length > 480 then s.Substring(0, 480) + " ..." else s

        let private keyOf (msg: string) =
            let s = if String.IsNullOrEmpty msg then "" else msg.Trim()
            let parts = s.Split([| ' '; '\t'; '\r'; '\n' |], StringSplitOptions.RemoveEmptyEntries)
            if parts.Length > 0 && parts.[0] = "[spiral_compiler]" then
                if parts.Length >= 2 then parts.[0] + " " + parts.[1]
                else parts.[0]
            else
                let i = s.IndexOfAny([| ' '; '\t'; '\r'; '\n' |])
                if i > 0 then s.Substring(0, i)
                elif s.Length > 32 then s.Substring(0, 32)
                else s

        type DiagReentryFieldId =
            | DiagReentryKey

        let private tryReentryFieldValue fieldId (msg: string) =
            if String.IsNullOrWhiteSpace msg then None
            else
                let expectedKey =
                    match fieldId with
                    | DiagReentryKey -> "key"
                msg.Split([|' '; '\t'; '\r'; '\n'|], StringSplitOptions.RemoveEmptyEntries)
                |> Array.tryPick (fun field ->
                    let parts = field.Split([|'='|], 2, StringSplitOptions.None)
                    if parts.Length = 2 && parts.[0] = expectedKey && not (String.IsNullOrWhiteSpace parts.[1]) then
                        Some (parts.[1].Trim())
                    else None)

        let private noteEjp0011Hot (msg: string) =
            try
                match tryReentryHotKind msg, tryReentryFieldValue DiagReentryKey msg with
                | Some hotKind, Some key ->
                    let keyId = DiagSidecarKeyIdOps.create (reentryHotPrefix hotKind + key)
                    keyedCounts.AddOrUpdate(keyId, 1, (fun _ old -> old + 1)) |> ignore
                | _ -> ()
            with _ -> ()

        /// Emit sampled diagnostics (auto-keyed). First 3 always, then powers-of-two.
        let emit (msg: string) =
            noteEjp0011Hot msg
            let key = keyOf msg
            let keyId = DiagSidecarKeyIdOps.create key
            let c = keyedCounts.AddOrUpdate(keyId, 1, (fun _ old -> old + 1))
            if c <= 3 || isPow2 c then
                let m = sanitize msg
                let m = if c = 1 then m else sprintf "%s [count=%d]" m c
                enqueueRaw m
            else
                ()

        /// Emit sampled diagnostics keyed by <key>. First 3 always, then powers-of-two.
        let emitKeyedSample (key: string) (msg: string) =
            // MIGRATION: keyed sidecar sampling was the missing seam in MIGRATION.
            // Human EJP0011W lines could reach the retry sidecar through this path
            // while bypassing the hotkey counters read by build_retry_sota_triage.
            noteEjp0011Hot msg
            let keyId = DiagSidecarKeyIdOps.create key
            let c = keyedCounts.AddOrUpdate(keyId, 1, (fun _ old -> old + 1))
            if c <= 3 || isPow2 c then
                let m = sanitize msg
                enqueueRaw (sprintf "%s [count=%d]" m c)
            else
                ()
    

        let snapshot (maxTake: int) : string list =
            let arr = q.ToArray()
            if arr.Length = 0 then []
            else
                let n = if maxTake < 0 then 0 else min maxTake arr.Length
                arr.[arr.Length - n ..] |> Array.toList
    

        let private reentryHotKeyBelongsTo hotKind (key:string) =
            let prefix = reentryHotPrefix hotKind
            key.Length >= prefix.Length
            && String.Compare(key, 0, prefix, 0, prefix.Length, StringComparison.Ordinal) = 0

        /// Snapshot of top-k keyed counters matching a typed hot-key family (descending by count).
        let snapshotTopKeyed (hotKind:DiagReentryHotKindId) (k: int) : (string * int) list =
            try
                keyedCounts.ToArray()
                |> Array.choose (fun kv ->
                    let keyText = DiagSidecarKeyIdOps.text kv.Key
                    if reentryHotKeyBelongsTo hotKind keyText then Some(keyText, kv.Value)
                    else None)
                |> Array.sortByDescending snd
                |> Array.truncate (max 0 k)
                |> Array.toList
            with _ -> []

        let private shortKey (k: string) =
            let i = k.LastIndexOf('|')
            if i >= 0 && i + 1 < k.Length then k.Substring(i + 1) else k

        /// Human-friendly compact hotkeys string (k items). Each item is "<shortKey>:<count>".
        let snapshotTopKeyedShort (hotKind:DiagReentryHotKindId) (k: int) : string =
            snapshotTopKeyed hotKind k
            |> List.map (fun (key,c) -> sprintf "%s:%d" (shortKey key) c)
            |> String.concat " "

        /// Total count for a typed hot-key family. Used by structured retry triage
        /// to distinguish "no hotkey evidence" from "hotkey evidence was truncated from top-k".
        let snapshotTopKeyedCount (hotKind:DiagReentryHotKindId) : int =
            try
                keyedCounts.ToArray()
                |> Array.sumBy (fun kv ->
                    let keyText = DiagSidecarKeyIdOps.text kv.Key
                    if reentryHotKeyBelongsTo hotKind keyText then kv.Value else 0)
            with _ -> 0

        type EnvSnapshotEmissionState =
            | EnvSnapshotPending
            | EnvSnapshotEmitted

        let private envSnapshotEmissionGate = obj()
        let mutable private envSnapshotEmissionState = EnvSnapshotPending
        let emitEnvSnapshotOnce () =
            lock envSnapshotEmissionGate (fun () ->
                match envSnapshotEmissionState with
                | EnvSnapshotEmitted -> ()
                | EnvSnapshotPending ->
                    envSnapshotEmissionState <- EnvSnapshotEmitted
                    emit "---- ENV SNAPSHOT DISABLED (env_snapshot_no_env_var_reads: no env var reads) ----")
    

    /// ### dump_spiral_env_once
    /// Back-compat alias used by newer error paths.
    let dump_spiral_env_once () = DiagSidecar.emitEnvSnapshotOnce ()
    

    /// ### map_try_find_by_string
    /// Helper for maps keyed by (id, backend) pairs.
    let map_try_find_by_string (backend: string) (m: Map<(int * string), 'a>) : 'a option =
        m |> Map.tryPick (fun (_, b) v -> if b = backend then Some v else None)
    
#endif
    /// ## PersistentVectorExtensions
    // #!import '../../../polyglot/deps/The-Spiral-Language/The Spiral Language 2/PersistentVectorExtensions.fs'

    // #if !INTERACTIVE
    //     open Polyglot
    //     open Common
    //     open Lib
    // #endif

    open System
    open FSharpx.Collections

    /// ### range_checks
    let range_checks from near_to vec =
        if from <= near_to = false then
            Common.trace Common.Critical (fun () -> $"PersistentVectorExtensions.range_checks / `from` must be less or equal to `near_to`. / from: {from} / near_to: {near_to} / vec: {vec}") Common._locals
            // raise (ArgumentException("`from` must be less or equal to `near_to`."))
        if from < 0 then raise (ArgumentException("`from` must not be negative."))
        if PersistentVector.length vec < near_to then raise (ArgumentException("`near_to` must not be beyond the length of the vector."))

    /// ### replace
    /// O(n+m). Replace the specified range in a vector with the sequence.
    let replace from near_to seq vec =
        range_checks from near_to vec
        let rec rest s =
            if from < PersistentVector.length s then
                PersistentVector.unconj s |> fst |> rest
            else
                Seq.fold (fun s x -> PersistentVector.conj x s) s seq
        let rec init s =
            if near_to < PersistentVector.length s then
                let s',x = PersistentVector.unconj s
                PersistentVector.conj x (init s')
            else
                rest s
        init vec

    /// ### mapi
    /// O(n). Returns a vector of the supplied length using the supplied function operating on the index.
    let mapi f vec = PersistentVector.init (PersistentVector.length vec) (fun i -> f i vec.[i])

    /// ### iter
    /// O(n). Iterates over a vector using the supplied function operating on the index.
    let iter f vec =
        let rec loop i = if i < PersistentVector.length vec then f vec.[i]
        loop 0

    /// ### unzip
    /// O(n). Unzips a vector of pairs into pairs of vectors.
    let unzip vec =
        let mutable a = PersistentVector.empty
        let mutable b = PersistentVector.empty
        iter (fun (a',b') -> a <- PersistentVector.conj a' a; b <- PersistentVector.conj b' b) vec
        a,b

    /// ### concat
    /// O(n). Concatenates a vector of vectors.
    let concat vec = PersistentVector.fold (PersistentVector.append) PersistentVector.empty vec

    /// ### rangePersistentVector
    /// O(near_to-from). Get the vector at a range.
    let persistentVectorRange from near_to vec =
        range_checks from near_to vec
        PersistentVector.init (near_to-from) (fun i -> vec.[i+from])

    /// ### tryFindBack
    /// O(~n). Returns the last element for which a given function returns true. None if such an element does not exist.
    let tryFindBack f vec =
        let rec loop i =
            if 0 <= i then
                let x = PersistentVector.nth i vec
                if f x then Some x else loop (i-1)
            else
                None
        loop (PersistentVector.length vec - 1)

    /// ## HashConsing
    // Adapted from: https://github.com/backtracking/ocaml-hashcons
    // Type-Safe Modular Hash-Consing: https://www.lri.fr/~filliatr/ftp/publis/hash-consing2.pdf

    // open System
    open System.Runtime.InteropServices

    /// ### ConsedNode<'a>
    [<CustomComparison;CustomEquality;StructuredFormatDisplay("{AsString}")>]
    type ConsedNode<'a> =
        {
        node: 'a
        tag: int
        hkey: int
        }

        override x.ToString() = sprintf "<tag %i>" x.tag
        member x.AsString = x.ToString()
        override x.GetHashCode() = x.hkey
        override x.Equals(y) =
            match y with
            | :? ConsedNode<'a> as y -> x.tag = y.tag
            | _ -> false

        interface IComparable with
            member x.CompareTo(y) =
                match y with
                | :? ConsedNode<'a> as y -> compare x.tag y.tag
                | _ -> raise <| ArgumentException "Invalid comparison for HashConsed."

    /// ### HashConsTable
    type HashConsTable() =
        let mutable table: ResizeArray<GCHandle> [] = Array.init 7 (fun _ -> ResizeArray(0))
        let mutable total_size: int = 0
        let mutable limit: int = 3
        let mutable is_finalized: bool = false
        let mutable counter: int = 0
        let sync_root = obj()

        member private t.Resize() =
            let next_table_length x = x*3/2+3

            let table_length' = next_table_length table.Length
            if table_length' <= table.Length then failwith "The hash consing table cannot be grown anymore."
            let table' = Array.init table_length' (fun i -> ResizeArray())
            let limit' = limit+2
            let total_size' =
                let mutable total_size=0
                for i=0 to table.Length-1 do
                    let table = table.[i]
                    for i=0 to table.Count-1 do
                        let x = table.[i]
                        total_size <-
                            match x.Target with
                            | null ->
                                x.Free()
                                total_size
                            | a ->
                                let bucket = table'.[(hash a &&& Int32.MaxValue) % table_length']
                                bucket.Add x
                                total_size+1
                total_size
            table <- table'
            limit <- limit'
            total_size <- total_size'

        member t.Add(x: 'a): ConsedNode<'a> =
            lock sync_root (fun () ->
                let hkey = hash x
                let table = table
                let bucket = table.[(hkey &&& Int32.MaxValue) % Array.length table]
                let sz = bucket.Count

                let rec loop empty_pos i =
                    if i < sz then
                        match bucket.[i].Target with
                        | null -> loop i (i+1)
                        | :? ConsedNode<'a> as y when hkey = y.hkey && x = y.node -> y
                        | _ -> loop empty_pos (i+1)
                    else
                        let node = {node=x; hkey=hkey; tag=counter}
                        counter <- counter+1
                        if empty_pos <> -1 then
                            let mutable m = bucket.[empty_pos]
                            m.Target <- node
                        else
                            bucket.Add (GCHandle.Alloc(node,GCHandleType.Weak))
                            total_size <- total_size+1
                            if total_size > limit * Array.length table then t.Resize()
                        node

                loop -1 0 // `-1` indicates the state of no empty bucket
            )

        override __.Finalize() =
            if is_finalized = false then
                table |> (Array.iter << Seq.iter) (fun x -> x.Free())
                is_finalized <- true

    /// ### StripedHashConsTable (MIGRATION)
    /// Lock-free striped hash-consing with 32 shards using Fibonacci hashing.
    /// Eliminates the global sync_root bottleneck from HashConsTable.
    [<Sealed>]
    type StripedHashConsTable(shardCount: int) =
        let shardBits =
            let mutable bits = 0
            let mutable n = shardCount - 1
            while n > 0 do bits <- bits + 1; n <- n >>> 1
            bits
        let actualShardCount = 1 <<< shardBits
        let shardMask = actualShardCount - 1
        let shards = Array.init actualShardCount (fun _ -> HashConsTable())

        [<System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)>]
        member private _.GetShardIndex(hkey: int) =
            // Fibonacci hashing for better distribution
            let h = uint32 hkey
            let fib = 2654435769u  // 2^32 / phi
            int ((h * fib) >>> (32 - shardBits)) &&& shardMask

        member this.Add(x: 'a): ConsedNode<'a> =
            let hkey = hash x
            let shardIdx = this.GetShardIndex(hkey)
            shards.[shardIdx].Add(x)

    /// Default striped table with 32 shards (optimal for 8-16 core systems)
    let  createStripedHashConsTable () = StripedHashConsTable(32)

    /// ## Startup
    open Argu

    /// ### PrimitiveType
    type PrimitiveType =
        | UInt8T | UInt16T | UInt32T | UInt64T
        | Int8T | Int16T | Int32T | Int64T
        | Float32T | Float64T
        | BoolT | StringT | CharT

    /// ### DefaultEnv
    type DefaultEnv = {
        port : int
        default_int : PrimitiveType
        default_uint : PrimitiveType
        default_float : PrimitiveType
        }

    /// ### CliArguments
    type CliArguments =
        | [<Mandatory;Unique>] Port of int
        | [<Unique>] Default_Int of string
        | [<Unique>] Default_Float of string

        interface IArgParserTemplate with
            member s.Usage =
                match s with
                | Port _ -> "specify a primary port."
                | Default_Int _ -> "specify the default int: i8, i16, i32, i64, u8, u16, u32, u64"
                | Default_Float _ -> "specify the default float: f32, f64"

    /// ### parseStartup
    let startupParse args =
        let parser = ArgumentParser.Create<CliArguments>(programName = "spiral.exe")
        let results = parser.ParseCommandLine(args)
        let int =
            match results.GetResult(Default_Int,"i32") with
            | "i8" -> Int8T
            | "i16" -> Int16T
            | "i32" -> Int32T
            | "i64" -> Int64T
            | "u8" -> UInt8T
            | "u16" -> UInt16T
            | "u32" -> UInt32T
            | "u64" -> UInt64T
            | x -> failwith $"Invalid default int.\nGot: %s{x}\nExpected one of: i8, i16, i32, i64, u8, u16, u32, u64"

        let uint =
            match int with
            | Int8T -> UInt8T
            | Int16T -> UInt16T
            | Int32T -> UInt32T
            | Int64T -> UInt64T
            | x -> x // If the int is unsigned then make them the same type.
        {
        port = results.GetResult(Port)
        default_int = int
        default_uint = uint
        default_float =
            match results.GetResult(Default_Float,"f64") with
            | "f32" -> Float32T
            | "f64" -> Float64T
            | x -> failwith $"Invalid default float.\nGot: %s{x}\nExpected one of: f32, f64"
        }

