    module DiagLastWait =
        type private DiagLastWaitState =
            | DiagLastWaitMissing
            | DiagLastWaitObserved of detail:string

        let mutable private state = DiagLastWaitMissing

        let reset () =
            state <- DiagLastWaitMissing

        let set (detail: string) =
            state <- DiagLastWaitObserved detail

        let get () =
            match state with
            | DiagLastWaitMissing -> ""
            | DiagLastWaitObserved detail -> detail

