            | DiagnosticPatternMissTermProducer -> "pattern_miss_term_producer"
            | DiagnosticPatternMissTypeProducer -> "pattern_miss_type_producer"
            | DiagnosticPatternMissControlOnlyReplay -> "pattern_miss_control_only_replay"
            | DiagnosticPatternMissRequiredCodegenBody -> "pattern_miss_required_codegen_body"
            | DiagnosticPatternMissStasisCancelled -> "pattern_miss_stasis_cancelled"
            | DiagnosticPatternMissBreakthroughEscape -> "pattern_miss_breakthrough_escape"
            | DiagnosticTerminalClosedWorldPromiseOnlyResidual -> "terminal_closed_world_promise_only_residual"

        let factSetText (facts:Set<DiagnosticFactId>) =
            facts
            |> Seq.map factText
            |> Seq.sort
            |> String.concat "|"

        let factListText (facts:Set<DiagnosticFactId>) =
            facts
            |> Set.toList
            |> List.map factText

        let private classified facts code cause disposition =
            ClassifiedIngress { code = code; cause = cause; disposition = disposition; facts = facts }

        // This is the only lexical admission boundary for EJP control flow.
        // Raw text becomes a recursive evidence pattern here; downstream code receives DUs.
        type DiagnosticIngressEvidencePattern =
            | DiagnosticIngressAllTokens of required:Set<string>
            | DiagnosticIngressAllSegments of required:Set<string>
            | DiagnosticIngressAny of DiagnosticIngressEvidencePattern list

        let private diagnosticIngressDelimiters =
            [| '|'; '@'; '/'; ':'; '('; ')'; '['; ']'; '{'; '}'; ','; ';'; '='; ' '; '\t'; '\r'; '\n'; '"'; '\'' |]

        let private diagnosticIngressTokens (text:string) =
            if String.IsNullOrWhiteSpace text then Set.empty
            else
                text.Split(diagnosticIngressDelimiters, StringSplitOptions.RemoveEmptyEntries)
                |> Array.map (fun token -> token.ToLowerInvariant())
                |> Set.ofArray

        let private diagnosticIngressSegments (tokens:Set<string>) =
            tokens
            |> Seq.collect (fun token ->
                token.Split([| '_'; '-' |], StringSplitOptions.RemoveEmptyEntries)
                :> seq<string>)
            |> Set.ofSeq

        let private diagnosticIngressPatternFor (needle:string) =
            let tokens = diagnosticIngressTokens needle
            let segments = diagnosticIngressSegments tokens
            DiagnosticIngressAny [
                DiagnosticIngressAllTokens tokens
                DiagnosticIngressAllSegments segments
            ]

        let rec private diagnosticIngressPatternMatches messageTokens messageSegments = function
            | DiagnosticIngressAllTokens required ->
                not (Set.isEmpty required) && Set.isSubset required messageTokens
            | DiagnosticIngressAllSegments required ->
                not (Set.isEmpty required) && Set.isSubset required messageSegments
            | DiagnosticIngressAny patterns ->
                patterns
                |> List.exists (diagnosticIngressPatternMatches messageTokens messageSegments)

        let private has (needle:string) (message:string) =
            let messageTokens = diagnosticIngressTokens message
            let messageSegments = diagnosticIngressSegments messageTokens
            diagnosticIngressPatternFor needle
            |> diagnosticIngressPatternMatches messageTokens messageSegments

        let private hasAll needles message = needles |> List.forall (fun needle -> has needle message)
        let private hasAny needles message = needles |> List.exists (fun needle -> has needle message)
        let private hasCode code message = has (codeText code) message

        let private messageHasSpiralSourceSite (message:string) =
            if String.IsNullOrWhiteSpace message then false
            else
                message.Replace('\\', '/').Split(
                    [| '|'; '@'; '/'; ':'; '('; ')'; '['; ']'; '{'; '}'; ','; ';'; '='; ' '; '\t'; '\r'; '\n'; '"'; '\'' |],
                    StringSplitOptions.RemoveEmptyEntries)
                |> Array.exists (fun token ->
                    match System.IO.Path.GetExtension(token.ToLowerInvariant()) with
                    | ".spi"
                    | ".spir" -> true
                    | _ -> false)

        let private factsFor message =
            [
                DiagnosticGenerationChangedWhileWaiting, has "generation changed while waiting" message
                DiagnosticDeadIvarWhileWaiting, has "dead ivar while waiting" message
                DiagnosticBigStackGenerationChanged, hasAll ["BigStack"; "generation change"] message
                DiagnosticGlobalTermCycleFuseTripped, has "global term-cycle fuse already tripped" message
                DiagnosticJpWaitObservedSequentialTermCycle, has "jp_wait observed sequential term-cycle fuse" message
                DiagnosticReentrantTermCycle, has "re-entrant term evaluation cycle detected" message
                DiagnosticReentrantTypeCycle, has "re-entrant type evaluation cycle detected" message
                DiagnosticBigStackSemanticRootCompleteHandoff, has "BigStack join observed semantic_root_complete handoff" message
                DiagnosticSemanticRootComplete, has "semantic_root_complete" message
                DiagnosticFrameSemanticRootComplete, has "frame_status=semantic_root_complete" message
                DiagnosticReplayComplete, has "replay_complete=true" message
                DiagnosticBigStackJoinObserved, has "BigStack join observed" message
                DiagnosticSidecarTyReentryPrefetch, has "sidecar_ty_reentry_prefetch" message
                DiagnosticSidecarTermReentryPrefetch, has "sidecar_term_reentry_prefetch" message
                DiagnosticSpiralSourceSite, messageHasSpiralSourceSite message
                DiagnosticParentContinuationDeferred, hasAny ["semantic_parent_continuation_cycle_deferred"; "parent_continuation_cycle_deferred"; "deferred_child_cell"] message
                DiagnosticDeferredChildCell, has "deferred_child_cell" message
                DiagnosticNativePromiseFailure, hasAny ["native_promise_failure"; "native promise failure"] message
                DiagnosticRecordMapExpectedRecordFailure, hasAny ["ExpectedRecordButGotNonRecordInRecordMap"; "record_map_expected_record"; "Expected a record"] message
                DiagnosticDynamicJoinRuntimeDynTypecheck, has "runtime_function_apply_requires_dyn_typecheck" message
                DiagnosticDynamicJoinFunctionBodyDynamicArg, has "term_apply_function_body_dynamic_arg_blocked" message
                DiagnosticTyParentContinuationReplayCapExhausted, has "ty parent-continuation replay cap exhausted" message
                DiagnosticParentContinuationReplayCapExhausted, has "parent-continuation replay cap exhausted" message
                DiagnosticBlockedByReentry, has "blocked_by_reentry" message
                DiagnosticStackOverflow, hasAny ["stack overflow"; "StackOverflow"] message
                DiagnosticPartEvalTypeError, has "PartEvalTypeError" message
                DiagnosticReentrantReplayDriver, has "reentrant_replay_driver" message
                DiagnosticDynamicFunctionBridge, has "dynamic_function_bridge" message
                DiagnosticPinnedTerminalContract, has "EJP0021" message && hasAll ["pinned"; "terminal"; "contract"] message
                DiagnosticStaleActiveGlobalFuseTerminal, has "EJP0021" message && has "accepted_stale_active_no_queue_bounded_global_fuse_terminal" message
                DiagnosticBigStackJoinStalled, hasAll ["BigStack"; "join"; "stalled"] message
                DiagnosticBigStackTermDepthJoinStalled, hasAll ["BigStack"; "join"; "stalled"; "term_depth"] message
                DiagnosticDeferredType, hasAny ["DeferredTypeVar"; "deferred_type"] message
                DiagnosticHole, has "hole" message
                DiagnosticTerminalPoisonCascade, has "terminal_poison_cascade" message
                DiagnosticAppRootFinalizationSelfLoop, has "app_root_base16_root_witness_finalization_self_loop" message
                DiagnosticTimedOut, has "Timed out" message
                DiagnosticTerminalLetCycleReplay, has "terminal_let_cycle_replay" message
                DiagnosticTerminalCompositeCycleReplay, has "terminal_composite_cycle_replay" message
                DiagnosticReplayPrefetch, has "prefetch" message
                DiagnosticReplayMissingAfterPrefetch, hasAny ["missing_after_prefetch"; "missing after prefetch"] message
                DiagnosticReplayFrameStale, has "stale" message
                DiagnosticReplayAppRootBase16, has "app_root_base16" message
                DiagnosticReplayRootWitnessFinalizationSelfLoop, has "root_witness_finalization_self_loop" message
                DiagnosticReplayLiveLivelock, has "live_replay_livelock" message
                DiagnosticReplayStaleRetarget, has "stale_retarget" message
                DiagnosticReplayParentStatusPreservedRepeat, has "parent_replay_status_preserved_repeat" message
                DiagnosticReplayCacheHandoff, has "cache_handoff" message
                DiagnosticReplayCooperativeHandoff, has "cooperative_replay_handoff" message
                DiagnosticReplayCacheWriteParentHandoff, has "cache_write_parent_handoff" message
                DiagnosticReplayPostCommitParentQueueDriverTick, has "post_commit_parent_queue_driver_tick" message
                DiagnosticReplayNoRootBudget, has "no_root_budget" message
                DiagnosticReplayBigStackNoRootBudget, has "bigstack_no_root_budget" message
                DiagnosticReplayMaterializedTerminalBeatsNoRootBudget, has "materialized_terminal_beats_no_root_budget" message
                DiagnosticReplayJoinWait, has "join_wait" message
                DiagnosticReplayTermReentryPrefetch, has "term_reentry_prefetch" message
                DiagnosticReplayTyReentryPrefetch, has "ty_reentry_prefetch" message
                DiagnosticReplayReentryPrefetch, has "reentry_prefetch" message
                DiagnosticReplayHardPoisonObligation, has "hard_poison_obligation" message
                DiagnosticReplayParentReplay, has "parent_replay" message
                DiagnosticReplayPoison, has "poison" message
                DiagnosticReplayDynamicJoin, has "dynamic_join" message
                DiagnosticReplayDynamicRecordKeyBridge, has "dynamic_record_key_bridge" message
                DiagnosticReplayBridgeTail, has "bridge_tail" message
                DiagnosticReplayIdleCrossKind, has "idle_cross_kind" message
                DiagnosticReplayActiveTySidecar, has "active_ty_sidecar" message
                DiagnosticPatternMissStasisCancelled,
                    has "pattern_miss_stasis_cancelled" message
                    || hasAll ["typed"; "pattern-miss"; "stasis"; "cancelled"] message
            ]
            |> List.choose (fun (fact, present) -> if present then Some fact else None)
            |> Set.ofList

        // factsFor runs ~70 substring searches; the replay driver classifies the same few reason texts on
        // every pinned terminal cell (~4% of a compile). Pure, so memoized by text (bounded).
        let private factsMemo = System.Collections.Concurrent.ConcurrentDictionary<string, _>(System.StringComparer.Ordinal)

        let classifyFacts (message:string) =
            if isNull message || message.Length > 4096 then factsFor message
            else
                let mutable facts = Unchecked.defaultof<_>
                if factsMemo.TryGetValue(message, &facts) then facts
                else
                    let facts = factsFor message
                    if factsMemo.Count < 50000 then factsMemo.TryAdd(message, facts) |> ignore
                    facts

        let hasFact fact classification = Set.contains fact classification.facts

        let classifyIngress (message:string) : DiagnosticIngress =
            let facts = classifyFacts message
            if has "Cannot construct an instance of a void type" message
               || hasAll ["void type"; "Cannot construct"] message then
                classified facts DiagnosticEJP0013 DiagnosticVoidInstanceConstruction DiagnosticRetryAfterCacheInvalidation
            elif hasAny [
                    "jp_wait live frame closed by native promise failure"
                    "jp_wait explicit-worklist tail closed by native promise failure"
                    "parent_continuation_cycle_deferred_native_promise_failure_closed"
                    "terminal_cause_du=parent_continuation_replay_cap_exhausted"
                    "terminal_poison_cascade:deferred_child_cell"
                ] message
                || hasAll ["native_promise_failure_latched"; "root_complete_await_failed_closed_exit_1"] message
                || hasAll ["root_complete"; "handoff exhausted"; "native_promise_failure_latched"] message then
                classified facts DiagnosticEJP0032 DiagnosticNativePromiseFailedClosed DiagnosticTerminalNative
            elif hasCode DiagnosticEJP0033 message
                 || has "ExpectedRecordButGotNonRecordInRecordMap" message
                 || hasAll ["record_map"; "Expected a record"] message then
                classified facts DiagnosticEJP0033 DiagnosticRecordMapSemanticTerminal DiagnosticTerminalSemantic
            elif hasCode DiagnosticEJP0035 message then
                classified facts DiagnosticEJP0035 DiagnosticRequiredCodegenBodyUnmaterialized DiagnosticTerminalNative
            elif hasCode DiagnosticEJP0034 message || hasAll ["CODEGEN"; "JP"; "MALFORMED"] message then
                classified facts DiagnosticEJP0034 DiagnosticCodegenBodyMalformed DiagnosticTerminalSemantic
            elif has "apply mismatch" message then
                classified facts DiagnosticEJP0007 DiagnosticPrimitiveAppliedAsFunction DiagnosticRetryAfterCacheInvalidation
            elif hasAll ["pinned terminal contract"; "jp_wait stall"] message
                 || has "jp_stall_terminal_abort_without_retry" message then
                classified facts DiagnosticEJP0011 DiagnosticReentryCycle DiagnosticTerminalSemantic
            elif hasCode DiagnosticEJP0011 message || hasAll ["Re-entrant"; "cycle"] message then
                classified facts DiagnosticEJP0011 DiagnosticReentryCycle DiagnosticRetrySequential
            elif hasCode DiagnosticEJP0010 message
                 || has "Insufficient execution stack" message
                 || hasAll ["stack overflow"; "preempt"] message then
                classified facts DiagnosticEJP0010 DiagnosticInsufficientExecutionStack DiagnosticRetrySequential
            elif hasCode DiagnosticEJP0009 message
                 || (has "recursion depth" message && hasAny ["exceeded"; "overflow"] message) then
                classified facts DiagnosticEJP0009 DiagnosticRecursionDepthExceeded DiagnosticRetrySequential
            elif has "Expected a function" message
                 && hasAny ["Got: i32"; "Got: i64"; "Got: f32"; "Got: f64"; "Got: bool"] message then
                classified facts DiagnosticEJP0007 DiagnosticPrimitiveAppliedAsFunction DiagnosticRetryAfterCacheInvalidation
            elif hasAll ["annotation of the function"; "does not match its body's type"] message
                 && hasAny ["JPMethodRecPlaceholder"; "JPTypeRecPlaceholder"] message then
                classified facts DiagnosticEJP0002 DiagnosticJoinPointAnnotationMismatch DiagnosticRetryAfterCacheInvalidation
            elif hasAll ["annotation"; "mismatch"] message then
                classified facts DiagnosticEJP0002 DiagnosticJoinPointAnnotationMismatch DiagnosticRetryAfterCacheInvalidation
            elif has "specialization cap" message || hasCode DiagnosticEJP0012 message then
                classified facts DiagnosticEJP0012 DiagnosticSpecializationCapExceeded DiagnosticRetrySequential
            elif hasCode DiagnosticEJP0008 message || has "generation changed while waiting" message then
                classified facts DiagnosticEJP0008 DiagnosticStaleJoinPointArtifact DiagnosticRetryAfterCacheInvalidation
            elif has "JpIvarWaitFailureOwnedButStalled(" message then
                classified facts DiagnosticEJP0014 DiagnosticOwnedSetStall DiagnosticTerminalSemantic
            elif has "RootPromiseProjectionMigrationUnsatisfied(" message then
                classified facts DiagnosticEJP0014 DiagnosticRootProjectionMigrationUnsatisfied DiagnosticTerminalSemantic
            elif hasCode DiagnosticEJP0014 message || hasAny ["scheduler stalled while waiting"; "jp_wait stalled"] message then
                classified facts DiagnosticEJP0014 DiagnosticSchedulerStall DiagnosticRetryAfterSchedulerRecovery
            elif hasCode DiagnosticEJP0016 message || has "dead ivar while waiting" message then
                classified facts DiagnosticEJP0016 DiagnosticDeadIvar DiagnosticRetryAfterCacheInvalidation
            elif hasCode DiagnosticEJP0018 message || hasAll ["BigStack"; "join"; "aborted"] message then
                classified facts DiagnosticEJP0018 DiagnosticBigStackGenerationAbort DiagnosticRetryAfterCacheInvalidation
            elif Set.contains DiagnosticBigStackSemanticRootCompleteHandoff facts then
                classified facts DiagnosticEJP0019 DiagnosticBigStackRootCompleteHandoff DiagnosticRetryAfterSchedulerRecovery
            elif hasCode DiagnosticEJP0019 message || hasAll ["BigStack"; "join"; "stalled"] message then
                classified facts DiagnosticEJP0019 DiagnosticBigStackStall DiagnosticRetryAfterSchedulerRecovery
            elif hasCode DiagnosticEJP0020 message || hasAll ["BigStack"; "join"; "interrupted"] message then
                classified facts DiagnosticEJP0020 DiagnosticBigStackInterrupted DiagnosticRetryAfterSchedulerRecovery
            elif hasCode DiagnosticEJP0030 message then
                classified facts DiagnosticEJP0030 DiagnosticWatchdogProgressStall DiagnosticRetryAfterSchedulerRecovery
            elif hasCode DiagnosticEJP0031 message then
                classified facts DiagnosticEJP0031 DiagnosticWatchdogOperationTimeout DiagnosticRetryAfterSchedulerRecovery
            elif hasAll ["variables compared for equality"; "same type"] message then
                classified facts DiagnosticEJP0003 DiagnosticParallelTypeMismatch DiagnosticRetryAfterCacheInvalidation
            elif has "Cannot apply" message
                 && hasAny ["JPMethodRecPlaceholder"; "JPTypeRecPlaceholder"; "JPMethodUnknownRet"] message then
                classified facts DiagnosticEJP0008 DiagnosticStaleJoinPointArtifact DiagnosticRetryAfterCacheInvalidation
            elif hasAny ["type mismatch"; "Cannot apply"] message then
                classified facts DiagnosticEJP0003 DiagnosticParallelTypeMismatch DiagnosticRetryAfterCacheInvalidation
            else
                UnclassifiedIngress facts

        let isNoRetry classification =
            match classification.disposition with
            | DiagnosticTerminalNative
            | DiagnosticTerminalSemantic -> true
            | _ -> false

        let isRetryable classification = not (isNoRetry classification)

        let describe classification =
            match classification.cause with
            | DiagnosticJoinPointAnnotationMismatch -> "Join point annotation type mismatch"
            | DiagnosticParallelTypeMismatch -> "Type error during parallel evaluation"
            | DiagnosticPrimitiveAppliedAsFunction -> "Apply type mismatch: primitive where callable expected"
            | DiagnosticStaleJoinPointArtifact -> "Deep recursion cache corruption"
            | DiagnosticRecursionDepthExceeded -> "Term/type recursion depth exceeded"
            | DiagnosticInsufficientExecutionStack -> "Insufficient execution stack (stack overflow preempted)"
            | DiagnosticReentryCycle -> "Re-entrant term evaluation cycle detected"
            | DiagnosticSpecializationCapExceeded -> "Loop specialization cap exceeded"
            | DiagnosticVoidInstanceConstruction -> "Void instance construction (likely cache corruption)"
            | DiagnosticSchedulerStall -> "Join-point scheduler stall detected while waiting"
            | DiagnosticOwnedSetStall -> "Owned join-point work set made no progress and is terminally stalled"
            | DiagnosticRootProjectionMigrationUnsatisfied -> "Migrated root projection has no durable replacement receipt"
            | DiagnosticDeadIvar -> "Dead IVar detected while waiting (stale JP state)"
            | DiagnosticBigStackGenerationAbort -> "BigStack join aborted due to cache generation change"
            | DiagnosticBigStackRootCompleteHandoff -> "BigStack semantic root handoff observed after canonical root resolution"
            | DiagnosticBigStackStall -> "BigStack join stalled (possible deadlock / runaway job)"
            | DiagnosticBigStackInterrupted -> "BigStack join interrupted (treated as retryable abort)"
            | DiagnosticWatchdogProgressStall -> "JP watchdog abort (progress stalled / oldest job too old)"
            | DiagnosticWatchdogOperationTimeout -> "JP watchdog abort (a specific job exceeded its per-op timeout)"
            | DiagnosticNativePromiseFailedClosed -> "Native promise failure terminal reached (no legacy retry)"
            | DiagnosticRecordMapSemanticTerminal -> "RecordMap expected-record semantic terminal reached (no legacy retry)"
            | DiagnosticCodegenBodyMalformed -> "Codegen join-point body cell resolved to a malformed producer state (no legacy retry)"
            | DiagnosticRequiredCodegenBodyUnmaterialized -> "Required codegen join-point body was cancelled before any material body became authoritative"
    

    // BONUS 2077: one shared sticky-tail/owner-debt domain for both the
    // DiagJson observer projection and the authoritative reducer.  Keeping
    // these types in the enclosing compiler module removes the duplicated
    // 16k/68k type universes without granting the renderer exit authority.
    [<Struct>]
    type TerminalFlowStickyTailMutatingKind = struct end

    [<Struct>]
    type TerminalFlowStickyTailProceduralKind = struct end

    [<Struct>]
    type TerminalFlowMutatingTailOpenPhase = struct end

    [<Struct>]
    type TerminalFlowMutatingTailDrainedPhase = struct end

    [<Struct>]
    type TerminalFlowProceduralResidualAttachedPhase = struct end

    [<Struct>]
    type TerminalFlowProceduralResidualDetachedPhase = struct end

    type TerminalFlowWakerRegistrationStatus =
        | TerminalFlowWakerMissing
        | TerminalFlowWakerRegistered of obligationId:string * registeredAtMs:int64
        | TerminalFlowWakerExpired of obligationId:string * ageMs:int64

    // Domain migration : waker registration is a registry verdict, not a string.
    // The stage-token edge and sticky-tail cell are different authority sources;
    // JSON erases them only after the reducer has a typed verdict.
    type TerminalFlowWakerRegistrySource =
        | TerminalFlowWakerRegistryStageToken
        | TerminalFlowWakerRegistryStickyTail
        | TerminalFlowWakerRegistryShutdownHook

    type TerminalFlowWakerRegistryVerdict =
        | TerminalFlowWakerRegistryMissing of source:TerminalFlowWakerRegistrySource
        | TerminalFlowWakerRegistryRegistered of source:TerminalFlowWakerRegistrySource * obligationId:string * registeredAtMs:int64
        | TerminalFlowWakerRegistryExpired of source:TerminalFlowWakerRegistrySource * obligationId:string * ageMs:int64
        | TerminalFlowWakerRegistryObservedByAltChoose of source:TerminalFlowWakerRegistrySource * obligationRef:uint32

    type TerminalFlowMutatingTailCapability<'Phase> = private {
        tailId : string
        depth : int
        evidenceRef : uint32
    }

    type TerminalFlowProceduralResidualOwner<'Phase> = private {
        ownerId : string
        closeKey : string
        depth : int
        drainPassCount : int
        materialDeltaOnPass : int
        fixedPointRepeatCap : int
        wakerStatus : TerminalFlowWakerRegistrationStatus
    }

    type TerminalFlowTerminalizationPermit =
        | TerminalFlowTerminalizationBlockedByMutatingTail of TerminalFlowMutatingTailCapability<TerminalFlowMutatingTailOpenPhase>
        | TerminalFlowTerminalizationReady of
            TerminalFlowMutatingTailCapability<TerminalFlowMutatingTailDrainedPhase> *
            TerminalFlowProceduralResidualOwner<TerminalFlowProceduralResidualDetachedPhase> option

    type TerminalFlowStickyTailSnapshot = private {
        tailId : string
        mutatingDepth : int
        proceduralDepth : int
        globalPending : int
        globalQueue : int
        globalActive : int
        fixedPointRepeat : int
        proceduralDrainPassCount : int
        materialDeltaOnProceduralPass : int
        fixedPointRepeatCap : int
        materialQuiescenceAgeMs : int64
        evaluatorFrontierResolved : bool
        wakerStatus : TerminalFlowWakerRegistrationStatus
        aggregatePromiseArmed : bool
        mutatingTailDrained : bool
        evidence : string
        residualTopK : string list
    }

    type TerminalFlowStickyTailGateId =
        | TerminalFlowStickyTailAwaitMutatingAggregate of TerminalFlowStickyTailSnapshot
        | TerminalFlowStickyTailWriterReady of
            TerminalFlowStickyTailSnapshot *
            TerminalFlowProceduralResidualOwner<TerminalFlowProceduralResidualDetachedPhase> option
        | TerminalFlowStickyTailDrained of TerminalFlowStickyTailSnapshot
        | TerminalFlowStickyTailQuarantineProceduralResidual of TerminalFlowStickyTailSnapshot * reason:CompilerIdentityKernel.OperationalReasonId
        | TerminalFlowStickyTailRejectUnboundedMutatingTail of TerminalFlowStickyTailSnapshot * reason:CompilerIdentityKernel.OperationalReasonId

    module TerminalFlowBreakthrough =

        type CollectingStage = class end
        type QapResolvedStage = class end
        type OwnerTailSealedStage = class end
        type SemanticReadyStage = class end
        type OrderReadyStage = class end
        type CommittedStage = class end
        type DoneStage = class end
        type RunEndedStage = class end
        type ExitSelectedStage = class end

        [<Struct>]
        type PhaseToken<'Stage> = private | PhaseToken of uint32

        type QapClosure =
            | QapMaterialProgress of qapRef:uint32 * materialEpoch:int64
            | QapFullyDrained of qapRef:uint32 * drainProofRef:uint32 * relationReceiptRefs:uint32 list
            | QapProvenDeadlock of qapRef:uint32 * deadlockProofRef:uint32 * relationReceiptRefs:uint32 list

        type OwnerTailClosure =
            | OwnerTailOpen of ownerLedgerRef:uint32 * openOwners:int
            | OwnerTailSealed of ownerCertificateRef:uint32 * workDagTailProofRef:uint32 * closedOwners:int * acyclicByConstruction:bool

        type SemanticFactStatus =
            | SemanticFactMissing
            | SemanticFactExactOnce of semanticDigest:uint32 * materialEpoch:int64 * producerRef:uint32 * exactOnceRef:uint32

        type SchedulerAuthority =
            | SchedulerSpawnNotGranted
            | SchedulerSpawnGranted of grantRef:uint32 * maxConcurrentDrivers:int * semanticDebtBefore:int64 * semanticDebtAfter:int64

        type CicKernelAuthority =
            | CicKernelNotObserved
            | CicKernelActive of countersRef:uint32 * termCount:int64 * defEqOpen:int64 * universeOpen:int64
            | CicKernelQuiescent of countersRef:uint32 * termCount:int64 * whnfHits:int64 * defEqSolved:int64 * universeIterations:int64
            | CicKernelRejectedMetavars of countersRef:uint32 * metavarsInKernel:int64

        type BackendTargetId =
            | BackendTargetUnknown
            | BackendTargetFSharp
            | BackendTargetRust
            | BackendTargetGleam
            | BackendTargetHvm

        type BackendVerificationProvenance =
            | BackendVerificationRuntimeReceipt
            | BackendVerificationFixtureProjection

        type BackendVerificationEvidence = private {
            target : BackendTargetId
            artifactRef : CompilerIdentityKernel.ContentDigest
            semanticClosureRef : CompilerIdentityKernel.ContentDigest
            conformanceRef : CompilerIdentityKernel.ContentDigest
            provenance : BackendVerificationProvenance
        }

        type BackendLoweringAuthority =
            | BackendLoweringNotPrepared of BackendTargetId
            | BackendLoweringPrepared of target:BackendTargetId * artifactRef:CompilerIdentityKernel.ContentDigest
            | BackendLoweringVerified of BackendVerificationEvidence
            | BackendLoweringRejected of target:BackendTargetId * artifactRef:CompilerIdentityKernel.ContentDigest * conformanceRef:CompilerIdentityKernel.ContentDigest * reason:CompilerIdentityKernel.OperationalReasonId

        let backendVerificationEvidence target artifactRef semanticClosureRef conformanceRef provenance =
            { target = target
              artifactRef = artifactRef
              semanticClosureRef = semanticClosureRef
              conformanceRef = conformanceRef
              provenance = provenance }

        type CredentialKind =
            | DeterminismCredential
            | FairnessCredential
            | RecoveryCredential
            | GreenPathCredential
            | WriterCapabilityCredential
            | ArtifactCovenantCredential

        type CredentialMinter =
            | CredentialMinter of kind:CredentialKind * credentialRef:uint32 * minterRef:uint32 * exactOnceRef:uint32

        type BreakthroughCovenant =
            | BreakthroughCovenantMissing
            | BreakthroughCovenantObserved of predecessorRef:uint32 * credentials:CredentialMinter list

        type LegacyProjectionSurface =
            | DiagJsonTerminalFlowMirror
            | BigStackTerminalFlowMirror
            | EvalWorklistTerminalMirror
            | HudTerminalMirror

        type LegacyProjectionBoundaryReceipt =
            | LegacyProjectionBoundaryReceipt of surface:LegacyProjectionSurface * sourceRef:uint32 * projectionRef:uint32

        type TerminalIntent =
            | TerminalBuildOk
            | TerminalFailClosed

        type ReceiptChain =
            | TerminalOrderMissing
            | TerminalOrderMinted of orderRef:uint32 * predecessorRef:uint32 * exactOnceRef:uint32
            | TerminalCommitted of orderRef:uint32 * commitRef:uint32
            | TerminalDone of commitRef:uint32 * doneRef:uint32
            | TerminalRunEnded of doneRef:uint32 * runEndRef:uint32
            | TerminalPhysicalExitSelected of runEndRef:uint32 * exitRef:uint32

        type Facts<'OwnerKind> = private {
            ownerKind : 'OwnerKind option
            authorityRef : uint32
            qap : QapClosure option
            ownerTail : OwnerTailClosure
            semanticFact : SemanticFactStatus
            scheduler : SchedulerAuthority
            cic : CicKernelAuthority
            backend : BackendLoweringAuthority
            covenant : BreakthroughCovenant
            terminalIntent : TerminalIntent option
            receipts : ReceiptChain
            shutdownRequestRef : uint32 option
            revision : int64
        }

        type State<'OwnerKind> =
            | Collecting of PhaseToken<CollectingStage> * Facts<'OwnerKind>
            | QapResolved of PhaseToken<QapResolvedStage> * Facts<'OwnerKind>
            | OwnerTailSealedState of PhaseToken<OwnerTailSealedStage> * Facts<'OwnerKind>
            | SemanticReady of PhaseToken<SemanticReadyStage> * Facts<'OwnerKind>
            | OrderReady of PhaseToken<OrderReadyStage> * Facts<'OwnerKind>
            | Committed of PhaseToken<CommittedStage> * Facts<'OwnerKind>
            | Done of PhaseToken<DoneStage> * Facts<'OwnerKind>
            | RunEnded of PhaseToken<RunEndedStage> * Facts<'OwnerKind>
            | ExitSelected of PhaseToken<ExitSelectedStage> * Facts<'OwnerKind>

        type Command =
            | ObserveQap of QapClosure
            | SealOwnerTail of OwnerTailClosure
            | MintSemanticFact of semanticDigest:uint32 * materialEpoch:int64 * producerRef:uint32 * exactOnceRef:uint32
            | RejectNativeEvalWithoutSemanticFact of workUnitRef:uint32 * rejectionRef:uint32
            | GrantSchedulerSpawn of grantRef:uint32 * maxConcurrentDrivers:int * semanticDebtBefore:int64 * semanticDebtAfter:int64
            | ObserveCicKernel of CicKernelAuthority
            | PrepareBackendLowering of BackendLoweringAuthority
            | ObserveBreakthroughCovenant of BreakthroughCovenant
            | ProjectLegacySurface of LegacyProjectionBoundaryReceipt
            | MintTerminalOrder of intent:TerminalIntent * orderRef:uint32 * predecessorRef:uint32 * exactOnceRef:uint32
            | CommitTerminal of commitRef:uint32
            | MarkTerminalDone of doneRef:uint32
            | EmitRunEnd of runEndRef:uint32
            | SelectPhysicalExit of exitRef:uint32
            | RequestHostShutdown of shutdownRequestRef:uint32

        type BreakthroughPhaseId =
            | BreakthroughPhaseCollecting
            | BreakthroughPhaseQapResolved
            | BreakthroughPhaseOwnerTailSealed
            | BreakthroughPhaseSemanticReady
            | BreakthroughPhaseOrderReady
            | BreakthroughPhaseCommitted
            | BreakthroughPhaseDone
            | BreakthroughPhaseRunEnded
            | BreakthroughPhaseExitSelected

        type BreakthroughCommandKindId =
            | BreakthroughCommandObserveQap
            | BreakthroughCommandSealOwnerTail
            | BreakthroughCommandMintSemanticFact
            | BreakthroughCommandRejectNativeEvalWithoutSemanticFact
            | BreakthroughCommandGrantSchedulerSpawn
            | BreakthroughCommandObserveCicKernel
            | BreakthroughCommandPrepareBackendLowering
            | BreakthroughCommandObserveBreakthroughCovenant
            | BreakthroughCommandProjectLegacySurface
            | BreakthroughCommandMintTerminalOrder
            | BreakthroughCommandCommitTerminal
            | BreakthroughCommandMarkTerminalDone
            | BreakthroughCommandEmitRunEnd
            | BreakthroughCommandSelectPhysicalExit
            | BreakthroughCommandRequestHostShutdown

        type InvariantViolation =
            | QapNotPositivelyResolved
            | OwnerTailNotSealed
            | OwnerTailStillOpen of openOwners:int
            | WorkDagTailNotAcyclic
            | SemanticFactRequired
            | NativeEvalWithoutSemanticFact of workUnitRef:uint32 * rejectionRef:uint32
            | SchedulerSpawnWithoutReducerGrant
            | CicKernelObligationsOpen of defEqOpen:int64 * universeOpen:int64
            | CicKernelMetavarsForbidden of metavarsInKernel:int64
            | BackendLoweringRequiredForBuildOk
            | BackendLoweringVerificationRequiredForBuildOk
            | BackendLoweringVerificationRejectedForBuildOk of reason:CompilerIdentityKernel.OperationalReasonId
            | CovenantCredentialMissing of CredentialKind
            | TerminalOrderRequired
            | CommitRequired
            | DoneRequired
            | RunEndRequired
            | HostShutdownBeforeRunEnd of shutdownRequestRef:uint32
            | IllegalTransition of phase:BreakthroughPhaseId * command:BreakthroughCommandKindId

        type Decision<'OwnerKind> =
            | Advanced of State<'OwnerKind>
            | Blocked of State<'OwnerKind> * InvariantViolation list

        type TransitionReceipt<'OwnerKind> = private {
            transitionRef : uint32
            priorPhase : BreakthroughPhaseId
            nextPhase : BreakthroughPhaseId
            command : Command
            decision : Decision<'OwnerKind>
            violations : InvariantViolation list
            authorityRef : uint32
            revision : int64
        }

        let private breakthroughPhaseId = function
            | Collecting _ -> BreakthroughPhaseCollecting
            | QapResolved _ -> BreakthroughPhaseQapResolved
            | OwnerTailSealedState _ -> BreakthroughPhaseOwnerTailSealed
            | SemanticReady _ -> BreakthroughPhaseSemanticReady
            | OrderReady _ -> BreakthroughPhaseOrderReady
            | Committed _ -> BreakthroughPhaseCommitted
            | Done _ -> BreakthroughPhaseDone
            | RunEnded _ -> BreakthroughPhaseRunEnded
            | ExitSelected _ -> BreakthroughPhaseExitSelected

        let private breakthroughPhaseText = function
            | BreakthroughPhaseCollecting -> "collecting"
            | BreakthroughPhaseQapResolved -> "qap_resolved"
            | BreakthroughPhaseOwnerTailSealed -> "owner_tail_sealed"
            | BreakthroughPhaseSemanticReady -> "semantic_ready"
            | BreakthroughPhaseOrderReady -> "order_ready"
            | BreakthroughPhaseCommitted -> "committed"
            | BreakthroughPhaseDone -> "done"
            | BreakthroughPhaseRunEnded -> "run_ended"
            | BreakthroughPhaseExitSelected -> "exit_selected"

        let private phaseText state = breakthroughPhaseText (breakthroughPhaseId state)

        let private breakthroughCommandKindId = function
            | ObserveQap _ -> BreakthroughCommandObserveQap
            | SealOwnerTail _ -> BreakthroughCommandSealOwnerTail
            | MintSemanticFact _ -> BreakthroughCommandMintSemanticFact
            | RejectNativeEvalWithoutSemanticFact _ -> BreakthroughCommandRejectNativeEvalWithoutSemanticFact
            | GrantSchedulerSpawn _ -> BreakthroughCommandGrantSchedulerSpawn
            | ObserveCicKernel _ -> BreakthroughCommandObserveCicKernel
            | PrepareBackendLowering _ -> BreakthroughCommandPrepareBackendLowering
            | ObserveBreakthroughCovenant _ -> BreakthroughCommandObserveBreakthroughCovenant
            | ProjectLegacySurface _ -> BreakthroughCommandProjectLegacySurface
            | MintTerminalOrder _ -> BreakthroughCommandMintTerminalOrder
            | CommitTerminal _ -> BreakthroughCommandCommitTerminal
            | MarkTerminalDone _ -> BreakthroughCommandMarkTerminalDone
            | EmitRunEnd _ -> BreakthroughCommandEmitRunEnd
            | SelectPhysicalExit _ -> BreakthroughCommandSelectPhysicalExit
            | RequestHostShutdown _ -> BreakthroughCommandRequestHostShutdown

        let private breakthroughCommandKindText = function
            | BreakthroughCommandObserveQap -> "observe_qap"
            | BreakthroughCommandSealOwnerTail -> "seal_owner_tail"
            | BreakthroughCommandMintSemanticFact -> "mint_semantic_fact"
            | BreakthroughCommandRejectNativeEvalWithoutSemanticFact -> "reject_native_eval_without_semantic_fact"
            | BreakthroughCommandGrantSchedulerSpawn -> "grant_scheduler_spawn"
            | BreakthroughCommandObserveCicKernel -> "observe_cic_kernel"
            | BreakthroughCommandPrepareBackendLowering -> "prepare_backend_lowering"
            | BreakthroughCommandObserveBreakthroughCovenant -> "observe_breakthrough_covenant"
            | BreakthroughCommandProjectLegacySurface -> "project_legacy_surface"
            | BreakthroughCommandMintTerminalOrder -> "mint_terminal_order"
            | BreakthroughCommandCommitTerminal -> "commit_terminal"
            | BreakthroughCommandMarkTerminalDone -> "mark_terminal_done"
            | BreakthroughCommandEmitRunEnd -> "emit_run_end"
            | BreakthroughCommandSelectPhysicalExit -> "select_physical_exit"
            | BreakthroughCommandRequestHostShutdown -> "request_host_shutdown"

        let private commandText command = breakthroughCommandKindText (breakthroughCommandKindId command)

        let private factsOf = function
            | Collecting(_, facts)
            | QapResolved(_, facts)
            | OwnerTailSealedState(_, facts)
            | SemanticReady(_, facts)
            | OrderReady(_, facts)
            | Committed(_, facts)
            | Done(_, facts)
            | RunEnded(_, facts)
            | ExitSelected(_, facts) -> facts

        let private withFacts facts = function
            | Collecting(token, _) -> Collecting(token, facts)
            | QapResolved(token, _) -> QapResolved(token, facts)
            | OwnerTailSealedState(token, _) -> OwnerTailSealedState(token, facts)
            | SemanticReady(token, _) -> SemanticReady(token, facts)
            | OrderReady(token, _) -> OrderReady(token, facts)
            | Committed(token, _) -> Committed(token, facts)
            | Done(token, _) -> Done(token, facts)
            | RunEnded(token, _) -> RunEnded(token, facts)
            | ExitSelected(token, _) -> ExitSelected(token, facts)

        let private phaseTokenRef phase authorityRef revision =
            NativeCutoverStableRef.ref32
                "breakthrough-phase-token"
                [ breakthroughPhaseText phase; string authorityRef; string revision ]

        let private transitionRef prior next command authorityRef revision =
            NativeCutoverStableRef.ref32
                "breakthrough-transition"
                [ breakthroughPhaseText prior; breakthroughPhaseText next; commandText command; string authorityRef; string revision ]

        let initial<'OwnerKind> (ownerKind:'OwnerKind option) authorityRef =
            let facts = {
                ownerKind = ownerKind
                authorityRef = authorityRef
                qap = None
                ownerTail = OwnerTailOpen(authorityRef, 0)
                semanticFact = SemanticFactMissing
                scheduler = SchedulerSpawnNotGranted
                cic = CicKernelNotObserved
                backend = BackendLoweringNotPrepared BackendTargetUnknown
                covenant = BreakthroughCovenantMissing
                terminalIntent = None
                receipts = TerminalOrderMissing
                shutdownRequestRef = None
                revision = 0L
            }
            Collecting(PhaseToken(phaseTokenRef BreakthroughPhaseCollecting authorityRef 0L), facts)

        let private isPositiveQapClosure = function
            | QapFullyDrained _ | QapProvenDeadlock _ -> true
            | QapMaterialProgress _ -> false

        let private hasPositiveQap = function
            | Some closure -> isPositiveQapClosure closure
            | None -> false

        let private isOwnerTailSealed = function
            | OwnerTailSealed(_, _, closedOwners, true) when closedOwners >= 0 -> true
            | _ -> false

        let private hasSemanticFact = function
            | SemanticFactExactOnce _ -> true
            | SemanticFactMissing -> false

        let private cicReady = function
            | CicKernelQuiescent _ -> true
            | _ -> false

        let private backendReady intent backend =
            match intent, backend with
            | TerminalFailClosed, _ -> true
            | TerminalBuildOk, BackendLoweringVerified evidence ->
                evidence.provenance = BackendVerificationRuntimeReceipt
                && evidence.target <> BackendTargetUnknown
            | TerminalBuildOk, BackendLoweringPrepared _
            | TerminalBuildOk, BackendLoweringRejected _
            | TerminalBuildOk, BackendLoweringNotPrepared _ -> false

        let private requiredCredentials = [
            DeterminismCredential
            FairnessCredential
            RecoveryCredential
            GreenPathCredential
            WriterCapabilityCredential
            ArtifactCovenantCredential
        ]

        let private covenantCredentialKinds = function
            | BreakthroughCovenantMissing -> []
            | BreakthroughCovenantObserved(_, credentials) ->
                credentials |> List.map (fun (CredentialMinter(kind, _, _, _)) -> kind) |> List.distinct

        let private missingCovenantCredentials covenant =
            let observed = covenantCredentialKinds covenant
            requiredCredentials |> List.filter (fun required -> not (List.contains required observed))

        let private covenantReady covenant = List.isEmpty (missingCovenantCredentials covenant)

        let private decide (state:State<'OwnerKind>) (command:Command) : Decision<'OwnerKind> =
            let facts : Facts<'OwnerKind> = factsOf state
            let nextRevision = facts.revision + 1L
            let updated (facts:Facts<'OwnerKind>) : Facts<'OwnerKind> = { facts with revision = nextRevision }
            match state, command with
            | Collecting _, ObserveQap closure when isPositiveQapClosure closure ->
                let facts = updated { facts with qap = Some closure }
                Advanced(QapResolved(PhaseToken(phaseTokenRef BreakthroughPhaseQapResolved facts.authorityRef nextRevision), facts))
            | Collecting _, ObserveQap closure ->
                Advanced(withFacts (updated { facts with qap = Some closure }) state)
            | QapResolved _, SealOwnerTail (OwnerTailSealed(_, _, _, true) as closure) ->
                let facts = updated { facts with ownerTail = closure }
                Advanced(OwnerTailSealedState(PhaseToken(phaseTokenRef BreakthroughPhaseOwnerTailSealed facts.authorityRef nextRevision), facts))
            | QapResolved _, SealOwnerTail (OwnerTailOpen(_, openOwners) as closure) ->
                Blocked(withFacts (updated { facts with ownerTail = closure }) state, [OwnerTailStillOpen openOwners])
            | QapResolved _, SealOwnerTail (OwnerTailSealed(_, _, _, false) as closure) ->
                Blocked(withFacts (updated { facts with ownerTail = closure }) state, [WorkDagTailNotAcyclic])
            | OwnerTailSealedState _, MintSemanticFact(digest, epoch, producerRef, exactOnceRef) ->
                let facts = updated { facts with semanticFact = SemanticFactExactOnce(digest, epoch, producerRef, exactOnceRef) }
                Advanced(SemanticReady(PhaseToken(phaseTokenRef BreakthroughPhaseSemanticReady facts.authorityRef nextRevision), facts))
            | _, RejectNativeEvalWithoutSemanticFact(workUnitRef, rejectionRef) ->
                Blocked(withFacts (updated facts) state, [NativeEvalWithoutSemanticFact(workUnitRef, rejectionRef)])
            | _, GrantSchedulerSpawn(grantRef, maxDrivers, debtBefore, debtAfter) when maxDrivers > 0 && debtAfter <= debtBefore ->
                let facts = updated { facts with scheduler = SchedulerSpawnGranted(grantRef, maxDrivers, debtBefore, debtAfter) }
                Advanced(withFacts facts state)
            | _, GrantSchedulerSpawn _ ->
                Blocked(withFacts (updated facts) state, [SchedulerSpawnWithoutReducerGrant])
            | _, ObserveCicKernel (CicKernelRejectedMetavars(_, metavars) as cic) ->
                Blocked(withFacts (updated { facts with cic = cic }) state, [CicKernelMetavarsForbidden metavars])
            | _, ObserveCicKernel (CicKernelActive(_, _, defEqOpen, universeOpen) as cic) ->
                Blocked(withFacts (updated { facts with cic = cic }) state, [CicKernelObligationsOpen(defEqOpen, universeOpen)])
            | _, ObserveCicKernel cic ->
                Advanced(withFacts (updated { facts with cic = cic }) state)
            | _, PrepareBackendLowering backend ->
                Advanced(withFacts (updated { facts with backend = backend }) state)
            | _, ObserveBreakthroughCovenant covenant ->
                let missing = missingCovenantCredentials covenant
                if List.isEmpty missing then
                    Advanced(withFacts (updated { facts with covenant = covenant }) state)
                else
                    Blocked(withFacts (updated { facts with covenant = covenant }) state, missing |> List.map CovenantCredentialMissing)
            | _, ProjectLegacySurface _ ->
                Advanced(withFacts (updated facts) state)
            | SemanticReady _, MintTerminalOrder(intent, orderRef, predecessorRef, exactOnceRef)
                when hasPositiveQap facts.qap && isOwnerTailSealed facts.ownerTail && hasSemanticFact facts.semanticFact && cicReady facts.cic && backendReady intent facts.backend && (intent = TerminalFailClosed || covenantReady facts.covenant) ->
                let facts = updated { facts with terminalIntent = Some intent; receipts = TerminalOrderMinted(orderRef, predecessorRef, exactOnceRef) }
                Advanced(OrderReady(PhaseToken(phaseTokenRef BreakthroughPhaseOrderReady facts.authorityRef nextRevision), facts))
            | SemanticReady _, MintTerminalOrder _ when not (hasSemanticFact facts.semanticFact) ->
                Blocked(withFacts (updated facts) state, [SemanticFactRequired])
            | SemanticReady _, MintTerminalOrder _ when not (isOwnerTailSealed facts.ownerTail) ->
                Blocked(withFacts (updated facts) state, [OwnerTailNotSealed])
            | SemanticReady _, MintTerminalOrder _ when not (hasPositiveQap facts.qap) ->
                Blocked(withFacts (updated facts) state, [QapNotPositivelyResolved])
            | SemanticReady _, MintTerminalOrder _ when not (cicReady facts.cic) ->
                match facts.cic with
                | CicKernelRejectedMetavars(_, metavars) -> Blocked(withFacts (updated facts) state, [CicKernelMetavarsForbidden metavars])
                | CicKernelActive(_, _, defEqOpen, universeOpen) -> Blocked(withFacts (updated facts) state, [CicKernelObligationsOpen(defEqOpen, universeOpen)])
                | _ -> Blocked(withFacts (updated facts) state, [CicKernelObligationsOpen(0L, 0L)])
            | SemanticReady _, MintTerminalOrder(TerminalBuildOk, _, _, _) when not (backendReady TerminalBuildOk facts.backend) ->
                let violation =
                    match facts.backend with
                    | BackendLoweringPrepared _ -> BackendLoweringVerificationRequiredForBuildOk
                    | BackendLoweringVerified evidence when evidence.provenance = BackendVerificationFixtureProjection -> BackendLoweringVerificationRequiredForBuildOk
                    | BackendLoweringRejected(_, _, _, reason) -> BackendLoweringVerificationRejectedForBuildOk reason
                    | BackendLoweringNotPrepared _ -> BackendLoweringRequiredForBuildOk
                    | BackendLoweringVerified _ -> BackendLoweringRequiredForBuildOk
                Blocked(withFacts (updated facts) state, [violation])
            | SemanticReady _, MintTerminalOrder(TerminalBuildOk, _, _, _) when not (covenantReady facts.covenant) ->
                let missing = missingCovenantCredentials facts.covenant
                Blocked(withFacts (updated facts) state, missing |> List.map CovenantCredentialMissing)
            | SemanticReady _, MintTerminalOrder _ ->
                Blocked(withFacts (updated facts) state, [TerminalOrderRequired])
            | OrderReady _, CommitTerminal commitRef ->
                match facts.receipts with
                | TerminalOrderMinted(orderRef, _, _) ->
                    let facts = updated { facts with receipts = TerminalCommitted(orderRef, commitRef) }
                    Advanced(Committed(PhaseToken(phaseTokenRef BreakthroughPhaseCommitted facts.authorityRef nextRevision), facts))
                | _ -> Blocked(withFacts (updated facts) state, [TerminalOrderRequired])
            | Committed _, MarkTerminalDone doneRef ->
                match facts.receipts with
                | TerminalCommitted(_, commitRef) ->
                    let facts = updated { facts with receipts = TerminalDone(commitRef, doneRef) }
                    Advanced(Done(PhaseToken(phaseTokenRef BreakthroughPhaseDone facts.authorityRef nextRevision), facts))
                | _ -> Blocked(withFacts (updated facts) state, [CommitRequired])
            | Done _, EmitRunEnd runEndRef ->
                match facts.receipts with
                | TerminalDone(_, doneRef) ->
                    let facts = updated { facts with receipts = TerminalRunEnded(doneRef, runEndRef) }
                    Advanced(RunEnded(PhaseToken(phaseTokenRef BreakthroughPhaseRunEnded facts.authorityRef nextRevision), facts))
                | _ -> Blocked(withFacts (updated facts) state, [DoneRequired])
            | RunEnded _, SelectPhysicalExit exitRef ->
                match facts.receipts with
                | TerminalRunEnded(_, runEndRef) ->
                    let facts = updated { facts with receipts = TerminalPhysicalExitSelected(runEndRef, exitRef) }
                    Advanced(ExitSelected(PhaseToken(phaseTokenRef BreakthroughPhaseExitSelected facts.authorityRef nextRevision), facts))
                | _ -> Blocked(withFacts (updated facts) state, [RunEndRequired])
            | RunEnded _, RequestHostShutdown shutdownRef
            | ExitSelected _, RequestHostShutdown shutdownRef ->
                Advanced(withFacts (updated { facts with shutdownRequestRef = Some shutdownRef }) state)
            | _, RequestHostShutdown shutdownRef ->
                Blocked(withFacts (updated { facts with shutdownRequestRef = Some shutdownRef }) state, [HostShutdownBeforeRunEnd shutdownRef])
            | _ ->
                Blocked(withFacts (updated facts) state, [IllegalTransition(breakthroughPhaseId state, breakthroughCommandKindId command)])

        let reduce state command =
            let prior = breakthroughPhaseId state
            let decision = decide state command
            let nextState, violations =
                match decision with
                | Advanced next -> next, []
                | Blocked(next, violations) -> next, violations
            let next = breakthroughPhaseId nextState
            let facts = factsOf nextState
            {
                transitionRef = transitionRef prior next command facts.authorityRef facts.revision
                priorPhase = prior
                nextPhase = next
                command = command
                decision = decision
                violations = violations
                authorityRef = facts.authorityRef
                revision = facts.revision
            }

        let stateAfter receipt =
            match receipt.decision with
            | Advanced state | Blocked(state, _) -> state

        let transitionRefOf receipt = receipt.transitionRef

        let private credentialKindText = function
            | DeterminismCredential -> "determinism"
            | FairnessCredential -> "fairness"
            | RecoveryCredential -> "recovery"
            | GreenPathCredential -> "green_path"
            | WriterCapabilityCredential -> "writer_capability"
            | ArtifactCovenantCredential -> "artifact_covenant"

        let private invariantViolationText = function
            | QapNotPositivelyResolved -> "qap_not_positively_resolved"
            | OwnerTailNotSealed -> "owner_tail_not_sealed"
            | OwnerTailStillOpen openOwners -> "owner_tail_still_open:" + string openOwners
            | WorkDagTailNotAcyclic -> "workdag_tail_not_acyclic"
            | SemanticFactRequired -> "semantic_fact_required"
            | NativeEvalWithoutSemanticFact(workUnitRef, rejectionRef) -> sprintf "native_eval_without_semantic_fact:%u:%u" workUnitRef rejectionRef
            | SchedulerSpawnWithoutReducerGrant -> "scheduler_spawn_without_reducer_grant"
            | CicKernelObligationsOpen(defEqOpen, universeOpen) -> sprintf "cic_kernel_obligations_open:%d:%d" defEqOpen universeOpen
            | CicKernelMetavarsForbidden metavarsInKernel -> "cic_kernel_metavars_forbidden:" + string metavarsInKernel
            | BackendLoweringRequiredForBuildOk -> "backend_lowering_required_for_build_ok"
            | BackendLoweringVerificationRequiredForBuildOk -> "backend_lowering_verification_required_for_build_ok"
            | BackendLoweringVerificationRejectedForBuildOk reason -> "backend_lowering_verification_rejected_for_build_ok:" + CompilerIdentityKernel.OperationalReasonIdOps.text reason
            | CovenantCredentialMissing kind -> "covenant_credential_missing:" + credentialKindText kind
            | TerminalOrderRequired -> "terminal_order_required"
            | CommitRequired -> "commit_required"
            | DoneRequired -> "done_required"
            | RunEndRequired -> "run_end_required"
            | HostShutdownBeforeRunEnd shutdownRequestRef -> "host_shutdown_before_run_end:" + string shutdownRequestRef
            | IllegalTransition(phase, command) -> "illegal_transition:" + breakthroughPhaseText phase + ":" + breakthroughCommandKindText command

        let transitionReceiptText receipt =
            let violationsText = receipt.violations |> List.map invariantViolationText |> String.concat ","
            FastRuntimeFormat.format "breakthrough_transition|ref=%u|prior=%s|next=%s|command=%s|violations=%s|authority_ref=%u|revision=%d" [| box receipt.transitionRef; box (breakthroughPhaseText receipt.priorPhase); box (breakthroughPhaseText receipt.nextPhase); box (commandText receipt.command); box violationsText; box receipt.authorityRef; box receipt.revision |]

        type HarnessOwnerKind = class end

        type HarnessVector = private {
            name : string
            commands : Command list
            expectedPhase : BreakthroughPhaseId
            expectedViolation : InvariantViolation option
        }

        let harnessVectors = [
            {
                name = "deadlock_failclosed_total_order"
                commands = [
                    ObserveQap(QapProvenDeadlock(11u, 12u, [13u]))
                    SealOwnerTail(OwnerTailSealed(21u, 22u, 1, true))
                    MintSemanticFact(31u, 1L, 32u, 33u)
                    ObserveCicKernel(CicKernelQuiescent(34u, 10L, 7L, 4L, 2L))
                    MintTerminalOrder(TerminalFailClosed, 41u, 42u, 43u)
                    CommitTerminal 51u
                    MarkTerminalDone 61u
                    EmitRunEnd 71u
                    SelectPhysicalExit 81u
                ]
                expectedPhase = BreakthroughPhaseExitSelected
                expectedViolation = None
            }
            {
                name = "drained_buildok_total_order"
                commands = [
                    ObserveQap(QapFullyDrained(111u, 112u, [113u;114u]))
                    SealOwnerTail(OwnerTailSealed(121u, 122u, 2, true))
                    MintSemanticFact(131u, 2L, 132u, 133u)
                    ObserveCicKernel(CicKernelQuiescent(134u, 20L, 12L, 8L, 3L))
                    PrepareBackendLowering(
                        BackendLoweringVerified(
                            backendVerificationEvidence
                                BackendTargetHvm
                                (CompilerIdentityKernel.ContentDigest.ofText "fixture-hvm-artifact" "135")
                                (CompilerIdentityKernel.ContentDigest.ofText "fixture-hvm-semantic-closure" "1139")
                                (CompilerIdentityKernel.ContentDigest.ofText "fixture-hvm-conformance" "137")
                                BackendVerificationFixtureProjection))
                    ObserveBreakthroughCovenant(BreakthroughCovenantObserved(139u, [
                        CredentialMinter(DeterminismCredential, 140u, 240u, 340u)
                        CredentialMinter(FairnessCredential, 141u, 241u, 341u)
                        CredentialMinter(RecoveryCredential, 142u, 242u, 342u)
                        CredentialMinter(GreenPathCredential, 143u, 243u, 343u)
                        CredentialMinter(WriterCapabilityCredential, 144u, 244u, 344u)
                        CredentialMinter(ArtifactCovenantCredential, 145u, 245u, 345u)
                    ]))
                    MintTerminalOrder(TerminalBuildOk, 146u, 147u, 148u)
                    CommitTerminal 151u
                    MarkTerminalDone 161u
                    EmitRunEnd 171u
                    SelectPhysicalExit 181u
                ]
                expectedPhase = BreakthroughPhaseExitSelected
                expectedViolation = None
            }
            {
                name = "prepared_hvm_without_graph_receipt_blocks_buildok"
                commands = [
                    ObserveQap(QapFullyDrained(211u, 212u, [213u]))
                    SealOwnerTail(OwnerTailSealed(221u, 222u, 1, true))
                    MintSemanticFact(231u, 3L, 232u, 233u)
                    ObserveCicKernel(CicKernelQuiescent(234u, 1L, 1L, 1L, 1L))
                    PrepareBackendLowering(
                        BackendLoweringPrepared(
                            BackendTargetHvm,
                            CompilerIdentityKernel.ContentDigest.ofText "fixture-hvm-artifact" "235"))
                    ObserveBreakthroughCovenant(BreakthroughCovenantObserved(239u, [
                        CredentialMinter(DeterminismCredential, 240u, 340u, 440u)
                        CredentialMinter(FairnessCredential, 241u, 341u, 441u)
                        CredentialMinter(RecoveryCredential, 242u, 342u, 442u)
                        CredentialMinter(GreenPathCredential, 243u, 343u, 443u)
                        CredentialMinter(WriterCapabilityCredential, 244u, 344u, 444u)
                        CredentialMinter(ArtifactCovenantCredential, 245u, 345u, 445u)
                    ]))
                    MintTerminalOrder(TerminalBuildOk, 246u, 247u, 248u)
                ]
                expectedPhase = BreakthroughPhaseSemanticReady
                expectedViolation = Some BackendLoweringVerificationRequiredForBuildOk
            }
            {
                name = "shutdown_cannot_bypass_total_order"
                commands = [ RequestHostShutdown 201u ]
                expectedPhase = BreakthroughPhaseCollecting
                expectedViolation = Some(HostShutdownBeforeRunEnd 201u)
            }
            {
                name = "native_eval_no_fact_is_not_progress"
                commands = [ RejectNativeEvalWithoutSemanticFact(301u, 302u) ]
                expectedPhase = BreakthroughPhaseCollecting
                expectedViolation = Some(NativeEvalWithoutSemanticFact(301u, 302u))
            }
            {
                name = "commit_before_order_is_illegal"
                commands = [ CommitTerminal 401u ]
                expectedPhase = BreakthroughPhaseCollecting
                expectedViolation = Some(IllegalTransition(BreakthroughPhaseCollecting, BreakthroughCommandCommitTerminal))
            }
            {
                name = "legacy_terminal_copies_are_projection_only"
                commands = [ ProjectLegacySurface(LegacyProjectionBoundaryReceipt(DiagJsonTerminalFlowMirror, 501u, 502u)) ]
                expectedPhase = BreakthroughPhaseCollecting
                expectedViolation = None
            }
        ]

        let runHarnessVector vector =
            let finalState, receipts =
                vector.commands
                |> List.fold (fun (state, receipts) command ->
                    let receipt = reduce state command
                    stateAfter receipt, receipt :: receipts) ((initial<HarnessOwnerKind> None 1u), [])
            let receipts = List.rev receipts
            let actualPhaseId = breakthroughPhaseId finalState
            let actualPhase = breakthroughPhaseText actualPhaseId
            let actualViolations = receipts |> List.collect (fun receipt -> receipt.violations)
            let expectedViolationObserved =
                match vector.expectedViolation with
                | None -> List.isEmpty actualViolations
                | Some expected -> actualViolations |> List.exists ((=) expected)
            vector.name, actualPhaseId = vector.expectedPhase && expectedViolationObserved, actualPhase, actualViolations

        let runHarness () = harnessVectors |> List.map runHarnessVector

    module CompilerKernelV2 =

        // One transliterable kernel substrate is shared by compiler work,
        // terminal authority and observability. Identities, merges, progress
        // and journal order are represented before JSON/string erasure.
        [<Struct>]
        type NonZeroRef<'Kind> = private | NonZeroRef of uint32

        module NonZeroRef =
            [<StructuralEquality; NoComparison>]
            type private NonZeroRefIdentity = {
                label : string
                parts : string list
            }

            let private deriveGate = obj()
            let private deriveByPayload = Dictionary<NonZeroRefIdentity,uint32>()
            let private deriveByValue = Dictionary<uint32,string>()

            let tryCreate (value:uint32) : NonZeroRef<'Kind> option =
                if value = 0u then None else Some (NonZeroRef value)

            let require label (value:uint32) : NonZeroRef<'Kind> =
                match tryCreate value with
                | Some reference -> reference
                | None -> invalidOp (label + " cannot be zero")

            let value (NonZeroRef value) = value

            let private digestCandidate (identity:string) salt =
                let salted = if salt = 0 then identity else identity + "#" + string salt
                uint32 (CompilerIdentityKernel.ContentDigest.hash64 salted >>> 32)

            let derive label (parts:seq<string>) : NonZeroRef<'Kind> =
                let partList = parts |> Seq.toList
                let identity : NonZeroRefIdentity =
                    { label = label
                      parts = partList }
                let identityText = label + "|" + (partList |> String.concat "|")
                lock deriveGate (fun () ->
                    match deriveByPayload.TryGetValue identity with
                    | true, existing -> require label existing
                    | false, _ ->
                        let mutable salt = 0
                        let mutable candidate = digestCandidate identityText salt
                        let mutable accepted = false
                        while not accepted do
                            if candidate = 0u then
                                salt <- salt + 1
                                candidate <- digestCandidate identityText salt
                            else
                                match deriveByValue.TryGetValue candidate with
                                | false, _ -> accepted <- true
                                | true, prior when prior = identityText -> accepted <- true
                                | true, _ ->
                                    salt <- salt + 1
                                    candidate <- digestCandidate identityText salt
                        deriveByPayload.[identity] <- candidate
                        deriveByValue.[candidate] <- identityText
                        require label candidate)


