        [<Struct>]
        type PortableResourceId = private | PortableResourceId of ContentDigest

        module PortableResourceId =
            let digest (PortableResourceId digest) = digest
            let text resourceId = resourceId |> digest |> ContentDigest.text

        type PortableFSharpHopacBackend = class end
        type PortableRustBackend = class end
        type PortableBeamBackend = class end

        type private PortableOneShotPayload<'T> =
            | PortableFSharpHopacOneShotPayload of Hopac.IVar<'T>

        type PortableOneShotCellFor<'Backend,'T> = private {
            resourceId : PortableResourceId
            payload : PortableOneShotPayload<'T>
        }

        type PortableOneShotCell<'T> = PortableOneShotCellFor<PortableFSharpHopacBackend,'T>

        module PortableOneShotRuntime =
            let private gate = obj()
            let mutable private nextOrdinal = 0L

            let private next () =
                lock gate (fun () ->
                    nextOrdinal <- nextOrdinal + 1L
                    nextOrdinal)

            let count () = lock gate (fun () -> nextOrdinal)

            let oneShot<'T> label : PortableOneShotCell<'T> =
                let ordinal = next ()
                { resourceId = PortableResourceId(ContentDigest.ofText "portable-resource" (label + "|one_shot=" + string ordinal))
                  payload = PortableFSharpHopacOneShotPayload(Hopac.IVar<'T>()) }

            let wrapOneShot<'T> label (cell:Hopac.IVar<'T>) : PortableOneShotCell<'T> =
                let ordinal = next ()
                { resourceId = PortableResourceId(ContentDigest.ofText "portable-resource" (label + "|wrapped_one_shot=" + string ordinal))
                  payload = PortableFSharpHopacOneShotPayload cell }

            let private oneShotCell<'T> (cell:PortableOneShotCell<'T>) : Hopac.IVar<'T> =
                match cell.payload with
                | PortableFSharpHopacOneShotPayload raw -> raw

            let fillOneShot<'T> (cell:PortableOneShotCell<'T>) (value:'T) : Hopac.Job<unit> =
                Hopac.IVar.fill (oneShotCell<'T> cell) value

            let tryFillOneShot<'T> (cell:PortableOneShotCell<'T>) (value:'T) : Hopac.Job<unit> =
                Hopac.IVar.tryFill (oneShotCell<'T> cell) value

            let readOneShot<'T> (cell:PortableOneShotCell<'T>) : Hopac.Job<'T> =
                Hopac.IVar.read (oneShotCell<'T> cell)

            let projectOneShotToFSharp<'T> (cell:PortableOneShotCell<'T>) : Hopac.IVar<'T> =
                oneShotCell<'T> cell

            let tryReadOneShotNow<'T> (cell:PortableOneShotCell<'T>) : 'T option =
                let raw = oneShotCell<'T> cell
                if Hopac.IVar.Now.isFull raw then Some (Hopac.IVar.Now.get raw)
                else None

        [<Struct>]
        type StableDeclarationIdentity = private {
            moduleDigest : ContentDigest
            declarationDigest : ContentDigest
        }

        [<Struct>]
        type SourceProvenanceId = private | SourceProvenanceId of ContentDigest

        [<Struct>]
        type SpecializationIdentity = private | SpecializationIdentity of ContentDigest

        [<Struct>]
        type BackendArtifactIdentity = private | BackendArtifactIdentity of ContentDigest

        module StableDeclarationIdentity =
            let create moduleText declarationText =
                { moduleDigest = ContentDigest.ofText "binding-module" moduleText
                  declarationDigest = ContentDigest.ofText "binding-declaration" declarationText }
            let moduleDigest identity = identity.moduleDigest
            let declarationDigest identity = identity.declarationDigest

        module SourceProvenanceId =
            let create sourceSpan = SourceProvenanceId(ContentDigest.ofText "binding-source-span" sourceSpan)
            let digest (SourceProvenanceId digest) = digest

        module SpecializationIdentity =
            let create specialization = SpecializationIdentity(ContentDigest.ofText "binding-specialization" specialization)
            let digest (SpecializationIdentity digest) = digest

        module BackendArtifactIdentity =
            let create backend = BackendArtifactIdentity(ContentDigest.ofText "binding-backend" backend)
            let digest (BackendArtifactIdentity digest) = digest

        type SemanticBindingIdentity = private {
            declaration : StableDeclarationIdentity
            sourceProvenance : SourceProvenanceId
            specialization : SpecializationIdentity
            backendArtifact : BackendArtifactIdentity
        }

        type StableBindingId = private {
            identity : SemanticBindingIdentity
            digest : ContentDigest
            declarationOrdinal : int
        }

        module StableBindingId =
            let private semanticIdentity moduleText declarationText sourceSpan specialization backend =
                { declaration = StableDeclarationIdentity.create moduleText declarationText
                  sourceProvenance = SourceProvenanceId.create sourceSpan
                  specialization = SpecializationIdentity.create specialization
                  backendArtifact = BackendArtifactIdentity.create backend }

            let createSemantic declarationOrdinal moduleText declarationText sourceSpan specialization backend =
                if declarationOrdinal < 0 then invalidArg "declarationOrdinal" "must be non-negative"
                let identity = semanticIdentity moduleText declarationText sourceSpan specialization backend
                let canonical =
                    [ identity.declaration |> StableDeclarationIdentity.moduleDigest |> ContentDigest.text
                      identity.declaration |> StableDeclarationIdentity.declarationDigest |> ContentDigest.text
                      identity.sourceProvenance |> SourceProvenanceId.digest |> ContentDigest.text
                      identity.specialization |> SpecializationIdentity.digest |> ContentDigest.text
                      identity.backendArtifact |> BackendArtifactIdentity.digest |> ContentDigest.text
                      string declarationOrdinal ]
                    |> String.concat "|"
                { identity = identity
                  digest = ContentDigest.ofText "semantic-binding" canonical
                  declarationOrdinal = declarationOrdinal }

            // Legacy ingress is deliberately explicit.  It cannot silently masquerade
            // as a fully resolved declaration identity in new authority paths.
            let create declarationOrdinal source =
                createSemantic declarationOrdinal "legacy-module" source "legacy-span" "unspecialized" "host"

            let digestText binding = ContentDigest.text binding.digest

            let text binding =
                sprintf "%s@%d" (digestText binding) binding.declarationOrdinal

            let sameSemanticIdentity left right = left.identity = right.identity

