        [<StructuralEquality; NoComparison>]
        type WorkBindingIdentity =
            | WorkDeclarationBinding of StableBindingId
            | WorkKernelAuthorityBinding of ContentDigest

        module WorkBindingIdentity =
            let digest = function
                | WorkDeclarationBinding binding -> binding |> StableBindingId.digestText |> ContentDigest.ofText "work-declaration-binding"
                | WorkKernelAuthorityBinding authorityRef -> authorityRef

            let stableText = function
                | WorkDeclarationBinding binding -> "declaration:" + StableBindingId.digestText binding
                | WorkKernelAuthorityBinding authorityRef -> "kernel:" + ContentDigest.text authorityRef

        [<Struct; NoComparison>]
        type WorkUnitId<'Phase,'Kind> = private {
            binding : WorkBindingIdentity
            generation : int64
            instantiationRef : ContentDigest
            backendRef : ContentDigest
            digest : ContentDigest
        }

        module WorkUnitIdOps =
            let private createCore<'Phase,'Kind> binding generation instantiationRef backendRef : WorkUnitId<'Phase,'Kind> =
                let digest =
                    ContentDigest.ofText
                        "semantic-work-unit"
                        (String.concat "|"
                            [ WorkBindingIdentity.stableText binding
                              string generation
                              ContentDigest.text instantiationRef
                              ContentDigest.text backendRef ])
                { binding = binding
                  generation = generation
                  instantiationRef = instantiationRef
                  backendRef = backendRef
                  digest = digest }

            let create<'Phase,'Kind> binding generation instantiation backend : WorkUnitId<'Phase,'Kind> =
                createCore<'Phase,'Kind>
                    (WorkDeclarationBinding binding)
                    generation
                    (InstantiationIdOps.digest instantiation)
                    (BackendIdOps.digest backend)

            let createKernel<'Phase,'Kind> authorityRef generation : WorkUnitId<'Phase,'Kind> =
                createCore<'Phase,'Kind>
                    (WorkKernelAuthorityBinding authorityRef)
                    generation
                    (ContentDigest.ofText "kernel-instantiation" (ContentDigest.text authorityRef))
                    (ContentDigest.ofText "kernel-backend" "compiler-kernel")

            let digest (workUnit:WorkUnitId<'Phase,'Kind>) = workUnit.digest
            let digestText (workUnit:WorkUnitId<'Phase,'Kind>) = workUnit |> digest |> ContentDigest.text
            let binding (workUnit:WorkUnitId<'Phase,'Kind>) = workUnit.binding
            let generation (workUnit:WorkUnitId<'Phase,'Kind>) = workUnit.generation
            let instantiationRef (workUnit:WorkUnitId<'Phase,'Kind>) = workUnit.instantiationRef
            let backendRef (workUnit:WorkUnitId<'Phase,'Kind>) = workUnit.backendRef

        // Five-round migration round : the operational scheduler is indexed
        // by compiler phase, work kind, owner capability and lifecycle state.
        // These indices are authority; strings and mutable lifecycle fields are
        // retained only by explicitly named legacy adapters until the compatibility cut is deleted.
        type WorkQueuedState = class end
        type WorkRunningState = class end
        type WorkSuspendedState = class end
        type WorkRetiredState = class end

        type WorkOwnerUnboundState = class end
        type WorkOwnerBoundState = class end

        [<Struct; NoComparison>]
        type WorkIdentity<'CompilerPhase,'Kind> = private {
            workUnit : WorkUnitId<'CompilerPhase,'Kind>
            identityRef : ContentDigest
        }

        [<StructuralEquality; NoComparison>]
        type WorkOwnerIdentity =
            | WorkOwnerBinding of StableBindingId
            | WorkOwnerAuthority of ContentDigest

        [<Struct; NoComparison>]
        type WorkOwnerCapability<'Owner> = private {
            owner : WorkOwnerIdentity
            authorityRef : ContentDigest
        }

        type WorkTerminalDisposition =
            | WorkTerminalSucceeded of receiptRef:ContentDigest
            | WorkTerminalFailed of failureRef:ContentDigest
            | WorkTerminalCancelled of cancellationRef:ContentDigest
            | WorkTerminalSuperseded of transitionRef:ContentDigest

        module WorkTerminalDispositionOps =
            let text = function
                | WorkTerminalSucceeded _ -> "Succeeded"
                | WorkTerminalFailed _ -> "Failed"
                | WorkTerminalCancelled _ -> "Cancelled"
                | WorkTerminalSuperseded _ -> "Superseded"

        type WorkSuspensionReason =
            | WorkSuspendedOnPromise of promiseRef:ContentDigest
            | WorkSuspendedOnDependency of dependencyRef:ContentDigest
            | WorkSuspendedOnGeneration of generation:int64 * generationRef:ContentDigest
            | WorkSuspendedOnSchedulerCapacity of capacityRef:ContentDigest

        type WorkResumeFailure =
            | WorkResumeGenerationSuperseded of transitionRef:ContentDigest
            | WorkResumeProducerFailed of failureRef:ContentDigest
            | WorkResumeCancelled of cancellationRef:ContentDigest
            | WorkResumeProtocolViolation of violationRef:ContentDigest

        [<Struct>]
        type WorkContinuationId<'T> = private WorkContinuationId of ContentDigest

        type WorkContinuation<'T> = private {
            continuationId : WorkContinuationId<'T>
            generation : int64
            completion : PortableOneShotCell<Result<'T,WorkResumeFailure>>
            exactOnceRef : ContentDigest
        }

        // Destructive unit migration: quantities that used to share int64
        // are now incompatible by construction.  AST discovery can no longer
        // clamp semantic retirement, and CPU time cannot be added to wall time.
        type AstCostUnit = class end
        type SemanticCostUnit = class end
        type CpuTimeUnit = class end
        type WallTimeUnit = class end
        type QueueDelayUnit = class end
        type BlockedOnChildTimeUnit = class end
        type NodeCountUnit = class end
        type WorkerCountUnit = class end
        type BasisPointUnit = class end
        type CriticalPathCostUnit = class end
        type RevisionOrdinalUnit = class end
        type MonotonicTimeUnit = class end
        type ParallelismPermilleUnit = class end

        [<Struct>]
        type Measured<'Unit> = private Measured of int64

        module Measured =
            let zero<'Unit> : Measured<'Unit> = Measured 0L

            let create<'Unit> argumentName value : Measured<'Unit> =
                if value < 0L then invalidArg argumentName "measured values must be non-negative"
                Measured value

            let value (Measured value) = value
            let one<'Unit> : Measured<'Unit> = Measured 1L
            let increment (Measured value) =
                if value = Int64.MaxValue then invalidOp "measured value overflow"
                Measured(value + 1L)
            let ofInt<'Unit> argumentName value : Measured<'Unit> = create<'Unit> argumentName (int64 value)

            let add (Measured left) (Measured right) =
                if Int64.MaxValue - left < right then invalidOp "measured value overflow"
                Measured(left + right)

            let subtractFloor (Measured left) (Measured right) =
                Measured(max 0L (left - right))

            let maxValue (Measured left) (Measured right) = Measured(max left right)
            let minValue (Measured left) (Measured right) = Measured(min left right)

        type AstCost = Measured<AstCostUnit>
        type SemanticCost = Measured<SemanticCostUnit>
        type CpuTime = Measured<CpuTimeUnit>
        type WallTime = Measured<WallTimeUnit>
        type QueueDelay = Measured<QueueDelayUnit>
        type BlockedOnChildTime = Measured<BlockedOnChildTimeUnit>
        type NodeCount = Measured<NodeCountUnit>
        type WorkerCount = Measured<WorkerCountUnit>
        type BasisPoints = Measured<BasisPointUnit>
        type CriticalPathCost = Measured<CriticalPathCostUnit>
        type RevisionOrdinal = Measured<RevisionOrdinalUnit>
        type MonotonicTimestamp = Measured<MonotonicTimeUnit>
        type ParallelismPermille = Measured<ParallelismPermilleUnit>

        module BasisPoints =
            let zero : BasisPoints = Measured.zero
            let create value =
                if value < 0L || value > 10000L then invalidArg "value" "basis points must be 0..10000"
                Measured.create<BasisPointUnit> "basisPoints" value
            let value (basisPoints:BasisPoints) = Measured.value basisPoints

        type WorkItem<'CompilerPhase,'Kind,'Owner,'State> = private {
            identity : WorkIdentity<'CompilerPhase,'Kind>
            owner : WorkOwnerCapability<'Owner>
            generation : int64
            dependencyRefs : ContentDigest list
            siteId : WorkSiteId
            semanticCost : SemanticCost
            commitOrdinal : int64
            stateRef : ContentDigest
        }

        type WorkSuspension<'CompilerPhase,'Kind,'Owner,'T> = private {
            suspendedWork : WorkItem<'CompilerPhase,'Kind,'Owner,WorkSuspendedState>
            reason : WorkSuspensionReason
            continuation : WorkContinuation<'T>
            suspensionRef : ContentDigest
        }

        module WorkIdentityOps =
            let create (workUnit:WorkUnitId<'CompilerPhase,'Kind>) : WorkIdentity<'CompilerPhase,'Kind> =
                { workUnit = workUnit
                  identityRef = ContentDigest.ofText "operational-work-identity" (WorkUnitIdOps.digestText workUnit) }
            let workUnit (identity:WorkIdentity<'CompilerPhase,'Kind>) = identity.workUnit
            let identityRef (identity:WorkIdentity<'CompilerPhase,'Kind>) = identity.identityRef

        module WorkOwnerCapabilityOps =
            let bind (owner:StableBindingId) : WorkOwnerCapability<'Owner> =
                { owner = WorkOwnerBinding owner
                  authorityRef = ContentDigest.ofText "operational-work-owner" (StableBindingId.digestText owner) }

            let bindAuthority authorityRef : WorkOwnerCapability<'Owner> =
                { owner = WorkOwnerAuthority authorityRef
                  authorityRef = authorityRef }

            let owner (capability:WorkOwnerCapability<'Owner>) = capability.owner
            let authorityRef (capability:WorkOwnerCapability<'Owner>) = capability.authorityRef

        module WorkContinuation =
            // Continuation identity is attempt-scoped, not merely work-scoped. A logical work
            // item may legally suspend on the same dependency more than once after resuming;
            // anchoring the continuation to the current Running state keeps those transitions
            // distinct without introducing a mutable attempt counter.
            let create<'T> generation identityRef runningStateRef causeRef : WorkContinuation<'T> =
                let continuationRef =
                    ContentDigest.ofText
                        "operational-work-continuation"
                        (ContentDigest.text identityRef
                         + "|generation=" + string generation
                         + "|running_state=" + ContentDigest.text runningStateRef
                         + "|cause=" + ContentDigest.text causeRef)
                { continuationId = WorkContinuationId continuationRef
                  generation = generation
                  completion =
                    PortableOneShotRuntime.oneShot<Result<'T,WorkResumeFailure>>
                        ("operational-work-continuation|" + ContentDigest.text continuationRef)
                  exactOnceRef = ContentDigest.ofText "operational-work-continuation-exact-once" (ContentDigest.text continuationRef) }

            let idRef<'T> (continuation:WorkContinuation<'T>) =
                let (WorkContinuationId continuationRef) = continuation.continuationId
                continuationRef

            let awaitResult<'T> (continuation:WorkContinuation<'T>) : Hopac.Job<Result<'T,WorkResumeFailure>> =
                PortableOneShotRuntime.readOneShot<Result<'T,WorkResumeFailure>> continuation.completion

            let resume<'T>
                (continuation:WorkContinuation<'T>)
                (result:Result<'T,WorkResumeFailure>)
                : Hopac.Job<unit> =
                PortableOneShotRuntime.tryFillOneShot<Result<'T,WorkResumeFailure>> continuation.completion result

        module WorkItemOps =
            let private stateRef label identityRef generation =
                ContentDigest.ofText
                    ("operational-work-state-" + label)
                    (ContentDigest.text identityRef + "|generation=" + string generation)

            let createQueued workUnit owner generation dependencyRefs siteId semanticCost commitOrdinal =
                let identity = WorkIdentityOps.create workUnit
                { identity = identity
                  owner = owner
                  generation = generation
                  dependencyRefs = dependencyRefs
                  siteId = siteId
                  semanticCost = semanticCost
                  commitOrdinal = commitOrdinal
                  stateRef = stateRef "queued" (WorkIdentityOps.identityRef identity) generation }

            let start (item:WorkItem<'CompilerPhase,'Kind,'Owner,WorkQueuedState>) =
                { identity = item.identity
                  owner = item.owner
                  generation = item.generation
                  dependencyRefs = item.dependencyRefs
                  siteId = item.siteId
                  semanticCost = item.semanticCost
                  commitOrdinal = item.commitOrdinal
                  stateRef = stateRef "running" (WorkIdentityOps.identityRef item.identity) item.generation }

            let suspend
                (reason:WorkSuspensionReason)
                (continuation:WorkContinuation<'T>)
                (item:WorkItem<'CompilerPhase,'Kind,'Owner,WorkRunningState>) =
                let continuationRef = WorkContinuation.idRef continuation
                let suspensionRef =
                    ContentDigest.ofText
                        "operational-work-suspension"
                        (ContentDigest.text (WorkIdentityOps.identityRef item.identity)
                         + "|generation=" + string item.generation
                         + "|continuation=" + ContentDigest.text continuationRef)
                let suspendedStateRef =
                    ContentDigest.ofText
                        "operational-work-state-suspended"
                        (ContentDigest.text (WorkIdentityOps.identityRef item.identity)
                         + "|generation=" + string item.generation
                         + "|suspension=" + ContentDigest.text suspensionRef)
                let suspended =
                    { identity = item.identity
                      owner = item.owner
                      generation = item.generation
                      dependencyRefs = item.dependencyRefs
                      siteId = item.siteId
                      semanticCost = item.semanticCost
                      commitOrdinal = item.commitOrdinal
                      stateRef = suspendedStateRef }
                { suspendedWork = suspended
                  reason = reason
                  continuation = continuation
                  suspensionRef = suspensionRef }

            let resume (suspension:WorkSuspension<'CompilerPhase,'Kind,'Owner,'T>) =
                let item = suspension.suspendedWork
                // A resumed attempt is a child of one exact suspension. Using that parent in
                // the Running state identity prevents two distinct resume attempts from being
                // collapsed into the same operational state and transition receipt.
                let resumedStateRef =
                    ContentDigest.ofText
                        "operational-work-state-running-resume"
                        (ContentDigest.text (WorkIdentityOps.identityRef item.identity)
                         + "|generation=" + string item.generation
                         + "|suspension=" + ContentDigest.text suspension.suspensionRef)
                { identity = item.identity
                  owner = item.owner
                  generation = item.generation
                  dependencyRefs = item.dependencyRefs
                  siteId = item.siteId
                  semanticCost = item.semanticCost
                  commitOrdinal = item.commitOrdinal
                  stateRef = resumedStateRef }

            let retire disposition (item:WorkItem<'CompilerPhase,'Kind,'Owner,WorkRunningState>) =
                { identity = item.identity
                  owner = item.owner
                  generation = item.generation
                  dependencyRefs = item.dependencyRefs
                  siteId = item.siteId
                  semanticCost = item.semanticCost
                  commitOrdinal = item.commitOrdinal
                  stateRef = stateRef "retired" (WorkIdentityOps.identityRef item.identity) item.generation }, disposition

            let retireQueued disposition (item:WorkItem<'CompilerPhase,'Kind,'Owner,WorkQueuedState>) =
                { identity = item.identity
                  owner = item.owner
                  generation = item.generation
                  dependencyRefs = item.dependencyRefs
                  siteId = item.siteId
                  semanticCost = item.semanticCost
                  commitOrdinal = item.commitOrdinal
                  stateRef = stateRef "retired" (WorkIdentityOps.identityRef item.identity) item.generation }, disposition

            let identity (item:WorkItem<'CompilerPhase,'Kind,'Owner,'State>) = item.identity
            let identityRef (item:WorkItem<'CompilerPhase,'Kind,'Owner,'State>) = WorkIdentityOps.identityRef item.identity
            let workUnit (item:WorkItem<'CompilerPhase,'Kind,'Owner,'State>) = WorkIdentityOps.workUnit item.identity
            let owner (item:WorkItem<'CompilerPhase,'Kind,'Owner,'State>) = item.owner
            let generation (item:WorkItem<'CompilerPhase,'Kind,'Owner,'State>) = item.generation
            let dependencyRefs (item:WorkItem<'CompilerPhase,'Kind,'Owner,'State>) = item.dependencyRefs
            let siteId (item:WorkItem<'CompilerPhase,'Kind,'Owner,'State>) = item.siteId
            let siteRef (item:WorkItem<'CompilerPhase,'Kind,'Owner,'State>) = WorkSiteIdOps.digest item.siteId
            let semanticCost (item:WorkItem<'CompilerPhase,'Kind,'Owner,'State>) = item.semanticCost
            let getCommitOrdinal (item:WorkItem<'CompilerPhase,'Kind,'Owner,'State>) = item.commitOrdinal
            let getStateRef (item:WorkItem<'CompilerPhase,'Kind,'Owner,'State>) = item.stateRef
            let suspensionRef (suspension:WorkSuspension<'CompilerPhase,'Kind,'Owner,'T>) = suspension.suspensionRef
            let suspendedWork (suspension:WorkSuspension<'CompilerPhase,'Kind,'Owner,'T>) = suspension.suspendedWork
            let suspensionReason (suspension:WorkSuspension<'CompilerPhase,'Kind,'Owner,'T>) = suspension.reason
            let continuation (suspension:WorkSuspension<'CompilerPhase,'Kind,'Owner,'T>) = suspension.continuation

        [<Struct>]
        type WorkTransition<'From,'To> = private {
            identityRef : ContentDigest
            fromStateRef : ContentDigest
            toStateRef : ContentDigest
            transitionRef : ContentDigest
        }

        type WorkTransitionTargetId =
            | WorkTransitionTargetRunning
            | WorkTransitionTargetSuspended of reason:WorkSuspensionReason * suspensionRef:ContentDigest
            | WorkTransitionTargetRetired of WorkTerminalDisposition

        type SomeWorkTransition =
            | WorkQueuedToRunningTransition of WorkTransition<WorkQueuedState,WorkRunningState>
            | WorkRunningToSuspendedTransition of WorkTransition<WorkRunningState,WorkSuspendedState> * WorkSuspensionReason * ContentDigest
            | WorkSuspendedToRunningTransition of WorkTransition<WorkSuspendedState,WorkRunningState>
            | WorkRunningToRetiredTransition of WorkTransition<WorkRunningState,WorkRetiredState> * WorkTerminalDisposition
            | WorkQueuedToRetiredTransition of WorkTransition<WorkQueuedState,WorkRetiredState> * WorkTerminalDisposition

        module WorkTransitionOps =
            let private create label identityRef fromStateRef toStateRef =
                { identityRef = identityRef
                  fromStateRef = fromStateRef
                  toStateRef = toStateRef
                  transitionRef =
                    ContentDigest.ofText
                        ("operational-work-transition-" + label)
                        (ContentDigest.text identityRef
                         + "|from=" + ContentDigest.text fromStateRef
                         + "|to=" + ContentDigest.text toStateRef) }

            let start
                (queued:WorkItem<'CompilerPhase,'Kind,'Owner,WorkQueuedState>)
                (running:WorkItem<'CompilerPhase,'Kind,'Owner,WorkRunningState>) =
                WorkQueuedToRunningTransition(
                    create
                        "queued-to-running"
                        (WorkItemOps.identityRef queued)
                        (WorkItemOps.getStateRef queued)
                        (WorkItemOps.getStateRef running))

            let suspend
                (running:WorkItem<'CompilerPhase,'Kind,'Owner,WorkRunningState>)
                (suspension:WorkSuspension<'CompilerPhase,'Kind,'Owner,'T>) =
                let suspended = WorkItemOps.suspendedWork suspension
                WorkRunningToSuspendedTransition(
                    create
                        "running-to-suspended"
                        (WorkItemOps.identityRef running)
                        (WorkItemOps.getStateRef running)
                        (WorkItemOps.getStateRef suspended),
                    WorkItemOps.suspensionReason suspension,
                    WorkItemOps.suspensionRef suspension)

            let resume
                (suspension:WorkSuspension<'CompilerPhase,'Kind,'Owner,'T>)
                (running:WorkItem<'CompilerPhase,'Kind,'Owner,WorkRunningState>) =
                let suspended = WorkItemOps.suspendedWork suspension
                WorkSuspendedToRunningTransition(
                    create
                        "suspended-to-running"
                        (WorkItemOps.identityRef suspended)
                        (WorkItemOps.getStateRef suspended)
                        (WorkItemOps.getStateRef running))

            let retire
                (running:WorkItem<'CompilerPhase,'Kind,'Owner,WorkRunningState>)
                (retired:WorkItem<'CompilerPhase,'Kind,'Owner,WorkRetiredState>)
                disposition =
                WorkRunningToRetiredTransition(
                    create
                        "running-to-retired"
                        (WorkItemOps.identityRef running)
                        (WorkItemOps.getStateRef running)
                        (WorkItemOps.getStateRef retired),
                    disposition)

            let retireQueued
                (queued:WorkItem<'CompilerPhase,'Kind,'Owner,WorkQueuedState>)
                (retired:WorkItem<'CompilerPhase,'Kind,'Owner,WorkRetiredState>)
                disposition =
                WorkQueuedToRetiredTransition(
                    create
                        "queued-to-retired"
                        (WorkItemOps.identityRef queued)
                        (WorkItemOps.getStateRef queued)
                        (WorkItemOps.getStateRef retired),
                    disposition)

            let identityRef = function
                | WorkQueuedToRunningTransition transition -> transition.identityRef
                | WorkRunningToSuspendedTransition(transition,_,_) -> transition.identityRef
                | WorkSuspendedToRunningTransition transition -> transition.identityRef
                | WorkRunningToRetiredTransition(transition,_) -> transition.identityRef
                | WorkQueuedToRetiredTransition(transition,_) -> transition.identityRef

            let fromStateRef = function
                | WorkQueuedToRunningTransition transition -> transition.fromStateRef
                | WorkRunningToSuspendedTransition(transition,_,_) -> transition.fromStateRef
                | WorkSuspendedToRunningTransition transition -> transition.fromStateRef
                | WorkRunningToRetiredTransition(transition,_) -> transition.fromStateRef
                | WorkQueuedToRetiredTransition(transition,_) -> transition.fromStateRef

            let toStateRef = function
                | WorkQueuedToRunningTransition transition -> transition.toStateRef
                | WorkRunningToSuspendedTransition(transition,_,_) -> transition.toStateRef
                | WorkSuspendedToRunningTransition transition -> transition.toStateRef
                | WorkRunningToRetiredTransition(transition,_) -> transition.toStateRef
                | WorkQueuedToRetiredTransition(transition,_) -> transition.toStateRef

            let transitionRef = function
                | WorkQueuedToRunningTransition transition -> transition.transitionRef
                | WorkRunningToSuspendedTransition(transition,_,_) -> transition.transitionRef
                | WorkSuspendedToRunningTransition transition -> transition.transitionRef
                | WorkRunningToRetiredTransition(transition,_) -> transition.transitionRef
                | WorkQueuedToRetiredTransition(transition,_) -> transition.transitionRef

            let target = function
                | WorkQueuedToRunningTransition _
                | WorkSuspendedToRunningTransition _ -> WorkTransitionTargetRunning
                | WorkRunningToSuspendedTransition(_,reason,suspensionRef) ->
                    WorkTransitionTargetSuspended(reason,suspensionRef)
                | WorkRunningToRetiredTransition(_,disposition)
                | WorkQueuedToRetiredTransition(_,disposition) ->
                    WorkTransitionTargetRetired disposition

        type OperationalWorkGraphNodeState =
            | OperationalWorkQueued
            | OperationalWorkRunning
            | OperationalWorkSuspended of reason:WorkSuspensionReason * suspensionRef:ContentDigest
            | OperationalWorkRetired of WorkTerminalDisposition

        let operationalWorkGraphNodeStateText = function
            | OperationalWorkQueued -> "Queued"
            | OperationalWorkRunning -> "Running"
            | OperationalWorkSuspended(reason,suspensionRef) ->
                "Suspended(reason=" + string reason + "|ref=" + ContentDigest.text suspensionRef + ")"
            | OperationalWorkRetired disposition ->
                "Retired(" + string disposition + ")"

        type OperationalWorkTransitionAuthority =
            | OperationalWorkTransitionAlreadyApplied
            | OperationalWorkTransitionReady
            | OperationalWorkTransitionStale of currentState:OperationalWorkGraphNodeState * currentStateRef:ContentDigest
            | OperationalWorkTransitionMissingNode

        type OperationalWorkGraphNode = private {
            identityRef : ContentDigest
            workUnitRef : ContentDigest
            siteId : WorkSiteId
            ownerRef : ContentDigest
            generation : int64
            dependencyRefs : ContentDigest list
            state : OperationalWorkGraphNodeState
            stateRef : ContentDigest
        }

        type OperationalOpenWorkProjection = private {
            identityRef : ContentDigest
            workUnitRef : ContentDigest
            siteId : WorkSiteId
            state : OperationalWorkGraphNodeState
        }

        module OperationalOpenWorkProjectionOps =
            let identityRef (projection:OperationalOpenWorkProjection) = projection.identityRef
            let workUnitRef (projection:OperationalOpenWorkProjection) = projection.workUnitRef
            let siteId (projection:OperationalOpenWorkProjection) = projection.siteId
            let state (projection:OperationalOpenWorkProjection) = projection.state

        type OperationalWorkGraphApplyDisposition =
            | OperationalWorkGraphApplied
            | OperationalWorkGraphDuplicateAdmissionSuppressed
            | OperationalWorkGraphDuplicateTransitionSuppressed
            | OperationalWorkGraphCompensatingCloseApplied

        type OperationalWorkGraph = private {
            nodes : Map<ContentDigest,OperationalWorkGraphNode>
            appliedTransitionRefs : Set<ContentDigest>
            revision : int64
            graphRef : ContentDigest
        }

        type OperationalWorkGraphCommand =
            | OperationalWorkAdmit of OperationalWorkGraphNode
            | OperationalWorkTransition of SomeWorkTransition
            | OperationalWorkCompensatingClose of reasonRef:ContentDigest

        type OperationalWorkGraphEvent = private {
            command : OperationalWorkGraphCommand
            disposition : OperationalWorkGraphApplyDisposition
            transitionRef : ContentDigest option
            revision : int64
            openCount : int
            suspendedCount : int
            graphRef : ContentDigest
        }

        [<Struct>]
        type OperationalAuthoritySnapshot = private {
            graphRevision : int64
            graphRef : ContentDigest
            openCount : int
            suspendedCount : int
            semanticAdmittedCount : int
            semanticReceiptCount : int
            semanticEpoch : int64
            runtimeAuthorityRef : ContentDigest
            snapshotRef : ContentDigest
        }

        module OperationalWorkGraph =
            let private digest nodes appliedTransitionRefs revision =
                let nodePayload =
                    nodes
                    |> Map.toList
                    |> List.map (fun (key,node) -> ContentDigest.text key + ":" + ContentDigest.text node.stateRef)
                    |> String.concat "|"
                let transitionPayload =
                    appliedTransitionRefs
                    |> Set.toList
                    |> List.map ContentDigest.text
                    |> String.concat "|"
                ContentDigest.ofText
                    "operational-work-graph"
                    (string revision + "|nodes=" + nodePayload + "|transitions=" + transitionPayload)

            let empty =
                { nodes = Map.empty
                  appliedTransitionRefs = Set.empty
                  revision = 0L
                  graphRef = ContentDigest.ofText "operational-work-graph" "empty" }

            let nodeOfQueued (item:WorkItem<'CompilerPhase,'Kind,'Owner,WorkQueuedState>) =
                { identityRef = WorkItemOps.identityRef item
                  workUnitRef = item |> WorkItemOps.workUnit |> WorkUnitIdOps.digest
                  siteId = WorkItemOps.siteId item
                  ownerRef = WorkOwnerCapabilityOps.authorityRef (WorkItemOps.owner item)
                  generation = WorkItemOps.generation item
                  dependencyRefs = WorkItemOps.dependencyRefs item
                  state = OperationalWorkQueued
                  stateRef = WorkItemOps.getStateRef item }

            let nodeIdentityRef (node:OperationalWorkGraphNode) = node.identityRef
            let nodeState (node:OperationalWorkGraphNode) = node.state

            let tryState identityRef graph =
                Map.tryFind identityRef graph.nodes
                |> Option.map (fun node -> node.state)

            let openIdentityRefs limit graph =
                graph.nodes
                |> Map.toSeq
                |> Seq.choose (fun (identityRef,node) ->
                    match node.state with
                    | OperationalWorkRetired _ -> None
                    | _ -> Some identityRef)
                |> Seq.truncate (max 0 limit)
                |> Seq.toList

            let openWorkProjections limit graph =
                graph.nodes
                |> Map.toSeq
                |> Seq.choose (fun (identityRef,node) ->
                    match node.state with
                    | OperationalWorkRetired _ -> None
                    | state ->
                        Some {
                            identityRef = identityRef
                            workUnitRef = node.workUnitRef
                            siteId = node.siteId
                            state = state
                        })
                |> Seq.truncate (max 0 limit)
                |> Seq.toList

            let transitionAuthority transition graph =
                let transitionRef = WorkTransitionOps.transitionRef transition
                let identityRef = WorkTransitionOps.identityRef transition
                let expectedStateRef = WorkTransitionOps.fromStateRef transition
                let targetStateRef = WorkTransitionOps.toStateRef transition
                match Map.tryFind identityRef graph.nodes with
                | None -> OperationalWorkTransitionMissingNode
                | Some node when Set.contains transitionRef graph.appliedTransitionRefs ->
                    // Exact-once replay is authoritative only while the graph still denotes
                    // the target state produced by that transition. If the graph has since
                    // advanced, replaying an old transition is stale, not successful.
                    if node.stateRef = targetStateRef then OperationalWorkTransitionAlreadyApplied
                    else OperationalWorkTransitionStale(node.state,node.stateRef)
                | Some node when node.stateRef = expectedStateRef -> OperationalWorkTransitionReady
                | Some node -> OperationalWorkTransitionStale(node.state,node.stateRef)

            let private event disposition transitionRef command graph =
                let openCount =
                    graph.nodes
                    |> Map.toSeq
                    |> Seq.filter (fun (_,node) -> match node.state with | OperationalWorkRetired _ -> false | _ -> true)
                    |> Seq.length
                let suspendedCount =
                    graph.nodes
                    |> Map.toSeq
                    |> Seq.filter (fun (_,node) -> match node.state with | OperationalWorkSuspended _ -> true | _ -> false)
                    |> Seq.length
                { command = command
                  disposition = disposition
                  transitionRef = transitionRef
                  revision = graph.revision
                  openCount = openCount
                  suspendedCount = suspendedCount
                  graphRef = graph.graphRef }

            let apply command graph =
                match command with
                | OperationalWorkAdmit node ->
                    let nodeKey = node.identityRef
                    match Map.tryFind nodeKey graph.nodes with
                    | Some _ ->
                        graph,
                        event OperationalWorkGraphDuplicateAdmissionSuppressed None command graph
                    | None ->
                        let nextNodes = Map.add nodeKey node graph.nodes
                        let revision = graph.revision + 1L
                        let next =
                            { nodes = nextNodes
                              appliedTransitionRefs = graph.appliedTransitionRefs
                              revision = revision
                              graphRef = digest nextNodes graph.appliedTransitionRefs revision }
                        next, event OperationalWorkGraphApplied None command next

                | OperationalWorkTransition transition ->
                    let transitionRef = WorkTransitionOps.transitionRef transition
                    let transitionKey = transitionRef
                    if Set.contains transitionKey graph.appliedTransitionRefs then
                        graph,
                        event
                            OperationalWorkGraphDuplicateTransitionSuppressed
                            (Some transitionRef)
                            command
                            graph
                    else
                        let identityRef = WorkTransitionOps.identityRef transition
                        let stateRef = WorkTransitionOps.toStateRef transition
                        let nextState =
                            match WorkTransitionOps.target transition with
                            | WorkTransitionTargetRunning -> OperationalWorkRunning
                            | WorkTransitionTargetSuspended(reason,suspensionRef) ->
                                OperationalWorkSuspended(reason,suspensionRef)
                            | WorkTransitionTargetRetired disposition ->
                                OperationalWorkRetired disposition
                        let nodeKey = identityRef
                        let nextNodes =
                            match Map.tryFind nodeKey graph.nodes with
                            | None ->
                                invalidOp "operational work transition references a missing node"
                            | Some node ->
                                if node.stateRef <> WorkTransitionOps.fromStateRef transition then
                                    invalidOp "operational work transition source-state mismatch"
                                Map.add nodeKey { node with state = nextState; stateRef = stateRef } graph.nodes
                        let nextTransitionRefs = Set.add transitionKey graph.appliedTransitionRefs
                        let revision = graph.revision + 1L
                        let next =
                            { nodes = nextNodes
                              appliedTransitionRefs = nextTransitionRefs
                              revision = revision
                              graphRef = digest nextNodes nextTransitionRefs revision }
                        next,
                        event
                            OperationalWorkGraphApplied
                            (Some transitionRef)
                            command
                            next

                | OperationalWorkCompensatingClose reasonRef ->
                    let nextNodes =
                        graph.nodes
                        |> Map.map (fun _ node ->
                            match node.state with
                            | OperationalWorkRetired _ -> node
                            | _ ->
                                { node with
                                    state = OperationalWorkRetired(WorkTerminalCancelled reasonRef)
                                    stateRef = ContentDigest.ofText "operational-work-compensating-close" (ContentDigest.text node.identityRef + "|reason=" + ContentDigest.text reasonRef) })
                    let revision = graph.revision + 1L
                    let next =
                        { nodes = nextNodes
                          appliedTransitionRefs = graph.appliedTransitionRefs
                          revision = revision
                          graphRef = digest nextNodes graph.appliedTransitionRefs revision }
                    next,
                    event OperationalWorkGraphCompensatingCloseApplied (Some reasonRef) command next

            let openCount graph =
                graph.nodes
                |> Map.toSeq
                |> Seq.filter (fun (_,node) -> match node.state with | OperationalWorkRetired _ -> false | _ -> true)
                |> Seq.length

            let suspendedCount graph =
                graph.nodes
                |> Map.toSeq
                |> Seq.filter (fun (_,node) -> match node.state with | OperationalWorkSuspended _ -> true | _ -> false)
                |> Seq.length

            let getRevision (graph:OperationalWorkGraph) = graph.revision
            let getGraphRef (graph:OperationalWorkGraph) = graph.graphRef
            let eventDisposition (event:OperationalWorkGraphEvent) = event.disposition
            let eventGraphRef (event:OperationalWorkGraphEvent) = event.graphRef
            let eventOpenCount (event:OperationalWorkGraphEvent) = event.openCount
            let eventSuspendedCount (event:OperationalWorkGraphEvent) = event.suspendedCount

        module OperationalAuthoritySnapshotOps =
            let create graph semanticAdmittedCount semanticReceiptCount semanticEpoch runtimeAuthorityRef =
                let graphRevision = OperationalWorkGraph.getRevision graph
                let graphRef = OperationalWorkGraph.getGraphRef graph
                let openCount = OperationalWorkGraph.openCount graph
                let suspendedCount = OperationalWorkGraph.suspendedCount graph
                let snapshotRef =
                    ContentDigest.ofText
                        "operational-authority-snapshot"
                        (ContentDigest.text graphRef
                         + "|graph_revision=" + string graphRevision
                         + "|open=" + string openCount
                         + "|suspended=" + string suspendedCount
                         + "|semantic_admitted=" + string semanticAdmittedCount
                         + "|semantic_receipts=" + string semanticReceiptCount
                         + "|semantic_epoch=" + string semanticEpoch
                         + "|runtime_authority=" + ContentDigest.text runtimeAuthorityRef)
                { graphRevision = graphRevision
                  graphRef = graphRef
                  openCount = openCount
                  suspendedCount = suspendedCount
                  semanticAdmittedCount = semanticAdmittedCount
                  semanticReceiptCount = semanticReceiptCount
                  semanticEpoch = semanticEpoch
                  runtimeAuthorityRef = runtimeAuthorityRef
                  snapshotRef = snapshotRef }

            let graphRevision (snapshot:OperationalAuthoritySnapshot) = snapshot.graphRevision
            let graphRef (snapshot:OperationalAuthoritySnapshot) = snapshot.graphRef
            let openCount (snapshot:OperationalAuthoritySnapshot) = snapshot.openCount
            let suspendedCount (snapshot:OperationalAuthoritySnapshot) = snapshot.suspendedCount
            let semanticAdmittedCount (snapshot:OperationalAuthoritySnapshot) = snapshot.semanticAdmittedCount
            let semanticReceiptCount (snapshot:OperationalAuthoritySnapshot) = snapshot.semanticReceiptCount
            let semanticEpoch (snapshot:OperationalAuthoritySnapshot) = snapshot.semanticEpoch
            let runtimeAuthorityRef (snapshot:OperationalAuthoritySnapshot) = snapshot.runtimeAuthorityRef
            let snapshotRef (snapshot:OperationalAuthoritySnapshot) = snapshot.snapshotRef

        // Every join-point specialization
        // carries a content-addressed dependency chain. Runtime execution is no
        // longer allowed to enqueue an anonymous closure without this plan.
        type SpecializationDependencyRole =
            | SpecializationOwner
            | SpecializationGeneration
            | SpecializationInput
            | SpecializationMetaWake
            | SpecializationDefEqProof
            | SpecializationInteractionProof
            | SpecializationLoweringBoundary

        let specializationDependencyRoleStableText = function
            | SpecializationOwner -> "owner"
            | SpecializationGeneration -> "generation"
            | SpecializationInput -> "input"
            | SpecializationMetaWake -> "meta_wake"
            | SpecializationDefEqProof -> "defeq_proof"
            | SpecializationInteractionProof -> "interaction_proof"
            | SpecializationLoweringBoundary -> "lowering_boundary"

        type SpecializationDependencyEdge = private {
            role : SpecializationDependencyRole
            authorityRef : ContentDigest
            edgeRef : ContentDigest
        }

        type JoinPointSpecializationPlan = private {
            workUnitRef : ContentDigest
            ownerRef : ContentDigest
            generationRef : ContentDigest
            dependencyEdges : SpecializationDependencyEdge list
            planRef : ContentDigest
        }

        type SpecializationPureNodeKind =
            | SpecializationAuthorityNode of SpecializationDependencyRole
            | SpecializationLoweringNode

        type SpecializationPureNode = private {
            nodeRef : ContentDigest
            kind : SpecializationPureNodeKind
            authorityRef : ContentDigest
        }

        type SpecializationPureActivePair = private {
            pairRef : ContentDigest
            authorityNodeRef : ContentDigest
            loweringNodeRef : ContentDigest
            dependencyRef : ContentDigest
        }

        [<Struct>]
        type SpecializationPureNodeId = private | SpecializationPureNodeId of ContentDigest

        module SpecializationPureNodeId =
            let ofDigest digest = SpecializationPureNodeId digest
            let digest (SpecializationPureNodeId digest) = digest
            let text id = id |> digest |> ContentDigest.text

        [<Struct>]
        type SpecializationPureActivePairId = private | SpecializationPureActivePairId of ContentDigest

        module SpecializationPureActivePairId =
            let ofDigest digest = SpecializationPureActivePairId digest
            let digest (SpecializationPureActivePairId digest) = digest
            let text id = id |> digest |> ContentDigest.text

        type SpecializationPureGraph = private {
            nodes : Map<SpecializationPureNodeId, SpecializationPureNode>
            activePairs : Map<SpecializationPureActivePairId, SpecializationPureActivePair>
            consumedPairRefs : Set<SpecializationPureActivePairId>
            graphRef : ContentDigest
            proofRef : ContentDigest
            closed : bool
        }

        type SpecializationInteractionReceipt = private {
            sourcePlanRef : ContentDigest
            graphRef : ContentDigest
            consumedDependencyRefs : ContentDigest list
            consumedActivePairRefs : ContentDigest list
            activePairsBefore : int
            activePairsAfter : int
            proofRef : ContentDigest
            closed : bool
        }

        module SpecializationInteractionReceipt =
            let sourcePlanRef receipt = receipt.sourcePlanRef
            let graphRef receipt = receipt.graphRef
            let consumedDependencyRefs receipt = receipt.consumedDependencyRefs
            let consumedActivePairRefs receipt = receipt.consumedActivePairRefs
            let activePairsBefore receipt = receipt.activePairsBefore
            let activePairsAfter receipt = receipt.activePairsAfter
            let proofRef receipt = receipt.proofRef
            let closed receipt = receipt.closed

        // Cross-module views avoid the F# type/module-name ambiguity created by
        // private record fields that share names with accessor functions.
        module SpecializationInteractionReceiptView =
            let sourcePlanRef (receipt:SpecializationInteractionReceipt) = receipt.sourcePlanRef
            let graphRef (receipt:SpecializationInteractionReceipt) = receipt.graphRef
            let activePairsBefore (receipt:SpecializationInteractionReceipt) = receipt.activePairsBefore
            let activePairsAfter (receipt:SpecializationInteractionReceipt) = receipt.activePairsAfter
            let proofRef (receipt:SpecializationInteractionReceipt) = receipt.proofRef
            let closed (receipt:SpecializationInteractionReceipt) = receipt.closed

        module JoinPointSpecializationPlanView =
            let planRef (plan:JoinPointSpecializationPlan) = plan.planRef
            let dependencyCount (plan:JoinPointSpecializationPlan) = plan.dependencyEdges.Length
            let isClosed (plan:JoinPointSpecializationPlan) =
                let roles = plan.dependencyEdges |> List.map (fun edge -> edge.role) |> Set.ofList
                [ SpecializationOwner
                  SpecializationGeneration
                  SpecializationInput
                  SpecializationInteractionProof
                  SpecializationLoweringBoundary ]
                |> List.forall (fun role -> Set.contains role roles)

        module JoinPointSpecializationPlan =
            let private edge role authorityRef =
                { role = role
                  authorityRef = authorityRef
                  edgeRef =
                    ContentDigest.ofText
                        "join-point-specialization-edge"
                        (specializationDependencyRoleStableText role + "|" + ContentDigest.text authorityRef) }

            let private planDigest workUnitRef ownerRef generationRef edges =
                ContentDigest.ofText
                    "join-point-specialization-plan"
                    (String.concat "|"
                        [ ContentDigest.text workUnitRef
                          ContentDigest.text ownerRef
                          ContentDigest.text generationRef
                          edges |> List.map (fun item -> ContentDigest.text item.edgeRef) |> String.concat "," ])

            let create workUnit owner generation site =
                let workUnitRef = ContentDigest.ofText "join-point-work-unit" (WorkUnitIdOps.digestText workUnit)
                let ownerRef = ContentDigest.ofText "join-point-owner" (StableBindingId.digestText owner)
                let generationRef = ContentDigest.ofText "join-point-generation" (string generation)
                let inputRef = ContentDigest.ofText "join-point-input-site" site
                let edges =
                    [ edge SpecializationOwner ownerRef
                      edge SpecializationGeneration generationRef
                      edge SpecializationInput inputRef ]
                { workUnitRef = workUnitRef
                  ownerRef = ownerRef
                  generationRef = generationRef
                  dependencyEdges = edges
                  planRef = planDigest workUnitRef ownerRef generationRef edges }

            let attach role authorityRef plan =
                let proposed = edge role authorityRef
                if plan.dependencyEdges |> List.exists (fun existing -> existing.edgeRef = proposed.edgeRef) then plan
                else
                    let edges = plan.dependencyEdges @ [proposed]
                    { plan with
                        dependencyEdges = edges
                        planRef = planDigest plan.workUnitRef plan.ownerRef plan.generationRef edges }

            let private pureNodeKindStableText = function
                | SpecializationAuthorityNode role -> "authority:" + specializationDependencyRoleStableText role
                | SpecializationLoweringNode -> "lowering"

            let private pureNode role authorityRef =
                let kind = SpecializationAuthorityNode role
                let nodeRef =
                    ContentDigest.ofText
                        "join-point-specialization-pure-node"
                        (pureNodeKindStableText kind + "|" + ContentDigest.text authorityRef)
                { nodeRef = nodeRef; kind = kind; authorityRef = authorityRef }

            let private loweringNode loweringBoundaryRef =
                let kind = SpecializationLoweringNode
                let nodeRef =
                    ContentDigest.ofText
                        "join-point-specialization-pure-node"
                        (pureNodeKindStableText kind + "|" + ContentDigest.text loweringBoundaryRef)
                { nodeRef = nodeRef; kind = kind; authorityRef = loweringBoundaryRef }

            let private activePair loweringRef dependency node =
                let pairRef =
                    ContentDigest.ofText
                        "join-point-specialization-active-pair"
                        (ContentDigest.text dependency.edgeRef
                         + "|authority=" + ContentDigest.text node.nodeRef
                         + "|lowering=" + ContentDigest.text loweringRef)
                { pairRef = pairRef
                  authorityNodeRef = node.nodeRef
                  loweringNodeRef = loweringRef
                  dependencyRef = dependency.edgeRef }

            let private graphDigest nodes activePairs consumedPairRefs closed =
                let nodeText =
                    nodes
                    |> Map.toList
                    |> List.map (fun (_, node) ->
                        ContentDigest.text node.nodeRef
                        + ":" + pureNodeKindStableText node.kind
                        + ":" + ContentDigest.text node.authorityRef)
                    |> String.concat "|"
                let pairText =
                    activePairs
                    |> Map.toList
                    |> List.map (fun (_, pair) -> ContentDigest.text pair.pairRef)
                    |> String.concat "|"
                let consumedText =
                    consumedPairRefs
                    |> Set.toList
                    |> List.map SpecializationPureActivePairId.text
                    |> String.concat "|"
                ContentDigest.ofText
                    "join-point-specialization-pure-graph"
                    ("nodes=" + nodeText
                     + "|active=" + pairText
                     + "|consumed=" + consumedText
                     + "|closed=" + string closed)

            let lowerPureGraph loweringBoundaryRef plan =
                let loweringPlan = attach SpecializationLoweringBoundary loweringBoundaryRef plan
                let lowering = loweringNode loweringBoundaryRef
                let authorityNodes =
                    loweringPlan.dependencyEdges
                    |> List.filter (fun dependency -> dependency.role <> SpecializationInteractionProof)
                    |> List.map (fun dependency -> dependency, pureNode dependency.role dependency.authorityRef)
                let nodes =
                    (SpecializationPureNodeId.ofDigest lowering.nodeRef, lowering) ::
                    (authorityNodes
                     |> List.map (fun (_, node) -> SpecializationPureNodeId.ofDigest node.nodeRef, node))
                    |> Map.ofList
                let activePairs =
                    authorityNodes
                    |> List.map (fun (dependency, node) ->
                        let pair = activePair lowering.nodeRef dependency node
                        SpecializationPureActivePairId.ofDigest pair.pairRef, pair)
                    |> Map.ofList
                let activePairsBefore = activePairs.Count
                let consumedActivePairRefs = activePairs |> Map.toList |> List.map (fun (_, pair) -> pair.pairRef)
                let consumedPairRefs =
                    consumedActivePairRefs
                    |> List.map SpecializationPureActivePairId.ofDigest
                    |> Set.ofList
                let consumedDependencyRefs =
                    activePairs
                    |> Map.toList
                    |> List.map (fun (_, pair) -> pair.dependencyRef)
                    |> List.distinct
                let activePairsAfter = 0
                let roles = loweringPlan.dependencyEdges |> List.map (fun edge -> edge.role) |> Set.ofList
                let requiredRolesClosed =
                    [ SpecializationOwner
                      SpecializationGeneration
                      SpecializationInput
                      SpecializationLoweringBoundary ]
                    |> List.forall (fun role -> Set.contains role roles)
                let closed =
                    requiredRolesClosed
                    && activePairsBefore = consumedPairRefs.Count
                    && activePairsAfter = 0
                    && consumedDependencyRefs.Length = authorityNodes.Length
                let closedGraphRef = graphDigest nodes Map.empty consumedPairRefs closed
                let proofRef =
                    ContentDigest.ofText
                        "join-point-specialization-interaction-proof"
                        (ContentDigest.text loweringPlan.planRef
                         + "|graph=" + ContentDigest.text closedGraphRef
                         + "|pairs=" + (consumedPairRefs |> Set.toList |> List.map SpecializationPureActivePairId.text |> String.concat ",")
                         + "|active_before=" + string activePairsBefore
                         + "|active_after=" + string activePairsAfter
                         + "|closed=" + string closed)
                let graph =
                    { nodes = nodes
                      activePairs = Map.empty
                      consumedPairRefs = consumedPairRefs
                      graphRef = closedGraphRef
                      proofRef = proofRef
                      closed = closed }
                let provenPlan = attach SpecializationInteractionProof proofRef loweringPlan
                provenPlan,
                { sourcePlanRef = loweringPlan.planRef
                  graphRef = graph.graphRef
                  consumedDependencyRefs = consumedDependencyRefs
                  consumedActivePairRefs = consumedActivePairRefs
                  activePairsBefore = activePairsBefore
                  activePairsAfter = activePairsAfter
                  proofRef = proofRef
                  closed =
                    graph.closed
                    && ([ SpecializationOwner
                          SpecializationGeneration
                          SpecializationInput
                          SpecializationInteractionProof
                          SpecializationLoweringBoundary ]
                        |> List.forall (fun role ->
                            provenPlan.dependencyEdges |> List.exists (fun edge -> edge.role = role))) }

            let planRef plan = plan.planRef
            let dependencyRefs plan = plan.dependencyEdges |> List.map (fun edge -> edge.edgeRef)
            let dependencyCount plan = plan.dependencyEdges.Length
            let isClosed plan =
                let roles = plan.dependencyEdges |> List.map (fun edge -> edge.role) |> Set.ofList
                [ SpecializationOwner
                  SpecializationGeneration
                  SpecializationInput
                  SpecializationInteractionProof
                  SpecializationLoweringBoundary ]
                |> List.forall (fun role -> Set.contains role roles)

