        type SomeWorkUnitId =
            | SomeJoinPointWorkUnit of WorkUnitId<ElaboratedPhase,JoinPointWorkKind>
            | SomeDefEqWorkUnit of WorkUnitId<ElaboratedPhase,DefEqWorkKind>
            | SomeReplayWorkUnit of WorkUnitId<ReplayPhase,ReplayWorkKind>
            | SomeCicInternWorkUnit of WorkUnitId<CicKernelPhase,CicInternWorkKind>
