        module SomeWorkUnitIdOps =
            let creditScope = function
                | SomeTerminalWorkUnit _ -> SemanticWorkTerminalProtocol
                | SomeJoinPointWorkUnit _
                | SomeDefEqWorkUnit _
                | SomeReplayWorkUnit _
                | SomeCicInternWorkUnit _
                | SomeCicWhnfWorkUnit _
                | SomeCicDefEqWorkUnit _
                | SomeCicUniverseWorkUnit _
                | SomeCicDeclarationWorkUnit _
                | SomeCicObligationWorkUnit _
                | SomeLoweringWorkUnit _
                | SomeArtifactWorkUnit _ -> SemanticWorkOperational

            let kindText = function
                | SomeJoinPointWorkUnit _ -> "JoinPoint"
                | SomeDefEqWorkUnit _ -> "DefEq"
                | SomeReplayWorkUnit _ -> "Replay"
                | SomeCicInternWorkUnit _ -> "CicIntern"
                | SomeCicWhnfWorkUnit _ -> "CicWhnf"
                | SomeCicDefEqWorkUnit _ -> "CicDefEq"
                | SomeCicUniverseWorkUnit _ -> "CicUniverse"
                | SomeCicDeclarationWorkUnit _ -> "CicDeclaration"
                | SomeCicObligationWorkUnit _ -> "CicObligation"
                | SomeLoweringWorkUnit(ExecutionTargetFSharp, _) -> "Lowering(FSharp)"
                | SomeLoweringWorkUnit(ExecutionTargetRust, _) -> "Lowering(Rust)"
                | SomeLoweringWorkUnit(ExecutionTargetGleam, _) -> "Lowering(Gleam)"
                | SomeLoweringWorkUnit(ExecutionTargetHvm, _) -> "Lowering(Hvm)"
                | SomeArtifactWorkUnit _ -> "Artifact"
                | SomeTerminalWorkUnit _ -> "Terminal"

            let digestText = function
                | SomeJoinPointWorkUnit workUnit -> WorkUnitIdOps.digestText workUnit
                | SomeDefEqWorkUnit workUnit -> WorkUnitIdOps.digestText workUnit
                | SomeReplayWorkUnit workUnit -> WorkUnitIdOps.digestText workUnit
                | SomeCicInternWorkUnit workUnit -> WorkUnitIdOps.digestText workUnit
                | SomeCicWhnfWorkUnit workUnit -> WorkUnitIdOps.digestText workUnit
                | SomeCicDefEqWorkUnit workUnit -> WorkUnitIdOps.digestText workUnit
                | SomeCicUniverseWorkUnit workUnit -> WorkUnitIdOps.digestText workUnit
                | SomeCicDeclarationWorkUnit workUnit -> WorkUnitIdOps.digestText workUnit
                | SomeCicObligationWorkUnit workUnit -> WorkUnitIdOps.digestText workUnit
                | SomeLoweringWorkUnit(_, workUnit) -> WorkUnitIdOps.digestText workUnit
                | SomeArtifactWorkUnit workUnit -> WorkUnitIdOps.digestText workUnit
                | SomeTerminalWorkUnit workUnit -> WorkUnitIdOps.digestText workUnit

            let stableText workUnit = kindText workUnit + ":" + digestText workUnit

        type WorkUnitDisposition =
