        module WorkUnitReceipt =
            let private dispositionStableText = function
                | WorkUnitAdmitted -> "admitted"
                | WorkUnitRunning -> "running"
                | WorkUnitRetired receipt -> "retired:" + ContentDigest.text receipt
                | WorkUnitBlocked blocker -> "blocked:" + ContentDigest.text blocker
                | WorkUnitFailed failure -> "failed:" + ContentDigest.text failure
                | WorkUnitCancelled reason -> "cancelled:" + ContentDigest.text reason
                | WorkUnitSuperseded generationTransition -> "superseded:" + ContentDigest.text generationTransition

            let create workUnit disposition semanticCost =
                let exactOnceRef =
                    ContentDigest.ofText
                        "work-unit-receipt"
                        (String.concat "|"
                            [ WorkUnitIdOps.digestText workUnit
                              dispositionStableText disposition
                              string (Measured.value semanticCost) ])
                { workUnit = workUnit
                  disposition = disposition
                  exactOnceRef = exactOnceRef
                  semanticCost = semanticCost }

            let exactOnceRef receipt = receipt.exactOnceRef
            let workUnit receipt = receipt.workUnit
            let disposition receipt = receipt.disposition
            let semanticCost receipt = receipt.semanticCost

        let workUnitReceiptExactOnceRef (receipt:WorkUnitReceipt<'Phase,'Kind>) = receipt.exactOnceRef
        let workUnitReceiptWorkUnit (receipt:WorkUnitReceipt<'Phase,'Kind>) = receipt.workUnit
        let workUnitReceiptDisposition (receipt:WorkUnitReceipt<'Phase,'Kind>) = receipt.disposition
        let workUnitReceiptSemanticCost (receipt:WorkUnitReceipt<'Phase,'Kind>) = receipt.semanticCost

