        type WorkCellReceipt<'T> = private {
            binding : StableBindingId
            resultDigest : ContentDigest
            value : 'T
            committedAtOrdinal : int64
        }

        type ConfluentWorkCell<'T> =
            | WorkCellPending of StableBindingId
            | WorkCellComplete of WorkCellReceipt<'T>
            | WorkCellConflict of evidence:Set<ContentDigest * ContentDigest>

        module ConfluentWorkCell =
            let complete binding committedAtOrdinal resultText value =
                WorkCellComplete {
                    binding = binding
                    resultDigest = ContentDigest.ofText "work-result" resultText
                    value = value
                    committedAtOrdinal = committedAtOrdinal
                }

            let private receiptDigest receipt = ContentDigest.text receipt.resultDigest
            let private conflictEvidence receipt = receipt.binding.digest, receipt.resultDigest
            let private sameReceiptIdentity left right =
                left.binding.digest = right.binding.digest && left.resultDigest = right.resultDigest

            // Commutative and idempotent by construction.  Cross-binding disagreement
            // is preserved as a set of (binding,result) evidence, so operand order
            // cannot choose which binding survives the conflict.
            let merge left right =
                match left, right with
                | WorkCellPending _, other
                | other, WorkCellPending _ -> other
                | WorkCellComplete l, WorkCellComplete r when sameReceiptIdentity l r ->
                    if l.committedAtOrdinal <= r.committedAtOrdinal then WorkCellComplete l
                    else WorkCellComplete r
                | WorkCellComplete l, WorkCellComplete r ->
                    WorkCellConflict(Set.ofList [conflictEvidence l; conflictEvidence r])
                | WorkCellConflict evidence, WorkCellComplete receipt
                | WorkCellComplete receipt, WorkCellConflict evidence ->
                    WorkCellConflict(Set.add (conflictEvidence receipt) evidence)
                | WorkCellConflict leftEvidence, WorkCellConflict rightEvidence ->
                    WorkCellConflict(Set.union leftEvidence rightEvidence)

            let tryValue = function
                | WorkCellComplete receipt -> Some receipt.value
                | WorkCellPending _
                | WorkCellConflict _ -> None

            let conflictDigests = function
                | WorkCellConflict evidence -> Some (evidence |> Set.map (snd >> ContentDigest.text))
                | WorkCellPending _
                | WorkCellComplete _ -> None

