            | KernelDiscovering
            | KernelElaborating
            | KernelSolvingUniverses
            | KernelCheckingDefEq
            | KernelCommittingDeclarations
            | KernelTerminalizing
            | KernelClosed
            | KernelFailedClosed

        type CpuTimeAuthority =
            | CpuTimeUnavailable of reason:OperationalReasonId
            | CpuTimeExclusiveWorker of workerRef:ContentDigest

        module CpuTimeAuthority =
            let stableText = function
                | CpuTimeUnavailable reason -> "unavailable:" + OperationalReasonIdOps.text reason
                | CpuTimeExclusiveWorker workerRef -> "exclusive_worker:" + ContentDigest.text workerRef

        type WorkTimingReceipt = private {
            cpuExclusive : CpuTime option
            cpuAuthority : CpuTimeAuthority
            wallInclusive : WallTime
            queueDelay : QueueDelay
            blockedOnChild : BlockedOnChildTime
            receiptRef : ContentDigest
        }

        type WorkTimingReceiptCreationError =
            | WorkTimingQueueOrChildExceedsWall of wallMs:int64 * queueMs:int64 * childMs:int64
            | WorkTimingCpuExceedsWall of cpuMs:int64 * wallMs:int64
            | WorkTimingExclusiveAuthorityMissingCpu
            | WorkTimingUnavailableAuthorityHasCpu

        let workTimingReceiptCreationErrorText = function
            | WorkTimingQueueOrChildExceedsWall(wallMs, queueMs, childMs) ->
                FastRuntimeFormat.format "QueueOrChildExceedsWall(wall_ms=%d|queue_ms=%d|child_ms=%d)" [| box wallMs; box queueMs; box childMs |]
            | WorkTimingCpuExceedsWall(cpuMs, wallMs) ->
                sprintf "CpuExceedsWall(cpu_ms=%d|wall_ms=%d)" cpuMs wallMs
            | WorkTimingExclusiveAuthorityMissingCpu ->
                "ExclusiveAuthorityMissingCpu"
            | WorkTimingUnavailableAuthorityHasCpu ->
                "UnavailableAuthorityHasCpu"

        module WorkTimingReceiptOps =
            let tryCreate cpuExclusive cpuAuthority wallInclusive queueDelay blockedOnChild =
                let wall = Measured.value wallInclusive
                let queue = Measured.value queueDelay
                let child = Measured.value blockedOnChild
                let validation =
                    if queue > wall || child > wall - queue then
                        Error(WorkTimingQueueOrChildExceedsWall(wall, queue, child))
                    else
                        match cpuExclusive, cpuAuthority with
                        | None, CpuTimeUnavailable _ -> Ok()
                        | Some cpu, CpuTimeExclusiveWorker _ when Measured.value cpu <= wall -> Ok()
                        | Some cpu, CpuTimeExclusiveWorker _ ->
                            Error(WorkTimingCpuExceedsWall(Measured.value cpu, wall))
                        | None, CpuTimeExclusiveWorker _ ->
                            Error WorkTimingExclusiveAuthorityMissingCpu
                        | Some _, CpuTimeUnavailable _ ->
                            Error WorkTimingUnavailableAuthorityHasCpu
                match validation with
                | Error error -> Error error
                | Ok () ->
                    let cpuText = cpuExclusive |> Option.map (Measured.value >> string) |> Option.defaultValue "null"
                    let receiptRef =
                        ContentDigest.ofText
                            "work-timing-receipt"
                            (String.concat "|"
                                [ "cpu=" + cpuText
                                  "cpu_authority=" + CpuTimeAuthority.stableText cpuAuthority
                                  "wall=" + string wall
                                  "queue=" + string queue
                                  "child=" + string child ])
                    Ok {
                        cpuExclusive = cpuExclusive
                        cpuAuthority = cpuAuthority
                        wallInclusive = wallInclusive
                        queueDelay = queueDelay
                        blockedOnChild = blockedOnChild
                        receiptRef = receiptRef
                    }

            let cpuExclusive receipt = receipt.cpuExclusive
            let cpuAuthority receipt = receipt.cpuAuthority
            let wallInclusive receipt = receipt.wallInclusive
            let queueDelay receipt = receipt.queueDelay
            let blockedOnChild receipt = receipt.blockedOnChild
            let receiptRef receipt = receipt.receiptRef

        type ProgressDenominator<'Unit> =
            | ProgressDenominatorOpen of reserveP50:Measured<'Unit> * reserveP90:Measured<'Unit>
            | ProgressDenominatorClosed

        type ExactCostLedger<'Unit> = private {
            completedCost : Measured<'Unit>
            discoveredCost : Measured<'Unit>
            blockedCost : Measured<'Unit>
            denominator : ProgressDenominator<'Unit>
            revision : int64
        }

        type ExactCostProjection<'Unit> = {
            completedCost : Measured<'Unit>
            totalLow : Measured<'Unit>
            totalMid : Measured<'Unit>
            totalHigh : Measured<'Unit>
            lowBp : BasisPoints
            midBp : BasisPoints
            highBp : BasisPoints
            exact : bool
            revision : int64
        }

        type ExactCostAdvance<'Unit> =
            | ExactCostAdvanced of ExactCostLedger<'Unit>
            | ExactCostIdempotent of ExactCostLedger<'Unit>
            | ExactCostRejectedRegression of current:ExactCostLedger<'Unit> * attemptedCompleted:Measured<'Unit> * attemptedDiscovered:Measured<'Unit>

        module ExactCostLedger =
            let private validate completedCost discoveredCost blockedCost =
                let completed = Measured.value completedCost
                let discovered = Measured.value discoveredCost
                let blocked = Measured.value blockedCost
                if completed > discovered + blocked then
                    invalidArg "completedCost" "completed cost cannot exceed admitted cost in the same unit"

            let create
                (completedCost:Measured<'Unit>)
                (discoveredCost:Measured<'Unit>)
                (blockedCost:Measured<'Unit>)
                (denominator:ProgressDenominator<'Unit>)
                : ExactCostLedger<'Unit> =
                validate completedCost discoveredCost blockedCost
                { completedCost = completedCost
                  discoveredCost = discoveredCost
                  blockedCost = blockedCost
                  denominator = denominator
                  revision = 0L }

            let advance
                (completedCost:Measured<'Unit>)
                (discoveredCost:Measured<'Unit>)
                (blockedCost:Measured<'Unit>)
                (denominator:ProgressDenominator<'Unit>)
                (ledger:ExactCostLedger<'Unit>)
                : ExactCostAdvance<'Unit> =
                validate completedCost discoveredCost blockedCost
                let completed = Measured.value completedCost
                let discovered = Measured.value discoveredCost
                let currentCompleted = Measured.value ledger.completedCost
                let currentDiscovered = Measured.value ledger.discoveredCost
                if completed < currentCompleted || discovered < currentDiscovered then
                    ExactCostRejectedRegression(ledger, completedCost, discoveredCost)
                elif completed = currentCompleted
                     && discovered = currentDiscovered
                     && blockedCost = ledger.blockedCost
                     && denominator = ledger.denominator then
                    ExactCostIdempotent ledger
                else
                    ExactCostAdvanced
                        { completedCost = completedCost
                          discoveredCost = discoveredCost
                          blockedCost = blockedCost
                          denominator = denominator
                          revision = ledger.revision + 1L }

            let private basisPoints completed total : BasisPoints =
                let completedValue = Measured.value completed
                let totalValue = Measured.value total
                if totalValue <= 0L then BasisPoints.zero
                else BasisPoints.create (min 10000L ((completedValue * 10000L) / totalValue))

            let project (ledger:ExactCostLedger<'Unit>) : ExactCostProjection<'Unit> =
                let admitted = Measured.add ledger.discoveredCost ledger.blockedCost
                let reserveP50, reserveP90, exact =
                    match ledger.denominator with
                    | ProgressDenominatorOpen(p50, p90) -> p50, Measured.maxValue p50 p90, false
                    | ProgressDenominatorClosed -> Measured.zero, Measured.zero, true
                let totalLow = Measured.add admitted reserveP90
                let totalMid = Measured.add admitted reserveP50
                let totalHigh = admitted
                { completedCost = ledger.completedCost
                  totalLow = totalLow
                  totalMid = totalMid
                  totalHigh = totalHigh
                  lowBp = basisPoints ledger.completedCost totalLow
                  midBp = basisPoints ledger.completedCost totalMid
                  highBp = basisPoints ledger.completedCost totalHigh
                  exact = exact && ledger.completedCost = totalHigh
                  revision = ledger.revision }

        type CompilerProgressLedger = private {
            ast : ExactCostLedger<AstCostUnit>
            semantic : ExactCostLedger<SemanticCostUnit>
        }

        type CompilerProgressProjection = {
            ast : ExactCostProjection<AstCostUnit>
            semantic : ExactCostProjection<SemanticCostUnit>
        }

        module CompilerProgressLedger =
            let create
                (ast:ExactCostLedger<AstCostUnit>)
                (semantic:ExactCostLedger<SemanticCostUnit>)
                : CompilerProgressLedger =
                { ast = ast; semantic = semantic }

            let project (ledger:CompilerProgressLedger) : CompilerProgressProjection =
                { ast = ExactCostLedger.project ledger.ast
                  semantic = ExactCostLedger.project ledger.semantic }

        type WorkCriticalPathSnapshot = private {
            remainingCost : CriticalPathCost
            p50 : WallTime option
            p90 : WallTime option
            activeNodes : NodeCount
            activeWorkers : WorkerCount
            snapshotRef : ContentDigest
        }

        module WorkCriticalPathSnapshot =
            let create remainingCost p50 p90 activeNodes activeWorkers =
                let p50Text = p50 |> Option.map (Measured.value >> string) |> Option.defaultValue "null"
                let p90Text = p90 |> Option.map (Measured.value >> string) |> Option.defaultValue "null"
                { remainingCost = remainingCost
                  p50 = p50
                  p90 = p90
                  activeNodes = activeNodes
                  activeWorkers = activeWorkers
                  snapshotRef =
                    ContentDigest.ofText
                        "work-critical-path"
                        (String.concat "|"
                            [ string (Measured.value remainingCost)
                              p50Text
                              p90Text
                              string (Measured.value activeNodes)
                              string (Measured.value activeWorkers) ]) }
            let remainingCost value = value.remainingCost
            let p50 value = value.p50
            let p90 value = value.p90
            let activeNodes value = value.activeNodes
            let activeWorkers value = value.activeWorkers
            let snapshotRef value = value.snapshotRef

        [<Struct>]
        type SemanticWorkUnitKeyId = private | SemanticWorkUnitKeyId of ContentDigest

        module SemanticWorkUnitKeyId =
            let ofWorkUnit (workUnit:WorkUnitId<'Phase,'Kind>) =
                workUnit
                |> WorkUnitIdOps.digest
                |> SemanticWorkUnitKeyId
            let digest (SemanticWorkUnitKeyId digest) = digest
            let text key = key |> digest |> ContentDigest.text
            let ofSomeWorkUnit = function
                | SomeJoinPointWorkUnit workUnit -> ofWorkUnit workUnit
                | SomeDefEqWorkUnit workUnit -> ofWorkUnit workUnit
                | SomeReplayWorkUnit workUnit -> ofWorkUnit workUnit
                | SomeCicInternWorkUnit workUnit -> ofWorkUnit workUnit
                | SomeCicWhnfWorkUnit workUnit -> ofWorkUnit workUnit
                | SomeCicDefEqWorkUnit workUnit -> ofWorkUnit workUnit
                | SomeCicUniverseWorkUnit workUnit -> ofWorkUnit workUnit
                | SomeCicDeclarationWorkUnit workUnit -> ofWorkUnit workUnit
                | SomeCicObligationWorkUnit workUnit -> ofWorkUnit workUnit
                | SomeLoweringWorkUnit(_, workUnit) -> ofWorkUnit workUnit
                | SomeArtifactWorkUnit workUnit -> ofWorkUnit workUnit
                | SomeTerminalWorkUnit workUnit -> ofWorkUnit workUnit

        type SemanticWorkLedgerConflict =
            | SemanticWorkUnitAlreadyAdmittedWithDifferentCost of workUnit:SemanticWorkUnitKeyId * previousCost:SemanticCost * nextCost:SemanticCost
            | SemanticWorkUnitIdentityConflict of workUnit:SemanticWorkUnitKeyId
            | SemanticWorkUnitReceiptConflict of workUnit:SemanticWorkUnitKeyId * previousReceipt:ContentDigest * nextReceipt:ContentDigest
            | SemanticWorkUnitReceiptBeforeAdmission of workUnit:SemanticWorkUnitKeyId

        type SemanticWorkLedger = private {
            admitted : Map<SemanticWorkUnitKeyId,SemanticCost>
            admittedUnits : Map<SemanticWorkUnitKeyId,SomeWorkUnitId>
            receipts : Map<SemanticWorkUnitKeyId,ContentDigest * WorkUnitDisposition * SemanticCost>
            // Per credit scope, kept with admittedUnits/receipts: the admitted units, how many have a receipt,
            // and the ones still open. Heartbeats and credit decisions read these instead of scanning.
            scopeAdmitted : Map<SemanticWorkCreditScope,int>
            scopeReceipts : Map<SemanticWorkCreditScope,int>
            scopeOpen : Map<SemanticWorkCreditScope,Set<SemanticWorkUnitKeyId>>
            // Running totals for `project`, and every admitted unit without a receipt, for `openKeys`.
            admittedCostSum : SemanticCost
            retiredCostSum : SemanticCost
            blockedCostSum : SemanticCost
            openAll : Set<SemanticWorkUnitKeyId>
            // Admitted units with neither a receipt nor a classified unit (admittedUnits).
            unclassifiedOpen : int
            // admitted.Count and receipts.Count: F#'s Map.Count walks the tree, and every JP worker dequeue
            // read both (through jpTryReserveObserverLane), ~4% of a compile.
            admittedTotal : int
            receiptTotal : int
        }

        // openWorkUnits and creditDigest are built on first read: most deciders only ask whether credit is
        // returned, and with thousands of open units building both was ~36% of mega_spiral_proves' CPU
        // (FRONTIER.md fix 36).
        type SemanticWorkCreditOutstanding = private {
            openUnits : Lazy<SemanticWorkUnitKeyId list>
            openCount : int
            openWorkUnits : Lazy<SomeWorkUnitId list>
            creditDigest : Lazy<ContentDigest>
        }

        type SemanticWorkCreditReturned = private {
            admittedCount : int
            receiptCount : int
            returnDigest : ContentDigest
        }

        type SemanticWorkCreditDecision =
            | SemanticWorkCreditOutstanding of SemanticWorkCreditOutstanding
            | SemanticWorkCreditReturned of SemanticWorkCreditReturned

        module SemanticWorkCreditDecision =
            let openUnitCount = function
                | SemanticWorkCreditOutstanding credit -> credit.openCount
                | SemanticWorkCreditReturned _ -> 0
            let digest = function
                | SemanticWorkCreditOutstanding credit -> credit.creditDigest.Value
                | SemanticWorkCreditReturned credit -> credit.returnDigest
            let openUnitTexts = function
                | SemanticWorkCreditOutstanding credit -> credit.openUnits.Value |> List.map SemanticWorkUnitKeyId.text
                | SemanticWorkCreditReturned _ -> []
            let openWorkUnitTexts = function
                | SemanticWorkCreditOutstanding credit -> credit.openWorkUnits.Value |> List.map SomeWorkUnitIdOps.stableText
                | SemanticWorkCreditReturned _ -> []
            let isReturned = function
                | SemanticWorkCreditReturned _ -> true
                | SemanticWorkCreditOutstanding _ -> false

        type SemanticWorkFailClosedReplayCreditReconciliation = private {
            cancelledWorkUnits : SomeWorkUnitId list
            cancelledCount : int
            remainingOperationalOpenCount : int
            receiptDigest : ContentDigest
        }

        module SemanticWorkFailClosedReplayCreditReconciliationOps =
            let cancelledWorkUnits (receipt:SemanticWorkFailClosedReplayCreditReconciliation) = receipt.cancelledWorkUnits
            let cancelledCount (receipt:SemanticWorkFailClosedReplayCreditReconciliation) = receipt.cancelledCount
            let remainingOperationalOpenCount (receipt:SemanticWorkFailClosedReplayCreditReconciliation) = receipt.remainingOperationalOpenCount
            let receiptDigest (receipt:SemanticWorkFailClosedReplayCreditReconciliation) = receipt.receiptDigest

        type SemanticWorkQuiescentReplayCreditReconciliation = private {
            cancelledWorkUnits : SomeWorkUnitId list
            cancelledCount : int
            remainingOperationalOpenCount : int
            quiescenceRef : ContentDigest
            receiptDigest : ContentDigest
        }

        module SemanticWorkQuiescentReplayCreditReconciliationOps =
            let cancelledWorkUnits (receipt:SemanticWorkQuiescentReplayCreditReconciliation) = receipt.cancelledWorkUnits
            let cancelledCount (receipt:SemanticWorkQuiescentReplayCreditReconciliation) = receipt.cancelledCount
            let remainingOperationalOpenCount (receipt:SemanticWorkQuiescentReplayCreditReconciliation) = receipt.remainingOperationalOpenCount
            let quiescenceRef (receipt:SemanticWorkQuiescentReplayCreditReconciliation) = receipt.quiescenceRef
            let receiptDigest (receipt:SemanticWorkQuiescentReplayCreditReconciliation) = receipt.receiptDigest

        type SemanticWorkFailClosedTerminalReservationReconciliation = private {
            retiredWorkUnit : SomeWorkUnitId option
            retiredCount : int
            openCountBefore : int
            remainingTerminalOpenCount : int
            receiptDigest : ContentDigest
        }

        module SemanticWorkFailClosedTerminalReservationReconciliationOps =
            let retiredWorkUnit (receipt:SemanticWorkFailClosedTerminalReservationReconciliation) = receipt.retiredWorkUnit
            let retiredCount (receipt:SemanticWorkFailClosedTerminalReservationReconciliation) = receipt.retiredCount
            let openCountBefore (receipt:SemanticWorkFailClosedTerminalReservationReconciliation) = receipt.openCountBefore
            let remainingTerminalOpenCount (receipt:SemanticWorkFailClosedTerminalReservationReconciliation) = receipt.remainingTerminalOpenCount
            let receiptDigest (receipt:SemanticWorkFailClosedTerminalReservationReconciliation) = receipt.receiptDigest

        type SemanticWorkFailClosedTerminalReservationError =
            | SemanticWorkTerminalReservationOperationalCreditStillOpen of openCount:int * openWorkUnits:SomeWorkUnitId list
            | SemanticWorkTerminalReservationMultiplicityViolation of openCount:int * openWorkUnits:SomeWorkUnitId list
            | SemanticWorkTerminalReservationLedgerConflict of SemanticWorkLedgerConflict

        module SemanticWorkLedger =
            let empty =
                { admitted = Map.empty; admittedUnits = Map.empty; receipts = Map.empty
                  scopeAdmitted = Map.empty; scopeReceipts = Map.empty; scopeOpen = Map.empty
                  admittedCostSum = Measured.zero; retiredCostSum = Measured.zero; blockedCostSum = Measured.zero
                  openAll = Set.empty; unclassifiedOpen = 0; admittedTotal = 0; receiptTotal = 0 }

            let private bumpScope scope (counts:Map<SemanticWorkCreditScope,int>) =
                Map.add scope (1 + defaultArg (Map.tryFind scope counts) 0) counts

            let private openSetOf scope (ledger:SemanticWorkLedger) =
                defaultArg (Map.tryFind scope ledger.scopeOpen) Set.empty

            let admit
                (workUnit:WorkUnitId<'Phase,'Kind>)
                (semanticCost:SemanticCost)
                (ledger:SemanticWorkLedger) =
                let key = SemanticWorkUnitKeyId.ofWorkUnit workUnit
                match Map.tryFind key ledger.admitted with
                | None ->
                    Ok { ledger with
                            admitted = Map.add key semanticCost ledger.admitted
                            admittedTotal = ledger.admittedTotal + 1
                            admittedCostSum = Measured.add ledger.admittedCostSum semanticCost
                            openAll = if Map.containsKey key ledger.receipts then ledger.openAll else Set.add key ledger.openAll
                            unclassifiedOpen =
                                if Map.containsKey key ledger.receipts || Map.containsKey key ledger.admittedUnits then ledger.unclassifiedOpen
                                else ledger.unclassifiedOpen + 1 }
                | Some previous when previous = semanticCost -> Ok ledger
                | Some previous -> Error(SemanticWorkUnitAlreadyAdmittedWithDifferentCost(key,previous,semanticCost))

            let apply
                (receipt:WorkUnitReceipt<'Phase,'Kind>)
                (ledger:SemanticWorkLedger) =
                let workUnit = workUnitReceiptWorkUnit receipt
                let key = SemanticWorkUnitKeyId.ofWorkUnit workUnit
                let receiptRef = workUnitReceiptExactOnceRef receipt
                let cost = workUnitReceiptSemanticCost receipt
                match Map.tryFind key ledger.admitted with
                | None -> Error(SemanticWorkUnitReceiptBeforeAdmission key)
                | Some admittedCost when admittedCost <> cost ->
                    Error(SemanticWorkUnitAlreadyAdmittedWithDifferentCost(key,admittedCost,cost))
                | Some _ ->
                    match Map.tryFind key ledger.receipts with
                    | None ->
                        let disposition = workUnitReceiptDisposition receipt
                        let ledger =
                            { ledger with
                                receipts = Map.add key (receiptRef, disposition, cost) ledger.receipts
                                receiptTotal = ledger.receiptTotal + 1
                                openAll = Set.remove key ledger.openAll
                                unclassifiedOpen =
                                    if Map.containsKey key ledger.admittedUnits then ledger.unclassifiedOpen
                                    else ledger.unclassifiedOpen - 1
                                retiredCostSum = (match disposition with WorkUnitRetired _ -> Measured.add ledger.retiredCostSum cost | _ -> ledger.retiredCostSum)
                                blockedCostSum = (match disposition with WorkUnitBlocked _ -> Measured.add ledger.blockedCostSum cost | _ -> ledger.blockedCostSum) }
                        match Map.tryFind key ledger.admittedUnits with
                        | Some workUnit ->
                            let scope = SomeWorkUnitIdOps.creditScope workUnit
                            Ok { ledger with
                                    scopeReceipts = bumpScope scope ledger.scopeReceipts
                                    scopeOpen = Map.add scope (Set.remove key (openSetOf scope ledger)) ledger.scopeOpen }
                        | None -> Ok ledger
                    | Some(previousRef, previousDisposition, previousCost)
                        when previousRef = receiptRef && previousDisposition = workUnitReceiptDisposition receipt && previousCost = cost -> Ok ledger
                    | Some(previousRef, _, _) ->
                        Error(SemanticWorkUnitReceiptConflict(key, previousRef, receiptRef))

            let admitSome workUnit cost ledger =
                let admitted =
                    match workUnit with
                    | SomeJoinPointWorkUnit workUnit -> admit workUnit cost ledger
                    | SomeDefEqWorkUnit workUnit -> admit workUnit cost ledger
                    | SomeReplayWorkUnit workUnit -> admit workUnit cost ledger
                    | SomeCicInternWorkUnit workUnit -> admit workUnit cost ledger
                    | SomeCicWhnfWorkUnit workUnit -> admit workUnit cost ledger
                    | SomeCicDefEqWorkUnit workUnit -> admit workUnit cost ledger
                    | SomeCicUniverseWorkUnit workUnit -> admit workUnit cost ledger
                    | SomeCicDeclarationWorkUnit workUnit -> admit workUnit cost ledger
                    | SomeCicObligationWorkUnit workUnit -> admit workUnit cost ledger
                    | SomeLoweringWorkUnit(_, workUnit) -> admit workUnit cost ledger
                    | SomeArtifactWorkUnit workUnit -> admit workUnit cost ledger
                    | SomeTerminalWorkUnit workUnit -> admit workUnit cost ledger
                match admitted with
                | Error conflict -> Error conflict
                | Ok nextLedger ->
                    let key = SemanticWorkUnitKeyId.ofSomeWorkUnit workUnit
                    match Map.tryFind key nextLedger.admittedUnits with
                    | None ->
                        let scope = SomeWorkUnitIdOps.creditScope workUnit
                        let hasReceipt = Map.containsKey key nextLedger.receipts
                        Ok { nextLedger with
                                admittedUnits = Map.add key workUnit nextLedger.admittedUnits
                                unclassifiedOpen = if hasReceipt then nextLedger.unclassifiedOpen else nextLedger.unclassifiedOpen - 1
                                scopeAdmitted = bumpScope scope nextLedger.scopeAdmitted
                                scopeReceipts = if hasReceipt then bumpScope scope nextLedger.scopeReceipts else nextLedger.scopeReceipts
                                scopeOpen =
                                    if hasReceipt then nextLedger.scopeOpen
                                    else Map.add scope (Set.add key (openSetOf scope nextLedger)) nextLedger.scopeOpen }
                    | Some existing when existing = workUnit -> Ok nextLedger
                    | Some _ -> Error(SemanticWorkUnitIdentityConflict key)

            let applySome receipt ledger =
                match receipt with
                | SomeJoinPointWorkReceipt receipt -> apply receipt ledger
                | SomeDefEqWorkReceipt receipt -> apply receipt ledger
                | SomeReplayWorkReceipt receipt -> apply receipt ledger
                | SomeCicInternWorkReceipt receipt -> apply receipt ledger
                | SomeCicWhnfWorkReceipt receipt -> apply receipt ledger
                | SomeCicDefEqWorkReceipt receipt -> apply receipt ledger
                | SomeCicUniverseWorkReceipt receipt -> apply receipt ledger
                | SomeCicDeclarationWorkReceipt receipt -> apply receipt ledger
                | SomeCicObligationWorkReceipt receipt -> apply receipt ledger
                | SomeArtifactWorkReceipt receipt -> apply receipt ledger
                | SomeTerminalWorkReceipt receipt -> apply receipt ledger

            let mutate mutation ledger =
                match mutation with
                | SemanticWorkNoMutation -> Ok ledger
                | SemanticWorkAdmit(workUnit, cost) -> admitSome workUnit cost ledger
                | SemanticWorkApply receipt -> applySome receipt ledger

            let project
                (denominator:ProgressDenominator<SemanticCostUnit>)
                (ledger:SemanticWorkLedger)
                : ExactCostProjection<SemanticCostUnit> =
                let admittedCost = ledger.admittedCostSum
                let completedCost = ledger.retiredCostSum
                let blockedCost = ledger.blockedCostSum
                let nonBlockedAdmitted = Measured.subtractFloor admittedCost blockedCost
                ExactCostLedger.create completedCost nonBlockedAdmitted blockedCost denominator
                |> ExactCostLedger.project

            let counts (ledger:SemanticWorkLedger) = ledger.admittedTotal, ledger.receiptTotal

            let openCount (ledger:SemanticWorkLedger) = max 0 (ledger.admittedTotal - ledger.receiptTotal)

            let countsForScope scope ledger =
                defaultArg (Map.tryFind scope ledger.scopeAdmitted) 0,
                defaultArg (Map.tryFind scope ledger.scopeReceipts) 0

            let unclassifiedOpenCount ledger = ledger.unclassifiedOpen

            let openKeys ledger = Set.toList ledger.openAll

            let openKeysForScope scope ledger =
                openSetOf scope ledger |> Set.toList

            let isOpenSomeWorkUnit workUnit ledger =
                let key = SemanticWorkUnitKeyId.ofSomeWorkUnit workUnit
                Map.containsKey key ledger.admitted
                && not (Map.containsKey key ledger.receipts)

            // Returned or outstanding is decided from the counts and an O(1) emptiness check; the open keys are listed only when read.
            let private creditDecisionFromCounts digestScope admittedCount receiptCount (openIsEmpty: bool) (openUnits: Lazy<SemanticWorkUnitKeyId list>) ledger =
                let returnedDigestKind, outstandingDigestKind =
                    match digestScope with
                    | None -> "semantic-work-credit-returned", "semantic-work-credit-outstanding"
                    | Some SemanticWorkOperational ->
                        "semantic-work-credit-returned:operational", "semantic-work-credit-outstanding:operational"
                    | Some SemanticWorkTerminalProtocol ->
                        "semantic-work-credit-returned:terminal-protocol", "semantic-work-credit-outstanding:terminal-protocol"
                let openWorkUnits =
                    lazy (
                        openUnits.Value
                        |> List.map (fun key ->
                            match Map.tryFind key ledger.admittedUnits with
                            | Some workUnit -> workUnit
                            | None -> invalidOp ("semantic work witness missing for open credit: " + SemanticWorkUnitKeyId.text key)))
                if openIsEmpty && admittedCount = receiptCount then
                    let digest =
                        ContentDigest.ofText
                            returnedDigestKind
                            (FastRuntimeFormat.format "admitted=%d|receipts=%d" [| box admittedCount; box receiptCount |])
                    SemanticWorkCreditReturned {
                        admittedCount = admittedCount
                        receiptCount = receiptCount
                        returnDigest = digest
                    }
                else
                    let digest =
                        lazy (
                            let openText = openUnits.Value |> List.map SemanticWorkUnitKeyId.text |> String.concat "|"
                            ContentDigest.ofText
                                outstandingDigestKind
                                (FastRuntimeFormat.format "admitted=%d|receipts=%d|open=%s" [| box admittedCount; box receiptCount; box openText |]))
                    SemanticWorkCreditOutstanding {
                        openUnits = openUnits
                        openCount = max 0 (admittedCount - receiptCount)
                        openWorkUnits = openWorkUnits
                        creditDigest = digest
                    }

            // A decision is a function of the (immutable) ledger and the scope, and the terminal-flow observers
            // ask for it many times between two mutations; each computation lists the open units and digests
            // them (~6% of a compile). Memoized per ledger instance; entries go with the ledger.
            let private creditDecisionMemo =
                System.Runtime.CompilerServices.ConditionalWeakTable<SemanticWorkLedger, System.Collections.Concurrent.ConcurrentDictionary<SemanticWorkCreditScope option, SemanticWorkCreditDecision>>()

            let private memoCreditDecision (ledger:SemanticWorkLedger) (scope:SemanticWorkCreditScope option) (compute: unit -> SemanticWorkCreditDecision) =
                let table = creditDecisionMemo.GetValue(ledger, fun _ -> System.Collections.Concurrent.ConcurrentDictionary())
                let mutable decision = Unchecked.defaultof<SemanticWorkCreditDecision>
                if table.TryGetValue(scope, &decision) then decision
                else table.GetOrAdd(scope, compute ())

            let creditDecision ledger =
                memoCreditDecision ledger None (fun () ->
                    let admittedCount = ledger.admittedTotal
                    let receiptCount = ledger.receiptTotal
                    // A receipt needs its admission, so equal counts mean nothing is open (no scan).
                    creditDecisionFromCounts None admittedCount receiptCount ledger.openAll.IsEmpty (lazy (openKeys ledger)) ledger)

            let creditDecisionForScope scope ledger =
                memoCreditDecision ledger (Some scope) (fun () ->
                    let admittedCount, receiptCount = countsForScope scope ledger
                    creditDecisionFromCounts (Some scope) admittedCount receiptCount (openSetOf scope ledger).IsEmpty (lazy (openKeysForScope scope ledger)) ledger)

            let reconcileFailClosedReplayCredits
                (failureRef:ContentDigest)
                (ledger:SemanticWorkLedger) =
                let openReplayCredits =
                    openKeysForScope SemanticWorkOperational ledger
                    |> List.choose (fun key ->
                        match Map.tryFind key ledger.admittedUnits, Map.tryFind key ledger.admitted with
                        | Some (SomeReplayWorkUnit workUnit), Some cost -> Some(key, workUnit, cost)
                        | _ -> None)
                let rec applyAll pending next cancelled =
                    match pending with
                    | [] -> Ok(next, List.rev cancelled)
                    | (key, workUnit, cost) :: tail ->
                        let cancellationRef =
                            ContentDigest.ofText
                                "semantic-work-fail-closed-replay-cancel"
                                (ContentDigest.text failureRef + "|" + SemanticWorkUnitKeyId.text key)
                        let receipt =
                            WorkUnitReceipt.create
                                workUnit
                                (WorkUnitCancelled cancellationRef)
                                cost
                        match apply receipt next with
                        | Error conflict -> Error conflict
                        | Ok applied ->
                            applyAll tail applied (SomeReplayWorkUnit workUnit :: cancelled)
                match applyAll openReplayCredits ledger [] with
                | Error conflict -> Error conflict
                | Ok(next, cancelled) ->
                    let remainingOperationalOpenCount =
                        openKeysForScope SemanticWorkOperational next |> List.length
                    let cancelledText =
                        cancelled
                        |> List.map SomeWorkUnitIdOps.stableText
                        |> String.concat "|"
                    let receiptDigest =
                        ContentDigest.ofText
                            "semantic-work-fail-closed-replay-reconciliation"
                            (FastRuntimeFormat.format
                                "%s|cancelled=%d|remaining=%d|work=%s"
                                [| box (ContentDigest.text failureRef)
                                   box cancelled.Length
                                   box remainingOperationalOpenCount
                                   box cancelledText |])
                    Ok(
                        next,
                        { cancelledWorkUnits = cancelled
                          cancelledCount = cancelled.Length
                          remainingOperationalOpenCount = remainingOperationalOpenCount
                          receiptDigest = receiptDigest })

            let reconcileQuiescentReplayCredits
                (quiescenceRef:ContentDigest)
                (ledger:SemanticWorkLedger) =
                let openReplayCredits =
                    openKeysForScope SemanticWorkOperational ledger
                    |> List.choose (fun key ->
                        match Map.tryFind key ledger.admittedUnits, Map.tryFind key ledger.admitted with
                        | Some (SomeReplayWorkUnit workUnit), Some cost -> Some(key, workUnit, cost)
                        | _ -> None)
                let rec applyAll pending next cancelled =
                    match pending with
                    | [] -> Ok(next, List.rev cancelled)
                    | (key, workUnit, cost) :: tail ->
                        let cancellationRef =
                            ContentDigest.ofText
                                "semantic-work-quiescent-replay-cancel"
                                (ContentDigest.text quiescenceRef + "|" + SemanticWorkUnitKeyId.text key)
                        let receipt =
                            WorkUnitReceipt.create
                                workUnit
                                (WorkUnitCancelled cancellationRef)
                                cost
                        match apply receipt next with
                        | Error conflict -> Error conflict
                        | Ok applied ->
                            applyAll tail applied (SomeReplayWorkUnit workUnit :: cancelled)
                match applyAll openReplayCredits ledger [] with
                | Error conflict -> Error conflict
                | Ok(next, cancelled) ->
                    let remainingOperationalOpenCount =
                        openKeysForScope SemanticWorkOperational next |> List.length
                    let cancelledText =
                        cancelled
                        |> List.map SomeWorkUnitIdOps.stableText
                        |> String.concat "|"
                    let receiptDigest =
                        ContentDigest.ofText
                            "semantic-work-quiescent-replay-reconciliation"
                            (FastRuntimeFormat.format
                                "%s|cancelled=%d|remaining=%d|work=%s"
                                [| box (ContentDigest.text quiescenceRef)
                                   box cancelled.Length
                                   box remainingOperationalOpenCount
                                   box cancelledText |])
                    Ok(
                        next,
                        { cancelledWorkUnits = cancelled
                          cancelledCount = cancelled.Length
                          remainingOperationalOpenCount = remainingOperationalOpenCount
                          quiescenceRef = quiescenceRef
                          receiptDigest = receiptDigest })

            let reconcileFailClosedTerminalReservation
                (retirementRef:ContentDigest)
                (ledger:SemanticWorkLedger) =
                let openOperationalWorkUnits =
                    openKeysForScope SemanticWorkOperational ledger
                    |> List.choose (fun key -> Map.tryFind key ledger.admittedUnits)
                let openTerminalCredits =
                    openKeysForScope SemanticWorkTerminalProtocol ledger
                    |> List.choose (fun key ->
                        match Map.tryFind key ledger.admittedUnits, Map.tryFind key ledger.admitted with
                        | Some (SomeTerminalWorkUnit workUnit), Some cost -> Some(key, workUnit, cost)
                        | _ -> None)
                let openCountBefore = List.length openTerminalCredits
                if not (List.isEmpty openOperationalWorkUnits) then
                    Error(
                        SemanticWorkTerminalReservationOperationalCreditStillOpen(
                            List.length openOperationalWorkUnits,
                            openOperationalWorkUnits))
                elif List.isEmpty openTerminalCredits then
                    let receiptDigest =
                        ContentDigest.ofText
                            "semantic-work-fail-closed-terminal-reservation-already-returned"
                            (ContentDigest.text retirementRef)
                    Ok(
                        ledger,
                        { retiredWorkUnit = None
                          retiredCount = 0
                          openCountBefore = 0
                          remainingTerminalOpenCount = 0
                          receiptDigest = receiptDigest })
                elif openCountBefore = 1 then
                    let key, workUnit, cost = List.head openTerminalCredits
                    let receipt =
                        WorkUnitReceipt.create
                            workUnit
                            (WorkUnitRetired retirementRef)
                            cost
                    match apply receipt ledger with
                    | Error conflict -> Error(SemanticWorkTerminalReservationLedgerConflict conflict)
                    | Ok next ->
                        let remainingTerminalOpenCount =
                            openKeysForScope SemanticWorkTerminalProtocol next |> List.length
                        let receiptDigest =
                            ContentDigest.ofText
                                "semantic-work-fail-closed-terminal-reservation-retired"
                                (FastRuntimeFormat.format
                                    "%s|work=%s|remaining=%d"
                                    [| box (ContentDigest.text retirementRef)
                                       box (SemanticWorkUnitKeyId.text key)
                                       box remainingTerminalOpenCount |])
                        Ok(
                            next,
                            { retiredWorkUnit = Some (SomeTerminalWorkUnit workUnit)
                              retiredCount = 1
                              openCountBefore = 1
                              remainingTerminalOpenCount = remainingTerminalOpenCount
                              receiptDigest = receiptDigest })
                else
                    let openWorkUnits =
                        openTerminalCredits
                        |> List.map (fun (_, workUnit, _) -> SomeTerminalWorkUnit workUnit)
                    Error(
                        SemanticWorkTerminalReservationMultiplicityViolation(
                            openCountBefore,
                            openWorkUnits))


        module SemanticWorkLedgerAuthority =
            let private gate = obj()
            let mutable private state = SemanticWorkLedger.empty

            let snapshot () = lock gate (fun () -> state)

            let transact mutation =
                lock gate (fun () ->
                    match SemanticWorkLedger.mutate mutation state with
                    | Ok next ->
                        state <- next
                        Ok next
                    | Error conflict -> Error conflict)

            let transactMany mutations =
                lock gate (fun () ->
                    let mutable nextState = state
                    let mutable conflicts : SemanticWorkLedgerConflict list = []
                    for mutation in mutations do
                        match SemanticWorkLedger.mutate mutation nextState with
                        | Ok next -> nextState <- next
                        | Error conflict -> conflicts <- conflict :: conflicts
                    state <- nextState
                    nextState, List.rev conflicts)

            let project denominator =
                lock gate (fun () -> SemanticWorkLedger.project denominator state)

            let counts () = lock gate (fun () -> SemanticWorkLedger.counts state)

            let countsForScope scope =
                lock gate (fun () -> SemanticWorkLedger.countsForScope scope state)

            let openCount () = lock gate (fun () -> SemanticWorkLedger.openCount state)

            let unclassifiedOpenCount () =
                lock gate (fun () -> SemanticWorkLedger.unclassifiedOpenCount state)

            let creditDecision () =
                lock gate (fun () -> SemanticWorkLedger.creditDecision state)

            let creditDecisionForScope scope =
                lock gate (fun () -> SemanticWorkLedger.creditDecisionForScope scope state)

            let isOpenSomeWorkUnit workUnit =
                lock gate (fun () -> SemanticWorkLedger.isOpenSomeWorkUnit workUnit state)

            let reconcileFailClosedReplayCredits failureRef =
                lock gate (fun () ->
                    match SemanticWorkLedger.reconcileFailClosedReplayCredits failureRef state with
                    | Error conflict -> Error conflict
                    | Ok(next, receipt) ->
                        state <- next
                        Ok receipt)

            let reconcileQuiescentReplayCredits quiescenceRef =
                lock gate (fun () ->
                    match SemanticWorkLedger.reconcileQuiescentReplayCredits quiescenceRef state with
                    | Error conflict -> Error conflict
                    | Ok(next, receipt) ->
                        state <- next
                        Ok receipt)

            let reconcileFailClosedTerminalReservation retirementRef =
                lock gate (fun () ->
                    match SemanticWorkLedger.reconcileFailClosedTerminalReservation retirementRef state with
                    | Error conflict -> Error conflict
                    | Ok(next, receipt) ->
                        state <- next
                        Ok receipt)


        type PortableKernelOp =
            | KernelFork
            | KernelJoin
            | KernelRace
            | KernelSleep
            | KernelYield
            | KernelFillOnce
            | KernelReadOnce

        // Destructive migration: the concurrency vocabulary is now
        // paired with a law surface and opaque resources. Host scheduler types
        // remain below sealed adapters; compiler algorithms consume this domain.
        type RuntimeBackend =
            | RuntimeBackendHopac
            | RuntimeBackendRust
            | RuntimeBackendBeam
            | RuntimeBackendReference

        type PortableRuntimeLaw =
            | RuntimeStructuredChildLifetime
            | RuntimeBoundedMailbox
            | RuntimeCancellationIdempotent
            | RuntimeRaceLoserCleanup
            | RuntimeMemoryVisibility
            | RuntimeDeterministicFailure
            | RuntimeMonotonicTimer
            | RuntimeNoWorkAfterScopeClose

        let private portableRuntimeLawStableText = function
            | RuntimeStructuredChildLifetime -> "structured_child_lifetime"
            | RuntimeBoundedMailbox -> "bounded_mailbox"
            | RuntimeCancellationIdempotent -> "cancellation_idempotent"
            | RuntimeRaceLoserCleanup -> "race_loser_cleanup"
            | RuntimeMemoryVisibility -> "memory_visibility"
            | RuntimeDeterministicFailure -> "deterministic_failure"
            | RuntimeMonotonicTimer -> "monotonic_timer"
            | RuntimeNoWorkAfterScopeClose -> "no_work_after_scope_close"

        type MailboxBackpressure =
            | MailboxFailClosed
            | MailboxEvictOldest
            | MailboxConflateLatest

        // Portable runtime typestate: illegal scope transitions are represented
        // by the type parameter instead of a runtime state enum.
        type FiberScopeOpenPhase = class end
        type FiberScopeCancellingPhase = class end
        type FiberScopeClosedPhase = class end

        type FiberScopeRetireError =
            | FiberScopeForeignChild
            | FiberScopeChildNotLive

        type FiberScopeCloseError =
            | FiberScopeChildrenStillLive of count:int

        [<Struct>]
        type FiberScopeId = private | FiberScopeId of ContentDigest

        [<Struct>]
        type FiberId = private {
            scope : FiberScopeId
            ordinal : int64
        }

        type CancellationState =
            | CancellationOpen
            | CancellationRequested of reason:ContentDigest
            | CancellationAcknowledged of reason:ContentDigest

        type CancellationSource = private {
            sourceRef : ContentDigest
            state : CancellationState
        }

        type StructuredFailure = private {
            failureRef : ContentDigest
            category : string
            causalPredecessors : ContentDigest list
        }

        type Choice<'T> =
            | ChoicePending of choiceRef:ContentDigest * branchCount:int
            | ChoiceCommitted of choiceRef:ContentDigest * branch:int * value:'T
            | ChoiceCancelled of choiceRef:ContentDigest * reason:ContentDigest
            | ChoiceFailed of choiceRef:ContentDigest * failure:StructuredFailure

        type Rendezvous<'T> =
            | RendezvousWaiting of rendezvousRef:ContentDigest
            | RendezvousMatched of rendezvousRef:ContentDigest * value:'T
            | RendezvousCancelled of rendezvousRef:ContentDigest * reason:ContentDigest

        type OneShot<'T> =
            | OneShotEmpty of cellRef:ContentDigest
            | OneShotFilled of cellRef:ContentDigest * value:'T * receiptRef:ContentDigest
            | OneShotCancelled of cellRef:ContentDigest * reason:ContentDigest
            | OneShotConflict of cellRef:ContentDigest * receipts:Set<ContentDigest>

        // Destructive portable-runtime cutover, pass 4/5.  The operational
        // compiler stores only these opaque resources and effects.  Concrete
        // Hopac payloads are private to FSharpHopacRuntimeAdapter; Rust and BEAM
        // adapters lower the same resource/effect identities independently.
        type PortableMailboxLane =
            | PortableControlLane
            | PortableSemanticLane
            | PortableObserverLane

        type PortableEffectOrigin =
            | PortablePureEffect
            | PortableDeferredCommandGraph of graphRef:ContentDigest
            | PortableFSharpHopacBoundary of boundaryRef:ContentDigest

        type private PortableEffectPayload<'T> =
            | PortableFSharpHopacEffectPayload of Hopac.Job<'T>

        type private PortableMailboxPayload<'T> =
            | PortableFSharpHopacMailboxPayload of Hopac.Ch<'T>

        type PortableEffectFor<'Backend,'T> = private {
            effectRef : ContentDigest
            origin : PortableEffectOrigin
            payload : PortableEffectPayload<'T>
        }

        type PortableEffect<'T> = PortableEffectFor<PortableFSharpHopacBackend,'T>

        type PortableMailboxFor<'Backend,'T> = private {
            resourceId : PortableResourceId
            lane : PortableMailboxLane
            capacity : int
            backpressure : MailboxBackpressure
            payload : PortableMailboxPayload<'T>
        }

        type PortableMailbox<'T> = PortableMailboxFor<PortableFSharpHopacBackend,'T>

        type PortableCancellationHandleFor<'Backend> = private {
            cancellationRef : ContentDigest
            reason : OperationalReasonId option
        }

        type PortableCancellationHandle = PortableCancellationHandleFor<PortableFSharpHopacBackend>

        type PortableTimerFor<'Backend> = private {
            timerRef : ContentDigest
            delayMilliseconds : int
        }

        type PortableTimer = PortableTimerFor<PortableFSharpHopacBackend>

        type PortableFiberLeaseFor<'Backend> = private {
            scopeRef : ContentDigest
            fiberRef : ContentDigest
            cancellation : PortableCancellationHandleFor<'Backend>
        }

        type PortableFiberLease = PortableFiberLeaseFor<PortableFSharpHopacBackend>

        module PortableCancellationHandleOps =
            let cancellationRef (handle:PortableCancellationHandleFor<'Backend>) = handle.cancellationRef
            let reason (handle:PortableCancellationHandleFor<'Backend>) = handle.reason

        module PortableTimerOps =
            let timerRef (timer:PortableTimerFor<'Backend>) = timer.timerRef
            let delayMilliseconds (timer:PortableTimerFor<'Backend>) = timer.delayMilliseconds

        module PortableFiberLeaseOps =
            let scopeRef (lease:PortableFiberLeaseFor<'Backend>) = lease.scopeRef
            let fiberRef (lease:PortableFiberLeaseFor<'Backend>) = lease.fiberRef
            let cancellation (lease:PortableFiberLeaseFor<'Backend>) = lease.cancellation

        type PortableRuntimeAdapterKind =
            | PortableFSharpHopacAdapter
            | PortableRustAdapter
            | PortableBeamAdapter

        type PortableRuntimeAdapterReceipt = private {
            adapter : PortableRuntimeAdapterKind
            contractRef : ContentDigest
            effectCount : int64
            mailboxCount : int64
            oneShotCount : int64
            fiberCount : int64
            receiptRef : ContentDigest
        }

        module PortableRuntimeAdapterReceiptOps =
            let adapter (receipt:PortableRuntimeAdapterReceipt) = receipt.adapter
            let contractRef (receipt:PortableRuntimeAdapterReceipt) = receipt.contractRef
            let effectCount (receipt:PortableRuntimeAdapterReceipt) = receipt.effectCount
            let mailboxCount (receipt:PortableRuntimeAdapterReceipt) = receipt.mailboxCount
            let oneShotCount (receipt:PortableRuntimeAdapterReceipt) = receipt.oneShotCount
            let fiberCount (receipt:PortableRuntimeAdapterReceipt) = receipt.fiberCount
            let receiptRef (receipt:PortableRuntimeAdapterReceipt) = receipt.receiptRef

        module PortableEffectOps =
            let effectRef (effect:PortableEffect<'T>) = effect.effectRef
            let origin (effect:PortableEffect<'T>) = effect.origin

        module PortableOneShotCellOps =
            let resourceId (cell:PortableOneShotCell<'T>) = cell.resourceId

        module PortableMailboxOps =
            let resourceId (mailbox:PortableMailbox<'T>) = mailbox.resourceId
            let lane (mailbox:PortableMailbox<'T>) = mailbox.lane
            let capacity (mailbox:PortableMailbox<'T>) = mailbox.capacity
            let backpressure (mailbox:PortableMailbox<'T>) = mailbox.backpressure

        module FSharpHopacRuntimeAdapter =
            let private effectCounter = ref 0L
            let private mailboxCounter = ref 0L
            let private fiberCounter = ref 0L
            let private retiredFiberRefs =
                System.Collections.Concurrent.ConcurrentDictionary<ContentDigest,byte>()

            let private next (counter:int64 ref) =
                lock counter (fun () ->
                    counter.Value <- counter.Value + 1L
                    counter.Value)

            let effect label (program:Hopac.Job<'T>) : PortableEffect<'T> =
                let ordinal = next effectCounter
                let boundaryRef =
                    ContentDigest.ofText
                        "portable-fsharp-hopac-effect"
                        (label + "|ordinal=" + string ordinal)
                { effectRef = boundaryRef
                  origin = PortableFSharpHopacBoundary boundaryRef
                  payload = PortableFSharpHopacEffectPayload program }

            let toJob<'T> (effect:PortableEffect<'T>) : Hopac.Job<'T> =
                match effect.payload with
                | PortableFSharpHopacEffectPayload program -> program

            let oneShot<'T> label : PortableOneShotCell<'T> =
                PortableOneShotRuntime.oneShot<'T> label

            let wrapOneShot<'T> label (cell:Hopac.IVar<'T>) : PortableOneShotCell<'T> =
                PortableOneShotRuntime.wrapOneShot<'T> label cell

            let fillOneShot<'T> (cell:PortableOneShotCell<'T>) (value:'T) : Hopac.Job<unit> =
                PortableOneShotRuntime.fillOneShot<'T> cell value

            let tryFillOneShot<'T> (cell:PortableOneShotCell<'T>) (value:'T) : Hopac.Job<unit> =
                PortableOneShotRuntime.tryFillOneShot<'T> cell value

            let readOneShot<'T> (cell:PortableOneShotCell<'T>) : Hopac.Job<'T> =
                PortableOneShotRuntime.readOneShot<'T> cell

            let projectOneShotToFSharp<'T> (cell:PortableOneShotCell<'T>) : Hopac.IVar<'T> =
                PortableOneShotRuntime.projectOneShotToFSharp<'T> cell

            let tryReadOneShotNow<'T> (cell:PortableOneShotCell<'T>) : 'T option =
                PortableOneShotRuntime.tryReadOneShotNow<'T> cell

            let raceOneShots
                label
                (left:PortableOneShotCell<'A>)
                (mapLeft:'A -> 'R)
                (right:PortableOneShotCell<'B>)
                (mapRight:'B -> 'R)
                : PortableEffect<'R> =
                effect label (
                    Hopac.Alt.choose [
                        Hopac.IVar.read (PortableOneShotRuntime.projectOneShotToFSharp left)
                        |> Hopac.Alt.afterFun mapLeft
                        Hopac.IVar.read (PortableOneShotRuntime.projectOneShotToFSharp right)
                        |> Hopac.Alt.afterFun mapRight
                    ])

            let start (portableEffect:PortableEffect<unit>) : Hopac.Job<unit> =
                Hopac.Job.start (toJob portableEffect)

            let mailbox label lane capacity backpressure : PortableMailbox<'T> =
                if capacity < 0 then invalidArg "capacity" "portable mailbox capacity cannot be negative"
                let ordinal = next mailboxCounter
                { resourceId = PortableResourceId(ContentDigest.ofText "portable-resource" (label + "|mailbox=" + string ordinal))
                  lane = lane
                  capacity = capacity
                  backpressure = backpressure
                  payload = PortableFSharpHopacMailboxPayload(Hopac.Ch<'T>()) }

            let private mailboxChannel (mailbox:PortableMailbox<'T>) =
                match mailbox.payload with
                | PortableFSharpHopacMailboxPayload channel -> channel

            let send mailbox value : Hopac.Job<unit> =
                Hopac.Ch.send (mailboxChannel mailbox) value

            let take mailbox : Hopac.Job<'T> =
                Hopac.Ch.take (mailboxChannel mailbox)

            let chooseTake label (left:PortableMailbox<'T>) (right:PortableMailbox<'T>) : PortableEffect<'T> =
                effect label (
                    Hopac.Alt.choose [
                        Hopac.Ch.take (mailboxChannel left)
                        Hopac.Ch.take (mailboxChannel right)
                    ])

            let sleep milliseconds : PortableEffect<unit> =
                effect ("timer:" + string milliseconds) (Hopac.timeOutMillis milliseconds)

            let cancellation reason : PortableCancellationHandle =
                { cancellationRef = ContentDigest.ofText "portable-cancellation" (OperationalReasonIdOps.text reason)
                  reason = Some reason }

            let timer label milliseconds : PortableTimer =
                if milliseconds < 0 then invalidArg "milliseconds" "portable timer cannot be negative"
                { timerRef = ContentDigest.ofText "portable-timer" (label + "|delay_ms=" + string milliseconds)
                  delayMilliseconds = milliseconds }

            let leaseFiber scopeLabel cancellationReason : PortableFiberLease =
                let ordinal = next fiberCounter
                let scopeRef = ContentDigest.ofText "portable-fiber-scope" scopeLabel
                let fiberRef =
                    ContentDigest.ofText
                        "portable-fiber"
                        (scopeLabel + "|ordinal=" + string ordinal)
                { scopeRef = scopeRef
                  fiberRef = fiberRef
                  cancellation = cancellation cancellationReason }

            let retireFiber (lease:PortableFiberLease) =
                let applied = retiredFiberRefs.TryAdd(lease.fiberRef, 0uy)
                let receiptRef =
                    ContentDigest.ofText
                        "portable-fiber-retired"
                        (ContentDigest.text lease.scopeRef
                         + "|fiber=" + ContentDigest.text lease.fiberRef
                         + "|applied=" + string applied)
                receiptRef, applied

            let receipt contractRef =
                let effects = effectCounter.Value
                let mailboxes = mailboxCounter.Value
                let oneShots = PortableOneShotRuntime.count ()
                let fibers = fiberCounter.Value
                { adapter = PortableFSharpHopacAdapter
                  contractRef = contractRef
                  effectCount = effects
                  mailboxCount = mailboxes
                  oneShotCount = oneShots
                  fiberCount = fibers
                  receiptRef =
                    ContentDigest.ofText
                        "portable-runtime-adapter-receipt"
                        (FastRuntimeFormat.format "hopac|contract=%s|effects=%d|mailboxes=%d|one_shots=%d|fibers=%d" [| box (ContentDigest.text contractRef); box effects; box mailboxes; box oneShots; box fibers |]) }

        // Bonus breakthrough pass: the operational compiler is forbidden from naming
        // the concrete Hopac adapter directly.  This single integration point owns
        // the host representation while the surrounding compiler carries only
        // PortableEffect, PortableMailbox and PortableOneShotCell values.
        module CompilerRuntimeKernel =
            let backend = RuntimeBackendHopac
            let effect<'T> label (program:Hopac.Job<'T>) : PortableEffect<'T> =
                FSharpHopacRuntimeAdapter.effect label program

            let toJob<'T> (effect:PortableEffect<'T>) : Hopac.Job<'T> =
                FSharpHopacRuntimeAdapter.toJob effect
            let oneShot<'T> label : PortableOneShotCell<'T> =
                FSharpHopacRuntimeAdapter.oneShot<'T> label
            let wrapOneShot<'T> label (cell:Hopac.IVar<'T>) : PortableOneShotCell<'T> =
                FSharpHopacRuntimeAdapter.wrapOneShot<'T> label cell

            let fillOneShot<'T> (cell:PortableOneShotCell<'T>) (value:'T) : Hopac.Job<unit> =
                FSharpHopacRuntimeAdapter.fillOneShot<'T> cell value

            let tryFillOneShot<'T> (cell:PortableOneShotCell<'T>) (value:'T) : Hopac.Job<unit> =
                FSharpHopacRuntimeAdapter.tryFillOneShot<'T> cell value

            let readOneShot<'T> (cell:PortableOneShotCell<'T>) : Hopac.Job<'T> =
                FSharpHopacRuntimeAdapter.readOneShot<'T> cell

            let projectOneShotToFSharp<'T> (cell:PortableOneShotCell<'T>) : Hopac.IVar<'T> =
                FSharpHopacRuntimeAdapter.projectOneShotToFSharp<'T> cell

            let tryReadOneShotNow<'T> (cell:PortableOneShotCell<'T>) : 'T option =
                FSharpHopacRuntimeAdapter.tryReadOneShotNow<'T> cell

            let raceOneShots<'A,'B,'R>
                label
                (left:PortableOneShotCell<'A>)
                (mapLeft:'A -> 'R)
                (right:PortableOneShotCell<'B>)
                (mapRight:'B -> 'R)
                : PortableEffect<'R> =
                FSharpHopacRuntimeAdapter.raceOneShots label left mapLeft right mapRight
            let start = FSharpHopacRuntimeAdapter.start
            let mailbox<'T> label lane capacity backpressure : PortableMailbox<'T> =
                FSharpHopacRuntimeAdapter.mailbox label lane capacity backpressure
            let send<'T> (mailbox:PortableMailbox<'T>) (value:'T) : Hopac.Job<unit> =
                FSharpHopacRuntimeAdapter.send mailbox value

            let take<'T> (mailbox:PortableMailbox<'T>) : Hopac.Job<'T> =
                FSharpHopacRuntimeAdapter.take mailbox

            let chooseTake<'T>
                label
                (left:PortableMailbox<'T>)
                (right:PortableMailbox<'T>)
                : PortableEffect<'T> =
                FSharpHopacRuntimeAdapter.chooseTake label left right
            let sleep = FSharpHopacRuntimeAdapter.sleep
            let cancellation = FSharpHopacRuntimeAdapter.cancellation
            let timer = FSharpHopacRuntimeAdapter.timer
            let leaseFiber = FSharpHopacRuntimeAdapter.leaseFiber
            let retireFiber = FSharpHopacRuntimeAdapter.retireFiber
            let receipt = FSharpHopacRuntimeAdapter.receipt

            // The only synchronous Hopac boundary that remains in the compiler.
            // Callers must be host boundaries; compiler jobs compose PortableEffect
            // values instead of recursively entering the scheduler.
            let runHostBoundary label (program:Hopac.Job<'T>) : 'T =
                let _boundaryRef =
                    ContentDigest.ofText "portable-host-boundary" label
                Hopac.run program

        type FiberScope<'Phase> = private {
            scopeId : FiberScopeId
            nextOrdinal : int64
            liveChildren : Set<int64>
            cancellation : CancellationSource
        }

        module FiberScope =
            let private scopeDigest label = ContentDigest.ofText "fiber-scope" label

            let create label : FiberScope<FiberScopeOpenPhase> =
                let digest = scopeDigest label
                { scopeId = FiberScopeId digest
                  nextOrdinal = 1L
                  liveChildren = Set.empty
                  cancellation = { sourceRef = ContentDigest.ofText "cancellation" label; state = CancellationOpen } }

            let fork (scope:FiberScope<FiberScopeOpenPhase>) : FiberId * FiberScope<FiberScopeOpenPhase> =
                let ordinal = scope.nextOrdinal
                let fiber = { scope = scope.scopeId; ordinal = ordinal }
                fiber, { scope with nextOrdinal = ordinal + 1L; liveChildren = Set.add ordinal scope.liveChildren }

            let retire fiber (scope:FiberScope<'Phase>) : Result<FiberScope<'Phase>, FiberScopeRetireError> =
                if fiber.scope <> scope.scopeId then Error FiberScopeForeignChild
                elif not (Set.contains fiber.ordinal scope.liveChildren) then Error FiberScopeChildNotLive
                else Ok { scope with liveChildren = Set.remove fiber.ordinal scope.liveChildren }

            let requestCancellation reason (scope:FiberScope<FiberScopeOpenPhase>) : FiberScope<FiberScopeCancellingPhase> =
                let reasonRef = ContentDigest.ofText "cancellation-reason" reason
                { scopeId = scope.scopeId
                  nextOrdinal = scope.nextOrdinal
                  liveChildren = scope.liveChildren
                  cancellation = { scope.cancellation with state = CancellationRequested reasonRef } }

            let closeOpen (scope:FiberScope<FiberScopeOpenPhase>) : Result<FiberScope<FiberScopeClosedPhase>, FiberScopeCloseError> =
                if Set.isEmpty scope.liveChildren then
                    Ok { scopeId = scope.scopeId; nextOrdinal = scope.nextOrdinal; liveChildren = Set.empty; cancellation = scope.cancellation }
                else Error(FiberScopeChildrenStillLive scope.liveChildren.Count)

            let closeCancelling (scope:FiberScope<FiberScopeCancellingPhase>) : Result<FiberScope<FiberScopeClosedPhase>, FiberScopeCloseError> =
                if Set.isEmpty scope.liveChildren then
                    Ok { scopeId = scope.scopeId; nextOrdinal = scope.nextOrdinal; liveChildren = Set.empty; cancellation = scope.cancellation }
                else Error(FiberScopeChildrenStillLive scope.liveChildren.Count)

        type PortableRuntimeLawEvidence =
            | RuntimeLawDeclaredOnly
            | RuntimeLawVerifiedAgainstModel of traceRef:ContentDigest * modelRef:ContentDigest
            | RuntimeLawRejectedByModel of traceRef:ContentDigest * counterexampleRef:ContentDigest

        type PortableRuntimeDeclaredPhase = class end
        type PortableRuntimeVerifiedPhase = class end

        type PortableRuntimeContract<'Phase> = private {
            backend : RuntimeBackend
            operations : Set<PortableKernelOp>
            lawEvidence : Map<PortableRuntimeLaw, PortableRuntimeLawEvidence>
            mailboxBackpressure : Set<MailboxBackpressure>
            verificationRef : ContentDigest option
        }

        type PortableRuntimeContractSealFailure =
            | PortableRuntimeContractPending of missingLaws:PortableRuntimeLaw list * missingOperations:PortableKernelOp list
            | PortableRuntimeContractRejected of rejectedLaws:PortableRuntimeLaw list

        let private portableRuntimeOperationStableText = function
            | KernelFork -> "fork"
            | KernelJoin -> "join"
            | KernelRace -> "race"
            | KernelSleep -> "sleep"
            | KernelYield -> "yield"
            | KernelFillOnce -> "fill-once"
            | KernelReadOnce -> "read-once"

        let private portableRuntimeSealFailureStableText = function
            | PortableRuntimeContractPending(missingLaws, missingOperations) ->
                "pending(laws="
                + (missingLaws |> List.map portableRuntimeLawStableText |> String.concat ",")
                + "|operations="
                + (missingOperations |> List.map portableRuntimeOperationStableText |> String.concat ",")
                + ")"
            | PortableRuntimeContractRejected rejectedLaws ->
                "rejected(laws=" + (rejectedLaws |> List.map portableRuntimeLawStableText |> String.concat ",") + ")"

        module PortableRuntimeContract =
            let private allOperations =
                Set.ofList [ KernelFork; KernelJoin; KernelRace; KernelSleep; KernelYield; KernelFillOnce; KernelReadOnce ]

            let private allLaws =
                Set.ofList [ RuntimeStructuredChildLifetime
                             RuntimeBoundedMailbox
                             RuntimeCancellationIdempotent
                             RuntimeRaceLoserCleanup
                             RuntimeMemoryVisibility
                             RuntimeDeterministicFailure
                             RuntimeMonotonicTimer
                             RuntimeNoWorkAfterScopeClose ]

            let private declaredEvidence laws =
                laws
                |> Seq.map (fun law -> law, RuntimeLawDeclaredOnly)
                |> Map.ofSeq

            let create backend operations claimedLaws backpressure : PortableRuntimeContract<PortableRuntimeDeclaredPhase> =
                { backend = backend
                  operations = Set.ofList operations
                  lawEvidence = declaredEvidence claimedLaws
                  mailboxBackpressure = Set.ofList backpressure
                  verificationRef = None }

            let verifyLaw law traceRef modelRef (contract:PortableRuntimeContract<'Phase>) : PortableRuntimeContract<'Phase> =
                { contract with lawEvidence = Map.add law (RuntimeLawVerifiedAgainstModel(traceRef, modelRef)) contract.lawEvidence }

            let rejectLaw law traceRef counterexampleRef (contract:PortableRuntimeContract<'Phase>) : PortableRuntimeContract<'Phase> =
                { contract with lawEvidence = Map.add law (RuntimeLawRejectedByModel(traceRef, counterexampleRef)) contract.lawEvidence }

            let runtimeLawStableText = portableRuntimeLawStableText

            let private referenceModelRef = ContentDigest.ofText "portable-runtime-model" "reference-state-machine-v1"

            let private verifyReferenceLaw contract law =
                let traceRef = ContentDigest.ofText "portable-runtime-law-trace" ("reference:" + runtimeLawStableText law)
                verifyLaw law traceRef referenceModelRef contract

            let hopacDeclared = create RuntimeBackendHopac (Set.toList allOperations) (Set.toList allLaws) [MailboxFailClosed; MailboxConflateLatest]
            let rustDeclared = create RuntimeBackendRust (Set.toList allOperations) (Set.toList allLaws) [MailboxFailClosed; MailboxEvictOldest; MailboxConflateLatest]
            let beamDeclared = create RuntimeBackendBeam (Set.toList allOperations) (Set.toList allLaws) [MailboxFailClosed; MailboxConflateLatest]

            let missingLaws (contract:PortableRuntimeContract<'Phase>) =
                allLaws
                |> Set.toList
                |> List.filter (fun law ->
                    match Map.tryFind law contract.lawEvidence with
                    | Some(RuntimeLawVerifiedAgainstModel _) -> false
                    | _ -> true)

            let rejectedLaws (contract:PortableRuntimeContract<'Phase>) =
                contract.lawEvidence
                |> Map.toList
                |> List.choose (fun (law, evidence) ->
                    match evidence with
                    | RuntimeLawRejectedByModel _ -> Some law
                    | _ -> None)

            let missingOperations (contract:PortableRuntimeContract<'Phase>) =
                Set.difference allOperations contract.operations |> Set.toList

            let seal (contract:PortableRuntimeContract<PortableRuntimeDeclaredPhase>) : Result<PortableRuntimeContract<PortableRuntimeVerifiedPhase>,PortableRuntimeContractSealFailure> =
                let rejected = rejectedLaws contract
                let missing = missingLaws contract
                let missingOps = missingOperations contract
                if not (List.isEmpty rejected) then
                    Error(PortableRuntimeContractRejected rejected)
                elif not (List.isEmpty missing) || not (List.isEmpty missingOps) then
                    Error(PortableRuntimeContractPending(missing, missingOps))
                else
                    let evidenceText =
                        contract.lawEvidence
                        |> Map.toList
                        |> List.map (fun (law, evidence) ->
                            let evidenceRef =
                                match evidence with
                                | RuntimeLawVerifiedAgainstModel(traceRef, modelRef) ->
                                    ContentDigest.text traceRef + ":" + ContentDigest.text modelRef
                                | RuntimeLawDeclaredOnly -> "declared-only"
                                | RuntimeLawRejectedByModel(traceRef, counterexampleRef) ->
                                    "rejected:" + ContentDigest.text traceRef + ":" + ContentDigest.text counterexampleRef
                            runtimeLawStableText law + "=" + evidenceRef)
                        |> String.concat "|"
                    let verificationRef =
                        ContentDigest.ofText
                            "portable-runtime-contract-verification"
                            ((match contract.backend with
                              | RuntimeBackendHopac -> "hopac"
                              | RuntimeBackendRust -> "rust"
                              | RuntimeBackendBeam -> "beam"
                              | RuntimeBackendReference -> "reference")
                             + "|" + evidenceText)
                    Ok {
                        backend = contract.backend
                        operations = contract.operations
                        lawEvidence = contract.lawEvidence
                        mailboxBackpressure = contract.mailboxBackpressure
                        verificationRef = Some verificationRef
                    }

            let reference : PortableRuntimeContract<PortableRuntimeVerifiedPhase> =
                let declared =
                    (create RuntimeBackendReference (Set.toList allOperations) (Set.toList allLaws) [MailboxFailClosed], Set.toList allLaws)
                    ||> List.fold verifyReferenceLaw
                match seal declared with
                | Ok verified -> verified
                | Error failure -> invalidOp ("reference runtime contract failed to seal: " + portableRuntimeSealFailureStableText failure)

            let verifiedReceiptRef (contract:PortableRuntimeContract<PortableRuntimeVerifiedPhase>) =
                contract.verificationRef |> Option.defaultWith (fun () -> invalidOp "verified runtime contract lacks verification receipt")

            let isConformant (contract:PortableRuntimeContract<PortableRuntimeVerifiedPhase>) =
                Option.isSome contract.verificationRef

        type PortablePrimitive =
            | PortablePrimitiveFork
            | PortablePrimitiveJoin
            | PortablePrimitiveRaceWithNack
            | PortablePrimitiveOneShot
            | PortablePrimitiveRendezvous
            | PortablePrimitiveMailbox of MailboxBackpressure
            | PortablePrimitiveCancellation
            | PortablePrimitiveMonotonicTimer

        type BackendLowering = private {
            target : ExecutionTarget
            runtime : RuntimeBackend
            primitives : PortablePrimitive list
            contract : PortableRuntimeContract<PortableRuntimeVerifiedPhase>
            loweringRef : ContentDigest
        }

        module BackendLowering =
            let private targetStableText = function
                | ExecutionTargetFSharp -> "fsharp"
                | ExecutionTargetRust -> "rust"
                | ExecutionTargetGleam -> "gleam"
                | ExecutionTargetHvm -> "hvm"

            let private runtimeStableText = function
                | RuntimeBackendHopac -> "hopac"
                | RuntimeBackendRust -> "rust"
                | RuntimeBackendBeam -> "beam"
                | RuntimeBackendReference -> "reference"

            let private backpressureStableText = function
                | MailboxFailClosed -> "fail_closed"
                | MailboxEvictOldest -> "evict_oldest"
                | MailboxConflateLatest -> "conflate_latest"

            let private primitiveStableText = function
                | PortablePrimitiveFork -> "fork"
                | PortablePrimitiveJoin -> "join"
                | PortablePrimitiveRaceWithNack -> "race_with_nack"
                | PortablePrimitiveOneShot -> "one_shot"
                | PortablePrimitiveRendezvous -> "rendezvous"
                | PortablePrimitiveMailbox backpressure -> "mailbox:" + backpressureStableText backpressure
                | PortablePrimitiveCancellation -> "cancellation"
                | PortablePrimitiveMonotonicTimer -> "monotonic_timer"

            let create target runtime primitives (contract:PortableRuntimeContract<PortableRuntimeVerifiedPhase>) =
                let contractVerificationRef = PortableRuntimeContract.verifiedReceiptRef contract
                let identity =
                    primitives
                    |> List.map primitiveStableText
                    |> String.concat "|"
                { target = target
                  runtime = runtime
                  primitives = primitives
                  contract = contract
                  loweringRef =
                      ContentDigest.ofText
                          "backend-lowering"
                          (String.concat "|" [ targetStableText target; runtimeStableText runtime; identity; ContentDigest.text contractVerificationRef ]) }

        type PortableOneShotState =
            | PortableOneShotOpen
            | PortableOneShotFilled of payload:ContentDigest * receipt:ContentDigest
            | PortableOneShotCancelled of reason:ContentDigest

        type PortableChoiceState =
            | PortableChoiceOpen of branchCount:int
            | PortableChoiceCommitted of winner:int * cancelledLosers:Set<int>
            | PortableChoiceCancelled of reason:ContentDigest

        type PortableRuntimeModelState = private {
            monotonicNanoseconds : int64
            oneShots : Map<PortableResourceId, PortableOneShotState>
            choices : Map<PortableResourceId, PortableChoiceState>
        }

        type PortableRuntimeCommand =
            | RuntimeCreateOneShot of PortableResourceId
            | RuntimeFillOneShot of PortableResourceId * payload:ContentDigest
            | RuntimeCancelOneShot of PortableResourceId * reason:ContentDigest
            | RuntimeCreateChoice of PortableResourceId * branchCount:int
            | RuntimeCommitChoice of PortableResourceId * winner:int
            | RuntimeCancelChoice of PortableResourceId * reason:ContentDigest
            | RuntimeAdvanceMonotonicClock of nanoseconds:int64

        type PortableRuntimeRejection =
            | RuntimeResourceAlreadyExists of PortableResourceId
            | RuntimeResourceMissing of PortableResourceId
            | RuntimeOneShotAlreadyResolved of PortableResourceId
            | RuntimeChoiceAlreadyResolved of PortableResourceId
            | RuntimeChoiceWinnerOutOfRange of PortableResourceId * winner:int * branchCount:int
            | RuntimeClockRegression of current:int64 * requested:int64

        type PortableRuntimeTransitionReceipt = private {
            command : PortableRuntimeCommand
            accepted : bool
            rejection : PortableRuntimeRejection option
            receiptRef : ContentDigest
        }

        module PortableRuntimeModel =
            let empty = { monotonicNanoseconds = 0L; oneShots = Map.empty; choices = Map.empty }

            let resource label = PortableResourceId(ContentDigest.ofText "portable-resource" label)

            let private resourceStableText (PortableResourceId resourceRef) = ContentDigest.text resourceRef

            let commandStableText = function
                | RuntimeCreateOneShot resourceId -> "create_one_shot(" + resourceStableText resourceId + ")"
                | RuntimeFillOneShot(resourceId, payload) ->
                    "fill_one_shot(" + resourceStableText resourceId + "," + ContentDigest.text payload + ")"
                | RuntimeCancelOneShot(resourceId, reason) ->
                    "cancel_one_shot(" + resourceStableText resourceId + "," + ContentDigest.text reason + ")"
                | RuntimeCreateChoice(resourceId, branchCount) ->
                    sprintf "create_choice(%s,%d)" (resourceStableText resourceId) branchCount
                | RuntimeCommitChoice(resourceId, winner) ->
                    sprintf "commit_choice(%s,%d)" (resourceStableText resourceId) winner
                | RuntimeCancelChoice(resourceId, reason) ->
                    "cancel_choice(" + resourceStableText resourceId + "," + ContentDigest.text reason + ")"
                | RuntimeAdvanceMonotonicClock nanoseconds -> sprintf "advance_monotonic_clock(%d)" nanoseconds

            let rejectionStableText = function
                | None -> "accepted"
                | Some(RuntimeResourceAlreadyExists resourceId) -> "resource_already_exists(" + resourceStableText resourceId + ")"
                | Some(RuntimeResourceMissing resourceId) -> "resource_missing(" + resourceStableText resourceId + ")"
                | Some(RuntimeOneShotAlreadyResolved resourceId) -> "one_shot_already_resolved(" + resourceStableText resourceId + ")"
                | Some(RuntimeChoiceAlreadyResolved resourceId) -> "choice_already_resolved(" + resourceStableText resourceId + ")"
                | Some(RuntimeChoiceWinnerOutOfRange(resourceId, winner, branchCount)) ->
                    FastRuntimeFormat.format "choice_winner_out_of_range(%s,%d,%d)" [| box (resourceStableText resourceId); box winner; box branchCount |]
                | Some(RuntimeClockRegression(current, requested)) -> sprintf "clock_regression(%d,%d)" current requested

            let private receipt command accepted rejection =
                { command = command
                  accepted = accepted
                  rejection = rejection
                  receiptRef =
                    ContentDigest.ofText
                        "portable-runtime-transition"
                        (commandStableText command + "|accepted=" + string accepted + "|" + rejectionStableText rejection) }

            let apply command state =
                match command with
                | RuntimeCreateOneShot resourceId ->
                    if Map.containsKey resourceId state.oneShots then
                        receipt command false (Some(RuntimeResourceAlreadyExists resourceId)), state
                    else
                        receipt command true None,
                        { state with oneShots = Map.add resourceId PortableOneShotOpen state.oneShots }
                | RuntimeFillOneShot(resourceId, payload) ->
                    match Map.tryFind resourceId state.oneShots with
                    | None -> receipt command false (Some(RuntimeResourceMissing resourceId)), state
                    | Some PortableOneShotOpen ->
                        let fillReceipt = ContentDigest.ofText "portable-one-shot-fill" (ContentDigest.text payload)
                        receipt command true None,
                        { state with oneShots = Map.add resourceId (PortableOneShotFilled(payload, fillReceipt)) state.oneShots }
                    | Some _ -> receipt command false (Some(RuntimeOneShotAlreadyResolved resourceId)), state
                | RuntimeCancelOneShot(resourceId, reason) ->
                    match Map.tryFind resourceId state.oneShots with
                    | None -> receipt command false (Some(RuntimeResourceMissing resourceId)), state
                    | Some PortableOneShotOpen ->
                        receipt command true None,
                        { state with oneShots = Map.add resourceId (PortableOneShotCancelled reason) state.oneShots }
                    | Some _ -> receipt command false (Some(RuntimeOneShotAlreadyResolved resourceId)), state
                | RuntimeCreateChoice(resourceId, branchCount) ->
                    if branchCount <= 0 then
                        receipt command false (Some(RuntimeChoiceWinnerOutOfRange(resourceId, 0, branchCount))), state
                    elif Map.containsKey resourceId state.choices then
                        receipt command false (Some(RuntimeResourceAlreadyExists resourceId)), state
                    else
                        receipt command true None,
                        { state with choices = Map.add resourceId (PortableChoiceOpen branchCount) state.choices }
                | RuntimeCommitChoice(resourceId, winner) ->
                    match Map.tryFind resourceId state.choices with
                    | None -> receipt command false (Some(RuntimeResourceMissing resourceId)), state
                    | Some(PortableChoiceOpen branchCount) when winner >= 0 && winner < branchCount ->
                        let losers = [0 .. branchCount - 1] |> List.filter ((<>) winner) |> Set.ofList
                        receipt command true None,
                        { state with choices = Map.add resourceId (PortableChoiceCommitted(winner, losers)) state.choices }
                    | Some(PortableChoiceOpen branchCount) ->
                        receipt command false (Some(RuntimeChoiceWinnerOutOfRange(resourceId, winner, branchCount))), state
                    | Some _ -> receipt command false (Some(RuntimeChoiceAlreadyResolved resourceId)), state
                | RuntimeCancelChoice(resourceId, reason) ->
                    match Map.tryFind resourceId state.choices with
                    | None -> receipt command false (Some(RuntimeResourceMissing resourceId)), state
                    | Some(PortableChoiceOpen _) ->
                        receipt command true None,
                        { state with choices = Map.add resourceId (PortableChoiceCancelled reason) state.choices }
                    | Some _ -> receipt command false (Some(RuntimeChoiceAlreadyResolved resourceId)), state
                | RuntimeAdvanceMonotonicClock nanoseconds ->
                    if nanoseconds < state.monotonicNanoseconds then
                        receipt command false (Some(RuntimeClockRegression(state.monotonicNanoseconds, nanoseconds))), state
                    else
                        receipt command true None, { state with monotonicNanoseconds = nanoseconds }

            let private oneShotStateStableText = function
                | PortableOneShotOpen -> "open"
                | PortableOneShotFilled(payload, receipt) ->
                    "filled(" + ContentDigest.text payload + "," + ContentDigest.text receipt + ")"
                | PortableOneShotCancelled reason -> "cancelled(" + ContentDigest.text reason + ")"

            let private choiceStateStableText = function
                | PortableChoiceOpen branchCount -> sprintf "open(%d)" branchCount
                | PortableChoiceCommitted(winner, losers) ->
                    sprintf "committed(%d;%s)" winner (losers |> Set.toList |> List.map string |> String.concat ",")
                | PortableChoiceCancelled reason -> "cancelled(" + ContentDigest.text reason + ")"

            let stateDigest state =
                let oneShots =
                    state.oneShots
                    |> Map.toList
                    |> List.map (fun (resourceId, resourceState) -> resourceStableText resourceId + "=" + oneShotStateStableText resourceState)
                    |> String.concat "|"
                let choices =
                    state.choices
                    |> Map.toList
                    |> List.map (fun (resourceId, resourceState) -> resourceStableText resourceId + "=" + choiceStateStableText resourceState)
                    |> String.concat "|"
                ContentDigest.ofText
                    "portable-runtime-model-state"
                    (FastRuntimeFormat.format "clock=%d|one_shots=%s|choices=%s" [| box state.monotonicNanoseconds; box oneShots; box choices |])

            let receiptProjection receipt =
                FastRuntimeFormat.format "accepted=%b|rejection=%s|receipt=%s" [| box receipt.accepted; box (rejectionStableText receipt.rejection); box (ContentDigest.text receipt.receiptRef) |]

            let receiptAccepted receipt = receipt.accepted
            let receiptRef receipt = receipt.receiptRef
            let tryOneShot resourceId state = Map.tryFind resourceId state.oneShots
            let tryChoice resourceId state = Map.tryFind resourceId state.choices

        // Round : laws are discharged by executable traces. The adapter
        // harness is deliberately small and deterministic so each backend can
        // be compared against the same reference transition stream before the
        // real host-specific drivers are connected when host-specific drivers are connected.
        type PortableRuntimeTraceCommand =
            | TraceForkChild of ordinal:int64
            | TraceRetireChild of ordinal:int64
            | TraceCloseScope
            | TracePostMailbox of payload:ContentDigest
            | TraceRequestCancellation of reason:ContentDigest
            | TraceModelCommand of PortableRuntimeCommand

        type PortableRuntimeTraceRejection =
            | TraceScopeClosed
            | TraceChildAlreadyLive of ordinal:int64
            | TraceChildMissing of ordinal:int64
            | TraceChildrenStillLive of count:int
            | TraceMailboxFull of capacity:int
            | TraceCancellationConflict of existing:ContentDigest * requested:ContentDigest
            | TraceModelRejected of PortableRuntimeRejection

        type PortableRuntimeTraceStepReceipt = private {
            command : PortableRuntimeTraceCommand
            accepted : bool
            rejection : PortableRuntimeTraceRejection option
            semanticStateRef : ContentDigest
            stepRef : ContentDigest
        }

        type PortableRuntimeTraceProgram = private {
            law : PortableRuntimeLaw
            commands : PortableRuntimeTraceCommand list
            expectedAcceptance : bool list
        }

        type PortableRuntimeTraceState = private {
            model : PortableRuntimeModelState
            scopeClosed : bool
            liveChildren : Set<int64>
            mailboxCapacity : int
            mailbox : ContentDigest list
            cancellationReason : ContentDigest option
        }

        type PortableRuntimeHostDriverDisposition =
            | PortableReferenceInterpreter
            | PortableHopacMailboxActor
            | PortableRustExternalProcess
            | PortableBeamExternalProcess

        type PortableRuntimeDifferentialReceipt = private {
            backend : RuntimeBackend
            law : PortableRuntimeLaw
            driverDisposition : PortableRuntimeHostDriverDisposition
            hostReceiptPresent : bool
            traceRef : ContentDigest
            modelTraceRef : ContentDigest
            adapterTraceRef : ContentDigest
            comparedSteps : int
            mismatchSteps : int list
            expectedAcceptanceMatched : bool
            lawInvariantMatched : bool
            finalStateMatched : bool
            verified : bool
            counterexampleRef : ContentDigest option
        }

        type PortableRuntimeInteractionEvidenceSnapshot = {
            hostReceiptCount : int64
            verifiedReceiptCount : int64
            comparedTransitions : int64
            verifiedTransitions : int64
            latestTraceRef : ContentDigest option
        }

        module PortableRuntimeInteractionEvidenceBridge =
            let private registry =
                System.Collections.Concurrent.ConcurrentDictionary<ContentDigest, byte>()

            let private gate = obj()

            let mutable private snapshotValue =
                { hostReceiptCount = 0L
                  verifiedReceiptCount = 0L
                  comparedTransitions = 0L
                  verifiedTransitions = 0L
                  latestTraceRef = None }

            let note receipt =
                CompilerRuntimeActivation.requireInProcessEntered "portable_runtime_interaction_evidence"
                if registry.TryAdd(receipt.traceRef, 0uy) then
                    let compared = int64 receipt.comparedSteps
                    lock gate (fun () ->
                        let previous = snapshotValue
                        snapshotValue <-
                            { hostReceiptCount = previous.hostReceiptCount + (if receipt.hostReceiptPresent then 1L else 0L)
                              verifiedReceiptCount = previous.verifiedReceiptCount + (if receipt.verified then 1L else 0L)
                              comparedTransitions = previous.comparedTransitions + compared
                              verifiedTransitions = previous.verifiedTransitions + (if receipt.verified then compared else 0L)
                              latestTraceRef = Some receipt.traceRef })

            let snapshot () =
                CompilerRuntimeActivation.requireInProcessEntered "portable_runtime_interaction_evidence"
                lock gate (fun () -> snapshotValue)

        // Cross-backend conformance lives with each backend implementation.
        // The compiler keeps only its in-process Hopac evidence path.

        module PortableRuntimeTrace =
            let backendStableText = function
                | RuntimeBackendHopac -> "hopac"
                | RuntimeBackendRust -> "rust"
                | RuntimeBackendBeam -> "beam"
                | RuntimeBackendReference -> "reference"

            let traceCommandStableText = function
                | TraceForkChild ordinal -> sprintf "fork_child(%d)" ordinal
                | TraceRetireChild ordinal -> sprintf "retire_child(%d)" ordinal
                | TraceCloseScope -> "close_scope"
                | TracePostMailbox payload -> "post_mailbox(" + ContentDigest.text payload + ")"
                | TraceRequestCancellation reason -> "request_cancellation(" + ContentDigest.text reason + ")"
                | TraceModelCommand command ->
                    "model_command(" + PortableRuntimeModel.commandStableText command + ")"

            let traceRejectionStableText = function
                | None -> "accepted"
                | Some TraceScopeClosed -> "scope_closed"
                | Some(TraceChildAlreadyLive ordinal) -> sprintf "child_already_live(%d)" ordinal
                | Some(TraceChildMissing ordinal) -> sprintf "child_missing(%d)" ordinal
                | Some(TraceChildrenStillLive count) -> sprintf "children_still_live(%d)" count
                | Some(TraceMailboxFull capacity) -> sprintf "mailbox_full(%d)" capacity
                | Some(TraceCancellationConflict(existing, requested)) ->
                    "cancellation_conflict(" + ContentDigest.text existing + "," + ContentDigest.text requested + ")"
                | Some(TraceModelRejected rejection) ->
                    match rejection with
                    | RuntimeResourceAlreadyExists _ -> "model_resource_already_exists"
                    | RuntimeResourceMissing _ -> "model_resource_missing"
                    | RuntimeOneShotAlreadyResolved _ -> "model_one_shot_already_resolved"
                    | RuntimeChoiceAlreadyResolved _ -> "model_choice_already_resolved"
                    | RuntimeChoiceWinnerOutOfRange(_, winner, branchCount) -> sprintf "model_choice_out_of_range(%d,%d)" winner branchCount
                    | RuntimeClockRegression(current, requested) -> sprintf "model_clock_regression(%d,%d)" current requested

            let stateRef state =
                let children = state.liveChildren |> Set.toList |> List.map string |> String.concat ","
                let mailbox = state.mailbox |> List.map ContentDigest.text |> String.concat ","
                let cancellation = state.cancellationReason |> Option.map ContentDigest.text |> Option.defaultValue "none"
                ContentDigest.ofText
                    "portable-runtime-trace-state"
                    (FastRuntimeFormat.format "model=%s|scope_closed=%b|children=%s|mailbox_capacity=%d|mailbox=%s|cancellation=%s" [| box (ContentDigest.text (PortableRuntimeModel.stateDigest state.model)); box state.scopeClosed; box children; box state.mailboxCapacity; box mailbox; box cancellation |])

            let private emptyState =
                { model = PortableRuntimeModel.empty
                  scopeClosed = false
                  liveChildren = Set.empty
                  mailboxCapacity = 1
                  mailbox = []
                  cancellationReason = None }

            let private receipt command accepted rejection state =
                let semanticStateRef = stateRef state
                let stepRef =
                    ContentDigest.ofText
                        "portable-runtime-trace-step"
                        (traceCommandStableText command
                         + "|accepted=" + string accepted
                         + "|rejection=" + traceRejectionStableText rejection
                         + "|state=" + ContentDigest.text semanticStateRef)
                { command = command
                  accepted = accepted
                  rejection = rejection
                  semanticStateRef = semanticStateRef
                  stepRef = stepRef }

            let private apply command state =
                match command with
                | TraceForkChild ordinal ->
                    if state.scopeClosed then receipt command false (Some TraceScopeClosed) state, state
                    elif Set.contains ordinal state.liveChildren then receipt command false (Some(TraceChildAlreadyLive ordinal)) state, state
                    else
                        let next = { state with liveChildren = Set.add ordinal state.liveChildren }
                        receipt command true None next, next
                | TraceRetireChild ordinal ->
                    if not (Set.contains ordinal state.liveChildren) then receipt command false (Some(TraceChildMissing ordinal)) state, state
                    else
                        let next = { state with liveChildren = Set.remove ordinal state.liveChildren }
                        receipt command true None next, next
                | TraceCloseScope ->
                    if state.scopeClosed then receipt command true None state, state
                    elif not (Set.isEmpty state.liveChildren) then
                        receipt command false (Some(TraceChildrenStillLive state.liveChildren.Count)) state, state
                    else
                        let next = { state with scopeClosed = true }
                        receipt command true None next, next
                | TracePostMailbox payload ->
                    if state.mailbox.Length >= state.mailboxCapacity then
                        receipt command false (Some(TraceMailboxFull state.mailboxCapacity)) state, state
                    else
                        let next = { state with mailbox = state.mailbox @ [payload] }
                        receipt command true None next, next
                | TraceRequestCancellation reason ->
                    match state.cancellationReason with
                    | None ->
                        let next = { state with cancellationReason = Some reason }
                        receipt command true None next, next
                    | Some existing when existing = reason -> receipt command true None state, state
                    | Some existing -> receipt command false (Some(TraceCancellationConflict(existing, reason))) state, state
                | TraceModelCommand modelCommand ->
                    let modelReceipt, nextModel = PortableRuntimeModel.apply modelCommand state.model
                    let rejection =
                        match modelReceipt.rejection with
                        | None -> None
                        | Some reason -> Some(TraceModelRejected reason)
                    let next = { state with model = nextModel }
                    receipt command modelReceipt.accepted rejection next, next

            let private program law commands expectedAcceptance =
                { law = law; commands = commands; expectedAcceptance = expectedAcceptance }

            let programs () =
                let oneShot = PortableRuntimeModel.resource "differential-one-shot"
                let choice = PortableRuntimeModel.resource "differential-choice"
                let payload = ContentDigest.ofText "differential-payload" "visible"
                let reasonA = ContentDigest.ofText "differential-cancellation" "a"
                let reasonB = ContentDigest.ofText "differential-cancellation" "b"
                [ program RuntimeStructuredChildLifetime
                    [TraceForkChild 1L; TraceCloseScope; TraceRetireChild 1L; TraceCloseScope]
                    [true; false; true; true]
                  program RuntimeBoundedMailbox
                    [TracePostMailbox payload; TracePostMailbox payload]
                    [true; false]
                  program RuntimeCancellationIdempotent
                    [TraceRequestCancellation reasonA; TraceRequestCancellation reasonA; TraceRequestCancellation reasonB]
                    [true; true; false]
                  program RuntimeRaceLoserCleanup
                    [TraceModelCommand(RuntimeCreateChoice(choice, 3)); TraceModelCommand(RuntimeCommitChoice(choice, 1))]
                    [true; true]
                  program RuntimeMemoryVisibility
                    [TraceModelCommand(RuntimeCreateOneShot oneShot); TraceModelCommand(RuntimeFillOneShot(oneShot, payload))]
                    [true; true]
                  program RuntimeDeterministicFailure
                    [TraceModelCommand(RuntimeCreateOneShot oneShot)
                     TraceModelCommand(RuntimeFillOneShot(oneShot, payload))
                     TraceModelCommand(RuntimeFillOneShot(oneShot, payload))
                     TraceModelCommand(RuntimeFillOneShot(oneShot, payload))]
                    [true; true; false; false]
                  program RuntimeMonotonicTimer
                    [TraceModelCommand(RuntimeAdvanceMonotonicClock 10L); TraceModelCommand(RuntimeAdvanceMonotonicClock 9L)]
                    [true; false]
                  program RuntimeNoWorkAfterScopeClose
                    [TraceCloseScope; TraceForkChild 2L]
                    [true; false] ]

            type private PortableRuntimeHopacActorMessage =
                | PortableRuntimeHopacApply of PortableRuntimeTraceCommand * IVar<PortableRuntimeTraceStepReceipt>
                | PortableRuntimeHopacSnapshot of IVar<PortableRuntimeTraceState>

            let traceRefFor (backend:RuntimeBackend) (receipts:PortableRuntimeTraceStepReceipt list) =
                receipts
                |> List.map (fun receipt -> ContentDigest.text receipt.stepRef)
                |> String.concat "|"
                |> ContentDigest.ofText ("portable-runtime-trace-" + backendStableText backend)

            let executeReference (program:PortableRuntimeTraceProgram) =
                let finalState, receiptsRev =
                    ((emptyState, []), program.commands)
                    ||> List.fold (fun (state, receipts) command ->
                        let stepReceipt, next = apply command state
                        next, stepReceipt :: receipts)
                let receipts = List.rev receiptsRev
                receipts, finalState, traceRefFor RuntimeBackendReference receipts

            let rec private hopacActorLoop mailbox state =
                job {
                    let! message = Ch.take mailbox
                    match message with
                    | PortableRuntimeHopacApply(command, reply) ->
                        let stepReceipt, next = apply command state
                        do! IVar.fill reply stepReceipt
                        return! hopacActorLoop mailbox next
                    | PortableRuntimeHopacSnapshot reply ->
                        do! IVar.fill reply state
                        return! hopacActorLoop mailbox state
                }

            let private executeHopacActor (program:PortableRuntimeTraceProgram) =
                let mailbox = Ch<PortableRuntimeHopacActorMessage>()
                startHopacJob (hopacActorLoop mailbox emptyState)
                CompilerRuntimeKernel.runHostBoundary
                    "portable-runtime-differential-hopac"
                    (job {
                        let receipts = ResizeArray<PortableRuntimeTraceStepReceipt>()
                        for command in program.commands do
                            let reply = IVar<PortableRuntimeTraceStepReceipt>()
                            do! Ch.send mailbox (PortableRuntimeHopacApply(command, reply))
                            let! receipt = IVar.read reply
                            receipts.Add receipt
                        let reply = IVar<PortableRuntimeTraceState>()
                        do! Ch.send mailbox (PortableRuntimeHopacSnapshot reply)
                        let! finalState = IVar.read reply
                        let committedReceipts = receipts |> Seq.toList
                        return committedReceipts, finalState, traceRefFor RuntimeBackendHopac committedReceipts
                    })

            let private externalBackendNotOwnedByCompiler (backend:RuntimeBackend) (program:PortableRuntimeTraceProgram) =
                let boundary = backendStableText backend + "|" + PortableRuntimeContract.runtimeLawStableText program.law
                [],
                ContentDigest.ofText "portable-runtime-backend-owned-state" boundary,
                false,
                ContentDigest.ofText "portable-runtime-backend-owned-trace" boundary,
                false

            let compare (backend:RuntimeBackend) (program:PortableRuntimeTraceProgram) =
                let modelReceipts, modelState, modelTraceRef = executeReference program
                let driverDisposition, hostReceiptPresent, adapterReceipts, adapterState, adapterFinalStateRef, adapterInvariantOverride, adapterTraceRef =
                    match backend with
                    | RuntimeBackendReference ->
                        let receipts, state, traceRef = executeReference program
                        PortableReferenceInterpreter,
                        true,
                        receipts,
                        state,
                        stateRef state,
                        None,
                        traceRef
                    | RuntimeBackendHopac ->
                        let receipts, state, traceRef = executeHopacActor program
                        PortableHopacMailboxActor,
                        true,
                        receipts,
                        state,
                        stateRef state,
                        None,
                        traceRef
                    | RuntimeBackendRust ->
                        let receipts, finalStateRef, invariantMatched, traceRef, present = externalBackendNotOwnedByCompiler backend program
                        PortableRustExternalProcess,
                        present,
                        receipts,
                        emptyState,
                        finalStateRef,
                        Some invariantMatched,
                        traceRef
                    | RuntimeBackendBeam ->
                        let receipts, finalStateRef, invariantMatched, traceRef, present = externalBackendNotOwnedByCompiler backend program
                        PortableBeamExternalProcess,
                        present,
                        receipts,
                        emptyState,
                        finalStateRef,
                        Some invariantMatched,
                        traceRef
                let structuralInvariantMatched =
                    match program.law with
                       | RuntimeStructuredChildLifetime -> adapterState.scopeClosed && Set.isEmpty adapterState.liveChildren
                       | RuntimeBoundedMailbox -> adapterState.mailbox.Length = adapterState.mailboxCapacity
                       | RuntimeCancellationIdempotent -> Option.isSome adapterState.cancellationReason
                       | RuntimeRaceLoserCleanup ->
                           let choice = PortableRuntimeModel.resource "differential-choice"
                           match PortableRuntimeModel.tryChoice choice adapterState.model with
                           | Some(PortableChoiceCommitted(1, losers)) -> losers = Set.ofList [0; 2]
                           | _ -> false
                       | RuntimeMemoryVisibility ->
                           let oneShot = PortableRuntimeModel.resource "differential-one-shot"
                           match PortableRuntimeModel.tryOneShot oneShot adapterState.model with
                           | Some(PortableOneShotFilled(payload, _)) -> payload = ContentDigest.ofText "differential-payload" "visible"
                           | _ -> false
                       | RuntimeDeterministicFailure ->
                           match List.rev adapterReceipts with
                           | lastReceipt :: priorReceipt :: _ ->
                               not lastReceipt.accepted
                               && not priorReceipt.accepted
                               && lastReceipt.stepRef = priorReceipt.stepRef
                           | _ -> false
                       | RuntimeMonotonicTimer -> adapterState.model.monotonicNanoseconds = 10L
                       | RuntimeNoWorkAfterScopeClose -> adapterState.scopeClosed && Set.isEmpty adapterState.liveChildren
                let lawInvariantMatched =
                    hostReceiptPresent
                    && (adapterInvariantOverride |> Option.defaultValue structuralInvariantMatched)
                let comparedCount = min modelReceipts.Length adapterReceipts.Length
                let paired =
                    List.zip
                        (modelReceipts |> List.truncate comparedCount)
                        (adapterReceipts |> List.truncate comparedCount)
                let pairedMismatches =
                    paired
                    |> List.mapi (fun ordinal (modelReceipt, adapterReceipt) ->
                        let same =
                            modelReceipt.accepted = adapterReceipt.accepted
                            && traceRejectionStableText modelReceipt.rejection = traceRejectionStableText adapterReceipt.rejection
                            && modelReceipt.semanticStateRef = adapterReceipt.semanticStateRef
                        if same then None else Some ordinal)
                    |> List.choose id
                let lengthMismatches =
                    if modelReceipts.Length = adapterReceipts.Length then []
                    else [comparedCount .. max modelReceipts.Length adapterReceipts.Length - 1]
                let mismatches = pairedMismatches @ lengthMismatches
                let expectedAcceptanceMatched =
                    hostReceiptPresent
                    && (adapterReceipts |> List.map (fun receipt -> receipt.accepted) = program.expectedAcceptance)
                let finalStateMatched = hostReceiptPresent && stateRef modelState = adapterFinalStateRef
                let verified =
                    hostReceiptPresent
                    && List.isEmpty mismatches
                    && expectedAcceptanceMatched
                    && lawInvariantMatched
                    && finalStateMatched
                let counterexampleRef =
                    if verified then None
                    else
                        Some(ContentDigest.ofText
                            "portable-runtime-counterexample"
                            (FastRuntimeFormat.format "backend=%s|law=%s|host_receipt=%b|mismatches=%s|expected=%b|invariant=%b|state=%b" [| box (backendStableText backend); box (PortableRuntimeContract.runtimeLawStableText program.law); box hostReceiptPresent; box (mismatches |> List.map string |> String.concat ","); box expectedAcceptanceMatched; box lawInvariantMatched; box finalStateMatched |]))
                let differential =
                    { backend = backend
                      law = program.law
                      driverDisposition = driverDisposition
                      hostReceiptPresent = hostReceiptPresent
                      traceRef = ContentDigest.ofText "portable-runtime-differential-trace" (ContentDigest.text modelTraceRef + "|" + ContentDigest.text adapterTraceRef)
                      modelTraceRef = modelTraceRef
                      adapterTraceRef = adapterTraceRef
                      comparedSteps = paired.Length
                      mismatchSteps = mismatches
                      expectedAcceptanceMatched = expectedAcceptanceMatched
                      lawInvariantMatched = lawInvariantMatched
                      finalStateMatched = finalStateMatched
                      verified = verified
                      counterexampleRef = counterexampleRef }
                PortableRuntimeInteractionEvidenceBridge.note differential
                differential

            let verifyContract backend contract =
                programs ()
                |> List.fold (fun current program ->
                    let differential = compare backend program
                    if differential.verified then
                        PortableRuntimeContract.verifyLaw program.law differential.traceRef differential.modelTraceRef current
                    elif not differential.hostReceiptPresent then
                        current
                    else
                        PortableRuntimeContract.rejectLaw
                            program.law
                            differential.traceRef
                            (differential.counterexampleRef |> Option.defaultValue differential.adapterTraceRef)
                            current) contract

            let differentialReceipts backend = programs () |> List.map (compare backend)

        // External receipt loading was removed from the compiler. Backend drivers
        // validate themselves in their own processes; this module consumes only
        // the in-process Hopac model and never invokes Supervisor as a child.

        module PortableRuntimeEvidence =
            let reference = PortableRuntimeContract.reference

            let contract = function
                | RuntimeBackendReference -> Ok PortableRuntimeContract.reference
                | RuntimeBackendHopac ->
                    PortableRuntimeTrace.verifyContract RuntimeBackendHopac PortableRuntimeContract.hopacDeclared
                    |> PortableRuntimeContract.seal
                | RuntimeBackendRust ->
                    PortableRuntimeTrace.verifyContract RuntimeBackendRust PortableRuntimeContract.rustDeclared
                    |> PortableRuntimeContract.seal
                | RuntimeBackendBeam ->
                    PortableRuntimeTrace.verifyContract RuntimeBackendBeam PortableRuntimeContract.beamDeclared
                    |> PortableRuntimeContract.seal

            let allInProcessContracts () =
                // The compiler process owns only its Hopac adapter. Rust and BEAM
                // backends are validated by their own processes and never by Supervisor self-calls.
                [ RuntimeBackendHopac ]
                |> List.map (fun backend -> backend, contract backend)

        type PortableRuntimeInProcessEvidenceStatus =
            | PortableRuntimeInProcessEvidenceVerified of receiptRef:ContentDigest * verifiedLawCount:int
            | PortableRuntimeInProcessEvidencePending of receiptRef:ContentDigest * missing:(RuntimeBackend * PortableRuntimeLaw list) list
            | PortableRuntimeInProcessEvidenceRejected of receiptRef:ContentDigest * rejected:(RuntimeBackend * PortableRuntimeLaw list) list
            | PortableRuntimeInProcessEvidenceFaulted of receiptRef:ContentDigest * faultKind:string

        module PortableRuntimeInProcessEvidenceGate =
            let backendStableText = function
                | RuntimeBackendReference -> "reference"
                | RuntimeBackendHopac -> "hopac"
                | RuntimeBackendRust -> "rust"
                | RuntimeBackendBeam -> "beam"

            let private lawListText laws =
                laws
                |> List.map PortableRuntimeContract.runtimeLawStableText
                |> String.concat ","

            let private evidenceText evidence =
                evidence
                |> List.map (fun (backend, laws) -> backendStableText backend + "[" + lawListText laws + "]")
                |> String.concat "|"

            let private computeSnapshot () =
                let contracts = PortableRuntimeEvidence.allInProcessContracts ()
                let rejected =
                    contracts
                    |> List.choose (fun (backend, result) ->
                        match result with
                        | Error(PortableRuntimeContractRejected laws) when not (List.isEmpty laws) -> Some(backend, laws)
                        | _ -> None)
                let pending =
                    contracts
                    |> List.choose (fun (backend, result) ->
                        match result with
                        | Error(PortableRuntimeContractPending(missingLaws, _)) when not (List.isEmpty missingLaws) ->
                            Some(backend, missingLaws)
                        | _ -> None)
                let operationGapRefs =
                    contracts
                    |> List.choose (fun (backend, result) ->
                        match result with
                        | Error(PortableRuntimeContractPending(_, missingOperations)) when not (List.isEmpty missingOperations) ->
                            Some(ContentDigest.ofText
                                "portable-runtime-operation-gap"
                                (backendStableText backend + "|count=" + string missingOperations.Length))
                        | _ -> None)
                if not (List.isEmpty rejected) then
                    let receiptRef =
                        ContentDigest.ofText
                            "portable-runtime-in-process-evidence-rejected"
                            (evidenceText rejected)
                    PortableRuntimeInProcessEvidenceRejected(receiptRef, rejected)
                elif not (List.isEmpty pending) || not (List.isEmpty operationGapRefs) then
                    let receiptRef =
                        ContentDigest.ofText
                            "portable-runtime-in-process-evidence-pending"
                            (evidenceText pending
                             + "|operation_gaps="
                             + (operationGapRefs |> List.map ContentDigest.text |> String.concat ","))
                    PortableRuntimeInProcessEvidencePending(receiptRef, pending)
                else
                    let verifiedContracts =
                        contracts
                        |> List.choose (fun (backend, result) ->
                            match result with
                            | Ok contract -> Some(backend, contract)
                            | Error _ -> None)
                    let verifiedLawCount = verifiedContracts.Length * 8
                    let receiptRef =
                        verifiedContracts
                        |> List.map (fun (backend, contract) ->
                            backendStableText backend
                            + ":verification="
                            + ContentDigest.text (PortableRuntimeContract.verifiedReceiptRef contract))
                        |> String.concat "|"
                        |> ContentDigest.ofText "portable-runtime-in-process-evidence-verified"
                    PortableRuntimeInProcessEvidenceVerified(receiptRef, verifiedLawCount)

            type private PortableRuntimeEvidenceComputation =
                | PortableRuntimeEvidenceCold
                | PortableRuntimeEvidenceRunning of startedAtMs:int64 * computation:System.Threading.Tasks.Task<PortableRuntimeInProcessEvidenceStatus>
                | PortableRuntimeEvidenceReady of completedAtMs:int64 * snapshot:PortableRuntimeInProcessEvidenceStatus

            let private computationGate = obj()
            let mutable private computation = PortableRuntimeEvidenceCold

            let private pendingSnapshot () =
                let missing =
                    [ RuntimeBackendHopac,
                      PortableRuntimeContract.missingLaws PortableRuntimeContract.hopacDeclared ]
                let receiptRef =
                    ContentDigest.ofText
                        "portable-runtime-in-process-evidence-computing"
                        (evidenceText missing)
                PortableRuntimeInProcessEvidencePending(receiptRef, missing)

            let private faultedSnapshot (ex:exn) =
                let faultKind = ex.GetType().FullName
                let receiptRef =
                    ContentDigest.ofText
                        "portable-runtime-in-process-evidence-faulted"
                        faultKind
                PortableRuntimeInProcessEvidenceFaulted(receiptRef, faultKind)

            let private startComputation () =
                // Hopac.run belongs to the differential adapter, but never to a
                // Hopac worker. The evidence computation therefore owns a CLR
                // task boundary and the compiler only polls its typed snapshot.
                System.Threading.Tasks.Task.Run(fun () ->
                    try computeSnapshot ()
                    with ex -> faultedSnapshot ex)

            let refresh () =
                CompilerRuntimeActivation.requireInProcessEntered "portable_runtime_in_process_evidence"
                lock computationGate (fun () ->
                    match computation with
                    | PortableRuntimeEvidenceCold ->
                        let task = startComputation ()
                        computation <- PortableRuntimeEvidenceRunning(Environment.TickCount64, task)
                        pendingSnapshot ()
                    | PortableRuntimeEvidenceRunning(_, task) when task.IsCompleted ->
                        let snapshot =
                            try task.Result
                            with ex -> faultedSnapshot ex
                        computation <- PortableRuntimeEvidenceReady(Environment.TickCount64, snapshot)
                        snapshot
                    | PortableRuntimeEvidenceRunning _ ->
                        pendingSnapshot ()
                    | PortableRuntimeEvidenceReady(_, snapshot) -> snapshot)

            let isVerified () =
                match refresh () with
                | PortableRuntimeInProcessEvidenceVerified _ -> true
                | PortableRuntimeInProcessEvidencePending _
                | PortableRuntimeInProcessEvidenceRejected _
                | PortableRuntimeInProcessEvidenceFaulted _ -> false

            let receiptRef () =
                match refresh () with
                | PortableRuntimeInProcessEvidenceVerified(receiptRef, _)
                | PortableRuntimeInProcessEvidencePending(receiptRef, _)
                | PortableRuntimeInProcessEvidenceRejected(receiptRef, _)
                | PortableRuntimeInProcessEvidenceFaulted(receiptRef, _) -> receiptRef

            let stableText () =
                match refresh () with
                | PortableRuntimeInProcessEvidenceVerified(receiptRef, count) ->
                    sprintf "Verified(receipt=%s|laws=%d)" (ContentDigest.text receiptRef) count
                | PortableRuntimeInProcessEvidencePending(receiptRef, missing) ->
                    "Pending(receipt=" + ContentDigest.text receiptRef + "|missing=" + evidenceText missing + ")"
                | PortableRuntimeInProcessEvidenceRejected(receiptRef, rejected) ->
                    "Rejected(receipt=" + ContentDigest.text receiptRef + "|rejected=" + evidenceText rejected + ")"
                | PortableRuntimeInProcessEvidenceFaulted(receiptRef, faultKind) ->
                    "Faulted(receipt=" + ContentDigest.text receiptRef + "|kind=" + faultKind + ")"

        module PortableRuntimeOperationalAdapterAuthority =
            let private gate = obj()
            let mutable private installed : PortableRuntimeAdapterReceipt option = None

            let installFSharpHopac () =
                lock gate (fun () ->
                    let contractRef = PortableRuntimeInProcessEvidenceGate.receiptRef ()
                    match installed with
                    | Some receipt when PortableRuntimeAdapterReceiptOps.contractRef receipt = contractRef ->
                        receipt
                    | _ ->
                        let receipt = CompilerRuntimeKernel.receipt contractRef
                        installed <- Some receipt
                        receipt)

            let current () = lock gate (fun () -> installed)


        // Destructive migration: measured per-phase progress.  Static
        // AST shape is evidence about source structure, never a semantic-cost
        // denominator unless an explicit calibration supplies a semantic budget.
        type CompilerWorkPhase =
            | WorkDiscover
            | WorkParse
            | WorkResolve
            | WorkElaborate
            | WorkDefEq
            | WorkSpecialize
            | WorkLower
            | WorkCodegen
            | WorkArtifact
            | WorkTerminalize

        let compilerWorkPhaseStableText = function
            | WorkDiscover -> "discover"
            | WorkParse -> "parse"
            | WorkResolve -> "resolve"
            | WorkElaborate -> "elaborate"
            | WorkDefEq -> "defeq"
            | WorkSpecialize -> "specialize"
            | WorkLower -> "lower"
            | WorkCodegen -> "codegen"
            | WorkArtifact -> "artifact"
            | WorkTerminalize -> "terminalize"

        type SemanticPhaseRate = private {
            phase : CompilerWorkPhase
            retired : SemanticCost
            elapsed : WallTime
            rateRef : ContentDigest
        }

        module SemanticPhaseRate =
            let create phase retired elapsed =
                if Measured.value elapsed <= 0L then invalidArg "elapsed" "phase rate requires positive wall time"
                let rateRef =
                    ContentDigest.ofText
                        "semantic-phase-rate"
                        (compilerWorkPhaseStableText phase
                         + "|retired=" + string (Measured.value retired)
                         + "|wall_ms=" + string (Measured.value elapsed))
                { phase = phase; retired = retired; elapsed = elapsed; rateRef = rateRef }

            let etaFor phase remaining rate =
                if phase <> rate.phase then
                    Error("phase_rate_mismatch|expected=" + compilerWorkPhaseStableText phase + "|actual=" + compilerWorkPhaseStableText rate.phase)
                elif Measured.value rate.retired <= 0L then
                    Error "phase_rate_has_no_retirement"
                else
                    let remainingValue = Measured.value remaining
                    let elapsedValue = Measured.value rate.elapsed
                    let retiredValue = Measured.value rate.retired
                    if remainingValue > 0L && elapsedValue > Int64.MaxValue / remainingValue then
                        Error "phase_eta_overflow"
                    else
                        let etaMs = (remainingValue * elapsedValue) / retiredValue
                        Ok(Measured.create<WallTimeUnit> "eta" etaMs)

            let reference rate = rate.rateRef

        type PhaseDurationDistribution = private {
            sampleCount : int64
            p50 : WallTime
            p90 : WallTime
            p99 : WallTime
            maximum : WallTime
            slowSampleCount : int64
            distributionRef : ContentDigest
        }

        type PhaseStaticSeed = private {
            astCost : AstCost
            calibratedSemanticBudget : SemanticCost option
            sourceRef : ContentDigest
            closedAtParse : bool
        }

        type PhaseWork = private {
            retiredCost : SemanticCost
            discoveredCost : SemanticCost
            blockedCost : SemanticCost
            undiscoveredP50Cost : SemanticCost
            undiscoveredP90Cost : SemanticCost
            materialRate : SemanticPhaseRate option
            staticSeed : PhaseStaticSeed option
            durationSamples : WallTime list
            slowThreshold : WallTime
            revision : int64
        }

        type PhaseProgressBook = private {
            phases : Map<CompilerWorkPhase, PhaseWork>
            discoveryClosed : Set<CompilerWorkPhase>
        }

        type PhaseProgressProjection = {
            phase : CompilerWorkPhase
            retiredCost : SemanticCost
            discoveredCost : SemanticCost
            seedAstCost : AstCost option
            semanticBudgetExceededBy : SemanticCost
            progress : ExactCostProjection<SemanticCostUnit>
            etaP50 : WallTime option
            etaP90 : WallTime option
            staticSeedRef : ContentDigest option
            rateRef : ContentDigest option
            durationDistributionRef : ContentDigest option
            durationSampleCount : int64
            criticalPathRemainingCost : SemanticCost
        }

        module PhaseProgressBook =
            let empty = { phases = Map.empty; discoveryClosed = Set.empty }

            let private initialWork () =
                { retiredCost = Measured.zero
                  discoveredCost = Measured.zero
                  blockedCost = Measured.zero
                  undiscoveredP50Cost = Measured.zero
                  undiscoveredP90Cost = Measured.zero
                  materialRate = None
                  staticSeed = None
                  durationSamples = []
                  slowThreshold = Measured.create<WallTimeUnit> "slowThreshold" 3000L
                  revision = 0L }

            let setPhase phase retired discovered blocked reserveP50 reserveP90 rate book =
                if Measured.value retired > Measured.value discovered + Measured.value blocked then
                    invalidArg "retired" "semantic retirement cannot exceed semantic admission"
                if Measured.value reserveP90 < Measured.value reserveP50 then
                    invalidArg "reserveP90" "semantic p90 reserve must be at least p50"
                let current = Map.tryFind phase book.phases |> Option.defaultWith initialWork
                if Measured.value retired < Measured.value current.retiredCost
                   || Measured.value discovered < Measured.value current.discoveredCost then
                    invalidArg "phase-work" "semantic retirement and discovery are monotone within a phase"
                let next =
                    { current with
                        retiredCost = retired
                        discoveredCost = discovered
                        blockedCost = blocked
                        undiscoveredP50Cost = reserveP50
                        undiscoveredP90Cost = reserveP90
                        materialRate = rate
                        revision = current.revision + 1L }
                { book with phases = Map.add phase next book.phases }

            let closeDiscovery phase book =
                { book with discoveryClosed = Set.add phase book.discoveryClosed }

            let seedStatic phase astCost calibratedSemanticBudget source closedAtParse book =
                let sourceRef = ContentDigest.ofText "phase-static-seed" source
                let seed =
                    { astCost = astCost
                      calibratedSemanticBudget = calibratedSemanticBudget
                      sourceRef = sourceRef
                      closedAtParse = closedAtParse }
                let current = Map.tryFind phase book.phases |> Option.defaultWith initialWork
                let next = { current with staticSeed = Some seed; revision = current.revision + 1L }
                let nextBook = { book with phases = Map.add phase next book.phases }
                if closedAtParse then closeDiscovery phase nextBook else nextBook

            let observeDuration phase duration book =
                match Map.tryFind phase book.phases with
                | None -> book
                | Some current ->
                    let samples = duration :: current.durationSamples |> List.truncate 4096
                    { book with
                        phases = Map.add phase { current with durationSamples = samples; revision = current.revision + 1L } book.phases }

            let private percentile percentileValue samples =
                match samples |> List.sortBy Measured.value with
                | [] -> Measured.zero
                | sorted ->
                    let ordinal =
                        System.Math.Ceiling((float percentileValue / 100.0) * float sorted.Length)
                        |> int
                        |> max 1
                        |> min sorted.Length
                    sorted.[ordinal - 1]

            let private durationDistribution work =
                let samples = work.durationSamples
                let p50 = percentile 50 samples
                let p90 = percentile 90 samples
                let p99 = percentile 99 samples
                let maximum = samples |> List.fold Measured.maxValue Measured.zero
                let slowCount =
                    samples
                    |> List.filter (fun value -> Measured.value value >= Measured.value work.slowThreshold)
                    |> List.length
                    |> int64
                let distributionRef =
                    ContentDigest.ofText
                        "phase-duration-distribution"
                        (FastRuntimeFormat.format "samples=%d|p50=%d|p90=%d|p99=%d|max=%d|slow=%d" [| box samples.Length; box (Measured.value p50); box (Measured.value p90); box (Measured.value p99); box (Measured.value maximum); box slowCount |])
                { sampleCount = int64 samples.Length
                  p50 = p50
                  p90 = p90
                  p99 = p99
                  maximum = maximum
                  slowSampleCount = slowCount
                  distributionRef = distributionRef }

            let private estimatedWallTime remaining fast slow expectedSlow =
                let remainingValue = Measured.value remaining
                let expectedSlowValue = min remainingValue expectedSlow
                let expectedFastValue = max 0L (remainingValue - expectedSlowValue)
                let totalMs =
                    expectedFastValue * Measured.value fast
                    + expectedSlowValue * Measured.value slow
                Measured.create<WallTimeUnit> "estimatedWallTime" totalMs

            let project phase book =
                match Map.tryFind phase book.phases with
                | None -> None
                | Some work ->
                    let closed = Set.contains phase book.discoveryClosed
                    let semanticBudget = work.staticSeed |> Option.bind (fun seed -> seed.calibratedSemanticBudget)
                    let budgetExceededBy =
                        semanticBudget
                        |> Option.map (fun budget -> Measured.subtractFloor work.retiredCost budget)
                        |> Option.defaultValue Measured.zero
                    let denominator =
                        match semanticBudget, closed with
                        | Some budget, _ -> ProgressDenominatorClosed, budget
                        | None, true -> ProgressDenominatorClosed, Measured.add work.discoveredCost work.blockedCost
                        | None, false ->
                            ProgressDenominatorOpen(work.undiscoveredP50Cost, work.undiscoveredP90Cost),
                            Measured.add work.discoveredCost work.blockedCost
                    let denominatorState, admitted = denominator
                    let ledgerDiscoveredCost =
                        match semanticBudget with
                        | Some budget ->
                            Measured.maxValue
                                work.retiredCost
                                (Measured.subtractFloor budget work.blockedCost)
                        | None -> work.discoveredCost
                    let ledger = ExactCostLedger.create work.retiredCost ledgerDiscoveredCost work.blockedCost denominatorState
                    let projected = ExactCostLedger.project ledger
                    let progress =
                        match semanticBudget with
                        | Some budget when Measured.value work.retiredCost > Measured.value budget ->
                            { projected with exact = false }
                        | _ -> { projected with exact = projected.exact && closed }
                    let remaining = Measured.subtractFloor admitted work.retiredCost
                    let distribution = durationDistribution work
                    let slowFraction =
                        if distribution.sampleCount = 0L then 0.0
                        else float distribution.slowSampleCount / float distribution.sampleCount
                    let expectedSlow = System.Math.Ceiling(float (Measured.value remaining) * slowFraction) |> int64
                    let distributionP50 =
                        if distribution.sampleCount = 0L then None
                        else Some(estimatedWallTime remaining distribution.p50 (Measured.maxValue distribution.p99 distribution.p50) expectedSlow)
                    let distributionP90 =
                        if distribution.sampleCount = 0L then None
                        else Some(estimatedWallTime remaining distribution.p90 (Measured.maxValue distribution.maximum distribution.p99) expectedSlow)
                    let rateEta =
                        work.materialRate
                        |> Option.bind (fun rate -> SemanticPhaseRate.etaFor phase remaining rate |> Result.toOption)
                    Some {
                        phase = phase
                        retiredCost = work.retiredCost
                        discoveredCost = work.discoveredCost
                        seedAstCost = work.staticSeed |> Option.map (fun seed -> seed.astCost)
                        semanticBudgetExceededBy = budgetExceededBy
                        progress = progress
                        etaP50 = distributionP50 |> Option.orElse rateEta
                        etaP90 = distributionP90 |> Option.orElse rateEta
                        staticSeedRef = work.staticSeed |> Option.map (fun seed -> seed.sourceRef)
                        rateRef = work.materialRate |> Option.map SemanticPhaseRate.reference
                        durationDistributionRef = if distribution.sampleCount = 0L then None else Some distribution.distributionRef
                        durationSampleCount = distribution.sampleCount
                        criticalPathRemainingCost = remaining
                    }

            let projectAll book =
                book.phases
                |> Map.toList
                |> List.choose (fun (phase, _) -> project phase book)

            let projectAggregate (book:PhaseProgressBook) : ExactCostProjection<SemanticCostUnit> option =
                match projectAll book with
                | [] -> None
                | projections ->
                    let sum selector = projections |> List.map selector |> List.fold Measured.add Measured.zero
                    let completedCost = sum (fun projection -> projection.progress.completedCost)
                    let totalLow = sum (fun projection -> projection.progress.totalLow)
                    let totalMid = sum (fun projection -> projection.progress.totalMid)
                    let totalHigh = sum (fun projection -> projection.progress.totalHigh)
                    let basisPoints total =
                        let totalValue = Measured.value total
                        if totalValue <= 0L then BasisPoints.zero
                        else BasisPoints.create (min 10000L ((Measured.value completedCost * 10000L) / totalValue))
                    Some {
                        completedCost = completedCost
                        totalLow = totalLow
                        totalMid = totalMid
                        totalHigh = totalHigh
                        lowBp = basisPoints totalLow
                        midBp = basisPoints totalMid
                        highBp = basisPoints totalHigh
                        exact = projections |> List.forall (fun projection -> projection.progress.exact)
                        revision = projections |> List.sumBy (fun projection -> projection.progress.revision)
                    }

        // Compact CIC arena. Recursive semantic structure lives in nodes while
        // hot paths carry generation-checked IDs and persistent environment IDs.
        [<Struct>]
        type KernelTermId = private {
            generation : int
            slot : int
        }

        type KernelOpenPhase = class end
        type KernelClosedPhase = class end
        type KernelMetaFreePhase = class end

        [<Struct>]
        type KernelTerm<'Phase> = private | KernelTerm of KernelTermId

        module KernelTerm =
            let internal ofId term = KernelTerm term
            let id (KernelTerm term) = term
            let generation term = (id term).generation
            let slot term = (id term).slot

        [<Struct>]
        type KernelEnvironmentId = private {
            generation : int
            slot : int
        }

        type KernelUniverse =
            | KernelUniverseProp
            | KernelUniverseZero
            | KernelUniverseSucc of KernelUniverse
            | KernelUniverseMax of KernelUniverse * KernelUniverse
            | KernelUniverseIMax of KernelUniverse * KernelUniverse
            | KernelUniverseParameter of TypeNameId
            | KernelUniverseMeta of int

        type KernelBinderInfo =
            | KernelBinderExplicit
            | KernelBinderImplicit
            | KernelBinderStrictImplicit
            | KernelBinderInstanceImplicit

        type KernelLiteral =
            | KernelNatLiteral of bigint
            | KernelStringLiteral of string

        let rec private kernelUniverseStableText = function
            | KernelUniverseProp -> "prop"
            | KernelUniverseZero -> "zero"
            | KernelUniverseSucc inner -> "succ(" + kernelUniverseStableText inner + ")"
            | KernelUniverseMax(left, right) ->
                "max(" + kernelUniverseStableText left + "," + kernelUniverseStableText right + ")"
            | KernelUniverseIMax(left, right) ->
                "imax(" + kernelUniverseStableText left + "," + kernelUniverseStableText right + ")"
            | KernelUniverseParameter name -> "parameter(" + TypeNameIdOps.text name + ")"
            | KernelUniverseMeta meta -> sprintf "meta(%d)" meta

        let private kernelBinderInfoStableText = function
            | KernelBinderExplicit -> "explicit"
            | KernelBinderImplicit -> "implicit"
            | KernelBinderStrictImplicit -> "strict_implicit"
            | KernelBinderInstanceImplicit -> "instance_implicit"

        let private kernelLiteralStableText = function
            | KernelNatLiteral value -> "nat(" + string value + ")"
            | KernelStringLiteral value -> "string(" + ContentDigest.text (ContentDigest.ofText "kernel-string-literal" value) + ")"

        type KernelNode =
            | KernelBound of index:int
            | KernelFree of StableBindingId
            | KernelMeta of metaId:int
            | KernelSort of KernelUniverse
            | KernelConstant of StableBindingId * KernelUniverse list
            | KernelApplication of functionTerm:KernelTermId * argument:KernelTermId
            | KernelLambda of binder:KernelBinderInfo * domain:KernelTermId * body:KernelTermId
            | KernelForall of binder:KernelBinderInfo * domain:KernelTermId * body:KernelTermId
            | KernelLet of typeTerm:KernelTermId * value:KernelTermId * body:KernelTermId
            | KernelLiteral of KernelLiteral
            | KernelConstructorValue of constructor:StableBindingId * fields:KernelTermId list
            | KernelRecursorApplication of recursor:StableBindingId * motive:KernelTermId * major:KernelTermId * minors:KernelTermId list
            | KernelProjection of structureTerm:KernelTermId * fieldOrdinal:int
            | KernelQuotientValue of typeTerm:KernelTermId * relationTerm:KernelTermId * representative:KernelTermId
            | KernelQuotientLiftApplication of functionTerm:KernelTermId * respectsRelationProof:KernelTermId * quotientTerm:KernelTermId
            | KernelQuotientInductionApplication of motive:KernelTermId * representativeProof:KernelTermId * quotientTerm:KernelTermId

        type KernelPolarity =
            | KernelPositive
            | KernelNegative

        type KernelPositivityPathSegment =
            | KernelPositivityForallDomain
            | KernelPositivityForallBody
            | KernelPositivityApplicationFunction
            | KernelPositivityApplicationArgument
            | KernelPositivityConstructorField of ordinal:int
            | KernelPositivityRecursorField of label:string * ordinal:int
            | KernelPositivityProjectionField of ordinal:int
            | KernelPositivityQuotientComponent of label:string

        type KernelPositivityOccurrence = private {
            target : StableBindingId
            polarity : KernelPolarity
            path : KernelPositivityPathSegment list
            occurrenceRef : ContentDigest
        }

        type KernelPositivityCertificate = private {
            inductive : StableBindingId
            constructorTypes : KernelTermId list
            positiveOccurrences : KernelPositivityOccurrence list
            certificateRef : ContentDigest
            closed : bool
        }

        type KernelPositivityFailure =
            | KernelNegativeOccurrence of KernelPositivityOccurrence
            | KernelUnknownOccurrenceTerm of KernelTermId
            | KernelOccurrenceUnderUnknownApplication of KernelPositivityOccurrence
            | KernelPositivityForeignGeneration of KernelTermId

        type KernelDeclarationKind =
            | KernelAxiom
            | KernelDefinition
            | KernelOpaqueDefinition
            | KernelTheorem
            | KernelInductive
            | KernelConstructor
            | KernelRecursor
            | KernelQuotientPrimitive

        type KernelDeclaration = private {
            declarationId : StableBindingId
            kind : KernelDeclarationKind
            typeTerm : KernelTerm<KernelClosedPhase>
            valueTerm : KernelTerm<KernelClosedPhase> option
            universeParameters : string list
            dependencies : Set<StableBindingId>
            positivityCertificate : KernelPositivityCertificate option
        }

        type KernelEnvironmentFrame = private {
            parent : KernelEnvironmentId option
            value : KernelClosure option
            depth : int
        }

        and KernelClosure = private {
            term : KernelTermId
            environment : KernelEnvironmentId
        }

        type KernelEnvironment = private {
            generation : int
            nextSlot : int
            frames : Map<int, KernelEnvironmentFrame>
        }

        module KernelEnvironment =
            let empty (generation:int) : KernelEnvironment =
                { generation = generation
                  nextSlot = 1
                  frames = Map.ofList [0, { parent = None; value = None; depth = 0 }] }

            let root (environment:KernelEnvironment) : KernelEnvironmentId = { generation = environment.generation; slot = 0 }

            let extend (value:KernelClosure) (parent:KernelEnvironmentId) (environment:KernelEnvironment) : KernelEnvironmentId * KernelEnvironment =
                if parent.generation <> environment.generation then invalidArg "parent" "foreign kernel environment generation"
                let slot = environment.nextSlot
                let parentDepth = environment.frames |> Map.tryFind parent.slot |> Option.map (fun frame -> frame.depth) |> Option.defaultValue 0
                let frame = { parent = Some parent; value = Some value; depth = parentDepth + 1 }
                { generation = environment.generation; slot = slot },
                { environment with nextSlot = slot + 1; frames = Map.add slot frame environment.frames }

            let tryLookup (index:int) (environmentId:KernelEnvironmentId) (environment:KernelEnvironment) : KernelClosure option =
                if index < 0 || environmentId.generation <> environment.generation then None
                else
                    let mutable cursor = Some environmentId
                    let mutable remaining = index
                    let mutable found = None
                    while Option.isNone found && Option.isSome cursor do
                        match cursor with
                        | None -> ()
                        | Some current ->
                            match Map.tryFind current.slot environment.frames with
                            | None -> cursor <- None
                            | Some frame ->
                                if remaining = 0 then
                                    found <- frame.value
                                    cursor <- None
                                else
                                    remaining <- remaining - 1
                                    cursor <- frame.parent
                    found

        // Five-round migration round : metavariables are generation-scoped
        // resources with persistent assignments, explicit occurs checks and
        // wakeable DefEq obligations. A meta is never "just an int" once it
        // participates in kernel authority.
        [<Struct>]
        type KernelMetaDependencyPathRef = private KernelMetaDependencyPathRef of ContentDigest

        let private kernelMetaDependencyPathRefOfText text =
            KernelMetaDependencyPathRef (ContentDigest.ofText "kernel-meta-dependency-path" text)

        let private kernelMetaDependencyPathRefText (KernelMetaDependencyPathRef pathRef) =
            ContentDigest.text pathRef

        type KernelMetaBlockedObligation = private {
            obligationRef : ContentDigest
            interactionPairRef : ContentDigest
            resumptionEdgeRef : ContentDigest
            path : KernelMetaDependencyPathRef
            metaIds : Set<int>
            registeredAtRevision : int64
        }

        type KernelMetaAssignment = private {
            metaId : int
            value : KernelClosure
            dependencyMetas : Set<int>
            assignmentRef : ContentDigest
            assignedAtRevision : int64
        }

        [<Struct>]
        type KernelMetaWakeEdgeId = private KernelMetaWakeEdgeId of ContentDigest

        type KernelMetaContext = private {
            generation : int
            revision : int64
            assignments : Map<int, KernelMetaAssignment>
            blockedByMeta : Map<int, Map<KernelMetaWakeEdgeId, KernelMetaBlockedObligation>>
            revisionDigest : ContentDigest
        }

        type KernelMetaAssignmentError =
            | KernelMetaForeignGeneration of metaId:int * expectedGeneration:int * actualGeneration:int
            | KernelMetaOccursCheckFailed of metaId:int * dependencyPath:Set<int>
            | KernelMetaAssignmentConflict of metaId:int * existingRef:ContentDigest * proposedRef:ContentDigest
            | KernelMetaAssignmentUnknownTerm of metaId:int * term:KernelTermId

        type KernelMetaAssignmentReceipt = private {
            metaId : int
            assignmentRef : ContentDigest
            priorRevision : int64
            newRevision : int64
            dependencyMetas : Set<int>
            wokenObligations : KernelMetaBlockedObligation list
            contextRef : ContentDigest
        }

        type KernelMetaTransaction = private {
            baseRevision : int64
            proposals : Map<int, KernelClosure>
            transactionRef : ContentDigest
        }

        type KernelMetaTransactionError =
            | KernelMetaTransactionStale of expectedRevision:int64 * actualRevision:int64
            | KernelMetaTransactionAssignmentRejected of KernelMetaAssignmentError
            | KernelMetaTransactionDuplicateProposal of metaId:int

        type KernelMetaTransactionReceipt = private {
            transactionRef : ContentDigest
            baseRevision : int64
            committedRevision : int64
            assignmentReceipts : KernelMetaAssignmentReceipt list
            wokenObligationRefs : ContentDigest list
            contextRef : ContentDigest
        }

        module KernelMetaContext =
            let private contextDigest (generation:int) (revision:int64) (assignments:Map<int,KernelMetaAssignment>) =
                let assignmentText =
                    assignments
                    |> Map.toList
                    |> List.map (fun (metaId, assignment) ->
                        sprintf "%d=%s" metaId (ContentDigest.text assignment.assignmentRef))
                    |> String.concat "|"
                ContentDigest.ofText
                    "kernel-meta-context"
                    (FastRuntimeFormat.format "generation=%d|revision=%d|assignments=%s" [| box generation; box revision; box assignmentText |])

            let empty (generation:int) : KernelMetaContext =
                { generation = generation
                  revision = 0L
                  assignments = Map.empty
                  blockedByMeta = Map.empty
                  revisionDigest = contextDigest generation 0L Map.empty }

            let generation context = context.generation
            let revision context = context.revision
            let revisionDigest context = context.revisionDigest
            let assignmentCount context = context.assignments.Count
            let blockedMetaCount context = context.blockedByMeta.Count

            let tryResolve metaId (context:KernelMetaContext) : KernelClosure option =
                Map.tryFind metaId context.assignments |> Option.map (fun assignment -> assignment.value)

            let private closureStableText (closure:KernelClosure) =
                FastRuntimeFormat.format "%d:%d@%d:%d" [| box closure.term.generation; box closure.term.slot; box closure.environment.generation; box closure.environment.slot |]

            let private collectTermMetas (tryNode:KernelTermId -> KernelNode option) (root:KernelTermId) =
                let mutable pending = [root]
                let mutable visited : Set<KernelTermId> = Set.empty
                let mutable metas : Set<int> = Set.empty
                let mutable unknown : KernelTermId option = None
                while Option.isNone unknown && not (List.isEmpty pending) do
                    let current = List.head pending
                    pending <- List.tail pending
                    if not (Set.contains current visited) then
                        visited <- Set.add current visited
                        match tryNode current with
                        | None -> unknown <- Some current
                        | Some(KernelMeta metaId) -> metas <- Set.add metaId metas
                        | Some(KernelApplication(fnTerm, argument)) -> pending <- fnTerm :: argument :: pending
                        | Some(KernelLambda(_, domain, body))
                        | Some(KernelForall(_, domain, body)) -> pending <- domain :: body :: pending
                        | Some(KernelLet(typeTerm, value, body)) -> pending <- typeTerm :: value :: body :: pending
                        | Some(KernelConstructorValue(_, fields)) -> pending <- fields @ pending
                        | Some(KernelRecursorApplication(_, motive, major, minors)) ->
                            pending <- motive :: major :: (minors @ pending)
                        | Some(KernelProjection(structureTerm, _)) -> pending <- structureTerm :: pending
                        | Some(KernelQuotientValue(typeTerm, relationTerm, representative)) ->
                            pending <- typeTerm :: relationTerm :: representative :: pending
                        | Some(KernelQuotientLiftApplication(functionTerm, proofTerm, quotientTerm)) ->
                            pending <- functionTerm :: proofTerm :: quotientTerm :: pending
                        | Some(KernelQuotientInductionApplication(motive, proofTerm, quotientTerm)) ->
                            pending <- motive :: proofTerm :: quotientTerm :: pending
                        | Some _ -> ()
                match unknown with
                | Some term -> Error term
                | None -> Ok metas

            let private dependencyClosure (context:KernelMetaContext) (directMetas:Set<int>) =
                let mutable pending = Set.toList directMetas
                let mutable visited : Set<int> = Set.empty
                while not (List.isEmpty pending) do
                    let metaId = List.head pending
                    pending <- List.tail pending
                    if not (Set.contains metaId visited) then
                        visited <- Set.add metaId visited
                        match Map.tryFind metaId context.assignments with
                        | Some assignment -> pending <- Set.toList assignment.dependencyMetas @ pending
                        | None -> ()
                visited

            let registerBlocked (obligation:KernelMetaBlockedObligation) (context:KernelMetaContext) =
                let obligationKey = KernelMetaWakeEdgeId obligation.resumptionEdgeRef
                let blockedByMeta =
                    obligation.metaIds
                    |> Set.fold (fun state metaId ->
                        let current = Map.tryFind metaId state |> Option.defaultValue Map.empty
                        Map.add metaId (Map.add obligationKey obligation current) state) context.blockedByMeta
                { context with blockedByMeta = blockedByMeta }

            let blockedFor metaId (context:KernelMetaContext) : KernelMetaBlockedObligation list =
                Map.tryFind metaId context.blockedByMeta
                |> Option.map (Map.toList >> List.map snd)
                |> Option.defaultValue []

            let assign (tryNode:KernelTermId -> KernelNode option) metaId (value:KernelClosure) (context:KernelMetaContext) : Result<KernelMetaContext * KernelMetaAssignmentReceipt, KernelMetaAssignmentError> =
                if value.term.generation <> context.generation then
                    Error(KernelMetaForeignGeneration(metaId, context.generation, value.term.generation))
                else
                    match collectTermMetas tryNode value.term with
                    | Error unknown -> Error(KernelMetaAssignmentUnknownTerm(metaId, unknown))
                    | Ok directDependencies ->
                        let dependencies = dependencyClosure context directDependencies
                        if Set.contains metaId dependencies then
                            Error(KernelMetaOccursCheckFailed(metaId, dependencies))
                        else
                            let assignmentRef =
                                ContentDigest.ofText
                                    "kernel-meta-assignment"
                                    (FastRuntimeFormat.format "meta=%d|value=%s|dependencies=%s" [| box metaId; box (closureStableText value); box (dependencies |> Set.toList |> List.map string |> String.concat ",") |])
                            match Map.tryFind metaId context.assignments with
                            | Some existing when existing.assignmentRef = assignmentRef ->
                                let receipt =
                                    { metaId = metaId
                                      assignmentRef = assignmentRef
                                      priorRevision = context.revision
                                      newRevision = context.revision
                                      dependencyMetas = dependencies
                                      wokenObligations = []
                                      contextRef = context.revisionDigest }
                                Ok(context, receipt)
                            | Some existing ->
                                Error(KernelMetaAssignmentConflict(metaId, existing.assignmentRef, assignmentRef))
                            | None ->
                                let priorRevision = context.revision
                                let newRevision = priorRevision + 1L
                                let assignment =
                                    { metaId = metaId
                                      value = value
                                      dependencyMetas = dependencies
                                      assignmentRef = assignmentRef
                                      assignedAtRevision = newRevision }
                                let assignments = Map.add metaId assignment context.assignments
                                let woken = blockedFor metaId context
                                let wokenKeys =
                                    woken
                                    |> List.map (fun obligation -> KernelMetaWakeEdgeId obligation.resumptionEdgeRef)
                                    |> Set.ofList
                                let blockedByMeta =
                                    context.blockedByMeta
                                    |> Map.toList
                                    |> List.choose (fun (blockedMeta, obligations) ->
                                        let remaining =
                                            wokenKeys
                                            |> Set.fold (fun state obligationKey -> Map.remove obligationKey state) obligations
                                        if Map.isEmpty remaining then None
                                        else Some(blockedMeta, remaining))
                                    |> Map.ofList
                                let contextRef = contextDigest context.generation newRevision assignments
                                let updated =
                                    { context with
                                        revision = newRevision
                                        assignments = assignments
                                        blockedByMeta = blockedByMeta
                                        revisionDigest = contextRef }
                                let receipt =
                                    { metaId = metaId
                                      assignmentRef = assignmentRef
                                      priorRevision = priorRevision
                                      newRevision = newRevision
                                      dependencyMetas = dependencies
                                      wokenObligations = woken
                                      contextRef = contextRef }
                                Ok(updated, receipt)

            let beginTransaction (context:KernelMetaContext) : KernelMetaTransaction =
                { baseRevision = context.revision
                  proposals = Map.empty
                  transactionRef =
                    ContentDigest.ofText
                        "kernel-meta-transaction"
                        (FastRuntimeFormat.format "generation=%d|base_revision=%d|context=%s" [| box context.generation; box context.revision; box (ContentDigest.text context.revisionDigest) |]) }

            let propose metaId (value:KernelClosure) (transaction:KernelMetaTransaction) : Result<KernelMetaTransaction,KernelMetaTransactionError> =
                if Map.containsKey metaId transaction.proposals then
                    Error(KernelMetaTransactionDuplicateProposal metaId)
                else
                    let proposals = Map.add metaId value transaction.proposals
                    let transactionRef =
                        proposals
                        |> Map.toList
                        |> List.map (fun (id, closure) -> sprintf "%d=%s" id (closureStableText closure))
                        |> String.concat "|"
                        |> ContentDigest.ofText "kernel-meta-transaction-proposals"
                    Ok { transaction with proposals = proposals; transactionRef = transactionRef }

            let commitTransaction (tryNode:KernelTermId -> KernelNode option) (transaction:KernelMetaTransaction) (context:KernelMetaContext) : Result<KernelMetaContext * KernelMetaTransactionReceipt,KernelMetaTransactionError> =
                if transaction.baseRevision <> context.revision then
                    Error(KernelMetaTransactionStale(transaction.baseRevision, context.revision))
                else
                    let mutable state = context
                    let mutable receipts : KernelMetaAssignmentReceipt list = []
                    let mutable failure : KernelMetaTransactionError option = None
                    for (metaId, value) in Map.toList transaction.proposals do
                        if Option.isNone failure then
                            match assign tryNode metaId value state with
                            | Ok(next, receipt) ->
                                state <- next
                                receipts <- receipt :: receipts
                            | Error error -> failure <- Some(KernelMetaTransactionAssignmentRejected error)
                    match failure with
                    | Some error -> Error error
                    | None ->
                        let receipts = List.rev receipts
                        let woken =
                            receipts
                            |> List.collect (fun receipt -> receipt.wokenObligations)
                            |> List.map (fun obligation -> obligation.resumptionEdgeRef)
                            |> List.distinct
                        Ok(state,
                           { transactionRef = transaction.transactionRef
                             baseRevision = transaction.baseRevision
                             committedRevision = state.revision
                             assignmentReceipts = receipts
                             wokenObligationRefs = woken
                             contextRef = state.revisionDigest })

        [<Struct>]
        type KernelNodeIdentityId = private | KernelNodeIdentityId of ContentDigest

        module KernelNodeIdentityId =
            let ofNodeIdentity identity =
                ContentDigest.ofText "kernel-node" identity
                |> KernelNodeIdentityId
            let digest (KernelNodeIdentityId digest) = digest
            let text key = key |> digest |> ContentDigest.text

        type KernelArena = private {
            generation : int
            nextSlot : int
            nodes : Map<int, KernelNode>
            interned : Map<KernelNodeIdentityId, KernelTermId>
        }

        module KernelArena =
            let empty (generation:int) : KernelArena =
                { generation = generation
                  nextSlot = 1
                  nodes = Map.empty
                  interned = Map.empty }

            let private termText (term:KernelTermId) = sprintf "%d:%d" term.generation term.slot

            let private nodeIdentity (node:KernelNode) =
                match node with
                | KernelBound index -> sprintf "bound:%d" index
                | KernelFree binding -> "free:" + StableBindingId.text binding
                | KernelMeta metaId -> sprintf "meta:%d" metaId
                | KernelSort universe -> "sort:" + kernelUniverseStableText universe
                | KernelConstant(binding, universes) ->
                    sprintf "const:%s:%s"
                        (StableBindingId.text binding)
                        (universes |> List.map kernelUniverseStableText |> String.concat ",")
                | KernelApplication(fnTerm, argument) -> sprintf "app:%s:%s" (termText fnTerm) (termText argument)
                | KernelLambda(binder, domain, body) -> FastRuntimeFormat.format "lam:%s:%s:%s" [| box (kernelBinderInfoStableText binder); box (termText domain); box (termText body) |]
                | KernelForall(binder, domain, body) -> FastRuntimeFormat.format "forall:%s:%s:%s" [| box (kernelBinderInfoStableText binder); box (termText domain); box (termText body) |]
                | KernelLet(typeTerm, value, body) -> FastRuntimeFormat.format "let:%s:%s:%s" [| box (termText typeTerm); box (termText value); box (termText body) |]
                | KernelLiteral literal -> "literal:" + kernelLiteralStableText literal
                | KernelConstructorValue(constructor, fields) ->
                    sprintf "constructor:%s:%s" (StableBindingId.text constructor) (fields |> List.map termText |> String.concat ",")
                | KernelRecursorApplication(recursor, motive, major, minors) ->
                    FastRuntimeFormat.format "recursor:%s:%s:%s:%s" [| box (StableBindingId.text recursor); box (termText motive); box (termText major); box (minors |> List.map termText |> String.concat ",") |]
                | KernelProjection(structureTerm, ordinal) -> sprintf "projection:%s:%d" (termText structureTerm) ordinal
                | KernelQuotientValue(typeTerm, relationTerm, representative) ->
                    FastRuntimeFormat.format "quotient-value:%s:%s:%s" [| box (termText typeTerm); box (termText relationTerm); box (termText representative) |]
                | KernelQuotientLiftApplication(functionTerm, proofTerm, quotientTerm) ->
                    FastRuntimeFormat.format "quotient-lift:%s:%s:%s" [| box (termText functionTerm); box (termText proofTerm); box (termText quotientTerm) |]
                | KernelQuotientInductionApplication(motive, proofTerm, quotientTerm) ->
                    FastRuntimeFormat.format "quotient-induction:%s:%s:%s" [| box (termText motive); box (termText proofTerm); box (termText quotientTerm) |]

            let intern (node:KernelNode) (arena:KernelArena) : KernelTermId * KernelArena =
                let key = node |> nodeIdentity |> KernelNodeIdentityId.ofNodeIdentity
                match Map.tryFind key arena.interned with
                | Some term -> term, arena
                | None ->
                    let term : KernelTermId = { generation = arena.generation; slot = arena.nextSlot }
                    term,
                    { arena with
                        nextSlot = arena.nextSlot + 1
                        nodes = Map.add term.slot node arena.nodes
                        interned = Map.add key term arena.interned }

            let tryNode (term:KernelTermId) (arena:KernelArena) : KernelNode option =
                if term.generation <> arena.generation then None
                else Map.tryFind term.slot arena.nodes

        module KernelPositivity =
            let private opposite = function
                | KernelPositive -> KernelNegative
                | KernelNegative -> KernelPositive

            let private pathText path =
                path
                |> List.rev
                |> List.map (function
                    | KernelPositivityForallDomain -> "forall-domain"
                    | KernelPositivityForallBody -> "forall-body"
                    | KernelPositivityApplicationFunction -> "application-function"
                    | KernelPositivityApplicationArgument -> "application-argument"
                    | KernelPositivityConstructorField ordinal -> sprintf "constructor-field:%d" ordinal
                    | KernelPositivityRecursorField(label, ordinal) -> sprintf "recursor-%s:%d" label ordinal
                    | KernelPositivityProjectionField ordinal -> sprintf "projection:%d" ordinal
                    | KernelPositivityQuotientComponent label -> "quotient:" + label)
                |> String.concat "/"

            let private occurrence target polarity path =
                let occurrenceRef =
                    ContentDigest.ofText
                        "kernel-positivity-occurrence"
                        (StableBindingId.text target
                         + "|polarity=" + (match polarity with | KernelPositive -> "positive" | KernelNegative -> "negative")
                         + "|path=" + pathText path)
                { target = target; polarity = polarity; path = path; occurrenceRef = occurrenceRef }

            let certify (arena:KernelArena) (inductive:StableBindingId) (constructorTypes:KernelTermId list) =
                let mutable pending =
                    constructorTypes
                    |> List.mapi (fun ordinal term -> term, KernelPositive, [KernelPositivityConstructorField ordinal], false)
                let mutable visited : Set<KernelTermId * KernelPolarity * bool> = Set.empty
                let mutable positives : KernelPositivityOccurrence list = []
                let mutable failure : KernelPositivityFailure option = None
                while Option.isNone failure && not (List.isEmpty pending) do
                    let term, polarity, path, underUnknownApplication = List.head pending
                    pending <- List.tail pending
                    let visitKey = term, polarity, underUnknownApplication
                    if not (Set.contains visitKey visited) then
                        visited <- Set.add visitKey visited
                        if term.generation <> arena.generation then
                            failure <- Some(KernelPositivityForeignGeneration term)
                        else
                            match KernelArena.tryNode term arena with
                            | None -> failure <- Some(KernelUnknownOccurrenceTerm term)
                            | Some(KernelConstant(binding, _)) when binding = inductive ->
                                let found = occurrence inductive polarity path
                                match polarity, underUnknownApplication with
                                | KernelNegative, _ -> failure <- Some(KernelNegativeOccurrence found)
                                | KernelPositive, true -> failure <- Some(KernelOccurrenceUnderUnknownApplication found)
                                | KernelPositive, false -> positives <- found :: positives
                            | Some(KernelForall(_, domain, body)) ->
                                pending <- (domain, opposite polarity, KernelPositivityForallDomain :: path, underUnknownApplication)
                                           :: (body, polarity, KernelPositivityForallBody :: path, underUnknownApplication)
                                           :: pending
                            | Some(KernelApplication(fnTerm, argument)) ->
                                pending <- (fnTerm, polarity, KernelPositivityApplicationFunction :: path, underUnknownApplication)
                                           :: (argument, polarity, KernelPositivityApplicationArgument :: path, true)
                                           :: pending
                            | Some(KernelLambda(_, domain, body)) ->
                                pending <- (domain, opposite polarity, KernelPositivityForallDomain :: path, underUnknownApplication)
                                           :: (body, polarity, KernelPositivityForallBody :: path, underUnknownApplication)
                                           :: pending
                            | Some(KernelLet(typeTerm, value, body)) ->
                                pending <- (typeTerm, opposite polarity, KernelPositivityForallDomain :: path, underUnknownApplication)
                                           :: (value, polarity, KernelPositivityApplicationArgument :: path, underUnknownApplication)
                                           :: (body, polarity, KernelPositivityForallBody :: path, underUnknownApplication)
                                           :: pending
                            | Some(KernelConstructorValue(_, fields)) ->
                                fields
                                |> List.iteri (fun ordinal field ->
                                    pending <- (field, polarity, KernelPositivityConstructorField ordinal :: path, underUnknownApplication) :: pending)
                            | Some(KernelRecursorApplication(_, motive, major, minors)) ->
                                pending <- (motive, opposite polarity, KernelPositivityRecursorField("motive", 0) :: path, underUnknownApplication)
                                           :: (major, polarity, KernelPositivityRecursorField("major", 0) :: path, underUnknownApplication)
                                           :: pending
                                minors
                                |> List.iteri (fun ordinal minor ->
                                    pending <- (minor, polarity, KernelPositivityRecursorField("minor", ordinal) :: path, underUnknownApplication) :: pending)
                            | Some(KernelProjection(structureTerm, ordinal)) ->
                                pending <- (structureTerm, polarity, KernelPositivityProjectionField ordinal :: path, underUnknownApplication) :: pending
                            | Some(KernelQuotientValue(typeTerm, relationTerm, representative)) ->
                                pending <- (typeTerm, polarity, KernelPositivityQuotientComponent "type" :: path, underUnknownApplication)
                                           :: (relationTerm, opposite polarity, KernelPositivityQuotientComponent "relation" :: path, true)
                                           :: (representative, polarity, KernelPositivityQuotientComponent "representative" :: path, underUnknownApplication)
                                           :: pending
                            | Some(KernelQuotientLiftApplication(functionTerm, proofTerm, quotientTerm)) ->
                                pending <- (functionTerm, polarity, KernelPositivityQuotientComponent "lift-function" :: path, underUnknownApplication)
                                           :: (proofTerm, KernelNegative, KernelPositivityQuotientComponent "respect-proof" :: path, true)
                                           :: (quotientTerm, polarity, KernelPositivityQuotientComponent "quotient" :: path, underUnknownApplication)
                                           :: pending
                            | Some(KernelQuotientInductionApplication(motive, proofTerm, quotientTerm)) ->
                                pending <- (motive, opposite polarity, KernelPositivityQuotientComponent "motive" :: path, underUnknownApplication)
                                           :: (proofTerm, polarity, KernelPositivityQuotientComponent "proof" :: path, underUnknownApplication)
                                           :: (quotientTerm, polarity, KernelPositivityQuotientComponent "quotient" :: path, underUnknownApplication)
                                           :: pending
                            | Some(KernelBound _)
                            | Some(KernelFree _)
                            | Some(KernelMeta _)
                            | Some(KernelSort _)
                            | Some(KernelConstant _)
                            | Some(KernelLiteral _) -> ()
                match failure with
                | Some error -> Error error
                | None ->
                    let positives = List.rev positives
                    let certificateRef =
                        positives
                        |> List.map (fun item -> ContentDigest.text item.occurrenceRef)
                        |> String.concat "|"
                        |> fun occurrenceText ->
                            ContentDigest.ofText
                                "kernel-positivity-certificate"
                                (StableBindingId.text inductive
                                 + "|constructors=" + (constructorTypes |> List.map (fun term -> sprintf "%d:%d" term.generation term.slot) |> String.concat ",")
                                 + "|occurrences=" + occurrenceText)
                    Ok {
                        inductive = inductive
                        constructorTypes = constructorTypes
                        positiveOccurrences = positives
                        certificateRef = certificateRef
                        closed = true
                    }

            let certificateRef certificate = certificate.certificateRef
            let isClosed certificate = certificate.closed
            let inductive certificate = certificate.inductive

        type KernelTransparency =
            | KernelTransparencyReducible
            | KernelTransparencyInstances
            | KernelTransparencySemireducible
            | KernelTransparencyAll

        let private kernelTransparencyStableText = function
            | KernelTransparencyReducible -> "reducible"
            | KernelTransparencyInstances -> "instances"
            | KernelTransparencySemireducible -> "semireducible"
            | KernelTransparencyAll -> "all"

        type KernelWhnfBlockedReason =
            | KernelWhnfForeignGeneration
            | KernelWhnfUnknownTerm
            | KernelWhnfUnknownEnvironment
            | KernelWhnfMetaVariable of int
            | KernelWhnfRecursorAwaitingMajor of StableBindingId
            | KernelWhnfFuelExhausted

        let private kernelWhnfBlockedReasonStableText = function
            | KernelWhnfForeignGeneration -> "foreign_generation"
            | KernelWhnfUnknownTerm -> "unknown_term"
            | KernelWhnfUnknownEnvironment -> "unknown_environment"
            | KernelWhnfMetaVariable metaId -> sprintf "meta_variable(%d)" metaId
            | KernelWhnfRecursorAwaitingMajor recursor -> "recursor_awaiting_major(" + StableBindingId.text recursor + ")"
            | KernelWhnfFuelExhausted -> "fuel_exhausted"

        // Five-round migration round : pure kernel comparison is now
        // scheduled by an interaction net. Active-pair consumption is the
        // productivity authority; blocked pairs survive as typed suspended
        // edges and are resumed by MetaContext wake receipts.
        type KernelInteractionOrigin =
            | KernelInteractionDefEq of rootRef:ContentDigest
            | KernelInteractionSpecialization of planRef:ContentDigest

        type KernelInteractionPathStep =
            | KernelInteractionNeutralHead
            | KernelInteractionNeutralArgument of ordinal:int
            | KernelInteractionNodeField of label:string * ordinal:int
            | KernelInteractionApplicationFunction
            | KernelInteractionApplicationArgument
            | KernelInteractionBinderDomain
            | KernelInteractionBinderBody
            | KernelInteractionQuotientComponent of label:string * ordinal:int

        type KernelInteractionPath =
            | KernelInteractionRoot
            | KernelInteractionChild of parent:KernelInteractionPath * step:KernelInteractionPathStep

        [<Struct>]
        type KernelInteractionPairId = private KernelInteractionPairId of ContentDigest

        let private kernelInteractionPathStepStableText = function
            | KernelInteractionNeutralHead -> "neutral-head"
            | KernelInteractionNeutralArgument ordinal -> "neutral-argument:" + string ordinal
            | KernelInteractionNodeField(label, ordinal) -> "field:" + label + ":" + string ordinal
            | KernelInteractionApplicationFunction -> "application-function"
            | KernelInteractionApplicationArgument -> "application-argument"
            | KernelInteractionBinderDomain -> "binder-domain"
            | KernelInteractionBinderBody -> "binder-body"
            | KernelInteractionQuotientComponent(label, ordinal) -> "quotient:" + label + ":" + string ordinal

        let rec private kernelInteractionPathStableText = function
            | KernelInteractionRoot -> "root"
            | KernelInteractionChild(parent, step) ->
                kernelInteractionPathStableText parent + "/" + kernelInteractionPathStepStableText step

        type KernelInteractionPair = private {
            pairId : KernelInteractionPairId
            origin : KernelInteractionOrigin
            left : KernelClosure
            right : KernelClosure
            expectedType : KernelTermId option
            transparency : KernelTransparency
            path : KernelInteractionPath
            depth : int
            dependencyRefs : Set<ContentDigest>
        }

        type KernelInteractionSuspension = private {
            pair : KernelInteractionPair
            blockedMetas : Set<int>
            wakeRefs : Set<ContentDigest>
            suspensionRef : ContentDigest
        }

        type KernelInteractionEvent =
            | KernelInteractionPairEnqueued of pairRef:ContentDigest
            | KernelInteractionActivePairConsumed of pairRef:ContentDigest * ordinal:int64
            | KernelInteractionPairSuspended of pairRef:ContentDigest * suspensionRef:ContentDigest
            | KernelInteractionPairResumed of pairRef:ContentDigest * wakeRef:ContentDigest
            | KernelInteractionNetClosed of consumed:int64 * suspended:int

        type KernelInteractionProofNode = private {
            previousRef : ContentDigest option
            event : KernelInteractionEvent
            proofRef : ContentDigest
        }

        type KernelInteractionNet = private {
            generation : int
            active : Map<KernelInteractionPairId, KernelInteractionPair>
            suspended : Map<KernelInteractionPairId, KernelInteractionSuspension>
            consumedPairIds : Set<KernelInteractionPairId>
            consumedCount : int64
            resumedCount : int64
            proof : KernelInteractionProofNode
        }

        type KernelInteractionNetClosure =
            | KernelInteractionNetOpen of activePairs:int * suspendedPairs:int
            | KernelInteractionNetClosedReceipt of consumedPairs:int64 * proofRef:ContentDigest

        type KernelInteractionNetReceipt = private {
            netRef : ContentDigest
            proofRef : ContentDigest
            activePairs : int
            suspendedPairs : int
            consumedPairs : int64
            resumedPairs : int64
            closure : KernelInteractionNetClosure
        }

        module KernelInteractionNet =
            let private originStableText = function
                | KernelInteractionDefEq rootRef -> "defeq:" + ContentDigest.text rootRef
                | KernelInteractionSpecialization planRef -> "specialization:" + ContentDigest.text planRef

            let private closureStableText (closure:KernelClosure) =
                FastRuntimeFormat.format "%d:%d@%d:%d" [| box closure.term.generation; box closure.term.slot; box closure.environment.generation; box closure.environment.slot |]

            let private expectedTypeStableText (expectedType:KernelTermId option) =
                match expectedType with
                | None -> "none"
                | Some term -> sprintf "%d:%d" term.generation term.slot

            let private eventStableText = function
                | KernelInteractionPairEnqueued pairRef -> "enqueue:" + ContentDigest.text pairRef
                | KernelInteractionActivePairConsumed(pairRef, ordinal) ->
                    sprintf "consume:%s:%d" (ContentDigest.text pairRef) ordinal
                | KernelInteractionPairSuspended(pairRef, suspensionRef) ->
                    "suspend:" + ContentDigest.text pairRef + ":" + ContentDigest.text suspensionRef
                | KernelInteractionPairResumed(pairRef, wakeRef) ->
                    "resume:" + ContentDigest.text pairRef + ":" + ContentDigest.text wakeRef
                | KernelInteractionNetClosed(consumed, suspended) ->
                    sprintf "close:%d:%d" consumed suspended

            let private advance (event:KernelInteractionEvent) (proof:KernelInteractionProofNode) : KernelInteractionProofNode =
                let previous = ContentDigest.text proof.proofRef
                let proofRef = ContentDigest.ofText "kernel-interaction-proof" (previous + "|" + eventStableText event)
                { previousRef = Some proof.proofRef; event = event; proofRef = proofRef }

            let empty (generation:int) : KernelInteractionNet =
                let genesisEvent = KernelInteractionNetClosed(0L, 0)
                let genesisRef = ContentDigest.ofText "kernel-interaction-proof" (sprintf "genesis:%d" generation)
                { generation = generation
                  active = Map.empty
                  suspended = Map.empty
                  consumedPairIds = Set.empty
                  consumedCount = 0L
                  resumedCount = 0L
                  proof = { previousRef = None; event = genesisEvent; proofRef = genesisRef } }

            let private pairIdentity (origin:KernelInteractionOrigin) (left:KernelClosure) (right:KernelClosure) (expectedType:KernelTermId option) (transparency:KernelTransparency) (path:KernelInteractionPath) (depth:int) (dependencies:Set<ContentDigest>) =
                let leftText = closureStableText left
                let rightText = closureStableText right
                let first, second = if compare leftText rightText <= 0 then leftText, rightText else rightText, leftText
                KernelInteractionPairId (
                    ContentDigest.ofText
                        "kernel-interaction-pair"
                        (String.concat "|"
                            [ originStableText origin
                              first
                              second
                              expectedTypeStableText expectedType
                              kernelTransparencyStableText transparency
                              kernelInteractionPathStableText path
                              string depth
                              dependencies |> Set.toList |> List.map ContentDigest.text |> String.concat "," ]))

            let pairRef (KernelInteractionPairId pairRef) = pairRef

            let enqueue (origin:KernelInteractionOrigin) (left:KernelClosure) (right:KernelClosure) (expectedType:KernelTermId option) (transparency:KernelTransparency) (path:KernelInteractionPath) (depth:int) (dependencyRefs:Set<ContentDigest>) (net:KernelInteractionNet) : KernelInteractionNet =
                if left.term.generation <> net.generation || right.term.generation <> net.generation then
                    invalidArg "pair" "foreign interaction-net generation"
                let pairId = pairIdentity origin left right expectedType transparency path depth dependencyRefs
                if Set.contains pairId net.consumedPairIds || Map.containsKey pairId net.active || Map.containsKey pairId net.suspended then
                    net
                else
                    let pair =
                        { pairId = pairId
                          origin = origin
                          left = left
                          right = right
                          expectedType = expectedType
                          transparency = transparency
                          path = path
                          depth = depth
                          dependencyRefs = dependencyRefs }
                    let pairRef = pairRef pairId
                    { net with
                        active = Map.add pairId pair net.active
                        proof = advance (KernelInteractionPairEnqueued pairRef) net.proof }

            let tryConsume (net:KernelInteractionNet) : (KernelInteractionPair * KernelInteractionNet) option =
                match Map.toList net.active with
                | [] -> None
                | (key, pair) :: _ ->
                    let ordinal = net.consumedCount + 1L
                    let next =
                        { net with
                            active = Map.remove key net.active
                            consumedPairIds = Set.add key net.consumedPairIds
                            consumedCount = ordinal
                            proof = advance (KernelInteractionActivePairConsumed(pairRef pair.pairId, ordinal)) net.proof }
                    Some(pair, next)

            let resumptionEdgeRef (pairRef:ContentDigest) (metaId:int) (metaRevision:int64) =
                ContentDigest.ofText
                    "kernel-interaction-resumption-edge"
                    (ContentDigest.text pairRef + "|meta=" + string metaId + "|revision=" + string metaRevision)

            let suspend (pair:KernelInteractionPair) (blockedMetas:Set<int>) (wakeRefs:Set<ContentDigest>) (net:KernelInteractionNet) : KernelInteractionNet =
                let pairRef = pairRef pair.pairId
                let suspensionRef =
                    ContentDigest.ofText
                        "kernel-interaction-suspension"
                        (ContentDigest.text pairRef
                         + "|metas=" + (blockedMetas |> Set.toList |> List.map string |> String.concat ",")
                         + "|wakes=" + (wakeRefs |> Set.toList |> List.map ContentDigest.text |> String.concat ","))
                let suspension =
                    { pair = pair
                      blockedMetas = blockedMetas
                      wakeRefs = wakeRefs
                      suspensionRef = suspensionRef }
                { net with
                    suspended = Map.add pair.pairId suspension net.suspended
                    proof = advance (KernelInteractionPairSuspended(pairRef, suspensionRef)) net.proof }

            let resume (wakeRef:ContentDigest) (net:KernelInteractionNet) : KernelInteractionNet =
                let matching, retained =
                    net.suspended
                    |> Map.partition (fun _ suspension -> Set.contains wakeRef suspension.wakeRefs)
                let mutable next = { net with suspended = retained }
                for (_, suspension) in Map.toList matching do
                    let pairRef = pairRef suspension.pair.pairId
                    next <-
                        { next with
                            active = Map.add suspension.pair.pairId suspension.pair next.active
                            resumedCount = next.resumedCount + 1L
                            proof = advance (KernelInteractionPairResumed(pairRef, wakeRef)) next.proof }
                next

            let close (net:KernelInteractionNet) : KernelInteractionNet =
                let suspended = net.suspended.Count
                { net with
                    active = Map.empty
                    suspended = Map.empty
                    proof = advance (KernelInteractionNetClosed(net.consumedCount, suspended)) net.proof }

            let activeCount (net:KernelInteractionNet) = net.active.Count
            let suspendedCount (net:KernelInteractionNet) = net.suspended.Count
            let consumedCount (net:KernelInteractionNet) = net.consumedCount
            let resumedCount (net:KernelInteractionNet) = net.resumedCount
            let proofRef (net:KernelInteractionNet) = net.proof.proofRef

            let private netDigest (net:KernelInteractionNet) =
                ContentDigest.ofText
                    "kernel-interaction-net"
                    (FastRuntimeFormat.format "generation=%d|active=%s|suspended=%s|consumed=%d|resumed=%d|proof=%s" [| box net.generation; box (net.active |> Map.toList |> List.map (fst >> pairRef >> ContentDigest.text) |> String.concat ","); box (net.suspended |> Map.toList |> List.map (fst >> pairRef >> ContentDigest.text) |> String.concat ","); box net.consumedCount; box net.resumedCount; box (ContentDigest.text net.proof.proofRef) |])

            let receipt (net:KernelInteractionNet) : KernelInteractionNetReceipt =
                { netRef = netDigest net
                  proofRef = net.proof.proofRef
                  activePairs = net.active.Count
                  suspendedPairs = net.suspended.Count
                  consumedPairs = net.consumedCount
                  resumedPairs = net.resumedCount
                  closure =
                    if net.active.IsEmpty && net.suspended.IsEmpty then
                        KernelInteractionNetClosedReceipt(net.consumedCount, net.proof.proofRef)
                    else
                        KernelInteractionNetOpen(net.active.Count, net.suspended.Count) }

            let receiptNetRef (receipt:KernelInteractionNetReceipt) = receipt.netRef
            let receiptProofRef (receipt:KernelInteractionNetReceipt) = receipt.proofRef
            let receiptClosure (receipt:KernelInteractionNetReceipt) = receipt.closure

        [<Struct; StructuralEquality; NoComparison>]
        type KernelHvmNodeId = private | KernelHvmNodeId of int

        type KernelHvmPortSlot =
            | KernelHvmPrincipal
            | KernelHvmAuxiliary0
            | KernelHvmAuxiliary1

        [<Struct; StructuralEquality; NoComparison>]
        type KernelHvmPort = private {
            node : KernelHvmNodeId
            slot : KernelHvmPortSlot
        }

        [<StructuralEquality; NoComparison>]
        type KernelHvmWire = private {
            left : KernelHvmPort
            right : KernelHvmPort
        }

        type KernelHvmPortLinearityError =
            | KernelHvmUnknownPortNode of KernelHvmPort
            | KernelHvmDuplicatePortConnection of KernelHvmPort

        [<NoEquality; NoComparison>]
        type KernelHvmPortLinearityReceipt = private {
            proofRef : ContentDigest
            nodeCount : int
            wireCount : int
            errors : KernelHvmPortLinearityError list
        }

        module KernelHvmPortLinearity =
            let node value = KernelHvmNodeId value

            let port node slot =
                { node = node; slot = slot }

            let wire left right =
                { left = left; right = right }

            let validate (nodes:KernelHvmNodeId list) (wires:KernelHvmWire list) =
                let nodeMembership = System.Collections.Generic.HashSet<KernelHvmNodeId>(nodes)
                let ports =
                    wires
                    |> List.collect (fun wire -> [ wire.left; wire.right ])
                let unknown =
                    ports
                    |> List.choose (fun port ->
                        if nodeMembership.Contains port.node then None
                        else Some(KernelHvmUnknownPortNode port))
                let duplicates =
                    ports
                    |> List.countBy id
                    |> List.choose (fun (port, count) ->
                        if count > 1 then Some(KernelHvmDuplicatePortConnection port)
                        else None)
                unknown @ duplicates

            let private nodeStableText (KernelHvmNodeId value) = string value

            let private slotStableText = function
                | KernelHvmPrincipal -> "principal"
                | KernelHvmAuxiliary0 -> "aux0"
                | KernelHvmAuxiliary1 -> "aux1"

            let private portStableText port =
                nodeStableText port.node + ":" + slotStableText port.slot

            let private wireStableText wire =
                portStableText wire.left + "->" + portStableText wire.right

            let private errorStableText = function
                | KernelHvmUnknownPortNode port -> "unknown:" + portStableText port
                | KernelHvmDuplicatePortConnection port -> "duplicate:" + portStableText port

            let validateWithReceipt nodes wires =
                let errors = validate nodes wires
                let proofRef =
                    ContentDigest.ofText
                        "hvm-port-linearity-receipt"
                        ((nodes |> List.map nodeStableText |> String.concat ",")
                         + "|wires=" + (wires |> List.map wireStableText |> String.concat ",")
                         + "|errors=" + (errors |> List.map errorStableText |> String.concat ","))
                { proofRef = proofRef
                  nodeCount = List.length nodes
                  wireCount = List.length wires
                  errors = errors }

            let isLinear receipt = List.isEmpty receipt.errors
            let proofRef receipt = receipt.proofRef
            let errorCount receipt = List.length receipt.errors

        let hvmBackendLoweringAuthorityFromReceipts
            (netReceipt:KernelInteractionNetReceipt)
            (linearityReceipt:KernelHvmPortLinearityReceipt)
            : TerminalFlowBreakthrough.BackendLoweringAuthority =
            let artifactRef = KernelInteractionNet.receiptNetRef netReceipt
            let conformanceRef = KernelHvmPortLinearity.proofRef linearityReceipt
            match KernelInteractionNet.receiptClosure netReceipt, KernelHvmPortLinearity.isLinear linearityReceipt with
            | KernelInteractionNetClosedReceipt(_, semanticClosureRef), true ->
                TerminalFlowBreakthrough.BackendLoweringVerified(
                    TerminalFlowBreakthrough.backendVerificationEvidence
                        TerminalFlowBreakthrough.BackendTargetHvm
                        artifactRef
                        semanticClosureRef
                        conformanceRef
                        TerminalFlowBreakthrough.BackendVerificationRuntimeReceipt)
            | KernelInteractionNetOpen(activePairs, suspendedPairs), _ ->
                TerminalFlowBreakthrough.BackendLoweringRejected(
                    TerminalFlowBreakthrough.BackendTargetHvm,
                    artifactRef,
                    conformanceRef,
                    CompilerIdentityKernel.OperationalReasonIdOps.create(
                        FastRuntimeFormat.format "hvm_interaction_net_open:active=%d:suspended=%d" [| box activePairs; box suspendedPairs |]))
            | KernelInteractionNetClosedReceipt _, false ->
                TerminalFlowBreakthrough.BackendLoweringRejected(
                    TerminalFlowBreakthrough.BackendTargetHvm,
                    artifactRef,
                    conformanceRef,
                    CompilerIdentityKernel.OperationalReasonIdOps.create(
                        "hvm_port_linearity_rejected:errors=" + string (KernelHvmPortLinearity.errorCount linearityReceipt)))

        type KernelHvmNodeKind =
            | KernelHvmRoot
            | KernelHvmErase
            | KernelHvmConstructor of label:int
            | KernelHvmDuplicator of label:int
            | KernelHvmReference of StableBindingId
            | KernelHvmOperator of PortablePrimitive

        type KernelHvmRewrite =
            | KernelHvmAnnihilate of KernelHvmNodeId * KernelHvmNodeId
            | KernelHvmCommute of KernelHvmNodeId * KernelHvmNodeId
            | KernelHvmEraseNode of KernelHvmNodeId
            | KernelHvmDereference of KernelHvmNodeId * StableBindingId
            | KernelHvmNoRewrite

        type KernelHvmRewritePlan = private {
            rewrite : KernelHvmRewrite
            consumedNodes : KernelHvmNodeId list
            mutatesTopology : bool
        }

        module KernelHvmRewrite =
            let private plan rewrite consumedNodes mutatesTopology =
                { rewrite = rewrite
                  consumedNodes = consumedNodes
                  mutatesTopology = mutatesTopology }

            let classify leftNode leftKind rightNode rightKind =
                match leftKind, rightKind with
                | KernelHvmErase, _ -> plan (KernelHvmEraseNode rightNode) [ rightNode ] true
                | _, KernelHvmErase -> plan (KernelHvmEraseNode leftNode) [ leftNode ] true
                | KernelHvmConstructor left, KernelHvmConstructor right when left = right ->
                    plan (KernelHvmAnnihilate(leftNode, rightNode)) [ leftNode; rightNode ] true
                | KernelHvmDuplicator left, KernelHvmDuplicator right when left = right ->
                    plan (KernelHvmAnnihilate(leftNode, rightNode)) [ leftNode; rightNode ] true
                | KernelHvmReference binding, _ ->
                    plan (KernelHvmDereference(leftNode, binding)) [ leftNode ] true
                | _, KernelHvmReference binding ->
                    plan (KernelHvmDereference(rightNode, binding)) [ rightNode ] true
                | _ -> plan (KernelHvmCommute(leftNode, rightNode)) [] true

            let noRewrite = plan KernelHvmNoRewrite [] false
            let rewrite value = value.rewrite
            let consumedNodes value = value.consumedNodes
            let mutatesTopology value = value.mutatesTopology

            let private nodeText (KernelHvmNodeId value) = string value

            let stableText value =
                match value.rewrite with
                | KernelHvmAnnihilate(left, right) ->
                    "annihilate:" + nodeText left + ":" + nodeText right
                | KernelHvmCommute(left, right) ->
                    "commute:" + nodeText left + ":" + nodeText right
                | KernelHvmEraseNode node -> "erase:" + nodeText node
                | KernelHvmDereference(node, binding) ->
                    "dereference:" + nodeText node + ":" + StableBindingId.text binding
                | KernelHvmNoRewrite -> "no-rewrite"

        type KernelWhnfResult =
            | KernelWhnfValue of KernelClosure
            | KernelWhnfNeutral of head:KernelClosure * arguments:KernelClosure list
            | KernelWhnfBlocked of KernelWhnfBlockedReason

        type KernelWhnfEvaluation = private {
            result : KernelWhnfResult
            environment : KernelEnvironment
            steps : int
            productiveSteps : int
        }

        module KernelWhnfEvaluation =
            let result evaluation = evaluation.result
            let environment evaluation = evaluation.environment
            let steps evaluation = evaluation.steps
            let productiveSteps evaluation = evaluation.productiveSteps

        module KernelWhnf =
            let evaluate (fuel:int) (arena:KernelArena) (environment:KernelEnvironment) (metaContext:KernelMetaContext) (closure:KernelClosure) : KernelWhnfEvaluation =
                let initialFuel = max 0 fuel
                let mutable remainingFuel = initialFuel
                let mutable current = closure
                let mutable arguments : KernelClosure list = []
                let mutable result : KernelWhnfResult option =
                    if closure.term.generation <> arena.generation
                       || closure.environment.generation <> environment.generation then
                        Some(KernelWhnfBlocked KernelWhnfForeignGeneration)
                    else None
                let mutable environmentState = environment
                let mutable productiveSteps = 0
                while Option.isNone result && remainingFuel > 0 do
                    remainingFuel <- remainingFuel - 1
                    match KernelArena.tryNode current.term arena with
                    | None -> result <- Some(KernelWhnfBlocked KernelWhnfUnknownTerm)
                    | Some(KernelApplication(fnTerm, argument)) ->
                        productiveSteps <- productiveSteps + 1
                        arguments <- { term = argument; environment = current.environment } :: arguments
                        current <- { term = fnTerm; environment = current.environment }
                    | Some(KernelLet(_, value, body)) ->
                        productiveSteps <- productiveSteps + 1
                        let valueClosure = { term = value; environment = current.environment }
                        let nextEnvironment, updated = KernelEnvironment.extend valueClosure current.environment environmentState
                        environmentState <- updated
                        current <- { term = body; environment = nextEnvironment }
                    | Some(KernelBound index) ->
                        match KernelEnvironment.tryLookup index current.environment environmentState with
                        | Some replacement ->
                            productiveSteps <- productiveSteps + 1
                            current <- replacement
                        | None -> result <- Some(KernelWhnfNeutral(current, List.rev arguments))
                    | Some(KernelLambda(_, _, body)) when not (List.isEmpty arguments) ->
                        productiveSteps <- productiveSteps + 1
                        let argument = List.head arguments
                        arguments <- List.tail arguments
                        let nextEnvironment, updated = KernelEnvironment.extend argument current.environment environmentState
                        environmentState <- updated
                        current <- { term = body; environment = nextEnvironment }
                    | Some(KernelRecursorApplication(recursor, _, major, minors)) ->
                        match KernelArena.tryNode major arena with
                        | Some(KernelConstructorValue(_, fields)) when not (List.isEmpty minors) ->
                            productiveSteps <- productiveSteps + 1
                            current <- { term = List.head minors; environment = current.environment }
                            let fieldClosures = fields |> List.map (fun field -> { term = field; environment = current.environment })
                            arguments <- fieldClosures @ arguments
                        | _ -> result <- Some(KernelWhnfBlocked(KernelWhnfRecursorAwaitingMajor recursor))
                    | Some(KernelProjection(structureTerm, fieldOrdinal)) ->
                        match KernelArena.tryNode structureTerm arena with
                        | Some(KernelConstructorValue(_, fields)) when fieldOrdinal >= 0 && fieldOrdinal < fields.Length ->
                            productiveSteps <- productiveSteps + 1
                            current <- { term = fields.[fieldOrdinal]; environment = current.environment }
                        | _ -> result <- Some(KernelWhnfNeutral(current, List.rev arguments))
                    | Some(KernelQuotientLiftApplication(functionTerm, _, quotientTerm)) ->
                        match KernelArena.tryNode quotientTerm arena with
                        | Some(KernelQuotientValue(_, _, representative)) ->
                            productiveSteps <- productiveSteps + 1
                            arguments <- { term = representative; environment = current.environment } :: arguments
                            current <- { term = functionTerm; environment = current.environment }
                        | _ -> result <- Some(KernelWhnfNeutral(current, List.rev arguments))
                    | Some(KernelQuotientInductionApplication(_, representativeProof, quotientTerm)) ->
                        match KernelArena.tryNode quotientTerm arena with
                        | Some(KernelQuotientValue(_, _, representative)) ->
                            productiveSteps <- productiveSteps + 1
                            arguments <- { term = representative; environment = current.environment } :: arguments
                            current <- { term = representativeProof; environment = current.environment }
                        | _ -> result <- Some(KernelWhnfNeutral(current, List.rev arguments))
                    | Some(KernelMeta metaId) ->
                        match KernelMetaContext.tryResolve metaId metaContext with
                        | Some assigned ->
                            productiveSteps <- productiveSteps + 1
                            current <- assigned
                        | None -> result <- Some(KernelWhnfBlocked(KernelWhnfMetaVariable metaId))
                    | Some _ when List.isEmpty arguments -> result <- Some(KernelWhnfValue current)
                    | Some _ -> result <- Some(KernelWhnfNeutral(current, List.rev arguments))
                { result = result |> Option.defaultValue (KernelWhnfBlocked KernelWhnfFuelExhausted)
                  environment = environmentState
                  steps = initialFuel - remainingFuel
                  productiveSteps = productiveSteps }

        type KernelReadbackMode =
            | KernelReadbackWeakHead
            | KernelReadbackEtaLong
            | KernelReadbackMetaPreserving

        type KernelReadbackClosure =
            | KernelReadbackOpen of blockedReasons:KernelWhnfBlockedReason list
            | KernelReadbackClosed

        type KernelReadbackReceipt = private {
            sourceClosureRef : ContentDigest
            resultTerm : KernelTermId
            generatedNodes : int
            etaExpansions : int
            quotientReductions : int
            blockedReasons : KernelWhnfBlockedReason list
            receiptRef : ContentDigest
            closure : KernelReadbackClosure
        }

        module KernelQuoteReadback =
            let private closureRef closure =
                ContentDigest.ofText
                    "kernel-readback-closure"
                    (FastRuntimeFormat.format "%d:%d@%d:%d" [| box closure.term.generation; box closure.term.slot; box closure.environment.generation; box closure.environment.slot |])

            let quote fuel mode arena environment metaContext closure =
                let evaluation = KernelWhnf.evaluate fuel arena environment metaContext closure
                let mutable arenaState = arena
                let mutable generated = 0
                let mutable etaExpansions = 0
                let mutable quotientReductions = 0
                let mutable blocked : KernelWhnfBlockedReason list = []
                let intern node =
                    let term, next = KernelArena.intern node arenaState
                    if next.nextSlot <> arenaState.nextSlot then generated <- generated + 1
                    arenaState <- next
                    term
                let resultTerm =
                    match KernelWhnfEvaluation.result evaluation with
                    | KernelWhnfValue value ->
                        match mode, KernelArena.tryNode value.term arenaState with
                        | KernelReadbackEtaLong, Some(KernelConstructorValue(constructor, fields)) when not (List.isEmpty fields) ->
                            etaExpansions <- etaExpansions + 1
                            fields
                            |> List.mapi (fun ordinal _ -> intern (KernelProjection(value.term, ordinal)))
                            |> fun projected -> intern (KernelConstructorValue(constructor, projected))
                        | _, Some(KernelQuotientLiftApplication _)
                        | _, Some(KernelQuotientInductionApplication _) ->
                            quotientReductions <- quotientReductions + KernelWhnfEvaluation.productiveSteps evaluation
                            value.term
                        | _ -> value.term
                    | KernelWhnfNeutral(head, arguments) ->
                        arguments
                        |> List.fold (fun functionTerm argument -> intern (KernelApplication(functionTerm, argument.term))) head.term
                    | KernelWhnfBlocked reason ->
                        blocked <- [reason]
                        closure.term
                let sourceRef = closureRef closure
                let receiptRef =
                    ContentDigest.ofText
                        "kernel-readback-receipt"
                        (ContentDigest.text sourceRef
                         + "|result=" + sprintf "%d:%d" resultTerm.generation resultTerm.slot
                         + "|generated=" + string generated
                         + "|eta=" + string etaExpansions
                         + "|quotient=" + string quotientReductions
                         + "|blocked=" + (blocked |> List.map kernelWhnfBlockedReasonStableText |> String.concat ","))
                resultTerm,
                arenaState,
                KernelWhnfEvaluation.environment evaluation,
                { sourceClosureRef = sourceRef
                  resultTerm = resultTerm
                  generatedNodes = generated
                  etaExpansions = etaExpansions
                  quotientReductions = quotientReductions
                  blockedReasons = blocked
                  receiptRef = receiptRef
                  closure = if List.isEmpty blocked then KernelReadbackClosed else KernelReadbackOpen blocked }

        type KernelDefEqResult =
            | KernelDefEqEqual
            | KernelDefEqNotEqual
            | KernelDefEqBlocked of KernelWhnfBlockedReason list
            | KernelDefEqConflict of Set<ContentDigest>

        let private kernelDefEqResultStableText = function
            | KernelDefEqEqual -> "equal"
            | KernelDefEqNotEqual -> "not_equal"
            | KernelDefEqBlocked reasons ->
                "blocked(" + (reasons |> List.map kernelWhnfBlockedReasonStableText |> String.concat ",") + ")"
            | KernelDefEqConflict digests ->
                "conflict(" + (digests |> Set.toList |> List.map ContentDigest.text |> String.concat ",") + ")"

        type KernelDefEqContext = private {
            environmentRevisionDigest : ContentDigest
            universeAssignmentDigest : ContentDigest
            transparency : KernelTransparency
        }

        module KernelDefEqContext =
            let create environmentRevisionText universeAssignmentText transparency =
                { environmentRevisionDigest = ContentDigest.ofText "kernel-environment-revision" environmentRevisionText
                  universeAssignmentDigest = ContentDigest.ofText "universe-assignment" universeAssignmentText
                  transparency = transparency }

        type KernelDefEqObligation = private {
            left : KernelClosure
            right : KernelClosure
            transparency : KernelTransparency
            expectedType : KernelTermId option
        }

        type KernelDefEqWorklistClosure =
            | KernelDefEqWorklistOpen of activePairs:int * suspendedPairs:int * blockedReasons:KernelWhnfBlockedReason list
            | KernelDefEqWorklistClosed of result:KernelDefEqResult

        let private kernelDefEqWorklistClosureStableText = function
            | KernelDefEqWorklistOpen(activePairs, suspendedPairs, blockedReasons) ->
                "open(active=" + string activePairs
                + "|suspended=" + string suspendedPairs
                + "|blocked=" + (blockedReasons |> List.map kernelWhnfBlockedReasonStableText |> String.concat ",") + ")"
            | KernelDefEqWorklistClosed result -> "closed(" + kernelDefEqResultStableText result + ")"

        type KernelDefEqOperationalDisposition =
            | KernelDefEqOperationalQueued
            | KernelDefEqOperationalSuspended
            | KernelDefEqOperationalRetiredEqual
            | KernelDefEqOperationalRetiredNotEqual
            | KernelDefEqOperationalRetiredConflict

        let private kernelDefEqOperationalDispositionStableText = function
            | KernelDefEqOperationalQueued -> "queued"
            | KernelDefEqOperationalSuspended -> "suspended"
            | KernelDefEqOperationalRetiredEqual -> "retired_equal"
            | KernelDefEqOperationalRetiredNotEqual -> "retired_not_equal"
            | KernelDefEqOperationalRetiredConflict -> "retired_conflict"

        type KernelDefEqOperationalReceipt = private {
            workUnitRef : ContentDigest
            admissionRef : ContentDigest
            disposition : KernelDefEqOperationalDisposition
            transitionRef : ContentDigest
            dependencyRefs : ContentDigest list
        }

        type KernelDefEqWorklistReceipt = private {
            operational : KernelDefEqOperationalReceipt
            rootRef : ContentDigest
            interactionNetRef : ContentDigest
            productivityProofRef : ContentDigest
            comparedPairs : int
            consumedActivePairs : int64
            resumedActivePairs : int64
            suspendedActivePairs : int
            normalizedSteps : int
            productiveNormalizationSteps : int
            readbackRefs : ContentDigest list
            etaExpansions : int
            quotientReductions : int
            maxDepth : int
            visitedPairs : int
            pendingPairs : int
            blockedReasons : KernelWhnfBlockedReason list
            blockedMetas : Set<int>
            metaContextRevision : int64
            dependencyRefs : ContentDigest list
            closure : KernelDefEqWorklistClosure
        }

        type KernelDefEqDecision = private {
            result : KernelDefEqResult
            receipt : KernelDefEqWorklistReceipt
        }

        module KernelDefEqOperationalReceipt =
            let workUnitRef receipt = receipt.workUnitRef
            let admissionRef receipt = receipt.admissionRef
            let disposition receipt = receipt.disposition
            let transitionRef receipt = receipt.transitionRef
            let dependencyRefs receipt = receipt.dependencyRefs

        module KernelDefEqDecision =
            let result decision = decision.result
            let receipt decision = decision.receipt
            let operational decision = decision.receipt.operational

        [<Struct>]
        type KernelDefEqDecisionKey = private KernelDefEqDecisionKey of ContentDigest

        [<Struct>]
        type KernelDefEqLineageId = private KernelDefEqLineageId of ContentDigest

        type KernelDefEqMemo = private {
            decisions : Map<KernelDefEqDecisionKey, ConfluentWorkCell<KernelDefEqDecision>>
            suspendedNets : Map<KernelDefEqLineageId, KernelInteractionNet>
        }


        // Five-round migration round  cutover: the old list-backed
        // KernelDefEq implementation remains quarantined as KernelDefEqLegacy.
        // This module is the only current authority and requires explicit wake
        // refs when a MetaContext assignment resumes suspended active pairs.
        module KernelDefEq =
            let emptyMemo = { decisions = Map.empty; suspendedNets = Map.empty }

            type KernelClosureIdentity = private {
                termGeneration : int
                termSlot : int
                environmentGeneration : int
                environmentSlot : int
            }

            let private closureIdentity (closure:KernelClosure) =
                { termGeneration = closure.term.generation
                  termSlot = closure.term.slot
                  environmentGeneration = closure.environment.generation
                  environmentSlot = closure.environment.slot }

            let private closureIdentityText identity =
                FastRuntimeFormat.format "%d:%d@%d:%d" [| box identity.termGeneration; box identity.termSlot; box identity.environmentGeneration; box identity.environmentSlot |]

            let private expectedTypeIdentityText (expectedType:KernelTermId option) =
                match expectedType with
                | None -> "expected:none"
                | Some term -> FastRuntimeFormat.format "expected:%d:%d" [| box term.generation; box term.slot |]

            let private lineageRef (KernelDefEqLineageId lineageRef) = lineageRef
            let private decisionRef (KernelDefEqDecisionKey decisionRef) = decisionRef

            let private obligationLineageKey (context:KernelDefEqContext) (obligation:KernelDefEqObligation) =
                let leftIdentity = closureIdentity obligation.left
                let rightIdentity = closureIdentity obligation.right
                let firstIdentity, secondIdentity = if compare leftIdentity rightIdentity <= 0 then leftIdentity, rightIdentity else rightIdentity, leftIdentity
                KernelDefEqLineageId (
                    ContentDigest.ofText
                        "kernel-defeq-lineage"
                        (closureIdentityText firstIdentity
                         + "|" + closureIdentityText secondIdentity
                         + "|" + expectedTypeIdentityText obligation.expectedType
                         + "|" + ContentDigest.text context.environmentRevisionDigest
                         + "|" + ContentDigest.text context.universeAssignmentDigest
                         + "|" + kernelTransparencyStableText context.transparency
                         + "|" + kernelTransparencyStableText obligation.transparency))

            let private obligationKey (metaContext:KernelMetaContext) (context:KernelDefEqContext) (obligation:KernelDefEqObligation) =
                let lineage = obligationLineageKey context obligation
                KernelDefEqDecisionKey (
                    ContentDigest.ofText
                        "kernel-defeq"
                        (ContentDigest.text (lineageRef lineage)
                         + "|meta_context=" + ContentDigest.text (KernelMetaContext.revisionDigest metaContext)))

            let private proofIrrelevant (arena:KernelArena) (obligation:KernelDefEqObligation) =
                match obligation.expectedType with
                | Some expectedType ->
                    match KernelArena.tryNode expectedType arena with
                    | Some(KernelSort KernelUniverseProp) -> true
                    | _ -> false
                | None -> false

            let private decisionStableText (decision:KernelDefEqDecision) =
                let receipt = decision.receipt
                FastRuntimeFormat.format "%s|operational_work=%s|operational_disposition=%s|operational_transition=%s|net=%s|proof=%s|pairs=%d|consumed=%d|resumed=%d|suspended=%d|normalization_steps=%d|productive_steps=%d|readback_refs=%s|eta_expansions=%d|quotient_reductions=%d|max_depth=%d|visited=%d|pending=%d|blocked_metas=%s|meta_revision=%d|dependency_refs=%s|closure=%s" [| box (kernelDefEqResultStableText decision.result); box (ContentDigest.text receipt.operational.workUnitRef); box (kernelDefEqOperationalDispositionStableText receipt.operational.disposition); box (ContentDigest.text receipt.operational.transitionRef); box (ContentDigest.text receipt.interactionNetRef); box (ContentDigest.text receipt.productivityProofRef); box receipt.comparedPairs; box receipt.consumedActivePairs; box receipt.resumedActivePairs; box receipt.suspendedActivePairs; box receipt.normalizedSteps; box receipt.productiveNormalizationSteps; box (receipt.readbackRefs |> List.map ContentDigest.text |> String.concat ","); box receipt.etaExpansions; box receipt.quotientReductions; box receipt.maxDepth; box receipt.visitedPairs; box receipt.pendingPairs; box (receipt.blockedMetas |> Set.toList |> List.map string |> String.concat ","); box receipt.metaContextRevision; box (receipt.dependencyRefs |> List.map ContentDigest.text |> String.concat ","); box (kernelDefEqWorklistClosureStableText receipt.closure) |]

            let decide
                (fuel:int)
                (arena:KernelArena)
                (environment:KernelEnvironment)
                (metaContext:KernelMetaContext)
                (context:KernelDefEqContext)
                (obligation:KernelDefEqObligation)
                (wakeRefs:ContentDigest list)
                (memo:KernelDefEqMemo)
                : KernelDefEqDecision * KernelDefEqMemo * KernelMetaContext =
                let leftQuoted, arenaAfterLeft, environmentAfterLeft, leftReadback =
                    KernelQuoteReadback.quote fuel KernelReadbackEtaLong arena environment metaContext obligation.left
                let rightQuoted, arenaAfterRight, environmentAfterRight, rightReadback =
                    KernelQuoteReadback.quote fuel KernelReadbackEtaLong arenaAfterLeft environmentAfterLeft metaContext obligation.right
                let arena = arenaAfterRight
                let environment = environmentAfterRight
                let obligation =
                    { obligation with
                        left = { obligation.left with term = leftQuoted }
                        right = { obligation.right with term = rightQuoted } }
                let readbackClosed =
                    match leftReadback.closure, rightReadback.closure with
                    | KernelReadbackClosed, KernelReadbackClosed -> true
                    | KernelReadbackOpen _, _
                    | _, KernelReadbackOpen _ -> false
                let baseKey = obligationKey metaContext context obligation
                let key =
                    KernelDefEqDecisionKey (
                        ContentDigest.ofText
                            "kernel-defeq-readback"
                            (ContentDigest.text (decisionRef baseKey)
                             + "|left=" + ContentDigest.text leftReadback.receiptRef
                             + "|right=" + ContentDigest.text rightReadback.receiptRef
                             + "|closed=" + string readbackClosed))
                let lineageKey = obligationLineageKey context obligation
                let rootRef = ContentDigest.ofText "kernel-defeq-root" (ContentDigest.text (lineageRef lineageKey))
                let operationalBinding =
                    StableBindingId.createSemantic
                        0
                        "kernel-cic"
                        (ContentDigest.text rootRef)
                        "defeq"
                        (ContentDigest.text (decisionRef key))
                        "kernel"
                let operationalWorkUnit =
                    WorkUnitIdOps.create<ElaboratedPhase,DefEqWorkKind>
                        operationalBinding
                        (int64 arena.generation)
                        (InstantiationIdOps.create (ContentDigest.text (lineageRef lineageKey)))
                        (BackendIdOps.create "kernel")
                let operationalWorkUnitRef =
                    ContentDigest.ofText
                        "kernel-defeq-operational-work"
                        (WorkUnitIdOps.digestText operationalWorkUnit)
                let operationalReceipt result dependencyRefs =
                    let disposition =
                        match result with
                        | KernelDefEqEqual -> KernelDefEqOperationalRetiredEqual
                        | KernelDefEqNotEqual -> KernelDefEqOperationalRetiredNotEqual
                        | KernelDefEqBlocked _ -> KernelDefEqOperationalSuspended
                        | KernelDefEqConflict _ -> KernelDefEqOperationalRetiredConflict
                    let admissionRef =
                        ContentDigest.ofText
                            "kernel-defeq-operational-admission"
                            (ContentDigest.text operationalWorkUnitRef)
                    let transitionRef =
                        ContentDigest.ofText
                            "kernel-defeq-operational-transition"
                            (ContentDigest.text operationalWorkUnitRef
                             + "|disposition=" + kernelDefEqOperationalDispositionStableText disposition
                             + "|dependencies=" + (dependencyRefs |> List.map ContentDigest.text |> String.concat ","))
                    { workUnitRef = operationalWorkUnitRef
                      admissionRef = admissionRef
                      disposition = disposition
                      transitionRef = transitionRef
                      dependencyRefs = dependencyRefs }
                let origin = KernelInteractionDefEq rootRef
                let metaIdsOfReasons reasons =
                    reasons
                    |> List.choose (function | KernelWhnfMetaVariable metaId -> Some metaId | _ -> None)
                    |> Set.ofList
                let rootNet =
                    match Map.tryFind lineageKey memo.suspendedNets with
                    | Some suspendedNet ->
                        wakeRefs |> List.fold (fun state wakeRef -> KernelInteractionNet.resume wakeRef state) suspendedNet
                    | None ->
                        KernelInteractionNet.empty arena.generation
                        |> KernelInteractionNet.enqueue
                            origin
                            obligation.left
                            obligation.right
                            obligation.expectedType
                            obligation.transparency
                            KernelInteractionRoot
                            0
                            Set.empty
                let emptyReceipt result blockedReasons =
                    let netReceipt = KernelInteractionNet.receipt rootNet
                    { result = result
                      receipt =
                        { operational = operationalReceipt result wakeRefs
                          rootRef = rootRef
                          interactionNetRef = netReceipt.netRef
                          productivityProofRef = netReceipt.proofRef
                          comparedPairs = 0
                          consumedActivePairs = netReceipt.consumedPairs
                          resumedActivePairs = netReceipt.resumedPairs
                          suspendedActivePairs = netReceipt.suspendedPairs
                          normalizedSteps = 0
                          productiveNormalizationSteps = 0
                          readbackRefs = [leftReadback.receiptRef; rightReadback.receiptRef]
                          etaExpansions = leftReadback.etaExpansions + rightReadback.etaExpansions
                          quotientReductions = leftReadback.quotientReductions + rightReadback.quotientReductions
                          maxDepth = 0
                          visitedPairs = 0
                          pendingPairs = netReceipt.activePairs
                          blockedReasons = blockedReasons
                          blockedMetas = metaIdsOfReasons blockedReasons
                          metaContextRevision = KernelMetaContext.revision metaContext
                          dependencyRefs = wakeRefs
                          closure = KernelDefEqWorklistOpen(netReceipt.activePairs, netReceipt.suspendedPairs, blockedReasons) } }
                match Map.tryFind key memo.decisions with
                | Some(WorkCellComplete receipt) when List.isEmpty wakeRefs -> receipt.value, memo, metaContext
                | Some(WorkCellConflict evidence) ->
                    emptyReceipt (KernelDefEqConflict(evidence |> Set.map snd)) [], memo, metaContext
                | _ ->
                    let budget = max 1 fuel
                    let mutable interactionNet = rootNet
                    let mutable blockedReasons : KernelWhnfBlockedReason list = []
                    let mutable finalResult : KernelDefEqResult option = None
                    let mutable environmentState = environment
                    let mutable metaContextState = metaContext
                    let mutable normalizedSteps = 0
                    let mutable productiveNormalizationSteps = 0
                    let mutable maxDepth = 0
                    let mutable dependencyRefs : ContentDigest list = wakeRefs

                    while Option.isNone finalResult
                          && KernelInteractionNet.activeCount interactionNet > 0
                          && KernelInteractionNet.consumedCount interactionNet < int64 budget do
                        match KernelInteractionNet.tryConsume interactionNet with
                        | None -> ()
                        | Some(pair, consumedNet) ->
                            interactionNet <- consumedNet
                            maxDepth <- max maxDepth pair.depth
                            let itemObligation =
                                { left = pair.left
                                  right = pair.right
                                  transparency = pair.transparency
                                  expectedType = pair.expectedType }
                            if proofIrrelevant arena itemObligation then ()
                            elif pair.left.term = pair.right.term && pair.left.environment = pair.right.environment then ()
                            else
                                let leftEvaluation = KernelWhnf.evaluate budget arena environmentState metaContextState pair.left
                                let rightEvaluation = KernelWhnf.evaluate budget arena (KernelWhnfEvaluation.environment leftEvaluation) metaContextState pair.right
                                environmentState <- KernelWhnfEvaluation.environment rightEvaluation
                                normalizedSteps <- normalizedSteps + KernelWhnfEvaluation.steps leftEvaluation + KernelWhnfEvaluation.steps rightEvaluation
                                productiveNormalizationSteps <-
                                    productiveNormalizationSteps
                                    + KernelWhnfEvaluation.productiveSteps leftEvaluation
                                    + KernelWhnfEvaluation.productiveSteps rightEvaluation

                                let mutable pairBlocked = false
                                let mutable pairBlockedMetas : Set<int> = Set.empty
                                let mutable pairWakeRefs : Set<ContentDigest> = Set.empty
                                let enqueue path left right expectedType =
                                    interactionNet <-
                                        KernelInteractionNet.enqueue
                                            origin
                                            left
                                            right
                                            expectedType
                                            pair.transparency
                                            path
                                            (pair.depth + 1)
                                            pair.dependencyRefs
                                            interactionNet
                                let enqueueTerms label leftEnvironment rightEnvironment pairs =
                                    pairs
                                    |> List.mapi (fun ordinal (leftTerm, rightTerm) -> ordinal, leftTerm, rightTerm)
                                    |> List.iter (fun (ordinal, leftTerm, rightTerm) ->
                                        enqueue
                                            (KernelInteractionChild(pair.path, KernelInteractionNodeField(label, ordinal)))
                                            { term = leftTerm; environment = leftEnvironment }
                                            { term = rightTerm; environment = rightEnvironment }
                                            None)
                                let recordBlocked reason =
                                    pairBlocked <- true
                                    blockedReasons <- reason :: blockedReasons
                                    match reason with
                                    | KernelWhnfMetaVariable metaId ->
                                        let wakeRef =
                                            KernelInteractionNet.resumptionEdgeRef
                                                (KernelInteractionNet.pairRef pair.pairId)
                                                metaId
                                                (KernelMetaContext.revision metaContextState)
                                        let dependency =
                                            { obligationRef = rootRef
                                              interactionPairRef = KernelInteractionNet.pairRef pair.pairId
                                              resumptionEdgeRef = wakeRef
                                              path = kernelInteractionPathStableText pair.path |> kernelMetaDependencyPathRefOfText
                                              metaIds = Set.singleton metaId
                                              registeredAtRevision = KernelMetaContext.revision metaContextState }
                                        metaContextState <- KernelMetaContext.registerBlocked dependency metaContextState
                                        pairBlockedMetas <- Set.add metaId pairBlockedMetas
                                        pairWakeRefs <- Set.add wakeRef pairWakeRefs
                                        dependencyRefs <- wakeRef :: dependencyRefs
                                    | _ -> ()

                                match KernelWhnfEvaluation.result leftEvaluation, KernelWhnfEvaluation.result rightEvaluation with
                                | KernelWhnfBlocked leftReason, KernelWhnfBlocked rightReason ->
                                    recordBlocked leftReason
                                    recordBlocked rightReason
                                | KernelWhnfBlocked reason, _
                                | _, KernelWhnfBlocked reason -> recordBlocked reason
                                | KernelWhnfNeutral(leftHead, leftArguments), KernelWhnfNeutral(rightHead, rightArguments) ->
                                    if leftArguments.Length <> rightArguments.Length then
                                        finalResult <- Some KernelDefEqNotEqual
                                    else
                                        enqueue (KernelInteractionChild(pair.path, KernelInteractionNeutralHead)) leftHead rightHead None
                                        List.zip leftArguments rightArguments
                                        |> List.iteri (fun ordinal (leftArgument, rightArgument) ->
                                            enqueue (KernelInteractionChild(pair.path, KernelInteractionNeutralArgument ordinal)) leftArgument rightArgument None)
                                | KernelWhnfValue leftValue, KernelWhnfValue rightValue ->
                                    match KernelArena.tryNode leftValue.term arena, KernelArena.tryNode rightValue.term arena with
                                    | None, _
                                    | _, None -> recordBlocked KernelWhnfUnknownTerm
                                    | Some(KernelBound leftIndex), Some(KernelBound rightIndex)
                                        when leftIndex = rightIndex && leftValue.environment = rightValue.environment -> ()
                                    | Some(KernelFree leftBinding), Some(KernelFree rightBinding)
                                        when leftBinding = rightBinding -> ()
                                    | Some(KernelMeta leftMeta), Some(KernelMeta rightMeta) when leftMeta = rightMeta ->
                                        recordBlocked (KernelWhnfMetaVariable leftMeta)
                                    | Some(KernelSort leftUniverse), Some(KernelSort rightUniverse)
                                        when leftUniverse = rightUniverse -> ()
                                    | Some(KernelConstant(leftBinding, leftUniverses)), Some(KernelConstant(rightBinding, rightUniverses))
                                        when leftBinding = rightBinding && leftUniverses = rightUniverses -> ()
                                    | Some(KernelLiteral leftLiteral), Some(KernelLiteral rightLiteral)
                                        when leftLiteral = rightLiteral -> ()
                                    | Some(KernelApplication(leftFunction, leftArgument)), Some(KernelApplication(rightFunction, rightArgument)) ->
                                        enqueueTerms "application" leftValue.environment rightValue.environment
                                            [leftFunction, rightFunction; leftArgument, rightArgument]
                                    | Some(KernelLambda(leftBinder, leftDomain, leftBody)), Some(KernelLambda(rightBinder, rightDomain, rightBody))
                                        when leftBinder = rightBinder ->
                                        enqueueTerms "lambda" leftValue.environment rightValue.environment
                                            [leftDomain, rightDomain; leftBody, rightBody]
                                    | Some(KernelForall(leftBinder, leftDomain, leftBody)), Some(KernelForall(rightBinder, rightDomain, rightBody))
                                        when leftBinder = rightBinder ->
                                        enqueueTerms "forall" leftValue.environment rightValue.environment
                                            [leftDomain, rightDomain; leftBody, rightBody]
                                    | Some(KernelLet(leftType, leftValueTerm, leftBody)), Some(KernelLet(rightType, rightValueTerm, rightBody)) ->
                                        enqueueTerms "let" leftValue.environment rightValue.environment
                                            [leftType, rightType; leftValueTerm, rightValueTerm; leftBody, rightBody]
                                    | Some(KernelConstructorValue(leftConstructor, leftFields)), Some(KernelConstructorValue(rightConstructor, rightFields))
                                        when leftConstructor = rightConstructor && leftFields.Length = rightFields.Length ->
                                        enqueueTerms "constructor" leftValue.environment rightValue.environment (List.zip leftFields rightFields)
                                    | Some(KernelRecursorApplication(leftRecursor, leftMotive, leftMajor, leftMinors)),
                                      Some(KernelRecursorApplication(rightRecursor, rightMotive, rightMajor, rightMinors))
                                        when leftRecursor = rightRecursor && leftMinors.Length = rightMinors.Length ->
                                        enqueueTerms "recursor" leftValue.environment rightValue.environment
                                            ((leftMotive, rightMotive) :: (leftMajor, rightMajor) :: List.zip leftMinors rightMinors)
                                    | Some(KernelProjection(leftStructure, leftOrdinal)), Some(KernelProjection(rightStructure, rightOrdinal))
                                        when leftOrdinal = rightOrdinal ->
                                        enqueueTerms "projection" leftValue.environment rightValue.environment [leftStructure, rightStructure]
                                    | Some(KernelQuotientValue(leftType, leftRelation, leftRepresentative)),
                                      Some(KernelQuotientValue(rightType, rightRelation, rightRepresentative)) ->
                                        enqueueTerms "quotient-value" leftValue.environment rightValue.environment
                                            [leftType, rightType; leftRelation, rightRelation; leftRepresentative, rightRepresentative]
                                    | Some(KernelQuotientLiftApplication(leftFunction, leftProof, leftQuotient)),
                                      Some(KernelQuotientLiftApplication(rightFunction, rightProof, rightQuotient)) ->
                                        enqueueTerms "quotient-lift" leftValue.environment rightValue.environment
                                            [leftFunction, rightFunction; leftProof, rightProof; leftQuotient, rightQuotient]
                                    | Some(KernelQuotientInductionApplication(leftMotive, leftProof, leftQuotient)),
                                      Some(KernelQuotientInductionApplication(rightMotive, rightProof, rightQuotient)) ->
                                        enqueueTerms "quotient-induction" leftValue.environment rightValue.environment
                                            [leftMotive, rightMotive; leftProof, rightProof; leftQuotient, rightQuotient]
                                    | _ -> finalResult <- Some KernelDefEqNotEqual
                                | _ -> finalResult <- Some KernelDefEqNotEqual

                                if pairBlocked then
                                    interactionNet <- KernelInteractionNet.suspend pair pairBlockedMetas pairWakeRefs interactionNet

                    let blockedReasons = blockedReasons |> List.distinct |> List.rev
                    if Option.isSome finalResult then
                        interactionNet <- KernelInteractionNet.close interactionNet
                    let netReceipt = KernelInteractionNet.receipt interactionNet
                    let result =
                        match finalResult with
                        | Some result -> result
                        | None when netReceipt.activePairs > 0 -> KernelDefEqBlocked [KernelWhnfFuelExhausted]
                        | None when netReceipt.suspendedPairs > 0 || not (List.isEmpty blockedReasons) -> KernelDefEqBlocked blockedReasons
                        | None -> KernelDefEqEqual
                    let closed =
                        netReceipt.activePairs = 0
                        && netReceipt.suspendedPairs = 0
                        && (match result with | KernelDefEqEqual | KernelDefEqNotEqual -> true | _ -> false)
                    let operationalDependencyRefs =
                        dependencyRefs |> List.distinct |> List.rev
                    let receipt =
                        { operational = operationalReceipt result operationalDependencyRefs
                          rootRef = rootRef
                          interactionNetRef = netReceipt.netRef
                          productivityProofRef = netReceipt.proofRef
                          comparedPairs = int netReceipt.consumedPairs
                          consumedActivePairs = netReceipt.consumedPairs
                          resumedActivePairs = netReceipt.resumedPairs
                          suspendedActivePairs = netReceipt.suspendedPairs
                          normalizedSteps = normalizedSteps
                          productiveNormalizationSteps = productiveNormalizationSteps
                          readbackRefs = [leftReadback.receiptRef; rightReadback.receiptRef]
                          etaExpansions = leftReadback.etaExpansions + rightReadback.etaExpansions
                          quotientReductions = leftReadback.quotientReductions + rightReadback.quotientReductions
                          maxDepth = maxDepth
                          visitedPairs = int netReceipt.consumedPairs
                          pendingPairs = netReceipt.activePairs
                          blockedReasons = blockedReasons
                          blockedMetas = metaIdsOfReasons blockedReasons
                          metaContextRevision = KernelMetaContext.revision metaContextState
                          dependencyRefs = operationalDependencyRefs
                          closure =
                            if closed then KernelDefEqWorklistClosed result
                            else KernelDefEqWorklistOpen(netReceipt.activePairs, netReceipt.suspendedPairs, blockedReasons) }
                    let decision = { result = result; receipt = receipt }
                    let binding = StableBindingId.create 0 (ContentDigest.text (decisionRef key))
                    let cell = ConfluentWorkCell.complete binding netReceipt.consumedPairs (decisionStableText decision) decision
                    let suspendedNets =
                        if closed then Map.remove lineageKey memo.suspendedNets
                        elif netReceipt.suspendedPairs > 0 then Map.add lineageKey interactionNet memo.suspendedNets
                        else memo.suspendedNets
                    decision,
                    { decisions = Map.add key cell memo.decisions
                      suspendedNets = suspendedNets },
                    metaContextState

        type KernelUniverseConstraintRelation =
            | KernelUniverseEqual
            | KernelUniverseLessOrEqual

        let private kernelUniverseConstraintRelationStableText = function
            | KernelUniverseEqual -> "equal"
            | KernelUniverseLessOrEqual -> "less_or_equal"

        type KernelUniverseConstraint = private {
            left : KernelUniverse
            relation : KernelUniverseConstraintRelation
            right : KernelUniverse
            origin : ContentDigest
        }

        type KernelUniverseSolution =
            | KernelUniverseSolved of assignments:Map<int, KernelUniverse>
            | KernelUniverseBlocked of metas:Set<int> * constraints:KernelUniverseConstraint list
            | KernelUniverseInconsistent of constraintRef:ContentDigest

        module KernelUniverseSolver =
            let private constraintRef constraintItem =
                ContentDigest.ofText
                    "universe-constraint"
                    (kernelUniverseStableText constraintItem.left
                     + "|" + kernelUniverseConstraintRelationStableText constraintItem.relation
                     + "|" + kernelUniverseStableText constraintItem.right
                     + "|" + ContentDigest.text constraintItem.origin)

            let create relation left right origin =
                { left = left
                  relation = relation
                  right = right
                  origin = ContentDigest.ofText "universe-origin" origin }

            let rec private substitute assignments universe =
                match universe with
                | KernelUniverseMeta meta -> Map.tryFind meta assignments |> Option.defaultValue universe
                | KernelUniverseSucc inner -> KernelUniverseSucc(substitute assignments inner)
                | KernelUniverseMax(left, right) -> KernelUniverseMax(substitute assignments left, substitute assignments right)
                | KernelUniverseIMax(left, right) -> KernelUniverseIMax(substitute assignments left, substitute assignments right)
                | other -> other

            let rec private collectMetas universe =
                match universe with
                | KernelUniverseMeta meta -> Set.singleton meta
                | KernelUniverseSucc inner -> collectMetas inner
                | KernelUniverseMax(left, right)
                | KernelUniverseIMax(left, right) -> Set.union (collectMetas left) (collectMetas right)
                | _ -> Set.empty

            let solve constraints =
                let mutable assignments : Map<int, KernelUniverse> = Map.empty
                let mutable blocked : KernelUniverseConstraint list = []
                let mutable inconsistent : ContentDigest option = None
                for constraintItem in constraints do
                    if Option.isNone inconsistent then
                        let left = substitute assignments constraintItem.left
                        let right = substitute assignments constraintItem.right
                        match constraintItem.relation, left, right with
                        | KernelUniverseEqual, KernelUniverseMeta meta, value
                        | KernelUniverseEqual, value, KernelUniverseMeta meta ->
                            if Set.contains meta (collectMetas value) then inconsistent <- Some(constraintRef constraintItem)
                            else assignments <- Map.add meta value assignments
                        | KernelUniverseEqual, leftValue, rightValue when leftValue = rightValue -> ()
                        | KernelUniverseLessOrEqual, KernelUniverseZero, _ -> ()
                        | KernelUniverseLessOrEqual, KernelUniverseProp, _ -> ()
                        | KernelUniverseLessOrEqual, leftValue, rightValue when leftValue = rightValue -> ()
                        | _, leftValue, rightValue when not (Set.isEmpty (Set.union (collectMetas leftValue) (collectMetas rightValue))) ->
                            blocked <- constraintItem :: blocked
                        | _ -> inconsistent <- Some(constraintRef constraintItem)
                match inconsistent with
                | Some receipt -> KernelUniverseInconsistent receipt
                | None when List.isEmpty blocked -> KernelUniverseSolved assignments
                | None ->
                    let metas =
                        blocked
                        |> List.fold (fun state constraintItem ->
                            Set.union state (Set.union (collectMetas constraintItem.left) (collectMetas constraintItem.right))) Set.empty
                    KernelUniverseBlocked(metas, List.rev blocked)

        [<Struct>]
        type KernelEnvironmentRevision = private | KernelEnvironmentRevision of ContentDigest

        type KernelDeclarationCommitError =
            | KernelDeclarationDuplicate of StableBindingId
            | KernelDeclarationContainsMeta of StableBindingId
            | KernelDeclarationMissingDependency of declaration:StableBindingId * dependency:StableBindingId
            | KernelDeclarationForeignGeneration of StableBindingId
            | KernelDeclarationMissingPositivityCertificate of StableBindingId
            | KernelDeclarationPositivityCertificateMismatch of declaration:StableBindingId * certificateRef:ContentDigest

        type KernelDeclarationEnvironment = private {
            generation : int
            revision : KernelEnvironmentRevision
            declarations : Map<StableBindingId, KernelDeclaration>
            dependencyDag : Map<StableBindingId, Set<StableBindingId>>
        }

        module KernelDeclaration =
            let create declarationId kind typeTerm valueTerm universeParameters dependencies =
                { declarationId = declarationId
                  kind = kind
                  typeTerm = typeTerm
                  valueTerm = valueTerm
                  universeParameters = universeParameters
                  dependencies = Set.ofList dependencies
                  positivityCertificate = None }

            let withPositivity certificate declaration =
                { declaration with positivityCertificate = Some certificate }

            let id declaration = declaration.declarationId
            let kind declaration = declaration.kind
            let typeTerm declaration = declaration.typeTerm
            let valueTerm declaration = declaration.valueTerm

        module KernelDeclarationEnvironment =
            let private emptyRevision = KernelEnvironmentRevision(ContentDigest.ofText "kernel-environment" "empty")

            let empty (generation:int) : KernelDeclarationEnvironment =
                { generation = generation
                  revision = emptyRevision
                  declarations = Map.empty
                  dependencyDag = Map.empty }

            let private declarationKey declaration = declaration.declarationId

            let private revisionOf declarations =
                declarations
                |> Map.toList
                |> List.map (fst >> StableBindingId.text)
                |> String.concat "|"
                |> ContentDigest.ofText "kernel-environment-revision"
                |> KernelEnvironmentRevision

            let private termContainsMeta arena root =
                let mutable pending = [root]
                let mutable visited : Set<KernelTermId> = Set.empty
                let mutable containsMeta = false
                while not containsMeta && not (List.isEmpty pending) do
                    let current = List.head pending
                    pending <- List.tail pending
                    if not (Set.contains current visited) then
                        visited <- Set.add current visited
                        match KernelArena.tryNode current arena with
                        | Some(KernelMeta _) -> containsMeta <- true
                        | Some(KernelApplication(fnTerm, argument)) -> pending <- fnTerm :: argument :: pending
                        | Some(KernelLambda(_, domain, body))
                        | Some(KernelForall(_, domain, body)) -> pending <- domain :: body :: pending
                        | Some(KernelLet(typeTerm, value, body)) -> pending <- typeTerm :: value :: body :: pending
                        | Some(KernelConstructorValue(_, fields)) -> pending <- fields @ pending
                        | Some(KernelRecursorApplication(_, motive, major, minors)) -> pending <- motive :: major :: (minors @ pending)
                        | Some(KernelProjection(structureTerm, _)) -> pending <- structureTerm :: pending
                        | Some(KernelQuotientValue(typeTerm, relationTerm, representative)) ->
                            pending <- typeTerm :: relationTerm :: representative :: pending
                        | Some(KernelQuotientLiftApplication(functionTerm, proofTerm, quotientTerm)) ->
                            pending <- functionTerm :: proofTerm :: quotientTerm :: pending
                        | Some(KernelQuotientInductionApplication(motive, proofTerm, quotientTerm)) ->
                            pending <- motive :: proofTerm :: quotientTerm :: pending
                        | _ -> ()
                containsMeta

            let tryCloseTerm arena term =
                if termContainsMeta arena term then Error "kernel_term_contains_metavariable"
                else Ok(KernelTerm.ofId term)

            let tryFind declarationId environment = Map.tryFind declarationId environment.declarations

            let commit arena declaration environment =
                let key = declarationKey declaration
                let typeTermId = KernelTerm.id declaration.typeTerm
                let valueTermId = declaration.valueTerm |> Option.map KernelTerm.id
                if typeTermId.generation <> environment.generation then
                    Error(KernelDeclarationForeignGeneration declaration.declarationId)
                elif Map.containsKey key environment.declarations then
                    Error(KernelDeclarationDuplicate declaration.declarationId)
                elif termContainsMeta arena typeTermId
                     || (valueTermId |> Option.exists (termContainsMeta arena)) then
                    Error(KernelDeclarationContainsMeta declaration.declarationId)
                elif declaration.kind = KernelInductive then
                    match declaration.positivityCertificate with
                    | None -> Error(KernelDeclarationMissingPositivityCertificate declaration.declarationId)
                    | Some certificate when not (KernelPositivity.isClosed certificate)
                                             || KernelPositivity.inductive certificate <> declaration.declarationId ->
                        Error(KernelDeclarationPositivityCertificateMismatch(declaration.declarationId, KernelPositivity.certificateRef certificate))
                    | Some _ ->
                        match declaration.dependencies |> Set.toList |> List.tryFind (fun dependency -> not (Map.containsKey dependency environment.declarations)) with
                        | Some dependency -> Error(KernelDeclarationMissingDependency(declaration.declarationId, dependency))
                        | None ->
                            let declarations = Map.add key declaration environment.declarations
                            let dependencies = declaration.dependencies
                            let dependencyDag = Map.add key dependencies environment.dependencyDag
                            Ok { environment with declarations = declarations; dependencyDag = dependencyDag; revision = revisionOf declarations }
                else
                    match declaration.dependencies |> Set.toList |> List.tryFind (fun dependency -> not (Map.containsKey dependency environment.declarations)) with
                    | Some dependency -> Error(KernelDeclarationMissingDependency(declaration.declarationId, dependency))
                    | None ->
                        let declarations = Map.add key declaration environment.declarations
                        let dependencies = declaration.dependencies
                        Ok {
                            environment with
                                revision = revisionOf declarations
                                declarations = declarations
                                dependencyDag = Map.add key dependencies environment.dependencyDag
                        }

            let revision environment = environment.revision
            let declarationCount environment = environment.declarations.Count


        type PortableRuntimeConformanceBoundary =
            | PortableRuntimeInProcessOnly

        type RestoredSubstrateLaw =
            | RestoredRuntimeContractVerified
            | RestoredRuntimeAdaptersDifferentiallyVerified
            | RestoredRuntimeOneShotExactOnce
            | RestoredRuntimeChoiceCancelsLosers
            | RestoredRuntimeClockMonotonic
            | RestoredScopeRejectsEarlyClose
            | RestoredPhaseProgressExactWhenClosed
            | RestoredArenaInterningIdempotent
            | RestoredDefEqReflexive
            | RestoredDefEqAssignedMetaResolves
            | RestoredMetaOccursCheckRejects
            | RestoredMetaAssignmentWakesObligation
            | RestoredUniverseOccursCheckRejects
            | RestoredDeclarationCommitRejectsMeta
            | RestoredPositivityRejectsNegativeOccurrence
            | RestoredPositivityAdmitsPositiveOccurrence
            | RestoredInductiveCommitAcceptsCertified
            | RestoredQuotientLiftComputesRepresentative
            | RestoredEtaReadbackCloses
            | RestoredPhaseHeavyTailEtaAvailable
            | RestoredInteractionNetConsumesActivePair
            | RestoredInteractionNetSuspendsMeta
            | RestoredInteractionNetResumesWake
            | RestoredHvmPortLinearityRejectsDuplicate
            | RestoredHvmRewriteAlgebraClassifiesActivePairs
            | RestoredSpecializationDependencyPlanClosed

        let private restoredSubstrateLawStableText = function
            | RestoredRuntimeContractVerified -> "runtime-contract-verified"
            | RestoredRuntimeAdaptersDifferentiallyVerified -> "runtime-adapters-differentially-verified"
            | RestoredRuntimeOneShotExactOnce -> "runtime-one-shot-exact-once"
            | RestoredRuntimeChoiceCancelsLosers -> "runtime-choice-cancels-losers"
            | RestoredRuntimeClockMonotonic -> "runtime-clock-monotonic"
            | RestoredScopeRejectsEarlyClose -> "scope-rejects-early-close"
            | RestoredPhaseProgressExactWhenClosed -> "phase-progress-exact-when-closed"
            | RestoredArenaInterningIdempotent -> "arena-interning-idempotent"
            | RestoredDefEqReflexive -> "defeq-reflexive"
            | RestoredDefEqAssignedMetaResolves -> "defeq-assigned-meta-resolves"
            | RestoredMetaOccursCheckRejects -> "meta-occurs-check-rejects"
            | RestoredMetaAssignmentWakesObligation -> "meta-assignment-wakes-obligation"
            | RestoredUniverseOccursCheckRejects -> "universe-occurs-check-rejects"
            | RestoredDeclarationCommitRejectsMeta -> "declaration-commit-rejects-meta"
            | RestoredPositivityRejectsNegativeOccurrence -> "positivity-rejects-negative-occurrence"
            | RestoredPositivityAdmitsPositiveOccurrence -> "positivity-admits-positive-occurrence"
            | RestoredInductiveCommitAcceptsCertified -> "inductive-commit-accepts-certified"
            | RestoredQuotientLiftComputesRepresentative -> "quotient-lift-computes-representative"
            | RestoredEtaReadbackCloses -> "eta-readback-closes"
            | RestoredPhaseHeavyTailEtaAvailable -> "phase-heavy-tail-eta-available"
            | RestoredInteractionNetConsumesActivePair -> "interaction-net-consumes-active-pair"
            | RestoredInteractionNetSuspendsMeta -> "interaction-net-suspends-meta"
            | RestoredInteractionNetResumesWake -> "interaction-net-resumes-wake"
            | RestoredHvmPortLinearityRejectsDuplicate -> "hvm-port-linearity-rejects-duplicate"
            | RestoredHvmRewriteAlgebraClassifiesActivePairs -> "hvm-rewrite-algebra-classifies-active-pairs"
            | RestoredSpecializationDependencyPlanClosed -> "specialization-dependency-plan-closed"

        type RestoredSubstrateConformanceReceipt = private {
            runtimeBoundary : PortableRuntimeConformanceBoundary
            runtimeDifferentialTraceCount : int
            requiredLaws : Set<RestoredSubstrateLaw>
            satisfiedLaws : Set<RestoredSubstrateLaw>
            receiptRef : ContentDigest
        }

        let restoredSubstrateConformanceReceipt () =
            let scope = FiberScope.create "restored-substrate-conformance"
            let fiber, scopeWithChild = FiberScope.fork scope
            let earlyCloseRejected = FiberScope.closeOpen scopeWithChild |> Result.isError
            let retiredScope =
                match FiberScope.retire fiber scopeWithChild with
                | Ok value -> value
                | Error FiberScopeForeignChild -> invalidOp "fiber_scope_foreign_child"
                | Error FiberScopeChildNotLive -> invalidOp "fiber_scope_child_not_live"
            let _closedScope = FiberScope.closeOpen retiredScope

            let oneShotId = PortableRuntimeModel.resource "conformance-one-shot"
            let _, runtimeState1 = PortableRuntimeModel.apply (RuntimeCreateOneShot oneShotId) PortableRuntimeModel.empty
            let firstFill, runtimeState2 =
                PortableRuntimeModel.apply
                    (RuntimeFillOneShot(oneShotId, ContentDigest.ofText "payload" "first"))
                    runtimeState1
            let secondFill, _ =
                PortableRuntimeModel.apply
                    (RuntimeFillOneShot(oneShotId, ContentDigest.ofText "payload" "second"))
                    runtimeState2
            let runtimeOneShotExactOnce = firstFill.accepted && not secondFill.accepted

            let choiceId = PortableRuntimeModel.resource "conformance-choice"
            let _, runtimeState3 = PortableRuntimeModel.apply (RuntimeCreateChoice(choiceId, 3)) runtimeState2
            let choiceCommit, runtimeState4 = PortableRuntimeModel.apply (RuntimeCommitChoice(choiceId, 1)) runtimeState3
            let runtimeChoiceCancelsLosers =
                choiceCommit.accepted
                && (match PortableRuntimeModel.tryChoice choiceId runtimeState4 with
                    | Some(PortableChoiceCommitted(1, losers)) -> losers = Set.ofList [0; 2]
                    | _ -> false)

            let clockAdvance, runtimeState5 = PortableRuntimeModel.apply (RuntimeAdvanceMonotonicClock 10L) runtimeState4
            let clockRegression, _ = PortableRuntimeModel.apply (RuntimeAdvanceMonotonicClock 9L) runtimeState5
            let runtimeClockMonotonic = clockAdvance.accepted && not clockRegression.accepted

            let semanticZero = Measured.zero<SemanticCostUnit>
            let semanticTen = Measured.create<SemanticCostUnit> "semanticTen" 10L
            let semanticHundred = Measured.create<SemanticCostUnit> "semanticHundred" 100L
            let astHundred = Measured.create<AstCostUnit> "astHundred" 100L
            let wallMs value = Measured.create<WallTimeUnit> "wallMs" value
            let phaseBook =
                PhaseProgressBook.empty
                |> PhaseProgressBook.setPhase
                    WorkParse
                    semanticTen
                    semanticTen
                    semanticZero
                    semanticZero
                    semanticZero
                    None
                |> PhaseProgressBook.closeDiscovery WorkParse
            let phaseExact =
                PhaseProgressBook.project WorkParse phaseBook
                |> Option.exists (fun projection -> projection.progress.exact && BasisPoints.value projection.progress.midBp = 10000L)
            let heavyTailBook =
                PhaseProgressBook.empty
                |> PhaseProgressBook.setPhase
                    WorkSpecialize
                    semanticTen
                    semanticHundred
                    semanticZero
                    semanticZero
                    semanticZero
                    None
                |> PhaseProgressBook.seedStatic
                    WorkSpecialize
                    astHundred
                    (Some semanticHundred)
                    "conformance-static-seed"
                    true
                |> PhaseProgressBook.observeDuration WorkSpecialize (wallMs 234L)
                |> PhaseProgressBook.observeDuration WorkSpecialize (wallMs 703L)
                |> PhaseProgressBook.observeDuration WorkSpecialize (wallMs 46453L)
                |> PhaseProgressBook.observeDuration WorkSpecialize (wallMs 57141L)
            let phaseHeavyTailEtaAvailable =
                PhaseProgressBook.project WorkSpecialize heavyTailBook
                |> Option.exists (fun projection ->
                    match projection.etaP50, projection.etaP90 with
                    | Some p50, Some p90 ->
                        projection.durationSampleCount = 4L
                        && Measured.value p90 >= Measured.value p50
                        && Measured.value p50 > 0L
                    | _ -> false)

            let arena0 = KernelArena.empty 1
            let sortNode = KernelSort KernelUniverseProp
            let term1, arena1 = KernelArena.intern sortNode arena0
            let term2, arena2 = KernelArena.intern sortNode arena1
            let metaTerm, arena3 = KernelArena.intern (KernelMeta 7) arena2
            let selfMetaTerm, arena4 = KernelArena.intern (KernelMeta 8) arena3
            let inductiveId = StableBindingId.create 1 "conformance-inductive"
            let recursiveTerm, arena5 = KernelArena.intern (KernelConstant(inductiveId, [])) arena4
            let negativeConstructorType, arena6 =
                KernelArena.intern (KernelForall(KernelBinderExplicit, recursiveTerm, term1)) arena5
            let boundZero, arena7 = KernelArena.intern (KernelBound 0) arena6
            let identityFunction, arena8 =
                KernelArena.intern (KernelLambda(KernelBinderExplicit, term1, boundZero)) arena7
            let quotientValue, arena9 =
                KernelArena.intern (KernelQuotientValue(term1, term1, term1)) arena8
            let quotientLift, arena10 =
                KernelArena.intern (KernelQuotientLiftApplication(identityFunction, term1, quotientValue)) arena9
            let structureConstructor = StableBindingId.create 1 "conformance-structure"
            let structureValue, arenaFinal =
                KernelArena.intern (KernelConstructorValue(structureConstructor, [term1])) arena10
            let positivityRejectsNegativeOccurrence =
                match KernelPositivity.certify arenaFinal inductiveId [negativeConstructorType] with
                | Error(KernelNegativeOccurrence _) -> true
                | _ -> false
            let positiveCertificateResult = KernelPositivity.certify arenaFinal inductiveId [recursiveTerm]
            let positivityAdmitsPositiveOccurrence =
                match positiveCertificateResult with
                | Ok certificate -> KernelPositivity.isClosed certificate
                | Error _ -> false
            let environment = KernelEnvironment.empty 1
            let rootEnvironment = KernelEnvironment.root environment
            let closure = { term = term1; environment = rootEnvironment }
            let metaClosure = { term = metaTerm; environment = rootEnvironment }
            let selfMetaClosure = { term = selfMetaTerm; environment = rootEnvironment }
            let quotientClosure = { term = quotientLift; environment = rootEnvironment }
            let structureClosure = { term = structureValue; environment = rootEnvironment }
            let quotientEvaluation = KernelWhnf.evaluate 32 arenaFinal environment (KernelMetaContext.empty 1) quotientClosure
            let quotientLiftComputesRepresentative =
                match KernelWhnfEvaluation.result quotientEvaluation with
                | KernelWhnfValue value -> value.term = term1
                | _ -> false
            let _, _, _, etaReadbackReceipt =
                KernelQuoteReadback.quote 32 KernelReadbackEtaLong arenaFinal environment (KernelMetaContext.empty 1) structureClosure
            let etaReadbackCloses =
                match etaReadbackReceipt.closure with
                | KernelReadbackClosed -> etaReadbackReceipt.etaExpansions = 1
                | KernelReadbackOpen _ -> false
            let obligation = { left = closure; right = closure; transparency = KernelTransparencyReducible; expectedType = None }
            let metaObligation = { left = metaClosure; right = closure; transparency = KernelTransparencyReducible; expectedType = None }
            let defEqContext = KernelDefEqContext.create "empty" "empty" KernelTransparencyReducible
            let metaContext0 = KernelMetaContext.empty 1
            let defEq, _, _ =
                KernelDefEq.decide 32 arenaFinal environment metaContext0 defEqContext obligation [] KernelDefEq.emptyMemo
            let blockedMetaDecision, blockedMetaMemo, blockedMetaContext =
                KernelDefEq.decide 32 arenaFinal environment metaContext0 defEqContext metaObligation [] KernelDefEq.emptyMemo
            let tryNode term = KernelArena.tryNode term arenaFinal
            let assignedMetaContext, metaAssignmentWakesObligation, metaWakeRefs =
                match KernelMetaContext.assign tryNode 7 closure blockedMetaContext with
                | Ok(context, receipt) ->
                    let wakes = receipt.wokenObligations |> List.map (fun obligation -> obligation.resumptionEdgeRef)
                    context, not (List.isEmpty wakes), wakes
                | Error _ -> blockedMetaContext, false, []
            let resolvedMetaDecision, _, _ =
                KernelDefEq.decide 32 arenaFinal environment assignedMetaContext defEqContext metaObligation metaWakeRefs blockedMetaMemo
            let defEqAssignedMetaResolves =
                KernelDefEqDecision.result blockedMetaDecision = KernelDefEqBlocked [KernelWhnfMetaVariable 7]
                && KernelDefEqDecision.result resolvedMetaDecision = KernelDefEqEqual
            let metaOccursCheckRejects =
                match KernelMetaContext.assign tryNode 8 selfMetaClosure metaContext0 with
                | Error(KernelMetaOccursCheckFailed(metaId, dependencies)) -> metaId = 8 && Set.contains 8 dependencies
                | _ -> false

            let occursConstraint =
                KernelUniverseSolver.create
                    KernelUniverseEqual
                    (KernelUniverseMeta 1)
                    (KernelUniverseSucc(KernelUniverseMeta 1))
                    "occurs-check"
            let universeOccursRejected =
                match KernelUniverseSolver.solve [occursConstraint] with
                | KernelUniverseInconsistent _ -> true
                | _ -> false

            let declarationId = StableBindingId.create 1 "meta-declaration"
            let metaDeclaration = KernelDeclaration.create declarationId KernelDefinition (KernelTerm.ofId metaTerm) None [] []
            let declarationCommitRejectsMeta =
                match KernelDeclarationEnvironment.commit arenaFinal metaDeclaration (KernelDeclarationEnvironment.empty 1) with
                | Error(KernelDeclarationContainsMeta rejected) when rejected = declarationId -> true
                | _ -> false
            let inductiveCommitAcceptsCertified =
                match positiveCertificateResult with
                | Error _ -> false
                | Ok certificate ->
                    let inductiveDeclaration =
                        KernelDeclaration.create inductiveId KernelInductive (KernelTerm.ofId term1) None [] []
                        |> KernelDeclaration.withPositivity certificate
                    match KernelDeclarationEnvironment.commit arenaFinal inductiveDeclaration (KernelDeclarationEnvironment.empty 1) with
                    | Ok _ -> true
                    | Error _ -> false

            let runtimeDifferentials =
                // Conformance is in-process. Cross-runtime host receipts belong to
                // separate backend tests, not compiler startup or Supervisor self-probes.
                PortableRuntimeTrace.differentialReceipts RuntimeBackendHopac
            let runtimeDifferentialTraceCount = runtimeDifferentials.Length
            let runtimeDifferentialsVerified = runtimeDifferentials |> List.forall (fun receipt -> receipt.verified)

            let interactionRootRef = ContentDigest.ofText "conformance-interaction-root" "defeq"
            let interactionOrigin = KernelInteractionDefEq interactionRootRef
            let activePairNet =
                KernelInteractionNet.empty 1
                |> KernelInteractionNet.enqueue
                    interactionOrigin
                    closure
                    closure
                    None
                    KernelTransparencyReducible
                    (KernelInteractionChild(KernelInteractionRoot, KernelInteractionNodeField("conformance-active", 0)))
                    0
                    Set.empty
            let interactionNetConsumesActivePair, activePairProofRef =
                match KernelInteractionNet.tryConsume activePairNet with
                | Some(_, consumedNet) ->
                    let receipt = KernelInteractionNet.receipt consumedNet
                    receipt.consumedPairs = 1L && receipt.activePairs = 0, receipt.proofRef
                | None -> false, ContentDigest.ofText "missing-interaction-proof" "active-pair"

            let metaPairNet =
                KernelInteractionNet.empty 1
                |> KernelInteractionNet.enqueue
                    interactionOrigin
                    metaClosure
                    closure
                    None
                    KernelTransparencyReducible
                    (KernelInteractionChild(KernelInteractionRoot, KernelInteractionNodeField("conformance-meta", 0)))
                    0
                    Set.empty
            let interactionNetSuspendsMeta, interactionNetResumesWake, metaWakeProofRef =
                match KernelInteractionNet.tryConsume metaPairNet with
                | Some(pair, consumedNet) ->
                    let wakeRef = KernelInteractionNet.resumptionEdgeRef (KernelInteractionNet.pairRef pair.pairId) 7 0L
                    let suspendedNet =
                        KernelInteractionNet.suspend
                            pair
                            (Set.singleton 7)
                            (Set.singleton wakeRef)
                            consumedNet
                    let suspendedReceipt = KernelInteractionNet.receipt suspendedNet
                    let resumedNet = KernelInteractionNet.resume wakeRef suspendedNet
                    let resumedReceipt = KernelInteractionNet.receipt resumedNet
                    suspendedReceipt.suspendedPairs = 1,
                    resumedReceipt.suspendedPairs = 0 && resumedReceipt.activePairs = 1 && resumedReceipt.resumedPairs = 1L,
                    resumedReceipt.proofRef
                | None ->
                    false,
                    false,
                    ContentDigest.ofText "missing-interaction-proof" "meta-wake"

            let specializationIdentity =
                StableBindingId.createSemantic
                    0
                    "conformance"
                    "join-point"
                    "conformance:0"
                    "join-point-specialization"
                    "host"
            let specializationOwner =
                StableBindingId.createSemantic
                    0
                    "conformance"
                    "join-point-owner"
                    "conformance:0"
                    "owner"
                    "portable-runtime"
            let specializationWorkUnit =
                WorkUnitIdOps.create<ElaboratedPhase,JoinPointWorkKind>
                    specializationIdentity
                    1L
                    (InstantiationIdOps.create "conformance")
                    (BackendIdOps.create "host")
            let openSpecializationPlan =
                JoinPointSpecializationPlan.create specializationWorkUnit specializationOwner 1L "conformance"
                |> JoinPointSpecializationPlan.attach SpecializationDefEqProof activePairProofRef
                |> JoinPointSpecializationPlan.attach SpecializationMetaWake metaWakeProofRef
            let specializationLoweringBoundaryRef =
                ContentDigest.ofText "specialization-lowering-boundary" "conformance"
            let specializationPlan, specializationInteractionReceipt =
                JoinPointSpecializationPlan.lowerPureGraph
                    specializationLoweringBoundaryRef
                    openSpecializationPlan
            let specializationDependencyPlanClosed =
                JoinPointSpecializationPlan.isClosed specializationPlan
                && SpecializationInteractionReceipt.closed specializationInteractionReceipt
                && SpecializationInteractionReceipt.activePairsAfter specializationInteractionReceipt = 0

            let hvmNodeA = KernelHvmPortLinearity.node 1
            let hvmNodeB = KernelHvmPortLinearity.node 2
            let hvmNodeC = KernelHvmPortLinearity.node 3
            let hvmPrincipalA = KernelHvmPortLinearity.port hvmNodeA KernelHvmPrincipal
            let hvmDuplicateWires =
                [ KernelHvmPortLinearity.wire hvmPrincipalA (KernelHvmPortLinearity.port hvmNodeB KernelHvmPrincipal)
                  KernelHvmPortLinearity.wire hvmPrincipalA (KernelHvmPortLinearity.port hvmNodeC KernelHvmPrincipal) ]
            let hvmLinearityReceipt =
                KernelHvmPortLinearity.validateWithReceipt [ hvmNodeA; hvmNodeB; hvmNodeC ] hvmDuplicateWires
            let hvmPortLinearityRejectsDuplicate =
                not (KernelHvmPortLinearity.isLinear hvmLinearityReceipt)
                && KernelHvmPortLinearity.errorCount hvmLinearityReceipt > 0
                && not (System.String.IsNullOrWhiteSpace (KernelHvmPortLinearity.proofRef hvmLinearityReceipt |> ContentDigest.text))

            let hvmReferenceBinding =
                StableBindingId.createSemantic 0 "hvm-conformance" "reference" "conformance" "unspecialized" "host"
            let hvmAnnihilatePlan =
                KernelHvmRewrite.classify hvmNodeA (KernelHvmConstructor 7) hvmNodeB (KernelHvmConstructor 7)
            let hvmCommutePlan =
                KernelHvmRewrite.classify hvmNodeA (KernelHvmConstructor 7) hvmNodeB (KernelHvmDuplicator 7)
            let hvmErasePlan =
                KernelHvmRewrite.classify hvmNodeA KernelHvmErase hvmNodeB (KernelHvmConstructor 7)
            let hvmDereferencePlan =
                KernelHvmRewrite.classify hvmNodeA (KernelHvmReference hvmReferenceBinding) hvmNodeB KernelHvmRoot
            let hvmRewriteAlgebraClassifiesActivePairs =
                KernelHvmRewrite.rewrite hvmAnnihilatePlan = KernelHvmAnnihilate(hvmNodeA, hvmNodeB)
                && KernelHvmRewrite.consumedNodes hvmAnnihilatePlan = [ hvmNodeA; hvmNodeB ]
                && KernelHvmRewrite.rewrite hvmCommutePlan = KernelHvmCommute(hvmNodeA, hvmNodeB)
                && KernelHvmRewrite.rewrite hvmErasePlan = KernelHvmEraseNode hvmNodeB
                && KernelHvmRewrite.rewrite hvmDereferencePlan = KernelHvmDereference(hvmNodeA, hvmReferenceBinding)
                && KernelHvmRewrite.mutatesTopology hvmDereferencePlan
                && not (KernelHvmRewrite.mutatesTopology KernelHvmRewrite.noRewrite)
                && KernelHvmRewrite.stableText hvmAnnihilatePlan = "annihilate:1:2"

            let requiredLaws =
                Set.ofList [ RestoredRuntimeContractVerified
                             RestoredRuntimeAdaptersDifferentiallyVerified
                             RestoredRuntimeOneShotExactOnce
                             RestoredRuntimeChoiceCancelsLosers
                             RestoredRuntimeClockMonotonic
                             RestoredScopeRejectsEarlyClose
                             RestoredPhaseProgressExactWhenClosed
                             RestoredArenaInterningIdempotent
                             RestoredDefEqReflexive
                             RestoredDefEqAssignedMetaResolves
                             RestoredMetaOccursCheckRejects
                             RestoredMetaAssignmentWakesObligation
                             RestoredUniverseOccursCheckRejects
                             RestoredDeclarationCommitRejectsMeta
                             RestoredPositivityRejectsNegativeOccurrence
                             RestoredPositivityAdmitsPositiveOccurrence
                             RestoredInductiveCommitAcceptsCertified
                             RestoredQuotientLiftComputesRepresentative
                             RestoredEtaReadbackCloses
                             RestoredPhaseHeavyTailEtaAvailable
                             RestoredInteractionNetConsumesActivePair
                             RestoredInteractionNetSuspendsMeta
                             RestoredInteractionNetResumesWake
                             RestoredHvmPortLinearityRejectsDuplicate
                             RestoredHvmRewriteAlgebraClassifiesActivePairs
                             RestoredSpecializationDependencyPlanClosed ]
            let satisfiedLaws =
                [ PortableRuntimeContract.isConformant PortableRuntimeEvidence.reference, RestoredRuntimeContractVerified
                  runtimeDifferentialsVerified, RestoredRuntimeAdaptersDifferentiallyVerified
                  runtimeOneShotExactOnce, RestoredRuntimeOneShotExactOnce
                  runtimeChoiceCancelsLosers, RestoredRuntimeChoiceCancelsLosers
                  runtimeClockMonotonic, RestoredRuntimeClockMonotonic
                  earlyCloseRejected, RestoredScopeRejectsEarlyClose
                  phaseExact, RestoredPhaseProgressExactWhenClosed
                  term1 = term2, RestoredArenaInterningIdempotent
                  KernelDefEqDecision.result defEq = KernelDefEqEqual, RestoredDefEqReflexive
                  defEqAssignedMetaResolves, RestoredDefEqAssignedMetaResolves
                  metaOccursCheckRejects, RestoredMetaOccursCheckRejects
                  metaAssignmentWakesObligation, RestoredMetaAssignmentWakesObligation
                  universeOccursRejected, RestoredUniverseOccursCheckRejects
                  declarationCommitRejectsMeta, RestoredDeclarationCommitRejectsMeta
                  positivityRejectsNegativeOccurrence, RestoredPositivityRejectsNegativeOccurrence
                  positivityAdmitsPositiveOccurrence, RestoredPositivityAdmitsPositiveOccurrence
                  inductiveCommitAcceptsCertified, RestoredInductiveCommitAcceptsCertified
                  quotientLiftComputesRepresentative, RestoredQuotientLiftComputesRepresentative
                  etaReadbackCloses, RestoredEtaReadbackCloses
                  phaseHeavyTailEtaAvailable, RestoredPhaseHeavyTailEtaAvailable
                  interactionNetConsumesActivePair, RestoredInteractionNetConsumesActivePair
                  interactionNetSuspendsMeta, RestoredInteractionNetSuspendsMeta
                  interactionNetResumesWake, RestoredInteractionNetResumesWake
                  hvmPortLinearityRejectsDuplicate, RestoredHvmPortLinearityRejectsDuplicate
                  hvmRewriteAlgebraClassifiesActivePairs, RestoredHvmRewriteAlgebraClassifiesActivePairs
                  specializationDependencyPlanClosed, RestoredSpecializationDependencyPlanClosed ]
                |> List.choose (fun (satisfied, law) -> if satisfied then Some law else None)
                |> Set.ofList
            let receiptRef =
                satisfiedLaws
                |> Set.toList
                |> List.map restoredSubstrateLawStableText
                |> String.concat "|"
                |> ContentDigest.ofText "restored-substrate-conformance"
            { runtimeBoundary = PortableRuntimeInProcessOnly
              runtimeDifferentialTraceCount = runtimeDifferentialTraceCount
              requiredLaws = requiredLaws
              satisfiedLaws = satisfiedLaws
              receiptRef = receiptRef }

        let private restoredSubstrateConformance =
            lazy (restoredSubstrateConformanceReceipt ())

        let validateRestoredSubstrateConformance () =
            let receipt = restoredSubstrateConformance.Value
            let missing = Set.difference receipt.requiredLaws receipt.satisfiedLaws
            if receipt.runtimeBoundary = PortableRuntimeInProcessOnly
               && receipt.runtimeDifferentialTraceCount = 8
               && Set.isEmpty missing then
                Ok ()
            else
                let missingText =
                    missing
                    |> Set.toList
                    |> List.map restoredSubstrateLawStableText
                    |> String.concat ","
                Error(
                    "restored_compiler_substrate_conformance_failed"
                    + "|receipt=" + ContentDigest.text receipt.receiptRef
                    + "|trace_count=" + string receipt.runtimeDifferentialTraceCount
                    + "|missing=" + missingText)

        type KernelTerminalStage =
            | KernelRunEndClaimed
            | KernelRunEndDurable
            | KernelRunEndClaimReleased
            | KernelTerminalFilled
            | KernelTerminalWriterCommitted
            | KernelTerminalSealAuthorized
            | KernelTerminalSealed
            | KernelTerminalFailedClosed
            | KernelPhysicalExitSelected

        let kernelTerminalStageStableText = function
            | KernelRunEndClaimed -> "run_end_claimed"
            | KernelRunEndDurable -> "run_end_durable"
            | KernelRunEndClaimReleased -> "run_end_claim_released"
            | KernelTerminalFilled -> "terminal_filled"
            | KernelTerminalWriterCommitted -> "terminal_writer_committed"
            | KernelTerminalSealAuthorized -> "terminal_seal_authorized"
            | KernelTerminalSealed -> "terminal_sealed"
            | KernelTerminalFailedClosed -> "terminal_failed_closed"
            | KernelPhysicalExitSelected -> "physical_exit_selected"

        type KernelAuthorityKind =
            | KernelPushActorAuthority
            | KernelArtifactWriterAuthority
            | KernelRunEndAuthority
            | KernelSchedulerAuthority
            | KernelWorkCellAuthority

        type KernelAuthorityRejection =
            | KernelZeroReference
            | KernelForeignLineage
            | KernelStaleGeneration
            | KernelIllegalTransition
            | KernelConfluenceConflict

        type KernelJournalEvent =
            | JournalWorkDiscovered of binding:StableBindingId * cost:int64
            | JournalWorkCompleted of binding:StableBindingId * cost:int64 * result:ContentDigest
            | JournalTerminalStage of stage:KernelTerminalStage * authorityRef:ContentDigest
            | JournalAuthorityRejected of authority:KernelAuthorityKind * reason:KernelAuthorityRejection

        type KernelJournal = private {
            lastSequence : int64
            eventsNewestFirst : (int64 * KernelJournalEvent) list
        }

        module KernelJournal =
            let empty = { lastSequence = 0L; eventsNewestFirst = [] }

            let append sequence event journal =
                if sequence <> journal.lastSequence + 1L then
                    Error(sprintf "journal_sequence_gap|expected=%d|actual=%d" (journal.lastSequence + 1L) sequence)
                else
                    Ok { lastSequence = sequence
                         eventsNewestFirst = (sequence, event) :: journal.eventsNewestFirst }

            let lastSequence journal = journal.lastSequence
            let events journal = List.rev journal.eventsNewestFirst

        let kernelJournalEmpty = KernelJournal.empty
        let kernelJournalAppend sequence event journal = KernelJournal.append sequence event journal
        let kernelJournalLastSequence journal = KernelJournal.lastSequence journal
        let kernelJournalEvents journal = KernelJournal.events journal

        type KernelConformanceReceipt = {
            zeroRefRejected : bool
            mergeIdempotent : bool
            mergeCommutative : bool
            progressClosedExact : bool
            journalGapRejected : bool
        }

        let conformanceReceipt () =
            let binding = StableBindingId.create 0 "kernel-conformance"
            let cell = ConfluentWorkCell.complete binding 1L "ok" 1
            let mergedLeft = ConfluentWorkCell.merge cell cell
            let mergedRight = ConfluentWorkCell.merge cell cell
            let progress =
                ExactCostLedger.create
                    (Measured.create<SemanticCostUnit> "completedCost" 1L)
                    (Measured.create<SemanticCostUnit> "discoveredCost" 1L)
                    (Measured.create<SemanticCostUnit> "blockedCost" 0L)
                    ProgressDenominatorClosed
                |> ExactCostLedger.project
            { zeroRefRejected = NonZeroRef.tryCreate 0u |> Option.isNone
              mergeIdempotent = mergedLeft = cell
              mergeCommutative = mergedLeft = mergedRight
              progressClosedExact = progress.exact && BasisPoints.value progress.midBp = 10000L
              journalGapRejected =
                match KernelJournal.append 2L (JournalAuthorityRejected(KernelWorkCellAuthority, KernelIllegalTransition)) KernelJournal.empty with
                | Error _ -> true
                | Ok _ -> false }

        let private compilerKernelV2Conformance =
            lazy (conformanceReceipt ())

        let validateCompilerKernelV2Conformance () =
            let receipt = compilerKernelV2Conformance.Value
            if receipt.zeroRefRejected
               && receipt.mergeIdempotent
               && receipt.mergeCommutative
               && receipt.progressClosedExact
               && receipt.journalGapRejected then
                Ok ()
            else
                Error "compiler_kernel_v2_conformance_failed"

        type DeferredCompilerConformanceResult =
            | DeferredCompilerConformancePassed
            | DeferredCompilerConformanceFailed of failures:string list

        let runDeferredCompilerConformance () =
            CompilerRuntimeActivation.requireInProcessEntered "deferred_compiler_conformance"
            let failures =
                [ validateCompilerKernelV2Conformance ()
                  validateRestoredSubstrateConformance () ]
                |> List.choose (function
                    | Ok () -> None
                    | Error failure -> Some failure)
            if List.isEmpty failures then
                DeferredCompilerConformancePassed
            else
                DeferredCompilerConformanceFailed failures

    type JpActiveWorkIdentitySnapshot = private {
        workUnitRef : CompilerIdentityKernel.ContentDigest
        bindingId : CompilerKernelV2.StableBindingId
        siteId : CompilerIdentityKernel.WorkSiteId
        startedAtMs : int64
    }

    type JpLiveDependencySnapshot = private {
        waiterJobId : int64
        waiterWorkUnitRef : CompilerIdentityKernel.ContentDigest
        waiterBindingId : CompilerKernelV2.StableBindingId
        waiterSiteId : CompilerIdentityKernel.WorkSiteId
        producerWorkId : int64
        producerBindingId : CompilerKernelV2.StableBindingId
        promiseRef : CompilerIdentityKernel.ContentDigest
        waitRef : CompilerIdentityKernel.ContentDigest
        ownerRef : uint32
        startedAtMs : int64
        dispositionId : CompilerKernelV2.OperationalReasonId
    }

    type JpBlockedDependencyEvidence =
        | JpBlockedDependencyLive of JpLiveDependencySnapshot list
        | JpBlockedDependencyRetainedStale of snapshot:JpLiveDependencySnapshot * ageMs:int64
        | JpBlockedDependencyExpired of snapshot:JpLiveDependencySnapshot * ageMs:int64
        | JpBlockedDependencyUnavailable

    module JpActiveWorkIdentityAuthority =
        let private gate = obj()
        let mutable private activeByJob : Map<int64,JpActiveWorkIdentitySnapshot> = Map.empty
        let mutable private dependencyByWaiter : Map<int64,JpLiveDependencySnapshot> = Map.empty
        let mutable private retainedDependency : JpLiveDependencySnapshot option = None

        let private ownerRefOfJobId jobId =
            NativeCutoverStableRef.ref32 "jp-active-owner" [string jobId]

        let register jobId workUnitRef bindingId siteId _startedAtMs =
            // Terminal attribution uses the host monotonic clock. JP timing is
            // peval-relative and cannot be subtracted from Environment.TickCount64.
            let snapshot = {
                workUnitRef = workUnitRef
                bindingId = bindingId
                siteId = siteId
                startedAtMs = max 0L Environment.TickCount64
            }
            lock gate (fun () -> activeByJob <- Map.add jobId snapshot activeByJob)

        let beginDependency waiterJobId _startedAtMs producerWorkId producerBindingId promiseRef waitRef dispositionId =
            lock gate (fun () ->
                match Map.tryFind waiterJobId activeByJob with
                | None -> ()
                | Some waiter ->
                    let snapshot = {
                        waiterJobId = waiterJobId
                        waiterWorkUnitRef = waiter.workUnitRef
                        waiterBindingId = waiter.bindingId
                        waiterSiteId = waiter.siteId
                        producerWorkId = producerWorkId
                        producerBindingId = producerBindingId
                        promiseRef = promiseRef
                        waitRef = waitRef
                        ownerRef = ownerRefOfJobId waiterJobId
                        startedAtMs = max 0L Environment.TickCount64
                        dispositionId = dispositionId
                    }
                    dependencyByWaiter <- Map.add waiterJobId snapshot dependencyByWaiter
                    retainedDependency <- Some snapshot)

        let endDependency waiterJobId =
            lock gate (fun () ->
                match Map.tryFind waiterJobId dependencyByWaiter with
                | Some snapshot -> retainedDependency <- Some snapshot
                | None -> ()
                dependencyByWaiter <- Map.remove waiterJobId dependencyByWaiter)

        let retire jobId =
            lock gate (fun () ->
                match Map.tryFind jobId dependencyByWaiter with
                | Some snapshot -> retainedDependency <- Some snapshot
                | None -> ()
                activeByJob <- Map.remove jobId activeByJob
                dependencyByWaiter <- Map.remove jobId dependencyByWaiter)

        let readOldest () =
            lock gate (fun () ->
                activeByJob
                |> Map.toSeq
                |> Seq.map snd
                |> Seq.sortBy (fun snapshot -> snapshot.startedAtMs)
                |> Seq.tryHead)

        let readBlockedDependencyEvidence () =
            lock gate (fun () ->
                let live =
                    dependencyByWaiter
                    |> Map.toSeq
                    |> Seq.map snd
                    |> Seq.sortBy (fun snapshot -> snapshot.startedAtMs)
                    |> Seq.toList
                match live with
                | _ :: _ -> JpBlockedDependencyLive live
                | [] ->
                    match retainedDependency with
                    | Some snapshot ->
                        let ageMs = max 0L (Environment.TickCount64 - snapshot.startedAtMs)
                        if ageMs <= 30000L then
                            JpBlockedDependencyRetainedStale(snapshot, ageMs)
                        else
                            JpBlockedDependencyExpired(snapshot, ageMs)
                    | None -> JpBlockedDependencyUnavailable)

        let readCounts () =
            lock gate (fun () -> int64 activeByJob.Count, int64 dependencyByWaiter.Count)

        let clearRetainedForNewCompilation () =
            lock gate (fun () -> retainedDependency <- None)

    [<StructuralEquality; NoComparison>]
    type SemanticWorkOpenState =
        | SemanticWorkBalanced of admitted:int64
        | SemanticWorkOpen of admitted:int64 * receipts:int64 * openCount:int64
        | SemanticWorkOverApplied of admitted:int64 * receipts:int64 * excessReceipts:int64

    module SemanticWorkLedgerProjection =
        let private normalize admitted receipts =
            let admitted = max 0L admitted
            let receipts = max 0L receipts
            if admitted = receipts then
                SemanticWorkBalanced admitted
            elif admitted > receipts then
                SemanticWorkOpen(admitted, receipts, admitted - receipts)
            else
                SemanticWorkOverApplied(admitted, receipts, receipts - admitted)

        let read () =
            let admitted, receipts = CompilerKernelV2.SemanticWorkLedgerAuthority.counts ()
            normalize (int64 admitted) (int64 receipts)

        let readOperational () =
            let admitted, receipts =
                CompilerKernelV2.SemanticWorkLedgerAuthority.countsForScope
                    CompilerKernelV2.SemanticWorkOperational
            normalize (int64 admitted) (int64 receipts)

        let terminalDebtCountOf = function
            | SemanticWorkBalanced _ -> 0L
            | SemanticWorkOpen(_, _, openCount) -> openCount
            | SemanticWorkOverApplied(_, _, excessReceipts) -> excessReceipts

        let countsOf = function
            | SemanticWorkBalanced admitted -> admitted, admitted, 0L
            | SemanticWorkOpen(admitted, receipts, openCount) -> admitted, receipts, openCount
            | SemanticWorkOverApplied(admitted, receipts, _) -> admitted, receipts, 0L

        let stateClassTextOf = function
            | SemanticWorkBalanced _ -> "balanced"
            | SemanticWorkOpen _ -> "open"
            | SemanticWorkOverApplied _ -> "over_applied"

        let stateTextOf = function
            | SemanticWorkBalanced admitted ->
                FastRuntimeFormat.format "balanced|admitted=%d|receipts=%d" [| box admitted; box admitted |]
            | SemanticWorkOpen(admitted, receipts, openCount) ->
                FastRuntimeFormat.format "open|admitted=%d|receipts=%d|open=%d" [| box admitted; box receipts; box openCount |]
            | SemanticWorkOverApplied(admitted, receipts, excessReceipts) ->
                FastRuntimeFormat.format "over_applied|admitted=%d|receipts=%d|excess=%d" [| box admitted; box receipts; box excessReceipts |]

        let terminalDebtCount () = read () |> terminalDebtCountOf
        let stateText () = read () |> stateTextOf

    // Operational graph publication crosses the BigStack/diagnostics module boundary.
    // Keep the mutable registration cell in a tiny sibling module so F# module
    // visibility does not depend on exposing a late-added member through DiagJson.
    module TerminalFlowOperationalGraphSnapshotBridge =
        let mutable private snapshotProvider :
            unit -> (int64 * int64 * int64 * CompilerIdentityKernel.ContentDigest) option =
            fun () -> None

        let install
            (snapshot: unit -> int64 * int64 * int64 * CompilerIdentityKernel.ContentDigest) =
            snapshotProvider <- fun () ->
                let graphRevision, openCount, suspendedCount, graphRef = snapshot ()
                Some(graphRevision, max 0L openCount, max 0L suspendedCount, graphRef)

        let read () = snapshotProvider ()

    // Defunctionalized HKT application shared by replay and CIC domains.
    type App<'F,'A> = interface end

    module DiagJson =

        // SPIRAL_DIAG_QUIET=1 (scripts/test.ps1 sets it): batch builds nobody watches skip the diagnostic
        // JSONL rows and console projections, which cost ~20% of a compile (FRONTIER.md fix 35). Durable
        // terminal receipts, build errors and the result are unaffected. Direct compiles keep full telemetry.
        let quiet =
            System.String.Equals(System.Environment.GetEnvironmentVariable "SPIRAL_DIAG_QUIET", "1", System.StringComparison.Ordinal)

        let private diagnosticTextDelimiters =
            [| '|'; '@'; '/'; ':'; '('; ')'; '['; ']'; '{'; '}'; ','; ';'; '='; ' '; '\t'; '\r'; '\n'; '"'; '\'' |]

        let private diagnosticTextTokensLower (text:string) : Set<string> =
            if String.IsNullOrWhiteSpace text then Set.empty
            else
                text.Split(diagnosticTextDelimiters, StringSplitOptions.RemoveEmptyEntries)
                |> Array.map (fun token -> token.ToLowerInvariant())
                |> Set.ofArray

        let private diagnosticTextSegmentsLower (text:string) : Set<string> =
            diagnosticTextTokensLower text
            |> Seq.collect (fun token ->
                token.Split([| '_'; '-' |], StringSplitOptions.RemoveEmptyEntries)
                :> seq<string>)
            |> Set.ofSeq

        // Legacy text is allowed only at diagnostic ingress.  Turn marker syntax
        // into a recursive evidence pattern once, then let every operational
        // consumer match the closed pattern instead of performing substring scans.
        type DiagnosticTextEvidencePattern =
            | DiagnosticAllTokens of required:string list
            | DiagnosticAllSegments of required:string list
            | DiagnosticAnyPattern of DiagnosticTextEvidencePattern list
            | DiagnosticEveryPattern of DiagnosticTextEvidencePattern list

        let rec private diagnosticTextEvidencePatternMatches tokens segments = function
            | DiagnosticAllTokens required ->
                not (List.isEmpty required)
                && (required
                    |> List.forall (fun token ->
                        Set.contains (token.ToLowerInvariant()) tokens))
            | DiagnosticAllSegments required ->
                not (List.isEmpty required)
                && (required
                    |> List.forall (fun segment ->
                        Set.contains (segment.ToLowerInvariant()) segments))
            | DiagnosticAnyPattern patterns ->
                patterns
                |> List.exists (diagnosticTextEvidencePatternMatches tokens segments)
            | DiagnosticEveryPattern patterns ->
                not (List.isEmpty patterns)
                && (patterns
                    |> List.forall (diagnosticTextEvidencePatternMatches tokens segments))

        let private diagnosticTextPatternForMarker marker =
            DiagnosticAnyPattern
                [ DiagnosticAllTokens(
                      diagnosticTextTokensLower marker
                      |> Set.toList)
                  DiagnosticAllSegments(
                      diagnosticTextSegmentsLower marker
                      |> Set.toList) ]

        let private diagnosticTextHasAny candidates tokens =
            candidates |> List.exists (fun candidate -> Set.contains candidate tokens)

        type DynamicBridgeAuthoritySignalId =
            | DynamicBridgeTailPierceSignal
            | DynamicBridgeRecordKeySignal

        let private dynamicBridgeAuthoritySignals (text:string) =
            let tokens =
                if String.IsNullOrWhiteSpace text then Set.empty
                else
                    text.Split(
                        [| '|'; '@'; '/'; ':'; '('; ')'; '['; ']'; '{'; '}'; ','; ';'; '='; ' '; '\t'; '\r'; '\n'; '"' |],
                        StringSplitOptions.RemoveEmptyEntries)
                    |> Set.ofArray
            [ if Set.contains "DynamicRecordKeyBridgeTailPierce" tokens then
                  DynamicBridgeTailPierceSignal
              if Set.contains "dynamic_record_key_bridge" tokens then
                  DynamicBridgeRecordKeySignal ]
            |> Set.ofList

        type CachedLiveTailEvidenceShapeId =
            | CachedLiveTailEvidenceMissing
            | CachedLiveTailEvidenceNeedsFrontierReconciliation
            | CachedLiveTailEvidenceCarriesSampledWorkDelta
            | CachedLiveTailEvidenceLegacyWithoutSampledWorkDelta

        type CachedLiveTailEvidenceFieldId =
            | CachedLiveTailPendingNotReconciled
            | CachedLiveTailFrontierPendingZero
            | CachedLiveTailRawPendingPresent
            | CachedLiveTailSampledWorkDeltaPresent

        let private cachedLiveTailEvidenceFields (text:string) =
            if String.IsNullOrWhiteSpace text then Set.empty
            else
                text.Split([|'|'|], StringSplitOptions.RemoveEmptyEntries)
                |> Array.choose (fun segment ->
                    let parts = segment.Split([|'='|], StringSplitOptions.None)
                    if parts.Length < 2 then None
                    else
                        match parts.[0], parts.[1] with
                        | "pending_reconciled", "false" -> Some CachedLiveTailPendingNotReconciled
                        | "front_p", "0" -> Some CachedLiveTailFrontierPendingZero
                        | "raw_p", _ -> Some CachedLiveTailRawPendingPresent
                        | "sampled_work_delta", _ -> Some CachedLiveTailSampledWorkDeltaPresent
                        | _ -> None)
                |> Set.ofArray

        let private cachedLiveTailEvidenceShape (text:string) =
            if String.IsNullOrWhiteSpace text || text = "-" then CachedLiveTailEvidenceMissing
            else
                let fields = cachedLiveTailEvidenceFields text
                if Set.contains CachedLiveTailPendingNotReconciled fields
                   && Set.contains CachedLiveTailFrontierPendingZero fields
                   && Set.contains CachedLiveTailRawPendingPresent fields then
                    CachedLiveTailEvidenceNeedsFrontierReconciliation
                elif Set.contains CachedLiveTailSampledWorkDeltaPresent fields then
                    CachedLiveTailEvidenceCarriesSampledWorkDelta
                else CachedLiveTailEvidenceLegacyWithoutSampledWorkDelta

        type SidecarStickyStatusSignalId =
            | SidecarStickySidecarSignal
            | SidecarStickyPrefetchSignal
            | SidecarStickyMissingAfterPrefetchSignal

        let private sidecarStickyStatusSignals (text:string) =
            let tokens = diagnosticTextTokensLower text
            let segments = diagnosticTextSegmentsLower text
            [ if Set.contains "sidecar" segments then
                  SidecarStickySidecarSignal
              if Set.contains "prefetch" segments then
                  SidecarStickyPrefetchSignal
              if Set.contains "missing_after_prefetch" tokens
                 || (Set.contains "missing" segments
                     && Set.contains "after" segments
                     && Set.contains "prefetch" segments) then
                  SidecarStickyMissingAfterPrefetchSignal ]
            |> Set.ofList

        type PrefetchMissingTargetKeyId =
            | PrefetchParentHandoffKey of node:string
            | PrefetchTyKey of site:string * node:string
            | PrefetchTermKey of site:string * node:string
            | PrefetchOpaqueKey of raw:string

        let private prefetchMissingTargetKeyId (raw:string) =
            let nodeAfterHash () =
                let hashIx = raw.LastIndexOf("#", StringComparison.Ordinal)
                if hashIx >= 0 then raw.Substring(hashIx + 1) else "?"
            let siteBetweenSlashAndHash () =
                let hashIx = raw.LastIndexOf("#", StringComparison.Ordinal)
                let slashIx = raw.LastIndexOf("/", StringComparison.Ordinal)
                if slashIx >= 0 && hashIx > slashIx then raw.Substring(slashIx + 1, hashIx - slashIx - 1)
                else raw
            let tokens = diagnosticTextTokensLower raw
            let relation =
                let head = raw.Split([|':'|], 2, StringSplitOptions.RemoveEmptyEntries)
                if head.Length <> 2 then None
                else
                    let nested = head.[1].Split([|'@'|], 2, StringSplitOptions.RemoveEmptyEntries)
                    if nested.Length = 0 then None
                    else Some(head.[0].ToLowerInvariant(), nested.[0].ToLowerInvariant())
            if Set.contains "cache_write_parent_handoff" tokens then
                let parts = raw.Split([|'|'|], StringSplitOptions.RemoveEmptyEntries)
                let node = if parts.Length > 0 then parts.[parts.Length - 1] else "?"
                PrefetchParentHandoffKey node
            else
                match relation with
                | Some("ty", "ty") -> PrefetchTyKey(siteBetweenSlashAndHash(), nodeAfterHash())
                | Some("term", "term") -> PrefetchTermKey(siteBetweenSlashAndHash(), nodeAfterHash())
                | _ -> PrefetchOpaqueKey raw

        let private prefetchMissingTargetKeyText = function
            | PrefetchParentHandoffKey node -> "ParentHandoff(Term,Node:" + node + ")"
            | PrefetchTyKey(site, node) -> "TyKey(" + site + ",Node:" + node + ")"
            | PrefetchTermKey(site, node) -> "TermKey(" + site + ",Node:" + node + ")"
            | PrefetchOpaqueKey raw -> raw

        type ProgressTailTextSignalId =
            | ProgressTailTextPoisonSignal
            | ProgressTailTextTopologySignal
            | ProgressTailTextSidecarDrainSignal

        let private progressTailTextSignals (text:string) =
            let segments = diagnosticTextSegmentsLower text
            [ if diagnosticTextHasAny [ "poison"; "poisoned" ] segments then
                  ProgressTailTextPoisonSignal
              if Set.contains "topology" segments then
                  ProgressTailTextTopologySignal
              if Set.contains "sidecar" segments && Set.contains "drain" segments then
                  ProgressTailTextSidecarDrainSignal ]
            |> Set.ofList

        type TerminalStatusSignalId =
            | TerminalStatusSemanticRootComplete
            | TerminalStatusParentReplayCycleBreakPoisoned

        let private terminalStatusSignals (text:string) =
            let tokens = diagnosticTextTokensLower text
            [ if Set.contains "semantic_root_complete" tokens then
                  TerminalStatusSemanticRootComplete
              if Set.contains "semantic_parent_replay_cycle_break_poisoned" tokens then
                  TerminalStatusParentReplayCycleBreakPoisoned ]
            |> Set.ofList

        type TerminalCauseSignalId =
            | TerminalCauseHardPoisonObligation
            | TerminalCauseCrossKindYieldThrash
            | TerminalCauseParentReplay

        let private terminalCauseSignals (text:string) =
            let tokens = diagnosticTextTokensLower text
            let segments = diagnosticTextSegmentsLower text
            [ if Set.contains "hard_poison_obligation" tokens
                 || (Set.contains "hard" segments && Set.contains "poison" segments && Set.contains "obligation" segments) then
                  TerminalCauseHardPoisonObligation
              if Set.contains "cross_kind_yield_thrash" tokens
                 || (Set.contains "cross" segments && Set.contains "kind" segments && Set.contains "yield" segments && Set.contains "thrash" segments) then
                  TerminalCauseCrossKindYieldThrash
              if Set.contains "parent_replay" tokens
                 || (Set.contains "parent" segments && Set.contains "replay" segments) then
                  TerminalCauseParentReplay ]
            |> Set.ofList

        type NativeParentJobBindDebtSignalId =
            | NativeParentJobBindCrossKindDebt
            | NativeParentJobBindOtherDebt

        let private nativeParentJobBindDebtSignalId (text:string) =
            let tokens = diagnosticTextTokensLower text
            let segments = diagnosticTextSegmentsLower text
            if diagnosticTextHasAny [ "cross_kind"; "idlecrosskind"; "crosskindobligation" ] tokens
               || (Set.contains "cross" segments && Set.contains "kind" segments) then
                NativeParentJobBindCrossKindDebt
            else
                NativeParentJobBindOtherDebt

        let esc (s: string) =
            if System.Object.ReferenceEquals(s,null) then "null" else
                let s =
                    s.Replace("\\","\\\\")
                     .Replace("\"","\\\"")
                     .Replace("\r","\\r")
                     .Replace("\n","\\n")
                     .Replace("\t","\\t")
                "\"" + s + "\""

        // Sparse diagnostic policy is shared by terminal protocol and evaluator paths.
        // Keeping it at the JSONL boundary prevents module-local helpers from becoming
        // invisible when a new producer adopts the same first3/power2/every-N policy.
        let private sparseLogCountRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,int64>()

        let sparseLogDecision key everyN =
            let keyRef = CompilerIdentityKernel.ContentDigest.ofText "json-sparse-log-key" key
            let occurrence = sparseLogCountRegistry.AddOrUpdate(keyRef, 1L, fun _ count -> count + 1L)
            let powerOfTwo = occurrence > 0L && (occurrence &&& (occurrence - 1L)) = 0L
            let emit = occurrence <= 3L || powerOfTwo || (everyN > 0L && occurrence % everyN = 0L)
            occurrence, emit

        type SemanticFactSourceId =
            | SemanticFactRootValue
            | SemanticFactWorkUnitReceipt

        type SemanticFactBridgeSnapshot = {
            factCount : int64
            rootValueFactCount : int64
            workUnitReceiptFactCount : int64
            rootValueRetiredCost : int64
            workUnitReceiptRetiredCost : int64
            rootValueCriticalPathRetiredCost : int64
            workUnitReceiptCriticalPathRetiredCost : int64
            retiredCost : int64
            criticalPathRetiredCost : int64
        }

        let private semanticFactBridgeRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, struct(int64 * int64 * SemanticFactSourceId)>()

        let private semanticFactBridgeGate = obj()
        let mutable private semanticFactBridgeSnapshotValue =
            { factCount = 0L
              rootValueFactCount = 0L
              workUnitReceiptFactCount = 0L
              rootValueRetiredCost = 0L
              workUnitReceiptRetiredCost = 0L
              rootValueCriticalPathRetiredCost = 0L
              workUnitReceiptCriticalPathRetiredCost = 0L
              retiredCost = 0L
              criticalPathRetiredCost = 0L }

        let private noteSemanticFactExactOnceForSource source semanticAuthorityKey actualCost criticalPathCost =
            let actualCost = max 1L actualCost
            let criticalPathCost = max 0L criticalPathCost
            let semanticAuthorityRef =
                CompilerIdentityKernel.ContentDigest.ofText "semantic-fact-authority" semanticAuthorityKey
            let admitted =
                semanticFactBridgeRegistry.TryAdd(
                    semanticAuthorityRef,
                    struct(actualCost, criticalPathCost, source))
            if admitted then
                lock semanticFactBridgeGate (fun () ->
                    let previous = semanticFactBridgeSnapshotValue
                    semanticFactBridgeSnapshotValue <-
                        { factCount = previous.factCount + 1L
                          rootValueFactCount = previous.rootValueFactCount + (if source = SemanticFactRootValue then 1L else 0L)
                          workUnitReceiptFactCount = previous.workUnitReceiptFactCount + (if source = SemanticFactWorkUnitReceipt then 1L else 0L)
                          rootValueRetiredCost = previous.rootValueRetiredCost + (if source = SemanticFactRootValue then actualCost else 0L)
                          workUnitReceiptRetiredCost = previous.workUnitReceiptRetiredCost + (if source = SemanticFactWorkUnitReceipt then actualCost else 0L)
                          rootValueCriticalPathRetiredCost = previous.rootValueCriticalPathRetiredCost + (if source = SemanticFactRootValue then criticalPathCost else 0L)
                          workUnitReceiptCriticalPathRetiredCost = previous.workUnitReceiptCriticalPathRetiredCost + (if source = SemanticFactWorkUnitReceipt then criticalPathCost else 0L)
                          retiredCost = previous.retiredCost + actualCost
                          criticalPathRetiredCost = previous.criticalPathRetiredCost + criticalPathCost })
            admitted

        let noteSemanticFactExactOnce semanticAuthorityKey actualCost criticalPathCost =
            noteSemanticFactExactOnceForSource SemanticFactRootValue semanticAuthorityKey actualCost criticalPathCost

        let noteSemanticWorkUnitReceiptExactOnce semanticAuthorityKey actualCost criticalPathCost =
            noteSemanticFactExactOnceForSource SemanticFactWorkUnitReceipt semanticAuthorityKey actualCost criticalPathCost

        let semanticFactBridgeSnapshot () =
            lock semanticFactBridgeGate (fun () -> semanticFactBridgeSnapshotValue)

        type SpecializationInteractionBridgeSnapshot = {
            proofCount : int64
            consumedActivePairs : int64
            runtimeHostReceiptCount : int64
            runtimeVerifiedReceiptCount : int64
            runtimeComparedTransitions : int64
            runtimeVerifiedTransitions : int64
            latestRuntimeTraceRef : string
            latestProofRef : string
        }

        let private specializationInteractionBridgeRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,int64>()

        let private specializationInteractionBridgeGate = obj()
        let mutable private specializationInteractionBridgeSnapshotValue =
            { proofCount = 0L
              consumedActivePairs = 0L
              runtimeHostReceiptCount = 0L
              runtimeVerifiedReceiptCount = 0L
              runtimeComparedTransitions = 0L
              runtimeVerifiedTransitions = 0L
              latestRuntimeTraceRef = ""
              latestProofRef = "" }

        let noteSpecializationInteractionReceipt (receipt:CompilerKernelV2.SpecializationInteractionReceipt) =
            let proofRef =
                receipt
                |> CompilerKernelV2.SpecializationInteractionReceiptView.proofRef
            let proofRefText = CompilerIdentityKernel.ContentDigest.text proofRef
            let before =
                receipt
                |> CompilerKernelV2.SpecializationInteractionReceiptView.activePairsBefore
                |> int64
            let after =
                receipt
                |> CompilerKernelV2.SpecializationInteractionReceiptView.activePairsAfter
                |> int64
            let consumed = max 0L (before - after)
            let admitted = specializationInteractionBridgeRegistry.TryAdd(proofRef, consumed)
            if admitted then
                lock specializationInteractionBridgeGate (fun () ->
                    let previous = specializationInteractionBridgeSnapshotValue
                    specializationInteractionBridgeSnapshotValue <-
                        { previous with
                            proofCount = previous.proofCount + 1L
                            consumedActivePairs = previous.consumedActivePairs + consumed
                            latestProofRef = proofRefText })
            admitted

        let specializationInteractionBridgeSnapshot () =
            let specialization =
                lock specializationInteractionBridgeGate (fun () -> specializationInteractionBridgeSnapshotValue)
            let runtime = CompilerKernelV2.PortableRuntimeInteractionEvidenceBridge.snapshot()
            { specialization with
                consumedActivePairs = specialization.consumedActivePairs + runtime.verifiedTransitions
                runtimeHostReceiptCount = runtime.hostReceiptCount
                runtimeVerifiedReceiptCount = runtime.verifiedReceiptCount
                runtimeComparedTransitions = runtime.comparedTransitions
                runtimeVerifiedTransitions = runtime.verifiedTransitions
                latestRuntimeTraceRef =
                    runtime.latestTraceRef
                    |> Option.map CompilerIdentityKernel.ContentDigest.text
                    |> Option.defaultValue "" }

        type SemanticWorkLedgerSnapshot = {
            admitted : int64
            receipts : int64
            retiredCost : int64
            openCount : int64
            operationalOpenCount : int64
            operationalOpenWorkUnits : Lazy<string list>
            terminalProtocolOpenCount : int64
            terminalProtocolOpenWorkUnits : Lazy<string list>
            unclassifiedOpenCount : int64
        }


        let semanticWorkLedgerSnapshot () =
            let ledger = CompilerKernelV2.SemanticWorkLedgerAuthority.snapshot ()
            let admitted, receipts = CompilerKernelV2.SemanticWorkLedger.counts ledger
            let operationalDecision =
                CompilerKernelV2.SemanticWorkLedger.creditDecisionForScope
                    CompilerKernelV2.SemanticWorkOperational
                    ledger
            let terminalProtocolDecision =
                CompilerKernelV2.SemanticWorkLedger.creditDecisionForScope
                    CompilerKernelV2.SemanticWorkTerminalProtocol
                    ledger
            let projection =
                CompilerKernelV2.SemanticWorkLedger.project
                    CompilerKernelV2.ProgressDenominatorClosed
                    ledger
            { admitted = int64 admitted
              receipts = int64 receipts
              retiredCost = CompilerKernelV2.Measured.value projection.completedCost
              openCount = int64 (max 0 (admitted - receipts))
              operationalOpenCount = CompilerKernelV2.SemanticWorkCreditDecision.openUnitCount operationalDecision |> int64
              operationalOpenWorkUnits = lazy (CompilerKernelV2.SemanticWorkCreditDecision.openWorkUnitTexts operationalDecision)
              terminalProtocolOpenCount = CompilerKernelV2.SemanticWorkCreditDecision.openUnitCount terminalProtocolDecision |> int64
              terminalProtocolOpenWorkUnits = lazy (CompilerKernelV2.SemanticWorkCreditDecision.openWorkUnitTexts terminalProtocolDecision)
              unclassifiedOpenCount = CompilerKernelV2.SemanticWorkLedger.unclassifiedOpenCount ledger |> int64 }

        let semanticWorkLedgerClosed (snapshot : SemanticWorkLedgerSnapshot) =
            snapshot.openCount = 0L


        // Duration samples cross the DiagJson/peval declaration boundary as a
        // phase-indexed domain. Shape/site text is decoded once at ingress; the
        // progress book never infers a phase from a later diagnostic string.
        type CompilerPhaseDurationSampleSource =
            | CompilerPhaseDurationWorkUnit
            | CompilerPhaseDurationPhaseInterval
            | CompilerPhaseDurationImportedReceipt

        [<StructuralEquality; NoComparison>]
        type CompilerPhaseDurationSample = private {
            phase : CompilerKernelV2.CompilerWorkPhase
            source : CompilerPhaseDurationSampleSource
            shape : CompilerIdentityKernel.WorkShapeId
            site : CompilerIdentityKernel.WorkSiteId
            durationMs : int64
            sampleRef : CompilerIdentityKernel.ContentDigest
        }

        type CompilerPhaseDurationDistributionScope =
            | CompilerPhaseDurationObserved of CompilerKernelV2.CompilerWorkPhase * sampleCount:int
            | CompilerPhaseDurationAwaitingSamples of CompilerKernelV2.CompilerWorkPhase

        type CompilerPhaseEtaAvailability =
            | CompilerPhaseEtaAvailable
            | CompilerPhaseEtaAwaitingDurationDistribution of CompilerKernelV2.CompilerWorkPhase
            | CompilerPhaseEtaBlockedByOpenDiscovery of CompilerKernelV2.CompilerWorkPhase

        let compilerPhaseDurationDistributionScopeText = function
            | CompilerPhaseDurationObserved(phase, sampleCount) ->
                sprintf "Observed(phase=%s|samples=%d)" (CompilerKernelV2.compilerWorkPhaseStableText phase) sampleCount
            | CompilerPhaseDurationAwaitingSamples phase ->
                "AwaitingSamples(phase=" + CompilerKernelV2.compilerWorkPhaseStableText phase + ")"

        let compilerPhaseEtaAvailabilityText = function
            | CompilerPhaseEtaAvailable -> "Available"
            | CompilerPhaseEtaAwaitingDurationDistribution phase ->
                "AwaitingDurationDistribution(phase=" + CompilerKernelV2.compilerWorkPhaseStableText phase + ")"
            | CompilerPhaseEtaBlockedByOpenDiscovery phase ->
                "BlockedByOpenDiscovery(phase=" + CompilerKernelV2.compilerWorkPhaseStableText phase + ")"

        let private compilerPhaseForDurationSample (shape:string) (site:string) =
            let shapeKey = if System.String.IsNullOrWhiteSpace shape then "" else shape.Trim().ToLowerInvariant()
            match shapeKey with
            | "parse" | "parser" | "parsing" -> CompilerKernelV2.WorkParse
            | "resolve" | "name-resolution" -> CompilerKernelV2.WorkResolve
            | "defeq" | "definitional-equality" -> CompilerKernelV2.WorkDefEq
            | "lower" | "lowering" -> CompilerKernelV2.WorkLower
            | "codegen" | "emit" -> CompilerKernelV2.WorkCodegen
            | "artifact" | "writer" -> CompilerKernelV2.WorkArtifact
            | "terminal" | "terminalize" -> CompilerKernelV2.WorkTerminalize
            | "join-point-specialization" | "specialize" -> CompilerKernelV2.WorkSpecialize
            | _ -> CompilerKernelV2.WorkElaborate

        let compilerPhaseDurationSampleSourceText = function
            | CompilerPhaseDurationWorkUnit -> "work_unit"
            | CompilerPhaseDurationPhaseInterval -> "phase_interval"
            | CompilerPhaseDurationImportedReceipt -> "imported_receipt"

        type private CompilerPhaseIntervalState =
            | CompilerPhaseIntervalAwaitingFirstObservation
            | CompilerPhaseIntervalActive of phase:CompilerKernelV2.CompilerWorkPhase * startedAtMs:int64

        let private jpDurationPhaseBridgeGate = obj()
        let mutable private jpDurationPhaseBridgeSamples : CompilerPhaseDurationSample list = []
        let mutable private compilerPhaseIntervalState = CompilerPhaseIntervalAwaitingFirstObservation

        let private appendCompilerPhaseDurationSample source phase shape site durationMs =
            let durationMs = max 0L durationMs
            let shapeId = CompilerIdentityKernel.WorkShapeIdOps.create shape
            let siteId = CompilerIdentityKernel.WorkSiteIdOps.create site
            let sample =
                { phase = phase
                  source = source
                  shape = shapeId
                  site = siteId
                  durationMs = durationMs
                  sampleRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "compiler-phase-duration-sample"
                        (CompilerKernelV2.compilerWorkPhaseStableText phase
                         + "|source=" + compilerPhaseDurationSampleSourceText source
                         + "|shape=" + shape
                         + "|site=" + site
                         + "|duration=" + string durationMs) }
            lock jpDurationPhaseBridgeGate (fun () ->
                jpDurationPhaseBridgeSamples <- sample :: jpDurationPhaseBridgeSamples |> List.truncate 16384)

        let noteJpDurationPhaseSample (shape:string) (site:string) (durationMs:int64) =
            let phase = compilerPhaseForDurationSample shape site
            appendCompilerPhaseDurationSample CompilerPhaseDurationWorkUnit phase shape site durationMs

        let noteCompilerPhaseIntervalSample phase observedAtMs =
            let completedInterval =
                lock jpDurationPhaseBridgeGate (fun () ->
                    match compilerPhaseIntervalState with
                    | CompilerPhaseIntervalAwaitingFirstObservation ->
                        compilerPhaseIntervalState <- CompilerPhaseIntervalActive(phase, observedAtMs)
                        None
                    | CompilerPhaseIntervalActive(currentPhase, _) when currentPhase = phase ->
                        None
                    | CompilerPhaseIntervalActive(currentPhase, startedAtMs) ->
                        compilerPhaseIntervalState <- CompilerPhaseIntervalActive(phase, observedAtMs)
                        Some(currentPhase, max 0L (observedAtMs - startedAtMs)))
            match completedInterval with
            | None -> ()
            | Some(completedPhase, durationMs) ->
                appendCompilerPhaseDurationSample
                    CompilerPhaseDurationPhaseInterval
                    completedPhase
                    "phase-interval"
                    (CompilerKernelV2.compilerWorkPhaseStableText completedPhase)
                    durationMs

        let jpDurationPhaseSamplesSnapshot () =
            lock jpDurationPhaseBridgeGate (fun () -> List.rev jpDurationPhaseBridgeSamples)

        type BigStackJoinLocalProgressKind =
            | BigStackJoinLocalNodeDeclared
            | BigStackJoinLocalNodeRunnable
            | BigStackJoinLocalNodeRunning
            | BigStackJoinLocalNodeProduced
            | BigStackJoinLocalNodeBlocked
            | BigStackJoinLocalNodeRetired
            | BigStackJoinLocalSemanticFact
            | BigStackJoinLocalClosureCapture

        type BigStackJoinLocalEvidenceSnapshot = {
            joinRef : CompilerIdentityKernel.ContentDigest
            declaredCount : int64
            runnableCount : int64
            runningCount : int64
            producedCount : int64
            blockedCount : int64
            retiredCount : int64
            semanticFactCount : int64
            closureCaptureCount : int64
            revision : int64
            evidenceRef : CompilerIdentityKernel.ContentDigest
        }

        type BigStackJoinLocalEvidenceDelta =
            | BigStackJoinLocalEvidenceUnchanged of BigStackJoinLocalEvidenceSnapshot
            | BigStackJoinLocalEvidenceAdvanced of producedDelta:int64 * retiredDelta:int64 * semanticFactDelta:int64 * closureCaptureDelta:int64 * current:BigStackJoinLocalEvidenceSnapshot
            | BigStackJoinLocalEvidenceCompleted of BigStackJoinLocalEvidenceSnapshot

        type BigStackJoinEvidenceContext = private BigStackJoinEvidenceContext of CompilerIdentityKernel.ContentDigest

        let private bigStackJoinLocalEvidenceGate = obj()
        let mutable private bigStackJoinLocalEvidence : Map<CompilerIdentityKernel.ContentDigest,BigStackJoinLocalEvidenceSnapshot> = Map.empty

        let private bigStackJoinLocalEvidenceRef snapshot =
            CompilerIdentityKernel.ContentDigest.ofText
                "bigstack-join-local-evidence"
                (CompilerIdentityKernel.ContentDigest.text snapshot.joinRef
                 + "|declared=" + string snapshot.declaredCount
                 + "|runnable=" + string snapshot.runnableCount
                 + "|running=" + string snapshot.runningCount
                 + "|produced=" + string snapshot.producedCount
                 + "|blocked=" + string snapshot.blockedCount
                 + "|retired=" + string snapshot.retiredCount
                 + "|semantic=" + string snapshot.semanticFactCount
                 + "|closures=" + string snapshot.closureCaptureCount
                 + "|revision=" + string snapshot.revision)

        let private bigStackJoinLocalZero joinRef =
            let seed =
                { joinRef = joinRef
                  declaredCount = 0L
                  runnableCount = 0L
                  runningCount = 0L
                  producedCount = 0L
                  blockedCount = 0L
                  retiredCount = 0L
                  semanticFactCount = 0L
                  closureCaptureCount = 0L
                  revision = 0L
                  evidenceRef = CompilerIdentityKernel.ContentDigest.ofText "bigstack-join-local-evidence-zero" "" }
            { seed with evidenceRef = bigStackJoinLocalEvidenceRef seed }

        let bigStackJoinEvidenceContext joinRef : BigStackJoinEvidenceContext =
            lock bigStackJoinLocalEvidenceGate (fun () ->
                if not (Map.containsKey joinRef bigStackJoinLocalEvidence) then
                    bigStackJoinLocalEvidence <- Map.add joinRef (bigStackJoinLocalZero joinRef) bigStackJoinLocalEvidence)
            BigStackJoinEvidenceContext joinRef

        let bigStackJoinEvidenceContextRef (BigStackJoinEvidenceContext joinRef) = joinRef

        let noteBigStackJoinLocalProgress
            (context:BigStackJoinEvidenceContext option)
            kind =
            match context with
            | None -> ()
            | Some (BigStackJoinEvidenceContext joinRef) ->
                lock bigStackJoinLocalEvidenceGate (fun () ->
                    let prior = Map.tryFind joinRef bigStackJoinLocalEvidence |> Option.defaultWith (fun () -> bigStackJoinLocalZero joinRef)
                    let next =
                        match kind with
                        | BigStackJoinLocalNodeDeclared -> { prior with declaredCount = prior.declaredCount + 1L; revision = prior.revision + 1L }
                        | BigStackJoinLocalNodeRunnable -> { prior with runnableCount = prior.runnableCount + 1L; revision = prior.revision + 1L }
                        | BigStackJoinLocalNodeRunning -> { prior with runningCount = prior.runningCount + 1L; revision = prior.revision + 1L }
                        | BigStackJoinLocalNodeProduced -> { prior with producedCount = prior.producedCount + 1L; revision = prior.revision + 1L }
                        | BigStackJoinLocalNodeBlocked -> { prior with blockedCount = prior.blockedCount + 1L; revision = prior.revision + 1L }
                        | BigStackJoinLocalNodeRetired -> { prior with retiredCount = prior.retiredCount + 1L; revision = prior.revision + 1L }
                        | BigStackJoinLocalSemanticFact -> { prior with semanticFactCount = prior.semanticFactCount + 1L; revision = prior.revision + 1L }
                        | BigStackJoinLocalClosureCapture -> { prior with closureCaptureCount = prior.closureCaptureCount + 1L; revision = prior.revision + 1L }
                    let next = { next with evidenceRef = bigStackJoinLocalEvidenceRef next }
                    bigStackJoinLocalEvidence <- Map.add joinRef next bigStackJoinLocalEvidence)

        let bigStackJoinLocalEvidenceSnapshot (BigStackJoinEvidenceContext joinRef) =
            lock bigStackJoinLocalEvidenceGate (fun () ->
                Map.tryFind joinRef bigStackJoinLocalEvidence |> Option.defaultWith (fun () -> bigStackJoinLocalZero joinRef))

        let bigStackJoinLocalEvidenceDelta baseline current =
            let producedDelta = max 0L (current.producedCount - baseline.producedCount)
            let retiredDelta = max 0L (current.retiredCount - baseline.retiredCount)
            let semanticFactDelta = max 0L (current.semanticFactCount - baseline.semanticFactCount)
            let closureCaptureDelta = max 0L (current.closureCaptureCount - baseline.closureCaptureCount)
            if current.revision = baseline.revision then BigStackJoinLocalEvidenceUnchanged current
            elif retiredDelta > 0L && current.runningCount <= current.retiredCount then BigStackJoinLocalEvidenceCompleted current
            else BigStackJoinLocalEvidenceAdvanced(producedDelta, retiredDelta, semanticFactDelta, closureCaptureDelta, current)

        // The per-phase denominator may be provisional while discovery is open.
        // Discovery close can precede the last per-block parsed-AST seed notification,
        // so the frozen value may only refine monotonically when a larger structural
        // seed arrives. A discovered-work counter is never relabelled as a static seed.
        type PhaseSeedAuthorityId =
            | PhaseSeedProvisionalOpenGraphEstimate
            | PhaseSeedAwaitingParsedAstNonDegenerateSeed
            | PhaseSeedRefinedAfterDiscoveryClose of priorSeed:int64 * refinedSeed:int64
            | PhaseSeedFrozenAfterDiscoveryClose

        let private phaseSeedAuthorityText = function
            | PhaseSeedProvisionalOpenGraphEstimate -> "provisional_open_graph_estimate"
            | PhaseSeedAwaitingParsedAstNonDegenerateSeed -> "awaiting_parsed_ast_non_degenerate_seed"
            | PhaseSeedRefinedAfterDiscoveryClose(priorSeed, refinedSeed) ->
                sprintf "refined_after_discovery_close(prior=%d|current=%d)" priorSeed refinedSeed
            | PhaseSeedFrozenAfterDiscoveryClose -> "frozen_after_discovery_close"

        let private phaseSeedAuthorityIsFrozen = function
            | PhaseSeedFrozenAfterDiscoveryClose -> true
            | PhaseSeedProvisionalOpenGraphEstimate
            | PhaseSeedAwaitingParsedAstNonDegenerateSeed
            | PhaseSeedRefinedAfterDiscoveryClose _ -> false

        type ParsedAstStructuralSeedBreakdown = {
            topLevelBindings : int64
            functionDefinitions : int64
            typeDefinitions : int64
            realBlocks : int64
            joinPoints : int64
            imports : int64
        }

        type ParsedAstStructuralSeedIncrementId =
            | ParsedAstSeedFunctionDefinition
            | ParsedAstSeedTopLevelBinding
            | ParsedAstSeedTypeDefinition
            | ParsedAstSeedRealBlock
            | ParsedAstSeedJoinPoint
            | ParsedAstSeedImport

        let parsedAstStructuralSeedZero : ParsedAstStructuralSeedBreakdown =
            { topLevelBindings = 0L
              functionDefinitions = 0L
              typeDefinitions = 0L
              realBlocks = 0L
              joinPoints = 0L
              imports = 0L }

        let parsedAstStructuralSeedAdd
            (left:ParsedAstStructuralSeedBreakdown)
            (right:ParsedAstStructuralSeedBreakdown)
            : ParsedAstStructuralSeedBreakdown =
            { topLevelBindings = left.topLevelBindings + right.topLevelBindings
              functionDefinitions = left.functionDefinitions + right.functionDefinitions
              typeDefinitions = left.typeDefinitions + right.typeDefinitions
              realBlocks = left.realBlocks + right.realBlocks
              joinPoints = left.joinPoints + right.joinPoints
              imports = left.imports + right.imports }

        let parsedAstStructuralSeedIncrementBy
            count
            increment
            (value:ParsedAstStructuralSeedBreakdown)
            : ParsedAstStructuralSeedBreakdown =
            let count = max 0L count
            match increment with
            | ParsedAstSeedFunctionDefinition ->
                { value with functionDefinitions = value.functionDefinitions + count }
            | ParsedAstSeedTopLevelBinding ->
                { value with topLevelBindings = value.topLevelBindings + count }
            | ParsedAstSeedTypeDefinition ->
                { value with typeDefinitions = value.typeDefinitions + count }
            | ParsedAstSeedRealBlock ->
                { value with realBlocks = value.realBlocks + count }
            | ParsedAstSeedJoinPoint ->
                { value with joinPoints = value.joinPoints + count }
            | ParsedAstSeedImport ->
                { value with imports = value.imports + count }

        let parsedAstStructuralSeedIncrement increment value =
            parsedAstStructuralSeedIncrementBy 1L increment value

        let private phaseSeedAuthorityGate = obj()
        let mutable private phaseSeedParsedAstTotalCandidate : int64 option = None
        let mutable private phaseSeedTotalAfterParse : int64 option = None
        let mutable private parsedAstStructuralSeedByBlock =
            System.Collections.Generic.Dictionary<uint32, ParsedAstStructuralSeedBreakdown>()

        let private parsedAstStructuralSeedTotal (value:ParsedAstStructuralSeedBreakdown) =
            value.topLevelBindings
            + value.functionDefinitions
            + value.typeDefinitions
            + value.realBlocks
            + value.joinPoints
            + value.imports

        let noteParsedAstStructuralSeed blockRef (value:ParsedAstStructuralSeedBreakdown) =
            lock phaseSeedAuthorityGate (fun () ->
                parsedAstStructuralSeedByBlock.[blockRef] <- value
                let total =
                    parsedAstStructuralSeedByBlock.Values
                    |> Seq.sumBy parsedAstStructuralSeedTotal
                    |> max 0L
                if total > 1L then phaseSeedParsedAstTotalCandidate <- Some total
                total)

        let parsedAstStructuralSeedSnapshot () =
            lock phaseSeedAuthorityGate (fun () ->
                let aggregate =
                    parsedAstStructuralSeedByBlock.Values
                    |> Seq.fold parsedAstStructuralSeedAdd parsedAstStructuralSeedZero
                aggregate, parsedAstStructuralSeedTotal aggregate)

        let phaseSeedSnapshot discoveryClosed candidateTotal =
            let candidateTotal = max 1L candidateTotal
            lock phaseSeedAuthorityGate (fun () ->
                match phaseSeedTotalAfterParse, phaseSeedParsedAstTotalCandidate, discoveryClosed with
                | Some frozen, Some parsedSeed, true when parsedSeed > frozen ->
                    phaseSeedTotalAfterParse <- Some parsedSeed
                    parsedSeed, PhaseSeedRefinedAfterDiscoveryClose(frozen, parsedSeed)
                | Some frozen, _, _ -> frozen, PhaseSeedFrozenAfterDiscoveryClose
                | None, Some parsedSeed, true ->
                    phaseSeedTotalAfterParse <- Some parsedSeed
                    parsedSeed, PhaseSeedFrozenAfterDiscoveryClose
                | None, Some parsedSeed, false ->
                    max candidateTotal parsedSeed, PhaseSeedProvisionalOpenGraphEstimate
                | None, None, true -> candidateTotal, PhaseSeedAwaitingParsedAstNonDegenerateSeed
                | None, None, false -> candidateTotal, PhaseSeedProvisionalOpenGraphEstimate)

        let semanticFactStableRef (scope:string) (value:string) =
            let digest =
                CompilerIdentityKernel.ContentDigest.ofText scope value
                |> CompilerIdentityKernel.ContentDigest.text
            let hex = if digest.Length >= 8 then digest.Substring(0,8) else digest.PadRight(8,'0')
            System.UInt32.Parse(hex, System.Globalization.NumberStyles.HexNumber, System.Globalization.CultureInfo.InvariantCulture)

        // MIGRATION: diagnostic JSON is an erasure boundary, not a construction API.
        // Kernel code builds a typed event and this renderer alone owns field names,
        // quoting and kind strings. Raw sprintf JSON remains legacy telemetry debt.
        type DiagnosticEventKind =
            | DiagnosticIngressClassified
            | DiagnosticIngressUnclassified
            | DiagnosticBuildErrorTraceConsole
            | DiagnosticBuildErrorTraceSidecarOnly
            | DiagnosticBuildTerminalityClassified
            | DiagnosticTerminalCollapse
            | DiagnosticRetryDecision

        type DiagnosticEventValue =
            | DiagnosticString of string
            | DiagnosticInt of int
            | DiagnosticInt64 of int64
            | DiagnosticUInt32 of uint32
            | DiagnosticBool of bool
            | DiagnosticStringList of string list

        type DiagnosticFieldKey =
            | DiagnosticFieldMessage
            | DiagnosticFieldDiagnosticCodeId
            | DiagnosticFieldDiagnosticCause
            | DiagnosticFieldDiagnosticDisposition
            | DiagnosticFieldDiagnosticFacts
            | DiagnosticFieldBuildErrorTraceId
            | DiagnosticFieldTerminalCommitReceiptId
            | DiagnosticFieldRootPromiseTransition
            | DiagnosticFieldSchedulerOwnedRootTransition
            | DiagnosticFieldRootCompleteAltAuthority
            | DiagnosticFieldTerminalRootReceiptGate
            | DiagnosticFieldBuildErrorTraceAuthority
            | DiagnosticFieldRootTerminalOutcome
            | DiagnosticFieldFailClosedExitAuthority
            | DiagnosticFieldArmedWaitGraphSpine
            | DiagnosticFieldSchedulerPushEvent
            | DiagnosticFieldSchedulerPushAuthority
            | DiagnosticFieldBreakthroughExitArbiter
            | DiagnosticFieldTerminalAuthorityMigrationStatus
            | DiagnosticFieldNativeTerminalExitContract
            | DiagnosticFieldJsonlValidity
            | DiagnosticFieldTraceId
            | DiagnosticFieldCode
            | DiagnosticFieldTraceLines
            | DiagnosticFieldPolicy
            | DiagnosticFieldNext
            | DiagnosticFieldPayloadKind
            | DiagnosticFieldTerminalityDecision
            | DiagnosticFieldDispositionPayloadConflict
            | DiagnosticFieldFinishFastTerminal
            | DiagnosticFieldAuthority
            | DiagnosticFieldSource
            | DiagnosticFieldEvent
            | DiagnosticFieldTerminalKind
            | DiagnosticFieldAttempt
            | DiagnosticFieldMaxAttempts
            | DiagnosticFieldFile
            | DiagnosticFieldBackend
            | DiagnosticFieldRootPromiseStatus
            | DiagnosticFieldRootCompleteAwaitContract
            | DiagnosticFieldRootCompleteExitPolicy
            | DiagnosticFieldRootCompleteCollapseDecision
            | DiagnosticFieldNativePromiseFateFinalVerdict
            | DiagnosticFieldNativeJobGraph
            | DiagnosticFieldTypedTerminalPayload
            | DiagnosticFieldMinimalToRichPayloadStatus
            | DiagnosticFieldSemanticDiagnosis
            | DiagnosticFieldSemanticErrorPayload
            | DiagnosticFieldSourceSpanEnrichment
            | DiagnosticFieldHopacRootExitVerdict
            | DiagnosticFieldTrampolineBypassStatus
            | DiagnosticFieldTerminalReceiptDurability
            | DiagnosticFieldRetrySuppressed
            | DiagnosticFieldSingleFlight

        let diagnosticFieldKeyText = function
            | DiagnosticFieldMessage -> "message"
            | DiagnosticFieldDiagnosticCodeId -> "diagnostic_code_id"
            | DiagnosticFieldDiagnosticCause -> "diagnostic_cause_du"
            | DiagnosticFieldDiagnosticDisposition -> "diagnostic_disposition_du"
            | DiagnosticFieldDiagnosticFacts -> "diagnostic_facts_du"
            | DiagnosticFieldBuildErrorTraceId -> "build_error_trace_id"
            | DiagnosticFieldTerminalCommitReceiptId -> "terminal_commit_receipt_id"
            | DiagnosticFieldRootPromiseTransition -> "root_promise_transition_du"
            | DiagnosticFieldSchedulerOwnedRootTransition -> "scheduler_owned_root_transition_du"
            | DiagnosticFieldRootCompleteAltAuthority -> "root_complete_alt_authority_du"
            | DiagnosticFieldTerminalRootReceiptGate -> "terminal_root_receipt_gate_du"
            | DiagnosticFieldBuildErrorTraceAuthority -> "build_error_trace_authority_du"
            | DiagnosticFieldRootTerminalOutcome -> "root_terminal_outcome_du"
            | DiagnosticFieldFailClosedExitAuthority -> "fail_closed_exit_authority_du"
            | DiagnosticFieldArmedWaitGraphSpine -> "armed_wait_graph_spine_du"
            | DiagnosticFieldSchedulerPushEvent -> "scheduler_push_event_du"
            | DiagnosticFieldSchedulerPushAuthority -> "scheduler_push_authority_du"
            | DiagnosticFieldBreakthroughExitArbiter -> "breakthrough_exit_arbiter_du"
            | DiagnosticFieldTerminalAuthorityMigrationStatus -> "terminal_authority_migration_status_du"
            | DiagnosticFieldNativeTerminalExitContract -> "native_terminal_exit_contract_du"
            | DiagnosticFieldJsonlValidity -> "jsonl_validity"
            | DiagnosticFieldTraceId -> "trace_id"
            | DiagnosticFieldCode -> "code"
            | DiagnosticFieldTraceLines -> "trace_lines"
            | DiagnosticFieldPolicy -> "policy"
            | DiagnosticFieldNext -> "next"
            | DiagnosticFieldPayloadKind -> "payload_kind_du"
            | DiagnosticFieldTerminalityDecision -> "terminality_decision_du"
            | DiagnosticFieldDispositionPayloadConflict -> "disposition_payload_conflict_du"
            | DiagnosticFieldFinishFastTerminal -> "finish_fast_terminal"
            | DiagnosticFieldAuthority -> "authority"
            | DiagnosticFieldSource -> "source"
            | DiagnosticFieldEvent -> "event"
            | DiagnosticFieldTerminalKind -> "terminal_kind_du"
            | DiagnosticFieldAttempt -> "attempt"
            | DiagnosticFieldMaxAttempts -> "max_attempts"
            | DiagnosticFieldFile -> "file"
            | DiagnosticFieldBackend -> "backend"
            | DiagnosticFieldRootPromiseStatus -> "root_promise_status"
            | DiagnosticFieldRootCompleteAwaitContract -> "root_complete_await_contract_du"
            | DiagnosticFieldRootCompleteExitPolicy -> "root_complete_exit_policy_du"
            | DiagnosticFieldRootCompleteCollapseDecision -> "root_complete_collapse_decision_du"
            | DiagnosticFieldNativePromiseFateFinalVerdict -> "native_promise_fate_final_verdict_du"
            | DiagnosticFieldNativeJobGraph -> "native_job_graph"
            | DiagnosticFieldTypedTerminalPayload -> "typed_terminal_payload_du"
            | DiagnosticFieldMinimalToRichPayloadStatus -> "minimal_to_rich_payload_status_du"
            | DiagnosticFieldSemanticDiagnosis -> "semantic_diagnosis"
            | DiagnosticFieldSemanticErrorPayload -> "semantic_error_payload"
            | DiagnosticFieldSourceSpanEnrichment -> "source_span_enrichment_du"
            | DiagnosticFieldHopacRootExitVerdict -> "hopac_root_exit_verdict"
            | DiagnosticFieldTrampolineBypassStatus -> "trampoline_bypass_status"
            | DiagnosticFieldTerminalReceiptDurability -> "terminal_receipt_durability_du"
            | DiagnosticFieldRetrySuppressed -> "retry_suppressed"
            | DiagnosticFieldSingleFlight -> "single_flight"

        type DiagnosticEventField = private DiagnosticEventField of DiagnosticFieldKey * DiagnosticEventValue

        type DiagnosticEvent = private {
            eventKind : DiagnosticEventKind
            fields : DiagnosticEventField list
        }

        let diagnosticEvent kind = { eventKind = kind; fields = [] }
        let diagnosticStringKey key value event = { event with fields = DiagnosticEventField(key, DiagnosticString value) :: event.fields }
        let diagnosticIntKey key value event = { event with fields = DiagnosticEventField(key, DiagnosticInt value) :: event.fields }
        let diagnosticInt64Key key value event = { event with fields = DiagnosticEventField(key, DiagnosticInt64 value) :: event.fields }
        let diagnosticUInt32Key key value event = { event with fields = DiagnosticEventField(key, DiagnosticUInt32 value) :: event.fields }
        let diagnosticBoolKey key value event = { event with fields = DiagnosticEventField(key, DiagnosticBool value) :: event.fields }
        let diagnosticStringListKey key value event = { event with fields = DiagnosticEventField(key, DiagnosticStringList value) :: event.fields }

        let diagnosticEventKindText = function
            | DiagnosticIngressClassified -> "diagnostic_ingress_classified"
            | DiagnosticIngressUnclassified -> "diagnostic_ingress_unclassified"
            | DiagnosticBuildErrorTraceConsole -> "build_error_trace_console"
            | DiagnosticBuildErrorTraceSidecarOnly -> "build_error_trace_traced_error_sidecar_only"
            | DiagnosticBuildTerminalityClassified -> "build_trace_terminality_classified"
            | DiagnosticTerminalCollapse -> "terminal_collapse_to_build_error_trace"
            | DiagnosticRetryDecision -> "build_retry_diagnostic_decision"

        let private diagnosticEventValueJson = function
            | DiagnosticString value -> esc value
            | DiagnosticInt value -> string value
            | DiagnosticInt64 value -> string value
            | DiagnosticUInt32 value -> string value
            | DiagnosticBool value -> if value then "true" else "false"
            | DiagnosticStringList values ->
                values |> List.map esc |> String.concat "," |> fun body -> "[" + body + "]"

        let renderDiagnosticEvent event =
            let fieldJson =
                event.fields
                |> List.rev
                |> List.map (fun (DiagnosticEventField(key, value)) -> esc (diagnosticFieldKeyText key) + ":" + diagnosticEventValueJson value)
            let body =
                ("\"kind\":" + esc (diagnosticEventKindText event.eventKind)) :: fieldJson
                |> String.concat ","
            "{" + body + "}"

        type JsonObjectEnvelopeId =
            | JsonEnvelopeV1Object
            | JsonEnvelopeObject
            | JsonEnvelopeOther

        let private jsonObjectEnvelopeId (line:string) =
            if System.Object.ReferenceEquals(line, null) || line.Length < 2 then JsonEnvelopeOther
            elif line.[0] <> '{' || line.[line.Length - 1] <> '}' then JsonEnvelopeOther
            elif line.Length >= 7 && String.Compare(line, 0, "{\"v\":1,", 0, 7, StringComparison.Ordinal) = 0 then JsonEnvelopeV1Object
            else JsonEnvelopeObject

        type JsonScalarValueHeadId =
            | JsonScalarValueEmpty
            | JsonScalarValueQuoted
            | JsonScalarValueBare

        let private jsonScalarValueHeadId (value:string) =
            if String.IsNullOrEmpty value then JsonScalarValueEmpty
            elif value.[0] = '"' then JsonScalarValueQuoted
            else JsonScalarValueBare

        let private jsonScalarField (key: string) (line: string) =
            try
                let needle = "\"" + key + "\":"
                let parts = line.Split([|needle|], 2, StringSplitOptions.None)
                if parts.Length <> 2 then ""
                else
                    let rest = parts.[1].TrimStart()
                    match jsonScalarValueHeadId rest with
                    | JsonScalarValueQuoted ->
                        let mutable i = 1
                        let mutable escaped = false
                        while i < rest.Length && (escaped || rest.[i] <> '\"') do
                            escaped <- (not escaped && rest.[i] = '\\')
                            if rest.[i] <> '\\' then escaped <- false
                            i <- i + 1
                        if i < rest.Length then rest.Substring(1, i - 1) else ""
                    | JsonScalarValueBare ->
                        let mutable endi = 0
                        while endi < rest.Length && rest.[endi] <> ',' && rest.[endi] <> '}' do
                            endi <- endi + 1
                        if endi > 0 then rest.Substring(0, endi).Trim().Trim([|'\"'|]) else ""
                    | JsonScalarValueEmpty -> ""
            with _ -> ""

        let private jsonHasField (key:string) (line:string) =
            not (System.Object.ReferenceEquals(line, null))
            && line.IndexOf("\"" + key + "\":", StringComparison.Ordinal) >= 0

        type JsonFieldPresenceId =
            | JsonFieldPresent
            | JsonFieldAbsent

        let private jsonFieldPresenceId (key:string) (line:string) =
            if jsonHasField key line then JsonFieldPresent else JsonFieldAbsent

        let private firstField (keys: string list) (line: string) =
            keys
            |> List.tryPick (fun key ->
                let v = jsonScalarField key line
                if String.IsNullOrWhiteSpace v then None else Some v)
            |> function
                | Some v -> v
                | None -> ""

        let private run_id = System.Guid.NewGuid().ToString("N")

        // MIGRATION: publisher lifecycle rows live before the full DiagJson.emit
        // pipeline is defined.  Keep those early rows as inert projections here;
        // the authoritative reducer/command rows still use DiagJson.emit after
        // the module-level emitter exists.  This avoids illegal forward/self
        // references while preserving the typed publisher bridge.
        let private emitEarlyPublisherProjection (json: string) =
            try DiagSidecar.emit json with _ -> ()

        // Canonical root authority. Root resolution is a single-assignment fact;
        // HUD strings and owner-debt observations may project it but cannot mint it.
        [<Struct>]
        type CanonicalRootReceiptId = private CanonicalRootReceiptId of string

        type CanonicalRootReceiptSource =
            | CanonicalRootEvaluator
            | CanonicalRootTerminalBridge
            | CanonicalRootFailClosed

        let private canonicalRootReceiptSourceText = function
            | CanonicalRootEvaluator -> "evaluator"
            | CanonicalRootTerminalBridge -> "terminal-bridge"
            | CanonicalRootFailClosed -> "fail-closed"

        type CanonicalRootReceipt = private {
            receiptId : CanonicalRootReceiptId
            source : CanonicalRootReceiptSource
            resolvedAtMs : int64
            evidenceRef : uint32
        }

        type CanonicalRootAuthorityPhase =
            | CanonicalRootUnarmed
            | CanonicalRootArmed of armedAtMs:int64 * evidenceRef:uint32
            | CanonicalRootResolved of CanonicalRootReceipt

        type CanonicalRootAuthoritySnapshot = {
            phase : CanonicalRootAuthorityPhase
            receiptId : string
            source : string
            resolvedAtMs : int64
            evidenceRef : uint32
        }

        // Destructive domain migration round : evaluator root resolution is a typed
        // transaction that can publish exactly-once dataflow notices.  The
        // publisher is installed by TerminalFlow after its channel exists;
        // HUD/JSON remain projections and cannot resolve root truth.
        type CanonicalRootResolutionNotice = {
            receiptId : string
            source : CanonicalRootReceiptSource
            resolvedAtMs : int64
            evidenceRef : uint32
            resolvedNow : bool
        }

        type EvaluatorRootCommitRejectionReasonId =
            | EvaluatorRootReceiptNotMinted
            | EvaluatorCanonicalRootNotResolvedAfterCommit

        let evaluatorRootCommitRejectionReasonText = function
            | EvaluatorRootReceiptNotMinted -> "evaluator_root_receipt_not_minted"
            | EvaluatorCanonicalRootNotResolvedAfterCommit -> "canonical_root_not_resolved_after_evaluator_commit"

        type EvaluatorRootCommitResult =
            | EvaluatorRootCommittedNow of receiptId:string * resolvedAtMs:int64 * evidenceRef:uint32
            | EvaluatorRootAlreadyCommitted of receiptId:string * resolvedAtMs:int64 * evidenceRef:uint32
            | EvaluatorRootCommitRejected of EvaluatorRootCommitRejectionReasonId

        let evaluatorRootCommitResultText = function
            | EvaluatorRootCommittedNow(receiptId, resolvedAtMs, evidenceRef) ->
                FastRuntimeFormat.format "EvaluatorRootCommittedNow(receipt_ref=%u|resolved_at_ms=%d|evidence_ref=%u)" [| box (semanticFactStableRef "evaluator-root-commit-receipt" receiptId); box resolvedAtMs; box evidenceRef |]
            | EvaluatorRootAlreadyCommitted(receiptId, resolvedAtMs, evidenceRef) ->
                FastRuntimeFormat.format "EvaluatorRootAlreadyCommitted(receipt_ref=%u|resolved_at_ms=%d|evidence_ref=%u)" [| box (semanticFactStableRef "evaluator-root-commit-receipt" receiptId); box resolvedAtMs; box evidenceRef |]
            | EvaluatorRootCommitRejected reason ->
                let reasonText = evaluatorRootCommitRejectionReasonText reason
                sprintf "EvaluatorRootCommitRejected(reason_ref=%u)"
                    (semanticFactStableRef "evaluator-root-commit-rejection" reasonText)

        let private canonicalRootResolutionPublisherGate = obj()
        let private canonicalRootResolutionPending = System.Collections.Concurrent.ConcurrentQueue<CanonicalRootResolutionNotice>()
        let mutable private canonicalRootResolutionPublisherInstalled = false
        let mutable private canonicalRootResolutionPublisher : (CanonicalRootResolutionNotice -> unit) = ignore

        let private canonicalRootResolutionDrainTo publisher =
            let mutable keepDraining = true
            while keepDraining do
                let mutable notice = Unchecked.defaultof<CanonicalRootResolutionNotice>
                if canonicalRootResolutionPending.TryDequeue(&notice) then publisher notice
                else keepDraining <- false

        let canonicalRootAuthorityInstallResolutionPublisher publisher =
            let pendingBefore = canonicalRootResolutionPending.Count
            lock canonicalRootResolutionPublisherGate (fun () ->
                canonicalRootResolutionPublisher <- publisher
                canonicalRootResolutionPublisherInstalled <- true)
            emitEarlyPublisherProjection (
                sprintf "{\"kind\":\"terminal_flow_publisher_installed\",\"publisher\":\"canonical_root\",\"pending_before\":%d,\"bridge_authority\":\"typed_reducer_event_bridge\",\"polling_authority\":false}"
                    pendingBefore)
            canonicalRootResolutionDrainTo publisher
            emitEarlyPublisherProjection (
                sprintf "{\"kind\":\"terminal_flow_publisher_drain_complete\",\"publisher\":\"canonical_root\",\"pending_after\":%d,\"bridge_authority\":\"typed_reducer_event_bridge\",\"polling_authority\":false}"
                    canonicalRootResolutionPending.Count)

        let private canonicalRootAuthorityPublishResolution notice =
            let installed, publisher =
                lock canonicalRootResolutionPublisherGate (fun () -> canonicalRootResolutionPublisherInstalled, canonicalRootResolutionPublisher)
            emitEarlyPublisherProjection (
                FastRuntimeFormat.format "{\"kind\":\"terminal_flow_publisher_notice\",\"publisher\":\"canonical_root\",\"installed\":%b,\"receipt_ref\":%u,\"evidence_ref\":%u,\"pending_before\":%d,\"bridge_authority\":\"typed_reducer_event_bridge\"}" [| box installed; box (semanticFactStableRef "canonical-root-resolution-notice" notice.receiptId); box notice.evidenceRef; box canonicalRootResolutionPending.Count |])
            if installed then publisher notice
            else canonicalRootResolutionPending.Enqueue notice

        // MIGRATION: legacy owner-drain terminal receipts are no longer allowed
        // to remain renderer-only rows. Earlier evaluator code can publish a
        // terminal outcome candidate through this erased hook; TerminalFlow
        // installs the typed reducer bridge after its DUs and channel exist.
        type TerminalOutcomeCandidateIntent =
            | TerminalOutcomeCandidateBuildOk
            | TerminalOutcomeCandidateQuarantine
            | TerminalOutcomeCandidateFailClosed
            | TerminalOutcomeCandidateSafetyWatchdogFailClosed

        type TerminalOutcomeCandidateDeliveryDecision =
            | TerminalOutcomeCandidateAwaitPublisher
            | TerminalOutcomeCandidateDeliverySuppressed of retryAfterMs:int64
            | TerminalOutcomeCandidateDelivered of redrive:bool
            | TerminalOutcomeCandidatePublisherFaulted of exceptionType:string * message:string

        let private terminalOutcomeCandidateDigest (scope:string) (value:string) =
            CompilerIdentityKernel.ContentDigest.ofText scope (if obj.ReferenceEquals(value, null) then "" else value)
            |> CompilerIdentityKernel.ContentDigest.text

        let private terminalOutcomeCandidateStableRef (scope:string) (value:string) =
            let digest = terminalOutcomeCandidateDigest scope value
            let hex = if digest.Length >= 8 then digest.Substring(0, 8) else digest
            System.Convert.ToUInt32(hex, 16)

        let terminalOutcomeCandidateDeliveryDecisionText = function
            | TerminalOutcomeCandidateAwaitPublisher -> "AwaitPublisher"
            | TerminalOutcomeCandidateDeliverySuppressed retryAfterMs -> sprintf "Suppressed(retry_after_ms=%d)" retryAfterMs
            | TerminalOutcomeCandidateDelivered redrive -> sprintf "Delivered(redrive=%b)" redrive
            | TerminalOutcomeCandidatePublisherFaulted(exceptionType, message) ->
                sprintf "PublisherFaulted(type=%s|message_ref=%u)" exceptionType (terminalOutcomeCandidateStableRef "terminal-outcome-publisher-fault-message" message)

        let terminalOutcomeCandidateIntentText = function
            | TerminalOutcomeCandidateBuildOk -> "BuildOk"
            | TerminalOutcomeCandidateQuarantine -> "Quarantine"
            | TerminalOutcomeCandidateFailClosed -> "FailClosed"
            | TerminalOutcomeCandidateSafetyWatchdogFailClosed -> "SafetyWatchdogFailClosed"

        type TerminalOutcomeCandidateNotice = {
            intent : TerminalOutcomeCandidateIntent
            terminalReceiptId : string
            fillKey : string
            reason : CompilerKernelV2.OperationalReasonId
        }

        [<StructuralEquality; NoComparison>]
        type TerminalOutcomeCandidateIdentity = private {
            intent : TerminalOutcomeCandidateIntent
            terminalReceiptRef : CompilerIdentityKernel.ContentDigest
            fillRef : CompilerIdentityKernel.ContentDigest
        }

        let private terminalOutcomeCandidateIdentityFor intent terminalReceiptId fillKey _reason : TerminalOutcomeCandidateIdentity =
            { intent = intent
              terminalReceiptRef = CompilerIdentityKernel.ContentDigest.ofText "terminal-outcome-terminal-receipt" terminalReceiptId
              fillRef = CompilerIdentityKernel.ContentDigest.ofText "terminal-outcome-fill" fillKey }

        let private terminalOutcomeCandidatePublisherGate = obj()
        let private terminalOutcomeCandidatePending = System.Collections.Concurrent.ConcurrentQueue<TerminalOutcomeCandidateNotice>()
        let private terminalOutcomeCandidateNoticeRegistry = System.Collections.Concurrent.ConcurrentDictionary<TerminalOutcomeCandidateIdentity,byte>()
        let private terminalOutcomeCandidateDeliveryRegistry = System.Collections.Concurrent.ConcurrentDictionary<TerminalOutcomeCandidateIdentity,int64>()
        let mutable private terminalOutcomeCandidatePublisherInstalled = false
        let mutable private terminalOutcomeCandidatePublisher : (TerminalOutcomeCandidateNotice -> unit) = ignore

        let private terminalOutcomeCandidatePublisherFaultDetails (error:exn) =
            let errorType = error.GetType()
            let exceptionType =
                if System.String.IsNullOrWhiteSpace(errorType.FullName) then errorType.Name
                else errorType.FullName
            exceptionType, error.Message

        let private terminalOutcomeCandidateDrainTo publisher =
            let pendingAtStart = terminalOutcomeCandidatePending.Count
            let mutable drained = 0
            while drained < pendingAtStart do
                let mutable notice = Unchecked.defaultof<TerminalOutcomeCandidateNotice>
                if terminalOutcomeCandidatePending.TryDequeue(&notice) then
                    drained <- drained + 1
                    try publisher notice
                    with error ->
                        let exceptionType, message = terminalOutcomeCandidatePublisherFaultDetails error
                        terminalOutcomeCandidatePending.Enqueue notice
                        emitEarlyPublisherProjection (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_flow_publisher_drain_fault\",\"publisher\":\"terminal_outcome\",\"exception_type\":%s,\"message_ref\":%u,\"pending_after_requeue\":%d,\"authority\":\"typed_reducer_event_bridge\"}" [| box (esc exceptionType); box (terminalOutcomeCandidateStableRef "terminal-outcome-publisher-drain-fault-message" message); box terminalOutcomeCandidatePending.Count |])
                else drained <- pendingAtStart

        let terminalOutcomeCandidateInstallPublisher publisher =
            let pendingBefore = terminalOutcomeCandidatePending.Count
            lock terminalOutcomeCandidatePublisherGate (fun () ->
                terminalOutcomeCandidatePublisher <- publisher
                terminalOutcomeCandidatePublisherInstalled <- true)
            emitEarlyPublisherProjection (
                sprintf "{\"kind\":\"terminal_flow_publisher_installed\",\"publisher\":\"terminal_outcome\",\"pending_before\":%d,\"bridge_authority\":\"typed_reducer_event_bridge\",\"polling_authority\":false}"
                    pendingBefore)
            terminalOutcomeCandidateDrainTo publisher
            emitEarlyPublisherProjection (
                sprintf "{\"kind\":\"terminal_flow_publisher_drain_complete\",\"publisher\":\"terminal_outcome\",\"pending_after\":%d,\"bridge_authority\":\"typed_reducer_event_bridge\",\"polling_authority\":false}"
                    terminalOutcomeCandidatePending.Count)

        let publishTerminalOutcomeCandidate intent terminalReceiptId fillKey reason =
            let reasonId = CompilerKernelV2.OperationalReasonIdOps.create reason
            let notice = { intent = intent; terminalReceiptId = terminalReceiptId; fillKey = fillKey; reason = reasonId }
            let intentText = terminalOutcomeCandidateIntentText intent
            let identity = terminalOutcomeCandidateIdentityFor intent terminalReceiptId fillKey reason
            let firstNotice = terminalOutcomeCandidateNoticeRegistry.TryAdd(identity, 0uy)
            let nowMs = Environment.TickCount64
            let installed, publisher, deliveryDue, retryAfterMs =
                lock terminalOutcomeCandidatePublisherGate (fun () ->
                    let installed = terminalOutcomeCandidatePublisherInstalled
                    let publisher = terminalOutcomeCandidatePublisher
                    let mutable priorDeliveryMs = 0L
                    let deliveryKnown = terminalOutcomeCandidateDeliveryRegistry.TryGetValue(identity, &priorDeliveryMs)
                    let ageMs = if deliveryKnown then max 0L (nowMs - priorDeliveryMs) else 2000L
                    let deliveryDue = installed && (firstNotice || not deliveryKnown || ageMs >= 2000L)
                    let retryAfterMs = if deliveryDue then 0L else max 0L (2000L - ageMs)
                    installed, publisher, deliveryDue, retryAfterMs)
            if firstNotice || deliveryDue then
                emitEarlyPublisherProjection (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_flow_publisher_notice\",\"publisher\":\"terminal_outcome\",\"installed\":%b,\"intent_du\":%s,\"terminal_receipt_ref\":%u,\"fill_ref\":%u,\"pending_before\":%d,\"reason_ref\":%u,\"delivery_identity_du\":\"intent_plus_terminal_receipt_plus_fill\",\"reason_identity_authority\":false,\"diagnostic_text_authority\":false,\"bridge_authority\":\"typed_reducer_event_bridge\",\"dedupe_first_seen\":%b,\"delivery_due\":%b,\"delivery_redrive\":%b}" [| box installed; box (esc intentText); box (terminalOutcomeCandidateStableRef "terminal-outcome-terminal-receipt" terminalReceiptId); box (terminalOutcomeCandidateStableRef "terminal-outcome-fill" fillKey); box terminalOutcomeCandidatePending.Count; box (terminalOutcomeCandidateStableRef "terminal-outcome-reason" reason); box firstNotice; box deliveryDue; box (deliveryDue && not firstNotice) |])
            if not installed then
                if firstNotice then terminalOutcomeCandidatePending.Enqueue notice
                TerminalOutcomeCandidateAwaitPublisher
            elif not deliveryDue then
                TerminalOutcomeCandidateDeliverySuppressed retryAfterMs
            else
                try
                    publisher notice
                    lock terminalOutcomeCandidatePublisherGate (fun () ->
                        terminalOutcomeCandidateDeliveryRegistry.[identity] <- nowMs)
                    TerminalOutcomeCandidateDelivered(not firstNotice)
                with error ->
                    let exceptionType, message = terminalOutcomeCandidatePublisherFaultDetails error
                    let mutable ignoredDeliveryMs = 0L
                    terminalOutcomeCandidateDeliveryRegistry.TryRemove(identity, &ignoredDeliveryMs) |> ignore
                    emitEarlyPublisherProjection (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_flow_publisher_delivery_fault\",\"publisher\":\"terminal_outcome\",\"intent_du\":%s,\"terminal_receipt_ref\":%u,\"fill_ref\":%u,\"exception_type\":%s,\"message_ref\":%u,\"redrive_immediate\":true,\"authority\":\"typed_reducer_event_bridge\"}" [| box (esc intentText); box (terminalOutcomeCandidateStableRef "terminal-outcome-terminal-receipt" terminalReceiptId); box (terminalOutcomeCandidateStableRef "terminal-outcome-fill" fillKey); box (esc exceptionType); box (terminalOutcomeCandidateStableRef "terminal-outcome-publisher-delivery-fault-message" message) |])
                    TerminalOutcomeCandidatePublisherFaulted(exceptionType, message)

        let publishTerminalOutcomeCandidateObserved intent terminalReceiptId fillKey reason =
            publishTerminalOutcomeCandidate intent terminalReceiptId fillKey reason
            |> ignore

        let private canonicalRootAuthorityGate = obj()
        let private canonicalRootAuthorityCell = Hopac.IVar<CanonicalRootReceipt>()
        let mutable private canonicalRootAuthorityPhase : CanonicalRootAuthorityPhase = CanonicalRootUnarmed

        // MIGRATION round : root authority is evaluator-owned. TerminalFlow,
        // owner-debt and HUD may project the receipt, but the terminal bridge is
        // no longer allowed to mint root truth. The evaluator API below is the
        // only phase that should transition Unarmed/Armed -> Resolved; bridge
        // attempts become divergence receipts until the evaluator fills the IVar.
        type CanonicalRootAuthorityConsumer =
            | CanonicalRootConsumerEvaluator
            | CanonicalRootConsumerTerminalFlow
            | CanonicalRootConsumerOwnerDebt
            | CanonicalRootConsumerHud

        type CanonicalRootAuthorityBridgeDecision =
            | CanonicalRootBridgeAcceptedProjection of receiptId:string
            | CanonicalRootBridgeRejectedAwaitEvaluator of evidence:string
            | CanonicalRootBridgeDiverged of evaluatorReceipt:string * bridgeEvidence:string

        let private canonicalRootAuthorityBridgeDecisionText = function
            | CanonicalRootBridgeAcceptedProjection receiptId ->
                "CanonicalRootBridgeDecision(AcceptedProjection|receipt=" + receiptId + ")"
            | CanonicalRootBridgeRejectedAwaitEvaluator evidence ->
                "CanonicalRootBridgeDecision(RejectedAwaitEvaluator|evidence_ref=" + string (terminalOutcomeCandidateStableRef "canonical-root-bridge-evidence" evidence) + ")"
            | CanonicalRootBridgeDiverged(evaluatorReceipt, bridgeEvidence) ->
                "CanonicalRootBridgeDecision(Diverged|evaluator=" + evaluatorReceipt + "|bridge_ref=" + string (terminalOutcomeCandidateStableRef "canonical-root-bridge-divergence" bridgeEvidence) + ")"

        let private canonicalRootReceiptIdText (CanonicalRootReceiptId value) = value

        type CanonicalRootAuthorityRead = {
            notice : CanonicalRootResolutionNotice
            consumer : CanonicalRootAuthorityConsumer
        }

        let canonicalRootAuthorityAwait consumer : Hopac.Job<CanonicalRootAuthorityRead> =
            job {
                let! receipt = Hopac.IVar.read canonicalRootAuthorityCell
                return {
                    notice = {
                        receiptId = canonicalRootReceiptIdText receipt.receiptId
                        source = receipt.source
                        resolvedAtMs = receipt.resolvedAtMs
                        evidenceRef = receipt.evidenceRef
                        resolvedNow = false
                    }
                    consumer = consumer
                }
            }

        let private canonicalRootStableRef label value =
            CompilerKernelV2.NonZeroRef.derive label [value]
            |> CompilerKernelV2.NonZeroRef.value

        let canonicalRootAuthorityArm evidence =
            lock canonicalRootAuthorityGate (fun () ->
                match canonicalRootAuthorityPhase with
                | CanonicalRootUnarmed ->
                    canonicalRootAuthorityPhase <- CanonicalRootArmed(Environment.TickCount64, canonicalRootStableRef "canonical_root_arm_evidence_ref" evidence)
                    true
                | _ -> false)

        let private canonicalRootAuthorityMint source receiptHint evidence =
            let evidenceRef = canonicalRootStableRef "canonical_root_evidence_ref" evidence
            let receiptRef =
                CompilerKernelV2.NonZeroRef.derive
                    "canonical-root-receipt"
                    [ canonicalRootReceiptSourceText source
                      if String.IsNullOrWhiteSpace receiptHint then "<no-hint>" else receiptHint
                      string evidenceRef ]
                |> CompilerKernelV2.NonZeroRef.value
            { receiptId = CanonicalRootReceiptId("root:" + string receiptRef)
              source = source
              resolvedAtMs = Environment.TickCount64
              evidenceRef = evidenceRef }

        let canonicalRootAuthorityResolveFromEvaluator receiptHint evidence =
            let mutable minted : CanonicalRootReceipt option = None
            let mutable resolvedNow = false
            lock canonicalRootAuthorityGate (fun () ->
                match canonicalRootAuthorityPhase with
                | CanonicalRootResolved receipt -> minted <- Some receipt
                | CanonicalRootUnarmed
                | CanonicalRootArmed _ ->
                    let receipt = canonicalRootAuthorityMint CanonicalRootEvaluator receiptHint evidence
                    canonicalRootAuthorityPhase <- CanonicalRootResolved receipt
                    minted <- Some receipt
                    resolvedNow <- true)
            match minted with
            | None -> ""
            | Some receipt ->
                queue (job {
                    let! _ = Hopac.IVar.tryFill canonicalRootAuthorityCell receipt
                    return ()
                })
                let receiptId = canonicalRootReceiptIdText receipt.receiptId
                if resolvedNow then
                    emitEarlyPublisherProjection (
                        sprintf "{\"kind\":\"canonical_root_ivar_filled\",\"receipt_ref\":%u,\"evidence_ref\":%u,\"authority\":\"single_assignment_ivar\",\"publisher_queue_authority\":false}"
                            (canonicalRootStableRef "canonical_root_ivar_receipt_ref" receiptId)
                            receipt.evidenceRef)
                receiptId

        let canonicalRootAuthorityResolve source receiptHint evidence =
            match source with
            | CanonicalRootEvaluator -> canonicalRootAuthorityResolveFromEvaluator receiptHint evidence
            | CanonicalRootTerminalBridge ->
                lock canonicalRootAuthorityGate (fun () ->
                    match canonicalRootAuthorityPhase with
                    | CanonicalRootResolved receipt -> canonicalRootReceiptIdText receipt.receiptId
                    | CanonicalRootUnarmed
                    | CanonicalRootArmed _ ->
                        "")
            | CanonicalRootFailClosed ->
                let mutable minted : CanonicalRootReceipt option = None
                lock canonicalRootAuthorityGate (fun () ->
                    match canonicalRootAuthorityPhase with
                    | CanonicalRootResolved receipt -> minted <- Some receipt
                    | CanonicalRootUnarmed
                    | CanonicalRootArmed _ ->
                        let receipt = canonicalRootAuthorityMint CanonicalRootFailClosed receiptHint evidence
                        canonicalRootAuthorityPhase <- CanonicalRootResolved receipt
                        minted <- Some receipt)
                match minted with
                | None -> ""
                | Some receipt ->
                    queue (job {
                        let! _ = Hopac.IVar.tryFill canonicalRootAuthorityCell receipt
                        return ()
                    })
                    canonicalRootReceiptIdText receipt.receiptId

        let canonicalRootAuthorityTerminalProjection receiptHint evidence =
            lock canonicalRootAuthorityGate (fun () ->
                match canonicalRootAuthorityPhase with
                | CanonicalRootResolved receipt ->
                    let receiptId = canonicalRootReceiptIdText receipt.receiptId
                    if String.IsNullOrWhiteSpace receiptHint || receiptHint = receiptId then
                        CanonicalRootBridgeAcceptedProjection receiptId
                    else
                        CanonicalRootBridgeDiverged(receiptId, evidence)
                | CanonicalRootUnarmed
                | CanonicalRootArmed _ ->
                    CanonicalRootBridgeRejectedAwaitEvaluator evidence)

        let canonicalRootAuthorityTerminalProjectionText receiptHint evidence =
            canonicalRootAuthorityTerminalProjection receiptHint evidence
            |> canonicalRootAuthorityBridgeDecisionText

        let canonicalRootAuthoritySnapshot () =
            lock canonicalRootAuthorityGate (fun () ->
                match canonicalRootAuthorityPhase with
                | CanonicalRootUnarmed ->
                    { phase = CanonicalRootUnarmed; receiptId = ""; source = "unarmed"; resolvedAtMs = 0L; evidenceRef = 0u }
                | CanonicalRootArmed(armedAtMs, evidenceRef) ->
                    { phase = CanonicalRootArmed(armedAtMs, evidenceRef); receiptId = ""; source = "armed"; resolvedAtMs = 0L; evidenceRef = evidenceRef }
                | CanonicalRootResolved receipt ->
                    let source =
                        match receipt.source with
                        | CanonicalRootEvaluator -> "evaluator"
                        | CanonicalRootTerminalBridge -> "terminal_bridge"
                        | CanonicalRootFailClosed -> "fail_closed"
                    { phase = CanonicalRootResolved receipt
                      receiptId = canonicalRootReceiptIdText receipt.receiptId
                      source = source
                      resolvedAtMs = receipt.resolvedAtMs
                      evidenceRef = receipt.evidenceRef })

        type TerminalSemanticAuthorityAdmission =
            | TerminalSemanticAuthorityAdmitted
            | TerminalSemanticPostRootCacheEnrichment


        let commitEvaluatorRootAndReconcileTerminalFlow receiptHint evidence =
            let before = canonicalRootAuthoritySnapshot()
            let receiptId = canonicalRootAuthorityResolveFromEvaluator receiptHint evidence
            let after = canonicalRootAuthoritySnapshot()
            if String.IsNullOrWhiteSpace receiptId then
                EvaluatorRootCommitRejected EvaluatorRootReceiptNotMinted
            else
                match before.phase, after.phase with
                | CanonicalRootResolved _, CanonicalRootResolved _ ->
                    EvaluatorRootAlreadyCommitted(receiptId, after.resolvedAtMs, after.evidenceRef)
                | _, CanonicalRootResolved _ ->
                    // Canonical-root resolution proves the evaluator root, not global
                    // operational quiescence.  Publishing BuildOk here allowed a terminal
                    // outcome to be installed while semantic work units were still open.
                    // QAP finality or the typed no-work consumer owns the later candidate.
                    emitEarlyPublisherProjection (
                        sprintf "{\"kind\":\"canonical_root_terminal_candidate_deferred\",\"root_receipt_ref\":%u,\"terminal_candidate_published\":false,\"operational_quiescence_required\":true,\"qap_finality_required\":true,\"authority\":\"canonical_evaluator_root_commit_is_not_terminal_quiescence\",\"next\":\"await_operational_graph_quiescence_then_qap_finality\"}"
                            (terminalOutcomeCandidateStableRef "canonical-root-receipt" receiptId))
                    EvaluatorRootCommittedNow(receiptId, after.resolvedAtMs, after.evidenceRef)
                | _ ->
                    EvaluatorRootCommitRejected EvaluatorCanonicalRootNotResolvedAfterCommit

        let canonicalRootAuthorityText () =
            let snapshot = canonicalRootAuthoritySnapshot()
            match snapshot.phase with
            | CanonicalRootUnarmed -> "CanonicalRootAuthority(Unarmed)"
            | CanonicalRootArmed(armedAtMs, evidenceRef) ->
                sprintf "CanonicalRootAuthority(Armed|armed_at_ms=%d|evidence_ref=%u)" armedAtMs evidenceRef
            | CanonicalRootResolved _ ->
                FastRuntimeFormat.format "CanonicalRootAuthority(Resolved|receipt=%s|source=%s|resolved_at_ms=%d|evidence_ref=%u)" [| box snapshot.receiptId; box snapshot.source; box snapshot.resolvedAtMs; box snapshot.evidenceRef |]

        // Process-global push actor state. The metronome reads this typed state;
        // it no longer infers actor liveness from HUD prose.
        type TerminalSchedulerPushActorPhase =
            | PushActorNoop
            | PushActorArmed
            | PushActorOutcomeFilled
            | PushActorWriterBound
            | PushActorArtifactsCommitted
            | PushActorExitWitnessQueued
            | PushActorConsumed
            | PushActorFailedClosed

        // MIGRATION migration : the actor is no longer a ranked phase cell.
        // Each state carries the exact predecessor receipts needed by the next
        // transition. Observer projections may request a phase for telemetry, but
        // only an ActorCommand can mutate this recursive possession spine.
        [<Struct>]
        type TerminalSchedulerPushActorRefKind = struct end
        [<Struct>]
        type TerminalSchedulerPushActorOwnerTransactionRefKind = struct end
        [<Struct>]
        type TerminalSchedulerPushActorStageTokenRefKind = struct end

        [<Struct; StructuralEquality; NoComparison>]
        type TerminalSchedulerPushActorFillKeyId = private | TerminalSchedulerPushActorFillKeyId of string

        module TerminalSchedulerPushActorFillKeyId =
            let create value =
                if String.IsNullOrWhiteSpace value then invalidArg "value" "push actor fill key must be non-empty"
                TerminalSchedulerPushActorFillKeyId value
            let text (TerminalSchedulerPushActorFillKeyId value) = value

        type TerminalSchedulerPushActorIdentity = private {
            actorRef : CompilerKernelV2.NonZeroRef<TerminalSchedulerPushActorRefKind>
            fillKey : TerminalSchedulerPushActorFillKeyId
            receiptId : string
            dispatchId : string
            ownerTransactionRef : CompilerKernelV2.NonZeroRef<TerminalSchedulerPushActorOwnerTransactionRefKind>
            stageTokenRef : CompilerKernelV2.NonZeroRef<TerminalSchedulerPushActorStageTokenRefKind> option
        }

        type TerminalSchedulerPushActorWakerOwnership =
            | PushActorWakerRequired of requirementRef:uint32
            | PushActorWakerRegistered of requirementRef:uint32 * edgeRef:uint32 * registeredAtMs:int64
            | PushActorWakerConsumed of edgeRef:uint32 * consumedAtMs:int64
            | PushActorWakerRejected of requirementRef:uint32 * reasonRef:uint32

        type TerminalSchedulerPushActorOwnedState =
            | PushActorOwnedDormant of openedAtMs:int64
            | PushActorOwnedArmed of identity:TerminalSchedulerPushActorIdentity * armReceiptRef:uint32 * waker:TerminalSchedulerPushActorWakerOwnership * changedAtMs:int64
            | PushActorOwnedOutcomeFilled of identity:TerminalSchedulerPushActorIdentity * armReceiptRef:uint32 * fillReceiptRef:uint32 * waker:TerminalSchedulerPushActorWakerOwnership * changedAtMs:int64
            | PushActorOwnedWriterBound of identity:TerminalSchedulerPushActorIdentity * fillReceiptRef:uint32 * writerCapabilityRef:uint32 * waker:TerminalSchedulerPushActorWakerOwnership * changedAtMs:int64
            | PushActorOwnedArtifactsCommitted of identity:TerminalSchedulerPushActorIdentity * writerCapabilityRef:uint32 * artifactReceiptRef:uint32 * waker:TerminalSchedulerPushActorWakerOwnership * changedAtMs:int64
            | PushActorOwnedExitWitness of identity:TerminalSchedulerPushActorIdentity * artifactReceiptRef:uint32 * exitWitnessRef:uint32 * waker:TerminalSchedulerPushActorWakerOwnership * changedAtMs:int64
            | PushActorOwnedConsumed of identity:TerminalSchedulerPushActorIdentity * exitWitnessRef:uint32 * runEndReceiptRef:uint32 * changedAtMs:int64
            | PushActorOwnedFailedClosed of identity:TerminalSchedulerPushActorIdentity option * failureReceiptRef:uint32 * reasonRef:uint32 * changedAtMs:int64

        type TerminalSchedulerPushActorCommand =
            | PushActorArmOwned of identity:TerminalSchedulerPushActorIdentity * armReceiptRef:uint32 * wakerRequirementRef:uint32
            | PushActorRecordOutcomeFilled of fillReceiptRef:uint32 * stageTokenRef:uint32 * wakerEdgeRef:uint32
            | PushActorRecordWriterBound of writerCapabilityRef:uint32
            | PushActorRecordArtifactsCommitted of artifactReceiptRef:uint32
            | PushActorRecordExitWitness of exitWitnessRef:uint32
            | PushActorRecordConsumed of runEndReceiptRef:uint32
            | PushActorRecordFailedClosed of failureReceiptRef:uint32 * reasonRef:uint32

        type TerminalSchedulerPushActorAdvance =
            | PushActorAdvanced of beforePhase:TerminalSchedulerPushActorPhase * afterPhase:TerminalSchedulerPushActorPhase * commandRef:uint32
            | PushActorIdempotent of phase:TerminalSchedulerPushActorPhase * commandRef:uint32
            | PushActorRejectedWrongPredecessor of currentPhase:TerminalSchedulerPushActorPhase * commandRef:uint32
            | PushActorRejectedIdentityMismatch of currentFillRef:uint32 * attemptedFillRef:uint32 * commandRef:uint32
            | PushActorRejectedTerminalConflict of currentPhase:TerminalSchedulerPushActorPhase * commandRef:uint32

        type TerminalSchedulerPushActorProjectionReason =
            | PushActorProjectionReducerPossessionVacant
            | PushActorProjectionReducerPossessionObserved of possessionRef:uint32 * phase:TerminalSchedulerPushActorPhase


        type TerminalSchedulerPushActorSnapshot = {
            phase : TerminalSchedulerPushActorPhase
            fillKey : string
            receiptId : string
            dispatchId : string
            changedAtMs : int64
            reason : TerminalSchedulerPushActorProjectionReason
        }

        type TerminalSchedulerPushActorMailboxState = {
            owned : TerminalSchedulerPushActorOwnedState
            reducerProjection : TerminalSchedulerPushActorSnapshot
        }

        type TerminalSchedulerPushActorMailboxMessage =
            | PushActorMailboxApply of TerminalSchedulerPushActorCommand * CompilerKernelV2.PortableOneShotCell<TerminalSchedulerPushActorAdvance>
            | PushActorMailboxProjectReducer of TerminalSchedulerPushActorSnapshot * CompilerKernelV2.PortableOneShotCell<unit>
            | PushActorMailboxSnapshot of CompilerKernelV2.PortableOneShotCell<TerminalSchedulerPushActorSnapshot>

        let private terminalSchedulerPushActorInitialProjection () : TerminalSchedulerPushActorSnapshot =
            { phase = PushActorNoop
              fillKey = ""
              receiptId = ""
              dispatchId = ""
              changedAtMs = Environment.TickCount64
              reason = PushActorProjectionReducerPossessionVacant }

        // MIGRATION: observer reads use an immutable mirror written only by the
        // push-actor mailbox. This keeps ticker/finalization reads bounded and
        // prevents a scheduler job from nesting Hopac.run merely for telemetry.
        let private terminalSchedulerPushActorProjectionGate = obj()
        let mutable private terminalSchedulerPushActorProjection = terminalSchedulerPushActorInitialProjection()
        let private installTerminalSchedulerPushActorProjection projection =
            lock terminalSchedulerPushActorProjectionGate (fun () -> terminalSchedulerPushActorProjection <- projection)
        let private readTerminalSchedulerPushActorProjection () =
            lock terminalSchedulerPushActorProjectionGate (fun () -> terminalSchedulerPushActorProjection)

        let private terminalSchedulerPushActorIdentity = function
            | PushActorOwnedDormant _ -> None
            | PushActorOwnedArmed(identity, _, _, _)
            | PushActorOwnedOutcomeFilled(identity, _, _, _, _)
            | PushActorOwnedWriterBound(identity, _, _, _, _)
            | PushActorOwnedArtifactsCommitted(identity, _, _, _, _)
            | PushActorOwnedExitWitness(identity, _, _, _, _)
            | PushActorOwnedConsumed(identity, _, _, _)
            | PushActorOwnedFailedClosed(Some identity, _, _, _) -> Some identity
            | PushActorOwnedFailedClosed(None, _, _, _) -> None

        let private terminalSchedulerPushActorPhaseOf = function
            | PushActorOwnedDormant _ -> PushActorNoop
            | PushActorOwnedArmed _ -> PushActorArmed
            | PushActorOwnedOutcomeFilled _ -> PushActorOutcomeFilled
            | PushActorOwnedWriterBound _ -> PushActorWriterBound
            | PushActorOwnedArtifactsCommitted _ -> PushActorArtifactsCommitted
            | PushActorOwnedExitWitness _ -> PushActorExitWitnessQueued
            | PushActorOwnedConsumed _ -> PushActorConsumed
            | PushActorOwnedFailedClosed _ -> PushActorFailedClosed

        let private terminalSchedulerPushActorChangedAtMs = function
            | PushActorOwnedDormant changedAtMs
            | PushActorOwnedArmed(_, _, _, changedAtMs)
            | PushActorOwnedOutcomeFilled(_, _, _, _, changedAtMs)
            | PushActorOwnedWriterBound(_, _, _, _, changedAtMs)
            | PushActorOwnedArtifactsCommitted(_, _, _, _, changedAtMs)
            | PushActorOwnedExitWitness(_, _, _, _, changedAtMs)
            | PushActorOwnedConsumed(_, _, _, changedAtMs)
            | PushActorOwnedFailedClosed(_, _, _, changedAtMs) -> changedAtMs

        let terminalSchedulerPushActorPhaseStableText = function
            | PushActorNoop -> "Noop"
            | PushActorArmed -> "Armed"
            | PushActorOutcomeFilled -> "OutcomeFilled"
            | PushActorWriterBound -> "WriterBound"
            | PushActorArtifactsCommitted -> "ArtifactsCommitted"
            | PushActorExitWitnessQueued -> "ExitWitnessQueued"
            | PushActorConsumed -> "Consumed"
            | PushActorFailedClosed -> "FailedClosed"

        let private terminalSchedulerPushActorProjectionReasonText = function
            | PushActorProjectionReducerPossessionVacant -> "ReducerTerminalPossession(Vacant)"
            | PushActorProjectionReducerPossessionObserved(possessionRef, phase) ->
                sprintf "ReducerTerminalPossession(ref=%u|phase=%s)" possessionRef (terminalSchedulerPushActorPhaseStableText phase)

        let terminalSchedulerPushActorIdentityStableText (identity:TerminalSchedulerPushActorIdentity) =
            let stageTokenRef =
                identity.stageTokenRef
                |> Option.map CompilerKernelV2.NonZeroRef.value
                |> Option.defaultValue 0u
            FastRuntimeFormat.format "actor=%u|fill=%s|receipt=%s|dispatch=%s|owner=%u|stage=%u" [| box (CompilerKernelV2.NonZeroRef.value identity.actorRef); box (TerminalSchedulerPushActorFillKeyId.text identity.fillKey); box identity.receiptId; box identity.dispatchId; box (CompilerKernelV2.NonZeroRef.value identity.ownerTransactionRef); box stageTokenRef |]

        let terminalSchedulerPushActorCommandStableText = function
            | PushActorArmOwned(identity, armReceiptRef, wakerRequirementRef) ->
                FastRuntimeFormat.format "ArmOwned(%s|arm=%u|waker_requirement=%u)" [| box (terminalSchedulerPushActorIdentityStableText identity); box armReceiptRef; box wakerRequirementRef |]
            | PushActorRecordOutcomeFilled(fillReceiptRef, stageTokenRef, wakerEdgeRef) ->
                FastRuntimeFormat.format "RecordOutcomeFilled(fill=%u|stage=%u|waker_edge=%u)" [| box fillReceiptRef; box stageTokenRef; box wakerEdgeRef |]
            | PushActorRecordWriterBound writerCapabilityRef ->
                sprintf "RecordWriterBound(writer=%u)" writerCapabilityRef
            | PushActorRecordArtifactsCommitted artifactReceiptRef ->
                sprintf "RecordArtifactsCommitted(artifact=%u)" artifactReceiptRef
            | PushActorRecordExitWitness exitWitnessRef ->
                sprintf "RecordExitWitness(exit=%u)" exitWitnessRef
            | PushActorRecordConsumed runEndReceiptRef ->
                sprintf "RecordConsumed(run_end=%u)" runEndReceiptRef
            | PushActorRecordFailedClosed(failureReceiptRef, reasonRef) ->
                sprintf "RecordFailedClosed(failure=%u|reason=%u)" failureReceiptRef reasonRef

        let private terminalSchedulerPushActorCommandRef command =
            CompilerKernelV2.NonZeroRef.derive "push_actor_command_ref" [terminalSchedulerPushActorCommandStableText command]
            |> CompilerKernelV2.NonZeroRef.value

        let terminalSchedulerPushActorIdentityFor (fillKey:TerminalSchedulerPushActorFillKeyId) receiptId dispatchId ownerTransactionId =
            let requireText label value =
                if String.IsNullOrWhiteSpace value then invalidArg label "must be non-empty"
                value
            let receiptId = requireText "receiptId" receiptId
            let dispatchId = requireText "dispatchId" dispatchId
            let ownerTransactionId = requireText "ownerTransactionId" ownerTransactionId
            { actorRef = CompilerKernelV2.NonZeroRef.derive "push_actor_ref" [dispatchId]
              fillKey = fillKey
              receiptId = receiptId
              dispatchId = dispatchId
              ownerTransactionRef = CompilerKernelV2.NonZeroRef.derive "push_actor_owner_transaction_ref" [ownerTransactionId]
              stageTokenRef = None }

        let private terminalSchedulerPushActorTransition (current:TerminalSchedulerPushActorOwnedState) (command:TerminalSchedulerPushActorCommand) =
            let currentPhase = terminalSchedulerPushActorPhaseOf current
            let commandRef = terminalSchedulerPushActorCommandRef command
            let nowMs = Environment.TickCount64
            let advance next =
                next, PushActorAdvanced(currentPhase, terminalSchedulerPushActorPhaseOf next, commandRef)
            let retain result = current, result
            match current, command with
            | PushActorOwnedDormant _, PushActorArmOwned(identity, armReceiptRef, wakerRequirementRef) ->
                advance (PushActorOwnedArmed(identity, armReceiptRef, PushActorWakerRequired wakerRequirementRef, nowMs))
            | PushActorOwnedArmed(identity, armReceiptRef, PushActorWakerRequired requirementRef, _),
              PushActorRecordOutcomeFilled(fillReceiptRef, stageTokenRef, wakerEdgeRef)
                when stageTokenRef <> 0u && wakerEdgeRef <> 0u ->
                let identity =
                    { identity with
                        stageTokenRef = Some (CompilerKernelV2.NonZeroRef.require "push_actor_stage_token_ref" stageTokenRef) }
                advance (PushActorOwnedOutcomeFilled(identity, armReceiptRef, fillReceiptRef, PushActorWakerRegistered(requirementRef, wakerEdgeRef, nowMs), nowMs))
            | PushActorOwnedOutcomeFilled(identity, _, fillReceiptRef, waker, _), PushActorRecordWriterBound writerCapabilityRef
                when writerCapabilityRef <> 0u ->
                advance (PushActorOwnedWriterBound(identity, fillReceiptRef, writerCapabilityRef, waker, nowMs))
            | PushActorOwnedWriterBound(identity, _, writerCapabilityRef, waker, _), PushActorRecordArtifactsCommitted artifactReceiptRef
                when artifactReceiptRef <> 0u ->
                advance (PushActorOwnedArtifactsCommitted(identity, writerCapabilityRef, artifactReceiptRef, waker, nowMs))
            | PushActorOwnedArtifactsCommitted(identity, _, artifactReceiptRef, PushActorWakerRegistered(_, edgeRef, _), _), PushActorRecordExitWitness exitWitnessRef
                when exitWitnessRef <> 0u ->
                advance (PushActorOwnedExitWitness(identity, artifactReceiptRef, exitWitnessRef, PushActorWakerConsumed(edgeRef, nowMs), nowMs))
            | PushActorOwnedExitWitness(identity, _, exitWitnessRef, PushActorWakerConsumed _, _), PushActorRecordConsumed runEndReceiptRef
                when runEndReceiptRef <> 0u ->
                advance (PushActorOwnedConsumed(identity, exitWitnessRef, runEndReceiptRef, nowMs))
            | PushActorOwnedConsumed _, PushActorRecordFailedClosed _
            | PushActorOwnedFailedClosed _, PushActorRecordConsumed _ ->
                retain (PushActorRejectedTerminalConflict(currentPhase, commandRef))
            | PushActorOwnedFailedClosed(_, failureReceiptRef, reasonRef, _), PushActorRecordFailedClosed(attemptedFailureRef, attemptedReasonRef)
                when failureReceiptRef = attemptedFailureRef && reasonRef = attemptedReasonRef ->
                retain (PushActorIdempotent(PushActorFailedClosed, commandRef))
            | PushActorOwnedConsumed(_, _, runEndReceiptRef, _), PushActorRecordConsumed attemptedRunEndRef
                when runEndReceiptRef = attemptedRunEndRef ->
                retain (PushActorIdempotent(PushActorConsumed, commandRef))
            | _, PushActorRecordFailedClosed(failureReceiptRef, reasonRef)
                when failureReceiptRef <> 0u && reasonRef <> 0u ->
                advance (PushActorOwnedFailedClosed(terminalSchedulerPushActorIdentity current, failureReceiptRef, reasonRef, nowMs))
            | current, PushActorArmOwned(identity, _, _) ->
                match terminalSchedulerPushActorIdentity current with
                | Some currentIdentity when currentIdentity.fillKey <> identity.fillKey ->
                    let currentFillRef =
                        CompilerKernelV2.NonZeroRef.derive "push_actor_fill_key_ref" [TerminalSchedulerPushActorFillKeyId.text currentIdentity.fillKey]
                        |> CompilerKernelV2.NonZeroRef.value
                    let attemptedFillRef =
                        CompilerKernelV2.NonZeroRef.derive "push_actor_fill_key_ref" [TerminalSchedulerPushActorFillKeyId.text identity.fillKey]
                        |> CompilerKernelV2.NonZeroRef.value
                    retain (PushActorRejectedIdentityMismatch(currentFillRef, attemptedFillRef, commandRef))
                | _ -> retain (PushActorRejectedWrongPredecessor(currentPhase, commandRef))
            | _ -> retain (PushActorRejectedWrongPredecessor(currentPhase, commandRef))

        let private terminalSchedulerPushActorMailbox =
            CompilerKernelV2.CompilerRuntimeKernel.mailbox<TerminalSchedulerPushActorMailboxMessage>
                "terminal-scheduler-push-actor"
                CompilerKernelV2.PortableControlLane
                0
                CompilerKernelV2.MailboxFailClosed

        let rec private terminalSchedulerPushActorMailboxLoop (state:TerminalSchedulerPushActorMailboxState) =
            job {
                let! message = CompilerKernelV2.CompilerRuntimeKernel.take terminalSchedulerPushActorMailbox
                match message with
                | PushActorMailboxApply(command, reply) ->
                    let nextOwned, result = terminalSchedulerPushActorTransition state.owned command
                    do! CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply result
                    return! terminalSchedulerPushActorMailboxLoop { state with owned = nextOwned }
                | PushActorMailboxProjectReducer(projection, reply) ->
                    installTerminalSchedulerPushActorProjection projection
                    do! CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply ()
                    return! terminalSchedulerPushActorMailboxLoop { state with reducerProjection = projection }
                | PushActorMailboxSnapshot reply ->
                    do! CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply state.reducerProjection
                    return! terminalSchedulerPushActorMailboxLoop state
            }

        let private terminalSchedulerPushActorMailboxStarted =
            lazy (
                let initialProjection = terminalSchedulerPushActorInitialProjection()
                installTerminalSchedulerPushActorProjection initialProjection
                let initialState =
                    { owned = PushActorOwnedDormant Environment.TickCount64
                      reducerProjection = initialProjection }
                startHopacJob (terminalSchedulerPushActorMailboxLoop initialState))

        let private ensureTerminalSchedulerPushActorMailboxStarted () =
            CompilerRuntimeActivation.requireInProcessEntered "terminal_scheduler_push_actor"
            terminalSchedulerPushActorMailboxStarted.Force()

        let private terminalSchedulerPushActorMailboxApplyJob (command:TerminalSchedulerPushActorCommand) : Job<TerminalSchedulerPushActorAdvance> =
            ensureTerminalSchedulerPushActorMailboxStarted()
            job {
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<TerminalSchedulerPushActorAdvance>
                        "terminal-scheduler-push-actor-apply"
                do! CompilerKernelV2.CompilerRuntimeKernel.send terminalSchedulerPushActorMailbox (PushActorMailboxApply(command, reply))
                return! CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
            }


        let terminalSchedulerPushActorProjectReducer (phase:TerminalSchedulerPushActorPhase) (fillKey:string) (receiptRef:uint32) (dispatchRef:uint32) (changedAtMs:int64) (possessionRef:uint32) =
            ensureTerminalSchedulerPushActorMailboxStarted()
            let projection =
                { phase = phase
                  fillKey = fillKey
                  receiptId = if receiptRef = 0u then "" else string receiptRef
                  dispatchId = if dispatchRef = 0u then "" else string dispatchRef
                  changedAtMs = changedAtMs
                  reason = PushActorProjectionReducerPossessionObserved(possessionRef, phase) }
            installTerminalSchedulerPushActorProjection projection
            startHopacJob (job {
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<unit>
                        "terminal-scheduler-push-actor-project-reducer"
                do! CompilerKernelV2.CompilerRuntimeKernel.send terminalSchedulerPushActorMailbox (PushActorMailboxProjectReducer(projection, reply))
                do! CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
            })

        let private terminalSchedulerPushActorHandleAdvance result =
            match result with
            | PushActorRejectedWrongPredecessor(currentPhase, commandRef) ->
                emitEarlyPublisherProjection (
                    sprintf "{\"kind\":\"terminal_scheduler_push_actor_transition_rejected\",\"reason_du\":\"wrong_typed_predecessor\",\"current_phase_du\":%s,\"command_ref\":%u,\"authority\":\"push_actor_possession_spine\"}"
                        (esc (terminalSchedulerPushActorPhaseStableText currentPhase)) commandRef)
            | PushActorRejectedIdentityMismatch(currentFillRef, attemptedFillRef, commandRef) ->
                emitEarlyPublisherProjection (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_push_actor_transition_rejected\",\"reason_du\":\"actor_identity_mismatch\",\"current_fill_ref\":%u,\"attempted_fill_ref\":%u,\"command_ref\":%u,\"authority\":\"push_actor_possession_spine\"}" [| box currentFillRef; box attemptedFillRef; box commandRef |])
            | PushActorRejectedTerminalConflict(currentPhase, commandRef) ->
                emitEarlyPublisherProjection (
                    sprintf "{\"kind\":\"terminal_scheduler_push_actor_transition_rejected\",\"reason_du\":\"terminal_authority_conflict\",\"current_phase_du\":%s,\"command_ref\":%u,\"authority\":\"push_actor_possession_spine\"}"
                        (esc (terminalSchedulerPushActorPhaseStableText currentPhase)) commandRef)
            | PushActorAdvanced _
            | PushActorIdempotent _ -> ()

        let terminalSchedulerPushActorApplyJob command : Job<unit> =
            job {
                let! result = terminalSchedulerPushActorMailboxApplyJob command
                terminalSchedulerPushActorHandleAdvance result
            }



        let terminalSchedulerPushActorSnapshot () : TerminalSchedulerPushActorSnapshot =
            if CompilerRuntimeActivation.isInProcessEntered () then
                ensureTerminalSchedulerPushActorMailboxStarted()
                let snapshot = readTerminalSchedulerPushActorProjection ()
                if snapshot.changedAtMs < CompilerConsoleHud88.supervisorBuildRequestEpochNow () then
                    terminalSchedulerPushActorInitialProjection()
                else
                    snapshot
            else
                terminalSchedulerPushActorInitialProjection()

        let terminalSchedulerPushActorPhaseText = terminalSchedulerPushActorPhaseStableText

        let terminalSchedulerPushActorText () =
            let state = terminalSchedulerPushActorSnapshot()
            FastRuntimeFormat.format "TerminalSchedulerPushActor(%s|fill=%s|receipt=%s|dispatch=%s|changed_at_ms=%d|owned_state=%s)" [| box (terminalSchedulerPushActorPhaseText state.phase); box state.fillKey; box state.receiptId; box state.dispatchId; box state.changedAtMs; box (terminalSchedulerPushActorProjectionReasonText state.reason) |]

        // MIGRATION round : JSONL sequence, run_end, and HUD consensus are
        // emitted from typed root/actor/watchdog state.  JSON remains an erasure
        // boundary; it cannot mint a root receipt or a terminal exit witness.
        [<Struct>]
        type TerminalFlowRunEndClaimRefKind = struct end
        [<Struct>]
        type TerminalFlowRunEndDurableReceiptRefKind = struct end

        type TerminalFlowRunEndEmissionState =
            | TerminalFlowRunEndOpen
            | TerminalFlowRunEndClaimed of claimRef:CompilerKernelV2.NonZeroRef<TerminalFlowRunEndClaimRefKind>
            | TerminalFlowRunEndDurable of receiptRef:CompilerKernelV2.NonZeroRef<TerminalFlowRunEndDurableReceiptRefKind>

        type TerminalFlowRunEndMailboxState = private {
            emission : TerminalFlowRunEndEmissionState
            terminalStage : (CompilerKernelV2.KernelTerminalStage * uint32) option
            preRunEndStage : (CompilerKernelV2.KernelTerminalStage * uint32) option
            journal : CompilerKernelV2.KernelJournal
        }

        type TerminalFlowRunEndMailboxMessage =
            | TerminalFlowRunEndClaim of claimRef:CompilerKernelV2.NonZeroRef<TerminalFlowRunEndClaimRefKind> * CompilerKernelV2.PortableOneShotCell<bool>
            | TerminalFlowRunEndMarkDurable of claimRef:CompilerKernelV2.NonZeroRef<TerminalFlowRunEndClaimRefKind> * receiptRef:CompilerKernelV2.NonZeroRef<TerminalFlowRunEndDurableReceiptRefKind> * CompilerKernelV2.PortableOneShotCell<bool>
            | TerminalFlowRunEndReleaseClaim of claimRef:CompilerKernelV2.NonZeroRef<TerminalFlowRunEndClaimRefKind> * CompilerKernelV2.PortableOneShotCell<bool>
            | TerminalFlowRunEndRecordStage of stage:CompilerKernelV2.KernelTerminalStage * authorityRef:uint32 * CompilerKernelV2.PortableOneShotCell<bool>

        let private terminalFlowRunEndMailbox =
            CompilerKernelV2.CompilerRuntimeKernel.mailbox<TerminalFlowRunEndMailboxMessage>
                "terminal-flow-run-end"
                CompilerKernelV2.PortableControlLane
                0
                CompilerKernelV2.MailboxFailClosed
        // Mailbox-written observer mirror: readers inside Hopac jobs must never
        // perform a request/reply round-trip merely to render diagnostics.
        type TerminalFlowRunEndDurableProjection =
            | TerminalFlowRunEndProjectionPending
            | TerminalFlowRunEndProjectionDurable of receiptRef:uint32

        let mutable private terminalFlowRunEndDurableProjection = TerminalFlowRunEndProjectionPending

        let private terminalFlowRunEndJournalAppend stage authorityRef state =
            let nextSequence = CompilerKernelV2.kernelJournalLastSequence state.journal + 1L
            let authorityDigest =
                CompilerIdentityKernel.ContentDigest.ofText
                    "kernel-terminal-authority"
                    (CompilerKernelV2.kernelTerminalStageStableText stage
                     + "|legacy_ref=" + string authorityRef)
            match CompilerKernelV2.kernelJournalAppend nextSequence (CompilerKernelV2.JournalTerminalStage(stage, authorityDigest)) state.journal with
            | Ok journal -> { state with journal = journal }
            | Error reason -> invalidOp reason

        let private terminalFlowKernelStageAllows previous next =
            match previous, next with
            | None, CompilerKernelV2.KernelTerminalFilled
            | None, CompilerKernelV2.KernelTerminalFailedClosed -> true
            | Some CompilerKernelV2.KernelTerminalFilled, CompilerKernelV2.KernelTerminalWriterCommitted -> true
            | Some CompilerKernelV2.KernelTerminalWriterCommitted, CompilerKernelV2.KernelTerminalSealAuthorized -> true
            | Some CompilerKernelV2.KernelTerminalSealAuthorized, CompilerKernelV2.KernelTerminalSealed -> true
            | Some CompilerKernelV2.KernelTerminalSealed, CompilerKernelV2.KernelRunEndClaimed -> true
            | Some CompilerKernelV2.KernelTerminalFailedClosed, CompilerKernelV2.KernelRunEndClaimed -> true
            | Some CompilerKernelV2.KernelRunEndClaimed, CompilerKernelV2.KernelRunEndDurable -> true
            | Some CompilerKernelV2.KernelRunEndDurable, CompilerKernelV2.KernelPhysicalExitSelected -> true
            | Some current, candidate when current = candidate -> true
            | _ -> false

        let rec private terminalFlowRunEndMailboxLoop (state:TerminalFlowRunEndMailboxState) =
            job {
                let! message =
                    CompilerKernelV2.CompilerRuntimeKernel.take terminalFlowRunEndMailbox
                match message with
                | TerminalFlowRunEndClaim(claimRef, reply) ->
                    match state.emission with
                    | TerminalFlowRunEndOpen when terminalFlowKernelStageAllows (state.terminalStage |> Option.map fst) CompilerKernelV2.KernelRunEndClaimed ->
                        let rawClaimRef = CompilerKernelV2.NonZeroRef.value claimRef
                        let next =
                            { state with
                                emission = TerminalFlowRunEndClaimed claimRef
                                preRunEndStage = state.terminalStage
                                terminalStage = Some(CompilerKernelV2.KernelRunEndClaimed, rawClaimRef) }
                            |> terminalFlowRunEndJournalAppend CompilerKernelV2.KernelRunEndClaimed rawClaimRef
                        do! CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply true
                        return! terminalFlowRunEndMailboxLoop next
                    | _ ->
                        do! CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply false
                        return! terminalFlowRunEndMailboxLoop state
                | TerminalFlowRunEndMarkDurable(claimRef, receiptRef, reply) ->
                    match state.emission with
                    | TerminalFlowRunEndClaimed activeClaim
                        when activeClaim = claimRef
                             && terminalFlowKernelStageAllows (state.terminalStage |> Option.map fst) CompilerKernelV2.KernelRunEndDurable ->
                        let rawReceiptRef = CompilerKernelV2.NonZeroRef.value receiptRef
                        let next =
                            { state with
                                emission = TerminalFlowRunEndDurable receiptRef
                                terminalStage = Some(CompilerKernelV2.KernelRunEndDurable, rawReceiptRef) }
                            |> terminalFlowRunEndJournalAppend CompilerKernelV2.KernelRunEndDurable rawReceiptRef
                        System.Threading.Volatile.Write(&terminalFlowRunEndDurableProjection, TerminalFlowRunEndProjectionDurable rawReceiptRef)
                        do! CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply true
                        return! terminalFlowRunEndMailboxLoop next
                    | TerminalFlowRunEndDurable existing when existing = receiptRef ->
                        let rawExistingReceiptRef = CompilerKernelV2.NonZeroRef.value existing
                        System.Threading.Volatile.Write(&terminalFlowRunEndDurableProjection, TerminalFlowRunEndProjectionDurable rawExistingReceiptRef)
                        do! CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply true
                        return! terminalFlowRunEndMailboxLoop state
                    | _ ->
                        do! CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply false
                        return! terminalFlowRunEndMailboxLoop state
                | TerminalFlowRunEndReleaseClaim(claimRef, reply) ->
                    match state.emission with
                    | TerminalFlowRunEndClaimed activeRef when activeRef = claimRef ->
                        let rawClaimRef = CompilerKernelV2.NonZeroRef.value claimRef
                        let next =
                            { state with
                                emission = TerminalFlowRunEndOpen
                                terminalStage = state.preRunEndStage
                                preRunEndStage = None }
                            |> terminalFlowRunEndJournalAppend CompilerKernelV2.KernelRunEndClaimReleased rawClaimRef
                        do! CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply true
                        return! terminalFlowRunEndMailboxLoop next
                    | _ ->
                        do! CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply false
                        return! terminalFlowRunEndMailboxLoop state
                | TerminalFlowRunEndRecordStage(stage, authorityRef, reply) ->
                    match state.terminalStage with
                    | Some(existingStage, existingRef) when existingStage = stage ->
                        do! CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply (existingRef = authorityRef)
                        return! terminalFlowRunEndMailboxLoop state
                    | previous
                        when authorityRef <> 0u
                             && terminalFlowKernelStageAllows (previous |> Option.map fst) stage ->
                        let next =
                            { state with terminalStage = Some(stage, authorityRef) }
                            |> terminalFlowRunEndJournalAppend stage authorityRef
                        do! CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply true
                        return! terminalFlowRunEndMailboxLoop next
                    | _ ->
                        do! CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply false
                        return! terminalFlowRunEndMailboxLoop state
            }

        let private terminalFlowRunEndMailboxStarted =
            lazy (
                let actorEffect =
                    CompilerKernelV2.CompilerRuntimeKernel.effect
                        "terminal-flow-run-end-actor"
                        (terminalFlowRunEndMailboxLoop {
                            emission = TerminalFlowRunEndOpen
                            terminalStage = None
                            preRunEndStage = None
                            journal = CompilerKernelV2.kernelJournalEmpty
                        })
                startHopacJob (CompilerKernelV2.CompilerRuntimeKernel.toJob actorEffect))

        let private ensureTerminalFlowRunEndMailboxStarted () =
            CompilerRuntimeActivation.requireInProcessEntered "terminal_flow_run_end"
            terminalFlowRunEndMailboxStarted.Force()

        let private terminalFlowRunEndTryClaimJob claimRef =
            job {
                ensureTerminalFlowRunEndMailboxStarted()
                let claim = CompilerKernelV2.NonZeroRef.require "run_end_claim_ref" claimRef
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<bool>
                        "terminal-flow-run-end-reply"
                do! CompilerKernelV2.CompilerRuntimeKernel.send terminalFlowRunEndMailbox (TerminalFlowRunEndClaim(claim, reply))
                return! CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
            }


        let private terminalFlowRunEndMarkDurableJob claimRef receiptRef =
            job {
                ensureTerminalFlowRunEndMailboxStarted()
                let claim = CompilerKernelV2.NonZeroRef.require "run_end_mark_durable_claim_ref" claimRef
                let receipt = CompilerKernelV2.NonZeroRef.require "run_end_durable_receipt_ref" receiptRef
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<bool>
                        "terminal-flow-run-end-reply"
                do! CompilerKernelV2.CompilerRuntimeKernel.send terminalFlowRunEndMailbox (TerminalFlowRunEndMarkDurable(claim, receipt, reply))
                let! accepted = CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
                if not accepted then invalidOp "run_end durability requires the active matching claim"
            }


        let private terminalFlowRunEndReleaseClaimJob claimRef =
            job {
                ensureTerminalFlowRunEndMailboxStarted()
                let claim = CompilerKernelV2.NonZeroRef.require "run_end_release_claim_ref" claimRef
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<bool>
                        "terminal-flow-run-end-reply"
                do! CompilerKernelV2.CompilerRuntimeKernel.send terminalFlowRunEndMailbox (TerminalFlowRunEndReleaseClaim(claim, reply))
                let! released = CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
                if not released then invalidOp "run_end claim release rejected by mailbox state"
            }


        let terminalFlowKernelJournalRecordStageJob stage authorityRef =
            job {
                ensureTerminalFlowRunEndMailboxStarted()
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<bool>
                        "terminal-flow-run-end-reply"
                do! CompilerKernelV2.CompilerRuntimeKernel.send terminalFlowRunEndMailbox (TerminalFlowRunEndRecordStage(stage, authorityRef, reply))
                return! CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
            }

        [<Struct>]
        type private TerminalFlowKernelJournalCaptureState =
            | TerminalFlowKernelJournalCaptureInactive
            | TerminalFlowKernelJournalCaptureActive of requests:System.Collections.Generic.List<CompilerKernelV2.KernelTerminalStage * uint32>

        let private terminalFlowKernelJournalCapture =
            System.Threading.AsyncLocal<TerminalFlowKernelJournalCaptureState>()

        let withTerminalFlowKernelJournalJobContext (run:unit -> 'a) =
            let previous = terminalFlowKernelJournalCapture.Value
            match previous with
            | TerminalFlowKernelJournalCaptureActive _ ->
                run(), []
            | TerminalFlowKernelJournalCaptureInactive ->
                let current = System.Collections.Generic.List<CompilerKernelV2.KernelTerminalStage * uint32>()
                terminalFlowKernelJournalCapture.Value <- TerminalFlowKernelJournalCaptureActive current
                try
                    let result = run()
                    result, (current |> Seq.toList)
                finally
                    terminalFlowKernelJournalCapture.Value <- previous

        let terminalFlowKernelJournalSubmitCapturedJob requests =
            job {
                for (stage, authorityRef) in requests do
                    let! accepted = terminalFlowKernelJournalRecordStageJob stage authorityRef
                    if not accepted then
                        invalidOp (sprintf "terminal kernel journal rejected captured authority_ref=%u" authorityRef)
            }

        let terminalFlowKernelJournalRecordStage stage authorityRef =
            match terminalFlowKernelJournalCapture.Value with
            | TerminalFlowKernelJournalCaptureActive requests ->
                requests.Add(stage, authorityRef)
                true
            | TerminalFlowKernelJournalCaptureInactive -> false

        let terminalFlowRunEndEmittedNow () =
            match System.Threading.Volatile.Read(&terminalFlowRunEndDurableProjection) with
            | TerminalFlowRunEndProjectionDurable _ -> true
            | TerminalFlowRunEndProjectionPending -> false

        let terminalFlowRunEndDurableReceiptRefNow () =
            match System.Threading.Volatile.Read(&terminalFlowRunEndDurableProjection) with
            | TerminalFlowRunEndProjectionDurable receiptRef -> Some receiptRef
            | TerminalFlowRunEndProjectionPending -> None

        // JSON sequence is serialization metadata, not terminal authority. It has
        // one explicit allocator so portability does not depend on host atomics or
        // on nesting Hopac.run inside a scheduler worker.
        let private terminalFlowJsonSequenceGate = obj()
        let mutable private terminalFlowJsonSequence = 0L
        let private terminalFlowNextJsonSeq () =
            lock terminalFlowJsonSequenceGate (fun () ->
                terminalFlowJsonSequence <- terminalFlowJsonSequence + 1L
                terminalFlowJsonSequence)

        type TerminalFlowHudRequiredNextId =
            | TerminalFlowHudAwaitQapThenAcquirePossession
            | TerminalFlowHudConsumeStageTokenOrFailClosed
            | TerminalFlowHudCommitExitWitness

        let private terminalFlowHudRequiredNextText = function
            | TerminalFlowHudAwaitQapThenAcquirePossession -> "await_qap_finalization_then_acquire_terminal_possession"
            | TerminalFlowHudConsumeStageTokenOrFailClosed -> "consume_terminal_stage_token_or_fail_closed"
            | TerminalFlowHudCommitExitWitness -> "global_server_commit_exit_witness"

        type TerminalFlowHudConsensusId =
            | TerminalFlowHudConsensusCold
            | TerminalFlowHudConsensusAwaitRoot
            | TerminalFlowHudConsensusActorBlocker of rootReceipt:string * actorPhase:TerminalSchedulerPushActorPhase * requiredNext:TerminalFlowHudRequiredNextId
            | TerminalFlowHudConsensusTerminalClosed of rootReceipt:string * actorPhase:TerminalSchedulerPushActorPhase
            | TerminalFlowHudConsensusDiverged of evaluator:string * observer:string

        let private terminalFlowHudConsensusText = function
            | TerminalFlowHudConsensusCold ->
                "TerminalFlowHudConsensus(Cold|root=unarmed|actor=noop)"
            | TerminalFlowHudConsensusAwaitRoot ->
                "TerminalFlowHudConsensus(AwaitRoot|action=await_evaluator_root_ivar)"
            | TerminalFlowHudConsensusActorBlocker(rootReceipt, actorPhase, requiredNext) ->
                "TerminalFlowHudConsensus(BLOCKER|root=" + rootReceipt + "|actor=" + terminalSchedulerPushActorPhaseText actorPhase + "|required_next=" + terminalFlowHudRequiredNextText requiredNext + ")"
            | TerminalFlowHudConsensusTerminalClosed(rootReceipt, actorPhase) ->
                "TerminalFlowHudConsensus(Closed|root=" + rootReceipt + "|actor=" + terminalSchedulerPushActorPhaseText actorPhase + ")"
            | TerminalFlowHudConsensusDiverged(evaluator, observer) ->
                "TerminalFlowHudConsensus(DIVERGED|evaluator=" + evaluator + "|observer=" + observer + ")"

        let terminalFlowHudConsensusNow () =
            let root = canonicalRootAuthoritySnapshot()
            let actor = terminalSchedulerPushActorSnapshot()
            match root.phase, actor.phase with
            | CanonicalRootUnarmed, PushActorNoop -> TerminalFlowHudConsensusCold
            | CanonicalRootUnarmed, _
            | CanonicalRootArmed _, _ -> TerminalFlowHudConsensusAwaitRoot
            | CanonicalRootResolved _, PushActorNoop ->
                TerminalFlowHudConsensusActorBlocker(root.receiptId, actor.phase, TerminalFlowHudAwaitQapThenAcquirePossession)
            | CanonicalRootResolved _, PushActorArmed
            | CanonicalRootResolved _, PushActorOutcomeFilled
            | CanonicalRootResolved _, PushActorWriterBound
            | CanonicalRootResolved _, PushActorArtifactsCommitted ->
                TerminalFlowHudConsensusActorBlocker(root.receiptId, actor.phase, TerminalFlowHudConsumeStageTokenOrFailClosed)
            | CanonicalRootResolved _, PushActorExitWitnessQueued ->
                TerminalFlowHudConsensusActorBlocker(root.receiptId, actor.phase, TerminalFlowHudCommitExitWitness)
            | CanonicalRootResolved _, PushActorConsumed
            | CanonicalRootResolved _, PushActorFailedClosed ->
                TerminalFlowHudConsensusTerminalClosed(root.receiptId, actor.phase)

        let terminalFlowHudConsensusTextNow () =
            terminalFlowHudConsensusNow() |> terminalFlowHudConsensusText

        type TerminalFlowProgressJsonEmissionClass =
            | TerminalFlowProgressJsonDropNull
            | TerminalFlowProgressJsonDropIdleNoDelta of sidecarRef:uint32
            | TerminalFlowProgressJsonDropSchemaOnly of sidecarRef:uint32
            | TerminalFlowProgressJsonEmitTerminal of terminalRef:uint32
            | TerminalFlowProgressJsonEmitViolationTransition of transitionRef:uint32
            | TerminalFlowProgressJsonEmitArmingOrRecovery of evidenceRef:uint32
            | TerminalFlowProgressJsonEmitOther

        let private terminalFlowProgressJsonEmissionClassText = function
            | TerminalFlowProgressJsonDropNull -> "drop_null"
            | TerminalFlowProgressJsonDropIdleNoDelta sidecarRef -> "drop_idle_no_delta:sidecar=" + string sidecarRef
            | TerminalFlowProgressJsonDropSchemaOnly sidecarRef -> "drop_schema_only:sidecar=" + string sidecarRef
            | TerminalFlowProgressJsonEmitTerminal terminalRef -> "emit_terminal:ref=" + string terminalRef
            | TerminalFlowProgressJsonEmitViolationTransition transitionRef -> "emit_violation_transition:ref=" + string transitionRef
            | TerminalFlowProgressJsonEmitArmingOrRecovery evidenceRef -> "emit_arming_or_recovery:ref=" + string evidenceRef
            | TerminalFlowProgressJsonEmitOther -> "emit_other"

        type TerminalFlowProgressStableFieldId =
            | TerminalFlowProgressStableKind
            | TerminalFlowProgressStableEvent
            | TerminalFlowProgressStablePhase
            | TerminalFlowProgressStableRoot
            | TerminalFlowProgressStableSchedulerActor
            | TerminalFlowProgressStableActorPhase
            | TerminalFlowProgressStableViolation
            | TerminalFlowProgressStableRecovery
            | TerminalFlowProgressStableOwnerClosure
            | TerminalFlowProgressStableTerminalReceipt
            | TerminalFlowProgressStableWorkDelta
            | TerminalFlowProgressStableSemanticReceipts
            | TerminalFlowProgressStableMissedIntervals
            | TerminalFlowProgressStableTickContract
            | TerminalFlowProgressStableTickSchema

        let private terminalFlowProgressStableFieldCandidates = function
            | TerminalFlowProgressStableKind -> ["kind"]
            | TerminalFlowProgressStableEvent -> ["event"]
            | TerminalFlowProgressStablePhase -> ["phase"; "live_graph_phase_du"]
            | TerminalFlowProgressStableRoot -> ["root_consensus_du"; "root_promise_status_du"]
            | TerminalFlowProgressStableSchedulerActor -> ["scheduler_push_actor_du"; "actor_state_du"]
            | TerminalFlowProgressStableActorPhase -> ["actor_phase"; "actor_phase_after_du"]
            | TerminalFlowProgressStableViolation -> ["violation_transition_du"; "transition_du"; "violation"]
            | TerminalFlowProgressStableRecovery -> ["recovery_ref"; "queue_recovery_ref"]
            | TerminalFlowProgressStableOwnerClosure -> ["owner_closure_authority_ref"; "owner_ledger_ref"]
            | TerminalFlowProgressStableTerminalReceipt -> ["terminal_receipt_ref"; "run_end_receipt_ref"]
            | TerminalFlowProgressStableWorkDelta -> ["work_delta"]
            | TerminalFlowProgressStableSemanticReceipts -> ["semantic_receipts"]
            | TerminalFlowProgressStableMissedIntervals -> ["missed_intervals"]
            | TerminalFlowProgressStableTickContract -> ["tick_contract"]
            | TerminalFlowProgressStableTickSchema -> ["tick_schema"]

        let private terminalFlowProgressStableField (fieldId:TerminalFlowProgressStableFieldId) (line:string) =
            let jsonField (key:string) =
                if System.Object.ReferenceEquals(line,null) then ""
                else
                    let token = "\"" + key + "\":"
                    let parts = line.Split([|token|], 2, StringSplitOptions.None)
                    if parts.Length <> 2 then ""
                    else
                        let rest = parts.[1].TrimStart()
                        if String.IsNullOrEmpty rest then ""
                        elif rest.[0] = '"' then
                            let mutable valueEnd = 1
                            let mutable escaped = false
                            while valueEnd < rest.Length && (escaped || rest.[valueEnd] <> '"') do
                                escaped <- (not escaped && rest.[valueEnd] = '\\')
                                if rest.[valueEnd] <> '\\' then escaped <- false
                                valueEnd <- valueEnd + 1
                            if valueEnd < rest.Length then rest.Substring(1, valueEnd - 1) else ""
                        else
                            let mutable valueEnd = 0
                            while valueEnd < rest.Length && rest.[valueEnd] <> ',' && rest.[valueEnd] <> '}' do
                                valueEnd <- valueEnd + 1
                            if valueEnd > 0 then rest.Substring(0, valueEnd).Trim().Trim([|'"'|]) else ""
            terminalFlowProgressStableFieldCandidates fieldId
            |> List.tryPick (fun key ->
                let value = jsonField key
                if System.String.IsNullOrWhiteSpace value then None else Some value)
            |> Option.defaultValue ""

        let private terminalFlowProgressStableDigest (line:string) =
            let stableFields =
                [ terminalFlowProgressStableField TerminalFlowProgressStableKind line
                  terminalFlowProgressStableField TerminalFlowProgressStableEvent line
                  terminalFlowProgressStableField TerminalFlowProgressStablePhase line
                  terminalFlowProgressStableField TerminalFlowProgressStableRoot line
                  terminalFlowProgressStableField TerminalFlowProgressStableSchedulerActor line
                  terminalFlowProgressStableField TerminalFlowProgressStableViolation line
                  terminalFlowProgressStableField TerminalFlowProgressStableRecovery line
                  terminalFlowProgressStableField TerminalFlowProgressStableOwnerClosure line
                  terminalFlowProgressStableField TerminalFlowProgressStableTerminalReceipt line ]
            let stablePayload = stableFields |> List.filter (fun value -> not (System.String.IsNullOrWhiteSpace value)) |> String.concat "|"
            NativeCutoverStableRef.ref32
                "terminal-flow-progress-stable-digest"
                [ if System.String.IsNullOrWhiteSpace stablePayload then line else stablePayload ]

        type TerminalFlowProgressSemanticEvidence =
            | TerminalFlowProgressSemanticTerminal
            | TerminalFlowProgressSemanticViolationTransition
            | TerminalFlowProgressSemanticArmingOrRecovery
            | TerminalFlowProgressSemanticIdleTick
            | TerminalFlowProgressSemanticTickSchema
            | TerminalFlowProgressSemanticOther

        let private terminalFlowProgressSemanticEvidenceFor (line:string) =
            let kind = terminalFlowProgressStableField TerminalFlowProgressStableKind line
            let event = terminalFlowProgressStableField TerminalFlowProgressStableEvent line
            let violationTransition = terminalFlowProgressStableField TerminalFlowProgressStableViolation line
            let recoveryRef = terminalFlowProgressStableField TerminalFlowProgressStableRecovery line
            let actorPhase = terminalFlowProgressStableField TerminalFlowProgressStableActorPhase line
            let workDelta = terminalFlowProgressStableField TerminalFlowProgressStableWorkDelta line
            let semanticReceipts = terminalFlowProgressStableField TerminalFlowProgressStableSemanticReceipts line
            let missedIntervals = terminalFlowProgressStableField TerminalFlowProgressStableMissedIntervals line
            let tickContract = terminalFlowProgressStableField TerminalFlowProgressStableTickContract line
            let tickSchema = terminalFlowProgressStableField TerminalFlowProgressStableTickSchema line
            match kind, event with
            | "run_end", _
            | "terminal_done_transition", _
            | "terminal_flow_physical_exit_boundary", _
            | "terminal_flow_typed_failure", _
            | _, "fail_closed"
            | _, "commit_exit_witness" -> TerminalFlowProgressSemanticTerminal
            | _ when violationTransition = "violation_appeared" || violationTransition = "violation_cleared" -> TerminalFlowProgressSemanticViolationTransition
            | _ when not (System.String.IsNullOrWhiteSpace recoveryRef) || actorPhase = "Armed" || actorPhase = "PushActorArmed" -> TerminalFlowProgressSemanticArmingOrRecovery
            | "progress_tick", _ when workDelta = "0" && semanticReceipts = "0" && missedIntervals = "0" -> TerminalFlowProgressSemanticIdleTick
            | "progress_tick", _ when not (System.String.IsNullOrWhiteSpace tickContract) && not (System.String.IsNullOrWhiteSpace tickSchema) -> TerminalFlowProgressSemanticTickSchema
            | _ -> TerminalFlowProgressSemanticOther

        let private terminalFlowProgressJsonEmissionClassify (line:string) =
            if System.Object.ReferenceEquals(line,null) then TerminalFlowProgressJsonDropNull
            else
                match terminalFlowProgressSemanticEvidenceFor line with
                | TerminalFlowProgressSemanticTerminal -> TerminalFlowProgressJsonEmitTerminal(terminalFlowProgressStableDigest line)
                | TerminalFlowProgressSemanticViolationTransition -> TerminalFlowProgressJsonEmitViolationTransition(terminalFlowProgressStableDigest line)
                | TerminalFlowProgressSemanticArmingOrRecovery -> TerminalFlowProgressJsonEmitArmingOrRecovery(terminalFlowProgressStableDigest line)
                | TerminalFlowProgressSemanticIdleTick -> TerminalFlowProgressJsonDropIdleNoDelta(terminalFlowProgressStableDigest line)
                | TerminalFlowProgressSemanticTickSchema -> TerminalFlowProgressJsonDropSchemaOnly(terminalFlowProgressStableDigest line)
                | TerminalFlowProgressSemanticOther -> TerminalFlowProgressJsonEmitOther

        let private terminalFlowHotJsonLineShouldEmit (line:string) =
            match terminalFlowProgressJsonEmissionClassify line with
            | TerminalFlowProgressJsonDropNull
            | TerminalFlowProgressJsonDropIdleNoDelta _
            | TerminalFlowProgressJsonDropSchemaOnly _ -> false
            | TerminalFlowProgressJsonEmitTerminal _
            | TerminalFlowProgressJsonEmitViolationTransition _
            | TerminalFlowProgressJsonEmitArmingOrRecovery _
            | TerminalFlowProgressJsonEmitOther -> true


        type TerminalFlowCriticalHudRowContract = {
            rowIndex : int
            rowName : string
            authorityRef : uint32
            renderedText : string
            isNonEmpty : bool
            violationWhenEmpty : string option
            }

        type TerminalFlowPureClosureHarnessInput = private {
            matureOutcomeRef : uint32
            ownerAuthorityRef : uint32
            recoveryRef : uint32
            fairnessRef : uint32
            actorArmedRef : uint32
            terminalPetitionRef : uint32
            }

        type TerminalFlowPureClosureHarnessVerdict =
            | TerminalFlowPureHarnessRunEndExpected of runEndRef:uint32 * doneRef:uint32 * commitRef:uint32
            | TerminalFlowPureHarnessRejected of missing:string list

        type TerminalFlowPureClosureHarnessReceipt = {
            harnessRef : uint32
            input : TerminalFlowPureClosureHarnessInput
            verdict : TerminalFlowPureClosureHarnessVerdict
            expectedJsonKind : string
            reducerOwned : bool
            observerOwned : bool
            }


        let private terminalFlowCriticalHudRowContract rowIndex rowName authorityRef renderedText =
            let nonEmpty = not (System.String.IsNullOrWhiteSpace renderedText)
            {
            rowIndex = rowIndex
            rowName = rowName
            authorityRef = authorityRef
            renderedText = if nonEmpty then renderedText else "authority_missing:row=" + rowName
            isNonEmpty = nonEmpty
            violationWhenEmpty = if nonEmpty then None else Some("hud_row_empty:" + rowName)
            }

        type TerminalFlowBreakthroughTxnOpenStage = class end
        type TerminalFlowBreakthroughTxnCovenantSealedStage = class end
        type TerminalFlowBreakthroughTxnCommittedStage = class end
        type TerminalFlowBreakthroughTxnRunEndedStage = class end

        type TerminalFlowBreakthroughTxn<'Stage> = private {
            transactionRef : uint32
            input : TerminalFlowPureClosureHarnessInput
            missing : string list
            commitRef : uint32 option
            doneRef : uint32 option
            runEndRef : uint32 option
        }

        let private terminalFlowBreakthroughTxnOpen input : TerminalFlowBreakthroughTxn<TerminalFlowBreakthroughTxnOpenStage> =
            let missing = ResizeArray<string>()
            if input.matureOutcomeRef = 0u then missing.Add "mature_outcome_ref"
            if input.ownerAuthorityRef = 0u then missing.Add "owner_authority_ref"
            if input.recoveryRef = 0u then missing.Add "recovery_ref"
            if input.fairnessRef = 0u then missing.Add "fairness_ref"
            if input.actorArmedRef = 0u then missing.Add "actor_armed_ref"
            if input.terminalPetitionRef = 0u then missing.Add "terminal_petition_ref"
            let transactionRef =
                NativeCutoverStableRef.ref32
                    "terminal-flow-breakthrough-transaction"
                    [ string input.matureOutcomeRef
                      string input.ownerAuthorityRef
                      string input.recoveryRef
                      string input.fairnessRef
                      string input.actorArmedRef
                      string input.terminalPetitionRef ]
            { transactionRef = transactionRef
              input = input
              missing = List.ofSeq missing
              commitRef = None
              doneRef = None
              runEndRef = None }

        let private terminalFlowBreakthroughTxnSeal (txn:TerminalFlowBreakthroughTxn<TerminalFlowBreakthroughTxnOpenStage>) =
            if List.isEmpty txn.missing then
                Ok ({ transactionRef = txn.transactionRef
                      input = txn.input
                      missing = []
                      commitRef = None
                      doneRef = None
                      runEndRef = None } : TerminalFlowBreakthroughTxn<TerminalFlowBreakthroughTxnCovenantSealedStage>)
            else Error txn.missing

        let private terminalFlowBreakthroughTxnCommit (txn:TerminalFlowBreakthroughTxn<TerminalFlowBreakthroughTxnCovenantSealedStage>) =
            let commitRef =
                NativeCutoverStableRef.ref32
                    "terminal-flow-breakthrough-commit"
                    [ string txn.transactionRef ]
            let doneRef =
                NativeCutoverStableRef.ref32
                    "terminal-flow-breakthrough-done"
                    [ string commitRef ]
            ({ transactionRef = txn.transactionRef
               input = txn.input
               missing = []
               commitRef = Some commitRef
               doneRef = Some doneRef
               runEndRef = None } : TerminalFlowBreakthroughTxn<TerminalFlowBreakthroughTxnCommittedStage>)

        let private terminalFlowBreakthroughTxnRunEnd (txn:TerminalFlowBreakthroughTxn<TerminalFlowBreakthroughTxnCommittedStage>) =
            let commitRef = txn.commitRef |> Option.defaultValue 0u
            let doneRef = txn.doneRef |> Option.defaultValue 0u
            let runEndRef =
                NativeCutoverStableRef.ref32
                    "terminal-flow-breakthrough-run-end"
                    [ string doneRef ]
            ({ transactionRef = txn.transactionRef
               input = txn.input
               missing = []
               commitRef = Some commitRef
               doneRef = Some doneRef
               runEndRef = Some runEndRef } : TerminalFlowBreakthroughTxn<TerminalFlowBreakthroughTxnRunEndedStage>)

        let private terminalFlowPureClosureHarnessRun input =
            let opened = terminalFlowBreakthroughTxnOpen input
            let verdict =
                match terminalFlowBreakthroughTxnSeal opened with
                | Error missing -> TerminalFlowPureHarnessRejected missing
                | Ok sealedTxn ->
                    let ended = sealedTxn |> terminalFlowBreakthroughTxnCommit |> terminalFlowBreakthroughTxnRunEnd
                    TerminalFlowPureHarnessRunEndExpected(
                        ended.runEndRef |> Option.defaultValue 0u,
                        ended.doneRef |> Option.defaultValue 0u,
                        ended.commitRef |> Option.defaultValue 0u)
            {
            harnessRef = opened.transactionRef
            input = input
            verdict = verdict
            expectedJsonKind = "run_end"
            reducerOwned = true
            observerOwned = false
            }

        type TerminalFlowPureClosureHarnessVector = {
            name : string
            input : TerminalFlowPureClosureHarnessInput
            expectRunEnd : bool
            expectedMissing : string list
        }

        let private terminalFlowPureClosureHarnessVectors =
            let complete =
                { matureOutcomeRef = 11u
                  ownerAuthorityRef = 12u
                  recoveryRef = 13u
                  fairnessRef = 14u
                  actorArmedRef = 15u
                  terminalPetitionRef = 16u }
            [ { name = "mature_outcome_total_order"; input = complete; expectRunEnd = true; expectedMissing = [] }
              { name = "missing_mature_outcome"; input = { complete with matureOutcomeRef = 0u }; expectRunEnd = false; expectedMissing = ["mature_outcome_ref"] }
              { name = "missing_owner_authority"; input = { complete with ownerAuthorityRef = 0u }; expectRunEnd = false; expectedMissing = ["owner_authority_ref"] }
              { name = "missing_recovery"; input = { complete with recoveryRef = 0u }; expectRunEnd = false; expectedMissing = ["recovery_ref"] }
              { name = "missing_fairness"; input = { complete with fairnessRef = 0u }; expectRunEnd = false; expectedMissing = ["fairness_ref"] }
              { name = "missing_actor_arming"; input = { complete with actorArmedRef = 0u }; expectRunEnd = false; expectedMissing = ["actor_armed_ref"] }
              { name = "missing_terminal_petition"; input = { complete with terminalPetitionRef = 0u }; expectRunEnd = false; expectedMissing = ["terminal_petition_ref"] } ]

        let private terminalFlowPureClosureHarnessContractReceipts =
            terminalFlowPureClosureHarnessVectors
            |> List.map (fun vector -> vector.name, terminalFlowPureClosureHarnessRun vector.input)

        type TelemetryContentKind =
            | TelemetrySchemaVersion
            | TelemetryRunIdentity
            | TelemetryProgressContext
            | TelemetryElapsedSource
            | TelemetryRootConsensusPayload
            | TelemetrySchedulerActorPayload
            | TelemetryTaskbarResourceSnapshot

        let private telemetryContentKindText = function
            | TelemetrySchemaVersion -> "schema_version"
            | TelemetryRunIdentity -> "run_identity"
            | TelemetryProgressContext -> "progress_context"
            | TelemetryElapsedSource -> "elapsed_source"
            | TelemetryRootConsensusPayload -> "root_consensus_du_payload"
            | TelemetrySchedulerActorPayload -> "scheduler_actor_du_payload"
            | TelemetryTaskbarResourceSnapshot -> "taskbar_resource_snapshot"

        let private telemetryContentCategoryText = function
            | TelemetryRootConsensusPayload
            | TelemetrySchedulerActorPayload -> "du_payload"
            | TelemetryTaskbarResourceSnapshot -> "resource_snapshot"
            | TelemetrySchemaVersion
            | TelemetryRunIdentity
            | TelemetryProgressContext
            | TelemetryElapsedSource -> "metadata"

        type TelemetryContent = private {
            kind : TelemetryContentKind
            contentRef : CompilerIdentityKernel.ContentDigest
            payload : string
        }

        type TelemetryEnvelopeSource = private {
            schemaVersion : string
            runId : string
            progressContext : string
            elapsedSource : string
            rootConsensus : string
            schedulerPushActor : string
            taskbarRuntime : string
        }

        type TelemetryEnvelope = private {
            schemaRef : CompilerIdentityKernel.ContentDigest
            runRef : CompilerIdentityKernel.ContentDigest
            progressRef : CompilerIdentityKernel.ContentDigest
            elapsedRef : CompilerIdentityKernel.ContentDigest
            rootConsensusRef : CompilerIdentityKernel.ContentDigest
            schedulerActorRef : CompilerIdentityKernel.ContentDigest
            taskbarResourceRef : CompilerIdentityKernel.ContentDigest
        }

        type TelemetryEnvelopeIntern = private {
            envelopeRef : CompilerIdentityKernel.ContentDigest
            envelopeDefinitionRequired : bool
            newComponents : TelemetryContent list
            envelope : TelemetryEnvelope
            definitionRevision : int64
        }

        type TelemetryInternState = private {
            definedContentRefs : Set<string>
            definedEnvelopeRefs : Set<string>
            revision : int64
        }

        let private telemetryEnvelopeGate = obj()
        let mutable private telemetryInternState =
            { definedContentRefs = Set.empty
              definedEnvelopeRefs = Set.empty
              revision = 0L }

        let private telemetryContent kind payload =
            let kindText = telemetryContentKindText kind
            { kind = kind
              contentRef = CompilerIdentityKernel.ContentDigest.ofText ("telemetry-content:" + kindText) payload
              payload = payload }

        let private telemetryEnvelopePayload envelope =
            String.concat "|"
                [ "schema_ref=" + CompilerIdentityKernel.ContentDigest.text envelope.schemaRef
                  "run_ref=" + CompilerIdentityKernel.ContentDigest.text envelope.runRef
                  "progress_ref=" + CompilerIdentityKernel.ContentDigest.text envelope.progressRef
                  "elapsed_ref=" + CompilerIdentityKernel.ContentDigest.text envelope.elapsedRef
                  "root_ref=" + CompilerIdentityKernel.ContentDigest.text envelope.rootConsensusRef
                  "actor_ref=" + CompilerIdentityKernel.ContentDigest.text envelope.schedulerActorRef
                  "taskbar_ref=" + CompilerIdentityKernel.ContentDigest.text envelope.taskbarResourceRef ]

        let private internTelemetryEnvelope source =
            let components =
                [ telemetryContent TelemetrySchemaVersion source.schemaVersion
                  telemetryContent TelemetryRunIdentity source.runId
                  telemetryContent TelemetryProgressContext source.progressContext
                  telemetryContent TelemetryElapsedSource source.elapsedSource
                  telemetryContent TelemetryRootConsensusPayload source.rootConsensus
                  telemetryContent TelemetrySchedulerActorPayload source.schedulerPushActor
                  telemetryContent TelemetryTaskbarResourceSnapshot source.taskbarRuntime ]
            let contentRef kind =
                components
                |> List.find (fun contentEntry -> contentEntry.kind = kind)
                |> fun contentEntry -> contentEntry.contentRef
            let envelope =
                { schemaRef = contentRef TelemetrySchemaVersion
                  runRef = contentRef TelemetryRunIdentity
                  progressRef = contentRef TelemetryProgressContext
                  elapsedRef = contentRef TelemetryElapsedSource
                  rootConsensusRef = contentRef TelemetryRootConsensusPayload
                  schedulerActorRef = contentRef TelemetrySchedulerActorPayload
                  taskbarResourceRef = contentRef TelemetryTaskbarResourceSnapshot }
            let envelopeRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "telemetry-envelope"
                    (telemetryEnvelopePayload envelope)
            lock telemetryEnvelopeGate (fun () ->
                let componentKey contentEntry = CompilerIdentityKernel.ContentDigest.text contentEntry.contentRef
                let newComponents =
                    components
                    |> List.filter (fun contentEntry ->
                        not (Set.contains (componentKey contentEntry) telemetryInternState.definedContentRefs))
                let envelopeKey = CompilerIdentityKernel.ContentDigest.text envelopeRef
                let envelopeDefinitionRequired =
                    not (telemetryInternState.definedEnvelopeRefs.Contains envelopeKey)
                let hasNewDefinition = envelopeDefinitionRequired || not (List.isEmpty newComponents)
                let revision =
                    if hasNewDefinition then telemetryInternState.revision + 1L
                    else telemetryInternState.revision
                telemetryInternState <-
                    { definedContentRefs =
                        newComponents
                        |> List.fold (fun known contentEntry -> Set.add (componentKey contentEntry) known) telemetryInternState.definedContentRefs
                      definedEnvelopeRefs =
                        if envelopeDefinitionRequired then Set.add envelopeKey telemetryInternState.definedEnvelopeRefs
                        else telemetryInternState.definedEnvelopeRefs
                      revision = revision }
                { envelopeRef = envelopeRef
                  envelopeDefinitionRequired = envelopeDefinitionRequired
                  newComponents = newComponents
                  envelope = envelope
                  definitionRevision = revision })

        let private telemetryContentDefinitionsJson interned =
            match interned.newComponents with
            | [] -> ""
            | components ->
                let body =
                    components
                    |> List.map (fun contentEntry ->
                        FastRuntimeFormat.format "{\"kind_du\":%s,\"category_du\":%s,\"content_ref\":%s,\"payload\":%s}" [| box (esc (telemetryContentKindText contentEntry.kind)); box (esc (telemetryContentCategoryText contentEntry.kind)); box (esc (CompilerIdentityKernel.ContentDigest.text contentEntry.contentRef)); box (esc contentEntry.payload) |])
                    |> String.concat ","
                ",\"telemetry_content_du\":[" + body + "]"

        let private telemetryEnvelopeDefinitionJson interned =
            if not interned.envelopeDefinitionRequired then ""
            else
                let envelope = interned.envelope
                FastRuntimeFormat.format ",\"telemetry_envelope_du\":{\"definition_revision\":%d,\"schema_ref\":%s,\"run_ref\":%s,\"progress_context_ref\":%s,\"elapsed_source_ref\":%s,\"root_consensus_payload_ref\":%s,\"scheduler_actor_payload_ref\":%s,\"taskbar_resource_snapshot_ref\":%s}" [| box interned.definitionRevision; box (esc (CompilerIdentityKernel.ContentDigest.text envelope.schemaRef)); box (esc (CompilerIdentityKernel.ContentDigest.text envelope.runRef)); box (esc (CompilerIdentityKernel.ContentDigest.text envelope.progressRef)); box (esc (CompilerIdentityKernel.ContentDigest.text envelope.elapsedRef)); box (esc (CompilerIdentityKernel.ContentDigest.text envelope.rootConsensusRef)); box (esc (CompilerIdentityKernel.ContentDigest.text envelope.schedulerActorRef)); box (esc (CompilerIdentityKernel.ContentDigest.text envelope.taskbarResourceRef)) |]

        let private enrichJsonLineWithSeqRunConsensus (line:string) =
            try
                match jsonObjectEnvelopeId line with
                | JsonEnvelopeOther -> line
                | JsonEnvelopeV1Object
                | JsonEnvelopeObject ->
                    let seqNo = terminalFlowNextJsonSeq()
                    let hasJsonField field = jsonHasField field line
                    let seqField = if hasJsonField "seq" then "" else sprintf ",\"seq\":%d" seqNo
                    let envelope =
                        { schemaVersion = "terminal_flow"
                          runId = run_id
                          progressContext = "typed_reducer_snapshot_only"
                          elapsedSource = "monotonic_emit_wall_clock"
                          rootConsensus = terminalFlowHudConsensusTextNow()
                          schedulerPushActor = terminalSchedulerPushActorText()
                          taskbarRuntime = CompilerConsoleHud88.taskbarRuntimeStatusNow() }
                    let interned = internTelemetryEnvelope envelope
                    let envelopeRefField =
                        if hasJsonField "telemetry_envelope_ref" then ""
                        else ",\"telemetry_envelope_ref\":" + esc (CompilerIdentityKernel.ContentDigest.text interned.envelopeRef)
                    let contentDefinitionField = telemetryContentDefinitionsJson interned
                    let envelopeDefinitionField = telemetryEnvelopeDefinitionJson interned
                    line.Substring(0, line.Length - 1)
                    + seqField
                    + envelopeRefField
                    + contentDefinitionField
                    + envelopeDefinitionField
                    + "}"
            with _ -> line

        // MIGRATION round : shared TerminalFlow kernel. The historical file
        // still contains two local TerminalFlow renderers, but both must now
        // project through this single spine instead of inventing independent
        // root/receipt meanings. Round 3 will move the server loop itself here.
        module TerminalFlowSharedKernel =
            [<Struct>]
            type TerminalFlowSharedKind = struct end

            type RootTruth =
                | RootTruthEvaluator of receipt:string
                | RootTruthAwaitEvaluator of evidence:string
                | RootTruthDiverged of evaluatorReceipt:string * observerEvidence:string

            type ReceiptOwner =
                | ReceiptOwnerEvaluator
                | ReceiptOwnerSchedulerPushActor
                | ReceiptOwnerTerminalFlowProjection

            type TerminalFlowSharedAction =
                | DispatchSchedulerPush
                | AwaitEvaluatorRootIvar
                | FailClosedRootConsensusDiverged

            type TerminalFlowSharedDecision = {
                rootTruth : RootTruth
                receiptOwner : ReceiptOwner
                terminalReceiptRef : uint32
                action : TerminalFlowSharedAction
            }

            let rootTruthText = function
                | RootTruthEvaluator receipt -> "RootTruth(Evaluator|receipt=" + receipt + ")"
                | RootTruthAwaitEvaluator evidence ->
                    let evidenceRef = NativeCutoverStableRef.ref32 "root-truth-await-evaluator" [ evidence ]
                    "RootTruth(AwaitEvaluator|evidence_ref=" + string evidenceRef + ")"
                | RootTruthDiverged(evaluatorReceipt, observerEvidence) ->
                    let observerRef = NativeCutoverStableRef.ref32 "root-truth-diverged-observer" [ observerEvidence ]
                    "RootTruth(Diverged|evaluator=" + evaluatorReceipt + "|observer_ref=" + string observerRef + ")"

            let receiptOwnerText = function
                | ReceiptOwnerEvaluator -> "evaluator"
                | ReceiptOwnerSchedulerPushActor -> "scheduler_push_actor"
                | ReceiptOwnerTerminalFlowProjection -> "terminal_flow_projection"

            let actionText = function
                | DispatchSchedulerPush -> "dispatch_scheduler_push"
                | AwaitEvaluatorRootIvar -> "await_evaluator_root_ivar"
                | FailClosedRootConsensusDiverged -> "fail_closed_root_consensus_diverged"

            let decisionText decision =
                "TerminalFlowSharedDecision(root=" + rootTruthText decision.rootTruth
                + "|owner=" + receiptOwnerText decision.receiptOwner
                + "|terminal_receipt_ref=" + string decision.terminalReceiptRef
                + "|action=" + actionText decision.action + ")"

            let decisionForTerminalProjection rootReceipt terminalReceipt fillKey =
                let bridge = canonicalRootAuthorityTerminalProjection rootReceipt ("shared_terminal_projection|terminal=" + terminalReceipt + "|fill=" + fillKey)
                match bridge with
                | CanonicalRootBridgeAcceptedProjection receipt ->
                    { rootTruth = RootTruthEvaluator receipt
                      receiptOwner = ReceiptOwnerSchedulerPushActor
                      terminalReceiptRef =
                          NativeCutoverStableRef.ref32
                              "terminal-flow-shared-terminal-receipt"
                              [ terminalReceipt ]
                      action = DispatchSchedulerPush }
                | CanonicalRootBridgeRejectedAwaitEvaluator evidence ->
                    { rootTruth = RootTruthAwaitEvaluator evidence
                      receiptOwner = ReceiptOwnerTerminalFlowProjection
                      terminalReceiptRef =
                          NativeCutoverStableRef.ref32
                              "terminal-flow-shared-terminal-receipt"
                              [ terminalReceipt ]
                      action = AwaitEvaluatorRootIvar }
                | CanonicalRootBridgeDiverged(evaluatorReceipt, observerEvidence) ->
                    { rootTruth = RootTruthDiverged(evaluatorReceipt, observerEvidence)
                      receiptOwner = ReceiptOwnerTerminalFlowProjection
                      terminalReceiptRef =
                          NativeCutoverStableRef.ref32
                              "terminal-flow-shared-terminal-receipt"
                              [ terminalReceipt ]
                      action = FailClosedRootConsensusDiverged }

        // MIGRATION: keep the minimal metronome worker-introspection helpers inside
        // DiagJson itself.  MIGRATION defined the HUD-side DUs in CompilerConsoleHud88,
        // but the true metronome is an outer sibling module and cannot see private HUD
        // helpers or unqualified constructors.  Duplicate the tiny diagnostic contract
        // here so FS0039 cannot regress and the JSONL schema remains typed at the
        // emission point.
        let private parseInt64Safe (s: string) =
            let mutable v = 0L
            if Int64.TryParse((if isNull s then "" else s).Trim(), &v) then v else 0L

        // MIGRATION: typed progress/ETA estimator.  The rich historical score is
        // still exported as runtime_activity_score, but percentage/ETA authority
        // now comes from graph remaining/total plus a fused EWMA rate.  Topology
        // witnesses pause the ETA clock rather than decaying throughput to zero.
        type GraphProgressPhaseId =
            | GraphProgressMaterial
            | GraphProgressTopologyPause
            | GraphProgressRescueInProgress
            | GraphProgressTerminalExhausted

        let private graphProgressPhaseText = function
            | GraphProgressMaterial -> "material_progress"
            | GraphProgressTopologyPause -> "topology_clock_paused"
            | GraphProgressRescueInProgress -> "rescue_in_progress_live_graph"
            | GraphProgressTerminalExhausted -> "terminal_exhausted"

        type ProgressEstimatorAuthorityModelId =
            | ProgressEstimatorAuthorityColdStart
            | ProgressEstimatorAuthoritySampledWorkOnly
            | ProgressEstimatorAuthorityReplayScheduleOnly
            | ProgressEstimatorAuthorityReplayTerminalChatterNoRoot
            | ProgressEstimatorAuthorityReplayDriverNoRoot
            | ProgressEstimatorAuthoritySparseRootNoSemantic
            | ProgressEstimatorAuthorityLowAuthorityRootTerminalDrip
            | ProgressEstimatorAuthorityDriverOrRootAuthority
            | ProgressEstimatorAuthorityWorkUnitDenominator

        let private progressEstimatorAuthorityModelText = function
            | ProgressEstimatorAuthorityColdStart -> "cold_start"
            | ProgressEstimatorAuthoritySampledWorkOnly -> "sampled_work_only"
            | ProgressEstimatorAuthorityReplayScheduleOnly -> "replay_schedule_only"
            | ProgressEstimatorAuthorityReplayTerminalChatterNoRoot -> "replay_terminal_chatter_no_root"
            | ProgressEstimatorAuthorityReplayDriverNoRoot -> "replay_driver_no_root"
            | ProgressEstimatorAuthoritySparseRootNoSemantic -> "sparse_root_no_semantic"
            | ProgressEstimatorAuthorityLowAuthorityRootTerminalDrip -> "low_authority_root_terminal_drip"
            | ProgressEstimatorAuthorityDriverOrRootAuthority -> "driver_or_root_authority"
            | ProgressEstimatorAuthorityWorkUnitDenominator -> "progress_work_unit_denominator"

        type ProgressEstimatorModelId =
            | ProgressEstimatorGraphExhaustion of remaining:int64 * total:int64 * sameStateRepeat:int64 * poisonTail:string
            | ProgressEstimatorAuthorityOnly of ProgressEstimatorAuthorityModelId

        let private progressEstimatorModelText = function
            | ProgressEstimatorGraphExhaustion(remaining,total,sameStateRepeat,poisonTail) ->
                FastRuntimeFormat.format "ProgressEstimator(GraphExhaustion|remaining=%d|total=%d|same_state_repeat=%d|poison_tail=%s)" [| box remaining; box total; box sameStateRepeat; box poisonTail |]
            | ProgressEstimatorAuthorityOnly model ->
                sprintf "ProgressEstimator(AuthorityOnly|model=%s)" (progressEstimatorAuthorityModelText model)

        type GraphProgressEwmaState = {
            mutable lastTsMs : int64
            mutable ewmaRate : float
            mutable variance : float
            mutable lastModel : ProgressEstimatorModelId
            mutable lastPoisonTail : string
        }
        type WorkUnitId = { value : string }

        type GraphProgressWorkKind =
            | WorkKindSemanticMaterial
            | WorkKindRootAuthority
            | WorkKindTerminalAuthority
            | WorkKindQueueDrain
            | WorkKindCrossKind
            | WorkKindSidecar
            | WorkKindContinuation
            | WorkKindUndiscoveredReserve
            | WorkKindObserverActivity

        type GraphProgressWorkState =
            | WorkUnitDiscovered
            | WorkUnitCompleted
            | WorkUnitBlocked
            | WorkUnitReservedUndiscovered
            | WorkUnitObserverOnly

        type GraphDiscoveryState =
            | GraphDiscoveryClosed
            | GraphDiscoveryOpen of undiscoveredP50:int64 * undiscoveredP90:int64

        type GraphProgressAuthorityId =
            | GraphProgressAuthoritativeGeneric
            | GraphProgressExhaustedOrUnpopulated

        let private graphProgressAuthorityText = function
            | GraphProgressAuthoritativeGeneric -> "GraphWorkLedger(authoritative_generic|completion=material_exact_once|observer=activity_score|eta=multi_horizon_ewma)"
            | GraphProgressExhaustedOrUnpopulated -> "GraphWorkLedger(exhausted_or_unpopulated|old_score=runtime_activity_score)"

        let private graphProgressWorkKindText = function
            | WorkKindSemanticMaterial -> "semantic_material"
            | WorkKindRootAuthority -> "root_authority"
            | WorkKindTerminalAuthority -> "terminal_authority"
            | WorkKindQueueDrain -> "queue_drain"
            | WorkKindCrossKind -> "cross_kind"
            | WorkKindSidecar -> "sidecar"
            | WorkKindContinuation -> "continuation"
            | WorkKindUndiscoveredReserve -> "undiscovered_reserve"
            | WorkKindObserverActivity -> "observer_activity"

        let private graphProgressWorkStateText = function
            | WorkUnitDiscovered -> "discovered"
            | WorkUnitCompleted -> "completed_exact_once"
            | WorkUnitBlocked -> "blocked_live_dependency"
            | WorkUnitReservedUndiscovered -> "reserved_undiscovered"
            | WorkUnitObserverOnly -> "observer_only_not_completion"

        let private graphDiscoveryStateText = function
            | GraphDiscoveryClosed -> "DiscoveryClosed"
            | GraphDiscoveryOpen(p50,p90) -> sprintf "DiscoveryOpen(undiscovered_p50=%d|undiscovered_p90=%d)" p50 p90

        // Promote the hot WorkUnit stasis/credit/ETA horizon from
        // renderer strings into typed local DUs.  This keeps the JSON/HUD text
        // as erasure only while the scheduler spine reasons over algebraic
        // states: zero-fact bind repeat-cap, material credit, or deferred live
        // lease.  The next migration can consume these cases directly in the
        // terminal commit gate instead of re-parsing rendered strings.
        type GraphStasisReasonId =
            | GraphStasisZeroFactOrTopologyWait of sameStateRepeat:int64
            | GraphStasisMaterialOrFreshProgress

        type WorkUnitCreditDeferredReasonId =
            | WorkUnitCreditTerminalGraphClosedNoMaterialDelta
            | WorkUnitCreditTerminalGraphQuiescentAwaitingClosureAuthority
            | WorkUnitCreditTerminalGraphNoMaterialDelta
            | WorkUnitCreditProgressTickClosedGraphNoMaterialDelta
            | WorkUnitCreditProgressTickQuiescentAwaitingClosureAuthority
            | WorkUnitCreditAwaitingMaterialOrConservedCreditClosure

        type WorkUnitCreditDecisionId =
            | WorkUnitCreditMaterialDelta of cost:int64
            | WorkUnitCreditDeferred of WorkUnitCreditDeferredReasonId

        type EtaStasisHorizonId =
            | EtaStasisStalledOnBoundGraph of sameStateRepeat:int64
            | EtaStasisUnknownLiveGraphRate
            | EtaStasisNormal

        type EtaConfidenceLevelId =
            | EtaConfidenceUnavailable
            | EtaConfidenceHigh
            | EtaConfidenceMedium
            | EtaConfidenceLow

        let private etaConfidenceLevelText = function
            | EtaConfidenceUnavailable -> "rescue_or_topology_pause"
            | EtaConfidenceHigh -> "high"
            | EtaConfidenceMedium -> "medium"
            | EtaConfidenceLow -> "low"

        let private graphStasisReasonText = function
            | GraphStasisZeroFactOrTopologyWait repeat ->
                sprintf "GraphStasis(zero_fact_or_topology_wait|same_state_repeat=%d)" repeat
            | GraphStasisMaterialOrFreshProgress ->
                "GraphStasis(material_or_fresh_progress)"

        let private workUnitCreditDeferredReasonText = function
            | WorkUnitCreditTerminalGraphClosedNoMaterialDelta -> "terminal_graph_closed_no_material_delta"
            | WorkUnitCreditTerminalGraphQuiescentAwaitingClosureAuthority -> "terminal_graph_quiescent_awaiting_closure_authority"
            | WorkUnitCreditTerminalGraphNoMaterialDelta -> "terminal_graph_no_material_delta"
            | WorkUnitCreditProgressTickClosedGraphNoMaterialDelta -> "progress_tick_closed_graph_no_material_delta"
            | WorkUnitCreditProgressTickQuiescentAwaitingClosureAuthority -> "progress_tick_quiescent_awaiting_closure_authority"
            | WorkUnitCreditAwaitingMaterialOrConservedCreditClosure -> "awaiting_material_or_conserved_credit_closure"

        let private workUnitCreditDecisionText = function
            | WorkUnitCreditMaterialDelta cost ->
                sprintf "WorkUnitCredit(MaterialDelta|cost=%d)" cost
            | WorkUnitCreditDeferred reason ->
                sprintf "WorkUnitCredit(Deferred|reason=%s)" (workUnitCreditDeferredReasonText reason)

        let private etaStasisHorizonText = function
            | EtaStasisStalledOnBoundGraph repeat ->
                sprintf "EtaStasisHorizon(stalled_on_bound_graph|same_state_repeat=%d|diagnostic_repeat_only_no_terminal_authority)" repeat
            | EtaStasisUnknownLiveGraphRate ->
                "EtaStasisHorizon(unknown_live_graph_rate)"
            | EtaStasisNormal ->
                "EtaStasisHorizon(normal)"

        let private workUnitIdFor (phase:string) (kind:string) (key:string) =
            let raw = (if System.String.IsNullOrWhiteSpace key then "none" else key).Replace("\n","|").Replace("\r","")
            let rawHash = CompilerIdentityKernel.ContentDigest.ofText "work-unit-key" raw |> CompilerIdentityKernel.ContentDigest.text
            { value = FastRuntimeFormat.format "wu:%s:%s:%s" [| box phase; box kind; box rawHash |] }

        type EtaSuccessUnavailableReasonId =
            | EtaSuccessTerminalFailureOrPoisonFrontier
            | EtaSuccessTerminalOrPoisonAuthorityFrontier
            | EtaSuccessUnknownLiveGraphRate

        type EtaSuccessBasisId =
            | EtaSuccessUnavailable of EtaSuccessUnavailableReasonId
            | EtaSuccessMinimalSameAsTerminalUntilBuildOkSplit
            | EtaSuccessRichSameAsTerminalUntilBuildOkSplit

        let private etaSuccessUnavailableReasonText = function
            | EtaSuccessTerminalFailureOrPoisonFrontier -> "terminal_failure_or_poison_frontier"
            | EtaSuccessTerminalOrPoisonAuthorityFrontier -> "terminal_or_poison_authority_frontier"
            | EtaSuccessUnknownLiveGraphRate -> "unknown_live_graph_rate"

        let private etaSuccessBasisText = function
            | EtaSuccessUnavailable reason -> sprintf "EtaSuccessUnavailable(reason=%s)" (etaSuccessUnavailableReasonText reason)
            | EtaSuccessMinimalSameAsTerminalUntilBuildOkSplit -> "EtaSuccessBasis(same_as_terminal_until_build_ok_split_lands)"
            | EtaSuccessRichSameAsTerminalUntilBuildOkSplit -> "EtaSuccessBasis(rich_same_as_terminal_until_build_ok_split_lands)"

        let private graphProgressEwmaLedger =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, GraphProgressEwmaState>()

        let private graphProgressObserveRate (key:string) (nowMs:int64) (model:ProgressEstimatorModelId) (poisonTail:string) (phase:GraphProgressPhaseId) (deltaCost:int64) (windowS:float) =
            let sampleRate =
                if deltaCost <= 0L || windowS <= 0.0 then 0.0
                else (float deltaCost) / windowS
            let seed () = { lastTsMs = nowMs; ewmaRate = sampleRate; variance = 0.0; lastModel = model; lastPoisonTail = poisonTail }
            let keyRef = CompilerIdentityKernel.ContentDigest.ofText "graph-progress-ewma" key
            let state = graphProgressEwmaLedger.GetOrAdd(keyRef, fun _ -> seed())
            let phaseReset = state.lastModel <> model || state.lastPoisonTail <> poisonTail
            let oldRate = max 0.0 state.ewmaRate
            let alpha = if phaseReset then 0.55 else 0.30
            let nextRate =
                match phase with
                | GraphProgressTopologyPause -> oldRate
                | GraphProgressRescueInProgress when sampleRate <= 0.0 -> oldRate
                | GraphProgressTerminalExhausted -> max oldRate sampleRate
                | _ -> (alpha * sampleRate) + ((1.0 - alpha) * oldRate)
            let diff = sampleRate - nextRate
            let nextVariance =
                match phase with
                | GraphProgressTopologyPause -> state.variance * 0.90
                | GraphProgressRescueInProgress when sampleRate <= 0.0 -> state.variance + max 1.0 (oldRate * 0.25)
                | _ -> (alpha * diff * diff) + ((1.0 - alpha) * max 0.0 state.variance)
            state.lastTsMs <- nowMs
            state.ewmaRate <- nextRate
            state.variance <- nextVariance
            state.lastModel <- model
            state.lastPoisonTail <- poisonTail
            nextRate, nextVariance, System.Math.Sqrt(max 0.0 nextVariance), phaseReset

        // MIGRATION: DiagJson owns the executable ETA horizon ledger.
        type GraphProgressHorizonState = {
            mutable lastTsMs : int64
            mutable shortRate : float
            mutable mediumRate : float
            mutable sessionRate : float
            mutable variance : float
            mutable lastPhase : GraphProgressPhaseId
            mutable lastPoisonTail : string
            mutable samples : int64
        }

        type GraphProgressHorizonSnapshot = {
            shortRate : float
            mediumRate : float
            sessionRate : float
            fusedRate : float
            variance : float
            sigma : float
            confidenceProbability : float
            samples : int64
            phaseTransitionReset : bool
            topologyClockPaused : bool
            rescueUnknownButLive : bool
        }

        let private graphProgressHorizonSnapshotText (x:GraphProgressHorizonSnapshot) =
            FastRuntimeFormat.format "GraphProgressHorizon(short=%.4f|medium=%.4f|session=%.4f|fused=%.4f|variance=%.4f|sigma=%.4f|confidence=%.4f|samples=%d|phase_reset=%b|topology_pause=%b|rescue_unknown_live=%b)" [| box x.shortRate; box x.mediumRate; box x.sessionRate; box x.fusedRate; box x.variance; box x.sigma; box x.confidenceProbability; box x.samples; box x.phaseTransitionReset; box x.topologyClockPaused; box x.rescueUnknownButLive |]

        let private graphProgressHorizonLedger =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, GraphProgressHorizonState>()

        let private graphProgressObserveHorizonRate (key:string) (nowMs:int64) (poisonTail:string) (phase:GraphProgressPhaseId) (deltaCost:int64) (windowS:float) =
            let sampleRate = if deltaCost <= 0L || windowS <= 0.0 then 0.0 else (float deltaCost) / windowS
            let seed () = { lastTsMs = nowMs; shortRate = sampleRate; mediumRate = sampleRate; sessionRate = sampleRate; variance = 0.0; lastPhase = phase; lastPoisonTail = poisonTail; samples = 0L }
            let keyRef = CompilerIdentityKernel.ContentDigest.ofText "graph-progress-horizon" key
            let state = graphProgressHorizonLedger.GetOrAdd(keyRef, fun _ -> seed())
            let phaseReset = state.lastPhase <> phase || state.lastPoisonTail <> poisonTail
            let topologyPaused = phase = GraphProgressTopologyPause
            let rescueUnknownButLive = phase = GraphProgressRescueInProgress && sampleRate <= 0.0
            let observe alpha oldRate =
                if topologyPaused || rescueUnknownButLive then oldRate
                elif phaseReset then (0.70 * sampleRate) + (0.30 * oldRate)
                else (alpha * sampleRate) + ((1.0 - alpha) * oldRate)
            let nextShort = observe 0.55 (max 0.0 state.shortRate)
            let nextMedium = observe 0.18 (max 0.0 state.mediumRate)
            let nextSession = observe 0.045 (max 0.0 state.sessionRate)
            let priorSigma = System.Math.Sqrt(max 0.0 state.variance)
            let volatility = min 1.0 (priorSigma / max 1.0 (nextShort + nextMedium + nextSession))
            let shortWeight = 0.55 - (0.35 * volatility)
            let mediumWeight = 0.30 + (0.15 * volatility)
            let sessionWeight = max 0.10 (1.0 - shortWeight - mediumWeight)
            let weightTotal = shortWeight + mediumWeight + sessionWeight
            let fused =
                if nextShort <= 0.0 && nextMedium <= 0.0 then nextSession
                elif rescueUnknownButLive then max nextMedium nextSession
                else ((shortWeight * nextShort) + (mediumWeight * nextMedium) + (sessionWeight * nextSession)) / max 0.000001 weightTotal
            let diff = sampleRate - fused
            let nextVariance =
                if topologyPaused then state.variance * 0.92
                elif rescueUnknownButLive then state.variance + max 1.0 (fused * 0.35)
                else (0.25 * diff * diff) + (0.75 * max 0.0 state.variance)
            let sigma = System.Math.Sqrt(max 0.0 nextVariance)
            let evidence = min 1.0 (float (state.samples + 1L) / 12.0)
            let stability = 1.0 / (1.0 + (sigma / max 1.0 fused))
            let confidence =
                if fused <= 0.0 || rescueUnknownButLive then max 0.05 (0.35 * evidence * stability)
                elif topologyPaused then max 0.15 (0.50 * evidence * stability)
                else min 0.98 (max 0.05 (0.70 * evidence + 0.30 * stability))
            state.lastTsMs <- nowMs
            state.shortRate <- nextShort
            state.mediumRate <- nextMedium
            state.sessionRate <- nextSession
            state.variance <- nextVariance
            state.lastPhase <- phase
            state.lastPoisonTail <- poisonTail
            state.samples <- state.samples + 1L
            { shortRate = nextShort; mediumRate = nextMedium; sessionRate = nextSession; fusedRate = fused; variance = nextVariance; sigma = sigma; confidenceProbability = confidence; samples = state.samples; phaseTransitionReset = phaseReset; topologyClockPaused = topologyPaused; rescueUnknownButLive = rescueUnknownButLive }

