        // MIGRATION: bounded JSON telemetry sampling.
        // Noisy worklist liveness events are useful for proving progress while a
        // frontier is unknown, but after the same kind repeats hundreds of times they
        // become storage pressure.  Sample only the noisy classes; terminal failures,
        // blockers, explicit guards and build/error receipts still emit in full.
        let private jsonKindCounts =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,int>()

        // MIGRATION: sampled progress tick stats.  These are approximate because they
        // deliberately reuse emitted/sampled diagnostics instead of adding hot-path scans.
        let private progressSpiralSites =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.WorkSiteId,int>()

        // MIGRATION: expose bounded kind counters to BigStack join policy.
        // These counters are diagnostic liveness evidence only; consumers must stay
        // fail-closed and may only choose a retry/drain path, never a semantic value.
        let snapshotKindCount (kind: string) =
            try
                let kindRef = CompilerIdentityKernel.ContentDigest.ofText "json-kind-count" kind
                match jsonKindCounts.TryGetValue kindRef with
                | true, v -> v
                | _ -> 0
            with _ -> 0

        // MIGRATION: keep console logging policy typed.  Earlier rounds kept adding
        // string predicates and booleans to the sampler; this made it too easy to
        // accidentally unsample a terminal receipt or let a new liveness family spam
        // stderr.  The recursive DU below separates the evidence class from the
        // cadence, like a tiny GADT-ish contract for diagnostics.
        type JsonEmissionCadence =
            | EmitAlways
            | EmitDenseThenPowerThenHeartbeat of heartbeat:int
            | EmitSparsePowerThenHeartbeat of heartbeat:int
            | EmitFirstThenHeartbeat of heartbeat:int

        type JsonEmissionClass =
            | CriticalEvidence
            | NoisyEvidence of kind:string * cadence:JsonEmissionCadence
            | CompositeEvidence of primary:JsonEmissionClass * secondary:JsonEmissionClass option

        type JsonEmissionDecision =
            | EmitLine
            | DropRepeatedLine of kind:string * repeat:int * cadence:JsonEmissionCadence

        let rec private jsonEmissionClassKind = function
            | CriticalEvidence -> "critical"
            | NoisyEvidence(kind, _) -> kind
            | CompositeEvidence(primary, _) -> jsonEmissionClassKind primary

        let private densePowerHeartbeat cadence repeat =
            match cadence with
            | EmitAlways -> true
            | EmitDenseThenPowerThenHeartbeat heartbeat ->
                repeat <= 3
                || repeat = 4 || repeat = 8 || repeat = 16 || repeat = 32 || repeat = 64 || repeat = 128
                || repeat = 256 || repeat = 512 || repeat = 1024
                || (heartbeat > 0 && repeat % heartbeat = 0)
            | EmitSparsePowerThenHeartbeat heartbeat ->
                repeat = 1 || repeat = 2 || repeat = 4 || repeat = 8 || repeat = 16 || repeat = 32
                || (heartbeat > 0 && repeat % heartbeat = 0)
            | EmitFirstThenHeartbeat heartbeat ->
                repeat = 1 || (heartbeat > 0 && repeat % heartbeat = 0)

        let rec private shouldEmitEmissionClass emissionClass =
            match emissionClass with
            | CriticalEvidence -> EmitLine
            | NoisyEvidence(kind, cadence) ->
                let kindRef = CompilerIdentityKernel.ContentDigest.ofText "json-kind-count" kind
                let c = jsonKindCounts.AddOrUpdate(kindRef, 1, (fun _ old -> old + 1))
                if densePowerHeartbeat cadence c then EmitLine else DropRepeatedLine(kind, c, cadence)
            | CompositeEvidence(primary, secondary) ->
                match shouldEmitEmissionClass primary with
                | EmitLine -> EmitLine
                | DropRepeatedLine _ as dropped ->
                    match secondary with
                    | Some CriticalEvidence -> EmitLine
                    | Some s -> shouldEmitEmissionClass s
                    | None -> dropped

        type TerminalFlowHotRowOrdinalKind =
            | TerminalFlowHotRowSemanticStaleRetarget
            | TerminalFlowHotRowParentReplayCycleBreak

        type TerminalFlowHotRowOrdinalState = private {
            semanticStaleRetarget : int
            parentReplayCycleBreak : int
        }

        let private terminalFlowHotRowOrdinalGate = obj()
        let mutable private terminalFlowHotRowOrdinalState = {
            semanticStaleRetarget = 0
            parentReplayCycleBreak = 0
        }

        let private nextTerminalFlowHotRowOrdinal kind =
            lock terminalFlowHotRowOrdinalGate (fun () ->
                let next, state =
                    match kind with
                    | TerminalFlowHotRowSemanticStaleRetarget ->
                        let next = terminalFlowHotRowOrdinalState.semanticStaleRetarget + 1
                        next, { terminalFlowHotRowOrdinalState with semanticStaleRetarget = next }
                    | TerminalFlowHotRowParentReplayCycleBreak ->
                        let next = terminalFlowHotRowOrdinalState.parentReplayCycleBreak + 1
                        next, { terminalFlowHotRowOrdinalState with parentReplayCycleBreak = next }
                terminalFlowHotRowOrdinalState <- state
                next)

        let private nextSemanticStaleRetargetHotRowOrdinal () =
            nextTerminalFlowHotRowOrdinal TerminalFlowHotRowSemanticStaleRetarget
        let private shouldEmitSemanticStaleRetargetHotRow ordinal =
            ordinal > 0 && (ordinal <= 4 || ordinal = 16 || ordinal = 64 || ordinal % 512 = 0)

        let private nextParentReplayCycleBreakTerminalHotRowOrdinal () =
            nextTerminalFlowHotRowOrdinal TerminalFlowHotRowParentReplayCycleBreak
        let private shouldEmitParentReplayCycleBreakTerminalHotRow ordinal =
            ordinal > 0 && (ordinal <= 4 || ordinal = 16 || ordinal = 64 || ordinal % 512 = 0)

        let private isPow2 (x: int) =
            x > 0 && ((x &&& (x - 1)) = 0)

        type ProgressJsonStringFieldId =
            | ProgressJsonSiteField

        let private progressJsonStringFieldName = function
            | ProgressJsonSiteField -> "site"

        // IndexOf, not Split: Split copied the whole rest of the row to read one field (~6% of a quiet
        // compile, which still classifies every row for the kind counters). Same result: the text up to the
        // next quote, or to the end of the row.
        let private jsonStringFieldByName (field: string) (s: string) =
            if isNull s then ""
            else
                let needle = "\"" + field + "\":\""
                let idx = s.IndexOf(needle, StringComparison.Ordinal)
                if idx < 0 then ""
                else
                    let start = idx + needle.Length
                    let stop = s.IndexOf('"', start)
                    if stop < 0 then s.Substring(start) else s.Substring(start, stop - start)

        let private jsonStringField (fieldId: ProgressJsonStringFieldId) (s: string) =
            jsonStringFieldByName (progressJsonStringFieldName fieldId) s

        type ProgressSiteSourceKind =
            | ProgressSiteSpiralTopDown
            | ProgressSiteSpiralBottomUp
            | ProgressSiteNonSpiral

        let private progressSiteSourceKind (site:string) =
            match System.IO.Path.GetExtension(site).ToLowerInvariant() with
            | ".spi" -> ProgressSiteSpiralTopDown
            | ".spir" -> ProgressSiteSpiralBottomUp
            | _ -> ProgressSiteNonSpiral

        let private noteProgressSiteFromJsonLine (line: string) =
            try
                let site = jsonStringField ProgressJsonSiteField line
                match progressSiteSourceKind site with
                | ProgressSiteSpiralTopDown
                | ProgressSiteSpiralBottomUp ->
                    let siteId = CompilerIdentityKernel.WorkSiteIdOps.create site
                    progressSpiralSites.AddOrUpdate(siteId, 1, (fun _ old -> old + 1)) |> ignore
                | ProgressSiteNonSpiral -> ()
            with _ -> ()

        let private sampledLegacyActivityStatsJsonFields () =
            try
                let semanticLikeRows =
                    snapshotKindCount "eval_worklist_payload"
                    + snapshotKindCount "eval_worklist_replay_commit"
                    + snapshotKindCount "eval_worklist_replay_reduce"
                    + snapshotKindCount "eval_worklist_replay_step"
                    + snapshotKindCount "eval_worklist_frame_parent_continuation"
                let structuralRows =
                    snapshotKindCount "eval_worklist_apply_spine_post_fuse_recursive_children_registered"
                    + snapshotKindCount "eval_worklist_if_branch_children_registered"
                    + snapshotKindCount "eval_worklist_type_apply_arg_tv_env_snapshot"
                    + snapshotKindCount "eval_worklist_type_fun_tv_child_env_snapshot"
                FastRuntimeFormat.format ",\"stats_schema\":\"legacy_activity_v2\",\"progress_authority\":false,\"legacy_activity_semantic_like_rows\":%d,\"legacy_activity_structural_rows\":%d,\"legacy_activity_spiral_file_sites\":%d" [| box semanticLikeRows; box structuralRows; box progressSpiralSites.Count |]
            with _ ->
                ",\"stats_schema\":\"legacy_activity_v2\",\"progress_authority\":false,\"legacy_activity_semantic_like_rows\":-1,\"legacy_activity_structural_rows\":-1,\"legacy_activity_spiral_file_sites\":-1"

        do
            Progress88.set_stats_provider sampledLegacyActivityStatsJsonFields

        let private isNoisyJsonKind (kind: string) =
            match kind with
            | "eval_worklist_payload"
