        let private truncateForDiag (limit: int) (s: string) =
            if System.Object.ReferenceEquals(s,null) then ""
            elif s.Length <= limit then s
            else s.Substring(0, limit) + sprintf "…[+%d chars]" (s.Length - limit)

        let private textOrDefault (fallback: string) (text: string) =
            if System.String.IsNullOrWhiteSpace text then fallback else text

        // MIGRATION history intentionally retained above. MIGRATION removes all
        // runtime environment reads: these defaults are the compiler policy.
        type FinishFastPolicy =
            { terminalClosureRepeatCap:int
              bypassRepeatAfterClearCap:int
              buildRetrySoftAbortCap:int
              buildRetryMaxAttemptsCap:int
              sourceSnippetPreviewCap:int
              compactPayloadPreviewCap:int
              parentContinuationPhase2RepeatCap:int }

        let finishFastPolicy =
            { terminalClosureRepeatCap = 2
              bypassRepeatAfterClearCap = 4
              buildRetrySoftAbortCap = 4
              buildRetryMaxAttemptsCap = 4
              sourceSnippetPreviewCap = 240
              compactPayloadPreviewCap = 320
              parentContinuationPhase2RepeatCap = 4 }

        let terminalClosureRepeatFastFinishCap = finishFastPolicy.terminalClosureRepeatCap
        let bypassRepeatAfterClearFastFinishCap = finishFastPolicy.bypassRepeatAfterClearCap
        let buildRetrySoftAbortFinishFastCap = finishFastPolicy.buildRetrySoftAbortCap
        let buildRetryMaxAttemptsFastFinishCap = finishFastPolicy.buildRetryMaxAttemptsCap
        let sourceSnippetPreviewCap = finishFastPolicy.sourceSnippetPreviewCap
        let compactPayloadPreviewCap = finishFastPolicy.compactPayloadPreviewCap
        let parentContinuationPhase2RepeatCap = finishFastPolicy.parentContinuationPhase2RepeatCap

        let finishFastPolicyText () =
            FastRuntimeFormat.format "FinishFastPolicy(terminal_repeat_cap=%d|bypass_repeat_after_clear_cap=%d|build_retry_soft_abort_cap=%d|build_retry_max_attempts_cap=%d|source_snippet_preview_chars=%d|compact_payload_preview_chars=%d|parent_continuation_phase2_repeat_cap=%d|authority=native_hopac_scheduler_exit_gate)" [| box finishFastPolicy.terminalClosureRepeatCap; box finishFastPolicy.bypassRepeatAfterClearCap; box finishFastPolicy.buildRetrySoftAbortCap; box finishFastPolicy.buildRetryMaxAttemptsCap; box finishFastPolicy.sourceSnippetPreviewCap; box finishFastPolicy.compactPayloadPreviewCap; box finishFastPolicy.parentContinuationPhase2RepeatCap |]

        type SourceTextLocationReceipt =
            | SourceTextMissingLocation
            | SourceTextUnparsed of original:string
            | SourceTextUnavailable of kindPrefix:string * normalized:string * path:string * line:int * col:int
            | SourceTextOutOfRange of kindPrefix:string * normalized:string * path:string * line:int * col:int * lineCount:int
            | SourceTextOk of kindPrefix:string * normalized:string * path:string * line:int * col:int * text:string
            | SourceTextError of message:string

        let private sourceTextReceiptText = function
            | SourceTextMissingLocation -> "source_text_status=missing_location"
            | SourceTextUnparsed original -> "source_text_status=unparsed|location=" + truncateForDiag 160 original
            | SourceTextUnavailable(kindPrefix, normalized, path, line, col) ->
                FastRuntimeFormat.format "source_text_status=unavailable|source_kind_prefix=%s|source_location_normalized=%s|path=%s|line=%d|col=%d" [| box (truncateForDiag 80 kindPrefix); box normalized; box path; box line; box col |]
            | SourceTextOutOfRange(kindPrefix, normalized, path, line, col, lineCount) ->
                FastRuntimeFormat.format "source_text_status=out_of_range|source_kind_prefix=%s|source_location_normalized=%s|path=%s|line=%d|col=%d|line_count=%d" [| box (truncateForDiag 80 kindPrefix); box normalized; box path; box line; box col; box lineCount |]
            | SourceTextOk(kindPrefix, normalized, path, line, col, text) ->
                FastRuntimeFormat.format "source_text_status=ok|source_kind_prefix=%s|source_location_normalized=%s|path=%s|line=%d|col=%d|text=%s" [| box (truncateForDiag 80 kindPrefix); box normalized; box path; box line; box col; box (truncateForDiag sourceSnippetPreviewCap text) |]
            | SourceTextError message -> "source_text_status=error|ex=" + truncateForDiag 120 message

        type SourcePathSchemeId =
            | SourcePathFileUriAbsolute
            | SourcePathFileUriAuthority
            | SourcePathPlain

        let private sourcePathSchemeFor (value:string) =
            let safe = if System.Object.ReferenceEquals(value, null) then "" else value
            let hasHead (head:string) =
                safe.Length >= head.Length
                && System.String.Equals(safe.Substring(0, head.Length), head, System.StringComparison.OrdinalIgnoreCase)
            if hasHead "file:///" then SourcePathFileUriAbsolute
            elif hasHead "file://" then SourcePathFileUriAuthority
            else SourcePathPlain

        type SourcePathRootId =
            | SourcePathWindowsDrive
            | SourcePathUnixRoot
            | SourcePathRelative

        let private sourcePathRootFor (value:string) =
            let safe = if System.Object.ReferenceEquals(value, null) then "" else value
            if System.Text.RegularExpressions.Regex.IsMatch(safe, "^[A-Za-z]:/") then SourcePathWindowsDrive
            elif safe.Length > 0 && safe.[0] = '/' then SourcePathUnixRoot
            else SourcePathRelative

        let private normalizeSourcePathCandidate (path: string) =
            let trimmed = (textOrDefault "" path).Trim().Trim([|'('; ')'; '['; ']'; '{'; '}'; '\''; '"'; '<'; '>'|])
            match sourcePathSchemeFor trimmed with
            | SourcePathFileUriAbsolute ->
                let rest = trimmed.Substring("file:///".Length)
                if rest.Length >= 2 && rest.[1] = ':' then rest else "/" + rest.TrimStart('/')
            | SourcePathFileUriAuthority ->
                trimmed.Substring("file://".Length)
            | SourcePathPlain ->
                trimmed

        let private sourceTextLookupRoots () =
            [| System.IO.Directory.GetCurrentDirectory()
               System.AppContext.BaseDirectory |]
            |> Array.map (fun x -> (textOrDefault "" x).Trim())
            |> Array.filter (fun x -> not (System.String.IsNullOrWhiteSpace x))
            |> Array.distinct

        let private sourcePathRelativeTail (path: string) =
            let p = (textOrDefault "" path).Replace('\\','/')
            match sourcePathRootFor p with
            | SourcePathWindowsDrive -> p.Substring(3).TrimStart('/')
            | SourcePathUnixRoot -> p.TrimStart('/')
            | SourcePathRelative -> p

        let private resolveSourceTextPath (path: string) =
            let normalized = normalizeSourcePathCandidate path
            if System.IO.File.Exists normalized then normalized
            else
                let tail = sourcePathRelativeTail normalized
                let candidateForRoot root =
                    let tailForPlatform = tail.Replace('/', System.IO.Path.DirectorySeparatorChar)
                    System.IO.Path.Combine(root, tailForPlatform)
                sourceTextLookupRoots ()
                |> Array.map candidateForRoot
                |> Array.tryFind System.IO.File.Exists
                |> Option.defaultValue normalized

        let private tryExtractSourcePathAndPrefix (beforeSpan: string) =
            let before = (textOrDefault "" beforeSpan).Trim().TrimEnd([|'|'; ','; ';'; ')'; ']'; '}'; '\''; '"'; ' '|])
            let choose (m:System.Text.RegularExpressions.Match) =
                if m.Success then
                    let path = normalizeSourcePathCandidate m.Groups.[1].Value
                    let prefixRaw = before.Substring(0, m.Index).Trim()
                    let prefix = prefixRaw.TrimEnd([|':' ; '@'; '|'; '='; ' '; '('; '['; '{'; '\''; '"'|])
                    Some(prefix, path)
                else None
            let win = System.Text.RegularExpressions.Regex.Match(before, @"([A-Za-z]:[/\\][^|,;\)\]\}\>""\']*)$", System.Text.RegularExpressions.RegexOptions.IgnoreCase)
            match choose win with
            | Some _ as x -> x
            | None ->
                let uriWin = System.Text.RegularExpressions.Regex.Match(before, @"(file:///[A-Za-z]:[/\\][^|,;\)\]\}\>""\']*)$", System.Text.RegularExpressions.RegexOptions.IgnoreCase)
                match choose uriWin with
                | Some _ as x -> x
                | None ->
                    let posix = System.Text.RegularExpressions.Regex.Match(before, @"(/[^|,;\)\]\}\>""\']*)$", System.Text.RegularExpressions.RegexOptions.IgnoreCase)
                    choose posix

        let private tryParseSourceLocation (location: string) =
            if System.String.IsNullOrWhiteSpace location then SourceTextMissingLocation
            else
                let raw = location.Trim().Trim([|'('; ')'; '['; ']'; '{'; '}'; '\''; '"'|])
                let spans = System.Text.RegularExpressions.Regex.Matches(raw, @":(\d+):(\d+)-(\d+):(\d+)")
                if spans.Count = 0 then SourceTextUnparsed location
                else
                    let span = spans.[spans.Count - 1]
                    let before = raw.Substring(0, span.Index)
                    match tryExtractSourcePathAndPrefix before with
                    | None -> SourceTextUnparsed location
                    | Some(kindPrefix, path) ->
                        let lineNo = int span.Groups.[1].Value
                        let colNo = int span.Groups.[2].Value
                        let endLineNo = span.Groups.[3].Value
                        let endColNo = span.Groups.[4].Value
                        let resolvedPath = resolveSourceTextPath path
                        let normalized = resolvedPath + FastRuntimeFormat.format ":%d:%d-%s:%s" [| box lineNo; box colNo; box endLineNo; box endColNo |]
                        if not (System.IO.File.Exists resolvedPath) then SourceTextUnavailable(kindPrefix, normalized, resolvedPath, lineNo, colNo)
                        else
                            let lines = System.IO.File.ReadAllLines resolvedPath
                            if lineNo <= 0 || lineNo > lines.Length then SourceTextOutOfRange(kindPrefix, normalized, resolvedPath, lineNo, colNo, lines.Length)
                            else SourceTextOk(kindPrefix, normalized, resolvedPath, lineNo, colNo, lines.[lineNo - 1].Replace("\t", "    "))

        // MIGRATION: generic source text receipt. It accepts arbitrary file
        // paths with trailing line/column spans, optional kind prefixes (ty:,
        // term@, payload=...), and file:// URIs. It does not special-case any
        // source file or line; if the file is unavailable it emits a stable
        // unavailable receipt instead of fabricating source.
        let sourceTextForLocation (location: string) =
            try sourceTextReceiptText (tryParseSourceLocation location)
            with ex -> sourceTextReceiptText (SourceTextError ex.Message)

        // MIGRATION MIGRATION : hot rows must preserve the typed authority
        // surface without repeating the full nested terminal/root payload in every
        // heartbeat. The compact row keeps replayable scheduler/root/wait/live
        // fields and records a deterministic detail ref/hash for offline sidecar
        // reconstruction. Full-fidelity payloads remain in first-source receipts;
        // periodic hot rows become pointer ledgers instead of scroll bombs.
        type JsonHotRowCompactionReasonId =
            | JsonHotRowRichTickPeriodic
            | JsonHotRowMinimalTickPeriodic
            | JsonHotRowStallProbe
            | JsonHotRowUnderutilizedAbort
            | JsonHotRowUnderutilizedHoldoff
            | JsonHotRowNoWorkAbort
            | JsonHotRowTerminalLedger
            | JsonHotRowRootSemanticExit
            | JsonHotRowRootConsensusRange
            | JsonHotRowCanonicalTerminalRange
            | JsonHotRowTerminalBoundaryRange
            | JsonHotRowPostRootNoiseRange
            | JsonHotRowOwnerDebtRange
            | JsonHotRowOrphanDrainRange
            | JsonHotRowGlobalReducerRange
            | JsonHotRowGlobalCommandRange
            | JsonHotRowSchedulerDispatchRange
            | JsonHotRowSchedulerExitRange
            | JsonHotRowLargeTypedPayload

        let private jsonHotRowCompactionReasonText = function
            | JsonHotRowRichTickPeriodic -> "rich_tick_periodic"
            | JsonHotRowMinimalTickPeriodic -> "minimal_tick_periodic"
            | JsonHotRowStallProbe -> "stall_probe_hot"
            | JsonHotRowUnderutilizedAbort -> "underutilized_abort_hot"
            | JsonHotRowUnderutilizedHoldoff -> "underutilized_holdoff_hot"
            | JsonHotRowNoWorkAbort -> "no_work_abort_hot"
            | JsonHotRowTerminalLedger -> "terminal_ledger_hot"
            | JsonHotRowRootSemanticExit -> "root_semantic_exit_hot"
            | JsonHotRowRootConsensusRange -> "root_consensus_receipt_projection_range"
            | JsonHotRowCanonicalTerminalRange -> "canonical_terminal_projection_receipt_range"
            | JsonHotRowTerminalBoundaryRange -> "terminal_boundary_receipt_range"
            | JsonHotRowPostRootNoiseRange -> "post_root_noise_receipt_projection"
            | JsonHotRowOwnerDebtRange -> "owner_debt_receipt_projection"
            | JsonHotRowOrphanDrainRange -> "orphan_drain_receipt_projection"
            | JsonHotRowGlobalReducerRange -> "global_reducer_projection_range"
            | JsonHotRowGlobalCommandRange -> "global_command_projection_range"
            | JsonHotRowSchedulerDispatchRange -> "scheduler_dispatch_receipt_projection"
            | JsonHotRowSchedulerExitRange -> "scheduler_exit_receipt_projection"
            | JsonHotRowLargeTypedPayload -> "large_typed_payload_hot_row"

        type JsonHotRowCompactionDecision =
            | JsonHotRowKeepFull
            | JsonHotRowCompact of JsonHotRowCompactionReasonId

        let private jsonRawFieldForCompaction (field: string) (line: string) =
            try
                let quoted = jsonStringFieldByName field line
                if quoted <> "" then quoted
                else
                    let needle = "\"" + field + "\":"
                    let parts = line.Split([|needle|], 2, StringSplitOptions.None)
                    if parts.Length <> 2 then ""
                    else
                        let rest = parts.[1].TrimStart()
                        if String.IsNullOrEmpty rest then ""
                        elif rest.[0] = '"' then
                            let mutable endi = 1
                            let mutable finished = false
                            while endi < rest.Length && not finished do
                                if rest.[endi] = '"' && rest.[endi - 1] <> '\\' then finished <- true
                                else endi <- endi + 1
                            if endi < rest.Length then rest.Substring(1, endi - 1) else ""
                        else
                            let mutable endi = 0
                            while endi < rest.Length && rest.[endi] <> ',' && rest.[endi] <> '}' do
                                endi <- endi + 1
                            if endi > 0 then rest.Substring(0, endi).Trim().Trim([|'"'|]) else ""
            with _ -> ""

        let private jsonCompactionHash (line: string) =
            try
                let h = uint32 (line.GetHashCode())
                h.ToString("x8", System.Globalization.CultureInfo.InvariantCulture)
            with _ -> "00000000"

        // MIGRATION round : JSONL hot rows are no longer allowed to
        // repeat large proof strings after the first source receipt.  The
        // compactor keeps reducer/writer/receipt refs, then turns repeated
        // rows into receipt-projection range rows.  Authority stays in the
        // typed receipts; this layer is projection-only.
        let private hotJsonCompactionDecision (kind: string) (line: string) =
            if System.String.IsNullOrWhiteSpace kind then JsonHotRowKeepFull
            elif kind = "compile_progress_prediction_tick" then JsonHotRowCompact JsonHotRowRichTickPeriodic
            elif kind = "progress_tick" then JsonHotRowCompact JsonHotRowMinimalTickPeriodic
            elif kind = "compile_progress_stall_probe" then JsonHotRowCompact JsonHotRowStallProbe
            elif kind = "compile_progress_underutilized_abort" then JsonHotRowCompact JsonHotRowUnderutilizedAbort
            elif kind = "compile_progress_underutilized_live_replay_holdoff" then JsonHotRowCompact JsonHotRowUnderutilizedHoldoff
            elif kind = "compile_progress_no_work_abort" then JsonHotRowCompact JsonHotRowNoWorkAbort
            elif kind = "native_closure_failure_ledger_terminal" then JsonHotRowCompact JsonHotRowTerminalLedger
            elif kind = "root_promise_failed_semantic_exit" then JsonHotRowCompact JsonHotRowRootSemanticExit
            elif kind = "root_authority_consensus" then JsonHotRowCompact JsonHotRowRootConsensusRange
            elif kind = "canonical_root_terminal_projection" then JsonHotRowCompact JsonHotRowCanonicalTerminalRange
            elif kind = "terminal_flow_boundary_receipt_materialized" || kind = "eval_worklist_terminal_flow_boundary_receipt_materialized" then JsonHotRowCompact JsonHotRowTerminalBoundaryRange
            elif kind = "bigstack_no_root_budget_terminal_bypass" then JsonHotRowCompact JsonHotRowPostRootNoiseRange
            elif kind = "owner_deadlock_blocked_by_live_owner_debt_tie_breaker" then JsonHotRowCompact JsonHotRowOwnerDebtRange
            elif kind = "forced_orphan_drain_worker_requested" then JsonHotRowCompact JsonHotRowOrphanDrainRange
            elif kind = "terminal_flow_global_server" then JsonHotRowCompact JsonHotRowGlobalReducerRange
            elif kind = "terminal_flow_global_server_command" then JsonHotRowCompact JsonHotRowGlobalCommandRange
            elif kind = "terminal_scheduler_dispatch" then JsonHotRowCompact JsonHotRowSchedulerDispatchRange
            elif kind = "terminal_scheduler_exit" then JsonHotRowCompact JsonHotRowSchedulerExitRange
            elif line.Length > 8192 && (["typed_terminal_payload_du"; "native_job_graph"; "semantic_stale_retarget_bridge_exit_gate_du"] |> List.exists (fun field -> not (String.IsNullOrWhiteSpace (jsonScalarField field line)))) then JsonHotRowCompact JsonHotRowLargeTypedPayload
            else JsonHotRowKeepFull

        let private hotJsonDecisionHashes =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,CompilerIdentityKernel.ContentDigest>()

        let private hotJsonProjectionRangeCounters =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,int64>()

        let private hotJsonDecisionChangeKey (line:string) =
            let kind = jsonStringFieldByName "kind" line
            let isDecisionHot =
                kind = "compile_progress_prediction_tick"
                || kind = "progress_tick"
                || kind = "compile_progress_stall_probe"
                || kind = "eval_worklist_native_cutover_backup_tick_suppressed"
                || kind = "terminal_closure_repeat_exit_deferred_executable_graph"
                || kind = "root_promise_failed_semantic_exit"
                || kind = "root_authority_consensus"
                || kind = "canonical_root_terminal_projection"
                || kind = "terminal_flow_boundary_receipt_materialized"
                || kind = "eval_worklist_terminal_flow_boundary_receipt_materialized"
                || kind = "bigstack_no_root_budget_terminal_bypass"
                || kind = "owner_deadlock_blocked_by_live_owner_debt_tie_breaker"
                || kind = "forced_orphan_drain_worker_requested"
                || kind = "terminal_flow_global_server"
                || kind = "terminal_flow_global_server_command"
                || kind = "terminal_scheduler_dispatch"
                || kind = "terminal_scheduler_exit"
            if not isDecisionHot then None
            else
                let fields =
                    [|
                        "root_promise_status_du"
                        "live_graph_phase_du"
                        "owner_ledger_snapshot_du"
                        "open_owners_count"
                        "native_root_complete_wait_graph_du"
                        "native_root_complete_runtime_receipt_du"
                        "native_promise_terminal_commit_gate_du"
                        "parent_continuation_ivar_fill_result_du"
                        "queue_only_recovery_decision_du"
                        "work_dag_authority_du"
                        "scheduler_causal_authority_du"
                        "breakthrough_terminal_verdict_du"
                        "dominant_active_node_id"
                        "blocker"
                        "next"
                        "sampled_work_delta"
                        "semantic_activity_receipt_delta"
                        "root_complete_delta"
                        "native_scheduler_sleep_action"
                        "semantic_receipt_bridge_ready"
                        "wait_graph_edges"
                        "root_receipt_ref"
                        "terminal_outcome_ref"
                        "terminal_receipt_ref"
                        "terminal_ref"
                        "fill_ref"
                        "dispatch_ref"
                        "dispatch_request_id"
                        "dispatch_idempotency_key"
                        "actor_phase"
                        "actor_phase_before_du"
                        "actor_phase_after_du"
                        "actor_arm_result_du"
                        "why_not_dispatch_du"
                        "writer_ref"
                        "artifact_ref"
                        "exit_ref"
                        "stage_capability_ref"
                        "kernel_projection_ref"
                        "receipt_vector_hash"
                        "owner_closure_certificate"
                        "owner_close_key"
                        "owner_waker_obligation"
                        "terminal_outcome_ivar_fill_decision"
                        "waker_registration_status"
                        "procedural_residual_drain_pass_count"
                        "material_delta_on_procedural_pass"
                    |]
                let canonical =
                    fields
                    |> Array.map (fun field -> field + "=" + jsonRawFieldForCompaction field line)
                    |> String.concat "|"
                let decisionHash = jsonCompactionHash canonical
                Some(kind, decisionHash)

        let private hotJsonDecisionChanged (line:string) =
            match hotJsonDecisionChangeKey line with
            | None -> true
            | Some(kind, decisionHash) ->
                let kindRef = CompilerIdentityKernel.ContentDigest.ofText "hot-json-kind" kind
                let decisionRef = CompilerIdentityKernel.ContentDigest.ofText "hot-json-decision" decisionHash
                let mutable previous = Unchecked.defaultof<CompilerIdentityKernel.ContentDigest>
                let hadPrevious = hotJsonDecisionHashes.TryGetValue(kindRef, &previous)
                let changed = (not hadPrevious) || previous <> decisionRef
                if changed then hotJsonDecisionHashes.[kindRef] <- decisionRef
                changed

        let private compactHotJsonLineIfNeeded (line: string) =
            try
                let kind = jsonStringFieldByName "kind" line
                match hotJsonCompactionDecision kind line with
                | JsonHotRowKeepFull -> None
                | JsonHotRowCompact reason ->
                    let reasonText = jsonHotRowCompactionReasonText reason
                    let keepFields =
                        [|
                            "event"; "source"; "elapsed_s"; "progress_pct";
                            "sampled_work_delta"; "semantic_receipt_delta"; "replay_progress_delta"; "root_complete_delta"; "terminal_signal_delta";
                            "no_work_stall_s"; "no_work_pokes"; "overview_state"; "parallelism_state";
                            "no_work_gate_decision_du"; "underutilized_decision_du"; "native_scheduler_authority_du"; "native_scheduler_raw_authority_du"; "native_scheduler_sleep_action";
                            "scheduler_fatal_authority_gate_du"; "no_work_hard_abort_gate_du"; "hard_abort_recent_progress_du";
                            "live_replay_evidence_du"; "native_wait_for_graph_verdict_du"; "native_wait_for_graph_can_collapse_root"; "live_replay_gate_queue_source_du";
                            "semantic_stale_retarget_bridge_exit_gate_du"; "minimal_to_rich_evidence_receipt_du"; "minimal_native_failure_evidence_class_du";
                            "root_promise_status_du"; "root_collapse_action_du"; "root_collapse_action_taken"; "root_collapse_exit_code";
                            "terminal_action_executor_du"; "terminal_action_liveness_gate_du"; "fatal_semantic_exit_required"; "fatal_semantic_exit_suppressed_by";
                            "kind_indexed_terminal_payload_du"; "terminal_payload_class_du"; "terminal_payload_bridge_action_du";
                            "terminal_closure_repeat_fast_finish_du"; "scheduler_escalation_reason_du"; "finish_fast_policy_du"; "effective_no_work_gate_du";
                            "semantic_fixed_point_lease_du"; "active_workers_trace_du"; "ivar_dependencies_du";
                            "semantic_failure_id"; "source_span_du"; "source_span_enrichment_du"; "source_text"; "source_text_du"; "source_location_normalized"; "source_file"; "source_line"; "source_column";
                            "root_receipt_ref"; "canonical_receipt_ref"; "terminal_outcome_ref"; "terminal_receipt_ref"; "terminal_ref"; "fill_ref";
                            "dispatch_ref"; "dispatch_request_id"; "dispatch_idempotency_key"; "dispatch_accepted"; "dispatch_already_exists"; "dispatch_rejected_reason_du";
                            "actor_phase"; "actor_phase_before_du"; "actor_phase_after_du"; "actor_arm_attempted"; "actor_arm_result_du"; "why_not_dispatch_du";
                            "writer_ref"; "artifact_ref"; "exit_ref"; "stage_capability_ref"; "kernel_projection_ref"; "kernel_capture_complete"; "receipt_vector_hash";
                            "owner_closure_certificate"; "owner_close_key"; "owner_waker_obligation"; "owner_transaction";
                            "terminal_outcome_ivar_fill_decision"; "terminal_outcome_installation_du"; "terminal_outcome_installed"; "waker_registration_status"; "procedural_residual_drain_pass_count"; "material_delta_on_procedural_pass";
                            "run_end_emitted"; "capture_complete"; "final_hud_emitted"; "policy"; "next"
                        |]
                    let kept =
                        keepFields
                        |> Array.choose (fun field ->
                            let value = jsonRawFieldForCompaction field line
                            if System.String.IsNullOrWhiteSpace value then None
                            else
                                let compactLimit =
                                    match field with
                                    | "minimal_to_rich_evidence_receipt_du" | "semantic_stale_retarget_bridge_exit_gate_du" | "kind_indexed_terminal_payload_du" -> compactPayloadPreviewCap
                                    | "native_scheduler_authority_du" | "native_scheduler_raw_authority_du" | "scheduler_fatal_authority_gate_du" | "no_work_hard_abort_gate_du" | "live_replay_evidence_du" | "source_text" | "source_text_du" -> max compactPayloadPreviewCap sourceSnippetPreviewCap
                                    | _ -> 240
                                Some(sprintf ",\"%s\":%s" field (esc (truncateForDiag compactLimit value))))
                        |> String.concat ""
                    let ts = string (System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())
                    let pid = string (System.Environment.ProcessId)
                    let tid = string (System.Threading.Thread.CurrentThread.ManagedThreadId)
                    let decisionHash =
                        match hotJsonDecisionChangeKey line with
                        | Some(_, h) -> h
                        | None -> jsonCompactionHash line
                    let projectionRangeIdentity =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "hot-json-projection-range"
                            ((if System.String.IsNullOrWhiteSpace kind then "diag_compacted_hot_row" else kind) + "|" + decisionHash)
                    let projectionRangeCount =
                        hotJsonProjectionRangeCounters.AddOrUpdate(projectionRangeIdentity, 1L, fun _ previous -> previous + 1L)
                    let compact =
                        FastRuntimeFormat.format "{\"v\":1,\"ts_ms\":%s,\"pid\":%s,\"tid\":%s,\"run_id\":%s,\"kind\":%s,\"jsonl_compaction_du\":%s,\"receipt_projection_ref\":%s,\"hot_row_range_count\":%d,\"projection_authority\":\"receipt_projection_only\",\"full_proof_policy\":\"first_source_receipt_then_ref_range\"%s}" [| box ts; box pid; box tid; box (esc run_id); box (esc (if System.String.IsNullOrWhiteSpace kind then "diag_compacted_hot_row" else kind)); box (esc ("HotRowCompacted|reason=" + reasonText + "|policy=receipt_refs_only_no_full_proof_strings|source_authority=typed_receipt")); box (esc decisionHash); box projectionRangeCount; box kept |]
                    Some compact
            with _ -> None

        type LogCompletenessPolicy =
            | FullFidelityJsonl
            | TruncatedPreview of int

        let private activeLogCompletenessPolicy = FullFidelityJsonl

        let private logCompletenessPolicyText policy =
            match policy with
            | FullFidelityJsonl -> "full_fidelity_jsonl"
            | TruncatedPreview n -> sprintf "truncated_preview_%d" n

        let private compactJsonLineIfLarge (line: string) =
            match compactHotJsonLineIfNeeded line with
            | Some compact -> compact
            | None ->
                match activeLogCompletenessPolicy with
                | FullFidelityJsonl ->
                    // MIGRATION: full fidelity still holds for non-hot rows. Hot
                    // metronome/root/terminal rows are now compact pointer ledgers
                    // because their detail payloads repeat typed receipts already
                    // emitted by source receipts.
                    line
                | TruncatedPreview limit ->
                    if System.Object.ReferenceEquals(line,null) || line.Length <= limit then line
                    else
                        let keep (field: string) =
                            let value = jsonStringFieldByName field line
                            if value = "" then "" else sprintf ",\"%s\":%s" field (esc (truncateForDiag 384 value))
                        let kind = jsonStringFieldByName "kind" line
                        let ts = string (System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())
                        let pid = string (System.Environment.ProcessId)
                        let tid = string (System.Threading.Thread.CurrentThread.ManagedThreadId)
                        let compactKind = if kind = "" then "diag_compacted" else kind
                        FastRuntimeFormat.format "{\"v\":1,\"ts_ms\":%s,\"pid\":%s,\"tid\":%s,\"run_id\":%s,\"kind\":%s%s%s%s%s%s%s,\"original_bytes\":%d,\"compact_policy\":\"truncated_preview_%d\",\"excerpt\":%s}" [| box ts; box pid; box tid; box (esc run_id); box (esc compactKind); box (keep "event"); box (keep "status"); box (keep "outcome"); box (keep "reason"); box (keep "site"); box (keep "next"); box line.Length; box limit; box (esc (truncateForDiag 512 line)) |]

        let private processResourceGate = obj()
        let mutable private processResourceLastWallMs = 0L
        let mutable private processResourceLastCpuMs = 0.0

        let private computeProcessMemoryJsonFields () =
            try
                let nowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                let p = System.Diagnostics.Process.GetCurrentProcess()
                let ws = p.WorkingSet64
                let privateBytes = p.PrivateMemorySize64
                let virtualBytes = p.VirtualMemorySize64
                let managedBytes = System.GC.GetTotalMemory(false)
                let cpuMs = p.TotalProcessorTime.TotalMilliseconds
                let threadCount = p.Threads.Count
                let logicalCores = max 1 System.Environment.ProcessorCount
                let cpuDeltaMs, wallDeltaMs, cpuProcessPct, cpuMachinePct =
                    lock processResourceGate (fun () ->
                        if processResourceLastWallMs = 0L then
                            processResourceLastWallMs <- nowMs
                            processResourceLastCpuMs <- cpuMs
                            0.0, 0L, 0.0, 0.0
                        else
                            let wallDelta = max 1L (nowMs - processResourceLastWallMs)
                            let cpuDelta = max 0.0 (cpuMs - processResourceLastCpuMs)
                            processResourceLastWallMs <- nowMs
                            processResourceLastCpuMs <- cpuMs
                            let pct = cpuDelta / float wallDelta * 100.0
                            cpuDelta, wallDelta, pct, pct / float logicalCores)
                FastRuntimeFormat.format ",\"mem_ws_bytes\":%d,\"mem_private_bytes\":%d,\"mem_virtual_bytes\":%d,\"mem_managed_bytes\":%d,\"proc_cpu_total_ms\":%d,\"proc_cpu_delta_ms\":%.4f,\"proc_cpu_wall_delta_ms\":%d,\"proc_cpu_pct\":%.4f,\"proc_cpu_machine_pct\":%.4f,\"proc_thread_count\":%d,\"cpu_logical_cores\":%d" [| box ws; box privateBytes; box virtualBytes; box managedBytes; box (int64 cpuMs); box cpuDeltaMs; box wallDeltaMs; box cpuProcessPct; box cpuMachinePct; box threadCount; box logicalCores |]
            with _ ->
                ",\"mem_ws_bytes\":-1,\"mem_private_bytes\":-1,\"mem_virtual_bytes\":-1,\"mem_managed_bytes\":-1,\"proc_cpu_total_ms\":-1,\"proc_cpu_delta_ms\":-1,\"proc_cpu_wall_delta_ms\":-1,\"proc_cpu_pct\":-1,\"proc_cpu_machine_pct\":-1,\"proc_thread_count\":-1,\"cpu_logical_cores\":-1"

        // Every emitted JSON row is enriched with these fields, and reading them through
        // System.Diagnostics.Process enumerates every process on the machine (NtProcessInfoHelper on Windows):
        // stack samples of a slow build spent most of partial evaluation there. The snapshot is diagnostic,
        // so reuse it for up to 250 ms.
        let private processMemoryJsonFieldsCacheGate = obj()
        let mutable private processMemoryJsonFieldsCache = ""
        let mutable private processMemoryJsonFieldsCacheMs = 0L
        let private processMemoryJsonFields () =
            let nowMs = System.Environment.TickCount64
            let cached =
                lock processMemoryJsonFieldsCacheGate (fun () ->
                    if processMemoryJsonFieldsCache <> "" && nowMs - processMemoryJsonFieldsCacheMs < 250L then Some processMemoryJsonFieldsCache
                    else None)
            match cached with
            | Some fields -> fields
            | None ->
                let fields = computeProcessMemoryJsonFields ()
                lock processMemoryJsonFieldsCacheGate (fun () ->
                    processMemoryJsonFieldsCache <- fields
                    processMemoryJsonFieldsCacheMs <- nowMs)
                fields

        let private processResourceSnapshotJsonFields (cpuDeltaMs: float) (wallDeltaMs: int64) (cpuProcessPct: float) (cpuMachinePct: float) =
            try
                let p = System.Diagnostics.Process.GetCurrentProcess()
                let ws = p.WorkingSet64
                let privateBytes = p.PrivateMemorySize64
                let virtualBytes = p.VirtualMemorySize64
                let managedBytes = System.GC.GetTotalMemory(false)
                let cpuMs = p.TotalProcessorTime.TotalMilliseconds
                let threadCount = p.Threads.Count
                let logicalCores = max 1 System.Environment.ProcessorCount
                FastRuntimeFormat.format ",\"mem_ws_bytes\":%d,\"mem_private_bytes\":%d,\"mem_virtual_bytes\":%d,\"mem_managed_bytes\":%d,\"proc_cpu_total_ms\":%d,\"proc_cpu_delta_ms\":%.4f,\"proc_cpu_wall_delta_ms\":%d,\"proc_cpu_pct\":%.4f,\"proc_cpu_machine_pct\":%.4f,\"proc_thread_count\":%d,\"cpu_logical_cores\":%d" [| box ws; box privateBytes; box virtualBytes; box managedBytes; box (int64 cpuMs); box cpuDeltaMs; box wallDeltaMs; box cpuProcessPct; box cpuMachinePct; box threadCount; box logicalCores |]
            with _ ->
                ",\"mem_ws_bytes\":-1,\"mem_private_bytes\":-1,\"mem_virtual_bytes\":-1,\"mem_managed_bytes\":-1,\"proc_cpu_total_ms\":-1,\"proc_cpu_delta_ms\":-1,\"proc_cpu_wall_delta_ms\":-1,\"proc_cpu_pct\":-1,\"proc_cpu_machine_pct\":-1,\"proc_thread_count\":-1,\"cpu_logical_cores\":-1"

        let private enrichJsonLineWithProcessMemory (line: string) =
            try
                if System.Object.ReferenceEquals(line,null) then line
                elif jsonHasField "mem_ws_bytes" line then line
                elif line.EndsWith("}", StringComparison.Ordinal) then
                    line.Substring(0, line.Length - 1) + processMemoryJsonFields() + "}"
                else line
            with _ -> line

        // The Progress88 heartbeat is not guaranteed to start on every
        // BuildFile path, so DiagJson owns a low-priority background heartbeat and
        // also keeps the emit-side opportunistic poke.  Both converge through the
        // same throttle and write directly to stderr, so the tick survives quiet
        // diagnostic windows without recursing through DiagJson.emit.
        let private progressPredictionTickGate = obj()
        // MIGRATION: the HUD's authority must not wait a full second or a rich
        // snapshot.  The rich snapshot remains best-effort; this cadence drives
        // the direct line-atomic minimal tick and terminal panel repaint.
        type ProgressHudCadenceId =
            | ProgressHudCadenceSubsecond250ms
            | ProgressHudCadenceOneSecondFallback

        let private progressHudCadenceMs = function
            | ProgressHudCadenceSubsecond250ms -> 250L
            | ProgressHudCadenceOneSecondFallback -> 1000L

        let private progressHudCadenceText = function
            | ProgressHudCadenceSubsecond250ms -> "observer_only_native_closure_receipt_pump"
            | ProgressHudCadenceOneSecondFallback -> "1s_line_atomic_metronome"

        let private progressPredictionMinimalCadenceId = ProgressHudCadenceSubsecond250ms
        let private progressPredictionMinimalCadenceMs = progressHudCadenceMs progressPredictionMinimalCadenceId

        // MIGRATION: refresh the interactive HUD every 250ms, but do not append a
        // full progress_tick JSON object every beat when stderr is being captured.
        type ProgressMinimalJsonEmissionId =
            | ProgressMinimalJsonHudOnly
            | ProgressMinimalJsonColdCadence
            | ProgressMinimalJsonCadence
            | ProgressMinimalJsonImportantDelta

        let private progressMinimalJsonEmissionText = function
            | ProgressMinimalJsonHudOnly -> "hud_only"
            | ProgressMinimalJsonColdCadence -> "cold_64s_json"
            | ProgressMinimalJsonCadence -> "active_16s_json"
            | ProgressMinimalJsonImportantDelta -> "important_delta_json"

        let private progressMinimalJsonEmissionShouldWrite = function
            | ProgressMinimalJsonHudOnly -> false
            | ProgressMinimalJsonColdCadence
            | ProgressMinimalJsonCadence
            | ProgressMinimalJsonImportantDelta -> true

        // MIGRATION: keep the no-work recycle threshold typed as an age state.
        // This prevents the logging cadence from mixing second counters with
        // beat counters or queue depths while we keep reducing stringy Hopac glue.
        type ProgressMinimalNoWorkAgeId =
            | ProgressMinimalNoWorkAgeFresh
            | ProgressMinimalNoWorkAgeRecycleEligible

        let private progressMinimalNoWorkAgeFor (noWorkS: int64) =
            if noWorkS >= 2L then ProgressMinimalNoWorkAgeRecycleEligible
            else ProgressMinimalNoWorkAgeFresh

        let private progressMinimalNoWorkAgeText = function
            | ProgressMinimalNoWorkAgeFresh -> "fresh_lt_2s"
            | ProgressMinimalNoWorkAgeRecycleEligible -> "recycle_eligible_ge_2s"

        let private progressMinimalJsonEmissionFor
            (beatNo: int64)
            (sampledWork: int64)
            (replayProgress: int64)
            (sampledDelta: int64)
            (semanticReceipts: int64)
            (replayDelta: int64)
            (rootDelta: int64)
            (terminalDelta: int64)
            (missedIntervals: int64)
            (noWorkS: int64) =
            let noAuthorityDelta =
                sampledDelta <= 0L
                && semanticReceipts <= 0L
                && replayDelta <= 0L
                && rootDelta <= 0L
                && terminalDelta <= 0L
                && missedIntervals <= 0L
            let noFreshDelta = sampledDelta <= 0L && replayDelta <= 0L && rootDelta <= 0L && terminalDelta <= 0L
            let noWorkAgeId = progressMinimalNoWorkAgeFor noWorkS
            if noAuthorityDelta then
                ProgressMinimalJsonHudOnly
            elif rootDelta >= 8L || terminalDelta >= 16L then
                ProgressMinimalJsonImportantDelta
            elif rootDelta > 0L || terminalDelta > 0L then
                if beatNo % 64L = 0L then ProgressMinimalJsonCadence else ProgressMinimalJsonHudOnly
            elif sampledWork <= 0L && replayProgress <= 0L then
                ProgressMinimalJsonHudOnly
            elif noFreshDelta && noWorkAgeId = ProgressMinimalNoWorkAgeRecycleEligible then
                if beatNo % 256L = 0L then ProgressMinimalJsonColdCadence else ProgressMinimalJsonHudOnly
            elif sampledDelta >= 16L || replayDelta >= 2048L then
                if beatNo % 64L = 0L then ProgressMinimalJsonCadence else ProgressMinimalJsonHudOnly
            elif beatNo % 64L = 0L then ProgressMinimalJsonCadence
            else ProgressMinimalJsonHudOnly

        // MIGRATION: the HUD and the rich JSON snapshot are separate clocks.
        // The HUD remains 250ms line-atomic; the rich snapshot is heavier and
        // intentionally sparser so it does not coalesce under replay pressure.
        type ProgressRichSnapshotCadenceId =
            | ProgressRichSnapshotSparse2s
            | ProgressRichSnapshotLegacy1s

        let private progressRichSnapshotCadenceMs = function
            | ProgressRichSnapshotSparse2s -> 2000L
            | ProgressRichSnapshotLegacy1s -> 1000L

        let private progressRichSnapshotCadenceText = function
            | ProgressRichSnapshotSparse2s -> "2s_best_effort_snapshot_jsonl"
            | ProgressRichSnapshotLegacy1s -> "1s_best_effort_snapshot_jsonl"

        let private progressPredictionRichCadenceId = ProgressRichSnapshotSparse2s
        let private progressPredictionRichCadenceMs = progressRichSnapshotCadenceMs progressPredictionRichCadenceId
        let private progressPredictionRichCadenceText = progressRichSnapshotCadenceText progressPredictionRichCadenceId
        type ProgressPredictionMetronomeLedger = private {
            startMs : int64
            beatTick : int64
            lastSampledWork : int64
            lastSemanticReceipts : int64
            lastReplayProgress : int64
            lastRootComplete : int64
            lastTerminalSignals : int64
        }

        type ProgressPredictionMetronomeObservation = private {
            sampledWork : int64
            sampledDelta : int64
            semanticDelta : int64
            replayDelta : int64
            rootDelta : int64
            terminalDelta : int64
        }

        let private progressPredictionMetronomeLedgerGate = obj()
        let mutable private progressPredictionMetronomeLedger = {
            startMs = 0L
            beatTick = 0L
            lastSampledWork = 0L
            lastSemanticReceipts = 0L
            lastReplayProgress = 0L
            lastRootComplete = 0L
            lastTerminalSignals = 0L
        }

        let private progressPredictionMetronomeBegin scheduledMs =
            lock progressPredictionMetronomeLedgerGate (fun () ->
                let previous = progressPredictionMetronomeLedger
                let startMs = if previous.startMs = 0L then scheduledMs else previous.startMs
                let next = { previous with startMs = startMs; beatTick = previous.beatTick + 1L }
                progressPredictionMetronomeLedger <- next
                startMs, next.beatTick)

        let private progressPredictionMetronomeRead () =
            lock progressPredictionMetronomeLedgerGate (fun () -> progressPredictionMetronomeLedger)

        let private progressPredictionMetronomeObserve sampledWork semanticReceipts replayProgress rootComplete terminalSignals =
            lock progressPredictionMetronomeLedgerGate (fun () ->
                let previous = progressPredictionMetronomeLedger
                let next = {
                    previous with
                        lastSampledWork = max previous.lastSampledWork sampledWork
                        lastSemanticReceipts = max previous.lastSemanticReceipts semanticReceipts
                        lastReplayProgress = max previous.lastReplayProgress replayProgress
                        lastRootComplete = max previous.lastRootComplete rootComplete
                        lastTerminalSignals = max previous.lastTerminalSignals terminalSignals }
                progressPredictionMetronomeLedger <- next
                {
                    sampledWork = next.lastSampledWork
                    sampledDelta = max 0L (next.lastSampledWork - previous.lastSampledWork)
                    semanticDelta = max 0L (next.lastSemanticReceipts - previous.lastSemanticReceipts)
                    replayDelta = max 0L (next.lastReplayProgress - previous.lastReplayProgress)
                    rootDelta = max 0L (next.lastRootComplete - previous.lastRootComplete)
                    terminalDelta = max 0L (next.lastTerminalSignals - previous.lastTerminalSignals)
                })

        let mutable private progressPredictionRichTickInFlight = 0
        let mutable private progressPredictionRichTickStartedMs = 0L

        type ProgressPredictionRichLedgerProjection = private {
            tickMs : int64
            tickNo : int64
            progressBp : int64
            sampledWork : int64
            cpuCoreMilli : int64
            etaS : int64
            totalS : int64
            semanticReceipts : int64
            structuralReceipts : int64
