        // MIGRATION: HUD readers must never wait behind the rich tick actor. The
        // immutable record is published as one volatile reference, preserving the
        // MIGRATION same-generation snapshot without reintroducing split atomics.
        let private progressPredictionRichLedgerRead () =
            System.Threading.Volatile.Read(&progressPredictionRichLedgerProjection)

        let private progressPredictionRichLedgerReplace snapshot =
            lock progressPredictionRichLedgerGate (fun () ->
                let current = System.Threading.Volatile.Read(&progressPredictionRichLedgerProjection)
                if snapshot.tickMs >= current.tickMs then
                    System.Threading.Volatile.Write(&progressPredictionRichLedgerProjection, snapshot))

        let private progressPredictionRichLedgerUpdate update =
            lock progressPredictionRichLedgerGate (fun () ->
                let current = System.Threading.Volatile.Read(&progressPredictionRichLedgerProjection)
                let next = update current
                System.Threading.Volatile.Write(&progressPredictionRichLedgerProjection, next))
