            System.Threading.Volatile.Read(&progressPredictionLineProjection)

        let private progressPredictionLineReplace tickMs tickNo progressBp etaS =
            lock progressPredictionLineGate (fun () ->
                let current = System.Threading.Volatile.Read(&progressPredictionLineProjection)
                if tickMs >= current.tickMs then
                    let next = {
                        tickMs = tickMs
                        tickNo = tickNo
                        progressBp = progressBp
                        etaS = etaS
                    }
                    System.Threading.Volatile.Write(&progressPredictionLineProjection, next))
