        // MIGRATION: 1810.jsonl emitted the same EJP0032 terminal receipt seven
        // times and then entered EJP0019 retry. Model terminal failure as a
        // process-wide three-state latch: open -> requested -> committed.
        type TerminalFailureExitLatch =
            | TerminalFailureExitOpen
            | TerminalFailureExitRequested of reason:CompilerKernelV2.OperationalReasonId
            | TerminalFailureExitCommitted of code:int

        type TerminalQapDeadlockLatch =
            | TerminalQapDeadlockUnobserved
            | TerminalQapDeadlockObserved

        let private terminalFailureLatchGate = obj()
        let mutable private terminalFailureExitLatch = TerminalFailureExitOpen
        let mutable private terminalQapDeadlockLatch = TerminalQapDeadlockUnobserved

        let terminalFailureExitMarkRequested reason =
            lock terminalFailureLatchGate (fun () ->
                match terminalFailureExitLatch with
                | TerminalFailureExitOpen -> terminalFailureExitLatch <- TerminalFailureExitRequested reason
                | TerminalFailureExitRequested _
                | TerminalFailureExitCommitted _ -> ())

        let terminalFailureExitMarkCommitted (code:int) =
            lock terminalFailureLatchGate (fun () ->
                terminalFailureExitLatch <- TerminalFailureExitCommitted code)

        let terminalFailureExitRequestedNow () =
            lock terminalFailureLatchGate (fun () ->
                match terminalFailureExitLatch with
                | TerminalFailureExitOpen -> false
                | TerminalFailureExitRequested _
                | TerminalFailureExitCommitted _ -> true)

        let terminalQapProvenDeadlockMarkObserved () =
            lock terminalFailureLatchGate (fun () ->
                terminalQapDeadlockLatch <- TerminalQapDeadlockObserved)

        let terminalQapProvenDeadlockNow () =
            lock terminalFailureLatchGate (fun () ->
                match terminalQapDeadlockLatch with
                | TerminalQapDeadlockUnobserved -> false
                | TerminalQapDeadlockObserved -> true)

        type OwnerDebtTieBreakerState = {
