        let private ownerDebtTieBreakerGate = obj()
        let mutable private ownerDebtTieBreakerState = {
            liveLastMs = 0L
            liveCount = 0L
            injectedLastMs = 0L
            injectedCount = 0L
            materialDeltaLastMs = 0L
            materialDeltaCount = 0L
            proceduralDeltaLastMs = 0L
            proceduralDeltaCount = 0L
