        type OwnerDebtActivityKind =
            | OwnerDebtMaterialFacts
            | OwnerDebtProceduralQueueMovement

        type OwnerDebtMaterialActivityKind = struct end
        type OwnerDebtProceduralActivityKind = struct end

        type OwnerDebtActivitySample<'Kind> = private {
            count : int64
            ageMs : int64
        }

        type OwnerDebtActivitySnapshot =
            | OwnerDebtActivityQuiescent
            | OwnerDebtActivityMaterialRecent of OwnerDebtActivitySample<OwnerDebtMaterialActivityKind>
            | OwnerDebtActivityProceduralOnly of OwnerDebtActivitySample<OwnerDebtProceduralActivityKind>
            | OwnerDebtActivityMixed of material:OwnerDebtActivitySample<OwnerDebtMaterialActivityKind> * procedural:OwnerDebtActivitySample<OwnerDebtProceduralActivityKind>

        type OwnerDebtProceduralExhaustion =
            | OwnerDebtProceduralOpen
            | OwnerDebtProceduralExhausted of queueDepth:int * activeDepth:int * pending:int * attemptCount:int64 * proceduralDeltaCount:int64

        let ownerDebtProceduralExhaustionFor queueDepth activeDepth pending attemptCount activity =
            let proceduralDeltaCount, materialRecent =
                match activity with
                | OwnerDebtActivityProceduralOnly sample -> sample.count, false
                | OwnerDebtActivityMixed(_, procedural) -> procedural.count, true
                | OwnerDebtActivityMaterialRecent _ -> 0L, true
                | OwnerDebtActivityQuiescent -> 0L, false
            if queueDepth <= 8
               && activeDepth <= 4
               && pending <= 4
               && queueDepth + activeDepth + pending <= 16
               && attemptCount >= 64L
               && proceduralDeltaCount > 0L
               && not materialRecent then
                OwnerDebtProceduralExhausted(queueDepth, activeDepth, pending, attemptCount, proceduralDeltaCount)
            else OwnerDebtProceduralOpen

        let ownerDebtProceduralExhaustionText = function
            | OwnerDebtProceduralOpen -> "OwnerDebtProceduralExhaustion(Open)"
            | OwnerDebtProceduralExhausted(queueDepth, activeDepth, pending, attempts, proceduralCount) ->
                FastRuntimeFormat.format "OwnerDebtProceduralExhaustion(Exhausted|qap=%d/%d/%d|attempts=%d|procedural_delta_count=%d|material_delta=false)" [| box queueDepth; box activeDepth; box pending; box attempts; box proceduralCount |]

        let noteOwnerDebtLiveWorkTieBreaker (beforeQ:int) (beforeA:int) (beforeP:int) (afterQ:int) (afterA:int) (afterP:int) =
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            lock ownerDebtTieBreakerGate (fun () ->
                ownerDebtTieBreakerState <-
                    { ownerDebtTieBreakerState with
                        liveLastMs = now
                        liveCount = ownerDebtTieBreakerState.liveCount + 1L })

        let noteOwnerDebtLiveWorkTieBreakerInjection (injected: bool) =
