                        { ownerDebtTieBreakerState with
                            injectedLastMs = now
                            injectedCount = ownerDebtTieBreakerState.injectedCount + 1L })

        let noteOwnerDebtLiveWorkTieBreakerActivity kind delta =
            if delta > 0 then
                let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                lock ownerDebtTieBreakerGate (fun () ->
                    ownerDebtTieBreakerState <-
                        match kind with
                        | OwnerDebtMaterialFacts ->
