            else
                match (canonicalRootAuthoritySnapshot()).phase with
                | CanonicalRootResolved _ ->
                    noteOwnerDebtLiveWorkTieBreakerProceduralDelta semanticDelta
                    TerminalSemanticPostRootCacheEnrichment
                | CanonicalRootUnarmed
                | CanonicalRootArmed _ ->
                    noteTerminalSemanticAuthorityDelta semanticDelta
                    noteOwnerDebtLiveWorkTieBreakerMaterialDelta semanticDelta
                    TerminalSemanticAuthorityAdmitted

        let terminalSemanticAuthorityCountNow () =
            (terminalSemanticFlowSnapshotNow ()).authorityCount

        let terminalSemanticAuthorityAgeMsNow () =
            let last = (terminalSemanticFlowSnapshotNow ()).authorityLastMs
            if last <= 0L then System.Int64.MaxValue
            else max 0L (System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - last)

        let terminalSemanticAuthorityActiveNow () =
            let snapshot = terminalSemanticFlowSnapshotNow ()
            let ageMs =
                if snapshot.authorityLastMs <= 0L then System.Int64.MaxValue
                else max 0L (System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - snapshot.authorityLastMs)
            snapshot.authorityCount > 0L && ageMs <= 15000L

        let noteTerminalSemanticDrainRequested durationMs =
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let requestedUntil = now + max 1000L durationMs
            lock terminalSemanticFlowGate (fun () ->
                terminalSemanticFlowState <-
                    { terminalSemanticFlowState with
                        drainUntilMs = max terminalSemanticFlowState.drainUntilMs requestedUntil
                        drainRequestCount = terminalSemanticFlowState.drainRequestCount + 1L
                        drainFirstRequestMs = if terminalSemanticFlowState.drainFirstRequestMs <= 0L then now else terminalSemanticFlowState.drainFirstRequestMs })

        let terminalSemanticDrainActiveNow () =
            let snapshot = terminalSemanticFlowSnapshotNow ()
            snapshot.drainUntilMs > System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()

        let terminalSemanticDrainRemainingMsNow () =
            let snapshot = terminalSemanticFlowSnapshotNow ()
            max 0L (snapshot.drainUntilMs - System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())

        let terminalSemanticDrainRequestCountNow () =
            (terminalSemanticFlowSnapshotNow ()).drainRequestCount

        let terminalSemanticDrainRequestAgeMsNow () =
            let first = (terminalSemanticFlowSnapshotNow ()).drainFirstRequestMs
            if first <= 0L then 0L
            else max 0L (System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - first)

        let noteTerminalFrontierProgress progressPct =
            let progressBp = max 0L (int64 (System.Math.Floor(progressPct * 100.0)))
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            lock terminalSemanticFlowGate (fun () ->
                if progressBp > terminalSemanticFlowState.frontierMaxBp then
