                            drainFirstRequestMs = 0L })

        let terminalFrontierProgressEpochNow () =
            (terminalSemanticFlowSnapshotNow ()).frontierEpoch

        let terminalFrontierProgressBpNow () =
            (terminalSemanticFlowSnapshotNow ()).frontierMaxBp

        let terminalFrontierProgressAgeMsNow () =
            let last = (terminalSemanticFlowSnapshotNow ()).frontierLastMs
            if last <= 0L then System.Int64.MaxValue
            else max 0L (System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - last)

        let noteTerminalCompletionCredit completedCost =
            let completedCost = max 0L completedCost
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            lock terminalSemanticFlowGate (fun () ->
                if completedCost > terminalSemanticFlowState.completionMaxCost then
                    terminalSemanticFlowState <-
