        let private ownerDebtTieBreakerAgeMs now last =
            if last <= 0L then System.Int64.MaxValue else max 0L (now - last)

        let ownerDebtLiveWorkTieBreakerActiveNow () =
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let snapshot = ownerDebtTieBreakerSnapshotNow ()
            ownerDebtTieBreakerIsRecent now snapshot.liveLastMs snapshot.liveCount

        let ownerDebtLiveWorkTieBreakerInjectionActiveNow () =
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let snapshot = ownerDebtTieBreakerSnapshotNow ()
            ownerDebtTieBreakerIsRecent now snapshot.injectedLastMs snapshot.injectedCount

        let ownerDebtLiveWorkTieBreakerMaterialDeltaActiveNow () =
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let snapshot = ownerDebtTieBreakerSnapshotNow ()
            ownerDebtTieBreakerIsRecent now snapshot.materialDeltaLastMs snapshot.materialDeltaCount

        let ownerDebtLiveWorkTieBreakerInjectionAgeMsNow () =
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            (ownerDebtTieBreakerSnapshotNow ()).injectedLastMs |> ownerDebtTieBreakerAgeMs now

        let ownerDebtLiveWorkTieBreakerMaterialDeltaAgeMsNow () =
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            (ownerDebtTieBreakerSnapshotNow ()).materialDeltaLastMs |> ownerDebtTieBreakerAgeMs now

        let ownerDebtLiveWorkTieBreakerProceduralDeltaAgeMsNow () =
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            (ownerDebtTieBreakerSnapshotNow ()).proceduralDeltaLastMs |> ownerDebtTieBreakerAgeMs now

        let ownerDebtLiveWorkTieBreakerCountNow () =
            (ownerDebtTieBreakerSnapshotNow ()).liveCount

        let ownerDebtLiveWorkTieBreakerInjectedCountNow () =
            (ownerDebtTieBreakerSnapshotNow ()).injectedCount

        let ownerDebtLiveWorkTieBreakerMaterialDeltaCountNow () =
            (ownerDebtTieBreakerSnapshotNow ()).materialDeltaCount

        let ownerDebtLiveWorkTieBreakerProceduralDeltaCountNow () =
            (ownerDebtTieBreakerSnapshotNow ()).proceduralDeltaCount

        let ownerDebtActivitySnapshotNow () =
            let materialCount = ownerDebtLiveWorkTieBreakerMaterialDeltaCountNow()
            let proceduralCount = ownerDebtLiveWorkTieBreakerProceduralDeltaCountNow()
            let materialAgeMs = ownerDebtLiveWorkTieBreakerMaterialDeltaAgeMsNow()
            let proceduralAgeMs = ownerDebtLiveWorkTieBreakerProceduralDeltaAgeMsNow()
            let materialRecent = materialCount > 0L && materialAgeMs <= 15000L
            let proceduralRecent = proceduralCount > 0L && proceduralAgeMs <= 15000L
            match materialRecent, proceduralRecent with
            | false, false -> OwnerDebtActivityQuiescent
            | true, false -> OwnerDebtActivityMaterialRecent { count = materialCount; ageMs = materialAgeMs }
            | false, true -> OwnerDebtActivityProceduralOnly { count = proceduralCount; ageMs = proceduralAgeMs }
            | true, true ->
                OwnerDebtActivityMixed(
                    { count = materialCount; ageMs = materialAgeMs },
                    { count = proceduralCount; ageMs = proceduralAgeMs })

        let ownerDebtActivitySnapshotText = function
            | OwnerDebtActivityQuiescent -> "OwnerDebtActivity(Quiescent)"
            | OwnerDebtActivityMaterialRecent sample -> sprintf "OwnerDebtActivity(MaterialRecent|count=%d|age_ms=%d)" sample.count sample.ageMs
            | OwnerDebtActivityProceduralOnly sample -> sprintf "OwnerDebtActivity(ProceduralOnly|count=%d|age_ms=%d)" sample.count sample.ageMs
            | OwnerDebtActivityMixed(material, procedural) ->
                FastRuntimeFormat.format "OwnerDebtActivity(Mixed|material_count=%d|material_age_ms=%d|procedural_count=%d|procedural_age_ms=%d)" [| box material.count; box material.ageMs; box procedural.count; box procedural.ageMs |]
        // MIGRATION: 1762 proved that progress_tick could carry RootPromiseFailed
        // + ExitFatalSemantic for thousands of rows without emitting the terminal
        // root_promise_failed_semantic_exit action.  Track action emission per
        // closure/promise so the hot native promise boundary can fire once,
        // independently of the no-work abort readiness branch.
        let private progressPredictionRootSemanticExitEmitted =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,int>()
        let noteRootSemanticExitEmitted (key:string) =
            if System.String.IsNullOrWhiteSpace key then 0
            else
                let keyRef = CompilerIdentityKernel.ContentDigest.ofText "root-semantic-exit" key
                progressPredictionRootSemanticExitEmitted.AddOrUpdate(keyRef, 1, fun _ old -> old + 1)
        // MIGRATION: 1723.jsonl proved that promise failures emitted by proof-tuple
        // rows did not always update the no-work suppression latch before the metronome
        // rescue loop fired again.  Keep the latch long enough for the whole compile-run
        // tail and expose a small public observer so EvalWorklist rows can close the
        // terminal immediately when they emit NativePromiseFailed/NoFurther.
        let private nativePromiseFailureClosedLatchWindowMs = 900000L
        type JpWaitLiveFrameDisposition =
            | JpWaitLiveFrameObserved
            | JpWaitLiveFrameClosedByNativePromiseFailure

        let jpWaitLiveFrameDispositionText = function
            | JpWaitLiveFrameObserved -> "JpWaitLiveFrameDisposition(Observed|authority=live_explicit_frame)"
            | JpWaitLiveFrameClosedByNativePromiseFailure -> "JpWaitLiveFrameDisposition(ClosedByNativePromiseFailure|authority=preexisting_native_promise_failure)"

        type JpWaitNativePromiseLatchDecision =
            | JpWaitFailClosedExplicitWorklist
            | JpWaitFailClosedLiveFrame
            | JpWaitContinueLiveFrame
            | JpWaitLiveConsoleObserver

        let jpWaitNativePromiseLatchDecisionText = function
            | JpWaitFailClosedExplicitWorklist -> "fail_closed_explicit_worklist_after_native_promise_failure"
            | JpWaitFailClosedLiveFrame -> "fail_closed_live_frame_after_native_promise_failure"
            | JpWaitContinueLiveFrame -> "continue_live_frame_without_native_promise_failure"
            | JpWaitLiveConsoleObserver -> "jp_wait_live_console_observer"

        type JpWaitLiveFrameStatusId = private | JpWaitLiveFrameStatusId of CompilerKernelV2.OperationalReasonId

        module JpWaitLiveFrameStatusIdOps =
            let create status = JpWaitLiveFrameStatusId (CompilerKernelV2.OperationalReasonIdOps.create status)
            let text (JpWaitLiveFrameStatusId status) = CompilerKernelV2.OperationalReasonIdOps.text status

        type JpWaitLiveFrameLifecycle =
            | JpWaitLiveFrameDormant
            | JpWaitLiveFrameObserved of key:string * status:JpWaitLiveFrameStatusId * observedMs:int64
            | JpWaitLiveFrameClosed of key:string * status:JpWaitLiveFrameStatusId * closedMs:int64

        let mutable private progressPredictionJpWaitLiveFrameLifecycle = JpWaitLiveFrameDormant
        type NativePromiseFailureSourceId =
            | NativePromiseFailureSourceMinimalProgressTick
            | NativePromiseFailureSourceDynamicRecordKeyBridgeTailCausalDead
            | NativePromiseFailureSourceBuildErrorTraceFinishFastTerminal

        let private nativePromiseFailureSourceText = function
            | NativePromiseFailureSourceMinimalProgressTick -> "DiagJson.progress_tick_minimal"
            | NativePromiseFailureSourceDynamicRecordKeyBridgeTailCausalDead -> "dynamic_record_key_bridge_tail_causal_dead"
            | NativePromiseFailureSourceBuildErrorTraceFinishFastTerminal -> "build_error_trace_finish_fast_terminal"

        type NativePromiseFailureAuthorityId =
            | NativePromiseFailureAuthorityUnspecified
            | NativePromiseFailureAuthorityTypedTerminalAction of semanticFailureId:string * promiseId:string * payloadClass:string * source:NativePromiseFailureSourceId

        let nativePromiseFailureAuthorityText = function
            | NativePromiseFailureAuthorityUnspecified ->
                "NativePromiseFailureAuthority(UnspecifiedExecutionPath)"
            | NativePromiseFailureAuthorityTypedTerminalAction(semanticFailureId, promiseId, payloadClass, source) ->
                "NativePromiseFailureAuthority(TypedTerminalAction|semantic_failure_id=" + semanticFailureId + "|promise=" + promiseId + "|payload_class=" + payloadClass + "|source=" + nativePromiseFailureSourceText source + ")"

        let mutable private progressPredictionNativePromiseFailureClosedAuthority = NativePromiseFailureAuthorityUnspecified

        let noteJpWaitLiveFrameObserved key status =
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let statusId = JpWaitLiveFrameStatusIdOps.create status
            lock progressPredictionTickGate (fun () ->
                progressPredictionJpWaitLiveFrameLifecycle <- JpWaitLiveFrameObserved(key, statusId, now)
                "jp_wait_observation:" + key + ":" + JpWaitLiveFrameStatusIdOps.text statusId + ":observed_ms=" + string now)

        // MIGRATION invariant: JP-wait is a consumer of native-promise failure,
        // never a producer. Calling this while the failure latch is open records
        // only a live-frame observation and cannot synthesize EJP0032 authority.
        let noteJpWaitLiveFrameClosed key status =
            let closedMs = progressPredictionNativePromiseFailureClosedMsNow ()
            if closedMs <= 0L then
                noteJpWaitLiveFrameObserved key status
            else
                let statusId = JpWaitLiveFrameStatusIdOps.create status
                lock progressPredictionTickGate (fun () ->
                    progressPredictionJpWaitLiveFrameLifecycle <- JpWaitLiveFrameClosed(key, statusId, closedMs)
                    "jp_wait_closure:" + key + ":" + JpWaitLiveFrameStatusIdOps.text statusId + ":native_promise_failure_closed_ms=" + string closedMs)
        let jpWaitLiveFrameClosedKeyNow () =
            lock progressPredictionTickGate (fun () ->
                match progressPredictionJpWaitLiveFrameLifecycle with
                | JpWaitLiveFrameClosed(key, _, _) -> key
                | _ -> "")
        let jpWaitLiveFrameClosedStatusNow () =
            lock progressPredictionTickGate (fun () ->
                match progressPredictionJpWaitLiveFrameLifecycle with
                | JpWaitLiveFrameClosed(_, status, _) -> JpWaitLiveFrameStatusIdOps.text status
                | _ -> "")
        let jpWaitLiveFrameClosedNow () =
            lock progressPredictionTickGate (fun () ->
                match progressPredictionJpWaitLiveFrameLifecycle with
                | JpWaitLiveFrameClosed _ -> true
                | _ -> false)
        let private nativePromiseFailureClosedRecently now =
            let closedMs = progressPredictionNativePromiseFailureClosedMsNow ()
            // Concurrent terminal observers may refresh closedMs between this reader's
            // clock sample and the atomic read.  A future-by-a-few-ms timestamp is still
            // a closed latch, not permission to reopen the promise.
            closedMs > 0L && (now < closedMs || (now - closedMs) <= nativePromiseFailureClosedLatchWindowMs)
        let private nativePromiseFailureClosedAgeMs now =
            let closedMs = progressPredictionNativePromiseFailureClosedMsNow ()
            if closedMs > 0L then max 0L (now - closedMs) else -1L
        let nativePromiseFailureClosedNow () =
            // Called on every replay tick and pinned cell (~3% of a large compile): read the latch before the
            // clock and without the tick lock (an aligned int64 read is atomic), since it is almost always unset.
            if progressPredictionNativePromiseFailureClosedMs <= 0L then false
            else
                let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                nativePromiseFailureClosedRecently now
        let nativePromiseFailureClosedAgeNowMs () =
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            nativePromiseFailureClosedAgeMs now
        let nativePromiseFailureClosedAuthorityNow () =
            lock progressPredictionTickGate (fun () ->
                nativePromiseFailureAuthorityText progressPredictionNativePromiseFailureClosedAuthority)
        let jpWaitNativePromiseLatchStateText decisionId =
            let latched = nativePromiseFailureClosedNow()
            let age = nativePromiseFailureClosedAgeNowMs()
            let key = jpWaitLiveFrameClosedKeyNow ()
            let status = jpWaitLiveFrameClosedStatusNow ()
            let decision = jpWaitNativePromiseLatchDecisionText decisionId
            "JpWaitNativePromiseLatch(latched=" + string latched + "|age_ms=" + string age + "|closed_key=" + key + "|closed_status=" + status + "|decision=" + decision + ")"
        let noteNativePromiseFailureClosed authorityId =
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            lock progressPredictionTickGate (fun () ->
                progressPredictionNativePromiseFailureClosedMs <- now
                progressPredictionNativePromiseFailureClosedAuthority <- authorityId)
            now
        let mutable private progressPredictionLastAnyProgressMs = 0L
        let mutable private progressPredictionLastReplayProgressMs = 0L
        let mutable private progressPredictionLastSemanticProgressMs = 0L

        type NativePromiseFailureRecoveryDisposition =
            | NativePromiseFailureRecoveryNotApplicable
            | NativePromiseFailureRecoveryAwaitingMaterialProgress of closedMs:int64 * authority:NativePromiseFailureAuthorityId
            | NativePromiseFailureRecoveredAfterMaterialProgress of closedMs:int64 * progressMs:int64 * authority:NativePromiseFailureAuthorityId
            | NativePromiseFailureRecoveryIrrevocable of authority:NativePromiseFailureAuthorityId

        let nativePromiseFailureRecoveryDispositionText = function
            | NativePromiseFailureRecoveryNotApplicable ->
                "NativePromiseFailureRecovery(NotApplicable)"
            | NativePromiseFailureRecoveryAwaitingMaterialProgress(closedMs, authorityId) ->
                "NativePromiseFailureRecovery(AwaitingMaterialProgress|closed_ms=" + string closedMs + "|authority=" + nativePromiseFailureAuthorityText authorityId + ")"
            | NativePromiseFailureRecoveredAfterMaterialProgress(closedMs, progressMs, authorityId) ->
                "NativePromiseFailureRecovery(RecoveredAfterMaterialProgress|closed_ms=" + string closedMs + "|progress_ms=" + string progressMs + "|authority=" + nativePromiseFailureAuthorityText authorityId + ")"
            | NativePromiseFailureRecoveryIrrevocable authorityId ->
                "NativePromiseFailureRecovery(Irrevocable|authority=" + nativePromiseFailureAuthorityText authorityId + ")"

        let private nativePromiseFailureAuthorityIsRecoverableWatchdog = function
            | NativePromiseFailureAuthorityTypedTerminalAction(_, _, payloadClass, _)
                when payloadClass = "[spiral_compiler] EJP0019" || payloadClass = "EJP0019" -> true
            | _ -> false

        let nativePromiseFailureRecoveryDispositionNow () =
            lock progressPredictionTickGate (fun () ->
                let closedMs = progressPredictionNativePromiseFailureClosedMs
                let authorityId = progressPredictionNativePromiseFailureClosedAuthority
                match authorityId with
                | NativePromiseFailureAuthorityUnspecified ->
                    NativePromiseFailureRecoveryNotApplicable
                | _ when nativePromiseFailureAuthorityIsRecoverableWatchdog authorityId ->
                    if closedMs > 0L && progressPredictionLastAnyProgressMs > closedMs then
                        NativePromiseFailureRecoveredAfterMaterialProgress(closedMs, progressPredictionLastAnyProgressMs, authorityId)
                    else
                        NativePromiseFailureRecoveryAwaitingMaterialProgress(closedMs, authorityId)
                | _ ->
                    NativePromiseFailureRecoveryIrrevocable authorityId)

        let tryRecoverNativePromiseFailureAfterMaterialProgress progressMs =
            lock progressPredictionTickGate (fun () ->
                let closedMs = progressPredictionNativePromiseFailureClosedMs
                let authorityId = progressPredictionNativePromiseFailureClosedAuthority
                if closedMs > 0L
                   && progressMs > closedMs
                   && nativePromiseFailureAuthorityIsRecoverableWatchdog authorityId then
                    let authority = nativePromiseFailureAuthorityText authorityId
                    progressPredictionNativePromiseFailureClosedMs <- 0L
                    progressPredictionNativePromiseFailureClosedAuthority <- NativePromiseFailureAuthorityUnspecified
                    true, closedMs, progressMs, authority
                else
                    false, closedMs, progressMs, nativePromiseFailureAuthorityText authorityId)

        let nativePromiseFailureCanVetoRetryNow () =
            match nativePromiseFailureRecoveryDispositionNow() with
            | NativePromiseFailureRecoveryIrrevocable _ -> nativePromiseFailureClosedNow()
            | NativePromiseFailureRecoveryNotApplicable
            | NativePromiseFailureRecoveryAwaitingMaterialProgress _
            | NativePromiseFailureRecoveredAfterMaterialProgress _ -> false
        let mutable private progressPredictionLastStallProbeSeconds = -1L
        let mutable private progressPredictionMaterialStallSinceMs = 0L
        let mutable private progressPredictionLastMaterialStallProbeSeconds = -1L

        // MIGRATION MIGRATION : the minimal->rich bridge no longer stores a
        // bare observer string and then lets the rich heartbeat infer a fatal
        // dropped-evidence state.  The minimal side stamps a compact typed
        // receipt.  The rich side either receives that receipt with an age, or
        // explicitly reports AwaitingFreshMinimalEvidence.  A missing observer
        // payload is therefore not root-collapse authority.
        type MinimalNativeFailureEvidenceClassId =
            | MinimalNativeFailureSemanticStaleRetarget
            | MinimalNativeFailureIdleCrossKindSidecar
            | MinimalNativeFailurePureTopologyZeroFact
            | MinimalNativeFailurePlateauPoison
            | MinimalNativeFailureCyclePoison
            | MinimalNativeFailureNoFurther
            | MinimalNativeFailureObserverOnly

        [<Struct>]
        type MinimalToRichEvidenceReceipt = {
            stampedMs:int64
            classId:MinimalNativeFailureEvidenceClassId
            payload:string
            rootStatus:string
            waitGraph:string
            liveEvidence:string
            preservationAction:string
            }

        let minimalNativeFailureEvidenceClassText = function
            | MinimalNativeFailureSemanticStaleRetarget -> "SemanticStaleRetarget"
            | MinimalNativeFailureIdleCrossKindSidecar -> "IdleCrossKindSidecar"
            | MinimalNativeFailurePureTopologyZeroFact -> "PureTopologyZeroFact"
            | MinimalNativeFailurePlateauPoison -> "PlateauPoison"
            | MinimalNativeFailureCyclePoison -> "CyclePoison"
            | MinimalNativeFailureNoFurther -> "NoFurther"
            | MinimalNativeFailureObserverOnly -> "ObserverOnly"

        let private receiptPart key (text:string) =
            let safe = if System.String.IsNullOrWhiteSpace text then "unknown" else text.Replace("\n", " ").Replace("\r", " ")
            key + "=" + safe

        let minimalToRichEvidenceReceiptText receipt =
            "MinimalToRichEvidenceReceipt(class=" + minimalNativeFailureEvidenceClassText receipt.classId
            + "|" + receiptPart "payload" receipt.payload
            + "|" + receiptPart "root" receipt.rootStatus
            + "|" + receiptPart "wait_graph" receipt.waitGraph
            + "|" + receiptPart "live" receipt.liveEvidence
            + "|" + receiptPart "action" receipt.preservationAction
            + "|stamped_ms=" + string receipt.stampedMs + ")"

        let mutable private progressPredictionLastMinimalNativeFailureEvidenceMs = 0L
        let mutable private progressPredictionLastMinimalNativeFailureEvidenceText = ""
        let mutable private progressPredictionLastMinimalNativeFailureEvidenceReceipt : MinimalToRichEvidenceReceipt option = None

        let noteMinimalNativeFailureEvidenceReceipt (receipt:MinimalToRichEvidenceReceipt) =
            lock progressPredictionTickGate (fun () ->
                progressPredictionLastMinimalNativeFailureEvidenceMs <- receipt.stampedMs
                progressPredictionLastMinimalNativeFailureEvidenceText <- minimalToRichEvidenceReceiptText receipt
                progressPredictionLastMinimalNativeFailureEvidenceReceipt <- Some receipt)

        let latestMinimalNativeFailureEvidenceReceipt maxAgeMs =
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            lock progressPredictionTickGate (fun () ->
                let age = if progressPredictionLastMinimalNativeFailureEvidenceMs > 0L then now - progressPredictionLastMinimalNativeFailureEvidenceMs else System.Int64.MaxValue
                match progressPredictionLastMinimalNativeFailureEvidenceReceipt with
                | Some receipt when age >= 0L && age <= maxAgeMs -> Some(receipt, age)
                | _ -> None)

        let latestMinimalNativeFailureEvidence maxAgeMs =
            match latestMinimalNativeFailureEvidenceReceipt maxAgeMs with
            | Some(receipt, age) -> minimalToRichEvidenceReceiptText { receipt with preservationAction = receipt.preservationAction + "|age_ms=" + string age }
            | None -> ""
        let mutable private progressPredictionNoWorkStallPoke : (unit -> unit) option = None
        let setNoWorkStallPoke (_handler: unit -> unit) =
            // BREAKTHROUGH BONUS: registration is retained as a source-compatibility
            // surface, but the metronome cannot own or invoke scheduler mutation.
            lock progressPredictionTickGate (fun () ->
                progressPredictionNoWorkStallPoke <- None)
        let noteNoWorkRescueGateBusy () =
            lock progressPredictionTickGate (fun () ->
                progressPredictionNoWorkRescueGateBusyCount <- progressPredictionNoWorkRescueGateBusyCount + 1L)
        let noWorkRescueGateBusyCount () =
            lock progressPredictionTickGate (fun () -> progressPredictionNoWorkRescueGateBusyCount)
        let private tryNoWorkStallPoke () =
            let handlerOpt = lock progressPredictionTickGate (fun () -> progressPredictionNoWorkStallPoke)
            match handlerOpt with
            | Some handler ->
                // MIGRATION: do not swallow rescue-handler exceptions here.
                // The detached worker already catches and emits error_type/message; returning false hid
                // the obstruction in MIGRATION after the first gate-busy rescues.
                handler()
                true
            | None -> false

        type NoWorkRescueStartPolicyId =
            | NoWorkRescueAlreadyInFlightObserveOnly
            | NoWorkRescueDedicatedThreadStart

        type NoWorkRescueBurstClass =
            | NoWorkRescueBurstNoHandler
            | NoWorkRescueBurstNoDelta
            | NoWorkRescueBurstReplayDelta
            | NoWorkRescueBurstSemanticDelta
            | NoWorkRescueBurstRootOrTerminalDelta
            | NoWorkRescueBurstMixedDelta

        let noWorkRescueBurstClassFor handlerInvoked workDelta replayDelta rootDelta terminalDelta =
            if not handlerInvoked then NoWorkRescueBurstNoHandler
            else
                let semantic = workDelta > 0L
                let replay = replayDelta > 0L
                let terminal = rootDelta > 0L || terminalDelta > 0L
                let classes = (if semantic then 1 else 0) + (if replay then 1 else 0) + (if terminal then 1 else 0)
                if classes > 1 then NoWorkRescueBurstMixedDelta
                elif terminal then NoWorkRescueBurstRootOrTerminalDelta
                elif semantic then NoWorkRescueBurstSemanticDelta
                elif replay then NoWorkRescueBurstReplayDelta
                else NoWorkRescueBurstNoDelta

        let noWorkRescueBurstClassText = function
            | NoWorkRescueBurstNoHandler -> "NoWorkRescueBurst(NoHandler)"
            | NoWorkRescueBurstNoDelta -> "NoWorkRescueBurst(NoDelta)"
            | NoWorkRescueBurstReplayDelta -> "NoWorkRescueBurst(ReplayDelta)"
            | NoWorkRescueBurstSemanticDelta -> "NoWorkRescueBurst(SemanticDelta)"
            | NoWorkRescueBurstRootOrTerminalDelta -> "NoWorkRescueBurst(RootOrTerminalDelta)"
            | NoWorkRescueBurstMixedDelta -> "NoWorkRescueBurst(MixedDelta)"

        let noWorkRescueStartPolicyText = function
            | NoWorkRescueAlreadyInFlightObserveOnly -> "already_in_flight_observe_only"
            | NoWorkRescueDedicatedThreadStart -> "dedicated_thread_start"

        let noWorkRescueStartPolicyFor rescueWasInFlight =
            if rescueWasInFlight then NoWorkRescueAlreadyInFlightObserveOnly
            else NoWorkRescueDedicatedThreadStart
        let private progressPredictionPlateauHardAbortS = 30L

        let private progressPredictionAbortMessage () =
            "[spiral_compiler] EJP0022: compile progress plateau; replay counters stopped moving while diagnostics kept burning CPU. Run ended early with a reproducible frontier instead of waiting for manual interrupt."

        type ProgressPlateauEvidenceId =
            | PlateauEvidenceNone
            | PlateauEvidenceReplayProgress
            | PlateauEvidenceRootProgress
            | PlateauEvidenceTerminalSignal
            | PlateauEvidenceSampledWork
            | PlateauEvidenceSemanticWork
            | PlateauEvidencePostRootObserverChurn

        let private progressPlateauEvidenceToString evidence =
            match evidence with
            | PlateauEvidenceNone -> "none"
            | PlateauEvidenceReplayProgress -> "replay_progress"
            | PlateauEvidenceRootProgress -> "root_progress"
            | PlateauEvidenceTerminalSignal -> "terminal_signal"
            | PlateauEvidenceSampledWork -> "sampled_work"
            | PlateauEvidenceSemanticWork -> "semantic_work"
            | PlateauEvidencePostRootObserverChurn -> "post_root_observer_churn_non_material"

        type ProgressPlateauDecisionId =
            | PlateauDecisionNone
            | PlateauDecisionGenericAbort
            | PlateauDecisionRouteToNoWorkAbort
            | PlateauDecisionHoldLiveReplayEvidence
            | PlateauDecisionExtendLiveReplayEvidence

        let private progressPlateauDecisionText = function
            | PlateauDecisionNone -> "none"
            | PlateauDecisionGenericAbort -> "generic_abort"
            | PlateauDecisionRouteToNoWorkAbort -> "route_to_no_work_abort"
            | PlateauDecisionHoldLiveReplayEvidence -> "hold_live_replay_evidence"
            | PlateauDecisionExtendLiveReplayEvidence -> "extend_live_replay_evidence"

        // MIGRATION: migrate heartbeat control labels to closed DUs.  JSON keeps the
        // string projection for downstream compatibility, but predicates stop owning
        // raw strings as control values.
        type ProgressOverviewStateId =
            | OverviewQuietOrStartup
            | OverviewWorkProgress
            | OverviewReplayProgress
            | OverviewNoWorkStall
            | OverviewNoWorkStallAbortRequested
            | OverviewNoWorkRescueSaturationAbortRequested
            | OverviewReplayChatterAbortRequested
            | OverviewPlateauAbortRequested
            | OverviewCpuBurnSemanticQuiet

        let private progressOverviewStateText = function
            | OverviewQuietOrStartup -> "quiet_or_startup"
            | OverviewWorkProgress -> "work_progress"
            | OverviewReplayProgress -> "replay_progress"
            | OverviewNoWorkStall -> "no_work_stall"
            | OverviewNoWorkStallAbortRequested -> "no_work_stall_abort_requested"
            | OverviewNoWorkRescueSaturationAbortRequested -> "no_work_rescue_saturation_abort_requested"
            | OverviewReplayChatterAbortRequested -> "replay_chatter_abort_requested"
            | OverviewPlateauAbortRequested -> "plateau_abort_requested"
            | OverviewCpuBurnSemanticQuiet -> "cpu_burn_semantic_quiet"

        let private progressOverviewStateCode = function
            | OverviewWorkProgress -> 1L
            | OverviewReplayProgress -> 2L
            | OverviewNoWorkStall -> 3L
            | OverviewNoWorkStallAbortRequested -> 4L
            | OverviewPlateauAbortRequested -> 5L
            | OverviewCpuBurnSemanticQuiet -> 6L
            | OverviewNoWorkRescueSaturationAbortRequested -> 7L
            | OverviewReplayChatterAbortRequested -> 8L
            | OverviewQuietOrStartup -> 0L

        type ProgressParallelismStateId =
            | ParallelismCpuUnknown
            | ParallelismCpuQuiet
            | ParallelismSingleCoreBurn
            | ParallelismUnderutilizedParallelWork
            | ParallelismPartialCoreUse
            | ParallelismMultiCoreHot

        let private progressParallelismStateText = function
            | ParallelismCpuUnknown -> "cpu_unknown"
            | ParallelismCpuQuiet -> "cpu_quiet"
            | ParallelismSingleCoreBurn -> "single_core_burn"
            | ParallelismUnderutilizedParallelWork -> "underutilized_parallel_work"
            | ParallelismPartialCoreUse -> "partial_core_use"
            | ParallelismMultiCoreHot -> "multi_core_hot"

        let private progressParallelismStateCode = function
            | ParallelismCpuQuiet -> 1L
            | ParallelismSingleCoreBurn -> 2L
            | ParallelismUnderutilizedParallelWork -> 3L
            | ParallelismPartialCoreUse -> 4L
            | ParallelismMultiCoreHot -> 5L
            | ParallelismCpuUnknown -> 0L

        type NoWorkAbortReasonId =
            | NoWorkAbortNone
            | NoWorkAbortReplayObligationExtendedFrozenAuthority
            | NoWorkAbortReplayObligationMidAuthorityFrozen
            | NoWorkAbortLateQuietGateBusy
            | NoWorkAbortMidGraphGateBusy
            | NoWorkAbortStallWithRescueEvidence
            | NoWorkAbortLongStallFallback
            | NoWorkAbortRescueSaturation
            | NoWorkAbortLateRaceTinyReplayDrip
            | NoWorkAbortIdleCrossKindRichStaleSaturation
            | NoWorkAbortIdleCrossKindRetryExhausted
            | NoWorkAbortFrozenDriverRootAuthority
            | NoWorkAbortCpuQuietNoDeltaSpin

        let private noWorkAbortReasonText = function
            | NoWorkAbortNone -> "none"
            | NoWorkAbortReplayObligationExtendedFrozenAuthority -> "replay_obligation_extended_frozen_authority"
            | NoWorkAbortReplayObligationMidAuthorityFrozen -> "replay_obligation_mid_authority_frozen"
            | NoWorkAbortLateQuietGateBusy -> "late_quiet_gate_busy"
            | NoWorkAbortMidGraphGateBusy -> "mid_graph_gate_busy"
            | NoWorkAbortStallWithRescueEvidence -> "stall_with_rescue_evidence"
            | NoWorkAbortLongStallFallback -> "long_stall_fallback"
            | NoWorkAbortRescueSaturation -> "rescue_saturation"
            | NoWorkAbortLateRaceTinyReplayDrip -> "late_race_tiny_replay_drip"
            | NoWorkAbortIdleCrossKindRichStaleSaturation -> "idle_cross_kind_rich_stale_saturation"
            | NoWorkAbortIdleCrossKindRetryExhausted -> "idle_cross_kind_retry_exhausted"
            | NoWorkAbortFrozenDriverRootAuthority -> "frozen_driver_root_authority"
            | NoWorkAbortCpuQuietNoDeltaSpin -> "cpu_quiet_no_delta_spin"

        type NoWorkGateProbePolicyId =
            | NoWorkGateProbeBounded64ms
            | NoWorkGateProbeEscalated128ms
            | NoWorkGateProbeEscalated256ms
            | NoWorkGateProbeEscalated512ms

        let noWorkGateProbePolicyFor gateBusySeen =
            if gateBusySeen >= 16L then NoWorkGateProbeEscalated512ms
            elif gateBusySeen >= 8L then NoWorkGateProbeEscalated256ms
            elif gateBusySeen >= 3L then NoWorkGateProbeEscalated128ms
            else NoWorkGateProbeBounded64ms

        let noWorkGateProbeWaitMs gateBusySeen =
            match noWorkGateProbePolicyFor gateBusySeen with
            | NoWorkGateProbeEscalated512ms -> 512
            | NoWorkGateProbeEscalated256ms -> 256
            | NoWorkGateProbeEscalated128ms -> 128
            | NoWorkGateProbeBounded64ms -> 64

        let noWorkGateProbePolicyText = function
            | NoWorkGateProbeBounded64ms -> "bounded_64ms"
            | NoWorkGateProbeEscalated128ms -> "escalated_128ms"
            | NoWorkGateProbeEscalated256ms -> "escalated_256ms"
            | NoWorkGateProbeEscalated512ms -> "escalated_512ms"

        type NoWorkReplayEvidenceId =
            | NoWorkReplayEvidenceNone
            | NoWorkReplayEvidenceSchedulesOnly
            | NoWorkReplayEvidenceTerminalOnly
            | NoWorkReplayEvidenceLowAuthorityRootTerminalDrip
            | NoWorkReplayEvidenceDriverOrRoot
            | NoWorkReplayEvidenceMixed

        let noWorkReplayEvidenceFor replaySchedules replayDrivers rootCompleteStores terminalSignals =
            let hasReplay = replaySchedules > 0 || replayDrivers > 0
            let hasRoot = rootCompleteStores > 0
            let hasTerminal = terminalSignals > 0
            let lowAuthorityRootTerminalDrip =
                hasRoot
                && hasTerminal
                && rootCompleteStores <= 8
                && replayDrivers <= 16
                && replaySchedules <= 64
                && terminalSignals <= 32
            match hasReplay, hasRoot, hasTerminal with
            | false, false, false -> NoWorkReplayEvidenceNone
            | _, true, true when lowAuthorityRootTerminalDrip -> NoWorkReplayEvidenceLowAuthorityRootTerminalDrip
            | true, false, true -> NoWorkReplayEvidenceMixed
            | true, false, false -> NoWorkReplayEvidenceSchedulesOnly
            | false, false, true -> NoWorkReplayEvidenceTerminalOnly
            | _, true, _ -> NoWorkReplayEvidenceDriverOrRoot

        let noWorkReplayEvidenceText = function
            | NoWorkReplayEvidenceNone -> "none"
            | NoWorkReplayEvidenceSchedulesOnly -> "schedules_only"
            | NoWorkReplayEvidenceTerminalOnly -> "terminal_only"
            | NoWorkReplayEvidenceLowAuthorityRootTerminalDrip -> "low_authority_root_terminal_drip"
            | NoWorkReplayEvidenceDriverOrRoot -> "driver_or_root"
            | NoWorkReplayEvidenceMixed -> "mixed"

        let noWorkReplayEvidenceSupportsNativeCallback = function
            | NoWorkReplayEvidenceDriverOrRoot -> true
            | NoWorkReplayEvidenceNone
            | NoWorkReplayEvidenceSchedulesOnly
            | NoWorkReplayEvidenceTerminalOnly
            | NoWorkReplayEvidenceLowAuthorityRootTerminalDrip
            | NoWorkReplayEvidenceMixed -> false

        type ReplayDeltaMaterialityId =
            | ReplayDeltaMaterialAuthority
            | ReplayDeltaTinyDripNonMaterial
            | ReplayDeltaPostRootObserverChurn

        let replayDeltaMaterialityText = function
            | ReplayDeltaMaterialAuthority -> "material_replay_delta"
            | ReplayDeltaTinyDripNonMaterial -> "tiny_replay_drip_non_material"
            | ReplayDeltaPostRootObserverChurn -> "post_root_observer_churn_non_material"

        type NoWorkStallCauseId =
            | NoWorkStallCauseNone
            | NoWorkStallCauseIdleCrossKindReplayDriver
            | NoWorkStallCauseIdleCrossKindRetryExhausted
            | NoWorkStallCauseReplayObligationDeferred
            | NoWorkStallCauseSemanticStaleRetarget
            | NoWorkStallCauseCycleBreakPoisonLiveTail
            | NoWorkStallCauseFrozenDriverRoot
            | NoWorkStallCauseTinyReplayDrip
            | NoWorkStallCauseDriverOrRoot

        let noWorkStallCauseText = function
            | NoWorkStallCauseNone -> "none"
            | NoWorkStallCauseIdleCrossKindReplayDriver -> "idle_cross_kind_replay_driver"
            | NoWorkStallCauseIdleCrossKindRetryExhausted -> "idle_cross_kind_retry_exhausted"
            | NoWorkStallCauseReplayObligationDeferred -> "replay_obligation_deferred"
            | NoWorkStallCauseSemanticStaleRetarget -> "semantic_stale_retarget"
            | NoWorkStallCauseCycleBreakPoisonLiveTail -> "cycle_break_poison_live_tail"
            | NoWorkStallCauseFrozenDriverRoot -> "frozen_driver_root"
            | NoWorkStallCauseTinyReplayDrip -> "tiny_replay_drip"
            | NoWorkStallCauseDriverOrRoot -> "driver_or_root"

        type NoWorkFreshDeltaStateId =
            | NoWorkFreshDeltaPresent
            | NoWorkFreshDeltaAbsent

        let noWorkFreshDeltaStateText = function
            | NoWorkFreshDeltaPresent -> "fresh_delta_present"
            | NoWorkFreshDeltaAbsent -> "no_fresh_delta"

        // Cross-kind liveness is a typed observation, not a lifetime diagnostic
        // counter. Historical rows can prove that a path existed, but cannot keep
        // the terminal graph open after physical pending/queue/active state has
        // drained and fresh semantic work is still advancing.
        type MinimalCrossKindQuiescentCauseId =
            | MinimalCrossKindIdleReplayDriver

        let minimalCrossKindQuiescentCauseText = function
            | MinimalCrossKindIdleReplayDriver -> "idle_cross_kind_replay_driver"

        type MinimalCrossKindObservation =
            | MinimalCrossKindAbsent
            | MinimalCrossKindPhysicalLive of pending:int64 * queue:int64 * active:int64
            | MinimalCrossKindQuiescentCauseLive of cause:MinimalCrossKindQuiescentCauseId
            | MinimalCrossKindHistoricalOnlyIgnored of pokeResumedCount:int * obligationRunCount:int

        let minimalCrossKindObservationText = function
            | MinimalCrossKindAbsent -> "MinimalCrossKind(Absent)"
            | MinimalCrossKindPhysicalLive(pending, queue, active) ->
                FastRuntimeFormat.format "MinimalCrossKind(PhysicalLive|pending=%d|queue=%d|active=%d)" [| box pending; box queue; box active |]
            | MinimalCrossKindQuiescentCauseLive cause ->
                "MinimalCrossKind(QuiescentCauseLive|cause=" + minimalCrossKindQuiescentCauseText cause + ")"
            | MinimalCrossKindHistoricalOnlyIgnored(pokeResumedCount, obligationRunCount) ->
                sprintf "MinimalCrossKind(HistoricalOnlyIgnored|poke_resumed=%d|obligation_run=%d)" pokeResumedCount obligationRunCount

        let minimalCrossKindObservationIsLive = function
            | MinimalCrossKindPhysicalLive _
            | MinimalCrossKindQuiescentCauseLive _ -> true
            | MinimalCrossKindAbsent
            | MinimalCrossKindHistoricalOnlyIgnored _ -> false

        let minimalCrossKindObservationCount = function
            | MinimalCrossKindPhysicalLive(pending, queue, active) -> max 1L (max pending (max queue active))
            | MinimalCrossKindQuiescentCauseLive _ -> 1L
            | MinimalCrossKindAbsent
            | MinimalCrossKindHistoricalOnlyIgnored _ -> 0L

        let minimalCrossKindObservationFor
            (quiescentCause:MinimalCrossKindQuiescentCauseId option)
            (pending:int64)
            (queue:int64)
            (active:int64)
            (hasFreshDelta:bool)
            (noWorkSeconds:int64)
            (pokeResumedCount:int)
            (obligationRunCount:int) =
            if pending > 0L || queue > 0L || active > 0L then
                MinimalCrossKindPhysicalLive(max 0L pending, max 0L queue, max 0L active)
            elif not hasFreshDelta && noWorkSeconds > 0L then
                match quiescentCause with
                | Some cause -> MinimalCrossKindQuiescentCauseLive cause
                | None when pokeResumedCount > 0 || obligationRunCount > 0 -> MinimalCrossKindHistoricalOnlyIgnored(pokeResumedCount, obligationRunCount)
                | None -> MinimalCrossKindAbsent
            elif pokeResumedCount > 0 || obligationRunCount > 0 then
                MinimalCrossKindHistoricalOnlyIgnored(pokeResumedCount, obligationRunCount)
            else MinimalCrossKindAbsent

        // MIGRATION: the 1468 runtime proved "frozen_driver_root" was still too
        // generic.  Keep the abort/gate DU stable, but type the source so HUD/JSONL
        // can distinguish a repeat-cap chatter freeze from a missing-prefetch +
        // cycle-break poison freeze.
        type NoWorkFrozenFrontierSourceId =
            | NoWorkFrozenFrontierNoSpecificSource
            | NoWorkFrozenFrontierRepeatCapProbation
            | NoWorkFrozenFrontierSemanticMissingAfterPrefetch
            | NoWorkFrozenFrontierCycleBreakPoison
            | NoWorkFrozenFrontierMissingPrefetchCycleBreak

        let noWorkFrozenFrontierSourceText = function
            | NoWorkFrozenFrontierNoSpecificSource -> "none"
            | NoWorkFrozenFrontierRepeatCapProbation -> "repeat_cap_probation"
            | NoWorkFrozenFrontierSemanticMissingAfterPrefetch -> "semantic_missing_after_prefetch"
            | NoWorkFrozenFrontierCycleBreakPoison -> "cycle_break_poison"
            | NoWorkFrozenFrontierMissingPrefetchCycleBreak -> "missing_prefetch_cycle_break"

        type SidecarStickyTargetId =
            | SidecarStickyTargetAbsent
            | SidecarStickyTargetEmptyFrontier
            | SidecarStickyTargetPresent

        let sidecarStickyTargetOfText (text:string) =
            if System.String.IsNullOrWhiteSpace text || text = "-" then
                SidecarStickyTargetAbsent
            else
                let targetHead = text.Split([|'|'|], 2, StringSplitOptions.None).[0]
                if targetHead = "frontier:0/0/0" then
                    SidecarStickyTargetEmptyFrontier
                else
                    SidecarStickyTargetPresent

        let sidecarStickyTargetIsPresent = function
            | SidecarStickyTargetPresent -> true
            | SidecarStickyTargetAbsent
            | SidecarStickyTargetEmptyFrontier -> false

        type SidecarStickyPhysicalPendingDecisionId =
            | SidecarStickyNoTarget
            | SidecarStickyRawAndFrontierPending
            | SidecarStickyRawPendingFrontierUnknown
            | SidecarStickyStaleRawPendingFrontierZero
            | SidecarStickyNoPhysicalPending

        let sidecarStickyPhysicalPendingDecisionText = function
            | SidecarStickyNoTarget -> "sidecar_no_target"
            | SidecarStickyRawAndFrontierPending -> "sidecar_raw_and_frontier_pending"
            | SidecarStickyRawPendingFrontierUnknown -> "sidecar_raw_pending_frontier_unknown"
            | SidecarStickyStaleRawPendingFrontierZero -> "sidecar_stale_raw_pending_frontier_zero"
            | SidecarStickyNoPhysicalPending -> "sidecar_no_physical_pending"

        let sidecarStickyPhysicalPendingDecisionHasPhysical = function
            | SidecarStickyRawAndFrontierPending -> true
            | SidecarStickyRawPendingFrontierUnknown
            | SidecarStickyNoTarget
            | SidecarStickyStaleRawPendingFrontierZero
            | SidecarStickyNoPhysicalPending -> false

        let sidecarStickyPhysicalPendingDecisionFor (rawPending: int64) (frontierPending: int64) (frontierKnown: bool) (hasTarget: bool) =
            if not hasTarget then SidecarStickyNoTarget
            elif rawPending > 0L && frontierKnown && frontierPending > 0L then SidecarStickyRawAndFrontierPending
            elif rawPending > 0L && not frontierKnown then SidecarStickyRawPendingFrontierUnknown
            elif rawPending > 0L && frontierKnown && frontierPending <= 0L then SidecarStickyStaleRawPendingFrontierZero
            elif rawPending > 0L && frontierPending > 0L then SidecarStickyRawAndFrontierPending
            else SidecarStickyNoPhysicalPending

