            | MinimalSidecarStackFenceShadowTimeoutPierced -> "sidecar_shadow_alt_timeout_pierced_stack_fence"
            | MinimalSidecarParentReplayCycleBreakPoisonShadowTimeoutPierced -> "parent_replay_cycle_break_poison_shadow_timeout_pierced_repeat_cap_probation"
            | MinimalSidecarParentContinuationDeferredChildShadowTimeoutPierced -> "parent_continuation_deferred_child_shadow_timeout_pierced_bridge_tail"
