            | MinimalSidecarDynamicRecordKeyBridgeTailShadowTimeoutPierced -> "dynamic_record_key_bridge_tail_shadow_timeout_pierced_weak_pending_active_root"
            | MinimalSidecarCooperativeYieldShadowTimerPierced -> "cooperative_yield_shadow_timer_monotonic_pierced"
            | MinimalSidecarIdleCrossKindActiveTySidecarShadowTimeoutPierced -> "idle_cross_kind_replay_driver_active_ty_sidecar_shadow_timeout_pierced"
            | MinimalSidecarIfUnknownReturnConditionShadowTimeoutPierced -> "if_unknown_return_condition_shadow_timeout_pierced_repeat_cap"
            | MinimalSidecarIfUnknownReturnAbsentShadowTimeoutPierced -> "if_unknown_return_absent_sidecar_shadow_timeout_pierced_repeat_cap"
            | MinimalSidecarShadowAltTimeoutLeaseExpired -> "sidecar_shadow_alt_timeout_lease_expired"
            | MinimalSidecarPhysicalPendingAbsentFailClosed -> "sidecar_physical_pending_absent_fail_closed"
            | MinimalSidecarIdleCrossKindWithActiveTySidecarDrain -> "idle_cross_kind_replay_driver_with_active_ty_sidecar_drain"
            | MinimalSidecarActivelyDrainingTySidecar -> "actively_draining_ty_sidecar"
            | MinimalSidecarStillMissingAfterProbe -> "still_missing_after_probe"

        let minimalSidecarDrainDecisionText physicalPendingText = function
            | MinimalSidecarActivelyDrainingTySidecar -> "initiate_prefetch_or_replay_driver_drain"
            | MinimalSidecarLedgerDesyncInvalidatesLease -> "ledger_desync_pierces_sidecar_grace"
            | MinimalSidecarStackFenceShadowTimeoutPierced -> "shadow_alt_timeout_pierces_blocked_repeat_cap_stack_fence_yield"
            | MinimalSidecarParentReplayCycleBreakPoisonShadowTimeoutPierced -> "shadow_alt_timeout_pierces_parent_replay_cycle_break_poison_repeat_cap_probation"
            | MinimalSidecarParentContinuationDeferredChildShadowTimeoutPierced -> "shadow_alt_timeout_pierces_parent_continuation_deferred_child_bridge_tail"
            | MinimalSidecarSemanticStaleRetargetShadowTimeoutPierced -> "shadow_alt_timeout_pierces_semantic_stale_retarget_missing_prefetch_cycle_break"
            | MinimalSidecarDynamicRecordKeyBridgeTailShadowTimeoutPierced -> "shadow_alt_timeout_pierces_dynamic_record_key_bridge_tail_weak_pending_active_root"
            | MinimalSidecarCooperativeYieldShadowTimerPierced -> "shadow_alt_timeout_pierces_cooperative_yield_thrash"
            | MinimalSidecarIdleCrossKindActiveTySidecarShadowTimeoutPierced -> "shadow_alt_timeout_pierces_idle_cross_kind_active_ty_sidecar"
            | MinimalSidecarIdleCrossKindWithActiveTySidecarDrain -> "sidecar_drain_owns_idle_cross_kind_continuation_window"
            | MinimalSidecarIfUnknownReturnConditionShadowTimeoutPierced -> "if_unknown_return_branch_probe_or_fail_closed_after_shadow_timeout"
            | MinimalSidecarIfUnknownReturnAbsentShadowTimeoutPierced -> "if_unknown_return_absent_sidecar_branch_obligation_or_fail_closed_after_shadow_timeout"
            | MinimalSidecarShadowAltTimeoutLeaseExpired -> "shadow_alt_timeout_pierces_legacy_sidecar_grace"
