            | MinimalSidecarIdleCrossKindActiveTySidecarShadowTimeoutPierced
            | MinimalSidecarIfUnknownReturnConditionShadowTimeoutPierced
            | MinimalSidecarIfUnknownReturnAbsentShadowTimeoutPierced -> true
            | _ -> false

        let minimalSidecarDrainIndicatesSidecarOrDrain = function
