            | _ -> false

        let minimalSidecarDrainIsActivelyDraining = function
            | MinimalSidecarIdleCrossKindWithActiveTySidecarDrain
            | MinimalSidecarActivelyDrainingTySidecar -> true
            | _ -> false

        let minimalSidecarDrainIsLeaseExpired = function
            | MinimalSidecarShadowAltTimeoutLeaseExpired -> true
            | _ -> false

        type CpuQuietNoDeltaSpinDecisionId =
            | CpuQuietNoDeltaSpinNone
            | CpuQuietNoDeltaSpinSidecarActiveNoDelta
            | CpuQuietNoDeltaSpinSidecarPhysicalAbsent
            | CpuQuietNoDeltaSpinFrozenDriverRootPhysicalAbsent

        let cpuQuietNoDeltaSpinDecisionText = function
            | CpuQuietNoDeltaSpinNone -> "none"
            | CpuQuietNoDeltaSpinSidecarActiveNoDelta -> "sidecar_active_cpu_quiet_no_delta"
            | CpuQuietNoDeltaSpinSidecarPhysicalAbsent -> "sidecar_physical_pending_absent_cpu_quiet_no_delta"
            | CpuQuietNoDeltaSpinFrozenDriverRootPhysicalAbsent -> "frozen_driver_root_physical_pending_absent_cpu_quiet_no_delta"

        let cpuQuietNoDeltaSpinDecisionIsAbort = function
            | CpuQuietNoDeltaSpinSidecarActiveNoDelta
            | CpuQuietNoDeltaSpinSidecarPhysicalAbsent
            | CpuQuietNoDeltaSpinFrozenDriverRootPhysicalAbsent -> true
            | CpuQuietNoDeltaSpinNone -> false

        let cpuQuietNoDeltaSpinDecisionFor hasTarget hasPhysicalPending hasSidecarEvidence hasLiveReplay noFreshDelta noWorkS noWorkPokes rescueCompleted cpuPct cpuMachinePct =
            let cpuQuiet =
                cpuPct >= 0.0
                && cpuPct < 18.0
                && cpuMachinePct >= 0.0
                && cpuMachinePct < 5.0
            let maturedByClock =
                noWorkS >= 60L
                && noWorkPokes >= 10L
                && rescueCompleted >= 8L
            let maturedByRescueSaturation =
                // MIGRATION: minimal heartbeat can keep no_work_s near zero by
                // crediting tiny replay/root drips while the same sidecar row has
                // already completed 160+ rescues.  Treat that as lease exhaustion
                // when CPU is quiet and the shadow data says no fresh delta.
                rescueCompleted >= 160L
            let matured =
                (maturedByClock || maturedByRescueSaturation)
                && cpuQuiet
                && noFreshDelta
                && hasLiveReplay
            if not matured then CpuQuietNoDeltaSpinNone
            elif hasTarget && hasSidecarEvidence && not hasPhysicalPending then CpuQuietNoDeltaSpinSidecarPhysicalAbsent
            elif hasTarget && hasSidecarEvidence && hasPhysicalPending then CpuQuietNoDeltaSpinSidecarActiveNoDelta
            elif hasTarget && not hasPhysicalPending then CpuQuietNoDeltaSpinFrozenDriverRootPhysicalAbsent
            else CpuQuietNoDeltaSpinNone

