            | NoWorkGateDecisionHoldoffHardSemanticQuarantineLiveTail
            | NoWorkGateDecisionForceIdleCrossKindSidecarDirectEval
            | NoWorkGateDecisionHoldoffIdleCrossKindRichStaleRetry
            | NoWorkGateDecisionAbortIdleCrossKindRetryExhausted -> true
            | _ -> false

