            | UnderutilizedReplayDecisionNone -> "none"
            | UnderutilizedReplayDecisionAbortReady -> "abort_ready"
            | UnderutilizedReplayDecisionAbortCpuQuietNoDeltaSpin -> "abort_cpu_quiet_no_delta_spin"
