        type NoWorkMidGraphStallWindowId =
            | NoWorkMidGraphStallBeforeWindow
            | NoWorkMidGraphStallGraceWindow
            | NoWorkMidGraphStallExpired

        let noWorkMidGraphStallWindowFor stallS =
            if stallS < 30L then NoWorkMidGraphStallBeforeWindow
            elif stallS < 90L then NoWorkMidGraphStallGraceWindow
            else NoWorkMidGraphStallExpired

        let noWorkMidGraphStallWindowIsGrace = function
            | NoWorkMidGraphStallGraceWindow -> true
            | _ -> false

        let noWorkMidGraphStallWindowText = function
            | NoWorkMidGraphStallBeforeWindow -> "before_window"
            | NoWorkMidGraphStallGraceWindow -> "grace_window"
            | NoWorkMidGraphStallExpired -> "expired"

        // MIGRATION: 1182 proved the metronome can now abort fail-closed at 95%,
        // but repeated gate-busy no-work rescues only accumulated evidence.  Keep
        // the gate-busy response typed and bounded: after several busy probes,
        // request a replay-driver tick from outside the hot path before accepting
        // the no-work abort frontier.
        type NoWorkGateBusyRescueDecisionId =
            | NoWorkGateBusyObserveOnly
            | NoWorkGateBusyScheduleReplayTick
            | NoWorkGateBusyScheduleSparseReplayTick
            | NoWorkGateBusyAbortEvidenceOnly

        let noWorkGateBusyRescueDecisionText = function
            | NoWorkGateBusyObserveOnly -> "observe_only"
            | NoWorkGateBusyScheduleReplayTick -> "schedule_replay_tick"
            | NoWorkGateBusyScheduleSparseReplayTick -> "schedule_sparse_replay_tick"
            | NoWorkGateBusyAbortEvidenceOnly -> "abort_evidence_only"

        let noWorkGateBusyRescueDecisionFor gateBusySeen =
            // MIGRATION: 1259 ended with q=3/a=4 and 80% gate-busy rescues.
            // A gate-busy probe is evidence that the worker gate is occupied, not proof that
            // the final replay tail has been physically drained.  Keep issuing bounded replay
            // ticks through the final 96-probe window before accepting abort evidence.
            if gateBusySeen <= 1L then NoWorkGateBusyObserveOnly
            elif gateBusySeen <= 64L && gateBusySeen % 2L = 1L then NoWorkGateBusyScheduleReplayTick
            elif gateBusySeen <= 64L && gateBusySeen % 4L = 0L then NoWorkGateBusyScheduleSparseReplayTick
            elif gateBusySeen < 96L then NoWorkGateBusyScheduleReplayTick
            elif gateBusySeen < 160L && gateBusySeen % 3L = 0L then
                // MIGRATION: 1326 ended with gate_busy=119 while root=30/terminal=54
                // still described a replay-obligation tail.  Keep a bounded sparse
                // driver tick window instead of turning those probes into inert
                // abort evidence too early.
                NoWorkGateBusyScheduleSparseReplayTick
            elif gateBusySeen < 160L then NoWorkGateBusyScheduleReplayTick
            else NoWorkGateBusyAbortEvidenceOnly

        // MIGRATION: replay-obligation deferred/cross-kind drains are not the same
        // terminal as an inert terminal flood.  Historical runtime reached q/a/p=98/4/2
        // with semantic_replay_obligation_deferred and a hot cross-kind node; the
        // old 45s grace cliff still let terminal_flood_quiet_abort win.  Keep the
        // window typed so extending it cannot silently mask unrelated no-work aborts.
        type ReplayObligationDeferredNoWorkWindowId =
            | ReplayObligationDeferredNoAuthority
            | ReplayObligationDeferredInitialDrainGrace
            | ReplayObligationDeferredExtendedLiveTailGrace
            | ReplayObligationDeferredExpired

        let replayObligationDeferredNoWorkWindowText = function
            | ReplayObligationDeferredNoAuthority -> "no_authority"
            | ReplayObligationDeferredInitialDrainGrace -> "initial_drain_grace"
            | ReplayObligationDeferredExtendedLiveTailGrace -> "extended_live_tail_grace"
            | ReplayObligationDeferredExpired -> "expired"

        let replayObligationDeferredNoWorkWindowFor noWorkS noWorkPokes rescueCompleted rescueGateBusy _progressPct rootComplete terminalSignals replayProgress replayObligationReceiptSeen matureTerminalReplayAuthority =
            // MIGRATION: display progress is no longer a scheduler-control input.
            // This legacy adapter now keys only on typed receipt/counter evidence;
            // the follow-up migration will replace the counter tuple with TerminalFlowProgressPhase.
            let hasReplayObligationAuthority =
                (rootComplete >= 24L || terminalSignals >= 48L)
                && (terminalSignals >= 48L || rootComplete >= 30L)
                && replayProgress >= 1000L
                && (replayObligationReceiptSeen || matureTerminalReplayAuthority)
            if not hasReplayObligationAuthority then ReplayObligationDeferredNoAuthority
            elif noWorkS < 45L && noWorkPokes < 12L && rescueCompleted < 96L && rescueGateBusy < 96L then
                ReplayObligationDeferredInitialDrainGrace
            elif noWorkS < 150L && noWorkPokes < 32L && rescueCompleted < 256L && rescueGateBusy < 128L then
                ReplayObligationDeferredExtendedLiveTailGrace
            else ReplayObligationDeferredExpired

        // MIGRATION: 1178 proved the rich heartbeat can get stuck busy after the
        // hot-frontier cap extends to 90s.  Keep the 1s metronome authoritative:
        // if no sampled/replay/root/terminal deltas move after many successful
        // rescue pokes, emit a typed no-work saturation abort instead of waiting
        // for manual Ctrl-C.
        type MetronomeNoWorkSaturationDecisionId =
