            | MetronomeStallSemanticParentContinuationCycleDeferred
            | MetronomeStallSemanticParentReplayCycleBreakPoisoned
            | MetronomeStallHardPoisonObligation

        type MetronomeNativeCallbackStallAtomFamilyId =
            | MetronomeStallAtomApplySpine
            | MetronomeStallAtomParentReplayStatusPreserved
            | MetronomeStallAtomCacheHandoff
            | MetronomeStallAtomNoRootBudget
            | MetronomeStallAtomDynamicRecordKeyBridge
            | MetronomeStallAtomBridgeTail
            | MetronomeStallAtomParentReplay
            | MetronomeStallAtomCycleBreak
            | MetronomeStallAtomPoison
            | MetronomeStallAtomStaleRetarget
            | MetronomeStallAtomRootComplete
            | MetronomeStallAtomDeferredChild
            | MetronomeStallAtomIdleCrossKind
            | MetronomeStallAtomActiveTySidecar
            | MetronomeStallAtomStackFence
            | MetronomeStallAtomParentContinuation
            | MetronomeStallAtomHardPoisonObligation

        let private metronomeNativeCallbackStallAtomFamilies (atom:string) =
            let segments =
                if System.String.IsNullOrWhiteSpace atom then [||]
                else atom.Split([| '_' |], System.StringSplitOptions.RemoveEmptyEntries)
            let begins (expected:string array) =
                segments.Length >= expected.Length
                && (expected |> Array.mapi (fun index segment -> segments.[index] = segment) |> Array.forall id)
            let ends (expected:string array) =
                let offset = segments.Length - expected.Length
                offset >= 0
                && (expected |> Array.mapi (fun index segment -> segments.[offset + index] = segment) |> Array.forall id)
            [ if begins [| "apply"; "spine" |]
                 || begins [| "semantic"; "apply"; "spine" |]
                 || begins [| "term"; "apply"; "spine" |] then MetronomeStallAtomApplySpine
              if begins [| "parent"; "replay"; "status"; "preserved" |] then MetronomeStallAtomParentReplayStatusPreserved
              if begins [| "cache"; "handoff" |] then MetronomeStallAtomCacheHandoff
              if begins [| "no"; "root"; "budget" |] then MetronomeStallAtomNoRootBudget
              if begins [| "dynamic"; "record"; "key"; "bridge" |] then MetronomeStallAtomDynamicRecordKeyBridge
              if begins [| "bridge"; "tail" |] then MetronomeStallAtomBridgeTail
              if begins [| "parent"; "replay" |] then MetronomeStallAtomParentReplay
              if begins [| "cycle"; "break" |]
                 || begins [| "parent"; "replay"; "cycle"; "break" |]
                 || ends [| "cycle"; "break" |]
                 || ends [| "cycle"; "break"; "poison" |]
                 || ends [| "cycle"; "break"; "poisoned" |] then MetronomeStallAtomCycleBreak
              if begins [| "poison" |]
                 || begins [| "hard"; "poison" |]
                 || ends [| "poison" |]
                 || ends [| "poisoned" |] then MetronomeStallAtomPoison
              if begins [| "stale"; "retarget" |]
                 || begins [| "semantic"; "stale"; "retarget" |] then MetronomeStallAtomStaleRetarget
              if begins [| "root"; "complete" |]
                 || begins [| "semantic"; "root"; "complete" |] then MetronomeStallAtomRootComplete
              if begins [| "deferred"; "child" |] then MetronomeStallAtomDeferredChild
              if begins [| "idle"; "cross"; "kind" |] then MetronomeStallAtomIdleCrossKind
              if begins [| "active"; "ty"; "sidecar" |] then MetronomeStallAtomActiveTySidecar
              if begins [| "stack"; "fence" |] then MetronomeStallAtomStackFence
              if begins [| "parent"; "continuation" |] then MetronomeStallAtomParentContinuation
              if begins [| "hard"; "poison"; "obligation" |] then MetronomeStallAtomHardPoisonObligation ]
            |> Set.ofList

        let metronomeNativeCallbackStallSignals (text:string) =
            let safe =
                if System.String.IsNullOrWhiteSpace text then ""
                else text.ToLowerInvariant()
            let atoms =
                safe.Split(
                    [| '|'; ':'; ';'; ','; ' '; '='; '['; ']'; '('; ')'; '/' |],
                    System.StringSplitOptions.RemoveEmptyEntries)
                |> Set.ofArray
            let has atom = Set.contains atom atoms
            let families =
                atoms
                |> Seq.collect (metronomeNativeCallbackStallAtomFamilies >> Set.toSeq)
                |> Set.ofSeq
            let hasFamily family = Set.contains family families
            [ if hasFamily MetronomeStallAtomApplySpine then MetronomeStallApplySpine
              if hasFamily MetronomeStallAtomParentReplayStatusPreserved then MetronomeStallParentReplayStatusPreserved
              if has "parent_replay_status_preserved_repeat" then MetronomeStallParentReplayStatusPreservedRepeat
              if hasFamily MetronomeStallAtomCacheHandoff then MetronomeStallCacheHandoff
              if hasFamily MetronomeStallAtomNoRootBudget then MetronomeStallNoRootBudget
              if hasFamily MetronomeStallAtomDynamicRecordKeyBridge then MetronomeStallDynamicRecordKeyBridge
              if hasFamily MetronomeStallAtomBridgeTail then MetronomeStallBridgeTail
              if hasFamily MetronomeStallAtomParentReplay then MetronomeStallParentReplay
              if hasFamily MetronomeStallAtomCycleBreak then MetronomeStallCycleBreak
              if hasFamily MetronomeStallAtomPoison then MetronomeStallPoison
              if hasFamily MetronomeStallAtomStaleRetarget then MetronomeStallStaleRetarget
              if hasFamily MetronomeStallAtomRootComplete then MetronomeStallRootComplete
              if hasFamily MetronomeStallAtomDeferredChild then MetronomeStallDeferredChild
              if hasFamily MetronomeStallAtomIdleCrossKind then MetronomeStallIdleCrossKind
              if hasFamily MetronomeStallAtomActiveTySidecar then MetronomeStallActiveTySidecar
              if hasFamily MetronomeStallAtomStackFence then MetronomeStallStackFence
              if hasFamily MetronomeStallAtomParentContinuation then MetronomeStallParentContinuation
              if has "semantic_parent_continuation_cycle_deferred" then MetronomeStallSemanticParentContinuationCycleDeferred
              if has "semantic_parent_replay_cycle_break_poisoned" then MetronomeStallSemanticParentReplayCycleBreakPoisoned
              if hasFamily MetronomeStallAtomHardPoisonObligation then MetronomeStallHardPoisonObligation ]
            |> Set.ofList

        let metronomeNativeCallbackStallSignalPresent signal signals =
            Set.contains signal signals

        let metronomeTerminalAuthorityPayloadText = function
            | MetronomeTerminalObservedPinnedAuthority -> "MetronomeObservedPinnedAuthority"
            | MetronomeTerminalApplySpineStoreDirect -> "ApplySpineStoreDirect"
            | MetronomeTerminalIdleCrossKindActiveTySidecarTimeout -> "IdleCrossKindActiveTySidecarTimeout"
            | MetronomeTerminalDynamicRecordKeyBridgeTailPierce -> "DynamicRecordKeyBridgeTailPierce"
            | MetronomeTerminalParentReplayCycleBreakPoisonShadowTimeoutPierce -> "ParentReplayCycleBreakPoisonShadowTimeoutPierce"
            | MetronomeTerminalNoRootBudgetParentReplayImmediateFill -> "NoRootBudgetParentReplayImmediateFill"
            | MetronomeTerminalSemanticStaleRetargetShadowTimeoutPierce -> "SemanticStaleRetargetShadowTimeoutPierce"
            | MetronomeTerminalStackFenceShadowTimeoutPierce -> "StackFenceShadowTimeoutPierce"
            | MetronomeTerminalDeferredChildShadowTimeout -> "ShadowTimeoutDeferredChild"
            | MetronomeTerminalParentContinuationCycleShadowTimeout -> "ParentContinuationCycleShadowTimeout"
            | MetronomeTerminalPendingGraphCommittedTerminal -> "PendingGraphCommittedTerminal"
            | MetronomeTerminalParentReplayStatusPreservedCacheHandoff -> "ParentReplayStatusPreservedCacheHandoff"

        let metronomeTerminalAuthorityIvarRegistryText = function
            | MetronomeTerminalObservedPinnedAuthority -> "metronome_terminal_authority:observed_pinned_terminal_payload"
            | MetronomeTerminalApplySpineStoreDirect -> "metronome_terminal_authority:apply_spine_store_direct"
            | MetronomeTerminalIdleCrossKindActiveTySidecarTimeout -> "metronome_terminal_authority:idle_cross_kind_terminal_commit"
            | MetronomeTerminalDynamicRecordKeyBridgeTailPierce -> "metronome_terminal_authority:dynamic_record_key_bridge_commit"
            | MetronomeTerminalParentReplayCycleBreakPoisonShadowTimeoutPierce -> "metronome_terminal_authority:parent_replay_poison_live_tail"
            | MetronomeTerminalNoRootBudgetParentReplayImmediateFill -> "metronome_terminal_authority:no_root_budget_parent_replay_immediate_fill"
            | MetronomeTerminalSemanticStaleRetargetShadowTimeoutPierce -> "metronome_terminal_authority:semantic_stale_retarget"
            | MetronomeTerminalStackFenceShadowTimeoutPierce -> "metronome_terminal_authority:stack_fence"
            | MetronomeTerminalDeferredChildShadowTimeout -> "metronome_terminal_authority:deferred_child"
            | MetronomeTerminalParentContinuationCycleShadowTimeout -> "metronome_terminal_authority:parent_continuation_cycle"
            | MetronomeTerminalPendingGraphCommittedTerminal -> "metronome_terminal_authority:pending_graph_committed_terminal"
            | MetronomeTerminalParentReplayStatusPreservedCacheHandoff -> "metronome_terminal_authority:parent_replay_status_preserved_cache_handoff"

        let metronomeTerminalAuthorityWitnessKindText = function
            | MetronomeTerminalObservedPinnedAuthority -> "MetronomeTerminalAuthorityProof"
            | MetronomeTerminalApplySpineStoreDirect -> "ApplySpineStoreDirectProof"
            | MetronomeTerminalIdleCrossKindActiveTySidecarTimeout -> "IdleCrossKindTerminalCommitProof"
            | MetronomeTerminalDynamicRecordKeyBridgeTailPierce -> "DynamicRecordKeyBridgeCommitProof"
            | MetronomeTerminalParentReplayCycleBreakPoisonShadowTimeoutPierce -> "ParentReplayPoisonLiveTailProof"
            | MetronomeTerminalNoRootBudgetParentReplayImmediateFill -> "NoRootBudgetParentReplayImmediateFillProof"
            | MetronomeTerminalSemanticStaleRetargetShadowTimeoutPierce -> "SemanticStaleRetargetProof"
            | MetronomeTerminalStackFenceShadowTimeoutPierce -> "StackFenceShadowTimeoutProof"
            | MetronomeTerminalDeferredChildShadowTimeout -> "DeferredChildShadowTimeoutProof"
            | MetronomeTerminalParentContinuationCycleShadowTimeout -> "ParentContinuationCycleShadowTimeoutProof"
            | MetronomeTerminalPendingGraphCommittedTerminal -> "TerminalPayloadProof"
            | MetronomeTerminalParentReplayStatusPreservedCacheHandoff -> "ParentReplayStatusPreservedCacheHandoffProof"

        let metronomeTerminalAuthorityResolutionEdgeText = function
            | MetronomeTerminalObservedPinnedAuthority -> "MetronomeObservedPinnedAuthority->IVar<ParentContinuationImmediateFill>"
            | MetronomeTerminalApplySpineStoreDirect -> "ApplySpineMissingDirectValue->IVar<ApplySpineStoreDirect>"
            | MetronomeTerminalIdleCrossKindActiveTySidecarTimeout -> "MetronomeIdleCrossKindAuthority->IVar<IdleCrossKindTerminalCommit>"
            | MetronomeTerminalDynamicRecordKeyBridgeTailPierce -> "MetronomeDynamicRecordKeyBridgeAuthority->IVar<DynamicRecordKeyBridgeCommit>"
            | MetronomeTerminalParentReplayCycleBreakPoisonShadowTimeoutPierce -> "MetronomeParentReplayPoisonAuthority->IVar<ParentReplayPoisonLiveTail>"
            | MetronomeTerminalNoRootBudgetParentReplayImmediateFill -> "MetronomeNoRootBudgetAuthority->IVar<NoRootBudgetParentReplayImmediateFill>"
            | MetronomeTerminalSemanticStaleRetargetShadowTimeoutPierce -> "MetronomeSemanticStaleRetargetAuthority->IVar<SemanticStaleRetarget>"
            | MetronomeTerminalStackFenceShadowTimeoutPierce -> "MetronomeStackFenceAuthority->IVar<StackFenceShadowTimeout>"
            | MetronomeTerminalDeferredChildShadowTimeout -> "MetronomeDeferredChildAuthority->IVar<DeferredChildShadowTimeout>"
            | MetronomeTerminalParentContinuationCycleShadowTimeout -> "MetronomeParentContinuationCycleAuthority->IVar<ParentContinuationCycleShadowTimeout>"
            | MetronomeTerminalPendingGraphCommittedTerminal -> "MetronomePendingGraphAuthority->IVar<TerminalPayload>"
            | MetronomeTerminalParentReplayStatusPreservedCacheHandoff -> "MetronomeParentReplayStatusPreservedCacheHandoff->IVar<ParentReplayStatusPreservedCacheHandoff>"

        let metronomeTerminalAuthorityFillStrategyText = function
            | MetronomeTerminalObservedPinnedAuthority -> "fill_parent_continuation_ivar_immediately_from_metronome_observed_pinned_authority"
            | MetronomeTerminalApplySpineStoreDirect -> "fill_apply_spine_store_direct_ivar_then_execute_native_apply_spine_store"
            | MetronomeTerminalIdleCrossKindActiveTySidecarTimeout -> "fill_idle_cross_kind_terminal_ivar_immediately_before_ejp0024_abort"
            | MetronomeTerminalDynamicRecordKeyBridgeTailPierce -> "fill_dynamic_record_key_bridge_ivar_immediately_before_ejp0024_abort"
            | MetronomeTerminalParentReplayCycleBreakPoisonShadowTimeoutPierce -> "fill_parent_replay_poison_live_tail_ivar_immediately_before_ejp0024_abort"
            | MetronomeTerminalNoRootBudgetParentReplayImmediateFill -> "fill_no_root_budget_parent_replay_ivar_then_materialize_parent_job_bind"
            | MetronomeTerminalSemanticStaleRetargetShadowTimeoutPierce -> "fill_semantic_stale_retarget_ivar_immediately_before_ejp0024_abort"
            | MetronomeTerminalStackFenceShadowTimeoutPierce -> "fill_stack_fence_shadow_timeout_ivar_immediately_before_ejp0024_abort"
            | MetronomeTerminalDeferredChildShadowTimeout -> "fill_deferred_child_shadow_timeout_ivar_immediately_before_ejp0024_abort"
            | MetronomeTerminalParentContinuationCycleShadowTimeout -> "fill_parent_continuation_cycle_shadow_timeout_ivar_immediately_before_ejp0024_abort"
            | MetronomeTerminalPendingGraphCommittedTerminal -> "dispatch_terminal_payload_before_legacy_metronome_exit"
            | MetronomeTerminalParentReplayStatusPreservedCacheHandoff -> "fill_parent_replay_status_preserved_cache_handoff_ivar_then_execute_native_direct_eval"

        type MetronomeTerminalConsumerExecutionDecision =
            | MetronomeTerminalConsumerObserverOnly
            | MetronomeTerminalConsumerPublishBuildOk of terminalReceiptId:string * fillKey:string * reason:CompilerKernelV2.OperationalReasonId

        [<StructuralEquality; NoComparison>]
        type MetronomeTerminalConsumerRequestIdentity = private {
            terminalReceiptRef : CompilerIdentityKernel.ContentDigest
            fillRef : CompilerIdentityKernel.ContentDigest
        }

        let private metronomeTerminalConsumerRequestIdentityFor terminalReceiptId fillKey : MetronomeTerminalConsumerRequestIdentity =
            { terminalReceiptRef = CompilerIdentityKernel.ContentDigest.ofText "metronome-terminal-receipt" terminalReceiptId
              fillRef = CompilerIdentityKernel.ContentDigest.ofText "metronome-terminal-fill" fillKey }

        let private metronomeTerminalConsumerRequestRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<MetronomeTerminalConsumerRequestIdentity,byte>()

        let metronomeTerminalConsumerExecutionDecision
            (runId:string)
            authority
            (progressPct:float)
            (rootReceiptCount:int64)
            (pendingDepth:int64)
            (sampledDelta:int64)
            (replayDelta:int64)
            (terminalDelta:int64)
            (noWorkSeconds:int64) =
            let materialClosureProven =
                progressPct >= 100.0
                && rootReceiptCount > 0L
                && pendingDepth = 0L
                && sampledDelta = 0L
                && replayDelta = 0L
                && terminalDelta = 0L
                && noWorkSeconds >= 2L
            if materialClosureProven then
                let authorityKey = metronomeTerminalAuthorityIvarRegistryText authority
                MetronomeTerminalConsumerPublishBuildOk(
                    sprintf "metronome-terminal:%s:%s" runId authorityKey,
                    sprintf "metronome-fill:%s:%s" runId authorityKey,
                    CompilerKernelV2.OperationalReasonIdOps.create "TerminalBuildOk(metronome_materialized_terminal_consumer_ready)")
            else
                MetronomeTerminalConsumerObserverOnly

        let metronomeTerminalConsumerExecutionDecisionText = function
            | MetronomeTerminalConsumerObserverOnly -> "ObserverOnly"
            | MetronomeTerminalConsumerPublishBuildOk _ -> "PublishBuildOk"

        // Wake Graph binding streak. The prior projection exposed wake graph
        // categories, but the assessment correctly noted that a category string
        // can still hide an IVar island.  These helpers now derive a structural
        // owner/child edge from the hot replay key whenever possible and render
        // the exact continuation listeners/count that should be woken by fill.
        type NativeWakeTargetFieldId =
            | NativeWakeTargetChild
            | NativeWakeTargetNode
            | NativeWakeTargetOwner
            | NativeWakeTargetOtherField of key:string

        [<Struct>]
        type NativeWakeTargetFields = private {
            Child : string option
            Node : string option
            Owner : string option
            HashSuffix : string option
        }

        module NativeWakeTargetFieldParser =
            let private delimiters = [|','; '('; ')'; '['; ']'; '|'; ';'; ' '; '\t'; '\r'; '\n'|]

            let private fieldId (key:string) =
                match key.Trim().ToLowerInvariant() with
                | "child" -> NativeWakeTargetChild
                | "node" -> NativeWakeTargetNode
                | "owner" -> NativeWakeTargetOwner
                | other -> NativeWakeTargetOtherField other

            let private splitKeyValue (token:string) =
                let mutable separator = -1
                let mutable index = 0
                while separator < 0 && index < token.Length do
                    if token.[index] = '=' then separator <- index
                    index <- index + 1
                if separator <= 0 || separator >= token.Length - 1 then None
                else Some(fieldId (token.Substring(0, separator)), token.Substring(separator + 1))

            let parse (target:string) =
                let safe = if System.String.IsNullOrWhiteSpace target then "frontier_unknown" else target
                let mutable child = None
                let mutable node = None
                let mutable owner = None
                for token in safe.Split(delimiters, System.StringSplitOptions.RemoveEmptyEntries) do
                    match splitKeyValue token with
                    | Some(NativeWakeTargetChild, value) when child.IsNone -> child <- Some value
                    | Some(NativeWakeTargetNode, value) when node.IsNone -> node <- Some value
                    | Some(NativeWakeTargetOwner, value) when owner.IsNone -> owner <- Some value
                    | _ -> ()
                let mutable hashAt = -1
                for index = 0 to safe.Length - 1 do
                    if safe.[index] = '#' then hashAt <- index
                let hashSuffix =
                    if hashAt >= 0 && hashAt + 1 < safe.Length then Some(safe.Substring(hashAt + 1))
                    else None
                { Child = child; Node = node; Owner = owner; HashSuffix = hashSuffix }

            let value field fields =
                match field with
                | NativeWakeTargetChild -> fields.Child
                | NativeWakeTargetNode -> fields.Node
                | NativeWakeTargetOwner -> fields.Owner
                | NativeWakeTargetOtherField _ -> None

            let hashSuffix fields = fields.HashSuffix

        let private wakeSanitizeTargetKey (targetKey: string) =
            if System.String.IsNullOrWhiteSpace targetKey then "frontier_unknown"
            else targetKey.Replace("\"", "'").Replace("\\", "/")

        let private wakeTargetFields (targetKey:string) =
            wakeSanitizeTargetKey targetKey
            |> NativeWakeTargetFieldParser.parse

        let private wakeTargetFieldText field fields =
            NativeWakeTargetFieldParser.value field fields
            |> Option.defaultValue ""

        let private wakeTargetNodeToken authority targetKey =
            let fields = wakeTargetFields targetKey
            let child = wakeTargetFieldText NativeWakeTargetChild fields
            let node = wakeTargetFieldText NativeWakeTargetNode fields
            let owner = wakeTargetFieldText NativeWakeTargetOwner fields
            let suffix = NativeWakeTargetFieldParser.hashSuffix fields |> Option.defaultValue ""
            let structural = if child <> "" then child elif node <> "" then node elif owner <> "" then owner elif suffix <> "" then suffix else ""
            if structural <> "" then structural
            else
                let raw = metronomeTerminalAuthorityIvarRegistryText authority + "|" + wakeSanitizeTargetKey targetKey
                CompilerIdentityKernel.ContentDigest.ofText "wake-target-node" raw
                |> CompilerIdentityKernel.ContentDigest.text

        let private wakeTopologyEdgeText authority targetKey =
            let target = wakeSanitizeTargetKey targetKey
            let fields = wakeTargetFields targetKey
            let owner = wakeTargetFieldText NativeWakeTargetOwner fields
            let child = wakeTargetFieldText NativeWakeTargetChild fields
            let node = wakeTargetFieldText NativeWakeTargetNode fields
            let targetNode = wakeTargetNodeToken authority targetKey
            let ownerText =
                if owner <> "" then owner
                elif target <> "" && target <> "frontier_unknown" then target
                elif node <> "" then node
                elif targetNode <> "" then targetNode
                else "UNKNOWN_OWNER"
            let childText = if child <> "" then child else targetNode
            "owner=" + ownerText + "->child=" + childText + "|target=" + target

        let metronomeTerminalAuthorityStructuralNodeIdText authority targetKey =
            "IVar_for_Node_" + wakeTargetNodeToken authority targetKey

        let metronomeTerminalAuthorityPromiseIdText authority targetKey =
            "Promise_for_Node_" + wakeTargetNodeToken authority targetKey

        let metronomeTerminalAuthorityContinuationBindingTargetsText authority targetKey =
            let edge = wakeTopologyEdgeText authority targetKey
            match authority with
            | MetronomeTerminalSemanticStaleRetargetShadowTimeoutPierce -> "[RootCompleteLiveReplay(" + edge + ");IdleCrossKindSidecarDrain(" + edge + ");ParentContinuationCell(" + edge + ")]"
            | MetronomeTerminalDynamicRecordKeyBridgeTailPierce -> "[DynamicBridgeParentContinuation(" + edge + ");DynamicJoinApplyReplay(" + edge + ");WriterlessQueueDrain(" + edge + ")]"
            | MetronomeTerminalIdleCrossKindActiveTySidecarTimeout -> "[TySidecarDrainContinuation(" + edge + ");CrossKindSiblingReplay(" + edge + ");ParentContinuationCell(" + edge + ")]"
            | MetronomeTerminalParentReplayCycleBreakPoisonShadowTimeoutPierce -> "[ParentReplayPoisonContinuation(" + edge + ");CycleBreakConsumer(" + edge + ")]"
            | MetronomeTerminalNoRootBudgetParentReplayImmediateFill -> "[NoRootBudgetParentReplayJobBind(" + edge + ");ParentReplayCycleBreakConsumer(" + edge + ");ContinuationCellWake(" + edge + ")]"
            | MetronomeTerminalStackFenceShadowTimeoutPierce -> "[StackFenceReplayContinuation(" + edge + ");PrefetchPierceConsumer(" + edge + ")]"
            | MetronomeTerminalDeferredChildShadowTimeout -> "[DeferredChildContinuation(" + edge + ");ParentPhase2Replay(" + edge + ")]"
            | MetronomeTerminalParentContinuationCycleShadowTimeout -> "[ParentContinuationCycleConsumer(" + edge + ")]"
            | MetronomeTerminalApplySpineStoreDirect -> "[ApplySpineStoreDirectConsumer(" + edge + ");ParentContinuationCell(" + edge + ");PendingGraphTerminalConsumer(" + edge + ")]"
            | MetronomeTerminalObservedPinnedAuthority -> "[ObservedPinnedParentContinuation(" + edge + ")]"
            | MetronomeTerminalPendingGraphCommittedTerminal -> "[CooperativeReplayNativeBindConsumer(" + edge + ");PendingGraphCommittedTerminalConsumer(" + edge + ");PendingGraphTerminalConsumer(" + edge + ")]"
            | MetronomeTerminalParentReplayStatusPreservedCacheHandoff -> "[ParentReplayStatusPreservedCacheHandoffConsumer(" + edge + ");CooperativeReplayNativeBindConsumer(" + edge + ");ParentContinuationCell(" + edge + ")]"

        type NativeWakeBindingStateId =
            | NativeWakeBoundParentContinuationTargets
            | NativeWakeBoundParentContinuationNoDeltaStarved
            | NativeWakePartialOwnerIdentityParentBindProbeRequired
            | NativeWakeUnboundTopologicalIsland

        let nativeWakeBindingStateText = function
            | NativeWakeBoundParentContinuationTargets -> "bound_parent_continuation_targets"
            | NativeWakeBoundParentContinuationNoDeltaStarved -> "bound_parent_continuation_targets_but_no_work_delta"
            | NativeWakePartialOwnerIdentityParentBindProbeRequired -> "partial_owner_identity_parent_bind_probe_required"
            | NativeWakeUnboundTopologicalIsland -> "unbound_topological_island"

        let nativeWakeFateText = function
            | NativeWakeBoundParentContinuationTargets -> "native_fill_wakes_parent_job_bind_cascade"
            | NativeWakeBoundParentContinuationNoDeltaStarved -> "native_fill_wake_edge_bound_but_parent_cascade_no_delta"
            | NativeWakePartialOwnerIdentityParentBindProbeRequired -> "native_fill_requires_parent_binding_identity_repair"
            | NativeWakeUnboundTopologicalIsland -> "native_fill_executed_but_no_parent_job_bind_listener"

        type NativeWakeRepairActionId =
            | NativeWakeNoRepairNeeded
            | NativeWakeGraftActiveParentBindingProbe
            | NativeWakeMaterializeBoundNoDeltaParentJobBind
            | NativeWakeMaterializeMissingParentJobBind

        let nativeWakeRepairActionText = function
            | NativeWakeNoRepairNeeded -> "parent_promise_binding_resolved_from_wake_edge"
            | NativeWakeGraftActiveParentBindingProbe -> "graft_active_worker_as_parent_promise_listener"
            | NativeWakeMaterializeBoundNoDeltaParentJobBind -> "materialize_bound_wake_edge_parent_job_bind_before_next_tick"
            | NativeWakeMaterializeMissingParentJobBind -> "materialize_missing_parent_job_bind_listener"

        let nativeWakeRepairActionFor bindingState activeParentProbePresent =
            match bindingState, activeParentProbePresent with
            | NativeWakeBoundParentContinuationTargets, _ -> NativeWakeNoRepairNeeded
            | NativeWakeBoundParentContinuationNoDeltaStarved, _ -> NativeWakeMaterializeBoundNoDeltaParentJobBind
            | NativeWakePartialOwnerIdentityParentBindProbeRequired, true -> NativeWakeGraftActiveParentBindingProbe
            | NativeWakePartialOwnerIdentityParentBindProbeRequired, false -> NativeWakeMaterializeMissingParentJobBind
            | NativeWakeUnboundTopologicalIsland, true -> NativeWakeGraftActiveParentBindingProbe
            | NativeWakeUnboundTopologicalIsland, false -> NativeWakeMaterializeMissingParentJobBind

        // MIGRATION: parent Job.bind materialization is now its own typed
        // decision instead of a prose next-action.  The no-root authority can
        // therefore carry a concrete bind-graft contract whenever a filled IVar
        // has visible listeners but no downstream work delta.
        type NativeWakeParentJobBindMaterializationId =
            | NativeWakeParentJobBindAlreadyMaterialized
            | NativeWakeParentJobBindForceBoundConsumerDelta
            | NativeWakeParentJobBindGraftFromActiveWorker
            | NativeWakeParentJobBindGraftFromNoRootBudgetAuthority
            | NativeWakeParentJobBindMaterializeMissingConsumer

        let nativeWakeParentJobBindMaterializationText = function
            | NativeWakeParentJobBindAlreadyMaterialized -> "parent_job_bind_already_materialized"
            | NativeWakeParentJobBindForceBoundConsumerDelta -> "force_bound_parent_consumer_delta_before_metronome"
            | NativeWakeParentJobBindGraftFromActiveWorker -> "graft_parent_job_bind_from_active_worker_probe"
            | NativeWakeParentJobBindGraftFromNoRootBudgetAuthority -> "graft_parent_job_bind_from_no_root_budget_authority"
            | NativeWakeParentJobBindMaterializeMissingConsumer -> "materialize_missing_parent_job_bind_consumer"

        let nativeWakeParentJobBindMaterializationFor authority bindingState activeParentProbePresent =
            match authority, bindingState, activeParentProbePresent with
            | (MetronomeTerminalIdleCrossKindActiveTySidecarTimeout
              | MetronomeTerminalParentReplayCycleBreakPoisonShadowTimeoutPierce
              | MetronomeTerminalDynamicRecordKeyBridgeTailPierce
              | MetronomeTerminalSemanticStaleRetargetShadowTimeoutPierce
              | MetronomeTerminalNoRootBudgetParentReplayImmediateFill), NativeWakeBoundParentContinuationTargets, _ -> NativeWakeParentJobBindForceBoundConsumerDelta
            | _, NativeWakeBoundParentContinuationTargets, _ -> NativeWakeParentJobBindAlreadyMaterialized
            | MetronomeTerminalNoRootBudgetParentReplayImmediateFill, NativeWakeBoundParentContinuationNoDeltaStarved, _ -> NativeWakeParentJobBindGraftFromNoRootBudgetAuthority
            | _, NativeWakeBoundParentContinuationNoDeltaStarved, true -> NativeWakeParentJobBindGraftFromActiveWorker
            | _, NativeWakePartialOwnerIdentityParentBindProbeRequired, true -> NativeWakeParentJobBindGraftFromActiveWorker
            | _, _, _ -> NativeWakeParentJobBindMaterializeMissingConsumer

        let nativeWakeParentJobBindContractText materialization edge bindTarget promiseId =
            "materialization=" + nativeWakeParentJobBindMaterializationText materialization + "|edge=" + edge + "|bind_target=" + bindTarget + "|wake_promise=" + promiseId + "|return=Job.bind->semantic_result_or_plateau_poison"

// MIGRATION: compile hotfix + assessment hygiene streak: move nativeWakeContinuationTargetStatusText above the Hopac call-stack renderer so MIGRATION builds past FS0039, preserving pure AST delta/no-further-delta telemetry and keeping the anti-spam HUD compaction intact for the next runtime run.
// MIGRATION: passive materialized bind execution streak: 1683 run dropped CPU after cooperative_replay_native_bind and preserved cache-handoff rows showed expected_work_delta_from_wake_graph=true but parent_job_bind_execution_not_required. Treat already-materialized Job.bind listeners as executable bound consumers by default, force cooperative/cache/pending-terminal consumers through direct-eval delta before metronome, and keep shadow timeouts observer-only after structural reentry.
// MIGRATION: compile hotfix for dynamic-join turn-on gate: MIGRATION still qualified MIGRATION helper DUs through Progress88 from BigStack, but F# did not expose those new lowercase helpers/cases across the sibling module boundary in this compile context. Inline the rendered structural handoff/gate/blocker strings at the BigStack JSON edge while leaving the Progress88 DU model as documentation/migration target, removing the FS0039 streak without reverting shadow-timeout observer semantics.
// MIGRATION: forced bound-consumer delta streak: after MIGRATION, follow MIGRATION assessments by treating already-bound hot Job.bind listeners as executable consumers, not passive materialization; force bound parent consumers for IdleCrossKind/ParentReplayPoison/DynamicRecordKey/SemanticStaleRetarget/NoRootBudget before metronome authority, add proof-tuple payload envelope/topological tracer/kill-switch fields, and carry sidecar-vs-continuation-cell parity consistently through proof tuple JSON/HUD.
// MIGRATION: native topology metronome kill-switch streak: 1673 reached ParentReplayCycleBreakPoisonShadowTimeoutPierce with ParentReplayPoisonContinuation/CycleBreakConsumer already bound, but the legacy cpu_quiet metronome still aborted. Suppress metronome kill authority when native consumers are attached, expose algebraic CyclePoison payload trace, and replace probation HUD lines with topology/kill-switch status.
// MIGRATION: idle-cross-kind and dynamic stack-fence callback streak: 1672 reached EJP0024 with IdleCrossKindActiveTySidecarTimeout and DynamicJoinPendingStackFenceBridgeAltTimeout already materialized as native callbacks; promote those payloads to direct-eval/expected-delta DUs and force their callbacks before metronome hard abort.
// MIGRATION: parent-replay status cache-handoff + global fuse native callback streak: 1671 reached EJP0011 global_fuse_abort while ParentReplayStatusPreservedCacheHandoff inline callbacks and sidecar deltas were already materialized; promote the cache-handoff as its own wake/delta/direct-eval DU and defer global fuse aborts to native callback handoff when live pending/replay evidence exists.
        // MIGRATION: MIGRATION stopped at a bind contract.  This DU names the
        // executable closure that must run after IVar.fill wakes a parent edge
        // but before the evaluator is allowed to fall back to another polling tick.
        type NativeWakeParentJobBindExecutionId =
            | NativeWakeParentJobBindExecutionNotRequired
            | NativeWakeParentJobBindExecuteBoundConsumerDelta
            | NativeWakeParentJobBindExecuteActiveWorkerProbe
            | NativeWakeParentJobBindExecuteNoRootAuthority
            | NativeWakeParentJobBindExecuteMissingConsumer

        let nativeWakeParentJobBindExecutionFor = function
            | NativeWakeParentJobBindAlreadyMaterialized -> NativeWakeParentJobBindExecuteBoundConsumerDelta
            | NativeWakeParentJobBindForceBoundConsumerDelta -> NativeWakeParentJobBindExecuteBoundConsumerDelta
            | NativeWakeParentJobBindGraftFromActiveWorker -> NativeWakeParentJobBindExecuteActiveWorkerProbe
            | NativeWakeParentJobBindGraftFromNoRootBudgetAuthority -> NativeWakeParentJobBindExecuteNoRootAuthority
            | NativeWakeParentJobBindMaterializeMissingConsumer -> NativeWakeParentJobBindExecuteMissingConsumer

        let nativeWakeParentJobBindExecutionText = function
            | NativeWakeParentJobBindExecutionNotRequired -> "parent_job_bind_execution_not_required"
            | NativeWakeParentJobBindExecuteBoundConsumerDelta -> "execute_bound_parent_consumer_delta_before_metronome"
            | NativeWakeParentJobBindExecuteActiveWorkerProbe -> "execute_job_bind_from_active_worker_probe"
            | NativeWakeParentJobBindExecuteNoRootAuthority -> "execute_job_bind_from_no_root_budget_authority"
            | NativeWakeParentJobBindExecuteMissingConsumer -> "execute_job_bind_for_missing_parent_consumer"

        let nativeWakeParentJobBindExecutionClosureText execution bindTarget promiseId =
            match execution with
            | NativeWakeParentJobBindExecutionNotRequired -> "none:parent_job_bind_already_materialized"
            | NativeWakeParentJobBindExecuteBoundConsumerDelta -> "Job.bind(" + bindTarget + ")->" + promiseId + "|force=consumer_delta_before_metronome|schedule=native_direct_ast_eval_or_ivar_fill_before_any_polling_boundary|return=semantic_result_or_plateau_poison"
            | _ -> "Job.bind(" + bindTarget + ")->" + promiseId + "|schedule=native_direct_ast_eval_before_any_polling_boundary|return=semantic_result_or_plateau_poison"

        let nativeWakeParentJobBindRecyclePolicyText execution =
            match execution with
            | NativeWakeParentJobBindExecutionNotRequired -> "retain_cadence_after_existing_bind"
            | _ -> "emit_first_bind_execution_then_hud_only_until_delta"

        // MIGRATION: the 1658 assessments identified the remaining livelock as
        // graft debt, not a terminal cpu-quiet condition.  Keep the repair,
        // payload, expected-delta and abort-override facts typed so JSON/HUD can
        // prove whether a filled IVar woke an actual semantic continuation or a
        // cultural fallback to the old eval_worklist topology.
        type NativeWakeParentJobBindGraftStatusId =
            | NativeWakeParentJobBindGraftMaterialized
            | NativeWakeParentJobBindGraftPendingForceReplay
            | NativeWakeParentJobBindGraftNoDeltaAfterGraft
            | NativeWakeParentJobBindGraftUnboundIsland

        let nativeWakeParentJobBindGraftStatusFor (bindingState: NativeWakeBindingStateId) (execution: NativeWakeParentJobBindExecutionId) =
            match bindingState, execution with
            | NativeWakeBoundParentContinuationTargets, NativeWakeParentJobBindExecutionNotRequired -> NativeWakeParentJobBindGraftMaterialized
            | NativeWakeBoundParentContinuationTargets, _ -> NativeWakeParentJobBindGraftPendingForceReplay
            | NativeWakeBoundParentContinuationNoDeltaStarved, _ -> NativeWakeParentJobBindGraftNoDeltaAfterGraft
            | NativeWakePartialOwnerIdentityParentBindProbeRequired, _ -> NativeWakeParentJobBindGraftPendingForceReplay
            | NativeWakeUnboundTopologicalIsland, _ -> NativeWakeParentJobBindGraftUnboundIsland

        let nativeWakeParentJobBindGraftStatusText = function
            | NativeWakeParentJobBindGraftMaterialized -> "materialized"
            | NativeWakeParentJobBindGraftPendingForceReplay -> "pending_force_replay"
            | NativeWakeParentJobBindGraftNoDeltaAfterGraft -> "no_delta_after_graft"
            | NativeWakeParentJobBindGraftUnboundIsland -> "unbound_island"

        type NativeWakeContinuationTargetId =
            | NativeWakeContinuationApplySpineStore
            | NativeWakeContinuationCooperativeReplayNativeBind
            | NativeWakeContinuationParentReplayStatusPreservedCacheHandoff
            | NativeWakeContinuationIdleCrossKindSidecar
            | NativeWakeContinuationDynamicJoinStackFenceBridge
            | NativeWakeContinuationDynamicJoinBridgeTailHandoff
            | NativeWakeContinuationObservedPinnedImmediateFill
            | NativeWakeContinuationPendingGraphCommittedTerminal
            | NativeWakeContinuationPendingGraphTerminal
            | NativeWakeContinuationDynamicBridgeParent
            | NativeWakeContinuationDynamicJoinReplay
            | NativeWakeContinuationWriterlessQueueDrain
            | NativeWakeContinuationObservedPinnedParent
            | NativeWakeContinuationSemanticStaleRetarget
            | NativeWakeContinuationParentReplayPoison
            | NativeWakeContinuationTySidecarDrain
            | NativeWakeContinuationCrossKindSiblingReplay
            | NativeWakeContinuationParentContinuationCell
            | NativeWakeContinuationParentBindingProbe
            | NativeWakeContinuationUnknownOwner

        type NativeWakeContinuationTargets = private {
            TargetIds : Set<NativeWakeContinuationTargetId>
            BindingCount : int
            RawText : string
        }

        module NativeWakeContinuationTargets =
            // Typed producers are now the only authority.  The former text parser
            // reconstructed target ownership from rendered continuation labels and
            // had no live callers; keeping it would invite future render->parse drift.
            let ofStructured targetIds bindingCount rawText =
                { TargetIds = Set.ofList targetIds
                  BindingCount = max 0 bindingCount
                  RawText = rawText }

            let withStructuredTarget targetId rawText targets =
                { TargetIds = Set.add targetId targets.TargetIds
                  BindingCount = targets.BindingCount + 1
                  RawText = rawText }

            let has targetId targets = Set.contains targetId targets.TargetIds
            let hasAny targetIds targets = targetIds |> List.exists (fun targetId -> has targetId targets)
            let hasUnknownOwner targets = has NativeWakeContinuationUnknownOwner targets
            let bindingCount targets = targets.BindingCount
            let rawText targets = targets.RawText

        let private metronomeTerminalAuthorityContinuationTargetShape = function
            | MetronomeTerminalSemanticStaleRetargetShadowTimeoutPierce ->
                [ NativeWakeContinuationSemanticStaleRetarget
                  NativeWakeContinuationIdleCrossKindSidecar
                  NativeWakeContinuationParentContinuationCell ], 3
            | MetronomeTerminalDynamicRecordKeyBridgeTailPierce ->
                [ NativeWakeContinuationDynamicBridgeParent
                  NativeWakeContinuationDynamicJoinReplay
                  NativeWakeContinuationWriterlessQueueDrain ], 3
            | MetronomeTerminalIdleCrossKindActiveTySidecarTimeout ->
                [ NativeWakeContinuationTySidecarDrain
                  NativeWakeContinuationCrossKindSiblingReplay
                  NativeWakeContinuationParentContinuationCell ], 3
            | MetronomeTerminalParentReplayCycleBreakPoisonShadowTimeoutPierce ->
                [ NativeWakeContinuationParentReplayPoison ], 2
            | MetronomeTerminalNoRootBudgetParentReplayImmediateFill ->
                [ NativeWakeContinuationParentReplayPoison
                  NativeWakeContinuationParentContinuationCell
                  NativeWakeContinuationParentBindingProbe ], 3
            | MetronomeTerminalStackFenceShadowTimeoutPierce ->
                [ NativeWakeContinuationDynamicJoinStackFenceBridge ], 2
            | MetronomeTerminalDeferredChildShadowTimeout ->
                [ NativeWakeContinuationParentContinuationCell ], 2
            | MetronomeTerminalParentContinuationCycleShadowTimeout ->
                [ NativeWakeContinuationParentReplayPoison ], 1
            | MetronomeTerminalApplySpineStoreDirect ->
                [ NativeWakeContinuationApplySpineStore
                  NativeWakeContinuationParentContinuationCell
                  NativeWakeContinuationPendingGraphTerminal ], 3
            | MetronomeTerminalObservedPinnedAuthority ->
                [ NativeWakeContinuationObservedPinnedParent ], 1
            | MetronomeTerminalPendingGraphCommittedTerminal ->
                [ NativeWakeContinuationCooperativeReplayNativeBind
                  NativeWakeContinuationPendingGraphCommittedTerminal
                  NativeWakeContinuationPendingGraphTerminal ], 3
            | MetronomeTerminalParentReplayStatusPreservedCacheHandoff ->
                [ NativeWakeContinuationParentReplayStatusPreservedCacheHandoff
                  NativeWakeContinuationCooperativeReplayNativeBind
                  NativeWakeContinuationParentContinuationCell ], 3

        let metronomeTerminalAuthorityContinuationTargets authority targetKey =
            let targetIds, bindingCount = metronomeTerminalAuthorityContinuationTargetShape authority
            let rawText = metronomeTerminalAuthorityContinuationBindingTargetsText authority targetKey
            NativeWakeContinuationTargets.ofStructured targetIds bindingCount rawText

        type NativeWakeTargetIdentityState =
            | NativeWakeTargetIdentityAvailable
            | NativeWakeTargetIdentityFrontierUnknown
            | NativeWakeTargetIdentityErased

        [<Struct>]
        type NativeWakeTargetIdentity = private {
            RawText : string
            SanitizedText : string
            State : NativeWakeTargetIdentityState
        }

        module NativeWakeTargetIdentity =
            type private NativeWakeIdentityMarkerId =
                | NativeWakeIdentityErasedMarker
                | NativeWakeIdentityMarkerOther

            let private nativeWakeIdentityMarkerId (text:string) =
                let tokens =
                    (if isNull text then "" else text)
                        .Split([|'['; ']'; '|'; ':'; ';'; ','; ' '; '\t'; '\r'; '\n'|], StringSplitOptions.RemoveEmptyEntries)
                if tokens |> Array.exists (fun token -> token.Equals("ERASED_IDENTITY", StringComparison.OrdinalIgnoreCase)) then
                    NativeWakeIdentityErasedMarker
                else NativeWakeIdentityMarkerOther

            let create (rawText: string) (sanitizedText: string) =
                let raw = if isNull rawText then "" else rawText
                let sanitized =
                    if System.String.IsNullOrWhiteSpace sanitizedText then "frontier_unknown"
                    else sanitizedText
                let state =
                    if sanitized = "frontier_unknown" then NativeWakeTargetIdentityFrontierUnknown
                    elif nativeWakeIdentityMarkerId raw = NativeWakeIdentityErasedMarker
                      || nativeWakeIdentityMarkerId sanitized = NativeWakeIdentityErasedMarker then NativeWakeTargetIdentityErased
                    else NativeWakeTargetIdentityAvailable
                { RawText = raw
                  SanitizedText = sanitized
                  State = state }

            let rawText identity = identity.RawText
            let sanitizedText identity = identity.SanitizedText
            let state identity = identity.State

            let stateText identity =
                match identity.State with
                | NativeWakeTargetIdentityAvailable -> "available"
                | NativeWakeTargetIdentityFrontierUnknown -> "frontier_unknown"
                | NativeWakeTargetIdentityErased -> "erased"

            let text identity =
                "NativeWakeTargetIdentity(state=" + stateText identity + "|sanitized=" + identity.SanitizedText + ")"

        type NativeWakeTopologicalDisconnectId =
            | NativeWakeDisconnectUnboundOrErasedIdentity
            | NativeWakeDisconnectPartialOwnerIdentityRequiresParentBindProbe
            | NativeWakeDisconnectStructuralContinuationTargets
            | NativeWakeDisconnectBoundParentContinuationNoWorkDeltaRequiresGraft
            | NativeWakeDisconnectPartialIdentityWithActiveParentBindingProbe
            | NativeWakeDisconnectUnboundWithActiveParentBindingProbe
            | NativeWakeDisconnectConsumedByNativeConsumerDeltaOrNoFurtherDeclared

        let nativeWakeTopologicalDisconnectText = function
            | NativeWakeDisconnectUnboundOrErasedIdentity -> "wake_graph_unbound_or_erased_identity"
            | NativeWakeDisconnectPartialOwnerIdentityRequiresParentBindProbe -> "wake_graph_partial_owner_identity_requires_parent_bind_probe"
            | NativeWakeDisconnectStructuralContinuationTargets -> "wake_graph_has_structural_continuation_targets"
            | NativeWakeDisconnectBoundParentContinuationNoWorkDeltaRequiresGraft -> "wake_graph_bound_parent_continuation_but_no_work_delta_requires_parent_job_bind_graft"
            | NativeWakeDisconnectPartialIdentityWithActiveParentBindingProbe -> "wake_graph_partial_identity_with_active_parent_binding_probe"
            | NativeWakeDisconnectUnboundWithActiveParentBindingProbe -> "wake_graph_unbound_but_active_parent_binding_probe_present"
            | NativeWakeDisconnectConsumedByNativeConsumerDeltaOrNoFurtherDeclared -> "wake_graph_consumed_by_native_consumer_delta_or_no_further_declared"

        type NativeWakeParentBindingHintId =
            | NativeWakeParentBindingActiveWorkerAwaiter of nodeIdJson:string
            | NativeWakeParentBindingContinuationCellProbe of readiness:string * topologyEdge:string
