            elif NativeWakeContinuationTargets.has NativeWakeContinuationApplySpineStore targets then NativeWakeExpectedDeltaApplySpineStore
            elif NativeWakeContinuationTargets.has NativeWakeContinuationCooperativeReplayNativeBind targets then NativeWakeExpectedDeltaCooperativeReplayNativeBind
            elif NativeWakeContinuationTargets.has NativeWakeContinuationParentReplayStatusPreservedCacheHandoff targets then NativeWakeExpectedDeltaParentReplayStatusPreservedCacheHandoff
            elif NativeWakeContinuationTargets.has NativeWakeContinuationIdleCrossKindSidecar targets then NativeWakeExpectedDeltaIdleCrossKindSidecarCallback
            elif NativeWakeContinuationTargets.has NativeWakeContinuationDynamicJoinStackFenceBridge targets then NativeWakeExpectedDeltaDynamicJoinStackFenceBridge
            elif NativeWakeContinuationTargets.has NativeWakeContinuationDynamicJoinBridgeTailHandoff targets then NativeWakeExpectedDeltaDynamicJoinBridgeTailHandoff
            elif NativeWakeContinuationTargets.has NativeWakeContinuationObservedPinnedImmediateFill targets then NativeWakeExpectedDeltaObservedPinnedImmediateFill
            elif NativeWakeContinuationTargets.has NativeWakeContinuationPendingGraphCommittedTerminal targets then NativeWakeExpectedDeltaPendingGraphCommittedTerminal
            elif NativeWakeContinuationTargets.has NativeWakeContinuationPendingGraphTerminal targets then NativeWakeExpectedDeltaPendingGraphTerminal
            elif NativeWakeContinuationTargets.has NativeWakeContinuationDynamicBridgeParent targets then NativeWakeExpectedDeltaDynamicBridge
            elif NativeWakeContinuationTargets.has NativeWakeContinuationDynamicJoinReplay targets then NativeWakeExpectedDeltaDynamicJoinReplay
            elif NativeWakeContinuationTargets.has NativeWakeContinuationWriterlessQueueDrain targets then NativeWakeExpectedDeltaWriterlessQueueDrain
            elif NativeWakeContinuationTargets.has NativeWakeContinuationObservedPinnedParent targets then NativeWakeExpectedDeltaObservedPinnedTerminal
            elif NativeWakeContinuationTargets.has NativeWakeContinuationSemanticStaleRetarget targets then NativeWakeExpectedDeltaSemanticStaleRetarget
            elif NativeWakeContinuationTargets.has NativeWakeContinuationParentReplayPoison targets then NativeWakeExpectedDeltaParentReplayCycleBreak
            elif NativeWakeContinuationTargets.has NativeWakeContinuationTySidecarDrain targets then NativeWakeExpectedDeltaSidecarDrain
            elif NativeWakeContinuationTargets.has NativeWakeContinuationCrossKindSiblingReplay targets then NativeWakeExpectedDeltaCrossKindSibling
            elif NativeWakeContinuationTargets.has NativeWakeContinuationParentContinuationCell targets then NativeWakeExpectedDeltaParentContinuation
            elif NativeWakeContinuationTargets.has NativeWakeContinuationParentBindingProbe targets then NativeWakeExpectedDeltaGraftRepair
            else NativeWakeExpectedDeltaNone

        let nativeWakeExpectedDeltaText = function
            | NativeWakeExpectedDeltaNone -> "none"
            | NativeWakeExpectedDeltaApplySpineStore -> "apply_spine_store_delta_expected"
            | NativeWakeExpectedDeltaPendingGraphTerminal -> "pending_graph_terminal_delta_expected"
            | NativeWakeExpectedDeltaPendingGraphCommittedTerminal -> "pending_graph_committed_terminal_delta_expected"
            | NativeWakeExpectedDeltaCooperativeReplayNativeBind -> "cooperative_replay_native_bind_delta_expected"
            | NativeWakeExpectedDeltaParentReplayStatusPreservedCacheHandoff -> "parent_replay_status_preserved_cache_handoff_delta_expected"
            | NativeWakeExpectedDeltaIdleCrossKindSidecarCallback -> "idle_cross_kind_sidecar_callback_delta_expected"
            | NativeWakeExpectedDeltaDynamicJoinStackFenceBridge -> "dynamic_join_stack_fence_bridge_delta_expected"
            | NativeWakeExpectedDeltaDynamicJoinBridgeTailHandoff -> "dynamic_join_bridge_tail_handoff_delta_expected"
            | NativeWakeExpectedDeltaObservedPinnedImmediateFill -> "observed_pinned_immediate_fill_delta_expected"
            | NativeWakeExpectedDeltaDynamicBridge -> "dynamic_bridge_parent_continuation_delta_expected"
            | NativeWakeExpectedDeltaDynamicJoinReplay -> "dynamic_join_apply_replay_delta_expected"
            | NativeWakeExpectedDeltaWriterlessQueueDrain -> "writerless_queue_drain_delta_expected"
            | NativeWakeExpectedDeltaObservedPinnedTerminal -> "observed_pinned_terminal_delta_expected"
            | NativeWakeExpectedDeltaSemanticStaleRetarget -> "semantic_stale_retarget_direct_delta_expected"
            | NativeWakeExpectedDeltaParentReplayCycleBreak -> "parent_replay_cycle_break_delta_expected"
            | NativeWakeExpectedDeltaParentContinuation -> "parent_continuation_delta_expected"
            | NativeWakeExpectedDeltaCrossKindSibling -> "cross_kind_sibling_delta_expected"
            | NativeWakeExpectedDeltaSidecarDrain -> "sidecar_drain_delta_expected"
            | NativeWakeExpectedDeltaGraftRepair -> "graft_repair_delta_expected"

        let nativeWakeExpectedDeltaFlag = function
            | NativeWakeExpectedDeltaNone -> false
            | _ -> true

        // MIGRATION: begin the structural wake-graph remodel requested by the
        // assessments.  These phantom markers make the native callback contract
        // name the state it is allowed to consume before any pretty JSON string
        // is produced.  They are intentionally tiny: the next rounds can move
        // more fields from string probes into these carriers without reopening
        // the old worklist scheduler.
        type NativeWakeUnresolvedState = class end
        type NativeWakeMaterializedState = class end
        type NativeWakeClearedState = class end
        type NativeWakeNode<'State,'Payload> = private { NativeWakeNodeId: string; NativeWakeNodePayload: 'Payload }
        type NativeWakePayloadEnvelopeId =
            | NativeWakePayloadResolution of payload:string * witness:string * edge:string
            | NativeWakePayloadCyclePoison of payload:string * witness:string * edge:string
            | NativeWakePayloadDummyUnit of witness:string * edge:string
            | NativeWakePayloadMissing of witness:string

        // MIGRATION: begin the phantom-kind WakeGraph/BoundConsumer streak.
        // The current runtime still renders many closure identities as JSON, but
        // the type surface now carries the intended kind boundary explicitly so
        // later rounds can move routing out of text probes and into indexed graph
        // envelopes without reopening EvalWorklist authority.
        type NativeWakeKindTerm = class end
        type NativeWakeKindTy = class end
        type NativeWakeKindCrossKind = class end
        type NativeWakeKindParentReplayPoison = class end
        type NativeWakeKindDynamicJoin = class end
        type NativeWakeBoundConsumer<'Kind> = private { NativeWakeBoundConsumerName: string }
        type NativeWakeGraph<'Kind,'Payload> =
            | NativeWakeGraphFilled of NativeWakeNode<NativeWakeMaterializedState,'Payload> * NativeWakeBoundConsumer<'Kind> list
            | NativeWakeGraphPending of nodeId:string * witness:string
        module NativeWakeBoundConsumer =
            let create name : NativeWakeBoundConsumer<'Kind> = { NativeWakeBoundConsumerName = name }
            let name (consumer: NativeWakeBoundConsumer<'Kind>) = consumer.NativeWakeBoundConsumerName
        module NativeWakeGraph =
            let filled node consumers : NativeWakeGraph<'Kind,'Payload> = NativeWakeGraphFilled(node, consumers)
            let pending nodeId witness : NativeWakeGraph<'Kind,'Payload> = NativeWakeGraphPending(nodeId, witness)
            let consumerCount = function | NativeWakeGraphFilled(_, consumers) -> List.length consumers | NativeWakeGraphPending _ -> 0
            let compactText graph =
                match graph with
                | NativeWakeGraphFilled(node, consumers) -> "typed_wake_graph_filled(node=" + node.NativeWakeNodeId + "|consumers=" + string (List.length consumers) + ")"
                | NativeWakeGraphPending(nodeId, witness) -> "typed_wake_graph_pending(node=" + nodeId + "|witness=" + witness + ")"

        // MIGRATION: closure ledger/latch surface.  1692 proved that adjacent
        // proof/delta rows are not enough: HUD/BigStack can still rediscover
        // the old parent-replay poison action from status strings.  This DU
        // names the state transition the runtime must render and later enforce:
        // open -> consumer executed -> no-further/owner released -> cleared.
        type TerminalClosureStageId =
            | TerminalClosureOpen
            | TerminalClosureNativeConsumerExecuted
            | TerminalClosureNoFurtherDeltaDeclared
            | TerminalClosureOwnerReleased
            | TerminalClosureCleared

        type GraftExecutionOutcomeId =
            | GraftExecutionDeltaProduced
            | GraftExecutionNoFurtherDeltaButPoisonAdvanced
            | GraftExecutionDeferred
            | GraftExecutionConsumerRanButNoObservableProgress

        type ParentPoisonConsumerAdvanceId =
            | ParentPoisonConsumerAdvancePending
            | ParentPoisonConsumerAdvancedByCyclePoison
            | ParentPoisonConsumerAdvancedByNoFurtherDelta
            | ParentPoisonConsumerAdvancedByAstDelta

        let terminalClosureStageText = function
            | TerminalClosureOpen -> "open"
            | TerminalClosureNativeConsumerExecuted -> "native_consumer_executed"
            | TerminalClosureNoFurtherDeltaDeclared -> "no_further_delta_declared"
            | TerminalClosureOwnerReleased -> "owner_released"
            | TerminalClosureCleared -> "terminal_cleared"

        let graftExecutionOutcomeText = function
            | GraftExecutionDeltaProduced -> "DeltaProduced"
            | GraftExecutionNoFurtherDeltaButPoisonAdvanced -> "NoFurtherDeltaButPoisonAdvanced"
            | GraftExecutionDeferred -> "GraftDeferred"
            | GraftExecutionConsumerRanButNoObservableProgress -> "ConsumerRanButNoObservableProgress"

        let parentPoisonConsumerAdvanceText = function
            | ParentPoisonConsumerAdvancePending -> "pending"
            | ParentPoisonConsumerAdvancedByCyclePoison -> "advanced_by_cycle_poison"
            | ParentPoisonConsumerAdvancedByNoFurtherDelta -> "advanced_by_no_further_delta"
            | ParentPoisonConsumerAdvancedByAstDelta -> "advanced_by_ast_delta"

        let terminalClosureId lane key site =
            let sanitize (s: string) =
                if System.Object.ReferenceEquals(s, null) || s = "" then "unknown"
                else
                    s.Replace("\\", "_").Replace("/", "_").Replace("|", "_").Replace(":", "_").Replace(" ", "_")
            "tc:" + sanitize lane + ":" + sanitize key + ":" + sanitize site

        let terminalClosureStageIsClosed = function
            | TerminalClosureCleared -> true
            | _ -> false

        type TerminalClosureRegressionId =
            | TerminalClosureNoRegression
            | TerminalClosureHudFrontierReopenedAfterClear
            | TerminalClosureBypassReopenedAfterClear
            | TerminalClosureRepeatAfterClear of count:int

        let terminalClosureRegressionText = function
            | TerminalClosureNoRegression -> "none"
            | TerminalClosureHudFrontierReopenedAfterClear -> "hud_frontier_reopened_after_terminal_clear"
            | TerminalClosureBypassReopenedAfterClear -> "bypass_reopened_after_terminal_clear"
            | TerminalClosureRepeatAfterClear count -> "repeat_after_clear(count=" + string count + ")"

        let terminalClosureRepeatPolicyText stage =
            if terminalClosureStageIsClosed stage then "emit_ref_only_after_terminal_closure_latched"
            else "emit_candidate_until_terminal_closure_latched"

        // MIGRATION: the repeat cap is not terminal authority by itself.  A
        // phantom-indexed recursive graph carries whether a bound executable
        // continuation still owns the closure.  This keeps the fail-closed
        // EJP0026 path, but only after queue/worker execution is exhausted.
        type TerminalClosureRepeatNoRootKind = | TerminalClosureRepeatNoRootKind
        type TerminalClosureRepeatGraph<'Kind> =
            | TerminalClosureRepeatExecutableGraph of key:string * pending:int * queue:int * active:int * continuation:TerminalClosureRepeatGraph<'Kind> option
            | TerminalClosureRepeatGraphExhausted of key:string * pending:int

        let terminalClosureRepeatGraphFor<'Kind> key pending queue active replayComplete writeWitness : TerminalClosureRepeatGraph<'Kind> =
            // MIGRATION: write_wit/replay_complete are receipts, not exhaustion proofs.
            // If Q/A/P remains live, finish-fast must defer to the executable graph
            // instead of letting a witness mask work that still has a parent-poison
            // consumer, sidecar or replay continuation to drain.
            if pending > 0 || queue > 0 || active > 0 then
                TerminalClosureRepeatExecutableGraph(key, pending, queue, active, None)
            elif not replayComplete && not writeWitness then
                TerminalClosureRepeatExecutableGraph(key, pending, queue, active, None)
            else
                TerminalClosureRepeatGraphExhausted(key, pending)

        let rec terminalClosureRepeatGraphText = function
            | TerminalClosureRepeatExecutableGraph(key, pending, queue, active, continuation) ->
                let tail =
                    match continuation with
                    | Some next -> "|next=" + terminalClosureRepeatGraphText next
                    | None -> "|next=bound_native_callback_or_parent_continuation"
                "TerminalClosureRepeatGraph(Executable|key=" + key + "|pending=" + string pending + "|queue=" + string queue + "|active=" + string active + tail + ")"
            | TerminalClosureRepeatGraphExhausted(key, pending) ->
                "TerminalClosureRepeatGraph(Exhausted|key=" + key + "|pending=" + string pending + ")"

        let terminalClosureRepeatGraphCanExit = function
            | TerminalClosureRepeatGraphExhausted _ -> true
            | TerminalClosureRepeatExecutableGraph _ -> false

        let terminalClosureStageFromNoRootEvidence dispatchCount authorityCount =
            if dispatchCount > 0 || authorityCount > 0 then TerminalClosureCleared
            else TerminalClosureOpen

        let terminalClosureShouldEmitFull stage repeatCount =
            not (terminalClosureStageIsClosed stage) || repeatCount <= 2 || repeatCount % 64 = 0

        let private terminalClosureJsonEsc (s: string) =
            if System.Object.ReferenceEquals(s, null) then "null" else
                let s =
                    s.Replace("\\", "\\\\")
                     .Replace("\"", "\\\"")
                     .Replace("\r", "\\r")
                     .Replace("\n", "\\n")
                     .Replace("\t", "\\t")
                "\"" + s + "\""

        type NativeClosureCycleCounterDecisionId =
            | NativeClosureCycleCounterOpen of wakeCount:int * semanticFactCount:int64
            | NativeClosureCycleCounterStarving of wakeCount:int * starvationCount:int * threshold:int * blocker:string
            | NativeClosureCycleCounterPlateauPoison of wakeCount:int * starvationCount:int * threshold:int * blocker:string

        let nativeClosureCycleCounterThresholdDefault = 4

        let nativeClosureSemanticFactCount (sampledDelta:int64) (replayDelta:int64) (rootDelta:int64) (terminalDelta:int64) =
            [sampledDelta; replayDelta; rootDelta; terminalDelta]
            |> List.fold (fun acc delta -> if delta > 0L then acc + delta else acc) 0L

        type NativeClosureBlockerClassId =
            | NativeClosureBlockerClassIdSidecarOrCrossKind
            | NativeClosureBlockerClassIdOther

        let nativeClosureEffectiveSemanticFactCount (sampledDelta:int64) (replayDelta:int64) (rootDelta:int64) (terminalDelta:int64) (richStale:bool) (richAgeMs:int64) (noWorkS:int64) (blockerClass:NativeClosureBlockerClassId) =
            let raw = nativeClosureSemanticFactCount sampledDelta replayDelta rootDelta terminalDelta
            let topologyOnlyDelta = rootDelta <= 0L && terminalDelta <= 0L && (sampledDelta > 0L || replayDelta > 0L)
            let blockerIsSidecarOrCrossKind =
                match blockerClass with
                | NativeClosureBlockerClassIdSidecarOrCrossKind -> true
                | NativeClosureBlockerClassIdOther -> false
            let staleObserverOnly = richStale || richAgeMs >= 60000L || noWorkS >= 40L
            if blockerIsSidecarOrCrossKind && topologyOnlyDelta && staleObserverOnly then 0L else raw

        let nativeClosureCycleCounterDecision (threshold:int) (wakeCount:int) (semanticFactCount:int64) (blocker:string) =
            if semanticFactCount > 0L then NativeClosureCycleCounterOpen(wakeCount, semanticFactCount)
            else
                let starvationCount = max 0 wakeCount
                if starvationCount >= threshold then NativeClosureCycleCounterPlateauPoison(wakeCount, starvationCount, threshold, blocker)
                elif starvationCount > 0 then NativeClosureCycleCounterStarving(wakeCount, starvationCount, threshold, blocker)
                else NativeClosureCycleCounterOpen(wakeCount, semanticFactCount)

        let nativeClosureCycleCounterDecisionText = function
            | NativeClosureCycleCounterOpen(wakeCount, semanticFactCount) -> "ClosureCounterOpen(wake_count=" + string wakeCount + "|semantic_fact_count=" + string semanticFactCount + ")"
            | NativeClosureCycleCounterStarving(wakeCount, starvationCount, threshold, blocker) -> "ClosureCounterStarving(wake_count=" + string wakeCount + "|starvation_count=" + string starvationCount + "|threshold=" + string threshold + "|blocker=" + blocker + ")"
            | NativeClosureCycleCounterPlateauPoison(wakeCount, starvationCount, threshold, blocker) -> "ClosurePlateauPoison(wake_count=" + string wakeCount + "|starvation_count=" + string starvationCount + "|threshold=" + string threshold + "|blocker=" + blocker + ")"

        let nativeClosureCycleCounterStarvationCount = function
            | NativeClosureCycleCounterOpen _ -> 0
            | NativeClosureCycleCounterStarving(_, starvationCount, _, _) -> starvationCount
            | NativeClosureCycleCounterPlateauPoison(_, starvationCount, _, _) -> starvationCount

        let nativeClosureCycleCounterPoisonText = function
            | NativeClosureCycleCounterPlateauPoison _ -> "PlateauPoison(closure_cycle_counter_threshold_reached)"
            | NativeClosureCycleCounterStarving _ -> "not_armed_starving"
            | NativeClosureCycleCounterOpen _ -> "not_armed"

        let nativeClosureCycleCounterResultText = function
            | NativeClosureCycleCounterPlateauPoison _ -> "ClosureCycleCounterReturnedPlateauPoison"
            | NativeClosureCycleCounterStarving _ -> "ClosureCycleCounterObservedStarvation"
            | NativeClosureCycleCounterOpen(_, semanticFactCount) when semanticFactCount > 0L -> "ClosureCycleCounterObservedSemanticFact"
            | NativeClosureCycleCounterOpen _ -> "ClosureCycleCounterOpen"

        type NativeClosureKindId =
            | NativeClosureTerminalLatch
            | NativeClosureDynamicRecordKeyBridgeTail
            | NativeClosureSemanticStaleRetarget
            | NativeClosureTySidecarPrefetch
            | NativeClosureTySidecarDrain
            | NativeClosureParentReplayPoison
            | NativeClosureNoRootBudget
            | NativeClosureBoundWakeConsumer
            | NativeClosureCooperativeReplayNativeBind
            | NativeClosureParentCacheHandoffWake
            | NativeClosureParentReplayStatusPreservedCacheHandoff
            | NativeClosureUnknown of CompilerKernelV2.OperationalReasonId

        let nativeClosureKindText = function
            | NativeClosureTerminalLatch -> "terminal_closure_latch"
            | NativeClosureDynamicRecordKeyBridgeTail -> "dynamic_record_key_bridge_tail"
            | NativeClosureSemanticStaleRetarget -> "semantic_stale_retarget"
            | NativeClosureTySidecarPrefetch -> "ty_sidecar_prefetch"
            | NativeClosureTySidecarDrain -> "ty_sidecar_drain"
            | NativeClosureParentReplayPoison -> "parent_replay_poison"
            | NativeClosureNoRootBudget -> "no_root_budget"
            | NativeClosureBoundWakeConsumer -> "bound_wake_consumer"
            | NativeClosureCooperativeReplayNativeBind -> "cooperative_replay_native_bind"
            | NativeClosureParentCacheHandoffWake -> "parent_cache_handoff_wake"
            | NativeClosureParentReplayStatusPreservedCacheHandoff -> "parent_replay_status_preserved_cache_handoff"
            | NativeClosureUnknown reasonId -> "unknown(" + CompilerKernelV2.OperationalReasonIdOps.text reasonId + ")"

        type NativeClosureSemanticFactId =
            | NativeClosureNoSemanticFact
            | NativeClosureAstMutation of node:string
            | NativeClosureTypeUnification of leftTy:string * rightTy:string
            | NativeClosureTermEvaluation of term:string
            | NativeClosureCyclePoisonFact of poison:string

        let nativeClosureSemanticFactText = function
            | NativeClosureNoSemanticFact -> "NoSemanticFact"
            | NativeClosureAstMutation node -> "AstMutation(node=" + node + ")"
            | NativeClosureTypeUnification(leftTy, rightTy) -> "TypeUnification(left=" + leftTy + "|right=" + rightTy + ")"
            | NativeClosureTermEvaluation term -> "TermEvaluation(term=" + term + ")"
            | NativeClosureCyclePoisonFact poison -> "CyclePoisonFact(" + poison + ")"

        type NativeClosureFixedPointVerdictId =
            | NativeClosureMayContinue of NativeClosureCycleCounterDecisionId
            | NativeClosureMustPoison of NativeClosureCycleCounterDecisionId * NativeClosureKindId * blocker:string

        let nativeClosureFixedPointVerdictText = function
            | NativeClosureMayContinue decision -> "MayContinue(" + nativeClosureCycleCounterDecisionText decision + ")"
            | NativeClosureMustPoison(decision, kind, blocker) -> "MustPoison(kind=" + nativeClosureKindText kind + "|blocker=" + blocker + "|" + nativeClosureCycleCounterDecisionText decision + ")"

        let nativeClosureFixedPointVerdict threshold wakeCount semanticFactCount kind blocker =
            let decision = nativeClosureCycleCounterDecision threshold wakeCount semanticFactCount blocker
            match decision with
            | NativeClosureCycleCounterPlateauPoison _ -> NativeClosureMustPoison(decision, kind, blocker)
            | _ -> NativeClosureMayContinue decision

        type NativeEvalGraph<'T> =
            | NativeEvalYield of 'T
            | NativeEvalAwait of promiseId:string * continuationLabel:string
            | NativeEvalPoison of poison:string * blocker:string

        let nativeEvalGraphText renderValue = function
            | NativeEvalYield value -> "Yield(" + renderValue value + ")"
            | NativeEvalAwait(promiseId, continuationLabel) -> "Await(promise_id=" + promiseId + "|continuation=" + continuationLabel + ")"
            | NativeEvalPoison(poison, blocker) -> "Poison(" + poison + "|blocker=" + blocker + ")"

        let nativeClosureEvalGraphFromVerdict renderOk verdict okValue =
            match verdict with
            | NativeClosureMayContinue _ -> NativeEvalYield okValue |> nativeEvalGraphText renderOk
            | NativeClosureMustPoison(decision, kind, blocker) ->
                NativeEvalPoison(nativeClosureCycleCounterPoisonText decision + "|kind=" + nativeClosureKindText kind, blocker)
                |> nativeEvalGraphText id

        type NativeClosureTopologyVerdictId =
            | NativeTopologyAcyclic of node:string * edge:string
            | NativeTopologySccCyclePoison of scc:string * blocker:string
            | NativeTopologySemanticPlateau of scc:string * blocker:string * NativeClosureFixedPointVerdictId

        let nativeClosureTopologyVerdictText = function
            | NativeTopologyAcyclic(node, edge) -> "Acyclic(node=" + node + "|edge=" + edge + ")"
            | NativeTopologySccCyclePoison(scc, blocker) -> "SccCyclePoison(scc=" + scc + "|blocker=" + blocker + ")"
            | NativeTopologySemanticPlateau(scc, blocker, verdict) -> "SemanticPlateau(scc=" + scc + "|blocker=" + blocker + "|" + nativeClosureFixedPointVerdictText verdict + ")"

        let nativeClosureTopologyVerdict scc blocker verdict =
            match verdict with
            | NativeClosureMustPoison _ -> NativeTopologySemanticPlateau(scc, blocker, verdict)
            | NativeClosureMayContinue _ -> NativeTopologyAcyclic(scc, "await_native_semantic_fact")

        type NativeClosureAdmissionId =
            | NativeClosureAdmissionAllowed of kind:NativeClosureKindId * reason:CompilerKernelV2.OperationalReasonId
            | NativeClosureAdmissionBlockedPlateaued of kind:NativeClosureKindId * blocker:string
            | NativeClosureAdmissionBlockedLegacyPolling of kind:NativeClosureKindId * reason:CompilerKernelV2.OperationalReasonId

        let nativeClosureAdmissionText = function
            | NativeClosureAdmissionAllowed(kind, reason) -> "AdmissionAllowed(kind=" + nativeClosureKindText kind + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NativeClosureAdmissionBlockedPlateaued(kind, blocker) -> "AdmissionBlockedPlateaued(kind=" + nativeClosureKindText kind + "|blocker=" + blocker + ")"
            | NativeClosureAdmissionBlockedLegacyPolling(kind, reason) -> "AdmissionBlockedLegacyPolling(kind=" + nativeClosureKindText kind + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let nativeClosureAdmissionFromVerdict kind verdict blocker =
            match verdict with
            | NativeClosureMustPoison _ -> NativeClosureAdmissionBlockedPlateaued(kind, blocker)
            | NativeClosureMayContinue _ -> NativeClosureAdmissionAllowed(kind, CompilerKernelV2.OperationalReasonIdOps.create "semantic_fixed_point_open")

        type NativeClosureReentryPolicyId =
            | NativeClosureReentryAllowed of NativeClosureKindId * reason:CompilerKernelV2.OperationalReasonId
            | NativeClosureReentryBlockedByPlateau of NativeClosureKindId * blocker:string * repeatAfterClear:int
            | NativeClosureReentrySuppressedObserverOnly of NativeClosureKindId * repeatAfterClear:int

        let nativeClosureReentryPolicyText = function
            | NativeClosureReentryAllowed(kind, reason) -> "ReentryAllowed(kind=" + nativeClosureKindText kind + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NativeClosureReentryBlockedByPlateau(kind, blocker, repeatAfterClear) -> "ReentryBlockedByPlateau(kind=" + nativeClosureKindText kind + "|blocker=" + blocker + "|repeat_after_clear=" + string repeatAfterClear + ")"
            | NativeClosureReentrySuppressedObserverOnly(kind, repeatAfterClear) -> "ReentrySuppressedObserverOnly(kind=" + nativeClosureKindText kind + "|repeat_after_clear=" + string repeatAfterClear + ")"

        let terminalClosureRefFields lane key site stage outcome advance sourceRowRef =
            let id = terminalClosureId lane key site
            let closureClosed = terminalClosureStageIsClosed stage
            let closureWakeCount = if closureClosed then nativeClosureCycleCounterThresholdDefault else 0
            let closureSemanticFactCount = 0L
            let closureCycleDecision = nativeClosureCycleCounterDecision nativeClosureCycleCounterThresholdDefault closureWakeCount closureSemanticFactCount ("terminal_closure_ref/" + lane)
            let closureStarvationCount = nativeClosureCycleCounterStarvationCount closureCycleDecision
            ",\"terminal_closure_id\":" + terminalClosureJsonEsc id +
            ",\"proof_tuple_id\":" + terminalClosureJsonEsc ("pt:" + id) +
            ",\"source_row_ref\":" + terminalClosureJsonEsc sourceRowRef +
            ",\"terminal_latch_state_du\":" + terminalClosureJsonEsc (terminalClosureStageText stage) +
            ",\"owner_release_du\":" + terminalClosureJsonEsc (if stage = TerminalClosureOwnerReleased || stage = TerminalClosureCleared then "owner_released" else "owner_not_released") +
            ",\"terminal_clear_du\":" + terminalClosureJsonEsc (if terminalClosureStageIsClosed stage then "terminal_cleared" else "terminal_open") +
            ",\"consumer_execution_latch_du\":" + terminalClosureJsonEsc (if stage = TerminalClosureOpen then "not_consumed" else "consumer_execution_latched") +
            ",\"parent_continuation_state_du\":" + terminalClosureJsonEsc (if terminalClosureStageIsClosed stage then "parent_continuation_released" else "parent_continuation_waiting") +
            ",\"authority_lane_du\":" + terminalClosureJsonEsc lane +
            ",\"graft_execution_outcome_du\":" + terminalClosureJsonEsc (graftExecutionOutcomeText outcome) +
            ",\"parent_poison_consumer_advance_du\":" + terminalClosureJsonEsc (parentPoisonConsumerAdvanceText advance) +
            ",\"repeat_counter_after_clear\":" + (if terminalClosureStageIsClosed stage then "1" else "0") +
            ",\"terminal_closure_regression_du\":" + terminalClosureJsonEsc (if terminalClosureStageIsClosed stage then terminalClosureRegressionText TerminalClosureNoRegression else terminalClosureRegressionText TerminalClosureNoRegression) +
            ",\"terminal_latch_owns_frontier\":" + (if terminalClosureStageIsClosed stage then "true" else "false") +
            ",\"closure_latch_blocks_ejp0022\":" + (if terminalClosureStageIsClosed stage then "true" else "false") +
            ",\"closure_ledger_semantic_starvation_count\":" + string closureStarvationCount +
            ",\"closure_cycle_counter_threshold\":" + string nativeClosureCycleCounterThresholdDefault +
            ",\"closure_cycle_counter_du\":" + terminalClosureJsonEsc (nativeClosureCycleCounterDecisionText closureCycleDecision) +
            ",\"closure_semantic_fact_count\":" + string closureSemanticFactCount +
            ",\"native_promise_closure_result_du\":" + terminalClosureJsonEsc (nativeClosureCycleCounterResultText closureCycleDecision) +
            ",\"semantic_blocker_ast_node\":" + terminalClosureJsonEsc ("terminal_closure_ref/" + lane) +
            ",\"native_closure_semantic_delta_du\":" + terminalClosureJsonEsc (if closureSemanticFactCount > 0L then "semantic_delta_produced" elif closureClosed then "semantic_delta_starved" else "unknown") +
            ",\"native_closure_plateau_poison_du\":" + terminalClosureJsonEsc (nativeClosureCycleCounterPoisonText closureCycleDecision) +
            ",\"jsonl_recycle_du\":" + terminalClosureJsonEsc (terminalClosureRepeatPolicyText stage)

        module NativeWakeNode =
            let materialize id payload : NativeWakeNode<NativeWakeMaterializedState,'Payload> = { NativeWakeNodeId = id; NativeWakeNodePayload = payload }
            let clear (node: NativeWakeNode<NativeWakeMaterializedState,'Payload>) : NativeWakeNode<NativeWakeClearedState,'Payload> = { NativeWakeNodeId = node.NativeWakeNodeId; NativeWakeNodePayload = node.NativeWakeNodePayload }
            let extractWitness (node: NativeWakeNode<NativeWakeMaterializedState,'Payload>) : 'Payload = node.NativeWakeNodePayload
            let id (node: NativeWakeNode<'State,'Payload>) = node.NativeWakeNodeId
        let nativeWakePayloadEnvelopeText = function
            | NativeWakePayloadResolution(payload, witness, edge) -> "resolution_payload(payload=" + payload + "|witness=" + witness + "|edge=" + edge + ")"
            | NativeWakePayloadCyclePoison(payload, witness, edge) -> "cycle_poison_payload(payload=" + payload + "|witness=" + witness + "|edge=" + edge + ")"
            | NativeWakePayloadDummyUnit(witness, edge) -> "dummy_unit_payload(witness=" + witness + "|edge=" + edge + ")"
            | NativeWakePayloadMissing(witness) -> "missing_payload(witness=" + witness + ")"

        // MIGRATION: the assessment asked for an algebraic payload trace and a
        // metronome kill-switch.  These DUs make the operation visible as graph
        // topology, not as polling-era liveness/probation text.
        type NativeTopologicalResolutionTracerId =
            | NativeTopologyNoResolution
            | NativeTopologyCyclePoisonResolution of node:string * payload:string * target:string * result:string
            | NativeTopologyDirectAstEvaluation of node:string * payload:string * target:string

        let nativeTopologicalResolutionTracerText = function
            | NativeTopologyNoResolution -> "none"
            | NativeTopologyCyclePoisonResolution(node, payload, target, result) -> "node=" + node + "->emits=" + payload + "->unblocks=" + target + "->yields=" + result
            | NativeTopologyDirectAstEvaluation(node, payload, target) -> "node=" + node + "->payload=" + payload + "->direct_ast_eval_target=" + target

        type NativeMetronomeKillSwitchId =
            | NativeMetronomeKillSwitchArmed
            | NativeMetronomeKillSwitchSuppressedNativeConsumersAttached of reason:CompilerKernelV2.OperationalReasonId
            | NativeMetronomeKillSwitchSuppressedCyclePoisonResolution of reason:CompilerKernelV2.OperationalReasonId

        let nativeMetronomeKillSwitchText = function
            | NativeMetronomeKillSwitchArmed -> "armed"
            | NativeMetronomeKillSwitchSuppressedNativeConsumersAttached reason -> "suppressed_native_consumers_attached(" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NativeMetronomeKillSwitchSuppressedCyclePoisonResolution reason -> "suppressed_cycle_poison_resolution(" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        // MIGRATION: remove time as the hidden resolver for the current hot path.
        // A filled native IVar can now report that a parent/sibling edge is a
        // structural re-entry/cycle condition before any shadow-alt timeout is
        // allowed to claim authority.
        type NativeStructuralCycleDetectionId =
            | NativeStructuralCycleNoCycle
            | NativeStructuralCycleLocalizedCyclePoison of node:string * edge:string * payload:string
            | NativeStructuralCycleDirectWakeReentry of node:string * edge:string
            | NativeStructuralCycleShadowTimerDeprecated of reason:CompilerKernelV2.OperationalReasonId

        let nativeStructuralCycleDetectionText = function
            | NativeStructuralCycleNoCycle -> "no_structural_cycle"
            | NativeStructuralCycleLocalizedCyclePoison(node, edge, payload) -> "localized_cycle_poison(node=" + node + "|edge=" + edge + "|payload=" + payload + ")"
            | NativeStructuralCycleDirectWakeReentry(node, edge) -> "direct_wake_reentry(node=" + node + "|edge=" + edge + ")"
            | NativeStructuralCycleShadowTimerDeprecated reason -> "shadow_timer_deprecated(" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        // MIGRATION: dynamic-join turn-on gate.  The 1679 JSONL still shows
        // DynamicJoinCooperativeAltTimeout and DynamicJoinBridgeTailHandoff rows
        // carrying shadow_alt_timeout/weak_physical_queue vocabulary even after
        // proof_tuple_complete=true and an inline callback were available.  These
        // DUs name whether the next step is a real native continuation turn-on,
        // a structural re-entry poison, or legacy shadow observation only.
        type NativeHopacTurnOnGateId =
            | NativeHopacTurnOnGateOpenNow of gate:string
            | NativeHopacTurnOnGateBlockedByStructuralReentry of gate:string
            | NativeHopacTurnOnGateShadowObserverOnly of gate:string
            | NativeHopacTurnOnGateLegacyForbidden of gate:string

        let nativeHopacTurnOnGateText = function
            | NativeHopacTurnOnGateOpenNow gate -> "open_native_turn_on(" + gate + ")"
            | NativeHopacTurnOnGateBlockedByStructuralReentry gate -> "blocked_by_structural_reentry(" + gate + ")"
            | NativeHopacTurnOnGateShadowObserverOnly gate -> "shadow_observer_only(" + gate + ")"
            | NativeHopacTurnOnGateLegacyForbidden gate -> "legacy_forbidden(" + gate + ")"

        type DynamicJoinNativeHandoffStrengthId =
            | DynamicJoinNativeHandoffWeakPhysicalQueue
            | DynamicJoinNativeHandoffStructuralWitnessStrong
            | DynamicJoinNativeHandoffDirectReplayContinuation
            | DynamicJoinNativeHandoffCyclePoisonFailClosed

        let dynamicJoinNativeHandoffStrengthText = function
            | DynamicJoinNativeHandoffWeakPhysicalQueue -> "weak_physical_queue_observer_only"
            | DynamicJoinNativeHandoffStructuralWitnessStrong -> "structural_witness_strong_for_native_handoff"
            | DynamicJoinNativeHandoffDirectReplayContinuation -> "direct_replay_continuation_strong_for_handoff"
            | DynamicJoinNativeHandoffCyclePoisonFailClosed -> "cycle_poison_fail_closed_strong_for_handoff"

        let dynamicJoinNativeHandoffStrengthFor promotesReplay (bridgeTailStrong: bool) =
            if promotesReplay then DynamicJoinNativeHandoffDirectReplayContinuation
            elif bridgeTailStrong then DynamicJoinNativeHandoffStructuralWitnessStrong
            else DynamicJoinNativeHandoffCyclePoisonFailClosed

        let nativeTurnOnBlockerText (turnOnGate: NativeHopacTurnOnGateId) =
            match turnOnGate with
            | NativeHopacTurnOnGateOpenNow gate -> "none:" + gate
            | NativeHopacTurnOnGateBlockedByStructuralReentry gate -> "structural_reentry_cycle_poison_required_before_legacy_tick:" + gate
            | NativeHopacTurnOnGateShadowObserverOnly gate -> "shadow_timer_observer_only_after_proof_tuple:" + gate
            | NativeHopacTurnOnGateLegacyForbidden gate -> "legacy_scheduler_forbidden_after_native_witness:" + gate
        type NativeWakeContinuationEdgeId =
            | NativeWakeEdgeApplySpineStore
            | NativeWakeEdgePendingGraphTerminal
            | NativeWakeEdgePendingGraphCommittedTerminal
            | NativeWakeEdgeCooperativeReplayNativeBind
            | NativeWakeEdgeParentReplayStatusPreservedCacheHandoff
            | NativeWakeEdgeIdleCrossKindSidecarCallback
            | NativeWakeEdgeDynamicJoinStackFenceBridge
            | NativeWakeEdgeDynamicJoinBridgeTailHandoff
            | NativeWakeEdgeObservedPinnedImmediateFill
            | NativeWakeEdgeDynamicBridge
            | NativeWakeEdgeDynamicJoinReplay
            | NativeWakeEdgeWriterlessQueueDrain
            | NativeWakeEdgeObservedPinnedTerminal
            | NativeWakeEdgeSemanticStaleRetarget
            | NativeWakeEdgeParentReplayCycleBreak
            | NativeWakeEdgeParentContinuation
            | NativeWakeEdgeCrossKindSibling
            | NativeWakeEdgeSidecarDrain
            | NativeWakeEdgeGraftRepair
            | NativeWakeEdgeUnknown
        type NativeWakeGraphShapeId =
            | NativeWakeGraphFilled of ivar:string * edge:NativeWakeContinuationEdgeId * expected:NativeWakeExpectedDeltaId
            | NativeWakeGraphPendingGraft of parent:string * edge:NativeWakeContinuationEdgeId
            | NativeWakeGraphUnboundIsland of owner:string
        type NativeCallbackReturnId =
            | NativeCallbackReturnNoFurtherDelta
            | NativeCallbackReturnPlateauPoison
            | NativeCallbackReturnExecuteDirectAstEval
            | NativeCallbackReturnResolveParentPromise
            | NativeCallbackReturnForceGraftRepair
            | NativeCallbackReturnForbiddenLegacyWorklist

        let nativeWakeContinuationEdgeFor = function
            | NativeWakeExpectedDeltaApplySpineStore -> NativeWakeEdgeApplySpineStore
            | NativeWakeExpectedDeltaPendingGraphTerminal -> NativeWakeEdgePendingGraphTerminal
            | NativeWakeExpectedDeltaPendingGraphCommittedTerminal -> NativeWakeEdgePendingGraphCommittedTerminal
            | NativeWakeExpectedDeltaCooperativeReplayNativeBind -> NativeWakeEdgeCooperativeReplayNativeBind
            | NativeWakeExpectedDeltaParentReplayStatusPreservedCacheHandoff -> NativeWakeEdgeParentReplayStatusPreservedCacheHandoff
            | NativeWakeExpectedDeltaIdleCrossKindSidecarCallback -> NativeWakeEdgeIdleCrossKindSidecarCallback
            | NativeWakeExpectedDeltaDynamicJoinStackFenceBridge -> NativeWakeEdgeDynamicJoinStackFenceBridge
            | NativeWakeExpectedDeltaDynamicJoinBridgeTailHandoff -> NativeWakeEdgeDynamicJoinBridgeTailHandoff
            | NativeWakeExpectedDeltaObservedPinnedImmediateFill -> NativeWakeEdgeObservedPinnedImmediateFill
            | NativeWakeExpectedDeltaDynamicBridge -> NativeWakeEdgeDynamicBridge
            | NativeWakeExpectedDeltaDynamicJoinReplay -> NativeWakeEdgeDynamicJoinReplay
            | NativeWakeExpectedDeltaWriterlessQueueDrain -> NativeWakeEdgeWriterlessQueueDrain
            | NativeWakeExpectedDeltaObservedPinnedTerminal -> NativeWakeEdgeObservedPinnedTerminal
            | NativeWakeExpectedDeltaSemanticStaleRetarget -> NativeWakeEdgeSemanticStaleRetarget
            | NativeWakeExpectedDeltaParentReplayCycleBreak -> NativeWakeEdgeParentReplayCycleBreak
            | NativeWakeExpectedDeltaParentContinuation -> NativeWakeEdgeParentContinuation
            | NativeWakeExpectedDeltaCrossKindSibling -> NativeWakeEdgeCrossKindSibling
            | NativeWakeExpectedDeltaSidecarDrain -> NativeWakeEdgeSidecarDrain
            | NativeWakeExpectedDeltaGraftRepair -> NativeWakeEdgeGraftRepair
            | NativeWakeExpectedDeltaNone -> NativeWakeEdgeUnknown

        let nativeWakeContinuationEdgeText = function
            | NativeWakeEdgeApplySpineStore -> "apply_spine_store"
            | NativeWakeEdgePendingGraphTerminal -> "pending_graph_terminal"
            | NativeWakeEdgePendingGraphCommittedTerminal -> "pending_graph_committed_terminal"
            | NativeWakeEdgeCooperativeReplayNativeBind -> "cooperative_replay_native_bind"
            | NativeWakeEdgeParentReplayStatusPreservedCacheHandoff -> "parent_replay_status_preserved_cache_handoff"
            | NativeWakeEdgeIdleCrossKindSidecarCallback -> "idle_cross_kind_sidecar_callback"
            | NativeWakeEdgeDynamicJoinStackFenceBridge -> "dynamic_join_stack_fence_bridge"
            | NativeWakeEdgeDynamicJoinBridgeTailHandoff -> "dynamic_join_bridge_tail_handoff"
            | NativeWakeEdgeObservedPinnedImmediateFill -> "observed_pinned_immediate_fill"
            | NativeWakeEdgeDynamicBridge -> "dynamic_bridge"
            | NativeWakeEdgeDynamicJoinReplay -> "dynamic_join_replay"
            | NativeWakeEdgeWriterlessQueueDrain -> "writerless_queue_drain"
            | NativeWakeEdgeObservedPinnedTerminal -> "observed_pinned_terminal"
            | NativeWakeEdgeSemanticStaleRetarget -> "semantic_stale_retarget"
            | NativeWakeEdgeParentReplayCycleBreak -> "parent_replay_cycle_break"
            | NativeWakeEdgeParentContinuation -> "parent_continuation"
            | NativeWakeEdgeCrossKindSibling -> "cross_kind_sibling"
            | NativeWakeEdgeSidecarDrain -> "sidecar_drain"
            | NativeWakeEdgeGraftRepair -> "graft_repair"
            | NativeWakeEdgeUnknown -> "unknown"

        let nativeWakeGraphShapeText = function
            | NativeWakeGraphFilled(ivar, edge, expected) -> "filled(" + ivar + ")->" + nativeWakeContinuationEdgeText edge + "->" + nativeWakeExpectedDeltaText expected
            | NativeWakeGraphPendingGraft(parent, edge) -> "pending_graft(" + parent + ")->" + nativeWakeContinuationEdgeText edge
            | NativeWakeGraphUnboundIsland(owner) -> "unbound_island(" + owner + ")"

        let nativeWakeGraphShapeFor ivar parent bindingState expectedDeltaId =
            let edge = nativeWakeContinuationEdgeFor expectedDeltaId
            match bindingState with
            | NativeWakeUnboundTopologicalIsland -> NativeWakeGraphUnboundIsland parent
            | NativeWakeBoundParentContinuationNoDeltaStarved -> NativeWakeGraphPendingGraft(parent, edge)
            | _ -> NativeWakeGraphFilled(ivar, edge, expectedDeltaId)

        let nativeCallbackReturnText = function
            | NativeCallbackReturnNoFurtherDelta -> "return_NoFurtherDeltaPossible"
            | NativeCallbackReturnPlateauPoison -> "return_NativePromiseFailed_PlateauPoison"
            | NativeCallbackReturnExecuteDirectAstEval -> "execute_native_direct_ast_eval_then_return_native_promise_result"
            | NativeCallbackReturnResolveParentPromise -> "resolve_parent_promise_then_return_native_promise_result"
            | NativeCallbackReturnForceGraftRepair -> "force_parent_graft_repair_then_return_native_promise_result"
            | NativeCallbackReturnForbiddenLegacyWorklist -> "FORBIDDEN_explicit_eval_worklist_return"

        // MIGRATION: start the multi-round assessment streak by making the
        // consumer result and cross-kind owner visible as typed facts.
        // MIGRATION: move continuation target status from text-only probes into
        // a real DU so consumer-delta and direct-eval contracts cannot compare
        // magic strings in the hot native Hopac path.
        type NativeWakeContinuationTargetStatusId =
            | NativeWakeTargetApplySpineStore
            | NativeWakeTargetPendingGraphTerminal
            | NativeWakeTargetPendingGraphCommittedTerminal
            | NativeWakeTargetCooperativeReplayNativeBind
            | NativeWakeTargetParentReplayStatusPreservedCacheHandoff
            | NativeWakeTargetIdleCrossKindSidecarCallback
            | NativeWakeTargetDynamicJoinStackFenceBridge
            | NativeWakeTargetDynamicJoinBridgeTailHandoff
            | NativeWakeTargetObservedPinnedImmediateFill
            | NativeWakeTargetDynamicBridge
            | NativeWakeTargetDynamicJoinReplay
            | NativeWakeTargetWriterlessQueueDrain
            | NativeWakeTargetObservedPinnedTerminal
            | NativeWakeTargetSemanticStaleRetarget
            | NativeWakeTargetRunnableParentContinuation
            | NativeWakeTargetWaitingCrossKind
            | NativeWakeTargetSidecarDrain
            | NativeWakeTargetPoisoned
            | NativeWakeTargetUnknown

        // The previous fields proved a wake existed; these fields ask the stricter
        // question: did the unblocked closure own a real semantic delta, or did
        // it defer back into a cultural worklist-shaped phantom limb?
        type NativeWakeConsumerDeltaResultId =
            | NativeWakeConsumerDeltaProduced
            | NativeWakeConsumerDeltaPureAstStep
            | NativeWakeConsumerDeltaForcedDirectEval
            | NativeWakeConsumerDeltaExpectedButDeferred
            | NativeWakeConsumerDeltaNotExpected
            | NativeWakeConsumerDeltaPoisonOnly
            | NativeWakeConsumerDeltaTopologicalResolution

        let nativeWakeConsumerDeltaResultFor (expectedDeltaId: NativeWakeExpectedDeltaId) sampledDelta replayDelta rootDelta terminalDelta (continuationStatusId: NativeWakeContinuationTargetStatusId) =
            let semanticDelta = rootDelta > 0L || terminalDelta > 0L
            let topologyOnlyDelta = not semanticDelta && (sampledDelta > 0L || replayDelta > 0L)
            let sidecarOrCooperativeTopologyOnly =
                topologyOnlyDelta &&
                    (continuationStatusId = NativeWakeTargetIdleCrossKindSidecarCallback
                     || continuationStatusId = NativeWakeTargetSidecarDrain
                     || continuationStatusId = NativeWakeTargetCooperativeReplayNativeBind
                     || continuationStatusId = NativeWakeTargetParentReplayStatusPreservedCacheHandoff
                     || continuationStatusId = NativeWakeTargetRunnableParentContinuation)
            if semanticDelta then NativeWakeConsumerDeltaProduced
            elif sidecarOrCooperativeTopologyOnly && (continuationStatusId = NativeWakeTargetIdleCrossKindSidecarCallback || continuationStatusId = NativeWakeTargetSidecarDrain) then NativeWakeConsumerDeltaPureAstStep
            elif sidecarOrCooperativeTopologyOnly then NativeWakeConsumerDeltaForcedDirectEval
            elif topologyOnlyDelta then NativeWakeConsumerDeltaProduced
            elif continuationStatusId = NativeWakeTargetPoisoned && expectedDeltaId = NativeWakeExpectedDeltaParentReplayCycleBreak then NativeWakeConsumerDeltaTopologicalResolution
            elif continuationStatusId = NativeWakeTargetPoisoned then NativeWakeConsumerDeltaPoisonOnly
            elif nativeWakeExpectedDeltaFlag expectedDeltaId then
                match continuationStatusId with
                | NativeWakeTargetCooperativeReplayNativeBind
                | NativeWakeTargetParentReplayStatusPreservedCacheHandoff
                | NativeWakeTargetPendingGraphCommittedTerminal
                | NativeWakeTargetPendingGraphTerminal
                | NativeWakeTargetObservedPinnedTerminal
                | NativeWakeTargetObservedPinnedImmediateFill
                | NativeWakeTargetDynamicBridge
                | NativeWakeTargetDynamicJoinReplay
                | NativeWakeTargetDynamicJoinBridgeTailHandoff
                | NativeWakeTargetDynamicJoinStackFenceBridge
                | NativeWakeTargetSemanticStaleRetarget
                | NativeWakeTargetWriterlessQueueDrain
                | NativeWakeTargetRunnableParentContinuation -> NativeWakeConsumerDeltaForcedDirectEval
                | NativeWakeTargetIdleCrossKindSidecarCallback
                | NativeWakeTargetSidecarDrain -> NativeWakeConsumerDeltaPureAstStep
                | _ -> NativeWakeConsumerDeltaExpectedButDeferred
            else NativeWakeConsumerDeltaNotExpected

        let nativeWakeConsumerDeltaResultText = function
            | NativeWakeConsumerDeltaProduced -> "consumer_produced_work_delta"
            | NativeWakeConsumerDeltaPureAstStep -> "consumer_executed_pure_ast_step_no_sidecar_requery"
            | NativeWakeConsumerDeltaForcedDirectEval -> "consumer_forced_direct_eval_delta_before_metronome"
            | NativeWakeConsumerDeltaExpectedButDeferred -> "consumer_expected_delta_but_deferred"
            | NativeWakeConsumerDeltaNotExpected -> "consumer_delta_not_expected"
            | NativeWakeConsumerDeltaPoisonOnly -> "consumer_poison_only_no_structural_delta"
            | NativeWakeConsumerDeltaTopologicalResolution -> "consumer_topological_cycle_resolution_no_counter_delta"

        type NativeCrossKindObligationDetailId =
            | NativeCrossKindObligationNone
            | NativeCrossKindObligationApplySpineStoreOwnsWindow
            | NativeCrossKindObligationPendingGraphTerminalOwnsWindow
            | NativeCrossKindObligationPendingGraphCommittedTerminalOwnsWindow
            | NativeCrossKindObligationCooperativeReplayNativeBindOwnsWindow
            | NativeCrossKindObligationParentReplayStatusPreservedCacheHandoffOwnsWindow
            | NativeCrossKindObligationIdleCrossKindSidecarCallbackOwnsWindow
            | NativeCrossKindObligationDynamicJoinStackFenceBridgeOwnsWindow
            | NativeCrossKindObligationDynamicJoinBridgeTailHandoffOwnsWindow
            | NativeCrossKindObligationObservedPinnedImmediateFillOwnsWindow
            | NativeCrossKindObligationDynamicBridgeOwnsWindow
            | NativeCrossKindObligationDynamicJoinReplayOwnsWindow
            | NativeCrossKindObligationWriterlessQueueDrainOwnsWindow
            | NativeCrossKindObligationObservedPinnedTerminalOwnsWindow
            | NativeCrossKindObligationSemanticStaleRetargetOwnsWindow
            | NativeCrossKindObligationParentReplayCycleBreakOwnsWindow
            | NativeCrossKindObligationSidecarDrainOwnsWindow
            | NativeCrossKindObligationParentContinuationPending
            | NativeCrossKindObligationSiblingReplayWaiting
            | NativeCrossKindObligationGraftRepairOwnsWindow

        let nativeCrossKindObligationDetailFor (expectedDeltaId: NativeWakeExpectedDeltaId) (continuationStatusId: NativeWakeContinuationTargetStatusId) (graftStatusId: NativeWakeParentJobBindGraftStatusId) =
            match expectedDeltaId with
            | NativeWakeExpectedDeltaApplySpineStore -> NativeCrossKindObligationApplySpineStoreOwnsWindow
            | NativeWakeExpectedDeltaPendingGraphTerminal -> NativeCrossKindObligationPendingGraphTerminalOwnsWindow
            | NativeWakeExpectedDeltaPendingGraphCommittedTerminal -> NativeCrossKindObligationPendingGraphCommittedTerminalOwnsWindow
            | NativeWakeExpectedDeltaCooperativeReplayNativeBind -> NativeCrossKindObligationCooperativeReplayNativeBindOwnsWindow
            | NativeWakeExpectedDeltaParentReplayStatusPreservedCacheHandoff -> NativeCrossKindObligationParentReplayStatusPreservedCacheHandoffOwnsWindow
            | NativeWakeExpectedDeltaIdleCrossKindSidecarCallback -> NativeCrossKindObligationIdleCrossKindSidecarCallbackOwnsWindow
            | NativeWakeExpectedDeltaDynamicJoinStackFenceBridge -> NativeCrossKindObligationDynamicJoinStackFenceBridgeOwnsWindow
            | NativeWakeExpectedDeltaDynamicJoinBridgeTailHandoff -> NativeCrossKindObligationDynamicJoinBridgeTailHandoffOwnsWindow
            | NativeWakeExpectedDeltaObservedPinnedImmediateFill -> NativeCrossKindObligationObservedPinnedImmediateFillOwnsWindow
            | NativeWakeExpectedDeltaDynamicBridge -> NativeCrossKindObligationDynamicBridgeOwnsWindow
            | NativeWakeExpectedDeltaDynamicJoinReplay -> NativeCrossKindObligationDynamicJoinReplayOwnsWindow
            | NativeWakeExpectedDeltaWriterlessQueueDrain -> NativeCrossKindObligationWriterlessQueueDrainOwnsWindow
            | NativeWakeExpectedDeltaObservedPinnedTerminal -> NativeCrossKindObligationObservedPinnedTerminalOwnsWindow
            | NativeWakeExpectedDeltaSemanticStaleRetarget -> NativeCrossKindObligationSemanticStaleRetargetOwnsWindow
            | NativeWakeExpectedDeltaParentReplayCycleBreak -> NativeCrossKindObligationParentReplayCycleBreakOwnsWindow
            | NativeWakeExpectedDeltaSidecarDrain -> NativeCrossKindObligationSidecarDrainOwnsWindow
            | NativeWakeExpectedDeltaParentContinuation -> NativeCrossKindObligationParentContinuationPending
            | NativeWakeExpectedDeltaCrossKindSibling -> NativeCrossKindObligationSiblingReplayWaiting
            | NativeWakeExpectedDeltaGraftRepair -> NativeCrossKindObligationGraftRepairOwnsWindow
            | NativeWakeExpectedDeltaNone when graftStatusId = NativeWakeParentJobBindGraftPendingForceReplay -> NativeCrossKindObligationGraftRepairOwnsWindow
            | NativeWakeExpectedDeltaNone when continuationStatusId = NativeWakeTargetSidecarDrain -> NativeCrossKindObligationSidecarDrainOwnsWindow
            | _ -> NativeCrossKindObligationNone

        let nativeCrossKindObligationDetailText = function
            | NativeCrossKindObligationNone -> "none"
            | NativeCrossKindObligationApplySpineStoreOwnsWindow -> "apply_spine_store_owns_window"
            | NativeCrossKindObligationPendingGraphTerminalOwnsWindow -> "pending_graph_terminal_owns_window"
            | NativeCrossKindObligationPendingGraphCommittedTerminalOwnsWindow -> "pending_graph_committed_terminal_owns_window"
            | NativeCrossKindObligationCooperativeReplayNativeBindOwnsWindow -> "cooperative_replay_native_bind_owns_window"
            | NativeCrossKindObligationParentReplayStatusPreservedCacheHandoffOwnsWindow -> "parent_replay_status_preserved_cache_handoff_owns_window"
            | NativeCrossKindObligationIdleCrossKindSidecarCallbackOwnsWindow -> "idle_cross_kind_sidecar_callback_owns_window"
            | NativeCrossKindObligationDynamicJoinStackFenceBridgeOwnsWindow -> "dynamic_join_stack_fence_bridge_owns_window"
            | NativeCrossKindObligationDynamicJoinBridgeTailHandoffOwnsWindow -> "dynamic_join_bridge_tail_handoff_owns_window"
            | NativeCrossKindObligationObservedPinnedImmediateFillOwnsWindow -> "observed_pinned_immediate_fill_owns_window"
            | NativeCrossKindObligationDynamicBridgeOwnsWindow -> "dynamic_bridge_owns_window"
            | NativeCrossKindObligationDynamicJoinReplayOwnsWindow -> "dynamic_join_replay_owns_window"
            | NativeCrossKindObligationWriterlessQueueDrainOwnsWindow -> "writerless_queue_drain_owns_window"
            | NativeCrossKindObligationObservedPinnedTerminalOwnsWindow -> "observed_pinned_terminal_owns_window"
            | NativeCrossKindObligationSemanticStaleRetargetOwnsWindow -> "semantic_stale_retarget_owns_direct_eval_window"
            | NativeCrossKindObligationParentReplayCycleBreakOwnsWindow -> "parent_replay_cycle_break_owns_window"
            | NativeCrossKindObligationSidecarDrainOwnsWindow -> "sidecar_drain_owns_window"
            | NativeCrossKindObligationParentContinuationPending -> "parent_continuation_pending"
            | NativeCrossKindObligationSiblingReplayWaiting -> "cross_kind_sibling_waiting"
            | NativeCrossKindObligationGraftRepairOwnsWindow -> "graft_repair_owns_window"

        type NativeDirectEvaluationContractId =
            | NativeDirectEvaluationNoContract
            | NativeDirectEvaluationApplySpineStore
            | NativeDirectEvaluationPendingGraphTerminal
            | NativeDirectEvaluationPendingGraphCommittedTerminal
            | NativeDirectEvaluationCooperativeReplayNativeBind
            | NativeDirectEvaluationParentReplayStatusPreservedCacheHandoff
            | NativeDirectEvaluationIdleCrossKindSidecarCallback
            | NativeDirectEvaluationDynamicJoinStackFenceBridge
            | NativeDirectEvaluationDynamicJoinBridgeTailHandoff
            | NativeDirectEvaluationObservedPinnedImmediateFill
            | NativeDirectEvaluationDynamicBridge
            | NativeDirectEvaluationDynamicJoinApply
            | NativeDirectEvaluationWriterlessQueueDrain
            | NativeDirectEvaluationObservedPinnedTerminal
            | NativeDirectEvaluationSemanticStaleRetarget
            | NativeDirectEvaluationParentReplayCycleBreak
            | NativeDirectEvaluationParentContinuation
            | NativeDirectEvaluationTySidecarDrain
            | NativeDirectEvaluationCrossKindSidecar

        let nativeDirectEvaluationContractFor (expectedDeltaId: NativeWakeExpectedDeltaId) (continuationStatusId: NativeWakeContinuationTargetStatusId) =
            match expectedDeltaId, continuationStatusId with
            | NativeWakeExpectedDeltaApplySpineStore, _ -> NativeDirectEvaluationApplySpineStore
            | NativeWakeExpectedDeltaPendingGraphTerminal, _ -> NativeDirectEvaluationPendingGraphTerminal
            | NativeWakeExpectedDeltaPendingGraphCommittedTerminal, _ -> NativeDirectEvaluationPendingGraphCommittedTerminal
            | NativeWakeExpectedDeltaCooperativeReplayNativeBind, _ -> NativeDirectEvaluationCooperativeReplayNativeBind
            | NativeWakeExpectedDeltaParentReplayStatusPreservedCacheHandoff, _ -> NativeDirectEvaluationParentReplayStatusPreservedCacheHandoff
            | NativeWakeExpectedDeltaIdleCrossKindSidecarCallback, _ -> NativeDirectEvaluationIdleCrossKindSidecarCallback
            | NativeWakeExpectedDeltaDynamicJoinStackFenceBridge, _ -> NativeDirectEvaluationDynamicJoinStackFenceBridge
            | NativeWakeExpectedDeltaDynamicJoinBridgeTailHandoff, _ -> NativeDirectEvaluationDynamicJoinBridgeTailHandoff
            | NativeWakeExpectedDeltaObservedPinnedImmediateFill, _ -> NativeDirectEvaluationObservedPinnedImmediateFill
            | NativeWakeExpectedDeltaDynamicBridge, _ -> NativeDirectEvaluationDynamicBridge
            | NativeWakeExpectedDeltaDynamicJoinReplay, _ -> NativeDirectEvaluationDynamicJoinApply
            | NativeWakeExpectedDeltaWriterlessQueueDrain, _ -> NativeDirectEvaluationWriterlessQueueDrain
            | NativeWakeExpectedDeltaObservedPinnedTerminal, _ -> NativeDirectEvaluationObservedPinnedTerminal
            | NativeWakeExpectedDeltaSemanticStaleRetarget, _ -> NativeDirectEvaluationSemanticStaleRetarget
            | NativeWakeExpectedDeltaParentReplayCycleBreak, _ -> NativeDirectEvaluationParentReplayCycleBreak
            | NativeWakeExpectedDeltaParentContinuation, _ -> NativeDirectEvaluationParentContinuation
            | NativeWakeExpectedDeltaCrossKindSibling, _ -> NativeDirectEvaluationCrossKindSidecar
            | NativeWakeExpectedDeltaSidecarDrain, _ -> NativeDirectEvaluationTySidecarDrain
            | NativeWakeExpectedDeltaGraftRepair, _ -> NativeDirectEvaluationDynamicJoinApply
            | NativeWakeExpectedDeltaNone, NativeWakeTargetDynamicBridge -> NativeDirectEvaluationDynamicBridge
            | NativeWakeExpectedDeltaNone, NativeWakeTargetDynamicJoinReplay -> NativeDirectEvaluationDynamicJoinApply
            | NativeWakeExpectedDeltaNone, NativeWakeTargetWriterlessQueueDrain -> NativeDirectEvaluationWriterlessQueueDrain
            | NativeWakeExpectedDeltaNone, NativeWakeTargetObservedPinnedTerminal -> NativeDirectEvaluationObservedPinnedTerminal
            | NativeWakeExpectedDeltaNone, NativeWakeTargetSemanticStaleRetarget -> NativeDirectEvaluationSemanticStaleRetarget
            | NativeWakeExpectedDeltaNone, NativeWakeTargetRunnableParentContinuation -> NativeDirectEvaluationParentContinuation
            | _ -> NativeDirectEvaluationNoContract

        let nativeDirectEvaluationContractText = function
            | NativeDirectEvaluationNoContract -> "none"
            | NativeDirectEvaluationApplySpineStore -> "native_direct_ast_eval_apply_spine_store_return_native_promise_result"
            | NativeDirectEvaluationPendingGraphTerminal -> "native_direct_ast_eval_pending_graph_terminal_return_native_promise_result"
            | NativeDirectEvaluationPendingGraphCommittedTerminal -> "native_direct_ast_eval_pending_graph_committed_terminal_return_native_promise_result"
            | NativeDirectEvaluationCooperativeReplayNativeBind -> "native_direct_ast_eval_cooperative_replay_native_bind_return_native_promise_result"
            | NativeDirectEvaluationParentReplayStatusPreservedCacheHandoff -> "native_direct_ast_eval_parent_replay_status_preserved_cache_handoff_return_native_promise_result"
            | NativeDirectEvaluationIdleCrossKindSidecarCallback -> "native_direct_ast_eval_idle_cross_kind_sidecar_callback_return_native_promise_result"
            | NativeDirectEvaluationDynamicJoinStackFenceBridge -> "native_direct_ast_eval_dynamic_join_stack_fence_bridge_return_native_promise_result"
            | NativeDirectEvaluationDynamicJoinBridgeTailHandoff -> "native_direct_ast_eval_dynamic_join_bridge_tail_handoff_return_native_promise_result"
            | NativeDirectEvaluationObservedPinnedImmediateFill -> "native_direct_ast_eval_observed_pinned_immediate_fill_return_native_promise_result"
            | NativeDirectEvaluationDynamicBridge -> "native_direct_ast_eval_dynamic_record_key_bridge_parent_return_native_promise_result"
            | NativeDirectEvaluationDynamicJoinApply -> "native_direct_ast_eval_dynamic_join_apply_return_native_promise_result"
            | NativeDirectEvaluationWriterlessQueueDrain -> "native_direct_ast_eval_writerless_queue_drain_return_native_promise_result"
            | NativeDirectEvaluationObservedPinnedTerminal -> "native_direct_ast_eval_observed_pinned_terminal_return_native_promise_result"
            | NativeDirectEvaluationSemanticStaleRetarget -> "native_direct_ast_eval_semantic_stale_retarget_shadow_timeout_return_native_promise_result"
            | NativeDirectEvaluationParentReplayCycleBreak -> "native_direct_ast_eval_parent_replay_cycle_break_return_native_promise_result"
            | NativeDirectEvaluationParentContinuation -> "native_direct_ast_eval_parent_continuation_return_native_promise_result"
            | NativeDirectEvaluationTySidecarDrain -> "native_direct_ast_eval_ty_sidecar_drain_pure_ast_step_no_sidecar_requery_return_native_promise_result"
            | NativeDirectEvaluationCrossKindSidecar -> "native_direct_ast_eval_cross_kind_sidecar_return_native_promise_result"

        let nativeDirectEvaluationSemanticPlateauKind = function
            | NativeDirectEvaluationCooperativeReplayNativeBind -> Some NativeClosureCooperativeReplayNativeBind
            | NativeDirectEvaluationParentReplayStatusPreservedCacheHandoff -> Some NativeClosureParentReplayStatusPreservedCacheHandoff
            | NativeDirectEvaluationParentReplayCycleBreak -> Some NativeClosureParentReplayPoison
            | NativeDirectEvaluationParentContinuation -> Some NativeClosureParentCacheHandoffWake
            | NativeDirectEvaluationDynamicBridge -> Some NativeClosureDynamicRecordKeyBridgeTail
            | NativeDirectEvaluationDynamicJoinBridgeTailHandoff -> Some NativeClosureDynamicRecordKeyBridgeTail
            | NativeDirectEvaluationTySidecarDrain -> Some NativeClosureTySidecarDrain
            | NativeDirectEvaluationIdleCrossKindSidecarCallback -> Some NativeClosureTySidecarDrain
            | NativeDirectEvaluationCrossKindSidecar -> Some NativeClosureTySidecarDrain
            | _ -> None

        type NativeDirectEvaluationSemanticStateId =
            | NativeDirectEvaluationSemanticFactsAvailablePlateauCapable of factCount:int64 * kind:NativeClosureKindId
            | NativeDirectEvaluationSemanticFactsAvailableWithoutPlateauAuthority of factCount:int64
            | NativeDirectEvaluationSemanticFactsAbsentPlateauCapable of kind:NativeClosureKindId
            | NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority

        let nativeDirectEvaluationSemanticStateFor directContractId semanticFactCount =
            match nativeDirectEvaluationSemanticPlateauKind directContractId with
            | Some kind when semanticFactCount > 0L ->
                NativeDirectEvaluationSemanticFactsAvailablePlateauCapable(semanticFactCount, kind)
            | None when semanticFactCount > 0L ->
                NativeDirectEvaluationSemanticFactsAvailableWithoutPlateauAuthority semanticFactCount
            | Some kind -> NativeDirectEvaluationSemanticFactsAbsentPlateauCapable kind
            | None -> NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority

        let nativeDirectEvaluationSemanticStateText = function
            | NativeDirectEvaluationSemanticFactsAvailablePlateauCapable(factCount, kind) ->
                "FactsAvailablePlateauCapable(count=" + string factCount + "|kind=" + nativeClosureKindText kind + ")"
            | NativeDirectEvaluationSemanticFactsAvailableWithoutPlateauAuthority factCount ->
                "FactsAvailableWithoutPlateauAuthority(count=" + string factCount + ")"
            | NativeDirectEvaluationSemanticFactsAbsentPlateauCapable kind ->
                "FactsAbsentPlateauCapable(kind=" + nativeClosureKindText kind + ")"
            | NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority ->
                "FactsAbsentWithoutPlateauAuthority"

        type NativePureTopologyWitnessReasonId =
            | NativePureTopologyWitnessConsumerDeltaBeforeSemanticFact
            | NativePureTopologyWitnessTerminalActionLivenessGateDeferred of livenessGateText:string

        let private nativePureTopologyWitnessReasonText = function
            | NativePureTopologyWitnessConsumerDeltaBeforeSemanticFact -> "consumer_delta_produced_topology_witness_before_semantic_fact"
            | NativePureTopologyWitnessTerminalActionLivenessGateDeferred livenessGateText -> "terminal_action_liveness_gate_deferred|" + livenessGateText

        type NativeSemanticPlateauPoisonReasonId =
            | NativeSemanticPlateauPureAstStepReturnedPromiseWithoutFact
            | NativeSemanticPlateauForcedDirectEvalReturnedPromiseWithoutFact
            | NativeSemanticPlateauProofTupleJobBindReturnedPromiseWithoutFact

        let private nativeSemanticPlateauPoisonReasonText = function
            | NativeSemanticPlateauPureAstStepReturnedPromiseWithoutFact -> "pure_ast_step_returned_native_promise_result_without_semantic_fact"
            | NativeSemanticPlateauForcedDirectEvalReturnedPromiseWithoutFact -> "forced_direct_eval_returned_native_promise_result_without_semantic_fact"
            | NativeSemanticPlateauProofTupleJobBindReturnedPromiseWithoutFact -> "proof_tuple_job_bind_returned_native_promise_result_without_semantic_fact"

        let nativeDirectEvaluationSemanticPlateauPayload contract kind reason =
            "PlateauPoison(contract=" + nativeDirectEvaluationContractText contract + "|kind=" + nativeClosureKindText kind + "|semantic_fact_count=0|reason=" + nativeSemanticPlateauPoisonReasonText reason + ")"

        type NativeAstEvaluationDeltaResultId =
            | NativeAstDeltaMeasuredCounterDelta
            | NativeAstDeltaExecutePureAstStep of contract:NativeDirectEvaluationContractId
            | NativeAstDeltaPureTopologyWitnessMaterialized of contract:NativeDirectEvaluationContractId * kind:NativeClosureKindId * reason:NativePureTopologyWitnessReasonId
            | NativeAstDeltaCyclePoisonInjected of payload:string
            | NativeAstDeltaSemanticPlateauPoison of contract:NativeDirectEvaluationContractId * kind:NativeClosureKindId * reason:NativeSemanticPlateauPoisonReasonId
            | NativeAstDeltaBlockedLegacyFallback of contract:NativeDirectEvaluationContractId
            | NativeAstDeltaNoContractLegacyForbidden

        let nativeAstEvaluationDeltaResultText = function
            | NativeAstDeltaMeasuredCounterDelta -> "DirectEvalProducedDelta(measured_counter_delta)"
            | NativeAstDeltaExecutePureAstStep contract -> "DirectEvalProducedDelta(pure_ast_step=" + nativeDirectEvaluationContractText contract + ")"
            | NativeAstDeltaPureTopologyWitnessMaterialized(contract, kind, reason) -> "DirectEvalProducedDelta(pure_topology_witness_materialized|contract=" + nativeDirectEvaluationContractText contract + "|kind=" + nativeClosureKindText kind + "|reason=" + nativePureTopologyWitnessReasonText reason + ")"
            | NativeAstDeltaCyclePoisonInjected payload -> "NativePromiseFailed(cycle_break_algebraic_payload=" + payload + "|propagation=monadic_poison_not_native_promise_result)"
            | NativeAstDeltaSemanticPlateauPoison(contract, kind, reason) -> "NativePromiseFailed(plateau_poison=" + nativeDirectEvaluationSemanticPlateauPayload contract kind reason + "|propagation=monadic_poison_not_native_promise_result)"
            | NativeAstDeltaBlockedLegacyFallback contract -> "DeferredNoDelta(blocked_legacy_fallback_after_direct_wake_reentry|contract=" + nativeDirectEvaluationContractText contract + ")"
            | NativeAstDeltaNoContractLegacyForbidden -> "DeferredNoDelta(no_direct_eval_contract_legacy_forbidden)"

        let nativeAstEvaluationDeltaResultFor consumerDeltaId directContractId structuralCycleId payloadEnvelopeId semanticFactCount =
            let semanticState = nativeDirectEvaluationSemanticStateFor directContractId semanticFactCount
            match consumerDeltaId, directContractId, structuralCycleId, payloadEnvelopeId, semanticState with
            | NativeWakeConsumerDeltaProduced, _, _, _, NativeDirectEvaluationSemanticFactsAvailablePlateauCapable _
            | NativeWakeConsumerDeltaProduced, _, _, _, NativeDirectEvaluationSemanticFactsAvailableWithoutPlateauAuthority _ ->
                NativeAstDeltaMeasuredCounterDelta
            | NativeWakeConsumerDeltaProduced, _, _, _, NativeDirectEvaluationSemanticFactsAbsentPlateauCapable kind ->
                NativeAstDeltaPureTopologyWitnessMaterialized(directContractId, kind, NativePureTopologyWitnessConsumerDeltaBeforeSemanticFact)
            | NativeWakeConsumerDeltaProduced, _, _, _, NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority ->
                NativeAstDeltaMeasuredCounterDelta
            | NativeWakeConsumerDeltaTopologicalResolution, _, _, NativeWakePayloadCyclePoison(payload, _, _), _ -> NativeAstDeltaCyclePoisonInjected payload
            | NativeWakeConsumerDeltaPoisonOnly, _, _, NativeWakePayloadCyclePoison(payload, _, _), _ -> NativeAstDeltaCyclePoisonInjected payload
            | NativeWakeConsumerDeltaPureAstStep, NativeDirectEvaluationNoContract, _, _, _ -> NativeAstDeltaNoContractLegacyForbidden
            | NativeWakeConsumerDeltaForcedDirectEval, NativeDirectEvaluationNoContract, _, _, _ -> NativeAstDeltaNoContractLegacyForbidden
            | NativeWakeConsumerDeltaExpectedButDeferred, NativeDirectEvaluationNoContract, _, _, _ -> NativeAstDeltaNoContractLegacyForbidden
            | NativeWakeConsumerDeltaForcedDirectEval, _, NativeStructuralCycleDirectWakeReentry(node, reentryEdge), NativeWakePayloadResolution(payload, witness, sourceEdge), _
            | NativeWakeConsumerDeltaPureAstStep, _, NativeStructuralCycleDirectWakeReentry(node, reentryEdge), NativeWakePayloadResolution(payload, witness, sourceEdge), _ ->
                NativeAstDeltaCyclePoisonInjected ("CyclePoison(depth=direct_wake_reentry|node=" + node + "|edge=" + reentryEdge + "|payload=" + payload + "|witness=" + witness + "|source_edge=" + sourceEdge + ")")
            | NativeWakeConsumerDeltaPureAstStep, _, _, _, NativeDirectEvaluationSemanticFactsAvailablePlateauCapable _
            | NativeWakeConsumerDeltaPureAstStep, _, _, _, NativeDirectEvaluationSemanticFactsAvailableWithoutPlateauAuthority _ ->
                NativeAstDeltaExecutePureAstStep directContractId
            | NativeWakeConsumerDeltaPureAstStep, _, _, _, NativeDirectEvaluationSemanticFactsAbsentPlateauCapable kind ->
                NativeAstDeltaSemanticPlateauPoison(directContractId, kind, NativeSemanticPlateauPureAstStepReturnedPromiseWithoutFact)
            | NativeWakeConsumerDeltaPureAstStep, _, _, _, NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority ->
                NativeAstDeltaExecutePureAstStep directContractId
            | NativeWakeConsumerDeltaForcedDirectEval, _, _, _, NativeDirectEvaluationSemanticFactsAvailablePlateauCapable _
            | NativeWakeConsumerDeltaForcedDirectEval, _, _, _, NativeDirectEvaluationSemanticFactsAvailableWithoutPlateauAuthority _ ->
                NativeAstDeltaExecutePureAstStep directContractId
            | NativeWakeConsumerDeltaForcedDirectEval, _, _, _, NativeDirectEvaluationSemanticFactsAbsentPlateauCapable kind ->
                NativeAstDeltaSemanticPlateauPoison(directContractId, kind, NativeSemanticPlateauForcedDirectEvalReturnedPromiseWithoutFact)
            | NativeWakeConsumerDeltaForcedDirectEval, _, _, _, NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority ->
                NativeAstDeltaExecutePureAstStep directContractId
            | NativeWakeConsumerDeltaExpectedButDeferred, _, NativeStructuralCycleDirectWakeReentry(_, _), _, _ -> NativeAstDeltaBlockedLegacyFallback directContractId
            | NativeWakeConsumerDeltaExpectedButDeferred, _, _, _, _ -> NativeAstDeltaBlockedLegacyFallback directContractId
            | _, NativeDirectEvaluationNoContract, _, _, _ -> NativeAstDeltaNoContractLegacyForbidden
            | _ -> NativeAstDeltaExecutePureAstStep directContractId

        let nativeDeltaProducedByConsumerExecutionFlag = function
            | NativeAstDeltaMeasuredCounterDelta
            | NativeAstDeltaExecutePureAstStep _ -> true
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, _, _)
            | NativeAstDeltaCyclePoisonInjected _
            | NativeAstDeltaSemanticPlateauPoison(_, _, _) -> false
            | NativeAstDeltaBlockedLegacyFallback _
            | NativeAstDeltaNoContractLegacyForbidden -> false

        type NativeNoFurtherDeltaDeclarationId =
            | NativeNoFurtherDeltaNotDeclared
            | NativeNoFurtherDeltaPossibleAfterMeasuredDelta
            | NativeNoFurtherDeltaPossibleAfterPureAstStep of contract:NativeDirectEvaluationContractId
            | NativeNoFurtherDeltaPossibleAfterCyclePoison of payload:string
            | NativeNoFurtherDeltaUnsafeMissingConsumerDelta of contract:NativeDirectEvaluationContractId
            | NativeNoFurtherDeltaUnsafeMissingContract

        let nativeNoFurtherDeltaDeclarationText = function
            | NativeNoFurtherDeltaNotDeclared -> "not_declared"
            | NativeNoFurtherDeltaPossibleAfterMeasuredDelta -> "NoFurtherDeltaPossible(after_measured_delta)"
            | NativeNoFurtherDeltaPossibleAfterPureAstStep contract -> "NoFurtherDeltaPossible(after_pure_ast_step_owner_released|contract=" + nativeDirectEvaluationContractText contract + ")"
            | NativeNoFurtherDeltaPossibleAfterCyclePoison payload -> "NoFurtherDeltaPossible(after_cycle_poison_payload=" + payload + ")"
            | NativeNoFurtherDeltaUnsafeMissingConsumerDelta contract -> "unsafe_no_further_delta_missing_consumer_delta(contract=" + nativeDirectEvaluationContractText contract + ")"
            | NativeNoFurtherDeltaUnsafeMissingContract -> "unsafe_no_further_delta_missing_direct_eval_contract"

        let nativeNoFurtherDeltaDeclarationIsPossible = function
            | NativeNoFurtherDeltaPossibleAfterMeasuredDelta
            | NativeNoFurtherDeltaPossibleAfterPureAstStep _
            | NativeNoFurtherDeltaPossibleAfterCyclePoison _ -> true
            | NativeNoFurtherDeltaNotDeclared
            | NativeNoFurtherDeltaUnsafeMissingConsumerDelta _
            | NativeNoFurtherDeltaUnsafeMissingContract -> false

        let nativeNoFurtherDeltaDeclarationFor astDeltaId =
            match astDeltaId with
            | NativeAstDeltaMeasuredCounterDelta -> NativeNoFurtherDeltaPossibleAfterMeasuredDelta
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, _, _) -> NativeNoFurtherDeltaNotDeclared
            | NativeAstDeltaCyclePoisonInjected payload -> NativeNoFurtherDeltaPossibleAfterCyclePoison payload
            | NativeAstDeltaSemanticPlateauPoison(_, _, _) -> NativeNoFurtherDeltaPossibleAfterCyclePoison (nativeAstEvaluationDeltaResultText astDeltaId)
            | NativeAstDeltaExecutePureAstStep contract -> NativeNoFurtherDeltaPossibleAfterPureAstStep contract
            | NativeAstDeltaBlockedLegacyFallback contract -> NativeNoFurtherDeltaUnsafeMissingConsumerDelta contract
            | NativeAstDeltaNoContractLegacyForbidden -> NativeNoFurtherDeltaUnsafeMissingContract

        type NativeConsumerExecutionResultId =
            | NativeConsumerAstDelta of semanticFacts:int64
            | NativeConsumerPlateauPoisonReturned of payload:string
            | NativeConsumerPromiseFailedPoison of payload:string
            | NativeConsumerNoFurtherDeltaPossible of reason:CompilerKernelV2.OperationalReasonId
            | NativeConsumerObserverOnlyGrace
            | NativeConsumerNoFurtherNoEffect of contract:NativeDirectEvaluationContractId

        let nativeConsumerExecutionResultText = function
            | NativeConsumerAstDelta facts -> "ASTDelta(facts=" + string facts + ")"
            | NativeConsumerPlateauPoisonReturned payload -> "NativePromiseFailedPlateau(payload=" + payload + ")"
            | NativeConsumerPromiseFailedPoison payload -> "NativePromiseFailedPoison(payload=" + payload + ")"
            | NativeConsumerNoFurtherDeltaPossible reason -> "NoFurtherDeltaPossible(reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NativeConsumerObserverOnlyGrace -> "ObserverOnlyGrace"
            | NativeConsumerNoFurtherNoEffect contract -> "NoFurtherNoEffect(contract=" + nativeDirectEvaluationContractText contract + ")"

        let nativeConsumerExecutionResultFor astDeltaId semanticFactCount =
            match astDeltaId with
            | NativeAstDeltaMeasuredCounterDelta when semanticFactCount > 0L -> NativeConsumerAstDelta semanticFactCount
            | NativeAstDeltaExecutePureAstStep _ when semanticFactCount > 0L -> NativeConsumerAstDelta semanticFactCount
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, _, _) when semanticFactCount <= 0L -> NativeConsumerObserverOnlyGrace
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, _, _) -> NativeConsumerAstDelta semanticFactCount
            | NativeAstDeltaCyclePoisonInjected payload -> NativeConsumerPromiseFailedPoison payload
            | NativeAstDeltaSemanticPlateauPoison(contract, kind, reason) -> NativeConsumerPlateauPoisonReturned (nativeDirectEvaluationSemanticPlateauPayload contract kind reason)
            | NativeAstDeltaExecutePureAstStep contract -> NativeConsumerNoFurtherNoEffect contract
            | NativeAstDeltaBlockedLegacyFallback contract -> NativeConsumerNoFurtherNoEffect contract
            | NativeAstDeltaNoContractLegacyForbidden -> NativeConsumerNoFurtherDeltaPossible (CompilerKernelV2.OperationalReasonIdOps.create "no_direct_eval_contract_legacy_forbidden")
            | _ -> NativeConsumerNoFurtherDeltaPossible (CompilerKernelV2.OperationalReasonIdOps.create "consumer_closed_without_measured_ast_delta")

        // MIGRATION: the assessments identified the last gap as a poisoned
        // closure being rendered correctly but still looking like a successful
        // native promise result to upstream bind nodes.  Make the promise outcome
        // a typed DU before it reaches JSON/HUD projection.
        type NativePromiseOutcomeId =
            | NativePromiseOutcomeResolvedDelta of promiseId:string * facts:int64
            | NativePromiseOutcomeFailedPlateau of promiseId:string * payload:string
            | NativePromiseOutcomeFailedCycle of promiseId:string * payload:string
            | NativePromiseOutcomeNoFurther of promiseId:string * reason:CompilerKernelV2.OperationalReasonId
            | NativePromiseOutcomeObserverOnly of promiseId:string * reason:CompilerKernelV2.OperationalReasonId

        type RootPromiseStatusId =
            | RootPromiseResolved of promiseId:string
            | RootPromiseFailed of promiseId:string * payload:string
            | RootPromiseNoFurther of promiseId:string * reason:CompilerKernelV2.OperationalReasonId
            | RootPromiseWaiting of promiseId:string * reason:CompilerKernelV2.OperationalReasonId

        let rootPromiseStatusFor = function
            | NativePromiseOutcomeResolvedDelta(promiseId, _) -> RootPromiseResolved promiseId
            | NativePromiseOutcomeFailedPlateau(promiseId, payload) -> RootPromiseFailed(promiseId, payload)
            | NativePromiseOutcomeFailedCycle(promiseId, payload) -> RootPromiseFailed(promiseId, payload)
            | NativePromiseOutcomeNoFurther(promiseId, reason) -> RootPromiseNoFurther(promiseId, reason)
            | NativePromiseOutcomeObserverOnly(promiseId, reason) -> RootPromiseWaiting(promiseId, reason)

        let rootPromiseStatusText = function
            | RootPromiseResolved promiseId -> "RootPromiseResolved(promise=" + promiseId + ")"
            | RootPromiseFailed(promiseId, payload) -> "RootPromiseFailed(promise=" + promiseId + "|payload=" + payload + ")"
            | RootPromiseNoFurther(promiseId, reason) -> "RootPromiseNoFurther(promise=" + promiseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | RootPromiseWaiting(promiseId, reason) -> "RootPromiseWaiting(promise=" + promiseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let rootPromiseStatusIsFailed = function
            | RootPromiseFailed _ -> true
            | RootPromiseResolved _
            | RootPromiseNoFurther _
            | RootPromiseWaiting _ -> false

        let rootPromiseStatusRequiresFailureEvidence = function
            | RootPromiseFailed _
            | RootPromiseNoFurther _ -> true
            | RootPromiseResolved _
            | RootPromiseWaiting _ -> false

        // DOMAIN MIGRATION : RootPromise is no longer a sticky HUD string.
        // ParentContinuation fill receipts must either be consumed by the
        // RootComplete boundary or emit a typed contradiction that names the
        // missing witness/owner-ledger evidence.  This is the bridge from the
        // assessment's status-string world to a recursive owner/root spine.
        type RootPromiseTransitionId =
            | RootPromiseTransitionResolveAfterParentContinuationFill of promiseId:string * fillReceiptId:string * rootWitness:string
            | RootPromiseTransitionKeepWaiting of promiseId:string * reason:CompilerKernelV2.OperationalReasonId * missingEvidence:string
            | RootPromiseTransitionContradiction of promiseId:string * ownerLedgerId:string * contradiction:string
            | RootPromiseTransitionAwaitNativeRootCompleteAlt of promiseId:string * reason:CompilerKernelV2.OperationalReasonId

        let rootPromiseTransitionText = function
            | RootPromiseTransitionResolveAfterParentContinuationFill(promiseId, fillReceiptId, rootWitness) ->
                "RootPromiseTransition(ResolveAfterParentContinuationFill|promise=" + promiseId + "|fill_receipt=" + fillReceiptId + "|root_witness=" + rootWitness + ")"
            | RootPromiseTransitionKeepWaiting(promiseId, reason, missingEvidence) ->
                "RootPromiseTransition(KeepWaiting|promise=" + promiseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|missing=" + missingEvidence + ")"
            | RootPromiseTransitionContradiction(promiseId, ownerLedgerId, contradiction) ->
                "RootPromiseTransition(Contradiction|promise=" + promiseId + "|owner_ledger=" + ownerLedgerId + "|why=" + contradiction + ")"
            | RootPromiseTransitionAwaitNativeRootCompleteAlt(promiseId, reason) ->
                "RootPromiseTransition(AwaitNativeRootCompleteAlt|promise=" + promiseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let rootPromiseTransitionStatusText = function
            | RootPromiseTransitionResolveAfterParentContinuationFill(promiseId, _, _) -> rootPromiseStatusText (RootPromiseResolved promiseId)
            | RootPromiseTransitionAwaitNativeRootCompleteAlt(promiseId, reason) -> rootPromiseStatusText (RootPromiseWaiting(promiseId, reason))
            | RootPromiseTransitionKeepWaiting(promiseId, reason, _) -> rootPromiseStatusText (RootPromiseWaiting(promiseId, reason))
            | RootPromiseTransitionContradiction(promiseId, _, contradiction) -> rootPromiseStatusText (RootPromiseFailed(promiseId, contradiction))

        // MIGRATION: model the final Hopac collapse explicitly even before the
        // outer CLI entry point is fully migrated.  These DUs are intentionally
        // small and text-projected so existing call sites can carry the contract
        // without parsing metronome strings.  The next compile log should prove
        // RootCompleteAwaitFailedClosed/ExitOne instead of another sleeping tail.

        type SemanticDiagnosisId =
            | SemanticDiagnosisNone
            | SemanticDiagnosisPlateau of payload:string
            | SemanticDiagnosisCycle of payload:string
            | SemanticDiagnosisNoFurther of reason:CompilerKernelV2.OperationalReasonId

        let semanticDiagnosisFor = function
            | NativePromiseOutcomeFailedPlateau(_, payload) -> SemanticDiagnosisPlateau payload
            | NativePromiseOutcomeFailedCycle(_, payload) -> SemanticDiagnosisCycle payload
            | NativePromiseOutcomeNoFurther(_, reason) -> SemanticDiagnosisNoFurther reason
            | _ -> SemanticDiagnosisNone

        type SemanticSourceSpanId =
            | SemanticSourceSpanUnknown
            | SemanticSourceSpanFromWorkSite of site:CompilerIdentityKernel.WorkSiteId
            | SemanticSourceSpanFromPayload of span:string
            | SemanticSourceSpanFromNode of node:string
            | SemanticSourceSpanFromSite of site:string

        type SemanticSourceFallbackSignalId =
            | SemanticSourceFallbackStaleRetarget
            | SemanticSourceFallbackTySidecarDrain
            | SemanticSourceFallbackWaitForGraph
            | SemanticSourceFallbackIdleCrossKind
            | SemanticSourceFallbackUnknown

        type SemanticSourceMarkerId =
            | SemanticSourceMarkerSourceSpan
            | SemanticSourceMarkerSpan
            | SemanticSourceMarkerSite
            | SemanticSourceMarkerNode
            | SemanticSourceMarkerPromiseNode
            | SemanticSourceMarkerRawPromiseNode
            | SemanticSourceMarkerBlocker

        let private semanticSourceMarkerOrder =
            [ SemanticSourceMarkerSourceSpan
              SemanticSourceMarkerSpan
              SemanticSourceMarkerSite
              SemanticSourceMarkerNode
              SemanticSourceMarkerPromiseNode
              SemanticSourceMarkerRawPromiseNode
              SemanticSourceMarkerBlocker ]

        let private semanticSourceFallbackSignalFor (payload:string) =
            let tokens = diagnosticTextTokensLower payload
            let segments = diagnosticTextSegmentsLower payload
            if diagnosticTextHasAny [ "semanticstaleretarget"; "stale_retarget" ] tokens
               || (Set.contains "stale" segments && Set.contains "retarget" segments) then
                SemanticSourceFallbackStaleRetarget
            elif Set.contains "ty_sidecar_drain" tokens
                 || (Set.contains "ty" segments && Set.contains "sidecar" segments && Set.contains "drain" segments) then
                SemanticSourceFallbackTySidecarDrain
            elif Set.contains "nativetopologyfatalpromisewaitforgraph" tokens
                 || (Set.contains "wait" segments && Set.contains "graph" segments && Set.contains "fatal" segments) then
                SemanticSourceFallbackWaitForGraph
            elif diagnosticTextHasAny [ "idlecrosskind"; "idle_cross_kind" ] tokens
                 || (Set.contains "idle" segments && Set.contains "cross" segments && Set.contains "kind" segments) then
                SemanticSourceFallbackIdleCrossKind
            else
                SemanticSourceFallbackUnknown

        let private semanticSourceSpanForMarker marker value =
            match marker with
            | SemanticSourceMarkerSourceSpan
            | SemanticSourceMarkerSpan -> SemanticSourceSpanFromPayload value
            | SemanticSourceMarkerSite -> SemanticSourceSpanFromSite value
            | SemanticSourceMarkerNode
            | SemanticSourceMarkerPromiseNode
            | SemanticSourceMarkerRawPromiseNode -> SemanticSourceSpanFromNode value
            | SemanticSourceMarkerBlocker ->
                let slash = value.LastIndexOf('/')
                if slash >= 0 && slash + 1 < value.Length then SemanticSourceSpanFromNode(value.Substring(slash + 1))
                else SemanticSourceSpanFromPayload value

        let private semanticSourceMarkerValueFromField marker (field:string) =
            let parts = field.Split([|'='|], 2, StringSplitOptions.None)
            let exactField key =
                if parts.Length = 2 && String.Equals(parts.[0], key, StringComparison.OrdinalIgnoreCase) then
                    let value = parts.[1].Trim()
                    if String.IsNullOrWhiteSpace value then None else Some value
                else None
            let promiseSuffix (value:string) =
                let pieces = value.Split([|"Promise_for_Node_"|], 2, StringSplitOptions.None)
                if pieces.Length = 2 && pieces.[0].Length = 0 && pieces.[1].Length > 0 then Some pieces.[1]
                else None
            match marker with
            | SemanticSourceMarkerSourceSpan -> exactField "source_span"
            | SemanticSourceMarkerSpan -> exactField "span"
            | SemanticSourceMarkerSite -> exactField "site"
            | SemanticSourceMarkerNode -> exactField "node"
            | SemanticSourceMarkerBlocker -> exactField "blocker"
            | SemanticSourceMarkerPromiseNode ->
                match exactField "promise" with
                | Some value -> promiseSuffix value
                | None -> None
            | SemanticSourceMarkerRawPromiseNode -> promiseSuffix field

        let semanticSourceSpanFromPayload (payload:string) =
            let payload = if isNull payload then "" else payload
            let fields =
                payload.Split(
                    [|'|'; ')'; ','; ' '; '\n'; '\r'; '"'|],
                    StringSplitOptions.RemoveEmptyEntries)
            let markerValue marker =
                fields
                |> Array.tryPick (semanticSourceMarkerValueFromField marker)
            match semanticSourceMarkerOrder |> List.tryPick (fun marker -> markerValue marker |> Option.map (fun value -> marker, value)) with
            | Some (marker, value) -> semanticSourceSpanForMarker marker value
            | None ->
                match semanticSourceFallbackSignalFor payload with
                | SemanticSourceFallbackStaleRetarget -> SemanticSourceSpanFromSite "native_topology:semantic_stale_retarget"
                | SemanticSourceFallbackTySidecarDrain -> SemanticSourceSpanFromSite "native_topology:ty_sidecar_drain"
                | SemanticSourceFallbackWaitForGraph -> SemanticSourceSpanFromSite "native_topology:wait_for_graph"
                | SemanticSourceFallbackIdleCrossKind -> SemanticSourceSpanFromSite "native_topology:idle_cross_kind"
                | SemanticSourceFallbackUnknown -> SemanticSourceSpanUnknown

        let semanticSourceSpanText = function
            | SemanticSourceSpanUnknown -> "source_unknown"
            | SemanticSourceSpanFromWorkSite site -> "source_work_site:" + CompilerIdentityKernel.WorkSiteIdOps.text site
            | SemanticSourceSpanFromPayload span -> "source_span_payload:" + span
            | SemanticSourceSpanFromNode node -> "source_node:" + node
            | SemanticSourceSpanFromSite site -> "source_site:" + site

        let semanticDiagnosisText = function
            | SemanticDiagnosisNone -> "SemanticDiagnosis(None)"
            | SemanticDiagnosisPlateau payload -> "SemanticDiagnosis(PlateauPoison|span=" + (semanticSourceSpanFromPayload payload |> semanticSourceSpanText) + "|message=" + payload + ")"
            | SemanticDiagnosisCycle payload -> "SemanticDiagnosis(CyclePoison|span=" + (semanticSourceSpanFromPayload payload |> semanticSourceSpanText) + "|message=" + payload + ")"
            | SemanticDiagnosisNoFurther reason ->
                let reasonText = CompilerKernelV2.OperationalReasonIdOps.text reason
                "SemanticDiagnosis(NoFurtherDeltaPossible|span=" + (semanticSourceSpanFromPayload reasonText |> semanticSourceSpanText) + "|message=" + reasonText + ")"

        // MIGRATION: make the root-exit / trampoline / record-map terminals typed
        // before JSON projection.  The 1736 assessments asked for
        // hopac_root_exit_verdict and trampoline_bypass_status as DUs rather than
        // ad-hoc strings; keep the projection compact but force all hot rows to
        // spell the same native terminal contract.
        type HopacRootExitVerdictId =
            | HopacRootExitReturnOk of promiseId:string
            | HopacRootExitObserverSemanticFailure of semantic:string
            | HopacRootExitAwaitPending of reason:CompilerKernelV2.OperationalReasonId

        let hopacRootExitVerdictFor = function
            | RootPromiseResolved promiseId -> HopacRootExitReturnOk promiseId
            | RootPromiseFailed(_, payload) -> HopacRootExitObserverSemanticFailure payload
            | RootPromiseNoFurther(_, reason) -> HopacRootExitObserverSemanticFailure (CompilerKernelV2.OperationalReasonIdOps.text reason)
            | RootPromiseWaiting(_, reason) -> HopacRootExitAwaitPending reason

        let hopacRootExitVerdictText = function
            | HopacRootExitReturnOk promiseId -> "ExitOk(RootComplete|promise=" + promiseId + ")"
            | HopacRootExitObserverSemanticFailure semantic -> "ExitObserverOnly(SemanticDiagnosis(" + semantic + ")|authority=NativeRootCompleteAlt)"
            | HopacRootExitAwaitPending reason -> "ExitPending(RootCompleteAwait|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        type TrampolineBypassStatusId =
            | TrampolineBypassedNativeTerminal of code:string * policy:string
            | TrampolineBypassedSemanticTerminal of code:string * policy:string
            | TrampolineStillArmed of reason:CompilerKernelV2.OperationalReasonId

        let trampolineBypassStatusText = function
            | TrampolineBypassedNativeTerminal(code, policy) -> "TrampolineBypass(NativeTerminal|code=" + code + "|policy=" + policy + ")"
            | TrampolineBypassedSemanticTerminal(code, policy) -> "TrampolineBypass(SemanticTerminal|code=" + code + "|policy=" + policy + ")"
            | TrampolineStillArmed reason -> "TrampolineStillArmed(reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        type NativePromiseFateFinalVerdictId =
            | NativePromiseFateExitOk of promiseId:string
            | NativePromiseFateObserverSemanticFailure of payload:string * span:SemanticSourceSpanId
            | NativePromiseFateObserverNoFurther of reason:CompilerKernelV2.OperationalReasonId * span:SemanticSourceSpanId
            | NativePromiseFateStillPending of promiseId:string * reason:CompilerKernelV2.OperationalReasonId

        let private nativePromiseFateSourceNow () =
            match activeWorkSourceSiteNow () with
            | Some site -> SemanticSourceSpanFromWorkSite site
            | None -> SemanticSourceSpanUnknown

        let nativePromiseFateFinalVerdictFor = function
            | RootPromiseResolved promiseId -> NativePromiseFateExitOk promiseId
            | RootPromiseFailed(_, payload) -> NativePromiseFateObserverSemanticFailure(payload, nativePromiseFateSourceNow ())
            | RootPromiseNoFurther(_, reason) -> NativePromiseFateObserverNoFurther(reason, nativePromiseFateSourceNow ())
            | RootPromiseWaiting(promiseId, reason) -> NativePromiseFateStillPending(promiseId, reason)

        let nativePromiseFateFinalVerdictText = function
            | NativePromiseFateExitOk promiseId -> "NativePromiseFateFinalVerdict(ExitOk|promise=" + promiseId + ")"
            | NativePromiseFateObserverSemanticFailure(payload, span) -> "NativePromiseFateFinalVerdict(ObserverSemanticFailure|authority=NativeRootCompleteAlt|span=" + semanticSourceSpanText span + "|payload=" + payload + ")"
            | NativePromiseFateObserverNoFurther(reason, span) -> "NativePromiseFateFinalVerdict(ObserverNoFurther|authority=NativeRootCompleteAlt|span=" + semanticSourceSpanText span + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NativePromiseFateStillPending(promiseId, reason) -> "NativePromiseFateFinalVerdict(StillPending|promise=" + promiseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        type RecordMapSemanticTerminalId =
            | RecordMapExpectedRecordFailed of semanticFailureId:string * expectedOperandIndex:int * leftShape:string * rightShape:string

        let recordMapSemanticTerminalText = function
            | RecordMapExpectedRecordFailed(semanticFailureId, expectedOperandIndex, leftShape, rightShape) ->
                "RecordMapSemanticTerminal(ExpectedRecordButGotNonRecord|semantic_failure_id=" + semanticFailureId + "|expected_operand_index=" + string expectedOperandIndex + "|left_shape=" + leftShape + "|right_shape=" + rightShape + ")"

        // MIGRATION migration phase: stop using cumulative scheduler counters as
        // proof that a terminal closure is still alive.  These DUs are a
        // breaking bridge toward the assessment model: typed consumer result
        // -> semantic frontier verdict -> closure/root collapse projection.
        type ConsumerResultVerdictId =
            | ConsumerResultRealDelta of factKind:string * count:int64
            | ConsumerResultPlateauPoison of blocker:string * factKind:string
            | ConsumerResultForceSemanticSidecarDrain of topologyWitness:string * missingSemanticFact:string
            | ConsumerResultStrictSidecarDataflowBindRequired of topologyWitness:string * semanticPromise:string * waitGraphEdge:string
            | ConsumerResultNoFurtherDeclared of reason:CompilerKernelV2.OperationalReasonId
            | ConsumerResultObserverOnly of reason:CompilerKernelV2.OperationalReasonId

        let consumerResultVerdictText = function
            | ConsumerResultRealDelta(factKind, count) -> "ConsumerResultVerdict(RealDelta|fact_kind=" + factKind + "|count=" + string count + ")"
            | ConsumerResultPlateauPoison(blocker, factKind) -> "ConsumerResultVerdict(PlateauPoison|blocker=" + blocker + "|fact_kind=" + factKind + ")"
            | ConsumerResultForceSemanticSidecarDrain(topologyWitness, missingSemanticFact) -> "ConsumerResultVerdict(ForceSemanticSidecarDrain|topology_witness=" + topologyWitness + "|missing_semantic_fact=" + missingSemanticFact + ")"
            | ConsumerResultStrictSidecarDataflowBindRequired(topologyWitness, semanticPromise, waitGraphEdge) -> "ConsumerResultVerdict(StrictSidecarDataflowBindRequired|topology_witness=" + topologyWitness + "|semantic_promise=" + semanticPromise + "|wait_edge=" + waitGraphEdge + ")"
            | ConsumerResultNoFurtherDeclared reason -> "ConsumerResultVerdict(NoFurtherDeclared|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | ConsumerResultObserverOnly reason -> "ConsumerResultVerdict(ObserverOnly|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        // DOMAIN MIGRATION bonus / MIGRATION: quarantine all string parsing at
        // the legacy erasure boundary.  NoFurther authority must consume the
        // typed verdict below; scattered Contains calls are not allowed to mint
        // terminal authority or physical exit decisions.
        type NoFurtherAuthorityClassifierId =
            | NoFurtherTopologyOnlyDebt of reason:CompilerKernelV2.OperationalReasonId
            | NoFurtherSemanticReceiptPresent of receipt:string
            | NoFurtherLegacyUnknown of erasure:string

        let private noFurtherAuthorityClassifierText = function
            | NoFurtherTopologyOnlyDebt reason -> "NoFurtherAuthorityClassifier(TopologyOnlyDebt|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NoFurtherSemanticReceiptPresent receipt -> "NoFurtherAuthorityClassifier(SemanticReceiptPresent|receipt=" + receipt + ")"
            | NoFurtherLegacyUnknown erasure -> "NoFurtherAuthorityClassifier(LegacyUnknown|erasure=" + erasure + ")"

        type TerminalClosurePrerequisiteDebtId =
            | TerminalClosurePrerequisiteSemanticFactDebtOpen
            | TerminalClosurePrerequisiteKnownWorkWithoutSemanticFactDelta
            | TerminalClosurePrerequisiteDebtClosedOrUnknown

        let private terminalClosurePrerequisiteDebtFromErasure (text:string) =
            let value = if isNull text then "" else text
            let tokens =
                value.Split(
                    [| '|'; ':'; ','; ';'; ' '; '='; '('; ')'; '['; ']'; '\n'; '\r'; '\t' |],
                    StringSplitOptions.RemoveEmptyEntries)
                |> Set.ofArray
            if Set.contains "semantic_fact_debt_open" tokens then
                TerminalClosurePrerequisiteSemanticFactDebtOpen
            elif Set.contains "known_work_without_semantic_fact_delta" tokens then
                TerminalClosurePrerequisiteKnownWorkWithoutSemanticFactDelta
            else
                TerminalClosurePrerequisiteDebtClosedOrUnknown

        let private terminalClosurePrerequisiteDebtIsOpen = function
            | TerminalClosurePrerequisiteSemanticFactDebtOpen
            | TerminalClosurePrerequisiteKnownWorkWithoutSemanticFactDelta -> true
            | TerminalClosurePrerequisiteDebtClosedOrUnknown -> false

        type NoFurtherSemanticDebtEvidenceId =
            | NoFurtherSemanticDebtPaid
            | NoFurtherSemanticDebtNotPaid

        let consumerResultVerdictFor semanticFactCount astDeltaId =
            match astDeltaId with
            | NativeAstDeltaMeasuredCounterDelta when semanticFactCount > 0L -> ConsumerResultRealDelta("term_or_ty", semanticFactCount)
            | NativeAstDeltaExecutePureAstStep _ when semanticFactCount > 0L -> ConsumerResultRealDelta("term_or_ty", semanticFactCount)
            | NativeAstDeltaPureTopologyWitnessMaterialized(contract, kind, reason) when semanticFactCount <= 0L ->
                let topologyWitness = "topology_witness=" + nativeDirectEvaluationContractText contract + "|fact_kind=" + nativeClosureKindText kind + "|reason=" + nativePureTopologyWitnessReasonText reason
                ConsumerResultStrictSidecarDataflowBindRequired(
                    topologyWitness,
                    "semantic_promise_required_before_consumer_nofurther",
                    "wait_graph_edge=topology_witness->semantic_sidecar_fact")
            | NativeAstDeltaPureTopologyWitnessMaterialized(contract, kind, reason) -> ConsumerResultRealDelta("pure_topology_witness_semantic_receipt:" + nativeDirectEvaluationContractText contract + ":" + nativeClosureKindText kind + ":" + nativePureTopologyWitnessReasonText reason, semanticFactCount)
            | NativeAstDeltaCyclePoisonInjected payload when semanticFactCount > 0L -> ConsumerResultRealDelta("cycle_poison_semantic_receipt:" + payload, semanticFactCount)
            | NativeAstDeltaCyclePoisonInjected payload -> ConsumerResultPlateauPoison(payload, "none")
            | NativeAstDeltaSemanticPlateauPoison(contract, kind, reason) when semanticFactCount > 0L -> ConsumerResultRealDelta("semantic_plateau_receipt:" + nativeDirectEvaluationSemanticPlateauPayload contract kind reason + ":" + nativeClosureKindText kind, semanticFactCount)
            | NativeAstDeltaSemanticPlateauPoison(contract, kind, reason) -> ConsumerResultPlateauPoison(nativeDirectEvaluationSemanticPlateauPayload contract kind reason, nativeClosureKindText kind)
            | NativeAstDeltaBlockedLegacyFallback contract -> ConsumerResultNoFurtherDeclared(CompilerKernelV2.OperationalReasonIdOps.create ("blocked_legacy_fallback|" + nativeDirectEvaluationContractText contract))
            | NativeAstDeltaNoContractLegacyForbidden -> ConsumerResultNoFurtherDeclared(CompilerKernelV2.OperationalReasonIdOps.create "no_direct_eval_contract_legacy_forbidden")
            | _ -> ConsumerResultObserverOnly(CompilerKernelV2.OperationalReasonIdOps.create "zero_semantic_fact_no_poison")

        type SemanticFrontierFactKindId =
            | SemanticFrontierTermOrTyFact
            | SemanticFrontierPureTopologyWitnessFact of NativeClosureKindId
            | SemanticFrontierPureTopologyFact

        let semanticFrontierFactKindText = function
            | SemanticFrontierTermOrTyFact -> "term_or_ty"
            | SemanticFrontierPureTopologyWitnessFact kind -> "pure_topology_witness:" + nativeClosureKindText kind
            | SemanticFrontierPureTopologyFact -> "pure_topology"

        type SemanticFrontierAdvanceResultId =
            | SemanticFrontierAdvanced of factKind:SemanticFrontierFactKindId * count:int64
            | SemanticFrontierStarvedAtFixedPoint of blocker:string
            | SemanticFrontierTopologyExpectedButZeroFact of expected:string * actual:string
            | SemanticFrontierObserverOnly of reason:CompilerKernelV2.OperationalReasonId

        let semanticFrontierAdvanceResultText = function
            | SemanticFrontierAdvanced(factKind, count) -> "SemanticFrontierAdvance(Advanced|fact_kind=" + semanticFrontierFactKindText factKind + "|count=" + string count + ")"
            | SemanticFrontierStarvedAtFixedPoint blocker -> "SemanticFrontierAdvance(StarvedAtFixedPoint|blocker=" + blocker + ")"
            | SemanticFrontierTopologyExpectedButZeroFact(expected, actual) -> "SemanticFrontierAdvance(TopologyExpectedButZeroFact|expected=" + expected + "|actual=" + actual + ")"
            | SemanticFrontierObserverOnly reason -> "SemanticFrontierAdvance(ObserverOnly|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let semanticFrontierAdvanceResultFor expectedDeltaId semanticFactCount astDeltaId =
            let expectedText = nativeWakeExpectedDeltaText expectedDeltaId
            match astDeltaId with
            | NativeAstDeltaMeasuredCounterDelta when semanticFactCount > 0L -> SemanticFrontierAdvanced(SemanticFrontierTermOrTyFact, semanticFactCount)
            | NativeAstDeltaExecutePureAstStep _ when semanticFactCount > 0L -> SemanticFrontierAdvanced(SemanticFrontierTermOrTyFact, semanticFactCount)
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, kind, _) when semanticFactCount > 0L -> SemanticFrontierAdvanced(SemanticFrontierPureTopologyWitnessFact kind, semanticFactCount)
            | NativeAstDeltaPureTopologyWitnessMaterialized(contract, kind, reason) -> SemanticFrontierTopologyExpectedButZeroFact(expectedText, "PureTopologyWitnessZeroFact(contract=" + nativeDirectEvaluationContractText contract + "|kind=" + nativeClosureKindText kind + "|reason=" + nativePureTopologyWitnessReasonText reason + ")")
            | NativeAstDeltaCyclePoisonInjected _ when semanticFactCount > 0L -> SemanticFrontierAdvanced(SemanticFrontierPureTopologyFact, semanticFactCount)
            | NativeAstDeltaCyclePoisonInjected payload -> SemanticFrontierStarvedAtFixedPoint payload
            | NativeAstDeltaSemanticPlateauPoison(_, _, _) when semanticFactCount > 0L -> SemanticFrontierAdvanced(SemanticFrontierPureTopologyFact, semanticFactCount)
            | NativeAstDeltaSemanticPlateauPoison(contract, kind, reason) -> SemanticFrontierTopologyExpectedButZeroFact(expectedText, nativeDirectEvaluationSemanticPlateauPayload contract kind reason)
            | NativeAstDeltaBlockedLegacyFallback contract -> SemanticFrontierObserverOnly(CompilerKernelV2.OperationalReasonIdOps.create ("blocked_legacy_fallback|" + nativeDirectEvaluationContractText contract))
            | NativeAstDeltaNoContractLegacyForbidden -> SemanticFrontierObserverOnly(CompilerKernelV2.OperationalReasonIdOps.create "no_direct_eval_contract_legacy_forbidden")
            | _ -> SemanticFrontierObserverOnly(CompilerKernelV2.OperationalReasonIdOps.create "zero_semantic_fact_no_poison")

        let private consumerNoFurtherClassifier
            (consumerResultVerdictId:ConsumerResultVerdictId)
            (semanticFrontierAdvanceResultId:SemanticFrontierAdvanceResultId)
            (semanticDebtEvidenceId:NoFurtherSemanticDebtEvidenceId) =
            let topologyOnly =
                match consumerResultVerdictId, semanticFrontierAdvanceResultId with
                | ConsumerResultForceSemanticSidecarDrain _, _
                | ConsumerResultStrictSidecarDataflowBindRequired _, _
                | _, SemanticFrontierTopologyExpectedButZeroFact _ -> true
                | _ -> false
            let semanticReceipt =
                match semanticDebtEvidenceId, consumerResultVerdictId, semanticFrontierAdvanceResultId with
                | NoFurtherSemanticDebtPaid, _, _ -> true
                | _, ConsumerResultRealDelta(_, count), _ when count > 0L -> true
                | _, _, SemanticFrontierAdvanced(_, count) when count > 0L && not topologyOnly -> true
                | _ -> false
            if semanticReceipt then NoFurtherSemanticReceiptPresent "semantic_frontier_or_debt_receipt"
            elif topologyOnly then NoFurtherTopologyOnlyDebt (CompilerKernelV2.OperationalReasonIdOps.create "topology_witness_does_not_pay_semantic_fact_debt")
            else NoFurtherLegacyUnknown "no_typed_receipt_seen"

        type AbortBlockerFreshnessId =
            | AbortBlockerNone
            | AbortBlockerRecentDelta of rootDelta:int64 * terminalDelta:int64
            | AbortBlockerCumulativeOnly of roots:int64 * terminals:int64

        // MIGRATION: typed lane payload bridge. 1751 proved that a string-only
        // minimal/rich handoff can silently erase the terminal diagnosis; keep the
        // payload as a DU until the last JSON/HUD projection so blank diagnosis is
        // no longer a representable terminal state.
        type MinimalLane = interface end
        type RichLane = interface end

        type NativeTerminalPayload<'Lane> =
            | NativeTerminalPayloadPending
            | NativeTerminalPayloadPlateauPoison of blocker:string * diagnosis:string * semanticPayload:string * starved:int * result:string
            | NativeTerminalPayloadSemanticStaleRetarget of node:string * diagnosis:string * semanticPayload:string * starved:int * result:string
            | NativeTerminalPayloadCyclePoison of blocker:string * diagnosis:string * semanticPayload:string * starved:int * result:string
            | NativeTerminalPayloadNoFurtherDelta of reason:CompilerKernelV2.OperationalReasonId * diagnosis:string * semanticPayload:string * starved:int * result:string

        type MinimalTerminalPayloadClass =
            | MinimalTerminalPayloadPlateauPoison
            | MinimalTerminalPayloadSemanticStaleRetarget
            | MinimalTerminalPayloadCyclePoison
            | MinimalTerminalPayloadNoFurtherDelta

        let minimalTerminalPayloadClassText = function
            | MinimalTerminalPayloadPlateauPoison -> "PlateauPoison"
            | MinimalTerminalPayloadSemanticStaleRetarget -> "SemanticStaleRetarget"
            | MinimalTerminalPayloadCyclePoison -> "CyclePoison"
            | MinimalTerminalPayloadNoFurtherDelta -> "NoFurtherDelta"

        let minimalNativeFailureEvidenceClassForPayloadClass = function
            | MinimalTerminalPayloadSemanticStaleRetarget -> MinimalNativeFailureSemanticStaleRetarget
            | MinimalTerminalPayloadCyclePoison -> MinimalNativeFailureCyclePoison
            | MinimalTerminalPayloadNoFurtherDelta -> MinimalNativeFailureNoFurther
            | MinimalTerminalPayloadPlateauPoison -> MinimalNativeFailurePlateauPoison

        type MinimalToRichPayloadStatusId =
            | MinimalToRichNoPayload
            | MinimalToRichSuccess of payload:string
            | MinimalToRichAwaitingFreshEvidence of reason:CompilerKernelV2.OperationalReasonId
            | MinimalToRichDropped of reason:CompilerKernelV2.OperationalReasonId

        let private nonEmptyOr fallback text =
            if String.IsNullOrWhiteSpace text then fallback else text

        let nativeTerminalPayloadText = function
            | NativeTerminalPayloadPending -> "NativeTerminalPayload(Pending)"
            | NativeTerminalPayloadPlateauPoison(blocker, diagnosis, semanticPayload, starved, result) -> "NativeTerminalPayload(PlateauPoison|blocker=" + nonEmptyOr "unknown" blocker + "|diagnosis=" + nonEmptyOr "required" diagnosis + "|semantic_error_payload=" + nonEmptyOr "required" semanticPayload + "|starved=" + string starved + "|result=" + nonEmptyOr "required" result + ")"
            | NativeTerminalPayloadSemanticStaleRetarget(node, diagnosis, semanticPayload, starved, result) -> "NativeTerminalPayload(SemanticStaleRetarget|node=" + nonEmptyOr "unknown" node + "|diagnosis=" + nonEmptyOr "required" diagnosis + "|semantic_error_payload=" + nonEmptyOr "required" semanticPayload + "|starved=" + string starved + "|result=" + nonEmptyOr "required" result + ")"
            | NativeTerminalPayloadCyclePoison(blocker, diagnosis, semanticPayload, starved, result) -> "NativeTerminalPayload(CyclePoison|blocker=" + nonEmptyOr "unknown" blocker + "|diagnosis=" + nonEmptyOr "required" diagnosis + "|semantic_error_payload=" + nonEmptyOr "required" semanticPayload + "|starved=" + string starved + "|result=" + nonEmptyOr "required" result + ")"
            | NativeTerminalPayloadNoFurtherDelta(reason, diagnosis, semanticPayload, starved, result) -> "NativeTerminalPayload(NoFurtherDelta|reason=" + nonEmptyOr "unknown" (CompilerKernelV2.OperationalReasonIdOps.text reason) + "|diagnosis=" + nonEmptyOr "required" diagnosis + "|semantic_error_payload=" + nonEmptyOr "required" semanticPayload + "|starved=" + string starved + "|result=" + nonEmptyOr "required" result + ")"

        let minimalTerminalPayloadForBridge payloadClass blocker diagnosis semanticPayload starved result : NativeTerminalPayload<MinimalLane> =
            let blocker = nonEmptyOr "unknown_terminal_blocker" blocker
            let diagnosis = nonEmptyOr ("diagnosis_from_blocker:" + blocker) diagnosis
            let semanticPayload = nonEmptyOr ("semantic_error_payload_from_blocker:" + blocker) semanticPayload
            let result = nonEmptyOr ("result_from_blocker:" + blocker) result
            match payloadClass with
            | MinimalTerminalPayloadSemanticStaleRetarget -> NativeTerminalPayloadSemanticStaleRetarget(blocker, diagnosis, semanticPayload, starved, result)
            | MinimalTerminalPayloadCyclePoison -> NativeTerminalPayloadCyclePoison(blocker, diagnosis, semanticPayload, starved, result)
            | MinimalTerminalPayloadNoFurtherDelta -> NativeTerminalPayloadNoFurtherDelta(CompilerKernelV2.OperationalReasonIdOps.create blocker, diagnosis, semanticPayload, starved, result)
            | MinimalTerminalPayloadPlateauPoison -> NativeTerminalPayloadPlateauPoison(blocker, diagnosis, semanticPayload, starved, result)

        let promoteMinimalTerminalPayloadToRich (payload:NativeTerminalPayload<MinimalLane>) : NativeTerminalPayload<RichLane> * MinimalToRichPayloadStatusId =
            match payload with
            | NativeTerminalPayloadPending -> NativeTerminalPayloadPending, MinimalToRichNoPayload
            | NativeTerminalPayloadPlateauPoison(blocker, diagnosis, semanticPayload, starved, result) ->
                let rich = NativeTerminalPayloadPlateauPoison(nonEmptyOr "unknown_terminal_blocker" blocker, nonEmptyOr ("diagnosis_from_blocker:" + blocker) diagnosis, nonEmptyOr ("semantic_error_payload_from_blocker:" + blocker) semanticPayload, starved, nonEmptyOr ("result_from_blocker:" + blocker) result)
                rich, MinimalToRichSuccess(nativeTerminalPayloadText rich)
            | NativeTerminalPayloadSemanticStaleRetarget(node, diagnosis, semanticPayload, starved, result) ->
                let rich = NativeTerminalPayloadSemanticStaleRetarget(nonEmptyOr "unknown_semantic_stale_retarget" node, nonEmptyOr ("diagnosis_from_blocker:" + node) diagnosis, nonEmptyOr ("semantic_error_payload_from_blocker:" + node) semanticPayload, starved, nonEmptyOr ("result_from_blocker:" + node) result)
                rich, MinimalToRichSuccess(nativeTerminalPayloadText rich)
            | NativeTerminalPayloadCyclePoison(blocker, diagnosis, semanticPayload, starved, result) ->
                let rich = NativeTerminalPayloadCyclePoison(nonEmptyOr "unknown_cycle_poison" blocker, nonEmptyOr ("diagnosis_from_blocker:" + blocker) diagnosis, nonEmptyOr ("semantic_error_payload_from_blocker:" + blocker) semanticPayload, starved, nonEmptyOr ("result_from_blocker:" + blocker) result)
                rich, MinimalToRichSuccess(nativeTerminalPayloadText rich)
            | NativeTerminalPayloadNoFurtherDelta(reason, diagnosis, semanticPayload, starved, result) ->
                let reasonText = CompilerKernelV2.OperationalReasonIdOps.text reason
                let normalizedReason = nonEmptyOr "unknown_no_further_delta" reasonText
                let rich = NativeTerminalPayloadNoFurtherDelta(CompilerKernelV2.OperationalReasonIdOps.create normalizedReason, nonEmptyOr ("diagnosis_from_blocker:" + normalizedReason) diagnosis, nonEmptyOr ("semantic_error_payload_from_blocker:" + normalizedReason) semanticPayload, starved, nonEmptyOr ("result_from_blocker:" + normalizedReason) result)
                rich, MinimalToRichSuccess(nativeTerminalPayloadText rich)

        let minimalToRichPayloadStatusText = function
            | MinimalToRichNoPayload -> "NoPayload"
            | MinimalToRichSuccess payload -> "Success|payload=" + nonEmptyOr "required" payload
            | MinimalToRichAwaitingFreshEvidence reason -> "AwaitingFreshMinimalEvidence|reason=" + nonEmptyOr "unknown" (CompilerKernelV2.OperationalReasonIdOps.text reason)
            | MinimalToRichDropped reason -> "Dropped|reason=" + nonEmptyOr "unknown" (CompilerKernelV2.OperationalReasonIdOps.text reason)

        let minimalToRichBridgeReceiptFor classId status payloadText rootStatus waitGraphText liveEvidenceText =
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let statusText = minimalToRichPayloadStatusText status
            let action =
                match status with
                | MinimalToRichNoPayload -> "NoPayloadObserverOnly"
                | MinimalToRichSuccess _ -> "PreservedTypedNativeFailureEvidence"
                | MinimalToRichAwaitingFreshEvidence _ -> "AwaitFreshEvidenceAndSuppressRootCollapse"
                | MinimalToRichDropped _ -> "LegacyDroppedQuarantinedNoAuthority"
            {
                stampedMs = now
                classId = classId
                payload = nonEmptyOr statusText payloadText
                rootStatus = nonEmptyOr "unknown_root" rootStatus
                waitGraph = nonEmptyOr "unknown_wait_graph" waitGraphText
                liveEvidence = nonEmptyOr "unknown_live_evidence" liveEvidenceText
                preservationAction = action
            }

        let minimalToRichBridgeReceiptTextFor classId status payloadText rootStatus waitGraphText liveEvidenceText =
            minimalToRichBridgeReceiptFor classId status payloadText rootStatus waitGraphText liveEvidenceText |> minimalToRichEvidenceReceiptText

        type NativeMaterialDeltaClassId =
            | NativeMaterialDeltaFatalPromiseFailure
            | NativeMaterialDeltaPureTopologyDelta
            | NativeMaterialDeltaMaterialTermOrTyFact
            | NativeMaterialDeltaMaterialCounterDelta
            | NativeMaterialDeltaNoDelta

        let nativeMaterialDeltaClassText = function
            | NativeMaterialDeltaFatalPromiseFailure -> "FatalPromiseFailure"
            | NativeMaterialDeltaPureTopologyDelta -> "PureTopologyDelta"
            | NativeMaterialDeltaMaterialTermOrTyFact -> "MaterialTermOrTyFact"
            | NativeMaterialDeltaMaterialCounterDelta -> "MaterialCounterDelta"
            | NativeMaterialDeltaNoDelta -> "NoDelta"

        let nativeMaterialDeltaClassFor rootPromiseAlreadyFailed semanticFactCount astDeltaId =
            match astDeltaId with
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, _, _) -> NativeMaterialDeltaPureTopologyDelta
            | NativeAstDeltaSemanticPlateauPoison _
            | NativeAstDeltaCyclePoisonInjected _ when rootPromiseAlreadyFailed -> NativeMaterialDeltaFatalPromiseFailure
            | NativeAstDeltaSemanticPlateauPoison _
            | NativeAstDeltaCyclePoisonInjected _ -> NativeMaterialDeltaPureTopologyDelta
            | _ when semanticFactCount > 0L -> NativeMaterialDeltaMaterialTermOrTyFact
            | NativeAstDeltaExecutePureAstStep _ -> NativeMaterialDeltaPureTopologyDelta
            | NativeAstDeltaMeasuredCounterDelta -> NativeMaterialDeltaMaterialCounterDelta
            | _ -> NativeMaterialDeltaNoDelta

        let nativeMaterialDeltaClassIsPureTopologyProgress rootPromiseAlreadyFailed = function
            | NativeMaterialDeltaPureTopologyDelta when not rootPromiseAlreadyFailed -> true
            | _ -> false

        type NativeActualSemanticDeltaClassId =
            | NativeActualSemanticFatalPromiseFailure
            | NativeActualSemanticPureTopologyMaterializedWitness
            | NativeActualSemanticTermOrTyFact
            | NativeActualSemanticPureTopologyDelta
            | NativeActualSemanticNone

        let nativeActualSemanticDeltaClassText = function
            | NativeActualSemanticFatalPromiseFailure -> "FatalPromiseFailure"
            | NativeActualSemanticPureTopologyMaterializedWitness -> "PureTopologyDelta(MaterializedWitness)"
            | NativeActualSemanticTermOrTyFact -> "TermOrTyFact"
            | NativeActualSemanticPureTopologyDelta -> "PureTopologyDelta"
            | NativeActualSemanticNone -> "None"

        type PureTopologyWitnessGuardId =
            | PureTopologyWitnessAbsent
            | PureTopologyWitnessMaterialized of facts:int64 * consumer:string * frontier:string
            | PureTopologyWitnessZeroFact of consumer:string * frontier:string
            | PureTopologyWitnessZeroFactContinuation of consumer:string * frontier:string

        let pureTopologyWitnessGuardText = function
            | PureTopologyWitnessAbsent -> "PureTopologyWitnessGuard(Absent)"
            | PureTopologyWitnessMaterialized(facts, consumer, frontier) -> "PureTopologyWitnessGuard(Materialized|facts=" + string facts + "|consumer=" + nonEmptyOr "unknown" consumer + "|frontier=" + nonEmptyOr "unknown" frontier + ")"
            | PureTopologyWitnessZeroFact(consumer, frontier) -> "PureTopologyWitnessGuard(ZeroFact|consumer=" + nonEmptyOr "unknown" consumer + "|frontier=" + nonEmptyOr "unknown" frontier + ")"
            | PureTopologyWitnessZeroFactContinuation(consumer, frontier) -> "PureTopologyWitnessGuard(ZeroFactContinuation|reason=zero_new_fact_after_materialized_topology_witness|consumer=" + nonEmptyOr "unknown" consumer + "|frontier=" + nonEmptyOr "unknown" frontier + ")"

        let pureTopologyWitnessGuardFor
            facts
            (consumerResultVerdictId:ConsumerResultVerdictId)
            (semanticFrontierAdvanceResultId:SemanticFrontierAdvanceResultId) =
            let consumerResultText = consumerResultVerdictText consumerResultVerdictId
            let semanticFrontierText = semanticFrontierAdvanceResultText semanticFrontierAdvanceResultId
            let materialized =
                match consumerResultVerdictId, semanticFrontierAdvanceResultId with
                | ConsumerResultForceSemanticSidecarDrain _, _
                | ConsumerResultStrictSidecarDataflowBindRequired _, _
                | _, SemanticFrontierAdvanced(SemanticFrontierPureTopologyWitnessFact _, _)
                | _, SemanticFrontierAdvanced(SemanticFrontierPureTopologyFact, _) -> true
                | _ -> false
            let zeroFactCanContinue =
                match consumerResultVerdictId, semanticFrontierAdvanceResultId with
                | ConsumerResultNoFurtherDeclared _, _
                | _, SemanticFrontierTopologyExpectedButZeroFact _ -> true
                | _ -> false
            if materialized && facts > 0L then PureTopologyWitnessMaterialized(facts, consumerResultText, semanticFrontierText)
            elif materialized && zeroFactCanContinue then PureTopologyWitnessZeroFactContinuation(consumerResultText, semanticFrontierText)
            elif materialized then PureTopologyWitnessZeroFact(consumerResultText, semanticFrontierText)
            else PureTopologyWitnessAbsent

        let pureTopologyWitnessGuardAllowsContinuation = function
            | PureTopologyWitnessMaterialized _
            | PureTopologyWitnessZeroFactContinuation(_, _) -> true
            | _ -> false

        type NativeSourceSpanBridgeResultId =
            | NativeSourceSpanBridgeSuccess of span:SemanticSourceSpanId
            | NativeSourceSpanBridgeMissing of reason:CompilerKernelV2.OperationalReasonId
            | NativeSourceSpanBridgeDeferred of reason:CompilerKernelV2.OperationalReasonId

        let nativeSourceSpanBridgeResultText = function
            | NativeSourceSpanBridgeSuccess span -> "SourceSpanBridge(Success|span=" + semanticSourceSpanText span + ")"
            | NativeSourceSpanBridgeMissing reason -> "SourceSpanBridge(Missing|reason=" + nonEmptyOr "unknown" (CompilerKernelV2.OperationalReasonIdOps.text reason) + ")"
            | NativeSourceSpanBridgeDeferred reason -> "SourceSpanBridge(Deferred|reason=" + nonEmptyOr "unknown" (CompilerKernelV2.OperationalReasonIdOps.text reason) + ")"

        type NativeTerminalCommitClassId =
            | NativeTerminalCommitFailedPromiseFatalSemanticExit of semanticFailureId:string * materialDeltaKind:string
            | NativeTerminalCommitClearedByMaterialDelta of semanticFailureId:string * materialDeltaKind:string
            | NativeTerminalCommitNotRequired of reason:CompilerKernelV2.OperationalReasonId

        let nativeTerminalCommitClassText = function
            | NativeTerminalCommitFailedPromiseFatalSemanticExit(semanticFailureId, materialDeltaKind) -> "TerminalCommitClass(FailedPromiseFatalSemanticExit|semantic_failure_id=" + nonEmptyOr "unknown" semanticFailureId + "|material_delta=" + nonEmptyOr "unknown" materialDeltaKind + ")"
            | NativeTerminalCommitClearedByMaterialDelta(semanticFailureId, materialDeltaKind) -> "TerminalCommitClass(ClearedByMaterialDelta|semantic_failure_id=" + nonEmptyOr "unknown" semanticFailureId + "|material_delta=" + nonEmptyOr "unknown" materialDeltaKind + ")"
            | NativeTerminalCommitNotRequired reason -> "TerminalCommitClass(NotRequired|reason=" + nonEmptyOr "unknown" (CompilerKernelV2.OperationalReasonIdOps.text reason) + ")"

        let nativeActualSemanticDeltaClassFor rootPromiseAlreadyFailed semanticFactCount astDeltaId =
            match astDeltaId with
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, _, _) -> NativeActualSemanticPureTopologyMaterializedWitness
            | NativeAstDeltaSemanticPlateauPoison _
            | NativeAstDeltaCyclePoisonInjected _ when rootPromiseAlreadyFailed -> NativeActualSemanticFatalPromiseFailure
            | NativeAstDeltaSemanticPlateauPoison _
            | NativeAstDeltaCyclePoisonInjected _ when semanticFactCount <= 0L -> NativeActualSemanticFatalPromiseFailure
            | NativeAstDeltaSemanticPlateauPoison _
            | NativeAstDeltaCyclePoisonInjected _ -> NativeActualSemanticPureTopologyMaterializedWitness
            | _ when semanticFactCount > 0L -> NativeActualSemanticTermOrTyFact
            | NativeAstDeltaExecutePureAstStep _ -> NativeActualSemanticPureTopologyDelta
            | _ -> NativeActualSemanticNone

        type ConsumerDeltaKindAfterExecutionId =
            | ConsumerDeltaRealTermOrTyFactProduced of count:int64
            | ConsumerDeltaPureSidecarDrain of count:int64
            | ConsumerDeltaPureParentContinuation of count:int64
            | ConsumerDeltaPureTopologyDelta of count:int64
            | ConsumerDeltaNoSemanticFact

        let consumerDeltaKindAfterExecutionText = function
            | ConsumerDeltaRealTermOrTyFactProduced count -> "ConsumerDeltaKind(RealTermOrTyFactProduced|facts=" + string count + ")"
            | ConsumerDeltaPureSidecarDrain count -> "ConsumerDeltaKind(PureSidecarDrain|facts=" + string count + ")"
            | ConsumerDeltaPureParentContinuation count -> "ConsumerDeltaKind(PureParentContinuation|facts=" + string count + ")"
            | ConsumerDeltaPureTopologyDelta count -> "ConsumerDeltaKind(PureTopologyDelta|facts=" + string count + ")"
            | ConsumerDeltaNoSemanticFact -> "ConsumerDeltaKind(None)"

        type NativeClosureBlockerClass =
            | NativeClosureBlockerSidecar
            | NativeClosureBlockerParentContinuation
            | NativeClosureBlockerSemanticStaleRetarget
            | NativeClosureBlockerIdleCrossKind
            | NativeClosureBlockerCyclePoison
            | NativeClosureBlockerPlateauPoison
            | NativeClosureBlockerOther

        let nativeClosureBlockerClassText = function
            | NativeClosureBlockerSidecar -> "sidecar"
            | NativeClosureBlockerParentContinuation -> "parent_continuation"
            | NativeClosureBlockerSemanticStaleRetarget -> "semantic_stale_retarget"
            | NativeClosureBlockerIdleCrossKind -> "idle_cross_kind"
            | NativeClosureBlockerCyclePoison -> "cycle_poison"
            | NativeClosureBlockerPlateauPoison -> "plateau_poison"
            | NativeClosureBlockerOther -> "other"

        // Runtime blocker authority is projected directly from the typed metronome
        // decision. Human blocker text is no longer parsed back into execution state.
        let metronomeTerminalAuthorityBlockerClass = function
            | MetronomeTerminalIdleCrossKindActiveTySidecarTimeout -> NativeClosureBlockerIdleCrossKind
            | MetronomeTerminalSemanticStaleRetargetShadowTimeoutPierce -> NativeClosureBlockerSemanticStaleRetarget
            | MetronomeTerminalParentReplayCycleBreakPoisonShadowTimeoutPierce -> NativeClosureBlockerCyclePoison
            | MetronomeTerminalApplySpineStoreDirect
            | MetronomeTerminalDynamicRecordKeyBridgeTailPierce
            | MetronomeTerminalNoRootBudgetParentReplayImmediateFill
            | MetronomeTerminalDeferredChildShadowTimeout
            | MetronomeTerminalParentContinuationCycleShadowTimeout
            | MetronomeTerminalParentReplayStatusPreservedCacheHandoff -> NativeClosureBlockerParentContinuation
            | MetronomeTerminalObservedPinnedAuthority
            | MetronomeTerminalStackFenceShadowTimeoutPierce
            | MetronomeTerminalPendingGraphCommittedTerminal -> NativeClosureBlockerOther

        let nativeClosureKindBlockerClass = function
            | NativeClosureTySidecarPrefetch
            | NativeClosureTySidecarDrain -> NativeClosureBlockerSidecar
            | NativeClosureParentReplayPoison
            | NativeClosureParentCacheHandoffWake
            | NativeClosureParentReplayStatusPreservedCacheHandoff -> NativeClosureBlockerParentContinuation
            | NativeClosureSemanticStaleRetarget -> NativeClosureBlockerSemanticStaleRetarget
            | _ -> NativeClosureBlockerOther

        let nativeClosureBlockerClassAfterAst baseClass plateauArmed = function
            | NativeAstDeltaCyclePoisonInjected _ -> NativeClosureBlockerCyclePoison
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, kind, _) ->
                match nativeClosureKindBlockerClass kind with
                | NativeClosureBlockerOther -> baseClass
                | typedClass -> typedClass
            | NativeAstDeltaSemanticPlateauPoison(_, kind, _) ->
                match nativeClosureKindBlockerClass kind with
                | NativeClosureBlockerOther -> NativeClosureBlockerPlateauPoison
                | typedClass -> typedClass
            | _ when plateauArmed -> NativeClosureBlockerPlateauPoison
            | _ -> baseClass

        let private nativeClosureBlockerIsTopology = function
            | NativeClosureBlockerSemanticStaleRetarget
            | NativeClosureBlockerIdleCrossKind
            | NativeClosureBlockerCyclePoison
            | NativeClosureBlockerPlateauPoison -> true
            | _ -> false

        let consumerDeltaKindAfterExecutionFor (blockerClass:NativeClosureBlockerClass) (semanticFactCount:int64) (astDeltaId:NativeAstEvaluationDeltaResultId) =
            if semanticFactCount <= 0L && nativeClosureBlockerIsTopology blockerClass then ConsumerDeltaPureTopologyDelta 0L
            elif semanticFactCount <= 0L then ConsumerDeltaNoSemanticFact
            else
                match astDeltaId with
                | NativeAstDeltaPureTopologyWitnessMaterialized(_, kind, _)
                | NativeAstDeltaSemanticPlateauPoison(_, kind, _)
                    when blockerClass = NativeClosureBlockerSidecar
                         || nativeClosureKindBlockerClass kind = NativeClosureBlockerSidecar ->
                    ConsumerDeltaPureSidecarDrain semanticFactCount
                | NativeAstDeltaPureTopologyWitnessMaterialized(_, _, _)
                | NativeAstDeltaSemanticPlateauPoison(_, _, _)
                | NativeAstDeltaCyclePoisonInjected _
                    when blockerClass = NativeClosureBlockerParentContinuation ->
                    ConsumerDeltaPureParentContinuation semanticFactCount
                | NativeAstDeltaPureTopologyWitnessMaterialized(_, _, _)
                | NativeAstDeltaSemanticPlateauPoison _
                | NativeAstDeltaCyclePoisonInjected _ ->
                    ConsumerDeltaPureTopologyDelta semanticFactCount
                | _ -> ConsumerDeltaRealTermOrTyFactProduced semanticFactCount

        type PlateauInjectionDecisionId =
            | PlateauTopologySatisfiedButZeroNewFact of blocker:NativeClosureBlockerClass
            | PlateauCycleEvidenceWithoutSemanticFact of blocker:NativeClosureBlockerClass
            | PlateauMeasuredCounterDeltaWithoutKindFact of blocker:NativeClosureBlockerClass
            | PlateauNotInjected
            | PlateauSuppressedPureTopologyDelta of facts:int64
            | PlateauSuppressedPureTopologyZeroFactWitness of blocker:NativeClosureBlockerClass

        let plateauInjectionDecisionText = function
            | PlateauTopologySatisfiedButZeroNewFact blocker -> "PlateauInjection(TopologySatisfiedButZeroNewFact|blocker=" + nativeClosureBlockerClassText blocker + ")"
            | PlateauCycleEvidenceWithoutSemanticFact blocker -> "PlateauInjection(CycleEvidenceWithoutSemanticFact|blocker=" + nativeClosureBlockerClassText blocker + ")"
            | PlateauMeasuredCounterDeltaWithoutKindFact blocker -> "PlateauInjection(MeasuredCounterDeltaWithoutKindFact|blocker=" + nativeClosureBlockerClassText blocker + ")"
            | PlateauSuppressedPureTopologyDelta facts -> "PlateauInjection(SuppressedPureTopologyDelta|facts=" + string facts + ")"
            | PlateauSuppressedPureTopologyZeroFactWitness blocker -> "PlateauInjection(SuppressedPureTopologyZeroFactWitness|blocker=" + nativeClosureBlockerClassText blocker + ")"
            | PlateauNotInjected -> "PlateauInjection(NotInjected)"

        let plateauInjectionDecisionFor blocker semanticFactCount astDeltaId =
            match astDeltaId with
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, _, _) when semanticFactCount > 0L -> PlateauSuppressedPureTopologyDelta semanticFactCount
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, _, _) -> PlateauSuppressedPureTopologyZeroFactWitness blocker
            | NativeAstDeltaSemanticPlateauPoison _
            | NativeAstDeltaCyclePoisonInjected _ when semanticFactCount > 0L -> PlateauSuppressedPureTopologyDelta semanticFactCount
            | NativeAstDeltaSemanticPlateauPoison _ when semanticFactCount <= 0L -> PlateauTopologySatisfiedButZeroNewFact blocker
            | NativeAstDeltaCyclePoisonInjected _ when semanticFactCount <= 0L -> PlateauCycleEvidenceWithoutSemanticFact blocker
            | _ -> PlateauNotInjected

        let abortBlockerFreshnessFor rootCompleteStores terminalSignals rootCompleteDelta terminalSignalDelta =
            if rootCompleteDelta > 0L || terminalSignalDelta > 0L then AbortBlockerRecentDelta(rootCompleteDelta, terminalSignalDelta)
            elif rootCompleteStores > 0 || terminalSignals > 0 then AbortBlockerCumulativeOnly(int64 rootCompleteStores, int64 terminalSignals)
            else AbortBlockerNone

        let abortBlockerFreshnessText = function
            | AbortBlockerNone -> "AbortBlocker(None)"
            | AbortBlockerRecentDelta(rootDelta, terminalDelta) -> "AbortBlocker(RecentDelta|root_delta=" + string rootDelta + "|terminal_delta=" + string terminalDelta + ")"
            | AbortBlockerCumulativeOnly(roots, terminals) -> "AbortBlocker(CumulativeOnly|roots=" + string roots + "|terminals=" + string terminals + ")"

        let abortBlockerIsRecentDelta = function
            | AbortBlockerRecentDelta _ -> true
            | _ -> false

        let abortBlockerIsCumulativeOnly = function
            | AbortBlockerCumulativeOnly _ -> true
            | _ -> false

        // MIGRATION migration phase: migrate authority from string/Contains and
        // cumulative snapshot counters into a typed closure/failure ledger.
        // The raw evidence still comes from legacy HUD/cache bridges for now,
        // but gates consume this DU instead of naked booleans.
        type NativeClosureFailureClassId =
            | NativeClosureFailureSemanticStaleRetarget
            | NativeClosureFailureIdleCrossKind
            | NativeClosureFailureRootPromisePlateau
            | NativeClosureFailureTopologyCycle

        let nativeClosureFailureClassText = function
            | NativeClosureFailureSemanticStaleRetarget -> "SemanticStaleRetarget"
            | NativeClosureFailureIdleCrossKind -> "IdleCrossKind"
            | NativeClosureFailureRootPromisePlateau -> "RootPromisePlateau"
            | NativeClosureFailureTopologyCycle -> "TopologyCycle"

        type NativeClosureFailureLedgerAuthorityId =
            | NativeClosureFailureLedgerNoConsumer
            | NativeClosureFailureLedgerFailedCycle of failureClass:NativeClosureFailureClassId * blocker:string * recentDelta:bool * typedPayload:string
            | NativeClosureFailureLedgerFailedPlateau of failureClass:NativeClosureFailureClassId * blocker:string * semanticFactKind:string * recentDelta:bool * typedPayload:string
            | NativeClosureFailureLedgerNoFurther of reason:CompilerKernelV2.OperationalReasonId * recentDelta:bool * typedPayload:string

        let nativeClosureFailureLedgerAuthorityText = function
            | NativeClosureFailureLedgerNoConsumer -> "NativeClosureFailureLedger(NoConsumer)"
            | NativeClosureFailureLedgerFailedCycle(failureClass, blocker, recentDelta, typedPayload) -> "NativeClosureFailureLedger(FailedCycle|class=" + nativeClosureFailureClassText failureClass + "|blocker=" + blocker + "|recent_delta=" + string recentDelta + "|typed_payload=" + typedPayload + ")"
            | NativeClosureFailureLedgerFailedPlateau(failureClass, blocker, semanticFactKind, recentDelta, typedPayload) -> "NativeClosureFailureLedger(FailedPlateau|class=" + nativeClosureFailureClassText failureClass + "|blocker=" + blocker + "|semantic_fact_kind=" + semanticFactKind + "|recent_delta=" + string recentDelta + "|typed_payload=" + typedPayload + ")"
            | NativeClosureFailureLedgerNoFurther(reason, recentDelta, typedPayload) -> "NativeClosureFailureLedger(NoFurther|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|recent_delta=" + string recentDelta + "|typed_payload=" + typedPayload + ")"

        let nativeClosureFailureLedgerConsumerAttached = function
            | NativeClosureFailureLedgerNoConsumer -> false
            | _ -> true

        let nativeClosureFailureLedgerCanCollapseRoot = function
            | NativeClosureFailureLedgerFailedCycle(_, _, recentDelta, _)
            | NativeClosureFailureLedgerFailedPlateau(_, _, _, recentDelta, _)
            | NativeClosureFailureLedgerNoFurther(_, recentDelta, _) -> not recentDelta
            | NativeClosureFailureLedgerNoConsumer -> false

        let nativeClosureFailureLedgerBlockerText = function
            | NativeClosureFailureLedgerFailedCycle(_, blocker, _, _) -> blocker
            | NativeClosureFailureLedgerFailedPlateau(_, blocker, _, _, _) -> blocker
            | NativeClosureFailureLedgerNoFurther(reason, _, _) -> CompilerKernelV2.OperationalReasonIdOps.text reason
            | NativeClosureFailureLedgerNoConsumer -> "none"

        let nativeClosureFailureLedgerTypedPayloadText = function
            | NativeClosureFailureLedgerFailedCycle(_, _, _, typedPayload) -> typedPayload
            | NativeClosureFailureLedgerFailedPlateau(_, _, _, _, typedPayload) -> typedPayload
            | NativeClosureFailureLedgerNoFurther(_, _, typedPayload) -> typedPayload
            | NativeClosureFailureLedgerNoConsumer -> "NativeTerminalPayload(Pending)"

        // MIGRATION: preserve the working typed ledger, but stop collapsing
        // different semantic failures into the old generic topology blocker.
        // The ledger now carries a small evidence slice so the terminal payload
        // can point at SemanticStaleRetarget / IdleCrossKind instead of a
        // fallback NativeTopologyResolutionConsumerAttachedCyclePoison label.
        type NativeClosureEvidenceNeedle =
            | NativeClosureEvidenceSemanticStaleRetarget
            | NativeClosureEvidenceIdleCrossKind
            | NativeClosureEvidencePlateauPoison
            | NativeClosureEvidenceCycle

        type NativeClosureEvidenceFallback =
            | NativeClosureFallbackSemanticStaleRetarget
            | NativeClosureFallbackIdleCrossKind
            | NativeClosureFallbackRootPromisePlateau
            | NativeClosureFallbackTopologyCycle

        let private nativeClosureEvidenceNeedleText = function
            | NativeClosureEvidenceSemanticStaleRetarget -> "SemanticStaleRetarget"
            | NativeClosureEvidenceIdleCrossKind -> "IdleCrossKind"
            | NativeClosureEvidencePlateauPoison -> "PlateauPoison"
            | NativeClosureEvidenceCycle -> "Cycle"

        let private nativeClosureEvidenceFallbackText = function
            | NativeClosureFallbackSemanticStaleRetarget -> "SemanticStaleRetargetShadowTimeoutPierce"
            | NativeClosureFallbackIdleCrossKind -> "IdleCrossKindActiveTySidecarTimeout"
            | NativeClosureFallbackRootPromisePlateau -> "RootPromiseFailedPlateau"
            | NativeClosureFallbackTopologyCycle -> "NativeTopologyResolutionConsumerAttachedCyclePoison"

        let nativeClosureFailureEvidenceSlice (fallback: NativeClosureEvidenceFallback) (evidence:string) (needle: NativeClosureEvidenceNeedle) =
            let fallbackText = nativeClosureEvidenceFallbackText fallback
            if String.IsNullOrWhiteSpace evidence then fallbackText
            else
                let tokens = diagnosticTextTokensLower evidence
                let segments = diagnosticTextSegmentsLower evidence
                let matchesNeedle =
                    match needle with
                    | NativeClosureEvidenceSemanticStaleRetarget ->
                        diagnosticTextHasAny [ "semanticstaleretarget"; "stale_retarget" ] tokens
                        || (Set.contains "stale" segments && Set.contains "retarget" segments)
                    | NativeClosureEvidenceIdleCrossKind ->
                        diagnosticTextHasAny [ "idlecrosskind"; "idle_cross_kind" ] tokens
                        || (Set.contains "idle" segments && Set.contains "cross" segments && Set.contains "kind" segments)
                    | NativeClosureEvidencePlateauPoison ->
                        diagnosticTextHasAny [ "plateaupoison"; "plateau_poison" ] tokens
                        || Set.contains "plateau" segments
                    | NativeClosureEvidenceCycle ->
                        diagnosticTextHasAny [ "cyclepoison"; "cycle_poison" ] tokens
                        || Set.contains "cycle" segments
                if not matchesNeedle then fallbackText
                else
                    let normalized = evidence.Replace("\"", "'").Replace("\\", "/").Replace("\r", " ").Replace("\n", " ")
                    normalized.Substring(0, min 224 normalized.Length)

        let nativeClosureFailureLedgerCollapseThresholdS = function
            | NativeClosureFailureLedgerFailedCycle(NativeClosureFailureSemanticStaleRetarget, _, _, _) -> 30L
            | NativeClosureFailureLedgerFailedPlateau(NativeClosureFailureIdleCrossKind, _, _, _, _) -> 45L
            | NativeClosureFailureLedgerFailedCycle _ -> 60L
            | NativeClosureFailureLedgerFailedPlateau _ -> 60L
            | NativeClosureFailureLedgerNoFurther _ -> 30L
            | NativeClosureFailureLedgerNoConsumer -> Int64.MaxValue

        let nativeClosureFailureLedgerAuthorityFor minimalFailureClass semanticStaleRetargetEvidence idleCrossKindEvidence rootPromiseFailedEvidence topologyResolutionEvidence recentDelta evidenceText =
            let mkPayload payloadClass blocker starved result =
                let diagnosis = "SemanticDiagnosis(ClosureLedgerAuthority|message=" + blocker + ")"
                let minimal = minimalTerminalPayloadForBridge payloadClass blocker diagnosis blocker starved result
                let rich, _ = promoteMinimalTerminalPayloadToRich minimal
                nativeTerminalPayloadText rich
            if semanticStaleRetargetEvidence then
                let blocker = nativeClosureFailureEvidenceSlice NativeClosureFallbackSemanticStaleRetarget evidenceText NativeClosureEvidenceSemanticStaleRetarget
                NativeClosureFailureLedgerFailedCycle(NativeClosureFailureSemanticStaleRetarget, blocker, recentDelta, mkPayload MinimalTerminalPayloadSemanticStaleRetarget blocker 0 "ConsumerResultVerdict(SemanticStaleRetargetLedgerAuthority)")
            elif idleCrossKindEvidence then
                let blocker = nativeClosureFailureEvidenceSlice NativeClosureFallbackIdleCrossKind evidenceText NativeClosureEvidenceIdleCrossKind
                NativeClosureFailureLedgerFailedPlateau(NativeClosureFailureIdleCrossKind, blocker, "none", recentDelta, mkPayload MinimalTerminalPayloadPlateauPoison blocker 0 "ConsumerResultVerdict(IdleCrossKindLedgerAuthority)")
            elif rootPromiseFailedEvidence && minimalFailureClass = MinimalNativeFailureSemanticStaleRetarget then
                let blocker = nativeClosureFailureEvidenceSlice NativeClosureFallbackSemanticStaleRetarget evidenceText NativeClosureEvidenceSemanticStaleRetarget
                NativeClosureFailureLedgerFailedCycle(NativeClosureFailureSemanticStaleRetarget, blocker, recentDelta, mkPayload MinimalTerminalPayloadSemanticStaleRetarget blocker 0 "ConsumerResultVerdict(RootPromiseFailedSemanticLedgerAuthority)")
            elif rootPromiseFailedEvidence then
                let blocker = nativeClosureFailureEvidenceSlice NativeClosureFallbackRootPromisePlateau evidenceText NativeClosureEvidencePlateauPoison
                NativeClosureFailureLedgerFailedPlateau(NativeClosureFailureRootPromisePlateau, blocker, "none", recentDelta, mkPayload MinimalTerminalPayloadPlateauPoison blocker 0 "ConsumerResultVerdict(RootPromiseFailedPlateauLedgerAuthority)")
            elif topologyResolutionEvidence then
                let blocker = nativeClosureFailureEvidenceSlice NativeClosureFallbackTopologyCycle evidenceText NativeClosureEvidenceCycle
                NativeClosureFailureLedgerFailedCycle(NativeClosureFailureTopologyCycle, blocker, recentDelta, mkPayload MinimalTerminalPayloadCyclePoison blocker 0 "ConsumerResultVerdict(TopologyResolutionLedgerAuthority)")
            else NativeClosureFailureLedgerNoConsumer

        // MIGRATION: promote the 1758 evidence from timeout telemetry into an
        // active wait-for graph verdict.  The log proved a terminal shape at
        // active=0, frontier=0, continuation_cell_waiting_no_sidecar_authority,
        // source_node:8195443 and no fresh deltas long before the timeout-based
        // semantic stale retarget collapse.  This DU lets the native closure
        // ledger short-circuit from graph shape instead of waiting for metronome
        // starvation counters.
        // MIGRATION: canonical topology obligations are live work, not terminal
        // absence.  The 1781 log ended with idle_cross_kind, frontier=0,
        // active=0, canonical=2 and facts=1.  Treat that shape as a deferred
        // topology continuation until the canonical side drains or an explicit
        // material term/type delta clears the root promise.
        type NativeWaitForGraphTopologyCollapseReasonId =
            | NativeWaitForGraphAllCanonicalTopologyDrained
            | NativeWaitForGraphCanonicalTopologyPending
            | NativeWaitForGraphCrossKindTopologyCanonicalPending

        type NativeWaitForGraphTopologyProof = private {
            pendingCanonical : int64
            pendingFrontier : int64
            activeWorkers : int64
            typedTopologyTerminal : bool
            idleCrossKind : bool
            semanticStaleRetarget : bool
            reason : NativeWaitForGraphTopologyCollapseReasonId
        }

        let private nativeWaitForGraphTopologyCollapseReasonText = function
            | NativeWaitForGraphAllCanonicalTopologyDrained -> "all_canonical_topology_drained"
            | NativeWaitForGraphCanonicalTopologyPending -> "canonical_topology_pending"
            | NativeWaitForGraphCrossKindTopologyCanonicalPending -> "cross_kind_topology_obligation_has_canonical_pending"

        let private nativeWaitForGraphTopologyProofText proof =
            "canonical=" + string proof.pendingCanonical
            + "|frontier=" + string proof.pendingFrontier
            + "|active=" + string proof.activeWorkers
            + "|typed_topology_terminal=" + string proof.typedTopologyTerminal
            + "|idle_cross_kind=" + string proof.idleCrossKind
            + "|semantic_stale_retarget=" + string proof.semanticStaleRetarget
            + "|reason=" + nativeWaitForGraphTopologyCollapseReasonText proof.reason

        type NativeWaitForGraphTopologyCollapseGateId =
            | NativeWaitForGraphTopologyCollapseAllowed of proof:NativeWaitForGraphTopologyProof
            | NativeWaitForGraphTopologyCollapseDeferredCanonical of proof:NativeWaitForGraphTopologyProof
            | NativeWaitForGraphTopologyCollapseDeferredCrossKind of proof:NativeWaitForGraphTopologyProof

        let nativeWaitForGraphTopologyCollapseGateText = function
            | NativeWaitForGraphTopologyCollapseAllowed proof -> "NativeWaitForGraphTopologyCollapseGate(Allowed|" + nativeWaitForGraphTopologyProofText proof + ")"
            | NativeWaitForGraphTopologyCollapseDeferredCanonical proof -> "NativeWaitForGraphTopologyCollapseGate(DeferredCanonical|" + nativeWaitForGraphTopologyProofText proof + ")"
            | NativeWaitForGraphTopologyCollapseDeferredCrossKind proof -> "NativeWaitForGraphTopologyCollapseGate(DeferredCrossKind|" + nativeWaitForGraphTopologyProofText proof + ")"

        let nativeWaitForGraphTopologyCollapseGateAllowsCollapse = function
            | NativeWaitForGraphTopologyCollapseAllowed _ -> true
            | _ -> false

        type NativeWaitForGraphLiveEvidence = private {
            pendingFrontier : int64
            pendingCanonical : int64
            activeWorkers : int64
            physicalSidecarPending : bool
            continuationBlocked : bool
            parentContinuationLiveness : NativeParentContinuationLivenessId
            continuationHistoricalHint : bool
            source : SemanticSourceSpanId
        }

        let private nativeWaitForGraphLiveEvidenceText proof =
            "DeferredByLiveReplayEvidence|frontier=" + string proof.pendingFrontier
            + "|canonical=" + string proof.pendingCanonical
            + "|active=" + string proof.activeWorkers
            + "|sidecar=" + (if proof.physicalSidecarPending then "draining" else "absent")
            + "|continuation=" + (if proof.continuationBlocked then "pending" else "none")
            + "|continuation_authority=" + nativeParentContinuationLivenessText proof.parentContinuationLiveness
            + "|continuation_historical_hint=" + string proof.continuationHistoricalHint
            + "|source=" + semanticSourceSpanText proof.source

        type NativeWaitForGraphOpenReasonId =
            | NativeWaitForGraphOpenLiveEvidence of proof:NativeWaitForGraphLiveEvidence
            | NativeWaitForGraphOpenTopologyDeferred of NativeWaitForGraphTopologyCollapseGateId
            | NativeWaitForGraphOpenNotClosed

        let nativeWaitForGraphOpenReasonText = function
            | NativeWaitForGraphOpenLiveEvidence proof -> nativeWaitForGraphLiveEvidenceText proof
            | NativeWaitForGraphOpenTopologyDeferred gate -> nativeWaitForGraphTopologyCollapseGateText gate
            | NativeWaitForGraphOpenNotClosed -> "wait_for_graph_not_closed"

        type NativeWaitForGraphDeadlockReasonId =
            | NativeWaitDeadlockFatalPromiseFailureNotClearedByMaterialDelta
            | NativeWaitDeadlockMaterializedTerminalWithNoExecutableFrontier
            | NativeWaitDeadlockStrandedCanonicalPendingWithoutFrontier
            | NativeWaitDeadlockFatalPromiseFailureActionEmitted

        let private nativeWaitForGraphDeadlockReasonText = function
            | NativeWaitDeadlockFatalPromiseFailureNotClearedByMaterialDelta -> "fatal_promise_failure_not_cleared_by_material_delta"
            | NativeWaitDeadlockMaterializedTerminalWithNoExecutableFrontier -> "materialized_terminal_with_no_executable_frontier"
            | NativeWaitDeadlockStrandedCanonicalPendingWithoutFrontier -> "stranded_canonical_pending_without_frontier"
            | NativeWaitDeadlockFatalPromiseFailureActionEmitted -> "fatal_promise_failure_action_emitted"

        type NativeWaitForGraphVerdictId =
            | NativeWaitForGraphOpen of NativeWaitForGraphOpenReasonId
            | NativeWaitForGraphDeadlocked of source:SemanticSourceSpanId * reason:NativeWaitForGraphDeadlockReasonId * payload:string
            | NativeWaitForGraphResolvedByDelta of reason:CompilerKernelV2.OperationalReasonId

        let nativeWaitForGraphVerdictText = function
            | NativeWaitForGraphOpen reason -> "NativeWaitForGraph(Open|reason=" + nativeWaitForGraphOpenReasonText reason + ")"
            | NativeWaitForGraphDeadlocked(source, reason, payload) -> "NativeWaitForGraph(Deadlocked|source=" + semanticSourceSpanText source + "|reason=" + nativeWaitForGraphDeadlockReasonText reason + "|payload=" + nonEmptyOr "required" payload + ")"
            | NativeWaitForGraphResolvedByDelta reason -> "NativeWaitForGraph(ResolvedByDelta|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let nativeWaitForGraphCanCollapseRoot = function
            | NativeWaitForGraphDeadlocked _ -> true
            | _ -> false

        let nativeWaitForGraphPayloadText = function
            | NativeWaitForGraphDeadlocked(_, _, payload) -> payload
            | NativeWaitForGraphOpen reason -> nativeWaitForGraphOpenReasonText reason
            | NativeWaitForGraphResolvedByDelta reason -> CompilerKernelV2.OperationalReasonIdOps.text reason

        let nativeWaitForGraphTopologyDeferredByCanonical = function
            | NativeWaitForGraphOpen(NativeWaitForGraphOpenTopologyDeferred(NativeWaitForGraphTopologyCollapseDeferredCanonical _))
            | NativeWaitForGraphOpen(NativeWaitForGraphOpenTopologyDeferred(NativeWaitForGraphTopologyCollapseDeferredCrossKind _)) -> true
            | _ -> false

        type NativeWaitForGraphDebtSignalId =
            | NativeWaitForGraphDebtTerminalPayload
            | NativeWaitForGraphDebtContinuationHistorical
            | NativeWaitForGraphDebtCrossKindTopology

        let nativeWaitForGraphDebtSignalsOfParentSignals (signals:Set<NoWorkParentJobBindSignalId>) =
            [ if Set.contains NoWorkParentJobBindRootPromiseFailure signals
                 || Set.contains NoWorkParentJobBindPlateauPoison signals then
                  yield NativeWaitForGraphDebtTerminalPayload
              if Set.contains NoWorkParentJobBindHistoricalContinuation signals then
                  yield NativeWaitForGraphDebtContinuationHistorical
              if Set.contains NoWorkParentJobBindIdleCrossKind signals then
                  yield NativeWaitForGraphDebtCrossKindTopology ]
            |> Set.ofList

        let nativeWaitForGraphTopologyCollapseGateFor pendingCanonical pendingFrontier activeWorkers typedTopologyTerminal idleCrossKind semanticStaleRetarget (debtSignals:Set<NativeWaitForGraphDebtSignalId>) =
            let proof reason =
                { pendingCanonical = pendingCanonical
                  pendingFrontier = pendingFrontier
                  activeWorkers = activeWorkers
                  typedTopologyTerminal = typedTopologyTerminal
                  idleCrossKind = idleCrossKind
                  semanticStaleRetarget = semanticStaleRetarget
                  reason = reason }
            let crossKindEvidence =
                idleCrossKind
                || Set.contains NativeWaitForGraphDebtCrossKindTopology debtSignals
            if typedTopologyTerminal && pendingCanonical > 0L && crossKindEvidence then
                NativeWaitForGraphTopologyCollapseDeferredCrossKind(proof NativeWaitForGraphCrossKindTopologyCanonicalPending)
            elif typedTopologyTerminal && pendingCanonical > 0L then
                NativeWaitForGraphTopologyCollapseDeferredCanonical(proof NativeWaitForGraphCanonicalTopologyPending)
            else NativeWaitForGraphTopologyCollapseAllowed(proof NativeWaitForGraphAllCanonicalTopologyDrained)

        // MIGRATION: make fatal promise action/clearance a typed decision instead
        // of re-inferring it from rendered HUD strings.  Assessments showed that
        // PureTopologyDelta must never clear or postpone a failed native promise;
        // only a material term/type fact or an explicit withdrawal can do that.
        type NativePromiseFailureClearanceId =
            | NativePromiseFailureClearanceNone of reason:CompilerKernelV2.OperationalReasonId
            | NativePromiseFailureClearanceMaterialDelta of factKind:string
            | NativePromiseFailureClearanceExplicitWithdrawn of reason:CompilerKernelV2.OperationalReasonId

        let nativePromiseFailureClearanceText = function
            | NativePromiseFailureClearanceNone reason -> "NativePromiseFailureClearance(None|reason=" + nonEmptyOr "unknown" (CompilerKernelV2.OperationalReasonIdOps.text reason) + ")"
            | NativePromiseFailureClearanceMaterialDelta factKind -> "NativePromiseFailureClearance(MaterialDelta|fact_kind=" + nonEmptyOr "term_or_ty" factKind + ")"
            | NativePromiseFailureClearanceExplicitWithdrawn reason -> "NativePromiseFailureClearance(ExplicitWithdrawn|reason=" + nonEmptyOr "unknown" (CompilerKernelV2.OperationalReasonIdOps.text reason) + ")"

        let nativePromiseFailureClearanceAllowsProgress = function
            | NativePromiseFailureClearanceMaterialDelta _
            | NativePromiseFailureClearanceExplicitWithdrawn _ -> true
            | NativePromiseFailureClearanceNone _ -> false

        type NativeTerminalActionSuppressionReasonId =
            | NativeTerminalActionSuppressionDeadlockObserverOnly of CompilerKernelV2.OperationalReasonId
            | NativeTerminalActionSuppressionOpenOwners of CompilerKernelV2.OperationalReasonId
            | NativeTerminalActionSuppressionWorkDagAuthority of CompilerKernelV2.OperationalReasonId
            | NativeTerminalActionSuppressionSchedulerCausality of CompilerKernelV2.OperationalReasonId
            | NativeTerminalActionSuppressionBreakthroughQuorum of CompilerKernelV2.OperationalReasonId
            | NativeTerminalActionSuppressionCommitGate of CompilerKernelV2.OperationalReasonId
            | NativeTerminalActionSuppressionLiveReplayEvidenceGate of CompilerKernelV2.OperationalReasonId
            | NativeTerminalActionSuppressionSemanticStaleRetargetBridge of CompilerKernelV2.OperationalReasonId
            | NativeTerminalActionSuppressionGateDecision of CompilerKernelV2.OperationalReasonId
            | NativeTerminalActionSuppressionLiveGraphNotTerminalEligible
            | NativeTerminalActionSuppressionFreshTopologyWitnessEpoch
            | NativeTerminalActionSuppressionTypedTerminalGate

        let nativeTerminalActionSuppressionReasonText = function
            | NativeTerminalActionSuppressionDeadlockObserverOnly reason -> "DeadlockObserverOnly|" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | NativeTerminalActionSuppressionOpenOwners reason -> "OpenOwners|" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | NativeTerminalActionSuppressionWorkDagAuthority reason -> "WorkDagAuthority|" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | NativeTerminalActionSuppressionSchedulerCausality reason -> "SchedulerCausality|" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | NativeTerminalActionSuppressionBreakthroughQuorum reason -> "BreakthroughQuorum|" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | NativeTerminalActionSuppressionCommitGate reason -> "CommitGate|" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | NativeTerminalActionSuppressionLiveReplayEvidenceGate reason -> "LiveReplayEvidenceGate|" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | NativeTerminalActionSuppressionSemanticStaleRetargetBridge reason -> "SemanticStaleRetargetBridge|" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | NativeTerminalActionSuppressionGateDecision reason -> "GateDecision|" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | NativeTerminalActionSuppressionLiveGraphNotTerminalEligible -> "LiveGraphTypestateNotTerminalEligible"
            | NativeTerminalActionSuppressionFreshTopologyWitnessEpoch -> "FreshTopologyWitnessConsumesOneProgressEpoch"
            | NativeTerminalActionSuppressionTypedTerminalGate -> "TypedTerminalGate"

        // MIGRATION MIGRATION : terminal actions are no longer failure-only.
        // NoFurther is a terminal outcome with its own identity and executor lane.
        type NativeTerminalActionSourceId =
            | NativeTerminalActionSourceProgressTickMinimal
            | NativeTerminalActionSourceHeartbeatThread

        let nativeTerminalActionSourceText = function
            | NativeTerminalActionSourceProgressTickMinimal -> "DiagJson.progress_tick_minimal"
            | NativeTerminalActionSourceHeartbeatThread -> "DiagJson.heartbeat_thread"

        type NativeTerminalActionDecisionId =
            | NativeTerminalActionNotRequired of reason:CompilerKernelV2.OperationalReasonId
            | NativeTerminalActionRequired of semanticFailureId:string * payload:string
            | NativeTerminalActionNoFurtherRequired of terminalOutcomeId:string * reason:CompilerKernelV2.OperationalReasonId * rootCompleteProofHash:string
            | NativeTerminalActionEmitted of semanticFailureId:string * payload:string * source:NativeTerminalActionSourceId
            | NativeTerminalActionNoFurtherEmitted of terminalOutcomeId:string * reason:CompilerKernelV2.OperationalReasonId * source:NativeTerminalActionSourceId
            | NativeTerminalActionSuppressed of semanticFailureId:string * reason:NativeTerminalActionSuppressionReasonId
            | NativeTerminalActionNoFurtherSuppressed of terminalOutcomeId:string * reason:NativeTerminalActionSuppressionReasonId

        let nativeTerminalActionDecisionText = function
            | NativeTerminalActionNotRequired reason -> "NativeTerminalAction(NotRequired|reason=" + nonEmptyOr "unknown" (CompilerKernelV2.OperationalReasonIdOps.text reason) + ")"
            | NativeTerminalActionRequired(id, payload) -> "NativeTerminalAction(RequiredSemanticFailure|semantic_failure_id=" + nonEmptyOr "unknown" id + "|payload=" + nonEmptyOr "required" payload + ")"
            | NativeTerminalActionNoFurtherRequired(id, reason, proofHash) -> "NativeTerminalAction(RequiredNoFurther|terminal_outcome_id=" + nonEmptyOr "unknown" id + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|root_complete_proof_hash=" + nonEmptyOr "unknown" proofHash + ")"
            | NativeTerminalActionEmitted(id, payload, source) -> "NativeTerminalAction(EmittedSemanticFailure|semantic_failure_id=" + nonEmptyOr "unknown" id + "|source=" + nativeTerminalActionSourceText source + "|payload=" + nonEmptyOr "required" payload + ")"
            | NativeTerminalActionNoFurtherEmitted(id, reason, source) -> "NativeTerminalAction(EmittedNoFurther|terminal_outcome_id=" + nonEmptyOr "unknown" id + "|source=" + nativeTerminalActionSourceText source + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NativeTerminalActionSuppressed(id, reason) -> "NativeTerminalAction(SuppressedSemanticFailure|semantic_failure_id=" + nonEmptyOr "unknown" id + "|reason=" + nativeTerminalActionSuppressionReasonText reason + ")"
            | NativeTerminalActionNoFurtherSuppressed(id, reason) -> "NativeTerminalAction(SuppressedNoFurther|terminal_outcome_id=" + nonEmptyOr "unknown" id + "|reason=" + nativeTerminalActionSuppressionReasonText reason + ")"

        type NativeTerminalActionExecutorStageId =
            | NativeTerminalActionStageNotRequired of reason:CompilerKernelV2.OperationalReasonId
            | NativeTerminalActionStagePending of semanticFailureId:string
            | NativeTerminalActionStagePendingNoFurther of terminalOutcomeId:string
            | NativeTerminalActionStageEmitted of semanticFailureId:string * source:NativeTerminalActionSourceId
            | NativeTerminalActionStageEmittedNoFurther of terminalOutcomeId:string * source:NativeTerminalActionSourceId
            | NativeTerminalActionStageSuppressed of semanticFailureId:string * reason:NativeTerminalActionSuppressionReasonId
            | NativeTerminalActionStageSuppressedNoFurther of terminalOutcomeId:string * reason:NativeTerminalActionSuppressionReasonId

        let nativeTerminalActionExecutorStageFor = function
            | NativeTerminalActionNotRequired reason -> NativeTerminalActionStageNotRequired reason
            | NativeTerminalActionRequired(id, _) -> NativeTerminalActionStagePending id
            | NativeTerminalActionNoFurtherRequired(id, _, _) -> NativeTerminalActionStagePendingNoFurther id
            | NativeTerminalActionEmitted(id, _, source) -> NativeTerminalActionStageEmitted(id, source)
            | NativeTerminalActionNoFurtherEmitted(id, _, source) -> NativeTerminalActionStageEmittedNoFurther(id, source)
            | NativeTerminalActionSuppressed(id, reason) -> NativeTerminalActionStageSuppressed(id, reason)
            | NativeTerminalActionNoFurtherSuppressed(id, reason) -> NativeTerminalActionStageSuppressedNoFurther(id, reason)

        let nativeTerminalActionExecutorStageText = function
            | NativeTerminalActionStageNotRequired reason -> "TerminalActionStage(NotRequired|reason=" + nonEmptyOr "unknown" (CompilerKernelV2.OperationalReasonIdOps.text reason) + ")"
            | NativeTerminalActionStagePending id -> "TerminalActionStage(PendingSemanticFailure|semantic_failure_id=" + nonEmptyOr "unknown" id + ")"
            | NativeTerminalActionStagePendingNoFurther id -> "TerminalActionStage(PendingNoFurther|terminal_outcome_id=" + nonEmptyOr "unknown" id + ")"
            | NativeTerminalActionStageEmitted(id, source) -> "TerminalActionStage(EmittedSemanticFailure|semantic_failure_id=" + nonEmptyOr "unknown" id + "|source=" + nativeTerminalActionSourceText source + ")"
            | NativeTerminalActionStageEmittedNoFurther(id, source) -> "TerminalActionStage(EmittedNoFurther|terminal_outcome_id=" + nonEmptyOr "unknown" id + "|source=" + nativeTerminalActionSourceText source + ")"
            | NativeTerminalActionStageSuppressed(id, reason) -> "TerminalActionStage(SuppressedSemanticFailure|semantic_failure_id=" + nonEmptyOr "unknown" id + "|reason=" + nativeTerminalActionSuppressionReasonText reason + ")"
            | NativeTerminalActionStageSuppressedNoFurther(id, reason) -> "TerminalActionStage(SuppressedNoFurther|terminal_outcome_id=" + nonEmptyOr "unknown" id + "|reason=" + nativeTerminalActionSuppressionReasonText reason + ")"

        // MIGRATION: unify the live-tail proof used by terminal-action,
        // stale-retarget bridge, root handoff and watchdog abort paths.  Older
        // lanes each blocked one class of false terminal, but EJP0023 could still
        // win after the bridge said "defer" because low CPU looked scary.  This
        // DU is fail-closed: if any pending/active/cross/sidecar/continuation
        // witness is present, watchdogs must sleep/hold instead of exiting.
        type LiveReplayEvidenceGateId =
            | LiveReplayEvidenceAbsent of proof:CompilerKernelV2.OperationalReasonId
            | LiveReplayEvidencePresent of proof:CompilerKernelV2.OperationalReasonId

        let liveReplayEvidenceGateText = function
            | LiveReplayEvidenceAbsent proof -> "LiveReplayEvidence(Absent|" + CompilerKernelV2.OperationalReasonIdOps.text proof + "|has_live=false)"
            | LiveReplayEvidencePresent proof -> "LiveReplayEvidence(Present|" + CompilerKernelV2.OperationalReasonIdOps.text proof + "|has_live=true)"

        let liveReplayEvidenceGateHasLive = function
            | LiveReplayEvidencePresent _ -> true
            | _ -> false

        // MIGRATION MIGRATION : the assessment asked to stop layering
        // string-based gates and move the scheduler ledger toward recursive DUs
        // with phantom indices.  This block is the hard-domain spine.  It is
        // intentionally more than telemetry: later rounds will replace the
        // remaining Contains/snapshotKindCount authorities by consuming these
        // values directly from WaitGraph/BridgeGate/RootCollapseAuthority.
        type ReplayTermKind = | ReplayTermKind
        type ReplayTyKind = | ReplayTyKind
        type ReplayCrossKind = | ReplayCrossKind
        type ReplayParentResumeKind = | ReplayParentResumeKind
        type ReplaySidecarDrainKind = | ReplaySidecarDrainKind
        type ReplayDynamicJoinKind = | ReplayDynamicJoinKind
        type ReplayUnknownKind = | ReplayUnknownKind

        [<Struct>]
        type ReplayKindTag<'K> = private { name:string }

        [<Struct>]
        type NativeReplayKey<'K> = private { node:string; site:string; stable:string; kind:ReplayKindTag<'K> }

        type ReplayObligationDirection =
            | ReplayObligationTermToTy
            | ReplayObligationTyToTermOrParent
            | ReplayObligationSameKind
            | ReplayObligationParentResume
            | ReplayObligationSidecarDrain
            | ReplayObligationUnknown

        type AnyNativeReplayKey =
            | AnyNativeReplayKey of direction:ReplayObligationDirection * node:string * site:string * stable:string

        type LiveReplayEvidenceSnapshot = {
            pending:int64
            active:int64
            cross:int64
            sidecar:bool
            continuation:bool
            queue:int64
            replayDriverTicks:int64
            direction:ReplayObligationDirection
            focus:AnyNativeReplayKey
            }

        type NativeWaitGraphStageOpen = | NativeWaitGraphStageOpen
        type NativeWaitGraphStageDeadlocked = | NativeWaitGraphStageDeadlocked
        type NativeWaitGraphStageResolved = | NativeWaitGraphStageResolved

        type NativeWaitGraphReason =
            | WaitGraphDeferredByLiveEvidence of LiveReplayEvidenceSnapshot
            | WaitGraphDeferredByCrossKind of LiveReplayEvidenceSnapshot
            | WaitGraphDeferredBySidecarDrain of LiveReplayEvidenceSnapshot
            | WaitGraphDeadlockedAfterAllEmpty of LiveReplayEvidenceSnapshot
            | WaitGraphResolvedByMaterialDelta of factCount:int64
            | WaitGraphObserverOnly of reason:CompilerKernelV2.OperationalReasonId

        type NativeWaitGraphLedger<'K,'Stage> = private {
            key:NativeReplayKey<'K>
            reason:NativeWaitGraphReason
            frontier:int64
            canonical:int64
            terminal:int64
            }

        type BridgeGateAuthority<'K> =
            | BridgeGateSleep of NativeWaitGraphLedger<'K,NativeWaitGraphStageOpen> * LiveReplayEvidenceSnapshot
            | BridgeGateRepair of NativeWaitGraphLedger<'K,NativeWaitGraphStageOpen> * LiveReplayEvidenceSnapshot
            | BridgeGateEmitStructuredError of NativeWaitGraphLedger<'K,NativeWaitGraphStageDeadlocked>
            | BridgeGateConsumeMaterialDelta of NativeWaitGraphLedger<'K,NativeWaitGraphStageResolved> * factCount:int64

        type RootCollapseAuthority<'K> =
            | RootCollapseBlockedByBridgeGate of BridgeGateAuthority<'K>
            | RootCollapseBlockedByLiveReplayEvidence of LiveReplayEvidenceSnapshot
            | RootCollapseAllowedAfterDeadlock of NativeWaitGraphLedger<'K,NativeWaitGraphStageDeadlocked>
            | RootCollapseAllowedAfterMaterialDelta of NativeWaitGraphLedger<'K,NativeWaitGraphStageResolved>

        let replayKindTag<'K> name : ReplayKindTag<'K> = { name = name }
        let nativeReplayKey<'K> kindName node site stable : NativeReplayKey<'K> =
            { node = nonEmptyOr "unknown" node; site = nonEmptyOr "unknown" site; stable = nonEmptyOr "unknown" stable; kind = replayKindTag<'K> kindName }

        let replayObligationDirectionText = function
            | ReplayObligationTermToTy -> "term_to_ty"
            | ReplayObligationTyToTermOrParent -> "ty_to_term_or_parent"
            | ReplayObligationSameKind -> "same_kind"
            | ReplayObligationParentResume -> "parent_resume"
            | ReplayObligationSidecarDrain -> "sidecar_drain"
            | ReplayObligationUnknown -> "unknown"

        let anyNativeReplayKeyText = function
            | AnyNativeReplayKey(direction,node,site,stable) -> "AnyReplayKey(kind=" + replayObligationDirectionText direction + "|node=" + node + "|site=" + site + "|stable=" + stable + ")"

        let nativeReplayKeyText (key:NativeReplayKey<'K>) =
            "ReplayKey(kind=" + key.kind.name + "|node=" + key.node + "|site=" + key.site + "|stable=" + key.stable + ")"

        type ReplayObligationFocusId =
            | ReplayObligationFocusTermToTy
            | ReplayObligationFocusParent
            | ReplayObligationFocusSameKind
            | ReplayObligationFocusUnknown

        let private replayObligationFocusFor (focusText:string) =
            let safeFocus = nonEmptyOr "unknown" focusText
            let tokens = diagnosticTextTokensLower safeFocus
            let segments = diagnosticTextSegmentsLower safeFocus
            if Set.contains "term_to_ty" tokens
               || (["term"; "to"; "ty"] |> List.forall (fun segment -> Set.contains segment segments)) then
                ReplayObligationFocusTermToTy
            elif Set.contains "parent" tokens || Set.contains "parent" segments then
                ReplayObligationFocusParent
            elif Set.contains "same" tokens || Set.contains "same" segments then
                ReplayObligationFocusSameKind
            else
                ReplayObligationFocusUnknown

        let replayObligationDirectionFor crossKindCount sidecarPending continuationPending (focusText:string) =
            let focus = replayObligationFocusFor focusText
            if sidecarPending then ReplayObligationSidecarDrain
            elif continuationPending && crossKindCount > 0L then ReplayObligationTyToTermOrParent
            elif crossKindCount > 0L && focus = ReplayObligationFocusTermToTy then ReplayObligationTermToTy
            elif crossKindCount > 0L then ReplayObligationTyToTermOrParent
            else
                match focus with
                | ReplayObligationFocusParent -> ReplayObligationParentResume
                | ReplayObligationFocusSameKind -> ReplayObligationSameKind
                | ReplayObligationFocusTermToTy
                | ReplayObligationFocusUnknown -> ReplayObligationUnknown

        let liveReplayEvidenceSnapshotHasLive (s:LiveReplayEvidenceSnapshot) =
            s.pending > 0L || s.active > 0L || s.cross > 0L || s.sidecar || s.continuation || (s.queue > 0L && s.replayDriverTicks > 0L)

        // MIGRATION: live evidence is not executable evidence.  If only
        // pending/cross-kind/continuation bits remain while active workers and
        // queue are both empty, the metronome must not sleep forever.  It gets a
        // bounded repair lease and then emits a structured fatal blocker so the
        // operator gets a fast, reproducible failure instead of a CPU-zero hang.
        let liveReplayEvidenceSnapshotHasExecutableLane (s:LiveReplayEvidenceSnapshot) =
            s.active > 0L || s.queue > 0L || (s.sidecar && s.pending > 0L)

        let liveReplayEvidenceSnapshotNoExecutableLane (s:LiveReplayEvidenceSnapshot) =
            liveReplayEvidenceSnapshotHasLive s && not (liveReplayEvidenceSnapshotHasExecutableLane s)

        type LiveReplayExecutionLaneId =
            | LiveReplayNoExecutableLane
            | LiveReplayExecutableLaneWithoutProgress
            | LiveReplayEmptyOrNotLiveLane

        type LiveReplayLeaseDecisionId =
            | LiveReplayLeaseEscalateStructuredFatal
            | LiveReplayLeaseRepairBridge
            | LiveReplayLeaseSleepGraceNoExecutableLane
            | LiveReplayLeaseSleepGraceExecutableLane
            | LiveReplayLeaseEmptyOrNotLive

        let private liveReplayExecutionLaneFor (s:LiveReplayEvidenceSnapshot) =
            if liveReplayEvidenceSnapshotNoExecutableLane s then LiveReplayNoExecutableLane
            elif liveReplayEvidenceSnapshotHasLive s then LiveReplayExecutableLaneWithoutProgress
            else LiveReplayEmptyOrNotLiveLane

        let private liveReplayExecutionLaneText = function
            | LiveReplayNoExecutableLane -> "no_executable_lane"
            | LiveReplayExecutableLaneWithoutProgress -> "executable_lane_but_no_progress"
            | LiveReplayEmptyOrNotLiveLane -> "empty_or_not_live"

        let private liveReplayLeaseDecisionFor (stallS:int64) (underutilizedS:int64) (s:LiveReplayEvidenceSnapshot) =
            if liveReplayEvidenceSnapshotHasLive s && (stallS >= 90L || underutilizedS >= 30L) then LiveReplayLeaseEscalateStructuredFatal
            elif liveReplayEvidenceSnapshotHasLive s && (stallS >= 45L || underutilizedS >= 15L) then LiveReplayLeaseRepairBridge
            elif liveReplayEvidenceSnapshotNoExecutableLane s then LiveReplayLeaseSleepGraceNoExecutableLane
            elif liveReplayEvidenceSnapshotHasLive s then LiveReplayLeaseSleepGraceExecutableLane
            else LiveReplayLeaseEmptyOrNotLive

        let private liveReplayLeaseDecisionText = function
            | LiveReplayLeaseEscalateStructuredFatal -> "escalate_structured_fatal"
            | LiveReplayLeaseRepairBridge -> "repair_bridge"
            | LiveReplayLeaseSleepGraceNoExecutableLane -> "sleep_grace_no_executable_lane"
            | LiveReplayLeaseSleepGraceExecutableLane -> "sleep_grace_executable_lane"
            | LiveReplayLeaseEmptyOrNotLive -> "empty_or_not_live"

        let liveReplayEvidenceSnapshotFinishFastLeaseText (stallS:int64) (underutilizedS:int64) (s:LiveReplayEvidenceSnapshot) =
            let lane = liveReplayExecutionLaneFor s
            let decision = liveReplayLeaseDecisionFor stallS underutilizedS s
            "LiveReplayLease(" + liveReplayExecutionLaneText lane
            + "|stall_s=" + string stallS
            + "|underutilized_s=" + string underutilizedS
            + "|pending=" + string s.pending
            + "|active=" + string s.active
            + "|cross=" + string s.cross
            + "|sidecar=" + (if s.sidecar then "draining" else "none")
            + "|continuation=" + (if s.continuation then "pending" else "none")
            + "|queue=" + string s.queue
            + "|decision=" + liveReplayLeaseDecisionText decision + ")"

        let liveReplayEvidenceSnapshotText (s:LiveReplayEvidenceSnapshot) =
            "LiveReplayEvidenceSnapshot(pending=" + string s.pending
            + "|active=" + string s.active
            + "|cross=" + string s.cross
            + "|sidecar=" + (if s.sidecar then "draining" else "none")
            + "|continuation=" + (if s.continuation then "pending" else "none")
            + "|queue=" + string s.queue
            + "|replay_driver_ticks=" + string s.replayDriverTicks
            + "|direction=" + replayObligationDirectionText s.direction
            + "|focus=" + anyNativeReplayKeyText s.focus
            + "|has_live=" + string (liveReplayEvidenceSnapshotHasLive s) + ")"

        type SemanticFixedPointLease =
            | SemanticFixedPointInactive
            | SemanticFixedPointObserving of elapsedS:int64 * repeatCount:int64 * evidence:LiveReplayEvidenceSnapshot
            | SemanticFixedPointDeferredExecutableGraph of elapsedS:int64 * repeatCount:int64 * evidence:LiveReplayEvidenceSnapshot

        let semanticFixedPointLeaseIsReady _ = false

        let semanticFixedPointLeaseIsExecutableGraphDeferred = function
            | SemanticFixedPointDeferredExecutableGraph _ -> true
            | _ -> false

        let semanticFixedPointLeaseText = function
            | SemanticFixedPointInactive -> "SemanticFixedPointLease(Inactive)"
            | SemanticFixedPointObserving(elapsedS, repeatCount, evidence) ->
                "SemanticFixedPointLease(Observing|elapsed_s=" + string elapsedS
                + "|repeat=" + string repeatCount
                + "|authority=diagnostic_only_conserved_credit_required"
                + "|" + liveReplayEvidenceSnapshotText evidence + ")"
            | SemanticFixedPointDeferredExecutableGraph(elapsedS, repeatCount, evidence) ->
                "SemanticFixedPointLease(DeferredExecutableGraph|elapsed_s=" + string elapsedS
                + "|repeat=" + string repeatCount
                + "|authority=diagnostic_only_conserved_credit_required"
                + "|" + liveReplayEvidenceSnapshotText evidence + ")"

        type SemanticProgressDeltaClass =
            | SemanticOrTerminalDelta
            | ObserverOnlyRootDelta
            | NoTerminalAuthorityDelta

        let semanticProgressDeltaClassFor semanticReceiptDelta rootCompleteDelta terminalSignalDelta =
            if semanticReceiptDelta > 0 || terminalSignalDelta > 0 then SemanticOrTerminalDelta
            elif rootCompleteDelta > 0 then ObserverOnlyRootDelta
            else NoTerminalAuthorityDelta

        let semanticProgressDeltaClassText = function
            | SemanticOrTerminalDelta -> "SemanticProgressDeltaClass(SemanticOrTerminalDelta)"
            | ObserverOnlyRootDelta -> "SemanticProgressDeltaClass(ObserverOnlyRootDelta|does_not_reset_fixed_point_lease)"
            | NoTerminalAuthorityDelta -> "SemanticProgressDeltaClass(NoTerminalAuthorityDelta)"

        let activeWorkersTraceText (evidence:LiveReplayEvidenceSnapshot) =
            "ActiveWorkersTrace(active=" + string evidence.active
            + "|pending=" + string evidence.pending
            + "|queue=" + string evidence.queue
            + "|cross=" + string evidence.cross
            + "|sidecar=" + (if evidence.sidecar then "draining" else "none")
            + "|continuation=" + (if evidence.continuation then "pending" else "none")
            + "|focus=" + anyNativeReplayKeyText evidence.focus + ")"

        let ivarDependenciesText (evidence:LiveReplayEvidenceSnapshot) (waitGraphText:string) =
            "IVarDependencies(direction=" + replayObligationDirectionText evidence.direction
            + "|focus=" + anyNativeReplayKeyText evidence.focus
            + "|wait_graph=" + truncateForDiag 220 (nonEmptyOr "unknown" waitGraphText) + ")"

        let liveReplayEvidenceSnapshotFor
            (pendingDepth:int64)
            (activeDepth:int64)
            (crossKindCount:int64)
            (sidecarPending:bool)
            (continuationPending:bool)
            (queueDepth:int64)
            (replayDriverTicks:int64)
            (focusText:string)
            : LiveReplayEvidenceSnapshot =
            let direction = replayObligationDirectionFor crossKindCount sidecarPending continuationPending focusText
            let focus = AnyNativeReplayKey(direction, "observer", "live_replay_evidence_gate", nonEmptyOr "unknown" focusText)
            { pending = pendingDepth; active = activeDepth; cross = crossKindCount; sidecar = sidecarPending; continuation = continuationPending; queue = queueDepth; replayDriverTicks = replayDriverTicks; direction = direction; focus = focus }

        let nativeWaitGraphReasonText = function
            | WaitGraphDeferredByLiveEvidence evidence -> "DeferredByLiveEvidence|" + liveReplayEvidenceSnapshotText evidence
            | WaitGraphDeferredByCrossKind evidence -> "DeferredByCrossKind|" + liveReplayEvidenceSnapshotText evidence
            | WaitGraphDeferredBySidecarDrain evidence -> "DeferredBySidecarDrain|" + liveReplayEvidenceSnapshotText evidence
            | WaitGraphDeadlockedAfterAllEmpty evidence -> "DeadlockedAfterAllEmpty|" + liveReplayEvidenceSnapshotText evidence
            | WaitGraphResolvedByMaterialDelta facts -> "ResolvedByMaterialDelta|facts=" + string facts
            | WaitGraphObserverOnly reason -> "ObserverOnly|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason

        let nativeWaitGraphLedgerText (ledger:NativeWaitGraphLedger<'K,'Stage>) =
            "WaitGraphLedger(key=" + nativeReplayKeyText ledger.key
            + "|frontier=" + string ledger.frontier
            + "|canonical=" + string ledger.canonical
            + "|terminal=" + string ledger.terminal
            + "|reason=" + nativeWaitGraphReasonText ledger.reason + ")"

        let bridgeGateAuthorityText = function
            | BridgeGateSleep(ledger, evidence) -> "BridgeGate(Sleep|ledger=" + nativeWaitGraphLedgerText ledger + "|evidence=" + liveReplayEvidenceSnapshotText evidence + ")"
            | BridgeGateRepair(ledger, evidence) -> "BridgeGate(Repair|ledger=" + nativeWaitGraphLedgerText ledger + "|evidence=" + liveReplayEvidenceSnapshotText evidence + ")"
            | BridgeGateEmitStructuredError ledger -> "BridgeGate(EmitStructuredError|ledger=" + nativeWaitGraphLedgerText ledger + ")"
            | BridgeGateConsumeMaterialDelta(ledger, facts) -> "BridgeGate(ConsumeMaterialDelta|facts=" + string facts + "|ledger=" + nativeWaitGraphLedgerText ledger + ")"

        let rootCollapseAuthorityText = function
            | RootCollapseBlockedByBridgeGate gate -> "RootCollapseAuthority(BlockedByBridgeGate|" + bridgeGateAuthorityText gate + ")"
            | RootCollapseBlockedByLiveReplayEvidence evidence -> "RootCollapseAuthority(BlockedByLiveReplayEvidence|" + liveReplayEvidenceSnapshotText evidence + ")"
            | RootCollapseAllowedAfterDeadlock ledger -> "RootCollapseAuthority(AllowedAfterDeadlock|" + nativeWaitGraphLedgerText ledger + ")"
            | RootCollapseAllowedAfterMaterialDelta ledger -> "RootCollapseAuthority(AllowedAfterMaterialDelta|" + nativeWaitGraphLedgerText ledger + ")"

        // MIGRATION MIGRATION : the metronome now emits scheduler
        // authority.  Only EscalateStructuredFatal preserves abort authority;
        // Sleep/Repair/Yield/Await/Recheck routes return control to Hopac.
        [<NoEquality; NoComparison>]
        type NativeMetronomePushDeferralKindId =
            | PushDeferralReadyButNoop
            | PushDeferralActorOwnsPendingOutcome
            | PushDeferralRuntimeEventObserved
            | PushDeferralPostRootDispatchPending

        [<NoEquality; NoComparison>]
        type SchedulerStructuredFatalReasonId =
            | SchedulerFatalLiveReplayEvidenceProgressLeaseExpired of noWorkStallS:int64 * underutilizedReplayS:int64 * evidence:LiveReplayEvidenceSnapshot
            | SchedulerFatalClosedPureTopologyMissingMinimalReceiptFastFinish of noWorkStallS:int64 * underutilizedReplayS:int64 * evidence:LiveReplayEvidenceSnapshot
            | SchedulerFatalAllTypedSchedulerDeferralsEmpty

        let private schedulerStructuredFatalReasonText = function
            | SchedulerFatalLiveReplayEvidenceProgressLeaseExpired(noWorkStallS, underutilizedReplayS, evidence) ->
                "live_replay_evidence_progress_lease_expired|" + liveReplayEvidenceSnapshotFinishFastLeaseText noWorkStallS underutilizedReplayS evidence
            | SchedulerFatalClosedPureTopologyMissingMinimalReceiptFastFinish(noWorkStallS, underutilizedReplayS, evidence) ->
                "closed_pure_topology_missing_minimal_receipt_fast_finish|" + liveReplayEvidenceSnapshotFinishFastLeaseText noWorkStallS underutilizedReplayS evidence
            | SchedulerFatalAllTypedSchedulerDeferralsEmpty ->
                "all_typed_scheduler_deferrals_empty"

        [<NoEquality; NoComparison>]
        type NativeMetronomeSchedulerAuthority =
            | SchedulerNoop
            | SchedulerSleepLiveReplay of evidence:LiveReplayEvidenceSnapshot * rootAuthority:string
            | SchedulerRepairMinimalToRichBridge of bridgeGate:string * evidenceReceipt:string
            | SchedulerYieldDeferredTopology of waitGraph:string * evidence:LiveReplayEvidenceSnapshot
            | SchedulerAwaitMinimalEvidence of bridgeGate:string * waitGraph:string
            | SchedulerCooperativeRecheck of reason:CompilerKernelV2.OperationalReasonId * evidence:LiveReplayEvidenceSnapshot
            | SchedulerDeferToPushEvent of kind:NativeMetronomePushDeferralKindId * authority:string
            | SchedulerEscalateStructuredFatal of reason:SchedulerStructuredFatalReasonId

        let nativeMetronomePushDeferralKindText = function
            | PushDeferralReadyButNoop -> "ready_but_noop"
            | PushDeferralActorOwnsPendingOutcome -> "actor_owns_pending_outcome"
            | PushDeferralRuntimeEventObserved -> "runtime_event_observed"
            | PushDeferralPostRootDispatchPending -> "post_root_dispatch_pending"

        let nativeMetronomeSchedulerAuthorityBlocksAbort = function
            | SchedulerEscalateStructuredFatal _ -> false
            | SchedulerNoop -> false
            | SchedulerDeferToPushEvent(_, _) -> true
            | _ -> true

        let nativeMetronomeSchedulerAuthorityIsStaleVacantPush = function
            | SchedulerDeferToPushEvent(PushDeferralReadyButNoop, _) -> true
            | _ -> false

        let nativeMetronomeSchedulerAuthorityIsEscalate = function
            | SchedulerEscalateStructuredFatal _ -> true
            | _ -> false

        type SchedulerFatalObservedKind =
            | SchedulerFatalObservedKind

        type SchedulerFatalAuthorityGate<'Kind> =
            | SchedulerFatalAuthorityNotRequested
            | SchedulerFatalAuthorityDeferredExecutableGraph of reason:SchedulerStructuredFatalReasonId * evidence:LiveReplayEvidenceSnapshot * deltaClass:SemanticProgressDeltaClass
            | SchedulerFatalAuthorityDeferredRecentProgress of reason:SchedulerStructuredFatalReasonId * evidence:LiveReplayEvidenceSnapshot * deltaClass:SemanticProgressDeltaClass
            | SchedulerFatalAuthorityDeferredOpenWaitGraph of reason:SchedulerStructuredFatalReasonId * waitGraph:string
            | SchedulerFatalAuthorityAllowedExhaustedGraph of reason:SchedulerStructuredFatalReasonId

        let schedulerFatalAuthorityGateFor authority evidence deltaClass waitGraphCanCollapseRoot waitGraphText =
            match authority with
            | SchedulerEscalateStructuredFatal reason when liveReplayEvidenceSnapshotHasLive evidence ->
                SchedulerFatalAuthorityDeferredExecutableGraph(reason, evidence, deltaClass)
            | SchedulerEscalateStructuredFatal reason when deltaClass <> NoTerminalAuthorityDelta ->
                SchedulerFatalAuthorityDeferredRecentProgress(reason, evidence, deltaClass)
            | SchedulerEscalateStructuredFatal reason when not waitGraphCanCollapseRoot ->
                SchedulerFatalAuthorityDeferredOpenWaitGraph(reason, nonEmptyOr "unknown" waitGraphText)
            | SchedulerEscalateStructuredFatal reason ->
                SchedulerFatalAuthorityAllowedExhaustedGraph reason
            | _ -> SchedulerFatalAuthorityNotRequested

        let schedulerFatalAuthorityGateAllowsExit = function
            | SchedulerFatalAuthorityAllowedExhaustedGraph _ -> true
            | _ -> false

        let schedulerFatalAuthorityGateText = function
            | SchedulerFatalAuthorityNotRequested -> "SchedulerFatalAuthorityGate(NotRequested)"
            | SchedulerFatalAuthorityDeferredExecutableGraph(reason, evidence, deltaClass) ->
                "SchedulerFatalAuthorityGate(DeferredExecutableGraph|reason=" + schedulerStructuredFatalReasonText reason
                + "|delta=" + semanticProgressDeltaClassText deltaClass
                + "|" + liveReplayEvidenceSnapshotText evidence + ")"
            | SchedulerFatalAuthorityDeferredRecentProgress(reason, evidence, deltaClass) ->
                "SchedulerFatalAuthorityGate(DeferredRecentProgress|reason=" + schedulerStructuredFatalReasonText reason
                + "|delta=" + semanticProgressDeltaClassText deltaClass
                + "|" + liveReplayEvidenceSnapshotText evidence + ")"
            | SchedulerFatalAuthorityDeferredOpenWaitGraph(reason, waitGraph) ->
                "SchedulerFatalAuthorityGate(DeferredOpenWaitGraph|reason=" + schedulerStructuredFatalReasonText reason
                + "|wait_graph=" + waitGraph + ")"
            | SchedulerFatalAuthorityAllowedExhaustedGraph reason ->
                "SchedulerFatalAuthorityGate(AllowedExhaustedGraph|reason=" + schedulerStructuredFatalReasonText reason + ")"

        let schedulerAuthorityAfterFatalGate gate authority minimalReceiptText =
            match gate with
            | SchedulerFatalAuthorityDeferredExecutableGraph(reason, evidence, deltaClass) ->
                let reasonText = schedulerStructuredFatalReasonText reason
                SchedulerRepairMinimalToRichBridge(
                    "scheduler_fatal_deferred_executable_graph|reason=" + reasonText
                    + "|delta=" + semanticProgressDeltaClassText deltaClass
                    + "|" + liveReplayEvidenceSnapshotText evidence,
                    nonEmptyOr "no_minimal_receipt_available" minimalReceiptText)
            | SchedulerFatalAuthorityDeferredRecentProgress(reason, evidence, deltaClass) ->
                let reasonText = schedulerStructuredFatalReasonText reason
                SchedulerCooperativeRecheck(
                    CompilerKernelV2.OperationalReasonIdOps.create (
                        "scheduler_fatal_deferred_recent_progress|reason=" + reasonText
                        + "|delta=" + semanticProgressDeltaClassText deltaClass),
                    evidence)
            | SchedulerFatalAuthorityDeferredOpenWaitGraph(reason, waitGraph) ->
                SchedulerAwaitMinimalEvidence(
                    "scheduler_fatal_deferred_open_wait_graph|reason=" + schedulerStructuredFatalReasonText reason,
                    waitGraph)
            | SchedulerFatalAuthorityAllowedExhaustedGraph _
            | SchedulerFatalAuthorityNotRequested -> authority

        type NoWorkHardAbortObservedKind =
            | NoWorkHardAbortObservedKind

        type HardAbortRecentProgressClass =
            | HardAbortRecentSemanticOrTerminalDelta
            | HardAbortRecentRootDelta
            | HardAbortRecentSampledOrReplayDelta
            | HardAbortPostRootObserverChurn
            | HardAbortNoRecentProgress

        let hardAbortRecentProgressClassFor
            (rootResolved:bool)
            (sampledWorkDelta:int64)
            (replayProgressDelta:int64)
            (semanticAuthorityDelta:int64)
            (rootCompleteDelta:int64)
            (terminalSignalDelta:int64)
            : HardAbortRecentProgressClass =
            if semanticAuthorityDelta > 0L || terminalSignalDelta > 0L then HardAbortRecentSemanticOrTerminalDelta
            elif rootCompleteDelta > 0L then HardAbortRecentRootDelta
            elif rootResolved && (sampledWorkDelta > 0L || replayProgressDelta > 0L) then HardAbortPostRootObserverChurn
            elif sampledWorkDelta > 0L || replayProgressDelta > 0L then HardAbortRecentSampledOrReplayDelta
            else HardAbortNoRecentProgress

        let hardAbortRecentProgressClassText = function
            | HardAbortRecentSemanticOrTerminalDelta -> "HardAbortRecentProgress(SemanticOrTerminalDelta)"
            | HardAbortRecentRootDelta -> "HardAbortRecentProgress(RootDelta)"
            | HardAbortRecentSampledOrReplayDelta -> "HardAbortRecentProgress(SampledOrReplayDelta)"
            | HardAbortPostRootObserverChurn -> "HardAbortRecentProgress(PostRootObserverChurnIgnored)"
            | HardAbortNoRecentProgress -> "HardAbortRecentProgress(None)"

        type NoWorkBuildOutcomeAuthority =
            | NoWorkBuildOutcomeAuthorityUnknown
            | NoWorkBuildOutcomeAuthorityNoProvenBuildOk of proof:CompilerIdentityKernel.ContentDigest
            | NoWorkBuildOutcomeAuthorityProvenBuildOk of proof:CompilerIdentityKernel.ContentDigest

        let mutable private noWorkBuildOutcomeAuthorityProvider : unit -> NoWorkBuildOutcomeAuthority =
            fun () -> NoWorkBuildOutcomeAuthorityUnknown

        let installNoWorkBuildOutcomeAuthorityProvider provider =
            noWorkBuildOutcomeAuthorityProvider <- provider

        let noWorkBuildOutcomeAuthoritySnapshot () =
            noWorkBuildOutcomeAuthorityProvider ()

        [<NoEquality; NoComparison>]
        type NoWorkHardAbortGate<'Kind> =
            | NoWorkHardAbortNotRequested
            | NoWorkHardAbortBlockedSemanticWorkLedger of openCount:int64
            | NoWorkHardAbortBlockedOutcomeAuthorityUnknown
            | NoWorkHardAbortBlockedProvenBuildOk of proof:CompilerIdentityKernel.ContentDigest
            | NoWorkHardAbortBlockedExecutableGraph of evidence:LiveReplayEvidenceSnapshot
            | NoWorkHardAbortBlockedRecentProgress of progressClass:HardAbortRecentProgressClass
            | NoWorkHardAbortBlockedMissingWaitGraph
            | NoWorkHardAbortBlockedOpenWaitGraph of waitGraph:NativeWaitForGraphVerdictId
            | NoWorkHardAbortAllowedExplicitRootFailure of reason:CompilerKernelV2.OperationalReasonId
            | NoWorkHardAbortAllowedStaleVacantPush of reason:CompilerKernelV2.OperationalReasonId
            | NoWorkHardAbortAllowedExhaustedGraph of reason:CompilerKernelV2.OperationalReasonId

        let noWorkHardAbortGateFor candidate semanticOpenCount outcomeAuthority explicitRootFailure staleVacantPush evidence progressClass waitGraph reason =
            if not candidate then NoWorkHardAbortNotRequested
            elif semanticOpenCount > 0L then NoWorkHardAbortBlockedSemanticWorkLedger semanticOpenCount
            elif explicitRootFailure then NoWorkHardAbortAllowedExplicitRootFailure (CompilerKernelV2.OperationalReasonIdOps.create reason)
            else
                match outcomeAuthority with
                | NoWorkBuildOutcomeAuthorityUnknown -> NoWorkHardAbortBlockedOutcomeAuthorityUnknown
                | NoWorkBuildOutcomeAuthorityProvenBuildOk proof -> NoWorkHardAbortBlockedProvenBuildOk proof
                | NoWorkBuildOutcomeAuthorityNoProvenBuildOk _ ->
                    if liveReplayEvidenceSnapshotHasLive evidence then NoWorkHardAbortBlockedExecutableGraph evidence
                    elif progressClass <> HardAbortNoRecentProgress && progressClass <> HardAbortPostRootObserverChurn then NoWorkHardAbortBlockedRecentProgress progressClass
                    elif staleVacantPush then NoWorkHardAbortAllowedStaleVacantPush (CompilerKernelV2.OperationalReasonIdOps.create reason)
                    else
                        match waitGraph with
                        | None -> NoWorkHardAbortBlockedMissingWaitGraph
                        | Some verdict when not (nativeWaitForGraphCanCollapseRoot verdict) -> NoWorkHardAbortBlockedOpenWaitGraph verdict
                        | Some _ -> NoWorkHardAbortAllowedExhaustedGraph (CompilerKernelV2.OperationalReasonIdOps.create reason)

        let noWorkHardAbortGateAllowsExit = function
            | NoWorkHardAbortAllowedExplicitRootFailure _
            | NoWorkHardAbortAllowedStaleVacantPush _
            | NoWorkHardAbortAllowedExhaustedGraph _ -> true
            | _ -> false

        let noWorkHardAbortGateText = function
            | NoWorkHardAbortNotRequested -> "NoWorkHardAbortGate(NotRequested)"
            | NoWorkHardAbortBlockedSemanticWorkLedger openCount ->
                "NoWorkHardAbortGate(BlockedSemanticWorkLedger|open=" + string openCount + ")"
            | NoWorkHardAbortBlockedOutcomeAuthorityUnknown -> "NoWorkHardAbortGate(BlockedOutcomeAuthorityUnknown)"
            | NoWorkHardAbortBlockedProvenBuildOk proof -> "NoWorkHardAbortGate(BlockedProvenBuildOk|proof=" + CompilerIdentityKernel.ContentDigest.text proof + ")"
            | NoWorkHardAbortBlockedExecutableGraph evidence -> "NoWorkHardAbortGate(BlockedExecutableGraph|" + liveReplayEvidenceSnapshotText evidence + ")"
            | NoWorkHardAbortBlockedRecentProgress progressClass -> "NoWorkHardAbortGate(BlockedRecentProgress|progress=" + hardAbortRecentProgressClassText progressClass + ")"
            | NoWorkHardAbortBlockedMissingWaitGraph -> "NoWorkHardAbortGate(BlockedMissingWaitGraph)"
            | NoWorkHardAbortBlockedOpenWaitGraph waitGraph -> "NoWorkHardAbortGate(BlockedOpenWaitGraph|wait_graph=" + nativeWaitForGraphVerdictText waitGraph + ")"
            | NoWorkHardAbortAllowedExplicitRootFailure reason -> "NoWorkHardAbortGate(AllowedExplicitRootFailure|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NoWorkHardAbortAllowedStaleVacantPush reason -> "NoWorkHardAbortGate(AllowedStaleVacantPush|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NoWorkHardAbortAllowedExhaustedGraph reason -> "NoWorkHardAbortGate(AllowedExhaustedGraph|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let nativeMetronomeSchedulerAuthorityText = function
            | SchedulerNoop -> "NativeHopacSchedulerAuthority(Noop)"
            | SchedulerSleepLiveReplay(evidence, rootAuthority) ->
                "NativeHopacSchedulerAuthority(Sleep|action=Hopac.Job.sleep|reason=live_replay_evidence|" + liveReplayEvidenceSnapshotText evidence + "|root=" + rootAuthority + ")"
            | SchedulerRepairMinimalToRichBridge(bridgeGate, evidenceReceipt) ->
                "NativeHopacSchedulerAuthority(Repair|target=minimal_to_rich_bridge|bridge_gate=" + bridgeGate + "|evidence=" + evidenceReceipt + ")"
            | SchedulerYieldDeferredTopology(waitGraph, evidence) ->
                "NativeHopacSchedulerAuthority(Yield|target=wait_graph|wait_graph=" + waitGraph + "|" + liveReplayEvidenceSnapshotText evidence + ")"
            | SchedulerAwaitMinimalEvidence(bridgeGate, waitGraph) ->
                "NativeHopacSchedulerAuthority(AwaitMinimalEvidence|action=Hopac.Alt.await|bridge_gate=" + bridgeGate + "|wait_graph=" + waitGraph + ")"
            | SchedulerCooperativeRecheck(reason, evidence) ->
                "NativeHopacSchedulerAuthority(CooperativeRecheck|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|" + liveReplayEvidenceSnapshotText evidence + ")"
            | SchedulerDeferToPushEvent(kind, authority) ->
                "NativeHopacSchedulerAuthority(DeferToPushEvent|kind=" + nativeMetronomePushDeferralKindText kind + "|authority=" + authority + ")"
            | SchedulerEscalateStructuredFatal reason ->
                "NativeHopacSchedulerAuthority(EscalateStructuredFatal|reason=" + schedulerStructuredFatalReasonText reason + ")"

        let nativeMetronomeSchedulerAuthorityExitGateText authority =
            if nativeMetronomeSchedulerAuthorityBlocksAbort authority then
                "NativeHopacSchedulerExitGate(Blocked|" + nativeMetronomeSchedulerAuthorityText authority + ")"
            else
                "NativeHopacSchedulerExitGate(Allowed|" + nativeMetronomeSchedulerAuthorityText authority + ")"

        type NativeMetronomeLegacyIngressSignalId =
            | NativeMetronomeIngressPushRuntimeEvent
            | NativeMetronomeIngressPostRootTerminalOutcome
            | NativeMetronomeIngressClosedPureTopology
            | NativeMetronomeIngressTerminalPayloadBridge

        let private nativeMetronomeLegacyIngressSignalsFor (rootAuthorityText:string) (minimalReceiptText:string) =
            let rootTokens = diagnosticTextTokensLower rootAuthorityText
            let rootSegments = diagnosticTextSegmentsLower rootAuthorityText
            let receiptTokens = diagnosticTextTokensLower minimalReceiptText
            let receiptSegments = diagnosticTextSegmentsLower minimalReceiptText
            let hasToken candidates tokens = diagnosticTextHasAny candidates tokens
            let hasAll required segments = required |> List.forall (fun segment -> Set.contains segment segments)
            [ if hasToken ["pushdrivenschedulerauthority"; "hopacpushruntimeevent"; "poisontailtransitionframe"; "poison_tail_typed"] receiptTokens
                 || hasAll ["push"; "runtime"; "event"] receiptSegments then
                  yield NativeMetronomeIngressPushRuntimeEvent
              if hasToken ["rootpromiseresolved"; "rootcompletealreadyresolved"; "awaiting_terminal_outcome"; "native_job_bind_root_capability"] rootTokens
                 || hasToken ["rootpromiseresolved"; "terminal-flow-boundary"; "awaiting_terminal_outcome"; "native_job_bind_root_capability"] receiptTokens
                 || hasAll ["root"; "promise"; "resolved"] rootSegments then
                  yield NativeMetronomeIngressPostRootTerminalOutcome
              if hasToken ["nofurtherdeclared"; "pure_topology"; "sidecar_drain"] receiptTokens
                 || hasAll ["pure"; "topology"] receiptSegments
                 || hasAll ["sidecar"; "drain"] receiptSegments then
                  yield NativeMetronomeIngressClosedPureTopology
              if hasToken ["terminalpayloadbridgereceipt"] receiptTokens
                 || hasAll ["terminal"; "payload"; "bridge"; "receipt"] receiptSegments then
                  yield NativeMetronomeIngressTerminalPayloadBridge ]
            |> Set.ofList

        let private noWorkGateDecisionIsHoldoff = function
            | NoWorkGateDecisionHoldoffEscalateProbe
            | NoWorkGateDecisionHoldoffLiveReplayEvidence
            | NoWorkGateDecisionHoldoffFreshSemanticLiveReplay
            | NoWorkGateDecisionHoldoffMidGraphLiveReplayGateBusy
            | NoWorkGateDecisionHoldoffLowAuthorityReplayDripDrain
            | NoWorkGateDecisionHoldoffCoalescedRichReplayDrip
            | NoWorkGateDecisionHoldoffPoisonDrain
            | NoWorkGateDecisionHoldoffHardSemanticQuarantineLiveTail
            | NoWorkGateDecisionHoldoffNativeParentJobBindExecution
            | NoWorkGateDecisionHoldoffFinalQueueSparseReplayTickQuorum
            | NoWorkGateDecisionHoldoffFinalQueueActiveDriverRootProbe
            | NoWorkGateDecisionHoldoffFinalQueueDrain
            | NoWorkGateDecisionHoldoffTySidecarPrefetchDrain
            | NoWorkGateDecisionHoldoffIdleCrossKindRichStaleRetry
            | NoWorkGateDecisionHoldoffLateRaceFreshRootWitnessDrain -> true
            | _ -> false

        let private noWorkGateDecisionIndicatesTerminalFailure = function
            | NoWorkGateDecisionRootPromiseFailedSemanticExit
            | NoWorkGateDecisionSuppressMetronomeNativeConsumersAttached -> true
            | _ -> false

        let private progressPlateauDecisionRequiresRecheck = function
            | PlateauDecisionHoldLiveReplayEvidence
            | PlateauDecisionExtendLiveReplayEvidence -> true
            | _ -> false

        type NativeMetronomeBridgeStateId =
            | NativeMetronomeBridgeAllowed of evidence:string
            | NativeMetronomeBridgeAwaitingMinimalEvidence of evidence:string
            | NativeMetronomeBridgeDeferred of evidence:string

        let private nativeMetronomeBridgeStateAllows = function
            | NativeMetronomeBridgeAllowed _ -> true
            | _ -> false

        let private nativeMetronomeBridgeStateAwaitsMinimalEvidence = function
            | NativeMetronomeBridgeAwaitingMinimalEvidence _ -> true
            | _ -> false

        let private nativeMetronomeBridgeStateText = function
            | NativeMetronomeBridgeAllowed evidence -> evidence
            | NativeMetronomeBridgeAwaitingMinimalEvidence evidence -> evidence
            | NativeMetronomeBridgeDeferred evidence -> evidence

        let private rootCollapseAuthorityBlockedByBridge = function
            | RootCollapseBlockedByBridgeGate _ -> true
            | _ -> false

        let nativeMetronomeSchedulerAuthorityFor
            (underutilizedAbortRecommended: bool)
            (noWorkStallS:int64)
            (underutilizedReplayS:int64)
            (evidence:LiveReplayEvidenceSnapshot)
            (rootAuthority:RootCollapseAuthority<ReplayCrossKind>)
            (bridgeState:NativeMetronomeBridgeStateId)
            (minimalReceiptText:string)
            (waitGraph:NativeWaitForGraphVerdictId)
            (gateDecision:NoWorkGateDecisionId)
            (plateauDecision:ProgressPlateauDecisionId) =
            let liveLeaseText = liveReplayEvidenceSnapshotFinishFastLeaseText noWorkStallS underutilizedReplayS evidence
            let rootAuthorityText = rootCollapseAuthorityText rootAuthority
            let bridgeAllows = nativeMetronomeBridgeStateAllows bridgeState
            let bridgeText = nativeMetronomeBridgeStateText bridgeState
            let waitGraphText = nativeWaitForGraphVerdictText waitGraph
            let waitGraphCanCollapseRoot = nativeWaitForGraphCanCollapseRoot waitGraph
            let topologyDeferredByCanonical = nativeWaitForGraphTopologyDeferredByCanonical waitGraph
            let ingressSignals = nativeMetronomeLegacyIngressSignalsFor rootAuthorityText minimalReceiptText
            let canonicalRoot = canonicalRootAuthoritySnapshot()
            let pushActor = terminalSchedulerPushActorSnapshot()
            let canonicalRootResolved =
                match canonicalRoot.phase with
                | CanonicalRootResolved _ -> true
                | _ -> false
            let pushActorOwnsPendingTerminalOutcome =
                match pushActor.phase with
                | PushActorArmed
                | PushActorOutcomeFilled
                | PushActorWriterBound
                | PushActorArtifactsCommitted
                | PushActorExitWitnessQueued -> true
                | _ -> false
            let pushActorReadyButNoop = canonicalRootResolved && pushActor.phase = PushActorNoop
            let pushRuntimeEventIngressQuarantine =
                "StringIngressTranslationReceipt(ToleratedIngressOnly|field=minimal_receipt_text|pattern=push-runtime string marker|typed_projection=HopacPushRuntimeEvent|PushDrivenSchedulerAuthority)"
            let pushRuntimeEventObserved =
                Set.contains NativeMetronomeIngressPushRuntimeEvent ingressSignals
            let postRootTerminalOutcomeDispatchPending =
                canonicalRootResolved
                || pushActorOwnsPendingTerminalOutcome
                || Set.contains NativeMetronomeIngressPostRootTerminalOutcome ingressSignals
            let proactiveClosedPureTopologyRepair =
                liveReplayEvidenceSnapshotHasLive evidence
                && (Set.contains NativeMetronomeIngressClosedPureTopology ingressSignals
                    || rootCollapseAuthorityBlockedByBridge rootAuthority)
                && (noWorkGateDecisionIndicatesTerminalFailure gateDecision
                    || Set.contains NativeMetronomeIngressTerminalPayloadBridge ingressSignals)
            if pushActorReadyButNoop then
                SchedulerDeferToPushEvent(PushDeferralReadyButNoop, "typed_push_actor_blocker|owner_of=terminal_outcome_ivar|root=" + canonicalRoot.receiptId + "|ready=true|action=none|" + terminalSchedulerPushActorText() + "|" + liveLeaseText)
            elif pushActorOwnsPendingTerminalOutcome then
                SchedulerDeferToPushEvent(PushDeferralActorOwnsPendingOutcome, "typed_push_actor_owns_terminal_outcome|" + terminalSchedulerPushActorText() + "|" + liveLeaseText)
            elif pushRuntimeEventObserved then
                SchedulerDeferToPushEvent(PushDeferralRuntimeEventObserved, "push_runtime_event_owns_scheduler_authority|metronome_observer_only|" + pushRuntimeEventIngressQuarantine + "|" + liveLeaseText)
            elif liveReplayEvidenceSnapshotHasLive evidence && (noWorkStallS >= 90L || underutilizedReplayS >= 30L) then
                SchedulerEscalateStructuredFatal(SchedulerFatalLiveReplayEvidenceProgressLeaseExpired(noWorkStallS, underutilizedReplayS, evidence))
            elif proactiveClosedPureTopologyRepair && System.String.IsNullOrWhiteSpace(minimalReceiptText) then
                SchedulerEscalateStructuredFatal(SchedulerFatalClosedPureTopologyMissingMinimalReceiptFastFinish(noWorkStallS, underutilizedReplayS, evidence))
            elif postRootTerminalOutcomeDispatchPending then
                SchedulerDeferToPushEvent(PushDeferralPostRootDispatchPending, "post_root_terminal_outcome_dispatch_pending|hud_deadman_heartbeat_required|metronome_observer_only_must_not_noop|" + liveLeaseText)
            elif liveReplayEvidenceSnapshotHasLive evidence && (noWorkStallS >= 45L || underutilizedReplayS >= 15L) then
                SchedulerRepairMinimalToRichBridge("live_replay_progress_lease_repair|" + liveLeaseText, nonEmptyOr "no_minimal_receipt_available" minimalReceiptText)
            elif (not underutilizedAbortRecommended) && proactiveClosedPureTopologyRepair then
                SchedulerRepairMinimalToRichBridge("proactive_root_complete_repair_after_closed_pure_topology|" + liveLeaseText, nonEmptyOr "no_minimal_receipt_available" minimalReceiptText)
            elif not underutilizedAbortRecommended then SchedulerNoop
            elif liveReplayEvidenceSnapshotHasLive evidence then SchedulerSleepLiveReplay(evidence, rootAuthorityText + "|" + liveLeaseText)
            elif not bridgeAllows && nativeMetronomeBridgeStateAwaitsMinimalEvidence bridgeState then SchedulerAwaitMinimalEvidence(bridgeText, waitGraphText)
            elif not bridgeAllows then SchedulerRepairMinimalToRichBridge(bridgeText, nonEmptyOr "no_minimal_receipt_available" minimalReceiptText)
            elif topologyDeferredByCanonical || not waitGraphCanCollapseRoot then SchedulerYieldDeferredTopology(waitGraphText, evidence)
            elif progressPlateauDecisionRequiresRecheck plateauDecision || noWorkGateDecisionIsHoldoff gateDecision then SchedulerCooperativeRecheck(CompilerKernelV2.OperationalReasonIdOps.create "bounded_holdoff_or_plateau_receipt", evidence)
            else SchedulerEscalateStructuredFatal SchedulerFatalAllTypedSchedulerDeferralsEmpty


        // MIGRATION MIGRATION : terminal payloads become kind-indexed
        // bridge receipts.  The old NativeTerminalPayload<'Lane> still exists as
        // a compatibility ingress for the minimal/rich handoff, but root/bridge
        // authority now receives a typed payload class plus the same live replay
        // evidence snapshot used by the phantom WaitGraph ledger.  String matching
        // is quarantined at this boundary; decisions downstream consume these DUs.
        type TerminalPayloadIngressClass =
            | TerminalPayloadIngressSemanticStaleRetarget
            | TerminalPayloadIngressIdleCrossKindSidecar
            | TerminalPayloadIngressPureTopologyZeroFact
            | TerminalPayloadIngressPlateauPoison
            | TerminalPayloadIngressCyclePoison
            | TerminalPayloadIngressNoFurther


        type TerminalPayloadBridgeAction =
            | TerminalPayloadBridgeSleep of reason:CompilerKernelV2.OperationalReasonId
            | TerminalPayloadBridgeRepair of reason:CompilerKernelV2.OperationalReasonId
            | TerminalPayloadBridgeEmitStructuredError of reason:CompilerKernelV2.OperationalReasonId
            | TerminalPayloadBridgeConsumeMaterialDelta of facts:int64

        type KindIndexedNativeTerminalPayload<'K> =
            | KindedTerminalSemanticStaleRetarget of key:NativeReplayKey<'K> * semanticFailureId:string * payload:string * diagnosis:string * starved:int
            | KindedTerminalIdleCrossKindSidecar of key:NativeReplayKey<'K> * payload:string * sidecarState:string * continuationState:string * starved:int
            | KindedTerminalPureTopologyZeroFact of key:NativeReplayKey<'K> * witness:string * payload:string * diagnosis:string
            | KindedTerminalPlateauPoison of key:NativeReplayKey<'K> * payload:string * diagnosis:string * starved:int
            | KindedTerminalCyclePoison of key:NativeReplayKey<'K> * payload:string * diagnosis:string * starved:int
            | KindedTerminalNoFurther of key:NativeReplayKey<'K> * payload:string * diagnosis:string

        type TerminalPayloadBridgeReceipt =
            | TerminalPayloadBridgeReceipt of className:string * kindName:string * payloadText:string * liveEvidence:string * rootAuthority:string * bridgeAction:TerminalPayloadBridgeAction

        let terminalPayloadIngressClassText = function
            | TerminalPayloadIngressSemanticStaleRetarget -> "SemanticStaleRetarget"
            | TerminalPayloadIngressIdleCrossKindSidecar -> "IdleCrossKindSidecar"
            | TerminalPayloadIngressPureTopologyZeroFact -> "PureTopologyZeroFact"
            | TerminalPayloadIngressPlateauPoison -> "PlateauPoison"
            | TerminalPayloadIngressCyclePoison -> "CyclePoison"
            | TerminalPayloadIngressNoFurther -> "NoFurther"

        let terminalPayloadBridgeActionText = function
            | TerminalPayloadBridgeSleep reason -> "Sleep|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | TerminalPayloadBridgeRepair reason -> "Repair|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | TerminalPayloadBridgeEmitStructuredError reason -> "EmitStructuredError|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | TerminalPayloadBridgeConsumeMaterialDelta facts -> "ConsumeMaterialDelta|facts=" + string facts

        let kindIndexedNativeTerminalPayloadText = function
            | KindedTerminalSemanticStaleRetarget(key, semanticFailureId, payload, diagnosis, starved) ->
                "KindIndexedTerminalPayload(SemanticStaleRetarget|" + nativeReplayKeyText key + "|semantic_failure_id=" + nonEmptyOr "unknown" semanticFailureId + "|starved=" + string starved + "|payload=" + nonEmptyOr "required" payload + "|diagnosis=" + nonEmptyOr "required" diagnosis + ")"
            | KindedTerminalIdleCrossKindSidecar(key, payload, sidecarState, continuationState, starved) ->
                "KindIndexedTerminalPayload(IdleCrossKindSidecar|" + nativeReplayKeyText key + "|sidecar=" + nonEmptyOr "unknown" sidecarState + "|continuation=" + nonEmptyOr "unknown" continuationState + "|starved=" + string starved + "|payload=" + nonEmptyOr "required" payload + ")"
            | KindedTerminalPureTopologyZeroFact(key, witness, payload, diagnosis) ->
                "KindIndexedTerminalPayload(PureTopologyZeroFact|" + nativeReplayKeyText key + "|witness=" + nonEmptyOr "unknown" witness + "|payload=" + nonEmptyOr "required" payload + "|diagnosis=" + nonEmptyOr "required" diagnosis + ")"
            | KindedTerminalPlateauPoison(key, payload, diagnosis, starved) ->
                "KindIndexedTerminalPayload(PlateauPoison|" + nativeReplayKeyText key + "|starved=" + string starved + "|payload=" + nonEmptyOr "required" payload + "|diagnosis=" + nonEmptyOr "required" diagnosis + ")"
            | KindedTerminalCyclePoison(key, payload, diagnosis, starved) ->
                "KindIndexedTerminalPayload(CyclePoison|" + nativeReplayKeyText key + "|starved=" + string starved + "|payload=" + nonEmptyOr "required" payload + "|diagnosis=" + nonEmptyOr "required" diagnosis + ")"
            | KindedTerminalNoFurther(key, payload, diagnosis) ->
                "KindIndexedTerminalPayload(NoFurther|" + nativeReplayKeyText key + "|payload=" + nonEmptyOr "required" payload + "|diagnosis=" + nonEmptyOr "required" diagnosis + ")"

        let terminalPayloadBridgeReceiptText = function
            | TerminalPayloadBridgeReceipt(className, kindName, payloadText, liveEvidence, rootAuthority, bridgeAction) ->
                "TerminalPayloadBridgeReceipt(class=" + className
                + "|kind=" + kindName
                + "|payload=" + payloadText
                + "|live=" + liveEvidence
                + "|root_authority=" + rootAuthority
                + "|action=" + terminalPayloadBridgeActionText bridgeAction + ")"

        let terminalPayloadIngressClassFor
            (minimalClass:MinimalTerminalPayloadClass)
            (blockerClass:NativeClosureBlockerClass)
            (consumerDelta:ConsumerDeltaKindAfterExecutionId)
            semanticFactCount =
            match minimalClass, blockerClass, consumerDelta with
            | MinimalTerminalPayloadSemanticStaleRetarget, _, _ ->
                TerminalPayloadIngressSemanticStaleRetarget
            | MinimalTerminalPayloadCyclePoison, _, _ ->
                TerminalPayloadIngressCyclePoison
            | MinimalTerminalPayloadNoFurtherDelta, _, _ ->
                TerminalPayloadIngressNoFurther
            | _, NativeClosureBlockerIdleCrossKind, _
            | _, NativeClosureBlockerSidecar, _
            | _, _, ConsumerDeltaPureSidecarDrain _ ->
                TerminalPayloadIngressIdleCrossKindSidecar
            | _, _, ConsumerDeltaPureTopologyDelta _ when semanticFactCount <= 0L ->
                TerminalPayloadIngressPureTopologyZeroFact
            | MinimalTerminalPayloadPlateauPoison, _, _ ->
                TerminalPayloadIngressPlateauPoison

        let terminalBridgeActionFor classId (rootAuthority:RootCollapseAuthority<'K>) evidence =
            if liveReplayEvidenceSnapshotHasLive evidence then TerminalPayloadBridgeSleep(CompilerKernelV2.OperationalReasonIdOps.create "live_replay_evidence_present")
            else
                match rootAuthority, classId with
                | RootCollapseAllowedAfterMaterialDelta _, _ -> TerminalPayloadBridgeConsumeMaterialDelta 1L
                | RootCollapseAllowedAfterDeadlock _, TerminalPayloadIngressSemanticStaleRetarget
                | RootCollapseAllowedAfterDeadlock _, TerminalPayloadIngressPlateauPoison
                | RootCollapseAllowedAfterDeadlock _, TerminalPayloadIngressCyclePoison -> TerminalPayloadBridgeEmitStructuredError(CompilerKernelV2.OperationalReasonIdOps.create "all_empty_deadlocked_terminal_payload")
                | RootCollapseAllowedAfterDeadlock _, TerminalPayloadIngressIdleCrossKindSidecar
                | RootCollapseAllowedAfterDeadlock _, TerminalPayloadIngressPureTopologyZeroFact -> TerminalPayloadBridgeRepair(CompilerKernelV2.OperationalReasonIdOps.create "topology_payload_requires_repair_before_error")
                | RootCollapseBlockedByBridgeGate _, _ -> TerminalPayloadBridgeSleep(CompilerKernelV2.OperationalReasonIdOps.create "bridge_gate_blocked")
                | RootCollapseBlockedByLiveReplayEvidence _, _ -> TerminalPayloadBridgeSleep(CompilerKernelV2.OperationalReasonIdOps.create "live_replay_evidence_gate_blocked")
                | _, TerminalPayloadIngressNoFurther -> TerminalPayloadBridgeRepair(CompilerKernelV2.OperationalReasonIdOps.create "no_further_requires_root_complete_receipt")

        // MIGRATION: the migration deliberately hoists the root-collapse authority
        // helpers before terminal payload projection.  Round 2 left this as a
        // forward reference; that is fine as design sketch but not as an F#
        // source migration.  The duplicate definitions below remain temporarily
        // shadowed later until the compatibility cut is deleted deletes the legacy copy.
        let liveReplayBridgeGateFor evidence frontier canonical terminal =
            let key = nativeReplayKey<ReplayCrossKind> "cross_kind" "observer" "live_replay_bridge_gate" (anyNativeReplayKeyText evidence.focus)
            if liveReplayEvidenceSnapshotHasLive evidence then
                let reason =
                    if evidence.sidecar then WaitGraphDeferredBySidecarDrain evidence
                    elif evidence.cross > 0L then WaitGraphDeferredByCrossKind evidence
                    else WaitGraphDeferredByLiveEvidence evidence
                let ledger : NativeWaitGraphLedger<ReplayCrossKind,NativeWaitGraphStageOpen> = { key = key; reason = reason; frontier = frontier; canonical = canonical; terminal = terminal }
                BridgeGateSleep(ledger, evidence)
            else
                let ledger : NativeWaitGraphLedger<ReplayCrossKind,NativeWaitGraphStageDeadlocked> = { key = key; reason = WaitGraphDeadlockedAfterAllEmpty evidence; frontier = frontier; canonical = canonical; terminal = terminal }
                BridgeGateEmitStructuredError ledger

        let liveReplayRootCollapseAuthorityFor evidence frontier canonical terminal =
            let bridge = liveReplayBridgeGateFor evidence frontier canonical terminal
            match bridge with
            | BridgeGateSleep _
            | BridgeGateRepair _ -> RootCollapseBlockedByBridgeGate bridge
            | BridgeGateEmitStructuredError ledger -> RootCollapseAllowedAfterDeadlock ledger
            | BridgeGateConsumeMaterialDelta(ledger, _) -> RootCollapseAllowedAfterMaterialDelta ledger

        let nativeKindIndexedTerminalPayloadEnvelopeFor classId payloadText diagnosisText starved resultText evidence =
            let className = terminalPayloadIngressClassText classId
            let rootAuthority = liveReplayRootCollapseAuthorityFor evidence 0L evidence.cross evidence.active
            let action = terminalBridgeActionFor classId rootAuthority evidence
            match classId with
            | TerminalPayloadIngressSemanticStaleRetarget ->
                let key = nativeReplayKey<ReplayCrossKind> "cross_kind" "semantic_stale_retarget" "terminal_payload_bridge" payloadText
                let payload = KindedTerminalSemanticStaleRetarget(key, "semantic_failure_from_payload", payloadText, diagnosisText, starved)
                TerminalPayloadBridgeReceipt(className, "ReplayCrossKind", kindIndexedNativeTerminalPayloadText payload, liveReplayEvidenceSnapshotText evidence, rootCollapseAuthorityText rootAuthority, action) |> terminalPayloadBridgeReceiptText
            | TerminalPayloadIngressIdleCrossKindSidecar ->
                let key = nativeReplayKey<ReplaySidecarDrainKind> "sidecar_drain" "idle_cross_kind" "terminal_payload_bridge" payloadText
                let sidecarState = if evidence.sidecar then "draining" else "unknown"
                let continuationState = if evidence.continuation then "pending" else "unknown"
                let payload = KindedTerminalIdleCrossKindSidecar(key, payloadText, sidecarState, continuationState, starved)
                TerminalPayloadBridgeReceipt(className, "ReplaySidecarDrainKind", kindIndexedNativeTerminalPayloadText payload, liveReplayEvidenceSnapshotText evidence, rootCollapseAuthorityText rootAuthority, action) |> terminalPayloadBridgeReceiptText
            | TerminalPayloadIngressPureTopologyZeroFact ->
                let key = nativeReplayKey<ReplayTyKind> "ty" "pure_topology_zero_fact" "terminal_payload_bridge" payloadText
                let payload = KindedTerminalPureTopologyZeroFact(key, "zero_fact_topology_witness", payloadText, diagnosisText)
                TerminalPayloadBridgeReceipt(className, "ReplayTyKind", kindIndexedNativeTerminalPayloadText payload, liveReplayEvidenceSnapshotText evidence, rootCollapseAuthorityText rootAuthority, action) |> terminalPayloadBridgeReceiptText
            | TerminalPayloadIngressCyclePoison ->
                let key = nativeReplayKey<ReplayDynamicJoinKind> "dynamic_join" "cycle_poison" "terminal_payload_bridge" payloadText
                let payload = KindedTerminalCyclePoison(key, payloadText, diagnosisText, starved)
                TerminalPayloadBridgeReceipt(className, "ReplayDynamicJoinKind", kindIndexedNativeTerminalPayloadText payload, liveReplayEvidenceSnapshotText evidence, rootCollapseAuthorityText rootAuthority, action) |> terminalPayloadBridgeReceiptText
            | TerminalPayloadIngressNoFurther ->
                let key = nativeReplayKey<ReplayParentResumeKind> "parent_resume" "no_further" "terminal_payload_bridge" payloadText
                let payload = KindedTerminalNoFurther(key, payloadText, diagnosisText)
                TerminalPayloadBridgeReceipt(className, "ReplayParentResumeKind", kindIndexedNativeTerminalPayloadText payload, liveReplayEvidenceSnapshotText evidence, rootCollapseAuthorityText rootAuthority, action) |> terminalPayloadBridgeReceiptText
            | TerminalPayloadIngressPlateauPoison ->
                let key = nativeReplayKey<ReplayCrossKind> "cross_kind" "plateau_poison" "terminal_payload_bridge" payloadText
                let payload = KindedTerminalPlateauPoison(key, payloadText, diagnosisText, starved)
                TerminalPayloadBridgeReceipt(className, "ReplayCrossKind", kindIndexedNativeTerminalPayloadText payload, liveReplayEvidenceSnapshotText evidence, rootCollapseAuthorityText rootAuthority, action) |> terminalPayloadBridgeReceiptText

        let liveReplayEvidenceGateFor (pendingDepth:int64) (activeDepth:int64) (crossKindCount:int64) sidecarPending continuationPending (queueDepth:int64) (replayDriverTicks:int64) =
            let evidence =
                liveReplayEvidenceSnapshotFor pendingDepth activeDepth crossKindCount sidecarPending continuationPending queueDepth replayDriverTicks
                    ("pending=" + string pendingDepth + "|active=" + string activeDepth + "|cross=" + string crossKindCount)
            let authority = liveReplayRootCollapseAuthorityFor evidence 0L crossKindCount activeDepth
            let proof =
                liveReplayEvidenceSnapshotText evidence
                + "|root_collapse_authority=" + rootCollapseAuthorityText authority
            if liveReplayEvidenceSnapshotHasLive evidence then
                LiveReplayEvidencePresent(CompilerKernelV2.OperationalReasonIdOps.create (proof + "|decision=DeferredByLiveReplayEvidence"))
            else LiveReplayEvidenceAbsent(CompilerKernelV2.OperationalReasonIdOps.create (proof + "|decision=AllEmpty"))

        // MIGRATION: the action executor must not turn a failed promise into a
        // physical root exit while the live tail still has queue/cross-kind/
        // sidecar evidence.  This is the terminal-action counterpart to the
        // MIGRATION wait-for-graph collapse gate.
        type TerminalActionLivenessGateId =
            | TerminalActionLivenessAllClear of proof:CompilerKernelV2.OperationalReasonId
            | TerminalActionLivenessBlockedByReplayQueue of proof:CompilerKernelV2.OperationalReasonId
            | TerminalActionLivenessBlockedByActiveWorker of proof:CompilerKernelV2.OperationalReasonId
            | TerminalActionLivenessBlockedByCrossKindObligation of proof:CompilerKernelV2.OperationalReasonId
            | TerminalActionLivenessBlockedByReentrantReplay of proof:CompilerKernelV2.OperationalReasonId
            | TerminalActionLivenessBlockedBySidecarDrain of proof:CompilerKernelV2.OperationalReasonId

        let terminalActionLivenessGateText = function
            | TerminalActionLivenessAllClear proof -> "TerminalActionLivenessGate(AllClear|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | TerminalActionLivenessBlockedByReplayQueue proof -> "TerminalActionLivenessGate(BlockedByReplayQueue|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | TerminalActionLivenessBlockedByActiveWorker proof -> "TerminalActionLivenessGate(BlockedByActiveWorker|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | TerminalActionLivenessBlockedByCrossKindObligation proof -> "TerminalActionLivenessGate(BlockedByCrossKindObligation|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | TerminalActionLivenessBlockedByReentrantReplay proof -> "TerminalActionLivenessGate(BlockedByReentrantReplay|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | TerminalActionLivenessBlockedBySidecarDrain proof -> "TerminalActionLivenessGate(BlockedBySidecarDrain|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"

        let terminalActionLivenessGateAllowsEmit = function
            | TerminalActionLivenessAllClear _ -> true
            | _ -> false

        // MIGRATION: stale-retarget root-collapse must not be inferred from a
        // rich heartbeat after the minimal->rich terminal bridge explicitly says
        // the native failure evidence was dropped, or while RootComplete is still
        // waiting/open.  This gate is intentionally separate from the generic
        // terminal-action liveness gate: queue/active may be empty, but the bridge
        // can still be semantically non-authoritative.
        type SemanticStaleRetargetBridgeExitGateId =
            | SemanticStaleRetargetBridgeExitAllowed of proof:CompilerKernelV2.OperationalReasonId
            | SemanticStaleRetargetBridgeExitDeferredByDroppedBridge of proof:CompilerKernelV2.OperationalReasonId
            | SemanticStaleRetargetBridgeExitDeferredByAwaitingMinimalEvidence of proof:CompilerKernelV2.OperationalReasonId
            | SemanticStaleRetargetBridgeExitDeferredByOpenWaitGraph of proof:CompilerKernelV2.OperationalReasonId
            | SemanticStaleRetargetBridgeExitDeferredByRootWaiting of proof:CompilerKernelV2.OperationalReasonId
            | SemanticStaleRetargetBridgeExitDeferredByCrossKindObligation of proof:CompilerKernelV2.OperationalReasonId
            | SemanticStaleRetargetBridgeExitDeferredByTopologyWitness of proof:CompilerKernelV2.OperationalReasonId

        let semanticStaleRetargetBridgeExitGateText = function
            | SemanticStaleRetargetBridgeExitAllowed proof -> "SemanticStaleRetargetBridgeExitGate(Allowed|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | SemanticStaleRetargetBridgeExitDeferredByDroppedBridge proof -> "SemanticStaleRetargetBridgeExitGate(DeferredByDroppedBridge|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | SemanticStaleRetargetBridgeExitDeferredByAwaitingMinimalEvidence proof -> "SemanticStaleRetargetBridgeExitGate(DeferredByAwaitingMinimalEvidence|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | SemanticStaleRetargetBridgeExitDeferredByOpenWaitGraph proof -> "SemanticStaleRetargetBridgeExitGate(DeferredByOpenWaitGraph|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | SemanticStaleRetargetBridgeExitDeferredByRootWaiting proof -> "SemanticStaleRetargetBridgeExitGate(DeferredByRootWaiting|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | SemanticStaleRetargetBridgeExitDeferredByCrossKindObligation proof -> "SemanticStaleRetargetBridgeExitGate(DeferredByCrossKindObligation|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | SemanticStaleRetargetBridgeExitDeferredByTopologyWitness proof -> "SemanticStaleRetargetBridgeExitGate(DeferredByTopologyWitness|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"

        let semanticStaleRetargetBridgeExitGateAllowsEmit = function
            | SemanticStaleRetargetBridgeExitAllowed _ -> true
            | _ -> false

        let nativeMetronomeBridgeStateFor gate =
            let text = semanticStaleRetargetBridgeExitGateText gate
            match gate with
            | SemanticStaleRetargetBridgeExitAllowed _ ->
                NativeMetronomeBridgeAllowed text
            | SemanticStaleRetargetBridgeExitDeferredByAwaitingMinimalEvidence _ ->
                NativeMetronomeBridgeAwaitingMinimalEvidence text
            | _ ->
                NativeMetronomeBridgeDeferred text

        type TerminalBoundaryEvidenceId =
            | TerminalBoundarySemanticStaleRetarget
            | TerminalBoundaryMinimalBridgeDropped
            | TerminalBoundaryMinimalBridgeAwaitingFreshEvidence
            | TerminalBoundaryWaitGraphOpen
            | TerminalBoundaryRootPromiseWaiting
            | TerminalBoundaryCrossKindLive
            | TerminalBoundaryReplayDeferred
            | TerminalBoundarySidecarDrainLive
            | TerminalBoundarySemanticPayloadLive

        let private terminalBoundaryPatterns markers =
            markers
            |> List.map diagnosticTextPatternForMarker

        let private terminalBoundaryMatchesAny patterns text =
            let tokens = diagnosticTextTokensLower (nonEmptyOr "" text)
            let segments = diagnosticTextSegmentsLower (nonEmptyOr "" text)
            patterns
            |> List.exists (diagnosticTextEvidencePatternMatches tokens segments)

        let private terminalBoundarySemanticStalePatterns =
            terminalBoundaryPatterns ["SemanticStaleRetarget"; "stale_retarget"]
        let private terminalBoundaryDroppedPayloadPatterns =
            terminalBoundaryPatterns ["minimal_to_rich_payload_status=Dropped"]
        let private terminalBoundaryDroppedBridgePatterns =
            terminalBoundaryPatterns ["Dropped"]
        let private terminalBoundaryAwaitingPayloadPatterns =
            terminalBoundaryPatterns ["AwaitingFreshMinimalEvidence"; "rich_tick_awaiting_minimal_native_failure_evidence"]
        let private terminalBoundaryAwaitingBridgePatterns =
            terminalBoundaryPatterns ["AwaitingFreshMinimalEvidence"; "AwaitFreshEvidenceAndSuppressRootCollapse"]
        let private terminalBoundaryWaitOpenPatterns =
            terminalBoundaryPatterns ["NativeWaitForGraph(Open"; "wait_for_graph_not_closed"]
        let private terminalBoundaryRootWaitingPatterns =
            terminalBoundaryPatterns ["RootPromiseWaiting"]
        let private terminalBoundaryReplayActionPatterns =
            terminalBoundaryPatterns ["defer_live_replay"; "replay"]
        let private terminalBoundaryReplayReasonPatterns =
            terminalBoundaryPatterns ["reentrant_replay_driver"]
        let private terminalBoundaryDeferredNextPatterns =
            terminalBoundaryPatterns ["defer"]
        let private terminalBoundaryWaitingReadinessPatterns =
            terminalBoundaryPatterns ["waiting"; "pending"]
        let private terminalBoundarySidecarPatterns =
            terminalBoundaryPatterns ["sidecar"]
        let private terminalBoundaryContinuationPatterns =
            terminalBoundaryPatterns ["sidecar"; "continuation_cell"]
        let private terminalBoundarySemanticPayloadPatterns =
            terminalBoundaryPatterns ["cell"; "semantic"]

        type private TerminalBoundaryCrossKindState =
            | TerminalBoundaryCrossKindAbsent
            | TerminalBoundaryCrossKindLiveState of evidence:string

        let private terminalBoundaryCrossKindStateFor (text:string) =
            let safe = nonEmptyOr "none" text
            let tokens = diagnosticTextTokensLower safe
            let segments = diagnosticTextSegmentsLower safe
            let explicitAbsent =
                safe.Equals("none", StringComparison.OrdinalIgnoreCase)
                || ((Set.contains "crosskindobligation" tokens
                     || (Set.contains "cross" segments
                         && Set.contains "kind" segments
                         && Set.contains "obligation" segments))
                    && (Set.contains "absent" segments
                        || Set.contains "none" segments))
            let zeroCountPrefix =
                let parts = safe.Split([|'@'|], 2, StringSplitOptions.None)
                if parts.Length <> 2 then false
                else
                    match Int64.TryParse(parts.[0].Trim()) with
                    | true, count -> count = 0L
                    | _ -> false
            if explicitAbsent || zeroCountPrefix then
                TerminalBoundaryCrossKindAbsent
            else TerminalBoundaryCrossKindLiveState safe

        let private terminalBoundaryCrossKindLive text =
            match terminalBoundaryCrossKindStateFor text with
            | TerminalBoundaryCrossKindAbsent -> false
            | TerminalBoundaryCrossKindLiveState _ -> true

        let private terminalBoundaryEvidenceFor payload bridge rootStatus waitText crossKind readiness sidecar continuation action reason nextText =
            let mutable evidence : Set<TerminalBoundaryEvidenceId> = Set.empty
            let includeWhen condition item =
                if condition then evidence <- Set.add item evidence
            includeWhen (terminalBoundaryMatchesAny terminalBoundarySemanticStalePatterns payload) TerminalBoundarySemanticStaleRetarget
            includeWhen (terminalBoundaryMatchesAny terminalBoundaryDroppedPayloadPatterns payload || terminalBoundaryMatchesAny terminalBoundaryDroppedBridgePatterns bridge) TerminalBoundaryMinimalBridgeDropped
            includeWhen (terminalBoundaryMatchesAny terminalBoundaryAwaitingPayloadPatterns payload || terminalBoundaryMatchesAny terminalBoundaryAwaitingBridgePatterns bridge) TerminalBoundaryMinimalBridgeAwaitingFreshEvidence
            includeWhen (terminalBoundaryMatchesAny terminalBoundaryWaitOpenPatterns waitText) TerminalBoundaryWaitGraphOpen
            includeWhen (terminalBoundaryMatchesAny terminalBoundaryRootWaitingPatterns rootStatus) TerminalBoundaryRootPromiseWaiting
            includeWhen (terminalBoundaryCrossKindLive crossKind) TerminalBoundaryCrossKindLive
            includeWhen (terminalBoundaryMatchesAny terminalBoundaryReplayActionPatterns action || terminalBoundaryMatchesAny terminalBoundaryReplayReasonPatterns reason || terminalBoundaryMatchesAny terminalBoundaryDeferredNextPatterns nextText) TerminalBoundaryReplayDeferred
            includeWhen (terminalBoundaryMatchesAny terminalBoundaryWaitingReadinessPatterns readiness || terminalBoundaryMatchesAny terminalBoundarySidecarPatterns sidecar || terminalBoundaryMatchesAny terminalBoundaryContinuationPatterns continuation) TerminalBoundarySidecarDrainLive
            includeWhen (terminalBoundaryMatchesAny terminalBoundarySemanticPayloadPatterns payload) TerminalBoundarySemanticPayloadLive
            evidence

        let private terminalBoundaryEvidenceHas item evidence = Set.contains item evidence

        let semanticStaleRetargetBridgeExitGateFor payload minimalToRichStatus rootStatus waitForGraphText crossKindObligation consumerFacts astFacts =
            let safePayload = nonEmptyOr "none" payload
            let safeBridge = nonEmptyOr "unknown" minimalToRichStatus
            let safeRoot = nonEmptyOr "unknown" rootStatus
            let safeWait = nonEmptyOr "unknown" waitForGraphText
            let safeCross = nonEmptyOr "none" crossKindObligation
            let proof =
                "payload=" + safePayload
                + "|bridge=" + safeBridge
                + "|root=" + safeRoot
                + "|wait=" + safeWait
                + "|cross=" + safeCross
                + "|consumer_facts=" + string consumerFacts
                + "|ast_facts=" + string astFacts
            let evidence =
                terminalBoundaryEvidenceFor safePayload safeBridge safeRoot safeWait safeCross "" "" "" "" "" ""
            let proofWith reason = CompilerKernelV2.OperationalReasonIdOps.create (proof + "|reason=" + reason)
            if not (terminalBoundaryEvidenceHas TerminalBoundarySemanticStaleRetarget evidence) then SemanticStaleRetargetBridgeExitAllowed(proofWith "not_semantic_stale_retarget")
            elif terminalBoundaryEvidenceHas TerminalBoundaryMinimalBridgeAwaitingFreshEvidence evidence then SemanticStaleRetargetBridgeExitDeferredByAwaitingMinimalEvidence(proofWith "minimal_to_rich_bridge_awaiting_fresh_typed_evidence")
            elif terminalBoundaryEvidenceHas TerminalBoundaryMinimalBridgeDropped evidence then SemanticStaleRetargetBridgeExitDeferredByDroppedBridge(proofWith "legacy_dropped_bridge_quarantined_no_authority")
            elif terminalBoundaryEvidenceHas TerminalBoundaryWaitGraphOpen evidence then SemanticStaleRetargetBridgeExitDeferredByOpenWaitGraph(proofWith "wait_for_graph_still_open")
            elif terminalBoundaryEvidenceHas TerminalBoundaryRootPromiseWaiting evidence then SemanticStaleRetargetBridgeExitDeferredByRootWaiting(proofWith "root_complete_still_waiting")
            elif terminalBoundaryEvidenceHas TerminalBoundaryCrossKindLive evidence then SemanticStaleRetargetBridgeExitDeferredByCrossKindObligation(proofWith "cross_kind_obligation_live")
            elif consumerFacts > 0L || astFacts > 0L then SemanticStaleRetargetBridgeExitDeferredByTopologyWitness(proofWith "topology_witness_facts_present")
            else SemanticStaleRetargetBridgeExitAllowed(proofWith "stale_retarget_bridge_authoritative")

        let terminalActionLivenessGateFor queueDepth activeDepth pendingDepth crossKindObligation continuationReadiness sidecarParity continuationVsSidecarDrain actionDu reasonText nextText blockerText =
            let q = parseInt64Safe queueDepth
            let a = parseInt64Safe activeDepth
            let p = parseInt64Safe pendingDepth
            let safeCross = nonEmptyOr "none" crossKindObligation
            let safeReadiness = nonEmptyOr "unknown" continuationReadiness
            let safeSidecar = nonEmptyOr "none" sidecarParity
            let safeContinuation = nonEmptyOr "none" continuationVsSidecarDrain
            let safeAction = nonEmptyOr "none" actionDu
            let safeReason = nonEmptyOr "none" reasonText
            let safeNext = nonEmptyOr "none" nextText
            let safeBlocker = nonEmptyOr "unknown" blockerText
            let proof =
                "queue=" + string q
                + "|active=" + string a
                + "|pending=" + string p
                + "|cross=" + safeCross
                + "|readiness=" + safeReadiness
                + "|sidecar=" + safeSidecar
                + "|continuation=" + safeContinuation
                + "|action=" + safeAction
                + "|reason=" + safeReason
                + "|next=" + safeNext
                + "|blocker=" + safeBlocker
            let evidence =
                terminalBoundaryEvidenceFor "" "" "" "" safeCross safeReadiness safeSidecar safeContinuation safeAction safeReason safeNext
            let proofId suffix = CompilerKernelV2.OperationalReasonIdOps.create (proof + suffix)
            if q > 0L then TerminalActionLivenessBlockedByReplayQueue(proofId "|reason=replay_queue_not_empty")
            elif a > 0L then TerminalActionLivenessBlockedByActiveWorker(proofId "|reason=active_worker_not_empty")
            elif terminalBoundaryEvidenceHas TerminalBoundaryCrossKindLive evidence then TerminalActionLivenessBlockedByCrossKindObligation(proofId "|reason=cross_kind_obligation_live")
            elif terminalBoundaryEvidenceHas TerminalBoundaryReplayDeferred evidence then TerminalActionLivenessBlockedByReentrantReplay(proofId "|reason=reentrant_replay_still_deferred")
            elif terminalBoundaryEvidenceHas TerminalBoundarySidecarDrainLive evidence then TerminalActionLivenessBlockedBySidecarDrain(proofId "|reason=sidecar_or_continuation_cell_live")
            else TerminalActionLivenessAllClear(proofId "|reason=queue_active_cross_kind_sidecar_empty")

        // MIGRATION: root-complete handoff exhaustion is not a terminal proof while
        // the live replay tail still has queue/active/pending/payload witnesses.
        // This gate mirrors the terminal action liveness gate, but sits at the
        // retry-trampoline boundary that previously converted attempt=cap+1 into
        // a semantic fatal even with RootPromiseWaiting in the HUD.
        type RootCompleteHandoffLivenessGateId =
            | RootCompleteHandoffLivenessAllowed of proof:CompilerKernelV2.OperationalReasonId
            | RootCompleteHandoffLivenessDeferredByReplayQueue of proof:CompilerKernelV2.OperationalReasonId
            | RootCompleteHandoffLivenessDeferredByActiveDriver of proof:CompilerKernelV2.OperationalReasonId
            | RootCompleteHandoffLivenessDeferredByPendingTopology of proof:CompilerKernelV2.OperationalReasonId
            | RootCompleteHandoffLivenessDeferredByReplayWitness of proof:CompilerKernelV2.OperationalReasonId
            | RootCompleteHandoffLivenessDeferredByPayloadCell of proof:CompilerKernelV2.OperationalReasonId

        let rootCompleteHandoffLivenessGateText = function
            | RootCompleteHandoffLivenessAllowed proof -> "RootCompleteHandoffLivenessGate(Allowed|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | RootCompleteHandoffLivenessDeferredByReplayQueue proof -> "RootCompleteHandoffLivenessGate(DeferredByReplayQueue|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | RootCompleteHandoffLivenessDeferredByActiveDriver proof -> "RootCompleteHandoffLivenessGate(DeferredByActiveDriver|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | RootCompleteHandoffLivenessDeferredByPendingTopology proof -> "RootCompleteHandoffLivenessGate(DeferredByPendingTopology|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | RootCompleteHandoffLivenessDeferredByReplayWitness proof -> "RootCompleteHandoffLivenessGate(DeferredByReplayWitness|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | RootCompleteHandoffLivenessDeferredByPayloadCell proof -> "RootCompleteHandoffLivenessGate(DeferredByPayloadCell|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"

        let rootCompleteHandoffLivenessGateAllowsExhaustion = function
            | RootCompleteHandoffLivenessAllowed _ -> true
            | _ -> false

        let rootCompleteHandoffLivenessGateFor pendingDepth queueDepth activeDepth payloadStatus hasReplayCompleteWitness rootFinalizationRequested yieldUsed yieldCap =
            let p = int64 pendingDepth
            let q = int64 queueDepth
            let a = int64 activeDepth
            let safePayload = nonEmptyOr "none" payloadStatus
            let proof =
                "pending=" + string p
                + "|queue=" + string q
                + "|active=" + string a
                + "|payload_status=" + safePayload
                + "|replay_write_witness=" + string hasReplayCompleteWitness
                + "|root_finalization_requested=" + string rootFinalizationRequested
                + "|yield_used=" + string yieldUsed
                + "|yield_cap=" + string yieldCap
            let evidence = terminalBoundaryEvidenceFor safePayload "" "" "" "" "" "" "" "" "" ""
            let proofId suffix = CompilerKernelV2.OperationalReasonIdOps.create (proof + suffix)
            if q > 0L then RootCompleteHandoffLivenessDeferredByReplayQueue(proofId "|reason=replay_queue_not_empty")
            elif a > 0L then RootCompleteHandoffLivenessDeferredByActiveDriver(proofId "|reason=replay_driver_active")
            elif p > 0L then RootCompleteHandoffLivenessDeferredByPendingTopology(proofId "|reason=pending_topology_not_empty")
            elif hasReplayCompleteWitness then RootCompleteHandoffLivenessDeferredByReplayWitness(proofId "|reason=fresh_replay_root_witness")
            elif terminalBoundaryEvidenceHas TerminalBoundarySemanticPayloadLive evidence then RootCompleteHandoffLivenessDeferredByPayloadCell(proofId "|reason=semantic_payload_cell_or_value_live")
            else RootCompleteHandoffLivenessAllowed(proofId "|reason=no_live_handoff_witness")

        // MIGRATION: RootComplete exit now consumes a typed phantom event instead
        // of rebuilding terminal cause from rendered strings.  This is intentionally
        // parallel to the MIGRATION dynamic-join witness migration: JSON/HUD are
        // projections of TerminalPayload<'K> -> PromiseOutcome<'K> -> RootCompleteEvent<'K>.
        type RootCompleteK = | RootCompleteK
        type NativeTerminalPayloadTyped<'K> =
            | NativeTerminalPayloadTypedFailedPromise of promiseId:string * closureId:string * semanticFailureId:string * payload:string * sourceSpan:string
            | NativeTerminalPayloadTypedNoFurther of promiseId:string * closureId:string * reason:CompilerKernelV2.OperationalReasonId
            | NativeTerminalPayloadTypedObserverOnly of promiseId:string * reason:CompilerKernelV2.OperationalReasonId

        let nativeTerminalPayloadTypedText = function
            | NativeTerminalPayloadTypedFailedPromise(promiseId, closureId, semanticFailureId, payload, sourceSpan) ->
                "TerminalPayload<RootComplete>(FailedPromise|promise=" + nonEmptyOr "unknown" promiseId + "|closure=" + nonEmptyOr "unknown" closureId + "|semantic_failure_id=" + nonEmptyOr "unknown" semanticFailureId + "|span=" + nonEmptyOr "unknown" sourceSpan + "|payload=" + nonEmptyOr "required" payload + ")"
            | NativeTerminalPayloadTypedNoFurther(promiseId, closureId, reason) ->
                "TerminalPayload<RootComplete>(NoFurther|promise=" + nonEmptyOr "unknown" promiseId + "|closure=" + nonEmptyOr "unknown" closureId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NativeTerminalPayloadTypedObserverOnly(promiseId, reason) ->
                "TerminalPayload<RootComplete>(ObserverOnly|promise=" + nonEmptyOr "unknown" promiseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        type NativePromiseOutcomeTyped<'K> =
            | NativePromiseOutcomeTypedFailed of promiseId:string * payload:NativeTerminalPayloadTyped<'K>
            | NativePromiseOutcomeTypedClearedByMaterialDelta of promiseId:string * factKind:string
            | NativePromiseOutcomeTypedWaiting of promiseId:string * reason:CompilerKernelV2.OperationalReasonId

        let nativePromiseOutcomeTypedText = function
            | NativePromiseOutcomeTypedFailed(promiseId, payload) ->
                "PromiseOutcome<RootComplete>(Failed|promise=" + nonEmptyOr "unknown" promiseId + "|payload=" + nativeTerminalPayloadTypedText payload + ")"
            | NativePromiseOutcomeTypedClearedByMaterialDelta(promiseId, factKind) ->
                "PromiseOutcome<RootComplete>(ClearedByMaterialDelta|promise=" + nonEmptyOr "unknown" promiseId + "|fact_kind=" + nonEmptyOr "term_or_ty" factKind + ")"
            | NativePromiseOutcomeTypedWaiting(promiseId, reason) ->
                "PromiseOutcome<RootComplete>(Waiting|promise=" + nonEmptyOr "unknown" promiseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        type RootCompleteTypedEvent<'K> =
            | RootCompleteTypedTerminal of outcome:NativePromiseOutcomeTyped<'K> * commit:NativeTerminalCommitClassId * action:NativeTerminalActionDecisionId
            | RootCompleteTypedAwaiting of outcome:NativePromiseOutcomeTyped<'K> * reason:CompilerKernelV2.OperationalReasonId
            | RootCompleteTypedCleared of outcome:NativePromiseOutcomeTyped<'K> * reason:CompilerKernelV2.OperationalReasonId

        let rootCompleteTypedEventText = function
            | RootCompleteTypedTerminal(outcome, commit, action) ->
                "RootCompleteTypedEvent(Terminal|outcome=" + nativePromiseOutcomeTypedText outcome + "|commit=" + nativeTerminalCommitClassText commit + "|action=" + nativeTerminalActionDecisionText action + ")"
            | RootCompleteTypedAwaiting(outcome, reason) ->
                "RootCompleteTypedEvent(Awaiting|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|outcome=" + nativePromiseOutcomeTypedText outcome + ")"
            | RootCompleteTypedCleared(outcome, reason) ->
                "RootCompleteTypedEvent(Cleared|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|outcome=" + nativePromiseOutcomeTypedText outcome + ")"

        let rootCompleteTypedExitPolicyText = function
            | RootCompleteTypedTerminal(outcome, _, _) ->
                "RootCompleteTypedExitPolicy(EmitStructuredSemanticErrorExitOne|outcome=" + nativePromiseOutcomeTypedText outcome + ")"
            | RootCompleteTypedAwaiting(outcome, reason) ->
                "RootCompleteTypedExitPolicy(AwaitNativeOutcome|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|outcome=" + nativePromiseOutcomeTypedText outcome + ")"
            | RootCompleteTypedCleared(outcome, reason) ->
                "RootCompleteTypedExitPolicy(ClearedByMaterialDelta|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|outcome=" + nativePromiseOutcomeTypedText outcome + ")"

        let semanticFailureIdFor promiseId terminalClosureId payload =
            let stable = (nonEmptyOr "promise_unknown" promiseId) + "|" + (nonEmptyOr "closure_unknown" terminalClosureId) + "|" + (nonEmptyOr "payload_unknown" payload)
            CompilerIdentityKernel.ContentDigest.ofText "semantic-failure" stable |> CompilerIdentityKernel.ContentDigest.text

        let nativeWaitForGraphVerdictFor
            (debtSignals:Set<NativeWaitForGraphDebtSignalId>)
            (source:SemanticSourceSpanId)
            semanticStaleRetarget
            idleCrossKind
            hasPhysicalSidecarPending
            (parentContinuationLiveness:NativeParentContinuationLivenessId)
            noDelta
            (pendingFrontier:int64)
            (pendingCanonical:int64)
            (activeWorkers:int64)
            (terminalSignals:int64)
            (rootPromiseFailed:bool)
            (failedPromiseClearance:NativePromiseFailureClearanceId) =
            let failedPromiseClearanceAllowed = nativePromiseFailureClearanceAllowsProgress failedPromiseClearance
            let sourceText = semanticSourceSpanText source
            let terminalPayloadInDebtText =
                Set.contains NativeWaitForGraphDebtTerminalPayload debtSignals
            let continuationHistoricalHint =
                Set.contains NativeWaitForGraphDebtContinuationHistorical debtSignals
            let continuationBlocked =
                nativeParentContinuationLivenessHasAuthority parentContinuationLiveness
            let terminalPayloadMaterialized = terminalSignals > 0L || rootPromiseFailed || terminalPayloadInDebtText
            let noExecutableFrontier = pendingFrontier <= 0L && activeWorkers <= 1L
            let strandedCanonicalPending = pendingCanonical > 0L && pendingFrontier <= 0L
            let typedTopologyTerminal = semanticStaleRetarget || idleCrossKind || terminalPayloadMaterialized
            let liveWaitGraphEvidence =
                pendingFrontier > 0L
                || pendingCanonical > 0L
                || activeWorkers > 0L
                || hasPhysicalSidecarPending
                || continuationBlocked
            let liveWaitGraphProof =
                { pendingFrontier = pendingFrontier
                  pendingCanonical = pendingCanonical
                  activeWorkers = activeWorkers
                  physicalSidecarPending = hasPhysicalSidecarPending
                  continuationBlocked = continuationBlocked
                  parentContinuationLiveness = parentContinuationLiveness
                  continuationHistoricalHint = continuationHistoricalHint
                  source = source }
            let topologyCollapseGateId =
                nativeWaitForGraphTopologyCollapseGateFor pendingCanonical pendingFrontier activeWorkers typedTopologyTerminal idleCrossKind semanticStaleRetarget debtSignals
            if not noDelta && not rootPromiseFailed then NativeWaitForGraphResolvedByDelta (CompilerKernelV2.OperationalReasonIdOps.create "fresh_nonfailed_delta_present")
            elif rootPromiseFailed && failedPromiseClearanceAllowed then NativeWaitForGraphResolvedByDelta (CompilerKernelV2.OperationalReasonIdOps.create (nativePromiseFailureClearanceText failedPromiseClearance))
            elif liveWaitGraphEvidence && (semanticStaleRetarget || idleCrossKind || continuationBlocked) then
                NativeWaitForGraphOpen(NativeWaitForGraphOpenLiveEvidence liveWaitGraphProof)
            elif noExecutableFrontier && not hasPhysicalSidecarPending && not (nativeWaitForGraphTopologyCollapseGateAllowsCollapse topologyCollapseGateId) then
                NativeWaitForGraphOpen(NativeWaitForGraphOpenTopologyDeferred topologyCollapseGateId)
            elif not noDelta && rootPromiseFailed && terminalPayloadMaterialized && noExecutableFrontier && not hasPhysicalSidecarPending then
                let payload = "NativeTopologyFatalPromiseWaitForGraph(node=" + sourceText + "|continuation=" + (if continuationBlocked then "waiting" else "materialized_terminal") + "|sidecar=absent|frontier=" + string pendingFrontier + "|canonical=" + string pendingCanonical + "|active=" + string activeWorkers + "|terminal=" + string terminalSignals + "|delta_class=fresh_nonmaterial_or_unwithdrawn_failure)"
                NativeWaitForGraphDeadlocked(source, NativeWaitDeadlockFatalPromiseFailureNotClearedByMaterialDelta, payload)
            elif terminalPayloadMaterialized && noExecutableFrontier && not hasPhysicalSidecarPending then
                let payload = "NativeTopologyTerminalWaitForGraph(node=" + sourceText + "|continuation=" + (if continuationBlocked then "waiting" else "materialized_terminal") + "|sidecar=absent|frontier=" + string pendingFrontier + "|canonical=" + string pendingCanonical + "|active=" + string activeWorkers + "|terminal=" + string terminalSignals + ")"
                NativeWaitForGraphDeadlocked(source, NativeWaitDeadlockMaterializedTerminalWithNoExecutableFrontier, payload)
            elif typedTopologyTerminal && noExecutableFrontier && continuationBlocked && not hasPhysicalSidecarPending && terminalPayloadMaterialized then
                let payload = "NativeTopologyTerminalWaitForGraph(node=" + sourceText + "|continuation=waiting|sidecar=absent|frontier=" + string pendingFrontier + "|canonical=" + string pendingCanonical + "|active=" + string activeWorkers + "|terminal=" + string terminalSignals + ")"
                NativeWaitForGraphDeadlocked(source, NativeWaitDeadlockMaterializedTerminalWithNoExecutableFrontier, payload)
            elif typedTopologyTerminal && noExecutableFrontier && continuationBlocked && not hasPhysicalSidecarPending && strandedCanonicalPending then
                let payload = "NativeTopologyStrandedPendingWaitForGraph(node=" + sourceText + "|continuation=waiting|sidecar=absent|frontier=" + string pendingFrontier + "|canonical=" + string pendingCanonical + "|active=" + string activeWorkers + ")"
                NativeWaitForGraphDeadlocked(source, NativeWaitDeadlockStrandedCanonicalPendingWithoutFrontier, payload)
            else NativeWaitForGraphOpen NativeWaitForGraphOpenNotClosed

        // MIGRATION migration phase: RootPromiseFailed must be an action, not only
        // a projection on progress_tick.  This DU is the breaking bridge that
        // turns SemanticStaleRetarget/CyclePoison fixed-points into a typed
        // BuildErrorTrace/exit surface once no recent root/terminal delta exists.
        type RootCollapseActionId =
            | RootCollapseNoAction of reason:CompilerKernelV2.OperationalReasonId
            | RootCollapseEmitStructuredSemanticErrorExitOne of payload:string * exitCode:int
            | RootCollapseEmitNoFurtherExitOne of terminalOutcomeId:string * reason:CompilerKernelV2.OperationalReasonId * exitCode:int
            | RootCollapseObserverOnly of reason:CompilerKernelV2.OperationalReasonId

        let rootCollapseActionText = function
            | RootCollapseNoAction reason -> "RootCollapseAction(NoAction|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | RootCollapseEmitStructuredSemanticErrorExitOne(payload, exitCode) -> "RootCollapseAction(EmitStructuredSemanticErrorExitOne|payload=" + payload + "|exit_code=" + string exitCode + ")"
            | RootCollapseEmitNoFurtherExitOne(terminalOutcomeId, reason, exitCode) -> "RootCollapseAction(EmitNoFurtherExitOne|terminal_outcome_id=" + terminalOutcomeId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|exit_code=" + string exitCode + ")"
            | RootCollapseObserverOnly reason -> "RootCollapseAction(ObserverOnly|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let rootCollapseActionExitCode = function
            | RootCollapseEmitStructuredSemanticErrorExitOne(_, exitCode)
            | RootCollapseEmitNoFurtherExitOne(_, _, exitCode) -> exitCode
            | _ -> 0

        let nativePromiseSemanticErrorPayloadText = function
            | NativePromiseOutcomeFailedPlateau(_, payload) -> payload
            | NativePromiseOutcomeFailedCycle(_, payload) -> payload
            | NativePromiseOutcomeNoFurther(_, reason) -> CompilerKernelV2.OperationalReasonIdOps.text reason
            | NativePromiseOutcomeResolvedDelta _ -> ""
            | NativePromiseOutcomeObserverOnly _ -> ""

        let nativePromiseOutcomeText = function
            | NativePromiseOutcomeResolvedDelta(promiseId, facts) -> "PromiseOutcome.ResolvedDelta(promise=" + promiseId + "|facts=" + string facts + ")"
            | NativePromiseOutcomeFailedPlateau(promiseId, payload) -> "PromiseOutcome.FailedPlateau(promise=" + promiseId + "|payload=" + payload + "|propagation=monadic_poison_not_native_promise_success)"
            | NativePromiseOutcomeFailedCycle(promiseId, payload) -> "PromiseOutcome.FailedCycle(promise=" + promiseId + "|payload=" + payload + "|propagation=monadic_poison_not_native_promise_success)"
            | NativePromiseOutcomeNoFurther(promiseId, reason) -> "PromiseOutcome.NoFurther(promise=" + promiseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NativePromiseOutcomeObserverOnly(promiseId, reason) -> "PromiseOutcome.ObserverOnly(promise=" + promiseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        type NativeCyclePoisonPayloadKindId =
            | NativeCyclePoisonTopologyTerminalWait
            | NativeCyclePoisonIdleCrossKind
            | NativeCyclePoisonOther

        let private nativeCyclePoisonPayloadKind (payload:string) =
            if System.String.IsNullOrEmpty payload then NativeCyclePoisonOther
            else
                let tokens =
                    payload.Split(
                        [| '|'; ':'; ','; ';'; ' '; '='; '('; ')'; '['; ']'; '\n'; '\r'; '\t' |],
                        StringSplitOptions.RemoveEmptyEntries)
                    |> Array.map (fun token -> token.ToLowerInvariant())
                    |> Set.ofArray
                if Set.contains "nativetopologyterminalwaitforgraph" tokens then
                    NativeCyclePoisonTopologyTerminalWait
                elif Set.contains "idlecrosskind" tokens then
                    NativeCyclePoisonIdleCrossKind
                else NativeCyclePoisonOther

        let nativePromiseOutcomeFor promiseId astDeltaId semanticFactCount =
            match astDeltaId with
            | NativeAstDeltaMeasuredCounterDelta
            | NativeAstDeltaExecutePureAstStep _ when semanticFactCount > 0L -> NativePromiseOutcomeResolvedDelta(promiseId, semanticFactCount)
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, _, _) when semanticFactCount > 0L -> NativePromiseOutcomeResolvedDelta(promiseId, semanticFactCount)
            | NativeAstDeltaPureTopologyWitnessMaterialized(contract, kind, reason) -> NativePromiseOutcomeObserverOnly(promiseId, CompilerKernelV2.OperationalReasonIdOps.create ("semantic_barrier_required|topology_witness_materialized|contract=" + nativeDirectEvaluationContractText contract + "|kind=" + nativeClosureKindText kind + "|reason=" + nativePureTopologyWitnessReasonText reason + "|facts=" + string semanticFactCount))
            | NativeAstDeltaCyclePoisonInjected payload when semanticFactCount > 0L ->
                match nativeCyclePoisonPayloadKind payload with
                | NativeCyclePoisonTopologyTerminalWait ->
                    NativePromiseOutcomeNoFurther(promiseId, CompilerKernelV2.OperationalReasonIdOps.create ("topology_terminal_cycle_poison_deferred_by_material_fact|payload=" + payload + "|facts=" + string semanticFactCount))
                | NativeCyclePoisonIdleCrossKind ->
                    NativePromiseOutcomeNoFurther(promiseId, CompilerKernelV2.OperationalReasonIdOps.create ("idle_cross_kind_cycle_poison_deferred_by_material_fact|payload=" + payload + "|facts=" + string semanticFactCount))
                | NativeCyclePoisonOther ->
                    NativePromiseOutcomeFailedCycle(promiseId, payload)
            | NativeAstDeltaCyclePoisonInjected payload -> NativePromiseOutcomeFailedCycle(promiseId, payload)
            | NativeAstDeltaSemanticPlateauPoison(contract, kind, reason) -> NativePromiseOutcomeFailedPlateau(promiseId, nativeDirectEvaluationSemanticPlateauPayload contract kind reason)
            | NativeAstDeltaBlockedLegacyFallback contract -> NativePromiseOutcomeNoFurther(promiseId, CompilerKernelV2.OperationalReasonIdOps.create ("blocked_legacy_fallback|" + nativeDirectEvaluationContractText contract))
            | NativeAstDeltaNoContractLegacyForbidden -> NativePromiseOutcomeNoFurther(promiseId, CompilerKernelV2.OperationalReasonIdOps.create "no_direct_eval_contract_legacy_forbidden")
            | _ -> NativePromiseOutcomeObserverOnly(promiseId, CompilerKernelV2.OperationalReasonIdOps.create "no_semantic_fact_and_no_poison_payload")

        // MIGRATION MIGRATION : replace the failure-only commit boundary with
        // a phantom-indexed terminal-outcome graph.  Physical occupancy is not
        // equivalent to semantic progress, and NoFurther is terminal without
        // pretending to be a semantic failure.
        type TerminalOutcomeKind = | TerminalOutcomeKind
        type TerminalGraphProgressing = | TerminalGraphProgressing
        type TerminalGraphStalled = | TerminalGraphStalled
        type TerminalGraphExhausted = | TerminalGraphExhausted

        type TerminalGraphClosureAuthorityId =
            | TerminalGraphClosureUnproven
            | TerminalGraphClosureProven of receipt:string

        let terminalGraphClosureAuthorityText = function
            | TerminalGraphClosureUnproven -> "TerminalGraphClosureAuthority(Unproven)"
            | TerminalGraphClosureProven receipt -> "TerminalGraphClosureAuthority(Proven|receipt=" + receipt + ")"

        [<Struct>]
        type CanonicalTerminalClosureId<'Kind> =
            { value:string }

        [<Struct>]
        type TerminalGraphEpoch<'Kind> =
            { value:int64 }

        [<Struct>]
        type TerminalGraphStateHash<'Kind> =
            { value:string }

        [<Struct>]
        type TopologyWitnessId<'Kind> =
            { value:string }

        type TopologyWitnessMaterialization<'Kind> =
            | TopologyWitnessAbsent
            | TopologyWitnessFirstMaterialization of witnessId:TopologyWitnessId<'Kind> * epoch:TerminalGraphEpoch<'Kind>
            | TopologyWitnessAlreadyMaterialized of witnessId:TopologyWitnessId<'Kind> * firstEpoch:TerminalGraphEpoch<'Kind> * observedEpoch:TerminalGraphEpoch<'Kind>

        type TerminalExecutableGraph<'Kind,'Phase> =
            | TerminalExecutableGraphNode of
                closureId:CanonicalTerminalClosureId<'Kind> *
                pending:int64 *
                queue:int64 *
                active:int64 *
                crossKind:int64 *
                sidecarPending:bool *
                continuationPending:bool *
                epoch:TerminalGraphEpoch<'Kind> *
                stateHash:TerminalGraphStateHash<'Kind> *
                sameStateRepeat:int64 *
                next:TerminalExecutableGraph<'Kind,'Phase> option

        type TerminalExecutableGraphState<'Kind> =
            | TerminalGraphProgressingState of TerminalExecutableGraph<'Kind,TerminalGraphProgressing>
            | TerminalGraphStalledState of TerminalExecutableGraph<'Kind,TerminalGraphStalled>
            | TerminalGraphExhaustedState of TerminalExecutableGraph<'Kind,TerminalGraphExhausted>

        // The live scheduler graph is a typestate, not a boolean occupancy test.
        // The phantom phase prevents a stale graph lease from being consumed as
        // material progress or terminal eligibility without an explicit transition.
        type LiveGraphFresh = | LiveGraphFresh
        type LiveGraphProgressing = | LiveGraphProgressing
        type LiveGraphStale = | LiveGraphStale
        type LiveGraphDeadlocked = | LiveGraphDeadlocked
        type LiveGraphQuarantined = | LiveGraphQuarantined
        type LiveGraphTerminalEligible = | LiveGraphTerminalEligible

        [<Struct>]
        type LiveGraphCreditId<'Kind> =
            { value:string }

        type LiveGraphCreditResolution<'Kind> =
            | RequireMaterialDeltaBeforeCreditRelease
            | RequireFreshTopologyWitnessBeforeCreditRelease of TopologyWitnessId<'Kind> option
            | RequireCrossKindDrainBeforeCreditRelease of obligationId:string
            | RequireParentContinuationHandoffBeforeCreditRelease of cellId:string

        type LiveGraphConservedCredit<'Kind> = {
            leaseId : LiveGraphCreditId<'Kind>
            graphHash : TerminalGraphStateHash<'Kind>
            requiredResolution : LiveGraphCreditResolution<'Kind>
        }

        type CrossKindObligationOwnerId<'Kind> =
            { value:string }

        type CrossKindObligationCloseKey<'Kind> =
            { value:string }

        type CrossKindDrainReasonId =
            | CrossKindDrainLeaseExpiredBeforeDrain
            | CrossKindDrainDeadlockOwnerLease
            | CrossKindDrainExpiredOwnerLease
            | CrossKindDrainOwnedDeadlock

        let crossKindDrainReasonText = function
            | CrossKindDrainLeaseExpiredBeforeDrain -> "lease_expired_before_cross_kind_drain"
            | CrossKindDrainDeadlockOwnerLease -> "deadlock_owner_lease_force_drain"
            | CrossKindDrainExpiredOwnerLease -> "expired_cross_kind_owner_lease_force_drain"
            | CrossKindDrainOwnedDeadlock -> "owned_cross_kind_deadlock_force_drain"

        type CrossKindQuarantineActionId =
            | CrossKindQuarantineOrphanWorkersAfterDeadlock
            | CrossKindQuarantineUnresolvedDeadlockOwnerLease

        let crossKindQuarantineActionText = function
            | CrossKindQuarantineOrphanWorkersAfterDeadlock -> "quarantine_orphan_workers_after_deadlock_without_cross_kind_obligation"
            | CrossKindQuarantineUnresolvedDeadlockOwnerLease -> "quarantine_unresolved_deadlock_owner_lease"

        type CrossKindDrainAttempt<'Kind> = {
            owner : CrossKindObligationOwnerId<'Kind>
            obligationId : string
            beforeCount : int64
            afterCount : int64
            closedBy : CrossKindObligationCloseKey<'Kind>
            drained : bool
            reason : CrossKindDrainReasonId
        }

        type CrossKindQuarantinePlan<'Kind> = {
            owner : CrossKindObligationOwnerId<'Kind>
            obligationId : string
            remainingCount : int64
            leaseId : LiveGraphCreditId<'Kind>
            graphHash : TerminalGraphStateHash<'Kind>
            action : CrossKindQuarantineActionId
        }

        type CrossKindObligationState<'Kind> =
            | CrossKindObligationAbsent
            | CrossKindObligationOwned of owner:CrossKindObligationOwnerId<'Kind> * obligationId:string * beforeCount:int64 * lease:LiveGraphConservedCredit<'Kind>
            | CrossKindObligationReduced of attempt:CrossKindDrainAttempt<'Kind>
            | CrossKindObligationExpired of owner:CrossKindObligationOwnerId<'Kind> * obligationId:string * remainingCount:int64 * leaseId:LiveGraphCreditId<'Kind> * closeKey:CrossKindObligationCloseKey<'Kind>
            | CrossKindObligationQuarantined of plan:CrossKindQuarantinePlan<'Kind>

        type ParentContinuationOwnerId<'Kind> =
            { value:string }

        type ParentContinuationCellId<'Kind> =
            { value:string }

        type ParentContinuationCloseKey<'Kind> =
            { value:string }

        type ParentContinuationCloseReasonId =
            | ParentContinuationLeaseExpiredBeforeHandoff
            | ParentContinuationDeadlockForceHandoff
            | ParentContinuationExpiredOwnerLeaseForceHandoff
            | ParentContinuationOwnedDeadlockForceHandoff

        let parentContinuationCloseReasonText = function
            | ParentContinuationLeaseExpiredBeforeHandoff -> "lease_expired_before_parent_continuation_handoff"
            | ParentContinuationDeadlockForceHandoff -> "deadlock_parent_continuation_force_handoff"
            | ParentContinuationExpiredOwnerLeaseForceHandoff -> "expired_parent_continuation_owner_lease_force_handoff"
            | ParentContinuationOwnedDeadlockForceHandoff -> "owned_parent_continuation_deadlock_force_handoff"

        type ParentContinuationQuarantineActionId =
            | ParentContinuationQuarantineAfterDeadlockWithoutHandoff
            | ParentContinuationQuarantineUnknownOwnerAfterDeadlock

        let parentContinuationQuarantineActionText = function
            | ParentContinuationQuarantineAfterDeadlockWithoutHandoff -> "quarantine_parent_continuation_after_deadlock_without_handoff_delta"
            | ParentContinuationQuarantineUnknownOwnerAfterDeadlock -> "quarantine_parent_continuation_unknown_owner_after_deadlock"

        type ParentContinuationCloseProof<'Kind> = {
            owner : ParentContinuationOwnerId<'Kind>
            cellId : ParentContinuationCellId<'Kind>
            beforePending : int64
            afterPending : int64
            closedBy : ParentContinuationCloseKey<'Kind>
            materializedDelta : bool
            reason : ParentContinuationCloseReasonId
        }

        type ParentContinuationQuarantinePlan<'Kind> = {
            owner : ParentContinuationOwnerId<'Kind>
            cellId : ParentContinuationCellId<'Kind>
            pendingCount : int64
            leaseId : LiveGraphCreditId<'Kind>
            graphHash : TerminalGraphStateHash<'Kind>
            action : ParentContinuationQuarantineActionId
        }

        type ParentContinuationObligationState<'Kind> =
            | ParentContinuationAbsent
            | ParentContinuationOwned of owner:ParentContinuationOwnerId<'Kind> * cellId:ParentContinuationCellId<'Kind> * closureId:CanonicalTerminalClosureId<'Kind> * pendingCount:int64 * lease:LiveGraphConservedCredit<'Kind>
            | ParentContinuationHandoffReady of proof:ParentContinuationCloseProof<'Kind>
            | ParentContinuationHandoffClosed of proof:ParentContinuationCloseProof<'Kind>
            | ParentContinuationExpired of owner:ParentContinuationOwnerId<'Kind> * cellId:ParentContinuationCellId<'Kind> * pendingCount:int64 * leaseId:LiveGraphCreditId<'Kind> * closeKey:ParentContinuationCloseKey<'Kind>
            | ParentContinuationQuarantined of plan:ParentContinuationQuarantinePlan<'Kind>

        // DOMAIN MIGRATION : owner identity, close authority and lifecycle
        // are now represented by phantom-indexed values. The heterogeneous
        // recursive ledger is the new source of truth; TerminalOwnershipLedger
        // remains below as a compatibility projection while central consumers
        // migrate over the next four rounds.
        type ParentContinuationOwnerKind = | ParentContinuationOwnerKind
        type CrossKindOwnerKind = | CrossKindOwnerKind
        type SidecarDrainOwnerKind = | SidecarDrainOwnerKind
        type DynamicBridgeOwnerKind = | DynamicBridgeOwnerKind
        type PoisonTailOwnerKind = | PoisonTailOwnerKind
        type JoinPointWaitOwnerKind = | JoinPointWaitOwnerKind
        type ProceduralResidualOwnerKind = | ProceduralResidualOwnerKind
        type CicProofObligationOwnerKind = | CicProofObligationOwnerKind

        type OwnerOpenPhase = | OwnerOpenPhase
        type OwnerCloseReadyPhase = | OwnerCloseReadyPhase
        type OwnerClosedPhase = | OwnerClosedPhase
        type OwnerQuarantinedPhase = | OwnerQuarantinedPhase

        [<Struct>]
        type PhantomOwnerId<'GraphKind,'OwnerKind> = private {
            value : string
        }

        [<Struct>]
        type PhantomCloseKey<'GraphKind,'OwnerKind> = private {
            owner : PhantomOwnerId<'GraphKind,'OwnerKind>
            value : string
        }

        let phantomCloseKeyValue (key: PhantomCloseKey<'GraphKind,'OwnerKind>) = key.value

        [<Struct>]
        type ActiveNodeId<'GraphKind> = private {
            value : string
        }

        type SidecarDrainTopologyState<'GraphKind> =
            | PureSidecarDrainAccumulating of facts:int64 * dominant:ActiveNodeId<'GraphKind> option
            | PureSidecarDrainForgivenessReady of facts:int64 * threshold:int64 * dominant:ActiveNodeId<'GraphKind> option
            | SidecarDrainMaterialSemanticDelta of facts:int64 * dominant:ActiveNodeId<'GraphKind> option

        type DynamicRecordKeyBridgeTailState<'GraphKind> =
            | DynamicBridgeTailAbsent
            | DynamicBridgeTailLeased of bridgeId:string * remainingDeferrals:int64 * dominant:ActiveNodeId<'GraphKind> option
            | DynamicBridgeTailExhausted of bridgeId:string * closeKey:string * dominant:ActiveNodeId<'GraphKind> option
            | DynamicBridgeTailQuarantined of bridgeId:string * closeKey:string * remainingOwners:int64

        type PoisonTailOwnerState<'GraphKind> =
            | PoisonTailOwnerAbsent
            | PoisonTailOwnerLive of poisonId:string * dominant:ActiveNodeId<'GraphKind> option
            | PoisonTailOwnerCloseReady of poisonId:string * closeKey:string
            | PoisonTailOwnerClosed of poisonId:string * closeKey:string

        type ProceduralResidualOwnerState<'GraphKind> =
            | ProceduralResidualOwnerAbsent
            | ProceduralResidualOwnerLive of tailId:string * passCount:int64 * pending:int64 * queue:int64 * active:int64 * procedural:int64
            | ProceduralResidualOwnerCloseReady of tailId:string * closeKey:string * passCount:int64 * materialDelta:int64
            | ProceduralResidualOwnerClosed of tailId:string * closeKey:string * receiptId:string
            | ProceduralResidualOwnerFailClosed of tailId:string * reason:CompilerKernelV2.OperationalReasonId

        [<Struct>]
        type CicProofObligationId<'GraphKind> = private { value : uint32 }

        [<Struct>]
        type CicProofWitnessRef<'GraphKind> = private { value : uint32 }

        let cicProofObligationIdFor<'GraphKind> value : CicProofObligationId<'GraphKind> = { value = value }
        let cicProofWitnessRefFor<'GraphKind> value : CicProofWitnessRef<'GraphKind> = { value = value }
        let cicProofWitnessRefValue (witness:CicProofWitnessRef<'GraphKind>) = witness.value

        type CicProofObligationOwnerState<'GraphKind> =
            | CicProofObligationPending of obligation:CicProofObligationId<'GraphKind> * universeEpoch:int64 * defEqPairRef:uint32
            | CicProofObligationWitnessed of obligation:CicProofObligationId<'GraphKind> * witness:CicProofWitnessRef<'GraphKind>
            | CicProofObligationBlocked of obligation:CicProofObligationId<'GraphKind> * blockerRef:uint32
            | CicProofObligationClosed of obligation:CicProofObligationId<'GraphKind> * witness:CicProofWitnessRef<'GraphKind> * closeReceiptRef:uint32

        type TypedOwnerRequiredResolution<'GraphKind,'OwnerKind> =
            | OwnerRequireParentContinuationIvarFill of ParentContinuationCellId<'GraphKind>
            | OwnerRequireCrossKindDrain of obligationId:string
            | OwnerRequireSidecarTopologyCollapse of SidecarDrainTopologyState<'GraphKind>
            | OwnerRequireDynamicBridgeQuarantine of DynamicRecordKeyBridgeTailState<'GraphKind>
            | OwnerRequirePoisonTailClosure of PoisonTailOwnerState<'GraphKind>
            | OwnerRequireJoinPointWake of joinPointId:string
            | OwnerRequireProceduralResidualDrain of ProceduralResidualOwnerState<'GraphKind>
            | OwnerRequireCicProofWitness of CicProofObligationOwnerState<'GraphKind>
            | OwnerRequireNoFurtherAuthorityProof

        type TypedOwnerLease<'GraphKind,'OwnerKind,'Phase> = private {
            owner : PhantomOwnerId<'GraphKind,'OwnerKind>
            closeKey : PhantomCloseKey<'GraphKind,'OwnerKind> option
            lease : LiveGraphConservedCredit<'GraphKind> option
            remaining : int64
            required : TypedOwnerRequiredResolution<'GraphKind,'OwnerKind>
            evidence : string
        }

        type ExistentialOwnerLease<'GraphKind,'OwnerKind> =
            | OwnerLeaseOpen of TypedOwnerLease<'GraphKind,'OwnerKind,OwnerOpenPhase>
            | OwnerLeaseCloseReady of TypedOwnerLease<'GraphKind,'OwnerKind,OwnerCloseReadyPhase>
            | OwnerLeaseClosed of TypedOwnerLease<'GraphKind,'OwnerKind,OwnerClosedPhase>
            | OwnerLeaseQuarantined of TypedOwnerLease<'GraphKind,'OwnerKind,OwnerQuarantinedPhase>

        type RecursiveOwnerLedgerNode<'GraphKind> =
            | ParentContinuationOwnerNode of ExistentialOwnerLease<'GraphKind,ParentContinuationOwnerKind>
            | CrossKindOwnerNode of ExistentialOwnerLease<'GraphKind,CrossKindOwnerKind>
            | SidecarDrainOwnerNode of ExistentialOwnerLease<'GraphKind,SidecarDrainOwnerKind>
            | DynamicBridgeOwnerNode of ExistentialOwnerLease<'GraphKind,DynamicBridgeOwnerKind>
            | PoisonTailOwnerNode of ExistentialOwnerLease<'GraphKind,PoisonTailOwnerKind>
            | JoinPointWaitOwnerNode of ExistentialOwnerLease<'GraphKind,JoinPointWaitOwnerKind>
            | ProceduralResidualOwnerNode of ExistentialOwnerLease<'GraphKind,ProceduralResidualOwnerKind>
            | CicProofObligationOwnerNode of ExistentialOwnerLease<'GraphKind,CicProofObligationOwnerKind>

        type RecursiveOwnerLedger<'GraphKind> =
            | OwnerLedgerEmpty
            | OwnerLedgerCons of head:RecursiveOwnerLedgerNode<'GraphKind> * tail:RecursiveOwnerLedger<'GraphKind>

        // DOMAIN MIGRATION : closure is one typed transaction.  A command
        // carries a close key whose phantom owner kind must match the owner it
        // can mutate.  The heterogeneous union is the existential envelope;
        // individual cases still make a parent key unusable for bridge,
        // sidecar, poison, cross-kind, or join-point owners.
        type EvalWorklistTerminalGraphKind = | EvalWorklistTerminalGraphKind

        type TypedOwnerCloseAction<'GraphKind> =
            | CloseParentContinuationWith of key:PhantomCloseKey<'GraphKind,ParentContinuationOwnerKind> * cellId:ParentContinuationCellId<'GraphKind> * fillReceipt:string
            | CloseCrossKindWith of key:PhantomCloseKey<'GraphKind,CrossKindOwnerKind> * obligationId:string
            | QuarantineSidecarDrainWith of key:PhantomCloseKey<'GraphKind,SidecarDrainOwnerKind> * state:SidecarDrainTopologyState<'GraphKind>
            | QuarantineDynamicBridgeWith of key:PhantomCloseKey<'GraphKind,DynamicBridgeOwnerKind> * state:DynamicRecordKeyBridgeTailState<'GraphKind>
            | ClosePoisonTailWith of key:PhantomCloseKey<'GraphKind,PoisonTailOwnerKind> * state:PoisonTailOwnerState<'GraphKind>
            | QuarantineJoinPointWaitWith of key:PhantomCloseKey<'GraphKind,JoinPointWaitOwnerKind> * joinPointId:string
            | CloseProceduralResidualWith of key:PhantomCloseKey<'GraphKind,ProceduralResidualOwnerKind> * state:ProceduralResidualOwnerState<'GraphKind> * exactOnceReceipt:string
            | CloseCicProofObligationWith of key:PhantomCloseKey<'GraphKind,CicProofObligationOwnerKind> * state:CicProofObligationOwnerState<'GraphKind> * witnessRef:CicProofWitnessRef<'GraphKind>

        type TypedOwnerMutationId<'GraphKind> =
            | ParentContinuationOwnerClosedMutation of PhantomCloseKey<'GraphKind,ParentContinuationOwnerKind>
            | CrossKindOwnerClosedMutation of PhantomCloseKey<'GraphKind,CrossKindOwnerKind>
            | SidecarDrainOwnerQuarantinedMutation of PhantomCloseKey<'GraphKind,SidecarDrainOwnerKind>
            | DynamicBridgeOwnerQuarantinedMutation of PhantomCloseKey<'GraphKind,DynamicBridgeOwnerKind>
            | PoisonTailOwnerClosedMutation of PhantomCloseKey<'GraphKind,PoisonTailOwnerKind>
            | JoinPointWaitOwnerQuarantinedMutation of PhantomCloseKey<'GraphKind,JoinPointWaitOwnerKind>
            | ProceduralResidualOwnerClosedMutation of PhantomCloseKey<'GraphKind,ProceduralResidualOwnerKind>
            | CicProofObligationOwnerClosedMutation of PhantomCloseKey<'GraphKind,CicProofObligationOwnerKind>

        type TypedOwnerTransactionPhaseId =
            | OwnerTransactionPhaseOpen
            | OwnerTransactionPhaseQuarantined
            | OwnerTransactionPhaseTerminalEligible
            | OwnerTransactionPhaseRejected

        type TypedOwnerTransactionReceipt<'GraphKind> = {
            transactionId : string
            beforeLedger : RecursiveOwnerLedger<'GraphKind>
            afterLedger : RecursiveOwnerLedger<'GraphKind>
            mutations : TypedOwnerMutationId<'GraphKind> list
            openBefore : int64
            openAfter : int64
            quarantinedAfter : int64
            phaseAfter : TypedOwnerTransactionPhaseId
            evidence : string
        }

        type TypedOwnerTransactionResult<'GraphKind> =
            | TypedOwnerTransactionRejected of transactionId:string * reason:CompilerKernelV2.OperationalReasonId * ledger:RecursiveOwnerLedger<'GraphKind>
            | TypedOwnerTransactionCommitted of TypedOwnerTransactionReceipt<'GraphKind>

        type ParentContinuationTailTransactionRequest = {
            key : string
            cellId : string
            pending : int64
            queueDepth : int64
            activeDepth : int64
            topologyFacts : int64
            dominantNodeId : string
            sidecarLive : bool
            dynamicBridgeLive : bool
            bridgeDeferrals : int64
            poisonTailLive : bool
            joinPointWaitLive : bool
            fillReceipt : string
        }

        // DOMAIN MIGRATION : exact-once owner drain and semantic sidecar
        // causality.  Topology witnesses are now separated from semantic facts
        // so ConsumerResultNoFurtherDeclared cannot be constructed from a pure
        // topology delta before a semantic receipt or an explicit quarantine.
        type OwnerLedgerAxisId =
            | OwnerAxisParentContinuation
            | OwnerAxisSemanticFactDebt
            | OwnerAxisSidecarDrain
            | OwnerAxisDynamicBridge
            | OwnerAxisCrossKind
            | OwnerAxisPoisonTail
            | OwnerAxisJoinPointWait
            | OwnerAxisProceduralResidual
            | OwnerAxisCicProofObligation

        type OwnerLedgerAxisStageId =
            | OwnerAxisStageOpen
            | OwnerAxisStageClosed
            | OwnerAxisStageDeadlocked
            | OwnerAxisStageQuarantined

        type OwnerLedgerAxisTransition<'GraphKind> = {
            axis : OwnerLedgerAxisId
            beforeStage : OwnerLedgerAxisStageId
            afterStage : OwnerLedgerAxisStageId
            closeKey : string
            ownerId : string
            rowRef : string
            materialDelta : int64
            evidence : string
        }

        type ExactOnceOwnerDrainReceipt<'GraphKind> = private {
            receiptId : string
            beforeLedger : RecursiveOwnerLedger<'GraphKind>
            afterLedger : RecursiveOwnerLedger<'GraphKind>
            ownerOpenBefore : int64
            ownerOpenAfter : int64
            qapBefore : int64 * int64 * int64
            qapAfter : int64 * int64 * int64
            materialDelta : int64
            targetAxis : OwnerLedgerAxisId
            transitions : OwnerLedgerAxisTransition<'GraphKind> list
            semanticFactDebtPaid : bool
            terminalEligibleAfter : bool
        }

        type SidecarDrainCausalityPhase =
            | SidecarTopologyWitnessObserved
            | SidecarSemanticFactRequired
            | SidecarSemanticFactMaterialized
            | SidecarSemanticFactQuarantined

        type StrictSidecarDrainCausality<'GraphKind> = {
            node : ActiveNodeId<'GraphKind> option
            topologyFacts : int64
            semanticFacts : int64
            phase : SidecarDrainCausalityPhase
            missingDependency : string
            waitGraphEdge : string
        }

        // DOMAIN MIGRATION : strict Hopac dataflow spine.  A pure topology
        // witness is not a schedulable terminal consumer input anymore; it is a
        // prerequisite promise that must bind to a semantic sidecar promise before
        // NoFurther, RootComplete or writer capability can observe it.
        type TopologyPromisePhase = interface end
        type SemanticPromisePhase = interface end
        type SemanticSidecarBlockedPhase = interface end
        type SemanticSidecarQuarantinedPhase = interface end

        type SidecarDataflowPromise<'GraphKind,'Phase> = private {
            promiseId : string
            node : ActiveNodeId<'GraphKind> option
            topologyFacts : int64
            semanticFacts : int64
            dependency : string
            waitGraphEdge : string
            receiptId : string option
        }

        type StrictSidecarDataflowBind<'GraphKind,'FromPhase,'ToPhase> = private {
            bindId : string
            prerequisite : SidecarDataflowPromise<'GraphKind,'FromPhase>
            continuation : SidecarDataflowPromise<'GraphKind,'ToPhase>
            hopacBindContract : string
            consumerSchedulable : bool
            noFurtherLegal : bool
        }

        type StrictSidecarDataflowDecision<'GraphKind> =
            | StrictSidecarBindRequired of StrictSidecarDataflowBind<'GraphKind,TopologyPromisePhase,SemanticSidecarBlockedPhase>
            | StrictSidecarBindSatisfied of StrictSidecarDataflowBind<'GraphKind,TopologyPromisePhase,SemanticPromisePhase>
            | StrictSidecarBindQuarantined of StrictSidecarDataflowBind<'GraphKind,TopologyPromisePhase,SemanticSidecarQuarantinedPhase> * reason:CompilerKernelV2.OperationalReasonId
            | StrictSidecarBindIllegalNoFurther of topologyPromise:SidecarDataflowPromise<'GraphKind,TopologyPromisePhase> * reason:CompilerKernelV2.OperationalReasonId

        type TypedTerminalOwnerClosureVerdict<'GraphKind> =
            | TypedTerminalOwnersAllClosed of ledger:RecursiveOwnerLedger<'GraphKind>
            | TypedTerminalOwnersStillOpen of ledger:RecursiveOwnerLedger<'GraphKind> * openAxes:OwnerLedgerAxisId list
            | TypedTerminalOwnersNeedDeadlockResolution of ledger:RecursiveOwnerLedger<'GraphKind> * openAxes:OwnerLedgerAxisId list

        type TerminalOwnerClosureVerdict<'Kind> =
            | TerminalOwnersAllClosed of ledger:RecursiveOwnerLedger<'Kind>
            | TerminalOwnersStillOpen of ledger:RecursiveOwnerLedger<'Kind> * openAxes:OwnerLedgerAxisId list
            | TerminalOwnersNeedDeadlockResolution of ledger:RecursiveOwnerLedger<'Kind> * openAxes:OwnerLedgerAxisId list

        // DOMAIN MIGRATION : recursive owner quorum. Owner closure is no
        // longer a boolean HUD projection.  The terminal path now carries an
        // explicit quorum object with per-axis stages and an optional exact-once
        // drain receipt so RootComplete/TerminalQuorum can decide from typed
        // owner state instead of scattered strings.
        type OwnerLedgerQuorumStateId =
            | OwnerLedgerQuorumOpen
            | OwnerLedgerQuorumClosed
            | OwnerLedgerQuorumDeadlocked
            | OwnerLedgerQuorumQuarantined

        type OwnerLedgerQuorum<'GraphKind> = private {
            quorumId : string
            ledger : RecursiveOwnerLedger<'GraphKind>
            openOwnerCount : int64
            closedOwnerCount : int64
            quarantinedOwnerCount : int64
            openAxes : OwnerLedgerAxisId list
            closedAxes : OwnerLedgerAxisId list
            quarantinedAxes : OwnerLedgerAxisId list
            transitions : OwnerLedgerAxisTransition<'GraphKind> list
            receiptId : string option
            materialDelta : int64
            semanticFactDebtPaid : bool
            terminalEligible : bool
            state : OwnerLedgerQuorumStateId
            decision : string
        }

        type TerminalQuorumDecision<'GraphKind> =
            | TerminalQuorumEligible of OwnerLedgerQuorum<'GraphKind>
            | TerminalQuorumBlockedByOpenOwners of OwnerLedgerQuorum<'GraphKind>
            | TerminalQuorumDeadlockedByOwnerLedger of OwnerLedgerQuorum<'GraphKind>
            | TerminalQuorumQuarantinedByOwnerLedger of OwnerLedgerQuorum<'GraphKind>

        // DOMAIN MIGRATION : writer/root terminal seal.  BuildOk is no
        // longer a projection of a loose artifact manifest plus a resolved
        // root string.  The writer boundary must name the exact authority chain:
        // RootComplete resolution, owner-ledger quorum, strict sidecar dataflow,
        // exhausted WorkDag and authorized artifact hash.
        type WorkDagTerminalSealStateId =
            | WorkDagTerminalSealExhausted of workDagHash:string
            | WorkDagTerminalSealBlocked of blocker:string
            | WorkDagTerminalSealUnknown of reason:CompilerKernelV2.OperationalReasonId

        type WriterRootSealOwnerStateId =
            | WriterRootSealOwnersClosed
            | WriterRootSealOwnersQuarantined of reason:CompilerKernelV2.OperationalReasonId
            | WriterRootSealOwnersOpen of openAxes:OwnerLedgerAxisId list

        type WriterRootSealSemanticStateId =
            | WriterRootSealSemanticBound of receiptId:string
            | WriterRootSealSemanticQuarantined of reason:CompilerKernelV2.OperationalReasonId
            | WriterRootSealSemanticMissing of dependency:string

        type WriterRootBuildOkSeal<'GraphKind> = private {
            sealId : string
            rootPromiseTransition : RootPromiseTransitionId
            terminalQuorum : TerminalQuorumDecision<'GraphKind>
            ownerState : WriterRootSealOwnerStateId
            semanticState : WriterRootSealSemanticStateId
            workDagState : WorkDagTerminalSealStateId
            artifactSetHash : string
            writerCapabilityDu : string
            contentHashAuthorized : bool
        }

        type WriterRootBuildOkSealDecision<'GraphKind> =
            | WriterRootBuildOkSealAccepted of WriterRootBuildOkSeal<'GraphKind>
            | WriterRootBuildOkSealRejected of WriterRootBuildOkSeal<'GraphKind> * reason:CompilerKernelV2.OperationalReasonId

        // DOMAIN MIGRATION round : owner-axis exact-once migration.  This
        // turns the hairy assessment demand into a typed graph: an owner axis
        // can be open, closed, deadlocked, or quarantined, and every drain must
        // either reduce an axis, pay a semantic receipt, or expire to a named
        // deadlock/quarantine proof.  A pure topology RealDelta is observability
        // until a stasis seal names the axis it is paying.
        type OwnerOpenState = interface end
        type OwnerClosedState = interface end
        type OwnerDeadlockedState = interface end
        type OwnerQuarantinedState = interface end

        type OwnerAxisLease<'GraphKind> = private {
            leaseId : string
            ownerId : string
            axis : OwnerLedgerAxisId
            materialEpoch : int64
            expiryLine : int64
            rowRef : string
        }

        type OwnerAxisNode<'GraphKind,'State> = private {
            axis : OwnerLedgerAxisId
            ownerId : string
            closeKey : string
            lease : OwnerAxisLease<'GraphKind>
            receiptId : string option
            evidence : string
        }

        type OwnerAxisExactOnceReceipt<'GraphKind> = private {
            receiptId : string
            axis : OwnerLedgerAxisId
            closeKey : string
            before : OwnerAxisNode<'GraphKind,OwnerOpenState> option
            afterClosed : OwnerAxisNode<'GraphKind,OwnerClosedState> option
            afterDeadlocked : OwnerAxisNode<'GraphKind,OwnerDeadlockedState> option
            afterQuarantined : OwnerAxisNode<'GraphKind,OwnerQuarantinedState> option
            materialEpochBefore : int64
            materialEpochAfter : int64
            qapBefore : int64 * int64 * int64
            qapAfter : int64 * int64 * int64
            semanticReceiptId : string option
            rootTransitionBefore : RootPromiseTransitionId option
            rootTransitionAfter : RootPromiseTransitionId option
        }

        type OwnerAxisDrainDecision<'GraphKind> =
            | OwnerAxisReduced of OwnerAxisExactOnceReceipt<'GraphKind>
            | OwnerAxisClosed of OwnerAxisExactOnceReceipt<'GraphKind>
            | OwnerAxisSemanticDebtPaid of OwnerAxisExactOnceReceipt<'GraphKind> * remaining:OwnerLedgerAxisId list
            | OwnerAxisZeroDeltaStillOpen of axis:OwnerLedgerAxisId * lease:OwnerAxisLease<'GraphKind> * reason:CompilerKernelV2.OperationalReasonId
            | OwnerAxisExpiredToDeadlock of OwnerAxisExactOnceReceipt<'GraphKind> * proof:CompilerKernelV2.OperationalReasonId
            | OwnerAxisQuarantined of OwnerAxisExactOnceReceipt<'GraphKind> * reason:CompilerKernelV2.OperationalReasonId

        // DOMAIN MIGRATION round : drain receipts are now consumed by a
        // monotonic axis-local root transition.  Telemetry may render this as
        // JSON, but scheduler authority is modeled as a receipt index, a
        // wait-graph arm token, and a writer-capability handoff contract.
        // This makes the formerly stringy owner-debt loop act like a typed
        // state machine: an axis either shrinks, closes, expires, quarantines,
        // or remains open with the exact lease that must wake next.
        type OwnerAxisReceiptIndex<'GraphKind> = private {
            receiptId : string
            axis : OwnerLedgerAxisId
            closeKey : string
            leaseId : string
            rowRef : string
            beforeEpoch : int64
            afterEpoch : int64
            beforeOpenCount : int64
            afterOpenCount : int64
            consumedByRoot : bool
        }

        type OwnerAxisDrainMonotonicity =
            | OwnerAxisMonotonicReduced of beforeOpen:int64 * afterOpen:int64
            | OwnerAxisMonotonicClosed of receiptId:string
            | OwnerAxisMonotonicExpired of proof:CompilerKernelV2.OperationalReasonId
            | OwnerAxisMonotonicQuarantined of reason:CompilerKernelV2.OperationalReasonId
            | OwnerAxisMonotonicRejected of beforeOpen:int64 * afterOpen:int64 * reason:CompilerKernelV2.OperationalReasonId

        type SemanticSidecarWakerRegistration<'GraphKind> = private {
            wakerEdgeId : string
            waiterAxis : OwnerLedgerAxisId
            topologyEpochHash : string
            semanticReceiptId : string option
            ivarRegistered : bool
            writerCapability : string option
            qapDepthAtArm : int64
        }

        type RootWriterCapabilityHandoff<'GraphKind> = private {
            handoffId : string
            rootBefore : RootPromiseTransitionId
            rootAfter : RootPromiseTransitionId
            ownerReceipt : OwnerAxisReceiptIndex<'GraphKind>
            semanticWaker : SemanticSidecarWakerRegistration<'GraphKind> option
            writerReady : bool
            failClosedIfWriterMissingAfterMs : int64
        }

        type PureSidecarTopologyStasisSeal<'GraphKind> = private {
            sealId : string
            topologyEpochHash : string
            sameTopologyRepeatCount : int64
            threshold : int64
            topologyFacts : int64
            materialDelta : int64
            ownerAxis : OwnerLedgerAxisId
            semanticReceiptId : string
            debtPaymentAllowed : bool
        }

        type RootOwnerAxisTransition<'GraphKind> =
            | RootKeepWaitingOnAxis of axis:OwnerLedgerAxisId * reason:CompilerKernelV2.OperationalReasonId
            | RootResolveAfterAxisReceipt of OwnerAxisExactOnceReceipt<'GraphKind>
            | RootFailClosedAfterAxisDeadlock of OwnerAxisExactOnceReceipt<'GraphKind>
            | RootQuarantineAfterAxisStasis of PureSidecarTopologyStasisSeal<'GraphKind>

        let private ownerAxisStageText = function
            | OwnerAxisStageOpen -> "open"
            | OwnerAxisStageClosed -> "closed"
            | OwnerAxisStageDeadlocked -> "deadlocked"
            | OwnerAxisStageQuarantined -> "quarantined"

        let private ownerAxisIdText = function
            | OwnerAxisParentContinuation -> "parent_continuation"
            | OwnerAxisSemanticFactDebt -> "semantic_fact_debt"
            | OwnerAxisSidecarDrain -> "sidecar_drain"
            | OwnerAxisDynamicBridge -> "dynamic_bridge"
            | OwnerAxisCrossKind -> "cross_kind"
            | OwnerAxisPoisonTail -> "poison_tail"
            | OwnerAxisJoinPointWait -> "join_point_wait"
            | OwnerAxisProceduralResidual -> "procedural_residual"
            | OwnerAxisCicProofObligation -> "cic_proof_obligation"

        let private topologyStasisSealText (seal:PureSidecarTopologyStasisSeal<'GraphKind>) =
            "PureSidecarTopologyStasisSeal(id=" + seal.sealId
            + "|epoch=" + seal.topologyEpochHash
            + "|repeat=" + string seal.sameTopologyRepeatCount
            + "|threshold=" + string seal.threshold
            + "|facts=" + string seal.topologyFacts
            + "|material_delta=" + string seal.materialDelta
            + "|axis=" + ownerAxisIdText seal.ownerAxis
            + "|semantic_receipt=" + seal.semanticReceiptId
            + "|debt_payment_allowed=" + string seal.debtPaymentAllowed + ")"

        let private ownerAxisDrainMonotonicityText = function
            | OwnerAxisMonotonicReduced(beforeOpen, afterOpen) -> "OwnerAxisMonotonicity(Reduced|before=" + string beforeOpen + "|after=" + string afterOpen + ")"
            | OwnerAxisMonotonicClosed receiptId -> "OwnerAxisMonotonicity(Closed|receipt=" + receiptId + ")"
            | OwnerAxisMonotonicExpired proof -> "OwnerAxisMonotonicity(Expired|proof=" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | OwnerAxisMonotonicQuarantined reason -> "OwnerAxisMonotonicity(Quarantined|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | OwnerAxisMonotonicRejected(beforeOpen, afterOpen, reason) -> "OwnerAxisMonotonicity(Rejected|before=" + string beforeOpen + "|after=" + string afterOpen + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let private semanticSidecarWakerRegistrationText (waker:SemanticSidecarWakerRegistration<'GraphKind>) =
            "SemanticSidecarWakerRegistration(edge=" + waker.wakerEdgeId
            + "|axis=" + ownerAxisIdText waker.waiterAxis
            + "|epoch=" + waker.topologyEpochHash
            + "|semantic_receipt=" + (waker.semanticReceiptId |> Option.defaultValue "none")
            + "|ivar_registered=" + string waker.ivarRegistered
            + "|writer=" + (waker.writerCapability |> Option.defaultValue "pending")
            + "|qap_depth=" + string waker.qapDepthAtArm + ")"

        // DOMAIN MIGRATION round : break the HUD authority boundary.  From
        // here the root/writer path is modeled as scheduler-owned values:
        // the renderer may stringify receipts, but it cannot authorize a root
        // transition.  This is intentionally stricter than prior rounds: a
        // root transition consumes a receipt index exactly once, validates the
        // owner-axis lease epoch, registers the semantic waker before waiting,
        // and either produces writer capability or emits a typed fail-closed
        // exit.  Observer rows are snapshots, never authority.
        type OwnerAxisReceiptConsumptionState =
            | OwnerAxisReceiptUnconsumed
            | OwnerAxisReceiptConsumedByRoot of rootTransition:string
            | OwnerAxisReceiptConsumedByWriter of writerCapability:string
            | OwnerAxisReceiptRejectedByEpoch of beforeEpoch:int64 * afterEpoch:int64 * reason:CompilerKernelV2.OperationalReasonId
            | OwnerAxisReceiptRejectedByLease of leaseId:string * reason:CompilerKernelV2.OperationalReasonId

        type OwnerAxisAuthorityBoundary<'GraphKind> = private {
            boundaryId : string
            axis : OwnerLedgerAxisId
            receipt : OwnerAxisReceiptIndex<'GraphKind>
            consumptionState : OwnerAxisReceiptConsumptionState
            monotonicity : OwnerAxisDrainMonotonicity
            rendererMayObserve : bool
            schedulerOwnsTransition : bool
        }

        type OwnerDrainAuthorityViolation =
            | OwnerDrainWouldIncreaseOpenCount of beforeOpen:int64 * afterOpen:int64
            | OwnerDrainWouldReopenTerminalEligible of receiptId:string
            | OwnerDrainWouldUseTopologyWithoutStasisSeal of epochHash:string * repeatCount:int64
            | OwnerDrainWouldResolveRootWithoutWriterCapability of root:string
            | OwnerDrainWouldWaitWithoutRegisteredWaker of edgeId:string
            | OwnerDrainRendererTriedToAuthorize of rowRef:string

        type RootWriterHandoffInstruction<'GraphKind> =
            | RootWriterConsumeAxisReceipt of OwnerAxisAuthorityBoundary<'GraphKind>
            | RootWriterAwaitRegisteredWaker of SemanticSidecarWakerRegistration<'GraphKind>
            | RootWriterMintCapabilityAfterRootResolved of RootWriterCapabilityHandoff<'GraphKind>
            | RootWriterFailClosedAfterViolation of OwnerDrainAuthorityViolation
            | RootWriterQuarantineTopologyStasis of PureSidecarTopologyStasisSeal<'GraphKind>

        type OwnerLedgerRecursive<'GraphKind> =
            | OwnerLedgerAxisLeaf of OwnerAxisAuthorityBoundary<'GraphKind>
            | OwnerLedgerAxisJoin of OwnerLedgerRecursive<'GraphKind> list
            | OwnerLedgerAxisQuorum of required:int * children:OwnerLedgerRecursive<'GraphKind> list
            | OwnerLedgerAxisErasedForJson of digest:string

        type SchedulerOwnedRootTransition<'GraphKind> =
            | SchedulerRootKeepWaiting of OwnerLedgerRecursive<'GraphKind> * blocker:OwnerLedgerAxisId
            | SchedulerRootResolveAfterReceiptConsumption of RootWriterHandoffInstruction<'GraphKind>
            | SchedulerRootCommitAfterWriterCapability of RootWriterCapabilityHandoff<'GraphKind>
            | SchedulerRootFailClosedAfterOwnerDeadlock of OwnerDrainAuthorityViolation * terminalReceiptId:string

        // DOMAIN MIGRATION round : terminal/root/writer authority is now
        // moved behind scheduler-owned receipts.  A BuildErrorTrace, terminal
        // commit row, or RootCompleteAlt row is only an observation until this
        // gate produces a TerminalRootReceiptGate and a WriterCommitReceipt.
        // This deliberately breaks the old path where the HUD/root string could
        // imply success or failure without a writer-owned commit decision.
        type TerminalRootReceiptKind =
            | TerminalRootReceiptBuildOk
            | TerminalRootReceiptBuildErrorTrace
            | TerminalRootReceiptNoFurther
            | TerminalRootReceiptOwnerDeadlock
            | TerminalRootReceiptCpuDeadman
            | TerminalRootReceiptQuarantine

        type RootCompleteAltAuthority<'GraphKind> = private {
            altId : string
            transition : SchedulerOwnedRootTransition<'GraphKind>
            rootReceiptId : string
            receiptKind : TerminalRootReceiptKind
            writerCapabilityRequired : bool
            buildErrorTraceId : string option
            ownerAxisBlocker : OwnerLedgerAxisId option
            qapAtAlt : int64 * int64 * int64
            observerRowsSuppressed : int64
        }

        type TerminalRootReceiptGate<'GraphKind> = private {
            gateId : string
            altAuthority : RootCompleteAltAuthority<'GraphKind>
            receiptConsumedByRoot : bool
            receiptConsumedByWriter : bool
            terminalCommitAllowed : bool
            failClosedIfMissingWriterAfterMs : int64
        }

        type WriterCommitReceipt<'GraphKind> = private {
            commitReceiptId : string
            rootGate : TerminalRootReceiptGate<'GraphKind>
            artifactHash : string option
            writerCapability : string option
            buildOkAllowed : bool
            exitCode : int option
        }

        type BuildErrorTraceAuthority<'GraphKind> = private {
            traceId : string
            compactCode : string
            terminalGate : TerminalRootReceiptGate<'GraphKind> option
            rawConsoleSuppressed : bool
            rootFailureOwnedByScheduler : bool
            terminalReceiptDurableBeforeExit : bool
        }

        type BuildErrorTraceLineId =
            | BuildErrorTraceSiteLine of moduleTail:string
            | BuildErrorTraceOtherLine

        let buildErrorTraceLineId (line:string) =
            let marker = "Error trace on line:"
            if System.String.IsNullOrEmpty line
               || line.Length < marker.Length
               || not (System.String.Equals(line.Substring(0, marker.Length), marker, System.StringComparison.Ordinal)) then
                BuildErrorTraceOtherLine
            else
                let moduleMarker = "in module:"
                let parts = line.Split([| moduleMarker |], 2, System.StringSplitOptions.None)
                if parts.Length <> 2 then BuildErrorTraceOtherLine
                else
                    let rawTail = parts.[1].Trim()
                    let moduleTail =
                        if rawTail.Length > 0 && rawTail.[rawTail.Length - 1] = '.' then
                            rawTail.Substring(0, rawTail.Length - 1).TrimEnd()
                        else rawTail
                    if System.String.IsNullOrWhiteSpace moduleTail then BuildErrorTraceOtherLine
                    else BuildErrorTraceSiteLine moduleTail

        type SpiralDiagnosticCodeProjectionId =
            | SpiralDiagnosticCodePrefixed of code:string
            | SpiralDiagnosticCodeRaw of code:string

        let spiralDiagnosticCodeProjectionFor (code:string) =
            let safe = if System.Object.ReferenceEquals(code, null) then "" else code
            let prefix = "[spiral_compiler]"
            if safe.Length >= prefix.Length
               && System.String.Equals(safe.Substring(0, prefix.Length), prefix, System.StringComparison.Ordinal) then
                SpiralDiagnosticCodePrefixed (safe.Substring(prefix.Length).TrimStart())
            else
                SpiralDiagnosticCodeRaw safe

        let spiralDiagnosticCodeProjectionText = function
            | SpiralDiagnosticCodePrefixed code
            | SpiralDiagnosticCodeRaw code -> code

        // DOMAIN MIGRATION round  (second destructive migration): post-root
        // terminalization is a separate typed phase.  Once RootComplete is
        // resolved, owner-debt authority is consumed and demoted into a bounded
        // WriterCapabilityLease over the remaining WorkDag tail.  The old
        // schedule_parent_poison loop is illegal in this phase: the tail must
        // drain, quarantine, deadlock, or mint a writer receipt exactly once.
        type RootPendingStage = interface end
        type RootResolvedStage = interface end
        type WriterPendingStage = interface end
        type WriterBoundStage = interface end
        type WriterDeadlockedStage = interface end
        type WriterQuarantinedStage = interface end
        type TerminalEmittedStage = interface end

        type PostRootTailKind =
            | PostRootCrossKindTail
            | PostRootParentPoisonTail
            | PostRootSidecarDrainTail
            | PostRootParentContinuationTail
            | PostRootDynamicBridgeTail
            | PostRootJoinPointTail
            | PostRootArtifactWriterTail

        type RootResolvedReceipt<'GraphKind> = private {
            receiptId : string
            semanticReceiptId : string option
            transition : SchedulerOwnedRootTransition<'GraphKind>
            qapAtResolution : int * int * int
            sourceRowRef : string
            resolvedAtLine : int64
        }

        type WriterCapabilityLease<'GraphKind> = private {
            leaseId : string
            rootReceipt : RootResolvedReceipt<'GraphKind>
            owner : string
            startedAtLine : int64
            expiresAfterMs : int64
            repeatCap : int64
        }

        type WorkDagTail<'GraphKind,'Stage> = private {
            tailId : string
            kind : PostRootTailKind
            ownerId : string
            obligationId : string
            waitGraphEdgeId : string
            qap : int * int * int
            repeatCount : int64
            materialEpoch : int64
            proof : string
        }

        type WriterCapabilityState<'GraphKind,'Stage> = private {
            rootReceipt : RootResolvedReceipt<'GraphKind>
            lease : WriterCapabilityLease<'GraphKind>
            tail : WorkDagTail<'GraphKind,'Stage>
            writerReceiptId : string option
            terminalReceiptId : string option
        }

        type TerminalAfterRoot<'GraphKind> =
            | TerminalAfterRootKeepDraining of WriterCapabilityState<'GraphKind,WriterPendingStage>
            | TerminalAfterRootEmitSuccess of WriterCapabilityState<'GraphKind,WriterBoundStage>
            | TerminalAfterRootEmitBuildError of WriterCapabilityState<'GraphKind,WriterDeadlockedStage>
            | TerminalAfterRootEmitNoFurther of WriterCapabilityState<'GraphKind,WriterQuarantinedStage>

        type PostRootAuthorityViolation =
            | PostRootOwnerDrainReopenedRoot of receiptId:string
            | PostRootWriterLeaseExpiredWithoutDecision of leaseId:string * tailId:string
            | PostRootCrossKindTailRepeatCapExceeded of tailId:string * repeatCount:int64 * repeatCap:int64
            | PostRootDeadmanMissingTerminalReceipt of leaseId:string
            | PostRootRendererTriedToMutateTerminalFlow of rowRef:string
            | PostRootTailLostWriterCapability of tailId:string * waitGraphEdgeId:string
            | PostRootMaterializedTerminalHandoffObserverOnlyExhausted of leaseId:string * tailId:string * payload:string * noWorkS:int64
            | PostRootFrontierZeroStalePendingCacheClosed of leaseId:string * tailId:string * rawPending:int64 * frontPending:int64
            | PostRootEmptyOwnerLedgerBlockedByOpenQuorum of leaseId:string * tailId:string
            | PostRootWriterLeaseObservedButNotOwned of leaseId:string * observerRow:string
            | PostRootOwnerDebtRowAfterRootResolved of receiptId:string * demotedToTailId:string

        // MIGRATION / migration migration phase: post-root is no longer a
        // rendered extension of owner debt.  The root has already resolved;
        // remaining obligations are writer leases and WorkDag tail leases.
        // These values are the type-level runway for replacing every
        // schedule_parent_poison... tail after RootPromiseResolved with an
        // exact terminal flow: bind writer, keep draining under a lease,
        // quarantine, or emit a typed fail-closed receipt.
        type WriterCapabilityLeaseStatus =
            | WriterLeaseLive of leaseId:string * ageMs:int64 * expiresAfterMs:int64
            | WriterLeaseBound of leaseId:string * writerReceiptId:string
            | WriterLeaseExpired of leaseId:string * ageMs:int64 * expiresAfterMs:int64
            | WriterLeaseQuarantined of leaseId:string * reason:CompilerKernelV2.OperationalReasonId

        type WorkDagTailLease<'GraphKind,'Stage> = private {
            tailLeaseId : string
            writerLeaseId : string
            tail : WorkDagTail<'GraphKind,'Stage>
            qapBefore : int * int * int
            qapAfter : int * int * int
            materialDelta : int
            repeatCap : int64
            expiresAfterMs : int64
        }

        type PostRootTerminalizationGate<'GraphKind> =
            | PostRootGateKeepDraining of lease:WriterCapabilityLease<'GraphKind> * tail:WorkDagTail<'GraphKind,WriterPendingStage>
            | PostRootGateBindWriter of state:WriterCapabilityState<'GraphKind,WriterBoundStage> * writerReceiptId:string
            | PostRootGateEmitDeadlock of state:WriterCapabilityState<'GraphKind,WriterDeadlockedStage> * violation:PostRootAuthorityViolation
            | PostRootGateEmitQuarantine of state:WriterCapabilityState<'GraphKind,WriterQuarantinedStage> * proof:CompilerKernelV2.TerminalTailQuarantineReasonId

        type PostRootSchedulerDecision<'GraphKind> =
            | PostRootDemoteOwnerDrainToWriterTail of WriterCapabilityState<'GraphKind,WriterPendingStage>
            | PostRootBindWriterAfterTailDrained of WriterCapabilityState<'GraphKind,WriterBoundStage>
            | PostRootDeadlockTailAfterLeaseExpiry of WriterCapabilityState<'GraphKind,WriterDeadlockedStage> * PostRootAuthorityViolation
            | PostRootQuarantineTailAfterStasis of WriterCapabilityState<'GraphKind,WriterQuarantinedStage> * proof:CompilerKernelV2.TerminalTailQuarantineReasonId
            | PostRootBindWriterLeaseToTerminalGate of PostRootTerminalizationGate<'GraphKind>
            | PostRootExpireWriterLeaseToTerminalReceipt of WriterCapabilityLease<'GraphKind> * WorkDagTail<'GraphKind,WriterPendingStage> * PostRootAuthorityViolation
            | PostRootEmitTerminal of TerminalAfterRoot<'GraphKind>

        // MIGRATION / migration migration phase: post-root terminalization stops
        // being advisory.  A writer-bound or expired writer lease must produce a
        // physical terminal emission contract and either exit-0 with a writer
        // commit receipt or fail-closed with a named workdag-tail proof.  Owner
        // debt rows after RootPromiseResolved are quarantined as legacy renderer
        // rows and may only render a demotion receipt, never mutate root again.
        type PostRootTerminalFlowState =
            | PostRootFlowBeforeWriter
            | PostRootFlowWriterLeaseLive
            | PostRootFlowWriterBound
            | PostRootFlowTailDeadlocked
            | PostRootFlowTailQuarantined
            | PostRootFlowTerminalEmitted

        // MIGRATION / destructive domain migration migration phase:
        // create the stricter TerminalFlow runway requested by the assessments.
        // This deliberately mirrors a GADT by phantom stage parameters.  A
        // renderer may erase these values to JSON/HUD strings, but terminal
        // decisions must move through these constructors rather than through
        // string Contains checks or an imperative "is QAP empty yet?" loop.
        type TerminalFlowRootPendingStage = interface end
        type TerminalFlowRootResolvedStage = interface end
        type TerminalFlowWriterPendingStage = interface end
        type TerminalFlowWriterBoundStage = interface end
        type TerminalFlowTailDeadlockedStage = interface end
        type TerminalFlowTailQuarantinedStage = interface end
        type TerminalFlowEmittedStage = interface end

        type TerminalFlowRootReceipt<'GraphKind,'Stage> = private {
            terminalFlowRootReceiptId : string
            semanticReceiptId : string option
            qapSnapshot : int * int * int
            ownerLedgerClosed : bool
        }

        type TerminalFlowTail<'GraphKind,'Stage> = private {
            terminalFlowTailId : string
            writerLeaseId : string
            blocker : string option
            qapSnapshot : int * int * int
            repeatCount : int64
        }

        type TerminalFlow<'GraphKind,'Stage> =
            | TerminalFlowBeforeRoot of TerminalFlowRootReceipt<'GraphKind,TerminalFlowRootPendingStage>
            | TerminalFlowAfterRoot of TerminalFlowRootReceipt<'GraphKind,TerminalFlowRootResolvedStage> * TerminalFlowTail<'GraphKind,TerminalFlowWriterPendingStage>
            | TerminalFlowWriterBound of TerminalFlowRootReceipt<'GraphKind,TerminalFlowRootResolvedStage> * TerminalFlowTail<'GraphKind,TerminalFlowWriterBoundStage> * writerReceiptId:string
            | TerminalFlowTailDeadlocked of TerminalFlowRootReceipt<'GraphKind,TerminalFlowRootResolvedStage> * TerminalFlowTail<'GraphKind,TerminalFlowTailDeadlockedStage> * proof:CompilerKernelV2.TerminalTailDeadlockProofId
            | TerminalFlowTailQuarantined of TerminalFlowRootReceipt<'GraphKind,TerminalFlowRootResolvedStage> * TerminalFlowTail<'GraphKind,TerminalFlowTailQuarantinedStage> * reason:CompilerKernelV2.TerminalTailQuarantineReasonId
            | TerminalFlowEmitted of terminalReceiptId:string

        type TerminalFlowExitGate<'GraphKind,'Stage> = private {
            flow : TerminalFlow<'GraphKind,'Stage>
            writerAltStatus : string
            qapResidualJobIds : string list
            terminalEmitBlocker : string option
        }

        // MIGRATION / destructive domain migration migration phase:
        // make the post-root terminal gate reason over typed observations, not
        // over scattered HUD strings.  DiagJson/HUD parsing is intentionally
        // quarantined to one adapter; every scheduler predicate below consumes
        // these DUs.  This is still an F# phantom/GADT simulation, but now the
        // runtime decision surface mirrors the assessment's TerminalFlow shape:
        // RootResolved -> WriterPending -> WriterBound | TailDeadlocked |
        // TailQuarantined | TerminalEmitted.
        type TerminalFlowRootObservationId =
            | TerminalFlowRootNotObserved
            | TerminalFlowRootPending
            | TerminalFlowRootResolved of receiptId:string
            | TerminalFlowRootResolvedWithoutReceipt of evidence:string

        type TerminalFlowWriterObservationId =
            | TerminalFlowWriterNotObserved
            | TerminalFlowWriterPending of leaseId:string
            | TerminalFlowWriterBlockedOnQap of leaseId:string
            | TerminalFlowWriterBoundObserved of writerReceiptId:string

        type TerminalFlowTailObservationId =
            | TerminalFlowTailUnknown
            | TerminalFlowTailPendingDrain of tailId:string
            | TerminalFlowTailDrained of tailId:string
            | TerminalFlowTailDeadlockedObserved of tailId:string * proof:CompilerKernelV2.TerminalTailDeadlockProofId
            | TerminalFlowTailQuarantinedObserved of tailId:string * reason:CompilerKernelV2.TerminalTailQuarantineReasonId
            | TerminalFlowTailTerminalEmittedObserved of receiptId:string

        type TerminalFlowOwnerObservationId =
            | TerminalFlowOwnersUnknown
            | TerminalFlowOwnersOpen of openCount:int64
            | TerminalFlowOwnersQuarantinable of openCount:int64 * reason:CompilerKernelV2.TerminalOwnerQuarantineReasonId
            | TerminalFlowOwnersWakerRegistrationRequired of openCount:int64 * obligationId:string
            | TerminalFlowOwnersWakerRegistrationRejected of openCount:int64 * obligationId:string * reason:CompilerKernelV2.TerminalOwnerWakerRejectionReasonId
            | TerminalFlowOwnersClosed
            | TerminalFlowOwnersStickyTerminalEligible

        // Semantic ledger state is projected from the single file-global
        // authority; terminal kernels do not own mutable ledger copies.

        type TerminalFlowQapBoundedness =
            | TerminalFlowQapBounded
            | TerminalFlowQapUnbounded

        type TerminalFlowQapOccupancy =
            | TerminalFlowQapEmpty
            | TerminalFlowQapResidual

        // Domain migration : pending is no longer an anonymous integer.  The
        // frontier snapshot owns terminal truth; sampled cache depth is evidence
        // only and may be reconciled away as a ghost without keeping QAP open.
        type TerminalFlowPendingLedgerAuthority =
            | TerminalFlowPendingFrontierAuthoritative
            | TerminalFlowPendingFrontierReconciledGhosts
            | TerminalFlowPendingFrontierUnavailableRawZeroClosed of closeReceiptRef:uint32
            | TerminalFlowPendingFrontierUnavailableReducerClosed of closeReceiptRef:uint32
            | TerminalFlowPendingFrontierUnavailableQuarantine of quarantineRef:uint32

        // Domain migration : sampled-pending decrements become exact-once
        // receipts.  Raw cache depth may explain ghosts, but only the frontier
        // count can decide terminal closure.
        type TerminalFlowPendingDecrementSource =
            | TerminalFlowPendingDecrementInlineCallbackCommit
            | TerminalFlowPendingDecrementReducerFrontierReconcile
            | TerminalFlowPendingDecrementReducerClosedProjection
            | TerminalFlowPendingDecrementParentCommit
            | TerminalFlowPendingDecrementUnknown of raw:string

        type TerminalFlowPendingDecrementReceipt = private {
            source : TerminalFlowPendingDecrementSource
            beforeRaw : int
            afterRaw : int
            frontierPending : int
            canonicalPending : int
            exactOnceRef : uint32
        }

        type TerminalFlowPendingQuarantineReason =
            | TerminalFlowPendingRejectedSyntheticObservation
            | TerminalFlowPendingFrontierSnapshotMissing

        type TerminalFlowPendingDecision =
            | TerminalFlowPendingDecisionFrontierCanonical of canonicalPending:int
            | TerminalFlowPendingDecisionRawZeroClosedWithoutFrontier of closeReceiptRef:uint32
            | TerminalFlowPendingDecisionReducerClosedWithoutFrontier of closeReceiptRef:uint32
            | TerminalFlowPendingDecisionBlockedWithoutFrontier of sampledEvidence:int * reason:TerminalFlowPendingQuarantineReason * quarantineRef:uint32

        type TerminalFlowPendingClosureProof =
            | TerminalFlowPendingClosureUnproven
            | TerminalFlowPendingClosureReducerExact of closeReceiptRef:uint32

        type TerminalFlowPendingProvenance = private {
            rawPending : int
            frontierPending : int
            canonicalPending : int
            authority : TerminalFlowPendingLedgerAuthority
            decrementReceipts : TerminalFlowPendingDecrementReceipt list
            decision : TerminalFlowPendingDecision
        }

        type TerminalFlowQapFixpointMaturity =
            | TerminalFlowQapFixpointAwaitingReducerWitness
            | TerminalFlowQapFixpointCandidateObserved
            | TerminalFlowQapFixpointWitnessedByReducer

        type TerminalFlowQapObservation = private {
            pending : int
            pendingProvenance : TerminalFlowPendingProvenance
            queue : int
            active : int
            semanticLedgerState : SemanticWorkOpenState
            semanticOpen : int64
            boundedness : TerminalFlowQapBoundedness
            occupancy : TerminalFlowQapOccupancy
        }

        // Projection identity is typed separately from human rendering.
        // QAP replay is no longer modelled as anonymous procedural churn.  The
        // recurring cache_handoff children that kept the terminal gate alive are
        // captured as a typed fixpoint set with its own identity kind, maturity
        // witness and terminal decision.  Renderers may erase this to strings,
        // but scheduler logic now has a domain object for bounded residual QAP.
        [<AbstractClass; Sealed>]
        type TerminalFlowQapFixpointItemRefKind private () =
            static member InternedKindTag () = 0x190001u

        [<AbstractClass; Sealed>]
        type TerminalFlowQapFixpointSetRefKind private () =
            static member InternedKindTag () = 0x190002u

        type TerminalFlowQapFixpointRef<'Kind> =
            private
            | TerminalFlowQapFixpointRef of CompilerIdentityKernel.InternedTextId<'Kind>

        let inline private terminalFlowQapFixpointRefCreate< ^Kind when ^Kind : (static member InternedKindTag : unit -> uint32)> value : TerminalFlowQapFixpointRef< ^Kind> =
            value
            |> CompilerIdentityKernel.InternedTextId.create< ^Kind>
            |> TerminalFlowQapFixpointRef

        type TerminalFlowQapUnknownTextKind private () =
            static member InternedKindTag () = 0x130001u

        type TerminalFlowQapUnknownTextId =
            CompilerIdentityKernel.InternedTextId<TerminalFlowQapUnknownTextKind>

        module TerminalFlowQapUnknownTextIdOps =
            let create value : TerminalFlowQapUnknownTextId =
                CompilerIdentityKernel.InternedTextId.create<TerminalFlowQapUnknownTextKind> value

            let text (value:TerminalFlowQapUnknownTextId) =
                CompilerIdentityKernel.InternedTextId.text value

        type TerminalFlowQapFixpointSiteId =
            | TerminalFlowQapCacheHandoffApplyArg0Child
            | TerminalFlowQapParentContinuationPoison
            | TerminalFlowQapDynamicBridgePoison
            | TerminalFlowQapPendingOwner
            | TerminalFlowQapUnknownSite of raw:TerminalFlowQapUnknownTextId

        type TerminalFlowQapNodeId =
            | TerminalFlowQapCacheHandoffChildApplyArg0Node
            | TerminalFlowQapParentPoisonTerminalTailNode
            | TerminalFlowQapPendingOwnerTerminalTailNode
            | TerminalFlowQapUnknownNode of raw:TerminalFlowQapUnknownTextId

        type TerminalFlowQapEvidenceWitness =
            | TerminalFlowQapPrimaryFixpointWitness
            | TerminalFlowQapActiveTailWitness
            | TerminalFlowQapPendingOwnerWitness
            | TerminalFlowQapUnknownWitness of raw:TerminalFlowQapUnknownTextId

        // Domain migration : model the recurring parent-poison/cache-handoff
        // structure as a recursive relationship rather than parallel strings.
        type TerminalFlowQapRelationKind =
            | TerminalFlowQapCacheHandoffEdge
            | TerminalFlowQapParentContinuationEdge
            | TerminalFlowQapDynamicBridgeEdge
            | TerminalFlowQapPendingOwnerEdge

        type TerminalFlowQapRelationRejectionReasonId =
            private
            | TerminalFlowQapRelationRejectionReasonId of CompilerKernelV2.OperationalReasonId

        module TerminalFlowQapRelationRejectionReasonId =
            let create reason =
                reason
                |> CompilerKernelV2.OperationalReasonIdOps.create
                |> TerminalFlowQapRelationRejectionReasonId

            let text (TerminalFlowQapRelationRejectionReasonId reason) =
                CompilerKernelV2.OperationalReasonIdOps.text reason

        type TerminalFlowQapRelationConsumption =
            | TerminalFlowQapRelationUnconsumed
            | TerminalFlowQapRelationConsumedExactOnce of receiptRef:uint32 * reducerSequence:int64
            | TerminalFlowQapRelationConsumptionRejected of reason:TerminalFlowQapRelationRejectionReasonId

        type TerminalFlowQapRelation =
            | TerminalFlowQapRelationLeaf of node:TerminalFlowQapNodeId * witness:TerminalFlowQapEvidenceWitness * consumption:TerminalFlowQapRelationConsumption
            | TerminalFlowQapRelationParentChild of parent:TerminalFlowQapNodeId * edge:TerminalFlowQapRelationKind * child:TerminalFlowQapRelation * consumption:TerminalFlowQapRelationConsumption
            | TerminalFlowQapRelationCycle of head:TerminalFlowQapNodeId * edge:TerminalFlowQapRelationKind * path:TerminalFlowQapRelation list * consumption:TerminalFlowQapRelationConsumption

        type TerminalFlowQapRelationProtocolState =
            | TerminalFlowQapRelationProtocolObserved of relation:TerminalFlowQapRelation
            | TerminalFlowQapRelationProtocolCanonicalized of relation:TerminalFlowQapRelation * canonicalRef:uint32
            | TerminalFlowQapRelationProtocolConsumed of relation:TerminalFlowQapRelation * receiptRef:uint32
            | TerminalFlowQapRelationProtocolClosed of relation:TerminalFlowQapRelation * closeCertificateRef:uint32
            | TerminalFlowQapRelationProtocolPoisoned of relation:TerminalFlowQapRelation * blocker:TerminalFlowQapUnknownTextId

        type TerminalFlowQapTerminalDecision =
            | TerminalFlowQapAwaitMaterialOrWaker
            | TerminalFlowQapCandidateTerminalErrorOrQuarantine
            | TerminalFlowQapAwaitReducerFourClockWitness

        type TerminalFlowQapFixpointItem = private {
            itemRef : TerminalFlowQapFixpointRef<TerminalFlowQapFixpointItemRefKind>
            site : TerminalFlowQapFixpointSiteId
            nodeId : TerminalFlowQapNodeId
            relation : TerminalFlowQapRelation
            repeatCount : int64
            repeatCap : int64
            materialDelta : int64
            lastWitness : TerminalFlowQapEvidenceWitness
        }

        type TerminalFlowQapFixpointSet = private {
            setRef : TerminalFlowQapFixpointRef<TerminalFlowQapFixpointSetRefKind>
            items : TerminalFlowQapFixpointItem list
            materialQuiescenceAgeMs : int64
            maturity : TerminalFlowQapFixpointMaturity
            terminalDecision : TerminalFlowQapTerminalDecision
        }

        // MIGRATION: the only residual cycle promoted by this recovery tranche.
        // It is structural and total: two exact QAP sites, both past their repeat
        // caps, both with zero material delta.  Generic queue pressure cannot
        // manufacture this state.
        type TerminalFlowQapResidualCycleClass =
            | TerminalFlowQapResidualCycleNotApplicable
            | TerminalFlowQapResidualCycleCacheHandoffParentPoison of repeatFloor:int64 * repeatCap:int64

        let private terminalFlowQapResidualCycleClassFor (fixpoint:TerminalFlowQapFixpointSet) =
            let itemClosed (item:TerminalFlowQapFixpointItem) =
                let rec consumed = function
                    | TerminalFlowQapRelationLeaf(_, _, TerminalFlowQapRelationConsumedExactOnce _)
                    | TerminalFlowQapRelationParentChild(_, _, _, TerminalFlowQapRelationConsumedExactOnce _)
                    | TerminalFlowQapRelationCycle(_, _, _, TerminalFlowQapRelationConsumedExactOnce _) -> true
                    | _ -> false
                consumed item.relation
            let hasSite site =
                fixpoint.items |> List.exists (fun (item:TerminalFlowQapFixpointItem) -> item.site = site)
            if List.length fixpoint.items = 2
               && (fixpoint.items |> List.forall itemClosed)
               && hasSite TerminalFlowQapCacheHandoffApplyArg0Child
               && hasSite TerminalFlowQapParentContinuationPoison then
                let repeatFloor = fixpoint.items |> List.map (fun (item:TerminalFlowQapFixpointItem) -> item.repeatCount) |> List.min
                let repeatCap = fixpoint.items |> List.map (fun (item:TerminalFlowQapFixpointItem) -> item.repeatCap) |> List.max
                TerminalFlowQapResidualCycleCacheHandoffParentPoison(repeatFloor, repeatCap)
            else
                TerminalFlowQapResidualCycleNotApplicable

        let private terminalFlowQapResidualCycleClassText = function
            | TerminalFlowQapResidualCycleNotApplicable -> "NotApplicable"
            | TerminalFlowQapResidualCycleCacheHandoffParentPoison(repeatFloor, repeatCap) ->
                sprintf "CacheHandoffParentPoison(repeat_floor=%d|repeat_cap=%d)" repeatFloor repeatCap

        // MIGRATION: this local TerminalFlow copy is projection-only. It may render
        // or adapt legacy observations, but only TerminalFlowBreakthrough may advance
        // QAP, owner-tail, semantic, covenant, terminal-order or exit authority.
        type TerminalFlowLegacyMirrorAuthority =
            | TerminalFlowLegacyMirrorProjectionOnly

        // MIGRATION / destructive migration migration phase:
        // A fixpoint observation is not itself a terminal fact. The reducer must
        // return one of three staged resolutions, and only the Deadlocked/Drained
        // branches carry the proof receipts required to mature a terminal outcome.
        type TerminalFlowQapAwaitingMaterialStage = class end
        type TerminalFlowQapProgressingStage = class end
        type TerminalFlowQapDrainedStage = class end
        type TerminalFlowQapDeadlockedStage = class end

        [<Struct>]
        type TerminalFlowQapProtocolId<'Kind> = private | TerminalFlowQapProtocolId of uint64

        let private terminalFlowQapLocalMintedRefOf kind payload =
            NativeCutoverStableRef.ref32
                "terminal-flow-qap-local"
                [ kind; payload ]

        [<Struct>]
        type TerminalFlowQapRelationResolutionReceiptRefKind = struct end

        [<Struct>]
        type TerminalFlowQapDrainProofRefKind = struct end

        [<Struct>]
        type TerminalFlowQapDeadlockProofRefKind = struct end

        type TerminalFlowQapRelationResolution =
            | TerminalFlowQapRelationRegistered of relationRef:uint32 * wakerRef:uint32 option
            | TerminalFlowQapRelationConsumed of relationRef:uint32 * consumeReceiptRef:uint32
            | TerminalFlowQapRelationDeadlocked of relationRef:uint32 * deadlockReceiptRef:uint32
            | TerminalFlowQapRelationQuarantined of relationRef:uint32 * quarantineReceiptRef:uint32

        let private terminalFlowQapRelationResolutionText (resolution:TerminalFlowQapRelationResolution) =
            match resolution with
            | TerminalFlowQapRelationRegistered(relationRef, wakerRef) ->
                sprintf "Registered(relation_ref=%u|waker_ref=%s)" relationRef (wakerRef |> Option.map string |> Option.defaultValue "none")
            | TerminalFlowQapRelationConsumed(relationRef, consumeReceiptRef) ->
                sprintf "Consumed(relation_ref=%u|consume_receipt_ref=%u)" relationRef consumeReceiptRef
            | TerminalFlowQapRelationDeadlocked(relationRef, deadlockReceiptRef) ->
                sprintf "Deadlocked(relation_ref=%u|deadlock_receipt_ref=%u)" relationRef deadlockReceiptRef
            | TerminalFlowQapRelationQuarantined(relationRef, quarantineReceiptRef) ->
                sprintf "Quarantined(relation_ref=%u|quarantine_receipt_ref=%u)" relationRef quarantineReceiptRef

        type TerminalFlowQapRelationResolutionReceipt = private {
            receiptRef : TerminalFlowQapProtocolId<TerminalFlowQapRelationResolutionReceiptRefKind>
            relationRef : uint32
            resolution : TerminalFlowQapRelationResolution
            materialEpochBefore : int64
            materialEpochAfter : int64
            reducerSequence : int64
        }

        type TerminalFlowQapNoPendingRebaseWitness = private | TerminalFlowQapNoPendingRebaseWitness of reducerSequence:int64

        type TerminalFlowQapDrainAuthority =
            | TerminalFlowQapDrainByEmptyRelationSet
            | TerminalFlowQapDrainByExactOnceConsumption of relationCount:int

        let private terminalFlowQapDrainAuthorityText = function
            | TerminalFlowQapDrainByEmptyRelationSet -> "empty_relation_set"
            | TerminalFlowQapDrainByExactOnceConsumption relationCount -> sprintf "exact_once_consumed:%d" relationCount

        type TerminalFlowQapDrainProof<'Kind> = private {
            proofRef : TerminalFlowQapProtocolId<TerminalFlowQapDrainProofRefKind>
            qapRef : TerminalFlowQapProtocolId<'Kind>
            relationReceipts : TerminalFlowQapRelationResolutionReceipt list
            drainAuthority : TerminalFlowQapDrainAuthority
            materialEpoch : int64
            reducerSequence : int64
        }

        type TerminalFlowQapQuiescenceWitness = private | TerminalFlowQapQuiescenceWitness of creditDigest:CompilerIdentityKernel.ContentDigest

        type TerminalFlowQapDeadlockProof<'Kind> = private {
            proofRef : TerminalFlowQapProtocolId<TerminalFlowQapDeadlockProofRefKind>
            qapRef : TerminalFlowQapProtocolId<'Kind>
            quiescence : TerminalFlowQapQuiescenceWitness
            noPendingRebase : TerminalFlowQapNoPendingRebaseWitness
            relationReceipts : TerminalFlowQapRelationResolutionReceipt list
            reducerSequence : int64
        }

        type TerminalFlowQap<'Kind,'Stage> = private {
            qapRef : TerminalFlowQapProtocolId<'Kind>
            semanticDigestRef : uint32
            proceduralDigestRef : uint32
            relationSetRef : uint32
            materialEpoch : int64
            relations : TerminalFlowQapRelation list
            fixpoint : TerminalFlowQapFixpointSet
        }

        type TerminalFlowQapResolution<'Kind> =
            | TerminalFlowQapMaterialProgress of TerminalFlowQap<'Kind,TerminalFlowQapProgressingStage>
            | TerminalFlowQapFullyDrained of TerminalFlowQap<'Kind,TerminalFlowQapDrainedStage> * TerminalFlowQapDrainProof<'Kind>
            | TerminalFlowQapProvenDeadlock of TerminalFlowQap<'Kind,TerminalFlowQapDeadlockedStage> * TerminalFlowQapDeadlockProof<'Kind>

        type TerminalFlowQapResolutionBox =
            | TerminalFlowQapMaterialProgressBox of TerminalFlowQap<TerminalFlowQapFixpointSetRefKind,TerminalFlowQapProgressingStage>
            | TerminalFlowQapFullyDrainedBox of TerminalFlowQap<TerminalFlowQapFixpointSetRefKind,TerminalFlowQapDrainedStage> * TerminalFlowQapDrainProof<TerminalFlowQapFixpointSetRefKind>
            | TerminalFlowQapProvenDeadlockBox of TerminalFlowQap<TerminalFlowQapFixpointSetRefKind,TerminalFlowQapDeadlockedStage> * TerminalFlowQapDeadlockProof<TerminalFlowQapFixpointSetRefKind>

        // Every new seal requirement names the capability that can mint it.
        // A requirement without a minter is now a malformed domain value.
        type TerminalFlowQapDeadlockCredential = class end
        type TerminalFlowQapDrainCredential = class end
        type TerminalFlowOutcomeMaturityCredential = class end
        type TerminalFlowHostShutdownFinalizationCredential = class end

        type TerminalFlowMinterCapability<'Credential> = private {
            minterRef : uint32
            reducerOwned : bool
            exactOnceRef : uint32
        }

        type TerminalFlowSealRequirement<'Credential> = private {
            requirementRef : uint32
            minter : TerminalFlowMinterCapability<'Credential>
            predecessorRef : uint32 option
        }

        // Destructive typed terminal-server migration:
        // material authority and procedural churn are different types.  A replay
        // yield, boundary echo, owner-drain wake or terminal/root counter cannot
        // be passed to the material defer branch.  The phantom parameter keeps
        // that distinction at compile time while the DU keeps the runtime shape
        // inspectable without parsing HUD text back into authority.
        [<Struct>]
        type TerminalFlowMaterialActivityKind = struct end

        [<Struct>]
        type TerminalFlowProceduralActivityKind = struct end

        [<AbstractClass; Sealed>]
        type TerminalFlowRootReceiptRefKind private () =
            static member IdentityKindTag () = 0x0A0001u

        [<AbstractClass; Sealed>]
        type TerminalFlowWriterReceiptRefKind private () =
            static member IdentityKindTag () = 0x0A0002u

        [<AbstractClass; Sealed>]
        type TerminalFlowTerminalReceiptRefKind private () =
            static member IdentityKindTag () = 0x01000Eu

        type TerminalFlowReceiptRef<'Kind> =
            | TerminalFlowReceiptMissing
            | TerminalFlowReceiptPresent of value:string

        type TerminalFlowMaterialActivitySourceId =
            | TerminalFlowMaterialDelta
            | TerminalFlowFreshTopologyWitness

        type TerminalFlowProceduralActivitySourceId =
            | TerminalFlowReplayChatter
            | TerminalFlowOwnerDrainSelfChurn
            | TerminalFlowBoundaryTelemetryEcho
            | TerminalFlowRootSignalChurn
            | TerminalFlowTerminalSignalChurn
            | TerminalFlowInjectionChurn

        type TerminalFlowActivityToken<'Kind,'Source> = private {
            source : 'Source
            ageMs : int64
            count : int64
        }

        type TerminalFlowActivityObservationId =
            | TerminalFlowMaterialActivityRecent of TerminalFlowActivityToken<TerminalFlowMaterialActivityKind,TerminalFlowMaterialActivitySourceId>
            | TerminalFlowMaterialQuiescent of materialAgeMs:int64 * procedural:TerminalFlowActivityToken<TerminalFlowProceduralActivityKind,TerminalFlowProceduralActivitySourceId> option

        type TerminalFlowObservation = private {
            root : TerminalFlowRootObservationId
            writer : TerminalFlowWriterObservationId
            tail : TerminalFlowTailObservationId
            owners : TerminalFlowOwnerObservationId
            qap : TerminalFlowQapObservation
            activity : TerminalFlowActivityObservationId
        }

        // Shared in the enclosing compiler module; this scope is projection/consumer only.

        let private terminalFlowWakerRegistrationStatusText = function
            | TerminalFlowWakerMissing -> "missing"
            | TerminalFlowWakerRegistered(obligationId, registeredAtMs) -> sprintf "registered:%s@%d" obligationId registeredAtMs
            | TerminalFlowWakerExpired(obligationId, ageMs) -> sprintf "expired:%s@%d" obligationId ageMs

        let private terminalFlowWakerRegistrySourceText = function
            | TerminalFlowWakerRegistryStageToken -> "stage_token"
            | TerminalFlowWakerRegistryStickyTail -> "sticky_tail"
            | TerminalFlowWakerRegistryShutdownHook -> "shutdown_hook"

        let private terminalFlowWakerRegistryVerdictFor source = function
            | TerminalFlowWakerMissing -> TerminalFlowWakerRegistryMissing source
            | TerminalFlowWakerRegistered(obligationId, registeredAtMs) -> TerminalFlowWakerRegistryRegistered(source, obligationId, registeredAtMs)
            | TerminalFlowWakerExpired(obligationId, ageMs) -> TerminalFlowWakerRegistryExpired(source, obligationId, ageMs)

        let private terminalFlowWakerRegistryVerdictText = function
            | TerminalFlowWakerRegistryMissing source -> "missing:" + terminalFlowWakerRegistrySourceText source
            | TerminalFlowWakerRegistryRegistered(source, obligationId, registeredAtMs) -> FastRuntimeFormat.format "registered:%s:%s@%d" [| box (terminalFlowWakerRegistrySourceText source); box obligationId; box registeredAtMs |]
            | TerminalFlowWakerRegistryExpired(source, obligationId, ageMs) -> FastRuntimeFormat.format "expired:%s:%s@%d" [| box (terminalFlowWakerRegistrySourceText source); box obligationId; box ageMs |]
            | TerminalFlowWakerRegistryObservedByAltChoose(source, obligationRef) -> sprintf "observed_by_alt_choose:%s:%u" (terminalFlowWakerRegistrySourceText source) obligationRef

        let private terminalFlowProceduralResidualOwnerText (owner:TerminalFlowProceduralResidualOwner<'Phase>) =
            FastRuntimeFormat.format "ProceduralResidualOwner(id=%s|close_key=%s|depth=%d|pass=%d|material_delta=%d|repeat_cap=%d|waker=%s)" [| box owner.ownerId; box owner.closeKey; box owner.depth; box owner.drainPassCount; box owner.materialDeltaOnPass; box owner.fixedPointRepeatCap; box (terminalFlowWakerRegistrationStatusText owner.wakerStatus) |]

        let private terminalFlowStickyTailSnapshotText (snapshot:TerminalFlowStickyTailSnapshot) =
            FastRuntimeFormat.format "TerminalFlowStickyTailSnapshot(tail=%s|mutating_depth=%d|procedural_depth=%d|qap=%d/%d/%d|fixed_point_repeat=%d|procedural_pass=%d|procedural_material_delta=%d|repeat_cap=%d|material_quiescence_age_ms=%d|evaluator_frontier_resolved=%b|waker=%s|aggregate_armed=%b|mutating_drained=%b|evidence=%s)" [| box snapshot.tailId; box snapshot.mutatingDepth; box snapshot.proceduralDepth; box snapshot.globalPending; box snapshot.globalQueue; box snapshot.globalActive; box snapshot.fixedPointRepeat; box snapshot.proceduralDrainPassCount; box snapshot.materialDeltaOnProceduralPass; box snapshot.fixedPointRepeatCap; box snapshot.materialQuiescenceAgeMs; box snapshot.evaluatorFrontierResolved; box (terminalFlowWakerRegistrationStatusText snapshot.wakerStatus); box snapshot.aggregatePromiseArmed; box snapshot.mutatingTailDrained; box snapshot.evidence |]

        let private terminalFlowStickyTailGateText (gate:TerminalFlowStickyTailGateId) =
            match gate with
            | TerminalFlowStickyTailAwaitMutatingAggregate snapshot -> "TerminalFlowStickyTailGate(AwaitMutatingAggregate|" + terminalFlowStickyTailSnapshotText snapshot + ")"
            | TerminalFlowStickyTailWriterReady(snapshot, None) -> "TerminalFlowStickyTailGate(WriterReady|procedural=none|" + terminalFlowStickyTailSnapshotText snapshot + ")"
            | TerminalFlowStickyTailWriterReady(snapshot, Some owner) -> "TerminalFlowStickyTailGate(WriterReady|" + terminalFlowProceduralResidualOwnerText owner + "|" + terminalFlowStickyTailSnapshotText snapshot + ")"
            | TerminalFlowStickyTailDrained snapshot -> "TerminalFlowStickyTailGate(Drained|" + terminalFlowStickyTailSnapshotText snapshot + ")"
            | TerminalFlowStickyTailQuarantineProceduralResidual(snapshot, reason) -> "TerminalFlowStickyTailGate(QuarantineProceduralResidual|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|" + terminalFlowStickyTailSnapshotText snapshot + ")"
            | TerminalFlowStickyTailRejectUnboundedMutatingTail(snapshot, reason) -> "TerminalFlowStickyTailGate(RejectUnboundedMutatingTail|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|" + terminalFlowStickyTailSnapshotText snapshot + ")"

        let private terminalFlowStickyTailGateShouldWake (gate:TerminalFlowStickyTailGateId) =
            match gate with
            | TerminalFlowStickyTailAwaitMutatingAggregate snapshot -> snapshot.aggregatePromiseArmed || (snapshot.mutatingTailDrained && snapshot.mutatingDepth = 0)
            | TerminalFlowStickyTailWriterReady _ -> true
            | TerminalFlowStickyTailDrained _ -> true
            | TerminalFlowStickyTailQuarantineProceduralResidual _ -> true
            | TerminalFlowStickyTailRejectUnboundedMutatingTail _ -> true

        type TerminalFlowTransitionDecisionId =
            | TerminalFlowTransitionObserve
            | TerminalFlowTransitionDeferMaterialActivity of TerminalFlowActivityToken<TerminalFlowMaterialActivityKind,TerminalFlowMaterialActivitySourceId>
            | TerminalFlowTransitionRejectTopology of qap:TerminalFlowQapObservation
            | TerminalFlowTransitionRegisterWakerEdge of rootReceipt:string * leaseId:string * tailId:string * obligationId:string * nextWakeAfterMs:int64
            | TerminalFlowTransitionWriterLeaseLive of rootReceipt:string * leaseId:string * tailId:string * ageMs:int64
            | TerminalFlowTransitionWriterLeaseExpired of rootReceipt:string * leaseId:string * tailId:string * ageMs:int64 * qap:TerminalFlowQapObservation
            | TerminalFlowTransitionQuarantineResidualQap of rootReceipt:string * leaseId:string * tailId:string * ageMs:int64 * qap:TerminalFlowQapObservation
            | TerminalFlowTransitionQapFixpointMatured of rootReceipt:string * leaseId:string * tailId:string * fixpoint:TerminalFlowQapFixpointSet
            | TerminalFlowTransitionQapFixpointAwaitingMaterial of rootReceipt:string * leaseId:string * tailId:string * fixpoint:TerminalFlowQapFixpointSet
            | TerminalFlowTransitionForceCloseResidual of rootReceipt:string * leaseId:string * tailId:string * ownerCloseReceiptId:string * workDagTailCloseReceipt:string
            | TerminalFlowTransitionBindWriter of rootReceipt:string * writerReceiptId:string * tailId:string
            | TerminalFlowTransitionDeadlockTail of rootReceipt:string * leaseId:string * tailId:string * proof:CompilerKernelV2.TerminalTailDeadlockProofId
            | TerminalFlowTransitionQuarantineTail of rootReceipt:string * leaseId:string * tailId:string * reason:CompilerKernelV2.TerminalTailQuarantineReasonId
            | TerminalFlowTransitionTerminalEmitted of terminalReceiptId:string

        // MIGRATION / destructive domain migration migration phase:
        // a transition is no longer enough evidence.  Every post-root writer-tail
        // transition must project into an outcome category that can feed the
        // terminal certificate boundary: WriterBound, TailDeadlocked,
        // TailQuarantined, TerminalEmitted, or a still-live bounded lease.
        type TerminalFlowAwaitingObservationReasonId =
            | TerminalFlowAwaitingQapFixpointMaterial of rootReceipt:string * leaseId:string * tailId:string * fixpoint:TerminalFlowQapFixpointSet
            | TerminalFlowAwaitingRecentMaterialActivity of TerminalFlowActivityToken<TerminalFlowMaterialActivityKind,TerminalFlowMaterialActivitySourceId>
            | TerminalFlowAwaitingRejectedTopology of qap:TerminalFlowQapObservation
            | TerminalFlowAwaitingWakerRegistrationRequired of leaseId:string * tailId:string * obligationId:string * nextWakeAfterMs:int64
            | TerminalFlowAwaitingWriterLeaseLive of leaseId:string * tailId:string * ageMs:int64
            | TerminalFlowAwaitingGenericObservation
            | TerminalFlowAwaitingOperationalReason of CompilerKernelV2.OperationalReasonId

        type TerminalFlowOutcomeId =
            | TerminalFlowOutcomeAwaitingObservation of reason:TerminalFlowAwaitingObservationReasonId
            | TerminalFlowOutcomeWakerRegistrationRequired of rootReceipt:string * leaseId:string * tailId:string * obligationId:string * nextWakeAfterMs:int64
            | TerminalFlowOutcomeWriterLeaseStillLive of rootReceipt:string * leaseId:string * tailId:string * ageMs:int64
            | TerminalFlowOutcomeWriterBound of rootReceipt:string * writerReceiptId:string * tailId:string
            | TerminalFlowOutcomeTailDeadlocked of rootReceipt:string * leaseId:string * tailId:string * proof:CompilerKernelV2.TerminalTailDeadlockProofId
            | TerminalFlowOutcomeTailQuarantined of rootReceipt:string * leaseId:string * tailId:string * reason:CompilerKernelV2.TerminalTailQuarantineReasonId
            | TerminalFlowOutcomeTerminalEmitted of terminalReceiptId:string

        type TerminalFlowCertificateIntentId =
            | TerminalFlowCertificateAwaiting of reason:TerminalFlowAwaitingObservationReasonId
            | TerminalFlowCertificateBuildOk of rootReceipt:string * writerReceiptId:string * tailId:string
            | TerminalFlowCertificateBuildError of rootReceipt:string * leaseId:string * tailId:string * proof:CompilerKernelV2.TerminalTailDeadlockProofId
            | TerminalFlowCertificateNoFurther of terminalReceiptId:string
            | TerminalFlowCertificateQuarantine of rootReceipt:string * leaseId:string * tailId:string * reason:CompilerKernelV2.TerminalTailQuarantineReasonId

        // MIGRATION / destructive domain migration migration phase:
        // intent is no longer an endpoint.  Every terminal-flow outcome must
        // either mint a top-level receipt/certificate identifier or explain why
        // no terminal commit is legal yet.  This is deliberately stricter than
        // the HUD: a renderer may display the text, but the queue-only recovery
        // predicate consumes this boundary DU so terminal-like outcomes cannot
        // silently fall back into KeepDraining.
        type TerminalFlowWhyNotTerminalCommitId =
            | TerminalFlowWhyNotAwaitingBoundedLease of leaseId:string * tailId:string * ageMs:int64
            | TerminalFlowWhyNotAwaitingObservation of reason:TerminalFlowAwaitingObservationReasonId
            | TerminalFlowWhyNotWakerRegistrationRequired of obligationId:string * nextWakeAfterMs:int64
            | TerminalFlowWhyNotMissingRootReceipt of evidence:string
            | TerminalFlowWhyNotRecentMaterialActivity of TerminalFlowActivityToken<TerminalFlowMaterialActivityKind,TerminalFlowMaterialActivitySourceId>
            | TerminalFlowWhyNotRejectedTopology of qap:TerminalFlowQapObservation
            | TerminalFlowWhyNotMissingWriterReceipt of rootReceipt:string * tailId:string
            | TerminalFlowWhyNotObserverOnly of reason:CompilerKernelV2.OperationalReasonId

        type TerminalFlowTopLevelReceiptId =
            | TerminalFlowTopLevelBuildOkReceipt of terminalReceiptId:string * rootReceipt:string * writerReceiptId:string * tailId:string
            | TerminalFlowTopLevelBuildErrorCertificate of terminalReceiptId:string * rootReceipt:string * leaseId:string * tailId:string * proof:CompilerKernelV2.TerminalTailDeadlockProofId
            | TerminalFlowTopLevelNoFurtherCertificate of terminalReceiptId:string
            | TerminalFlowTopLevelQuarantineCertificate of terminalReceiptId:string * rootReceipt:string * leaseId:string * tailId:string * reason:CompilerKernelV2.TerminalTailQuarantineReasonId

        type TerminalFlowCertificateBoundaryId =
            | TerminalFlowBoundaryReceipt of TerminalFlowTopLevelReceiptId
            | TerminalFlowBoundaryWhyNotCommit of TerminalFlowWhyNotTerminalCommitId

        // MIGRATION / destructive bonus migration phase:
        // the boundary is no longer just a rendered proof.  It is promoted into
        // a post-root action obligation so the scheduler can distinguish
        // receipt-bearing terminal authority from bounded why-not evidence.
        // This is the breakthrough-level seam requested by the assessments:
        // every RootResolved writer-tail path either has a top-level receipt or
        // an exact typed reason that prevents terminal commit.
        type TerminalFlowBoundaryActionId =
            | TerminalFlowBoundaryActionEmitReceipt of TerminalFlowTopLevelReceiptId
            | TerminalFlowBoundaryActionBlockCommit of TerminalFlowWhyNotTerminalCommitId
            | TerminalFlowBoundaryActionFatalMissingBoundary of reason:CompilerKernelV2.OperationalReasonId

        type PostRootTailDrainOutcome =
            | PostRootTailDrainMadeProgress of before:int * after:int * materialDelta:int
            | PostRootTailDrainBoundWriter of writerReceiptId:string * qap:string
            | PostRootTailDrainExpiredToDeadlock of tailId:string * repeatCount:int64 * repeatCap:int64
            | PostRootTailDrainLiveHighQueue of tailId:string * qap:string * materialProgressObserved:bool
            | PostRootTailDrainHighQueueExpiredToDeadlock of tailId:string * qap:string * leaseId:string
            | PostRootTailDrainNoRootBudgetLive of tailId:string * qap:string * repeatCount:int64
            | PostRootTailDrainNoRootBudgetExpiredToTerminal of tailId:string * qap:string * terminalReceiptId:string
            | PostRootTailDrainQuarantined of tailId:string * proof:CompilerKernelV2.OperationalReasonId
            | PostRootTailDrainRejectedOwnerDebtReopen of receiptId:string * demotionReceiptId:string

        // MIGRATION: the 1957 run proved the legacy back-edge was gone, but
        // a post-root WorkDag tail with q=109/a=4/p=0 was neither small,
        // drained, nor expired.  Model this as a high-queue writer tail lease:
        // liveness must prove material progress, not mere occupancy.
        type PostRootLiveTailProgress =
            | PostRootTailMaterialProgress of before:int * after:int * materialDelta:int
            | PostRootTailOccupiedNoMaterialProgress of qap:string * leaseId:string
            | PostRootTailHighQueueLeaseLive of qap:string * deadlineMs:int
            | PostRootTailHighQueueLeaseExpired of qap:string * terminalReceiptId:string
            | PostRootNoRootBudgetTailLive of qap:string * targetKey:string * repeatCount:int64
            | PostRootNoRootBudgetTailExpired of qap:string * targetKey:string * terminalReceiptId:string

        type PostRootHighQueueTailLease<'GraphKind> = private {
            leaseId : string
            rootReceiptId : string
            writerLeaseId : string
            tailId : string
            qapSnapshot : string
            materialProgressRequired : bool
            expiresAfterMs : int
            progress : PostRootLiveTailProgress
        }

        // MIGRATION: 1958 proved the high-queue class exists, but a second
        // residual lane was still rendered by the old no-root-budget bypass
        // while the post-root writer lease was alive.  Model that bypass as a
        // bounded writer-tail lease too: no-root-budget after RootResolved is
        // not a root blocker; it is a WorkDag tail obligation owned by WriterCapability.
        type PostRootNoRootBudgetTailLease<'GraphKind> = private {
            leaseId : string
            rootReceiptId : string
            writerLeaseId : string
            tailId : string
            targetKey : string
            qapSnapshot : string
            repeatCount : int64
            repeatCap : int64
            expiresAfterMs : int
            progress : PostRootLiveTailProgress
        }

        type PostRootOwnerDebtDemotionReceipt<'GraphKind> = private {
            demotionReceiptId : string
            rootReceiptId : string
            writerLeaseId : string
            demotedOwnerReceiptId : string
            tailId : string
            ownerDebtAuthorityConsumed : bool
            rootReopenForbidden : bool
            schedulerDecision : PostRootSchedulerDecision<'GraphKind>
        }

        type TerminalCommitEmissionContract<'GraphKind> = private {
            terminalReceiptId : string
            rootReceiptId : string
            writerLeaseId : string
            tailOutcome : PostRootTailDrainOutcome
            flowState : PostRootTerminalFlowState
            terminalAfterRoot : TerminalAfterRoot<'GraphKind> option
            exitCode : int
            physicalExitRequired : bool
            ownerDebtRowsSuppressedAfterRoot : int64
        }

        // MIGRATION / post-root migration migration phase: terminalization is
        // now modeled as a physical emission boundary.  The writer tail may
        // no longer stop at an advisory TerminalCommitEmissionContract; it
        // must pass through a sealed boundary that records artifact intent,
        // writer capability intent, owner-row suppression, and an exit latch.
        // This prepares the authoritative cut to make RootComplete -> WriterCapability a
        // pure Hopac Alt with no remaining owner-debt back-edge.
        type PostRootPhysicalExitKind =
            | PostRootExitBuildOk
            | PostRootExitBuildError
            | PostRootExitNoFurther
            | PostRootExitQuarantine

        type PostRootOwnerDebtBackEdgePolicy =
            | PostRootOwnerDebtBackEdgeRejected of rowRef:string * demotionReceiptId:string
            | PostRootOwnerDebtBackEdgeDemoted of rowRef:string * writerLeaseId:string * tailId:string
            | PostRootOwnerDebtBackEdgeFatalViolation of rowRef:string * violation:PostRootAuthorityViolation

        type WriterTailEmissionSeal<'GraphKind> = private {
            sealId : string
            terminalContract : TerminalCommitEmissionContract<'GraphKind>
            exitKind : PostRootPhysicalExitKind
            writerCapabilityId : string option
            artifactHashId : string option
            workDagTailId : string
            ownerBackEdgePolicy : PostRootOwnerDebtBackEdgePolicy
            physicalExitLatched : bool
        }

        type PostRootTerminalEmissionBoundary<'GraphKind> =
            | PostRootBoundaryAwaitingWriter of lease:WriterCapabilityLease<'GraphKind> * tail:WorkDagTail<'GraphKind,WriterPendingStage>
            | PostRootBoundarySealedSuccess of WriterTailEmissionSeal<'GraphKind>
            | PostRootBoundarySealedFailure of WriterTailEmissionSeal<'GraphKind> * violation:PostRootAuthorityViolation
            | PostRootBoundaryRejectedObserver of rowRef:string * reason:CompilerKernelV2.OperationalReasonId

        // MIGRATION / post-root migration migration phase: close the last
        // legacy back-edge.  RootResolved no longer hands a generic owner
        // drain to the old terminal board; it binds a RootToWriterAlt that
        // owns the WriterCapabilityLease, WorkDagTailLease and terminal
        // emission boundary.  Any post-root owner-debt row becomes a banned
        // back-edge value.  This is deliberately type-heavy: the next compile
        // should fail on unported matches rather than silently plateauing.
        type RootToWriterAltState =
            | RootToWriterAltArmed
            | RootToWriterAltWriterBound
            | RootToWriterAltTailDeadlocked
            | RootToWriterAltTailQuarantined
            | RootToWriterAltTerminalEmitted

        type RootToWriterAlt<'GraphKind> = private {
            altId : string
            rootReceipt : RootResolvedReceipt<'GraphKind>
            writerLease : WriterCapabilityLease<'GraphKind>
            tailLease : WorkDagTailLease<'GraphKind,WriterPendingStage>
            state : RootToWriterAltState
            boundary : PostRootTerminalEmissionBoundary<'GraphKind>
            rendererBackEdgesBanned : bool
        }

        type PostRootTerminalizationWitness<'GraphKind> = private {
            witnessId : string
            rootToWriterAltId : string
            terminalBoundary : PostRootTerminalEmissionBoundary<'GraphKind>
            schedulerDecision : PostRootSchedulerDecision<'GraphKind>
            terminalContract : TerminalCommitEmissionContract<'GraphKind> option
            ownerDebtBackEdgesSuppressed : int64
            malformedObserverRowsSuppressed : int64
        }

        type PostRootLegacyBackEdgeBan<'GraphKind> =
            | BackEdgeBanOwnerDebtRow of rowRef:string * policy:PostRootOwnerDebtBackEdgePolicy
            | BackEdgeBanScheduleParentPoisonAfterRoot of rowRef:string * alt:RootToWriterAlt<'GraphKind>
            | BackEdgeBanMetronomeDeadmanBeforeLeaseExpiry of lease:WriterCapabilityLease<'GraphKind>
            | BackEdgeBanRootWaitingAfterResolved of rowRef:string * receipt:RootResolvedReceipt<'GraphKind>

        type PostRootFinalMigrationSeal<'GraphKind> = private {
            sealId : string
            alt : RootToWriterAlt<'GraphKind>
            witness : PostRootTerminalizationWitness<'GraphKind>
            legacyBackEdges : PostRootLegacyBackEdgeBan<'GraphKind> list
            terminalBoundary : PostRootTerminalEmissionBoundary<'GraphKind>
            physicalExitKind : PostRootPhysicalExitKind option
        }

        // MIGRATION / bonus migration phase: consolidate the five-round
        // post-root migration into a single breakthrough certificate.  The
        // compiler may still expose HUD/debug strings, but the terminal path
        // must be owned by a certificate that joins root receipt, writer lease,
        // workdag tail, semantic debt payment, wait-graph arming, and physical
        // emission boundary.  This is the bridge from the current board-driven
        // runtime into the assessment target: pure Hopac dataflow where the
        // top-level promise is WriterCapability, not a polling quorum board.
        type BreakthroughCertificateStage =
            | BreakthroughCertificateDraft
            | BreakthroughCertificatePureGraphJoined
            | BreakthroughCertificateTerminalSealed
            | BreakthroughCertificateRejected

        type PureHopacGraphObligation<'GraphKind> = private {
            obligationId : string
            rootReceiptId : string
            writerLeaseId : string
            workDagTailId : string
            semanticReceiptIds : string list
            waitGraphSpineIds : string list
            ownerDebtConsumed : bool
            rootBackEdgeImpossible : bool
            writerCapabilityIsTopLevelPromise : bool
        }

        type BreakthroughSealCertificate<'GraphKind> = private {
            certificateId : string
            stage : BreakthroughCertificateStage
            rootToWriterAlt : RootToWriterAlt<'GraphKind>
            finalMigrationSeal : PostRootFinalMigrationSeal<'GraphKind>
            pureGraphObligation : PureHopacGraphObligation<'GraphKind>
            terminalBoundary : PostRootTerminalEmissionBoundary<'GraphKind>
            physicalExitKind : PostRootPhysicalExitKind option
            rendererRowsSuppressed : int64
            quorumBoardAuthorityAbolished : bool
        }

        type TerminalEmissionDecision<'GraphKind> =
            | TerminalEmissionAwaitPureGraphJoin of BreakthroughSealCertificate<'GraphKind>
            | TerminalEmissionCommitWriter of BreakthroughSealCertificate<'GraphKind> * WriterTailEmissionSeal<'GraphKind>
            | TerminalEmissionFailClosed of BreakthroughSealCertificate<'GraphKind> * PostRootAuthorityViolation
            | TerminalEmissionRejectLegacyBackEdge of BreakthroughSealCertificate<'GraphKind> * PostRootLegacyBackEdgeBan<'GraphKind>

        type RootTerminalOutcome<'GraphKind> =
            | RootTerminalOutcomePendingWriter of TerminalRootReceiptGate<'GraphKind>
            | RootTerminalOutcomePostRoot of TerminalAfterRoot<'GraphKind>
            | RootTerminalOutcomeCommitted of WriterCommitReceipt<'GraphKind>
            | RootTerminalOutcomeFailedClosed of BuildErrorTraceAuthority<'GraphKind>
            | RootTerminalOutcomeRejectedObserverOnly of rowRef:string * reason:CompilerKernelV2.OperationalReasonId

        // DOMAIN MIGRATION round : terminal exit authority is no longer
        // inferred from RootComplete, BuildErrorTrace, or the HUD.  Exit-0 is
        // legal only when RootTerminalOutcomeCommitted carries a writer commit
        // receipt and the writer seal accepts the exact artifact hash.  Every
        // fail-closed exit must carry either BuildErrorTraceAuthority or a named
        // OwnerDrainAuthorityViolation, so the runtime can never produce a
        // silent observer-only terminal row again.
        type BuildOkExitAuthority<'GraphKind> =
            | BuildOkExitCommitted of outcome:RootTerminalOutcome<'GraphKind> * seal:WriterRootBuildOkSealDecision<'GraphKind>
            | BuildOkExitRejectedWithoutCommittedOutcome of seal:WriterRootBuildOkSealDecision<'GraphKind> * reason:CompilerKernelV2.OperationalReasonId

        type FailClosedExitAuthority<'GraphKind> =
            | FailClosedByBuildErrorAuthority of BuildErrorTraceAuthority<'GraphKind>
            | FailClosedByOwnerDrainViolation of OwnerDrainAuthorityViolation * terminalGate:TerminalRootReceiptGate<'GraphKind> option
            | FailClosedByUnconsumedRootReceipt of TerminalRootReceiptGate<'GraphKind> * reason:CompilerKernelV2.OperationalReasonId

        type NativeTerminalExitContract<'GraphKind> = private {
            contractId : string
            rootOutcome : RootTerminalOutcome<'GraphKind>
            buildOkAuthority : BuildOkExitAuthority<'GraphKind> option
            failClosedAuthority : FailClosedExitAuthority<'GraphKind> option
            observerOnlyRowsSuppressed : int64
            exitCode : int option
        }

        // BONUS MIGRATION round : breakthrough-level authority is now a
        // scheduler-owned push spine instead of a late HUD explanation.  The
        // metronome may observe, but only push events backed by armed wait-graph
        // edges, exact-once owner receipts, root terminal contracts, and writer
        // commit receipts can move the final state.  This is deliberately stricter
        // than the previous five-round migration: it makes dropped continuations,
        // unarmed semantic waits, and BuildOk-without-writer mathematically visible
        // as rejected authority values before they can become plateau behavior.
        type WaitGraphEdgeArmingState =
            | WaitGraphEdgeArmed of edgeId:string * writerCapability:string * consumerCapability:string
            | WaitGraphEdgeMissingWriter of edgeId:string * expectedWriter:string
            | WaitGraphEdgeMissingConsumer of edgeId:string * expectedConsumer:string
            | WaitGraphEdgeDroppedContinuation of edgeId:string * lastKnownOwner:string * reason:CompilerKernelV2.OperationalReasonId

        type ArmedWaitGraphSpine<'GraphKind> = private {
            spineId : string
            semanticReceiptId : string option
            topologyEpochHash : string option
            qapQueueDepth : int
            qapActiveDepth : int
            qapPendingDepth : int
            edges : WaitGraphEdgeArmingState list
            unarmedEdgeCount : int
            droppedContinuationCount : int
        }

        type SchedulerPushEvent<'GraphKind> =
            | PushOwnerAxisReceipt of OwnerAxisExactOnceReceipt<'GraphKind>
            | PushTopologyStasisSeal of PureSidecarTopologyStasisSeal<'GraphKind>
            | PushWaitGraphArmed of ArmedWaitGraphSpine<'GraphKind>
            | PushRootTransition of RootTerminalOutcome<'GraphKind>
            | PushPostRootTerminalization of TerminalAfterRoot<'GraphKind>
            | PushPostRootHighQueueTailLease of PostRootHighQueueTailLease<'GraphKind>
            | PushPostRootNoRootBudgetTailLease of PostRootNoRootBudgetTailLease<'GraphKind>
            | PushRootToWriterAlt of RootToWriterAlt<'GraphKind>
            | PushPostRootTerminalizationWitness of PostRootTerminalizationWitness<'GraphKind>
            | PushPostRootBackEdgeBan of PostRootLegacyBackEdgeBan<'GraphKind>
            | PushPostRootFinalMigrationSeal of PostRootFinalMigrationSeal<'GraphKind>
            | PushBreakthroughSealCertificate of BreakthroughSealCertificate<'GraphKind>
            | PushPureHopacGraphJoin of PureHopacGraphObligation<'GraphKind>
            | PushTerminalEmissionDecision of TerminalEmissionDecision<'GraphKind>
            | PushWriterCommit of WriterCommitReceipt<'GraphKind>
            | PushFailClosed of FailClosedExitAuthority<'GraphKind>
            | PushRejectedObserver of rowRef:string * reason:CompilerKernelV2.OperationalReasonId

        type SchedulerPushAuthority<'GraphKind> = private {
            authorityId : string
            pushEvent : SchedulerPushEvent<'GraphKind>
            rootContract : NativeTerminalExitContract<'GraphKind> option
            writerSealRequired : bool
            rendererAuthorityAllowed : bool
            metronomeObserverOnly : bool
        }

        type BreakthroughExitArbiter<'GraphKind> =
            | BreakthroughCommitted of contract:NativeTerminalExitContract<'GraphKind> * writer:WriterCommitReceipt<'GraphKind> * spine:ArmedWaitGraphSpine<'GraphKind>
            | BreakthroughPostRootTerminalization of flow:TerminalAfterRoot<'GraphKind> * spine:ArmedWaitGraphSpine<'GraphKind>
            | BreakthroughSealCertified of certificate:BreakthroughSealCertificate<'GraphKind> * decision:TerminalEmissionDecision<'GraphKind> * spine:ArmedWaitGraphSpine<'GraphKind>
            | BreakthroughFailedClosed of contract:NativeTerminalExitContract<'GraphKind> * authority:FailClosedExitAuthority<'GraphKind> * spine:ArmedWaitGraphSpine<'GraphKind> option
            | BreakthroughRejectedMissingContract of push:SchedulerPushEvent<'GraphKind> * reason:CompilerKernelV2.OperationalReasonId
            | BreakthroughRejectedUnarmedSpine of spine:ArmedWaitGraphSpine<'GraphKind> * violation:OwnerDrainAuthorityViolation

        type TerminalAuthorityMigrationStatus<'GraphKind> = private {
            migrationId : string
            ownerReceiptsConsumed : int
            topologyStasisSealsConsumed : int
            waitGraphSpinesArmed : int
            schedulerPushEventsConsumed : int
            rendererOnlyRowsRejected : int
            exitArbiter : BreakthroughExitArbiter<'GraphKind> option
        }

        let private ownerAxisReceiptConsumptionText = function
            | OwnerAxisReceiptUnconsumed -> "OwnerAxisReceiptConsumption(Unconsumed)"
            | OwnerAxisReceiptConsumedByRoot rootTransition -> "OwnerAxisReceiptConsumption(ConsumedByRoot|root=" + rootTransition + ")"
            | OwnerAxisReceiptConsumedByWriter writerCapability -> "OwnerAxisReceiptConsumption(ConsumedByWriter|writer=" + writerCapability + ")"
            | OwnerAxisReceiptRejectedByEpoch(beforeEpoch, afterEpoch, reason) -> "OwnerAxisReceiptConsumption(RejectedByEpoch|before=" + string beforeEpoch + "|after=" + string afterEpoch + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | OwnerAxisReceiptRejectedByLease(leaseId, reason) -> "OwnerAxisReceiptConsumption(RejectedByLease|lease=" + leaseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let private ownerDrainAuthorityViolationText = function
            | OwnerDrainWouldIncreaseOpenCount(beforeOpen, afterOpen) -> "OwnerDrainAuthorityViolation(OpenCountIncreased|before=" + string beforeOpen + "|after=" + string afterOpen + ")"
            | OwnerDrainWouldReopenTerminalEligible receiptId -> "OwnerDrainAuthorityViolation(ReopenTerminalEligible|receipt=" + receiptId + ")"
            | OwnerDrainWouldUseTopologyWithoutStasisSeal(epochHash, repeatCount) -> "OwnerDrainAuthorityViolation(TopologyWithoutStasisSeal|epoch=" + epochHash + "|repeat=" + string repeatCount + ")"
            | OwnerDrainWouldResolveRootWithoutWriterCapability root -> "OwnerDrainAuthorityViolation(RootWithoutWriterCapability|root=" + root + ")"
            | OwnerDrainWouldWaitWithoutRegisteredWaker edgeId -> "OwnerDrainAuthorityViolation(WaitWithoutRegisteredWaker|edge=" + edgeId + ")"
            | OwnerDrainRendererTriedToAuthorize rowRef -> "OwnerDrainAuthorityViolation(RendererTriedToAuthorize|row=" + rowRef + ")"

        let private terminalRootReceiptKindText = function
            | TerminalRootReceiptBuildOk -> "build_ok"
            | TerminalRootReceiptBuildErrorTrace -> "build_error_trace"
            | TerminalRootReceiptNoFurther -> "no_further"
            | TerminalRootReceiptOwnerDeadlock -> "owner_deadlock"
            | TerminalRootReceiptCpuDeadman -> "cpu_deadman"
            | TerminalRootReceiptQuarantine -> "quarantine"

        let private rootCompleteAltAuthorityText (x:RootCompleteAltAuthority<'GraphKind>) =
            "RootCompleteAltAuthority(id=" + x.altId
            + "|receipt=" + x.rootReceiptId
            + "|kind=" + terminalRootReceiptKindText x.receiptKind
            + "|writer_required=" + string x.writerCapabilityRequired
            + "|build_error_trace=" + (x.buildErrorTraceId |> Option.defaultValue "none")
            + "|owner_blocker=" + (x.ownerAxisBlocker |> Option.map ownerAxisIdText |> Option.defaultValue "none")
            + "|observer_rows_suppressed=" + string x.observerRowsSuppressed + ")"

        let private terminalRootReceiptGateText (x:TerminalRootReceiptGate<'GraphKind>) =
            "TerminalRootReceiptGate(id=" + x.gateId
            + "|root_consumed=" + string x.receiptConsumedByRoot
            + "|writer_consumed=" + string x.receiptConsumedByWriter
            + "|commit_allowed=" + string x.terminalCommitAllowed
            + "|fail_closed_ms=" + string x.failClosedIfMissingWriterAfterMs
            + "|alt=" + rootCompleteAltAuthorityText x.altAuthority + ")"

        let private writerCommitReceiptText (x:WriterCommitReceipt<'GraphKind>) =
            "WriterCommitReceipt(id=" + x.commitReceiptId
            + "|writer=" + (x.writerCapability |> Option.defaultValue "pending")
            + "|artifact=" + (x.artifactHash |> Option.defaultValue "pending")
            + "|build_ok_allowed=" + string x.buildOkAllowed
            + "|exit=" + (x.exitCode |> Option.map string |> Option.defaultValue "pending") + ")"

        let private buildErrorTraceAuthorityText (x:BuildErrorTraceAuthority<'GraphKind>) =
            "BuildErrorTraceAuthority(trace=" + x.traceId
            + "|code=" + x.compactCode
            + "|root_owned=" + string x.rootFailureOwnedByScheduler
            + "|durable_before_exit=" + string x.terminalReceiptDurableBeforeExit
            + "|raw_console_suppressed=" + string x.rawConsoleSuppressed + ")"

        let private postRootTailKindText = function
            | PostRootCrossKindTail -> "cross_kind"
            | PostRootParentPoisonTail -> "parent_poison"
            | PostRootSidecarDrainTail -> "sidecar_drain"
            | PostRootParentContinuationTail -> "parent_continuation"
            | PostRootDynamicBridgeTail -> "dynamic_bridge"
            | PostRootJoinPointTail -> "join_point"
            | PostRootArtifactWriterTail -> "artifact_writer"

        let private rootResolvedReceiptText (x:RootResolvedReceipt<'GraphKind>) =
            let q,a,p = x.qapAtResolution
            "RootResolvedReceipt(id=" + x.receiptId
            + "|semantic=" + (x.semanticReceiptId |> Option.defaultValue "none")
            + "|qap=" + string q + "/" + string a + "/" + string p
            + "|row=" + x.sourceRowRef
            + "|line=" + string x.resolvedAtLine + ")"

        let private writerCapabilityLeaseText (x:WriterCapabilityLease<'GraphKind>) =
            "WriterCapabilityLease(id=" + x.leaseId
            + "|root=" + x.rootReceipt.receiptId
            + "|owner=" + x.owner
            + "|started_line=" + string x.startedAtLine
            + "|expires_ms=" + string x.expiresAfterMs
            + "|repeat_cap=" + string x.repeatCap + ")"

        let private workDagTailText (x:WorkDagTail<'GraphKind,'Stage>) =
            let q,a,p = x.qap
            "WorkDagTail(id=" + x.tailId
            + "|kind=" + postRootTailKindText x.kind
            + "|owner=" + x.ownerId
            + "|obligation=" + x.obligationId
            + "|edge=" + x.waitGraphEdgeId
            + "|qap=" + string q + "/" + string a + "/" + string p
            + "|repeat=" + string x.repeatCount
            + "|epoch=" + string x.materialEpoch
            + "|proof=" + x.proof + ")"

        let private writerCapabilityStateText (x:WriterCapabilityState<'GraphKind,'Stage>) =
            "WriterCapabilityState(root=" + rootResolvedReceiptText x.rootReceipt
            + "|lease=" + writerCapabilityLeaseText x.lease
            + "|tail=" + workDagTailText x.tail
            + "|writer_receipt=" + (x.writerReceiptId |> Option.defaultValue "none")
            + "|terminal_receipt=" + (x.terminalReceiptId |> Option.defaultValue "none") + ")"

        let private terminalAfterRootText = function
            | TerminalAfterRootKeepDraining x -> "TerminalAfterRoot(KeepDraining|" + writerCapabilityStateText x + ")"
            | TerminalAfterRootEmitSuccess x -> "TerminalAfterRoot(EmitSuccess|" + writerCapabilityStateText x + ")"
            | TerminalAfterRootEmitBuildError x -> "TerminalAfterRoot(EmitBuildError|" + writerCapabilityStateText x + ")"
            | TerminalAfterRootEmitNoFurther x -> "TerminalAfterRoot(EmitNoFurther|" + writerCapabilityStateText x + ")"

        let private postRootAuthorityViolationText = function
            | PostRootOwnerDrainReopenedRoot receiptId -> "PostRootAuthorityViolation(OwnerDrainReopenedRoot|receipt=" + receiptId + ")"
            | PostRootWriterLeaseExpiredWithoutDecision(leaseId, tailId) -> "PostRootAuthorityViolation(WriterLeaseExpiredWithoutDecision|lease=" + leaseId + "|tail=" + tailId + ")"
            | PostRootCrossKindTailRepeatCapExceeded(tailId, repeatCount, repeatCap) -> "PostRootAuthorityViolation(CrossKindTailRepeatCapExceeded|tail=" + tailId + "|repeat=" + string repeatCount + "|cap=" + string repeatCap + ")"
            | PostRootDeadmanMissingTerminalReceipt leaseId -> "PostRootAuthorityViolation(DeadmanMissingTerminalReceipt|lease=" + leaseId + ")"
            | PostRootRendererTriedToMutateTerminalFlow rowRef -> "PostRootAuthorityViolation(RendererTriedToMutateTerminalFlow|row=" + rowRef + ")"
            | PostRootTailLostWriterCapability(tailId, edgeId) -> "PostRootAuthorityViolation(TailLostWriterCapability|tail=" + tailId + "|edge=" + edgeId + ")"
            | PostRootMaterializedTerminalHandoffObserverOnlyExhausted(leaseId, tailId, payload, noWorkS) -> "PostRootAuthorityViolation(MaterializedTerminalHandoffObserverOnlyExhausted|lease=" + leaseId + "|tail=" + tailId + "|payload=" + payload + "|no_work_s=" + string noWorkS + ")"
            | PostRootFrontierZeroStalePendingCacheClosed(leaseId, tailId, rawPending, frontPending) -> "PostRootAuthorityViolation(FrontierZeroStalePendingCacheClosed|lease=" + leaseId + "|tail=" + tailId + "|raw_pending=" + string rawPending + "|front_pending=" + string frontPending + ")"
            | PostRootEmptyOwnerLedgerBlockedByOpenQuorum(leaseId, tailId) -> "PostRootAuthorityViolation(EmptyOwnerLedgerBlockedByOpenQuorum|lease=" + leaseId + "|tail=" + tailId + ")"
            | PostRootWriterLeaseObservedButNotOwned(leaseId, observerRow) -> "PostRootAuthorityViolation(WriterLeaseObservedButNotOwned|lease=" + leaseId + "|row=" + observerRow + ")"
            | PostRootOwnerDebtRowAfterRootResolved(receiptId, demotedToTailId) -> "PostRootAuthorityViolation(OwnerDebtRowAfterRootResolved|receipt=" + receiptId + "|tail=" + demotedToTailId + ")"

        let private writerCapabilityLeaseStatusText = function
            | WriterLeaseLive(leaseId, ageMs, expiresAfterMs) -> "WriterCapabilityLeaseStatus(Live|lease=" + leaseId + "|age_ms=" + string ageMs + "|expires_after_ms=" + string expiresAfterMs + ")"
            | WriterLeaseBound(leaseId, writerReceiptId) -> "WriterCapabilityLeaseStatus(Bound|lease=" + leaseId + "|writer_receipt=" + writerReceiptId + ")"
            | WriterLeaseExpired(leaseId, ageMs, expiresAfterMs) -> "WriterCapabilityLeaseStatus(Expired|lease=" + leaseId + "|age_ms=" + string ageMs + "|expires_after_ms=" + string expiresAfterMs + ")"
            | WriterLeaseQuarantined(leaseId, reason) -> "WriterCapabilityLeaseStatus(Quarantined|lease=" + leaseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let private postRootTerminalizationGateText = function
            | PostRootGateKeepDraining(lease, tail) -> "PostRootTerminalizationGate(KeepDraining|lease=" + lease.leaseId + "|tail=" + tail.tailId + ")"
            | PostRootGateBindWriter(state, writerReceiptId) -> "PostRootTerminalizationGate(BindWriter|" + writerCapabilityStateText state + "|writer_receipt=" + writerReceiptId + ")"
            | PostRootGateEmitDeadlock(state, violation) -> "PostRootTerminalizationGate(EmitDeadlock|" + writerCapabilityStateText state + "|" + postRootAuthorityViolationText violation + ")"
            | PostRootGateEmitQuarantine(state, proof) -> "PostRootTerminalizationGate(EmitQuarantine|" + writerCapabilityStateText state + "|proof=" + CompilerKernelV2.TerminalTailQuarantineReasonIdOps.text proof + ")"

        let private postRootSchedulerDecisionText = function
            | PostRootDemoteOwnerDrainToWriterTail x -> "PostRootSchedulerDecision(DemoteOwnerDrainToWriterTail|" + writerCapabilityStateText x + ")"
            | PostRootBindWriterAfterTailDrained x -> "PostRootSchedulerDecision(BindWriterAfterTailDrained|" + writerCapabilityStateText x + ")"
            | PostRootDeadlockTailAfterLeaseExpiry(x, violation) -> "PostRootSchedulerDecision(DeadlockTailAfterLeaseExpiry|" + writerCapabilityStateText x + "|" + postRootAuthorityViolationText violation + ")"
            | PostRootQuarantineTailAfterStasis(x, proof) -> "PostRootSchedulerDecision(QuarantineTailAfterStasis|" + writerCapabilityStateText x + "|proof=" + CompilerKernelV2.TerminalTailQuarantineReasonIdOps.text proof + ")"
            | PostRootBindWriterLeaseToTerminalGate gate -> "PostRootSchedulerDecision(BindWriterLeaseToTerminalGate|" + postRootTerminalizationGateText gate + ")"
            | PostRootExpireWriterLeaseToTerminalReceipt(lease, tail, violation) -> "PostRootSchedulerDecision(ExpireWriterLeaseToTerminalReceipt|lease=" + lease.leaseId + "|tail=" + tail.tailId + "|" + postRootAuthorityViolationText violation + ")"
            | PostRootEmitTerminal flow -> "PostRootSchedulerDecision(EmitTerminal|" + terminalAfterRootText flow + ")"

        let private postRootTerminalFlowStateText = function
            | PostRootFlowBeforeWriter -> "before_writer"
            | PostRootFlowWriterLeaseLive -> "writer_lease_live"
            | PostRootFlowWriterBound -> "writer_bound"
            | PostRootFlowTailDeadlocked -> "tail_deadlocked"
            | PostRootFlowTailQuarantined -> "tail_quarantined"
            | PostRootFlowTerminalEmitted -> "terminal_emitted"

        let private terminalFlowRootObservationText = function
            | TerminalFlowRootNotObserved -> "root:not_observed"
            | TerminalFlowRootPending -> "root:pending"
            | TerminalFlowRootResolved receiptId -> "root:resolved:" + receiptId
            | TerminalFlowRootResolvedWithoutReceipt evidence -> "root:resolved_without_receipt:" + evidence

        let private terminalFlowWriterObservationText = function
            | TerminalFlowWriterNotObserved -> "writer:not_observed"
            | TerminalFlowWriterPending leaseId -> "writer:pending:" + leaseId
            | TerminalFlowWriterBlockedOnQap leaseId -> "writer:blocked_on_qap:" + leaseId
            | TerminalFlowWriterBoundObserved writerReceiptId -> "writer:bound:" + writerReceiptId

        let private terminalFlowTailObservationText = function
            | TerminalFlowTailUnknown -> "tail:unknown"
            | TerminalFlowTailPendingDrain tailId -> "tail:pending_drain:" + tailId
            | TerminalFlowTailDrained tailId -> "tail:drained:" + tailId
            | TerminalFlowTailDeadlockedObserved(tailId, proof) ->
                "tail:deadlocked:" + tailId + ":" + CompilerKernelV2.TerminalTailDeadlockProofIdOps.text proof
            | TerminalFlowTailQuarantinedObserved(tailId, reason) ->
                "tail:quarantined:" + tailId + ":" + CompilerKernelV2.TerminalTailQuarantineReasonIdOps.text reason
            | TerminalFlowTailTerminalEmittedObserved receiptId -> "tail:terminal_emitted:" + receiptId

        let private terminalFlowOwnerObservationText = function
            | TerminalFlowOwnersUnknown -> "owners:unknown"
            | TerminalFlowOwnersOpen openCount -> "owners:open:" + string openCount
            | TerminalFlowOwnersQuarantinable(openCount, reason) ->
                "owners:quarantinable:" + string openCount + ":" + CompilerKernelV2.TerminalOwnerQuarantineReasonIdOps.text reason
            | TerminalFlowOwnersWakerRegistrationRequired(openCount, obligationId) -> "owners:waker_registration_required:" + string openCount + ":" + obligationId
            | TerminalFlowOwnersWakerRegistrationRejected(openCount, obligationId, reason) ->
                "owners:waker_registration_rejected:" + string openCount + ":" + obligationId + ":" + CompilerKernelV2.TerminalOwnerWakerRejectionReasonIdOps.text reason
            | TerminalFlowOwnersClosed -> "owners:closed"
            | TerminalFlowOwnersStickyTerminalEligible -> "owners:sticky_terminal_eligible"

        let private terminalFlowMaterialActivitySourceText = function
            | TerminalFlowMaterialDelta -> "material_delta"
            | TerminalFlowFreshTopologyWitness -> "fresh_topology_witness"

        let private terminalFlowProceduralActivitySourceText = function
            | TerminalFlowReplayChatter -> "replay_chatter"
            | TerminalFlowOwnerDrainSelfChurn -> "owner_drain_self_churn"
            | TerminalFlowBoundaryTelemetryEcho -> "boundary_telemetry_echo"
            | TerminalFlowRootSignalChurn -> "root_signal_churn"
            | TerminalFlowTerminalSignalChurn -> "terminal_signal_churn"
            | TerminalFlowInjectionChurn -> "injection_churn"

        let private terminalFlowReceiptRefOfText (value:string) : TerminalFlowReceiptRef<'Kind> =
            if String.IsNullOrWhiteSpace value || value = "-" then TerminalFlowReceiptMissing
            else TerminalFlowReceiptPresent value

        let private terminalFlowReceiptRefTextOr fallback = function
            | TerminalFlowReceiptPresent value -> value
            | TerminalFlowReceiptMissing -> fallback

        let private terminalFlowMaterialActivityToken source ageMs count : TerminalFlowActivityToken<TerminalFlowMaterialActivityKind,TerminalFlowMaterialActivitySourceId> =
            { source = source; ageMs = max 0L ageMs; count = max 0L count }

        let private terminalFlowProceduralActivityToken source ageMs count : TerminalFlowActivityToken<TerminalFlowProceduralActivityKind,TerminalFlowProceduralActivitySourceId> =
            { source = source; ageMs = max 0L ageMs; count = max 0L count }

        let private terminalFlowActivityTokenText kind sourceText (token:TerminalFlowActivityToken<'Kind,'Source>) =
            FastRuntimeFormat.format "activity:%s|source=%s|age_ms=%d|count=%d" [| box kind; box (sourceText token.source); box token.ageMs; box token.count |]

        let private terminalFlowActivityObservationText = function
            | TerminalFlowMaterialActivityRecent token -> terminalFlowActivityTokenText "material_recent" terminalFlowMaterialActivitySourceText token
            | TerminalFlowMaterialQuiescent(materialAgeMs, None) -> sprintf "activity:material_quiescent|age_ms=%d|procedural=none" materialAgeMs
            | TerminalFlowMaterialQuiescent(materialAgeMs, Some procedural) ->
                sprintf "activity:material_quiescent|age_ms=%d|%s" materialAgeMs (terminalFlowActivityTokenText "procedural_churn" terminalFlowProceduralActivitySourceText procedural)

        let private terminalFlowQapBoundednessText = function
            | TerminalFlowQapBounded -> "bounded"
            | TerminalFlowQapUnbounded -> "unbounded"

        let private terminalFlowQapOccupancyText = function
            | TerminalFlowQapEmpty -> "empty"
            | TerminalFlowQapResidual -> "residual"

        let private terminalFlowQapIsBounded (x:TerminalFlowQapObservation) =
            match x.boundedness with
            | TerminalFlowQapBounded -> true
            | TerminalFlowQapUnbounded -> false

        let private terminalFlowQapHasResidual (x:TerminalFlowQapObservation) =
            match x.occupancy with
            | TerminalFlowQapResidual -> true
            | TerminalFlowQapEmpty -> false

        let private terminalFlowRejectedQapObservation pending queue active : TerminalFlowQapObservation =
            let sampledEvidence = max 0 pending
            let quarantineRef =
                NativeCutoverStableRef.ref32
                    "rejected-qap-synthetic"
                    [ string sampledEvidence; string queue; string active ]
            let safeCanonical = 1
            let provenance =
                { rawPending = sampledEvidence
                  frontierPending = 0
                  canonicalPending = safeCanonical
                  authority = TerminalFlowPendingFrontierUnavailableQuarantine quarantineRef
                  decrementReceipts = []
                  decision = TerminalFlowPendingDecisionBlockedWithoutFrontier(sampledEvidence, TerminalFlowPendingRejectedSyntheticObservation, quarantineRef) }
            { pending = safeCanonical
              pendingProvenance = provenance
              queue = queue
              active = active
              semanticLedgerState = SemanticWorkOpen(1L, 0L, 1L)
              semanticOpen = 1L
              boundedness = TerminalFlowQapUnbounded
              occupancy = TerminalFlowQapResidual }

        let private terminalFlowQapFixpointMaturityText = function
            | TerminalFlowQapFixpointAwaitingReducerWitness -> "awaiting_reducer_witness"
            | TerminalFlowQapFixpointCandidateObserved -> "candidate_observed"
            | TerminalFlowQapFixpointWitnessedByReducer -> "witnessed_by_reducer"

        let private terminalFlowQapFixpointIsCandidate = function
            | TerminalFlowQapFixpointCandidateObserved -> true
            | TerminalFlowQapFixpointAwaitingReducerWitness
            | TerminalFlowQapFixpointWitnessedByReducer -> false

        let private terminalFlowPendingLedgerAuthorityText = function
            | TerminalFlowPendingFrontierAuthoritative -> "frontier_authoritative"
            | TerminalFlowPendingFrontierReconciledGhosts -> "frontier_reconciled_ghosts"
            | TerminalFlowPendingFrontierUnavailableRawZeroClosed closeReceiptRef -> "frontier_unavailable_raw_zero_closed:" + string closeReceiptRef
            | TerminalFlowPendingFrontierUnavailableReducerClosed closeReceiptRef -> "frontier_unavailable_reducer_closed:" + string closeReceiptRef
            | TerminalFlowPendingFrontierUnavailableQuarantine quarantineRef -> "frontier_unavailable_quarantine:" + string quarantineRef

        let private terminalFlowPendingDecrementSourceText = function
            | TerminalFlowPendingDecrementInlineCallbackCommit -> "inline_callback_commit"
            | TerminalFlowPendingDecrementReducerFrontierReconcile -> "reducer_frontier_reconcile"
            | TerminalFlowPendingDecrementReducerClosedProjection -> "reducer_closed_projection"
            | TerminalFlowPendingDecrementParentCommit -> "parent_commit"
            | TerminalFlowPendingDecrementUnknown raw -> "unknown:" + raw

        let private terminalFlowPendingQuarantineReasonText = function
            | TerminalFlowPendingRejectedSyntheticObservation -> "rejected_synthetic_observation"
            | TerminalFlowPendingFrontierSnapshotMissing -> "frontier_snapshot_missing"

        let private terminalFlowPendingDecisionText = function
            | TerminalFlowPendingDecisionFrontierCanonical canonicalPending -> sprintf "frontier_canonical:%d" canonicalPending
            | TerminalFlowPendingDecisionRawZeroClosedWithoutFrontier closeReceiptRef ->
                sprintf "raw_zero_closed_without_frontier:receipt=%u" closeReceiptRef
            | TerminalFlowPendingDecisionReducerClosedWithoutFrontier closeReceiptRef ->
                sprintf "reducer_closed_without_frontier:receipt=%u" closeReceiptRef
            | TerminalFlowPendingDecisionBlockedWithoutFrontier(sampledEvidence, reason, quarantineRef) ->
                FastRuntimeFormat.format "blocked_without_frontier:sampled=%d:reason=%s:quarantine=%u" [| box sampledEvidence; box (terminalFlowPendingQuarantineReasonText reason); box quarantineRef |]

        let private terminalFlowPendingDecrementReceiptText (x:TerminalFlowPendingDecrementReceipt) =
            FastRuntimeFormat.format "decrement(source=%s|raw=%d->%d|frontier=%d|canonical=%d|receipt=%u)" [| box (terminalFlowPendingDecrementSourceText x.source); box x.beforeRaw; box x.afterRaw; box x.frontierPending; box x.canonicalPending; box x.exactOnceRef |]

        let private terminalFlowPendingDecrementReceiptsFor raw frontier canonical authority =
            if raw > canonical then
                let source =
                    match authority with
                    | TerminalFlowPendingFrontierReconciledGhosts -> TerminalFlowPendingDecrementReducerFrontierReconcile
                    | TerminalFlowPendingFrontierAuthoritative -> TerminalFlowPendingDecrementInlineCallbackCommit
                    | TerminalFlowPendingFrontierUnavailableRawZeroClosed _ -> TerminalFlowPendingDecrementUnknown "raw_zero_closed_no_decrement"
                    | TerminalFlowPendingFrontierUnavailableReducerClosed _ -> TerminalFlowPendingDecrementReducerClosedProjection
                    | TerminalFlowPendingFrontierUnavailableQuarantine _ -> TerminalFlowPendingDecrementUnknown "frontier_unavailable_no_decrement_authority"
                [ { source = source
                    beforeRaw = raw
                    afterRaw = canonical
                    frontierPending = frontier
                    canonicalPending = canonical
                    exactOnceRef =
                        NativeCutoverStableRef.ref32
                            "terminal-pending-decrement"
                            [ terminalFlowPendingDecrementSourceText source
                              string raw
                              string frontier
                              string canonical
                              terminalFlowPendingLedgerAuthorityText authority ] } ]
            else
                []

        let private terminalFlowPendingProvenanceFor rawPending frontierPending frontierAvailable closureProof =
            let raw = max 0 rawPending
            let frontier = max 0 frontierPending
            if frontierAvailable then
                let authority = if raw = frontier then TerminalFlowPendingFrontierAuthoritative else TerminalFlowPendingFrontierReconciledGhosts
                let canonical = frontier
                { rawPending = raw
                  frontierPending = frontier
                  canonicalPending = canonical
                  authority = authority
                  decrementReceipts = terminalFlowPendingDecrementReceiptsFor raw frontier canonical authority
                  decision = TerminalFlowPendingDecisionFrontierCanonical canonical }
            else
                match closureProof with
                | TerminalFlowPendingClosureReducerExact closeReceiptRef ->
                    let authority = TerminalFlowPendingFrontierUnavailableReducerClosed closeReceiptRef
                    { rawPending = raw
                      frontierPending = frontier
                      canonicalPending = 0
                      authority = authority
                      decrementReceipts = terminalFlowPendingDecrementReceiptsFor raw frontier 0 authority
                      decision = TerminalFlowPendingDecisionReducerClosedWithoutFrontier closeReceiptRef }
                | TerminalFlowPendingClosureUnproven when raw = 0 && frontier = 0 ->
                    let closeReceiptRef =
                        NativeCutoverStableRef.ref32
                            "frontier-snapshot-missing-raw-zero-closed"
                            [ string raw; string frontier ]
                    { rawPending = raw
                      frontierPending = frontier
                      canonicalPending = 0
                      authority = TerminalFlowPendingFrontierUnavailableRawZeroClosed closeReceiptRef
                      decrementReceipts = []
                      decision = TerminalFlowPendingDecisionRawZeroClosedWithoutFrontier closeReceiptRef }
                | TerminalFlowPendingClosureUnproven ->
                    let quarantineRef =
                        NativeCutoverStableRef.ref32
                            "frontier-snapshot-missing"
                            [ string raw; string frontier ]
                    let authority = TerminalFlowPendingFrontierUnavailableQuarantine quarantineRef
                    let safeCanonical = max 1 raw
                    { rawPending = raw
                      frontierPending = frontier
                      canonicalPending = safeCanonical
                      authority = authority
                      decrementReceipts = []
                      decision = TerminalFlowPendingDecisionBlockedWithoutFrontier(raw, TerminalFlowPendingFrontierSnapshotMissing, quarantineRef) }

        let private terminalFlowPendingProvenanceText (x:TerminalFlowPendingProvenance) =
            let decrementText = x.decrementReceipts |> List.map terminalFlowPendingDecrementReceiptText |> String.concat ";"
            FastRuntimeFormat.format "pending(raw=%d|frontier=%d|canonical=%d|authority=%s|decision=%s|decrement_receipts=%d|decrements=%s)" [| box x.rawPending; box x.frontierPending; box x.canonicalPending; box (terminalFlowPendingLedgerAuthorityText x.authority); box (terminalFlowPendingDecisionText x.decision); box x.decrementReceipts.Length; box decrementText |]

        let private terminalFlowQapObservationText (x:TerminalFlowQapObservation) =
            FastRuntimeFormat.format "qap:p=%d/q=%d/a=%d|%s|boundedness=%s|occupancy=%s" [| box x.pending; box x.queue; box x.active; box (terminalFlowPendingProvenanceText x.pendingProvenance); box (terminalFlowQapBoundednessText x.boundedness); box (terminalFlowQapOccupancyText x.occupancy) |]

        let private terminalFlowQapFixpointRefText (TerminalFlowQapFixpointRef value) =
            CompilerIdentityKernel.InternedTextId.text value

        let private terminalFlowQapFixpointSiteText = function
            | TerminalFlowQapCacheHandoffApplyArg0Child -> "cache_handoff_child_apply_arg_0"
            | TerminalFlowQapParentContinuationPoison -> "parent_continuation_poison"
            | TerminalFlowQapDynamicBridgePoison -> "dynamic_bridge_poison"
            | TerminalFlowQapPendingOwner -> "pending_owner"
            | TerminalFlowQapUnknownSite raw ->
                "unknown:" + TerminalFlowQapUnknownTextIdOps.text raw

        let private terminalFlowQapNodeIdText = function
            | TerminalFlowQapCacheHandoffChildApplyArg0Node -> "cache_handoff@child:*:apply_arg_0"
            | TerminalFlowQapParentPoisonTerminalTailNode -> "parent_poison@terminal_tail"
            | TerminalFlowQapPendingOwnerTerminalTailNode -> "pending_owner@terminal_tail"
            | TerminalFlowQapUnknownNode raw ->
                "unknown:" + TerminalFlowQapUnknownTextIdOps.text raw

        let private terminalFlowQapEvidenceWitnessText = function
            | TerminalFlowQapPrimaryFixpointWitness -> "terminal_qap_fixpoint_primary"
            | TerminalFlowQapActiveTailWitness -> "terminal_qap_fixpoint_active"
            | TerminalFlowQapPendingOwnerWitness -> "terminal_qap_fixpoint_pending"
            | TerminalFlowQapUnknownWitness raw ->
                "unknown:" + TerminalFlowQapUnknownTextIdOps.text raw

        let private terminalFlowQapRelationKindText = function
            | TerminalFlowQapCacheHandoffEdge -> "cache_handoff"
            | TerminalFlowQapParentContinuationEdge -> "parent_continuation"
            | TerminalFlowQapDynamicBridgeEdge -> "dynamic_bridge"
            | TerminalFlowQapPendingOwnerEdge -> "pending_owner"

        let private terminalFlowQapRelationConsumptionText = function
            | TerminalFlowQapRelationUnconsumed -> "unconsumed"
            | TerminalFlowQapRelationConsumedExactOnce(receiptRef, reducerSequence) -> sprintf "consumed_exact_once:receipt=%u:seq=%d" receiptRef reducerSequence
            | TerminalFlowQapRelationConsumptionRejected reason ->
                "consumption_rejected:" + TerminalFlowQapRelationRejectionReasonId.text reason

        let rec private terminalFlowQapRelationText = function
            | TerminalFlowQapRelationLeaf(node, witness, consumption) ->
                FastRuntimeFormat.format "Leaf(node=%s|witness=%s|consumption=%s)" [| box (terminalFlowQapNodeIdText node); box (terminalFlowQapEvidenceWitnessText witness); box (terminalFlowQapRelationConsumptionText consumption) |]
            | TerminalFlowQapRelationParentChild(parent, edge, child, consumption) ->
                FastRuntimeFormat.format "ParentChild(parent=%s|edge=%s|child=%s|consumption=%s)" [| box (terminalFlowQapNodeIdText parent); box (terminalFlowQapRelationKindText edge); box (terminalFlowQapRelationText child); box (terminalFlowQapRelationConsumptionText consumption) |]
            | TerminalFlowQapRelationCycle(head, edge, path, consumption) ->
                FastRuntimeFormat.format "Cycle(head=%s|edge=%s|path=[%s]|consumption=%s)" [| box (terminalFlowQapNodeIdText head); box (terminalFlowQapRelationKindText edge); box (path |> List.map terminalFlowQapRelationText |> String.concat ";"); box (terminalFlowQapRelationConsumptionText consumption) |]

        let private terminalFlowQapRelationFor site node witness =
            let pendingConsumption = TerminalFlowQapRelationUnconsumed
            let leaf = TerminalFlowQapRelationLeaf(node, witness, pendingConsumption)
            match site with
            | TerminalFlowQapCacheHandoffApplyArg0Child ->
                TerminalFlowQapRelationParentChild(TerminalFlowQapParentPoisonTerminalTailNode, TerminalFlowQapCacheHandoffEdge, leaf, pendingConsumption)
            | TerminalFlowQapParentContinuationPoison ->
                TerminalFlowQapRelationCycle(TerminalFlowQapParentPoisonTerminalTailNode, TerminalFlowQapParentContinuationEdge, [leaf], pendingConsumption)
            | TerminalFlowQapDynamicBridgePoison ->
                TerminalFlowQapRelationParentChild(TerminalFlowQapParentPoisonTerminalTailNode, TerminalFlowQapDynamicBridgeEdge, leaf, pendingConsumption)
            | TerminalFlowQapPendingOwner ->
                TerminalFlowQapRelationParentChild(TerminalFlowQapPendingOwnerTerminalTailNode, TerminalFlowQapPendingOwnerEdge, leaf, pendingConsumption)
            | TerminalFlowQapUnknownSite _ -> leaf

        let rec private terminalFlowQapRelationConsume reducerSequence relation =
            let existingReceiptRef =
                match relation with
                | TerminalFlowQapRelationLeaf(_, _, TerminalFlowQapRelationConsumedExactOnce(existingRef, _))
                | TerminalFlowQapRelationParentChild(_, _, _, TerminalFlowQapRelationConsumedExactOnce(existingRef, _))
                | TerminalFlowQapRelationCycle(_, _, _, TerminalFlowQapRelationConsumedExactOnce(existingRef, _)) -> Some existingRef
                | _ -> None
            match existingReceiptRef with
            | Some existingRef ->
                TerminalFlowQapRelationProtocolConsumed(relation, existingRef)
            | None ->
                // Reducer sequence records when consumption was observed; it is not
                // receipt identity. One causal relation owns one receipt.
                let receiptRef =
                    terminalFlowQapLocalMintedRefOf
                        "qap_relation_consumption_ref"
                        (terminalFlowQapRelationText relation)
                let consumed = TerminalFlowQapRelationConsumedExactOnce(receiptRef, reducerSequence)
                let consumedRelation =
                    match relation with
                    | TerminalFlowQapRelationLeaf(node, witness, TerminalFlowQapRelationUnconsumed) ->
                        TerminalFlowQapRelationLeaf(node, witness, consumed)
                    | TerminalFlowQapRelationParentChild(parent, edge, child, TerminalFlowQapRelationUnconsumed) ->
                        let childState = terminalFlowQapRelationConsume reducerSequence child
                        let childRelation =
                            match childState with
                            | TerminalFlowQapRelationProtocolConsumed(value, _) -> value
                            | TerminalFlowQapRelationProtocolClosed(value, _) -> value
                            | TerminalFlowQapRelationProtocolCanonicalized(value, _)
                            | TerminalFlowQapRelationProtocolObserved value
                            | TerminalFlowQapRelationProtocolPoisoned(value, _) -> value
                        TerminalFlowQapRelationParentChild(parent, edge, childRelation, consumed)
                    | TerminalFlowQapRelationCycle(head, edge, path, TerminalFlowQapRelationUnconsumed) ->
                        let consumedPath =
                            path
                            |> List.map (fun item ->
                                match terminalFlowQapRelationConsume reducerSequence item with
                                | TerminalFlowQapRelationProtocolConsumed(value, _) -> value
                                | TerminalFlowQapRelationProtocolClosed(value, _) -> value
                                | TerminalFlowQapRelationProtocolCanonicalized(value, _)
                                | TerminalFlowQapRelationProtocolObserved value
                                | TerminalFlowQapRelationProtocolPoisoned(value, _) -> value)
                        TerminalFlowQapRelationCycle(head, edge, consumedPath, consumed)
                    | _ -> relation
                TerminalFlowQapRelationProtocolConsumed(consumedRelation, receiptRef)

        let private terminalFlowQapRelationProtocolValue = function
            | TerminalFlowQapRelationProtocolObserved relation -> relation, 0u
            | TerminalFlowQapRelationProtocolCanonicalized(relation, receiptRef)
            | TerminalFlowQapRelationProtocolConsumed(relation, receiptRef)
            | TerminalFlowQapRelationProtocolClosed(relation, receiptRef) -> relation, receiptRef
            | TerminalFlowQapRelationProtocolPoisoned(relation, _) -> relation, 0u

        let private terminalFlowQapFixpointConsumeRelations reducerSequence (fixpoint:TerminalFlowQapFixpointSet) =
            let consumed =
                fixpoint.items
                |> List.map (fun item ->
                    let relation, receiptRef =
                        item.relation
                        |> terminalFlowQapRelationConsume reducerSequence
                        |> terminalFlowQapRelationProtocolValue
                    { item with relation = relation }, receiptRef)
            let consumedItems = consumed |> List.map fst
            let receiptRefs = consumed |> List.map snd |> List.filter (fun receiptRef -> receiptRef <> 0u)
            { fixpoint with
                items = consumedItems
                maturity = TerminalFlowQapFixpointWitnessedByReducer
                terminalDecision = TerminalFlowQapCandidateTerminalErrorOrQuarantine },
            receiptRefs

        let rec private terminalFlowQapRelationIsConsumed = function
            | TerminalFlowQapRelationLeaf(_, _, TerminalFlowQapRelationConsumedExactOnce _)
            | TerminalFlowQapRelationParentChild(_, _, _, TerminalFlowQapRelationConsumedExactOnce _)
            | TerminalFlowQapRelationCycle(_, _, _, TerminalFlowQapRelationConsumedExactOnce _) -> true
            | _ -> false

        let private terminalFlowQapFixpointAllRelationsConsumed (fixpoint:TerminalFlowQapFixpointSet) =
            fixpoint.items |> List.forall (fun item -> terminalFlowQapRelationIsConsumed item.relation)

        let private terminalFlowQapTerminalDecisionText = function
            | TerminalFlowQapAwaitMaterialOrWaker -> "await_material_or_waker"
            | TerminalFlowQapCandidateTerminalErrorOrQuarantine -> "terminal_error_or_quarantine_candidate"
            | TerminalFlowQapAwaitReducerFourClockWitness -> "await_reducer_four_clock_witness"

        let private terminalFlowQapFixpointItemText (x:TerminalFlowQapFixpointItem) =
            FastRuntimeFormat.format "qap_item(ref=%s|site=%s|node=%s|relation=%s|repeat=%d/%d|material_delta=%d|witness=%s)" [| box (terminalFlowQapFixpointRefText x.itemRef); box (terminalFlowQapFixpointSiteText x.site); box (terminalFlowQapNodeIdText x.nodeId); box (terminalFlowQapRelationText x.relation); box x.repeatCount; box x.repeatCap; box x.materialDelta; box (terminalFlowQapEvidenceWitnessText x.lastWitness) |]

        let private terminalFlowQapFixpointSetText (x:TerminalFlowQapFixpointSet) =
            let items = x.items |> List.map terminalFlowQapFixpointItemText |> String.concat ";"
            FastRuntimeFormat.format "QapFixpoint(set=%s|items=%d|material_age_ms=%d|maturity=%s|mature=%b|decision=%s|top_k=%s)" [| box (terminalFlowQapFixpointRefText x.setRef); box x.items.Length; box x.materialQuiescenceAgeMs; box (terminalFlowQapFixpointMaturityText x.maturity); box (terminalFlowQapFixpointIsCandidate x.maturity); box (terminalFlowQapTerminalDecisionText x.terminalDecision); box items |]

        let private terminalFlowAwaitingObservationReasonText = function
            | TerminalFlowAwaitingQapFixpointMaterial(rootReceipt, leaseId, tailId, fixpoint) ->
                "qap_fixpoint_awaiting_material|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|" + terminalFlowQapFixpointSetText fixpoint
            | TerminalFlowAwaitingRecentMaterialActivity token ->
                "recent_material_activity|" + terminalFlowActivityTokenText "material_recent" terminalFlowMaterialActivitySourceText token
            | TerminalFlowAwaitingRejectedTopology qap ->
                "rejected_topology|" + terminalFlowQapObservationText qap
            | TerminalFlowAwaitingWakerRegistrationRequired(leaseId, tailId, obligationId, nextWakeAfterMs) ->
                FastRuntimeFormat.format "waker_registration_required|lease=%s|tail=%s|obligation=%s|next_wake_after_ms=%d" [| box leaseId; box tailId; box obligationId; box nextWakeAfterMs |]
            | TerminalFlowAwaitingWriterLeaseLive(leaseId, tailId, ageMs) ->
                FastRuntimeFormat.format "writer_lease_live|lease=%s|tail=%s|age_ms=%d" [| box leaseId; box tailId; box ageMs |]
            | TerminalFlowAwaitingGenericObservation -> "observe"
            | TerminalFlowAwaitingOperationalReason reason -> CompilerKernelV2.OperationalReasonIdOps.text reason

        let private terminalFlowQapFixpointRefFor nodeId _repeatCount : TerminalFlowQapFixpointRef<TerminalFlowQapFixpointItemRefKind> =
            // Repeat magnitude is evidence, never exact-once identity. The same causal
            // QAP relation must dereference one item while q/a/p churns.
            terminalFlowQapFixpointRefCreate (sprintf "qap-item:%s" (terminalFlowQapNodeIdText nodeId))

        let private terminalFlowQapFixpointSetRefFor (qap:TerminalFlowQapObservation) _materialAgeMs : TerminalFlowQapFixpointRef<TerminalFlowQapFixpointSetRefKind> =
            // Stable causal identity: queue magnitudes and wall-clock age are
            // observations, not identity. This lets the reducer watch one culprit
            // set across structural churn and mature it on semantic quiescence.
            terminalFlowQapFixpointRefCreate (
                FastRuntimeFormat.format "qap-fixpoint:canonical_pending=%b|queue=%b|semantic_ledger_state=%s|pending_authority=%s" [| box (qap.pending > 0); box (qap.queue > 0); box (SemanticWorkLedgerProjection.stateClassTextOf qap.semanticLedgerState); box (terminalFlowPendingLedgerAuthorityText qap.pendingProvenance.authority) |])

        let private terminalFlowQapFixpointFromObservation materialAgeMs repeatCap (qap:TerminalFlowQapObservation) : TerminalFlowQapFixpointSet =
            let mk site node repeat delta witness =
                { itemRef = terminalFlowQapFixpointRefFor node repeat
                  site = site
                  nodeId = node
                  relation = terminalFlowQapRelationFor site node witness
                  repeatCount = max 0L repeat
                  repeatCap = max 1L repeatCap
                  materialDelta = max 0L delta
                  lastWitness = witness }
            let reducerClosedWithoutFrontier =
                match qap.pendingProvenance.authority with
                | TerminalFlowPendingFrontierUnavailableReducerClosed _ -> true
                | _ -> false
            let primarySite = if qap.queue > 0 then TerminalFlowQapCacheHandoffApplyArg0Child elif qap.active > 0 then TerminalFlowQapParentContinuationPoison else TerminalFlowQapDynamicBridgePoison
            // A QAP repeat is an observation of unchanged causal state, not queue magnitude.
            // The MIGRATION tail stayed at q=1/a=1/p=2 for more than twelve minutes, so
            // occupancy-derived repeats could never reach the cap of four.  Quiescence
            // seconds provide a monotonic observation epoch while remaining outside identity.
            let quiescentRepeat = max 1L (materialAgeMs / 1000L)
            let primaryRepeat = quiescentRepeat
            let items =
                [ if qap.queue > 0 || qap.active > 0 || qap.pending > 0 then
                      yield mk primarySite TerminalFlowQapCacheHandoffChildApplyArg0Node primaryRepeat 0L TerminalFlowQapPrimaryFixpointWitness
                  if qap.active > 0 then yield mk TerminalFlowQapParentContinuationPoison TerminalFlowQapParentPoisonTerminalTailNode quiescentRepeat 0L TerminalFlowQapActiveTailWitness
                  if qap.pending > 0 then yield mk TerminalFlowQapPendingOwner TerminalFlowQapPendingOwnerTerminalTailNode quiescentRepeat 0L TerminalFlowQapPendingOwnerWitness ]
            let maturityThresholdMs = if reducerClosedWithoutFrontier then 1000L else 4000L
            let candidateMature =
                (terminalFlowQapHasResidual qap || reducerClosedWithoutFrontier)
                && (terminalFlowQapIsBounded qap || (qap.pending = 0 && qap.active >= 0 && qap.active <= 4))
                && qap.semanticOpen = 0L
                && materialAgeMs >= maturityThresholdMs
                && (items |> List.forall (fun (item:TerminalFlowQapFixpointItem) -> item.materialDelta = 0L && item.repeatCount >= item.repeatCap))
            { setRef = terminalFlowQapFixpointSetRefFor qap materialAgeMs
              items = items
              materialQuiescenceAgeMs = max 0L materialAgeMs
              maturity = if candidateMature then TerminalFlowQapFixpointCandidateObserved else TerminalFlowQapFixpointAwaitingReducerWitness
              terminalDecision = if candidateMature then TerminalFlowQapCandidateTerminalErrorOrQuarantine else TerminalFlowQapAwaitMaterialOrWaker }

        // A physically and semantically closed graph has a positive empty relation-set
        // witness. It must enter the same reducer finalizer as an observed QAP rather
        // than remaining Idle merely because no residual relation existed to open a watch.
        let private terminalFlowQapClosedGraphFixpointFor identity materialAgeMs : TerminalFlowQapFixpointSet =
            { setRef = terminalFlowQapFixpointRefCreate ("qap-fixpoint:closed-graph:" + identity)
              items = []
              materialQuiescenceAgeMs = max 0L materialAgeMs
              maturity = TerminalFlowQapFixpointCandidateObserved
              terminalDecision = TerminalFlowQapAwaitReducerFourClockWitness }

        let private terminalFlowQapProtocolIdValue (TerminalFlowQapProtocolId value) = value

        let private terminalFlowQapRelationRef relation =
            terminalFlowQapLocalMintedRefOf
                "qap_relation_ref"
                (terminalFlowQapRelationText relation)

        let private terminalFlowQapRelationResolutionReceiptFor reducerSequence materialEpoch resolution relation =
            let relationRef = terminalFlowQapRelationRef relation
            let receiptIdentity =
                FastRuntimeFormat.format "qap-relation-resolution:%u:%d:%s" [| box relationRef; box reducerSequence; box (terminalFlowQapRelationResolutionText resolution) |]
            { receiptRef = TerminalFlowQapProtocolId(uint64 (terminalFlowQapLocalMintedRefOf "qap_relation_resolution_receipt_ref" receiptIdentity))
              relationRef = relationRef
              resolution = resolution
              materialEpochBefore = materialEpoch
              materialEpochAfter = materialEpoch
              reducerSequence = reducerSequence }

        let private terminalFlowQapTypedFor<'Stage>
            semanticDigestRef
            proceduralDigestRef
            relationSetRef
            materialEpoch
            (fixpoint:TerminalFlowQapFixpointSet)
            : TerminalFlowQap<TerminalFlowQapFixpointSetRefKind,'Stage> =
            let setText = terminalFlowQapFixpointRefText fixpoint.setRef
            { qapRef = TerminalFlowQapProtocolId(uint64 (terminalFlowQapLocalMintedRefOf "qap_protocol_ref" setText))
              semanticDigestRef = semanticDigestRef
              proceduralDigestRef = proceduralDigestRef
              relationSetRef = relationSetRef
              materialEpoch = materialEpoch
              relations = fixpoint.items |> List.map (fun (item:TerminalFlowQapFixpointItem) -> item.relation)
              fixpoint = fixpoint }

        let private terminalFlowQapResolutionText = function
            | TerminalFlowQapMaterialProgressBox qap ->
                sprintf "MaterialProgress(qap_ref=%d|material_epoch=%d)" (terminalFlowQapProtocolIdValue qap.qapRef) qap.materialEpoch
            | TerminalFlowQapFullyDrainedBox(qap, proof) ->
                FastRuntimeFormat.format "FullyDrained(qap_ref=%d|proof_ref=%d|relations=%d|authority=%s)" [| box (terminalFlowQapProtocolIdValue qap.qapRef); box (terminalFlowQapProtocolIdValue proof.proofRef); box proof.relationReceipts.Length; box (terminalFlowQapDrainAuthorityText proof.drainAuthority) |]
            | TerminalFlowQapProvenDeadlockBox(qap, proof) ->
                FastRuntimeFormat.format "ProvenDeadlock(qap_ref=%d|proof_ref=%d|relations=%d|reducer_sequence=%d)" [| box (terminalFlowQapProtocolIdValue qap.qapRef); box (terminalFlowQapProtocolIdValue proof.proofRef); box proof.relationReceipts.Length; box proof.reducerSequence |]

        let private terminalFlowQapResolutionBoxRef = function
            | TerminalFlowQapMaterialProgressBox qap -> uint32 (terminalFlowQapProtocolIdValue qap.qapRef)
            | TerminalFlowQapFullyDrainedBox(_, proof) -> uint32 (terminalFlowQapProtocolIdValue proof.proofRef)
            | TerminalFlowQapProvenDeadlockBox(_, proof) -> uint32 (terminalFlowQapProtocolIdValue proof.proofRef)

        let private terminalFlowQapResolvePositive
            reducerSequence
            semanticDigestRef
            proceduralDigestRef
            materialEpoch
            quiescenceDigest
            noPendingRebase
            (fixpoint:TerminalFlowQapFixpointSet)
            : TerminalFlowQapResolutionBox =
            let relationSetText =
                fixpoint.items
                |> List.map (fun (item:TerminalFlowQapFixpointItem) -> terminalFlowQapRelationText item.relation)
                |> String.concat "|"
            let relationSetRef = terminalFlowQapLocalMintedRefOf "qap_relation_set_ref" relationSetText
            let allRelationsConsumed = terminalFlowQapFixpointAllRelationsConsumed fixpoint
            let drained = fixpoint.items.IsEmpty || allRelationsConsumed
            let relationReceipts disposition =
                fixpoint.items
                |> List.map (fun item ->
                    let relationRef = terminalFlowQapRelationRef item.relation
                    let receiptRef = terminalFlowQapLocalMintedRefOf "qap_relation_disposition_ref" (string relationRef + ":" + disposition)
                    let resolution =
                        if terminalFlowQapRelationIsConsumed item.relation then
                            TerminalFlowQapRelationConsumed(relationRef, receiptRef)
                        elif disposition = "deadlocked" then
                            TerminalFlowQapRelationDeadlocked(relationRef, receiptRef)
                        else
                            TerminalFlowQapRelationRegistered(relationRef, None)
                    terminalFlowQapRelationResolutionReceiptFor reducerSequence materialEpoch resolution item.relation)
            match quiescenceDigest with
            | Some creditDigest when drained ->
                let qap = terminalFlowQapTypedFor<TerminalFlowQapDrainedStage> semanticDigestRef proceduralDigestRef relationSetRef materialEpoch fixpoint
                let receipts = relationReceipts "drained"
                let proofIdentity = FastRuntimeFormat.format "qap-drain-proof:%d:%u:%d" [| box reducerSequence; box relationSetRef; box materialEpoch |]
                let proof =
                    { proofRef = TerminalFlowQapProtocolId(uint64 (terminalFlowQapLocalMintedRefOf "qap_drain_proof_ref" proofIdentity))
                      qapRef = qap.qapRef
                      relationReceipts = receipts
                      drainAuthority = if fixpoint.items.IsEmpty then TerminalFlowQapDrainByEmptyRelationSet else TerminalFlowQapDrainByExactOnceConsumption (List.length fixpoint.items)
                      materialEpoch = materialEpoch
                      reducerSequence = reducerSequence }
                TerminalFlowQapFullyDrainedBox(qap, proof)
            | Some creditDigest when noPendingRebase ->
                let qap = terminalFlowQapTypedFor<TerminalFlowQapDeadlockedStage> semanticDigestRef proceduralDigestRef relationSetRef materialEpoch fixpoint
                let receipts = relationReceipts "deadlocked"
                let proofIdentity =
                    FastRuntimeFormat.format "qap-deadlock-proof:%d:%u:%s" [| box reducerSequence; box relationSetRef; box (CompilerIdentityKernel.ContentDigest.text creditDigest) |]
                let proof =
                    { proofRef = TerminalFlowQapProtocolId(uint64 (terminalFlowQapLocalMintedRefOf "qap_deadlock_proof_ref" proofIdentity))
                      qapRef = qap.qapRef
                      quiescence = TerminalFlowQapQuiescenceWitness creditDigest
                      noPendingRebase = TerminalFlowQapNoPendingRebaseWitness reducerSequence
                      relationReceipts = receipts
                      reducerSequence = reducerSequence }
                TerminalFlowQapProvenDeadlockBox(qap, proof)
            | _ ->
                let qap = terminalFlowQapTypedFor<TerminalFlowQapProgressingStage> semanticDigestRef proceduralDigestRef relationSetRef materialEpoch fixpoint
                TerminalFlowQapMaterialProgressBox qap

        let private terminalFlowObservationText (x:TerminalFlowObservation) =
            "TerminalFlowObservation("
            + terminalFlowRootObservationText x.root
            + "|" + terminalFlowWriterObservationText x.writer
            + "|" + terminalFlowTailObservationText x.tail
            + "|" + terminalFlowOwnerObservationText x.owners
            + "|" + terminalFlowQapObservationText x.qap
            + "|" + terminalFlowActivityObservationText x.activity
            + ")"

        let private terminalFlowTransitionDecisionText = function
            | TerminalFlowTransitionObserve -> "TerminalFlowTransition(Observe)"
            | TerminalFlowTransitionDeferMaterialActivity token -> terminalFlowActivityTokenText "defer_material" terminalFlowMaterialActivitySourceText token
            | TerminalFlowTransitionRejectTopology qap -> "TerminalFlowTransition(RejectTopology|" + terminalFlowQapObservationText qap + ")"
            | TerminalFlowTransitionRegisterWakerEdge(rootReceipt, leaseId, tailId, obligationId, nextWakeAfterMs) -> FastRuntimeFormat.format "TerminalFlowTransition(RegisterWakerEdge|root=%s|lease=%s|tail=%s|obligation=%s|next_wake_after_ms=%d)" [| box rootReceipt; box leaseId; box tailId; box obligationId; box nextWakeAfterMs |]
            | TerminalFlowTransitionWriterLeaseLive(rootReceipt, leaseId, tailId, ageMs) -> FastRuntimeFormat.format "TerminalFlowTransition(WriterLeaseLive|root=%s|lease=%s|tail=%s|age_ms=%d)" [| box rootReceipt; box leaseId; box tailId; box ageMs |]
            | TerminalFlowTransitionWriterLeaseExpired(rootReceipt, leaseId, tailId, ageMs, qap) -> FastRuntimeFormat.format "TerminalFlowTransition(WriterLeaseExpired|root=%s|lease=%s|tail=%s|age_ms=%d|%s)" [| box rootReceipt; box leaseId; box tailId; box ageMs; box (terminalFlowQapObservationText qap) |]
            | TerminalFlowTransitionQuarantineResidualQap(rootReceipt, leaseId, tailId, ageMs, qap) -> FastRuntimeFormat.format "TerminalFlowTransition(QuarantineResidualQap|root=%s|lease=%s|tail=%s|age_ms=%d|%s)" [| box rootReceipt; box leaseId; box tailId; box ageMs; box (terminalFlowQapObservationText qap) |]
            | TerminalFlowTransitionQapFixpointMatured(rootReceipt, leaseId, tailId, fixpoint) -> "TerminalFlowTransition(QapFixpointMatured|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|" + terminalFlowQapFixpointSetText fixpoint + ")"
            | TerminalFlowTransitionQapFixpointAwaitingMaterial(rootReceipt, leaseId, tailId, fixpoint) -> "TerminalFlowTransition(QapFixpointAwaitingMaterial|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|" + terminalFlowQapFixpointSetText fixpoint + ")"
            | TerminalFlowTransitionForceCloseResidual(rootReceipt, leaseId, tailId, ownerCloseReceiptId, workDagTailCloseReceipt) -> FastRuntimeFormat.format "TerminalFlowTransition(ForceCloseResidual|root=%s|lease=%s|tail=%s|owner_close_receipt=%s|workdag_close=%s)" [| box rootReceipt; box leaseId; box tailId; box ownerCloseReceiptId; box workDagTailCloseReceipt |]
            | TerminalFlowTransitionBindWriter(rootReceipt, writerReceiptId, tailId) -> "TerminalFlowTransition(BindWriter|root=" + rootReceipt + "|writer=" + writerReceiptId + "|tail=" + tailId + ")"
            | TerminalFlowTransitionDeadlockTail(rootReceipt, leaseId, tailId, proof) ->
                "TerminalFlowTransition(DeadlockTail|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|proof=" + CompilerKernelV2.TerminalTailDeadlockProofIdOps.text proof + ")"
            | TerminalFlowTransitionQuarantineTail(rootReceipt, leaseId, tailId, reason) ->
                "TerminalFlowTransition(QuarantineTail|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|reason=" + CompilerKernelV2.TerminalTailQuarantineReasonIdOps.text reason + ")"
            | TerminalFlowTransitionTerminalEmitted terminalReceiptId -> "TerminalFlowTransition(TerminalEmitted|receipt=" + terminalReceiptId + ")"

        let private terminalFlowOutcomeText = function
            | TerminalFlowOutcomeAwaitingObservation reason ->
                "TerminalFlowOutcome(AwaitingObservation|reason=" + terminalFlowAwaitingObservationReasonText reason + ")"
            | TerminalFlowOutcomeWakerRegistrationRequired(rootReceipt, leaseId, tailId, obligationId, nextWakeAfterMs) -> FastRuntimeFormat.format "TerminalFlowOutcome(WakerRegistrationRequired|root=%s|lease=%s|tail=%s|obligation=%s|next_wake_after_ms=%d)" [| box rootReceipt; box leaseId; box tailId; box obligationId; box nextWakeAfterMs |]
            | TerminalFlowOutcomeWriterLeaseStillLive(rootReceipt, leaseId, tailId, ageMs) -> FastRuntimeFormat.format "TerminalFlowOutcome(WriterLeaseStillLive|root=%s|lease=%s|tail=%s|age_ms=%d)" [| box rootReceipt; box leaseId; box tailId; box ageMs |]
            | TerminalFlowOutcomeWriterBound(rootReceipt, writerReceiptId, tailId) -> "TerminalFlowOutcome(WriterBound|root=" + rootReceipt + "|writer=" + writerReceiptId + "|tail=" + tailId + ")"
            | TerminalFlowOutcomeTailDeadlocked(rootReceipt, leaseId, tailId, proof) ->
                "TerminalFlowOutcome(TailDeadlocked|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|proof=" + CompilerKernelV2.TerminalTailDeadlockProofIdOps.text proof + ")"
            | TerminalFlowOutcomeTailQuarantined(rootReceipt, leaseId, tailId, reason) ->
                "TerminalFlowOutcome(TailQuarantined|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|reason=" + CompilerKernelV2.TerminalTailQuarantineReasonIdOps.text reason + ")"
            | TerminalFlowOutcomeTerminalEmitted terminalReceiptId -> "TerminalFlowOutcome(TerminalEmitted|receipt=" + terminalReceiptId + ")"

        let private terminalFlowCertificateIntentText = function
            | TerminalFlowCertificateAwaiting reason ->
                "TerminalFlowCertificateIntent(Awaiting|reason=" + terminalFlowAwaitingObservationReasonText reason + ")"
            | TerminalFlowCertificateBuildOk(rootReceipt, writerReceiptId, tailId) -> "TerminalFlowCertificateIntent(BuildOk|root=" + rootReceipt + "|writer=" + writerReceiptId + "|tail=" + tailId + ")"
            | TerminalFlowCertificateBuildError(rootReceipt, leaseId, tailId, proof) ->
                "TerminalFlowCertificateIntent(BuildError|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|proof=" + CompilerKernelV2.TerminalTailDeadlockProofIdOps.text proof + ")"
            | TerminalFlowCertificateNoFurther terminalReceiptId -> "TerminalFlowCertificateIntent(NoFurther|receipt=" + terminalReceiptId + ")"
            | TerminalFlowCertificateQuarantine(rootReceipt, leaseId, tailId, reason) ->
                "TerminalFlowCertificateIntent(Quarantine|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|reason=" + CompilerKernelV2.TerminalTailQuarantineReasonIdOps.text reason + ")"

        let private terminalFlowCertificateIntentForOutcome = function
            | TerminalFlowOutcomeWriterBound(rootReceipt, writerReceiptId, tailId) -> TerminalFlowCertificateBuildOk(rootReceipt, writerReceiptId, tailId)
            | TerminalFlowOutcomeTailDeadlocked(rootReceipt, leaseId, tailId, proof) -> TerminalFlowCertificateBuildError(rootReceipt, leaseId, tailId, proof)
            | TerminalFlowOutcomeTailQuarantined(rootReceipt, leaseId, tailId, reason) -> TerminalFlowCertificateQuarantine(rootReceipt, leaseId, tailId, reason)
            | TerminalFlowOutcomeTerminalEmitted terminalReceiptId -> TerminalFlowCertificateNoFurther terminalReceiptId
            | TerminalFlowOutcomeWakerRegistrationRequired(_, leaseId, tailId, obligationId, nextWakeAfterMs) ->
                TerminalFlowCertificateAwaiting(
                    TerminalFlowAwaitingWakerRegistrationRequired(leaseId, tailId, obligationId, nextWakeAfterMs))
            | TerminalFlowOutcomeWriterLeaseStillLive(_, leaseId, tailId, ageMs) ->
                TerminalFlowCertificateAwaiting(TerminalFlowAwaitingWriterLeaseLive(leaseId, tailId, ageMs))
            | TerminalFlowOutcomeAwaitingObservation reason -> TerminalFlowCertificateAwaiting reason

        let private terminalFlowTopLevelReceiptIdFor prefix root writer tail =
            prefix
            + ":"
            + string (NativeCutoverStableRef.ref32 "terminal-top-level-receipt" [ prefix; root; writer; tail ])

        let private terminalFlowTopLevelFailureIdFor prefix root lease tail =
            prefix
            + ":"
            + string (NativeCutoverStableRef.ref32 "terminal-top-level-failure" [ prefix; root; lease; tail ])

        let private terminalFlowWhyNotTerminalCommitText = function
            | TerminalFlowWhyNotAwaitingBoundedLease(leaseId, tailId, ageMs) -> FastRuntimeFormat.format "WhyNotTerminalCommit(AwaitingBoundedLease|lease=%s|tail=%s|age_ms=%d)" [| box leaseId; box tailId; box ageMs |]
            | TerminalFlowWhyNotAwaitingObservation reason ->
                "WhyNotTerminalCommit(AwaitingObservation|reason=" + terminalFlowAwaitingObservationReasonText reason + ")"
            | TerminalFlowWhyNotWakerRegistrationRequired(obligationId, nextWakeAfterMs) -> sprintf "WhyNotTerminalCommit(WakerRegistrationRequired|obligation=%s|next_wake_after_ms=%d)" obligationId nextWakeAfterMs
            | TerminalFlowWhyNotMissingRootReceipt evidence -> "WhyNotTerminalCommit(MissingRootReceipt|evidence=" + evidence + ")"
            | TerminalFlowWhyNotRecentMaterialActivity token -> "WhyNotTerminalCommit(RecentMaterialActivity|" + terminalFlowActivityTokenText "material_recent" terminalFlowMaterialActivitySourceText token + ")"
            | TerminalFlowWhyNotRejectedTopology qap -> "WhyNotTerminalCommit(RejectedTopology|" + terminalFlowQapObservationText qap + ")"
            | TerminalFlowWhyNotMissingWriterReceipt(rootReceipt, tailId) -> "WhyNotTerminalCommit(MissingWriterReceipt|root=" + rootReceipt + "|tail=" + tailId + ")"
            | TerminalFlowWhyNotObserverOnly reason -> "WhyNotTerminalCommit(ObserverOnly|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let private terminalFlowWhyNotIdentityText = function
            | TerminalFlowWhyNotAwaitingBoundedLease(leaseId, tailId, _) ->
                "awaiting_bounded_lease|lease=" + leaseId + "|tail=" + tailId
            | TerminalFlowWhyNotWakerRegistrationRequired(obligationId, _) ->
                "waker_registration_required|obligation=" + obligationId
            | TerminalFlowWhyNotRecentMaterialActivity token ->
                sprintf "recent_material_activity|source=%s|count=%d"
                    (terminalFlowMaterialActivitySourceText token.source)
                    token.count
            | whyNot -> terminalFlowWhyNotTerminalCommitText whyNot

        let private terminalFlowTopLevelReceiptText = function
            | TerminalFlowTopLevelBuildOkReceipt(receiptId, rootReceipt, writerReceiptId, tailId) -> "TerminalFlowTopLevelReceipt(BuildOk|receipt=" + receiptId + "|root=" + rootReceipt + "|writer=" + writerReceiptId + "|tail=" + tailId + ")"
            | TerminalFlowTopLevelBuildErrorCertificate(receiptId, rootReceipt, leaseId, tailId, proof) ->
                "TerminalFlowTopLevelReceipt(BuildErrorCertificate|receipt=" + receiptId + "|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|proof=" + CompilerKernelV2.TerminalTailDeadlockProofIdOps.text proof + ")"
            | TerminalFlowTopLevelNoFurtherCertificate receiptId -> "TerminalFlowTopLevelReceipt(NoFurtherCertificate|receipt=" + receiptId + ")"
            | TerminalFlowTopLevelQuarantineCertificate(receiptId, rootReceipt, leaseId, tailId, reason) ->
                "TerminalFlowTopLevelReceipt(QuarantineCertificate|receipt=" + receiptId + "|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|reason=" + CompilerKernelV2.TerminalTailQuarantineReasonIdOps.text reason + ")"

        let private terminalFlowCertificateBoundaryText = function
            | TerminalFlowBoundaryReceipt receipt -> "TerminalFlowCertificateBoundary(" + terminalFlowTopLevelReceiptText receipt + ")"
            | TerminalFlowBoundaryWhyNotCommit reason -> "TerminalFlowCertificateBoundary(" + terminalFlowWhyNotTerminalCommitText reason + ")"

        let private terminalFlowCertificateBoundaryForOutcome = function
            | TerminalFlowOutcomeWriterBound(rootReceipt, writerReceiptId, tailId) ->
                TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt(terminalFlowTopLevelReceiptIdFor "terminal_commit_receipt" rootReceipt writerReceiptId tailId, rootReceipt, writerReceiptId, tailId))
            | TerminalFlowOutcomeTailDeadlocked(rootReceipt, leaseId, tailId, proof) ->
                TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildErrorCertificate(terminalFlowTopLevelFailureIdFor "post_root_breakthrough_certificate" rootReceipt leaseId tailId, rootReceipt, leaseId, tailId, proof))
            | TerminalFlowOutcomeTailQuarantined(rootReceipt, leaseId, tailId, reason) ->
                TerminalFlowBoundaryReceipt(TerminalFlowTopLevelQuarantineCertificate(terminalFlowTopLevelFailureIdFor "post_root_quarantine_certificate" rootReceipt leaseId tailId, rootReceipt, leaseId, tailId, reason))
            | TerminalFlowOutcomeTerminalEmitted terminalReceiptId ->
                TerminalFlowBoundaryReceipt(TerminalFlowTopLevelNoFurtherCertificate terminalReceiptId)
            | TerminalFlowOutcomeWakerRegistrationRequired(_, _, _, obligationId, nextWakeAfterMs) ->
                TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotWakerRegistrationRequired(obligationId, nextWakeAfterMs))
            | TerminalFlowOutcomeWriterLeaseStillLive(_, leaseId, tailId, ageMs) ->
                TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotAwaitingBoundedLease(leaseId, tailId, ageMs))
            | TerminalFlowOutcomeAwaitingObservation reason ->
                match reason with
                | TerminalFlowAwaitingRecentMaterialActivity token ->
                    TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRecentMaterialActivity token)
                | TerminalFlowAwaitingRejectedTopology rejected ->
                    TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRejectedTopology rejected)
                | _ ->
                    TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotAwaitingObservation reason)

        let private terminalFlowCertificateBoundaryIsReceipt = function
            | TerminalFlowBoundaryReceipt _ -> true
            | TerminalFlowBoundaryWhyNotCommit _ -> false

        let private terminalFlowBoundaryActionForBoundary = function
            | TerminalFlowBoundaryReceipt receipt -> TerminalFlowBoundaryActionEmitReceipt receipt
            | TerminalFlowBoundaryWhyNotCommit reason -> TerminalFlowBoundaryActionBlockCommit reason

        let private terminalFlowBoundaryActionText = function
            | TerminalFlowBoundaryActionEmitReceipt receipt -> "TerminalFlowBoundaryAction(EmitReceipt|" + terminalFlowTopLevelReceiptText receipt + ")"
            | TerminalFlowBoundaryActionBlockCommit reason -> "TerminalFlowBoundaryAction(BlockCommit|" + terminalFlowWhyNotTerminalCommitText reason + ")"
            | TerminalFlowBoundaryActionFatalMissingBoundary reason -> "TerminalFlowBoundaryAction(FatalMissingBoundary|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let private terminalFlowBoundaryTopLevelReceiptText = function
            | TerminalFlowBoundaryReceipt receipt -> terminalFlowTopLevelReceiptText receipt
            | TerminalFlowBoundaryWhyNotCommit _ -> "TerminalFlowTopLevelReceipt(None)"

        let private terminalFlowBoundaryTerminalCommitReceiptId = function
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt(receiptId, _, _, _)) -> receiptId
            | _ -> ""

        let private terminalFlowBoundaryPostRootCertificateId = function
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildErrorCertificate(receiptId, _, _, _, _)) -> receiptId
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelNoFurtherCertificate receiptId) -> receiptId
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelQuarantineCertificate(receiptId, _, _, _, _)) -> receiptId
            | _ -> ""

        let private postRootTailDrainOutcomeText = function
            | PostRootTailDrainMadeProgress(beforeCount, afterCount, materialDelta) -> FastRuntimeFormat.format "PostRootTailDrainOutcome(MadeProgress|before=%d|after=%d|material_delta=%d)" [| box beforeCount; box afterCount; box materialDelta |]
            | PostRootTailDrainBoundWriter(writerReceiptId, qap) -> "PostRootTailDrainOutcome(BoundWriter|writer_receipt=" + writerReceiptId + "|qap=" + qap + ")"
            | PostRootTailDrainExpiredToDeadlock(tailId, repeatCount, repeatCap) -> FastRuntimeFormat.format "PostRootTailDrainOutcome(ExpiredToDeadlock|tail=%s|repeat=%d|cap=%d)" [| box tailId; box repeatCount; box repeatCap |]
            | PostRootTailDrainLiveHighQueue(tailId, qap, materialProgressObserved) -> "PostRootTailDrainOutcome(LiveHighQueue|tail=" + tailId + "|qap=" + qap + "|material_progress=" + string materialProgressObserved + ")"
            | PostRootTailDrainHighQueueExpiredToDeadlock(tailId, qap, leaseId) -> "PostRootTailDrainOutcome(HighQueueExpiredToDeadlock|tail=" + tailId + "|qap=" + qap + "|lease=" + leaseId + ")"
            | PostRootTailDrainNoRootBudgetLive(tailId, qap, repeatCount) -> "PostRootTailDrainOutcome(NoRootBudgetLive|tail=" + tailId + "|qap=" + qap + "|repeat=" + string repeatCount + ")"
            | PostRootTailDrainNoRootBudgetExpiredToTerminal(tailId, qap, terminalReceiptId) -> "PostRootTailDrainOutcome(NoRootBudgetExpiredToTerminal|tail=" + tailId + "|qap=" + qap + "|receipt=" + terminalReceiptId + ")"
            | PostRootTailDrainQuarantined(tailId, proof) -> "PostRootTailDrainOutcome(Quarantined|tail=" + tailId + "|proof=" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | PostRootTailDrainRejectedOwnerDebtReopen(receiptId, demotionReceiptId) -> "PostRootTailDrainOutcome(RejectedOwnerDebtReopen|receipt=" + receiptId + "|demotion=" + demotionReceiptId + ")"

        let private postRootOwnerDebtDemotionReceiptText (x:PostRootOwnerDebtDemotionReceipt<'GraphKind>) =
            "PostRootOwnerDebtDemotionReceipt(id=" + x.demotionReceiptId
            + "|root=" + x.rootReceiptId
            + "|lease=" + x.writerLeaseId
            + "|owner_receipt=" + x.demotedOwnerReceiptId
            + "|tail=" + x.tailId
            + "|consumed=" + string x.ownerDebtAuthorityConsumed
            + "|root_reopen_forbidden=" + string x.rootReopenForbidden
            + "|decision=" + postRootSchedulerDecisionText x.schedulerDecision + ")"

        let private terminalCommitEmissionContractText (x:TerminalCommitEmissionContract<'GraphKind>) =
            "TerminalCommitEmissionContract(id=" + x.terminalReceiptId
            + "|root=" + x.rootReceiptId
            + "|lease=" + x.writerLeaseId
            + "|tail_outcome=" + postRootTailDrainOutcomeText x.tailOutcome
            + "|flow=" + postRootTerminalFlowStateText x.flowState
            + "|after_root=" + (x.terminalAfterRoot |> Option.map terminalAfterRootText |> Option.defaultValue "none")
            + "|exit=" + string x.exitCode
            + "|physical_exit=" + string x.physicalExitRequired
            + "|owner_rows_suppressed=" + string x.ownerDebtRowsSuppressedAfterRoot + ")"

        let private postRootPhysicalExitKindText = function
            | PostRootExitBuildOk -> "build_ok"
            | PostRootExitBuildError -> "build_error"
            | PostRootExitNoFurther -> "no_further"
            | PostRootExitQuarantine -> "quarantine"

        let private postRootOwnerDebtBackEdgePolicyText = function
            | PostRootOwnerDebtBackEdgeRejected(rowRef, demotionReceiptId) -> "PostRootOwnerDebtBackEdgePolicy(Rejected|row=" + rowRef + "|demotion=" + demotionReceiptId + ")"
            | PostRootOwnerDebtBackEdgeDemoted(rowRef, writerLeaseId, tailId) -> "PostRootOwnerDebtBackEdgePolicy(Demoted|row=" + rowRef + "|lease=" + writerLeaseId + "|tail=" + tailId + ")"
            | PostRootOwnerDebtBackEdgeFatalViolation(rowRef, violation) -> "PostRootOwnerDebtBackEdgePolicy(FatalViolation|row=" + rowRef + "|" + postRootAuthorityViolationText violation + ")"

        let private writerTailEmissionSealText (x:WriterTailEmissionSeal<'GraphKind>) =
            "WriterTailEmissionSeal(id=" + x.sealId
            + "|contract=" + terminalCommitEmissionContractText x.terminalContract
            + "|exit_kind=" + postRootPhysicalExitKindText x.exitKind
            + "|writer=" + (x.writerCapabilityId |> Option.defaultValue "none")
            + "|artifact=" + (x.artifactHashId |> Option.defaultValue "none")
            + "|tail=" + x.workDagTailId
            + "|owner_back_edge=" + postRootOwnerDebtBackEdgePolicyText x.ownerBackEdgePolicy
            + "|physical_exit_latched=" + string x.physicalExitLatched + ")"

        let private postRootTerminalEmissionBoundaryText = function
            | PostRootBoundaryAwaitingWriter(lease, tail) -> "PostRootTerminalEmissionBoundary(AwaitingWriter|lease=" + lease.leaseId + "|tail=" + tail.tailId + ")"
            | PostRootBoundarySealedSuccess seal -> "PostRootTerminalEmissionBoundary(SealedSuccess|" + writerTailEmissionSealText seal + ")"
            | PostRootBoundarySealedFailure(seal, violation) -> "PostRootTerminalEmissionBoundary(SealedFailure|" + writerTailEmissionSealText seal + "|" + postRootAuthorityViolationText violation + ")"
            | PostRootBoundaryRejectedObserver(rowRef, reason) -> "PostRootTerminalEmissionBoundary(RejectedObserver|row=" + rowRef + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let private rootTerminalOutcomeText = function
            | RootTerminalOutcomePendingWriter gate -> "RootTerminalOutcome(PendingWriter|" + terminalRootReceiptGateText gate + ")"
            | RootTerminalOutcomePostRoot flow -> "RootTerminalOutcome(PostRoot|" + terminalAfterRootText flow + ")"
            | RootTerminalOutcomeCommitted receipt -> "RootTerminalOutcome(Committed|" + writerCommitReceiptText receipt + ")"
            | RootTerminalOutcomeFailedClosed authority -> "RootTerminalOutcome(FailedClosed|" + buildErrorTraceAuthorityText authority + ")"
            | RootTerminalOutcomeRejectedObserverOnly(rowRef, reason) -> "RootTerminalOutcome(RejectedObserverOnly|row=" + rowRef + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        // DOMAIN MIGRATION bonus: breakthrough-level authority
        // certificate.  This is the post-assessment spine that replaces the
        // old organic string HUD with a typed receipt graph: every BuildOk or
        // NoFurther terminal decision must name the exact unresolved edge or
        // sealed edge across root, owner, semantic sidecar, WorkDag, artifact
        // hash and writer capability.
        type TerminalBreakthroughObligationId =
            | BreakthroughRootCompleteResolved of rootReceipt:string
            | BreakthroughOwnerLedgerSealed of ownerReceipt:string
            | BreakthroughSemanticSidecarBound of sidecarReceipt:string
            | BreakthroughPostRootWriterLeaseBound of leaseId:string
            | BreakthroughWorkDagTailTerminalized of tailId:string * outcome:string
            | BreakthroughWorkDagExhausted of workDagHash:string
            | BreakthroughArtifactHashAuthorized of artifactHash:string
            | BreakthroughWriterCapabilityMinted of capability:string
            | BreakthroughBlocked of edge:string * blocker:string
            | BreakthroughQuarantined of edge:string * proof:CompilerKernelV2.OperationalReasonId

        type WaitGraphEdgeKindId =
            | WaitGraphRootToOwnerLedger
            | WaitGraphOwnerToSemanticSidecar
            | WaitGraphTopologyToSemanticFact
            | WaitGraphWorkDagToRootComplete
            | WaitGraphRootResolvedToWriterLease
            | WaitGraphWriterLeaseToWorkDagTail
            | WaitGraphWorkDagTailToTerminalReceipt
            | WaitGraphArtifactHashToWriter
            | WaitGraphWriterToBuildOk

        type WaitGraphEdgeCertificate<'GraphKind> = private {
            edgeId : string
            edgeKind : WaitGraphEdgeKindId
            fromNode : string
            toNode : string
            ownerAxis : OwnerLedgerAxisId option
            dependency : string
            resolved : bool
            receiptId : string option
        }

        type HotWorkUnitDependencyChain<'GraphKind> = private {
            chainId : string
            edges : WaitGraphEdgeCertificate<'GraphKind> list
            topBlocker : string
            schedulerCanRun : bool
            consumerCanDeclareNoFurther : bool
        }

        type TerminalBreakthroughSealCertificate<'GraphKind> = private {
            certificateId : string
            obligations : TerminalBreakthroughObligationId list
            waitGraph : HotWorkUnitDependencyChain<'GraphKind>
            exactOnceOwnerDrainReceiptId : string option
            rootPromiseTransitionReceiptId : string option
            writerRootSealReceiptId : string option
            accepted : bool
        }

        let private terminalBreakthroughObligationText = function
            | BreakthroughRootCompleteResolved rootReceipt -> "BreakthroughObligation(RootCompleteResolved|receipt=" + rootReceipt + ")"
            | BreakthroughOwnerLedgerSealed ownerReceipt -> "BreakthroughObligation(OwnerLedgerSealed|receipt=" + ownerReceipt + ")"
            | BreakthroughSemanticSidecarBound sidecarReceipt -> "BreakthroughObligation(SemanticSidecarBound|receipt=" + sidecarReceipt + ")"
            | BreakthroughPostRootWriterLeaseBound leaseId -> "BreakthroughObligation(PostRootWriterLeaseBound|lease=" + leaseId + ")"
            | BreakthroughWorkDagTailTerminalized(tailId, outcome) -> "BreakthroughObligation(WorkDagTailTerminalized|tail=" + tailId + "|outcome=" + outcome + ")"
            | BreakthroughWorkDagExhausted workDagHash -> "BreakthroughObligation(WorkDagExhausted|hash=" + workDagHash + ")"
            | BreakthroughArtifactHashAuthorized artifactHash -> "BreakthroughObligation(ArtifactHashAuthorized|hash=" + artifactHash + ")"
            | BreakthroughWriterCapabilityMinted capability -> "BreakthroughObligation(WriterCapabilityMinted|capability=" + capability + ")"
            | BreakthroughBlocked(edge, blocker) -> "BreakthroughObligation(Blocked|edge=" + edge + "|blocker=" + blocker + ")"
            | BreakthroughQuarantined(edge, proof) -> "BreakthroughObligation(Quarantined|edge=" + edge + "|proof=" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"

        let private terminalBreakthroughSealCertificateText (certificate:TerminalBreakthroughSealCertificate<'GraphKind>) =
            "TerminalBreakthroughSealCertificate(id=" + certificate.certificateId
            + "|accepted=" + string certificate.accepted
            + "|obligations=" + (certificate.obligations |> List.map terminalBreakthroughObligationText |> String.concat ";")
            + "|owner_drain_receipt=" + (certificate.exactOnceOwnerDrainReceiptId |> Option.defaultValue "none")
            + "|root_transition_receipt=" + (certificate.rootPromiseTransitionReceiptId |> Option.defaultValue "none")
            + "|writer_root_seal_receipt=" + (certificate.writerRootSealReceiptId |> Option.defaultValue "none") + ")"

        let private writerRootSealOwnerAxisText = function
            | OwnerAxisParentContinuation -> "parent_continuation"
            | OwnerAxisSemanticFactDebt -> "semantic_fact_debt"
            | OwnerAxisSidecarDrain -> "sidecar_drain"
            | OwnerAxisDynamicBridge -> "dynamic_bridge"
            | OwnerAxisCrossKind -> "cross_kind"
            | OwnerAxisPoisonTail -> "poison_tail"
            | OwnerAxisJoinPointWait -> "join_point_wait"
            | OwnerAxisProceduralResidual -> "procedural_residual"
            | OwnerAxisCicProofObligation -> "cic_proof_obligation"

        let writerRootSealOwnerStateText = function
            | WriterRootSealOwnersClosed -> "WriterRootSealOwners(Closed)"
            | WriterRootSealOwnersQuarantined reason -> "WriterRootSealOwners(Quarantined|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | WriterRootSealOwnersOpen axes ->
                "WriterRootSealOwners(Open|axes=" + (axes |> List.map writerRootSealOwnerAxisText |> String.concat ";") + ")"

        let writerRootSealSemanticStateText = function
            | WriterRootSealSemanticBound receiptId -> "WriterRootSealSemantic(Bound|receipt=" + receiptId + ")"
            | WriterRootSealSemanticQuarantined reason -> "WriterRootSealSemantic(Quarantined|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | WriterRootSealSemanticMissing dependency -> "WriterRootSealSemantic(Missing|dependency=" + dependency + ")"

        let workDagTerminalSealStateText = function
            | WorkDagTerminalSealExhausted workDagHash -> "WorkDagTerminalSeal(Exhausted|hash=" + workDagHash + ")"
            | WorkDagTerminalSealBlocked blocker -> "WorkDagTerminalSeal(Blocked|blocker=" + blocker + ")"
            | WorkDagTerminalSealUnknown reason -> "WorkDagTerminalSeal(Unknown|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let writerRootBuildOkSealText (seal:WriterRootBuildOkSeal<'GraphKind>) =
            "WriterRootBuildOkSeal(id=" + seal.sealId
            + "|root=" + rootPromiseTransitionText seal.rootPromiseTransition
            + "|owner=" + writerRootSealOwnerStateText seal.ownerState
            + "|semantic=" + writerRootSealSemanticStateText seal.semanticState
            + "|work_dag=" + workDagTerminalSealStateText seal.workDagState
            + "|artifact_hash=" + seal.artifactSetHash
            + "|content_hash_authorized=" + string seal.contentHashAuthorized
            + "|writer=" + seal.writerCapabilityDu + ")"

        let writerRootBuildOkSealDecisionText = function
            | WriterRootBuildOkSealAccepted seal -> "WriterRootBuildOkSealDecision(Accepted|" + writerRootBuildOkSealText seal + ")"
            | WriterRootBuildOkSealRejected(seal, reason) -> "WriterRootBuildOkSealDecision(Rejected|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|" + writerRootBuildOkSealText seal + ")"

        // MIGRATION: progress and ETA authority is promoted from HUD scoring
        // into a typed Work-DAG ledger. Percent and ETA are derived from
        // explicit costs, dependency edges, discovery reserve, material delta
        // credit and stasis horizon; JSON remains an erasure of this authority
        // instead of the source of truth. Terminal closure must consult this
        // ledger together with owner closure before any fail-closed outcome can
        // commit.
        type WorkDagNodeId<'Kind> =
            { value:string }

        type WorkDagEdgeId<'Kind> =
            { value:string }

        type WorkDagCostLedger = {
            completedCost : int64
            knownRemainingCost : int64
            blockedRemainingCost : int64
            undiscoveredP50Cost : int64
            undiscoveredP90Cost : int64
            totalCost : int64
        }

        type WorkDagProgressBand = {
            lowPct : float
            midPct : float
            highPct : float
        }

        type WorkDagEtaConfidenceId =
            | WorkDagEtaClosed
            | WorkDagEtaQuiescentAwaitingClosureAuthority
            | WorkDagEtaUnknownTerminalGraphRate
            | WorkDagEtaEstimatorConfidence of EtaConfidenceLevelId

        let private workDagEtaConfidenceText = function
            | WorkDagEtaClosed -> "closed"
            | WorkDagEtaQuiescentAwaitingClosureAuthority -> "quiescent_awaiting_closure_authority"
            | WorkDagEtaUnknownTerminalGraphRate -> "unknown_terminal_graph_rate"
            | WorkDagEtaEstimatorConfidence confidence -> etaConfidenceLevelText confidence

        type WorkDagEtaBasisId =
            | WorkDagEtaTerminalGraphStructuralAuthority
            | WorkDagEtaEstimatorBasis of EtaSuccessBasisId

        let private workDagEtaBasisText = function
            | WorkDagEtaTerminalGraphStructuralAuthority -> "terminal_graph_structural_authority"
            | WorkDagEtaEstimatorBasis basis -> etaSuccessBasisText basis

        type WorkDagEtaBand = {
            terminalP50S : int64
            terminalP90S : int64
            successP50S : int64
            successP90S : int64
            confidence : WorkDagEtaConfidenceId
            basis : WorkDagEtaBasisId
        }

        type SemanticFactDebtOpenReasonId =
            | SemanticFactDebtKnownWorkWithoutSemanticFactDelta
            | SemanticFactDebtProgressTickKnownRemainingWithoutSemanticFactDelta

        let private semanticFactDebtOpenReasonText = function
            | SemanticFactDebtKnownWorkWithoutSemanticFactDelta -> "known_work_without_semantic_fact_delta"
            | SemanticFactDebtProgressTickKnownRemainingWithoutSemanticFactDelta -> "progress_tick_known_remaining_without_semantic_fact_delta"

        type SemanticFactDebtState<'Kind> =
            | SemanticFactDebtNone
            | SemanticFactDebtOpen of hot:WorkDagNodeId<'Kind> * closure:CanonicalTerminalClosureId<'Kind> * missingFacts:int64 * reason:SemanticFactDebtOpenReasonId
            | SemanticFactDebtPaid of hot:WorkDagNodeId<'Kind> * producedFacts:int64 * receipt:string
            | SemanticFactDebtClosedGraph of closure:CanonicalTerminalClosureId<'Kind> * completedCost:int64 * receipt:string
            | SemanticFactDebtQuarantined of hot:WorkDagNodeId<'Kind> * missingFacts:int64 * action:string

        type WorkDagAuthority<'Kind> = {
            root : WorkDagNodeId<'Kind>
            hot : WorkDagNodeId<'Kind>
            parent : WorkDagNodeId<'Kind> option
            edges : WorkDagEdgeId<'Kind> list
            cost : WorkDagCostLedger
            progress : WorkDagProgressBand
            eta : WorkDagEtaBand
            materialDeltaCost : int64
            throughputCostPerS : float
            discovery : GraphDiscoveryState
            creditDecision : WorkUnitCreditDecisionId
            stasis : GraphStasisReasonId
            etaStasis : EtaStasisHorizonId
            semanticFactDebt : SemanticFactDebtState<'Kind>
            ledgerClosed : bool
        }

        type SchedulerCausalClock = {
            epoch : int64
            repeat : int64
            writerFreshMs : int64
            observerFreshMs : int64
        }

        type SchedulerWakeToken<'Kind> =
            { value:string }

        type SchedulerCausalAuthority<'Kind> = {
            wakeToken : SchedulerWakeToken<'Kind>
            graphHash : TerminalGraphStateHash<'Kind>
            clock : SchedulerCausalClock
            liveWorkers : int64
            pendingWakes : int64
            lostWakeRisk : int64
            fairnessDebt : int64
            semanticFactDebt : SemanticFactDebtState<'Kind>
            causalClosed : bool
            reason : CompilerKernelV2.OperationalReasonId
        }

        type SchedulerCausalVerdict<'Kind> =
            | SchedulerCausalityClosed of authority:SchedulerCausalAuthority<'Kind>
            | SchedulerCausalityOpen of authority:SchedulerCausalAuthority<'Kind> * reason:CompilerKernelV2.OperationalReasonId
            | SchedulerCausalityDebtObserved of authority:SchedulerCausalAuthority<'Kind> * reason:CompilerKernelV2.OperationalReasonId

        type BreakthroughEvidenceAxis =
            | BreakthroughOwnerClosure
            | BreakthroughWorkDagClosure
            | BreakthroughSchedulerCausality
            | BreakthroughSemanticFactDebt
            | BreakthroughConsoleEvidence
            | BreakthroughDeadlockResolution

        type BreakthroughEvidenceAtom<'Kind> = {
            axis : BreakthroughEvidenceAxis
            present : bool
            witness : string
            authorityHash : string
            workDag : WorkDagAuthority<'Kind> option
            scheduler : SchedulerCausalAuthority<'Kind> option
        }

        type BreakthroughEvidenceQuorum<'Kind> = {
            required : BreakthroughEvidenceAxis list
            observed : BreakthroughEvidenceAtom<'Kind> list
            missing : BreakthroughEvidenceAxis list
            canPromote : bool
            reason : CompilerKernelV2.OperationalReasonId
        }

        type BreakthroughTerminalVerdict<'Kind> =
            | BreakthroughTerminalReady of quorum:BreakthroughEvidenceQuorum<'Kind>
            | BreakthroughTerminalBlocked of quorum:BreakthroughEvidenceQuorum<'Kind> * reason:CompilerKernelV2.OperationalReasonId

        type WorkDagTerminalClosureVerdict<'Kind> =
            | WorkDagTerminalClosureAllowed of workDag:WorkDagAuthority<'Kind>
            | WorkDagTerminalClosureBlocked of workDag:WorkDagAuthority<'Kind> * openCost:int64 * reason:CompilerKernelV2.OperationalReasonId

        type TerminalClosurePrerequisiteLedger<'Kind> = {
            ownerVerdict : TypedTerminalOwnerClosureVerdict<'Kind>
            workDagVerdict : WorkDagTerminalClosureVerdict<'Kind>
            schedulerVerdict : SchedulerCausalVerdict<'Kind>
            breakthroughVerdict : BreakthroughTerminalVerdict<'Kind>
        }

        type TerminalClosurePrerequisiteVerdict<'Kind> =
            | TerminalClosurePrerequisitesSatisfied of ledger:TerminalClosurePrerequisiteLedger<'Kind>
            | TerminalClosurePrerequisitesBlockedByOwners of ledger:TerminalClosurePrerequisiteLedger<'Kind> * reason:CompilerKernelV2.OperationalReasonId
            | TerminalClosurePrerequisitesBlockedByWorkDag of ledger:TerminalClosurePrerequisiteLedger<'Kind> * reason:CompilerKernelV2.OperationalReasonId
            | TerminalClosurePrerequisitesBlockedBySchedulerCausality of ledger:TerminalClosurePrerequisiteLedger<'Kind> * reason:CompilerKernelV2.OperationalReasonId
            | TerminalClosurePrerequisitesBlockedByBreakthroughQuorum of ledger:TerminalClosurePrerequisiteLedger<'Kind> * reason:CompilerKernelV2.OperationalReasonId
            | TerminalClosurePrerequisitesNeedDeadlockResolution of ledger:TerminalClosurePrerequisiteLedger<'Kind> * reason:CompilerKernelV2.OperationalReasonId

        type LiveGraphProgressProof<'Kind> =
            | MaterialProgress of epoch:TerminalGraphEpoch<'Kind> * graphHash:TerminalGraphStateHash<'Kind>
            | TopologyProgressOnce of witness:TopologyWitnessId<'Kind> * epoch:TerminalGraphEpoch<'Kind>
            | OccupiedNoMaterialProgress of graphHash:TerminalGraphStateHash<'Kind> * repeat:int64
            | DeadlockedObligation of graphHash:TerminalGraphStateHash<'Kind> * repeat:int64 * obligation:CrossKindObligationState<'Kind>
            | GraphExhausted of epoch:TerminalGraphEpoch<'Kind> * graphHash:TerminalGraphStateHash<'Kind>

        type LiveGraphPhaseId =
            | LiveGraphPhaseFresh
            | LiveGraphPhaseProgressing
            | LiveGraphPhaseStale
            | LiveGraphPhaseDeadlocked
            | LiveGraphPhaseQuarantined
            | LiveGraphPhaseTerminalEligible

        type LiveGraphAuthorityTransitionReasonId =
            | LiveGraphTransitionMaterialAdvanced
            | LiveGraphTransitionTopologyOnly
            | LiveGraphTransitionOwnerLedgerChanged
            | LiveGraphTransitionLeaseExpired
            | LiveGraphTransitionQuarantinePromoted
            | LiveGraphTransitionTerminalExhausted

        type LiveGraphAuthorityTransitionReceipt<'Kind> = private {
            transitionId : string
            fromPhase : LiveGraphPhaseId
            toPhase : LiveGraphPhaseId
            reason : LiveGraphAuthorityTransitionReasonId
            ownerLedgerBefore : RecursiveOwnerLedger<'Kind>
            ownerLedgerAfter : RecursiveOwnerLedger<'Kind>
            ownerMutations : TypedOwnerMutationId<'Kind> list
            materialDelta : int64
            evidence : string
        }

        type LiveGraphAuthorityCheckpoint<'Kind> = private {
            checkpointId : string
            phase : LiveGraphPhaseId
            owners : RecursiveOwnerLedger<'Kind>
            transitionCount : int
            digest : string
        }

        type LiveGraphAuthorityHistory<'Kind> =
            | LiveGraphAuthorityGenesis of phase:LiveGraphPhaseId * owners:RecursiveOwnerLedger<'Kind> * evidence:string
            | LiveGraphAuthorityTransition of receipt:LiveGraphAuthorityTransitionReceipt<'Kind> * previous:LiveGraphAuthorityHistory<'Kind>
            | LiveGraphAuthorityCheckpoint of checkpoint:LiveGraphAuthorityCheckpoint<'Kind>

        type LiveGraphAuthority<'Kind,'Phase> =
            | LiveGraphAuthorityNode of
                graph:TerminalExecutableGraphState<'Kind> *
                proof:LiveGraphProgressProof<'Kind> *
                workDag:WorkDagAuthority<'Kind> *
                scheduler:SchedulerCausalAuthority<'Kind> *
                lease:LiveGraphConservedCredit<'Kind> option *
                crossKind:CrossKindObligationState<'Kind> *
                parentContinuation:ParentContinuationObligationState<'Kind> *
                owners:RecursiveOwnerLedger<'Kind> *
                history:LiveGraphAuthorityHistory<'Kind>

        type LiveGraphAuthorityState<'Kind> =
            | LiveGraphFreshState of LiveGraphAuthority<'Kind,LiveGraphFresh>
            | LiveGraphProgressingState of LiveGraphAuthority<'Kind,LiveGraphProgressing>
            | LiveGraphStaleState of LiveGraphAuthority<'Kind,LiveGraphStale>
            | LiveGraphDeadlockedState of LiveGraphAuthority<'Kind,LiveGraphDeadlocked>
            | LiveGraphQuarantinedState of LiveGraphAuthority<'Kind,LiveGraphQuarantined>
            | LiveGraphTerminalEligibleState of LiveGraphAuthority<'Kind,LiveGraphTerminalEligible>

        type LiveGraphOwnerTransactionApplyResult<'Kind> =
            | LiveGraphOwnerTransactionApplied of authority:LiveGraphAuthorityState<'Kind> * receipt:TypedOwnerTransactionReceipt<'Kind>
            | LiveGraphOwnerTransactionPromotedTerminalEligible of authority:LiveGraphAuthority<'Kind,LiveGraphTerminalEligible> * receipt:TypedOwnerTransactionReceipt<'Kind>
            | LiveGraphOwnerTransactionRejectedMismatch of authority:LiveGraphAuthorityState<'Kind> * receipt:TypedOwnerTransactionReceipt<'Kind> * reason:CompilerKernelV2.OperationalReasonId

        type PhaseIndexedLiveGraph<'Kind,'Phase> = private {
            authority : LiveGraphAuthority<'Kind,'Phase>
            phase : LiveGraphPhaseId
        }

        type PhaseIndexedLiveGraphState<'Kind> =
            | PhaseIndexedFresh of PhaseIndexedLiveGraph<'Kind,LiveGraphFresh>
            | PhaseIndexedProgressing of PhaseIndexedLiveGraph<'Kind,LiveGraphProgressing>
            | PhaseIndexedStale of PhaseIndexedLiveGraph<'Kind,LiveGraphStale>
            | PhaseIndexedDeadlocked of PhaseIndexedLiveGraph<'Kind,LiveGraphDeadlocked>
            | PhaseIndexedQuarantined of PhaseIndexedLiveGraph<'Kind,LiveGraphQuarantined>
            | PhaseIndexedTerminalEligible of PhaseIndexedLiveGraph<'Kind,LiveGraphTerminalEligible>

        type LiveGraphDeadlockResolution<'Kind> =
            | EmitStructuredLiveGraphDeadlock of authority:LiveGraphAuthority<'Kind,LiveGraphDeadlocked>
            | ForceCrossKindDrainWithLease of authority:LiveGraphAuthority<'Kind,LiveGraphDeadlocked> * attempt:CrossKindDrainAttempt<'Kind>
            | ForceParentContinuationHandoffWithLease of authority:LiveGraphAuthority<'Kind,LiveGraphDeadlocked> * proof:ParentContinuationCloseProof<'Kind>
            | ResolveCrossKindThenParentContinuation of authority:LiveGraphAuthority<'Kind,LiveGraphDeadlocked> * attempt:CrossKindDrainAttempt<'Kind> * parent:ParentContinuationObligationState<'Kind>
            | QuarantineParentContinuationAndCommitNoFurther of authority:LiveGraphAuthority<'Kind,LiveGraphDeadlocked> * plan:ParentContinuationQuarantinePlan<'Kind>
            | QuarantineOrphanWorkersAndCommitNoFurther of authority:LiveGraphAuthority<'Kind,LiveGraphDeadlocked> * plan:CrossKindQuarantinePlan<'Kind>

        type PoisonTailState<'Kind> =
            | PoisonTailNotPresent of closureKind:NativeClosureKindId
            | PoisonTailDeferredBoundGraph of closureKind:NativeClosureKindId * graph:TerminalExecutableGraphState<'Kind> * retriesRemaining:int64
            | PoisonTailTerminalEligibleAfterBoundedStasis of closureKind:NativeClosureKindId * graph:TerminalExecutableGraphState<'Kind> * sameStateRepeat:int64

        // MIGRATION MIGRATION : push-driven Hopac authority is now the
        // public scheduler spine.  JP wait and generation-change poison
        // surfaces project into the same typed push event ledger that owns
        // terminal/deferral authority; the metronome becomes an observer of
        // these events instead of a polling judge.
        // MIGRATION MIGRATION : old poison-tail cannot surface a
        // fail-closed terminal while a bound graph, cross-kind edge or parent
        // continuation remains live.  The old branch becomes a typed handoff
        // authority that either defers, permits only bounded-stasis terminal
        // handoff, or marks non-poison traffic as out of scope.
        type PoisonTailHandoffAuthority<'Kind> =
            | PoisonTailHandoffNotPoison of closureKind:NativeClosureKindId
            | PoisonTailHandoffDeferredBoundGraph of
                state:PoisonTailState<'Kind> *
                waitForEdge:string *
                participants:string *
                nextAction:string
            | PoisonTailHandoffAllowedAfterBoundedStasis of
                state:PoisonTailState<'Kind> *
                terminalOutcome:string *
                nextAction:string

        type PoisonTailLegacyBypassReasonId =
            | PoisonTailLegacyBypassForbiddenWhileBoundGraphOrCrossKindEdgeLive
            | PoisonTailLegacyBypassBoundedStasisRequiresTerminalCommitGate

        let private poisonTailLegacyBypassReasonText = function
            | PoisonTailLegacyBypassForbiddenWhileBoundGraphOrCrossKindEdgeLive -> "legacy_old_poison_tail_fail_closed_forbidden_while_bound_graph_or_cross_kind_edge_live"
            | PoisonTailLegacyBypassBoundedStasisRequiresTerminalCommitGate -> "bounded_stasis_reached_terminal_commit_gate_must_own_exit"

        type PoisonTailLegacyBypassVerdict<'Kind> =
            | PoisonTailLegacyBypassQuarantined of authority:PoisonTailHandoffAuthority<'Kind> * reason:PoisonTailLegacyBypassReasonId
            | PoisonTailLegacyBypassAllowed of authority:PoisonTailHandoffAuthority<'Kind> * reason:PoisonTailLegacyBypassReasonId
            | PoisonTailLegacyBypassNotApplicable of reason:CompilerKernelV2.OperationalReasonId

        type PoisonTailObservedStatusId =
            | PoisonTailObservedParentReplayCycleBreakPoisoned

        let private poisonTailObservedStatusText = function
            | PoisonTailObservedParentReplayCycleBreakPoisoned -> "semantic_parent_replay_cycle_break_poisoned"

        type PoisonTailTransitionFrame<'Kind> = {
            closureId : CanonicalTerminalClosureId<'Kind>
            status : PoisonTailObservedStatusId
            reason : CompilerKernelV2.OperationalReasonId
            waitForEdge : string
            participants : string
            graph : TerminalExecutableGraphState<'Kind>
            state : PoisonTailState<'Kind>
            authority : PoisonTailHandoffAuthority<'Kind>
            verdict : PoisonTailLegacyBypassVerdict<'Kind>
        }

        // MIGRATION: parent-replay poison is no longer a loose next= string.
        // It becomes a durable single-flight obligation.  A terminal/finish-fast
        // row cannot close while this DU says Pending/Scheduled/BlockedNoDelta;
        // only AdvancedWithDelta/AdvancedWithCyclePoison/ResolvedNoFurther or a
        // typed exhausted graph can permit terminal authority.
        type ParentReplayPoisonConsumerReasonId =
            | ParentReplayPoisonForceDrainBeforeTerminalAuthority
            | ParentReplayPoisonBoundedStasisNonQuarantinedTail
            | ParentReplayPoisonForceDrainNotScheduledOrNoDeltaYet
            | ParentReplayPoisonOperationalReason of CompilerKernelV2.OperationalReasonId

        let private parentReplayPoisonConsumerReasonText = function
            | ParentReplayPoisonForceDrainBeforeTerminalAuthority -> "force_drain_parent_poison_single_flight_before_terminal_authority"
            | ParentReplayPoisonBoundedStasisNonQuarantinedTail -> "bounded_stasis_non_quarantined_tail"
            | ParentReplayPoisonForceDrainNotScheduledOrNoDeltaYet -> "force_drain_not_scheduled_or_no_delta_yet"
            | ParentReplayPoisonOperationalReason reason -> CompilerKernelV2.OperationalReasonIdOps.text reason

        type ParentReplayPoisonRequiredWakeId =
            | ParentReplayPoisonSingleFlightConsumerWake

        let private parentReplayPoisonRequiredWakeText = function
            | ParentReplayPoisonSingleFlightConsumerWake -> "parent_replay_poison_single_flight_consumer"

        type ParentReplayPoisonConsumerResult =
            | ParentReplayPoisonConsumerResultMissing
            | ParentReplayPoisonConsumerScheduledDrain of passes:int * reason:ParentReplayPoisonConsumerReasonId
            | ParentReplayPoisonConsumerNoDeltaButPoisonAdvanced of reason:ParentReplayPoisonConsumerReasonId
            | ParentReplayPoisonConsumerAstDeltaProduced of facts:int64 * reason:ParentReplayPoisonConsumerReasonId
            | ParentReplayPoisonConsumerCyclePoisonProduced of payload:CompilerKernelV2.OperationalReasonId
            | ParentReplayPoisonConsumerBlockedLostWake of requiredWake:ParentReplayPoisonRequiredWakeId * reason:ParentReplayPoisonConsumerReasonId

        type ParentReplayPoisonSingleFlight<'Kind> =
            | ParentReplayPoisonSingleFlightNotApplicable of reason:CompilerKernelV2.OperationalReasonId
            | ParentReplayPoisonSingleFlightPending of key:string * frame:PoisonTailTransitionFrame<'Kind> * requiredWake:string
            | ParentReplayPoisonSingleFlightScheduled of key:string * frame:PoisonTailTransitionFrame<'Kind> * result:ParentReplayPoisonConsumerResult
            | ParentReplayPoisonSingleFlightResolved of key:string * frame:PoisonTailTransitionFrame<'Kind> * result:ParentReplayPoisonConsumerResult
            | ParentReplayPoisonSingleFlightBlockedNoDelta of key:string * frame:PoisonTailTransitionFrame<'Kind> * result:ParentReplayPoisonConsumerResult

        type NativeTerminalAuthorityDeferredReasonId =
            | NativeTerminalAuthorityParentReplayPoisonSingleFlightNotResolved
            | NativeTerminalAuthorityGraphNotExhausted

        let private nativeTerminalAuthorityDeferredReasonText = function
            | NativeTerminalAuthorityParentReplayPoisonSingleFlightNotResolved -> "parent_replay_poison_single_flight_not_resolved"
            | NativeTerminalAuthorityGraphNotExhausted -> "graph_not_exhausted"

        type NativeTerminalExhaustionProofId =
            | NativeTerminalExhaustionGraphAndPoisonResolved

        let private nativeTerminalExhaustionProofText = function
            | NativeTerminalExhaustionGraphAndPoisonResolved -> "typed_graph_exhausted_and_poison_consumer_resolved"

        type NativeTerminalAuthorityPhase<'Kind> =
            | NativeTerminalAuthorityLive of graph:TerminalExecutableGraphState<'Kind> * poison:ParentReplayPoisonSingleFlight<'Kind>
            | NativeTerminalAuthorityDeferred of graph:TerminalExecutableGraphState<'Kind> * poison:ParentReplayPoisonSingleFlight<'Kind> * reason:NativeTerminalAuthorityDeferredReasonId
            | NativeTerminalAuthorityExhausted of graph:TerminalExecutableGraphState<'Kind> * poison:ParentReplayPoisonSingleFlight<'Kind> * proof:NativeTerminalExhaustionProofId

        type HopacPushRuntimeEvent<'Kind> =
            | HopacPushPoisonTailHandoff of frame:PoisonTailTransitionFrame<'Kind>
            | HopacPushJpWaitFrameObserved of key:string * status:JpWaitLiveFrameStatusId * waitMs:int64
            | HopacPushJpWaitFrameClosedByTerminalAction of key:string * status:JpWaitLiveFrameStatusId * waitMs:int64 * terminalAuthority:string
            | HopacPushGenerationChangePoisonTail of tag:string * key:string * site:string * frame:PoisonTailTransitionFrame<'Kind>
            | HopacPushSchedulerHeartbeatObserved of reason:CompilerKernelV2.OperationalReasonId

        type PushDrivenAuthorityObserverReasonId =
            | PushDrivenObserverPoisonTailNotApplicable of CompilerKernelV2.OperationalReasonId
            | PushDrivenObserverJpWaitCannotRewriteProducer
            | PushDrivenObserverJpWaitLiveFrame
            | PushDrivenObserverMetronomeHeartbeat of CompilerKernelV2.OperationalReasonId

        let private pushDrivenAuthorityObserverReasonText = function
            | PushDrivenObserverPoisonTailNotApplicable reason -> CompilerKernelV2.OperationalReasonIdOps.text reason
            | PushDrivenObserverJpWaitCannotRewriteProducer -> "jp_wait_can_observe_terminal_action_but_cannot_rewrite_producer"
            | PushDrivenObserverJpWaitLiveFrame -> "jp_wait_live_frame_observer_only"
            | PushDrivenObserverMetronomeHeartbeat reason -> "metronome_observer_only|" + CompilerKernelV2.OperationalReasonIdOps.text reason

        type PushDrivenSchedulerAuthority<'Kind> =
            | PushDrivenAuthorityAbsent
            | PushDrivenAuthorityObserverOnly of event:HopacPushRuntimeEvent<'Kind> * reason:PushDrivenAuthorityObserverReasonId
            | PushDrivenAuthorityDeferredByPoisonTail of event:HopacPushRuntimeEvent<'Kind> * frame:PoisonTailTransitionFrame<'Kind>
            | PushDrivenAuthorityRequiresTerminalCommit of event:HopacPushRuntimeEvent<'Kind> * frame:PoisonTailTransitionFrame<'Kind>

        type MetronomeObserverRole<'Kind> =
            | MetronomeObserverNoPushEvent
            | MetronomeObserverPushEventObserved of authority:PushDrivenSchedulerAuthority<'Kind>
            | MetronomeObserverRootCompleteAltOwnsTerminal of authority:PushDrivenSchedulerAuthority<'Kind>

        // MIGRATION MIGRATION : terminal rendering is no longer a bag of
        // repeated DU strings.  The runtime keeps a canonical closure identity,
        // graph hash/epoch and a compact token; JSON/HUD projections may expand
        // a detail row once, but hot rows consume this stable projection.
        type TerminalProjectionVerbosity =
            | TerminalProjectionFullFirstOccurrence
            | TerminalProjectionCompactRepeat
            | TerminalProjectionHudBoard

        type TerminalProjectionDecisionRefs = private {
            outcomeRef : uint32
            commitGateRef : uint32
            pushAuthorityRef : uint32
            poisonAuthorityRef : uint32
        }

        type CanonicalTerminalProjection<'Kind> = {
            canonicalClosureId : CanonicalTerminalClosureId<'Kind>
            graphHash : TerminalGraphStateHash<'Kind>
            graphEpoch : TerminalGraphEpoch<'Kind>
            sameGraphRepeatCount : int64
            decisionRefs : TerminalProjectionDecisionRefs
            compactionToken : string
            verbosity : TerminalProjectionVerbosity
        }

        type TerminalDiagnosticRefs = private {
            blockerRef : uint32
            reasonRef : uint32
            nextActionRef : uint32
            invariantRefs : uint32 list
        }

        type TerminalDiagnosticBoard<'Kind> = {
            projection : CanonicalTerminalProjection<'Kind>
            refs : TerminalDiagnosticRefs
        }

        type StringIngressTranslationReceipt =
            | StringIngressForbidden of fieldRef:uint32 * patternRef:uint32 * replacementRef:uint32
            | StringIngressTranslated of fieldRef:uint32 * patternRef:uint32 * typedProjectionRef:uint32
            | StringIngressErased of fieldRef:uint32 * replacementRef:uint32

        type NativePromiseTerminalOutcome<'Kind> =
            | NativePromiseTerminalResolvedMaterial of promiseId:string * facts:int64
            | NativePromiseTerminalFailedSemantic of promiseId:string * payload:string * payloadClass:string
            | NativePromiseTerminalClosedNoFurther of promiseId:string * reason:CompilerKernelV2.OperationalReasonId * witness:TopologyWitnessMaterialization<'Kind>
            | NativePromiseTerminalObserverOnly of promiseId:string * reason:CompilerKernelV2.OperationalReasonId

        // DOMAIN MIGRATION : terminal authority is an actual Hopac IVar/Alt
        // spine.  Clocks, repeat counters, rescue loops and HUD observers may
        // describe why the spine is still open, but they cannot arm or resolve it.
        type NativeRootCompleteOpenPhase = | NativeRootCompleteOpenPhase
        type NativeRootCompleteArmedPhase = | NativeRootCompleteArmedPhase
        type NativeRootCompleteResolvedPhase = | NativeRootCompleteResolvedPhase

        type WorkUnitOpenPhase = | WorkUnitOpenPhase
        type WorkUnitExhaustedPhase = | WorkUnitExhaustedPhase
        type ReplayKeyOpenPhase = | ReplayKeyOpenPhase
        type ReplayKeyClosedPhase = | ReplayKeyClosedPhase
        type TerminalOutcomePendingPhase = | TerminalOutcomePendingPhase
        type TerminalOutcomeResolvedPhase = | TerminalOutcomeResolvedPhase
        type PoisonTailOpenPhase = | PoisonTailOpenPhase
        type PoisonTailClosedPhase = | PoisonTailClosedPhase
        type WorkDagOpenPhase = | WorkDagOpenPhase
        type WorkDagExhaustedPhase = | WorkDagExhaustedPhase

        [<Struct>]
        type PhaseIndexedWorkUnitId<'Kind,'Phase> = private { value : string }

        [<Struct>]
        type PhaseIndexedReplayKey<'Kind,'Phase> = private { value : string }

        type PhaseIndexedTerminalOutcome<'Kind,'Phase> = private {
            outcome : NativePromiseTerminalOutcome<'Kind>
            graphHash : TerminalGraphStateHash<'Kind>
        }

        type PhaseIndexedPoisonTail<'Kind,'Phase> = private {
            ownerLedger : RecursiveOwnerLedger<'Kind>
            transitionHash : string
        }

        type CriticalPathWorkLedger = {
            completedCost : CompilerKernelV2.SemanticCost
            criticalPathRemainingCost : CompilerKernelV2.SemanticCost
            discoveryReserveP50 : CompilerKernelV2.SemanticCost
            discoveryReserveP90 : CompilerKernelV2.SemanticCost
            materialSemanticCredit : CompilerKernelV2.SemanticCost
            effectiveRemainingCost : CompilerKernelV2.SemanticCost
            totalCost : CompilerKernelV2.SemanticCost
            progressLowPct : float
            progressMidPct : float
            progressHighPct : float
            etaP50S : int64
            etaP90S : int64
        }

        type PhaseIndexedWorkDag<'Kind,'Phase> = private {
            authority : WorkDagAuthority<'Kind>
            criticalPath : CriticalPathWorkLedger
            closureHash : string
        }

        type PhaseIndexedWorkDagState<'Kind> =
            | PhaseIndexedWorkDagOpen of PhaseIndexedWorkDag<'Kind,WorkDagOpenPhase>
            | PhaseIndexedWorkDagExhausted of PhaseIndexedWorkDag<'Kind,WorkDagExhaustedPhase>

        [<Struct>]
        type NativeRootCompleteCellId<'Kind> = private {
            value : string
        }

        // Emptiness and terminal outcome are proofs,
        // not raw values that callers may pair inconsistently.  NoFurther is
        // only constructible with an empty owner ledger and an exhausted WorkDag.
        type RecursiveOwnerLedgerEmptyProof<'Kind> = private {
            ledger : RecursiveOwnerLedger<'Kind>
            proofHash : string
        }

        type NativeTerminalOutcomeProof<'Kind> =
            | NativeTerminalMaterialProof of outcome:NativePromiseTerminalOutcome<'Kind>
            | NativeTerminalSemanticFailureProof of outcome:NativePromiseTerminalOutcome<'Kind>
            | NativeTerminalNoFurtherProof of
                outcome:NativePromiseTerminalOutcome<'Kind>
                * emptyOwners:RecursiveOwnerLedgerEmptyProof<'Kind>
                * exhaustedWorkDag:PhaseIndexedWorkDag<'Kind,WorkDagExhaustedPhase>
                * witness:TopologyWitnessMaterialization<'Kind>

        type NativeRootCompleteResolution<'Kind> =
            | NativeRootCompleteBuildOk of promiseId:string * graphHash:TerminalGraphStateHash<'Kind>
            | NativeRootCompleteSemanticFailure of promiseId:string * semanticFailureId:string * payloadClass:string * graphHash:TerminalGraphStateHash<'Kind>
            | NativeRootCompleteNoFurther of promiseId:string * terminalOutcomeId:string * reason:CompilerKernelV2.OperationalReasonId * graphHash:TerminalGraphStateHash<'Kind>

        type NativeRootCompleteTerminalProof<'Kind> = {
            cellId : NativeRootCompleteCellId<'Kind>
            graph : PhaseIndexedLiveGraph<'Kind,LiveGraphTerminalEligible>
            emptyOwners : RecursiveOwnerLedgerEmptyProof<'Kind>
            prerequisites : TerminalClosurePrerequisiteLedger<'Kind>
            workDag : PhaseIndexedWorkDag<'Kind,WorkDagExhaustedPhase>
            criticalPathRoot : PhaseIndexedWorkUnitId<'Kind,WorkUnitExhaustedPhase>
            replayKey : PhaseIndexedReplayKey<'Kind,ReplayKeyClosedPhase>
            terminalOutcome : PhaseIndexedTerminalOutcome<'Kind,TerminalOutcomeResolvedPhase>
            poisonTail : PhaseIndexedPoisonTail<'Kind,PoisonTailClosedPhase>
            outcomeProof : NativeTerminalOutcomeProof<'Kind>
            promiseId : string
            graphHash : TerminalGraphStateHash<'Kind>
            proofHash : string
        }

        type NativeRootCompleteCell<'Kind,'Phase> = private {
            id : NativeRootCompleteCellId<'Kind>
            ivar : Hopac.IVar<NativeRootCompleteResolution<'Kind>>
            proof : NativeRootCompleteTerminalProof<'Kind> option
        }

        type NativeRootCompleteState<'Kind> =
            | NativeRootCompleteOpen of NativeRootCompleteCell<'Kind,NativeRootCompleteOpenPhase>
            | NativeRootCompleteArmed of NativeRootCompleteCell<'Kind,NativeRootCompleteArmedPhase> * NativeRootCompleteTerminalProof<'Kind>
            | NativeRootCompleteResolved of NativeRootCompleteCell<'Kind,NativeRootCompleteResolvedPhase> * NativeRootCompleteTerminalProof<'Kind> * NativeRootCompleteResolution<'Kind>

        type NativeRootCompleteArmVerdict<'Kind> =
            | NativeRootCompleteObserverOnly of reason:CompilerKernelV2.OperationalReasonId * authority:LiveGraphAuthorityState<'Kind>
            | NativeRootCompleteRejectedPhase of reason:CompilerKernelV2.OperationalReasonId * authority:LiveGraphAuthorityState<'Kind>
            | NativeRootCompleteRejectedOwners of reason:CompilerKernelV2.OperationalReasonId * ledger:RecursiveOwnerLedger<'Kind>
            | NativeRootCompleteRejectedPrerequisites of reason:CompilerKernelV2.OperationalReasonId * verdict:TerminalClosurePrerequisiteVerdict<'Kind>
            | NativeRootCompleteArmedByTerminalProof of proof:NativeRootCompleteTerminalProof<'Kind>

        type NativeRootCompleteAuthorityBoundary<'Kind> =
            | NativeRootCompleteAuthorityOwnedBySchedulerPushActor of proof:NativeRootCompleteTerminalProof<'Kind>
            | NativeRootCompleteAuthorityObserverOnly of reason:CompilerKernelV2.OperationalReasonId * authority:LiveGraphAuthorityState<'Kind>

        type NativeRootCompleteWaitEdge<'Kind> =
            | NativeRootCompleteWaitsForTerminalEligible of authority:LiveGraphAuthorityState<'Kind>
            | NativeRootCompleteWaitsForOwnerClose of ledger:RecursiveOwnerLedger<'Kind>
            | NativeRootCompleteWaitsForPrerequisites of verdict:TerminalClosurePrerequisiteVerdict<'Kind>
            | NativeRootCompleteWaitsForIvarResolution of proof:NativeRootCompleteTerminalProof<'Kind>

        type NativeRootCompleteWaitAuthority =
            | NativeRootCompleteWaitObserverOnly
            | NativeRootCompleteWaitSchedulerPushOwned

        type NativeRootCompleteWaitGraph<'Kind> = {
            cellId : NativeRootCompleteCellId<'Kind> option
            edges : NativeRootCompleteWaitEdge<'Kind> list
            authority : NativeRootCompleteWaitAuthority
        }

        type TemporalLivenessObservation =
            | TemporalLivenessUnknown
            | TemporalLivenessObserved of gate:string

        type TemporalBridgeObservation =
            | TemporalBridgeUnknown
            | TemporalBridgeObserved of gate:string

        type TemporalTerminalActionObservation =
            | TemporalTerminalActionNotObserved
            | TemporalTerminalActionObserved

        type TemporalTerminalObserverEvidence = {
            waitedMs : int64
            repeat : int64
            liveness : TemporalLivenessObservation
            bridge : TemporalBridgeObservation
            terminalAction : TemporalTerminalActionObservation
        }

        type NativePromiseTerminalCommitGate<'Kind> =
            | NativePromiseTerminalCommitNotRequested of reason:CompilerKernelV2.OperationalReasonId
            | NativePromiseTerminalCommitDeferredLiveGraph of outcome:NativePromiseTerminalOutcome<'Kind> * authority:LiveGraphAuthorityState<'Kind>
            | NativePromiseTerminalCommitDeferredFreshTopologyWitness of outcome:NativePromiseTerminalOutcome<'Kind> * witness:TopologyWitnessMaterialization<'Kind> * authority:LiveGraphAuthorityState<'Kind>
            | NativePromiseTerminalCommitDeferredTypedTerminalGate of outcome:NativePromiseTerminalOutcome<'Kind> * authority:LiveGraphAuthorityState<'Kind> * observer:TemporalTerminalObserverEvidence * reason:NativeTerminalActionSuppressionReasonId
            | NativePromiseTerminalCommitBlockedByOpenOwners of outcome:NativePromiseTerminalOutcome<'Kind> * authority:LiveGraphAuthorityState<'Kind> * ledger:RecursiveOwnerLedger<'Kind> * reason:NativeTerminalActionSuppressionReasonId
            | NativePromiseTerminalCommitBlockedByWorkDagAuthority of outcome:NativePromiseTerminalOutcome<'Kind> * authority:LiveGraphAuthorityState<'Kind> * workDag:WorkDagAuthority<'Kind> * reason:NativeTerminalActionSuppressionReasonId
            | NativePromiseTerminalCommitBlockedBySchedulerCausality of outcome:NativePromiseTerminalOutcome<'Kind> * authority:LiveGraphAuthorityState<'Kind> * scheduler:SchedulerCausalAuthority<'Kind> * reason:NativeTerminalActionSuppressionReasonId
            | NativePromiseTerminalCommitBlockedByBreakthroughQuorum of outcome:NativePromiseTerminalOutcome<'Kind> * authority:LiveGraphAuthorityState<'Kind> * quorum:BreakthroughEvidenceQuorum<'Kind> * reason:NativeTerminalActionSuppressionReasonId
            | NativePromiseTerminalCommitRejectedDeadlockObserverOnly of outcome:NativePromiseTerminalOutcome<'Kind> * authority:LiveGraphAuthorityState<'Kind> * reason:NativeTerminalActionSuppressionReasonId
            | NativePromiseTerminalCommitAllowedSemanticFailure of semanticFailureId:string * promiseId:string * payloadClass:string * graph:TerminalExecutableGraphState<'Kind> * proof:NativeRootCompleteTerminalProof<'Kind>
            | NativePromiseTerminalCommitAllowedResolvedMaterial of promiseId:string * graph:TerminalExecutableGraphState<'Kind> * proof:NativeRootCompleteTerminalProof<'Kind>
            | NativePromiseTerminalCommitAllowedNoFurther of terminalOutcomeId:string * promiseId:string * reason:CompilerKernelV2.OperationalReasonId * graph:TerminalExecutableGraphState<'Kind> * proof:NativeRootCompleteTerminalProof<'Kind>

        // DOMAIN MIGRATION : the writer is no longer a loose consumer of
        // RootComplete text.  Work units, replay keys, terminal outcomes and
        // poison tails are indexed by phase; a resolved RootComplete may mint a
        // writer capability only when the critical-path WorkDag is exhausted.
        type NativeWriterArtifactPlan<'Kind> = {
            proofHash : string
            graphHash : TerminalGraphStateHash<'Kind>
            workDagClosureHash : string
            artifactSetHash : string
        }

        type NativeWriterCapability<'Kind> = private {
            proof : NativeRootCompleteTerminalProof<'Kind>
            resolution : NativeRootCompleteResolution<'Kind>
            workDag : PhaseIndexedWorkDag<'Kind,WorkDagExhaustedPhase>
            plan : NativeWriterArtifactPlan<'Kind>
        }

        // Public evidence projection for sibling modules. The capability constructor and
        // representation remain private; consumers receive only the typed facts needed
        // to bind an artifact request to the exact NativeRootComplete proof.
        type NativeWriterCapabilityEvidence<'Kind> = {
            cellId : string
            proofHash : string
            resolution : NativeRootCompleteResolution<'Kind>
            workDag : PhaseIndexedWorkDag<'Kind,WorkDagExhaustedPhase>
            workDagClosureHash : string
            artifactSetHash : string
        }

        type NativeWriterProjection<'Kind> =
            | NativeWriterProjectionBlocked of reason:CompilerKernelV2.OperationalReasonId
            | NativeWriterProjectionBuildOk of capability:NativeWriterCapability<'Kind>
            | NativeWriterProjectionBuildError of capability:NativeWriterCapability<'Kind> * resolution:NativeRootCompleteResolution<'Kind>

        type NativeRootCompleteWriterGate<'Kind> =
            | NativeRootCompleteWriterBlockedOpen
            | NativeRootCompleteWriterBlockedUnarmed of reason:CompilerKernelV2.OperationalReasonId
            | NativeRootCompleteWriterBlockedWorkDag of workDag:PhaseIndexedWorkDagState<'Kind> * reason:CompilerKernelV2.OperationalReasonId
            | NativeRootCompleteWriterReady of capability:NativeWriterCapability<'Kind>

        // BREAKTHROUGH AUTHORITY KERNEL: one recursive event spine owns graph,
        // owners, WorkDag, terminal outcome and RootComplete.  Observer events
        // may be recorded, but only typed transitions can advance the kernel.
        type NativeAuthorityKernelRunning<'Kind> = private {
            graph : PhaseIndexedLiveGraphState<'Kind>
            owners : RecursiveOwnerLedger<'Kind>
            workDag : PhaseIndexedWorkDagState<'Kind>
            waitGraph : NativeRootCompleteWaitGraph<'Kind> option
            epochHash : string
        }

        type NativeAuthorityKernelTerminalEligible<'Kind> = private {
            graph : PhaseIndexedLiveGraph<'Kind,LiveGraphTerminalEligible>
            emptyOwners : RecursiveOwnerLedgerEmptyProof<'Kind>
            prerequisites : TerminalClosurePrerequisiteLedger<'Kind>
            workDag : PhaseIndexedWorkDag<'Kind,WorkDagExhaustedPhase>
            replayKey : PhaseIndexedReplayKey<'Kind,ReplayKeyClosedPhase>
            terminalOutcome : PhaseIndexedTerminalOutcome<'Kind,TerminalOutcomeResolvedPhase>
            outcomeProof : NativeTerminalOutcomeProof<'Kind>
            poisonTail : PhaseIndexedPoisonTail<'Kind,PoisonTailClosedPhase>
            kernelHash : string
        }

        type NativeAuthorityKernelArmed<'Kind> = private {
            terminal : NativeAuthorityKernelTerminalEligible<'Kind>
            root : NativeRootCompleteState<'Kind>
            proof : NativeRootCompleteTerminalProof<'Kind>
            kernelHash : string
        }

        type NativeAuthorityKernelResolved<'Kind> = private {
            terminal : NativeAuthorityKernelTerminalEligible<'Kind>
            root : NativeRootCompleteState<'Kind>
            resolution : NativeRootCompleteResolution<'Kind>
            writerGate : NativeRootCompleteWriterGate<'Kind>
            kernelHash : string
        }

        type NativeAuthorityKernelState<'Kind> =
            | NativeAuthorityKernelRunningState of NativeAuthorityKernelRunning<'Kind>
            | NativeAuthorityKernelTerminalEligibleState of NativeAuthorityKernelTerminalEligible<'Kind>
            | NativeAuthorityKernelArmedState of NativeAuthorityKernelArmed<'Kind>
            | NativeAuthorityKernelResolvedState of NativeAuthorityKernelResolved<'Kind>

        type NativeAuthorityEvent<'Kind> =
            | NativeAuthorityObserve of TemporalTerminalObserverEvidence
            | NativeAuthorityOwnerTransaction of TypedOwnerTransactionResult<'Kind>
            | NativeAuthorityWorkDagTransition of PhaseIndexedWorkDagState<'Kind>
            | NativeAuthorityTerminalOutcomeResolved of PhaseIndexedTerminalOutcome<'Kind,TerminalOutcomeResolvedPhase>
            | NativeAuthorityRootCompleteArmed of NativeRootCompleteTerminalProof<'Kind>
            | NativeAuthorityRootCompleteResolved of NativeRootCompleteResolution<'Kind>
            | NativeAuthorityBatch of NativeAuthorityEvent<'Kind> list

        type NativeAuthorityRejectionId =
            | NativeAuthorityOwnerTransactionRejected of reason:CompilerKernelV2.OperationalReasonId
            | NativeAuthorityTerminalOutcomeRequiresTerminalEligibleGraph
            | NativeAuthorityTerminalOutcomeRejected of verdict:string
            | NativeAuthorityRootProofGraphMismatch
            | NativeAuthorityRootResolutionRequiresArmedKernel
            | NativeAuthorityOwnerMutationAfterTerminalForbidden
            | NativeAuthorityWorkDagMutationAfterTerminalForbidden
            | NativeAuthorityTerminalOutcomeAlreadyResolved
            | NativeAuthorityRootAlreadyArmed
            | NativeAuthorityArmedStateMissingRoot

        type NativeAuthorityTransition<'Kind> =
            | NativeAuthorityTransitionObserved of NativeAuthorityKernelState<'Kind>
            | NativeAuthorityTransitionAdvanced of beforeHash:string * afterHash:string * NativeAuthorityKernelState<'Kind>
            | NativeAuthorityTransitionRejected of rejection:NativeAuthorityRejectionId * NativeAuthorityKernelState<'Kind>

        [<StructuralEquality; NoComparison>]
        type TopologyWitnessMaterializationIdentity = private {
            witnessRef : CompilerIdentityKernel.ContentDigest
        }

        let private topologyWitnessMaterializationIdentityFor value : TopologyWitnessMaterializationIdentity =
            { witnessRef = CompilerIdentityKernel.ContentDigest.ofText "terminal-topology-witness" value }

        let private terminalTopologyWitnessEpochs =
            System.Collections.Concurrent.ConcurrentDictionary<TopologyWitnessMaterializationIdentity,int64>()

        let private stableTerminalGraphHash (text:string) =
            let mutable hash = 1469598103934665603UL
            for ch in text do
                hash <- (hash ^^^ uint64 (int ch)) * 1099511628211UL
            sprintf "g:%016x" hash

        let canonicalTerminalClosureId<'Kind> value : CanonicalTerminalClosureId<'Kind> =
            { value = if String.IsNullOrWhiteSpace value then "tc:unknown" else value }

        let terminalGraphEpoch<'Kind> value : TerminalGraphEpoch<'Kind> =
            { value = max 0L value }

        let terminalGraphStateHash<'Kind> value : TerminalGraphStateHash<'Kind> =
            { value = stableTerminalGraphHash value }

        type TopologyWitnessReasonId =
            | TopologyWitnessReasonTerminalLivenessDeferred
            | TopologyWitnessReasonIngressOther of canonical:CompilerKernelV2.OperationalReasonId

        let topologyWitnessReasonIdText = function
            | TopologyWitnessReasonTerminalLivenessDeferred -> "terminal_action_liveness_gate_deferred"
            | TopologyWitnessReasonIngressOther canonical -> CompilerKernelV2.OperationalReasonIdOps.text canonical

        let topologyWitnessReasonOfNativePure = function
            | NativePureTopologyWitnessConsumerDeltaBeforeSemanticFact ->
                TopologyWitnessReasonIngressOther(
                    CompilerKernelV2.OperationalReasonIdOps.create "consumer_delta_produced_topology_witness_before_semantic_fact")
            | NativePureTopologyWitnessTerminalActionLivenessGateDeferred _ ->
                TopologyWitnessReasonTerminalLivenessDeferred

        let topologyWitnessId<'Kind> value : TopologyWitnessId<'Kind> =
            { value = if String.IsNullOrWhiteSpace value then "tw:unknown" else value }

        let topologyWitnessMaterializationFor<'Kind>
            (witnessId:TopologyWitnessId<'Kind>)
            (epoch:TerminalGraphEpoch<'Kind>)
            : TopologyWitnessMaterialization<'Kind> =
            let identity = topologyWitnessMaterializationIdentityFor witnessId.value
            let mutable firstEpoch = 0L
            if terminalTopologyWitnessEpochs.TryAdd(identity, epoch.value) then
                TopologyWitnessFirstMaterialization(witnessId, epoch)
            else
                firstEpoch <- terminalTopologyWitnessEpochs.[identity]
                TopologyWitnessAlreadyMaterialized(witnessId, terminalGraphEpoch<'Kind> firstEpoch, epoch)

        let topologyWitnessMaterializationText = function
            | TopologyWitnessAbsent -> "TopologyWitness(Absent)"
            | TopologyWitnessFirstMaterialization(witnessId, epoch) ->
                "TopologyWitness(FirstMaterialization|id=" + witnessId.value + "|epoch=" + string epoch.value + ")"
            | TopologyWitnessAlreadyMaterialized(witnessId, firstEpoch, observedEpoch) ->
                "TopologyWitness(AlreadyMaterialized|id=" + witnessId.value + "|first_epoch=" + string firstEpoch.value + "|observed_epoch=" + string observedEpoch.value + ")"

        let topologyWitnessIsFresh = function
            | TopologyWitnessFirstMaterialization _ -> true
            | _ -> false

        // MIGRATION: pure topology facts are not automatically semantic/material progress.
        // First materialization of a topology witness is progress; repeating the same
        // witness becomes a stasis proof even if the drain reports topology fact rows.
        type TopologyWitnessProgressClass =
            | TopologyWitnessProgressAbsent
            | TopologyWitnessProgressFirstMaterialization
            | TopologyWitnessProgressRepeatedTopologyOnly
            | TopologyWitnessProgressSemanticMaterialFact of facts:int64
            | TopologyWitnessProgressNoMaterialFact

        let topologyWitnessProgressClassText = function
            | TopologyWitnessProgressAbsent -> "TopologyWitnessProgress(Absent)"
            | TopologyWitnessProgressFirstMaterialization -> "TopologyWitnessProgress(FirstMaterialization)"
            | TopologyWitnessProgressRepeatedTopologyOnly -> "TopologyWitnessProgress(RepeatedTopologyOnly)"
            | TopologyWitnessProgressSemanticMaterialFact facts -> "TopologyWitnessProgress(SemanticMaterialFact|facts=" + string facts + ")"
            | TopologyWitnessProgressNoMaterialFact -> "TopologyWitnessProgress(NoMaterialFact)"

        let topologyWitnessProgressClassIsMaterialProgress = function
            | TopologyWitnessProgressFirstMaterialization
            | TopologyWitnessProgressSemanticMaterialFact _ -> true
            | _ -> false

        [<StructuralEquality; NoComparison>]
        type TerminalGraphRepeatIdentity = private {
            closureRef : CompilerIdentityKernel.ContentDigest
            pending : int64
            queue : int64
            active : int64
            crossKind : int64
            sidecarPending : bool
            continuationPending : bool
        }

        let private terminalGraphRepeatIdentityFor<'Kind>
            (closureId:CanonicalTerminalClosureId<'Kind>)
            pending
            queue
            active
            crossKind
            sidecarPending
            continuationPending
            : TerminalGraphRepeatIdentity =
            { closureRef = CompilerIdentityKernel.ContentDigest.ofText "terminal-graph-closure" closureId.value
              pending = pending
              queue = queue
              active = active
              crossKind = crossKind
              sidecarPending = sidecarPending
              continuationPending = continuationPending }

        let private terminalGraphRepeatIdentityText (identity:TerminalGraphRepeatIdentity) =
            FastRuntimeFormat.format "closure_ref=%s|p=%d|q=%d|a=%d|cross=%d|sidecar=%b|continuation=%b" [| box (CompilerIdentityKernel.ContentDigest.text identity.closureRef); box identity.pending; box identity.queue; box identity.active; box identity.crossKind; box identity.sidecarPending; box identity.continuationPending |]

        let private terminalGraphStateRepeatLedger =
            System.Collections.Concurrent.ConcurrentDictionary<TerminalGraphRepeatIdentity,int64>()

        let terminalGraphObservedRepeatFor (identity:TerminalGraphRepeatIdentity) (materialProgressObserved:bool) (fallbackRepeat:int64) : int64 =
            if materialProgressObserved then
                terminalGraphStateRepeatLedger.AddOrUpdate(identity, 0L, fun (_:TerminalGraphRepeatIdentity) (_:int64) -> 0L) |> ignore
                0L
            else
                terminalGraphStateRepeatLedger.AddOrUpdate(identity, max 1L fallbackRepeat, fun (_:TerminalGraphRepeatIdentity) (previous:int64) -> max (previous + 1L) fallbackRepeat)

        let terminalExecutableGraphFor<'Kind>
            (closureId:CanonicalTerminalClosureId<'Kind>)
            (pending:int64)
            (queue:int64)
            (active:int64)
            (crossKind:int64)
            (sidecarPending:bool)
            (continuationPending:bool)
            (epoch:TerminalGraphEpoch<'Kind>)
            (sameStateRepeat:int64)
            (materialProgressObserved:bool)
            (closureAuthority:TerminalGraphClosureAuthorityId)
            : TerminalExecutableGraphState<'Kind> =
            let repeatIdentity =
                terminalGraphRepeatIdentityFor closureId pending queue active crossKind sidecarPending continuationPending
            let stateHash = terminalGraphStateHash (terminalGraphRepeatIdentityText repeatIdentity)
            let live = pending > 0L || queue > 0L || active > 0L || crossKind > 0L || sidecarPending || continuationPending
            let observedRepeat =
                if live then terminalGraphObservedRepeatFor repeatIdentity materialProgressObserved (max 0L sameStateRepeat)
                else terminalGraphObservedRepeatFor repeatIdentity true 0L
            if live && materialProgressObserved then
                let graph : TerminalExecutableGraph<'Kind,TerminalGraphProgressing> =
                    TerminalExecutableGraphNode(closureId, pending, queue, active, crossKind, sidecarPending, continuationPending, epoch, stateHash, observedRepeat, None)
                TerminalGraphProgressingState graph
            elif live then
                let graph : TerminalExecutableGraph<'Kind,TerminalGraphStalled> =
                    TerminalExecutableGraphNode(closureId, pending, queue, active, crossKind, sidecarPending, continuationPending, epoch, stateHash, observedRepeat, None)
                TerminalGraphStalledState graph
            else
                match closureAuthority with
                | TerminalGraphClosureProven _ ->
                    let graph : TerminalExecutableGraph<'Kind,TerminalGraphExhausted> =
                        TerminalExecutableGraphNode(closureId, pending, queue, active, crossKind, sidecarPending, continuationPending, epoch, stateHash, observedRepeat, None)
                    TerminalGraphExhaustedState graph
                | TerminalGraphClosureUnproven ->
                    let graph : TerminalExecutableGraph<'Kind,TerminalGraphStalled> =
                        TerminalExecutableGraphNode(closureId, pending, queue, active, crossKind, sidecarPending, continuationPending, epoch, stateHash, observedRepeat, None)
                    TerminalGraphStalledState graph

        let private terminalExecutableGraphNodeText phase = function
            | TerminalExecutableGraphNode(closureId, pending, queue, active, crossKind, sidecarPending, continuationPending, epoch, stateHash, sameStateRepeat, next) ->
                let nextText = if Option.isSome next then "recursive_continuation" else "none"
                "TerminalExecutableGraph(" + phase + "|closure=" + closureId.value + "|pending=" + string pending + "|queue=" + string queue + "|active=" + string active + "|cross=" + string crossKind + "|sidecar=" + string sidecarPending + "|continuation=" + string continuationPending + "|epoch=" + string epoch.value + "|state_hash=" + stateHash.value + "|same_state_repeat=" + string sameStateRepeat + "|next=" + nextText + ")"

        let terminalExecutableGraphStateText = function
            | TerminalGraphProgressingState graph -> terminalExecutableGraphNodeText "Progressing" graph
            | TerminalGraphStalledState graph -> terminalExecutableGraphNodeText "Stalled" graph
            | TerminalGraphExhaustedState graph -> terminalExecutableGraphNodeText "Exhausted" graph

        let terminalExecutableGraphSameStateRepeat = function
            | TerminalGraphProgressingState(TerminalExecutableGraphNode(_, _, _, _, _, _, _, _, _, repeat, _))
            | TerminalGraphStalledState(TerminalExecutableGraphNode(_, _, _, _, _, _, _, _, _, repeat, _))
            | TerminalGraphExhaustedState(TerminalExecutableGraphNode(_, _, _, _, _, _, _, _, _, repeat, _)) -> repeat

        let terminalExecutableGraphEpochValue = function
            | TerminalGraphProgressingState(TerminalExecutableGraphNode(_, _, _, _, _, _, _, epoch, _, _, _))
            | TerminalGraphStalledState(TerminalExecutableGraphNode(_, _, _, _, _, _, _, epoch, _, _, _))
            | TerminalGraphExhaustedState(TerminalExecutableGraphNode(_, _, _, _, _, _, _, epoch, _, _, _)) -> epoch

        let terminalExecutableGraphHashValue = function
            | TerminalGraphProgressingState(TerminalExecutableGraphNode(_, _, _, _, _, _, _, _, stateHash, _, _))
            | TerminalGraphStalledState(TerminalExecutableGraphNode(_, _, _, _, _, _, _, _, stateHash, _, _))
            | TerminalGraphExhaustedState(TerminalExecutableGraphNode(_, _, _, _, _, _, _, _, stateHash, _, _)) -> stateHash

        let terminalExecutableGraphLiveEvidenceText = function
            | TerminalGraphProgressingState(TerminalExecutableGraphNode(_, pending, queue, active, crossKind, sidecarPending, continuationPending, _, _, _, _))
            | TerminalGraphStalledState(TerminalExecutableGraphNode(_, pending, queue, active, crossKind, sidecarPending, continuationPending, _, _, _, _))
            | TerminalGraphExhaustedState(TerminalExecutableGraphNode(_, pending, queue, active, crossKind, sidecarPending, continuationPending, _, _, _, _)) ->
                "pending=" + string pending + "|queue=" + string queue + "|active=" + string active + "|cross=" + string crossKind + "|sidecar=" + string sidecarPending + "|continuation=" + string continuationPending

        let private terminalExecutableGraphCrossKindCount = function
            | TerminalGraphProgressingState(TerminalExecutableGraphNode(_, _, _, _, crossKind, _, _, _, _, _, _))
            | TerminalGraphStalledState(TerminalExecutableGraphNode(_, _, _, _, crossKind, _, _, _, _, _, _))
            | TerminalGraphExhaustedState(TerminalExecutableGraphNode(_, _, _, _, crossKind, _, _, _, _, _, _)) -> crossKind

        let private terminalExecutableGraphContinuationPending = function
            | TerminalGraphProgressingState(TerminalExecutableGraphNode(_, _, _, _, _, _, continuationPending, _, _, _, _))
            | TerminalGraphStalledState(TerminalExecutableGraphNode(_, _, _, _, _, _, continuationPending, _, _, _, _))
            | TerminalGraphExhaustedState(TerminalExecutableGraphNode(_, _, _, _, _, _, continuationPending, _, _, _, _)) -> continuationPending

        let private terminalExecutableGraphPendingCount = function
            | TerminalGraphProgressingState(TerminalExecutableGraphNode(_, pending, _, _, _, _, _, _, _, _, _))
            | TerminalGraphStalledState(TerminalExecutableGraphNode(_, pending, _, _, _, _, _, _, _, _, _))
            | TerminalGraphExhaustedState(TerminalExecutableGraphNode(_, pending, _, _, _, _, _, _, _, _, _)) -> pending

        let private terminalExecutableGraphQueueCount = function
            | TerminalGraphProgressingState(TerminalExecutableGraphNode(_, _, queue, _, _, _, _, _, _, _, _))
            | TerminalGraphStalledState(TerminalExecutableGraphNode(_, _, queue, _, _, _, _, _, _, _, _))
            | TerminalGraphExhaustedState(TerminalExecutableGraphNode(_, _, queue, _, _, _, _, _, _, _, _)) -> queue

        let private terminalExecutableGraphActiveCount = function
            | TerminalGraphProgressingState(TerminalExecutableGraphNode(_, _, _, active, _, _, _, _, _, _, _))
            | TerminalGraphStalledState(TerminalExecutableGraphNode(_, _, _, active, _, _, _, _, _, _, _))
            | TerminalGraphExhaustedState(TerminalExecutableGraphNode(_, _, _, active, _, _, _, _, _, _, _)) -> active

        let private terminalExecutableGraphSidecarPending = function
            | TerminalGraphProgressingState(TerminalExecutableGraphNode(_, _, _, _, _, sidecarPending, _, _, _, _, _))
            | TerminalGraphStalledState(TerminalExecutableGraphNode(_, _, _, _, _, sidecarPending, _, _, _, _, _))
            | TerminalGraphExhaustedState(TerminalExecutableGraphNode(_, _, _, _, _, sidecarPending, _, _, _, _, _)) -> sidecarPending

        let private terminalExecutableGraphClosureId = function
            | TerminalGraphProgressingState(TerminalExecutableGraphNode(closureId, _, _, _, _, _, _, _, _, _, _))
            | TerminalGraphStalledState(TerminalExecutableGraphNode(closureId, _, _, _, _, _, _, _, _, _, _))
            | TerminalGraphExhaustedState(TerminalExecutableGraphNode(closureId, _, _, _, _, _, _, _, _, _, _)) -> closureId

        let private liveGraphRequiredResolutionText = function
            | RequireMaterialDeltaBeforeCreditRelease -> "RequireMaterialDeltaBeforeCreditRelease"
            | RequireFreshTopologyWitnessBeforeCreditRelease None -> "RequireFreshTopologyWitnessBeforeCreditRelease(unknown)"
            | RequireFreshTopologyWitnessBeforeCreditRelease(Some witness) -> "RequireFreshTopologyWitnessBeforeCreditRelease(" + witness.value + ")"
            | RequireCrossKindDrainBeforeCreditRelease obligationId -> "RequireCrossKindDrainBeforeCreditRelease(" + obligationId + ")"
            | RequireParentContinuationHandoffBeforeCreditRelease cellId -> "RequireParentContinuationHandoffBeforeCreditRelease(" + cellId + ")"

        let private liveGraphConservedCreditText (lease:LiveGraphConservedCredit<'Kind>) =
            "LiveGraphConservedCredit(id=" + lease.leaseId.value
            + "|graph_hash=" + lease.graphHash.value

            + "|required=" + liveGraphRequiredResolutionText lease.requiredResolution + ")"

        let private crossKindObligationOwnerText (owner:CrossKindObligationOwnerId<'Kind>) =
            owner.value

        let private crossKindObligationCloseKeyText (closeKey:CrossKindObligationCloseKey<'Kind>) =
            closeKey.value

        let private crossKindDrainAttemptText (attempt:CrossKindDrainAttempt<'Kind>) =
            "CrossKindDrainAttempt(owner=" + crossKindObligationOwnerText attempt.owner
            + "|id=" + attempt.obligationId
            + "|before=" + string attempt.beforeCount
            + "|after=" + string attempt.afterCount
            + "|closed_by=" + crossKindObligationCloseKeyText attempt.closedBy
            + "|drained=" + string attempt.drained
            + "|reason=" + crossKindDrainReasonText attempt.reason + ")"

        let private crossKindQuarantinePlanText (plan:CrossKindQuarantinePlan<'Kind>) =
            "CrossKindQuarantinePlan(owner=" + crossKindObligationOwnerText plan.owner
            + "|id=" + plan.obligationId
            + "|remaining=" + string plan.remainingCount
            + "|lease_id=" + plan.leaseId.value
            + "|graph_hash=" + plan.graphHash.value
            + "|action=" + crossKindQuarantineActionText plan.action + ")"

        let private parentContinuationOwnerText (owner:ParentContinuationOwnerId<'Kind>) = owner.value

        let private parentContinuationCellText (cell:ParentContinuationCellId<'Kind>) = cell.value

        let private parentContinuationCloseKeyText (key:ParentContinuationCloseKey<'Kind>) = key.value

        let private parentContinuationCloseProofText (proof:ParentContinuationCloseProof<'Kind>) =
            "ParentContinuationCloseProof(owner=" + parentContinuationOwnerText proof.owner
            + "|cell=" + parentContinuationCellText proof.cellId
            + "|before=" + string proof.beforePending
            + "|after=" + string proof.afterPending
            + "|closed_by=" + parentContinuationCloseKeyText proof.closedBy
            + "|materialized_delta=" + string proof.materializedDelta
            + "|reason=" + parentContinuationCloseReasonText proof.reason + ")"

        let private parentContinuationQuarantinePlanText (plan:ParentContinuationQuarantinePlan<'Kind>) =
            "ParentContinuationQuarantinePlan(owner=" + parentContinuationOwnerText plan.owner
            + "|cell=" + parentContinuationCellText plan.cellId
            + "|pending=" + string plan.pendingCount
            + "|lease_id=" + plan.leaseId.value
            + "|graph_hash=" + plan.graphHash.value
            + "|action=" + parentContinuationQuarantineActionText plan.action + ")"

        let private parentContinuationObligationStateText = function
            | ParentContinuationAbsent -> "ParentContinuation(Absent)"
            | ParentContinuationOwned(owner, cellId, closureId, pendingCount, lease) ->
                "ParentContinuation(Owned|owner=" + parentContinuationOwnerText owner + "|cell=" + parentContinuationCellText cellId + "|closure=" + closureId.value + "|pending=" + string pendingCount + "|" + liveGraphConservedCreditText lease + ")"
            | ParentContinuationHandoffReady proof ->
                "ParentContinuation(HandoffReady|" + parentContinuationCloseProofText proof + ")"
            | ParentContinuationHandoffClosed proof ->
                "ParentContinuation(HandoffClosed|" + parentContinuationCloseProofText proof + ")"
            | ParentContinuationExpired(owner, cellId, pendingCount, leaseId, closeKey) ->
                "ParentContinuation(Expired|owner=" + parentContinuationOwnerText owner + "|cell=" + parentContinuationCellText cellId + "|pending=" + string pendingCount + "|lease_id=" + leaseId.value + "|close_key=" + parentContinuationCloseKeyText closeKey + ")"
            | ParentContinuationQuarantined plan ->
                "ParentContinuation(Quarantined|" + parentContinuationQuarantinePlanText plan + ")"

        let private crossKindObligationStateText = function
            | CrossKindObligationAbsent -> "CrossKindObligation(Absent)"
            | CrossKindObligationOwned(owner, obligationId, beforeCount, lease) ->
                "CrossKindObligation(Owned|owner=" + crossKindObligationOwnerText owner + "|id=" + obligationId + "|before=" + string beforeCount + "|" + liveGraphConservedCreditText lease + ")"
            | CrossKindObligationReduced attempt ->
                "CrossKindObligation(Reduced|" + crossKindDrainAttemptText attempt + ")"
            | CrossKindObligationExpired(owner, obligationId, remainingCount, leaseId, closeKey) ->
                "CrossKindObligation(Expired|owner=" + crossKindObligationOwnerText owner + "|id=" + obligationId + "|remaining=" + string remainingCount + "|lease_id=" + leaseId.value + "|close_key=" + crossKindObligationCloseKeyText closeKey + ")"
            | CrossKindObligationQuarantined plan ->
                "CrossKindObligation(Quarantined|" + crossKindQuarantinePlanText plan + ")"

        let rec recursiveOwnerLedgerText ledger =
            let rec loop acc = function
                | OwnerLedgerEmpty -> acc
                | OwnerLedgerCons(head, tail) ->
                    let kind =
                        match head with
                        | ParentContinuationOwnerNode _ -> "parent_continuation"
                        | CrossKindOwnerNode _ -> "cross_kind"
                        | SidecarDrainOwnerNode _ -> "sidecar_drain"
                        | DynamicBridgeOwnerNode _ -> "dynamic_bridge"
                        | PoisonTailOwnerNode _ -> "poison_tail"
                        | JoinPointWaitOwnerNode _ -> "join_point_wait"
                        | ProceduralResidualOwnerNode _ -> "procedural_residual"
                        | CicProofObligationOwnerNode _ -> "cic_proof_obligation"
                    loop (kind :: acc) tail
            let rows = loop [] ledger |> List.rev
            "RecursiveOwnerLedger(nodes=" + (if List.isEmpty rows then "none" else String.concat ";" rows) + ")"

        let private terminalOwnershipLedgerText (ledger:RecursiveOwnerLedger<'Kind>) =
            recursiveOwnerLedgerText ledger

        let private terminalOwnerClosureVerdictText = function
            | TerminalOwnersAllClosed ledger -> "TerminalOwnersAllClosed(" + terminalOwnershipLedgerText ledger + ")"
            | TerminalOwnersStillOpen(ledger, openAxes) ->
