        let private workDagAuthorityForCosts<'Kind>
            (rootId:string)
            (hotId:string)
            (parentId:string option)
            (edgeIds:string list)
            (completedCost:int64)
            (knownRemainingCost:int64)
            (blockedRemainingCost:int64)
            (undiscoveredP50Cost:int64)
            (undiscoveredP90Cost:int64)
            (materialDeltaCost:int64)
            (throughputCostPerS:float)
            (terminalP50S:int64)
            (terminalP90S:int64)
            (successP50S:int64)
            (successP90S:int64)
            (confidence:WorkDagEtaConfidenceId)
            (basis:WorkDagEtaBasisId)
            (discovery:GraphDiscoveryState)
            (creditDecision:WorkUnitCreditDecisionId)
            (stasis:GraphStasisReasonId)
            (etaStasis:EtaStasisHorizonId)
            (semanticFactDebt:SemanticFactDebtState<'Kind>)
            (ledgerClosed:bool)
            : WorkDagAuthority<'Kind> =
            let completed = max 0L completedCost
            let known = max 0L knownRemainingCost
            let blocked = max 0L blockedRemainingCost
            let p50 = max 0L undiscoveredP50Cost
            let p90 = max p50 undiscoveredP90Cost
            let total = max 1L (completed + known + blocked + p90)
            let midPct = 100.0 * (float completed) / (float total) |> max 0.0 |> min 100.0
            let lowPct = 100.0 * (float completed) / (float (max 1L (total + p90))) |> max 0.0 |> min midPct
            let highPct = 100.0 * (float (completed + max 0L (known / 2L))) / (float total) |> max midPct |> min 100.0
            {
                root = { value = if String.IsNullOrWhiteSpace rootId then "wd:root:unknown" else rootId }
                hot = { value = if String.IsNullOrWhiteSpace hotId then "wd:hot:unknown" else hotId }
                parent = parentId |> Option.filter (fun x -> not (String.IsNullOrWhiteSpace x)) |> Option.map (fun x -> { value = x })
                edges = edgeIds |> List.filter (fun x -> not (String.IsNullOrWhiteSpace x)) |> List.map (fun x -> { value = x })
                cost = {
                    completedCost = completed
                    knownRemainingCost = known
                    blockedRemainingCost = blocked
                    undiscoveredP50Cost = p50
                    undiscoveredP90Cost = p90
                    totalCost = total
                }
                progress = { lowPct = lowPct; midPct = midPct; highPct = highPct }
                eta = {
                    terminalP50S = terminalP50S
                    terminalP90S = terminalP90S
                    successP50S = successP50S
                    successP90S = successP90S
                    confidence = confidence
                    basis = basis
                }
                materialDeltaCost = max 0L materialDeltaCost
                throughputCostPerS = max 0.0 throughputCostPerS
                discovery = discovery
                creditDecision = creditDecision
                stasis = stasis
                etaStasis = etaStasis
                semanticFactDebt = semanticFactDebt
                ledgerClosed = ledgerClosed
            }

        let private workDagAuthorityForTerminalGraph<'Kind>
            (graph:TerminalExecutableGraphState<'Kind>)
            : WorkDagAuthority<'Kind> =
            let closureId = terminalExecutableGraphClosureId graph
            let graphHash = terminalExecutableGraphHashValue graph
            let repeat = terminalExecutableGraphSameStateRepeat graph
            let pending = terminalExecutableGraphPendingCount graph
            let queue = terminalExecutableGraphQueueCount graph
            let active = terminalExecutableGraphActiveCount graph
            let cross = terminalExecutableGraphCrossKindCount graph
            let sidecar = terminalExecutableGraphSidecarPending graph
            let continuation = terminalExecutableGraphContinuationPending graph
            let structuralOwnerWorkOpen = cross > 0L || sidecar || continuation
            let physicallyQuiescent = pending <= 0L && queue <= 0L && active <= 0L && not structuralOwnerWorkOpen
            let graphClosed =
                match graph with
                | TerminalGraphExhaustedState _ -> true
                | _ -> false
            let qapOnlyObserverTail = (not structuralOwnerWorkOpen) && (pending + queue + active > 0L)
            let known =
                if physicallyQuiescent || qapOnlyObserverTail then 0L
                else max 0L (pending * 13L + queue * 8L + active * 21L + cross * 34L + (if sidecar then 55L else 0L) + (if continuation then 34L else 0L))
            let completed, materialDelta =
                match graph with
                | TerminalGraphProgressingState _ -> 1L, 1L
                | TerminalGraphExhaustedState _ -> 1L, 0L
                | TerminalGraphStalledState _ -> 0L, 0L
            let discovery =
                if graphClosed then GraphDiscoveryClosed
                elif physicallyQuiescent then GraphDiscoveryOpen(0L, 0L)
                else GraphDiscoveryOpen(known, known + max 0L (repeat * 8L))
            let credit =
                if materialDelta > 0L then WorkUnitCreditMaterialDelta materialDelta
                elif graphClosed then WorkUnitCreditDeferred WorkUnitCreditTerminalGraphClosedNoMaterialDelta
                elif physicallyQuiescent then WorkUnitCreditDeferred WorkUnitCreditTerminalGraphQuiescentAwaitingClosureAuthority
                else WorkUnitCreditDeferred WorkUnitCreditTerminalGraphNoMaterialDelta
            let stasis =
                if graphClosed then GraphStasisMaterialOrFreshProgress
                elif repeat > 0L && materialDelta <= 0L then GraphStasisZeroFactOrTopologyWait repeat
                else GraphStasisMaterialOrFreshProgress
            let etaStasis =
                if graphClosed then EtaStasisNormal
                elif repeat >= 20L then EtaStasisStalledOnBoundGraph repeat
                elif materialDelta <= 0L then EtaStasisUnknownLiveGraphRate
                else EtaStasisNormal
            let semanticFactDebt =
                if materialDelta > 0L then SemanticFactDebtPaid({ value = "wd:hot:" + closureId.value }, materialDelta, "material_delta_paid_semantic_fact_debt")
                elif graphClosed then SemanticFactDebtClosedGraph(closureId, completed, "terminal_graph_exhausted_no_semantic_fact_debt")
                elif physicallyQuiescent then SemanticFactDebtNone
                else SemanticFactDebtOpen({ value = "wd:hot:" + closureId.value }, closureId, max 1L (pending + queue + active + cross), SemanticFactDebtKnownWorkWithoutSemanticFactDelta)
            workDagAuthorityForCosts
                ("wd:root:" + graphHash.value)
                ("wd:hot:" + closureId.value)
                (Some("wd:parent:" + graphHash.value))
                ["edge:root->hot:" + graphHash.value; "edge:hot->terminal:" + closureId.value]
                completed
                known
                (if repeat > 0L then known * max 1L (min 64L repeat) else 0L)
                (if known > 0L then known else 0L)
                (if known > 0L then known + max 0L (repeat * 8L) else 0L)
                materialDelta
                (if materialDelta > 0L then float materialDelta else 0.0)
                (if graphClosed then 0L else -1L)
                (if graphClosed then 0L else -1L)
                (if graphClosed then 0L else -1L)
                (if graphClosed then 0L else -1L)
                (if graphClosed then WorkDagEtaClosed elif physicallyQuiescent then WorkDagEtaQuiescentAwaitingClosureAuthority else WorkDagEtaUnknownTerminalGraphRate)
                WorkDagEtaTerminalGraphStructuralAuthority
                discovery
                credit
                stasis
                etaStasis
                semanticFactDebt
                graphClosed

        let private semanticFactDebtBlocksTerminal = function
            | SemanticFactDebtOpen _ -> true
            | _ -> false

        let private semanticFactDebtTerminalBlockReason = function
            | SemanticFactDebtOpen(hot, closure, missingFacts, reason) ->
                "semantic_fact_debt_open|hot=" + workDagNodeIdText hot + "|closure=" + closure.value + "|missing=" + string missingFacts + "|reason=" + semanticFactDebtOpenReasonText reason
            | SemanticFactDebtQuarantined(hot, missingFacts, action) ->
                "semantic_fact_debt_quarantined|hot=" + workDagNodeIdText hot + "|missing=" + string missingFacts + "|action=" + action
            | SemanticFactDebtPaid(_, producedFacts, receipt) ->
                "semantic_fact_debt_paid|produced=" + string producedFacts + "|receipt=" + receipt
            | SemanticFactDebtClosedGraph(closure, completedCost, receipt) ->
                "semantic_fact_debt_closed_graph|closure=" + closure.value + "|completed=" + string completedCost + "|receipt=" + receipt
            | SemanticFactDebtNone -> "semantic_fact_debt_none"

        let private schedulerCausalAuthorityForTerminalGraph<'Kind>
            (graph:TerminalExecutableGraphState<'Kind>)
            (workDag:WorkDagAuthority<'Kind>)
            (leaseOpt:LiveGraphConservedCredit<'Kind> option)
            (crossKind:CrossKindObligationState<'Kind>)
            (parentContinuation:ParentContinuationObligationState<'Kind>)
            : SchedulerCausalAuthority<'Kind> =
            let graphHash = terminalExecutableGraphHashValue graph
            let epoch = terminalExecutableGraphEpochValue graph
            let repeat = terminalExecutableGraphSameStateRepeat graph
            let pending = terminalExecutableGraphPendingCount graph
            let queue = terminalExecutableGraphQueueCount graph
            let active = terminalExecutableGraphActiveCount graph
            let crossOpen =
                match crossKind with
                | CrossKindObligationAbsent
                | CrossKindObligationReduced { drained = true }
                | CrossKindObligationQuarantined _ -> 0L
                | _ -> 1L
            let parentOpen =
                match parentContinuation with
                | ParentContinuationAbsent
                | ParentContinuationHandoffClosed _
                | ParentContinuationQuarantined _ -> 0L
                | _ -> 1L
            let pendingWakes = max 0L (queue + crossOpen + parentOpen)
            let liveWorkers = max 0L active
            let lostWakeRisk =
                if workDag.materialDeltaCost > 0L then 0L
                elif pendingWakes > 0L && liveWorkers <= 0L then max 1L repeat
                elif pendingWakes > 0L && repeat >= 20L then repeat
                else 0L
            let fairnessDebt =
                if pendingWakes > 0L && workDag.materialDeltaCost <= 0L then max 0L (repeat + pendingWakes + liveWorkers)
                else 0L
            let causalClosed = workDag.ledgerClosed && pendingWakes <= 0L && lostWakeRisk <= 0L && not (semanticFactDebtBlocksTerminal workDag.semanticFactDebt)
            {
                wakeToken = { value = "wake:" + graphHash.value + ":e" + string epoch.value + ":r" + string repeat }
                graphHash = graphHash
                clock = {
                    epoch = epoch.value
                    repeat = repeat
                    writerFreshMs = if workDag.materialDeltaCost > 0L then 0L else -1L
                    observerFreshMs = if pendingWakes > 0L then max 0L repeat else 0L
                }
                liveWorkers = liveWorkers
                pendingWakes = pendingWakes
                lostWakeRisk = lostWakeRisk
                fairnessDebt = fairnessDebt
                semanticFactDebt = workDag.semanticFactDebt
                causalClosed = causalClosed
                reason =
                    CompilerKernelV2.OperationalReasonIdOps.create (
                        if causalClosed then "causal_closed"
                        elif semanticFactDebtBlocksTerminal workDag.semanticFactDebt then semanticFactDebtTerminalBlockReason workDag.semanticFactDebt
                        elif lostWakeRisk > 0L then "lost_wake_risk_requires_push_receipt"
                        elif fairnessDebt > 0L then "fairness_debt_requires_worker_handoff"
                        else "scheduler_causality_open")
            }

        let private schedulerCausalVerdictFor (authority:SchedulerCausalAuthority<'Kind>) =
            if authority.causalClosed then SchedulerCausalityClosed authority
            elif authority.lostWakeRisk >= 20L || authority.fairnessDebt >= 20L then
                SchedulerCausalityDebtObserved(
                    authority,
                    authority.reason)
            else
                SchedulerCausalityOpen(
                    authority,
                    authority.reason)

        let private crossKindObligationOwnerFor<'Kind>
            (graph:TerminalExecutableGraphState<'Kind>)
            (lease:LiveGraphConservedCredit<'Kind>)
            : CrossKindObligationOwnerId<'Kind> =
            let epoch = terminalExecutableGraphEpochValue graph
            { value = "owner:cross_kind:" + lease.graphHash.value + ":e" + string epoch.value }

        let private crossKindObligationCloseKeyFor<'Kind>
            (owner:CrossKindObligationOwnerId<'Kind>)
            (lease:LiveGraphConservedCredit<'Kind>)
            (reason:CrossKindDrainReasonId)
            : CrossKindObligationCloseKey<'Kind> =
            { value = "close:" + owner.value + ":" + lease.leaseId.value + ":" + crossKindDrainReasonText reason }

        let private crossKindDrainAttemptFor<'Kind>
            (owner:CrossKindObligationOwnerId<'Kind>)
            (obligationId:string)
            (beforeCount:int64)
            (afterCount:int64)
            (closeKey:CrossKindObligationCloseKey<'Kind>)
            (reason:CrossKindDrainReasonId) =
            {
                owner = owner
                obligationId = obligationId
                beforeCount = max 0L beforeCount
                afterCount = max 0L afterCount
                closedBy = closeKey
                drained = afterCount <= 0L
                reason = reason
            }

        let private crossKindQuarantinePlanFor<'Kind>
            (owner:CrossKindObligationOwnerId<'Kind>)
            (obligationId:string)
            (remainingCount:int64)
            (leaseId:LiveGraphCreditId<'Kind>)
            (graphHash:TerminalGraphStateHash<'Kind>)
            (action:CrossKindQuarantineActionId) =
            {
                owner = owner
                obligationId = obligationId
                remainingCount = max 0L remainingCount
                leaseId = leaseId
                graphHash = graphHash
                action = action
            }

        let private liveGraphCrossKindObligationFor<'Kind>
            (graph:TerminalExecutableGraphState<'Kind>)
            (lease:LiveGraphConservedCredit<'Kind>) =
            let count = terminalExecutableGraphCrossKindCount graph
            if count <= 0L then CrossKindObligationAbsent
            else
                let owner = crossKindObligationOwnerFor graph lease
                CrossKindObligationOwned(owner, "cko:" + lease.graphHash.value, count, lease)

        let private parentContinuationOwnerFor<'Kind>
            (graph:TerminalExecutableGraphState<'Kind>)
            (lease:LiveGraphConservedCredit<'Kind>)
            : ParentContinuationOwnerId<'Kind> =
            let epoch = terminalExecutableGraphEpochValue graph
            { value = "owner:parent_continuation:" + lease.graphHash.value + ":e" + string epoch.value }

        let private parentContinuationCellFor<'Kind>
            (graph:TerminalExecutableGraphState<'Kind>)
            : ParentContinuationCellId<'Kind> =
            let graphHash = terminalExecutableGraphHashValue graph
            { value = "pco:" + graphHash.value }

        let private parentContinuationCloseKeyFor<'Kind>
            (owner:ParentContinuationOwnerId<'Kind>)
            (lease:LiveGraphConservedCredit<'Kind>)
            (reason:ParentContinuationCloseReasonId)
            : ParentContinuationCloseKey<'Kind> =
            { value = "close:" + owner.value + ":" + lease.leaseId.value + ":" + parentContinuationCloseReasonText reason }

        let private parentContinuationCloseProofFor<'Kind>
            (owner:ParentContinuationOwnerId<'Kind>)
            (cellId:ParentContinuationCellId<'Kind>)
            (beforePending:int64)
            (afterPending:int64)
            (closeKey:ParentContinuationCloseKey<'Kind>)
            (materializedDelta:bool)
            (reason:ParentContinuationCloseReasonId) =
            {
                owner = owner
                cellId = cellId
                beforePending = max 0L beforePending
                afterPending = max 0L afterPending
                closedBy = closeKey
                materializedDelta = materializedDelta
                reason = reason
            }

        let private parentContinuationQuarantinePlanFor<'Kind>
            (owner:ParentContinuationOwnerId<'Kind>)
            (cellId:ParentContinuationCellId<'Kind>)
            (pendingCount:int64)
            (leaseId:LiveGraphCreditId<'Kind>)
            (graphHash:TerminalGraphStateHash<'Kind>)
            (action:ParentContinuationQuarantineActionId) =
            {
                owner = owner
                cellId = cellId
                pendingCount = max 0L pendingCount
                leaseId = leaseId
                graphHash = graphHash
                action = action
            }

        let private liveGraphParentContinuationObligationFor<'Kind>
            (graph:TerminalExecutableGraphState<'Kind>)
            (lease:LiveGraphConservedCredit<'Kind>) =
            if terminalExecutableGraphContinuationPending graph then
                let owner = parentContinuationOwnerFor graph lease
                let cellId = parentContinuationCellFor graph
                let closureId = terminalExecutableGraphClosureId graph
                let pendingCount = max 1L (terminalExecutableGraphPendingCount graph)
                ParentContinuationOwned(owner, cellId, closureId, pendingCount, lease)
            else ParentContinuationAbsent

        let private parentContinuationIsClosed = function
            | ParentContinuationAbsent
            | ParentContinuationHandoffClosed _
            | ParentContinuationQuarantined _ -> true
            | _ -> false

        let private crossKindIsClosed = function
            | CrossKindObligationAbsent
            | CrossKindObligationReduced { drained = true }
            | CrossKindObligationQuarantined _ -> true
            | _ -> false

        let phantomOwnerIdFor<'GraphKind,'OwnerKind> value : PhantomOwnerId<'GraphKind,'OwnerKind> =
            { value = if System.String.IsNullOrWhiteSpace value then "owner:unknown" else value }

        let phantomCloseKeyFor<'GraphKind,'OwnerKind>
            (owner:PhantomOwnerId<'GraphKind,'OwnerKind>)
            value
            : PhantomCloseKey<'GraphKind,'OwnerKind> =
            { owner = owner; value = if System.String.IsNullOrWhiteSpace value then "close:unknown" else value }


        let typedOwnerLeaseFor<'GraphKind,'OwnerKind,'Phase>
            (owner:PhantomOwnerId<'GraphKind,'OwnerKind>)
            (closeKey:PhantomCloseKey<'GraphKind,'OwnerKind> option)
            (lease:LiveGraphConservedCredit<'GraphKind> option)
            (remaining:int64)
            (required:TypedOwnerRequiredResolution<'GraphKind,'OwnerKind>)
            evidence
            : TypedOwnerLease<'GraphKind,'OwnerKind,'Phase> =
            {
                owner = owner
                closeKey = closeKey
                lease = lease
                remaining = max 0L remaining
                required = required
                evidence = if System.String.IsNullOrWhiteSpace evidence then "evidence:none" else evidence
            }

        let private activeNodeIdOptionText (node:ActiveNodeId<'Kind> option) =
            match node with
            | Some node -> node.value
            | None -> "node:none"

        let private sidecarDrainTopologyStateText = function
            | PureSidecarDrainAccumulating(facts, dominant) ->
                "PureSidecarDrain(Accumulating|facts=" + string facts + "|dominant=" + activeNodeIdOptionText dominant + ")"
            | PureSidecarDrainForgivenessReady(facts, threshold, dominant) ->
                "PureSidecarDrain(ForgivenessReady|facts=" + string facts + "|threshold=" + string threshold + "|dominant=" + activeNodeIdOptionText dominant + ")"
            | SidecarDrainMaterialSemanticDelta(facts, dominant) ->
                "SidecarDrain(MaterialSemanticDelta|facts=" + string facts + "|dominant=" + activeNodeIdOptionText dominant + ")"

        let private dynamicRecordKeyBridgeTailStateText = function
            | DynamicBridgeTailAbsent -> "DynamicBridgeTail(Absent)"
            | DynamicBridgeTailLeased(bridgeId, remaining, dominant) ->
                "DynamicBridgeTail(Leased|id=" + bridgeId + "|remaining=" + string remaining + "|dominant=" + activeNodeIdOptionText dominant + ")"
            | DynamicBridgeTailExhausted(bridgeId, closeKey, dominant) ->
                "DynamicBridgeTail(Exhausted|id=" + bridgeId + "|close_key=" + closeKey + "|dominant=" + activeNodeIdOptionText dominant + ")"
            | DynamicBridgeTailQuarantined(bridgeId, closeKey, remainingOwners) ->
                "DynamicBridgeTail(Quarantined|id=" + bridgeId + "|close_key=" + closeKey + "|remaining_owners=" + string remainingOwners + ")"

        let private poisonTailOwnerStateText = function
            | PoisonTailOwnerAbsent -> "PoisonTailOwner(Absent)"
            | PoisonTailOwnerLive(poisonId, dominant) ->
                "PoisonTailOwner(Live|id=" + poisonId + "|dominant=" + activeNodeIdOptionText dominant + ")"
            | PoisonTailOwnerCloseReady(poisonId, closeKey) ->
                "PoisonTailOwner(CloseReady|id=" + poisonId + "|close_key=" + closeKey + ")"
            | PoisonTailOwnerClosed(poisonId, closeKey) ->
                "PoisonTailOwner(Closed|id=" + poisonId + "|close_key=" + closeKey + ")"

        let private proceduralResidualOwnerStateText = function
            | ProceduralResidualOwnerAbsent -> "ProceduralResidualOwner(Absent)"
            | ProceduralResidualOwnerLive(tailId, passCount, pending, queue, active, procedural) ->
                FastRuntimeFormat.format "ProceduralResidualOwner(Live|tail=%s|pass=%d|pending=%d|queue=%d|active=%d|procedural=%d)" [| box tailId; box passCount; box pending; box queue; box active; box procedural |]
            | ProceduralResidualOwnerCloseReady(tailId, closeKey, passCount, materialDelta) ->
                FastRuntimeFormat.format "ProceduralResidualOwner(CloseReady|tail=%s|close_key=%s|pass=%d|material_delta=%d)" [| box tailId; box closeKey; box passCount; box materialDelta |]
            | ProceduralResidualOwnerClosed(tailId, closeKey, receiptId) ->
                "ProceduralResidualOwner(Closed|tail=" + tailId + "|close_key=" + closeKey + "|receipt=" + receiptId + ")"
            | ProceduralResidualOwnerFailClosed(tailId, reason) ->
                "ProceduralResidualOwner(FailClosed|tail=" + tailId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let private typedOwnerRequiredResolutionText = function
            | OwnerRequireParentContinuationIvarFill cellId -> "parent_continuation_ivar_fill:" + cellId.value
            | OwnerRequireCrossKindDrain obligationId -> "cross_kind_drain:" + obligationId
            | OwnerRequireSidecarTopologyCollapse state -> "sidecar_topology_collapse:" + sidecarDrainTopologyStateText state
            | OwnerRequireDynamicBridgeQuarantine state -> "dynamic_bridge_quarantine:" + dynamicRecordKeyBridgeTailStateText state
            | OwnerRequirePoisonTailClosure state -> "poison_tail_closure:" + poisonTailOwnerStateText state
            | OwnerRequireJoinPointWake joinPointId -> "join_point_wake:" + joinPointId
            | OwnerRequireProceduralResidualDrain state -> "procedural_residual_drain:" + proceduralResidualOwnerStateText state
            | OwnerRequireCicProofWitness state ->
                match state with
                | CicProofObligationPending(obligation, universeEpoch, defEqPairRef) -> FastRuntimeFormat.format "cic_proof_pending:%u:universe_epoch=%d:defeq_ref=%u" [| box obligation.value; box universeEpoch; box defEqPairRef |]
                | CicProofObligationWitnessed(obligation, witness) -> sprintf "cic_proof_witnessed:%u:witness=%u" obligation.value witness.value
                | CicProofObligationBlocked(obligation, blockerRef) -> sprintf "cic_proof_blocked:%u:blocker=%u" obligation.value blockerRef
                | CicProofObligationClosed(obligation, witness, closeReceiptRef) -> FastRuntimeFormat.format "cic_proof_closed:%u:witness=%u:close_receipt=%u" [| box obligation.value; box witness.value; box closeReceiptRef |]
            | OwnerRequireNoFurtherAuthorityProof -> "nofurther_authority_proof"

        let private existentialOwnerLeaseIsOpen = function
            | OwnerLeaseOpen _
            | OwnerLeaseCloseReady _ -> true
            | OwnerLeaseClosed _
            | OwnerLeaseQuarantined _ -> false

        let private existentialOwnerLeaseIsClosed = function
            | OwnerLeaseClosed _ -> true
            | _ -> false

        let private existentialOwnerLeaseIsQuarantined = function
            | OwnerLeaseQuarantined _ -> true
            | _ -> false

        let private existentialOwnerLeaseStateText ownerKind = function
            | OwnerLeaseOpen lease ->
                ownerKind + "(Open|id=" + lease.owner.value + "|remaining=" + string lease.remaining + "|required=" + typedOwnerRequiredResolutionText lease.required + "|evidence=" + lease.evidence + ")"
            | OwnerLeaseCloseReady lease ->
                let closeKey = lease.closeKey |> Option.map (fun x -> x.value) |> Option.defaultValue "close:none"
                ownerKind + "(CloseReady|id=" + lease.owner.value + "|close_key=" + closeKey + "|remaining=" + string lease.remaining + "|required=" + typedOwnerRequiredResolutionText lease.required + "|evidence=" + lease.evidence + ")"
            | OwnerLeaseClosed lease ->
                let closeKey = lease.closeKey |> Option.map (fun x -> x.value) |> Option.defaultValue "close:none"
                ownerKind + "(Closed|id=" + lease.owner.value + "|close_key=" + closeKey + "|required=" + typedOwnerRequiredResolutionText lease.required + "|evidence=" + lease.evidence + ")"
            | OwnerLeaseQuarantined lease ->
                let closeKey = lease.closeKey |> Option.map (fun x -> x.value) |> Option.defaultValue "close:none"
                ownerKind + "(Quarantined|id=" + lease.owner.value + "|close_key=" + closeKey + "|remaining=" + string lease.remaining + "|required=" + typedOwnerRequiredResolutionText lease.required + "|evidence=" + lease.evidence + ")"

        let private recursiveOwnerLedgerNodeIsOpen = function
            | ParentContinuationOwnerNode lease -> existentialOwnerLeaseIsOpen lease
            | CrossKindOwnerNode lease -> existentialOwnerLeaseIsOpen lease
            | SidecarDrainOwnerNode lease -> existentialOwnerLeaseIsOpen lease
            | DynamicBridgeOwnerNode lease -> existentialOwnerLeaseIsOpen lease
            | PoisonTailOwnerNode lease -> existentialOwnerLeaseIsOpen lease
            | JoinPointWaitOwnerNode lease -> existentialOwnerLeaseIsOpen lease
            | ProceduralResidualOwnerNode lease -> existentialOwnerLeaseIsOpen lease
            | CicProofObligationOwnerNode lease -> existentialOwnerLeaseIsOpen lease

        let private recursiveOwnerLedgerNodeIsClosed = function
            | ParentContinuationOwnerNode lease -> existentialOwnerLeaseIsClosed lease
            | CrossKindOwnerNode lease -> existentialOwnerLeaseIsClosed lease
            | SidecarDrainOwnerNode lease -> existentialOwnerLeaseIsClosed lease
            | DynamicBridgeOwnerNode lease -> existentialOwnerLeaseIsClosed lease
            | PoisonTailOwnerNode lease -> existentialOwnerLeaseIsClosed lease
            | JoinPointWaitOwnerNode lease -> existentialOwnerLeaseIsClosed lease
            | ProceduralResidualOwnerNode lease -> existentialOwnerLeaseIsClosed lease
            | CicProofObligationOwnerNode lease -> existentialOwnerLeaseIsClosed lease

        let private recursiveOwnerLedgerNodeIsQuarantined = function
            | ParentContinuationOwnerNode lease -> existentialOwnerLeaseIsQuarantined lease
            | CrossKindOwnerNode lease -> existentialOwnerLeaseIsQuarantined lease
            | SidecarDrainOwnerNode lease -> existentialOwnerLeaseIsQuarantined lease
            | DynamicBridgeOwnerNode lease -> existentialOwnerLeaseIsQuarantined lease
            | PoisonTailOwnerNode lease -> existentialOwnerLeaseIsQuarantined lease
            | JoinPointWaitOwnerNode lease -> existentialOwnerLeaseIsQuarantined lease
            | ProceduralResidualOwnerNode lease -> existentialOwnerLeaseIsQuarantined lease
            | CicProofObligationOwnerNode lease -> existentialOwnerLeaseIsQuarantined lease

        let private recursiveOwnerLedgerNodeKindText = function
            | ParentContinuationOwnerNode _ -> "parent_continuation"
            | CrossKindOwnerNode _ -> "cross_kind"
            | SidecarDrainOwnerNode _ -> "sidecar_drain"
            | DynamicBridgeOwnerNode _ -> "dynamic_bridge"
            | PoisonTailOwnerNode _ -> "poison_tail"
            | JoinPointWaitOwnerNode _ -> "join_point_wait"
            | ProceduralResidualOwnerNode _ -> "procedural_residual"
            | CicProofObligationOwnerNode _ -> "cic_proof_obligation"

        let private recursiveOwnerLedgerNodeText = function
            | ParentContinuationOwnerNode lease -> existentialOwnerLeaseStateText "ParentContinuationOwner" lease
            | CrossKindOwnerNode lease -> existentialOwnerLeaseStateText "CrossKindOwner" lease
            | SidecarDrainOwnerNode lease -> existentialOwnerLeaseStateText "SidecarDrainOwner" lease
            | DynamicBridgeOwnerNode lease -> existentialOwnerLeaseStateText "DynamicBridgeOwner" lease
            | PoisonTailOwnerNode lease -> existentialOwnerLeaseStateText "PoisonTailOwner" lease
            | JoinPointWaitOwnerNode lease -> existentialOwnerLeaseStateText "JoinPointWaitOwner" lease
            | ProceduralResidualOwnerNode lease -> existentialOwnerLeaseStateText "ProceduralResidualOwner" lease
            | CicProofObligationOwnerNode lease -> existentialOwnerLeaseStateText "CicProofObligationOwner" lease

        let rec private recursiveOwnerLedgerFold folder state = function
            | OwnerLedgerEmpty -> state
            | OwnerLedgerCons(head, tail) -> recursiveOwnerLedgerFold folder (folder state head) tail

        let recursiveOwnerLedgerOpenCount ledger =
            recursiveOwnerLedgerFold (fun count node -> if recursiveOwnerLedgerNodeIsOpen node then count + 1L else count) 0L ledger

        let private recursiveOwnerLedgerClosedCount ledger =
            recursiveOwnerLedgerFold (fun count node -> if recursiveOwnerLedgerNodeIsClosed node then count + 1L else count) 0L ledger

        let private recursiveOwnerLedgerQuarantinedCount ledger =
            recursiveOwnerLedgerFold (fun count node -> if recursiveOwnerLedgerNodeIsQuarantined node then count + 1L else count) 0L ledger

        let private recursiveOwnerLedgerOpenKinds ledger =
            recursiveOwnerLedgerFold
                (fun kinds node -> if recursiveOwnerLedgerNodeIsOpen node then recursiveOwnerLedgerNodeKindText node :: kinds else kinds)
                []
                ledger
            |> List.rev

        let private recursiveOwnerLedgerDetailedText ledger =
            let rows = recursiveOwnerLedgerFold (fun rows node -> recursiveOwnerLedgerNodeText node :: rows) [] ledger |> List.rev
            "RecursiveOwnerLedger(open=" + string (recursiveOwnerLedgerOpenCount ledger)
            + "|closed=" + string (recursiveOwnerLedgerClosedCount ledger)
            + "|quarantined=" + string (recursiveOwnerLedgerQuarantinedCount ledger)
            + "|nodes=" + (if List.isEmpty rows then "none" else System.String.Join(";", rows)) + ")"

        let private typedOwnerTransactionPhaseText = function
            | OwnerTransactionPhaseOpen -> "Open"
            | OwnerTransactionPhaseQuarantined -> "Quarantined"
            | OwnerTransactionPhaseTerminalEligible -> "TerminalEligible"
            | OwnerTransactionPhaseRejected -> "Rejected"

        let private typedOwnerMutationText = function
            | ParentContinuationOwnerClosedMutation key -> "ParentContinuationClosed(close_key=" + key.value + ")"
            | CrossKindOwnerClosedMutation key -> "CrossKindClosed(close_key=" + key.value + ")"
            | SidecarDrainOwnerQuarantinedMutation key -> "SidecarDrainQuarantined(close_key=" + key.value + ")"
            | DynamicBridgeOwnerQuarantinedMutation key -> "DynamicBridgeQuarantined(close_key=" + key.value + ")"
            | PoisonTailOwnerClosedMutation key -> "PoisonTailClosed(close_key=" + key.value + ")"
            | JoinPointWaitOwnerQuarantinedMutation key -> "JoinPointWaitQuarantined(close_key=" + key.value + ")"
            | ProceduralResidualOwnerClosedMutation key -> "ProceduralResidualClosed(close_key=" + key.value + ")"
            | CicProofObligationOwnerClosedMutation key -> "CicProofObligationClosed(close_key=" + key.value + ")"

        let private ownerLedgerAxisText = function
            | OwnerAxisParentContinuation -> "parent_continuation"
            | OwnerAxisSemanticFactDebt -> "semantic_fact_debt"
            | OwnerAxisSidecarDrain -> "sidecar_drain"
            | OwnerAxisDynamicBridge -> "dynamic_bridge"
            | OwnerAxisCrossKind -> "cross_kind"
            | OwnerAxisPoisonTail -> "poison_tail"
            | OwnerAxisJoinPointWait -> "join_point_wait"
            | OwnerAxisProceduralResidual -> "procedural_residual"
            | OwnerAxisCicProofObligation -> "cic_proof_obligation"

        let private ownerLedgerAxisStageText = function
            | OwnerAxisStageOpen -> "open"
            | OwnerAxisStageClosed -> "closed"
            | OwnerAxisStageDeadlocked -> "deadlocked"
            | OwnerAxisStageQuarantined -> "quarantined"

        let private ownerLedgerAxisTransitionText (transition: OwnerLedgerAxisTransition<'GraphKind>) =
            "OwnerAxisTransition(axis=" + ownerLedgerAxisText transition.axis
            + "|before=" + ownerLedgerAxisStageText transition.beforeStage
            + "|after=" + ownerLedgerAxisStageText transition.afterStage
            + "|owner=" + transition.ownerId
            + "|close_key=" + transition.closeKey
            + "|row_ref=" + transition.rowRef
            + "|material_delta=" + string transition.materialDelta
            + "|evidence=" + transition.evidence + ")"

        let private exactOnceOwnerDrainReceiptText (receipt: ExactOnceOwnerDrainReceipt<'GraphKind>) =
            "ExactOnceOwnerDrainReceipt(id=" + receipt.receiptId
            + "|target=" + ownerLedgerAxisText receipt.targetAxis
            + "|open_before=" + string receipt.ownerOpenBefore
            + "|open_after=" + string receipt.ownerOpenAfter
            + "|qap_before=" + (let p,q,a = receipt.qapBefore in string p + "/" + string q + "/" + string a)
            + "|qap_after=" + (let p,q,a = receipt.qapAfter in string p + "/" + string q + "/" + string a)
            + "|material_delta=" + string receipt.materialDelta
            + "|semantic_fact_debt_paid=" + string receipt.semanticFactDebtPaid
            + "|terminal_eligible_after=" + string receipt.terminalEligibleAfter
            + "|transitions=" + (if List.isEmpty receipt.transitions then "none" else receipt.transitions |> List.map ownerLedgerAxisTransitionText |> String.concat ";")
            + "|after=" + recursiveOwnerLedgerText receipt.afterLedger + ")"

        let private ownerAxisTransitionForMutation rowRef materialDelta = function
            | ParentContinuationOwnerClosedMutation key -> { axis = OwnerAxisParentContinuation; beforeStage = OwnerAxisStageOpen; afterStage = OwnerAxisStageClosed; closeKey = key.value; ownerId = key.owner.value; rowRef = rowRef; materialDelta = materialDelta; evidence = "typed_parent_continuation_close" }
            | CrossKindOwnerClosedMutation key -> { axis = OwnerAxisCrossKind; beforeStage = OwnerAxisStageOpen; afterStage = OwnerAxisStageClosed; closeKey = key.value; ownerId = key.owner.value; rowRef = rowRef; materialDelta = materialDelta; evidence = "typed_cross_kind_close" }
            | SidecarDrainOwnerQuarantinedMutation key -> { axis = OwnerAxisSidecarDrain; beforeStage = OwnerAxisStageOpen; afterStage = OwnerAxisStageQuarantined; closeKey = key.value; ownerId = key.owner.value; rowRef = rowRef; materialDelta = materialDelta; evidence = "typed_sidecar_quarantine" }
            | DynamicBridgeOwnerQuarantinedMutation key -> { axis = OwnerAxisDynamicBridge; beforeStage = OwnerAxisStageOpen; afterStage = OwnerAxisStageQuarantined; closeKey = key.value; ownerId = key.owner.value; rowRef = rowRef; materialDelta = materialDelta; evidence = "typed_dynamic_bridge_quarantine" }
            | PoisonTailOwnerClosedMutation key -> { axis = OwnerAxisPoisonTail; beforeStage = OwnerAxisStageOpen; afterStage = OwnerAxisStageClosed; closeKey = key.value; ownerId = key.owner.value; rowRef = rowRef; materialDelta = materialDelta; evidence = "typed_poison_tail_close" }
            | JoinPointWaitOwnerQuarantinedMutation key -> { axis = OwnerAxisJoinPointWait; beforeStage = OwnerAxisStageOpen; afterStage = OwnerAxisStageQuarantined; closeKey = key.value; ownerId = key.owner.value; rowRef = rowRef; materialDelta = materialDelta; evidence = "typed_join_point_wait_quarantine" }
            | ProceduralResidualOwnerClosedMutation key -> { axis = OwnerAxisProceduralResidual; beforeStage = OwnerAxisStageOpen; afterStage = OwnerAxisStageClosed; closeKey = key.value; ownerId = key.owner.value; rowRef = rowRef; materialDelta = materialDelta; evidence = "typed_procedural_residual_exact_once_close" }
            | CicProofObligationOwnerClosedMutation key -> { axis = OwnerAxisCicProofObligation; beforeStage = OwnerAxisStageOpen; afterStage = OwnerAxisStageClosed; closeKey = key.value; ownerId = key.owner.value; rowRef = rowRef; materialDelta = materialDelta; evidence = "typed_cic_proof_witness_exact_once_close" }

        let private exactOnceOwnerDrainReceiptForTransaction (rowRef:string) qapBefore qapAfter (materialDelta:int64) (targetAxis:OwnerLedgerAxisId) (receipt:TypedOwnerTransactionReceipt<'GraphKind>) =
            let transitions = receipt.mutations |> List.map (ownerAxisTransitionForMutation rowRef materialDelta)
            let qAfterP, qAfterQ, qAfterA = qapAfter
            let qapExhausted = qAfterP <= 0L && qAfterQ <= 0L && qAfterA <= 0L
            let ownerClosedOrQuarantined = receipt.openAfter = 0L
            { receiptId = receipt.transactionId + ":exact_once_owner_drain"
              beforeLedger = receipt.beforeLedger
              afterLedger = receipt.afterLedger
              ownerOpenBefore = receipt.openBefore
              ownerOpenAfter = receipt.openAfter
              qapBefore = qapBefore
              qapAfter = qapAfter
              materialDelta = materialDelta
              targetAxis = targetAxis
              transitions = transitions
              semanticFactDebtPaid = materialDelta > 0L || (ownerClosedOrQuarantined && qapExhausted)
              terminalEligibleAfter = ownerClosedOrQuarantined && (materialDelta > 0L || qapExhausted || receipt.phaseAfter = OwnerTransactionPhaseTerminalEligible) }

        let private ownerLedgerAxisForNode = function
            | ParentContinuationOwnerNode _ -> OwnerAxisParentContinuation
            | CrossKindOwnerNode _ -> OwnerAxisCrossKind
            | SidecarDrainOwnerNode _ -> OwnerAxisSidecarDrain
            | DynamicBridgeOwnerNode _ -> OwnerAxisDynamicBridge
            | PoisonTailOwnerNode _ -> OwnerAxisPoisonTail
            | JoinPointWaitOwnerNode _ -> OwnerAxisJoinPointWait
            | ProceduralResidualOwnerNode _ -> OwnerAxisProceduralResidual
            | CicProofObligationOwnerNode _ -> OwnerAxisCicProofObligation

        let private ownerLedgerAxesBy predicate ledger =
            recursiveOwnerLedgerFold
                (fun axes node -> if predicate node then ownerLedgerAxisForNode node :: axes else axes)
                []
                ledger
            |> List.rev

        let private ownerLedgerQuorumStateText = function
            | OwnerLedgerQuorumOpen -> "open"
            | OwnerLedgerQuorumClosed -> "closed"
            | OwnerLedgerQuorumDeadlocked -> "deadlocked"
            | OwnerLedgerQuorumQuarantined -> "quarantined"

        let private ownerLedgerQuorumText (quorum: OwnerLedgerQuorum<'GraphKind>) =
            "OwnerLedgerQuorum(id=" + quorum.quorumId
            + "|state=" + ownerLedgerQuorumStateText quorum.state
            + "|open=" + string quorum.openOwnerCount
            + "|closed=" + string quorum.closedOwnerCount
            + "|quarantined=" + string quorum.quarantinedOwnerCount
            + "|open_axes=" + (if List.isEmpty quorum.openAxes then "none" else quorum.openAxes |> List.map ownerLedgerAxisText |> String.concat ",")
            + "|closed_axes=" + (if List.isEmpty quorum.closedAxes then "none" else quorum.closedAxes |> List.map ownerLedgerAxisText |> String.concat ",")
            + "|quarantined_axes=" + (if List.isEmpty quorum.quarantinedAxes then "none" else quorum.quarantinedAxes |> List.map ownerLedgerAxisText |> String.concat ",")
            + "|receipt=" + (quorum.receiptId |> Option.defaultValue "none")
            + "|material_delta=" + string quorum.materialDelta
            + "|semantic_fact_debt_paid=" + string quorum.semanticFactDebtPaid
            + "|terminal_eligible=" + string quorum.terminalEligible
            + "|decision=" + quorum.decision + ")"

        let private ownerLedgerQuorumForLedger (quorumId:string) (decision:string) (materialDelta:int64) (semanticFactDebtPaid:bool) (receiptId:string option) (transitions:OwnerLedgerAxisTransition<'GraphKind> list) (ledger:RecursiveOwnerLedger<'GraphKind>) =
            let openCount = recursiveOwnerLedgerOpenCount ledger
            let closedCount = recursiveOwnerLedgerClosedCount ledger
            let quarantinedCount = recursiveOwnerLedgerQuarantinedCount ledger
            let openAxes = ownerLedgerAxesBy recursiveOwnerLedgerNodeIsOpen ledger
            let closedAxes = ownerLedgerAxesBy recursiveOwnerLedgerNodeIsClosed ledger
            let quarantinedAxes = ownerLedgerAxesBy recursiveOwnerLedgerNodeIsQuarantined ledger
            let ownerAxisClosed = openCount = 0L && List.isEmpty openAxes
            let terminalEligible = ownerAxisClosed && (semanticFactDebtPaid || materialDelta > 0L || quarantinedCount > 0L)
            let state =
                if terminalEligible || ownerAxisClosed then OwnerLedgerQuorumClosed
                elif openCount > 1L then OwnerLedgerQuorumDeadlocked
                elif quarantinedCount > 0L then OwnerLedgerQuorumQuarantined
                else OwnerLedgerQuorumOpen
            { quorumId = quorumId
              ledger = ledger
              openOwnerCount = openCount
              closedOwnerCount = closedCount
              quarantinedOwnerCount = quarantinedCount
              openAxes = openAxes
              closedAxes = closedAxes
              quarantinedAxes = quarantinedAxes
              transitions = transitions
              receiptId = receiptId
              materialDelta = materialDelta
              semanticFactDebtPaid = semanticFactDebtPaid
              terminalEligible = terminalEligible
              state = state
              decision = decision }

        let private ownerLedgerQuorumForReceipt (receipt: ExactOnceOwnerDrainReceipt<'GraphKind>) =
            ownerLedgerQuorumForLedger
                (receipt.receiptId + ":quorum")
                "exact_once_owner_drain_receipt"
                receipt.materialDelta
                receipt.semanticFactDebtPaid
                (Some receipt.receiptId)
                receipt.transitions
                receipt.afterLedger

        let private terminalQuorumDecisionForOwnerLedgerQuorum (quorum: OwnerLedgerQuorum<'GraphKind>) =
            // Owner closure and semantic fact debt are related but not the same
            // authority.  The 1967 trace exposed an empty recursive owner
            // ledger rendered as `TerminalOwnersStillOpen(reason=typed_owner_ledger_open:)`.
            // If no owner axis is open, owner quorum is closed; later writer/root
            // seal checks still decide whether a semantic receipt is required.
            if quorum.terminalEligible || (quorum.openOwnerCount = 0L && List.isEmpty quorum.openAxes) then TerminalQuorumEligible quorum
            else
                match quorum.state with
                | OwnerLedgerQuorumDeadlocked -> TerminalQuorumDeadlockedByOwnerLedger quorum
                | OwnerLedgerQuorumQuarantined -> TerminalQuorumQuarantinedByOwnerLedger quorum
                | _ -> TerminalQuorumBlockedByOpenOwners quorum

        let private terminalQuorumDecisionText = function
            | TerminalQuorumEligible quorum -> "TerminalQuorumDecision(Eligible|" + ownerLedgerQuorumText quorum + ")"
            | TerminalQuorumBlockedByOpenOwners quorum -> "TerminalQuorumDecision(BlockedByOpenOwners|" + ownerLedgerQuorumText quorum + ")"
            | TerminalQuorumDeadlockedByOwnerLedger quorum -> "TerminalQuorumDecision(DeadlockedByOwnerLedger|" + ownerLedgerQuorumText quorum + ")"
            | TerminalQuorumQuarantinedByOwnerLedger quorum -> "TerminalQuorumDecision(QuarantinedByOwnerLedger|" + ownerLedgerQuorumText quorum + ")"

        let private sidecarDrainCausalityPhaseText = function
            | SidecarTopologyWitnessObserved -> "topology_witness_observed"
            | SidecarSemanticFactRequired -> "semantic_fact_required"
            | SidecarSemanticFactMaterialized -> "semantic_fact_materialized"
            | SidecarSemanticFactQuarantined -> "semantic_fact_quarantined"

        let private strictSidecarDrainCausalityText (causality: StrictSidecarDrainCausality<'GraphKind>) =
            "StrictSidecarDrainCausality(phase=" + sidecarDrainCausalityPhaseText causality.phase
            + "|topology_facts=" + string causality.topologyFacts
            + "|semantic_facts=" + string causality.semanticFacts
            + "|missing=" + causality.missingDependency
            + "|wait_edge=" + causality.waitGraphEdge + ")"

        let private sidecarDataflowPromiseText (promise: SidecarDataflowPromise<'GraphKind,'Phase>) =
            "SidecarDataflowPromise(id=" + promise.promiseId
            + "|node=" + activeNodeIdOptionText promise.node
            + "|topology_facts=" + string promise.topologyFacts
            + "|semantic_facts=" + string promise.semanticFacts
            + "|dependency=" + promise.dependency
            + "|wait_edge=" + promise.waitGraphEdge
            + "|receipt=" + (promise.receiptId |> Option.defaultValue "none") + ")"

        let private strictSidecarDataflowBindText (bind: StrictSidecarDataflowBind<'GraphKind,'FromPhase,'ToPhase>) =
            "StrictSidecarDataflowBind(id=" + bind.bindId
            + "|prerequisite=" + sidecarDataflowPromiseText bind.prerequisite
            + "|continuation=" + sidecarDataflowPromiseText bind.continuation
            + "|hopac_bind_contract=" + bind.hopacBindContract
            + "|consumer_schedulable=" + string bind.consumerSchedulable
            + "|nofurther_legal=" + string bind.noFurtherLegal + ")"

        let private strictSidecarDataflowDecisionText = function
            | StrictSidecarBindRequired bind -> "StrictSidecarDataflowDecision(BindRequired|" + strictSidecarDataflowBindText bind + ")"
            | StrictSidecarBindSatisfied bind -> "StrictSidecarDataflowDecision(BindSatisfied|" + strictSidecarDataflowBindText bind + ")"
            | StrictSidecarBindQuarantined(bind, reason) -> "StrictSidecarDataflowDecision(BindQuarantined|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|" + strictSidecarDataflowBindText bind + ")"
            | StrictSidecarBindIllegalNoFurther(promise, reason) -> "StrictSidecarDataflowDecision(IllegalNoFurther|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|topology=" + sidecarDataflowPromiseText promise + ")"

        let private strictSidecarDataflowDecisionForCausality (closureId:string) (nativePromiseId:string) (causality: StrictSidecarDrainCausality<'GraphKind>) =
            let topologyPromise : SidecarDataflowPromise<'GraphKind,TopologyPromisePhase> =
                { promiseId = nativePromiseId + ":topology:" + closureId
                  node = causality.node
                  topologyFacts = causality.topologyFacts
                  semanticFacts = 0L
                  dependency = "topology_witness"
                  waitGraphEdge = causality.waitGraphEdge
                  receiptId = None }
            let semanticFacts = max 0L causality.semanticFacts
            if semanticFacts > 0L then
                let semanticPromise : SidecarDataflowPromise<'GraphKind,SemanticPromisePhase> =
                    { promiseId = nativePromiseId + ":semantic:" + closureId
                      node = causality.node
                      topologyFacts = causality.topologyFacts
                      semanticFacts = semanticFacts
                      dependency = "semantic_fact_materialized"
                      waitGraphEdge = causality.waitGraphEdge
                      receiptId = Some (nativePromiseId + ":semantic_fact_receipt") }
                StrictSidecarBindSatisfied
                    { bindId = nativePromiseId + ":topology_to_semantic_bind"
                      prerequisite = topologyPromise
                      continuation = semanticPromise
                      hopacBindContract = "Job.bind(topology_witness, semantic_sidecar_fact)"
                      consumerSchedulable = true
                      noFurtherLegal = true }
            else
                let semanticPromise : SidecarDataflowPromise<'GraphKind,SemanticSidecarBlockedPhase> =
                    { promiseId = nativePromiseId + ":semantic:" + closureId
                      node = causality.node
                      topologyFacts = causality.topologyFacts
                      semanticFacts = 0L
                      dependency = causality.missingDependency
                      waitGraphEdge = causality.waitGraphEdge
                      receiptId = None }
                StrictSidecarBindRequired
                    { bindId = nativePromiseId + ":topology_to_semantic_bind"
                      prerequisite = topologyPromise
                      continuation = semanticPromise
                      hopacBindContract = "Job.bind(topology_witness, semantic_sidecar_fact)"
                      consumerSchedulable = false
                      noFurtherLegal = false }

        let typedOwnerTransactionReceiptText receipt =
            "TypedOwnerTransaction(id=" + receipt.transactionId
            + "|phase=" + typedOwnerTransactionPhaseText receipt.phaseAfter
            + "|open_before=" + string receipt.openBefore
            + "|open_after=" + string receipt.openAfter
            + "|quarantined_after=" + string receipt.quarantinedAfter
            + "|mutations=" + (if List.isEmpty receipt.mutations then "none" else receipt.mutations |> List.map typedOwnerMutationText |> String.concat ";")
            + "|evidence=" + receipt.evidence
            + "|after=" + recursiveOwnerLedgerText receipt.afterLedger + ")"

        let typedOwnerTransactionResultText = function
            | TypedOwnerTransactionRejected(transactionId, reason, ledger) ->
                "TypedOwnerTransactionRejected(id=" + transactionId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|ledger=" + recursiveOwnerLedgerText ledger + ")"
            | TypedOwnerTransactionCommitted receipt -> typedOwnerTransactionReceiptText receipt

        let typedOwnerTransactionResultCommitted = function
            | TypedOwnerTransactionCommitted receipt when receipt.phaseAfter = OwnerTransactionPhaseTerminalEligible -> true
            | _ -> false

        let typedOwnerTransactionResultOpenAfter = function
            | TypedOwnerTransactionRejected(_, _, ledger) -> recursiveOwnerLedgerOpenCount ledger
            | TypedOwnerTransactionCommitted receipt -> receipt.openAfter

        let typedOwnerTransactionResultPhaseText = function
            | TypedOwnerTransactionRejected _ -> typedOwnerTransactionPhaseText OwnerTransactionPhaseRejected
            | TypedOwnerTransactionCommitted receipt -> typedOwnerTransactionPhaseText receipt.phaseAfter

        let private applyTypedOwnerCloseActionToNode action node =
            match action, node with
            | CloseParentContinuationWith(key, cellId, fillReceipt), ParentContinuationOwnerNode(OwnerLeaseOpen lease)
                when lease.owner.value = key.owner.value ->
                let closed : TypedOwnerLease<_,ParentContinuationOwnerKind,OwnerClosedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireParentContinuationIvarFill cellId) ("parent_continuation_ivar_filled:" + fillReceipt)
                ParentContinuationOwnerNode(OwnerLeaseClosed closed), Some(ParentContinuationOwnerClosedMutation key)
            | CloseParentContinuationWith(key, cellId, fillReceipt), ParentContinuationOwnerNode(OwnerLeaseCloseReady lease)
                when lease.owner.value = key.owner.value ->
                let closed : TypedOwnerLease<_,ParentContinuationOwnerKind,OwnerClosedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireParentContinuationIvarFill cellId) ("parent_continuation_ivar_filled:" + fillReceipt)
                ParentContinuationOwnerNode(OwnerLeaseClosed closed), Some(ParentContinuationOwnerClosedMutation key)
            | CloseParentContinuationWith(key, _, _), ParentContinuationOwnerNode(OwnerLeaseClosed lease)
                when lease.owner.value = key.owner.value ->
                node, Some(ParentContinuationOwnerClosedMutation key)

            | CloseCrossKindWith(key, obligationId), CrossKindOwnerNode(OwnerLeaseOpen lease)
                when lease.owner.value = key.owner.value ->
                let closed : TypedOwnerLease<_,CrossKindOwnerKind,OwnerClosedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireCrossKindDrain obligationId) "cross_kind_drain_closed"
                CrossKindOwnerNode(OwnerLeaseClosed closed), Some(CrossKindOwnerClosedMutation key)
            | CloseCrossKindWith(key, obligationId), CrossKindOwnerNode(OwnerLeaseCloseReady lease)
                when lease.owner.value = key.owner.value ->
                let closed : TypedOwnerLease<_,CrossKindOwnerKind,OwnerClosedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireCrossKindDrain obligationId) "cross_kind_drain_closed"
                CrossKindOwnerNode(OwnerLeaseClosed closed), Some(CrossKindOwnerClosedMutation key)
            | CloseCrossKindWith(key, _), CrossKindOwnerNode(OwnerLeaseClosed lease)
                when lease.owner.value = key.owner.value ->
                node, Some(CrossKindOwnerClosedMutation key)

            | QuarantineSidecarDrainWith(key, state), SidecarDrainOwnerNode(OwnerLeaseOpen lease)
                when lease.owner.value = key.owner.value ->
                let quarantined : TypedOwnerLease<_,SidecarDrainOwnerKind,OwnerQuarantinedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireSidecarTopologyCollapse state) "pure_sidecar_topology_debt_forgiven_and_quarantined"
                SidecarDrainOwnerNode(OwnerLeaseQuarantined quarantined), Some(SidecarDrainOwnerQuarantinedMutation key)
            | QuarantineSidecarDrainWith(key, state), SidecarDrainOwnerNode(OwnerLeaseCloseReady lease)
                when lease.owner.value = key.owner.value ->
                let quarantined : TypedOwnerLease<_,SidecarDrainOwnerKind,OwnerQuarantinedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireSidecarTopologyCollapse state) "pure_sidecar_topology_debt_forgiven_and_quarantined"
                SidecarDrainOwnerNode(OwnerLeaseQuarantined quarantined), Some(SidecarDrainOwnerQuarantinedMutation key)
            | QuarantineSidecarDrainWith(key, _), SidecarDrainOwnerNode(OwnerLeaseQuarantined lease)
                when lease.owner.value = key.owner.value ->
                node, Some(SidecarDrainOwnerQuarantinedMutation key)

            | QuarantineDynamicBridgeWith(key, state), DynamicBridgeOwnerNode(OwnerLeaseOpen lease)
                when lease.owner.value = key.owner.value ->
                let quarantined : TypedOwnerLease<_,DynamicBridgeOwnerKind,OwnerQuarantinedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireDynamicBridgeQuarantine state) "dynamic_record_key_bridge_tail_quarantined"
                DynamicBridgeOwnerNode(OwnerLeaseQuarantined quarantined), Some(DynamicBridgeOwnerQuarantinedMutation key)
            | QuarantineDynamicBridgeWith(key, state), DynamicBridgeOwnerNode(OwnerLeaseCloseReady lease)
                when lease.owner.value = key.owner.value ->
                let quarantined : TypedOwnerLease<_,DynamicBridgeOwnerKind,OwnerQuarantinedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireDynamicBridgeQuarantine state) "dynamic_record_key_bridge_tail_quarantined"
                DynamicBridgeOwnerNode(OwnerLeaseQuarantined quarantined), Some(DynamicBridgeOwnerQuarantinedMutation key)
            | QuarantineDynamicBridgeWith(key, _), DynamicBridgeOwnerNode(OwnerLeaseQuarantined lease)
                when lease.owner.value = key.owner.value ->
                node, Some(DynamicBridgeOwnerQuarantinedMutation key)

            | ClosePoisonTailWith(key, state), PoisonTailOwnerNode(OwnerLeaseOpen lease)
                when lease.owner.value = key.owner.value ->
                let closed : TypedOwnerLease<_,PoisonTailOwnerKind,OwnerClosedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequirePoisonTailClosure state) "poison_tail_closed_after_owner_transaction"
                PoisonTailOwnerNode(OwnerLeaseClosed closed), Some(PoisonTailOwnerClosedMutation key)
            | ClosePoisonTailWith(key, state), PoisonTailOwnerNode(OwnerLeaseCloseReady lease)
                when lease.owner.value = key.owner.value ->
                let closed : TypedOwnerLease<_,PoisonTailOwnerKind,OwnerClosedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequirePoisonTailClosure state) "poison_tail_closed_after_owner_transaction"
                PoisonTailOwnerNode(OwnerLeaseClosed closed), Some(PoisonTailOwnerClosedMutation key)
            | ClosePoisonTailWith(key, _), PoisonTailOwnerNode(OwnerLeaseClosed lease)
                when lease.owner.value = key.owner.value ->
                node, Some(PoisonTailOwnerClosedMutation key)

            | QuarantineJoinPointWaitWith(key, joinPointId), JoinPointWaitOwnerNode(OwnerLeaseOpen lease)
                when lease.owner.value = key.owner.value ->
                let quarantined : TypedOwnerLease<_,JoinPointWaitOwnerKind,OwnerQuarantinedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireJoinPointWake joinPointId) "join_point_wait_quarantined"
                JoinPointWaitOwnerNode(OwnerLeaseQuarantined quarantined), Some(JoinPointWaitOwnerQuarantinedMutation key)
            | QuarantineJoinPointWaitWith(key, joinPointId), JoinPointWaitOwnerNode(OwnerLeaseCloseReady lease)
                when lease.owner.value = key.owner.value ->
                let quarantined : TypedOwnerLease<_,JoinPointWaitOwnerKind,OwnerQuarantinedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireJoinPointWake joinPointId) "join_point_wait_quarantined"
                JoinPointWaitOwnerNode(OwnerLeaseQuarantined quarantined), Some(JoinPointWaitOwnerQuarantinedMutation key)
            | QuarantineJoinPointWaitWith(key, _), JoinPointWaitOwnerNode(OwnerLeaseQuarantined lease)
                when lease.owner.value = key.owner.value ->
                node, Some(JoinPointWaitOwnerQuarantinedMutation key)

            | CloseProceduralResidualWith(key, state, exactOnceReceipt), ProceduralResidualOwnerNode(OwnerLeaseOpen lease)
                when lease.owner.value = key.owner.value ->
                let closedState =
                    match state with
                    | ProceduralResidualOwnerCloseReady(tailId, closeKey, _, _) -> ProceduralResidualOwnerClosed(tailId, closeKey, exactOnceReceipt)
                    | ProceduralResidualOwnerLive(tailId, _, _, _, _, _) -> ProceduralResidualOwnerClosed(tailId, key.value, exactOnceReceipt)
                    | ProceduralResidualOwnerClosed _ as closed -> closed
                    | ProceduralResidualOwnerAbsent -> ProceduralResidualOwnerClosed("procedural-residual:unknown", key.value, exactOnceReceipt)
                    | ProceduralResidualOwnerFailClosed(tailId, reason) -> ProceduralResidualOwnerFailClosed(tailId, reason)
                let closed : TypedOwnerLease<_,ProceduralResidualOwnerKind,OwnerClosedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireProceduralResidualDrain closedState) ("procedural_residual_closed_exact_once:" + exactOnceReceipt)
                ProceduralResidualOwnerNode(OwnerLeaseClosed closed), Some(ProceduralResidualOwnerClosedMutation key)
            | CloseProceduralResidualWith(key, state, exactOnceReceipt), ProceduralResidualOwnerNode(OwnerLeaseCloseReady lease)
                when lease.owner.value = key.owner.value ->
                let closedState =
                    match state with
                    | ProceduralResidualOwnerCloseReady(tailId, closeKey, _, _) -> ProceduralResidualOwnerClosed(tailId, closeKey, exactOnceReceipt)
                    | ProceduralResidualOwnerLive(tailId, _, _, _, _, _) -> ProceduralResidualOwnerClosed(tailId, key.value, exactOnceReceipt)
                    | ProceduralResidualOwnerClosed _ as closed -> closed
                    | ProceduralResidualOwnerAbsent -> ProceduralResidualOwnerClosed("procedural-residual:unknown", key.value, exactOnceReceipt)
                    | ProceduralResidualOwnerFailClosed(tailId, reason) -> ProceduralResidualOwnerFailClosed(tailId, reason)
                let closed : TypedOwnerLease<_,ProceduralResidualOwnerKind,OwnerClosedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireProceduralResidualDrain closedState) ("procedural_residual_closed_exact_once:" + exactOnceReceipt)
                ProceduralResidualOwnerNode(OwnerLeaseClosed closed), Some(ProceduralResidualOwnerClosedMutation key)
            | CloseProceduralResidualWith(key, _, _), ProceduralResidualOwnerNode(OwnerLeaseClosed lease)
                when lease.owner.value = key.owner.value ->
                node, Some(ProceduralResidualOwnerClosedMutation key)
            | CloseCicProofObligationWith(key, state, witnessRef), CicProofObligationOwnerNode(OwnerLeaseOpen lease)
                when lease.owner.value = key.owner.value ->
                let obligation =
                    match state with
                    | CicProofObligationPending(obligation, _, _)
                    | CicProofObligationWitnessed(obligation, _)
                    | CicProofObligationBlocked(obligation, _)
                    | CicProofObligationClosed(obligation, _, _) -> obligation
                let closeReceiptRef =
                    NativeCutoverStableRef.ref32
                        "cic-proof-obligation-close"
                        [ string key.value; string witnessRef.value ]
                let closedState = CicProofObligationClosed(obligation, witnessRef, closeReceiptRef)
                let closed : TypedOwnerLease<_,CicProofObligationOwnerKind,OwnerClosedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireCicProofWitness closedState) ("cic_proof_obligation_closed_exact_once:" + string closeReceiptRef)
                CicProofObligationOwnerNode(OwnerLeaseClosed closed), Some(CicProofObligationOwnerClosedMutation key)
            | CloseCicProofObligationWith(key, state, witnessRef), CicProofObligationOwnerNode(OwnerLeaseCloseReady lease)
                when lease.owner.value = key.owner.value ->
                let obligation =
                    match state with
                    | CicProofObligationPending(obligation, _, _)
                    | CicProofObligationWitnessed(obligation, _)
                    | CicProofObligationBlocked(obligation, _)
                    | CicProofObligationClosed(obligation, _, _) -> obligation
                let closeReceiptRef =
                    NativeCutoverStableRef.ref32
                        "cic-proof-obligation-close"
                        [ string key.value; string witnessRef.value ]
                let closedState = CicProofObligationClosed(obligation, witnessRef, closeReceiptRef)
                let closed : TypedOwnerLease<_,CicProofObligationOwnerKind,OwnerClosedPhase> =
                    typedOwnerLeaseFor key.owner (Some key) lease.lease 0L (OwnerRequireCicProofWitness closedState) ("cic_proof_obligation_closed_exact_once:" + string closeReceiptRef)
                CicProofObligationOwnerNode(OwnerLeaseClosed closed), Some(CicProofObligationOwnerClosedMutation key)
            | CloseCicProofObligationWith(key, _, _), CicProofObligationOwnerNode(OwnerLeaseClosed lease)
                when lease.owner.value = key.owner.value ->
                node, Some(CicProofObligationOwnerClosedMutation key)
            | _ -> node, None

        let rec private applyTypedOwnerCloseActionToLedger action = function
            | OwnerLedgerEmpty -> None
            | OwnerLedgerCons(head, tail) ->
                let headAfter, mutation = applyTypedOwnerCloseActionToNode action head
                match mutation with
                | Some mutation -> Some(OwnerLedgerCons(headAfter, tail), mutation)
                | None ->
                    match applyTypedOwnerCloseActionToLedger action tail with
                    | Some(tailAfter, mutation) -> Some(OwnerLedgerCons(head, tailAfter), mutation)
                    | None -> None

        let executeTypedOwnerTransaction transactionId evidence actions beforeLedger =
            let rec applyAll current mutations = function
                | [] ->
                    let openAfter = recursiveOwnerLedgerOpenCount current
                    let quarantinedAfter = recursiveOwnerLedgerQuarantinedCount current
                    let phaseAfter =
                        if openAfter = 0L then OwnerTransactionPhaseTerminalEligible
                        elif quarantinedAfter > 0L then OwnerTransactionPhaseQuarantined
                        else OwnerTransactionPhaseOpen
                    TypedOwnerTransactionCommitted {
                        transactionId = transactionId
                        beforeLedger = beforeLedger
                        afterLedger = current
                        mutations = List.rev mutations
                        openBefore = recursiveOwnerLedgerOpenCount beforeLedger
                        openAfter = openAfter
                        quarantinedAfter = quarantinedAfter
                        phaseAfter = phaseAfter
                        evidence = evidence
                    }
                | action :: rest ->
                    match applyTypedOwnerCloseActionToLedger action current with
                    | Some(nextLedger, mutation) -> applyAll nextLedger (mutation :: mutations) rest
                    | None -> TypedOwnerTransactionRejected(transactionId, CompilerKernelV2.OperationalReasonIdOps.create "close_key_did_not_match_required_owner_kind", beforeLedger)
            applyAll beforeLedger [] actions

        let executeParentContinuationTailCloseTransaction<'GraphKind> (request:ParentContinuationTailTransactionRequest) : TypedOwnerTransactionResult<'GraphKind> =
            let dominant =
                if System.String.IsNullOrWhiteSpace request.dominantNodeId then None
                else Some({ value = request.dominantNodeId } : ActiveNodeId<'GraphKind>)
            let parentOwner : PhantomOwnerId<'GraphKind,ParentContinuationOwnerKind> = phantomOwnerIdFor ("owner:parent_continuation:" + request.key)
            let parentCell : ParentContinuationCellId<'GraphKind> = { value = if System.String.IsNullOrWhiteSpace request.cellId then "ivar:parent_continuation:" + request.key else request.cellId }
            let parentCloseKey = phantomCloseKeyFor parentOwner ("close:parent_continuation:" + request.key)
            let parentLease : TypedOwnerLease<'GraphKind,ParentContinuationOwnerKind,OwnerOpenPhase> =
                typedOwnerLeaseFor parentOwner None None (max 1L request.pending) (OwnerRequireParentContinuationIvarFill parentCell) "parent_continuation_tail_transaction_open"
            let mutable ledger : RecursiveOwnerLedger<'GraphKind> = OwnerLedgerCons(ParentContinuationOwnerNode(OwnerLeaseOpen parentLease), OwnerLedgerEmpty)
            let mutable actions : TypedOwnerCloseAction<'GraphKind> list = [ CloseParentContinuationWith(parentCloseKey, parentCell, request.fillReceipt) ]

            if request.sidecarLive then
                let sidecarOwner : PhantomOwnerId<'GraphKind,SidecarDrainOwnerKind> = phantomOwnerIdFor ("owner:sidecar_drain:" + request.key)
                let sidecarState =
                    PureSidecarDrainAccumulating(max 0L request.topologyFacts, dominant)
                let sidecarLease : TypedOwnerLease<'GraphKind,SidecarDrainOwnerKind,OwnerOpenPhase> =
                    typedOwnerLeaseFor sidecarOwner None None 1L (OwnerRequireSidecarTopologyCollapse sidecarState) "pure_sidecar_drain_tail_transaction_open"
                ledger <- OwnerLedgerCons(SidecarDrainOwnerNode(OwnerLeaseOpen sidecarLease), ledger)

            if request.dynamicBridgeLive then
                let bridgeOwner : PhantomOwnerId<'GraphKind,DynamicBridgeOwnerKind> = phantomOwnerIdFor ("owner:dynamic_bridge:" + request.key)
                let bridgeCloseKey = phantomCloseKeyFor bridgeOwner ("close:dynamic_bridge:" + request.key)
                let bridgeState =
                    if request.bridgeDeferrals <= 0L then
                        DynamicBridgeTailExhausted(request.key, bridgeCloseKey.value, dominant)
                    else DynamicBridgeTailLeased(request.key, max 0L request.bridgeDeferrals, dominant)
                let bridgeLease : TypedOwnerLease<'GraphKind,DynamicBridgeOwnerKind,OwnerOpenPhase> =
                    typedOwnerLeaseFor bridgeOwner None None (max 1L request.bridgeDeferrals) (OwnerRequireDynamicBridgeQuarantine bridgeState) "dynamic_bridge_tail_transaction_open"
                ledger <- OwnerLedgerCons(DynamicBridgeOwnerNode(OwnerLeaseOpen bridgeLease), ledger)
                match bridgeState with
                | DynamicBridgeTailExhausted _
                | DynamicBridgeTailQuarantined _ -> actions <- QuarantineDynamicBridgeWith(bridgeCloseKey, bridgeState) :: actions
                | DynamicBridgeTailAbsent
                | DynamicBridgeTailLeased _ -> ()

            if request.poisonTailLive then
                let poisonOwner : PhantomOwnerId<'GraphKind,PoisonTailOwnerKind> = phantomOwnerIdFor ("owner:poison_tail:" + request.key)
                let poisonState =
                    PoisonTailOwnerLive(request.key, dominant)
                let poisonLease : TypedOwnerLease<'GraphKind,PoisonTailOwnerKind,OwnerOpenPhase> =
                    typedOwnerLeaseFor poisonOwner None None 1L (OwnerRequirePoisonTailClosure poisonState) "poison_tail_transaction_open"
                ledger <- OwnerLedgerCons(PoisonTailOwnerNode(OwnerLeaseOpen poisonLease), ledger)

            if request.joinPointWaitLive then
                let joinOwner : PhantomOwnerId<'GraphKind,JoinPointWaitOwnerKind> = phantomOwnerIdFor ("owner:join_point_wait:" + request.key)
                let joinPointId = "jp_wait:" + request.key
                let joinLease : TypedOwnerLease<'GraphKind,JoinPointWaitOwnerKind,OwnerOpenPhase> =
                    typedOwnerLeaseFor joinOwner None None 1L (OwnerRequireJoinPointWake joinPointId) "join_point_wait_live"
                ledger <- OwnerLedgerCons(JoinPointWaitOwnerNode(OwnerLeaseOpen joinLease), ledger)

            let transactionId = "owner_tx:parent_continuation_tail:" + request.key
            match executeTypedOwnerTransaction transactionId request.fillReceipt (List.rev actions) ledger with
            | TypedOwnerTransactionCommitted receipt ->
                // DOMAIN MIGRATION : keep the exact before/after receipt even
                // when some owners remain open. TerminalQuorum now consumes the
                // recursive OwnerLedgerQuorum and decides blocked/deadlocked/
                // quarantined centrally; throwing the receipt away here was the
                // old string-era behavior that hid the owner axis that failed to
                // close.
                TypedOwnerTransactionCommitted receipt
            | TypedOwnerTransactionRejected _ as rejected -> rejected

        let private parentContinuationOwnerNodeForLegacy<'Kind> = function
            | ParentContinuationAbsent -> None
            | ParentContinuationOwned(owner, cellId, _, pendingCount, lease) ->
                let ownerId : PhantomOwnerId<'Kind,ParentContinuationOwnerKind> = phantomOwnerIdFor owner.value
                let typed : TypedOwnerLease<'Kind,ParentContinuationOwnerKind,OwnerOpenPhase> =
                    typedOwnerLeaseFor ownerId None (Some lease) pendingCount (OwnerRequireParentContinuationIvarFill cellId) "legacy_parent_continuation_owned"
                Some(ParentContinuationOwnerNode(OwnerLeaseOpen typed))
            | ParentContinuationHandoffReady proof ->
                let ownerId : PhantomOwnerId<'Kind,ParentContinuationOwnerKind> = phantomOwnerIdFor proof.owner.value
                let closeKey = phantomCloseKeyFor ownerId proof.closedBy.value
                let typed : TypedOwnerLease<'Kind,ParentContinuationOwnerKind,OwnerCloseReadyPhase> =
                    typedOwnerLeaseFor ownerId (Some closeKey) None proof.afterPending (OwnerRequireParentContinuationIvarFill proof.cellId) "legacy_parent_continuation_handoff_ready"
                Some(ParentContinuationOwnerNode(OwnerLeaseCloseReady typed))
            | ParentContinuationHandoffClosed proof ->
                let ownerId : PhantomOwnerId<'Kind,ParentContinuationOwnerKind> = phantomOwnerIdFor proof.owner.value
                let closeKey = phantomCloseKeyFor ownerId proof.closedBy.value
                let typed : TypedOwnerLease<'Kind,ParentContinuationOwnerKind,OwnerClosedPhase> =
                    typedOwnerLeaseFor ownerId (Some closeKey) None 0L (OwnerRequireParentContinuationIvarFill proof.cellId) "legacy_parent_continuation_handoff_closed"
                Some(ParentContinuationOwnerNode(OwnerLeaseClosed typed))
            | ParentContinuationExpired(owner, cellId, pendingCount, _, closeKey) ->
                let ownerId : PhantomOwnerId<'Kind,ParentContinuationOwnerKind> = phantomOwnerIdFor owner.value
                let typedCloseKey = phantomCloseKeyFor ownerId closeKey.value
                let typed : TypedOwnerLease<'Kind,ParentContinuationOwnerKind,OwnerCloseReadyPhase> =
                    typedOwnerLeaseFor ownerId (Some typedCloseKey) None pendingCount (OwnerRequireParentContinuationIvarFill cellId) "legacy_parent_continuation_expired"
                Some(ParentContinuationOwnerNode(OwnerLeaseCloseReady typed))
            | ParentContinuationQuarantined plan ->
                let ownerId : PhantomOwnerId<'Kind,ParentContinuationOwnerKind> = phantomOwnerIdFor plan.owner.value
                let typed : TypedOwnerLease<'Kind,ParentContinuationOwnerKind,OwnerQuarantinedPhase> =
                    typedOwnerLeaseFor ownerId None None plan.pendingCount (OwnerRequireParentContinuationIvarFill plan.cellId) "legacy_parent_continuation_quarantined"
                Some(ParentContinuationOwnerNode(OwnerLeaseQuarantined typed))

        let private crossKindOwnerNodeForLegacy<'Kind> = function
            | CrossKindObligationAbsent -> None
            | CrossKindObligationOwned(owner, obligationId, beforeCount, lease) ->
                let ownerId : PhantomOwnerId<'Kind,CrossKindOwnerKind> = phantomOwnerIdFor owner.value
                let typed : TypedOwnerLease<'Kind,CrossKindOwnerKind,OwnerOpenPhase> =
                    typedOwnerLeaseFor ownerId None (Some lease) beforeCount (OwnerRequireCrossKindDrain obligationId) "legacy_cross_kind_owned"
                Some(CrossKindOwnerNode(OwnerLeaseOpen typed))
            | CrossKindObligationReduced attempt when attempt.drained ->
                let ownerId : PhantomOwnerId<'Kind,CrossKindOwnerKind> = phantomOwnerIdFor attempt.owner.value
                let closeKey = phantomCloseKeyFor ownerId attempt.closedBy.value
                let typed : TypedOwnerLease<'Kind,CrossKindOwnerKind,OwnerClosedPhase> =
                    typedOwnerLeaseFor ownerId (Some closeKey) None 0L (OwnerRequireCrossKindDrain attempt.obligationId) "legacy_cross_kind_drained"
                Some(CrossKindOwnerNode(OwnerLeaseClosed typed))
            | CrossKindObligationReduced attempt ->
                let ownerId : PhantomOwnerId<'Kind,CrossKindOwnerKind> = phantomOwnerIdFor attempt.owner.value
                let closeKey = phantomCloseKeyFor ownerId attempt.closedBy.value
                let typed : TypedOwnerLease<'Kind,CrossKindOwnerKind,OwnerCloseReadyPhase> =
                    typedOwnerLeaseFor ownerId (Some closeKey) None attempt.afterCount (OwnerRequireCrossKindDrain attempt.obligationId) "legacy_cross_kind_reduced_not_drained"
                Some(CrossKindOwnerNode(OwnerLeaseCloseReady typed))
            | CrossKindObligationExpired(owner, obligationId, remainingCount, _, closeKey) ->
                let ownerId : PhantomOwnerId<'Kind,CrossKindOwnerKind> = phantomOwnerIdFor owner.value
                let typedCloseKey = phantomCloseKeyFor ownerId closeKey.value
                let typed : TypedOwnerLease<'Kind,CrossKindOwnerKind,OwnerCloseReadyPhase> =
                    typedOwnerLeaseFor ownerId (Some typedCloseKey) None remainingCount (OwnerRequireCrossKindDrain obligationId) "legacy_cross_kind_expired"
                Some(CrossKindOwnerNode(OwnerLeaseCloseReady typed))
            | CrossKindObligationQuarantined plan ->
                let ownerId : PhantomOwnerId<'Kind,CrossKindOwnerKind> = phantomOwnerIdFor plan.owner.value
                let typed : TypedOwnerLease<'Kind,CrossKindOwnerKind,OwnerQuarantinedPhase> =
                    typedOwnerLeaseFor ownerId None None plan.remainingCount (OwnerRequireCrossKindDrain plan.obligationId) "legacy_cross_kind_quarantined"
                Some(CrossKindOwnerNode(OwnerLeaseQuarantined typed))

        let private recursiveOwnerLedgerForLegacy<'Kind>
            (crossKind:CrossKindObligationState<'Kind>)
            (parentContinuation:ParentContinuationObligationState<'Kind>) =
            let withCross =
                match crossKindOwnerNodeForLegacy crossKind with
                | Some node -> OwnerLedgerCons(node, OwnerLedgerEmpty)
                | None -> OwnerLedgerEmpty
            match parentContinuationOwnerNodeForLegacy parentContinuation with
            | Some node -> OwnerLedgerCons(node, withCross)
            | None -> withCross

        let private terminalOwnershipObligationsFor = function
            | LiveGraphFreshState(LiveGraphAuthorityNode(_, _, _, _, _, crossKind, parent, _, _))
            | LiveGraphProgressingState(LiveGraphAuthorityNode(_, _, _, _, _, crossKind, parent, _, _))
            | LiveGraphStaleState(LiveGraphAuthorityNode(_, _, _, _, _, crossKind, parent, _, _))
            | LiveGraphDeadlockedState(LiveGraphAuthorityNode(_, _, _, _, _, crossKind, parent, _, _))
            | LiveGraphQuarantinedState(LiveGraphAuthorityNode(_, _, _, _, _, crossKind, parent, _, _))
            | LiveGraphTerminalEligibleState(LiveGraphAuthorityNode(_, _, _, _, _, crossKind, parent, _, _)) ->
                crossKind, parent

        let private sidecarOwnerNodeForGraph<'Kind>
            (graph:TerminalExecutableGraphState<'Kind>)
            (leaseOpt:LiveGraphConservedCredit<'Kind> option) =
            if not (terminalExecutableGraphSidecarPending graph) then None
            else
                let closureId = terminalExecutableGraphClosureId graph
                let dominant : ActiveNodeId<'Kind> = { value = closureId.value }
                let facts = max 0L (terminalExecutableGraphSameStateRepeat graph)
                let topologyState =
                    if facts >= 50L then PureSidecarDrainForgivenessReady(facts, 50L, Some dominant)
                    else PureSidecarDrainAccumulating(facts, Some dominant)
                let ownerId : PhantomOwnerId<'Kind,SidecarDrainOwnerKind> =
                    phantomOwnerIdFor ("owner:sidecar_drain:" + closureId.value)
                let closeKey = phantomCloseKeyFor ownerId ("close:sidecar_drain:" + closureId.value)
                match topologyState with
                | PureSidecarDrainForgivenessReady _
                | SidecarDrainMaterialSemanticDelta _ ->
                    let typed : TypedOwnerLease<'Kind,SidecarDrainOwnerKind,OwnerQuarantinedPhase> =
                        typedOwnerLeaseFor ownerId (Some closeKey) leaseOpt 0L (OwnerRequireSidecarTopologyCollapse topologyState) "terminal_graph_sidecar_forgiveness_quarantined"
                    Some(SidecarDrainOwnerNode(OwnerLeaseQuarantined typed))
                | PureSidecarDrainAccumulating _ ->
                    let typed : TypedOwnerLease<'Kind,SidecarDrainOwnerKind,OwnerOpenPhase> =
                        typedOwnerLeaseFor ownerId None leaseOpt 1L (OwnerRequireSidecarTopologyCollapse topologyState) "terminal_graph_sidecar_pending" 
                    Some(SidecarDrainOwnerNode(OwnerLeaseOpen typed))

        let private dynamicBridgeOwnerNodeForGraph<'Kind>
            (graph:TerminalExecutableGraphState<'Kind>)
            (leaseOpt:LiveGraphConservedCredit<'Kind> option) =
            let continuationPending = terminalExecutableGraphContinuationPending graph
            let crossKindCount = terminalExecutableGraphCrossKindCount graph
            if not continuationPending || crossKindCount <= 0L then None
            else
                let closureId = terminalExecutableGraphClosureId graph
                let repeat = max 0L (terminalExecutableGraphSameStateRepeat graph)
                let dominant : ActiveNodeId<'Kind> = { value = closureId.value }
                let ownerId : PhantomOwnerId<'Kind,DynamicBridgeOwnerKind> =
                    phantomOwnerIdFor ("owner:dynamic_bridge:" + closureId.value)
                let closeKey = phantomCloseKeyFor ownerId ("close:dynamic_bridge:" + closureId.value)
                if repeat >= 50L then
                    let state = DynamicBridgeTailExhausted(closureId.value, (phantomCloseKeyValue closeKey), Some dominant)
                    let typed : TypedOwnerLease<'Kind,DynamicBridgeOwnerKind,OwnerQuarantinedPhase> =
                        typedOwnerLeaseFor ownerId (Some closeKey) leaseOpt 0L (OwnerRequireDynamicBridgeQuarantine state) "terminal_graph_dynamic_bridge_exhausted_quarantined"
                    Some(DynamicBridgeOwnerNode(OwnerLeaseQuarantined typed))
                else
                    let state = DynamicBridgeTailLeased(closureId.value, crossKindCount, Some dominant)
                    let typed : TypedOwnerLease<'Kind,DynamicBridgeOwnerKind,OwnerOpenPhase> =
                        typedOwnerLeaseFor ownerId None leaseOpt crossKindCount (OwnerRequireDynamicBridgeQuarantine state) "terminal_graph_dynamic_bridge_live"
                    Some(DynamicBridgeOwnerNode(OwnerLeaseOpen typed))

        let private poisonTailOwnerNodeForGraph<'Kind>
            (graph:TerminalExecutableGraphState<'Kind>)
            (leaseOpt:LiveGraphConservedCredit<'Kind> option) =
            let continuationPending = terminalExecutableGraphContinuationPending graph
            let repeat = max 0L (terminalExecutableGraphSameStateRepeat graph)
            let isStalled =
                match graph with
                | TerminalGraphStalledState _ -> true
                | _ -> false
            if not continuationPending || not isStalled || repeat <= 0L then None
            else
                let closureId = terminalExecutableGraphClosureId graph
                let dominant : ActiveNodeId<'Kind> = { value = closureId.value }
                let ownerId : PhantomOwnerId<'Kind,PoisonTailOwnerKind> =
                    phantomOwnerIdFor ("owner:poison_tail:" + closureId.value)
                let closeKey = phantomCloseKeyFor ownerId ("close:poison_tail:" + closureId.value)
                if repeat >= 64L then
                    let state = PoisonTailOwnerClosed(closureId.value, (phantomCloseKeyValue closeKey))
                    let typed : TypedOwnerLease<'Kind,PoisonTailOwnerKind,OwnerClosedPhase> =
                        typedOwnerLeaseFor ownerId (Some closeKey) leaseOpt 0L (OwnerRequirePoisonTailClosure state) "terminal_graph_poison_tail_closed_by_repeat_cap"
                    Some(PoisonTailOwnerNode(OwnerLeaseClosed typed))
                else
                    let state = PoisonTailOwnerLive(closureId.value, Some dominant)
                    let typed : TypedOwnerLease<'Kind,PoisonTailOwnerKind,OwnerOpenPhase> =
                        typedOwnerLeaseFor ownerId None leaseOpt 1L (OwnerRequirePoisonTailClosure state) "terminal_graph_poison_tail_live"
                    Some(PoisonTailOwnerNode(OwnerLeaseOpen typed))

        let private joinPointWaitOwnerNodeForGraph<'Kind>
            (graph:TerminalExecutableGraphState<'Kind>)
            (leaseOpt:LiveGraphConservedCredit<'Kind> option) =
            let continuationPending = terminalExecutableGraphContinuationPending graph
            let queue = terminalExecutableGraphQueueCount graph
            let active = terminalExecutableGraphActiveCount graph
            let repeat = max 0L (terminalExecutableGraphSameStateRepeat graph)
            let isStalled =
                match graph with
                | TerminalGraphStalledState _ -> true
                | _ -> false
            if not continuationPending || not isStalled || active <= 0L || queue > 0L then None
            else
                let closureId = terminalExecutableGraphClosureId graph
                let ownerId : PhantomOwnerId<'Kind,JoinPointWaitOwnerKind> =
                    phantomOwnerIdFor ("owner:join_point_wait:" + closureId.value)
                let closeKey = phantomCloseKeyFor ownerId ("close:join_point_wait:" + closureId.value)
                let joinPointId = "jp_wait:" + closureId.value
                if repeat >= 64L then
                    let typed : TypedOwnerLease<'Kind,JoinPointWaitOwnerKind,OwnerQuarantinedPhase> =
                        typedOwnerLeaseFor ownerId (Some closeKey) leaseOpt 0L (OwnerRequireJoinPointWake joinPointId) "terminal_graph_join_point_wait_quarantined_by_repeat_cap"
                    Some(JoinPointWaitOwnerNode(OwnerLeaseQuarantined typed))
                else
                    let typed : TypedOwnerLease<'Kind,JoinPointWaitOwnerKind,OwnerOpenPhase> =
                        typedOwnerLeaseFor ownerId None leaseOpt active (OwnerRequireJoinPointWake joinPointId) "terminal_graph_join_point_wait_live"
                    Some(JoinPointWaitOwnerNode(OwnerLeaseOpen typed))

        let private proceduralResidualOwnerNodeForGraph<'Kind>
            (graph:TerminalExecutableGraphState<'Kind>)
            (leaseOpt:LiveGraphConservedCredit<'Kind> option) =
            let pending = max 0L (terminalExecutableGraphPendingCount graph)
            let queue = max 0L (terminalExecutableGraphQueueCount graph)
            let active = max 0L (terminalExecutableGraphActiveCount graph)
            let repeat = max 0L (terminalExecutableGraphSameStateRepeat graph)
            let cross = max 0L (terminalExecutableGraphCrossKindCount graph)
            let continuationPending = terminalExecutableGraphContinuationPending graph
            let procedural = queue + active
            if pending > 0L || procedural <= 0L || cross > 0L || continuationPending then None
            else
                let closureId = terminalExecutableGraphClosureId graph
                let tailId = "procedural-residual:" + closureId.value
                let ownerId : PhantomOwnerId<'Kind,ProceduralResidualOwnerKind> =
                    phantomOwnerIdFor ("owner:" + tailId)
                let closeKey = phantomCloseKeyFor ownerId ("close:" + tailId)
                if repeat >= 32L then
                    let state = ProceduralResidualOwnerCloseReady(tailId, (phantomCloseKeyValue closeKey), repeat, 0L)
                    let typed : TypedOwnerLease<'Kind,ProceduralResidualOwnerKind,OwnerCloseReadyPhase> =
                        typedOwnerLeaseFor ownerId (Some closeKey) leaseOpt 0L (OwnerRequireProceduralResidualDrain state) "live_graph_residual_close_ready_exact_once"
                    Some(ProceduralResidualOwnerNode(OwnerLeaseCloseReady typed))
                else
                    let state = ProceduralResidualOwnerLive(tailId, repeat, pending, queue, active, procedural)
                    let typed : TypedOwnerLease<'Kind,ProceduralResidualOwnerKind,OwnerOpenPhase> =
                        typedOwnerLeaseFor ownerId None leaseOpt procedural (OwnerRequireProceduralResidualDrain state) "live_graph_residual_owned_not_observed"
                    Some(ProceduralResidualOwnerNode(OwnerLeaseOpen typed))

        let private recursiveOwnerLedgerForGraph
            (graph:TerminalExecutableGraphState<'Kind>)
            (leaseOpt:LiveGraphConservedCredit<'Kind> option)
            (crossKind:CrossKindObligationState<'Kind>)
            (parentContinuation:ParentContinuationObligationState<'Kind>) =
            let legacy = recursiveOwnerLedgerForLegacy crossKind parentContinuation
            let withSidecar =
                match sidecarOwnerNodeForGraph graph leaseOpt with
                | Some node -> OwnerLedgerCons(node, legacy)
                | None -> legacy
            let withDynamicBridge =
                match dynamicBridgeOwnerNodeForGraph graph leaseOpt with
                | Some node -> OwnerLedgerCons(node, withSidecar)
                | None -> withSidecar
            let withPoisonTail =
                match poisonTailOwnerNodeForGraph graph leaseOpt with
                | Some node -> OwnerLedgerCons(node, withDynamicBridge)
                | None -> withDynamicBridge
            let withJoinPoint =
                match joinPointWaitOwnerNodeForGraph graph leaseOpt with
                | Some node -> OwnerLedgerCons(node, withPoisonTail)
                | None -> withPoisonTail
            match proceduralResidualOwnerNodeForGraph graph leaseOpt with
            | Some node -> OwnerLedgerCons(node, withJoinPoint)
            | None -> withJoinPoint

        let private recursiveOwnerLedgerFor = function
            | LiveGraphFreshState(LiveGraphAuthorityNode(_, _, _, _, _, _, _, owners, _))
            | LiveGraphProgressingState(LiveGraphAuthorityNode(_, _, _, _, _, _, _, owners, _))
            | LiveGraphStaleState(LiveGraphAuthorityNode(_, _, _, _, _, _, _, owners, _))
            | LiveGraphDeadlockedState(LiveGraphAuthorityNode(_, _, _, _, _, _, _, owners, _))
            | LiveGraphQuarantinedState(LiveGraphAuthorityNode(_, _, _, _, _, _, _, owners, _))
            | LiveGraphTerminalEligibleState(LiveGraphAuthorityNode(_, _, _, _, _, _, _, owners, _)) -> owners

        let private typedTerminalOwnerClosureVerdictFor authority =
            let ledger = recursiveOwnerLedgerFor authority
            let quorum = ownerLedgerQuorumForLedger "terminal_owner_closure" "live_graph_authority_owner_scan" 0L false None [] ledger
            match terminalQuorumDecisionForOwnerLedgerQuorum quorum with
            | TerminalQuorumEligible q -> TypedTerminalOwnersAllClosed q.ledger
            | TerminalQuorumQuarantinedByOwnerLedger q when q.openOwnerCount = 0L -> TypedTerminalOwnersAllClosed q.ledger
            | TerminalQuorumBlockedByOpenOwners q -> TypedTerminalOwnersStillOpen(q.ledger, q.openAxes)
            | TerminalQuorumDeadlockedByOwnerLedger q -> TypedTerminalOwnersNeedDeadlockResolution(q.ledger, q.openAxes)
            | TerminalQuorumQuarantinedByOwnerLedger q -> TypedTerminalOwnersNeedDeadlockResolution(q.ledger, q.openAxes)

        let private phaseIndexedLiveGraphFor authority =
            match authority with
            | LiveGraphFreshState typed ->
                PhaseIndexedFresh { authority = typed; phase = LiveGraphPhaseFresh }
            | LiveGraphProgressingState typed ->
                PhaseIndexedProgressing { authority = typed; phase = LiveGraphPhaseProgressing }
            | LiveGraphStaleState typed ->
                PhaseIndexedStale { authority = typed; phase = LiveGraphPhaseStale }
            | LiveGraphDeadlockedState typed ->
                PhaseIndexedDeadlocked { authority = typed; phase = LiveGraphPhaseDeadlocked }
            | LiveGraphQuarantinedState typed ->
                PhaseIndexedQuarantined { authority = typed; phase = LiveGraphPhaseQuarantined }
            | LiveGraphTerminalEligibleState typed ->
                PhaseIndexedTerminalEligible { authority = typed; phase = LiveGraphPhaseTerminalEligible }

        // Compatibility verdict for residual HUD consumers only. The payload is
        // already the recursive typed ledger; terminal authority no longer rebuilds
        // a two-field boolean ownership record here.
        let private terminalOwnerClosureVerdictFor authority =
            match typedTerminalOwnerClosureVerdictFor authority with
            | TypedTerminalOwnersAllClosed ledger ->
                TerminalOwnersAllClosed ledger
            | TypedTerminalOwnersStillOpen(ledger, openAxes) ->
                TerminalOwnersStillOpen(ledger, openAxes)
            | TypedTerminalOwnersNeedDeadlockResolution(ledger, openAxes) ->
                TerminalOwnersNeedDeadlockResolution(ledger, openAxes)

        let liveGraphAuthorityFor<'Kind>
            (graph:TerminalExecutableGraphState<'Kind>)
            : LiveGraphAuthorityState<'Kind> =
            let graphHash = terminalExecutableGraphHashValue graph
            let epoch = terminalExecutableGraphEpochValue graph
            let repeat = terminalExecutableGraphSameStateRepeat graph
            match graph with
            | TerminalGraphProgressingState _ ->
                let authority : LiveGraphAuthority<'Kind,LiveGraphProgressing> =
                    let workDag = workDagAuthorityForTerminalGraph graph
                    let scheduler = schedulerCausalAuthorityForTerminalGraph graph workDag None CrossKindObligationAbsent ParentContinuationAbsent
                    let owners = recursiveOwnerLedgerForGraph graph None CrossKindObligationAbsent ParentContinuationAbsent
                    let history = LiveGraphAuthorityGenesis(LiveGraphPhaseProgressing, owners, "material_progress_genesis")
                    LiveGraphAuthorityNode(graph, MaterialProgress(epoch, graphHash), workDag, scheduler, None, CrossKindObligationAbsent, ParentContinuationAbsent, owners, history)
                LiveGraphProgressingState authority
            | TerminalGraphStalledState _ when repeat <= 0L ->
                let lease = liveGraphConservedCreditFor graph RequireMaterialDeltaBeforeCreditRelease
                let obligation = liveGraphCrossKindObligationFor graph lease
                let authority : LiveGraphAuthority<'Kind,LiveGraphFresh> =
                    let parentContinuation = liveGraphParentContinuationObligationFor graph lease
                    let workDag = workDagAuthorityForTerminalGraph graph
                    let scheduler = schedulerCausalAuthorityForTerminalGraph graph workDag (Some lease) obligation parentContinuation
                    let owners = recursiveOwnerLedgerForGraph graph (Some lease) obligation parentContinuation
                    let history = LiveGraphAuthorityGenesis(LiveGraphPhaseFresh, owners, "fresh_stalled_genesis")
                    LiveGraphAuthorityNode(graph, OccupiedNoMaterialProgress(graphHash, repeat), workDag, scheduler, Some lease, obligation, parentContinuation, owners, history)
                LiveGraphFreshState authority
            | TerminalGraphStalledState _ ->
                let resolution =
                    if terminalExecutableGraphCrossKindCount graph > 0L then
                        RequireCrossKindDrainBeforeCreditRelease("cko:" + graphHash.value)
                    elif terminalExecutableGraphContinuationPending graph then
                        RequireParentContinuationHandoffBeforeCreditRelease("pco:" + graphHash.value)
                    else
                        RequireMaterialDeltaBeforeCreditRelease
                let lease = liveGraphConservedCreditFor graph resolution
                let obligation = liveGraphCrossKindObligationFor graph lease
                let authority : LiveGraphAuthority<'Kind,LiveGraphStale> =
                    let parentContinuation = liveGraphParentContinuationObligationFor graph lease
                    let workDag = workDagAuthorityForTerminalGraph graph
                    let scheduler = schedulerCausalAuthorityForTerminalGraph graph workDag (Some lease) obligation parentContinuation
                    let owners = recursiveOwnerLedgerForGraph graph (Some lease) obligation parentContinuation
                    let history = LiveGraphAuthorityGenesis(LiveGraphPhaseStale, owners, "conserved_credit_stalled_genesis")
                    LiveGraphAuthorityNode(graph, OccupiedNoMaterialProgress(graphHash, repeat), workDag, scheduler, Some lease, obligation, parentContinuation, owners, history)
                LiveGraphStaleState authority
            | TerminalGraphExhaustedState _ ->
                let authority : LiveGraphAuthority<'Kind,LiveGraphTerminalEligible> =
                    let workDag = workDagAuthorityForTerminalGraph graph
                    let scheduler = schedulerCausalAuthorityForTerminalGraph graph workDag None CrossKindObligationAbsent ParentContinuationAbsent
                    let owners = recursiveOwnerLedgerForGraph graph None CrossKindObligationAbsent ParentContinuationAbsent
                    let history = LiveGraphAuthorityGenesis(LiveGraphPhaseTerminalEligible, owners, "graph_exhausted_genesis")
                    LiveGraphAuthorityNode(graph, GraphExhausted(epoch, graphHash), workDag, scheduler, None, CrossKindObligationAbsent, ParentContinuationAbsent, owners, history)
                LiveGraphTerminalEligibleState authority

        let private liveGraphAuthorityStateEnvelope = function
            | LiveGraphFreshState(LiveGraphAuthorityNode(_, _, _, _, _, _, _, owners, history)) -> LiveGraphPhaseFresh, owners, history
            | LiveGraphProgressingState(LiveGraphAuthorityNode(_, _, _, _, _, _, _, owners, history)) -> LiveGraphPhaseProgressing, owners, history
            | LiveGraphStaleState(LiveGraphAuthorityNode(_, _, _, _, _, _, _, owners, history)) -> LiveGraphPhaseStale, owners, history
            | LiveGraphDeadlockedState(LiveGraphAuthorityNode(_, _, _, _, _, _, _, owners, history)) -> LiveGraphPhaseDeadlocked, owners, history
            | LiveGraphQuarantinedState(LiveGraphAuthorityNode(_, _, _, _, _, _, _, owners, history)) -> LiveGraphPhaseQuarantined, owners, history
            | LiveGraphTerminalEligibleState(LiveGraphAuthorityNode(_, _, _, _, _, _, _, owners, history)) -> LiveGraphPhaseTerminalEligible, owners, history

        let private liveGraphAuthorityTransitionReasonFor fromPhase toPhase materialDelta beforeOwners afterOwners =
            if toPhase = LiveGraphPhaseTerminalEligible then LiveGraphTransitionTerminalExhausted
            elif toPhase = LiveGraphPhaseDeadlocked then LiveGraphTransitionLeaseExpired
            elif toPhase = LiveGraphPhaseQuarantined then LiveGraphTransitionQuarantinePromoted
            elif recursiveOwnerLedgerOpenCount beforeOwners <> recursiveOwnerLedgerOpenCount afterOwners then LiveGraphTransitionOwnerLedgerChanged
            elif materialDelta > 0L then LiveGraphTransitionMaterialAdvanced
            elif fromPhase <> toPhase then LiveGraphTransitionTopologyOnly
            else LiveGraphTransitionTopologyOnly

        let private liveGraphPhaseStableText = function
            | LiveGraphPhaseFresh -> "fresh"
            | LiveGraphPhaseProgressing -> "progressing"
            | LiveGraphPhaseStale -> "stale"
            | LiveGraphPhaseDeadlocked -> "deadlocked"
            | LiveGraphPhaseQuarantined -> "quarantined"
            | LiveGraphPhaseTerminalEligible -> "terminal_eligible"

        let private liveGraphAuthorityHistoryWindowCap = 32

        let private liveGraphAuthorityHistoryAppend<'Kind>
            (receipt:LiveGraphAuthorityTransitionReceipt<'Kind>)
            (previous:LiveGraphAuthorityHistory<'Kind>) =
            let rec depth = function
                | LiveGraphAuthorityGenesis _ -> 1
                | LiveGraphAuthorityCheckpoint checkpoint -> checkpoint.transitionCount
                | LiveGraphAuthorityTransition(_, tail) -> 1 + depth tail
            if depth previous >= liveGraphAuthorityHistoryWindowCap then
                let checkpoint =
                    { checkpointId = "live-graph-checkpoint:" + receipt.transitionId
                      phase = receipt.fromPhase
                      owners = receipt.ownerLedgerBefore
                      transitionCount = depth previous
                      digest =
                          CompilerIdentityKernel.ContentDigest.ofText
                              "live-graph-authority-checkpoint"
                              (receipt.transitionId
                               + "|" + liveGraphPhaseStableText receipt.fromPhase
                               + "|" + liveGraphPhaseStableText receipt.toPhase
                               + "|" + string receipt.materialDelta)
                          |> CompilerIdentityKernel.ContentDigest.text }
                LiveGraphAuthorityTransition(receipt, LiveGraphAuthorityCheckpoint checkpoint)
            else
                LiveGraphAuthorityTransition(receipt, previous)

        let liveGraphAuthorityAdvance<'Kind>
            (previous:LiveGraphAuthorityState<'Kind>)
            (graph:TerminalExecutableGraphState<'Kind>)
            (repeatCap:int64)
            : LiveGraphAuthorityState<'Kind> =
            let fromPhase, beforeOwners, previousHistory = liveGraphAuthorityStateEnvelope previous
            let candidate = liveGraphAuthorityFor graph
            let receiptFor toPhase workDag afterOwners =
                let graphHash = terminalExecutableGraphHashValue graph
                let materialDelta = max 0L workDag.materialDeltaCost
                { transitionId = "live-graph-transition:" + graphHash.value + ":" + liveGraphPhaseStableText fromPhase + "->" + liveGraphPhaseStableText toPhase
                  fromPhase = fromPhase
                  toPhase = toPhase
                  reason = liveGraphAuthorityTransitionReasonFor fromPhase toPhase materialDelta beforeOwners afterOwners
                  ownerLedgerBefore = beforeOwners
                  ownerLedgerAfter = afterOwners
                  ownerMutations = []
                  materialDelta = materialDelta
                  evidence = "authority_owns_recursive_owner_ledger_and_transition_history" }
            match candidate with
            | LiveGraphFreshState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, owners, _)) ->
                let history = liveGraphAuthorityHistoryAppend (receiptFor LiveGraphPhaseFresh w owners) previousHistory
                LiveGraphFreshState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, owners, history))
            | LiveGraphProgressingState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, owners, _)) ->
                let history = liveGraphAuthorityHistoryAppend (receiptFor LiveGraphPhaseProgressing w owners) previousHistory
                LiveGraphProgressingState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, owners, history))
            | LiveGraphStaleState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, owners, _)) ->
                let history = liveGraphAuthorityHistoryAppend (receiptFor LiveGraphPhaseStale w owners) previousHistory
                LiveGraphStaleState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, owners, history))
            | LiveGraphDeadlockedState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, owners, _)) ->
                let history = liveGraphAuthorityHistoryAppend (receiptFor LiveGraphPhaseDeadlocked w owners) previousHistory
                LiveGraphDeadlockedState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, owners, history))
            | LiveGraphQuarantinedState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, owners, _)) ->
                let history = liveGraphAuthorityHistoryAppend (receiptFor LiveGraphPhaseQuarantined w owners) previousHistory
                LiveGraphQuarantinedState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, owners, history))
            | LiveGraphTerminalEligibleState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, owners, _)) ->
                let history = liveGraphAuthorityHistoryAppend (receiptFor LiveGraphPhaseTerminalEligible w owners) previousHistory
                LiveGraphTerminalEligibleState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, owners, history))

        let liveGraphAuthorityApplyOwnerTransaction<'Kind>
            (authority:LiveGraphAuthorityState<'Kind>)
            (ownerReceipt:TypedOwnerTransactionReceipt<'Kind>)
            : LiveGraphOwnerTransactionApplyResult<'Kind> =
            let fromPhase, currentOwners, previousHistory = liveGraphAuthorityStateEnvelope authority
            let currentOpen = recursiveOwnerLedgerOpenCount currentOwners
            if currentOpen <> ownerReceipt.openBefore then
                LiveGraphOwnerTransactionRejectedMismatch(
                    authority,
                    ownerReceipt,
                    CompilerKernelV2.OperationalReasonIdOps.create (
                        sprintf "owner_ledger_open_count_mismatch|authority=%d|receipt=%d" currentOpen ownerReceipt.openBefore))
            else
                let transitionReceipt toPhase =
                    { transitionId = "live-graph-owner-transaction:" + ownerReceipt.transactionId
                      fromPhase = fromPhase
                      toPhase = toPhase
                      reason = LiveGraphTransitionOwnerLedgerChanged
                      ownerLedgerBefore = currentOwners
                      ownerLedgerAfter = ownerReceipt.afterLedger
                      ownerMutations = ownerReceipt.mutations
                      materialDelta = 0L
                      evidence = ownerReceipt.evidence }
                let transitionHistory toPhase =
                    liveGraphAuthorityHistoryAppend (transitionReceipt toPhase) previousHistory
                let tryPromote graph workDag =
                    match graph with
                    | TerminalGraphExhaustedState _ when ownerReceipt.openAfter = 0L ->
                        let graphHash = terminalExecutableGraphHashValue graph
                        let epoch = terminalExecutableGraphEpochValue graph
                        let scheduler = schedulerCausalAuthorityForTerminalGraph graph workDag None CrossKindObligationAbsent ParentContinuationAbsent
                        let promoted : LiveGraphAuthority<'Kind,LiveGraphTerminalEligible> =
                            LiveGraphAuthorityNode(
                                graph,
                                GraphExhausted(epoch, graphHash),
                                workDag,
                                scheduler,
                                None,
                                CrossKindObligationAbsent,
                                ParentContinuationAbsent,
                                ownerReceipt.afterLedger,
                                transitionHistory LiveGraphPhaseTerminalEligible)
                        Some promoted
                    | _ -> None
                match authority with
                | LiveGraphFreshState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, _, _)) ->
                    match tryPromote g w with
                    | Some promoted -> LiveGraphOwnerTransactionPromotedTerminalEligible(promoted, ownerReceipt)
                    | None ->
                        let next = LiveGraphFreshState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, ownerReceipt.afterLedger, transitionHistory LiveGraphPhaseFresh))
                        LiveGraphOwnerTransactionApplied(next, ownerReceipt)
                | LiveGraphProgressingState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, _, _)) ->
                    match tryPromote g w with
                    | Some promoted -> LiveGraphOwnerTransactionPromotedTerminalEligible(promoted, ownerReceipt)
                    | None ->
                        let next = LiveGraphProgressingState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, ownerReceipt.afterLedger, transitionHistory LiveGraphPhaseProgressing))
                        LiveGraphOwnerTransactionApplied(next, ownerReceipt)
                | LiveGraphStaleState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, _, _)) ->
                    match tryPromote g w with
                    | Some promoted -> LiveGraphOwnerTransactionPromotedTerminalEligible(promoted, ownerReceipt)
                    | None ->
                        let next = LiveGraphStaleState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, ownerReceipt.afterLedger, transitionHistory LiveGraphPhaseStale))
                        LiveGraphOwnerTransactionApplied(next, ownerReceipt)
                | LiveGraphDeadlockedState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, _, _)) ->
                    match tryPromote g w with
                    | Some promoted -> LiveGraphOwnerTransactionPromotedTerminalEligible(promoted, ownerReceipt)
                    | None ->
                        let next = LiveGraphDeadlockedState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, ownerReceipt.afterLedger, transitionHistory LiveGraphPhaseDeadlocked))
                        LiveGraphOwnerTransactionApplied(next, ownerReceipt)
                | LiveGraphQuarantinedState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, _, _)) ->
                    match tryPromote g w with
                    | Some promoted -> LiveGraphOwnerTransactionPromotedTerminalEligible(promoted, ownerReceipt)
                    | None ->
                        let next = LiveGraphQuarantinedState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, ownerReceipt.afterLedger, transitionHistory LiveGraphPhaseQuarantined))
                        LiveGraphOwnerTransactionApplied(next, ownerReceipt)
                | LiveGraphTerminalEligibleState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, _, _)) ->
                    let next = LiveGraphTerminalEligibleState(LiveGraphAuthorityNode(g, p, w, s, l, c, pc, ownerReceipt.afterLedger, transitionHistory LiveGraphPhaseTerminalEligible))
                    LiveGraphOwnerTransactionApplied(next, ownerReceipt)

        let rec private liveGraphAuthorityHistoryDepth = function
            | LiveGraphAuthorityGenesis _ -> 1
            | LiveGraphAuthorityCheckpoint checkpoint -> checkpoint.transitionCount
            | LiveGraphAuthorityTransition(_, previous) -> 1 + liveGraphAuthorityHistoryDepth previous

        let private liveGraphAuthorityHistoryHeadText = function
            | LiveGraphAuthorityGenesis(phase, _, evidence) -> "genesis:" + liveGraphPhaseStableText phase + ":" + evidence
            | LiveGraphAuthorityCheckpoint checkpoint -> "checkpoint:" + checkpoint.checkpointId + ":" + checkpoint.digest
            | LiveGraphAuthorityTransition(receipt, _) -> receipt.transitionId + ":" + liveGraphPhaseStableText receipt.fromPhase + "->" + liveGraphPhaseStableText receipt.toPhase

        let liveGraphAuthorityStateText = function
            | LiveGraphFreshState(LiveGraphAuthorityNode(graph, proof, workDag, scheduler, lease, obligation, parentContinuation, owners, history)) ->
                "LiveGraphAuthority(Fresh|graph=" + terminalExecutableGraphStateText graph + "|proof=" + liveGraphProgressProofText proof + "|work_dag=" + workDagAuthorityText workDag + "|scheduler=" + schedulerCausalAuthorityText scheduler + "|lease=" + (lease |> Option.map liveGraphConservedCreditText |> Option.defaultValue "none") + "|cross=" + crossKindObligationStateText obligation + "|parent=" + parentContinuationObligationStateText parentContinuation + "|owners=" + recursiveOwnerLedgerText owners + "|history_depth=" + string (liveGraphAuthorityHistoryDepth history) + "|history_head=" + liveGraphAuthorityHistoryHeadText history + ")"
            | LiveGraphProgressingState(LiveGraphAuthorityNode(graph, proof, workDag, scheduler, lease, obligation, parentContinuation, owners, history)) ->
                "LiveGraphAuthority(Progressing|graph=" + terminalExecutableGraphStateText graph + "|proof=" + liveGraphProgressProofText proof + "|work_dag=" + workDagAuthorityText workDag + "|scheduler=" + schedulerCausalAuthorityText scheduler + "|lease=" + (lease |> Option.map liveGraphConservedCreditText |> Option.defaultValue "none") + "|cross=" + crossKindObligationStateText obligation + "|parent=" + parentContinuationObligationStateText parentContinuation + "|owners=" + recursiveOwnerLedgerText owners + "|history_depth=" + string (liveGraphAuthorityHistoryDepth history) + "|history_head=" + liveGraphAuthorityHistoryHeadText history + ")"
            | LiveGraphStaleState(LiveGraphAuthorityNode(graph, proof, workDag, scheduler, lease, obligation, parentContinuation, owners, history)) ->
                "LiveGraphAuthority(Stale|graph=" + terminalExecutableGraphStateText graph + "|proof=" + liveGraphProgressProofText proof + "|work_dag=" + workDagAuthorityText workDag + "|scheduler=" + schedulerCausalAuthorityText scheduler + "|lease=" + (lease |> Option.map liveGraphConservedCreditText |> Option.defaultValue "none") + "|cross=" + crossKindObligationStateText obligation + "|parent=" + parentContinuationObligationStateText parentContinuation + "|owners=" + recursiveOwnerLedgerText owners + "|history_depth=" + string (liveGraphAuthorityHistoryDepth history) + "|history_head=" + liveGraphAuthorityHistoryHeadText history + ")"
            | LiveGraphDeadlockedState(LiveGraphAuthorityNode(graph, proof, workDag, scheduler, lease, obligation, parentContinuation, owners, history)) ->
                "LiveGraphAuthority(Deadlocked|graph=" + terminalExecutableGraphStateText graph + "|proof=" + liveGraphProgressProofText proof + "|work_dag=" + workDagAuthorityText workDag + "|scheduler=" + schedulerCausalAuthorityText scheduler + "|lease=" + (lease |> Option.map liveGraphConservedCreditText |> Option.defaultValue "none") + "|cross=" + crossKindObligationStateText obligation + "|parent=" + parentContinuationObligationStateText parentContinuation + "|owners=" + recursiveOwnerLedgerText owners + "|history_depth=" + string (liveGraphAuthorityHistoryDepth history) + "|history_head=" + liveGraphAuthorityHistoryHeadText history + ")"
            | LiveGraphQuarantinedState(LiveGraphAuthorityNode(graph, proof, workDag, scheduler, lease, obligation, parentContinuation, owners, history)) ->
                "LiveGraphAuthority(Quarantined|graph=" + terminalExecutableGraphStateText graph + "|proof=" + liveGraphProgressProofText proof + "|work_dag=" + workDagAuthorityText workDag + "|scheduler=" + schedulerCausalAuthorityText scheduler + "|lease=" + (lease |> Option.map liveGraphConservedCreditText |> Option.defaultValue "none") + "|cross=" + crossKindObligationStateText obligation + "|parent=" + parentContinuationObligationStateText parentContinuation + "|owners=" + recursiveOwnerLedgerText owners + "|history_depth=" + string (liveGraphAuthorityHistoryDepth history) + "|history_head=" + liveGraphAuthorityHistoryHeadText history + ")"
            | LiveGraphTerminalEligibleState(LiveGraphAuthorityNode(graph, proof, workDag, scheduler, lease, obligation, parentContinuation, owners, history)) ->
                "LiveGraphAuthority(TerminalEligible|graph=" + terminalExecutableGraphStateText graph + "|proof=" + liveGraphProgressProofText proof + "|work_dag=" + workDagAuthorityText workDag + "|scheduler=" + schedulerCausalAuthorityText scheduler + "|lease=" + (lease |> Option.map liveGraphConservedCreditText |> Option.defaultValue "none") + "|cross=" + crossKindObligationStateText obligation + "|parent=" + parentContinuationObligationStateText parentContinuation + "|owners=" + recursiveOwnerLedgerText owners + "|history_depth=" + string (liveGraphAuthorityHistoryDepth history) + "|history_head=" + liveGraphAuthorityHistoryHeadText history + ")"

        let private liveGraphPhaseIdText = function
            | LiveGraphPhaseFresh -> "Fresh"
            | LiveGraphPhaseProgressing -> "Progressing"
            | LiveGraphPhaseStale -> "Stale"
            | LiveGraphPhaseDeadlocked -> "Deadlocked"
            | LiveGraphPhaseQuarantined -> "Quarantined"
            | LiveGraphPhaseTerminalEligible -> "TerminalEligible"

        let private phaseIndexedLiveGraphStatePhaseText = function
            | PhaseIndexedFresh graph -> liveGraphPhaseIdText graph.phase
            | PhaseIndexedProgressing graph -> liveGraphPhaseIdText graph.phase
            | PhaseIndexedStale graph -> liveGraphPhaseIdText graph.phase
            | PhaseIndexedDeadlocked graph -> liveGraphPhaseIdText graph.phase
            | PhaseIndexedQuarantined graph -> liveGraphPhaseIdText graph.phase
            | PhaseIndexedTerminalEligible graph -> liveGraphPhaseIdText graph.phase

        let private phaseIndexedLiveGraphAuthorityOwners (graph:PhaseIndexedLiveGraph<'Kind,'Phase>) =
            match graph.authority with
            | LiveGraphAuthorityNode(_, _, _, _, _, _, _, owners, _) -> owners

        let private phaseIndexedLiveGraphStateOwnerLedgerText = function
            | PhaseIndexedFresh graph -> recursiveOwnerLedgerText (phaseIndexedLiveGraphAuthorityOwners graph)
            | PhaseIndexedProgressing graph -> recursiveOwnerLedgerText (phaseIndexedLiveGraphAuthorityOwners graph)
            | PhaseIndexedStale graph -> recursiveOwnerLedgerText (phaseIndexedLiveGraphAuthorityOwners graph)
            | PhaseIndexedDeadlocked graph -> recursiveOwnerLedgerText (phaseIndexedLiveGraphAuthorityOwners graph)
            | PhaseIndexedQuarantined graph -> recursiveOwnerLedgerText (phaseIndexedLiveGraphAuthorityOwners graph)
            | PhaseIndexedTerminalEligible graph -> recursiveOwnerLedgerText (phaseIndexedLiveGraphAuthorityOwners graph)

        let private phaseIndexedLiveGraphStateOpenOwnerCount = function
            | PhaseIndexedFresh graph -> recursiveOwnerLedgerOpenCount (phaseIndexedLiveGraphAuthorityOwners graph)
            | PhaseIndexedProgressing graph -> recursiveOwnerLedgerOpenCount (phaseIndexedLiveGraphAuthorityOwners graph)
            | PhaseIndexedStale graph -> recursiveOwnerLedgerOpenCount (phaseIndexedLiveGraphAuthorityOwners graph)
            | PhaseIndexedDeadlocked graph -> recursiveOwnerLedgerOpenCount (phaseIndexedLiveGraphAuthorityOwners graph)
            | PhaseIndexedQuarantined graph -> recursiveOwnerLedgerOpenCount (phaseIndexedLiveGraphAuthorityOwners graph)
            | PhaseIndexedTerminalEligible graph -> recursiveOwnerLedgerOpenCount (phaseIndexedLiveGraphAuthorityOwners graph)

        let private phaseIndexedLiveGraphAuthorityGraph (graph:PhaseIndexedLiveGraph<'Kind,'Phase>) =
            match graph.authority with
            | LiveGraphAuthorityNode(graphState, _, _, _, _, _, _, _, _) -> graphState

        let private phaseIndexedLiveGraphAuthorityWorkDag (graph:PhaseIndexedLiveGraph<'Kind,'Phase>) =
            match graph.authority with
            | LiveGraphAuthorityNode(_, _, workDag, _, _, _, _, _, _) -> workDag

        let private liveGraphAuthorityStateWorkDag = function
            | LiveGraphFreshState(LiveGraphAuthorityNode(_, _, workDag, _, _, _, _, _, _))
            | LiveGraphProgressingState(LiveGraphAuthorityNode(_, _, workDag, _, _, _, _, _, _))
            | LiveGraphStaleState(LiveGraphAuthorityNode(_, _, workDag, _, _, _, _, _, _))
            | LiveGraphDeadlockedState(LiveGraphAuthorityNode(_, _, workDag, _, _, _, _, _, _))
            | LiveGraphQuarantinedState(LiveGraphAuthorityNode(_, _, workDag, _, _, _, _, _, _))
            | LiveGraphTerminalEligibleState(LiveGraphAuthorityNode(_, _, workDag, _, _, _, _, _, _)) -> workDag

        let private liveGraphAuthorityStateScheduler = function
            | LiveGraphFreshState(LiveGraphAuthorityNode(_, _, _, scheduler, _, _, _, _, _))
            | LiveGraphProgressingState(LiveGraphAuthorityNode(_, _, _, scheduler, _, _, _, _, _))
            | LiveGraphStaleState(LiveGraphAuthorityNode(_, _, _, scheduler, _, _, _, _, _))
            | LiveGraphDeadlockedState(LiveGraphAuthorityNode(_, _, _, scheduler, _, _, _, _, _))
            | LiveGraphQuarantinedState(LiveGraphAuthorityNode(_, _, _, scheduler, _, _, _, _, _))
            | LiveGraphTerminalEligibleState(LiveGraphAuthorityNode(_, _, _, scheduler, _, _, _, _, _)) -> scheduler

        let private criticalPathWorkLedgerFor (workDag:WorkDagAuthority<'Kind>) =
            let completed = max 0L workDag.cost.completedCost
            let criticalRemaining =
                max 0L (workDag.cost.knownRemainingCost + workDag.cost.blockedRemainingCost)
            let reserveP50 = max 0L workDag.cost.undiscoveredP50Cost
            let reserveP90 = max reserveP50 workDag.cost.undiscoveredP90Cost
            let semanticCredit = max 0L workDag.materialDeltaCost
            let effectiveRemaining = max 0L (criticalRemaining + reserveP90)
            let total = max 1L (completed + effectiveRemaining)
            let pct doneCost denominator =
                max 0.0 (min 100.0 (100.0 * float doneCost / float (max 1L denominator)))
            let throughput = max 0.001 workDag.throughputCostPerS
            let semanticCost label value =
                CompilerKernelV2.Measured.create<CompilerKernelV2.SemanticCostUnit> label value
            {
                completedCost = semanticCost "completedCost" completed
                criticalPathRemainingCost = semanticCost "criticalPathRemainingCost" criticalRemaining
                discoveryReserveP50 = semanticCost "discoveryReserveP50" reserveP50
                discoveryReserveP90 = semanticCost "discoveryReserveP90" reserveP90
                materialSemanticCredit = semanticCost "materialSemanticCredit" semanticCredit
                effectiveRemainingCost = semanticCost "effectiveRemainingCost" effectiveRemaining
                totalCost = semanticCost "totalCost" total
                progressLowPct = pct completed (completed + criticalRemaining + reserveP90)
                progressMidPct = pct completed (completed + criticalRemaining + reserveP50)
                progressHighPct = pct completed (completed + criticalRemaining)
                etaP50S = int64 (System.Math.Ceiling(float (max 0L (criticalRemaining + reserveP50)) / throughput))
                etaP90S = int64 (System.Math.Ceiling(float effectiveRemaining / throughput))
            }

        let private phaseIndexedWorkDagFor (workDag:WorkDagAuthority<'Kind>) : PhaseIndexedWorkDagState<'Kind> =
            let criticalPath = criticalPathWorkLedgerFor workDag
            let closureHash =
                stableTerminalGraphHash (
                    workDag.root.value + "|" + workDag.hot.value
                    + "|completed=" + string (CompilerKernelV2.Measured.value criticalPath.completedCost)
                    + "|critical_remaining=" + string (CompilerKernelV2.Measured.value criticalPath.criticalPathRemainingCost)
                    + "|reserve_p90=" + string (CompilerKernelV2.Measured.value criticalPath.discoveryReserveP90)
                    + "|semantic_credit=" + string (CompilerKernelV2.Measured.value criticalPath.materialSemanticCredit)
                    + "|effective_remaining=" + string (CompilerKernelV2.Measured.value criticalPath.effectiveRemainingCost))
            if workDag.ledgerClosed
               && CompilerKernelV2.Measured.value criticalPath.effectiveRemainingCost = 0L
               && not (semanticFactDebtBlocksTerminal workDag.semanticFactDebt) then
                PhaseIndexedWorkDagExhausted {
                    authority = workDag
                    criticalPath = criticalPath
                    closureHash = closureHash
                }
            else
                PhaseIndexedWorkDagOpen {
                    authority = workDag
                    criticalPath = criticalPath
                    closureHash = closureHash
                }

        let phaseIndexedWorkDagStateText = function
            | PhaseIndexedWorkDagOpen dag ->
                "PhaseIndexedWorkDag(Open|closure_hash=" + dag.closureHash
                + "|critical_remaining=" + string (CompilerKernelV2.Measured.value dag.criticalPath.criticalPathRemainingCost)
                + "|reserve_p90=" + string (CompilerKernelV2.Measured.value dag.criticalPath.discoveryReserveP90)
                + "|semantic_credit=" + string (CompilerKernelV2.Measured.value dag.criticalPath.materialSemanticCredit)
                + "|effective_remaining=" + string (CompilerKernelV2.Measured.value dag.criticalPath.effectiveRemainingCost)
                + "|progress_mid=" + sprintf "%.2f" dag.criticalPath.progressMidPct
                + "|eta_p90_s=" + string dag.criticalPath.etaP90S + ")"
            | PhaseIndexedWorkDagExhausted dag ->
                "PhaseIndexedWorkDag(Exhausted|closure_hash=" + dag.closureHash
                + "|completed=" + string (CompilerKernelV2.Measured.value dag.criticalPath.completedCost)
                + "|semantic_credit=" + string (CompilerKernelV2.Measured.value dag.criticalPath.materialSemanticCredit)
                + "|progress_mid=100.00|eta_p90_s=0)"


        let private workDagTerminalBlockReason (workDag:WorkDagAuthority<'Kind>) =
            let criticalPath = criticalPathWorkLedgerFor workDag
            "work_dag_open_critical_path_authority|hot=" + workDagNodeIdText workDag.hot
            + "|critical_remaining=" + string (CompilerKernelV2.Measured.value criticalPath.criticalPathRemainingCost)
            + "|reserve_p90=" + string (CompilerKernelV2.Measured.value criticalPath.discoveryReserveP90)
            + "|semantic_credit=" + string (CompilerKernelV2.Measured.value criticalPath.materialSemanticCredit)
            + "|effective_remaining=" + string (CompilerKernelV2.Measured.value criticalPath.effectiveRemainingCost)
            + "|credit=" + workUnitCreditDecisionText workDag.creditDecision
            + "|semantic_fact_debt=" + semanticFactDebtText workDag.semanticFactDebt

        let private workDagTerminalClosureVerdictFor (workDag:WorkDagAuthority<'Kind>) =
            match phaseIndexedWorkDagFor workDag with
            | PhaseIndexedWorkDagExhausted exhausted ->
                WorkDagTerminalClosureAllowed exhausted.authority
            | PhaseIndexedWorkDagOpen openDag when semanticFactDebtBlocksTerminal workDag.semanticFactDebt ->
                WorkDagTerminalClosureBlocked(
                    openDag.authority,
                    max 1L (CompilerKernelV2.Measured.value openDag.criticalPath.effectiveRemainingCost),
                    CompilerKernelV2.OperationalReasonIdOps.create (
                        semanticFactDebtTerminalBlockReason workDag.semanticFactDebt))
            | PhaseIndexedWorkDagOpen openDag ->
                WorkDagTerminalClosureBlocked(
                    openDag.authority,
                    max 1L (CompilerKernelV2.Measured.value openDag.criticalPath.effectiveRemainingCost),
                    CompilerKernelV2.OperationalReasonIdOps.create (
                        workDagTerminalBlockReason workDag))

        let private workDagBlocksTerminalClose (workDag:WorkDagAuthority<'Kind>) =
            match workDagTerminalClosureVerdictFor workDag with
            | WorkDagTerminalClosureBlocked _ -> true
            | WorkDagTerminalClosureAllowed _ -> false

        let private breakthroughAxisSatisfied
            (ownerVerdict:TypedTerminalOwnerClosureVerdict<'Kind>)
            (workDagVerdict:WorkDagTerminalClosureVerdict<'Kind>)
            (schedulerVerdict:SchedulerCausalVerdict<'Kind>)
            axis =
            match axis, ownerVerdict, workDagVerdict, schedulerVerdict with
            | BreakthroughOwnerClosure, TypedTerminalOwnersAllClosed _, _, _ -> true
            | BreakthroughWorkDagClosure, _, WorkDagTerminalClosureAllowed _, _ -> true
            | BreakthroughSchedulerCausality, _, _, SchedulerCausalityClosed _ -> true
            | BreakthroughSemanticFactDebt, _, WorkDagTerminalClosureAllowed workDag, _ ->
                not (semanticFactDebtBlocksTerminal workDag.semanticFactDebt)
            | BreakthroughSemanticFactDebt, _, WorkDagTerminalClosureBlocked(workDag, _, _), _ ->
                not (semanticFactDebtBlocksTerminal workDag.semanticFactDebt)
            | BreakthroughConsoleEvidence, _, _, _ -> true
            | BreakthroughDeadlockResolution, _, _, SchedulerCausalityDebtObserved _ -> false
            | _ -> false

        let private breakthroughEvidenceQuorumFor
            (ownerVerdict:TypedTerminalOwnerClosureVerdict<'Kind>)
            (workDagVerdict:WorkDagTerminalClosureVerdict<'Kind>)
            (schedulerVerdict:SchedulerCausalVerdict<'Kind>)
            : BreakthroughEvidenceQuorum<'Kind> =
            let required = [BreakthroughOwnerClosure; BreakthroughWorkDagClosure; BreakthroughSchedulerCausality; BreakthroughSemanticFactDebt; BreakthroughConsoleEvidence]
            let workDagOpt =
                match workDagVerdict with
                | WorkDagTerminalClosureAllowed workDag
                | WorkDagTerminalClosureBlocked(workDag, _, _) -> Some workDag
            let schedulerOpt =
                match schedulerVerdict with
                | SchedulerCausalityClosed scheduler
                | SchedulerCausalityOpen(scheduler, _)
                | SchedulerCausalityDebtObserved(scheduler, _) -> Some scheduler
            let observed =
                required
                |> List.map (fun axis ->
                    let present = breakthroughAxisSatisfied ownerVerdict workDagVerdict schedulerVerdict axis
                    { axis = axis
                      present = present
                      witness = if present then "present" else "missing"
                      authorityHash = stableTerminalGraphHash (breakthroughEvidenceAxisText axis + "|" + typedTerminalOwnerClosureVerdictText ownerVerdict + "|" + workDagTerminalClosureVerdictText workDagVerdict + "|" + schedulerCausalVerdictText schedulerVerdict)
                      workDag = workDagOpt
                      scheduler = schedulerOpt })
            let missing = observed |> List.choose (fun atom -> if atom.present then None else Some atom.axis)
            { required = required
              observed = observed
              missing = missing
              canPromote = List.isEmpty missing
              reason = CompilerKernelV2.OperationalReasonIdOps.create (if List.isEmpty missing then "breakthrough_quorum_satisfied" else "missing=" + (missing |> List.map breakthroughEvidenceAxisText |> String.concat ",")) }

        let private breakthroughTerminalVerdictFor ownerVerdict workDagVerdict schedulerVerdict =
            let quorum = breakthroughEvidenceQuorumFor ownerVerdict workDagVerdict schedulerVerdict
            if quorum.canPromote then BreakthroughTerminalReady quorum
            else
                BreakthroughTerminalBlocked(
                    quorum,
                    quorum.reason)

        let private terminalClosurePrerequisiteLedgerFor authority =
            let ownerVerdict = typedTerminalOwnerClosureVerdictFor authority
            let workDagVerdict = workDagTerminalClosureVerdictFor (liveGraphAuthorityStateWorkDag authority)
            let schedulerVerdict = schedulerCausalVerdictFor (liveGraphAuthorityStateScheduler authority)
            {
                ownerVerdict = ownerVerdict
                workDagVerdict = workDagVerdict
                schedulerVerdict = schedulerVerdict
                breakthroughVerdict = breakthroughTerminalVerdictFor ownerVerdict workDagVerdict schedulerVerdict
            }

        let private terminalClosurePrerequisiteVerdictFor authority =
            let ledger = terminalClosurePrerequisiteLedgerFor authority
            match ledger.ownerVerdict, ledger.workDagVerdict, ledger.schedulerVerdict, ledger.breakthroughVerdict with
            | TypedTerminalOwnersAllClosed _, WorkDagTerminalClosureAllowed _, SchedulerCausalityClosed _, BreakthroughTerminalReady _ ->
                TerminalClosurePrerequisitesSatisfied ledger
            | _, WorkDagTerminalClosureBlocked(_, _, reason), _, _ ->
                TerminalClosurePrerequisitesBlockedByWorkDag(ledger, reason)
            | TypedTerminalOwnersStillOpen(_, openKinds), _, _, _ ->
                TerminalClosurePrerequisitesBlockedByOwners(
                    ledger,
                    CompilerKernelV2.OperationalReasonIdOps.create (
                        "open=" + (openKinds |> List.map ownerAxisIdText |> String.concat ",")))
            | TypedTerminalOwnersNeedDeadlockResolution _, _, SchedulerCausalityDebtObserved(_, reason), _ ->
                TerminalClosurePrerequisitesBlockedBySchedulerCausality(ledger, reason)
            | _, _, SchedulerCausalityDebtObserved(_, reason), _
            | _, _, SchedulerCausalityOpen(_, reason), _ ->
                TerminalClosurePrerequisitesBlockedBySchedulerCausality(ledger, reason)
            | _, _, _, BreakthroughTerminalBlocked(_, reason) ->
                TerminalClosurePrerequisitesBlockedByBreakthroughQuorum(ledger, reason)
            | TypedTerminalOwnersNeedDeadlockResolution(_, openKinds), _, _, _ ->
                TerminalClosurePrerequisitesNeedDeadlockResolution(
                    ledger,
                    CompilerKernelV2.OperationalReasonIdOps.create (
                        "open=" + (openKinds |> List.map ownerAxisIdText |> String.concat ",")))

        let private liveGraphDeadlockResolutionFor<'Kind>
            (authority:LiveGraphAuthority<'Kind,LiveGraphDeadlocked>) =
            match authority with
            | LiveGraphAuthorityNode(graph, _, _, _, leaseOpt, obligation, parentContinuation, _, _) ->
                let graphHash = terminalExecutableGraphHashValue graph
                let crossAttemptOpt =
                    match obligation, leaseOpt with
                    | CrossKindObligationExpired(owner, obligationId, remainingCount, _, closeKey), _ when remainingCount > 0L ->
                        Some(
                            crossKindDrainAttemptFor
                                owner
                                obligationId
                                remainingCount
                                0L
                                closeKey
                                CrossKindDrainExpiredOwnerLease)
                    | CrossKindObligationOwned(owner, obligationId, beforeCount, lease), _ when beforeCount > 0L ->
                        let closeKey = crossKindObligationCloseKeyFor owner lease CrossKindDrainDeadlockOwnerLease
                        Some(
                            crossKindDrainAttemptFor
                                owner
                                obligationId
                                beforeCount
                                0L
                                closeKey
                                CrossKindDrainOwnedDeadlock)
                    | CrossKindObligationReduced attempt, _ when not attempt.drained ->
                        Some attempt
                    | _ -> None
                let parentProofOpt =
                    match parentContinuation, leaseOpt with
                    | ParentContinuationExpired(owner, cellId, pendingCount, _, closeKey), _ when pendingCount > 0L ->
                        Some(parentContinuationCloseProofFor owner cellId pendingCount 0L closeKey false ParentContinuationExpiredOwnerLeaseForceHandoff)
                    | ParentContinuationOwned(owner, cellId, _, pendingCount, lease), _ when pendingCount > 0L ->
                        let closeKey = parentContinuationCloseKeyFor owner lease ParentContinuationDeadlockForceHandoff
                        Some(parentContinuationCloseProofFor owner cellId pendingCount 0L closeKey false ParentContinuationOwnedDeadlockForceHandoff)
                    | ParentContinuationHandoffReady proof, _ when proof.afterPending > 0L ->
                        Some proof
                    | _ -> None
                match crossAttemptOpt, parentProofOpt, obligation, parentContinuation, leaseOpt with
                | Some attempt, Some _, _, _, _ ->
                    ResolveCrossKindThenParentContinuation(authority, attempt, parentContinuation)
                | Some attempt, None, _, _, _ ->
                    ForceCrossKindDrainWithLease(authority, attempt)
                | None, Some proof, _, _, _ ->
                    ForceParentContinuationHandoffWithLease(authority, proof)
                | None, None, _, ParentContinuationQuarantined plan, _ ->
                    QuarantineParentContinuationAndCommitNoFurther(authority, plan)
                | None, None, _, ParentContinuationOwned(owner, cellId, _, pendingCount, lease), _ when pendingCount > 0L ->
                    let plan =
                        parentContinuationQuarantinePlanFor
                            owner
                            cellId
                            pendingCount
                            lease.leaseId
                            graphHash
                            ParentContinuationQuarantineAfterDeadlockWithoutHandoff
                    QuarantineParentContinuationAndCommitNoFurther(authority, plan)
                | None, None, CrossKindObligationQuarantined plan, _, _ ->
                    QuarantineOrphanWorkersAndCommitNoFurther(authority, plan)
                | None, None, CrossKindObligationAbsent, _, Some lease ->
                    let owner = crossKindObligationOwnerFor graph lease
                    let plan =
                        crossKindQuarantinePlanFor
                            owner
                            ("orphan:" + graphHash.value)
                            (terminalExecutableGraphCrossKindCount graph)
                            lease.leaseId
                            graphHash
                            CrossKindQuarantineOrphanWorkersAfterDeadlock
                    QuarantineOrphanWorkersAndCommitNoFurther(authority, plan)
                | None, None, _, _, Some lease when terminalExecutableGraphContinuationPending graph ->
                    let owner = parentContinuationOwnerFor graph lease
                    let cellId = parentContinuationCellFor graph
                    let plan =
                        parentContinuationQuarantinePlanFor
                            owner
                            cellId
                            (terminalExecutableGraphPendingCount graph)
                            lease.leaseId
                            graphHash
                            ParentContinuationQuarantineUnknownOwnerAfterDeadlock
                    QuarantineParentContinuationAndCommitNoFurther(authority, plan)
                | None, None, _, _, Some lease ->
                    let owner = crossKindObligationOwnerFor graph lease
                    let plan =
                        crossKindQuarantinePlanFor
                            owner
                            ("unknown:" + graphHash.value)
                            (terminalExecutableGraphCrossKindCount graph)
                            lease.leaseId
                            graphHash
                            CrossKindQuarantineUnresolvedDeadlockOwnerLease
                    QuarantineOrphanWorkersAndCommitNoFurther(authority, plan)
                | _ ->
                    EmitStructuredLiveGraphDeadlock authority

        let liveGraphDeadlockResolutionText = function
            | EmitStructuredLiveGraphDeadlock authority -> "LiveGraphDeadlockResolution(EmitStructuredLiveGraphDeadlock|authority=" + liveGraphAuthorityStateText (LiveGraphDeadlockedState authority) + ")"
            | ForceCrossKindDrainWithLease(authority, attempt) -> "LiveGraphDeadlockResolution(ForceCrossKindDrainWithLease|" + crossKindDrainAttemptText attempt + "|authority=" + liveGraphAuthorityStateText (LiveGraphDeadlockedState authority) + ")"
            | ForceParentContinuationHandoffWithLease(authority, proof) -> "LiveGraphDeadlockResolution(ForceParentContinuationHandoffWithLease|" + parentContinuationCloseProofText proof + "|authority=" + liveGraphAuthorityStateText (LiveGraphDeadlockedState authority) + ")"
            | ResolveCrossKindThenParentContinuation(authority, attempt, parent) -> "LiveGraphDeadlockResolution(ResolveCrossKindThenParentContinuation|" + crossKindDrainAttemptText attempt + "|parent=" + parentContinuationObligationStateText parent + "|authority=" + liveGraphAuthorityStateText (LiveGraphDeadlockedState authority) + ")"
            | QuarantineParentContinuationAndCommitNoFurther(authority, plan) -> "LiveGraphDeadlockResolution(QuarantineParentContinuationAndCommitNoFurther|" + parentContinuationQuarantinePlanText plan + "|authority=" + liveGraphAuthorityStateText (LiveGraphDeadlockedState authority) + ")"
            | QuarantineOrphanWorkersAndCommitNoFurther(authority, plan) -> "LiveGraphDeadlockResolution(QuarantineOrphanWorkersAndCommitNoFurther|" + crossKindQuarantinePlanText plan + "|authority=" + liveGraphAuthorityStateText (LiveGraphDeadlockedState authority) + ")"

        let poisonTailStateFor<'Kind>
            (closureKind:NativeClosureKindId)
            (graph:TerminalExecutableGraphState<'Kind>)
            (repeatCap:int64)
            : PoisonTailState<'Kind> =
            let isPoisonTail =
                match closureKind with
                | NativeClosureParentReplayPoison -> true
                | _ -> false
            if not isPoisonTail then PoisonTailNotPresent closureKind
            else
                let repeat = terminalExecutableGraphSameStateRepeat graph
                match graph with
                | TerminalGraphProgressingState _ ->
                    PoisonTailDeferredBoundGraph(closureKind, graph, max 0L (repeatCap - repeat))
                | TerminalGraphStalledState _ when repeat <= repeatCap ->
                    PoisonTailDeferredBoundGraph(closureKind, graph, max 0L (repeatCap - repeat))
                | _ ->
                    PoisonTailTerminalEligibleAfterBoundedStasis(closureKind, graph, repeat)

        let poisonTailStateText = function
            | PoisonTailNotPresent closureKind ->
                "PoisonTailState(NotPresent|closure_kind=" + nativeClosureKindText closureKind + ")"
            | PoisonTailDeferredBoundGraph(closureKind, graph, retriesRemaining) ->
                "PoisonTailState(DeferredBoundGraph|closure_kind=" + nativeClosureKindText closureKind + "|retries_remaining=" + string retriesRemaining + "|graph=" + terminalExecutableGraphStateText graph + ")"
            | PoisonTailTerminalEligibleAfterBoundedStasis(closureKind, graph, sameStateRepeat) ->
                "PoisonTailState(TerminalEligibleAfterBoundedStasis|closure_kind=" + nativeClosureKindText closureKind + "|same_state_repeat=" + string sameStateRepeat + "|graph=" + terminalExecutableGraphStateText graph + ")"

        let poisonTailHandoffAuthorityText = function
            | PoisonTailHandoffNotPoison closureKind ->
                "PoisonTailHandoffAuthority(NotPoison|closure_kind=" + nativeClosureKindText closureKind + ")"
            | PoisonTailHandoffDeferredBoundGraph(state, waitForEdge, participants, nextAction) ->
                "PoisonTailHandoffAuthority(DeferredBoundGraph|state=" + poisonTailStateText state + "|wait_for_edge=" + waitForEdge + "|participants=" + participants + "|next=" + nextAction + ")"
            | PoisonTailHandoffAllowedAfterBoundedStasis(state, terminalOutcome, nextAction) ->
                "PoisonTailHandoffAuthority(AllowedAfterBoundedStasis|state=" + poisonTailStateText state + "|terminal_outcome=" + terminalOutcome + "|next=" + nextAction + ")"

        let poisonTailLegacyBypassVerdictText = function
            | PoisonTailLegacyBypassQuarantined(authority, reason) ->
                "PoisonTailLegacyBypass(Quarantined|reason=" + poisonTailLegacyBypassReasonText reason + "|authority=" + poisonTailHandoffAuthorityText authority + ")"
            | PoisonTailLegacyBypassAllowed(authority, reason) ->
                "PoisonTailLegacyBypass(Allowed|reason=" + poisonTailLegacyBypassReasonText reason + "|authority=" + poisonTailHandoffAuthorityText authority + ")"
            | PoisonTailLegacyBypassNotApplicable reason ->
                "PoisonTailLegacyBypass(NotApplicable|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let poisonTailHandoffAuthorityFor<'Kind>
            (closureKind:NativeClosureKindId)
            (state:PoisonTailState<'Kind>)
            (waitForEdge:string)
            (participants:string)
            : PoisonTailHandoffAuthority<'Kind> =
            match state with
            | PoisonTailNotPresent _ -> PoisonTailHandoffNotPoison closureKind
            | PoisonTailDeferredBoundGraph _ ->
                PoisonTailHandoffDeferredBoundGraph(state, waitForEdge, participants, "continue_parent_replay_poison_consumer_or_cross_kind_edge")
            | PoisonTailTerminalEligibleAfterBoundedStasis _ ->
                PoisonTailHandoffAllowedAfterBoundedStasis(state, "bounded_stasis_terminal_commit_required", "emit_typed_terminal_commit_not_legacy_fail_closed")

        let poisonTailLegacyBypassVerdictFor<'Kind>
            (authority:PoisonTailHandoffAuthority<'Kind>)
            : PoisonTailLegacyBypassVerdict<'Kind> =
            match authority with
            | PoisonTailHandoffNotPoison _ -> PoisonTailLegacyBypassNotApplicable (CompilerKernelV2.OperationalReasonIdOps.create "not_parent_replay_poison_tail")
            | PoisonTailHandoffDeferredBoundGraph _ ->
                PoisonTailLegacyBypassQuarantined(authority, PoisonTailLegacyBypassForbiddenWhileBoundGraphOrCrossKindEdgeLive)
            | PoisonTailHandoffAllowedAfterBoundedStasis _ ->
                PoisonTailLegacyBypassAllowed(authority, PoisonTailLegacyBypassBoundedStasisRequiresTerminalCommitGate)

        let poisonTailTransitionFrameText (frame:PoisonTailTransitionFrame<'Kind>) =
            "PoisonTailTransitionFrame(closure=" + frame.closureId.value + "|status=" + poisonTailObservedStatusText frame.status + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text frame.reason + "|wait_for_edge=" + frame.waitForEdge + "|participants=" + frame.participants + "|graph=" + terminalExecutableGraphStateText frame.graph + "|state=" + poisonTailStateText frame.state + "|authority=" + poisonTailHandoffAuthorityText frame.authority + "|verdict=" + poisonTailLegacyBypassVerdictText frame.verdict + ")"

        let parentReplayPoisonConsumerResultText = function
            | ParentReplayPoisonConsumerResultMissing ->
                "ParentReplayPoisonConsumerResult(Missing)"
            | ParentReplayPoisonConsumerScheduledDrain(passes, reason) ->
                "ParentReplayPoisonConsumerResult(ScheduledDrain|passes=" + string passes + "|reason=" + parentReplayPoisonConsumerReasonText reason + ")"
            | ParentReplayPoisonConsumerNoDeltaButPoisonAdvanced reason ->
                "ParentReplayPoisonConsumerResult(NoDeltaButPoisonAdvanced|reason=" + parentReplayPoisonConsumerReasonText reason + ")"
            | ParentReplayPoisonConsumerAstDeltaProduced(facts, reason) ->
                "ParentReplayPoisonConsumerResult(AstDeltaProduced|facts=" + string facts + "|reason=" + parentReplayPoisonConsumerReasonText reason + ")"
            | ParentReplayPoisonConsumerCyclePoisonProduced payload ->
                "ParentReplayPoisonConsumerResult(CyclePoisonProduced|payload=" + CompilerKernelV2.OperationalReasonIdOps.text payload + ")"
            | ParentReplayPoisonConsumerBlockedLostWake(requiredWake, reason) ->
                "ParentReplayPoisonConsumerResult(BlockedLostWake|required_wake=" + parentReplayPoisonRequiredWakeText requiredWake + "|reason=" + parentReplayPoisonConsumerReasonText reason + ")"

        let parentReplayPoisonSingleFlightText = function
            | ParentReplayPoisonSingleFlightNotApplicable reason ->
                "ParentReplayPoisonSingleFlight(NotApplicable|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | ParentReplayPoisonSingleFlightPending(key, frame, requiredWake) ->
                "ParentReplayPoisonSingleFlight(Pending|key=" + key + "|required_wake=" + requiredWake + "|frame=" + poisonTailTransitionFrameText frame + ")"
            | ParentReplayPoisonSingleFlightScheduled(key, frame, result) ->
                "ParentReplayPoisonSingleFlight(Scheduled|key=" + key + "|result=" + parentReplayPoisonConsumerResultText result + "|frame=" + poisonTailTransitionFrameText frame + ")"
            | ParentReplayPoisonSingleFlightResolved(key, frame, result) ->
                "ParentReplayPoisonSingleFlight(Resolved|key=" + key + "|result=" + parentReplayPoisonConsumerResultText result + "|frame=" + poisonTailTransitionFrameText frame + ")"
            | ParentReplayPoisonSingleFlightBlockedNoDelta(key, frame, result) ->
                "ParentReplayPoisonSingleFlight(BlockedNoDelta|key=" + key + "|result=" + parentReplayPoisonConsumerResultText result + "|frame=" + poisonTailTransitionFrameText frame + ")"

        let parentReplayPoisonSingleFlightBlocksClose = function
            | ParentReplayPoisonSingleFlightPending _
            | ParentReplayPoisonSingleFlightScheduled _
            | ParentReplayPoisonSingleFlightBlockedNoDelta _ -> true
            | ParentReplayPoisonSingleFlightNotApplicable _
            | ParentReplayPoisonSingleFlightResolved _ -> false

        let nativeTerminalAuthorityPhaseText = function
            | NativeTerminalAuthorityLive(graph, poison) ->
                "NativeTerminalAuthorityPhase(Live|graph=" + terminalExecutableGraphStateText graph + "|poison=" + parentReplayPoisonSingleFlightText poison + ")"
            | NativeTerminalAuthorityDeferred(graph, poison, reason) ->
                "NativeTerminalAuthorityPhase(Deferred|reason=" + nativeTerminalAuthorityDeferredReasonText reason + "|graph=" + terminalExecutableGraphStateText graph + "|poison=" + parentReplayPoisonSingleFlightText poison + ")"
            | NativeTerminalAuthorityExhausted(graph, poison, proof) ->
                "NativeTerminalAuthorityPhase(Exhausted|proof=" + nativeTerminalExhaustionProofText proof + "|graph=" + terminalExecutableGraphStateText graph + "|poison=" + parentReplayPoisonSingleFlightText poison + ")"

        let nativeTerminalAuthorityPhaseFor graph poison =
            if parentReplayPoisonSingleFlightBlocksClose poison then
                NativeTerminalAuthorityDeferred(graph, poison, NativeTerminalAuthorityParentReplayPoisonSingleFlightNotResolved)
            else
                match graph with
                | TerminalGraphExhaustedState _ -> NativeTerminalAuthorityExhausted(graph, poison, NativeTerminalExhaustionGraphAndPoisonResolved)
                | TerminalGraphProgressingState(TerminalExecutableGraphNode(_, pending, queue, active, crossKind, sidecarPending, continuationPending, _, _, _, _))
                | TerminalGraphStalledState(TerminalExecutableGraphNode(_, pending, queue, active, crossKind, sidecarPending, continuationPending, _, _, _, _))
                | TerminalGraphExhaustedState(TerminalExecutableGraphNode(_, pending, queue, active, crossKind, sidecarPending, continuationPending, _, _, _, _))
                    when pending > 0L || queue > 0L || active > 0L || crossKind > 0L || sidecarPending || continuationPending ->
                    NativeTerminalAuthorityLive(graph, poison)
                | _ -> NativeTerminalAuthorityDeferred(graph, poison, NativeTerminalAuthorityGraphNotExhausted)

        let hopacPushRuntimeEventText = function
            | HopacPushPoisonTailHandoff frame ->
                "HopacPushRuntimeEvent(PoisonTailHandoff|" + poisonTailTransitionFrameText frame + ")"
            | HopacPushJpWaitFrameObserved(key, status, waitMs) ->
                "HopacPushRuntimeEvent(JpWaitFrameObserved|key=" + key + "|status=" + JpWaitLiveFrameStatusIdOps.text status + "|wait_ms=" + string waitMs + ")"
            | HopacPushJpWaitFrameClosedByTerminalAction(key, status, waitMs, authority) ->
                "HopacPushRuntimeEvent(JpWaitFrameClosedByTerminalAction|key=" + key + "|status=" + JpWaitLiveFrameStatusIdOps.text status + "|wait_ms=" + string waitMs + "|authority=" + authority + ")"
            | HopacPushGenerationChangePoisonTail(tag, key, site, frame) ->
                "HopacPushRuntimeEvent(GenerationChangePoisonTail|tag=" + tag + "|key=" + key + "|site=" + site + "|" + poisonTailTransitionFrameText frame + ")"
            | HopacPushSchedulerHeartbeatObserved reason ->
                "HopacPushRuntimeEvent(SchedulerHeartbeatObserved|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let pushDrivenSchedulerAuthorityFor = function
            | HopacPushPoisonTailHandoff frame as event ->
                match frame.verdict with
                | PoisonTailLegacyBypassQuarantined _ -> PushDrivenAuthorityDeferredByPoisonTail(event, frame)
                | PoisonTailLegacyBypassAllowed _ -> PushDrivenAuthorityRequiresTerminalCommit(event, frame)
                | PoisonTailLegacyBypassNotApplicable reason -> PushDrivenAuthorityObserverOnly(event, PushDrivenObserverPoisonTailNotApplicable reason)
            | HopacPushGenerationChangePoisonTail(_, _, _, frame) as event ->
                match frame.verdict with
                | PoisonTailLegacyBypassQuarantined _ -> PushDrivenAuthorityDeferredByPoisonTail(event, frame)
                | PoisonTailLegacyBypassAllowed _ -> PushDrivenAuthorityRequiresTerminalCommit(event, frame)
                | PoisonTailLegacyBypassNotApplicable reason -> PushDrivenAuthorityObserverOnly(event, PushDrivenObserverPoisonTailNotApplicable reason)
            | HopacPushJpWaitFrameClosedByTerminalAction _ as event ->
                PushDrivenAuthorityObserverOnly(event, PushDrivenObserverJpWaitCannotRewriteProducer)
            | HopacPushJpWaitFrameObserved _ as event ->
                PushDrivenAuthorityObserverOnly(event, PushDrivenObserverJpWaitLiveFrame)
            | HopacPushSchedulerHeartbeatObserved reason as event ->
                PushDrivenAuthorityObserverOnly(event, PushDrivenObserverMetronomeHeartbeat reason)

        let pushDrivenSchedulerAuthorityText = function
            | PushDrivenAuthorityAbsent -> "PushDrivenSchedulerAuthority(Absent)"
            | PushDrivenAuthorityObserverOnly(event, reason) ->
                "PushDrivenSchedulerAuthority(ObserverOnly|reason=" + pushDrivenAuthorityObserverReasonText reason + "|event=" + hopacPushRuntimeEventText event + ")"
            | PushDrivenAuthorityDeferredByPoisonTail(event, frame) ->
                "PushDrivenSchedulerAuthority(DeferredByPoisonTail|event=" + hopacPushRuntimeEventText event + "|frame=" + poisonTailTransitionFrameText frame + ")"
            | PushDrivenAuthorityRequiresTerminalCommit(event, frame) ->
                "PushDrivenSchedulerAuthority(RequiresTerminalCommit|event=" + hopacPushRuntimeEventText event + "|frame=" + poisonTailTransitionFrameText frame + ")"

        let metronomeObserverRoleFor authority =
            match authority with
            | PushDrivenAuthorityAbsent -> MetronomeObserverNoPushEvent
            | PushDrivenAuthorityDeferredByPoisonTail _
            | PushDrivenAuthorityObserverOnly _ -> MetronomeObserverPushEventObserved authority
            | PushDrivenAuthorityRequiresTerminalCommit _ -> MetronomeObserverRootCompleteAltOwnsTerminal authority

        let metronomeObserverRoleText = function
            | MetronomeObserverNoPushEvent -> "MetronomeObserverRole(NoPushEvent|authority=none)"
            | MetronomeObserverPushEventObserved authority ->
                "MetronomeObserverRole(PushEventObserved|authority=observer_only|" + pushDrivenSchedulerAuthorityText authority + ")"
            | MetronomeObserverRootCompleteAltOwnsTerminal authority ->
                "MetronomeObserverRole(RootCompleteAltOwnsTerminal|metronome=observer_only|" + pushDrivenSchedulerAuthorityText authority + ")"

        let terminalProjectionVerbosityText = function
            | TerminalProjectionFullFirstOccurrence -> "full_first_occurrence"
            | TerminalProjectionCompactRepeat -> "compact_repeat"
            | TerminalProjectionHudBoard -> "hud_board"

        let private terminalProjectionRef (text:string) =
            NativeCutoverStableRef.ref32 "terminal-projection" [ text ]

        let stringIngressTranslationReceiptText = function
            | StringIngressForbidden(fieldRef, patternRef, replacementRef) ->
                FastRuntimeFormat.format "StringIngressTranslationReceipt(Forbidden|field_ref=%s|pattern_ref=%s|replacement_ref=%s)" [| box (sprintf "%08x" fieldRef); box (sprintf "%08x" patternRef); box (sprintf "%08x" replacementRef) |]
            | StringIngressTranslated(fieldRef, patternRef, typedProjectionRef) ->
                FastRuntimeFormat.format "StringIngressTranslationReceipt(Translated|field_ref=%s|pattern_ref=%s|typed_projection_ref=%s)" [| box (sprintf "%08x" fieldRef); box (sprintf "%08x" patternRef); box (sprintf "%08x" typedProjectionRef) |]
            | StringIngressErased(fieldRef, replacementRef) ->
                sprintf "StringIngressTranslationReceipt(Erased|field_ref=%08x|replacement_ref=%08x)" fieldRef replacementRef

        let terminalProjectionCompactToken closureId graphHash refs repeat =
            stableTerminalGraphHash (
                closureId + "|" + graphHash
                + "|" + string refs.outcomeRef
                + "|" + string refs.commitGateRef
                + "|" + string refs.pushAuthorityRef
                + "|" + string refs.poisonAuthorityRef
                + "|" + string repeat)

        let canonicalTerminalProjectionFor<'Kind>
            (closureId:CanonicalTerminalClosureId<'Kind>)
            (graph:TerminalExecutableGraphState<'Kind>)
            (outcomeClass:string)
            (commitGateClass:string)
            (pushAuthorityClass:string)
            (poisonAuthorityClass:string)
            (verbosity:TerminalProjectionVerbosity)
            : CanonicalTerminalProjection<'Kind> =
            let graphHash = terminalExecutableGraphHashValue graph
            let repeat = terminalExecutableGraphSameStateRepeat graph
            let epoch = terminalExecutableGraphEpochValue graph
            let refs =
                { outcomeRef = terminalProjectionRef outcomeClass
                  commitGateRef = terminalProjectionRef commitGateClass
                  pushAuthorityRef = terminalProjectionRef pushAuthorityClass
                  poisonAuthorityRef = terminalProjectionRef poisonAuthorityClass }
            {
                canonicalClosureId = closureId
                graphHash = graphHash
                graphEpoch = epoch
                sameGraphRepeatCount = repeat
                decisionRefs = refs
                compactionToken = terminalProjectionCompactToken closureId.value graphHash.value refs repeat
                verbosity = verbosity
            }

        let canonicalTerminalProjectionText (projection:CanonicalTerminalProjection<'Kind>) =
            let refs = projection.decisionRefs
            FastRuntimeFormat.format "CanonicalTerminalProjection(closure=%s|graph_hash=%s|graph_epoch=%d|same_graph_repeat=%d|outcome_ref=%s|commit_gate_ref=%s|push_authority_ref=%s|poison_authority_ref=%s|token=%s|verbosity=%s)" [| box projection.canonicalClosureId.value; box projection.graphHash.value; box projection.graphEpoch.value; box projection.sameGraphRepeatCount; box (sprintf "%08x" refs.outcomeRef); box (sprintf "%08x" refs.commitGateRef); box (sprintf "%08x" refs.pushAuthorityRef); box (sprintf "%08x" refs.poisonAuthorityRef); box projection.compactionToken; box (terminalProjectionVerbosityText projection.verbosity) |]

        let terminalDiagnosticBoardText (board:TerminalDiagnosticBoard<'Kind>) =
            let refs = board.refs
            let invariantText =
                if List.isEmpty refs.invariantRefs then "none"
                else refs.invariantRefs |> List.map (sprintf "%08x") |> String.concat ";"
            FastRuntimeFormat.format "TerminalDiagnosticBoard(blocker_ref=%s|reason_ref=%s|next_ref=%s|violation_refs=%s|projection=%s)" [| box (sprintf "%08x" refs.blockerRef); box (sprintf "%08x" refs.reasonRef); box (sprintf "%08x" refs.nextActionRef); box invariantText; box (canonicalTerminalProjectionText board.projection) |]

        let terminalDiagnosticBoardFor projection blocker reason nextAction invariantViolations =
            { projection = projection
              refs =
                { blockerRef = terminalProjectionRef blocker
                  reasonRef = terminalProjectionRef reason
                  nextActionRef = terminalProjectionRef nextAction
                  invariantRefs = invariantViolations |> List.map terminalProjectionRef } }

        let poisonTailLegacyBypassIsQuarantined = function
            | PoisonTailLegacyBypassQuarantined _ -> true
            | _ -> false

        let nativePromiseTerminalOutcomeFor<'Kind>
            (closureId:CanonicalTerminalClosureId<'Kind>)
            (epoch:TerminalGraphEpoch<'Kind>)
            (astDeltaId:NativeAstEvaluationDeltaResultId)
            (outcome:NativePromiseOutcomeId)
            : NativePromiseTerminalOutcome<'Kind> =
            match outcome with
            | NativePromiseOutcomeResolvedDelta(promiseId, facts) -> NativePromiseTerminalResolvedMaterial(promiseId, facts)
            | NativePromiseOutcomeFailedPlateau(promiseId, payload) -> NativePromiseTerminalFailedSemantic(promiseId, payload, "plateau")
            | NativePromiseOutcomeFailedCycle(promiseId, payload) -> NativePromiseTerminalFailedSemantic(promiseId, payload, "cycle")
            | NativePromiseOutcomeNoFurther(promiseId, reason) ->
                let witness =
                    match astDeltaId with
                    | NativeAstDeltaPureTopologyWitnessMaterialized(contract, kind, witnessReason) ->
                        let witnessReasonCanonical =
                            witnessReason
                            |> topologyWitnessReasonOfNativePure
                            |> topologyWitnessReasonIdText
                        let id : TopologyWitnessId<'Kind> = topologyWitnessId ("tw:" + closureId.value + "|" + nativeDirectEvaluationContractText contract + "|" + nativeClosureKindText kind + "|" + witnessReasonCanonical)
                        topologyWitnessMaterializationFor id epoch
                    | _ -> TopologyWitnessAbsent
                NativePromiseTerminalClosedNoFurther(promiseId, reason, witness)
            | NativePromiseOutcomeObserverOnly(promiseId, reason) -> NativePromiseTerminalObserverOnly(promiseId, reason)

        let topologyWitnessProgressClassFor
            facts
            (consumerDeltaKindId:ConsumerDeltaKindAfterExecutionId)
            (materialDeltaKindId:NativeMaterialDeltaClassId)
            (actualSemanticDeltaKindId:NativeActualSemanticDeltaClassId)
            (outcome:NativePromiseTerminalOutcome<'Kind>) =
            let topologyOnly =
                match consumerDeltaKindId, materialDeltaKindId, actualSemanticDeltaKindId with
                | ConsumerDeltaPureSidecarDrain _, _, _
                | ConsumerDeltaPureParentContinuation _, _, _
                | ConsumerDeltaPureTopologyDelta _, _, _
                | _, NativeMaterialDeltaPureTopologyDelta, _
                | _, _, NativeActualSemanticPureTopologyMaterializedWitness
                | _, _, NativeActualSemanticPureTopologyDelta -> true
                | _ -> false
            match outcome with
            | NativePromiseTerminalClosedNoFurther(_, _, witness) when topologyWitnessIsFresh witness ->
                TopologyWitnessProgressFirstMaterialization
            | NativePromiseTerminalClosedNoFurther(_, _, TopologyWitnessAlreadyMaterialized _) when topologyOnly ->
                TopologyWitnessProgressRepeatedTopologyOnly
            | _ when facts > 0L && not topologyOnly ->
                TopologyWitnessProgressSemanticMaterialFact facts
            | _ when facts > 0L && topologyOnly ->
                TopologyWitnessProgressRepeatedTopologyOnly
            | _ -> TopologyWitnessProgressNoMaterialFact

        let nativePromiseTerminalOutcomeText = function
            | NativePromiseTerminalResolvedMaterial(promiseId, facts) -> "NativePromiseTerminalOutcome(ResolvedMaterial|promise=" + promiseId + "|facts=" + string facts + ")"
            | NativePromiseTerminalFailedSemantic(promiseId, payload, payloadClass) -> "NativePromiseTerminalOutcome(FailedSemantic|promise=" + promiseId + "|payload_class=" + payloadClass + "|payload=" + payload + ")"
            | NativePromiseTerminalClosedNoFurther(promiseId, reason, witness) -> "NativePromiseTerminalOutcome(ClosedNoFurther|promise=" + promiseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|witness=" + topologyWitnessMaterializationText witness + ")"
            | NativePromiseTerminalObserverOnly(promiseId, reason) -> "NativePromiseTerminalOutcome(ObserverOnly|promise=" + promiseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let nativePromiseTerminalOutcomeId = function
            | NativePromiseTerminalResolvedMaterial(promiseId, _) -> "to:resolved:" + promiseId
            | NativePromiseTerminalFailedSemantic(promiseId, _, payloadClass) -> "to:failed:" + payloadClass + ":" + promiseId
            | NativePromiseTerminalClosedNoFurther(promiseId, _, witness) ->
                match witness with
                | TopologyWitnessFirstMaterialization(id, _)
                | TopologyWitnessAlreadyMaterialized(id, _, _) -> "to:no_further:" + promiseId + ":" + id.value
                | TopologyWitnessAbsent -> "to:no_further:" + promiseId
            | NativePromiseTerminalObserverOnly(promiseId, _) -> "to:observer:" + promiseId

        let tryRecursiveOwnerLedgerEmptyProof (ledger:RecursiveOwnerLedger<'Kind>) =
            let openOwners = recursiveOwnerLedgerOpenCount ledger
            if openOwners = 0L then
                Ok {
                    ledger = ledger
                    proofHash = stableTerminalGraphHash ("owner_ledger_no_open_owners|" + recursiveOwnerLedgerText ledger)
                }
            else
                Error("recursive_owner_ledger_not_empty|open=" + string openOwners)

        let recursiveOwnerLedgerEmptyProofHash (proof:RecursiveOwnerLedgerEmptyProof<'Kind>) = proof.proofHash

        let private nativeTerminalOutcomeProofFor
            (emptyOwners:RecursiveOwnerLedgerEmptyProof<'Kind>)
            (exhaustedWorkDag:PhaseIndexedWorkDag<'Kind,WorkDagExhaustedPhase>)
            (outcome:NativePromiseTerminalOutcome<'Kind>) =
            match outcome with
            | NativePromiseTerminalResolvedMaterial _ ->
                Ok (NativeTerminalMaterialProof outcome)
            | NativePromiseTerminalFailedSemantic _ ->
                Ok (NativeTerminalSemanticFailureProof outcome)
            | NativePromiseTerminalClosedNoFurther(_, _, witness) ->
                Ok (NativeTerminalNoFurtherProof(outcome, emptyOwners, exhaustedWorkDag, witness))
            | NativePromiseTerminalObserverOnly(promiseId, reason) ->
                Error("observer_only_outcome_cannot_form_terminal_proof|promise=" + promiseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason)

        let private nativeTerminalOutcomeProofOutcome = function
            | NativeTerminalMaterialProof outcome
            | NativeTerminalSemanticFailureProof outcome
            | NativeTerminalNoFurtherProof(outcome, _, _, _) -> outcome

        let private nativeRootCompletePromiseIdFor = function
            | NativePromiseTerminalResolvedMaterial(promiseId, _)
            | NativePromiseTerminalFailedSemantic(promiseId, _, _)
            | NativePromiseTerminalClosedNoFurther(promiseId, _, _)
            | NativePromiseTerminalObserverOnly(promiseId, _) -> promiseId

        let private nativeRootCompleteResolutionFor
            (proof:NativeRootCompleteTerminalProof<'Kind>)
            : NativeRootCompleteResolution<'Kind> =
            let outcome = nativeTerminalOutcomeProofOutcome proof.outcomeProof
            let resolution =
                match proof.outcomeProof with
                | NativeTerminalMaterialProof (NativePromiseTerminalResolvedMaterial(promiseId, _)) ->
                    NativeRootCompleteBuildOk(promiseId, proof.graphHash)
                | NativeTerminalSemanticFailureProof (NativePromiseTerminalFailedSemantic(promiseId, _, payloadClass)) ->
                    NativeRootCompleteSemanticFailure(promiseId, "sf:" + proof.proofHash, payloadClass, proof.graphHash)
                | NativeTerminalNoFurtherProof(NativePromiseTerminalClosedNoFurther(promiseId, reason, _), _, _, _) ->
                    NativeRootCompleteNoFurther(promiseId, nativePromiseTerminalOutcomeId outcome, reason, proof.graphHash)
                | NativeTerminalMaterialProof unexpected
                | NativeTerminalSemanticFailureProof unexpected
                | NativeTerminalNoFurtherProof(unexpected, _, _, _) ->
                    invalidOp ("terminal outcome proof variant mismatch: " + nativePromiseTerminalOutcomeText unexpected)
            let evaluatorReceiptHint =
                match resolution with
                | NativeRootCompleteBuildOk(promiseId, _)
                | NativeRootCompleteSemanticFailure(promiseId, _, _, _)
                | NativeRootCompleteNoFurther(promiseId, _, _, _) -> promiseId
            canonicalRootAuthorityResolveFromEvaluator evaluatorReceiptHint ("native_root_complete_terminal_proof|proof=" + proof.proofHash) |> ignore
            resolution

        let nativeRootCompleteResolutionText = function
            | NativeRootCompleteBuildOk(promiseId, graphHash) ->
                "NativeRootCompleteResolution(BuildOk|promise=" + promiseId + "|graph_hash=" + graphHash.value + ")"
            | NativeRootCompleteSemanticFailure(promiseId, semanticFailureId, payloadClass, graphHash) ->
                "NativeRootCompleteResolution(SemanticFailure|promise=" + promiseId + "|semantic_failure_id=" + semanticFailureId + "|payload_class=" + payloadClass + "|graph_hash=" + graphHash.value + ")"
            | NativeRootCompleteNoFurther(promiseId, terminalOutcomeId, reason, graphHash) ->
                "NativeRootCompleteResolution(NoFurther|promise=" + promiseId + "|terminal_outcome_id=" + terminalOutcomeId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|graph_hash=" + graphHash.value + ")"

        let nativeRootCompleteTerminalProofText (proof:NativeRootCompleteTerminalProof<'Kind>) =
            "NativeRootCompleteTerminalProof(cell=" + proof.cellId.value
            + "|promise=" + proof.promiseId
            + "|graph_hash=" + proof.graphHash.value
            + "|open_owners=" + string (recursiveOwnerLedgerOpenCount proof.emptyOwners.ledger)
            + "|work_dag_closure_hash=" + proof.workDag.closureHash
            + "|critical_path_root=" + proof.criticalPathRoot.value
            + "|replay_key=" + proof.replayKey.value
            + "|poison_tail_transition_hash=" + proof.poisonTail.transitionHash
            + "|terminal_outcome_graph_hash=" + proof.terminalOutcome.graphHash.value
            + "|proof_hash=" + proof.proofHash
            + ")"

        let private nativeRootCompleteProofHash
            (promiseId:string)
            (graphHash:TerminalGraphStateHash<'Kind>)
            (owners:RecursiveOwnerLedger<'Kind>)
            (workDagClosureHash:string)
            (outcome:NativePromiseTerminalOutcome<'Kind>) =
            stableTerminalGraphHash (
                promiseId + "|" + graphHash.value
                + "|owners=" + recursiveOwnerLedgerText owners
                + "|work_dag=" + workDagClosureHash
                + "|outcome=" + nativePromiseTerminalOutcomeId outcome)

        let private nativeRootCompleteArmFor<'Kind>
            (outcome:NativePromiseTerminalOutcome<'Kind>)
            (authority:LiveGraphAuthorityState<'Kind>)
            : NativeRootCompleteArmVerdict<'Kind> =
            match outcome with
            | NativePromiseTerminalObserverOnly(_, reason) ->
                NativeRootCompleteObserverOnly(reason, authority)
            | NativePromiseTerminalResolvedMaterial _
            | NativePromiseTerminalFailedSemantic _
            | NativePromiseTerminalClosedNoFurther _ ->
                let indexed = phaseIndexedLiveGraphFor authority
                let prerequisites = terminalClosurePrerequisiteVerdictFor authority
                match indexed, prerequisites with
                | PhaseIndexedTerminalEligible terminalGraph, TerminalClosurePrerequisitesSatisfied ledger ->
                    let openOwners = recursiveOwnerLedgerOpenCount (phaseIndexedLiveGraphAuthorityOwners terminalGraph)
                    if openOwners <> 0L then
                        NativeRootCompleteRejectedOwners(
                            CompilerKernelV2.OperationalReasonIdOps.create ("terminal_eligible_graph_has_open_owners:" + string openOwners),
                            (phaseIndexedLiveGraphAuthorityOwners terminalGraph))
                    else
                        let graphState = phaseIndexedLiveGraphAuthorityGraph terminalGraph
                        let workDagAuthority = phaseIndexedLiveGraphAuthorityWorkDag terminalGraph
                        let graphHash = terminalExecutableGraphHashValue graphState
                        match phaseIndexedWorkDagFor workDagAuthority with
                        | PhaseIndexedWorkDagOpen openDag ->
                            NativeRootCompleteRejectedPrerequisites(
                                CompilerKernelV2.OperationalReasonIdOps.create "terminal_eligible_graph_has_open_phase_indexed_work_dag",
                                TerminalClosurePrerequisitesBlockedByWorkDag(
                                    ledger,
                                    CompilerKernelV2.OperationalReasonIdOps.create (
                                        phaseIndexedWorkDagStateText (PhaseIndexedWorkDagOpen openDag))))
                        | PhaseIndexedWorkDagExhausted exhaustedDag ->
                            match tryRecursiveOwnerLedgerEmptyProof (phaseIndexedLiveGraphAuthorityOwners terminalGraph) with
                            | Error reason ->
                                NativeRootCompleteRejectedOwners(CompilerKernelV2.OperationalReasonIdOps.create reason, (phaseIndexedLiveGraphAuthorityOwners terminalGraph))
                            | Ok emptyOwners ->
                                match nativeTerminalOutcomeProofFor emptyOwners exhaustedDag outcome with
                                | Error reason ->
                                    NativeRootCompleteObserverOnly(CompilerKernelV2.OperationalReasonIdOps.create reason, authority)
                                | Ok outcomeProof ->
                                    let promiseId = nativeRootCompletePromiseIdFor outcome
                                    let proofHash = nativeRootCompleteProofHash promiseId graphHash emptyOwners.ledger exhaustedDag.closureHash outcome
                                    let cellId : NativeRootCompleteCellId<'Kind> = { value = "root_complete:" + proofHash }
                                    let criticalPathRoot : PhaseIndexedWorkUnitId<'Kind,WorkUnitExhaustedPhase> = {
                                        value = exhaustedDag.authority.root.value
                                    }
                                    let replayKey : PhaseIndexedReplayKey<'Kind,ReplayKeyClosedPhase> = {
                                        value = "replay_closed:" + proofHash
                                    }
                                    let terminalOutcome : PhaseIndexedTerminalOutcome<'Kind,TerminalOutcomeResolvedPhase> = {
                                        outcome = outcome
                                        graphHash = graphHash
                                    }
                                    let poisonTail : PhaseIndexedPoisonTail<'Kind,PoisonTailClosedPhase> = {
                                        ownerLedger = emptyOwners.ledger
                                        transitionHash = stableTerminalGraphHash ("poison_tail_closed|" + proofHash)
                                    }
                                    NativeRootCompleteArmedByTerminalProof {
                                        cellId = cellId
                                        graph = terminalGraph
                                        emptyOwners = emptyOwners
                                        prerequisites = ledger
                                        workDag = exhaustedDag
                                        criticalPathRoot = criticalPathRoot
                                        replayKey = replayKey
                                        terminalOutcome = terminalOutcome
                                        poisonTail = poisonTail
                                        outcomeProof = outcomeProof
                                        promiseId = promiseId
                                        graphHash = graphHash
                                        proofHash = proofHash
                                    }
                | PhaseIndexedTerminalEligible terminalGraph, blocked ->
                    if recursiveOwnerLedgerOpenCount (phaseIndexedLiveGraphAuthorityOwners terminalGraph) > 0L then
                        NativeRootCompleteRejectedOwners(
                            CompilerKernelV2.OperationalReasonIdOps.create "terminal_eligible_graph_blocked_by_open_owners",
                            (phaseIndexedLiveGraphAuthorityOwners terminalGraph))
                    else
                        NativeRootCompleteRejectedPrerequisites(
                            CompilerKernelV2.OperationalReasonIdOps.create "terminal_eligible_graph_prerequisites_not_satisfied",
                            blocked)
                | PhaseIndexedDeadlocked _, _ ->
                    NativeRootCompleteRejectedPhase(
                        CompilerKernelV2.OperationalReasonIdOps.create "deadlock_is_observer_evidence_until_owner_transaction_promotes_terminal_eligible",
                        authority)
                | _ ->
                    NativeRootCompleteRejectedPhase(
                        CompilerKernelV2.OperationalReasonIdOps.create "root_complete_requires_phase_terminal_eligible",
                        authority)

        let nativeRootCompleteArmVerdictText = function
            | NativeRootCompleteObserverOnly(reason, authority) ->
                "NativeRootCompleteArm(ObserverOnly|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|authority=" + liveGraphAuthorityStateText authority + ")"
            | NativeRootCompleteRejectedPhase(reason, authority) ->
                "NativeRootCompleteArm(RejectedPhase|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|authority=" + liveGraphAuthorityStateText authority + ")"
            | NativeRootCompleteRejectedOwners(reason, ledger) ->
                "NativeRootCompleteArm(RejectedOwners|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|ledger=" + recursiveOwnerLedgerText ledger + ")"
            | NativeRootCompleteRejectedPrerequisites(reason, verdict) ->
                "NativeRootCompleteArm(RejectedPrerequisites|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|verdict=" + terminalClosurePrerequisiteVerdictText verdict + ")"
            | NativeRootCompleteArmedByTerminalProof proof ->
                "NativeRootCompleteArm(Armed|proof=" + nativeRootCompleteTerminalProofText proof + ")"

        let nativeRootCompleteWaitEdgeText = function
            | NativeRootCompleteWaitsForTerminalEligible authority ->
                "WaitEdge(TerminalEligible|authority=" + liveGraphAuthorityStateText authority + ")"
            | NativeRootCompleteWaitsForOwnerClose ledger ->
                "WaitEdge(OwnerClose|open=" + string (recursiveOwnerLedgerOpenCount ledger) + "|ledger=" + recursiveOwnerLedgerText ledger + ")"
            | NativeRootCompleteWaitsForPrerequisites verdict ->
                "WaitEdge(Prerequisites|verdict=" + terminalClosurePrerequisiteVerdictText verdict + ")"
            | NativeRootCompleteWaitsForIvarResolution proof ->
                "WaitEdge(IVarResolution|proof=" + nativeRootCompleteTerminalProofText proof + ")"

        let nativeRootCompleteWaitGraphFor verdict : NativeRootCompleteWaitGraph<'Kind> =
            match verdict with
            | NativeRootCompleteObserverOnly(_, authority)
            | NativeRootCompleteRejectedPhase(_, authority) -> {
                cellId = None
                edges = [NativeRootCompleteWaitsForTerminalEligible authority]
                authority = NativeRootCompleteWaitObserverOnly
              }
            | NativeRootCompleteRejectedOwners(_, ledger) -> {
                cellId = None
                edges = [NativeRootCompleteWaitsForOwnerClose ledger]
                authority = NativeRootCompleteWaitObserverOnly
              }
            | NativeRootCompleteRejectedPrerequisites(_, prerequisiteVerdict) -> {
                cellId = None
                edges = [NativeRootCompleteWaitsForPrerequisites prerequisiteVerdict]
                authority = NativeRootCompleteWaitObserverOnly
              }
            | NativeRootCompleteArmedByTerminalProof proof -> {
                cellId = Some proof.cellId
                edges = [NativeRootCompleteWaitsForIvarResolution proof]
                authority = NativeRootCompleteWaitSchedulerPushOwned
              }

        let nativeRootCompleteWaitGraphText (graph:NativeRootCompleteWaitGraph<'Kind>) =
            let cellText = graph.cellId |> Option.map (fun cellId -> cellId.value) |> Option.defaultValue "unarmed"
            let authorityText =
                match graph.authority with
                | NativeRootCompleteWaitObserverOnly -> "ObserverOnly"
                | NativeRootCompleteWaitSchedulerPushOwned -> "SchedulerPushOwned"
            "NativeRootCompleteWaitGraph(cell=" + cellText
            + "|authority=" + authorityText
            + "|edges=" + (graph.edges |> List.map nativeRootCompleteWaitEdgeText |> String.concat "->")
            + ")"

        let nativeRootCompleteStateForProof
            (proof:NativeRootCompleteTerminalProof<'Kind>)
            : NativeRootCompleteState<'Kind> =
            let ivar = Hopac.IVar<NativeRootCompleteResolution<'Kind>>()
            let armed : NativeRootCompleteCell<'Kind,NativeRootCompleteArmedPhase> = {
                id = proof.cellId
                ivar = ivar
                proof = Some proof
            }
            NativeRootCompleteArmed(armed, proof)

        let nativeRootCompleteAwaitAlt = function
            | NativeRootCompleteOpen cell -> Hopac.IVar.read cell.ivar
            | NativeRootCompleteArmed(cell, _) -> Hopac.IVar.read cell.ivar
            | NativeRootCompleteResolved(cell, _, _) -> Hopac.IVar.read cell.ivar

        let nativeRootCompleteFillJob = function
            | NativeRootCompleteArmed(cell, proof) ->
                let resolution = nativeRootCompleteResolutionFor proof
                Hopac.IVar.fill cell.ivar resolution
            | NativeRootCompleteOpen _ ->
                invalidOp "RootComplete IVar cannot be filled before terminal proof is armed."
            | NativeRootCompleteResolved _ ->
                invalidOp "RootComplete IVar cannot be filled twice."

        let nativeRootCompleteAuthorityBoundaryFor
            (outcome:NativePromiseTerminalOutcome<'Kind>)
            (authority:LiveGraphAuthorityState<'Kind>) =
            match nativeRootCompleteArmFor outcome authority with
            | NativeRootCompleteArmedByTerminalProof proof ->
                NativeRootCompleteAuthorityOwnedBySchedulerPushActor proof
            | verdict ->
                NativeRootCompleteAuthorityObserverOnly(
                    CompilerKernelV2.OperationalReasonIdOps.create (nativeRootCompleteArmVerdictText verdict),
                    authority)

        let private nativeWriterCapabilityForResolved
            (proof:NativeRootCompleteTerminalProof<'Kind>)
            (resolution:NativeRootCompleteResolution<'Kind>) =
            let workDagAuthority = phaseIndexedLiveGraphAuthorityWorkDag proof.graph
            match phaseIndexedWorkDagFor workDagAuthority with
            | PhaseIndexedWorkDagOpen openDag ->
                Error(
                    PhaseIndexedWorkDagOpen openDag,
                    "writer_capability_requires_exhausted_critical_path_work_dag")
            | PhaseIndexedWorkDagExhausted exhaustedDag when recursiveOwnerLedgerOpenCount proof.emptyOwners.ledger <> 0L ->
                Error(
                    PhaseIndexedWorkDagExhausted exhaustedDag,
                    "writer_capability_requires_empty_recursive_owner_ledger")
            | PhaseIndexedWorkDagExhausted exhaustedDag ->
                let artifactSetHash =
                    stableTerminalGraphHash (
                        proof.proofHash + "|" + exhaustedDag.closureHash
                        + "|resolution=" + nativeRootCompleteResolutionText resolution)
                let plan = {
                    proofHash = proof.proofHash
                    graphHash = proof.graphHash
                    workDagClosureHash = exhaustedDag.closureHash
                    artifactSetHash = artifactSetHash
                }
                Ok {
                    proof = proof
                    resolution = resolution
                    workDag = exhaustedDag
                    plan = plan
                }

        let nativeWriterCapabilityText (capability:NativeWriterCapability<'Kind>) =
            "NativeWriterCapability(proof_hash=" + capability.plan.proofHash
            + "|graph_hash=" + capability.plan.graphHash.value
            + "|work_dag_closure_hash=" + capability.plan.workDagClosureHash
            + "|artifact_set_hash=" + capability.plan.artifactSetHash
            + "|resolution=" + nativeRootCompleteResolutionText capability.resolution + ")"

        let nativeWriterCapabilityEvidence (capability:NativeWriterCapability<'Kind>) : NativeWriterCapabilityEvidence<'Kind> =
            {
                cellId = capability.proof.cellId.value
                proofHash = capability.proof.proofHash
                resolution = capability.resolution
                workDag = capability.workDag
                workDagClosureHash = capability.plan.workDagClosureHash
                artifactSetHash = capability.plan.artifactSetHash
            }

        let nativeWriterArtifactSetHashForText capabilityHash artifactManifestText =
            stableTerminalGraphHash (
                "writer_artifact_set|capability=" + capabilityHash
                + "|manifest=" + artifactManifestText)

        let nativeRootCompleteWriterGateFor = function
            | NativeRootCompleteResolved(_, proof, resolution) ->
                match nativeWriterCapabilityForResolved proof resolution with
                | Ok capability -> NativeRootCompleteWriterReady capability
                | Error(workDag, reason) ->
                    NativeRootCompleteWriterBlockedWorkDag(
                        workDag,
                        CompilerKernelV2.OperationalReasonIdOps.create reason)
            | NativeRootCompleteArmed(_, proof) ->
                NativeRootCompleteWriterBlockedUnarmed(
                    CompilerKernelV2.OperationalReasonIdOps.create ("root_complete_ivar_armed_but_not_resolved:" + proof.proofHash))
            | NativeRootCompleteOpen _ -> NativeRootCompleteWriterBlockedOpen

        let nativeRootCompleteWriterGateText = function
            | NativeRootCompleteWriterBlockedOpen ->
                "NativeRootCompleteWriterGate(BlockedOpen)"
            | NativeRootCompleteWriterBlockedUnarmed reason ->
                "NativeRootCompleteWriterGate(BlockedAwaitingIvar|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NativeRootCompleteWriterBlockedWorkDag(workDag, reason) ->
                "NativeRootCompleteWriterGate(BlockedWorkDag|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|work_dag=" + phaseIndexedWorkDagStateText workDag + ")"
            | NativeRootCompleteWriterReady capability ->
                "NativeRootCompleteWriterGate(Ready|capability=" + nativeWriterCapabilityText capability + ")"

        let private nativeWriterProjectionForCapability (capability:NativeWriterCapability<'Kind>) =
            match capability.resolution with
            | NativeRootCompleteBuildOk _ -> NativeWriterProjectionBuildOk capability
            | NativeRootCompleteSemanticFailure _
            | NativeRootCompleteNoFurther _ -> NativeWriterProjectionBuildError(capability, capability.resolution)

        let private nativeAuthorityKernelHash label parts =
            stableTerminalGraphHash (label + "|" + String.concat "|" parts)

        let nativeAuthorityKernelStateText = function
            | NativeAuthorityKernelRunningState running ->
                "NativeAuthorityKernel(Running|phase=" + phaseIndexedLiveGraphStatePhaseText running.graph
                + "|owners=" + recursiveOwnerLedgerText running.owners
                + "|work_dag=" + phaseIndexedWorkDagStateText running.workDag
                + "|epoch_hash=" + running.epochHash + ")"
            | NativeAuthorityKernelTerminalEligibleState terminal ->
                "NativeAuthorityKernel(TerminalEligible|kernel_hash=" + terminal.kernelHash
                + "|proof=" + nativePromiseTerminalOutcomeText (nativeTerminalOutcomeProofOutcome terminal.outcomeProof)
                + ")"
            | NativeAuthorityKernelArmedState armed ->
                "NativeAuthorityKernel(Armed|kernel_hash=" + armed.kernelHash
                + "|proof_hash=" + armed.proof.proofHash + ")"
            | NativeAuthorityKernelResolvedState resolved ->
                "NativeAuthorityKernel(Resolved|kernel_hash=" + resolved.kernelHash
                + "|resolution=" + nativeRootCompleteResolutionText resolved.resolution
                + "|writer=" + nativeRootCompleteWriterGateText resolved.writerGate + ")"

        let nativeAuthorityKernelStart
            (graph:PhaseIndexedLiveGraphState<'Kind>)
            (owners:RecursiveOwnerLedger<'Kind>)
            (workDag:PhaseIndexedWorkDagState<'Kind>)
            (waitGraph:NativeRootCompleteWaitGraph<'Kind> option) =
            let epochHash =
                nativeAuthorityKernelHash "kernel_running" [
                    phaseIndexedLiveGraphStatePhaseText graph
                    recursiveOwnerLedgerText owners
                    phaseIndexedWorkDagStateText workDag
                ]
            NativeAuthorityKernelRunningState {
                graph = graph
                owners = owners
                workDag = workDag
                waitGraph = waitGraph
                epochHash = epochHash
            }

        let private nativeAuthorityKernelTerminalForProof
            (proof:NativeRootCompleteTerminalProof<'Kind>) =
            {
                graph = proof.graph
                emptyOwners = proof.emptyOwners
                prerequisites = proof.prerequisites
                workDag = proof.workDag
                replayKey = proof.replayKey
                terminalOutcome = proof.terminalOutcome
                outcomeProof = proof.outcomeProof
                poisonTail = proof.poisonTail
                kernelHash =
                    nativeAuthorityKernelHash "kernel_terminal" [
                        proof.proofHash
                        proof.workDag.closureHash
                        proof.replayKey.value
                        proof.poisonTail.transitionHash
                    ]
            }

        let rec nativeAuthorityKernelTransition
            (event:NativeAuthorityEvent<'Kind>)
            (state:NativeAuthorityKernelState<'Kind>)
            : NativeAuthorityTransition<'Kind> =
            let advance next =
                let beforeHash = nativeAuthorityKernelHash "before" [nativeAuthorityKernelStateText state]
                let afterHash = nativeAuthorityKernelHash "after" [nativeAuthorityKernelStateText next]
                if beforeHash = afterHash then NativeAuthorityTransitionObserved next
                else NativeAuthorityTransitionAdvanced(beforeHash, afterHash, next)
            match event, state with
            | NativeAuthorityBatch events, _ ->
                let folder current nextEvent =
                    match nativeAuthorityKernelTransition nextEvent current with
                    | NativeAuthorityTransitionObserved next
                    | NativeAuthorityTransitionAdvanced(_, _, next) -> next
                    | NativeAuthorityTransitionRejected(_, next) -> next
                let next = List.fold folder state events
                advance next
            | NativeAuthorityObserve _, _ -> NativeAuthorityTransitionObserved state
            | NativeAuthorityOwnerTransaction (TypedOwnerTransactionRejected(_, reason, _)), _ ->
                NativeAuthorityTransitionRejected(NativeAuthorityOwnerTransactionRejected reason, state)
            | NativeAuthorityOwnerTransaction (TypedOwnerTransactionCommitted receipt), NativeAuthorityKernelRunningState running ->
                let next = NativeAuthorityKernelRunningState {
                    running with
                        owners = receipt.afterLedger
                        epochHash = nativeAuthorityKernelHash "kernel_owner_transaction" [running.epochHash; receipt.transactionId; recursiveOwnerLedgerText receipt.afterLedger]
                }
                advance next
            | NativeAuthorityWorkDagTransition workDag, NativeAuthorityKernelRunningState running ->
                let next = NativeAuthorityKernelRunningState {
                    running with
                        workDag = workDag
                        epochHash = nativeAuthorityKernelHash "kernel_work_dag" [running.epochHash; phaseIndexedWorkDagStateText workDag]
                }
                advance next
            | NativeAuthorityTerminalOutcomeResolved terminalOutcome, NativeAuthorityKernelRunningState running ->
                match running.graph with
                | PhaseIndexedTerminalEligible terminalGraph ->
                    let authority = LiveGraphTerminalEligibleState terminalGraph.authority
                    match nativeRootCompleteArmFor terminalOutcome.outcome authority with
                    | NativeRootCompleteArmedByTerminalProof proof ->
                        advance (NativeAuthorityKernelTerminalEligibleState (nativeAuthorityKernelTerminalForProof proof))
                    | verdict ->
                        NativeAuthorityTransitionRejected(NativeAuthorityTerminalOutcomeRejected (nativeRootCompleteArmVerdictText verdict), state)
                | _ ->
                    NativeAuthorityTransitionRejected(NativeAuthorityTerminalOutcomeRequiresTerminalEligibleGraph, state)
            | NativeAuthorityRootCompleteArmed proof, NativeAuthorityKernelTerminalEligibleState terminal ->
                let terminalGraphState = phaseIndexedLiveGraphAuthorityGraph terminal.graph
                let terminalGraphHash = terminalExecutableGraphHashValue terminalGraphState
                if proof.graphHash.value <> terminalGraphHash.value then
                    NativeAuthorityTransitionRejected(NativeAuthorityRootProofGraphMismatch, state)
                else
                    let root = nativeRootCompleteStateForProof proof
                    let armed = {
                        terminal = terminal
                        root = root
                        proof = proof
                        kernelHash = nativeAuthorityKernelHash "kernel_armed" [terminal.kernelHash; proof.proofHash]
                    }
                    advance (NativeAuthorityKernelArmedState armed)
            | NativeAuthorityRootCompleteArmed _, NativeAuthorityKernelRunningState _ ->
                NativeAuthorityTransitionRejected(
                    NativeAuthorityTerminalOutcomeRequiresTerminalEligibleGraph,
                    state)
            | NativeAuthorityRootCompleteResolved resolution, NativeAuthorityKernelArmedState armed ->
                match armed.root with
                | NativeRootCompleteArmed(cell, proof) ->
                    let resolvedCell : NativeRootCompleteCell<'Kind,NativeRootCompleteResolvedPhase> = {
                        id = cell.id
                        ivar = cell.ivar
                        proof = cell.proof
                    }
                    let root = NativeRootCompleteResolved(resolvedCell, proof, resolution)
                    let writerGate = nativeRootCompleteWriterGateFor root
                    let resolved = {
                        terminal = armed.terminal
                        root = root
                        resolution = resolution
                        writerGate = writerGate
                        kernelHash = nativeAuthorityKernelHash "kernel_resolved" [armed.kernelHash; nativeRootCompleteResolutionText resolution; nativeRootCompleteWriterGateText writerGate]
                    }
                    advance (NativeAuthorityKernelResolvedState resolved)
                | _ -> NativeAuthorityTransitionRejected(NativeAuthorityArmedStateMissingRoot, state)
            | NativeAuthorityRootCompleteResolved _, _ ->
                NativeAuthorityTransitionRejected(NativeAuthorityRootResolutionRequiresArmedKernel, state)
            | NativeAuthorityOwnerTransaction _, _ ->
                NativeAuthorityTransitionRejected(NativeAuthorityOwnerMutationAfterTerminalForbidden, state)
            | NativeAuthorityWorkDagTransition _, _ ->
                NativeAuthorityTransitionRejected(NativeAuthorityWorkDagMutationAfterTerminalForbidden, state)
            | NativeAuthorityTerminalOutcomeResolved _, _ ->
                NativeAuthorityTransitionRejected(NativeAuthorityTerminalOutcomeAlreadyResolved, state)
            | NativeAuthorityRootCompleteArmed _, _ ->
                NativeAuthorityTransitionRejected(NativeAuthorityRootAlreadyArmed, state)

        let nativeAuthorityTransitionState = function
            | NativeAuthorityTransitionObserved state
            | NativeAuthorityTransitionAdvanced(_, _, state)
            | NativeAuthorityTransitionRejected(_, state) -> state

        let nativeAuthorityRejectionText = function
            | NativeAuthorityOwnerTransactionRejected reason -> "OwnerTransactionRejected(" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NativeAuthorityTerminalOutcomeRequiresTerminalEligibleGraph -> "TerminalOutcomeRequiresTerminalEligibleGraph"
            | NativeAuthorityTerminalOutcomeRejected verdict -> "TerminalOutcomeRejected(" + verdict + ")"
            | NativeAuthorityRootProofGraphMismatch -> "RootProofGraphMismatch"
            | NativeAuthorityRootResolutionRequiresArmedKernel -> "RootResolutionRequiresArmedKernel"
            | NativeAuthorityOwnerMutationAfterTerminalForbidden -> "OwnerMutationAfterTerminalForbidden"
            | NativeAuthorityWorkDagMutationAfterTerminalForbidden -> "WorkDagMutationAfterTerminalForbidden"
            | NativeAuthorityTerminalOutcomeAlreadyResolved -> "TerminalOutcomeAlreadyResolved"
            | NativeAuthorityRootAlreadyArmed -> "RootAlreadyArmed"
            | NativeAuthorityArmedStateMissingRoot -> "ArmedStateMissingRoot"

        open Hopac

        type NativeRootCompleteRuntimeReceipt =
            | NativeRootCompleteRuntimeFirstFill of cellId:string * resolution:NativeRootCompleteResolution<TerminalOutcomeKind>
            | NativeRootCompleteRuntimeAlreadyFilled of cellId:string * resolution:NativeRootCompleteResolution<TerminalOutcomeKind>
            | NativeRootCompleteRuntimeFillRejected of cellId:string * reason:CompilerKernelV2.OperationalReasonId

        type NativeRootCompleteTerminalCellIdentity = NativeRootCompleteCellId<TerminalOutcomeKind>

        let private nativeRootCompleteTerminalCells =
            System.Collections.Concurrent.ConcurrentDictionary<NativeRootCompleteTerminalCellIdentity, Hopac.IVar<NativeRootCompleteResolution<TerminalOutcomeKind>>>()

        let private nativeRootCompleteTerminalResolutions =
            System.Collections.Concurrent.ConcurrentDictionary<NativeRootCompleteTerminalCellIdentity, NativeRootCompleteResolution<TerminalOutcomeKind>>()

        let private nativeRootCompleteTerminalProofs =
            System.Collections.Concurrent.ConcurrentDictionary<NativeRootCompleteTerminalCellIdentity, NativeRootCompleteTerminalProof<TerminalOutcomeKind>>()

        let private nativeAuthorityKernelTerminalStates =
            System.Collections.Concurrent.ConcurrentDictionary<NativeRootCompleteTerminalCellIdentity, NativeAuthorityKernelState<TerminalOutcomeKind>>()

        let private nativeAuthorityDecisionHashes =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,CompilerIdentityKernel.ContentDigest>()

        let mutable private nativeRootCompleteLatestCellId : NativeRootCompleteTerminalCellIdentity option = None

        let emitNativeAuthorityDecisionChange
            (decisionKey:string)
            (decisionHash:string)
            (_detailJson:string) =
            let decisionKeyRef = CompilerIdentityKernel.ContentDigest.ofText "native-authority-decision-key" decisionKey
            let decisionHashRef = CompilerIdentityKernel.ContentDigest.ofText "native-authority-decision-hash" decisionHash
            let mutable previous = Unchecked.defaultof<CompilerIdentityKernel.ContentDigest>
            let hadPrevious = nativeAuthorityDecisionHashes.TryGetValue(decisionKeyRef, &previous)
            let changed = (not hadPrevious) || previous <> decisionHashRef
            if changed then nativeAuthorityDecisionHashes.[decisionKeyRef] <- decisionHashRef
            changed

        let tryNativeRootCompleteLatestAlt () =
            match nativeRootCompleteLatestCellId with
            | Some cellId ->
                match nativeRootCompleteTerminalCells.TryGetValue cellId with
                | true, ivar -> Some(Hopac.IVar.read ivar)
                | false, _ -> None
            | None -> None

        let nativeRootCompleteRuntimeReceiptText = function
            | NativeRootCompleteRuntimeFirstFill(cellId, resolution) ->
                "NativeRootCompleteRuntimeReceipt(FirstFill|cell=" + cellId + "|resolution=" + nativeRootCompleteResolutionText resolution + ")"
            | NativeRootCompleteRuntimeAlreadyFilled(cellId, resolution) ->
                "NativeRootCompleteRuntimeReceipt(AlreadyFilled|cell=" + cellId + "|resolution=" + nativeRootCompleteResolutionText resolution + ")"
            | NativeRootCompleteRuntimeFillRejected(cellId, reason) ->
                "NativeRootCompleteRuntimeReceipt(FillRejected|cell=" + cellId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let nativeRootCompleteResolveTerminalProof
            (proof:NativeRootCompleteTerminalProof<TerminalOutcomeKind>) =
            let cellIdentity = proof.cellId
            let cellId = proof.cellId.value
            let ivar =
                nativeRootCompleteTerminalCells.GetOrAdd(
                    cellIdentity,
                    fun _ -> Hopac.IVar<NativeRootCompleteResolution<TerminalOutcomeKind>>())
            let resolution = nativeRootCompleteResolutionFor proof
            let terminalKernel =
                NativeAuthorityKernelTerminalEligibleState (nativeAuthorityKernelTerminalForProof proof)
            let armedKernel =
                nativeAuthorityKernelTransition
                    (NativeAuthorityRootCompleteArmed proof)
                    terminalKernel
                |> nativeAuthorityTransitionState
            let resolvedKernel =
                nativeAuthorityKernelTransition
                    (NativeAuthorityRootCompleteResolved resolution)
                    armedKernel
                |> nativeAuthorityTransitionState
            match resolvedKernel with
            | NativeAuthorityKernelResolvedState _ ->
                nativeAuthorityKernelTerminalStates.[cellIdentity] <- resolvedKernel
                nativeRootCompleteLatestCellId <- Some cellIdentity
                nativeRootCompleteTerminalProofs.[cellIdentity] <- proof
                let kernelText = nativeAuthorityKernelStateText resolvedKernel
                let resolutionHash =
                    stableTerminalGraphHash (
                        proof.proofHash + "|" + nativeRootCompleteResolutionText resolution
                        + "|kernel=" + kernelText)
                emitNativeAuthorityDecisionChange
                    ("root_complete:" + cellId)
                    resolutionHash
                    ("{\"proof\":" + esc (nativeRootCompleteTerminalProofText proof)
                     + ",\"resolution\":" + esc (nativeRootCompleteResolutionText resolution)
                     + ",\"authority_kernel_du\":" + esc kernelText + "}")
                |> ignore
                if nativeRootCompleteTerminalResolutions.TryAdd(cellIdentity, resolution) then
                    run (Hopac.IVar.fill ivar resolution)
                    NativeRootCompleteRuntimeFirstFill(cellId, resolution)
                else
                    match nativeRootCompleteTerminalResolutions.TryGetValue cellIdentity with
                    | true, existing -> NativeRootCompleteRuntimeAlreadyFilled(cellId, existing)
                    | false, _ ->
                        NativeRootCompleteRuntimeFillRejected(
                            cellId,
                            CompilerKernelV2.OperationalReasonIdOps.create "resolution_registry_lost_after_try_add")
            | invalidKernel ->
                NativeRootCompleteRuntimeFillRejected(
                    cellId,
                    CompilerKernelV2.OperationalReasonIdOps.create (
                        "native_authority_kernel_did_not_reach_resolved|state=" + nativeAuthorityKernelStateText invalidKernel))

        let nativeRootCompleteAwaitTerminalProof
            (proof:NativeRootCompleteTerminalProof<TerminalOutcomeKind>) =
            let ivar =
                nativeRootCompleteTerminalCells.GetOrAdd(
                    proof.cellId,
                    fun _ -> Hopac.IVar<NativeRootCompleteResolution<TerminalOutcomeKind>>())
            Hopac.IVar.read ivar

        let nativeWriterBuildOkSealText cellId capabilityText artifactSetHash resolutionText workDagText =
            "NativeWriterBuildOkSeal(cell=" + cellId
            + "|root_complete=resolved_by_native_authority_kernel"
            + "|root_resolution=" + resolutionText
            + "|owner_ledger=closed_or_quarantined_by_terminal_quorum"
            + "|semantic_sidecar=strict_dataflow_satisfied_or_quarantined"
            + "|work_dag=" + workDagText
            + "|artifact_hash=" + artifactSetHash
            + "|content_hash_authorized=true"
            + "|writer=" + capabilityText + ")"

        let tryNativeAuthorityKernelLatestResolved () =
            match nativeRootCompleteLatestCellId with
            | Some cellId ->
                match nativeAuthorityKernelTerminalStates.TryGetValue cellId with
                | true, NativeAuthorityKernelResolvedState resolved -> Some resolved
                | _ -> None
            | None -> None

        let tryNativeRootCompleteLatestResolvedState () =
            tryNativeAuthorityKernelLatestResolved ()
            |> Option.map (fun resolved -> resolved.root)

        // Expose the already-minted typed writer capability as
        // a value, not as a string authorization query.  Consumers may carry it
        // through another phantom-indexed corridor, but cannot construct it.
        let tryNativeWriterCapabilityLatest () =
            match tryNativeAuthorityKernelLatestResolved () with
            | Some resolved ->
                match resolved.writerGate with
                | NativeRootCompleteWriterReady capability -> Some capability
                | _ -> None
            | None -> None

        type NativeRootBoundaryState =
            | NativeRootBoundaryUnarmed
            | NativeRootBoundaryRunning of kernelHash:string
            | NativeRootBoundaryTerminalEligible of kernelHash:string
            | NativeRootBoundaryArmed of cellId:string * proofHash:string
            | NativeRootBoundaryResolved of cellId:string * resolution:NativeRootCompleteResolution<TerminalOutcomeKind>

        let nativeRootBoundaryState () =
            match nativeRootCompleteLatestCellId with
            | Some cellIdentity ->
                let cellId = cellIdentity.value
                match nativeAuthorityKernelTerminalStates.TryGetValue cellIdentity with
                | true, NativeAuthorityKernelResolvedState resolved ->
                    NativeRootBoundaryResolved(cellId, resolved.resolution)
                | true, NativeAuthorityKernelArmedState armed ->
                    NativeRootBoundaryArmed(cellId, armed.proof.proofHash)
                | true, NativeAuthorityKernelTerminalEligibleState terminal ->
                    NativeRootBoundaryTerminalEligible terminal.kernelHash
                | true, NativeAuthorityKernelRunningState running ->
                    NativeRootBoundaryRunning running.epochHash
                | false, _ -> NativeRootBoundaryUnarmed
            | None -> NativeRootBoundaryUnarmed

        let nativeRootBoundaryStateText = function
            | NativeRootBoundaryUnarmed -> "NativeRootBoundary(Unarmed)"
            | NativeRootBoundaryRunning kernelHash ->
                "NativeRootBoundary(Running|kernel_hash=" + kernelHash + ")"
            | NativeRootBoundaryTerminalEligible kernelHash ->
                "NativeRootBoundary(TerminalEligible|kernel_hash=" + kernelHash + ")"
            | NativeRootBoundaryArmed(cellId, proofHash) ->
                "NativeRootBoundary(Armed|cell=" + cellId + "|proof_hash=" + proofHash + ")"
            | NativeRootBoundaryResolved(cellId, resolution) ->
                "NativeRootBoundary(Resolved|cell=" + cellId + "|resolution=" + nativeRootCompleteResolutionText resolution + ")"

        let nativePromiseTerminalCommitGateText (gate:NativePromiseTerminalCommitGate<'Kind>) =
            match gate with
            | NativePromiseTerminalCommitNotRequested reason ->
                "NativePromiseTerminalCommitGate(NotRequested|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NativePromiseTerminalCommitDeferredLiveGraph(outcome, authority) ->
                "NativePromiseTerminalCommitGate(DeferredLiveGraph|outcome=" + nativePromiseTerminalOutcomeText outcome + "|authority=" + liveGraphAuthorityStateText authority + ")"
            | NativePromiseTerminalCommitDeferredFreshTopologyWitness(outcome, witness, authority) ->
                "NativePromiseTerminalCommitGate(DeferredFreshTopologyWitness|outcome=" + nativePromiseTerminalOutcomeText outcome + "|witness=" + topologyWitnessMaterializationText witness + "|authority=" + liveGraphAuthorityStateText authority + ")"
            | NativePromiseTerminalCommitDeferredTypedTerminalGate(outcome, authority, observer, reason) ->
                let livenessText =
                    match observer.liveness with
                    | TemporalLivenessUnknown -> "unknown"
                    | TemporalLivenessObserved gate -> gate
                let bridgeText =
                    match observer.bridge with
                    | TemporalBridgeUnknown -> "unknown"
                    | TemporalBridgeObserved gate -> gate
                let terminalActionText =
                    match observer.terminalAction with
                    | TemporalTerminalActionNotObserved -> "not_observed"
                    | TemporalTerminalActionObserved -> "observed"
                "NativePromiseTerminalCommitGate(DeferredTypedTerminalGate|outcome=" + nativePromiseTerminalOutcomeText outcome
                + "|authority=" + liveGraphAuthorityStateText authority
                + "|reason=" + nativeTerminalActionSuppressionReasonText reason
                + "|liveness=" + livenessText
                + "|bridge=" + bridgeText
                + "|terminal_action=" + terminalActionText + ")"
            | NativePromiseTerminalCommitBlockedByOpenOwners(outcome, authority, ledger, reason) ->
                "NativePromiseTerminalCommitGate(BlockedByOpenOwners|outcome=" + nativePromiseTerminalOutcomeText outcome + "|reason=" + nativeTerminalActionSuppressionReasonText reason + "|authority=" + liveGraphAuthorityStateText authority + "|owners=" + terminalOwnershipLedgerText ledger + ")"
            | NativePromiseTerminalCommitBlockedByWorkDagAuthority(outcome, authority, workDag, reason) ->
                "NativePromiseTerminalCommitGate(BlockedByWorkDagAuthority|outcome=" + nativePromiseTerminalOutcomeText outcome + "|reason=" + nativeTerminalActionSuppressionReasonText reason + "|work_dag=" + workDagAuthorityText workDag + "|authority=" + liveGraphAuthorityStateText authority + ")"
            | NativePromiseTerminalCommitBlockedBySchedulerCausality(outcome, authority, scheduler, reason) ->
                "NativePromiseTerminalCommitGate(BlockedBySchedulerCausality|outcome=" + nativePromiseTerminalOutcomeText outcome + "|reason=" + nativeTerminalActionSuppressionReasonText reason + "|scheduler=" + schedulerCausalAuthorityText scheduler + "|authority=" + liveGraphAuthorityStateText authority + ")"
            | NativePromiseTerminalCommitBlockedByBreakthroughQuorum(outcome, authority, quorum, reason) ->
                "NativePromiseTerminalCommitGate(BlockedByBreakthroughQuorum|outcome=" + nativePromiseTerminalOutcomeText outcome + "|reason=" + nativeTerminalActionSuppressionReasonText reason + "|quorum=" + breakthroughEvidenceQuorumText quorum + "|authority=" + liveGraphAuthorityStateText authority + ")"
            | NativePromiseTerminalCommitRejectedDeadlockObserverOnly(outcome, authority, reason) ->
                "NativePromiseTerminalCommitGate(RejectedDeadlockObserverOnly|outcome=" + nativePromiseTerminalOutcomeText outcome + "|reason=" + nativeTerminalActionSuppressionReasonText reason + "|authority=" + liveGraphAuthorityStateText authority + ")"
            | NativePromiseTerminalCommitAllowedSemanticFailure(semanticFailureId, promiseId, payloadClass, graph, proof) ->
                "NativePromiseTerminalCommitGate(AllowedSemanticFailure|semantic_failure_id=" + semanticFailureId + "|promise=" + promiseId + "|payload_class=" + payloadClass + "|graph=" + terminalExecutableGraphStateText graph + "|root_complete_proof=" + nativeRootCompleteTerminalProofText proof + ")"
            | NativePromiseTerminalCommitAllowedResolvedMaterial(promiseId, graph, proof) ->
                "NativePromiseTerminalCommitGate(AllowedResolvedMaterial|promise=" + promiseId + "|graph=" + terminalExecutableGraphStateText graph + "|root_complete_proof=" + nativeRootCompleteTerminalProofText proof + ")"
            | NativePromiseTerminalCommitAllowedNoFurther(terminalOutcomeId, promiseId, reason, graph, proof) ->
                "NativePromiseTerminalCommitGate(AllowedNoFurther|terminal_outcome_id=" + terminalOutcomeId + "|promise=" + promiseId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|graph=" + terminalExecutableGraphStateText graph + "|root_complete_proof=" + nativeRootCompleteTerminalProofText proof + ")"

        let nativePromiseTerminalCommitGateAllowsClose = function
            | NativePromiseTerminalCommitAllowedSemanticFailure _
            | NativePromiseTerminalCommitAllowedResolvedMaterial _
            | NativePromiseTerminalCommitAllowedNoFurther _ -> true
            | _ -> false

        let nativePromiseTerminalCommitGateFor<'Kind>
            (outcome:NativePromiseTerminalOutcome<'Kind>)
            (graph:TerminalExecutableGraphState<'Kind>)
            (repeatCap:int64)
            (temporalEvidence:TemporalTerminalObserverEvidence)
            (semanticFailureId:string)
            : NativePromiseTerminalCommitGate<'Kind> =
            let authority = liveGraphAuthorityFor graph
            let livenessText =
                match temporalEvidence.liveness with
                | TemporalLivenessUnknown -> "unknown"
                | TemporalLivenessObserved gate -> gate
            let bridgeText =
                match temporalEvidence.bridge with
                | TemporalBridgeUnknown -> "unknown"
                | TemporalBridgeObserved gate -> gate
            let terminalActionText =
                match temporalEvidence.terminalAction with
                | TemporalTerminalActionNotObserved -> "not_observed"
                | TemporalTerminalActionObserved -> "observed"
            let observerText =
                "TemporalTerminalObserverEvidence(waited_ms=" + string temporalEvidence.waitedMs
                + "|repeat=" + string temporalEvidence.repeat
                + "|liveness=" + livenessText
                + "|bridge=" + bridgeText
                + "|terminal_action=" + terminalActionText
                + ")"
            match outcome with
            | NativePromiseTerminalClosedNoFurther(_, _, witness) when topologyWitnessIsFresh witness ->
                NativePromiseTerminalCommitDeferredFreshTopologyWitness(outcome, witness, authority)
            | _ ->
                match nativeRootCompleteArmFor outcome authority with
                | NativeRootCompleteObserverOnly(reason, _) ->
                    let reasonText = CompilerKernelV2.OperationalReasonIdOps.text reason
                    NativePromiseTerminalCommitNotRequested(
                        CompilerKernelV2.OperationalReasonIdOps.create (reasonText + "|" + observerText))
                | NativeRootCompleteRejectedPhase(reason, rejectedAuthority) ->
                    let reasonText = CompilerKernelV2.OperationalReasonIdOps.text reason
                    match rejectedAuthority with
                    | LiveGraphDeadlockedState _ ->
                        NativePromiseTerminalCommitRejectedDeadlockObserverOnly(
                            outcome,
                            rejectedAuthority,
                            NativeTerminalActionSuppressionDeadlockObserverOnly(
                                CompilerKernelV2.OperationalReasonIdOps.create (reasonText + "|" + observerText)))
                    | _ ->
                        NativePromiseTerminalCommitDeferredLiveGraph(outcome, rejectedAuthority)
                | NativeRootCompleteRejectedOwners(reason, ledger) ->
                    NativePromiseTerminalCommitBlockedByOpenOwners(
                        outcome,
                        authority,
                        ledger,
                        NativeTerminalActionSuppressionOpenOwners(
                            CompilerKernelV2.OperationalReasonIdOps.create (
                                CompilerKernelV2.OperationalReasonIdOps.text reason + "|" + observerText)))
                | NativeRootCompleteRejectedPrerequisites(reason, prerequisiteVerdict) ->
                    let reasonText = CompilerKernelV2.OperationalReasonIdOps.text reason
                    match prerequisiteVerdict with
                    | TerminalClosurePrerequisitesBlockedByWorkDag(ledger, blockReason) ->
                        match ledger.workDagVerdict with
                        | WorkDagTerminalClosureBlocked(workDag, _, detailedReason) ->
                            NativePromiseTerminalCommitBlockedByWorkDagAuthority(
                                outcome,
                                authority,
                                workDag,
                                NativeTerminalActionSuppressionWorkDagAuthority detailedReason)
                        | WorkDagTerminalClosureAllowed workDag ->
                            NativePromiseTerminalCommitBlockedByWorkDagAuthority(
                                outcome,
                                authority,
                                workDag,
                                NativeTerminalActionSuppressionWorkDagAuthority blockReason)
                    | TerminalClosurePrerequisitesBlockedByOwners(ledger, blockReason)
                    | TerminalClosurePrerequisitesNeedDeadlockResolution(ledger, blockReason) ->
                        match ledger.ownerVerdict with
                        | TypedTerminalOwnersAllClosed ownerLedger ->
                            NativePromiseTerminalCommitBlockedByOpenOwners(
                                outcome,
                                authority,
                                ownerLedger,
                                NativeTerminalActionSuppressionOpenOwners blockReason)
                        | TypedTerminalOwnersStillOpen(ownerLedger, openKinds)
                        | TypedTerminalOwnersNeedDeadlockResolution(ownerLedger, openKinds) ->
                            NativePromiseTerminalCommitBlockedByOpenOwners(
                                outcome,
                                authority,
                                ownerLedger,
                                NativeTerminalActionSuppressionOpenOwners blockReason)
                    | TerminalClosurePrerequisitesBlockedBySchedulerCausality(ledger, blockReason) ->
                        match ledger.schedulerVerdict with
                        | SchedulerCausalityClosed scheduler ->
                            NativePromiseTerminalCommitBlockedBySchedulerCausality(
                                outcome,
                                authority,
                                scheduler,
                                NativeTerminalActionSuppressionSchedulerCausality blockReason)
                        | SchedulerCausalityOpen(scheduler, detailedReason)
                        | SchedulerCausalityDebtObserved(scheduler, detailedReason) ->
                            NativePromiseTerminalCommitBlockedBySchedulerCausality(
                                outcome,
                                authority,
                                scheduler,
                                NativeTerminalActionSuppressionSchedulerCausality detailedReason)
                    | TerminalClosurePrerequisitesBlockedByBreakthroughQuorum(ledger, blockReason) ->
                        match ledger.breakthroughVerdict with
                        | BreakthroughTerminalReady quorum ->
                            NativePromiseTerminalCommitBlockedByBreakthroughQuorum(
                                outcome,
                                authority,
                                quorum,
                                NativeTerminalActionSuppressionBreakthroughQuorum blockReason)
                        | BreakthroughTerminalBlocked(quorum, detailedReason) ->
                            NativePromiseTerminalCommitBlockedByBreakthroughQuorum(
                                outcome,
                                authority,
                                quorum,
                                NativeTerminalActionSuppressionBreakthroughQuorum detailedReason)
                    | TerminalClosurePrerequisitesSatisfied _ ->
                        NativePromiseTerminalCommitDeferredTypedTerminalGate(
                            outcome,
                            authority,
                            temporalEvidence,
                            NativeTerminalActionSuppressionGateDecision(
                                CompilerKernelV2.OperationalReasonIdOps.create (reasonText + "|" + observerText)))
                | NativeRootCompleteArmedByTerminalProof proof ->
                    match outcome with
                    | NativePromiseTerminalFailedSemantic(promiseId, _, payloadClass) ->
                        NativePromiseTerminalCommitAllowedSemanticFailure(
                            semanticFailureId,
                            promiseId,
                            payloadClass,
                            graph,
                            proof)
                    | NativePromiseTerminalClosedNoFurther(promiseId, reason, _) ->
                        NativePromiseTerminalCommitAllowedNoFurther(
                            nativePromiseTerminalOutcomeId outcome,
                            promiseId,
                            reason,
                            graph,
                            proof)
                    | NativePromiseTerminalResolvedMaterial(promiseId, _) ->
                        NativePromiseTerminalCommitAllowedResolvedMaterial(
                            promiseId,
                            graph,
                            proof)
                    | NativePromiseTerminalObserverOnly(_, reason) ->
                        NativePromiseTerminalCommitNotRequested(CompilerKernelV2.OperationalReasonIdOps.create ("observer_only:" + CompilerKernelV2.OperationalReasonIdOps.text reason))

        let nativePromiseOutcomeLedgerAdvanceText = function
            | NativePromiseOutcomeResolvedDelta(_, facts) when facts > 0L -> "RootFrontierAdvancedByNativePromiseDelta(facts=" + string facts + ")"
            | NativePromiseOutcomeFailedPlateau(_, _) -> "PendingLedgerClosedByNativePromiseFailedPlateau"
            | NativePromiseOutcomeFailedCycle(_, _) -> "PendingLedgerClosedByNativePromiseFailedCycle"
            | NativePromiseOutcomeNoFurther(_, reason) -> "PendingLedgerClosedByNoFurther(reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | NativePromiseOutcomeResolvedDelta(_, _) -> "PendingLedgerHealthyNoChange(zero_fact_delta_rejected)"
            | NativePromiseOutcomeObserverOnly(_, reason) -> "NoAdvanceBecauseObserverOnly(reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let nativePromiseOutcomeTransitionText closureId beforeState outcome =
            let afterState =
                match outcome with
                | NativePromiseOutcomeResolvedDelta(_, facts) -> "frontier_advanced(delta_facts=" + string facts + "|closure=" + closureId + ")"
                | NativePromiseOutcomeFailedPlateau(_, payload) -> "promise_failed_plateau(closure=" + closureId + "|payload=" + payload + ")"
                | NativePromiseOutcomeFailedCycle(_, payload) -> "promise_failed_cycle(closure=" + closureId + "|payload=" + payload + ")"
                | NativePromiseOutcomeNoFurther(_, reason) -> "no_further_delta_declared(closure=" + closureId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
                | NativePromiseOutcomeObserverOnly(_, reason) -> "observer_only_no_state_change(closure=" + closureId + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            beforeState + "->" + afterState

        type NativeMonadicPoisonPropagationId =
            | NativePoisonPropagatedToPromiseFailure of promiseId:string * payload:string * wrapper:string
            | NativePoisonBlockedLegacyUnitCast of wrapper:string * payload:string
            | NativePoisonNotPresent of wrapper:string

        let nativeMonadicPoisonPropagationText = function
            | NativePoisonPropagatedToPromiseFailure(promiseId, payload, wrapper) -> "PoisonPropagated(wrapper=" + wrapper + "|promise=" + promiseId + "|payload=" + payload + ")"
            | NativePoisonBlockedLegacyUnitCast(wrapper, payload) -> "PoisonBlockedLegacyUnitCast(wrapper=" + wrapper + "|payload=" + payload + ")"
            | NativePoisonNotPresent wrapper -> "NoPoison(wrapper=" + wrapper + ")"

        let nativeMonadicPoisonPropagationFor promiseId wrapper astDeltaId =
            match astDeltaId with
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, _, _) -> NativePoisonNotPresent wrapper
            | NativeAstDeltaCyclePoisonInjected payload -> NativePoisonPropagatedToPromiseFailure(promiseId, payload, wrapper)
            | NativeAstDeltaSemanticPlateauPoison(contract, kind, reason) -> NativePoisonPropagatedToPromiseFailure(promiseId, nativeDirectEvaluationSemanticPlateauPayload contract kind reason, wrapper)
            | NativeAstDeltaExecutePureAstStep contract ->
                match nativeDirectEvaluationSemanticPlateauKind contract with
                | Some _ -> NativePoisonBlockedLegacyUnitCast(wrapper, nativeDirectEvaluationContractText contract)
                | None -> NativePoisonNotPresent wrapper
            | _ -> NativePoisonNotPresent wrapper

        let nativeFailedAstFactText directContractId semanticFactCount blocker =
            match nativeDirectEvaluationSemanticStateFor directContractId semanticFactCount with
            | NativeDirectEvaluationSemanticFactsAvailablePlateauCapable _
            | NativeDirectEvaluationSemanticFactsAvailableWithoutPlateauAuthority _ -> "None"
            | NativeDirectEvaluationSemanticFactsAbsentPlateauCapable kind ->
                "FailedFact(kind=" + nativeClosureKindText kind + "|contract=" + nativeDirectEvaluationContractText directContractId + "|blocker=" + blocker + ")"
            | NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority ->
                "FailedFact(unknown_contract|contract=" + nativeDirectEvaluationContractText directContractId + "|blocker=" + blocker + ")"

        let nativeNoFurtherDeltaRootCauseText astDeltaId =
            match astDeltaId with
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, kind, reason) -> "PureTopologyWitnessMaterialized|" + nativeClosureKindText kind + "|" + nativePureTopologyWitnessReasonText reason
            | NativeAstDeltaCyclePoisonInjected _ -> "PoisonPayloadReturned"
            | NativeAstDeltaSemanticPlateauPoison(_, _, reason) -> "StarvationThreshold|" + nativeSemanticPlateauPoisonReasonText reason
            | NativeAstDeltaMeasuredCounterDelta
            | NativeAstDeltaExecutePureAstStep _ -> "ConsumerClosedDeltaContract"
            | NativeAstDeltaBlockedLegacyFallback _ -> "GraftDebtNoDeltaAfterForcedConsumer"
            | NativeAstDeltaNoContractLegacyForbidden -> "NoDirectEvalContract"

        let nativeLedgerAdvanceResultText semanticFactCount astDeltaId =
            match astDeltaId with
            | NativeAstDeltaMeasuredCounterDelta
            | NativeAstDeltaExecutePureAstStep _ when semanticFactCount > 0L -> "RootFrontierAdvanced"
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, kind, _) when semanticFactCount > 0L -> "RootFrontierAdvancedByPureTopologyWitness(kind=" + nativeClosureKindText kind + "|facts=" + string semanticFactCount + ")"
            | NativeAstDeltaPureTopologyWitnessMaterialized(_, kind, _) -> "PendingLedgerHealthyPureTopologyWitnessZeroFact(kind=" + nativeClosureKindText kind + ")"
            | NativeAstDeltaCyclePoisonInjected _
            | NativeAstDeltaSemanticPlateauPoison(_, _, _) -> "NoFurtherDeltaAdvancedByPoison"
            | NativeAstDeltaBlockedLegacyFallback _
            | NativeAstDeltaNoContractLegacyForbidden -> "NoAdvanceBecauseObserverOnly"
            | _ -> "PendingLedgerHealthyNoChange"

        let nativeExpectedVsActualDeltaAfterForcedConsumerText expectedDeltaId consumerDeltaId astDeltaId =
            let expectedText = nativeWakeExpectedDeltaText expectedDeltaId
            let consumerText = nativeWakeConsumerDeltaResultText consumerDeltaId
            let actualText = nativeAstEvaluationDeltaResultText astDeltaId
            "expected=" + expectedText + "|consumer=" + consumerText + "|actual=" + actualText

        let nativeCycleBreakAlgebraicPayloadText payloadEnvelopeId structuralCycleId =
            match payloadEnvelopeId, structuralCycleId with
            | NativeWakePayloadCyclePoison(payload, witness, edge), _ -> "CyclePoison(payload=" + payload + "|witness=" + witness + "|edge=" + edge + ")"
            | NativeWakePayloadResolution(payload, witness, edge), NativeStructuralCycleDirectWakeReentry(node, reentryEdge) -> "CyclePoison(payload=CyclePoison(depth=direct_wake_reentry|node=" + node + "|edge=" + reentryEdge + "|payload=" + payload + "|witness=" + witness + "|source_edge=" + edge + ")|action=resolve_current_promise_no_requeue)"
            | NativeWakePayloadResolution(payload, witness, edge), _ -> "ResolutionPayload(payload=" + payload + "|witness=" + witness + "|edge=" + edge + ")"
            | NativeWakePayloadDummyUnit(witness, edge), _ -> "DummyUnitPayload(witness=" + witness + "|edge=" + edge + ")"
            | NativeWakePayloadMissing witness, _ -> "MissingPayload(witness=" + witness + ")"

        let nativePromiseResolutionLatticeText promiseId payloadEnvelopeId continuationTargets astDeltaId =
            "IVar(" + promiseId + ") filled_with=" + nativeWakePayloadEnvelopeText payloadEnvelopeId + " -> unblocks=" + continuationTargets + " -> ast_delta=" + nativeAstEvaluationDeltaResultText astDeltaId

        let nativeWakeContinuationTargetStatusText = function
            | NativeWakeTargetApplySpineStore -> "apply_spine_store_direct"
            | NativeWakeTargetPendingGraphTerminal -> "pending_graph_terminal"
            | NativeWakeTargetPendingGraphCommittedTerminal -> "pending_graph_committed_terminal"
            | NativeWakeTargetCooperativeReplayNativeBind -> "cooperative_replay_native_bind"
            | NativeWakeTargetParentReplayStatusPreservedCacheHandoff -> "parent_replay_status_preserved_cache_handoff"
            | NativeWakeTargetIdleCrossKindSidecarCallback -> "idle_cross_kind_sidecar_callback"
            | NativeWakeTargetDynamicJoinStackFenceBridge -> "dynamic_join_stack_fence_bridge"
            | NativeWakeTargetDynamicJoinBridgeTailHandoff -> "dynamic_join_bridge_tail_handoff"
            | NativeWakeTargetObservedPinnedImmediateFill -> "observed_pinned_immediate_fill"
            | NativeWakeTargetDynamicBridge -> "dynamic_bridge_parent_continuation"
            | NativeWakeTargetDynamicJoinReplay -> "dynamic_join_apply_replay"
            | NativeWakeTargetWriterlessQueueDrain -> "writerless_queue_drain"
            | NativeWakeTargetObservedPinnedTerminal -> "observed_pinned_terminal"
            | NativeWakeTargetSemanticStaleRetarget -> "semantic_stale_retarget"
            | NativeWakeTargetRunnableParentContinuation -> "runnable_parent_continuation"
            | NativeWakeTargetWaitingCrossKind -> "waiting_cross_kind"
            | NativeWakeTargetSidecarDrain -> "sidecar_drain"
            | NativeWakeTargetPoisoned -> "poisoned"
            | NativeWakeTargetUnknown -> "unknown"

        let nativeCallStackHopacText directContractId continuationStatusId astDeltaId =
            "[Job.bind:" + nativeWakeContinuationTargetStatusText continuationStatusId + "]->[" + nativeDirectEvaluationContractText directContractId + "]->[" + nativeAstEvaluationDeltaResultText astDeltaId + "]"

        let nativeCallbackReturnFor graftStatusId consumerDeltaId directContractId semanticFactCount =
            let semanticState = nativeDirectEvaluationSemanticStateFor directContractId semanticFactCount
            match graftStatusId, consumerDeltaId, directContractId, semanticState with
            | _, NativeWakeConsumerDeltaProduced, _, NativeDirectEvaluationSemanticFactsAvailablePlateauCapable _
            | _, NativeWakeConsumerDeltaProduced, _, NativeDirectEvaluationSemanticFactsAvailableWithoutPlateauAuthority _ -> NativeCallbackReturnResolveParentPromise
            | _, NativeWakeConsumerDeltaPureAstStep, _, NativeDirectEvaluationSemanticFactsAvailablePlateauCapable _
            | _, NativeWakeConsumerDeltaPureAstStep, _, NativeDirectEvaluationSemanticFactsAvailableWithoutPlateauAuthority _ -> NativeCallbackReturnExecuteDirectAstEval
            | _, NativeWakeConsumerDeltaForcedDirectEval, _, NativeDirectEvaluationSemanticFactsAvailablePlateauCapable _
            | _, NativeWakeConsumerDeltaForcedDirectEval, _, NativeDirectEvaluationSemanticFactsAvailableWithoutPlateauAuthority _ -> NativeCallbackReturnExecuteDirectAstEval
            | _, NativeWakeConsumerDeltaExpectedButDeferred, _, NativeDirectEvaluationSemanticFactsAvailablePlateauCapable _
            | _, NativeWakeConsumerDeltaExpectedButDeferred, _, NativeDirectEvaluationSemanticFactsAvailableWithoutPlateauAuthority _ -> NativeCallbackReturnExecuteDirectAstEval
            | _, NativeWakeConsumerDeltaProduced, _, NativeDirectEvaluationSemanticFactsAbsentPlateauCapable _ -> NativeCallbackReturnPlateauPoison
            | _, NativeWakeConsumerDeltaPureAstStep, _, NativeDirectEvaluationSemanticFactsAbsentPlateauCapable _ -> NativeCallbackReturnPlateauPoison
            | _, NativeWakeConsumerDeltaForcedDirectEval, _, NativeDirectEvaluationSemanticFactsAbsentPlateauCapable _ -> NativeCallbackReturnPlateauPoison
            | _, NativeWakeConsumerDeltaExpectedButDeferred, _, NativeDirectEvaluationSemanticFactsAbsentPlateauCapable _ -> NativeCallbackReturnPlateauPoison
            | NativeWakeParentJobBindGraftPendingForceReplay, _, _, NativeDirectEvaluationSemanticFactsAbsentPlateauCapable _ -> NativeCallbackReturnPlateauPoison
            | NativeWakeParentJobBindGraftPendingForceReplay, _, _, NativeDirectEvaluationSemanticFactsAvailableWithoutPlateauAuthority _
            | NativeWakeParentJobBindGraftPendingForceReplay, _, _, NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority -> NativeCallbackReturnForceGraftRepair
            | _, NativeWakeConsumerDeltaProduced, _, NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority -> NativeCallbackReturnResolveParentPromise
            | _, NativeWakeConsumerDeltaPureAstStep, NativeDirectEvaluationNoContract, NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority -> NativeCallbackReturnForbiddenLegacyWorklist
            | _, NativeWakeConsumerDeltaPureAstStep, _, NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority -> NativeCallbackReturnExecuteDirectAstEval
            | _, NativeWakeConsumerDeltaForcedDirectEval, NativeDirectEvaluationNoContract, NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority -> NativeCallbackReturnForbiddenLegacyWorklist
            | _, NativeWakeConsumerDeltaForcedDirectEval, _, NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority -> NativeCallbackReturnExecuteDirectAstEval
            | _, NativeWakeConsumerDeltaExpectedButDeferred, NativeDirectEvaluationNoContract, NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority -> NativeCallbackReturnForbiddenLegacyWorklist
            | _, NativeWakeConsumerDeltaExpectedButDeferred, _, NativeDirectEvaluationSemanticFactsAbsentWithoutPlateauAuthority -> NativeCallbackReturnExecuteDirectAstEval
            | _, _, NativeDirectEvaluationNoContract, _ -> NativeCallbackReturnForbiddenLegacyWorklist
            | _ -> NativeCallbackReturnNoFurtherDelta

        type NativeCallbackExecutionPlanId =
            | NativeCallbackPlanReturnNoFurtherDelta of payload:NativeWakePayloadEnvelopeId
            | NativeCallbackPlanPlateauPoison of contract:NativeDirectEvaluationContractId * payload:NativeWakePayloadEnvelopeId * shape:NativeWakeGraphShapeId
            | NativeCallbackPlanRunDirectAstEval of contract:NativeDirectEvaluationContractId * payload:NativeWakePayloadEnvelopeId * shape:NativeWakeGraphShapeId
            | NativeCallbackPlanResolveParentPromise of payload:NativeWakePayloadEnvelopeId * shape:NativeWakeGraphShapeId
            | NativeCallbackPlanForceParentGraftRepair of payload:NativeWakePayloadEnvelopeId * shape:NativeWakeGraphShapeId
            | NativeCallbackPlanRejectLegacyReturn of payload:NativeWakePayloadEnvelopeId

        let nativeCallbackExecutionPlanFor callbackReturnId directContractId payloadEnvelopeId wakeShapeId =
            // MIGRATION: payload text is render-only.  The direct contract must be supplied
            // by typed wake/consumer routing; do not infer execution authority with
            // substring probing, because that is exactly how poison was swallowed by
            // successful NativePromiseResult-looking wrappers.
            let directContractId = directContractId
            match callbackReturnId, directContractId with
            | NativeCallbackReturnPlateauPoison, _ -> NativeCallbackPlanPlateauPoison(directContractId, payloadEnvelopeId, wakeShapeId)
            | NativeCallbackReturnExecuteDirectAstEval, NativeDirectEvaluationNoContract -> NativeCallbackPlanRejectLegacyReturn payloadEnvelopeId
            | NativeCallbackReturnExecuteDirectAstEval, _ -> NativeCallbackPlanRunDirectAstEval(directContractId, payloadEnvelopeId, wakeShapeId)
            | NativeCallbackReturnResolveParentPromise, _ -> NativeCallbackPlanResolveParentPromise(payloadEnvelopeId, wakeShapeId)
            | NativeCallbackReturnForceGraftRepair, _ -> NativeCallbackPlanForceParentGraftRepair(payloadEnvelopeId, wakeShapeId)
            | NativeCallbackReturnForbiddenLegacyWorklist, _ -> NativeCallbackPlanRejectLegacyReturn payloadEnvelopeId
            | NativeCallbackReturnNoFurtherDelta, NativeDirectEvaluationNoContract -> NativeCallbackPlanReturnNoFurtherDelta payloadEnvelopeId
            | NativeCallbackReturnNoFurtherDelta, _ -> NativeCallbackPlanRunDirectAstEval(directContractId, payloadEnvelopeId, wakeShapeId)

        let nativeCallbackExecutionPlanText = function
            | NativeCallbackPlanReturnNoFurtherDelta(payload) -> "plan_return_native_promise_result(payload=" + nativeWakePayloadEnvelopeText payload + ")"
            | NativeCallbackPlanPlateauPoison(contract, payload, shape) -> "plan_return_plateau_poison(contract=" + nativeDirectEvaluationContractText contract + "|payload=" + nativeWakePayloadEnvelopeText payload + "|shape=" + nativeWakeGraphShapeText shape + ")"
            | NativeCallbackPlanRunDirectAstEval(contract, payload, shape) -> "plan_execute_direct_ast_eval(contract=" + nativeDirectEvaluationContractText contract + "|payload=" + nativeWakePayloadEnvelopeText payload + "|shape=" + nativeWakeGraphShapeText shape + ")"
            | NativeCallbackPlanResolveParentPromise(payload, shape) -> "plan_resolve_parent_promise(payload=" + nativeWakePayloadEnvelopeText payload + "|shape=" + nativeWakeGraphShapeText shape + ")"
            | NativeCallbackPlanForceParentGraftRepair(payload, shape) -> "plan_force_parent_graft_repair(payload=" + nativeWakePayloadEnvelopeText payload + "|shape=" + nativeWakeGraphShapeText shape + ")"
            | NativeCallbackPlanRejectLegacyReturn(payload) -> "plan_reject_legacy_worklist_return(payload=" + nativeWakePayloadEnvelopeText payload + ")"

        type NoWorkAbortOverrideReasonId =
            | NoWorkAbortOverrideNone
            | NoWorkAbortOverrideNativeParentJobBindGraftDebt
            | NoWorkAbortOverrideBoundWakeExpectedDelta
            | NoWorkAbortOverrideProofTupleCompleteRecycle

        let noWorkAbortOverrideReasonText = function
            | NoWorkAbortOverrideNone -> "none"
            | NoWorkAbortOverrideNativeParentJobBindGraftDebt -> "native_parent_job_bind_graft_debt"
            | NoWorkAbortOverrideBoundWakeExpectedDelta -> "bound_wake_expected_delta"
            | NoWorkAbortOverrideProofTupleCompleteRecycle -> "proof_tuple_complete_recycle_not_abort"

        let noWorkAbortOverrideReasonFor nativeParentJobBindHoldoff expectedDeltaId proofTupleComplete =
            if nativeParentJobBindHoldoff then NoWorkAbortOverrideNativeParentJobBindGraftDebt
            elif nativeWakeExpectedDeltaFlag expectedDeltaId then NoWorkAbortOverrideBoundWakeExpectedDelta
            elif proofTupleComplete then NoWorkAbortOverrideProofTupleCompleteRecycle
            else NoWorkAbortOverrideNone

        let nativeWakeContinuationTargetStatusFor (targets: NativeWakeContinuationTargets) =
            if NativeWakeContinuationTargets.has NativeWakeContinuationParentReplayPoison targets then NativeWakeTargetPoisoned
            elif NativeWakeContinuationTargets.has NativeWakeContinuationApplySpineStore targets then NativeWakeTargetApplySpineStore
            elif NativeWakeContinuationTargets.has NativeWakeContinuationCooperativeReplayNativeBind targets then NativeWakeTargetCooperativeReplayNativeBind
            elif NativeWakeContinuationTargets.has NativeWakeContinuationParentReplayStatusPreservedCacheHandoff targets then NativeWakeTargetParentReplayStatusPreservedCacheHandoff
            elif NativeWakeContinuationTargets.has NativeWakeContinuationIdleCrossKindSidecar targets then NativeWakeTargetIdleCrossKindSidecarCallback
            elif NativeWakeContinuationTargets.has NativeWakeContinuationDynamicJoinStackFenceBridge targets then NativeWakeTargetDynamicJoinStackFenceBridge
            elif NativeWakeContinuationTargets.has NativeWakeContinuationDynamicJoinBridgeTailHandoff targets then NativeWakeTargetDynamicJoinBridgeTailHandoff
            elif NativeWakeContinuationTargets.has NativeWakeContinuationObservedPinnedImmediateFill targets then NativeWakeTargetObservedPinnedImmediateFill
            elif NativeWakeContinuationTargets.has NativeWakeContinuationPendingGraphCommittedTerminal targets then NativeWakeTargetPendingGraphCommittedTerminal
            elif NativeWakeContinuationTargets.has NativeWakeContinuationPendingGraphTerminal targets then NativeWakeTargetPendingGraphTerminal
            elif NativeWakeContinuationTargets.has NativeWakeContinuationDynamicBridgeParent targets then NativeWakeTargetDynamicBridge
            elif NativeWakeContinuationTargets.has NativeWakeContinuationDynamicJoinReplay targets then NativeWakeTargetDynamicJoinReplay
            elif NativeWakeContinuationTargets.has NativeWakeContinuationWriterlessQueueDrain targets then NativeWakeTargetWriterlessQueueDrain
            elif NativeWakeContinuationTargets.has NativeWakeContinuationObservedPinnedParent targets then NativeWakeTargetObservedPinnedTerminal
            elif NativeWakeContinuationTargets.has NativeWakeContinuationSemanticStaleRetarget targets then NativeWakeTargetSemanticStaleRetarget
            elif NativeWakeContinuationTargets.has NativeWakeContinuationCrossKindSiblingReplay targets then NativeWakeTargetWaitingCrossKind
            elif NativeWakeContinuationTargets.has NativeWakeContinuationTySidecarDrain targets then NativeWakeTargetSidecarDrain
            elif NativeWakeContinuationTargets.has NativeWakeContinuationParentContinuationCell targets then NativeWakeTargetRunnableParentContinuation
            else NativeWakeTargetUnknown

        let nativeWakePayloadProbeText payload witness edge =
            "payload=" + payload + "|witness=" + witness + "|edge=" + edge

        let metronomeTerminalAuthorityTopologicalDisconnectProbeId authority targetKey =
            let targetIdentity =
                NativeWakeTargetIdentity.create targetKey (wakeSanitizeTargetKey targetKey)
            let targetIdentityState = NativeWakeTargetIdentity.state targetIdentity
            let sanitizedTargetKey = NativeWakeTargetIdentity.sanitizedText targetIdentity
            let targets = metronomeTerminalAuthorityContinuationTargets authority sanitizedTargetKey
            match targetIdentityState with
            | NativeWakeTargetIdentityFrontierUnknown
            | NativeWakeTargetIdentityErased ->
                NativeWakeDisconnectUnboundOrErasedIdentity
            | NativeWakeTargetIdentityAvailable when NativeWakeContinuationTargets.hasUnknownOwner targets ->
                NativeWakeDisconnectPartialOwnerIdentityRequiresParentBindProbe
            | NativeWakeTargetIdentityAvailable ->
                NativeWakeDisconnectStructuralContinuationTargets

        let metronomeTerminalAuthorityContinuationBindingCount authority targetKey =
            match metronomeTerminalAuthorityTopologicalDisconnectProbeId authority targetKey with
            | NativeWakeDisconnectUnboundOrErasedIdentity -> 0
            | _ ->
                metronomeTerminalAuthorityContinuationTargets authority targetKey
                |> NativeWakeContinuationTargets.bindingCount

        let metronomeTerminalAuthorityWakeGraphBindingStateId authority targetKey =
            match metronomeTerminalAuthorityTopologicalDisconnectProbeId authority targetKey with
            | NativeWakeDisconnectUnboundOrErasedIdentity -> NativeWakeUnboundTopologicalIsland
            | NativeWakeDisconnectPartialOwnerIdentityRequiresParentBindProbe -> NativeWakePartialOwnerIdentityParentBindProbeRequired
            | _ -> NativeWakeBoundParentContinuationTargets

        let metronomeTerminalAuthorityWakeGraphBindingStateText authority targetKey =
            metronomeTerminalAuthorityWakeGraphBindingStateId authority targetKey |> nativeWakeBindingStateText

        let metronomeTerminalAuthorityWakeGraphNativeFateText authority targetKey =
            metronomeTerminalAuthorityWakeGraphBindingStateId authority targetKey |> nativeWakeFateText

        let metronomeTerminalAuthorityWakeGraphText authority targetKey =
            let nodeId = metronomeTerminalAuthorityStructuralNodeIdText authority targetKey
            "IVar[Node:" + nodeId + "] filled -> Unblocked Continuations: " + metronomeTerminalAuthorityContinuationBindingTargetsText authority targetKey

        let metronomeTerminalAuthorityTopologicalDisconnectProbeText authority targetKey =
            metronomeTerminalAuthorityTopologicalDisconnectProbeId authority targetKey
            |> nativeWakeTopologicalDisconnectText

        let metronomeTerminalAuthorityIsHandoffWindow (_: MetronomeTerminalAuthorityId) = true

        // MIGRATION MIGRATION : no-work scheduling may receive display
        // progress as telemetry, but all control gates below are derived from
        // replay/root/terminal/semantic receipts and bounded no-work evidence.
        type TypedNoWorkDisplayProjectionBandId =
            | TypedNoWorkBandPct95To995
            | TypedNoWorkBandPct80To95
            | TypedNoWorkBandPct70To95
            | TypedNoWorkBandPct60To95
            | TypedNoWorkBandPct95
            | TypedNoWorkBandDisabledDeadman

        let typedNoWorkDisplayProjectionQuarantined (_band:TypedNoWorkDisplayProjectionBandId) (_progressPct:float) = true
        let typedNoWorkMidDrainControl replayProgress rootComplete terminalSignals =
            replayProgress >= 512L || rootComplete >= 4L || terminalSignals >= 4L
        let typedNoWorkLateDrainControl semanticReceipts replayProgress rootComplete terminalSignals =
            terminalSignals >= 120L || rootComplete >= 60L || replayProgress >= 8000L || semanticReceipts >= 256L
        let typedNoWorkVerdictImminentControl rootComplete terminalSignals =
            terminalSignals >= 512L && rootComplete >= 48L

        let metronomeNoWorkSaturationDecisionFor noWorkS progressPct noWorkPokes rescueCompleted rescueGateBusy richInFlight richBusyMs richAgeMs sampledWork semanticReceipts replayProgress rootComplete terminalSignals physicalHandoffs parentEnqueueDebt sampledDelta replayDelta rootDelta terminalDelta =
            let hasLiveHistory =
                sampledWork > 0L
                && (replayProgress > 0L || rootComplete > 0L || terminalSignals > 0L)
            let noFreshDelta =
                sampledDelta <= 0L
                && replayDelta <= 0L
                && rootDelta <= 0L
                && terminalDelta <= 0L
            let midDrainControl = hasLiveHistory && typedNoWorkMidDrainControl replayProgress rootComplete terminalSignals
            let lateDrainControl = hasLiveHistory && typedNoWorkLateDrainControl semanticReceipts replayProgress rootComplete terminalSignals
            let verdictImminentControl = hasLiveHistory && typedNoWorkVerdictImminentControl rootComplete terminalSignals
            let lateLiveReplayDrainGrace =
                hasLiveHistory
                && noFreshDelta
                && typedNoWorkDisplayProjectionQuarantined TypedNoWorkBandPct95To995 progressPct
                && lateDrainControl
                && noWorkS >= 12L
                && noWorkS < 75L
                && noWorkPokes >= 6L
                && rescueCompleted >= 80L
                && rescueGateBusy < 8L
                && replayProgress > 0L
                && (rootComplete > 0L || terminalSignals > 0L)
            let midCapReplayDrainGrace =
                // MIGRATION: 1216 aborted at 89.11% after only an 11s no-work
                // window with replay/root/terminal history still present.  This is
                // too early for a fail-closed abort: give the replay drain a bounded
                // grace window before gate-busy evidence can become terminal.
                hasLiveHistory
                && noFreshDelta
                && typedNoWorkDisplayProjectionQuarantined TypedNoWorkBandPct80To95 progressPct
                && midDrainControl
                && noWorkS >= 8L
                && noWorkS < 45L
                && noWorkPokes >= 4L
                && noWorkPokes < 28L
                && rescueCompleted >= 32L
                && rescueCompleted < 160L
                && replayProgress > 0L
                && (rootComplete > 0L || terminalSignals > 0L)
            let richBusyReplayDrainGrace =
