                // receipts plus replay debt as a protected drain state, not as
                // semantic inactivity.
                hasLiveHistory
                && noFreshDelta
                && physicalHandoffs > 0L
                && (parentEnqueueDebt > 0L || replayProgress > 0L)
                && noWorkS >= 8L
                && noWorkS < 90L
                && rescueCompleted < 192L
            let hardSemanticQuarantineLiveTailGrace =
                // MIGRATION: assessment reread still had one open authority gap: a
                // correctly pinned hard semantic terminal must not force sibling or
                // parent live tails into generic no-work abort/deferral while replay,
                // root or terminal evidence is still present.  Quarantine the terminal
                // and ask the next log for explicit no_work_deferral_reason_du instead.
                hasLiveHistory
                && noFreshDelta
                && typedNoWorkDisplayProjectionQuarantined TypedNoWorkBandPct70To95 progressPct
                && midDrainControl
                && replayProgress >= 512L
                && (rootComplete > 0L || terminalSignals > 0L)
                && noWorkS >= 12L
                && noWorkS < 60L
                && noWorkPokes >= 6L
                && rescueCompleted < 256L
                && (snapshotKindCount "eval_worklist_error_type_message_ready" > 0
                    || snapshotKindCount "eval_worklist_apply_function_body_part_eval_type_error_terminal_preserved" > 0
                    || snapshotKindCount "eval_worklist_terminal_contract_pinned_from_status" > 0
                    || snapshotKindCount "eval_worklist_bigstack_missing_after_prefetch_handoff_decision" > 0
                    || snapshotKindCount "eval_worklist_bigstack_missing_after_prefetch_terminal_deferred_for_live_replay" > 0
                    || snapshotKindCount "eval_worklist_stack_fence_prefetch_ledger_audit" > 0
                    || snapshotKindCount "eval_worklist_bigstack_concrete_op_terminal_deferred_for_live_replay" > 0)
            let finalQueueSparseReplayTickQuorumGrace =
