                hasLiveHistory
                && noFreshDelta
                && typedNoWorkDisplayProjectionQuarantined TypedNoWorkBandPct60To95 progressPct
                && midDrainControl
                && replayProgress >= 512L
                && rootComplete >= 4L
                && terminalSignals >= 4L
                && noWorkS >= 45L
                && noWorkS < 150L
                && noWorkPokes >= 12L
                && noWorkPokes < 96L
                && rescueCompleted >= 8L
                && rescueCompleted < 128L
                && rescueGateBusy < 96L
            let finalQueueActiveDriverRootProbeGrace =
                // MIGRATION: MIGRATION reached q/a/p=57/4/0 with roots=8,
