                terminalFloodQuietAbort
                && typedNoWorkDisplayProjectionQuarantined TypedNoWorkBandPct80To95 progressPct
                && midDrainControl
                && replayProgress >= 3000L
                && rootComplete >= 120L
                && terminalSignals >= 256L
                && noWorkS < 24L
                && noWorkPokes < 12L
                && rescueCompleted < 320L
                && (snapshotKindCount "eval_worklist_cross_kind_yield_thrash_hard_poison" > 0
                    || snapshotKindCount "eval_worklist_parent_replay_poison_stale_pending_witness_force_surface" > 0
                    || snapshotKindCount "eval_worklist_terminal_poison_cascade" > 0)
            let terminalFloodDynamicRecordKeyGrace =
