                && typedNoWorkDisplayProjectionQuarantined TypedNoWorkBandPct80To95 progressPct
                && midDrainControl
                && replayProgress >= 8000L
                && rootComplete >= 40L
                && terminalSignals >= 80L
                && noWorkS >= 60L
                && noWorkPokes >= 8L
                && rescueCompleted >= 8L
                && snapshotKindCount "eval_worklist_stack_fence_hopac_override_pierced_repeat_cap" >= 64
                && (snapshotKindCount "eval_worklist_parent_poison_hopac_override_pierced_live_tail" > 0
                    || snapshotKindCount "eval_worklist_parent_replay_cycle_break_poison_live_tail_override_deferred" > 0
                    || snapshotKindCount "eval_worklist_cross_kind_yield_thrash_hard_poison" > 0)
