                && noFreshDelta
                && typedNoWorkDisplayProjectionQuarantined TypedNoWorkBandPct70To95 progressPct
                && midDrainControl
                && (snapshotKindCount "compile_progress_metronome_materialized_terminal_handoff_before_hard_abort" > 0
                    || snapshotKindCount "eval_worklist_bigstack_no_root_budget_terminal_dispatched_before_legacy_qap" > 0
