                    || snapshotKindCount "eval_worklist_terminal_frontier_pin_snapshot" > 0
                    || snapshotKindCount "eval_worklist_parent_replay_cycle_break_poison_inline_callback_commit" > 0)
                && (snapshotKindCount "eval_worklist_cross_kind_yield_thrash_hard_poison" > 0
                    || snapshotKindCount "eval_worklist_parent_poison_hopac_override_pierced_live_tail" > 0
                    || snapshotKindCount "eval_worklist_parent_replay_cycle_break_poison_live_tail_override_deferred" > 0
                    || snapshotKindCount "eval_worklist_parent_replay_cycle_break_poison_shadow_timeout_pierce" > 0)
            if nativeTopologyResolutionConsumersAttached
