            elif hasLiveHistory && noFreshDelta && richInFlight && richBusyMs >= 5000L && richBusyMs < 20000L && noWorkS >= 10L && noWorkPokes >= 6L && rescueCompleted >= 64L && typedNoWorkDisplayProjectionQuarantined TypedNoWorkBandPct95 progressPct && lateDrainControl then
                MetronomeNoWorkRichDiagReset
