        type ReplayProgressQualityId =
            | ReplayProgressNone
            | ReplayProgressScheduleProgress
            | ReplayProgressDriverOrRootProgress
            | ReplayProgressTerminalChatter
            | ReplayProgressScheduleTerminalChatterNoRoot

        let private replayProgressQualityText = function
            | ReplayProgressNone -> "none"
            | ReplayProgressScheduleProgress -> "schedule_progress"
            | ReplayProgressDriverOrRootProgress -> "driver_or_root_progress"
            | ReplayProgressTerminalChatter -> "terminal_chatter"
            | ReplayProgressScheduleTerminalChatterNoRoot -> "schedule_terminal_chatter_no_root"

        let private replayProgressQualityCode = function
            | ReplayProgressScheduleProgress -> 1L
            | ReplayProgressDriverOrRootProgress -> 2L
            | ReplayProgressTerminalChatter -> 3L
            | ReplayProgressScheduleTerminalChatterNoRoot -> 4L
            | ReplayProgressNone -> 0L

        // MIGRATION: root/semantic authority is distinct from replay-driver liveness.
        // A run can have many replay drivers and still have no root or semantic authority;
        // that is exactly the fast-fail frontier seen in MIGRATION.
        type ReplayRootAuthorityDecisionId =
            | ReplayRootAuthorityColdOrNoReplay
            | ReplayRootAuthorityScheduleOnlyNoRoot
            | ReplayRootAuthorityDriverOnlyNoRoot
            | ReplayRootAuthorityTerminalOnlyNoRoot
            | ReplayRootAuthoritySparseRootNoSemantic
            | ReplayRootAuthorityMultiRootNoSemantic
            | ReplayRootAuthoritySemanticOrRoot

        let private replayRootAuthorityDecisionText = function
            | ReplayRootAuthorityColdOrNoReplay -> "cold_or_no_replay"
            | ReplayRootAuthorityScheduleOnlyNoRoot -> "schedule_only_no_root"
            | ReplayRootAuthorityDriverOnlyNoRoot -> "driver_only_no_root"
            | ReplayRootAuthorityTerminalOnlyNoRoot -> "terminal_only_no_root"
            | ReplayRootAuthoritySparseRootNoSemantic -> "sparse_root_no_semantic"
            | ReplayRootAuthorityMultiRootNoSemantic -> "multi_root_no_semantic"
            | ReplayRootAuthoritySemanticOrRoot -> "semantic_or_terminal_authority"

        let private replayRootAuthorityAbortCandidate = function
            | ReplayRootAuthorityScheduleOnlyNoRoot
            | ReplayRootAuthorityDriverOnlyNoRoot
            | ReplayRootAuthorityTerminalOnlyNoRoot -> true
            | _ -> false

        let private replayRootAuthorityDecisionFor semanticReceipts rootCompleteStores terminalSignals replaySchedules replayDrivers replayYields =
            if semanticReceipts > 0 then ReplayRootAuthoritySemanticOrRoot
            elif rootCompleteStores > 1 then ReplayRootAuthorityMultiRootNoSemantic
            elif rootCompleteStores = 1 then ReplayRootAuthoritySparseRootNoSemantic
            elif terminalSignals > 0 then ReplayRootAuthorityTerminalOnlyNoRoot
            elif replayDrivers > 0 then ReplayRootAuthorityDriverOnlyNoRoot
            elif replaySchedules > 0 || replayYields > 0 then ReplayRootAuthorityScheduleOnlyNoRoot
            else ReplayRootAuthorityColdOrNoReplay

        // MIGRATION: expose root/replay authority as a typed relationship instead
        // of a loose pair of strings.  This keeps the Hopac frontier honest: replay
        // movement, root stores and semantic receipts are related, but not equivalent.
        type ReplayAuthorityEvidenceId =
            | ReplayAuthorityEvidenceCold
            | ReplayAuthorityEvidenceReplayOnly of ReplayProgressQualityId
            | ReplayAuthorityEvidenceRootNoSemantic of ReplayRootAuthorityDecisionId * ReplayProgressQualityId
            | ReplayAuthorityEvidenceSemanticOrTerminal of ReplayRootAuthorityDecisionId

        let private replayAuthorityEvidenceFor rootAuthority progressQuality =
            match rootAuthority with
            | ReplayRootAuthoritySemanticOrRoot -> ReplayAuthorityEvidenceSemanticOrTerminal rootAuthority
            | ReplayRootAuthoritySparseRootNoSemantic
            | ReplayRootAuthorityMultiRootNoSemantic -> ReplayAuthorityEvidenceRootNoSemantic(rootAuthority, progressQuality)
            | ReplayRootAuthorityScheduleOnlyNoRoot
            | ReplayRootAuthorityDriverOnlyNoRoot
            | ReplayRootAuthorityTerminalOnlyNoRoot -> ReplayAuthorityEvidenceReplayOnly progressQuality
            | ReplayRootAuthorityColdOrNoReplay -> ReplayAuthorityEvidenceCold

        let private replayAuthorityEvidenceText = function
            | ReplayAuthorityEvidenceCold -> "cold"
            | ReplayAuthorityEvidenceReplayOnly q -> sprintf "replay_only:%s" (replayProgressQualityText q)
            | ReplayAuthorityEvidenceRootNoSemantic (r, q) -> sprintf "root_no_semantic:%s:%s" (replayRootAuthorityDecisionText r) (replayProgressQualityText q)
            | ReplayAuthorityEvidenceSemanticOrTerminal r -> sprintf "semantic_or_terminal:%s" (replayRootAuthorityDecisionText r)

        // MIGRATION: EJP0025 must distinguish mature no-root/no-semantic churn
        // from a still-moving structural/draining frontier.  Historical runtime aborted at
        // elapsed=38s with sampled_work_delta=17 and a final HUD queue=1 active=0;
        // that is too close to a drained handoff frontier for a blind hard abort.
        type ReplayAbortMaturityId =
            | ReplayAbortMaturityColdOrImmature
            | ReplayAbortMaturityGraceStructuralWork
            | ReplayAbortMaturityGraceDrainingFrontier
            | ReplayAbortMaturityMatureNoRootNoSemantic

        let private replayAbortMaturityText = function
            | ReplayAbortMaturityColdOrImmature -> "cold_or_immature"
            | ReplayAbortMaturityGraceStructuralWork -> "grace_structural_work"
            | ReplayAbortMaturityGraceDrainingFrontier -> "grace_draining_frontier"
            | ReplayAbortMaturityMatureNoRootNoSemantic -> "mature_no_root_no_semantic"

        let private replayAbortMaturityIsAbort = function
            | ReplayAbortMaturityMatureNoRootNoSemantic -> true
            | ReplayAbortMaturityColdOrImmature
            | ReplayAbortMaturityGraceStructuralWork
            | ReplayAbortMaturityGraceDrainingFrontier -> false

        let private replayAbortMaturityFor elapsedS replaySchedules replayDrivers replayYields sampledWork sampledWorkDelta replayProgressDelta rootCompleteDelta terminalSignalDelta semanticReceipts rootCompleteStores terminalSignals =
            if semanticReceipts > 0 || rootCompleteStores > 0 || rootCompleteDelta > 0L then ReplayAbortMaturityGraceDrainingFrontier
            elif elapsedS < 42L then ReplayAbortMaturityColdOrImmature
            elif sampledWorkDelta > 4L then ReplayAbortMaturityGraceStructuralWork
            elif replaySchedules < 192 || replayDrivers < 4 || replayYields < 8192 then ReplayAbortMaturityColdOrImmature
            elif replayProgressDelta <= 0L then ReplayAbortMaturityColdOrImmature
            elif terminalSignals > 0 || terminalSignalDelta > 0L then ReplayAbortMaturityMatureNoRootNoSemantic
            elif sampledWork >= 160L then ReplayAbortMaturityMatureNoRootNoSemantic
            else ReplayAbortMaturityColdOrImmature

        // MIGRATION: active structural churn is a first-class diagnostic decision.
        // The assessment called out fake work: replay/structural movement with zero
        // semantic conversion.  This DU does not claim semantic failure by itself; it
        // gives HUD/JSON and BigStack gates a closed label for the arbitration.
        type ActiveStructuralChurnDecisionId =
            | ActiveStructuralChurnNone
            | ActiveStructuralChurnObserveSemanticOrRoot
            | ActiveStructuralChurnBoundedLiveDrain
            | ActiveStructuralChurnCircuitBreak

        let private activeStructuralChurnDecisionText = function
            | ActiveStructuralChurnNone -> "none"
            | ActiveStructuralChurnObserveSemanticOrRoot -> "observe_semantic_or_root"
            | ActiveStructuralChurnBoundedLiveDrain -> "bounded_live_structural_drain"
            | ActiveStructuralChurnCircuitBreak -> "active_structural_churn_circuit_break"

        let private activeStructuralChurnDecisionFor elapsedS semanticDelta structuralDelta replayDelta rootDelta terminalDelta replaySchedules replayDrivers terminalSignals =
            let semanticOrRootFresh = semanticDelta > 0 || rootDelta > 0 || terminalDelta > 0
            let structuralHot = structuralDelta >= 4 || replayDelta >= 16
            let replayActive = replaySchedules >= 32 || replayDrivers >= 4
            if semanticOrRootFresh then ActiveStructuralChurnObserveSemanticOrRoot
            elif elapsedS < 30L || not structuralHot || not replayActive then ActiveStructuralChurnNone
            elif elapsedS < 120L && terminalSignals < 128 then ActiveStructuralChurnBoundedLiveDrain
            else ActiveStructuralChurnCircuitBreak

        let private structuralSemanticDeltaRatioText semanticDelta structuralDelta =
            if structuralDelta <= 0 then "none"
            elif semanticDelta <= 0 then "inf_structural_no_semantic"
            else sprintf "%.4f" (float structuralDelta / max 1.0 (float semanticDelta))

        type RetryGenerationPolicyId =
            | RetryGenerationNoInvalidateGenWait
            | RetryGenerationNoInvalidateTermReentryFuse
            | RetryGenerationInvalidateLivenessParallel
            | RetryGenerationInvalidateSequentialFallback
            | RetryGenerationInvalidateOther

        let retryGenerationPolicyText = function
            | RetryGenerationNoInvalidateGenWait -> "no_invalidate_gen_wait"
            | RetryGenerationNoInvalidateTermReentryFuse -> "no_invalidate_term_reentry_fuse"
            | RetryGenerationInvalidateLivenessParallel -> "invalidate_liveness_parallel_retry"
            | RetryGenerationInvalidateSequentialFallback -> "invalidate_sequential_fallback"
            | RetryGenerationInvalidateOther -> "invalidate_other"

        let retryGenerationPolicyFor (isGenWait: bool) (isTermReentryFuse: bool) (retryPreservesParallel: bool) (willForceSequential: bool) =
            if isGenWait then RetryGenerationNoInvalidateGenWait
            elif isTermReentryFuse then RetryGenerationNoInvalidateTermReentryFuse
            elif retryPreservesParallel then RetryGenerationInvalidateLivenessParallel
            elif willForceSequential then RetryGenerationInvalidateSequentialFallback
            else RetryGenerationInvalidateOther

