            | ProgressForecastSparseRootNoSemantic -> "sparse_root_no_semantic"
            | ProgressForecastLowAuthorityRootTerminalDrip -> "low_authority_root_terminal_drip"
            | ProgressForecastDriverOrRootAuthority -> "driver_or_root_authority"

        let private progressEstimatorAuthorityModelOfForecast = function
