            | ProgressForecastSampledWorkOnly -> ProgressEstimatorAuthoritySampledWorkOnly
            | ProgressForecastReplayScheduleOnly -> ProgressEstimatorAuthorityReplayScheduleOnly
            | ProgressForecastReplayTerminalChatterNoRoot -> ProgressEstimatorAuthorityReplayTerminalChatterNoRoot
            | ProgressForecastReplayDriverNoRoot -> ProgressEstimatorAuthorityReplayDriverNoRoot
            | ProgressForecastSparseRootNoSemantic -> ProgressEstimatorAuthoritySparseRootNoSemantic
            | ProgressForecastLowAuthorityRootTerminalDrip -> ProgressEstimatorAuthorityLowAuthorityRootTerminalDrip
            | ProgressForecastDriverOrRootAuthority -> ProgressEstimatorAuthorityDriverOrRootAuthority

        let private progressForecastCapPct = function
