            | ProgressForecastReplayDriverNoRoot -> 4
            | ProgressForecastSparseRootNoSemantic -> 5
            | ProgressForecastLowAuthorityRootTerminalDrip -> 6
            | ProgressForecastDriverOrRootAuthority -> 7

