        let private progressEtaTargetText = function
            | ProgressEtaTargetAuthorityCap -> "authority_cap"
            | ProgressEtaTargetOrganicAuthorityMargin -> "organic_authority_margin"

        let private progressEtaSlopeBasisText = function
            | ProgressEtaSlopeBasisNone -> "none"
            | ProgressEtaSlopeBasisSampledWork -> "sampled_work_delta"
            | ProgressEtaSlopeBasisReplay -> "replay_progress_delta"
            | ProgressEtaSlopeBasisRoot -> "root_complete_delta"
            | ProgressEtaSlopeBasisTerminal -> "terminal_signal_delta"

        let private progressEtaSlopeBasisFor sampledWorkDelta replayProgressDelta rootCompleteDelta terminalSignalDelta =
            if terminalSignalDelta > 0 then ProgressEtaSlopeBasisTerminal
            elif rootCompleteDelta > 0 then ProgressEtaSlopeBasisRoot
            elif replayProgressDelta > 0 then ProgressEtaSlopeBasisReplay
            elif sampledWorkDelta > 0 then ProgressEtaSlopeBasisSampledWork
            else ProgressEtaSlopeBasisNone

        let private progressEtaConfidenceText = function
            | ProgressEtaUnknownStartup -> "unknown_startup"
            | ProgressEtaTargetReached -> "target_reached"
            | ProgressEtaUnknownNoRecentProgressDelta -> "unknown_no_recent_progress_delta"
            | ProgressEtaUnknownInsufficientAuthority -> "unknown_insufficient_authority"
            | ProgressEtaUnknownStaleTerminalChurn -> "unknown_stale_terminal_churn"
            | ProgressEtaUnknownLiveGraphNoMaterialDelta -> "unknown_live_graph_no_material_delta"
            | ProgressEtaCalibratingMaterialSlope -> "calibrating_material_authority_slope"
            | ProgressEtaMaterialAuthoritySlope -> "material_authority_slope"
            | ProgressEtaSampledWorkRecentPctSlope -> "sampled_work_only_recent_pct_slope"
            | ProgressEtaSampledWorkCarryForward -> "sampled_work_only_carry_forward"
            | ProgressEtaOrganicCapMarginRecentPctSlope -> "organic_cap_margin_recent_pct_slope"
            | ProgressEtaAuthorityCapRecentPctSlope -> "authority_cap_recent_pct_slope"
            | ProgressEtaOrganicCapMarginCarryForward -> "organic_cap_margin_carry_forward"
            | ProgressEtaAuthorityCapCarryForward -> "authority_cap_carry_forward"

        type ProgressCommitGateClassId =
            | ProgressCommitGateRejectedDeadlockObserverOnly
            | ProgressCommitGateAllowedSemanticFailure
            | ProgressCommitGateAllowedResolvedMaterial
            | ProgressCommitGateAllowedNoFurther
            | ProgressCommitGateBlockedByOpenOwners
            | ProgressCommitGateBlockedByWorkDagAuthority
            | ProgressCommitGateBlockedBySchedulerCausality
            | ProgressCommitGateBlockedByBreakthroughQuorum
            | ProgressCommitGateDeferredLiveGraph
            | ProgressCommitGateDeferredFreshTopologyWitness
            | ProgressCommitGateDeferredTypedTerminalGate
            | ProgressCommitGateNotRequested

        let private progressCommitGateClassFor (gate:NativePromiseTerminalCommitGate<'Kind>) =
            match gate with
            | NativePromiseTerminalCommitRejectedDeadlockObserverOnly _ -> ProgressCommitGateRejectedDeadlockObserverOnly
            | NativePromiseTerminalCommitAllowedSemanticFailure _ -> ProgressCommitGateAllowedSemanticFailure
            | NativePromiseTerminalCommitAllowedResolvedMaterial _ -> ProgressCommitGateAllowedResolvedMaterial
            | NativePromiseTerminalCommitAllowedNoFurther _ -> ProgressCommitGateAllowedNoFurther
            | NativePromiseTerminalCommitBlockedByOpenOwners _ -> ProgressCommitGateBlockedByOpenOwners
            | NativePromiseTerminalCommitBlockedByWorkDagAuthority _ -> ProgressCommitGateBlockedByWorkDagAuthority
            | NativePromiseTerminalCommitBlockedBySchedulerCausality _ -> ProgressCommitGateBlockedBySchedulerCausality
            | NativePromiseTerminalCommitBlockedByBreakthroughQuorum _ -> ProgressCommitGateBlockedByBreakthroughQuorum
            | NativePromiseTerminalCommitDeferredLiveGraph _ -> ProgressCommitGateDeferredLiveGraph
            | NativePromiseTerminalCommitDeferredFreshTopologyWitness _ -> ProgressCommitGateDeferredFreshTopologyWitness
            | NativePromiseTerminalCommitDeferredTypedTerminalGate _ -> ProgressCommitGateDeferredTypedTerminalGate
            | NativePromiseTerminalCommitNotRequested _ -> ProgressCommitGateNotRequested

        let private progressCommitGateClassText = function
            | ProgressCommitGateRejectedDeadlockObserverOnly -> "rejected_deadlock_observer_only"
            | ProgressCommitGateAllowedSemanticFailure -> "allowed_semantic_failure"
            | ProgressCommitGateAllowedResolvedMaterial -> "allowed_resolved_material"
            | ProgressCommitGateAllowedNoFurther -> "allowed_no_further"
            | ProgressCommitGateBlockedByOpenOwners -> "blocked_by_open_owners"
            | ProgressCommitGateBlockedByWorkDagAuthority -> "blocked_by_work_dag_authority"
            | ProgressCommitGateBlockedBySchedulerCausality -> "blocked_by_scheduler_causality"
            | ProgressCommitGateBlockedByBreakthroughQuorum -> "blocked_by_breakthrough_quorum"
            | ProgressCommitGateDeferredLiveGraph -> "deferred_live_graph_typestate"
            | ProgressCommitGateDeferredFreshTopologyWitness -> "deferred_fresh_topology_witness"
            | ProgressCommitGateDeferredTypedTerminalGate -> "deferred_typed_terminal_gate"
            | ProgressCommitGateNotRequested -> "not_requested"

        let private progressCommitGateNextAction topologyWitnessClass = function
            | ProgressCommitGateAllowedSemanticFailure -> "emit_typed_semantic_failure_terminal_commit"
            | ProgressCommitGateAllowedResolvedMaterial -> "resolve_root_complete_buildok_and_mint_writer_capability"
            | ProgressCommitGateAllowedNoFurther -> "emit_typed_no_further_terminal_commit"
            | ProgressCommitGateBlockedByOpenOwners -> "close_or_quarantine_terminal_owners_before_commit"
            | ProgressCommitGateBlockedByWorkDagAuthority -> "materialize_work_dag_delta_or_close_ledger_before_commit"
            | ProgressCommitGateBlockedBySchedulerCausality -> "materialize_push_wake_receipt_or_close_scheduler_causality"
            | ProgressCommitGateBlockedByBreakthroughQuorum -> "satisfy_breakthrough_quorum_before_terminal_commit"
            | ProgressCommitGateDeferredLiveGraph -> "wait_bounded_stasis_or_consume_typed_live_graph_edge"
            | ProgressCommitGateDeferredFreshTopologyWitness when topologyWitnessClass = TopologyWitnessProgressRepeatedTopologyOnly ->
                "topology_witness_repeat_is_stasis_advance_commit_gate"
            | ProgressCommitGateDeferredFreshTopologyWitness -> "consume_fresh_topology_witness_once"
            | (ProgressCommitGateRejectedDeadlockObserverOnly
              | ProgressCommitGateDeferredTypedTerminalGate
              | ProgressCommitGateNotRequested) when topologyWitnessClass = TopologyWitnessProgressRepeatedTopologyOnly ->
                "topology_witness_repeat_is_stasis_advance_commit_gate"
            | ProgressCommitGateRejectedDeadlockObserverOnly
            | ProgressCommitGateDeferredTypedTerminalGate
            | ProgressCommitGateNotRequested -> "continue_progress_tick"

        type ProgressTailFact =
            | ProgressTailTopology
            | ProgressTailSidecarDrain
            | ProgressTailPoison
            | ProgressTailFatal

        let private progressTailFactsFor (reasonId:CompilerKernelV2.OperationalReasonId) (poisonStateId:CompilerKernelV2.OperationalReasonId) (decisionId:CompilerKernelV2.OperationalReasonId) =
            // Text is admitted once at this legacy boundary; all downstream
            // control flow consumes the closed fact set.
            let reasonSignals = progressTailTextSignals (CompilerKernelV2.OperationalReasonIdOps.text reasonId)
            let poisonSignals = progressTailTextSignals (CompilerKernelV2.OperationalReasonIdOps.text poisonStateId)
            let decisionTokens = diagnosticTextTokensLower (CompilerKernelV2.OperationalReasonIdOps.text decisionId)
            [ if Set.contains ProgressTailTextTopologySignal reasonSignals then ProgressTailTopology
              if Set.contains ProgressTailTextSidecarDrainSignal poisonSignals then ProgressTailSidecarDrain
              if Set.contains ProgressTailTextPoisonSignal poisonSignals then ProgressTailPoison
              if diagnosticTextHasAny [ "fatal"; "failedclosed"; "fail_closed"; "fatal_terminal" ] decisionTokens then ProgressTailFatal ]
            |> Set.ofList

        let private progressForecastModelFor sampledWork replaySchedules replayDrivers replayYields rootComplete terminalSignals semanticReceipts =
            let lowAuthorityRootTerminalDrip =
                replaySchedules > 0
                && replaySchedules <= 64
                && replayDrivers <= 16
                && rootComplete > 0
                && rootComplete <= 8
                && terminalSignals > 0
                && terminalSignals <= 32
            if sampledWork <= 0 then ProgressForecastColdStart
            elif lowAuthorityRootTerminalDrip then ProgressForecastLowAuthorityRootTerminalDrip
            elif terminalSignals > 0 || semanticReceipts > 0 || rootComplete > 16 then ProgressForecastDriverOrRootAuthority
            elif rootComplete > 0 then ProgressForecastSparseRootNoSemantic
            elif replayDrivers > 0 && rootComplete <= 0 then ProgressForecastReplayDriverNoRoot
            elif replaySchedules > 0 && terminalSignals > 0 && rootComplete <= 0 && replayDrivers <= 16 then ProgressForecastReplayTerminalChatterNoRoot
            elif replaySchedules + replayYields > 0 then ProgressForecastReplayScheduleOnly
            else ProgressForecastSampledWorkOnly

        type private TerminalLatchJsonKindId =
            | TerminalLatchHudFinal
            | TerminalLatchParentPoisonDurableExit
            | TerminalLatchTerminalFamily
            | TerminalLatchBuildErrorTraceFamily
            | TerminalLatchBuildRetryVetoFamily
            | TerminalLatchRootPromiseFamily
            | TerminalLatchHudLivenessFamily
            | TerminalLatchPhysicalExitFailsafeFamily
            | TerminalLatchOther

        let private terminalLatchJsonKindFor (kind:string) =
            let atoms =
                if System.String.IsNullOrWhiteSpace kind then []
                else kind.Split([|'_'|], System.StringSplitOptions.RemoveEmptyEntries) |> Array.toList
            match atoms with
            | ["spiral"; "hud"; "final"] -> TerminalLatchHudFinal
            | ["parent"; "poison"; "quorum"; "closed"; "durable"; "exit"] -> TerminalLatchParentPoisonDurableExit
            | "terminal" :: _ -> TerminalLatchTerminalFamily
            | "build" :: "error" :: "trace" :: _ -> TerminalLatchBuildErrorTraceFamily
            | "build" :: "retry" :: "vetoed" :: "by" :: "terminal" :: "authority" :: _ -> TerminalLatchBuildRetryVetoFamily
            | "root" :: "promise" :: _ -> TerminalLatchRootPromiseFamily
            | "progress" :: "hud" :: "ticker" :: _ -> TerminalLatchHudLivenessFamily
            | "progress" :: "hud" :: "bootstrap" :: _ -> TerminalLatchHudLivenessFamily
            | "physical" :: "exit" :: "failsafe" :: _ -> TerminalLatchPhysicalExitFailsafeFamily
            | _ -> TerminalLatchOther

        let private terminalLatchAllowsJsonLine (line: string) =
            if not (terminalFailureExitRequestedNow()) then true
            else
                match jsonStringFieldByName "kind" line |> terminalLatchJsonKindFor with
                | TerminalLatchHudFinal
                | TerminalLatchParentPoisonDurableExit
                | TerminalLatchTerminalFamily
                | TerminalLatchBuildErrorTraceFamily
                | TerminalLatchBuildRetryVetoFamily
                | TerminalLatchRootPromiseFamily
                | TerminalLatchHudLivenessFamily
                | TerminalLatchPhysicalExitFailsafeFamily -> true
                | TerminalLatchOther -> false

        let private writeProgressHeartbeatLineDirect (line: string) =
            if terminalLatchAllowsJsonLine line then
                CompilerConsoleHud88.writeProgressJsonLineNonBlocking line

        let private refreshProgressHeartbeatHudOnlyDirect (line: string) =
            if not (CompilerConsoleHud88.progressHudPresentationClosedNow()) then
                CompilerConsoleHud88.refreshProgressJsonLineNonBlocking line

        let private ensureProgressHudSmoothFrameTicker () =
            // Start from the bootstrap projection, as the pre-2621 ticker did, but
            // never require the reducer mailbox before in-process activation.
            if CompilerRuntimeActivation.isInProcessEntered()
               && not (CompilerConsoleHud88.progressHudPresentationClosedNow()) then
                let nowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                // Health reporting belongs to the metronome supervisor, not the
                // painter. A slow log append must never consume the frame budget.
                let healthSnapshot =
                    lock progressHudSmoothFrameTickerGate (fun () ->
                        match progressHudSmoothFrameTickerState with
                        | ProgressHudTickerRunning(generation, startedAtMs, lastFrameMs, frameCount)
                            when lastFrameMs > 0L
                                 && (progressHudSmoothFrameTickerLastHealthMs = 0L
                                     || nowMs - progressHudSmoothFrameTickerLastHealthMs >= progressHudSmoothFrameHealthCadenceMs) ->
                            progressHudSmoothFrameTickerLastHealthMs <- nowMs
                            Some(generation, startedAtMs, frameCount, lastFrameMs)
                        | _ -> None)
                match healthSnapshot with
                | Some(generation, startedAtMs, frameCount, lastFrameMs) ->
                    let visibleFrameCount, noVisualDeltaFrameCount, visibleLastFrameMs, effectiveLastFrameMs, visibleFailure = CompilerConsoleHud88.progressHudVisibleFrameSnapshot()
                    let visibleAgeMs = if visibleLastFrameMs <= 0L then -1L else max 0L (nowMs - visibleLastFrameMs)
                    let effectiveAgeMs = if effectiveLastFrameMs <= 0L then -1L else max 0L (nowMs - effectiveLastFrameMs)
                    // Only the metronome paints. Semantic publishers install immutable
                    // snapshots and return without touching the console lane. The global
                    // counters therefore describe one bounded frame authority.
                    let globalEffectiveFrameCount = visibleFrameCount + noVisualDeltaFrameCount
                    let effectiveFrameCount = min frameCount globalEffectiveFrameCount
                    let activeDurationMs = max 1L (nowMs - startedAtMs)
                    let attemptedFpsMilli = 1000000L * frameCount / activeDurationMs
                    let effectiveFpsMilli = 1000000L * effectiveFrameCount / activeDurationMs
                    let cadenceHealth =
                        progressHudCadenceHealthFor activeDurationMs effectiveFpsMilli effectiveAgeMs
                    let expectedFrameCount = max 1L (activeDurationMs / progressHudSmoothFrameCadenceMs)
                    writeProgressHeartbeatLineDirect (
                        FastRuntimeFormat.format "{\"kind\":\"progress_hud_ticker_health\",\"generation\":%d,\"active_duration_ms\":%d,\"attempted_frame_count\":%d,\"attempted_fps_milli\":%d,\"attempted_last_frame_ms\":%d,\"visible_frame_count\":%d,\"no_visual_delta_frame_count\":%d,\"global_effective_frame_count\":%d,\"effective_frame_count\":%d,\"effective_fps_milli\":%d,\"visible_last_frame_ms\":%d,\"visible_frame_age_ms\":%d,\"effective_last_frame_ms\":%d,\"effective_frame_age_ms\":%d,\"visible_failure_du\":%s,\"hud_console_lane_du\":%s,\"frame_flush_du\":%s,\"cadence_health_du\":%s,\"cadence_ms\":%d,\"expected_min_frames\":%d,\"console_projection_du\":\"JsonlCompleteHumanTerminalConsole\",\"semantic_repaint_du\":\"TypedSnapshotDiffEveryFrame\",\"clock_tick_du\":\"ElapsedAndEtaDiffEvery50ms\",\"taskbar_projection_du\":\"ReducerSnapshotOnly\",\"authority\":\"hud_visible_write_receipt_plus_no_delta_receipt\",\"emitter_du\":\"metronome_supervisor_plus_painter_receipt\"}" [| box generation; box activeDurationMs; box frameCount; box attemptedFpsMilli; box lastFrameMs; box visibleFrameCount; box noVisualDeltaFrameCount; box globalEffectiveFrameCount; box effectiveFrameCount; box effectiveFpsMilli; box visibleLastFrameMs; box visibleAgeMs; box effectiveLastFrameMs; box effectiveAgeMs; box (esc visibleFailure); box (esc (CompilerConsoleHud88.progressHudVisibleConsoleLaneText())); box (esc (CompilerConsoleHud88.progressHudVisibleFlushPolicyText())); box (esc (progressHudCadenceHealthText cadenceHealth)); box progressHudSmoothFrameCadenceMs; box expectedFrameCount |])
                | None -> ()
                let startDecision =
                    lock progressHudSmoothFrameTickerGate (fun () ->
                        match progressHudSmoothFrameTickerState with
                        | ProgressHudTickerRunning _ ->
                            // MIGRATION: a slow paint must not spawn competing ticker generations.
                            // The one background runner owns cadence until it explicitly faults/stops.
                            None
                        | ProgressHudTickerStopped(generation, lastFrameMs, frameCount, failure) ->
                            let nextGeneration = generation + 1L
                            progressHudSmoothFrameTickerState <- ProgressHudTickerRunning(nextGeneration, nowMs, 0L, 0L)
                            Some(nextGeneration, failure, lastFrameMs, frameCount))
                match startDecision with
                | None -> ()
                | Some(generation, startReason, priorLastFrameMs, priorFrameCount) ->
                    // Paint before emitting the ticker receipt.  The MIGRATION freeze
                    // happened after the receipt but before the first frame, so this
                    // ordering makes startup liveness directly observable.
                    let bootstrapPainted =
                        try
                            CompilerConsoleHud88.tryPaintReducerHudSnapshotNow()
                        with ex ->
                            writeProgressHeartbeatLineDirect (
                                sprintf "{\"kind\":\"progress_hud_bootstrap_paint_failed\",\"generation\":%d,\"exception_type\":%s,\"authority\":\"bounded_startup_diagnostic\"}"
                                    generation (esc (ex.GetType().FullName)))
                            false
                    // The bootstrap paint is a real frame attempt. Account for it in
                    // the ticker state so attempted/effective FPS cannot begin with
                    // visible_frame_count greater than attempted_frame_count.
                    let bootstrapAttemptMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                    lock progressHudSmoothFrameTickerGate (fun () ->
                        match progressHudSmoothFrameTickerState with
                        | ProgressHudTickerRunning(activeGeneration, startedAtMs, _, previousFrameCount) when activeGeneration = generation ->
                            progressHudSmoothFrameTickerState <-
                                ProgressHudTickerRunning(activeGeneration, startedAtMs, bootstrapAttemptMs, previousFrameCount + 1L)
                        | _ -> ())
                    writeProgressHeartbeatLineDirect (
                        FastRuntimeFormat.format "{\"kind\":\"progress_hud_ticker_started\",\"generation\":%d,\"start_reason_du\":%s,\"prior_last_frame_ms\":%d,\"prior_frame_count\":%d,\"cadence_ms\":%d,\"stale_after_ms\":%d,\"bootstrap_painted\":%s,\"authority\":\"hud_observer_liveness_only\"}" [| box generation; box (esc (progressHudTickerStopReasonText startReason)); box priorLastFrameMs; box priorFrameCount; box progressHudSmoothFrameCadenceMs; box progressHudSmoothFrameStaleAfterMs; box (if bootstrapPainted then "true" else "false") |])
                    let runner () =
                        let mutable running = true
                        let mutable nextDueMs = bootstrapAttemptMs + progressHudSmoothFrameCadenceMs
                        while running && not (CompilerConsoleHud88.progressHudPresentationClosedNow()) do
                            let ownsGeneration =
                                lock progressHudSmoothFrameTickerGate (fun () ->
                                    match progressHudSmoothFrameTickerState with
                                    | ProgressHudTickerRunning(activeGeneration, _, _, _) when activeGeneration = generation -> true
                                    | _ -> false)
                            if not ownsGeneration then
                                running <- false
                            else
                                try
                                    let mutable now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                                    while now < nextDueMs && running do
                                        let sleepMs = int (min 25L (max 1L (nextDueMs - now)))
                                        System.Threading.Thread.Sleep(sleepMs)
                                        now <- System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                                    if running then
                                        if progressPredictionStartMs <= 0L then progressPredictionStartMs <- now
                                        // The visual ticker owns presentation only. Render directly from
                                        // the immutable reducer projection instead of rebuilding an
                                        // intermediate JSON frame or touching push-actor/metronome state.
                                        // This keeps elapsed/ETA paint bounded even when semantic lanes
                                        // are saturated or the terminal actor is still initializing.
                                        if not quiet then CompilerConsoleHud88.tryPaintReducerHudSnapshotNow() |> ignore
                                        // Publish the attempt after the bounded paint. Effective/visible
                                        // receipts are tracked independently by the console compositor.
                                        lock progressHudSmoothFrameTickerGate (fun () ->
                                            match progressHudSmoothFrameTickerState with
                                            | ProgressHudTickerRunning(activeGeneration, startedAtMs, _, previousFrameCount) when activeGeneration = generation ->
                                                progressHudSmoothFrameTickerState <- ProgressHudTickerRunning(activeGeneration, startedAtMs, now, previousFrameCount + 1L)
                                            | _ -> ())
                                        // The visual ticker must remain presentation-only. Terminal
                                        // ledger liveness runs on the independent prediction heartbeat;
                                        // otherwise reducer contention can freeze elapsed/ETA painting.
                                        let nominalNextDueMs = nextDueMs + progressHudSmoothFrameCadenceMs
                                        nextDueMs <- if now >= nominalNextDueMs then now + progressHudSmoothFrameCadenceMs else nominalNextDueMs
                                with ex ->
                                    let failure =
                                        ProgressHudTickerFaulted(
                                            ex.GetType().Name,
                                            ex.Message)
                                    lock progressHudSmoothFrameTickerGate (fun () ->
                                        match progressHudSmoothFrameTickerState with
                                        | ProgressHudTickerRunning(activeGeneration, _, lastFrameMs, frameCount) when activeGeneration = generation ->
                                            progressHudSmoothFrameTickerState <- ProgressHudTickerStopped(generation, lastFrameMs, frameCount, failure)
                                        | _ -> ())
                                    writeProgressHeartbeatLineDirect (
                                        sprintf "{\"kind\":\"progress_hud_ticker_faulted\",\"generation\":%d,\"failure_du\":%s,\"next\":\"heartbeat_restarts_stale_or_stopped_ticker\",\"authority\":\"hud_observer_liveness_only\"}"
                                            generation (esc (progressHudTickerStopReasonText failure)))
                                    running <- false
                        lock progressHudSmoothFrameTickerGate (fun () ->
                            match progressHudSmoothFrameTickerState with
                            | ProgressHudTickerRunning(activeGeneration, _, lastFrameMs, frameCount) when activeGeneration = generation ->
                                progressHudSmoothFrameTickerState <- ProgressHudTickerStopped(
                                    generation,
                                    lastFrameMs,
                                    frameCount,
                                    ProgressHudTickerRunnerStopped)
                            | _ -> ())
                    // The visual clock is intentionally outside Hopac. It is an
                    // observer-only lane and must remain alive even if the compiler
                    // scheduler is saturated or stopping.
                    let t = System.Threading.Thread(System.Threading.ThreadStart(runner))
                    t.IsBackground <- true
                    t.Name <- "spiral-hud-frame-ticker-" + string generation
                    t.Start()

        let private writeProgressHeartbeatLine (_directWrite: bool) (line: string) =
            writeProgressHeartbeatLineDirect line

        let private writeProgressHeartbeatTerminalLineDurable (line: string) =
            CompilerConsoleHud88.writeProgressJsonLineTerminalDurable line


        // DOMAIN MIGRATION : legacy process exits are quarantined from semantic authority.
        // Ordinary heartbeat/watchdog/metronome/replay observations can only publish a
        // request.  A separately typed extreme host deadman may terminate a failed-closed
        // process, but it can never mint run_end, semantic success, or durable closure.
        type LegacyProcessExitReasonId =
            | LegacyExitTypedRootCollapse
            | LegacyExitTypedNoWorkRootCollapse
            | LegacyExitMetronomeLedgerIdentityCorruption
            | LegacyExitTypedNoWorkAbort
            | LegacyExitTypedNoWorkRescueSaturation
            | LegacyExitTypedReplayChatterAbort
            | LegacyExitTypedNoWorkSchedulerAbort
            | LegacyExitTypedUnderutilizedAbort
            | LegacyExitTrueMetronomeStalledCpuDeadman
            | LegacyExitFailedClosedResidualDeadman
            | LegacyExitTypedTerminalReducerAcknowledged
            | LegacyExitParentObserverAfterNativeRootComplete
            | LegacyExitClientAfterReducerOwnedTotalOrder
            | LegacyExitClientWithoutReducerOwnedPhysicalReceipt
            | LegacyExitWebHostWithoutReducerOwnedPhysicalReceipt

        type LegacyExitQuiescenceRequirement =
            | LegacyExitRequiresSemanticQuiescence
            | LegacyExitMayFailClosedWithResidualEvidence

        let legacyExitQuiescenceRequirementFor = function
            | LegacyExitTypedNoWorkAbort
            | LegacyExitTypedNoWorkRescueSaturation
            | LegacyExitTypedReplayChatterAbort
            | LegacyExitTypedNoWorkSchedulerAbort
            | LegacyExitTypedUnderutilizedAbort -> LegacyExitRequiresSemanticQuiescence
            | _ -> LegacyExitMayFailClosedWithResidualEvidence

        let legacyExitQuiescenceRequirementText = function
            | LegacyExitRequiresSemanticQuiescence -> "requires_semantic_quiescence"
            | LegacyExitMayFailClosedWithResidualEvidence -> "may_fail_closed_with_residual_evidence"

        let legacyProcessExitReasonText = function
            | LegacyExitTypedRootCollapse -> "typed_root_collapse_exit"
            | LegacyExitTypedNoWorkRootCollapse -> "typed_no_work_root_collapse_exit"
            | LegacyExitMetronomeLedgerIdentityCorruption -> "metronome_ledger_identity_corruption_quarantine"
            | LegacyExitTypedNoWorkAbort -> "typed_no_work_abort_exit"
            | LegacyExitTypedNoWorkRescueSaturation -> "typed_no_work_rescue_saturation_exit"
            | LegacyExitTypedReplayChatterAbort -> "typed_replay_chatter_abort_exit"
            | LegacyExitTypedNoWorkSchedulerAbort -> "typed_no_work_scheduler_abort_exit"
            | LegacyExitTypedUnderutilizedAbort -> "typed_underutilized_abort_exit"
            | LegacyExitTrueMetronomeStalledCpuDeadman -> "true_metronome_stalled_cpu_deadman_exit"
            | LegacyExitFailedClosedResidualDeadman -> "failed_closed_residual_host_deadman_exit"
            | LegacyExitTypedTerminalReducerAcknowledged -> "typed_terminal_reducer_acknowledged"
            | LegacyExitParentObserverAfterNativeRootComplete -> "parent_process_exit_observer_only_after_native_root_complete_cutover"
            | LegacyExitClientAfterReducerOwnedTotalOrder -> "client_exit_request_after_reducer_owned_total_order"
            | LegacyExitClientWithoutReducerOwnedPhysicalReceipt -> "client_exit_request_without_reducer_owned_physical_exit_receipt"
            | LegacyExitWebHostWithoutReducerOwnedPhysicalReceipt -> "web_host_returned_without_reducer_owned_physical_exit_receipt"

        type LegacyProcessExitObservationKind =
            | LegacyPostRootWriterLeaseExpired
            | LegacyTrueMetronomeStalled
            | LegacyFailedClosedResidualDeadman
            | LegacyProvisionalTypedTerminalFailureRequested
            | LegacyTypedTerminalFailureRequested of reason:CompilerKernelV2.OperationalReasonId
            | LegacyOtherExitObservation of CompilerKernelV2.OperationalReasonId

        let private legacyProcessExitObservationKindFor reason =
            let reasonText = legacyProcessExitReasonText reason
            let operationalReason = CompilerKernelV2.OperationalReasonIdOps.create reasonText
            match reason with
            | LegacyExitTrueMetronomeStalledCpuDeadman -> LegacyTrueMetronomeStalled
            | LegacyExitFailedClosedResidualDeadman -> LegacyFailedClosedResidualDeadman
            | LegacyExitTypedRootCollapse
            | LegacyExitTypedNoWorkRootCollapse
            | LegacyExitMetronomeLedgerIdentityCorruption
            | LegacyExitTypedNoWorkAbort
            | LegacyExitTypedNoWorkRescueSaturation
            | LegacyExitTypedReplayChatterAbort
            | LegacyExitTypedNoWorkSchedulerAbort
            | LegacyExitTypedUnderutilizedAbort -> LegacyTypedTerminalFailureRequested operationalReason
            | LegacyExitTypedTerminalReducerAcknowledged
            | LegacyExitParentObserverAfterNativeRootComplete
            | LegacyExitClientAfterReducerOwnedTotalOrder
            | LegacyExitClientWithoutReducerOwnedPhysicalReceipt
            | LegacyExitWebHostWithoutReducerOwnedPhysicalReceipt -> LegacyOtherExitObservation operationalReason

        let private legacyProcessExitObservationKindText = function
            | LegacyPostRootWriterLeaseExpired -> "post_root_writer_lease_expired"
            | LegacyTrueMetronomeStalled -> "true_metronome_stalled"
            | LegacyFailedClosedResidualDeadman -> "failed_closed_residual_deadman"
            | LegacyProvisionalTypedTerminalFailureRequested -> "provisional_typed_terminal_failure_requested"
            | LegacyTypedTerminalFailureRequested reason -> "typed_terminal_failure_requested:" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | LegacyOtherExitObservation reason -> "other:" + CompilerKernelV2.OperationalReasonIdOps.text reason

        type LegacyProcessExitObserverRequest = {
            code : int
            reason : LegacyProcessExitReasonId
            kind : LegacyProcessExitObservationKind
            observedAtUtc : System.DateTime
        }

        let private legacyProcessExitObserverRequests =
            System.Collections.Concurrent.ConcurrentQueue<LegacyProcessExitObserverRequest>()

        type LegacyProcessExitObserverRemoval =
            | LegacyProcessExitObserverRemoved of LegacyProcessExitObserverRequest
            | LegacyProcessExitObserverEmpty

        let legacyProcessExitObserverTryRemove () =
            let mutable target = Unchecked.defaultof<LegacyProcessExitObserverRequest>
            if legacyProcessExitObserverRequests.TryDequeue(&target) then
                LegacyProcessExitObserverRemoved target
            else
                LegacyProcessExitObserverEmpty

        let legacyProcessExitObservationKindTextPublic kind =
            legacyProcessExitObservationKindText kind

        type private LegacyProcessExitFailsafeState =
            | LegacyProcessExitFailsafeDisarmed
            | LegacyProcessExitFailsafeArmed
            | LegacyProcessExitFailsafeFiring

        type private LegacyProcessExitFailsafeDecision =
            | LegacyProcessExitFailsafeNotRequired
            | LegacyProcessExitFailsafeAlreadyArmed
            | LegacyProcessExitFailsafeArmedNow

        type private LegacyProcessExitFailsafePolicy =
            | LegacyProcessExitFailsafeAfterDelay of delayMs:int

        let private legacyProcessExitFailsafePolicyText = function
            | LegacyProcessExitFailsafeAfterDelay _ -> "AfterDelay"

        let private legacyProcessExitFailsafePolicyDelayMs = function
            | LegacyProcessExitFailsafeAfterDelay delayMs -> delayMs

        let private legacy_process_exit_failsafe_policy =
            LegacyProcessExitFailsafeAfterDelay 1500

        let private legacyProcessExitFailsafeGate = obj()
        let mutable private legacyProcessExitFailsafeState = LegacyProcessExitFailsafeDisarmed

        let private legacyProcessExitFailsafeDecisionFor kind =
            match kind with
            | LegacyTrueMetronomeStalled
            | LegacyFailedClosedResidualDeadman ->
                lock legacyProcessExitFailsafeGate (fun () ->
                    match legacyProcessExitFailsafeState with
                    | LegacyProcessExitFailsafeArmed
                    | LegacyProcessExitFailsafeFiring -> LegacyProcessExitFailsafeAlreadyArmed
                    | LegacyProcessExitFailsafeDisarmed ->
                        legacyProcessExitFailsafeState <- LegacyProcessExitFailsafeArmed
                        LegacyProcessExitFailsafeArmedNow)
            | LegacyTypedTerminalFailureRequested _
            | LegacyPostRootWriterLeaseExpired
            | LegacyProvisionalTypedTerminalFailureRequested
            | LegacyOtherExitObservation _ ->
                // Watchdog/failure requests are observations consumed by the reducer.
                // They never own physical exit; only an extreme host deadman may
                // engage the emergency process escape below.
                LegacyProcessExitFailsafeNotRequired

        let forceProcessExitDirect (code:int) (reason:LegacyProcessExitReasonId) =
            // Legacy callers may request an exit, but they cannot publish run_end,
            // claim the terminal latch, or freeze the live console projection.  The
            // reducer alone owns durable semantic exit; the typed extreme deadman below
            // is only a host escape after stable failed-closed evidence.
            let request = {
                code = code
                reason = reason
                kind = legacyProcessExitObservationKindFor reason
                observedAtUtc = System.DateTime.UtcNow
            }
            legacyProcessExitObserverRequests.Enqueue request
            let reasonText = legacyProcessExitReasonText reason
            let safeReason =
                reasonText.Replace("\"", "'").Replace("\r", " ").Replace("\n", " ")
            let safeKind =
                legacyProcessExitObservationKindText request.kind
                |> fun value -> value.Replace("\"", "'").Replace("\r", " ").Replace("\n", " ")
            let line =
                "{\"kind\":\"legacy_process_exit_observer_request\",\"event\":\"physical_exit_quarantined_until_scheduler_push_writer_receipt\",\"requested_exit_code\":"
                + string code
                + ",\"reason\":\"" + safeReason
                + "\",\"observation_kind_du\":\"" + safeKind
                + "\",\"run_end_emitted\":false,\"terminal_latch_claimed\":false,\"authority_du\":\"LegacyExitObserverOnly(scheduler_push_actor_owns_boundary)\",\"next\":\"await_scheduler_push_writer_receipt\"}"
            // Decide and arm any emergency host escape before touching presentation/telemetry.
            // The failed-closed watchdog exists precisely for cases where writer/HUD paths may
            // be wedged, so no synchronous observer write may precede the timer thread.
            let failsafeDecision = legacyProcessExitFailsafeDecisionFor request.kind
            match failsafeDecision with
            | LegacyProcessExitFailsafeArmedNow ->
                let failsafePolicy = legacy_process_exit_failsafe_policy
                let failsafeDelayMs = legacyProcessExitFailsafePolicyDelayMs failsafePolicy
                let failsafePolicyText = legacyProcessExitFailsafePolicyText failsafePolicy
                let failsafeLine =
                    sprintf "{\"kind\":\"physical_exit_failsafe_armed\",\"requested_exit_code\":%d,\"reason\":%s,\"deadline_ms\":%d,\"failsafe_policy_du\":%s,\"failsafe_mode_du\":\"single_shot_no_dead_cpu_hang\",\"semantic_success_authorized\":false,\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"authority_du\":\"emergency_host_deadman_only_not_terminal_authority\",\"policy\":\"emergency_host_escape_only_not_success_or_semantic_authority\"}"
                        code (esc safeReason) failsafeDelayMs (esc failsafePolicyText)
                let failsafePresentationEpilogueLine =
                    sprintf "{\"v\":2,\"kind\":\"terminal_presentation_epilogue\",\"boundary_du\":\"failsafe_pending_exit\",\"exit_code\":%d,\"host_exit_observed\":false,\"taskbar_shutdown_latched\":false,\"hud_tail_required\":false,\"control_authority\":false,\"terminal_stage_authority\":false,\"authority\":\"best_effort_pre_exit_presentation_breadcrumb\",\"next\":\"physical_exit_failsafe_firing_then_environment_exit\"}"
                        code
                let runner =
                    System.Threading.Thread(System.Threading.ThreadStart(fun () ->
                        try
                            System.Threading.Thread.Sleep(failsafeDelayMs)
                            lock legacyProcessExitFailsafeGate (fun () -> legacyProcessExitFailsafeState <- LegacyProcessExitFailsafeFiring)
                            // Emergency host escape must not depend on HUD/taskbar locks.
                            // The previous ordering could arm the deadman, wake it, then
                            // block forever in presentation cleanup before Environment.Exit.
                            let firingLine =
                                sprintf "{\"kind\":\"physical_exit_failsafe_firing\",\"requested_exit_code\":%d,\"reason\":%s,\"failsafe_policy_du\":%s,\"physical_exit_receipt_minted\":false,\"semantic_success_authorized\":false,\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"authority_du\":\"emergency_host_escape_timer_fired_not_semantic_terminal_receipt\",\"next\":\"invoke_environment_exit\"}"
                                    code (esc safeReason) (esc failsafePolicyText)
                            try startHopacJob (Hopac.Job.thunk (fun () -> try writeProgressHeartbeatLineDirect firingLine with _ -> ())) with _ -> ()
                            System.Environment.Exit(code)
                        with _ ->
                            try System.Environment.FailFast("Spiral terminal exit failsafe failed") with _ -> ()))
                runner.IsBackground <- true
                runner.Name <- "spiral-terminal-exit-failsafe"
                runner.Start()
                try startHopacJob (Hopac.Job.thunk (fun () -> try writeProgressHeartbeatLineDirect failsafeLine with _ -> ())) with _ -> ()
                try startHopacJob (Hopac.Job.thunk (fun () -> try writeProgressHeartbeatLineDirect failsafePresentationEpilogueLine with _ -> ())) with _ -> ()
            | LegacyProcessExitFailsafeAlreadyArmed
            | LegacyProcessExitFailsafeNotRequired ->
                ()
            // Observer telemetry is best-effort and may never be allowed to delay arming/firing.
            try startHopacJob (Hopac.Job.thunk (fun () -> try writeProgressHeartbeatLineDirect line with _ -> ())) with _ -> ()

        type private ProgressObserverDrainHookState =
            | ProgressObserverDrainHookUnavailable
            | ProgressObserverDrainHookInstalled of hook:(string -> CompilerKernelV2.OperationalReasonId -> int -> bool)

        type ProgressObserverDrainRequestOutcome =
            | ProgressObserverDrainAccepted
            | ProgressObserverDrainRejected
            | ProgressObserverDrainUnavailable
            | ProgressObserverDrainFaulted of exceptionType:string

        let mutable private progressObserverDrainHookState = ProgressObserverDrainHookUnavailable

        let registerProgressObserverDrainRequestHook (hook: string -> CompilerKernelV2.OperationalReasonId -> int -> bool) =
            progressObserverDrainHookState <- ProgressObserverDrainHookInstalled hook

        let progressObserverDrainRequestOutcomeId (event: string) (reasonId: CompilerKernelV2.OperationalReasonId) (attempts: int) =
            match progressObserverDrainHookState with
            | ProgressObserverDrainHookInstalled hook ->
                try
                    if hook event reasonId attempts then ProgressObserverDrainAccepted
                    else ProgressObserverDrainRejected
                with ex ->
                    ProgressObserverDrainFaulted(ex.GetType().FullName)
            | ProgressObserverDrainHookUnavailable ->
                ProgressObserverDrainUnavailable

        let requestProgressObserverDrainId (event: string) (reasonId: CompilerKernelV2.OperationalReasonId) (attempts: int) =
            match progressObserverDrainRequestOutcomeId event reasonId attempts with
            | ProgressObserverDrainAccepted -> true
            | ProgressObserverDrainRejected
            | ProgressObserverDrainUnavailable
            | ProgressObserverDrainFaulted _ -> false

        // The terminal reducer can observe semantic work that belongs to the JP scheduler,
        // while EvalWorklist is already empty.  Keep a typed bridge so ForceReplayDrain
        // targets the data plane that actually owns the outstanding semantic work.
        type private SemanticSchedulerDrainHookState =
            | SemanticSchedulerDrainHookUnavailable
            | SemanticSchedulerDrainHookInstalled of hook:(string -> int -> bool)

        type SemanticSchedulerDrainRequestOutcome =
            | SemanticSchedulerDrainAccepted
            | SemanticSchedulerDrainRejected
            | SemanticSchedulerDrainUnavailable
            | SemanticSchedulerDrainFaulted of exceptionType:string

        let mutable private semanticSchedulerDrainHookState = SemanticSchedulerDrainHookUnavailable

        let registerSemanticSchedulerDrainRequestHook (hook: string -> int -> bool) =
            semanticSchedulerDrainHookState <- SemanticSchedulerDrainHookInstalled hook

        let semanticSchedulerDrainRequestOutcomeId (reason: string) (attempts: int) =
            match semanticSchedulerDrainHookState with
            | SemanticSchedulerDrainHookInstalled hook ->
                try
                    if hook reason attempts then SemanticSchedulerDrainAccepted
                    else SemanticSchedulerDrainRejected
                with ex ->
                    SemanticSchedulerDrainFaulted(ex.GetType().FullName)
            | SemanticSchedulerDrainHookUnavailable ->
                SemanticSchedulerDrainUnavailable

        let requestSemanticSchedulerDrainId (reason: string) (attempts: int) =
            match semanticSchedulerDrainRequestOutcomeId reason attempts with
            | SemanticSchedulerDrainAccepted -> true
            | SemanticSchedulerDrainRejected
            | SemanticSchedulerDrainUnavailable
            | SemanticSchedulerDrainFaulted _ -> false

        // Public fail-closed seam for structured compiler errors discovered outside
        // the heartbeat thread. It preserves one durable JSONL terminal receipt before
        // the process exits, so BuildErrorTrace cannot linger as background churn.
        let private enrichTerminalDurableJsonLine (line: string) =
            let trimmed = if System.Object.ReferenceEquals(line,null) then "" else line.Trim()
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let pid = string (System.Environment.ProcessId)
            let tid = string (System.Threading.Thread.CurrentThread.ManagedThreadId)
            let withEnvelope =
                match jsonObjectEnvelopeId trimmed with
                | JsonEnvelopeV1Object -> trimmed
                | JsonEnvelopeObject ->
                    let body = trimmed.Substring(1, trimmed.Length - 2)
                    FastRuntimeFormat.format "{\"v\":1,\"ts_ms\":%d,\"pid\":%s,\"tid\":%s,\"run_id\":%s,%s}" [| box now; box pid; box tid; box (esc run_id); box body |]
                | JsonEnvelopeOther ->
                    FastRuntimeFormat.format "{\"v\":1,\"ts_ms\":%d,\"pid\":%s,\"tid\":%s,\"run_id\":%s,\"kind\":\"terminal_diag\",\"msg\":%s}" [| box now; box pid; box tid; box (esc run_id); box (esc trimmed) |]
            let startMs =
                if progressPredictionStartMs <= 0L then
                    progressPredictionStartMs <- now
                    now
                else progressPredictionStartMs
            let elapsedMs = max 0L (now - startMs)
            let authoritativeSnapshot = progressPredictionAuthoritativeRead()
            let sourceAgeMs = if authoritativeSnapshot.snapshotMs <= 0L then System.Int64.MaxValue else max 0L (now - authoritativeSnapshot.snapshotMs)
            let progressBp = authoritativeSnapshot.work.midBp
            let etaCandidate = CompilerConsoleHud88.reducerHudEtaP50Seconds authoritativeSnapshot
            let etaS = if sourceAgeMs <= 15000L && 0L <= etaCandidate && etaCandidate <= 86400L then etaCandidate else -1L
            let terminalClosed = terminalFailureExitRequestedNow()
            let durableCompletion = CompilerConsoleHud88.progressHudTerminalExactNow()
            // Durable JSON enrichment is observation-only. Build-work completion and
            // terminal-protocol completion are distinct facts; the legacy progress_pct
            // remains capped until reducer-owned run_end is durable.
            let projectedProgressBp = if durableCompletion then progressBp else min 9999L progressBp
            let projectedEtaS = if terminalClosed then -1L else etaS
            let terminalFailureExitState = if terminalClosed then 1 else 0
            let terminalOutcomeDu = if terminalClosed then "FailedClosed" else "OpenOrSuccessful"
            let progressCompletionAuthority =
                if durableCompletion then "durable_run_end_committed"
                else "durable_terminal_pending"
            let appendIfMissing field serializedValue =
                match jsonFieldPresenceId field withEnvelope with
                | JsonFieldPresent -> None
                | JsonFieldAbsent -> Some (string '"' + field + string '"' + ":" + serializedValue)
            // The durable codec owns field uniqueness. Semantic events may already carry
            // their own authoritative progress/ETA; enrichment only fills absent fields.
            let additions =
                [
                    appendIfMissing "elapsed_s" (string (elapsedMs / 1000L))
                    appendIfMissing "elapsed_ms" (string elapsedMs)
                    appendIfMissing "progress_pct" (FastRuntimeFormat.format "%.2f" [| box (float projectedProgressBp / 100.0) |])
                    appendIfMissing "build_work_progress_pct" (FastRuntimeFormat.format "%.2f" [| box (float progressBp / 100.0) |])
                    appendIfMissing "terminal_protocol_complete" (if durableCompletion then "true" else "false")
                    appendIfMissing "progress_completion_authority_du" (esc progressCompletionAuthority)
                    appendIfMissing "eta_s" (string projectedEtaS)
                    appendIfMissing "terminal_failure_exit_state" (string terminalFailureExitState)
                    appendIfMissing "terminal_outcome_du" (esc terminalOutcomeDu)
                    appendIfMissing "terminal_line_enriched" "true"
                ]
                |> List.choose id
            if List.isEmpty additions || not (withEnvelope.EndsWith("}", System.StringComparison.Ordinal)) then withEnvelope
            else withEnvelope.Substring(0, withEnvelope.Length - 1) + "," + String.concat "," additions + "}"

        let emitTerminalJsonDurable (line: string) =
            writeProgressHeartbeatTerminalLineDurable (compactJsonLineIfLarge (enrichTerminalDurableJsonLine line)) |> ignore

        let emitTerminalJsonDurableJob (line:string) =
            CompilerConsoleHud88.tryWriteProgressJsonLineTerminalDurableJob
                (compactJsonLineIfLarge (enrichTerminalDurableJsonLine line))

        let emitTerminalFailureJsonDurableJob (code:int) (line:string) =
            CompilerConsoleHud88.tryWriteProgressJsonLineTerminalFailureDurableJob
                code
                (compactJsonLineIfLarge (enrichTerminalDurableJsonLine line))

        let emitTerminalFailureJsonDurable (code:int) (line:string) =
            CompilerConsoleHud88.tryWriteProgressJsonLineTerminalFailureDurable code (compactJsonLineIfLarge (enrichTerminalDurableJsonLine line))
            |> ignore

        let emitRunEndJsonDurable (code:int) (line:string) =
            CompilerConsoleHud88.tryWriteProgressJsonLineRunEndDurable code (compactJsonLineIfLarge (enrichTerminalDurableJsonLine line))
            |> ignore

        // Destructive authority migration: absence of authority is no longer
        // representable at the run_end or physical-exit boundary.  Raw uint32 refs
        // may be inspected by renderers, but only this private capability crosses
        // into durable terminal effects.
        type TerminalJsonExitAuthority = private | TerminalJsonExitAuthority of terminalAuthorityRef:uint32 * endToEndSealRef:uint32 * runEndReceiptRef:uint32 * physicalExitReceiptRef:uint32

        type TerminalJsonExitAuthorityMintFailure =
            | TerminalJsonTerminalAuthorityMissing
            | TerminalJsonEndToEndSealMissing
            | TerminalJsonRunEndReceiptMissing
            | TerminalJsonPhysicalExitReceiptMissing

        type TerminalJsonPhysicalExitReasonId =
            | TerminalJsonExitWriterArtifactCommitted
            | TerminalJsonExitTypedFailure
            | TerminalJsonExitContractFallback

        let terminalJsonPhysicalExitReasonText = function
            | TerminalJsonExitWriterArtifactCommitted -> "terminal_flow_writer_artifact_committed"
            | TerminalJsonExitTypedFailure -> "terminal_flow_typed_failure"
            | TerminalJsonExitContractFallback -> "native_terminal_exit_contract"

        let tryMintTerminalJsonExitAuthority terminalAuthorityRef endToEndSealRef runEndReceiptRef physicalExitReceiptRef =
            if terminalAuthorityRef = 0u then Error TerminalJsonTerminalAuthorityMissing
            elif endToEndSealRef = 0u then Error TerminalJsonEndToEndSealMissing
            elif runEndReceiptRef = 0u then Error TerminalJsonRunEndReceiptMissing
            elif physicalExitReceiptRef = 0u then Error TerminalJsonPhysicalExitReceiptMissing
            else Ok (TerminalJsonExitAuthority(terminalAuthorityRef, endToEndSealRef, runEndReceiptRef, physicalExitReceiptRef))

        let terminalJsonExitAuthorityMintFailureText = function
            | TerminalJsonTerminalAuthorityMissing -> "terminal_authority_missing"
            | TerminalJsonEndToEndSealMissing -> "end_to_end_seal_missing"
            | TerminalJsonRunEndReceiptMissing -> "run_end_receipt_missing"
            | TerminalJsonPhysicalExitReceiptMissing -> "physical_exit_receipt_missing"

        let private terminalJsonExitAuthorityRefs (TerminalJsonExitAuthority(terminalAuthorityRef, endToEndSealRef, runEndReceiptRef, physicalExitReceiptRef)) =
            terminalAuthorityRef, endToEndSealRef, runEndReceiptRef, physicalExitReceiptRef

        let acknowledgeTerminalJsonRunEndReceiptWithAuthorityOnceJob (authority:TerminalJsonExitAuthority) (code:int) reasonId (line:string) (stopReason:string) =
            job {
                let terminalAuthorityRef, endToEndSealRef, runEndReceiptRef, physicalExitReceiptRef = terminalJsonExitAuthorityRefs authority
                let safeReason = terminalJsonPhysicalExitReasonText reasonId
                let claimRef =
                    NativeCutoverStableRef.ref32
                        "terminal-json-run-end-claim"
                        [ safeReason; string code; string runEndReceiptRef ]
                let! claimed = terminalFlowRunEndTryClaimJob claimRef
                if claimed then
                    let root = canonicalRootAuthoritySnapshot()
                    let actor = terminalSchedulerPushActorSnapshot()
                    let runEndLine =
                        "{\"kind\":\"terminal_run_end_receipt_consumed_by_physical_boundary\",\"run_id\":" + esc run_id
                        + ",\"exit_code\":" + string code
                        + ",\"reason\":" + esc safeReason
                        + ",\"run_end_emitted\":false,\"canonical_run_end_already_emitted\":true,\"capture_complete\":true,\"capture_stop_reason_du\":" + esc stopReason
                        + ",\"last_durable_receipt_ref\":" + string (NativeCutoverStableRef.ref32 "terminal-json-durable-line" [ line ])
                        + ",\"root_receipt_ref\":" + string (NativeCutoverStableRef.ref32 "terminal-json-root-receipt" [ root.receiptId ])
                        + ",\"root_source\":" + esc root.source
                        + ",\"push_actor_phase\":" + esc (terminalSchedulerPushActorPhaseText actor.phase)
                        + ",\"push_actor_fill_ref\":" + string (NativeCutoverStableRef.ref32 "terminal-json-actor-fill" [ actor.fillKey ])
                        + ",\"push_actor_dispatch_ref\":" + string (NativeCutoverStableRef.ref32 "terminal-json-actor-dispatch" [ actor.dispatchId ])
                        + ",\"terminal_authority_ref\":" + string terminalAuthorityRef
                        + ",\"end_to_end_seal_ref\":" + string endToEndSealRef
                        + ",\"run_end_receipt_ref\":" + string runEndReceiptRef
                        + ",\"physical_exit_receipt_ref\":" + string physicalExitReceiptRef
                        + ",\"terminal_authority_chain_required\":true,\"authority_capability_typed\":true,\"renderer_authority\":false,\"prose_authority\":false"
                        + "}"
                    let! persisted =
                        CompilerConsoleHud88.tryWriteProgressJsonLineRunEndDurableJob
                            code
                            (compactJsonLineIfLarge (enrichTerminalDurableJsonLine runEndLine))
                    if persisted then
                        do! terminalFlowRunEndMarkDurableJob claimRef runEndReceiptRef
                    else
                        do! terminalFlowRunEndReleaseClaimJob claimRef
            }

        let private durableTerminalObserverReceiptKeys =
            System.Collections.Concurrent.ConcurrentDictionary<int, byte>()

        type TerminalPhysicalExitBoundaryLatch =
            | TerminalPhysicalExitBoundaryOpen
            | TerminalPhysicalExitBoundarySelected of exitCode:int * physicalExitReceiptRef:uint32

        type TerminalPhysicalExitBoundarySelection =
            | TerminalPhysicalExitSelectionGranted of exitCode:int * physicalExitReceiptRef:uint32
            | TerminalPhysicalExitSelectionAlreadyHeld of exitCode:int * physicalExitReceiptRef:uint32

        type TerminalPhysicalExitJournalDecision =
            | TerminalPhysicalExitJournalRecorded
            | TerminalPhysicalExitJournalLagReconciledByReducerAuthority

        let private terminalPhysicalExitBoundaryGate = obj()
        let mutable private terminalPhysicalExitBoundaryLatch = TerminalPhysicalExitBoundaryOpen

        let private selectTerminalPhysicalExitBoundary code physicalExitReceiptRef =
            lock terminalPhysicalExitBoundaryGate (fun () ->
                match terminalPhysicalExitBoundaryLatch with
                | TerminalPhysicalExitBoundaryOpen ->
                    terminalPhysicalExitBoundaryLatch <- TerminalPhysicalExitBoundarySelected(code, physicalExitReceiptRef)
                    TerminalPhysicalExitSelectionGranted(code, physicalExitReceiptRef)
                | TerminalPhysicalExitBoundarySelected(existingCode, existingReceiptRef) ->
                    TerminalPhysicalExitSelectionAlreadyHeld(existingCode, existingReceiptRef))

        // Observer-side terminal evidence is no longer discarded at the physical
        // boundary.  It becomes a typed petition that can be consumed only by the
        // process-global TerminalFlow reducer.  The payload carries the complete
        // owner/work-DAG/scheduler/semantic covenant, so the reducer never needs to
        // rediscover a mature verdict by scraping the durable JSON projection.
        type ObserverTerminalProjectionClass =
            | ObserverProjectionParentPoisonQuorumClosed
            | ObserverProjectionCooperativeTickNativePromiseFailure
            | ObserverProjectionReplayDriverNativePromiseFailure
            | ObserverProjectionOwnerDebtTieBreakerExhausted
            | ObserverProjectionPevalTimeoutOwnerDebtDrainDeadline
            | ObserverProjectionBuildRetryVetoed

        let observerTerminalProjectionClassText = function
            | ObserverProjectionParentPoisonQuorumClosed -> "ParentPoisonQuorumClosed"
            | ObserverProjectionCooperativeTickNativePromiseFailure -> "CooperativeTickNativePromiseFailure"
            | ObserverProjectionReplayDriverNativePromiseFailure -> "ReplayDriverNativePromiseFailure"
            | ObserverProjectionOwnerDebtTieBreakerExhausted -> "OwnerDebtTieBreakerExhausted"
            | ObserverProjectionPevalTimeoutOwnerDebtDrainDeadline -> "PevalTimeoutOwnerDebtDrainDeadline"
            | ObserverProjectionBuildRetryVetoed -> "BuildRetryVetoed"

        let observerTerminalProjectionClassRef projectionClass =
            NativeCutoverStableRef.ref32
                "observer-terminal-projection-class"
                [ observerTerminalProjectionClassText projectionClass ]

        type ObserverTerminalExitPetitionOrigin =
            | ObserverExitBigStackOwnerDeadlockClosed
            | ObserverExitLegacyProjection of ObserverTerminalProjectionClass

        type ObserverTerminalDocument =
            | ObserverTerminalReducerCandidateDocument of documentRef:uint32 * canonicalLine:string
            | ObserverTerminalProjectionDocument of documentRef:uint32 * canonicalLine:string

        let observerTerminalDocumentRef = function
            | ObserverTerminalReducerCandidateDocument(documentRef, _)
            | ObserverTerminalProjectionDocument(documentRef, _) -> documentRef

        let observerTerminalDocumentLine = function
            | ObserverTerminalReducerCandidateDocument(_, line)
            | ObserverTerminalProjectionDocument(_, line) -> line

        let observerTerminalDocumentCanAuthorize = function
            | ObserverTerminalReducerCandidateDocument(documentRef, line) ->
                documentRef <> 0u && not (System.String.IsNullOrWhiteSpace line)
            | ObserverTerminalProjectionDocument _ -> false

        type ObserverTerminalOwnerClosureProvenance =
            | ObserverOwnerClosureFromReducer
            | ObserverOwnerClosureFromBigStackReconciliation

        type ObserverTerminalOwnerClosureCertificate = private {
            certificateRef : uint32
            provenance : ObserverTerminalOwnerClosureProvenance
            ownerLedgerRef : uint32
            workDagClosureRef : uint32
            schedulerCausalityRef : uint32
            semanticDebtRef : uint32
            qapResolutionRef : uint32
        }

        type ObserverTerminalOwnerClosureAuthority =
            | ObserverOwnerClosureCertified of ObserverTerminalOwnerClosureCertificate
            | ObserverOwnerClosureProjectionOnly of sourceRef:uint32

        let private observerTerminalOwnerClosureCertificate provenance ownerLedgerRef workDagClosureRef schedulerCausalityRef semanticDebtRef qapResolutionRef =
            let provenanceText =
                match provenance with
                | ObserverOwnerClosureFromReducer -> "reducer"
                | ObserverOwnerClosureFromBigStackReconciliation -> "bigstack_reconciliation"
            let certificateRef =
                NativeCutoverStableRef.ref32
                    "observer-terminal-owner-closure-certificate"
                    [ provenanceText
                      string ownerLedgerRef
                      string workDagClosureRef
                      string schedulerCausalityRef
                      string semanticDebtRef
                      string qapResolutionRef ]
            { certificateRef = certificateRef
              provenance = provenance
              ownerLedgerRef = ownerLedgerRef
              workDagClosureRef = workDagClosureRef
              schedulerCausalityRef = schedulerCausalityRef
              semanticDebtRef = semanticDebtRef
              qapResolutionRef = qapResolutionRef }

        let observerTerminalOwnerClosureAuthorityText = function
            | ObserverOwnerClosureCertified certificate ->
                let provenanceText =
                    match certificate.provenance with
                    | ObserverOwnerClosureFromReducer -> "Reducer"
                    | ObserverOwnerClosureFromBigStackReconciliation -> "BigStackReconciliation"
                FastRuntimeFormat.format "OwnerClosureAuthority(Certified|provenance=%s|certificate_ref=%u|owner_ledger_ref=%u|workdag_ref=%u|scheduler_ref=%u|semantic_debt_ref=%u|qap_ref=%u)" [| box provenanceText; box certificate.certificateRef; box certificate.ownerLedgerRef; box certificate.workDagClosureRef; box certificate.schedulerCausalityRef; box certificate.semanticDebtRef; box certificate.qapResolutionRef |]
            | ObserverOwnerClosureProjectionOnly sourceRef ->
                sprintf "OwnerClosureAuthority(ProjectionOnly|source_ref=%u)" sourceRef

        let observerTerminalOwnerClosureAuthorityRef authority =
            NativeCutoverStableRef.ref32
                "observer-terminal-owner-closure-authority"
                [ observerTerminalOwnerClosureAuthorityText authority ]

        let observerTerminalOwnerClosureAuthorityCanFailClose = function
            | ObserverOwnerClosureCertified certificate ->
                certificate.certificateRef <> 0u
                && certificate.ownerLedgerRef <> 0u
                && certificate.workDagClosureRef <> 0u
                && certificate.schedulerCausalityRef <> 0u
                && certificate.semanticDebtRef <> 0u
            | ObserverOwnerClosureProjectionOnly _ -> false

        type ObserverTerminalExitPetitionEvidence = {
            petitionRef : uint32
            origin : ObserverTerminalExitPetitionOrigin
            ownerClosureAuthority : ObserverTerminalOwnerClosureAuthority
            terminalReceiptRef : uint32
            ownerClosureRef : uint32
            workDagClosureRef : uint32
            schedulerCausalityRef : uint32
            semanticDebtRef : uint32
            requestedExitCode : int
            sourceRowRef : string
            terminalDocument : ObserverTerminalDocument
            observedAtMs : int64
        }

        let observerTerminalExitPetitionCanFailClose petition =
            observerTerminalOwnerClosureAuthorityCanFailClose petition.ownerClosureAuthority
            && observerTerminalDocumentCanAuthorize petition.terminalDocument
            && petition.terminalReceiptRef <> 0u
            && petition.ownerClosureRef <> 0u
            && petition.workDagClosureRef <> 0u
            && petition.schedulerCausalityRef <> 0u
            && petition.semanticDebtRef <> 0u

        let private observerTerminalExitPetitionGate = obj()
        let mutable private observerTerminalExitPetitionPublisher : (ObserverTerminalExitPetitionEvidence -> unit) option = None
        let private observerTerminalExitPetitionBacklog = ResizeArray<ObserverTerminalExitPetitionEvidence>()

        let installObserverTerminalExitPetitionPublisher publisher =
            let backlog =
                lock observerTerminalExitPetitionGate (fun () ->
                    observerTerminalExitPetitionPublisher <- Some publisher
                    let pending = observerTerminalExitPetitionBacklog.ToArray()
                    observerTerminalExitPetitionBacklog.Clear()
                    pending)
            backlog |> Array.iter publisher

        let publishObserverTerminalExitPetition (petition:ObserverTerminalExitPetitionEvidence) =
            let key = int petition.petitionRef
            if durableTerminalObserverReceiptKeys.TryAdd(key, 0uy) then
                match petition.terminalDocument with
                | ObserverTerminalReducerCandidateDocument _ ->
                    emitTerminalJsonDurable (observerTerminalDocumentLine petition.terminalDocument)
                | ObserverTerminalProjectionDocument(documentRef, _) ->
                    emitTerminalJsonDurable (
                        sprintf "{\"kind\":\"observer_terminal_projection_quarantined\",\"document_ref\":%u,\"petition_ref\":%u,\"physical_exit\":false,\"authority\":\"projection_only\"}"
                            documentRef petition.petitionRef)
                let publisher =
                    lock observerTerminalExitPetitionGate (fun () ->
                        match observerTerminalExitPetitionPublisher with
                        | Some publisher -> Some publisher
                        | None ->
                            observerTerminalExitPetitionBacklog.Add petition
                            None)
                match publisher with
                | Some publisher -> publisher petition
                | None ->
                    emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"observer_terminal_exit_petition_buffered\",\"petition_ref\":%u,\"terminal_receipt_ref\":%u,\"owner_closure_ref\":%u,\"owner_closure_authority_ref\":%u,\"owner_closure_authority_du\":%s,\"workdag_closure_ref\":%u,\"scheduler_causality_ref\":%u,\"semantic_debt_ref\":%u,\"requested_exit_code\":%d,\"physical_exit\":false,\"reason_du\":\"ReducerPublisherNotInstalledYet\"}" [| box petition.petitionRef; box petition.terminalReceiptRef; box petition.ownerClosureRef; box (observerTerminalOwnerClosureAuthorityRef petition.ownerClosureAuthority); box (esc (observerTerminalOwnerClosureAuthorityText petition.ownerClosureAuthority)); box petition.workDagClosureRef; box petition.schedulerCausalityRef; box petition.semanticDebtRef; box petition.requestedExitCode |])

        let observerTerminalExitPetitionForBigStackOwnerDeadlock
            terminalReceiptId
            sourceRowRef
            closureId
            pending
            queueDepth
            activeDepth
            waitedMs
            durableLine =
            let identity =
                FastRuntimeFormat.format "bigstack-owner-deadlock:%s:%s:%s:%d:%d:%d:%d" [| box terminalReceiptId; box sourceRowRef; box closureId; box pending; box queueDepth; box activeDepth; box waitedMs |]
            let ownerClosureRef = NativeCutoverStableRef.ref32 "observer-owner-closure" [ identity ]
            let workDagClosureRef = NativeCutoverStableRef.ref32 "observer-workdag-closure" [ identity ]
            let schedulerCausalityRef = NativeCutoverStableRef.ref32 "observer-scheduler-causality" [ identity ]
            let semanticDebtRef = NativeCutoverStableRef.ref32 "observer-semantic-debt" [ identity ]
            let qapResolutionRef = NativeCutoverStableRef.ref32 "observer-qap-resolution" [ identity ]
            let ownerClosureCertificate =
                observerTerminalOwnerClosureCertificate
                    ObserverOwnerClosureFromBigStackReconciliation
                    ownerClosureRef
                    workDagClosureRef
                    schedulerCausalityRef
                    semanticDebtRef
                    qapResolutionRef
            { petitionRef = NativeCutoverStableRef.ref32 "observer-terminal-exit-petition" [ identity ]
              origin = ObserverExitBigStackOwnerDeadlockClosed
              ownerClosureAuthority = ObserverOwnerClosureCertified ownerClosureCertificate
              terminalReceiptRef = NativeCutoverStableRef.ref32 "observer-terminal-receipt" [ terminalReceiptId ]
              ownerClosureRef = ownerClosureRef
              workDagClosureRef = workDagClosureRef
              schedulerCausalityRef = schedulerCausalityRef
              semanticDebtRef = semanticDebtRef
              requestedExitCode = 1
              sourceRowRef = sourceRowRef
              terminalDocument =
                  ObserverTerminalReducerCandidateDocument(
                      NativeCutoverStableRef.ref32 "observer-terminal-document" [ identity ],
                      durableLine)
              observedAtMs = Environment.TickCount64 }

        let emitTerminalJsonDurableAndExitSingleFlight projectionClass (line: string) =
            // Projection rows can never authorize physical exit. Their identity must
            // therefore be stable by semantic class, not by a dynamic JSON payload.
            // The durable single-flight map admits at most one reducer petition for
            // each closed class and suppresses the unbounded revision flood.
            let petitionRef = observerTerminalProjectionClassRef projectionClass
            publishObserverTerminalExitPetition {
                petitionRef = petitionRef
                origin = ObserverExitLegacyProjection projectionClass
                ownerClosureAuthority = ObserverOwnerClosureProjectionOnly petitionRef
                terminalReceiptRef = 0u
                ownerClosureRef = 0u
                workDagClosureRef = 0u
                schedulerCausalityRef = 0u
                semanticDebtRef = 0u
                requestedExitCode = 1
                sourceRowRef = observerTerminalProjectionClassText projectionClass
                terminalDocument = ObserverTerminalProjectionDocument(petitionRef, line)
                observedAtMs = Environment.TickCount64
            }

        let emitTerminalJsonDurableAndPhysicalExitJob (authority:TerminalJsonExitAuthority) (code:int) reasonId (line:string) =
            job {
                let terminalAuthorityRef, endToEndSealRef, runEndReceiptRef, physicalExitReceiptRef = terminalJsonExitAuthorityRefs authority
                match selectTerminalPhysicalExitBoundary code physicalExitReceiptRef with
                | TerminalPhysicalExitSelectionGranted _ ->
                    let key = if isNull line then code else line.GetHashCode() ^^^ code
                    if durableTerminalObserverReceiptKeys.TryAdd(key, 0uy) then
                        if code = 0 then
                            let! _ = emitTerminalJsonDurableJob line
                            ()
                        else
                            let! _ = emitTerminalFailureJsonDurableJob code line
                            ()
                    terminalFailureExitMarkCommitted code
                    let safeReason = terminalJsonPhysicalExitReasonText reasonId
                    let! journalRecorded =
                        terminalFlowKernelJournalRecordStageJob
                            CompilerKernelV2.KernelPhysicalExitSelected
                            physicalExitReceiptRef
                    let journalDecision =
                        if journalRecorded then TerminalPhysicalExitJournalRecorded
                        else TerminalPhysicalExitJournalLagReconciledByReducerAuthority
                    let journalDecisionText =
                        match journalDecision with
                        | TerminalPhysicalExitJournalRecorded -> "journal_recorded"
                        | TerminalPhysicalExitJournalLagReconciledByReducerAuthority -> "journal_lag_reconciled_by_reducer_authority"
                    let exitLine =
                        "{\"kind\":\"native_terminal_exit_contract_physical_boundary\",\"event\":\"post_root_terminal_commit_emission\",\"exit_code\":"
                        + string code
                        + ",\"reason\":\"" + safeReason
                        + "\",\"terminal_authority_ref\":" + string terminalAuthorityRef
                        + ",\"end_to_end_seal_ref\":" + string endToEndSealRef
                        + ",\"run_end_receipt_ref\":" + string runEndReceiptRef
                        + ",\"physical_exit_receipt_ref\":" + string physicalExitReceiptRef
                        + ",\"journal_decision_du\":\"" + journalDecisionText
                        + "\",\"physical_exit_boundary_committed\":true,\"physical_exit_boundary_commit_state_du\":\"CommittedByBoundaryOwner\",\"authority_du\":\"TerminalCommitEmissionContract(typed_exit_authority_capability=true|physical_exit_required=true)\",\"terminal_authority_chain_required\":true,\"authority_capability_typed\":true,\"renderer_authority\":false,\"prose_authority\":false,\"next\":\"process_exit\"}"
                    let! _ = emitTerminalJsonDurableJob exitLine
                    ()
                    match journalDecision with
                    | TerminalPhysicalExitJournalRecorded -> ()
                    | TerminalPhysicalExitJournalLagReconciledByReducerAuthority ->
                        let! _ =
                            emitTerminalJsonDurableJob (
                                "{\"kind\":\"terminal_kernel_physical_exit_journal_lag_reconciled\",\"exit_code\":"
                                + string code
                                + ",\"terminal_authority_ref\":" + string terminalAuthorityRef
                                + ",\"run_end_receipt_ref\":" + string runEndReceiptRef
                                + ",\"physical_exit_receipt_ref\":" + string physicalExitReceiptRef
                                + ",\"reducer_total_order_authoritative\":true,\"journal_veto_authority\":false,\"physical_exit\":true}"
                            )
                        ()
                    try CompilerConsoleHud88.completeTerminalPresentationForPhysicalExit code runEndReceiptRef physicalExitReceiptRef with _ -> ()
                    try System.Console.Error.Flush() with _ -> ()
                    try System.Console.Out.Flush() with _ -> ()
                    System.Environment.Exit(code)
                | TerminalPhysicalExitSelectionAlreadyHeld(existingCode, existingReceiptRef) ->
                    let! _ =
                        emitTerminalJsonDurableJob (
                            "{\"kind\":\"native_terminal_exit_contract_physical_boundary_coalesced\",\"exit_code\":"
                            + string code
                            + ",\"physical_exit_receipt_ref\":" + string physicalExitReceiptRef
                            + ",\"selected_exit_code\":" + string existingCode
                            + ",\"selected_physical_exit_receipt_ref\":" + string existingReceiptRef
                            + ",\"authority_du\":\"TerminalPhysicalExitBoundarySelected\",\"physical_exit_owner\":false,\"next\":\"await_selected_boundary\"}"
                        )
                    ()
            }

