        let private emitProgressPredictionTickIfDue () =
            emitProgressPredictionTick false 0L "DiagJson.emit_opportunistic" false

        let private emitProgressPredictionTickMetronome (scheduledMs: int64) =
            emitTrueMetronomeBeat scheduledMs
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let beatNo = (progressPredictionMetronomeRead()).beatTick
            let lastRichMs = (progressPredictionRichLedgerRead()).tickMs
            let richAgeMs = if lastRichMs > 0L then max 0L (now - lastRichMs) else 999999L
            let shouldQueueRich =
                lastRichMs = 0L
                || (beatNo <= 8L && richAgeMs >= progressPredictionMinimalCadenceMs)
                || richAgeMs >= progressPredictionRichCadenceMs
            if shouldQueueRich && lock progressPredictionTickGate (fun () -> if progressPredictionRichTickInFlight = 0 then progressPredictionRichTickInFlight <- 1; true else false) then
                lock progressPredictionTickGate (fun () -> progressPredictionRichTickStartedMs <- now)
                try
                    let richRunner =
                        System.Threading.ThreadStart(fun () ->
                            try
                                emitProgressPredictionTick true scheduledMs "DiagJson.true_metronome_rich_diag_async" true
                            finally
                                lock progressPredictionTickGate (fun () -> progressPredictionRichTickInFlight <- 0))
                    let richThread = System.Threading.Thread(richRunner)
                    richThread.IsBackground <- true
                    richThread.Name <- "spiral-progress-rich-diagnostic"
                    richThread.Start()
                with _ ->
                    lock progressPredictionTickGate (fun () -> progressPredictionRichTickInFlight <- 0)

        let private progressPredictionHeartbeatStarted =
            lazy (
                try
                    // MIGRATION: metronome diagnostics call synchronous mailbox
                    // projections. Keep this observer on its own background thread so
                    // it can never nest Hopac.run inside the compiler scheduler.
                    let loop =
                        System.Threading.ThreadStart(fun () ->
                            let cadenceMs = progressPredictionMinimalCadenceMs
                            let mutable nextDueMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() + cadenceMs
                            while not (CompilerConsoleHud88.progressHudPresentationClosedNow()) do
                                try
                                    let mutable nowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                                    while nowMs < nextDueMs && not (CompilerConsoleHud88.progressHudPresentationClosedNow()) do
                                        // 1-5 ms sleeps kept this observer thread ~7% busy; quiet (batch) runs have no
                                        // visible clock to keep smooth, so they wait in 25 ms steps (fix 37).
                                        let sleepMs = int (min (if quiet then 25L else 5L) (max 1L (nextDueMs - nowMs)))
                                        System.Threading.Thread.Sleep(sleepMs)
                                        nowMs <- System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                                    if not (CompilerConsoleHud88.progressHudPresentationClosedNow()) then
                                        // After a typed terminal failure the HUD clock remains live,
                                        // but metronome semantic work stays latched off.
                                        if not (terminalFailureExitRequestedNow()) then
                                            try emitProgressPredictionTickMetronome nextDueMs with _ -> ()
                                        // Terminal ledger liveness is semantic observer work. Keep it
                                        // off the 50 ms visible clock so reducer contention cannot
                                        // freeze elapsed/ETA presentation.
                                        let terminalLedgerHeartbeatNowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                                        let terminalLedgerHeartbeatDue =
                                            lock progressHudTerminalLedgerHeartbeatGate (fun () ->
                                                if progressHudTerminalLedgerHeartbeatLastMs = 0L
                                                   || terminalLedgerHeartbeatNowMs - progressHudTerminalLedgerHeartbeatLastMs >= progressHudTerminalLedgerHeartbeatCadenceMs then
                                                    progressHudTerminalLedgerHeartbeatLastMs <- terminalLedgerHeartbeatNowMs
                                                    true
                                                else false)
                                        if terminalLedgerHeartbeatDue then
                                            try CompilerConsoleHud88.invokeTerminalLedgerHeartbeat () with _ -> ()
                                        try ensureProgressHudSmoothFrameTicker() with _ -> ()
                                    let afterMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                                    let nominalNextDueMs = nextDueMs + cadenceMs
                                    nextDueMs <- if afterMs >= nominalNextDueMs then afterMs + cadenceMs else nominalNextDueMs
                                with _ -> System.Threading.Thread.Sleep(5))
                    let th = System.Threading.Thread(loop)
                    th.IsBackground <- true
                    th.Name <- "spiral-progress-prediction-heartbeat"
                    th.Start()
                    true
                with _ -> false)

        let private ensureProgressPredictionHeartbeat () =
            try progressPredictionHeartbeatStarted.Force() |> ignore with _ -> ()

        // MIGRATION: replay/handoff receipts are not generic noise anymore.
        // The 1237 log proved the graph can move while the rich heartbeat is stale,
        // so these families get a much denser typed cadence.
        type JsonTelemetryDetailId =
            | JsonTelemetryCritical
            | JsonTelemetryReplayDetail
            | JsonTelemetryHandoffDetail
            | JsonTelemetryCycleBreakDetail
            | JsonTelemetryObligationDetail
            | JsonTelemetryQueueChatter
            | JsonTelemetryDeprecatedChatter
            | JsonTelemetryHudDetail
            | JsonTelemetryGenericNoisy

        type JsonTelemetryTextSignalId =
            | JsonTelemetryQueueMarker
            | JsonTelemetryReplayMarker
            | JsonTelemetryHandoffMarker
            | JsonTelemetryStructuralNoiseMarker
            | JsonTelemetryBlockedStatusMarker
            | JsonTelemetryTerminalStatusMarker

        let private jsonTelemetryTextSignalMarkers =
            [ JsonTelemetryQueueMarker,
                [ "_children_registered"
                  "_tv_env_snapshot"
                  "_free_metavar_snapshot"
                  "_reentry_prefetch_replay_drained" ]
              JsonTelemetryReplayMarker,
                [ "replay_driver"
                  "replay_step"
                  "replay_reduce"
                  "replay_commit"
                  "parent_resume"
                  "typed_worklist_facade_active" ]
              JsonTelemetryHandoffMarker,
                [ "handoff"
                  "parent_continuation"
                  "queue_only_replay_driver" ]
              JsonTelemetryStructuralNoiseMarker,
                [ "_snapshot"
                  "_children_registered"
                  "_scheduled"
                  "_suppressed"
                  "_payload"
                  "_step"
                  "_consume"
                  "_wait_"
                  "_cached_children_"
                  "_children_resolved"
                  "_source_value_stored"
                  "_replay_"
                  "_parent_continuation"
                  "_terminal_"
                  "_handoff" ]
              JsonTelemetryBlockedStatusMarker, [ "blocked" ]
              JsonTelemetryTerminalStatusMarker, [ "terminal" ] ]

        let private jsonTelemetryTextSignalPatterns =
            jsonTelemetryTextSignalMarkers
            |> List.map (fun (signal, markers) ->
                signal,
                (markers
                 |> List.map diagnosticTextPatternForMarker))

        let private jsonTelemetryTextSignalsUncached (text:string) =
            let tokens = diagnosticTextTokensLower text
            let segments = diagnosticTextSegmentsLower text
            jsonTelemetryTextSignalPatterns
            |> List.choose (fun (signal, patterns) ->
                let present =
                    patterns
                    |> List.exists (diagnosticTextEvidencePatternMatches tokens segments)
                if present then Some signal else None)
            |> Set.ofList

        let private jsonTelemetrySignalsMemo = System.Collections.Concurrent.ConcurrentDictionary<string, _>(System.StringComparer.Ordinal)
        let private jsonTelemetryTextSignals (text:string) =
            if isNull text || text.Length > 512 then jsonTelemetryTextSignalsUncached text
            else
                let mutable signals = Unchecked.defaultof<_>
                if jsonTelemetrySignalsMemo.TryGetValue(text, &signals) then signals
                else
                    let signals = jsonTelemetryTextSignalsUncached text
                    if jsonTelemetrySignalsMemo.Count < 20000 then jsonTelemetrySignalsMemo.TryAdd(text, signals) |> ignore
                    signals

        let private jsonTelemetryDetailForKindUncached (kind: string) =
            let textSignals = jsonTelemetryTextSignals kind
            if System.String.IsNullOrWhiteSpace kind then JsonTelemetryCritical
            elif kind = "eval_worklist_parent_replay_key_dedupe"
                 || kind = "eval_worklist_replay_driver_stack_fence_yielded"
                 || kind = "eval_worklist_global_fuse_deferred_replay_queue_preserved"
                 || kind = "eval_worklist_single_flight_busy_no_sync_wait"
                 || kind = "eval_worklist_single_flight_reacquired_after_graph_tick"
                 || kind = "eval_worklist_orphan_global_fuse_live_replay_deferred"
                 || kind = "eval_worklist_ty_orphan_global_fuse_live_replay_deferred"
                 || kind = "eval_worklist_root_complete_stale_retarget_suppressed_after_witness_no_reinsert"
                 || kind = "eval_worklist_adapter"
                 || kind = "eval_worklist_cache_write_parent_handoff_enqueued"
                 || kind = "eval_worklist_global_fuse_deferred_replay_tick_requested"
                 || kind = "eval_worklist_parent_handoff_driver_wake_requested"
                 || kind = "eval_worklist_parent_continuation_explicit_enqueue"
                 || kind = "eval_worklist_bigstack_queue_only_replay_driver_tick_requested"
                 || kind = "eval_worklist_parent_replay_status_preserved"
                 || kind = "eval_worklist_typed_worklist_facade_active"
                 || Set.contains JsonTelemetryQueueMarker textSignals then JsonTelemetryQueueChatter
            elif kind = "eval_worklist_deferred_type_var_cycle_break_scheduled" then JsonTelemetryCycleBreakDetail
            elif kind = "eval_worklist_replay_obligation_deferred" then JsonTelemetryObligationDetail
            elif Set.contains JsonTelemetryReplayMarker textSignals then JsonTelemetryReplayDetail
            elif Set.contains JsonTelemetryHandoffMarker textSignals then JsonTelemetryHandoffDetail
            elif kind = "eval_worklist_hud_snapshot"
                 || kind = "rich_diag_busy"
                 || kind = "rich_diag_watchdog_reset" then JsonTelemetryHudDetail
            elif kind = "eval_worklist_forced_pressure_drain_worker_requested"
                 || kind = "eval_worklist_raise_retry_queue_surge_repeat_cap_probation_drain"
                 || kind = "eval_worklist_raise_retry_queue_surge_repeat_cap_probation_exhausted_parent_poison"
                 || kind = "eval_worklist_bigstack_replay_no_root_finish_budget"
                 || kind = "eval_worklist_bigstack_dynamic_join_terminal_deferred_for_live_replay"
                 || kind = "eval_worklist_bigstack_dynamic_join_pending_zero_no_writer_decision"
                 || kind = "eval_worklist_replay_queue_surge_parent_poison_suppressed_live_tail"
                 || kind = "eval_worklist_parent_replay_poison_repeat_cap_fresh_root_pin_suppressed"
                 || kind = "eval_worklist_live_replay_parent_replay_poison_pin_suppressed"
                 || kind = "eval_worklist_bigstack_hot_frontier_repeat_cap_probation_guard"
                 || kind = "eval_worklist_forced_active_tail_quiescent_no_queue"
                 || kind = "eval_worklist_replay_obligation_deferred_cross_kind_shielded"
                 || kind = "eval_worklist_cross_kind_yield_thrash_deferred_fresh_pending_tail"
                 || kind = "eval_worklist_cross_kind_yield_thrash_deferred_zero_repeat_active_tail"
                 || kind = "eval_worklist_cross_kind_live_tail_blocks_post_schedule_hard_poison"
                 || kind = "eval_worklist_queue_surge_repeated_deferral_matured"
                 || kind = "eval_worklist_bigstack_no_root_budget_pre_cap_active_tail_override_probation_drain"
                 || kind = "eval_worklist_bigstack_pinned_terminal_queue_drain_deferred"
                 || kind = "eval_worklist_bigstack_pinned_terminal_late_race_queue_drain_deferred"
                 || kind = "eval_worklist_replay_driver_cooperative_cap_breach_surface"
                 || kind = "eval_worklist_parent_replay_status_preserved_repeat_deferred_live_replay"
                 || kind = "eval_worklist_bigstack_dynamic_join_late_tail_deferred_live_queue"
                 || kind = "eval_worklist_replay_parent_poison_deferred_cold_structural_surge"
                 || kind = "eval_worklist_replay_queue_surge_parent_poison_event_cap_suppressed"
                 || kind = "eval_worklist_bigstack_terminal_frontier_snapshot"
                 || kind = "eval_worklist_bigstack_sequential_hot_frontier_fast_retry"
                 || kind = "eval_worklist_parent_replay_poison_stale_pending_witness_force_surface"
                 || kind = "eval_worklist_cross_kind_yield_thrash_hard_poison"
                 || kind = "eval_worklist_replay_obligation_post_schedule_cap_hard_poison"
                 || kind = "eval_worklist_bigstack_parent_replay_repeat_terminal_pending_zero_physical_tail_draining"
                 || kind = "eval_worklist_bigstack_parent_replay_recent_progress_credit_exhausted"
                 || kind = "eval_worklist_bigstack_parent_replay_poison_live_tail_cap_exhausted"
                 || kind = "compile_progress_metronome_no_work_saturation_grace"
                 || kind = "progress_tick_no_work_rescue_requested"
                 || kind = "progress_tick_no_work_rescue_worker_started"
                 || kind = "progress_tick_no_work_rescue_worker_finished"
                 || kind = "eval_worklist_root_complete_stale_retarget_repeat_blocked"
                 || kind = "eval_worklist_root_complete_stale_retarget_pending_no_queue_live_deferred"
                 || kind = "eval_worklist_idle_cross_kind_replay_poke_resumed"
                 || kind = "eval_worklist_replay_obligation_run"
                 || kind = "compile_progress_stall_probe"
                 || kind = "progress_tick_replay_detail"
                 || kind = "eval_worklist_replay_driver_stack_fence_cap_breach_probation_guard"
                 || kind = "eval_worklist_replay_driver_cooperative_cap_breach_probation_guard"
                 || kind = "eval_worklist_replay_driver_stack_fence_cap_breach_surface"
                 || kind = "eval_worklist_tfun_body_tv_binder_snapshot"
                 || kind = "eval_worklist_terminal_poison_cascade"
                 || kind = "eval_worklist_bigstack_no_root_budget_repeat_cap_pending_semantic_probation_drain"
                 || kind = "eval_worklist_idle_deferred_replay_poke_resumed"
                 || kind = "eval_worklist_type_source_value_replay_return"
                 || kind = "eval_worklist_direct_cycle_replay_return"
                 || kind = "eval_worklist_replay_fingerprint_repeat"
                 || kind = "eval_worklist_live_replay_fingerprint_repeat_deferred"
                 || kind = "eval_worklist_apply_function_body_part_eval_type_error_arg_binder_tail_deferred"
                 || kind = "eval_worklist_phase2_deferred_type_var_synchronous_sweep"
                 || kind = "eval_worklist_direct_term_reentry_replay_return"
                 || kind = "eval_worklist_global_fuse_phase2_deferred_child_transition_applied"
                 || kind = "eval_worklist_ty_global_fuse_phase2_deferred_child_transition_applied" then JsonTelemetryDeprecatedChatter
            elif isNoisyJsonKind kind then JsonTelemetryGenericNoisy
            else JsonTelemetryCritical

        // Both classifications are pure functions of short texts (row kinds and statuses) that repeat
        // endlessly; memoized (bounded), since every row is classified even in quiet runs (fix 39).
        let private jsonTelemetryDetailMemo = System.Collections.Concurrent.ConcurrentDictionary<string, JsonTelemetryDetailId>(System.StringComparer.Ordinal)
        let private jsonTelemetryDetailForKind (kind: string) =
            if isNull kind then jsonTelemetryDetailForKindUncached kind
            else
                let mutable detail = Unchecked.defaultof<JsonTelemetryDetailId>
                if jsonTelemetryDetailMemo.TryGetValue(kind, &detail) then detail
                else
                    let detail = jsonTelemetryDetailForKindUncached kind
                    if jsonTelemetryDetailMemo.Count < 20000 then jsonTelemetryDetailMemo.TryAdd(kind, detail) |> ignore
                    detail

        let private jsonTelemetryDetailCadence = function
            | JsonTelemetryReplayDetail -> EmitSparsePowerThenHeartbeat 2048
            | JsonTelemetryHandoffDetail -> EmitFirstThenHeartbeat 4096
            | JsonTelemetryCycleBreakDetail -> EmitSparsePowerThenHeartbeat 512
            | JsonTelemetryObligationDetail -> EmitSparsePowerThenHeartbeat 512
            | JsonTelemetryQueueChatter -> EmitFirstThenHeartbeat 4096
            | JsonTelemetryDeprecatedChatter -> EmitFirstThenHeartbeat 65536
            | JsonTelemetryHudDetail -> EmitSparsePowerThenHeartbeat 128
            | JsonTelemetryGenericNoisy -> EmitFirstThenHeartbeat 8192
            | JsonTelemetryCritical -> EmitAlways

        let private jsonTelemetryDetailKey detailId kind line =
            match detailId with
            | JsonTelemetryReplayDetail
            | JsonTelemetryHandoffDetail ->
                let driver = jsonStringFieldByName "driver" line
                let decision = jsonStringFieldByName "decision_du" line
                let status = jsonStringFieldByName "status_du" line
                kind + "|driver=" + driver + "|decision=" + decision + "|status=" + status
            | JsonTelemetryCycleBreakDetail ->
                let decision = jsonStringFieldByName "decision_du" line
                kind + "|decision=" + decision
            | JsonTelemetryObligationDetail ->
                let reason = jsonStringFieldByName "reason_du" line
                let targetKind = jsonStringFieldByName "target_kind" line
                kind + "|reason=" + reason + "|target=" + targetKind
            | JsonTelemetryQueueChatter -> kind
            | JsonTelemetryDeprecatedChatter -> kind
            | JsonTelemetryHudDetail -> kind
            | _ -> kind

        let private shouldEmitJsonLine (line: string) =
            let kind = jsonStringFieldByName "kind" line
            let kindSignals = jsonTelemetryTextSignals kind
            let structurallyNoisy = Set.contains JsonTelemetryStructuralNoiseMarker kindSignals
            let emissionClass =
                let detailId = jsonTelemetryDetailForKind kind
                match detailId with
                | JsonTelemetryCritical -> CriticalEvidence
                | _ ->
                    // A line that carries an explicit terminal/blocked status gets its own
                    // typed sample key.  Replay/handoff families also include driver and
                    // decision dimensions so detailed logs stay visible during live drains.
                    let status = jsonStringFieldByName "status" line
                    let sampleKey0 = jsonTelemetryDetailKey detailId kind line
                    let statusSignals = jsonTelemetryTextSignals status
                    let sampleKey =
                        if Set.contains JsonTelemetryBlockedStatusMarker statusSignals
                           || Set.contains JsonTelemetryTerminalStatusMarker statusSignals
                        then sampleKey0 + "|status=" + status
                        else sampleKey0
                    CompositeEvidence(NoisyEvidence(sampleKey, jsonTelemetryDetailCadence detailId), None)
            match shouldEmitEmissionClass emissionClass with
            | EmitLine -> true
            | DropRepeatedLine _ -> false

        // MIGRATION: 1190 proved the heartbeat can choose hold_live_replay_evidence
        // and still lose to the global DiagJson.emit plateau fuse later.  Keep the
        // global fuse typed: if the last rich snapshot still has replay/root authority
        // and no fresh deltas, extend a short bounded lease and emit a direct receipt;
        // otherwise preserve the fail-closed EJP0022 raise.
        type PlateauGlobalEmitGuardDecisionId =
            | PlateauGlobalEmitGuardRaise
            | PlateauGlobalEmitGuardHoldLiveReplayEvidence
            | PlateauGlobalEmitGuardWaitHoldoff
            | PlateauGlobalEmitGuardNativeClosurePlateauPoison

        type NativeClosureSemanticDeltaId =
            | NativeClosureSemanticDeltaUnknown
            | NativeClosureSemanticDeltaProduced
            | NativeClosureSemanticDeltaStarved

        let nativeClosureSemanticDeltaText = function
            | NativeClosureSemanticDeltaUnknown -> "unknown"
            | NativeClosureSemanticDeltaProduced -> "semantic_delta_produced"
            | NativeClosureSemanticDeltaStarved -> "semantic_delta_starved"

        type NativeClosurePlateauPoisonId =
            | NativeClosurePlateauPoisonNotArmed
            | NativeClosurePlateauPoisonStarvedAfterWakeCycle
            | NativeClosurePlateauPoisonSemanticFixedPoint

        let nativeClosurePlateauPoisonText = function
            | NativeClosurePlateauPoisonNotArmed -> "not_armed"
            | NativeClosurePlateauPoisonStarvedAfterWakeCycle -> "PlateauPoison(starved_native_closure_wake_cycle)"
            | NativeClosurePlateauPoisonSemanticFixedPoint -> "PlateauPoison(semantic_fixed_point_no_ast_delta)"

        let plateauGlobalEmitGuardDecisionText = function
            | PlateauGlobalEmitGuardRaise -> "raise_ejp0022"
            | PlateauGlobalEmitGuardHoldLiveReplayEvidence -> "hold_live_replay_evidence"
            | PlateauGlobalEmitGuardWaitHoldoff -> "wait_existing_holdoff"
            | PlateauGlobalEmitGuardNativeClosurePlateauPoison -> "native_closure_plateau_poison"

        type ProgressEtaSnapshotClock =
            | ProgressEtaSnapshotClockMissing
            | ProgressEtaSnapshotClockUnixEpoch of timestampMs:int64
            | ProgressEtaSnapshotClockMonotonic of tickMs:int64

        let private progressEtaSnapshotClockFor tickMs =
            if tickMs <= 0L then ProgressEtaSnapshotClockMissing
            elif tickMs >= 100000000000L then ProgressEtaSnapshotClockUnixEpoch tickMs
            else ProgressEtaSnapshotClockMonotonic tickMs

        let private progressEtaSnapshotAgeMs nowUnixMs nowMonotonicMs = function
            | ProgressEtaSnapshotClockMissing -> -1L
            | ProgressEtaSnapshotClockUnixEpoch timestampMs -> max 0L (nowUnixMs - timestampMs)
            | ProgressEtaSnapshotClockMonotonic tickMs -> max 0L (nowMonotonicMs - tickMs)

        let private progressEtaSnapshotClockText = function
            | ProgressEtaSnapshotClockMissing -> "missing"
            | ProgressEtaSnapshotClockUnixEpoch _ -> "unix_epoch_ms"
            | ProgressEtaSnapshotClockMonotonic _ -> "monotonic_tick_ms"

        let private enrichJsonLineWithProgressEta (line: string) =
            try
                match jsonObjectEnvelopeId line with
                | JsonEnvelopeOther -> line
                | JsonEnvelopeV1Object
                | JsonEnvelopeObject ->
                    let authoritySnapshot = progressPredictionAuthoritativeRead()
                    let progressBp = authoritySnapshot.work.midBp
                    let progressPct = float progressBp / 100.0
                    let durableCompletion = CompilerConsoleHud88.progressHudTerminalExactNow()
                    let globalProgressPct = if durableCompletion then progressPct else min 99.99 progressPct
                    let projectedCompletionOnly = globalProgressPct < progressPct
                    let etaCandidate = CompilerConsoleHud88.reducerHudEtaP50Seconds authoritySnapshot
                    let etaS = if 0L <= etaCandidate && etaCandidate <= 86400L then etaCandidate else -1L
                    let tickNo = authoritySnapshot.generation
                    let tickMs = authoritySnapshot.snapshotMs
                    let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                    let monotonicNow = Environment.TickCount64
                    if progressPredictionStartMs = 0L then progressPredictionStartMs <- now
                    let elapsedMs = if progressPredictionStartMs > 0L then max 0L (now - progressPredictionStartMs) else 0L
                    let elapsedS = elapsedMs / 1000L
                    let tickClock = progressEtaSnapshotClockFor tickMs
                    let tickAgeMs = progressEtaSnapshotAgeMs now monotonicNow tickClock
                    let elapsedField =
                        if jsonHasField "elapsed_s" line then ""
                        else sprintf ",\"elapsed_s\":%d" elapsedS
                    let elapsedMsField =
                        if jsonHasField "elapsed_ms" line then ""
                        else sprintf ",\"elapsed_ms\":%d" elapsedMs
                    let progressPctForLine = globalProgressPct
                    let progressField =
                        if jsonHasField "progress_pct" line then ""
                        else sprintf ",\"progress_pct\":%.2f" progressPctForLine
                    let globalProgressField =
                        if jsonHasField "global_progress_pct" line then ""
                        else sprintf ",\"global_progress_pct\":%.2f" globalProgressPct
                    let progressAuthorityStale = tickAgeMs < 0L || tickAgeMs > 15000L
                    let etaAuthorityInvalid = etaS < 0L || etaS > 86400L
                    let progressObserverOnly = progressAuthorityStale || etaAuthorityInvalid || projectedCompletionOnly
                    let etaForLine = if progressObserverOnly then -1L else int64 etaS
                    let etaField =
                        if jsonHasField "eta_s" line then ""
                        else sprintf ",\"eta_s\":%d" etaForLine
                    let progressCompletionAuthority =
                        if projectedCompletionOnly then "global_progress_capped_before_durable_run_end"
                        elif durableCompletion then "durable_run_end_committed"
                        else "in_progress"
                    let contextField =
                        FastRuntimeFormat.format ",\"progress_eta_source_tick\":%d,\"progress_eta_clock_du\":\"%s\",\"progress_eta_source_age_ms\":%d,\"progress_eta_authority_du\":\"%s\",\"progress_pct_observer_only\":%s,\"progress_completion_authority_du\":\"%s\"" [| box tickNo; box (progressEtaSnapshotClockText tickClock); box tickAgeMs; box (if projectedCompletionOnly then "projected_completion_eta_unavailable" elif progressAuthorityStale then "stale_source_tick_eta_unavailable" elif etaAuthorityInvalid then "invalid_eta_unavailable" else "fresh_source_tick"); box (if progressObserverOnly then "true" else "false"); box progressCompletionAuthority |]
                    line.Substring(0, line.Length - 1) + elapsedField + elapsedMsField + progressField + globalProgressField + etaField + contextField + "}"
            with _ -> line

        let emit (json: string) =
            if progressPredictionPlateauAbortRequested then
                let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                let earliestRaiseMs = lock progressPredictionTickGate (fun () -> progressPredictionPlateauAbortEarliestRaiseMs)
                let holdoffUntilMs = lock progressPredictionTickGate (fun () -> progressPredictionPlateauAbortHoldoffUntilMs)
                let gateOpen = (earliestRaiseMs <= 0L || now >= earliestRaiseMs) && now >= holdoffUntilMs
                if gateOpen then
                    let lastReplaySchedules = (progressPredictionRichLedgerRead()).replaySchedules
                    let lastReplayDrivers = (progressPredictionRichLedgerRead()).replayDrivers
                    let lastRootComplete = (progressPredictionRichLedgerRead()).rootComplete
                    let lastTerminalSignals = (progressPredictionRichLedgerRead()).terminalSignals
                    let lastSampledDelta = (progressPredictionRichLedgerRead()).sampledDelta
                    let lastReplayDelta = (progressPredictionRichLedgerRead()).replayDelta
                    let lastRootDelta = (progressPredictionRichLedgerRead()).rootDelta
                    let lastTerminalDelta = (progressPredictionRichLedgerRead()).terminalDelta
                    let lastNoWorkS = (progressPredictionRichLedgerRead()).noWorkS
                    let liveReplayEvidence =
                        lastReplayDrivers > 0L
                        || lastRootComplete > 0L
                        || (lastReplaySchedules > 0L && lastTerminalSignals > 0L)
                    let noFreshDelta =
                        lastSampledDelta <= 0L
                        && lastReplayDelta <= 0L
                        && lastRootDelta <= 0L
                        && lastTerminalDelta <= 0L
                    let terminalLatchOwnsFrontier = liveReplayEvidence && noFreshDelta && lastTerminalSignals > 0L
                    let semanticFactCount = nativeClosureSemanticFactCount lastSampledDelta lastReplayDelta lastRootDelta lastTerminalDelta
                    let closureWakeCount64 = if terminalLatchOwnsFrontier then max lastTerminalSignals lastReplayDrivers else 0L
                    let closureWakeCount = int (min 2147483647L (max 0L closureWakeCount64))
                    let closureCounterDecision = nativeClosureCycleCounterDecision nativeClosureCycleCounterThresholdDefault closureWakeCount semanticFactCount "diag_emit_plateau_guard/native_callback_closure"
                    let closureStarvationCount = nativeClosureCycleCounterStarvationCount closureCounterDecision
                    let guardDecisionId =
                        if terminalLatchOwnsFrontier && noFreshDelta && closureStarvationCount >= nativeClosureCycleCounterThresholdDefault && lastNoWorkS >= progressPredictionPlateauHardAbortS then PlateauGlobalEmitGuardNativeClosurePlateauPoison
                        elif liveReplayEvidence && noFreshDelta && lastNoWorkS < 180L then PlateauGlobalEmitGuardHoldLiveReplayEvidence
                        else PlateauGlobalEmitGuardRaise
                    match guardDecisionId with
                    | PlateauGlobalEmitGuardNativeClosurePlateauPoison ->
                        let nextHoldoffUntilMs = now + 30000L
                        lock progressPredictionTickGate (fun () -> progressPredictionPlateauAbortHoldoffUntilMs <- nextHoldoffUntilMs)
                        let pid = string (System.Environment.ProcessId)
                        let tid = string (System.Threading.Thread.CurrentThread.ManagedThreadId)
                        let semanticDelta = nativeClosureSemanticDeltaText NativeClosureSemanticDeltaStarved
                        let poison = nativeClosurePlateauPoisonText NativeClosurePlateauPoisonSemanticFixedPoint
                        let line =
                            FastRuntimeFormat.format """{"v":1,"ts_ms":%d,"pid":%s,"tid":%s,"run_id":%s,"kind":"compile_progress_plateau_native_closure_poison_holdoff","event":"diag_emit_plateau_guard","decision_du":%s,"terminal_latch_owns_frontier":true,"closure_latch_blocks_ejp0022":true,"plateau_holdoff_active_due_to_terminal_latch":true,"closure_ledger_semantic_starvation_count":%d,"closure_cycle_counter_threshold":%d,"closure_cycle_counter_du":%s,"closure_semantic_fact_count":%d,"native_promise_closure_result_du":%s,"semantic_blocker_ast_node":"unknown_until_ast_frontier_receipt","native_closure_semantic_delta_du":%s,"native_closure_plateau_poison_du":%s,"last_no_work_s":%d,"last_replay_scheduled":%d,"last_replay_driver_ticks":%d,"last_root_receipts":%d,"last_terminal_signals":%d,"last_sampled_delta":%d,"last_replay_delta":%d,"last_root_delta":%d,"last_terminal_delta":%d,"holdoff_ms":30000,"policy":"native_closure_cycle_counter_thresholds_global_ejp0022_and_returns_plateau_poison_no_buildok_no_writer"}""" [| box now; box pid; box tid; box (esc run_id); box (esc (plateauGlobalEmitGuardDecisionText guardDecisionId)); box closureStarvationCount; box nativeClosureCycleCounterThresholdDefault; box (esc (nativeClosureCycleCounterDecisionText closureCounterDecision)); box semanticFactCount; box (esc (nativeClosureCycleCounterResultText closureCounterDecision)); box (esc semanticDelta); box (esc poison); box lastNoWorkS; box lastReplaySchedules; box lastReplayDrivers; box lastRootComplete; box lastTerminalSignals; box lastSampledDelta; box lastReplayDelta; box lastRootDelta; box lastTerminalDelta |]
                        writeProgressHeartbeatLineDirect line
                    | PlateauGlobalEmitGuardHoldLiveReplayEvidence ->
                        let nextHoldoffUntilMs = now + 30000L
                        lock progressPredictionTickGate (fun () -> progressPredictionPlateauAbortHoldoffUntilMs <- nextHoldoffUntilMs)
                        let pid = string (System.Environment.ProcessId)
                        let tid = string (System.Threading.Thread.CurrentThread.ManagedThreadId)
                        let line =
                            FastRuntimeFormat.format """{"v":1,"ts_ms":%d,"pid":%s,"tid":%s,"run_id":%s,"kind":"compile_progress_plateau_global_emit_guard_holdoff","event":"diag_emit_plateau_guard","decision_du":%s,"last_no_work_s":%d,"last_replay_scheduled":%d,"last_replay_driver_ticks":%d,"last_root_receipts":%d,"last_terminal_signals":%d,"last_sampled_delta":%d,"last_replay_delta":%d,"last_root_delta":%d,"last_terminal_delta":%d,"holdoff_ms":30000,"policy":"typed_global_emit_guard_respects_live_replay_holdoff_no_buildok_no_writer"}""" [| box now; box pid; box tid; box (esc run_id); box (esc (plateauGlobalEmitGuardDecisionText guardDecisionId)); box lastNoWorkS; box lastReplaySchedules; box lastReplayDrivers; box lastRootComplete; box lastTerminalSignals; box lastSampledDelta; box lastReplayDelta; box lastRootDelta; box lastTerminalDelta |]
                        writeProgressHeartbeatLineDirect line
                    | PlateauGlobalEmitGuardRaise ->
                        let nextHoldoffUntilMs = now + 1000L
                        lock progressPredictionTickGate (fun () -> progressPredictionPlateauAbortHoldoffUntilMs <- nextHoldoffUntilMs)
                        let pid = string (System.Environment.ProcessId)
                        let tid = string (System.Threading.Thread.CurrentThread.ManagedThreadId)
                        let line =
                            FastRuntimeFormat.format
                                "{\"v\":1,\"ts_ms\":%d,\"pid\":%s,\"tid\":%s,\"run_id\":%s,\"kind\":\"compile_progress_plateau_abort_delegated\",\"event\":\"diag_emit_plateau_guard\",\"decision_du\":%s,\"exception_thrown\":false,\"heartbeat_abort_authority\":true,\"holdoff_ms\":1000,\"policy\":\"diagnostic_writer_never_throws_plateau_abort_heartbeat_owns_typed_terminal_action\",\"next\":\"heartbeat_hard_abort_or_typed_scheduler_holdoff\"}"
                                [| box now; box pid; box tid; box (esc run_id); box (esc (plateauGlobalEmitGuardDecisionText guardDecisionId)) |]
                        writeProgressHeartbeatLineDirect line
                    | PlateauGlobalEmitGuardWaitHoldoff -> ()
            if quiet then
                // Still classify the row: shouldEmitJsonLine keeps the per-kind counters that
                // snapshotKindCount exposes to the replay/join retry policies, and quiet runs must choose the
                // same paths as full-telemetry runs. Only the envelope, enrichment and the write are skipped.
                try
                    if not (System.Object.ReferenceEquals(json, null)) then shouldEmitJsonLine json |> ignore
                with _ -> ()
            else
              try
                let trimmed = if System.Object.ReferenceEquals(json,null) then "" else json.Trim()
                let line =
                    match jsonObjectEnvelopeId trimmed with
                    | JsonEnvelopeV1Object -> trimmed
                    | JsonEnvelopeObject ->
                        let body = trimmed.Substring(1, trimmed.Length - 2)
                        let ts = string (System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())
                        let pid = string (System.Environment.ProcessId)
                        let tid = string (System.Threading.Thread.CurrentThread.ManagedThreadId)
                        FastRuntimeFormat.format "{\"v\":1,\"ts_ms\":%s,\"pid\":%s,\"tid\":%s,%s}" [| box ts; box pid; box tid; box body |]
                    | JsonEnvelopeOther ->
                        let ts = string (System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())
                        let pid = string (System.Environment.ProcessId)
                        let tid = string (System.Threading.Thread.CurrentThread.ManagedThreadId)
                        FastRuntimeFormat.format "{\"v\":1,\"ts_ms\":%s,\"pid\":%s,\"tid\":%s,\"kind\":\"diag\",\"msg\":%s}" [| box ts; box pid; box tid; box (esc trimmed) |]
                // Compaction and enrichment (memory, progress/ETA, seq/consensus envelope) only add fields;
                // the emission filters below read the producer's own fields (kind, status, driver,
                // decision_du, site, ...). Most rows are dropped, so decide on the raw row and enrich only
                // what is written: enriching every row cost ~10% of a hopac compile's CPU.
                let enrichForWrite line =
                    let line = compactJsonLineIfLarge line
                    let line = enrichJsonLineWithProcessMemory line
                    let line = enrichJsonLineWithProgressEta line
                    enrichJsonLineWithSeqRunConsensus line
                let nowAfterEnrich = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                // JSON is only the erasure boundary here: the bounded lease is
                // persisted as an atomic runtime state and the deadman merely
                // observes it.  Root resolution consumes owner-debt authority;
                // subsequent owner-drain rows are writer-tail work, never root blockers.
                // Writer-tail authority is read directly from the reducer snapshot.
                // JSON text cannot arm, extend, expire or terminalize the lease.
                let postRootWriterLeaseDeadlineMs = 0L
                let postRootWriterLeaseGeneration = postRootWriterLeaseGenerationNow ()
                let postRootTerminalReceiptAlreadySeen = postRootTerminalReceiptSeenNow ()
                let postRootWriterLeaseLive = postRootWriterLeaseActiveNow ()
                if false then
                    if true then
                        ()
                        let elapsedMsForLease = if progressPredictionStartMs > 0L then max 0L (nowAfterEnrich - progressPredictionStartMs) else 0L
                        let elapsedSForLease = elapsedMsForLease / 1000L
                        let progressBpForLease = progressPredictionAuthoritativeProgressBp()
                        let progressPctForLease = float progressBpForLease / 100.0
                        let postRootTailQueue, postRootTailActive, postRootTailPending = postRootWriterTailSnapshotNow()
                        writeProgressHeartbeatLineDirect (
                            FastRuntimeFormat.format "{\"v\":1,\"ts_ms\":%d,\"pid\":%s,\"tid\":%s,\"run_id\":%s,\"kind\":\"post_root_writer_tail_snapshot_before_lease_expiry\",\"event\":\"diag_emit_post_root_tail_snapshot\",\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"workdag_tail_after_state_du\":\"WorkDagTail(LastObserved|qap=%d/%d/%d)\",\"writer_capability_lease_id\":\"writer-lease:expired\",\"root_reopen_forbidden\":true,\"next\":\"emit_typed_lease_expiry_receipt\"}" [| box nowAfterEnrich; box (string (System.Environment.ProcessId)); box (string (System.Threading.Thread.CurrentThread.ManagedThreadId)); box (esc run_id); box postRootTailQueue; box postRootTailActive; box postRootTailPending; box postRootTailQueue; box postRootTailActive; box postRootTailPending |])
                        writeProgressHeartbeatLineDirect (
