        type ITypedDiagEvent = interface end

        let private typedDiagRecordEnvelope (line:string) =
            match jsonObjectEnvelopeId line with
            | JsonEnvelopeV1Object
            | JsonEnvelopeObject ->
                let schemaField =
                    if jsonHasField "typed_event_schema_revision" line then ""
                    else ",\"typed_event_schema_revision\":1"
                let serializerField =
                    if jsonHasField "typed_event_serializer_du" line then ""
                    else ",\"typed_event_serializer_du\":\"FSharp.Json.Record\""
                let contractField =
                    if jsonHasField "typed_event_serializer_contract_du" line then ""
                    else ",\"typed_event_serializer_contract_du\":\"SchemaRoundTripValidatedBeforeEmit\""
                line.Substring(0, line.Length - 1)
                + schemaField
                + serializerField
                + contractField
                + "}"
            | JsonEnvelopeOther ->
                invalidOp "typed diagnostic records must serialize as one JSON object"


        let private typedDiagValidatedTypes =
            System.Collections.Concurrent.ConcurrentDictionary<System.Type, byte>()

        let private compactTypedDiagJson (payload:string) =
            let output = System.Text.StringBuilder(payload.Length)
            let mutable inString = false
            let mutable escaped = false
            for c in payload do
                if inString then
                    output.Append(c) |> ignore
                    if escaped then
                        escaped <- false
                    elif c = '\\' then
                        escaped <- true
                    elif c = '"' then
                        inString <- false
                elif c = '"' then
                    inString <- true
                    output.Append(c) |> ignore
                elif not (System.Char.IsWhiteSpace c) then
                    output.Append(c) |> ignore
            output.ToString()

        let private validateTypedDiagRoundTrip<'T when 'T :> ITypedDiagEvent> (_event:'T) (payload:string) =
            let eventType = typeof<'T>
            if typedDiagValidatedTypes.ContainsKey eventType then ()
            else
                let roundTrip = FSharp.Json.Json.deserialize<'T> payload
                let roundTripPayload = FSharp.Json.Json.serialize roundTrip |> compactTypedDiagJson
                if not (System.String.Equals(payload, roundTripPayload, System.StringComparison.Ordinal)) then
                    invalidOp ("FSharp.Json typed diagnostic record roundtrip changed canonical payload for " + eventType.FullName)
                let envelope = typedDiagRecordEnvelope payload
                if jsonHasField "kind" envelope
                   && jsonHasField "typed_event_schema_revision" envelope
                   && jsonHasField "typed_event_serializer_du" envelope
                   && jsonHasField "typed_event_serializer_contract_du" envelope then
                    if typedDiagValidatedTypes.TryAdd(eventType, 1uy) then
                        emit (
                            sprintf "{\"kind\":\"typed_diag_schema_roundtrip_passed\",\"event_type\":%s,\"authority\":\"first_concrete_record_value_roundtrip_before_emit\",\"next\":\"require_one_pass_receipt_per_emitted_schema\"}"
                                (esc eventType.FullName))
                else
                    invalidOp ("FSharp.Json typed diagnostic record envelope contract failed for " + eventType.FullName)

        let emitRecord<'T when 'T :> ITypedDiagEvent> (event:'T) =
            try
                let payload = FSharp.Json.Json.serialize event |> compactTypedDiagJson
                validateTypedDiagRoundTrip event payload
                payload
                |> typedDiagRecordEnvelope
                |> emit
            with ex ->
                let eventType = typeof<'T>.FullName
                let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                let pid = System.Environment.ProcessId
                let tid = System.Threading.Thread.CurrentThread.ManagedThreadId
                writeProgressHeartbeatLineDirect (
                    FastRuntimeFormat.format "{\"v\":1,\"ts_ms\":%d,\"pid\":%d,\"tid\":%d,\"kind\":\"typed_diag_serialization_failed\",\"event_type\":%s,\"exception_type\":%s,\"exception_message\":%s,\"authority\":\"direct_serializer_failure_survival_lane\",\"next\":\"keep_compiler_running_and_fix_event_schema\"}" [| box now; box pid; box tid; box (esc eventType); box (esc (ex.GetType().FullName)); box (esc ex.Message) |])

        // Ordinary diagnostics can be requested from Hopac jobs, but JSON enrichment,
        // file mirroring and console arbitration are blocking operations. Route those
        // requests through one ordered external lane. Terminal-durable receipts keep
        // their explicit synchronous path and are never sent through this lossy queue.
        type private ExternalDiagEnvelope = {
            json : string
            enqueuedAtMs : int64
        }

        let private externalDiagQueue = System.Collections.Concurrent.ConcurrentQueue<ExternalDiagEnvelope>()
        let private externalDiagSignal = new System.Threading.AutoResetEvent(false)
        type private ExternalDiagWriterStartDecision =
            | ExternalDiagWriterStartGranted
            | ExternalDiagWriterAlreadyStarted

        type private ExternalDiagAdmissionDecision =
            | ExternalDiagAdmissionGranted of depth:int
            | ExternalDiagAdmissionRejected of depth:int

        type private ExternalDiagLaneCounters = {
            mutable queued : int
            mutable dropped : int64
        }

        type private ExternalDiagWriterState =
            | ExternalDiagWriterNotStarted
            | ExternalDiagWriterStarted

        let private externalDiagCounters = {
            queued = 0
            dropped = 0L
        }
        let private externalDiagWriterGate = obj()
        let private externalDiagCountersGate = obj()
        let mutable private externalDiagWriterState = ExternalDiagWriterNotStarted
        let private externalDiagQueueLimit = 8192

        let private externalDiagWriterStartDecision () =
            lock externalDiagWriterGate (fun () ->
                match externalDiagWriterState with
                | ExternalDiagWriterStarted -> ExternalDiagWriterAlreadyStarted
                | ExternalDiagWriterNotStarted ->
                    externalDiagWriterState <- ExternalDiagWriterStarted
                    ExternalDiagWriterStartGranted)

        let private externalDiagAdmissionDecision () =
            lock externalDiagCountersGate (fun () ->
                externalDiagCounters.queued <- externalDiagCounters.queued + 1
                let depth = externalDiagCounters.queued
                if depth <= externalDiagQueueLimit
                then ExternalDiagAdmissionGranted depth
                else ExternalDiagAdmissionRejected depth)

        let private externalDiagDequeued () =
            lock externalDiagCountersGate (fun () ->
                externalDiagCounters.queued <- max 0 (externalDiagCounters.queued - 1))

        let private externalDiagDropped () =
            lock externalDiagCountersGate (fun () ->
                externalDiagCounters.dropped <- externalDiagCounters.dropped + 1L)

        let private externalDiagUndoRejectedAdmission () =
            lock externalDiagCountersGate (fun () ->
                externalDiagCounters.queued <- max 0 (externalDiagCounters.queued - 1))

        let private ensureExternalDiagWriter () =
            match externalDiagWriterStartDecision () with
            | ExternalDiagWriterAlreadyStarted -> ()
            | ExternalDiagWriterStartGranted ->
                let writer =
                    System.Threading.Thread(System.Threading.ThreadStart(fun () ->
                        let mutable envelope = Unchecked.defaultof<ExternalDiagEnvelope>
                        while true do
                            externalDiagSignal.WaitOne(250) |> ignore
                            let mutable drained = 0
                            while drained < 512 && externalDiagQueue.TryDequeue(&envelope) do
                                externalDiagDequeued ()
                                try emit envelope.json with _ -> externalDiagDropped ()
                                drained <- drained + 1))
                writer.IsBackground <- true
                writer.Name <- "spiral-diag-json-external-writer"
                writer.Start()

        let emitOutsideHopac (json:string) =
            ensureExternalDiagWriter()
            match externalDiagAdmissionDecision () with
            | ExternalDiagAdmissionGranted _ ->
                externalDiagQueue.Enqueue {
                    json = json
                    enqueuedAtMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                }
                externalDiagSignal.Set() |> ignore
            | ExternalDiagAdmissionRejected _ ->
                externalDiagUndoRejectedAdmission ()
                externalDiagDropped ()

        let externalDiagLaneSnapshot () =
            lock externalDiagCountersGate (fun () ->
                externalDiagCounters.queued,
                externalDiagCounters.dropped)

        do
            ensureProgressPredictionHeartbeat()
            ensureProgressHudSmoothFrameTicker()
            Progress88.set_prediction_tick_sink emit

        let retry (code: string) (gen_before: int) (gen_after: int) (attempt: int) (max_attempts: int) (file: string) (backend: string) (is_gen_wait: bool) (seq: bool) (dop_env: int) (dop_forced: int) =
            emit (FastRuntimeFormat.format "{\"kind\":\"retry\",\"code\":%s,\"gen_before\":%d,\"gen_after\":%d,\"attempt\":%d,\"max_attempts\":%d,\"file\":%s,\"backend\":%s,\"gen_wait\":%b,\"seq\":%b,\"dop_env\":%d,\"dop_forced\":%d}" [| box (esc code); box gen_before; box gen_after; box attempt; box max_attempts; box (esc file); box (esc backend); box is_gen_wait; box seq; box dop_env; box dop_forced |])
        let retryStop (code: string) (reason: string) (attempt: int) (max_attempts: int) (file: string) (backend: string) (key: string) (site: string) (depth: int) (re: int) (max_re: int) =
            emit (FastRuntimeFormat.format "{\"kind\":\"retry_stop\",\"code\":%s,\"reason\":%s,\"attempt\":%d,\"max_attempts\":%d,\"file\":%s,\"backend\":%s,\"key\":%s,\"site\":%s,\"depth\":%d,\"re\":%d,\"max_re\":%d}" [| box (esc code); box (esc reason); box attempt; box max_attempts; box (esc file); box (esc backend); box (esc key); box (esc site); box depth; box re; box max_re |])
        let termCycle (key: string) (depth: int) (site: string) (gen: int) (re: int) (max_re: int) (big: bool) (hs: string) (ks: string) (count: int) (panic: bool) =
            // Defensive truncation: term-cycle payloads can become huge and contribute to stack/alloc pressure
            let hs =
                if System.Object.ReferenceEquals(hs,null) then ""
                elif hs.Length > 512 then hs.Substring(0,512) + "…"
                else hs
            let ks =
                if System.Object.ReferenceEquals(ks,null) then ""
                elif ks.Length > 2048 then ks.Substring(0,2048) + "…"
                else ks
            let compact = count > 1 || (panic && depth > 768)
            let hs_out = if compact then "" else hs
            let ks_out = if compact then "" else ks
            emit (FastRuntimeFormat.format "{\"kind\":\"term_cycle\",\"code\":%s,\"key\":%s,\"depth\":%d,\"site\":%s,\"gen\":%d,\"re\":%d,\"max_re\":%d,\"big\":%b,\"count\":%d,\"panic\":%b,\"compact\":%b,\"hs\":%s,\"ks\":%s}" [| box (esc DiagnosticClassifier.EJP0011); box (esc key); box depth; box (esc site); box gen; box re; box max_re; box big; box count; box panic; box compact; box (esc hs_out); box (esc ks_out) |])


    module TermCycleWatchdog =
        open System.Collections.Generic
        let private lock_obj = obj()
        // key -> struct(lastGen,totalCount,genCount)
        let private seen = Dictionary<CompilerIdentityKernel.ContentDigest, struct(int*int*int)>()
        /// Returns total count for this key across the whole compilation session.
        let note (key: string) (gen: int) =
            let keyRef = CompilerIdentityKernel.ContentDigest.ofText "term-cycle-watchdog" key
            lock lock_obj (fun () ->
                match seen.TryGetValue keyRef with
                | true, struct(g,tot,genC) ->
                    let tot' = tot + 1
                    let genC' = if g = gen then genC + 1 else 1
                    seen.[keyRef] <- struct(gen, tot', genC')
                    tot'
                | _ ->
                    seen.[keyRef] <- struct(gen,1,1)
                    1)


    type EvalVisitKind =
        | EvalVisitTerm
        | EvalVisitType

    type EvalVisitKey = private {
        generation : int
        kind : EvalVisitKind
        binding : CompilerKernelV2.StableBindingId
        }

    type EvalVisitBudgetBasis =
        | EvalVisitAdaptiveProductivityWindow of streakLimit:int * minimumAgeMs:int64

    let evalVisitBudgetBasisText = function
        | EvalVisitAdaptiveProductivityWindow(streakLimit, minimumAgeMs) ->
            sprintf "Adaptive(UnproductiveStreakAndAge|facts+cell-revision+work-receipts|limit=%d|minimum_age_ms=%d)" streakLimit minimumAgeMs

    type EvalVisitAdmission =
        | EvalVisitAdmitted of visitCount:int * budget:int * unproductiveStreak:int * unproductiveAgeMs:int64
        | EvalVisitProductiveRepeat of visitCount:int * budget:int * factsDelta:int64 * cellRevisionDelta:int64 * workReceiptDelta:int64
        | EvalVisitBudgetExhausted of visitCount:int * budget:int * unproductiveStreak:int * unproductiveAgeMs:int64

    exception EvalVisitBudgetFailure of kind:EvalVisitKind * key:string * site:string * visitCount:int * visitBudget:int * unproductiveStreak:int * unproductiveAgeMs:int64

    type EvalVisitLedgerEntry = private {
        visitCount : int
        unproductiveStreak : int
        unproductiveSinceMs : int64
        unproductiveAgeMs : int64
        semanticFactCount : int64
        workUnitReceiptCount : int64
        cellRevision : string
        factsDelta : int64
        workReceiptDelta : int64
        cellRevisionDelta : int64
    }

    module EvalVisitLedger =
        let private visits = System.Collections.Concurrent.ConcurrentDictionary<EvalVisitKey,EvalVisitLedgerEntry>()

        let private normalizeKey (key:string) =
            if System.Object.ReferenceEquals(key,null) then "" else key

        let key kind generation sourceKey : EvalVisitKey =
            let normalized = normalizeKey sourceKey
            let binding =
                CompilerKernelV2.StableBindingId.createSemantic
                    0
                    "evaluator"
                    normalized
                    normalized
                    (match kind with EvalVisitTerm -> "term" | EvalVisitType -> "type")
                    "host"
            { generation = generation
              kind = kind
              binding = binding }

        let observe kind generation sourceKey cellRevision budget : EvalVisitAdmission =
            let budget = max 1 budget
            let basis = EvalVisitAdaptiveProductivityWindow(budget, 1000L)
            let minimumAgeMs =
                match basis with
                | EvalVisitAdaptiveProductivityWindow(_, value) -> value
            let stableKey = key kind generation sourceKey
            let semanticSnapshot = DiagJson.semanticFactBridgeSnapshot()
            let semanticWorkSnapshot = DiagJson.semanticWorkLedgerSnapshot()
            let semanticFactCount = semanticSnapshot.factCount
            let workUnitReceiptCount = semanticWorkSnapshot.receipts
            let cellRevision = if System.Object.ReferenceEquals(cellRevision,null) then "" else cellRevision
            let nowMs = System.Environment.TickCount64
            let initial =
                { visitCount = 1
                  unproductiveStreak = 0
                  unproductiveSinceMs = 0L
                  unproductiveAgeMs = 0L
                  semanticFactCount = semanticFactCount
                  workUnitReceiptCount = workUnitReceiptCount
                  cellRevision = cellRevision
                  factsDelta = 0L
                  workReceiptDelta = 0L
                  cellRevisionDelta = 0L }
            let entry =
                visits.AddOrUpdate(
                    stableKey,
                    initial,
                    fun _ previous ->
                        let visitCount = if previous.visitCount = System.Int32.MaxValue then previous.visitCount else previous.visitCount + 1
                        let factsDelta = max 0L (semanticFactCount - previous.semanticFactCount)
                        let workReceiptDelta = max 0L (workUnitReceiptCount - previous.workUnitReceiptCount)
                        let cellRevisionDelta = if cellRevision = previous.cellRevision then 0L else 1L
                        let productive = factsDelta > 0L || workReceiptDelta > 0L || cellRevisionDelta > 0L
                        let unproductiveStreak =
                            if productive then 0
                            elif previous.unproductiveStreak = System.Int32.MaxValue then previous.unproductiveStreak
                            else previous.unproductiveStreak + 1
                        let unproductiveSinceMs =
                            if productive then 0L
                            elif previous.unproductiveStreak = 0 || previous.unproductiveSinceMs <= 0L then nowMs
                            else previous.unproductiveSinceMs
                        let unproductiveAgeMs =
                            if productive || unproductiveSinceMs <= 0L then 0L
                            else max 0L (nowMs - unproductiveSinceMs)
                        { visitCount = visitCount
                          unproductiveStreak = unproductiveStreak
                          unproductiveSinceMs = unproductiveSinceMs
                          unproductiveAgeMs = unproductiveAgeMs
                          semanticFactCount = semanticFactCount
                          workUnitReceiptCount = workUnitReceiptCount
                          cellRevision = cellRevision
                          factsDelta = factsDelta
                          workReceiptDelta = workReceiptDelta
                          cellRevisionDelta = cellRevisionDelta })
            if entry.visitCount > 1 && (entry.factsDelta > 0L || entry.workReceiptDelta > 0L || entry.cellRevisionDelta > 0L) then
                EvalVisitProductiveRepeat(entry.visitCount, budget, entry.factsDelta, entry.cellRevisionDelta, entry.workReceiptDelta)
            elif entry.unproductiveStreak >= budget && entry.unproductiveAgeMs >= minimumAgeMs then
                EvalVisitBudgetExhausted(entry.visitCount, budget, entry.unproductiveStreak, entry.unproductiveAgeMs)
            else
                EvalVisitAdmitted(entry.visitCount, budget, entry.unproductiveStreak, entry.unproductiveAgeMs)

        let count kind generation sourceKey =
            match visits.TryGetValue(key kind generation sourceKey) with
            | true, entry -> entry.visitCount
            | false, _ -> 0

    /// Global one-way fuse for EJP0011 panic.
    ///
    /// Why MIGRATION needs this: under parallel evaluation, one worker can detect a real
    /// re-entrant term/type cycle and raise EJP0011, while sibling workers keep descending
    /// through the same poisoned graph. That produced useful compact JSONL in MIGRATION, but
    /// still ended in a process-level StackOverflow. This fuse turns the first panic cycle
    /// into an immediate minimal abort for every later evaluator entry, avoiding diagnostic
    /// recursion and preventing sibling workers from amplifying the cycle.
    module TermCycleFuse =
        type TermCycleFuseTraceFrame = {
            path : string
            fromLine : int
            fromCharacter : int
            nearToLine : int
            nearToCharacter : int
            }

        let traceFrame path fromLine fromCharacter nearToLine nearToCharacter =
            { path = if System.Object.ReferenceEquals(path,null) then "" else path
              fromLine = fromLine
              fromCharacter = fromCharacter
              nearToLine = nearToLine
              nearToCharacter = nearToCharacter }

        let traceFrameData (frame: TermCycleFuseTraceFrame) =
            {| path = frame.path
               fromLine = frame.fromLine
               fromCharacter = frame.fromCharacter
               nearToLine = frame.nearToLine
               nearToCharacter = frame.nearToCharacter |}

        type TermCycleFuseEvidence = {
            kind : EvalVisitKind
            key : string
            site : string
            depth : int
            generation : int
            reentry : int
            maxReentry : int
            trace : TermCycleFuseTraceFrame list
            }

        type TermCycleFuseState =
            | TermCycleFuseOpen
            | TermCycleFuseTripped of TermCycleFuseEvidence

        let private lock_obj = obj()
        let mutable private state = TermCycleFuseOpen

        let private esc (s: string) =
            if System.Object.ReferenceEquals(s,null) then "null" else
                let s =
                    s.Replace("\\","\\\\")
                     .Replace("\"","\\\"")
                     .Replace("\r","\\r")
                     .Replace("\n","\\n")
                     .Replace("\t","\\t")
                "\"" + s + "\""

        let private compactTrace tr =
            let maxFrontierTrace = 48
            match tr with
            | [] -> []
            | _ ->
                let head = tr |> List.truncate (maxFrontierTrace / 2)
                let tail =
                    tr
                    |> List.rev
                    |> List.truncate (maxFrontierTrace - head.Length)
                    |> List.rev
                // Preserve order while avoiding duplicate overlap when the trace is already short.
                if head.Length + tail.Length >= tr.Length then tr
                else head @ tail

        let private evidenceFor (kind: EvalVisitKind) (key: string) (site: string) (depth: int) (gen: int) (re: int) (maxRe: int) trace =
            {
                kind = kind
                key = if System.Object.ReferenceEquals(key,null) then "" else key
                site = if System.Object.ReferenceEquals(site,null) then "" else site
                depth = depth
                generation = gen
                reentry = re
                maxReentry = maxRe
                trace = compactTrace trace
            }

        let visitLog2Bucket value =
            let mutable scaled = max 1 value
            let mutable bucket = 0
            while scaled > 1 do
                scaled <- scaled >>> 1
                bucket <- bucket + 1
            bucket

        [<StructuralEquality; NoComparison>]
        type private TermCyclePrefetchBucketIdentity = {
            keyRef : CompilerIdentityKernel.ContentDigest
            generation : int
            bucket : int
        }

        let private prefetchBucketSeen =
            System.Collections.Concurrent.ConcurrentDictionary<TermCyclePrefetchBucketIdentity, byte>()

        let prefetchBucketFirst key generation bucket =
            let identity : TermCyclePrefetchBucketIdentity =
                { keyRef = CompilerIdentityKernel.ContentDigest.ofText "term-reentry-prefetch" key
                  generation = generation
                  bucket = bucket }
            prefetchBucketSeen.TryAdd(identity, 0uy)

        let observeWithTrace (kind: EvalVisitKind) (key: string) (site: string) (depth: int) (gen: int) (re: int) (maxRe: int) trace : unit =
            let evidence = evidenceFor kind key site depth gen re maxRe trace
            let reentryBucket = visitLog2Bucket evidence.reentry
            let shouldEmit =
                prefetchBucketFirst evidence.key evidence.generation reentryBucket
            let occurrenceCount = 1L
            try
                if shouldEmit then
                    let observationPayload =
                        FastRuntimeFormat.format "{\"kind\":\"term_reentry_prefetch_observation\",\"key\":%s,\"site\":%s,\"depth\":%d,\"gen\":%d,\"re\":%d,\"reentry_log2_bucket\":%d,\"max_re\":%d,\"trace_lines\":%d,\"fuse_state_du\":\"TermCycleFuseOpen\",\"admission_du\":\"TermCyclePrefetchObservation\",\"cap_exceeded\":%b,\"occurrence_count\":%d,\"sparse_policy\":\"key_generation_log2_bucket_exact_first_only\",\"terminal_authority\":false,\"single_flight\":1,\"next\":\"prefetch_replay_without_tripping_global_fuse\"}" [| box (esc evidence.key); box (esc evidence.site); box evidence.depth; box evidence.generation; box evidence.reentry; box reentryBucket; box evidence.maxReentry; box evidence.trace.Length; box (evidence.maxReentry > 0 && evidence.reentry > evidence.maxReentry); box occurrenceCount |]
                    DiagJson.emit observationPayload
            with _ -> ()

        let tripWithTrace (kind: EvalVisitKind) (key: string) (site: string) (depth: int) (gen: int) (re: int) (maxRe: int) trace : unit =
            let evidence = evidenceFor kind key site depth gen re maxRe trace
            let accepted =
                lock lock_obj (fun () ->
                    match state with
                    | TermCycleFuseOpen ->
                        state <- TermCycleFuseTripped evidence
                        true
                    | TermCycleFuseTripped _ -> false)
            if accepted then
                try
                    let fusePayload = FastRuntimeFormat.format "term_reentry_fuse key=%s site=%s depth=%d re=%d max_re=%d" [| box evidence.key; box evidence.site; box evidence.depth; box evidence.reentry; box evidence.maxReentry |]
                    DiagJson.emit (FastRuntimeFormat.format "{\"kind\":\"term_reentry_fuse\",\"code\":%s,\"key\":%s,\"site\":%s,\"depth\":%d,\"gen\":%d,\"re\":%d,\"max_re\":%d,\"trace_lines\":%d,\"root_promise_status\":%s,\"root_complete_await_contract_du\":%s,\"root_complete_exit_policy_du\":%s,\"root_complete_collapse_decision_du\":\"RootCompleteCollapse(EmitStructuredSemanticErrorExitOne|promise=term_reentry_fuse|payload=hard_cycle_fuse)\",\"semantic_diagnosis\":%s,\"semantic_error_payload\":%s,\"global_fuse_arbitration_du\":%s,\"global_fuse_live_replay_evidence_present\":false,\"global_fuse_native_consumer_attached\":false,\"global_fuse_cap_exceeded\":%b,\"fuse_state_du\":\"TermCycleFuseTripped\"}" [| box (esc DiagnosticClassifier.EJP0011); box (esc evidence.key); box (esc evidence.site); box evidence.depth; box evidence.generation; box evidence.reentry; box evidence.maxReentry; box evidence.trace.Length; box (esc "RootPromiseFailed(term_reentry_fuse)"); box (esc "RootCompleteAwaitFailedClosed(term_reentry_fuse)"); box (esc "observer_only_semantic_failure_requires_native_root_complete_boundary(term_reentry_fuse)"); box (esc "SemanticDiagnosis(TermReentryFuse|span=first_trace_site|message=hard_cycle_requires_native_parent_callback_or_terminal_collapse)"); box (esc fusePayload); box (esc "hard_cycle_fuse_wait_for_native_arbitration_before_EJP0011"); box (evidence.maxReentry > 0 && evidence.reentry > evidence.maxReentry) |])
                with _ -> ()

        let observePrefetchVisitWithTrace (kind: EvalVisitKind) (key: string) (site: string) (depth: int) (gen: int) (cellRevision: string) trace : EvalVisitAdmission =
            let budget = 3
            let basisText = evalVisitBudgetBasisText (EvalVisitAdaptiveProductivityWindow(budget, 1000L))
            match EvalVisitLedger.observe kind gen key cellRevision budget with
            | (EvalVisitAdmitted(visitCount, visitBudget, unproductiveStreak, unproductiveAgeMs) as admission) ->
                let evidence = evidenceFor kind key site depth gen visitCount visitBudget trace
                let visitBucket = visitLog2Bucket visitCount
                let shouldEmit = prefetchBucketFirst key gen visitBucket
                let occurrenceCount = 1L
                if shouldEmit then
                    try
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"term_reentry_prefetch_observation\",\"key\":%s,\"site\":%s,\"depth\":%d,\"gen\":%d,\"stack_guard_scope_du\":\"thread_local_stack_depth\",\"visit_guard_scope_du\":\"process_wide_generation_productivity_ledger\",\"visit_count\":%d,\"visit_log2_bucket\":%d,\"visit_budget\":%d,\"unproductive_streak\":%d,\"unproductive_age_ms\":%d,\"facts_delta\":0,\"work_receipt_delta\":0,\"cell_revision_delta\":0,\"visit_budget_basis_du\":%s,\"trace_lines\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"key_generation_log2_bucket_exact_first_only\",\"fuse_state_du\":\"TermCycleFuseOpen\",\"admission_du\":\"EvalVisitAdmitted\",\"terminal_authority\":false,\"single_flight\":1,\"next\":\"prefetch_replay_until_productivity_window_exhausted\"}" [| box (esc evidence.key); box (esc evidence.site); box evidence.depth; box evidence.generation; box visitCount; box visitBucket; box visitBudget; box unproductiveStreak; box unproductiveAgeMs; box (esc basisText); box evidence.trace.Length; box occurrenceCount |])
                    with _ -> ()
                admission
            | (EvalVisitProductiveRepeat(visitCount, visitBudget, factsDelta, cellRevisionDelta, workReceiptDelta) as admission) ->
                let evidence = evidenceFor kind key site depth gen visitCount visitBudget trace
                let visitBucket = visitLog2Bucket visitCount
                let shouldEmit = prefetchBucketFirst key gen visitBucket
                let occurrenceCount = 1L
                if shouldEmit then
                    try
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"term_reentry_prefetch_observation\",\"key\":%s,\"site\":%s,\"depth\":%d,\"gen\":%d,\"visit_count\":%d,\"visit_log2_bucket\":%d,\"visit_budget\":%d,\"productive_visits\":true,\"unproductive_streak\":0,\"unproductive_age_ms\":0,\"facts_delta\":%d,\"work_receipt_delta\":%d,\"cell_revision_delta\":%d,\"visit_budget_basis_du\":%s,\"trace_lines\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"key_generation_log2_bucket_exact_first_only\",\"admission_du\":\"EvalVisitProductiveRepeat\",\"terminal_authority\":false,\"single_flight\":1,\"next\":\"reset_unproductive_window_and_continue\"}" [| box (esc evidence.key); box (esc evidence.site); box evidence.depth; box evidence.generation; box visitCount; box visitBucket; box visitBudget; box factsDelta; box workReceiptDelta; box cellRevisionDelta; box (esc basisText); box evidence.trace.Length; box occurrenceCount |])
                    with _ -> ()
                admission
            | (EvalVisitBudgetExhausted(visitCount, visitBudget, unproductiveStreak, unproductiveAgeMs) as admission) ->
                let occurrenceCount, firstExhaustion =
                    DiagJson.sparseLogDecision ("eval_visit_exhausted|" + key) 0L
                if firstExhaustion && occurrenceCount = 1L then
                    tripWithTrace kind key site depth gen visitCount visitBudget trace
                    try
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"term_reentry_visit_budget_exhausted\",\"key\":%s,\"site\":%s,\"depth\":%d,\"gen\":%d,\"visit_count\":%d,\"visit_budget\":%d,\"productive_visits\":false,\"unproductive_streak\":%d,\"unproductive_age_ms\":%d,\"facts_delta\":0,\"work_receipt_delta\":0,\"cell_revision_delta\":0,\"visit_budget_basis_du\":%s,\"first_exhaustion\":true,\"occurrence_count\":%d,\"guard_scope_du\":\"process_wide_generation_productivity_ledger\",\"admission_du\":\"EvalVisitBudgetExhausted\",\"visit_ledger_disposition_du\":\"RaisedCycleFailure\",\"terminal_authority\":true,\"single_flight\":1,\"next\":\"raise_typed_cycle_failure_after_productivity_window\"}" [| box (esc key); box (esc site); box depth; box gen; box visitCount; box visitBudget; box unproductiveStreak; box unproductiveAgeMs; box (esc basisText); box occurrenceCount |])
                    with _ -> ()
                admission

        let trip (kind: EvalVisitKind) (key: string) (site: string) (depth: int) (gen: int) (re: int) (maxRe: int) : unit =
            tripWithTrace kind key site depth gen re maxRe []

        let isTripped () : bool =
            lock lock_obj (fun () ->
                match state with
                | TermCycleFuseOpen -> false
                | TermCycleFuseTripped _ -> true)

        let describe () : EvalVisitKind option * string * string * int * int * int * int =
            lock lock_obj (fun () ->
                match state with
                | TermCycleFuseOpen -> None, "", "", 0, 0, 0, 0
                | TermCycleFuseTripped evidence -> Some evidence.kind, evidence.key, evidence.site, evidence.depth, evidence.generation, evidence.reentry, evidence.maxReentry)

        let traceSnapshot () =
            lock lock_obj (fun () ->
                match state with
                | TermCycleFuseOpen -> []
                | TermCycleFuseTripped evidence -> evidence.trace)

        /// Clear the one-way fuse before a whole-build retry.
        let reset () : unit =
            lock lock_obj (fun () -> state <- TermCycleFuseOpen)
            prefetchBucketSeen.Clear()


    /// Centralized evaluator fallback budgets.
    ///
    /// Hardcoded only. Keep the parallel attempt strict, but give forced
    /// sequential mode a single legacy-style budget so future changes are policy edits,
    /// not scattered magic numbers. This module intentionally does not reference
    /// BigStack because it is declared later in the compiler file.
    module EvalFallbackPolicy =
        let depthBase : int = 2048
        let parallelBigDepth : int = 4096
        let sequentialBigDepth : int = 32768
        let sequentialReentryMax : int = 4096
        let sequentialJpWaitStallMs : int64 = 1000L
        let sequentialJpWaitHelpWindowMs : int64 = 0L
        let sequentialJpWaitSlowJobs : int = 4
        let sequentialDeepCycleDepth : int = 4096
        let sequentialDeepCycleReentryMax : int = 1024

        let maxDepthBig (seqNow: bool) : int =
            if seqNow then sequentialBigDepth else parallelBigDepth

        let maxReentry (seqNow: bool) (invNow: int64) (depth: int) : int =
            if seqNow && depth >= sequentialDeepCycleDepth then sequentialDeepCycleReentryMax
            elif seqNow then sequentialReentryMax
            elif depth > 512 then 64
            elif invNow > 0L then 128
            else 256

        let warnReentry (maxReentryBase: int) : int = max 32 (maxReentryBase / 4)

        let retryStopReasonForCycle (_key: string) (_site: string) (depth: int) (re: int) (maxRe: int) =
            if depth >= sequentialDeepCycleDepth && maxRe > 0 && re > maxRe then
                "deep_reentry_saturation_after_sequential_retry"
            elif depth >= sequentialBigDepth / 2 then
                "deep_reentrant_cycle_after_sequential_retry"
            elif maxRe > 0 && re > maxRe then
                "reentry_budget_exhausted_after_sequential_retry"
            else
                "semantic_cycle_after_sequential_retry"

        let describe (seqNow: bool) (invNow: int64) (depth: int) =
            FastRuntimeFormat.format "seq=%b inv=%d depth=%d max_re=%d max_depth_big=%d seq_wait_stall_ms=%d seq_wait_help_window_ms=%d deep_cycle_depth=%d deep_cycle_max_re=%d stall_clock=%s policy_next=explicit_eval_worklist" [| box seqNow; box invNow; box depth; box (maxReentry seqNow invNow depth); box (maxDepthBig seqNow); box sequentialJpWaitStallMs; box sequentialJpWaitHelpWindowMs; box sequentialDeepCycleDepth; box sequentialDeepCycleReentryMax; box (if seqNow then "elapsed" else "idle") |]


    /// Generic boundary marker for the next stack-safe evaluator step.
    ///
    /// This deliberately does not know about source files such as listm/core/runtime.
    /// This deliberately stays source-path agnostic.
    /// It only records evaluator shape: sequential fallback, depth, re-entry, and fuse state.
    module EvalWorklistFrontier =
        let private esc (s: string) =
            if System.Object.ReferenceEquals(s,null) then "null" else
                let s =
                    s.Replace("\\","\\\\")
                     .Replace("\"","\\\"")
                     .Replace("\r","\\r")
                     .Replace("\n","\\n")
                     .Replace("\t","\\t")
                "\"" + s + "\""

        let isDeepSequentialCycle (depth: int) (re: int) (maxRe: int) =
            depth >= EvalFallbackPolicy.sequentialDeepCycleDepth
            && maxRe > 0
            && re > maxRe

        let emit (code: string) (reason: string) (key: string) (site: string) (depth: int) (re: int) (maxRe: int) =
            DiagJson.emit (
                FastRuntimeFormat.format "{\"kind\":\"eval_frontier\",\"code\":%s,\"reason\":%s,\"key\":%s,\"site\":%s,\"depth\":%d,\"re\":%d,\"max_re\":%d,\"policy\":\"stack_safe_worklist_required\",\"policy_next\":\"explicit_eval_worklist\"}" [| box (esc code); box (esc reason); box (esc key); box (esc site); box depth; box re; box maxRe |])

        let reasonForCycle (fallbackReason: string) (depth: int) (re: int) (maxRe: int) =
            if isDeepSequentialCycle depth re maxRe then "explicit_worklist_required_after_sequential_cycle"
            else fallbackReason


    module Utils =
        open System
        open System.Collections.Generic
        open System.Collections.Concurrent
        open System.Runtime.CompilerServices
    

        /// ### list_try_zip
        let list_try_zip a b =
            try Some (List.zip a b) with _ -> None
    

        /// ### get_default
        let inline get_default (memo_dict: ^D) (k: ^K) (def: unit -> ^V) : ^V =
            let mutable v = Unchecked.defaultof<^V>
            if (^D : (member TryGetValue : ^K * byref<^V> -> bool) (memo_dict, k, &v)) then v
            else def()
    

        /// ### memoize'
        let memoize' (memo_dict: ConditionalWeakTable<_,_>) f k =
            match memo_dict.TryGetValue k with
            | true, v -> v
            | false, _ ->
                let v = f k
                memo_dict.Add(k,v)
                v
    

        /// ### memoize
        let memoize (memo_dict: System.Collections.Concurrent.ConcurrentDictionary<_,_>) f k =
            match memo_dict.TryGetValue k with
            | true, v -> v
            | false, _ ->
                let v = f k
                if memo_dict.TryAdd(k,v) then v
                else memo_dict.[k]
    

        /// ### file_uri
        let file_uri (x : string) =
            let result = x |> SpiralFileSystem.standardize_path |> SpiralFileSystem.new_file_uri
            trace Verbose (fun () -> $"Utils.file_uri / x: {x} / result: {result}") _locals
            result
    

