    /// ## ParserCombinators

    /// ### index
    let inline index d = (^a : (member Index: ^b) d)

    /// ### index_set
    let inline index_set i d = (^a : (member set_Index: ^b -> unit) (d,i))

    /// ### (.>>.)
    let inline (.>>.) a b d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b -> Ok (a,b)
            | Error x -> Error x
        | Error x -> Error x

    /// ### tuple3
    let inline tuple3 a b c d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c -> Ok (a, b, c)
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x

    /// ### tuple4
    let inline tuple4 a b c d' d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c ->
                    match d' d with
                    | Ok d' -> Ok (a, b, c, d')
                    | Error x -> Error x
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x

    /// ### tuple5
    let inline tuple5 a b c d' e d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c ->
                    match d' d with
                    | Ok d' ->
                        match e d with
                        | Ok e -> Ok (a, b, c, d', e)
                        | Error x -> Error x
                    | Error x -> Error x
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x

    /// ### tuple6
    let inline tuple6 a b c d' e f d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c ->
                    match d' d with
                    | Ok d' ->
                        match e d with
                        | Ok e ->
                            match f d with
                            | Ok f -> Ok (a, b, c, d', e, f)
                            | Error x -> Error x
                        | Error x -> Error x
                    | Error x -> Error x
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x

    /// ### tuple7
    let inline tuple7 a b c d' e f g d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c ->
                    match d' d with
                    | Ok d' ->
                        match e d with
                        | Ok e ->
                            match f d with
                            | Ok f ->
                                match g d with
                                | Ok g -> Ok (a, b, c, d', e, f, g)
                                | Error x -> Error x
                            | Error x -> Error x
                        | Error x -> Error x
                    | Error x -> Error x
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x

    /// ### pipe2
    let inline pipe2 a b f d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b -> Ok (f a b)
            | Error x -> Error x
        | Error x -> Error x

    /// ### pipe3
    let inline pipe3 a b c f d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c -> Ok (f a b c)
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x

    /// ### pipe4
    let inline pipe4 a b c d' f d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c ->
                    match d' d with
                    | Ok d' -> Ok (f a b c d')
                    | Error x -> Error x
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x

    /// ### pipe5
    let inline pipe5 a b c d' e f d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c ->
                    match d' d with
                    | Ok d' ->
                        match e d with
                        | Ok e -> Ok (f a b c d' e)
                        | Error x -> Error x
                    | Error x -> Error x
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x

    /// ### (.>>)
    let inline (.>>) a b d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b -> Ok a
            | Error x -> Error x
        | Error x -> Error x

    /// ### (>>.)
    let inline (>>.) a b d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b -> Ok b
            | Error x -> Error x
        | Error x -> Error x

    /// ### opt
    let inline opt a d =
        let s = index d
        match a d with
        | Ok a -> Ok(Some a)
        | Error x ->
            if s = index d then Ok(None)
            else Error x

    /// ### optional
    let inline optional a d =
        let s = index d
        match a d with
        | Ok a -> Ok()
        | Error x ->
            if s = index d then Ok()
            else Error x

    /// ### (|>>)
    let inline (|>>) a b d =
        match a d with
        | Ok a -> Ok(b a)
        | Error x -> Error x

    /// ### (>>%)
    let inline (>>%) a b d =
        match a d with
        | Ok a -> Ok(b)
        | Error x -> Error x

    /// ### (>>=)
    let inline (>>=) a b d =
        match a d with
        | Ok a -> b a d
        | Error x -> Error x

    /// ### (>>=?)
    let inline (>>=?) a b d =
        let i = index d
        match a d with
        | Ok a ->
            let i' = index d
            match b a d with
            | Ok _ as x -> x
            | Error _ as x -> (if i' = index d then index_set i d); x // Backtracks to the beginning if the parser state has not changed.
        | Error x -> Error x

    /// ### many_iter
    let inline many_iter f a d =
        let rec loop () =
            let s = index d
            match a d with
            | Ok _ when s = index d -> failwith "The parser succeeded without changing the parser index in `many`. Had an exception not been raised the parser would have diverged."
            | Ok x -> f x; loop()
            | Error er -> if s = index d then Ok() else Error er
        loop ()

    /// ### many_resize_array
    let inline many_resize_array a d =
        let ar = ResizeArray()
        match many_iter ar.Add a d with
        | Ok() -> Ok(ar)
        | Error er -> Error er

    /// ### many_array
    let inline many_array a d = many_resize_array a d |> Result.map (fun x -> x.ToArray())

    /// ### many
    let inline many a d = many_resize_array a d |> Result.map Seq.toList

    /// ### sepBy
    let inline sepBy a b d =
        let s = index d
        match a d with
        | Ok a' -> (many (b >>. a) |>> fun b -> a' :: b) d
        | Error x -> if s = index d then Ok [] else Error x

    /// ### sepBy1
    let inline sepBy1 a b d =
        match a d with
        | Ok a' -> (many (b >>. a) |>> fun b -> a' :: b) d
        | Error x -> Error x

    /// ### many1
    let inline many1 a d =
        match a d with
        | Ok a' -> (many a |>> fun b -> a' :: b) d
        | Error x -> Error x

    /// ### attempt
    let inline attempt a d =
        let s = index d
        match a d with
        | Ok x -> Ok x
        | Error a as a' -> index_set s d; a'

    /// ### restore
    /// Restores the index on an error if at least i tokens have been consumed.
    let inline restore i a d =
        let s = index d
        match a d with
        | Ok x -> Ok x
        | Error _ as er -> (if index d <= s + i then index_set s d); er

    /// ### alt
    let inline alt s a b d =
        match a d with
        | Ok x -> Ok x
        | Error a as a' ->
            if s = index d then
                match b d with
                | Ok x -> Ok x
                | Error b -> if s = index d then Error(List.append a b) else Error b
            else
                a'

    /// ### (<|>)
    let inline (<|>) a b d = let s = index d in alt s a b d

    /// ### (<|>%)
    let inline (<|>%) a b d =
        let s = index d
        match a d with
        | Ok x -> Ok x
        | Error _ as a' -> if s = index d then Ok b else a'

    /// ### choice
    let inline choice ar d =
        let s = index d
        let rec loop i =
            if i < Array.length ar then
                match ar.[i] d with
                | Ok x -> Ok x
                | Error a as a' ->
                    if s = index d then
                        match loop (i+1) with
                        | Ok x -> Ok x
                        | Error b -> Error(List.append a b)
                    else
                        a'
            else
                Error []
        loop 0

    /// ### between
    let inline between a b c = a >>. c .>> b

    /// ## LineParsers
    // open System
    open System.Text

    open Microsoft.FSharp.Core

    /// ### TokenizerRange
    type TokenizerRange = {from : int; nearTo : int}

    /// ### TokenizerError
    type TokenizerError = string

    /// ### Tokenizer
    type Tokenizer = {
        text : string // A single line.
        mutable from : int
        } with

        member t.Index with get() = t.from and set i = t.from <- i

    /// ### range_char
    let range_char i = {from=i; nearTo=i+1}

    /// ### error_char
    let error_char i er = Error [range_char i, er]

    /// ### inc'
    let inc' i (s : Tokenizer) = s.from <- s.from+i

    /// ### inc
    let inc (s : Tokenizer) = inc' 1 s

    /// ### lineParsersEol
    /// End Of Line character
    let lineParsersEol = Char.MaxValue

    /// ### peek'
    let peek' (s : Tokenizer) i =
        let i = s.from + i
        if 0 <= i && i < s.text.Length then s.text.[i]
        else lineParsersEol

    /// ### peek
    let peek (s : Tokenizer) = peek' s 0

    /// ### many1Satisfy2L
    let inline many1Satisfy2L init body label (s : Tokenizer) =
        let x = peek s
        if init x && x <> lineParsersEol then
            inc s
            let rec loop (b : StringBuilder) =
                let x = peek s
                if body x && x <> lineParsersEol then inc s; b.Append(x) |> loop
                else b.ToString()
            Ok(loop (StringBuilder().Append(x)))
        else
            let i = s.from
            error_char i label

    /// ### many1SatisfyL
    let inline many1SatisfyL body label (s : Tokenizer) = many1Satisfy2L body body label s

    /// ### skip
    let inline skip c (s : Tokenizer) = let b = peek s = c in (if b then inc s); b

    /// ### spaces'
    let rec spaces' (s : Tokenizer) = if peek s = ' ' then inc s; spaces' s

    /// ### spaces
    let spaces s = spaces' s |> Ok

    /// ### spaces1
    let spaces1 (s : Tokenizer) =
        if peek s = ' ' then inc s; spaces s else error_char s.from "space"

    /// ### skip_char
    let skip_char c (s : Tokenizer) =
        let from = s.from
        if skip c s then Ok() else error_char from (sprintf "'%c'" c)

    /// ### skip_string
    let skip_string x (s : Tokenizer) =
        if String.Compare(s.text,s.from,x,0,x.Length) = 0 then inc' x.Length s; Ok()
        else error_char s.from x

    /// ### anyOf
    let anyOf (l : char list) (s : Tokenizer) =
        let c = peek s
        if Seq.contains c l then
            inc s; Ok(c)
        else
            let i = s.from
            Error (List.map (fun c -> range_char i, string c) l)

    /// ### chars_till_string
    let chars_till_string close (s : Tokenizer) =
        assert (close <> "")
        let rec loop (b : StringBuilder) =
            let x = peek s
            if x = close.[0] && String.Compare(s.text,s.from,close,1,close.Length-1) = 0 then inc' close.Length s; Ok(b.ToString())
            else
                if x <> lineParsersEol then inc s; b.Append(x) |> loop
                else error_char s.from close
        loop(StringBuilder())

    /// ### lineParsersNumber
    /// Parses a number as a sequence of digits and optionally underscores. Filters out the underscores from the result.
    let lineParsersNumber (s : Tokenizer) =
        let x = peek s
        if Char.IsDigit x then
            inc s
            let rec loop (b : StringBuilder) =
                let x = peek s
                if x = '_' then inc s; loop b
                elif Char.IsDigit x then inc s; loop(b.Append(x))
                else Ok(b.ToString())
            loop (StringBuilder().Append(x))
        else
            let i = s.from
            error_char i "number"

    /// ### number_fractional
    let number_fractional s = (lineParsersNumber .>>. (opt (skip_char '.' >>. lineParsersNumber))) s

    /// ## VSCTypes

    /// ### VSCPos
    type VSCPos = {|line : int; character : int|}

    // Cross-assembly factories for the anonymous position record.
    let vscpos line character : VSCPos =
        {|line=line; character=character|}
    let vscpos_with_line line (a : VSCPos) : VSCPos =
        vscpos line a.character

    /// ### VSCRange
    type VSCRange = VSCPos * VSCPos

    /// ### RString
    type RString = VSCRange * string

    /// ### PackageId
    type PackageId = int

    /// ### ModuleId
    type ModuleId = int

    /// ### DirId
    type DirId = int

    /// ### GlobalId
    type GlobalId = { package_id : PackageId; module_id : ModuleId; tag : int }

    let globalIdStableText (id: GlobalId) =
        string id.package_id + ":" + string id.module_id + ":" + string id.tag

    /// ### RGlobalId
    type RGlobalId = VSCRange * GlobalId

    /// ### SpiEdit
    type SpiEdit = {|from: int; nearTo: int; lines: string []|}

