        /// ## HopacExtensions
        open Hopac
        open Hopac.Infixes
    

        let (>>**) x f =
            if x |> Hopac.Promise.Now.isFulfilled
            then x |> Hopac.Promise.Now.get |> f
            else Hopac.Infixes.(>>=*) x f
        // Runtime Hopac re-export e utilitários base (definir antes de uso para evitar FS0039).
        open System.Threading.Tasks
    

        let private hopacRunPrimitive (j: Job<'a>) : 'a = run j
        let run (j: Job<'a>) : 'a = hopacRunPrimitive j
        let start (j: Job<unit>) : unit = startHopacJob j
        let queue (j: Job<unit>) : unit = start j
        let server (j: Job<unit>) : unit = start j
        let startAsTask (j: Job<'a>) : Task<'a> = Task.Run(fun () -> hopacRunPrimitive j)
        let queueAsTask (j: Job<'a>) : Task<'a> = startAsTask j
    

        let awaitUnitTask (t: Task) : Job<unit> = Hopac.Job.awaitUnitTask t
        let awaitTask (t: Task<'a>) : Job<'a> = Job.fromAsync (Async.AwaitTask t)
    

        // Sleep/timeout como Job, para remover Async.Sleep e Alt ambiguo do resto do arquivo.
        let  sleepMs (ms: int) : Job<unit> = awaitUnitTask (Task.Delay ms)

        // Concurrency override hook (wired later in module)
        // - default is 0 (no cap)
        // - forceConcurrency updates the backing store; this hook lets earlier helpers respect it
        let mutable private getForcedConcurrency : unit -> int = fun () -> 0

        let  private capConcurrency (requested: int) : int =
            let req = max 1 requested
            let forced = getForcedConcurrency()
            if forced > 0 then min forced req else req

    
    


