#if SPIRAL_CORE_HOPAC
        /// ## BlockBundling
        open Hopac.Extensions
        open Hopac.Stream
        /// Run a Hopac Job/Alt with a timeout (ms), returning None on timeout.
        /// Implemented via Tasks to avoid Alt/Job operator overload pitfalls.
        let jobWithTimeoutMs (timeoutMs: int) (work: Job<'a>) : Job<'a option> = job {
            let workT = startAsTask work
            let timeoutT = System.Threading.Tasks.Task.Delay timeoutMs
            let! completed = System.Threading.Tasks.Task.WhenAny(workT :> System.Threading.Tasks.Task, timeoutT)
            if obj.ReferenceEquals(completed, (workT :> System.Threading.Tasks.Task)) then
                let! r = workT
                return Some r
            else
                return None
        }


        // MIGRATION: Hopac-native migration scaffold.
        // This module is deliberately small and side-effect-free except for constructing
        // Hopac primitives. It gives the next migration rounds typed contracts for the
        // three architectural fronts named in the assessment: IVar cells, actor-owned
        // generation cache, and cooperative timeout/poison policy.  It does not replace
        // the evaluator yet and never manufactures semantic/root/write/build evidence.
        module NativeHopacMigration =
            type NativeHopacMigrationPhaseId =
                | NativeHopacMigrationInventory
                | NativeHopacMigrationCellIvarBridge
                | NativeHopacMigrationActorCacheBridge
                | NativeHopacMigrationJobCompositionBridge
                | NativeHopacMigrationAltTimeoutBridge
                | NativeHopacMigrationSchedulerHandover

            let nativeHopacMigrationPhaseText = function
                | NativeHopacMigrationInventory -> "inventory"
                | NativeHopacMigrationCellIvarBridge -> "cell_ivar_bridge"
                | NativeHopacMigrationActorCacheBridge -> "actor_cache_bridge"
                | NativeHopacMigrationJobCompositionBridge -> "job_composition_bridge"
                | NativeHopacMigrationAltTimeoutBridge -> "alt_timeout_bridge"
                | NativeHopacMigrationSchedulerHandover -> "scheduler_handover"

            type NativeHopacReadinessId =
                | NativeHopacReadinessLegacyBlocking
                | NativeHopacReadinessHybridBridge
                | NativeHopacReadinessNativeHopacCandidate
                | NativeHopacReadinessNativeHopacRequiredBeforeSota

            let nativeHopacReadinessText = function
                | NativeHopacReadinessLegacyBlocking -> "legacy_blocking"
                | NativeHopacReadinessHybridBridge -> "hybrid_bridge"
                | NativeHopacReadinessNativeHopacCandidate -> "native_hopac_candidate"
                | NativeHopacReadinessNativeHopacRequiredBeforeSota -> "native_hopac_required_before_sota"

            type NativeHopacWaitPrimitiveId =
                | NativeWaitManualResetEventSlimLegacy
                | NativeWaitSpinYieldLegacy
                | NativeWaitIvarRead
                | NativeWaitPromiseRead
                | NativeWaitAltChooseTimeout

            let nativeHopacWaitPrimitiveText = function
                | NativeWaitManualResetEventSlimLegacy -> "manual_reset_event_slim_legacy"
                | NativeWaitSpinYieldLegacy -> "spin_yield_legacy"
                | NativeWaitIvarRead -> "ivar_read"
                | NativeWaitPromiseRead -> "promise_read"
                | NativeWaitAltChooseTimeout -> "alt_choose_timeout"

            type NativeHopacCellStateId =
                | NativeCellCreated
                | NativeCellAwaitingProducer
                | NativeCellFulfilled
                | NativeCellPoisoned
                | NativeCellGenerationInvalidated

            let nativeHopacCellStateText = function
                | NativeCellCreated -> "created"
                | NativeCellAwaitingProducer -> "awaiting_producer"
                | NativeCellFulfilled -> "fulfilled"
                | NativeCellPoisoned -> "poisoned"
                | NativeCellGenerationInvalidated -> "generation_invalidated"

            type NativeHopacCacheOwnerId =
                | NativeCacheConcurrentDictionaryLegacy
