                | NativeCacheGenerationOwner
                | NativeCacheSidecarPrefetchOwner

            let nativeHopacCacheOwnerText = function
                | NativeCacheConcurrentDictionaryLegacy -> "concurrent_dictionary_legacy"
                | NativeCacheActorOwned -> "actor_owned"
                | NativeCacheGenerationOwner -> "generation_owner"
                | NativeCacheSidecarPrefetchOwner -> "sidecar_prefetch_owner"

            type NativeHopacGenerationPolicyId =
                | NativeGenerationObserveOnly
                | NativeGenerationInvalidateByActor
                | NativeGenerationReplayWaiters
                | NativeGenerationPoisonStaleWaiters

            let nativeHopacGenerationPolicyText = function
                | NativeGenerationObserveOnly -> "observe_only"
                | NativeGenerationInvalidateByActor -> "invalidate_by_actor"
                | NativeGenerationReplayWaiters -> "replay_waiters"
                | NativeGenerationPoisonStaleWaiters -> "poison_stale_waiters"

            type NativeHopacTimeoutPolicyId =
                | NativeTimeoutLegacyMetronome
                | NativeTimeoutAltChooseProbe
                | NativeTimeoutAltChooseHardPoison
                | NativeTimeoutNoGlobalAbortAuthority

            let nativeHopacTimeoutPolicyText = function
                | NativeTimeoutLegacyMetronome -> "legacy_metronome"
                | NativeTimeoutAltChooseProbe -> "alt_choose_probe"
                | NativeTimeoutAltChooseHardPoison -> "alt_choose_hard_poison"
                | NativeTimeoutNoGlobalAbortAuthority -> "no_global_abort_authority"

            type NativeHopacWorklistPolicyId =
                | NativeWorklistLegacyQueueProbation
                | NativeWorklistJobCompositionCandidate
                | NativeWorklistAwaitDependencyIvar
                | NativeWorklistActorRoutedDependency

            let nativeHopacWorklistPolicyText = function
                | NativeWorklistLegacyQueueProbation -> "legacy_queue_probation"
                | NativeWorklistJobCompositionCandidate -> "job_composition_candidate"
                | NativeWorklistAwaitDependencyIvar -> "await_dependency_ivar"
                | NativeWorklistActorRoutedDependency -> "actor_routed_dependency"

            type NativeHopacCacheMsg<'k,'v> =
                | NativeCacheGet of key: 'k * reply: IVar<'v option>
                | NativeCachePut of key: 'k * value: 'v
                | NativeCacheInvalidateGeneration of generation: int64 * policy: NativeHopacGenerationPolicyId
                | NativeCacheMissingDependency of key: 'k * reply: IVar<string>
                | NativeCacheSnapshot of reply: IVar<int * int64>

            type NativeHopacCell<'a> = {
                result: IVar<'a>
                state: NativeHopacCellStateId
                wait_primitive: NativeHopacWaitPrimitiveId
                owner: NativeHopacCacheOwnerId
            }

            let createIvarCell<'a> () : NativeHopacCell<'a> =
                { result = IVar()
                  state = NativeCellCreated
                  wait_primitive = NativeWaitIvarRead
                  owner = NativeCacheActorOwned }

            let createCacheChannel<'k,'v> () : Ch<NativeHopacCacheMsg<'k,'v>> =
                Ch()

            // Shared typed control vocabulary retained by live replay/telemetry consumers.
            // These are domain decisions, not historical receipts; strings are rendered only at boundaries.
            type JsonlHotRowRecycleDecisionId =
                | JsonlHotRowEmitInitial
                | JsonlHotRowEmitPeriodic
                | JsonlHotRowEmitCritical
                | JsonlHotRowSuppressRecycled

            let jsonlHotRowRecycleDecisionText = function
                | JsonlHotRowEmitInitial -> "emit_initial_hot_row"
                | JsonlHotRowEmitPeriodic -> "emit_periodic_hot_row"
                | JsonlHotRowEmitCritical -> "emit_critical_hot_row"
                | JsonlHotRowSuppressRecycled -> "suppress_recycled_hot_row"

            let jsonlHotRowRecycleDecisionShouldEmit = function
                | JsonlHotRowEmitInitial
                | JsonlHotRowEmitPeriodic
                | JsonlHotRowEmitCritical -> true
                | JsonlHotRowSuppressRecycled -> false

            let jsonlHotRowRecycleDecisionFor (seen:int) (initialBudget:int) (period:int) (critical:bool) =
                if critical then JsonlHotRowEmitCritical
                elif seen < initialBudget then JsonlHotRowEmitInitial
                elif period > 0 && seen % period = 0 then JsonlHotRowEmitPeriodic
                else JsonlHotRowSuppressRecycled

            type HopacOverrideArbitrationDecisionId =
                | HopacOverrideNoShadowConflict
                | HopacOverrideLegacyDefersWhileAltAlive
                | HopacOverrideShadowTimeoutPiercesRepeatCap
                | HopacOverridePromoteSymbolicCarrierBeforeFailClosed
                | HopacOverrideFailClosedAfterCarrierReject

            let hopacOverrideArbitrationDecisionText = function
                | HopacOverrideNoShadowConflict -> "no_shadow_conflict"
                | HopacOverrideLegacyDefersWhileAltAlive -> "legacy_defers_while_alt_alive"
                | HopacOverrideShadowTimeoutPiercesRepeatCap -> "shadow_timeout_pierces_legacy_repeat_cap"
                | HopacOverridePromoteSymbolicCarrierBeforeFailClosed -> "promote_symbolic_carrier_before_fail_closed"
                | HopacOverrideFailClosedAfterCarrierReject -> "shadow_timeout_fail_closed_after_carrier_reject"

            let hopacOverrideArbitrationForAltTimeout promotesCarrier =
                if promotesCarrier then HopacOverridePromoteSymbolicCarrierBeforeFailClosed
                else HopacOverrideFailClosedAfterCarrierReject

            let private nativeHopacTextDelimiters =
                [| '|'; '@'; '/'; ':'; '('; ')'; '['; ']'; '{'; '}'; ','; ';'; '='; ' '; '\t'; '\r'; '\n'; '"'; '\'' |]

            let private nativeHopacTextTokensLower (text:string) : Set<string> =
                if String.IsNullOrWhiteSpace text then Set.empty
                else
                    text.Split(nativeHopacTextDelimiters, System.StringSplitOptions.RemoveEmptyEntries)
                    |> Array.map (fun token -> token.ToLowerInvariant())
                    |> Set.ofArray

            type ParentPoisonLegacyOverrideSignalId =
                | ParentPoisonOverrideRepeatCapFreshRootWitness
                | ParentPoisonOverridePinnedTerminal
                | ParentPoisonOverrideStaleRetarget
                | ParentPoisonOverrideHardPoison

            let private parentPoisonLegacyOverrideSignals (reasonProbe:string) (probationState:string) =
                let reasonTokens = nativeHopacTextTokensLower reasonProbe
                let probationTokens = nativeHopacTextTokensLower probationState
                [ if Set.contains "repeat_cap_fresh_root_witness" probationTokens then ParentPoisonOverrideRepeatCapFreshRootWitness
                  if Set.contains "pinned_terminal" probationTokens then ParentPoisonOverridePinnedTerminal
                  if Set.contains "stale_retarget" reasonTokens then ParentPoisonOverrideStaleRetarget
                  if Set.contains "hard_poison" reasonTokens then ParentPoisonOverrideHardPoison ]
                |> Set.ofList

            type ParentPoisonLegacyOverrideTargetId =
                | ParentPoisonNoLegacyOverrideTarget
                | ParentPoisonPierceLiveTailEvidenceNoRootBypass
                | ParentPoisonPierceRepeatCapFreshRootWitness
                | ParentPoisonPiercePinnedTerminalFocus
                | ParentPoisonPierceStaleRetarget
                | ParentPoisonPierceUnknownLegacyOverride

            let parentPoisonLegacyOverrideTargetText = function
                | ParentPoisonNoLegacyOverrideTarget -> "none"
                | ParentPoisonPierceLiveTailEvidenceNoRootBypass -> "live_tail_evidence_overrides_no_root_bypass"
                | ParentPoisonPierceRepeatCapFreshRootWitness -> "repeat_cap_fresh_root_witness_before_pin"
                | ParentPoisonPiercePinnedTerminalFocus -> "pinned_terminal_focus_observe"
                | ParentPoisonPierceStaleRetarget -> "stale_retarget_probation"
                | ParentPoisonPierceUnknownLegacyOverride -> "unknown_legacy_liveness_override"

            let parentPoisonLegacyOverrideTargetFor (liveTailOverride:bool) (reasonProbe:string) (probationState:string) =
                let signals = parentPoisonLegacyOverrideSignals reasonProbe probationState
                if liveTailOverride then ParentPoisonPierceLiveTailEvidenceNoRootBypass
                elif Set.contains ParentPoisonOverrideRepeatCapFreshRootWitness signals then ParentPoisonPierceRepeatCapFreshRootWitness
                elif Set.contains ParentPoisonOverridePinnedTerminal signals then ParentPoisonPiercePinnedTerminalFocus
                elif Set.contains ParentPoisonOverrideStaleRetarget signals then ParentPoisonPierceStaleRetarget
                elif Set.contains ParentPoisonOverrideHardPoison signals then ParentPoisonPierceUnknownLegacyOverride
                else ParentPoisonNoLegacyOverrideTarget

            type LiveReplayAbsenceProofId =
                | LiveReplayAbsenceNotRequired
                | LiveReplayEvidencePresent
                | LiveReplayAbsenceNotProven
                | LiveReplayAbsenceProvenPendingClosed

            let liveReplayAbsenceProofText = function
                | LiveReplayAbsenceNotRequired -> "not_required"
                | LiveReplayEvidencePresent -> "live_replay_evidence_present"
                | LiveReplayAbsenceNotProven -> "live_replay_absence_not_proven"
                | LiveReplayAbsenceProvenPendingClosed -> "live_replay_absence_proven_pending_closed"

            let liveReplayAbsenceProofFor (pending:int) (queueDepth:int) (activeDepth:int) (progressYield:int) =
                if pending <= 0 && queueDepth <= 0 && activeDepth <= 0 && progressYield <= 0 then LiveReplayAbsenceProvenPendingClosed
                elif pending > 0 || queueDepth > 0 || activeDepth > 0 || progressYield > 0 then LiveReplayEvidencePresent
                else LiveReplayAbsenceNotProven

            type HopacPrimaryAuthorityReadinessId =
                | HopacPrimaryNotReadyShadowOnly
                | HopacPrimaryNotReadyActiveSidecarDrain
                | HopacPrimaryNotReadyParentPoisonArbitrationOpen
                | HopacPrimaryNotReadyWriterRootProofMissing
                | HopacPrimaryReadyObservationWindowOnly

            let hopacPrimaryAuthorityReadinessText = function
                | HopacPrimaryNotReadyShadowOnly -> "not_ready_shadow_only"
                | HopacPrimaryNotReadyActiveSidecarDrain -> "not_ready_active_sidecar_drain"
                | HopacPrimaryNotReadyParentPoisonArbitrationOpen -> "not_ready_parent_poison_arbitration_open"
                | HopacPrimaryNotReadyWriterRootProofMissing -> "not_ready_writer_root_proof_missing"
                | HopacPrimaryReadyObservationWindowOnly -> "ready_observation_window_only_no_primary_promotion"

            let hopacPrimaryAuthorityReadinessFor (activeSidecarDrain:bool) (parentPoisonOpen:bool) (writerRootProof:bool) =
                if activeSidecarDrain then HopacPrimaryNotReadyActiveSidecarDrain
                elif parentPoisonOpen then HopacPrimaryNotReadyParentPoisonArbitrationOpen
                elif not writerRootProof then HopacPrimaryNotReadyWriterRootProofMissing
                else HopacPrimaryReadyObservationWindowOnly

            type ParentPoisonVsLiveTailVerdictId =
                | ParentPoisonNoCycleBreak
                | ParentPoisonDeferLiveTailEvidence
                | ParentPoisonDeferLiveTailPhysicalPending
                | ParentPoisonLiveReplayEvidenceStillDraining
                | ParentPoisonShadowAltTimeoutPiercesLiveTailOverride
                | ParentPoisonShadowAltTimeoutPiercesAllLegacyOverrides
                | ParentPoisonWinsNoLiveReplayEvidenceGraceExpired

            let parentPoisonVsLiveTailVerdictText = function
                | ParentPoisonNoCycleBreak -> "not_parent_cycle_break_poison"
                | ParentPoisonDeferLiveTailEvidence -> "defer_poison_live_tail_evidence"
                | ParentPoisonDeferLiveTailPhysicalPending -> "defer_poison_live_tail_physical_pending"
                | ParentPoisonLiveReplayEvidenceStillDraining -> "live_replay_evidence_still_draining"
                | ParentPoisonShadowAltTimeoutPiercesLiveTailOverride -> "shadow_alt_timeout_pierces_live_tail_override"
                | ParentPoisonShadowAltTimeoutPiercesAllLegacyOverrides -> "shadow_alt_timeout_pierces_all_legacy_overrides"
                | ParentPoisonWinsNoLiveReplayEvidenceGraceExpired -> "poison_wins_no_live_replay_evidence_grace_expired"

            let parentPoisonVsLiveTailVerdictPiercesLegacy = function
                | ParentPoisonShadowAltTimeoutPiercesLiveTailOverride
                | ParentPoisonShadowAltTimeoutPiercesAllLegacyOverrides -> true
                | _ -> false

            let parentPoisonVsLiveTailVerdictFor isParentPoison pending queueDepth activeDepth progressYield witnessAgeMs hardCapReceipts suppressedPins preservedRepeats liveTailOverride =
                if not isParentPoison then ParentPoisonNoCycleBreak
                elif liveTailOverride && witnessAgeMs >= 1500.0 && (hardCapReceipts > 0 || suppressedPins >= 4 || preservedRepeats >= 4 || progressYield >= 512) then ParentPoisonShadowAltTimeoutPiercesAllLegacyOverrides
                elif liveTailOverride && pending > 0 then ParentPoisonDeferLiveTailPhysicalPending
                elif liveTailOverride then ParentPoisonDeferLiveTailEvidence
                elif pending > 0 || queueDepth > 0 || activeDepth > 0 || progressYield > 0 then ParentPoisonLiveReplayEvidenceStillDraining
                else ParentPoisonWinsNoLiveReplayEvidenceGraceExpired

            type PinnedTerminalReplayEvidenceId =
                | PinnedTerminalShadowTimeoutPiercesLegacyLiveTail
                | PinnedTerminalLiveReplayOrTailEvidencePresent
                | PinnedTerminalNoLiveReplayEvidence

            let pinnedTerminalReplayEvidenceText = function
                | PinnedTerminalShadowTimeoutPiercesLegacyLiveTail -> "shadow_timeout_pierces_legacy_live_tail"
                | PinnedTerminalLiveReplayOrTailEvidencePresent -> "live_replay_or_tail_evidence_present"
                | PinnedTerminalNoLiveReplayEvidence -> "no_live_replay_evidence"

            let pinnedTerminalReplayEvidenceFor shadowPierced liveReplayOrTailPresent =
                if shadowPierced then PinnedTerminalShadowTimeoutPiercesLegacyLiveTail
                elif liveReplayOrTailPresent then PinnedTerminalLiveReplayOrTailEvidencePresent
                else PinnedTerminalNoLiveReplayEvidence

            type NativeHopacSidecarDrainAuthorityId =
                | NativeSidecarDrainNoTarget
                | NativeSidecarDrainShadowIvarRegistered
                | NativeSidecarDrainMailboxProbeScheduled
                | NativeSidecarDrainAltTimeoutHoldoff
                | NativeSidecarDrainAltTimeoutExpiredFailClosed
                | NativeSidecarDrainPrimaryStillBlocked

            let nativeHopacSidecarDrainAuthorityText = function
                | NativeSidecarDrainNoTarget -> "no_sidecar_target"
                | NativeSidecarDrainShadowIvarRegistered -> "shadow_ivar_registered"
                | NativeSidecarDrainMailboxProbeScheduled -> "mailbox_probe_scheduled"
                | NativeSidecarDrainAltTimeoutHoldoff -> "alt_timeout_holdoff"
                | NativeSidecarDrainAltTimeoutExpiredFailClosed -> "alt_timeout_expired_fail_closed"
                | NativeSidecarDrainPrimaryStillBlocked -> "primary_hopac_blocked"

            type NativeHopacSidecarIvarStateId =
                | NativeSidecarIvarNoTarget
                | NativeSidecarIvarShadowRegistered
                | NativeSidecarIvarAwaitingFill
                | NativeSidecarIvarFilledButPrimaryBlocked
                | NativeSidecarIvarExpiredFailClosed

            let nativeHopacSidecarIvarStateText = function
                | NativeSidecarIvarNoTarget -> "no_target"
                | NativeSidecarIvarShadowRegistered -> "shadow_ivar_registered"
                | NativeSidecarIvarAwaitingFill -> "shadow_ivar_awaiting_fill"
                | NativeSidecarIvarFilledButPrimaryBlocked -> "shadow_ivar_filled_primary_blocked"
                | NativeSidecarIvarExpiredFailClosed -> "shadow_ivar_expired_fail_closed"

            type NativeHopacMailboxProbeStateId =
                | NativeMailboxProbeNone
                | NativeMailboxProbeScheduled
                | NativeMailboxProbeObservedMiss
                | NativeMailboxProbeObservedHitPrimaryBlocked
                | NativeMailboxProbeExpiredFailClosed

            let nativeHopacMailboxProbeStateText = function
                | NativeMailboxProbeNone -> "mailbox_probe_none"
                | NativeMailboxProbeScheduled -> "mailbox_probe_scheduled"
                | NativeMailboxProbeObservedMiss -> "mailbox_probe_observed_miss"
                | NativeMailboxProbeObservedHitPrimaryBlocked -> "mailbox_probe_observed_hit_primary_blocked"
                | NativeMailboxProbeExpiredFailClosed -> "mailbox_probe_expired_fail_closed"

            type NativeHopacAltStateId =
                | NativeAltNoTarget
                | NativeAltArmedShadowOnly
                | NativeAltHoldoff
                | NativeAltExpiredFailClosed

            let nativeHopacAltStateText = function
                | NativeAltNoTarget -> "alt_no_target"
                | NativeAltArmedShadowOnly -> "alt_armed_shadow_only"
                | NativeAltHoldoff -> "alt_timeout_holdoff"
                | NativeAltExpiredFailClosed -> "alt_timeout_expired_fail_closed"

            type NativeHopacSidecarLeaseStateId =
                | NativeSidecarLeaseNoTarget
                | NativeSidecarLeasePhysicalPending
                | NativeSidecarLeaseQ0P0Vetoed
                | NativeSidecarLeaseExpiredFailClosed

            let nativeHopacSidecarLeaseStateText = function
                | NativeSidecarLeaseNoTarget -> "lease_no_target"
                | NativeSidecarLeasePhysicalPending -> "lease_physical_pending"
                | NativeSidecarLeaseQ0P0Vetoed -> "lease_q0_p0_vetoed"
                | NativeSidecarLeaseExpiredFailClosed -> "lease_expired_fail_closed"

            type NativeHopacSidecarTargetId =
                | NativeSidecarTargetAbsent
                | NativeSidecarTargetPresent of key:string

            let nativeHopacSidecarTargetOfText (targetKey:string) =
                if String.IsNullOrWhiteSpace targetKey || targetKey = "-" || targetKey = "none" then NativeSidecarTargetAbsent
                else NativeSidecarTargetPresent targetKey

            let nativeHopacSidecarHasTarget = function
                | NativeSidecarTargetPresent _ -> true
                | NativeSidecarTargetAbsent -> false

            type NativeHopacSidecarTimingBasisId =
                | NativeSidecarTimingStaticSafetyWindow of holdoffMs:int64 * failClosedMs:int64

            type NativeHopacSidecarTimingBandId =
                | NativeSidecarTimingProbeWindow
                | NativeSidecarTimingHoldoffWindow
                | NativeSidecarTimingFailClosedDeadline

            let nativeHopacSidecarTimingBasis = NativeSidecarTimingStaticSafetyWindow(40000L, 60000L)

            let nativeHopacSidecarTimingBandFor basis ageMs =
                match basis with
                | NativeSidecarTimingStaticSafetyWindow(holdoffMs, failClosedMs) ->
                    if ageMs >= failClosedMs then NativeSidecarTimingFailClosedDeadline
                    elif ageMs >= holdoffMs then NativeSidecarTimingHoldoffWindow
                    else NativeSidecarTimingProbeWindow

            let nativeHopacSidecarTimingBasisText = function
                | NativeSidecarTimingStaticSafetyWindow(holdoffMs, failClosedMs) ->
                    "StaticSafetyWindow(holdoff_ms=" + string holdoffMs + "|fail_closed_ms=" + string failClosedMs + ")"

            let nativeHopacSidecarIvarStateFor (pending:int) target (ageMs:int64) =
                let timingBand = nativeHopacSidecarTimingBandFor nativeHopacSidecarTimingBasis ageMs
                if not (nativeHopacSidecarHasTarget target) then NativeSidecarIvarNoTarget
                elif pending <= 0 || timingBand = NativeSidecarTimingFailClosedDeadline then NativeSidecarIvarExpiredFailClosed
                else NativeSidecarIvarAwaitingFill

            let nativeHopacMailboxProbeStateFor (pending:int) (queueDepth:int) (activeDepth:int) target (ageMs:int64) =
                let timingBand = nativeHopacSidecarTimingBandFor nativeHopacSidecarTimingBasis ageMs
                if not (nativeHopacSidecarHasTarget target) then NativeMailboxProbeNone
                elif pending <= 0 || timingBand = NativeSidecarTimingFailClosedDeadline then NativeMailboxProbeExpiredFailClosed
                elif queueDepth > 0 || activeDepth > 0 then NativeMailboxProbeScheduled
                else NativeMailboxProbeObservedMiss

            let nativeHopacAltStateFor (pending:int) target (ageMs:int64) =
                let timingBand = nativeHopacSidecarTimingBandFor nativeHopacSidecarTimingBasis ageMs
                if not (nativeHopacSidecarHasTarget target) then NativeAltNoTarget
                elif pending <= 0 || timingBand = NativeSidecarTimingFailClosedDeadline then NativeAltExpiredFailClosed
                elif timingBand = NativeSidecarTimingHoldoffWindow then NativeAltHoldoff
                else NativeAltArmedShadowOnly

            let nativeHopacSidecarLeaseStateFor (pending:int) (queueDepth:int) (activeDepth:int) target (ageMs:int64) =
                let timingBand = nativeHopacSidecarTimingBandFor nativeHopacSidecarTimingBasis ageMs
                if not (nativeHopacSidecarHasTarget target) then NativeSidecarLeaseNoTarget
                elif pending <= 0 && queueDepth <= 0 then NativeSidecarLeaseQ0P0Vetoed
                elif timingBand = NativeSidecarTimingFailClosedDeadline then NativeSidecarLeaseExpiredFailClosed
                else NativeSidecarLeasePhysicalPending

            type NativeHopacSidecarUnblockReadyId =
                | NativeSidecarUnblockNotReadyProbeScheduled
                | NativeSidecarUnblockFailClosed
                | NativeSidecarUnblockNotReadyPrimaryBlocked

            let nativeHopacSidecarUnblockReadyForStates ivarState mailboxState altState leaseState =
                match ivarState, mailboxState, altState, leaseState with
                | NativeSidecarIvarAwaitingFill, NativeMailboxProbeScheduled, NativeAltArmedShadowOnly, NativeSidecarLeasePhysicalPending -> NativeSidecarUnblockNotReadyProbeScheduled
                | NativeSidecarIvarExpiredFailClosed, _, _, _
                | _, NativeMailboxProbeExpiredFailClosed, _, _
                | _, _, NativeAltExpiredFailClosed, _
                | _, _, _, NativeSidecarLeaseExpiredFailClosed
                | _, _, _, NativeSidecarLeaseQ0P0Vetoed -> NativeSidecarUnblockFailClosed
                | _ -> NativeSidecarUnblockNotReadyPrimaryBlocked

            let nativeHopacSidecarUnblockReadyText = function
                | NativeSidecarUnblockNotReadyProbeScheduled -> "shadow_unblock_not_ready_probe_scheduled"
                | NativeSidecarUnblockFailClosed -> "unblock_fail_closed"
                | NativeSidecarUnblockNotReadyPrimaryBlocked -> "shadow_unblock_not_ready_primary_blocked"

            let nativeHopacSidecarDrainAuthorityFor (pending:int) (queueDepth:int) (activeDepth:int) target (ageMs:int64) =
                let timingBand = nativeHopacSidecarTimingBandFor nativeHopacSidecarTimingBasis ageMs
                if not (nativeHopacSidecarHasTarget target) then NativeSidecarDrainNoTarget
                elif pending <= 0 || timingBand = NativeSidecarTimingFailClosedDeadline then NativeSidecarDrainAltTimeoutExpiredFailClosed
                elif queueDepth > 0 || activeDepth > 0 then NativeSidecarDrainMailboxProbeScheduled
                else NativeSidecarDrainShadowIvarRegistered

            let nativeHopacSidecarDrainPrimaryBlockerText = function
                | NativeSidecarDrainAltTimeoutExpiredFailClosed -> "sidecar_alt_timeout_expired_fail_closed_primary_blocked"
                | NativeSidecarDrainNoTarget -> "sidecar_target_missing_primary_blocked"
                | _ -> "terminal_payload_outranks_qap_bypasses_shadow_sidecar_drain_parity"

            // MIGRATION: typed native-Hopac obligation model.
            // This is the next destructive-but-shadowed migration seam requested by the assessments:
            // replace raw replay-key strings and driver while-loops with kind-tagged obligations whose
            // reply cell and timeout budget travel with the work item.  It deliberately remains a
            // typed scaffold: no semantic value, root proof, writer witness, or BuildOk is fabricated here.
            type NativeTermKind =
                | NativeTermKind
            type NativeTyKind =
                | NativeTyKind

            [<Struct>]
            type NativeNodeId<'Kind> = NativeNodeId of int

            let nativeNodeIdValue (NativeNodeId value) = value

            type NativeSyntheticNodeRoleId =
                | NativeSyntheticParentContinuationCycleOwner
                | NativeSyntheticParentContinuationCycleChild
                | NativeSyntheticDynamicRecordKeyBridgeTarget
                | NativeSyntheticSmallQueueParentReplayPoisonOwner
                | NativeSyntheticSmallQueueParentReplayPoisonChild
                | NativeSyntheticStackFenceOwner
                | NativeSyntheticStackFenceChild
                | NativeSyntheticDeferredChildCell
                | NativeSyntheticIfUnknownReturnConditionOwner
                | NativeSyntheticIfUnknownReturnConditionChild

            let nativeSyntheticNodeRoleText = function
                | NativeSyntheticParentContinuationCycleOwner -> "parent_continuation_cycle_owner"
                | NativeSyntheticParentContinuationCycleChild -> "parent_continuation_cycle_child"
                | NativeSyntheticDynamicRecordKeyBridgeTarget -> "dynamic_record_key_bridge_target"
                | NativeSyntheticSmallQueueParentReplayPoisonOwner -> "small_queue_parent_replay_poison_owner"
                | NativeSyntheticSmallQueueParentReplayPoisonChild -> "small_queue_parent_replay_poison_child"
                | NativeSyntheticStackFenceOwner -> "stack_fence_owner"
                | NativeSyntheticStackFenceChild -> "stack_fence_child"
                | NativeSyntheticDeferredChildCell -> "deferred_child_cell"
                | NativeSyntheticIfUnknownReturnConditionOwner -> "if_unknown_return_condition_owner"
                | NativeSyntheticIfUnknownReturnConditionChild -> "if_unknown_return_condition_child"

            let nativeSyntheticNodeId<'Kind> role : NativeNodeId<'Kind> =
                let raw =
                    NativeCutoverStableRef.ref32
                        "native-synthetic-node"
                        [ nativeSyntheticNodeRoleText role ]
                    &&& 0x7fffffffu
                NativeNodeId (if raw = 0u then 1 else int raw)

            type NativeReplayDriverKindId =
                | NativeReplayDriverTerm
                | NativeReplayDriverTy
                | NativeReplayDriverCrossKind

            let nativeReplayDriverKindText = function
                | NativeReplayDriverTerm -> "term"
                | NativeReplayDriverTy -> "ty"
                | NativeReplayDriverCrossKind -> "cross_kind"

            type NativeReplayShapeId =
                | NativeReplayShapeApply
                | NativeReplayShapeFunctionBody
                | NativeReplayShapeRecordKey
                | NativeReplayShapeParentHandoff
                | NativeReplayShapeContinuationCell
                | NativeReplayShapeDeferredChild
                | NativeReplayShapeUnknown

            let nativeReplayShapeText = function
                | NativeReplayShapeApply -> "apply"
                | NativeReplayShapeFunctionBody -> "function_body"
                | NativeReplayShapeRecordKey -> "record_key"
                | NativeReplayShapeParentHandoff -> "parent_handoff"
                | NativeReplayShapeContinuationCell -> "continuation_cell"
                | NativeReplayShapeDeferredChild -> "deferred_child"
                | NativeReplayShapeUnknown -> "unknown"

            type NativeReplayKey<'Kind> =
                | NativeApplyArg of node: NativeNodeId<'Kind> * index: int
                | NativeFunctionBody of node: NativeNodeId<'Kind>
                | NativeRecordKey of name: string * node: NativeNodeId<'Kind>
                | NativeParentHandoff of node: NativeNodeId<'Kind>
                | NativeContinuationCell of owner: NativeNodeId<'Kind> * child: NativeNodeId<'Kind>
                | NativeDeferredChildCell of owner: NativeNodeId<'Kind> * child: NativeNodeId<'Kind>

            let nativeReplayKeyShape = function
                | NativeApplyArg _ -> NativeReplayShapeApply
                | NativeFunctionBody _ -> NativeReplayShapeFunctionBody
                | NativeRecordKey _ -> NativeReplayShapeRecordKey
                | NativeParentHandoff _ -> NativeReplayShapeParentHandoff
                | NativeContinuationCell _ -> NativeReplayShapeContinuationCell
                | NativeDeferredChildCell _ -> NativeReplayShapeDeferredChild

            let nativeReplayKeyText renderKind key =
                let nodeText n = nativeNodeIdValue n |> string
                match key with
                | NativeApplyArg(node,index) -> FastRuntimeFormat.format "%s:EApply(%s).arg%d" [| box (renderKind()); box (nodeText node); box index |]
                | NativeFunctionBody node -> sprintf "%s:FunctionBody(%s)" (renderKind()) (nodeText node)
                | NativeRecordKey(name,node) -> FastRuntimeFormat.format "%s:RecordKey(%s,%s)" [| box (renderKind()); box name; box (nodeText node) |]
                | NativeParentHandoff node -> sprintf "%s:ParentHandoff(%s)" (renderKind()) (nodeText node)
                | NativeContinuationCell(owner,child) -> FastRuntimeFormat.format "%s:ContinuationCell(owner=%s,child=%s)" [| box (renderKind()); box (nodeText owner); box (nodeText child) |]
                | NativeDeferredChildCell(owner,child) -> FastRuntimeFormat.format "%s:DeferredChildCell(owner=%s,child=%s)" [| box (renderKind()); box (nodeText owner); box (nodeText child) |]

            type NativeErasedReplayKey =
                | NativeErasedTermKey of NativeReplayKey<NativeTermKind>
                | NativeErasedTyKey of NativeReplayKey<NativeTyKind>

            let nativeErasedReplayKeyText = function
                | NativeErasedTermKey key -> nativeReplayKeyText (fun () -> "term") key
                | NativeErasedTyKey key -> nativeReplayKeyText (fun () -> "ty") key

            type NativeSemanticShadowResult<'Kind> = {
                key: NativeReplayKey<'Kind>
                generation: int64
                evidence: CompilerIdentityKernel.ContentDigest
                authority: NativeHopacReadinessId
            }

            type NativeEvaluationObligation =
                | NativeTermObligation of NativeReplayKey<NativeTermKind> * IVar<Result<NativeSemanticShadowResult<NativeTermKind>,CompilerKernelV2.OperationalReasonId>>
                | NativeTyObligation of NativeReplayKey<NativeTyKind> * IVar<Result<NativeSemanticShadowResult<NativeTyKind>,CompilerKernelV2.OperationalReasonId>>

            let nativeEvaluationObligationKey = function
                | NativeTermObligation(key,_) -> NativeErasedTermKey key
                | NativeTyObligation(key,_) -> NativeErasedTyKey key

            // MIGRATION: assessment-mandated existential proof envelope.
            // The mailbox still has one erased shape, but each case pins the key kind, terminal
            // payload, and IVar return witness together.  This prevents the next cutover from
            // routing a term frontier through a ty payload by string accident while staying
            // shadow-only/no-fabrication.
            type NativeTerminalCommitClassId =
                | NativeTerminalCommitClassPending
                | NativeTerminalCommitClassCommitted
                | NativeTerminalCommitClassRejected

            let nativeTerminalCommitClassText = function
                | NativeTerminalCommitClassPending -> "pending"
                | NativeTerminalCommitClassCommitted -> "committed"
                | NativeTerminalCommitClassRejected -> "rejected"

            type NativeDispatchOutcomeId =
                | NativeDispatchOutcomePending
                | NativeDispatchOutcomeDispatched
                | NativeDispatchOutcomeSuppressed
                | NativeDispatchOutcomeFailed

            let nativeDispatchOutcomeText = function
                | NativeDispatchOutcomePending -> "pending"
                | NativeDispatchOutcomeDispatched -> "dispatched"
                | NativeDispatchOutcomeSuppressed -> "suppressed"
                | NativeDispatchOutcomeFailed -> "failed"

            type NativeTerminalPayloadWitness<'Kind> = {
                key: NativeReplayKey<'Kind>
                terminal: string
                ivar_edge: string
                terminal_commit_class_du: NativeTerminalCommitClassId
                dispatch_outcome_du: NativeDispatchOutcomeId
                mailbox_batch_summary: string
                legacy_observer_vetoed: bool
                raw_key_deprecated: bool
            }

            type NativePendingGraphExistentialDispatchProof =
                | NativeDispatchTermTerminal of NativeTerminalPayloadWitness<NativeTermKind> * IVar<string>
                | NativeDispatchTyTerminal of NativeTerminalPayloadWitness<NativeTyKind> * IVar<string>

            let nativeTerminalPayloadWitnessText renderKind (w: NativeTerminalPayloadWitness<'Kind>) =
                FastRuntimeFormat.format "key=%s|terminal=%s|edge=%s|class=%s|outcome=%s|batch=%s|legacy_vetoed=%b|raw_key_deprecated=%b" [| box (nativeReplayKeyText renderKind w.key); box w.terminal; box w.ivar_edge; box (nativeTerminalCommitClassText w.terminal_commit_class_du); box (nativeDispatchOutcomeText w.dispatch_outcome_du); box w.mailbox_batch_summary; box w.legacy_observer_vetoed; box w.raw_key_deprecated |]

            let nativePendingGraphExistentialDispatchProofText = function
                | NativeDispatchTermTerminal(w,_) -> nativeTerminalPayloadWitnessText (fun () -> "term") w
                | NativeDispatchTyTerminal(w,_) -> nativeTerminalPayloadWitnessText (fun () -> "ty") w

            type NativeMandatoryDispatchProofFieldId =
                | NativeProofPendingGraphDispatchOutcome
                | NativeProofHopacIvarResolutionEdge
                | NativeProofTerminalCommitClass
                | NativeProofPendingGraphMailboxBatchSummary
                | NativeProofLegacyObserverVetoed
                | NativeProofRawKeyDeprecated

            let nativeMandatoryDispatchProofFieldText = function
                | NativeProofPendingGraphDispatchOutcome -> "pending_graph_dispatch_outcome"
                | NativeProofHopacIvarResolutionEdge -> "hopac_ivar_resolution_edge"
                | NativeProofTerminalCommitClass -> "terminal_commit_class_du"
                | NativeProofPendingGraphMailboxBatchSummary -> "pending_graph_mailbox_batch_summary"
                | NativeProofLegacyObserverVetoed -> "legacy_observer_vetoed"
                | NativeProofRawKeyDeprecated -> "raw_key_deprecated"

            let nativeMandatoryDispatchProofFields =
                [ NativeProofPendingGraphDispatchOutcome
                  NativeProofHopacIvarResolutionEdge
                  NativeProofTerminalCommitClass
                  NativeProofPendingGraphMailboxBatchSummary
                  NativeProofLegacyObserverVetoed
                  NativeProofRawKeyDeprecated ]

            let nativeMandatoryDispatchProofFieldsSummary =
                nativeMandatoryDispatchProofFields
                |> List.map nativeMandatoryDispatchProofFieldText
                |> String.concat ","

            type NativeReplayDriverFn<'Kind> = NativeReplayKey<'Kind> -> Job<Result<NativeSemanticShadowResult<'Kind>,CompilerKernelV2.OperationalReasonId>>

            type NativeReplayDriverEnvelope<'Kind> = {
                driver: NativeReplayDriverKindId
                timeout_ms: int
                execute: NativeReplayDriverFn<'Kind>
                claim_boundary: string
            }

            type NativeObligationMailboxReceipt = {
                driver: NativeReplayDriverKindId
                key_shape: NativeReplayShapeId
                timeout_ms: int
                wait_primitive: NativeHopacWaitPrimitiveId
                worklist_policy: NativeHopacWorklistPolicyId
                primary_authority: NativeHopacReadinessId
                claim_boundary: string
            }

            let nativeObligationMailboxReceiptText (r: NativeObligationMailboxReceipt) =
                FastRuntimeFormat.format "driver=%s|shape=%s|timeout_ms=%d|wait=%s|worklist=%s|primary=%s|claim=%s" [| box (nativeReplayDriverKindText r.driver); box (nativeReplayShapeText r.key_shape); box r.timeout_ms; box (nativeHopacWaitPrimitiveText r.wait_primitive); box (nativeHopacWorklistPolicyText r.worklist_policy); box (nativeHopacReadinessText r.primary_authority); box r.claim_boundary |]

            let nativeObligationReceiptForTermKey key =
                { driver = NativeReplayDriverTerm
                  key_shape = nativeReplayKeyShape key
                  timeout_ms = 1500
                  wait_primitive = NativeWaitIvarRead
                  worklist_policy = NativeWorklistAwaitDependencyIvar
                  primary_authority = NativeHopacReadinessHybridBridge
                  claim_boundary = "shadow_only_no_writer_root_buildok" }

            let nativeObligationReceiptForTyKey key =
                { driver = NativeReplayDriverTy
                  key_shape = nativeReplayKeyShape key
                  timeout_ms = 1500
                  wait_primitive = NativeWaitIvarRead
                  worklist_policy = NativeWorklistAwaitDependencyIvar
                  primary_authority = NativeHopacReadinessHybridBridge
                  claim_boundary = "shadow_only_no_writer_root_buildok" }

            let nativeObligationMailboxSummary =
                [ nativeObligationReceiptForTermKey (NativeApplyArg(NativeNodeId 0,0))
                  nativeObligationReceiptForTyKey (NativeContinuationCell(NativeNodeId 0,NativeNodeId 1)) ]
                |> List.map nativeObligationMailboxReceiptText
                |> String.concat ";"

            // MIGRATION: accelerate the native Hopac cutover with the first typed
            // stack-fence obligation plan.  The runtime still runs shadow-only, but the
            // frontier exposed by 1553 now has a concrete destination: a ContinuationCell
            // key, an IVar wait, and an Alt timeout/hard-poison boundary instead of a
            // repeat-cap/probation loop.  This gives later rounds a single integration
            // point to wire without promoting BuildOk, writer, root, or semantic authority.
            type NativeAltOutcomeId =
                | NativeAltOutcomeAwaitingIvar
                | NativeAltOutcomeFulfilled
                | NativeAltOutcomeTimeoutPoison
                | NativeAltOutcomeLegacyFallbackBlocked

            let nativeAltOutcomeText = function
                | NativeAltOutcomeAwaitingIvar -> "awaiting_ivar"
                | NativeAltOutcomeFulfilled -> "fulfilled"
                | NativeAltOutcomeTimeoutPoison -> "timeout_poison"
                | NativeAltOutcomeLegacyFallbackBlocked -> "legacy_fallback_blocked"

            type NativeStackFenceObligationPlan = {
                key: NativeErasedReplayKey
                wait_primitive: NativeHopacWaitPrimitiveId
                timeout_policy: NativeHopacTimeoutPolicyId
                timeout_ms: int
                expected_outcome: NativeAltOutcomeId
                primary_authority: NativeHopacReadinessId
                claim_boundary: string
            }

            let nativeStackFenceObligationPlanText (p: NativeStackFenceObligationPlan) =
                FastRuntimeFormat.format "key=%s|wait=%s|timeout=%s/%dms|outcome=%s|primary=%s|claim=%s" [| box (nativeErasedReplayKeyText p.key); box (nativeHopacWaitPrimitiveText p.wait_primitive); box (nativeHopacTimeoutPolicyText p.timeout_policy); box p.timeout_ms; box (nativeAltOutcomeText p.expected_outcome); box (nativeHopacReadinessText p.primary_authority); box p.claim_boundary |]

            let stackFenceObligationPlan =
                { key = NativeErasedTermKey (NativeContinuationCell(NativeNodeId 0, NativeNodeId 1))
                  wait_primitive = NativeWaitAltChooseTimeout
                  timeout_policy = NativeTimeoutAltChooseHardPoison
                  timeout_ms = 1500
                  expected_outcome = NativeAltOutcomeTimeoutPoison
                  primary_authority = NativeHopacReadinessHybridBridge
                  claim_boundary = "shadow_only_stack_fence_no_writer_root_buildok" }

            let nativeStackFencePlanSummary =
                nativeStackFenceObligationPlanText stackFenceObligationPlan

            // MIGRATION: parent-preserved yield-thrash is now modeled as a native
            // Hopac Alt/IVar obligation boundary instead of another legacy probation
            // grace.  Historical runtime showed the stack-fence lane firing correctly, then
            // the tail moved to parent_replay_status_preserved_yield_thrash_hard_poison.
            // Keep this as a shadow-only plan: it names the poison authority and timeout
            // that later replaces Thread.Yield/repeat-cap churn, without fabricating
            // writer/root/BuildOk or a semantic value.
            type NativeParentReplayPoisonObligationPlan = {
                parent_key: NativeErasedReplayKey
                continuation_cell: NativeErasedReplayKey
                handoff_site: string
                timeout_policy: NativeHopacTimeoutPolicyId
                timeout_ms: int
                expected_outcome: NativeAltOutcomeId
                primary_authority: NativeHopacReadinessId
                claim_boundary: string
            }

            let nativeParentReplayPoisonObligationPlanText (p: NativeParentReplayPoisonObligationPlan) =
                FastRuntimeFormat.format "parent=%s|cell=%s|handoff=%s|timeout=%s/%dms|outcome=%s|primary=%s|claim=%s" [| box (nativeErasedReplayKeyText p.parent_key); box (nativeErasedReplayKeyText p.continuation_cell); box p.handoff_site; box (nativeHopacTimeoutPolicyText p.timeout_policy); box p.timeout_ms; box (nativeAltOutcomeText p.expected_outcome); box (nativeHopacReadinessText p.primary_authority); box p.claim_boundary |]

            let parentReplayPoisonObligationPlan =
                { parent_key = NativeErasedTermKey (NativeParentHandoff(NativeNodeId 0))
                  continuation_cell = NativeErasedTermKey (NativeContinuationCell(NativeNodeId 0, NativeNodeId 1))
                  handoff_site = "term_to_ty_or_parent"
                  timeout_policy = NativeTimeoutAltChooseHardPoison
                  timeout_ms = 1500
                  expected_outcome = NativeAltOutcomeTimeoutPoison
                  primary_authority = NativeHopacReadinessHybridBridge
                  claim_boundary = "shadow_only_parent_preserved_yield_thrash_no_writer_root_buildok" }

            let nativeParentReplayPoisonPlanSummary =
                nativeParentReplayPoisonObligationPlanText parentReplayPoisonObligationPlan

            // MIGRATION: materialized terminal outcome + typed PendingGraph shard.
            // The 1555 assessment identified the current missing bridge: shadow Alt pierces
            // semantic_stale_retarget, but the legacy pinned terminal observer receives only
            // an instruction string (required_next=materialize_...) instead of a typed terminal
            // payload.  These DUs make the fail-closed target explicit while remaining shadow-only.
            type NativeMaterializedTerminalOutcomeId =
                | NativeTerminalShadowTimeoutStaleRetargetPierce
                | NativeTerminalSemanticStaleRetargetShadowTimeoutPierce
                | NativeTerminalMissingPrefetchCycleBreakPoison
                | NativeTerminalCrossKindContinuationPendingReplay
                | NativeTerminalLegacyObserverRejected
                | NativeTerminalDynamicRecordKeyBridgeTailPierce
                | NativeTerminalSmallQueueParentReplayPoisonPierce
                | NativeTerminalStackFenceShadowTimeoutPierce
                | NativeTerminalIfUnknownReturnConditionTailPierce
                | NativeTerminalShadowTimeoutDeferredChildPierce
                | NativeTerminalParentContinuationCycleShadowTimeoutPierce
                | NativeTerminalQapVetoRejectedPendingGraphAuthority
                | NativeTerminalLocalizedDriverCutoverRequired
                | NativeTerminalSmallQueueActiveAuthorityDrainPierce

            let nativeMaterializedTerminalOutcomeText = function
                | NativeTerminalShadowTimeoutStaleRetargetPierce -> "ShadowTimeoutStaleRetargetPierce"
                | NativeTerminalSemanticStaleRetargetShadowTimeoutPierce -> "SemanticStaleRetargetShadowTimeoutPierce"
                | NativeTerminalMissingPrefetchCycleBreakPoison -> "MissingPrefetchCycleBreakPoison"
                | NativeTerminalCrossKindContinuationPendingReplay -> "CrossKindContinuationPendingReplay"
                | NativeTerminalLegacyObserverRejected -> "LegacyObserverRejected"
                | NativeTerminalDynamicRecordKeyBridgeTailPierce -> "DynamicRecordKeyBridgeTailPierce"
                | NativeTerminalSmallQueueParentReplayPoisonPierce -> "SmallQueueParentReplayPoisonPierce"
                | NativeTerminalStackFenceShadowTimeoutPierce -> "StackFenceShadowTimeoutPierce"
                | NativeTerminalIfUnknownReturnConditionTailPierce -> "IfUnknownReturnConditionTailPierce"
                | NativeTerminalShadowTimeoutDeferredChildPierce -> "ShadowTimeoutDeferredChildPierce"
                | NativeTerminalParentContinuationCycleShadowTimeoutPierce -> "ParentContinuationCycleShadowTimeoutPierce"
                | NativeTerminalQapVetoRejectedPendingGraphAuthority -> "QapVetoRejectedPendingGraphAuthority"
                | NativeTerminalLocalizedDriverCutoverRequired -> "LocalizedDriverCutoverRequired"
                | NativeTerminalSmallQueueActiveAuthorityDrainPierce -> "SmallQueueActiveAuthorityDrainPierce"

            type NativePendingGraphReadinessId =
                | NativePendingGraphReadyToSchedule
                | NativePendingGraphAwaitingIvarFill
                | NativePendingGraphPendingReplay
                | NativePendingGraphFailClosedTerminalMaterialized

            let nativePendingGraphReadinessText = function
                | NativePendingGraphReadyToSchedule -> "ready_to_schedule"
                | NativePendingGraphAwaitingIvarFill -> "awaiting_ivar_fill"
                | NativePendingGraphPendingReplay -> "pending_replay"
                | NativePendingGraphFailClosedTerminalMaterialized -> "fail_closed_terminal_materialized"

            type NativePendingGraphShardStateId =
                | NativeShardAwaitingChild of int
                | NativeShardAwaitingCrossKindContinuation
                | NativeShardTerminalPayloadMaterialized of NativeMaterializedTerminalOutcomeId
                | NativeShardLegacyQapVetoRejected of q: int * active: int * pending: int

            let nativePendingGraphShardStateText = function
                | NativeShardAwaitingChild nodeId -> sprintf "AwaitingChild(NodeId<TermKind:%d>)" nodeId
                | NativeShardAwaitingCrossKindContinuation -> "AwaitingCrossKindContinuation"
                | NativeShardTerminalPayloadMaterialized outcome -> sprintf "TerminalPayload(%s)" (nativeMaterializedTerminalOutcomeText outcome)
                | NativeShardLegacyQapVetoRejected(q,active,pending) -> FastRuntimeFormat.format "LegacyQapVetoRejected(q=%d,a=%d,p=%d)" [| box q; box active; box pending |]

            type NativePendingGraphStatusId =
                | NativePendingSemanticStaleRetarget
                | NativePendingSemanticParentContinuationCycleDeferred
                | NativePendingDynamicRecordKeyBridgeTail
                | NativePendingBlockedRepeatCapStackFenceYield
                | NativePendingSemanticParentReplayCycleBreakPoisoned

            let nativePendingGraphStatusText = function
                | NativePendingSemanticStaleRetarget -> "semantic_stale_retarget"
                | NativePendingSemanticParentContinuationCycleDeferred -> "semantic_parent_continuation_cycle_deferred"
                | NativePendingDynamicRecordKeyBridgeTail -> "dynamic_record_key_bridge_tail"
                | NativePendingBlockedRepeatCapStackFenceYield -> "blocked_repeat_cap_stack_fence_yield"
                | NativePendingSemanticParentReplayCycleBreakPoisoned -> "semantic_parent_replay_cycle_break_poisoned"

            type NativePendingGraphNode =
                | NativePendingGraphTerm of key: NativeReplayKey<NativeTermKind> * status: NativePendingGraphStatusId * readiness: NativePendingGraphReadinessId * children: NativePendingGraphNode list
                | NativePendingGraphTy of key: NativeReplayKey<NativeTyKind> * status: NativePendingGraphStatusId * readiness: NativePendingGraphReadinessId * children: NativePendingGraphNode list

            let nativePendingGraphNodeKeyText = function
                | NativePendingGraphTerm(key,_,_,_) -> nativeReplayKeyText (fun () -> "term") key
                | NativePendingGraphTy(key,_,_,_) -> nativeReplayKeyText (fun () -> "ty") key

            let nativePendingGraphNodeReadinessText = function
                | NativePendingGraphTerm(_,_,readiness,_) -> nativePendingGraphReadinessText readiness
                | NativePendingGraphTy(_,_,readiness,_) -> nativePendingGraphReadinessText readiness

            type NativePierceTargetId =
                | NativePierceSemanticRootCompleteStaleRetarget
                | NativePierceParentContinuationCycleDeferred
