                | NativePierceDynamicRecordKeyBridgeTail -> "dynamic_record_key_bridge_tail_weak_pending_active_root"
                | NativePierceSmallQueueParentReplayPoison -> "small_queue_parent_replay_poison_cross_kind_yield_thrash"
                | NativePierceStackFenceShadowTimeout -> "sidecar_shadow_alt_timeout_pierced_stack_fence"
                | NativePierceDeferredChildCell -> "semantic_parent_continuation_cycle_deferred_child_cell"
                | NativePierceIfUnknownReturnConditionTail -> "if_unknown_return_condition_p0_tiny_live_tail"

            type NativeExpectedTerminalReturnId =
                | NativeReturnSemanticStaleRetarget
                | NativeReturnParentContinuationCycleDeferred
                | NativeReturnDynamicRecordKeyBridgeTail
                | NativeReturnSmallQueueParentReplayPoison
                | NativeReturnStackFenceShadowTimeout
                | NativeReturnDeferredChild
                | NativeReturnIfUnknownConditionTail

            let nativeExpectedTerminalReturnText = function
                | NativeReturnSemanticStaleRetarget -> "EvalWorklistTerminal(SemanticStaleRetargetShadowTimeoutPierce)"
                | NativeReturnParentContinuationCycleDeferred -> "EvalWorklistTerminal(ParentContinuationCycleDeferredPierce)"
                | NativeReturnDynamicRecordKeyBridgeTail -> "EvalWorklistTerminal(DynamicRecordKeyBridgeTailPierce)"
                | NativeReturnSmallQueueParentReplayPoison -> "EvalWorklistTerminal(SmallQueueParentReplayPoisonPierce)"
                | NativeReturnStackFenceShadowTimeout -> "EvalWorklistTerminal(StackFenceShadowTimeoutPierce)"
                | NativeReturnDeferredChild -> "EvalWorklistTerminal(ShadowTimeoutDeferredChild)"
                | NativeReturnIfUnknownConditionTail -> "EvalWorklistTerminal(IfUnknownReturnConditionTailPierce)"

            type NativeMaterializedClaimBoundaryId =
                | NativeClaimShadowTimeoutMaterialized
                | NativeClaimParentContinuationCycleMaterialized
                | NativeClaimDynamicRecordKeyBridgeMaterialized
                | NativeClaimSmallQueueParentReplayPoisonMaterialized
                | NativeClaimStackFenceMaterialized
                | NativeClaimDeferredChildMaterialized
                | NativeClaimIfUnknownReturnMaterialized

            let nativeMaterializedClaimBoundaryText = function
                | NativeClaimShadowTimeoutMaterialized -> "shadow_timeout_materialized_no_writer_root_buildok"
                | NativeClaimParentContinuationCycleMaterialized -> "parent_continuation_cycle_materialized_no_writer_root_buildok"
                | NativeClaimDynamicRecordKeyBridgeMaterialized -> "dynamic_record_key_bridge_payload_materialized_no_writer_root_buildok"
                | NativeClaimSmallQueueParentReplayPoisonMaterialized -> "small_queue_parent_replay_poison_payload_materialized_no_writer_root_buildok"
                | NativeClaimStackFenceMaterialized -> "stack_fence_payload_materialized_no_writer_root_buildok"
                | NativeClaimDeferredChildMaterialized -> "deferred_child_cell_payload_materialized_rejects_q16_no_writer_root_buildok"
                | NativeClaimIfUnknownReturnMaterialized -> "if_unknown_return_payload_materialized_no_writer_root_buildok"

            type NativeMaterializedTerminalPayload = {
                replay_key: NativeErasedReplayKey
                terminal_outcome: NativeMaterializedTerminalOutcomeId
                pierce_target: NativePierceTargetId
                continuation_readiness: NativePendingGraphReadinessId
                fail_closed: bool
                expected_return: NativeExpectedTerminalReturnId
                claim_boundary: NativeMaterializedClaimBoundaryId
            }

            let nativeMaterializedTerminalPayloadText (p: NativeMaterializedTerminalPayload) =
                FastRuntimeFormat.format "key=%s|terminal=%s|target=%s|continuation=%s|fail_closed=%b|return=%s|claim=%s" [| box (nativeErasedReplayKeyText p.replay_key); box (nativeMaterializedTerminalOutcomeText p.terminal_outcome); box (nativePierceTargetText p.pierce_target); box (nativePendingGraphReadinessText p.continuation_readiness); box p.fail_closed; box (nativeExpectedTerminalReturnText p.expected_return); box (nativeMaterializedClaimBoundaryText p.claim_boundary) |]

            type NativeSemanticStaleRetargetMaterializationPlan = {
                hot_node: NativePendingGraphNode
                payload: NativeMaterializedTerminalPayload
                timeout_policy: NativeHopacTimeoutPolicyId
                timeout_ms: int
                alt_outcome: NativeAltOutcomeId
                primary_authority: NativeHopacReadinessId
            }

            let nativeSemanticStaleRetargetMaterializationPlanText (p: NativeSemanticStaleRetargetMaterializationPlan) =
                FastRuntimeFormat.format "node=%s|readiness=%s|payload=%s|timeout=%s/%dms|alt=%s|primary=%s" [| box (nativePendingGraphNodeKeyText p.hot_node); box (nativePendingGraphNodeReadinessText p.hot_node); box (nativeMaterializedTerminalPayloadText p.payload); box (nativeHopacTimeoutPolicyText p.timeout_policy); box p.timeout_ms; box (nativeAltOutcomeText p.alt_outcome); box (nativeHopacReadinessText p.primary_authority) |]

            let materializeTypedSemanticStaleRetargetOutcome key : NativeMaterializedTerminalPayload =
                { replay_key = key
                  terminal_outcome = NativeTerminalSemanticStaleRetargetShadowTimeoutPierce
                  pierce_target = NativePierceSemanticRootCompleteStaleRetarget
                  continuation_readiness = NativePendingGraphPendingReplay
                  fail_closed = true
                  expected_return = NativeReturnSemanticStaleRetarget
                  claim_boundary = NativeClaimShadowTimeoutMaterialized }

            let semanticStaleRetargetMaterializationPlan =
                let continuation = NativeContinuationCell(NativeNodeId 0, NativeNodeId 1)
                let erased = NativeErasedTyKey continuation
                { hot_node = NativePendingGraphTy(continuation, NativePendingSemanticStaleRetarget, NativePendingGraphPendingReplay, [])
                  payload = materializeTypedSemanticStaleRetargetOutcome erased
                  timeout_policy = NativeTimeoutAltChooseHardPoison
                  timeout_ms = 1500
                  alt_outcome = NativeAltOutcomeTimeoutPoison
                  primary_authority = NativeHopacReadinessHybridBridge }

            let semanticStaleRetargetMaterializationSummary =
                nativeSemanticStaleRetargetMaterializationPlanText semanticStaleRetargetMaterializationPlan

            // MIGRATION: assessment debt burn-down.  MIGRATION created the typed payload;
            // this slice makes the handoff decision itself typed so the next runtime can
            // distinguish "terminal materialized, fail closed" from "legacy observer froze again".
            // The values remain shadow/burn-in only and intentionally carry no writer/root/BuildOk.
            type NativeTerminalMaterializationDecisionId =
                | NativeTerminalMaterializeAndFailClosed
                | NativeTerminalSchedulePendingReplayDrain
                | NativeTerminalRequeueCrossKindContinuation
                | NativeTerminalRejectLegacyPinnedObserver
                | NativeTerminalMissingPayloadDebt

            let nativeTerminalMaterializationDecisionText = function
                | NativeTerminalMaterializeAndFailClosed -> "materialize_and_fail_closed"
                | NativeTerminalSchedulePendingReplayDrain -> "schedule_pending_replay_drain"
                | NativeTerminalRequeueCrossKindContinuation -> "requeue_cross_kind_continuation"
                | NativeTerminalRejectLegacyPinnedObserver -> "reject_legacy_pinned_observer"
                | NativeTerminalMissingPayloadDebt -> "missing_payload_debt"

            type NativeObligationLivenessId =
                | NativeObligationNoEvidence
                | NativeObligationLegacyPhysicalOnly
                | NativeObligationIvarAwaitingFill
                | NativeObligationAltTimeoutFired
                | NativeObligationTerminalMaterialized

            let nativeObligationLivenessText = function
