            let materializeTypedParentContinuationCycleOutcome key : NativeMaterializedTerminalPayload =
                { replay_key = key
                  terminal_outcome = NativeTerminalParentContinuationCycleShadowTimeoutPierce
                  pierce_target = NativePierceParentContinuationCycleDeferred
                  continuation_readiness = NativePendingGraphPendingReplay
                  fail_closed = true
                  expected_return = NativeReturnParentContinuationCycleDeferred
                  claim_boundary = NativeClaimParentContinuationCycleMaterialized }

            let parentContinuationCycleMaterializationPlan =
                let continuation =
                    NativeContinuationCell(
                        nativeSyntheticNodeId NativeSyntheticParentContinuationCycleOwner,
                        nativeSyntheticNodeId NativeSyntheticParentContinuationCycleChild)
                let erased = NativeErasedTermKey continuation
                let payload = materializeTypedParentContinuationCycleOutcome erased
                { hot_graph = NativePendingGraphTerm(continuation, NativePendingSemanticParentContinuationCycleDeferred, NativePendingGraphPendingReplay, [])
                  typed_key = nativeTypedReplayKeyProjectionFromErased erased
                  payload = payload
                  terminal_decision = NativeTerminalMaterializeAndFailClosed
                  liveness = NativeObligationTerminalMaterialized
                  localized_driver_stage = "continuation_cell_job_envelope_shadow_bound"
