            let nativeDynamicRecordKeyBridgeMaterializationPlanText p =
                FastRuntimeFormat.format "typed_key=%s|payload=%s|decision=%s|liveness=%s|driver=%s|mailbox=%s|alt=%dms|legacy_wait_veto=%b|strength=%s|claim=%s" [| box (nativeTypedReplayKeyProjectionText p.typed_key); box (nativeMaterializedTerminalPayloadText p.payload); box (nativeTerminalMaterializationDecisionText p.terminal_decision); box (nativeObligationLivenessText p.liveness); box p.localized_driver_stage; box p.mailbox_obligation; box p.alt_timeout_ms; box p.legacy_wait_veto; box p.bridge_tail_strength; box p.claim_boundary |]

            let materializeTypedDynamicRecordKeyBridgeOutcome key : NativeMaterializedTerminalPayload =
                { replay_key = key
                  terminal_outcome = NativeTerminalDynamicRecordKeyBridgeTailPierce
                  pierce_target = NativePierceDynamicRecordKeyBridgeTail
                  continuation_readiness = NativePendingGraphPendingReplay
                  fail_closed = true
                  expected_return = NativeReturnDynamicRecordKeyBridgeTail
                  claim_boundary = NativeClaimDynamicRecordKeyBridgeMaterialized }

            let dynamicRecordKeyBridgeMaterializationPlan =
                let bridgeKey =
                    NativeRecordKey(
                        "dynamic_record_key_bridge_tail",
                        nativeSyntheticNodeId NativeSyntheticDynamicRecordKeyBridgeTarget)
                let erased = NativeErasedTermKey bridgeKey
