                  typed_key = nativeTypedReplayKeyProjectionFromErased erased
                  payload = materializeTypedDynamicRecordKeyBridgeOutcome erased
                  terminal_decision = NativeTerminalMaterializeAndFailClosed
                  liveness = NativeObligationTerminalMaterialized
                  localized_driver_stage = "dynamic_record_key_bridge_job_envelope_shadow_bound"
                  mailbox_obligation = "EvaluateTerm(RecordKeyBridge,IVar<DynamicRecordKeyBridgeTailPierce>)"
                  alt_timeout_ms = 1500
                  legacy_wait_veto = true
                  bridge_tail_strength = "weak_pending_active_root"
                  claim_boundary = "shadow_only_dynamic_record_key_bridge_payload_no_primary_hopac_no_buildok" }

            let dynamicRecordKeyBridgeMaterializationSummary =
                nativeDynamicRecordKeyBridgeMaterializationPlanText dynamicRecordKeyBridgeMaterializationPlan

            // MIGRATION: small-queue parent-replay poison materialization burn-in.
            // The 1559 runtime reached the next honest frontier: q/a/p=3/1/2 stayed
            // physically live while the hot ty TFun continuation was only ping-ponging
            // through cross_kind_yield_thrash:hard_poison_obligation_cap.  The legacy
            // small-queue authority guard treated that as material liveness because root
            // receipts were fresh, but root_yield_age kept growing past 30s.  Model it as
            // a typed ty continuation-cell obligation with an Alt timeout and a fail-closed
            // terminal payload, rather than another drain_sibling_tail observer loop.
            type NativeSmallQueueParentReplayPoisonMaterializationPlan = {
                hot_graph: NativePendingGraphNode
                typed_key: NativeTypedReplayKeyProjection
                payload: NativeMaterializedTerminalPayload
                terminal_decision: NativeTerminalMaterializationDecisionId
                liveness: NativeObligationLivenessId
                localized_driver_stage: string
                mailbox_obligation: string
                alt_timeout_ms: int
                q_live: int
                a_live: int
                p_live: int
                root_yield_age_ms: int
                legacy_live_tail_veto: bool
                claim_boundary: string
            }

            let nativeSmallQueueParentReplayPoisonMaterializationPlanText p =
                FastRuntimeFormat.format "typed_key=%s|payload=%s|decision=%s|liveness=%s|driver=%s|mailbox=%s|alt=%dms|qap=%d/%d/%d|root_yield_age_ms=%d|legacy_live_tail_veto=%b|claim=%s" [| box (nativeTypedReplayKeyProjectionText p.typed_key); box (nativeMaterializedTerminalPayloadText p.payload); box (nativeTerminalMaterializationDecisionText p.terminal_decision); box (nativeObligationLivenessText p.liveness); box p.localized_driver_stage; box p.mailbox_obligation; box p.alt_timeout_ms; box p.q_live; box p.a_live; box p.p_live; box p.root_yield_age_ms; box p.legacy_live_tail_veto; box p.claim_boundary |]

            let materializeTypedSmallQueueParentReplayPoisonOutcome key : NativeMaterializedTerminalPayload =
