        type PendingGraphProofTuple = {
            witness: TerminalWitnessEnvelope
            commitClass: TerminalCommitClassId
            mailboxBatch: PendingGraphMailboxBatchSummaryId
            fillStrategy: ParentContinuationFillStrategyId
            qapAuthority: QapAuthorityId
            legacyVeto: LegacyVetoQuarantineId
            rawKeyDeprecated: bool
            shadowTimeoutMs: int
            }

        let pendingGraphProofTupleComplete tuple =
            tuple.rawKeyDeprecated && tuple.shadowTimeoutMs = 0

        // MIGRATION: assessment asked for tuple expansion and native Promise visibility.
        // These renderers make the tuple's required slots explicit before HUD/JSONL,
        // keeping repeat caps and legacy live-tail as observers after a witnessed IVar exists.
        type NativeHopacPromiseStateId =
            | NativePromisePending of NativeHopacIvarRegistryId
            | NativePromiseMaterialized of NativeHopacIvarRegistryId
            | NativePromiseWitnessed of NativeHopacIvarRegistryId * TerminalWitnessKindId
            | NativePromiseFilled of NativeHopacIvarRegistryId * ParentContinuationFillStrategyId
            | NativePromiseLegacyObserverQuarantined of NativeHopacIvarRegistryId * LegacyVetoQuarantineId

        let nativeHopacPromiseStateText = function
            | NativePromisePending ivar -> "Pending(" + nativeHopacIvarRegistryText ivar + ")"
            | NativePromiseMaterialized ivar -> "Materialized(" + nativeHopacIvarRegistryText ivar + ")"
            | NativePromiseWitnessed (ivar,witness) -> "Witnessed(" + nativeHopacIvarRegistryText ivar + "," + terminalWitnessKindText witness + ")"
            | NativePromiseFilled (ivar,fill) -> "Filled(" + nativeHopacIvarRegistryText ivar + "," + parentContinuationFillStrategyText fill + ")"
            | NativePromiseLegacyObserverQuarantined (ivar,legacy) -> "LegacyObserverQuarantined(" + nativeHopacIvarRegistryText ivar + "," + legacyVetoQuarantineText legacy + ")"

        type HotRowRecyclePolicyId =
            | RecycleEmitFullThenCompactTerminalTuple
            | RecycleCompactSemanticStaleRetarget
            | RecycleCompactParentReplayCycleBreakPoison
            | RecycleCompactCrossKindYieldThrashHardPoison
            | RecycleCompactHardPoisonObligationCap
            | RecycleCompactParentReplayStatusPreservedCacheHandoff
            | RecycleCompactCooperativeReplayNativeBind
            | RecycleCompactJoinWaitAfterWitness
            | RecycleCompactMetronomeAfterAuthority
            | RecycleCompactNoRootBudgetParentReplay
            | RecycleKeepFullUntilWitness

        let hotRowRecyclePolicyText = function
            | RecycleEmitFullThenCompactTerminalTuple -> "emit_full_once_then_compact_terminal_tuple"
            | RecycleCompactSemanticStaleRetarget -> "emit_once_then_compact_semantic_stale_retarget"
            | RecycleCompactParentReplayCycleBreakPoison -> "emit_once_then_compact_parent_replay_cycle_break_poison"
            | RecycleCompactCrossKindYieldThrashHardPoison -> "emit_once_then_compact_cross_kind_yield_thrash_hard_poison"
            | RecycleCompactHardPoisonObligationCap -> "emit_once_then_compact_hard_poison_obligation_cap"
            | RecycleCompactParentReplayStatusPreservedCacheHandoff -> "emit_once_then_compact_parent_replay_status_preserved_cache_handoff"
            | RecycleCompactCooperativeReplayNativeBind -> "emit_once_then_compact_cooperative_replay_native_bind"
            | RecycleCompactJoinWaitAfterWitness -> "emit_once_then_compact_join_wait_after_witness"
            | RecycleCompactMetronomeAfterAuthority -> "emit_once_then_compact_metronome_authority"
            | RecycleCompactNoRootBudgetParentReplay -> "emit_once_then_compact_no_root_budget_parent_replay"
            | RecycleKeepFullUntilWitness -> "keep_full_until_witness_materialized"

        type ProofTupleMatrixStatus = {
            witnessOk: bool
            ivarRegistryOk: bool
            cycleRootOk: bool
            commitClassOk: bool
            fillOk: bool
            promiseState: NativeHopacPromiseStateId
            recyclePolicy: HotRowRecyclePolicyId
            }

        let proofTupleMatrixStatusFor tuple =
            let recyclePolicy =
                match tuple.witness.kind with
                | WitnessSemanticStaleRetargetProof -> RecycleCompactSemanticStaleRetarget
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof -> RecycleCompactParentReplayCycleBreakPoison
                | WitnessCrossKindYieldThrashHardPoisonProof -> RecycleCompactCrossKindYieldThrashHardPoison
                | WitnessHardPoisonObligationCapProof -> RecycleCompactHardPoisonObligationCap
                | WitnessParentReplayStatusPreservedCacheHandoffProof -> RecycleCompactParentReplayStatusPreservedCacheHandoff
                | WitnessCooperativeReplayNativeBindProof -> RecycleCompactCooperativeReplayNativeBind
                | WitnessJoinWaitDriverPromiseProof -> RecycleCompactJoinWaitAfterWitness
                | WitnessMetronomeTerminalAuthorityProof -> RecycleCompactMetronomeAfterAuthority
                | WitnessNoRootBudgetParentReplayImmediateFillProof -> RecycleCompactNoRootBudgetParentReplay
                | _ -> RecycleEmitFullThenCompactTerminalTuple
            { witnessOk = true
              ivarRegistryOk = true
              cycleRootOk = not (System.String.IsNullOrWhiteSpace tuple.witness.cycleRootOrigin)
              commitClassOk = true
              fillOk = true
              promiseState =
                if pendingGraphProofTupleComplete tuple then NativePromiseFilled (tuple.witness.ivar, tuple.fillStrategy)
                else NativePromiseWitnessed (tuple.witness.ivar, tuple.witness.kind)
              recyclePolicy = recyclePolicy }

        let proofTupleMatrixText matrix =
            FastRuntimeFormat.format "[Witness:%s]|[IVar Reg:%s]|[Cycle Root:%s]|[Commit Class:%s]|[Fill:%s]|promise=%s|recycle=%s" [| box (if matrix.witnessOk then "OK" else "Missing"); box (if matrix.ivarRegistryOk then "OK" else "Missing"); box (if matrix.cycleRootOk then "OK" else "Missing"); box (if matrix.commitClassOk then "OK" else "Missing"); box (if matrix.fillOk then "OK" else "Missing"); box (nativeHopacPromiseStateText matrix.promiseState); box (hotRowRecyclePolicyText matrix.recyclePolicy) |]

        let proofTupleCriticalPathText tuple =
            FastRuntimeFormat.format "payload_witness=%s -> ivar=%s -> fill=%s -> legacy=%s -> qap=observer" [| box (terminalWitnessKindText tuple.witness.kind); box (nativeHopacIvarRegistryText tuple.witness.ivar); box (parentContinuationFillStrategyText tuple.fillStrategy); box (legacyVetoQuarantineText tuple.legacyVeto) |]

        let pendingGraphProofTupleText tuple =
            FastRuntimeFormat.format "witness=%s|commit=%s|mailbox=%s|fill=%s|qap=%s|legacy=%s|raw_key_deprecated=%b|timeout_ms=%d|complete=%b" [| box (terminalWitnessEnvelopeText tuple.witness); box (terminalCommitClassText tuple.commitClass); box (pendingGraphMailboxBatchSummaryText tuple.mailboxBatch); box (parentContinuationFillStrategyText tuple.fillStrategy); box (qapAuthorityText tuple.qapAuthority); box (legacyVetoQuarantineText tuple.legacyVeto); box tuple.rawKeyDeprecated; box tuple.shadowTimeoutMs; box (pendingGraphProofTupleComplete tuple) |]

        // The structural graph is shared by many re-entry nodes.  Node-local
        // payload, site and visit counters stay on compact reference rows; the
        // expensive graph proof is materialized once per structural class and
        // build generation.
        let private pendingGraphProofTupleSnapshotLedger =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,byte>()

        let pendingGraphProofTupleStructuralSnapshotText tuple =
            FastRuntimeFormat.format "witness_kind=%s|ivar=%s|commit=%s|mailbox=%s|fill=%s|qap=%s|legacy=%s|raw_key_deprecated=%b|timeout_ms=%d|complete=%b" [| box (terminalWitnessKindText tuple.witness.kind); box (nativeHopacIvarRegistryText tuple.witness.ivar); box (terminalCommitClassText tuple.commitClass); box (pendingGraphMailboxBatchSummaryText tuple.mailboxBatch); box (parentContinuationFillStrategyText tuple.fillStrategy); box (qapAuthorityText tuple.qapAuthority); box (legacyVetoQuarantineText tuple.legacyVeto); box tuple.rawKeyDeprecated; box tuple.shadowTimeoutMs; box (pendingGraphProofTupleComplete tuple) |]

        let private pendingGraphProofTupleSnapshotDigest tuple =
            CompilerIdentityKernel.ContentDigest.ofText
                "pending-graph-proof-tuple-structural-snapshot"
                (pendingGraphProofTupleStructuralSnapshotText tuple)

        let pendingGraphProofTupleSnapshotRef tuple =
            pendingGraphProofTupleSnapshotDigest tuple
            |> CompilerIdentityKernel.ContentDigest.text

        let tryCommitPendingGraphProofTupleSnapshot tuple =
            let snapshotDigest = pendingGraphProofTupleSnapshotDigest tuple
            let snapshotRef = CompilerIdentityKernel.ContentDigest.text snapshotDigest
            snapshotRef, pendingGraphProofTupleSnapshotLedger.TryAdd(snapshotDigest, 0uy)

        let resetPendingGraphProofTupleSnapshots () =
            pendingGraphProofTupleSnapshotLedger.Clear()

        // MIGRATION: close the authority gap between tuple existence and action.
        // The decision/projection pair is the typed source for JSON/HUD compact rows;
        // string rendering happens only at the boundary.
        type ProofTupleAuthorityDecisionId =
            | ProofTupleDecisionFillIvarImmediately of NativeHopacIvarRegistryId * ParentContinuationFillStrategyId
            | ProofTupleDecisionBindNativePromise of NativeHopacIvarRegistryId
            | ProofTupleDecisionQuarantineHudFrontier of LegacyVetoQuarantineId
            | ProofTupleDecisionCompactObserverPolling of HotRowRecyclePolicyId

        let proofTupleAuthorityDecisionText = function
            | ProofTupleDecisionFillIvarImmediately (ivar,fill) -> "fill_ivar_immediately(" + nativeHopacIvarRegistryText ivar + "," + parentContinuationFillStrategyText fill + ")"
            | ProofTupleDecisionBindNativePromise ivar -> "bind_native_promise_before_hud_frontier(" + nativeHopacIvarRegistryText ivar + ")"
            | ProofTupleDecisionQuarantineHudFrontier legacy -> "quarantine_eval_worklist_hud_frontier(" + legacyVetoQuarantineText legacy + ")"
            | ProofTupleDecisionCompactObserverPolling recycle -> "compact_observer_polling(" + hotRowRecyclePolicyText recycle + ")"

        // MIGRATION: authoritative ordering is now a DU projection.  It makes
        // the assessment invariant explicit: typed proof and native callback
        // outrank HUD frontier, q/a/p, repeat caps and legacy live-tail polling.
        type ProofTupleAuthorityStackId =
            | ProofTupleAuthorityStackMissingWitness
            | ProofTupleAuthorityStackTypedProofNativeCallback
            | ProofTupleAuthorityStackTypedProofRecycleThenCallback
            | ProofTupleAuthorityStackLegacyObserverQuarantined
            | ProofTupleAuthorityStackUnknown of CompilerKernelV2.OperationalReasonId

        let proofTupleAuthorityStackText = function
            | ProofTupleAuthorityStackMissingWitness -> "missing_witness_then_bind_native_promise"
            | ProofTupleAuthorityStackTypedProofNativeCallback -> "typed_proof>native_callback>compact_recycle>legacy_observer"
            | ProofTupleAuthorityStackTypedProofRecycleThenCallback -> "typed_proof>compact_hot_row>native_callback>legacy_observer"
            | ProofTupleAuthorityStackLegacyObserverQuarantined -> "legacy_observer_quarantined_after_proof_tuple"
            | ProofTupleAuthorityStackUnknown reasonId -> CompilerKernelV2.OperationalReasonIdOps.text reasonId

        type NativeCallbackCommitmentId =
            | NativeCallbackCommitmentIvarFill of NativeHopacIvarRegistryId * ParentContinuationFillStrategyId
            | NativeCallbackCommitmentPromiseBind of NativeHopacIvarRegistryId
            | NativeCallbackCommitmentCyclePoisonPromise of TerminalWitnessKindId
            | NativeCallbackCommitmentHudFrontierQuarantine

        let nativeCallbackCommitmentText = function
            | NativeCallbackCommitmentIvarFill (ivar,fill) -> "commit:IVar.fill(" + nativeHopacIvarRegistryText ivar + "," + parentContinuationFillStrategyText fill + ")"
            | NativeCallbackCommitmentPromiseBind ivar -> "commit:Job.bind(Promise(" + nativeHopacIvarRegistryText ivar + "))"
            | NativeCallbackCommitmentCyclePoisonPromise witness -> "commit:CyclePoisonPromise(" + terminalWitnessKindText witness + ")"
            | NativeCallbackCommitmentHudFrontierQuarantine -> "commit:quarantine_eval_worklist_hud_terminal_frontier"

        type CompactObserverEnvelopeId =
            | CompactObserverEnvelopeFullOnceThenKeyedDelta
            | CompactObserverEnvelopeProofTupleOnly
            | CompactObserverEnvelopeJoinWaitKeyPayloadIvarFill
            | CompactObserverEnvelopeCacheHandoffPayloadPromiseNext
            | CompactObserverEnvelopeHardPoisonPayloadWitnessIvar

        let compactObserverEnvelopeText = function
            | CompactObserverEnvelopeFullOnceThenKeyedDelta -> "emit_full_once_then_keyed_delta"
            | CompactObserverEnvelopeProofTupleOnly -> "payload,witness,ivar,fill,authority,next"
            | CompactObserverEnvelopeJoinWaitKeyPayloadIvarFill -> "join_wait:key,payload,witness,ivar,fill,next"
            | CompactObserverEnvelopeCacheHandoffPayloadPromiseNext -> "cache_handoff:payload,promise,callback,next"
            | CompactObserverEnvelopeHardPoisonPayloadWitnessIvar -> "hard_poison:payload,witness,ivar,cycle_root,next"

        // MIGRATION: hot rows that still surface through backup ticks, pin snapshots
        // or parent-poison live-tail override are explicitly projected from the proof
        // tuple before JSON rendering.  This keeps the old scheduler fields as
        // receipts instead of authority.
        type HotRowAuthorityProjectionId =
            | HotRowProjectionNativeBackupTick of HotRowRecyclePolicyId
            | HotRowProjectionTerminalFrontierPin of TerminalWitnessKindId
            | HotRowProjectionParentPoisonLiveTailOverride of TerminalWitnessKindId
            | HotRowProjectionReplayDriverSurface of TerminalWitnessKindId
            | HotRowProjectionUnknown of CompilerKernelV2.OperationalReasonId

        let hotRowAuthorityProjectionText = function
            | HotRowProjectionNativeBackupTick recycle -> "native_backup_tick_suppressed_by_proof_tuple(" + hotRowRecyclePolicyText recycle + ")"
            | HotRowProjectionTerminalFrontierPin witness -> "terminal_frontier_pin_observes_proof_tuple(" + terminalWitnessKindText witness + ")"
            | HotRowProjectionParentPoisonLiveTailOverride witness -> "parent_poison_live_tail_override_bypassed_by_proof_tuple(" + terminalWitnessKindText witness + ")"
            | HotRowProjectionReplayDriverSurface witness -> "replay_driver_surface_observes_proof_tuple(" + terminalWitnessKindText witness + ")"
            | HotRowProjectionUnknown reasonId -> CompilerKernelV2.OperationalReasonIdOps.text reasonId


        // MIGRATION: a materialized proof must make the HUD frontier topologically unreachable.
        // These DUs render the final cutover contract: inline IVar.fill / Job.bind wins before
        // any pinned-terminal observer, live-tail veto, no-root budget or repeat-cap path can run.
        type NativeInlineCallbackCutoverId =
            | NativeInlineCallbackCutoverMissingWitness
            | NativeInlineCallbackCutoverIvarFill of NativeHopacIvarRegistryId * ParentContinuationFillStrategyId
            | NativeInlineCallbackCutoverJobBind of NativeHopacIvarRegistryId
            | NativeInlineCallbackCutoverCyclePoison of TerminalWitnessKindId
            | NativeInlineCallbackCutoverHudFrontierSevered of LegacyVetoQuarantineId

        let nativeInlineCallbackCutoverText = function
            | NativeInlineCallbackCutoverMissingWitness -> "missing_witness_no_inline_callback"
            | NativeInlineCallbackCutoverIvarFill (ivar,fill) -> "inline:IVar.fill(" + nativeHopacIvarRegistryText ivar + "," + parentContinuationFillStrategyText fill + ")"
            | NativeInlineCallbackCutoverJobBind ivar -> "inline:Job.bind(Promise(" + nativeHopacIvarRegistryText ivar + "))"
            | NativeInlineCallbackCutoverCyclePoison witness -> "inline:CyclePoisonPromise(" + terminalWitnessKindText witness + ")"
            | NativeInlineCallbackCutoverHudFrontierSevered legacy -> "sever_eval_worklist_hud_terminal_frontier(" + legacyVetoQuarantineText legacy + ")"

        type LegacyObserverTopologyId =
            | LegacyObserverTopologyReachableBeforeWitness
            | LegacyObserverTopologySeveredByInlineIvarFill
            | LegacyObserverTopologySeveredByNativePromiseBind
            | LegacyObserverTopologySeveredByCyclePoison

        let legacyObserverTopologyText = function
            | LegacyObserverTopologyReachableBeforeWitness -> "legacy_observer_reachable_until_witness"
            | LegacyObserverTopologySeveredByInlineIvarFill -> "legacy_observer_topologically_inaccessible_after_inline_ivar_fill"
            | LegacyObserverTopologySeveredByNativePromiseBind -> "legacy_observer_topologically_inaccessible_after_job_bind"
            | LegacyObserverTopologySeveredByCyclePoison -> "legacy_observer_topologically_inaccessible_after_cycle_poison"

        type WitnessRoutingLatticeId =
            | WitnessRoutingLatticeUnresolved
            | WitnessRoutingLatticeImmediateFill of TerminalWitnessKindId * NativeHopacIvarRegistryId
            | WitnessRoutingLatticePromiseBind of TerminalWitnessKindId * NativeHopacIvarRegistryId
            | WitnessRoutingLatticeCyclePoison of TerminalWitnessKindId

        let witnessRoutingLatticeText = function
            | WitnessRoutingLatticeUnresolved -> "[Witness:Missing]->[Route:Wait]->[Status:Unresolved]"
            | WitnessRoutingLatticeImmediateFill (w,ivar) -> "[Witness:" + terminalWitnessKindText w + "]->[Route:IVar.fill]->[IVar:" + nativeHopacIvarRegistryText ivar + "]->[Status:InlineCommitted]"
            | WitnessRoutingLatticePromiseBind (w,ivar) -> "[Witness:" + terminalWitnessKindText w + "]->[Route:Job.bind]->[Promise:" + nativeHopacIvarRegistryText ivar + "]->[Status:NativeQueue]"
            | WitnessRoutingLatticeCyclePoison w -> "[Witness:" + terminalWitnessKindText w + "]->[Route:CyclePoisonPromise]->[Status:NativeQueue]"

        // MIGRATION: the assessment asked for memory-level native Promise identifiers and
        // the exact commit pathway executing the continuation.  These DUs keep that
        // topology typed before JSON/HUD rendering, making the legacy frontier an
        // impossible return target once the proof tuple is complete.
        type NativePromiseIdentifierId =
            | NativePromiseIdentifier of NativeHopacIvarRegistryId * TerminalWitnessKindId
            | NativePromiseIdentifierCyclePoison of TerminalWitnessKindId
            | NativePromiseIdentifierUnknown of CompilerKernelV2.OperationalReasonId

        let nativePromiseIdentifierText = function
            | NativePromiseIdentifier (ivar,witness) -> "promise_id(" + nativeHopacIvarRegistryText ivar + "," + terminalWitnessKindText witness + ")"
            | NativePromiseIdentifierCyclePoison witness -> "cycle_poison_promise_id(" + terminalWitnessKindText witness + ")"
            | NativePromiseIdentifierUnknown reasonId -> CompilerKernelV2.OperationalReasonIdOps.text reasonId

        type WorkerReturnTopologyId =
            | WorkerReturnNativeRunQueueAfterIvarFill of NativeHopacIvarRegistryId
            | WorkerReturnNativeRunQueueAfterJobBind of NativeHopacIvarRegistryId
            | WorkerReturnNativeRunQueueAfterCyclePoison of TerminalWitnessKindId
            | WorkerReturnLegacyHudFrontierForbidden of LegacyVetoQuarantineId

        let workerReturnTopologyText = function
            | WorkerReturnNativeRunQueueAfterIvarFill ivar -> "return:native_hopac_run_queue_after_IVar.fill(" + nativeHopacIvarRegistryText ivar + ")"
            | WorkerReturnNativeRunQueueAfterJobBind ivar -> "return:native_hopac_run_queue_after_Job.bind(" + nativeHopacIvarRegistryText ivar + ")"
            | WorkerReturnNativeRunQueueAfterCyclePoison witness -> "return:native_hopac_run_queue_after_CyclePoisonPromise(" + terminalWitnessKindText witness + ")"
            | WorkerReturnLegacyHudFrontierForbidden legacy -> "forbid:return_to_eval_worklist_hud_terminal_frontier(" + legacyVetoQuarantineText legacy + ")"

        type NativeRunQueueCommitId =
            | NativeRunQueueCommitIvarFill of NativeHopacIvarRegistryId * ParentContinuationFillStrategyId
            | NativeRunQueueCommitJobBind of NativeHopacIvarRegistryId
            | NativeRunQueueCommitCyclePoison of TerminalWitnessKindId
            | NativeRunQueueCommitReceiptOnly

        let nativeRunQueueCommitText = function
            | NativeRunQueueCommitIvarFill (ivar,fill) -> "commit:IVar.fill(" + nativeHopacIvarRegistryText ivar + "," + parentContinuationFillStrategyText fill + ")"
            | NativeRunQueueCommitJobBind ivar -> "commit:Job.bind(Promise(" + nativeHopacIvarRegistryText ivar + "))"
            | NativeRunQueueCommitCyclePoison witness -> "commit:CyclePoisonPromise(" + terminalWitnessKindText witness + ")"
            | NativeRunQueueCommitReceiptOnly -> "commit:receipt_only_after_native_callback"

        type ProofTupleExecutionClosure = {
            promiseIdentifier: NativePromiseIdentifierId
            workerReturn: WorkerReturnTopologyId
            runQueueCommit: NativeRunQueueCommitId
            legacyYieldForbidden: bool
            hudFrontierReceiptOnly: bool
            }

        let nativePromiseIdentifierFor (tuple: PendingGraphProofTuple) =
            match tuple.witness.kind with
            | WitnessParentReplayCycleBreakPoisonImmediateFillProof
            | WitnessCrossKindYieldThrashHardPoisonProof
            | WitnessHardPoisonObligationCapProof -> NativePromiseIdentifierCyclePoison tuple.witness.kind
            | _ -> NativePromiseIdentifier (tuple.witness.ivar, tuple.witness.kind)

        let workerReturnTopologyFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof -> WorkerReturnNativeRunQueueAfterCyclePoison tuple.witness.kind
                | _ -> WorkerReturnNativeRunQueueAfterIvarFill tuple.witness.ivar
            else WorkerReturnNativeRunQueueAfterJobBind tuple.witness.ivar

        let nativeRunQueueCommitFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof -> NativeRunQueueCommitCyclePoison tuple.witness.kind
                | _ -> NativeRunQueueCommitIvarFill (tuple.witness.ivar, tuple.fillStrategy)
            else NativeRunQueueCommitJobBind tuple.witness.ivar

        let proofTupleExecutionClosureFor (tuple: PendingGraphProofTuple) =
            { promiseIdentifier = nativePromiseIdentifierFor tuple
              workerReturn = workerReturnTopologyFor tuple
              runQueueCommit = nativeRunQueueCommitFor tuple
              legacyYieldForbidden = pendingGraphProofTupleComplete tuple
              hudFrontierReceiptOnly = pendingGraphProofTupleComplete tuple }

        let proofTupleExecutionClosureText (closure: ProofTupleExecutionClosure) =
            FastRuntimeFormat.format "promise=%s|worker=%s|run_queue=%s|legacy_yield_forbidden=%b|hud_receipt_only=%b" [| box (nativePromiseIdentifierText closure.promiseIdentifier); box (workerReturnTopologyText closure.workerReturn); box (nativeRunQueueCommitText closure.runQueueCommit); box closure.legacyYieldForbidden; box closure.hudFrontierReceiptOnly |]

        type ActiveNativeCallbackBoundaryId =
            | ActiveCallbackExecuteBeforeEvalWorklistBoundary
            | ActiveCallbackBindExistingPromiseBeforeLegacyObserver
            | ActiveCallbackReturnNativePromiseResultAfterInlineCommit
            | ActiveCallbackObserverOnlyUntilWitness

        let activeNativeCallbackBoundaryText = function
            | ActiveCallbackExecuteBeforeEvalWorklistBoundary -> "execute_native_direct_ast_eval_before_polling_boundary"
            | ActiveCallbackBindExistingPromiseBeforeLegacyObserver -> "bind_existing_promise_before_legacy_observer"
            | ActiveCallbackReturnNativePromiseResultAfterInlineCommit -> "return:NativePromiseResult_after_inline_native_callback"
            | ActiveCallbackObserverOnlyUntilWitness -> "observer_only_until_witness_materializes"

        type ActiveNativeCallbackClosure = {
            callback: NativeCallbackCommitmentId
            boundary: ActiveNativeCallbackBoundaryId
            workerReturn: WorkerReturnTopologyId
            runQueueCommit: NativeRunQueueCommitId
            legacyLiveTailReachable: bool
            evalWorklistBoundaryReachable: bool
            }

        let activeNativeCallbackClosureFor (tuple: PendingGraphProofTuple) =
            let complete = pendingGraphProofTupleComplete tuple
            { callback = if complete then NativeCallbackCommitmentIvarFill (tuple.witness.ivar, tuple.fillStrategy) else NativeCallbackCommitmentPromiseBind tuple.witness.ivar
              boundary = if complete then ActiveCallbackExecuteBeforeEvalWorklistBoundary else ActiveCallbackBindExistingPromiseBeforeLegacyObserver
              workerReturn = workerReturnTopologyFor tuple
              runQueueCommit = nativeRunQueueCommitFor tuple
              legacyLiveTailReachable = not complete
              evalWorklistBoundaryReachable = not complete }

        let activeNativeCallbackClosureText (closure: ActiveNativeCallbackClosure) =
            FastRuntimeFormat.format "callback=%s|boundary=%s|worker=%s|run_queue=%s|legacy_live_tail_reachable=%b|eval_worklist_boundary_reachable=%b|return=callback_result_projected_by_ast_delta" [| box (nativeCallbackCommitmentText closure.callback); box (activeNativeCallbackBoundaryText closure.boundary); box (workerReturnTopologyText closure.workerReturn); box (nativeRunQueueCommitText closure.runQueueCommit); box closure.legacyLiveTailReachable; box closure.evalWorklistBoundaryReachable |]

        let proofTupleAuthorityDecisionFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                ProofTupleDecisionFillIvarImmediately (tuple.witness.ivar, tuple.fillStrategy)
            else
                ProofTupleDecisionBindNativePromise tuple.witness.ivar

        type ProofTupleCompactProjection = {
            payloadDu: string
            witnessKind: TerminalWitnessKindId
            ivarRegistry: NativeHopacIvarRegistryId
            fillStrategy: ParentContinuationFillStrategyId
            authorityDecision: ProofTupleAuthorityDecisionId
            recyclePolicy: HotRowRecyclePolicyId
            nextAction: string
            }

        let proofTupleCompactProjectionFor (tuple: PendingGraphProofTuple) =
            let matrix = proofTupleMatrixStatusFor tuple
            let decision = proofTupleAuthorityDecisionFor tuple
            let nextAction =
                match decision with
                | ProofTupleDecisionFillIvarImmediately _ -> "fill_parent_continuation_ivar_immediately"
                | ProofTupleDecisionBindNativePromise _ -> "bind_native_promise_before_hud_frontier"
                | ProofTupleDecisionQuarantineHudFrontier _ -> "quarantine_hud_frontier"
                | ProofTupleDecisionCompactObserverPolling _ -> "compact_observer_polling"
            { payloadDu = tuple.witness.payload
              witnessKind = tuple.witness.kind
              ivarRegistry = tuple.witness.ivar
              fillStrategy = tuple.fillStrategy
              authorityDecision = decision
              recyclePolicy = matrix.recyclePolicy
              nextAction = nextAction }

        let proofTupleCompactProjectionText (projection: ProofTupleCompactProjection) =
            FastRuntimeFormat.format "payload=%s|witness=%s|ivar=%s|fill=%s|decision=%s|recycle=%s|next=%s" [| box projection.payloadDu; box (terminalWitnessKindText projection.witnessKind); box (nativeHopacIvarRegistryText projection.ivarRegistry); box (parentContinuationFillStrategyText projection.fillStrategy); box (proofTupleAuthorityDecisionText projection.authorityDecision); box (hotRowRecyclePolicyText projection.recyclePolicy); box projection.nextAction |]

        let proofTupleAuthorityStackFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof
                | WitnessParentReplayStatusPreservedCacheHandoffProof
                | WitnessNoRootBudgetParentReplayImmediateFillProof
                | WitnessCooperativeReplayNativeBindProof -> ProofTupleAuthorityStackTypedProofRecycleThenCallback
                | _ -> ProofTupleAuthorityStackTypedProofNativeCallback
            else ProofTupleAuthorityStackMissingWitness

        let nativeCallbackCommitmentFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof -> NativeCallbackCommitmentCyclePoisonPromise tuple.witness.kind
                | _ -> NativeCallbackCommitmentIvarFill (tuple.witness.ivar, tuple.fillStrategy)
            else NativeCallbackCommitmentPromiseBind tuple.witness.ivar

        let compactObserverEnvelopeFor (tuple: PendingGraphProofTuple) =
            match tuple.witness.kind with
            | WitnessJoinWaitDriverPromiseProof -> CompactObserverEnvelopeJoinWaitKeyPayloadIvarFill
            | WitnessParentCacheHandoffWakeProof
            | WitnessParentReplayStatusPreservedCacheHandoffProof
            | WitnessCooperativeReplayNativeBindProof -> CompactObserverEnvelopeCacheHandoffPayloadPromiseNext
            | WitnessParentReplayCycleBreakPoisonImmediateFillProof
            | WitnessCrossKindYieldThrashHardPoisonProof
            | WitnessHardPoisonObligationCapProof -> CompactObserverEnvelopeHardPoisonPayloadWitnessIvar
            | _ when pendingGraphProofTupleComplete tuple -> CompactObserverEnvelopeProofTupleOnly
            | _ -> CompactObserverEnvelopeFullOnceThenKeyedDelta

        let nativeInlineCallbackCutoverFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof -> NativeInlineCallbackCutoverCyclePoison tuple.witness.kind
                | _ -> NativeInlineCallbackCutoverIvarFill (tuple.witness.ivar, tuple.fillStrategy)
            else NativeInlineCallbackCutoverJobBind tuple.witness.ivar

        let legacyObserverTopologyFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof -> LegacyObserverTopologySeveredByCyclePoison
                | _ -> LegacyObserverTopologySeveredByInlineIvarFill
            else LegacyObserverTopologySeveredByNativePromiseBind

        let witnessRoutingLatticeFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof -> WitnessRoutingLatticeCyclePoison tuple.witness.kind
                | _ -> WitnessRoutingLatticeImmediateFill (tuple.witness.kind, tuple.witness.ivar)
            else WitnessRoutingLatticePromiseBind (tuple.witness.kind, tuple.witness.ivar)

        let proofTupleAuthorityClosureText (tuple: PendingGraphProofTuple) =
            FastRuntimeFormat.format "stack=%s|callback=%s|inline_cutover=%s|topology=%s|compact=%s|hud=severed|legacy=topologically_inaccessible" [| box (proofTupleAuthorityStackText (proofTupleAuthorityStackFor tuple)); box (nativeCallbackCommitmentText (nativeCallbackCommitmentFor tuple)); box (nativeInlineCallbackCutoverText (nativeInlineCallbackCutoverFor tuple)); box (legacyObserverTopologyText (legacyObserverTopologyFor tuple)); box (compactObserverEnvelopeText (compactObserverEnvelopeFor tuple)) |]

        type ProofTupleWakeAuthorityId =
            | ProofTupleWakeApplySpineStoreDirect
            | ProofTupleWakeSemanticStaleRetarget
            | ProofTupleWakeDynamicRecordKeyBridgeTail
            | ProofTupleWakeObservedPinnedTerminal
            | ProofTupleWakeIdleCrossKindSidecarDrain
            | ProofTupleWakeParentReplayCycleBreakPoison
            | ProofTupleWakeNoRootBudgetParentReplayImmediateFill
            | ProofTupleWakePendingGraphCommittedTerminal
            | ProofTupleWakeParentReplayStatusPreservedCacheHandoff

        let private proofTupleWakeSanitizeTargetKey (targetKey: string) =
            if System.String.IsNullOrWhiteSpace targetKey then "frontier_unknown"
            else targetKey.Replace("\"", "'").Replace("\\", "/")

        let private proofTupleWakeTargetIdentity (targetKey: string) =
            let sanitized = proofTupleWakeSanitizeTargetKey targetKey
            DiagJson.NativeWakeTargetIdentity.create targetKey sanitized

        let private proofTupleWakeTargetFields (targetKey:string) =
            proofTupleWakeSanitizeTargetKey targetKey
            |> DiagJson.NativeWakeTargetFieldParser.parse

        let private proofTupleWakeTargetFieldText field fields =
            DiagJson.NativeWakeTargetFieldParser.value field fields
            |> Option.defaultValue ""

        let private proofTupleWakeIvarRegistryText = function
            | ProofTupleWakeApplySpineStoreDirect -> "metronome_terminal_authority:apply_spine_store_direct"
            | ProofTupleWakeSemanticStaleRetarget -> "metronome_terminal_authority:semantic_stale_retarget"
            | ProofTupleWakeDynamicRecordKeyBridgeTail -> "metronome_terminal_authority:dynamic_record_key_bridge_commit"
            | ProofTupleWakeObservedPinnedTerminal -> "metronome_terminal_authority:observed_pinned_terminal_payload"
            | ProofTupleWakeIdleCrossKindSidecarDrain -> "metronome_terminal_authority:idle_cross_kind_terminal_commit"
            | ProofTupleWakeParentReplayCycleBreakPoison -> "metronome_terminal_authority:parent_replay_poison_live_tail"
            | ProofTupleWakeNoRootBudgetParentReplayImmediateFill -> "metronome_terminal_authority:no_root_budget_parent_replay_immediate_fill"
            | ProofTupleWakePendingGraphCommittedTerminal
            | ProofTupleWakeParentReplayStatusPreservedCacheHandoff -> "metronome_terminal_authority:parent_replay_status_preserved_cache_handoff"

        let private proofTupleWakeTargetNodeToken authority targetKey =
            let fields = proofTupleWakeTargetFields targetKey
            let child = proofTupleWakeTargetFieldText DiagJson.NativeWakeTargetChild fields
            let node = proofTupleWakeTargetFieldText DiagJson.NativeWakeTargetNode fields
            let owner = proofTupleWakeTargetFieldText DiagJson.NativeWakeTargetOwner fields
            let suffix = DiagJson.NativeWakeTargetFieldParser.hashSuffix fields |> Option.defaultValue ""
            let structural = if child <> "" then child elif node <> "" then node elif owner <> "" then owner elif suffix <> "" then suffix else ""
            if structural <> "" then structural
            else
                let raw = proofTupleWakeIvarRegistryText authority + "|" + proofTupleWakeSanitizeTargetKey targetKey
                CompilerIdentityKernel.ContentDigest.ofText "proof-tuple-wake-target-node" raw
                |> CompilerIdentityKernel.ContentDigest.text

        let private proofTupleWakeTopologyEdgeText authority targetKey =
            let target = proofTupleWakeSanitizeTargetKey targetKey
            let fields = proofTupleWakeTargetFields targetKey
            let owner = proofTupleWakeTargetFieldText DiagJson.NativeWakeTargetOwner fields
            let child = proofTupleWakeTargetFieldText DiagJson.NativeWakeTargetChild fields
            let node = proofTupleWakeTargetFieldText DiagJson.NativeWakeTargetNode fields
            let targetNode = proofTupleWakeTargetNodeToken authority targetKey
            let ownerText =
                if owner <> "" then owner
                elif target <> "" && target <> "frontier_unknown" then target
                elif node <> "" then node
                elif targetNode <> "" then targetNode
                else "UNKNOWN_OWNER"
            let childText = if child <> "" then child else targetNode
            "owner=" + ownerText + "->child=" + childText + "|target=" + target

        let private proofTupleWakeStructuralNodeIdText authority targetKey =
            "IVar_for_Node_" + proofTupleWakeTargetNodeToken authority targetKey

        let private proofTupleWakePromiseIdText authority targetKey =
            "Promise_for_Node_" + proofTupleWakeTargetNodeToken authority targetKey

        let private proofTupleWakeContinuationBindingTargetsText authority targetKey =
            let edge = proofTupleWakeTopologyEdgeText authority targetKey
            match authority with
            | ProofTupleWakeApplySpineStoreDirect -> "[ApplySpineStoreDirectConsumer(" + edge + ");ParentContinuationCell(" + edge + ");PendingGraphTerminalConsumer(" + edge + ")]"
            | ProofTupleWakeSemanticStaleRetarget -> "[RootCompleteLiveReplay(" + edge + ");IdleCrossKindSidecarDrain(" + edge + ");ParentContinuationCell(" + edge + ")]"
            | ProofTupleWakeDynamicRecordKeyBridgeTail -> "[DynamicBridgeParentContinuation(" + edge + ");DynamicJoinApplyReplay(" + edge + ");WriterlessQueueDrain(" + edge + ")]"
            | ProofTupleWakeObservedPinnedTerminal -> "[ObservedPinnedParentContinuation(" + edge + ");ParentContinuationCell(" + edge + ")]"
            | ProofTupleWakeIdleCrossKindSidecarDrain -> "[TySidecarDrainContinuation(" + edge + ");CrossKindSiblingReplay(" + edge + ");ParentContinuationCell(" + edge + ")]"
            | ProofTupleWakeParentReplayCycleBreakPoison -> "[ParentReplayPoisonContinuation(" + edge + ");CycleBreakConsumer(" + edge + ")]"
            | ProofTupleWakeNoRootBudgetParentReplayImmediateFill -> "[NoRootBudgetParentReplayJobBind(" + edge + ");ParentReplayCycleBreakConsumer(" + edge + ");ContinuationCellWake(" + edge + ")]"
            | ProofTupleWakePendingGraphCommittedTerminal
            | ProofTupleWakeParentReplayStatusPreservedCacheHandoff -> "[ParentReplayStatusPreservedCacheHandoffConsumer(" + edge + ");CooperativeReplayNativeBindConsumer(" + edge + ");ParentContinuationCell(" + edge + ")]"

        let private proofTupleWakeContinuationTargetShape : ProofTupleWakeAuthorityId -> DiagJson.NativeWakeContinuationTargetId list * int = function
            | ProofTupleWakeApplySpineStoreDirect ->
                [ DiagJson.NativeWakeContinuationApplySpineStore
                  DiagJson.NativeWakeContinuationParentContinuationCell
                  DiagJson.NativeWakeContinuationPendingGraphTerminal ], 3
            | ProofTupleWakeSemanticStaleRetarget ->
                [ DiagJson.NativeWakeContinuationSemanticStaleRetarget
                  DiagJson.NativeWakeContinuationIdleCrossKindSidecar
                  DiagJson.NativeWakeContinuationParentContinuationCell ], 3
            | ProofTupleWakeDynamicRecordKeyBridgeTail ->
                [ DiagJson.NativeWakeContinuationDynamicBridgeParent
                  DiagJson.NativeWakeContinuationDynamicJoinReplay
                  DiagJson.NativeWakeContinuationWriterlessQueueDrain ], 3
            | ProofTupleWakeObservedPinnedTerminal ->
                [ DiagJson.NativeWakeContinuationObservedPinnedParent
                  DiagJson.NativeWakeContinuationParentContinuationCell ], 2
            | ProofTupleWakeIdleCrossKindSidecarDrain ->
                [ DiagJson.NativeWakeContinuationTySidecarDrain
                  DiagJson.NativeWakeContinuationCrossKindSiblingReplay
                  DiagJson.NativeWakeContinuationParentContinuationCell ], 3
            | ProofTupleWakeParentReplayCycleBreakPoison ->
                [ DiagJson.NativeWakeContinuationParentReplayPoison ], 2
            | ProofTupleWakeNoRootBudgetParentReplayImmediateFill ->
                [ DiagJson.NativeWakeContinuationParentReplayPoison
                  DiagJson.NativeWakeContinuationParentContinuationCell
                  DiagJson.NativeWakeContinuationParentBindingProbe ], 3
            | ProofTupleWakePendingGraphCommittedTerminal
            | ProofTupleWakeParentReplayStatusPreservedCacheHandoff ->
                [ DiagJson.NativeWakeContinuationParentReplayStatusPreservedCacheHandoff
                  DiagJson.NativeWakeContinuationCooperativeReplayNativeBind
                  DiagJson.NativeWakeContinuationParentContinuationCell ], 3

        let private proofTupleWakeContinuationTargets (authority: ProofTupleWakeAuthorityId) (targetIdentity: DiagJson.NativeWakeTargetIdentity) : DiagJson.NativeWakeContinuationTargets =
            let targetIds, bindingCount = proofTupleWakeContinuationTargetShape authority
            let targetKey = DiagJson.NativeWakeTargetIdentity.sanitizedText targetIdentity
            let rawText = proofTupleWakeContinuationBindingTargetsText authority targetKey
            DiagJson.NativeWakeContinuationTargets.ofStructured targetIds bindingCount rawText

        type ProofTupleWakeBindingStateId =
            | ProofTupleWakeBoundParentContinuationTargets
            | ProofTupleWakePartialOwnerIdentityParentBindProbeRequired
            | ProofTupleWakeUnboundTopologicalIsland

        let private proofTupleWakeBindingStateText = function
            | ProofTupleWakeBoundParentContinuationTargets -> "bound_parent_continuation_targets"
            | ProofTupleWakePartialOwnerIdentityParentBindProbeRequired -> "partial_owner_identity_parent_bind_probe_required"
            | ProofTupleWakeUnboundTopologicalIsland -> "unbound_topological_island"

        let private proofTupleWakeFateText = function
            | ProofTupleWakeBoundParentContinuationTargets -> "native_fill_wakes_parent_job_bind_cascade"
            | ProofTupleWakePartialOwnerIdentityParentBindProbeRequired -> "native_fill_requires_parent_binding_identity_repair"
            | ProofTupleWakeUnboundTopologicalIsland -> "native_fill_executed_but_no_parent_job_bind_listener"

        let private proofTupleWakeTopologicalDisconnectProbeId (authority: ProofTupleWakeAuthorityId) (targetIdentity: DiagJson.NativeWakeTargetIdentity) : DiagJson.NativeWakeTopologicalDisconnectId =
            let targetIdentityState = DiagJson.NativeWakeTargetIdentity.state targetIdentity
            let targets = proofTupleWakeContinuationTargets authority targetIdentity
            match targetIdentityState with
            | DiagJson.NativeWakeTargetIdentityFrontierUnknown
            | DiagJson.NativeWakeTargetIdentityErased ->
                DiagJson.NativeWakeDisconnectUnboundOrErasedIdentity
            | DiagJson.NativeWakeTargetIdentityAvailable when DiagJson.NativeWakeContinuationTargets.hasUnknownOwner targets ->
                DiagJson.NativeWakeDisconnectPartialOwnerIdentityRequiresParentBindProbe
            | DiagJson.NativeWakeTargetIdentityAvailable ->
                DiagJson.NativeWakeDisconnectStructuralContinuationTargets

        let private proofTupleWakeContinuationBindingCount authority targetIdentity =
            match proofTupleWakeTopologicalDisconnectProbeId authority targetIdentity with
            | DiagJson.NativeWakeDisconnectUnboundOrErasedIdentity -> 0
            | _ ->
                proofTupleWakeContinuationTargets authority targetIdentity
                |> DiagJson.NativeWakeContinuationTargets.bindingCount

        let private proofTupleWakeBindingStateId authority targetIdentity =
            match proofTupleWakeTopologicalDisconnectProbeId authority targetIdentity with
            | DiagJson.NativeWakeDisconnectUnboundOrErasedIdentity -> ProofTupleWakeUnboundTopologicalIsland
            | DiagJson.NativeWakeDisconnectPartialOwnerIdentityRequiresParentBindProbe -> ProofTupleWakePartialOwnerIdentityParentBindProbeRequired
            | _ -> ProofTupleWakeBoundParentContinuationTargets

        type ProofTupleWakeRepairActionId =
            | ProofTupleWakeRepairBindingResolved
            | ProofTupleWakeRepairGraftActiveWorker
            | ProofTupleWakeRepairMaterializeMissingParentBind

        let private proofTupleWakeRepairActionFor bindingState activeParentProbePresent =
            match bindingState, activeParentProbePresent with
            | ProofTupleWakeBoundParentContinuationTargets, _ -> ProofTupleWakeRepairBindingResolved
            | ProofTupleWakePartialOwnerIdentityParentBindProbeRequired, true
            | ProofTupleWakeUnboundTopologicalIsland, true -> ProofTupleWakeRepairGraftActiveWorker
            | ProofTupleWakePartialOwnerIdentityParentBindProbeRequired, false
            | ProofTupleWakeUnboundTopologicalIsland, false -> ProofTupleWakeRepairMaterializeMissingParentBind

        let private proofTupleWakeRepairActionText = function
            | ProofTupleWakeRepairBindingResolved -> "parent_promise_binding_resolved_from_wake_edge"
            | ProofTupleWakeRepairGraftActiveWorker -> "graft_active_worker_as_parent_promise_listener"
            | ProofTupleWakeRepairMaterializeMissingParentBind -> "materialize_missing_parent_job_bind_listener"

        type ProofTupleParentJobBindMaterializationId =
            | ProofTupleParentJobBindAlreadyMaterialized
            | ProofTupleParentJobBindForceBoundConsumerDelta
            | ProofTupleParentJobBindGraftFromWakeAuthority
            | ProofTupleParentJobBindMaterializeMissingConsumer

        let private proofTupleParentJobBindMaterializationText = function
            | ProofTupleParentJobBindAlreadyMaterialized -> "parent_job_bind_already_materialized"
            | ProofTupleParentJobBindForceBoundConsumerDelta -> "force_bound_parent_consumer_delta_before_metronome"
            | ProofTupleParentJobBindGraftFromWakeAuthority -> "graft_parent_job_bind_from_proof_tuple_wake_authority"
            | ProofTupleParentJobBindMaterializeMissingConsumer -> "materialize_missing_parent_job_bind_consumer"

        let private proofTupleParentJobBindMaterializationFor authority bindingState =
            match authority, bindingState with
            | (ProofTupleWakeIdleCrossKindSidecarDrain
              | ProofTupleWakeParentReplayCycleBreakPoison
              | ProofTupleWakeDynamicRecordKeyBridgeTail
              | ProofTupleWakeSemanticStaleRetarget
              | ProofTupleWakeNoRootBudgetParentReplayImmediateFill), ProofTupleWakeBoundParentContinuationTargets -> ProofTupleParentJobBindForceBoundConsumerDelta
            | _, ProofTupleWakeBoundParentContinuationTargets -> ProofTupleParentJobBindAlreadyMaterialized
            | ProofTupleWakeNoRootBudgetParentReplayImmediateFill, _ -> ProofTupleParentJobBindGraftFromWakeAuthority
            | _, ProofTupleWakePartialOwnerIdentityParentBindProbeRequired -> ProofTupleParentJobBindGraftFromWakeAuthority
            | _, ProofTupleWakeUnboundTopologicalIsland -> ProofTupleParentJobBindMaterializeMissingConsumer

        let private proofTupleParentJobBindContractText materialization edge bindTarget promiseId =
            "materialization=" + proofTupleParentJobBindMaterializationText materialization + "|edge=" + edge + "|bind_target=" + bindTarget + "|wake_promise=" + promiseId + "|return=Job.bind->semantic_result_or_plateau_poison"

        type ProofTupleParentJobBindExecutionId =
            | ProofTupleParentJobBindExecutionNotRequired
            | ProofTupleParentJobBindExecuteBoundConsumerDelta
            | ProofTupleParentJobBindExecuteWakeAuthority
            | ProofTupleParentJobBindExecuteMissingConsumer

        let private proofTupleParentJobBindExecutionFor = function
            | ProofTupleParentJobBindAlreadyMaterialized -> ProofTupleParentJobBindExecuteBoundConsumerDelta
            | ProofTupleParentJobBindForceBoundConsumerDelta -> ProofTupleParentJobBindExecuteBoundConsumerDelta
            | ProofTupleParentJobBindGraftFromWakeAuthority -> ProofTupleParentJobBindExecuteWakeAuthority
            | ProofTupleParentJobBindMaterializeMissingConsumer -> ProofTupleParentJobBindExecuteMissingConsumer

        let private proofTupleParentJobBindExecutionText = function
            | ProofTupleParentJobBindExecutionNotRequired -> "parent_job_bind_execution_not_required"
            | ProofTupleParentJobBindExecuteBoundConsumerDelta -> "execute_bound_parent_consumer_delta_before_metronome"
            | ProofTupleParentJobBindExecuteWakeAuthority -> "execute_job_bind_from_proof_tuple_wake_authority"
            | ProofTupleParentJobBindExecuteMissingConsumer -> "execute_job_bind_for_missing_parent_consumer"

        let private proofTupleParentJobBindExecutionClosureText execution bindTarget promiseId =
            match execution with
            | ProofTupleParentJobBindExecutionNotRequired -> "none:parent_job_bind_already_materialized"
            | ProofTupleParentJobBindExecuteBoundConsumerDelta -> "Job.bind(" + bindTarget + ")->" + promiseId + "|force=consumer_delta_before_metronome|schedule=native_direct_ast_eval_or_ivar_fill_before_any_polling_boundary|return=semantic_result_or_plateau_poison"
            | _ -> "Job.bind(" + bindTarget + ")->" + promiseId + "|schedule=native_direct_ast_eval_before_any_polling_boundary|return=semantic_result_or_plateau_poison"

        let private proofTupleParentJobBindRecyclePolicyText execution =
            match execution with
            | ProofTupleParentJobBindExecutionNotRequired -> "retain_cadence_after_existing_bind"
            | _ -> "emit_first_bind_execution_then_hud_only_until_delta"

        type ProofTupleParentJobBindGraftStatusId =
            | ProofTupleParentJobBindGraftMaterialized
            | ProofTupleParentJobBindGraftPendingForceReplay
            | ProofTupleParentJobBindGraftNoDeltaAfterGraft
            | ProofTupleParentJobBindGraftUnboundIsland

        let private proofTupleParentJobBindGraftStatusFor (bindingState: ProofTupleWakeBindingStateId) (execution: ProofTupleParentJobBindExecutionId) =
            match bindingState, execution with
            | ProofTupleWakeBoundParentContinuationTargets, ProofTupleParentJobBindExecutionNotRequired -> ProofTupleParentJobBindGraftMaterialized
            | ProofTupleWakeBoundParentContinuationTargets, _ -> ProofTupleParentJobBindGraftPendingForceReplay
            | ProofTupleWakePartialOwnerIdentityParentBindProbeRequired, _ -> ProofTupleParentJobBindGraftPendingForceReplay
            | ProofTupleWakeUnboundTopologicalIsland, _ -> ProofTupleParentJobBindGraftUnboundIsland

        let private proofTupleParentJobBindGraftStatusText = function
            | ProofTupleParentJobBindGraftMaterialized -> "materialized"
            | ProofTupleParentJobBindGraftPendingForceReplay -> "pending_force_replay"
            | ProofTupleParentJobBindGraftNoDeltaAfterGraft -> "no_delta_after_graft"
            | ProofTupleParentJobBindGraftUnboundIsland -> "unbound_island"

        // MIGRATION: proof-tuple hot rows now mirror the runtime HUD path with
        // typed expected-delta and continuation-status DUs instead of rechecking
        // string literals when deciding graft repair, consumer delta and direct
        // evaluation contracts.
        type ProofTupleWakeExpectedDeltaId =
            | ProofTupleWakeExpectedDeltaNone
            | ProofTupleWakeExpectedDeltaApplySpineStore
            | ProofTupleWakeExpectedDeltaPendingGraphTerminal
            | ProofTupleWakeExpectedDeltaPendingGraphCommittedTerminal
            | ProofTupleWakeExpectedDeltaCooperativeReplayNativeBind
            | ProofTupleWakeExpectedDeltaParentReplayStatusPreservedCacheHandoff
            | ProofTupleWakeExpectedDeltaIdleCrossKindSidecarCallback
            | ProofTupleWakeExpectedDeltaDynamicJoinStackFenceBridge
            | ProofTupleWakeExpectedDeltaDynamicJoinBridgeTailHandoff
            | ProofTupleWakeExpectedDeltaObservedPinnedImmediateFill
            | ProofTupleWakeExpectedDeltaDynamicBridge
            | ProofTupleWakeExpectedDeltaDynamicJoinReplay
            | ProofTupleWakeExpectedDeltaWriterlessQueueDrain
            | ProofTupleWakeExpectedDeltaObservedPinnedTerminal
            | ProofTupleWakeExpectedDeltaSemanticStaleRetarget
            | ProofTupleWakeExpectedDeltaParentReplayCycleBreak
            | ProofTupleWakeExpectedDeltaParentContinuation
            | ProofTupleWakeExpectedDeltaCrossKindSibling
            | ProofTupleWakeExpectedDeltaSidecarDrain
            | ProofTupleWakeExpectedDeltaGraftRepair

        let private proofTupleExpectedDeltaFor (targets: DiagJson.NativeWakeContinuationTargets) (bindingState: ProofTupleWakeBindingStateId) =
            if bindingState = ProofTupleWakeUnboundTopologicalIsland then ProofTupleWakeExpectedDeltaNone
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationApplySpineStore targets then ProofTupleWakeExpectedDeltaApplySpineStore
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationCooperativeReplayNativeBind targets then ProofTupleWakeExpectedDeltaCooperativeReplayNativeBind
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationParentReplayStatusPreservedCacheHandoff targets then ProofTupleWakeExpectedDeltaParentReplayStatusPreservedCacheHandoff
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationIdleCrossKindSidecar targets then ProofTupleWakeExpectedDeltaIdleCrossKindSidecarCallback
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationDynamicJoinStackFenceBridge targets then ProofTupleWakeExpectedDeltaDynamicJoinStackFenceBridge
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationDynamicJoinBridgeTailHandoff targets then ProofTupleWakeExpectedDeltaDynamicJoinBridgeTailHandoff
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationObservedPinnedImmediateFill targets then ProofTupleWakeExpectedDeltaObservedPinnedImmediateFill
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationPendingGraphCommittedTerminal targets then ProofTupleWakeExpectedDeltaPendingGraphCommittedTerminal
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationPendingGraphTerminal targets then ProofTupleWakeExpectedDeltaPendingGraphTerminal
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationDynamicBridgeParent targets then ProofTupleWakeExpectedDeltaDynamicBridge
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationDynamicJoinReplay targets then ProofTupleWakeExpectedDeltaDynamicJoinReplay
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationWriterlessQueueDrain targets then ProofTupleWakeExpectedDeltaWriterlessQueueDrain
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationObservedPinnedParent targets then ProofTupleWakeExpectedDeltaObservedPinnedTerminal
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationSemanticStaleRetarget targets then ProofTupleWakeExpectedDeltaSemanticStaleRetarget
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationParentReplayPoison targets then ProofTupleWakeExpectedDeltaParentReplayCycleBreak
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationTySidecarDrain targets then ProofTupleWakeExpectedDeltaSidecarDrain
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationCrossKindSiblingReplay targets then ProofTupleWakeExpectedDeltaCrossKindSibling
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationParentContinuationCell targets then ProofTupleWakeExpectedDeltaParentContinuation
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationParentBindingProbe targets then ProofTupleWakeExpectedDeltaGraftRepair
            else ProofTupleWakeExpectedDeltaNone

        let private proofTupleExpectedDeltaText = function
            | ProofTupleWakeExpectedDeltaNone -> "none"
            | ProofTupleWakeExpectedDeltaApplySpineStore -> "apply_spine_store_delta_expected"
            | ProofTupleWakeExpectedDeltaPendingGraphTerminal -> "pending_graph_terminal_delta_expected"
            | ProofTupleWakeExpectedDeltaPendingGraphCommittedTerminal -> "pending_graph_committed_terminal_delta_expected"
            | ProofTupleWakeExpectedDeltaCooperativeReplayNativeBind -> "cooperative_replay_native_bind_delta_expected"
            | ProofTupleWakeExpectedDeltaParentReplayStatusPreservedCacheHandoff -> "parent_replay_status_preserved_cache_handoff_delta_expected"
            | ProofTupleWakeExpectedDeltaIdleCrossKindSidecarCallback -> "idle_cross_kind_sidecar_callback_delta_expected"
            | ProofTupleWakeExpectedDeltaDynamicJoinStackFenceBridge -> "dynamic_join_stack_fence_bridge_delta_expected"
            | ProofTupleWakeExpectedDeltaDynamicJoinBridgeTailHandoff -> "dynamic_join_bridge_tail_handoff_delta_expected"
            | ProofTupleWakeExpectedDeltaObservedPinnedImmediateFill -> "observed_pinned_immediate_fill_delta_expected"
            | ProofTupleWakeExpectedDeltaDynamicBridge -> "dynamic_bridge_parent_continuation_delta_expected"
            | ProofTupleWakeExpectedDeltaDynamicJoinReplay -> "dynamic_join_apply_replay_delta_expected"
            | ProofTupleWakeExpectedDeltaWriterlessQueueDrain -> "writerless_queue_drain_delta_expected"
            | ProofTupleWakeExpectedDeltaObservedPinnedTerminal -> "observed_pinned_terminal_delta_expected"
            | ProofTupleWakeExpectedDeltaSemanticStaleRetarget -> "semantic_stale_retarget_direct_delta_expected"
            | ProofTupleWakeExpectedDeltaParentReplayCycleBreak -> "parent_replay_cycle_break_delta_expected"
            | ProofTupleWakeExpectedDeltaParentContinuation -> "parent_continuation_delta_expected"
            | ProofTupleWakeExpectedDeltaCrossKindSibling -> "cross_kind_sibling_delta_expected"
            | ProofTupleWakeExpectedDeltaSidecarDrain -> "sidecar_drain_delta_expected"
            | ProofTupleWakeExpectedDeltaGraftRepair -> "graft_repair_delta_expected"

        type ProofTupleUnresolvedState = class end
        type ProofTupleWitnessedState = class end
        type ProofTupleClearedState = class end
        type ProofTupleNodeKindId =
            | ProofTupleTermNode
            | ProofTupleTyNode
            | ProofTupleParentContinuationNode
            | ProofTupleCrossKindSiblingNode
            | ProofTupleSidecarDrainNode
        type ProofTupleCarrier<'State,'Payload> = private { ProofTupleCarrierNode:string; ProofTupleCarrierKind:ProofTupleNodeKindId; ProofTupleCarrierPayload:'Payload }
        type ProofTupleChildObligationId =
            | ProofTupleChildTerm of node:string * next:string
            | ProofTupleChildTy of node:string * next:string
            | ProofTupleChildParentContinuation of node:string * next:string
            | ProofTupleChildCrossKindSibling of node:string * next:string
            | ProofTupleChildSidecarDrain of node:string * next:string
            | ProofTupleChildSemanticStaleRetarget of node:string * next:string
            | ProofTupleChildParentReplayStatusPreservedCacheHandoff of node:string * next:string
            | ProofTupleChildIdleCrossKindSidecarCallback of node:string * next:string
            | ProofTupleChildDynamicJoinStackFenceBridge of node:string * next:string
            | ProofTupleChildDynamicJoinBridgeTailHandoff of node:string * next:string
            | ProofTupleChildObservedPinnedImmediateFill of node:string * next:string
        type ProofTupleCompositeReplayId =
            | ProofTupleCompositeLeaf of node:string
            | ProofTupleCompositeReplay of node:string * obligations:ProofTupleChildObligationId list
        module ProofTupleCarrier =
            let witness node kind payload : ProofTupleCarrier<ProofTupleWitnessedState,'Payload> = { ProofTupleCarrierNode = node; ProofTupleCarrierKind = kind; ProofTupleCarrierPayload = payload }
            let clear (tuple: ProofTupleCarrier<ProofTupleWitnessedState,'Payload>) : ProofTupleCarrier<ProofTupleClearedState,'Payload> = { ProofTupleCarrierNode = tuple.ProofTupleCarrierNode; ProofTupleCarrierKind = tuple.ProofTupleCarrierKind; ProofTupleCarrierPayload = tuple.ProofTupleCarrierPayload }
            let extractWitness (tuple: ProofTupleCarrier<ProofTupleWitnessedState,'Payload>) = tuple.ProofTupleCarrierPayload
        let proofTupleChildObligationText = function
            | ProofTupleChildTerm(node, next) -> "term_child(" + node + ")->" + next
            | ProofTupleChildTy(node, next) -> "ty_child(" + node + ")->" + next
            | ProofTupleChildParentContinuation(node, next) -> "parent_continuation_child(" + node + ")->" + next
            | ProofTupleChildCrossKindSibling(node, next) -> "cross_kind_sibling_child(" + node + ")->" + next
            | ProofTupleChildSidecarDrain(node, next) -> "sidecar_drain_child(" + node + ")->" + next
            | ProofTupleChildSemanticStaleRetarget(node, next) -> "semantic_stale_retarget_child(" + node + ")->" + next
            | ProofTupleChildParentReplayStatusPreservedCacheHandoff(node, next) -> "parent_replay_status_preserved_cache_handoff_child(" + node + ")->" + next
            | ProofTupleChildIdleCrossKindSidecarCallback(node, next) -> "idle_cross_kind_sidecar_callback_child(" + node + ")->" + next
            | ProofTupleChildDynamicJoinStackFenceBridge(node, next) -> "dynamic_join_stack_fence_bridge_child(" + node + ")->" + next
            | ProofTupleChildDynamicJoinBridgeTailHandoff(node, next) -> "dynamic_join_bridge_tail_handoff_child(" + node + ")->" + next
            | ProofTupleChildObservedPinnedImmediateFill(node, next) -> "observed_pinned_immediate_fill_child(" + node + ")->" + next
        let proofTupleCompositeReplayText = function
            | ProofTupleCompositeLeaf node -> "leaf(" + node + ")"
            | ProofTupleCompositeReplay(node, obligations) -> "replay(" + node + ")[" + (obligations |> List.map proofTupleChildObligationText |> String.concat ";") + "]"

        type ProofTupleCallbackExecutionPlanId =
            | ProofTupleCallbackPlanExecuteDirectAstEval of expected:ProofTupleWakeExpectedDeltaId * composite:ProofTupleCompositeReplayId
            | ProofTupleCallbackPlanForceGraftRepair of composite:ProofTupleCompositeReplayId
            | ProofTupleCallbackPlanResolveParentPromise of composite:ProofTupleCompositeReplayId
            | ProofTupleCallbackPlanRecycleOnly of witness:string
            | ProofTupleCallbackPlanRejectLegacyReturn of witness:string
        let proofTupleCallbackExecutionPlanText = function
            | ProofTupleCallbackPlanExecuteDirectAstEval(expected, composite) -> "plan_execute_direct_ast_eval(expected=" + proofTupleExpectedDeltaText expected + "|" + proofTupleCompositeReplayText composite + ")"
            | ProofTupleCallbackPlanForceGraftRepair(composite) -> "plan_force_graft_repair(" + proofTupleCompositeReplayText composite + ")"
            | ProofTupleCallbackPlanResolveParentPromise(composite) -> "plan_resolve_parent_promise(" + proofTupleCompositeReplayText composite + ")"
            | ProofTupleCallbackPlanRecycleOnly(witness) -> "plan_recycle_only(witness=" + witness + ")"
            | ProofTupleCallbackPlanRejectLegacyReturn(witness) -> "plan_reject_legacy_worklist_return(witness=" + witness + ")"

        type ProofTupleContinuationTargetStatusId =
            | ProofTupleTargetApplySpineStore
            | ProofTupleTargetPendingGraphTerminal
            | ProofTupleTargetPendingGraphCommittedTerminal
            | ProofTupleTargetCooperativeReplayNativeBind
            | ProofTupleTargetParentReplayStatusPreservedCacheHandoff
            | ProofTupleTargetIdleCrossKindSidecarCallback
            | ProofTupleTargetDynamicJoinStackFenceBridge
            | ProofTupleTargetDynamicJoinBridgeTailHandoff
            | ProofTupleTargetObservedPinnedImmediateFill
            | ProofTupleTargetDynamicBridge
            | ProofTupleTargetDynamicJoinReplay
            | ProofTupleTargetWriterlessQueueDrain
            | ProofTupleTargetObservedPinnedTerminal
            | ProofTupleTargetSemanticStaleRetarget
            | ProofTupleTargetRunnableParentContinuation
            | ProofTupleTargetWaitingCrossKind
            | ProofTupleTargetSidecarDrain
            | ProofTupleTargetPoisoned
            | ProofTupleTargetUnknown

        let private proofTupleContinuationTargetStatusFor (targets: DiagJson.NativeWakeContinuationTargets) =
            if DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationParentReplayPoison targets then ProofTupleTargetPoisoned
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationApplySpineStore targets then ProofTupleTargetApplySpineStore
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationCooperativeReplayNativeBind targets then ProofTupleTargetCooperativeReplayNativeBind
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationParentReplayStatusPreservedCacheHandoff targets then ProofTupleTargetParentReplayStatusPreservedCacheHandoff
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationIdleCrossKindSidecar targets then ProofTupleTargetIdleCrossKindSidecarCallback
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationDynamicJoinStackFenceBridge targets then ProofTupleTargetDynamicJoinStackFenceBridge
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationDynamicJoinBridgeTailHandoff targets then ProofTupleTargetDynamicJoinBridgeTailHandoff
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationObservedPinnedImmediateFill targets then ProofTupleTargetObservedPinnedImmediateFill
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationPendingGraphCommittedTerminal targets then ProofTupleTargetPendingGraphCommittedTerminal
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationPendingGraphTerminal targets then ProofTupleTargetPendingGraphTerminal
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationDynamicBridgeParent targets then ProofTupleTargetDynamicBridge
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationDynamicJoinReplay targets then ProofTupleTargetDynamicJoinReplay
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationWriterlessQueueDrain targets then ProofTupleTargetWriterlessQueueDrain
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationObservedPinnedParent targets then ProofTupleTargetObservedPinnedTerminal
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationSemanticStaleRetarget targets then ProofTupleTargetSemanticStaleRetarget
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationCrossKindSiblingReplay targets then ProofTupleTargetWaitingCrossKind
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationTySidecarDrain targets then ProofTupleTargetSidecarDrain
            elif DiagJson.NativeWakeContinuationTargets.has DiagJson.NativeWakeContinuationParentContinuationCell targets then ProofTupleTargetRunnableParentContinuation
            else ProofTupleTargetUnknown

        let private proofTupleContinuationTargetStatusText = function
            | ProofTupleTargetApplySpineStore -> "apply_spine_store_direct"
            | ProofTupleTargetPendingGraphTerminal -> "pending_graph_terminal"
            | ProofTupleTargetPendingGraphCommittedTerminal -> "pending_graph_committed_terminal"
            | ProofTupleTargetCooperativeReplayNativeBind -> "cooperative_replay_native_bind"
            | ProofTupleTargetParentReplayStatusPreservedCacheHandoff -> "parent_replay_status_preserved_cache_handoff"
            | ProofTupleTargetIdleCrossKindSidecarCallback -> "idle_cross_kind_sidecar_callback"
            | ProofTupleTargetDynamicJoinStackFenceBridge -> "dynamic_join_stack_fence_bridge"
            | ProofTupleTargetDynamicJoinBridgeTailHandoff -> "dynamic_join_bridge_tail_handoff"
            | ProofTupleTargetObservedPinnedImmediateFill -> "observed_pinned_immediate_fill"
            | ProofTupleTargetDynamicBridge -> "dynamic_bridge_parent_continuation"
            | ProofTupleTargetDynamicJoinReplay -> "dynamic_join_apply_replay"
            | ProofTupleTargetWriterlessQueueDrain -> "writerless_queue_drain"
            | ProofTupleTargetObservedPinnedTerminal -> "observed_pinned_terminal"
            | ProofTupleTargetSemanticStaleRetarget -> "semantic_stale_retarget"
            | ProofTupleTargetRunnableParentContinuation -> "runnable_parent_continuation"
            | ProofTupleTargetWaitingCrossKind -> "waiting_cross_kind"
            | ProofTupleTargetSidecarDrain -> "sidecar_drain"
            | ProofTupleTargetPoisoned -> "poisoned"
            | ProofTupleTargetUnknown -> "unknown"

        let private proofTupleWakeConsumerDeltaResultFor
            (execution: ProofTupleParentJobBindExecutionId)
            (expectedDeltaId: ProofTupleWakeExpectedDeltaId)
            (continuationStatusId: ProofTupleContinuationTargetStatusId) : DiagJson.NativeWakeConsumerDeltaResultId =
            match execution, expectedDeltaId with
            | _, ProofTupleWakeExpectedDeltaSidecarDrain -> DiagJson.NativeWakeConsumerDeltaPureAstStep
            | (ProofTupleParentJobBindExecuteBoundConsumerDelta | ProofTupleParentJobBindExecuteWakeAuthority), ProofTupleWakeExpectedDeltaNone ->
                if continuationStatusId = ProofTupleTargetPoisoned then DiagJson.NativeWakeConsumerDeltaPoisonOnly
                else DiagJson.NativeWakeConsumerDeltaNotExpected
            | (ProofTupleParentJobBindExecuteBoundConsumerDelta | ProofTupleParentJobBindExecuteWakeAuthority), _ -> DiagJson.NativeWakeConsumerDeltaForcedDirectEval
            | _, ProofTupleWakeExpectedDeltaNone when continuationStatusId = ProofTupleTargetPoisoned -> DiagJson.NativeWakeConsumerDeltaPoisonOnly
            | _, ProofTupleWakeExpectedDeltaNone -> DiagJson.NativeWakeConsumerDeltaNotExpected
            | _ -> DiagJson.NativeWakeConsumerDeltaExpectedButDeferred

        let private proofTupleCrossKindObligationDetailFor
            (expectedDeltaId: ProofTupleWakeExpectedDeltaId)
            (continuationStatusId: ProofTupleContinuationTargetStatusId)
            (graftStatusId: ProofTupleParentJobBindGraftStatusId) : DiagJson.NativeCrossKindObligationDetailId =
            match expectedDeltaId with
            | ProofTupleWakeExpectedDeltaApplySpineStore -> DiagJson.NativeCrossKindObligationApplySpineStoreOwnsWindow
            | ProofTupleWakeExpectedDeltaPendingGraphTerminal -> DiagJson.NativeCrossKindObligationPendingGraphTerminalOwnsWindow
            | ProofTupleWakeExpectedDeltaPendingGraphCommittedTerminal -> DiagJson.NativeCrossKindObligationPendingGraphCommittedTerminalOwnsWindow
            | ProofTupleWakeExpectedDeltaCooperativeReplayNativeBind -> DiagJson.NativeCrossKindObligationCooperativeReplayNativeBindOwnsWindow
            | ProofTupleWakeExpectedDeltaParentReplayStatusPreservedCacheHandoff -> DiagJson.NativeCrossKindObligationParentReplayStatusPreservedCacheHandoffOwnsWindow
            | ProofTupleWakeExpectedDeltaIdleCrossKindSidecarCallback -> DiagJson.NativeCrossKindObligationIdleCrossKindSidecarCallbackOwnsWindow
            | ProofTupleWakeExpectedDeltaDynamicJoinStackFenceBridge -> DiagJson.NativeCrossKindObligationDynamicJoinStackFenceBridgeOwnsWindow
            | ProofTupleWakeExpectedDeltaDynamicJoinBridgeTailHandoff -> DiagJson.NativeCrossKindObligationDynamicJoinBridgeTailHandoffOwnsWindow
            | ProofTupleWakeExpectedDeltaObservedPinnedImmediateFill -> DiagJson.NativeCrossKindObligationObservedPinnedImmediateFillOwnsWindow
            | ProofTupleWakeExpectedDeltaDynamicBridge -> DiagJson.NativeCrossKindObligationDynamicBridgeOwnsWindow
            | ProofTupleWakeExpectedDeltaDynamicJoinReplay -> DiagJson.NativeCrossKindObligationDynamicJoinReplayOwnsWindow
            | ProofTupleWakeExpectedDeltaWriterlessQueueDrain -> DiagJson.NativeCrossKindObligationWriterlessQueueDrainOwnsWindow
            | ProofTupleWakeExpectedDeltaObservedPinnedTerminal -> DiagJson.NativeCrossKindObligationObservedPinnedTerminalOwnsWindow
            | ProofTupleWakeExpectedDeltaSemanticStaleRetarget -> DiagJson.NativeCrossKindObligationSemanticStaleRetargetOwnsWindow
            | ProofTupleWakeExpectedDeltaParentReplayCycleBreak -> DiagJson.NativeCrossKindObligationParentReplayCycleBreakOwnsWindow
            | ProofTupleWakeExpectedDeltaSidecarDrain -> DiagJson.NativeCrossKindObligationSidecarDrainOwnsWindow
            | ProofTupleWakeExpectedDeltaParentContinuation -> DiagJson.NativeCrossKindObligationParentContinuationPending
            | ProofTupleWakeExpectedDeltaCrossKindSibling -> DiagJson.NativeCrossKindObligationSiblingReplayWaiting
            | ProofTupleWakeExpectedDeltaGraftRepair -> DiagJson.NativeCrossKindObligationGraftRepairOwnsWindow
            | ProofTupleWakeExpectedDeltaNone when graftStatusId = ProofTupleParentJobBindGraftPendingForceReplay -> DiagJson.NativeCrossKindObligationGraftRepairOwnsWindow
            | ProofTupleWakeExpectedDeltaNone when continuationStatusId = ProofTupleTargetSidecarDrain -> DiagJson.NativeCrossKindObligationSidecarDrainOwnsWindow
            | ProofTupleWakeExpectedDeltaNone -> DiagJson.NativeCrossKindObligationNone

        type ProofTupleResolutionPayloadEnvelopeId =
            | ProofTupleResolutionCyclePoison of payload:string
            | ProofTupleResolutionSidecarDrainExpectedDelta of payload:string
            | ProofTupleResolutionDynamicBridgeTailExpectedDelta of payload:string
            | ProofTupleResolutionSemanticStaleRetargetExpectedDelta of payload:string
            | ProofTupleResolutionNoRootBudgetParentReplayImmediateFill of payload:string
            | ProofTupleResolutionWitnessPayload of payload:string

        let private proofTupleResolutionPayloadEnvelopeFor authority witnessPayload =
            match authority with
            | ProofTupleWakeParentReplayCycleBreakPoison -> ProofTupleResolutionCyclePoison "CyclePoison(depth=localized,parent_replay=true)"
            | ProofTupleWakeIdleCrossKindSidecarDrain -> ProofTupleResolutionSidecarDrainExpectedDelta "SidecarDrainExpectedDelta(kind=ty_sidecar,parent_cell=ready)"
            | ProofTupleWakeDynamicRecordKeyBridgeTail -> ProofTupleResolutionDynamicBridgeTailExpectedDelta "DynamicBridgeTailExpectedDelta(kind=record_key,parent_replay=ready)"
            | ProofTupleWakeSemanticStaleRetarget -> ProofTupleResolutionSemanticStaleRetargetExpectedDelta "SemanticStaleRetargetExpectedDelta(root_complete_live_replay=true)"
            | ProofTupleWakeNoRootBudgetParentReplayImmediateFill -> ProofTupleResolutionNoRootBudgetParentReplayImmediateFill "NoRootBudgetParentReplayImmediateFill(parent_cycle_break_consumer=true)"
            | _ -> ProofTupleResolutionWitnessPayload witnessPayload

        let private proofTupleResolutionPayloadEnvelopeText = function
            | ProofTupleResolutionCyclePoison payload
            | ProofTupleResolutionSidecarDrainExpectedDelta payload
            | ProofTupleResolutionDynamicBridgeTailExpectedDelta payload
            | ProofTupleResolutionSemanticStaleRetargetExpectedDelta payload
            | ProofTupleResolutionNoRootBudgetParentReplayImmediateFill payload
            | ProofTupleResolutionWitnessPayload payload -> payload

        let private proofTupleResolutionPayloadIsCyclePoison = function
            | ProofTupleResolutionCyclePoison _ -> true
            | _ -> false

        type ProofTupleStructuralCycleId =
            | ProofTupleStructuralBoundWakeZeroFactDeferred of node:string * edge:string * listeners:int
            | ProofTupleStructuralDirectWakeReentryPlateau of node:string * edge:string * payload:string
            | ProofTupleStructuralLocalizedCyclePoison of node:string * edge:string * payload:string
            | ProofTupleStructuralDirectWakeReentry of node:string * edge:string
            | ProofTupleStructuralShadowTimerDeprecated
            | ProofTupleStructuralNoCycle

        let private proofTupleStructuralCycleText = function
            | ProofTupleStructuralBoundWakeZeroFactDeferred(node, edge, listeners) -> "bound_wake_zero_fact_deferred(node=" + node + "|edge=" + edge + "|listeners=" + string listeners + ")"
            | ProofTupleStructuralDirectWakeReentryPlateau(node, edge, payload) -> "direct_wake_reentry_plateau(node=" + node + "|edge=" + edge + "|payload=" + payload + ")"
            | ProofTupleStructuralLocalizedCyclePoison(node, edge, payload) -> "localized_cycle_poison(node=" + node + "|edge=" + edge + "|payload=" + payload + ")"
            | ProofTupleStructuralDirectWakeReentry(node, edge) -> "direct_wake_reentry(node=" + node + "|edge=" + edge + ")"
            | ProofTupleStructuralShadowTimerDeprecated -> "shadow_timer_deprecated(native_expected_delta_edge_replaces_shadow_timeout)"
            | ProofTupleStructuralNoCycle -> "no_structural_cycle"

        let private proofTupleStructuralCycleIsDirectWakeReentry = function
            | ProofTupleStructuralDirectWakeReentryPlateau _
            | ProofTupleStructuralDirectWakeReentry _ -> true
            | _ -> false

        open DiagJson

        let private proofTupleWakeGraphText authority targetKey =
            let nodeId = proofTupleWakeStructuralNodeIdText authority targetKey
            "IVar[Node:" + nodeId + "] filled -> Unblocked Continuations: " + proofTupleWakeContinuationBindingTargetsText authority targetKey

        let private proofTupleWakeTopologicalDisconnectProbeText authority targetIdentity =
            let disconnect =
                proofTupleWakeTopologicalDisconnectProbeId authority targetIdentity
                |> nativeWakeTopologicalDisconnectText
            DiagJson.NativeWakeTargetIdentity.text targetIdentity + "|disconnect=" + disconnect

        let proofTupleWakeMetronomeAuthorityFor (tuple: PendingGraphProofTuple) =
            match tuple.witness.kind with
            | WitnessSemanticStaleRetargetProof -> ProofTupleWakeSemanticStaleRetarget
            | WitnessDynamicJoinBridgeTailProof
            | WitnessDynamicRecordKeyBridgeCommitProof -> ProofTupleWakeDynamicRecordKeyBridgeTail
            | WitnessObservedPinnedTerminalContractProof
            | WitnessObservedPinnedTerminalImmediateFillProof -> ProofTupleWakeObservedPinnedTerminal
            | WitnessIdleCrossKindSidecarDrainProof -> ProofTupleWakeIdleCrossKindSidecarDrain
            | WitnessParentReplayCycleBreakPoisonImmediateFillProof
            | WitnessParentReplayPoisonLiveTailProof -> ProofTupleWakeParentReplayCycleBreakPoison
            | WitnessNoRootBudgetParentReplayImmediateFillProof -> ProofTupleWakeNoRootBudgetParentReplayImmediateFill
            | WitnessParentReplayStatusPreservedCacheHandoffProof -> ProofTupleWakeParentReplayStatusPreservedCacheHandoff
            | _ -> ProofTupleWakePendingGraphCommittedTerminal

        let pendingGraphProofTupleJsonFields tuple =
            let matrix = proofTupleMatrixStatusFor tuple
            let authorityDecision = proofTupleAuthorityDecisionFor tuple
            let compactProjection = proofTupleCompactProjectionFor tuple
            let authorityStack = proofTupleAuthorityStackFor tuple
            let callbackCommitment = nativeCallbackCommitmentFor tuple
            let compactEnvelope = compactObserverEnvelopeFor tuple
            let authorityClosure = proofTupleAuthorityClosureText tuple
            let inlineCutover = nativeInlineCallbackCutoverFor tuple
            let legacyTopology = legacyObserverTopologyFor tuple
            let witnessRoutingLattice = witnessRoutingLatticeFor tuple
            let executionClosure = proofTupleExecutionClosureFor tuple
            let activeClosure = activeNativeCallbackClosureFor tuple
            let witnessForcesPlateauPoison =
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessParentReplayPoisonLiveTailProof
                | WitnessNoRootBudgetParentReplayImmediateFillProof
                | WitnessCooperativeReplayNativeBindProof
                | WitnessParentReplayStatusPreservedCacheHandoffProof
                | WitnessIdleCrossKindSidecarDrainProof -> true
                | _ -> false
            let nativeCallbackControlFlowGateText =
                if pendingGraphProofTupleComplete tuple && witnessForcesPlateauPoison then
                    "proof_tuple_complete->execute_native_direct_ast_callback_before_polling_boundary->return_NativePromiseFailed_PlateauPoison->legacy_unreachable"
                elif pendingGraphProofTupleComplete tuple then
                    "proof_tuple_complete->execute_native_direct_ast_callback_before_polling_boundary->return_semantic_result_or_plateau_poison->legacy_unreachable"
                else
                    "proof_tuple_incomplete->Job.bind_existing_promise_before_legacy_observer"
            let nativePromiseIdentifier = nativePromiseIdentifierFor tuple
            let workerReturnTopology = workerReturnTopologyFor tuple
            let nativeRunQueueCommit = nativeRunQueueCommitFor tuple
            let readinessGateText = if pendingGraphProofTupleComplete tuple then "inline_ivar_fill_ready" else "native_promise_bind_ready"
            let callbackRouteText =
                if pendingGraphProofTupleComplete tuple then
                    "IVar.fill(" + nativeHopacIvarRegistryText tuple.witness.ivar + "," + parentContinuationFillStrategyText tuple.fillStrategy + ")"
                else "Job.bind(Promise(" + nativeHopacIvarRegistryText tuple.witness.ivar + "))"
            let deprecatedPollingText =
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof
                | WitnessParentReplayStatusPreservedCacheHandoffProof
                | WitnessNoRootBudgetParentReplayImmediateFillProof
                | WitnessCooperativeReplayNativeBindProof
                | WitnessSemanticStaleRetargetProof
                | WitnessTyGlobalFuseParentContinuationProof
                | WitnessIdleCrossKindSidecarDrainProof
                | WitnessJoinWaitDriverPromiseProof -> "recycle_qap_recent_sample_term_age_delta_replay"
                | WitnessMetronomeTerminalAuthorityProof -> "compact_polling_fields_after_witness"
                | _ -> "retain_full_fields_for_first_emission"
            let criticalNodeText =
                FastRuntimeFormat.format "payload=%s|witness=%s|ivar=%s|callback=%s|gate=%s|recycle=%s" [| box tuple.witness.payload; box (terminalWitnessKindText tuple.witness.kind); box (nativeHopacIvarRegistryText tuple.witness.ivar); box callbackRouteText; box readinessGateText; box deprecatedPollingText |]
            let hotProjectionText = hotRowAuthorityProjectionText (HotRowProjectionReplayDriverSurface tuple.witness.kind)
            let wakeAuthority = proofTupleWakeMetronomeAuthorityFor tuple
            let wakeTargetIdentity = proofTupleWakeTargetIdentity tuple.witness.cycleRootOrigin
            let wakeTargetKey = DiagJson.NativeWakeTargetIdentity.sanitizedText wakeTargetIdentity
            let wakeNodeId = proofTupleWakeStructuralNodeIdText wakeAuthority wakeTargetKey
            let wakePromiseId = proofTupleWakePromiseIdText wakeAuthority wakeTargetKey
            let wakeTargetsId = proofTupleWakeContinuationTargets wakeAuthority wakeTargetIdentity
            let wakeTargets = DiagJson.NativeWakeContinuationTargets.rawText wakeTargetsId
            let wakeCount = DiagJson.NativeWakeContinuationTargets.bindingCount wakeTargetsId
            let wakeBindingStateId = proofTupleWakeBindingStateId wakeAuthority wakeTargetIdentity
            let wakeBindingState = wakeBindingStateId |> proofTupleWakeBindingStateText
            let wakeFate = wakeBindingStateId |> proofTupleWakeFateText
            let wakeRepairId = proofTupleWakeRepairActionFor wakeBindingStateId (wakeCount > 0)
            let wakeRepair = proofTupleWakeRepairActionText wakeRepairId
            let wakeGraph = proofTupleWakeGraphText wakeAuthority wakeTargetKey
            let wakeProbe = proofTupleWakeTopologicalDisconnectProbeText wakeAuthority wakeTargetIdentity
            let parentJobBindMaterializationId = proofTupleParentJobBindMaterializationFor wakeAuthority wakeBindingStateId
            let parentJobBindMaterializationText = proofTupleParentJobBindMaterializationText parentJobBindMaterializationId
            let parentJobBindWakeConsumerText = "Job.bind(" + wakeTargets + ")->" + wakePromiseId
            let parentJobBindGraftContractText = proofTupleParentJobBindContractText parentJobBindMaterializationId (proofTupleWakeTopologyEdgeText wakeAuthority wakeTargetKey) wakeTargets wakePromiseId
            let parentJobBindExecutionId = proofTupleParentJobBindExecutionFor parentJobBindMaterializationId
            let parentJobBindExecutionText = proofTupleParentJobBindExecutionText parentJobBindExecutionId
            let parentJobBindExecutionClosureText = proofTupleParentJobBindExecutionClosureText parentJobBindExecutionId wakeTargets wakePromiseId
            let parentJobBindRecyclePolicyText = proofTupleParentJobBindRecyclePolicyText parentJobBindExecutionId
            let parentJobBindGraftStatusId = proofTupleParentJobBindGraftStatusFor wakeBindingStateId parentJobBindExecutionId
            let parentJobBindGraftStatusText = proofTupleParentJobBindGraftStatusText parentJobBindGraftStatusId
            let wakeExpectedDeltaId = proofTupleExpectedDeltaFor wakeTargetsId wakeBindingStateId
            let wakeExpectedDeltaText = proofTupleExpectedDeltaText wakeExpectedDeltaId
            let wakeExpectedDeltaFlag = wakeExpectedDeltaId <> ProofTupleWakeExpectedDeltaNone
            let continuationTargetStatusId = proofTupleContinuationTargetStatusFor wakeTargetsId
            let continuationTargetStatusText = proofTupleContinuationTargetStatusText continuationTargetStatusId
            let wakeConsumerDeltaResultId =
                proofTupleWakeConsumerDeltaResultFor parentJobBindExecutionId wakeExpectedDeltaId continuationTargetStatusId
            let wakeConsumerDeltaResultText = DiagJson.nativeWakeConsumerDeltaResultText wakeConsumerDeltaResultId
            let crossKindObligationDetailId =
                proofTupleCrossKindObligationDetailFor wakeExpectedDeltaId continuationTargetStatusId parentJobBindGraftStatusId
            let crossKindObligationDetailText = DiagJson.nativeCrossKindObligationDetailText crossKindObligationDetailId
            let nativeDirectEvaluationContractId =
                match wakeExpectedDeltaId with
                | ProofTupleWakeExpectedDeltaApplySpineStore -> DiagJson.NativeDirectEvaluationApplySpineStore
                | ProofTupleWakeExpectedDeltaPendingGraphTerminal -> DiagJson.NativeDirectEvaluationPendingGraphTerminal
                | ProofTupleWakeExpectedDeltaPendingGraphCommittedTerminal -> DiagJson.NativeDirectEvaluationPendingGraphCommittedTerminal
                | ProofTupleWakeExpectedDeltaCooperativeReplayNativeBind -> DiagJson.NativeDirectEvaluationCooperativeReplayNativeBind
                | ProofTupleWakeExpectedDeltaParentReplayStatusPreservedCacheHandoff -> DiagJson.NativeDirectEvaluationParentReplayStatusPreservedCacheHandoff
                | ProofTupleWakeExpectedDeltaIdleCrossKindSidecarCallback -> DiagJson.NativeDirectEvaluationIdleCrossKindSidecarCallback
                | ProofTupleWakeExpectedDeltaDynamicJoinStackFenceBridge -> DiagJson.NativeDirectEvaluationDynamicJoinStackFenceBridge
                | ProofTupleWakeExpectedDeltaDynamicJoinBridgeTailHandoff -> DiagJson.NativeDirectEvaluationDynamicJoinBridgeTailHandoff
                | ProofTupleWakeExpectedDeltaObservedPinnedImmediateFill -> DiagJson.NativeDirectEvaluationObservedPinnedImmediateFill
                | ProofTupleWakeExpectedDeltaSemanticStaleRetarget -> DiagJson.NativeDirectEvaluationSemanticStaleRetarget
                | ProofTupleWakeExpectedDeltaDynamicBridge -> DiagJson.NativeDirectEvaluationDynamicBridge
                | ProofTupleWakeExpectedDeltaDynamicJoinReplay -> DiagJson.NativeDirectEvaluationDynamicJoinApply
                | ProofTupleWakeExpectedDeltaWriterlessQueueDrain -> DiagJson.NativeDirectEvaluationWriterlessQueueDrain
                | ProofTupleWakeExpectedDeltaObservedPinnedTerminal -> DiagJson.NativeDirectEvaluationObservedPinnedTerminal
                | ProofTupleWakeExpectedDeltaParentReplayCycleBreak -> DiagJson.NativeDirectEvaluationParentReplayCycleBreak
                | ProofTupleWakeExpectedDeltaParentContinuation -> DiagJson.NativeDirectEvaluationParentContinuation
                | ProofTupleWakeExpectedDeltaSidecarDrain -> DiagJson.NativeDirectEvaluationTySidecarDrain
                | ProofTupleWakeExpectedDeltaCrossKindSibling -> DiagJson.NativeDirectEvaluationCrossKindSidecar
                | ProofTupleWakeExpectedDeltaGraftRepair -> DiagJson.NativeDirectEvaluationDynamicJoinApply
                | ProofTupleWakeExpectedDeltaNone -> DiagJson.NativeDirectEvaluationNoContract
            let nativeDirectEvaluationContractText = DiagJson.nativeDirectEvaluationContractText nativeDirectEvaluationContractId
            let noWorkAbortOverrideReasonText = if wakeExpectedDeltaFlag then "bound_wake_expected_delta" else "proof_tuple_complete_recycle_not_abort"
            let payloadProbeText = "payload=" + tuple.witness.payload + "|witness=" + terminalWitnessKindText tuple.witness.kind + "|edge=" + proofTupleWakeTopologyEdgeText wakeAuthority wakeTargetKey
            let resolutionPayloadEnvelopeId =
                proofTupleResolutionPayloadEnvelopeFor wakeAuthority tuple.witness.payload
            let resolutionPayloadEnvelopeText =
                proofTupleResolutionPayloadEnvelopeText resolutionPayloadEnvelopeId
            let algebraicPayloadTraceText = "InjectedPayload=" + resolutionPayloadEnvelopeText + "|ivar=" + wakeNodeId + "|unblocks=" + wakeTargets
            let topologicalResolutionTracerText = "[" + wakeNodeId + "]->emits " + resolutionPayloadEnvelopeText + "->unblocks " + wakeTargets + "->consumer=" + wakeConsumerDeltaResultText
            let metronomeKillSwitchText = if wakeCount > 0 then "Suppressed(Native Consumers Attached)" else "Armed(Unbound Topological Island)"
            let proofTupleCarrier = ProofTupleCarrier.witness wakeNodeId ProofTupleParentContinuationNode payloadProbeText
            let proofTupleCarrierWitnessText = ProofTupleCarrier.extractWitness proofTupleCarrier
            let proofTupleCompositeReplayId = ProofTupleCompositeReplay(wakeNodeId, [ ProofTupleChildParentContinuation(wakeTargetKey, nativeDirectEvaluationContractText) ])
            let proofTupleCompositeReplayText = proofTupleCompositeReplayId |> proofTupleCompositeReplayText
            let semanticPlateauClosureKindId = DiagJson.nativeDirectEvaluationSemanticPlateauKind nativeDirectEvaluationContractId
            let executableContinuationGraphOwnsZeroFact =
                wakeCount > 0
                && wakeBindingStateId = ProofTupleWakeBoundParentContinuationTargets
                && continuationTargetStatusId <> ProofTupleTargetPoisoned
            let boundWakeZeroFactDeferral =
                executableContinuationGraphOwnsZeroFact
            let semanticPlateauDirectEval =
                (witnessForcesPlateauPoison || Option.isSome semanticPlateauClosureKindId)
                && not boundWakeZeroFactDeferral
            let zeroFactWakeDispositionText =
                if boundWakeZeroFactDeferral then
                    "BoundWakeZeroFact(DeferredToExecutableContinuationGraph|listeners=" + string wakeCount + "|binding=" + wakeBindingState + ")"
                elif semanticPlateauDirectEval then
                    "BoundWakeZeroFact(FailPlateauPoison|listeners=" + string wakeCount + "|binding=" + wakeBindingState + ")"
                else
                    "BoundWakeZeroFact(ObserverOnly|listeners=" + string wakeCount + "|binding=" + wakeBindingState + ")"
            let nativeCallbackControlFlowGateText =
                if boundWakeZeroFactDeferral then
                    "proof_tuple_complete->bound_executable_continuation_graph_owns_zero_fact_deferral->Job.bind_existing_parent_continuation->legacy_unreachable"
                else nativeCallbackControlFlowGateText
            let semanticPlateauKindText =
                match semanticPlateauClosureKindId with
                | Some kind -> DiagJson.nativeClosureKindText kind
                | None -> "witness_forced_plateau"
            let semanticPlateauPayloadText =
                "PlateauPoison(contract=" + nativeDirectEvaluationContractText + "|kind=" + semanticPlateauKindText + "|reason=job_bind_returned_native_promise_result_without_semantic_fact|target=" + continuationTargetStatusText + "|expected=" + wakeExpectedDeltaText + ")"
            let proofTupleCallbackExecutionPlanText =
                if boundWakeZeroFactDeferral then "plan_defer_zero_fact_to_bound_continuation_graph(contract=" + nativeDirectEvaluationContractText + "|listeners=" + string wakeCount + "|next=Job.bind_existing_parent_continuation)"
                elif semanticPlateauDirectEval then "plan_return_plateau_poison(contract=" + nativeDirectEvaluationContractText + "|payload=" + resolutionPayloadEnvelopeText + "|shape=bound_wake_graph_no_semantic_fact)"
                elif wakeExpectedDeltaFlag then ProofTupleCallbackPlanExecuteDirectAstEval(wakeExpectedDeltaId, proofTupleCompositeReplayId) |> proofTupleCallbackExecutionPlanText
                elif parentJobBindGraftStatusId = ProofTupleParentJobBindGraftPendingForceReplay then ProofTupleCallbackPlanForceGraftRepair proofTupleCompositeReplayId |> proofTupleCallbackExecutionPlanText
                elif continuationTargetStatusId = ProofTupleTargetPoisoned then ProofTupleCallbackPlanRejectLegacyReturn proofTupleCarrierWitnessText |> proofTupleCallbackExecutionPlanText
                else ProofTupleCallbackPlanRecycleOnly proofTupleCarrierWitnessText |> proofTupleCallbackExecutionPlanText
            let wakeTopologyEdgeText = proofTupleWakeTopologyEdgeText wakeAuthority wakeTargetKey
            let structuralCycleDetectorId =
                if boundWakeZeroFactDeferral then ProofTupleStructuralBoundWakeZeroFactDeferred(wakeNodeId, wakeTopologyEdgeText, wakeCount)
                elif semanticPlateauDirectEval && wakeExpectedDeltaFlag then ProofTupleStructuralDirectWakeReentryPlateau(wakeNodeId, wakeTopologyEdgeText, semanticPlateauPayloadText)
                elif wakeAuthority = ProofTupleWakeParentReplayCycleBreakPoison then ProofTupleStructuralLocalizedCyclePoison(wakeNodeId, wakeTopologyEdgeText, resolutionPayloadEnvelopeText)
                elif wakeExpectedDeltaFlag && DiagJson.NativeWakeContinuationTargets.hasAny [ DiagJson.NativeWakeContinuationParentContinuationCell; DiagJson.NativeWakeContinuationCrossKindSiblingReplay ] wakeTargetsId then ProofTupleStructuralDirectWakeReentry(wakeNodeId, wakeTopologyEdgeText)
                elif tuple.shadowTimeoutMs <= 0 && wakeExpectedDeltaFlag then ProofTupleStructuralShadowTimerDeprecated
                else ProofTupleStructuralNoCycle
            let structuralCycleDetectorText = proofTupleStructuralCycleText structuralCycleDetectorId
            let proofTupleAstEvaluationDeltaResultId =
                if boundWakeZeroFactDeferral then
                    DiagJson.NativeAstDeltaExecutePureAstStep nativeDirectEvaluationContractId
                elif semanticPlateauDirectEval then
                    match semanticPlateauClosureKindId with
                    | Some kind -> DiagJson.NativeAstDeltaSemanticPlateauPoison(nativeDirectEvaluationContractId, kind, DiagJson.NativeSemanticPlateauProofTupleJobBindReturnedPromiseWithoutFact)
                    | None -> DiagJson.NativeAstDeltaCyclePoisonInjected semanticPlateauPayloadText
                else
                    match wakeConsumerDeltaResultId with
                    | DiagJson.NativeWakeConsumerDeltaPureAstStep
                    | DiagJson.NativeWakeConsumerDeltaForcedDirectEval -> DiagJson.NativeAstDeltaExecutePureAstStep nativeDirectEvaluationContractId
                    | DiagJson.NativeWakeConsumerDeltaPoisonOnly
                    | DiagJson.NativeWakeConsumerDeltaTopologicalResolution -> DiagJson.NativeAstDeltaCyclePoisonInjected resolutionPayloadEnvelopeText
                    | DiagJson.NativeWakeConsumerDeltaExpectedButDeferred -> DiagJson.NativeAstDeltaBlockedLegacyFallback nativeDirectEvaluationContractId
                    | DiagJson.NativeWakeConsumerDeltaProduced
                    | DiagJson.NativeWakeConsumerDeltaNotExpected ->
                        if wakeExpectedDeltaFlag then DiagJson.NativeAstDeltaBlockedLegacyFallback nativeDirectEvaluationContractId
                        else DiagJson.NativeAstDeltaNoContractLegacyForbidden
            let astEvaluationDeltaResultText = DiagJson.nativeAstEvaluationDeltaResultText proofTupleAstEvaluationDeltaResultId
            let proofTupleAstEvaluationFailed =
                match proofTupleAstEvaluationDeltaResultId with
                | DiagJson.NativeAstDeltaCyclePoisonInjected _
                | DiagJson.NativeAstDeltaSemanticPlateauPoison _ -> true
                | _ -> false
            let proofTupleConsumerExecutionResultId = DiagJson.nativeConsumerExecutionResultFor proofTupleAstEvaluationDeltaResultId 0L
            let deltaProducedByConsumerExecution =
                match proofTupleConsumerExecutionResultId with
                | DiagJson.NativeConsumerAstDelta _ -> true
                | _ -> false
            let noFurtherDeltaDeclarationText =
                match proofTupleConsumerExecutionResultId with
                | DiagJson.NativeConsumerPlateauPoisonReturned _
                | DiagJson.NativeConsumerPromiseFailedPoison _ -> "NoFurtherDeltaPossible(after_native_promise_failed_payload=" + astEvaluationDeltaResultText + ")"
                | DiagJson.NativeConsumerAstDelta _ -> "NoFurtherDeltaPossible(after_consumer_delta_or_cycle_payload)"
                | DiagJson.NativeConsumerNoFurtherDeltaPossible reason -> "NoFurtherDeltaPossible(reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
                | DiagJson.NativeConsumerNoFurtherNoEffect _ when boundWakeZeroFactDeferral -> "DeferredDelta(bound_executable_continuation_graph_owns_next_attempt)"
                | _ -> "unsafe_no_further_delta_missing_consumer_delta(contract=" + nativeDirectEvaluationContractText + ")"
            let proofTupleConsumerExecutionResultText = DiagJson.nativeConsumerExecutionResultText proofTupleConsumerExecutionResultId
            let proofTupleMonadicPoisonTraceText = DiagJson.nativeMonadicPoisonPropagationFor wakePromiseId ("Job.bind(" + wakePromiseId + ")") proofTupleAstEvaluationDeltaResultId |> DiagJson.nativeMonadicPoisonPropagationText
            let proofTupleFailedAstFactText =
                if boundWakeZeroFactDeferral then
                    "DeferredFact(kind=" + semanticPlateauKindText + "|contract=" + nativeDirectEvaluationContractText + "|reason=bound_executable_continuation_graph_owns_next_attempt)"
                else
                    DiagJson.nativeFailedAstFactText nativeDirectEvaluationContractId 0L (continuationTargetStatusText + "|witness=" + terminalWitnessKindText tuple.witness.kind)
            let proofTupleNoFurtherRootCauseText =
                if boundWakeZeroFactDeferral then "ExecutableContinuationGraphDeferredZeroFact"
                else DiagJson.nativeNoFurtherDeltaRootCauseText proofTupleAstEvaluationDeltaResultId
            let proofTupleNativePromiseOutcomeId = DiagJson.nativePromiseOutcomeFor wakePromiseId proofTupleAstEvaluationDeltaResultId 0L
            // JSON/HUD projection is pure.  Only execution/commit paths may close
            // the process-wide native-promise latch.
            let proofTupleNativePromiseOutcomeText = DiagJson.nativePromiseOutcomeText proofTupleNativePromiseOutcomeId
            let proofTupleBeforeStateText = "PromiseBound(closure=" + wakeNodeId + "|promise=" + wakePromiseId + ")"
            let proofTupleAfterStateText = proofTupleNativePromiseOutcomeText
            let proofTupleStateTransitionText = DiagJson.nativePromiseOutcomeTransitionText wakeNodeId proofTupleBeforeStateText proofTupleNativePromiseOutcomeId
            let proofTupleLedgerAdvanceText = DiagJson.nativePromiseOutcomeLedgerAdvanceText proofTupleNativePromiseOutcomeId
            let proofTupleParentOutcomeText =
