                | DiagJson.NativeConsumerPromiseFailedPoison _ -> "NativePromiseFailed"
                | DiagJson.NativeConsumerAstDelta facts -> "DeltaProduced(count=" + string facts + ")"
                | DiagJson.NativeConsumerNoFurtherNoEffect _ when boundWakeZeroFactDeferral -> "DeferredToBoundContinuationGraph"
                | DiagJson.NativeConsumerNoFurtherNoEffect _ -> "NoFurtherDeltaPossible(no_semantic_fact_no_native_promise_success)"
                | DiagJson.NativeConsumerObserverOnlyGrace -> "ObserverOnlyGrace"
                | DiagJson.NativeConsumerNoFurtherDeltaPossible _ -> "NoFurtherDeltaPossible"
            let expectedVsActualDeltaAfterForcedConsumerText = "expected=" + wakeExpectedDeltaText + "|consumer=" + wakeConsumerDeltaResultText + "|actual=" + astEvaluationDeltaResultText + "|poison_trace=" + proofTupleMonadicPoisonTraceText
            let pureAstStepDependencyBlockerText =
                if deltaProducedByConsumerExecution then "none_consumer_closed_by_ast_delta_or_cycle_poison"
                elif proofTupleStructuralCycleIsDirectWakeReentry structuralCycleDetectorId then "await_missing_dependency_ivar_or_inject_cycle_poison_before_requeue"
                elif wakeExpectedDeltaFlag then "awaiting_dependency_for_" + nativeDirectEvaluationContractText
                else "none_no_direct_ast_eval_contract"
            let algebraicCyclePoisonPayloadText =
                if proofTupleStructuralCycleIsDirectWakeReentry structuralCycleDetectorId || proofTupleResolutionPayloadIsCyclePoison resolutionPayloadEnvelopeId then resolutionPayloadEnvelopeText
                else "not_required_unless_direct_wake_reentry_returns_zero_delta"
            let promiseResolutionLatticeText = "IVar(" + wakePromiseId + ") filled_with=" + resolutionPayloadEnvelopeText + " -> unblocks=" + wakeTargets + " -> ast_delta=" + astEvaluationDeltaResultText
            let nativeCallStackHopacText = "[Job.bind:" + continuationTargetStatusText + "]->[" + nativeDirectEvaluationContractText + "]->[" + astEvaluationDeltaResultText + "]"
            let causalityChainText = "fill(" + wakeNodeId + ")->" + continuationTargetStatusText + "->consumer=" + wakeConsumerDeltaResultText + "->expected=" + wakeExpectedDeltaText + "->actual=" + astEvaluationDeltaResultText + "->no_further=" + noFurtherDeltaDeclarationText + "->graft=" + parentJobBindGraftStatusText + "->contract=" + nativeDirectEvaluationContractText + "->plan=" + proofTupleCallbackExecutionPlanText + "->cycle=" + structuralCycleDetectorText
            FastRuntimeFormat.format ",\"hopac_ivar_registry_id\":%s,\"hopac_ivar_resolution_edge\":%s,\"witness_type\":%s,\"cycle_root_origin\":%s,\"terminal_commit_class_du\":%s,\"pending_graph_mailbox_batch_summary\":%s,\"terminal_witness_envelope_du\":%s,\"parent_continuation_fill_strategy_du\":%s,\"qap_authority_du\":%s,\"legacy_veto_quarantine_du\":%s,\"raw_key_deprecated\":%b,\"proof_tuple_complete\":%b,\"native_hopac_alt_timeout_ms\":%d,\"shadow_timeout_bypassed_by_witness\":%b,\"proof_tuple_matrix_du\":%s,\"native_hopac_promise_state_du\":%s,\"hot_row_recycle_policy_du\":%s,\"critical_path_du\":%s,\"repeat_cap_authority_du\":\"observer_only_after_witness_tuple\",\"witness_clear_readiness_gate_du\":%s,\"native_hopac_callback_route_du\":%s,\"eval_worklist_hud_frontier_authority_du\":\"quarantined_after_typed_proof_tuple\",\"deprecated_polling_fields_du\":%s,\"proof_tuple_critical_path_node_du\":%s,\"proof_tuple_authority_decision_du\":%s,\"proof_tuple_compact_projection_du\":%s,\"proof_tuple_authority_stack_du\":%s,\"native_callback_commitment_du\":%s,\"compact_observer_envelope_du\":%s,\"proof_tuple_authority_closure_du\":%s,\"hot_row_authority_projection_du\":%s,\"native_inline_callback_cutover_du\":%s,\"legacy_observer_topology_du\":%s,\"witness_routing_lattice_du\":%s,\"commit_pathway_trace_du\":%s,\"native_promise_identifier_du\":%s,\"worker_return_topology_du\":%s,\"native_run_queue_commit_du\":%s,\"proof_tuple_execution_closure_du\":%s,\"active_native_callback_closure_du\":%s,\"native_callback_control_flow_gate_du\":%s,\"callback_tracer_du\":%s,\"native_hopac_ivar_memory_identity_du\":%s,\"native_hopac_promise_id\":%s,\"continuation_binding_targets_du\":%s,\"continuation_binding_target_count\":%d,\"parent_job_bind_materialization_du\":%s,\"parent_job_bind_wake_consumer_du\":%s,\"parent_job_bind_graft_contract_du\":%s,\"parent_job_bind_execution_du\":%s,\"parent_job_bind_execution_closure_du\":%s,\"parent_job_bind_jsonl_recycle_policy_du\":%s,\"parent_job_bind_graft_status_du\":%s,\"expected_work_delta_from_wake_graph\":%b,\"wake_graph_expected_delta_du\":%s,\"continuation_target_status_du\":%s,\"wake_consumer_delta_result_du\":%s,\"consumer_execution_result_du\":%s,\"semantic_fact_count_produced_by_this_consumer\":0,\"plateau_poison_injection_reason_du\":%s,\"no_further_delta_root_cause_du\":%s,\"parent_job_bind_execution_outcome_du\":%s,\"ledger_advance_result_du\":%s,\"native_promise_outcome_du\":%s,\"state_transition_du\":%s,\"before_state_du\":%s,\"after_state_du\":%s,\"monadic_poison_propagation_trace\":%s,\"failed_ast_fact_du\":%s,\"delta_produced_by_consumer_execution\":%b,\"ast_evaluation_delta_result_du\":%s,\"no_further_delta_declaration_du\":%s,\"expected_vs_actual_delta_after_forced_consumer_du\":%s,\"pure_ast_step_dependency_blocker\":%s,\"algebraic_cycle_poison_payload\":%s,\"cycle_break_algebraic_payload_du\":%s,\"promise_resolution_lattice_du\":%s,\"native_call_stack_hopac_du\":%s,\"cross_kind_obligation_detail_du\":%s,\"sidecar_vs_continuation_cell_parity_du\":\"typed_cross_kind_obligation_owns_sidecar_parent_cell_parity\",\"continuation_cell_vs_sidecar_drain_du\":\"native_callback_direct_eval_precedes_shadow_timeout\",\"native_direct_evaluation_contract_du\":%s,\"no_work_abort_override_reason_du\":%s,\"resolution_payload_probe_du\":%s,\"resolution_payload_envelope_du\":%s,\"algebraic_payload_trace_du\":%s,\"topological_resolution_tracer_du\":%s,\"structural_cycle_detector_du\":%s,\"shadow_timeout_authority_du\":\"observer_only_after_structural_cycle_detector\",\"metronome_kill_switch_du\":%s,\"proof_tuple_carrier_witness_du\":%s,\"proof_tuple_composite_replay_du\":%s,\"proof_tuple_callback_execution_plan_du\":%s,\"wake_graph_causality_chain_du\":%s,\"wake_binding_repair_action_du\":%s,\"wake_graph_du\":%s,\"wake_graph_binding_state_du\":%s,\"wake_graph_native_fate_du\":%s,\"topological_disconnect_probe_du\":%s,\"thread_fate_du\":\"native_hopac_run_queue_after_inline_callback\",\"eval_worklist_boundary_reachable_after_callback\":false,\"legacy_polling_metrics_observer_only\":true,\"qap_observer_policy_du\":\"observer_only_after_proof_tuple_complete\",\"eval_worklist_hud_frontier_yield_path_du\":\"topologically_severed_after_proof_tuple\",\"legacy_live_tail_veto_reachable\":false" [| box (DiagJson.esc (nativeHopacIvarRegistryText tuple.witness.ivar)); box (DiagJson.esc (nativeHopacIvarRegistryText tuple.witness.ivar + "->" + terminalCommitClassText tuple.commitClass)); box (DiagJson.esc (terminalWitnessKindText tuple.witness.kind)); box (DiagJson.esc tuple.witness.cycleRootOrigin); box (DiagJson.esc (terminalCommitClassText tuple.commitClass)); box (DiagJson.esc (pendingGraphMailboxBatchSummaryText tuple.mailboxBatch)); box (DiagJson.esc (terminalWitnessEnvelopeText tuple.witness)); box (DiagJson.esc (parentContinuationFillStrategyText tuple.fillStrategy)); box (DiagJson.esc (qapAuthorityText tuple.qapAuthority)); box (DiagJson.esc (legacyVetoQuarantineText tuple.legacyVeto)); box tuple.rawKeyDeprecated; box (pendingGraphProofTupleComplete tuple); box tuple.shadowTimeoutMs; box (pendingGraphProofTupleComplete tuple && (tuple.shadowTimeoutMs = 0)); box (DiagJson.esc ("PROOF TUPLE: complete | witness=" + terminalWitnessKindText tuple.witness.kind + " | route=IVar.fill | legacy=unreachable | recycle=emit_once_then_compact")); box (DiagJson.esc (nativeHopacPromiseStateText matrix.promiseState)); box (DiagJson.esc (hotRowRecyclePolicyText matrix.recyclePolicy)); box (DiagJson.esc (proofTupleCriticalPathText tuple)); box (DiagJson.esc readinessGateText); box (DiagJson.esc callbackRouteText); box (DiagJson.esc deprecatedPollingText); box (DiagJson.esc criticalNodeText); box (DiagJson.esc (proofTupleAuthorityDecisionText authorityDecision)); box (DiagJson.esc (proofTupleCompactProjectionText compactProjection)); box (DiagJson.esc "typed_proof>native_callback>compact_badge; legacy_observer=unreachable_after_complete_tuple"); box (DiagJson.esc (nativeCallbackCommitmentText callbackCommitment)); box (DiagJson.esc (compactObserverEnvelopeText compactEnvelope)); box (DiagJson.esc authorityClosure); box (DiagJson.esc hotProjectionText); box (DiagJson.esc (nativeInlineCallbackCutoverText inlineCutover)); box (DiagJson.esc (legacyObserverTopologyText legacyTopology)); box (DiagJson.esc (witnessRoutingLatticeText witnessRoutingLattice)); box (DiagJson.esc (nativeCallbackCommitmentText callbackCommitment)); box (DiagJson.esc (nativePromiseIdentifierText nativePromiseIdentifier)); box (DiagJson.esc (workerReturnTopologyText workerReturnTopology)); box (DiagJson.esc (nativeRunQueueCommitText nativeRunQueueCommit)); box (DiagJson.esc (proofTupleExecutionClosureText executionClosure)); box (DiagJson.esc (activeNativeCallbackClosureText activeClosure)); box (DiagJson.esc nativeCallbackControlFlowGateText); box (DiagJson.esc (nativeCallbackCommitmentText callbackCommitment)); box (DiagJson.esc wakeNodeId); box (DiagJson.esc wakePromiseId); box (DiagJson.esc wakeTargets); box wakeCount; box (DiagJson.esc parentJobBindMaterializationText); box (DiagJson.esc parentJobBindWakeConsumerText); box (DiagJson.esc parentJobBindGraftContractText); box (DiagJson.esc parentJobBindExecutionText); box (DiagJson.esc parentJobBindExecutionClosureText); box (DiagJson.esc parentJobBindRecyclePolicyText); box (DiagJson.esc parentJobBindGraftStatusText); box wakeExpectedDeltaFlag; box (DiagJson.esc wakeExpectedDeltaText); box (DiagJson.esc continuationTargetStatusText); box (DiagJson.esc wakeConsumerDeltaResultText); box (DiagJson.esc proofTupleConsumerExecutionResultText); box (DiagJson.esc (if boundWakeZeroFactDeferral then zeroFactWakeDispositionText elif semanticPlateauDirectEval then "NoSemanticFactInAlgebraicPayload" elif proofTupleAstEvaluationFailed then "CyclePoisonPayload" else "not_injected")); box (DiagJson.esc proofTupleNoFurtherRootCauseText); box (DiagJson.esc proofTupleParentOutcomeText); box (DiagJson.esc proofTupleLedgerAdvanceText); box (DiagJson.esc proofTupleNativePromiseOutcomeText); box (DiagJson.esc proofTupleStateTransitionText); box (DiagJson.esc proofTupleBeforeStateText); box (DiagJson.esc proofTupleAfterStateText); box (DiagJson.esc proofTupleMonadicPoisonTraceText); box (DiagJson.esc proofTupleFailedAstFactText); box deltaProducedByConsumerExecution; box (DiagJson.esc astEvaluationDeltaResultText); box (DiagJson.esc noFurtherDeltaDeclarationText); box (DiagJson.esc expectedVsActualDeltaAfterForcedConsumerText); box (DiagJson.esc pureAstStepDependencyBlockerText); box (DiagJson.esc algebraicCyclePoisonPayloadText); box (DiagJson.esc (if proofTupleResolutionPayloadIsCyclePoison resolutionPayloadEnvelopeId then resolutionPayloadEnvelopeText else structuralCycleDetectorText + "|payload=" + resolutionPayloadEnvelopeText)); box (DiagJson.esc promiseResolutionLatticeText); box (DiagJson.esc nativeCallStackHopacText); box (DiagJson.esc crossKindObligationDetailText); box (DiagJson.esc nativeDirectEvaluationContractText); box (DiagJson.esc noWorkAbortOverrideReasonText); box (DiagJson.esc payloadProbeText); box (DiagJson.esc resolutionPayloadEnvelopeText); box (DiagJson.esc algebraicPayloadTraceText); box (DiagJson.esc topologicalResolutionTracerText); box (DiagJson.esc structuralCycleDetectorText); box (DiagJson.esc metronomeKillSwitchText); box (DiagJson.esc proofTupleCarrierWitnessText); box (DiagJson.esc proofTupleCompositeReplayText); box (DiagJson.esc proofTupleCallbackExecutionPlanText); box (DiagJson.esc causalityChainText); box (DiagJson.esc wakeRepair); box (DiagJson.esc wakeGraph); box (DiagJson.esc wakeBindingState); box (DiagJson.esc wakeFate); box (DiagJson.esc wakeProbe) |]

        let witnessClearBypassesShadowTimeout tuple =
            pendingGraphProofTupleComplete tuple && (tuple.shadowTimeoutMs = 0)

        type EvalCell<'State,'Kind> = private {
            nodeId: NodeId<'Kind>
            payload: string
            witness: TerminalWitnessEnvelope option
            }

        module EvalCellOps =
            let unresolved nodeId payload : EvalCell<EvalCellUnresolved,'Kind> =
                { nodeId = nodeId; payload = payload; witness = None }

            let provideWitness witness (cell: EvalCell<EvalCellUnresolved,'Kind>) : EvalCell<EvalCellWitnessed,'Kind> =
                { nodeId = cell.nodeId; payload = cell.payload; witness = Some witness }

            let clear (cell: EvalCell<EvalCellWitnessed,'Kind>) : EvalCell<EvalCellCleared,'Kind> =
                { nodeId = cell.nodeId; payload = cell.payload; witness = cell.witness }

            // MIGRATION: a plateaued cell is a typed terminal state, not a value
            // that can be accidentally fed back through the native wake path.
            let plateauPoison (cell: EvalCell<EvalCellWitnessed,'Kind>) : EvalCell<EvalCellPlateaued,'Kind> =
                { nodeId = cell.nodeId; payload = cell.payload + "|PlateauPoison(closure_cycle_counter_threshold_reached)"; witness = cell.witness }

            let plateauPoisonText (cell: EvalCell<EvalCellPlateaued,'Kind>) = cell.payload

            // MIGRATION: encode the assessment's phantom-state rule at the API edge:
            // only a cleared cell has a bind-next surface; a plateaued cell only has
            // a rejection renderer, so accidental re-entry has no typed helper.
            let bindNextText (cell: EvalCell<EvalCellCleared,'Kind>) =
                "bindNext_allowed(node=" + string cell.nodeId + "|state=Cleared|next=await_native_semantic_fact)"

            let plateauReentryBlockedText (cell: EvalCell<EvalCellPlateaued,'Kind>) =
                "bindNext_forbidden(node=" + string cell.nodeId + "|state=Plateaued|payload=" + cell.payload + ")"

            let witnessTypeText (cell: EvalCell<_,_>) =
                match cell.witness with
                | Some witness -> terminalWitnessKindText witness.kind
                | None -> "none"

        type WitnessClearTransitionId =
            | WitnessClearNoPayload
            | WitnessClearMaterialized
            | WitnessClearWitnessed
            | WitnessClearFilledParentContinuation
            | WitnessClearLegacyVetoQuarantined

        let witnessClearTransitionText = function
            | WitnessClearNoPayload -> "Pending"
            | WitnessClearMaterialized -> "Materialized"
            | WitnessClearWitnessed -> "Witnessed"
            | WitnessClearFilledParentContinuation -> "Cleared"
            | WitnessClearLegacyVetoQuarantined -> "LegacyVetoQuarantined"

        type ReplayObligationTree<'Kind> =
            | ReplayObligationRoot
            | ReplayObligationParent of NodeId<'Kind>
            | ReplayObligationSibling of CacheKey<'Kind> * ReplayObligationTree<'Kind>

        let rec replayObligationTreeDepth = function
            | ReplayObligationRoot -> 0
            | ReplayObligationParent _ -> 1
            | ReplayObligationSibling (_, next) -> 1 + replayObligationTreeDepth next

        // MIGRATION: recursive DU obligation graph.  This is the next bridge away
        // from typed_key strings: immediate-fill, sibling bridge and cycle poison
        // are constructors, while the phantom phase keeps Pending/Witnessed/Cleared
        // lanes separated for future native Hopac Job.bind cutover.
        type ReplayPendingPhase = interface end
        type ReplayWitnessedPhase = interface end
        type ReplayClearedPhase = interface end

        type NativeReplayObligation<'Kind,'Phase> =
            | NativeImmediateFill of owner: string * child: string * ivar: NativeHopacIvarRegistryId * fill: ParentContinuationFillStrategyId
            | NativeSiblingBridge of bridge: CacheKey<'Kind> * next: NativeReplayObligation<'Kind,'Phase>
            | NativeCyclePoison of witness: TerminalWitnessEnvelope
            | NativePromiseBind of ivar: NativeHopacIvarRegistryId * next: NativeReplayObligation<'Kind,'Phase>

        let rec nativeReplayObligationDepth = function
            | NativeImmediateFill _ -> 1
            | NativeCyclePoison _ -> 1
            | NativePromiseBind (_, next) -> 1 + nativeReplayObligationDepth next
            | NativeSiblingBridge (_, next) -> 1 + nativeReplayObligationDepth next

        let nativeReplayObligationText obligation =
            sprintf "native_replay_obligation_depth=%d" (nativeReplayObligationDepth obligation)

        // MIGRATION: make the proof tuple an authority gate, not just a set of
        // JSON fields.  A complete tuple routes directly to a native Hopac callback
        // contract and explicitly demotes repeat caps, probation drains and HUD
        // frontier polling to observation-only.
        type ProofTupleAuthorityGateId =
            | ProofTupleAuthorityMissingWitness
            | ProofTupleAuthorityWitnessReady
            | ProofTupleAuthorityIvarFillReady
            | ProofTupleAuthorityLegacyBypassed
            | ProofTupleAuthorityHudPollingQuarantined

        let proofTupleAuthorityGateText = function
            | ProofTupleAuthorityMissingWitness -> "missing_witness"
            | ProofTupleAuthorityWitnessReady -> "witness_ready"
            | ProofTupleAuthorityIvarFillReady -> "ivar_fill_ready"
            | ProofTupleAuthorityLegacyBypassed -> "legacy_probation_bypassed"
            | ProofTupleAuthorityHudPollingQuarantined -> "eval_worklist_hud_frontier_quarantined"

        type NativeHopacCallbackRouteId =
            | NativeCallbackRouteNone
            | NativeCallbackRouteIvarFill of NativeHopacIvarRegistryId * ParentContinuationFillStrategyId
            | NativeCallbackRouteJobBindPromise of NativeHopacIvarRegistryId
            | NativeCallbackRouteCyclePoisonPromise of NativeHopacIvarRegistryId

        let nativeHopacCallbackRouteText = function
            | NativeCallbackRouteNone -> "none"
            | NativeCallbackRouteIvarFill (ivar,fill) -> "IVar.fill(" + nativeHopacIvarRegistryText ivar + "," + parentContinuationFillStrategyText fill + ")"
            | NativeCallbackRouteJobBindPromise ivar -> "Job.bind(Promise(" + nativeHopacIvarRegistryText ivar + "))"
            | NativeCallbackRouteCyclePoisonPromise ivar -> "CyclePoisonPromise(" + nativeHopacIvarRegistryText ivar + ")"

        type PollingFieldDeprecationId =
            | PollingFieldsRetainedForFirstFullEmission
            | PollingFieldsCompactAfterWitness
            | PollingFieldsRecycleQapRecentAndTermAge
            | PollingFieldsDropLegacyLiveTailAfterTuple

        let pollingFieldDeprecationText = function
            | PollingFieldsRetainedForFirstFullEmission -> "retain_full_fields_for_first_emission"
            | PollingFieldsCompactAfterWitness -> "compact_polling_fields_after_witness"
            | PollingFieldsRecycleQapRecentAndTermAge -> "recycle_qap_recent_sample_term_age_delta_replay"
            | PollingFieldsDropLegacyLiveTailAfterTuple -> "drop_legacy_live_tail_veto_after_tuple"

        let proofTupleAuthorityGateFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then ProofTupleAuthorityIvarFillReady
            else ProofTupleAuthorityWitnessReady

        let nativeHopacCallbackRouteFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then NativeCallbackRouteIvarFill (tuple.witness.ivar, tuple.fillStrategy)
            else NativeCallbackRouteJobBindPromise tuple.witness.ivar

        let pollingFieldDeprecationFor (tuple: PendingGraphProofTuple) =
            match tuple.witness.kind with
            | WitnessParentReplayCycleBreakPoisonImmediateFillProof
            | WitnessCrossKindYieldThrashHardPoisonProof
            | WitnessHardPoisonObligationCapProof
            | WitnessParentReplayStatusPreservedCacheHandoffProof
            | WitnessCooperativeReplayNativeBindProof
            | WitnessSemanticStaleRetargetProof
            | WitnessTyGlobalFuseParentContinuationProof
            | WitnessIdleCrossKindSidecarDrainProof
            | WitnessJoinWaitDriverPromiseProof -> PollingFieldsRecycleQapRecentAndTermAge
            | WitnessMetronomeTerminalAuthorityProof -> PollingFieldsCompactAfterWitness
            | _ -> PollingFieldsRetainedForFirstFullEmission

        type ProofTupleCriticalPathNode = {
            payload: string
            witness: TerminalWitnessKindId
            ivar: NativeHopacIvarRegistryId
            callback: NativeHopacCallbackRouteId
            gate: ProofTupleAuthorityGateId
            recycle: PollingFieldDeprecationId
            }

        let proofTupleCriticalPathNodeFor (tuple: PendingGraphProofTuple) : ProofTupleCriticalPathNode =
            { payload = tuple.witness.payload
              witness = tuple.witness.kind
              ivar = tuple.witness.ivar
              callback = nativeHopacCallbackRouteFor tuple
              gate = proofTupleAuthorityGateFor tuple
              recycle = pollingFieldDeprecationFor tuple }

        let proofTupleCriticalPathNodeText (node: ProofTupleCriticalPathNode) =
            FastRuntimeFormat.format "payload=%s|witness=%s|ivar=%s|callback=%s|gate=%s|recycle=%s" [| box node.payload; box (terminalWitnessKindText node.witness); box (nativeHopacIvarRegistryText node.ivar); box (nativeHopacCallbackRouteText node.callback); box (proofTupleAuthorityGateText node.gate); box (pollingFieldDeprecationText node.recycle) |]

        // MIGRATION: Church-style visitor scaffold for the next migration slice.
        // The payload remains a normal F# DU-backed record today, but consumers can
        // start depending on visitor methods instead of downcasting JSON strings.
        type IProofTupleVisitor<'Result> =
            abstract VisitParentReplayPoison : PendingGraphProofTuple -> 'Result
            abstract VisitCrossKindHardPoison : PendingGraphProofTuple -> 'Result
            abstract VisitDynamicJoin : PendingGraphProofTuple -> 'Result
            abstract VisitCacheOrFuse : PendingGraphProofTuple -> 'Result
            abstract VisitGeneric : PendingGraphProofTuple -> 'Result

        type IPendingGraphProof =
            abstract Apply<'Result> : IProofTupleVisitor<'Result> -> 'Result

        type PendingGraphProofBox(tuple: PendingGraphProofTuple) =
            member _.Tuple = tuple
            interface IPendingGraphProof with
                member _.Apply<'Result>(visitor: IProofTupleVisitor<'Result>) =
                    match tuple.witness.kind with
                    | WitnessParentReplayCycleBreakPoisonImmediateFillProof -> visitor.VisitParentReplayPoison tuple
                    | WitnessCrossKindYieldThrashHardPoisonProof -> visitor.VisitCrossKindHardPoison tuple
                    | WitnessDynamicJoinSymbolicCarrierProof
                    | WitnessDynamicJoinCooperativeAltTimeoutProof
                    | WitnessDynamicJoinBridgeTailProof -> visitor.VisitDynamicJoin tuple
                    | WitnessParentCacheHandoffWakeProof
                    | WitnessParentReplayStatusPreservedCacheHandoffProof
                    | WitnessCooperativeReplayNativeBindProof
                    | WitnessTyGlobalFuseParentContinuationProof -> visitor.VisitCacheOrFuse tuple
                    | _ -> visitor.VisitGeneric tuple

        // MIGRATION: native-Hopac promise registry scaffold for the assessment HUD.
        // This gives the bottom HUD a typed source for the "top oldest unresolved IVars"
        // idea instead of rebuilding it from q/a/p strings.  It is still inert/shadow-only,
        // but every parent-continuation cycle row can now name the promise it would fill.
        type LivePromiseRegistrySlot<'Kind> = {
            slot: int
            ivar: NativeHopacIvarRegistryId
            obligation: ReplayObligationTree<'Kind>
            ageMs: int64
            awaitKind: string
            }

        type DeadlockDependencyEdge<'Kind> = {
            waiter: NodeId<'Kind>
            parent: NodeId<'Kind>
            reason: CompilerKernelV2.OperationalReasonId
            fillStrategy: ParentContinuationFillStrategyId
            }

        let livePromiseRegistrySlotText slot =
            FastRuntimeFormat.format "slot=%d|ivar=%s|obligation_depth=%d|age_ms=%d|await=%s" [| box slot.slot; box (nativeHopacIvarRegistryText slot.ivar); box (replayObligationTreeDepth slot.obligation); box slot.ageMs; box slot.awaitKind |]

        let deadlockDependencyEdgeText edge =
            FastRuntimeFormat.format "waiter=%s<-parent=%s|reason=%s|fill=%s" [| box (nodeIdText edge.waiter); box (nodeIdText edge.parent); box (CompilerKernelV2.OperationalReasonIdOps.text edge.reason); box (parentContinuationFillStrategyText edge.fillStrategy) |]

        // MIGRATION: first assessment-migration slice.  These DUs make the cooperative-yield
        // and cross-kind continuation frontiers explicit without promoting primary Hopac or
        // fabricating writer/root/BuildOk witnesses.  Future rounds can replace HUD strings
        // with these values at the source of the scheduler decisions.
        type CooperativeYieldHandoffId =
            | CooperativeYieldHandoffNone
            | CooperativeYieldHandoffTermToTy
            | CooperativeYieldHandoffTyToTermOrParent
            | CooperativeYieldHandoffSameNodePingPong
        let cooperativeYieldHandoffText = function
            | CooperativeYieldHandoffNone -> "none"
            | CooperativeYieldHandoffTermToTy -> "term_to_ty"
            | CooperativeYieldHandoffTyToTermOrParent -> "ty_to_term_or_parent"
            | CooperativeYieldHandoffSameNodePingPong -> "same_node_ping_pong"
