        let proofTupleForMaterializedTerminal outcome key =
            match outcome with
            | MaterializedTerminalIfUnknownReturnConditionTailPierce -> proofTupleForIfUnknownReturn key
            | MaterializedTerminalParentContinuationImmediateFill -> proofTupleForParentContinuationImmediateFill key
            | MaterializedTerminalSemanticStaleRetargetShadowTimeoutPierce -> proofTupleForSemanticStaleRetargetImmediateFill key
            | MaterializedTerminalShadowTimeoutStaleRetargetPierce -> proofTupleForSemanticStaleRetargetImmediateFill key
            | MaterializedTerminalObservedPinnedTerminalImmediateFill -> proofTupleForObservedPinnedImmediateFill key
            | MaterializedTerminalDynamicJoinSymbolicCarrierReplay -> proofTupleForDynamicJoinSymbolicCarrier key
            | MaterializedTerminalDynamicJoinCooperativeAltTimeout -> proofTupleForDynamicJoinCooperativeAltTimeout key
            | MaterializedTerminalDynamicJoinBridgeTailHandoff -> proofTupleForDynamicJoinBridgeTail key
            | MaterializedTerminalIdleCrossKindSidecarDrain -> proofTupleForIdleCrossKindSidecarDrain key
            | MaterializedTerminalIdleCrossKindTerminalCommit -> proofTupleForIdleCrossKindTerminalCommit key
            | MaterializedTerminalDynamicRecordKeyBridgeCommit -> proofTupleForDynamicRecordKeyBridgeCommit key
            | MaterializedTerminalParentReplayPoisonLiveTail -> proofTupleForParentReplayPoisonLiveTail key
            | MaterializedTerminalParentReplayCycleBreakPoisonImmediateFill -> proofTupleForParentReplayCycleBreakPoisonImmediateFill key
            | MaterializedTerminalCrossKindYieldThrashHardPoison -> proofTupleForCrossKindYieldThrashHardPoison key
            | MaterializedTerminalHardPoisonObligationCapImmediateFill -> proofTupleForHardPoisonObligationCapImmediateFill key
            | MaterializedTerminalParentCacheHandoffWake -> proofTupleForParentCacheHandoffWake key
            | MaterializedTerminalParentReplayStatusPreservedCacheHandoff -> proofTupleForParentReplayStatusPreservedCacheHandoff key
            | MaterializedTerminalCooperativeReplayNativeBind -> proofTupleForCooperativeReplayNativeBind key
            | MaterializedTerminalTyGlobalFuseParentContinuation -> proofTupleForTyGlobalFuseParentContinuation key
            | MaterializedTerminalReentryPrefetchTerminalDriver -> proofTupleForReentryPrefetchTerminalDriver key
            | MaterializedTerminalJoinWaitDriverPromise -> proofTupleForJoinWaitDriverPromise key
            | MaterializedTerminalNoRootBudgetParentReplayImmediateFill -> proofTupleForNoRootBudgetParentReplayImmediateFill key
            | MaterializedTerminalObservedPinnedTerminalContract -> proofTupleForObservedPinnedImmediateFill key
            | MaterializedTerminalMetronomeObservedPinnedAuthority -> proofTupleForObservedPinnedImmediateFill key
            | _ -> proofTupleForParentContinuationImmediateFill key

        type ReplayTickProofSignalId =
            | ReplayTickProofAppRootBase16
            | ReplayTickProofRootWitnessFinalizationSelfLoop
            | ReplayTickProofLiveReplayLivelock
            | ReplayTickProofStaleRetarget
            | ReplayTickProofParentReplayStatusPreservedRepeat
            | ReplayTickProofCacheHandoff
            | ReplayTickProofCooperativeReplayHandoff
            | ReplayTickProofCacheWriteParentHandoff
            | ReplayTickProofPostCommitParentQueueDriverTick
            | ReplayTickProofNoRootBudget
            | ReplayTickProofBigStackNoRootBudget
            | ReplayTickProofMaterializedTerminalBeatsNoRootBudget
            | ReplayTickProofJoinWait
            | ReplayTickProofTermReentryPrefetch
            | ReplayTickProofTyReentryPrefetch
            | ReplayTickProofReentryPrefetch
            | ReplayTickProofReentrantReplayDriver
            | ReplayTickProofHardPoisonObligation
            | ReplayTickProofParentReplay
            | ReplayTickProofPoison
            | ReplayTickProofDynamicJoin
            | ReplayTickProofDynamicRecordKeyBridge
            | ReplayTickProofBridgeTail
            | ReplayTickProofIdleCrossKind
            | ReplayTickProofActiveTySidecar

        let private replayTickProofSignalsOfFacts (facts:Set<DiagnosticClassifier.DiagnosticFactId>) =
            [ if Set.contains DiagnosticClassifier.DiagnosticReplayAppRootBase16 facts then ReplayTickProofAppRootBase16
              if Set.contains DiagnosticClassifier.DiagnosticReplayRootWitnessFinalizationSelfLoop facts then ReplayTickProofRootWitnessFinalizationSelfLoop
              if Set.contains DiagnosticClassifier.DiagnosticReplayLiveLivelock facts then ReplayTickProofLiveReplayLivelock
              if Set.contains DiagnosticClassifier.DiagnosticReplayStaleRetarget facts then ReplayTickProofStaleRetarget
              if Set.contains DiagnosticClassifier.DiagnosticReplayParentStatusPreservedRepeat facts then ReplayTickProofParentReplayStatusPreservedRepeat
              if Set.contains DiagnosticClassifier.DiagnosticReplayCacheHandoff facts then ReplayTickProofCacheHandoff
              if Set.contains DiagnosticClassifier.DiagnosticReplayCooperativeHandoff facts then ReplayTickProofCooperativeReplayHandoff
              if Set.contains DiagnosticClassifier.DiagnosticReplayCacheWriteParentHandoff facts then ReplayTickProofCacheWriteParentHandoff
              if Set.contains DiagnosticClassifier.DiagnosticReplayPostCommitParentQueueDriverTick facts then ReplayTickProofPostCommitParentQueueDriverTick
              if Set.contains DiagnosticClassifier.DiagnosticReplayNoRootBudget facts then ReplayTickProofNoRootBudget
              if Set.contains DiagnosticClassifier.DiagnosticReplayBigStackNoRootBudget facts then ReplayTickProofBigStackNoRootBudget
              if Set.contains DiagnosticClassifier.DiagnosticReplayMaterializedTerminalBeatsNoRootBudget facts then ReplayTickProofMaterializedTerminalBeatsNoRootBudget
              if Set.contains DiagnosticClassifier.DiagnosticReplayJoinWait facts then ReplayTickProofJoinWait
              if Set.contains DiagnosticClassifier.DiagnosticReplayTermReentryPrefetch facts then ReplayTickProofTermReentryPrefetch
              if Set.contains DiagnosticClassifier.DiagnosticReplayTyReentryPrefetch facts then ReplayTickProofTyReentryPrefetch
              if Set.contains DiagnosticClassifier.DiagnosticReplayReentryPrefetch facts then ReplayTickProofReentryPrefetch
              if Set.contains DiagnosticClassifier.DiagnosticReentrantReplayDriver facts then ReplayTickProofReentrantReplayDriver
              if Set.contains DiagnosticClassifier.DiagnosticReplayHardPoisonObligation facts then ReplayTickProofHardPoisonObligation
              if Set.contains DiagnosticClassifier.DiagnosticReplayParentReplay facts then ReplayTickProofParentReplay
              if Set.contains DiagnosticClassifier.DiagnosticReplayPoison facts then ReplayTickProofPoison
              if Set.contains DiagnosticClassifier.DiagnosticReplayDynamicJoin facts then ReplayTickProofDynamicJoin
              if Set.contains DiagnosticClassifier.DiagnosticReplayDynamicRecordKeyBridge facts then ReplayTickProofDynamicRecordKeyBridge
              if Set.contains DiagnosticClassifier.DiagnosticReplayBridgeTail facts then ReplayTickProofBridgeTail
              if Set.contains DiagnosticClassifier.DiagnosticReplayIdleCrossKind facts then ReplayTickProofIdleCrossKind
              if Set.contains DiagnosticClassifier.DiagnosticReplayActiveTySidecar facts then ReplayTickProofActiveTySidecar ]
            |> Set.ofList

        let private replayTickProofTupleForFacts (eventText:string) (reasonText:string) (eventFacts:Set<DiagnosticClassifier.DiagnosticFactId>) (reasonFacts:Set<DiagnosticClassifier.DiagnosticFactId>) =
            let eventLower = if System.Object.ReferenceEquals(eventText, null) then "" else eventText.ToLowerInvariant()
            let reasonLower = if System.Object.ReferenceEquals(reasonText, null) then "" else reasonText.ToLowerInvariant()
            let eventSignals = replayTickProofSignalsOfFacts eventFacts
            let reasonSignals = replayTickProofSignalsOfFacts reasonFacts
            let eventHas signal = Set.contains signal eventSignals
            let reasonHas signal = Set.contains signal reasonSignals
            let stableKey = "replay_tick:" + eventLower + ":" + reasonLower
            if eventHas ReplayTickProofAppRootBase16
               || reasonHas ReplayTickProofAppRootBase16
               || reasonHas ReplayTickProofRootWitnessFinalizationSelfLoop
               || reasonHas ReplayTickProofLiveReplayLivelock
               || reasonHas ReplayTickProofStaleRetarget then
                Some (proofTupleForSemanticStaleRetargetImmediateFill stableKey)
            elif reasonHas ReplayTickProofParentReplayStatusPreservedRepeat
                 && reasonHas ReplayTickProofCacheHandoff then
                Some (proofTupleForParentReplayStatusPreservedCacheHandoff stableKey)
            elif eventHas ReplayTickProofCooperativeReplayHandoff
                 || reasonHas ReplayTickProofCooperativeReplayHandoff then
                Some (proofTupleForCooperativeReplayNativeBind stableKey)
            elif eventHas ReplayTickProofCacheWriteParentHandoff
                 || reasonHas ReplayTickProofPostCommitParentQueueDriverTick then
                Some (proofTupleForParentCacheHandoffWake stableKey)
            elif eventHas ReplayTickProofNoRootBudget
                 || reasonHas ReplayTickProofNoRootBudget
                 || eventHas ReplayTickProofBigStackNoRootBudget
                 || reasonHas ReplayTickProofMaterializedTerminalBeatsNoRootBudget then
                Some (proofTupleForNoRootBudgetParentReplayImmediateFill stableKey)
            elif eventHas ReplayTickProofJoinWait || reasonHas ReplayTickProofJoinWait then
                Some (proofTupleForJoinWaitDriverPromise stableKey)
            elif eventHas ReplayTickProofTermReentryPrefetch
                 || eventHas ReplayTickProofTyReentryPrefetch
                 || reasonHas ReplayTickProofReentryPrefetch
                 || reasonHas ReplayTickProofReentrantReplayDriver then
                Some (proofTupleForReentryPrefetchTerminalDriver stableKey)
            elif reasonHas ReplayTickProofHardPoisonObligation then
                Some (proofTupleForHardPoisonObligationCapImmediateFill stableKey)
            elif reasonHas ReplayTickProofParentReplayStatusPreservedRepeat
                 || reasonHas ReplayTickProofParentReplay
                 || reasonHas ReplayTickProofPoison then
                Some (proofTupleForParentReplayCycleBreakPoisonImmediateFill stableKey)
            elif reasonHas ReplayTickProofDynamicJoin then
                Some (proofTupleForDynamicJoinSymbolicCarrier stableKey)
            elif reasonHas ReplayTickProofDynamicRecordKeyBridge
                 || reasonHas ReplayTickProofBridgeTail then
                Some (proofTupleForDynamicRecordKeyBridgeCommit stableKey)
            elif reasonHas ReplayTickProofIdleCrossKind
                 || reasonHas ReplayTickProofActiveTySidecar then
                Some (proofTupleForIdleCrossKindSidecarDrain stableKey)
            else None

        let replayTickProofTupleFor (eventText:string) (reasonText:string) =
            replayTickProofTupleForFacts
                eventText
                reasonText
                (DiagnosticClassifier.classifyFacts eventText)
                (DiagnosticClassifier.classifyFacts reasonText)

        let replayTickProofTupleJsonFields (eventText: string) (reasonText: string) =
            match replayTickProofTupleFor eventText reasonText with
            | Some tuple -> pendingGraphProofTupleJsonFields tuple
            | None -> ""

        // A pure function of the two texts, computed on every replay tick (it classifies both texts: ~4% of a
        // slow compile); memoized, with a bounded cache.
        let private replayTickProofCompactCache =
            System.Collections.Concurrent.ConcurrentDictionary<struct (string * string), string>()

        let rec replayTickProofTupleCompactJsonFields (eventText: string) (reasonText: string) =
            let key = struct (eventText, reasonText)
            let mutable cached = null
            if replayTickProofCompactCache.TryGetValue(key, &cached) then cached
            else
                let fields = replayTickProofTupleCompactJsonFieldsUncached eventText reasonText
                if replayTickProofCompactCache.Count < 4096 then replayTickProofCompactCache.TryAdd(key, fields) |> ignore
                fields

        and private replayTickProofTupleCompactJsonFieldsUncached (eventText: string) (reasonText: string) =
            match replayTickProofTupleFor eventText reasonText with
            | Some tuple ->
                let compactText =
                    "PendingGraphProofTuple(witness=" + terminalWitnessKindText tuple.witness.kind
                    + "|ivar=" + nativeHopacIvarRegistryText tuple.witness.ivar
                    + "|commit=" + terminalCommitClassText tuple.commitClass
                    + "|complete=" + string (pendingGraphProofTupleComplete tuple)
                    + "|shadow_timeout_ms=" + string tuple.shadowTimeoutMs + ")"
                sprintf ",\"pending_graph_proof_compact_du\":%s,\"jsonl_compaction_du\":\"ReplayTickProofCompact|full_proof_fields_suppressed\",\"proof_tuple_projection_purity_du\":\"ProjectionOnlyNoTerminalLatchMutation\""
                    (esc compactText)
            | None -> ""

        let pendingGraphProofTupleOptionJsonFields (tupleOpt: PendingGraphProofTuple option) =
            match tupleOpt with
            | Some tuple -> pendingGraphProofTupleJsonFields tuple
            | None -> ""

        let pendingGraphProofTupleOptionComplete (tupleOpt: PendingGraphProofTuple option) =
            match tupleOpt with
            | Some tuple -> pendingGraphProofTupleComplete tuple
            | None -> false

        type AuthorityWinnerId =
            | AuthorityWinnerLegacyStillValid
            | AuthorityWinnerShadowAltTimeoutStackFence
            | AuthorityWinnerShadowAltTimeoutIfUnknownReturn
            | AuthorityWinnerShadowAltTimeoutIfUnknownReturnAbsentSidecar
            | AuthorityWinnerShadowAltTimeoutParentReplayCycleBreak
            | AuthorityWinnerShadowAltTimeoutSemanticStaleRetarget
            | AuthorityWinnerShadowAltTimeoutDynamicRecordKeyBridgeTail
            | AuthorityWinnerShadowAltTimeoutParentContinuationDeferredChild
            | AuthorityWinnerLedgerIdentityPanic
            | AuthorityWinnerNoWinner
        let authorityWinnerText = function
            | AuthorityWinnerLegacyStillValid -> "legacy_still_valid"
            | AuthorityWinnerShadowAltTimeoutStackFence -> "shadow_alt_timeout_stack_fence"
            | AuthorityWinnerShadowAltTimeoutIfUnknownReturn -> "shadow_alt_timeout_if_unknown_return"
            | AuthorityWinnerShadowAltTimeoutIfUnknownReturnAbsentSidecar -> "shadow_alt_timeout_if_unknown_return_absent_sidecar"
            | AuthorityWinnerShadowAltTimeoutParentReplayCycleBreak -> "shadow_alt_timeout_parent_replay_cycle_break_poison"
            | AuthorityWinnerShadowAltTimeoutSemanticStaleRetarget -> "shadow_alt_timeout_semantic_stale_retarget"
            | AuthorityWinnerShadowAltTimeoutDynamicRecordKeyBridgeTail -> "shadow_alt_timeout_dynamic_record_key_bridge_tail"
            | AuthorityWinnerShadowAltTimeoutParentContinuationDeferredChild -> "shadow_alt_timeout_parent_continuation_deferred_child"
            | AuthorityWinnerLedgerIdentityPanic -> "ledger_identity_panic"
            | AuthorityWinnerNoWinner -> "none"
        type BlockerHierarchyId =
            | BlockerHierarchyShadowAltOverLegacyStackFence
            | BlockerHierarchyShadowAltOverIfUnknownReturn
            | BlockerHierarchyShadowAltOverIfUnknownReturnAbsentSidecar
            | BlockerHierarchyShadowAltOverParentReplayCycleBreak
            | BlockerHierarchyShadowAltOverSemanticStaleRetarget
            | BlockerHierarchyShadowAltOverDynamicRecordKeyBridgeTail
            | BlockerHierarchyShadowAltOverParentContinuationDeferredChild
            | BlockerHierarchyLedgerOverSidecar
            | BlockerHierarchyLegacyOnly
            | BlockerHierarchyNone
        let blockerHierarchyText = function
            | BlockerHierarchyShadowAltOverLegacyStackFence -> "shadow_alt_timeout > blocked_repeat_cap_before_stack_fence_yield > physical_qap"
            | BlockerHierarchyShadowAltOverIfUnknownReturn -> "shadow_alt_timeout > if_unknown_return_repeat_cap > physical_queue"
            | BlockerHierarchyShadowAltOverIfUnknownReturnAbsentSidecar -> "shadow_alt_timeout > if_unknown_return_absent_sidecar > legacy_repeat_cap_or_quarantine_tail"
            | BlockerHierarchyShadowAltOverParentReplayCycleBreak -> "shadow_alt_timeout > parent_replay_cycle_break_poison > repeat_cap_probation_drain > physical_qap"
            | BlockerHierarchyShadowAltOverSemanticStaleRetarget -> "shadow_alt_timeout > semantic_stale_retarget > missing_prefetch_cycle_break > stale_root_retarget"
            | BlockerHierarchyShadowAltOverDynamicRecordKeyBridgeTail -> "shadow_alt_timeout > dynamic_record_key_bridge_tail > weak_pending_active_root > physical_qap"
            | BlockerHierarchyShadowAltOverParentContinuationDeferredChild -> "shadow_alt_timeout > parent_continuation_deferred_child > bridge_tail > ty_sidecar_prefetch_grace"
            | BlockerHierarchyLedgerOverSidecar -> "ledger_identity_panic > sidecar_prefetch > live_tail"
            | BlockerHierarchyLegacyOnly -> "legacy_only_no_shadow_breach"
            | BlockerHierarchyNone -> "none"
        type IfUnknownReturnConditionObligationId =
            | IfUnknownReturnNotCurrent
            | IfUnknownReturnBranchProbeRequired
            | IfUnknownReturnPhysicalQueueDrainBeforeTerminal
            | IfUnknownReturnShadowTimeoutPiercesRepeatCap
            | IfUnknownReturnAbsentSidecarShadowTimeoutPiercesRepeatCap
        let ifUnknownReturnConditionObligationText = function
            | IfUnknownReturnNotCurrent -> "not_if_unknown_return"
            | IfUnknownReturnBranchProbeRequired -> "if_unknown_return_branch_probe_required"
            | IfUnknownReturnPhysicalQueueDrainBeforeTerminal -> "if_unknown_return_physical_queue_drain_before_terminal"
            | IfUnknownReturnShadowTimeoutPiercesRepeatCap -> "if_unknown_return_shadow_timeout_pierces_repeat_cap"
            | IfUnknownReturnAbsentSidecarShadowTimeoutPiercesRepeatCap -> "if_unknown_return_absent_sidecar_shadow_timeout_pierces_repeat_cap"
        let cacheKeyText = function
            | CacheKeyFromReplayCell (NodeId nodeId, site) -> sprintf "node:%d@%s" nodeId (ReplayCacheSiteIdOps.text site)
            | CacheKeyFromRaw key when RawCacheKeyIdOps.text key = "-1" -> "[ERASED_IDENTITY]"
            | CacheKeyFromRaw key -> RawCacheKeyIdOps.text key
            | CacheKeyErasedIdentity site -> "[ERASED_IDENTITY:" + CacheErasureSiteIdOps.text site + "]"
            | CacheKeyMissing -> "missing"
        [<StructuralEquality; NoComparison>]
        type ReplayCellTransitionStatusId =
            | ReplayCellSemanticValueResolved
            | ReplayCellSemanticLeafValueResolved
            | ReplayCellParentContinuationCycleBlocked
            | ReplayCellTypeVariableValueMissingBlocked
            | ReplayCellParentContinuationDispatched
            | ReplayCellApplyHeadDispatched
            | ReplayCellApplyArgDispatched
            | ReplayCellLetBodyDispatched
            | ReplayCellLetSuccessDispatched
            | ReplayCellOpArgDispatched
            | ReplayCellSeqFirstDispatched
            | ReplayCellSeqSecondDispatched
            | ReplayCellPairLeftDispatched
            | ReplayCellPairRightDispatched
            | ReplayCellTypeTermTermDispatched
            | ReplayCellTypeFunArgDispatched
            | ReplayCellTypeFunBodyDispatched
            | ReplayCellTypePairLeftDispatched
            | ReplayCellTypePairRightDispatched
            | ReplayCellIfBranchDispatched
            | ReplayCellSemanticStepDispatched

        [<StructuralEquality; NoComparison>]
        type ReplayCellCommitStatusId =
            | ReplayCellCommitRootComplete
            | ReplayCellCommitLeafComplete
            | ReplayCellCommitParentContinuationCycleBlocked
            | ReplayCellCommitTypeVariableValueMissingBlocked
            | ReplayCellCommitOther

