        let private evalKindOfString (kind: string) =
            match kind with
            | "term" -> EvalTerm
            | "ty" -> EvalTy
            | "data" -> EvalData
            | "codegen" -> EvalCodegen
            | "dynamic_join" -> EvalDynamicJoin
            | "parent"
            | "parent_resume" -> EvalParentResume
            | other -> EvalUnknown(CompilerKernelV2.OperationalReasonIdOps.create other)

        let private evalKindToString kind =
            match kind with
            | EvalTerm -> "term"
            | EvalTy -> "ty"
            | EvalData -> "data"
            | EvalCodegen -> "codegen"
            | EvalDynamicJoin -> "dynamic_join"
            | EvalParentResume -> "parent"
            | EvalUnknown reasonId -> CompilerKernelV2.OperationalReasonIdOps.text reasonId

        let private deferredReplayKindForEvalKind = function
            | EvalTerm -> EvalReplayValueStore.DeferredReplayTerm
            | EvalTy -> EvalReplayValueStore.DeferredReplayTy
            | EvalData -> EvalReplayValueStore.DeferredReplayData
            | EvalCodegen -> EvalReplayValueStore.DeferredReplayCodegen
            | EvalDynamicJoin -> EvalReplayValueStore.DeferredReplayDynamicJoin
            | EvalParentResume -> EvalReplayValueStore.DeferredReplayParentResume
            | EvalUnknown reasonId -> EvalReplayValueStore.DeferredReplayOther reasonId

        let private evalKindForDeferredReplayKind = function
            | EvalReplayValueStore.DeferredReplayTerm -> EvalTerm
            | EvalReplayValueStore.DeferredReplayTy -> EvalTy
            | EvalReplayValueStore.DeferredReplayData -> EvalData
            | EvalReplayValueStore.DeferredReplayCodegen -> EvalCodegen
            | EvalReplayValueStore.DeferredReplayDynamicJoin -> EvalDynamicJoin
            | EvalReplayValueStore.DeferredReplayParentResume -> EvalParentResume
            | EvalReplayValueStore.DeferredReplayOther reasonId -> EvalUnknown reasonId

        let private evaluatorNodeKindForEvalKind = function
            | EvalTerm -> EvalReplayValueStore.EvaluatorTermNode
            | EvalTy -> EvalReplayValueStore.EvaluatorTypeNode
            | EvalData -> EvalReplayValueStore.EvaluatorDataReplayNode
            | EvalCodegen -> EvalReplayValueStore.EvaluatorCodegenReplayNode
            | EvalDynamicJoin -> EvalReplayValueStore.EvaluatorDynamicJoinReplayNode
            | EvalParentResume -> EvalReplayValueStore.EvaluatorParentResumeReplayNode
            | EvalUnknown reasonId -> EvalReplayValueStore.EvaluatorUnknownReplayNode reasonId

        let private evalKindForEvaluatorNodeKind = function
            | EvalReplayValueStore.EvaluatorTermNode -> EvalTerm
            | EvalReplayValueStore.EvaluatorTypeNode -> EvalTy
            | EvalReplayValueStore.EvaluatorDataReplayNode -> EvalData
            | EvalReplayValueStore.EvaluatorCodegenReplayNode -> EvalCodegen
            | EvalReplayValueStore.EvaluatorDynamicJoinReplayNode -> EvalDynamicJoin
            | EvalReplayValueStore.EvaluatorParentResumeReplayNode -> EvalParentResume
            | EvalReplayValueStore.EvaluatorMetaNode -> EvalUnknown (CompilerKernelV2.OperationalReasonIdOps.create "meta")
            | EvalReplayValueStore.EvaluatorClosureNode -> EvalUnknown (CompilerKernelV2.OperationalReasonIdOps.create "closure")
            | EvalReplayValueStore.EvaluatorUnknownReplayNode reasonId -> EvalUnknown reasonId

