            | ReplayCellSemanticStatus SemanticPairLeftReady -> ReplayCellReadyPairLeft
            | ReplayCellSemanticStatus SemanticSelectedFrontierStepperReady -> ReplayCellReadySelectedFrontierStepper
            | _ -> ReplayCellReadyOther

        let private replayCellTransitionStatusForIds commitStatusId currentStatusId =
            match commitStatusId with
            | ReplayCellCommitRootComplete -> ReplayCellSemanticValueResolved
            | ReplayCellCommitLeafComplete -> ReplayCellSemanticLeafValueResolved
            | ReplayCellCommitParentContinuationCycleBlocked -> ReplayCellParentContinuationCycleBlocked
            | ReplayCellCommitTypeVariableValueMissingBlocked -> ReplayCellTypeVariableValueMissingBlocked
            | ReplayCellCommitOther ->
                match currentStatusId with
                | ReplayCellReadyParentContinuation -> ReplayCellParentContinuationDispatched
                | ReplayCellReadyApplyHead -> ReplayCellApplyHeadDispatched
                | ReplayCellReadyApplyArg -> ReplayCellApplyArgDispatched
                | ReplayCellReadyLetBody -> ReplayCellLetBodyDispatched
                | ReplayCellReadyLetSuccess -> ReplayCellLetSuccessDispatched
                | ReplayCellReadyOpArg -> ReplayCellOpArgDispatched
                | ReplayCellReadySeqFirst -> ReplayCellSeqFirstDispatched
                | ReplayCellReadySeqSecond -> ReplayCellSeqSecondDispatched
                | ReplayCellReadyPairLeft -> ReplayCellPairLeftDispatched
                | ReplayCellReadyPairRight -> ReplayCellPairRightDispatched
                | ReplayCellReadyTypeTermTerm -> ReplayCellTypeTermTermDispatched
                | ReplayCellReadyTypeFunArg -> ReplayCellTypeFunArgDispatched
                | ReplayCellReadyTypeFunBody -> ReplayCellTypeFunBodyDispatched
                | ReplayCellReadyTypePairLeft -> ReplayCellTypePairLeftDispatched
                | ReplayCellReadyTypePairRight -> ReplayCellTypePairRightDispatched
                | ReplayCellReadyIfBranch -> ReplayCellIfBranchDispatched
                | ReplayCellReadyTypeApplyFunction
                | ReplayCellReadyTypeApplyTypeArg
                | ReplayCellReadyNominalInner
                | ReplayCellReadyNominalType
                | ReplayCellReadyAnnotInner
                | ReplayCellReadyAnnotType
                | ReplayCellReadyMacroTermChild
                | ReplayCellReadyMacroTypeChild
                | ReplayCellReadyMacroResultType
                | ReplayCellReadyDynamicFunctionBridgeBigStackBody
                | ReplayCellReadyApplyFunctionBodyDynamicLiteralTail
                | ReplayCellReadyApplyFunctionBodyDynamicDynTypecheckPairTail
                | ReplayCellReadyApplyFunctionBodyDynamicPartEvalTail
                | ReplayCellReadyDynamicRecordBridgeBigStackBody
                | ReplayCellReadyAnnotTestBody
                | ReplayCellReadyOpBody
                | ReplayCellReadyApplyFunctionBody
                | ReplayCellReadyOpTypeAwareChild
                | ReplayCellReadyUnitTestBind
                | ReplayCellReadyUnitTestBranch
                | ReplayCellReadyTypeApplyAnnotBody
                | ReplayCellReadyTypeApplyOpBody
                | ReplayCellReadyTypeApplyNominalConstructor
                | ReplayCellReadyAnnotTestBranch
                | ReplayCellReadyAnnotTestBranchProbe
                | ReplayCellReadyAnnotTestType
                | ReplayCellReadyIfTrueBranch
                | ReplayCellReadyIfFalseBranch
                | ReplayCellReadyIfUnknownReturnBranchProbe
                | ReplayCellReadyIfSymbolicConditionBranchProbe
                | ReplayCellReadyIfCondition
                | ReplayCellReadyRecordWithChild
                | ReplayCellReadyPairTestBranch
                | ReplayCellReadyUnboxChild _
                | ReplayCellReadyAnnotNullDeferredChild
                | ReplayCellReadyJoinpointLiveDeferredChild
                | ReplayCellReadyDeferredTyChild
                | ReplayCellReadyTjoinpointBody
                | ReplayCellReadySelectedFrontierStepper
                | ReplayCellReadyOther -> ReplayCellSemanticStepDispatched

        let termCacheKeyFromCell (cell: ReplayCell option) (fallbackKey: string) =
            match cell with
            | Some c -> CacheKeyFromReplayCell ((NodeId c.nodeId : NodeId<TermKind>), ReplayCacheSiteIdOps.create (CompilerIdentityKernel.WorkSiteIdOps.text c.site))
            | None when String.IsNullOrWhiteSpace fallbackKey -> CacheKeyMissing
            | None -> CacheKeyFromRaw (RawCacheKeyIdOps.create fallbackKey)

        type ReplayKeyKind private () =
            static member InternedKindTag () = 0x140005u
        type ReplayKeyId = CompilerIdentityKernel.InternedTextId<ReplayKeyKind>

        module ReplayKeyIdOps =
            let create value : ReplayKeyId = CompilerIdentityKernel.InternedTextId.create<ReplayKeyKind> value
            let slot (value: ReplayKeyId) = CompilerIdentityKernel.InternedTextIdOps.slot value
            let text (value: ReplayKeyId) = CompilerIdentityKernel.InternedTextIdOps.text value
            module Known =
                let empty = create ""
                let unresolved = create "replay:unresolved"

        [<StructuralEquality; NoComparison>]
        type ReplayFrameKeySignalId =
            | ReplayFrameKeyNodeIdentity
            | ReplayFrameKeySyntheticZero

        let private replayFrameKeySignalsAtIngress (key:string) =
            let safe = if System.String.IsNullOrEmpty key then "" else key
            let hasNodeIdentity = safe.Split([| '#' |], StringSplitOptions.None).Length > 1
            let hasSyntheticZero =
                safe.Split([| ':' |], StringSplitOptions.RemoveEmptyEntries)
                |> Array.exists (fun token -> token = "0")
            [ if hasNodeIdentity then ReplayFrameKeyNodeIdentity
              if hasSyntheticZero then ReplayFrameKeySyntheticZero ]

        [<StructuralEquality; NoComparison>]
        type FrameStatusId =
            | FrameReadyExplicitLoop
            | FrameTracingExplicitLoop
            | FrameContinuationEnvelope
            | FrameSemanticStepPartial
            | FrameSemanticRootComplete
            | FrameSemanticLeafComplete
            | FrameBlockedByReentry
            | FrameCaptured
            | FrameProgressYieldFrontier
            | FrameSemanticStatus of SemanticStatusId
            | FrameReplayCellStatus of ReplayCellStatusId
            | FrameUnknown of CompilerKernelV2.OperationalReasonId * Set<DiagnosticClassifier.DiagnosticFactId>

        let private frameUnknown reasonId =
            let facts =
                reasonId
                |> CompilerKernelV2.OperationalReasonIdOps.text
                |> DiagnosticClassifier.classifyFacts
            FrameUnknown(reasonId, facts)

        type ReplayPrefetchEvidenceSignalId =
            | ReplayPrefetchEvidencePresent
            | ReplayPrefetchEvidenceMissingAfterPrefetch

        let private replayPrefetchEvidenceSignalsFromFacts (facts:Set<DiagnosticClassifier.DiagnosticFactId>) =
            [ if Set.contains DiagnosticClassifier.DiagnosticReplayPrefetch facts then
                  ReplayPrefetchEvidencePresent
              if Set.contains DiagnosticClassifier.DiagnosticReplayMissingAfterPrefetch facts then
                  ReplayPrefetchEvidenceMissingAfterPrefetch ]
            |> Set.ofList

        [<StructuralEquality; StructuralComparison>]
        type FrontierSemanticPayloadFactId =
            | FrontierSemanticPayloadContinuation

        let private frontierSemanticPayloadFacts (payload:string) =
            let safe = if String.IsNullOrWhiteSpace payload then "" else payload
            let tokens =
                safe.Split(
                    [| '|'; ':'; ','; ';'; ' '; '='; '('; ')'; '['; ']'; '\n'; '\r'; '\t' |],
                    StringSplitOptions.RemoveEmptyEntries)
                |> Array.map (fun token -> token.ToLowerInvariant())
                |> Set.ofArray
            [ if Set.contains "continuation" tokens then
                  FrontierSemanticPayloadContinuation ]
            |> Set.ofList

        [<StructuralEquality; NoComparison>]
        type FrameLegacySemanticPayloadId = private {
            text: string
            diagnosticFacts: Set<DiagnosticClassifier.DiagnosticFactId>
            semanticFacts: Set<FrontierSemanticPayloadFactId>
        }

        let private frameLegacySemanticPayloadId text =
            let safe = if isNull text then "" else text
            { text = safe
              diagnosticFacts = DiagnosticClassifier.classifyFacts safe
              semanticFacts = frontierSemanticPayloadFacts safe }

        [<StructuralEquality; NoComparison>]
        type FrameCrossKindReasonId =
            | FrameCrossKindActiveReplayDriver
            | FrameCrossKindPayloadStaleRetargetObligationBypass
            | FrameCrossKindYieldThrash
            | FrameCrossKindYieldThrashHardPoisonStaleRetargetObligation
            | FrameCrossKindYieldThrashHardPoisonPostScheduleCap

        [<StructuralEquality; NoComparison>]
        type FrameReasonSignalId =
            | FrameReasonSignalOpReplayDriverNull
            | FrameReasonSignalParentReplayStatusPreservedRepeat of ReplayKeyId
            | FrameReasonSignalReentrantP0FailClosed of ReplayKeyId
            | FrameReasonSignalCrossKind of FrameCrossKindReasonId
            | FrameReasonSignalDynamicJoin of EvalReplayValueStore.DynamicJoinReasonEvidenceId
            | FrameReasonSignalMissingAfterPrefetch

        [<StructuralEquality; NoComparison>]
        type FramePayloadId =
            | FrameSemanticCellPayload of ReplayCell
            | FrameSemanticCellPayloadWithReasonSignal of ReplayCell * FrameReasonSignalId
            | FrameLegacySemanticPayload of FrameLegacySemanticPayloadId
            | FramePayloadMissing

        [<StructuralEquality; NoComparison>]
        type Frame = {
            kind: EvalKind
            key: ReplayKeyId
            keySignals: ReplayFrameKeySignalId list
            site: CompilerIdentityKernel.WorkSiteId
            depth: int
            re: int
            maxRe: int
            trace: Trace
            reason: CompilerKernelV2.OperationalReasonId
            reasonFacts: Set<DiagnosticClassifier.DiagnosticFactId>
            status: FrameStatusId
            cursor: int
            payload: FramePayloadId
        }
        with
            member this.semanticCell =
                match this.payload with
                | FrameSemanticCellPayload cell
                | FrameSemanticCellPayloadWithReasonSignal(cell, _) -> Some cell
                | _ -> None

            member this.semanticPayload =
                match this.payload with
                | FrameLegacySemanticPayload legacy when not (System.String.IsNullOrWhiteSpace legacy.text) -> Some legacy.text
                | _ -> None

        let replayCellKindText (cell: ReplayCell) = evalKindToString cell.kind
        let replayCellShapeText (cell: ReplayCell) = CompilerIdentityKernel.WorkShapeIdOps.text cell.shape
        let replayCellSiteText (cell: ReplayCell) = CompilerIdentityKernel.WorkSiteIdOps.text cell.site
        let frameKindText (frame: Frame) = evalKindToString frame.kind
        let frameSiteText (frame: Frame) = CompilerIdentityKernel.WorkSiteIdOps.text frame.site
        let frameKeyText (frame: Frame) = ReplayKeyIdOps.text frame.key

        let private framePayloadTypedCell = function
            | FrameSemanticCellPayload cell
            | FrameSemanticCellPayloadWithReasonSignal(cell, _) -> Some cell
            | _ -> None

        let private framePayloadWithReasonSignal reasonSignal cell =
            match reasonSignal with
            | Some signal -> FrameSemanticCellPayloadWithReasonSignal(cell, signal)
            | None -> FrameSemanticCellPayload cell

        let private framePayloadReasonSignal = function
            | FrameSemanticCellPayloadWithReasonSignal(_, signal) -> Some signal
            | _ -> None

        let frameReasonSignalId (frame:Frame) = framePayloadReasonSignal frame.payload

        let dynamicJoinReasonEvidenceForFrame (frame:Frame) =
            match framePayloadReasonSignal frame.payload with
            | Some (FrameReasonSignalDynamicJoin evidence) -> evidence
            | _ -> EvalReplayValueStore.dynamicJoinReasonEvidenceEmpty

        let private framePayloadLegacyText = function
            | FrameLegacySemanticPayload legacy when not (System.String.IsNullOrWhiteSpace legacy.text) -> Some legacy.text
            | _ -> None

        let private framePayloadLegacyDiagnosticFacts = function
            | FrameLegacySemanticPayload legacy -> legacy.diagnosticFacts
            | _ -> Set.empty

        let private framePayloadLegacyPrefetchEvidence payload =
            payload
            |> framePayloadLegacyDiagnosticFacts
            |> replayPrefetchEvidenceSignalsFromFacts

        let frameReasonFacts (frame:Frame) =
            Set.union frame.reasonFacts (framePayloadLegacyDiagnosticFacts frame.payload)

        let frameReasonOfString value = CompilerKernelV2.OperationalReasonIdOps.create value
        let frameReasonToString reasonId = CompilerKernelV2.OperationalReasonIdOps.text reasonId
        let private frameReasonAppend reasonId suffix =
            frameReasonOfString (frameReasonToString reasonId + suffix)

        type HotQueueNodeFocusId =
            | HotQueueNodeFocusUnknown
            | HotQueueNodeFromReplayCell of int

        let private hotQueueNodeFocusForFrame (frame: Frame) =
            match framePayloadTypedCell frame.payload with
            | Some cell -> HotQueueNodeFromReplayCell cell.nodeId
            | None -> HotQueueNodeFocusUnknown

        let private hotQueueNodeFocusValue = function
            | HotQueueNodeFromReplayCell nodeId -> nodeId
            | HotQueueNodeFocusUnknown -> -1

        [<StructuralEquality; NoComparison>]
        type ReplaySemanticPayloadStateId =
            | ReplaySemanticPayloadMissing
            | ReplaySemanticPayloadReady

        [<StructuralEquality; NoComparison>]
        type ReplayTaskPayloadId =
            | ReplayTaskSemanticCellPayload of ReplayCell
            | ReplayTaskLegacyTextPayload of text:string * state:ReplaySemanticPayloadStateId

        [<StructuralEquality; NoComparison>]
        type ReplayTaskKeyOriginId =
            | ReplayTaskKeyFrame
            | ReplayTaskKeyParent
            | ReplayTaskKeyChild
            | ReplayTaskKeyDeferredAfterActive

        let private replayTaskKeyOriginText = function
            | ReplayTaskKeyFrame -> "Frame"
            | ReplayTaskKeyParent -> "Parent"
            | ReplayTaskKeyChild -> "Child"
            | ReplayTaskKeyDeferredAfterActive -> "DeferredAfterActive"

        [<StructuralEquality; NoComparison>]
        type private ReplayTaskKeyDescriptor = {
            replayKey: ReplayKeyId
            parentNodeIds: int list
            origin: ReplayTaskKeyOriginId
            sourceKind: EvalKind option
        }

        [<StructuralEquality; NoComparison>]
        type ReplayTaskKeyId = private ReplayTaskKeyId of ReplayTaskKeyDescriptor

        module ReplayTaskKeyIdOps =
            let private safeText (text:string) =
                if System.Object.ReferenceEquals(text, null) then "" else text

            let private make origin parentNodeIds sourceKind text =
                let text = safeText text
                ReplayTaskKeyId {
                    replayKey = ReplayKeyIdOps.create text
                    parentNodeIds = parentNodeIds
                    origin = origin
                    sourceKind = sourceKind
                }

            let createParent (parentNodeId:int) (sourceKind:EvalKind) (text:string) =
                make ReplayTaskKeyParent [parentNodeId] (Some sourceKind) text

            let deriveParent (ReplayTaskKeyId parent) (parentNodeId:int) (text:string) =
                let parentNodeIds =
                    parentNodeId :: parent.parentNodeIds
                    |> List.distinct
                make ReplayTaskKeyParent parentNodeIds parent.sourceKind text

            let deriveChildText (ReplayTaskKeyId parent) (roleText:string) (nodeId:int) (step:int) =
                let childText = FastRuntimeFormat.format "%s|%s|%d|%d" [| box (ReplayKeyIdOps.text parent.replayKey); box (safeText roleText); box nodeId; box step |]
                make ReplayTaskKeyChild parent.parentNodeIds parent.sourceKind childText

            let createFrame (frame:Frame) =
                let text = FastRuntimeFormat.format "%s|%s|%s|%d|%d" [| box (evalKindToString frame.kind); box (frameKeyText frame); box (frameSiteText frame); box frame.cursor; box frame.trace.Length |]
                make ReplayTaskKeyFrame [] (Some frame.kind) text

            let createDeferredAfterActive (cell:ReplayCell) =
                let text = FastRuntimeFormat.format "deferred_after_active_driver|%s|%s|%d|%d" [| box (replayCellKindText cell); box (replayCellShapeText cell); box cell.nodeId; box cell.step |]
                make ReplayTaskKeyDeferredAfterActive [] (Some cell.kind) text

            let text (ReplayTaskKeyId key) = ReplayKeyIdOps.text key.replayKey
            let replayKey (ReplayTaskKeyId key) = key.replayKey
            let parentNodeIds (ReplayTaskKeyId key) = key.parentNodeIds
            let hasParent (ReplayTaskKeyId key) = not (List.isEmpty key.parentNodeIds)
            let origin (ReplayTaskKeyId key) = key.origin
            let sourceKind (ReplayTaskKeyId key) = key.sourceKind

        let private replayBootstrapScenarioId (taskKey:ReplayTaskKeyId) parentCellKind parentCellShape =
            match ReplayTaskKeyIdOps.sourceKind taskKey, parentCellKind with
            | Some EvalTy, EvalTerm when parentCellShape = CompilerIdentityKernel.WorkShapeIdOps.Known.eMacro ->
                ReplayBootstrapCrossKindMacroPreservation
            | _ -> ReplayBootstrapOther

        [<StructuralEquality; NoComparison>]
        type ReplayDriverId =
            | TermReplayDriver
            | TyReplayDriver
            | DynamicJoinReplayDriver
            | ParentResumeReplayDriver
            | TerminalContractReplayDriver
            | TerminalContractEmissionReplayDriver
            | CrossKindUnresolvedReplayDriver
            | UnknownReplayDriver of CompilerKernelV2.OperationalReasonId

        [<StructuralEquality; NoComparison>]
        type ReplayTaskStatusId =
            | ReplayTaskNew
            | ReplayTaskCaptured
            | ReplayTaskScheduledReplay
            | ReplayTaskScheduledParentReplay
            | ReplayTaskDriverReadyReplayCell
            | ReplayTaskDriverReadySemanticPayload
            | ReplayTaskDriverBlockedSemanticPayload
            | ReplayTaskStepperReady
            | ReplayTaskParentContinuationReady
            | ReplayTaskParentContinuationDispatched
            | ReplayTaskSemanticStepPartial
            | ReplayTaskSemanticStepDone
            | ReplayTaskSemanticRootComplete
            | ReplayTaskContinuationEnvelope
