        [<StructuralEquality; NoComparison>]
        type ReplayTaskFactId =
            | ReplayTaskFactParentKey
            | ReplayTaskFactReplayContinuation
            | ReplayTaskFactSemanticEvalPayload
            | ReplayTaskFactSemanticRootComplete
            | ReplayTaskFactTyReplayMode
            | ReplayTaskFactShapeApply
            | ReplayTaskFactShapeOp
            | ReplayTaskFactShapeTypeApply
            | ReplayTaskFactTermFunction
            | ReplayTaskFactApplyContinuationRootWitness
            | ReplayTaskFactSemanticStepPartial
            | ReplayTaskFactCaptured
            | ReplayTaskFactSemanticReplayDriverExceptionBlocked
            | ReplayTaskFactReplayDriverExceptionBlocked
            | ReplayTaskFactOpContinuationRootWitnessNullGuarded
            | ReplayTaskFactDeferredAfterActiveDriverReady
            | ReplayTaskFactParentReplayCycleBreakPoisoned

        [<StructuralEquality; NoComparison>]
        type ReplayTaskPayloadSignalId =
            | ReplayTaskPayloadReplayContinuation
            | ReplayTaskPayloadSemanticEval
            | ReplayTaskPayloadSemanticRootComplete
            | ReplayTaskPayloadTyReplayMode
            | ReplayTaskPayloadShapeApply
            | ReplayTaskPayloadShapeOp
            | ReplayTaskPayloadShapeTypeApply
            | ReplayTaskPayloadKindTerm
            | ReplayTaskPayloadShapeFunction
            | ReplayTaskPayloadApplyContinuationRootWitness
            | ReplayTaskPayloadSemanticStepPartial
            | ReplayTaskPayloadCaptured
            | ReplayTaskPayloadSemanticReplayDriverExceptionBlocked
            | ReplayTaskPayloadReplayDriverExceptionBlocked
            | ReplayTaskPayloadOpContinuationRootWitnessNullGuarded
            | ReplayTaskPayloadDeferredAfterActiveDriverReady
            | ReplayTaskPayloadParentReplayCycleBreakPoisoned
            | ReplayTaskPayloadNodeId of int

        [<StructuralEquality; NoComparison>]
        type ReplayTask = {
            id: int64
            key: ReplayTaskKeyId
            driver: ReplayDriverId
            payload: ReplayTaskPayloadId
            status: ReplayTaskStatusId
            legacyFacts: ReplayTaskFactId list
            legacyNodeIds: Set<int>
        }

        type ReplayTaskExecutionClaimDecision<'Claimed> =
            | ReplayTaskExecutionClaimed of 'Claimed
            | ReplayTaskExecutionAlreadyOwned of replayId:int64
            | ReplayTaskExecutionQueueEmpty

        // A task's work unit is a function of its key text and id, but it was rebuilt (a SHA-256 of the key
        // text) on every admit, open check and completion: ~9% of mega_lean_cic's CPU. Memoized per (id, key);
        // task records are copied on status changes, so object identity would miss.
        let private replayTaskSemanticWorkUnits =
            System.Collections.Concurrent.ConcurrentDictionary<struct (int64 * string), CompilerKernelV2.WorkUnitId<CompilerKernelV2.ReplayPhase,CompilerKernelV2.ReplayWorkKind>>()

        let private replayTaskSemanticWorkUnit (task:ReplayTask) =
            let keyText = ReplayTaskKeyIdOps.text task.key
            let memoKey = struct (task.id, keyText)
            let mutable cached = Unchecked.defaultof<_>
            if replayTaskSemanticWorkUnits.TryGetValue(memoKey, &cached) then cached
            else
                let authorityRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "replay-semantic-work"
                        (keyText + "|task=" + string task.id)
                let workUnit =
                    CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.ReplayPhase,CompilerKernelV2.ReplayWorkKind>
                        authorityRef
                        (max 1L task.id)
                if replayTaskSemanticWorkUnits.Count > 200000 then replayTaskSemanticWorkUnits.Clear()
                replayTaskSemanticWorkUnits.TryAdd(memoKey, workUnit) |> ignore
                workUnit

        let private replayTaskSemanticWorkCost : CompilerKernelV2.SemanticCost =
            CompilerKernelV2.Measured.one

        let private replayTaskSemanticAdmit (task:ReplayTask) =
            let workUnit = replayTaskSemanticWorkUnit task
            CompilerKernelV2.SemanticWorkLedgerAuthority.transact
                (CompilerKernelV2.SemanticWorkAdmit(
                    CompilerKernelV2.SomeReplayWorkUnit workUnit,
                    replayTaskSemanticWorkCost))
            |> ignore

        let private replayTaskSemanticIsOpen (task:ReplayTask) =
            let workUnit = replayTaskSemanticWorkUnit task
            CompilerKernelV2.SemanticWorkLedgerAuthority.isOpenSomeWorkUnit
                (CompilerKernelV2.SomeReplayWorkUnit workUnit)

        let private replayTaskSemanticComplete disposition (task:ReplayTask) =
            let workUnit = replayTaskSemanticWorkUnit task
            let receipt = CompilerKernelV2.WorkUnitReceipt.create workUnit disposition replayTaskSemanticWorkCost
            CompilerKernelV2.SemanticWorkLedgerAuthority.transact
                (CompilerKernelV2.SemanticWorkApply(CompilerKernelV2.SomeReplayWorkReceipt receipt))
            |> ignore

        let private replayTaskSemanticCancelForQueueReset (task:ReplayTask) =
            let workUnit = replayTaskSemanticWorkUnit task
            let cancellationRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "replay-semantic-queue-reset"
                    (ReplayTaskKeyIdOps.text task.key + "|task=" + string task.id)
            let receipt =
                CompilerKernelV2.WorkUnitReceipt.create
                    workUnit
                    (CompilerKernelV2.WorkUnitCancelled cancellationRef)
                    replayTaskSemanticWorkCost
            CompilerKernelV2.SemanticWorkLedgerAuthority.transact
                (CompilerKernelV2.SemanticWorkApply(CompilerKernelV2.SomeReplayWorkReceipt receipt))
            |> ignore

        let private replayTaskSemanticCancelQueuedForReset (tasks:ReplayTask list) =
            tasks |> List.iter replayTaskSemanticCancelForQueueReset

        let private replayTaskSemanticCell (task:ReplayTask) =
            match task.payload with
            | ReplayTaskSemanticCellPayload cell -> Some cell
            | ReplayTaskLegacyTextPayload _ -> None

        let private replayTaskSemanticPayloadState (task:ReplayTask) =
            match task.payload with
            | ReplayTaskSemanticCellPayload _ -> ReplaySemanticPayloadReady
            | ReplayTaskLegacyTextPayload(_, state) -> state

        let private replayTaskLegacyPayloadText (task:ReplayTask) =
            match task.payload with
            | ReplayTaskSemanticCellPayload _ -> ""
            | ReplayTaskLegacyTextPayload(text, _) -> text

        let private replayTaskPayloadSignalOfToken (token:string) =
            match token with
            | "replay_continuation" -> Some ReplayTaskPayloadReplayContinuation
            | "semantic_eval_payload" -> Some ReplayTaskPayloadSemanticEval
            | "semantic_root_complete" -> Some ReplayTaskPayloadSemanticRootComplete
            | "mode=ty_replay" -> Some ReplayTaskPayloadTyReplayMode
            | "shape=EApply" -> Some ReplayTaskPayloadShapeApply
            | "shape=EOp" -> Some ReplayTaskPayloadShapeOp
            | "shape=ETypeApply" -> Some ReplayTaskPayloadShapeTypeApply
            | "kind=term" -> Some ReplayTaskPayloadKindTerm
            | "shape=EFun'" -> Some ReplayTaskPayloadShapeFunction
            | "apply_continuation_root_witness" -> Some ReplayTaskPayloadApplyContinuationRootWitness
            | "status=semantic_step_partial" -> Some ReplayTaskPayloadSemanticStepPartial
            | "status=captured" -> Some ReplayTaskPayloadCaptured
            | "status=semantic_replay_driver_exception_blocked" -> Some ReplayTaskPayloadSemanticReplayDriverExceptionBlocked
            | "status=replay_driver_exception_blocked" -> Some ReplayTaskPayloadReplayDriverExceptionBlocked
            | "status=op_continuation_root_witness_null_guarded" -> Some ReplayTaskPayloadOpContinuationRootWitnessNullGuarded
            | "status=deferred_after_active_driver_ready" -> Some ReplayTaskPayloadDeferredAfterActiveDriverReady
            | "status=semantic_parent_replay_cycle_break_poisoned" -> Some ReplayTaskPayloadParentReplayCycleBreakPoisoned
            | _ ->
                let parts = token.Split([|'='|], 2, StringSplitOptions.None)
                if parts.Length = 2 && parts.[0] = "node_id" then
                    match Int32.TryParse parts.[1] with
                    | true, nodeId -> Some (ReplayTaskPayloadNodeId nodeId)
                    | _ -> None
                else None

        let private replayTaskPayloadSignalsAtIngress (payload:string) =
            let safe = if String.IsNullOrWhiteSpace payload then "" else payload
            safe.Split(
                [| '|'; ','; ';'; '('; ')'; '['; ']'; '{'; '}'; ' ' |],
                StringSplitOptions.RemoveEmptyEntries)
            |> Array.choose replayTaskPayloadSignalOfToken
            |> Array.distinct

        let private replayTaskLegacyEvidenceAtIngress payload =
            let signals = replayTaskPayloadSignalsAtIngress payload
            let has signal = Array.contains signal signals
            let facts =
                [ if has ReplayTaskPayloadReplayContinuation then ReplayTaskFactReplayContinuation
                  if has ReplayTaskPayloadSemanticEval then ReplayTaskFactSemanticEvalPayload
                  if has ReplayTaskPayloadSemanticRootComplete then ReplayTaskFactSemanticRootComplete
                  if has ReplayTaskPayloadTyReplayMode then ReplayTaskFactTyReplayMode
                  if has ReplayTaskPayloadShapeApply then ReplayTaskFactShapeApply
                  if has ReplayTaskPayloadShapeOp then ReplayTaskFactShapeOp
                  if has ReplayTaskPayloadShapeTypeApply then ReplayTaskFactShapeTypeApply
                  if has ReplayTaskPayloadKindTerm && has ReplayTaskPayloadShapeFunction then ReplayTaskFactTermFunction
                  if has ReplayTaskPayloadApplyContinuationRootWitness then ReplayTaskFactApplyContinuationRootWitness
                  if has ReplayTaskPayloadSemanticStepPartial then ReplayTaskFactSemanticStepPartial
                  if has ReplayTaskPayloadCaptured then ReplayTaskFactCaptured
                  if has ReplayTaskPayloadSemanticReplayDriverExceptionBlocked then ReplayTaskFactSemanticReplayDriverExceptionBlocked
                  if has ReplayTaskPayloadReplayDriverExceptionBlocked then ReplayTaskFactReplayDriverExceptionBlocked
                  if has ReplayTaskPayloadOpContinuationRootWitnessNullGuarded then ReplayTaskFactOpContinuationRootWitnessNullGuarded
                  if has ReplayTaskPayloadDeferredAfterActiveDriverReady then ReplayTaskFactDeferredAfterActiveDriverReady
                  if has ReplayTaskPayloadParentReplayCycleBreakPoisoned then ReplayTaskFactParentReplayCycleBreakPoisoned ]
                |> List.distinct
            let nodeIds =
                signals
                |> Array.choose (function ReplayTaskPayloadNodeId nodeId -> Some nodeId | _ -> None)
                |> Set.ofArray
            facts, nodeIds

        let private replayTaskEmptyLegacyEvidence : ReplayTaskFactId list * Set<int> =
            [], Set.empty

        let private replayTaskKeyHasParent key = ReplayTaskKeyIdOps.hasParent key

        let private replayTaskParentNodeIds key = ReplayTaskKeyIdOps.parentNodeIds key

        let private replayTaskShapeEApply = CompilerIdentityKernel.WorkShapeIdOps.create "EApply"
        let private replayTaskShapeEOp = CompilerIdentityKernel.WorkShapeIdOps.create "EOp"
        let private replayTaskShapeETypeApply = CompilerIdentityKernel.WorkShapeIdOps.create "ETypeApply"
        let private replayTaskShapeEFun = CompilerIdentityKernel.WorkShapeIdOps.create "EFun'"

        let private replayTaskFacts (task:ReplayTask) =
            match replayTaskSemanticCell task with
            | Some cell ->
                let shapeId = cell.shape
                [ if replayTaskKeyHasParent task.key then ReplayTaskFactParentKey
                  ReplayTaskFactSemanticEvalPayload
                  if cell.status = ReplayCellSemanticStatus SemanticRootComplete then ReplayTaskFactSemanticRootComplete
                  if shapeId = replayTaskShapeEApply then ReplayTaskFactShapeApply
                  if shapeId = replayTaskShapeEOp then ReplayTaskFactShapeOp
                  if shapeId = replayTaskShapeETypeApply then ReplayTaskFactShapeTypeApply
                  if cell.kind = EvalTerm && shapeId = replayTaskShapeEFun then ReplayTaskFactTermFunction
                  if cell.status = ReplayCellSemanticStatus SemanticStepPartial then ReplayTaskFactSemanticStepPartial
                  if cell.status = ReplayCellProtocolStatus ReplayCellProtocolCaptured then ReplayTaskFactCaptured
                  if cell.status = ReplayCellSemanticStatus SemanticReplayDriverExceptionBlocked then ReplayTaskFactSemanticReplayDriverExceptionBlocked
                  if cell.status = ReplayCellSemanticStatus SemanticOpContinuationRootWitnessNullGuarded then ReplayTaskFactOpContinuationRootWitnessNullGuarded
                  if cell.status = ReplayCellSemanticStatus SemanticDeferredAfterActiveDriverReady then ReplayTaskFactDeferredAfterActiveDriverReady
                  if cell.status = ReplayCellSemanticStatus SemanticParentReplayCycleBreakPoisoned then ReplayTaskFactParentReplayCycleBreakPoisoned ]
                |> List.distinct
            | None ->
                [ if replayTaskKeyHasParent task.key then ReplayTaskFactParentKey
                  yield! task.legacyFacts ]
                |> List.distinct

        let private replayTaskHasFact fact task =
            replayTaskFacts task |> List.contains fact

        [<StructuralEquality; NoComparison>]
        type ReplayTaskNodeRelationId =
            | ReplayTaskDirectNode
            | ReplayTaskParentNode

        let private replayTaskNodeRelations nodeId (task:ReplayTask) =
            let directNode =
                match replayTaskSemanticCell task with
                | Some cell -> cell.nodeId = nodeId
                | None -> Set.contains nodeId task.legacyNodeIds
            let parentNodeIds = replayTaskParentNodeIds task.key
            [ if directNode then ReplayTaskDirectNode
              if List.contains nodeId parentNodeIds then ReplayTaskParentNode ]
            |> List.distinct

        let private replayTaskReferencesNode nodeId task =
            replayTaskNodeRelations nodeId task |> List.isEmpty |> not

        type StableRootKeyFactId =
            | StableRootSemanticRootComplete
            | StableRootUnitTestComplete
            | StableRootSequenceCaptured
            | StableRootPrimitiveCaptured
            | StableRootTypeApplyComplete
            | StableRootSequenceComplete
            | StableRootFunctionCaptured

        type StableRootSiteRelationId =
            | StableRootSiteAbsent
            | StableRootSitePresent

        let stableRootSiteRelation (site:string) (value:string) =
            if String.IsNullOrWhiteSpace site
               || String.IsNullOrEmpty value
               || site.Length > value.Length then
                StableRootSiteAbsent
            else
                let mutable offset = 0
                let mutable found = false
                let lastOffset = value.Length - site.Length
                while not found && offset <= lastOffset do
                    if String.Compare(value, offset, site, 0, site.Length, StringComparison.Ordinal) = 0 then
                        found <- true
                    else
                        offset <- offset + 1
                if found then StableRootSitePresent else StableRootSiteAbsent

        let stableRootKeyContainsSite (site:CompilerIdentityKernel.WorkSiteId) value =
            match stableRootSiteRelation (CompilerIdentityKernel.WorkSiteIdOps.text site) value with
            | StableRootSitePresent -> true
            | StableRootSiteAbsent -> false

        // MIGRATION: the legacy replay/worklist records still serialize as strings so
        // old diagnostics and bundle diffs remain readable, but policy should no
        // longer branch directly on ad-hoc text.  These small closed DUs form the
        // migration seam; later rounds can move the record fields themselves once
        // all central matches are updated.
        let private replayCellEvalKindId (cell: ReplayCell) = cell.kind

