            | UnknownReplayChildRole -> ""

        let private replayTaskChildKey parentKey role nodeId step =
            ReplayTaskKeyIdOps.deriveChildText parentKey (replayChildRoleToString role) nodeId step

        let private cellKindOfEvalKind = function
            | EvalTerm -> CellTerm
            | EvalTy -> CellTy
            | EvalData -> CellData
            | _ -> CellUnknownKind


        let private cellShapeByWorkShapeSlot =
            let map = System.Collections.Generic.Dictionary<int64,EvalCellShapeId>()
            let add text shapeId =
                let slot = CompilerIdentityKernel.WorkShapeIdOps.create text |> CompilerIdentityKernel.WorkShapeIdOps.slot
                map.[slot] <- shapeId
            add "EB" CellShapeEB
            add "EV" CellShapeEV
            add "ELit" CellShapeELit
            add "ESymbol" CellShapeESymbol
            add "EApply" CellShapeEApply
            add "ETypeApply" CellShapeETypeApply
            add "ENominal" CellShapeENominal
            add "EAnnotTest" CellShapeEAnnotTest
            add "EIfThenElse" CellShapeEIfThenElse
            add "ELet" CellShapeELet
            add "EMacro" CellShapeEMacro
            add "ESeq" CellShapeESeq
            add "EOp" CellShapeEOp
            add "EForall'" CellShapeEForall
            add "ERecursiveForall'" CellShapeEForall
            add "EFun'" CellShapeEFun
            add "ERecursiveFun'" CellShapeEFun
            add "EType" CellShapeEType
            add "EPair" CellShapeEPair
            add "ERecordWith" CellShapeERecordWith
            add "EUnitTest" CellShapeEUnitTest
            add "EPairTest" CellShapeEPairTest
            add "EUnbox" CellShapeEUnbox
            add "EJoinPoint'" CellShapeEJoinPointPrime
            add "EAnnot" CellShapeEAnnot
            add "EPatternMiss" CellShapeEPatternMiss
            add "ETypePatternMiss" CellShapeETypePatternMiss
            add "TTerm" CellShapeTTerm
            add "TPrim" CellShapeTPrim
            add "TFun" CellShapeTFun
            add "TPair" CellShapeTPair
            add "TRecord" CellShapeTRecord
            add "TUnion" CellShapeTUnion
            add "TNominal" CellShapeTNominal
            add "TB" CellShapeTB
            add "TV" CellShapeTV
            add "TArrow'" CellShapeTArrowPrime
            add "TLit" CellShapeTLit
            add "TExists" CellShapeTExists
            add "TForall'" CellShapeTForallPrime
            add "TMetaV" CellShapeTMetaV
            add "TApply" CellShapeTApply
            add "TJoinPoint" CellShapeTJoinPoint
            add "TJoinPoint'" CellShapeTJoinPointPrime
            map

        let private cellShapeOfWorkShapeId (shape:CompilerIdentityKernel.WorkShapeId) =
            let slot = CompilerIdentityKernel.WorkShapeIdOps.slot shape
            match cellShapeByWorkShapeSlot.TryGetValue slot with
            | true, shapeId -> shapeId
            | false, _ ->
                let shapeText = CompilerIdentityKernel.WorkShapeIdOps.text shape
                let family =
                    if System.String.IsNullOrEmpty shapeText then ReplayCellOtherShapeFamily
                    else
                        match shapeText.[0] with
                        | 'E' -> ReplayCellTermShapeFamily
                        | 'T' -> ReplayCellTypeShapeFamily
                        | _ -> ReplayCellOtherShapeFamily
                CellShapeOther family

        let private cellShapeFamilyId = function
            | CellShapeEB
            | CellShapeEV
            | CellShapeELit
            | CellShapeESymbol
            | CellShapeEApply
            | CellShapeETypeApply
            | CellShapeENominal
            | CellShapeEAnnotTest
            | CellShapeEIfThenElse
            | CellShapeELet
            | CellShapeEMacro
            | CellShapeESeq
            | CellShapeEOp
            | CellShapeEForall
            | CellShapeEFun
            | CellShapeEType
            | CellShapeEPair
            | CellShapeERecordWith
            | CellShapeEUnitTest
            | CellShapeEPairTest
            | CellShapeEUnbox
            | CellShapeEJoinPointPrime
            | CellShapeEAnnot
            | CellShapeEPatternMiss
            | CellShapeETypePatternMiss -> ReplayCellTermShapeFamily
            | CellShapeTTerm
            | CellShapeTPrim
            | CellShapeTFun
            | CellShapeTPair
            | CellShapeTRecord
            | CellShapeTUnion
            | CellShapeTNominal
            | CellShapeTB
            | CellShapeTV
            | CellShapeTArrowPrime
            | CellShapeTLit
            | CellShapeTExists
            | CellShapeTForallPrime
            | CellShapeTMetaV
            | CellShapeTApply
            | CellShapeTJoinPoint
            | CellShapeTJoinPointPrime -> ReplayCellTypeShapeFamily
            | CellShapeOther family -> family

        let private replayCellShapeId (cell: ReplayCell) =
            cellShapeOfWorkShapeId cell.shape

        let isJoinPointCellShape (shape:CompilerIdentityKernel.WorkShapeId) =
            match cellShapeOfWorkShapeId shape with
            | CellShapeTJoinPoint
            | CellShapeTJoinPointPrime -> true
            | _ -> false

