        let private replayTickRequestDecisionFromPressure = function
            | ReplayTickQueueEmpty -> ReplayTickNoQueue
            | ReplayTickScheduleableQueue
            | ReplayTickFenceStale -> ReplayTickSchedule
            | ReplayTickFenceAlreadyQueued
            | ReplayTickActiveDrainBackpressure -> ReplayTickWaitForExistingFence

        let private replayTickRequestDecision qd activeDepth stackFenceQueued staleQueued =
            replayTickQueuePressureFor qd activeDepth stackFenceQueued staleQueued
            |> replayTickRequestDecisionFromPressure

        let private replayTickRequestDecisionShouldSchedule decision =
            match decision with
            | ReplayTickSchedule -> true
            | _ -> false

        let private replayTickRequestDecisionToString decision =
            match decision with
            | ReplayTickNoQueue -> "no_queue"
            | ReplayTickSchedule -> "schedule_tick"
