            | ReplayTaskReadyExplicitLoop -> "ready_explicit_loop"
            | ReplayTaskUnknown reasonId -> CompilerKernelV2.OperationalReasonIdOps.text reasonId

        let private makeReplayTask id (key:ReplayTaskKeyId) driver payload semanticCell semanticPayloadState status : ReplayTask =
            let payloadId =
                match semanticCell with
                | Some cell -> ReplayTaskSemanticCellPayload cell
                | None -> ReplayTaskLegacyTextPayload(payload, semanticPayloadState)
            let legacyFacts, legacyNodeIds =
                match semanticCell with
                | Some _ -> replayTaskEmptyLegacyEvidence
                | None -> replayTaskLegacyEvidenceAtIngress payload
            { id = id
              key = key
              driver = driver
              payload = payloadId
              status = status
              legacyFacts = legacyFacts
              legacyNodeIds = legacyNodeIds }

        let private replayTaskDriverId (task:ReplayTask) = task.driver
        let private replayTaskStatusId (task:ReplayTask) = task.status

        let private replayTaskStatusIsScheduledParent status =
            match status with
            | ReplayTaskScheduledParentReplay -> true
            | _ -> false

        let private replayTaskStatusIsQueuedReplay status =
            match status with
            | ReplayTaskScheduledReplay
            | ReplayTaskScheduledParentReplay
            | ReplayTaskDriverReadyReplayCell
            | ReplayTaskDriverReadySemanticPayload -> true
            | _ -> false

        let private replayHandoffOwnerToString owner =
            match owner with
            | ReplayOwnerNoQueue -> "no_queue"
            | ReplayOwnerQueuedIdle -> "queued_idle"
            | ReplayOwnerQueuedActive -> "queued_active"
            | ReplayOwnerNestedActive -> "nested_active"
            | ReplayOwnerStackFence -> "stack_fence"
            | ReplayOwnerParentPreserved -> "parent_preserved"
            | ReplayOwnerDeferredChild -> "deferred_child"
            | ReplayOwnerCrossKind -> "cross_kind"
            | ReplayOwnerReentrant -> "reentrant"
            | ReplayOwnerUnknown reasonId -> CompilerKernelV2.OperationalReasonIdOps.text reasonId

        [<StructuralEquality; NoComparison>]
        type ReplayHandoffCauseId =
            | ReplayHandoffGeneric
            | ReplayHandoffStackFence
            | ReplayHandoffParentResume
            | ReplayHandoffDeferredChild
            | ReplayHandoffCrossKind
            | ReplayHandoffReentrant
            | ReplayHandoffSchedule
            | ReplayHandoffCooperativeTick

        let private replayHandoffOwnerForState cause queueDepth activeDepth stackCap statusId =
            match cause with
            | ReplayHandoffCrossKind -> ReplayOwnerCrossKind
            | ReplayHandoffReentrant -> ReplayOwnerReentrant
            | ReplayHandoffParentResume
            | ReplayHandoffDeferredChild -> ReplayOwnerDeferredChild
            | ReplayHandoffStackFence -> ReplayOwnerStackFence
            | ReplayHandoffGeneric
            | ReplayHandoffSchedule
            | ReplayHandoffCooperativeTick ->
                if activeDepth > stackCap then ReplayOwnerStackFence
                elif statusId = ReplayTaskScheduledParentReplay then ReplayOwnerParentPreserved
                elif queueDepth <= 0 then ReplayOwnerNoQueue
                elif activeDepth > 0 then ReplayOwnerQueuedActive
                else ReplayOwnerQueuedIdle

        let private replayDriverForKind fallback kind =
            match kind with
            | EvalTerm -> TermReplayDriver
            | EvalTy -> TyReplayDriver
            | _ -> fallback

