        let replayCellStatusText = function
            | ReplayCellSemanticStatus status -> semanticStatusToString status
            | ReplayCellReadyStatus status -> replayCellReadyStatusText status
            | ReplayCellTransitionStatus status -> replayCellTransitionStatusText status
            | ReplayCellProtocolStatus status -> replayCellProtocolStatusText status

        let frameStatusOfSemanticStatusId status =
            match status with
            | SemanticRootComplete -> FrameSemanticRootComplete
            | SemanticLeafComplete -> FrameSemanticLeafComplete
            | SemanticStepPartial -> FrameSemanticStepPartial
            | SemanticParentContinuationCycleBlocked -> FrameBlockedByReentry
            | other -> FrameSemanticStatus other

        let private frameStatusOfReplayCellStatusId status =
            match status with
            | ReplayCellSemanticStatus semanticStatus -> frameStatusOfSemanticStatusId semanticStatus
            | ReplayCellProtocolStatus ReplayCellProtocolContinuationEnvelope -> FrameContinuationEnvelope
            | ReplayCellProtocolStatus ReplayCellProtocolBlockedByReentry -> FrameBlockedByReentry
            | ReplayCellProtocolStatus ReplayCellProtocolCaptured -> FrameCaptured
            | other -> FrameReplayCellStatus other

        type ReplayCellReadyLegacyCodecDecision =
            | ReplayCellReadyLegacyUnboxRole of CompilerKernelV2.OperationalReasonId
            | ReplayCellReadyLegacyNotUnbox

        let private replayCellReadyLegacyCodecDecodeUnbox (value:string) =
            let prefix = "unbox_"
            let suffix = "_ready"
            let prefixLength = prefix.Length
            let suffixLength = suffix.Length
            let roleLength = value.Length - prefixLength - suffixLength
            if roleLength > 0
               && System.String.CompareOrdinal(value, 0, prefix, 0, prefixLength) = 0
               && System.String.CompareOrdinal(value, value.Length - suffixLength, suffix, 0, suffixLength) = 0 then
                ReplayCellReadyLegacyUnboxRole(
                    CompilerKernelV2.OperationalReasonIdOps.create (value.Substring(prefixLength, roleLength)))
            else
                ReplayCellReadyLegacyNotUnbox

        let private replayCellReadyStatusOfText = function
            | "parent_continuation_ready" -> Some ReplayCellReadyParentContinuation
            | "apply_head_ready" -> Some ReplayCellReadyApplyHead
            | "apply_arg_ready" -> Some ReplayCellReadyApplyArg
            | "let_body_ready" -> Some ReplayCellReadyLetBody
            | "let_success_ready" -> Some ReplayCellReadyLetSuccess
            | "op_arg_ready" -> Some ReplayCellReadyOpArg
            | "seq_first_ready" -> Some ReplayCellReadySeqFirst
            | "seq_second_ready" -> Some ReplayCellReadySeqSecond
            | "pair_left_ready" -> Some ReplayCellReadyPairLeft
            | "pair_right_ready" -> Some ReplayCellReadyPairRight
            | "tterm_term_ready" -> Some ReplayCellReadyTypeTermTerm
            | "tfun_arg_ready" -> Some ReplayCellReadyTypeFunArg
            | "tfun_body_ready" -> Some ReplayCellReadyTypeFunBody
            | "tpair_left_ready" -> Some ReplayCellReadyTypePairLeft
            | "tpair_right_ready" -> Some ReplayCellReadyTypePairRight
            | "type_apply_function_ready" -> Some ReplayCellReadyTypeApplyFunction
            | "type_apply_type_arg_ready" -> Some ReplayCellReadyTypeApplyTypeArg
            | "nominal_inner_ready" -> Some ReplayCellReadyNominalInner
            | "nominal_type_ready" -> Some ReplayCellReadyNominalType
            | "annot_inner_ready" -> Some ReplayCellReadyAnnotInner
            | "annot_type_ready" -> Some ReplayCellReadyAnnotType
            | "macro_term_child_ready" -> Some ReplayCellReadyMacroTermChild
            | "macro_type_child_ready" -> Some ReplayCellReadyMacroTypeChild
            | "macro_result_type_ready" -> Some ReplayCellReadyMacroResultType
            | "dynamic_function_bridge_bigstack_body_ready" -> Some ReplayCellReadyDynamicFunctionBridgeBigStackBody
            | "apply_function_body_dynamic_literal_tail_ready" -> Some ReplayCellReadyApplyFunctionBodyDynamicLiteralTail
            | "apply_function_body_dynamic_dyn_typecheck_pair_tail_ready" -> Some ReplayCellReadyApplyFunctionBodyDynamicDynTypecheckPairTail
            | "apply_function_body_dynamic_part_eval_tail_ready" -> Some ReplayCellReadyApplyFunctionBodyDynamicPartEvalTail
            | "dynamic_record_bridge_bigstack_body_ready" -> Some ReplayCellReadyDynamicRecordBridgeBigStackBody
            | "annot_test_body_ready" -> Some ReplayCellReadyAnnotTestBody
            | "op_body_ready" -> Some ReplayCellReadyOpBody
            | "apply_function_body_ready" -> Some ReplayCellReadyApplyFunctionBody
            | "op_type_aware_child_ready" -> Some ReplayCellReadyOpTypeAwareChild
            | "unit_test_bind_ready" -> Some ReplayCellReadyUnitTestBind
            | "unit_test_branch_ready" -> Some ReplayCellReadyUnitTestBranch
            | "type_apply_annot_body_ready" -> Some ReplayCellReadyTypeApplyAnnotBody
            | "type_apply_op_body_ready" -> Some ReplayCellReadyTypeApplyOpBody
            | "type_apply_nominal_constructor_ready" -> Some ReplayCellReadyTypeApplyNominalConstructor
            | "annot_test_branch_ready" -> Some ReplayCellReadyAnnotTestBranch
            | "annot_test_branch_probe_ready" -> Some ReplayCellReadyAnnotTestBranchProbe
            | "annot_test_type_ready" -> Some ReplayCellReadyAnnotTestType
            | "if_true_branch_ready" -> Some ReplayCellReadyIfTrueBranch
            | "if_false_branch_ready" -> Some ReplayCellReadyIfFalseBranch
            | "if_unknown_return_branch_probe_ready" -> Some ReplayCellReadyIfUnknownReturnBranchProbe
            | "if_symbolic_condition_branch_probe_ready" -> Some ReplayCellReadyIfSymbolicConditionBranchProbe
            | "if_condition_ready" -> Some ReplayCellReadyIfCondition
            | "record_with_child_ready" -> Some ReplayCellReadyRecordWithChild
            | "pair_test_branch_ready" -> Some ReplayCellReadyPairTestBranch
            | "annot_null_deferred_child_ready" -> Some ReplayCellReadyAnnotNullDeferredChild
            | "joinpoint_live_deferred_child_ready" -> Some ReplayCellReadyJoinpointLiveDeferredChild
            | "deferred_ty_child_ready" -> Some ReplayCellReadyDeferredTyChild
            | "tjoinpoint_body_ready" -> Some ReplayCellReadyTjoinpointBody
            | "selected_frontier_stepper_ready" -> Some ReplayCellReadySelectedFrontierStepper
            | value ->
                match replayCellReadyLegacyCodecDecodeUnbox value with
                | ReplayCellReadyLegacyUnboxRole role -> Some (ReplayCellReadyUnboxChild role)
                | ReplayCellReadyLegacyNotUnbox ->
                    match value with
                    | "if_branch_ready" -> Some ReplayCellReadyIfBranch
                    | _ -> None

        let private replayCellProtocolStatusOfText = function
            | "captured" -> Some ReplayCellProtocolCaptured
            | "stale_root_retarget_quarantined" -> Some ReplayCellProtocolStaleRootRetargetQuarantined
            | "stale_root_retargeted" -> Some ReplayCellProtocolStaleRootRetargeted
            | "blocked_by_reentry" -> Some ReplayCellProtocolBlockedByReentry
            | "dynamic_join_apply_bigstack_stall_guarded" -> Some ReplayCellProtocolDynamicJoinApplyBigStackStallGuarded
            | "dynamic_join_apply_root_witness_guarded" -> Some ReplayCellProtocolDynamicJoinApplyRootWitnessGuarded
            | "dynamic_function_bridge_recoverable_yielded" -> Some ReplayCellProtocolDynamicFunctionBridgeRecoverableYielded
            | "continuation_envelope" -> Some ReplayCellProtocolContinuationEnvelope
            | _ -> None

        let private replayCellStatusOfText text =
            match replayCellReadyStatusOfText text with
            | Some status -> ReplayCellReadyStatus status
            | None ->
                match replayCellProtocolStatusOfText text with
                | Some status -> ReplayCellProtocolStatus status
                | None -> ReplayCellSemanticStatus (semanticStatusOfString text)

        let private replayCellSemanticStatusId = function
            | ReplayCellSemanticStatus status -> status
            | ReplayCellReadyStatus ReplayCellReadyParentContinuation -> SemanticParentContinuationReady
            | ReplayCellReadyStatus ReplayCellReadyLetSuccess -> SemanticLetSuccessReady
            | ReplayCellReadyStatus ReplayCellReadyTypeFunArg -> SemanticTfunArgReady
            | ReplayCellReadyStatus ReplayCellReadyTypePairLeft -> SemanticTpairLeftReady
            | ReplayCellReadyStatus ReplayCellReadyPairLeft -> SemanticPairLeftReady
            | ReplayCellReadyStatus ReplayCellReadySelectedFrontierStepper -> SemanticSelectedFrontierStepperReady
            | ReplayCellReadyStatus status -> SemanticOther (CompilerKernelV2.OperationalReasonIdOps.create (replayCellReadyStatusText status))
            | ReplayCellTransitionStatus status -> SemanticOther (CompilerKernelV2.OperationalReasonIdOps.create (replayCellTransitionStatusText status))
            | ReplayCellProtocolStatus status -> SemanticOther (CompilerKernelV2.OperationalReasonIdOps.create (replayCellProtocolStatusText status))

        let frameStatusToString status =
            match status with
            | FrameReadyExplicitLoop -> "ready_explicit_loop"
            | FrameTracingExplicitLoop -> "tracing_explicit_loop"
            | FrameContinuationEnvelope -> "continuation_envelope"
            | FrameSemanticStepPartial -> "semantic_step_partial"
            | FrameSemanticRootComplete -> "semantic_root_complete"
            | FrameSemanticLeafComplete -> "semantic_leaf_complete"
            | FrameBlockedByReentry -> "blocked_by_reentry"
            | FrameCaptured -> "captured"
            | FrameProgressYieldFrontier -> "progress_yield_frontier"
            | FrameSemanticStatus semanticStatus -> semanticStatusToString semanticStatus
            | FrameReplayCellStatus replayStatus -> replayCellStatusText replayStatus
            | FrameUnknown(reasonId, _) -> CompilerKernelV2.OperationalReasonIdOps.text reasonId

        let frameStatusIsPresent = function
            | FrameUnknown(reasonId, _) -> not (System.String.IsNullOrEmpty (CompilerKernelV2.OperationalReasonIdOps.text reasonId))
            | _ -> true

        let private frameStatusSemanticStatusId = function
            | FrameSemanticRootComplete -> SemanticRootComplete
            | FrameSemanticLeafComplete -> SemanticLeafComplete
            | FrameSemanticStepPartial -> SemanticStepPartial
            | FrameBlockedByReentry -> SemanticParentContinuationCycleBlocked
            | FrameSemanticStatus semanticStatus -> semanticStatus
            | FrameReplayCellStatus replayStatus -> replayCellSemanticStatusId replayStatus
            | FrameUnknown(reasonId, _) -> SemanticOther reasonId
            | FrameReadyExplicitLoop -> SemanticOther(CompilerKernelV2.OperationalReasonIdOps.create "ready_explicit_loop")
            | FrameTracingExplicitLoop -> SemanticOther(CompilerKernelV2.OperationalReasonIdOps.create "tracing_explicit_loop")
            | FrameContinuationEnvelope -> SemanticOther(CompilerKernelV2.OperationalReasonIdOps.create "continuation_envelope")
            | FrameCaptured -> SemanticOther(CompilerKernelV2.OperationalReasonIdOps.create "captured")
            | FrameProgressYieldFrontier -> SemanticOther(CompilerKernelV2.OperationalReasonIdOps.create "progress_yield_frontier")

        let replayCellRevisionText (cell:ReplayCell) =
            String.concat "\u001f"
                [ replayCellKindText cell
                  replayCellShapeText cell
                  string cell.nodeId
                  string cell.envGlobalTerm
                  string cell.envStackTerm
                  string cell.envGlobalType
                  string cell.envStackType
                  string cell.seqLen
                  string cell.cseDepth
                  string cell.traceDepth
                  replayCellSiteText cell
                  string cell.cursor
                  string cell.step
                  replayCellStatusText cell.status ]
            |> CompilerIdentityKernel.ContentDigest.ofText "eval-replay-cell-revision"
            |> CompilerIdentityKernel.ContentDigest.text

        // MIGRATION: MIGRATION placed SidecarPrefetchOutcomeId under BigStack, but the
        // ty/term re-entry call sites intentionally address EvalWorklist.  Keep this
        // seam in EvalWorklist so missing-after-prefetch is a typed semantic outcome
        // before it crosses back to Frame.status / JSON text.
        type SidecarPrefetchKindId =
            | SidecarPrefetchTy
            | SidecarPrefetchTerm
            | SidecarPrefetchUnknown of CompilerKernelV2.OperationalReasonId


        let sidecarPrefetchKindText = function
            | SidecarPrefetchTy -> "ty"
            | SidecarPrefetchTerm -> "term"
            | SidecarPrefetchUnknown reasonId -> CompilerKernelV2.OperationalReasonIdOps.text reasonId

        type SidecarPrefetchOutcomeId =
            | SidecarPrefetchFrameAvailable
            | SidecarPrefetchMissingAfterPrefetch

        let sidecarPrefetchOutcomeForFrame frameOpt =
            match frameOpt with
            | Some _ -> SidecarPrefetchFrameAvailable
            | None -> SidecarPrefetchMissingAfterPrefetch

        let sidecarPrefetchOutcomeText = function
            | SidecarPrefetchFrameAvailable -> "frame_available"
            | SidecarPrefetchMissingAfterPrefetch -> "missing_after_prefetch"

        let sidecarPrefetchStatusText = function
            | SidecarPrefetchFrameAvailable -> "frame_available"
            | SidecarPrefetchMissingAfterPrefetch -> "semantic_missing_after_prefetch_blocked"

        // MIGRATION: missing-after-prefetch is a terminal only after the
        // replay lane proves quiet.  1230 proved pending protects the BigStack
        // handoff, but the same pin could still leak through the global-fuse
        // primary-message retarget path while a fresh replay frame was being
        // promoted.  Keep the contract as a typed decision and require a quiet
        // window before surfacing.
        type GenerationInvalidationCauseId =
            | GenerationInvalidationCauseNoneObserved
            | GenerationInvalidationCauseJpIvarWaitGenerationChanged
            | GenerationInvalidationCauseUnknownOrCacheGenerationRetry

        let private generationInvalidationCauseText = function
            | GenerationInvalidationCauseNoneObserved -> "none_observed"
            | GenerationInvalidationCauseJpIvarWaitGenerationChanged -> "jp_ivar_wait_generation_changed"
            | GenerationInvalidationCauseUnknownOrCacheGenerationRetry -> "unknown_or_cache_generation_retry"

        type PrefetchResolutionStatusId =
            | PrefetchResolutionResolved
            | PrefetchResolutionNotFoundAfterSidecarPrefetch
            | PrefetchResolutionGenerationDesyncCacheMiss
            | PrefetchResolutionEvictedOrInvalidated

        let private prefetchResolutionStatusText = function
            | PrefetchResolutionResolved -> "resolved"
            | PrefetchResolutionNotFoundAfterSidecarPrefetch -> "not_found_after_sidecar_prefetch"
            | PrefetchResolutionGenerationDesyncCacheMiss -> "generation_desync_cache_miss"
            | PrefetchResolutionEvictedOrInvalidated -> "evicted_or_invalidated"

        type NodeLifecycleEventId =
            | NodeLifecycleNoVisibleEvictionReceipt
            | NodeLifecycleInvalidatedByGenerationChange
            | NodeLifecycleMissingDependencyAfterPrefetch

        let private nodeLifecycleEventText = function
            | NodeLifecycleNoVisibleEvictionReceipt -> "missing_after_prefetch_without_visible_eviction_receipt"
            | NodeLifecycleInvalidatedByGenerationChange -> "invalidated_by_generation_change"
            | NodeLifecycleMissingDependencyAfterPrefetch -> "missing_dependency_after_prefetch"

        type MissingDependencyTailBlockerId =
            | MissingDependencyTailNone
            | MissingDependencyTailBlockedPrefetch
            | MissingDependencyTailBlockedGenerationDesync
            | MissingDependencyTailBlockedJpIvarWait

        let private missingDependencyTailBlockerText = function
            | MissingDependencyTailNone -> "none"
            | MissingDependencyTailBlockedPrefetch -> "blocked:missing_prefetch"
            | MissingDependencyTailBlockedGenerationDesync -> "blocked:generation_desync"
            | MissingDependencyTailBlockedJpIvarWait -> "blocked:jp_ivar_wait"

        type JpIvarWaitStateId =
            | JpIvarWaitStateNone
            | JpIvarWaitStateGenerationChangedErasedTag0
            | JpIvarWaitStateGenerationChangedUnknownTag

        let private jpIvarWaitStateText = function
            | JpIvarWaitStateNone -> "none"
            | JpIvarWaitStateGenerationChangedErasedTag0 -> "generation_desync_erased_tag_0"
            | JpIvarWaitStateGenerationChangedUnknownTag -> "generation_desync_unknown_tag"

        type CycleBreakPoisonLiveOverrideOutcomeId =
            | CycleBreakPoisonLiveOverrideNotAttempted
            | CycleBreakPoisonLiveOverrideGranted
            | CycleBreakPoisonLiveOverrideDeniedNoLiveTail
            | CycleBreakPoisonLiveOverrideDeniedNoSemanticRootEvidence
            | CycleBreakPoisonLiveOverrideDeniedRetryBudgetExhausted
            | CycleBreakPoisonLiveOverrideLegacyLiveRetry

        let private cycleBreakPoisonLiveOverrideOutcomeText = function
            | CycleBreakPoisonLiveOverrideNotAttempted -> "not_attempted"
            | CycleBreakPoisonLiveOverrideGranted -> "granted"
            | CycleBreakPoisonLiveOverrideDeniedNoLiveTail -> "denied_no_live_tail"
            | CycleBreakPoisonLiveOverrideDeniedNoSemanticRootEvidence -> "denied_no_semantic_or_root_evidence"
            | CycleBreakPoisonLiveOverrideDeniedRetryBudgetExhausted -> "denied_retry_budget_exhausted"
            | CycleBreakPoisonLiveOverrideLegacyLiveRetry -> "legacy_live_retry"

        type MissingAfterPrefetchTerminalDecisionId =
            | MissingAfterPrefetchNotTerminal
            | MissingAfterPrefetchSurfaceTerminal
            | MissingAfterPrefetchSurfacePinnedHighRankProgress
            | MissingAfterPrefetchSurfaceSmallPendingQueue
            | MissingAfterPrefetchSurfaceSmallLiveTail
            | MissingAfterPrefetchDeferLiveReplay
            | MissingAfterPrefetchDeferFreshReplayProgress
            | MissingAfterPrefetchDeferLiveTailProbation
            | MissingAfterPrefetchDeferQuietWindow
            | MissingAfterPrefetchDeferGenerationDesyncLiveTail
            | MissingAfterPrefetchSurfaceGenerationDesyncExhausted
            | MissingAfterPrefetchSurfaceNegativePendingLedgerCorruption
            | MissingAfterPrefetchHardSurfacePendingZeroNoWaiter

        let missingAfterPrefetchTerminalDecisionText = function
            | MissingAfterPrefetchNotTerminal -> "not_missing_after_prefetch"
            | MissingAfterPrefetchSurfaceTerminal -> "surface_terminal"
            | MissingAfterPrefetchSurfacePinnedHighRankProgress -> "surface_pinned_high_rank_progress"
            | MissingAfterPrefetchSurfaceSmallPendingQueue -> "surface_small_pending_queue"
            | MissingAfterPrefetchSurfaceSmallLiveTail -> "surface_small_live_tail"
            | MissingAfterPrefetchDeferLiveReplay -> "defer_live_replay"
            | MissingAfterPrefetchDeferFreshReplayProgress -> "defer_fresh_replay_progress"
            | MissingAfterPrefetchDeferLiveTailProbation -> "defer_live_tail_probation"
            | MissingAfterPrefetchDeferQuietWindow -> "defer_quiet_window"
            | MissingAfterPrefetchDeferGenerationDesyncLiveTail -> "defer_generation_desync_live_tail"
            | MissingAfterPrefetchSurfaceGenerationDesyncExhausted -> "surface_generation_desync_exhausted"
            | MissingAfterPrefetchSurfaceNegativePendingLedgerCorruption -> "surface_negative_pending_ledger_corruption"
            | MissingAfterPrefetchHardSurfacePendingZeroNoWaiter -> "hard_surface_pending_zero_no_waiter"

        let missingAfterPrefetchTerminalDecisionFor (statusId: SemanticStatusId) pending queueDepth activeDepth progressYield replayComplete writeWitness terminalAgeMs =
            let replayProgressEvidence =
                (try DiagJson.snapshotKindCount "eval_worklist_source_value_stored" with _ -> 0)
                + (try DiagJson.snapshotKindCount "eval_worklist_root_complete_replay_progress_marked" with _ -> 0)
            let liveReplayEvidence = queueDepth > 0 || activeDepth > 0 || progressYield
            let highRankProgressAuthority =
                pending = 0
                && not writeWitness
                && liveReplayEvidence
                && replayProgressEvidence >= 8
            let saturatedOrActiveLiveTail =
                queueDepth >= 16
                || activeDepth > 0
                || highRankProgressAuthority
            match statusId with
            | SemanticMissingAfterPrefetchBlocked when pending < 0 -> MissingAfterPrefetchSurfaceNegativePendingLedgerCorruption
            | SemanticMissingAfterPrefetchBlocked when pending = 0 && not writeWitness && saturatedOrActiveLiveTail && not replayComplete -> MissingAfterPrefetchDeferLiveTailProbation
            | SemanticMissingAfterPrefetchBlocked when pending <= 1 && queueDepth <= 2 && activeDepth = 0 && not writeWitness -> MissingAfterPrefetchSurfaceSmallPendingQueue
            | SemanticMissingAfterPrefetchBlocked when pending <= 1 && queueDepth <= 8 && activeDepth <= 4 && not writeWitness && replayProgressEvidence >= 4 && terminalAgeMs >= 1500 -> MissingAfterPrefetchSurfaceSmallLiveTail
            | SemanticMissingAfterPrefetchBlocked when pending = 0 && not writeWitness && liveReplayEvidence && replayProgressEvidence > 0 && terminalAgeMs < 1500 -> MissingAfterPrefetchDeferFreshReplayProgress
            | SemanticMissingAfterPrefetchBlocked when pending = 0 && not writeWitness && liveReplayEvidence && replayProgressEvidence > 0 && terminalAgeMs < 12000 -> MissingAfterPrefetchDeferGenerationDesyncLiveTail
            | SemanticMissingAfterPrefetchBlocked when pending = 0 && not writeWitness && liveReplayEvidence && terminalAgeMs < 5000 -> MissingAfterPrefetchDeferLiveTailProbation
            | SemanticMissingAfterPrefetchBlocked when pending = 0 && not writeWitness && liveReplayEvidence && replayProgressEvidence > 0 -> MissingAfterPrefetchSurfaceGenerationDesyncExhausted
            | SemanticMissingAfterPrefetchBlocked when pending = 0 && not writeWitness && liveReplayEvidence -> MissingAfterPrefetchHardSurfacePendingZeroNoWaiter
            | SemanticMissingAfterPrefetchBlocked when pending > 0 || liveReplayEvidence -> MissingAfterPrefetchDeferLiveReplay
            | SemanticMissingAfterPrefetchBlocked when not replayComplete && not writeWitness && terminalAgeMs < 1000 -> MissingAfterPrefetchDeferQuietWindow
            | SemanticMissingAfterPrefetchBlocked -> MissingAfterPrefetchSurfaceTerminal
            | _ -> MissingAfterPrefetchNotTerminal

        let missingAfterPrefetchTerminalDecisionShouldDefer = function
            | MissingAfterPrefetchDeferLiveReplay
            | MissingAfterPrefetchDeferFreshReplayProgress
            | MissingAfterPrefetchDeferLiveTailProbation
            | MissingAfterPrefetchDeferGenerationDesyncLiveTail
            | MissingAfterPrefetchDeferQuietWindow -> true
            | _ -> false

        let missingAfterPrefetchTerminalDecisionIsFreshProgressDefer = function
            | MissingAfterPrefetchDeferFreshReplayProgress
            | MissingAfterPrefetchDeferGenerationDesyncLiveTail
            | MissingAfterPrefetchDeferLiveTailProbation -> true
            | _ -> false

        let missingAfterPrefetchTerminalDecisionShouldHardSurface = function
            | MissingAfterPrefetchHardSurfacePendingZeroNoWaiter
            | MissingAfterPrefetchSurfaceNegativePendingLedgerCorruption
            | MissingAfterPrefetchSurfacePinnedHighRankProgress
            | MissingAfterPrefetchSurfaceSmallPendingQueue
            | MissingAfterPrefetchSurfaceSmallLiveTail
            | MissingAfterPrefetchSurfaceGenerationDesyncExhausted -> true
            | _ -> false

        type SidecarPrefetchTerminalReasonId =
            | SidecarTyReentryPrefetchMissingAfterPrefetch
            | SidecarTermReentryPrefetchMissingAfterPrefetch

        let sidecarPrefetchTerminalReasonText = function
            | SidecarTyReentryPrefetchMissingAfterPrefetch -> "ty_sidecar_prefetch_missing_after_prefetch"
            | SidecarTermReentryPrefetchMissingAfterPrefetch -> "term_sidecar_prefetch_missing_after_prefetch"

        // MIGRATION: this is the smallest compile-safe step away from stringly
        // scheduling in the new keyed global-fuse branch.  It does not pretend the
        // whole worklist is reimagined yet; it gives the fuse path a real decision
        // value carrying the repeat/cap evidence, with string rendering confined to
        // the logging / Frame.status boundary.
        type GlobalFuseReplayDecision =
            | ParentContinuationFuseDeferred of int * int
            | ParentContinuationFuseDeferredTypeHole of int * int
            | ParentContinuationFuseDeferredTypeHoleWithReplayRootWitness of int * int
            | ParentContinuationFuseReplayRootWitnessPreserved of int * int
            | ParentContinuationFuseBlocked of int * int
            | OrphanGlobalFuseDeferred of int * int
            | OrphanGlobalFuseBlocked of int * int

        let globalFuseReplayDecisionRepeat decision =
            match decision with
            | ParentContinuationFuseDeferred(repeat, _)
            | ParentContinuationFuseDeferredTypeHole(repeat, _)
            | ParentContinuationFuseDeferredTypeHoleWithReplayRootWitness(repeat, _)
            | ParentContinuationFuseReplayRootWitnessPreserved(repeat, _)
            | ParentContinuationFuseBlocked(repeat, _)
            | OrphanGlobalFuseDeferred(repeat, _)
            | OrphanGlobalFuseBlocked(repeat, _) -> repeat

        let globalFuseReplayDecisionCap decision =
            match decision with
            | ParentContinuationFuseDeferred(_, cap)
            | ParentContinuationFuseDeferredTypeHole(_, cap)
            | ParentContinuationFuseDeferredTypeHoleWithReplayRootWitness(_, cap)
            | ParentContinuationFuseReplayRootWitnessPreserved(_, cap)
            | ParentContinuationFuseBlocked(_, cap)
            | OrphanGlobalFuseDeferred(_, cap)
            | OrphanGlobalFuseBlocked(_, cap) -> cap

        let globalFuseReplayDecisionStatusId decision =
            match decision with
            | ParentContinuationFuseDeferred _ -> SemanticParentContinuationCycleDeferred
            | ParentContinuationFuseDeferredTypeHole _ -> SemanticStepPartial
            | ParentContinuationFuseDeferredTypeHoleWithReplayRootWitness _ -> SemanticStepPartial
            | ParentContinuationFuseReplayRootWitnessPreserved _ -> SemanticStepPartial
            | ParentContinuationFuseBlocked _ -> SemanticGlobalFuseParentContinuationCycleBlocked
            | OrphanGlobalFuseDeferred _ -> SemanticStepPartial
            | OrphanGlobalFuseBlocked _ -> SemanticGlobalFuseParentContinuationCycleBlocked

        let globalFuseReplayDecisionStatusText decision =
            decision |> globalFuseReplayDecisionStatusId |> semanticStatusToString

        // MIGRATION: MIGRATION proves MIGRATION advanced past the metronome
        // no-work frontier and returned to a concrete rank-80 parent-continuation
        // global-fuse pin.  The pin is useful only after the live replay lane is
        // empty or after a bounded late-drain grace has been consumed.  Keep that
        // arbitration as data so term/ty global-fuse sites do not surface an
        // EJP0011 while pending replay, queued replay, active drivers, or progress
        // yield are still alive.
        type ParentFuseStarvationTerminalDecisionId =
            | ParentFuseStarvationNotReached
            | ParentFuseStarvationDeferLiveReplay
            | ParentFuseStarvationDeferFreshRootReplay
            | ParentFuseStarvationProbeProgressingReplay
            | ParentFuseStarvationDeferRecentProgressReplay
            | ParentFuseStarvationFailFastLiveReplayDrip
            | ParentFuseStarvationPinTerminal

        let parentFuseStarvationTerminalDecisionText = function
            | ParentFuseStarvationNotReached -> "not_reached"
            | ParentFuseStarvationDeferLiveReplay -> "defer_live_replay"
            | ParentFuseStarvationDeferFreshRootReplay -> "defer_fresh_root_replay"
            | ParentFuseStarvationProbeProgressingReplay -> "probe_progressing_replay"
            | ParentFuseStarvationDeferRecentProgressReplay -> "defer_recent_progress_replay"
            | ParentFuseStarvationFailFastLiveReplayDrip -> "failfast_live_replay_drip"
            | ParentFuseStarvationPinTerminal -> "pin_terminal"

        let parentFuseStarvationTerminalDecisionFor starved pendingCount queueDepth activeDepth hasProgressYield freshRootWitness recentProgress repeat cap =
            let liveReplay = pendingCount > 0 && (queueDepth > 0 || activeDepth > 0 || hasProgressYield)
            if not starved then ParentFuseStarvationNotReached
            elif liveReplay && freshRootWitness && repeat <= (cap + 24) then ParentFuseStarvationDeferFreshRootReplay
            elif liveReplay && recentProgress && hasProgressYield && activeDepth > 0 && repeat <= (cap + 32) then ParentFuseStarvationDeferRecentProgressReplay
            elif liveReplay && queueDepth > 0 && activeDepth > 0 && hasProgressYield && repeat <= (cap + 16) then ParentFuseStarvationProbeProgressingReplay
            elif liveReplay && repeat <= (cap + 8) then ParentFuseStarvationDeferLiveReplay
            elif liveReplay && recentProgress then ParentFuseStarvationFailFastLiveReplayDrip
            else ParentFuseStarvationPinTerminal

        // MIGRATION: classify the final global-fuse abort cause as data before it
        // is rendered into an EJP0011 message.  MIGRATION reached real replay and
        // failed on a dynamic-join terminal whose original fuse text still carried
        // raw English suffixes.  Keep those suffixes at the final human boundary,
        // but make the policy/logging seam a closed DU.
        type GlobalFuseAbortCauseId =
            | GlobalFuseAbortTermParentContinuationReplayCapExhaustedBeforeStackOverflow
            | GlobalFuseAbortTyParentContinuationReplayCapExhaustedBeforeStackOverflow
            | GlobalFuseAbortGenericTermGlobalFuse
            | GlobalFuseAbortGenericTyGlobalFuse

        let globalFuseAbortCauseText = function
            | GlobalFuseAbortTermParentContinuationReplayCapExhaustedBeforeStackOverflow -> "term_parent_continuation_replay_cap_exhausted_before_stackoverflow"
            | GlobalFuseAbortTyParentContinuationReplayCapExhaustedBeforeStackOverflow -> "ty_parent_continuation_replay_cap_exhausted_before_stackoverflow"
            | GlobalFuseAbortGenericTermGlobalFuse -> "term_global_fuse"
            | GlobalFuseAbortGenericTyGlobalFuse -> "ty_global_fuse"

        let globalFuseAbortCauseMessage = function
            | GlobalFuseAbortTermParentContinuationReplayCapExhaustedBeforeStackOverflow -> "parent-continuation replay cap exhausted before StackOverflow"
            | GlobalFuseAbortTyParentContinuationReplayCapExhaustedBeforeStackOverflow -> "ty parent-continuation replay cap exhausted before StackOverflow"
            | GlobalFuseAbortGenericTermGlobalFuse -> "aborting term worker before StackOverflow"
            | GlobalFuseAbortGenericTyGlobalFuse -> "aborting ty worker before StackOverflow"

        // MIGRATION: keep retry-stop terminal/replay arbitration typed.  The old
        // branch was already mostly correct, but MIGRATION proved the late global
        // fuse terminal can arrive while pending replay is still live and the
        // generic yield cap has been consumed.  The DU records whether retry-stop
        // should abort, consume the normal progress-yield path, or enter the
        // global-fuse-specific live drain extension.
        type RetryStopFrontierDecisionId =
            | RetryStopNoReplay
            | RetryStopProgressYield
            | RetryStopGlobalFuseLiveDrain
            | RetryStopGlobalFuseLiveQueueDrain
            | RetryStopGlobalFusePendingStackFenceDrain
            | RetryStopDynamicJoinPendingStackFenceDrain
            | RetryStopDynamicJoinLiveDrain
            | RetryStopDynamicJoinLiveQueueDrain
            | RetryStopParentReplayStatusLiveDrain
            | RetryStopParentReplayStatusQueueDrain
            | RetryStopTerminalContractAbort
            | RetryStopBlockedAbort

        let retryStopFrontierDecisionText = function
            | RetryStopNoReplay -> "no_replay"
            | RetryStopProgressYield -> "progress_yield"
            | RetryStopGlobalFuseLiveDrain -> "global_fuse_live_drain"
            | RetryStopGlobalFuseLiveQueueDrain -> "global_fuse_live_queue_drain"
            | RetryStopGlobalFusePendingStackFenceDrain -> "cycle_fuse_deferred_by_pending_stack_fence"
            | RetryStopDynamicJoinPendingStackFenceDrain -> "dynamic_join_deferred_by_pending_stack_fence"
            | RetryStopDynamicJoinLiveDrain -> "dynamic_join_live_drain"
            | RetryStopDynamicJoinLiveQueueDrain -> "dynamic_join_live_queue_drain"
            | RetryStopParentReplayStatusLiveDrain -> "parent_replay_status_live_drain"
            | RetryStopParentReplayStatusQueueDrain -> "parent_replay_status_queue_drain"
            | RetryStopTerminalContractAbort -> "terminal_contract_abort"
            | RetryStopBlockedAbort -> "blocked_abort"

        // MIGRATION: 1183 was the first good diagnostic run after the no-work
        // frontier, but the final retry_stop_drain still let a rank-80 global-fuse
        // parent-continuation pin retarget a live continuation envelope while pending
        // replay was alive.  Keep that arbitration typed and generic: a global fuse
        // pin is terminal only after the live replay/continuation/root evidence lane
        // is empty or quiet.  This is selection hygiene; it does not synthesize any
        // value, writer witness, root proof, codegen output, or BuildOk.
        type RetryDrainPinnedTerminalDecisionId =
            | RetryDrainPinTerminal
            | RetryDrainDeferGlobalFuseLiveReplay
            | RetryDrainDeferGlobalFuseContinuationEnvelope
            | RetryDrainDeferDynamicJoinRunnableReplay
            | RetryDrainDeferDynamicJoinPendingReplay
            | RetryDrainPreserveRootEvidence

        let retryDrainPinnedTerminalDecisionText = function
            | RetryDrainPinTerminal -> "pin_terminal"
            | RetryDrainDeferGlobalFuseLiveReplay -> "defer_global_fuse_live_replay"
            | RetryDrainDeferGlobalFuseContinuationEnvelope -> "defer_global_fuse_continuation_envelope"
            | RetryDrainDeferDynamicJoinRunnableReplay -> "defer_dynamic_join_runnable_replay"
            | RetryDrainDeferDynamicJoinPendingReplay -> "defer_dynamic_join_pending_replay"
            | RetryDrainPreserveRootEvidence -> "preserve_root_evidence"

        type RetryDrainLiveEvidenceId =
            | RetryDrainNoLiveEvidence
            | RetryDrainPendingOnly
            | RetryDrainQueueLive
            | RetryDrainActiveDriverLive
            | RetryDrainProgressYieldLive

        let retryDrainLiveEvidenceText = function
            | RetryDrainNoLiveEvidence -> "none"
            | RetryDrainPendingOnly -> "pending_only"
            | RetryDrainQueueLive -> "queue_live"
            | RetryDrainActiveDriverLive -> "active_driver_live"
            | RetryDrainProgressYieldLive -> "progress_yield_live"

        let retryDrainLiveEvidenceFor pending queueDepth activeDepth progressYield =
            if pending <= 0 then RetryDrainNoLiveEvidence
            elif queueDepth > 0 then RetryDrainQueueLive
            elif activeDepth > 0 then RetryDrainActiveDriverLive
            elif progressYield then RetryDrainProgressYieldLive
            else RetryDrainPendingOnly

        let retryDrainLiveEvidenceIsLive = function
            | RetryDrainNoLiveEvidence
            | RetryDrainPendingOnly -> false
            | RetryDrainQueueLive
            | RetryDrainActiveDriverLive
            | RetryDrainProgressYieldLive -> true

        let retryDrainLiveEvidenceHasPending = function
            | RetryDrainNoLiveEvidence -> false
            | _ -> true

        let retryDrainPinnedTerminalDecisionFor (pinnedStatus:FrameStatusId) (frameStatus:FrameStatusId) pending queueDepth activeDepth progressYield freshRootWitness =
            let liveEvidence = retryDrainLiveEvidenceFor pending queueDepth activeDepth progressYield
            let liveReplay = retryDrainLiveEvidenceIsLive liveEvidence
            let pendingReplay = retryDrainLiveEvidenceHasPending liveEvidence
            let pinnedSemanticStatus = frameStatusSemanticStatusId pinnedStatus
            let frameSemanticStatus = frameStatusSemanticStatusId frameStatus
            let continuationEnvelope = frameStatus = FrameContinuationEnvelope
            let liveOrRootComplete = isLiveOrRootCompleteFrameStatus frameStatus
            let semanticLeafComplete = frameStatus = FrameSemanticLeafComplete
            let replayDriverException = frameSemanticStatus = SemanticReplayDriverExceptionBlocked
            let drainableFrame =
                continuationEnvelope
                || liveOrRootComplete
                || semanticLeafComplete
                || frameSemanticStatus = SemanticStepPartial
                || replayDriverException
            if pinnedSemanticStatus = SemanticDynamicJoinApplyBlocked && liveReplay && drainableFrame then
                RetryDrainDeferDynamicJoinRunnableReplay
            elif pinnedSemanticStatus = SemanticDynamicJoinApplyBlocked && pendingReplay && continuationEnvelope then
                RetryDrainDeferDynamicJoinPendingReplay
            elif pinnedSemanticStatus <> SemanticGlobalFuseParentContinuationCycleBlocked then
                RetryDrainPinTerminal
            elif liveReplay && continuationEnvelope then
                RetryDrainDeferGlobalFuseContinuationEnvelope
            elif liveReplay && freshRootWitness && liveOrRootComplete then
                RetryDrainPreserveRootEvidence
            elif liveReplay && (liveOrRootComplete || semanticLeafComplete || replayDriverException) then
                RetryDrainDeferGlobalFuseLiveReplay
            else
                RetryDrainPinTerminal

        let retryStopFrontierDecisionFor replayOrLiveTerminal terminalReplayContractBlocked terminalGlobalFuseParentContinuationBlocked terminalDynamicJoinApplyBlocked terminalParentReplayStatusPreservedBlocked replayStillRunnable pendingCount queueDepth activeDepth hasProgressYield frontierUsed frontierCap globalFuseUsed globalFuseCap dynamicJoinUsed dynamicJoinCap =
            if not replayOrLiveTerminal then RetryStopNoReplay
            elif terminalParentReplayStatusPreservedBlocked then RetryStopTerminalContractAbort
            elif terminalGlobalFuseParentContinuationBlocked && pendingCount > 0 && activeDepth > 0 && globalFuseUsed < (globalFuseCap * 2) then RetryStopGlobalFusePendingStackFenceDrain
            elif terminalDynamicJoinApplyBlocked && pendingCount > 0 && activeDepth > 0 && dynamicJoinUsed < (dynamicJoinCap * 2) then RetryStopDynamicJoinPendingStackFenceDrain
            elif terminalGlobalFuseParentContinuationBlocked && replayStillRunnable && pendingCount > 0 && hasProgressYield && globalFuseUsed < globalFuseCap then RetryStopGlobalFuseLiveDrain
            elif terminalGlobalFuseParentContinuationBlocked && replayStillRunnable && pendingCount > 0 && queueDepth > 0 && globalFuseUsed < globalFuseCap then RetryStopGlobalFuseLiveQueueDrain
            elif terminalDynamicJoinApplyBlocked && replayStillRunnable && pendingCount > 0 && hasProgressYield && dynamicJoinUsed < dynamicJoinCap then RetryStopDynamicJoinLiveDrain
            elif terminalDynamicJoinApplyBlocked && replayStillRunnable && pendingCount > 0 && dynamicJoinUsed < dynamicJoinCap then RetryStopDynamicJoinLiveQueueDrain
            elif terminalReplayContractBlocked then RetryStopTerminalContractAbort
            elif hasProgressYield && frontierUsed < frontierCap then RetryStopProgressYield
            else RetryStopBlockedAbort


        type SemanticTerminalContract = {
            rank: int
            next: ReplayCommitNextId
        }

        let private replayTerminalNext statusId =
            ReplayNextSemanticStatus statusId

        let private semanticTerminalContract status =
            match status with
            | SemanticMacroThunkMissingBlocked -> Some { rank = 100; next = replayTerminalNext SemanticMacroThunkMissingBlocked }
            | SemanticCodegenJpBodyDictMissingBlocked -> Some { rank = 99; next = replayTerminalNext SemanticCodegenJpBodyDictMissingBlocked }
            | SemanticErrorTypeBlocked -> Some { rank = 96; next = replayTerminalNext SemanticErrorTypeBlocked }
            | SemanticLiteralOpBodyStepperBlocked -> Some { rank = 95; next = replayTerminalNext SemanticLiteralOpBodyStepperBlocked }
            | SemanticOpImplRequiredBlocked -> Some { rank = 94; next = replayTerminalNext SemanticOpImplRequiredBlocked }
            | SemanticApplySeqUnknownReturnWitnessBlocked -> Some { rank = 93; next = replayTerminalNext SemanticApplySeqUnknownReturnWitnessBlocked }
            | SemanticApplyContinuationAfterSeqUnknownBlocked -> Some { rank = 92; next = replayTerminalNext SemanticApplyContinuationAfterSeqUnknownBlocked }
            | SemanticDynamicJoinApplyBlocked -> Some { rank = 92; next = replayTerminalNext SemanticDynamicJoinApplyBlocked }
            | SemanticApplySpineMissingDirectValueBlocked -> Some { rank = 92; next = replayTerminalNext SemanticApplySpineMissingDirectValueBlocked }
            // MIGRATION: sidecar prefetch can prove that the explicit worklist has no frame
            // for a concrete recursive term/type key while BigStack has no scheduler work.
            // Rank it high enough to stop the multi-minute hot-frontier loop, but still
            // below concrete op/apply/dynamic-join obligations.
            | SemanticMissingAfterPrefetchBlocked -> Some { rank = 91; next = replayTerminalNext SemanticMissingAfterPrefetchBlocked }
            | SemanticSeqUnknownReturnWitnessBlocked -> Some { rank = 91; next = replayTerminalNext SemanticSeqUnknownReturnWitnessBlocked }
            | SemanticIfUnknownReturnConditionBlocked -> Some { rank = 90; next = replayTerminalNext SemanticIfUnknownReturnConditionBlocked }
            | SemanticIfSymbolicConditionBlocked -> Some { rank = 89; next = replayTerminalNext SemanticIfSymbolicConditionBlocked }
            | SemanticRecordWithValueBlocked -> Some { rank = 88; next = replayTerminalNext SemanticRecordWithValueBlocked }
            | SemanticAnnotTestBranchSelectionBlocked -> Some { rank = 87; next = replayTerminalNext SemanticAnnotTestBranchSelectionBlocked }
            | SemanticUnboxReplayBlocked -> Some { rank = 87; next = replayTerminalNext SemanticUnboxReplayBlocked }
            | SemanticTypeApplyNominalConstructorStepperBlocked -> Some { rank = 87; next = replayTerminalNext SemanticTypeApplyNominalConstructorStepperBlocked }
            | SemanticNominalConstructorStepperBlocked -> Some { rank = 86; next = replayTerminalNext SemanticNominalConstructorStepperBlocked }
            | SemanticTermTypeValueBlocked -> Some { rank = 86; next = replayTerminalNext SemanticTermTypeValueBlocked }
            | SemanticReplayChildScheduleRepeatBlocked -> Some { rank = 85; next = replayTerminalNext SemanticReplayChildScheduleRepeatBlocked }
            | SemanticPairValueBlocked -> Some { rank = 84; next = replayTerminalNext SemanticPairValueBlocked }
            | SemanticTypeApplyNestedForallStepperBlocked -> Some { rank = 84; next = replayTerminalNext SemanticTypeApplyNestedForallStepperBlocked }
            | SemanticSeqTypeErrorBlocked -> Some { rank = 83; next = replayTerminalNext SemanticSeqTypeErrorBlocked }
            | SemanticLeafParentContinuationMissingBlocked -> Some { rank = 82; next = replayTerminalNext SemanticLeafParentContinuationMissingBlocked }
            | SemanticUnitTestValueBlocked -> Some { rank = 82; next = replayTerminalNext SemanticUnitTestValueBlocked }
            | SemanticTypeApplyForallBodyStepperBlocked -> Some { rank = 81; next = replayTerminalNext SemanticTypeApplyForallBodyStepperBlocked }
            | SemanticTypeVariableValueMissingBlocked -> Some { rank = 80; next = replayTerminalNext SemanticTypeVariableValueMissingBlocked }
            | SemanticApplyContinuationExceptionBlocked -> Some { rank = 79; next = replayTerminalNext SemanticApplyContinuationExceptionBlocked }
            | SemanticReplayFingerprintRepeatBlocked -> Some { rank = 79; next = ReplayNextReplayFingerprintRepeatDirectRequired }
            // MIGRATION: historical runtime emitted this bounded terminal 21 times but
            // highRankPinnedTerminal only retargets ranks >= 80.  Rank it at the
            // high-rank boundary so the existing pinned-terminal retarget path can
            // stop the manual-interrupt loop without inventing a value or BuildOk.
            | SemanticGlobalFuseParentContinuationCycleBlocked -> Some { rank = 80; next = replayTerminalNext SemanticGlobalFuseParentContinuationCycleBlocked }
            // MIGRATION: the MIGRATION frontier is not the older blocked global-fuse case;
            // it is a deferred-child parent-continuation cycle that becomes Phase 2
            // material once q/a/p reaches 2/0/1.  Rank it above parent replay poison
            // so the transition hook can see it explicitly.
            | SemanticParentContinuationCycleDeferred -> Some { rank = 90; next = replayTerminalNext SemanticParentContinuationCycleDeferred }
            | SemanticParentReplayCycleBreakPoisoned -> Some { rank = 91; next = replayTerminalNext SemanticParentReplayCycleBreakPoisoned }
            | SemanticParentReplayStatusPreservedRepeatBlocked -> Some { rank = 88; next = replayTerminalNext SemanticParentReplayStatusPreservedRepeatBlocked }
            | SemanticReentrantReplayDriverStarvationBlocked -> Some { rank = 78; next = replayTerminalNext SemanticReentrantReplayDriverStarvationBlocked }
            | SemanticRootCompleteStaleRetargetPendingNoQueueBlocked -> Some { rank = 77; next = replayTerminalNext SemanticRootCompleteStaleRetargetPendingNoQueueBlocked }
            | SemanticRootCompleteStaleRetargetRepeatBlocked -> Some { rank = 77; next = replayTerminalNext SemanticRootCompleteStaleRetargetRepeatBlocked }
            | SemanticAppRootBase16StaleRetargetHardcapBlocked -> Some { rank = 76; next = replayTerminalNext SemanticAppRootBase16StaleRetargetHardcapBlocked }
            | SemanticRootCompletePendingJobsBlocked -> Some { rank = 76; next = replayTerminalNext SemanticRootCompletePendingJobsBlocked }
            | SemanticSelectedFrontierRepeatBlocked -> Some { rank = 76; next = replayTerminalNext SemanticSelectedFrontierRepeatBlocked }
            | SemanticTjoinpointStepperBlocked -> Some { rank = 75; next = replayTerminalNext SemanticTjoinpointStepperBlocked }
            // MIGRATION: historical runtime pinned semantic_joinpoint_value_blocked repeatedly but
            // rank 74 let higher-rank generic/global-fuse evidence keep the build alive until
            // manual interruption.  This is now a concrete missing EJoinPoint' value terminal.
            | SemanticJoinpointValueBlocked -> Some { rank = 81; next = replayTerminalNext SemanticJoinpointValueBlocked }
            | SemanticJoinpointTermStepperBlocked -> Some { rank = 72; next = ReplayNextJoinpointTermStepperDirectRequired }
            | SemanticReplayPayloadMissingBlocked -> Some { rank = 69; next = replayTerminalNext SemanticReplayPayloadMissingBlocked }
            // MIGRATION: historical runtime showed a concrete replay-driver NullReferenceException
            // arriving after a generic rank-80 global-fuse pin. Rank this above global-fuse
            // and annot-test/unbox diagnostics, but still below concrete op/codegen terminals.
            | SemanticReplayDriverExceptionBlocked -> Some { rank = 88; next = replayTerminalNext SemanticReplayDriverExceptionBlocked }
            | SemanticRootCompleteStaleRetargetLiveReplayLivelockBlocked -> Some { rank = 91; next = replayTerminalNext SemanticRootCompleteStaleRetargetLiveReplayLivelockBlocked }
            | SemanticParentContinuationCycleBlocked -> Some { rank = 60; next = replayTerminalNext SemanticParentContinuationCycleBlocked }
            | SemanticStaleRootRetargetBlocked -> Some { rank = 55; next = replayTerminalNext SemanticStaleRootRetargetBlocked }
            | SemanticLetSuccessAllReadyApplyBlocked -> Some { rank = 45; next = replayTerminalNext SemanticLetSuccessAllReadyApplyBlocked }
            | SemanticDeferredFunctionReplayExceptionBlocked -> Some { rank = 40; next = replayTerminalNext SemanticDeferredFunctionReplayExceptionBlocked }
            | SemanticLetSuccessApplyContinuationBlocked -> Some { rank = 35; next = replayTerminalNext SemanticLetSuccessApplyContinuationBlocked }
            | SemanticLetSuccessApplyExceptionBlocked -> Some { rank = 30; next = replayTerminalNext SemanticLetSuccessApplyExceptionBlocked }
            | _ -> None


        // Keep BigStack terminal handoff decisions typed internally: callers still
        // receive legacy status text from Frame.status, but branch selection is a
        // closed DU instead of ad-hoc string equality.
        type BigStackPinnedTerminalStatus =
            | BigStackPinnedConcreteOpTerminal
            | BigStackPinnedGlobalFuseTerminal
            | BigStackPinnedOtherTerminal

        let bigStackPinnedTerminalStatus (statusId: SemanticStatusId) =
            match statusId with
            | SemanticOpImplRequiredBlocked -> BigStackPinnedConcreteOpTerminal
            | SemanticGlobalFuseParentContinuationCycleBlocked -> BigStackPinnedGlobalFuseTerminal
            | _ -> BigStackPinnedOtherTerminal

        // MIGRATION: MIGRATION proved that terminal_cause_du is emitted correctly,
        // but the BigStack join still accepted a just-pinned rank-80 parent-continuation
        // global-fuse terminal at terminal_age=0ms while pending replay/root returns were
        // still draining.  Keep the fail-closed terminal, but make that handoff a typed
        // decision and give young pending parent-continuation pins one bounded drain lease.
        type BigStackPinnedTerminalHandoffDecisionId =
            | BigStackPinnedTerminalHandoffReady
            | BigStackPinnedTerminalDeferYoungPendingParentContinuationFuse

        let bigStackPinnedTerminalHandoffDecisionText = function
            | BigStackPinnedTerminalHandoffReady -> "handoff_ready"
            | BigStackPinnedTerminalDeferYoungPendingParentContinuationFuse -> "defer_young_pending_parent_continuation_fuse"

        let bigStackPinnedTerminalHandoffDecisionFor (statusId: SemanticStatusId) pendingCount terminalAgeMs youngPendingAgeCapMs =
            match statusId with
            | SemanticGlobalFuseParentContinuationCycleBlocked when pendingCount > 0 && terminalAgeMs < youngPendingAgeCapMs ->
                BigStackPinnedTerminalDeferYoungPendingParentContinuationFuse
            | _ -> BigStackPinnedTerminalHandoffReady

        type BigStackPinnedTerminalQueueDrainDecisionId =
            | BigStackPinnedTerminalQueueDrainNotNeeded
            | BigStackPinnedTerminalQueueDrainPoisonTail
            | BigStackPinnedTerminalQueueDrainStatusPreservedTail
            | BigStackPinnedTerminalQueueDrainPendingTail
            | BigStackPinnedTerminalQueueDrainDynamicJoinTail
            | BigStackPinnedTerminalQueueDrainYoungTerminalTail
            | BigStackPinnedTerminalQueueDrainLateRaceTail
            | BigStackPinnedTerminalQueueDrainActiveOnlyGrace
            | BigStackPinnedTerminalQueueDrainQuietPoisonGrace
            | BigStackPinnedTerminalQueueDrainQuietStatusPreservedGrace
            | BigStackPinnedTerminalQueueDrainReplayIncompletePendingTail
            | BigStackPinnedTerminalQueueDrainParentPoisonPendingStackFenceTail
            | BigStackPinnedTerminalQueueDrainParentPoisonActiveQueueTail

        let bigStackPinnedTerminalQueueDrainDecisionText = function
            | BigStackPinnedTerminalQueueDrainNotNeeded -> "queue_drain_not_needed"
            | BigStackPinnedTerminalQueueDrainPoisonTail -> "poison_tail_queue_drain"
            | BigStackPinnedTerminalQueueDrainStatusPreservedTail -> "status_preserved_tail_queue_drain"
            | BigStackPinnedTerminalQueueDrainPendingTail -> "pending_tail_queue_drain"
            | BigStackPinnedTerminalQueueDrainDynamicJoinTail -> "dynamic_join_tail_queue_drain"
            | BigStackPinnedTerminalQueueDrainYoungTerminalTail -> "young_terminal_tail_queue_drain"
            | BigStackPinnedTerminalQueueDrainLateRaceTail -> "late_race_tail_queue_drain"
            | BigStackPinnedTerminalQueueDrainActiveOnlyGrace -> "active_only_tail_grace"
            | BigStackPinnedTerminalQueueDrainQuietPoisonGrace -> "quiet_poison_terminal_grace"
            | BigStackPinnedTerminalQueueDrainQuietStatusPreservedGrace -> "quiet_status_preserved_terminal_grace"
            | BigStackPinnedTerminalQueueDrainReplayIncompletePendingTail -> "replay_incomplete_pending_tail"
            | BigStackPinnedTerminalQueueDrainParentPoisonPendingStackFenceTail -> "parent_poison_pending_stack_fence_tail"
            | BigStackPinnedTerminalQueueDrainParentPoisonActiveQueueTail -> "parent_poison_active_queue_tail"

        let bigStackPinnedTerminalQueueDrainDecisionFor (statusId: SemanticStatusId) pendingCount queueDepth activeDepth terminalAgeMs queueDrainAgeCapMs replayComplete =
            let tailLive = pendingCount > 0 || queueDepth > 0 || activeDepth > 0
            let activeOnlyTail = pendingCount <= 0 && queueDepth <= 0 && activeDepth > 0
            let shortPoisonTailAgeCapMs = min queueDrainAgeCapMs 500
            let quietPoisonAgeCapMs = 0
            let statusPreservedTailAgeCapMs = min queueDrainAgeCapMs 3000
            let dynamicJoinTailAgeCapMs = min queueDrainAgeCapMs 6000
            match statusId with
            | SemanticParentReplayCycleBreakPoisoned when tailLive && terminalAgeMs < shortPoisonTailAgeCapMs ->
                BigStackPinnedTerminalQueueDrainPoisonTail
            | SemanticParentReplayCycleBreakPoisoned when pendingCount > 0 && activeDepth > 0 && terminalAgeMs < max queueDrainAgeCapMs 60000 ->
                // MIGRATION: 1486.jsonl proved replay_complete/write_witness can flicker true
                // while p=2/a>0 are still behind a stack fence.  Do not let the legacy
                // old-poison 3s fail-closed branch snap before the pending fence gets its
                // bounded IVar/Alt-style drain window.
                BigStackPinnedTerminalQueueDrainParentPoisonPendingStackFenceTail
            | SemanticParentReplayCycleBreakPoisoned when (not replayComplete) && pendingCount > 0 && queueDepth <= 0 && activeDepth > 0 && terminalAgeMs >= 12000 ->
                // MIGRATION: pending work is not a drain license after the queue is empty,
                // active workers are only a quiescent tail, and the pinned poison has aged.
                // Surface through the normal terminal handoff instead of replay-only chatter.
                BigStackPinnedTerminalQueueDrainNotNeeded
            | SemanticParentReplayCycleBreakPoisoned when (not replayComplete) && pendingCount = 0 && queueDepth >= 16 && activeDepth > 0 && terminalAgeMs < max queueDrainAgeCapMs 60000 ->
                // MIGRATION: 1488.jsonl moved beyond the dynamic-join frontier, then pinned
                // parent poison at pending=0 while queue≈98/active=4 and replay commits were
                // still arriving.  Pending-zero is not automatically quiet when the active
                // queue is materially draining; give it one bounded active-queue lease before
                // the legacy old_poison_tail_fail_closed handoff may surface EJP0021.
                BigStackPinnedTerminalQueueDrainParentPoisonActiveQueueTail
            | SemanticParentReplayCycleBreakPoisoned when (not replayComplete) && pendingCount > 0 && terminalAgeMs < max queueDrainAgeCapMs 60000 ->
                // MIGRATION: historical runtime reached a generic ty_replay_driver/TFun pinned terminal
                // with pending=2 queue=2 and replay_complete=false.  The old poison branch
                // treated that as mature after the short 500ms poison-tail grace; keep draining
                // pending replay completeness instead of surfacing EJP0021 while work is owned.
                BigStackPinnedTerminalQueueDrainReplayIncompletePendingTail
            | SemanticParentReplayCycleBreakPoisoned when (not replayComplete) && terminalAgeMs < quietPoisonAgeCapMs ->
                // MIGRATION: historical runtime reached pending=0/q=0/a=0 with replay_complete=false,
                // then near-simultaneous child replay scheduling and poison cascades still appeared
                // around the terminal handoff. Treat that as a quiet drain window, not proof that
                // EJP0021 is mature.
                BigStackPinnedTerminalQueueDrainQuietPoisonGrace
            | SemanticParentReplayCycleBreakPoisoned when tailLive ->
                // MIGRATION: MIGRATION kept a poisoned terminal alive for hundreds of
                // seconds because the old queueDrainAgeCapMs still allowed poison_tail_queue_drain
                // until the late-race window.  Once the short poison-tail grace expires,
                // surface the fail-closed terminal instead of recycling stale tail churn.
                BigStackPinnedTerminalQueueDrainNotNeeded
            | SemanticParentReplayStatusPreservedRepeatBlocked when tailLive && terminalAgeMs < statusPreservedTailAgeCapMs ->
                BigStackPinnedTerminalQueueDrainStatusPreservedTail
            | SemanticParentReplayStatusPreservedRepeatBlocked when (not replayComplete) && terminalAgeMs < quietPoisonAgeCapMs ->
                BigStackPinnedTerminalQueueDrainQuietStatusPreservedGrace
            | SemanticDynamicJoinApplyBlocked when tailLive && terminalAgeMs < dynamicJoinTailAgeCapMs ->
                // MIGRATION: historical runtime reached rank-92 dynamic join with p/q/a shrinking to 1/4/0
                // and only replay trickle/terminal churn left. Give that tail one small bounded drain
                // window, then surface the explicit dynamic-join obligation instead of recycling the
                // late-race queue drain forever.
                BigStackPinnedTerminalQueueDrainDynamicJoinTail
            | SemanticDynamicJoinApplyBlocked when tailLive ->
                BigStackPinnedTerminalQueueDrainNotNeeded
            | _ when activeOnlyTail && terminalAgeMs < queueDrainAgeCapMs ->
                BigStackPinnedTerminalQueueDrainActiveOnlyGrace
            | _ when activeOnlyTail ->
                // MIGRATION: q=0/p=0/a>0 for an old pinned terminal is not a schedulable orphan
                // drain.  Historical runtime kept requesting four forced workers every 250ms while
                // each returned scheduled_async=false; after the bounded grace, surface the
                // fail-closed terminal instead of hiding it behind infinite late-race drain.
                BigStackPinnedTerminalQueueDrainNotNeeded
            | _ when not tailLive -> BigStackPinnedTerminalQueueDrainNotNeeded
            | _ when pendingCount > 0 && terminalAgeMs < queueDrainAgeCapMs ->
                BigStackPinnedTerminalQueueDrainPendingTail
            | _ when terminalAgeMs < min queueDrainAgeCapMs 4000 ->
                BigStackPinnedTerminalQueueDrainYoungTerminalTail
            | _ when queueDepth > 0 && terminalAgeMs < max queueDrainAgeCapMs 8000 ->
                BigStackPinnedTerminalQueueDrainLateRaceTail
            | _ when tailLive ->
                // MIGRATION: if a poisoned/status-preserved terminal is old and the only
                // evidence is a tiny persistent tail, another late-race drain just emits
                // unschedulable orphan workers.  Let the caller surface the terminal contract.
                BigStackPinnedTerminalQueueDrainNotNeeded
            | _ -> BigStackPinnedTerminalQueueDrainNotNeeded

        let isRootCompleteStaleRetargetLiveReplayLivelockStatus (statusId: SemanticStatusId) =
            match statusId with
            | SemanticRootCompleteStaleRetargetLiveReplayLivelockBlocked -> true
            | _ -> false

        // MIGRATION: make the late BigStack stale-retarget handoff a typed decision.
        // Runtime evidence proved the old Boolean gate was too narrow: replay_complete/write_witness
        // can flip true while the selected replay cell still reports replay_completeness=not_complete
        // and the rich tick is still seeing replay/root/terminal deltas.  This DU keeps the old
        // fail-closed terminal, but defers it while there is either directly runnable replay or
        // fresh replay/root/terminal progress around the captured root-stale-retarget terminal.
        type RootStaleRetargetHandoffDecisionId =
            | RootStaleRetargetNotTerminal
            | RootStaleRetargetDeferActiveReplay
            | RootStaleRetargetDeferRecentReplayProgress
            | RootStaleRetargetDeferDynamicRecordKeyBridgeTail
            | RootStaleRetargetPoisonCascadeHandoffReady
            | RootStaleRetargetTerminalChurnHandoffReady
            | RootStaleRetargetDeferredChildLivelockHandoffReady
            | RootStaleRetargetDeferredHoleSweepRequired
            | RootStaleRetargetDurableActiveReplayHandoffReady
            | RootStaleRetargetHandoffReady

        let rootStaleRetargetHandoffDecisionText = function
            | RootStaleRetargetNotTerminal -> "not_terminal"
            | RootStaleRetargetDeferActiveReplay -> "defer_active_replay"
            | RootStaleRetargetDeferRecentReplayProgress -> "defer_recent_replay_progress"
            | RootStaleRetargetDeferDynamicRecordKeyBridgeTail -> "defer_dynamic_record_key_bridge_tail"
            | RootStaleRetargetPoisonCascadeHandoffReady -> "poison_cascade_handoff_ready"
            | RootStaleRetargetTerminalChurnHandoffReady -> "terminal_churn_handoff_ready"
            | RootStaleRetargetDeferredChildLivelockHandoffReady -> "deferred_child_livelock_handoff_ready"
            | RootStaleRetargetDeferredHoleSweepRequired -> "deferred_hole_sweep_required"
            | RootStaleRetargetDurableActiveReplayHandoffReady -> "durable_active_replay_handoff_ready"
            | RootStaleRetargetHandoffReady -> "handoff_ready"

        type RootStaleRetargetReasonSignalId =
            | RootStaleRetargetReasonDeferredChild
            | RootStaleRetargetReasonDeferredType
            | RootStaleRetargetReasonHole
            | RootStaleRetargetReasonTerminalPoisonCascade
            | RootStaleRetargetReasonAppRootFinalizationSelfLoop

        let private rootStaleRetargetReasonSignalsFromFacts (facts:Set<DiagnosticClassifier.DiagnosticFactId>) =
            [ if Set.contains DiagnosticClassifier.DiagnosticDeferredChildCell facts then
                  RootStaleRetargetReasonDeferredChild
              if Set.contains DiagnosticClassifier.DiagnosticDeferredType facts then
                  RootStaleRetargetReasonDeferredType
              if Set.contains DiagnosticClassifier.DiagnosticHole facts then
                  RootStaleRetargetReasonHole
              if Set.contains DiagnosticClassifier.DiagnosticTerminalPoisonCascade facts then
                  RootStaleRetargetReasonTerminalPoisonCascade
              if Set.contains DiagnosticClassifier.DiagnosticAppRootFinalizationSelfLoop facts then
                  RootStaleRetargetReasonAppRootFinalizationSelfLoop ]
            |> Set.ofList

        let rootStaleRetargetReasonLooksDeferredChild signals =
            Set.contains RootStaleRetargetReasonDeferredChild signals

        let rootStaleRetargetReasonLooksDeferredHoleSweepCandidate signals =
            rootStaleRetargetReasonLooksDeferredChild signals
            || Set.contains RootStaleRetargetReasonDeferredType signals
            || Set.contains RootStaleRetargetReasonHole signals

        let rootStaleRetargetHandoffDecisionFor (statusId: SemanticStatusId) (reasonFacts: Set<DiagnosticClassifier.DiagnosticFactId>) (pendingCount: int) (queueDepth: int) (activeDepth: int) (progressYield: bool) (replayComplete: bool) (writeWitness: bool) (terminalAgeMs: int) (ageCapMs: int) (recentProgress: bool) (recentSampledDelta: int64) (recentRootDelta: int64) (recentTerminalDelta: int64) (richTickAgeMs: int) (dynamicRecordKeyBridgeTailLive: bool) =
            let reasonSignals = rootStaleRetargetReasonSignalsFromFacts reasonFacts
            let rootDeferredHoleSweepEligibleStatus =
                statusId = SemanticRootCompleteStaleRetargetLiveReplayLivelockBlocked
                || statusId = SemanticRootComplete
            let liveRootStaleRetarget =
                pendingCount > 0
                && not replayComplete
                && activeDepth = 0
                && queueDepth <= 16
            let noSampledOrRootAuthority =
                recentSampledDelta <= 0L
                && recentRootDelta <= 0L
            let deferredChildReason =
                rootStaleRetargetReasonLooksDeferredChild reasonSignals
            let deferredHoleSweepCandidate =
                rootStaleRetargetReasonLooksDeferredHoleSweepCandidate reasonSignals
            let terminalOrReplayChurn =
                recentTerminalDelta > 0L
                || progressYield
                || richTickAgeMs >= (min ageCapMs 8000)
            if not rootDeferredHoleSweepEligibleStatus then RootStaleRetargetNotTerminal
            elif Set.contains RootStaleRetargetReasonTerminalPoisonCascade reasonSignals
                 && Set.contains RootStaleRetargetReasonAppRootFinalizationSelfLoop reasonSignals
                 && liveRootStaleRetarget then
                // MIGRATION: MIGRATION proved the poison is now correctly detected by the replay
                // driver, but the app-root stale-retarget gate kept treating the resulting
                // terminal/replay churn as live progress.  Once a poisoned child cascade reaches the rank-88 root-stale-retarget
                // self-loop with no active driver,
                // surface the explicit terminal instead of re-opening grace forever.
                RootStaleRetargetPoisonCascadeHandoffReady
            elif deferredHoleSweepCandidate
                 && liveRootStaleRetarget
                 && noSampledOrRootAuthority then
                // MIGRATION: move toward the assessment's phase-2 synchronous sweep direction
                // without fabricating witness completion.  When the app-root stale-retarget seam
                // is parked on deferred-child/type-hole evidence with no active driver, expose a
                // dedicated sweep-required decision.  A later real implementation can attach an
                // owned DeferredTypeVar registry here; this round only names the authority boundary.
                RootStaleRetargetDeferredHoleSweepRequired
            elif deferredChildReason
                 && liveRootStaleRetarget
                 && noSampledOrRootAuthority then
                // MIGRATION: historical runtime reached semantic_root_complete with active=0, pending=2,
                // low queue, replay_complete=false, and reason=idle_deferred_child_cell.  That is
                // the same rank-88 root-stale-retarget livelock, but it lacks the poison-cascade
                // substrings MIGRATION required.  Terminal/replay churn cannot keep this deferred
                // child root parked forever; surface the explicit terminal contract fail-closed.
                RootStaleRetargetDeferredChildLivelockHandoffReady
            elif (Set.contains RootStaleRetargetReasonAppRootFinalizationSelfLoop reasonSignals
                  || deferredChildReason)
                 && liveRootStaleRetarget
                 && noSampledOrRootAuthority
                 && terminalOrReplayChurn then
                // MIGRATION: widen the MIGRATION terminal-churn path to include deferred-child
                // root-stale-retarget reasons and rich-busy windows where the terminal delta may
                // not line up on the exact decision tick.
                RootStaleRetargetTerminalChurnHandoffReady
            elif dynamicRecordKeyBridgeTailLive
                 && pendingCount > 0
                 && not replayComplete
                 && not writeWitness
                 && terminalAgeMs < ageCapMs * 2
                 && (queueDepth > 0 || activeDepth > 0 || progressYield || recentProgress) then
                // MIGRATION: MIGRATION threaded dynamic-record-key bridge evidence into the
                // root-stale retarget call before the function accepted it, causing FS0003.
                // Keep the fix typed: a live dynamic-key bridge tail is its own handoff DU,
                // not another stringly active-replay grace or a positional spare argument.
                RootStaleRetargetDeferDynamicRecordKeyBridgeTail
            elif pendingCount > 0 && not replayComplete && terminalAgeMs < ageCapMs && (queueDepth > 0 || activeDepth > 0 || progressYield) then RootStaleRetargetDeferActiveReplay
            elif pendingCount > 0 && replayComplete && writeWitness && terminalAgeMs < ageCapMs && recentProgress then RootStaleRetargetDeferRecentReplayProgress
            else RootStaleRetargetHandoffReady

        // MIGRATION: 1172 moved the late frontier to a symbolic-if terminal while
        // replay was still pending/runnable.  Keep symbolic-if as a concrete
        // terminal, but gate BigStack handoff through a typed live-replay decision
        // instead of file-specific or status-string special cases.
        type SymbolicIfHandoffDecisionId =
            | SymbolicIfNotTerminal
            | SymbolicIfDeferActiveReplay
            | SymbolicIfDeferRecentReplayProgress
            | SymbolicIfHandoffReady

        let symbolicIfHandoffDecisionText = function
            | SymbolicIfNotTerminal -> "not_terminal"
            | SymbolicIfDeferActiveReplay -> "defer_active_replay"
            | SymbolicIfDeferRecentReplayProgress -> "defer_recent_replay_progress"
            | SymbolicIfHandoffReady -> "handoff_ready"

        let symbolicIfHandoffDecisionFor (statusId: SemanticStatusId) pendingCount queueDepth activeDepth progressYield replayComplete terminalAgeMs ageCapMs recentProgress =
            match statusId with
            | SemanticIfSymbolicConditionBlocked when pendingCount > 0 && not replayComplete && terminalAgeMs < ageCapMs && (queueDepth > 0 || activeDepth > 0 || progressYield) -> SymbolicIfDeferActiveReplay
            | SemanticIfSymbolicConditionBlocked when pendingCount > 0 && terminalAgeMs < ageCapMs && recentProgress -> SymbolicIfDeferRecentReplayProgress
            | SemanticIfSymbolicConditionBlocked -> SymbolicIfHandoffReady
            | _ -> SymbolicIfNotTerminal

        // Unknown-return if terminals are concrete diagnostics, but they are not
        // allowed to outrank a still-pending replay driver in the same bounded
        // join window.  This is intentionally structural: status + pending/replay
        // evidence only, no source path or application-specific case.
        type IfUnknownReturnHandoffDecisionId =
            | IfUnknownReturnNotTerminal
            | IfUnknownReturnDeferPendingReplay
            | IfUnknownReturnDeferPhysicalQueueReplay
            | IfUnknownReturnDeferRecentReplayProgress
            | IfUnknownReturnShadowTimeoutPierceRepeatCap
            | IfUnknownReturnShadowTimeoutPierceAbsentSidecar
            | IfUnknownReturnHandoffReady

        let ifUnknownReturnHandoffDecisionText = function
            | IfUnknownReturnNotTerminal -> "not_terminal"
            | IfUnknownReturnDeferPendingReplay -> "defer_pending_replay"
            | IfUnknownReturnDeferPhysicalQueueReplay -> "defer_physical_queue_replay"
            | IfUnknownReturnDeferRecentReplayProgress -> "defer_recent_replay_progress"
            | IfUnknownReturnShadowTimeoutPierceRepeatCap -> "shadow_timeout_pierce_repeat_cap"
            | IfUnknownReturnShadowTimeoutPierceAbsentSidecar -> "shadow_timeout_pierce_absent_sidecar_repeat_cap"
            | IfUnknownReturnHandoffReady -> "handoff_ready"

        let ifUnknownReturnHandoffDecisionFor (statusId: SemanticStatusId) pendingCount queueDepth activeDepth progressYield replayComplete terminalAgeMs ageCapMs recentProgress =
            match statusId with
            | SemanticIfUnknownReturnConditionBlocked when pendingCount > 0 && not replayComplete && terminalAgeMs < ageCapMs -> IfUnknownReturnDeferPendingReplay
            | SemanticIfUnknownReturnConditionBlocked when pendingCount <= 0 && not replayComplete && terminalAgeMs < ageCapMs && (queueDepth >= 16 || activeDepth > 0 || progressYield) -> IfUnknownReturnDeferPhysicalQueueReplay
            | SemanticIfUnknownReturnConditionBlocked when terminalAgeMs >= ageCapMs && pendingCount <= 0 && queueDepth > 0 && activeDepth > 0 && not replayComplete -> IfUnknownReturnShadowTimeoutPierceRepeatCap
            | SemanticIfUnknownReturnConditionBlocked when pendingCount > 0 && terminalAgeMs < ageCapMs && (queueDepth > 0 || activeDepth > 0 || progressYield || recentProgress) -> IfUnknownReturnDeferRecentReplayProgress
            | SemanticIfUnknownReturnConditionBlocked -> IfUnknownReturnHandoffReady
            | _ -> IfUnknownReturnNotTerminal

        // MIGRATION: 1173 proved symbolic-if moved on, but the next rank-94
        // op-implementation terminal was still handed to BigStack while pending
        // replay and fresh replay/root/terminal deltas existed. Keep it generic:
        // no .spi path is mentioned; only the semantic status and replay evidence
        // drive the handoff decision.
        type OpImplReplayLivenessId =
            | OpImplReplayNoLive
            | OpImplReplayPendingOnly
            | OpImplReplayQueueLive
            | OpImplReplayActiveDriverLive
            | OpImplReplayProgressYieldLive

        let opImplReplayLivenessText = function
            | OpImplReplayNoLive -> "no_live_replay"
            | OpImplReplayPendingOnly -> "pending_only"
            | OpImplReplayQueueLive -> "queue_live"
            | OpImplReplayActiveDriverLive -> "active_driver_live"
            | OpImplReplayProgressYieldLive -> "progress_yield_live"

        let opImplReplayLivenessFor pendingCount queueDepth activeDepth progressYield =
            if progressYield then OpImplReplayProgressYieldLive
            elif activeDepth > 0 then OpImplReplayActiveDriverLive
            elif queueDepth > 0 then OpImplReplayQueueLive
            elif pendingCount > 0 then OpImplReplayPendingOnly
            else OpImplReplayNoLive

        // MIGRATION: make the assessment arbitration explicit.  The top-level
        // MIGRATION mandate says op_impl_required is a hard semantic authoring blocker,
        // even when live replay looks healthy.  Keep the contradictory pending-zero
        // live-tail note visible as policy data instead of letting it silently win.
        type OpImplSemanticTerminalPolicyId =
            | OpImplSemanticNotTerminal
            | OpImplSemanticHardAuthoringBlocker
            | OpImplSemanticSoftReplayDeferrable

        let opImplSemanticTerminalPolicyText = function
            | OpImplSemanticNotTerminal -> "not_terminal"
            | OpImplSemanticHardAuthoringBlocker -> "hard_authoring_blocker"
            | OpImplSemanticSoftReplayDeferrable -> "soft_replay_deferrable"

        let opImplSemanticTerminalPolicyFor (statusId: SemanticStatusId) =
            match statusId with
            | SemanticOpImplRequiredBlocked -> OpImplSemanticHardAuthoringBlocker
            | _ -> OpImplSemanticNotTerminal

        type OpImplProgressDeltaClassId =
            | OpImplDeltaNone
            | OpImplDeltaReplayChatterOnly
            | OpImplDeltaRootOrSampledWork
            | OpImplDeltaTerminalOnly

        let opImplProgressDeltaClassText = function
            | OpImplDeltaNone -> "none"
            | OpImplDeltaReplayChatterOnly -> "replay_chatter_only"
            | OpImplDeltaRootOrSampledWork -> "root_or_sampled_work"
            | OpImplDeltaTerminalOnly -> "terminal_only"

        let opImplProgressDeltaClassFor sampledDelta replayDelta rootDelta terminalDelta =
            if sampledDelta > 0L || rootDelta > 0L then OpImplDeltaRootOrSampledWork
            elif replayDelta > 0L then OpImplDeltaReplayChatterOnly
            elif terminalDelta > 0L then OpImplDeltaTerminalOnly
            else OpImplDeltaNone

        type TerminalDeferralEligibilityId =
            | TerminalDeferralNotEvaluated
            | TerminalDeferralHardSemanticNotDeferrable
            | TerminalDeferralWriterWitnessRequired
            | TerminalDeferralLiveReplayWouldDeferSoftTerminal
            | TerminalDeferralQuietTerminalCanSurface

        let terminalDeferralEligibilityText = function
            | TerminalDeferralNotEvaluated -> "not_evaluated"
            | TerminalDeferralHardSemanticNotDeferrable -> "hard_semantic_terminal_not_deferrable_by_live_replay"
            | TerminalDeferralWriterWitnessRequired -> "writer_witness_required"
            | TerminalDeferralLiveReplayWouldDeferSoftTerminal -> "live_replay_would_defer_soft_terminal"
            | TerminalDeferralQuietTerminalCanSurface -> "quiet_terminal_can_surface"

        let terminalDeferralEligibilityFor semanticPolicy writeWitness queueDepth activeDepth pendingCount replayDelta rootDelta sampledDelta =
            match semanticPolicy with
            | OpImplSemanticHardAuthoringBlocker -> TerminalDeferralHardSemanticNotDeferrable
            | _ when writeWitness -> TerminalDeferralQuietTerminalCanSurface
            | _ when queueDepth > 0 || activeDepth > 0 || pendingCount > 0 || replayDelta > 0L || rootDelta > 0L || sampledDelta > 0L -> TerminalDeferralLiveReplayWouldDeferSoftTerminal
            | _ -> TerminalDeferralWriterWitnessRequired

        type OpImplHandoffDecisionId =
            | OpImplNotTerminal
            | OpImplHandoffHardSemanticMissingImpl
            | OpImplDeferPendingReplay
            | OpImplDeferActiveReplay
            | OpImplDeferPendingActiveReplay
            | OpImplDeferQueuedReplayAlive
            | OpImplDeferPendingZeroLiveReplay
            | OpImplDeferRecentReplayProgress
            | OpImplHandoffReadyPendingZeroYieldThrash
            | OpImplHandoffReadyTerminalFlood
            | OpImplHandoffReady

        let opImplHandoffDecisionText = function
            | OpImplNotTerminal -> "not_terminal"
            | OpImplHandoffHardSemanticMissingImpl -> "hard_semantic_missing_impl_fail_closed"
            | OpImplDeferPendingReplay -> "defer_pending_replay"
            | OpImplDeferActiveReplay -> "defer_active_replay"
            | OpImplDeferPendingActiveReplay -> "defer_pending_active_replay"
            | OpImplDeferQueuedReplayAlive -> "defer_queued_replay_alive"
            | OpImplDeferPendingZeroLiveReplay -> "defer_pending_zero_live_replay"
            | OpImplDeferRecentReplayProgress -> "defer_recent_replay_progress"
            | OpImplHandoffReadyPendingZeroYieldThrash -> "handoff_ready_pending_zero_yield_thrash"
            | OpImplHandoffReadyTerminalFlood -> "handoff_ready_terminal_flood"
            | OpImplHandoffReady -> "handoff_ready"

        type OpImplSignatureId =
            | OpImplSignatureKnown of raw:string * name:string * arity:string
            | OpImplSignatureUnknown of raw:string

        let opImplSignatureFromReason (reasonId:CompilerKernelV2.OperationalReasonId) =
            let reason = CompilerKernelV2.OperationalReasonIdOps.text reasonId
            let prefix = "term_op_impl_required:"
            let raw = if String.IsNullOrWhiteSpace reason then "" else reason
            let fragments = raw.Split([|prefix|], StringSplitOptions.None)
            let signatureText =
                if fragments.Length < 2 then raw
                else
                    let tail = fragments.[1]
                    let stop = tail.IndexOfAny([|' '; '#'; '|'; '@'|])
                    if stop >= 0 then tail.Substring(0, stop) else tail
            let normalized = if String.IsNullOrWhiteSpace signatureText then "unknown_op" else signatureText
            match normalized |> Seq.tryFindIndex ((=) '/') with
            | Some slash when slash > 0 ->
                let name = normalized.Substring(0, slash)
                let arity = if slash < normalized.Length - 1 then normalized.Substring(slash + 1) else "unknown"
                OpImplSignatureKnown(normalized, name, arity)
            | _ ->
                OpImplSignatureUnknown normalized

        let opImplSignatureText = function
            | OpImplSignatureKnown(raw, _, _)
            | OpImplSignatureUnknown raw -> raw

        let opImplNameFromSignature = function
            | OpImplSignatureKnown(_, name, _) -> name
            | OpImplSignatureUnknown raw -> if String.IsNullOrWhiteSpace raw then "unknown_op" else raw

        let opImplArityFromSignature = function
            | OpImplSignatureKnown(_, _, arity) -> arity
            | OpImplSignatureUnknown _ -> "unknown"

        let opImplNodeIdFromKey (key: string) =
            let v = if String.IsNullOrWhiteSpace key then "" else key
            let hash = v.LastIndexOf("#", StringComparison.Ordinal)
            if hash >= 0 && hash < v.Length - 1 then v.Substring(hash + 1) else "unknown"

        let opImplHandoffDecisionFor (statusId: SemanticStatusId) pendingCount queueDepth activeDepth progressYield terminalAgeMs ageCapMs recentProgress terminalFloodMature =
            let semanticPolicy = opImplSemanticTerminalPolicyFor statusId
            match semanticPolicy with
            | OpImplSemanticHardAuthoringBlocker ->
                // MIGRATION: assessment arbitration is now policy-first, not a raw status string.
                // term_op_impl_required is a hard semantic authoring blocker; live replay proves only scheduler liveness.
                // Do not let replay_repeat_live_tail_guard, pending-zero overrides, or root chatter hide a missing implementation.
                OpImplHandoffHardSemanticMissingImpl
            | OpImplSemanticSoftReplayDeferrable ->
                if pendingCount > 0 && activeDepth > 0 && not (terminalFloodMature) then OpImplDeferPendingActiveReplay
                elif activeDepth > 0 && terminalAgeMs < ageCapMs then OpImplDeferActiveReplay
                elif queueDepth > 0 && terminalAgeMs < ageCapMs then OpImplDeferQueuedReplayAlive
                elif progressYield || recentProgress then OpImplDeferRecentReplayProgress
                else OpImplHandoffReady
            | _ -> OpImplNotTerminal

        // MIGRATION: keep pushing the live-replay policy boundary toward DUs.
        // Runtime evidence proved semantic_annot_test_branch_selection_blocked is now
        // the useful rank-87 frontier.  Treat it as a typed surface-now terminal
        // rather than another stringly deferrable status; active replay may still
        // defer soft replay/fingerprint/root terminals, but it cannot hide the
        // concrete branch-selection obligation.
        type LiveReplayTerminalPolicy =
            | DeferTerminalWhileLiveReplay
            | SurfaceTerminalDuringLiveReplay
            | TerminalNotLiveReplayPolicy

        // MIGRATION: MIGRATION proved the app-root/base16 live hardcap can fire
        // after a real root write witness already exists.  Keep that decision as
        // a closed DU so the root-witness path can defer to finalization without
        // weakening the fail-closed terminal used when no witness exists.
        type AppRootBase16LiveReplayHardcapDecision =
            | AppRootWitnessCanFinalize
            | AppRootWitnessFinalizeSelfLoopTerminal
            | AppRootLiveReplayLivelockTerminal
            | AppRootLiveReplayDemote
            | AppRootQuiescedHardcapTerminal
            | AppRootPreserveRootEvidence

        let private appRootBase16LiveReplayHardcapDecisionToString decision =
            match decision with
            | AppRootWitnessCanFinalize -> "root_witness_can_finalize"
            | AppRootWitnessFinalizeSelfLoopTerminal -> "root_witness_finalize_self_loop_terminal"
            | AppRootLiveReplayLivelockTerminal -> "live_replay_livelock_terminal"
            | AppRootLiveReplayDemote -> "live_replay_demote"
            | AppRootQuiescedHardcapTerminal -> "quiesced_hardcap_terminal"
            | AppRootPreserveRootEvidence -> "preserve_root_evidence"

        // MIGRATION: keep cross-kind payload attachment as a closed decision.
        // Runtime evidence showed term cells arriving while the canonical frame was ty;
        // dropping them as kind_mismatch_frame_ty_cell_term loses runnable replay work.
        // The safe path stores the cell as a deferred replay obligation whenever
        // there is pending/queued/active replay evidence, while preserving the old
        // fail-closed rejection when the mismatch is quiescent.
        type CrossKindPayloadAttachDecision =
            | CrossKindSwitchToFreshFrontier
            | CrossKindDeferAsReplayObligation
            | CrossKindRejectUnsafeMismatch

        type SemanticCellAttachStatusId =
            | SemanticCellAttached
            | SemanticCellStaleRootRetargeted
            | SemanticCellStaleRootRetargetQuarantined
            | SemanticCellRootCompleteStaleRetargetRepeatBlocked
            | SemanticCellRootCompleteStaleRetargetSuppressed
            | SemanticCellSameRootCompleteCellEchoMaterialized
            | SemanticCellSameSiteAppRootRetargetEchoMaterialized
            | SemanticCellAppRootBase16StaleRetargetHardcapDemoted
            | SemanticCellCrossKindPayloadDeferredFrame of frameKind:EvalKind * cellKind:EvalKind
            | SemanticCellCrossKindPayloadStaleRetargetObligationBypassed
            | SemanticCellCrossKindMismatchSwitched of frameKind:EvalKind * cellKind:EvalKind
            | SemanticCellKindMismatch of frameKind:EvalKind * cellKind:EvalKind
            | SemanticCellFrameParentContinuation
            | SemanticCellParentResumeDeferred
            | SemanticCellActiveReplayDeferred
            | SemanticCellSameNodeParentReplayDeferred
            | SemanticCellMissingFrontier

        let private semanticCellAttachStatusText = function
            | SemanticCellAttached -> "cell"
            | SemanticCellStaleRootRetargeted -> "stale_root_complete_retargeted"
            | SemanticCellStaleRootRetargetQuarantined -> "stale_root_complete_retarget_quarantined"
            | SemanticCellRootCompleteStaleRetargetRepeatBlocked -> "root_complete_stale_retarget_repeat_blocked"
            | SemanticCellRootCompleteStaleRetargetSuppressed -> "root_complete_stale_retarget_suppressed"
            | SemanticCellSameRootCompleteCellEchoMaterialized -> "same_root_complete_cell_echo_materialized"
            | SemanticCellSameSiteAppRootRetargetEchoMaterialized -> "same_site_app_root_retarget_echo_materialized"
            | SemanticCellAppRootBase16StaleRetargetHardcapDemoted -> "app_root_base16_stale_retarget_hardcap_demoted"
            | SemanticCellCrossKindPayloadDeferredFrame(frameKind, cellKind) ->
                FastRuntimeFormat.format "cross_kind_payload_deferred_frame_%s_cell_%s" [| box (evalKindToString frameKind); box (evalKindToString cellKind) |]
            | SemanticCellCrossKindPayloadStaleRetargetObligationBypassed -> "cross_kind_payload_stale_retarget_obligation_bypassed"
            | SemanticCellCrossKindMismatchSwitched(frameKind, cellKind) ->
                FastRuntimeFormat.format "kind_mismatch_switched_frame_%s_cell_%s" [| box (evalKindToString frameKind); box (evalKindToString cellKind) |]
            | SemanticCellKindMismatch(frameKind, cellKind) ->
                FastRuntimeFormat.format "kind_mismatch_frame_%s_cell_%s" [| box (evalKindToString frameKind); box (evalKindToString cellKind) |]
            | SemanticCellFrameParentContinuation -> "cell_frame_parent_continuation"
            | SemanticCellParentResumeDeferred -> "parent_resume_cell_deferred"
            | SemanticCellActiveReplayDeferred -> "active_replay_cell_deferred"
            | SemanticCellSameNodeParentReplayDeferred -> "same_node_parent_replay_cell_deferred"
            | SemanticCellMissingFrontier -> "missing_frontier"

        let private semanticCellAttachStatusIsCrossKindPayloadDeferred = function
            | SemanticCellCrossKindPayloadDeferredFrame _ -> true
            | _ -> false

        let private crossKindPayloadAttachDecisionToString decision =
            match decision with
            | CrossKindSwitchToFreshFrontier -> "switch_to_fresh_frontier"
            | CrossKindDeferAsReplayObligation -> "defer_as_replay_obligation"
            | CrossKindRejectUnsafeMismatch -> "reject_unsafe_mismatch"

        // MIGRATION: a repeated NullReferenceException after a root-complete
        // write witness is not the same thing as an uncovered semantic terminal.
        // Runtime evidence showed Hopac replay reaching semantic_root_complete, then
        // rebuilding a let-success/apply continuation until the old null-repeat
        // cap pinned let_success_apply_continuation_null_repeat_terminal. Keep
        // the decision closed: terminal only when there is no root witness/live
        // replay evidence; otherwise preserve the witness or defer the still-live
        // replay tick without pretending BuildOk locally.
        type RootWitnessNullReplayDecision =
            | RootWitnessNullDeferLiveReplay
            | RootWitnessNullPreserveComplete
            | RootWitnessNullSurfaceTerminal

        let private rootWitnessNullReplayDecisionToString decision =
            match decision with
            | RootWitnessNullDeferLiveReplay -> "root_witness_null_defer_live_replay"
            | RootWitnessNullPreserveComplete -> "root_witness_null_preserve_complete"
            | RootWitnessNullSurfaceTerminal -> "root_witness_null_surface_terminal"

        // MIGRATION: EUnbox replay can surface a real BigStack wait timeout through
        // the child detail. Do not schedule that child again as semantic_step_partial,
        // or the replay loop masks the true blocker until a manual interrupt.
        type UnboxChildControlEvidence =
            | UnboxChildControlRootCompleteHandoff
            | UnboxChildControlBoundJoinStall
            | UnboxChildControlExecutableError

        let private unboxChildControlEvidenceOfDetail (detail: string) =
            let facts = DiagnosticClassifier.classifyFacts detail
            if Set.contains DiagnosticClassifier.DiagnosticBigStackSemanticRootCompleteHandoff facts then
                UnboxChildControlRootCompleteHandoff
            elif Set.contains DiagnosticClassifier.DiagnosticBigStackTermDepthJoinStalled facts then
                UnboxChildControlBoundJoinStall
            else
                UnboxChildControlExecutableError

        type UnboxChildReplayDecision =
            | UnboxChildScheduleReplay
            | UnboxChildPreserveRootCompleteHandoff
            | UnboxChildBoundJoinStall
            | UnboxChildSurfaceBlocked

        let private unboxChildReplayDecisionToString decision =
            match decision with
            | UnboxChildScheduleReplay -> "schedule_replay"
            | UnboxChildPreserveRootCompleteHandoff -> "preserve_root_complete_handoff"
            | UnboxChildBoundJoinStall -> "bound_bigstack_join_stall"
            | UnboxChildSurfaceBlocked -> "surface_blocked"

        let private liveReplayTerminalPolicyOfSemanticStatusId = function
            | SemanticParentContinuationCycleBlocked
            | SemanticRootCompletePendingJobsBlocked
            | SemanticAppRootBase16StaleRetargetHardcapBlocked
            | SemanticReplayChildScheduleRepeatBlocked
            | SemanticRecordWithValueBlocked
            | SemanticReplayFingerprintRepeatBlocked
            | SemanticRootCompleteStaleRetargetPendingNoQueueBlocked -> DeferTerminalWhileLiveReplay
            // MIGRATION: these are concrete obligations, not soft replay churn.
            // Let BigStack fail closed on the precise missing implementation/branch
            // selector instead of demoting them into a lower-rank global-fuse loop.
            | SemanticOpImplRequiredBlocked
            | SemanticAnnotTestBranchSelectionBlocked
            | SemanticUnboxReplayBlocked
            | SemanticApplySpineMissingDirectValueBlocked
            // MIGRATION: dynamic-join terminal evidence is durable, but live
            // q/a/p replay is still a carrier/drain obligation, not a terminal
            // surface. Keep stale-retarget livelock aggressive; defer dynamic join.
            | SemanticRootCompleteStaleRetargetLiveReplayLivelockBlocked -> SurfaceTerminalDuringLiveReplay
            | SemanticDynamicJoinApplyBlocked -> DeferTerminalWhileLiveReplay
            // MIGRATION: missing-after-prefetch is only terminal authority after
            // the explicit replay lane is quiet; while pending/queued/active replay
            // exists it is a drain obligation.
            | SemanticMissingAfterPrefetchBlocked -> DeferTerminalWhileLiveReplay
            // MIGRATION: semantic_global_fuse_parent_continuation_cycle_blocked
            // is emitted only after the bounded global-fuse repeat cap is
            // exhausted. Runtime evidence showed that treating it as deferrable lets
            // active/queued replay suppress the terminal forever, producing a
            // manual interrupt instead of the intended fail-closed BuildError.
            | SemanticGlobalFuseParentContinuationCycleBlocked -> TerminalNotLiveReplayPolicy
            | _ -> TerminalNotLiveReplayPolicy

        let private isLiveReplayDeferrableSemanticStatusId statusId =
            match liveReplayTerminalPolicyOfSemanticStatusId statusId with
            | DeferTerminalWhileLiveReplay -> true
            | SurfaceTerminalDuringLiveReplay
            | TerminalNotLiveReplayPolicy -> false


        // MIGRATION: dynamic-record-key placeholder handling is a typed three-way
        // decision.  DV returned by the explicit dynamic-join runner is the existing
        // symbolic runtime carrier; DB is still not a fabricated key, but it may get
        // one bounded bridge-tail drain window when the run has just observed dynamic
        // key bridge activity and there is no writer witness.
        type DynamicRecordKeyPlaceholderDecisionId =
            | DynamicRecordKeyPlaceholderAcceptSymbolicRuntimeValue
            | DynamicRecordKeyPlaceholderDeferObservedBridgeTail
            | DynamicRecordKeyPlaceholderDeferDvSymbolicLiveTail
            | DynamicRecordKeyPlaceholderPinNoBridgeEvidenceOrCapExhausted
            | DynamicRecordKeyPlaceholderPinTerminal

        let dynamicRecordKeyPlaceholderDecisionText = function
            | DynamicRecordKeyPlaceholderAcceptSymbolicRuntimeValue -> "accept_symbolic_runtime_value"
            | DynamicRecordKeyPlaceholderDeferObservedBridgeTail -> "defer_observed_bridge_tail"
            | DynamicRecordKeyPlaceholderDeferDvSymbolicLiveTail -> "defer_dv_symbolic_live_bridge_tail"
            | DynamicRecordKeyPlaceholderPinNoBridgeEvidenceOrCapExhausted -> "pin_no_bridge_evidence_or_cap_exhausted"
            | DynamicRecordKeyPlaceholderPinTerminal -> "pin_terminal"

        type DynamicRecordKeyBridgeTailEvidenceId =
            | DynamicRecordKeyBridgeTailNone
            | DynamicRecordKeyBridgeTailObservedBridge
            | DynamicRecordKeyBridgeTailSymbolicCarrier
            | DynamicRecordKeyBridgeTailPendingActiveRoot
            | DynamicRecordKeyBridgeTailPhysicalQueue
            | DynamicRecordKeyBridgeTailCapExhausted

        type DynamicRecordKeyBridgeTailStrengthId =
            | DynamicRecordKeyBridgeTailStrengthNone
            | DynamicRecordKeyBridgeTailStrengthStrongObservedBridge
            | DynamicRecordKeyBridgeTailStrengthStrongSymbolicCarrier
            | DynamicRecordKeyBridgeTailStrengthWeakPendingActiveRoot
            | DynamicRecordKeyBridgeTailStrengthWeakPhysicalQueue
            | DynamicRecordKeyBridgeTailStrengthCapExhausted

        let dynamicRecordKeyBridgeTailStrengthText = function
            | DynamicRecordKeyBridgeTailStrengthNone -> "none"
            | DynamicRecordKeyBridgeTailStrengthStrongObservedBridge -> "strong_observed_bridge"
            | DynamicRecordKeyBridgeTailStrengthStrongSymbolicCarrier -> "strong_dv_symbolic_carrier"
            | DynamicRecordKeyBridgeTailStrengthWeakPendingActiveRoot -> "weak_pending_active_root"
            | DynamicRecordKeyBridgeTailStrengthWeakPhysicalQueue -> "weak_physical_queue"
            | DynamicRecordKeyBridgeTailStrengthCapExhausted -> "cap_exhausted"

        let dynamicRecordKeyBridgeTailStrengthForEvidence = function
            | DynamicRecordKeyBridgeTailObservedBridge -> DynamicRecordKeyBridgeTailStrengthStrongObservedBridge
            | DynamicRecordKeyBridgeTailSymbolicCarrier -> DynamicRecordKeyBridgeTailStrengthStrongSymbolicCarrier
            | DynamicRecordKeyBridgeTailPendingActiveRoot -> DynamicRecordKeyBridgeTailStrengthWeakPendingActiveRoot
            | DynamicRecordKeyBridgeTailPhysicalQueue -> DynamicRecordKeyBridgeTailStrengthWeakPhysicalQueue
            | DynamicRecordKeyBridgeTailCapExhausted -> DynamicRecordKeyBridgeTailStrengthCapExhausted
            | DynamicRecordKeyBridgeTailNone -> DynamicRecordKeyBridgeTailStrengthNone

        type DynamicRecordKeyBridgeTailLeaseId =
            | DynamicRecordKeyBridgeTailLeaseDormant
            | DynamicRecordKeyBridgeTailLeaseDraining of observedDeferrals:int * remainingDeferrals:int
            | DynamicRecordKeyBridgeTailLeaseExhausted of observedDeferrals:int

        let dynamicRecordKeyBridgeTailLeaseCap = 8

        let dynamicRecordKeyBridgeTailLeaseFor isDrain observedDeferrals =
            if not isDrain then DynamicRecordKeyBridgeTailLeaseDormant
            elif observedDeferrals >= dynamicRecordKeyBridgeTailLeaseCap then DynamicRecordKeyBridgeTailLeaseExhausted observedDeferrals
            else DynamicRecordKeyBridgeTailLeaseDraining(observedDeferrals, max 0 (dynamicRecordKeyBridgeTailLeaseCap - observedDeferrals))

        let dynamicRecordKeyBridgeTailLeaseText = function
            | DynamicRecordKeyBridgeTailLeaseDormant -> "DynamicRecordKeyBridgeTailLease(Dormant)"
            | DynamicRecordKeyBridgeTailLeaseDraining(observedDeferrals, remainingDeferrals) ->
                FastRuntimeFormat.format "DynamicRecordKeyBridgeTailLease(Draining|observed=%d|remaining=%d|cap=%d)" [| box observedDeferrals; box remainingDeferrals; box dynamicRecordKeyBridgeTailLeaseCap |]
            | DynamicRecordKeyBridgeTailLeaseExhausted observedDeferrals ->
                sprintf "DynamicRecordKeyBridgeTailLease(Exhausted|observed=%d|cap=%d)" observedDeferrals dynamicRecordKeyBridgeTailLeaseCap

        let dynamicRecordKeyBridgeTailLeaseIsExhausted = function
            | DynamicRecordKeyBridgeTailLeaseExhausted _ -> true
            | DynamicRecordKeyBridgeTailLeaseDormant
            | DynamicRecordKeyBridgeTailLeaseDraining _ -> false

        type DynamicRecordKeyPlaceholderRepeatCapOutcomeId =
            | DynamicRecordKeyRepeatCapSuppressedByLiveBridgeTail
            | DynamicRecordKeyRepeatCapPendingRootOnlyFallsThrough
            | DynamicRecordKeyRepeatCapPhysicalQueueOnlyFallsThrough
            | DynamicRecordKeyRepeatCapPinNoLiveBridgeTailOrCapExhausted

        let dynamicRecordKeyPlaceholderRepeatCapOutcomeText = function
            | DynamicRecordKeyRepeatCapSuppressedByLiveBridgeTail -> "bridge_tail_live_suppresses_repeat_cap_pin"
            | DynamicRecordKeyRepeatCapPendingRootOnlyFallsThrough -> "pending_root_only_falls_through_to_structural_churn"
            | DynamicRecordKeyRepeatCapPhysicalQueueOnlyFallsThrough -> "physical_queue_only_falls_through_to_structural_churn"
            | DynamicRecordKeyRepeatCapPinNoLiveBridgeTailOrCapExhausted -> "pin_no_live_bridge_tail_or_cap_exhausted"

        let dynamicRecordKeyBridgeTailEvidenceText = function
            | DynamicRecordKeyBridgeTailNone -> "none"
            | DynamicRecordKeyBridgeTailObservedBridge -> "observed_bridge"
            | DynamicRecordKeyBridgeTailSymbolicCarrier -> "dv_symbolic_carrier"
            | DynamicRecordKeyBridgeTailPendingActiveRoot -> "pending_active_root"
            | DynamicRecordKeyBridgeTailPhysicalQueue -> "physical_queue_or_active"
            | DynamicRecordKeyBridgeTailCapExhausted -> "cap_exhausted"

        let dynamicRecordKeyBridgeTailEvidenceFor
            (pending: int)
            (queueDepth: int)
            (activeDepth: int)
            (rootWitnessActivity: int)
            (bridgeCount: int)
            (symbolicAcceptedCount: int)
            (bridgeTailDeferCount: int)
            =
            if bridgeTailDeferCount >= 32 then DynamicRecordKeyBridgeTailCapExhausted
            elif pending <= 0 && queueDepth <= 0 && rootWitnessActivity <= 0 then
                // MIGRATION: q=0/p=0 means there is no physical producer left that
                // can satisfy a dynamic-record-key bridge lease.  Active workers alone
                // are waiters, not evidence of future work; do not let them hold a
                // ghost bridge tail alive through graceful shutdown.
                DynamicRecordKeyBridgeTailNone
            elif bridgeCount > 0 then DynamicRecordKeyBridgeTailObservedBridge
            elif symbolicAcceptedCount > 0 then DynamicRecordKeyBridgeTailSymbolicCarrier
            elif pending > 0 && (activeDepth > 0 || rootWitnessActivity > 0) then DynamicRecordKeyBridgeTailPendingActiveRoot
            elif pending > 0 || queueDepth > 0 || activeDepth > 0 then DynamicRecordKeyBridgeTailPhysicalQueue
            else DynamicRecordKeyBridgeTailNone

        let dynamicRecordKeyBridgeTailEvidenceIsLive = function
            | DynamicRecordKeyBridgeTailObservedBridge
            | DynamicRecordKeyBridgeTailSymbolicCarrier
            | DynamicRecordKeyBridgeTailPendingActiveRoot
            | DynamicRecordKeyBridgeTailPhysicalQueue -> true
            | DynamicRecordKeyBridgeTailNone
            | DynamicRecordKeyBridgeTailCapExhausted -> false

        let dynamicRecordKeyBridgeTailEvidenceIsStrongRepeatCapLive = function
            | DynamicRecordKeyBridgeTailObservedBridge
            | DynamicRecordKeyBridgeTailSymbolicCarrier
            | DynamicRecordKeyBridgeTailPendingActiveRoot
            | DynamicRecordKeyBridgeTailPhysicalQueue -> true
            | DynamicRecordKeyBridgeTailNone
            | DynamicRecordKeyBridgeTailCapExhausted -> false

        let dynamicRecordKeyPlaceholderDecisionFor
            (isDynamicRecordKey: bool)
            (valueCarrierId: EvalReplayValueStore.DynamicRecordKeyValueCarrierId)
            (queueDepth: int)
            (activeDepth: int)
            (pending: int)
            (writeWitness: bool)
            (bridgeCount: int)
            (symbolicAcceptedCount: int)
            (bridgeTailDeferCount: int)
            (rootWitnessActivity: int)
            =
            let isDvCarrier = EvalReplayValueStore.dynamicRecordKeyValueCarrierIsDv valueCarrierId
            let isDbPlaceholder = EvalReplayValueStore.dynamicRecordKeyValueCarrierIsDb valueCarrierId
            let bridgeTailEvidence =
                dynamicRecordKeyBridgeTailEvidenceFor pending queueDepth activeDepth rootWitnessActivity bridgeCount symbolicAcceptedCount bridgeTailDeferCount
            let bridgeTailLive = dynamicRecordKeyBridgeTailEvidenceIsLive bridgeTailEvidence
            let bridgeTailWindowOpen = bridgeTailDeferCount < 32
            if isDynamicRecordKey && isDvCarrier && not writeWitness then
                DynamicRecordKeyPlaceholderAcceptSymbolicRuntimeValue
            elif isDynamicRecordKey
                 && isDbPlaceholder
                 && not writeWitness
                 && bridgeTailWindowOpen
                 && bridgeTailLive then
                match bridgeTailEvidence with
                | DynamicRecordKeyBridgeTailSymbolicCarrier
                | DynamicRecordKeyBridgeTailPendingActiveRoot -> DynamicRecordKeyPlaceholderDeferDvSymbolicLiveTail
                | _ -> DynamicRecordKeyPlaceholderDeferObservedBridgeTail
            elif isDynamicRecordKey && isDbPlaceholder && not writeWitness then
                DynamicRecordKeyPlaceholderPinNoBridgeEvidenceOrCapExhausted
            else
                DynamicRecordKeyPlaceholderPinTerminal

        // MIGRATION: dynamic-join surfacing is now a first-class decision, not a
        // stringly side-effect of liveReplayTerminalSuppressed.  This preserves the
        // aggressive MIGRATION behavior while making future tweaks exhaustive.
        type DynamicJoinTerminalDecisionId =
            | DynamicJoinTerminalSurface
            | DynamicJoinTerminalDeferLiveReplay

        let private dynamicJoinTerminalDecisionText = function
            | DynamicJoinTerminalSurface -> "surface_terminal"
            | DynamicJoinTerminalDeferLiveReplay -> "defer_live_replay"

        let private dynamicJoinTerminalDecisionForStatusId statusId =
            match statusId with
            | SemanticDynamicJoinApplyBlocked ->
                match liveReplayTerminalPolicyOfSemanticStatusId statusId with
                | DeferTerminalWhileLiveReplay -> DynamicJoinTerminalDeferLiveReplay
                | SurfaceTerminalDuringLiveReplay
                | TerminalNotLiveReplayPolicy -> DynamicJoinTerminalSurface
            | _ -> DynamicJoinTerminalSurface


        // MIGRATION: BigStack handoff for dynamic-join terminals is now a
        // typed decision.  MIGRATION proved the dynamic-join frontier is real;
        // MIGRATION proved the first age window was too short because BigStack still
        // accepted the same rank-92 terminal with pending/queued/active replay.  Keep
        // the terminal durable, but runnable replay now defers by DU until it actually
        // drains; only stalled replay without a runnable queue may surface as aged.
        type DynamicJoinReplayLivenessId =
            | DynamicJoinReplayNoLive
            | DynamicJoinReplayPendingOnly
            | DynamicJoinReplayQueueLive
            | DynamicJoinReplayActiveDriverLive
            | DynamicJoinReplayProgressYieldLive

        let dynamicJoinReplayLivenessText = function
            | DynamicJoinReplayNoLive -> "no_live_replay"
            | DynamicJoinReplayPendingOnly -> "pending_only"
            | DynamicJoinReplayQueueLive -> "queue_live"
            | DynamicJoinReplayActiveDriverLive -> "active_driver_live"
            | DynamicJoinReplayProgressYieldLive -> "progress_yield_live"

        let dynamicJoinReplayLivenessFor pending queueDepth activeDepth progressYield =
            if progressYield then DynamicJoinReplayProgressYieldLive
            elif activeDepth > 0 then DynamicJoinReplayActiveDriverLive
            elif queueDepth > 0 then DynamicJoinReplayQueueLive
            elif pending > 0 then DynamicJoinReplayPendingOnly
            else DynamicJoinReplayNoLive

        type DynamicJoinProgressEvidenceId =
            | DynamicJoinNoFreshProgress
            | DynamicJoinReplayTrickleOnly
            | DynamicJoinSampledOrReplayBurst
            | DynamicJoinRootOrTerminalDelta

        let dynamicJoinProgressEvidenceText = function
            | DynamicJoinNoFreshProgress -> "no_fresh_progress"
            | DynamicJoinReplayTrickleOnly -> "replay_trickle_only"
            | DynamicJoinSampledOrReplayBurst -> "sampled_or_replay_burst"
            | DynamicJoinRootOrTerminalDelta -> "root_or_terminal_delta"

        let dynamicJoinProgressEvidenceIsMeaningful = function
            | DynamicJoinRootOrTerminalDelta
            | DynamicJoinSampledOrReplayBurst -> true
            | DynamicJoinReplayTrickleOnly
            | DynamicJoinNoFreshProgress -> false

        type DynamicJoinProgressFreshnessId =
            | DynamicJoinProgressFresh
            | DynamicJoinProgressStale

        let dynamicJoinProgressFreshnessText = function
            | DynamicJoinProgressFresh -> "fresh"
            | DynamicJoinProgressStale -> "stale"

        let dynamicJoinProgressFreshnessFor richTickAgeMs ageCap =
            if richTickAgeMs < ageCap * 2 then DynamicJoinProgressFresh
            else DynamicJoinProgressStale

        let dynamicJoinProgressFreshnessIsFresh = function
            | DynamicJoinProgressFresh -> true
            | DynamicJoinProgressStale -> false

        let dynamicJoinProgressEvidenceFor (sampledDelta:int64) (replayDelta:int64) (rootDelta:int64) (terminalDelta:int64) =
            if rootDelta > 0L || terminalDelta > 0L then DynamicJoinRootOrTerminalDelta
            elif sampledDelta > 0L || replayDelta >= 32L then DynamicJoinSampledOrReplayBurst
            elif replayDelta > 0L then DynamicJoinReplayTrickleOnly
            else DynamicJoinNoFreshProgress

        type DynamicJoinHandoffDecisionId =
            | DynamicJoinHandoffNotDynamic
            | DynamicJoinHandoffDeferPendingReplay
            | DynamicJoinHandoffDeferActiveReplay
            | DynamicJoinHandoffDeferRunnableReplay
            | DynamicJoinHandoffDeferRecentReplayProgress
            | DynamicJoinHandoffDeferRuntimeUnionCarrier
            | DynamicJoinHandoffDeferRecordKeyBridgeTail
            | DynamicJoinHandoffDeferPendingStackFenceBridge
            | DynamicJoinHandoffDeferCooperativeYieldShadowBridge
            | DynamicJoinHandoffSurfacePendingStackFenceBridgeAltTimeout
            | DynamicJoinHandoffSurfaceCooperativeYieldShadowAltTimeout
            | DynamicJoinHandoffSurfaceWaitedStaleTail
            | DynamicJoinHandoffSurfaceQuiet
            | DynamicJoinHandoffSurfaceAgedStalledReplay

        let dynamicJoinHandoffDecisionText = function
            | DynamicJoinHandoffNotDynamic -> "not_dynamic_join"
            | DynamicJoinHandoffDeferPendingReplay -> "defer_pending_replay"
            | DynamicJoinHandoffDeferActiveReplay -> "defer_active_replay"
            | DynamicJoinHandoffDeferRunnableReplay -> "defer_runnable_replay"
            | DynamicJoinHandoffDeferRecentReplayProgress -> "defer_recent_replay_progress"
            | DynamicJoinHandoffDeferRuntimeUnionCarrier -> "defer_runtime_union_carrier"
            | DynamicJoinHandoffDeferRecordKeyBridgeTail -> "defer_record_key_bridge_tail"
            | DynamicJoinHandoffDeferPendingStackFenceBridge -> "defer_pending_stack_fence_bridge"
            | DynamicJoinHandoffDeferCooperativeYieldShadowBridge -> "defer_cooperative_yield_shadow_bridge"
            | DynamicJoinHandoffSurfacePendingStackFenceBridgeAltTimeout -> "native_inline_pending_stack_fence_bridge_alt_timeout"
            | DynamicJoinHandoffSurfaceCooperativeYieldShadowAltTimeout -> "native_inline_cooperative_yield_shadow_alt_timeout"
            | DynamicJoinHandoffSurfaceWaitedStaleTail -> "surface_waited_stale_tail"
            | DynamicJoinHandoffSurfaceQuiet -> "surface_quiet"
            | DynamicJoinHandoffSurfaceAgedStalledReplay -> "surface_aged_stalled_replay"

        type DynamicJoinPendingZeroNoWriterDecisionId =
            | DynamicJoinPendingZeroNoWriterNotDynamic
            | DynamicJoinPendingZeroNoWriterDeferFreshLiveReplay
            | DynamicJoinPendingZeroNoWriterDeferLiveQueueSurge
            | DynamicJoinPendingZeroNoWriterDeferRecentAuthority
            | DynamicJoinPendingZeroNoWriterDeferReplayBurstActiveQueue
            | DynamicJoinPendingZeroNoWriterDeferActiveReplayTrickle
            | DynamicJoinPendingZeroNoWriterDeferQueuedReplayNoActiveDriver
            | DynamicJoinPendingZeroNoWriterSurfaceQueuedReplayStarvedNoActiveDriver
            | DynamicJoinPendingZeroNoWriterHardPin

        let dynamicJoinPendingZeroNoWriterDecisionText = function
            | DynamicJoinPendingZeroNoWriterNotDynamic -> "not_dynamic_join"
            | DynamicJoinPendingZeroNoWriterDeferFreshLiveReplay -> "defer_fresh_live_replay"
            | DynamicJoinPendingZeroNoWriterDeferLiveQueueSurge -> "defer_live_queue_surge"
            | DynamicJoinPendingZeroNoWriterDeferRecentAuthority -> "defer_recent_authority"
            | DynamicJoinPendingZeroNoWriterDeferReplayBurstActiveQueue -> "defer_replay_burst_active_queue"
            | DynamicJoinPendingZeroNoWriterDeferActiveReplayTrickle -> "defer_active_replay_trickle"
            | DynamicJoinPendingZeroNoWriterDeferQueuedReplayNoActiveDriver -> "defer_queued_replay_no_active_driver"
            | DynamicJoinPendingZeroNoWriterSurfaceQueuedReplayStarvedNoActiveDriver -> "surface_queued_replay_starved_no_active_driver"
            | DynamicJoinPendingZeroNoWriterHardPin -> "hard_pin_no_writer"

        let dynamicJoinPendingZeroNoWriterDecisionFor
            (statusId: SemanticStatusId)
            (pending: int)
            (queueDepth: int)
            (activeDepth: int)
            (writeWitness: bool)
            (terminalAge: int)
            (ageCap: int)
            (replayDelta: int64)
            (rootDelta: int64)
            (terminalDelta: int64)
            =
            match statusId with
            | SemanticDynamicJoinApplyBlocked ->
                let liveTail = pending > 0 || queueDepth > 0 || activeDepth > 0
                // MIGRATION: replay-only movement around a durable dynamic-join
                // blocker is scheduler churn, not semantic authority.  MIGRATION
                // still let replayDelta hundreds-wide extend the no-writer window
                // until jp_wait wrapped the real rank-92 terminal as generic EJP0011.
                let recentAuthority = rootDelta > 0L || terminalDelta > 0L
                if writeWitness || pending > 0 then DynamicJoinPendingZeroNoWriterNotDynamic
                elif liveTail && terminalAge < max ageCap 1 then DynamicJoinPendingZeroNoWriterDeferFreshLiveReplay
                elif pending = 0 && queueDepth >= 16 && activeDepth > 0 && replayDelta >= 32L && terminalAge < max (ageCap * 4) 60000 then DynamicJoinPendingZeroNoWriterDeferReplayBurstActiveQueue
                elif pending = 0 && queueDepth > 0 && activeDepth > 0 && replayDelta > 0L && terminalAge < max (ageCap * 8) 90000 then DynamicJoinPendingZeroNoWriterDeferActiveReplayTrickle
                elif pending = 0 && queueDepth >= 64 && activeDepth <= 0 && (replayDelta <= 0L || terminalAge >= max (ageCap * 12) 120000) then DynamicJoinPendingZeroNoWriterSurfaceQueuedReplayStarvedNoActiveDriver
                elif pending = 0 && queueDepth >= 64 && activeDepth <= 0 && replayDelta > 0L && terminalAge < max (ageCap * 12) 120000 then DynamicJoinPendingZeroNoWriterDeferQueuedReplayNoActiveDriver
                elif pending = 0 && queueDepth >= 16 && activeDepth > 0 then DynamicJoinPendingZeroNoWriterDeferLiveQueueSurge
                elif liveTail && recentAuthority && terminalAge < max (ageCap * 2) (ageCap + 1) then DynamicJoinPendingZeroNoWriterDeferRecentAuthority
                else DynamicJoinPendingZeroNoWriterHardPin
            | _ -> DynamicJoinPendingZeroNoWriterNotDynamic

        type DynamicJoinLateTailDecisionId =
            | DynamicJoinLateTailNotDynamic
            | DynamicJoinLateTailDeferLiveTail
            | DynamicJoinLateTailSurfaceQuietTail

        let dynamicJoinLateTailDecisionText = function
            | DynamicJoinLateTailNotDynamic -> "not_dynamic_join"
            | DynamicJoinLateTailDeferLiveTail -> "defer_live_tail"
            | DynamicJoinLateTailSurfaceQuietTail -> "surface_quiet_tail"

        let dynamicJoinLateTailDecisionFor
            (statusId: SemanticStatusId)
            (waited: int)
            (ageCap: int)
            (pending: int)
            (queueDepth: int)
            (activeDepth: int)
            (_rootDelta: int64)
            (_terminalDelta: int64)
            =
            match statusId with
            | SemanticDynamicJoinApplyBlocked ->
                let staleWindow = waited >= max (ageCap * 8) 12000
                if not staleWindow then DynamicJoinLateTailNotDynamic
                elif pending > 0 || queueDepth > 0 || activeDepth > 0 then DynamicJoinLateTailDeferLiveTail
                else DynamicJoinLateTailSurfaceQuietTail
            | _ -> DynamicJoinLateTailNotDynamic

        let dynamicJoinHandoffDecisionFor (statusId: SemanticStatusId) pending queueDepth activeDepth progressYield terminalAge ageCap recentProgress sampledDelta replayDelta rootDelta terminalDelta richTickAgeMs recordKeyBridgeTailStrongLive =
            match statusId with
            | SemanticDynamicJoinApplyBlocked ->
                let replayLiveness =
                    dynamicJoinReplayLivenessFor pending queueDepth activeDepth progressYield
                let progressEvidence =
                    dynamicJoinProgressEvidenceFor sampledDelta replayDelta rootDelta terminalDelta
                let progressFreshness =
                    dynamicJoinProgressFreshnessFor richTickAgeMs ageCap
                let meaningfulProgress =
                    // MIGRATION: root/replay churn is useful before the terminal matures,
                    // but after one bounded dynamic-join window it is evidence for fail-closed
                    // handoff, not a license to keep replaying around a rank-92 blocker.
                    terminalAge < ageCap
                    && dynamicJoinProgressEvidenceIsMeaningful progressEvidence
                    && dynamicJoinProgressFreshnessIsFresh progressFreshness
                let freshAuthorityProgress =
                    // MIGRATION: MIGRATION surfaced EJP0021 at terminal_age=6000ms while
                    // replay/root/terminal deltas were still arriving and the blocker was an
                    // explicit dynamic-record-key DV carrier.  MIGRATION narrows that grace:
                    // replay-only churn around semantic_dynamic_join_apply_blocked may not
                    // keep deferring the terminal after the first bounded window; root or
                    // terminal authority is required to buy extra time.
                    terminalAge < ageCap * 2
                    && dynamicJoinProgressFreshnessIsFresh progressFreshness
                    && (rootDelta > 0L || terminalDelta > 0L)
                let hardStale =
                    terminalAge >= ageCap * 16
                    && pending = 0
                    && queueDepth = 0
                    && activeDepth = 0
                    && not meaningfulProgress
                    && not freshAuthorityProgress
                let recordKeyBridgeTailGrace =
                    // MIGRATION: generic queue/active evidence is not record-key bridge authority.
                    // Only observed bridge/DV-carrier evidence gets the dynamic-record-key grace;
                    // weak pending/root/physical tails fall through to active-structural-churn or terminal arbitration.
                    recordKeyBridgeTailStrongLive
                    && not hardStale
                    && (pending > 0 || queueDepth > 0 || activeDepth > 0 || freshAuthorityProgress || meaningfulProgress)
                let pendingStackFenceBridgeEvidence =
                    // MIGRATION: 1496.jsonl proved the bridge can be live yet spin for minutes because late-tail arbitration
                    // rewrites it to runtime-union carrier and the HUD keeps saying weak fallthrough.  Split evidence from lease.
                    recordKeyBridgeTailStrongLive
                    && pending > 0
                    && activeDepth > 0
                    && replayDelta > 0L
                    && not hardStale
                let pendingStackFenceBridgeAltTimeout =
                    // MIGRATION: 1682.jsonl dropped CPU while repeatedly alternating
                    // dynamic_join_pending_stack_fence_bridge_deferred with
                    // dynamic_key_bridge_tail_status.  A structurally bound Hopac
                    // stack-fence bridge may not wait for the old 120s shadow timer;
                    // after the short native turn-on window, surface the typed
                    // Job.bind handoff and make the timer observer-only.
                    pendingStackFenceBridgeEvidence
                    && terminalAge >= max (ageCap * 2) 3000
                    && not freshAuthorityProgress
                let pendingStackFenceBridgeAuthority =
                    pendingStackFenceBridgeEvidence
                    && not pendingStackFenceBridgeAltTimeout
                let cooperativeYieldShadowBridgeEvidence =
                    // MIGRATION: MIGRATION showed p=0/q=39/a=4 term_to_ty cooperative-yield thrash while Hopac shadow parity
                    // already advertised alt=timeout_1500ms.  A cooperative yield is useful for fairness, not an infinite
                    // repeat-cap pardon once the shadow Alt timeout would have snapped the branch.
                    progressYield
                    && pending = 0
                    && queueDepth > 0
                    && activeDepth > 0
                    && replayDelta > 0L
                    && not hardStale
                let cooperativeYieldShadowAltTimeout =
                    cooperativeYieldShadowBridgeEvidence
                    && terminalAge >= 1500
                let pendingStackFenceCausalDead =
                    // MIGRATION: 1865.jsonl proved that pending=2/active=4 plus replay
                    // trickle around dynamic_join_pending_stack_fence_bridge_alt_timeout
                    // can spin for >130s with root/terminal deltas at zero. The short
                    // native turn-on window is useful once; after 30s it is a causal-dead
                    // stack-fence, not live Hopac work.
                    pendingStackFenceBridgeEvidence
                    && terminalAge >= max (ageCap * 20) 30000
                    && sampledDelta <= 0L
                    && rootDelta <= 0L
                    && terminalDelta <= 0L
                    && not freshAuthorityProgress
                    && not meaningfulProgress
                if pendingStackFenceCausalDead then
                    DynamicJoinHandoffSurfaceAgedStalledReplay
                elif cooperativeYieldShadowAltTimeout then
                    DynamicJoinHandoffSurfaceCooperativeYieldShadowAltTimeout
                elif pendingStackFenceBridgeAltTimeout then
                    DynamicJoinHandoffSurfacePendingStackFenceBridgeAltTimeout
                elif pendingStackFenceBridgeAuthority then
                    DynamicJoinHandoffDeferPendingStackFenceBridge
                elif cooperativeYieldShadowBridgeEvidence then
                    DynamicJoinHandoffDeferCooperativeYieldShadowBridge
                elif recordKeyBridgeTailGrace then
                    DynamicJoinHandoffDeferRecordKeyBridgeTail
                else
                    match replayLiveness with
                    | DynamicJoinReplayProgressYieldLive
                    | DynamicJoinReplayActiveDriverLive
                    | DynamicJoinReplayQueueLive ->
                        if terminalAge < ageCap then
                            DynamicJoinHandoffDeferActiveReplay
                        elif hardStale then
                            DynamicJoinHandoffSurfaceAgedStalledReplay
                        elif freshAuthorityProgress then
                            DynamicJoinHandoffDeferRuntimeUnionCarrier
                        elif meaningfulProgress || (recentProgress && terminalAge < ageCap * 2) then
                            DynamicJoinHandoffDeferRunnableReplay
                        else
                            DynamicJoinHandoffSurfaceAgedStalledReplay
                    | DynamicJoinReplayPendingOnly ->
                        if terminalAge < ageCap then
                            DynamicJoinHandoffDeferPendingReplay
                        elif freshAuthorityProgress then
                            DynamicJoinHandoffDeferRuntimeUnionCarrier
                        elif meaningfulProgress && terminalAge < ageCap * 2 then
                            DynamicJoinHandoffDeferRecentReplayProgress
                        else
                            DynamicJoinHandoffSurfaceAgedStalledReplay
                    | DynamicJoinReplayNoLive ->
                        if freshAuthorityProgress then
                            DynamicJoinHandoffDeferRuntimeUnionCarrier
                        elif meaningfulProgress && terminalAge < ageCap * 2 then
                            DynamicJoinHandoffDeferRecentReplayProgress
                        else
                            DynamicJoinHandoffSurfaceQuiet
            | _ -> DynamicJoinHandoffNotDynamic

        // MIGRATION: single-flight continuation frontier.
        //
        // MIGRATION proved the bounded trampoline could advance the captured trace, but the log showed
        // several Hopac/JP waiters promoting and running the same cycle concurrently. A ConcurrentQueue
        // made that look like useful parallelism while actually duplicating the same frame and racing the
        // cursor. Keep one canonical frontier per evaluator cycle until typed replay can consume the continuation envelope.
        let private gate = obj()

        type ReplayEventKind private () =
            static member InternedKindTag () = 0x140006u

        type ReplayEventId = CompilerIdentityKernel.InternedTextId<ReplayEventKind>

        module ReplayEventIdOps =
            let create value : ReplayEventId = CompilerIdentityKernel.InternedTextId.create<ReplayEventKind> value
            let text (value: ReplayEventId) = CompilerIdentityKernel.InternedTextIdOps.text value

        [<StructuralEquality; NoComparison>]
        type ParentContinuationPhase2AttemptIdentity = private {
            kind : EvalKind
            key : ReplayKeyId
            site : CompilerIdentityKernel.WorkSiteId
        }

        [<StructuralEquality; NoComparison>]
        type ParentCacheHandoffWakeIdentity = private {
            parentKind : EvalReplayValueStore.EvaluatorNodeKind
            parentShape : CompilerIdentityKernel.WorkShapeId
            parentNodeId : int
            childNodeId : int
            role : EvalReplayValueStore.EvaluatorDependencyRole
        }

        [<StructuralEquality; NoComparison>]
        type SemanticCellSiteIdentity = private {
            kind : EvalKind
            site : CompilerIdentityKernel.WorkSiteId
        }

        [<StructuralEquality; NoComparison>]
        type CanonicalRootObservationIdentity = private {
            kind : EvalKind
            shape : CompilerIdentityKernel.WorkShapeId
            nodeId : int
            site : CompilerIdentityKernel.WorkSiteId
        }

        [<StructuralEquality; NoComparison>]
        type CanonicalRootParentResumeIdentity = private {
            driver : ReplayDriverId
            root : CanonicalRootObservationIdentity
        }

        let private canonicalRootObservationIdentityText (identity: CanonicalRootObservationIdentity) =
            FastRuntimeFormat.format "%s|%s|%d|%s" [| box (evalKindToString identity.kind); box (CompilerIdentityKernel.WorkShapeIdOps.text identity.shape); box identity.nodeId; box (CompilerIdentityKernel.WorkSiteIdOps.text identity.site) |]

        let private canonicalRootParentResumeIdentityText (identity: CanonicalRootParentResumeIdentity) =
            sprintf "%s|%s"
                (replayDriverToString identity.driver)
                (canonicalRootObservationIdentityText identity.root)

        [<StructuralEquality; NoComparison>]
        type ReplayCellIdentity = private {
            kind : EvalKind
            shape : CompilerIdentityKernel.WorkShapeId
            nodeId : int
            site : CompilerIdentityKernel.WorkSiteId
        }

        [<StructuralEquality; NoComparison>]
        type FrameDerivedTyPingPongIdentity = private {
            parent : ReplayCellIdentity
            child : ReplayCellIdentity
        }

        let private replayCellIdentity (cell: ReplayCell) : ReplayCellIdentity =
            { kind = replayCellEvalKindId cell
              shape = cell.shape
              nodeId = cell.nodeId
              site = cell.site }

        let private replayCellIdentityText (identity: ReplayCellIdentity) =
            FastRuntimeFormat.format "%s|%s|%d|%s" [| box (evalKindToString identity.kind); box (CompilerIdentityKernel.WorkShapeIdOps.text identity.shape); box identity.nodeId; box (CompilerIdentityKernel.WorkSiteIdOps.text identity.site) |]

        let private frameDerivedTyPingPongIdentityText (identity: FrameDerivedTyPingPongIdentity) =
            replayCellIdentityText identity.parent + "->" + replayCellIdentityText identity.child

        [<StructuralEquality; NoComparison>]
        type ReplayNullGuardExceptionKind =
            | ReplayNullGuardNullReferenceException
            | ReplayNullGuardOtherException of exceptionType:ReplayKeyId

        [<StructuralEquality; NoComparison>]
        type ReplayNullGuardTaskIdentity =
            | ReplayNullGuardMissingTask
            | ReplayNullGuardTask of driver:ReplayDriverId * status:ReplayTaskStatusId * key:ReplayKeyId

        [<StructuralEquality; NoComparison>]
        type ReplayNullGuardCellIdentity =
            | ReplayNullGuardMissingCell
            | ReplayNullGuardCell of cell:ReplayCellIdentity * status:FrameStatusId

        [<StructuralEquality; NoComparison>]
        type ReplayNullGuardIdentity = private {
            exceptionKind : ReplayNullGuardExceptionKind
            task : ReplayNullGuardTaskIdentity
            cell : ReplayNullGuardCellIdentity
        }

        [<StructuralEquality; NoComparison>]
        type StaleRootRetargetIdentity = private {
            incoming : ReplayCellIdentity
            frameKey : ReplayKeyId
            frameCursor : int
        }

        [<StructuralEquality; NoComparison>]
        type TerminalCycleRepairIdentity =
            | TerminalCycleLetRepair of letNodeId:int * role:EvalReplayValueStore.EvaluatorDependencyRole * childNodeId:int
            | TerminalCycleCompositeRepair of parentShape:CompilerIdentityKernel.WorkShapeId * parentNodeId:int * role:EvalReplayValueStore.EvaluatorDependencyRole * childKind:EvalKind * childNodeId:int

        [<StructuralEquality; NoComparison>]
        type LeafParentContinuationYieldIdentity = private {
            leafKind : EvalKind
            leafStatus : FrameStatusId
            leafCursor : int
            leafSite : CompilerIdentityKernel.WorkSiteId
            leafNodeId : int option
            alternateKind : EvalKind
            alternateStatus : FrameStatusId
            alternateNodeId : int option
            alternateSite : CompilerIdentityKernel.WorkSiteId
        }

        [<StructuralEquality; NoComparison>]
        type SelectedFrontierStepperReplayIdentity =
            | SelectedFrontierCapturedCellReplay of repeatedKey:ReplayKeyId * nodeId:int * shape:CompilerIdentityKernel.WorkShapeId * cursor:int * step:int
            | SelectedFrontierTypedStepperReplay of repeatedKey:ReplayKeyId * nodeId:int * shape:CompilerIdentityKernel.WorkShapeId
            | SelectedFrontierTypedStepperRearm of repeatedKey:ReplayKeyId * nodeId:int * shape:CompilerIdentityKernel.WorkShapeId * cursor:int * step:int

        [<StructuralEquality; NoComparison>]
        type ReplayFramePendingIdentity = private {
            kind : EvalKind
            key : ReplayKeyId
            site : CompilerIdentityKernel.WorkSiteId
        }

        let private replayFramePendingIdentity (frame:Frame) : ReplayFramePendingIdentity =
            { kind = frame.kind
              key = frame.key
              site = frame.site }

        [<StructuralEquality; NoComparison>]
        type ReplayCellProgressIdentity = private {
            cell : ReplayCellIdentity
            status : FrameStatusId
            cursor : int
            step : int
        }

        [<StructuralEquality; NoComparison>]
        type ReplayFrontierFingerprintIdentity = private {
            kind : EvalKind
            key : ReplayKeyId
            site : CompilerIdentityKernel.WorkSiteId
            cursor : int
            traceLength : int
            status : FrameStatusId
            queueDepth : int
            cell : ReplayCellProgressIdentity option
        }

        let private stableRootFactsOfIdentity (identity: ReplayFrontierFingerprintIdentity) =
            let semanticRootComplete =
                identity.status = FrameSemanticRootComplete
                || (identity.cell |> Option.exists (fun progress -> progress.status = FrameSemanticRootComplete))
            let cellHas shape status =
                identity.cell
                |> Option.exists (fun progress -> progress.cell.shape = shape && progress.status = status)
            [ if semanticRootComplete then StableRootSemanticRootComplete
              if cellHas CompilerIdentityKernel.WorkShapeIdOps.Known.eUnitTest FrameSemanticRootComplete then StableRootUnitTestComplete
              if cellHas CompilerIdentityKernel.WorkShapeIdOps.Known.eSeq FrameCaptured then StableRootSequenceCaptured
              if cellHas CompilerIdentityKernel.WorkShapeIdOps.Known.tPrim FrameCaptured then StableRootPrimitiveCaptured
              if cellHas CompilerIdentityKernel.WorkShapeIdOps.Known.eTypeApply FrameSemanticRootComplete then StableRootTypeApplyComplete
              if cellHas CompilerIdentityKernel.WorkShapeIdOps.Known.eSeq FrameSemanticRootComplete then StableRootSequenceComplete
              if cellHas CompilerIdentityKernel.WorkShapeIdOps.Known.tFun FrameCaptured then StableRootFunctionCaptured ]
            |> Set.ofList

        [<StructuralEquality; NoComparison>]
        type StableRootSelectedIdentity = private {
            blockedRoot : ReplayFrontierFingerprintIdentity
            selected : ReplayFrontierFingerprintIdentity
        }

        // MIGRATION: repeated phase2 bridging of the same typed key is observer churn,
        // not semantic authority. Keep a compact per-key ledger and fail closed after
        // the compiled policy cap instead of re-pinning/bridging indefinitely.
        let private parentContinuationPhase2Attempts =
            System.Collections.Concurrent.ConcurrentDictionary<ParentContinuationPhase2AttemptIdentity,int>()
        let noteParentContinuationPhase2Attempt (kind: EvalKind) (key: string) (site: string) =
            let identity : ParentContinuationPhase2AttemptIdentity = {
                kind = kind
                key = ReplayKeyIdOps.create key
                site = CompilerIdentityKernel.WorkSiteIdOps.create site
            }
            parentContinuationPhase2Attempts.AddOrUpdate(identity, 1, (fun _ old -> old + 1))
        let private parentCacheHandoffWakeAttempts =
            System.Collections.Concurrent.ConcurrentDictionary<ParentCacheHandoffWakeIdentity,int>()
        let private noteParentCacheHandoffWakeAttempt (identity: ParentCacheHandoffWakeIdentity) =
            parentCacheHandoffWakeAttempts.AddOrUpdate(identity, 1, (fun _ old -> old + 1))
        let mutable private frontier : Frame option = None
        let mutable private frontierTerm : Frame option = None
        let mutable private frontierTy : Frame option = None
        let mutable private activeRun = false
        let mutable private captureSeq = 0L
        let mutable private replaySeq = 0L
        let mutable private replayScheduledKey : ReplayTaskKeyId option = None
        let mutable private replayQueue : ReplayTask list = []
        // MIGRATION: same-run semantic-payload backfill cache.
        // MIGRATION reached semantic_replay_payload_missing_blocked even though
        // semantic cells for the same kind/site were observed earlier in the run.
        // Store only observed ReplayCell metadata; this never fabricates values.
        let private semanticCellsByKindSite = System.Collections.Concurrent.ConcurrentDictionary<SemanticCellSiteIdentity, ReplayCell>()
        // MIGRATION: remember the first missing-payload replay terminal so later
        // downstream terminals cannot shadow the root replay-payload contract.
        let mutable private pinnedReplayPayloadMissing : Frame option = None
        // MIGRATION: remember the strongest explicit terminal contract observed so a
        // downstream let-success/apply/deferred blocker cannot shadow the real upstream
        // missing stepper contract in retry_stop.
        let mutable private pinnedTerminalContract : Frame option = None
        // MIGRATION: durable per-BuildFile terminal ledger.  MIGRATION showed
        // the live pin can be cleared by root-complete shielding before the final
        // replay-root handoff branch asks for it; keep the strongest terminal
        // observed in this transaction without making it a semantic success.
        let mutable private durableTerminalContract : Frame option = None
        // MIGRATION: compact anti-repeat ledger for continuation replays that make no semantic progress.
        [<StructuralEquality; NoComparison>]
        type ReplayFingerprintIdentity = private {
            driver : ReplayDriverId
            taskKey : ReplayKeyId
            cellKind : EvalKind
            cellShape : CompilerIdentityKernel.WorkShapeId
            cellNodeId : int
            cursor : int
            outcome : CompilerKernelV2.OperationalReasonId
            next : ReplayCommitNextId
        }

        let private replayFingerprintIdentityText (identity: ReplayFingerprintIdentity) =
            FastRuntimeFormat.format "%s|%s|%s|%s|%d|cursor=%d|outcome=%s|next=%s" [| box (replayDriverToString identity.driver); box (ReplayKeyIdOps.text identity.taskKey); box (evalKindToString identity.cellKind); box (CompilerIdentityKernel.WorkShapeIdOps.text identity.cellShape); box identity.cellNodeId; box identity.cursor; box (CompilerKernelV2.OperationalReasonIdOps.text identity.outcome); box (replayCommitNextIdText identity.next) |]

        let private replayFingerprintRepeats = System.Collections.Generic.Dictionary<ReplayFingerprintIdentity,int>()
        // MIGRATION: a canonical root may request its parent continuation once. The
        // source-value cache can already be populated before that first handoff, so
        // exact-once is tracked by the root/parent relation rather than cache presence.
        let private replayCanonicalRootParentResumeConsumed = System.Collections.Generic.Dictionary<CanonicalRootParentResumeIdentity,byte>()
        // MIGRATION: root completion observation is distinct from parent-resume authority.
        // A replay task key may be reminted while the semantic cell is unchanged; use the
        // stable cell relation to prevent already-committed roots from renewing liveness.
        let private replayCanonicalRootObservationRepeats = System.Collections.Generic.Dictionary<CanonicalRootObservationIdentity,int>()
        // Synthetic ty/TFun <-> ty/TB edges are suppressed, but the same pair can still
        // re-enter through the scheduler. Bound that exact pair so it becomes a typed
        // failure instead of an unbounded observer loop.
        let private frameDerivedTyPingPongSuppressionRepeats = System.Collections.Generic.Dictionary<FrameDerivedTyPingPongIdentity,int>()
        let private frame_derived_ty_pingpong_repeat_cap = 64
        // MIGRATION: compact ledger for child replay scheduling that repeats the same semantic child.
        // MIGRATION proved the final macro terminal is correct, but a 245s gap before retry_stop
        // was spent re-scheduling the same seq/apply/deferred children around parsing.spi:257.
        // Cap that repeat as a terminal contract so retry_stop can fail closed before JP watchdog.
        let private replay_child_schedule_repeat_cap = 8
        // MIGRATION: annot-test ArgumentNullException(key) is a replay obligation
        // while at least one branch has just been scheduled.  Historical runtime showed
        // the true ELet branch was scheduled and BigStack immediately consumed the
        // rank-87 terminal before that short replay window could close.  Track the
        // exact annot-test branch key and pin only after a bounded repeat window.
        [<StructuralEquality; NoComparison>]
        type AnnotTestBranchSelectionIdentity = private {
            annotNodeId : int
            typeNodeId : int
            branch : ReplayKeyId
            branchShape : CompilerIdentityKernel.WorkShapeId
        }

        let private annotTestBranchSelectionIdentityText (identity: AnnotTestBranchSelectionIdentity) =
            FastRuntimeFormat.format "annot_test|%d|%d|%s|%s" [| box identity.annotNodeId; box identity.typeNodeId; box (ReplayKeyIdOps.text identity.branch); box (CompilerIdentityKernel.WorkShapeIdOps.text identity.branchShape) |]

        let private annotTestBranchSelectionGuardRepeats = System.Collections.Generic.Dictionary<AnnotTestBranchSelectionIdentity,int>()
        let private annot_test_branch_selection_guard_cap = 2
        let private noteAnnotTestBranchSelectionGuard (identity: AnnotTestBranchSelectionIdentity) =
            lock gate (fun () ->
                let mutable prior = 0
                let nextCount = if annotTestBranchSelectionGuardRepeats.TryGetValue(identity, &prior) then prior + 1 else 1
                annotTestBranchSelectionGuardRepeats.[identity] <- nextCount
                nextCount)
        // MIGRATION: reentrant semantic-cell attachments can starve the replay loop without ever
        // reaching the child schedule repeat guard.  Historical runtime emitted only reentrant-poke
        // suppressions for the same EOp/EV cells while an active driver stayed alive.  Count
        // those suppressions by semantic cell and promote the exact cell to a terminal contract.
        [<StructuralEquality; NoComparison>]
        type ParentReplayCellLocatorId =
            | ParentReplayCellNodeId of int
            | ParentReplayCellSiteAtom of ReplayKeyId

        [<StructuralEquality; NoComparison>]
        type ParentReplayPreservedIdentity =
            | ParentReplayPreservedCell of
                driver:ReplayDriverId *
                kind:EvalKind *
                shape:CompilerIdentityKernel.WorkShapeId *
                locator:ParentReplayCellLocatorId *
                siteAtom:ReplayKeyId *
                status:FrameStatusId *
                cursor:int *
                step:int
            | ParentReplayPreservedMissingCell of driver:ReplayDriverId * taskKeyAtom:ReplayKeyId

        [<StructuralEquality; NoComparison>]
        type ParentReplayPreservedHotKeyId =
            | ParentReplayPreservedHotNone
            | ParentReplayPreservedHotIdentity of ParentReplayPreservedIdentity
            | ParentReplayPreservedHotAlias of ReplayKeyId

        let private parentReplayCellLocatorText = function
            | ParentReplayCellNodeId nodeId -> string nodeId
            | ParentReplayCellSiteAtom siteAtom -> ReplayKeyIdOps.text siteAtom

        let private parentReplayPreservedIdentityText = function
            | ParentReplayPreservedCell(driver, kind, shape, locator, siteAtom, status, cursor, step) ->
                FastRuntimeFormat.format "%s|%s|%s|%s|%s|%s|cursor=%d|step=%d" [| box (replayDriverToString driver); box (evalKindToString kind); box (CompilerIdentityKernel.WorkShapeIdOps.text shape); box (parentReplayCellLocatorText locator); box (ReplayKeyIdOps.text siteAtom); box (frameStatusToString status); box cursor; box step |]
            | ParentReplayPreservedMissingCell(driver, taskKeyAtom) ->
                sprintf "%s|%s|missing_cell"
                    (replayDriverToString driver)
                    (ReplayKeyIdOps.text taskKeyAtom)

        let parentReplayPreservedHotKeyText = function
            | ParentReplayPreservedHotNone -> ""
            | ParentReplayPreservedHotIdentity identity -> parentReplayPreservedIdentityText identity
            | ParentReplayPreservedHotAlias key -> ReplayKeyIdOps.text key

        let private parentReplayPreservedHotKeyCompactText = function
            | ParentReplayPreservedHotIdentity(ParentReplayPreservedCell(_, kind, _, locator, _, _, _, _)) ->
                let kindText = if kind = EvalTy then "Ty" else "Term"
                FastRuntimeFormat.format "ParentHandoff(%s,Node:%s)" [| box kindText; box (parentReplayCellLocatorText locator) |]
            | hotKey -> parentReplayPreservedHotKeyText hotKey

        let private reentrantReplayPokeRepeats = System.Collections.Generic.Dictionary<ReplayCellIdentity,int>()
        let private reentrantReplayPokeAliasRepeats = System.Collections.Generic.Dictionary<ReplayKeyId,int>()
        let private reentrant_replay_poke_repeat_cap = 64
        let private noteReentrantReplayPoke (cell: ReplayCell) =
            let identity = replayCellIdentity cell
            let identityText = replayCellIdentityText identity
            let aliasId = ReplayKeyIdOps.create identityText
            let count =
                lock gate (fun () ->
                    let mutable prior = 0
                    let nextCount = if reentrantReplayPokeRepeats.TryGetValue(identity, &prior) then prior + 1 else 1
                    reentrantReplayPokeRepeats.[identity] <- nextCount
                    let mutable aliasPrior = 0
                    if (not (reentrantReplayPokeAliasRepeats.TryGetValue(aliasId, &aliasPrior))) || aliasPrior < nextCount then
                        reentrantReplayPokeAliasRepeats.[aliasId] <- nextCount
                    nextCount)
            count, identityText

        type ReplayReasonPayloadId =
            | ReplayReasonReentrantP0FailClosed of key:ReplayKeyId
            | ReplayReasonParentReplayPreserved of key:ReplayKeyId
            | ReplayReasonRaw of value:ReplayKeyId

        type ReplayReasonPayloadMarkerId =
            | ReplayReasonPayloadReentrantP0FailClosed
            | ReplayReasonPayloadParentReplayPreserved

        let private replayReasonPayloadMarkerText = function
            | ReplayReasonPayloadReentrantP0FailClosed -> "reentrant_replay_driver_p0_fail_closed:"
            | ReplayReasonPayloadParentReplayPreserved -> "parent_replay_status_preserved_repeat:"

        let private replayReasonTryPayloadAfter markerId (reasonId:CompilerKernelV2.OperationalReasonId) =
            let reason = CompilerKernelV2.OperationalReasonIdOps.text reasonId
            let marker = replayReasonPayloadMarkerText markerId
            let mutable foundAt = -1
            let mutable index = 0
            let limit = reason.Length - marker.Length
            while foundAt < 0 && index <= limit do
                if System.String.CompareOrdinal(reason, index, marker, 0, marker.Length) = 0 then foundAt <- index
                index <- index + 1
            if foundAt < 0 then None
            else Some(reason.Substring(foundAt + marker.Length))

        let private replayReasonPayloadId (reasonId:CompilerKernelV2.OperationalReasonId) =
            match replayReasonTryPayloadAfter ReplayReasonPayloadReentrantP0FailClosed reasonId with
            | Some key -> ReplayReasonReentrantP0FailClosed (ReplayKeyIdOps.create key)
            | None ->
                match replayReasonTryPayloadAfter ReplayReasonPayloadParentReplayPreserved reasonId with
                | Some key -> ReplayReasonParentReplayPreserved (ReplayKeyIdOps.create key)
                | None ->
                    reasonId
                    |> CompilerKernelV2.OperationalReasonIdOps.text
                    |> ReplayKeyIdOps.create
                    |> ReplayReasonRaw

        let private reentrantReplayP0CountForId (key:ReplayKeyId) =
            if String.IsNullOrWhiteSpace (ReplayKeyIdOps.text key) then 0
            else
                lock gate (fun () ->
                    let mutable count = 0
                    if reentrantReplayPokeAliasRepeats.TryGetValue(key, &count) then count else 0)

        let reentrantReplayP0CountForReason (reasonId: CompilerKernelV2.OperationalReasonId) =
            match replayReasonPayloadId reasonId with
            | ReplayReasonReentrantP0FailClosed key -> reentrantReplayP0CountForId key
            | ReplayReasonParentReplayPreserved _ -> 0
            | ReplayReasonRaw value -> reentrantReplayP0CountForId value

        let reentrantReplayP0CountForFrame (frame:Frame) =
            match framePayloadReasonSignal frame.payload with
            | Some (FrameReasonSignalReentrantP0FailClosed key) -> reentrantReplayP0CountForId key
            | _ -> reentrantReplayP0CountForReason frame.reason
        // MIGRATION: the repeat key includes cursor/step so only an exact no-progress
        // parent replay state spends the repeat budget.  Historical runtime showed
        // semantic_step_partial handoffs can still be advancing across ticks.
        // MIGRATION: scheduled parent replay preservation is a liveness guard, not
        // an unbounded parking state. Historical runtime proved the literal-op replay can
        // resolve, then the parent replay can be preserved/deferred again with no
        // new terminal before manual interrupt. Count the exact parent replay/cell
        // identity and fail closed only after repeated preservation of the same
        // typed replay obligation.
        let private parentReplayPreservedRepeats = System.Collections.Generic.Dictionary<ParentReplayPreservedIdentity,int>()
        let private parent_replay_preserved_repeat_cap = 4
        let parentReplayPreservedRepeatCap () = parent_replay_preserved_repeat_cap
        let private normalizeReplayPreservedKeyAtom (raw: string) =
            // MIGRATION: the old repeat key included volatile task handoff strings
            // such as ty:ty@c:/home/git/...; terminal HUD then saw cap evidence while
            // frontier repeat_stats fell back to 0/4.  Normalize every repeat key to
            // the replay cell identity first, keeping full source sites out of the key.
            let v = if String.IsNullOrWhiteSpace raw then "unknown" else raw.Replace("\\", "/")
            let hash = v.LastIndexOf("#", StringComparison.Ordinal)
            if hash >= 0 && hash < v.Length - 1 then v.Substring(hash + 1)
            else
                let slash = v.LastIndexOf("/", StringComparison.Ordinal)
                if slash >= 0 && slash < v.Length - 1 then v.Substring(slash + 1)
                else v

        let private parentReplayPreservedIdentity (task: ReplayTask) (cellOpt: ReplayCell option) =
            match cellOpt with
            | Some cell ->
                let siteAtom = ReplayKeyIdOps.create (normalizeReplayPreservedKeyAtom (replayCellSiteText cell))
                let locator =
                    if cell.nodeId >= 0 then ParentReplayCellNodeId cell.nodeId
                    else ParentReplayCellSiteAtom siteAtom
                ParentReplayPreservedCell(
                    replayTaskDriverId task,
                    replayCellEvalKindId cell,
                    cell.shape,
                    locator,
                    siteAtom,
                    frameStatusOfReplayCellStatusId cell.status,
                    cell.cursor,
                    cell.step)
            | None ->
                ParentReplayPreservedMissingCell(
                    replayTaskDriverId task,
                    ReplayKeyIdOps.create (normalizeReplayPreservedKeyAtom (ReplayTaskKeyIdOps.text task.key)))

        let private parentReplayPreservedKey (task: ReplayTask) (cellOpt: ReplayCell option) =
            parentReplayPreservedIdentity task cellOpt
            |> parentReplayPreservedIdentityText

        let private parentReplayPreservedAliasRepeats = System.Collections.Generic.Dictionary<ReplayKeyId,int>()

        let private parentReplayPreservedCountForId (key: ReplayKeyId) =
            lock gate (fun () ->
                let mutable count = 0
                if parentReplayPreservedAliasRepeats.TryGetValue(key, &count) then count else 0)

        let parentReplayPreservedCountForKey (key: string) =
            if String.IsNullOrWhiteSpace key then 0
            else
                key
                |> normalizeReplayPreservedKeyAtom
                |> ReplayKeyIdOps.create
                |> parentReplayPreservedCountForId

        let parentReplayPreservedMaxRepeatSnapshot () =
            lock gate (fun () ->
                let mutable bestCount = 0
                let mutable bestKey = ParentReplayPreservedHotNone
                for kv in parentReplayPreservedRepeats do
                    if kv.Value > bestCount then
                        bestCount <- kv.Value
                        bestKey <- ParentReplayPreservedHotIdentity kv.Key
                for kv in parentReplayPreservedAliasRepeats do
                    if kv.Value > bestCount then
                        bestCount <- kv.Value
                        bestKey <- ParentReplayPreservedHotAlias kv.Key
                bestCount, parent_replay_preserved_repeat_cap, bestKey)

        let parentReplayPreservedRepeatCapBreachedSnapshot () =
            let count, cap, key = parentReplayPreservedMaxRepeatSnapshot()
            count, cap, key, count > cap

        let private noteParentReplayPreservedAliasUnlocked (alias: string) (count: int) =
            if not (String.IsNullOrWhiteSpace alias) then
                let key = alias |> normalizeReplayPreservedKeyAtom |> ReplayKeyIdOps.create
                let mutable prior = 0
                if (not (parentReplayPreservedAliasRepeats.TryGetValue(key, &prior))) || prior < count then
                    parentReplayPreservedAliasRepeats.[key] <- count

        let private parentReplayPreservedCountForIngressId (key: ReplayKeyId) =
            key
            |> ReplayKeyIdOps.text
            |> normalizeReplayPreservedKeyAtom
            |> ReplayKeyIdOps.create
            |> parentReplayPreservedCountForId

        let parentReplayPreservedCountForReason (reasonId: CompilerKernelV2.OperationalReasonId) =
            match replayReasonPayloadId reasonId with
            | ReplayReasonParentReplayPreserved key -> parentReplayPreservedCountForIngressId key
            | ReplayReasonReentrantP0FailClosed _ -> 0
            | ReplayReasonRaw value -> parentReplayPreservedCountForIngressId value

        let parentReplayPreservedCountForFrame (frame: Frame) =
            let reasonCount =
                match framePayloadReasonSignal frame.payload with
                | Some (FrameReasonSignalParentReplayStatusPreservedRepeat key) -> parentReplayPreservedCountForIngressId key
                | Some _ -> 0
                | None -> parentReplayPreservedCountForReason frame.reason
            [ reasonCount
              parentReplayPreservedCountForKey (frameKeyText frame)
              parentReplayPreservedCountForKey (frameSiteText frame) ]
            |> List.max

        let parentReplayPreservedHotKeyForFrame (frame: Frame) =
            match framePayloadReasonSignal frame.payload with
            | Some (FrameReasonSignalParentReplayStatusPreservedRepeat key)
            | Some (FrameReasonSignalReentrantP0FailClosed key) -> ParentReplayPreservedHotAlias key
            | _ ->
                let rawKey =
                    let key = frameKeyText frame
                    if String.IsNullOrWhiteSpace key then frameSiteText frame else key
                if String.IsNullOrWhiteSpace rawKey then ParentReplayPreservedHotNone
                else
                    rawKey
                    |> normalizeReplayPreservedKeyAtom
                    |> ReplayKeyIdOps.create
                    |> ParentReplayPreservedHotAlias

        let private noteParentReplayPreserved (task: ReplayTask) (cellOpt: ReplayCell option) =
            let identity = parentReplayPreservedIdentity task cellOpt
            let identityText = parentReplayPreservedIdentityText identity
            let count =
                lock gate (fun () ->
                    let mutable prior = 0
                    let nextCount = if parentReplayPreservedRepeats.TryGetValue(identity, &prior) then prior + 1 else 1
                    parentReplayPreservedRepeats.[identity] <- nextCount
                    noteParentReplayPreservedAliasUnlocked identityText nextCount
                    noteParentReplayPreservedAliasUnlocked (ReplayTaskKeyIdOps.text task.key) nextCount
                    match cellOpt with
                    | Some cell ->
                        noteParentReplayPreservedAliasUnlocked (string cell.nodeId) nextCount
                        noteParentReplayPreservedAliasUnlocked (replayCellSiteText cell) nextCount
                        noteParentReplayPreservedAliasUnlocked (FastRuntimeFormat.format "%s|%s|%d" [| box (replayCellKindText cell); box (replayCellShapeText cell); box cell.nodeId |]) nextCount
                    | None -> ()
                    nextCount)
            count, identityText
        // MIGRATION: parent-preserved repeat is not a string threshold anymore.
        // If there is a live queued/active replay lane, repeat pressure is a drain
        // obligation; only exact witness hardcaps or quiet repeats pin terminal.
        type ParentReplayPreservedRepeatDecisionId =
            | ParentReplayPreservedRepeatContinue
            | ParentReplayPreservedRepeatDeferLiveReplay
            | ParentReplayPreservedRepeatCycleBreakLiveReplay
            | ParentReplayPreservedRepeatDeferStructuralSurge
            | ParentReplayPreservedRepeatCycleFuseLiveTailGuard
            | ParentReplayPreservedRepeatHardPoisonReentryCap
            | ParentReplayPreservedRepeatPoisonAfterCycleBreakExhausted
            | ParentReplayPreservedRepeatPinTerminal
            | ParentReplayPreservedRepeatPinExactWitness

        let private parentReplayPreservedRepeatDecisionText = function
            | ParentReplayPreservedRepeatContinue -> "continue"
            | ParentReplayPreservedRepeatDeferLiveReplay -> "defer_live_replay"
            | ParentReplayPreservedRepeatCycleBreakLiveReplay -> "cycle_break_live_replay"
            | ParentReplayPreservedRepeatDeferStructuralSurge -> "defer_structural_surge"
            | ParentReplayPreservedRepeatCycleFuseLiveTailGuard -> "replay_repeat_live_tail_guard"
            | ParentReplayPreservedRepeatHardPoisonReentryCap -> "hard_poison_reentry_cap"
            | ParentReplayPreservedRepeatPoisonAfterCycleBreakExhausted -> "poison_after_cycle_break_exhausted"
            | ParentReplayPreservedRepeatPinTerminal -> "pin_terminal"
            | ParentReplayPreservedRepeatPinExactWitness -> "pin_exact_witness"

        // MIGRATION: start the multi-round migration away from ad-hoc replay-driver
        // poison strings.  This DU names the authority boundary used by the driver
        // poison handoff before later rounds move ReplayTask.status/ReplayCell.status
        // themselves from strings into typed cases.
        type ReplayDriverPoisonDecisionId =
            | ReplayDriverPoisonNoPoison
            | ReplayDriverPoisonCellPoison
            | ReplayDriverPoisonPayloadPoison
            | ReplayDriverPoisonFrontierSameIdentityPoison
            | ReplayDriverPoisonFrontierFallbackPoison

        let private replayDriverPoisonDecisionText = function
            | ReplayDriverPoisonNoPoison -> "no_poison"
            | ReplayDriverPoisonCellPoison -> "cell_poison"
            | ReplayDriverPoisonPayloadPoison -> "payload_poison"
            | ReplayDriverPoisonFrontierSameIdentityPoison -> "frontier_same_identity_poison"
            | ReplayDriverPoisonFrontierFallbackPoison -> "frontier_fallback_poison"

        let private parentReplayPreservedRepeatDecisionShouldPin = function
            | ParentReplayPreservedRepeatPinTerminal
            | ParentReplayPreservedRepeatPinExactWitness
            | ParentReplayPreservedRepeatHardPoisonReentryCap
            | ParentReplayPreservedRepeatPoisonAfterCycleBreakExhausted -> true
            | ParentReplayPreservedRepeatContinue
            | ParentReplayPreservedRepeatDeferLiveReplay
            | ParentReplayPreservedRepeatCycleBreakLiveReplay
            | ParentReplayPreservedRepeatDeferStructuralSurge
            | ParentReplayPreservedRepeatCycleFuseLiveTailGuard -> false

        let private parentReplayPreservedRepeatTerminalStatusId = function
            | ParentReplayPreservedRepeatPoisonAfterCycleBreakExhausted
            | ParentReplayPreservedRepeatHardPoisonReentryCap -> SemanticParentReplayCycleBreakPoisoned
            | _ -> SemanticParentReplayStatusPreservedRepeatBlocked

        let private parentReplayPreservedRepeatTerminalStatus decision =
            decision |> parentReplayPreservedRepeatTerminalStatusId |> semanticStatusToString

        // MIGRATION: second-pass assessment guard.  MIGRATION blocked the named
        // cross_kind_active_replay_driver branch, but the same p=0 yield-thrash
        // leaked through parent-replay preserved deferrals.  Treat pending=0 as a
        // terminal graph fact before calling Thread.Yield.
        type ParentReplayPreservedYieldThrashDecisionId =
            | ParentReplayPreservedYieldAllowed
            | ParentReplayPreservedHardPoisonPendingZero
            | ParentReplayPreservedYieldCapBreachedSurface

        let private parentReplayPreservedYieldThrashDecisionText = function
            | ParentReplayPreservedYieldAllowed -> "yield_allowed"
            | ParentReplayPreservedHardPoisonPendingZero -> "hard_poison_pending_zero"
            | ParentReplayPreservedYieldCapBreachedSurface -> "surface_cascaded_terminal_repeat_cap_breach"

        let private parentReplayPreservedYieldThrashDecisionFor decision repeatCount repeatCap pending queueDepth activeDepth writeWitness =
            let liveQueueOrActive = queueDepth > 0 || activeDepth > 0
            let smallTailAtCap =
                decision = ParentReplayPreservedRepeatCycleFuseLiveTailGuard
                && repeatCount >= repeatCap
                && pending > 0
                && queueDepth <= 3
                && activeDepth <= 1
                && not writeWitness
            if (repeatCount > repeatCap && not writeWitness) || smallTailAtCap then
                // MIGRATION: q/a/p liveness is evidence, not authority, once the
                // parent-preserved live-tail guard reaches its local cap on a tiny
                // tail.  1528 ended manually at q/a/p=3/1/2 with count=4/cap=4;
                // waiting for count>cap simply burns another scheduler lap.
                ParentReplayPreservedYieldCapBreachedSurface
            else
                match decision with
                | ParentReplayPreservedRepeatDeferLiveReplay
                | ParentReplayPreservedRepeatCycleBreakLiveReplay
                | ParentReplayPreservedRepeatDeferStructuralSurge
                | ParentReplayPreservedRepeatCycleFuseLiveTailGuard when pending = 0 && not liveQueueOrActive && not writeWitness ->
                    ParentReplayPreservedHardPoisonPendingZero
                | _ -> ParentReplayPreservedYieldAllowed

        // MIGRATION: cooperative handoff repeat-cap breach needs its own closed
        // decision because historical runtime surfaced repeat=9/4 while q/a/p=6/4/2.
        // Pending obligations plus a physical queue are still runnable replay, not
        // proof that the cascaded parent poison should surface on this turn.
        // MIGRATION: once a physical repeat key surfaces, probation is exact-once.
        // A fresh scheduler reason cannot reopen the same exhausted relation.
        let private cooperativeRepeatCapSurfacedKeys =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, byte>()

        let private cooperativeRepeatCapIdentity repeatKey =
            CompilerIdentityKernel.ContentDigest.ofText "cooperative-repeat-cap" repeatKey

        let private cooperativeRepeatCapSurfaceAlreadyLatched repeatKey =
            not (System.String.IsNullOrWhiteSpace repeatKey)
            && cooperativeRepeatCapSurfacedKeys.ContainsKey(cooperativeRepeatCapIdentity repeatKey)

        let private cooperativeRepeatCapSurfaceLatch repeatKey =
            if System.String.IsNullOrWhiteSpace repeatKey then false
            else cooperativeRepeatCapSurfacedKeys.TryAdd(cooperativeRepeatCapIdentity repeatKey, 0uy)

        type CooperativeRepeatCapSurfaceDecisionId =
            | CooperativeRepeatCapSurfaceNow
            | CooperativeRepeatCapDeferPendingActiveTail
            | CooperativeRepeatCapDeferActiveOnlyPendingTail
            | CooperativeRepeatCapDeferFreshQueueTail

        let private cooperativeRepeatCapSurfaceDecisionText = function
            | CooperativeRepeatCapSurfaceNow -> "surface_now"
            | CooperativeRepeatCapDeferPendingActiveTail -> "defer_pending_active_tail"
            | CooperativeRepeatCapDeferActiveOnlyPendingTail -> "defer_active_only_pending_tail"
            | CooperativeRepeatCapDeferFreshQueueTail -> "defer_fresh_queue_tail"

        let private cooperativeRepeatCapSurfaceShouldDefer = function
            | CooperativeRepeatCapDeferPendingActiveTail
            | CooperativeRepeatCapDeferActiveOnlyPendingTail
            | CooperativeRepeatCapDeferFreshQueueTail -> true
            | CooperativeRepeatCapSurfaceNow -> false

        let private cooperativeRepeatCapSurfaceDecisionFor repeatCount repeatCap surfaceAlreadyLatched pending queueDepth activeDepth replayComplete writeWitness =
            let boundedPendingTailExhausted =
                repeatCap > 0
                && repeatCount >= repeatCap * 3
                && pending > 0
                && pending <= 2
                && queueDepth > 0
                && queueDepth <= 16
                && activeDepth > 0
                && activeDepth <= 2
                && not writeWitness
            // MIGRATION: q/a/p is liveness evidence, not an infinite lease. 2298
            // repeated the same physical parent-handoff at 12/4 with q/a/p=16/1/2
            // for minutes. Once the bounded tail spends three local caps, or the
            // same key has already surfaced once, it may not re-enter probation.
            if replayComplete || writeWitness || surfaceAlreadyLatched || boundedPendingTailExhausted then CooperativeRepeatCapSurfaceNow
            elif pending > 0 && queueDepth > 0 && activeDepth > 0 then CooperativeRepeatCapDeferPendingActiveTail
            elif pending > 0 && activeDepth > 0 then CooperativeRepeatCapDeferActiveOnlyPendingTail
            elif pending = 0 && queueDepth > 0 && activeDepth > 0 then CooperativeRepeatCapDeferFreshQueueTail
            else CooperativeRepeatCapSurfaceNow

        // MIGRATION: stack-fence repeat-cap breach is also a typed decision.
        // Runtime evidence surfaced stack_fence_cap_breach_surface with q/a/p=/2,
        // which is a live pending+active tail.  The stack fence must defer the
        // cascaded terminal just like the cooperative handoff path.
        type StackFenceRepeatCapDecisionId =
            | StackFenceRepeatCapSurfaceNow
            | StackFenceRepeatCapDeferPendingActiveTail
            | StackFenceRepeatCapDeferFreshQueueTail

        let private stackFenceRepeatCapDecisionText = function
            | StackFenceRepeatCapSurfaceNow -> "surface_now"
            | StackFenceRepeatCapDeferPendingActiveTail -> "defer_pending_active_tail"
            | StackFenceRepeatCapDeferFreshQueueTail -> "defer_fresh_queue_tail"

        let private stackFenceRepeatCapShouldDefer = function
            | StackFenceRepeatCapDeferPendingActiveTail
            | StackFenceRepeatCapDeferFreshQueueTail -> true
            | StackFenceRepeatCapSurfaceNow -> false

        let private stackFenceRepeatCapDecisionFor pending queueDepth activeDepth replayComplete writeWitness =
            // MIGRATION: p>0/a>0 is the strongest stack-fence liveness signal.
            // 1486.jsonl surfaced stack_fence_cap_breach_surface at q/a/p=/2
            // because replay_complete/write_witness can flicker while pending fence
            // waiters are still owned.  Defer the pending-active tail before trusting
            // the replay-complete bit; the surrounding budget remains bounded.
            if pending > 0 && activeDepth > 0 && queueDepth >= 0 then StackFenceRepeatCapDeferPendingActiveTail
            elif replayComplete || writeWitness then StackFenceRepeatCapSurfaceNow
            elif queueDepth > 0 && activeDepth > 0 then StackFenceRepeatCapDeferFreshQueueTail
            else StackFenceRepeatCapSurfaceNow

        // MIGRATION: MIGRATION still let a pending-zero parent poison terminal be
        // erased by "recent progress" credit.  Recent replay/root chatter can open a
        // phase2 transition before this branch, but once this branch sees p=0 the
        // terminal itself must remain authoritative.
        type ParentReplayTerminalRecentProgressDecisionId =
            | ParentReplayTerminalRecentProgressAllowClearWithWitness
            | ParentReplayTerminalRecentProgressKeepPinnedPendingZero
            | ParentReplayTerminalRecentProgressConfirmPhysicalTailDrained
            | ParentReplayTerminalRecentProgressSurfaceReplayOnlyNoRootAuthority
            | ParentReplayTerminalRecentProgressSurfacePhysicalTailDrained
            | ParentReplayTerminalRecentProgressDeferLiveTail

        let parentReplayTerminalRecentProgressDecisionText = function
            | ParentReplayTerminalRecentProgressAllowClearWithWitness -> "allow_clear_with_witness"
            | ParentReplayTerminalRecentProgressKeepPinnedPendingZero -> "keep_pinned_pending_zero"
            | ParentReplayTerminalRecentProgressConfirmPhysicalTailDrained -> "confirm_pending_zero_physical_tail_drained"
            | ParentReplayTerminalRecentProgressSurfaceReplayOnlyNoRootAuthority -> "surface_replay_only_no_root_authority"
            | ParentReplayTerminalRecentProgressSurfacePhysicalTailDrained -> "surface_pending_zero_physical_tail_drained"
            | ParentReplayTerminalRecentProgressDeferLiveTail -> "defer_live_tail"

        let parentReplayTerminalRecentProgressDecisionShouldClear = function
            | ParentReplayTerminalRecentProgressAllowClearWithWitness -> true
            | ParentReplayTerminalRecentProgressKeepPinnedPendingZero
            | ParentReplayTerminalRecentProgressConfirmPhysicalTailDrained
            | ParentReplayTerminalRecentProgressSurfaceReplayOnlyNoRootAuthority
            | ParentReplayTerminalRecentProgressSurfacePhysicalTailDrained
            | ParentReplayTerminalRecentProgressDeferLiveTail -> false

        let parentReplayTerminalRecentProgressDecisionShouldDrainTail = function
            | ParentReplayTerminalRecentProgressConfirmPhysicalTailDrained
            | ParentReplayTerminalRecentProgressDeferLiveTail -> true
            | ParentReplayTerminalRecentProgressAllowClearWithWitness
            | ParentReplayTerminalRecentProgressKeepPinnedPendingZero
            | ParentReplayTerminalRecentProgressSurfaceReplayOnlyNoRootAuthority
            | ParentReplayTerminalRecentProgressSurfacePhysicalTailDrained -> false

        let parentReplayTerminalRecentProgressDecisionFor
            (pending: int)
            (queueDepth: int)
            (activeDepth: int)
            (writeWitness: bool)
            (recentReplayDelta: int64)
            (recentRootDelta: int64)
            (recentSampledDelta: int64)
            (recentTerminalDelta: int64)
            (terminalAgeMs: int)
            (stableDrainAgeMs: int)
            =
            let replayOnlyNoRootAuthorityMature =
                pending = 0
                && not writeWitness
                && queueDepth <= 0
                && activeDepth <= 0
                && terminalAgeMs >= max 750 (stableDrainAgeMs / 2)
                && recentReplayDelta > 0L
                && recentSampledDelta > 0L
                && recentRootDelta <= 0L
            if replayOnlyNoRootAuthorityMature then
                ParentReplayTerminalRecentProgressSurfaceReplayOnlyNoRootAuthority
            elif pending = 0 && not writeWitness && queueDepth <= 0 && activeDepth <= 0 && terminalAgeMs < stableDrainAgeMs then
                ParentReplayTerminalRecentProgressConfirmPhysicalTailDrained
            elif pending = 0 && not writeWitness && queueDepth <= 0 && activeDepth <= 0 then
                ParentReplayTerminalRecentProgressSurfacePhysicalTailDrained
            elif pending = 0 && not writeWitness && (queueDepth > 0 || activeDepth > 0) then
                // MIGRATION: historical runtime disproved the old assumption that pinned
                // rank-83 q/a tail is only residue: the same frame still had root and
                // replay deltas plus q/a live.  Defer until the physical tail is truly
                // quiet or a hard/stale authority path fires.
                ParentReplayTerminalRecentProgressDeferLiveTail
            elif pending = 0 then ParentReplayTerminalRecentProgressKeepPinnedPendingZero
            elif writeWitness && (recentReplayDelta > 0L || recentRootDelta > 0L || recentSampledDelta > 0L || recentTerminalDelta > 0L) then
                ParentReplayTerminalRecentProgressAllowClearWithWitness
            elif queueDepth > 0 || activeDepth > 0 then ParentReplayTerminalRecentProgressDeferLiveTail
            else ParentReplayTerminalRecentProgressKeepPinnedPendingZero

        // MIGRATION: audit pass after 1339.  Cooperative replay may only reschedule
        // a pending-zero tail when it has a real writer/root witness.  Grace/live
        // terminal labels are no longer harmless observability; they are part of the
        // livelock mechanism the assessments kept flagging.
        type ReplayDriverCooperativePendingZeroDecisionId =
            | ReplayDriverCooperativeAllowSchedule
            | ReplayDriverCooperativeHardStopPendingZero

        type ReplayDriverTickCauseId =
            | ReplayTickParentReplayPreserved
            | ReplayTickDynamicFunctionBridge
            | ReplayTickParentContinuationFill
            | ReplayTickDynamicFunctionCarrier
            | ReplayTickCooperativeHandoff
            | ReplayTickPostActiveParentResume

        let replayDriverCooperativePendingZeroDecisionText = function
            | ReplayDriverCooperativeAllowSchedule -> "allow_schedule"
            | ReplayDriverCooperativeHardStopPendingZero -> "hard_stop_pending_zero"

        let replayDriverCooperativePendingZeroDecisionShouldStop = function
            | ReplayDriverCooperativeHardStopPendingZero -> true
            | ReplayDriverCooperativeAllowSchedule -> false

        let private replayDriverTickCauseIsAssessmentEscape = function
            | ReplayTickCooperativeHandoff
            | ReplayTickPostActiveParentResume -> true
            | ReplayTickParentReplayPreserved
            | ReplayTickDynamicFunctionBridge
            | ReplayTickParentContinuationFill
            | ReplayTickDynamicFunctionCarrier -> false

        let replayDriverCooperativePendingZeroDecisionFor
            (pending: int)
            (queueDepth: int)
            (activeDepth: int)
            (writeWitness: bool)
            (cause: ReplayDriverTickCauseId)
            =
            let hasRunnableTail = queueDepth > 0 || activeDepth > 0
            if pending = 0 && not hasRunnableTail && not writeWitness && replayDriverTickCauseIsAssessmentEscape cause then
                ReplayDriverCooperativeHardStopPendingZero
            else
                ReplayDriverCooperativeAllowSchedule

        let private parentReplayPreservedRepeatDecisionFor repeatCount repeatCap exactWitnessHardcap queueDepth activeDepth pending writeWitness =
            let liveQueueOrActive = queueDepth > 0 || activeDepth > 0
            if exactWitnessHardcap then ParentReplayPreservedRepeatPinExactWitness
            elif repeatCount < repeatCap then
                // MIGRATION: follow the assessment literally.  The local repeat cap,
                // not global pending, decides whether a preserved repeat may continue.
                // pending=0 only says no IVar is parked; it does not prove the replay
                // graph is dead, even if the queue snapshot is momentarily empty.
                ParentReplayPreservedRepeatContinue
            elif liveQueueOrActive && repeatCount >= repeatCap + 1 && not writeWitness then
                // MIGRATION: historical runtime still allowed repeat=5/4 and 6/4 when
                // pending JP work existed.  Pending proves there is more graph work,
                // not that this same stale parent continuation can keep bypassing
                // the local repeat cap.  Cap+1 hard-poisons with or without pending.
                ParentReplayPreservedRepeatHardPoisonReentryCap
            elif liveQueueOrActive && repeatCount >= repeatCap then
                // MIGRATION: exactly at the cap gets one typed live-tail guard receipt;
                // the next recurrence hard-poisons above. This preserves evidence while
                // preventing cap+2/cap+8 churn.
                ParentReplayPreservedRepeatCycleFuseLiveTailGuard
            elif liveQueueOrActive then
                ParentReplayPreservedRepeatDeferLiveReplay
            elif pending > 0 && not writeWitness then ParentReplayPreservedRepeatDeferStructuralSurge
            elif repeatCount >= repeatCap + 16 then ParentReplayPreservedRepeatPoisonAfterCycleBreakExhausted
            elif repeatCount >= repeatCap && not writeWitness then ParentReplayPreservedRepeatPinTerminal
            elif repeatCount >= repeatCap then ParentReplayPreservedRepeatPoisonAfterCycleBreakExhausted
            else ParentReplayPreservedRepeatPinTerminal

        // MIGRATION: a scheduled_parent_replay that has already hit the preserved-repeat cap is terminal.
        // Runtime evidence showed MIGRATION fixed the NullReferenceException loop, then pinned
        // semantic_parent_replay_status_preserved_repeat_blocked while the same live replay
        // kept executing and required manual interruption. Once this cap is hit, remove the
        // replay task from the queue and publish the existing terminal instead of resuming it.
        // MIGRATION: a guarded NullReferenceException is liveness only while it
        // exposes fresh replay evidence. Historical runtime kept reporting the same
        // let-success/apply-continuation null guards until manual interruption.
        // Count the exact replay task/cell identity and promote it to an
        // existing explicit terminal after a small cap instead of inventing a
        // new state or spinning semantic_step_partial forever.
        let private replayNullGuardExceptionKindFor (ex: exn) =
            if ex :? NullReferenceException then ReplayNullGuardNullReferenceException
            else ReplayNullGuardOtherException (ReplayKeyIdOps.create (ex.GetType().Name))

        let private replayNullGuardTaskIdentity (taskOpt: ReplayTask option) =
            match taskOpt with
            | Some (task: ReplayTask) ->
                ReplayNullGuardTask(
                    replayTaskDriverId task,
                    replayTaskStatusId task,
                    ReplayKeyIdOps.create (ReplayTaskKeyIdOps.text task.key))
            | None -> ReplayNullGuardMissingTask

        let private replayNullGuardCellIdentity (cellOpt: ReplayCell option) =
            match cellOpt with
            | Some (cell: ReplayCell) -> ReplayNullGuardCell(replayCellIdentity cell, frameStatusOfReplayCellStatusId cell.status)
            | None -> ReplayNullGuardMissingCell

        let private replayNullGuardIdentityText (identity: ReplayNullGuardIdentity) =
            let exceptionText =
                match identity.exceptionKind with
                | ReplayNullGuardNullReferenceException -> "NullReferenceException"
                | ReplayNullGuardOtherException exceptionType -> ReplayKeyIdOps.text exceptionType
            let taskText =
                match identity.task with
                | ReplayNullGuardMissingTask -> "missing_task"
                | ReplayNullGuardTask(driver, status, key) ->
                    FastRuntimeFormat.format "%s|%s|%s" [| box (replayDriverToString driver); box (replayTaskStatusToString status); box (ReplayKeyIdOps.text key) |]
            let cellText =
                match identity.cell with
                | ReplayNullGuardMissingCell -> "missing_cell"
                | ReplayNullGuardCell(cell, status) ->
                    FastRuntimeFormat.format "%s|%s|%d|%s|%s" [| box (evalKindToString cell.kind); box (CompilerIdentityKernel.WorkShapeIdOps.text cell.shape); box cell.nodeId; box (CompilerIdentityKernel.WorkSiteIdOps.text cell.site); box (frameStatusToString status) |]
            FastRuntimeFormat.format "%s|%s|%s" [| box exceptionText; box taskText; box cellText |]

        let private replayNullGuardRepeats = System.Collections.Generic.Dictionary<ReplayNullGuardIdentity,int>()
        let private replay_null_guard_repeat_cap = 4
        let private noteReplayNullGuard (taskOpt: ReplayTask option) (cellOpt: ReplayCell option) (ex: exn) =
            let identity : ReplayNullGuardIdentity = {
                exceptionKind = replayNullGuardExceptionKindFor ex
                task = replayNullGuardTaskIdentity taskOpt
                cell = replayNullGuardCellIdentity cellOpt
            }
            let count =
                lock gate (fun () ->
                    let mutable prior = 0
                    let nextCount = if replayNullGuardRepeats.TryGetValue(identity, &prior) then prior + 1 else 1
                    replayNullGuardRepeats.[identity] <- nextCount
                    nextCount)
            count, replayNullGuardIdentityText identity
        // MIGRATION: compact anti-repeat ledger for stale root-complete retargets.
        // A root-complete shell is evidence for its original cell only; if the same
        // different incoming cell repeatedly retargets it, quarantine that retarget
        // as a terminal blocker instead of spinning another continuation envelope.
        let private staleRootRetargetRepeats = System.Collections.Generic.Dictionary<StaleRootRetargetIdentity,int>()
        // MIGRATION: terminal cycle repair attempts share one closed relation ledger.
        // The DU distinguishes ELet repair from broad composite repair while preserving
        // the prior per-relation counters and caps.
        let private terminalCycleRepairs = System.Collections.Generic.Dictionary<TerminalCycleRepairIdentity,int>()
        let private noteTerminalCycleRepairLocked (identity: TerminalCycleRepairIdentity) =
            let mutable prior = 0
            let next = if terminalCycleRepairs.TryGetValue(identity, &prior) then prior + 1 else 1
            terminalCycleRepairs.[identity] <- next
            next
        let private noteLetTerminalCycleRepairLocked letNodeId role childNodeId =
            noteTerminalCycleRepairLocked (TerminalCycleLetRepair(letNodeId, role, childNodeId))
        let private noteCompositeTerminalCycleRepairLocked parentShape parentNodeId role (childKind: EvalKind) childNodeId =
            noteTerminalCycleRepairLocked (
                TerminalCycleCompositeRepair(
                    parentShape,
                    parentNodeId,
                    role,
                    childKind,
                    childNodeId))
        // MIGRATION: a ready replay duplicate can be real progress if the task was
        // produced by MIGRATION's leaf-yield terminal-let repair.  The old duplicate
        // guard suppressed the already-ready task and left retry_stop_drain looping
        // over duplicate=1.  Cap reruns by an interned replay key so punctuation in
        // the human renderer cannot change ownership.
        let private readyDuplicateReplayReruns = System.Collections.Generic.Dictionary<ReplayTaskKeyId,int>()
        let private noteReadyDuplicateReplayRerunLocked (key: ReplayTaskKeyId) =
            let mutable prior = 0
            let next = if readyDuplicateReplayReruns.TryGetValue(key, &prior) then prior + 1 else 1
            readyDuplicateReplayReruns.[key] <- next
            next
        // MIGRATION: retry_stop can churn on the same leaf-parent gap by yielding
        // a ty semantic_leaf_complete frontier to the same term continuation_envelope
        // over and over.  The exact leaf/alternate relation is now structural.
        let private leafParentContinuationYieldRepeats = System.Collections.Generic.Dictionary<LeafParentContinuationYieldIdentity,int>()
        let private leaf_parent_continuation_yield_cap = 16
        let private leafParentContinuationYieldIdentityText (identity: LeafParentContinuationYieldIdentity) =
            FastRuntimeFormat.format "%s|%s|%d|%s|%d|%s|%s|%d|%s" [| box (evalKindToString identity.leafKind); box (frameStatusToString identity.leafStatus); box identity.leafCursor; box (CompilerIdentityKernel.WorkSiteIdOps.text identity.leafSite); box (Option.defaultValue -1 identity.leafNodeId); box (evalKindToString identity.alternateKind); box (frameStatusToString identity.alternateStatus); box (Option.defaultValue -1 identity.alternateNodeId); box (CompilerIdentityKernel.WorkSiteIdOps.text identity.alternateSite) |]
        let private noteLeafParentContinuationYieldLocked (leaf: Frame) (alt: Frame) =
            let identity : LeafParentContinuationYieldIdentity = {
                leafKind = leaf.kind
                leafStatus = leaf.status
                leafCursor = leaf.cursor
                leafSite = leaf.site
                leafNodeId = leaf.semanticCell |> Option.map (fun cell -> cell.nodeId)
                alternateKind = alt.kind
                alternateStatus = alt.status
                alternateNodeId = alt.semanticCell |> Option.map (fun cell -> cell.nodeId)
                alternateSite = alt.site
            }
            let mutable prior = 0
            let next = if leafParentContinuationYieldRepeats.TryGetValue(identity, &prior) then prior + 1 else 1
            leafParentContinuationYieldRepeats.[identity] <- next
            next, leafParentContinuationYieldIdentityText identity

        // MIGRATION: progress-bearing scheduler yields (fingerprint/stale-retarget)
        // can justify a bounded retry trampoline, but only if the selected frontier
        // is preserved across the immediate retry.  This counter is consumed by
        // BuildFile.retry_stop; it is not a semantic proof.
        let mutable private progressYieldCount = 0
        let private noteProgressYieldLocked () =
            progressYieldCount <- progressYieldCount + 1
        let tryConsumeProgressYield () =
            lock gate (fun () ->
                if progressYieldCount > 0 then
                    progressYieldCount <- progressYieldCount - 1
                    true
                else false)
        // MIGRATION: retry_stop must be able to distinguish a hard terminal from a
        // terminal-shaped frontier that still has a cooperative replay tick in flight.
        // This is a liveness hint only; it does not prove or fabricate semantic success.
        let hasProgressYield () =
            lock gate (fun () -> progressYieldCount > 0)
        // MIGRATION: after a concrete root-complete write witness has decided that
        // a stale retarget should not be reinserted, stale progress-yield hints must
        // not keep retry_stop in the same pending=2 finalization loop.
        let drainProgressYield () =
            lock gate (fun () ->
                let n = progressYieldCount
                progressYieldCount <- 0
                n)
        // MIGRATION: replay-driver stack depth for suppressing semantic-cell-attached
        // self-pokes while the driver is already reducing that active typed replay.
        let mutable private replayDriverActiveDepth = 0
        // Queue residency is not execution ownership. Multiple replay-driver callbacks may be
        // active concurrently, but a concrete replay task id has exactly one body owner.
        let private replayTaskExecutionClaims = System.Collections.Generic.HashSet<int64>()
        let replayDriverActiveDepthValue () =
            lock gate (fun () -> replayDriverActiveDepth)

        let mutable private replayDriverStackFenceQueued = false
        let mutable private replayDriverStackFenceQueuedSinceMs = 0L
        let mutable private stackFenceHopacOverrideHotRowOrdinal = 0
        let private nextStackFenceHopacOverrideHotRowOrdinal () =
            lock gate (fun () -> stackFenceHopacOverrideHotRowOrdinal <- stackFenceHopacOverrideHotRowOrdinal + 1; stackFenceHopacOverrideHotRowOrdinal)
        let private shouldEmitStackFenceHopacOverrideHotRow ordinal =
            ordinal > 0 && (ordinal <= 4 || ordinal = 16 || ordinal = 64 || ordinal % 512 = 0)

        let mutable private stackFencePrefetchLedgerAuditHotRowOrdinal = 0
        let private nextStackFencePrefetchLedgerAuditHotRowOrdinal () =
            lock gate (fun () -> stackFencePrefetchLedgerAuditHotRowOrdinal <- stackFencePrefetchLedgerAuditHotRowOrdinal + 1; stackFencePrefetchLedgerAuditHotRowOrdinal)
        let private shouldEmitStackFencePrefetchLedgerAuditHotRow ordinal =
            ordinal > 0 && (ordinal <= 3 || ordinal = 16 || ordinal = 64 || ordinal % 512 = 0)
        // MIGRATION: kind-local frontier slots.
        // MIGRATION proved term replay can now reach semantic_root_complete and store source-key
        // values, but the remaining log alternated term/ty fuses through one canonical frontier,
        // causing kind_local_active_reset and missing_frontier churn.  Keep at most one parked
        // frame per evaluator kind; switching kinds parks the active frame instead of erasing it.
        let private slotSetLocked (frame: Frame) =
            match frame.kind with
            | EvalTerm -> frontierTerm <- Some frame
            | EvalTy -> frontierTy <- Some frame
            | EvalData
            | EvalCodegen
            | EvalDynamicJoin
            | EvalParentResume
            | EvalUnknown _ -> ()

        let private slotGetLocked kind =
            match kind with
            | EvalTerm -> frontierTerm
            | EvalTy -> frontierTy
            | EvalData
            | EvalCodegen
            | EvalDynamicJoin
            | EvalParentResume
            | EvalUnknown _ -> None

        let private saveFrontierLocked () =
            match frontier with
            | Some frame -> slotSetLocked frame
            | None -> ()

        let private selectKindLockedId kind =
            match kind with
            | EvalTerm
            | EvalTy ->
                match frontier with
                | Some frame when frame.kind = kind ->
                    slotSetLocked frame
                    true
                | _ ->
                    saveFrontierLocked ()
                    match slotGetLocked kind with
                    | Some frame ->
                        frontier <- Some frame
                        true
                    | None ->
                        false
            | EvalData
            | EvalCodegen
            | EvalDynamicJoin
            | EvalParentResume
            | EvalUnknown _ -> false

        let private selectKindLocked (kind: EvalKind) =
            selectKindLockedId kind

        type ReplayFrontierKindId =
            | ReplayFrontierTerm
            | ReplayFrontierTy
            | ReplayFrontierUnknown

        let private replayFrontierKindText = function
            | ReplayFrontierTerm -> "term"
            | ReplayFrontierTy -> "ty"
            | ReplayFrontierUnknown -> "unknown"


        let rec private replayFrontierKindOfTickEvent = function
            | ReplayTickEventTermEntry
            | ReplayTickEventTermCycle
            | ReplayTickEventTermReentryPrefetch
            | ReplayTickEventTermEntryGlobalFuse -> ReplayFrontierTerm
            | ReplayTickEventTyEntry
            | ReplayTickEventTyCycle
            | ReplayTickEventTyReentryPrefetch
            | ReplayTickEventTyEntryGlobalFuse -> ReplayFrontierTy
            | ReplayTickEventDerived(parentId, _) -> replayFrontierKindOfTickEvent parentId
            | ReplayTickEventCooperativeReplayHandoff
            | ReplayTickEventCacheWriteParentHandoffWakeCallback
            | ReplayTickEventBigstackQueueOnlyLiveReplay
            | ReplayTickEventBigstackJoinWaitLiveReplayDrain
            | ReplayTickEventBigstackJoinWait
            | ReplayTickEventJoinWait
            | ReplayTickEventJpPromiseTerminalResumption
            | ReplayTickEventJpPromiseResolvedResumption
            | ReplayTickEventJpPromiseFailedResumption
            | ReplayTickEventJpPromiseCancelledResumption
            | ReplayTickEventJpDeclaredBodyCheckpoint
            | ReplayTickEventRetryStop
            | ReplayTickEventRetryStopDrain
            | ReplayTickEventJpWaitCycleDrain
            | ReplayTickEventHeartbeatNoWorkGateBusy
            | ReplayTickEventHeartbeatNoWorkStallDirectBurst
            | ReplayTickEventBigstackNoRootBudgetTerminalBypassCpuIdleLiveGraph
            | ReplayTickEventBigstackNoRootBudgetTerminalRepeatDeferred
            | ReplayTickEventBigstackJoinWaitQueueSurgeFallback
            | ReplayTickEventBigstackJoinWaitQueueFallback
            | ReplayTickEventForcedDrain _
            | ReplayTickEventUnknown _ -> ReplayFrontierUnknown

        let private replayFrontierKindOfDriver = function
            | TermReplayDriver -> ReplayFrontierTerm
            | TyReplayDriver -> ReplayFrontierTy
            | _ -> ReplayFrontierUnknown

        let parkActiveAndSelectKind (requestedKind: EvalKind) =
            lock gate (fun () ->
                let restored = selectKindLocked requestedKind
                if not restored then frontier <- None
                replayScheduledKey <- None
                replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                replayDriverStackFenceQueued <- false
                activeRun <- false
                restored)

        let parkActiveAndSelectKindKeepingReplay (event: string) (requestedKind: EvalKind) =
            // MIGRATION: keep this helper self-contained.  It sits before
            // pendingCount in lexical order, so it cannot reference pendingCount
            // or the later local `esc` alias.  Recompute the tiny pending summary
            // from the three frontier slots while preserving replayQueue.
            let restored, qd, pendingNow =
                lock gate (fun () ->
                    let restored = selectKindLocked requestedKind
                    if not restored then frontier <- None
                    replayDriverStackFenceQueued <- false
                    activeRun <- false
                    let mutable pendingNow = 0
                    let seen = System.Collections.Generic.HashSet<ReplayFramePendingIdentity>()
                    let add (opt: Frame option) =
                        match opt with
                        | Some frame ->
                            let identity : ReplayFramePendingIdentity = {
                                kind = frame.kind
                                key = frame.key
                                site = frame.site
                            }
                            if seen.Add identity then pendingNow <- pendingNow + 1
                        | None -> ()
                    add frontier
                    add frontierTerm
                    add frontierTy
                    restored, replayQueue.Length, pendingNow)
            DiagJson.emit (
                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_global_fuse_deferred_replay_queue_preserved\",\"event\":%s,\"requested_kind\":%s,\"queue_depth\":%d,\"pending\":%d,\"restored\":%b,\"single_flight\":1,\"next\":\"await_preserved_replay_tick\"}" [| box (DiagJson.esc event); box (DiagJson.esc (evalKindToString requestedKind)); box qd; box pendingNow; box restored |])
            restored

        // MIGRATION: the root witness is durable for one explicit build epoch. Volatile
        // replay resets may replace the current frontier, but they cannot erase a canonical
        // root receipt. The writer may consume this proof only after pending, queue and active
        // replay reach zero; beginBuildEpoch clears it before the next top-level build.
        let mutable private replayRootCompleteWitnessUtc = System.DateTime.MinValue
        let mutable private replayRootFirstCompleteWitnessUtc = System.DateTime.MinValue
        let mutable private replayRootCompleteWitnessSummary = ""
        let mutable private replayRootCompleteWitnessIdentity = ""
        // MIGRATION: this admission authority is build-epoch monotone. EvalWorklist.reset
        // may clear volatile replay state between attempts, but it must not reopen parent
        // cache handoffs after a root witness has closed them for the current build.
        type private ParentCacheHandoffBuildAdmission =
            | ParentCacheHandoffOpenForBuild
            | ParentCacheHandoffClosedAfterRootWitness

        type private RootWitnessResidualTailDisposition =
            | RootWitnessResidualTailKeepDraining
            | RootWitnessResidualQueueTailQuarantine
            | RootWitnessResidualPendingFrontierTailQuarantine

        let private rootWitnessResidualTailDispositionText = function
            | RootWitnessResidualTailKeepDraining -> "keep_draining"
            | RootWitnessResidualQueueTailQuarantine -> "quarantine_stale_post_root_queue_tail"
            | RootWitnessResidualPendingFrontierTailQuarantine -> "quarantine_stale_post_root_pending_frontier_tail"

        let mutable private parentCacheHandoffBuildAdmission = ParentCacheHandoffOpenForBuild
        let private replayRootCompleteWitnessWindowMs = 120000.0
        let private replayRootCompleteLivenessWindowMs = 5000.0
        let private replayRootResidualTailQuarantineAgeMs = 30000.0
        let private replayRootResidualTailMaxQueueDepth = 8

        // MIGRATION: stable root-complete retry ledger.
        // MIGRATION proved preserving the completed frontier is not enough: spiral.spi:2671
        // can keep proving the same cursor=trace_len root-complete cell for hundreds of
        // attempts, producing megabytes of replay logs without new information.  Track the
        // root-complete frontier fingerprint and let BuildFile stop after a small stable
        // repeat budget with a compact typed diagnostic.
        let mutable private stableRootCompleteKey : ReplayFrontierFingerprintIdentity option = None
        let mutable private stableRootCompleteCount = 0

        // MIGRATION: do not spend the bounded root-complete yield budget on the
        // exact same blocked-root -> selected-frontier pair forever.  The MIGRATION
        // runtime log proved the cap accounting works, but also proved that selecting
        // the same semantic_dynamic_join_apply_blocked term frontier 31+ times cycles
        // back to the same ty semantic_root_complete proof.
        let mutable private stableRootSelectedKey : StableRootSelectedIdentity option = None
        let mutable private stableRootSelectedCount = 0
        let private stable_root_selected_frontier_repeat_cap = 8

        // MIGRATION: a selected-frontier repeat is terminal only after the real
        // typed stepper has been re-enqueued as a continuation envelope.  Runtime
        // 583 proved MIGRATION ranks and aborts the repeat correctly, but also
        // showed the repeated EApply at core/listm.spi:27 was parked as a bare
        // semantic_step_partial frame with no replay queue.  Give that exact cell
        // a small, bounded replay escape before preserving the precise terminal.
        let private selectedFrontierStepperReplayAttempts = System.Collections.Generic.Dictionary<SelectedFrontierStepperReplayIdentity,int>()
        let private selected_frontier_stepper_replay_cap = 2
        let private selected_frontier_stepper_rearm_cap = 2
        // Captured composite frontiers can arrive after a successful root-complete handoff:
        // the log shows an existing term/ESeq semantic cell, not a missing value. Give that
        // captured cell a bounded replay envelope before terminalizing selected-frontier repeat.
        let private selected_frontier_captured_cell_replay_cap = 4

        let private esc (s: string) =
            if Object.ReferenceEquals(s,null) then "null" else
                let s =
                    s.Replace("\\","\\\\")
                     .Replace("\"","\\\"")
                     .Replace("\r","\\r")
                     .Replace("\n","\\n")
                     .Replace("\t","\\t")
                "\"" + s + "\""

        // MIGRATION: historical runtime proved a diagnostic reason could append the same
        // app-root finalization tag hundreds of times and create multi-hundred-KB
        // JSON lines. Keep the evidence, but make reason strings idempotent and
        // bounded at the diagnostic boundary; no replay value or terminal rank changes.
        let private compactReasonTag (tag: string) (reason: string) =
            if System.Object.ReferenceEquals(reason, null) || reason = "" then ""
            else
                let parts = reason.Split([|':'|], System.StringSplitOptions.RemoveEmptyEntries)
                let tagCount =
                    parts
                    |> Array.filter (fun part -> part = tag)
                    |> Array.length
                if tagCount > 0 then
                    let prefixParts =
                        parts
                        |> Array.takeWhile (fun part -> part <> tag)
                        |> Array.truncate 4
                    let prefix =
                        if prefixParts.Length = 0 then "reason"
                        else System.String.Join(":", prefixParts)
                    if tagCount = 1 then sprintf "%s:%s" prefix tag
                    else FastRuntimeFormat.format "%s:%s#repeat=%d" [| box prefix; box tag; box tagCount |]
                else reason

        type BoundedReasonText = private BoundedReasonText of string

        module BoundedReasonTextOps =
            let create value = BoundedReasonText (if isNull value then "" else value)
            let text (BoundedReasonText value) = value

        let private compactFrameReason reasonText =
            let reason = BoundedReasonTextOps.text reasonText
            let tag = "app_root_base16_live_replay_root_witness_finalization_deferred"
            let r = compactReasonTag tag reason
            let compacted =
                if System.Object.ReferenceEquals(r, null) then ""
                elif r.Length <= 768 then r
                else r.Substring(0, 768) + sprintf "…[+%d chars]" (r.Length - 768)
            BoundedReasonTextOps.create compacted

        type BoundedReasonAppendDispositionId =
            | BoundedReasonTagAlreadyPresent
            | BoundedReasonEmptyBase
            | BoundedReasonAppendTag

        let private boundedReasonContainsTag (text:string) (tag:string) =
            if System.String.IsNullOrEmpty text || System.String.IsNullOrEmpty tag || tag.Length > text.Length then false
            else
                let mutable offset = 0
                let lastOffset = text.Length - tag.Length
                let mutable found = false
                while not found && offset <= lastOffset do
                    if System.String.Compare(text, offset, tag, 0, tag.Length, System.StringComparison.Ordinal) = 0 then
                        found <- true
                    else
                        offset <- offset + 1
                found

        type BoundedReasonTagId =
            | BoundedReasonAppRootBase16LiveReplayRootWitnessFinalizationDeferred

        let private boundedReasonTagText = function
            | BoundedReasonAppRootBase16LiveReplayRootWitnessFinalizationDeferred -> "app_root_base16_live_replay_root_witness_finalization_deferred"

        let private boundedReasonAppendDispositionFor reasonText tagId =
            let reason = BoundedReasonTextOps.text reasonText
            let tag = boundedReasonTagText tagId
            if boundedReasonContainsTag reason tag then BoundedReasonTagAlreadyPresent
            elif System.String.IsNullOrEmpty reason then BoundedReasonEmptyBase
            else BoundedReasonAppendTag

        let private boundedReasonAppend reasonText tagId =
            let r = compactFrameReason reasonText
            let rText = BoundedReasonTextOps.text r
            let tag = boundedReasonTagText tagId
            match boundedReasonAppendDispositionFor r tagId with
            | BoundedReasonTagAlreadyPresent -> compactFrameReason r
            | BoundedReasonEmptyBase -> BoundedReasonTextOps.create tag
            | BoundedReasonAppendTag -> BoundedReasonTextOps.create (rText + ":" + tag) |> compactFrameReason

        type LogCompletenessPolicy =
            | FullFidelityJsonl
            | TruncatedPreview of int

        let private activeLogCompletenessPolicy = FullFidelityJsonl

        let private logCompletenessPolicyText policy =
            match policy with
            | FullFidelityJsonl -> "full_fidelity_jsonl"
            | TruncatedPreview n -> sprintf "truncated_preview_%d" n

        let terminalContractRankId (statusId: SemanticStatusId) =
            match semanticTerminalContract statusId with
            | Some contract -> contract.rank
            | None -> 0

        let terminalContractRank (status: FrameStatusId) =
            status |> frameStatusSemanticStatusId |> terminalContractRankId

        let isTerminalContractStatusId (statusId: SemanticStatusId) =
            match semanticTerminalContract statusId with
            | Some _ -> true
            | None -> false

        let terminalContractNextReplayId (statusId: SemanticStatusId) =
            match semanticTerminalContract statusId with
            | Some contract -> contract.next
            | None -> replayCommitNextOther "native_hopac_real_stepper_direct_required"

        let terminalContractNextId (statusId: SemanticStatusId) =
            statusId |> terminalContractNextReplayId |> replayCommitNextIdText

        let terminalContractNext (status: FrameStatusId) =
            status |> frameStatusSemanticStatusId |> terminalContractNextId

        let isParentReplayCycleBreakPoisonedStatus (statusId: SemanticStatusId) =
            match statusId with
            | SemanticParentReplayCycleBreakPoisoned -> true
            | _ -> false

        let private frameStatusId (frame: Frame) = frame.status
        let frameEvalKindId (frame: Frame) = frame.kind
        let private cellEvalKindId (cell: ReplayCell) = replayCellEvalKindId cell
        let private cellFrameStatusId (cell: ReplayCell) = frameStatusOfReplayCellStatusId cell.status
        let frameStatusIs statusId (frame: Frame) = frameStatusId frame = statusId
        let private cellFrameStatusIs statusId (cell: ReplayCell) = cellFrameStatusId cell = statusId
        let frameSemanticStatusId (frame: Frame) = frameStatusSemanticStatusId frame.status
        let cellSemanticStatusId (cell: ReplayCell) = replayCellSemanticStatusId cell.status
        let frameSemanticStatusIs statusId (frame: Frame) = frameSemanticStatusId frame = statusId
        let private cellSemanticStatusIs statusId (cell: ReplayCell) = cellSemanticStatusId cell = statusId
        let private frameOrCellSemanticStatusIs statusId (frame: Frame) =
            frameSemanticStatusIs statusId frame
            || (match frame.semanticCell with
                | Some cell -> cellSemanticStatusIs statusId cell
                | None -> false)
        let private frameOrCellIsRootComplete frame = frameOrCellSemanticStatusIs SemanticRootComplete frame

        let private pendingCountUnlocked () =
            let mutable n = 0
            let seen = System.Collections.Generic.HashSet<ReplayFramePendingIdentity>()
            let add (opt: Frame option) =
                match opt with
                | Some frame ->
                    let identity : ReplayFramePendingIdentity = {
                        kind = frameEvalKindId frame
                        key = frame.key
                        site = frame.site
                    }
                    if seen.Add identity then n <- n + 1
                | None -> ()
            add frontier
            add frontierTerm
            add frontierTy
            n

        // MIGRATION: keep the replay/root liveness DU before all consumers.
        // MIGRATION proved the direction was right but placed the helper after
        // pinTerminalContractLocked, which F# rejects because local lets are lexical.
        // The snapshot is intentionally built from existing worklist facts only; it
        // does not promote a terminal, fabricate replay completion, or mint BuildOk.
        type ReplayDrainState =
            | ReplayDrainQuiescent
            | ReplayDrainPendingOnly
            | ReplayDrainQueueAlive
            | ReplayDrainActiveOnly
            | ReplayDrainRootWitnessQueueAlive
            | ReplayDrainWriteWitnessQueueAlive

        type TerminalPinLivenessGate =
            | TerminalPinNoLiveReplay
            | TerminalPinLiveReplay of ReplayDrainState
            | TerminalPinWitnessQueue of ReplayDrainState
            | TerminalPinProgressYield of ReplayDrainState

        let private replayDrainStateLocked () =
            let pending = pendingCountUnlocked()
            let qd = replayQueue.Length
            let active = replayDriverActiveDepth
            let rootWitness =
                match frontier with
                | Some frame when frameOrCellIsRootComplete frame -> true
                | Some _ -> false
                | None -> false
            let writeWitness = replayRootCompleteWitnessUtc <> System.DateTime.MinValue
            if pending <= 0 && qd <= 0 && active <= 0 then ReplayDrainQuiescent
            elif qd > 0 && rootWitness then ReplayDrainRootWitnessQueueAlive
            elif qd > 0 && writeWitness then ReplayDrainWriteWitnessQueueAlive
            elif qd > 0 then ReplayDrainQueueAlive
            elif active > 0 then ReplayDrainActiveOnly
            else ReplayDrainPendingOnly

        let private replayDrainStateToString state =
            match state with
            | ReplayDrainQuiescent -> "quiescent"
            | ReplayDrainPendingOnly -> "pending_only"
            | ReplayDrainQueueAlive -> "queue_alive"
            | ReplayDrainActiveOnly -> "active_only"
            | ReplayDrainRootWitnessQueueAlive -> "root_witness_queue_alive"
            | ReplayDrainWriteWitnessQueueAlive -> "write_witness_queue_alive"

        let private replayDrainStateHasQueue state =
            match state with
            | ReplayDrainQueueAlive
            | ReplayDrainRootWitnessQueueAlive
            | ReplayDrainWriteWitnessQueueAlive -> true
            | _ -> false

        let private replayDrainStateHasLiveReplay state =
            match state with
            | ReplayDrainQueueAlive
            | ReplayDrainRootWitnessQueueAlive
            | ReplayDrainWriteWitnessQueueAlive
            | ReplayDrainActiveOnly -> true
            | _ -> false

        let private replayDrainStateHasWitnessQueue state =
            match state with
            | ReplayDrainRootWitnessQueueAlive
            | ReplayDrainWriteWitnessQueueAlive -> true
            | _ -> false

        let private terminalPinLivenessGateOfState drainState progressYieldPending =
            if progressYieldPending then TerminalPinProgressYield drainState
            elif replayDrainStateHasWitnessQueue drainState then TerminalPinWitnessQueue drainState
            elif replayDrainStateHasLiveReplay drainState then TerminalPinLiveReplay drainState
            else TerminalPinNoLiveReplay

        let private terminalPinLivenessGateHasLiveReplay gate =
            match gate with
            | TerminalPinNoLiveReplay -> false
            | TerminalPinLiveReplay _
            | TerminalPinWitnessQueue _
            | TerminalPinProgressYield _ -> true

        let private terminalPinLivenessGateHasWitnessQueue gate =
            match gate with
            | TerminalPinWitnessQueue _ -> true
            | _ -> false

        let private terminalPinLivenessGateToString gate =
            match gate with
            | TerminalPinNoLiveReplay -> "no_live_replay"
            | TerminalPinLiveReplay state -> sprintf "live_replay:%s" (replayDrainStateToString state)
            | TerminalPinWitnessQueue state -> sprintf "witness_queue:%s" (replayDrainStateToString state)
            | TerminalPinProgressYield state -> sprintf "progress_yield:%s" (replayDrainStateToString state)

        let private liveReplayTerminalSuppressedLocked (statusId: SemanticStatusId) =
            let drainState = replayDrainStateLocked()
            let activeReplay = replayDrainStateHasLiveReplay drainState
            match liveReplayTerminalPolicyOfSemanticStatusId statusId with
            | DeferTerminalWhileLiveReplay ->
                pendingCountUnlocked() > 0 && activeReplay
            | SurfaceTerminalDuringLiveReplay
            | TerminalNotLiveReplayPolicy -> false

        let liveReplayTerminalSuppressedId statusId =
            lock gate (fun () -> liveReplayTerminalSuppressedLocked statusId)

        let replayDrainStateSnapshot () =
            lock gate (fun () -> replayDrainStateLocked())

        let replayDrainStateText state = replayDrainStateToString state
        let replayDrainStateHasWitnessQueuePublic state = replayDrainStateHasWitnessQueue state
        let replayDrainStateHasLiveReplayPublic state = replayDrainStateHasLiveReplay state
        let replayDrainStateHasQueuePublic state = replayDrainStateHasQueue state

        // MIGRATION: replay-driver exceptions are no longer pinned by the low-level
        // exception kind alone.  Historical runtime showed a generic NullReferenceException
        // on an EPairTest replay cell while pending/queued replay was still alive; the
        // old policy turned that first live retry into a rank-88 terminal.  Keep the
        // decision closed and generic: live drain can defer, repeated null guards still
        // pin once their bounded repeat cap fires, and no BuildOk/root proof is minted.
        type ReplayDriverExceptionTerminalDecisionId =
            | ReplayDriverExceptionPinNow
            | ReplayDriverExceptionDeferLiveReplayDrain
            | ReplayDriverExceptionNullGuardLiveReplayRetry
            | ReplayDriverExceptionPreserveRootWitnessDrain

        let private replayDriverExceptionTerminalDecisionText = function
            | ReplayDriverExceptionPinNow -> "pin_now"
            | ReplayDriverExceptionDeferLiveReplayDrain -> "defer_live_replay_drain"
            | ReplayDriverExceptionNullGuardLiveReplayRetry -> "null_guard_live_replay_retry"
            | ReplayDriverExceptionPreserveRootWitnessDrain -> "preserve_root_witness_drain"

        // Post-root replay exceptions carry the concrete writer-tail
        // occupancy.  This is intentionally separate from the legacy pin policy:
        // after RootComplete, a null callback is a WriterCapability failure, not
        // an owner-debt retry.  The snapshot payload acts like a small existential
        // witness: the decision cannot exist without the Q/A/P state it governs.
        type PostRootReplayExceptionTailSnapshot =
            { queueDepth : int
              activeDepth : int
              pending : int }

        type PostRootReplayExceptionTailAuthorityId =
            | PostRootReplayExceptionTailNotOwned
            | PostRootReplayExceptionTailContinueBoundedDrain of PostRootReplayExceptionTailSnapshot
            | PostRootReplayExceptionTailBindTypedFailure of PostRootReplayExceptionTailSnapshot

        let private postRootReplayExceptionTailAuthorityText = function
            | PostRootReplayExceptionTailNotOwned -> "PostRootReplayExceptionTail(NotOwned)"
            | PostRootReplayExceptionTailContinueBoundedDrain snapshot ->
                FastRuntimeFormat.format "PostRootReplayExceptionTail(ContinueBoundedDrain|qap=%d/%d/%d)" [| box snapshot.queueDepth; box snapshot.activeDepth; box snapshot.pending |]
            | PostRootReplayExceptionTailBindTypedFailure snapshot ->
                FastRuntimeFormat.format "PostRootReplayExceptionTail(BindTypedFailure|qap=%d/%d/%d)" [| box snapshot.queueDepth; box snapshot.activeDepth; box snapshot.pending |]

        let private postRootReplayExceptionTailAuthorityFor postRootLeaseActive exceptionKind isNullException nullGuardBlocked queueDepth activeDepth pending =
            let snapshot : PostRootReplayExceptionTailSnapshot = { queueDepth = queueDepth; activeDepth = activeDepth; pending = pending }
            if not postRootLeaseActive || not isNullException then PostRootReplayExceptionTailNotOwned
            else
                match exceptionKind with
                | ReplayExceptionLetSuccessApplyContinuationRootWitnessDeferred
                | ReplayExceptionApplyContinuationRootWitnessDeferred
                | ReplayExceptionApplyContinuationRootWitnessRetryDeferred
                | ReplayExceptionOpContinuationRootWitnessDeferred ->
                    // Once root is resolved, retrying the same null continuation
                    // cannot create a writer. Bind the typed failure immediately;
                    // repeat caps remain diagnostics, not authority.
                    PostRootReplayExceptionTailBindTypedFailure snapshot
                | _ when nullGuardBlocked -> PostRootReplayExceptionTailBindTypedFailure snapshot
                | _ -> PostRootReplayExceptionTailContinueBoundedDrain snapshot

        let private replayDriverExceptionTerminalDecisionFor pinPolicy drainState isNullException nullGuardBlocked progressYieldPending pending postRootLeaseActive =
            let liveDrain =
                pending > 0
                || progressYieldPending
                || replayDrainStateHasLiveReplayPublic drainState
            match pinPolicy with
            | ReplayExceptionPreserveRootWitness when postRootLeaseActive && isNullException -> ReplayDriverExceptionPinNow
            | ReplayExceptionDeferLiveReplay when postRootLeaseActive && isNullException -> ReplayDriverExceptionPinNow
            | ReplayExceptionPreserveRootWitness when liveDrain -> ReplayDriverExceptionPreserveRootWitnessDrain
            | ReplayExceptionDeferLiveReplay when liveDrain -> ReplayDriverExceptionDeferLiveReplayDrain
            | ReplayExceptionPinTerminal when isNullException && liveDrain && not nullGuardBlocked -> ReplayDriverExceptionNullGuardLiveReplayRetry
            | _ -> ReplayDriverExceptionPinNow

        type TerminalPoisonCascadeDecisionId =
            | TerminalPoisonCascadeNone
            | TerminalPoisonCascadeGlobalFuse
            | TerminalPoisonCascadeParentReplay
            | TerminalPoisonCascadeReplayDriverException
            | TerminalPoisonCascadeOpImpl
            | TerminalPoisonCascadeDynamicJoin
            | TerminalPoisonCascadeRank80KnownTerminal

        let terminalPoisonCascadeDecisionText = function
            | TerminalPoisonCascadeNone -> "none"
            | TerminalPoisonCascadeGlobalFuse -> "global_fuse"
            | TerminalPoisonCascadeParentReplay -> "parent_replay"
            | TerminalPoisonCascadeReplayDriverException -> "replay_driver_exception"
            | TerminalPoisonCascadeOpImpl -> "op_impl"
            | TerminalPoisonCascadeDynamicJoin -> "dynamic_join"
            | TerminalPoisonCascadeRank80KnownTerminal -> "rank80_known_terminal"

        // MIGRATION: keep the cascade live-tail deferral scheduler typed as well.
        // The branch that consumes this DU lives before the generic replay-drain helpers
        // are declared, so it must not call those later let-bound helpers directly.
        type TerminalPoisonCascadeLiveTailDeferDecisionId =
            | TerminalPoisonCascadeLiveTailNoDefer
            | TerminalPoisonCascadeLiveTailScheduleLocalDrain
            | TerminalPoisonCascadeLiveTailObserveActiveDrain

        let terminalPoisonCascadeLiveTailDeferDecisionText = function
            | TerminalPoisonCascadeLiveTailNoDefer -> "no_defer"
            | TerminalPoisonCascadeLiveTailScheduleLocalDrain -> "schedule_local_drain"
            | TerminalPoisonCascadeLiveTailObserveActiveDrain -> "observe_active_drain"

        let terminalPoisonCascadeLiveTailDeferDecisionFor pending queueDepth activeDepth progressYield =
            if pending > 0 || queueDepth > 0 then TerminalPoisonCascadeLiveTailScheduleLocalDrain
            elif activeDepth > 0 || progressYield > 0 then TerminalPoisonCascadeLiveTailObserveActiveDrain
            else TerminalPoisonCascadeLiveTailNoDefer

        let terminalPoisonCascadeDecisionFor rank pending queueDepth activeDepth progressYield (statusId: SemanticStatusId) forceParentReplayCascade =
            // MIGRATION: dynamic-join poison is the concrete 1233/1234 terminal, so
            // do not let a rank-table mismatch turn it into another passive pin.
            // If replay is or was live, dynamic-join apply blocked is poison even
            // before the generic rank>=80 gate.  Other known terminals keep the
            // rank gate.
            let liveOrRecentlyLive = pending > 0 || queueDepth > 0 || activeDepth > 0 || progressYield > 0
            let runnableQueueOrActive = queueDepth > 0 || activeDepth > 0
            if not liveOrRecentlyLive then TerminalPoisonCascadeNone
            else
                match statusId with
                | SemanticDynamicJoinApplyBlocked -> TerminalPoisonCascadeDynamicJoin
                | _ when rank < 80 -> TerminalPoisonCascadeNone
                | SemanticGlobalFuseParentContinuationCycleBlocked -> TerminalPoisonCascadeGlobalFuse
                | SemanticMissingAfterPrefetchBlocked when pending = 0 && runnableQueueOrActive && progressYield > 0 ->
                    // MIGRATION: rank-91 missing-after-prefetch is a drain obligation while the live tail is still running.
                    // A missing prefetch can be fulfilled by the active queue, so do not recursively poison slots before probation.
                    TerminalPoisonCascadeNone
                | SemanticParentReplayStatusPreservedRepeatBlocked
                | SemanticParentReplayCycleBreakPoisoned when runnableQueueOrActive && forceParentReplayCascade ->
                    // MIGRATION: only proven macro authority may cascade a live parent-replay frontier.
                    // Stale pending witnesses without hard-cap receipts must defer instead of clearing q/a/p.
                    TerminalPoisonCascadeParentReplay
                | SemanticParentReplayStatusPreservedRepeatBlocked
                | SemanticParentReplayCycleBreakPoisoned when pending > 0 && liveOrRecentlyLive ->
                    // MIGRATION: pending-positive parent replay poison is not cascade authority while q/a/progress exists.
                    // The 1418 trace.spi:121 frontier had p=2 and live replay evidence but no hard-cap receipt.
                    TerminalPoisonCascadeNone
                | SemanticParentReplayStatusPreservedRepeatBlocked
                | SemanticParentReplayCycleBreakPoisoned when pending = 0 && runnableQueueOrActive ->
                    // MIGRATION: do not let a fresh parent-replay terminal cascade murder a live queue.
                    // MIGRATION narrows the exception above to proven obligation-cap poison only.
                    TerminalPoisonCascadeNone
                | SemanticParentReplayStatusPreservedRepeatBlocked
                | SemanticParentReplayCycleBreakPoisoned -> TerminalPoisonCascadeParentReplay
                | SemanticReplayDriverExceptionBlocked -> TerminalPoisonCascadeReplayDriverException
                | SemanticOpImplRequiredBlocked -> TerminalPoisonCascadeOpImpl
                | SemanticOther _ when isTerminalContractStatusId statusId -> TerminalPoisonCascadeRank80KnownTerminal
                | _ when isTerminalContractStatusId statusId -> TerminalPoisonCascadeRank80KnownTerminal
                | _ -> TerminalPoisonCascadeNone

        // MIGRATION: the 1337 log proved that rank-83 parent replay poison was still
        // being suppressed while pending=0 and writer witness=none.  Model the
        // suppression decision explicitly so "progress_yield" can no longer smuggle
        // a pending-zero tail back into the live replay loop.
        type ParentReplayPoisonLivenessId =
            | ParentReplayPoisonNoLiveTail
            | ParentReplayPoisonLiveQueueOrDriver
            | ParentReplayPoisonPendingWitness
            | ParentReplayPoisonRecentProgressOnly

        let private parentReplayPoisonLivenessText = function
            | ParentReplayPoisonNoLiveTail -> "no_live_tail"
            | ParentReplayPoisonLiveQueueOrDriver -> "live_queue_or_driver"
            | ParentReplayPoisonPendingWitness -> "pending_witness"
            | ParentReplayPoisonRecentProgressOnly -> "recent_progress_only"

        let private parentReplayPoisonLivenessFor terminalPinHasLiveReplay pendingForTerminalPin progressYieldCount =
            if pendingForTerminalPin > 0 then ParentReplayPoisonPendingWitness
            elif terminalPinHasLiveReplay then ParentReplayPoisonLiveQueueOrDriver
            elif progressYieldCount > 0 then ParentReplayPoisonRecentProgressOnly
            else ParentReplayPoisonNoLiveTail

        // MIGRATION: reason classification is carried by FramePayloadId signals.
        // The pin policy consumes a typed probe; arbitrary reasons remain opaque IDs
        // and are rendered only for diagnostics.
        [<NoComparison>]
        type ParentReplayPoisonReasonProbeId =
            | ParentReplayPoisonReasonCrossKindActiveReplayDriver
            | ParentReplayPoisonReasonStatusPreservedRepeat
            | ParentReplayPoisonReasonOther of CompilerKernelV2.OperationalReasonId

        let private parentReplayPoisonReasonProbeText = function
            | ParentReplayPoisonReasonCrossKindActiveReplayDriver -> "cross_kind_active_replay_driver"
            | ParentReplayPoisonReasonStatusPreservedRepeat -> "parent_replay_status_preserved_repeat"
            | ParentReplayPoisonReasonOther reasonId ->
                let text = CompilerKernelV2.OperationalReasonIdOps.text reasonId
                if System.String.IsNullOrWhiteSpace text then "none" else text

        let private parentReplayPoisonReasonProbeIsCrossKindActive = function
            | ParentReplayPoisonReasonCrossKindActiveReplayDriver -> true
            | ParentReplayPoisonReasonStatusPreservedRepeat
            | ParentReplayPoisonReasonOther _ -> false

        let private parentReplayPoisonReasonProbeIsStatusPreservedRepeat = function
            | ParentReplayPoisonReasonStatusPreservedRepeat -> true
            | ParentReplayPoisonReasonCrossKindActiveReplayDriver
            | ParentReplayPoisonReasonOther _ -> false

        // MIGRATION: op replay exception classification is carried structurally by
        // FramePayloadId; arbitrary OperationalReasonId values stay opaque until
        // diagnostic rendering.
        [<NoComparison>]
        type OpReplayDriverExceptionReasonId =
            | OpReplayDriverExceptionNull
            | OpReplayDriverExceptionOther of CompilerKernelV2.OperationalReasonId

        let private opReplayDriverExceptionReasonText = function
            | OpReplayDriverExceptionNull -> "op_replay_driver_null"
            | OpReplayDriverExceptionOther reasonId ->
                let text = CompilerKernelV2.OperationalReasonIdOps.text reasonId
                if System.String.IsNullOrWhiteSpace text then "none" else text

        let private opReplayDriverExceptionReasonIsNull = function
            | OpReplayDriverExceptionNull -> true
            | OpReplayDriverExceptionOther _ -> false

        type ParentReplayPoisonPinSuppressionDecisionId =
            | ParentReplayPoisonPinSurface
            | ParentReplayPoisonPinSuppressWithPendingWitness
            | ParentReplayPoisonPinDeferLiveQueuePendingZero
            | ParentReplayPoisonPinHardSurfacePendingZero
            | ParentReplayPoisonPinDeferFreshRootLiveTail
            | ParentReplayPoisonPinDeferHardObligationFreshPendingTail
            | ParentReplayPoisonPinDeferHardObligationStalePendingLiveTail
            | ParentReplayPoisonPinDeferJpStallPendingActiveTail
            | ParentReplayPoisonPinDeferCycleBreakLiveTailOverride
            | ParentReplayPoisonPinForceSurfaceObligationCap
            | ParentReplayPoisonPinForceSurfaceStalePendingWitness
            | ParentReplayPoisonPinForceSurfaceHotPendingWitness

        let private parentReplayPoisonPinSuppressionDecisionText = function
            | ParentReplayPoisonPinSurface -> "surface"
            | ParentReplayPoisonPinSuppressWithPendingWitness -> "suppress_with_pending_witness"
            | ParentReplayPoisonPinDeferLiveQueuePendingZero -> "defer_live_queue_pending_zero"
            | ParentReplayPoisonPinHardSurfacePendingZero -> "hard_surface_pending_zero"
            | ParentReplayPoisonPinDeferFreshRootLiveTail -> "defer_fresh_root_live_tail"
            | ParentReplayPoisonPinDeferHardObligationFreshPendingTail -> "defer_hard_obligation_fresh_pending_tail"
            | ParentReplayPoisonPinDeferHardObligationStalePendingLiveTail -> "defer_hard_obligation_stale_pending_live_tail"
            | ParentReplayPoisonPinDeferJpStallPendingActiveTail -> "defer_jp_stall_pending_active_tail"
            | ParentReplayPoisonPinDeferCycleBreakLiveTailOverride -> "defer_cycle_break_poison_live_tail_override"
            | ParentReplayPoisonPinForceSurfaceObligationCap -> "require_hard_obligation_cap_terminal"
            | ParentReplayPoisonPinForceSurfaceStalePendingWitness -> "force_surface_stale_pending_witness"
            | ParentReplayPoisonPinForceSurfaceHotPendingWitness -> "force_surface_hot_pending_witness"

        let private parentReplayPoisonPinSuppressionDecisionFor isParentReplayPoison liveness replayRootWriteWitnessFreshForPin capBreachForceSurface stalePendingWitnessForceSurface hotPendingWitnessForceSurface freshPendingTailHardObligationDefer stalePendingTailHardObligationDefer jpStallPendingActiveTailDefer cycleBreakPoisonLiveTailOverride =
            if not isParentReplayPoison then ParentReplayPoisonPinSurface
            elif cycleBreakPoisonLiveTailOverride then ParentReplayPoisonPinDeferCycleBreakLiveTailOverride
            elif hotPendingWitnessForceSurface && not jpStallPendingActiveTailDefer then ParentReplayPoisonPinForceSurfaceHotPendingWitness
            elif jpStallPendingActiveTailDefer then ParentReplayPoisonPinDeferJpStallPendingActiveTail
            elif capBreachForceSurface && freshPendingTailHardObligationDefer then ParentReplayPoisonPinDeferHardObligationFreshPendingTail
            elif capBreachForceSurface && stalePendingTailHardObligationDefer then ParentReplayPoisonPinDeferHardObligationStalePendingLiveTail
            elif capBreachForceSurface then ParentReplayPoisonPinForceSurfaceObligationCap
            elif stalePendingWitnessForceSurface then ParentReplayPoisonPinForceSurfaceStalePendingWitness
            elif replayRootWriteWitnessFreshForPin then
                match liveness with
                | ParentReplayPoisonLiveQueueOrDriver
                | ParentReplayPoisonPendingWitness
                | ParentReplayPoisonRecentProgressOnly -> ParentReplayPoisonPinDeferFreshRootLiveTail
                | ParentReplayPoisonNoLiveTail -> ParentReplayPoisonPinSurface
            else
                match liveness with
                | ParentReplayPoisonLiveQueueOrDriver -> ParentReplayPoisonPinDeferLiveQueuePendingZero
                | ParentReplayPoisonPendingWitness -> ParentReplayPoisonPinSuppressWithPendingWitness
                | ParentReplayPoisonRecentProgressOnly -> ParentReplayPoisonPinHardSurfacePendingZero
                | ParentReplayPoisonNoLiveTail -> ParentReplayPoisonPinSurface

        let private parentReplayPoisonPinSuppressionDecisionSuppresses = function
            | ParentReplayPoisonPinSuppressWithPendingWitness
            | ParentReplayPoisonPinDeferLiveQueuePendingZero
            | ParentReplayPoisonPinDeferFreshRootLiveTail
            | ParentReplayPoisonPinDeferHardObligationFreshPendingTail
            | ParentReplayPoisonPinDeferHardObligationStalePendingLiveTail
            | ParentReplayPoisonPinDeferJpStallPendingActiveTail
            | ParentReplayPoisonPinDeferCycleBreakLiveTailOverride -> true
            | ParentReplayPoisonPinSurface
            | ParentReplayPoisonPinHardSurfacePendingZero
            | ParentReplayPoisonPinForceSurfaceObligationCap
            | ParentReplayPoisonPinForceSurfaceStalePendingWitness
            | ParentReplayPoisonPinForceSurfaceHotPendingWitness -> false

        // MIGRATION: collapse the pending-zero parent-replay cascade authority into a DU.
        // Earlier rounds accumulated this as a large boolean OR, which made it too easy
        // to add another string/flag-only exception without updating telemetry.
        type ParentReplayPendingZeroCascadeAuthorityId =
            | ParentReplayPendingZeroCascadeNotPendingZero
            | ParentReplayPendingZeroCascadeDeferLiveTail
            | ParentReplayPendingZeroCascadeHardCapReceipt
            | ParentReplayPendingZeroCascadeStalePendingWitness
            | ParentReplayPendingZeroCascadeSuppressionForceSurfaceObligationCap
            | ParentReplayPendingZeroCascadeSuppressionForceSurfaceStaleWitness
            | ParentReplayPendingZeroCascadeSuppressionHardSurfacePendingZero

        let private parentReplayPendingZeroCascadeAuthorityText = function
            | ParentReplayPendingZeroCascadeNotPendingZero -> "not_pending_zero"
            | ParentReplayPendingZeroCascadeDeferLiveTail -> "defer_live_tail"
            | ParentReplayPendingZeroCascadeHardCapReceipt -> "hard_cap_receipt"
            | ParentReplayPendingZeroCascadeStalePendingWitness -> "stale_pending_witness"
            | ParentReplayPendingZeroCascadeSuppressionForceSurfaceObligationCap -> "suppression_force_surface_obligation_cap"
            | ParentReplayPendingZeroCascadeSuppressionForceSurfaceStaleWitness -> "suppression_force_surface_stale_witness"
            | ParentReplayPendingZeroCascadeSuppressionHardSurfacePendingZero -> "suppression_hard_surface_pending_zero"

        let private parentReplayPendingZeroCascadeAuthorityAllowsCascade = function
            | ParentReplayPendingZeroCascadeHardCapReceipt
            | ParentReplayPendingZeroCascadeStalePendingWitness
            | ParentReplayPendingZeroCascadeSuppressionForceSurfaceObligationCap
            | ParentReplayPendingZeroCascadeSuppressionForceSurfaceStaleWitness
            | ParentReplayPendingZeroCascadeSuppressionHardSurfacePendingZero -> true
            | ParentReplayPendingZeroCascadeNotPendingZero
            | ParentReplayPendingZeroCascadeDeferLiveTail -> false

        let private parentReplayPendingZeroCascadeAuthorityFor pending hardCapReceiptCount stalePendingWitnessForceSurface pinSuppressionDecision =
            if pending <> 0 then ParentReplayPendingZeroCascadeNotPendingZero
            elif hardCapReceiptCount > 0 then ParentReplayPendingZeroCascadeHardCapReceipt
            elif stalePendingWitnessForceSurface then ParentReplayPendingZeroCascadeStalePendingWitness
            else
                match pinSuppressionDecision with
                | ParentReplayPoisonPinForceSurfaceObligationCap -> ParentReplayPendingZeroCascadeSuppressionForceSurfaceObligationCap
                | ParentReplayPoisonPinForceSurfaceStalePendingWitness -> ParentReplayPendingZeroCascadeSuppressionForceSurfaceStaleWitness
                | ParentReplayPoisonPinHardSurfacePendingZero -> ParentReplayPendingZeroCascadeSuppressionHardSurfacePendingZero
                | ParentReplayPoisonPinSurface
                | ParentReplayPoisonPinSuppressWithPendingWitness
                | ParentReplayPoisonPinDeferLiveQueuePendingZero
                | ParentReplayPoisonPinDeferFreshRootLiveTail
                | ParentReplayPoisonPinDeferHardObligationFreshPendingTail
                | ParentReplayPoisonPinDeferHardObligationStalePendingLiveTail
                | ParentReplayPoisonPinDeferJpStallPendingActiveTail
                | ParentReplayPoisonPinDeferCycleBreakLiveTailOverride
                | ParentReplayPoisonPinForceSurfaceHotPendingWitness -> ParentReplayPendingZeroCascadeDeferLiveTail

        type ReplayObligationLivenessKind =
            | ReplayObligationQuiescent
            | ReplayObligationPendingOnly
            | ReplayObligationQueued
            | ReplayObligationActive
            | ReplayObligationDeferredCell
            | ReplayObligationProgressYield

        let private replayObligationLivenessKindText = function
            | ReplayObligationQuiescent -> "quiescent"
            | ReplayObligationPendingOnly -> "pending_only"
            | ReplayObligationQueued -> "queued"
            | ReplayObligationActive -> "active"
            | ReplayObligationDeferredCell -> "deferred_cell"
            | ReplayObligationProgressYield -> "progress_yield"

        // MIGRATION MIGRATION : replay identity is now a typed carrier.
        // No scheduler decision may use node=-1, raw kind/shape strings or an
        // unqualified stable key as authority.  Erasure is isolated to JSON/HUD.
        type ReplayKindId =
            | ReplayKindTerm
            | ReplayKindTy
            | ReplayKindDynamicJoin
            | ReplayKindParentResume
            | ReplayKindTerminalContract
            | ReplayKindTerminalContractEmission
            | ReplayKindReentrant
            | ReplayKindCrossKind
            | ReplayKindUnknown of reason:CompilerKernelV2.OperationalReasonId

        type ReentrantReplayK =
            | ReentrantReplayK
            static member ReplayKindId () = ReplayKindReentrant
        type ParentResumeReplayK =
            | ParentResumeReplayK
            static member ReplayKindId () = ReplayKindParentResume
        type DynamicJoinK =
            | DynamicJoinK
            static member ReplayKindId () = ReplayKindDynamicJoin
        type TerminalContractK =
            | TerminalContractK
            static member ReplayKindId () = ReplayKindTerminalContract
        type TerminalContractEmissionK =
            | TerminalContractEmissionK
            static member ReplayKindId () = ReplayKindTerminalContractEmission
        type TermReplayK =
            | TermReplayK
            static member ReplayKindId () = ReplayKindTerm
        type TyReplayK =
            | TyReplayK
            static member ReplayKindId () = ReplayKindTy
        type CrossKindReplayK =
            | CrossKindReplayK
            static member ReplayKindId () = ReplayKindCrossKind

        type ReplayShapeId =
            | ReplayShapeKnown of shape:CompilerIdentityKernel.WorkShapeId
            | ReplayShapeFromEvalKind of kind:EvalKind
            | ReplayShapeUnknown

        type ReplaySiteId =
            | ReplaySiteKnown of site:CompilerIdentityKernel.WorkSiteId
            | ReplaySiteSyntheticZero of site:CompilerIdentityKernel.WorkSiteId
            | ReplaySiteUnknown

        type SyntheticReplayNodeId =
            | ReplayNodeDerivedFromStableKey of stableKey:ReplayKeyId
            | ReplayNodeDerivedFromSite of site:CompilerIdentityKernel.WorkSiteId
            | ReplayNodeUnresolved

        type ReplayNodeIdentity<'K> =
            | ReplayNodeKnown of NodeId<'K>
            | ReplayNodeSynthetic of SyntheticReplayNodeId

        [<Struct>]
        type ReplayStableKey<'K> = private ReplayStableKey of ReplayKeyId

        [<Struct>]
        type ReplayKey<'K> = {
            node : ReplayNodeIdentity<'K>
            kind : ReplayKindId
            shape : ReplayShapeId
            site : ReplaySiteId
            stableKey : ReplayStableKey<'K>
        }

        // Defunctionalized HKT application keeps replay kinds typed across erased boundaries.
        // App<'F,'A> is the portable placeholder for Spiral's future real HKT.
        // ReplayKeyF is one type constructor witness; the existential package below
        // hides 'A without erasing the replay kind to string/obj in scheduler code.
        type ReplayKeyF = class end

        type private ReplayKeyApp<'K>(value:ReplayKey<'K>) =
            member _.Value = value
            interface App<ReplayKeyF,'K>

        type IReplayKeyAppVisitor<'R> =
            abstract Visit<'K> : App<ReplayKeyF,'K> -> 'R

        type ISomeReplayKeyApp =
            abstract Kind : ReplayKindId
            abstract ShapeText : string
            abstract SiteText : string
            abstract NodeText : string
            abstract KeyText : string
            abstract Accept<'R> : IReplayKeyAppVisitor<'R> -> 'R

        type private SomeReplayKeyApp<'K>(key:ReplayKey<'K>) =
            let app = ReplayKeyApp<'K>(key) :> App<ReplayKeyF,'K>
            interface ISomeReplayKeyApp with
                member _.Kind = key.kind
                member _.ShapeText =
                    match key.shape with
                    | ReplayShapeKnown shape -> CompilerIdentityKernel.WorkShapeIdOps.text shape
                    | ReplayShapeFromEvalKind kind -> evalKindToString kind
                    | ReplayShapeUnknown -> "unknown"
                member _.SiteText =
                    match key.site with
                    | ReplaySiteKnown site
                    | ReplaySiteSyntheticZero site -> CompilerIdentityKernel.WorkSiteIdOps.text site
                    | ReplaySiteUnknown -> "unknown"
                member _.NodeText =
                    match key.node with
                    | ReplayNodeKnown(NodeId nodeId) -> "node:" + string nodeId
                    | ReplayNodeSynthetic(ReplayNodeDerivedFromStableKey stableKey) -> "synthetic:key:" + ReplayKeyIdOps.text stableKey
                    | ReplayNodeSynthetic(ReplayNodeDerivedFromSite site) -> "synthetic:site:" + CompilerIdentityKernel.WorkSiteIdOps.text site
                    | ReplayNodeSynthetic ReplayNodeUnresolved -> "synthetic:unresolved"
                member _.KeyText =
                    let (ReplayStableKey stableKey) = key.stableKey
                    ReplayKeyIdOps.text stableKey
                member _.Accept<'R>(visitor:IReplayKeyAppVisitor<'R>) = visitor.Visit<'K> app

        let private someReplayKeyApp (key:ReplayKey<'K>) : ISomeReplayKeyApp =
            SomeReplayKeyApp<'K>(key) :> ISomeReplayKeyApp

        type AnyReplayKey =
            | AnyTermReplayKey of ReplayKey<TermReplayK>
            | AnyTyReplayKey of ReplayKey<TyReplayK>
            | AnyDynamicJoinReplayKey of ReplayKey<DynamicJoinK>
            | AnyParentResumeReplayKey of ReplayKey<ParentResumeReplayK>
            | AnyTerminalContractReplayKey of ReplayKey<TerminalContractK>
            | AnyTerminalContractEmissionReplayKey of ReplayKey<TerminalContractEmissionK>
            | AnyCrossKindReplayKey of ReplayKey<CrossKindReplayK>

        type CrossKindReplayObligation =
            | ReplayTermToTy of source:ReplayKey<TermReplayK> * target:ReplayKey<TyReplayK>
            | ReplayTyToTerm of source:ReplayKey<TyReplayK> * target:ReplayKey<TermReplayK>
            | ReplayTyToParent of source:ReplayKey<TyReplayK> * target:ReplayKey<ParentResumeReplayK>
            | ReplayDynamicJoinToParent of source:ReplayKey<DynamicJoinK> * target:ReplayKey<ParentResumeReplayK>
            | ReplayCrossKindUnresolved of source:AnyReplayKey * target:AnyReplayKey option

        type CrossKindWakeForEdge =
            | WakeTermWaitsForTy of source:ReplayKey<TermReplayK> * target:ReplayKey<TyReplayK> * ivarRef:CompilerIdentityKernel.ContentDigest option
            | WakeTyWaitsForTerm of source:ReplayKey<TyReplayK> * target:ReplayKey<TermReplayK> * ivarRef:CompilerIdentityKernel.ContentDigest option
            | WakeTyWaitsForParent of source:ReplayKey<TyReplayK> * target:ReplayKey<ParentResumeReplayK> * ivarRef:CompilerIdentityKernel.ContentDigest option
            | WakeDynamicJoinWaitsForParent of source:ReplayKey<DynamicJoinK> * target:ReplayKey<ParentResumeReplayK> * ivarRef:CompilerIdentityKernel.ContentDigest option
            | WakeCrossKindUnresolved of source:AnyReplayKey * target:AnyReplayKey option * ivarRef:CompilerIdentityKernel.ContentDigest option

        type ReplayObligationTarget =
            | ReplayObligationTypedTarget of target:ISomeReplayKeyApp
            | ReplayObligationCrossKindTarget of obligation:CrossKindReplayObligation

        type ReplayPayloadAvailabilityId =
            | ReplayPayloadCell
            | ReplayPayloadSemantic
            | ReplayPayloadMissing
            | ReplayPayloadNone

        type ReplayLivenessStatusId =
            | ReplayLivenessFrameStatus of FrameStatusId
            | ReplayLivenessPayloadAvailability of ReplayPayloadAvailabilityId

        type ReplayLivenessSnapshot = {
            pending : int
            queueDepth : int
            activeDepth : int
            payloadStatus : ReplayLivenessStatusId
            hasDeferredCell : bool
            hasProgressYield : bool
            kind : ReplayObligationLivenessKind
        }

        type ReplayQuiescenceLivenessNormalizationId =
            | ReplayQuiescenceMaterialReplayOpen
            | ReplayQuiescenceAlreadyClosed
            | ReplayQuiescenceProgressYieldResidueRetired of retiredCount:int

        type ReplayQuiescenceLivenessNormalization = {
            before : ReplayLivenessSnapshot
            after : ReplayLivenessSnapshot
            decision : ReplayQuiescenceLivenessNormalizationId
        }

        let private replayPayloadAvailabilityText = function
            | ReplayPayloadCell -> "cell"
            | ReplayPayloadSemantic -> "semantic"
            | ReplayPayloadMissing -> "missing"
            | ReplayPayloadNone -> "none"

        let private replayLivenessStatusText = function
            | ReplayLivenessFrameStatus status -> frameStatusToString status
            | ReplayLivenessPayloadAvailability availability -> replayPayloadAvailabilityText availability

        [<Struct>]
        type ClosureId<'K> = {
            id : ReplayKeyId
            status : FrameStatusId
            key : ReplayKeyId
        }

        let inline private replayKindIdFor< ^K when ^K : (static member ReplayKindId : unit -> ReplayKindId)> (_shape:CompilerIdentityKernel.WorkShapeId) =
            ((^K) : (static member ReplayKindId : unit -> ReplayKindId) ())

        let private replayShapeIdFor (shape:CompilerIdentityKernel.WorkShapeId) =
            if CompilerIdentityKernel.WorkShapeIdOps.slot shape = CompilerIdentityKernel.WorkShapeIdOps.slot CompilerIdentityKernel.WorkShapeIdOps.Known.unknown then ReplayShapeUnknown
            else ReplayShapeKnown shape

        let private replaySiteIdFor (site:CompilerIdentityKernel.WorkSiteId) =
            let siteText = CompilerIdentityKernel.WorkSiteIdOps.text site
            if String.IsNullOrWhiteSpace siteText then ReplaySiteUnknown
            elif siteText.EndsWith(":0", StringComparison.Ordinal) then ReplaySiteSyntheticZero site
            else ReplaySiteKnown site

        let private replaySiteIsSyntheticZero = function
            | ReplaySiteSyntheticZero _ -> true
            | _ -> false

        let private replayWorkSiteIsSyntheticZero site =
            site |> replaySiteIdFor |> replaySiteIsSyntheticZero

        let private replayStableKey<'K> (key:ReplayKeyId option) : ReplayStableKey<'K> =
            ReplayStableKey(defaultArg key ReplayKeyIdOps.Known.unresolved)

        let private replayNodeIdentityFor<'K> nodeId site key : ReplayNodeIdentity<'K> =
            if nodeId >= 0 then ReplayNodeKnown(NodeId nodeId)
            else
                match key, site with
                | Some stableKey, _ -> ReplayNodeSynthetic(ReplayNodeDerivedFromStableKey stableKey)
                | None, ReplaySiteKnown workSite
                | None, ReplaySiteSyntheticZero workSite -> ReplayNodeSynthetic(ReplayNodeDerivedFromSite workSite)
                | None, ReplaySiteUnknown -> ReplayNodeSynthetic ReplayNodeUnresolved

        let private terminalContractWorkShapeId = CompilerIdentityKernel.WorkShapeIdOps.create "TerminalContract"

        let private frameWorkShapeId (frame:Frame) =
            match frame.semanticCell with
            | Some cell -> cell.shape
            | None -> terminalContractWorkShapeId

        let inline private replayKeyOf< ^K when ^K : (static member ReplayKindId : unit -> ReplayKindId)> nodeId (shape:CompilerIdentityKernel.WorkShapeId) (site:CompilerIdentityKernel.WorkSiteId) key : ReplayKey< ^K> =
            let siteId = replaySiteIdFor site
            let keyId = if String.IsNullOrWhiteSpace key then None else Some(ReplayKeyIdOps.create key)
            { node = replayNodeIdentityFor< ^K> nodeId siteId keyId
              kind = replayKindIdFor< ^K> shape
              shape = replayShapeIdFor shape
              site = siteId
              stableKey = replayStableKey< ^K> keyId }

        let private closureIdOfStatusId<'K> id (status:FrameStatusId) key : ClosureId<'K> =
            { id = ReplayKeyIdOps.create id
              status = status
              key = ReplayKeyIdOps.create key }


        let private replayKindIdText = function
            | ReplayKindTerm -> "term"
            | ReplayKindTy -> "ty"
            | ReplayKindDynamicJoin -> "dynamic_join"
            | ReplayKindParentResume -> "parent_resume"
            | ReplayKindTerminalContract -> "terminal_contract"
            | ReplayKindTerminalContractEmission -> "terminal_contract_emission"
            | ReplayKindReentrant -> "reentrant"
            | ReplayKindCrossKind -> "cross_kind"
            | ReplayKindUnknown reason -> "unknown:" + CompilerKernelV2.OperationalReasonIdOps.text reason

        let private evalKindForReplayKindId = function
            | ReplayKindTerm -> EvalTerm
            | ReplayKindTy -> EvalTy
            | ReplayKindDynamicJoin -> EvalDynamicJoin
            | ReplayKindParentResume
            | ReplayKindTerminalContract
            | ReplayKindTerminalContractEmission
            | ReplayKindReentrant
            | ReplayKindCrossKind -> EvalUnknown (CompilerKernelV2.OperationalReasonIdOps.create "non_eval_replay_kind")
            | ReplayKindUnknown reason -> EvalUnknown reason

        let private replayShapeIdText = function
            | ReplayShapeKnown shape -> CompilerIdentityKernel.WorkShapeIdOps.text shape
            | ReplayShapeFromEvalKind kind -> evalKindToString kind
            | ReplayShapeUnknown -> "unknown"

        let private replaySiteIdText = function
            | ReplaySiteKnown site
            | ReplaySiteSyntheticZero site -> CompilerIdentityKernel.WorkSiteIdOps.text site
            | ReplaySiteUnknown -> "unknown"

        let private replayNodeIdentityText = function
            | ReplayNodeKnown(NodeId nodeId) -> "node:" + string nodeId
            | ReplayNodeSynthetic(ReplayNodeDerivedFromStableKey stableKey) -> "synthetic:key:" + ReplayKeyIdOps.text stableKey
            | ReplayNodeSynthetic(ReplayNodeDerivedFromSite site) -> "synthetic:site:" + CompilerIdentityKernel.WorkSiteIdOps.text site
            | ReplayNodeSynthetic ReplayNodeUnresolved -> "synthetic:unresolved"

        let private replayStableKeyText (ReplayStableKey key) = ReplayKeyIdOps.text key

        let private replayKeyDuText (key:ReplayKey<'K>) =
            FastRuntimeFormat.format "ReplayKey(node=%s|kind=%s|shape=%s|site=%s|key=%s)" [| box (replayNodeIdentityText key.node); box (replayKindIdText key.kind); box (replayShapeIdText key.shape); box (replaySiteIdText key.site); box (replayStableKeyText key.stableKey) |]

        let private anyReplayKeyText = function
            | AnyTermReplayKey key -> replayKeyDuText key
            | AnyTyReplayKey key -> replayKeyDuText key
            | AnyDynamicJoinReplayKey key -> replayKeyDuText key
            | AnyParentResumeReplayKey key -> replayKeyDuText key
            | AnyTerminalContractReplayKey key -> replayKeyDuText key
            | AnyTerminalContractEmissionReplayKey key -> replayKeyDuText key
            | AnyCrossKindReplayKey key -> replayKeyDuText key

        let private anyReplayKeyKind = function
            | AnyTermReplayKey _ -> ReplayKindTerm
            | AnyTyReplayKey _ -> ReplayKindTy
            | AnyDynamicJoinReplayKey _ -> ReplayKindDynamicJoin
            | AnyParentResumeReplayKey _ -> ReplayKindParentResume
            | AnyTerminalContractReplayKey _ -> ReplayKindTerminalContract
            | AnyTerminalContractEmissionReplayKey _ -> ReplayKindTerminalContractEmission
            | AnyCrossKindReplayKey _ -> ReplayKindUnknown (CompilerKernelV2.OperationalReasonIdOps.create "cross_kind")

        let private closureIdDuText (closure: ClosureId<'K>) =
            FastRuntimeFormat.format "ClosureId(id=%s|status=%s|key=%s)" [| box (ReplayKeyIdOps.text closure.id); box (frameStatusToString closure.status); box (ReplayKeyIdOps.text closure.key) |]

        type TerminalContractClosureEvidenceId = private TerminalContractClosureEvidenceId of string
        type TerminalContractReplayEvidenceId = private TerminalContractReplayEvidenceId of string
        type TerminalContractLivenessEvidenceId = private TerminalContractLivenessEvidenceId of string

        let private terminalContractClosureEvidence value = TerminalContractClosureEvidenceId value
        let private terminalContractReplayEvidence value = TerminalContractReplayEvidenceId value
        let private terminalContractLivenessEvidence value = TerminalContractLivenessEvidenceId value
        let private terminalContractClosureEvidenceText (TerminalContractClosureEvidenceId value) = value
        let private terminalContractReplayEvidenceText (TerminalContractReplayEvidenceId value) = value
        let private terminalContractLivenessEvidenceText (TerminalContractLivenessEvidenceId value) = value

        type TerminalContractAuthorityId =
            | TerminalContractClosureAware of closure:TerminalContractClosureEvidenceId * replay:TerminalContractReplayEvidenceId * liveness:TerminalContractLivenessEvidenceId
            | TerminalContractEmissionClosureAware of closure:TerminalContractClosureEvidenceId * replay:TerminalContractReplayEvidenceId * liveness:TerminalContractLivenessEvidenceId

        let private terminalContractAuthorityText = function
            | TerminalContractClosureAware(closure, replay, liveness) ->
                FastRuntimeFormat.format "TerminalContractAuthority(ClosureAware|closure=%s|replay=%s|liveness=%s)" [| box (terminalContractClosureEvidenceText closure); box (terminalContractReplayEvidenceText replay); box (terminalContractLivenessEvidenceText liveness) |]
            | TerminalContractEmissionClosureAware(closure, replay, liveness) ->
                FastRuntimeFormat.format "TerminalContractAuthority(EmissionClosureAware|closure=%s|replay=%s|liveness=%s)" [| box (terminalContractClosureEvidenceText closure); box (terminalContractReplayEvidenceText replay); box (terminalContractLivenessEvidenceText liveness) |]

        type DynamicJoinOperandIndexId =
            | DynamicJoinOperandIndex of int
            | DynamicJoinOperandIndexUnknown

        let private dynamicJoinOperandIndexText = function
            | DynamicJoinOperandIndex i -> sprintf "DynamicJoinOperand(index=%d)" i
            | DynamicJoinOperandIndexUnknown -> "DynamicJoinOperand(unknown)"

        type DynamicJoinBigStackSignalId =
            | DynamicJoinBigStackStalled
            | DynamicJoinBigStackRootHandoffObserved

        type DynamicJoinEvidenceId = {
            operand : DynamicJoinOperandIndexId
            dataShape : ReplayDataShapeId option
            reentrantReplayDriver : bool
            dynamicFunctionBridge : bool
            runtimeDynTypecheck : bool
            partEvalTypeError : bool
            pinnedTerminalContract : bool
            generationChangedWait : bool
            staleActiveGlobalFuseTerminal : bool
            bigStackSignal : DynamicJoinBigStackSignalId option
        }

        let private dynamicJoinEvidenceFromTypedContext dynamicFunctionBridgeContext operand dataShape reasonEvidence diagnosticFacts =
            let has fact = Set.contains fact diagnosticFacts
            let bigStackSignal =
                if has DiagnosticClassifier.DiagnosticBigStackSemanticRootCompleteHandoff then
                    Some DynamicJoinBigStackRootHandoffObserved
                elif has DiagnosticClassifier.DiagnosticBigStackJoinStalled then
                    Some DynamicJoinBigStackStalled
                else None
            { operand = DynamicJoinOperandIndex operand
              dataShape = Some dataShape
              reentrantReplayDriver = has DiagnosticClassifier.DiagnosticReentrantReplayDriver
              dynamicFunctionBridge = dynamicFunctionBridgeContext || has DiagnosticClassifier.DiagnosticDynamicFunctionBridge
              runtimeDynTypecheck =
                  EvalReplayValueStore.dynamicJoinReasonEvidenceHasRuntimeDynTypecheck reasonEvidence
                  || has DiagnosticClassifier.DiagnosticDynamicJoinRuntimeDynTypecheck
              partEvalTypeError =
                  EvalReplayValueStore.dynamicJoinReasonEvidenceHasPartEvalTypeError reasonEvidence
                  || has DiagnosticClassifier.DiagnosticPartEvalTypeError
              pinnedTerminalContract = has DiagnosticClassifier.DiagnosticPinnedTerminalContract
              generationChangedWait = has DiagnosticClassifier.DiagnosticGenerationChangedWhileWaiting
              staleActiveGlobalFuseTerminal = has DiagnosticClassifier.DiagnosticStaleActiveGlobalFuseTerminal
              bigStackSignal = bigStackSignal }

        let private dynamicJoinEvidenceOfReplayApplyContext dynamicFunctionBridgeContext applyFailure =
            dynamicJoinEvidenceFromTypedContext
                dynamicFunctionBridgeContext
                (EvalReplayValueStore.replayApplyContextFailureArgIndex applyFailure)
                (EvalReplayValueStore.replayApplyContextFailureArgShape applyFailure)
                (EvalReplayValueStore.replayApplyContextFailureEvidence applyFailure)
                (EvalReplayValueStore.replayApplyContextFailureDiagnosticFacts applyFailure)

        let private dynamicJoinEvidenceOfDynamicJoinApplyContext dynamicFunctionBridgeContext dynamicJoinFailure =
            dynamicJoinEvidenceFromTypedContext
                dynamicFunctionBridgeContext
                (EvalReplayValueStore.dynamicJoinApplyContextFailureArgIndex dynamicJoinFailure)
                (EvalReplayValueStore.dynamicJoinApplyContextFailureArgShape dynamicJoinFailure)
                (EvalReplayValueStore.dynamicJoinApplyContextFailureEvidence dynamicJoinFailure)
                (EvalReplayValueStore.dynamicJoinApplyContextFailureDiagnosticFacts dynamicJoinFailure)

        type DynamicJoinShapeRoleId =
            | DynamicJoinFunctionRole
            | DynamicJoinArgumentRole

        let private dynamicJoinShapeRoleText = function
            | DynamicJoinFunctionRole -> "function"
            | DynamicJoinArgumentRole -> "arg"

        type DynamicJoinShapeId =
            | DynamicJoinTypedShape of role:DynamicJoinShapeRoleId * shape:ReplayDataShapeId
            | DynamicJoinFallbackShape of role:DynamicJoinShapeRoleId * raw:string
            | DynamicJoinShapeUnknown of role:DynamicJoinShapeRoleId

        let private dynamicJoinShapeText = function
            | DynamicJoinTypedShape(role, shape) ->
                sprintf "DynamicJoinShape(role=%s|shape=%s)" (dynamicJoinShapeRoleText role) (replayDataShapeText shape)
            | DynamicJoinFallbackShape(role, raw) ->
                sprintf "DynamicJoinShape(role=%s|shape=%s)" (dynamicJoinShapeRoleText role) raw
            | DynamicJoinShapeUnknown role -> sprintf "DynamicJoinShape(role=%s|shape=unknown)" (dynamicJoinShapeRoleText role)

        let private dynamicJoinShapeFromEvidence role fallback evidence =
            match evidence.dataShape with
            | Some shape -> DynamicJoinTypedShape(role, shape)
            | None when System.String.IsNullOrWhiteSpace fallback -> DynamicJoinShapeUnknown role
            | None -> DynamicJoinFallbackShape(role, fallback)

        type DynamicJoinSymbolicCarrierId =
            | DynamicJoinCarrierRuntimeUnion
            | DynamicJoinCarrierSymbolicRuntimeValue
            | DynamicJoinCarrierDynamicFunction
            | DynamicJoinCarrierDynamicRecord
            | DynamicJoinCarrierPlaceholder
            | DynamicJoinCarrierLiteral
            | DynamicJoinCarrierUnknown

        let private dynamicJoinSymbolicCarrierText = function
            | DynamicJoinCarrierRuntimeUnion -> "DynamicJoinCarrier(RuntimeUnion)"
            | DynamicJoinCarrierSymbolicRuntimeValue -> "DynamicJoinCarrier(SymbolicRuntimeValue)"
            | DynamicJoinCarrierDynamicFunction -> "DynamicJoinCarrier(DynamicFunction)"
            | DynamicJoinCarrierDynamicRecord -> "DynamicJoinCarrier(DynamicRecord)"
            | DynamicJoinCarrierPlaceholder -> "DynamicJoinCarrier(Placeholder)"
            | DynamicJoinCarrierLiteral -> "DynamicJoinCarrier(Literal)"
            | DynamicJoinCarrierUnknown -> "DynamicJoinCarrier(Unknown)"

        let private dynamicJoinSymbolicCarrierForEvidence evidence =
            match evidence.dataShape with
            | Some (ReplayDataNominal ReplayDataUnion)
            | Some ReplayDataUnion -> DynamicJoinCarrierRuntimeUnion
            | Some ReplayDataVariable -> DynamicJoinCarrierSymbolicRuntimeValue
            | Some ReplayDataFunction -> DynamicJoinCarrierDynamicFunction
            | Some ReplayDataRecord -> DynamicJoinCarrierDynamicRecord
            | Some ReplayDataDb -> DynamicJoinCarrierPlaceholder
            | Some ReplayDataLiteral
            | Some ReplayDataTypeLiteral -> DynamicJoinCarrierLiteral
            | _ -> DynamicJoinCarrierUnknown

        [<StructuralEquality; NoComparison>]
        type DynamicJoinOwnerId = private {
            nodeId : int
            shape : CompilerIdentityKernel.WorkShapeId
        }

        let private dynamicJoinOwnerId nodeId shape = { nodeId = nodeId; shape = shape }
        let private dynamicJoinOwnerText owner =
            sprintf "dynamic_join:%d:%s" owner.nodeId (CompilerIdentityKernel.WorkShapeIdOps.text owner.shape)

        type DynamicJoinBridgeTailLeaseId =
            | DynamicJoinBridgeTailLeaseLive of owner:DynamicJoinOwnerId * pending:int * queueDepth:int * activeDepth:int
            | DynamicJoinBridgeTailLeaseAbsentNoPendingQueueActiveOrProgressYield

        let private dynamicJoinBridgeTailLeaseText = function
            | DynamicJoinBridgeTailLeaseLive(owner, pending, queueDepth, activeDepth) ->
                FastRuntimeFormat.format "BridgeTailLease(Live|owner=%s|pending=%d|queue=%d|active=%d)" [| box (dynamicJoinOwnerText owner); box pending; box queueDepth; box activeDepth |]
            | DynamicJoinBridgeTailLeaseAbsentNoPendingQueueActiveOrProgressYield ->
                "BridgeTailLease(Absent|reason=no_pending_queue_active_or_progress_yield)"

        let private dynamicJoinBridgeTailLeaseFor owner pending queueDepth activeDepth progressYieldPending =
            if pending > 0 || queueDepth > 0 || activeDepth > 0 || progressYieldPending then
                DynamicJoinBridgeTailLeaseLive(owner, pending, queueDepth, activeDepth)
            else
                DynamicJoinBridgeTailLeaseAbsentNoPendingQueueActiveOrProgressYield

        type DynamicJoinHandoffStateId =
            | DynamicJoinHandoffSuppressedLiveReplay of carrier:DynamicJoinSymbolicCarrierId * lease:DynamicJoinBridgeTailLeaseId
            | DynamicJoinHandoffPinnedTerminal of carrier:DynamicJoinSymbolicCarrierId * lease:DynamicJoinBridgeTailLeaseId
            | DynamicJoinHandoffObservedBlocked of carrier:DynamicJoinSymbolicCarrierId * lease:DynamicJoinBridgeTailLeaseId

        let private dynamicJoinHandoffStateText = function
            | DynamicJoinHandoffSuppressedLiveReplay(carrier, lease) ->
                sprintf "DynamicJoinHandoff(SuppressedLiveReplay|carrier=%s|lease=%s)" (dynamicJoinSymbolicCarrierText carrier) (dynamicJoinBridgeTailLeaseText lease)
            | DynamicJoinHandoffPinnedTerminal(carrier, lease) ->
                sprintf "DynamicJoinHandoff(PinnedTerminal|carrier=%s|lease=%s)" (dynamicJoinSymbolicCarrierText carrier) (dynamicJoinBridgeTailLeaseText lease)
            | DynamicJoinHandoffObservedBlocked(carrier, lease) ->
                sprintf "DynamicJoinHandoff(ObservedBlocked|carrier=%s|lease=%s)" (dynamicJoinSymbolicCarrierText carrier) (dynamicJoinBridgeTailLeaseText lease)

        type DynamicJoinApplyWitnessTypedId =
            | DynamicJoinApplyWitnessTyped of operand:DynamicJoinOperandIndexId * functionShape:DynamicJoinShapeId * argShape:DynamicJoinShapeId * carrier:DynamicJoinSymbolicCarrierId * lease:DynamicJoinBridgeTailLeaseId

        let private dynamicJoinApplyWitnessTypedText = function
            | DynamicJoinApplyWitnessTyped(operand, functionShape, argShape, carrier, lease) ->
                FastRuntimeFormat.format "DynamicJoinApplyWitnessTyped(operand=%s|function=%s|arg=%s|carrier=%s|lease=%s)" [| box (dynamicJoinOperandIndexText operand); box (dynamicJoinShapeText functionShape); box (dynamicJoinShapeText argShape); box (dynamicJoinSymbolicCarrierText carrier); box (dynamicJoinBridgeTailLeaseText lease) |]

        type DynamicJoinAuthorityReasonId =
            | DynamicJoinAuthorityExplicitReentrantNoWaiter
            | DynamicJoinAuthorityRuntimeUnionBridgeTailLive
            | DynamicJoinAuthorityTerminalPolicyDefersWhileLiveReplay
            | DynamicJoinAuthorityBridgeTailLiveRequiresReplayDrain
            | DynamicJoinAuthorityBridgeTailAbsent

        let private dynamicJoinAuthorityReasonText = function
            | DynamicJoinAuthorityExplicitReentrantNoWaiter -> "explicit_reentrant_no_waiter"
            | DynamicJoinAuthorityRuntimeUnionBridgeTailLive -> "runtime_union_bridge_tail_live"
            | DynamicJoinAuthorityTerminalPolicyDefersWhileLiveReplay -> "terminal_policy_defers_while_live_replay"
            | DynamicJoinAuthorityBridgeTailLiveRequiresReplayDrain -> "bridge_tail_live_requires_replay_drain"
            | DynamicJoinAuthorityBridgeTailAbsent -> "bridge_tail_absent"

        type DynamicJoinAuthorityDecisionId =
            | DynamicJoinAuthoritySuppressLiveReplay of witness:DynamicJoinApplyWitnessTypedId * reason:DynamicJoinAuthorityReasonId
            | DynamicJoinAuthorityAwaitBridgeTail of witness:DynamicJoinApplyWitnessTypedId * reason:DynamicJoinAuthorityReasonId
            | DynamicJoinAuthorityScheduleDrain of witness:DynamicJoinApplyWitnessTypedId * reason:DynamicJoinAuthorityReasonId
            | DynamicJoinAuthorityPinTerminal of witness:DynamicJoinApplyWitnessTypedId * reason:DynamicJoinAuthorityReasonId

        let private dynamicJoinAuthorityDecisionText = function
            | DynamicJoinAuthoritySuppressLiveReplay(witness, reason) -> sprintf "DynamicJoinAuthority(SuppressLiveReplay|reason=%s|witness=%s)" (dynamicJoinAuthorityReasonText reason) (dynamicJoinApplyWitnessTypedText witness)
            | DynamicJoinAuthorityAwaitBridgeTail(witness, reason) -> sprintf "DynamicJoinAuthority(AwaitBridgeTail|reason=%s|witness=%s)" (dynamicJoinAuthorityReasonText reason) (dynamicJoinApplyWitnessTypedText witness)
            | DynamicJoinAuthorityScheduleDrain(witness, reason) -> sprintf "DynamicJoinAuthority(ScheduleDrain|reason=%s|witness=%s)" (dynamicJoinAuthorityReasonText reason) (dynamicJoinApplyWitnessTypedText witness)
            | DynamicJoinAuthorityPinTerminal(witness, reason) -> sprintf "DynamicJoinAuthority(PinTerminal|reason=%s|witness=%s)" (dynamicJoinAuthorityReasonText reason) (dynamicJoinApplyWitnessTypedText witness)

        let private dynamicJoinAuthorityNextText = function
            | DynamicJoinAuthoritySuppressLiveReplay(_, _) -> "continue_active_replay_driver"
            | DynamicJoinAuthorityAwaitBridgeTail(_, _) -> "await_bridge_tail_or_root_complete"
            | DynamicJoinAuthorityScheduleDrain(_, _) -> "schedule_dynamic_join_replay_drain"
            | DynamicJoinAuthorityPinTerminal(_, _) -> "pin_terminal_contract"

        let private dynamicJoinAuthoritySuppressesPin = function
            | DynamicJoinAuthoritySuppressLiveReplay(_, _)
            | DynamicJoinAuthorityAwaitBridgeTail(_, _)
            | DynamicJoinAuthorityScheduleDrain(_, _) -> true
            | DynamicJoinAuthorityPinTerminal(_, _) -> false

        let private dynamicJoinAuthorityDecisionFor
            (baseDecision: DynamicJoinTerminalDecisionId)
            liveSuppressed
            freshRootOrReplayEvidence
            reentrantNoWaiter
            (witness: DynamicJoinApplyWitnessTypedId) =
            match witness with
            | DynamicJoinApplyWitnessTyped(_, _, _, carrier, lease) ->
                match lease, carrier, reentrantNoWaiter, baseDecision, liveSuppressed, freshRootOrReplayEvidence with
                | _, _, true, _, _, _ ->
                    DynamicJoinAuthorityPinTerminal(witness, DynamicJoinAuthorityExplicitReentrantNoWaiter)
                | DynamicJoinBridgeTailLeaseLive(_, _, _, _), DynamicJoinCarrierRuntimeUnion, false, _, _, true ->
                    DynamicJoinAuthorityAwaitBridgeTail(witness, DynamicJoinAuthorityRuntimeUnionBridgeTailLive)
                | DynamicJoinBridgeTailLeaseLive(_, _, _, _), _, false, DynamicJoinTerminalDeferLiveReplay, true, _ ->
                    DynamicJoinAuthoritySuppressLiveReplay(witness, DynamicJoinAuthorityTerminalPolicyDefersWhileLiveReplay)
                | DynamicJoinBridgeTailLeaseLive(_, _, _, _), _, false, _, _, _ ->
                    DynamicJoinAuthorityScheduleDrain(witness, DynamicJoinAuthorityBridgeTailLiveRequiresReplayDrain)
                | DynamicJoinBridgeTailLeaseAbsentNoPendingQueueActiveOrProgressYield, _, _, _, _, _ ->
                    DynamicJoinAuthorityPinTerminal(witness, DynamicJoinAuthorityBridgeTailAbsent)

        [<Struct>]
        type ReplayLivenessProof<'K> = {
            pending : int
            queueDepth : int
            activeDepth : int
            deferredCell : bool
            progressYield : bool
            allEmpty : bool
            proofKind : ReplayKeyId
        }

        let private replayLivenessProof<'K> proofKind (liveness: ReplayLivenessSnapshot) : ReplayLivenessProof<'K> =
            { pending = liveness.pending
              queueDepth = liveness.queueDepth
              activeDepth = liveness.activeDepth
              deferredCell = liveness.hasDeferredCell
              progressYield = liveness.hasProgressYield
              allEmpty = liveness.pending = 0 && liveness.queueDepth = 0 && liveness.activeDepth = 0 && not liveness.hasDeferredCell && not liveness.hasProgressYield
              proofKind = ReplayKeyIdOps.create proofKind }

        let private replayLivenessProofDuText (proof: ReplayLivenessProof<'K>) =
            FastRuntimeFormat.format "ReplayLivenessProof(kind=%s|pending=%d|queue=%d|active=%d|deferred=%b|progress_yield=%b|all_empty=%b)" [| box (ReplayKeyIdOps.text proof.proofKind); box proof.pending; box proof.queueDepth; box proof.activeDepth; box proof.deferredCell; box proof.progressYield; box proof.allEmpty |]


        let private replayNonEmptyOr fallback (text:string) =
            if System.String.IsNullOrWhiteSpace text then fallback else text

        type MissingAfterPrefetchTerminalSnapshot = {
            observationId : string
            event : string
            site : CompilerIdentityKernel.WorkSiteId
            key : ReplayKeyId
            reason : CompilerKernelV2.OperationalReasonId
            firstSeenMs : int64
            lastSeenMs : int64
            repeatCount : int64
            pending : int
            queueDepth : int
            activeDepth : int
            physicallyClosedObserved : bool
        }

        [<StructuralEquality; NoComparison>]
        type MissingAfterPrefetchTerminalIdentity = private {
            site : CompilerIdentityKernel.WorkSiteId
            key : ReplayKeyId
        }

        let private missingAfterPrefetchTerminalIdentityFor
            (site:CompilerIdentityKernel.WorkSiteId)
            (key:ReplayKeyId)
            : MissingAfterPrefetchTerminalIdentity =
            { site = site
              key = key }

        let private missingAfterPrefetchTerminalLedger =
            System.Collections.Concurrent.ConcurrentDictionary<MissingAfterPrefetchTerminalIdentity,MissingAfterPrefetchTerminalSnapshot>()

        let private missingAfterPrefetchTerminalObservationId (identity:MissingAfterPrefetchTerminalIdentity) =
            CompilerIdentityKernel.ContentDigest.ofText
                "missing-after-prefetch-terminal"
                (CompilerIdentityKernel.WorkSiteIdOps.text identity.site + "\u001f" + ReplayKeyIdOps.text identity.key)
            |> CompilerIdentityKernel.ContentDigest.text

        let private noteMissingAfterPrefetchTerminalObservation
            (event:string)
            (site:CompilerIdentityKernel.WorkSiteId)
            (key:ReplayKeyId)
            (reason:CompilerKernelV2.OperationalReasonId)
            (pending:int)
            (queueDepth:int)
            (activeDepth:int)
            : MissingAfterPrefetchTerminalSnapshot =
            let nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let identity = missingAfterPrefetchTerminalIdentityFor site key
            let observationId = missingAfterPrefetchTerminalObservationId identity
            let physicallyClosed = pending = 0 && queueDepth = 0 && activeDepth = 0
            missingAfterPrefetchTerminalLedger.AddOrUpdate(
                identity,
                (fun _ ->
                    { observationId = observationId
                      event = event
                      site = site
                      key = key
                      reason = reason
                      firstSeenMs = nowMs
                      lastSeenMs = nowMs
                      repeatCount = 1L
                      pending = pending
                      queueDepth = queueDepth
                      activeDepth = activeDepth
                      physicallyClosedObserved = physicallyClosed }),
                (fun _ (prior:MissingAfterPrefetchTerminalSnapshot) ->
                    { prior with
                        event = event
                        reason = reason
                        lastSeenMs = nowMs
                        repeatCount = prior.repeatCount + 1L
                        pending = pending
                        queueDepth = queueDepth
                        activeDepth = activeDepth
                        physicallyClosedObserved = prior.physicallyClosedObserved || physicallyClosed }))

        let missingAfterPrefetchTerminalSnapshotAgeMs (snapshot:MissingAfterPrefetchTerminalSnapshot) =
            max 0L (DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - snapshot.firstSeenMs)

        let missingAfterPrefetchTerminalSnapshotNow () : MissingAfterPrefetchTerminalSnapshot option =
            let mutable selected : MissingAfterPrefetchTerminalSnapshot option = None
            for kv in missingAfterPrefetchTerminalLedger do
                match selected with
                | Some prior when prior.physicallyClosedObserved && not kv.Value.physicallyClosedObserved -> ()
                | Some prior
                    when prior.physicallyClosedObserved = kv.Value.physicallyClosedObserved
                         && prior.lastSeenMs >= kv.Value.lastSeenMs -> ()
                | _ -> selected <- Some kv.Value
            selected

        let private pinTerminalContractLocked (event: string) (frame: Frame) =
            let isCurrentRootCompleteSite =
                frameOrCellIsRootComplete frame
            let pendingForTerminalPin =
                let mutable n = 0
                let seen = System.Collections.Generic.HashSet<ReplayFramePendingIdentity>()
                let add (opt: Frame option) =
                    match opt with
                    | Some frame ->
                        let identity : ReplayFramePendingIdentity = {
                            kind = frameEvalKindId frame
                            key = frame.key
                            site = frame.site
                        }
                        if seen.Add identity then n <- n + 1
                    | None -> ()
                add frontier
                add frontierTerm
                add frontierTy
                n
            let drainStateForTerminalPin = replayDrainStateLocked()
            let terminalPinLivenessGate = terminalPinLivenessGateOfState drainStateForTerminalPin (progressYieldCount > 0)
            let terminalPinHasLiveReplay = terminalPinLivenessGateHasLiveReplay terminalPinLivenessGate
            let terminalPinHasWitnessQueue = terminalPinLivenessGateHasWitnessQueue terminalPinLivenessGate
            let replayRootWriteWitnessFreshForPin =
                let frontierComplete =
                    match frontier with
                    | Some frame when frameOrCellIsRootComplete frame -> true
                    | Some _ -> false
                    | None -> false
                if frontierComplete then true
                else
                    let noLiveReplay =
                        pendingForTerminalPin = 0
                        && replayQueue.Length = 0
                        && replayDriverActiveDepth = 0
                    let ageMs = (System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds
                    noLiveReplay
                    && replayRootCompleteWitnessUtc <> System.DateTime.MinValue
                    && ageMs >= 0.0
                    && ageMs <= replayRootCompleteWitnessWindowMs
            let replayRootWriteWitnessSummaryForPin =
                if replayRootCompleteWitnessUtc = System.DateTime.MinValue then "none"
                else sprintf "%s age_ms=%.0f" replayRootCompleteWitnessSummary ((System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds)
            let suppressAppRootStaleRetargetPin =
                frameSemanticStatusIs SemanticRootCompleteStaleRetargetRepeatBlocked frame
                && isCurrentRootCompleteSite
                && stableRootCompleteCount > 0
                && (match frame.semanticCell with
                    | Some cell -> replayCellShapeId cell = CellShapeTRecord
                    | None -> List.contains ReplayFrameKeyNodeIdentity frame.keySignals)
            let suppressAppRootParentCyclePin =
                frameSemanticStatusIs SemanticParentContinuationCycleBlocked frame
                && isCurrentRootCompleteSite
                && (stableRootCompleteCount > 0 || replayRootWriteWitnessFreshForPin)
                && pendingForTerminalPin <= 2
                && replayRootWriteWitnessFreshForPin
            let suppressSyntheticChildScheduleRepeatPin =
                frameSemanticStatusIs SemanticReplayChildScheduleRepeatBlocked frame
                && pendingForTerminalPin > 0
                && replayRootWriteWitnessFreshForPin
                && (replayWorkSiteIsSyntheticZero frame.site
                    || List.contains ReplayFrameKeySyntheticZero frame.keySignals
                    || (match frame.semanticCell with
                        | Some cell -> replayWorkSiteIsSyntheticZero cell.site
                        | None -> false))
            let suppressLiveReplayParentCyclePin =
                frameSemanticStatusIs SemanticParentContinuationCycleBlocked frame
                && pendingForTerminalPin > 0
                && terminalPinHasLiveReplay
            let suppressLiveReplayAppRootBase16HardcapPin =
                frameSemanticStatusIs SemanticAppRootBase16StaleRetargetHardcapBlocked frame
                && pendingForTerminalPin > 0
                && terminalPinHasLiveReplay
            let suppressLiveReplayChildScheduleRepeatPin =
                isSemanticReplayChildScheduleRepeatBlockedStatusId (frameSemanticStatusId frame)
                && pendingForTerminalPin > 0
                && terminalPinHasLiveReplay
            let suppressLiveReplayRecordWithValuePin =
                match frameSemanticStatusId frame with
                | SemanticRecordWithValueBlocked ->
                    pendingForTerminalPin > 0
                    && terminalPinHasLiveReplay
                | _ -> false
            let suppressLiveReplayOpImplRequiredPin =
                match frameSemanticStatusId frame with
                | SemanticOpImplRequiredBlocked ->
                    match liveReplayTerminalPolicyOfSemanticStatusId SemanticOpImplRequiredBlocked with
                    | DeferTerminalWhileLiveReplay ->
                        pendingForTerminalPin > 0
                        && (terminalPinHasLiveReplay || terminalPinHasWitnessQueue || replayRootWriteWitnessFreshForPin)
                    | SurfaceTerminalDuringLiveReplay
                    | TerminalNotLiveReplayPolicy -> false
                | _ -> false
            let opReplayDriverExceptionReasonId =
                match framePayloadReasonSignal frame.payload with
                | Some FrameReasonSignalOpReplayDriverNull -> OpReplayDriverExceptionNull
                | _ -> OpReplayDriverExceptionOther frame.reason
            let suppressLiveReplayOpReplayDriverExceptionPin =
                frameSemanticStatusIs SemanticReplayDriverExceptionBlocked frame
                && pendingForTerminalPin > 0
                && (terminalPinHasLiveReplay || replayRootWriteWitnessFreshForPin)
                && (opReplayDriverExceptionReasonIsNull opReplayDriverExceptionReasonId
                    || (match frame.semanticCell with
                        | Some cell -> replayCellEvalKindId cell = EvalTerm && replayCellShapeId cell = CellShapeEOp
                        | None -> false))
            let frameTypedPrefetchSignal =
                match framePayloadReasonSignal frame.payload with
                | Some FrameReasonSignalMissingAfterPrefetch -> true
                | _ -> false
            let frameLegacyPrefetchSignals =
                framePayloadLegacyPrefetchEvidence frame.payload
            let terminalPinHopacOverridePierceSidecarP0 =
                (frameSemanticStatusIs SemanticMissingAfterPrefetchBlocked frame
                 || frameTypedPrefetchSignal
                 || Set.contains ReplayPrefetchEvidenceMissingAfterPrefetch frameLegacyPrefetchSignals
                 || Set.contains ReplayPrefetchEvidencePresent frameLegacyPrefetchSignals)
                && pendingForTerminalPin <= 0
                && (replayQueue.Length > 0 || replayDriverActiveDepth > 0)
                && (DiagJson.snapshotKindCount "eval_worklist_stack_fence_prefetch_ledger_audit" > 0
                    || DiagJson.snapshotKindCount "eval_worklist_live_replay_missing_after_prefetch_pin_suppressed" > 0
                    || DiagJson.snapshotKindCount "eval_worklist_pending_ledger_reconciled_from_frontier_snapshot" > 0)
            let suppressLiveReplayMissingAfterPrefetchPin =
                frameSemanticStatusIs SemanticMissingAfterPrefetchBlocked frame
                && not terminalPinHopacOverridePierceSidecarP0
                && (pendingForTerminalPin > 0
                    || replayQueue.Length >= 16
                    || replayDriverActiveDepth > 0
                    || replayRootWriteWitnessFreshForPin
                    || isCurrentRootCompleteSite)
                && (terminalPinHasLiveReplay || terminalPinHasWitnessQueue || replayQueue.Length > 0 || replayDriverActiveDepth > 0 || replayRootWriteWitnessFreshForPin || isCurrentRootCompleteSite)
            let parentReplayPoisonLivenessId =
                parentReplayPoisonLivenessFor terminalPinHasLiveReplay pendingForTerminalPin progressYieldCount
            let parentReplayPoisonHardCapReceiptCount =
                DiagJson.snapshotKindCount "eval_worklist_cross_kind_yield_thrash_hard_poison"
                + DiagJson.snapshotKindCount "eval_worklist_replay_obligation_post_schedule_cap_hard_poison"
            let parentReplayPoisonSuppressedPinCount =
                DiagJson.snapshotKindCount "eval_worklist_live_replay_parent_replay_poison_pin_suppressed"
            let parentReplayPoisonPreservedRepeatCount =
                parentReplayPreservedCountForFrame frame
            let parentReplayPoisonWitnessAgeMs =
                if replayRootCompleteWitnessUtc = System.DateTime.MinValue then -1.0
                else (System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds
            let parentReplayPoisonReasonProbeId =
                match framePayloadReasonSignal frame.payload with
                | Some (FrameReasonSignalParentReplayStatusPreservedRepeat _) -> ParentReplayPoisonReasonStatusPreservedRepeat
                | Some (FrameReasonSignalCrossKind _) -> ParentReplayPoisonReasonCrossKindActiveReplayDriver
                | _ when frameSemanticStatusIs SemanticParentReplayStatusPreservedRepeatBlocked frame -> ParentReplayPoisonReasonStatusPreservedRepeat
                | _ -> ParentReplayPoisonReasonOther frame.reason
            let parentReplayPoisonReasonProbe =
                parentReplayPoisonReasonProbeText parentReplayPoisonReasonProbeId
            let parentReplayPoisonPhysicalLiveTail =
                terminalPinHasLiveReplay
                || terminalPinHasWitnessQueue
                || replayQueue.Length > 0
                || replayDriverActiveDepth > 0
            let parentReplayPoisonRepeatCapFreshRootWitnessGuard =
                // MIGRATION: MIGRATION proved the no-root probation drain can be correct
                // but arrive too late: parent poison pin/cascade may fire first while a
                // fresh root witness and runnable sibling tail still exist.  Guard only
                // the young repeat-cap case; hard-cap receipts and stale witnesses keep
                // their terminal authority.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && pendingForTerminalPin = 0
                && parentReplayPoisonHardCapReceiptCount = 0
                && parentReplayPoisonPreservedRepeatCount > parent_replay_preserved_repeat_cap
                && parentReplayPoisonWitnessAgeMs >= 0.0
                && parentReplayPoisonWitnessAgeMs <= 5000.0
                && (replayQueue.Length > 0 || replayDriverActiveDepth > 0 || terminalPinHasLiveReplay || terminalPinHasWitnessQueue)
                && not isCurrentRootCompleteSite
                && (not replayRootWriteWitnessFreshForPin || parentReplayPoisonReasonProbeIsCrossKindActive parentReplayPoisonReasonProbeId || parentReplayPoisonHardCapReceiptCount > 0)
            let parentReplayPoisonStalePendingWitnessForceSurface =
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && pendingForTerminalPin > 0
                && not replayRootWriteWitnessFreshForPin
                && (progressYieldCount >= 1024
                    || parentReplayPoisonSuppressedPinCount >= 4
                    || parentReplayPoisonPreservedRepeatCount >= 4
                    || parentReplayPoisonHardCapReceiptCount > 0)
                && not parentReplayPoisonRepeatCapFreshRootWitnessGuard
                && (parentReplayPoisonWitnessAgeMs < 0.0
                    || parentReplayPoisonWitnessAgeMs >= 1500.0
                    || parentReplayPoisonSuppressedPinCount >= 8
                    || parentReplayPoisonPreservedRepeatCount >= 7)
                && (terminalPinHasLiveReplay
                    || terminalPinHasWitnessQueue
                    || replayQueue.Length > 0
                    || replayDriverActiveDepth > 0)
                && (parentReplayPoisonHardCapReceiptCount > 0
                    || parentReplayPoisonSuppressedPinCount >= 2
                    || parentReplayPoisonPreservedRepeatCount >= 4
                    || progressYieldCount >= 32768
                    || replayQueue.Length <= 64
                    || parentReplayPoisonReasonProbeIsCrossKindActive parentReplayPoisonReasonProbeId)
                && (parentReplayPoisonHardCapReceiptCount > 0
                    || (parentReplayPoisonWitnessAgeMs >= 12000.0 && replayQueue.Length <= 8 && replayDriverActiveDepth <= 0))
            let parentReplayPoisonStalePendingWitnessCap =
                parentReplayPoisonStalePendingWitnessForceSurface
            let parentReplayPoisonPendingZeroLiveTailForceSurface =
                // MIGRATION: MIGRATION showed pending=0 parent replay poison could still be
                // suppressed by the live-queue shield while the HUD already had same_hot=5,
                // hard_poison_obligation_cap and q/a/p=150/4/0.  Once pending is zero,
                // cross-kind live-tail churn is scheduler tail, not semantic authority.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && pendingForTerminalPin = 0
                && not parentReplayPoisonRepeatCapFreshRootWitnessGuard
                && not replayRootWriteWitnessFreshForPin
                && (replayQueue.Length > 0 || replayDriverActiveDepth > 0)
                && (parentReplayPoisonHardCapReceiptCount > 0
                    || ((parentReplayPoisonWitnessAgeMs < 0.0 || parentReplayPoisonWitnessAgeMs >= 12000.0)
                        && replayQueue.Length <= 8
                        && replayDriverActiveDepth <= 0))
                && (parentReplayPoisonSuppressedPinCount > 0
                    || parentReplayPoisonPreservedRepeatCount >= 4
                    || progressYieldCount >= 1024
                    || replayQueue.Length >= 32
                    || parentReplayPoisonReasonProbeIsCrossKindActive parentReplayPoisonReasonProbeId)
            let parentReplayPoisonSmallPendingLiveTailForceSurface =
                // MIGRATION: MIGRATION ended with p=2 while repeated hard-poison
                // receipts and small q/a live-tail churn kept the pinned dynamic/root
                // terminal wrapped as EJP0011.  A tiny pending witness is not authority
                // after hard-cap/cross-kind evidence has already told us to surface.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && pendingForTerminalPin > 0
                && pendingForTerminalPin <= 2
                && not replayRootWriteWitnessFreshForPin
                && (terminalPinHasLiveReplay || terminalPinHasWitnessQueue || replayQueue.Length > 0 || replayDriverActiveDepth > 0)
                && (replayQueue.Length <= 64
                    || progressYieldCount >= 512
                    || parentReplayPoisonSuppressedPinCount >= 4
                    || parentReplayPoisonPreservedRepeatCount >= 4
                    || parentReplayPoisonHardCapReceiptCount > 0)
                && (parentReplayPoisonHardCapReceiptCount > 0
                    || parentReplayPoisonSuppressedPinCount >= 2
                    || parentReplayPoisonPreservedRepeatCount >= 4
                    || parentReplayPoisonWitnessAgeMs >= 1500.0
                    || parentReplayPoisonReasonProbeIsCrossKindActive parentReplayPoisonReasonProbeId)
            let parentReplayPoisonHotPendingWitnessForceSurface =
                // MIGRATION: MIGRATION exposed the new suppress shape:
                // repeat=1, pending=1, q=4/a=4, fresh dynamic-join witness, but
                // progress_yield_pending was already hundreds and the terminal
                // still surfaced as EJP0021 immediately after.  A tiny hot witness
                // is scheduler tail once parent-preserved replay has already pinned
                // rank-83 poison.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && pendingForTerminalPin > 0
                && pendingForTerminalPin <= 2
                && replayRootWriteWitnessFreshForPin
                && (terminalPinHasLiveReplay || terminalPinHasWitnessQueue || replayQueue.Length > 0 || replayDriverActiveDepth > 0)
                && replayQueue.Length <= 8
                && replayDriverActiveDepth <= 4
                && progressYieldCount >= 512
                && (parentReplayPoisonReasonProbeIsStatusPreservedRepeat parentReplayPoisonReasonProbeId
                    || parentReplayPoisonPreservedRepeatCount > 0
                    || parentReplayPoisonSuppressedPinCount > 0)
            let parentReplayPoisonJpStallPendingActiveTailDefer =
                // MIGRATION: historical runtime emitted an EJP0014 jp_ivar_wait stall and immediately
                // selected rank83 parent replay poison while q/a/p stayed live. A terminal-flood or
                // hard-cap receipt is not enough authority to surface while the typed JP retry gate
                // has fresh evidence and pending+active replay still exists.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && pendingForTerminalPin > 0
                && replayDriverActiveDepth > 0
                && (replayQueue.Length <= 64 || progressYieldCount > 0)
                && not replayRootWriteWitnessFreshForPin
                && parentReplayPoisonHardCapReceiptCount > 0
                && (DiagJson.snapshotKindCount "eval_worklist_jp_stall_pinned_terminal_live_replay_retry" > 0
                    || DiagJson.snapshotKindCount "eval_worklist_jp_stall_strong_terminal_candidate" > 0)
                && (terminalPinHasLiveReplay
                    || terminalPinHasWitnessQueue
                    || replayQueue.Length > 0
                    || replayDriverActiveDepth > 0)
            let parentReplayPoisonCapBreachForceSurface =
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && not parentReplayPoisonRepeatCapFreshRootWitnessGuard
                && (parentReplayPoisonHardCapReceiptCount > 0
                    || parentReplayPoisonPendingZeroLiveTailForceSurface
                    || parentReplayPoisonSmallPendingLiveTailForceSurface
                    || parentReplayPoisonHotPendingWitnessForceSurface)
            let parentReplayPoisonFreshPendingTailHardObligationDefer =
                // MIGRATION: MIGRATION showed a hard-obligation cap inferred only
                // from cross-kind same-hot churn while pending/root evidence was live:
                // p=2, q=17/a=1, root_age=0, hard_cap_receipts=0.  That is a
                // probation/drain authority, not terminal authority.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && parentReplayPoisonCapBreachForceSurface
                && pendingForTerminalPin > 0
                && parentReplayPoisonHardCapReceiptCount = 0
                && (replayRootWriteWitnessFreshForPin
                    || isCurrentRootCompleteSite
                    || (parentReplayPoisonWitnessAgeMs >= 0.0 && parentReplayPoisonWitnessAgeMs <= 5000.0))
                && (terminalPinHasLiveReplay
                    || terminalPinHasWitnessQueue
                    || replayQueue.Length > 0
                    || replayDriverActiveDepth > 0
                    || progressYieldCount > 0)
            let parentReplayPoisonStalePendingTailHardObligationDefer =
                // MIGRATION: MIGRATION hit trace.spi:121 with pending=2, q/a=7/2, progress_yield_pending=35,
                // witness_age_ms=5798, parent_repeat_count=1 and hard_cap_receipts=0. The old cap-breach path
                // treated this as require_hard_obligation_cap_terminal only because the witness was slightly
                // older than the 5s fresh-root window. This is still a bounded live pending tail, not macro terminal authority.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && parentReplayPoisonCapBreachForceSurface
                && pendingForTerminalPin > 0
                && parentReplayPoisonHardCapReceiptCount = 0
                && not replayRootWriteWitnessFreshForPin
                && not isCurrentRootCompleteSite
                && parentReplayPoisonWitnessAgeMs >= 0.0
                && parentReplayPoisonWitnessAgeMs <= 12000.0
                && parentReplayPoisonPreservedRepeatCount < 4
                && parentReplayPoisonSuppressedPinCount = 0
                && (terminalPinHasLiveReplay
                    || terminalPinHasWitnessQueue
                    || replayQueue.Length > 0
                    || replayDriverActiveDepth > 0
                    || progressYieldCount > 0)
                && (replayQueue.Length > 0
                    || replayDriverActiveDepth > 0
                    || progressYieldCount >= 4)
            let parentReplayPoisonCycleBreakLiveTailOverride =
                // MIGRATION: keep the MIGRATION bounded drain, but do not let fresh
                // root/write-witness evidence disqualify the override.  The assessment
                // showed poison won precisely while fresh replay/root/semantic authority
                // was present, so freshness is veto evidence, not a reason to surface.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && pendingForTerminalPin > 0
                && (parentReplayPoisonCapBreachForceSurface
                    || parentReplayPoisonHardCapReceiptCount > 0
                    || parentReplayPoisonReasonProbeIsCrossKindActive parentReplayPoisonReasonProbeId)
                && (terminalPinHasLiveReplay
                    || terminalPinHasWitnessQueue
                    || replayQueue.Length > 0
                    || replayDriverActiveDepth > 0
                    || progressYieldCount > 0)
                && (replayDriverActiveDepth > 0
                    || replayQueue.Length > 0
                    || pendingForTerminalPin > 0)
                && (parentReplayPoisonWitnessAgeMs < 15000.0
                    || progressYieldCount > 0)
            let parentPoisonVsLiveTailVerdictId =
