        let private pinTerminalContract (event: string) (frame: Frame) =
            lock gate (fun () -> pinTerminalContractLocked event frame)

        let pinSemanticTerminalContractId (event: string) (kindId: EvalKind) (statusId: SemanticStatusId) (key: string) (site: string) (depth: int) (re: int) (maxRe: int) (reasonId: CompilerKernelV2.OperationalReasonId) =
            // Terminal evidence emitted outside a ReplayCell crosses one explicit typed
            // boundary.  Rendered text is reconstructed only for the legacy Frame/log
            // envelope; policy receives EvalKind, SemanticStatusId and OperationalReasonId.
            let reasonText = CompilerKernelV2.OperationalReasonIdOps.text reasonId
            match semanticTerminalContract statusId with
            | Some contract ->
                let frame =
                    { kind = kindId
                      key = ReplayKeyIdOps.create key
                      keySignals = replayFrameKeySignalsAtIngress key
                      site = CompilerIdentityKernel.WorkSiteIdOps.create site
                      depth = depth
                      re = re
                      maxRe = maxRe
                      trace = []
                      reason = reasonId
                      reasonFacts = DiagnosticClassifier.classifyFacts reasonText
                      status = frameStatusOfSemanticStatusId statusId
                      cursor = 32
                      payload = FrameLegacySemanticPayload (frameLegacySemanticPayloadId reasonText) }
                // MIGRATION: this status-only wrapper lives before pendingCount/replayQueueDepth in lexical order.
                // Use already-visible worklist facts so closure-aware terminal authority stays typed without
                // forward references.
                let statusPending = pendingCountUnlocked()
                let statusQueue = replayQueue.Length
                let statusActive = replayDriverActiveDepth
                let statusReplayKey = replayKeyOf<TerminalContractK> contract.rank terminalContractWorkShapeId (CompilerIdentityKernel.WorkSiteIdOps.create site) key
                let statusClosure = closureIdOfStatusId<TerminalContractK> (FastRuntimeFormat.format "terminal_status:%s:%s:%d" [| box (frameStatusToString frame.status); box key; box contract.rank |]) frame.status key
                let statusLivenessSnapshot =
                    { pending = statusPending
                      queueDepth = statusQueue
                      activeDepth = statusActive
                      payloadStatus = ReplayLivenessFrameStatus (frameStatusId frame)
                      hasDeferredCell = false
                      hasProgressYield = hasProgressYield()
                      kind = if statusActive > 0 then ReplayObligationActive elif statusQueue > 0 then ReplayObligationQueued elif statusPending > 0 then ReplayObligationPendingOnly else ReplayObligationQuiescent }
                let statusLivenessProof = replayLivenessProof<ParentResumeReplayK> "terminal_contract_from_status" statusLivenessSnapshot
                let statusTerminalAuthorityText =
                    TerminalContractClosureAware(
                        terminalContractClosureEvidence (closureIdDuText statusClosure),
                        terminalContractReplayEvidence (replayKeyDuText statusReplayKey),
                        terminalContractLivenessEvidence (replayLivenessProofDuText statusLivenessProof))
                    |> terminalContractAuthorityText
                pinTerminalContract event frame
                let liveReplayPolicy =
                    match liveReplayTerminalPolicyOfSemanticStatusId statusId with
                    | DeferTerminalWhileLiveReplay -> "defer_terminal_while_live_replay"
                    | SurfaceTerminalDuringLiveReplay -> "surface_terminal_during_live_replay"
                    | TerminalNotLiveReplayPolicy -> "terminal_not_live_replay_policy"
