        let resetDurableTerminalContractLedger () =
            lock gate (fun () -> durableTerminalContract <- None)

        /// peval's root retry re-runs main from scratch: terminal contracts the abandoned attempt pinned
        /// (e.g. a dynamic-join frame blocked behind a placeholder) must not abort the fresh attempt's jp_wait.
        let resetTerminalContractsForRootRetry () =
            lock gate (fun () ->
                pinnedTerminalContract <- None
                durableTerminalContract <- None)

        let clearTerminalContractIfId
            (statusId: SemanticStatusId)
            (site: CompilerIdentityKernel.WorkSiteId option)
            (key: ReplayKeyId option) =
            lock gate (fun () ->
                let matches (frame: Frame) =
                    let siteMatches =
                        match site with
                        | Some expected -> frame.site = expected
                        | None -> true
                    let keyMatches =
                        match key with
                        | Some expected -> frame.key = expected
                        | None -> true
                    frameSemanticStatusId frame = statusId
                    && siteMatches
                    && keyMatches
                let pinnedCleared =
                    match pinnedTerminalContract with
                    | Some frame when matches frame ->
                        pinnedTerminalContract <- None
                        true
                    | _ -> false
                let durableCleared =
                    match durableTerminalContract with
                    | Some frame when matches frame ->
                        durableTerminalContract <- None
                        true
                    | _ -> false
                pinnedCleared || durableCleared)


        let private compactTrace (tr: Trace) : Trace =
            let head = 16
            let tail = 16
            let n = tr.Length
            if n <= head + tail + 1 then tr
            else (tr |> List.truncate head) @ (tr |> List.rev |> List.truncate tail |> List.rev)


        let private sameCycle (a: Frame) (b: Frame) =
            a.kind = b.kind && a.key = b.key && a.site = b.site

        // MIGRATION: keep retry-drain diagnostics in lexical order.
        // MIGRATION added cross-kind terminal telemetry above the old pendingCount
        // binding; F# does not forward-declare local lets, so pendingCount must be
        // available before those helpers call it.
        let pendingCount () =
            lock gate (fun () ->
                let mutable n = 0
                let seen = System.Collections.Generic.HashSet<ReplayFramePendingIdentity>()
                let add (opt: Frame option) =
                    match opt with
                    | Some frame ->
                        let identity : ReplayFramePendingIdentity = {
                            kind = frameEvalKindId frame
                            key = frame.key
                            site = frame.site
                        }
                        if seen.Add identity then n <- n + 1
                    | None -> ()
                add frontier
                add frontierTerm
                add frontierTy
                n)

        type ParentContinuationPhase2TransitionDecisionId =
            | ParentContinuationPhase2NotCandidate
            | ParentContinuationPhase2SweepAndBridge
            | ParentContinuationPhase2NoDeferredHolesBridge

        let private parentContinuationPhase2TransitionDecisionText = function
            | ParentContinuationPhase2NotCandidate -> "not_candidate"
            | ParentContinuationPhase2SweepAndBridge -> "sweep_and_bridge"
            | ParentContinuationPhase2NoDeferredHolesBridge -> "no_deferred_holes_bridge"

        type ParentContinuationPhase2CandidateReasonId =
            | ParentContinuationPhase2Rejected
            | ParentContinuationPhase2DeferredChildIdleRootWitness
            | ParentContinuationPhase2ParentReplayCycleBreakIdleRootWitness
            | ParentContinuationPhase2DeferredTypeVarCycleBreakIdleRootWitness
            | ParentContinuationPhase2MissingAfterPrefetchClosedWorldRootWitness

        let private parentContinuationPhase2CandidateReasonText = function
            | ParentContinuationPhase2Rejected -> "rejected"
            | ParentContinuationPhase2DeferredChildIdleRootWitness -> "deferred_child_idle_root_witness"
            | ParentContinuationPhase2ParentReplayCycleBreakIdleRootWitness -> "parent_replay_cycle_break_idle_root_witness"
            | ParentContinuationPhase2DeferredTypeVarCycleBreakIdleRootWitness -> "deferred_type_var_cycle_break_idle_root_witness"
            | ParentContinuationPhase2MissingAfterPrefetchClosedWorldRootWitness -> "missing_after_prefetch_closed_world_root_witness"

        type ParentContinuationPhase2IdleSnapshotId =
            | ParentContinuationPhase2IdleSnapshotNotReady
            | ParentContinuationPhase2IdleSnapshotQueueDrainedActiveParkedRootWitness
            | ParentContinuationPhase2IdleSnapshotSingleNativeCallbackParkedRootWitness
            | ParentContinuationPhase2IdleSnapshotBoundedNativeCallbackFanoutParkedRootWitness
            | ParentContinuationPhase2IdleSnapshotQuiescentQueueFanoutParkedRootWitness

        let private parentContinuationPhase2IdleSnapshotText = function
            | ParentContinuationPhase2IdleSnapshotNotReady -> "not_ready"
            | ParentContinuationPhase2IdleSnapshotQueueDrainedActiveParkedRootWitness -> "queue_drained_active_parked_root_witness"
            | ParentContinuationPhase2IdleSnapshotSingleNativeCallbackParkedRootWitness -> "single_native_callback_parked_root_witness"
            | ParentContinuationPhase2IdleSnapshotBoundedNativeCallbackFanoutParkedRootWitness -> "bounded_native_callback_fanout_parked_root_witness"
            | ParentContinuationPhase2IdleSnapshotQuiescentQueueFanoutParkedRootWitness -> "quiescent_queue_fanout_parked_root_witness"

        type ParentContinuationPhase2StatusId =
            | ParentContinuationPhase2StatusCycleDeferred
            | ParentContinuationPhase2StatusReplayCyclePoisoned
            | ParentContinuationPhase2StatusReplayPreservedRepeatBlocked
            | ParentContinuationPhase2StatusObservedPinnedTerminalLivelock
            | ParentContinuationPhase2StatusMissingAfterPrefetchBlocked
            | ParentContinuationPhase2StatusOther

        type ParentContinuationPhase2ReasonFactId =
            | ParentContinuationPhase2ReasonMissingAfterPrefetch
            | ParentContinuationPhase2ReasonDeferredChildCell
            | ParentContinuationPhase2ReasonParentContinuationCycle
            | ParentContinuationPhase2ReasonParentContinuationReady
            | ParentContinuationPhase2ReasonCycleBreakPoison
            | ParentContinuationPhase2ReasonDeferredTypeVar
            | ParentContinuationPhase2ReasonSingleFlightCrossKindCycleBreak
            | ParentContinuationPhase2ReasonPendingMonomorphization
            | ParentContinuationPhase2ReasonPureSidecarDrain
            | ParentContinuationPhase2ReasonDynamicRecordKeyBridgeTail
            | ParentContinuationPhase2ReasonCrossKindActiveReplayDriver
            | ParentContinuationPhase2ReasonHardPoison
            | ParentContinuationPhase2ReasonTerminalPoisonCascade
            | ParentContinuationPhase2ReasonCycleBreak

        type ParentContinuationPhase2IngressEvidence = {
            status : ParentContinuationPhase2StatusId
            facts : ParentContinuationPhase2ReasonFactId list
        }

        type ParentContinuationPhase2BridgeMutationId =
            | ParentContinuationPhase2BridgeRootWitnessRecorded

        let private parentContinuationPhase2BridgeMutationText = function
            | ParentContinuationPhase2BridgeRootWitnessRecorded -> "root_witness_recorded"

        type ParentContinuationDependencyKind =
            | ParentContinuationTermDependency
            | ParentContinuationTypeDependency
            | ParentContinuationUnknownDependency

        let private parentContinuationDependencyKindFor = function
            | EvalTerm -> ParentContinuationTermDependency
            | EvalTy -> ParentContinuationTypeDependency
            | _ -> ParentContinuationUnknownDependency

        let private parentContinuationDependencyKindText = function
            | ParentContinuationTermDependency -> "term"
            | ParentContinuationTypeDependency -> "ty"
            | ParentContinuationUnknownDependency -> "unknown"

        type ParentContinuationCompletionCellId =
            | ParentContinuationReplayCell of nodeId:int

        let private parentContinuationCompletionCellText = function
            | ParentContinuationReplayCell nodeId -> "replay-cell:" + string nodeId

        type ParentContinuationMissingDependency = private {
            kind : ParentContinuationDependencyKind
            key : ReplayKeyId
            nodeId : int option
            completionCell : ParentContinuationCompletionCellId option
            site : CompilerIdentityKernel.WorkSiteId
            generation : int
            pending : int
            queueDepth : int
            activeDepth : int
            }

        type ParentContinuationClosedWorldReasonId =
            | ParentContinuationSealedEmptyFrontierWithoutPhase2Candidate

        let parentContinuationClosedWorldReasonText = function
            | ParentContinuationSealedEmptyFrontierWithoutPhase2Candidate ->
                "sealed_empty_frontier_without_phase2_candidate"

        type ParentContinuationClosedWorldProof = private {
            generation : int
            pending : int
            queueDepth : int
            activeDepth : int
            frontierCount : int
            proofReason : ParentContinuationClosedWorldReasonId
            }

        type ParentContinuationPhase2Candidate =
            | ParentContinuationPhase2Ready of Frame * int * int * int * ParentContinuationPhase2CandidateReasonId * ParentContinuationPhase2IdleSnapshotId * ParentContinuationPhase2IngressEvidence
            | ParentContinuationPhase2AwaitingDependency of ParentContinuationMissingDependency
            | ParentContinuationPhase2Exhausted of ParentContinuationClosedWorldProof
            | ParentContinuationPhase2MissingProducer of ParentContinuationMissingDependency

        type ParentContinuationIvarFillReasonId =
            | ParentContinuationQueueOnlyRecoveryNotReady
            | ParentContinuationOwnerDebtFillGateNotReady
            | ParentContinuationBigStackPhase2GateNotReady
            | ParentContinuationObservedPinnedSparseRecheckDeferred
            | ParentContinuationTyGlobalFusePhase2NotReady
            | ParentContinuationTermGlobalFusePhase2NotReady
            | ParentContinuationJpStallPreAbortException of CompilerKernelV2.OperationalReasonId
            | ParentContinuationJpStallPreAbortNotApplicable
            | ParentContinuationTypedOwnerTransactionRejected
            | ParentContinuationQueueOnlyOwnerTransactionException
            | ParentContinuationObservedPinnedOwnerTransactionException

        let parentContinuationIvarFillReasonText = function
            | ParentContinuationQueueOnlyRecoveryNotReady -> "queue_only_recovery_not_ready"
            | ParentContinuationOwnerDebtFillGateNotReady -> "owner_debt_fill_gate_not_ready"
            | ParentContinuationBigStackPhase2GateNotReady -> "bigstack_phase2_gate_not_ready"
            | ParentContinuationObservedPinnedSparseRecheckDeferred -> "observed_pinned_state_sparse_recheck_deferred"
            | ParentContinuationTyGlobalFusePhase2NotReady -> "ty_global_fuse_phase2_not_ready"
            | ParentContinuationTermGlobalFusePhase2NotReady -> "term_global_fuse_phase2_not_ready"
            | ParentContinuationJpStallPreAbortException exceptionType ->
                "jp_stall_pre_abort_exception:" + CompilerKernelV2.OperationalReasonIdOps.text exceptionType
            | ParentContinuationJpStallPreAbortNotApplicable -> "jp_stall_pre_abort_not_applicable"
            | ParentContinuationTypedOwnerTransactionRejected -> "typed_owner_transaction_rejected"
            | ParentContinuationQueueOnlyOwnerTransactionException -> "queue_only_owner_transaction_exception"
            | ParentContinuationObservedPinnedOwnerTransactionException -> "observed_pinned_owner_transaction_exception"

        type ParentContinuationIvarFillResultId =
            | ParentContinuationIvarFillPending of reason:ParentContinuationIvarFillReasonId
            | ParentContinuationIvarFillAwaitingDependency of ParentContinuationMissingDependency
            | ParentContinuationIvarFillExhausted of ParentContinuationClosedWorldProof
            | ParentContinuationIvarFillMissingProducer of ParentContinuationMissingDependency
            | ParentContinuationIvarFillRejected of reason:ParentContinuationIvarFillReasonId * ownerTransaction:DiagJson.TypedOwnerTransactionResult<DiagJson.EvalWorklistTerminalGraphKind>
            | ParentContinuationIvarFillSucceeded of
                key:ReplayKeyId
                * candidate:ParentContinuationPhase2CandidateReasonId
                * mutation:ParentContinuationPhase2BridgeMutationId
                * ownerTransaction:DiagJson.TypedOwnerTransactionReceipt<DiagJson.EvalWorklistTerminalGraphKind>

        let parentContinuationIvarFillResultText = function
            | ParentContinuationIvarFillPending reason ->
                "Pending(reason=" + parentContinuationIvarFillReasonText reason + ")"
            | ParentContinuationIvarFillAwaitingDependency dependency ->
                "AwaitingDependency(kind=" + parentContinuationDependencyKindText dependency.kind + "|key=" + ReplayKeyIdOps.text dependency.key + "|generation=" + string dependency.generation + ")"
            | ParentContinuationIvarFillExhausted proof ->
                "Exhausted(generation=" + string proof.generation + "|pending=" + string proof.pending + "|queue=" + string proof.queueDepth + "|active=" + string proof.activeDepth + "|reason=" + parentContinuationClosedWorldReasonText proof.proofReason + ")"
            | ParentContinuationIvarFillMissingProducer dependency ->
                "MissingProducer(kind=" + parentContinuationDependencyKindText dependency.kind + "|key=" + ReplayKeyIdOps.text dependency.key + "|generation=" + string dependency.generation + ")"
            | ParentContinuationIvarFillRejected(reason, ownerTransaction) ->
                "Rejected(reason=" + parentContinuationIvarFillReasonText reason
                + "|owner_transaction=" + DiagJson.typedOwnerTransactionResultText ownerTransaction + ")"
            | ParentContinuationIvarFillSucceeded(key, candidate, mutation, ownerTransaction) ->
                "Success(key=" + ReplayKeyIdOps.text key + "|candidate=" + parentContinuationPhase2CandidateReasonText candidate + "|mutation=" + parentContinuationPhase2BridgeMutationText mutation + "|owner_transaction=" + DiagJson.typedOwnerTransactionReceiptText ownerTransaction + ")"

        let parentContinuationIvarFillResultDidFill = function
            | ParentContinuationIvarFillSucceeded _ -> true
            | ParentContinuationIvarFillPending _
            | ParentContinuationIvarFillAwaitingDependency _
            | ParentContinuationIvarFillExhausted _
            | ParentContinuationIvarFillMissingProducer _
            | ParentContinuationIvarFillRejected _ -> false

        let parentContinuationIvarFillResultOwnerTransactionText = function
            | ParentContinuationIvarFillSucceeded(_, _, _, ownerTransaction) -> DiagJson.typedOwnerTransactionReceiptText ownerTransaction
            | ParentContinuationIvarFillRejected(_, ownerTransaction) -> DiagJson.typedOwnerTransactionResultText ownerTransaction
            | ParentContinuationIvarFillPending reason ->
                "owner_transaction_not_started:" + parentContinuationIvarFillReasonText reason
            | ParentContinuationIvarFillAwaitingDependency dependency -> "dependency_waiting:" + ReplayKeyIdOps.text dependency.key
            | ParentContinuationIvarFillExhausted proof -> "owner_transaction_closed_world:" + parentContinuationClosedWorldReasonText proof.proofReason
            | ParentContinuationIvarFillMissingProducer dependency -> "owner_transaction_missing_producer:" + ReplayKeyIdOps.text dependency.key

        let private parentContinuationPhase2IdleSnapshotFor pending queueDepth activeDepth =
            if pending > 0 && pending <= 3 && queueDepth <= 16 && activeDepth = 0 then
                ParentContinuationPhase2IdleSnapshotQueueDrainedActiveParkedRootWitness
            elif pending > 0 && pending <= 3 && queueDepth <= 16 && activeDepth = 1 then
                ParentContinuationPhase2IdleSnapshotSingleNativeCallbackParkedRootWitness
            elif pending > 0 && pending <= 2 && queueDepth <= 4 && activeDepth > 1 && activeDepth <= 4 then
                ParentContinuationPhase2IdleSnapshotBoundedNativeCallbackFanoutParkedRootWitness
            elif pending > 0 && pending <= 3 && queueDepth <= 16 && activeDepth > 1 && activeDepth <= 4 then
                ParentContinuationPhase2IdleSnapshotQuiescentQueueFanoutParkedRootWitness
            else
                ParentContinuationPhase2IdleSnapshotNotReady

        type PairValueExceptionHandoffDecisionId =
            | PairValueExceptionNotCandidate
            | PairValueExceptionDrainGrace
            | PairValueExceptionExplicitHandoffReady

        let pairValueExceptionHandoffDecisionText = function
            | PairValueExceptionNotCandidate -> "not_candidate"
            | PairValueExceptionDrainGrace -> "drain_grace"
            | PairValueExceptionExplicitHandoffReady -> "explicit_handoff_ready"

        let pairValueExceptionHandoffDecisionShouldHandoff = function
            | PairValueExceptionExplicitHandoffReady -> true
            | _ -> false

        let pairValueExceptionHandoffDecisionFor (statusId: SemanticStatusId) (exceptionKind: EvalReplayValueStore.EvaluatorTermExceptionKindId option) rank pending queueDepth activeDepth terminalAge =
            let isPairValueNre =
                statusId = SemanticPairValueBlocked
                && rank >= 80
                && (exceptionKind |> Option.exists EvalReplayValueStore.evaluatorTermExceptionKindIsNullReference)
            if not isPairValueNre then PairValueExceptionNotCandidate
            elif terminalAge < 1500 && (pending > 0 || queueDepth > 0 || activeDepth > 0) then PairValueExceptionDrainGrace
            else PairValueExceptionExplicitHandoffReady

        let private parentContinuationPhase2StatusIdForSemanticStatus = function
            | SemanticParentContinuationCycleDeferred -> ParentContinuationPhase2StatusCycleDeferred
            | SemanticParentReplayCycleBreakPoisoned -> ParentContinuationPhase2StatusReplayCyclePoisoned
            | SemanticParentReplayStatusPreservedRepeatBlocked -> ParentContinuationPhase2StatusReplayPreservedRepeatBlocked
            | SemanticRootCompleteStaleRetargetLiveReplayLivelockBlocked -> ParentContinuationPhase2StatusObservedPinnedTerminalLivelock
            | SemanticMissingAfterPrefetchBlocked -> ParentContinuationPhase2StatusMissingAfterPrefetchBlocked
            | _ -> ParentContinuationPhase2StatusOther

        let private parentContinuationPhase2IngressEvidenceFor (frame:Frame) (explicitFacts:ParentContinuationPhase2ReasonFactId list) =
            let statusId = frameSemanticStatusId frame
            let statusFacts =
                if statusId = SemanticMissingAfterPrefetchBlocked then
                    [ ParentContinuationPhase2ReasonMissingAfterPrefetch ]
                else []
            let reasonSignal = framePayloadReasonSignal frame.payload
            let signalFacts =
                match reasonSignal with
                | Some (FrameReasonSignalParentReplayStatusPreservedRepeat _) -> []
                | Some (FrameReasonSignalCrossKind _) ->
                    [ ParentContinuationPhase2ReasonCrossKindActiveReplayDriver ]
                | Some FrameReasonSignalMissingAfterPrefetch ->
                    [ ParentContinuationPhase2ReasonMissingAfterPrefetch ]
                | Some FrameReasonSignalOpReplayDriverNull
                | Some (FrameReasonSignalReentrantP0FailClosed _)
                | Some (FrameReasonSignalDynamicJoin _)
                | None -> []
            let legacyFrameReasonFacts =
                // Frames without a typed reason signal are diagnostic-only at this boundary.
                // They must not regain phase-2 authority by reparsing OperationalReasonId text.
                []
            {
                status = parentContinuationPhase2StatusIdForSemanticStatus statusId
                facts =
                    statusFacts
                    @ signalFacts
                    @ legacyFrameReasonFacts
                    @ explicitFacts
                    |> List.distinct
            }

        let private parentContinuationPhase2ReasonHas fact evidence =
            evidence.facts |> List.contains fact

        let private parentContinuationPhase2CandidateReasonFor
            (evidence:ParentContinuationPhase2IngressEvidence)
            pending queueDepth activeDepth =
            let idleId = parentContinuationPhase2IdleSnapshotFor pending queueDepth activeDepth
            let deferredChild =
                parentContinuationPhase2ReasonHas ParentContinuationPhase2ReasonDeferredChildCell evidence
                || parentContinuationPhase2ReasonHas ParentContinuationPhase2ReasonParentContinuationCycle evidence
            let parentReplayCycle =
                match evidence.status with
                | ParentContinuationPhase2StatusReplayCyclePoisoned -> true
                | _ -> false
            let observedPinnedTerminalLivelock =
                match evidence.status with
                | ParentContinuationPhase2StatusObservedPinnedTerminalLivelock -> true
                | _ -> false
            let missingAfterPrefetchBlocked =
                match evidence.status with
                | ParentContinuationPhase2StatusMissingAfterPrefetchBlocked -> true
                | _ -> false
            let missingAfterPrefetchReason =
                parentContinuationPhase2ReasonHas ParentContinuationPhase2ReasonMissingAfterPrefetch evidence
                && (parentContinuationPhase2ReasonHas ParentContinuationPhase2ReasonPureSidecarDrain evidence
                    || parentContinuationPhase2ReasonHas ParentContinuationPhase2ReasonTerminalPoisonCascade evidence
                    || parentContinuationPhase2ReasonHas ParentContinuationPhase2ReasonCycleBreak evidence)
            let parentReplayReason =
                parentContinuationPhase2ReasonHas ParentContinuationPhase2ReasonParentContinuationReady evidence
                || parentContinuationPhase2ReasonHas ParentContinuationPhase2ReasonCycleBreakPoison evidence
            let deferredTypeVarReason =
                parentContinuationPhase2ReasonHas ParentContinuationPhase2ReasonDeferredTypeVar evidence
                || parentContinuationPhase2ReasonHas ParentContinuationPhase2ReasonSingleFlightCrossKindCycleBreak evidence
                || parentContinuationPhase2ReasonHas ParentContinuationPhase2ReasonPendingMonomorphization evidence
            match idleId with
            | ParentContinuationPhase2IdleSnapshotNotReady -> ParentContinuationPhase2Rejected
            | ParentContinuationPhase2IdleSnapshotBoundedNativeCallbackFanoutParkedRootWitness
            | ParentContinuationPhase2IdleSnapshotQuiescentQueueFanoutParkedRootWitness ->
                ParentContinuationPhase2Rejected
            | ParentContinuationPhase2IdleSnapshotQueueDrainedActiveParkedRootWitness
            | ParentContinuationPhase2IdleSnapshotSingleNativeCallbackParkedRootWitness ->
                if missingAfterPrefetchBlocked
                   && missingAfterPrefetchReason
                   && pending = 1
                   && queueDepth = 0
                   && activeDepth = 0 then
                    ParentContinuationPhase2MissingAfterPrefetchClosedWorldRootWitness
                elif evidence.status = ParentContinuationPhase2StatusCycleDeferred && deferredChild then
                    ParentContinuationPhase2DeferredChildIdleRootWitness
                elif parentReplayCycle && parentReplayReason then
                    ParentContinuationPhase2ParentReplayCycleBreakIdleRootWitness
                elif parentReplayCycle && deferredTypeVarReason then
                    ParentContinuationPhase2DeferredTypeVarCycleBreakIdleRootWitness
                else
                    ParentContinuationPhase2Rejected

        let tryParentContinuationPhase2SynchronousTransitionId (event: string) (explicitFacts:ParentContinuationPhase2ReasonFactId list) (reasonId: CompilerKernelV2.OperationalReasonId) : ParentContinuationIvarFillResultId =
            let reason = CompilerKernelV2.OperationalReasonIdOps.text reasonId
            // DOMAIN MIGRATION : candidate selection is observational; no
            // frontier, queue, promise, or owner is mutated until the typed
            // heterogeneous owner transaction proves every required close key.
            let candidate =
                lock gate (fun () ->
                    let pending =
                        let mutable n = 0
                        let seen = System.Collections.Generic.HashSet<ReplayFramePendingIdentity>()
                        let add (opt: Frame option) =
                            match opt with
                            | Some frame ->
                                let identity : ReplayFramePendingIdentity = {
                                    kind = frameEvalKindId frame
                                    key = frame.key
                                    site = frame.site
                                }
                                if seen.Add identity then n <- n + 1
                            | None -> ()
                        add pinnedTerminalContract
                        add durableTerminalContract
                        add frontier
                        add frontierTerm
                        add frontierTy
                        n
                    let queueDepth = replayQueue.Length
                    let activeDepth = replayDriverActiveDepth
                    let pick (opt: Frame option) =
                        match opt with
                        | Some frame ->
                            let ingressEvidence =
                                parentContinuationPhase2IngressEvidenceFor frame explicitFacts
                            let candidateReasonId =
                                parentContinuationPhase2CandidateReasonFor ingressEvidence pending queueDepth activeDepth
                            let idleSnapshotId = parentContinuationPhase2IdleSnapshotFor pending queueDepth activeDepth
                            match candidateReasonId with
                            | ParentContinuationPhase2DeferredChildIdleRootWitness
                            | ParentContinuationPhase2ParentReplayCycleBreakIdleRootWitness
                            | ParentContinuationPhase2DeferredTypeVarCycleBreakIdleRootWitness
                                            | ParentContinuationPhase2MissingAfterPrefetchClosedWorldRootWitness ->
                                Some(frame, pending, queueDepth, activeDepth, candidateReasonId, idleSnapshotId, ingressEvidence)
                            | ParentContinuationPhase2Rejected -> None
                        | _ -> None
                    let candidates = [ pinnedTerminalContract; durableTerminalContract; frontier; frontierTerm; frontierTy ]
                    match candidates |> List.tryPick pick with
                    | Some ready -> ParentContinuationPhase2Ready ready
                    | None ->
                        let generation = 0
                        let frontierFrames = candidates |> List.choose id
                        match frontierFrames with
                        | frame :: _ ->
                            let nodeId = frame.semanticCell |> Option.map (fun cell -> cell.nodeId)
                            let dependency = {
                                kind = parentContinuationDependencyKindFor frame.kind
                                key = frame.key
                                nodeId = nodeId
                                completionCell = nodeId |> Option.map ParentContinuationReplayCell
                                site = frame.site
                                generation = generation
                                pending = pending
                                queueDepth = queueDepth
                                activeDepth = activeDepth
                                }
                            ParentContinuationPhase2AwaitingDependency dependency
                        | [] when pending = 0 && queueDepth = 0 && activeDepth = 0 ->
                            ParentContinuationPhase2Exhausted {
                                generation = generation
                                pending = pending
                                queueDepth = queueDepth
                                activeDepth = activeDepth
                                frontierCount = 0
                                proofReason = ParentContinuationSealedEmptyFrontierWithoutPhase2Candidate
                                }
                        | [] ->
                            ParentContinuationPhase2MissingProducer {
                                kind = ParentContinuationUnknownDependency
                                key = ReplayKeyIdOps.create "missing-phase2-producer"
                                nodeId = None
                                completionCell = None
                                site = CompilerIdentityKernel.WorkSiteIdOps.create event
                                generation = generation
                                pending = pending
                                queueDepth = queueDepth
                                activeDepth = activeDepth
                                }
                    )
            match candidate with
            | ParentContinuationPhase2AwaitingDependency dependency ->
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_parent_continuation_phase2_owned_dependency\",\"dependency_kind_du\":%s,\"key\":%s,\"node_id\":%d,\"owner_id\":%s,\"completion_cell_id\":%s,\"site\":%s,\"generation\":%d,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"authority\":\"typed_phase2_dependency\",\"next\":\"await_exact_owner_fill_ack\"}" [| box (DiagJson.esc (parentContinuationDependencyKindText dependency.kind)); box (DiagJson.esc (ReplayKeyIdOps.text dependency.key)); box (dependency.nodeId |> Option.defaultValue -1); box (DiagJson.esc ""); box (DiagJson.esc (dependency.completionCell |> Option.map parentContinuationCompletionCellText |> Option.defaultValue "")); box (DiagJson.esc (CompilerIdentityKernel.WorkSiteIdOps.text dependency.site)); box dependency.generation; box dependency.pending; box dependency.queueDepth; box dependency.activeDepth |])
                ParentContinuationIvarFillAwaitingDependency dependency
            | ParentContinuationPhase2Exhausted proof ->
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_parent_continuation_phase2_closed_world_exhausted\",\"generation\":%d,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"frontier_count\":%d,\"proof_reason_du\":%s,\"authority\":\"typed_closed_world_proof\",\"next\":\"terminalize_without_generic_redrive\"}" [| box proof.generation; box proof.pending; box proof.queueDepth; box proof.activeDepth; box proof.frontierCount; box (DiagJson.esc (parentContinuationClosedWorldReasonText proof.proofReason)) |])
                ParentContinuationIvarFillExhausted proof
            | ParentContinuationPhase2MissingProducer dependency ->
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_parent_continuation_phase2_missing_producer\",\"dependency_kind_du\":%s,\"key\":%s,\"site\":%s,\"generation\":%d,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"authority\":\"typed_missing_producer_failure\",\"next\":\"fail_local_and_cancel_bigstack_child\"}" [| box (DiagJson.esc (parentContinuationDependencyKindText dependency.kind)); box (DiagJson.esc (ReplayKeyIdOps.text dependency.key)); box (DiagJson.esc (CompilerIdentityKernel.WorkSiteIdOps.text dependency.site)); box dependency.generation; box dependency.pending; box dependency.queueDepth; box dependency.activeDepth |])
                ParentContinuationIvarFillMissingProducer dependency
            | ParentContinuationPhase2Ready(frame, pending, queueDepth, activeDepth, candidateReasonId, idleSnapshotId, ingressEvidence) ->
                let sweepReason = sprintf "%s:%s" reason (frameReasonToString frame.reason)
                let hasReason fact = parentContinuationPhase2ReasonHas fact ingressEvidence
                let sidecarLive = activeDepth > 0 || hasReason ParentContinuationPhase2ReasonPureSidecarDrain
                let dynamicBridgeLive =
                    hasReason ParentContinuationPhase2ReasonDynamicRecordKeyBridgeTail
                let poisonTailLive =
                    hasReason ParentContinuationPhase2ReasonCycleBreakPoison
                    || ingressEvidence.status = ParentContinuationPhase2StatusReplayCyclePoisoned
                let dominantNodeId =
                    match frame.semanticCell with
                    | Some cell -> string cell.nodeId
                    | None -> (frameKeyText frame)
                let topologyFacts = int64 (max activeDepth queueDepth + max 0 pending)
                let ownerTransactionRequest : DiagJson.ParentContinuationTailTransactionRequest = {
                    key = (frameKeyText frame)
                    cellId = "ivar:parent_continuation:" + (frameKeyText frame)
                    pending = int64 pending
                    queueDepth = int64 queueDepth
                    activeDepth = int64 activeDepth
                    topologyFacts = topologyFacts
                    dominantNodeId = dominantNodeId
                    sidecarLive = sidecarLive
                    dynamicBridgeLive = dynamicBridgeLive
                    bridgeDeferrals = int64 queueDepth
                    poisonTailLive = poisonTailLive
                    joinPointWaitLive = activeDepth > 0 && queueDepth <= 0
                    fillReceipt = event + ":" + parentContinuationPhase2CandidateReasonText candidateReasonId
                }
                let ownerTransactionResult =
                    DiagJson.executeParentContinuationTailCloseTransaction<DiagJson.EvalWorklistTerminalGraphKind> ownerTransactionRequest
                match ownerTransactionResult with
                | DiagJson.TypedOwnerTransactionRejected(_, transactionReason, _) ->
                    let transactionText = DiagJson.typedOwnerTransactionResultText ownerTransactionResult
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_parent_continuation_owner_transaction_rejected\",\"event\":%s,\"reason\":%s,\"candidate_reason_du\":%s,\"idle_snapshot_du\":%s,\"owner_close_transaction_du\":%s,\"owner_ledger_snapshot_du\":%s,\"open_owners_count\":%d,\"pending_snapshot\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"dominant_active_node_id\":%s,\"single_flight\":1,\"next\":\"preserve_original_graph_and_wait_for_typed_close_keys\"}" [| box (DiagJson.esc event); box (DiagJson.esc (CompilerKernelV2.OperationalReasonIdOps.text transactionReason)); box (DiagJson.esc (parentContinuationPhase2CandidateReasonText candidateReasonId)); box (DiagJson.esc (parentContinuationPhase2IdleSnapshotText idleSnapshotId)); box (DiagJson.esc transactionText); box (DiagJson.esc transactionText); box (DiagJson.typedOwnerTransactionResultOpenAfter ownerTransactionResult); box pending; box queueDepth; box activeDepth; box (DiagJson.esc dominantNodeId) |])
                    ParentContinuationIvarFillRejected(
                        ParentContinuationTypedOwnerTransactionRejected,
                        ownerTransactionResult)
                | DiagJson.TypedOwnerTransactionCommitted ownerReceipt ->
                    let patched = EvalReplayValueStore.tryPhase2SynchronousDeferredTypeVarSweep event (CompilerKernelV2.OperationalReasonIdOps.create sweepReason) 4096
                    let decisionId =
                        if patched > 0 then ParentContinuationPhase2SweepAndBridge
                        else ParentContinuationPhase2NoDeferredHolesBridge
                    let bridgeMutationId = ParentContinuationPhase2BridgeRootWitnessRecorded
                    let fillResultId = ParentContinuationIvarFillSucceeded(frame.key, candidateReasonId, bridgeMutationId, ownerReceipt)
                    let evaluatorRootEvidence =
                        "phase2_parent_continuation_root_witness|key=" + (frameKeyText frame)
                        + "|owner_transaction=" + ownerReceipt.transactionId
                        + "|open_after=" + string ownerReceipt.openAfter
                        + "|patched_holes=" + string patched
                    let evaluatorRootCommit =
                        DiagJson.commitEvaluatorRootAndReconcileTerminalFlow
                            ("phase2-parent-continuation:" + (frameKeyText frame))
                            evaluatorRootEvidence
                    let evaluatorRootReceiptId =
                        match evaluatorRootCommit with
                        | DiagJson.EvaluatorRootCommittedNow(receiptId, _, _)
                        | DiagJson.EvaluatorRootAlreadyCommitted(receiptId, _, _) -> receiptId
                        | DiagJson.EvaluatorRootCommitRejected reason -> "root-commit-rejected:" + DiagJson.evaluatorRootCommitRejectionReasonText reason
                    lock gate (fun () ->
                        let staleParentReplayTasksDropped = 0
                        let completedCell =
                            frame.semanticCell
                            |> Option.map (fun cell -> { cell with status = ReplayCellSemanticStatus SemanticRootComplete; step = cell.step + 1 })
                        let completedPayload =
                            match completedCell with
                            | Some cell -> FrameSemanticCellPayload cell
                            | None -> FrameLegacySemanticPayload(frameLegacySemanticPayloadId (sprintf "phase2_parent_continuation_root_bridge:%s" (frameKeyText frame)))
                        let completedFrame =
                            { frame with
                                status = frameStatusOfSemanticStatusId SemanticRootComplete
                                reason = frameReasonOfString (sprintf "typed_owner_transaction_committed:phase2_parent_continuation_bridge:patched_holes=%d" patched)
                                cursor = frame.cursor + 1
                                payload = completedPayload }
                        frontier <- Some completedFrame
                        if frameEvalKindId frame = EvalTerm then frontierTerm <- Some completedFrame
                        elif frameEvalKindId frame = EvalTy then frontierTy <- Some completedFrame
                        pinnedTerminalContract <- None
                        durableTerminalContract <- None
                        let witnessIdentity = FastRuntimeFormat.format "phase2-parent-bridge|%s|%s|%d" [| box (frameKeyText frame); box (frameSiteText frame); box patched |]
                        let observedAtUtc = System.DateTime.UtcNow
                        if replayRootFirstCompleteWitnessUtc = System.DateTime.MinValue then
                            replayRootFirstCompleteWitnessUtc <- observedAtUtc
                        replayRootCompleteWitnessUtc <- observedAtUtc
                        if witnessIdentity <> replayRootCompleteWitnessIdentity then
                            replayRootCompleteWitnessIdentity <- witnessIdentity
                        replayRootCompleteWitnessSummary <-
                            FastRuntimeFormat.format "typed owner transaction parent bridge identity=%s key=%s site=%s patched=%d" [| box witnessIdentity; box (frameKeyText frame); box (frameSiteText frame); box patched |]
                        progressYieldCount <- progressYieldCount + 1
                        let ownerTransactionText = DiagJson.typedOwnerTransactionReceiptText ownerReceipt
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_phase2_parent_continuation_deferred_child_cell_root_witness_bridged\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"candidate_reason_du\":%s,\"idle_snapshot_du\":%s,\"bridge_mutation_du\":%s,\"parent_continuation_ivar_fill_result_du\":%s,\"owner_close_transaction_du\":%s,\"owner_ledger_snapshot_du\":%s,\"live_graph_phase_du\":%s,\"open_owners_count\":%d,\"dynamic_record_key_bridge_tail_close_key\":%s,\"bridge_tail_remaining_owners\":%d,\"poison_cascade_chain\":\"sidecar_forgiveness->dynamic_bridge_quarantine->poison_tail_close->join_point_wait_quarantine->parent_continuation_fill\",\"status_before\":%s,\"status_after\":\"semantic_root_complete\",\"canonical_root_after_du\":\"Resolved\",\"evaluator_root_receipt_id\":%s,\"evaluator_root_commit_result_du\":%s,\"root_authority_resolve_called\":true,\"global_server_event_published\":true,\"kind2\":%s,\"site\":%s,\"key\":%s,\"patched_holes\":%d,\"stale_parent_replay_tasks_dropped\":%d,\"pending_snapshot\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"single_flight\":1,\"next\":\"root_complete_probe_or_codegen_transition\"}" [| box (DiagJson.esc event); box (DiagJson.esc sweepReason); box (DiagJson.esc (parentContinuationPhase2TransitionDecisionText decisionId)); box (DiagJson.esc (parentContinuationPhase2CandidateReasonText candidateReasonId)); box (DiagJson.esc (parentContinuationPhase2IdleSnapshotText idleSnapshotId)); box (DiagJson.esc (parentContinuationPhase2BridgeMutationText bridgeMutationId)); box (DiagJson.esc (parentContinuationIvarFillResultText fillResultId)); box (DiagJson.esc ownerTransactionText); box (DiagJson.esc ownerTransactionText); box (DiagJson.esc (DiagJson.typedOwnerTransactionResultPhaseText ownerTransactionResult)); box ownerReceipt.openAfter; box (DiagJson.esc (if dynamicBridgeLive then "close:dynamic_bridge:" + (frameKeyText frame) else "close:none")); box ownerReceipt.openAfter; box (DiagJson.esc (frameStatusToString frame.status)); box (DiagJson.esc evaluatorRootReceiptId); box (DiagJson.esc (DiagJson.evaluatorRootCommitResultText evaluatorRootCommit)); box (DiagJson.esc (evalKindToString frame.kind)); box (DiagJson.esc (frameSiteText frame)); box (DiagJson.esc (frameKeyText frame)); box patched; box staleParentReplayTasksDropped; box pending; box queueDepth; box activeDepth |])
                        fillResultId)

        let codegenJpBodyDictShouldDefer () =
            lock gate (fun () ->
                let liveFrame (opt: Frame option) =
                    match opt with
                    | Some frame ->
                        let nonCodegen =
                            match frameEvalKindId frame with
                            | EvalCodegen -> false
                            | _ -> true
                        let liveStatus =
                            match frameStatusId frame with
                            | FrameSemanticRootComplete -> true
                            | statusId -> isLiveExplicitFrameStatusId statusId
                        nonCodegen && liveStatus
                    | None -> false
                liveFrame frontier
                || liveFrame frontierTerm
                || liveFrame frontierTy
                || replayQueue.Length > 0
                || replayDriverActiveDepth > 0
                || progressYieldCount > 0)

        // MIGRATION: terminal contracts are kind-local evidence.
        // Runtime evidence exposed a stale cross-kind selection bug: retry_stop_drain
        // had a live ty semantic_root_complete frontier at apps/spiral/spiral.spi:2670,
        // but preferred an older term semantic_replay_fingerprint_repeat_blocked
        // contract from trace.spi:121. Cross-kind pins remain evidence for their
        // own parked kind slot; they must not retarget the current global fuse.
        let private frameKindCompatibleId (requestedKindId: EvalKind) (frame: Frame) =
            match frameEvalKindId frame with
            | EvalUnknown _ ->
                match framePayloadTypedCell frame.payload with
                | Some cell -> replayCellEvalKindId cell = requestedKindId
                | None -> false
            | frameKindId -> frameKindId = requestedKindId


        // MIGRATION: cross-kind pinned terminals are useful once, but repeated
        // observations are keyed by structural evidence rather than a rendered
        // concatenation of kind/status/key/reason fields.
        type CrossKindPinnedTerminalIgnoreReasonId =
            | CrossKindPinnedTerminalActiveFrameMismatch of activeKind:EvalKind * activeStatus:FrameStatusId * cleared:bool
            | CrossKindPinnedTerminalGlobalFuseMismatch of cleared:bool

        let private crossKindPinnedTerminalIgnoreReasonText = function
            | CrossKindPinnedTerminalActiveFrameMismatch(activeKind, activeStatus, cleared) ->
                FastRuntimeFormat.format "active_frame_kind=%s status=%s cleared=%b" [| box (evalKindToString activeKind); box (frameStatusToString activeStatus); box cleared |]
            | CrossKindPinnedTerminalGlobalFuseMismatch cleared ->
                sprintf "high_rank_terminal_belongs_to_other_kind cleared=%b" cleared

        [<StructuralEquality; NoComparison>]
        type CrossKindPinnedTerminalIgnoredIdentity = private {
            event : ReplayEventId
            requestedKind : EvalKind
            pinnedKind : EvalKind
            pinnedStatus : FrameStatusId
            pinnedKey : ReplayKeyId
            reason : CrossKindPinnedTerminalIgnoreReasonId
        }

        let private crossKindPinnedTerminalIgnoredSeen = System.Collections.Concurrent.ConcurrentDictionary<CrossKindPinnedTerminalIgnoredIdentity,int>()

        let private emitCrossKindPinnedTerminalIgnoredId (event: string) (requestedKind: EvalKind) (pinned: Frame) (rank: int) (reason: CrossKindPinnedTerminalIgnoreReasonId) =
            let identity : CrossKindPinnedTerminalIgnoredIdentity = {
                event = ReplayEventIdOps.create event
                requestedKind = requestedKind
                pinnedKind = pinned.kind
                pinnedStatus = pinned.status
                pinnedKey = pinned.key
                reason = reason
            }
            let repeatCount = crossKindPinnedTerminalIgnoredSeen.AddOrUpdate(identity, 1, fun _ old -> old + 1)
            if repeatCount <= 3 || repeatCount = 8 || repeatCount = 32 || repeatCount % 256 = 0 then
                let why = crossKindPinnedTerminalIgnoreReasonText reason
                DiagJson.emit (
                    FastRuntimeFormat.format """{"kind":"eval_worklist_cross_kind_pinned_terminal_ignored","event":%s,"requested_kind":%s,"pinned_kind":%s,"pinned_status":%s,"pinned_rank":%d,"pinned_site":%s,"pinned_key":%s,"reason":%s,"repeat_count":%d,"pending":%d,"single_flight":1,"next":"preserve_kind_local_frontier"}""" [| box (esc event); box (esc (evalKindToString requestedKind)); box (esc (frameKindText pinned)); box (esc (frameStatusToString pinned.status)); box rank; box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (esc why); box repeatCount; box (pendingCount()) |])


        let private clearCurrentCrossKindPinnedTerminalLocked (pinned: Frame) =
            // Clear only the active terminal selector when it is exactly the stale
            // cross-kind frame we just rejected. This does not synthesize replay
            // value, root proof, writer output, codegen result, or BuildOk.
            match pinnedTerminalContract with
            | Some p when p.kind = pinned.kind && p.key = pinned.key && p.site = pinned.site && p.status = pinned.status ->
                pinnedTerminalContract <- None
                true
            | _ -> false

        // MIGRATION: same-node replay identity deliberately ignores site/env/cursor.
        // The MIGRATION tail showed the same TJoinPoint' node reappearing through two
        // source sites while the scheduled_parent_replay payload still targeted that
        // node.  Treat this as self-poke churn, not a fresh child payload.
        let private sameReplayNode (a: ReplayCell) (b: ReplayCell) =
            a.kind = b.kind && a.shape = b.shape && a.nodeId = b.nodeId

        // MIGRATION: EJP0014 can be raised while other forced-sequential workers are
        // still converging on the real terminal contract.  MIGRATION showed a macro
        // thunk pin appearing shortly after a semantic_root_complete+pending-JP-body
        // deferral.  Wait briefly for an already-running worker to publish that pin
        // before the retry gate spends time on root-complete churn.  This is
        // diagnostic-only and fail-closed: it never marks replay complete, never
        // writes output, and only returns an existing high-rank terminal contract.
        let waitForPinnedTerminalContract (event: string) (tries: int) (sleepMs: int) =
            let maxTries = max 1 (min 256 tries)
            let delay = max 1 (min 50 sleepMs)
            match tryPinnedTerminalContract() with
            | Some pinned when terminalContractRank pinned.status >= 90 ->
                let rank = terminalContractRank pinned.status
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_wait_for_pinned_terminal_contract_observed\",\"event\":%s,\"status\":%s,\"rank\":%d,\"site\":%s,\"key\":%s,\"remaining_tries\":0,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (esc (frameStatusToString pinned.status)); box rank; box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (pendingCount()); box (esc (terminalContractNext pinned.status)) |])
                Some pinned
            | _ ->
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_wait_for_pinned_terminal_contract_no_sync_wait\",\"event\":%s,\"tries_requested\":%d,\"sleep_ms_requested\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"schedule_or_continue_fail_closed\"}" [| box (esc event); box maxTries; box delay; box (pendingCount()) |])
                None

        let private short (maxLen: int) (s: string) =
            // MIGRATION: maxLen remains as call-site documentation only.  The
            // compiler log must preserve complete JSON/string payloads; report and
            // UI tools may summarize later, but the receipt itself must not lose
            // tail evidence.
            match activeLogCompletenessPolicy with
            | FullFidelityJsonl -> if Object.ReferenceEquals(s,null) then "" else s
            | TruncatedPreview _ ->
                if Object.ReferenceEquals(s,null) then ""
                elif maxLen <= 3 then s
                elif s.Length > maxLen then s.Substring(0, maxLen - 3) + "..."
                else s

        let private formatCellPayload (cell: ReplayCell) =
            FastRuntimeFormat.format "semantic_eval_payload(kind=%s,shape=%s,node_id=%d,env_term=%d/%d,env_type=%d/%d,seq_len=%d,cse_depth=%d,trace_depth=%d,site=%s,cursor=%d,step=%d,status=%s)" [| box (replayCellKindText cell); box (replayCellShapeText cell); box cell.nodeId; box cell.envGlobalTerm; box cell.envStackTerm; box cell.envGlobalType; box cell.envStackType; box cell.seqLen; box cell.cseDepth; box cell.traceDepth; box (replayCellSiteText cell); box cell.cursor; box cell.step; box (replayCellStatusText cell.status) |]

        let private replayTaskPayloadText (task:ReplayTask) =
            match task.payload with
            | ReplayTaskSemanticCellPayload cell -> formatCellPayload cell
            | ReplayTaskLegacyTextPayload(text, _) -> text

        let private makeReplayCellTask id (key:ReplayTaskKeyId) driver (cell:ReplayCell) status : ReplayTask =
            { id = id
              key = key
              driver = driver
              payload = ReplayTaskSemanticCellPayload cell
              status = status
              legacyFacts = []
              legacyNodeIds = Set.empty }

        let private formatCell (cell: ReplayCell) =
            FastRuntimeFormat.format "semantic_eval_cell(kind=%s,shape=%s,node_id=%d,cursor=%d,step=%d,status=%s,site=%s)" [| box (replayCellKindText cell); box (replayCellShapeText cell); box cell.nodeId; box cell.cursor; box cell.step; box (replayCellStatusText cell.status); box (replayCellSiteText cell) |]

        type ParentReplayEnqueueDecisionId =
            | ParentReplayNoCell
            | ParentReplayScheduledTerm
            | ParentReplayScheduledTy
            | ParentReplayScheduledUnknownKind of CompilerKernelV2.OperationalReasonId
            | ParentReplayCoalescedExisting of driver:ReplayDriverId
            | ParentReplaySuppressedAfterTerminalRunEnd

        let parentReplayEnqueueDecisionText = function
            | ParentReplayNoCell -> "no_cell"
            | ParentReplayScheduledTerm -> "scheduled_term_parent_replay"
            | ParentReplayScheduledTy -> "scheduled_ty_parent_replay"
            | ParentReplayScheduledUnknownKind reasonId -> "scheduled_unknown_parent_replay:" + CompilerKernelV2.OperationalReasonIdOps.text reasonId
            | ParentReplayCoalescedExisting driver -> "coalesced_existing_parent_replay:" + replayDriverToString driver
            | ParentReplaySuppressedAfterTerminalRunEnd -> "suppressed_after_terminal_run_end"

        type ParentReplayPostRootGateId =
            | ParentReplayPostRootOpen
            | ParentReplayPostRootWitnessProvisional
            | ParentReplayPostRootTerminalClosed

        let parentReplayPostRootGateText = function
            | ParentReplayPostRootOpen -> "open"
            | ParentReplayPostRootWitnessProvisional -> "root_witness_provisional_replay_allowed"
            | ParentReplayPostRootTerminalClosed -> "terminal_run_end_closed"

        type ParentReplayCompositeCycleId =
            | ParentReplayApplyCycle
            | ParentReplayTypeApplyCycle
            | ParentReplayNonCompositeCycle of kind:EvalKind * shape:CompilerIdentityKernel.WorkShapeId

        let parentReplayCompositeCycleOf (cell: ReplayCell) =
            match cell.kind, replayCellShapeId cell with
            | EvalTerm, CellShapeEApply -> ParentReplayApplyCycle
            | EvalTerm, CellShapeETypeApply -> ParentReplayTypeApplyCycle
            | kind, _ -> ParentReplayNonCompositeCycle(kind, cell.shape)

        let parentReplayCompositeCycleText = function
            | ParentReplayApplyCycle -> "apply"
            | ParentReplayTypeApplyCycle -> "type_apply"
            | ParentReplayNonCompositeCycle(kind, shape) -> "other:" + evalKindToString kind + ":" + CompilerIdentityKernel.WorkShapeIdOps.text shape

        type ParentReplayKeyDedupeId =
            | ParentReplayStableKey
            | ParentReplayReplacedPriorKey

        let parentReplayKeyDedupeText = function
            | ParentReplayStableKey -> "stable_key"
            | ParentReplayReplacedPriorKey -> "replaced_prior_key"

        type ParentReplayDriverWakeDecisionId =
            | ParentReplayDriverWakeNoQueue
            | ParentReplayDriverWakeAlreadyActive
            | ParentReplayDriverWakeScheduleTick
            | ParentReplayDriverWakeSuppressQueuedFence

        let parentReplayDriverWakeDecisionText = function
            | ParentReplayDriverWakeNoQueue -> "no_queue"
            | ParentReplayDriverWakeAlreadyActive -> "already_active"
            | ParentReplayDriverWakeScheduleTick -> "schedule_tick"
            | ParentReplayDriverWakeSuppressQueuedFence -> "suppress_queued_fence"

        let private parentReplayDriverWakeDecisionFor queueDepth activeDepth fenceQueued =
            if queueDepth <= 0 then ParentReplayDriverWakeNoQueue
            elif activeDepth > 0 then ParentReplayDriverWakeAlreadyActive
            elif fenceQueued then ParentReplayDriverWakeSuppressQueuedFence
            else ParentReplayDriverWakeScheduleTick

        type DirectCellCycleBreakLeaseId =
            | DirectCellCycleBreakLeaseAcquired
            | DirectCellCycleBreakLeaseAlreadyActive
            | DirectCellCycleBreakLeaseRenewedAfterDrain
            | DirectCellCycleBreakLeaseRootProgressDefers
            | DirectCellCycleBreakLeaseExhausted

        let private directCellCycleBreakLeaseText = function
            | DirectCellCycleBreakLeaseAcquired -> "acquired"
            | DirectCellCycleBreakLeaseAlreadyActive -> "already_active"
            | DirectCellCycleBreakLeaseRenewedAfterDrain -> "renewed_after_drain"
            | DirectCellCycleBreakLeaseRootProgressDefers -> "root_progress_defers"
            | DirectCellCycleBreakLeaseExhausted -> "exhausted"

        let private directCellCycleBreakLeaseCounts =
            System.Collections.Concurrent.ConcurrentDictionary<ReplayCellIdentity,int>()

        // MIGRATION: runtime emission counters for closure-latched terminal rows.
        // DiagJson.snapshotKindCount is an observer and can be truncated/recycled; these
        // counters are the hot-path anti-spam latch for already-cleared terminal closure loops.
        let mutable private forcedOrphanTerminalAuthorityEmitCount = 0L
        let mutable private noRootBudgetBypassClosureEmitCount = 0L
        let mutable private noRootBudgetDispatchClosureEmitCount = 0L
        let mutable private parentReplayFloodCreditEmitCount = 0L

        let private terminalClosureEmitIsFull (ordinal: int64) =
            ordinal <= 2L || ordinal % 128L = 0L

        let private directCellCycleBreakLeaseKey (_event: string) (cell: ReplayCell) =
            // MIGRATION: key by stable semantic cell identity, not by wake event/status.
            // 1258 showed the same node escaping the lease through bigstack queue-fallback
            // and parent-handoff callbacks.  Status is also mutable, so including it makes
            // poison / stepper transitions look like a different hole target.
            replayCellIdentity cell

        let private directCellCycleBreakLeaseDecision (leaseKey: ReplayCellIdentity) (queueDepthAtLease: int) (activeDepthAtLease: int) (rootProgressActive: bool) =
            // MIGRATION: do not update the lease dictionary while holding the evaluator gate.
            // ConcurrentDictionary may briefly coordinate internally; that must not happen inside
            // lock gate while Hopac replay workers are parked behind the same gate.
            let leaseCount = directCellCycleBreakLeaseCounts.AddOrUpdate(leaseKey, 1, fun _ old -> old + 1)
            let drainedEnough = queueDepthAtLease <= 12 && activeDepthAtLease <= 1
            let activeTailQueueSurge =
                // MIGRATION: MIGRATION showed q≈79/a=4 repeatedly reporting
                // root_progress_defers for the same EApply direct-cell cycle.  Root
                // activity proves liveness, not cycle freedom; after one lease, a
                // large active tail must escalate to the existing exhausted->parent
                // poison path instead of suppressing the handoff.
                queueDepthAtLease >= 64 && activeDepthAtLease >= 4
            let leaseDecision =
                if leaseCount = 1 then DirectCellCycleBreakLeaseAcquired
                elif drainedEnough && leaseCount % 4 = 0 then DirectCellCycleBreakLeaseRenewedAfterDrain
                elif activeTailQueueSurge && leaseCount >= 2 then DirectCellCycleBreakLeaseExhausted
                elif leaseCount >= 4 then DirectCellCycleBreakLeaseExhausted
                elif rootProgressActive then DirectCellCycleBreakLeaseRootProgressDefers
                else DirectCellCycleBreakLeaseAlreadyActive
            leaseDecision, leaseCount

        let mutable private replayDriverTickRequestHook : (ReplayTickEventId -> ReplayTickReasonId -> bool) option = None

        type ReplayDriverTickRequestHookId =
            | ReplayDriverTickRequestNoHook
            | ReplayDriverTickRequestScheduled
            | ReplayDriverTickRequestRefused
            | ReplayDriverTickRequestFailed

        let private replayDriverTickRequestHookText = function
            | ReplayDriverTickRequestNoHook -> "no_hook"
            | ReplayDriverTickRequestScheduled -> "scheduled"
            | ReplayDriverTickRequestRefused -> "refused"
            | ReplayDriverTickRequestFailed -> "failed"

        let private replayDriverTickRequestHookScheduled = function
            | ReplayDriverTickRequestScheduled -> true
            | ReplayDriverTickRequestNoHook
            | ReplayDriverTickRequestRefused
            | ReplayDriverTickRequestFailed -> false

        let private tryRequestReplayDriverTickViaHook (eventId: ReplayTickEventId) (reasonId: ReplayTickReasonId) =
            match replayDriverTickRequestHook with
            | Some hook ->
                try
                    if hook eventId reasonId then ReplayDriverTickRequestScheduled
                    else ReplayDriverTickRequestRefused
                with _ -> ReplayDriverTickRequestFailed
            | None -> ReplayDriverTickRequestNoHook

        let private directCellCycleBreakLeaseAllowsMutation = function
            | DirectCellCycleBreakLeaseAcquired
            | DirectCellCycleBreakLeaseRenewedAfterDrain -> true
            | DirectCellCycleBreakLeaseAlreadyActive
            | DirectCellCycleBreakLeaseRootProgressDefers
            | DirectCellCycleBreakLeaseExhausted -> false

        type DirectCellCycleBreakPhysicalHandoffId =
            | DirectCellCycleBreakPhysicalHandoffNone
            | DirectCellCycleBreakPhysicalHandoffParentPoison
            | DirectCellCycleBreakPhysicalHandoffDeferredHole

        let private directCellCycleBreakPhysicalHandoffText = function
            | DirectCellCycleBreakPhysicalHandoffNone -> "none"
            | DirectCellCycleBreakPhysicalHandoffParentPoison -> "parent_poison"
            | DirectCellCycleBreakPhysicalHandoffDeferredHole -> "deferred_hole"

        let private directCellCycleBreakPhysicalHandoffReason = function
            | DirectCellCycleBreakPhysicalHandoffNone -> ReplayTickReasonDirectCellCycleBreakNoop
            | DirectCellCycleBreakPhysicalHandoffParentPoison -> ReplayTickReasonDirectCellCycleBreakParentPoisonPhysicalHandoff
            | DirectCellCycleBreakPhysicalHandoffDeferredHole -> ReplayTickReasonDirectCellCycleBreakDeferredHolePhysicalHandoff

        let private directCellCycleBreakPhysicalHandoffShouldRequest = function
            | DirectCellCycleBreakPhysicalHandoffParentPoison
            | DirectCellCycleBreakPhysicalHandoffDeferredHole -> true
            | DirectCellCycleBreakPhysicalHandoffNone -> false

        [<StructuralEquality; NoComparison>]
        type ParentReplayRoute = private {
            driver : ReplayDriverId
            scheduledDecision : ParentReplayEnqueueDecisionId
        }

        let private parentReplayRouteForParentCell (cell: ReplayCell) =
            let kind = replayCellEvalKindId cell
            match kind with
            | EvalTy ->
                { driver = TyReplayDriver
                  scheduledDecision = ParentReplayScheduledTy }
            | EvalTerm
            | EvalParentResume ->
                { driver = TermReplayDriver
                  scheduledDecision = ParentReplayScheduledTerm }
            | EvalDynamicJoin
            | EvalData
            | EvalCodegen ->
                { driver = TermReplayDriver
                  scheduledDecision = ParentReplayScheduledUnknownKind(CompilerKernelV2.OperationalReasonIdOps.create (evalKindToString kind)) }
            | EvalUnknown reasonId ->
                { driver = TermReplayDriver
                  scheduledDecision = ParentReplayScheduledUnknownKind reasonId }

        let mutable private postRootParentReplaySuppressionCount = 0L

        let private postRootParentReplaySuppressionReadyLocked () =
            parentCacheHandoffBuildAdmission = ParentCacheHandoffClosedAfterRootWitness
            && replayRootFirstCompleteWitnessUtc <> System.DateTime.MinValue
            && (System.DateTime.UtcNow - replayRootFirstCompleteWitnessUtc).TotalMilliseconds >= replayRootResidualTailQuarantineAgeMs

        let private parentReplaySuppressionMilestone ordinal =
            ordinal <= 3L
            || (ordinal > 0L && (ordinal &&& (ordinal - 1L)) = 0L)
            || ordinal % 256L = 0L

        let private scheduleParentReplayLocked (event: string) (reasonId: OperationalReasonId) (cell: ReplayCell) =
            let route = parentReplayRouteForParentCell cell
            let driverText = replayDriverToString route.driver
            let reasonText = OperationalReasonIdOps.text reasonId
            let reasonKey = if System.String.IsNullOrWhiteSpace reasonText then "parent_continuation" else reasonText.Replace(" ", "_")
            let rootWitnessMature = postRootParentReplaySuppressionReadyLocked()
            let postRootGate =
                if rootWitnessMature && DiagJson.terminalFlowRunEndEmittedNow() then ParentReplayPostRootTerminalClosed
                elif rootWitnessMature then ParentReplayPostRootWitnessProvisional
                else ParentReplayPostRootOpen
            let suppressAfterRoot =
                match postRootGate with
                | ParentReplayPostRootTerminalClosed -> true
                | ParentReplayPostRootOpen
                | ParentReplayPostRootWitnessProvisional -> false
            let resumeKey = FastRuntimeFormat.format "scheduled_parent_replay|%s|%d|%s|%s" [| box (replayCellKindText cell); box cell.nodeId; box (replayCellShapeText cell); box (replayCellSiteText cell) |]
            let resumeTaskKey = ReplayTaskKeyIdOps.createParent cell.nodeId cell.kind resumeKey
            let replacedPrior = replayQueue |> List.exists (fun t -> t.key = resumeTaskKey)
            let decision =
                if suppressAfterRoot then ParentReplaySuppressedAfterTerminalRunEnd
                elif replacedPrior then ParentReplayCoalescedExisting route.driver
                else route.scheduledDecision
            let dedupeId = if replacedPrior then ParentReplayReplacedPriorKey else ParentReplayStableKey
            if not replacedPrior && not suppressAfterRoot then
                replaySeq <- replaySeq + 1L
                let resumeTask = makeReplayCellTask replaySeq resumeTaskKey route.driver cell ReplayTaskScheduledParentReplay
                replayScheduledKey <- Some resumeTaskKey
                replayQueue <- resumeTask :: replayQueue
                replayTaskSemanticAdmit resumeTask
                noteProgressYieldLocked ()
            if suppressAfterRoot then postRootParentReplaySuppressionCount <- postRootParentReplaySuppressionCount + 1L
            let suppressionOrdinal = postRootParentReplaySuppressionCount
            if not suppressAfterRoot || parentReplaySuppressionMilestone suppressionOrdinal then
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_parent_replay_key_dedupe\",\"event\":%s,\"decision_du\":%s,\"dedupe_du\":%s,\"post_root_gate_du\":%s,\"driver\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"reason\":%s,\"queue_depth\":%d,\"inserted\":%b,\"post_root_suppression_count\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (esc (parentReplayEnqueueDecisionText decision)); box (esc (parentReplayKeyDedupeText dedupeId)); box (esc (parentReplayPostRootGateText postRootGate)); box (esc driverText); box (esc (evalKindToString cell.kind)); box (esc (replayCellShapeText cell)); box cell.nodeId; box (esc reasonKey); box replayQueue.Length; box (not replacedPrior && not suppressAfterRoot); box suppressionOrdinal; box (esc (if suppressAfterRoot then "retain_observation_after_terminal_run_end" elif replacedPrior then "await_existing_parent_replay" else "resume_parent_replay_driver")) |])
            decision

        let private replayCellFromParentCacheHandoff (req: EvalReplayValueStore.ParentCacheHandoffRequest) =
            let parentKindText = EvalReplayValueStore.evaluatorNodeKindText req.cont.parentKind
            let roleText = EvalReplayValueStore.evaluatorDependencyRoleText req.cont.role
            { kind = evalKindForEvaluatorNodeKind req.cont.parentKind
              shape = req.cont.parentShape
              nodeId = req.cont.parentNodeId
              envGlobalTerm = 0
              envStackTerm = 0
              envGlobalType = 0
              envStackType = 0
              seqLen = 0
              cseDepth = 0
              traceDepth = 0
              site = CompilerIdentityKernel.WorkSiteIdOps.create (FastRuntimeFormat.format "cache_handoff@parent:%s:%s:%s" [| box parentKindText; box (EvalReplayValueStore.workShapeIdText req.cont.parentShape); box roleText |])
              cursor = 0
              step = 0
              status = ReplayCellReadyStatus ReplayCellReadyParentContinuation }

        let private drainParentCacheHandoffsLocked (event: string) (maxItems: int) =
            let limit = max 1 (min 8 maxItems)
            let mutable drained = 0
            let mutable keepGoing = true
            while keepGoing && drained < limit do
                match EvalReplayValueStore.tryTakeParentCacheHandoff() with
                | Some req ->
                    let parentCell = replayCellFromParentCacheHandoff req
                    let decision = scheduleParentReplayLocked event (OperationalReasonIdOps.create "cache_write_parent_handoff") parentCell
                    let parentKindText = EvalReplayValueStore.evaluatorNodeKindText req.cont.parentKind
                    let roleText = EvalReplayValueStore.evaluatorDependencyRoleText req.cont.role
                    let parentHandoffIdentity : ParentCacheHandoffWakeIdentity = {
                        parentKind = req.cont.parentKind
                        parentShape = req.cont.parentShape
                        parentNodeId = req.cont.parentNodeId
                        childNodeId = req.childNodeId
                        role = req.cont.role
                    }
                    let parentHandoffProofKey = FastRuntimeFormat.format "%s|%s|parent:%d|child:%d|role:%s" [| box parentKindText; box (EvalReplayValueStore.workShapeIdText req.cont.parentShape); box req.cont.parentNodeId; box req.childNodeId; box roleText |]
                    let parentHandoffProofTuple = proofTupleForParentCacheHandoffWake parentHandoffProofKey
                    // Do not execute a renderer for side effects.  The compact
                    // receipt below carries the required proof evidence.
                    let parentHandoffWakeAttempt = noteParentCacheHandoffWakeAttempt parentHandoffIdentity
                    let parentHandoffProofCompactText =
                        "PendingGraphProofTuple(witness=" + terminalWitnessKindText parentHandoffProofTuple.witness.kind
                        + "|ivar=" + nativeHopacIvarRegistryText parentHandoffProofTuple.witness.ivar
                        + "|commit=" + terminalCommitClassText parentHandoffProofTuple.commitClass
                        + "|complete=" + string (pendingGraphProofTupleComplete parentHandoffProofTuple)
                        + "|shadow_timeout_ms=" + string parentHandoffProofTuple.shadowTimeoutMs + ")"
                    drained <- drained + 1
                    noteProgressYieldLocked ()
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_cache_write_parent_handoff_enqueued\",\"event\":%s,\"child_kind_du\":%s,\"child_node_id\":%d,\"decision_du\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"role\":%s,\"queue_depth\":%d,\"pending\":%d,\"wake_attempt\":%d,\"materialized_terminal_payload_du\":%s,\"pending_graph_shard_state\":%s,\"pending_graph_proof_compact_du\":%s,\"jsonl_compaction_du\":\"ParentCacheHandoffWakeCompact|full_proof_fields_suppressed\",\"single_flight\":1,\"next\":\"schedule_parent_cache_handoff_replay_continuation_immediately\"}" [| box (esc event); box (esc (EvalReplayValueStore.parentCacheHandoffKindText req.childKindId)); box req.childNodeId; box (esc (parentReplayEnqueueDecisionText decision)); box (esc parentKindText); box (esc (EvalReplayValueStore.workShapeIdText req.cont.parentShape)); box req.cont.parentNodeId; box (esc roleText); box replayQueue.Length; box (pendingCount()); box parentHandoffWakeAttempt; box (esc (materializedTerminalOutcomeText MaterializedTerminalParentCacheHandoffWake)); box (esc (typedTerminalPayloadText (parentCacheHandoffWakeTypedTerminalPayload parentHandoffProofKey))); box (esc parentHandoffProofCompactText) |])
                | None -> keepGoing <- false
            drained

        // MIGRATION: once a real build has produced its root-complete witness,
        // parent cache commits are observations only.  They may not recreate
        // executable parent continuations behind the terminal frontier.
        do EvalReplayValueStore.installParentCacheHandoffAdmission (fun () ->
            lock gate (fun () ->
                match parentCacheHandoffBuildAdmission with
                | ParentCacheHandoffOpenForBuild -> true
                | ParentCacheHandoffClosedAfterRootWitness -> false))

        do EvalReplayValueStore.installParentCacheHandoffWake (fun () ->
            try
                // MIGRATION: this is the concrete parent wakeup the assessment
                // demanded.  A child cache commit now immediately drains the
                // handoff queue into replayQueue after the cache write, instead
                // of waiting for passive join_wait/prefetch polling.
                lock gate (fun () -> drainParentCacheHandoffsLocked "cache_write_parent_handoff_wake_callback" 8 |> ignore)
            with _ -> ())

        // MIGRATION: active structural cycle breaker.  When the global-fuse frontier
        // is a tiny pending/queued set backed by both term and ty hot-frontier
        // pressure, waiting for another replay drip only preserves the cross-kind
        // standoff.  Inject a deferred type hole into the ty side and explicitly
        // enqueue the opposite parent cell so the term side can collapse now; the
        // hole remains visible in PendingMonomorphizationQueue for later unification.
        type DeferredTypeVarCycleBreakDecisionId =
            | DeferredTypeVarCycleBreakNoCrossKind
            | DeferredTypeVarCycleBreakInjectedTy
            | DeferredTypeVarCycleBreakFallbackInjectedTerm
            | DeferredTypeVarCycleBreakAlreadyHadHoleButParentWoken

        let private deferredTypeVarCycleBreakDecisionText = function
            | DeferredTypeVarCycleBreakNoCrossKind -> "no_cross_kind"
            | DeferredTypeVarCycleBreakInjectedTy -> "injected_ty"
            | DeferredTypeVarCycleBreakFallbackInjectedTerm -> "fallback_injected_term"
            | DeferredTypeVarCycleBreakAlreadyHadHoleButParentWoken -> "already_had_hole_but_parent_woken"

        let tryForceDeferredTypeVarCycleBreakId (event: string) (reasonId: CompilerKernelV2.OperationalReasonId) =
            let reason = CompilerKernelV2.OperationalReasonIdOps.text reasonId
            lock gate (fun () ->
                let frontierFrames = [ frontier; frontierTerm; frontierTy ] |> List.choose (fun x -> x)
                let frontierCells = frontierFrames |> List.choose (fun frame -> frame.semanticCell)
                let tyCellOpt = frontierCells |> List.tryFind (fun cell -> replayCellEvalKindId cell = EvalTy)
                let termCellOpt = frontierCells |> List.tryFind (fun cell -> replayCellEvalKindId cell = EvalTerm)
                let fallbackTermCellOpt =
                    match termCellOpt with
                    | Some _ -> termCellOpt
                    | None ->
                        frontierCells
                        |> List.tryFind (fun cell ->
                            match replayCellEvalKindId cell with
                            | EvalTerm -> true
                            | _ -> replayCellShapeId cell = CellShapeETypeApply || replayCellShapeId cell = CellShapeEApply)
                let liveReplayWindow =
                    // MIGRATION: this is intentionally broader than the 1233 window.
                    // The manual interrupt tail had pending=2 queue=0 active=4; refusing
                    // to synthesize a hole there just leaves the four workers asleep.
                    pendingCount() <= 32
                    && replayQueue.Length <= 256
                    && replayDriverActiveDepth <= 8
                let scheduleParents decision (termCellOpt: ReplayCell option) (tyCellOpt: ReplayCell option) injected =
                    let mutable scheduled = 0
                    let mutable lastParentDecision = ParentReplayNoCell
                    match termCellOpt with
                    | Some termCell ->
                        lastParentDecision <- scheduleParentReplayLocked event (OperationalReasonIdOps.create "deferred_type_var_cycle_break_parent_term") termCell
                        scheduled <- scheduled + 1
                    | None -> ()
                    match tyCellOpt with
                    | Some tyCell ->
                        lastParentDecision <- scheduleParentReplayLocked event (OperationalReasonIdOps.create "deferred_type_var_cycle_break_parent_ty") tyCell
                        scheduled <- scheduled + 1
                    | None -> ()
                    if injected || scheduled > 0 then
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_deferred_type_var_cycle_break_scheduled\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"parent_enqueue_du\":%s,\"scheduled_parents\":%d,\"injected\":%b,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending_monomorphization_queue\":%d,\"policy\":\"deferred_unification_break_fills_hole_and_wakes_parent_after_cycle_break\",\"single_flight\":1,\"next\":\"resume_parent_with_deferred_type_hole\"}" [| box (esc event); box (esc reason); box (esc (deferredTypeVarCycleBreakDecisionText decision)); box (esc (parentReplayEnqueueDecisionText lastParentDecision)); box scheduled; box injected; box (pendingCount()); box replayQueue.Length; box replayDriverActiveDepth; box (EvalReplayValueStore.pendingMonomorphizationQueueDepth()) |])
                        true
                    else false
                if not liveReplayWindow then false
                else
                    match tyCellOpt, fallbackTermCellOpt with
                    | Some tyCell, Some termCell ->
                        let injected =
                            EvalReplayValueStore.putDeferredTypeVar
                                tyCell.nodeId
                                EvalReplayValueStore.PendingMonoCrossKindCycle
                        let decision = if injected then DeferredTypeVarCycleBreakInjectedTy else DeferredTypeVarCycleBreakAlreadyHadHoleButParentWoken
                        scheduleParents decision (Some termCell) (Some tyCell) injected
                    | None, Some termCell ->
                        // Destructive fallback requested by the assessment: when the ty
                        // side exists only as a blocked frame/payloadless key, inject a
                        // visible hole at the term cell identity too, then wake that parent.
                        // It is a cycle-breaking placeholder, not semantic success.
                        let injected =
                            EvalReplayValueStore.putDeferredTypeVar
                                termCell.nodeId
                                EvalReplayValueStore.PendingMonoCrossKindCycle
                        let decision = if injected then DeferredTypeVarCycleBreakFallbackInjectedTerm else DeferredTypeVarCycleBreakAlreadyHadHoleButParentWoken
                        scheduleParents decision (Some termCell) None injected
                    | Some tyCell, None ->
                        let injected =
                            EvalReplayValueStore.putDeferredTypeVar
                                tyCell.nodeId
                                EvalReplayValueStore.PendingMonoCrossKindCycle
                        let decision = if injected then DeferredTypeVarCycleBreakInjectedTy else DeferredTypeVarCycleBreakAlreadyHadHoleButParentWoken
                        scheduleParents decision None (Some tyCell) injected
                    | None, None -> false)

        let tryForceDeferredTypeVarCycleBreakForCell (eventId: ReplayTickEventId) (reasonId: CompilerKernelV2.OperationalReasonId) (cell: ReplayCell) =
            let event = replayTickEventToString eventId
            let reason = CompilerKernelV2.OperationalReasonIdOps.text reasonId
            let leaseKey = directCellCycleBreakLeaseKey event cell
            let queueDepthAtLease = try replayQueue.Length with _ -> -1
            let activeDepthAtLease = try replayDriverActiveDepth with _ -> -1
            let rootProgressActive =
                try
                    // MIGRATION: root progress can defer a duplicate direct-cell
                    // mutation only while the queue is small enough to prove real
                    // drain.  At q>=64/a>=4 the same signal becomes evidence for
                    // active-tail poison rather than a reason to suppress it.
                    DiagJson.snapshotKindCount "eval_worklist_root_complete_replay_progress_marked" > 0
                    && queueDepthAtLease <= 63
                with _ -> false
            let leaseDecisionId, leaseCount =
                directCellCycleBreakLeaseDecision leaseKey queueDepthAtLease activeDepthAtLease rootProgressActive
            let mutable physicalHandoffId = DirectCellCycleBreakPhysicalHandoffNone
            let result =
                lock gate (fun () ->
                    if not (directCellCycleBreakLeaseAllowsMutation leaseDecisionId) then
                        let exhausted = leaseDecisionId = DirectCellCycleBreakLeaseExhausted
                        let poisonedParentEnqueue =
                            if exhausted then
                                let poisonedCell = { cell with status = ReplayCellSemanticStatus SemanticParentReplayCycleBreakPoisoned }
                                let parentDecision = scheduleParentReplayLocked event (OperationalReasonIdOps.create "deferred_type_var_cycle_break_lease_exhausted_poison") poisonedCell
                                physicalHandoffId <- DirectCellCycleBreakPhysicalHandoffParentPoison
                                let poisonMsg =
                                    sprintf
                                        ("""{"kind":"eval_worklist_deferred_type_var_direct_cell_cycle_break_exhausted_poison","event":%s,"reason":%s,"lease_decision_du":%s,"lease_count":%d,"lease_key":%s,"physical_handoff_du":%s,"parent_enqueue_du":%s,"cell_kind":%s,"cell_shape":%s,"cell_node_id":%d,"pending":%d,"queue_depth":%d,"active_depth":%d,"policy":"bounded_repeated_cycle_break_escalates_to_typed_parent_poison_and_requests_physical_replay_drain","single_flight":1,"next":"execute_parent_cycle_break_poison_inline_callback_and_wake_native_driver"}""")
                                        (esc event) (esc reason) (esc (directCellCycleBreakLeaseText leaseDecisionId)) leaseCount (esc (replayCellIdentityText leaseKey)) (esc (directCellCycleBreakPhysicalHandoffText physicalHandoffId)) (esc (parentReplayEnqueueDecisionText parentDecision)) (esc (evalKindToString cell.kind)) (esc (replayCellShapeText cell)) cell.nodeId (pendingCount()) replayQueue.Length replayDriverActiveDepth
                                DiagJson.emit poisonMsg
                                true
                            else false
                        let suppressedMsg =
                            sprintf
                                ("""{"kind":"eval_worklist_deferred_type_var_direct_cell_cycle_break_suppressed","event":%s,"reason":%s,"lease_decision_du":%s,"lease_count":%d,"lease_key":%s,"physical_handoff_du":%s,"cell_kind":%s,"cell_shape":%s,"cell_node_id":%d,"pending":%d,"queue_depth":%d,"active_depth":%d,"lease_queue_depth":%d,"lease_active_depth":%d,"poison_parent_enqueued":%b,"policy":"same_cell_cycle_break_hole_is_leased_without_holding_gate_for_dictionary_update","single_flight":1,"next":"continue_replay_without_duplicate_hole"}""")
                                (esc event) (esc reason) (esc (directCellCycleBreakLeaseText leaseDecisionId)) leaseCount (esc (replayCellIdentityText leaseKey)) (esc (directCellCycleBreakPhysicalHandoffText physicalHandoffId)) (esc (evalKindToString cell.kind)) (esc (replayCellShapeText cell)) cell.nodeId (pendingCount()) replayQueue.Length replayDriverActiveDepth queueDepthAtLease activeDepthAtLease poisonedParentEnqueue
                        DiagJson.emit suppressedMsg
                        poisonedParentEnqueue
                    else
                        let injected =
                            EvalReplayValueStore.putDeferredTypeVar
                                cell.nodeId
                                EvalReplayValueStore.PendingMonoChildCycle
                        let decision = if injected then DeferredTypeVarCycleBreakFallbackInjectedTerm else DeferredTypeVarCycleBreakAlreadyHadHoleButParentWoken
                        let parentDecision = scheduleParentReplayLocked event (OperationalReasonIdOps.create "deferred_type_var_cycle_break_direct_cell") cell
                        physicalHandoffId <- DirectCellCycleBreakPhysicalHandoffDeferredHole
                        let cycleBreakMsg =
                            sprintf
                                ("""{"kind":"eval_worklist_deferred_type_var_direct_cell_cycle_break","event":%s,"reason":%s,"decision_du":%s,"lease_decision_du":%s,"lease_count":%d,"lease_key":%s,"physical_handoff_du":%s,"parent_enqueue_du":%s,"cell_kind":%s,"cell_shape":%s,"cell_node_id":%d,"injected":%b,"pending":%d,"queue_depth":%d,"active_depth":%d,"lease_queue_depth":%d,"lease_active_depth":%d,"policy":"direct_cell_fallback_fills_hole_once_per_lease_and_reenqueues_parent_with_physical_tick","single_flight":1,"next":"resume_parent_with_deferred_type_hole"}""")
                                (esc event) (esc reason) (esc (deferredTypeVarCycleBreakDecisionText decision)) (esc (directCellCycleBreakLeaseText leaseDecisionId)) leaseCount (esc (replayCellIdentityText leaseKey)) (esc (directCellCycleBreakPhysicalHandoffText physicalHandoffId)) (esc (parentReplayEnqueueDecisionText parentDecision)) (esc (evalKindToString cell.kind)) (esc (replayCellShapeText cell)) cell.nodeId injected (pendingCount()) replayQueue.Length replayDriverActiveDepth queueDepthAtLease activeDepthAtLease
                        DiagJson.emit cycleBreakMsg
                        true)
            if directCellCycleBreakPhysicalHandoffShouldRequest physicalHandoffId then
                let physicalReason = directCellCycleBreakPhysicalHandoffReason physicalHandoffId
                let tickRequestId = tryRequestReplayDriverTickViaHook eventId physicalReason
                let scheduled = replayDriverTickRequestHookScheduled tickRequestId
                let handoffMsg =
                    sprintf
                        ("""{"kind":"eval_worklist_deferred_type_var_direct_cell_physical_handoff_requested","event":%s,"reason":%s,"lease_decision_du":%s,"lease_count":%d,"lease_key":%s,"physical_handoff_du":%s,"replay_tick_request_du":%s,"scheduled_async":%b,"policy":"cycle_break_and_poison_handoffs_request_a_driver_tick_after_parent_enqueue","single_flight":1,"next":"hopac_replay_driver_job_or_existing_drain"}""")
                        (esc event) (esc reason) (esc (directCellCycleBreakLeaseText leaseDecisionId)) leaseCount (esc (replayCellIdentityText leaseKey)) (esc (directCellCycleBreakPhysicalHandoffText physicalHandoffId)) (esc (replayDriverTickRequestHookText tickRequestId)) scheduled
                DiagJson.emit handoffMsg
            result

        let private semanticCellSiteIdentity (kind: EvalKind) (site: CompilerIdentityKernel.WorkSiteId) : SemanticCellSiteIdentity =
            { kind = kind
              site = site }

        let private rememberSemanticCell (cell: ReplayCell) =
            try
                if not (String.IsNullOrWhiteSpace (evalKindToString cell.kind)) && not (String.IsNullOrWhiteSpace (replayCellSiteText cell)) then
                    semanticCellsByKindSite.[semanticCellSiteIdentity cell.kind cell.site] <- cell
            with _ -> ()

        let private trySemanticCellForFrame (frame: Frame) : ReplayCell option =
            try
                let mutable cell = Unchecked.defaultof<ReplayCell>
                if semanticCellsByKindSite.TryGetValue(semanticCellSiteIdentity frame.kind frame.site, &cell) then Some cell
                else None
            with _ -> None

        // MIGRATION: synthetic frame-derived parent edges are now classified by a
        // small DU before mutation.  The 1676 run showed useful native wake deltas,
        // but the final tail was still spammed by TFun/TB ty re-entry prefetch rows.
        // Treat that pair as a typed Hopac topology hygiene decision, not a stringly
        // scheduler hint.
        type FrameDerivedParentEdgeSuppressionId =
            | FrameDerivedParentEdgeAllowed
            | FrameDerivedParentEdgeSameNodeParentReplayProtected
            | FrameDerivedParentEdgeActiveReplayCellProtected
            | FrameDerivedParentEdgeStaleRootRetarget
            | FrameDerivedParentEdgeTypedTyPingPong

        let private frameDerivedParentEdgeSuppressionText = function
            | FrameDerivedParentEdgeAllowed -> "frame_parent_edge_allowed"
            | FrameDerivedParentEdgeSameNodeParentReplayProtected -> "same_node_parent_replay_protected"
            | FrameDerivedParentEdgeActiveReplayCellProtected -> "active_replay_cell_protected"
            | FrameDerivedParentEdgeStaleRootRetarget -> "stale_root_retarget"
            | FrameDerivedParentEdgeTypedTyPingPong -> "typed_ty_pingpong_synthetic_parent_edge_suppressed"

        let private frameDerivedParentEdgeSuppresses = function
            | FrameDerivedParentEdgeAllowed -> false
            | _ -> true

        // MIGRATION: scheduling the same child identity again and again is now treated
        // as a typed terminal obligation, not as useful replay progress.  The key
        // intentionally ignores step/cursor because MIGRATION's watchdog gap changed
        // those counters while returning to the same child obligation.
        type ReplayChildScheduleRoleId =
            | ReplayChildScheduleApplyChildren of CompilerKernelV2.OperationalReasonId
            | ReplayChildScheduleTypeApplyArg of CompilerKernelV2.OperationalReasonId
            | ReplayChildScheduleTypeFunChild of CompilerKernelV2.OperationalReasonId
            | ReplayChildScheduleIfBranch of CompilerKernelV2.OperationalReasonId
            | ReplayChildScheduleSynthetic of CompilerKernelV2.OperationalReasonId
            | ReplayChildScheduleUnknown of CompilerKernelV2.OperationalReasonId

        let private replayChildScheduleRoleForChildRole role =
            let reasonId = CompilerKernelV2.OperationalReasonIdOps.create (replayChildRoleToString role)
            match role with
            | ApplyHeadChild
            | ApplyArgChild -> ReplayChildScheduleApplyChildren reasonId
            | TypeApplyTypeArgChild
            | TypeApplyFunctionChild -> ReplayChildScheduleTypeApplyArg reasonId
            | TFunArgChild
            | TFunBodyChild -> ReplayChildScheduleTypeFunChild reasonId
            | other -> ReplayChildScheduleUnknown (CompilerKernelV2.OperationalReasonIdOps.create (replayChildRoleToString other))

        let private replayChildScheduleRoleText = function
            | ReplayChildScheduleApplyChildren reasonId
            | ReplayChildScheduleTypeApplyArg reasonId
            | ReplayChildScheduleTypeFunChild reasonId
            | ReplayChildScheduleIfBranch reasonId
            | ReplayChildScheduleSynthetic reasonId
            | ReplayChildScheduleUnknown reasonId -> CompilerKernelV2.OperationalReasonIdOps.text reasonId

        [<StructuralEquality; NoComparison>]
        type ReplayChildScheduleIdentity = private {
            role : ReplayChildScheduleRoleId
            cell : ReplayCellIdentity
        }

        let private replayChildScheduleIdentityForRole roleId (cell: ReplayCell) : ReplayChildScheduleIdentity =
            { role = roleId
              cell = replayCellIdentity cell }

        let private replayChildScheduleIdentityText (identity: ReplayChildScheduleIdentity) =
            sprintf "%s|%s"
                (replayChildScheduleRoleText identity.role)
                (replayCellIdentityText identity.cell)

        let private replayChildScheduleRepeats = System.Collections.Generic.Dictionary<ReplayChildScheduleIdentity,int>()


        let private noteReplayChildSchedule (role: ReplayChildRoleId) (cell: ReplayCell) =
            let roleId = replayChildScheduleRoleForChildRole role
            let identity = replayChildScheduleIdentityForRole roleId cell
            let key = replayChildScheduleIdentityText identity
            let count =
                lock gate (fun () ->
                    let mutable prior = 0
                    let nextCount = if replayChildScheduleRepeats.TryGetValue(identity, &prior) then prior + 1 else 1
                    replayChildScheduleRepeats.[identity] <- nextCount
                    nextCount)
            count, key

        // MIGRATION: pin terminal replay contracts at the emission site, not only
        // when retry-drain later peeks the canonical frontier.  MIGRATION showed the
        // earlier literal/macro terminal receipts could be shadowed by a downstream
        // let-success continuation before pinTerminalContract saw them.
        let private pinTerminalCellCore (event: string) (reasonId: CompilerKernelV2.OperationalReasonId) (reasonSignal: FrameReasonSignalId option) (cell: ReplayCell) =
            let reason = CompilerKernelV2.OperationalReasonIdOps.text reasonId
            let statusId = cellSemanticStatusId cell
            let effectiveReasonSignal =
                match reasonSignal, statusId with
                | Some signal, _ -> Some signal
                | None, SemanticMissingAfterPrefetchBlocked -> Some FrameReasonSignalMissingAfterPrefetch
                | None, _ -> None
            let status = semanticStatusToString statusId
            if isTerminalContractStatusId statusId then
                let frameKey = FastRuntimeFormat.format "%s:%s#%d" [| box (replayCellKindText cell); box (replayCellSiteText cell); box cell.nodeId |]
                let frame =
                    { kind = cell.kind
                      key = ReplayKeyIdOps.create frameKey
                      keySignals = replayFrameKeySignalsAtIngress frameKey
                      site = cell.site
                      depth = cell.traceDepth
                      re = 0
                      maxRe = 0
                      trace = []
                      reason = reasonId
                      reasonFacts = DiagnosticClassifier.classifyFacts reason
                      status = frameStatusOfSemanticStatusId statusId
                      cursor = cell.cursor
                      payload =
                          match effectiveReasonSignal with
                          | Some signal -> FrameSemanticCellPayloadWithReasonSignal(cell, signal)
                          | None -> FrameSemanticCellPayload cell }
                if liveReplayTerminalSuppressedId statusId then
                    // MIGRATION: pinTerminalCell is above replayQueueDepth in declaration order;
                    // use the local queue under the gate instead of calling the later public helper.
                    let queueDepth = lock gate (fun () -> replayQueue.Length)
                    let activeDepth = replayDriverActiveDepthValue()
                    let progressYieldPending = hasProgressYield()
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_cell_emission_suppressed_after_live_replay\",\"event\":%s,\"status\":%s,\"rank\":%d,\"node_id\":%d,\"shape\":%s,\"site\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"progress_yield_pending\":%b,\"policy\":\"typed_terminal_status_defers_cell_emission_while_replay_is_live\",\"single_flight\":1,\"next\":\"continue_active_replay_driver\"}" [| box (esc event); box (esc status); box (terminalContractRankId statusId); box cell.nodeId; box (esc (replayCellShapeText cell)); box (esc (replayCellSiteText cell)); box (pendingCount()); box queueDepth; box activeDepth; box progressYieldPending |])
                else
                    let emissionQueueDepth = lock gate (fun () -> replayQueue.Length)
                    let emissionActiveDepth = replayDriverActiveDepthValue()
                    let emissionProgressYieldPending = hasProgressYield()
                    let emissionReplayKey = replayKeyOf<TerminalContractEmissionK> cell.nodeId cell.shape cell.site (frameKeyText frame)
                    let emissionClosure = closureIdOfStatusId<TerminalContractEmissionK> (FastRuntimeFormat.format "terminal_emission:%s:%s:%d" [| box status; box (replayCellSiteText cell); box cell.nodeId |]) frame.status (frameKeyText frame)
