                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_contract_emission_pinned\",\"event\":%s,\"status\":%s,\"rank\":%d,\"node_id\":%d,\"shape\":%s,\"site\":%s,\"terminal_contract_authority_du\":%s,\"replay_key_du\":%s,\"closure_id_du\":%s,\"liveness_proof_du\":%s,\"log_completeness\":%s,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (esc status); box (terminalContractRankId statusId); box cell.nodeId; box (esc (replayCellShapeText cell)); box (esc (replayCellSiteText cell)); box (esc emissionAuthorityText); box (esc (replayKeyDuText emissionReplayKey)); box (esc (closureIdDuText emissionClosure)); box (esc (replayLivenessProofDuText emissionLivenessProof)); box (esc (logCompletenessPolicyText activeLogCompletenessPolicy)); box (esc (terminalContractNextId statusId)) |])


