        let private pinDynamicJoinBlockerId (event: string) (reasonId: CompilerKernelV2.OperationalReasonId) (detail: string) (dynamicJoinTextEvidence: DynamicJoinEvidenceId) (cell: ReplayCell) =
            let reason = CompilerKernelV2.OperationalReasonIdOps.text reasonId
            let blockedCell = { cell with status = ReplayCellSemanticStatus SemanticDynamicJoinApplyBlocked }
            let dynamicJoinDecision = dynamicJoinTerminalDecisionForStatusId (cellSemanticStatusId blockedCell)
            let queueDepth = lock gate (fun () -> replayQueue.Length)
            let activeDepth = replayDriverActiveDepthValue()
            let progressYieldPending = hasProgressYield()
            let dynamicJoinPending = pendingCount()
            let dynamicJoinOwner = dynamicJoinOwnerId blockedCell.nodeId blockedCell.shape
            let dynamicJoinOwnerTextValue = dynamicJoinOwnerText dynamicJoinOwner
            let dynamicJoinOperandId = dynamicJoinTextEvidence.operand
            let dynamicJoinFunctionShapeId = dynamicJoinShapeFromEvidence DynamicJoinFunctionRole (replayCellShapeText blockedCell) dynamicJoinTextEvidence
            let dynamicJoinArgShapeId = dynamicJoinShapeFromEvidence DynamicJoinArgumentRole detail dynamicJoinTextEvidence
            let dynamicJoinCarrierId = dynamicJoinSymbolicCarrierForEvidence dynamicJoinTextEvidence
            let dynamicJoinCarrierText = dynamicJoinSymbolicCarrierText dynamicJoinCarrierId
            let dynamicJoinLeaseId = dynamicJoinBridgeTailLeaseFor dynamicJoinOwner dynamicJoinPending queueDepth activeDepth progressYieldPending
            let dynamicJoinLeaseText = dynamicJoinBridgeTailLeaseText dynamicJoinLeaseId
