                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_dynamic_join_terminal_suppressed_after_live_replay\",\"event\":%s,\"node_id\":%d,\"shape\":%s,\"site\":%s,\"status\":%s,\"rank\":%d,\"reason\":%s,\"detail\":%s,\"dynamic_join_apply_operand_index\":%s,\"dynamic_join_function_shape_du\":%s,\"dynamic_join_arg_shape_du\":%s,\"dynamic_join_symbolic_carrier_du\":%s,\"bridge_tail_lease_id\":%s,\"bridge_tail_owner_du\":%s,\"dynamic_join_handoff_state_du\":%s,\"dynamic_join_apply_witness_du\":%s,\"dynamic_join_authority_decision_du\":%s,\"dynamic_join_authority_next_du\":%s,\"replay_key_du\":%s,\"closure_id_du\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"progress_yield_pending\":%b,\"runtime_union_carrier\":%b,\"policy\":\"dynamic_join_runtime_union_defers_durable_pin_while_root_or_replay_live\",\"decision_du\":%s,\"single_flight\":1,\"next\":\"continue_active_replay_driver\"}" [| box (esc event); box blockedCell.nodeId; box (esc (replayCellShapeText blockedCell)); box (esc (replayCellSiteText blockedCell)); box (esc (replayCellStatusText blockedCell.status)); box (terminalContractRankId SemanticDynamicJoinApplyBlocked); box (esc reason); box (esc detail); box (esc (dynamicJoinOperandIndexText dynamicJoinOperandId)); box (esc (dynamicJoinShapeText dynamicJoinFunctionShapeId)); box (esc (dynamicJoinShapeText dynamicJoinArgShapeId)); box (esc dynamicJoinCarrierText); box (esc dynamicJoinLeaseText); box (esc dynamicJoinOwnerTextValue); box (esc handoffText); box (esc dynamicJoinWitnessText); box (esc dynamicJoinAuthorityText); box (esc dynamicJoinNextActionText); box (esc (replayKeyDuText dynamicJoinReplayKey)); box (esc (closureIdDuText dynamicJoinClosure)); box dynamicJoinPending; box queueDepth; box activeDepth; box progressYieldPending; box runtimeUnionCarrier; box (esc (dynamicJoinTerminalDecisionText dynamicJoinDecision)) |])
