                    let rootCompleteShieldsStaleDynamicJoin =
                        rootCompleteShieldsPinnedShape SemanticDynamicJoinApplyBlocked [CellShapeEApply] frame pinned
                    let rootCompleteShieldsStaleMacroReplayRepeat =
