                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_backend4_stale_annot_retarget_demoted\",\"event\":%s,\"root_site\":%s,\"stale_site\":%s,\"root_status\":%s,\"stale_status\":%s,\"pending\":%d,\"durable_cleared\":%b,\"single_flight\":1,\"next\":\"preserve_retry_drain_frontier\"}" [| box (esc event); box (esc (frameSiteText frame)); box (esc (frameSiteText pinned)); box (esc (frameStatusToString frame.status)); box (esc (frameStatusToString pinned.status)); box (pendingCount()); box durableCleared |])
                        Some frame
                    elif leafCompleteShieldsStaleTypeVar then
                        // MIGRATION: historical runtime ended with a precise leaf-complete gap
                        // (missing parent continuation) being shadowed by a stale TV pin.
                        // Preserve the local semantic frontier and surface the missing parent
                        // continuation as the terminal contract without inventing it.
                        let leafFrame = { frame with status = frameStatusOfSemanticStatusId SemanticLeafParentContinuationMissingBlocked }
                        let durableCleared =
                            lock gate (fun () ->
                                match pinnedTerminalContract with
                                | Some p when frameSemanticStatusIs SemanticTypeVariableValueMissingBlocked p ->
                                    pinnedTerminalContract <- Some leafFrame
                                | _ -> pinTerminalContractLocked event leafFrame
                                match durableTerminalContract with
                                | Some p when frameSemanticStatusIs SemanticTypeVariableValueMissingBlocked p && (p.key = pinned.key || p.site = pinned.site) ->
                                    durableTerminalContract <- None
                                    true
                                | _ -> false)
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_leaf_parent_gap_pinned\",\"event\":%s,\"leaf_site\":%s,\"stale_site\":%s,\"leaf_status\":%s,\"stale_status\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"explicit_eval_worklist_leaf_parent_continuation_required\"}" [| box (esc event); box (esc (frameSiteText frame)); box (esc (frameSiteText pinned)); box (esc (frameStatusToString leafFrame.status)); box (esc (frameStatusToString pinned.status)); box (pendingCount()) |])
                        if durableCleared then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_durable_stale_typevar_cleared\",\"event\":%s,\"shield_status\":%s,\"stale_site\":%s,\"stale_key\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"preserve_leaf_gap\"}" [| box (esc event); box (esc (frameStatusToString leafFrame.status)); box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (pendingCount()) |])
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_stale_typevar_pin_cleared\",\"event\":%s,\"leaf_site\":%s,\"stale_site\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"preserve_leaf_gap\"}" [| box (esc event); box (esc (frameSiteText frame)); box (esc (frameSiteText pinned)); box (pendingCount()) |])
                        Some leafFrame
                    elif rootCompleteShieldsPayloadMissing then
                        // MIGRATION: historical runtime showed a root-complete ty/term frontier being
                        // retargeted to a rank-69 payload-missing continuation from backend.spi:2.
                        // Payload-missing is a scheduler evidence gap; once a real root proof is
                        // visible, keep it canonical and clear the stale payload pin.
                        lock gate (fun () ->
                            match pinnedTerminalContract with
                            | Some p when frameSemanticStatusIs SemanticReplayPayloadMissingBlocked p ->
                                pinnedTerminalContract <- None
                            | _ -> ())
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_root_complete_payload_missing_pin_suppressed\",\"event\":%s,\"root_site\":%s,\"payload_site\":%s,\"root_status\":%s,\"payload_status\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"preserve_root_evidence\"}" [| box (esc event); box (esc (frameSiteText frame)); box (esc (frameSiteText pinned)); box (esc (frameStatusToString frame.status)); box (esc (frameStatusToString pinned.status)); box (pendingCount()) |])
                        Some frame
                    elif rootCompleteShieldsStaleTypeVar || retargetShieldedByRootEvidence then
                        // MIGRATION: once a stale TV has been demoted under root-complete
                        // evidence, remove the pin.  MIGRATION returned the root frame but
                        // left the pinned TV alive; the next retry_stop pass could then
                        // retarget a stale-root-retarget blocker back to the old TV.
                        let durableCleared =
                            lock gate (fun () ->
                                match pinnedTerminalContract with
                                | Some p when frameSemanticStatusIs SemanticTypeVariableValueMissingBlocked p ->
                                    pinnedTerminalContract <- None
                                | _ -> ()
                                match durableTerminalContract with
                                | Some p when frameSemanticStatusIs SemanticTypeVariableValueMissingBlocked p && (p.key = pinned.key || p.site = pinned.site) ->
                                    durableTerminalContract <- None
                                    true
                                | _ -> false)
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_root_complete_stale_typevar_demoted\",\"event\":%s,\"root_site\":%s,\"stale_site\":%s,\"root_status\":%s,\"stale_status\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"attempt_build\"}" [| box (esc event); box (esc (frameSiteText frame)); box (esc (frameSiteText pinned)); box (esc (frameStatusToString frame.status)); box (esc (frameStatusToString pinned.status)); box (pendingCount()) |])
                        if durableCleared then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_durable_stale_typevar_cleared\",\"event\":%s,\"shield_status\":%s,\"stale_site\":%s,\"stale_key\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"preserve_root_evidence\"}" [| box (esc event); box (esc (frameStatusToString frame.status)); box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (pendingCount()) |])
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_stale_typevar_pin_cleared\",\"event\":%s,\"shield_status\":%s,\"stale_site\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"preserve_root_evidence\"}" [| box (esc event); box (esc (frameStatusToString frame.status)); box (esc (frameSiteText pinned)); box (pendingCount()) |])
                        Some frame
                    elif retryDrainPinnedTerminalDecision <> RetryDrainPinTerminal then
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_retry_drain_pinned_terminal_deferred_by_du\",\"event\":%s,\"decision_du\":%s,\"live_evidence_du\":%s,\"old_status\":%s,\"new_status\":%s,\"old_rank\":%d,\"new_rank\":%d,\"old_site\":%s,\"new_site\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"progress_yield_pending\":%b,\"fresh_root_witness\":%b,\"policy\":\"typed_retry_drain_preserves_live_replay_over_global_fuse_or_dynamic_join_pin\",\"single_flight\":1,\"next\":\"continue_with_live_frontier\"}" [| box (esc event); box (esc (retryDrainPinnedTerminalDecisionText retryDrainPinnedTerminalDecision)); box (esc (retryDrainLiveEvidenceText retryDrainLiveEvidence)); box (esc (frameStatusToString frame.status)); box (esc (frameStatusToString pinned.status)); box frameRank; box pinnedRank; box (esc (frameSiteText frame)); box (esc (frameSiteText pinned)); box retryDrainPending; box retryDrainQueueDepth; box retryDrainActiveDepth; box retryDrainProgressYield; box freshReplayRootWitnessAvailable |])
                        Some frame
                    elif pinnedBeatsLowerTerminal || ((pinnedRank >= 90 || pinnedBeatsNonTerminal) && (pinnedRank > frameRank || pinnedBeatsRootComplete || pinnedBeatsNonTerminal)) then
                        // MIGRATION: make the visible retry_stop frontier agree with
                        // the terminal chosen by MIGRATION, otherwise the final panel
                        // still prints the stale continuation_envelope frame.
                        lock gate (fun () ->
                            frontier <- Some pinned
                            slotSetLocked pinned)
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_retry_stop_frontier_retargeted_to_pinned_terminal\",\"event\":%s,\"old_status\":%s,\"new_status\":%s,\"old_rank\":%d,\"new_rank\":%d,\"old_site\":%s,\"new_site\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (esc (frameStatusToString frame.status)); box (esc (frameStatusToString pinned.status)); box frameRank; box pinnedRank; box (esc (frameSiteText frame)); box (esc (frameSiteText pinned)); box (pendingCount()); box (esc (terminalContractNext pinned.status)) |])
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_retry_drain_pinned_terminal_preferred\",\"event\":%s,\"old_status\":%s,\"new_status\":%s,\"old_rank\":%d,\"new_rank\":%d,\"old_site\":%s,\"new_site\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (esc (frameStatusToString frame.status)); box (esc (frameStatusToString pinned.status)); box frameRank; box pinnedRank; box (esc (frameSiteText frame)); box (esc (frameSiteText pinned)); box (pendingCount()); box (esc (terminalContractNext pinned.status)) |])
                        Some pinned
                    else Some frame
                | None -> Some frame

        [<StructuralEquality; NoComparison>]
        type ReplayPayloadFieldId =
            | ReplayPayloadKind
            | ReplayPayloadShape
            | ReplayPayloadNodeId
            | ReplayPayloadEnvTerm
            | ReplayPayloadEnvType
            | ReplayPayloadSeqLen
            | ReplayPayloadCseDepth
            | ReplayPayloadTraceDepth
            | ReplayPayloadSite
            | ReplayPayloadCursor
            | ReplayPayloadStep
            | ReplayPayloadStatus

        let private replayPayloadFieldId = function
            | "kind" -> Some ReplayPayloadKind
            | "shape" -> Some ReplayPayloadShape
            | "node_id" -> Some ReplayPayloadNodeId
            | "env_term" -> Some ReplayPayloadEnvTerm
            | "env_type" -> Some ReplayPayloadEnvType
            | "seq_len" -> Some ReplayPayloadSeqLen
            | "cse_depth" -> Some ReplayPayloadCseDepth
            | "trace_depth" -> Some ReplayPayloadTraceDepth
            | "site" -> Some ReplayPayloadSite
            | "cursor" -> Some ReplayPayloadCursor
            | "step" -> Some ReplayPayloadStep
            | "status" -> Some ReplayPayloadStatus
            | _ -> None

        // MIGRATION: reconstruct a ReplayCell from the exact compact payload emitted
        // by formatCellPayload.  The lexical envelope is opened once into a closed
        // field DU; downstream reconstruction never indexes by raw field names.
        let private tryReplayCellPayload (payload: string) : ReplayCell option =
            let tryInt (s: string) =
                let mutable v = 0
                if Int32.TryParse(s, &v) then Some v else None
            let tryPair (s: string) =
                let parts =
                    if Object.ReferenceEquals(s, null) then [||]
                    else s.Split([|'/'|], 2, StringSplitOptions.None)
                if parts.Length <> 2 then None
                else
                    match tryInt parts.[0], tryInt parts.[1] with
                    | Some a, Some b -> Some(a, b)
                    | _ -> None
            try
                if String.IsNullOrWhiteSpace payload then None
                else
                    let marker = "semantic_eval_payload("
                    let envelope = payload.Split([| marker |], 2, StringSplitOptions.None)
                    if envelope.Length <> 2 then None
                    else
                        let bodyParts = envelope.[1].Split([|')'|], 2, StringSplitOptions.None)
                        if bodyParts.Length = 0 || String.IsNullOrWhiteSpace bodyParts.[0] then None
                        else
                            let fields = System.Collections.Generic.Dictionary<ReplayPayloadFieldId,string>()
                            for part in bodyParts.[0].Split([|','|], StringSplitOptions.None) do
                                let pair = part.Split([|'='|], 2, StringSplitOptions.None)
                                if pair.Length = 2 then
                                    match replayPayloadFieldId (pair.[0].Trim()) with
                                    | Some field -> fields.[field] <- pair.[1].Trim()
                                    | None -> ()
                            let get field =
                                let mutable value = ""
                                if fields.TryGetValue(field, &value) then Some value else None
                            let kind = get ReplayPayloadKind
                            let shape = get ReplayPayloadShape
                            let nodeId = get ReplayPayloadNodeId |> Option.bind tryInt
                            let envTerm = get ReplayPayloadEnvTerm |> Option.bind tryPair
                            let envType = get ReplayPayloadEnvType |> Option.bind tryPair
                            let seqLen = get ReplayPayloadSeqLen |> Option.bind tryInt
                            let cseDepth = get ReplayPayloadCseDepth |> Option.bind tryInt
                            let traceDepth = get ReplayPayloadTraceDepth |> Option.bind tryInt
                            let site = get ReplayPayloadSite
                            let cursor = get ReplayPayloadCursor |> Option.bind tryInt
                            let step = get ReplayPayloadStep |> Option.bind tryInt
                            let status = get ReplayPayloadStatus
                            match kind, shape, nodeId, envTerm, envType, seqLen, cseDepth, traceDepth, site, cursor, step, status with
                            | Some kind, Some shape, Some nodeId, Some (egt, est), Some (egty, esty), Some seqLen, Some cseDepth, Some traceDepth, Some site, Some cursor, Some step, Some status ->
                                Some { kind = evalKindOfString kind; shape = EvalReplayValueStore.workShapeIdOfText shape; nodeId = nodeId; envGlobalTerm = egt; envStackTerm = est; envGlobalType = egty; envStackType = esty; seqLen = seqLen; cseDepth = cseDepth; traceDepth = traceDepth; site = EvalReplayValueStore.workSiteIdOfText site; cursor = cursor; step = step; status = replayCellStatusOfText status }
                            | _ -> None
            with _ -> None

        let private replayTaskCell (task:ReplayTask) =
            match replayTaskSemanticCell task with
            | Some cell -> Some cell
            | None -> tryReplayCellPayload (replayTaskLegacyPayloadText task)

        // MIGRATION: dominant queue sampling for the HUD and fail-fast yield-thrash guard.
        // Typed tasks expose their ReplayCell directly; only legacy envelopes parse text at
        // the replayTaskCell quarantine. Sampling itself stores typed kind/shape buckets.
        type HotQueueNodeId =
            | HotQueueDominantNodeUnknown
            | HotQueueNode of int

        [<StructuralEquality; NoComparison>]
        type HotQueueBucketId =
            | HotQueueCellBucket of kind:EvalKind * shape:CompilerIdentityKernel.WorkShapeId
            | HotQueueTaskDriverBucket of driver:ReplayDriverId

        let private hotQueueBucketText = function
            | HotQueueCellBucket(kind, shape) ->
                evalKindToString kind + ":" + CompilerIdentityKernel.WorkShapeIdOps.text shape
            | HotQueueTaskDriverBucket driver ->
                "task:" + replayDriverToString driver

        let private hotQueueNodeIdText = function
            | HotQueueNode nodeId -> string nodeId
            | HotQueueDominantNodeUnknown -> "unknown"

        [<StructuralEquality; NoComparison>]
        type HotQueueSample = {
            hotQueueBucket : HotQueueBucketId option
            hotQueueNodeId : HotQueueNodeId
            hotQueueCount : int
            hotQueueSampled : int
        }

        let private emptyHotQueueSample =
            { hotQueueBucket = None
              hotQueueNodeId = HotQueueDominantNodeUnknown
              hotQueueCount = 0
              hotQueueSampled = 0 }

        let private replayQueueCellHotKey (cell: ReplayCell) =
            HotQueueCellBucket(
                replayCellEvalKindId cell,
                cell.shape)

        let private replayQueueHotQueueSampleUnlocked (maxItems: int) =
            let limit = max 1 (min 128 maxItems)
            let counts = System.Collections.Generic.Dictionary<HotQueueBucketId,int>()
            let nodeCounts = System.Collections.Generic.Dictionary<int,int>()
            let addKey (key: HotQueueBucketId) =
                let mutable prior = 0
                if counts.TryGetValue(key, &prior) then counts.[key] <- prior + 1
                else counts.[key] <- 1
            let addNodeId (nodeId: int) =
                let mutable prior = 0
                if nodeCounts.TryGetValue(nodeId, &prior) then nodeCounts.[nodeId] <- prior + 1
                else nodeCounts.[nodeId] <- 1
            let mutable sampled = 0
            replayQueue
            |> List.truncate limit
            |> List.iter (fun task ->
                match replayTaskCell task with
                | Some cell ->
                    sampled <- sampled + 1
                    addKey (replayQueueCellHotKey cell)
                    addNodeId cell.nodeId
                | None ->
                    sampled <- sampled + 1
                    addKey (HotQueueTaskDriverBucket (replayTaskDriverId task)))
            if sampled <= 0 || counts.Count <= 0 then emptyHotQueueSample
            else
                let mutable bestKey : HotQueueBucketId option = None
                let mutable bestCount = 0
                for kv in counts do
                    if kv.Value > bestCount then
                        bestKey <- Some kv.Key
                        bestCount <- kv.Value
                let mutable bestNodeId = HotQueueDominantNodeUnknown
                let mutable bestNodeCount = 0
                for kv in nodeCounts do
                    if kv.Value > bestNodeCount then
                        bestNodeId <- HotQueueNode kv.Key
                        bestNodeCount <- kv.Value
                { hotQueueBucket = bestKey
                  hotQueueNodeId = bestNodeId
                  hotQueueCount = bestCount
                  hotQueueSampled = sampled }

        let replayQueueHotQueueSample (maxItems: int) =
            lock gate (fun () -> replayQueueHotQueueSampleUnlocked maxItems)

        let replayQueueHotQueueDu () =
            (replayQueueHotQueueSample 64).hotQueueBucket
            |> Option.map hotQueueBucketText
            |> Option.defaultValue "-"

        let tryForceDeferredTypeVarCycleBreakFromReplayQueueId (eventId: ReplayTickEventId) (reasonId: CompilerKernelV2.OperationalReasonId) (maxItems: int) =
            let event = replayTickEventToString eventId
            let reason = CompilerKernelV2.OperationalReasonIdOps.text reasonId
            let scanLimit = max 1 (min 64 maxItems)
            let cells =
                lock gate (fun () ->
                    replayQueue
                    |> List.truncate scanLimit
                    |> List.choose (fun task -> replayTaskCell task))
            if cells.IsEmpty then
                let queueDepth, activeDepth, pending =
                    lock gate (fun () -> replayQueue.Length, replayDriverActiveDepth, pendingCount())
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_queue_cycle_break_fallback_missing_cell\",\"event\":%s,\"reason\":%s,\"scan_limit\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"policy\":\"no_root_cycle_break_scans_queued_payloads_when_frontier_sample_missing\",\"single_flight\":1,\"next\":\"retry_or_continue_live_replay\"}" [| box (esc event); box (esc reason); box scanLimit; box queueDepth; box activeDepth; box pending |])
                false
            else
                let mutable mutated = false
                let mutable attempted = 0
                for cell in cells do
                    if not mutated then
                        attempted <- attempted + 1
                        mutated <-
                            tryForceDeferredTypeVarCycleBreakForCell
                                eventId
                                (CompilerKernelV2.OperationalReasonIdOps.create (FastRuntimeFormat.format "%s:replay_queue_fallback:scan=%d:attempt=%d" [| box reason; box scanLimit; box attempted |]))
                                cell
                if not mutated then
                    let queueDepth, activeDepth, pending =
                        lock gate (fun () -> replayQueue.Length, replayDriverActiveDepth, pendingCount())
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_queue_cycle_break_fallback_all_leased\",\"event\":%s,\"reason\":%s,\"scan_limit\":%d,\"attempted_cells\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"policy\":\"queue_fallback_advances_past_first_leased_cell_before_reporting_no_mutation\",\"single_flight\":1,\"next\":\"retry_or_poison_when_repeat_cap_exhausts\"}" [| box (esc event); box (esc reason); box scanLimit; box attempted; box queueDepth; box activeDepth; box pending |])
                mutated

        type ReplayQueueSurgePoisonDecisionId =
            | ReplayQueueSurgePoisonMissingCell
            | ReplayQueueSurgePoisonAlreadyCovered
            | ReplayQueueSurgePoisonEventCapSuppressed
            | ReplayQueueSurgePoisonInjected

        let private replayQueueSurgePoisonDecisionText = function
            | ReplayQueueSurgePoisonMissingCell -> "missing_cell"
            | ReplayQueueSurgePoisonAlreadyCovered -> "already_covered"
            | ReplayQueueSurgePoisonEventCapSuppressed -> "event_cap_suppressed"
            | ReplayQueueSurgePoisonInjected -> "poison_injected"

        type ReplayQueueSurgeParentPoisonAuthorityId =
            | ReplayQueueSurgeParentPoisonSuppressLiveTailDrain
            | ReplayQueueSurgeParentPoisonAllowParentPoison

        type ReplayQueueSurgeEventId =
            | ReplayQueueSurgeActiveHard
            | ReplayQueueSurgeCrossKind
            | ReplayQueueSurgeOrdinary
            | ReplayQueueSurgeOther of event:ReplayEventId

        [<Struct>]
        type ReplayQueueSurgeClassifiedEvent = private {
            surgeId : ReplayQueueSurgeEventId
            tickEventId : ReplayTickEventId
        }

        let private replayQueueSurgeEventId (event:string) =
            let tickEventId = ReplayTickEventUnknown(CompilerKernelV2.OperationalReasonIdOps.create event)
            let surgeId =
                match if String.IsNullOrWhiteSpace event then "" else event.ToLowerInvariant() with
                | "bigstack_join_wait_active_queue_surge_hard_poison"
                | "active_queue_surge_hard"
                | "active_queue_surge_hard_poison" -> ReplayQueueSurgeActiveHard
                | "cross_kind_terminal_drain_monadic_tie_breaker"
                | "cross_kind_admission_semantic_tie_breaker"
                | "cross_kind_admission_procedural_cycle_exhausted"
                | "bigstack_join_wait_cross_kind_poison"
                | "cross_kind_queue_surge" -> ReplayQueueSurgeCrossKind
                | "bigstack_join_wait_raise_retry_queue_surge_poison"
                | "bigstack_join_wait_queue_surge_repeated_deferral_poison"
                | "bigstack_join_wait_queue_surge_poison"
                | "queue_surge"
                | "replay_queue_surge" -> ReplayQueueSurgeOrdinary
                | _ -> ReplayQueueSurgeOther (ReplayEventIdOps.create event)
            { surgeId = surgeId; tickEventId = tickEventId }

        let private replayQueueSurgeParentPoisonAuthorityText = function
            | ReplayQueueSurgeParentPoisonSuppressLiveTailDrain -> "suppress_live_tail_drain"
            | ReplayQueueSurgeParentPoisonAllowParentPoison -> "allow_parent_poison"

        let private replayQueueSurgeParentPoisonAuthorityFor (eventId: ReplayQueueSurgeEventId) queueDepth activeDepth pending =
            if DiagJson.terminalSemanticDrainActiveNow() then ReplayQueueSurgeParentPoisonSuppressLiveTailDrain
            elif eventId = ReplayQueueSurgeActiveHard then ReplayQueueSurgeParentPoisonAllowParentPoison
            elif queueDepth >= 96 && activeDepth >= 4 && pending >= 0 then ReplayQueueSurgeParentPoisonSuppressLiveTailDrain
            else ReplayQueueSurgeParentPoisonAllowParentPoison

        let private replayQueueSurgePoisonCounts =
            System.Collections.Concurrent.ConcurrentDictionary<ReplayCellIdentity,int>()

        let private replayQueueSurgePoisonEventCounts =
            System.Collections.Concurrent.ConcurrentDictionary<ReplayQueueSurgeEventId,int>()

        let private replayQueueSurgePoisonEventCap (eventId: ReplayQueueSurgeEventId) =
            // MIGRATION: active_queue_surge_hard_poison is a bounded emergency valve for
            // q>=256/a>=4 stalls.  It needs more than the old cross-kind pulse, but still
            // stays capped to avoid unbounded terminal spray.
            match eventId with
            | ReplayQueueSurgeActiveHard -> 96
            | ReplayQueueSurgeCrossKind -> 3
            | ReplayQueueSurgeOrdinary
            | ReplayQueueSurgeOther _ -> 48

        let tryForceDeferredTypeVarPoisonFromReplayQueueId (event: string) (reasonId: OperationalReasonId) (maxItems: int) =
            let classifiedEvent = replayQueueSurgeEventId event
            let tickEventId = classifiedEvent.tickEventId
            let reasonText = OperationalReasonIdOps.text reasonId
            let scanLimit = max 1 (min 64 maxItems)
            let eventId = classifiedEvent.surgeId
            let eventAttempt = replayQueueSurgePoisonEventCounts.AddOrUpdate(eventId, 1, fun _ old -> old + 1)
            let eventCap = replayQueueSurgePoisonEventCap eventId
            if eventAttempt > eventCap then
                let queueDepth, activeDepth, pending =
                    lock gate (fun () -> replayQueue.Length, replayDriverActiveDepth, pendingCount())
                if eventAttempt = eventCap + 1 || eventAttempt % 32 = 0 then
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_queue_surge_parent_poison_event_cap_suppressed\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"event_attempt\":%d,\"event_cap\":%d,\"scan_limit\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"policy\":\"cap_parent_poison_spray_per_event_after_enough_parent_poison_requests\",\"single_flight\":1,\"next\":\"continue_replay_or_fail_closed\"}" [| box (esc event); box (esc reasonText); box (esc (replayQueueSurgePoisonDecisionText ReplayQueueSurgePoisonEventCapSuppressed)); box eventAttempt; box eventCap; box scanLimit; box queueDepth; box activeDepth; box pending |])
                false
            else
                let initialQueueDepth, initialActiveDepth, initialPending =
                    lock gate (fun () -> replayQueue.Length, replayDriverActiveDepth, pendingCount())
                let authorityId = replayQueueSurgeParentPoisonAuthorityFor eventId initialQueueDepth initialActiveDepth initialPending
                if authorityId = ReplayQueueSurgeParentPoisonSuppressLiveTailDrain then
                    let tickRequestId = tryRequestReplayDriverTickViaHook tickEventId ReplayTickReasonQueueSurgeParentPoisonSuppressedLiveTail
                    let scheduled = replayDriverTickRequestHookScheduled tickRequestId
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_queue_surge_parent_poison_suppressed_live_tail\",\"event\":%s,\"reason\":%s,\"authority_du\":%s,\"event_attempt\":%d,\"event_cap\":%d,\"replay_tick_request_du\":%s,\"scheduled_async\":%b,\"scan_limit\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"policy\":\"generic_live_queue_surge_drains_before_parent_poison_surface_no_buildok\",\"single_flight\":1,\"next\":\"continue_replay_driver_or_pressure_drain\"}" [| box (esc event); box (esc reasonText); box (esc (replayQueueSurgeParentPoisonAuthorityText authorityId)); box eventAttempt; box eventCap; box (esc (replayDriverTickRequestHookText tickRequestId)); box scheduled; box scanLimit; box initialQueueDepth; box initialActiveDepth; box initialPending |])
                    false
                else
                    let cells =
                        lock gate (fun () ->
                            replayQueue
                            |> List.truncate scanLimit
                            |> List.choose (fun task -> replayTaskCell task))
                    if cells.IsEmpty then
                        let queueDepth, activeDepth, pending =
                            lock gate (fun () -> replayQueue.Length, replayDriverActiveDepth, pendingCount())
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_queue_surge_poison_missing_cell\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"event_attempt\":%d,\"event_cap\":%d,\"scan_limit\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"policy\":\"high_queue_surge_prefers_parent_poison_over_new_hole_churn_but_found_no_typed_payload\",\"single_flight\":1,\"next\":\"retry_or_continue_live_replay\"}" [| box (esc event); box (esc reasonText); box (esc (replayQueueSurgePoisonDecisionText ReplayQueueSurgePoisonMissingCell)); box eventAttempt; box eventCap; box scanLimit; box queueDepth; box activeDepth; box pending |])
                        false
                    else
                        let mutable injected = false
                        let mutable attempted = 0
                        let mutable covered = 0
                        for cell in cells do
                            if not injected then
                                attempted <- attempted + 1
                                let poisonKey = directCellCycleBreakLeaseKey event cell
                                let poisonCount = replayQueueSurgePoisonCounts.AddOrUpdate(poisonKey, 1, fun _ old -> old + 1)
                                if poisonCount = 1 || poisonCount % 8 = 0 then
                                    let parentDecision, queueDepth, activeDepth, pending =
                                        lock gate (fun () ->
                                            let poisonedCell = { cell with status = ReplayCellSemanticStatus SemanticParentReplayCycleBreakPoisoned }
                                            let parentDecision = scheduleParentReplayLocked event (OperationalReasonIdOps.create "queue_surge_parent_poison") poisonedCell
                                            parentDecision, replayQueue.Length, replayDriverActiveDepth, pendingCount())
                                    let tickRequestId = tryRequestReplayDriverTickViaHook tickEventId ReplayTickReasonQueueSurgeParentPoisonPhysicalHandoff
                                    let scheduled = replayDriverTickRequestHookScheduled tickRequestId
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_queue_surge_parent_poison_injected\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"authority_du\":%s,\"event_attempt\":%d,\"event_cap\":%d,\"parent_enqueue_du\":%s,\"replay_tick_request_du\":%s,\"scheduled_async\":%b,\"scan_limit\":%d,\"attempted_cells\":%d,\"poison_count\":%d,\"poison_key\":%s,\"cell_kind\":%s,\"cell_shape\":%s,\"cell_node_id\":%d,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"materialized_terminal_payload_du\":\"QueueSurgeParentReplayCycleBreakPoisonImmediateFill\",\"hopac_ivar_registry_id\":\"parent_replay_cycle_break_poison:queue_surge\",\"witness_type\":\"ParentReplayCycleBreakPoisonImmediateFillProof\",\"proof_tuple_complete\":true,\"native_hopac_callback_route_du\":\"IVar.fill(parent_replay_cycle_break_poison:queue_surge)\",\"native_promise_identifier_du\":\"promise_id(parent_replay_cycle_break_poison:queue_surge,ParentReplayCycleBreakPoisonImmediateFillProof)\",\"commit_pathway_trace_du\":\"queue_surge_parent_poison->IVar.fill->NativePromiseResult\",\"active_native_callback_closure_du\":\"callback=IVar.fill(parent_replay_cycle_break_poison:queue_surge)|boundary=execute_native_direct_ast_eval_before_polling_boundary|return=NativePromiseFailed_or_ASTDelta|legacy=false\",\"native_callback_control_flow_gate_du\":\"proof_tuple_complete->execute_native_direct_ast_callback_before_polling_boundary->return_NativePromiseResult->legacy_unreachable\",\"callback_tracer_du\":\"[Witness:ParentReplayCycleBreakPoisonImmediateFillProof]->[IVar:parent_replay_cycle_break_poison:queue_surge]->[Action:IVar.fill]\",\"thread_fate_du\":\"native_hopac_run_queue_after_inline_callback\",\"worker_return_topology_du\":\"return_NativePromiseResult_after_inline_queue_surge_parent_poison_callback\",\"eval_worklist_boundary_reachable_after_callback\":false,\"legacy_live_tail_veto_reachable\":false,\"policy\":\"queue_surge_hard_authority_parent_poison_no_buildok\",\"single_flight\":1,\"next\":\"execute_queue_surge_parent_poison_inline_callback_before_eval_worklist_boundary\"}" [| box (esc event); box (esc reasonText); box (esc (replayQueueSurgePoisonDecisionText ReplayQueueSurgePoisonInjected)); box (esc (replayQueueSurgeParentPoisonAuthorityText authorityId)); box eventAttempt; box eventCap; box (esc (parentReplayEnqueueDecisionText parentDecision)); box (esc (replayDriverTickRequestHookText tickRequestId)); box scheduled; box scanLimit; box attempted; box poisonCount; box (esc (replayCellIdentityText poisonKey)); box (esc (evalKindToString cell.kind)); box (esc (replayCellShapeText cell)); box cell.nodeId; box pending; box queueDepth; box activeDepth |])
                                    injected <- true
                                else
                                    covered <- covered + 1
                        if not injected then
                            let queueDepth, activeDepth, pending =
                                lock gate (fun () -> replayQueue.Length, replayDriverActiveDepth, pendingCount())
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_queue_surge_parent_poison_already_covered\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"authority_du\":%s,\"event_attempt\":%d,\"event_cap\":%d,\"scan_limit\":%d,\"attempted_cells\":%d,\"covered_cells\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"policy\":\"queue_surge_poison_suppresses_repeat_receipts_after_parent_poison_was_already_requested\",\"single_flight\":1,\"next\":\"continue_replay_without_duplicate_poison\"}" [| box (esc event); box (esc reasonText); box (esc (replayQueueSurgePoisonDecisionText ReplayQueueSurgePoisonAlreadyCovered)); box (esc (replayQueueSurgeParentPoisonAuthorityText authorityId)); box eventAttempt; box eventCap; box scanLimit; box attempted; box covered; box queueDepth; box activeDepth; box pending |])
                        injected

        let snapshot (maxn: int) : Frame list =
            if maxn <= 0 then []
            else
                lock gate (fun () ->
                    let xs = ResizeArray<Frame>()
                    let seen = System.Collections.Generic.HashSet<ReplayFramePendingIdentity>()
                    let add (opt: Frame option) =
                        match opt with
                        | Some frame ->
                            let identity : ReplayFramePendingIdentity = {
                                kind = frame.kind
                                key = frame.key
                                site = frame.site
                            }
                            if seen.Add identity then xs.Add frame
                        | None -> ()
                    add frontier
                    add frontierTerm
                    add frontierTy
                    xs |> Seq.truncate maxn |> Seq.toList)

        type ReplayQueueQuiescenceSnapshot = {
            queueDepth : int
            activeDepth : int
            headTaskId : int64
            headKey : ReplayTaskKeyId option
            headDriver : ReplayDriverId option
            headStatus : ReplayTaskStatusId option
            headWorkUnit : CompilerKernelV2.WorkUnitId<CompilerKernelV2.ReplayPhase,CompilerKernelV2.ReplayWorkKind> option
        }

        let replayQueueQuiescenceSnapshot () : ReplayQueueQuiescenceSnapshot =
            lock gate (fun () ->
                match replayQueue with
                | task :: _ ->
                    let semanticWorkUnit = replayTaskSemanticWorkUnit task
                    { queueDepth = replayQueue.Length
                      activeDepth = replayDriverActiveDepth
                      headTaskId = task.id
                      headKey = Some task.key
                      headDriver = Some task.driver
                      headStatus = Some task.status
                      headWorkUnit = Some semanticWorkUnit }
                | [] ->
                    { queueDepth = 0
                      activeDepth = replayDriverActiveDepth
                      headTaskId = 0L
                      headKey = None
                      headDriver = None
                      headStatus = None
                      headWorkUnit = None })

        let replayQueueQuiescenceHeadDriverText snapshot =
            snapshot.headDriver
            |> Option.map replayDriverToString
            |> Option.defaultValue "none"

        let replayQueueQuiescenceHeadStatusText snapshot =
            snapshot.headStatus
            |> Option.map replayTaskStatusToString
            |> Option.defaultValue "none"

        let replayQueueQuiescenceHeadKeyText snapshot =
            snapshot.headKey
            |> Option.map ReplayTaskKeyIdOps.text
            |> Option.defaultValue ""

        let replayQueueQuiescenceHeadWorkUnitText snapshot =
            snapshot.headWorkUnit
            |> Option.map CompilerKernelV2.WorkUnitIdOps.digestText
            |> Option.defaultValue ""

        let replayQueueDepth () =
            lock gate (fun () -> replayQueue.Length)

        let replayDriverStatus () =
            lock gate (fun () ->
                match replayQueue with
                | task :: _ -> sprintf "%s/%s" (replayDriverToString task.driver) (replayTaskStatusToString task.status)
                | [] -> "none")

        let private semanticPayloadAvailabilityId () =
            lock gate (fun () ->
                match frontier with
                | Some frame ->
                    match frame.payload with
                    | FrameSemanticCellPayload _
                    | FrameSemanticCellPayloadWithReasonSignal _ -> ReplayPayloadCell
                    | FrameLegacySemanticPayload legacy when not (String.IsNullOrWhiteSpace legacy.text) -> ReplayPayloadSemantic
                    | _ -> ReplayPayloadMissing
                | None -> ReplayPayloadNone)

        let semanticPayloadStatus () =
            semanticPayloadAvailabilityId () |> replayPayloadAvailabilityText

        let semanticPayloadIsCell () =
            match semanticPayloadAvailabilityId () with
            | ReplayPayloadCell -> true
            | _ -> false

        let semanticPayloadIsCellOrSemantic () =
            match semanticPayloadAvailabilityId () with
            | ReplayPayloadCell
            | ReplayPayloadSemantic -> true
            | _ -> false

        let semanticPayloadHasFact (fact: FrontierSemanticPayloadFactId) =
            lock gate (fun () ->
                match frontier with
                | Some frame ->
                    match frame.payload with
                    | FrameLegacySemanticPayload legacy -> Set.contains fact legacy.semanticFacts
                    | FrameSemanticCellPayload _
                    | FrameSemanticCellPayloadWithReasonSignal _
                    | FramePayloadMissing -> false
                | None -> false)

        // MIGRATION: move the replay scheduler away from dumb status aliases.
        // A replay obligation carries the actual runnable/suppressed work item,
        // its liveness snapshot, and its terminal budget.  Strings are now only
        // a serialization boundary for JSON/status fields.
        type ReplayObligationKind =
            | ReplayObligationRun
            | ReplayObligationDefer
            | ReplayObligationBlock

        // MIGRATION: reason strings had become the new untyped edge after
        // ReplayObligation itself became a DU-backed carrier.  Keep raw text
        // only at the JSON/status boundary so the active cross-kind loop can
        // be bucketed without promoting any semantic completion.
        type ReplayObligationReasonId =
            | ReplayReasonCrossKindActiveDriver
            | ReplayReasonIdleCrossKindDriver
            | ReplayReasonParentResumeCellDeferred
            | ReplayReasonSameNodeParentReplayDeferred
            | ReplayReasonActiveReplayCellDeferred
            | ReplayReasonReentrantReplayDriver
            | ReplayReasonDeferredChildCell
            | ReplayReasonUnknown of CompilerKernelV2.OperationalReasonId

        let private replayObligationReasonText = function
            | ReplayReasonCrossKindActiveDriver -> "cross_kind_active_replay_driver"
            | ReplayReasonIdleCrossKindDriver -> "idle_cross_kind_replay_driver"
            | ReplayReasonParentResumeCellDeferred -> "parent_resume_cell_deferred"
            | ReplayReasonSameNodeParentReplayDeferred -> "same_node_parent_replay_cell_deferred"
            | ReplayReasonActiveReplayCellDeferred -> "active_replay_cell_deferred"
            | ReplayReasonReentrantReplayDriver -> "reentrant_replay_driver"
            | ReplayReasonDeferredChildCell -> "deferred_child_cell"
            | ReplayReasonUnknown reasonId -> CompilerKernelV2.OperationalReasonIdOps.text reasonId

        type CrossKindReentryEvidenceId =
            | CrossKindReentryNoHotNode
            | CrossKindReentrySameHotNode of int
            | CrossKindReentryQueueSurge of int
            | CrossKindReentryRootStalled of int

        let private crossKindReentryEvidenceText = function
            | CrossKindReentryNoHotNode -> "no_hot_node"
            | CrossKindReentrySameHotNode n -> "same_hot_node:" + string n
            | CrossKindReentryQueueSurge q -> "queue_surge:" + string q
            | CrossKindReentryRootStalled ms -> "root_stalled:" + string ms

        type CrossKindReentryEvidence = {
            evidenceId : CrossKindReentryEvidenceId
            effectiveReentryCount : int
            sameHotNodeCount : int
            rootReceiptCount : int
            lastRootReceiptAgeMs : int
        }

        type HotReplayObligationId =
            | HotReplayObligationTermSameKind
            | HotReplayObligationTySameKind
            | HotReplayObligationTermToTy
            | HotReplayObligationTyToTerm
            | HotReplayObligationCrossKindUnknown

        let private hotReplayObligationText = function
            | HotReplayObligationTermSameKind -> "term_same_kind_reentry"
            | HotReplayObligationTySameKind -> "ty_same_kind_reentry"
            | HotReplayObligationTermToTy -> "term_to_ty"
            | HotReplayObligationTyToTerm -> "ty_to_term"
            | HotReplayObligationCrossKindUnknown -> "cross_kind_unknown"


        let private hotReplayObligationForTyped activeDriverKind cellKind =
            match activeDriverKind, cellKind with
            | ReplayKindTerm, ReplayKindTerm -> HotReplayObligationTermSameKind
            | ReplayKindTy, ReplayKindTy -> HotReplayObligationTySameKind
            | ReplayKindTerm, ReplayKindTy -> HotReplayObligationTermToTy
            | ReplayKindTy, ReplayKindTerm -> HotReplayObligationTyToTerm
            | _ -> HotReplayObligationCrossKindUnknown

        let private hotReplayObligationForEvalKind activeDriverKind cellKind =
            match activeDriverKind, cellKind with
            | EvalTerm, EvalTerm -> HotReplayObligationTermSameKind
            | EvalTy, EvalTy -> HotReplayObligationTySameKind
            | EvalTerm, EvalTy -> HotReplayObligationTermToTy
            | EvalTy, EvalTerm -> HotReplayObligationTyToTerm
            | _ -> HotReplayObligationCrossKindUnknown

        let mutable private crossKindLastHotNodeId = HotQueueDominantNodeUnknown
        let mutable private crossKindSameHotNodeCount = 0
        let mutable private crossKindLastRootReceiptCount = 0
        let mutable private crossKindLastRootReceiptMs = 0L
        let mutable private pendingStarvationStartMs = 0L

        let private hotQueueNodeIdSame (a: HotQueueNodeId) (b: HotQueueNodeId) =
            match a, b with
            | HotQueueNode x, HotQueueNode y -> x = y
            | _ -> false

        let private hotQueueNodeIdKnown = function
            | HotQueueNode _ -> true
            | HotQueueDominantNodeUnknown -> false

        let private crossKindRootReceiptCount () =
            DiagJson.snapshotKindCount "eval_worklist_source_value_stored"
            + DiagJson.snapshotKindCount "eval_worklist_root_complete_replay_progress_marked"

        let private noteCrossKindReentryEvidence (hotQueue: HotQueueSample) (liveness: ReplayLivenessSnapshot) =
            let nowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let rootCount = crossKindRootReceiptCount()
            lock gate (fun () ->
                if rootCount > crossKindLastRootReceiptCount || crossKindLastRootReceiptMs <= 0L then
                    crossKindLastRootReceiptCount <- rootCount
                    crossKindLastRootReceiptMs <- nowMs
                if hotQueueNodeIdKnown hotQueue.hotQueueNodeId then
                    if hotQueueNodeIdSame hotQueue.hotQueueNodeId crossKindLastHotNodeId then
                        crossKindSameHotNodeCount <- crossKindSameHotNodeCount + 1
                    else
                        crossKindLastHotNodeId <- hotQueue.hotQueueNodeId
                        crossKindSameHotNodeCount <- 1
                else
                    crossKindSameHotNodeCount <- 0
                    crossKindLastHotNodeId <- HotQueueDominantNodeUnknown
                let rootAge =
                    if crossKindLastRootReceiptMs <= 0L then -1
                    else int (min 2147483647L (max 0L (nowMs - crossKindLastRootReceiptMs)))
                let physicalSameHotNodeCount = max crossKindSameHotNodeCount hotQueue.hotQueueCount
                let effective = max hotQueue.hotQueueCount (max liveness.queueDepth physicalSameHotNodeCount)
                let evidenceId =
                    if rootAge >= 500 && (liveness.queueDepth > 0 || liveness.activeDepth > 0) then CrossKindReentryRootStalled rootAge
                    elif physicalSameHotNodeCount >= 2 then CrossKindReentrySameHotNode physicalSameHotNodeCount
                    elif liveness.queueDepth >= 12 then CrossKindReentryQueueSurge liveness.queueDepth
                    else CrossKindReentryNoHotNode
                { evidenceId = evidenceId
                  effectiveReentryCount = effective
                  sameHotNodeCount = physicalSameHotNodeCount
                  rootReceiptCount = rootCount
                  lastRootReceiptAgeMs = rootAge })

        let private pendingStarvedMsSnapshot () =
            let nowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let p = pendingCount()
            lock gate (fun () ->
                if p > 0 then
                    if pendingStarvationStartMs <= 0L then pendingStarvationStartMs <- nowMs
                    int (min 2147483647L (max 0L (nowMs - pendingStarvationStartMs)))
                else
                    pendingStarvationStartMs <- 0L
                    0)

        let private staleRetargetObligationShieldActive () =
            lock gate (fun () ->
                // MIGRATION: force the option type to Frame.  Both Frame and
                // ReplayTask have a status field, and MIGRATION left this helper
                // unannotated; F# inferred ReplayTask option, then rejected the
                // terminal ledgers below as Frame option.
                let isStaleRetargetFrame (opt: Frame option) =
                    match opt with
                    | Some frame -> isRootCompleteStaleRetargetLiveReplayLivelockStatus (frameSemanticStatusId frame)
                    | None -> false
                isStaleRetargetFrame pinnedTerminalContract
                || isStaleRetargetFrame durableTerminalContract
                || DiagJson.snapshotKindCount "eval_worklist_bigstack_root_stale_retarget_handoff_decision" > 0)

        type ReplayObligationMacroTerminalDecisionId =
            | ReplayObligationMacroTerminalNone
            | ReplayObligationMacroTerminalStaleRetarget

        let private replayObligationMacroTerminalDecisionText = function
            | ReplayObligationMacroTerminalNone -> "none"
            | ReplayObligationMacroTerminalStaleRetarget -> "stale_retarget"

        let private replayObligationMacroTerminalDecisionFor () =
            if staleRetargetObligationShieldActive() then ReplayObligationMacroTerminalStaleRetarget
            else ReplayObligationMacroTerminalNone

        let private replayObligationMacroTerminalBlocksDeferral = function
            | ReplayObligationMacroTerminalStaleRetarget -> true
            | ReplayObligationMacroTerminalNone -> false

        type ReplayObligation = {
            obligation : ReplayObligationKind
            target : ReplayObligationTarget
            liveness : ReplayLivenessSnapshot
            reason : ReplayObligationReasonId
            repeat : int
            cap : int
        }

        // MIGRATION: the assessment's key invariant as a DU.  If a cross-kind
        // obligation wants to yield while pending=0, no parked IVar/work item exists
        // that can resolve it.  That is terminal graph evidence, not scheduler liveness.
        type CrossKindYieldThrashDecisionId =
            | CrossKindYieldThrashPromoteRequeue
            | CrossKindYieldThrashDeferFreshRootPendingTail
            | CrossKindYieldThrashDeferZeroRepeatActiveTail
            | CrossKindYieldThrashHardPoisonPendingZero
            | CrossKindYieldThrashHardPoisonHotQueue
            | CrossKindYieldThrashHardPoisonReentryCap
            | CrossKindYieldThrashHardPoisonObligationCap
            | CrossKindYieldThrashHardPoisonPostScheduleCap
            | CrossKindYieldThrashHardPoisonStaleRetargetObligation
            | CrossKindYieldThrashHardPoisonRootStalled

        type YieldThrashParticipantRole =
            | YieldThrashIncoming
            | YieldThrashHotQueueDominant
            | YieldThrashParentContinuation
            | YieldThrashCrossKindSibling

        type YieldThrashParticipant = {
            role : YieldThrashParticipantRole
            key : AnyReplayKey
            repeatCount : int64
        }

        type CrossKindYieldThrashParticipants = {
            incoming : YieldThrashParticipant
            hotQueue : YieldThrashParticipant option
            direction : HotReplayObligationId
            rootReceiptAgeMs : int64
        }

        type CrossKindYieldThrashAuthority =
            | CrossKindThrashContinueProgressingGraph
            | CrossKindThrashDeferredBoundGraph of graph:DiagJson.TerminalExecutableGraphState<DiagJson.TerminalOutcomeKind>
            | CrossKindThrashAllowedExhaustedGraph of graph:DiagJson.TerminalExecutableGraphState<DiagJson.TerminalOutcomeKind>
            | CrossKindThrashAllowedSchedulerCausalDeadGraph of graph:DiagJson.TerminalExecutableGraphState<DiagJson.TerminalOutcomeKind> * rootAgeMs:int

        type CrossKindYieldThrashArbitration = {
            rawDecision : CrossKindYieldThrashDecisionId
            decision : CrossKindYieldThrashDecisionId
            authority : CrossKindYieldThrashAuthority
            participants : CrossKindYieldThrashParticipants
            graph : DiagJson.TerminalExecutableGraphState<DiagJson.TerminalOutcomeKind>
            boundExecutableGraphExhausted : bool
        }

        let private crossKindYieldThrashDecisionText = function
            | CrossKindYieldThrashPromoteRequeue -> "promote_requeue"
            | CrossKindYieldThrashDeferFreshRootPendingTail -> "defer_fresh_root_pending_tail"
            | CrossKindYieldThrashDeferZeroRepeatActiveTail -> "defer_zero_repeat_active_tail"
            | CrossKindYieldThrashHardPoisonPendingZero -> "hard_poison_pending_zero"
            | CrossKindYieldThrashHardPoisonHotQueue -> "hard_poison_hot_queue"
            | CrossKindYieldThrashHardPoisonReentryCap -> "hard_poison_reentry_cap"
            | CrossKindYieldThrashHardPoisonObligationCap -> "hard_poison_obligation_cap"
            | CrossKindYieldThrashHardPoisonPostScheduleCap -> "hard_poison_post_schedule_cap"
            | CrossKindYieldThrashHardPoisonStaleRetargetObligation -> "hard_poison_stale_retarget_obligation"
            | CrossKindYieldThrashHardPoisonRootStalled -> "hard_poison_root_stalled"

        let private yieldThrashParticipantRoleText = function
            | YieldThrashIncoming -> "incoming"
            | YieldThrashHotQueueDominant -> "hot_queue_dominant"
            | YieldThrashParentContinuation -> "parent_continuation"
            | YieldThrashCrossKindSibling -> "cross_kind_sibling"

        let private yieldThrashParticipantText participant =
            FastRuntimeFormat.format "%s:%s:repeat=%d" [| box (yieldThrashParticipantRoleText participant.role); box (anyReplayKeyText participant.key); box participant.repeatCount |]

        let private crossKindYieldThrashParticipantsText participants =
            let hotText =
                match participants.hotQueue with
                | Some hot -> yieldThrashParticipantText hot
                | None -> "none"
            FastRuntimeFormat.format "YieldThrashParticipants(incoming=%s|hot=%s|direction=%s|root_age_ms=%d)" [| box (yieldThrashParticipantText participants.incoming); box hotText; box (hotReplayObligationText participants.direction); box participants.rootReceiptAgeMs |]

        let private crossKindYieldThrashAuthorityText = function
            | CrossKindThrashContinueProgressingGraph -> "CrossKindThrashAuthority(ContinueProgressingGraph)"
            | CrossKindThrashDeferredBoundGraph graph ->
                "CrossKindThrashAuthority(DeferredBoundGraph|graph=" + DiagJson.terminalExecutableGraphStateText graph + ")"
            | CrossKindThrashAllowedExhaustedGraph graph ->
                "CrossKindThrashAuthority(AllowedExhaustedGraph|graph=" + DiagJson.terminalExecutableGraphStateText graph + ")"
            | CrossKindThrashAllowedSchedulerCausalDeadGraph(graph, rootAgeMs) ->
                sprintf "CrossKindThrashAuthority(AllowedSchedulerCausalDeadGraph|root_age_ms=%d|graph=%s)" rootAgeMs (DiagJson.terminalExecutableGraphStateText graph)

        let private crossKindYieldThrashDecisionIsHardPoison = function
            | CrossKindYieldThrashHardPoisonPendingZero
            | CrossKindYieldThrashHardPoisonHotQueue
            | CrossKindYieldThrashHardPoisonReentryCap
            | CrossKindYieldThrashHardPoisonObligationCap
            | CrossKindYieldThrashHardPoisonPostScheduleCap
            | CrossKindYieldThrashHardPoisonStaleRetargetObligation
            | CrossKindYieldThrashHardPoisonRootStalled -> true
            | _ -> false

        let private hotQueueReplayKey (hotQueue:HotQueueSample) : AnyReplayKey option =
            match hotQueue.hotQueueBucket with
            | None -> None
            | Some bucket ->
                let node =
                    match hotQueue.hotQueueNodeId with
                    | HotQueueNode nodeId -> ReplayNodeKnown(NodeId nodeId)
                    | HotQueueDominantNodeUnknown -> ReplayNodeSynthetic ReplayNodeUnresolved
                let bucketText = hotQueueBucketText bucket
                let hotKey = ReplayKeyIdOps.create ("hot:" + bucketText)
                let key : ReplayKey<CrossKindReplayK> =
                    { node = node
                      kind = ReplayKindUnknown (CompilerKernelV2.OperationalReasonIdOps.create bucketText)
                      shape = ReplayShapeUnknown
                      site = ReplaySiteKnown CompilerIdentityKernel.WorkSiteIdOps.Known.replayQueueHotSample
                      stableKey = replayStableKey<CrossKindReplayK> (Some hotKey) }
                Some(AnyCrossKindReplayKey key)

        let private crossKindYieldThrashDecisionFor
            (incomingKey:AnyReplayKey)
            (liveness:ReplayLivenessSnapshot)
            (hotQueue:HotQueueSample)
            (evidence:CrossKindReentryEvidence)
            : CrossKindYieldThrashArbitration =
            let repeatCap = 4
            let rootStalled = evidence.lastRootReceiptAgeMs >= 500
            let capBreached = evidence.effectiveReentryCount > repeatCap
            let sameHotCapBreached = evidence.sameHotNodeCount >= repeatCap
            let freshPendingTail =
                liveness.pending > 0
                && evidence.lastRootReceiptAgeMs >= 0
                && evidence.lastRootReceiptAgeMs < 5000
                && (liveness.queueDepth > 0 || liveness.activeDepth > 0 || liveness.hasProgressYield)
            let zeroRepeatActiveTail =
                evidence.effectiveReentryCount < repeatCap
                && liveness.activeDepth > 0
                && (liveness.queueDepth > 0 || liveness.pending > 0 || liveness.hasProgressYield || evidence.rootReceiptCount > 0)
                && evidence.lastRootReceiptAgeMs >= 0
                && evidence.lastRootReceiptAgeMs < 5000
            let schedulerCausalDeadTail =
                evidence.lastRootReceiptAgeMs >= 30000
                && liveness.pending > 0
                && liveness.queueDepth > 0
                && liveness.activeDepth > 0
                && liveness.hasDeferredCell
                && liveness.hasProgressYield
            let repeatedOpenOwnerTail =
                evidence.lastRootReceiptAgeMs >= 5000
                && liveness.pending > 0
                && (liveness.queueDepth > 0 || liveness.activeDepth > 0 || liveness.hasDeferredCell || liveness.hasProgressYield)
                && (evidence.effectiveReentryCount >= 4 || evidence.sameHotNodeCount >= 2)
            let decision =
                if schedulerCausalDeadTail || repeatedOpenOwnerTail then
                    CrossKindYieldThrashHardPoisonRootStalled
                elif freshPendingTail && (capBreached || sameHotCapBreached) then
                    CrossKindYieldThrashDeferFreshRootPendingTail
                elif zeroRepeatActiveTail then
                    CrossKindYieldThrashDeferZeroRepeatActiveTail
                else
                    match evidence.evidenceId with
                    | _ when rootStalled && capBreached -> CrossKindYieldThrashHardPoisonObligationCap
                    | _ when rootStalled && sameHotCapBreached -> CrossKindYieldThrashHardPoisonReentryCap
                    | CrossKindReentryRootStalled ms when ms >= 500 && evidence.effectiveReentryCount >= 8 -> CrossKindYieldThrashHardPoisonRootStalled
                    | CrossKindReentrySameHotNode n when n >= repeatCap -> CrossKindYieldThrashHardPoisonReentryCap
                    | CrossKindReentryQueueSurge q when q >= 64 && evidence.lastRootReceiptAgeMs >= 500 -> CrossKindYieldThrashHardPoisonRootStalled
                    | _ ->
                        if evidence.effectiveReentryCount > repeatCap && liveness.activeDepth > 0 then CrossKindYieldThrashHardPoisonObligationCap
                        elif hotQueue.hotQueueCount >= repeatCap then CrossKindYieldThrashHardPoisonReentryCap
                        elif liveness.pending = 0 && (liveness.queueDepth > 0 || liveness.activeDepth > 0) then
                            if hotQueue.hotQueueCount >= repeatCap then CrossKindYieldThrashHardPoisonHotQueue
                            else CrossKindYieldThrashHardPoisonPendingZero
                        else CrossKindYieldThrashPromoteRequeue
            let hotParticipant =
                hotQueueReplayKey hotQueue
                |> Option.map (fun key ->
                    { role = YieldThrashHotQueueDominant
                      key = key
                      repeatCount = int64 hotQueue.hotQueueCount })
            let incomingKindId = incomingKey |> anyReplayKeyKind
            let hotKindId =
                hotParticipant
                |> Option.map (fun participant -> participant.key |> anyReplayKeyKind)
                |> Option.defaultValue (ReplayKindUnknown (CompilerKernelV2.OperationalReasonIdOps.create "hot_queue_missing"))
            let participants =
                { incoming =
                    { role = YieldThrashIncoming
                      key = incomingKey
                      repeatCount = int64 evidence.effectiveReentryCount }
                  hotQueue = hotParticipant
                  direction = hotReplayObligationForTyped hotKindId incomingKindId
                  rootReceiptAgeMs = int64 evidence.lastRootReceiptAgeMs }
            let graph =
                DiagJson.terminalExecutableGraphFor<DiagJson.TerminalOutcomeKind>
                    (DiagJson.canonicalTerminalClosureId<DiagJson.TerminalOutcomeKind> (anyReplayKeyText incomingKey))
                    (int64 liveness.pending)
                    (int64 liveness.queueDepth)
                    (int64 liveness.activeDepth)
                    (if hotReplayObligationText participants.direction = "cross_kind_unknown" then 0L else 1L)
                    liveness.hasDeferredCell
                    liveness.hasProgressYield
                    (DiagJson.terminalGraphEpoch<DiagJson.TerminalOutcomeKind> (int64 evidence.rootReceiptCount))
                    (int64 evidence.sameHotNodeCount)
                    (evidence.lastRootReceiptAgeMs >= 0 && evidence.lastRootReceiptAgeMs < 500)
                    DiagJson.TerminalGraphClosureUnproven
            let exhausted =
                match graph with
                | DiagJson.TerminalGraphExhaustedState _ -> true
                | _ -> false
            let effectiveDecision, authority =
                let hardPoisonAgedOpenOwnerTail =
                    crossKindYieldThrashDecisionIsHardPoison decision
                    && (schedulerCausalDeadTail || repeatedOpenOwnerTail)
                if schedulerCausalDeadTail || repeatedOpenOwnerTail || hardPoisonAgedOpenOwnerTail then
                    CrossKindYieldThrashHardPoisonRootStalled, CrossKindThrashAllowedSchedulerCausalDeadGraph(graph, evidence.lastRootReceiptAgeMs)
                elif crossKindYieldThrashDecisionIsHardPoison decision && not exhausted then
                    let deferredDecision =
                        if liveness.pending > 0 then CrossKindYieldThrashDeferFreshRootPendingTail
                        else CrossKindYieldThrashDeferZeroRepeatActiveTail
                    deferredDecision, CrossKindThrashDeferredBoundGraph graph
                elif crossKindYieldThrashDecisionIsHardPoison decision then
                    decision, CrossKindThrashAllowedExhaustedGraph graph
                else
                    decision, CrossKindThrashContinueProgressingGraph
            { rawDecision = decision
              decision = effectiveDecision
              authority = authority
              participants = participants
              graph = graph
              boundExecutableGraphExhausted = exhausted }

        // MIGRATION: dynamic-join reentrant replay hard poison requires a full
        // all-empty liveness proof.  The 1770 assessment showed pending=0 while
        // queueDepth/activeDepth were still live; that is scheduler progress, not
        // terminal evidence.  Make the proof algebraic before JSON/HUD rendering.
        type ReentrantReplayLivelockDecisionId =
            | ReentrantReplayContinueActive of blocker:string
            | ReentrantReplayScheduleDrain of blocker:string
            | ReentrantReplayHardPoisonPendingZero of proof:CompilerKernelV2.OperationalReasonId

        let replayMaterialLivenessAllEmpty (liveness: ReplayLivenessSnapshot) =
            liveness.pending = 0
            && liveness.queueDepth = 0
            && liveness.activeDepth = 0
            && not liveness.hasDeferredCell

        let replayLivenessAllEmpty (liveness: ReplayLivenessSnapshot) =
            replayMaterialLivenessAllEmpty liveness
            && not liveness.hasProgressYield

        let replayLivenessProofText (liveness: ReplayLivenessSnapshot) =
            liveness |> replayLivenessProof<ReentrantReplayK> "reentrant_replay_driver" |> replayLivenessProofDuText

        let private reentrantReplayLivelockDecisionText = function
            | ReentrantReplayContinueActive blocker -> "continue_active|blocker=" + replayNonEmptyOr "live_replay" blocker
            | ReentrantReplayScheduleDrain blocker -> "schedule_drain|blocker=" + replayNonEmptyOr "live_queue_or_active_driver" blocker
            | ReentrantReplayHardPoisonPendingZero proof -> "hard_poison_pending_zero|proof=" + CompilerKernelV2.OperationalReasonIdOps.text proof

        let private reentrantReplayLivelockDecisionFor (liveness: ReplayLivenessSnapshot) =
            if replayLivenessAllEmpty liveness then
                ReentrantReplayHardPoisonPendingZero (replayLivenessProofText liveness |> CompilerKernelV2.OperationalReasonIdOps.create)
            elif liveness.activeDepth > 0 then
                ReentrantReplayContinueActive (replayLivenessProofText liveness)
            elif liveness.queueDepth > 0 || liveness.hasDeferredCell || liveness.hasProgressYield then
                ReentrantReplayScheduleDrain (replayLivenessProofText liveness)
            else
                ReentrantReplayContinueActive (replayLivenessProofText liveness)

        let private replayObligationKindText = function
            | ReplayObligationRun -> "run"
            | ReplayObligationDefer -> "defer"
            | ReplayObligationBlock -> "block"

        let private replayObligationStatusText (obligation:ReplayObligation) =
            match obligation.obligation with
            | ReplayObligationRun -> "semantic_replay_obligation_run"
            | ReplayObligationDefer -> "semantic_replay_obligation_deferred"
            | ReplayObligationBlock -> "semantic_replay_obligation_blocked"

        let captureReplayLiveness () =
            let pending = pendingCount()
            let queueDepth = replayQueueDepth()
            let activeDepth = lock gate (fun () -> replayDriverActiveDepth)
            let hasDeferredCell = EvalReplayValueStore.hasDeferredReplayCell()
            let hasProgressYield = hasProgressYield()
            let kind =
                if hasProgressYield then ReplayObligationProgressYield
                elif hasDeferredCell then ReplayObligationDeferredCell
                elif activeDepth > 0 then ReplayObligationActive
                elif queueDepth > 0 then ReplayObligationQueued
                elif pending > 0 then ReplayObligationPendingOnly
                else ReplayObligationQuiescent
            { pending = pending
              queueDepth = queueDepth
              activeDepth = activeDepth
              payloadStatus = ReplayLivenessPayloadAvailability (semanticPayloadAvailabilityId ())
              hasDeferredCell = hasDeferredCell
              hasProgressYield = hasProgressYield
              kind = kind }

        let replayQuiescenceLivenessNormalizationText = function
            | ReplayQuiescenceMaterialReplayOpen -> "material_replay_open"
            | ReplayQuiescenceAlreadyClosed -> "already_closed"
            | ReplayQuiescenceProgressYieldResidueRetired retiredCount ->
                FastRuntimeFormat.format "progress_yield_residue_retired(count=%d)" [| box retiredCount |]

        let replayQuiescenceLivenessRetiredProgressYieldCount = function
            | ReplayQuiescenceProgressYieldResidueRetired retiredCount -> retiredCount
            | ReplayQuiescenceMaterialReplayOpen
            | ReplayQuiescenceAlreadyClosed -> 0

        // Quiescence is allowed to retire retry-stop residue, never material replay.
        // progressYieldCount is explicitly a BuildFile retry hint rather than semantic
        // evidence. Re-snapshot after draining it so a concurrently materialized replay
        // still vetoes semantic-credit reconciliation.
        let normalizeReplayLivenessForQuiescence () =
            let before = captureReplayLiveness ()
            let decision =
                if not (replayMaterialLivenessAllEmpty before) then
                    ReplayQuiescenceMaterialReplayOpen
                elif before.hasProgressYield then
                    ReplayQuiescenceProgressYieldResidueRetired (drainProgressYield ())
                else
                    ReplayQuiescenceAlreadyClosed
            let after =
                match decision with
                | ReplayQuiescenceProgressYieldResidueRetired _ -> captureReplayLiveness ()
                | ReplayQuiescenceMaterialReplayOpen
                | ReplayQuiescenceAlreadyClosed -> before
            { before = before
              after = after
              decision = decision }


        // MIGRATION: must be defined before emitReplayObligation, which now
        // reports hot_oblig_du from the active ReplayTask.
        let private replayTaskDriverKindId (task:ReplayTask) =
            match replayFrontierKindOfDriver task.driver with
            | ReplayFrontierTerm -> ReplayKindTerm
            | ReplayFrontierTy -> ReplayKindTy
            | ReplayFrontierUnknown -> ReplayKindUnknown (CompilerKernelV2.OperationalReasonIdOps.create (replayDriverToString task.driver))


        let private replayCellStableKey (cell:ReplayCell) =
            FastRuntimeFormat.format "%s:%s:%d:%s:%d:%d" [| box (evalKindToString cell.kind); box (replayCellShapeText cell); box cell.nodeId; box (replayCellSiteText cell); box cell.cursor; box cell.step |]

        let private anyReplayKeyFromCell (cell:ReplayCell) : AnyReplayKey =
            match replayCellEvalKindId cell with
            | EvalTerm -> AnyTermReplayKey(replayKeyOf<TermReplayK> cell.nodeId cell.shape cell.site (replayCellStableKey cell))
            | EvalTy -> AnyTyReplayKey(replayKeyOf<TyReplayK> cell.nodeId cell.shape cell.site (replayCellStableKey cell))
            | _ -> AnyCrossKindReplayKey(replayKeyOf<CrossKindReplayK> cell.nodeId cell.shape cell.site (replayCellStableKey cell))

        let private anyReplayKeyShape = function
            | AnyTermReplayKey key -> replayShapeIdText key.shape
            | AnyTyReplayKey key -> replayShapeIdText key.shape
            | AnyDynamicJoinReplayKey key -> replayShapeIdText key.shape
            | AnyParentResumeReplayKey key -> replayShapeIdText key.shape
            | AnyTerminalContractReplayKey key -> replayShapeIdText key.shape
            | AnyTerminalContractEmissionReplayKey key -> replayShapeIdText key.shape
            | AnyCrossKindReplayKey key -> replayShapeIdText key.shape

        let private anyReplayKeySite = function
            | AnyTermReplayKey key -> replaySiteIdText key.site
            | AnyTyReplayKey key -> replaySiteIdText key.site
            | AnyDynamicJoinReplayKey key -> replaySiteIdText key.site
            | AnyParentResumeReplayKey key -> replaySiteIdText key.site
            | AnyTerminalContractReplayKey key -> replaySiteIdText key.site
            | AnyTerminalContractEmissionReplayKey key -> replaySiteIdText key.site
            | AnyCrossKindReplayKey key -> replaySiteIdText key.site

        let private anyReplayKeyNode = function
            | AnyTermReplayKey key -> replayNodeIdentityText key.node
            | AnyTyReplayKey key -> replayNodeIdentityText key.node
            | AnyDynamicJoinReplayKey key -> replayNodeIdentityText key.node
            | AnyParentResumeReplayKey key -> replayNodeIdentityText key.node
            | AnyTerminalContractReplayKey key -> replayNodeIdentityText key.node
            | AnyTerminalContractEmissionReplayKey key -> replayNodeIdentityText key.node
            | AnyCrossKindReplayKey key -> replayNodeIdentityText key.node

        let inline private replayKeyFromFrame< ^K when ^K : (static member ReplayKindId : unit -> ReplayKindId)> (frame:Frame) : ReplayKey< ^K> =
            let keyId =
                if ReplayKeyIdOps.slot frame.key = ReplayKeyIdOps.slot ReplayKeyIdOps.Known.empty then None
                else Some frame.key
            let siteId = replaySiteIdFor frame.site
            { node = replayNodeIdentityFor< ^K> -1 siteId keyId
              kind = replayKindIdFor< ^K> (frameWorkShapeId frame)
              shape = ReplayShapeFromEvalKind frame.kind
              site = siteId
              stableKey = replayStableKey< ^K> keyId }

        let private crossKindReplayObligationFor (frame:Frame) (cell:ReplayCell) : CrossKindReplayObligation =
            match frame.kind, cell.kind with
            | EvalTerm, EvalTy ->
                ReplayTermToTy(
                    replayKeyFromFrame<TermReplayK> frame,
                    replayKeyOf<TyReplayK> cell.nodeId cell.shape cell.site (replayCellStableKey cell))
            | EvalTy, EvalTerm ->
                ReplayTyToTerm(
                    replayKeyFromFrame<TyReplayK> frame,
                    replayKeyOf<TermReplayK> cell.nodeId cell.shape cell.site (replayCellStableKey cell))
            | EvalTy, EvalParentResume ->
                ReplayTyToParent(
                    replayKeyFromFrame<TyReplayK> frame,
                    replayKeyOf<ParentResumeReplayK> cell.nodeId cell.shape cell.site (replayCellStableKey cell))
            | EvalDynamicJoin, _ ->
                ReplayDynamicJoinToParent(
                    replayKeyFromFrame<DynamicJoinK> frame,
                    replayKeyOf<ParentResumeReplayK> cell.nodeId cell.shape cell.site (replayCellStableKey cell))
            | _ ->
                ReplayCrossKindUnresolved(
                    AnyCrossKindReplayKey(replayKeyFromFrame<CrossKindReplayK> frame),
                    Some(anyReplayKeyFromCell cell))

        let private crossKindReplayObligationText = function
            | ReplayTermToTy(source, target) ->
                "CrossKindReplayObligation(TermToTy|source=" + replayKeyDuText source + "|target=" + replayKeyDuText target + ")"
            | ReplayTyToTerm(source, target) ->
                "CrossKindReplayObligation(TyToTerm|source=" + replayKeyDuText source + "|target=" + replayKeyDuText target + ")"
            | ReplayTyToParent(source, target) ->
                "CrossKindReplayObligation(TyToParent|source=" + replayKeyDuText source + "|target=" + replayKeyDuText target + ")"
            | ReplayDynamicJoinToParent(source, target) ->
                "CrossKindReplayObligation(DynamicJoinToParent|source=" + replayKeyDuText source + "|target=" + replayKeyDuText target + ")"
            | ReplayCrossKindUnresolved(source, target) ->
                "CrossKindReplayObligation(Unresolved|source=" + anyReplayKeyText source + "|target=" + (target |> Option.map anyReplayKeyText |> Option.defaultValue "none") + ")"

        let private crossKindWakeForEdgeFor = function
            | ReplayTermToTy(source, target) -> WakeTermWaitsForTy(source, target, None)
            | ReplayTyToTerm(source, target) -> WakeTyWaitsForTerm(source, target, None)
            | ReplayTyToParent(source, target) -> WakeTyWaitsForParent(source, target, None)
            | ReplayDynamicJoinToParent(source, target) -> WakeDynamicJoinWaitsForParent(source, target, None)
            | ReplayCrossKindUnresolved(source, target) -> WakeCrossKindUnresolved(source, target, None)

        let private crossKindWakeRefText =
            Option.map CompilerIdentityKernel.ContentDigest.text
            >> Option.defaultValue "none"

        let private crossKindWakeForEdgeText = function
            | WakeTermWaitsForTy(source, target, ivarRef) ->
                "WakeForEdge(Term->Ty|source=" + replayKeyDuText source + "|target=" + replayKeyDuText target + "|ivar=" + crossKindWakeRefText ivarRef + ")"
            | WakeTyWaitsForTerm(source, target, ivarRef) ->
                "WakeForEdge(Ty->Term|source=" + replayKeyDuText source + "|target=" + replayKeyDuText target + "|ivar=" + crossKindWakeRefText ivarRef + ")"
            | WakeTyWaitsForParent(source, target, ivarRef) ->
                "WakeForEdge(Ty->Parent|source=" + replayKeyDuText source + "|target=" + replayKeyDuText target + "|ivar=" + crossKindWakeRefText ivarRef + ")"
            | WakeDynamicJoinWaitsForParent(source, target, ivarRef) ->
                "WakeForEdge(DynamicJoin->Parent|source=" + replayKeyDuText source + "|target=" + replayKeyDuText target + "|ivar=" + crossKindWakeRefText ivarRef + ")"
            | WakeCrossKindUnresolved(source, target, ivarRef) ->
                "WakeForEdge(Unresolved|source=" + anyReplayKeyText source + "|target=" + (target |> Option.map anyReplayKeyText |> Option.defaultValue "none") + "|ivar=" + crossKindWakeRefText ivarRef + ")"

        type CrossKindReplayObligationEnvelope = {
            obligationRef : CompilerIdentityKernel.ContentDigest
            obligation : CrossKindReplayObligation
            wakeForEdge : CrossKindWakeForEdge
            firstSeenMs : int64
            lastSeenMs : int64
            repeatCount : int64
        }

        type CrossKindReplayAdmissionId =
            | CrossKindReplayAdmissionFirst
            | CrossKindReplayAdmissionAfterOwnerQuiescence of repeatCount:int64
            | CrossKindReplayAdmissionCoalescedIntoActiveOwner of repeatCount:int64
            | CrossKindReplayAdmissionForceSemanticTieBreaker of repeatCount:int64
            | CrossKindReplayAdmissionProceduralCycleExhausted of repeatCount:int64

        type SemanticDebtDrainBudgetId =
            | SemanticDebtDrainCrossKindTieBreaker of attempts:int
            | SemanticDebtDrainClosureProbe of attempts:int

        let semanticDebtDrainBudgetValue = function
            | SemanticDebtDrainCrossKindTieBreaker attempts
            | SemanticDebtDrainClosureProbe attempts -> attempts

        let private semanticDebtDrainBudgetText = function
            | SemanticDebtDrainCrossKindTieBreaker attempts -> sprintf "SemanticDebtDrainBudget(CrossKindTieBreaker|attempts=%d)" attempts
            | SemanticDebtDrainClosureProbe attempts -> sprintf "SemanticDebtDrainBudget(ClosureProbe|attempts=%d)" attempts

        let private crossKindReplayAdmissionText = function
            | CrossKindReplayAdmissionFirst -> "CrossKindReplayAdmission(First)"
            | CrossKindReplayAdmissionAfterOwnerQuiescence repeatCount -> sprintf "CrossKindReplayAdmission(AfterOwnerQuiescence|repeat=%d)" repeatCount
            | CrossKindReplayAdmissionCoalescedIntoActiveOwner repeatCount -> sprintf "CrossKindReplayAdmission(CoalescedIntoActiveOwner|repeat=%d)" repeatCount
            | CrossKindReplayAdmissionForceSemanticTieBreaker repeatCount -> sprintf "CrossKindReplayAdmission(ForceSemanticTieBreaker|repeat=%d)" repeatCount
            | CrossKindReplayAdmissionProceduralCycleExhausted repeatCount -> sprintf "CrossKindReplayAdmission(ProceduralCycleExhausted|repeat=%d)" repeatCount

        let private crossKindReplayAdmissionAllowsSchedule = function
            | CrossKindReplayAdmissionFirst
            | CrossKindReplayAdmissionAfterOwnerQuiescence _ -> true
            | CrossKindReplayAdmissionCoalescedIntoActiveOwner _
            | CrossKindReplayAdmissionForceSemanticTieBreaker _
            | CrossKindReplayAdmissionProceduralCycleExhausted _ -> false

        let private crossKindReplayAdmissionIsLogMilestone repeatCount =
            repeatCount <= 3L
            || (repeatCount > 0L && (repeatCount &&& (repeatCount - 1L)) = 0L)
            || repeatCount % 64L = 0L

        let private crossKindReplayObligationLedger =
            System.Collections.Concurrent.ConcurrentDictionary<CrossKindReplayObligation,CrossKindReplayObligationEnvelope>()

        let private stableCrossKindObligationRef (obligation:CrossKindReplayObligation) =
            obligation
            |> crossKindReplayObligationText
            |> CompilerIdentityKernel.ContentDigest.ofText "cross-kind-replay-obligation"

        let private noteCrossKindReplayObligation (obligation:CrossKindReplayObligation) =
            let nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let obligationRef = stableCrossKindObligationRef obligation
            crossKindReplayObligationLedger.AddOrUpdate(
                obligation,
                (fun _ ->
                    { obligationRef = obligationRef
                      obligation = obligation
                      wakeForEdge = crossKindWakeForEdgeFor obligation
                      firstSeenMs = nowMs
                      lastSeenMs = nowMs
                      repeatCount = 1L }),
                (fun _ prior ->
                    { prior with
                        lastSeenMs = nowMs
                        repeatCount = prior.repeatCount + 1L }))

        let private currentCrossKindReplayObligationEnvelope (obligation:CrossKindReplayObligation) =
            match crossKindReplayObligationLedger.TryGetValue obligation with
            | true, envelope -> envelope
            | false, _ -> noteCrossKindReplayObligation obligation

        let private crossKindReplayAdmissionFor (envelope:CrossKindReplayObligationEnvelope) (liveness:ReplayLivenessSnapshot) =
            let activity = DiagJson.ownerDebtActivitySnapshotNow()
            match DiagJson.ownerDebtProceduralExhaustionFor liveness.queueDepth liveness.activeDepth liveness.pending envelope.repeatCount activity with
            | DiagJson.OwnerDebtProceduralExhausted _ -> CrossKindReplayAdmissionProceduralCycleExhausted envelope.repeatCount
            | DiagJson.OwnerDebtProceduralOpen when envelope.repeatCount <= 1L -> CrossKindReplayAdmissionFirst
            | DiagJson.OwnerDebtProceduralOpen when envelope.repeatCount >= 8L && envelope.repeatCount % 8L = 0L -> CrossKindReplayAdmissionForceSemanticTieBreaker envelope.repeatCount
            | DiagJson.OwnerDebtProceduralOpen when liveness.activeDepth > 0 -> CrossKindReplayAdmissionCoalescedIntoActiveOwner envelope.repeatCount
            | DiagJson.OwnerDebtProceduralOpen -> CrossKindReplayAdmissionAfterOwnerQuiescence envelope.repeatCount

        let private crossKindReplayObligationRefText envelope =
            CompilerIdentityKernel.ContentDigest.text envelope.obligationRef

        let private crossKindReplayObligationEnvelopeText envelope =
            FastRuntimeFormat.format "CrossKindReplayObligationEnvelope(id=%s|repeat=%d|first_ms=%d|last_ms=%d|obligation=%s|wait_for_edge=%s)" [| box (crossKindReplayObligationRefText envelope); box envelope.repeatCount; box envelope.firstSeenMs; box envelope.lastSeenMs; box (crossKindReplayObligationText envelope.obligation); box (crossKindWakeForEdgeText envelope.wakeForEdge) |]

        let private crossKindReplayObligationLedgerSummary () =
            let mutable hotId = "none"
            let mutable hotRepeat = 0L
            let mutable totalRepeat = 0L
            for kv in crossKindReplayObligationLedger do
                totalRepeat <- totalRepeat + kv.Value.repeatCount
                if kv.Value.repeatCount > hotRepeat then
                    hotRepeat <- kv.Value.repeatCount
                    hotId <- crossKindReplayObligationRefText kv.Value
            FastRuntimeFormat.format "CrossKindReplayLedger(entries=%d|total_repeat=%d|hot_id=%s|hot_repeat=%d)" [| box crossKindReplayObligationLedger.Count; box totalRepeat; box hotId; box hotRepeat |]

        type CrossKindReplayHotSnapshot = {
            obligationId : string
            repeatCount : int64
            ageMs : int64
            obligationText : string
            sourceSite : string
            targetSite : string
            targetNode : string
        }

        let private crossKindReplayObligationEndpoints = function
            | ReplayTermToTy(source, target) -> replaySiteIdText source.site, replaySiteIdText target.site, replayNodeIdentityText target.node
            | ReplayTyToTerm(source, target) -> replaySiteIdText source.site, replaySiteIdText target.site, replayNodeIdentityText target.node
            | ReplayTyToParent(source, target) -> replaySiteIdText source.site, replaySiteIdText target.site, replayNodeIdentityText target.node
            | ReplayDynamicJoinToParent(source, target) -> replaySiteIdText source.site, replaySiteIdText target.site, replayNodeIdentityText target.node
            | ReplayCrossKindUnresolved(source, target) ->
                anyReplayKeySite source,
                (target |> Option.map anyReplayKeySite |> Option.defaultValue "unknown"),
                (target |> Option.map anyReplayKeyNode |> Option.defaultValue "unknown")

        let crossKindReplayHotSnapshotNow () : CrossKindReplayHotSnapshot option =
            let mutable hot : CrossKindReplayObligationEnvelope option = None
            for kv in crossKindReplayObligationLedger do
                match hot with
                | Some prior when prior.repeatCount >= kv.Value.repeatCount -> ()
                | _ -> hot <- Some kv.Value
            hot
            |> Option.map (fun envelope ->
                let sourceSite, targetSite, targetNode = crossKindReplayObligationEndpoints envelope.obligation
                { obligationId = crossKindReplayObligationRefText envelope
                  repeatCount = envelope.repeatCount
                  ageMs = max 0L (DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - envelope.firstSeenMs)
                  obligationText = crossKindReplayObligationText envelope.obligation
                  sourceSite = sourceSite
                  targetSite = targetSite
                  targetNode = targetNode })

        type private ReplayKeyAppDigestVisitor() =
            interface IReplayKeyAppVisitor<uint32> with
                member _.Visit<'K>(app:App<ReplayKeyF,'K>) =
                    match app with
                    | :? ReplayKeyApp<'K> as boxed ->
                        let key = boxed.Value
                        NativeCutoverStableRef.ref32
                            "replay-key-hkt-app"
                            [ replayKindIdText key.kind
                              replayShapeIdText key.shape
                              replaySiteIdText key.site
                              replayNodeIdentityText key.node
                              replayStableKeyText key.stableKey ]
                    | _ -> invalidOp "replay key HKT witness mismatch"

        let private replayKeyAppDigest (target:ISomeReplayKeyApp) =
            target.Accept<uint32>(ReplayKeyAppDigestVisitor())

        let private someReplayKeyAppOfAnyReplayKey = function
            | AnyTermReplayKey key -> someReplayKeyApp key
            | AnyTyReplayKey key -> someReplayKeyApp key
            | AnyDynamicJoinReplayKey key -> someReplayKeyApp key
            | AnyParentResumeReplayKey key -> someReplayKeyApp key
            | AnyTerminalContractReplayKey key -> someReplayKeyApp key
            | AnyTerminalContractEmissionReplayKey key -> someReplayKeyApp key
            | AnyCrossKindReplayKey key -> someReplayKeyApp key

        let private replayObligationTargetFromCell (cell:ReplayCell) =
            let target : ISomeReplayKeyApp =
                match replayCellEvalKindId cell with
                | EvalTerm -> someReplayKeyApp (replayKeyOf<TermReplayK> cell.nodeId cell.shape cell.site (replayCellStableKey cell))
                | EvalTy -> someReplayKeyApp (replayKeyOf<TyReplayK> cell.nodeId cell.shape cell.site (replayCellStableKey cell))
                | _ when replayCellEvalKindId cell = EvalDynamicJoin -> someReplayKeyApp (replayKeyOf<DynamicJoinK> cell.nodeId cell.shape cell.site (replayCellStableKey cell))
                | _ -> someReplayKeyApp (replayKeyOf<ParentResumeReplayK> cell.nodeId cell.shape cell.site (replayCellStableKey cell))
            ReplayObligationTypedTarget target

        let private replayObligationTargetKey = function
            | ReplayObligationTypedTarget target -> target
            | ReplayObligationCrossKindTarget(ReplayTermToTy(_, target)) -> someReplayKeyApp target
            | ReplayObligationCrossKindTarget(ReplayTyToTerm(_, target)) -> someReplayKeyApp target
            | ReplayObligationCrossKindTarget(ReplayTyToParent(_, target)) -> someReplayKeyApp target
            | ReplayObligationCrossKindTarget(ReplayDynamicJoinToParent(_, target)) -> someReplayKeyApp target
            | ReplayObligationCrossKindTarget(ReplayCrossKindUnresolved(source, Some target)) -> someReplayKeyAppOfAnyReplayKey target
            | ReplayObligationCrossKindTarget(ReplayCrossKindUnresolved(source, None)) -> someReplayKeyAppOfAnyReplayKey source

        let private replayDriverForKindId = function
            | ReplayKindTerm -> TermReplayDriver
            | ReplayKindTy -> TyReplayDriver
            | ReplayKindDynamicJoin -> DynamicJoinReplayDriver
            | ReplayKindParentResume -> ParentResumeReplayDriver
            | ReplayKindTerminalContract -> TerminalContractReplayDriver
            | ReplayKindTerminalContractEmission -> TerminalContractEmissionReplayDriver
            | ReplayKindReentrant
            | ReplayKindCrossKind
            | ReplayKindUnknown _ -> CrossKindUnresolvedReplayDriver

        let private replayObligationTargetDriver = function
            | ReplayObligationTypedTarget target -> replayDriverForKindId target.Kind
            | ReplayObligationCrossKindTarget(ReplayTermToTy _) -> TyReplayDriver
            | ReplayObligationCrossKindTarget(ReplayTyToTerm _) -> TermReplayDriver
            | ReplayObligationCrossKindTarget(ReplayTyToParent _)
            | ReplayObligationCrossKindTarget(ReplayDynamicJoinToParent _) -> ParentResumeReplayDriver
            | ReplayObligationCrossKindTarget(ReplayCrossKindUnresolved _) -> CrossKindUnresolvedReplayDriver

        let private makeReplayObligationWithTarget
            (obligation:ReplayObligationKind)
            (reason:ReplayObligationReasonId)
            (repeat:int)
            (cap:int)
            (target:ReplayObligationTarget)
            : ReplayObligation =
            { obligation = obligation
              target = target
              liveness = captureReplayLiveness()
              reason = reason
              repeat = repeat
              cap = cap }

        let private makeReplayObligation
            (obligation:ReplayObligationKind)
            (reason:ReplayObligationReasonId)
            (repeat:int)
            (cap:int)
            (cell:ReplayCell)
            : ReplayObligation =
            makeReplayObligationWithTarget obligation reason repeat cap (replayObligationTargetFromCell cell)

        let private crossKindReplayObligationFromArbitration (arbitration:CrossKindYieldThrashArbitration) =
            let target = arbitration.participants.hotQueue |> Option.map (fun participant -> participant.key)
            ReplayCrossKindUnresolved(arbitration.participants.incoming.key, target)

        let private emitReplayObligation
            (event:string)
            (kindName:string)
            (obligation:ReplayObligation) =
            let reasonText = replayObligationReasonText obligation.reason
            let targetKey = replayObligationTargetKey obligation.target
            let targetKind = targetKey.Kind
            let targetKeyText =
                FastRuntimeFormat.format "ReplayKey(kind=%s|shape=%s|site=%s|node=%s|key=%s)" [| box (replayKindIdText targetKind); box targetKey.ShapeText; box targetKey.SiteText; box targetKey.NodeText; box targetKey.KeyText |]
            let targetHktDigestRef = replayKeyAppDigest targetKey
            let activeDriverKind =
                lock gate (fun () ->
                    match replayQueue with
                    | activeTask :: _ -> replayTaskDriverKindId activeTask
                    | [] -> targetKind)
            let hotObligationDu =
                hotReplayObligationText (hotReplayObligationForTyped activeDriverKind targetKind)
            let targetDriver = replayObligationTargetDriver obligation.target
            let pStarvedMs = pendingStarvedMsSnapshot()
            let macroTerminalDecision = replayObligationMacroTerminalDecisionFor()
            DiagJson.emit (
                FastRuntimeFormat.format "{\"kind\":%s,\"event\":%s,\"status\":%s,\"obligation\":%s,\"reason\":%s,\"reason_du\":%s,\"liveness_du\":%s,\"target_replay_key_du\":%s,\"target_hkt_digest_ref\":%u,\"target_kind_du\":%s,\"target_shape\":%s,\"target_site\":%s,\"target_node_du\":%s,\"target_driver\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"payload_status\":%s,\"has_deferred_cell\":%b,\"has_progress_yield\":%b,\"repeat\":%d,\"cap\":%d,\"hot_oblig_du\":%s,\"p_starved_ms\":%d,\"macro_terminal_du\":%s,\"single_flight\":1,\"next\":%s}" [| box (esc kindName); box (esc event); box (esc (replayObligationStatusText obligation)); box (esc (replayObligationKindText obligation.obligation)); box (esc reasonText); box (esc reasonText); box (esc (replayObligationLivenessKindText obligation.liveness.kind)); box (esc targetKeyText); box targetHktDigestRef; box (esc (replayKindIdText targetKind)); box (esc targetKey.ShapeText); box (esc targetKey.SiteText); box (esc targetKey.NodeText); box (esc (replayDriverToString targetDriver)); box obligation.liveness.pending; box obligation.liveness.queueDepth; box obligation.liveness.activeDepth; box (esc (replayLivenessStatusText obligation.liveness.payloadStatus)); box obligation.liveness.hasDeferredCell; box obligation.liveness.hasProgressYield; box obligation.repeat; box obligation.cap; box (esc hotObligationDu); box pStarvedMs; box (esc (replayObligationMacroTerminalDecisionText macroTerminalDecision)); box (esc (replayDriverToString targetDriver)) |])



        let tryPinnedReplayPayloadMissing () =
            lock gate (fun () -> pinnedReplayPayloadMissing)

        // MIGRATION: distinguish local leaf value resolution from root replay completion.
        // MIGRATION proved the old gate was still too permissive: a single EV leaf could mark
        // semantic_leaf_complete, trigger retry_after_replay_root_complete if not gated, and let an unstable write
        // path emit a tiny residual. Until a parent-continuation stack proves the root frame, local
        // value resolutions are semantic_leaf_complete and remain fail-closed.
        let private replayPartialSemanticStatuses =
            [
                SemanticStepPartial
                SemanticOther(CompilerKernelV2.OperationalReasonIdOps.create "semantic_step_done")
                SemanticOther(CompilerKernelV2.OperationalReasonIdOps.create "semantic_leaf_complete")
                SemanticReplayObligationDeferred
                SemanticParentContinuationCycleBlocked
                SemanticTypeVariableValueMissingBlocked
                SemanticStaleRootRetargetBlocked
                SemanticReplayDriverExceptionBlocked
                SemanticReplayPayloadMissingBlocked
                SemanticRecordWithValueBlocked
                SemanticSeqTypeErrorBlocked
                SemanticReplayChildScheduleRepeatBlocked
                SemanticMacroThunkMissingBlocked
                SemanticTjoinpointStepperBlocked
                SemanticLiteralOpBodyStepperBlocked
                SemanticLetSuccessApplyExceptionBlocked
                SemanticLetSuccessAllReadyApplyBlocked
                SemanticLetSuccessApplyContinuationBlocked
                SemanticApplyContinuationExceptionBlocked
                SemanticDeferredFunctionReplayExceptionBlocked
            ]

        let private isReplayPartialSemanticStatus (status:FrameStatusId) =
            status
            |> frameStatusSemanticStatusId
            |> fun statusId -> List.contains statusId replayPartialSemanticStatuses

        let hasReplayPartial () =
            lock gate (fun () ->
                match frontier with
                | Some frame when isReplayPartialSemanticStatus frame.status -> true
                | Some frame ->
                    match frame.semanticCell with
                    | Some cell -> List.contains (cellSemanticStatusId cell) replayPartialSemanticStatuses
                    | None -> false
                | None -> false)

        let hasReplayComplete () =
            lock gate (fun () ->
                match frontier with
                | Some frame ->
                    frameStatusId frame = FrameSemanticRootComplete
                    || (match frame.semanticCell with
                        | Some cell -> frameStatusOfReplayCellStatusId cell.status = FrameSemanticRootComplete
                        | None -> false)
                | None -> false)

        // MIGRATION: root-complete witnesses are kind-local for evaluator returns.
        // MIGRATION proved a term frontier could complete, after which a ty entry
        // incorrectly treated that term completion as a missing type value.
        // Keep the global witness for coarse diagnostics/write gating, but require
        // the frame or attached cell to match the caller kind before returning ty/term.
        // MIGRATION: active fuses are also kind-local.  MIGRATION proved the completed-kind
        // reset, then exposed a live ty fuse (file_system.spi:993) being consumed by
        // term_entry_global_fuse as a missing term value.  Reset active cross-kind fuses
        // before value-missing diagnostics so the requested evaluator can proceed normally.
        let frameReplayCompleteKindId (kindId: EvalKind) (frame: Frame) =
            // MIGRATION: a frame-level semantic_root_complete is not a proof for a newly
            // attached same-kind cell unless that cell is also complete.  MIGRATION proved
            // the old rule can keep attempting build for listm.spi:6 while the live cell
            // is a different TJoinPoint' at runtime.spi:330.
            let cellComplete =
                match frame.semanticCell with
                | Some cell ->
                    replayCellEvalKindId cell = kindId
                    && frameStatusOfReplayCellStatusId cell.status = FrameSemanticRootComplete
                | None -> false
            let frameComplete =
                frameEvalKindId frame = kindId
                && frameStatusId frame = FrameSemanticRootComplete
                && (match frame.semanticCell with Some _ -> cellComplete | None -> true)
            frameComplete || cellComplete

        let frameReplayCompleteAny (frame: Frame) =
            let frameComplete = frameStatusId frame = FrameSemanticRootComplete
            let cellComplete =
                match frame.semanticCell with
                | Some cell -> frameStatusOfReplayCellStatusId cell.status = FrameSemanticRootComplete
                | None -> false
            frameComplete || cellComplete

        let private replayCellProgressIdentity (cell: ReplayCell) : ReplayCellProgressIdentity = {
            cell = replayCellIdentity cell
            status = frameStatusOfReplayCellStatusId cell.status
            cursor = cell.cursor
            step = cell.step
        }

        let private replayFrontierFingerprintIdentity (frame: Frame) : ReplayFrontierFingerprintIdentity = {
            kind = frameEvalKindId frame
            key = frame.key
            site = frame.site
            cursor = frame.cursor
            traceLength = frame.trace.Length
            status = frameStatusId frame
            queueDepth = replayQueue.Length
            cell = frame.semanticCell |> Option.map replayCellProgressIdentity
        }

        let private replayCellProgressIdentityText (progressOpt: ReplayCellProgressIdentity option) =
            match progressOpt with
            | Some progress ->
                FastRuntimeFormat.format "%s:%s:%s:cursor=%d:step=%d:site=%s" [| box (evalKindToString progress.cell.kind); box (CompilerIdentityKernel.WorkShapeIdOps.text progress.cell.shape); box (frameStatusToString progress.status); box progress.cursor; box progress.step; box (CompilerIdentityKernel.WorkSiteIdOps.text progress.cell.site) |]
            | None -> "cell:none"

        let private rootCompleteFingerprintIdentityText (identity: ReplayFrontierFingerprintIdentity) =
            FastRuntimeFormat.format "%s|%s|%s|cursor=%d|trace=%d|frame_status=%s|queue=%d|%s" [| box (evalKindToString identity.kind); box (ReplayKeyIdOps.text identity.key); box (CompilerIdentityKernel.WorkSiteIdOps.text identity.site); box identity.cursor; box identity.traceLength; box (frameStatusToString identity.status); box identity.queueDepth; box (replayCellProgressIdentityText identity.cell) |]

        let private selectedFrontierFingerprintIdentityText (identity: ReplayFrontierFingerprintIdentity) =
            FastRuntimeFormat.format "%s|%s|%s|status=%s|cursor=%d|trace=%d|queue=%d|%s" [| box (evalKindToString identity.kind); box (ReplayKeyIdOps.text identity.key); box (CompilerIdentityKernel.WorkSiteIdOps.text identity.site); box (frameStatusToString identity.status); box identity.cursor; box identity.traceLength; box identity.queueDepth; box (replayCellProgressIdentityText identity.cell) |]

        let private rootCompleteFingerprintLocked () =
            match frontier with
            | Some frame when frameReplayCompleteAny frame ->
                // MIGRATION: stable root-complete is semantic, but not oblivious to parent-continuation progress.
                // Keep node allocation ids out, while cursor/step/site remain structural fields.
                Some (replayFrontierFingerprintIdentity frame)
            | _ -> None

        let private selectedFrontierFingerprintLocked (frame: Frame) =
            replayFrontierFingerprintIdentity frame

        let private stableRootSelectedIdentityText (identity: StableRootSelectedIdentity) =
            rootCompleteFingerprintIdentityText identity.blockedRoot
            + "=>"
            + selectedFrontierFingerprintIdentityText identity.selected

        let private noteStableRootSelectedFrontierLocked (blockedRoot: ReplayFrontierFingerprintIdentity) (selected: Frame) =
            let identity : StableRootSelectedIdentity = {
                blockedRoot = blockedRoot
                selected = selectedFrontierFingerprintLocked selected
            }
            if stableRootSelectedKey = Some identity then
                stableRootSelectedCount <- stableRootSelectedCount + 1
            else
                stableRootSelectedKey <- Some identity
                stableRootSelectedCount <- 1
            stableRootSelectedCount, stableRootSelectedIdentityText identity

        let private noteSelectedFrontierStepperReplayLocked (identity: SelectedFrontierStepperReplayIdentity) =
            let mutable prior = 0
            let nextCount = if selectedFrontierStepperReplayAttempts.TryGetValue(identity, &prior) then prior + 1 else 1
            selectedFrontierStepperReplayAttempts.[identity] <- nextCount
            nextCount

        let noteRootCompleteHandoff () =
            lock gate (fun () ->
                match rootCompleteFingerprintLocked () with
                | None ->
                    stableRootCompleteKey <- None
                    stableRootCompleteCount <- 0
                    0, "none", Set.empty
                | Some identity ->
                    if stableRootCompleteKey = Some identity then
                        stableRootCompleteCount <- stableRootCompleteCount + 1
                    else
                        stableRootCompleteKey <- Some identity
                        stableRootCompleteCount <- 1
                    stableRootCompleteCount, rootCompleteFingerprintIdentityText identity, stableRootFactsOfIdentity identity)

        let hasReplayCompleteKind (kind: EvalKind) =
            lock gate (fun () ->
                match frontier with
                | Some frame -> frameReplayCompleteKindId kind frame
                | None -> false)

        let hasReplayCompleteOtherKind (kind: EvalKind) =
            lock gate (fun () ->
                match frontier with
                | Some frame -> frameReplayCompleteAny frame && frame.kind <> kind
                | None -> false)

        let private rememberReplayRootComplete (event: string) (outcome: string) (cell: ReplayCell) =
            let witnessIdentity =
                FastRuntimeFormat.format "%s|%s|%d|%s|%d|%d|%s" [| box (replayCellKindText cell); box (replayCellShapeText cell); box cell.nodeId; box (replayCellSiteText cell); box cell.cursor; box cell.step; box outcome |]
            parentCacheHandoffBuildAdmission <- ParentCacheHandoffClosedAfterRootWitness
            let observedAtUtc = System.DateTime.UtcNow
            if replayRootFirstCompleteWitnessUtc = System.DateTime.MinValue then
                replayRootFirstCompleteWitnessUtc <- observedAtUtc
            replayRootCompleteWitnessUtc <- observedAtUtc
            if witnessIdentity <> replayRootCompleteWitnessIdentity then
                replayRootCompleteWitnessIdentity <- witnessIdentity
                let quarantinedHandoffs = EvalReplayValueStore.quarantineParentCacheHandoffsAfterRootComplete()
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"parent_cache_handoff_admission_closed_at_root_witness\",\"event\":%s,\"outcome\":%s,\"witness_identity\":%s,\"node_id\":%d,\"site\":%s,\"quarantined_handoff_count\":%d,\"authority\":\"eval_worklist_root_complete_witness\",\"admission_du\":\"ClosedAfterRootComplete\",\"next\":\"observe_late_cache_commits_without_parent_replay\"}" [| box (DiagJson.esc event); box (DiagJson.esc outcome); box (DiagJson.esc witnessIdentity); box cell.nodeId; box (DiagJson.esc (replayCellSiteText cell)); box quarantinedHandoffs |])
            replayRootCompleteWitnessSummary <- FastRuntimeFormat.format "event=%s outcome=%s identity=%s cell=%s" [| box event; box outcome; box witnessIdentity; box (formatCell cell) |]

        let private postRootResidualFrame (frame: Frame) =
            match frameSemanticStatusId frame with
            | SemanticParentContinuationCycleDeferred
            | SemanticReplayFingerprintRepeatBlocked -> true
            | _ -> false

        let private rootWitnessResidualTailDispositionLocked () =
            let witnessAgeMs =
                if replayRootFirstCompleteWitnessUtc = System.DateTime.MinValue then -1.0
                else (System.DateTime.UtcNow - replayRootFirstCompleteWitnessUtc).TotalMilliseconds
            let durableWitnessForBuild =
                parentCacheHandoffBuildAdmission = ParentCacheHandoffClosedAfterRootWitness
                && not (System.String.IsNullOrWhiteSpace replayRootCompleteWitnessIdentity)
            let queueDepth = replayQueue.Length
            let pending = pendingCountUnlocked()
            let active = replayDriverActiveDepth
            let pendingFrames = [frontier; frontierTerm; frontierTy] |> List.choose id
            let pendingFrontierTail =
                queueDepth = 0
                && pending > 0
                && pending <= 2
                && active = 0
                && not (List.isEmpty pendingFrames)
                && (pendingFrames |> List.forall postRootResidualFrame)
            if durableWitnessForBuild && witnessAgeMs >= replayRootResidualTailQuarantineAgeMs then
                if queueDepth > 0
                   && queueDepth <= replayRootResidualTailMaxQueueDepth
                   && active <= 1
                   && pending = 0 then
                    RootWitnessResidualQueueTailQuarantine, witnessAgeMs
                elif pendingFrontierTail then
                    RootWitnessResidualPendingFrontierTailQuarantine, witnessAgeMs
                else
                    RootWitnessResidualTailKeepDraining, witnessAgeMs
            else
                RootWitnessResidualTailKeepDraining, witnessAgeMs

        let private quarantineResidualTailAfterRootWitnessIfEligible () =
            lock gate (fun () ->
                let disposition, witnessAgeMs = rootWitnessResidualTailDispositionLocked()
                match disposition with
                | RootWitnessResidualTailKeepDraining -> None
                | RootWitnessResidualQueueTailQuarantine ->
                    let queueBefore = replayQueue.Length
                    let pendingBefore = pendingCountUnlocked()
                    replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                    replayScheduledKey <- None
                    replayDriverStackFenceQueued <- false
                    replayDriverStackFenceQueuedSinceMs <- 0L
                    Some(disposition, queueBefore, replayDriverActiveDepth, pendingBefore, int64 witnessAgeMs)
                | RootWitnessResidualPendingFrontierTailQuarantine ->
                    let queueBefore = replayQueue.Length
                    let pendingBefore = pendingCountUnlocked()
                    frontier <- None
                    frontierTerm <- None
                    frontierTy <- None
                    activeRun <- false
                    replayScheduledKey <- None
                    replayDriverStackFenceQueued <- false
                    replayDriverStackFenceQueuedSinceMs <- 0L
                    Some(disposition, queueBefore, replayDriverActiveDepth, pendingBefore, int64 witnessAgeMs))

        let hasReplayCompleteWriteWitness () =
            lock gate (fun () ->
                let frontierComplete =
                    match frontier with
                    | Some frame when frameOrCellIsRootComplete frame -> true
                    | Some _ -> false
                    | None -> false
                if frontierComplete then true
                else
                    let noLiveReplay =
                        pendingCount() = 0
                        && replayQueueDepth() = 0
                        && replayDriverActiveDepthValue() = 0
                    let durableWitnessForBuild =
                        parentCacheHandoffBuildAdmission = ParentCacheHandoffClosedAfterRootWitness
                        && replayRootCompleteWitnessUtc <> System.DateTime.MinValue
                        && not (System.String.IsNullOrWhiteSpace replayRootCompleteWitnessIdentity)
                    noLiveReplay && durableWitnessForBuild)

        let hasFreshReplayRootWitness () =
            lock gate (fun () ->
                let ageMs = (System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds
                replayRootCompleteWitnessUtc <> System.DateTime.MinValue
                && ageMs >= 0.0
                && ageMs <= replayRootCompleteLivenessWindowMs)

        let replayCompleteWriteWitnessSummary () =
            lock gate (fun () ->
                if replayRootCompleteWitnessUtc = System.DateTime.MinValue then "none"
                else sprintf "%s age_ms=%.0f" replayRootCompleteWitnessSummary ((System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds))

        type ReplayFrameObsolescenceId =
            | ReplayFrameRootComplete
            | ReplayFrameStaleStatus
            | ReplayFrameStaleReason
            | ReplayFrameContinuationEnvelope
            | ReplayFrameSemanticStepPartial
            | ReplayFrameActive

        let private replayFrameObsolescenceId (frame:Frame) =
            let statusId = frame.status
            let statusStale =
                match frame.status with
                | FrameUnknown(_, facts) -> Set.contains DiagnosticClassifier.DiagnosticReplayFrameStale facts
                | _ -> false
            let cellStatusId =
                match frame.semanticCell with
                | Some cell -> frameStatusOfReplayCellStatusId cell.status
                | None -> frameUnknown (CompilerKernelV2.OperationalReasonIdOps.create "")
            if statusId = FrameSemanticRootComplete || cellStatusId = FrameSemanticRootComplete then ReplayFrameRootComplete
            elif statusStale then ReplayFrameStaleStatus
            elif Set.contains DiagnosticClassifier.DiagnosticReplayFrameStale (frameReasonFacts frame) then ReplayFrameStaleReason
            elif statusId = FrameContinuationEnvelope then ReplayFrameContinuationEnvelope
            elif statusId = FrameSemanticStepPartial then ReplayFrameSemanticStepPartial
            else ReplayFrameActive

        let private frameLooksObsoleteAfterRootWitness (frame: Frame) =
            match replayFrameObsolescenceId frame with
            | ReplayFrameStaleStatus
            | ReplayFrameStaleReason
            | ReplayFrameContinuationEnvelope
            | ReplayFrameSemanticStepPartial -> true
            | ReplayFrameRootComplete
            | ReplayFrameActive -> false

        let heartbeatRootWitnessQuiescenceSweep () =
            try
                let beforeCount, afterCount, dropped, rootSite, writeWitness =
                    lock gate (fun () ->
                        let countPendingLocked () =
                            let mutable n = 0
                            let seen = System.Collections.Generic.HashSet<ReplayFramePendingIdentity>()
                            let add (opt: Frame option) =
                                match opt with
                                | Some frame ->
                                    let identity : ReplayFramePendingIdentity = {
                                        kind = frameEvalKindId frame
                                        key = frame.key
                                        site = frame.site
                                    }
                                    if seen.Add identity then n <- n + 1
                                | None -> ()
                            add frontier
                            add frontierTerm
                            add frontierTy
                            n
                        let frameRootComplete (opt: Frame option) =
                            match opt with
                            | Some frame ->
                                frameStatusId frame = FrameSemanticRootComplete
                                || (match frame.semanticCell with
                                    | Some cell -> frameStatusOfReplayCellStatusId cell.status = FrameSemanticRootComplete
                                    | None -> false)
                            | None -> false
                        let rootOpt =
                            match frontier with
                            | Some f when frameRootComplete (Some f) -> Some f
                            | _ ->
                                match frontierTerm with
                                | Some f when frameRootComplete (Some f) -> Some f
                                | _ ->
                                    match frontierTy with
                                    | Some f when frameRootComplete (Some f) -> Some f
                                    | _ -> None
                        let frontierComplete = rootOpt.IsSome
                        let noReplayQueue = replayQueue.IsEmpty
                        let writeWitness =
                            frontierComplete
                            || (replayRootCompleteWitnessUtc <> System.DateTime.MinValue
                                && (System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds <= replayRootCompleteWitnessWindowMs)
                        let beforeCount = countPendingLocked()
                        let rootSite = match rootOpt with Some f -> f.site | None -> CompilerIdentityKernel.WorkSiteIdOps.create "missing_root_frontier"
                        if writeWitness && noReplayQueue && beforeCount > 0 then
                            let mutable dropped = 0
                            let scrub (opt: Frame option) =
                                match opt with
                                | Some f when frameLooksObsoleteAfterRootWitness f ->
                                    dropped <- dropped + 1
                                    None
                                | other -> other
                            frontier <- scrub frontier
                            frontierTerm <- scrub frontierTerm
                            frontierTy <- scrub frontierTy
                            if dropped > 0 then
                                replayDriverStackFenceQueued <- false
                                replayDriverStackFenceQueuedSinceMs <- 0L
                                progressYieldCount <- 0
                            beforeCount, countPendingLocked(), dropped, rootSite, writeWitness
                        else beforeCount, beforeCount, 0, rootSite, writeWitness)
                if dropped > 0 then
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_root_witness_quiescence_sweep\",\"event\":\"heartbeat_no_work_stall\",\"pending_before\":%d,\"pending_after\":%d,\"dropped_stale_frontiers\":%d,\"root_site\":%s,\"write_witness\":%b,\"queue_depth\":%d,\"active_depth\":%d,\"single_flight\":1,\"next\":\"retry_clean_buildfile_after_stale_frontier_sweep\"}" [| box beforeCount; box afterCount; box dropped; box (esc (CompilerIdentityKernel.WorkSiteIdOps.text rootSite)); box writeWitness; box (replayQueueDepth()); box (replayDriverActiveDepthValue()) |])
                dropped
            with _ -> 0

        // MIGRATION: only completed semantic states are absorbing for the bounded
        // trampoline.  MIGRATION proved that treating semantic_step_partial as terminal
        // strands a real child replay at cursor=trace_len: ESeq schedules its first
        // child EApply, the child reports semantic_step_partial, and retry_stop aborts
        // with explicit_eval_worklist_real_stepper_required instead of building the
        // next replay continuation.  Keep root/leaf absorbing to preserve MIGRATION's
        // no-downgrade invariant, but let partial/done states flow back into the
        // continuation adapter when their trace cursor is exhausted.
        let private isSemanticTerminalFrame (frame: Frame) =
            match frameStatusId frame, frameSemanticStatusId frame with
            | FrameSemanticLeafComplete, _ -> true
            | _, (SemanticRootComplete
                 | SemanticParentContinuationCycleBlocked
                 | SemanticRootCompleteStaleRetargetPendingNoQueueBlocked
                 | SemanticTypeVariableValueMissingBlocked
                 | SemanticStaleRootRetargetBlocked
                 | SemanticReplayDriverExceptionBlocked
                 | SemanticReplayPayloadMissingBlocked
                 | SemanticSeqTypeErrorBlocked
                 | SemanticReplayChildScheduleRepeatBlocked
                 | SemanticReplayFingerprintRepeatBlocked
                 | SemanticJoinpointTermStepperBlocked
                 | SemanticMacroThunkMissingBlocked
                 | SemanticTjoinpointStepperBlocked
                 | SemanticJoinpointValueBlocked
                 | SemanticLiteralOpBodyStepperBlocked
                 | SemanticLetSuccessApplyExceptionBlocked
                 | SemanticLetSuccessAllReadyApplyBlocked
                 | SemanticLetSuccessApplyContinuationBlocked
                 | SemanticNominalConstructorStepperBlocked
                 | SemanticTypeApplyForallBodyStepperBlocked
                 | SemanticApplyContinuationExceptionBlocked
                 | SemanticDeferredFunctionReplayExceptionBlocked) -> true
            | _ -> false

        let private semanticTerminalNextForFrame (frame: Frame) =
            match frameStatusId frame with
            | FrameSemanticLeafComplete -> ReplayNextParentContinuationDirectRequired
            | _ ->
                match frameSemanticStatusId frame with
                | SemanticRootComplete -> ReplayNextAttemptBuild
                | SemanticReplayFingerprintRepeatBlocked -> ReplayNextReplayFingerprintRepeatDirectRequired
                | SemanticJoinpointTermStepperBlocked -> ReplayNextJoinpointTermStepperDirectRequired
                | terminalStatus when isTerminalContractStatusId terminalStatus -> ReplayNextSemanticStatus terminalStatus
                | _ -> replayCommitNextOther "native_hopac_real_stepper_direct_required"

        let private semanticPayloadOf (frame: Frame) =
            match frame.payload with
            | FrameSemanticCellPayload cell
            | FrameSemanticCellPayloadWithReasonSignal(cell, _) -> formatCellPayload cell
            | FrameLegacySemanticPayload legacy when not (String.IsNullOrWhiteSpace legacy.text) -> legacy.text
            | _ ->
                match trySemanticCellForFrame frame with
                | Some cell -> formatCellPayload cell
                | None -> "semantic_eval_payload_missing"

        let private semanticCellOf (frame: Frame) =
            match frame.payload with
            | FrameSemanticCellPayload cell
            | FrameSemanticCellPayloadWithReasonSignal(cell, _) -> Some cell
            | FrameLegacySemanticPayload _
            | FramePayloadMissing -> trySemanticCellForFrame frame

        let private replayKey (frame: Frame) =
            ReplayTaskKeyIdOps.createFrame frame

        let private replayDriverFor (frame: Frame) =
            match frameEvalKindId frame with
            | EvalTerm -> TermReplayDriver
            | EvalTy -> TyReplayDriver
            | _ -> UnknownReplayDriver (CompilerKernelV2.OperationalReasonIdOps.create "unknown_replay_driver")

        // MIGRATION: replayTaskDriverKind moved above emitReplayObligation
        // because generic obligation telemetry needs it before this point.

        let private activeReplayDriverKindMismatch (incomingKind: EvalKind) =
            lock gate (fun () ->
                match replayQueue with
                | task :: _ ->
                    match replayTaskDriverKindId task with
                    | ReplayKindUnknown _ -> false
                    | taskKind -> evalKindForReplayKindId taskKind <> incomingKind
                | [] -> false)

        type ReplayDriverOutcomeId =
            | ReplayDriverTypedCellCaptured
            | ReplayDriverSemanticPayloadCaptured
            | ReplayDriverSemanticPayloadRequired

        let private replayDriverOutcomeText = function
            | ReplayDriverTypedCellCaptured -> "typed_replay_cell_captured"
            | ReplayDriverSemanticPayloadCaptured -> "semantic_payload_captured"
            | ReplayDriverSemanticPayloadRequired -> "semantic_payload_required"

        type ReplayDriverNextId =
            | ReplayDriverNextExecuteTermStepper
            | ReplayDriverNextExecuteTyStepper
            | ReplayDriverNextWireTermTypedCell
            | ReplayDriverNextWireTyTypedCell
            | ReplayDriverNextWireTermPayload
            | ReplayDriverNextWireTyPayload
            | ReplayDriverNextExecuteUnknownStepper
            | ReplayDriverNextWireUnknownTypedCell
            | ReplayDriverNextWireUnknownPayload

        let private replayDriverNextText = function
            | ReplayDriverNextExecuteTermStepper -> "execute_term_eval_stepper"
            | ReplayDriverNextExecuteTyStepper -> "execute_ty_eval_stepper"
            | ReplayDriverNextWireTermTypedCell -> "wire_term_typed_replay_cell"
            | ReplayDriverNextWireTyTypedCell -> "wire_ty_typed_replay_cell"
            | ReplayDriverNextWireTermPayload -> "wire_term_eval_payload"
            | ReplayDriverNextWireTyPayload -> "wire_ty_eval_payload"
            | ReplayDriverNextExecuteUnknownStepper -> "execute_unknown_eval_stepper"
            | ReplayDriverNextWireUnknownTypedCell -> "wire_unknown_typed_replay_cell"
            | ReplayDriverNextWireUnknownPayload -> "wire_unknown_eval_payload"

        let private replayDriverNextFor (task: ReplayTask) (hasCell: bool) (hasSemantic: bool) =
            match replayTaskDriverId task, hasCell, hasSemantic with
            | TermReplayDriver, true, _ -> ReplayDriverNextExecuteTermStepper
            | TyReplayDriver, true, _ -> ReplayDriverNextExecuteTyStepper
            | TermReplayDriver, false, true -> ReplayDriverNextWireTermTypedCell
            | TyReplayDriver, false, true -> ReplayDriverNextWireTyTypedCell
            | TermReplayDriver, false, false -> ReplayDriverNextWireTermPayload
            | TyReplayDriver, false, false -> ReplayDriverNextWireTyPayload
            | _, true, _ -> ReplayDriverNextExecuteUnknownStepper
            | _, false, true -> ReplayDriverNextWireUnknownTypedCell
            | _ -> ReplayDriverNextWireUnknownPayload

        // MIGRATION: typed replay-cell driver commit gate.
        //
        // MIGRATION proved the semantic payload can reach the replay driver and dispatch a reducer. It was still a
        // string envelope, so the driver could only say "wire_term_eval_stepper". MIGRATION
        // keeps that textual envelope for diagnostics, but also carries a ReplayCell record
        // and emits a deterministic eval_worklist_replay_step. This is the first stack-safe
        // stepper boundary: it does not recurse into term/ty yet; it hands a typed cell to the
        // future executor and deduplicates repeated driver ticks.
        // MIGRATION: drain one preserved deferred replay child after the active driver
        // fully unwinds.  MIGRATION intentionally suppressed cross-kind/reentrant pokes while a
        // parent/root replay was already reducing; the missing piece is the safe handoff after
        // that active tick is done and no replay task remains queued.
        let private tryScheduleDeferredAfterActiveDriver (event: string) =
            let deferredOpt =
                // MIGRATION: annotated test bodies now arrive as the next concrete
                // replay obligation after the live-cycle defer.  Drain them before
                // macro/type catch-alls so the explicit EAnnotTest stepper gets a tick
                // instead of being hidden behind an older fingerprint-repeat terminal.
                match EvalReplayValueStore.tryTakeDeferredReplayCell EvalReplayValueStore.DeferredReplayTerm (CompilerIdentityKernel.WorkShapeIdOps.Known.eAnnotTest) -1 with
                | Some cell -> Some cell
                | None ->
                    // MIGRATION: direct EAnnot wrappers can surface after root-complete
                    // handoff while their inner/type children are still live. Drain
                    // them before macro/type catch-alls so the annotation spine keeps
                    // its own replay tick instead of being buried behind stale root proof.
                    match EvalReplayValueStore.tryTakeDeferredReplayCell EvalReplayValueStore.DeferredReplayTerm (CompilerIdentityKernel.WorkShapeIdOps.Known.eAnnot) -1 with
                    | Some cell -> Some cell
                    | None ->
                        // MIGRATION: do not starve term macro apply-args behind the ty catch-all.
                        // Runtime evidence showed EMacro apply_arg_child was repeatedly scheduled while
                        // a ty replay driver remained active, then terminalized as child_schedule_repeat.
                        match EvalReplayValueStore.tryTakeDeferredReplayCell EvalReplayValueStore.DeferredReplayTerm (CompilerIdentityKernel.WorkShapeIdOps.Known.eMacro) -1 with
                        | Some cell -> Some cell
                        | None ->
                            match EvalReplayValueStore.tryTakeDeferredReplayCell EvalReplayValueStore.DeferredReplayTy (CompilerIdentityKernel.WorkShapeIdOps.Known.tFun) -1 with
                            | Some cell -> Some cell
                            | None ->
                                match EvalReplayValueStore.tryTakeDeferredReplayCell EvalReplayValueStore.DeferredReplayTerm (CompilerIdentityKernel.WorkShapeIdOps.Known.eFunPrime) -1 with
                                | Some cell -> Some cell
                                | None ->
                                    // Prefer a live EJoinPoint' obligation before the
                                    // generic term catch-all. Runtime evidence showed the pinned terminal
                                    // at sm'_real.spir:285 while an EUnitTest/term replay queue was still
                                    // alive; this priority keeps joinpoint value materialization typed.
                                    match EvalReplayValueStore.tryTakeDeferredReplayCell EvalReplayValueStore.DeferredReplayTerm (CompilerIdentityKernel.WorkShapeIdOps.Known.eJoinPointPrime) -1 with
                                    | Some cell -> Some cell
                                    | None ->
                                        match EvalReplayValueStore.tryTakeDeferredReplayCell EvalReplayValueStore.DeferredReplayTerm (CompilerIdentityKernel.WorkShapeIdOps.Known.eUnitTest) -1 with
                                        | Some cell -> Some cell
                                        | None ->
                                            match EvalReplayValueStore.tryTakeDeferredReplayCell EvalReplayValueStore.DeferredReplayTerm (CompilerIdentityKernel.WorkShapeIdOps.Known.unknown) -1 with
                                            | Some cell -> Some cell
                                            | None -> EvalReplayValueStore.tryTakeDeferredReplayCell EvalReplayValueStore.DeferredReplayTy (CompilerIdentityKernel.WorkShapeIdOps.Known.unknown) -1
            match deferredOpt with
            | Some deferredCell ->
                let replayCell : ReplayCell = {
                    kind = evalKindForDeferredReplayKind deferredCell.kind
                    shape = deferredCell.shape
                    nodeId = deferredCell.nodeId
                    envGlobalTerm = deferredCell.envGlobalTerm
                    envStackTerm = deferredCell.envStackTerm
                    envGlobalType = deferredCell.envGlobalType
                    envStackType = deferredCell.envStackType
                    seqLen = deferredCell.seqLen
                    cseDepth = deferredCell.cseDepth
                    traceDepth = deferredCell.traceDepth
                    site = deferredCell.site
                    cursor = deferredCell.cursor
                    step = deferredCell.step
                    status = ReplayCellSemanticStatus SemanticDeferredAfterActiveDriverReady
                }
                let scheduled =
                    lock gate (fun () ->
                        if replayQueue.IsEmpty then
                            replaySeq <- replaySeq + 1L
                            let childDriverId = replayCell.kind |> replayDriverForKind (UnknownReplayDriver (CompilerKernelV2.OperationalReasonIdOps.create "unknown_replay_driver"))
                            let childDriver = replayDriverToString childDriverId
                            let childTaskKey = ReplayTaskKeyIdOps.createDeferredAfterActive replayCell
                            let childKey = ReplayTaskKeyIdOps.text childTaskKey
                            let childTask = makeReplayCellTask replaySeq childTaskKey childDriverId replayCell ReplayTaskScheduledReplay
                            replayScheduledKey <- Some childTaskKey
                            replayQueue <- [childTask]
                            true, childDriver, childKey, replaySeq
                        else
                            false, "", "", 0L)
                match scheduled with
                | true, childDriver, childKey, replayId ->
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_deferred_after_active_driver_scheduled\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"key\":%s,\"cell\":%s,\"queue_depth\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box replayId; box (esc childDriver); box (esc childKey); box (esc (formatCell replayCell)); box (replayQueueDepth()); box (esc childDriver) |])
                    true
                | false, _, _, _ ->
                    EvalReplayValueStore.putDeferredReplayCell deferredCell
                    false
            | None -> false

        let private replayDriverStackFenceCap = 4

        // MIGRATION: the 1231 assessment says the right frontier is not another
        // terminal: it is live parent-resume replay that is already queued/active
        // but can starve behind single-flight.  Model the handoff as a closed DU
        // before it becomes JSON text.
        type ParentResumeReplayDrainDecisionId =
            | ParentResumeReplayDrainNoop
            | ParentResumeReplayDrainAwaitActive
            | ParentResumeReplayDrainScheduleBackupTick
            | ParentResumeReplayDrainScheduleTailTick
            | ParentResumeReplayDrainHardStopPendingZero

        let private parentResumeReplayDrainDecisionText = function
            | ParentResumeReplayDrainNoop -> "noop"
            | ParentResumeReplayDrainAwaitActive -> "await_active"
            | ParentResumeReplayDrainScheduleBackupTick -> "schedule_backup_tick"
            | ParentResumeReplayDrainScheduleTailTick -> "schedule_tail_tick"
            | ParentResumeReplayDrainHardStopPendingZero -> "hard_stop_pending_zero"

        let private parentResumeReplayDrainDecisionShouldSchedule = function
            | ParentResumeReplayDrainScheduleBackupTick
            | ParentResumeReplayDrainScheduleTailTick -> true
            | ParentResumeReplayDrainNoop
            | ParentResumeReplayDrainAwaitActive
            | ParentResumeReplayDrainHardStopPendingZero -> false

        // MIGRATION: split parent-resume hard-stop from live replay scheduling with
        // an explicit all-empty gate.  This is deliberately redundant with the
        // integer fields in JSONL so future patches can delete the old string
        // heuristic without losing operator-visible evidence.
        type ParentResumeHardStopGateId =
            | ParentResumeHardStopAllowedAllEmpty of proof:CompilerKernelV2.OperationalReasonId
            | ParentResumeHardStopBlockedByQueueActive of proof:CompilerKernelV2.OperationalReasonId
            | ParentResumeHardStopBlockedByPending of proof:CompilerKernelV2.OperationalReasonId

        let private parentResumeHardStopGateText = function
            | ParentResumeHardStopAllowedAllEmpty proof -> "ParentResumeHardStopGate(AllowedAllEmpty|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | ParentResumeHardStopBlockedByQueueActive proof -> "ParentResumeHardStopGate(BlockedByQueueActive|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"
            | ParentResumeHardStopBlockedByPending proof -> "ParentResumeHardStopGate(BlockedByPending|" + CompilerKernelV2.OperationalReasonIdOps.text proof + ")"

        let private parentResumeHardStopGateFor (liveness: ReplayLivenessSnapshot) =
            let proof =
                replayLivenessProof<ParentResumeReplayK> "parent_resume_replay_drain" liveness
                |> replayLivenessProofDuText
                |> CompilerKernelV2.OperationalReasonIdOps.create
            if replayLivenessAllEmpty liveness then ParentResumeHardStopAllowedAllEmpty proof
            elif liveness.queueDepth > 0 || liveness.activeDepth > 0 || liveness.hasDeferredCell || liveness.hasProgressYield then ParentResumeHardStopBlockedByQueueActive proof
            else ParentResumeHardStopBlockedByPending proof

        let private parentResumeHardStopGateAllowsHardStop = function
            | ParentResumeHardStopAllowedAllEmpty _ -> true
            | _ -> false

        // MIGRATION: 1519's live tail ended with same_node_parent_replay_cell_deferred
        // plus same_node_parent_replay_self_poke while q>0/p>0. Treat that as a
        // typed drain decision instead of a passive string-only await.
        type SameNodeParentReplayDrainDecisionId =
            | SameNodeParentReplayAwaitExistingTick
            | SameNodeParentReplayScheduleBackupTick
            | SameNodeParentReplayScheduleTailTick
            | SameNodeParentReplayHardStopPendingZero

        let private sameNodeParentReplayDrainDecisionText = function
            | SameNodeParentReplayAwaitExistingTick -> "await_existing_parent_replay_tick"
            | SameNodeParentReplayScheduleBackupTick -> "schedule_same_node_parent_replay_backup_tick"
            | SameNodeParentReplayScheduleTailTick -> "schedule_same_node_parent_replay_tail_tick"
            | SameNodeParentReplayHardStopPendingZero -> "hard_stop_same_node_parent_replay_pending_zero"

        let private sameNodeParentReplayDrainDecisionShouldSchedule = function
            | SameNodeParentReplayScheduleBackupTick
            | SameNodeParentReplayScheduleTailTick -> true
            | SameNodeParentReplayAwaitExistingTick
            | SameNodeParentReplayHardStopPendingZero -> false

        let private sameNodeParentReplayDrainDecisionFor queueDepth activeDepth pending =
            if pending <= 0 && queueDepth <= 0 && activeDepth <= 0 then SameNodeParentReplayHardStopPendingZero
            elif queueDepth > 0 && activeDepth <= replayDriverStackFenceCap then SameNodeParentReplayScheduleBackupTick
            elif queueDepth > 0 && pending > 0 then SameNodeParentReplayScheduleTailTick
            else SameNodeParentReplayAwaitExistingTick

        type ParentResumeReplayDrainCauseId =
            | ParentResumeDrainGeneric
            | ParentResumeDrainDeferredChild
            | ParentResumeDrainCrossKind
            | ParentResumeDrainReentrant
            | ParentResumeDrainPostActive

        let private parentResumeReplayDrainCauseText = function
            | ParentResumeDrainGeneric -> "ParentResumeDrainCause(Generic)"
            | ParentResumeDrainDeferredChild -> "ParentResumeDrainCause(DeferredChild)"
            | ParentResumeDrainCrossKind -> "ParentResumeDrainCause(CrossKind)"
            | ParentResumeDrainReentrant -> "ParentResumeDrainCause(Reentrant)"
            | ParentResumeDrainPostActive -> "ParentResumeDrainCause(PostActive)"

        let private parentResumeReplayDrainDecisionFor cause queueDepth activeDepth pending =
            if pending = 0 && queueDepth <= 0 && activeDepth <= 0 then ParentResumeReplayDrainHardStopPendingZero
            elif activeDepth > 0 then ParentResumeReplayDrainAwaitActive
            else
                match cause with
                | ParentResumeDrainDeferredChild
                | ParentResumeDrainCrossKind
                | ParentResumeDrainReentrant
                | ParentResumeDrainPostActive ->
                    if queueDepth > 0 then ParentResumeReplayDrainScheduleBackupTick
                    elif pending > 0 then ParentResumeReplayDrainScheduleTailTick
                    else ParentResumeReplayDrainNoop
                | ParentResumeDrainGeneric -> ParentResumeReplayDrainNoop

        let private parentResumeReplayDrainDecisionForLiveness cause (liveness: ReplayLivenessSnapshot) =
            let gate = parentResumeHardStopGateFor liveness
            let decision = parentResumeReplayDrainDecisionFor cause liveness.queueDepth liveness.activeDepth liveness.pending
            match gate, decision with
            | ParentResumeHardStopAllowedAllEmpty _, _ -> ParentResumeReplayDrainHardStopPendingZero
            | ParentResumeHardStopBlockedByQueueActive _, ParentResumeReplayDrainHardStopPendingZero when liveness.activeDepth > 0 -> ParentResumeReplayDrainAwaitActive
            | ParentResumeHardStopBlockedByQueueActive _, ParentResumeReplayDrainHardStopPendingZero -> ParentResumeReplayDrainScheduleBackupTick
            | ParentResumeHardStopBlockedByPending _, ParentResumeReplayDrainHardStopPendingZero -> ParentResumeReplayDrainScheduleTailTick
            | _ -> decision

        let private replayDriverTickCauseText = function
            | ReplayTickParentReplayPreserved -> "parent_replay_preserved_deferred_scheduler_yield"
            | ReplayTickDynamicFunctionBridge -> "dynamic_function_bridge_recoverable_yield"
            | ReplayTickParentContinuationFill -> "parent_continuation_ivar_fill_required_after_symbolic_bridge"
            | ReplayTickDynamicFunctionCarrier -> "dynamic_function_bridge_symbolic_runtime_carrier"
            | ReplayTickCooperativeHandoff -> "cooperative_replay_handoff"
            | ReplayTickPostActiveParentResume -> "post_active_parent_resume_queue_tail"

        let private replayDriverTickCauseRequestsLegacyTick = function
            | ReplayTickParentReplayPreserved
            | ReplayTickDynamicFunctionBridge
            | ReplayTickParentContinuationFill
            | ReplayTickDynamicFunctionCarrier
            | ReplayTickCooperativeHandoff
            | ReplayTickPostActiveParentResume -> true

        let private replayDriverTickCauseSuppressedAfterTerminal = function
            | ReplayTickParentReplayPreserved
            | ReplayTickCooperativeHandoff -> true
            | ReplayTickDynamicFunctionBridge
            | ReplayTickParentContinuationFill
            | ReplayTickDynamicFunctionCarrier
            | ReplayTickPostActiveParentResume -> false

        let private replayDriverTickCauseAllowsNativeFailureSmallDrain = function
            | ReplayTickCooperativeHandoff
            | ReplayTickPostActiveParentResume -> true
            | ReplayTickParentReplayPreserved
            | ReplayTickDynamicFunctionBridge
            | ReplayTickParentContinuationFill
            | ReplayTickDynamicFunctionCarrier -> false

        let rec private runReplayDriver (eventId: ReplayTickEventId) =
            let event = replayTickEventToString eventId
            let tickEventId = eventId
            let activeDepthAfterEnter =
                lock gate (fun () ->
                    replayDriverActiveDepth <- replayDriverActiveDepth + 1
                    replayDriverActiveDepth)
            let scheduleReplayDriverTick cause (eventId': ReplayTickEventId) =
                let event' = replayTickEventToString eventId'
                let reason = replayDriverTickCauseText cause
                let queueDepthAtYield, shouldScheduleRaw, decision, tickPressureId =
                    lock gate (fun () ->
                        let qd = replayQueue.Length
                        let nowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                        let staleQueued = replayDriverStackFenceQueued && replayDriverStackFenceQueuedSinceMs > 0L && nowMs - replayDriverStackFenceQueuedSinceMs > 100L
                        if staleQueued then replayDriverStackFenceQueued <- false
                        let tickPressureId = replayTickQueuePressureFor qd replayDriverActiveDepth replayDriverStackFenceQueued staleQueued
                        let decision = replayTickRequestDecisionFromPressure tickPressureId
                        let shouldSchedule = replayTickRequestDecisionShouldSchedule decision && not (DiagJson.terminalFailureExitRequestedNow())
                        // MIGRATION: a cooperative handoff with runnable queue is real scheduler progress.
                        // Count it for retry_stop so root-complete/pending-job terminals do not abort
                        // before the fresh replay tick has a chance to consume the queued continuation.
                        if qd > 0 then noteProgressYieldLocked ()
                        if shouldSchedule then
                            replayDriverStackFenceQueued <- true
                            replayDriverStackFenceQueuedSinceMs <- nowMs
                        qd, shouldSchedule, decision, tickPressureId)
                let pinnedParentReplayPoisonTerminalCommitted =
                    try
                        match tryPinnedTerminalContract() with
                        | Some pinned when isParentReplayCycleBreakPoisonedStatus (frameSemanticStatusId pinned) -> true
                        | _ -> false
                    with _ -> false
                let pendingGraphTerminalCommitCount =
                    DiagJson.snapshotKindCount "eval_worklist_stack_fence_hopac_override_pierced_repeat_cap"
                    + DiagJson.snapshotKindCount "eval_worklist_parent_poison_hopac_override_pierced_live_tail"
                    + DiagJson.snapshotKindCount "eval_worklist_parent_replay_cycle_break_poison_live_tail_override_deferred"
                    + DiagJson.snapshotKindCount "eval_worklist_parent_replay_cycle_break_poison_shadow_timeout_pierced_repeat_cap_probation"
                    + DiagJson.snapshotKindCount "eval_worklist_parent_replay_cycle_break_poison_pending_graph_terminal_committed"
                    + DiagJson.snapshotKindCount "eval_worklist_semantic_stale_retarget_shadow_timeout_pierced_missing_prefetch_cycle_break"
                    + DiagJson.snapshotKindCount "eval_worklist_if_unknown_return_condition_shadow_timeout_pierced_repeat_cap"
                    + DiagJson.snapshotKindCount "eval_worklist_if_unknown_return_condition_pending_graph_terminal_committed"
                    + DiagJson.snapshotKindCount "eval_worklist_dynamic_record_key_bridge_tail_shadow_timeout_pierced_weak_pending_active_root"
                    + DiagJson.snapshotKindCount "eval_worklist_dynamic_record_key_bridge_pending_graph_terminal_committed"
                    + DiagJson.snapshotKindCount "eval_worklist_idle_cross_kind_active_ty_sidecar_pending_graph_terminal_committed"
                    + DiagJson.snapshotKindCount "eval_worklist_op_impl_required_pending_graph_terminal_committed"
                    + DiagJson.snapshotKindCount "eval_worklist_bigstack_op_impl_required_hard_semantic_fail_closed"
                    + DiagJson.snapshotKindCount "eval_worklist_op_impl_required_authoring_terminal_exit"
                    + DiagJson.snapshotKindCount "eval_worklist_idle_cross_kind_replay_driver_with_active_ty_sidecar_drain"
                    + DiagJson.snapshotKindCount "eval_worklist_small_queue_parent_replay_poison_shadow_timeout_pierced_repeat_cap_probation"
                    + DiagJson.snapshotKindCount "eval_worklist_deferred_child_cell_pending_graph_terminal_committed"
                    + (if pinnedParentReplayPoisonTerminalCommitted then 1 else 0)
                let pendingGraphTerminalAlreadyCommitted =
                    pendingGraphTerminalCommitCount > 0 || pinnedParentReplayPoisonTerminalCommitted
                let nativeCutoverReasonRequestsLegacyTick = replayDriverTickCauseRequestsLegacyTick cause
                let nativeCutoverBackupTickSuppressed =
                    pendingGraphTerminalAlreadyCommitted
                    && nativeCutoverReasonRequestsLegacyTick
                    && (not (hasReplayCompleteWriteWitness())
                        || replayDriverTickCauseSuppressedAfterTerminal cause
                        || pinnedParentReplayPoisonTerminalCommitted)
                let nativePromiseFailureClosedForCooperativeTick = DiagJson.nativePromiseFailureClosedNow()
                let pendingAtYield = pendingCount()
                let nativePromiseFailureClosedSmallSidecarDrain =
                    nativePromiseFailureClosedForCooperativeTick
                    && queueDepthAtYield <= 4
                    && activeDepthAfterEnter <= replayDriverStackFenceCap
                    && pendingAtYield <= 4
                    && replayDriverTickCauseAllowsNativeFailureSmallDrain cause
                let durableRunEndObserved = DiagJson.terminalFlowRunEndEmittedNow()
                let shouldSchedule =
                    shouldScheduleRaw
                    && not durableRunEndObserved
                    && not nativeCutoverBackupTickSuppressed
                    && (not nativePromiseFailureClosedForCooperativeTick || nativePromiseFailureClosedSmallSidecarDrain)
                if durableRunEndObserved || nativeCutoverBackupTickSuppressed || (nativePromiseFailureClosedForCooperativeTick && not nativePromiseFailureClosedSmallSidecarDrain) then
                    lock gate (fun () ->
                        replayDriverStackFenceQueued <- false
                        replayDriverStackFenceQueuedSinceMs <- 0L)
                let cooperativeOwnerDu = replayHandoffOwnerToString (replayHandoffOwnerForState ReplayHandoffCooperativeTick queueDepthAtYield activeDepthAfterEnter replayDriverStackFenceCap ReplayTaskSemanticStepPartial)
                let cooperativeLiveness = captureReplayLiveness()
                if nativePromiseFailureClosedForCooperativeTick && not nativePromiseFailureClosedSmallSidecarDrain then
                    let cooperativeTickTerminalLine =
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_native_promise_failure_cooperative_tick_closed\",\"event\":%s,\"reason\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"native_promise_failure_latched\":true,\"native_promise_failure_latched_age_ms\":%d,\"native_promise_failure_authority_du\":%s,\"root_promise_status\":\"RootPromiseFailed(native_promise_failure_latched)\",\"root_complete_await_contract_du\":\"RootCompleteAwaitFailedClosed(native_promise_failure_latched)\",\"root_complete_exit_policy_du\":\"observer_only_semantic_failure_requires_native_root_complete_boundary(native_promise_failure_latched)\",\"native_job_graph\":\"RootComplete.await(native_promise_failure_latched)\\n  Collapse(Error(NativePromiseFailureLatched))\\n    CLI.emit_semantic_error_then_exit_1(NativePromiseFailureLatched)\",\"semantic_diagnosis\":\"SemanticDiagnosis(NativePromiseFailureLatched|span=source_unknown|message=cooperative_tick_closed)\",\"scheduled_async\":false,\"worker_decision_du\":\"native_promise_failed_terminal_closed_cooperative_tick_suppressed\",\"worker_defer_decision_du\":\"no_threadpool_tick_after_native_promise_failure\",\"hopac_root_exit_verdict\":\"ExitObserverOnly(SemanticDiagnosis(NativePromiseFailureLatched))\",\"trampoline_bypass_status\":\"TrampolineBypass(NativeTerminal|code=[spiral_compiler] EJP0032|policy=cooperative_tick_native_promise_terminal_no_retry)\",\"root_complete_collapse_decision_du\":\"EmitStructuredSemanticErrorExitOne(reason=native_promise_failure_latched)\",\"terminal_collapse_to_build_error_trace\":true,\"finish_fast_terminal\":true,\"terminal_exit_owner_du\":\"TerminalExitOwner(CooperativeTickNativePromiseFailure)\",\"terminal_receipt_durability_du\":\"TerminalReceiptDurability(DurableFileFlushBeforeExit|source=cooperative_tick_closed)\",\"policy\":\"native_promise_failure_first_terminal_producer_owns_exit\",\"single_flight\":1,\"next\":\"await_native_root_complete_alt\"}" [| box (esc event'); box (esc reason); box queueDepthAtYield; box activeDepthAfterEnter; box pendingAtYield; box (DiagJson.nativePromiseFailureClosedAgeNowMs()); box (esc (DiagJson.nativePromiseFailureClosedAuthorityNow())) |]
                    DiagJson.emitTerminalJsonDurableAndExitSingleFlight DiagJson.ObserverProjectionCooperativeTickNativePromiseFailure cooperativeTickTerminalLine
                elif nativeCutoverBackupTickSuppressed then
                    let nativeCutoverBackupTickSuppressedCount =
                        DiagJson.snapshotKindCount "eval_worklist_native_cutover_backup_tick_suppressed"
                    if nativeCutoverBackupTickSuppressedCount < 1 || nativeCutoverBackupTickSuppressedCount % 256 = 0 then
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_native_cutover_backup_tick_suppressed\",\"event\":%s,\"reason\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"pending_graph_terminal_committed\":true,\"pending_graph_terminal_commit_count\":%d,\"terminal_commit_class_du\":%s,\"legacy_leak_policy_du\":\"backup_tick_rejected_after_terminal\",\"backup_tick_policy_du\":\"eval_worklist_cannot_schedule_backup_tick\",\"qap_quarantine_policy_du\":\"qap_veto_invalid_after_hopac_quorum\",\"raw_key_authority_policy_du\":\"raw_key_forbidden_for_authority\",\"localized_driver_route_policy_du\":\"pending_graph_dispatch_ready\",\"legacy_observer_action_du\":\"observer_backup_tick_rejected\",\"runtime_dispatch_verdict_du\":\"dispatch_terminal_committed_fail_closed\",\"legacy_tick_gate_du\":\"legacy_tick_suppressed_by_terminal_payload\",\"pending_graph_shard_state\":\"TerminalPayload(PendingGraphCommitted)\",\"hopac_quorum\":\"Alt_Expired_FailClosed\",\"jsonl_recycle_du\":\"emit_first_then_256_milestones\",\"suppression_count_before\":%d,\"policy\":\"materialized_terminal_payload_suppresses_any_legacy_tick_no_buildok_compact_after_first_then_256_milestones\",\"single_flight\":1,\"next\":\"execute_native_inline_callback_before_eval_worklist_backup_tick\"%s}" [| box (esc event'); box (esc reason); box queueDepthAtYield; box activeDepthAfterEnter; box pendingAtYield; box pendingGraphTerminalCommitCount; box (esc (nativeCutoverTerminalCommitSummary pendingGraphTerminalCommitCount)); box nativeCutoverBackupTickSuppressedCount; box (replayTickProofTupleCompactJsonFields event' reason) |])
                    if nativeCutoverBackupTickSuppressedCount > 0 && (nativeCutoverBackupTickSuppressedCount <= 1 || nativeCutoverBackupTickSuppressedCount % 64 = 0) then
                        let backupSuppressedDrainScheduled =
                            try DiagJson.requestProgressObserverDrainId "native_cutover_backup_tick_suppressed_forced_drain" (CompilerKernelV2.OperationalReasonIdOps.create "terminal_payload_committed_but_parent_sidecar_owner_still_open") 8
