                                    match replayFingerprintIdentity with
                                    | None -> 0
                                    | Some identity ->
                                        lock gate (fun () ->
                                            let mutable prior = 0
                                            let nextCount = if replayFingerprintRepeats.TryGetValue(identity, &prior) then prior + 1 else 1
