                                    && pendingCount() > 0
                                    && replayTaskDriverId task = TermReplayDriver
                                    && replayCellEvalKindId replayCell = EvalTerm
                                    && replayCellShapeId replayCell = CellShapeEPairTest
                                    && replayTaskHasFact ReplayTaskFactSemanticRootComplete task
                                let typeRecordFingerprintRootWitnessDemote =
                                    replayFingerprintRepeatCount >= 3
                                    && pendingCount() > 0
                                    && hasReplayCompleteWriteWitness()
                                    && replayTaskDriverId task = TyReplayDriver
                                    && replayCellEvalKindId replayCell = EvalTy
                                    && replayCellShapeId replayCell = CellShapeTRecord
