                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_record_fingerprint_repeat_deferred_after_root_witness\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"site\":%s,\"shape\":%s,\"repeat_count\":%d,\"pending\":%d,\"policy\":\"preserve_root_complete_and_drain_pending_testing_record_before_terminal_pin\",\"single_flight\":1,\"next\":\"continue_active_replay_driver\"}" [| box (esc event); box task.id; box (esc (replayDriverToString task.driver)); box (esc (replayCellSiteText replayCell)); box (esc (replayCellShapeText replayCell)); box replayFingerprintRepeatCount; box (pendingCount()) |])
