                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_deferred_function_driver_null_guarded\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"status\":%s,\"error_type\":%s,\"message\":%s,\"cell\":%s,\"queue_depth_after\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box rid; box (esc driver); box (esc blockedStatus); box (esc (ex.GetType().Name)); box (esc ex.Message); box (esc cellText); box qdAfter; box (pendingCount()); box (esc blockedNext) |])
                            if typeApplyArgDriverNull then
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_apply_arg_driver_null_guarded\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"status\":%s,\"error_type\":%s,\"message\":%s,\"cell\":%s,\"queue_depth_after\":%d,\"pending\":%d,\"witness\":%s,\"single_flight\":1,\"next\":%s}" [| box (esc event); box rid; box (esc driver); box (esc blockedStatus); box (esc (ex.GetType().Name)); box (esc ex.Message); box (esc cellText); box qdAfter; box (pendingCount()); box (esc (replayCompleteWriteWitnessSummary())); box (esc blockedNext) |])
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_driver_exception_blocked\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"status\":%s,\"error_type\":%s,\"message\":%s,\"cell\":%s,\"payload\":%s,\"queue_depth_after\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box rid; box (esc driver); box (esc status); box (esc (ex.GetType().Name)); box (esc ex.Message); box (esc cellText); box (esc payload); box qdAfter; box (pendingCount()); box (esc blockedNext) |])
                            // MIGRATION: when an ETypeApply replay null has become the explicit
                            // semantic replay-driver terminal, pin the semantic terminal status
                            // rather than the lower-level cell status so pending/deferred live
                            // replay cannot outvote it on the next trampoline tick.
                            if blockedSemanticStatusId = SemanticReplayDriverExceptionBlocked then
