                                    | ReplayExceptionPinTerminal ->
                                        pinTerminalCellId event (CompilerKernelV2.OperationalReasonIdOps.create ("replay_driver_exception:" + blockedReasonTag)) pinnedExceptionCell
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_driver_exception_terminal_pinned\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"exception_kind\":%s,\"reason\":%s,\"pin_policy\":%s,\"replay_drain_state\":%s,\"cell\":%s,\"queue_depth_after\":%d,\"active_depth\":%d,\"pending\":%d,\"pending_graph_authority_rank_du\":\"materialized_exception_terminal_beats_physical_qap\",\"legacy_veto_rejection_reason_du\":\"replay_driver_exception_terminal_rejects_live_tail_reentry\",\"localized_driver_handoff_ready\":true,\"localized_driver_route_du\":\"replay_driver_exception_terminal_driver\",\"terminal_commit_class_du\":\"replay_driver_exception_terminal\",\"pending_graph_dispatch_outcome\":\"TerminalWitnessObservedAwaitingReducerOrActiveDriver\",\"hopac_ivar_resolution_edge\":\"ReplayDriverException->IVar<TerminalPayload>\",\"raw_key_deprecated\":true,\"single_flight\":1,\"next\":\"stop_retry_drain_on_pinned_exception\"}" [| box (esc event); box rid; box (esc driver); box (esc (replayDriverExceptionKindToString replayDriverExceptionKind)); box (esc blockedReasonTag); box (esc blockedPinPolicyText); box (esc blockedDrainStateText); box (esc (formatCell pinnedExceptionCell)); box qdAfter; box (replayDriverActiveDepthValue()); box (pendingCount()) |])
                                    | ReplayExceptionDeferLiveReplay
                                    | ReplayExceptionPreserveRootWitness ->
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_driver_exception_terminal_pin_deferred\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"exception_kind\":%s,\"reason\":%s,\"pin_policy\":%s,\"replay_drain_state\":%s,\"cell\":%s,\"queue_depth_after\":%d,\"active_depth\":%d,\"pending\":%d,\"write_witness\":%b,\"single_flight\":1,\"next\":\"resume_or_explain_live_replay\"}" [| box (esc event); box rid; box (esc driver); box (esc (replayDriverExceptionKindToString replayDriverExceptionKind)); box (esc blockedReasonTag); box (esc blockedPinPolicyText); box (esc blockedDrainStateText); box (esc (formatCell pinnedExceptionCell)); box qdAfter; box (replayDriverActiveDepthValue()); box (pendingCount()); box (hasReplayCompleteWriteWitness()) |])
                                | None -> ()
                            if qdAfter = 0 && replayExceptionTerminalDecision = ReplayDriverExceptionPinNow && not letSuccessApplyContinuationDriverNull && not letSuccessApplyContinuationRootWitnessNull && not applyContinuationRootWitnessNull && not applyContinuationRootWitnessRetryNull && not opContinuationRootWitnessNull && not opContinuationDriverNull then
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_empty_queue_replay_driver_exception_pinned\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"error_type\":%s,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"stop_retry_drain_on_pinned_exception\"}" [| box (esc event); box rid; box (esc driver); box (esc (ex.GetType().Name)); box (esc cellText); box (pendingCount()) |])
                        | None -> ()
                finally
                    let deferredReplayPendingBeforeGate = EvalReplayValueStore.hasDeferredReplayCell()
                    let drainDeferred, terminalNoDeferred, terminalStatus, postActiveQueueDepth, postActivePending, postActiveDriverQuiet =
                        lock gate (fun () ->
                            match executingTaskOpt with
                            | Some task -> replayTaskExecutionClaims.Remove task.id |> ignore
                            | None -> ()
                            replayDriverActiveDepth <- max 0 (replayDriverActiveDepth - 1)
                            let terminalStatus =
                                match frontier with
                                | Some frame -> frame.status
                                | None -> frameUnknown (CompilerKernelV2.OperationalReasonIdOps.create "missing_terminal_frontier")
                            let pinnedTerminalStatusOpt =
                                match pinnedTerminalContract with
                                | Some pinned when terminalContractRank pinned.status >= 68 -> Some pinned.status
                                | _ -> None
                            let deferredReplayPending = deferredReplayPendingBeforeGate
                            let fingerprintRepeatHasDeferred (status:FrameStatusId) =
                                frameStatusSemanticStatusId status = SemanticReplayFingerprintRepeatBlocked
                                && deferredReplayPending
                            let pinnedTerminalNoDeferred =
                                match pinnedTerminalStatusOpt with
                                | Some pinnedStatus when fingerprintRepeatHasDeferred pinnedStatus -> false
                                | Some _ -> true
                                | None -> false
                            let terminalNoDeferred =
                                if fingerprintRepeatHasDeferred terminalStatus then false
                                else isTerminalContractStatusId (frameStatusSemanticStatusId terminalStatus) || pinnedTerminalNoDeferred
                            let effectiveTerminalStatus =
                                if isTerminalContractStatusId (frameStatusSemanticStatusId terminalStatus) then terminalStatus
                                else
                                    match pinnedTerminalStatusOpt with
                                    | Some pinnedStatus -> pinnedStatus
                                    | None -> terminalStatus
                            replayDriverActiveDepth = 0 && replayQueue.IsEmpty, terminalNoDeferred, effectiveTerminalStatus, replayQueue.Length, pendingCountUnlocked(), replayDriverActiveDepth = 0)
                    if postActiveDriverQuiet && postActiveQueueDepth > 0 then
                        let postActiveDrainDecision =
                            parentResumeReplayDrainDecisionFor ParentResumeDrainPostActive postActiveQueueDepth 0 postActivePending
                        if parentResumeReplayDrainDecisionShouldSchedule postActiveDrainDecision then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_post_active_parent_resume_queue_tail_tick_requested\",\"event\":%s,\"decision_du\":%s,\"queue_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"hopac_replay_driver_job\"}" [| box (esc event); box (esc (parentResumeReplayDrainDecisionText postActiveDrainDecision)); box postActiveQueueDepth; box postActivePending |])
                            scheduleReplayDriverTick ReplayTickPostActiveParentResume eventId
                        elif postActiveDrainDecision = ParentResumeReplayDrainHardStopPendingZero then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_post_active_parent_resume_pending_zero_hard_stop\",\"event\":%s,\"decision_du\":%s,\"queue_depth\":%d,\"pending\":%d,\"thread_yielded\":false,\"policy\":\"assessment_pending_zero_post_active_tail_must_not_schedule_tick\",\"single_flight\":1,\"next\":\"surface_existing_terminal_or_wait_real_pending\"}" [| box (esc event); box (esc (parentResumeReplayDrainDecisionText postActiveDrainDecision)); box postActiveQueueDepth; box postActivePending |])
                    elif drainDeferred && terminalNoDeferred then
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_deferred_after_terminal_suppressed\",\"event\":%s,\"status\":%s,\"single_flight\":1,\"next\":\"explicit_terminal_replay_contract\"}"
                                (esc event)
                                (esc (frameStatusToString terminalStatus)))
                    elif drainDeferred && tryScheduleDeferredAfterActiveDriver event then
                        scheduleReplayDriverTick ReplayTickCooperativeHandoff eventId
                    if postActiveDriverQuiet && postActiveQueueDepth = 0 then
                        let operationalCreditDecisionAfterReplay =
                            CompilerKernelV2.SemanticWorkLedgerAuthority.creditDecisionForScope
                                CompilerKernelV2.SemanticWorkOperational
                        if CompilerKernelV2.SemanticWorkCreditDecision.isReturned operationalCreditDecisionAfterReplay then
                            CompilerConsoleHud88.retryTerminalClosure ()
        let replayDriverCooperativeTickFromGlobalFuseId (eventId: ReplayTickEventId) (reasonId: ReplayTickReasonId) =
            try
                let eventText = replayTickEventToString eventId
                let reasonText = replayTickReasonToString reasonId
                let reasonKindText = replayTickReasonKindText reasonId
                let queueDepthAtRequest, activeDepthAtRequest, shouldSchedule, decision, tickPressureId =
                    lock gate (fun () ->
                        let qd = replayQueue.Length
                        let ad = replayDriverActiveDepth
                        let nowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                        let staleQueued = replayDriverStackFenceQueued && replayDriverStackFenceQueuedSinceMs > 0L && nowMs - replayDriverStackFenceQueuedSinceMs > 100L
                        if staleQueued then replayDriverStackFenceQueued <- false
                        let pressureId = replayTickQueuePressureFor qd replayDriverActiveDepth replayDriverStackFenceQueued staleQueued
                        let decision = replayTickRequestDecisionFromPressure pressureId
                        let shouldSchedule =
                            replayTickRequestDecisionShouldSchedule decision
                            && not (DiagJson.terminalFlowRunEndEmittedNow())
                            && not (DiagJson.terminalFailureExitRequestedNow())
                            && (not (DiagJson.terminalSemanticDrainActiveNow()) || ad < 2)
                        if qd > 0 then noteProgressYieldLocked ()
                        if shouldSchedule then
                            replayDriverStackFenceQueued <- true
                            replayDriverStackFenceQueuedSinceMs <- nowMs
                        qd, ad, shouldSchedule, decision, pressureId)
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_global_fuse_deferred_replay_tick_requested\",\"event\":%s,\"event_du\":%s,\"reason\":%s,\"reason_du\":%s,\"reason_kind_du\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"scheduled_async\":%b,\"decision\":%s,\"decision_du\":%s,\"tick_pressure_du\":%s,\"pending\":%d%s,\"single_flight\":1,\"next\":\"native_hopac_callback_or_hopac_replay_driver_job\"}" [| box (esc eventText); box (esc eventText); box (esc reasonText); box (esc reasonText); box (esc reasonKindText); box queueDepthAtRequest; box activeDepthAtRequest; box shouldSchedule; box (esc (replayTickRequestDecisionToString decision)); box (esc (replayTickRequestDecisionToString decision)); box (esc (replayTickQueuePressureText tickPressureId)); box (pendingCount()); box (replayTickProofTupleCompactJsonFields eventText reasonText) |])
                if shouldSchedule then
                    HopacExtensions.start (job {
                        try
                            try
                                runReplayDriver eventId
                            with ex ->
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_global_fuse_deferred_replay_tick_error\",\"event\":%s,\"event_du\":%s,\"reason\":%s,\"reason_du\":%s,\"error_type\":%s,\"message\":%s,\"queue_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"explicit_global_fuse_deferred_replay_tick_error\"}" [| box (esc eventText); box (esc eventText); box (esc reasonText); box (esc reasonText); box (esc (ex.GetType().Name)); box (esc ex.Message); box (replayQueueDepth()); box (pendingCount()) |])
                        finally
                            lock gate (fun () ->
                                replayDriverStackFenceQueued <- false
                                replayDriverStackFenceQueuedSinceMs <- 0L)
                    })
                shouldSchedule
            with _ -> false

        do replayDriverTickRequestHook <- Some replayDriverCooperativeTickFromGlobalFuseId

        let mutable forcedOrphanDrainWorkerRequestOrdinal = 0L

        let forceReplayDriverOrphanDrainWorker (eventId: ReplayTickEventId) (reasonId: OperationalReasonId) =
            let event = replayTickEventToString eventId
            let reason = OperationalReasonIdOps.text reasonId
            try
                let qd, ad, shouldStart =
                    lock gate (fun () ->
                        let qd = replayQueue.Length
                        let ad = replayDriverActiveDepth
                        let nowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                        let staleQueued =
                            replayDriverStackFenceQueued
                            && replayDriverStackFenceQueuedSinceMs > 0L
                            && nowMs - replayDriverStackFenceQueuedSinceMs > 100L
                        if staleQueued then
                            replayDriverStackFenceQueued <- false
                            replayDriverStackFenceQueuedSinceMs <- 0L
                        let shouldStart = qd > 0 && ad <= 0 && not replayDriverStackFenceQueued
                        if shouldStart then
                            replayDriverStackFenceQueued <- true
                            replayDriverStackFenceQueuedSinceMs <- nowMs
                            noteProgressYieldLocked ()
                        qd, ad, shouldStart)
                let forcedOrphanOrdinal = lock gate (fun () -> forcedOrphanDrainWorkerRequestOrdinal <- forcedOrphanDrainWorkerRequestOrdinal + 1L; forcedOrphanDrainWorkerRequestOrdinal)
                let shouldEmitForcedOrphanDrainReceipt =
                    shouldStart
                    || forcedOrphanOrdinal <= 4L
                    || forcedOrphanOrdinal = 16L
                    || forcedOrphanOrdinal = 64L
                    || forcedOrphanOrdinal % 512L = 0L
                if shouldEmitForcedOrphanDrainReceipt then
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_forced_orphan_drain_worker_requested\",\"event\":%s,\"reason\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"scheduled_async\":%b,\"hot_row_recycle_count\":%d,\"duplicate_rows_suppressed\":%d,\"pending_graph_authority_rank_du\":\"forced_orphan_worker_is_legacy_drain_only\",\"localized_driver_handoff_ready\":false,\"policy\":\"q_gt_zero_a_zero_gets_bounded_explicit_worker_before_watchdog_abort_recycled_after_generic\",\"single_flight\":1,\"next\":\"hopac_replay_driver_job_or_pending_graph_terminal_if_present\"}" [| box (esc event); box (esc reason); box qd; box ad; box shouldStart; box forcedOrphanOrdinal; box (max 0L (forcedOrphanOrdinal - 4L)) |])
                if shouldStart then
                    HopacExtensions.start (job {
                        try
                            try
                                runReplayDriver eventId
                            with ex ->
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_forced_orphan_drain_worker_error\",\"event\":%s,\"reason\":%s,\"error_type\":%s,\"message\":%s,\"queue_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"explicit_forced_orphan_drain_error\"}" [| box (esc event); box (esc reason); box (esc (ex.GetType().Name)); box (esc ex.Message); box (replayQueueDepth()); box (pendingCount()) |])
                        finally
                            lock gate (fun () ->
                                replayDriverStackFenceQueued <- false
                                replayDriverStackFenceQueuedSinceMs <- 0L)
                    })
                shouldStart
            with _ -> false

        type ForcedDrainTerminalAuthorityId =
            | ForcedDrainIdleCrossKindActiveTySidecar
            | ForcedDrainApplySpineStoreDirect
            | ForcedDrainObservedPinnedTerminalContract
            | ForcedDrainNoRootBudgetParentReplayImmediateFill
            | ForcedDrainDynamicJoinCooperativeAltTimeout
            | ForcedDrainDynamicJoinBridgeTailHandoff

        let forcedDrainTerminalAuthorityIdText = function
            | ForcedDrainIdleCrossKindActiveTySidecar -> "idle_cross_kind_active_ty_sidecar"
            | ForcedDrainApplySpineStoreDirect -> "apply_spine_store_direct"
            | ForcedDrainObservedPinnedTerminalContract -> "observed_pinned_terminal_contract"
            | ForcedDrainNoRootBudgetParentReplayImmediateFill -> "no_root_budget_parent_replay_immediate_fill"
            | ForcedDrainDynamicJoinCooperativeAltTimeout -> "dynamic_join_cooperative_alt_timeout"
            | ForcedDrainDynamicJoinBridgeTailHandoff -> "dynamic_join_bridge_tail_handoff"

        type ForcedDrainDispatchDispositionId =
            | ForcedDrainTerminalWitnessObserved
            | ForcedDrainActiveDriverOwnsQueue
            | ForcedDrainReplayTickScheduled

        let forcedDrainDispatchDispositionText = function
            | ForcedDrainTerminalWitnessObserved -> "terminal_witness_observed_no_dispatch"
            | ForcedDrainActiveDriverOwnsQueue -> "active_driver_owns_queue"
            | ForcedDrainReplayTickScheduled -> "replay_tick_scheduled"

        type OwnerDebtDrainTriggerId =
            | OwnerDebtDrainTriggerNone
            | OwnerDebtDrainTriggerOpenOwner
            | OwnerDebtDrainTriggerParentGraph
            | OwnerDebtDrainTriggerSemanticDebt

        let private ownerDebtDrainTriggerText = function
            | OwnerDebtDrainTriggerNone -> "none"
            | OwnerDebtDrainTriggerOpenOwner -> "open_owner"
            | OwnerDebtDrainTriggerParentGraph -> "parent_graph"
            | OwnerDebtDrainTriggerSemanticDebt -> "semantic_debt"

        let private ownerDebtDrainTriggerExplicitOnly = OwnerDebtDrainTriggerNone

        let private ownerDebtDrainTriggerIsOpen = function
            | OwnerDebtDrainTriggerNone -> false
            | OwnerDebtDrainTriggerOpenOwner
            | OwnerDebtDrainTriggerParentGraph
            | OwnerDebtDrainTriggerSemanticDebt -> true

        let private ownerDebtDrainTriggerIsSpecific = function
            | OwnerDebtDrainTriggerParentGraph
            | OwnerDebtDrainTriggerSemanticDebt -> true
            | OwnerDebtDrainTriggerNone
            | OwnerDebtDrainTriggerOpenOwner -> false

        type OwnerDebtPressureAdmissionId =
            | OwnerDebtPressureNoWork
            | OwnerDebtPressureCoalescedIntoActiveOwner of queueDepth:int * activeDepth:int
            | OwnerDebtPressureSuppressedByScheduledPulse of queueDepth:int
            | OwnerDebtPressureStartSingleOwner of queueDepth:int

        let private ownerDebtPressureAdmissionFor scheduledAny pressureEligible queueDepth activeDepth =
            if not pressureEligible || queueDepth <= 0 then OwnerDebtPressureNoWork
            elif activeDepth > 0 then OwnerDebtPressureCoalescedIntoActiveOwner(queueDepth, activeDepth)
            elif scheduledAny then OwnerDebtPressureSuppressedByScheduledPulse queueDepth
            else OwnerDebtPressureStartSingleOwner queueDepth

        let private ownerDebtPressureAdmissionMayStart = function
            | OwnerDebtPressureStartSingleOwner _ -> true
            | OwnerDebtPressureNoWork
            | OwnerDebtPressureCoalescedIntoActiveOwner _
            | OwnerDebtPressureSuppressedByScheduledPulse _ -> false

        let private ownerDebtPressureAdmissionText = function
            | OwnerDebtPressureNoWork -> "OwnerDebtPressureAdmission(NoWork)"
