                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_owner_debt_drain_live_work_tie_breaker_required\",\"event\":%s,\"reason\":%s,\"before_qap\":\"%d/%d/%d\",\"after_qap\":\"%d/%d/%d\",\"material_delta\":%d,\"recent_material_delta_active\":%b,\"recent_material_delta_count\":%d,\"qap_moved_after_drain\":%b,\"tie_breaker_injected\":%b,\"tie_breaker_attempt_count\":%d,\"productive_tie_breaker_count\":%d,\"productive_tie_breaker_active\":%b,\"owner_axis_id\":\"semantic_fact_debt\",\"owner_axis_authority_violation_du\":\"OwnerDrainAuthorityViolation(ZeroDeltaStillOpenRequiresRegisteredWakerOrDeadlock)\",\"owner_axis_receipt_consumption_du\":\"OwnerAxisReceiptConsumption(RejectedUntilAxisReducesOrExpires)\",\"root_writer_handoff_instruction_du\":\"RootWriterFailClosedAfterViolationUnlessTieBreakerProducesDelta\",\"owner_axis_drain_decision_du\":\"OwnerAxisDrainDecision(ZeroDeltaStillOpen|axis=semantic_fact_debt|lease=tie_breaker|requires=deferred_type_var_or_deadlock_expiry)\",\"owner_axis_monotonicity_du\":%s,\"semantic_fact_debt_payment_du\":\"SemanticFactDebtPayment(StillOpenTieBreakerRequiredAfterZeroDeltaOwnerDrain)\",\"terminal_quorum_after_drain_du\":\"TerminalQuorum(owner_debt_drain_live_work_tie_breaker_required|live_qap_after_drain|root_must_force_semantic_tie_breaker_before_terminal)\",\"root_promise_status_du\":\"RootPromiseWaiting(owner_debt_drain_live_work_tie_breaker_required)\",\"terminal_close_requires_du\":\"qap_empty_or_semantic_tie_breaker_exhaustion_without_recent_injection_or_recent_material_delta_before_terminal\",\"semantic_tie_breaker_progress_du\":%s,\"single_flight\":1,\"next\":\"force_semantic_tie_breaker_before_terminal_close\"}" [| box (esc event); box (esc reason); box beforeQ; box beforeA; box beforeP; box afterQ; box afterA; box afterP; box materialDelta; box materialDeltaActive; box (int materialDeltaCount); box qapMovedAfterDrain; box tieBreakerInjected; box tieBreakerAttemptCount; box productiveTieBreakerCount; box productiveTieBreakerActive; box (esc ownerAxisMonotonicityDu); box (esc semanticTieBreakerProgress) |])
                                if ownerDebtDrainZeroDeltaQuarantine then
                                    let terminalLine =
                                        FastRuntimeFormat.format "{\"kind\":\"terminal_owner_debt_drain_zero_delta_reducer_evidence\",\"event\":%s,\"source_row_ref\":\"eval_worklist_force_owner_debt_drain_receipt\",\"terminal_commit_receipt_id\":\"terminal-receipt:owner-axis-zero-delta-quarantine\",\"owner_axis_drain_decision_du\":\"OwnerAxisDrainDecision(ExpiredToDeadlock|axis=semantic_fact_debt|receipt=terminal-receipt:owner-axis-zero-delta-quarantine)\",\"root_promise_status_du\":\"RootPromiseFailed(owner_debt_drain_zero_delta_quarantine)\",\"root_complete_await_contract_du\":\"RootCompleteAwaitArmed(reason=owner_debt_drain_zero_delta_quarantine)\",\"root_complete_exit_policy_du\":\"fail_closed_after_bounded_owner_debt_drain_zero_delta\",\"owner_close_results\":\"OwnerCloseResults(parent_replay_poison=closed_by_bounded_owner_debt_drain|parent_or_sidecar=closed_by_zero_delta_quarantine|cross_kind=closed_by_zero_delta_quarantine|close_key=owner_debt_drain_zero_delta_quarantine)\",\"breakthrough_axes_after_drain\":\"BreakthroughAxes(owner_closure=true|work_dag_closure=true|scheduler_causality=true|semantic_fact_debt=true|reason=owner_debt_drain_zero_delta_quarantine)\",\"terminal_quorum_after_drain_du\":\"TerminalQuorum(owner_debt_drain_zero_delta_quarantine|owners_closed_by_bounded_owner_drain|work_dag_exhausted_no_material_delta|scheduler_causality_closed|semantic_fact_debt_quarantined)\",\"owner_deadlock_closed_terminal_prerequisites\":true,\"terminal_collapse_to_build_error_trace\":true,\"root_terminal_outcome_du\":\"RootTerminalOutcome(FailedClosed|source=owner_debt_zero_delta_quarantine)\",\"fail_closed_exit_authority_du\":\"FailClosedExitAuthority(ByOwnerDrainViolation|violation=OwnerDrainAuthorityViolation(ExpiredToDeadlock|axis=semantic_fact_debt)|terminal_gate=terminal-root-gate:owner-axis-zero-delta-quarantine)\",\"armed_wait_graph_spine_du\":\"ArmedWaitGraphSpine(id=spine:owner-axis-zero-delta-quarantine|qap=zero-delta|unarmed=0|dropped=0)\",\"scheduler_push_event_du\":\"SchedulerPushEvent(PushFailClosed|source=owner_axis_zero_delta_quarantine)\",\"scheduler_push_authority_du\":\"SchedulerPushAuthority(id=push:owner-axis-zero-delta-quarantine|writer_required=false|renderer=false|metronome=false)\",\"breakthrough_exit_arbiter_du\":\"BreakthroughFailedClosed(contract=exit-contract:owner-axis-zero-delta-quarantine|authority=owner_drain_violation|spine=spine:owner-axis-zero-delta-quarantine)\",\"terminal_authority_migration_status_du\":\"TerminalAuthorityMigration(round=7of5|push_events=1|renderer_rejected=0|arbiter=failed_closed)\",\"native_terminal_exit_contract_du\":\"NativeTerminalExitContract(id=exit-contract:owner-axis-zero-delta-quarantine|outcome=failed_closed|authority=owner_drain_violation|exit=1)\",\"finish_fast_terminal\":false,\"force_owner_debt_drain_receipt\":\"terminal_after_zero_delta_owner_debt_drain|pending=%d|queue=%d|active=%d|material_delta=0\",\"terminal_close_requires_du\":\"axis_local_zero_delta_deadlock_or_quarantine_receipt\",\"next\":\"await_native_root_complete_alt\"}" [| box (esc event); box afterP; box afterQ; box afterA |]
                                    // The evaluator may certify procedural exhaustion, but it no longer owns
