            scheduledAny

        let forceReplayDriverDrainPassId (event: string) (reasonId: CompilerKernelV2.OperationalReasonId) (attempts: int) =
            forceReplayDriverDrainPassTagged OwnerDebtDrainTriggerNone None event reasonId attempts

        let forceReplayDriverDrainPassForTerminalAuthority (authorityId: ForcedDrainTerminalAuthorityId) (event: string) (reasonId: CompilerKernelV2.OperationalReasonId) (attempts: int) =
            forceReplayDriverDrainPassTagged OwnerDebtDrainTriggerNone (Some authorityId) event reasonId attempts

        let forceReplayDriverDrainPassParentGraphId (event: string) (reasonId: CompilerKernelV2.OperationalReasonId) (attempts: int) =
            forceReplayDriverDrainPassTagged OwnerDebtDrainTriggerParentGraph None event reasonId attempts

        let forceReplayDriverDrainPassSemanticDebtId (event: string) (reasonId: CompilerKernelV2.OperationalReasonId) (attempts: int) =
            forceReplayDriverDrainPassTagged OwnerDebtDrainTriggerSemanticDebt None event reasonId attempts

        // MIGRATION: semantic-drain dispatch must be a bounded scheduling pulse.
        // The legacy forced drain pass may execute a long owner-debt traversal and is
        // retained for older explicit rescue paths, but the reducer-owned QAP lease
        // only asks the cooperative replay driver to run one materializing tick.
        let requestSemanticDrainPulse (eventId: ReplayTickEventId) (reasonId: ReplayTickReasonId) =
            let eventText = replayTickEventToString eventId
            let reasonText = replayTickReasonToString reasonId
            let scheduled = replayDriverCooperativeTickFromGlobalFuseId eventId reasonId
            if scheduled then true
            else
                let queueDepth = replayQueueDepth()
                let activeDepth = replayDriverActiveDepthValue()
                if queueDepth > 0 && activeDepth > 0 then
                    // An existing replay owner already holds the materializing lane.  The
                    // reducer request is accepted/coalesced rather than reported as a false
                    // failed dispatch that invites another procedural fanout.
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_semantic_drain_pulse_coalesced\",\"event\":%s,\"reason\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"authority\":\"existing_active_replay_owner\",\"single_flight\":1}" [| box (esc eventText); box (esc reasonText); box queueDepth; box activeDepth |])
                    true
                elif queueDepth > 0 && activeDepth = 0 && not (DiagJson.terminalFailureExitRequestedNow()) then
                    // The normal pressure gate can reject a pulse because of a stale stack
                    // fence.  A reducer-owned semantic drain may start exactly one bounded
                    // Hopac driver when the queue is non-empty and no driver owns it.
                    HopacExtensions.start (job {
                        try runReplayDriver eventId
                        with ex ->
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_semantic_drain_direct_pulse_error\",\"event\":%s,\"reason\":%s,\"error_type\":%s,\"message\":%s,\"single_flight\":1}" [| box (esc eventText); box (esc reasonText); box (esc (ex.GetType().Name)); box (esc ex.Message) |])
                    })
                    true
                else false

        do DiagJson.registerProgressObserverDrainRequestHook (fun event reasonId attempts ->
            forceReplayDriverDrainPassId event reasonId attempts)

        do EvalReplayValueStore.installParentCacheHandoffWake (fun () ->
            try
                // MIGRATION: MIGRATION proved the cache-write callback drains
                // parent handoffs into replayQueue, but no replay driver was
                // scheduled afterwards.  The second callback is intentionally
                // separate from the drain callback: first commit/drain, then
                // ask the cooperative driver to run the queued parent work.
                let queueDepthBeforeWake = replayQueueDepth()
                let activeDepthBeforeWake = replayDriverActiveDepthValue()
                let wakeDecision =
                    lock gate (fun () ->
                        parentReplayDriverWakeDecisionFor replayQueue.Length replayDriverActiveDepth replayDriverStackFenceQueued)
                let scheduled =
                    match wakeDecision with
                    | ParentReplayDriverWakeScheduleTick ->
                        replayDriverCooperativeTickFromGlobalFuseId
                            ReplayTickEventCacheWriteParentHandoffWakeCallback
                            ReplayTickReasonPostCommitParentQueueDriverTick
                    | ParentReplayDriverWakeNoQueue
                    | ParentReplayDriverWakeAlreadyActive
                    | ParentReplayDriverWakeSuppressQueuedFence -> false
                // The row's proof-tuple fields cost ~4% of a large compile to build; skip them when quiet.
                if not DiagJson.quiet then
                 DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_parent_handoff_driver_wake_requested\",\"event\":\"cache_write_parent_handoff_wake_callback\",\"decision_du\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"scheduled_async\":%b,\"pending\":%d%s,\"materialized_terminal_payload_du\":\"ParentCacheHandoffWake\",\"pending_graph_shard_state\":\"TerminalPayload(ParentCacheHandoffWake)\",\"jsonl_recycle_du\":\"emit_once_then_compact_parent_cache_handoff_wake\",\"single_flight\":1,\"next\":\"native_hopac_callback_or_hopac_replay_driver_job\"}" [| box (esc (parentReplayDriverWakeDecisionText wakeDecision)); box queueDepthBeforeWake; box activeDepthBeforeWake; box scheduled; box (pendingCount()); box (pendingGraphProofTupleJsonFields (proofTupleForParentCacheHandoffWake "cache_write_parent_handoff_wake_callback")) |]
                  )
            with _ -> ())

        do
            DiagJson.setNoWorkStallPoke (fun () ->
                try
                    // MIGRATION: the MIGRATION no-work worker started, then never
                    // reached its finished receipt.  The old first move called
                    // pendingCount()/replayQueueDepth(), both of which can wait on the
                    // evaluator gate while the heartbeat is trying to rescue that very
                    // gate.  Take a bounded snapshot first; if the evaluator still owns
                    // the gate, emit a reproducible gate-busy frontier and let the worker
                    // finish instead of leaving rescue_in_flight pinned forever.
                    let mutable gateTaken = false
                    let mutable gateBusy = false
                    let mutable qdBefore = -1
                    let mutable adBefore = -1
                    let mutable pendingBefore = -1
                    let mutable wasQueued = false
                    let mutable rootWitnessBefore = false
                    let mutable releasedActive = false
                    let gateBusySeen = DiagJson.noWorkRescueGateBusyCount()
                    let gateWaitMs = DiagJson.noWorkGateProbeWaitMs gateBusySeen
                    let probePolicy = DiagJson.noWorkGateProbePolicyText (DiagJson.noWorkGateProbePolicyFor gateBusySeen)
                    try
                        // Repeated gate_busy receipts showed that a fixed 64ms probe proved
                        // obstruction but could not distinguish a hot owner from a nearly-free gate.
                        // Escalate bounded waits by typed policy so the rescue can inspect more
                        // often without ever becoming an unbounded pin.
                        gateTaken <- System.Threading.Monitor.TryEnter(gate, gateWaitMs)
                        if gateTaken then
                            qdBefore <- replayQueue.Length
                            adBefore <- replayDriverActiveDepth
                            pendingBefore <- pendingCountUnlocked()
                            rootWitnessBefore <- hasReplayCompleteWriteWitness()
                            wasQueued <- replayDriverStackFenceQueued
                            replayDriverStackFenceQueued <- false
                            replayDriverStackFenceQueuedSinceMs <- 0L
                            let orphanedRootWitnessActive =
                                replayDriverActiveDepth > 0
                                && replayQueue.IsEmpty
                                && (pendingBefore <= 0 || (rootWitnessBefore && pendingBefore <= 2))
                                && rootWitnessBefore
                            let orphanedDeferredActive =
                                // MIGRATION: historical runtime still ended with q=0/a>0/p=2.
                                // In a no-work rescue window, a small pending/deferred tail plus
                                // an empty replay queue means active depth is stale ownership, not
                                // runnable work.  Clear the active counter only; do not promote any
                                // root/writer/codegen authority.
                                replayDriverActiveDepth > 0
                                && replayQueue.IsEmpty
                                && pendingBefore > 0
                                && pendingBefore <= 2
                                && not rootWitnessBefore
                            if replayDriverActiveDepth > 0 && (replayQueue.Length > 0 || pendingBefore > 0 || wasQueued || orphanedRootWitnessActive || orphanedDeferredActive) then
                                replayDriverActiveDepth <- 0
                                releasedActive <- true
                        else
                            gateBusy <- true
                    finally
                        if gateTaken then System.Threading.Monitor.Exit(gate)
                    if gateBusy then
                        DiagJson.noteNoWorkRescueGateBusy ()
                        let gateBusyRescueDecisionId = DiagJson.noWorkGateBusyRescueDecisionFor gateBusySeen
                        let replayTickRequested =
                            match gateBusyRescueDecisionId with
                            | DiagJson.NoWorkGateBusyScheduleReplayTick
                            | DiagJson.NoWorkGateBusyScheduleSparseReplayTick ->
                                HopacExtensions.start (job {
                                    try
                                        try
                                            runReplayDriver ReplayTickEventHeartbeatNoWorkGateBusy
                                        with ex ->
                                            DiagJson.emit (
                                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_heartbeat_no_work_gate_busy_replay_tick_error\",\"event\":\"heartbeat_no_work_gate_busy\",\"decision_du\":%s,\"error_type\":%s,\"message\":%s,\"single_flight\":1,\"next\":\"explicit_no_work_gate_busy_replay_tick_error\"}" [| box (esc (DiagJson.noWorkGateBusyRescueDecisionText gateBusyRescueDecisionId)); box (esc (ex.GetType().Name)); box (esc ex.Message) |])
                                    finally
                                        try
                                            lock gate (fun () ->
                                                replayDriverStackFenceQueued <- false
                                                replayDriverStackFenceQueuedSinceMs <- 0L)
                                        with _ -> ()
                                })
                                true
                            | _ -> false
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_heartbeat_no_work_rescue_gate_busy\",\"event\":\"heartbeat_no_work_stall\",\"gate_wait_ms\":%d,\"gate_busy_seen\":%d,\"rescue_probe_policy_du\":%s,\"gate_busy_rescue_decision_du\":%s,\"queue_depth_before\":%d,\"active_depth_before\":%d,\"pending\":%d,\"root_witness\":%b,\"released_active_depth\":%b,\"scheduled_deferred\":false,\"swept_stale_frontiers\":0,\"replay_tick_requested\":%b,\"single_flight\":1,\"next\":%s}" [| box gateWaitMs; box gateBusySeen; box (esc probePolicy); box (esc (DiagJson.noWorkGateBusyRescueDecisionText gateBusyRescueDecisionId)); box qdBefore; box adBefore; box pendingBefore; box rootWitnessBefore; box releasedActive; box replayTickRequested; box (esc (if replayTickRequested then "hopac_replay_driver_job_from_gate_busy" else "gate_busy_worker_finished_no_pinned_rescue")) |])
                    else
                        let scheduledDeferred =
                            if qdBefore <= 0 && pendingBefore > 0 then tryScheduleDeferredAfterActiveDriver "heartbeat_no_work_stall"
                            else false
                        let qdAfterDeferred =
                            if scheduledDeferred then replayQueueDepth()
                            else qdBefore
                        let sweptStaleFrontiers =
                            if qdAfterDeferred <= 0 && pendingBefore > 0 then heartbeatRootWitnessQuiescenceSweep()
                            else 0
                        let qdAfter =
                            if scheduledDeferred || sweptStaleFrontiers > 0 then replayQueueDepth()
                            else qdAfterDeferred
                        let adAfter =
                            if scheduledDeferred || sweptStaleFrontiers > 0 then replayDriverActiveDepthValue()
                            elif releasedActive then 0
                            else adBefore
                        let replayObligationNoWorkProbe =
                            qdAfter <= 0
                            && pendingBefore <= 0
                            && (DiagJson.snapshotKindCount "eval_worklist_replay_obligation_deferred" > 0
                                || DiagJson.snapshotKindCount "eval_worklist_replay_obligation_deferred_cross_kind_shielded" > 0)
                        let directBurstEligible = qdAfter > 0 || replayObligationNoWorkProbe
                        let replayTickRequested, directBurstExecuted =
                            if directBurstEligible then
                                if replayObligationNoWorkProbe then
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_heartbeat_replay_obligation_no_work_probe_requested\",\"event\":\"heartbeat_no_work_stall\",\"queue_depth_after\":%d,\"active_depth_after\":%d,\"pending\":%d,\"root_witness\":%b,\"single_flight\":1,\"next\":\"direct_replay_driver_burst_final_obligation_probe\"}" [| box qdAfter; box adAfter; box pendingBefore; box rootWitnessBefore |])
                                try
                                    try
                                        runReplayDriver ReplayTickEventHeartbeatNoWorkStallDirectBurst
                                        true, true
                                    with ex ->
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_heartbeat_no_work_replay_tick_error\",\"event\":\"heartbeat_no_work_stall_direct_burst\",\"error_type\":%s,\"message\":%s,\"queue_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"explicit_no_work_direct_burst_error\"}" [| box (esc (ex.GetType().Name)); box (esc ex.Message); box (replayQueueDepth()); box (pendingCount()) |])
                                        false, true
                                finally
                                    lock gate (fun () ->
                                        replayDriverStackFenceQueued <- false
                                        replayDriverStackFenceQueuedSinceMs <- 0L)
                            else false, false
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_heartbeat_nowork_rescue\",\"event\":\"heartbeat_no_work_stall\",\"gate_wait_ms\":%d,\"gate_busy_seen\":%d,\"rescue_probe_policy_du\":%s,\"queue_depth_before\":%d,\"queue_depth_after\":%d,\"active_depth_before\":%d,\"active_depth_after\":%d,\"pending\":%d,\"root_witness\":%b,\"gate_busy\":false,\"released_active_depth\":%b,\"scheduled_deferred\":%b,\"swept_stale_frontiers\":%d,\"replay_tick_requested\":%b,\"direct_burst_executed\":%b,\"nested_threadpool_handoff\":false,\"single_flight\":1,\"next\":\"direct_replay_driver_burst_or_quiescence_sweep\"}" [| box gateWaitMs; box gateBusySeen; box (esc probePolicy); box qdBefore; box qdAfter; box adBefore; box adAfter; box pendingBefore; box rootWitnessBefore; box releasedActive; box scheduledDeferred; box sweptStaleFrontiers; box replayTickRequested; box directBurstExecuted |])
                        if releasedActive && qdAfter = 0 && pendingBefore <= 0 then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_heartbeat_no_work_orphan_active_released\",\"event\":\"heartbeat_no_work_stall\",\"active_depth_before\":%d,\"active_depth_after\":%d,\"root_witness\":%b,\"queue_depth\":%d,\"pending\":%d,\"policy\":\"orphan_active_depth_release_only_no_buildok_promotion\",\"single_flight\":1,\"next\":\"retry_after_releasing_orphan_replay_active_depth\"}" [| box adBefore; box adAfter; box rootWitnessBefore; box qdAfter; box pendingBefore |])
                with ex ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_heartbeat_no_work_replay_rescue_error\",\"event\":\"heartbeat_no_work_stall\",\"error_type\":%s,\"message\":%s,\"single_flight\":1,\"next\":\"explicit_no_work_rescue_error\"}"
                            (esc (ex.GetType().Name)) (esc ex.Message)))

        let maybeWakeReplayAfterGlobalFuseDeferral (eventId: ReplayTickEventId) (reasonId: ReplayTickReasonId) =
            try
                let qd = replayQueueDepth()
                let ad = replayDriverActiveDepthValue()
                let pendingAtRequest = pendingCount()
                // MIGRATION: MIGRATION showed a real deferred replay queue with
                // pending=1/queue=1/active=1 at rust.spi:266.  Waiting for
                // active_depth>=8 was too conservative there: the single active
                // parent had already yielded a concrete child replay obligation.
                if qd > 0 && (ad >= 1 || pendingAtRequest <= 1) then
                    replayDriverCooperativeTickFromGlobalFuseId eventId reasonId |> ignore
            with _ -> ()


        let frontierSummary () =
            match snapshot 1 with
            | frame :: _ ->
                let cell =
                    match frame.semanticCell with
                    | Some c -> short 160 (formatCell c)
                    | None -> "none"
                FastRuntimeFormat.format "frontier kind=%s status=%s depth=%d re=%d/%d trace=%d cursor=%d replay_queue=%d driver=%s payload=%s cell=%s site=%s key=%s" [| box (evalKindToString frame.kind); box (frameStatusToString frame.status); box frame.depth; box frame.re; box frame.maxRe; box frame.trace.Length; box frame.cursor; box (replayQueueDepth()); box (replayDriverStatus()); box (semanticPayloadStatus()); box cell; box (short 96 (frameSiteText frame)); box (short 120 (frameKeyText frame)) |]
            | [] -> "frontier empty"

        let panel () =
            try
                let frames = snapshot 3
                if frames.IsEmpty then "" else
                    let sb = System.Text.StringBuilder()
                    sb.AppendFormat("eval.worklist pending={0} single_flight=1 active={1}", frames.Length, (if activeRun then 1 else 0)) |> ignore
                    frames
                    |> List.iteri (fun i frame ->
                        sb.AppendLine() |> ignore
                        let cell =
                            match frame.semanticCell with
                            | Some c -> short 120 (formatCell c)
                            | None -> "none"
                        let line =
                            FastRuntimeFormat.format "  #%d kind=%s status=%s depth=%d re=%d/%d trace=%d cursor=%d replay_queue=%d driver=%s payload=%s cell=%s site=%s" [| box i; box (evalKindToString frame.kind); box (frameStatusToString frame.status); box frame.depth; box frame.re; box frame.maxRe; box frame.trace.Length; box frame.cursor; box (replayQueueDepth()); box (replayDriverStatus()); box (semanticPayloadStatus()); box cell; box (short 92 (frameSiteText frame)) |]
                        sb.Append(line) |> ignore)
                    sb.ToString().TrimEnd()
            with _ -> ""

        let emitPanel (event: string) =
            try
                let n = pendingCount()
                let summary = frontierSummary()
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_panel\",\"event\":%s,\"pending\":%d,\"single_flight\":1,\"active\":%d,\"replay_queue\":%d,\"semantic_payload\":%s,\"summary\":%s}" [| box (esc event); box n; box (if activeRun then 1 else 0); box (replayQueueDepth()); box (esc (semanticPayloadStatus())); box (esc summary) |])
            with _ -> ()

        let fromCycleFuseId (reasonId: CompilerKernelV2.OperationalReasonId) : Frame =
            let visitKind, key, site, depth, _gen, re, maxRe = TermCycleFuse.describe()
            let frameKind =
                match visitKind with
                | Some EvalVisitTerm -> EvalTerm
                | Some EvalVisitType -> EvalTy
                | None -> EvalUnknown (CompilerKernelV2.OperationalReasonIdOps.create "term_cycle_fuse_open_without_kind")
            { kind = frameKind
              key = ReplayKeyIdOps.create key
              keySignals = replayFrameKeySignalsAtIngress key
              site = CompilerIdentityKernel.WorkSiteIdOps.create site
              depth = depth
              re = re
              maxRe = maxRe
              trace = TermCycleFuse.traceSnapshot() |> traceOfTermCycleFuseTrace |> compactTrace
              reason = reasonId
              reasonFacts = reasonId |> CompilerKernelV2.OperationalReasonIdOps.text |> DiagnosticClassifier.classifyFacts
              status = FrameBlockedByReentry
              cursor = 0
              payload = FramePayloadMissing }

        let emit (event: string) (frame: Frame) : unit =
            try
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_frame\",\"event\":%s,\"reason\":%s,\"frame_kind\":%s,\"key\":%s,\"site\":%s,\"depth\":%d,\"re\":%d,\"max_re\":%d,\"trace_lines\":%d,\"status\":%s,\"cursor\":%d,\"single_flight\":1}" [| box (esc event); box (esc (frameReasonToString frame.reason)); box (esc (evalKindToString frame.kind)); box (esc (frameKeyText frame)); box (esc (frameSiteText frame)); box frame.depth; box frame.re; box frame.maxRe; box frame.trace.Length; box (esc (frameStatusToString frame.status)); box frame.cursor |])
            with _ -> ()

        let attachSemanticPayload (event: string) (payload: string) : unit =
            try
                let payload = short 1800 payload
                let attached =
                    lock gate (fun () ->
                        match frontier with
                        | Some frame ->
                            let frame' = { frame with payload = FrameLegacySemanticPayload (frameLegacySemanticPayloadId payload) }
                            frontier <- Some frame'
                            true
                        | None -> false)
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_payload\",\"event\":%s,\"attached\":%d,\"semantic_payload\":%s,\"pending\":%d,\"single_flight\":1}" [| box (esc event); box (if attached then 1 else 0); box (esc (if attached then "semantic" else "missing_frontier")); box (pendingCount()) |])
            with _ -> ()

        let attachSemanticCell (eventId: ReplayTickEventId) (cell: ReplayCell) : unit =
            try
                let event = replayTickEventToString eventId
                let tickEventId = eventId
                let payload = formatCellPayload cell |> short 1800
                rememberSemanticCell cell
                let attached, attachStatus =
                    lock gate (fun () ->
                        selectKindLocked cell.kind |> ignore
                        match frontier with
                        | Some frame when frameEvalKindId frame = cellEvalKindId cell ->
                            // MIGRATION: do not let a completed same-kind frame masquerade as
                            // completion for a different incoming semantic cell.  This was the
                            // MIGRATION live-loop: frame=listm.spi:6/root_complete, cell=TJoinPoint'
                            // at runtime.spi:330.  Keep the trace shell, retarget it to the end,
                            // and force a continuation envelope so the typed replay driver handles
                            // the incoming cell instead of repeatedly attempting build.
                            // MIGRATION: when a scheduled parent replay is active, the incoming same-kind
                            // child cell is useful evidence, but it must not overwrite the parent cell that
                            // the queued replay task is about to reduce. MIGRATION showed the hot loop:
                            // ETypeApply(parent) -> EForall'(child) -> parent_resume -> child overwrite -> ...
                            let sameNodeParentReplayProtected =
                                match replayQueue, frame.semanticCell with
                                | task :: _, Some parent ->
                                    // MIGRATION: MIGRATION's tail is not a child-over-parent overwrite;
                                    // it is the active scheduled_parent_replay receiving the same
                                    // TJoinPoint' node as a fresh semantic cell and immediately poking
                                    // itself.  Defer that same-node payload so the queued parent replay
                                    // can advance instead of re-entering the same driver frame.
                                    let taskTargetsIncoming =
                                        replayTaskReferencesNode cell.nodeId task
                                    replayTaskStatusIsScheduledParent (replayTaskStatusId task)
                                    && taskTargetsIncoming
                                    && sameReplayNode parent cell
                                    && cellSemanticStatusId parent <> SemanticRootComplete
                                    && cellSemanticStatusId parent <> SemanticLeafComplete
                                | _ -> false
                            let activeReplayCellProtected =
                                if sameNodeParentReplayProtected then false
                                else
                                    match replayQueue, frame.semanticCell with
                                    | task :: _, Some parent ->
                                        // MIGRATION: MIGRATION preserved scheduled_parent_replay, but the same
                                        // overwrite hazard appears for a root continuation replay: a scheduled
                                        // EApply(trace.spi:295) is on the replay queue, then a late EUnitTest
                                        // child cell arrives and replaces the frontier before the driver reduces
                                        // the original continuation.  Protect any in-flight same-kind replay
                                        // cell whose queued payload/key points at the current frontier cell.
                                        let taskTargetsParent =
                                            replayTaskReferencesNode parent.nodeId task
                                            || (replayTaskStatusIsScheduledParent (replayTaskStatusId task) && replayTaskHasFact ReplayTaskFactParentKey task)
                                        let activeReplayStatus =
                                            replayTaskStatusIsQueuedReplay (replayTaskStatusId task)
                                        activeReplayStatus
                                        && taskTargetsParent
                                        && parent.kind = cell.kind
                                        && parent.nodeId <> cell.nodeId
                                        && cellSemanticStatusId parent <> SemanticRootComplete
                                        && cellSemanticStatusId parent <> SemanticLeafComplete
                                    | _ -> false
                            let staleRootComplete =
                                if sameNodeParentReplayProtected || activeReplayCellProtected then false
                                else
                                    frameSemanticStatusIs SemanticRootComplete frame
                                    && (match frame.semanticCell with
                                        | Some old -> old.nodeId <> cell.nodeId || old.site <> cell.site || old.shape <> cell.shape || old.kind <> cell.kind || cellSemanticStatusId old <> SemanticRootComplete
                                        | None -> frame.site <> cell.site)
                            let staleRootRetargetCount =
                                if staleRootComplete then
                                    let identity : StaleRootRetargetIdentity = {
                                        incoming = replayCellIdentity cell
                                        frameKey = frame.key
                                        frameCursor = frame.cursor
                                    }
                                    let mutable prior = 0
                                    let next = if staleRootRetargetRepeats.TryGetValue(identity, &prior) then prior + 1 else 1
                                    staleRootRetargetRepeats.[identity] <- next
                                    next
                                else 0
                            let staleRootRetargetQuarantined = staleRootComplete && staleRootRetargetCount > 3
                            // MIGRATION: a stale-root retarget must not overwrite an already
                            // replay-complete root frame even before quarantine.  Historical runtime
                            // showed repeated eval_worklist_stale_root_complete_retargeted before
                            // the final stale TV mask; defer the stale cell immediately.
                            let suppressRootCompleteRetarget =
                                staleRootComplete
                                && frameReplayCompleteAny frame
                            let rootCompleteStaleRetargetHardCap = 32
                            let rootCompleteStaleRetargetTerminal =
                                suppressRootCompleteRetarget
                                && staleRootRetargetCount >= rootCompleteStaleRetargetHardCap
                            // MIGRATION: historical runtime hit the hard cap with the root and
                            // incoming cell describing the same ty/TRecord node/site/shape at
                            // spiral.spi:2670.  That is not a new stale terminal; it is the
                            // root-complete frame echoing its own semantic cell with a stale
                            // cell-status.  Align the cell with the already-proven frame and
                            // keep the root evidence instead of pinning a synthetic terminal.
                            let sameRootCompleteCellEcho =
                                rootCompleteStaleRetargetTerminal
                                && frameSemanticStatusIs SemanticRootComplete frame
                                && (match frame.semanticCell with
                                    | Some old ->
                                        old.kind = cell.kind
                                        && old.nodeId = cell.nodeId
                                        && old.site = cell.site
                                        && old.shape = cell.shape
                                    | None ->
                                        frameEvalKindId frame = cellEvalKindId cell
                                        && frame.site = cell.site)
                            let sameSiteAppRootRetargetEcho =
                                // MIGRATION: MIGRATION showed the same app-root hardcap can
                                // arrive as TRecord first and then as TFun at the identical
                                // ty@apps/spiral/spiral.spi:2670 site.  Once the live frame is
                                // semantic_root_complete and the incoming cell is same-kind and
                                // same-site app root evidence, shape is not a stronger proof of
                                // failure.  Preserve the root witness instead of pinning the
                                // synthetic stale-retarget terminal.
                                rootCompleteStaleRetargetTerminal
                                && frameSemanticStatusIs SemanticRootComplete frame
                                && frameEvalKindId frame = cellEvalKindId cell
                                && frame.site = cell.site
                                && frameIsRootCompleteEvidence frame
                            let appRootBase16StaleRetargetEcho =
                                // MIGRATION: historical runtime proved MIGRATION did not hit the
                                // previous post-finalization demote.  The live root was the
                                // app tests frontier at spiral.spi:2670, while the stale
                                // incoming type cell was a core/base.spi:16 TUnion echo.
                                // The hardcap is still synthetic: keep the root frontier and
                                // leave the stale base16 cell deferred/quarantined instead of
                                // turning it into a terminal contract.
                                rootCompleteStaleRetargetTerminal
                                && frameSemanticStatusIs SemanticRootComplete frame
                                && frameEvalKindId frame = EvalTy
                                && replayCellEvalKindId cell = EvalTy
                                && frameIsRootCompleteEvidence frame
                                && (replayCellShapeId cell = CellShapeTUnion || replayCellShapeId cell = CellShapeTNominal)
                                && pendingCount() <= 2
                            let rootCompleteStaleRetargetShouldEmit =
                                staleRootRetargetCount <= 4
                                || staleRootRetargetCount = 8
                                || staleRootRetargetCount = 16
                                || staleRootRetargetCount = 32
                                || staleRootRetargetCount = rootCompleteStaleRetargetHardCap
                            let cursor' = if staleRootComplete then frame.trace.Length else frame.cursor
                            let retargetStatus =
                                if staleRootRetargetQuarantined then ReplayCellProtocolStaleRootRetargetQuarantined
                                elif staleRootComplete then ReplayCellProtocolStaleRootRetargeted
                                else ReplayCellProtocolCaptured
                            let cell' = { cell with cursor = cursor'; status = ReplayCellProtocolStatus retargetStatus }
                            // MIGRATION: if a fresh same-kind semantic cell replaces a frame that was
                            // carrying a parent semantic cell, keep the typed child -> parent edge.
                            // MIGRATION ended with EOp(real_core.spir:150) as semantic_leaf_complete
                            // while the frame/key still represented the ETypeApply at spiral.spi:2671.
                            // Without this edge the driver can only repeat leaf_complete_parent_continuation_missing.
                            // MIGRATION: frame_semantic_child is an artificial edge used to
