                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_same_node_parent_replay_drain_tick_requested\",\"event\":%s,\"reason\":\"same_node_parent_replay_self_poke\",\"decision_du\":%s,\"tick_decision_du\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"hopac_replay_driver_job\"}" [| box (esc event); box (esc sameNodeDecisionText); box (esc (replayTickRequestDecisionToString sameNodeTickDecision)); box sameNodeQueueDepth; box sameNodeActiveDepth; box sameNodePending |])
                                replayDriverCooperativeTickFromGlobalFuseId tickEventId ReplayTickReasonSameNodeParentReplayDrainTick |> ignore
                    else
                        if idleDeferredChildPoke then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_idle_deferred_replay_poke_resumed\",\"event\":%s,\"reason\":\"idle_deferred_child_cell\",\"queue_depth\":%d,\"semantic_payload\":%s,\"single_flight\":1,\"next\":\"run_replay_driver\"}" [| box (esc event); box (replayQueueDepth()); box (esc attachStatusText) |])
                        if idleCrossKindPoke then
                            let obligation = makeReplayObligation ReplayObligationRun ReplayReasonIdleCrossKindDriver 0 1 cell
                            emitReplayObligation event "eval_worklist_replay_obligation_run" obligation
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_idle_cross_kind_replay_poke_resumed\",\"event\":%s,\"reason\":\"idle_cross_kind_replay_driver\",\"idle_cross_kind_replay_driver_kind\":%s,\"idle_cross_kind_replay_driver_site\":%s,\"idle_cross_kind_replay_driver_duration_ms\":0,\"idle_cross_kind_replay_driver_awaiting\":\"cross_kind_sibling_or_parent_continuation_cell\",\"incoming_kind\":%s,\"incoming_shape\":%s,\"incoming_site\":%s,\"incoming_node_id\":%d,\"queue_depth\":%d,\"semantic_payload\":%s,\"single_flight\":1,\"next\":\"run_replay_driver\"}" [| box (esc event); box (esc (evalKindToString cell.kind)); box (esc (replayCellSiteText cell)); box (esc (evalKindToString cell.kind)); box (esc (replayCellShapeText cell)); box (esc (replayCellSiteText cell)); box cell.nodeId; box (replayQueueDepth()); box (esc attachStatusText) |])
                        let replayDriverProofKey = FastRuntimeFormat.format "%s|%s|%s|node:%d" [| box event; box (replayCellKindText cell); box (replayCellSiteText cell); box cell.nodeId |]
                        let replayDriverProofTuple = proofTupleForReentryPrefetchTerminalDriver replayDriverProofKey
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_driver_poke\",\"event\":%s,\"reason\":\"semantic_cell_attached\",\"queue_depth\":%d,\"semantic_payload\":%s,\"materialized_terminal_payload_du\":%s,\"pending_graph_shard_state\":%s%s,\"single_flight\":1,\"next\":\"run_reentry_prefetch_terminal_driver_immediately\"}" [| box (esc event); box (replayQueueDepth()); box (esc attachStatusText); box (esc (materializedTerminalOutcomeText MaterializedTerminalReentryPrefetchTerminalDriver)); box (esc (typedTerminalPayloadText (reentryPrefetchTerminalDriverTypedTerminalPayload replayDriverProofKey))); box (pendingGraphProofTupleJsonFields replayDriverProofTuple) |])
                        runReplayDriver eventId
            with _ -> ()

        let resetStableRootCompleteLedger () =
            lock gate (fun () ->
                stableRootCompleteKey <- None
                stableRootCompleteCount <- 0)

        let beginBuildEpoch () =
            // MIGRATION: reopen cache-handoff admission only for a genuinely new
            // top-level build. Retry resets remain volatile and cannot reopen it.
            let staleHandoffs = EvalReplayValueStore.quarantineParentCacheHandoffsAfterRootComplete()
            lock gate (fun () ->
                parentCacheHandoffBuildAdmission <- ParentCacheHandoffOpenForBuild
                replayRootCompleteWitnessUtc <- System.DateTime.MinValue
                replayRootFirstCompleteWitnessUtc <- System.DateTime.MinValue
                replayRootCompleteWitnessSummary <- ""
                replayRootCompleteWitnessIdentity <- "")
            DiagJson.emit (
                sprintf "{\"kind\":\"parent_cache_handoff_build_epoch_opened\",\"stale_handoff_count\":%d,\"admission_du\":\"OpenForBuild\",\"authority\":\"attempt_zero_only\",\"next\":\"close_monotonically_at_first_root_witness\"}"
                    staleHandoffs)

        let reset () =
            lock gate (fun () ->
                frontier <- None
                frontierTerm <- None
                frontierTy <- None
                activeRun <- false
                replayScheduledKey <- None
                replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                replayDriverStackFenceQueued <- false
                replayFingerprintRepeats.Clear()
                replayCanonicalRootParentResumeConsumed.Clear()
                replayCanonicalRootObservationRepeats.Clear()
                frameDerivedTyPingPongSuppressionRepeats.Clear()
                replayChildScheduleRepeats.Clear()
                reentrantReplayPokeRepeats.Clear()
                parentReplayPreservedRepeats.Clear()
                staleRootRetargetRepeats.Clear()
                leafParentContinuationYieldRepeats.Clear()
                resetPendingGraphProofTupleSnapshots()
                // MIGRATION: volatile retry reset must not erase build-epoch root authority.
                // beginBuildEpoch is the only owner allowed to clear these witnesses.
                progressYieldCount <- 0)

        let tryPeek () : Frame option =
            lock gate (fun () -> frontier)

        let captureId (reasonId: CompilerKernelV2.OperationalReasonId) : Frame =
            let fresh = fromCycleFuseId reasonId
            let event, frame =
                lock gate (fun () ->
                    selectKindLocked fresh.kind |> ignore
                    match frontier with
                    | Some old when sameCycle old fresh ->
                        slotSetLocked old
                        "capture:dedup", old
                    | _ ->
                        captureSeq <- captureSeq + 1L
                        frontier <- Some fresh
                        slotSetLocked fresh
                        replayScheduledKey <- None
                        replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                        // MIGRATION: captures may churn while the same root-complete proof recurs;
                        // keep the cross-attempt stable ledger and let noteRootCompleteHandoff
                        // decide whether the fingerprint is new or repeated.
                        "captured", fresh)
            emit event frame
            emitPanel "capture"
            frame


        let ensureCapturedForKindId (requestedKindId: ReplayFrontierKindId) (reasonId: CompilerKernelV2.OperationalReasonId) : Frame option =
            match requestedKindId with
            | ReplayFrontierTerm -> lock gate (fun () -> selectKindLockedId EvalTerm |> ignore)
            | ReplayFrontierTy -> lock gate (fun () -> selectKindLockedId EvalTy |> ignore)
            | ReplayFrontierUnknown -> ()
            match tryPeek() with
            | Some frame when requestedKindId = ReplayFrontierUnknown -> Some frame
            | Some frame when requestedKindId = ReplayFrontierTerm && frameEvalKindId frame = EvalTerm -> Some frame
            | Some frame when requestedKindId = ReplayFrontierTy && frameEvalKindId frame = EvalTy -> Some frame
            | Some _ when TermCycleFuse.isTripped() -> Some (captureId reasonId)
            | Some _ -> None
            | None ->
                if TermCycleFuse.isTripped() then Some (captureId reasonId)
                else None


        let private replaceHead (frame': Frame) : Frame =
            lock gate (fun () ->
                frontier <- Some frame'
                frame')

        let promoteHead (event: string) : Frame option =
            try
                let promoted =
                    lock gate (fun () ->
                        match frontier with
                        | Some frame ->
                            let alreadyRunning =
                                frameStatusIs FrameReadyExplicitLoop frame ||
                                frameStatusIs FrameTracingExplicitLoop frame ||
                                frameStatusIs FrameContinuationEnvelope frame ||
                                isSemanticTerminalFrame frame
                            let frame' =
                                if alreadyRunning then frame
                                else { frame with status = FrameReadyExplicitLoop; cursor = min frame.cursor frame.trace.Length }
                            frontier <- Some frame'
                            Some(frame', alreadyRunning)
                        | None -> None)
                match promoted with
                | Some(frame', alreadyRunning) ->
                    emit (event + (if alreadyRunning then ":already_ready" else ":promoted")) frame'
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_consume\",\"event\":%s,\"pending\":%d,\"status\":%s,\"cursor\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (pendingCount()); box (esc (frameStatusToString frame'.status)); box frame'.cursor; box (esc (if activeRun then "single_flight_busy" else "bounded_trampoline")) |])
                    Some frame'
                | None -> None
            with _ -> None

        let private traceAt (frame: Frame) (i: int) =
            try
                if i < 0 || i >= frame.trace.Length then ""
                else
                    let r = frame.trace.[i]
                    let a, b = r.range
                    FastRuntimeFormat.format "%s:%d:%d-%d:%d" [| box r.path; box a.line; box a.character; box b.line; box b.character |]
            with _ -> ""

        // MIGRATION: global-fuse diagnostics are often the visible terminal, while the
        // actual trace lives in the selected frontier or the TermCycleFuse snapshot.
        // Emit a compact JSON fragment so global-fuse records no longer look empty.
        let globalFuseTraceJson () =
            try
                let frameOpt = lock gate (fun () -> frontier)
                let frame, source =
                    match frameOpt with
                    | Some frame when frame.trace.Length > 0 -> frame, "frontier"
                    | _ -> fromCycleFuseId (CompilerKernelV2.OperationalReasonIdOps.create "global_fuse_trace_context"), "replay_repeat_guard"
                let traceN = frame.trace.Length
                let head =
                    frame.trace
                    |> List.truncate 4
                    |> List.mapi (fun i _ -> sprintf "%d:%s" i (traceAt frame i))
                    |> String.concat "|"
                let tail =
                    let skipN = max 0 (traceN - 4)
                    frame.trace
                    |> List.skip skipN
                    |> List.mapi (fun i _ -> sprintf "%d:%s" (skipN + i) (traceAt frame (skipN + i)))
                    |> String.concat "|"
                FastRuntimeFormat.format "\"trace_source\":%s,\"trace_lines\":%d,\"trace_cursor\":%d,\"trace_site\":%s,\"trace_key\":%s,\"trace_head\":%s,\"trace_tail\":%s" [| box (esc source); box traceN; box frame.cursor; box (esc (frameSiteText frame)); box (esc (frameKeyText frame)); box (esc head); box (esc tail) |]
            with _ ->
                "\"trace_source\":\"error\",\"trace_lines\":0,\"trace_cursor\":0,\"trace_site\":\"\",\"trace_key\":\"\",\"trace_head\":\"\",\"trace_tail\":\"\""

        let private adapterPayload (frame: Frame) =
            try
                let traceN = frame.trace.Length
                let head =
                    frame.trace
                    |> List.truncate 8
                    |> List.mapi (fun i _ -> sprintf "%d:%s" i (traceAt frame i))
                    |> String.concat "|"
                let tail =
                    let skipN = max 0 (traceN - 8)
                    frame.trace
                    |> List.skip skipN
                    |> List.mapi (fun i _ -> sprintf "%d:%s" (skipN + i) (traceAt frame (skipN + i)))
                    |> String.concat "|"
                let focus =
                    if traceN <= 0 then ""
                    else traceAt frame (min (max 0 frame.cursor) (traceN - 1))
                let replayMode =
                    match frameEvalKindId frame with
                    | EvalTerm -> "term_replay"
                    | EvalParentResume -> "parent_resume_replay"
                    | EvalTy -> "ty_replay"
                    | EvalData -> "data_replay"
                    | EvalCodegen -> "codegen_replay"
                    | EvalDynamicJoin -> "dynamic_join_replay"
                    | EvalUnknown _ -> "unknown_replay"
                FastRuntimeFormat.format "replay_continuation(mode=%s,kind=%s,key=%s,site=%s,cursor=%d/%d,focus=%s,semantic=%s,head=%s,tail=%s)" [| box replayMode; box (evalKindToString frame.kind); box (frameKeyText frame); box (frameSiteText frame); box frame.cursor; box traceN; box focus; box (semanticPayloadOf frame); box head; box tail |]
            with _ ->
                FastRuntimeFormat.format "replay_continuation(kind=%s,key=%s,site=%s,cursor=%d/%d,semantic=%s)" [| box (evalKindToString frame.kind); box (frameKeyText frame); box (frameSiteText frame); box frame.cursor; box frame.trace.Length; box (semanticPayloadOf frame) |]

        [<StructuralEquality; NoComparison>]
        type private SemanticReplayDispatchId =
            | SemanticReplayDispatch of semanticStatus:SemanticStatusId * next:ReplayCommitNextId

        let private semanticReplayDispatchFor statusId =
            let next =
                match statusId with
                | SemanticApplyContinuationAfterSeqUnknownBlocked -> replayCommitNextExplicit "explicit_eval_worklist_apply_continuation_after_seq_unknown_required"
                | SemanticIfUnknownReturnConditionBlocked -> replayCommitNextExplicit "explicit_eval_worklist_if_unknown_return_condition_required"
                | SemanticReplayFingerprintRepeatBlocked -> ReplayNextReplayFingerprintRepeatDirectRequired
                | SemanticJoinpointTermStepperBlocked -> ReplayNextJoinpointTermStepperDirectRequired
                | SemanticRootComplete -> ReplayNextAttemptBuild
                | SemanticLeafComplete -> ReplayNextParentContinuationDirectRequired
                | SemanticPayloadRequired -> replayCommitNextOther "wire_eval_payload"
                | SemanticStepPartial -> replayCommitNextOther "native_hopac_real_stepper_direct_required"
                | terminalStatus when isTerminalContractStatusId terminalStatus -> ReplayNextSemanticStatus terminalStatus
                | _ -> replayCommitNextOther "bounded_trampoline"
            SemanticReplayDispatch(statusId, next)

        let private semanticReplayDispatchNext = function
            | SemanticReplayDispatch(_, next) -> next

        let private nextForId (frame: Frame) =
            match frameStatusId frame with
            | FrameContinuationEnvelope -> replayCommitNextOther "schedule_term_ty_replay"
            | FrameTracingExplicitLoop -> replayCommitNextOther "advance_trace_cursor"
            | FrameReadyExplicitLoop -> replayCommitNextOther "bounded_trampoline"
            | _ ->
                frameSemanticStatusId frame
                |> semanticReplayDispatchFor
                |> semanticReplayDispatchNext

        let private nextFor (frame: Frame) =
            nextForId frame |> replayCommitNextIdText

        // MIGRATION: a semantic_leaf_complete frame with no registered parent
        // continuation is not a root proof and must not spin the retry drain forever.
        // MIGRATION proved real replay progress up to term_type_apply_type_arg_scheduled
        // and dynamic join leaf completion, but the jp_wait_cycle_drain tail then kept
        // re-entering explicit_eval_worklist_parent_continuation_required while another
        // kind-local frontier was pending.  Park the leaf in its kind slot and yield the
        // canonical frontier to the alternate live kind; this is fail-closed because it
        // never marks semantic_root_complete and never opens the writer gate.
        let private tryYieldLeafParentContinuationBlocked (event: string) (frame: Frame) : Frame option =
            try
                let switched =
                    lock gate (fun () ->
                        let noParentContinuation =
                            match frame.semanticCell with
                            | Some cell -> EvalReplayValueStore.tryParentContinuationForChildKind (evaluatorNodeKindForEvalKind cell.kind) cell.nodeId |> Option.isNone
                            | None -> true
                        let blockedLeaf =
                            frameStatusIs FrameSemanticLeafComplete frame
                            && replayQueue.IsEmpty
                            && noParentContinuation
                            && not (frameReplayCompleteAny frame)
                        if not blockedLeaf then None
                        else
                            slotSetLocked frame
                            let alternate =
                                let other =
                                    if frameEvalKindId frame = EvalTerm then frontierTy
                                    elif frameEvalKindId frame = EvalTy then frontierTerm
                                    else None
                                match other with
                                | Some alt when not (sameCycle alt frame) && not (frameSemanticStatusIs SemanticLeafComplete alt) && not (frameSemanticStatusIs SemanticRootComplete alt) -> Some alt
                                | _ -> None
                            let tryRepairAlternateTerminalLetCycleLocked (alt: Frame) : Frame option =
                                match alt.semanticCell with
                                | Some cell when frameSemanticStatusIs SemanticParentContinuationCycleBlocked alt
                                                 && frameEvalKindId alt = EvalTerm
                                                 && replayCellEvalKindId cell = EvalTerm
                                                 && replayCellShapeId cell = CellShapeELet ->
                                    match EvalReplayValueStore.tryLetSpine cell.nodeId with
                                    | Some spine ->
                                        let makeChildReplay role shape nodeId status (nextId: ReplayCommitNextId) =
                                            let roleText = EvalReplayValueStore.evaluatorDependencyRoleText role
                                            let attempt = noteLetTerminalCycleRepairLocked cell.nodeId role nodeId
                                            if attempt > 8 then None
                                            else
                                                EvalReplayValueStore.putParentContinuation nodeId {
                                                    parentKind = evaluatorNodeKindForEvalKind cell.kind
                                                    parentShape = cell.shape
                                                    parentNodeId = cell.nodeId
                                                    role = role
                                                }
                                                let childCell = { cell with shape = shape; nodeId = nodeId; status = status; step = 0 }
                                                let repaired =
                                                    { alt with
                                                        status = FrameContinuationEnvelope
                                                        cursor = alt.trace.Length
                                                        reason = frameReasonAppend alt.reason ":leaf_yield_terminal_let_cycle_replay"
                                                        payload = FrameSemanticCellPayload childCell }
                                                frontier <- Some repaired
                                                slotSetLocked repaired
                                                replayScheduledKey <- None
                                                replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                                                noteProgressYieldLocked ()
                                                DiagJson.emit (
                                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_let_cycle_replay\",\"event\":%s,\"route\":\"leaf_yield\",\"let_node_id\":%d,\"role\":%s,\"attempt\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box cell.nodeId; box (esc roleText); box attempt; box (esc (formatCell childCell)); box (pendingCount()); box (esc (replayCommitNextIdText nextId)) |])
                                                Some repaired
                                        let missingBody =
                                            spine.bodyNodeIds
                                            |> Array.mapi (fun i nodeId -> i, nodeId)
                                            |> Array.tryFind (fun (_, nodeId) -> not (EvalReplayValueStore.tryTermReady nodeId))
                                        match missingBody with
                                        | Some (i, nodeId) ->
                                            let shape = if i < spine.bodyShapes.Length then spine.bodyShapes.[i] else CompilerIdentityKernel.WorkShapeIdOps.Known.unknown
                                            makeChildReplay (EvaluatorLetBody i) shape nodeId (ReplayCellReadyStatus ReplayCellReadyLetBody) ReplayNextScheduleLetBody
                                        | None when not (EvalReplayValueStore.tryTermReady spine.successNodeId) ->
                                            makeChildReplay EvaluatorLetSuccess spine.successShape spine.successNodeId (ReplayCellReadyStatus ReplayCellReadyLetSuccess) ReplayNextScheduleLetSuccess
                                        | None -> None
                                    | None -> None
                                | _ -> None
                            match alternate with
                            | Some alt ->
                                let yieldCount, yieldKey =
                                    if event = "retry_stop_drain" then noteLeafParentContinuationYieldLocked frame alt
                                    else 1, ""
                                let leafYieldChurnCapped =
                                    event = "retry_stop_drain"
                                    && yieldCount > leaf_parent_continuation_yield_cap
                                    && frameStatusIs FrameContinuationEnvelope alt
                                    && pendingCount() > 0
                                let leafYieldCrossKindContinuationHandoff =
                                    leafYieldChurnCapped
                                    && frameEvalKindId frame = EvalTy
                                    && frameStatusIs FrameSemanticLeafComplete frame
                                    && frameCellShapeIn [CellShapeEApply] frame
                                    && frameEvalKindId alt = EvalTerm
                                    && frameStatusIs FrameContinuationEnvelope alt
                                    && frameHasSemanticEvidence alt
                                    && (match frame.semanticCell with
                                        | Some cell ->
                                            replayCellEvalKindId cell = EvalTerm
                                            && replayCellShapeId cell = CellShapeEApply
                                            && cellFrameStatusIs FrameSemanticLeafComplete cell
                                        | None -> false)
                                if leafYieldCrossKindContinuationHandoff then
                                    // MIGRATION: historical runtime proved the generic churn cap can stop
                                    // just after it schedules a live runtime fixture path:23 continuation
                                    // for the tests() leaf at spiral.spi:2670.  This exact handoff is
                                    // not a terminal missing-parent contract yet: preserve the selected
                                    // continuation envelope and its existing replay queue so the drain
                                    // can execute the scheduled replay instead of clearing it.
                                    let handoffFrame = { alt with reason = frameReasonAppend alt.reason ":leaf_parent_testing_handoff_churn_deferred" }
                                    frontier <- Some handoffFrame
                                    slotSetLocked handoffFrame
                                    replayScheduledKey <- None
                                    noteProgressYieldLocked ()
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_leaf_parent_testing_handoff_churn_deferred\",\"event\":%s,\"leaf_kind\":%s,\"leaf_site\":%s,\"leaf_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"selected_site\":%s,\"count\":%d,\"cap\":%d,\"pending\":%d,\"yield_key\":%s,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}" [| box (esc event); box (esc (evalKindToString frame.kind)); box (esc (frameSiteText frame)); box (esc (frameStatusToString frame.status)); box (esc (evalKindToString handoffFrame.kind)); box (esc (frameStatusToString handoffFrame.status)); box (esc (frameSiteText handoffFrame)); box yieldCount; box leaf_parent_continuation_yield_cap; box (pendingCount()); box (esc yieldKey) |])
                                    Some handoffFrame
                                elif leafYieldChurnCapped then
                                    let terminalFrame =
                                        { frame with
                                            status = frameStatusOfSemanticStatusId SemanticLeafParentContinuationMissingBlocked
                                            reason = frameReasonAppend frame.reason ":leaf_parent_yield_churn_capped" }
                                    frontier <- Some terminalFrame
                                    slotSetLocked terminalFrame
                                    replayScheduledKey <- None
                                    replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                                    pinTerminalContractLocked event terminalFrame
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_leaf_parent_yield_churn_capped\",\"event\":%s,\"leaf_kind\":%s,\"leaf_site\":%s,\"leaf_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"selected_site\":%s,\"count\":%d,\"cap\":%d,\"pending\":%d,\"yield_key\":%s,\"single_flight\":1,\"next\":\"explicit_eval_worklist_leaf_parent_continuation_required\"}" [| box (esc event); box (esc (evalKindToString frame.kind)); box (esc (frameSiteText frame)); box (esc (frameStatusToString frame.status)); box (esc (evalKindToString alt.kind)); box (esc (frameStatusToString alt.status)); box (esc (frameSiteText alt)); box yieldCount; box leaf_parent_continuation_yield_cap; box (pendingCount()); box (esc yieldKey) |])
                                    Some terminalFrame
                                else
                                    match tryRepairAlternateTerminalLetCycleLocked alt with
                                    | Some repaired -> Some repaired
                                    | None ->
                                        frontier <- Some alt
                                        replayScheduledKey <- None
                                        replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                                        Some alt
                            | None -> None)
                match switched with
                | Some alt ->
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_leaf_parent_continuation_yielded\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}" [| box (esc event); box (esc (evalKindToString frame.kind)); box (esc (frameStatusToString frame.status)); box (esc (evalKindToString alt.kind)); box (esc (frameStatusToString alt.status)); box (pendingCount()) |])
                    Some alt
                | None -> None
            with _ -> None

        // MIGRATION: a parent-continuation cycle blocker is useful evidence but not a
        // reason to keep rebuilding the same continuation envelope.  Park the blocked
        // frame in its kind slot and yield to another already-live frontier when one
        // exists.  If no alternate exists, leave the blocked frame terminal so retry_stop
        // reports explicit_eval_worklist_parent_continuation_cycle_required instead of
        // spinning another replay envelope.
        let private tryYieldParentContinuationCycleBlocked (event: string) (frame: Frame) : Frame option =
            try
                let makeTerminalCompositeReplayLocked (cell: ReplayCell) role childKind (shape: CompilerIdentityKernel.WorkShapeId) nodeId status (nextId: ReplayCommitNextId) =
                    let roleText = EvalReplayValueStore.evaluatorDependencyRoleText role
                    let attempt = noteCompositeTerminalCycleRepairLocked cell.shape cell.nodeId role childKind nodeId
                    if attempt > 12 then None
                    else
                        EvalReplayValueStore.putParentContinuationForChildKind (evaluatorNodeKindForEvalKind childKind) nodeId {
                            parentKind = evaluatorNodeKindForEvalKind cell.kind
                            parentShape = cell.shape
                            parentNodeId = cell.nodeId
                            role = role
                        }
                        let childCell =
                            { cell with
                                kind = childKind
                                shape = shape
                                nodeId = nodeId
                                status = status
                                step = 0 }
                        let repaired =
                            { frame with
                                kind = childKind
                                status = FrameContinuationEnvelope
                                cursor = frame.trace.Length
                                reason = frameReasonAppend frame.reason ":terminal_composite_cycle_replay"
                                payload = FrameSemanticCellPayload childCell }
                        frontier <- Some repaired
                        slotSetLocked repaired
                        replayScheduledKey <- None
                        replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                        noteProgressYieldLocked ()
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_composite_cycle_replay\",\"event\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"role\":%s,\"child_kind\":%s,\"child_shape\":%s,\"child_node_id\":%d,\"attempt\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (esc (evalKindToString cell.kind)); box (esc (replayCellShapeText cell)); box cell.nodeId; box (esc roleText); box (esc (evalKindToString childKind)); box (esc (CompilerIdentityKernel.WorkShapeIdOps.text shape)); box nodeId; box attempt; box (esc (formatCell childCell)); box (pendingCount()); box (esc (replayCommitNextIdText nextId)) |])
                        Some repaired

                let terminalCompositeRootEligible (cell: ReplayCell) =
                    cell.kind = frame.kind
                    && (frame.cursor >= frame.trace.Length || cell.cursor >= frame.trace.Length)

                let terminalCompositeStatusAndNext (cell: ReplayCell) =
                    if terminalCompositeRootEligible cell then
                        SemanticRootComplete, ReplayNextAttemptBuild, "eval_worklist_terminal_composite_cycle_root_resolved"
                    else
                        SemanticLeafComplete, ReplayNextParentContinuationDirectRequired, "eval_worklist_terminal_composite_cycle_value_resolved"

                let clearParentCycleTerminalAfterCompositeRootLocked (resolvedStatusId: SemanticStatusId) (cell: ReplayCell) =
                    if resolvedStatusId = SemanticRootComplete then
                        let matches (pinned: Frame) =
                            (frameSemanticStatusIs SemanticParentContinuationCycleBlocked pinned || frameSemanticStatusIs SemanticParentContinuationCycleDeferred pinned)
                            && (pinned.key = frame.key
                                || pinned.site = frame.site
                                || (match pinned.semanticCell with
                                    | Some pinnedCell -> pinnedCell.kind = cell.kind && pinnedCell.nodeId = cell.nodeId
                                    | None -> false))
                        let pinnedCleared =
                            match pinnedTerminalContract with
                            | Some pinned when matches pinned ->
                                pinnedTerminalContract <- None
                                true
                            | _ -> false
                        let durableCleared =
                            match durableTerminalContract with
                            | Some pinned when matches pinned ->
                                durableTerminalContract <- None
                                true
                            | _ -> false
                        if pinnedCleared || durableCleared then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_parent_cycle_terminal_cleared_after_composite_root\",\"event\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"pinned_cleared\":%b,\"durable_cleared\":%b,\"pending\":%d,\"single_flight\":1,\"next\":\"attempt_build_without_stale_terminal_contract\"}" [| box (esc event); box (esc (evalKindToString cell.kind)); box (esc (replayCellShapeText cell)); box cell.nodeId; box pinnedCleared; box durableCleared; box (pendingCount()) |])

                let completeCompositeIfReadyLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryTermDetailed cell.nodeId with
                    | Choice1Of2 value ->
                        EvalReplayValueStore.putTermValue cell.nodeId value
                        let resolvedStatusId, resolvedNext, resolvedKind = terminalCompositeStatusAndNext cell
                        let resolvedStatus = frameStatusOfSemanticStatusId resolvedStatusId
                        let resolvedCell = { cell with status = ReplayCellSemanticStatus resolvedStatusId }
                        let resolved =
                            { frame with
                                kind = cell.kind
                                status = resolvedStatus
                                payload = FrameSemanticCellPayload resolvedCell }
                        clearParentCycleTerminalAfterCompositeRootLocked resolvedStatusId cell
                        frontier <- Some resolved
                        slotSetLocked resolved
                        noteProgressYieldLocked ()
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":%s,\"event\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc resolvedKind); box (esc event); box (esc (evalKindToString cell.kind)); box (esc (replayCellShapeText cell)); box cell.nodeId; box (esc (formatCell resolvedCell)); box (pendingCount()); box (esc (replayCommitNextIdText resolvedNext)) |])
                        Some resolved
                    | Choice2Of2 detail ->
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_composite_cycle_value_blocked\",\"event\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"detail\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}" [| box (esc event); box (esc (evalKindToString cell.kind)); box (esc (replayCellShapeText cell)); box cell.nodeId; box (esc detail); box (pendingCount()) |])
                        None

                let completeTypeCompositeIfReadyLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryTypeDetailed cell.nodeId with
                    | Choice1Of2 value ->
                        EvalReplayValueStore.putTypeValue cell.nodeId value
                        let resolvedStatusId, resolvedNext, resolvedKind = terminalCompositeStatusAndNext cell
                        let resolvedStatus = frameStatusOfSemanticStatusId resolvedStatusId
                        let resolvedCell = { cell with status = ReplayCellSemanticStatus resolvedStatusId }
                        let resolved =
                            { frame with
                                kind = cell.kind
                                status = resolvedStatus
                                payload = FrameSemanticCellPayload resolvedCell }
                        clearParentCycleTerminalAfterCompositeRootLocked resolvedStatusId cell
                        frontier <- Some resolved
                        slotSetLocked resolved
                        noteProgressYieldLocked ()
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":%s,\"event\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc (resolvedKind + "_ty")); box (esc event); box (esc (evalKindToString cell.kind)); box (esc (replayCellShapeText cell)); box cell.nodeId; box (esc (formatCell resolvedCell)); box (pendingCount()); box (esc (replayCommitNextIdText resolvedNext)) |])
                        Some resolved
                    | Choice2Of2 detail ->
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_type_composite_cycle_value_blocked\",\"event\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"detail\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}" [| box (esc event); box (esc (evalKindToString cell.kind)); box (esc (replayCellShapeText cell)); box cell.nodeId; box (esc detail); box (pendingCount()) |])
                        None

                let tryRepairTerminalSeqCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.trySeqSpine cell.nodeId with
                    | Some spine ->
                        if not (EvalReplayValueStore.tryTermReady spine.firstNodeId) then
                            makeTerminalCompositeReplayLocked cell EvaluatorSequenceFirst EvalTerm spine.firstShape spine.firstNodeId (ReplayCellReadyStatus ReplayCellReadySeqFirst) ReplayNextScheduleSeqChild
                        elif not (EvalReplayValueStore.tryTermReady spine.secondNodeId) then
                            makeTerminalCompositeReplayLocked cell EvaluatorSequenceSecond EvalTerm spine.secondShape spine.secondNodeId (ReplayCellReadyStatus ReplayCellReadySeqSecond) ReplayNextScheduleSeqChild
                        else
                            completeCompositeIfReadyLocked cell
                    | None -> None

                let tryRepairTerminalLetCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryLetSpine cell.nodeId with
                    | Some spine ->
                        let missingBody =
                            spine.bodyNodeIds
                            |> Array.mapi (fun i nodeId -> i, nodeId)
                            |> Array.tryFind (fun (_, nodeId) -> not (EvalReplayValueStore.tryTermReady nodeId))
                        match missingBody with
                        | Some (i, nodeId) ->
                            let shape = if i < spine.bodyShapes.Length then spine.bodyShapes.[i] else CompilerIdentityKernel.WorkShapeIdOps.Known.unknown
                            makeTerminalCompositeReplayLocked cell (EvaluatorLetBody i) EvalTerm shape nodeId (ReplayCellReadyStatus ReplayCellReadyLetBody) ReplayNextScheduleLetBody
                        | None when not (EvalReplayValueStore.tryTermReady spine.successNodeId) ->
                            makeTerminalCompositeReplayLocked cell EvaluatorLetSuccess EvalTerm spine.successShape spine.successNodeId (ReplayCellReadyStatus ReplayCellReadyLetSuccess) ReplayNextScheduleLetSuccess
                        | None -> completeCompositeIfReadyLocked cell
                    | None -> None

                let tryRepairTerminalApplyCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryApplySpine cell.nodeId with
                    | Some spine ->
                        if not (EvalReplayValueStore.tryTermReady spine.headNodeId) then
                            makeTerminalCompositeReplayLocked cell EvaluatorApplyHead EvalTerm spine.headShape spine.headNodeId (ReplayCellReadyStatus ReplayCellReadyApplyHead) ReplayNextScheduleApplyHead
                        else
                            let missingArg =
                                spine.argNodeIds
                                |> Array.mapi (fun i nodeId -> i, nodeId)
                                |> Array.tryFind (fun (_, nodeId) -> not (EvalReplayValueStore.tryTermReady nodeId))
                            match missingArg with
                            | Some (i, nodeId) ->
                                let shape = if i < spine.argShapes.Length then spine.argShapes.[i] else CompilerIdentityKernel.WorkShapeIdOps.Known.unknown
                                makeTerminalCompositeReplayLocked cell (EvaluatorApplyArgument i) EvalTerm shape nodeId (ReplayCellReadyStatus ReplayCellReadyApplyArg) ReplayNextScheduleApplyArg
                            | None -> completeCompositeIfReadyLocked cell
                    | None -> None

                let tryRepairTerminalTypeApplyCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryTypeApplySpine cell.nodeId with
                    | Some spine ->
                        if not (EvalReplayValueStore.tryTermReady spine.funcNodeId) then
                            makeTerminalCompositeReplayLocked cell EvaluatorTypeApplyFunction EvalTerm spine.funcShape spine.funcNodeId (ReplayCellReadyStatus ReplayCellReadyTypeApplyFunction) ReplayNextScheduleTypeApplyFunction
                        else
                            match EvalReplayValueStore.tryType spine.typeNodeId with
                            | None ->
                                makeTerminalCompositeReplayLocked cell EvaluatorTypeApplyArgument EvalTy spine.typeShape spine.typeNodeId (ReplayCellReadyStatus ReplayCellReadyTypeApplyTypeArg) ReplayNextScheduleTypeApplyTypeArg
                            | Some _ ->
                                match EvalReplayValueStore.tryTypeApplyBodyValueAt cell.nodeId with
                                | Some value ->
                                    EvalReplayValueStore.putTermValue cell.nodeId value
                                    match EvalReplayValueStore.tryParentContinuationForChildKind (evaluatorNodeKindForEvalKind cell.kind) cell.nodeId with
                                    | Some cont when cont.parentNodeId <> cell.nodeId ->
                                        let parentCell =
                                            { cell with
                                                kind = evalKindForEvaluatorNodeKind cont.parentKind
                                                shape = cont.parentShape
                                                nodeId = cont.parentNodeId
                                                status = ReplayCellReadyStatus ReplayCellReadyParentContinuation
                                                step = cell.step + 1 }
                                        let repaired =
                                            { frame with
                                                kind = evalKindForEvaluatorNodeKind cont.parentKind
                                                status = FrameContinuationEnvelope
                                                cursor = frame.trace.Length
                                                reason = frameReasonAppend frame.reason ":terminal_type_apply_body_parent_resume"
                                                payload = FrameSemanticCellPayload parentCell }
                                        frontier <- Some repaired
                                        slotSetLocked repaired
                                        replayScheduledKey <- None
                                        replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                                        noteProgressYieldLocked ()
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_type_apply_cycle_body_parent_resumed\",\"event\":%s,\"child\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"role\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"resume_parent_replay_driver\"}" [| box (esc event); box (esc (formatCell cell)); box (esc (EvalReplayValueStore.evaluatorNodeKindText cont.parentKind)); box (esc (EvalReplayValueStore.workShapeIdText cont.parentShape)); box cont.parentNodeId; box (esc (EvalReplayValueStore.evaluatorDependencyRoleText cont.role)); box (pendingCount()) |])
                                        Some repaired
                                    | _ ->
                                        let resolvedStatusId, resolvedNext, resolvedKind = terminalCompositeStatusAndNext cell
                                        let resolvedStatus = frameStatusOfSemanticStatusId resolvedStatusId
                                        let resolvedCell = { cell with status = ReplayCellSemanticStatus resolvedStatusId }
                                        let resolved =
                                            { frame with
                                                kind = cell.kind
                                                status = resolvedStatus
                                                payload = FrameSemanticCellPayload resolvedCell }
                                        frontier <- Some resolved
                                        slotSetLocked resolved
                                        noteProgressYieldLocked ()
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":%s,\"event\":%s,\"parent_node_id\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc (resolvedKind + "_type_apply_body")); box (esc event); box cell.nodeId; box (esc (formatCell resolvedCell)); box (pendingCount()); box (esc (replayCommitNextIdText resolvedNext)) |])
                                        Some resolved
                                | None -> completeCompositeIfReadyLocked cell
                    | None -> None

                let tryRepairTerminalTypeFunCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryTypeFunSpine cell.nodeId with
                    | Some spine ->
                        match EvalReplayValueStore.tryType spine.argNodeId, EvalReplayValueStore.tryType spine.bodyNodeId with
                        | None, _ ->
                            makeTerminalCompositeReplayLocked cell EvaluatorFunctionArgumentType EvalTy spine.argShape spine.argNodeId (ReplayCellReadyStatus ReplayCellReadyTypeFunArg) ReplayNextScheduleTFunChild
                        | _, None ->
                            makeTerminalCompositeReplayLocked cell EvaluatorFunctionResultType EvalTy spine.bodyShape spine.bodyNodeId (ReplayCellReadyStatus ReplayCellReadyTypeFunBody) ReplayNextScheduleTFunChild
                        | Some argTy, Some bodyTy ->
                            EvalReplayValueStore.putTypeValue cell.nodeId (YFun(argTy, bodyTy, spine.funType))
                            completeTypeCompositeIfReadyLocked cell
                    | None -> completeTypeCompositeIfReadyLocked cell

                let tryRepairTerminalTypePairCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryTypePairSpine cell.nodeId with
                    | Some spine ->
                        match EvalReplayValueStore.tryType spine.leftNodeId, EvalReplayValueStore.tryType spine.rightNodeId with
                        | None, _ ->
                            makeTerminalCompositeReplayLocked cell EvaluatorPairLeft EvalTy spine.leftShape spine.leftNodeId (ReplayCellReadyStatus ReplayCellReadyTypePairLeft) ReplayNextScheduleTPairChild
                        | _, None ->
                            makeTerminalCompositeReplayLocked cell EvaluatorPairRight EvalTy spine.rightShape spine.rightNodeId (ReplayCellReadyStatus ReplayCellReadyTypePairRight) ReplayNextScheduleTPairChild
                        | Some leftTy, Some rightTy ->
                            EvalReplayValueStore.putTypeValue cell.nodeId (YPair(leftTy, rightTy))
                            completeTypeCompositeIfReadyLocked cell
                    | None -> completeTypeCompositeIfReadyLocked cell

                let tryRepairTerminalRecordWithCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryRecordWithSpine cell.nodeId with
                    | Some spine ->
                        let missingChild =
                            spine.childNodeIds
                            |> Array.mapi (fun i nodeId -> i, nodeId)
                            |> Array.tryFind (fun (_, nodeId) -> not (EvalReplayValueStore.tryTermReady nodeId))
                        match missingChild with
                        | Some (i, nodeId) ->
                            let shape = if i < spine.childShapes.Length then spine.childShapes.[i] else CompilerIdentityKernel.WorkShapeIdOps.Known.unknown
                            makeTerminalCompositeReplayLocked cell (EvaluatorRecordChild i) EvalTerm shape nodeId (ReplayCellReadyStatus ReplayCellReadyRecordWithChild) ReplayNextScheduleRecordWithChild
                        | None -> completeCompositeIfReadyLocked cell
                    | None -> None

                let tryRepairTerminalCompositeCycleLocked () =
                    match frame.semanticCell with
                    | Some cell when (frameSemanticStatusIs SemanticParentContinuationCycleBlocked frame || frameSemanticStatusIs SemanticParentContinuationCycleDeferred frame)
                                     && replayCellEvalKindId cell = EvalTerm ->
                        match replayCellShapeId cell with
                        | CellShapeELet -> tryRepairTerminalLetCycleLocked cell
                        | CellShapeESeq -> tryRepairTerminalSeqCycleLocked cell
                        | CellShapeEApply -> tryRepairTerminalApplyCycleLocked cell
                        | CellShapeETypeApply -> tryRepairTerminalTypeApplyCycleLocked cell
                        | CellShapeERecordWith -> tryRepairTerminalRecordWithCycleLocked cell
                        | _ -> None
                    | Some cell when (frameSemanticStatusIs SemanticParentContinuationCycleBlocked frame || frameSemanticStatusIs SemanticParentContinuationCycleDeferred frame)
                                     && replayCellEvalKindId cell = EvalTy ->
                        match replayCellShapeId cell with
                        | CellShapeTFun -> tryRepairTerminalTypeFunCycleLocked cell
                        | CellShapeTPair -> tryRepairTerminalTypePairCycleLocked cell
                        | _ -> completeTypeCompositeIfReadyLocked cell
                    | _ -> None

                let switched =
                    lock gate (fun () ->
                        let blockedCycle =
                            (frameSemanticStatusIs SemanticParentContinuationCycleBlocked frame
                             || frameSemanticStatusIs SemanticParentContinuationCycleDeferred frame)
                            && replayQueue.IsEmpty
                            && not (frameReplayCompleteAny frame)
                        if not blockedCycle then None
                        else
                            match tryRepairTerminalCompositeCycleLocked () with
                            | Some repaired -> Some repaired
                            | None ->
                                slotSetLocked frame
                                let candidates =
                                    [ frontierTerm; frontierTy ]
                                    |> List.choose (fun x -> x)
                                    |> List.filter (fun alt ->
                                        not (sameCycle alt frame)
                                        && not (frameSemanticStatusIs SemanticParentContinuationCycleBlocked alt)
                                        && not (frameSemanticStatusIs SemanticParentContinuationCycleDeferred alt)
                                        && not (frameSemanticStatusIs SemanticReplayFingerprintRepeatBlocked alt)
                                        && not (frameSemanticStatusIs SemanticJoinpointTermStepperBlocked alt)
                                        && not (frameSemanticStatusIs SemanticJoinpointValueBlocked alt)
                                        && not (frameSemanticStatusIs SemanticReplayPayloadMissingBlocked alt)
                                        && not (frameSemanticStatusIs SemanticMacroThunkMissingBlocked alt)
                                        && not (frameSemanticStatusIs SemanticTjoinpointStepperBlocked alt)
                                        && not (frameSemanticStatusIs SemanticLiteralOpBodyStepperBlocked alt)
                                        && not (frameSemanticStatusIs SemanticLeafComplete alt))
                                let selected =
                                    match candidates |> List.tryFind (fun alt -> frameSemanticStatusIs SemanticRootComplete alt) with
                                    | Some root -> Some root
                                    | None ->
                                        match candidates |> List.tryFind (fun alt -> frameStatusIs FrameContinuationEnvelope alt || frameStatusIs FrameReadyExplicitLoop alt || frameStatusIs FrameTracingExplicitLoop alt) with
                                        | Some live -> Some live
                                        | None -> candidates |> List.tryHead
                                match selected with
                                | Some alt ->
                                    frontier <- Some alt
                                    replayScheduledKey <- None
                                    replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                                    Some alt
                                | None -> None)
                match switched with
                | Some alt when frameStatusIs FrameContinuationEnvelope alt
                                && replayTerminalReasonIsCycle alt.reason ->
                    Some alt
                | Some alt ->
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_parent_continuation_cycle_yielded\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}" [| box (esc event); box (esc (evalKindToString frame.kind)); box (esc (frameStatusToString frame.status)); box (esc (evalKindToString alt.kind)); box (esc (frameStatusToString alt.status)); box (pendingCount()) |])
                    Some alt
                | None -> None
            with _ -> None

        // MIGRATION: a TV child with no materialized type environment is terminal evidence,
        // but should not monopolize retry_stop while a different kind-local frontier is live.
        // Park it and yield to another non-terminal frontier when one exists.
        let private tryYieldTypeVariableValueMissingBlocked (event: string) (frame: Frame) : Frame option =
            try
                let switched =
                    lock gate (fun () ->
                        let blockedTypeVar =
                            frameSemanticStatusIs SemanticTypeVariableValueMissingBlocked frame
                            && replayQueue.IsEmpty
                            && not (frameReplayCompleteAny frame)
                        if not blockedTypeVar then None
                        else
                            slotSetLocked frame
                            let candidates =
                                [ frontierTerm; frontierTy ]
                                |> List.choose (fun x -> x)
                                |> List.filter (fun alt ->
                                    not (sameCycle alt frame)
                                    && not (frameSemanticStatusIs SemanticTypeVariableValueMissingBlocked alt)
                                    && not (frameSemanticStatusIs SemanticParentContinuationCycleBlocked alt)
                                    && not (frameSemanticStatusIs SemanticReplayFingerprintRepeatBlocked alt)
                                    && not (frameSemanticStatusIs SemanticReplayPayloadMissingBlocked alt)
                                    && not (frameSemanticStatusIs SemanticMacroThunkMissingBlocked alt)
                                    && not (frameSemanticStatusIs SemanticTjoinpointStepperBlocked alt)
                                    && not (frameSemanticStatusIs SemanticLiteralOpBodyStepperBlocked alt)
                                    && not (frameSemanticStatusIs SemanticLeafComplete alt))
                            let selected =
                                match candidates |> List.tryFind (fun alt -> frameSemanticStatusIs SemanticRootComplete alt) with
                                | Some root -> Some root
                                | None ->
                                    match candidates |> List.tryFind (fun alt -> frameStatusIs FrameContinuationEnvelope alt || frameStatusIs FrameReadyExplicitLoop alt || frameStatusIs FrameTracingExplicitLoop alt) with
                                    | Some live -> Some live
                                    | None -> candidates |> List.tryHead
                            match selected with
                            | Some alt ->
                                frontier <- Some alt
                                replayScheduledKey <- None
                                replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                                Some alt
                            | None -> None)
                match switched with
                | Some alt ->
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_variable_value_missing_yielded\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}" [| box (esc event); box (esc (evalKindToString frame.kind)); box (esc (frameStatusToString frame.status)); box (esc (evalKindToString alt.kind)); box (esc (frameStatusToString alt.status)); box (pendingCount()) |])
                    Some alt
                | None -> None
            with _ -> None

        // MIGRATION: a stale-root retarget blocker is terminal evidence for the blocked
        // cell, but it should not monopolize retry_stop while another kind-local frontier
        // is already live.  Park it in the kind slot and yield to a non-terminal alternate
        // frontier when one exists.  This never promotes the stale proof to root-complete.
        let private tryYieldStaleRootRetargetBlocked (event: string) (frame: Frame) : Frame option =
            try
                let switched =
                    lock gate (fun () ->
                        let blockedRetarget =
                            frameSemanticStatusIs SemanticStaleRootRetargetBlocked frame
                            && replayQueue.IsEmpty
                            && not (frameReplayCompleteAny frame)
                        if not blockedRetarget then None
                        else
                            slotSetLocked frame
                            let candidates =
                                [ frontierTerm; frontierTy ]
                                |> List.choose (fun x -> x)
                                |> List.filter (fun alt ->
                                    not (sameCycle alt frame)
                                    && not (frameSemanticStatusIs SemanticStaleRootRetargetBlocked alt)
                                    && not (frameSemanticStatusIs SemanticTypeVariableValueMissingBlocked alt)
                                    && not (frameSemanticStatusIs SemanticParentContinuationCycleBlocked alt)
                                    && not (frameSemanticStatusIs SemanticReplayFingerprintRepeatBlocked alt)
                                    && not (frameSemanticStatusIs SemanticReplayPayloadMissingBlocked alt)
                                    && not (frameSemanticStatusIs SemanticMacroThunkMissingBlocked alt)
                                    && not (frameSemanticStatusIs SemanticTjoinpointStepperBlocked alt)
                                    && not (frameSemanticStatusIs SemanticLiteralOpBodyStepperBlocked alt)
                                    && not (frameSemanticStatusIs SemanticLeafComplete alt))
                            let selected =
                                match candidates |> List.tryFind (fun alt -> frameSemanticStatusIs SemanticRootComplete alt) with
                                | Some root -> Some root
                                | None ->
                                    match candidates |> List.tryFind (fun alt -> frameStatusIs FrameContinuationEnvelope alt || frameStatusIs FrameReadyExplicitLoop alt || frameStatusIs FrameTracingExplicitLoop alt) with
                                    | Some live -> Some live
                                    | None -> candidates |> List.tryHead
                            match selected with
                            | Some alt ->
                                frontier <- Some alt
                                replayScheduledKey <- None
                                replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                                noteProgressYieldLocked ()
                                Some alt
                            | None -> None)
                match switched with
                | Some alt ->
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_stale_root_retarget_yielded\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}" [| box (esc event); box (esc (evalKindToString frame.kind)); box (esc (frameStatusToString frame.status)); box (esc (evalKindToString alt.kind)); box (esc (frameStatusToString alt.status)); box (pendingCount()) |])
                    Some alt
                | None -> None
            with _ -> None

        // MIGRATION: retry_stop can now reach a real semantic leaf after jp_wait_cycle_drain
        // without yet having the parent continuation registered.  That is progress, but not
        // a root proof.  Request one bounded replay retry so the parent-continuation sidecar
        // can be observed on the next pass, rather than aborting immediately as a generic
        // semantic_step_partial.  The caller remains responsible for the normal retry cap.
        let tryRequestLeafParentContinuationRetry (event: string) (attempt: int) (maxAttempts: int) : bool =
            try
                match tryPeek() with
                | Some frame ->
                    let noParentContinuation =
                        match frame.semanticCell with
                        | Some cell -> EvalReplayValueStore.tryParentContinuationForChildKind (evaluatorNodeKindForEvalKind cell.kind) cell.nodeId |> Option.isNone
                        | None -> true
                    let blockedLeaf =
                        frameStatusIs FrameSemanticLeafComplete frame
                        && replayQueue.IsEmpty
                        && noParentContinuation
                        && not (frameReplayCompleteAny frame)
                    if not blockedLeaf then false
                    else
                        let yieldedAlternate =
                            match tryYieldLeafParentContinuationBlocked event frame with
                            | Some _ -> true
                            | None -> false
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_leaf_parent_continuation_retry\",\"event\":%s,\"attempt\":%d,\"next_attempt\":%d,\"max_attempts\":%d,\"frame_kind\":%s,\"status\":%s,\"key\":%s,\"site\":%s,\"cursor\":%d,\"trace_lines\":%d,\"pending\":%d,\"yielded_alternate\":%b,\"single_flight\":1,\"policy\":\"bounded_retry_after_leaf_parent_continuation_missing\",\"next\":\"attempt_build\"}" [| box (esc event); box attempt; box (attempt + 1); box maxAttempts; box (esc (evalKindToString frame.kind)); box (esc (frameStatusToString frame.status)); box (esc (frameKeyText frame)); box (esc (frameSiteText frame)); box frame.cursor; box frame.trace.Length; box (pendingCount()); box yieldedAlternate |])
                        true
                | None -> false
            with _ -> false

        // MIGRATION: a replay fingerprint repeat is useful evidence, but it
        // should not monopolize the canonical retry drain while another frontier is
        // live.  MIGRATION adds two guardrails observed after MIGRATION: progress-bearing
        // fingerprint-yields are counted for a bounded retry trampoline, and when no
        // independent kind-local slot exists, a live same-cycle non-terminal frontier
        // may be selected once instead of aborting immediately on the repeat blocker.
        let private tryYieldReplayFingerprintRepeatBlocked (event: string) (frame: Frame) : Frame option =
            try
                let mutable selectedScope = ReplayFingerprintYieldNoScope
                let switched =
                    lock gate (fun () ->
                        let blockedRepeat =
                            frameSemanticStatusIs SemanticReplayFingerprintRepeatBlocked frame
                            && replayQueue.IsEmpty
                            && not (frameReplayCompleteAny frame)
                        if not blockedRepeat then None
                        else
                            slotSetLocked frame
                            let liveNonRepeat (alt: Frame) =
                                not (frameSemanticStatusIs SemanticReplayFingerprintRepeatBlocked alt)
                                && not (frameSemanticStatusIs SemanticJoinpointTermStepperBlocked alt)
                                && not (frameSemanticStatusIs SemanticJoinpointValueBlocked alt)
                                && not (frameSemanticStatusIs SemanticParentContinuationCycleBlocked alt)
                                && not (frameSemanticStatusIs SemanticTypeVariableValueMissingBlocked alt)
                                && not (frameSemanticStatusIs SemanticStaleRootRetargetBlocked alt)
                                && not (frameSemanticStatusIs SemanticLeafComplete alt)
                            let allCandidates =
                                [ frontierTerm; frontierTy ]
                                |> List.choose (fun x -> x)
                                |> List.filter liveNonRepeat
                            let independent =
                                allCandidates |> List.filter (fun alt -> not (sameCycle alt frame))
                            let sameCycleLive =
                                allCandidates |> List.filter (fun alt -> sameCycle alt frame)
                            let candidates =
                                match independent with
                                | _ :: _ ->
                                    selectedScope <- ReplayFingerprintYieldIndependent
                                    independent
                                | [] ->
                                    selectedScope <- ReplayFingerprintYieldSameCycleLive
                                    sameCycleLive
                            let selected =
                                match candidates |> List.tryFind (fun alt -> frameSemanticStatusIs SemanticRootComplete alt) with
                                | Some root -> Some root
                                | None ->
                                    match candidates |> List.tryFind (fun alt -> frameStatusIs FrameContinuationEnvelope alt || frameStatusIs FrameReadyExplicitLoop alt || frameStatusIs FrameTracingExplicitLoop alt) with
                                    | Some live -> Some live
                                    | None -> candidates |> List.tryHead
                            match selected with
                            | Some alt ->
                                frontier <- Some alt
                                replayScheduledKey <- None
                                replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                                noteProgressYieldLocked ()
                                Some alt
                            | None -> None)
                match switched with
                | Some alt ->
                    let kind =
                        match selectedScope with
                        | ReplayFingerprintYieldSameCycleLive -> "eval_worklist_replay_fingerprint_repeat_same_cycle_yielded"
                        | ReplayFingerprintYieldNoScope
                        | ReplayFingerprintYieldIndependent -> "eval_worklist_replay_fingerprint_repeat_yielded"
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":%s,\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"scope\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}" [| box (esc kind); box (esc event); box (esc (evalKindToString frame.kind)); box (esc (frameStatusToString frame.status)); box (esc (evalKindToString alt.kind)); box (esc (frameStatusToString alt.status)); box (selectedScope |> replayFingerprintYieldScopeText |> esc); box (pendingCount()) |])
                    Some alt
                | None -> None
            with _ -> None

        // MIGRATION: dynamic apply blocked on a DV/DB runtime typecheck is not
        // semantic progress, but it also should not terminate retry_stop while an
        // alternate kind frontier is pending.  Park the blocked dynamic-join frame
        // and yield to another live frontier.  This is scheduler-only: the value
        // store, replay-root witness, and writer gates remain unchanged.
        let private tryYieldDynamicArgApplyBlocked (event: string) (frame: Frame) : Frame option =
            try
                let switched =
                    lock gate (fun () ->
                        let blockedDynamic =
                            frameSemanticStatusIs SemanticDynamicJoinApplyBlocked frame
                            && replayQueue.IsEmpty
                            && not (frameReplayCompleteAny frame)
                        if not blockedDynamic then None
                        else
                            slotSetLocked frame
                            let candidates =
                                [ frontierTerm; frontierTy ]
                                |> List.choose (fun x -> x)
                                |> List.filter (fun alt ->
                                    not (sameCycle alt frame)
                                    && not (frameSemanticStatusIs SemanticReplayFingerprintRepeatBlocked alt)
                                    && not (frameSemanticStatusIs SemanticReplayPayloadMissingBlocked alt)
                                    && not (frameSemanticStatusIs SemanticMacroThunkMissingBlocked alt)
                                    && not (frameSemanticStatusIs SemanticTjoinpointStepperBlocked alt)
                                    && not (frameSemanticStatusIs SemanticLiteralOpBodyStepperBlocked alt)
                                    && not (frameSemanticStatusIs SemanticLeafComplete alt)
                                    && not (frameSemanticStatusIs SemanticDynamicJoinApplyBlocked alt))
                            let selected =
                                match candidates |> List.tryFind (fun alt -> frameSemanticStatusIs SemanticRootComplete alt) with
                                | Some root -> Some root
                                | None ->
                                    match candidates |> List.tryFind (fun alt -> frameStatusIs FrameContinuationEnvelope alt) with
                                    | Some cont -> Some cont
                                    | None ->
                                        match candidates |> List.tryFind (fun alt -> frameStatusIs FrameReadyExplicitLoop alt || frameStatusIs FrameTracingExplicitLoop alt) with
                                        | Some live -> Some live
                                        | None -> candidates |> List.tryHead
                            match selected with
                            | Some alt ->
                                frontier <- Some alt
                                replayScheduledKey <- None
                                replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                                Some alt
                            | None -> None)
                match switched with
                | Some alt ->
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_dynamic_arg_apply_yielded\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}" [| box (esc event); box (esc (evalKindToString frame.kind)); box (esc (frameStatusToString frame.status)); box (esc (evalKindToString alt.kind)); box (esc (frameStatusToString alt.status)); box (pendingCount()) |])
                    Some alt
                | None -> None
            with _ -> None

        // MIGRATION: a semantic_root_complete frontier is a proof, not a scheduler sink.
        // MIGRATION reached multiple source_value_stored events and then stopped on
        // stable_root_complete_livelock while pending alternate work remained.  When
        // the root-complete handoff repeats up to the outer cap, park the completed
        // proof in its kind slot and select a live non-root frontier before aborting.
        // This is scheduler-only: it cannot create BuildOk, cannot mark completion,
        // and cannot unlock writer/shrink gates.
        let tryYieldStableRootCompleteHandoff (event: string) : Frame option =
            try
                let rankStableRootYieldCandidate (alt: Frame) =
                    if frameSemanticStatusIs SemanticDynamicJoinApplyBlocked alt then 0
                    elif frameStatusIs FrameContinuationEnvelope alt then 1
                    elif frameStatusIs FrameReadyExplicitLoop alt || frameStatusIs FrameTracingExplicitLoop alt || frameSemanticStatusIs SemanticStepPartial alt then 2
                    else 3

                let chooseStableRootYieldCandidate candidates =
                    candidates
                    |> List.sortBy rankStableRootYieldCandidate
                    |> List.tryHead

                let crossKindSelectedStepper (frame: Frame) =
                    match frame.semanticCell with
                    | Some cell when cellSemanticStatusIs SemanticSelectedFrontierStepperReady cell ->
                        match replayCellEvalKindId cell, frameEvalKindId frame with
                        | EvalTerm, EvalTy
                        | EvalTy, EvalTerm -> true
                        | _ -> false
                    | _ -> false

                // Selected-frontier promotion happens in the root-complete handoff path,
                // outside the normal bounded trampoline.  A continuation envelope without a
                // queued replay task only burns retry budget.  Enqueue the promoted envelope
                // immediately so the next preserved-progress attempt has a concrete driver.
                let enqueueSelectedFrontierReplayLocked (event: string) (frame: Frame) (route: string) =
                    let payload = adapterPayload frame
                    let key = replayKey frame
                    let driver = replayDriverFor frame
                    replaySeq <- replaySeq + 1L
                    let task =
                        makeReplayTask replaySeq key (driver) payload frame.semanticCell
                            (if Option.isSome frame.semanticCell || Option.isSome frame.semanticPayload then ReplaySemanticPayloadReady else ReplaySemanticPayloadMissing)
                            ReplayTaskScheduledReplay
                    replayScheduledKey <- Some key
                    replayQueue <- [task]
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_selected_frontier_replay_enqueued\",\"event\":%s,\"route\":%s,\"replay_id\":%d,\"driver\":%s,\"frame_kind\":%s,\"frame_status\":%s,\"cursor\":%d,\"trace_lines\":%d,\"queue_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"execute_selected_frontier_replay_driver\"}" [| box (esc event); box (esc route); box task.id; box (esc (replayDriverToString driver)); box (esc (evalKindToString frame.kind)); box (esc (frameStatusToString frame.status)); box frame.cursor; box frame.trace.Length; box (replayQueueDepth()); box (pendingCount()) |])

                let tryPromoteSelectedFrontierStepperLocked (repeated: Frame) (repeatCount: int) (repeatedKey: string) =
                    match repeated.semanticCell with
                    | Some cell when (frameStatusIs FrameCaptured repeated
                                      || frameStatusIs FrameReadyExplicitLoop repeated
                                      || frameStatusIs FrameTracingExplicitLoop repeated
                                      || frameSemanticStatusIs SemanticApplyContinuationExceptionBlocked repeated)
                                     && replayCellEvalKindId cell = EvalTerm
                                     && replayCellShapeId cell = CellShapeESeq
                                     && (cellFrameStatusIs FrameCaptured cell || cellSemanticStatusIs SemanticCellNew cell || cellSemanticStatusIs SemanticStepperReady cell) ->
                        let replayIdentity =
                            SelectedFrontierCapturedCellReplay(
                                ReplayKeyIdOps.create repeatedKey,
                                cell.nodeId,
                                cell.shape,
                                cell.cursor,
                                cell.step)
                        let attempt = noteSelectedFrontierStepperReplayLocked replayIdentity
                        if attempt > selected_frontier_captured_cell_replay_cap then None
                        else
                            let replayCell = { cell with status = ReplayCellReadyStatus ReplayCellReadySelectedFrontierStepper }
                            let promoted =
                                { repeated with
                                    status = FrameContinuationEnvelope
                                    cursor = repeated.trace.Length
                                    reason = frameReasonAppend repeated.reason ":selected_captured_frontier_cell_replay"
                                    payload = FrameSemanticCellPayload replayCell }
                            frontier <- Some promoted
                            slotSetLocked promoted
                            enqueueSelectedFrontierReplayLocked event promoted "captured_cell_replay"
                            noteProgressYieldLocked ()
                            stableRootSelectedKey <- None
                            stableRootSelectedCount <- 0
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_selected_frontier_captured_cell_replay\",\"event\":%s,\"frame_status\":%s,\"cell_kind\":%s,\"cell_shape\":%s,\"cell_status\":%s,\"node_id\":%d,\"site\":%s,\"attempt\":%d,\"cap\":%d,\"repeat_count\":%d,\"repeat_cap\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"run_captured_frontier_typed_stepper\"}" [| box (esc event); box (esc (frameStatusToString repeated.status)); box (esc (evalKindToString cell.kind)); box (esc (replayCellShapeText cell)); box (esc (replayCellStatusText cell.status)); box cell.nodeId; box (esc (replayCellSiteText cell)); box attempt; box selected_frontier_captured_cell_replay_cap; box repeatCount; box stable_root_selected_frontier_repeat_cap; box (pendingCount()) |])
                            Some promoted
                    | Some cell when frameSemanticStatusIs SemanticStepPartial repeated
                                     && replayCellEvalKindId cell = EvalTerm
                                     && (replayCellShapeId cell = CellShapeEApply || replayCellShapeId cell = CellShapeETypeApply || replayCellShapeId cell = CellShapeELet || replayCellShapeId cell = CellShapeESeq) ->
                        let replayIdentity =
                            SelectedFrontierTypedStepperReplay(
                                ReplayKeyIdOps.create repeatedKey,
                                cell.nodeId,
                                cell.shape)
                        let attempt = noteSelectedFrontierStepperReplayLocked replayIdentity
                        if attempt > selected_frontier_stepper_replay_cap then None
                        else
                            let replayCell = { cell with status = ReplayCellReadyStatus ReplayCellReadySelectedFrontierStepper }
                            let promoted =
                                { repeated with
                                    status = FrameContinuationEnvelope
                                    cursor = repeated.trace.Length
                                    reason = frameReasonAppend repeated.reason ":selected_frontier_stepper_replay"
                                    payload = FrameSemanticCellPayload replayCell }
                            frontier <- Some promoted
                            slotSetLocked promoted
                            enqueueSelectedFrontierReplayLocked event promoted "stepper_replay"
                            noteProgressYieldLocked ()
                            stableRootSelectedKey <- None
                            stableRootSelectedCount <- 0
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_selected_frontier_stepper_replay\",\"event\":%s,\"cell_kind\":%s,\"cell_shape\":%s,\"node_id\":%d,\"site\":%s,\"attempt\":%d,\"cap\":%d,\"repeat_count\":%d,\"repeat_cap\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"run_selected_frontier_typed_stepper\"}" [| box (esc event); box (esc (evalKindToString cell.kind)); box (esc (replayCellShapeText cell)); box cell.nodeId; box (esc (replayCellSiteText cell)); box attempt; box selected_frontier_stepper_replay_cap; box repeatCount; box stable_root_selected_frontier_repeat_cap; box (pendingCount()) |])
                            Some promoted
                    | Some cell when frameStatusIs FrameContinuationEnvelope repeated
                                     && replayCellEvalKindId cell = EvalTerm
                                     && cellSemanticStatusIs SemanticSelectedFrontierStepperReady cell
                                     && (replayCellShapeId cell = CellShapeEApply || replayCellShapeId cell = CellShapeETypeApply || replayCellShapeId cell = CellShapeELet || replayCellShapeId cell = CellShapeESeq) ->
                        let replayIdentity =
                            SelectedFrontierTypedStepperRearm(
                                ReplayKeyIdOps.create repeatedKey,
                                cell.nodeId,
                                cell.shape,
                                cell.cursor,
                                cell.step)
                        let attempt = noteSelectedFrontierStepperReplayLocked replayIdentity
                        if attempt > selected_frontier_stepper_rearm_cap then None
                        else
                            let rearmed =
                                { repeated with
                                    status = FrameContinuationEnvelope
                                    cursor = repeated.trace.Length
                                    reason = frameReasonAppend repeated.reason ":selected_frontier_stepper_rearm"
                                    payload = FrameSemanticCellPayload cell }
                            frontier <- Some rearmed
                            slotSetLocked rearmed
                            enqueueSelectedFrontierReplayLocked event rearmed "stepper_rearm"
                            noteProgressYieldLocked ()
                            stableRootSelectedKey <- None
                            stableRootSelectedCount <- 0
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_selected_frontier_stepper_rearm\",\"event\":%s,\"cell_kind\":%s,\"cell_shape\":%s,\"cell_status\":%s,\"node_id\":%d,\"site\":%s,\"attempt\":%d,\"cap\":%d,\"repeat_count\":%d,\"repeat_cap\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"rearm_selected_frontier_typed_stepper\"}" [| box (esc event); box (esc (evalKindToString cell.kind)); box (esc (replayCellShapeText cell)); box (esc (replayCellStatusText cell.status)); box cell.nodeId; box (esc (replayCellSiteText cell)); box attempt; box selected_frontier_stepper_rearm_cap; box repeatCount; box stable_root_selected_frontier_repeat_cap; box (pendingCount()) |])
                            Some rearmed
                    | _ -> None

                let switched =
                    lock gate (fun () ->
                        match frontier with
                        | Some frame when frameReplayCompleteAny frame && replayQueue.IsEmpty ->
                            slotSetLocked frame
                            let blockedRoot =
                                match rootCompleteFingerprintLocked () with
                                | Some identity -> identity
                                | None -> replayFrontierFingerprintIdentity frame
                            let candidates =
                                [ frontierTerm; frontierTy ]
                                |> List.choose (fun x -> x)
                                |> List.filter (fun alt ->
                                    not (sameCycle alt frame)
                                    && not (frameReplayCompleteAny alt)
                                    && not (frameSemanticStatusIs SemanticLeafComplete alt))
                            let preferred = chooseStableRootYieldCandidate candidates
                            let selected, repeatBlocked =
                                match preferred with
                                | Some pref ->
                                    let prefIdentity : StableRootSelectedIdentity = {
                                        blockedRoot = blockedRoot
                                        selected = selectedFrontierFingerprintLocked pref
                                    }
                                    let prefKey = stableRootSelectedIdentityText prefIdentity
                                    if stableRootSelectedKey = Some prefIdentity && stableRootSelectedCount >= stable_root_selected_frontier_repeat_cap then
                                        let fallback =
                                            candidates
                                            |> List.filter (fun alt ->
                                                let altIdentity : StableRootSelectedIdentity = {
                                                    blockedRoot = blockedRoot
                                                    selected = selectedFrontierFingerprintLocked alt
                                                }
                                                stableRootSelectedKey <> Some altIdentity)
                                            |> chooseStableRootYieldCandidate
                                        match fallback with
                                        | Some alt -> Some alt, Some(pref, stableRootSelectedCount, prefKey)
                                        | None ->
                                            // MIGRATION: forcing the same semantic_step_partial frontier after
                                            // the repeat cap only burns the root-complete yield budget.  Runtime
                                            // 581 proved the lone child repeats until trampoline exhaustion; when
                                            // there is no alternate, surface the exact repeat terminal instead.
                                            // MIGRATION: historical runtime exposed a narrower case where the repeated
                                            // selected frontier is already a selected_frontier_stepper_ready term
                                            // cell, but its site is ty@... under a completed ty root.  That is a
                                            // stale cross-kind continuation, not stronger evidence than the root
                                            // proof; demote it and leave the semantic_root_complete frontier intact.
                                            if crossKindSelectedStepper pref then
                                                let demotedRepeatCount = stableRootSelectedCount
                                                let cellSummary =
                                                    match pref.semanticCell with
                                                    | Some cell -> formatCell cell
                                                    | None -> "none"
                                                stableRootSelectedKey <- None
                                                stableRootSelectedCount <- 0
                                                DiagJson.emit (
                                                    FastRuntimeFormat.format """{"kind":"eval_worklist_cross_kind_selected_frontier_demoted","event":%s,"repeated_kind":%s,"repeated_status":%s,"repeat_count":%d,"repeat_cap":%d,"repeated_key":%s,"cell":%s,"pending":%d,"single_flight":1,"next":"preserve_root_complete_build_attempt"}""" [| box (esc event); box (esc (evalKindToString pref.kind)); box (esc (frameStatusToString pref.status)); box demotedRepeatCount; box stable_root_selected_frontier_repeat_cap; box (esc prefKey); box (esc cellSummary); box (pendingCount()) |])
                                                None, None
                                            else
                                                None, Some(pref, stableRootSelectedCount, prefKey)
                                    else
                                        Some pref, None
                                | None -> None, None
                            match selected with
                            | Some alt ->
                                let selectedRepeatCount, selectedKey = noteStableRootSelectedFrontierLocked blockedRoot alt
                                let promotedTerminal =
                                    if frameSemanticStatusIs SemanticApplyContinuationExceptionBlocked alt
                                       || frameSemanticStatusIs SemanticReplayPayloadMissingBlocked alt
                                       || frameSemanticStatusIs SemanticReplayChildScheduleRepeatBlocked alt then
                                        tryPromoteSelectedFrontierStepperLocked alt selectedRepeatCount selectedKey
                                    else None
                                match promotedTerminal with
                                | Some promoted ->
                                    Some (Choice1Of2(frame, promoted, repeatBlocked, selectedRepeatCount, selectedKey))
                                | None ->
                                    frontier <- Some alt
                                    replayScheduledKey <- None
                                    replayTaskSemanticCancelQueuedForReset replayQueue; replayQueue <- []
                                    Some (Choice1Of2(frame, alt, repeatBlocked, selectedRepeatCount, selectedKey))
                            | None ->
                                match repeatBlocked with
                                | Some info -> Some (Choice2Of2 info)
                                | None -> None
                        | _ -> None)
                match switched with
                | Some (Choice1Of2(blocked, alt, repeatBlocked, selectedRepeatCount, selectedKey)) ->
                    match repeatBlocked with
                    | Some(repeated, repeatCount, repeatedKey) ->
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_selected_frontier_repeat_blocked\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"repeated_kind\":%s,\"repeated_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"repeat_count\":%d,\"repeat_cap\":%d,\"repeated_key\":%s,\"fallback_key\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"alternate_frontier_selected\"}" [| box (esc event); box (esc (evalKindToString blocked.kind)); box (esc (frameStatusToString blocked.status)); box (esc (evalKindToString repeated.kind)); box (esc (frameStatusToString repeated.status)); box (esc (evalKindToString alt.kind)); box (esc (frameStatusToString alt.status)); box repeatCount; box stable_root_selected_frontier_repeat_cap; box (esc repeatedKey); box (esc selectedKey); box (pendingCount()) |])
                        if selectedKey = repeatedKey then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_selected_frontier_repeat_forced\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"forced_kind\":%s,\"forced_status\":%s,\"repeat_count\":%d,\"repeat_cap\":%d,\"forced_key\":%s,\"pending\":%d,\"single_flight\":1,\"policy\":\"no_alternate_frontier_force_only_live_child\",\"next\":\"retry_selected_frontier\"}" [| box (esc event); box (esc (evalKindToString blocked.kind)); box (esc (frameStatusToString blocked.status)); box (esc (evalKindToString alt.kind)); box (esc (frameStatusToString alt.status)); box repeatCount; box stable_root_selected_frontier_repeat_cap; box (esc selectedKey); box (pendingCount()) |])
                    | None -> ()
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_stable_root_complete_yielded\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"selected_repeat_count\":%d,\"selected_repeat_cap\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"retry_selected_frontier\"}" [| box (esc event); box (esc (evalKindToString blocked.kind)); box (esc (frameStatusToString blocked.status)); box (esc (evalKindToString alt.kind)); box (esc (frameStatusToString alt.status)); box selectedRepeatCount; box stable_root_selected_frontier_repeat_cap; box (pendingCount()) |])
                    Some alt
                | Some (Choice2Of2(repeated, repeatCount, repeatedKey)) ->
                    let promoted =
                        lock gate (fun () ->
                            tryPromoteSelectedFrontierStepperLocked repeated repeatCount repeatedKey)
                    match promoted with
                    | Some frame ->
                        Some frame
                    | None ->
                        let terminalFrame =
                            { repeated with
                                status = frameStatusOfSemanticStatusId SemanticSelectedFrontierRepeatBlocked
                                reason = frameReasonAppend repeated.reason ":selected_frontier_repeat_terminal" }
                        // A selected-frontier repeat is scheduler evidence. If a stronger
                        // semantic terminal was already pinned during replay, keep that terminal
                        // visible instead of overwriting it with the lower-rank repeat symptom.
                        let visibleFrame, priorRank, repeatRank, demotedBelowPinned, priorSource =
                            lock gate (fun () ->
                                let repeatRank = terminalContractRank terminalFrame.status
                                let liveRank =
                                    match pinnedTerminalContract with
                                    | Some prior -> terminalContractRank prior.status
                                    | None -> 0
                                let durableRank =
                                    match durableTerminalContract with
                                    | Some prior -> terminalContractRank prior.status
                                    | None -> 0
                                let priorSource, priorOpt, priorRank =
                                    if durableRank > liveRank then
                                        "durable_ledger", durableTerminalContract, durableRank
                                    elif liveRank > 0 then
                                        "live_pinned", pinnedTerminalContract, liveRank
                                    else
                                        "none", None, 0
                                match priorOpt with
                                | Some prior when priorRank > repeatRank ->
                                    frontier <- Some prior
                                    slotSetLocked prior
                                    prior, priorRank, repeatRank, true, priorSource
                                | _ ->
                                    frontier <- Some terminalFrame
                                    slotSetLocked terminalFrame
                                    pinTerminalContractLocked event terminalFrame
                                    terminalFrame, priorRank, repeatRank, false, priorSource)
                        if demotedBelowPinned then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_selected_frontier_repeat_demoted_below_stronger_terminal\",\"event\":%s,\"repeat_status\":%s,\"repeat_rank\":%d,\"terminal_status\":%s,\"terminal_rank\":%d,\"terminal_site\":%s,\"terminal_source\":%s,\"repeat_count\":%d,\"repeat_cap\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (esc (frameStatusToString terminalFrame.status)); box repeatRank; box (esc (frameStatusToString visibleFrame.status)); box priorRank; box (esc (frameSiteText visibleFrame)); box (esc priorSource); box repeatCount; box stable_root_selected_frontier_repeat_cap; box (pendingCount()); box (esc (terminalContractNext visibleFrame.status)) |])

                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_selected_frontier_repeat_blocked\",\"event\":%s,\"blocked_kind\":\"unknown\",\"blocked_status\":\"semantic_root_complete\",\"repeated_kind\":%s,\"repeated_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"visible_kind\":%s,\"visible_status\":%s,\"repeat_count\":%d,\"repeat_cap\":%d,\"repeated_key\":%s,\"fallback_key\":\"none\",\"pending\":%d,\"single_flight\":1,\"next\":\"abort_precise_terminal\"}" [| box (esc event); box (esc (evalKindToString repeated.kind)); box (esc (frameStatusToString repeated.status)); box (esc (evalKindToString terminalFrame.kind)); box (esc (frameStatusToString terminalFrame.status)); box (esc (evalKindToString visibleFrame.kind)); box (esc (frameStatusToString visibleFrame.status)); box repeatCount; box stable_root_selected_frontier_repeat_cap; box (esc repeatedKey); box (pendingCount()) |])
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_selected_frontier_repeat_terminal\",\"event\":%s,\"repeated_kind\":%s,\"repeated_status\":%s,\"visible_status\":%s,\"repeat_count\":%d,\"repeat_cap\":%d,\"repeated_key\":%s,\"pending\":%d,\"single_flight\":1,\"policy\":\"stop_forced_same_frontier_after_repeat_cap_preserve_stronger_terminal\",\"next\":%s}" [| box (esc event); box (esc (evalKindToString repeated.kind)); box (esc (frameStatusToString repeated.status)); box (esc (frameStatusToString visibleFrame.status)); box repeatCount; box stable_root_selected_frontier_repeat_cap; box (esc repeatedKey); box (pendingCount()); box (esc (terminalContractNext visibleFrame.status)) |])
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_selected_frontier_repeat_pinned_terminal\",\"event\":%s,\"status\":%s,\"rank\":%d,\"site\":%s,\"key\":%s,\"repeat_count\":%d,\"repeat_cap\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (esc (frameStatusToString visibleFrame.status)); box (terminalContractRank visibleFrame.status); box (esc (frameSiteText visibleFrame)); box (esc (frameKeyText visibleFrame)); box repeatCount; box stable_root_selected_frontier_repeat_cap; box (pendingCount()); box (esc (terminalContractNext visibleFrame.status)) |])
                        Some visibleFrame
                | None -> None
            with _ -> None

        let private isTerminalAdapter (frame: Frame) =
            frameStatusIs FrameContinuationEnvelope frame

        let private emitAdapter (event: string) (frame: Frame) =
            try
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_adapter\",\"event\":%s,\"adapter\":\"trace_continuation\",\"frame_kind\":%s,\"status\":%s,\"cursor\":%d,\"trace_lines\":%d,\"payload\":%s,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (esc (evalKindToString frame.kind)); box (esc (frameStatusToString frame.status)); box frame.cursor; box frame.trace.Length; box (esc (adapterPayload frame)); box (esc (nextFor frame)) |])
            with _ -> ()

        let private scheduleReplay (eventId: ReplayTickEventId) (frame: Frame) =
            let event = replayTickEventToString eventId
            try
                let backfillCellOpt =
                    if Option.isNone frame.semanticCell && Option.isNone frame.semanticPayload then trySemanticCellForFrame frame
                    else None
                let semanticCellOpt =
                    match frame.semanticCell with
                    | Some cell -> Some cell
                    | None -> backfillCellOpt
                let payload = adapterPayload frame
                let semanticPayloadState =
                    match semanticCellOpt, frame.semanticPayload with
                    | Some _, _
                    | _, Some _ -> ReplaySemanticPayloadReady
                    | _ -> ReplaySemanticPayloadMissing
                let key = replayKey frame
                let driver = replayDriverFor frame
                match backfillCellOpt with
                | Some cell ->
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_payload_backfilled_from_semantic_cell_cache\",\"event\":%s,\"frame_kind\":%s,\"frame_site\":%s,\"cell\":%s,\"single_flight\":1,\"next\":\"schedule_replay_with_semantic_payload\"}" [| box (esc event); box (esc (evalKindToString frame.kind)); box (esc (frameSiteText frame)); box (esc (formatCell cell)) |])
                | None -> ()
                let task, duplicate =
                    lock gate (fun () ->
                        let incomingHasSemantic = semanticPayloadState = ReplaySemanticPayloadReady
                        let wasMissingSemantic (t: ReplayTask) =
                            t.status = ReplayTaskDriverBlockedSemanticPayload
                            || replayTaskSemanticPayloadState t = ReplaySemanticPayloadMissing
                        match replayScheduledKey with
                        | Some k when k = key ->
                            match replayQueue with
                            | h :: rest ->
                                // MIGRATION: same-key replay envelopes may first be scheduled from
                                // jp_wait_cycle_drain with semantic_eval_payload_missing, then later
                                // revisit the exact cursor after a same-kind semantic cell attaches.
                                // Do not keep the stale missing-payload task forever: refresh it and
                                // let the driver run again.  This preserves dedupe for identical
                                // empty envelopes while unblocking the real typed continuation.
                                if wasMissingSemantic h && incomingHasSemantic then
                                    let refreshedPayload =
                                        match semanticCellOpt, replayTaskSemanticCell h with
                                        | Some cell, _ -> ReplayTaskSemanticCellPayload cell
                                        | None, Some cell -> ReplayTaskSemanticCellPayload cell
                                        | None, None -> ReplayTaskLegacyTextPayload(payload, ReplaySemanticPayloadReady)
                                    let refreshedLegacyFacts, refreshedLegacyNodeIds =
                                        match refreshedPayload with
                                        | ReplayTaskSemanticCellPayload _ -> replayTaskEmptyLegacyEvidence
                                        | ReplayTaskLegacyTextPayload(text, _) -> replayTaskLegacyEvidenceAtIngress text
                                    let t =
                                        { h with
                                            payload = refreshedPayload
                                            status = ReplayTaskScheduledReplay
                                            legacyFacts = refreshedLegacyFacts
                                            legacyNodeIds = refreshedLegacyNodeIds }
                                    replayQueue <- (t :: rest) |> List.truncate 16
                                    t, false
                                else
                                    h, true
                            | [] ->
                                replaySeq <- replaySeq + 1L
                                let t = makeReplayTask replaySeq key (driver) payload semanticCellOpt semanticPayloadState ReplayTaskScheduledReplay
                                replayQueue <- [t]
                                t, false
                        | _ ->
                            replaySeq <- replaySeq + 1L
                            let t = makeReplayTask replaySeq key (driver) payload semanticCellOpt semanticPayloadState ReplayTaskScheduledReplay
                            replayScheduledKey <- Some key
                            replayQueue <- (t :: replayQueue) |> List.truncate 16
                            t, false)
                // MIGRATION: a duplicate driver_blocked_semantic_payload task that still
                // carries semantic_eval_payload_missing is not progress.  MIGRATION allowed the
                // parent replay to reduce, but the follow-up jp_wait_cycle_drain repeatedly
                // reran an identical missing-payload envelope at sm'_operators.spi:19.  Park the
                // frontier as an explicit payload requirement until a later same-key envelope
                // refreshes the queued task with a real semantic_eval_payload(...).
                let blockedMissingDuplicate =
                    duplicate
                    && replayTaskStatusId task = ReplayTaskDriverBlockedSemanticPayload
                    && replayTaskSemanticPayloadState task = ReplaySemanticPayloadMissing
                let rerunBlockedDuplicate = duplicate && replayTaskStatusId task = ReplayTaskDriverBlockedSemanticPayload && not blockedMissingDuplicate
                let readyDuplicateCandidate =
                    duplicate
                    && (match replayTaskStatusId task with | ReplayTaskDriverReadyReplayCell | ReplayTaskDriverReadySemanticPayload -> true | _ -> false)
                    && frameStatusIs FrameContinuationEnvelope frame
                let readyDuplicateAttempt =
                    if readyDuplicateCandidate then lock gate (fun () -> noteReadyDuplicateReplayRerunLocked key) else 0
                let rerunReadyDuplicate = readyDuplicateCandidate && readyDuplicateAttempt <= 4
                let blockReadyDuplicate = readyDuplicateCandidate && readyDuplicateAttempt > 4
                let duplicateNext =
                    if blockedMissingDuplicate then "blocked_payload_duplicate_suppressed"
                    elif rerunBlockedDuplicate then "rerun_blocked_replay_driver"
                    elif rerunReadyDuplicate then "rerun_ready_duplicate_replay_driver"
                    elif blockReadyDuplicate then "ready_duplicate_replay_cap"
                    else "already_scheduled"
                let scheduledStatusDuText = replayTaskStatusToString (replayTaskStatusId task)
                let scheduledDriverDuText = replayDriverToString (replayTaskDriverId task)
                let scheduledLiveness = captureReplayLiveness()
                let scheduledOwnerDuText = replayHandoffOwnerToString (replayHandoffOwnerForState ReplayHandoffSchedule scheduledLiveness.queueDepth scheduledLiveness.activeDepth 4 (replayTaskStatusId task))
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_schedule\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"driver_du\":%s,\"status\":%s,\"status_du\":%s,\"owner_du\":%s,\"liveness_du\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"duplicate\":%d,\"payload\":%s,\"single_flight\":1,\"next\":%s}" [| box (esc event); box task.id; box (esc (replayDriverToString task.driver)); box (esc scheduledDriverDuText); box (esc (replayTaskStatusToString task.status)); box (esc scheduledStatusDuText); box (esc scheduledOwnerDuText); box (esc (replayObligationLivenessKindText scheduledLiveness.kind)); box scheduledLiveness.queueDepth; box scheduledLiveness.activeDepth; box scheduledLiveness.pending; box (if duplicate then 1 else 0); box (esc (replayTaskPayloadText task)); box (esc (if duplicate then duplicateNext else (replayDriverToString task.driver))) |])
                if blockedMissingDuplicate then
                    let payloadFrameOpt =
                        lock gate (fun () ->
                            match frontier with
                            | Some frame ->
                                let frame' = { frame with status = frameStatusOfSemanticStatusId SemanticReplayPayloadMissingBlocked; reason = frameReasonAppend frame.reason ":missing_semantic_payload_scheduler_terminal" }
                                let payloadRank = terminalContractRank frame'.status
                                let priorRank =
                                    match pinnedTerminalContract with
                                    | Some prior -> terminalContractRank prior.status
                                    | None -> 0
                                pinnedReplayPayloadMissing <- Some frame'
                                pinTerminalContractLocked event frame'
                                // MIGRATION: payload-missing is evidence that the scheduler lacks a
                                // typed cell, not stronger semantic evidence than an already pinned
                                // TV/TJoinPoint/value blocker.  Keep the concrete terminal as the
                                // visible frontier when it has a higher rank.
                                if priorRank > payloadRank then
                                    match pinnedTerminalContract with
                                    | Some prior ->
                                        frontier <- Some prior
                                        slotSetLocked prior
                                    | None -> ()
                                else
                                    frontier <- Some frame'
                                    slotSetLocked frame'
                                Some(frame', priorRank, payloadRank)
                            | None -> None)
                    match payloadFrameOpt with
                    | Some(_, priorRank, payloadRank) when priorRank > payloadRank ->
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_payload_missing_demoted_below_pinned_terminal\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"payload_rank\":%d,\"pinned_rank\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"prefer_concrete_pinned_terminal\"}" [| box (esc event); box task.id; box (esc (replayDriverToString task.driver)); box payloadRank; box priorRank; box (pendingCount()) |])
                    | _ -> ()
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_payload_missing_blocked\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"status\":\"semantic_replay_payload_missing_blocked\",\"queue_depth\":%d,\"payload\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"explicit_eval_worklist_replay_payload_required\"}" [| box (esc event); box task.id; box (esc (replayDriverToString task.driver)); box (replayQueueDepth()); box (esc (replayTaskPayloadText task)); box (pendingCount()) |])
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_payload_missing_pinned\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"status\":\"semantic_replay_payload_missing_blocked\",\"pending\":%d,\"single_flight\":1,\"next\":\"prefer_payload_missing_terminal\"}" [| box (esc event); box task.id; box (esc (replayDriverToString task.driver)); box (pendingCount()) |])
                elif blockReadyDuplicate then
                    lock gate (fun () ->
                        match frontier with
                        | Some frame ->
                            let frame' =
                                { frame with
                                    status = frameStatusOfSemanticStatusId SemanticReplayFingerprintRepeatBlocked
                                    reason = frameReasonAppend frame.reason ":ready_duplicate_replay_cap" }
                            frontier <- Some frame'
                            slotSetLocked frame'
                        | None -> ())
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_ready_duplicate_replay_cap\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"attempt\":%d,\"cap\":4,\"status\":\"semantic_replay_fingerprint_repeat_blocked\",\"queue_depth\":%d,\"payload\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"explicit_eval_worklist_replay_fingerprint_repeat_required\"}" [| box (esc event); box task.id; box (esc (replayDriverToString task.driver)); box readyDuplicateAttempt; box (replayQueueDepth()); box (esc (replayTaskPayloadText task)); box (pendingCount()) |])
                elif (not duplicate) || rerunBlockedDuplicate || rerunReadyDuplicate then
                    if rerunReadyDuplicate then
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_ready_duplicate_replay_driver_rerun\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"attempt\":%d,\"cap\":4,\"queue_depth\":%d,\"payload\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box task.id; box (esc (replayDriverToString task.driver)); box readyDuplicateAttempt; box (replayQueueDepth()); box (esc (replayTaskPayloadText task)); box (pendingCount()); box (esc (replayDriverToString task.driver)) |])
                    runReplayDriver eventId
            with _ -> ()

        let private beginRun (eventId: ReplayTickEventId) =
            let event = replayTickEventToString eventId
            let tickEventId = eventId
            let mutable acquired = false
            let mutable waits = 0
            acquired <-
                lock gate (fun () ->
                    if activeRun then false
                    else activeRun <- true; true)
            if not acquired then
                waits <- 1
                try
                    lock gate (fun () -> drainParentCacheHandoffsLocked event 8) |> ignore
                    let cycleBreakInjected =
                        tryForceDeferredTypeVarCycleBreakId event (CompilerKernelV2.OperationalReasonIdOps.create "single_flight_busy_cross_kind_cycle_break")
                    if cycleBreakInjected || replayQueueDepth() > 0 || EvalReplayValueStore.hasDeferredReplayCell() || EvalReplayValueStore.parentCacheHandoffQueueDepth() > 0 then
                        replayDriverCooperativeTickFromGlobalFuseId tickEventId ReplayTickReasonSingleFlightBusyGraphMutationTick |> ignore
                with _ -> ()
                acquired <-
                    lock gate (fun () ->
                        if activeRun then false
                        else activeRun <- true; true)
            if waits > 0 then
                try
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"%s\",\"event\":%s,\"waits\":%d,\"wait_ms\":0,\"parent_cache_handoffs\":%d,\"single_flight\":1,\"next\":\"%s\"}" [| box (if acquired then "eval_worklist_single_flight_reacquired_after_graph_tick" else "eval_worklist_single_flight_busy_no_sync_wait"); box (esc event); box waits; box (EvalReplayValueStore.parentCacheHandoffQueueDepth()); box (if acquired then "bounded_trampoline" else "return_busy_frontier") |])
                with _ -> ()
            acquired

        let private endRun () =
            lock gate (fun () -> activeRun <- false)

        let private stepOnce (eventId: ReplayTickEventId) (step: int) (limit: int) : Frame option =
            let event = replayTickEventToString eventId
            lock gate (fun () ->
                match frontier with
                | None -> None
                | Some f ->
                    let loc = traceAt f f.cursor
                    let capturedLeafCell =
                        frameStatusIs FrameSemanticLeafComplete f
                        && (match f.semanticCell with
                            | Some cell -> cellFrameStatusIs FrameCaptured cell || cellSemanticStatusIs SemanticCellNew cell
                            | None -> false)
                    let lateCapturedLeafCell =
                        capturedLeafCell
                        && f.cursor >= f.trace.Length
                    let orphanCapturedLeafCell =
                        event = "retry_stop_drain"
                        && capturedLeafCell
                        && f.cursor < f.trace.Length
                        && replayQueueDepth() = 0
                    let lateCapturedLeafNextId = replayCommitNextOther "replay_late_captured_leaf_cell"
                    let orphanCapturedLeafNextId = replayCommitNextOther "replay_orphan_captured_leaf_cell"
                    let status', cursor', nextId =
                        if frameSemanticStatusIs SemanticReplayDriverExceptionBlocked f then
                            f.status, f.cursor, ReplayNextSemanticStatus SemanticReplayDriverExceptionBlocked
                        elif frameSemanticStatusIs SemanticReplayFingerprintRepeatBlocked f then
                            f.status, f.cursor, ReplayNextReplayFingerprintRepeatDirectRequired
                        elif frameSemanticStatusIs SemanticJoinpointTermStepperBlocked f then
                            f.status, f.cursor, ReplayNextJoinpointTermStepperDirectRequired
                        elif frameSemanticStatusIs SemanticJoinpointValueBlocked f then
                            f.status, f.cursor, ReplayNextSemanticStatus SemanticJoinpointValueBlocked
                        elif lateCapturedLeafCell then
                            FrameContinuationEnvelope, f.cursor, lateCapturedLeafNextId
                        elif orphanCapturedLeafCell then
                            FrameContinuationEnvelope, f.cursor, orphanCapturedLeafNextId
                        elif isSemanticTerminalFrame f then
                            // MIGRATION: never rebuild a replay envelope from a semantic terminal state.
                            // Root completion must survive retry_stop_drain so BuildFile can retry safely.
                            f.status, f.cursor, semanticTerminalNextForFrame f
                        elif frameStatusIs FrameContinuationEnvelope f then
                            FrameContinuationEnvelope, f.cursor, replayCommitNextOther "schedule_term_ty_replay"
                        elif f.cursor < f.trace.Length then
                            FrameTracingExplicitLoop, f.cursor + 1, replayCommitNextOther "advance_trace_cursor"
                        else
                            // MIGRATION: terminal replay envelope + driver scheduling. Do not advance forever after the trace is exhausted;
                            // materialize a deterministic continuation payload with replay anchors instead of a bare adapter gate marker.
                            FrameContinuationEnvelope, f.cursor, replayCommitNextOther "build_replay_continuation_envelope"
                    let nextText = replayCommitNextIdText nextId
                    let f' = { f with status = status'; cursor = cursor' }
                    frontier <- Some f'
                    emit (event + ":step") f'
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_step\",\"event\":%s,\"step\":%d,\"budget\":%d,\"frame_kind\":%s,\"status\":%s,\"cursor\":%d,\"trace_lines\":%d,\"trace_loc\":%s,\"single_flight\":1,\"next\":%s}" [| box (esc event); box step; box limit; box (esc (evalKindToString f'.kind)); box (esc (frameStatusToString f'.status)); box f'.cursor; box f'.trace.Length; box (esc loc); box (esc nextText) |])
                    if nextId = lateCapturedLeafNextId || nextId = orphanCapturedLeafNextId then
                        let cellText =
                            match f.semanticCell with
                            | Some cell -> formatCell cell
                            | None -> "none"
                        let marker =
                            if nextId = orphanCapturedLeafNextId
                            then "eval_worklist_orphan_captured_leaf_cell_replayed"
                            else "eval_worklist_late_captured_leaf_cell_replayed"
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":%s,\"event\":%s,\"frame_kind\":%s,\"frame_status\":%s,\"cursor\":%d,\"trace_lines\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"schedule_term_ty_replay\"}" [| box (esc marker); box (esc event); box (esc (evalKindToString f.kind)); box (esc (frameStatusToString f.status)); box f.cursor; box f.trace.Length; box (esc cellText); box (pendingCount()) |])
                    if isTerminalAdapter f' then
                        emitAdapter event f'
                        scheduleReplay eventId f'
                    Some f')

        let runBounded (eventId: ReplayTickEventId) (budget: int) : Frame option =
            try
                let event = replayTickEventToString eventId
                let limit = if budget <= 0 then 1 else min budget 256
                if beginRun eventId then
                    try
                        let mutable steps = 0
                        let mutable last : Frame option = tryPeek()
                        let mutable blocked = false
                        while steps < limit && not blocked do
                            match stepOnce eventId steps limit with
                            | Some f ->
                                last <- Some f
                                steps <- steps + 1
                                blocked <- isTerminalAdapter f || isSemanticTerminalFrame f || frameSemanticStatusIs SemanticReplayFingerprintRepeatBlocked f || frameSemanticStatusIs SemanticJoinpointTermStepperBlocked f || frameSemanticStatusIs SemanticJoinpointValueBlocked f || frameSemanticStatusIs SemanticReplayDriverExceptionBlocked f || frameSemanticStatusIs SemanticReplayPayloadMissingBlocked f || frameSemanticStatusIs SemanticPayloadRequired f
                            | None ->
                                blocked <- true
                        let finalCursor =
                            match last with
                            | Some f -> f.cursor
                            | None -> -1
                        let finalStatus =
                            match last with
                            | Some f -> frameStatusToString f.status
                            | None -> "empty"
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_run\",\"event\":%s,\"steps\":%d,\"budget\":%d,\"pending\":%d,\"single_flight\":1,\"skipped\":0,\"final_status\":%s,\"cursor\":%d}" [| box (esc event); box steps; box limit; box (pendingCount()); box (esc finalStatus); box finalCursor |])
                        last
                    finally
                        endRun ()
                else
                    let frame = tryPeek()
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_run\",\"event\":%s,\"steps\":0,\"budget\":%d,\"pending\":%d,\"single_flight\":1,\"skipped\":1,\"final_status\":%s,\"cursor\":%d}" [| box (esc event); box limit; box (pendingCount()); box (esc (match frame with Some f -> frameStatusToString f.status | None -> "empty")); box (match frame with Some f -> f.cursor | None -> -1) |])
                    frame
            with _ -> None

        // MIGRATION: retry_stop is the supervisor's last synchronous chance to
        // finish a captured explicit worklist frontier.  MIGRATION proved that
        // ty replay could be half-drained (cursor=16/32) while another Hopac
        // worker still held the single-flight run token; retry_stop then
        // reported driver_state=none and aborted before the typed cell could
        // reach the replay driver.  Wait briefly for the active token, then run
        // a larger bounded drain.  This only advances trace/replay state; it
        // does not mark semantic_root_complete unless the typed stepper itself
        // proves it.
        let private drainAfterActiveRun (eventId: ReplayTickEventId) (budget: int) : Frame option =
            let event = replayTickEventToString eventId
            let tickEventId = eventId
            let limit = if budget <= 0 then 256 else min 768 (max 256 budget)
            // MIGRATION: the repeat-yield path can expose a two-kind dynamic-arg handoff
            // (term EApply blocked while a ty/TFun frontier resolves).  Keep the bound small,
            // but allow enough passes to alternate once after the first explicit dynamic block.
            let baseMaxPasses = 32
            // MIGRATION: retry_stop_drain may still be making real queued-replay
            // progress after twelve passes (MIGRATION ended with replay_queue=1 and
            // a term_replay_driver still advancing the dynamic-record bridge).  Extend
            // only this terminal drain, and keep the bound finite/fail-closed.
            let maxPasses =
                // MIGRATION: MIGRATION still made visible forward progress at pass 63
                // (same live queue, higher replay id, higher EApply step).  Keep the
                // extension terminal-only and finite, but allow enough turns for this
                // dynamic-record bridge to either discharge or reveal the next blocker.
                if event = "retry_stop_drain" then 384
                else baseMaxPasses
            let mutable waits = 0
            if lock gate (fun () -> activeRun) then
                waits <- 1
                try
                    replayDriverCooperativeTickFromGlobalFuseId tickEventId ReplayTickReasonDrainAfterActiveRunNoSyncWait |> ignore
                with _ -> ()
            let before = tryPeek()
            let mutable after = before
            let mutable pass = 0
            let mutable keepGoing = true
            while keepGoing && pass < maxPasses do
                if lock gate (fun () -> activeRun) then
                    keepGoing <- false
                else
                    if pass > 0 then
                        let status, cursor, next =
                            match after with
                            | Some frame -> frameStatusToString frame.status, frame.cursor, nextFor frame
                            | None -> "missing_before_retry_drain_continue", -1, "retry_stop_raise"
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_retry_drain_continue\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"replayCompleteNow\":%b,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box pass; box (esc status); box cursor; box (hasReplayComplete()); box (pendingCount()); box (esc next) |])
                    if event = "retry_stop_drain" && pass >= baseMaxPasses && replayQueueDepth() > 0 then
                        let status, cursor, next =
                            match after with
                            | Some frame -> frameStatusToString frame.status, frame.cursor, nextFor frame
                            | None -> "missing_before_retry_drain_live_queue_extend", -1, "run_replay_driver"
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_retry_drain_live_queue_extend\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"queue_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box pass; box (esc status); box cursor; box (replayQueueDepth()); box (pendingCount()); box (esc next) |])
                    let drained = runBounded eventId limit
                    // MIGRATION: runBounded returns the last pre-driver frame when a synchronous
                    // replay driver commits semantic_root_complete from scheduleReplay.  Re-peek
                    // after the drain so callers do not see stale continuation_envelope.
                    let canonical0 =
                        match tryPeek() with
                        | Some frame when frameSemanticStatusIs SemanticParentContinuationCycleBlocked frame -> Some frame
                        | Some frame when hasReplayComplete() -> Some frame
                        | _ -> drained
                    let canonicalFingerprintQueued =
                        match canonical0 with
                        | Some frame when event = "retry_stop_drain" && (frameSemanticStatusIs SemanticReplayFingerprintRepeatBlocked frame || frameSemanticStatusIs SemanticJoinpointTermStepperBlocked frame) && replayQueueDepth() > 0 ->
                            let qd0 = replayQueueDepth()
                            let cellText =
                                match frame.semanticCell with
                                | Some cell -> formatCell cell
                                | None -> "none"
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_fingerprint_live_queue_drain\",\"event\":%s,\"status\":%s,\"cursor\":%d,\"queue_depth_before\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"run_replay_driver\"}" [| box (esc event); box (esc (frameStatusToString frame.status)); box frame.cursor; box qd0; box (esc cellText); box (pendingCount()) |])
                            runReplayDriver tickEventId
                            let qd1 = replayQueueDepth()
                            let afterDriver =
                                match tryPeek() with
                                | Some frame' -> Some frame'
                                | None -> canonical0
                            let statusAfter, cursorAfter =
                                match afterDriver with
                                | Some frame' -> frameStatusToString frame'.status, frame'.cursor
                                | None -> "missing_after_fingerprint_live_queue_drain", -1
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_fingerprint_live_queue_drain_result\",\"event\":%s,\"status\":%s,\"cursor\":%d,\"queue_depth_after\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (esc statusAfter); box cursorAfter; box qd1; box (pendingCount()); box (esc (if qd1 > 0 then "continue_retry_drain" else "retry_drain_repeek")) |])
                            afterDriver
                        | _ -> canonical0
                    let canonicalQueued =
                        match canonicalFingerprintQueued with
                        | Some frame when frameStatusIs FrameSemanticLeafComplete frame && replayQueueDepth() > 0 ->
                            let qd0 = replayQueueDepth()
                            let cellText =
                                match frame.semanticCell with
                                | Some cell -> formatCell cell
                                | None -> "none"
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_leaf_complete_queued_replay_drain\",\"event\":%s,\"status\":%s,\"cursor\":%d,\"queue_depth_before\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"run_replay_driver\"}" [| box (esc event); box (esc (frameStatusToString frame.status)); box frame.cursor; box qd0; box (esc cellText); box (pendingCount()) |])
                            runReplayDriver tickEventId
                            let qd1 = replayQueueDepth()
                            let afterDriver =
                                match tryPeek() with
                                | Some frame' -> Some frame'
                                | None -> canonicalFingerprintQueued
                            let statusAfter, cursorAfter =
                                match afterDriver with
                                | Some frame' -> frameStatusToString frame'.status, frame'.cursor
                                | None -> "missing_after_leaf_queued_replay_drain", -1
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_leaf_complete_queued_replay_drain_result\",\"event\":%s,\"status\":%s,\"cursor\":%d,\"queue_depth_after\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (esc statusAfter); box cursorAfter; box qd1; box (pendingCount()); box (esc (if qd1 > 0 then "continue_retry_drain" else "retry_drain_repeek")) |])
                            afterDriver
                        | _ -> canonicalFingerprintQueued
                    let canonical =
                        match canonicalQueued with
                        | Some frame ->
                            match tryYieldParentContinuationCycleBlocked event frame with
                            | Some selected -> Some selected
                            | None ->
                                match tryYieldTypeVariableValueMissingBlocked event frame with
                                | Some selected -> Some selected
                                | None ->
                                    match tryYieldStaleRootRetargetBlocked event frame with
                                    | Some selected -> Some selected
                                    | None ->
                                        match tryYieldLeafParentContinuationBlocked event frame with
                                        | Some selected -> Some selected
                                        | None ->
                                            match tryYieldReplayFingerprintRepeatBlocked event frame with
                                            | Some selected -> Some selected
                                            | None ->
                                                match tryYieldDynamicArgApplyBlocked event frame with
                                                | Some selected -> Some selected
                                                | None -> canonicalQueued
                        | None -> canonicalQueued
                    let canonical =
                        match canonical with
                        | Some frame -> preferPinnedTerminalForRetryDrain event frame
                        | None -> None
                    match canonical with
                    | Some frame ->
                        after <- Some frame
                        pass <- pass + 1
                        pinTerminalContract event frame
                        if (event = "retry_stop_drain" || event = "jp_wait_cycle_drain") && (frameSemanticStatusIs SemanticReplayFingerprintRepeatBlocked frame || frameSemanticStatusIs SemanticJoinpointTermStepperBlocked frame) then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_replay_fingerprint_repeat_drain_stopped\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"queue_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box pass; box (esc (frameStatusToString frame.status)); box frame.cursor; box (replayQueueDepth()); box (pendingCount()); box (esc (nextFor frame)) |])
                            keepGoing <- false
                        elif event = "retry_stop_drain" && frameSemanticStatusIs SemanticLetSuccessApplyExceptionBlocked frame && replayQueueDepth() = 0 then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_let_success_apply_exception_drain_stopped\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box pass; box (esc (frameStatusToString frame.status)); box frame.cursor; box (pendingCount()); box (esc (nextFor frame)) |])
                            keepGoing <- false
                        elif isTerminalContractStatusId (frameSemanticStatusId frame) then
                            let parentDeferredClosed =
                                (frameSemanticStatusIs SemanticParentContinuationCycleDeferred frame)
                                && DiagJson.nativePromiseFailureClosedNow()
                            if parentDeferredClosed then
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_parent_continuation_deferred_native_promise_failure_closed\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"rank\":%d,\"pending\":%d,\"native_promise_failure_latched\":true,\"native_promise_failure_latched_age_ms\":%d,\"terminal_closure_id\":\"parent_continuation_deferred_native_promise_failure_closed\",\"proof_tuple_id\":\"pt:parent_continuation_deferred_native_promise_failure_closed\",\"source_row_ref\":\"eval_worklist_parent_continuation_deferred_native_promise_failure_closed\",\"owner_release_du\":\"owner_released_by_native_promise_failure_latch\",\"terminal_clear_du\":\"pinned_and_durable_terminal_contracts_cleared\",\"state_transition_du\":\"ParentContinuationCycleDeferred->NativePromiseFailureClosed->OwnerReleased->Cleared\",\"before_state_du\":\"ParentContinuationCycleDeferred(live_or_pinned)\",\"after_state_du\":\"NativePromiseFailureClosed(owner_released,terminal_cleared)\",\"terminal_latch_state_du\":\"terminal_closed_after_native_promise_failure\",\"consumer_execution_result_du\":\"PromiseOutcome.NoFurther(parent_continuation_cycle_deferred)\",\"root_promise_status\":\"RootPromiseNoFurther(parent_continuation_cycle_deferred)\",\"root_complete_await_contract_du\":\"RootCompleteAwaitNoFurtherClosed(parent_continuation_cycle_deferred)\",\"root_complete_exit_policy_du\":\"fail_closed_no_further_delta_exit_1(parent_continuation_cycle_deferred)\",\"native_job_graph\":\"RootComplete.await(parent_continuation_cycle_deferred)\\n  Collapse(Error(NoFurtherDeltaPossible(parent_continuation_cycle_deferred)))\\n    CLI.emit_semantic_error_then_exit_1(parent_continuation_cycle_deferred)\",\"semantic_diagnosis\":\"SemanticDiagnosis(NoFurtherDeltaPossible|span=source_unknown|message=parent_continuation_cycle_deferred)\",\"single_flight\":1,\"next\":\"close_terminal_without_ejp0011\"}" [| box (esc event); box pass; box (esc (frameStatusToString frame.status)); box frame.cursor; box (terminalContractRank frame.status); box (pendingCount()); box (DiagJson.nativePromiseFailureClosedAgeNowMs()) |])
                                pinnedTerminalContract <- None
                                durableTerminalContract <- None
                                keepGoing <- false
                            else
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_contract_drain_stopped\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"rank\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box pass; box (esc (frameStatusToString frame.status)); box frame.cursor; box (terminalContractRank frame.status); box (pendingCount()); box (esc (nextFor frame)) |])
                                keepGoing <- false
                        elif event = "retry_stop_drain" && frameSemanticStatusIs SemanticReplayDriverExceptionBlocked frame && replayQueueDepth() = 0 then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_replay_exception_drain_stopped\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box pass; box (esc (frameStatusToString frame.status)); box frame.cursor; box (pendingCount()); box (esc (nextFor frame)) |])
                            keepGoing <- false
                        elif event = "retry_stop_drain" && pass >= baseMaxPasses && frameSemanticStatusIs SemanticRootComplete frame && pendingCount() > 0 && replayQueueDepth() = 0 && (hasProgressYield() || replayDriverActiveDepthValue() > 0) then
                            // MIGRATION: pending-jobs terminals are only hard terminals when
                            // the typed liveness seam says no cooperative replay is still in
                            // flight. Historical runtime showed this terminal could pin while a
                            // progress-yield retry and deferred parent replay were still
                            // observable immediately afterwards.
                            after <- Some frame
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_root_complete_pending_jobs_progress_yield_allowed\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"progress_yield_pending\":%b,\"policy\":\"defer_pending_jobs_terminal_while_typed_replay_liveness_is_present\",\"single_flight\":1,\"next\":\"retry_stop_progress_yield\"}" [| box (esc event); box pass; box (esc (frameStatusToString frame.status)); box frame.cursor; box (pendingCount()); box (replayQueueDepth()); box (replayDriverActiveDepthValue()); box (hasProgressYield()) |])
                            keepGoing <- false
                        elif event = "retry_stop_drain" && pass >= baseMaxPasses && frameSemanticStatusIs SemanticRootComplete frame && pendingCount() > 0 && replayQueueDepth() = 0 then
                            // MIGRATION: MIGRATION proved the ty-reentry preflight can drain and return
                            // concrete typed values, but retry_stop_drain could still stop on a
                            // semantic_root_complete frontier while JP bookkeeping reported outstanding
                            // bodies and no replay queue. Make that state an explicit terminal contract
                            // instead of falling back to an open-ended wait/manual interrupt. This does
                            // not close the writer barrier, does not mark BuildFile.replay_root_complete,
                            // and does not synthesize missing JP bodies.
                            let blockedCellOpt =
                                match frame.semanticCell with
                                | Some cell -> Some { cell with status = ReplayCellSemanticStatus SemanticRootCompletePendingJobsBlocked }
                                | None -> None
                            let blockedPayload =
                                match blockedCellOpt with
                                | Some cell -> FrameSemanticCellPayload cell
                                | None -> frame.payload
                            let blockedFrame =
                                { frame with
                                    status = frameStatusOfSemanticStatusId SemanticRootCompletePendingJobsBlocked
                                    reason = frameReasonOfString "retry_stop_root_complete_pending_jobs_no_queue"
                                    payload = blockedPayload }
                            after <- Some blockedFrame
                            pinTerminalContract event blockedFrame
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_retry_stop_root_complete_pending_jobs_terminal_pinned\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"pending\":%d,\"rank\":%d,\"queue_depth\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box pass; box (esc (frameStatusToString blockedFrame.status)); box blockedFrame.cursor; box (pendingCount()); box (terminalContractRank blockedFrame.status); box (replayQueueDepth()); box (esc (terminalContractNext blockedFrame.status)) |])
                            keepGoing <- false
                        elif event = "retry_stop_drain" && pass >= baseMaxPasses && frameStatusIs FrameSemanticLeafComplete frame && replayQueueDepth() = 0 then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_leaf_no_queue_drain_stopped\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box pass; box (esc (frameStatusToString frame.status)); box frame.cursor; box (pendingCount()); box (esc (nextFor frame)) |])
                            keepGoing <- false
                    | None ->
                        keepGoing <- false
                        pass <- pass + 1
            match after with
            | Some _ -> after
            | None -> before

        let drainRetryStop (budget: int) : Frame option =
            drainAfterActiveRun ReplayTickEventRetryStopDrain budget

        // MIGRATION: forced sequential jp_wait can observe a term-cycle fuse before
        // EJP0014.  MIGRATION proved this path may already have a live frontier at
        // cursor=8/32, but the small jp_wait slice only advanced to cursor=24 and
        // left retry_stop to finish.  Drain the same frontier here, while preserving
        // the invariant that only typed replay may set semantic_root_complete.
        let drainJpCyclePreflight (budget: int) : Frame option =
            try
                let before = tryPeek()
                let after = drainAfterActiveRun ReplayTickEventJpWaitCycleDrain budget
                let status, cursor, complete, next =
                    match after with
                    | Some frame -> frameStatusToString frame.status, frame.cursor, hasReplayComplete(), nextFor frame
                    | None -> "missing_after_cycle_drain", -1, hasReplayComplete(), "jp_wait_cycle_raise"
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_jp_cycle_preflight\",\"event\":\"jp_wait_observed_sequential_replay_repeat_guard\",\"status\":%s,\"cursor\":%d,\"replayCompleteNow\":%b,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc status); box cursor; box complete; box (pendingCount()); box (esc next) |])
                match after with
                | Some _ -> after
                | None -> before
            with _ -> None

        // MIGRATION: EJP0014 jp_wait stalls are liveness frontiers too.  If a
        // semantic worklist frame is already present, or a cycle fuse can be
        // captured, spend a bounded synchronous slice draining it before the
        // retry path invalidates the generation.  This preserves MIGRATION's
        // write-gate strictness: only typed replay can set semantic_root_complete.
        let drainJpStallPreflight (event: string) (budget: int) : Frame option =
            try
                let before =
                    match tryPeek() with
                    | Some frame -> Some frame
                    | None -> ensureCapturedForKindId ReplayFrontierUnknown (CompilerKernelV2.OperationalReasonIdOps.create "jp_wait_stall_preflight")
                match before with
                | Some _ ->
                    promoteHead event |> ignore
                    let after = drainRetryStop budget
                    let status, cursor, complete, next =
                        match after with
                        | Some frame -> frameStatusToString frame.status, frame.cursor, hasReplayComplete(), nextFor frame
                        | None -> "missing_after_drain", -1, hasReplayComplete(), "abort_without_write"
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_jp_stall_preflight\",\"event\":%s,\"status\":%s,\"cursor\":%d,\"replayCompleteNow\":%b,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (esc status); box cursor; box complete; box (pendingCount()); box (esc next) |])
                    after
                | None ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_jp_stall_preflight\",\"event\":%s,\"status\":\"missing_frontier\",\"cursor\":-1,\"replayCompleteNow\":false,\"pending\":0,\"single_flight\":1,\"next\":\"jp_wait_retry_diag\"}"
                            (esc event))
                    None
            with _ -> None

        let ensureCapturedAndRunId (reasonId: CompilerKernelV2.OperationalReasonId) (eventId: ReplayTickEventId) (budget: int) : Frame option =
            let event = replayTickEventToString eventId
            let requestedKindId = replayFrontierKindOfTickEvent eventId
            match ensureCapturedForKindId requestedKindId reasonId with
            | Some _ ->
                promoteHead event |> ignore
                runBounded eventId budget
            | None -> None

        type ReplayFrameCompletenessId =
            | ReplayFrameComplete
            | ReplayFrameLeafCompleteParentContinuationMissing
            | ReplayFrameLeafParentContinuationMissingBlocked
            | ReplayFrameSelectedFrontierRepeatBlocked
            | ReplayFrameReplayDriverExceptionBlocked
            | ReplayFrameReplayPayloadMissingBlocked
            | ReplayFrameJoinpointValueBlocked
            | ReplayFrameReplayFingerprintRepeatBlocked
            | ReplayFrameIfUnknownReturnConditionBlocked
            | ReplayFrameIfSymbolicConditionBlocked
            | ReplayFrameJoinpointTermStepperBlocked
            | ReplayFrameMacroThunkMissingBlocked
            | ReplayFrameTypeJoinpointStepperBlocked
            | ReplayFrameLiteralOpBodyStepperBlocked
            | ReplayFrameDynamicJoinApplyBlocked
            | ReplayFrameNominalConstructorStepperBlocked
            | ReplayFrameSeqTypeErrorBlocked
            | ReplayFrameParentContinuationCycleBlocked
            | ReplayFrameParentContinuationCycleDeferred
            | ReplayFrameGlobalFuseParentContinuationCycleBlocked
            | ReplayFrameParentReplayStatusPreservedRepeatBlocked
            | ReplayFrameReplayObligationDeferred
            | ReplayFrameTypeVariableValueMissingBlocked
            | ReplayFrameStaleRootRetargetBlocked
            | ReplayFrameLetSuccessApplyExceptionBlocked
            | ReplayFrameLetSuccessAllReadyApplyBlocked
            | ReplayFrameLetSuccessApplyContinuationBlocked
            | ReplayFrameTypeApplyForallBodyStepperBlocked
            | ReplayFrameApplyContinuationExceptionBlocked
            | ReplayFrameDeferredFunctionReplayExceptionBlocked
            | ReplayFramePartialOneStepOnly
            | ReplayFrameNotComplete

        let private replayFrameCompletenessText = function
            | ReplayFrameComplete -> "complete"
            | ReplayFrameLeafCompleteParentContinuationMissing -> "leaf_complete_parent_continuation_missing"
            | ReplayFrameLeafParentContinuationMissingBlocked -> "leaf_parent_continuation_missing_blocked"
            | ReplayFrameSelectedFrontierRepeatBlocked -> "selected_frontier_repeat_blocked"
            | ReplayFrameReplayDriverExceptionBlocked -> "replay_driver_exception_blocked"
            | ReplayFrameReplayPayloadMissingBlocked -> "replay_payload_missing_blocked"
            | ReplayFrameJoinpointValueBlocked -> "joinpoint_value_blocked"
            | ReplayFrameReplayFingerprintRepeatBlocked -> "replay_fingerprint_repeat_blocked"
            | ReplayFrameIfUnknownReturnConditionBlocked -> "if_unknown_return_condition_blocked"
            | ReplayFrameIfSymbolicConditionBlocked -> "if_symbolic_condition_blocked"
            | ReplayFrameJoinpointTermStepperBlocked -> "joinpoint_term_stepper_blocked"
            | ReplayFrameMacroThunkMissingBlocked -> "macro_thunk_missing_blocked"
            | ReplayFrameTypeJoinpointStepperBlocked -> "tjoinpoint_stepper_blocked"
            | ReplayFrameLiteralOpBodyStepperBlocked -> "literal_op_body_stepper_blocked"
            | ReplayFrameDynamicJoinApplyBlocked -> "dynamic_join_apply_blocked"
            | ReplayFrameNominalConstructorStepperBlocked -> "nominal_constructor_stepper_blocked"
            | ReplayFrameSeqTypeErrorBlocked -> "seq_type_error_blocked"
            | ReplayFrameParentContinuationCycleBlocked -> "parent_continuation_cycle_blocked"
            | ReplayFrameParentContinuationCycleDeferred -> "parent_continuation_cycle_deferred_native_promise_failure_closed"
            | ReplayFrameGlobalFuseParentContinuationCycleBlocked -> "global_fuse_parent_continuation_cycle_blocked"
            | ReplayFrameParentReplayStatusPreservedRepeatBlocked -> "parent_replay_status_preserved_repeat_blocked"
            | ReplayFrameReplayObligationDeferred -> "replay_obligation_deferred"
            | ReplayFrameTypeVariableValueMissingBlocked -> "type_variable_value_missing_blocked"
            | ReplayFrameStaleRootRetargetBlocked -> "stale_root_retarget_blocked"
            | ReplayFrameLetSuccessApplyExceptionBlocked -> "let_success_apply_exception_blocked"
            | ReplayFrameLetSuccessAllReadyApplyBlocked -> "let_success_all_ready_apply_blocked"
            | ReplayFrameLetSuccessApplyContinuationBlocked -> "let_success_apply_continuation_blocked"
            | ReplayFrameTypeApplyForallBodyStepperBlocked -> "type_apply_forall_body_stepper_blocked"
            | ReplayFrameApplyContinuationExceptionBlocked -> "apply_continuation_exception_blocked"
            | ReplayFrameDeferredFunctionReplayExceptionBlocked -> "deferred_function_replay_exception_blocked"
            | ReplayFramePartialOneStepOnly -> "partial_one_step_only"
            | ReplayFrameNotComplete -> "not_complete"

        let private replayFrameCompletenessFor (frame:Frame) =
            let semanticCellRootComplete =
                match frame.semanticCell with
                | Some cell -> cellSemanticStatusIs SemanticRootComplete cell
                | None -> false
            if frameSemanticStatusIs SemanticRootComplete frame || semanticCellRootComplete then ReplayFrameComplete
            else
                match frameStatusSemanticStatusId frame.status with
                | SemanticLeafComplete -> ReplayFrameLeafCompleteParentContinuationMissing
                | SemanticLeafParentContinuationMissingBlocked -> ReplayFrameLeafParentContinuationMissingBlocked
                | SemanticSelectedFrontierRepeatBlocked -> ReplayFrameSelectedFrontierRepeatBlocked
                | SemanticReplayDriverExceptionBlocked -> ReplayFrameReplayDriverExceptionBlocked
                | SemanticReplayPayloadMissingBlocked -> ReplayFrameReplayPayloadMissingBlocked
                | SemanticJoinpointValueBlocked -> ReplayFrameJoinpointValueBlocked
                | SemanticReplayFingerprintRepeatBlocked -> ReplayFrameReplayFingerprintRepeatBlocked
                | SemanticIfUnknownReturnConditionBlocked -> ReplayFrameIfUnknownReturnConditionBlocked
                | SemanticIfSymbolicConditionBlocked -> ReplayFrameIfSymbolicConditionBlocked
                | SemanticJoinpointTermStepperBlocked -> ReplayFrameJoinpointTermStepperBlocked
                | SemanticMacroThunkMissingBlocked -> ReplayFrameMacroThunkMissingBlocked
                | SemanticTjoinpointStepperBlocked -> ReplayFrameTypeJoinpointStepperBlocked
                | SemanticLiteralOpBodyStepperBlocked -> ReplayFrameLiteralOpBodyStepperBlocked
                | SemanticDynamicJoinApplyBlocked -> ReplayFrameDynamicJoinApplyBlocked
                | SemanticNominalConstructorStepperBlocked -> ReplayFrameNominalConstructorStepperBlocked
                | SemanticSeqTypeErrorBlocked -> ReplayFrameSeqTypeErrorBlocked
                | SemanticParentContinuationCycleBlocked -> ReplayFrameParentContinuationCycleBlocked
                | SemanticParentContinuationCycleDeferred -> ReplayFrameParentContinuationCycleDeferred
                | SemanticGlobalFuseParentContinuationCycleBlocked -> ReplayFrameGlobalFuseParentContinuationCycleBlocked
                | SemanticParentReplayStatusPreservedRepeatBlocked -> ReplayFrameParentReplayStatusPreservedRepeatBlocked
                | SemanticReplayObligationDeferred -> ReplayFrameReplayObligationDeferred
                | SemanticTypeVariableValueMissingBlocked -> ReplayFrameTypeVariableValueMissingBlocked
                | SemanticStaleRootRetargetBlocked -> ReplayFrameStaleRootRetargetBlocked
                | SemanticLetSuccessApplyExceptionBlocked -> ReplayFrameLetSuccessApplyExceptionBlocked
                | SemanticLetSuccessAllReadyApplyBlocked -> ReplayFrameLetSuccessAllReadyApplyBlocked
                | SemanticLetSuccessApplyContinuationBlocked -> ReplayFrameLetSuccessApplyContinuationBlocked
                | SemanticTypeApplyForallBodyStepperBlocked -> ReplayFrameTypeApplyForallBodyStepperBlocked
                | SemanticApplyContinuationExceptionBlocked -> ReplayFrameApplyContinuationExceptionBlocked
                | SemanticDeferredFunctionReplayExceptionBlocked -> ReplayFrameDeferredFunctionReplayExceptionBlocked
                | SemanticStepPartial -> ReplayFramePartialOneStepOnly
                | SemanticOther reasonId when CompilerKernelV2.OperationalReasonIdOps.text reasonId = "semantic_step_done" -> ReplayFramePartialOneStepOnly
                | _ -> ReplayFrameNotComplete

        let private replayFrameCompletenessIsComplete = function
            | ReplayFrameComplete -> true
            | _ -> false

        let requiredMessage (msg: string) (frame: Frame) =
            let cellState = match frame.semanticCell with Some c -> formatCell c | None -> "none"
            let completenessId = replayFrameCompletenessFor frame
            let replayComplete = replayFrameCompletenessIsComplete completenessId
            let completeness = replayFrameCompletenessText completenessId
            FastRuntimeFormat.format "%s\nEvalWorklistFrame: kind=%s status=%s site=%s key=%s reason=%s depth=%d re=%d/%d trace_lines=%d pending=%d cursor=%d single_flight=1 replay_queue=%d semantic_payload=%s replay_complete=%b replay_completeness=%s replay_cell=%s adapter=trace_replay_continuation next=%s driver=%s driver_state=%s payload=%s" [| box msg; box (evalKindToString frame.kind); box (frameStatusToString frame.status); box (frameSiteText frame); box (frameKeyText frame); box (frame.reason |> frameReasonToString |> BoundedReasonTextOps.create |> compactFrameReason |> BoundedReasonTextOps.text); box frame.depth; box frame.re; box frame.maxRe; box frame.trace.Length; box (pendingCount()); box frame.cursor; box (replayQueueDepth()); box (semanticPayloadStatus()); box replayComplete; box completeness; box cellState; box (nextFor frame); box (replayDriverFor frame |> replayDriverToString); box (replayDriverStatus()); box (adapterPayload frame) |]


        // MIGRATION: when a global fuse abort is raised after retry_stop has already
        // selected a high-rank terminal, make the raised message name that terminal.
        // This prevents run_tests/root-source traces from looking like the live
        // problem when the real blocker is the pinned macro/literal/payload contract.
        //
        // MIGRATION: the historical marker proved the retarget worked but also
        // showed unbounded observer churn.  Rate-limit by a structural identity;
        // rendering event/status/key text is no longer the identity contract.
        type GlobalFuseRetargetNoticeKind =
            | GlobalFuseMissingAfterPrefetchHighRank
            | GlobalFuseTerminalPrimarySelected
            | GlobalFuseTerminalErrorCodeProjection
            | GlobalFuseTerminalPrimaryIdempotent
            | GlobalFuseAbortHandoffDeferred
            | GlobalFuseAbortRetargeted
            | GlobalFuseReplayReturnSuppressed

        [<StructuralEquality; NoComparison>]
        type GlobalFuseRetargetNoticeIdentity = private {
            noticeKind : GlobalFuseRetargetNoticeKind
            event : ReplayEventId option
            requestedKind : EvalKind
            shape : CompilerIdentityKernel.WorkShapeId option
            pinnedStatus : FrameStatusId
            pinnedKey : ReplayKeyId
        }

        let private globalFuseTerminalRetargetSeen =
            System.Collections.Concurrent.ConcurrentDictionary<GlobalFuseRetargetNoticeIdentity, int>()

        let private retargetSeenOnce (noticeKind: GlobalFuseRetargetNoticeKind) (event: string option) (requestedKind: EvalKind) (shape: CompilerIdentityKernel.WorkShapeId option) (pinned: Frame) =
            let identity : GlobalFuseRetargetNoticeIdentity = {
                noticeKind = noticeKind
                event = event |> Option.map ReplayEventIdOps.create
                requestedKind = requestedKind
                shape = shape
                pinnedStatus = pinned.status
                pinnedKey = pinned.key
            }
            globalFuseTerminalRetargetSeen.TryAdd(identity, 1)

        let private highRankPinnedTerminal (requestedKind: EvalKind) =
            match tryPinnedTerminalContract() with
            | Some pinned ->
                let rank = terminalContractRank pinned.status
                let missingAfterPrefetchDecisionId =
                    missingAfterPrefetchTerminalDecisionFor
                        (frameSemanticStatusId pinned)
                        (pendingCount())
                        (replayQueueDepth())
                        (replayDriverActiveDepthValue())
                        (hasProgressYield())
                        (hasReplayComplete())
                        (hasReplayCompleteWriteWitness())
                        0
                let missingAfterPrefetchRetargetDeferred =
                    missingAfterPrefetchTerminalDecisionShouldDefer missingAfterPrefetchDecisionId
                if missingAfterPrefetchRetargetDeferred then
                    if retargetSeenOnce GlobalFuseMissingAfterPrefetchHighRank None requestedKind None pinned then
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_missing_after_prefetch_high_rank_retarget_deferred\",\"event\":\"global_fuse_terminal_probe\",\"requested_kind\":%s,\"pinned_kind\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"decision_du\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"replay_complete\":%b,\"write_witness\":%b,\"single_flight\":1,\"next\":\"preserve_replay_lane_before_missing_after_prefetch_terminal\"}" [| box (esc (evalKindToString requestedKind)); box (esc (frameKindText pinned)); box (esc (frameStatusToString pinned.status)); box rank; box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (esc (missingAfterPrefetchTerminalDecisionText missingAfterPrefetchDecisionId)); box (pendingCount()); box (replayQueueDepth()); box (replayDriverActiveDepthValue()); box (hasReplayComplete()); box (hasReplayCompleteWriteWitness()) |])
                    None
                elif rank >= 80 && frameKindCompatibleId requestedKind pinned then Some (pinned, rank)
                elif rank >= 80 then
                    // MIGRATION: pre-Hopac kind locality. A high-rank terminal from a
                    // different evaluator kind is evidence for its own lane, not a
                    // selector for this global-fuse probe. Clear only the active pin;
                    // durable evidence remains available to same-kind consumers.
                    let cleared = lock gate (fun () -> clearCurrentCrossKindPinnedTerminalLocked pinned)
                    emitCrossKindPinnedTerminalIgnoredId
                        "global_fuse_terminal_probe"
                        requestedKind
                        pinned
                        rank
                        (CrossKindPinnedTerminalGlobalFuseMismatch cleared)
                    if cleared then
                        DiagJson.emit (
                            FastRuntimeFormat.format """{"kind":"eval_worklist_cross_kind_global_fuse_active_pin_cleared","event":"global_fuse_terminal_probe","requested_kind":%s,"pinned_kind":%s,"pinned_status":%s,"pinned_rank":%d,"pinned_site":%s,"pinned_key":%s,"pending":%d,"single_flight":1,"policy":"pre_hopac_kind_local_terminal_contracts","next":"preserve_kind_local_frontier"}""" [| box (esc (evalKindToString requestedKind)); box (esc (frameKindText pinned)); box (esc (frameStatusToString pinned.status)); box rank; box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (pendingCount()) |])
                    None
                else None
            | None -> None

        let private trimOriginalFuseForMessage (msg: string) =
            let withoutFrame =
                let marker = "\nEvalWorklistFrame:"
                msg.Split([|marker|], 2, StringSplitOptions.None).[0]
            withoutFrame.Replace("\r", " ").Replace("\n", " ⏎ ")

        // MIGRATION: terminal-primary retargets now expose the dynamic-join/root
        // fuse cause through a DU.  The final text can still carry the original
        // human-readable fuse, but downstream receipts can key on terminal_cause_du
        // instead of scanning message substrings.
        type TerminalPrimaryCauseId =
            | TerminalCauseDynamicJoinRuntimeDynTypecheck
            | TerminalCauseDynamicJoinFunctionBodyDynamicArg
            | TerminalCauseParentContinuationReplayCapExhausted
            | TerminalCauseTyParentContinuationReplayCapExhausted
            | TerminalCauseGlobalFuseAbort
            | TerminalCausePinnedTerminal

        let terminalPrimaryCauseText = function
            | TerminalCauseDynamicJoinRuntimeDynTypecheck -> "dynamic_join_runtime_dyn_typecheck"
            | TerminalCauseDynamicJoinFunctionBodyDynamicArg -> "dynamic_join_function_body_dynamic_arg"
            | TerminalCauseParentContinuationReplayCapExhausted -> "parent_continuation_replay_cap_exhausted"
            | TerminalCauseTyParentContinuationReplayCapExhausted -> "ty_parent_continuation_replay_cap_exhausted"
            | TerminalCauseGlobalFuseAbort -> "global_fuse_abort"
            | TerminalCausePinnedTerminal -> "pinned_terminal"

        type TerminalPrimaryEvidence = private {
            cause : TerminalPrimaryCauseId
            facts : Set<DiagnosticClassifier.DiagnosticFactId>
        }

        let terminalPrimaryEvidenceFor (msg: string) (pinned: Frame) =
            let safeMsg = if System.String.IsNullOrEmpty msg then "" else msg
            let safeReason = frameReasonToString pinned.reason
            let facts = DiagnosticClassifier.classifyFacts (safeMsg + "\n" + safeReason)
            let cause =
                if frameSemanticStatusIs SemanticDynamicJoinApplyBlocked pinned
                   && Set.contains DiagnosticClassifier.DiagnosticDynamicJoinRuntimeDynTypecheck facts then
                    TerminalCauseDynamicJoinRuntimeDynTypecheck
                elif frameSemanticStatusIs SemanticDynamicJoinApplyBlocked pinned
                     && Set.contains DiagnosticClassifier.DiagnosticDynamicJoinFunctionBodyDynamicArg facts then
                    TerminalCauseDynamicJoinFunctionBodyDynamicArg
                elif Set.contains DiagnosticClassifier.DiagnosticTyParentContinuationReplayCapExhausted facts then
                    TerminalCauseTyParentContinuationReplayCapExhausted
                elif frameSemanticStatusIs SemanticParentContinuationCycleDeferred pinned
                     || Set.contains DiagnosticClassifier.DiagnosticParentContinuationReplayCapExhausted facts then
                    TerminalCauseParentContinuationReplayCapExhausted
                elif Set.contains DiagnosticClassifier.DiagnosticGlobalTermCycleFuseTripped facts then
                    TerminalCauseGlobalFuseAbort
                else
                    TerminalCausePinnedTerminal
            { cause = cause; facts = facts }

        type TerminalErrorCodeProjectionId =
            | TerminalErrorCodeNativeCause of wrapper:DiagnosticClassifier.DiagnosticCodeId * cause:DiagnosticClassifier.DiagnosticCodeId
            | TerminalErrorCodeLegacyCause of wrapper:DiagnosticClassifier.DiagnosticCodeId * cause:DiagnosticClassifier.DiagnosticCodeId

        let terminalErrorCodeProjectionFor nativePromiseOwnedPinnedTerminal (_terminalCause: TerminalPrimaryCauseId) =
            let causeCode = if nativePromiseOwnedPinnedTerminal then DiagnosticClassifier.DiagnosticEJP0032 else DiagnosticClassifier.DiagnosticEJP0011
            if nativePromiseOwnedPinnedTerminal then TerminalErrorCodeNativeCause(DiagnosticClassifier.DiagnosticEJP0011, causeCode)
            else TerminalErrorCodeLegacyCause(DiagnosticClassifier.DiagnosticEJP0011, causeCode)

        let terminalErrorCodeProjectionText = function
            | TerminalErrorCodeNativeCause(wrapper, cause) -> sprintf "TerminalErrorCodeProjection(NativeCause|wrapper=%s|cause=%s)" (DiagnosticClassifier.codeIdText wrapper) (DiagnosticClassifier.codeIdText cause)
            | TerminalErrorCodeLegacyCause(wrapper, cause) -> sprintf "TerminalErrorCodeProjection(LegacyCause|wrapper=%s|cause=%s)" (DiagnosticClassifier.codeIdText wrapper) (DiagnosticClassifier.codeIdText cause)

        let terminalErrorCodeProjectionCanonicalCode = function
            | TerminalErrorCodeNativeCause(_, cause)
            | TerminalErrorCodeLegacyCause(_, cause) -> cause

        let terminalErrorCodeProjectionWrapperCode = function
            | TerminalErrorCodeNativeCause(wrapper, _)
            | TerminalErrorCodeLegacyCause(wrapper, _) -> wrapper

        type GlobalFuseNativeCallbackHandoffDecisionId =
            | GlobalFuseNativeCallbackHandoffNone
            | GlobalFuseNativeCallbackHandoffParentReplayStatusCacheHandoff
            | GlobalFuseNativeCallbackHandoffParentReplayCycleBreakInlineCallback

        let globalFuseNativeCallbackHandoffDecisionText = function
            | GlobalFuseNativeCallbackHandoffNone -> "none"
            | GlobalFuseNativeCallbackHandoffParentReplayStatusCacheHandoff -> "defer_global_fuse_to_parent_replay_status_preserved_cache_handoff"
            | GlobalFuseNativeCallbackHandoffParentReplayCycleBreakInlineCallback -> "defer_global_fuse_to_parent_replay_cycle_break_inline_callback"

        let globalFuseNativeCallbackHandoffDecisionShouldDefer = function
            | GlobalFuseNativeCallbackHandoffNone -> false
            | _ -> true

        type GlobalFuseHandoffEvidenceId =
            | GlobalFuseHandoffPreservedCache
            | GlobalFuseHandoffPreservedLegacyStatus

        let private globalFuseHandoffEvidence (text:string) =
            let safe = if System.String.IsNullOrEmpty text then "" else text
            let tokens =
                safe.Split(
                    [| '|'; ':'; ','; ';'; ' '; '='; '('; ')'; '['; ']'; '\n'; '\r'; '\t' |],
                    StringSplitOptions.RemoveEmptyEntries)
                |> Array.map (fun token -> token.ToLowerInvariant())
                |> Set.ofArray
            [ if Set.contains "parentreplaystatuspreservedcachehandoff" tokens then
                  GlobalFuseHandoffPreservedCache
              if Set.contains "parent_replay_status_preserved" tokens then
                  GlobalFuseHandoffPreservedLegacyStatus ]
            |> Set.ofList

        type NativePromiseOwnershipSignalId =
            | NativePromiseOwnershipParentContinuationClosed
            | NativePromiseOwnershipDeferredChildCell
            | NativePromiseOwnershipPinnedReason
            | NativePromiseOwnershipGlobalTermCycleFuse

        let nativePromiseOwnershipSignalText = function
            | NativePromiseOwnershipParentContinuationClosed -> "ParentContinuationClosed"
            | NativePromiseOwnershipDeferredChildCell -> "DeferredChildCell"
            | NativePromiseOwnershipPinnedReason -> "PinnedReason"
            | NativePromiseOwnershipGlobalTermCycleFuse -> "GlobalTermCycleFuse"

        type NativePromiseOwnershipEvidenceId =
            | NativePromiseOwnershipStructuredFailClosed
            | NativePromiseOwnershipStructuredEvidence of Set<NativePromiseOwnershipSignalId>

        let nativePromiseOwnershipEvidenceText = function
            | NativePromiseOwnershipStructuredFailClosed -> "StructuredFailClosed"
            | NativePromiseOwnershipStructuredEvidence signals ->
                signals
                |> Seq.map nativePromiseOwnershipSignalText
                |> Seq.sort
                |> String.concat ","
                |> sprintf "StructuredEvidence(signals=[%s])"

        let nativePromiseOwnershipEvidenceSignals = function
            | NativePromiseOwnershipStructuredFailClosed -> Set.empty
            | NativePromiseOwnershipStructuredEvidence signals -> signals

        let private nativePromiseOwnershipSignalsFor (evidence:TerminalPrimaryEvidence) =
            [ if evidence.cause = TerminalCauseParentContinuationReplayCapExhausted
                 || evidence.cause = TerminalCauseTyParentContinuationReplayCapExhausted then
                  NativePromiseOwnershipParentContinuationClosed
              if Set.contains DiagnosticClassifier.DiagnosticDeferredChildCell evidence.facts then
                  NativePromiseOwnershipDeferredChildCell
              if Set.contains DiagnosticClassifier.DiagnosticNativePromiseFailure evidence.facts then
                  NativePromiseOwnershipPinnedReason
              if Set.contains DiagnosticClassifier.DiagnosticGlobalTermCycleFuseTripped evidence.facts then
                  NativePromiseOwnershipGlobalTermCycleFuse ]
            |> Set.ofList

        let private nativePromiseOwnershipEvidence nativeFailureClosed terminalEvidence =
            if nativeFailureClosed then
                NativePromiseOwnershipStructuredFailClosed
            else
                NativePromiseOwnershipStructuredEvidence (nativePromiseOwnershipSignalsFor terminalEvidence)

        let globalFuseNativeCallbackHandoffDecisionFor (pinned: Frame) pending replayDepth activeDepth (msg: string) =
            let hasLiveNativeWork = pending > 0 || replayDepth > 0 || activeDepth > 0
            let blob = (if System.String.IsNullOrEmpty msg then "" else msg) + "\n" + frameReasonToString pinned.reason + "\n" + frameStatusToString pinned.status
            let handoffEvidence = globalFuseHandoffEvidence blob
            let preservedStatusEvidence =
                Set.contains GlobalFuseHandoffPreservedCache handoffEvidence
                || Set.contains GlobalFuseHandoffPreservedLegacyStatus handoffEvidence
            if not hasLiveNativeWork then GlobalFuseNativeCallbackHandoffNone
            elif frameSemanticStatusId pinned = SemanticParentReplayCycleBreakPoisoned && preservedStatusEvidence then GlobalFuseNativeCallbackHandoffParentReplayStatusCacheHandoff
            elif frameSemanticStatusId pinned = SemanticParentReplayCycleBreakPoisoned then GlobalFuseNativeCallbackHandoffParentReplayCycleBreakInlineCallback
            else GlobalFuseNativeCallbackHandoffNone

        type TerminalPrimaryMessageShapeId =
            | TerminalPrimaryCanonicalPinnedMessage of hasEvalWorklistFrame:bool
            | TerminalPrimaryMessageOther

        let private terminalPrimaryMessageShapeFor (primaryPrefix:string) (msg:string) =
            if System.String.IsNullOrWhiteSpace msg then
                TerminalPrimaryMessageOther
            else
                let lines =
                    msg.Replace("\r\n", "\n").Replace("\r", "\n")
                       .Split([|'\n'|], System.StringSplitOptions.RemoveEmptyEntries)
                let firstLine = lines |> Array.tryHead |> Option.defaultValue ""
                let header =
                    firstLine.Split([|" status="|], System.StringSplitOptions.None)
                    |> Array.tryHead
                    |> Option.defaultValue ""
                let hasPinnedTerminal =
                    lines
                    |> Array.exists (fun line ->
                        let parts = line.Trim().Split([|'='|], 2)
                        parts.Length = 2 && parts.[0] = "pinned_terminal")
                let hasEvalWorklistFrame =
                    lines
                    |> Array.exists (fun line ->
                        let parts = line.Trim().Split([|':'|], 2)
                        parts.Length > 0 && parts.[0] = "EvalWorklistFrame")
                if header = primaryPrefix && hasPinnedTerminal then
                    TerminalPrimaryCanonicalPinnedMessage hasEvalWorklistFrame
                else
                    TerminalPrimaryMessageOther

        let terminalPrimaryMessage (requestedKind: EvalKind) (msg: string) (pinned: Frame) (rank: int) =
            let terminalEvidence = terminalPrimaryEvidenceFor msg pinned
            let terminalCause = terminalEvidence.cause
            let terminalCauseText = terminalPrimaryCauseText terminalCause
            if retargetSeenOnce GlobalFuseTerminalPrimarySelected None requestedKind None pinned then
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_primary_message_selected\",\"event\":%s,\"requested_kind\":%s,\"status\":%s,\"terminal_cause_du\":%s,\"rank\":%d,\"site\":%s,\"key\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc "terminal_primary_message"); box (esc (evalKindToString requestedKind)); box (esc (frameStatusToString pinned.status)); box (esc terminalCauseText); box rank; box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (pendingCount()); box (esc (nextFor pinned)) |])
            let nativeFailureClosed = DiagJson.nativePromiseFailureClosedNow()
            let ownershipEvidence =
                nativePromiseOwnershipEvidence nativeFailureClosed terminalEvidence
            let ownershipSignals =
                nativePromiseOwnershipEvidenceSignals ownershipEvidence
            let nativePromiseOwnedPinnedTerminal =
                match ownershipEvidence with
                | NativePromiseOwnershipStructuredFailClosed -> true
                | NativePromiseOwnershipStructuredEvidence _ ->
                    Set.contains NativePromiseOwnershipParentContinuationClosed ownershipSignals
                    || Set.contains NativePromiseOwnershipDeferredChildCell ownershipSignals
                    || Set.contains NativePromiseOwnershipPinnedReason ownershipSignals
                    || (terminalCause = TerminalCauseParentContinuationReplayCapExhausted
                        && Set.contains NativePromiseOwnershipGlobalTermCycleFuse ownershipSignals)
            let terminalCodeProjectionId = terminalErrorCodeProjectionFor nativePromiseOwnedPinnedTerminal terminalCause
            let primaryCode = terminalErrorCodeProjectionCanonicalCode terminalCodeProjectionId
            let wrapperCode = terminalErrorCodeProjectionWrapperCode terminalCodeProjectionId
            let primaryCodeText = DiagnosticClassifier.codeText primaryCode
            let primaryCodeIdText = DiagnosticClassifier.codeIdText primaryCode
            let wrapperCodeIdText = DiagnosticClassifier.codeIdText wrapperCode
            let terminalCodeProjectionText = terminalErrorCodeProjectionText terminalCodeProjectionId
            if retargetSeenOnce GlobalFuseTerminalErrorCodeProjection None requestedKind None pinned then
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_error_code_projection\",\"event\":%s,\"requested_kind\":%s,\"status\":%s,\"terminal_cause_du\":%s,\"canonical_error_code_du\":%s,\"terminal_cause_code_du\":%s,\"wrapper_error_code_du\":%s,\"terminal_error_code_projection_du\":%s,\"ownership_evidence_du\":%s,\"native_promise_owned\":%b,\"rank\":%d,\"site\":%s,\"key\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc "terminal_error_code_projection"); box (esc (evalKindToString requestedKind)); box (esc (frameStatusToString pinned.status)); box (esc terminalCauseText); box (esc primaryCodeIdText); box (esc primaryCodeIdText); box (esc wrapperCodeIdText); box (esc terminalCodeProjectionText); box (esc (nativePromiseOwnershipEvidenceText ownershipEvidence)); box nativePromiseOwnedPinnedTerminal; box rank; box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (pendingCount()); box (esc (nextFor pinned)) |])
            let primaryPrefix = primaryCodeText + ": pinned terminal contract blocked"
            match terminalPrimaryMessageShapeFor primaryPrefix msg with
            | TerminalPrimaryCanonicalPinnedMessage hasEvalWorklistFrame ->
                if retargetSeenOnce GlobalFuseTerminalPrimaryIdempotent None requestedKind None pinned then
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_primary_message_idempotent\",\"event\":%s,\"requested_kind\":%s,\"status\":%s,\"terminal_cause_du\":%s,\"rank\":%d,\"site\":%s,\"key\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}" [| box (esc "terminal_primary_message"); box (esc (evalKindToString requestedKind)); box (esc (frameStatusToString pinned.status)); box (esc terminalCauseText); box rank; box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (pendingCount()); box (esc (nextFor pinned)) |])
                if hasEvalWorklistFrame then msg else requiredMessage msg pinned
            | TerminalPrimaryMessageOther ->
                let originalFuse = trimOriginalFuseForMessage msg
                let pinnedMsg =
                    FastRuntimeFormat.format "%s: pinned terminal contract blocked status=%s terminal_cause_du=%s canonical_error_code_du=%s terminal_cause_code_du=%s wrapper_error_code_du=%s terminal_error_code_projection_du=%s rank=%d site=%s requested_kind=%s\npinned_terminal=%s pinned_rank=%d pinned_site=%s requested_kind=%s original_fuse=%s" [| box primaryCodeText; box (frameStatusToString pinned.status); box terminalCauseText; box primaryCodeIdText; box primaryCodeIdText; box wrapperCodeIdText; box terminalCodeProjectionText; box rank; box (frameSiteText pinned); box (evalKindToString requestedKind); box (frameStatusToString pinned.status); box rank; box (frameSiteText pinned); box (evalKindToString requestedKind); box originalFuse |]
                requiredMessage pinnedMsg pinned

        let private pinnedTerminalMessage (requestedKind: EvalKind) (msg: string) (pinned: Frame) (rank: int) =
            terminalPrimaryMessage requestedKind msg pinned rank

        let retargetGlobalFuseAbortMessage (event: string) (requestedKind: EvalKind) (msg: string) =
            match highRankPinnedTerminal requestedKind with
            | Some (pinned, rank) ->
                let missingAfterPrefetchDecisionId =
                    missingAfterPrefetchTerminalDecisionFor
                        (frameSemanticStatusId pinned)
                        (pendingCount())
                        (replayQueueDepth())
                        (replayDriverActiveDepthValue())
                        (hasProgressYield())
                        (hasReplayComplete())
                        (hasReplayCompleteWriteWitness())
                        0
                let nativeCallbackHandoffDecisionId = globalFuseNativeCallbackHandoffDecisionFor pinned (pendingCount()) (replayQueueDepth()) (replayDriverActiveDepthValue()) msg
                if missingAfterPrefetchTerminalDecisionShouldDefer missingAfterPrefetchDecisionId || globalFuseNativeCallbackHandoffDecisionShouldDefer nativeCallbackHandoffDecisionId then
                    if retargetSeenOnce GlobalFuseAbortHandoffDeferred (Some event) requestedKind None pinned then
                        let decisionText = (missingAfterPrefetchTerminalDecisionText missingAfterPrefetchDecisionId) + "|" + (globalFuseNativeCallbackHandoffDecisionText nativeCallbackHandoffDecisionId)
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_global_fuse_abort_native_callback_handoff_deferred\",\"event\":%s,\"requested_kind\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"decision_du\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"replay_complete\":%b,\"write_witness\":%b,\"single_flight\":1,\"next\":\"native_hopac_parent_replay_status_preserved_cache_handoff_direct_required\"}" [| box (esc event); box (esc (evalKindToString requestedKind)); box (esc (frameStatusToString pinned.status)); box rank; box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (esc decisionText); box (pendingCount()); box (replayQueueDepth()); box (replayDriverActiveDepthValue()); box (hasReplayComplete()); box (hasReplayCompleteWriteWitness()) |])
                    msg
                else
                    if retargetSeenOnce GlobalFuseAbortRetargeted (Some event) requestedKind None pinned then
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_global_fuse_abort_retargeted_to_pinned_terminal\",\"event\":%s,\"requested_kind\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"pending\":%d,\"single_flight\":1,\"rate_limited\":1,\"next\":%s}" [| box (esc event); box (esc (evalKindToString requestedKind)); box (esc (frameStatusToString pinned.status)); box rank; box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (pendingCount()); box (esc (nextFor pinned)) |])
                    pinnedTerminalMessage requestedKind msg pinned rank
            | None -> msg

        type GlobalFuseReplayReturnShapeId =
            | GlobalFuseReturnTFun
            | GlobalFuseReturnTPrim
            | GlobalFuseReturnTV
            | GlobalFuseReturnTB
            | GlobalFuseReturnTPair
            | GlobalFuseReturnTRecord
            | GlobalFuseReturnTUnion
            | GlobalFuseReturnTNominal
            | GlobalFuseReturnTApply
            | GlobalFuseReturnTExists
            | GlobalFuseReturnTForall
            | GlobalFuseReturnEApply
            | GlobalFuseReturnEV
            | GlobalFuseReturnEFun
            | GlobalFuseReturnEForall
            | GlobalFuseReturnETypeApply
            | GlobalFuseReturnERecordWith
            | GlobalFuseReturnEUnbox
            | GlobalFuseReturnEOp
            | GlobalFuseReturnOther

        let private globalFuseReplayReturnShapeId (shape: CompilerIdentityKernel.WorkShapeId) =
            match cellShapeOfWorkShapeId shape with
            | CellShapeTFun -> GlobalFuseReturnTFun
            | CellShapeTPrim -> GlobalFuseReturnTPrim
            | CellShapeTV -> GlobalFuseReturnTV
            | CellShapeTB -> GlobalFuseReturnTB
            | CellShapeTPair -> GlobalFuseReturnTPair
            | CellShapeTRecord -> GlobalFuseReturnTRecord
            | CellShapeTUnion -> GlobalFuseReturnTUnion
            | CellShapeTNominal -> GlobalFuseReturnTNominal
            | CellShapeTApply -> GlobalFuseReturnTApply
            | CellShapeTExists -> GlobalFuseReturnTExists
            | CellShapeTForallPrime -> GlobalFuseReturnTForall
            | CellShapeEApply -> GlobalFuseReturnEApply
            | CellShapeEV -> GlobalFuseReturnEV
            | CellShapeEFun -> GlobalFuseReturnEFun
            | CellShapeEForall -> GlobalFuseReturnEForall
            | CellShapeETypeApply -> GlobalFuseReturnETypeApply
            | CellShapeERecordWith -> GlobalFuseReturnERecordWith
            | CellShapeEUnbox -> GlobalFuseReturnEUnbox
            | CellShapeEOp -> GlobalFuseReturnEOp
            | _ -> GlobalFuseReturnOther

        let private globalFuseShapeSupportsOpImplReturn = function
            | GlobalFuseReturnTFun
            | GlobalFuseReturnEApply
            | GlobalFuseReturnEV
            | GlobalFuseReturnEForall
            | GlobalFuseReturnETypeApply
            | GlobalFuseReturnEOp -> true
            | _ -> false

        let private globalFuseShapeSupportsSymbolicIfReturn = function
            | GlobalFuseReturnTFun
            | GlobalFuseReturnEApply
            | GlobalFuseReturnEV
            | GlobalFuseReturnEForall
            | GlobalFuseReturnETypeApply -> true
            | _ -> false

        let private globalFuseShapeSupportsGenericReturn = function
            | GlobalFuseReturnOther -> false
            | _ -> true

        let trySuppressGlobalFuseReplayReturnForPinnedTerminal (event: string) (requestedKind: EvalKind) (shape: CompilerIdentityKernel.WorkShapeId) (msg: string) =
            let shapeText = CompilerIdentityKernel.WorkShapeIdOps.text shape
            let shapeId = globalFuseReplayReturnShapeId shape
            match highRankPinnedTerminal requestedKind with
            | Some (pinned, rank) ->
                let freshReplayRootWitnessAvailable =
                    let ageMs = (System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds
                    replayRootCompleteWitnessUtc <> System.DateTime.MinValue
                    && ageMs >= 0.0
                    && ageMs <= replayRootCompleteWitnessWindowMs
                let freshRootWitnessShieldsOpImplReturn =
                    frameSemanticStatusIs SemanticOpImplRequiredBlocked pinned
                    && pendingCount() > 0
                    && freshReplayRootWitnessAvailable
                    && frameCellShapeOrSemanticEvidence [CellShapeEOp] pinned
                    && globalFuseShapeSupportsOpImplReturn shapeId
                let staleListmSymbolicIfRootReturn =
                    frameSemanticStatusIs SemanticIfSymbolicConditionBlocked pinned
                    && pendingCount() > 0
                    && frameCellShapeOrSemanticEvidence [CellShapeEIfThenElse] pinned
                    && globalFuseShapeSupportsSymbolicIfReturn shapeId
                let freshRootWitnessShieldsGlobalFuseReturn =
                    // MIGRATION: historical runtime reached stable root-complete at backend.spi:80
                    // and jp_wait closed with pending=0/enqueued=done, but the final
                    // BuildError was retargeted to an older rank-80 global-fuse parent
                    // continuation terminal.  When this function is called, the current
                    // path already has a global replay-complete return in hand; a fresh
                    // replay-root write witness is stronger than a stale generic global
                    // fuse pin, but only for that generic parent-continuation status.
                    frameSemanticStatusIs SemanticGlobalFuseParentContinuationCycleBlocked pinned
                    && freshReplayRootWitnessAvailable
                    && globalFuseShapeSupportsGenericReturn shapeId
                if freshRootWitnessShieldsOpImplReturn then
                    let durableCleared =
                        lock gate (fun () ->
                            match pinnedTerminalContract with
                            | Some p when frameSemanticStatusIs SemanticOpImplRequiredBlocked p && p.site = pinned.site ->
                                pinnedTerminalContract <- None
                            | _ -> ()
                            match durableTerminalContract with
                            | Some p when frameSemanticStatusIs SemanticOpImplRequiredBlocked p && p.site = pinned.site ->
                                durableTerminalContract <- None
                                true
                            | _ -> false)
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_global_fuse_root_return_demotes_fresh_op_impl_required\",\"event\":%s,\"requested_kind\":%s,\"shape\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"pending\":%d,\"durable_cleared\":%b,\"witness\":%s,\"single_flight\":1,\"next\":\"allow_root_complete_replay_return\"}" [| box (esc event); box (esc (evalKindToString requestedKind)); box (esc shapeText); box (esc (frameStatusToString pinned.status)); box rank; box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (pendingCount()); box durableCleared; box (esc replayRootCompleteWitnessSummary) |])
                    None
                elif staleListmSymbolicIfRootReturn then
                    let durableCleared =
                        lock gate (fun () ->
                            match pinnedTerminalContract with
                            | Some p when frameSemanticStatusIs SemanticIfSymbolicConditionBlocked p && p.site = pinned.site ->
                                pinnedTerminalContract <- None
                            | _ -> ()
                            match durableTerminalContract with
                            | Some p when frameSemanticStatusIs SemanticIfSymbolicConditionBlocked p && p.site = pinned.site ->
                                durableTerminalContract <- None
                                true
                            | _ -> false)
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_global_fuse_root_return_demotes_stale_if_symbolic\",\"event\":%s,\"requested_kind\":%s,\"shape\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"pending\":%d,\"durable_cleared\":%b,\"single_flight\":1,\"next\":\"allow_root_complete_replay_return\"}" [| box (esc event); box (esc (evalKindToString requestedKind)); box (esc shapeText); box (esc (frameStatusToString pinned.status)); box rank; box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (pendingCount()); box durableCleared |])
                    None
                elif freshRootWitnessShieldsGlobalFuseReturn then
                    let durableCleared =
                        lock gate (fun () ->
                            match pinnedTerminalContract with
                            | Some p when frameSemanticStatusIs SemanticGlobalFuseParentContinuationCycleBlocked p && p.site = pinned.site ->
                                pinnedTerminalContract <- None
                            | _ -> ()
                            match durableTerminalContract with
                            | Some p when frameSemanticStatusIs SemanticGlobalFuseParentContinuationCycleBlocked p && p.site = pinned.site ->
                                durableTerminalContract <- None
                                true
                            | _ -> false)
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_global_fuse_root_return_demotes_stale_parent_fuse\",\"event\":%s,\"requested_kind\":%s,\"shape\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"pending\":%d,\"durable_cleared\":%b,\"witness\":%s,\"single_flight\":1,\"next\":\"allow_root_complete_replay_return\"}" [| box (esc event); box (esc (evalKindToString requestedKind)); box (esc shapeText); box (esc (frameStatusToString pinned.status)); box rank; box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (pendingCount()); box durableCleared; box (esc replayRootCompleteWitnessSummary) |])
                    None
                else
                    if retargetSeenOnce GlobalFuseReplayReturnSuppressed (Some event) requestedKind (Some shape) pinned then
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_global_fuse_replay_return_suppressed_by_pinned_terminal\",\"event\":%s,\"requested_kind\":%s,\"shape\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"pending\":%d,\"fresh_root_witness\":%b,\"single_flight\":1,\"next\":%s}" [| box (esc event); box (esc (evalKindToString requestedKind)); box (esc shapeText); box (esc (frameStatusToString pinned.status)); box rank; box (esc (frameSiteText pinned)); box (esc (frameKeyText pinned)); box (pendingCount()); box freshReplayRootWitnessAvailable; box (esc (nextFor pinned)) |])
                    Some (pinnedTerminalMessage requestedKind msg pinned rank)
            | None -> None


    /// Typed owner identity shared by method and closure join-point registries.
    /// Equality requires both the interned BackendId and the structural body identity;
    /// backend equality alone is never authority to reuse a materialized codegen body.
    type JpBodyOwnerIdentity = private {
        backendId : CompilerKernelV2.BackendId
        backendNode : string ConsedNode
        body : E
    }

    module JpBodyOwnerIdentity =
        let create (backendNode:string ConsedNode) (body:E) : JpBodyOwnerIdentity =
            { backendId = CompilerKernelV2.BackendIdOps.create backendNode.node
              backendNode = backendNode
              body = body }

        let backendId (identity:JpBodyOwnerIdentity) = identity.backendId
        let backendNode (identity:JpBodyOwnerIdentity) = identity.backendNode
        let backendText (identity:JpBodyOwnerIdentity) = CompilerKernelV2.BackendIdOps.text identity.backendId
        let body (identity:JpBodyOwnerIdentity) = identity.body

        let equals (left:JpBodyOwnerIdentity) (right:JpBodyOwnerIdentity) =
            left.backendId = right.backendId
            && LanguagePrimitives.GenericEquality left.body right.body

        let hash (identity:JpBodyOwnerIdentity) =
            (LanguagePrimitives.GenericHash identity.backendId)
            ^^^ (LanguagePrimitives.GenericHash identity.body)

    type JpNestedBackendKind =
        | JpNestedCuda
        | JpNestedUnsupported of CompilerKernelV2.BackendId

    module JpNestedBackendKind =
        let ofOwner owner =
            match JpBodyOwnerIdentity.backendText owner with
            | "Cuda" -> JpNestedCuda
            | _ -> JpNestedUnsupported (JpBodyOwnerIdentity.backendId owner)

        let text = function
            | JpNestedCuda -> "Cuda"
            | JpNestedUnsupported backendId -> CompilerKernelV2.BackendIdOps.text backendId

    /// ### JoinPointKey
    type JoinPointKey =
        | JPMethod of JpBodyOwnerIdentity * ConsedNode<RData [] * Ty [] * Ty>
        | JPClosure of JpBodyOwnerIdentity * ConsedNode<RData [] * Ty [] * Ty>
    

    /// ### JoinPointCall
    type JoinPointCall = JoinPointKey * TyV []
    

    /// ### CodeMacro
    type CodeMacro =
        | CMText of string
        | CMTerm of Data * is_inline : bool
        | CMType of Ty
        | CMTypeLit of Ty
    

    type LayoutFieldNameKind private () =
        static member InternedKindTag () = 0x150001u
    type LayoutFieldNameId = CompilerIdentityKernel.InternedTextId<LayoutFieldNameKind>

    module LayoutFieldNameIdOps =
        let create value : LayoutFieldNameId =
            CompilerIdentityKernel.InternedTextId.create<LayoutFieldNameKind> value

        let text (value:LayoutFieldNameId) =
            CompilerIdentityKernel.InternedTextIdOps.text value

        let matchesText (fieldId:LayoutFieldNameId) text =
            fieldId = create text

    /// ### TypedBind
    type TypedBind =
        | TyLet of Data * Trace * TypedOp
        | TyLocalReturnOp of Trace * TypedOp * Data
        | TyLocalReturnData of Data * Trace
    

    and TypedOp =
        | TyMacro of CodeMacro list
        | TyOp of Op * Data list
        | TyUnionBox of UnionTagId * Data * Union
        | TyUnionUnbox of TyV list * Union * Map<UnionTagId,Data list * TypedBind []> * TypedBind [] option
        | TyIntSwitch of TyV * TypedBind [] [] * TypedBind []
        | TyToLayout of Data * Ty
        | TyLayoutIndexAll of TyV
        | TyLayoutIndexByKey of TyV * LayoutFieldNameId
        | TyLayoutMutableSet of TyV * LayoutFieldNameId list * Data
        | TyFailwith of Ty * Data
        | TyApply of TyV * Data
        | TyConv of Ty * Data
        | TySizeOf of Ty
        | TyArrayLiteral of Ty * Data list
        | TyArrayCreate of Ty * Data
        | TyArrayLength of Ty * Data
        | TyStringLength of Ty * Data
        | TyIf of cond: Data * tr: TypedBind [] * fl: TypedBind []
        | TyWhile of cond: JoinPointCall * TypedBind []
        | TyDo of TypedBind []
        | TyIndent of TypedBind []
        | TyJoinPoint of JoinPointCall
        | TyBackend of JpBodyOwnerIdentity * ConsedNode<RData [] * Ty [] * Ty> * Range
    

    /// ### UnionRewrite
    type UnionRewrite = UnionData of UnionTagId * Data | UnionBlockers of UnionTagId Set
    

    type TraceBudgetState = private {
        remaining : int
        truncated : bool
    }

    module TraceBudgetState =
        let create remaining = { remaining = max 0 remaining; truncated = false }
        let exhausted state = state.remaining <= 0 || state.truncated

    // Explicit execution contexts precede every environment that carries them.
    // Their representation is private to this compiler module, while the
    // RecursionTracker and BigStack modules below own construction/transitions.
    type RecursionContext = private {
        depth : int
        // Lazy and not chained: it was a SHA digest of the parent's digest on every term evaluation, and nothing
        // reads it on the hot path (a chained lazy value forced at depth would recurse as deep as the evaluation).
        lineage : Lazy<CompilerIdentityKernel.ContentDigest>
    }

    type RecursionEntry = private {
        prior : RecursionContext
        current : RecursionContext
        site : CompilerIdentityKernel.WorkSiteId
    }

    type BigStackExecutionContext = private {
        nesting : int
        recursion : RecursionContext
        joinEvidence : DiagJson.BigStackJoinEvidenceContext option
        contextRef : CompilerIdentityKernel.ContentDigest
    }

    /// Explicit evaluator traversal capabilities.  These paths are threaded
    /// through LangEnv so fiber migration cannot reset recursion authority.
    // `pathRef` is lazy: it digests the whole path, and computing it on every enter/exit made evaluation
    // quadratic in its depth (a contract compiled 8-16x slower than single-flight); nothing reads it on the hot path.
    type EvalNodePath = private {
        nodes : obj list
        pathRef : Lazy<CompilerIdentityKernel.ContentDigest>
    }

    type EvalKeyPath = private {
        // Plain strings with an occurrence count per key: interning each key and scanning the whole path
        // on every term evaluation cost O(depth) plus a global intern-table lookup (FRONTIER.md fix 39).
        keys : string list
        counts : Map<string, int>
        pathRef : Lazy<CompilerIdentityKernel.ContentDigest>
    }

    /// ### LangEnv
    type LangEnv = {
        trace : Trace
        traceBudget : TraceBudgetState
        recursion : RecursionContext
        bigStack : BigStackExecutionContext
        evalNodePath : EvalNodePath
        evalKeyPath : EvalKeyPath
        seq : ResizeArray<TypedBind>
        cse : System.Collections.Concurrent.ConcurrentDictionary<TypedOp, Data> list
        unions : Map<TyV, UnionRewrite>
        i : int ref
        env_global_type : Ty []
        env_global_term : Data []
        env_stack_type : Ty []
        env_stack_term : Data []
        backend : string ConsedNode
        globals : ResizeArray<string>
        globals_lock : obj
        globals_seen : System.Collections.Concurrent.ConcurrentDictionary<GlobalNameId, byte>
        join_point_method_key_names : System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<RData [] * Ty [] * Ty>, JpNameId>
        join_point_closure_key_names : System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<RData [] * Ty [] * Ty>, JpNameId>
        jp_method_stack : System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>
        jp_closure_stack : System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>
        jp_type_stack : System.Collections.Generic.HashSet<ConsedNode<Ty []>>
        }

    let private langEnvWithBigStack (childContext: BigStackExecutionContext) (s: LangEnv) : LangEnv =
        { s with
            bigStack = childContext
            recursion = childContext.recursion }

    let private evalNodeShapeTerm (x: E) =
        match x with
        | EFun _ -> "EFun" | EFun' _ -> "EFun'" | EForall _ -> "EForall" | EForall' _ -> "EForall'"
        | ERecursiveFun' _ -> "ERecursiveFun'" | ERecursiveForall' _ -> "ERecursiveForall'" | ERecursive _ -> "ERecursive" | EPatternRef _ -> "EPatternRef"
        | EJoinPoint _ -> "EJoinPoint" | EJoinPoint' _ -> "EJoinPoint'" | EB _ -> "EB" | EV _ -> "EV" | ELit _ -> "ELit" | EDefaultLit _ -> "EDefaultLit"
        | ESymbol _ -> "ESymbol" | EType _ -> "EType" | EApply _ -> "EApply" | EArray _ -> "EArray" | ETypeApply _ -> "ETypeApply" | ERecBlock _ -> "ERecBlock"
        | ERecordWith _ -> "ERecordWith" | EModule _ -> "EModule" | EOp _ -> "EOp" | EPatternMiss _ -> "EPatternMiss" | ETypePatternMiss _ -> "ETypePatternMiss"
        | EAnnot _ -> "EAnnot" | EIfThenElse _ -> "EIfThenElse" | EIfThen _ -> "EIfThen" | EPair _ -> "EPair" | ESeq _ -> "ESeq" | EMutableSet _ -> "EMutableSet"
        | EReal _ -> "EReal" | EExists _ -> "EExists" | EMacro _ -> "EMacro" | EPrototypeApply _ -> "EPrototypeApply" | EPatternMemo _ -> "EPatternMemo" | ENominal _ -> "ENominal"
        | ELet _ -> "ELet" | EUnbox _ -> "EUnbox" | EExistsTest _ -> "EExistsTest" | EPairTest _ -> "EPairTest" | ESymbolTest _ -> "ESymbolTest"
        | ERecordTest _ -> "ERecordTest" | EAnnotTest _ -> "EAnnotTest" | ENominalTest _ -> "ENominalTest" | EUnitTest _ -> "EUnitTest" | ELitTest _ -> "ELitTest" | EDefaultLitTest _ -> "EDefaultLitTest" | ETypecase _ -> "ETypecase"

