    let private evalCell
        (kind: EvalWorklist.EvalKind)
        (shape: CompilerIdentityKernel.WorkShapeId)
        (nodeId: int)
        (site: CompilerIdentityKernel.WorkSiteId)
        (s: LangEnv) : EvalWorklist.ReplayCell =
        // MIGRATION: PartEvalResult.ty_to_data intentionally keeps seq = null
        // after partial evaluation.  Codegen may still force nominal type
        // application while TermCycleFuse is armed, so replay diagnostics must
        // describe that post-peval environment without dereferencing nullable
        // fields or allocating fake codegen state.
        let safeArrayLen (xs: 'a []) = if obj.ReferenceEquals(xs, null) then 0 else xs.Length
        let safeResizeCount (xs: ResizeArray<'a>) = if obj.ReferenceEquals(xs, null) then 0 else xs.Count
        let safeListLen (xs: 'a list) = if obj.ReferenceEquals(xs, null) then 0 else xs.Length
        let envGlobalTerm, envStackTerm, envGlobalType, envStackType, seqLen, cseDepth, traceDepth =
            if obj.ReferenceEquals(s, null) then
                0, 0, 0, 0, 0, 0, 0
            else
                safeArrayLen s.env_global_term,
                safeArrayLen s.env_stack_term,
                safeArrayLen s.env_global_type,
                safeArrayLen s.env_stack_type,
                safeResizeCount s.seq,
                safeListLen s.cse,
                safeListLen s.trace
        { kind = kind
          shape = shape
          nodeId = nodeId
          envGlobalTerm = envGlobalTerm
          envStackTerm = envStackTerm
          envGlobalType = envGlobalType
          envStackType = envStackType
          seqLen = seqLen
          cseDepth = cseDepth
          traceDepth = traceDepth
          site = site
          cursor = 0
          step = 0
          status = EvalWorklist.ReplayCellSemanticStatus EvalReplayValueStore.SemanticCellNew }
    

    /// ### show_ty
    let show_ty x =
        let maxDepth = 96
        let rec f depth prec x =
            if depth >= maxDepth then "…"
            else
                let p = p prec
                let next = depth + 1
                match x with
                | YVoid -> "void"
                | YB -> "()"
                | YLit x -> show_lit x
                | YPair(a,b) -> p 25 (sprintf "%s * %s" (f next 25 a) (f next 24 b))
                | YSymbol x -> sprintf ".%s" x
                | YTypeFunction _ -> p 0 (sprintf "? => ?")
                | YForall -> p 0 (sprintf "forall ?. ?")
                | YExists -> p 0 (sprintf "exists ?. ?")
                | YRecord l -> sprintf "{%s}" (l |> Map.toList |> List.map (fun ((_,k),v) -> sprintf "%s : %s" k (f next -1 v)) |> String.concat "; ")
                | YUnion l -> sprintf "{%s}" (l.Item.cases |> Map.toList |> List.map (fun ((_,k),v) -> sprintf "%s : %s" k (f next -1 v)) |> String.concat " | ")
                | YPrim x -> show_primt x
                | YArray a -> p 30 (sprintf "array_base %s" (f next 30 a))
                | YFun(a,b,FT_Vanilla) -> p 20 (sprintf "%s -> %s" (f next 20 a) (f next 19 b))
                | YFun(a,b,FT_Pointer) -> p 20 (sprintf "fptr (%s -> %s)" (f next 20 a) (f next 19 b))
                | YFun(a,b,FT_Closure) -> p 20 (sprintf "closure (%s -> %s)" (f next 20 a) (f next 19 b))
                | YMacro a -> p 30 (List.map (function TypeLit a | Type a -> f next -1 a | Text a -> a) a |> String.concat "")
                | YApply(a,b) -> p 30 (sprintf "%s %s" (f next 29 a) (f next 30 b))
                | YLayout(a,b) -> p 30 (sprintf "%s %s" (show_layout_type b) (f next 30 a))
                | YNominal x -> x.node.name
                | YMetavar _ -> "?"
        f 0 -1 x
    

    /// ### Type-class helpers for diagnostic validation
    /// Used to detect obvious cache collisions (e.g., returning i32 when function expected).
    type NominalCallableHintId =
        | NominalCallableFunctionHint
        | NominalCallableClosureHint
        | NominalCallableOther

    let private nominalCallableHintId (name:string) =
        let tokens =
            if String.IsNullOrWhiteSpace name then Set.empty
            else
                name.Split([|'|'; ':'; '@'; '/'; '('; ')'; '_'; '-'; ' '|], StringSplitOptions.RemoveEmptyEntries)
                |> Array.map (fun token -> token.ToLowerInvariant())
                |> Set.ofArray
        if Set.contains "fun" tokens || Set.contains "function" tokens then
            NominalCallableFunctionHint
        elif Set.contains "closure" tokens then
            NominalCallableClosureHint
        else
            NominalCallableOther

    let is_ty_callable ty =
        match ty with
        | YFun _ | YForall | YTypeFunction _ -> true
        | YLayout(inner, _) ->
            match inner with
            | YFun _ | YRecord _ -> true
            | _ -> false
        | YNominal n ->
            // Some nominals wrap functions.
            match nominalCallableHintId n.node.name with
            | NominalCallableFunctionHint
            | NominalCallableClosureHint -> true
            | NominalCallableOther -> false
        | _ -> false
    

    let is_ty_primitive ty =
        match ty with
        | YPrim _ | YLit _ -> true
        | _ -> false
    

    /// ### RetryTracker
    /// Retry state is an explicit capability.  No thread identity or scheduler
    /// worker is allowed to imply that a retry is active.
    module RetryTracker =
        type RetryScope = private | RetryScopeInactive
                                  | RetryScopeActive of depth:int * scopeRef:CompilerIdentityKernel.ContentDigest

        type RetryOutcome =
            | RetrySucceeded
            | RetryFailed

        type RetryStatistics = {
            attempts : int
            successes : int
            failures : int
        }

        let private gate = obj()
        let mutable private statistics = { attempts = 0; successes = 0; failures = 0 }

        let empty = RetryScopeInactive

        let isInRetry = function
            | RetryScopeInactive -> false
            | RetryScopeActive _ -> true

        let enterRetry scope =
            let depth =
                match scope with
                | RetryScopeInactive -> 1
                | RetryScopeActive(depth, _) -> depth + 1
            let scopeRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "retry-scope"
                    (string depth + "|attempt=" + string (statistics.attempts + 1))
            lock gate (fun () -> statistics <- { statistics with attempts = statistics.attempts + 1 })
            RetryScopeActive(depth, scopeRef)

        let exitRetry outcome scope =
            let next =
                match scope with
                | RetryScopeInactive -> RetryScopeInactive
                | RetryScopeActive(depth, _) when depth <= 1 -> RetryScopeInactive
                | RetryScopeActive(depth, scopeRef) -> RetryScopeActive(depth - 1, scopeRef)
            lock gate (fun () ->
                statistics <-
                    match outcome with
                    | RetrySucceeded -> { statistics with successes = statistics.successes + 1 }
                    | RetryFailed -> { statistics with failures = statistics.failures + 1 })
            next

        let snapshot () = lock gate (fun () -> statistics)

        let logIfActive scope =
            if isInRetry scope then
                let s = snapshot ()
                DiagSidecar.emit (FastRuntimeFormat.format "RetryTracker: attempts=%d success=%d fail=%d" [| box s.attempts; box s.successes; box s.failures |])
    

    /// ### DiagNN
    /// Small, online "neural-ish" helper for diagnostics: hashed embeddings + cosine similarity.
    /// Always enabled in MIGRATION+ for error pattern clustering. Lightweight and thread-safe.
    module DiagNN =
        open System
        open System.Collections.Concurrent
    

        let private dims = 64
    

        let enabled () = true  // MIGRATION: always on
    

        type DiagClusterKeyKind private () =
            static member InternedKindTag () = 0x150002u
        type private DiagClusterKeyId = CompilerIdentityKernel.InternedTextId<DiagClusterKeyKind>

        module private DiagClusterKeyIdOps =
            let create value : DiagClusterKeyId =
                CompilerIdentityKernel.InternedTextId.create<DiagClusterKeyKind> value
            let text (value:DiagClusterKeyId) = CompilerIdentityKernel.InternedTextIdOps.text value

        let private centroids = System.Collections.Concurrent.ConcurrentDictionary<DiagClusterKeyId, float []>()
        let private counts = System.Collections.Concurrent.ConcurrentDictionary<DiagClusterKeyId, int>()
    

        let private fnv1a32 (s: string) : uint32 =
            let mutable h = 2166136261u
            for i = 0 to s.Length - 1 do
                h <- (h ^^^ uint32 (int s.[i])) * 16777619u
            h
    

        let private embed (s: string) : float [] =
            let v = Array.zeroCreate<float> dims
            if String.IsNullOrEmpty s then v
            else
                // Simple tokenization; stable enough for clustering and similarity hints.
                let toks =
                    s.Split([|' '; '\t'; '\r'; '\n'; '|'; ','; ';'; '('; ')'; '['; ']'; '{'; '}'; '<'; '>'; ':'; '='; '\''; '"'|],
                            StringSplitOptions.RemoveEmptyEntries)
                let n = min toks.Length 512
                for i = 0 to n - 1 do
                    let t = toks.[i]
                    let h = fnv1a32 t
                    let idx = int (h % uint32 dims)
                    let sign = if (h &&& 1u) = 0u then 1.0 else -1.0
                    v.[idx] <- v.[idx] + sign
                // L2 normalize (avoid div0).
                let mutable norm = 0.0
                for i = 0 to dims - 1 do norm <- norm + v.[i] * v.[i]
                if norm > 0.0 then
                    let inv = 1.0 / sqrt norm
                    for i = 0 to dims - 1 do v.[i] <- v.[i] * inv
                v
    

        let private cosine (a: float []) (b: float []) : float =
            let mutable dot = 0.0
            let mutable i = 0
            while i < dims do
                dot <- dot + a.[i] * b.[i]
                i <- i + 1
            dot
    

        let record (clusterKey: string) (payload: string) : string option =
            if not (enabled ()) then None
            else
                try
                    let x = embed payload
                    let clusterId = DiagClusterKeyIdOps.create clusterKey
                    let c = counts.AddOrUpdate(clusterId, 1, (fun _ n -> n + 1))
                    let w = centroids.GetOrAdd(clusterId, (fun _ -> Array.zeroCreate<float> dims))
                    lock w (fun () ->
                        // Exponential-ish moving average; stable enough for hints.
                        let alpha = 1.0 / float c
                        for i = 0 to dims - 1 do
                            w.[i] <- w.[i] + alpha * (x.[i] - w.[i])
                    )
                    // Nearest neighbors among existing clusters (bounded scan; only when enabled).
                    let mutable best1 = ("", -1.0)
                    let mutable best2 = ("", -1.0)
                    let mutable best3 = ("", -1.0)
                    for kv in centroids do
                        let keyId = kv.Key
                        if keyId <> clusterId then
                            let k = DiagClusterKeyIdOps.text keyId
                            let s = cosine x kv.Value
                            if s > snd best1 then
                                best3 <- best2
                                best2 <- best1
                                best1 <- (k, s)
                            elif s > snd best2 then
                                best3 <- best2
                                best2 <- (k, s)
                            elif s > snd best3 then
                                best3 <- (k, s)
                    let fmt (k, s) =
                        if k = "" then ""
                        else sprintf "%s(%.2f)" k s
                    let near =
                        [ fmt best1; fmt best2; fmt best3 ]
                        |> List.filter (fun s -> s <> "")
                        |> String.concat ", "
                    Some (FastRuntimeFormat.format "cluster=%s count=%d near=[%s]" [| box clusterKey; box c; box near |])
                with _ ->
                    None
    

    /// ### CacheGeneration
    /// Global generation counter for cache invalidation in deep recursion scenarios.
    /// When cache corruption is detected (EJP0007/EJP0008), incrementing the generation
    /// marks all older entries as stale, enabling clean retry without full cache flush.
    module CacheGeneration =
        open System
        open System.Threading
    

        type GenerationChangeReasonKind private () =
            static member InternedKindTag () = 0x150003u
        type GenerationChangeReasonId = CompilerIdentityKernel.InternedTextId<GenerationChangeReasonKind>

        module GenerationChangeReasonIdOps =
            let create value : GenerationChangeReasonId =
                CompilerIdentityKernel.InternedTextId.create<GenerationChangeReasonKind> value

            let text (value:GenerationChangeReasonId) =
                CompilerIdentityKernel.InternedTextIdOps.text value

        type GenerationChange = {
            previousGeneration : int64
            currentGeneration : int64
            reason : GenerationChangeReasonId
            transitionRef : CompilerIdentityKernel.ContentDigest
        }

        type GenerationReasonSignalId =
            | GenerationReasonUnclassified
            | GenerationReasonReplayRootComplete
            | GenerationReasonRetry of DiagnosticClassifier.DiagnosticCodeId
            | GenerationReasonDeadIvarJpWait

        let generationReasonSignalText = function
            | GenerationReasonUnclassified -> "unclassified"
            | GenerationReasonReplayRootComplete -> "replay_root_complete"
            | GenerationReasonRetry code -> "retry:" + DiagnosticClassifier.codeIdText code
            | GenerationReasonDeadIvarJpWait -> "dead_ivar_jp_wait"

        type GenerationReasonLedgerEntry = private {
            generation : int64
            reason : GenerationChangeReasonId
            signal : GenerationReasonSignalId
            observedAt : DateTime
        }

        type GenerationEpoch = private {
            generation : int64
            changed : Hopac.IVar<GenerationChange>
        }

        let private generationEpochGate = obj()
        let mutable private generationEpoch = { generation = 0L; changed = Hopac.IVar() }
        let private lastInvalidationTime = ref DateTime.MinValue
        let private invalidationReasons = System.Collections.Concurrent.ConcurrentQueue<GenerationReasonLedgerEntry>()
    

        let mutable private invalidation_count = 0L
        let invalidationCount () = lock generationEpochGate (fun () -> invalidation_count)

        // The retry fallback and generation epoch are separate typed state machines.
        // Each has one serialized owner; no host atomic participates in cache identity
        // or in the decision to fall back to sequential evaluation.
        type private SequentialFallbackState =
            | SequentialFallbackDisabled
            | SequentialFallbackRequested of requestedAtGeneration:int64

        let private sequentialFallbackGate = obj()
        let mutable private sequentialFallbackState = SequentialFallbackDisabled
        // MIGRATION: allow subsystems to register cache-clear callbacks that run on invalidation.
        let private onInvalidate = System.Collections.Concurrent.ConcurrentBag<GenerationChangeReasonId -> unit>()
        let registerOnInvalidate (f: GenerationChangeReasonId -> unit) =
            onInvalidate.Add f

        let requestSequential () =
            let currentGeneration = lock generationEpochGate (fun () -> generationEpoch.generation)
            let changed =
                lock sequentialFallbackGate (fun () ->
                    match sequentialFallbackState with
                    | SequentialFallbackDisabled ->
                        sequentialFallbackState <- SequentialFallbackRequested currentGeneration
                        true
                    | SequentialFallbackRequested _ -> false)
            if changed then
                DiagSidecar.emit (sprintf "CacheGeneration.requestSequential: enabled gen=%d state=SequentialFallbackRequested" currentGeneration)

        let resetSequentialRequest () =
            let previous =
                lock sequentialFallbackGate (fun () ->
                    let previous = sequentialFallbackState
                    sequentialFallbackState <- SequentialFallbackDisabled
                    previous)
            match previous with
            | SequentialFallbackRequested requestedAtGeneration ->
                DiagSidecar.emit (sprintf "CacheGeneration.requestSequential: reset requested_gen=%d current_gen=%d state=SequentialFallbackDisabled" requestedAtGeneration (lock generationEpochGate (fun () -> generationEpoch.generation)))
            | SequentialFallbackDisabled -> ()

        let isSequentialRequested () =
            lock sequentialFallbackGate (fun () ->
                match sequentialFallbackState with
                | SequentialFallbackRequested _ -> true
                | SequentialFallbackDisabled -> false)
    

        /// Get current generation number
        let current () = lock generationEpochGate (fun () -> generationEpoch.generation)

        let generationChangeText (change: GenerationChange) =
            FastRuntimeFormat.format "GenerationChange(previous=%d|current=%d|reason=%s|ref=%s)" [| box change.previousGeneration; box change.currentGeneration; box (GenerationChangeReasonIdOps.text change.reason); box (CompilerIdentityKernel.ContentDigest.text change.transitionRef) |]

        let generationReasonLedgerEntryText (entry: GenerationReasonLedgerEntry) =
            FastRuntimeFormat.format "[gen=%d] %s @ %s" [| box entry.generation; box (GenerationChangeReasonIdOps.text entry.reason); box (entry.observedAt.ToString("HH:mm:ss.fff")) |]

        // A waiter subscribes to the exact epoch it armed against.  The cell is
        // fulfilled once when that epoch is superseded; no polling or queue stealing
        // is required to detect generation change.
        let watch expectedGeneration : Hopac.IVar<GenerationChange> =
            lock generationEpochGate (fun () ->
                if generationEpoch.generation = expectedGeneration then generationEpoch.changed
                else
                    let currentGeneration = generationEpoch.generation
                    let change =
                        { previousGeneration = expectedGeneration
                          currentGeneration = currentGeneration
                          reason = GenerationChangeReasonIdOps.create "generation_already_superseded_before_watch"
                          transitionRef = CompilerIdentityKernel.ContentDigest.ofText "generation-change" (sprintf "%d|%d|already" expectedGeneration currentGeneration) }
                    let cell = Hopac.IVar<GenerationChange>()
                    startHopacJob (Hopac.IVar.fill cell change)
                    cell)

        let superseded expectedGeneration (reasonId: GenerationChangeReasonId) =
            let currentGeneration = current()
            { previousGeneration = expectedGeneration
              currentGeneration = currentGeneration
              reason = reasonId
              transitionRef = CompilerIdentityKernel.ContentDigest.ofText "generation-change" (FastRuntimeFormat.format "%d|%d|%s" [| box expectedGeneration; box currentGeneration; box (GenerationChangeReasonIdOps.text reasonId) |]) }

        do Progress88.set_gen_provider current
    

        let private enqueueReason generation signal reasonId observedAt =
            invalidationReasons.Enqueue {
                generation = generation
                reason = reasonId
                signal = signal
                observedAt = observedAt
            }
            while invalidationReasons.Count > 32 do
                let mutable v = Unchecked.defaultof<GenerationReasonLedgerEntry>
                invalidationReasons.TryDequeue(&v) |> ignore

        /// Invalidate one generation transactionally.  The old epoch cell is filled
        /// before the new epoch is published, so every armed waiter observes either the
        /// completion it awaited or an explicit generation transition.
        let invalidateWithSignal (signal:GenerationReasonSignalId) (reasonId: GenerationChangeReasonId) =
            let reasonText = GenerationChangeReasonIdOps.text reasonId
            let previousEpoch, newGen, change =
                lock generationEpochGate (fun () ->
                    let previousEpoch = generationEpoch
                    let newGen = previousEpoch.generation + 1L
                    let transitionRef =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "generation-change"
                            (FastRuntimeFormat.format "%d|%d|%s" [| box previousEpoch.generation; box newGen; box reasonText |])
                    let change =
                        { previousGeneration = previousEpoch.generation
                          currentGeneration = newGen
                          reason = reasonId
                          transitionRef = transitionRef }
                    generationEpoch <- { generation = newGen; changed = Hopac.IVar() }
                    invalidation_count <- invalidation_count + 1L
                    previousEpoch, newGen, change)
            startHopacJob (Hopac.IVar.fill previousEpoch.changed change)
            let observedAt = DateTime.UtcNow
            lastInvalidationTime := observedAt
            enqueueReason newGen signal reasonId observedAt
            DiagSidecar.emit (sprintf "CacheGeneration.invalidate: %s" (generationChangeText change))
            try
                for cb in onInvalidate do
                    try cb reasonId with _ -> ()
            with _ -> ()
            newGen

        let invalidate (reasonId: GenerationChangeReasonId) =
            invalidateWithSignal GenerationReasonUnclassified reasonId

        /// Record a diagnostic reason without changing the cache generation.
        /// MIGRATION: jp_wait can close after a typed replay root-complete proof in the
        /// same build attempt.  The writer needs that proof in the reason ledger, but
        /// incrementing the generation here would turn success back into a retry.
        let noteReasonWithSignal (signal:GenerationReasonSignalId) (reasonId: GenerationChangeReasonId) =
            let gen = current ()
            let observedAt = DateTime.UtcNow
            enqueueReason gen signal reasonId observedAt
            DiagSidecar.emit (
                sprintf "CacheGeneration.noteReason: gen=%d signal=%s reason=%s"
                    gen
                    (generationReasonSignalText signal)
                    (GenerationChangeReasonIdOps.text reasonId))

        // Legacy noteReason callers are the replay-root handoff path.  New generic
        // diagnostics must use noteReasonWithSignal explicitly so control authority
        // never has to be reconstructed from rendered reason text.
        let noteReason (reasonId: GenerationChangeReasonId) =
            noteReasonWithSignal GenerationReasonReplayRootComplete reasonId

        /// Snapshot recent typed reason signals (most recent first), for control decisions.
        let reasonSignalsSnapshot (n: int) : GenerationReasonSignalId list =
            try
                invalidationReasons.ToArray()
                |> Array.rev
                |> (fun a -> if n <= 0 then [||] else a |> Array.truncate (min n a.Length))
                |> Array.map (fun entry -> entry.signal)
                |> Array.toList
            with _ -> []

        /// Snapshot recent invalidation reasons (most recent first), for diagnostics
        let reasonsSnapshot (n: int) : string list =
            try
                invalidationReasons.ToArray()
                |> Array.rev
                |> (fun a -> if n <= 0 then [||] else a |> Array.truncate (min n a.Length))
                |> Array.map generationReasonLedgerEntryText
                |> Array.toList
            with _ -> []
    

        /// Check if a generation is stale (older than current)
        let isStale (g: int64) = g < current ()
    

        /// Get recent invalidation reasons for diagnostics
        let getRecentReasons () =
            invalidationReasons.ToArray()
            |> Array.map generationReasonLedgerEntryText
            |> Array.toList
    

    /// ### RecursionTracker
    /// Recursion depth is an explicit capability.  Thread migration cannot reset
    /// it and a BigStack boundary must state exactly which depth it inherits.
    module RecursionTracker =

        let private diagnosticsGate = obj()
        let mutable private maxObserved = 0
        let private deepCallSites =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.WorkSiteId, int>()

        let root =
            { depth = 0
              lineage = lazy (CompilerIdentityKernel.ContentDigest.ofText "recursion-context" "root") }

        let currentDepth context = context.depth
        let observerDepthUnavailable = 0
        let isDeep context = context.depth > 100
        let isModeratelyDeep context = context.depth > 50

        let inheritDepth depth parent =
            { depth = max 0 depth
              lineage =
                lazy (
                    CompilerIdentityKernel.ContentDigest.ofText
                        "recursion-context-inherit"
                        ("depth=" + string parent.depth + "->" + string (max 0 depth))) }

        let enter (siteId:CompilerIdentityKernel.WorkSiteId) context =
            let depth = context.depth + 1
            let siteText = CompilerIdentityKernel.WorkSiteIdOps.text siteId
            let current =
                { depth = depth
                  lineage =
                    lazy (
                        CompilerIdentityKernel.ContentDigest.ofText
                            "recursion-context-enter"
                            ("site=" + siteText + "|depth=" + string depth)) }
            if depth > maxObserved then lock diagnosticsGate (fun () -> maxObserved <- max maxObserved depth)
            if depth > 50 then
                deepCallSites.AddOrUpdate(siteId, 1, (fun _ n -> n + 1)) |> ignore
            { prior = context; current = current; site = siteId }

        let context entry = entry.current
        let exit entry = entry.prior
        let getMaxObserved () = lock diagnosticsGate (fun () -> maxObserved)
        let getDeepSites () =
            deepCallSites.ToArray()
            |> Array.map (fun kv -> CompilerIdentityKernel.WorkSiteIdOps.text kv.Key, kv.Value)
            |> Array.toList
    
    
    
    
    





    /// BigStack: Executes thunks on dedicated threads with large stacks.
    /// Used for deep recursion when EnsureSufficientExecutionStack triggers.
    /// 
    ///
    /// CONFIGURATION (hardcoded SOTA defaults):
    /// - Stack size: 256MB per level (enough for 100K+ recursive calls)
    /// - Max nesting: 32 levels (8GB total address space)
    /// - Automatic depth inheritance across BigStack boundaries
    

    open type EvalReplayValueStore.SemanticStatusId
    open type EvalWorklist.FrameStatusId
    open type EvalWorklist.EvalKind

    let private frameSemanticStatusIs = EvalWorklist.frameSemanticStatusIs
    let private frameStatusIs = EvalWorklist.frameStatusIs
    let private semanticStatusToString = EvalWorklist.semanticStatusToString
    let private frameEvalKindId = EvalWorklist.frameEvalKindId

    module BigStack =
        open System
        open System.Threading
        open DiagJson
    


        let rootContext =
            { nesting = 0
              recursion = RecursionTracker.root
              joinEvidence = None
              contextRef = CompilerIdentityKernel.ContentDigest.ofText "bigstack-context" "root" }

        let private childContext tag nesting recursion joinEvidence parent =
            { nesting = nesting
              recursion = recursion
              joinEvidence = Some joinEvidence
              contextRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "bigstack-context-child"
                    (CompilerIdentityKernel.ContentDigest.text parent.contextRef
                     + "|tag=" + tag
                     + "|nest=" + string nesting
                     + "|join=" + CompilerIdentityKernel.ContentDigest.text (DiagJson.bigStackJoinEvidenceContextRef joinEvidence)) }

        let private terminalClosureEmitGate = obj()

        // MIGRATION: BigStack-side runtime counters for closure-latched rows.
        // These avoid relying on DiagJson.snapshotKindCount after jsonl recycling.
        let mutable private noRootBudgetBypassClosureEmitCount = 0L
        let mutable private noRootBudgetDispatchClosureEmitCount = 0L
        let mutable private parentReplayFloodCreditEmitCount = 0L

        let private terminalClosureEmitIsFull (ordinal: int64) =
            ordinal <= 2L || ordinal % 128L = 0L
    

        /// True if the explicit execution context is inside a BigStack boundary.
        let isActive context = context.nesting > 0
    

        // SOTA defaults - no environment variable overrides
        let private stackMb = 256         // baseline MB per stack level
        let private maxNestingLevels = 32 // generic: cap nesting; prefer larger first stacks (big stacks park parent frames)

        /// Stack headroom by address. The .NET probe (EnsureSufficientExecutionStack) only guarantees about
        /// 128 KB, and a BigStack spawn plus its parent's join loop sometimes needed more: the compiler died
        /// with a stack overflow inside `spawn` (ContentDigest.ofText) in ~1 of 3 runs of some contracts.
        /// Threads created with a known stack size (BigStack children, jp workers) record where their stack
        /// starts; the part used is the distance from there to a local of the current frame.
        module StackBudget =
            [<System.Runtime.InteropServices.DllImport("kernel32.dll")>]
            extern void private GetCurrentThreadStackLimits(nativeint& lowLimit, nativeint& highLimit)

            // Per thread: the lowest usable address and the stack's size (0 until known).
            let private low = new System.Threading.ThreadLocal<nativeint>()
            let private size = new System.Threading.ThreadLocal<int64>()
            let private queried = new System.Threading.ThreadLocal<bool>()

            /// Records the stack of a thread created with a known size (used where the OS cannot say).
            [<System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)>]
            let enter (stackBytes:int) =
                if not (System.OperatingSystem.IsWindows()) then
                    let mutable probe = 0uy
                    low.Value <- NativeInterop.NativePtr.toNativeInt &&probe - nativeint stackBytes
                    size.Value <- int64 stackBytes

            let private ensureKnown () =
                if not queried.Value then
                    queried.Value <- true
                    if System.OperatingSystem.IsWindows() then
                        let mutable lowLimit = 0n
                        let mutable highLimit = 0n
                        GetCurrentThreadStackLimits(&lowLimit, &highLimit)
                        if highLimit > lowLimit then
                            low.Value <- lowLimit
                            size.Value <- int64 (highLimit - lowLimit)

            /// Bytes left on this thread's stack, or -1 when its size is unknown.
            [<System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)>]
            let remaining () =
                ensureKnown ()
                if size.Value = 0L then -1L
                else
                    let mutable probe = 0uy
                    int64 (NativeInterop.NativePtr.toNativeInt &&probe - low.Value)

            /// Spawn once less than this is left: 2 MB, or a quarter of a smaller stack.
            let margin () = min (2L * 1024L * 1024L) (size.Value / 4L)

        let hasSufficientExecutionStack () =
            let remaining = StackBudget.remaining ()
            if remaining >= 0L && remaining < StackBudget.margin () then false
            else
                try
                    System.Runtime.CompilerServices.RuntimeHelpers.EnsureSufficientExecutionStack()
                    true
                with :? System.InsufficientExecutionStackException ->
                    false

        // MIGRATION: keep join policy gated by a closed tag DU.
        // We only fast-retry peval_main in forced sequential mode; term/ty/apply nested stacks
        // keep their existing root-complete / terminal-contract handoff rules.
        type BigStackJoinTagId =
            | BigStackPevalMain
            | BigStackTerm
            | BigStackTy
            | BigStackApply
            | BigStackJoinPoint
            | BigStackRegisterReplayTermGlobalFuse
            | BigStackRegisterReplayTermNormal
            | BigStackIfEmergency
            | BigStackBackendSwitchReplayValidate
            | BigStackRecordWithEarly
            | BigStackBackendSwitchValidate

        let private bigStackJoinTagText = function
            | BigStackPevalMain -> "peval_main"
            | BigStackTerm -> "term"
            | BigStackTy -> "ty"
            | BigStackApply -> "apply"
            | BigStackJoinPoint -> "jp"
            | BigStackRegisterReplayTermGlobalFuse -> "register_replay_term_global_fuse"
            | BigStackRegisterReplayTermNormal -> "register_replay_term_normal"
            | BigStackIfEmergency -> "if_emergency"
            | BigStackBackendSwitchReplayValidate -> "backend_switch_replay_validate"
            | BigStackRecordWithEarly -> "recordwith_early"
            | BigStackBackendSwitchValidate -> "backend_switch_validate"

        let private bigStackTerminalKindId = function
            | BigStackTy -> EvalWorklist.EvalTy
            | BigStackPevalMain
            | BigStackTerm
            | BigStackApply
            | BigStackJoinPoint
            | BigStackRegisterReplayTermGlobalFuse
            | BigStackRegisterReplayTermNormal
            | BigStackIfEmergency
            | BigStackBackendSwitchReplayValidate
            | BigStackRecordWithEarly
            | BigStackBackendSwitchValidate -> EvalWorklist.EvalTerm

        // MIGRATION: close BigStack terminal/HUD frontier phases as a DU.
        // MIGRATION improved frontier observability but still passed phase labels as
        // raw strings, making typo drift possible exactly at the diagnostic boundary.
        type BigStackFrontierPhaseId =
            | BigStackFrontierFastRetryGate
            | BigStackFrontierFastRetryRaise
            | BigStackFrontierPinnedSeen
            | BigStackFrontierQueueDrain
            | BigStackFrontierLateRaceQueueDrain
            | BigStackFrontierTerminalHandoff
            | BigStackFrontierOther of CompilerKernelV2.OperationalReasonId

        let private bigStackFrontierPhaseText = function
            | BigStackFrontierFastRetryGate -> "fast_retry_gate"
            | BigStackFrontierFastRetryRaise -> "fast_retry_raise"
            | BigStackFrontierPinnedSeen -> "pinned_seen"
            | BigStackFrontierQueueDrain -> "queue_drain"
            | BigStackFrontierLateRaceQueueDrain -> "late_race_queue_drain"
            | BigStackFrontierTerminalHandoff -> "terminal_handoff"
            | BigStackFrontierOther reasonId -> CompilerKernelV2.OperationalReasonIdOps.text reasonId

        // MIGRATION: close terminal frontier status, reasons and fast-failure usefulness as DUs.
        // Text classification is confined to this boundary; downstream closure decisions
        // consume nominal cases rather than substring predicates.
        type BigStackHudTerminalStatusId =
            | BigStackHudTerminalParentReplay
            | BigStackHudTerminalSemanticErrorTypeBlocked
            | BigStackHudTerminalStatusOther of CompilerKernelV2.OperationalReasonId

        let private bigStackHudTerminalStatusOfFrame (frame:EvalWorklist.Frame) =
            match EvalWorklist.frameSemanticStatusId frame with
            | EvalReplayValueStore.SemanticParentReplayStatusPreservedRepeatBlocked
            | EvalReplayValueStore.SemanticParentReplayCycleBreakPoisoned
            | EvalReplayValueStore.SemanticParentReplayCycleBreakPoisonSingleFlightDeferred ->
                BigStackHudTerminalParentReplay
            | EvalReplayValueStore.SemanticErrorTypeBlocked ->
                BigStackHudTerminalSemanticErrorTypeBlocked
            | _ ->
                BigStackHudTerminalStatusOther (CompilerKernelV2.OperationalReasonIdOps.create (EvalWorklist.frameStatusToString frame.status))

        let private bigStackHudTerminalStatusText = function
            | BigStackHudTerminalParentReplay -> "parent_replay"
            | BigStackHudTerminalSemanticErrorTypeBlocked -> "semantic_error_type_blocked"
            | BigStackHudTerminalStatusOther reasonId ->
                let text = CompilerKernelV2.OperationalReasonIdOps.text reasonId
                if System.String.IsNullOrEmpty text then "none" else "other"

        type BigStackTerminalReasonId =
            | BigStackTerminalReasonParentReplayStatusPreservedRepeat
            | BigStackTerminalReasonRuntimeRecordDynamicKeyRequired
            | BigStackTerminalReasonReplayDriverPoisonHardFail
            | BigStackTerminalReasonOpReplayDriverNull
            | BigStackTerminalReasonQueueSurgeParentPoison
            | BigStackTerminalReasonDynamicJoinRequired
            | BigStackTerminalReasonMissingAfterPrefetch
            | BigStackTerminalReasonCrossKindActiveReplayDriver
            | BigStackTerminalReasonCrossKindYieldThrash
            | BigStackTerminalReasonHardPoisonObligationCap
            | BigStackTerminalReasonReplayObligation
            | BigStackTerminalReasonTermErrorTypeMessageReady
            | BigStackTerminalReasonOther of CompilerKernelV2.OperationalReasonId

        let private bigStackTerminalReasonOfFacts (facts:Set<DiagnosticClassifier.DiagnosticFactId>) =
            if Set.contains DiagnosticClassifier.DiagnosticReplayParentStatusPreservedRepeat facts
               || Set.contains DiagnosticClassifier.DiagnosticReplayParentReplay facts then
                Some BigStackTerminalReasonParentReplayStatusPreservedRepeat
            elif Set.contains DiagnosticClassifier.DiagnosticReplayDynamicRecordKeyBridge facts
                 || Set.contains DiagnosticClassifier.DiagnosticRecordMapExpectedRecordFailure facts then
                Some BigStackTerminalReasonRuntimeRecordDynamicKeyRequired
            elif Set.contains DiagnosticClassifier.DiagnosticTerminalPoisonCascade facts then
                Some BigStackTerminalReasonQueueSurgeParentPoison
            elif Set.contains DiagnosticClassifier.DiagnosticReplayPoison facts then
                Some BigStackTerminalReasonReplayDriverPoisonHardFail
            elif Set.contains DiagnosticClassifier.DiagnosticReplayMissingAfterPrefetch facts then
                Some BigStackTerminalReasonMissingAfterPrefetch
            elif Set.contains DiagnosticClassifier.DiagnosticReplayHardPoisonObligation facts then
                Some BigStackTerminalReasonHardPoisonObligationCap
            elif Set.contains DiagnosticClassifier.DiagnosticReplayDynamicJoin facts
                 || Set.contains DiagnosticClassifier.DiagnosticDynamicJoinRuntimeDynTypecheck facts
                 || Set.contains DiagnosticClassifier.DiagnosticDynamicJoinFunctionBodyDynamicArg facts then
                Some BigStackTerminalReasonDynamicJoinRequired
            elif Set.contains DiagnosticClassifier.DiagnosticReplayIdleCrossKind facts
                 || Set.contains DiagnosticClassifier.DiagnosticReplayActiveTySidecar facts then
                Some BigStackTerminalReasonCrossKindActiveReplayDriver
            elif Set.contains DiagnosticClassifier.DiagnosticReplayTermReentryPrefetch facts then
                Some BigStackTerminalReasonTermErrorTypeMessageReady
            elif Set.contains DiagnosticClassifier.DiagnosticReplayPrefetch facts
                 || Set.contains DiagnosticClassifier.DiagnosticReplayCacheHandoff facts
                 || Set.contains DiagnosticClassifier.DiagnosticReplayCooperativeHandoff facts then
                Some BigStackTerminalReasonReplayObligation
            else None

        let private bigStackTerminalReasonOfFrame (frame:EvalWorklist.Frame) =
            match EvalWorklist.frameReasonSignalId frame with
            | Some (EvalWorklist.FrameReasonSignalParentReplayStatusPreservedRepeat _) ->
                BigStackTerminalReasonParentReplayStatusPreservedRepeat
            | Some (EvalWorklist.FrameReasonSignalCrossKind EvalWorklist.FrameCrossKindYieldThrash) ->
                BigStackTerminalReasonCrossKindYieldThrash
            | Some (EvalWorklist.FrameReasonSignalCrossKind EvalWorklist.FrameCrossKindYieldThrashHardPoisonStaleRetargetObligation)
            | Some (EvalWorklist.FrameReasonSignalCrossKind EvalWorklist.FrameCrossKindYieldThrashHardPoisonPostScheduleCap) ->
                BigStackTerminalReasonCrossKindYieldThrash
            | Some (EvalWorklist.FrameReasonSignalCrossKind _) ->
                BigStackTerminalReasonCrossKindActiveReplayDriver
            | Some EvalWorklist.FrameReasonSignalMissingAfterPrefetch ->
                BigStackTerminalReasonMissingAfterPrefetch
            | Some EvalWorklist.FrameReasonSignalOpReplayDriverNull ->
                BigStackTerminalReasonOpReplayDriverNull
            | Some (EvalWorklist.FrameReasonSignalReentrantP0FailClosed _) ->
                BigStackTerminalReasonOther frame.reason
            | Some (EvalWorklist.FrameReasonSignalDynamicJoin _) ->
                BigStackTerminalReasonDynamicJoinRequired
            | None ->
                match EvalWorklist.frameSemanticStatusId frame with
                | EvalReplayValueStore.SemanticParentReplayStatusPreservedRepeatBlocked
                | EvalReplayValueStore.SemanticParentReplayCycleBreakPoisoned
                | EvalReplayValueStore.SemanticParentReplayCycleBreakPoisonSingleFlightDeferred ->
                    BigStackTerminalReasonParentReplayStatusPreservedRepeat
                | EvalReplayValueStore.SemanticMissingAfterPrefetchBlocked ->
                    BigStackTerminalReasonMissingAfterPrefetch
                | EvalReplayValueStore.SemanticDynamicJoinApplyBlocked ->
                    BigStackTerminalReasonDynamicJoinRequired
                | EvalReplayValueStore.SemanticReplayObligationDeferred ->
                    BigStackTerminalReasonReplayObligation
                | _ ->
                    match bigStackTerminalReasonOfFacts (EvalWorklist.frameReasonFacts frame) with
                    | Some reasonId -> reasonId
                    | None -> BigStackTerminalReasonOther frame.reason

        let private bigStackTerminalReasonText = function
            | BigStackTerminalReasonParentReplayStatusPreservedRepeat -> "parent_replay_status_preserved_repeat"
            | BigStackTerminalReasonRuntimeRecordDynamicKeyRequired -> "runtime_record_dynamic_key_required"
            | BigStackTerminalReasonReplayDriverPoisonHardFail -> "replay_driver_poison_hard_fail"
            | BigStackTerminalReasonOpReplayDriverNull -> "op_replay_driver_null"
            | BigStackTerminalReasonQueueSurgeParentPoison -> "queue_surge_parent_poison"
            | BigStackTerminalReasonDynamicJoinRequired -> "dynamic_join_required"
            | BigStackTerminalReasonMissingAfterPrefetch -> "missing_after_prefetch_blocked"
            | BigStackTerminalReasonCrossKindActiveReplayDriver -> "cross_kind_active_replay_driver"
            | BigStackTerminalReasonCrossKindYieldThrash -> "cross_kind_yield_thrash"
            | BigStackTerminalReasonHardPoisonObligationCap -> "hard_poison_obligation_cap"
            | BigStackTerminalReasonReplayObligation -> "replay_obligation"
            | BigStackTerminalReasonTermErrorTypeMessageReady -> "term_error_type_message_ready"
            | BigStackTerminalReasonOther reasonId ->
                let text = CompilerKernelV2.OperationalReasonIdOps.text reasonId
                if System.String.IsNullOrEmpty text then "none"
                else
                    let compact = text.Replace("\r", " ").Replace("\n", " ").Replace("\t", " ")
                    if compact.Length > 96 then "other:" + compact.Substring(0, 96)
                    else "other:" + compact

        type BigStackTerminalReasonSignalId =
            | BigStackTerminalReasonSignalParentReplayStatusPreservedRepeat
            | BigStackTerminalReasonSignalDeferredChildCell
            | BigStackTerminalReasonSignalParentContinuationCycle
            | BigStackTerminalReasonSignalParentContinuationReady
            | BigStackTerminalReasonSignalSingleFlightBusyCrossKindCycleBreak
            | BigStackTerminalReasonSignalCrossKindActiveReplayDriver
            | BigStackTerminalReasonSignalCrossKindYieldThrash
            | BigStackTerminalReasonSignalParentReplay
            | BigStackTerminalReasonSignalTermReplayDriver
            | BigStackTerminalReasonSignalCrossKind
            | BigStackTerminalReasonSignalSidecar
            | BigStackTerminalReasonSignalAppRootBase16FinalizationSelfLoop
            | BigStackTerminalReasonSignalHardPoison
            | BigStackTerminalReasonSignalHardPoisonObligationCap
            | BigStackTerminalReasonSignalTerminalPoisonCascade
            | BigStackTerminalReasonSignalDynamicJoinRequired
            | BigStackTerminalReasonSignalCycleBreak

        type BigStackTerminalReasonAtomFamilyId =
            | BigStackTerminalReasonAtomParentReplay
            | BigStackTerminalReasonAtomTermReplayDriver
            | BigStackTerminalReasonAtomCrossKind
            | BigStackTerminalReasonAtomSidecar
            | BigStackTerminalReasonAtomHardPoison
            | BigStackTerminalReasonAtomCycleBreak

        let private bigStackTerminalReasonAtomFamilies (atom:string) =
            let segments =
                if System.String.IsNullOrWhiteSpace atom then [||]
                else atom.Split([| '_' |], System.StringSplitOptions.RemoveEmptyEntries)
            let begins (expected:string array) =
                segments.Length >= expected.Length
                && (expected |> Array.mapi (fun index segment -> segments.[index] = segment) |> Array.forall id)
            let ends (expected:string array) =
                let offset = segments.Length - expected.Length
                offset >= 0
                && (expected |> Array.mapi (fun index segment -> segments.[offset + index] = segment) |> Array.forall id)
            [ if begins [| "parent"; "replay" |] then BigStackTerminalReasonAtomParentReplay
              if begins [| "term"; "replay"; "driver" |] then BigStackTerminalReasonAtomTermReplayDriver
              if begins [| "cross"; "kind" |] then BigStackTerminalReasonAtomCrossKind
              if begins [| "sidecar" |]
                 || begins [| "active"; "ty"; "sidecar" |]
                 || begins [| "ty"; "sidecar" |] then BigStackTerminalReasonAtomSidecar
              if begins [| "hard"; "poison" |] then BigStackTerminalReasonAtomHardPoison
              if begins [| "cycle"; "break" |]
                 || ends [| "cycle"; "break" |]
                 || ends [| "cycle"; "break"; "poison" |]
                 || ends [| "cycle"; "break"; "poisoned" |] then BigStackTerminalReasonAtomCycleBreak ]
            |> Set.ofList

        let private bigStackTerminalReasonSignals (reason: string) =
            let safe = if System.String.IsNullOrEmpty reason then "" else reason
            let atoms =
                safe.Split(
                    [| '|'; ':'; ';'; ','; ' '; '='; '['; ']'; '('; ')' |],
                    System.StringSplitOptions.RemoveEmptyEntries)
                |> Set.ofArray
            let has atom = Set.contains atom atoms
            let families =
                atoms
                |> Seq.collect (bigStackTerminalReasonAtomFamilies >> Set.toSeq)
                |> Set.ofSeq
            let hasFamily family = Set.contains family families
            [ if has "parent_replay_status_preserved_repeat" then BigStackTerminalReasonSignalParentReplayStatusPreservedRepeat
              if has "deferred_child_cell" then BigStackTerminalReasonSignalDeferredChildCell
              if has "parent_continuation_cycle" then BigStackTerminalReasonSignalParentContinuationCycle
              if has "parent_continuation_ready" then BigStackTerminalReasonSignalParentContinuationReady
              if has "single_flight_busy_cross_kind_cycle_break" then BigStackTerminalReasonSignalSingleFlightBusyCrossKindCycleBreak
              if has "cross_kind_active_replay_driver" then BigStackTerminalReasonSignalCrossKindActiveReplayDriver
              if has "cross_kind_yield_thrash" then BigStackTerminalReasonSignalCrossKindYieldThrash
              if hasFamily BigStackTerminalReasonAtomParentReplay then BigStackTerminalReasonSignalParentReplay
              if hasFamily BigStackTerminalReasonAtomTermReplayDriver then BigStackTerminalReasonSignalTermReplayDriver
              if hasFamily BigStackTerminalReasonAtomCrossKind then BigStackTerminalReasonSignalCrossKind
              if hasFamily BigStackTerminalReasonAtomSidecar then BigStackTerminalReasonSignalSidecar
              if has "app_root_base16_root_witness_finalization_self_loop" then BigStackTerminalReasonSignalAppRootBase16FinalizationSelfLoop
              if hasFamily BigStackTerminalReasonAtomHardPoison || has "replay_driver_poison_hard_fail" then BigStackTerminalReasonSignalHardPoison
              if has "hard_poison_obligation_cap" then BigStackTerminalReasonSignalHardPoisonObligationCap
              if has "terminal_poison_cascade" then BigStackTerminalReasonSignalTerminalPoisonCascade
              if has "dynamic_arg_join_required" || has "dynamic_join" then BigStackTerminalReasonSignalDynamicJoinRequired
              if hasFamily BigStackTerminalReasonAtomCycleBreak then BigStackTerminalReasonSignalCycleBreak ]
            |> Set.ofList

        let private bigStackTerminalReasonSignalsForFrame (frame:EvalWorklist.Frame) =
            let typedSignals =
                match EvalWorklist.frameReasonSignalId frame with
                | Some (EvalWorklist.FrameReasonSignalParentReplayStatusPreservedRepeat _) ->
                    Set.ofList [ BigStackTerminalReasonSignalParentReplayStatusPreservedRepeat; BigStackTerminalReasonSignalParentReplay ]
                | Some (EvalWorklist.FrameReasonSignalCrossKind EvalWorklist.FrameCrossKindYieldThrash) ->
                    Set.ofList [ BigStackTerminalReasonSignalCrossKindActiveReplayDriver; BigStackTerminalReasonSignalCrossKindYieldThrash; BigStackTerminalReasonSignalCrossKind ]
                | Some (EvalWorklist.FrameReasonSignalCrossKind EvalWorklist.FrameCrossKindYieldThrashHardPoisonStaleRetargetObligation)
                | Some (EvalWorklist.FrameReasonSignalCrossKind EvalWorklist.FrameCrossKindYieldThrashHardPoisonPostScheduleCap) ->
                    Set.ofList [ BigStackTerminalReasonSignalCrossKindActiveReplayDriver; BigStackTerminalReasonSignalCrossKindYieldThrash; BigStackTerminalReasonSignalCrossKind; BigStackTerminalReasonSignalHardPoison ]
                | Some (EvalWorklist.FrameReasonSignalCrossKind _) ->
                    Set.ofList [ BigStackTerminalReasonSignalCrossKindActiveReplayDriver; BigStackTerminalReasonSignalCrossKind ]
                | Some (EvalWorklist.FrameReasonSignalDynamicJoin _) ->
                    Set.singleton BigStackTerminalReasonSignalDynamicJoinRequired
                | Some EvalWorklist.FrameReasonSignalMissingAfterPrefetch
                | Some EvalWorklist.FrameReasonSignalOpReplayDriverNull
                | Some (EvalWorklist.FrameReasonSignalReentrantP0FailClosed _)
                | None -> Set.empty
            if not (Set.isEmpty typedSignals) then typedSignals
            else
                match EvalWorklist.frameSemanticStatusId frame with
                | EvalReplayValueStore.SemanticParentReplayStatusPreservedRepeatBlocked ->
                    Set.ofList [ BigStackTerminalReasonSignalParentReplayStatusPreservedRepeat; BigStackTerminalReasonSignalParentReplay ]
                | EvalReplayValueStore.SemanticParentReplayCycleBreakPoisoned
                | EvalReplayValueStore.SemanticParentReplayCycleBreakPoisonSingleFlightDeferred ->
                    Set.ofList [ BigStackTerminalReasonSignalParentReplay; BigStackTerminalReasonSignalCycleBreak ]
                | EvalReplayValueStore.SemanticParentContinuationCycleBlocked
                | EvalReplayValueStore.SemanticParentContinuationCycleDeferred ->
                    Set.singleton BigStackTerminalReasonSignalParentContinuationCycle
                | EvalReplayValueStore.SemanticParentContinuationReady ->
                    Set.singleton BigStackTerminalReasonSignalParentContinuationReady
                | _ ->
                    bigStackTerminalReasonSignals (EvalWorklist.frameReasonToString frame.reason)

        let private bigStackTerminalReasonSignalPresent signal signals =
            Set.contains signal signals

        type BigStackFastFailureUsefulnessId =
            | BigStackFastFailureUnclassified
            | BigStackFastFailureUsefulFrontierPinned
            | BigStackFastFailureUsefulDynamicBridgeLocalized
            | BigStackFastFailureUsefulPoisonTailBounded
            | BigStackFastFailureUsefulParentReplayPoisonHandoff
            | BigStackFastFailureLowInfoNoAuthority

        let private bigStackFastFailureUsefulnessText = function
            | BigStackFastFailureUnclassified -> "unclassified"
            | BigStackFastFailureUsefulFrontierPinned -> "useful_frontier_pinned"
            | BigStackFastFailureUsefulDynamicBridgeLocalized -> "useful_dynamic_bridge_localized"
            | BigStackFastFailureUsefulPoisonTailBounded -> "useful_poison_tail_bounded"
            | BigStackFastFailureUsefulParentReplayPoisonHandoff -> "useful_parent_replay_poison_handoff"
            | BigStackFastFailureLowInfoNoAuthority -> "low_info_no_authority"

        // MIGRATION: a typed gate separates the old q>0 deferred-child bridge from the
        // MIGRATION frontier: q/a/p drained, write witness present, but parent-replay
        // cycle-break poison still wins and the heartbeat eventually aborts.  This gate
        // lets the bridge fire in that specific write-witness tail without treating
        // arbitrary poison as success.
        type BigStackParentContinuationPhase2StatusId =
            | BigStackParentContinuationPhase2StatusDeferred
            | BigStackParentContinuationPhase2StatusReplayCycleBreakPoisoned
            | BigStackParentContinuationPhase2StatusReplayPreservedRepeatBlocked
            | BigStackParentContinuationPhase2StatusOther

        let private bigStackParentContinuationPhase2StatusId (statusId: EvalReplayValueStore.SemanticStatusId) =
            match statusId with
            | SemanticParentContinuationCycleDeferred ->
                BigStackParentContinuationPhase2StatusDeferred
            | SemanticParentReplayCycleBreakPoisoned ->
                BigStackParentContinuationPhase2StatusReplayCycleBreakPoisoned
            | SemanticParentReplayStatusPreservedRepeatBlocked ->
                BigStackParentContinuationPhase2StatusReplayPreservedRepeatBlocked
            | _ ->
                BigStackParentContinuationPhase2StatusOther

        type BigStackParentContinuationPhase2GateId =
            | BigStackParentContinuationPhase2GateClosed
            | BigStackParentContinuationPhase2PendingDeferredTail
            | BigStackParentContinuationPhase2QueueDrainedWriteWitnessTail
            | BigStackParentContinuationPhase2ActiveWriteWitnessTail

        let private bigStackParentContinuationPhase2GateText = function
            | BigStackParentContinuationPhase2GateClosed -> "closed"
            | BigStackParentContinuationPhase2PendingDeferredTail -> "pending_deferred_tail"
            | BigStackParentContinuationPhase2QueueDrainedWriteWitnessTail -> "queue_drained_write_witness_tail"
            | BigStackParentContinuationPhase2ActiveWriteWitnessTail -> "active_write_witness_tail"

        let private bigStackParentContinuationPhase2GateShouldBridge = function
            | BigStackParentContinuationPhase2GateClosed -> false
            | _ -> true

        let private bigStackParentContinuationPhase2GateFor
            statusId
            reasonSignals
            pendingCount
            queueDepth
            activeDepth
            replayComplete
            writeWitness =
            let statusCandidate =
                match statusId with
                | BigStackParentContinuationPhase2StatusDeferred
                | BigStackParentContinuationPhase2StatusReplayCycleBreakPoisoned
                | BigStackParentContinuationPhase2StatusReplayPreservedRepeatBlocked -> true
                | BigStackParentContinuationPhase2StatusOther -> false
            let reasonCandidate =
                [ BigStackTerminalReasonSignalDeferredChildCell
                  BigStackTerminalReasonSignalParentContinuationCycle
                  BigStackTerminalReasonSignalParentReplayStatusPreservedRepeat
                  BigStackTerminalReasonSignalParentContinuationReady
                  BigStackTerminalReasonSignalSingleFlightBusyCrossKindCycleBreak ]
                |> List.exists (fun signal -> bigStackTerminalReasonSignalPresent signal reasonSignals)
            let statusReplayCyclePoisoned =
                statusId = BigStackParentContinuationPhase2StatusReplayCycleBreakPoisoned
            if not statusCandidate || not reasonCandidate || replayComplete then
                BigStackParentContinuationPhase2GateClosed
            elif pendingCount > 0 && pendingCount <= 3 && queueDepth <= 8 && activeDepth = 0 then
                BigStackParentContinuationPhase2PendingDeferredTail
            elif pendingCount = 0
                 && queueDepth <= 16
                 && activeDepth = 0
                 && writeWitness
                 && statusReplayCyclePoisoned then
                BigStackParentContinuationPhase2QueueDrainedWriteWitnessTail
            elif pendingCount = 0
                 && queueDepth <= 8
                 && activeDepth <= 4
                 && writeWitness
                 && statusReplayCyclePoisoned then
                BigStackParentContinuationPhase2ActiveWriteWitnessTail
            else
                BigStackParentContinuationPhase2GateClosed

        // MIGRATION: split explicit parent-replay poison handoff from final failure.
        // Runtime evidence proved the terminal handoff is now reached, but it still raised
        // while active replay/root witnesses were live. Keep the terminal authoritative,
        // but give a typed post-handoff grace window before surfacing EJP0021.
        type BigStackExplicitParentReplayPoisonHandoffActionId =
            | BigStackExplicitParentReplayPoisonSurface
            | BigStackExplicitParentReplayPoisonDeferRecentRootOrReplayProgress
            | BigStackExplicitParentReplayPoisonDeferDeferredTypeHoleSweep
            | BigStackExplicitParentReplayPoisonDeferLiveUnfinishedTail
            | BigStackExplicitParentReplayPoisonDeferActiveTail
            | BigStackExplicitParentReplayPoisonDeferRootWitness
            | BigStackExplicitParentReplayPoisonDeferDynamicBridge
            | BigStackExplicitParentReplayPoisonDeferReplayCompleteness
            | BigStackExplicitParentReplayPoisonDeferRootAuthority

        let private bigStackExplicitParentReplayPoisonHandoffActionText = function
            | BigStackExplicitParentReplayPoisonSurface -> "surface_ejp0021"
            | BigStackExplicitParentReplayPoisonDeferRecentRootOrReplayProgress -> "defer_recent_root_or_replay_progress_tail"
            | BigStackExplicitParentReplayPoisonDeferDeferredTypeHoleSweep -> "defer_deferred_type_hole_sweep_tail"
            | BigStackExplicitParentReplayPoisonDeferLiveUnfinishedTail -> "defer_live_unfinished_tail"
            | BigStackExplicitParentReplayPoisonDeferActiveTail -> "defer_active_tail"
            | BigStackExplicitParentReplayPoisonDeferRootWitness -> "defer_root_witness_tail"
            | BigStackExplicitParentReplayPoisonDeferDynamicBridge -> "defer_dynamic_bridge_tail"
            | BigStackExplicitParentReplayPoisonDeferReplayCompleteness -> "defer_replay_completeness_tail"
            | BigStackExplicitParentReplayPoisonDeferRootAuthority -> "defer_root_authority_tail"

        let private bigStackExplicitParentReplayPoisonHandoffTickReason = function
            | BigStackExplicitParentReplayPoisonSurface -> EvalWorklist.ReplayTickReasonParentReplayPoisonSurface
            | BigStackExplicitParentReplayPoisonDeferRecentRootOrReplayProgress -> EvalWorklist.ReplayTickReasonParentReplayPoisonDeferRecentRootOrReplayProgress
            | BigStackExplicitParentReplayPoisonDeferDeferredTypeHoleSweep -> EvalWorklist.ReplayTickReasonParentReplayPoisonDeferDeferredTypeHoleSweep
            | BigStackExplicitParentReplayPoisonDeferLiveUnfinishedTail -> EvalWorklist.ReplayTickReasonParentReplayPoisonDeferLiveUnfinishedTail
            | BigStackExplicitParentReplayPoisonDeferActiveTail -> EvalWorklist.ReplayTickReasonParentReplayPoisonDeferActiveTail
            | BigStackExplicitParentReplayPoisonDeferRootWitness -> EvalWorklist.ReplayTickReasonParentReplayPoisonDeferRootWitness
            | BigStackExplicitParentReplayPoisonDeferDynamicBridge -> EvalWorklist.ReplayTickReasonParentReplayPoisonDeferDynamicBridge
            | BigStackExplicitParentReplayPoisonDeferReplayCompleteness -> EvalWorklist.ReplayTickReasonParentReplayPoisonDeferReplayCompleteness
            | BigStackExplicitParentReplayPoisonDeferRootAuthority -> EvalWorklist.ReplayTickReasonParentReplayPoisonDeferRootAuthority

        type BigStackParentReplayPendingZeroPhysicalTailDecisionId =
            | BigStackParentReplayPendingZeroPhysicalTailNone
            | BigStackParentReplayPendingZeroPhysicalTailDrainLiveTail
            | BigStackParentReplayPendingZeroPhysicalTailObserveNoLiveTail

        let private bigStackParentReplayPendingZeroPhysicalTailDecisionText = function
            | BigStackParentReplayPendingZeroPhysicalTailNone -> "none"
            | BigStackParentReplayPendingZeroPhysicalTailDrainLiveTail -> "drain_pending_zero_physical_tail"
            | BigStackParentReplayPendingZeroPhysicalTailObserveNoLiveTail -> "observe_pending_zero_no_live_tail"

        let private bigStackParentReplayPendingZeroPhysicalTailDecisionFor pendingZeroNoWriter physicalLiveTail =
            if pendingZeroNoWriter && physicalLiveTail then BigStackParentReplayPendingZeroPhysicalTailDrainLiveTail
            elif pendingZeroNoWriter then BigStackParentReplayPendingZeroPhysicalTailObserveNoLiveTail
            else BigStackParentReplayPendingZeroPhysicalTailNone

        type BigStackParentReplayRecentProgressCreditId =
            | BigStackParentReplayRecentProgressCreditOpen
            | BigStackParentReplayRecentProgressCreditExhaustedByClearCap
            | BigStackParentReplayRecentProgressCreditExhaustedByTerminalFlood
            | BigStackParentReplayRecentProgressCreditExhaustedByPhase2Attempt

        let private bigStackParentReplayRecentProgressCreditText = function
            | BigStackParentReplayRecentProgressCreditOpen -> "open"
            | BigStackParentReplayRecentProgressCreditExhaustedByClearCap -> "exhausted_by_clear_cap"
            | BigStackParentReplayRecentProgressCreditExhaustedByTerminalFlood -> "exhausted_by_terminal_flood"
            | BigStackParentReplayRecentProgressCreditExhaustedByPhase2Attempt -> "exhausted_by_phase2_attempt"

        let private bigStackParentReplayRecentProgressCreditFor postHandoffDeferrals recentProgressClears terminalFloodCount phase2BridgeAttempts =
            if phase2BridgeAttempts > 0 && recentProgressClears >= 2 then
                BigStackParentReplayRecentProgressCreditExhaustedByPhase2Attempt
            elif terminalFloodCount >= 96 then
                BigStackParentReplayRecentProgressCreditExhaustedByTerminalFlood
            elif postHandoffDeferrals + recentProgressClears >= 8 then
                BigStackParentReplayRecentProgressCreditExhaustedByClearCap
            else
                BigStackParentReplayRecentProgressCreditOpen

        let private bigStackParentReplayRecentProgressCreditAllowsClear = function
            | BigStackParentReplayRecentProgressCreditOpen -> true
            | _ -> false

        // MIGRATION: terminal-flood is a useful anti-livelock signal, but MIGRATION proved it
        // can outrank a still-live JP parent poison frontier: EJP0014 selected rank83 while
        // pending=2, active=4, root_progress=21 and the typed retry gate had just fired.
        // Keep this as a closed guard so terminal_flood_count>=96 cannot silently erase
        // pending+active JP tail authority.
        type BigStackParentReplayTerminalFloodCreditGuardId =
            | BigStackParentReplayTerminalFloodCreditNoOverride
            | BigStackParentReplayTerminalFloodCreditProtectedByPendingActiveJpTail
            | BigStackParentReplayTerminalFloodCreditProtectedByMaterialLiveTail
            | BigStackParentReplayTerminalFloodCreditExpiredCooperativeHandoffLiveTail

        let private bigStackParentReplayTerminalFloodCreditGuardText = function
            | BigStackParentReplayTerminalFloodCreditNoOverride -> "no_override"
            | BigStackParentReplayTerminalFloodCreditProtectedByPendingActiveJpTail -> "protected_by_pending_active_jp_tail"
            | BigStackParentReplayTerminalFloodCreditProtectedByMaterialLiveTail -> "protected_by_material_live_tail"
            | BigStackParentReplayTerminalFloodCreditExpiredCooperativeHandoffLiveTail -> "expired_cooperative_handoff_live_tail"

        let private bigStackParentReplayTerminalFloodCreditGuardFor statusId reason pendingCount queueDepth activeDepth rootProgress replayComplete writeWitness terminalFloodCount jpRetryCount =
            let materialLiveParentReplayTail =
                statusId = SemanticParentReplayCycleBreakPoisoned
                && reason = BigStackTerminalReasonParentReplayStatusPreservedRepeat
                && not replayComplete
                && not writeWitness
                && pendingCount > 0
                && activeDepth > 0
                && queueDepth <= 64
                && rootProgress > 0
                && terminalFloodCount >= 96
            let cooperativeHandoffTailExpired =
                // MIGRATION: MIGRATION proved semantic-stale-retarget can pierce, but the BigStack
                // parent-replay terminal flood guard still kept a tiny cooperative_handoff tail alive
                // as material work.  When there is no JP retry, no writer/replay completion and the
                // terminal flood is already deep, this is no longer semantic progress: it is a typed
                // fail-closed handoff boundary.
                materialLiveParentReplayTail
                && jpRetryCount <= 0
                && terminalFloodCount >= 128
                && pendingCount <= 2
                && queueDepth <= 5
                && activeDepth <= 4
            if cooperativeHandoffTailExpired then
                BigStackParentReplayTerminalFloodCreditExpiredCooperativeHandoffLiveTail
            elif materialLiveParentReplayTail && jpRetryCount > 0 then
                BigStackParentReplayTerminalFloodCreditProtectedByPendingActiveJpTail
            elif materialLiveParentReplayTail then
                BigStackParentReplayTerminalFloodCreditProtectedByMaterialLiveTail
            else
                BigStackParentReplayTerminalFloodCreditNoOverride

        let private bigStackParentReplayTerminalFloodCreditGuardAllowsClear = function
            | BigStackParentReplayTerminalFloodCreditProtectedByPendingActiveJpTail -> true
            | BigStackParentReplayTerminalFloodCreditProtectedByMaterialLiveTail -> true
            | BigStackParentReplayTerminalFloodCreditExpiredCooperativeHandoffLiveTail -> false
            | BigStackParentReplayTerminalFloodCreditNoOverride -> false

        type BigStackDynamicJoinDeferredFloodId =
            | BigStackDynamicJoinDeferredFloodNotMature
            | BigStackDynamicJoinDeferredFloodProtectedPendingActiveBridge
            | BigStackDynamicJoinDeferredFloodCapExhausted
            | BigStackDynamicJoinDeferredFloodRepeatedLiveTail
            | BigStackDynamicJoinDeferredFloodWaitedLiveTail

        let private bigStackDynamicJoinDeferredFloodText = function
            | BigStackDynamicJoinDeferredFloodNotMature -> "not_mature"
            | BigStackDynamicJoinDeferredFloodProtectedPendingActiveBridge -> "protected_pending_active_bridge"
            | BigStackDynamicJoinDeferredFloodCapExhausted -> "cap_exhausted"
            | BigStackDynamicJoinDeferredFloodRepeatedLiveTail -> "repeated_live_tail"
            | BigStackDynamicJoinDeferredFloodWaitedLiveTail -> "waited_live_tail"

        let private bigStackDynamicJoinDeferredFloodFor statusId deferredCount terminalAge pendingCount queueDepth activeDepth recentReplayDelta recentRootDelta recentTerminalDelta rootWitnessActivity =
            if statusId = SemanticDynamicJoinApplyBlocked then
                // MIGRATION: 1379 showed terminal_age can reset while the same rank-92
                // dynamic-join blocker keeps being deferred.  The run-level deferral count
                // and small active-tail shape are therefore authority to stop treating live
                // replay as a fresh semantic witness.
                if pendingCount > 0 && activeDepth > 0 && recentReplayDelta >= 32L && rootWitnessActivity > 0 && deferredCount < 96 then
                    BigStackDynamicJoinDeferredFloodProtectedPendingActiveBridge
                elif deferredCount >= 24 && queueDepth <= 128 && activeDepth <= 4 then
                    BigStackDynamicJoinDeferredFloodRepeatedLiveTail
                elif deferredCount >= 12 && terminalAge >= 1000 && queueDepth <= 128 && activeDepth <= 4 && recentRootDelta <= 0L then
                    BigStackDynamicJoinDeferredFloodWaitedLiveTail
                elif deferredCount >= 6
                     && terminalAge >= 4000
                     && queueDepth <= 64
                     && activeDepth <= 4
                     && recentRootDelta <= 0L
                     && recentTerminalDelta <= 1L then
                    BigStackDynamicJoinDeferredFloodCapExhausted
                else
                    BigStackDynamicJoinDeferredFloodNotMature
            else
                BigStackDynamicJoinDeferredFloodNotMature

        let private bigStackDynamicJoinDeferredFloodShouldSurface = function
            | BigStackDynamicJoinDeferredFloodCapExhausted
            | BigStackDynamicJoinDeferredFloodRepeatedLiveTail
            | BigStackDynamicJoinDeferredFloodWaitedLiveTail -> true
            | BigStackDynamicJoinDeferredFloodNotMature
            | BigStackDynamicJoinDeferredFloodProtectedPendingActiveBridge -> false

        let private bigStackExplicitParentReplayPoisonHandoffDeferralCap = function
            | BigStackExplicitParentReplayPoisonSurface -> 0
            // MIGRATION: while root/replay authority is fresh, a rank-83 parent-repeat pin
            // is not yet a final poison contract. Keep a bounded diagnostic grace window and
            // expose the deferred-type-hole sweep seam without fabricating completion.
            | BigStackExplicitParentReplayPoisonDeferRecentRootOrReplayProgress -> 12
            | BigStackExplicitParentReplayPoisonDeferDeferredTypeHoleSweep -> 18
            // MIGRATION: historical runtime showed defer_live_unfinished_tail can dominate after
            // the terminal has already become an explicit parent-replay poison contract.
            // Keep a small live-tail grace window, but do not let q/a churn bypass the cap.
            | BigStackExplicitParentReplayPoisonDeferLiveUnfinishedTail -> 6
            | BigStackExplicitParentReplayPoisonDeferReplayCompleteness -> 12
            | BigStackExplicitParentReplayPoisonDeferRootAuthority -> 10
            | BigStackExplicitParentReplayPoisonDeferDynamicBridge -> 8
            | BigStackExplicitParentReplayPoisonDeferRootWitness -> 8
            | BigStackExplicitParentReplayPoisonDeferActiveTail -> 6

        let private bigStackExplicitParentReplayPoisonHandoffActionFor terminalAgeMs pendingCount queueDepth activeDepth rootProgress dynamicKeyBridge replayComplete postHandoffDeferrals ageCapMs recentReplayDelta recentRootDelta recentTerminalDelta recentSampledDelta =
            let physicalLiveTail = pendingCount > 0 || queueDepth > 0 || activeDepth > 0
            let recentAuthorityProgress =
                recentRootDelta > 0L
                || recentSampledDelta > 0L
                || recentTerminalDelta > 0L
            let recentReplayMovement = recentReplayDelta > 0L
            let likelyDeferredTypeHoleSweep =
                not replayComplete
                && rootProgress >= 16
                && queueDepth <= 8
                && activeDepth <= 4
                && recentAuthorityProgress
                && terminalAgeMs < (max (ageCapMs * 2) 3000)
            // MIGRATION: MIGRATION was manually interrupted after 593s with a
            // pinned parent-replay poison, q/a/p=2/4/2, root/sample/terminal deltas
            // quiet and replay yielding only as scheduler churn.  A tiny live tail is
            // no longer authority to keep defer_live_unfinished_tail alive forever.
            let tinyStaleParentReplayPoisonTail =
                not replayComplete
                && physicalLiveTail
                && pendingCount <= 3
                && queueDepth <= 8
                && activeDepth <= 4
                && terminalAgeMs >= (max ageCapMs 12000)
                && recentRootDelta <= 0L
                && recentSampledDelta <= 0L
                && recentTerminalDelta <= 0L
            if tinyStaleParentReplayPoisonTail then
                BigStackExplicitParentReplayPoisonSurface
            elif not replayComplete && recentAuthorityProgress && postHandoffDeferrals < 8 then
                BigStackExplicitParentReplayPoisonDeferRecentRootOrReplayProgress
            elif likelyDeferredTypeHoleSweep && postHandoffDeferrals < 8 then
                BigStackExplicitParentReplayPoisonDeferDeferredTypeHoleSweep
            elif not replayComplete && physicalLiveTail then
                BigStackExplicitParentReplayPoisonDeferLiveUnfinishedTail
            elif dynamicKeyBridge > 0 && postHandoffDeferrals < 6 then
                BigStackExplicitParentReplayPoisonDeferDynamicBridge
            elif not replayComplete && rootProgress > 0 && postHandoffDeferrals < 8 then
                BigStackExplicitParentReplayPoisonDeferReplayCompleteness
            elif terminalAgeMs < ageCapMs && (queueDepth > 0 || activeDepth > 0) then
                if rootProgress > 0 then BigStackExplicitParentReplayPoisonDeferRootWitness
                else BigStackExplicitParentReplayPoisonDeferActiveTail
            elif not replayComplete && postHandoffDeferrals < 8 then
                BigStackExplicitParentReplayPoisonDeferRootAuthority
            else BigStackExplicitParentReplayPoisonSurface

        let private bigStackExplicitParentReplayPoisonHandoffShouldDefer = function
            | BigStackExplicitParentReplayPoisonSurface -> false
            | _ -> true

        let private bigStackFastFailureUsefulnessFor (statusId: EvalReplayValueStore.SemanticStatusId) statusPresent (reasonId: BigStackTerminalReasonId) dynamicKeyBridge poisonCascade terminalPins rootProgress =
            match reasonId with
            | BigStackTerminalReasonRuntimeRecordDynamicKeyRequired when dynamicKeyBridge > 0 ->
                BigStackFastFailureUsefulDynamicBridgeLocalized
            | BigStackTerminalReasonParentReplayStatusPreservedRepeat when statusId = EvalReplayValueStore.SemanticParentReplayCycleBreakPoisoned && poisonCascade > 0 && terminalPins > 0 ->
                BigStackFastFailureUsefulParentReplayPoisonHandoff
            | _ when statusPresent && terminalPins > 0 ->
                BigStackFastFailureUsefulFrontierPinned
            | _ when dynamicKeyBridge = 0 && poisonCascade = 0 && terminalPins = 0 && rootProgress = 0 ->
                BigStackFastFailureLowInfoNoAuthority
            | _ -> BigStackFastFailureUnclassified

        let private bigStackSequentialHotFrontierFastRetryAllowed = function
            | BigStackPevalMain -> true
            | _ -> false

        let private bigStackReplayChatterFastRetryAllowed = function
            | BigStackPevalMain
            | BigStackTerm
            | BigStackTy -> true
            | _ -> false

        // MIGRATION: historical runtime proved the previous structural threshold was unreachable
        // before the hard timeout because these counters represent sampled liveness
        // receipts at the join boundary.  Keep the threshold closed and local to
        // peval_main fast-retry so it cannot become semantic authority.
        let private bigStackDiagnosticActivityFastRetryThreshold = 32

        type TimingBasis =
            | TimingFixedMs of value:int64 * rationale:string
            | TimingDerivedFromDistribution of percentile:int * observedMs:int64 * multiplierNumerator:int64 * multiplierDenominator:int64 * floorMs:int64 * ceilingMs:int64
            | TimingAdaptiveProductivity of inactivityMs:int64 * signal:string

        let private timingBasisMilliseconds = function
            | TimingFixedMs(value, _) -> max 0L value
            | TimingDerivedFromDistribution(_, observedMs, multiplierNumerator, multiplierDenominator, floorMs, ceilingMs) ->
                let denominator = max 1L multiplierDenominator
                let scaled = ((max 0L observedMs * max 1L multiplierNumerator) + denominator - 1L) / denominator
                min (max floorMs ceilingMs) (max (min floorMs ceilingMs) scaled)
            | TimingAdaptiveProductivity(inactivityMs, _) -> max 0L inactivityMs

        let private timingBasisText = function
            | TimingFixedMs(value, rationale) ->
                sprintf "FixedMs(value=%d|rationale=%s)" value rationale
            | TimingDerivedFromDistribution(percentile, observedMs, multiplierNumerator, multiplierDenominator, floorMs, ceilingMs) ->
                FastRuntimeFormat.format "DerivedFromDistribution(percentile=%d|observed_ms=%d|multiplier=%d/%d|floor_ms=%d|ceiling_ms=%d)" [| box percentile; box observedMs; box multiplierNumerator; box multiplierDenominator; box floorMs; box ceilingMs |]
            | TimingAdaptiveProductivity(inactivityMs, signal) ->
                sprintf "AdaptiveProductivity(inactivity_ms=%d|signal=%s)" inactivityMs signal

        let private bigStackGenerationChangeGraceBasisFromSnapshot snapshot =
            TimingDerivedFromDistribution(
                99,
                BigStackDurationBasisAuthority.observedP99Ms snapshot,
                3L,
                2L,
                10000L,
                900000L)

        let private bigStackHardJoinAbortBasisFromSnapshot snapshot =
            TimingDerivedFromDistribution(
                99,
                BigStackDurationBasisAuthority.observedP99Ms snapshot,
                3L,
                1L,
                240000L,
                1800000L)

        // Generation-local JP evidence is the primary productivity authority.
        // Global semantic counters remain useful telemetry, but they cannot prove that the
        // child set owned by this join advanced.  A lock-owned immutable snapshot registry
        // records admitted, retired and live work-unit identities per generation so the
        // synchronous BigStack join can sample it without re-entering Hopac.
        type JpGenerationLocalEvidenceSnapshot = private {
            generation : int64
            admitted : Set<string>
            retired : Set<string>
            live : Set<string>
            revision : int64
            evidenceRef : CompilerIdentityKernel.ContentDigest
        }

        module JpGenerationLocalEvidenceAuthority =
            // This evidence is sampled synchronously by BigStack.tryRun while the caller may
            // already be executing on a Hopac worker.  A mailbox read implemented with
            // Hopac.run re-enters the global scheduler and can block in Condition.Wait.
            // The authority is a small process-local diagnostic ledger, so a lock-owned map
            // gives stronger read-after-write semantics without introducing another job.
            let private gate = obj()
            let mutable private states : Map<int64, JpGenerationLocalEvidenceSnapshot> = Map.empty

            let private snapshotFor generation admitted retired live revision = {
                generation = generation
                admitted = admitted
                retired = retired
                live = live
                revision = revision
                evidenceRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-generation-local-evidence"
                        (FastRuntimeFormat.format "%d|admitted=%s|retired=%s|live=%s|revision=%d" [| box generation; box (admitted |> Set.toList |> String.concat ","); box (retired |> Set.toList |> String.concat ","); box (live |> Set.toList |> String.concat ","); box revision |])
            }

            let private empty generation = snapshotFor generation Set.empty Set.empty Set.empty 0L

            let private update generation advance =
                lock gate (fun () ->
                    let prior = Map.tryFind generation states |> Option.defaultWith (fun () -> empty generation)
                    let next = advance prior
                    states <- Map.add generation next states)

            let noteAdmitted generation workUnitId =
                update generation (fun prior ->
                    let admitted = Set.add workUnitId prior.admitted
                    let live = Set.add workUnitId prior.live
                    snapshotFor generation admitted prior.retired live (prior.revision + 1L))

            let noteRetired generation workUnitId =
                update generation (fun prior ->
                    let admitted = Set.add workUnitId prior.admitted
                    let retired = Set.add workUnitId prior.retired
                    let live = Set.remove workUnitId prior.live
                    snapshotFor generation admitted retired live (prior.revision + 1L))

            let read generation : JpGenerationLocalEvidenceSnapshot =
                lock gate (fun () ->
                    Map.tryFind generation states |> Option.defaultWith (fun () -> empty generation))

        type JpGenerationLocalEvidenceDelta =
            | JpGenerationLocalEvidenceUnchanged of JpGenerationLocalEvidenceSnapshot
            | JpGenerationLocalEvidenceAdvanced of generation:int64 * admittedDelta:int * retiredDelta:int * liveDelta:int * current:JpGenerationLocalEvidenceSnapshot
            | JpGenerationLocalEvidenceClosed of generation:int64 * retiredDelta:int * current:JpGenerationLocalEvidenceSnapshot

        let private jpGenerationLocalEvidenceDelta baseline current =
            let admittedDelta = max 0 (current.admitted.Count - baseline.admitted.Count)
            let retiredDelta = max 0 (current.retired.Count - baseline.retired.Count)
            let liveDelta = current.live.Count - baseline.live.Count
            if retiredDelta > 0 && current.live.IsEmpty && current.admitted.Count > 0 then
                JpGenerationLocalEvidenceClosed(current.generation, retiredDelta, current)
            elif admittedDelta > 0 || retiredDelta > 0 || liveDelta <> 0 then
                JpGenerationLocalEvidenceAdvanced(current.generation, admittedDelta, retiredDelta, liveDelta, current)
            else
                JpGenerationLocalEvidenceUnchanged current

        type JoinProductivityEvidence =
            | JoinObservedFactDelta of subtreeFactDelta:int64
            | JoinObservedActivePairDelta of activePairDelta:int64
            | JoinObservedFactsAndPairs of subtreeFactDelta:int64 * activePairDelta:int64
            | JoinObservedJoinLocalProgress of joinRef:CompilerIdentityKernel.ContentDigest * producedDelta:int64 * retiredDelta:int64 * semanticFactDelta:int64 * closureCaptureDelta:int64 * evidenceRef:CompilerIdentityKernel.ContentDigest
            | JoinObservedJoinLocalCompletion of joinRef:CompilerIdentityKernel.ContentDigest * evidenceRef:CompilerIdentityKernel.ContentDigest
            | JoinObservedGenerationRetirement of generation:int64 * retiredDelta:int * liveDelta:int * evidenceRef:CompilerIdentityKernel.ContentDigest
            | JoinObservedGenerationClosure of generation:int64 * retiredDelta:int * evidenceRef:CompilerIdentityKernel.ContentDigest
            | JoinChildRetiredWithoutNewGlobalFacts
            | JoinNoLocalSignal
            | JoinCycleTerminal

        let private joinProductivityEvidenceText = function
            | JoinObservedFactDelta delta -> sprintf "ObservedFactDelta(delta=%d|authority=observer_only)" delta
            | JoinObservedActivePairDelta delta -> sprintf "ObservedActivePairDelta(delta=%d|authority=observer_only)" delta
            | JoinObservedFactsAndPairs(factsDelta, activePairDelta) ->
                sprintf "ObservedFactsAndPairs(facts_delta=%d|active_pair_delta=%d|authority=observer_only)" factsDelta activePairDelta
            | JoinObservedJoinLocalProgress(joinRef, producedDelta, retiredDelta, semanticFactDelta, closureCaptureDelta, evidenceRef) ->
                FastRuntimeFormat.format "JoinLocalProgress(join_ref=%s|produced_delta=%d|retired_delta=%d|semantic_fact_delta=%d|closure_capture_delta=%d|evidence_ref=%s|authority=join_local_scope)" [| box (CompilerIdentityKernel.ContentDigest.text joinRef); box producedDelta; box retiredDelta; box semanticFactDelta; box closureCaptureDelta; box (CompilerIdentityKernel.ContentDigest.text evidenceRef) |]
            | JoinObservedJoinLocalCompletion(joinRef, evidenceRef) ->
                sprintf "JoinLocalCompletion(join_ref=%s|evidence_ref=%s|authority=join_local_scope)"
                    (CompilerIdentityKernel.ContentDigest.text joinRef)
                    (CompilerIdentityKernel.ContentDigest.text evidenceRef)
            | JoinObservedGenerationRetirement(generation, retiredDelta, liveDelta, evidenceRef) ->
                FastRuntimeFormat.format "GenerationRetirement(generation=%d|retired_delta=%d|live_delta=%d|evidence_ref=%s|authority=generation_local_actor)" [| box generation; box retiredDelta; box liveDelta; box (CompilerIdentityKernel.ContentDigest.text evidenceRef) |]
            | JoinObservedGenerationClosure(generation, retiredDelta, evidenceRef) ->
                FastRuntimeFormat.format "GenerationClosure(generation=%d|retired_delta=%d|evidence_ref=%s|authority=generation_local_actor)" [| box generation; box retiredDelta; box (CompilerIdentityKernel.ContentDigest.text evidenceRef) |]
            | JoinChildRetiredWithoutNewGlobalFacts -> "ChildRetiredWithoutNewGlobalFacts(authority=join_local_completion)"
            | JoinNoLocalSignal -> "NoLocalSignal(non_fatal=true)"
            | JoinCycleTerminal -> "CycleTerminal(non_fatal=false|authority=typed_cycle_fuse)"

        type BigStackJoinProof =
            | BigStackJoinStarted of generation:int64 * semanticFactCount:CompilerKernelV2.NodeCount * consumedActivePairs:CompilerKernelV2.NodeCount * waited:CompilerKernelV2.WallTime
            | BigStackJoinGenerationChanged of prior:BigStackJoinProof * fromGeneration:int64 * toGeneration:int64 * semanticFactCount:CompilerKernelV2.NodeCount * consumedActivePairs:CompilerKernelV2.NodeCount * waited:CompilerKernelV2.WallTime
            | BigStackJoinProductive of prior:BigStackJoinProof * evidence:JoinProductivityEvidence * semanticFactCount:CompilerKernelV2.NodeCount * consumedActivePairs:CompilerKernelV2.NodeCount * waited:CompilerKernelV2.WallTime
            | BigStackJoinCompleted of prior:BigStackJoinProof * endGeneration:int64 * semanticFactCount:CompilerKernelV2.NodeCount * consumedActivePairs:CompilerKernelV2.NodeCount * waited:CompilerKernelV2.WallTime
            | BigStackJoinStalled of prior:BigStackJoinProof * inactivity:CompilerKernelV2.WallTime * grace:CompilerKernelV2.WallTime * semanticFactCount:CompilerKernelV2.NodeCount * consumedActivePairs:CompilerKernelV2.NodeCount * waited:CompilerKernelV2.WallTime

        let private bigStackJoinNodeCount value = CompilerKernelV2.Measured.create<CompilerKernelV2.NodeCountUnit> "bigStackJoinNodeCount" (max 0L (int64 value))
        let private bigStackJoinWallTime value = CompilerKernelV2.Measured.create<CompilerKernelV2.WallTimeUnit> "bigStackJoinWallTime" (max 0L (int64 value))

        let rec private bigStackJoinProofStableText = function
            | BigStackJoinStarted(generation, factCount, activePairs, waited) ->
                FastRuntimeFormat.format "started(generation=%d|facts=%d|active_pairs=%d|waited_ms=%d)" [| box generation; box (CompilerKernelV2.Measured.value factCount); box (CompilerKernelV2.Measured.value activePairs); box (CompilerKernelV2.Measured.value waited) |]
            | BigStackJoinGenerationChanged(prior, fromGeneration, toGeneration, factCount, activePairs, waited) ->
                FastRuntimeFormat.format "generation_changed(prior=%s|from=%d|to=%d|facts=%d|active_pairs=%d|waited_ms=%d)" [| box (bigStackJoinProofStableText prior); box fromGeneration; box toGeneration; box (CompilerKernelV2.Measured.value factCount); box (CompilerKernelV2.Measured.value activePairs); box (CompilerKernelV2.Measured.value waited) |]
            | BigStackJoinProductive(prior, evidence, factCount, activePairs, waited) ->
                FastRuntimeFormat.format "productive(prior=%s|evidence=%s|facts=%d|active_pairs=%d|waited_ms=%d)" [| box (bigStackJoinProofStableText prior); box (joinProductivityEvidenceText evidence); box (CompilerKernelV2.Measured.value factCount); box (CompilerKernelV2.Measured.value activePairs); box (CompilerKernelV2.Measured.value waited) |]
            | BigStackJoinCompleted(prior, endGeneration, factCount, activePairs, waited) ->
                FastRuntimeFormat.format "completed(prior=%s|end_generation=%d|facts=%d|active_pairs=%d|waited_ms=%d)" [| box (bigStackJoinProofStableText prior); box endGeneration; box (CompilerKernelV2.Measured.value factCount); box (CompilerKernelV2.Measured.value activePairs); box (CompilerKernelV2.Measured.value waited) |]
            | BigStackJoinStalled(prior, inactivity, grace, factCount, activePairs, waited) ->
                FastRuntimeFormat.format "stalled(prior=%s|inactivity_ms=%d|grace_ms=%d|facts=%d|active_pairs=%d|waited_ms=%d)" [| box (bigStackJoinProofStableText prior); box (CompilerKernelV2.Measured.value inactivity); box (CompilerKernelV2.Measured.value grace); box (CompilerKernelV2.Measured.value factCount); box (CompilerKernelV2.Measured.value activePairs); box (CompilerKernelV2.Measured.value waited) |]

        let private bigStackJoinProofAdvanceProductive prior evidence semanticFactCount consumedActivePairs waited =
            BigStackJoinProductive(prior, evidence, bigStackJoinNodeCount semanticFactCount, bigStackJoinNodeCount consumedActivePairs, bigStackJoinWallTime waited)

        let private bigStackJoinProofRef proof =
            bigStackJoinProofStableText proof
            |> CompilerIdentityKernel.ContentDigest.ofText "bigstack-join-proof"
            |> CompilerIdentityKernel.ContentDigest.text

        // Generation-change retries are a typed decision.  Their grace is derived
        // from measured join-point specialization latency and renewed by semantic
        // productivity instead of being an invisible fixed timeout.
        type BigStackGenerationChangeDecisionId =
            | BigStackGenerationChangeObserve
            | BigStackGenerationChangeRetryEjp0018
            | BigStackGenerationChangeDeferLiveReplayTail
            | BigStackGenerationChangeSurfaceTermCycleFusePoison

        let private bigStackGenerationChangeDecisionText = function
            | BigStackGenerationChangeObserve -> "observe"
            | BigStackGenerationChangeRetryEjp0018 -> "retry_ejp0018"
            | BigStackGenerationChangeDeferLiveReplayTail -> "defer_live_reentry_fuse_tail"
            | BigStackGenerationChangeSurfaceTermCycleFusePoison -> "surface_term_reentry_fuse_poison"

        let private bigStackGenerationChangeDecisionFor tag cycleTripped terminalAlreadyPinned pendingCount queueDepth activeDepth replayComplete writeWitness waitedSinceGenChangeMs =
            let liveTailRunnable = pendingCount > 0 || queueDepth > 0 || activeDepth > 0
            let liveTailFresh = waitedSinceGenChangeMs >= 0 && waitedSinceGenChangeMs < 5000
            if cycleTripped
               && tag = "peval_main"
               && not replayComplete
               && not writeWitness
               && liveTailRunnable
               && liveTailFresh then
                BigStackGenerationChangeDeferLiveReplayTail
            elif cycleTripped
                 && tag = "peval_main"
                 && not terminalAlreadyPinned
                 && not replayComplete
                 && not writeWitness
                 && pendingCount <= 2
                 && queueDepth <= 16
                 && activeDepth <= 4
                 && waitedSinceGenChangeMs >= 0 then
                BigStackGenerationChangeSurfaceTermCycleFusePoison
            elif cycleTripped || waitedSinceGenChangeMs >= 0 then
                BigStackGenerationChangeRetryEjp0018
            else
                BigStackGenerationChangeObserve

        // MIGRATION: closed evidence id for retry policy; no ad-hoc policy strings
        // in the predicate.  Text is only emitted at the diagnostic boundary.
        type BigStackFastRetryEvidenceId =
            | BigStackFastRetryHotFrontier
            | BigStackFastRetryDiagnosticActivity
            | BigStackFastRetryCycleFuse
            | BigStackFastRetryPreSequentialDiagnosticActivity

        let private bigStackFastRetryEvidenceText = function
            | BigStackFastRetryHotFrontier -> "hot_frontier"
            | BigStackFastRetryDiagnosticActivity -> "diagnostic_activity"
            | BigStackFastRetryCycleFuse -> "replay_repeat_guard"
            | BigStackFastRetryPreSequentialDiagnosticActivity -> "preseq_diagnostic_activity"

        type BigStackFastRetryActionId =
            | BigStackFastRetryRaiseEjp0019
            | BigStackFastRetryRaiseReplayNoRootEjp0019
            | BigStackFastRetryRaiseReplayChatterEjp0019
            | BigStackFastRetryRaiseStaleNoRootSmallQueueEjp0019
            | BigStackFastRetryDeferHotFrontierActivity
            | BigStackFastRetryDeferLiveReplay
            | BigStackFastRetryDeferSemanticTailActivity
            | BigStackFastRetryDeferActiveTailYield
            | BigStackFastRetryObserveOnly

        let private bigStackFastRetryActionText = function
            | BigStackFastRetryRaiseEjp0019 -> "raise_ejp0019"
            | BigStackFastRetryRaiseReplayNoRootEjp0019 -> "raise_replay_no_root_ejp0019"
            | BigStackFastRetryRaiseReplayChatterEjp0019 -> "raise_replay_chatter_ejp0019"
            | BigStackFastRetryRaiseStaleNoRootSmallQueueEjp0019 -> "raise_stale_no_root_small_queue_ejp0019"
            | BigStackFastRetryDeferHotFrontierActivity -> "defer_hot_frontier_activity"
            | BigStackFastRetryDeferLiveReplay -> "defer_live_replay"
            | BigStackFastRetryDeferSemanticTailActivity -> "defer_semantic_tail_activity"
            | BigStackFastRetryDeferActiveTailYield -> "defer_active_tail_yield"
            | BigStackFastRetryObserveOnly -> "observe_only"

        // MIGRATION: closed exit decision for the hot-frontier retry boundary.
        // The old path collapsed every fast-retry raise into EJP0019 even when the
        // frontier was still alive (1332 final: pending=2/q=1/a=4/root_wit≈15).
        type BigStackHotFrontierExitDecisionId =
            | BigStackHotFrontierExitObserve
            | BigStackHotFrontierExitYieldActiveTail
            | BigStackHotFrontierExitRepeatCapProbationDrainInFlight
            | BigStackHotFrontierExitPendingActiveRepeatCapDrain
            | BigStackHotFrontierExitPendingQueueRepeatCapDrain
            | BigStackHotFrontierExitQueueOnlyDrain
            | BigStackHotFrontierExitDynamicRecordKeyBridgeTailDrain
            | BigStackHotFrontierExitDynamicJoinPendingFenceBridgeDrain
            | BigStackHotFrontierExitActiveStructuralChurnCircuitBreak
            | BigStackHotFrontierExitSurfaceRepeatCapBreach
            | BigStackHotFrontierExitHardPoisonPendingZero
            | BigStackHotFrontierExitRaiseEjp0019

        let private bigStackHotFrontierExitDecisionText = function
            | BigStackHotFrontierExitObserve -> "observe"
            | BigStackHotFrontierExitYieldActiveTail -> "yield_active_tail"
            | BigStackHotFrontierExitRepeatCapProbationDrainInFlight -> "repeat_cap_probation_drain_in_flight"
            | BigStackHotFrontierExitPendingActiveRepeatCapDrain -> "pending_active_repeat_cap_drain"
            | BigStackHotFrontierExitPendingQueueRepeatCapDrain -> "pending_queue_repeat_cap_drain"
            | BigStackHotFrontierExitQueueOnlyDrain -> "queue_only_underutilized_drain"
            | BigStackHotFrontierExitDynamicRecordKeyBridgeTailDrain -> "dynamic_record_key_bridge_tail_drain"
            | BigStackHotFrontierExitDynamicJoinPendingFenceBridgeDrain -> "dynamic_join_pending_fence_bridge_drain"
            | BigStackHotFrontierExitActiveStructuralChurnCircuitBreak -> "active_structural_churn_circuit_break"
            | BigStackHotFrontierExitSurfaceRepeatCapBreach -> "surface_cascaded_terminal_repeat_cap_breach"
            | BigStackHotFrontierExitHardPoisonPendingZero -> "hard_poison_pending_zero"
            | BigStackHotFrontierExitRaiseEjp0019 -> "raise_ejp0019"

        let private bigStackHotFrontierExitDecisionFor action pending queueDepth activeDepth rootWitness replayComplete writeWitness progressYield repeatCapBreached repeatCapProbationDrainInFlight recordKeyBridgeTailLive dynamicJoinPendingFenceBridgeLive =
            let wantsRaise =
                match action with
                | BigStackFastRetryRaiseEjp0019
                | BigStackFastRetryRaiseReplayNoRootEjp0019
                | BigStackFastRetryRaiseReplayChatterEjp0019
                | BigStackFastRetryRaiseStaleNoRootSmallQueueEjp0019 -> true
                | _ -> false
            if repeatCapBreached && recordKeyBridgeTailLive && (pending > 0 || queueDepth > 0 || rootWitness > 0 || progressYield) && not replayComplete && not writeWitness then BigStackHotFrontierExitDynamicRecordKeyBridgeTailDrain
            elif repeatCapBreached && dynamicJoinPendingFenceBridgeLive && (pending > 0 || queueDepth > 0 || rootWitness > 0 || progressYield) && not replayComplete && not writeWitness then BigStackHotFrontierExitDynamicJoinPendingFenceBridgeDrain
            elif repeatCapBreached && repeatCapProbationDrainInFlight && not recordKeyBridgeTailLive && not dynamicJoinPendingFenceBridgeLive && not replayComplete && not writeWitness then BigStackHotFrontierExitRepeatCapProbationDrainInFlight
            elif repeatCapBreached && queueDepth >= 128 && activeDepth >= 4 && rootWitness > 0 && not replayComplete && not writeWitness && not recordKeyBridgeTailLive then BigStackHotFrontierExitRepeatCapProbationDrainInFlight
            elif repeatCapBreached && queueDepth >= 16 && activeDepth >= 2 && not replayComplete && not writeWitness && not recordKeyBridgeTailLive then BigStackHotFrontierExitActiveStructuralChurnCircuitBreak
            elif repeatCapBreached && activeDepth > 0 && pending > 0 && (queueDepth <= 16 || rootWitness > 0 || progressYield) && not replayComplete && not writeWitness then BigStackHotFrontierExitPendingActiveRepeatCapDrain
            elif repeatCapBreached && pending > 0 && queueDepth > 0 && queueDepth <= 16 && not replayComplete && not writeWitness then BigStackHotFrontierExitPendingQueueRepeatCapDrain
            elif repeatCapBreached && activeDepth > 0 && queueDepth > 0 && pending = 0 && (rootWitness > 0 || progressYield) && not replayComplete && not writeWitness then BigStackHotFrontierExitRepeatCapProbationDrainInFlight
            elif repeatCapBreached && not replayComplete && not writeWitness then BigStackHotFrontierExitSurfaceRepeatCapBreach
            elif action = BigStackFastRetryDeferActiveTailYield && activeDepth > 0 && queueDepth > 0 && pending = 0 && queueDepth <= 64 then BigStackHotFrontierExitYieldActiveTail
            elif action = BigStackFastRetryDeferActiveTailYield && activeDepth > 0 && pending > 0 then BigStackHotFrontierExitYieldActiveTail
            elif not wantsRaise then BigStackHotFrontierExitObserve
            elif replayComplete || writeWitness then BigStackHotFrontierExitObserve
            elif activeDepth = 0 && pending = 0 && queueDepth > 0 then BigStackHotFrontierExitQueueOnlyDrain
            elif action = BigStackFastRetryRaiseStaleNoRootSmallQueueEjp0019 then BigStackHotFrontierExitRaiseEjp0019
            elif activeDepth > 0 && pending = 0 && queueDepth > 0 && queueDepth <= 64 && (rootWitness > 0 || progressYield) then BigStackHotFrontierExitYieldActiveTail
            elif activeDepth > 0 && pending = 0 && queueDepth > 0 then BigStackHotFrontierExitHardPoisonPendingZero
            elif activeDepth > 0 && pending > 0 && (queueDepth <= 8 || rootWitness >= 10 || progressYield) then BigStackHotFrontierExitYieldActiveTail
            else BigStackHotFrontierExitRaiseEjp0019

        type ReplayNoRootFinishDecisionId =
