            | ReplayNoRootPressureObserve -> "observe"

        let private replayNoRootPressureGateFor waitedMs queueDepth activeDepth rootWitnessActivity rootWitnessStillRising rootWitnessGraceActive =
            if activeDepth >= 4 && queueDepth >= 48 && queueDepth < 96 && rootWitnessActivity > 0 && (rootWitnessStillRising || rootWitnessGraceActive) && waitedMs < 9000 then ReplayNoRootPressureFreshRootDrain
            elif waitedMs >= 1250 && queueDepth >= 96 && activeDepth >= 4 && rootWitnessActivity >= 4 then ReplayNoRootPressureMatureQueueRetry
            elif waitedMs >= 9000 && queueDepth >= 48 && activeDepth >= 4 && rootWitnessActivity >= 8 && not (rootWitnessStillRising || rootWitnessGraceActive) then ReplayNoRootPressureMatureQueueRetry
            elif waitedMs >= 26000 && queueDepth >= 48 && activeDepth >= 4 then ReplayNoRootPressureMatureQueueRetry
            elif waitedMs >= 34000 && queueDepth >= 32 && activeDepth >= 4 then ReplayNoRootPressureMatureQueueRetry
            elif waitedMs >= 44000 && queueDepth >= 24 && activeDepth >= 4 then ReplayNoRootPressureMatureQueueRetry
            else ReplayNoRootPressureObserve

        type ReplayNoRootDrainBudgetId =
            | ReplayNoRootDrainNoBudget
            | ReplayNoRootDrainStandardBudget
            | ReplayNoRootDrainUnderutilizedQueueBudget

        let private replayNoRootDrainBudgetText = function
