            | NoRootBudgetBypassProbationMissingAfterPrefetchLiveTail -> "missing_after_prefetch_live_tail"
            | NoRootBudgetBypassProbationMissingAfterPrefetchFrontierPendingSidecar -> "missing_after_prefetch_frontier_pending_sidecar"
            | NoRootBudgetBypassProbationRank83LiveRootSemanticTail -> "rank83_live_root_semantic_tail"
            | NoRootBudgetBypassProbationRank83WriteWitnessIncompleteLiveTail -> "rank83_write_witness_incomplete_live_tail"
            | NoRootBudgetBypassProbationRank83RepeatCapWriteWitnessPendingSemanticTail -> "rank83_repeat_cap_write_witness_pending_semantic_tail"
            | NoRootBudgetBypassProbationLiveTailEvidenceOverride -> "live_tail_evidence_overrides_no_root_bypass"
            | NoRootBudgetBypassProbationSmallQueueActiveAuthorityOverride -> "small_queue_active_authority_overrides_no_root_bypass"
            | NoRootBudgetBypassProbationActiveOnlyPendingAuthorityOverride -> "active_only_pending_authority_overrides_no_root_bypass"
            | NoRootBudgetBypassProbationPreCapActiveTailOverride -> "pre_cap_active_tail_override_forces_probation"
            | NoRootBudgetBypassProbationRank83RepeatCapPendingSemanticTail -> "rank83_repeat_cap_pending_semantic_tail"
            | NoRootBudgetBypassProbationRank83RepeatCapReachedLiveTail -> "rank83_repeat_cap_reached_live_tail"
            | NoRootBudgetBypassProbationRank83RepeatCapBreachedLiveTail -> "rank83_repeat_cap_breached_live_tail"

        let private noRootBudgetBypassProbationShouldDrain = function
            | NoRootBudgetBypassProbationNone -> false
            | NoRootBudgetBypassProbationMissingAfterPrefetchLiveTail
            | NoRootBudgetBypassProbationMissingAfterPrefetchFrontierPendingSidecar
            | NoRootBudgetBypassProbationRank83LiveRootSemanticTail
            | NoRootBudgetBypassProbationRank83WriteWitnessIncompleteLiveTail
            | NoRootBudgetBypassProbationRank83RepeatCapWriteWitnessPendingSemanticTail
            | NoRootBudgetBypassProbationLiveTailEvidenceOverride
            | NoRootBudgetBypassProbationSmallQueueActiveAuthorityOverride
            | NoRootBudgetBypassProbationActiveOnlyPendingAuthorityOverride
            | NoRootBudgetBypassProbationPreCapActiveTailOverride
            | NoRootBudgetBypassProbationRank83RepeatCapPendingSemanticTail
            | NoRootBudgetBypassProbationRank83RepeatCapReachedLiveTail
            | NoRootBudgetBypassProbationRank83RepeatCapBreachedLiveTail -> true

        // MIGRATION: one authoritative live-tail override DU for no-root bypass.
