            | ReplayNoRootStructuralCycleBreakInjected -> "cycle_break_injected"

        type ReplayParentPoisonScopeId =
            | ReplayParentPoisonQueueSurge
            | ReplayParentPoisonCrossKind

        let private replayParentPoisonScopeText = function
            | ReplayParentPoisonQueueSurge -> "queue_surge_parent_poison"
            | ReplayParentPoisonCrossKind -> "cross_kind_parent_poison"

        // MIGRATION: close queue-surge parent-poison maturity as a DU. MIGRATION
        // proved the terminal was correct but too late: q>=96/a=4/root>=10 kept
        // passing through cold_structural_surge receipts before the rank-83 poison
        // became visible. This typed gate makes high-root queue surge authority
        // explicit instead of hiding it in ad-hoc string thresholds.
        type ReplayQueueSurgeMaturityId =
            | ReplayQueueSurgeColdStructural
            | ReplayQueueSurgeMatureRepeatedDeferral
            | ReplayQueueSurgeMatureHighRootQueue
            | ReplayQueueSurgeMatureStalledRootQueue
            | ReplayQueueSurgeMatureWallClock

        let private replayQueueSurgeMaturityText = function
            | ReplayQueueSurgeColdStructural -> "cold_structural_surge"
            | ReplayQueueSurgeMatureRepeatedDeferral -> "mature_repeated_deferral"
            | ReplayQueueSurgeMatureHighRootQueue -> "mature_high_root_queue"
            | ReplayQueueSurgeMatureStalledRootQueue -> "mature_stalled_root_queue"
            | ReplayQueueSurgeMatureWallClock -> "mature_wall_clock"

        let private replayQueueSurgeMaturityIsMature = function
            | ReplayQueueSurgeColdStructural -> false
            | ReplayQueueSurgeMatureRepeatedDeferral
            | ReplayQueueSurgeMatureHighRootQueue
            | ReplayQueueSurgeMatureStalledRootQueue
            | ReplayQueueSurgeMatureWallClock -> true

        let private replayQueueSurgeMaturityFor waitedMs queueDepth activeDepth rootWitnessActivity coldDeferrals rootWitnessStallMs =
            if queueDepth >= 96 && activeDepth >= 4 && rootWitnessActivity >= 8 && waitedMs >= 750 then ReplayQueueSurgeMatureHighRootQueue
            elif queueDepth >= 96 && activeDepth >= 4 && rootWitnessActivity >= 4 && rootWitnessStallMs >= 750 && waitedMs >= 1000 then ReplayQueueSurgeMatureStalledRootQueue
            elif queueDepth >= 96 && activeDepth >= 4 && rootWitnessActivity >= 3 && coldDeferrals >= 1 && waitedMs >= 500 then ReplayQueueSurgeMatureRepeatedDeferral
            elif queueDepth >= 64 && activeDepth >= 4 && rootWitnessActivity >= 4 && waitedMs >= 9000 then ReplayQueueSurgeMatureWallClock
            else ReplayQueueSurgeColdStructural

        type ReplayQueueSurgePoisonBudgetId =
            | ReplayQueueSurgePoisonBudgetMinimal of attempts:int
            | ReplayQueueSurgePoisonBudgetBounded of attempts:int
            | ReplayQueueSurgePoisonBudgetCold of attempts:int

        let private replayQueueSurgePoisonBudgetFor queueDepth activeDepth rootWitnessActivity maturityId =
            match maturityId with
            | ReplayQueueSurgeMatureHighRootQueue when queueDepth >= 160 || activeDepth >= 4 ->
                ReplayQueueSurgePoisonBudgetMinimal 4
            | ReplayQueueSurgeMatureStalledRootQueue when queueDepth >= 160 || activeDepth >= 4 ->
                ReplayQueueSurgePoisonBudgetMinimal 4
            | ReplayQueueSurgeMatureRepeatedDeferral when queueDepth >= 96 ->
                ReplayQueueSurgePoisonBudgetBounded 8
            | ReplayQueueSurgeMatureWallClock when queueDepth >= 96 ->
                ReplayQueueSurgePoisonBudgetBounded 8
            | _ when queueDepth >= 64 || rootWitnessActivity >= 8 ->
                ReplayQueueSurgePoisonBudgetBounded 12
            | _ -> ReplayQueueSurgePoisonBudgetCold 16

        let private replayQueueSurgePoisonBudgetValue = function
            | ReplayQueueSurgePoisonBudgetMinimal attempts
            | ReplayQueueSurgePoisonBudgetBounded attempts
            | ReplayQueueSurgePoisonBudgetCold attempts -> attempts

        let private replayQueueSurgePoisonBudgetText = function
            | ReplayQueueSurgePoisonBudgetMinimal attempts -> sprintf "ReplayQueueSurgePoisonBudget(Minimal|attempts=%d)" attempts
            | ReplayQueueSurgePoisonBudgetBounded attempts -> sprintf "ReplayQueueSurgePoisonBudget(Bounded|attempts=%d)" attempts
            | ReplayQueueSurgePoisonBudgetCold attempts -> sprintf "ReplayQueueSurgePoisonBudget(Cold|attempts=%d)" attempts

        type BigStackQueueSurgeRetryDecisionId =
            | BigStackQueueSurgeRetryObserve
            | BigStackQueueSurgeRetryDrainRepeatCapProbation
            | BigStackQueueSurgeRetryEscalateRepeatCapExhausted
            | BigStackQueueSurgeRetryInjectParentPoison

        let private bigStackQueueSurgeRetryDecisionText = function
            | BigStackQueueSurgeRetryObserve -> "observe"
            | BigStackQueueSurgeRetryDrainRepeatCapProbation -> "drain_repeat_cap_probation"
            | BigStackQueueSurgeRetryEscalateRepeatCapExhausted -> "escalate_repeat_cap_exhausted"
            | BigStackQueueSurgeRetryInjectParentPoison -> "inject_parent_poison"

        let private bigStackQueueSurgeRetryDecisionFor finishDecisionId noPinnedBudgetBypass queueDepth activeDepth rootWitnessActivity repeatCount repeatCap waitedMs replayComplete writeWitness =
            if replayComplete || writeWitness then BigStackQueueSurgeRetryObserve
            elif finishDecisionId = ReplayNoRootFinishRaiseRetry
                 && noPinnedBudgetBypass
                 && activeDepth >= 4
                 && queueDepth >= 96
                 && rootWitnessActivity >= 4
                 && repeatCap > 0
                 && repeatCount >= (max 8 (repeatCap * 2))
                 && waitedMs >= 24000 then
                // MIGRATION: 1420 showed q=307/a=4/root=9/repeat=10/4 still
                // draining after 45s because the old cap*32 threshold required
                // repeat=128.  Mature queue-surge probation must close before it
                // becomes a CPU-only livelock.
                BigStackQueueSurgeRetryEscalateRepeatCapExhausted
            elif finishDecisionId = ReplayNoRootFinishRaiseRetry
                 && noPinnedBudgetBypass
                 && activeDepth >= 4
                 && queueDepth >= 96
                 && rootWitnessActivity >= 4
                 && repeatCap > 0
                 && repeatCount >= repeatCap then
                BigStackQueueSurgeRetryDrainRepeatCapProbation
            elif finishDecisionId = ReplayNoRootFinishRaiseRetry
                 && noPinnedBudgetBypass
                 && activeDepth >= 4
                 && queueDepth >= 96
                 && rootWitnessActivity >= 4
                 && (repeatCap <= 0 || repeatCount < repeatCap)
                 && waitedMs >= 12000 then
                BigStackQueueSurgeRetryInjectParentPoison
            else BigStackQueueSurgeRetryObserve

        // No-root finish-budget receipts remain typed, but their JSON emission is
        // cadence-gated so live replay does not drown the HUD/log in identical
        // hold_root_or_complete lines.
        type ReplayNoRootFinishLogCadenceId =
            | ReplayNoRootFinishLogSuppress
            | ReplayNoRootFinishLogDecisionChanged
            | ReplayNoRootFinishLogRootWitnessDelta
            | ReplayNoRootFinishLogQueuePhaseShift
            | ReplayNoRootFinishLogQueueSurgeMilestone
            | ReplayNoRootFinishLogCadenceDue
            | ReplayNoRootFinishLogRaiseRetry

        let private replayNoRootFinishLogCadenceText = function
            | ReplayNoRootFinishLogSuppress -> "suppress"
            | ReplayNoRootFinishLogDecisionChanged -> "decision_changed"
            | ReplayNoRootFinishLogRootWitnessDelta -> "root_witness_delta"
            | ReplayNoRootFinishLogQueuePhaseShift -> "queue_phase_shift"
            | ReplayNoRootFinishLogQueueSurgeMilestone -> "queue_surge_milestone"
            | ReplayNoRootFinishLogCadenceDue -> "cadence_due"
            | ReplayNoRootFinishLogRaiseRetry -> "raise_retry"

        let private replayNoRootFinishLogCadenceFor decision waitedMs lastEmitMs lastDecision rootWitnessActivity lastRootWitnessActivity queueDepth lastQueueDepth =
            if decision = ReplayNoRootFinishObserve then ReplayNoRootFinishLogSuppress
            elif decision <> lastDecision then ReplayNoRootFinishLogDecisionChanged
            elif decision = ReplayNoRootFinishRaiseRetry && waitedMs - lastEmitMs >= 3000 then ReplayNoRootFinishLogRaiseRetry
            elif rootWitnessActivity > lastRootWitnessActivity then ReplayNoRootFinishLogRootWitnessDelta
            elif queueDepth >= 128 && (queueDepth / 64) <> (lastQueueDepth / 64) then ReplayNoRootFinishLogQueueSurgeMilestone
            elif queueDepth < 128 && (queueDepth / 16) <> (lastQueueDepth / 16) then ReplayNoRootFinishLogQueuePhaseShift
            elif waitedMs - lastEmitMs >= 3000 then ReplayNoRootFinishLogCadenceDue
            else ReplayNoRootFinishLogSuppress

        type ReplayRootWitnessStallId =
            | ReplayRootWitnessProgressFresh
            | ReplayRootWitnessStalled of int

        let private replayRootWitnessStallFor waitedMs lastEmitMs rootWitnessActivity lastRootWitnessActivity =
            if rootWitnessActivity > lastRootWitnessActivity then ReplayRootWitnessProgressFresh
            else ReplayRootWitnessStalled (max 0 (waitedMs - lastEmitMs))

        let private replayRootWitnessStallText = function
            | ReplayRootWitnessProgressFresh -> "fresh"
            | ReplayRootWitnessStalled _ -> "stalled"

        let private replayRootWitnessStallMs = function
            | ReplayRootWitnessProgressFresh -> 0
            | ReplayRootWitnessStalled ms -> ms

        type ReplayActiveTailQuiescenceId =
            | ReplayActiveTailNotQuiescent
            | ReplayActiveTailQuiescentNoQueue

        let private replayActiveTailQuiescenceFor queueDepth activeDepth =
            if queueDepth <= 0 && activeDepth > 0 then ReplayActiveTailQuiescentNoQueue
            else ReplayActiveTailNotQuiescent

        let private replayActiveTailQuiescenceText = function
            | ReplayActiveTailNotQuiescent -> "not_quiescent"
            | ReplayActiveTailQuiescentNoQueue -> "quiescent_no_queue"

        let private replayActiveTailQuiescenceBool = function
            | ReplayActiveTailNotQuiescent -> false
            | ReplayActiveTailQuiescentNoQueue -> true

        let private replayNoRootFinishDecisionFor waitedMs queueDepth activeDepth rootWitnessActivity terminalSignals rootWitnessStillRising rootWitnessGraceActive replayComplete writeWitness =
            if replayComplete || writeWitness then ReplayNoRootFinishHoldRootOrComplete
            elif replayNoRootPressureGateFor waitedMs queueDepth activeDepth rootWitnessActivity rootWitnessStillRising rootWitnessGraceActive = ReplayNoRootPressureFreshRootDrain then ReplayNoRootFinishGraceDrainingFrontier
            elif waitedMs >= 12000 && queueDepth <= 8 && activeDepth <= 4 && rootWitnessActivity >= 192 then
                // MIGRATION: MIGRATION proved the old terminal-signal gate was too strict:
                // the HUD had thousands of terminal_signals, but this local no-root budget
                // counted only selected terminal kinds and kept returning grace_draining_frontier
                // at q≈6/a≈3/roots≈1108.  Mature root authority plus a small active tail is
                // enough to surface the fail-closed retry instead of waiting for one more
                // low-frequency replay trickle.
                ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 45000 && queueDepth <= 8 && activeDepth <= 4 && rootWitnessActivity >= 128 && terminalSignals >= 160 then ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 1250 && queueDepth >= 96 && activeDepth >= 4 && rootWitnessActivity >= 4 then
                // MIGRATION: MIGRATION showed q≈101..148/a=4/roots=4 being
                // reported as cold_structural_surge for several seconds before the
                // correct rank-83 poison surfaced. Root=4 is enough authority once
                // queue pressure is already triple digit and no writer/replay-complete exists.
                ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 2500 && queueDepth >= 48 && activeDepth >= 4 && rootWitnessActivity >= 2 then
                // MIGRATION: MIGRATION showed q≈53-85/a=4 with only 2-6 root
                // witnesses still being deferred as cold structural surge.  Queue+active
                // pressure is already scheduler debt at this point; raise fail-closed
                // before the graph drains into a silent no-work tail.
                ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 6500 && queueDepth >= 64 && activeDepth >= 4 && rootWitnessActivity >= 8 then
                // MIGRATION: MIGRATION spent the tail at q≈79-98/a=4/roots=9,
                // but the generic root-witness grace branch sat above queue-pressure
                // raises.  Mature active-tail pressure now outranks root-progress
                // grace; the retry is still fail-closed and produces no BuildOk.
                ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 9000 && queueDepth >= 48 && activeDepth >= 4 && rootWitnessActivity >= 8 then ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 14000 && queueDepth >= 32 && activeDepth >= 4 && rootWitnessActivity >= 8 then ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 26000 && queueDepth >= 48 && activeDepth >= 4 then ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 34000 && queueDepth >= 32 && activeDepth >= 4 then ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 44000 && queueDepth >= 24 && activeDepth >= 4 then ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 9000 && queueDepth <= 8 && activeDepth >= 4 && rootWitnessActivity >= 12 then
                // MIGRATION: 1326 showed the exact post-pressure tail:
                // q≈3/a=4/roots≈15 kept choosing grace_draining_frontier at
                // 9.25s, 12.25s and 15.25s, then the metronome spent 130s in
                // no-work rescue.  Treat this as mature scheduler debt, not
                // generic root-progress grace.
                ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 15000 && queueDepth <= 16 && activeDepth >= 4 && rootWitnessActivity >= 12 then ReplayNoRootFinishRaiseRetry
            elif rootWitnessActivity > 0 && (rootWitnessStillRising || rootWitnessGraceActive) then ReplayNoRootFinishGraceDrainingFrontier
            elif waitedMs >= 18000 && queueDepth <= 2 && activeDepth <= 0 then ReplayNoRootFinishGraceDrainingFrontier
            elif waitedMs >= 30000 && queueDepth > 0 && activeDepth <= 0 then ReplayNoRootFinishLastChanceDrain
            else ReplayNoRootFinishObserve

        type ReplayQueueDrainDecisionId =
            | ReplayQueueDrainNoQueue
            | ReplayQueueDrainActiveDriver
            | ReplayQueueDrainScheduleTick
            | ReplayQueueDrainLongWaitForceTick

        type TerminalFlowQueueOnlyDrainAuthority =
            | TerminalFlowQueueOnlyDrainLegacyReplayDriver
            | TerminalFlowQueueOnlyDrainCanonicalPendingZero
            | TerminalFlowQueueOnlyDrainSchedulerPushOwned

        let private terminalFlowQueueOnlyDrainAuthorityText = function
            | TerminalFlowQueueOnlyDrainLegacyReplayDriver -> "legacy_replay_driver"
            | TerminalFlowQueueOnlyDrainCanonicalPendingZero -> "canonical_pending_zero_hard_stop"
            | TerminalFlowQueueOnlyDrainSchedulerPushOwned -> "scheduler_push_owned_terminal_corridor"

        let private replayQueueDrainDecisionText = function
            | ReplayQueueDrainNoQueue -> "no_queue"
            | ReplayQueueDrainActiveDriver -> "active_driver"
            | ReplayQueueDrainScheduleTick -> "schedule_tick"
            | ReplayQueueDrainLongWaitForceTick -> "long_wait_force_tick"

        let private replayQueueDrainDecisionFor queueDepth activeDepth waitedMs =
            if queueDepth <= 0 then ReplayQueueDrainNoQueue
            elif activeDepth > 0 then ReplayQueueDrainActiveDriver
            elif waitedMs >= 8000 then ReplayQueueDrainLongWaitForceTick
            else ReplayQueueDrainScheduleTick


        type QueueOnlyParentContinuationRecoveryDecisionId =
            | QueueOnlyParentContinuationRecoveryObserve
            | QueueOnlyParentContinuationRecoveryDeferRecentSemanticActivity
            | QueueOnlyParentContinuationRecoveryRejectTopology
            | QueueOnlyParentContinuationRecoveryReady


        // MIGRATION: compile-rescue for the destructive TerminalFlow migration.
        // The previous rounds placed the TerminalFlow observation/outcome/boundary
        // DUs inside DiagJson, but the queue-only recovery decision that consumes
        // them lives in BigStack.  F# does not leak sibling-module private DUs or
        // private render helpers across that boundary, so the compiler failed with
        // a wide FS0039 cascade at the BigStack use sites.  Keep the breakthrough
        // contract, but materialize a BigStack-local capsule so the deciding module
        // owns the phase vocabulary it consumes.  DiagJson may keep its renderer
        // copy as a legacy HUD boundary; this local copy is the authority surface
        // for queue-only recovery.
        // MIGRATION / destructive domain migration migration phase:
        // create the stricter TerminalFlow runway requested by the assessments.
        // This deliberately mirrors a GADT by phantom stage parameters.  A
        // renderer may erase these values to JSON/HUD strings, but terminal
        // decisions must move through these constructors rather than through
        // string Contains checks or an imperative "is QAP empty yet?" loop.
        type TerminalFlowRootPendingStage = interface end
        type TerminalFlowRootResolvedStage = interface end
        type TerminalFlowWriterPendingStage = interface end
        type TerminalFlowWriterBoundStage = interface end
        type TerminalFlowTailDeadlockedStage = interface end
        type TerminalFlowTailQuarantinedStage = interface end
        type TerminalFlowEmittedStage = interface end

        type TerminalFlowRootReceipt<'GraphKind,'Stage> = private {
            terminalFlowRootReceiptId : string
            semanticReceiptId : string option
            qapSnapshot : int * int * int
            ownerLedgerClosed : bool
        }

        type TerminalFlowTail<'GraphKind,'Stage> = private {
            terminalFlowTailId : string
            writerLeaseId : string
            blocker : string option
            qapSnapshot : int * int * int
            repeatCount : int64
        }

        type TerminalFlow<'GraphKind,'Stage> =
            | TerminalFlowBeforeRoot of TerminalFlowRootReceipt<'GraphKind,TerminalFlowRootPendingStage>
            | TerminalFlowAfterRoot of TerminalFlowRootReceipt<'GraphKind,TerminalFlowRootResolvedStage> * TerminalFlowTail<'GraphKind,TerminalFlowWriterPendingStage>
            | TerminalFlowWriterBound of TerminalFlowRootReceipt<'GraphKind,TerminalFlowRootResolvedStage> * TerminalFlowTail<'GraphKind,TerminalFlowWriterBoundStage> * writerReceiptId:string
            | TerminalFlowTailDeadlocked of TerminalFlowRootReceipt<'GraphKind,TerminalFlowRootResolvedStage> * TerminalFlowTail<'GraphKind,TerminalFlowTailDeadlockedStage> * proof:CompilerKernelV2.TerminalTailDeadlockProofId
            | TerminalFlowTailQuarantined of TerminalFlowRootReceipt<'GraphKind,TerminalFlowRootResolvedStage> * TerminalFlowTail<'GraphKind,TerminalFlowTailQuarantinedStage> * reason:CompilerKernelV2.TerminalTailQuarantineReasonId
            | TerminalFlowEmitted of terminalReceiptId:string

        type TerminalFlowExitGate<'GraphKind,'Stage> = private {
            flow : TerminalFlow<'GraphKind,'Stage>
            writerAltStatus : string
            qapResidualJobIds : string list
            terminalEmitBlocker : string option
        }

        // MIGRATION / destructive domain migration migration phase:
        // make the post-root terminal gate reason over typed observations, not
        // over scattered HUD strings.  DiagJson/HUD parsing is intentionally
        // quarantined to one adapter; every scheduler predicate below consumes
        // these DUs.  This is still an F# phantom/GADT simulation, but now the
        // runtime decision surface mirrors the assessment's TerminalFlow shape:
        // RootResolved -> WriterPending -> WriterBound | TailDeadlocked |
        // TailQuarantined | TerminalEmitted.
        type TerminalFlowRootObservationId =
            | TerminalFlowRootNotObserved
            | TerminalFlowRootPending
            | TerminalFlowRootResolved of receiptId:string
            | TerminalFlowRootResolvedWithoutReceipt of evidence:string

        type TerminalFlowWriterObservationId =
            | TerminalFlowWriterNotObserved
            | TerminalFlowWriterPending of leaseId:string
            | TerminalFlowWriterBlockedOnQap of leaseId:string
            | TerminalFlowWriterBoundObserved of writerReceiptId:string

        type TerminalFlowTailObservationId =
            | TerminalFlowTailUnknown
            | TerminalFlowTailPendingDrain of tailId:string
            | TerminalFlowTailDrained of tailId:string
            | TerminalFlowTailDeadlockedObserved of tailId:string * proof:CompilerKernelV2.TerminalTailDeadlockProofId
            | TerminalFlowTailQuarantinedObserved of tailId:string * reason:CompilerKernelV2.TerminalTailQuarantineReasonId
            | TerminalFlowTailTerminalEmittedObserved of receiptId:string

        type TerminalFlowOwnerObservationId =
            | TerminalFlowOwnersUnknown
            | TerminalFlowOwnersOpen of openCount:int64
            | TerminalFlowOwnersQuarantinable of openCount:int64 * reason:CompilerKernelV2.TerminalOwnerQuarantineReasonId
            | TerminalFlowOwnersWakerRegistrationRequired of openCount:int64 * obligationId:string
            | TerminalFlowOwnersWakerRegistrationRejected of openCount:int64 * obligationId:string * reason:CompilerKernelV2.TerminalOwnerWakerRejectionReasonId
            | TerminalFlowOwnersClosed
            | TerminalFlowOwnersStickyTerminalEligible

        // Semantic ledger state is projected from the single file-global
        // authority; terminal kernels do not own mutable ledger copies.

        type TerminalFlowQapBoundedness =
            | TerminalFlowQapBounded
            | TerminalFlowQapUnbounded

        type TerminalFlowQapOccupancy =
            | TerminalFlowQapEmpty
            | TerminalFlowQapResidual

        // Domain migration : pending is no longer an anonymous integer.  The
        // frontier snapshot owns terminal truth; sampled cache depth is evidence
        // only and may be reconciled away as a ghost without keeping QAP open.
        type TerminalFlowPendingLedgerAuthority =
            | TerminalFlowPendingFrontierAuthoritative
            | TerminalFlowPendingFrontierReconciledGhosts
            | TerminalFlowPendingFrontierUnavailableRawZeroClosed of closeReceiptRef:uint32
            | TerminalFlowPendingFrontierUnavailableReducerClosed of closeReceiptRef:uint32
            | TerminalFlowPendingFrontierUnavailableQuarantine of quarantineRef:uint32

        // Domain migration : sampled-pending decrements become exact-once
        // receipts.  Raw cache depth may explain ghosts, but only the frontier
        // count can decide terminal closure.
        type TerminalFlowPendingDecrementSource =
            | TerminalFlowPendingDecrementInlineCallbackCommit
            | TerminalFlowPendingDecrementReducerFrontierReconcile
            | TerminalFlowPendingDecrementReducerClosedProjection
            | TerminalFlowPendingDecrementParentCommit
            | TerminalFlowPendingDecrementUnknown of raw:string

        type TerminalFlowPendingDecrementReceipt = private {
            source : TerminalFlowPendingDecrementSource
            beforeRaw : int
            afterRaw : int
            frontierPending : int
            canonicalPending : int
            exactOnceRef : uint32
        }

        type TerminalFlowPendingQuarantineReason =
            | TerminalFlowPendingRejectedSyntheticObservation
            | TerminalFlowPendingFrontierSnapshotMissing

        type TerminalFlowPendingDecision =
            | TerminalFlowPendingDecisionFrontierCanonical of canonicalPending:int
            | TerminalFlowPendingDecisionRawZeroClosedWithoutFrontier of closeReceiptRef:uint32
            | TerminalFlowPendingDecisionReducerClosedWithoutFrontier of closeReceiptRef:uint32
            | TerminalFlowPendingDecisionBlockedWithoutFrontier of sampledEvidence:int * reason:TerminalFlowPendingQuarantineReason * quarantineRef:uint32

        type TerminalFlowPendingClosureProof =
            | TerminalFlowPendingClosureUnproven
            | TerminalFlowPendingClosureReducerExact of closeReceiptRef:uint32

        type TerminalFlowPendingProvenance = private {
            rawPending : int
            frontierPending : int
            canonicalPending : int
            authority : TerminalFlowPendingLedgerAuthority
            decrementReceipts : TerminalFlowPendingDecrementReceipt list
            decision : TerminalFlowPendingDecision
        }

        type TerminalFlowQapFixpointMaturity =
            | TerminalFlowQapFixpointAwaitingReducerWitness
            | TerminalFlowQapFixpointCandidateObserved
            | TerminalFlowQapFixpointWitnessedByReducer

        type TerminalFlowQapObservation = private {
            pending : int
            pendingProvenance : TerminalFlowPendingProvenance
            queue : int
            active : int
            semanticLedgerState : SemanticWorkOpenState
            semanticOpen : int64
            boundedness : TerminalFlowQapBoundedness
            occupancy : TerminalFlowQapOccupancy
        }

        // Projection identity is typed separately from human rendering.
        // QAP replay is no longer modelled as anonymous procedural churn.  The
        // recurring cache_handoff children that kept the terminal gate alive are
        // captured as a typed fixpoint set with its own identity kind, maturity
        // witness and terminal decision.  Renderers may erase this to strings,
        // but scheduler logic now has a domain object for bounded residual QAP.
        [<AbstractClass; Sealed>]
        type TerminalFlowQapFixpointItemRefKind private () =
            static member InternedKindTag () = 0x190001u

        [<AbstractClass; Sealed>]
        type TerminalFlowQapFixpointSetRefKind private () =
            static member InternedKindTag () = 0x190002u

        type TerminalFlowQapFixpointRef<'Kind> =
            private
            | TerminalFlowQapFixpointRef of CompilerIdentityKernel.InternedTextId<'Kind>

        let inline private terminalFlowQapFixpointRefCreate< ^Kind when ^Kind : (static member InternedKindTag : unit -> uint32)> value : TerminalFlowQapFixpointRef< ^Kind> =
            value
            |> CompilerIdentityKernel.InternedTextId.create< ^Kind>
            |> TerminalFlowQapFixpointRef

        type TerminalFlowQapUnknownTextKind private () =
            static member InternedKindTag () = 0x190003u

        type TerminalFlowQapUnknownTextId =
            CompilerIdentityKernel.InternedTextId<TerminalFlowQapUnknownTextKind>

        module TerminalFlowQapUnknownTextIdOps =
            let create value : TerminalFlowQapUnknownTextId =
                CompilerIdentityKernel.InternedTextId.create<TerminalFlowQapUnknownTextKind> value

            let text (value:TerminalFlowQapUnknownTextId) =
                CompilerIdentityKernel.InternedTextId.text value

        type TerminalFlowQapFixpointSiteId =
            | TerminalFlowQapCacheHandoffApplyArg0Child
            | TerminalFlowQapParentContinuationPoison
            | TerminalFlowQapDynamicBridgePoison
            | TerminalFlowQapPendingOwner
            | TerminalFlowQapUnknownSite of raw:TerminalFlowQapUnknownTextId

        type TerminalFlowQapNodeId =
            | TerminalFlowQapCacheHandoffChildApplyArg0Node
            | TerminalFlowQapParentPoisonTerminalTailNode
            | TerminalFlowQapPendingOwnerTerminalTailNode
            | TerminalFlowQapUnknownNode of raw:TerminalFlowQapUnknownTextId

        type TerminalFlowQapEvidenceWitness =
            | TerminalFlowQapPrimaryFixpointWitness
            | TerminalFlowQapActiveTailWitness
            | TerminalFlowQapPendingOwnerWitness
            | TerminalFlowQapUnknownWitness of raw:TerminalFlowQapUnknownTextId

        // Domain migration : model the recurring parent-poison/cache-handoff
        // structure as a recursive relationship rather than parallel strings.
        type TerminalFlowQapRelationKind =
            | TerminalFlowQapCacheHandoffEdge
            | TerminalFlowQapParentContinuationEdge
            | TerminalFlowQapDynamicBridgeEdge
            | TerminalFlowQapPendingOwnerEdge

        type TerminalFlowQapRelationRejectionReasonId =
            private
            | TerminalFlowQapRelationRejectionReasonId of CompilerKernelV2.OperationalReasonId

        module TerminalFlowQapRelationRejectionReasonId =
            let create reason =
                reason
                |> CompilerKernelV2.OperationalReasonIdOps.create
                |> TerminalFlowQapRelationRejectionReasonId

            let text (TerminalFlowQapRelationRejectionReasonId reason) =
                CompilerKernelV2.OperationalReasonIdOps.text reason

        type TerminalFlowQapRelationConsumption =
            | TerminalFlowQapRelationUnconsumed
            | TerminalFlowQapRelationConsumedExactOnce of receiptRef:uint32 * reducerSequence:int64
            | TerminalFlowQapRelationConsumptionRejected of reason:TerminalFlowQapRelationRejectionReasonId

        type TerminalFlowQapRelation =
            | TerminalFlowQapRelationLeaf of node:TerminalFlowQapNodeId * witness:TerminalFlowQapEvidenceWitness * consumption:TerminalFlowQapRelationConsumption
            | TerminalFlowQapRelationParentChild of parent:TerminalFlowQapNodeId * edge:TerminalFlowQapRelationKind * child:TerminalFlowQapRelation * consumption:TerminalFlowQapRelationConsumption
            | TerminalFlowQapRelationCycle of head:TerminalFlowQapNodeId * edge:TerminalFlowQapRelationKind * path:TerminalFlowQapRelation list * consumption:TerminalFlowQapRelationConsumption

        type TerminalFlowQapRelationProtocolState =
            | TerminalFlowQapRelationProtocolObserved of relation:TerminalFlowQapRelation
            | TerminalFlowQapRelationProtocolCanonicalized of relation:TerminalFlowQapRelation * canonicalRef:uint32
            | TerminalFlowQapRelationProtocolConsumed of relation:TerminalFlowQapRelation * receiptRef:uint32
            | TerminalFlowQapRelationProtocolClosed of relation:TerminalFlowQapRelation * closeCertificateRef:uint32
            | TerminalFlowQapRelationProtocolPoisoned of relation:TerminalFlowQapRelation * blocker:TerminalFlowQapUnknownTextId

        type TerminalFlowQapTerminalDecision =
            | TerminalFlowQapAwaitMaterialOrWaker
            | TerminalFlowQapCandidateTerminalErrorOrQuarantine
            | TerminalFlowQapAwaitReducerFourClockWitness

        type TerminalFlowQapFixpointItem = private {
            itemRef : TerminalFlowQapFixpointRef<TerminalFlowQapFixpointItemRefKind>
            site : TerminalFlowQapFixpointSiteId
            nodeId : TerminalFlowQapNodeId
            relation : TerminalFlowQapRelation
            repeatCount : int64
            repeatCap : int64
            materialDelta : int64
            lastWitness : TerminalFlowQapEvidenceWitness
        }

        type TerminalFlowQapFixpointSet = private {
            setRef : TerminalFlowQapFixpointRef<TerminalFlowQapFixpointSetRefKind>
            items : TerminalFlowQapFixpointItem list
            materialQuiescenceAgeMs : int64
            maturity : TerminalFlowQapFixpointMaturity
            terminalDecision : TerminalFlowQapTerminalDecision
        }

        // MIGRATION: the only residual cycle promoted by this recovery tranche.
        // It is structural and total: two exact QAP sites, both past their repeat
        // caps, both with zero material delta.  Generic queue pressure cannot
        // manufacture this state.
        type TerminalFlowQapResidualCycleClass =
            | TerminalFlowQapResidualCycleNotApplicable
            | TerminalFlowQapResidualCycleCacheHandoffParentPoison of repeatFloor:int64 * repeatCap:int64

        let private terminalFlowQapResidualCycleClassFor (fixpoint:TerminalFlowQapFixpointSet) =
            let itemClosed (item:TerminalFlowQapFixpointItem) =
                let rec consumed = function
                    | TerminalFlowQapRelationLeaf(_, _, TerminalFlowQapRelationConsumedExactOnce _)
                    | TerminalFlowQapRelationParentChild(_, _, _, TerminalFlowQapRelationConsumedExactOnce _)
                    | TerminalFlowQapRelationCycle(_, _, _, TerminalFlowQapRelationConsumedExactOnce _) -> true
                    | _ -> false
                consumed item.relation
            let hasSite site =
                fixpoint.items |> List.exists (fun (item:TerminalFlowQapFixpointItem) -> item.site = site)
            if List.length fixpoint.items = 2
               && (fixpoint.items |> List.forall itemClosed)
               && hasSite TerminalFlowQapCacheHandoffApplyArg0Child
               && hasSite TerminalFlowQapParentContinuationPoison then
                let repeatFloor = fixpoint.items |> List.map (fun (item:TerminalFlowQapFixpointItem) -> item.repeatCount) |> List.min
                let repeatCap = fixpoint.items |> List.map (fun (item:TerminalFlowQapFixpointItem) -> item.repeatCap) |> List.max
                TerminalFlowQapResidualCycleCacheHandoffParentPoison(repeatFloor, repeatCap)
            else
                TerminalFlowQapResidualCycleNotApplicable

        let private terminalFlowQapResidualCycleClassText = function
            | TerminalFlowQapResidualCycleNotApplicable -> "NotApplicable"
            | TerminalFlowQapResidualCycleCacheHandoffParentPoison(repeatFloor, repeatCap) ->
                sprintf "CacheHandoffParentPoison(repeat_floor=%d|repeat_cap=%d)" repeatFloor repeatCap

        // MIGRATION: this local TerminalFlow copy is projection-only. It may render
        // or adapt legacy observations, but only TerminalFlowBreakthrough may advance
        // QAP, owner-tail, semantic, covenant, terminal-order or exit authority.
        type TerminalFlowLegacyMirrorAuthority =
            | TerminalFlowLegacyMirrorProjectionOnly

        // MIGRATION / destructive migration migration phase:
        // A fixpoint observation is not itself a terminal fact. The reducer must
        // return one of three staged resolutions, and only the Deadlocked/Drained
        // branches carry the proof receipts required to mature a terminal outcome.
        type TerminalFlowQapAwaitingMaterialStage = class end
        type TerminalFlowQapProgressingStage = class end
        type TerminalFlowQapDrainedStage = class end
        type TerminalFlowQapDeadlockedStage = class end

        [<Struct>]
        type TerminalFlowQapProtocolId<'Kind> = private | TerminalFlowQapProtocolId of uint64

        let private terminalFlowQapLocalMintedRefOf kind payload =
            NativeCutoverStableRef.ref32
                "terminal-flow-qap-local"
                [ kind; payload ]

        [<Struct>]
        type TerminalFlowQapRelationResolutionReceiptRefKind = struct end

        [<Struct>]
        type TerminalFlowQapDrainProofRefKind = struct end

        [<Struct>]
        type TerminalFlowQapDeadlockProofRefKind = struct end

        type TerminalFlowQapRelationResolution =
            | TerminalFlowQapRelationRegistered of relationRef:uint32 * wakerRef:uint32 option
            | TerminalFlowQapRelationConsumed of relationRef:uint32 * consumeReceiptRef:uint32
            | TerminalFlowQapRelationDeadlocked of relationRef:uint32 * deadlockReceiptRef:uint32
            | TerminalFlowQapRelationQuarantined of relationRef:uint32 * quarantineReceiptRef:uint32

        let private terminalFlowQapRelationResolutionText (resolution:TerminalFlowQapRelationResolution) =
            match resolution with
            | TerminalFlowQapRelationRegistered(relationRef, wakerRef) ->
                sprintf "Registered(relation_ref=%u|waker_ref=%s)" relationRef (wakerRef |> Option.map string |> Option.defaultValue "none")
            | TerminalFlowQapRelationConsumed(relationRef, consumeReceiptRef) ->
                sprintf "Consumed(relation_ref=%u|consume_receipt_ref=%u)" relationRef consumeReceiptRef
            | TerminalFlowQapRelationDeadlocked(relationRef, deadlockReceiptRef) ->
                sprintf "Deadlocked(relation_ref=%u|deadlock_receipt_ref=%u)" relationRef deadlockReceiptRef
            | TerminalFlowQapRelationQuarantined(relationRef, quarantineReceiptRef) ->
                sprintf "Quarantined(relation_ref=%u|quarantine_receipt_ref=%u)" relationRef quarantineReceiptRef

        type TerminalFlowQapRelationResolutionReceipt = private {
            receiptRef : TerminalFlowQapProtocolId<TerminalFlowQapRelationResolutionReceiptRefKind>
            relationRef : uint32
            resolution : TerminalFlowQapRelationResolution
            materialEpochBefore : int64
            materialEpochAfter : int64
            reducerSequence : int64
        }

        type TerminalFlowQapNoPendingRebaseWitness = private | TerminalFlowQapNoPendingRebaseWitness of reducerSequence:int64

        type TerminalFlowQapDrainAuthority =
            | TerminalFlowQapDrainByEmptyRelationSet
            | TerminalFlowQapDrainByExactOnceConsumption of relationCount:int

        let private terminalFlowQapDrainAuthorityText = function
            | TerminalFlowQapDrainByEmptyRelationSet -> "empty_relation_set"
            | TerminalFlowQapDrainByExactOnceConsumption relationCount -> sprintf "exact_once_consumed:%d" relationCount

        type TerminalFlowQapDrainProof<'Kind> = private {
            proofRef : TerminalFlowQapProtocolId<TerminalFlowQapDrainProofRefKind>
            qapRef : TerminalFlowQapProtocolId<'Kind>
            relationReceipts : TerminalFlowQapRelationResolutionReceipt list
            drainAuthority : TerminalFlowQapDrainAuthority
            materialEpoch : int64
            reducerSequence : int64
        }

        type TerminalFlowQapQuiescenceWitness = private | TerminalFlowQapQuiescenceWitness of creditDigest:CompilerIdentityKernel.ContentDigest

        type TerminalFlowQapDeadlockProof<'Kind> = private {
            proofRef : TerminalFlowQapProtocolId<TerminalFlowQapDeadlockProofRefKind>
            qapRef : TerminalFlowQapProtocolId<'Kind>
            quiescence : TerminalFlowQapQuiescenceWitness
            noPendingRebase : TerminalFlowQapNoPendingRebaseWitness
            relationReceipts : TerminalFlowQapRelationResolutionReceipt list
            reducerSequence : int64
        }

        type TerminalFlowQap<'Kind,'Stage> = private {
            qapRef : TerminalFlowQapProtocolId<'Kind>
            semanticDigestRef : uint32
            proceduralDigestRef : uint32
            relationSetRef : uint32
            materialEpoch : int64
            relations : TerminalFlowQapRelation list
            fixpoint : TerminalFlowQapFixpointSet
        }

        type TerminalFlowQapResolution<'Kind> =
            | TerminalFlowQapMaterialProgress of TerminalFlowQap<'Kind,TerminalFlowQapProgressingStage>
            | TerminalFlowQapFullyDrained of TerminalFlowQap<'Kind,TerminalFlowQapDrainedStage> * TerminalFlowQapDrainProof<'Kind>
            | TerminalFlowQapProvenDeadlock of TerminalFlowQap<'Kind,TerminalFlowQapDeadlockedStage> * TerminalFlowQapDeadlockProof<'Kind>

        type TerminalFlowQapResolutionBox =
            | TerminalFlowQapMaterialProgressBox of TerminalFlowQap<TerminalFlowQapFixpointSetRefKind,TerminalFlowQapProgressingStage>
            | TerminalFlowQapFullyDrainedBox of TerminalFlowQap<TerminalFlowQapFixpointSetRefKind,TerminalFlowQapDrainedStage> * TerminalFlowQapDrainProof<TerminalFlowQapFixpointSetRefKind>
            | TerminalFlowQapProvenDeadlockBox of TerminalFlowQap<TerminalFlowQapFixpointSetRefKind,TerminalFlowQapDeadlockedStage> * TerminalFlowQapDeadlockProof<TerminalFlowQapFixpointSetRefKind>

        // Every new seal requirement names the capability that can mint it.
        // A requirement without a minter is now a malformed domain value.
        type TerminalFlowQapDeadlockCredential = class end
        type TerminalFlowQapDrainCredential = class end
        type TerminalFlowOutcomeMaturityCredential = class end
        type TerminalFlowHostShutdownFinalizationCredential = class end

        type TerminalFlowMinterCapability<'Credential> = private {
            minterRef : uint32
            reducerOwned : bool
            exactOnceRef : uint32
        }

        type TerminalFlowSealRequirement<'Credential> = private {
            requirementRef : uint32
            minter : TerminalFlowMinterCapability<'Credential>
            predecessorRef : uint32 option
        }

        // Destructive typed terminal-server migration:
        // material authority and procedural churn are different types.  A replay
        // yield, boundary echo, owner-drain wake or terminal/root counter cannot
        // be passed to the material defer branch.  The phantom parameter keeps
        // that distinction at compile time while the DU keeps the runtime shape
        // inspectable without parsing HUD text back into authority.
        [<Struct>]
        type TerminalFlowMaterialActivityKind = struct end

        [<Struct>]
        type TerminalFlowProceduralActivityKind = struct end

        [<AbstractClass; Sealed>]
        type TerminalFlowRootReceiptRefKind private () =
            static member IdentityKindTag () = 0x0A0001u

        [<AbstractClass; Sealed>]
        type TerminalFlowWriterReceiptRefKind private () =
            static member IdentityKindTag () = 0x0A0002u

        [<AbstractClass; Sealed>]
        type TerminalFlowTerminalReceiptRefKind private () =
            static member IdentityKindTag () = 0x01000Eu

        type TerminalFlowReceiptRef<'Kind> =
            | TerminalFlowReceiptMissing
            | TerminalFlowReceiptPresent of value:string

        type TerminalFlowMaterialActivitySourceId =
            | TerminalFlowMaterialDelta
            | TerminalFlowFreshTopologyWitness

        type TerminalFlowProceduralActivitySourceId =
            | TerminalFlowReplayChatter
            | TerminalFlowOwnerDrainSelfChurn
            | TerminalFlowBoundaryTelemetryEcho
            | TerminalFlowRootSignalChurn
            | TerminalFlowTerminalSignalChurn
            | TerminalFlowInjectionChurn

        type TerminalFlowActivityToken<'Kind,'Source> = private {
            source : 'Source
            ageMs : int64
            count : int64
        }

        type TerminalFlowActivityObservationId =
            | TerminalFlowMaterialActivityRecent of TerminalFlowActivityToken<TerminalFlowMaterialActivityKind,TerminalFlowMaterialActivitySourceId>
            | TerminalFlowMaterialQuiescent of materialAgeMs:int64 * procedural:TerminalFlowActivityToken<TerminalFlowProceduralActivityKind,TerminalFlowProceduralActivitySourceId> option

        type TerminalFlowObservation = private {
            root : TerminalFlowRootObservationId
            writer : TerminalFlowWriterObservationId
            tail : TerminalFlowTailObservationId
            owners : TerminalFlowOwnerObservationId
            qap : TerminalFlowQapObservation
            activity : TerminalFlowActivityObservationId
        }

        // Shared in the enclosing compiler module; this scope is projection/consumer only.

        let private terminalFlowWakerRegistrationStatusText = function
            | TerminalFlowWakerMissing -> "missing"
            | TerminalFlowWakerRegistered(obligationId, registeredAtMs) -> sprintf "registered:%s@%d" obligationId registeredAtMs
            | TerminalFlowWakerExpired(obligationId, ageMs) -> sprintf "expired:%s@%d" obligationId ageMs

        let private terminalFlowWakerRegistrySourceText = function
            | TerminalFlowWakerRegistryStageToken -> "stage_token"
            | TerminalFlowWakerRegistryStickyTail -> "sticky_tail"
            | TerminalFlowWakerRegistryShutdownHook -> "shutdown_hook"

        let private terminalFlowWakerRegistryVerdictFor source = function
            | TerminalFlowWakerMissing -> TerminalFlowWakerRegistryMissing source
            | TerminalFlowWakerRegistered(obligationId, registeredAtMs) -> TerminalFlowWakerRegistryRegistered(source, obligationId, registeredAtMs)
            | TerminalFlowWakerExpired(obligationId, ageMs) -> TerminalFlowWakerRegistryExpired(source, obligationId, ageMs)

        let private terminalFlowWakerRegistryVerdictText = function
            | TerminalFlowWakerRegistryMissing source -> "missing:" + terminalFlowWakerRegistrySourceText source
            | TerminalFlowWakerRegistryRegistered(source, obligationId, registeredAtMs) -> FastRuntimeFormat.format "registered:%s:%s@%d" [| box (terminalFlowWakerRegistrySourceText source); box obligationId; box registeredAtMs |]
            | TerminalFlowWakerRegistryExpired(source, obligationId, ageMs) -> FastRuntimeFormat.format "expired:%s:%s@%d" [| box (terminalFlowWakerRegistrySourceText source); box obligationId; box ageMs |]
            | TerminalFlowWakerRegistryObservedByAltChoose(source, obligationRef) -> sprintf "observed_by_alt_choose:%s:%u" (terminalFlowWakerRegistrySourceText source) obligationRef

        let private terminalFlowProceduralResidualOwnerText (owner:TerminalFlowProceduralResidualOwner<'Phase>) =
            FastRuntimeFormat.format "ProceduralResidualOwner(id=%s|close_key=%s|depth=%d|pass=%d|material_delta=%d|repeat_cap=%d|waker=%s)" [| box owner.ownerId; box owner.closeKey; box owner.depth; box owner.drainPassCount; box owner.materialDeltaOnPass; box owner.fixedPointRepeatCap; box (terminalFlowWakerRegistrationStatusText owner.wakerStatus) |]

        let private terminalFlowStickyTailSnapshotText (snapshot:TerminalFlowStickyTailSnapshot) =
            FastRuntimeFormat.format "TerminalFlowStickyTailSnapshot(tail=%s|mutating_depth=%d|procedural_depth=%d|qap=%d/%d/%d|fixed_point_repeat=%d|procedural_pass=%d|procedural_material_delta=%d|repeat_cap=%d|material_quiescence_age_ms=%d|evaluator_frontier_resolved=%b|waker=%s|aggregate_armed=%b|mutating_drained=%b|evidence=%s)" [| box snapshot.tailId; box snapshot.mutatingDepth; box snapshot.proceduralDepth; box snapshot.globalPending; box snapshot.globalQueue; box snapshot.globalActive; box snapshot.fixedPointRepeat; box snapshot.proceduralDrainPassCount; box snapshot.materialDeltaOnProceduralPass; box snapshot.fixedPointRepeatCap; box snapshot.materialQuiescenceAgeMs; box snapshot.evaluatorFrontierResolved; box (terminalFlowWakerRegistrationStatusText snapshot.wakerStatus); box snapshot.aggregatePromiseArmed; box snapshot.mutatingTailDrained; box snapshot.evidence |]

        let private terminalFlowStickyTailGateText (gate:TerminalFlowStickyTailGateId) =
            match gate with
            | TerminalFlowStickyTailAwaitMutatingAggregate snapshot -> "TerminalFlowStickyTailGate(AwaitMutatingAggregate|" + terminalFlowStickyTailSnapshotText snapshot + ")"
            | TerminalFlowStickyTailWriterReady(snapshot, None) -> "TerminalFlowStickyTailGate(WriterReady|procedural=none|" + terminalFlowStickyTailSnapshotText snapshot + ")"
            | TerminalFlowStickyTailWriterReady(snapshot, Some owner) -> "TerminalFlowStickyTailGate(WriterReady|" + terminalFlowProceduralResidualOwnerText owner + "|" + terminalFlowStickyTailSnapshotText snapshot + ")"
            | TerminalFlowStickyTailDrained snapshot -> "TerminalFlowStickyTailGate(Drained|" + terminalFlowStickyTailSnapshotText snapshot + ")"
            | TerminalFlowStickyTailQuarantineProceduralResidual(snapshot, reason) -> "TerminalFlowStickyTailGate(QuarantineProceduralResidual|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|" + terminalFlowStickyTailSnapshotText snapshot + ")"
            | TerminalFlowStickyTailRejectUnboundedMutatingTail(snapshot, reason) -> "TerminalFlowStickyTailGate(RejectUnboundedMutatingTail|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|" + terminalFlowStickyTailSnapshotText snapshot + ")"

        let private terminalFlowStickyTailGateShouldWake (gate:TerminalFlowStickyTailGateId) =
            match gate with
            | TerminalFlowStickyTailAwaitMutatingAggregate snapshot -> snapshot.aggregatePromiseArmed || (snapshot.mutatingTailDrained && snapshot.mutatingDepth = 0)
            | TerminalFlowStickyTailWriterReady _ -> true
            | TerminalFlowStickyTailDrained _ -> true
            | TerminalFlowStickyTailQuarantineProceduralResidual _ -> true
            | TerminalFlowStickyTailRejectUnboundedMutatingTail _ -> true

        type TerminalFlowTransitionDecisionId =
            | TerminalFlowTransitionObserve
            | TerminalFlowTransitionDeferMaterialActivity of TerminalFlowActivityToken<TerminalFlowMaterialActivityKind,TerminalFlowMaterialActivitySourceId>
            | TerminalFlowTransitionRejectTopology of qap:TerminalFlowQapObservation
            | TerminalFlowTransitionRegisterWakerEdge of rootReceipt:string * leaseId:string * tailId:string * obligationId:string * nextWakeAfterMs:int64
            | TerminalFlowTransitionWriterLeaseLive of rootReceipt:string * leaseId:string * tailId:string * ageMs:int64
            | TerminalFlowTransitionWriterLeaseExpired of rootReceipt:string * leaseId:string * tailId:string * ageMs:int64 * qap:TerminalFlowQapObservation
            | TerminalFlowTransitionQuarantineResidualQap of rootReceipt:string * leaseId:string * tailId:string * ageMs:int64 * qap:TerminalFlowQapObservation
            | TerminalFlowTransitionQapFixpointMatured of rootReceipt:string * leaseId:string * tailId:string * fixpoint:TerminalFlowQapFixpointSet
            | TerminalFlowTransitionQapFixpointAwaitingMaterial of rootReceipt:string * leaseId:string * tailId:string * fixpoint:TerminalFlowQapFixpointSet
            | TerminalFlowTransitionForceCloseResidual of rootReceipt:string * leaseId:string * tailId:string * ownerCloseReceiptId:string * workDagTailCloseReceipt:string
            | TerminalFlowTransitionBindWriter of rootReceipt:string * writerReceiptId:string * tailId:string
            | TerminalFlowTransitionDeadlockTail of rootReceipt:string * leaseId:string * tailId:string * proof:CompilerKernelV2.TerminalTailDeadlockProofId
            | TerminalFlowTransitionQuarantineTail of rootReceipt:string * leaseId:string * tailId:string * reason:CompilerKernelV2.TerminalTailQuarantineReasonId
            | TerminalFlowTransitionTerminalEmitted of terminalReceiptId:string

        // MIGRATION / destructive domain migration migration phase:
        // a transition is no longer enough evidence.  Every post-root writer-tail
        // transition must project into an outcome category that can feed the
        // terminal certificate boundary: WriterBound, TailDeadlocked,
        // TailQuarantined, TerminalEmitted, or a still-live bounded lease.
        type TerminalFlowAwaitingObservationReasonId =
            | TerminalFlowAwaitingQapFixpointMaterial of rootReceipt:string * leaseId:string * tailId:string * fixpoint:TerminalFlowQapFixpointSet
            | TerminalFlowAwaitingRecentMaterialActivity of TerminalFlowActivityToken<TerminalFlowMaterialActivityKind,TerminalFlowMaterialActivitySourceId>
            | TerminalFlowAwaitingRejectedTopology of qap:TerminalFlowQapObservation
            | TerminalFlowAwaitingWakerRegistrationRequired of leaseId:string * tailId:string * obligationId:string * nextWakeAfterMs:int64
            | TerminalFlowAwaitingWriterLeaseLive of leaseId:string * tailId:string * ageMs:int64
            | TerminalFlowAwaitingGenericObservation
            | TerminalFlowAwaitingOperationalReason of CompilerKernelV2.OperationalReasonId

        type TerminalFlowOutcomeId =
            | TerminalFlowOutcomeAwaitingObservation of reason:TerminalFlowAwaitingObservationReasonId
            | TerminalFlowOutcomeWakerRegistrationRequired of rootReceipt:string * leaseId:string * tailId:string * obligationId:string * nextWakeAfterMs:int64
            | TerminalFlowOutcomeWriterLeaseStillLive of rootReceipt:string * leaseId:string * tailId:string * ageMs:int64
            | TerminalFlowOutcomeWriterBound of rootReceipt:string * writerReceiptId:string * tailId:string
            | TerminalFlowOutcomeTailDeadlocked of rootReceipt:string * leaseId:string * tailId:string * proof:CompilerKernelV2.TerminalTailDeadlockProofId
            | TerminalFlowOutcomeTailQuarantined of rootReceipt:string * leaseId:string * tailId:string * reason:CompilerKernelV2.TerminalTailQuarantineReasonId
            | TerminalFlowOutcomeTerminalEmitted of terminalReceiptId:string

        type TerminalFlowCertificateIntentId =
            | TerminalFlowCertificateAwaiting of reason:TerminalFlowAwaitingObservationReasonId
            | TerminalFlowCertificateBuildOk of rootReceipt:string * writerReceiptId:string * tailId:string
            | TerminalFlowCertificateBuildError of rootReceipt:string * leaseId:string * tailId:string * proof:CompilerKernelV2.TerminalTailDeadlockProofId
            | TerminalFlowCertificateNoFurther of terminalReceiptId:string
            | TerminalFlowCertificateQuarantine of rootReceipt:string * leaseId:string * tailId:string * reason:CompilerKernelV2.TerminalTailQuarantineReasonId

        // MIGRATION / destructive domain migration migration phase:
        // intent is no longer an endpoint.  Every terminal-flow outcome must
        // either mint a top-level receipt/certificate identifier or explain why
        // no terminal commit is legal yet.  This is deliberately stricter than
        // the HUD: a renderer may display the text, but the queue-only recovery
        // predicate consumes this boundary DU so terminal-like outcomes cannot
        // silently fall back into KeepDraining.
        type TerminalFlowWhyNotTerminalCommitId =
            | TerminalFlowWhyNotAwaitingBoundedLease of leaseId:string * tailId:string * ageMs:int64
            | TerminalFlowWhyNotAwaitingObservation of reason:TerminalFlowAwaitingObservationReasonId
            | TerminalFlowWhyNotWakerRegistrationRequired of obligationId:string * nextWakeAfterMs:int64
            | TerminalFlowWhyNotMissingRootReceipt of evidence:string
            | TerminalFlowWhyNotRecentMaterialActivity of TerminalFlowActivityToken<TerminalFlowMaterialActivityKind,TerminalFlowMaterialActivitySourceId>
            | TerminalFlowWhyNotRejectedTopology of qap:TerminalFlowQapObservation
            | TerminalFlowWhyNotMissingWriterReceipt of rootReceipt:string * tailId:string
            | TerminalFlowWhyNotObserverOnly of reason:CompilerKernelV2.OperationalReasonId

        type TerminalFlowTopLevelReceiptId =
            | TerminalFlowTopLevelBuildOkReceipt of terminalReceiptId:string * rootReceipt:string * writerReceiptId:string * tailId:string
            | TerminalFlowTopLevelBuildErrorCertificate of terminalReceiptId:string * rootReceipt:string * leaseId:string * tailId:string * proof:CompilerKernelV2.TerminalTailDeadlockProofId
            | TerminalFlowTopLevelNoFurtherCertificate of terminalReceiptId:string
            | TerminalFlowTopLevelQuarantineCertificate of terminalReceiptId:string * rootReceipt:string * leaseId:string * tailId:string * reason:CompilerKernelV2.TerminalTailQuarantineReasonId

        type TerminalFlowCertificateBoundaryId =
            | TerminalFlowBoundaryReceipt of TerminalFlowTopLevelReceiptId
            | TerminalFlowBoundaryWhyNotCommit of TerminalFlowWhyNotTerminalCommitId

        // MIGRATION / destructive bonus migration phase:
        // the boundary is no longer just a rendered proof.  It is promoted into
        // a post-root action obligation so the scheduler can distinguish
        // receipt-bearing terminal authority from bounded why-not evidence.
        // This is the breakthrough-level seam requested by the assessments:
        // every RootResolved writer-tail path either has a top-level receipt or
        // an exact typed reason that prevents terminal commit.
        type TerminalFlowBoundaryActionId =
            | TerminalFlowBoundaryActionEmitReceipt of TerminalFlowTopLevelReceiptId
            | TerminalFlowBoundaryActionBlockCommit of TerminalFlowWhyNotTerminalCommitId
            | TerminalFlowBoundaryActionFatalMissingBoundary of reason:CompilerKernelV2.OperationalReasonId

        [<Struct>]
        type TerminalFlowOutcomeOpenState = struct end

        [<Struct>]
        type TerminalFlowOutcomeSealedState = struct end

        [<Struct>]
        type TerminalFlowOutcomeEmittedState = struct end

        type TerminalFlowPhysicalExitIntentId =
            | TerminalFlowPhysicalExitBlockedUntilReceipt of CompilerKernelV2.OperationalReasonId
            | TerminalFlowPhysicalExitBlockedByWhyNot of TerminalFlowWhyNotTerminalCommitId
            | TerminalFlowPhysicalExitAllowedAfterDurableReceipt of receiptId:string

        type TerminalFlowTerminalOutcome<'State> = private {
            boundary : TerminalFlowCertificateBoundaryId
            stickyTailGate : TerminalFlowStickyTailGateId
            receiptId : string
            receiptDurable : bool
            ivarFillOnceKey : string
            physicalExitIntent : TerminalFlowPhysicalExitIntentId
        }

        type TerminalFlowTerminalOutcomeBox =
            | TerminalFlowTerminalOutcomeOpen of TerminalFlowTerminalOutcome<TerminalFlowOutcomeOpenState>
            | TerminalFlowTerminalOutcomeSealed of TerminalFlowTerminalOutcome<TerminalFlowOutcomeSealedState>
            | TerminalFlowTerminalOutcomeEmitted of TerminalFlowTerminalOutcome<TerminalFlowOutcomeEmittedState>
        // MIGRATION / destructive domain migration migration phase:
        // The post-root path is promoted from an observed gate into a capability spine.
        // These phantom stages and private constructors make the root -> outcome -> writer
        // ordering explicit. The legacy gate may render this spine, but it no longer owns it.
        [<Struct>]
        type TerminalFlowRootUnresolvedState = struct end

        [<Struct>]
        type TerminalFlowRootResolvedState = struct end

        [<Struct>]
        type TerminalFlowOutcomeUnfilledState = struct end

        [<Struct>]
        type TerminalFlowOutcomeFilledState = struct end

        [<Struct>]
        type TerminalFlowWriterUnboundState = struct end

        [<Struct>]
        type TerminalFlowWriterBoundState = struct end

        // MIGRATION : TerminalFlow no longer owns a parallel
        // owner-kind universe. Parent/cross/sidecar/join/dynamic/poison/procedural
        // identities are the same phantom kinds used by RecursiveOwnerLedger.
        // This makes a close key portable only inside its exact ledger kind.
        [<Struct>]
        type TerminalFlowOwnerWakeUnregisteredState = struct end

        [<Struct>]
        type TerminalFlowOwnerWakeRegisteredState = struct end

        [<Struct>]
        type TerminalFlowOwnerWakeObservedState = struct end

        type TerminalFlowOwnerLease = private {
            leaseId : string
            expiryPass : int
        }

        // Destructive domain migration: causal identities are
        // phantom-kind indexed before they enter consensus.  A terminal receipt,
        // fill key, dispatch id or artifact id can no longer be supplied to a
        // root-to-root comparison without an explicit (and therefore reviewable)
        // boundary conversion.
        type TerminalFlowCanonicalRootRefKind private () =
            static member IdentityKindTag () = 0x010001u
        // Reuse the existing TerminalFlowTerminalReceiptRefKind marker already defined for receipt refs.
        type TerminalFlowFillRefKind private () =
            static member IdentityKindTag () = 0x010002u
        type TerminalFlowDispatchRefKind private () =
            static member IdentityKindTag () = 0x010003u
        type TerminalFlowArtifactManifestRefKind private () =
            static member IdentityKindTag () = 0x010004u
        type TerminalFlowProgressSnapshotRefKind private () =
            static member IdentityKindTag () = 0x010005u
        type TerminalFlowWorkLedgerRefKind private () =
            static member IdentityKindTag () = 0x010006u
        type TerminalFlowCicArenaRefKind private () =
            static member IdentityKindTag () = 0x010007u
        type TerminalFlowTopologyGateRefKind private () =
            static member IdentityKindTag () = 0x010008u
        type TerminalFlowWatchdogPetitionRefKind private () =
            static member IdentityKindTag () = 0x010009u
        type TerminalFlowSemanticFrontierDigestRefKind private () =
            static member IdentityKindTag () = 0x01000Au
        type TerminalFlowProceduralFrontierDigestRefKind private () =
            static member IdentityKindTag () = 0x01000Bu
        type TerminalFlowQueueItemRefKind private () =
            static member IdentityKindTag () = 0x01000Cu
        type TerminalFlowQueueProducerRefKind private () =
            static member IdentityKindTag () = 0x01000Du
        type TerminalFlowExactOnceRefKind private () =
            static member IdentityKindTag () = 0x01000Fu

        // Terminal identities do not carry
        // their diagnostic spelling in the authority value. The hot representation is
        // a compact non-zero ref; text survives only in a side table for rendering.
        // Heterogeneous consumers use explicit kind witnesses instead of a runtime kind-name bridge and
        // explicit kind witnesses / existential visitors.
        [<Struct; StructuralEquality; NoComparison>]
        type TerminalFlowIdentityRef<'Kind> = private | TerminalFlowIdentityRef of uint32

        let private terminalFlowIdentityTextGate = obj()
        let private terminalFlowIdentityTextByRef = System.Collections.Generic.Dictionary<uint32,string>()

        let inline private terminalFlowIdentityKindTag< ^Kind when ^Kind : (static member IdentityKindTag : unit -> uint32)> () =
            ((^Kind) : (static member IdentityKindTag : unit -> uint32) ())

        let private terminalFlowIdentityRefOfTextWithKindTag (kindTag:uint32) (value:string) =
            let normalized = if isNull value then "<null>" else value
            let rawRef =
                CompilerKernelV2.NonZeroRef.derive
                    "terminal-flow-identity"
                    [ string kindTag; normalized ]
                |> CompilerKernelV2.NonZeroRef.value
            lock terminalFlowIdentityTextGate (fun () ->
                match terminalFlowIdentityTextByRef.TryGetValue rawRef with
                | true, existing when existing = normalized -> ()
                | true, _ -> () // NonZeroRef already collision-resolves globally; keep first diagnostic spelling.
                | false, _ -> terminalFlowIdentityTextByRef.[rawRef] <- normalized)
            TerminalFlowIdentityRef rawRef

        let inline private terminalFlowIdentityRefOfText (value:string) : TerminalFlowIdentityRef< ^Kind> =
            terminalFlowIdentityRefOfTextWithKindTag (terminalFlowIdentityKindTag< ^Kind> ()) value

        let private terminalFlowIdentityRefText (TerminalFlowIdentityRef rawRef) =
            lock terminalFlowIdentityTextGate (fun () ->
                match terminalFlowIdentityTextByRef.TryGetValue rawRef with
                | true, value -> value
                | false, _ -> FastRuntimeFormat.format "identity-ref:%u" [| box rawRef |])

        let private terminalFlowIdentityRefDigest (TerminalFlowIdentityRef rawRef) = rawRef

        [<Struct; StructuralEquality; NoComparison>]
        type TerminalFlowFillKeyId = private | TerminalFlowFillKeyId of TerminalFlowIdentityRef<TerminalFlowFillRefKind>

        module TerminalFlowFillKeyId =
            let create value =
                if String.IsNullOrWhiteSpace value then invalidArg "value" "terminal fill key must be non-empty"
                TerminalFlowFillKeyId (terminalFlowIdentityRefOfText value)
            let ofRef value = TerminalFlowFillKeyId value
            let reference (TerminalFlowFillKeyId value) = value
            let digest (TerminalFlowFillKeyId value) = terminalFlowIdentityRefDigest value
            let text (TerminalFlowFillKeyId value) = terminalFlowIdentityRefText value

        let private terminalFlowQueueItemRefOfText value : TerminalFlowIdentityRef<TerminalFlowQueueItemRefKind> =
            terminalFlowIdentityRefOfText value

        let private terminalFlowQueueProducerRefDigestOfText value =
            let typedRef : TerminalFlowIdentityRef<TerminalFlowQueueProducerRefKind> = terminalFlowIdentityRefOfText value
            terminalFlowIdentityRefDigest typedRef

        let private terminalFlowExactOnceRefOfText value : TerminalFlowIdentityRef<TerminalFlowExactOnceRefKind> =
            terminalFlowIdentityRefOfText value

        // Rank-2 Church encoding preserves
        // heterogeneous identity refs. The hidden 'Kind never escapes the package;
        // consumers must supply a polymorphic visitor, mirroring the existential
        // that the self-hosted Spiral GADT will express directly.
        type ITerminalFlowIdentityRefVisitor<'R> =
            abstract Visit<'Kind> : TerminalFlowIdentityRef<'Kind> -> 'R

        type ITerminalFlowSomeIdentityRef =
            abstract KindTag : uint32
            abstract Accept<'R> : ITerminalFlowIdentityRefVisitor<'R> -> 'R

        type private TerminalFlowSomeIdentityRef<'Kind>(kindTag:uint32, value:TerminalFlowIdentityRef<'Kind>) =
            interface ITerminalFlowSomeIdentityRef with
                member _.KindTag = kindTag
                member _.Accept<'R>(visitor:ITerminalFlowIdentityRefVisitor<'R>) =
                    visitor.Visit<'Kind> value

        let inline private terminalFlowPackIdentityRef< ^Kind when ^Kind : (static member IdentityKindTag : unit -> uint32)> (value:TerminalFlowIdentityRef< ^Kind>) : ITerminalFlowSomeIdentityRef =
            let kindTag = terminalFlowIdentityKindTag< ^Kind> ()
            TerminalFlowSomeIdentityRef< ^Kind>(kindTag, value) :> ITerminalFlowSomeIdentityRef

        type private TerminalFlowIdentityDigestVisitor() =
            interface ITerminalFlowIdentityRefVisitor<uint32> with
                member _.Visit<'Kind>(value:TerminalFlowIdentityRef<'Kind>) = terminalFlowIdentityRefDigest value

        let private terminalFlowSomeIdentityDigest (packed:ITerminalFlowSomeIdentityRef) =
            packed.Accept<uint32>(TerminalFlowIdentityDigestVisitor())

        type TerminalFlowIdentityLaneId =
            | TerminalFlowIdentityLaneRoot
            | TerminalFlowIdentityLaneTerminalReceipt
            | TerminalFlowIdentityLaneFill
            | TerminalFlowIdentityLaneDispatch

        type TerminalFlowExistentialIdentitySlot = private {
            lane : TerminalFlowIdentityLaneId
            reference : ITerminalFlowSomeIdentityRef
        }

        let inline private terminalFlowExistentialIdentitySlot< ^Kind when ^Kind : (static member IdentityKindTag : unit -> uint32)> lane (reference:TerminalFlowIdentityRef< ^Kind>) =
            { lane = lane; reference = terminalFlowPackIdentityRef reference }

        let private terminalFlowExistentialIdentitySlotDigest slot =
            (slot.reference.KindTag * 16777619u) ^^^ terminalFlowSomeIdentityDigest slot.reference

        // MIGRATION MIGRATION : reducer-owned progress, topology gates,
        // deterministic semantic frontiers and watchdog petitions.  Display
        // percentages are projections of these types and may never drive
        // scheduler or terminal authority.
        type TerminalFlowProgressPhase =
            | TerminalFlowProgressDag
            | TerminalFlowProgressSemantic
            | TerminalFlowProgressTerminal
            | TerminalFlowProgressWriter
            | TerminalFlowProgressProofKernel

        type TerminalFlowProgressGateCondition =
            | TerminalFlowProgressGateVerdictReady
            | TerminalFlowProgressGateQueueDrain of queueDepth:int64 * blocked:int64 * activeWorkers:int64
            | TerminalFlowProgressGatePhaseWork of phase:TerminalFlowProgressPhase * remaining:int64

        type TerminalFlowProgressControlBand =
            | TerminalFlowControlBandEarly
            | TerminalFlowControlBandMidDrain
            | TerminalFlowControlBandLateDrain
            | TerminalFlowControlBandVerdictImminent
            | TerminalFlowControlBandUnknownProjection of projectedPct:float

        type TerminalFlowControlEvidence = private {
            controlBand : TerminalFlowProgressControlBand
            hasLiveHistory : bool
            noFreshDelta : bool
            replayAuthority : int64
            rootAuthority : int64
            terminalAuthority : int64
            semanticAuthority : int64
            rescueAuthority : int64
        }

        let private terminalFlowControlEvidenceOfCounters projectedPct hasLiveHistory noFreshDelta semanticReceipts replayProgress rootComplete terminalSignals rescueCompleted =
            let band =
                if terminalSignals >= 512L && rootComplete >= 48L then TerminalFlowControlBandVerdictImminent
                elif terminalSignals >= 120L || rootComplete >= 60L || replayProgress >= 8000L then TerminalFlowControlBandLateDrain
                elif replayProgress >= 512L || rootComplete >= 4L || terminalSignals >= 4L then TerminalFlowControlBandMidDrain
                elif hasLiveHistory then TerminalFlowControlBandEarly
                else TerminalFlowControlBandUnknownProjection projectedPct
            {
                controlBand = band
                hasLiveHistory = hasLiveHistory
                noFreshDelta = noFreshDelta
                replayAuthority = replayProgress
                rootAuthority = rootComplete
                terminalAuthority = terminalSignals
                semanticAuthority = semanticReceipts
                rescueAuthority = rescueCompleted
            }

        let private terminalFlowControlBandIsAtLeast minimum actual =
            let rank = function
                | TerminalFlowControlBandEarly -> 1
                | TerminalFlowControlBandMidDrain -> 2
                | TerminalFlowControlBandLateDrain -> 3
                | TerminalFlowControlBandVerdictImminent -> 4
                | TerminalFlowControlBandUnknownProjection _ -> 0
            rank actual >= rank minimum

        let private terminalFlowControlEvidenceAllows minimum evidence =
            evidence.hasLiveHistory && terminalFlowControlBandIsAtLeast minimum evidence.controlBand

        type TerminalFlowQueueItemKind =
            | TerminalFlowQueueCrossKindReplayDriver
            | TerminalFlowQueueParentContinuation
            | TerminalFlowQueueDeclaredBodyVerification
            | TerminalFlowQueueUniverseConstraint
            | TerminalFlowQueueDefEqObligation
            | TerminalFlowQueueProceduralResidual

        type TerminalFlowWaitGraphNode =
            | TerminalFlowWaitProgressPhase of TerminalFlowProgressPhase
            | TerminalFlowWaitQueueKind of TerminalFlowQueueItemKind
            | TerminalFlowWaitVerdict

        type TerminalFlowWaitGraphEdge = private {
            fromNode : TerminalFlowWaitGraphNode
            toNode : TerminalFlowWaitGraphNode
            outstanding : int64
        }

