        let mutable private terminalFlowJpLaneSnapshotBridge : unit -> TerminalFlowJpLaneSnapshot =
            fun () -> { semanticQueueDepth = 0L; declaredBodyQueueDepth = 0L; semanticActive = 0L; declaredBodyActive = 0L }

        let installTerminalFlowJpLaneSnapshotBridge (snapshot: unit -> int64 * int64 * int64 * int64) =
            terminalFlowJpLaneSnapshotBridge <- fun () ->
                let semanticQueueDepth, declaredBodyQueueDepth, semanticActive, declaredBodyActive = snapshot ()
                { semanticQueueDepth = semanticQueueDepth
                  declaredBodyQueueDepth = declaredBodyQueueDepth
                  semanticActive = semanticActive
                  declaredBodyActive = declaredBodyActive }

