        let terminalFlowWorkLedgerStateText = function
            | TerminalFlowWorkLedgerOpen -> "Open"
            | TerminalFlowWorkLedgerMaterial -> "Material"
            | TerminalFlowWorkLedgerBlocked -> "Blocked"
            | TerminalFlowWorkLedgerResidual -> "Residual"
