            | TerminalFlowWorkLedgerProvenDead -> "ProvenDead"

        let terminalFlowBlockedAttributionAuthorityText = function
            | TerminalFlowBlockedAttributionLiveDependencyGraphComplete -> "LiveDependencyGraphComplete"
            | TerminalFlowBlockedAttributionLiveDependencyGraphPartial(attributedCount, blockedCost) ->
                sprintf "LiveDependencyGraphPartial(attributed=%d|blocked=%d)" attributedCount blockedCost
            | TerminalFlowBlockedAttributionLiveActiveWorkFallback ageMs ->
                sprintf "LiveActiveWorkFallback(age_ms=%d)" ageMs
            | TerminalFlowBlockedAttributionRetainedStale ageMs ->
                sprintf "RetainedStale(age_ms=%d)" ageMs
            | TerminalFlowBlockedAttributionUnavailable -> "Unavailable"

        // Dedupe keys use the structural authority class only. Volatile ages remain
        // sibling numeric observations and cannot fabricate state transitions.
        let terminalFlowBlockedAttributionAuthorityClassText = function
            | TerminalFlowBlockedAttributionLiveDependencyGraphComplete -> "LiveDependencyGraphComplete"
            | TerminalFlowBlockedAttributionLiveDependencyGraphPartial _ -> "LiveDependencyGraphPartial"
            | TerminalFlowBlockedAttributionLiveActiveWorkFallback _ -> "LiveActiveWorkFallback"
            | TerminalFlowBlockedAttributionRetainedStale _ -> "RetainedStale"
            | TerminalFlowBlockedAttributionUnavailable -> "Unavailable"

        let terminalFlowBlockedAttributionAuthorityAgeMs = function
            | TerminalFlowBlockedAttributionLiveActiveWorkFallback ageMs
            | TerminalFlowBlockedAttributionRetainedStale ageMs -> max 0L ageMs
            | TerminalFlowBlockedAttributionLiveDependencyGraphComplete
            | TerminalFlowBlockedAttributionLiveDependencyGraphPartial _
            | TerminalFlowBlockedAttributionUnavailable -> 0L

        let terminalFlowBlockedWorkIdentityAuthorityText = function
            | TerminalFlowBlockedWorkIdentityLiveDependencyGraph -> "LiveDependencyGraph"
            | TerminalFlowBlockedWorkIdentityLiveActiveWorkFallback -> "LiveActiveWorkFallback"
            | TerminalFlowBlockedWorkIdentityRetainedStale -> "RetainedStale"
            | TerminalFlowBlockedWorkIdentityUnavailable -> "Unavailable"

        let terminalFlowWorkLedgerBlockerKindText = function
            | TerminalFlowWorkLedgerBlockerQueue -> "Queue"
            | TerminalFlowWorkLedgerBlockerActiveWorker -> "ActiveWorker"
            | TerminalFlowWorkLedgerBlockerResidual -> "Residual"
            | TerminalFlowWorkLedgerBlockerRootAuthority -> "RootAuthority"
            | TerminalFlowWorkLedgerBlockerTerminalCredential -> "TerminalCredential"
            | TerminalFlowWorkLedgerBlockerCicKernel -> "CicKernel"

        let terminalFlowEtaAuthorityText = function
            | TerminalFlowEtaMaterialRate(remainingCost, milliCostPerSecond, etaSeconds) ->
                FastRuntimeFormat.format "MaterialRate(remaining_cost=%d|milli_cost_per_second=%d|eta_seconds=%d)" [| box remainingCost; box milliCostPerSecond; box etaSeconds |]
            | TerminalFlowEtaCredentialBlocked(blocker, blockerRef, ageMs) ->
                FastRuntimeFormat.format "CredentialBlocked(blocker=%s|blocker_ref=%u|age_ms=%d)" [| box (terminalFlowWorkLedgerBlockerKindText blocker); box blockerRef; box ageMs |]
            | TerminalFlowEtaNoMaterialAuthority zeroDeltaStreak ->
                sprintf "NoMaterialAuthority(zero_delta_streak=%d)" zeroDeltaStreak
            | TerminalFlowEtaComplete -> "OperationalGraphComplete"

