        let private terminalFlowCicArenaOwnerOfRaw actorRef =
            match CompilerKernelV2.NonZeroRef.tryCreate actorRef with
            | Some reference -> TerminalFlowCicArenaOwned reference
            | None -> TerminalFlowCicArenaUnowned

        let private terminalFlowCicArenaOwnerRaw = function
            | TerminalFlowCicArenaUnowned -> 0u
            | TerminalFlowCicArenaOwned reference -> CompilerKernelV2.NonZeroRef.value reference

        [<Struct; CustomEquality; NoComparison>]
        type TerminalFlowCicTermId = private {
            generation : TerminalFlowCicArenaGenerationId
            slot : uint32
            structuralHash : uint64
        }
        with
            override this.Equals(other:obj) =
                match other with
                | :? TerminalFlowCicTermId as other -> this.generation = other.generation && this.slot = other.slot
                | _ -> false
            override this.GetHashCode() = hash (this.generation, this.slot)
            interface System.IEquatable<TerminalFlowCicTermId> with
                member this.Equals(other:TerminalFlowCicTermId) = this.generation = other.generation && this.slot = other.slot

        [<Struct; CustomEquality; NoComparison>]
        type TerminalFlowCicLevelId = private {
            generation : TerminalFlowCicArenaGenerationId
            slot : uint32
            structuralHash : uint64
        }
        with
            override this.Equals(other:obj) =
                match other with
                | :? TerminalFlowCicLevelId as other -> this.generation = other.generation && this.slot = other.slot
                | _ -> false
            override this.GetHashCode() = hash (this.generation, this.slot)
            interface System.IEquatable<TerminalFlowCicLevelId> with
                member this.Equals(other:TerminalFlowCicLevelId) = this.generation = other.generation && this.slot = other.slot

        let private terminalFlowCicTermSlot (term:TerminalFlowCicTermId) = term.slot
        let private terminalFlowCicTermStructuralHash (term:TerminalFlowCicTermId) = term.structuralHash
        let private terminalFlowCicLevelSlot (level:TerminalFlowCicLevelId) = level.slot
        let private terminalFlowCicLevelStructuralHash (level:TerminalFlowCicLevelId) = level.structuralHash

