            whnfCacheMisses : CompilerKernelV2.NodeCount
            defEqSolvedCount : CompilerKernelV2.NodeCount
            defEqFailedCount : CompilerKernelV2.NodeCount
            universeSolverIterations : CompilerKernelV2.NodeCount
            obligationCount : CompilerKernelV2.NodeCount
            activeWorkers : CompilerKernelV2.WorkerCount
        }

        // Domain migration: CIC obligations are arena-owned, phase-indexed
        // values and can be stored heterogeneously without erasing their kind.
        type TerminalFlowCicObligationOpenStage = class end
        type TerminalFlowCicObligationSolvedStage = class end
        type TerminalFlowCicObligationRejectedStage = class end

        [<Struct>]
        type TerminalFlowCicObligationId<'Kind> = private | TerminalFlowCicObligationId of uint32

        type TerminalFlowCicDefEqKind private () =
            static member ObligationKindTag () = 0x030001u
        type TerminalFlowCicUniverseKind private () =
            static member ObligationKindTag () = 0x030002u
        type TerminalFlowCicWhnfKind private () =
            static member ObligationKindTag () = 0x030003u
        type TerminalFlowCicDeclarationKind private () =
            static member ObligationKindTag () = 0x030004u
        type TerminalFlowCicInternKind private () =
            static member ObligationKindTag () = 0x030005u
