        [<Struct; StructuralEquality; NoComparison>]
        type TerminalFlowCicObligationKey = private {
            kindTag : uint32
            value : uint32
        }

        let private terminalFlowCicObligationKeyOf kindTag (TerminalFlowCicObligationId value) =
            { kindTag = kindTag
              value = value }

        type TerminalFlowCicObligation<'Kind,'Stage> = private {
            obligationId : TerminalFlowCicObligationId<'Kind>
            owner : TerminalFlowCicArenaOwnerCapability<TerminalFlowCicArenaOwnedStage>
            subjectTerm : TerminalFlowCicTermId option
            subjectLevel : TerminalFlowCicLevelId option
            satisfierRef : uint32
            exactOnceRef : uint32
            openedAtSequence : int64
            closedAtSequence : int64 option
        }

        type private TerminalFlowCicObligationApp<'Kind>(value:TerminalFlowCicObligation<'Kind,TerminalFlowCicObligationOpenStage>) =
            member _.Value = value
            interface App<TerminalFlowCicObligationF,'Kind>

        type ITerminalFlowCicObligationVisitor<'R> =
            abstract Visit<'Kind> : App<TerminalFlowCicObligationF,'Kind> -> 'R

        type ISomeTerminalFlowCicObligation =
            abstract ObligationKey : TerminalFlowCicObligationKey
            abstract Accept<'R> : ITerminalFlowCicObligationVisitor<'R> -> 'R

        type private SomeTerminalFlowCicObligation<'Kind>(obligation:TerminalFlowCicObligation<'Kind,TerminalFlowCicObligationOpenStage>, key:TerminalFlowCicObligationKey) =
            let app = TerminalFlowCicObligationApp<'Kind>(obligation) :> App<TerminalFlowCicObligationF,'Kind>
            interface ISomeTerminalFlowCicObligation with
                member _.ObligationKey = key
                member _.Accept<'R>(visitor:ITerminalFlowCicObligationVisitor<'R>) = visitor.Visit<'Kind> app

        let private terminalFlowCicPackObligation kindTag (obligation:TerminalFlowCicObligation<'Kind,TerminalFlowCicObligationOpenStage>) : ISomeTerminalFlowCicObligation =
            let key = terminalFlowCicObligationKeyOf kindTag obligation.obligationId
            SomeTerminalFlowCicObligation<'Kind>(obligation, key) :> ISomeTerminalFlowCicObligation

        type TerminalFlowCicObligationCloseDisposition =
            | TerminalFlowCicObligationSolved
            | TerminalFlowCicObligationRejected of CompilerKernelV2.OperationalReasonId

        type TerminalFlowCicObligationCloseReceipt = private {
            obligation : ISomeTerminalFlowCicObligation
            closeReceiptRef : uint32
            disposition : TerminalFlowCicObligationCloseDisposition
            closedAtSequence : int64
        }

        // Round 3/5 deletes the projection-owned CIC ledger.  Progress code may
        // observe the owned actor, but it may not manufacture kernel counters from
        // unrelated frontier queue counts.  These late-bound bridges are installed
        // by the CIC actor runtime after its state type is defined below.
        let private terminalFlowCicDormantCounters () : TerminalFlowCicArenaCounters = {
            arenaRef = terminalFlowIdentityRefOfText "cic-arena:dormant"
            owner = TerminalFlowCicArenaUnowned
            termCount = CompilerKernelV2.Measured.zero
            levelCount = CompilerKernelV2.Measured.zero
            whnfCacheHits = CompilerKernelV2.Measured.zero
            whnfCacheMisses = CompilerKernelV2.Measured.zero
            defEqSolvedCount = CompilerKernelV2.Measured.zero
            defEqFailedCount = CompilerKernelV2.Measured.zero
            universeSolverIterations = CompilerKernelV2.Measured.zero
            obligationCount = CompilerKernelV2.Measured.zero
            activeWorkers = CompilerKernelV2.Measured.zero
        }

        let mutable private terminalFlowCicOwnedActorCountersBridge : unit -> TerminalFlowCicArenaCounters = terminalFlowCicDormantCounters

        type TerminalFlowProgressEvidenceSeed = private {
            snapshotRef : TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind>
            snapshotSequence : int64
            frontier : TerminalFlowMonotoneFrontier
            semanticDigest : TerminalFlowSemanticFrontierDigest
            proceduralDigestRef : TerminalFlowIdentityRef<TerminalFlowProceduralFrontierDigestRefKind>
            queueAttributionComplete : bool
            observedAtMs : int64
        }

        type TerminalFlowProgressEvidence = private {
            snapshotRef : TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind>
            snapshotSequence : int64
            frontier : TerminalFlowMonotoneFrontier
            semanticDigest : TerminalFlowSemanticFrontierDigest
            proceduralDigestRef : TerminalFlowIdentityRef<TerminalFlowProceduralFrontierDigestRefKind>
            workLedger : TerminalFlowActorOwnedWorkLedger
            cicKernel : TerminalFlowCicArenaCounters
            queueAttributionComplete : bool
            observedAtMs : int64
        }

        [<StructuralEquality; NoComparison>]
        type TerminalFlowHotIdentityKey =
            | TerminalFlowHotIdentityActor of dispatchRef:TerminalFlowIdentityRef<TerminalFlowDispatchRefKind> * fillRef:TerminalFlowIdentityRef<TerminalFlowFillRefKind>
            | TerminalFlowHotIdentityWorkLedger of snapshotRef:uint32 * actorRef:uint32
            | TerminalFlowHotIdentityCicArena of snapshotRef:uint32 * semanticEpoch:int64 * actorRef:uint32

        let private terminalFlowHotIdentityGate = obj()
        let private terminalFlowHotIdentityByKey = System.Collections.Generic.Dictionary<TerminalFlowHotIdentityKey,uint32>()
        let mutable private terminalFlowHotIdentityCounter = 0u

        let private terminalFlowHotIdentityRefFor key =
            lock terminalFlowHotIdentityGate (fun () ->
                match terminalFlowHotIdentityByKey.TryGetValue key with
                | true, value -> value
                | false, _ ->
                    terminalFlowHotIdentityCounter <- terminalFlowHotIdentityCounter + 1u
                    let value = terminalFlowHotIdentityCounter
                    terminalFlowHotIdentityByKey.[key] <- value
                    value)

        let private terminalFlowWorkLedgerFor
            (snapshotRef:TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind>)
            observedAtMs
            (frontier:TerminalFlowMonotoneFrontier)
            (semanticDigest:TerminalFlowSemanticFrontierDigest) =
            let actor = DiagJson.terminalSchedulerPushActorSnapshot()
            let ownerActorRef =
                if String.IsNullOrWhiteSpace actor.dispatchId then 0u
                else
                    let dispatchRef : TerminalFlowIdentityRef<TerminalFlowDispatchRefKind> = terminalFlowIdentityRefOfText actor.dispatchId
                    let fillRef : TerminalFlowIdentityRef<TerminalFlowFillRefKind> = terminalFlowIdentityRefOfText actor.fillKey
                    terminalFlowHotIdentityRefFor (TerminalFlowHotIdentityActor(dispatchRef, fillRef))
            let schedulerLedgerState = SemanticWorkLedgerProjection.readOperational ()
            let schedulerAdmittedCount, schedulerReceiptCount, schedulerOpenCount =
                SemanticWorkLedgerProjection.countsOf schedulerLedgerState
            let executionAttemptCount = max 0L frontier.activeWorkers
            let operationalGraphObservation =
                match TerminalFlowOperationalGraphSnapshotBridge.read () with
                | Some(graphRevision, openCount, suspendedCount, graphRef) ->
                    TerminalFlowOperationalGraphObserved(
                        graphRevision,
                        openCount,
                        suspendedCount,
                        graphRef)
                | None -> TerminalFlowOperationalGraphUnavailable
            let operationalGraphOpenCount, operationalGraphSuspendedCount, operationalGraphActiveCount, topologyOpenCount =
                match operationalGraphObservation with
                | TerminalFlowOperationalGraphObserved(_, openCount, suspendedCount, _) ->
                    let openCount = max 0L openCount
                    let suspendedCount = min openCount (max 0L suspendedCount)
                    openCount,
                    suspendedCount,
                    max 0L (openCount - suspendedCount),
                    max (max 0L frontier.queueDepth) openCount
                | TerminalFlowOperationalGraphUnavailable ->
                    let fallbackOpen = max 0L (frontier.queueDepth + executionAttemptCount)
                    fallbackOpen,
                    0L,
                    executionAttemptCount,
                    fallbackOpen
            let schedulerOpenNotRepresented = max 0L (schedulerOpenCount - topologyOpenCount)
            let frontierRemainingCost = max 0L (frontier.discovered - frontier.retired)
            let remainingCost = max (max frontierRemainingCost schedulerOpenCount) operationalGraphOpenCount
            let discoveredCost =
                max
                    (max 0L frontier.discovered)
                    (max 0L frontier.retired + max schedulerOpenCount operationalGraphOpenCount)
            let residualCost =
                frontier.queueKindCounts.crossKindReplayDriver
                + frontier.queueKindCounts.parentContinuation
                + frontier.queueKindCounts.declaredBodyVerification
                + frontier.queueKindCounts.proceduralResidual
                + frontier.queueKindCounts.universeConstraint
                + frontier.queueKindCounts.defEqObligation
            let frontierBlockedCost = max 0L frontier.blocked
            let activeCost = operationalGraphActiveCount
            let dependencyEvidence = JpActiveWorkIdentityAuthority.readBlockedDependencyEvidence ()
            let oldestActiveWork = JpActiveWorkIdentityAuthority.readOldest ()
            let liveDependencies, retainedDependency =
                match dependencyEvidence with
                | JpBlockedDependencyLive dependencies -> dependencies, None
                | JpBlockedDependencyRetainedStale(dependency, _) -> [], Some dependency
                | JpBlockedDependencyExpired _ -> [], None
                | JpBlockedDependencyUnavailable -> [], None
            let observedDependencyCount =
                match liveDependencies with
                | _ :: _ -> int64 liveDependencies.Length
                | [] ->
                    match retainedDependency with
                    | Some _ -> 1L
                    | None -> 0L
            let blockedCost =
                max frontierBlockedCost (min (max schedulerOpenCount operationalGraphOpenCount) observedDependencyCount)
            let readyCost = max 0L (frontier.queueDepth - blockedCost)
            let dependencyToBlockedUnit identityPrefix dependency =
                let producerRef =
                    if dependency.producerWorkId > 0L then
                        NativeCutoverStableRef.ref32 "jp-blocked-producer" [string dependency.producerWorkId]
                    else
                        terminalFlowQueueProducerRefDigestOfText (identityPrefix + "-producer:" + CompilerKernelV2.StableBindingId.text dependency.producerBindingId)
                { itemRef = terminalFlowQueueItemRefOfText (identityPrefix + ":" + CompilerIdentityKernel.ContentDigest.text dependency.waitRef)
                  itemKind = TerminalFlowQueueProceduralResidual
                  producerRef = producerRef
                  ownerRef = Some dependency.ownerRef
                  discoveredAtSnapshotRef = snapshotRef }
            let attributionDemand =
                max blockedCost (if operationalGraphOpenCount > 0L || schedulerOpenCount > 0L then 1L else 0L)
            let liveBlockedUnits =
                liveDependencies
                |> List.truncate (int (min 8L attributionDemand))
                |> List.map (dependencyToBlockedUnit "live-dependency")
            let retainedBlockedUnit =
                retainedDependency
                |> Option.map (dependencyToBlockedUnit "retained-stale-dependency")
            let activeBlockedUnit =
                oldestActiveWork
                |> Option.map (fun active ->
                    { itemRef = terminalFlowQueueItemRefOfText ("live-active-work:" + CompilerIdentityKernel.ContentDigest.text active.workUnitRef)
                      itemKind = TerminalFlowQueueProceduralResidual
                      producerRef = terminalFlowQueueProducerRefDigestOfText ("live-active-producer:" + CompilerIdentityKernel.ContentDigest.text active.workUnitRef)
                      ownerRef = None
                      discoveredAtSnapshotRef = snapshotRef })
            let liveAttributedCount = min attributionDemand (int64 liveBlockedUnits.Length)
            let blockedUnits, blockedAttributionAuthority, blockedAttributionComplete =
                if attributionDemand <= 0L then
                    [], TerminalFlowBlockedAttributionUnavailable, true
                elif liveAttributedCount >= attributionDemand then
                    liveBlockedUnits,
                    TerminalFlowBlockedAttributionLiveDependencyGraphComplete,
                    true
                elif liveAttributedCount > 0L then
                    liveBlockedUnits |> List.truncate (int (min 8L attributionDemand)),
                    TerminalFlowBlockedAttributionLiveDependencyGraphPartial(liveAttributedCount, attributionDemand),
                    false
                else
                    match oldestActiveWork, activeBlockedUnit, retainedDependency, retainedBlockedUnit with
                    | Some active, Some blockedUnit, _, _ ->
                        [blockedUnit],
                        TerminalFlowBlockedAttributionLiveActiveWorkFallback(max 0L (observedAtMs - active.startedAtMs)),
                        true
                    | None, None, Some dependency, Some blockedUnit ->
                        [blockedUnit],
                        TerminalFlowBlockedAttributionRetainedStale(max 0L (observedAtMs - dependency.startedAtMs)),
                        false
                    | _ ->
                        [],
                        TerminalFlowBlockedAttributionUnavailable,
                        false
            let blockedWorkUnitId, blockedMethodKey, blockedSource, blockedWorkIdentityAuthority =
                if blockedCost > 0L || schedulerOpenCount > 0L || operationalGraphOpenCount > 0L then
                    match liveDependencies, oldestActiveWork, retainedDependency with
                    | dependency :: _, _, _ ->
                        CompilerIdentityKernel.ContentDigest.text dependency.waiterWorkUnitRef,
                        (CompilerIdentityKernel.WorkSiteIdOps.text dependency.waiterSiteId
                         + " | binding=" + CompilerKernelV2.StableBindingId.text dependency.waiterBindingId),
                        CompilerIdentityKernel.WorkSiteIdOps.text dependency.waiterSiteId,
                        TerminalFlowBlockedWorkIdentityLiveDependencyGraph
                    | [], Some active, _ ->
                        CompilerIdentityKernel.ContentDigest.text active.workUnitRef,
                        (CompilerIdentityKernel.WorkSiteIdOps.text active.siteId
                         + " | binding=" + CompilerKernelV2.StableBindingId.text active.bindingId),
                        CompilerIdentityKernel.WorkSiteIdOps.text active.siteId,
                        TerminalFlowBlockedWorkIdentityLiveActiveWorkFallback
                    | [], None, Some dependency ->
                        CompilerIdentityKernel.ContentDigest.text dependency.waiterWorkUnitRef,
                        (CompilerIdentityKernel.WorkSiteIdOps.text dependency.waiterSiteId
                         + " | binding=" + CompilerKernelV2.StableBindingId.text dependency.waiterBindingId),
                        CompilerIdentityKernel.WorkSiteIdOps.text dependency.waiterSiteId,
                        TerminalFlowBlockedWorkIdentityRetainedStale
                    | [], None, None ->
                        "", "", "", TerminalFlowBlockedWorkIdentityUnavailable
                else
                    "", "", "", TerminalFlowBlockedWorkIdentityUnavailable
            let state =
                if remainingCost = 0L && frontier.queueDepth = 0L && operationalGraphOpenCount = 0L && schedulerOpenCount = 0L then TerminalFlowWorkLedgerClosed
                elif residualCost > 0L then TerminalFlowWorkLedgerResidual
                elif blockedCost > 0L || (operationalGraphOpenCount > 0L && operationalGraphSuspendedCount = operationalGraphOpenCount) then TerminalFlowWorkLedgerBlocked
                elif operationalGraphOpenCount > 0L || readyCost > 0L || schedulerOpenCount > 0L then TerminalFlowWorkLedgerMaterial
                else TerminalFlowWorkLedgerOpen
            let ledgerIdentityRef =
                terminalFlowHotIdentityRefFor
                    (TerminalFlowHotIdentityWorkLedger(terminalFlowIdentityRefDigest snapshotRef, ownerActorRef))
            { ledgerRef = terminalFlowIdentityRefOfText (sprintf "work-ledger:%u" ledgerIdentityRef)
              ownerActorRef = ownerActorRef
              snapshotRef = snapshotRef
              state = state
              discoveredCost = discoveredCost
              readyCost = readyCost
              activeCost = activeCost
              executionAttemptCount = executionAttemptCount
              operationalGraphObservation = operationalGraphObservation
              operationalGraphOpenCount = operationalGraphOpenCount
              operationalGraphSuspendedCount = operationalGraphSuspendedCount
              completedCost = max 0L frontier.retired
              blockedCost = blockedCost
              blockedUnits = blockedUnits
              blockedAttributionAuthority = blockedAttributionAuthority
              blockedAttributionComplete = blockedAttributionComplete
              blockedWorkUnitId = blockedWorkUnitId
              blockedMethodKey = blockedMethodKey
              blockedSource = blockedSource
              blockedWorkIdentityAuthority = blockedWorkIdentityAuthority
              schedulerAdmittedCount = schedulerAdmittedCount
              schedulerReceiptCount = schedulerReceiptCount
              schedulerOpenCount = schedulerOpenCount
              schedulerOpenNotRepresented = schedulerOpenNotRepresented
              residualCost = max 0L residualCost
              provenDeadCost = 0L
              remainingCost = remainingCost
              totalCost = max discoveredCost frontier.retired
              materialDeltaCost = 0L
              zeroDeltaStreak = 0L
              milliCostPerSecond = 0L
              etaAuthority = if remainingCost = 0L then TerminalFlowEtaComplete else TerminalFlowEtaNoMaterialAuthority 0L
              updatedAtMs = observedAtMs }

        let private terminalFlowCicArenaCountersFor
            (_snapshotRef:TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind>)
            ownerActorRef
            (_frontier:TerminalFlowMonotoneFrontier)
            (_semanticDigest:TerminalFlowSemanticFrontierDigest) =
            terminalFlowCicOwnedActorCountersBridge ()

        let private terminalFlowProgressEvidenceWithActorOwnedLedgers (seed:TerminalFlowProgressEvidenceSeed) =
            let workLedger = terminalFlowWorkLedgerFor seed.snapshotRef seed.observedAtMs seed.frontier seed.semanticDigest
            let cicKernel = terminalFlowCicArenaCountersFor seed.snapshotRef workLedger.ownerActorRef seed.frontier seed.semanticDigest
            { snapshotRef = seed.snapshotRef
              snapshotSequence = seed.snapshotSequence
              frontier = seed.frontier
              semanticDigest = seed.semanticDigest
              proceduralDigestRef = seed.proceduralDigestRef
              workLedger = workLedger
              cicKernel = cicKernel
              queueAttributionComplete = seed.queueAttributionComplete
              observedAtMs = seed.observedAtMs }

        let private terminalFlowProgressEvidenceWithOwnedCicActor evidence =
            { evidence with cicKernel = terminalFlowCicOwnedActorCountersBridge () }

        let private terminalFlowProgressEvidenceWithNativeCicCounters (_counters:NativeCutoverCicKernelCounters) evidence =
            terminalFlowProgressEvidenceWithOwnedCicActor evidence

        type TerminalFlowProgressRegression =
            | TerminalFlowProgressSnapshotSequenceRegressed of previous:int64 * incoming:int64
            | TerminalFlowProgressDiscoveredRegressed of previous:int64 * incoming:int64
            | TerminalFlowProgressRetiredRegressed of previous:int64 * incoming:int64
            | TerminalFlowProgressRetiredBeyondDiscovered of retired:int64 * discovered:int64
            | TerminalFlowWorkLedgerOwnerMismatch of previousActorRef:uint32 * incomingActorRef:uint32
            | TerminalFlowWorkLedgerCostInvariantBroken of completed:int64 * remaining:int64 * total:int64
            | TerminalFlowWorkLedgerCompletedRegressed of previous:int64 * incoming:int64
            | TerminalFlowCicArenaOwnerMismatch of ledgerActorRef:uint32 * arenaActorRef:uint32
            | TerminalFlowSemanticFrontierNondeterministic of previousRef:uint32 * incomingRef:uint32 * semanticEpoch:int64

        type TerminalFlowReducerProgressAuthority = private {
            accepted : TerminalFlowProgressEvidence option
            rejected : TerminalFlowProgressRegression option
        }

        let private terminalFlowProgressEvidenceIsOperationallyClosed (evidence:TerminalFlowProgressEvidence) =
            let workLedgerClosed =
                match evidence.workLedger.state with
                | TerminalFlowWorkLedgerClosed
                | TerminalFlowWorkLedgerProvenDead -> true
                | TerminalFlowWorkLedgerOpen
                | TerminalFlowWorkLedgerMaterial
                | TerminalFlowWorkLedgerBlocked
                | TerminalFlowWorkLedgerResidual -> false
            workLedgerClosed
            && evidence.workLedger.schedulerOpenCount = 0L
            && evidence.workLedger.remainingCost = 0L
            && evidence.workLedger.blockedCost = 0L
            && evidence.workLedger.readyCost = 0L
            && evidence.workLedger.activeCost = 0L
            && evidence.frontier.queueDepth = 0L
            // frontier.activeWorkers counts execution attempts/lane wrappers, not open work.
            // OperationalWorkGraph + scheduler/work-ledger state are the liveness authority.

        let private terminalFlowProgressEvidenceIsStructuralClosedWorld evidence =
            terminalFlowProgressEvidenceIsOperationallyClosed evidence
            && evidence.queueAttributionComplete

        // MIGRATION: QAP may mature only inside a closed-world frontier.  A stable
        // semantic digest is necessary but not sufficient: discovered work, active
        // workers and unattributed queue items are explicit evidence that the reducer
        // still lacks authority to choose FailClosed.
        let private terminalFlowSemanticDrainStrandedAfterMs = 5000L

        type TerminalFlowQapRootSettlementEvidence =
            | TerminalFlowQapRootAwaitingCanonicalReceipt of semanticReceipts:int64 * canonicalRoots:int64
            | TerminalFlowQapRootSettledByCanonicalReceipt of receiptRef:uint32 * evidenceRef:uint32 * source:string

        let private terminalFlowQapRootSettlementEvidenceText = function
            | TerminalFlowQapRootAwaitingCanonicalReceipt(semanticReceipts, canonicalRoots) ->
                sprintf "AwaitingCanonicalReceipt(semantic_receipts=%d|canonical_roots=%d)" semanticReceipts canonicalRoots
            | TerminalFlowQapRootSettledByCanonicalReceipt(receiptRef, evidenceRef, source) ->
                FastRuntimeFormat.format "SettledByCanonicalReceipt(receipt_ref=%u|evidence_ref=%u|source=%s)" [| box receiptRef; box evidenceRef; box source |]

        // Canonical-root settlement and semantic-fact receipts are different ledgers.
        // A canonical receipt settles the root; semanticReceiptCount remains diagnostic
        // and must never be used as a denominator or quorum for root authority.
        let private terminalFlowQapRootSettlementEvidenceFor (evidence:TerminalFlowProgressEvidence) =
            let canonicalRoot = DiagJson.canonicalRootAuthoritySnapshot()
            if String.IsNullOrWhiteSpace canonicalRoot.receiptId then
                TerminalFlowQapRootAwaitingCanonicalReceipt(
                    evidence.semanticDigest.semanticReceiptCount,
                    evidence.semanticDigest.canonicalRootCount)
            else
                TerminalFlowQapRootSettledByCanonicalReceipt(
                    semanticFactStableRef "qap-canonical-root-receipt" canonicalRoot.receiptId,
                    canonicalRoot.evidenceRef,
                    canonicalRoot.source)

        // Shared non-empty evidence lives above both termination and dispatch.
        // This removes declaration-order pressure that previously forced terminal
        // subsystems to duplicate missing-evidence representations.
        type TerminalFlowNonEmptyEvidence<'Evidence> = private {
            head : 'Evidence
            tail : 'Evidence list
        }

        let private terminalFlowNonEmptyEvidence head tail : TerminalFlowNonEmptyEvidence<'Evidence> =
            { head = head; tail = tail }

        let private terminalFlowNonEmptyEvidenceOfList = function
            | head :: tail -> terminalFlowNonEmptyEvidence head tail
            | [] -> invalidOp "typed missing-evidence set cannot be empty"

        let private terminalFlowNonEmptyEvidenceToList evidence = evidence.head :: evidence.tail

        // DESTRUCTIVE MIGRATION ROUND 4: termination authority is conserved credit,
        // not elapsed time, replay exhaustion, drain completion or watchdog policy.
        // Every operational scheduler admission owns one credit until an exact-once
        // receipt returns it.  Terminal-protocol work is a separate typed domain: at
        // most one winner credit may remain reserved through quiescence because the
        // indexed closure is the sole authority that can retire that winner.  The
        // total ledger must still close to zero before durable run_end/physical exit.
        type TerminalFlowTerminationCreditBlocker =
            | TerminalFlowTerminationCreditNoSnapshot
            | TerminalFlowTerminationCreditRootUnsettled of semanticReceipts:int64 * canonicalRoots:int64
            | TerminalFlowTerminationCreditQueueAttributionIncomplete of queueDepth:int64
            | TerminalFlowTerminationCreditConservationMismatch of admitted:int64 * receipts:int64 * openCount:int64
            | TerminalFlowTerminationCreditSchedulerOpen of openCount:int64
            | TerminalFlowTerminationCreditSemanticOpen of openCount:int64
            | TerminalFlowTerminationCreditUnclassifiedSemanticOpen of openCount:int64
            | TerminalFlowTerminationCreditTerminalProtocolMultiplicity of openCount:int64
            | TerminalFlowTerminationCreditOperationalGraphUnavailable
            | TerminalFlowTerminationCreditOperationalGraphOpen of openCount:int64 * suspendedCount:int64
            | TerminalFlowTerminationCreditRunnableOwners of activeWorkers:int64
            | TerminalFlowTerminationCreditQueuedOwners of queueDepth:int64
            | TerminalFlowTerminationCreditKernelObligations of obligationCount:int64

        type TerminalFlowQuiescenceReceipt = private {
            receiptDigest : CompilerIdentityKernel.ContentDigest
            snapshotRef : TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind>
            rootSettlement : TerminalFlowQapRootSettlementEvidence
            schedulerAdmitted : int64
            schedulerReceipts : int64
            semanticReceipts : int64
            semanticCreditDigest : CompilerIdentityKernel.ContentDigest
            terminalProtocolOpen : int64
            operationalGraphRevision : int64
            operationalGraphRef : CompilerIdentityKernel.ContentDigest
            discoveredDiagnostic : int64
            retiredDiagnostic : int64
            remainingDiagnostic : int64
            mintedAtMs : int64
        }

        type TerminalFlowTerminationCreditDecision =
            | TerminalFlowTerminationCreditOutstanding of TerminalFlowNonEmptyEvidence<TerminalFlowTerminationCreditBlocker>
            | TerminalFlowTerminationCreditReturned of TerminalFlowQuiescenceReceipt

        let private terminalFlowTerminationCreditBlockerText = function
            | TerminalFlowTerminationCreditNoSnapshot -> "NoSnapshot"
            | TerminalFlowTerminationCreditRootUnsettled(semanticReceipts, canonicalRoots) ->
                sprintf "RootUnsettled(semantic_receipts=%d|canonical_roots=%d)" semanticReceipts canonicalRoots
            | TerminalFlowTerminationCreditQueueAttributionIncomplete queueDepth ->
                sprintf "QueueAttributionIncomplete(queue=%d)" queueDepth
            | TerminalFlowTerminationCreditConservationMismatch(admitted, receipts, openCount) ->
                FastRuntimeFormat.format "ConservationMismatch(admitted=%d|receipts=%d|open=%d)" [| box admitted; box receipts; box openCount |]
            | TerminalFlowTerminationCreditSchedulerOpen openCount -> sprintf "SchedulerCreditOpen(%d)" openCount
            | TerminalFlowTerminationCreditSemanticOpen openCount -> sprintf "OperationalSemanticCreditOpen(%d)" openCount
            | TerminalFlowTerminationCreditUnclassifiedSemanticOpen openCount -> sprintf "UnclassifiedSemanticCreditOpen(%d)" openCount
            | TerminalFlowTerminationCreditTerminalProtocolMultiplicity openCount -> sprintf "TerminalProtocolCreditMultiplicity(%d)" openCount
            | TerminalFlowTerminationCreditOperationalGraphUnavailable -> "OperationalGraphUnavailable"
            | TerminalFlowTerminationCreditOperationalGraphOpen(openCount, suspendedCount) ->
                FastRuntimeFormat.format "OperationalGraphOpen(open=%d|suspended=%d)" [| box openCount; box suspendedCount |]
            | TerminalFlowTerminationCreditRunnableOwners activeWorkers -> sprintf "RunnableOwnerCredit(%d)" activeWorkers
            | TerminalFlowTerminationCreditQueuedOwners queueDepth -> sprintf "QueuedOwnerCredit(%d)" queueDepth
            | TerminalFlowTerminationCreditKernelObligations obligationCount -> sprintf "KernelCreditOpen(%d)" obligationCount

        let private terminalFlowTerminationCreditDecisionText = function
            | TerminalFlowTerminationCreditOutstanding blockers ->
                blockers
                |> terminalFlowNonEmptyEvidenceToList
                |> List.map terminalFlowTerminationCreditBlockerText
                |> String.concat "|"
                |> fun text -> "CreditOutstanding(" + text + ")"
            | TerminalFlowTerminationCreditReturned receipt ->
                FastRuntimeFormat.format
                    "CreditReturned(admitted=%d|receipts=%d|semantic_receipts=%d|terminal_protocol_open=%d|operational_graph_revision=%d|operational_graph_ref=%s|digest=%s)"
                    [| box receipt.schedulerAdmitted
                       box receipt.schedulerReceipts
                       box receipt.semanticReceipts
                       box receipt.terminalProtocolOpen
                       box receipt.operationalGraphRevision
                       box (CompilerIdentityKernel.ContentDigest.text receipt.operationalGraphRef)
                       box (CompilerIdentityKernel.ContentDigest.text receipt.receiptDigest) |]

        let private terminalFlowTerminationCreditDecisionFor (evidence:TerminalFlowProgressEvidence option) =
            match evidence with
            | None ->
                TerminalFlowTerminationCreditOutstanding(
                    terminalFlowNonEmptyEvidence TerminalFlowTerminationCreditNoSnapshot [])
            | Some evidence ->
                let rootSettlement = terminalFlowQapRootSettlementEvidenceFor evidence
                // The snapshot and the credit digest are only needed when credit is returned (no blockers);
                // computing them on every call digested thousands of open units (~25% of
                // mega_spiral_proves' CPU, FRONTIER.md fix 37).
                let semanticLedger = lazy (DiagJson.semanticWorkLedgerSnapshot())
                let semanticCreditDecision =
                    CompilerKernelV2.SemanticWorkLedgerAuthority.creditDecisionForScope
                        CompilerKernelV2.SemanticWorkOperational
                let terminalProtocolCreditDecision =
                    CompilerKernelV2.SemanticWorkLedgerAuthority.creditDecisionForScope
                        CompilerKernelV2.SemanticWorkTerminalProtocol
                let semanticCreditOpenCount =
                    CompilerKernelV2.SemanticWorkCreditDecision.openUnitCount semanticCreditDecision |> int64
                let terminalProtocolOpenCount =
                    CompilerKernelV2.SemanticWorkCreditDecision.openUnitCount terminalProtocolCreditDecision |> int64
                let unclassifiedSemanticOpenCount =
                    CompilerKernelV2.SemanticWorkLedgerAuthority.unclassifiedOpenCount () |> int64
                let semanticCreditDigest = lazy (CompilerKernelV2.SemanticWorkCreditDecision.digest semanticCreditDecision)
                let kernelObligations =
                    evidence.frontier.queueKindCounts.universeConstraint
                    + evidence.frontier.queueKindCounts.defEqObligation
                let admitted = max 0L evidence.workLedger.schedulerAdmittedCount
                let receipts = max 0L evidence.workLedger.schedulerReceiptCount
                let openCount = max 0L evidence.workLedger.schedulerOpenCount
                let blockers = ResizeArray<TerminalFlowTerminationCreditBlocker>()
                match rootSettlement with
                | TerminalFlowQapRootAwaitingCanonicalReceipt(semanticReceipts, canonicalRoots) ->
                    blockers.Add(TerminalFlowTerminationCreditRootUnsettled(semanticReceipts, canonicalRoots))
                | TerminalFlowQapRootSettledByCanonicalReceipt _ -> ()
                if not evidence.queueAttributionComplete then
                    blockers.Add(TerminalFlowTerminationCreditQueueAttributionIncomplete evidence.frontier.queueDepth)
                if admitted <> receipts + openCount then
                    blockers.Add(TerminalFlowTerminationCreditConservationMismatch(admitted, receipts, openCount))
                if openCount > 0L then blockers.Add(TerminalFlowTerminationCreditSchedulerOpen openCount)
                if semanticCreditOpenCount > 0L then blockers.Add(TerminalFlowTerminationCreditSemanticOpen semanticCreditOpenCount)
                if unclassifiedSemanticOpenCount > 0L then
                    blockers.Add(TerminalFlowTerminationCreditUnclassifiedSemanticOpen unclassifiedSemanticOpenCount)
                if terminalProtocolOpenCount > 1L then
                    blockers.Add(TerminalFlowTerminationCreditTerminalProtocolMultiplicity terminalProtocolOpenCount)
                match evidence.workLedger.operationalGraphObservation with
                | TerminalFlowOperationalGraphUnavailable ->
                    blockers.Add TerminalFlowTerminationCreditOperationalGraphUnavailable
                | TerminalFlowOperationalGraphObserved(_, operationalOpenCount, operationalSuspendedCount, _) ->
                    if operationalOpenCount > 0L then
                        blockers.Add(
                            TerminalFlowTerminationCreditOperationalGraphOpen(
                                operationalOpenCount,
                                operationalSuspendedCount))
                // Runnable/queued ownership is a location of conserved scheduler credit, not a
                // second minting authority.  Lane wrappers can remain active while their graph
                // work is already retired, so owner credit may never exceed the actually open
                // scheduler units.  A legitimately executing semantic unit is admitted before
                // it can own a lane, preserving the fail-closed invariant.
                let queuedOwnerCredit = min openCount (max 0L evidence.frontier.queueDepth)
                // Owner locations partition conserved open scheduler credit.  Queue ownership is
                // concrete; activeWorkers may include lane wrappers, so it receives only the
                // remainder.  This makes Runnable+Queued <= openCount by construction.
                let runnableOwnerCredit =
                    min (max 0L (openCount - queuedOwnerCredit)) (max 0L evidence.frontier.activeWorkers)
                if runnableOwnerCredit > 0L then blockers.Add(TerminalFlowTerminationCreditRunnableOwners runnableOwnerCredit)
                if queuedOwnerCredit > 0L then blockers.Add(TerminalFlowTerminationCreditQueuedOwners queuedOwnerCredit)
                if kernelObligations > 0L then blockers.Add(TerminalFlowTerminationCreditKernelObligations kernelObligations)
                if blockers.Count > 0 then
                    TerminalFlowTerminationCreditOutstanding(
                        terminalFlowNonEmptyEvidenceOfList (List.ofSeq blockers))
                else
                    let remaining = max 0L (evidence.frontier.discovered - evidence.frontier.retired)
                    let operationalGraphRevision, operationalGraphRef =
                        match evidence.workLedger.operationalGraphObservation with
                        | TerminalFlowOperationalGraphObserved(graphRevision, _, _, graphRef) -> graphRevision, graphRef
                        | TerminalFlowOperationalGraphUnavailable ->
                            0L, CompilerIdentityKernel.ContentDigest.ofText "operational-work-graph" "unavailable"
                    let receiptDigest =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "terminal-quiescence-credit-return"
                            (FastRuntimeFormat.format
                                "%u|%d|%d|%s|terminal_open=%d|graph_revision=%d|graph_ref=%s|%d|%d|%d"
                                [| box (terminalFlowIdentityRefDigest evidence.snapshotRef)
                                   box admitted
                                   box receipts
                                   box (CompilerIdentityKernel.ContentDigest.text semanticCreditDigest.Value)
                                   box terminalProtocolOpenCount
                                   box operationalGraphRevision
                                   box (CompilerIdentityKernel.ContentDigest.text operationalGraphRef)
                                   box evidence.frontier.discovered
                                   box evidence.frontier.retired
                                   box remaining |])
                    TerminalFlowTerminationCreditReturned {
                        receiptDigest = receiptDigest
                        snapshotRef = evidence.snapshotRef
                        rootSettlement = rootSettlement
                        schedulerAdmitted = admitted
                        schedulerReceipts = receipts
                        semanticReceipts = semanticLedger.Value.receipts
                        semanticCreditDigest = semanticCreditDigest.Value
                        terminalProtocolOpen = terminalProtocolOpenCount
                        operationalGraphRevision = operationalGraphRevision
                        operationalGraphRef = operationalGraphRef
                        discoveredDiagnostic = evidence.frontier.discovered
                        retiredDiagnostic = evidence.frontier.retired
                        remainingDiagnostic = remaining
                        mintedAtMs = Environment.TickCount64
                    }


        type TerminalFlowClosedWorldPromotionGateId =
            | TerminalFlowClosedWorldPromotionEligible
            | TerminalFlowClosedWorldPromotionCreditOutstanding of TerminalFlowNonEmptyEvidence<TerminalFlowTerminationCreditBlocker>

        let private terminalFlowClosedWorldPromotionGateFor (evidence:TerminalFlowProgressEvidence) =
            match terminalFlowTerminationCreditDecisionFor (Some evidence) with
            | TerminalFlowTerminationCreditReturned _ -> TerminalFlowClosedWorldPromotionEligible
            | TerminalFlowTerminationCreditOutstanding blockers ->
                TerminalFlowClosedWorldPromotionCreditOutstanding blockers

        let private terminalFlowClosedWorldPromotionGateText = function
            | TerminalFlowClosedWorldPromotionEligible -> "EligibleByReturnedCredit"
            | TerminalFlowClosedWorldPromotionCreditOutstanding blockers ->
                blockers
                |> terminalFlowNonEmptyEvidenceToList
                |> List.map terminalFlowTerminationCreditBlockerText
                |> String.concat "|"
                |> fun text -> "CreditOutstanding(" + text + ")"


        let private terminalFlowClosedWorldPromotionGateStructuralText = function
            | TerminalFlowClosedWorldPromotionEligible -> "EligibleByReturnedCredit"
            | TerminalFlowClosedWorldPromotionCreditOutstanding blockers ->
                blockers
                |> terminalFlowNonEmptyEvidenceToList
                |> List.map terminalFlowTerminationCreditBlockerText
                |> String.concat "|"
                |> fun text -> "CreditOutstanding(" + text + ")"

        // Age is no longer a termination authority.  Kept only for the generic HUD
        // interface until round 5 removes the old age-oriented display slot.
        let private terminalFlowClosedWorldPromotionGateAgeMs _ = 0L

        let private terminalFlowProgressEvidenceIsExactClosedWorld (evidence:TerminalFlowProgressEvidence) =
            let creditReturned =
                match terminalFlowClosedWorldPromotionGateFor evidence with
                | TerminalFlowClosedWorldPromotionEligible -> true
                | _ -> false
            terminalFlowProgressEvidenceIsStructuralClosedWorld evidence
            && creditReturned

        // A progress snapshot can become operationally closed after its last semantic/frontier
        // mutation. Preserve semantic identity/epoch, but rebase the operational frontier and
        // work ledger from the current typed graph before minting a derived snapshot identity.
        let private terminalFlowProgressEvidenceRefreshOperationalAuthority
            (evidence:TerminalFlowProgressEvidence) =
            match TerminalFlowOperationalGraphSnapshotBridge.read () with
            | Some(graphRevision, openCount, suspendedCount, graphRef)
                when openCount = 0L && suspendedCount = 0L ->
                let nowMs = Environment.TickCount64
                let refreshedSnapshotRef : TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind> =
                    terminalFlowIdentityRefOfText (
                        FastRuntimeFormat.format
                            "operational-closed-world-refresh:%u:%d:%s"
                            [| box (terminalFlowIdentityRefDigest evidence.snapshotRef)
                               box graphRevision
                               box (CompilerIdentityKernel.ContentDigest.text graphRef) |])
                // The live OperationalWorkGraph is the liveness authority.  A reducer
                // progress snapshot may predate the final operational retirements, so do
                // not carry its stale queue/remaining counters across a graph-quiescent
                // receipt.  Preserve semantic identity/epoch, but close only the
                // operational projection that the graph itself has proved empty.
                let closedCost = max 0L evidence.frontier.retired
                let closedQueueKinds : TerminalFlowQueueKindCounts =
                    { crossKindReplayDriver = 0L
                      parentContinuation = 0L
                      declaredBodyVerification = 0L
                      universeConstraint = 0L
                      defEqObligation = 0L
                      proceduralResidual = 0L }
                let closedFrontier : TerminalFlowMonotoneFrontier =
                    { evidence.frontier with
                        discovered = closedCost
                        retired = closedCost
                        blocked = 0L
                        queueDepth = 0L
                        queueKindCounts = closedQueueKinds
                        attributedQueueTop = [] }
                let refreshed =
                    { evidence with
                        snapshotRef = refreshedSnapshotRef
                        frontier = closedFrontier
                        workLedger = terminalFlowWorkLedgerFor refreshedSnapshotRef nowMs closedFrontier evidence.semanticDigest
                        queueAttributionComplete = true
                        observedAtMs = nowMs }
                if terminalFlowProgressEvidenceIsExactClosedWorld refreshed then
                    DiagJson.emit (
                        FastRuntimeFormat.format
                            "{\"kind\":\"terminal_operational_closed_world_rebased\",\"source_snapshot_ref\":%u,\"refreshed_snapshot_ref\":%u,\"graph_revision\":%d,\"graph_ref\":%s,\"before_discovered\":%d,\"before_retired\":%d,\"after_discovered\":%d,\"after_retired\":%d,\"operational_graph_open\":0,\"operational_graph_suspended\":0,\"semantic_identity_preserved\":true,\"authority\":\"live_operational_graph_zero_rebases_operational_frontier_only\",\"next\":\"open_green_path_from_exact_closed_world\"}"
                            [| box (terminalFlowIdentityRefDigest evidence.snapshotRef)
                               box (terminalFlowIdentityRefDigest refreshedSnapshotRef)
                               box graphRevision
                               box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text graphRef))
                               box evidence.frontier.discovered
                               box evidence.frontier.retired
                               box closedFrontier.discovered
                               box closedFrontier.retired |])
                    Some refreshed
                else None
            | _ -> None

        type TerminalFlowTopologyGateCause =
            | TerminalFlowTopologyGateCrossKindDrainReleased of beforeDepth:int64 * afterDepth:int64
            | TerminalFlowTopologyGateRootDrainReleased of completionRef:uint32 * planRef:uint32 * progressSnapshotRef:uint32
            | TerminalFlowTopologyGateQapRelationsConsumed of fixpointRef:uint32 * relationCount:int
            | TerminalFlowTopologyGateOwnerLedgerClosed of ownerCloseRef:uint32
            | TerminalFlowTopologyGateUniverseConstraintResolved of universeReceiptRef:uint32
            | TerminalFlowTopologyGateDefEqWitnessPublished of witnessRef:uint32
            | TerminalFlowTopologyGateUnknownTypedCause of causeRef:TerminalFlowIdentityRef<TerminalFlowTopologyGateRefKind>

        type TerminalFlowTopologyGateTransition = private {
            gateRef : TerminalFlowIdentityRef<TerminalFlowTopologyGateRefKind>
            cause : TerminalFlowTopologyGateCause
            beforeQueueDepth : int64
            afterQueueDepth : int64
            progressSnapshotRef : TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind>
            openedAtMs : int64
        }

        type TerminalFlowTopologyGateState =
            | TerminalFlowTopologyGateClosed
            | TerminalFlowTopologyGateOpened of TerminalFlowTopologyGateTransition

        type TerminalFlowWatchdogPetitionReason =
            | TerminalFlowWatchdogMaterialStasis
            | TerminalFlowWatchdogSchedulerStarvation
            | TerminalFlowWatchdogHostShutdownImminent

        type TerminalFlowWatchdogPetition = private {
            petitionRef : TerminalFlowIdentityRef<TerminalFlowWatchdogPetitionRefKind>
            reason : TerminalFlowWatchdogPetitionReason
            observedAgeMs : int64
            progressSnapshotRef : TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind> option
            requestedAtMs : int64
        }

        type TerminalFlowWatchdogPetitionState =
            | TerminalFlowWatchdogIdle
            | TerminalFlowWatchdogPending of TerminalFlowWatchdogPetition
            | TerminalFlowWatchdogConsumed of TerminalFlowWatchdogPetition * consumedAtRevision:int64

        // MIGRATION MIGRATION : scheduler fairness is now reducer-owned.
        // The assessment isolated the 398 -> 6 cliff around cross_kind_active_replay_driver;
        // this ledger makes replay-driver starvation, recovery folding and Interlocked
        // quarantine explicit typed state instead of HUD prose.
        type TerminalFlowReplayDriverRefKind private () =
            static member IdentityKindTag () = 0x030001u
        type TerminalFlowFairnessEpochRefKind private () =
            static member IdentityKindTag () = 0x030002u
        type TerminalFlowQueueRecoveryRefKind private () =
            static member IdentityKindTag () = 0x030003u
        type TerminalFlowReplayDrainRequestRefKind private () =
            static member IdentityKindTag () = 0x030004u

        type TerminalFlowReplayDriverLane =
            | TerminalFlowReplayDriverLaneCrossKindActive
            | TerminalFlowReplayDriverLaneParentContinuation
            | TerminalFlowReplayDriverLaneDeclaredBodyVerification
            | TerminalFlowReplayDriverLaneCicKernel
            | TerminalFlowReplayDriverLaneWriterSeal
            | TerminalFlowReplayDriverLaneUnknown

        // Fairness cannot carry a half-bound admission anymore.  Root semantic drain and
        // admission-indexed scheduling are different constructors, so the four historical
        // zero refs cannot drift independently.
        type TerminalFlowReplayDriverFairnessLineage =
            | TerminalFlowRootSemanticDrainFairnessLineage of fairnessEpochRef:TerminalFlowIdentityRef<TerminalFlowFairnessEpochRefKind>
            | TerminalFlowAdmissionFairnessLineage of
                admissionRef:uint32 *
                admissionIdentityRef:uint32 *
                actorBindingRef:uint32 *
                credentialLedgerRef:uint32 *
                fairnessEpochRef:TerminalFlowIdentityRef<TerminalFlowFairnessEpochRefKind>

        type TerminalFlowReplayDriverFairnessSample = private {
            sampleRef : TerminalFlowIdentityRef<TerminalFlowFairnessEpochRefKind>
            driverRef : TerminalFlowIdentityRef<TerminalFlowReplayDriverRefKind>
            lineage : TerminalFlowReplayDriverFairnessLineage
            lane : TerminalFlowReplayDriverLane
            queueDepth : int64
            activeWorkers : int64
            retiredWork : int64
            starvationScore : int64
            progressSnapshotRef : TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind>
            sampledAtMs : int64
        } with
            member this.admissionRef =
                match this.lineage with
                | TerminalFlowRootSemanticDrainFairnessLineage _ -> 0u
                | TerminalFlowAdmissionFairnessLineage(admissionRef, _, _, _, _) -> admissionRef
            member this.admissionIdentityRef =
                match this.lineage with
                | TerminalFlowRootSemanticDrainFairnessLineage _ -> 0u
                | TerminalFlowAdmissionFairnessLineage(_, admissionIdentityRef, _, _, _) -> admissionIdentityRef
            member this.actorBindingRef =
                match this.lineage with
                | TerminalFlowRootSemanticDrainFairnessLineage _ -> 0u
                | TerminalFlowAdmissionFairnessLineage(_, _, actorBindingRef, _, _) -> actorBindingRef
            member this.credentialLedgerRef =
                match this.lineage with
                | TerminalFlowRootSemanticDrainFairnessLineage _ -> 0u
                | TerminalFlowAdmissionFairnessLineage(_, _, _, credentialLedgerRef, _) -> credentialLedgerRef
            member this.fairnessEpochRef =
                match this.lineage with
                | TerminalFlowRootSemanticDrainFairnessLineage fairnessEpochRef
                | TerminalFlowAdmissionFairnessLineage(_, _, _, _, fairnessEpochRef) -> fairnessEpochRef

        type TerminalFlowFairnessReleaseRefKind private () =
            static member IdentityKindTag () = 0x030006u
        type TerminalFlowFairnessRequirementRefKind private () =
            static member IdentityKindTag () = 0x030007u
        type TerminalFlowFairnessHolderRefKind private () =
            static member IdentityKindTag () = 0x030008u

