            | TerminalFlowAdmissionFairnessPressureObserved of sampleRef:TerminalFlowIdentityRef<TerminalFlowFairnessEpochRefKind>
            | TerminalFlowAdmissionFairnessReleased of releaseRef:TerminalFlowIdentityRef<TerminalFlowFairnessReleaseRefKind>
            | TerminalFlowAdmissionFairnessRejected of TerminalFlowAdmissionFairnessRejection

        let private terminalFlowAdmissionFairnessRejectionText = function
            | TerminalFlowFairnessAdmissionIdentityMismatch -> "admission_identity_mismatch"

        let private terminalFlowAdmissionFairnessPhaseText = function
            | TerminalFlowAdmissionFairnessAwaitingSample -> "awaiting_sample"
            | TerminalFlowAdmissionFairnessPressureObserved sampleRef -> sprintf "pressure_observed:%u" (terminalFlowIdentityRefDigest sampleRef)
            | TerminalFlowAdmissionFairnessReleased releaseRef -> sprintf "released:%u" (terminalFlowIdentityRefDigest releaseRef)
            | TerminalFlowAdmissionFairnessRejected rejection -> "rejected:" + terminalFlowAdmissionFairnessRejectionText rejection

        type TerminalFlowAdmissionFairnessEpoch = private {
