            sampleRef : TerminalFlowIdentityRef<TerminalFlowFairnessEpochRefKind>
            basis : TerminalFlowFairnessReleaseBasis
            releaseRef : TerminalFlowIdentityRef<TerminalFlowFairnessReleaseRefKind>
            releasedAtMs : int64
            exactOnceRef : uint32
        }
        with
            member x.basisRef : TerminalFlowIdentityRef<TerminalFlowFairnessReleaseRefKind> =
                terminalFlowFairnessReleaseBasisRef x.basis

