        type TerminalFlowSchedulerLineageField =
            | TerminalFlowSchedulerMissingAdmissionRef
            | TerminalFlowSchedulerMissingAdmissionIdentityRef
            | TerminalFlowSchedulerMissingActorBindingRef
            | TerminalFlowSchedulerMissingCredentialLedgerRef
            | TerminalFlowSchedulerMissingFairnessEpochRef

        type TerminalFlowSchedulerLineageFieldPath =
            | TerminalFlowSchedulerLineageFieldLast of TerminalFlowSchedulerLineageField
            | TerminalFlowSchedulerLineageFieldMore of TerminalFlowSchedulerLineageField * TerminalFlowSchedulerLineageFieldPath

        let private terminalFlowSchedulerLineageFieldText = function
            | TerminalFlowSchedulerMissingAdmissionRef -> "admission_ref"
            | TerminalFlowSchedulerMissingAdmissionIdentityRef -> "admission_identity_ref"
            | TerminalFlowSchedulerMissingActorBindingRef -> "actor_binding_ref"
            | TerminalFlowSchedulerMissingCredentialLedgerRef -> "credential_ledger_ref"
            | TerminalFlowSchedulerMissingFairnessEpochRef -> "fairness_epoch_ref"

        let rec private terminalFlowSchedulerLineageFieldPathText = function
            | TerminalFlowSchedulerLineageFieldLast field -> terminalFlowSchedulerLineageFieldText field
            | TerminalFlowSchedulerLineageFieldMore(field, rest) ->
                terminalFlowSchedulerLineageFieldText field + "," + terminalFlowSchedulerLineageFieldPathText rest

        let rec private terminalFlowSchedulerLineageFieldPathForall predicate = function
            | TerminalFlowSchedulerLineageFieldLast field -> predicate field
            | TerminalFlowSchedulerLineageFieldMore(field, rest) ->
                predicate field && terminalFlowSchedulerLineageFieldPathForall predicate rest

        let rec private terminalFlowSchedulerLineageFieldPathOfList = function
            | [] -> None
            | [field] -> Some (TerminalFlowSchedulerLineageFieldLast field)
            | field :: rest ->
                terminalFlowSchedulerLineageFieldPathOfList rest
                |> Option.map (fun path -> TerminalFlowSchedulerLineageFieldMore(field, path))

        type TerminalFlowSchedulerLineageInspection =
            | TerminalFlowSchedulerLineageComplete
            | TerminalFlowSchedulerLineageIncompleteFields of TerminalFlowSchedulerLineageFieldPath

        let private terminalFlowSchedulerLineageInspection (sample:TerminalFlowReplayDriverFairnessSample) =
            [ if sample.admissionRef = 0u then yield TerminalFlowSchedulerMissingAdmissionRef
              if sample.admissionIdentityRef = 0u then yield TerminalFlowSchedulerMissingAdmissionIdentityRef
              if sample.actorBindingRef = 0u then yield TerminalFlowSchedulerMissingActorBindingRef
              if sample.credentialLedgerRef = 0u then yield TerminalFlowSchedulerMissingCredentialLedgerRef
              if terminalFlowIdentityRefDigest sample.fairnessEpochRef = 0u then yield TerminalFlowSchedulerMissingFairnessEpochRef ]
            |> terminalFlowSchedulerLineageFieldPathOfList
            |> function
                | Some missing -> TerminalFlowSchedulerLineageIncompleteFields missing
                | None -> TerminalFlowSchedulerLineageComplete

        let private terminalFlowSchedulerLineageInspectionText = function
            | TerminalFlowSchedulerLineageComplete -> ""
            | TerminalFlowSchedulerLineageIncompleteFields missing -> terminalFlowSchedulerLineageFieldPathText missing

        type TerminalFlowSchedulerReleaseRejection =
            | TerminalFlowSchedulerReleaseIdentityMismatch
            | TerminalFlowSchedulerQuiescenceMissingFairnessRelease

        let private terminalFlowSchedulerReleaseRejectionText = function
            | TerminalFlowSchedulerReleaseIdentityMismatch -> "fairness_release_scheduler_lease_identity_mismatch"
            | TerminalFlowSchedulerQuiescenceMissingFairnessRelease -> "quiescence_missing_fairness_release"

        type TerminalFlowAdmissionSchedulerLease =
            | TerminalFlowAdmissionSchedulerAwaiting of TerminalFlowAdmissionFairnessEpoch
            | TerminalFlowAdmissionSchedulerLineageIncomplete of admissionRef:uint32 * fairnessEpochRef:TerminalFlowIdentityRef<TerminalFlowFairnessEpochRefKind> * missing:TerminalFlowSchedulerLineageFieldPath
            | TerminalFlowAdmissionSchedulerGranted of TerminalFlowSchedulerLeaseGrant
            | TerminalFlowAdmissionSchedulerYieldRequested of TerminalFlowSchedulerLeaseGrant * yieldRef:TerminalFlowIdentityRef<TerminalFlowSchedulerYieldRefKind> * requestedAtRevision:int64
            | TerminalFlowAdmissionSchedulerReleased of TerminalFlowSchedulerPhysicalReleaseReceipt
            | TerminalFlowAdmissionSchedulerRejected of admissionRef:uint32 * fairnessEpochRef:TerminalFlowIdentityRef<TerminalFlowFairnessEpochRefKind> * reason:TerminalFlowSchedulerReleaseRejection

        type TerminalFlowReplayDriverFairnessVerdict =
            | TerminalFlowFairnessBalanced of TerminalFlowReplayDriverFairnessSample
            | TerminalFlowFairnessStarved of TerminalFlowReplayDriverFairnessSample
            | TerminalFlowFairnessYieldRequired of TerminalFlowReplayDriverFairnessSample
            | TerminalFlowFairnessReleasedByTopologyGate of TerminalFlowReplayDriverFairnessSample * TerminalFlowTopologyGateTransition
            | TerminalFlowFairnessReleasedByQuiescence of TerminalFlowReplayDriverFairnessSample * creditDigest:CompilerIdentityKernel.ContentDigest



        type TerminalFlowQueueRecoveryTrigger =
            | TerminalFlowRecoveryFromGhostReconciliation of gate:TerminalFlowTopologyGateTransition * fixpointRef:uint32 * relationCount:int
            | TerminalFlowRecoveryFromFairnessRelease of gate:TerminalFlowTopologyGateTransition * release:TerminalFlowFairnessReleaseReceipt

        type TerminalFlowQueueRecoveryCertificate = private {
            recoveryRef : TerminalFlowIdentityRef<TerminalFlowQueueRecoveryRefKind>
            trigger : TerminalFlowQueueRecoveryTrigger
            gate : TerminalFlowTopologyGateTransition
            exactOnceRef : uint32
        }

        type TerminalFlowQueueRecoveryReducerDecision =
