            schedulerLease : TerminalFlowAdmissionSchedulerLease option
            laneDebt : Map<uint32 * TerminalFlowReplayDriverLane, int64>
            maxConsecutiveBudget : int64
            exactOnceRef : uint32
        }

        type TerminalFlowReducerFairnessState = private {
            admissionEpoch : TerminalFlowAdmissionFairnessEpoch option
            lastSample : TerminalFlowReplayDriverFairnessSample option
            verdict : TerminalFlowReplayDriverFairnessVerdict option
            starvationEvents : int64
            yieldRequests : int64
            releasedEvents : int64
            schedule : TerminalFlowReplayDriverSchedule
            releaseReceipt : TerminalFlowFairnessReleaseReceipt option
            releaseCredential : TerminalFlowFairnessCredential
