        let private terminalFlowReplayDriverLaneText = function
            | TerminalFlowReplayDriverLaneCrossKindActive -> "cross_kind_active_replay_driver"
            | TerminalFlowReplayDriverLaneParentContinuation -> "parent_continuation"
            | TerminalFlowReplayDriverLaneDeclaredBodyVerification -> "declared_body_verification"
            | TerminalFlowReplayDriverLaneCicKernel -> "cic_kernel"
            | TerminalFlowReplayDriverLaneWriterSeal -> "writer_seal"
            | TerminalFlowReplayDriverLaneUnknown -> "unknown"

        let private terminalFlowReplayDriverLaneOfAttribution = function
            | Some attr ->
                match attr.itemKind with
                | TerminalFlowQueueCrossKindReplayDriver -> TerminalFlowReplayDriverLaneCrossKindActive
                | TerminalFlowQueueParentContinuation -> TerminalFlowReplayDriverLaneParentContinuation
                | TerminalFlowQueueDeclaredBodyVerification -> TerminalFlowReplayDriverLaneDeclaredBodyVerification
                | TerminalFlowQueueUniverseConstraint
                | TerminalFlowQueueDefEqObligation -> TerminalFlowReplayDriverLaneCicKernel
                | TerminalFlowQueueProceduralResidual -> TerminalFlowReplayDriverLaneWriterSeal
            | None -> TerminalFlowReplayDriverLaneUnknown

        let private terminalFlowFairnessSampleFor (evidence:TerminalFlowProgressEvidence) =
            let lane =
                [ TerminalFlowReplayDriverLaneCrossKindActive, evidence.frontier.queueKindCounts.crossKindReplayDriver
                  TerminalFlowReplayDriverLaneParentContinuation, evidence.frontier.queueKindCounts.parentContinuation
                  TerminalFlowReplayDriverLaneDeclaredBodyVerification, evidence.frontier.queueKindCounts.declaredBodyVerification
                  TerminalFlowReplayDriverLaneCicKernel, evidence.frontier.queueKindCounts.universeConstraint + evidence.frontier.queueKindCounts.defEqObligation
                  TerminalFlowReplayDriverLaneWriterSeal, evidence.frontier.queueKindCounts.proceduralResidual ]
                |> List.maxBy snd
                |> fst
            let score =
                if evidence.frontier.queueDepth <= 0L then 0L
                elif evidence.frontier.activeWorkers <= 0L then evidence.frontier.queueDepth * 4L
                elif evidence.frontier.queueDepth >= 64L && evidence.frontier.activeWorkers <= 1L then evidence.frontier.queueDepth * 2L
                else max 0L (evidence.frontier.queueDepth - evidence.frontier.retired)
            let sampleRef : TerminalFlowIdentityRef<TerminalFlowFairnessEpochRefKind> =
                terminalFlowIdentityRefOfText (
                    FastRuntimeFormat.format "fairness:%s:q=%d:a=%d:retired=%d:score=%d" [| box (terminalFlowReplayDriverLaneText lane); box evidence.frontier.queueDepth; box evidence.frontier.activeWorkers; box evidence.frontier.retired; box score |])
            let driverRef : TerminalFlowIdentityRef<TerminalFlowReplayDriverRefKind> =
                terminalFlowIdentityRefOfText (sprintf "driver:%s:%u" (terminalFlowReplayDriverLaneText lane) (terminalFlowIdentityRefDigest sampleRef))
            { sampleRef = sampleRef
              driverRef = driverRef
              lineage = TerminalFlowRootSemanticDrainFairnessLineage sampleRef
              lane = lane
              queueDepth = evidence.frontier.queueDepth
              activeWorkers = evidence.frontier.activeWorkers
              retiredWork = evidence.frontier.retired
              starvationScore = score
              progressSnapshotRef = evidence.snapshotRef
              sampledAtMs = evidence.observedAtMs }

        let private terminalFlowAdmissionFairnessEpochFor admissionRef admissionIdentityRef actorBindingRef credentialLedgerRef (epochRef:TerminalFlowIdentityRef<TerminalFlowFairnessEpochRefKind>) nowMs : TerminalFlowAdmissionFairnessEpoch =
            { admissionRef = admissionRef
              admissionIdentityRef = admissionIdentityRef
              actorBindingRef = actorBindingRef
              credentialLedgerRef = credentialLedgerRef
              epochRef = epochRef
              phase = TerminalFlowAdmissionFairnessAwaitingSample
              openedAtMs = nowMs
              updatedAtMs = nowMs
              exactOnceRef =
                terminalFlowExactOnceRefOfText (
                    FastRuntimeFormat.format "fairness-epoch-exact-once:%u:%u:%u:%u:%u" [| box admissionRef; box admissionIdentityRef; box actorBindingRef; box credentialLedgerRef; box (terminalFlowIdentityRefDigest epochRef) |])
                |> terminalFlowIdentityRefDigest }

        // Destructive migration round 3: terminal admission identity is declared before
        // scheduler-channel receipts so downstream authority can carry the identity value
        // itself instead of reconstructing its scalar projections.
        type TerminalFlowOutcomeAdmissionRefKind private () =
            static member IdentityKindTag () = 0x080001u
        type TerminalFlowOutcomeActorRefKind private () =
            static member IdentityKindTag () = 0x080002u
        type TerminalFlowOutcomeActorBindingRefKind private () =
            static member IdentityKindTag () = 0x080003u
        type TerminalFlowRequirementLedgerRefKind private () =
            static member IdentityKindTag () = 0x080004u
        type TerminalFlowOutcomeInstallationRefKind private () =
            static member IdentityKindTag () = 0x080005u
        type TerminalFlowOutcomeConsumeRefKind private () =
            static member IdentityKindTag () = 0x080006u

        type TerminalFlowAdmissionIdentity = private {
            admissionRef : TerminalFlowIdentityRef<TerminalFlowOutcomeAdmissionRefKind>
            admissionRawRef : uint32
            boundActorRef : TerminalFlowIdentityRef<TerminalFlowOutcomeActorRefKind>
            actorBindingRef : TerminalFlowIdentityRef<TerminalFlowOutcomeActorBindingRefKind>
            requirementLedgerRef : TerminalFlowIdentityRef<TerminalFlowRequirementLedgerRefKind>
            fairnessEpochRef : TerminalFlowIdentityRef<TerminalFlowFairnessEpochRefKind>
            mintedAtMs : int64
        }

        let private terminalFlowAdmissionIdentityForRefs
            (terminalReceiptRef:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>)
            (fillKey:TerminalFlowFillKeyId)
            admissionRawRef =
            let terminalReceiptId = terminalFlowIdentityRefText terminalReceiptRef
            let fillKeyText = TerminalFlowFillKeyId.text fillKey
            let admissionRef : TerminalFlowIdentityRef<TerminalFlowOutcomeAdmissionRefKind> =
                terminalFlowIdentityRefOfText (sprintf "terminal-outcome-admission:%u" admissionRawRef)
            { admissionRef = admissionRef
              admissionRawRef = admissionRawRef
              boundActorRef = terminalFlowIdentityRefOfText (sprintf "terminal-outcome-actor:%u:%s" admissionRawRef fillKeyText)
              actorBindingRef = terminalFlowIdentityRefOfText (sprintf "terminal-outcome-actor-binding:%u:%s" admissionRawRef terminalReceiptId)
              requirementLedgerRef = terminalFlowIdentityRefOfText (sprintf "terminal-requirement-ledger:%u" admissionRawRef)
              fairnessEpochRef = terminalFlowIdentityRefOfText (sprintf "terminal-fairness-epoch:%u:%s" admissionRawRef terminalReceiptId)
              mintedAtMs = Environment.TickCount64 }

        let private terminalFlowAdmissionIdentityFor terminalReceiptId fillKey admissionRawRef =
            terminalFlowAdmissionIdentityForRefs
                (terminalFlowIdentityRefOfText terminalReceiptId)
                (TerminalFlowFillKeyId.create fillKey)
                admissionRawRef

        let private terminalFlowAdmissionRawRef identity = identity.admissionRawRef
        let private terminalFlowAdmissionIdentityRef identity = terminalFlowIdentityRefDigest identity.admissionRef
        let private terminalFlowAdmissionActorRef identity = terminalFlowIdentityRefDigest identity.boundActorRef
        let private terminalFlowAdmissionActorBindingRef identity = terminalFlowIdentityRefDigest identity.actorBindingRef
        let private terminalFlowAdmissionRequirementLedgerRef identity = terminalFlowIdentityRefDigest identity.requirementLedgerRef
        let private terminalFlowAdmissionFairnessEpochRef identity = terminalFlowIdentityRefDigest identity.fairnessEpochRef
        let private terminalFlowAdmissionIdentitySame left right =
            left.admissionRawRef = right.admissionRawRef
            && terminalFlowIdentityRefDigest left.admissionRef = terminalFlowIdentityRefDigest right.admissionRef
            && terminalFlowIdentityRefDigest left.boundActorRef = terminalFlowIdentityRefDigest right.boundActorRef
            && terminalFlowIdentityRefDigest left.actorBindingRef = terminalFlowIdentityRefDigest right.actorBindingRef
            && terminalFlowIdentityRefDigest left.requirementLedgerRef = terminalFlowIdentityRefDigest right.requirementLedgerRef
            && terminalFlowIdentityRefDigest left.fairnessEpochRef = terminalFlowIdentityRefDigest right.fairnessEpochRef
        let private terminalFlowAdmissionFairnessEpochForIdentity identity nowMs =
            terminalFlowAdmissionFairnessEpochFor
                (terminalFlowAdmissionRawRef identity)
                (terminalFlowAdmissionIdentityRef identity)
                (terminalFlowAdmissionActorBindingRef identity)
                (terminalFlowAdmissionRequirementLedgerRef identity)
                identity.fairnessEpochRef
                nowMs

        let private terminalFlowFairnessSampleBindEpoch (epoch:TerminalFlowAdmissionFairnessEpoch) (sample:TerminalFlowReplayDriverFairnessSample) : TerminalFlowReplayDriverFairnessSample =
            { sample with
                lineage =
                    TerminalFlowAdmissionFairnessLineage(
                        epoch.admissionRef,
                        epoch.admissionIdentityRef,
                        epoch.actorBindingRef,
                        epoch.credentialLedgerRef,
                        epoch.epochRef) }

        let private terminalFlowFairnessReleaseFor (sample:TerminalFlowReplayDriverFairnessSample) (basis:TerminalFlowFairnessReleaseBasis) releasedAtMs : TerminalFlowFairnessReleaseReceipt =
            let basisRef = terminalFlowFairnessReleaseBasisRef basis
            let releaseRef : TerminalFlowIdentityRef<TerminalFlowFairnessReleaseRefKind> =
                terminalFlowIdentityRefOfText (
                    FastRuntimeFormat.format "fairness-release:%u:%u:%u:%u:%u" [| box sample.admissionRef; box sample.admissionIdentityRef; box sample.actorBindingRef; box sample.credentialLedgerRef; box basisRef |])
            { admissionRef = sample.admissionRef
              admissionIdentityRef = sample.admissionIdentityRef
              actorBindingRef = sample.actorBindingRef
              credentialLedgerRef = sample.credentialLedgerRef
              fairnessEpochRef = sample.fairnessEpochRef
              sampleRef = sample.sampleRef
              basis = basis
              releaseRef = releaseRef
              releasedAtMs = releasedAtMs
              exactOnceRef =
                terminalFlowExactOnceRefOfText (
                    FastRuntimeFormat.format "fairness-release-exact-once:%u:%u:%u:%u:%u" [| box sample.admissionRef; box sample.admissionIdentityRef; box sample.actorBindingRef; box sample.credentialLedgerRef; box (terminalFlowIdentityRefDigest releaseRef) |])
                |> terminalFlowIdentityRefDigest }

        let private terminalFlowFairnessRequirementRefFor admissionRef admissionIdentityRef actorBindingRef credentialLedgerRef epochRef : TerminalFlowIdentityRef<TerminalFlowFairnessRequirementRefKind> =
            terminalFlowIdentityRefOfText (
                FastRuntimeFormat.format "fairness-requirement:%u:%u:%u:%u:%u" [| box admissionRef; box admissionIdentityRef; box actorBindingRef; box credentialLedgerRef; box epochRef |])

        let private terminalFlowFairnessHoldReasonText = function
            | TerminalFlowFairnessHeldAwaitingQuiescence -> "awaiting_quiescence"
            | TerminalFlowFairnessHeldAwaitingSchedulerPhysicalRelease -> "awaiting_scheduler_physical_release"
            | TerminalFlowFairnessHeldAwaitingRecoveryGate -> "awaiting_recovery_gate_after_physical_release"
            | TerminalFlowFairnessHeldByAdmissionIdentityMismatch -> "admission_identity_mismatch"

        let private terminalFlowFairnessHoldFor requirementRef reason basisRef heldSinceMs : TerminalFlowFairnessCredentialHold =
            let reasonText = terminalFlowFairnessHoldReasonText reason
            let basisDigest = basisRef |> Option.map terminalFlowIdentityRefDigest |> Option.defaultValue 0u
            let holderRef : TerminalFlowIdentityRef<TerminalFlowFairnessHolderRefKind> =
                terminalFlowIdentityRefOfText (
                    FastRuntimeFormat.format "fairness-holder:%u:%s:%u:%d" [| box (terminalFlowIdentityRefDigest requirementRef); box reasonText; box basisDigest; box heldSinceMs |])
            { holderRef = holderRef
              requirementRef = requirementRef
              reason = reason
              basisRef = basisRef
              heldSinceMs = heldSinceMs
              exactOnceRef =
                terminalFlowExactOnceRefOfText (
                    FastRuntimeFormat.format "fairness-holder-exact-once:%u:%u:%s:%u:%d" [| box (terminalFlowIdentityRefDigest holderRef); box (terminalFlowIdentityRefDigest requirementRef); box reasonText; box basisDigest; box heldSinceMs |])
                |> terminalFlowIdentityRefDigest }

        let private terminalFlowFairnessCredentialRelease = function
            | TerminalFlowFairnessCredentialMinted release -> Some release
            | TerminalFlowFairnessCredentialAwaiting _
            | TerminalFlowFairnessCredentialHeldBy _ -> None

        let private terminalFlowFairnessCredentialText = function
            | TerminalFlowFairnessCredentialAwaiting requirementRef ->
                sprintf "awaiting:requirement=%u" (terminalFlowIdentityRefDigest requirementRef)
            | TerminalFlowFairnessCredentialHeldBy hold ->
                FastRuntimeFormat.format "held_by:holder=%u:requirement=%u:reason=%s:since_ms=%d:completion=%u" [| box (terminalFlowIdentityRefDigest hold.holderRef); box (terminalFlowIdentityRefDigest hold.requirementRef); box (terminalFlowFairnessHoldReasonText hold.reason); box hold.heldSinceMs; box (hold.basisRef |> Option.map terminalFlowIdentityRefDigest |> Option.defaultValue 0u) |]
            | TerminalFlowFairnessCredentialMinted release ->
                FastRuntimeFormat.format "minted:release=%u:epoch=%u:basis=%u" [| box (terminalFlowIdentityRefDigest release.releaseRef); box (terminalFlowIdentityRefDigest release.fairnessEpochRef); box (terminalFlowIdentityRefDigest release.basisRef) |]

        let private terminalFlowFairnessVerdictFor (topologyGate:TerminalFlowTopologyGateState) (sample:TerminalFlowReplayDriverFairnessSample) =
            // MIGRATION: fairness diagnosis is topology-owned, not admission-owned.
            // Before outcome installation the admission lineage is intentionally absent,
            // but queue starvation is still a real scheduler fact and must not be erased
            // into a synthetic Balanced verdict.
            match topologyGate with
            | TerminalFlowTopologyGateOpened transition when sample.queueDepth <= transition.afterQueueDepth ->
                TerminalFlowFairnessReleasedByTopologyGate(sample, transition)
            | _ when sample.queueDepth >= 64L && sample.activeWorkers <= 1L -> TerminalFlowFairnessStarved sample
            | _ when sample.queueDepth > 0L && sample.activeWorkers = 0L -> TerminalFlowFairnessYieldRequired sample
            | _ -> TerminalFlowFairnessBalanced sample


        let private terminalFlowFairnessVerdictText = function
            | TerminalFlowFairnessBalanced sample -> FastRuntimeFormat.format "Balanced|lane=%s|q=%d|a=%d|score=%d" [| box (terminalFlowReplayDriverLaneText sample.lane); box sample.queueDepth; box sample.activeWorkers; box sample.starvationScore |]
            | TerminalFlowFairnessStarved sample -> FastRuntimeFormat.format "Starved|lane=%s|q=%d|a=%d|score=%d" [| box (terminalFlowReplayDriverLaneText sample.lane); box sample.queueDepth; box sample.activeWorkers; box sample.starvationScore |]
            | TerminalFlowFairnessYieldRequired sample -> FastRuntimeFormat.format "YieldRequired|lane=%s|q=%d|a=%d|score=%d" [| box (terminalFlowReplayDriverLaneText sample.lane); box sample.queueDepth; box sample.activeWorkers; box sample.starvationScore |]
            | TerminalFlowFairnessReleasedByTopologyGate(sample, transition) -> FastRuntimeFormat.format "ReleasedByTopologyGate|lane=%s|q=%d|after=%d|gate_ref=%u" [| box (terminalFlowReplayDriverLaneText sample.lane); box sample.queueDepth; box transition.afterQueueDepth; box (terminalFlowIdentityRefDigest transition.gateRef) |]
            | TerminalFlowFairnessReleasedByQuiescence(sample, creditDigest) ->
                FastRuntimeFormat.format "ReleasedByQuiescence|lane=%s|sample=%u|credit=%s" [| box (terminalFlowReplayDriverLaneText sample.lane); box (terminalFlowIdentityRefDigest sample.sampleRef); box (CompilerIdentityKernel.ContentDigest.text creditDigest) |]

        let private terminalFlowSchedulerCapabilityStepKindText = function
            | TerminalFlowSchedulerCapabilityBudgetGranted -> "budget_granted"
            | TerminalFlowSchedulerCapabilityLaneOwned -> "lane_owned"
            | TerminalFlowSchedulerCapabilityLeaseGranted -> "lease_granted"
            | TerminalFlowSchedulerCapabilityYieldRequested -> "yield_requested"
            | TerminalFlowSchedulerCapabilityFairnessReleased -> "fairness_released"
            | TerminalFlowSchedulerCapabilityPhysicallyReleased -> "physically_released"

        let private terminalFlowSchedulerCapabilitySpineHead = function
            | TerminalFlowSchedulerCapabilityGenesis(_, _, _, _, epochRef) -> "genesis", epochRef
            | TerminalFlowSchedulerCapabilityStep(kind, capabilityRef, _, _) -> terminalFlowSchedulerCapabilityStepKindText kind, capabilityRef

        let rec private terminalFlowSchedulerCapabilitySpineDepth = function
            | TerminalFlowSchedulerCapabilityGenesis _ -> 0
            | TerminalFlowSchedulerCapabilityStep(_, _, _, previous) -> 1 + terminalFlowSchedulerCapabilitySpineDepth previous

        let private terminalFlowSchedulerCapabilitySpinePhysicalReleaseRef = function
            | TerminalFlowSchedulerCapabilityStep(TerminalFlowSchedulerCapabilityPhysicallyReleased, capabilityRef, _, _) -> Some capabilityRef
            | _ -> None

        let private terminalFlowAdmissionWorkerBudgetText (budget:TerminalFlowAdmissionWorkerBudget) =
            FastRuntimeFormat.format "budget=%u|admission=%u|identity=%u|binding=%u|ledger=%u|epoch=%u|requested=%d|granted=%d|cores=%d|q=%d|active=%d|revision=%d" [| box (terminalFlowIdentityRefDigest budget.budgetRef); box budget.admissionRef; box budget.admissionIdentityRef; box budget.actorBindingRef; box budget.credentialLedgerRef; box (terminalFlowIdentityRefDigest budget.fairnessEpochRef); box budget.requestedWorkers; box budget.grantedWorkers; box budget.hostCores; box budget.queueDepth; box budget.activeWorkers; box budget.issuedAtRevision |]

        let private terminalFlowSchedulerLeaseGrantText (grant:TerminalFlowSchedulerLeaseGrant) =
            let spineHeadKind, spineHeadRef = terminalFlowSchedulerCapabilitySpineHead grant.capabilitySpine
            FastRuntimeFormat.format "lease=%u|%s|ownership=%u|driver=%u|lane=%s|spine_depth=%d|spine_head=%s:%u|granted_at=%d" [| box (terminalFlowIdentityRefDigest grant.leaseRef); box (terminalFlowAdmissionWorkerBudgetText grant.budget); box (terminalFlowIdentityRefDigest grant.laneOwnership.ownershipRef); box (terminalFlowIdentityRefDigest grant.laneOwnership.driverRef); box (terminalFlowReplayDriverLaneText grant.laneOwnership.lane); box (terminalFlowSchedulerCapabilitySpineDepth grant.capabilitySpine); box spineHeadKind; box spineHeadRef; box grant.grantedAtRevision |]

        type private TerminalFlowAdmissionSchedulerLeaseCausalIdentity =
            | TerminalFlowSchedulerLeaseCausalAbsent
            | TerminalFlowSchedulerLeaseCausalAwaiting of epochRef:uint32
            | TerminalFlowSchedulerLeaseCausalLineageIncomplete of admissionRef:uint32 * epochRef:uint32 * missing:TerminalFlowSchedulerLineageFieldPath
            | TerminalFlowSchedulerLeaseCausalGranted of leaseRef:uint32
            | TerminalFlowSchedulerLeaseCausalYieldRequested of leaseRef:uint32 * yieldRef:uint32
            | TerminalFlowSchedulerLeaseCausalReleased of leaseRef:uint32 * physicalReleaseRef:uint32
            | TerminalFlowSchedulerLeaseCausalRejected of admissionRef:uint32 * epochRef:uint32 * reason:TerminalFlowSchedulerReleaseRejection

        let private terminalFlowAdmissionSchedulerLeaseCausalIdentity = function
            | None -> TerminalFlowSchedulerLeaseCausalAbsent
            | Some (TerminalFlowAdmissionSchedulerAwaiting epoch) ->
                TerminalFlowSchedulerLeaseCausalAwaiting(terminalFlowIdentityRefDigest epoch.epochRef)
            | Some (TerminalFlowAdmissionSchedulerLineageIncomplete(admissionRef, epochRef, missing)) ->
                TerminalFlowSchedulerLeaseCausalLineageIncomplete(admissionRef, terminalFlowIdentityRefDigest epochRef, missing)
            | Some (TerminalFlowAdmissionSchedulerGranted grant) ->
                TerminalFlowSchedulerLeaseCausalGranted(terminalFlowIdentityRefDigest grant.leaseRef)
            | Some (TerminalFlowAdmissionSchedulerYieldRequested(grant, yieldRef, _)) ->
                TerminalFlowSchedulerLeaseCausalYieldRequested(
                    terminalFlowIdentityRefDigest grant.leaseRef,
                    terminalFlowIdentityRefDigest yieldRef)
            | Some (TerminalFlowAdmissionSchedulerReleased receipt) ->
                TerminalFlowSchedulerLeaseCausalReleased(
                    terminalFlowIdentityRefDigest receipt.leaseRef,
                    terminalFlowIdentityRefDigest receipt.physicalReleaseRef)
            | Some (TerminalFlowAdmissionSchedulerRejected(admissionRef, epochRef, reason)) ->
                TerminalFlowSchedulerLeaseCausalRejected(admissionRef, terminalFlowIdentityRefDigest epochRef, reason)

        let private terminalFlowAdmissionSchedulerLeaseCausalIdentityText = function
            | TerminalFlowSchedulerLeaseCausalAbsent -> "absent"
            | TerminalFlowSchedulerLeaseCausalAwaiting epochRef -> sprintf "awaiting:%u" epochRef
            | TerminalFlowSchedulerLeaseCausalLineageIncomplete(admissionRef, epochRef, missing) ->
                FastRuntimeFormat.format "lineage_incomplete:%u:%u:%s" [| box admissionRef; box epochRef; box (terminalFlowSchedulerLineageFieldPathText missing) |]
            | TerminalFlowSchedulerLeaseCausalGranted leaseRef -> sprintf "granted:%u" leaseRef
            | TerminalFlowSchedulerLeaseCausalYieldRequested(leaseRef, yieldRef) -> sprintf "yield_requested:%u:%u" leaseRef yieldRef
            | TerminalFlowSchedulerLeaseCausalReleased(leaseRef, physicalReleaseRef) -> sprintf "released:%u:%u" leaseRef physicalReleaseRef
            | TerminalFlowSchedulerLeaseCausalRejected(admissionRef, epochRef, reason) ->
                FastRuntimeFormat.format "rejected:%u:%u:%s" [| box admissionRef; box epochRef; box (terminalFlowSchedulerReleaseRejectionText reason) |]

        let private terminalFlowAdmissionSchedulerLeaseText = function
            | TerminalFlowAdmissionSchedulerAwaiting epoch ->
                FastRuntimeFormat.format "awaiting|admission=%u|identity=%u|binding=%u|ledger=%u|epoch=%u" [| box epoch.admissionRef; box epoch.admissionIdentityRef; box epoch.actorBindingRef; box epoch.credentialLedgerRef; box (terminalFlowIdentityRefDigest epoch.epochRef) |]
            | TerminalFlowAdmissionSchedulerLineageIncomplete(admissionRef, epochRef, missing) ->
                FastRuntimeFormat.format "lineage_incomplete|admission=%u|epoch=%u|missing=%s" [| box admissionRef; box (terminalFlowIdentityRefDigest epochRef); box (terminalFlowSchedulerLineageFieldPathText missing) |]
            | TerminalFlowAdmissionSchedulerGranted grant -> "granted|" + terminalFlowSchedulerLeaseGrantText grant
            | TerminalFlowAdmissionSchedulerYieldRequested(grant, yieldRef, revision) ->
                FastRuntimeFormat.format "yield_requested|%s|yield=%u|revision=%d" [| box (terminalFlowSchedulerLeaseGrantText grant); box (terminalFlowIdentityRefDigest yieldRef); box revision |]
            | TerminalFlowAdmissionSchedulerReleased receipt ->
                let spineHeadKind, spineHeadRef = terminalFlowSchedulerCapabilitySpineHead receipt.capabilitySpine
                FastRuntimeFormat.format "released|admission=%u|identity=%u|binding=%u|ledger=%u|epoch=%u|lease=%u|budget=%u|ownership=%u|driver=%u|lane=%s|workers=%d|fairness_release=%u|physical_release=%u|spine_depth=%d|spine_head=%s:%u|revision=%d" [| box receipt.admissionRef; box receipt.admissionIdentityRef; box receipt.actorBindingRef; box receipt.credentialLedgerRef; box (terminalFlowIdentityRefDigest receipt.fairnessEpochRef); box (terminalFlowIdentityRefDigest receipt.leaseRef); box (terminalFlowIdentityRefDigest receipt.budgetRef); box (terminalFlowIdentityRefDigest receipt.laneOwnershipRef); box (terminalFlowIdentityRefDigest receipt.driverRef); box (terminalFlowReplayDriverLaneText receipt.lane); box receipt.grantedWorkers; box (terminalFlowIdentityRefDigest receipt.fairnessReleaseRef); box (terminalFlowIdentityRefDigest receipt.physicalReleaseRef); box (terminalFlowSchedulerCapabilitySpineDepth receipt.capabilitySpine); box spineHeadKind; box spineHeadRef; box receipt.releasedAtRevision |]
            | TerminalFlowAdmissionSchedulerRejected(admissionRef, epochRef, reason) ->
                FastRuntimeFormat.format "rejected|admission=%u|epoch=%u|reason=%s" [| box admissionRef; box (terminalFlowIdentityRefDigest epochRef); box (terminalFlowSchedulerReleaseRejectionText reason) |]

        let private terminalFlowAdmissionWorkerBudgetFor snapshotSequence maxConsecutiveBudget (sample:TerminalFlowReplayDriverFairnessSample) =
            let hostCores = max 1 Environment.ProcessorCount
            let queueSized = int ((max 1L sample.queueDepth + 31L) / 32L)
            let fairnessWorkerCap = max 1 (min 4 (hostCores / 8))
            let requestedWorkers = min fairnessWorkerCap (max 1 queueSized)
            let activeCap = int (min (int64 hostCores) (max 0L sample.activeWorkers))
            let capacity = max 1 (hostCores - activeCap)
            let grantedWorkers = min requestedWorkers (min capacity (int (min maxConsecutiveBudget (int64 requestedWorkers))))
            let budgetRef : TerminalFlowIdentityRef<TerminalFlowSchedulerWorkerBudgetRefKind> =
                terminalFlowIdentityRefOfText (
                    FastRuntimeFormat.format "scheduler-budget:%u:%u:%u:%u:%u:%s:q=%d:a=%d:r=%d:g=%d" [| box sample.admissionRef; box sample.admissionIdentityRef; box sample.actorBindingRef; box sample.credentialLedgerRef; box (terminalFlowIdentityRefDigest sample.fairnessEpochRef); box (terminalFlowReplayDriverLaneText sample.lane); box sample.queueDepth; box sample.activeWorkers; box requestedWorkers; box grantedWorkers |])
            { admissionRef = sample.admissionRef
              admissionIdentityRef = sample.admissionIdentityRef
              actorBindingRef = sample.actorBindingRef
              credentialLedgerRef = sample.credentialLedgerRef
              fairnessEpochRef = sample.fairnessEpochRef
              budgetRef = budgetRef
              requestedWorkers = requestedWorkers
              grantedWorkers = grantedWorkers
              hostCores = hostCores
              queueDepth = sample.queueDepth
              activeWorkers = sample.activeWorkers
              issuedAtRevision = snapshotSequence
              exactOnceRef =
                terminalFlowExactOnceRefOfText (
                    FastRuntimeFormat.format "scheduler-budget-exact-once:%u:%u:%u:%u:%u:%d" [| box sample.admissionRef; box sample.admissionIdentityRef; box sample.actorBindingRef; box sample.credentialLedgerRef; box (terminalFlowIdentityRefDigest budgetRef); box grantedWorkers |])
                |> terminalFlowIdentityRefDigest }

        let private terminalFlowSchedulerLeaseGrantFor snapshotSequence maxConsecutiveBudget (sample:TerminalFlowReplayDriverFairnessSample) =
            let budget = terminalFlowAdmissionWorkerBudgetFor snapshotSequence maxConsecutiveBudget sample
            let ownershipRef : TerminalFlowIdentityRef<TerminalFlowSchedulerLaneOwnershipRefKind> =
                terminalFlowIdentityRefOfText (
                    FastRuntimeFormat.format "scheduler-lane-owner:%u:%u:%u:%u:%u:%u:%s" [| box sample.admissionRef; box sample.admissionIdentityRef; box sample.actorBindingRef; box sample.credentialLedgerRef; box (terminalFlowIdentityRefDigest sample.fairnessEpochRef); box (terminalFlowIdentityRefDigest sample.driverRef); box (terminalFlowReplayDriverLaneText sample.lane) |])
            let laneOwnership =
                { admissionRef = sample.admissionRef
                  admissionIdentityRef = sample.admissionIdentityRef
                  actorBindingRef = sample.actorBindingRef
                  credentialLedgerRef = sample.credentialLedgerRef
                  fairnessEpochRef = sample.fairnessEpochRef
                  ownershipRef = ownershipRef
                  driverRef = sample.driverRef
                  lane = sample.lane
                  acquiredAtRevision = snapshotSequence
                  exactOnceRef =
                    terminalFlowExactOnceRefOfText (
                        FastRuntimeFormat.format "scheduler-lane-ownership-exact-once:%u:%u:%d" [| box sample.admissionRef; box (terminalFlowIdentityRefDigest ownershipRef); box snapshotSequence |])
                    |> terminalFlowIdentityRefDigest }
            let leaseRef : TerminalFlowIdentityRef<TerminalFlowSchedulerLeaseRefKind> =
                terminalFlowIdentityRefOfText (
                    FastRuntimeFormat.format "scheduler-lease:%u:%u:%u:%u:%u:%u:%u" [| box sample.admissionRef; box sample.admissionIdentityRef; box sample.actorBindingRef; box sample.credentialLedgerRef; box (terminalFlowIdentityRefDigest sample.fairnessEpochRef); box (terminalFlowIdentityRefDigest ownershipRef); box (terminalFlowIdentityRefDigest budget.budgetRef) |])
            let genesis =
                TerminalFlowSchedulerCapabilityGenesis(
                    sample.admissionRef,
                    sample.admissionIdentityRef,
                    sample.actorBindingRef,
                    sample.credentialLedgerRef,
                    terminalFlowIdentityRefDigest sample.fairnessEpochRef)
            let budgetStep =
                TerminalFlowSchedulerCapabilityStep(
                    TerminalFlowSchedulerCapabilityBudgetGranted,
                    terminalFlowIdentityRefDigest budget.budgetRef,
                    budget.exactOnceRef,
                    genesis)
            let ownershipStep =
                TerminalFlowSchedulerCapabilityStep(
                    TerminalFlowSchedulerCapabilityLaneOwned,
                    terminalFlowIdentityRefDigest laneOwnership.ownershipRef,
                    laneOwnership.exactOnceRef,
                    budgetStep)
            let leaseExactOnceRef =
                terminalFlowExactOnceRefOfText (
                    FastRuntimeFormat.format "scheduler-lease-exact-once:%u:%u:%u" [| box (terminalFlowIdentityRefDigest leaseRef); box budget.exactOnceRef; box laneOwnership.exactOnceRef |])
                |> terminalFlowIdentityRefDigest
            let capabilitySpine =
                TerminalFlowSchedulerCapabilityStep(
                    TerminalFlowSchedulerCapabilityLeaseGranted,
                    terminalFlowIdentityRefDigest leaseRef,
                    leaseExactOnceRef,
                    ownershipStep)
            { leaseRef = leaseRef
              budget = budget
              laneOwnership = laneOwnership
              capabilitySpine = capabilitySpine
              grantedAtRevision = snapshotSequence
              exactOnceRef = leaseExactOnceRef }

        let private terminalFlowSchedulerPhysicalReleaseFor revision grant (release:TerminalFlowFairnessReleaseReceipt) =
            let sameIdentity =
                grant.budget.admissionRef = release.admissionRef
                && grant.budget.admissionIdentityRef = release.admissionIdentityRef
                && grant.budget.actorBindingRef = release.actorBindingRef
                && grant.budget.credentialLedgerRef = release.credentialLedgerRef
                && terminalFlowIdentityRefDigest grant.budget.fairnessEpochRef = terminalFlowIdentityRefDigest release.fairnessEpochRef
            if not sameIdentity then
                Error TerminalFlowSchedulerReleaseIdentityMismatch
            else
                let physicalReleaseRef : TerminalFlowIdentityRef<TerminalFlowSchedulerPhysicalReleaseRefKind> =
                    terminalFlowIdentityRefOfText (
                        FastRuntimeFormat.format "scheduler-physical-release:%u:%u:%u:%u:%u:%u:%u" [| box release.admissionRef; box release.admissionIdentityRef; box release.actorBindingRef; box release.credentialLedgerRef; box (terminalFlowIdentityRefDigest release.fairnessEpochRef); box (terminalFlowIdentityRefDigest grant.leaseRef); box (terminalFlowIdentityRefDigest release.releaseRef) |])
                let fairnessStep =
                    TerminalFlowSchedulerCapabilityStep(
                        TerminalFlowSchedulerCapabilityFairnessReleased,
                        terminalFlowIdentityRefDigest release.releaseRef,
                        release.exactOnceRef,
                        grant.capabilitySpine)
                let physicalExactOnceRef =
                    terminalFlowExactOnceRefOfText (
                        FastRuntimeFormat.format "scheduler-physical-release-exact-once:%u:%u:%u" [| box grant.exactOnceRef; box release.exactOnceRef; box (terminalFlowIdentityRefDigest physicalReleaseRef) |])
                    |> terminalFlowIdentityRefDigest
                let capabilitySpine =
                    TerminalFlowSchedulerCapabilityStep(
                        TerminalFlowSchedulerCapabilityPhysicallyReleased,
                        terminalFlowIdentityRefDigest physicalReleaseRef,
                        physicalExactOnceRef,
                        fairnessStep)
                Ok {
                    admissionRef = release.admissionRef
                    admissionIdentityRef = release.admissionIdentityRef
                    actorBindingRef = release.actorBindingRef
                    credentialLedgerRef = release.credentialLedgerRef
                    fairnessEpochRef = release.fairnessEpochRef
                    leaseRef = grant.leaseRef
                    budgetRef = grant.budget.budgetRef
                    laneOwnershipRef = grant.laneOwnership.ownershipRef
                    driverRef = grant.laneOwnership.driverRef
                    lane = grant.laneOwnership.lane
                    grantedWorkers = grant.budget.grantedWorkers
                    fairnessReleaseRef = release.releaseRef
                    physicalReleaseRef = physicalReleaseRef
                    capabilitySpine = capabilitySpine
                    releasedAtRevision = revision
                    exactOnceRef = physicalExactOnceRef
                }

        let private terminalFlowSchedulerPhysicalReleaseSameIdentity (expected:TerminalFlowSchedulerPhysicalReleaseReceipt) (actual:TerminalFlowSchedulerPhysicalReleaseReceipt) =
            expected.admissionRef = actual.admissionRef
            && expected.admissionIdentityRef = actual.admissionIdentityRef
            && expected.actorBindingRef = actual.actorBindingRef
            && expected.credentialLedgerRef = actual.credentialLedgerRef
            && terminalFlowIdentityRefDigest expected.fairnessEpochRef = terminalFlowIdentityRefDigest actual.fairnessEpochRef
            && terminalFlowIdentityRefDigest expected.leaseRef = terminalFlowIdentityRefDigest actual.leaseRef
            && terminalFlowIdentityRefDigest expected.budgetRef = terminalFlowIdentityRefDigest actual.budgetRef
            && terminalFlowIdentityRefDigest expected.laneOwnershipRef = terminalFlowIdentityRefDigest actual.laneOwnershipRef
            && terminalFlowIdentityRefDigest expected.driverRef = terminalFlowIdentityRefDigest actual.driverRef
            && expected.lane = actual.lane
            && expected.grantedWorkers = actual.grantedWorkers
            && terminalFlowIdentityRefDigest expected.fairnessReleaseRef = terminalFlowIdentityRefDigest actual.fairnessReleaseRef
            && terminalFlowIdentityRefDigest expected.physicalReleaseRef = terminalFlowIdentityRefDigest actual.physicalReleaseRef
            && expected.exactOnceRef = actual.exactOnceRef
            && terminalFlowSchedulerCapabilitySpinePhysicalReleaseRef actual.capabilitySpine = Some (terminalFlowIdentityRefDigest actual.physicalReleaseRef)


        let private terminalFlowReplayDriverScheduleInitial = {
            epoch = 0L
            schedulerLease = None
            laneDebt = Map.empty
            maxConsecutiveBudget = 64L
            exactOnceRef = NativeCutoverStableRef.ref32 "replay-driver-schedule-genesis" ["genesis"]
        }

        let private terminalFlowReplayDriverScheduleAdvance snapshotSequence (verdict:TerminalFlowReplayDriverFairnessVerdict) (releaseReceipt:TerminalFlowFairnessReleaseReceipt option) (schedule:TerminalFlowReplayDriverSchedule) =
            let sample =
                match verdict with
                | TerminalFlowFairnessBalanced sample
                | TerminalFlowFairnessStarved sample
                | TerminalFlowFairnessYieldRequired sample
                | TerminalFlowFairnessReleasedByTopologyGate(sample, _)
                | TerminalFlowFairnessReleasedByQuiescence(sample, _) -> sample
            let lineageInspection = terminalFlowSchedulerLineageInspection sample
            let laneKey = sample.admissionRef, sample.lane
            match lineageInspection with
            | TerminalFlowSchedulerLineageIncompleteFields missingLineage ->
                let laneDebt = Map.remove laneKey schedule.laneDebt
                let schedulerLease =
                    Some (TerminalFlowAdmissionSchedulerLineageIncomplete(sample.admissionRef, sample.fairnessEpochRef, missingLineage))
                { epoch = schedule.epoch + 1L
                  schedulerLease = schedulerLease
                  laneDebt = laneDebt
                  maxConsecutiveBudget = schedule.maxConsecutiveBudget
                  exactOnceRef =
                    NativeCutoverStableRef.ref32
                        "replay-driver-schedule-lineage-incomplete"
                        [ string snapshotSequence
                          "lineage_incomplete_scheduler_capability"
                          terminalFlowReplayDriverLaneText sample.lane
                          terminalFlowSchedulerLineageFieldPathText missingLineage ] }
            | TerminalFlowSchedulerLineageComplete ->
                let priorDebt = schedule.laneDebt |> Map.tryFind laneKey |> Option.defaultValue 0L
                let grant = terminalFlowSchedulerLeaseGrantFor snapshotSequence schedule.maxConsecutiveBudget sample
                let laneDebt, schedulerLease =
                    match releaseReceipt with
                    | Some release ->
                        let nextDebt = Map.add laneKey 0L schedule.laneDebt
                        match schedule.schedulerLease with
                        | Some (TerminalFlowAdmissionSchedulerReleased retained)
                            when retained.admissionRef = release.admissionRef
                                 && retained.admissionIdentityRef = release.admissionIdentityRef
                                 && retained.actorBindingRef = release.actorBindingRef
                                 && retained.credentialLedgerRef = release.credentialLedgerRef
                                 && terminalFlowIdentityRefDigest retained.fairnessEpochRef = terminalFlowIdentityRefDigest release.fairnessEpochRef
                                 && terminalFlowIdentityRefDigest retained.fairnessReleaseRef = terminalFlowIdentityRefDigest release.releaseRef ->
                            // Physical release is an exact-once capability. Fairness resampling may
                            // update observations, but it must never remint the sealed scheduler identity.
                            nextDebt, schedule.schedulerLease
                        | _ ->
                            match terminalFlowSchedulerPhysicalReleaseFor snapshotSequence grant release with
                            | Ok receipt -> nextDebt, Some (TerminalFlowAdmissionSchedulerReleased receipt)
                            | Error reason -> nextDebt, Some (TerminalFlowAdmissionSchedulerRejected(sample.admissionRef, sample.fairnessEpochRef, reason))
                    | None ->
                        match verdict with
                        | TerminalFlowFairnessBalanced _ ->
                            Map.add laneKey (max 0L (priorDebt - max 1L sample.retiredWork)) schedule.laneDebt,
                            Some (TerminalFlowAdmissionSchedulerGranted grant)
                        | TerminalFlowFairnessStarved _
                        | TerminalFlowFairnessYieldRequired _
                        | TerminalFlowFairnessReleasedByTopologyGate _ ->
                            let yieldRef : TerminalFlowIdentityRef<TerminalFlowSchedulerYieldRefKind> =
                                terminalFlowIdentityRefOfText (
                                    FastRuntimeFormat.format "scheduler-yield:%u:%u:%u:%u:%u:%u" [| box sample.admissionRef; box sample.admissionIdentityRef; box sample.actorBindingRef; box sample.credentialLedgerRef; box (terminalFlowIdentityRefDigest sample.fairnessEpochRef); box (terminalFlowIdentityRefDigest grant.leaseRef) |])
                            let yieldExactOnceRef =
                                NativeCutoverStableRef.ref32
                                    "replay-driver-scheduler-yield"
                                    [ string grant.exactOnceRef
                                      string (terminalFlowIdentityRefDigest yieldRef)
                                      string snapshotSequence ]
                            let yieldGrant =
                                { grant with
                                    capabilitySpine =
                                        TerminalFlowSchedulerCapabilityStep(
                                            TerminalFlowSchedulerCapabilityYieldRequested,
                                            terminalFlowIdentityRefDigest yieldRef,
                                            yieldExactOnceRef,
                                            grant.capabilitySpine)
                                    exactOnceRef = yieldExactOnceRef }
                            Map.add laneKey (priorDebt + max 1L sample.queueDepth) schedule.laneDebt,
                            Some (TerminalFlowAdmissionSchedulerYieldRequested(yieldGrant, yieldRef, snapshotSequence))
                        | TerminalFlowFairnessReleasedByQuiescence _ ->
                            Map.add laneKey priorDebt schedule.laneDebt,
                            Some (TerminalFlowAdmissionSchedulerRejected(sample.admissionRef, sample.fairnessEpochRef, TerminalFlowSchedulerQuiescenceMissingFairnessRelease))
                let leaseText = schedulerLease |> Option.map terminalFlowAdmissionSchedulerLeaseText |> Option.defaultValue "none"
                { epoch = schedule.epoch + 1L
                  schedulerLease = schedulerLease
                  laneDebt = laneDebt
                  maxConsecutiveBudget = schedule.maxConsecutiveBudget
                  exactOnceRef =
                    NativeCutoverStableRef.ref32
                        "replay-driver-schedule-advance"
                        [ string snapshotSequence
                          string sample.admissionRef
                          string sample.admissionIdentityRef
                          string sample.actorBindingRef
                          string sample.credentialLedgerRef
                          string (terminalFlowIdentityRefDigest sample.fairnessEpochRef)
                          leaseText
                          string (laneDebt |> Map.tryFind laneKey |> Option.defaultValue 0L) ] }

        let private terminalFlowFairnessInitial =
            let initialRequirement : TerminalFlowIdentityRef<TerminalFlowFairnessRequirementRefKind> =
                terminalFlowIdentityRefOfText "fairness-requirement:unbound"
            { admissionEpoch = None
              lastSample = None
              verdict = None
              starvationEvents = 0L
              yieldRequests = 0L
              releasedEvents = 0L
              schedule = terminalFlowReplayDriverScheduleInitial
              releaseReceipt = None
              releaseCredential = TerminalFlowFairnessCredentialAwaiting initialRequirement
              exactOnceRef = NativeCutoverStableRef.ref32 "terminal-flow-fairness-initial" ["initial"] }

        let private terminalFlowFairnessAdvance (fairnessEpoch:TerminalFlowAdmissionFairnessEpoch option) (topologyGate:TerminalFlowTopologyGateState) (evidence:TerminalFlowProgressEvidence) (state:TerminalFlowReducerFairnessState) =
            let rawSample = terminalFlowFairnessSampleFor evidence
            let sample =
                match fairnessEpoch with
                | Some epoch -> terminalFlowFairnessSampleBindEpoch epoch rawSample
                | None -> rawSample
            let retainedRelease =
                match fairnessEpoch, state.releaseReceipt with
                | Some epoch, Some release
                    when release.admissionRef = epoch.admissionRef
                         && release.admissionIdentityRef = epoch.admissionIdentityRef
                         && release.actorBindingRef = epoch.actorBindingRef
                         && release.credentialLedgerRef = epoch.credentialLedgerRef
                         && terminalFlowIdentityRefDigest release.fairnessEpochRef = terminalFlowIdentityRefDigest epoch.epochRef -> Some release
                | None, Some release
                    when release.admissionRef = 0u
                         && release.admissionIdentityRef = 0u
                         && release.actorBindingRef = 0u
                         && release.credentialLedgerRef = 0u -> Some release
                | _ -> None
            let creditDecision = terminalFlowTerminationCreditDecisionFor (Some evidence)
            let quiescenceDigest : CompilerIdentityKernel.ContentDigest option =
                match creditDecision with
                | TerminalFlowTerminationCreditReturned receipt -> Some receipt.receiptDigest
                | TerminalFlowTerminationCreditOutstanding _ -> None
            let observedVerdict = terminalFlowFairnessVerdictFor topologyGate sample
            let verdict =
                match retainedRelease, quiescenceDigest with
                | Some _, _ -> TerminalFlowFairnessBalanced sample
                | None, Some digest -> TerminalFlowFairnessReleasedByQuiescence(sample, digest)
                | None, None -> observedVerdict
            let releaseReceipt =
                match retainedRelease, verdict with
                | Some release, _ -> Some release
                | None, TerminalFlowFairnessReleasedByQuiescence(subject, digest) ->
                    Some (terminalFlowFairnessReleaseFor subject (TerminalFlowFairnessReleaseByQuiescence digest) evidence.observedAtMs)
                | None, TerminalFlowFairnessReleasedByTopologyGate(subject, transition) ->
                    Some (terminalFlowFairnessReleaseFor subject (TerminalFlowFairnessReleaseByTopologyGate transition.gateRef) evidence.observedAtMs)
                | _ -> None
            let schedule = terminalFlowReplayDriverScheduleAdvance evidence.snapshotSequence verdict releaseReceipt state.schedule
            let nextEpoch =
                match fairnessEpoch, releaseReceipt with
                | Some epoch, Some release ->
                    Some { epoch with
                            phase = TerminalFlowAdmissionFairnessReleased release.releaseRef
                            updatedAtMs = release.releasedAtMs
                            exactOnceRef = NativeCutoverStableRef.ref32 "fairness-epoch-release" [string epoch.exactOnceRef; string (terminalFlowIdentityRefDigest release.releaseRef)] }
                | Some epoch, None ->
                    Some { epoch with
                            phase = TerminalFlowAdmissionFairnessPressureObserved sample.sampleRef
                            updatedAtMs = evidence.observedAtMs
                            exactOnceRef = NativeCutoverStableRef.ref32 "fairness-epoch-pressure-sample" [string epoch.exactOnceRef; string (terminalFlowIdentityRefDigest sample.sampleRef)] }
                | None, _ -> None
            let requirementRef =
                terminalFlowFairnessRequirementRefFor
                    sample.admissionRef sample.admissionIdentityRef sample.actorBindingRef sample.credentialLedgerRef
                    (terminalFlowIdentityRefDigest sample.fairnessEpochRef)
            let releaseCredential =
                match releaseReceipt, state.releaseCredential with
                | Some release, TerminalFlowFairnessCredentialMinted existing
                    when terminalFlowIdentityRefDigest existing.releaseRef = terminalFlowIdentityRefDigest release.releaseRef ->
                    TerminalFlowFairnessCredentialMinted release
                | Some release, _ -> TerminalFlowFairnessCredentialMinted release
                | None, (TerminalFlowFairnessCredentialMinted _ as minted) -> minted
                | None, _ ->
                    terminalFlowFairnessHoldFor requirementRef TerminalFlowFairnessHeldAwaitingQuiescence None evidence.observedAtMs
                    |> TerminalFlowFairnessCredentialHeldBy
            { admissionEpoch = nextEpoch
              lastSample = Some sample
              verdict = Some verdict
              starvationEvents = state.starvationEvents + (match verdict with | TerminalFlowFairnessStarved _ -> 1L | _ -> 0L)
              yieldRequests = state.yieldRequests + (match verdict with | TerminalFlowFairnessYieldRequired _ -> 1L | _ -> 0L)
              releasedEvents = state.releasedEvents + (if Option.isSome releaseReceipt && Option.isNone state.releaseReceipt then 1L else 0L)
              schedule = schedule
              releaseReceipt = releaseReceipt
              releaseCredential = releaseCredential
              exactOnceRef = NativeCutoverStableRef.ref32
                    "terminal-flow-fairness-credit-advance"
                    [ string state.exactOnceRef
                      string sample.admissionRef
                      string sample.admissionIdentityRef
                      string sample.actorBindingRef
                      string sample.credentialLedgerRef
                      string (terminalFlowIdentityRefDigest sample.sampleRef)
                      terminalFlowFairnessVerdictText verdict
                      terminalFlowFairnessCredentialText releaseCredential
                      terminalFlowTerminationCreditDecisionText creditDecision
                      string schedule.exactOnceRef ] }

        let private terminalFlowQueueRecoveryInitial =
            { decision = TerminalFlowQueueRecoveryAwaitingEvidence
              foldedAtRevision = None
              exactOnceRef = NativeCutoverStableRef.ref32 "terminal-flow-queue-recovery-initial" ["initial"] }

        let private terminalFlowQueueRecoveryTriggerText = function
            | TerminalFlowRecoveryFromGhostReconciliation(gate, fixpointRef, relationCount) ->
                FastRuntimeFormat.format "ghost_reconciliation:gate=%u:fixpoint=%u:relations=%d" [| box (terminalFlowIdentityRefDigest gate.gateRef); box fixpointRef; box relationCount |]
            | TerminalFlowRecoveryFromFairnessRelease(gate, release) ->
                FastRuntimeFormat.format "fairness_release:gate=%u:admission=%u:identity=%u:binding=%u:ledger=%u:epoch=%u:release=%u:sample=%u" [| box (terminalFlowIdentityRefDigest gate.gateRef); box release.admissionRef; box release.admissionIdentityRef; box release.actorBindingRef; box release.credentialLedgerRef; box (terminalFlowIdentityRefDigest release.fairnessEpochRef); box (terminalFlowIdentityRefDigest release.releaseRef); box (terminalFlowIdentityRefDigest release.sampleRef) |]

        let private terminalFlowQueueRecoveryDecisionText = function
            | TerminalFlowQueueRecoveryAwaitingEvidence -> "awaiting_evidence"
            | TerminalFlowQueueRecoveryHeldByFairness hold ->
                FastRuntimeFormat.format "held_by_fairness:holder=%u:requirement=%u:reason=%s:since_ms=%d:completion=%u" [| box (terminalFlowIdentityRefDigest hold.holderRef); box (terminalFlowIdentityRefDigest hold.requirementRef); box (terminalFlowFairnessHoldReasonText hold.reason); box hold.heldSinceMs; box (hold.basisRef |> Option.map terminalFlowIdentityRefDigest |> Option.defaultValue 0u) |]
            | TerminalFlowQueueRecoveryReadyForReducerSeal certificate ->
                FastRuntimeFormat.format "ready_for_reducer_seal:recovery=%u:gate=%u:trigger=%s:exact_once=%u" [| box (terminalFlowIdentityRefDigest certificate.recoveryRef); box (terminalFlowIdentityRefDigest certificate.gate.gateRef); box (terminalFlowQueueRecoveryTriggerText certificate.trigger); box certificate.exactOnceRef |]
            | TerminalFlowQueueRecoveryRejectedByProgressRegression _ ->
                "rejected_by_progress_regression"

        let private terminalFlowQueueRecoveryCertificateFor trigger =
            let gate =
                match trigger with
                | TerminalFlowRecoveryFromGhostReconciliation(gate, _, _)
                | TerminalFlowRecoveryFromFairnessRelease(gate, _) -> gate
            let identityText = terminalFlowQueueRecoveryTriggerText trigger
            let recoveryRef : TerminalFlowIdentityRef<TerminalFlowQueueRecoveryRefKind> =
                terminalFlowIdentityRefOfText ("queue-recovery:" + identityText)
            { recoveryRef = recoveryRef
              trigger = trigger
              gate = gate
              exactOnceRef = NativeCutoverStableRef.ref32 "queue-recovery-certificate-exact-once" [identityText] }


        let private terminalFlowQueueRecoveryDecisionFor revision topologyGate progressAuthority fairness =
            match progressAuthority.rejected with
            | Some regression -> TerminalFlowQueueRecoveryRejectedByProgressRegression regression
            | None ->
                let releaseReceipt = terminalFlowFairnessCredentialRelease fairness.releaseCredential
                let fairnessRecovery =
                    match topologyGate, fairness.verdict, releaseReceipt, fairness.schedule.schedulerLease with
                    | TerminalFlowTopologyGateOpened gate,
                      Some (TerminalFlowFairnessReleasedByQuiescence(_, creditDigest)),
                      Some release,
                      Some (TerminalFlowAdmissionSchedulerReleased schedulerRelease)
                        when release.admissionRef = schedulerRelease.admissionRef
                             && release.admissionIdentityRef = schedulerRelease.admissionIdentityRef
                             && release.actorBindingRef = schedulerRelease.actorBindingRef
                             && release.credentialLedgerRef = schedulerRelease.credentialLedgerRef
                             && terminalFlowIdentityRefDigest release.fairnessEpochRef = terminalFlowIdentityRefDigest schedulerRelease.fairnessEpochRef
                             && terminalFlowIdentityRefDigest release.releaseRef = terminalFlowIdentityRefDigest schedulerRelease.fairnessReleaseRef
                             && (match release.basis with | TerminalFlowFairnessReleaseByQuiescence digest -> digest = creditDigest | _ -> false) ->
                        TerminalFlowRecoveryFromFairnessRelease(gate, release)
                        |> terminalFlowQueueRecoveryCertificateFor
                        |> Some
                    | TerminalFlowTopologyGateOpened gate,
                      Some (TerminalFlowFairnessReleasedByTopologyGate(_, transition)),
                      Some release,
                      Some (TerminalFlowAdmissionSchedulerReleased schedulerRelease)
                        when terminalFlowIdentityRefDigest gate.gateRef = terminalFlowIdentityRefDigest transition.gateRef
                             && release.admissionRef = schedulerRelease.admissionRef
                             && release.admissionIdentityRef = schedulerRelease.admissionIdentityRef
                             && release.actorBindingRef = schedulerRelease.actorBindingRef
                             && release.credentialLedgerRef = schedulerRelease.credentialLedgerRef
                             && terminalFlowIdentityRefDigest release.fairnessEpochRef = terminalFlowIdentityRefDigest schedulerRelease.fairnessEpochRef
                             && terminalFlowIdentityRefDigest release.releaseRef = terminalFlowIdentityRefDigest schedulerRelease.fairnessReleaseRef ->
                        TerminalFlowRecoveryFromFairnessRelease(gate, release)
                        |> terminalFlowQueueRecoveryCertificateFor
                        |> Some
                    | TerminalFlowTopologyGateOpened gate,
                      Some (TerminalFlowFairnessBalanced _),
                      Some release,
                      Some (TerminalFlowAdmissionSchedulerReleased schedulerRelease)
                        when release.admissionRef = schedulerRelease.admissionRef
                             && release.admissionIdentityRef = schedulerRelease.admissionIdentityRef
                             && release.actorBindingRef = schedulerRelease.actorBindingRef
                             && release.credentialLedgerRef = schedulerRelease.credentialLedgerRef
                             && terminalFlowIdentityRefDigest release.fairnessEpochRef = terminalFlowIdentityRefDigest schedulerRelease.fairnessEpochRef
                             && terminalFlowIdentityRefDigest release.releaseRef = terminalFlowIdentityRefDigest schedulerRelease.fairnessReleaseRef ->
                        TerminalFlowRecoveryFromFairnessRelease(gate, release)
                        |> terminalFlowQueueRecoveryCertificateFor
                        |> Some
                    | _ -> None
                match fairnessRecovery with
                | Some certificate -> TerminalFlowQueueRecoveryReadyForReducerSeal certificate
                | None ->
                    match fairness.releaseCredential with
                    | TerminalFlowFairnessCredentialHeldBy hold -> TerminalFlowQueueRecoveryHeldByFairness hold
                    | TerminalFlowFairnessCredentialAwaiting requirementRef ->
                        match fairness.verdict with
                        | None -> TerminalFlowQueueRecoveryAwaitingEvidence
                        | Some _ ->
                            let heldSinceMs = fairness.lastSample |> Option.map (fun sample -> sample.sampledAtMs) |> Option.defaultValue revision
                            terminalFlowFairnessHoldFor requirementRef TerminalFlowFairnessHeldAwaitingQuiescence None heldSinceMs
                            |> TerminalFlowQueueRecoveryHeldByFairness
                    | TerminalFlowFairnessCredentialMinted release ->
                        let requirementRef =
                            terminalFlowFairnessRequirementRefFor release.admissionRef release.admissionIdentityRef release.actorBindingRef release.credentialLedgerRef (terminalFlowIdentityRefDigest release.fairnessEpochRef)
                        let holdReason =
                            match fairness.schedule.schedulerLease with
                            | Some (TerminalFlowAdmissionSchedulerReleased _) -> TerminalFlowFairnessHeldAwaitingRecoveryGate
                            | _ -> TerminalFlowFairnessHeldAwaitingSchedulerPhysicalRelease
                        terminalFlowFairnessHoldFor requirementRef holdReason None release.releasedAtMs
                        |> TerminalFlowQueueRecoveryHeldByFairness

        let private terminalFlowQueueRecoveryAdvance revision topologyGate progressAuthority fairness state =
            let observedDecision = terminalFlowQueueRecoveryDecisionFor revision topologyGate progressAuthority fairness
            match state.decision, observedDecision with
            | TerminalFlowQueueRecoveryReadyForReducerSeal _,
              TerminalFlowQueueRecoveryRejectedByProgressRegression _ ->
                { decision = observedDecision
                  foldedAtRevision = Some revision
                  exactOnceRef =
                      NativeCutoverStableRef.ref32
                          "terminal-flow-queue-recovery-advance"
                          [string state.exactOnceRef; string revision; terminalFlowQueueRecoveryDecisionText observedDecision] }
            | TerminalFlowQueueRecoveryReadyForReducerSeal _, _ ->
                { state with foldedAtRevision = Some revision }
            | _ ->
                { decision = observedDecision
                  foldedAtRevision = Some revision
                  exactOnceRef =
                      NativeCutoverStableRef.ref32
                          "terminal-flow-queue-recovery-advance"
                          [string state.exactOnceRef; string revision; terminalFlowQueueRecoveryDecisionText observedDecision] }

        let private terminalFlowLegacyAuthorityEraseReceiptFor erased replacement recoveryRef =
            { erasedSurface = erased
              replacementSurface = replacement
              proofRef = recoveryRef
              exactOnceRef =
                  NativeCutoverStableRef.ref32
                      "terminal-flow-legacy-authority-erased"
                      [erased; replacement; string (terminalFlowIdentityRefDigest recoveryRef)] }

        let private terminalFlowGreenPathSealIntentFor (recoveryRef:TerminalFlowIdentityRef<TerminalFlowQueueRecoveryRefKind>) (gate:TerminalFlowTopologyGateTransition) (fillKey:TerminalFlowFillKeyId) =
            let fillKeyText = TerminalFlowFillKeyId.text fillKey
            let writerReceiptId = sprintf "writer-receipt:queue-recovery:%u:%s" (terminalFlowIdentityRefDigest recoveryRef) fillKeyText
            { recoveryRef = recoveryRef
              gateRef = gate.gateRef
              fillKey = fillKey
              writerReceiptId = writerReceiptId
              exactOnceRef =
                  NativeCutoverStableRef.ref32
                      "terminal-flow-green-path-seal-intent"
                      [ string (terminalFlowIdentityRefDigest recoveryRef)
                        string (terminalFlowIdentityRefDigest gate.gateRef)
                        fillKeyText
                        writerReceiptId ] }

        let private terminalFlowGreenPathSealIntentText intent =
            FastRuntimeFormat.format "GreenPathSealIntent(recovery_ref=%u|gate_ref=%u|fill=%s|writer=%s|exact_once=%u)" [| box (terminalFlowIdentityRefDigest intent.recoveryRef); box (terminalFlowIdentityRefDigest intent.gateRef); box (TerminalFlowFillKeyId.text intent.fillKey); box intent.writerReceiptId; box intent.exactOnceRef |]

        let private terminalFlowProgressPhaseText = function
            | TerminalFlowProgressDag -> "dag"
            | TerminalFlowProgressSemantic -> "semantic"
            | TerminalFlowProgressTerminal -> "terminal"
            | TerminalFlowProgressWriter -> "writer"
            | TerminalFlowProgressProofKernel -> "proof_kernel"

        let private terminalFlowQueueItemKindText = function
            | TerminalFlowQueueCrossKindReplayDriver -> "cross_kind_replay_driver"
            | TerminalFlowQueueParentContinuation -> "parent_continuation"
            | TerminalFlowQueueDeclaredBodyVerification -> "declared_body_verification"
            | TerminalFlowQueueUniverseConstraint -> "universe_constraint"
            | TerminalFlowQueueDefEqObligation -> "defeq_obligation"
            | TerminalFlowQueueProceduralResidual -> "procedural_residual"

        let private terminalFlowQueueKindCountsTotal counts =
            counts.crossKindReplayDriver
            + counts.parentContinuation
            + counts.declaredBodyVerification
            + counts.universeConstraint
            + counts.defEqObligation
            + counts.proceduralResidual

        let private terminalFlowQueueKindCountsText counts =
            FastRuntimeFormat.format "cross=%d|parent=%d|declared_body=%d|universe=%d|defeq=%d|procedural=%d" [| box counts.crossKindReplayDriver; box counts.parentContinuation; box counts.declaredBodyVerification; box counts.universeConstraint; box counts.defEqObligation; box counts.proceduralResidual |]

        let private terminalFlowProgressRemaining evidence =
            max 0L (evidence.frontier.discovered - evidence.frontier.retired)

        let private terminalFlowProgressPhaseBp evidence =
            if evidence.frontier.discovered <= 0L then 0L
            else min 10000L ((evidence.frontier.retired * 10000L) / evidence.frontier.discovered)

        let private terminalFlowProgressGateConditionFor evidence =
            let remaining = terminalFlowProgressRemaining evidence
            if remaining = 0L && evidence.frontier.queueDepth = 0L && evidence.frontier.blocked = 0L then
                TerminalFlowProgressGateVerdictReady
            elif evidence.frontier.queueDepth > 0L || evidence.frontier.blocked > 0L then
                TerminalFlowProgressGateQueueDrain(evidence.frontier.queueDepth, evidence.frontier.blocked, evidence.frontier.activeWorkers)
            else
                TerminalFlowProgressGatePhaseWork(evidence.frontier.phase, remaining)

        let private terminalFlowProgressGateConditionText = function
            | TerminalFlowProgressGateVerdictReady -> "verdict_ready"
            | TerminalFlowProgressGateQueueDrain(queueDepth, blocked, activeWorkers) ->
                FastRuntimeFormat.format "queue_drain:q=%d:blocked=%d:active=%d" [| box queueDepth; box blocked; box activeWorkers |]
            | TerminalFlowProgressGatePhaseWork(phase, remaining) ->
                sprintf "phase_work:phase=%s:remaining=%d" (terminalFlowProgressPhaseText phase) remaining

        let private terminalFlowWaitGraphEdges evidence =
            let phaseNode = TerminalFlowWaitProgressPhase evidence.frontier.phase
            let edge kind outstanding =
                if outstanding <= 0L then None
                else Some { fromNode = TerminalFlowWaitQueueKind kind; toNode = phaseNode; outstanding = outstanding }
            [ edge TerminalFlowQueueCrossKindReplayDriver evidence.frontier.queueKindCounts.crossKindReplayDriver
              edge TerminalFlowQueueParentContinuation evidence.frontier.queueKindCounts.parentContinuation
              edge TerminalFlowQueueDeclaredBodyVerification evidence.frontier.queueKindCounts.declaredBodyVerification
              edge TerminalFlowQueueUniverseConstraint evidence.frontier.queueKindCounts.universeConstraint
              edge TerminalFlowQueueDefEqObligation evidence.frontier.queueKindCounts.defEqObligation
              edge TerminalFlowQueueProceduralResidual evidence.frontier.queueKindCounts.proceduralResidual ]
            |> List.choose id

        let private terminalFlowWaitGraphNodeText = function
            | TerminalFlowWaitProgressPhase phase -> "phase:" + terminalFlowProgressPhaseText phase
            | TerminalFlowWaitQueueKind kind -> "queue:" + terminalFlowQueueItemKindText kind
            | TerminalFlowWaitVerdict -> "verdict"

        let private terminalFlowWaitGraphEdgeText edge =
            FastRuntimeFormat.format "%s->%s:%d" [| box (terminalFlowWaitGraphNodeText edge.fromNode); box (terminalFlowWaitGraphNodeText edge.toNode); box edge.outstanding |]

        let private terminalFlowTopologyGateCauseText = function
            | TerminalFlowTopologyGateCrossKindDrainReleased(beforeDepth, afterDepth) ->
                sprintf "cross_kind_drain_released:before=%d:after=%d" beforeDepth afterDepth
            | TerminalFlowTopologyGateRootDrainReleased(completionRef, planRef, progressSnapshotRef) ->
                FastRuntimeFormat.format "root_drain_released:completion=%u:plan=%u:progress_snapshot=%u" [| box completionRef; box planRef; box progressSnapshotRef |]
            | TerminalFlowTopologyGateQapRelationsConsumed(fixpointRef, relationCount) ->
                sprintf "qap_relations_consumed:fixpoint=%u:relations=%d" fixpointRef relationCount
            | TerminalFlowTopologyGateOwnerLedgerClosed ownerCloseRef ->
                sprintf "owner_ledger_closed:ref=%u" ownerCloseRef
            | TerminalFlowTopologyGateUniverseConstraintResolved universeReceiptRef ->
                sprintf "universe_constraint_resolved:ref=%u" universeReceiptRef
            | TerminalFlowTopologyGateDefEqWitnessPublished witnessRef ->
                sprintf "defeq_witness_published:ref=%u" witnessRef
            | TerminalFlowTopologyGateUnknownTypedCause causeRef ->
                sprintf "unknown_typed_cause:ref=%u" (terminalFlowIdentityRefDigest causeRef)

        let private terminalFlowReplayFairnessVerdictTag = function
            | TerminalFlowFairnessBalanced _ -> "balanced"
            | TerminalFlowFairnessStarved _ -> "starved"
            | TerminalFlowFairnessYieldRequired _ -> "yield_required"
            | TerminalFlowFairnessReleasedByTopologyGate _ -> "released_by_topology_gate"
            | TerminalFlowFairnessReleasedByQuiescence _ -> "released_by_quiescence"

        let private terminalFlowWatchdogPetitionReasonText = function
            | TerminalFlowWatchdogMaterialStasis -> "material_stasis"
            | TerminalFlowWatchdogSchedulerStarvation -> "scheduler_starvation"
            | TerminalFlowWatchdogHostShutdownImminent -> "host_shutdown_imminent"

        let private terminalFlowProgressRegressionText = function
            | TerminalFlowProgressSnapshotSequenceRegressed(previous, incoming) ->
                sprintf "snapshot_sequence_regressed:previous=%d:incoming=%d" previous incoming
            | TerminalFlowProgressDiscoveredRegressed(previous, incoming) ->
                sprintf "discovered_regressed:previous=%d:incoming=%d" previous incoming
            | TerminalFlowProgressRetiredRegressed(previous, incoming) ->
                sprintf "retired_regressed:previous=%d:incoming=%d" previous incoming
            | TerminalFlowProgressRetiredBeyondDiscovered(retired, discovered) ->
                sprintf "retired_beyond_discovered:retired=%d:discovered=%d" retired discovered
            | TerminalFlowWorkLedgerOwnerMismatch(previousActorRef, incomingActorRef) ->
                sprintf "work_ledger_owner_mismatch:previous_actor_ref=%u:incoming_actor_ref=%u" previousActorRef incomingActorRef
            | TerminalFlowWorkLedgerCostInvariantBroken(completed, remaining, total) ->
                FastRuntimeFormat.format "work_ledger_cost_invariant_broken:completed=%d:remaining=%d:total=%d" [| box completed; box remaining; box total |]
            | TerminalFlowWorkLedgerCompletedRegressed(previous, incoming) ->
                sprintf "work_ledger_completed_regressed:previous=%d:incoming=%d" previous incoming
            | TerminalFlowCicArenaOwnerMismatch(ledgerActorRef, arenaActorRef) ->
                sprintf "cic_arena_owner_mismatch:ledger_actor_ref=%u:arena_actor_ref=%u" ledgerActorRef arenaActorRef
            | TerminalFlowSemanticFrontierNondeterministic(previousRef, incomingRef, semanticEpoch) ->
                FastRuntimeFormat.format "semantic_frontier_nondeterministic:previous_ref=%u:incoming_ref=%u:epoch=%d" [| box previousRef; box incomingRef; box semanticEpoch |]

        type TerminalFlowCicKernelActivityId =
            | TerminalFlowCicKernelNotEntered
            | TerminalFlowCicKernelEnteredEmpty
            | TerminalFlowCicKernelObservedWithoutOwner
            | TerminalFlowCicKernelPopulated

        let private terminalFlowCicKernelActivityText = function
            | TerminalFlowCicKernelNotEntered -> "not_entered"
            | TerminalFlowCicKernelEnteredEmpty -> "entered_empty"
            | TerminalFlowCicKernelObservedWithoutOwner -> "observed_without_owner"
            | TerminalFlowCicKernelPopulated -> "populated"

        let private terminalFlowCicKernelActivityFor (counters:TerminalFlowCicArenaCounters) =
            let populated =
                CompilerKernelV2.Measured.value counters.termCount > 0L
                || CompilerKernelV2.Measured.value counters.levelCount > 0L
                || CompilerKernelV2.Measured.value counters.whnfCacheHits > 0L
                || CompilerKernelV2.Measured.value counters.whnfCacheMisses > 0L
                || CompilerKernelV2.Measured.value counters.defEqSolvedCount > 0L
                || CompilerKernelV2.Measured.value counters.defEqFailedCount > 0L
                || CompilerKernelV2.Measured.value counters.universeSolverIterations > 0L
                || CompilerKernelV2.Measured.value counters.obligationCount > 0L
            if populated then TerminalFlowCicKernelPopulated
            else
                match counters.owner with
                | TerminalFlowCicArenaUnowned when CompilerKernelV2.Measured.value counters.activeWorkers > 0L ->
                    TerminalFlowCicKernelObservedWithoutOwner
                | TerminalFlowCicArenaUnowned -> TerminalFlowCicKernelNotEntered
                | TerminalFlowCicArenaOwned _ -> TerminalFlowCicKernelEnteredEmpty

        // CIC ownership is conditional on actual kernel participation. A compile
        // with no kernel work has no arena owner to agree with the work-ledger
        // actor; represent that vacuity explicitly instead of forging actor 0.
        type TerminalFlowCicArenaOwnershipCompatibility =
            | TerminalFlowCicArenaVacantNoKernelWork
            | TerminalFlowCicArenaOwnedByLedgerActor
            | TerminalFlowCicArenaOwnershipMismatch of ledgerActorRef:uint32 * arenaActorRef:uint32

        let private terminalFlowCicArenaOwnershipCompatibilityFor ledgerActorRef (counters:TerminalFlowCicArenaCounters) =
            let arenaActorRef = terminalFlowCicArenaOwnerRaw counters.owner
            match terminalFlowCicKernelActivityFor counters, counters.owner with
            | TerminalFlowCicKernelNotEntered, TerminalFlowCicArenaUnowned ->
                TerminalFlowCicArenaVacantNoKernelWork
            | (TerminalFlowCicKernelEnteredEmpty | TerminalFlowCicKernelPopulated), TerminalFlowCicArenaOwned ownerRef
                when CompilerKernelV2.NonZeroRef.value ownerRef = ledgerActorRef ->
                TerminalFlowCicArenaOwnedByLedgerActor
            | _ ->
                TerminalFlowCicArenaOwnershipMismatch(ledgerActorRef, arenaActorRef)

        let private terminalFlowCicArenaOwnershipCompatibilityText = function
            | TerminalFlowCicArenaVacantNoKernelWork -> "vacant_no_kernel_work_owner_not_required"
            | TerminalFlowCicArenaOwnedByLedgerActor -> "owned_by_work_ledger_actor"
            | TerminalFlowCicArenaOwnershipMismatch(ledgerActorRef, arenaActorRef) ->
                FastRuntimeFormat.format "ownership_mismatch(ledger_actor_ref=%u|arena_actor_ref=%u)" [| box ledgerActorRef; box arenaActorRef |]

        type TerminalFlowTypedDiagnosticEvent =
            | TerminalFlowDiagnosticProgressAuthority of TerminalFlowProgressEvidence
            | TerminalFlowDiagnosticWorkLedger of TerminalFlowProgressEvidence
            | TerminalFlowDiagnosticProgressRejected of TerminalFlowProgressRegression
            | TerminalFlowDiagnosticTopologyGateOpened of TerminalFlowTopologyGateTransition
            | TerminalFlowDiagnosticWatchdogPetition of TerminalFlowWatchdogPetition
            | TerminalFlowDiagnosticWaitGraphProjection of TerminalFlowProgressEvidence
            | TerminalFlowDiagnosticCicKernelProfile of TerminalFlowProgressEvidence
            | TerminalFlowDiagnosticSchedulerFairnessProjection of TerminalFlowProgressEvidence
            | TerminalFlowDiagnosticVerdictImminent of TerminalFlowProgressEvidence

        let private terminalFlowTypedDiagnosticEventJson = function
            | TerminalFlowDiagnosticProgressAuthority evidence ->
                let queueTop =
                    evidence.frontier.attributedQueueTop
                    |> List.map (fun item ->
                        FastRuntimeFormat.format "%s:ref=%u:producer=%u:owner=%u" [| box (terminalFlowQueueItemKindText item.itemKind); box (terminalFlowIdentityRefDigest item.itemRef); box item.producerRef; box (item.ownerRef |> Option.defaultValue 0u) |])
                    |> String.concat ";"
                let remaining = terminalFlowProgressRemaining evidence
                let phaseProgressBp = terminalFlowProgressPhaseBp evidence
                let gateCondition = terminalFlowProgressGateConditionFor evidence |> terminalFlowProgressGateConditionText
                FastRuntimeFormat.format "{\"kind\":\"terminal_progress_authority_projection\",\"snapshot_ref\":%u,\"snapshot_sequence\":%d,\"phase_du\":%s,\"phase_progress_bp\":%d,\"discovered\":%d,\"retired\":%d,\"remaining\":%d,\"blocked\":%d,\"queue_depth\":%d,\"active_workers\":%d,\"queue_cross_kind\":%d,\"queue_parent_continuation\":%d,\"queue_declared_body_verification\":%d,\"queue_universe_constraint\":%d,\"queue_defeq_obligation\":%d,\"queue_procedural_residual\":%d,\"gate_condition_du\":%s,\"semantic_digest_ref\":%u,\"procedural_digest_ref\":%u,\"semantic_epoch\":%d,\"queue_attribution_complete\":%b,\"queue_top_k\":%s,\"display_is_projection_only\":true,\"scheduler_control_from_pct\":false,\"control_authority\":\"reducer_acceptance_required\",\"authority\":\"typed_progress_snapshot_projection\"}" [| box (terminalFlowIdentityRefDigest evidence.snapshotRef); box evidence.snapshotSequence; box (DiagJson.esc (terminalFlowProgressPhaseText evidence.frontier.phase)); box phaseProgressBp; box evidence.frontier.discovered; box evidence.frontier.retired; box remaining; box evidence.frontier.blocked; box evidence.frontier.queueDepth; box evidence.frontier.activeWorkers; box evidence.frontier.queueKindCounts.crossKindReplayDriver; box evidence.frontier.queueKindCounts.parentContinuation; box evidence.frontier.queueKindCounts.declaredBodyVerification; box evidence.frontier.queueKindCounts.universeConstraint; box evidence.frontier.queueKindCounts.defEqObligation; box evidence.frontier.queueKindCounts.proceduralResidual; box (DiagJson.esc gateCondition); box (terminalFlowIdentityRefDigest evidence.semanticDigest.digestRef); box (terminalFlowIdentityRefDigest evidence.proceduralDigestRef); box evidence.semanticDigest.semanticEpoch; box evidence.queueAttributionComplete; box (DiagJson.esc queueTop) |]
            | TerminalFlowDiagnosticWorkLedger evidence ->
                let retiredCost = evidence.workLedger.completedCost + evidence.workLedger.provenDeadCost
                let semanticCompletedCost =
                    max retiredCost (max 0L (DiagJson.terminalCompletionCreditCostNow()))
                let semanticToAstRatioMilli =
                    if evidence.workLedger.completedCost <= 0L then 0L
                    elif semanticCompletedCost > Int64.MaxValue / 1000L then Int64.MaxValue
                    else (semanticCompletedCost * 1000L) / evidence.workLedger.completedCost
                let blockedUnitsText =
                    evidence.workLedger.blockedUnits
                    |> List.map (fun item ->
