        let private terminalFlowEmitTypedDiagnostic event =
            event |> terminalFlowTypedDiagnosticEventJson |> DiagJson.emitTerminalJsonDurable

        type private TerminalFlowProjectionEmissionGateState = {
            signature : string
            occurrence : int64
            lastEmittedAtMs : int64
        }

        let mutable private terminalFlowProjectionEmissionGateState = {
            signature = ""
            occurrence = 0L
            lastEmittedAtMs = 0L
        }

        let mutable private terminalFlowVerdictImminentEmissionGateState = {
            signature = ""
            occurrence = 0L
            lastEmittedAtMs = 0L
        }

        let private terminalFlowLiveWorkLedgerEmissionGate = obj()
        let mutable private terminalFlowLiveWorkLedgerEmissionGateState = {
            signature = ""
            occurrence = 0L
            lastEmittedAtMs = 0L
        }

        type TerminalFlowLiveProgressEvidenceSource =
            | TerminalFlowLiveProgressAcceptedForControl
            | TerminalFlowLiveProgressOperationalAuthority
            | TerminalFlowLiveProgressObservedProjectionOnly

        let private terminalFlowLiveProgressEvidenceSourceText = function
            | TerminalFlowLiveProgressAcceptedForControl -> "AcceptedForControl"
            | TerminalFlowLiveProgressOperationalAuthority -> "OperationalAuthority"
            | TerminalFlowLiveProgressObservedProjectionOnly -> "ObservedProjectionOnly"

        type TerminalFlowProgressProjectionObserverAuthority =
            | TerminalFlowProgressProjectionObserverUnavailable
            | TerminalFlowProgressProjectionObserverInstalled of observe:(TerminalFlowProgressEvidence -> unit)

        let private terminalFlowProgressProjectionObserverGate = obj()
        let mutable private terminalFlowProgressProjectionObserverAuthority =
            TerminalFlowProgressProjectionObserverUnavailable

        let private terminalFlowInstallProgressProjectionObserver observe =
            lock terminalFlowProgressProjectionObserverGate (fun () ->
                terminalFlowProgressProjectionObserverAuthority <-
                    TerminalFlowProgressProjectionObserverInstalled observe)

        let private terminalFlowObserveProgressProjection evidence =
            let observer =
                lock terminalFlowProgressProjectionObserverGate (fun () ->
                    terminalFlowProgressProjectionObserverAuthority)
            match observer with
            | TerminalFlowProgressProjectionObserverInstalled observe -> observe evidence
            | TerminalFlowProgressProjectionObserverUnavailable -> ()

        let private terminalFlowProjectionOccurrenceIsPowerOfTwo value =
            value > 0L && (value &&& (value - 1L)) = 0L

        let private terminalFlowProgressProjectionSemanticSignature evidence =
            FastRuntimeFormat.format "%s|discovered=%d|completed=%d|remaining=%d|blocked=%d|q=%d|a=%d|scheduler_admitted=%d|scheduler_receipts=%d|scheduler_open=%d|scheduler_unrepresented=%d|kinds=%s|gate=%s|actor=%u" [| box (terminalFlowProgressPhaseText evidence.frontier.phase); box evidence.workLedger.discoveredCost; box evidence.workLedger.completedCost; box (terminalFlowProgressRemaining evidence); box evidence.frontier.blocked; box evidence.frontier.queueDepth; box evidence.frontier.activeWorkers; box evidence.workLedger.schedulerAdmittedCount; box evidence.workLedger.schedulerReceiptCount; box evidence.workLedger.schedulerOpenCount; box evidence.workLedger.schedulerOpenNotRepresented; box (terminalFlowQueueKindCountsText evidence.frontier.queueKindCounts); box (terminalFlowProgressGateConditionFor evidence |> terminalFlowProgressGateConditionText); box evidence.workLedger.ownerActorRef |]

        let private terminalFlowProgressEvidenceWithLiveSchedulerOverlay (evidence:TerminalFlowProgressEvidence) =
            let nowMs = Environment.TickCount64
            let schedulerState = SemanticWorkLedgerProjection.readOperational ()
            let schedulerAdmittedCount, _, schedulerOpenCount =
                SemanticWorkLedgerProjection.countsOf schedulerState
            let _, dependencyCount = JpActiveWorkIdentityAuthority.readCounts ()
            let laneSnapshot = terminalFlowJpLaneSnapshotBridge ()
            let activeCount = max 0L (laneSnapshot.semanticActive + laneSnapshot.declaredBodyActive)
            let completedCost =
                max evidence.frontier.retired (max 0L (DiagJson.terminalCompletionCreditCostNow()))
            let discoveredCost =
                max evidence.frontier.discovered (max completedCost schedulerAdmittedCount)
            let liveQueueDepth = max 0L (schedulerOpenCount - activeCount)
            let liveBlockedCost = min (max 0L schedulerOpenCount) dependencyCount
            let declaredBodyQueue = min liveQueueDepth (max 0L laneSnapshot.declaredBodyQueueDepth)
            let semanticQueueBudget = max 0L (liveQueueDepth - declaredBodyQueue)
            let semanticQueueObserved = min semanticQueueBudget (max 0L laneSnapshot.semanticQueueDepth)
            let takeQueueKind remaining observed = min (max 0L remaining) (max 0L observed)
            let crossKindReplayDriver = takeQueueKind semanticQueueObserved evidence.frontier.queueKindCounts.crossKindReplayDriver
            let afterCrossKind = semanticQueueObserved - crossKindReplayDriver
            let parentContinuation = takeQueueKind afterCrossKind evidence.frontier.queueKindCounts.parentContinuation
            let afterParent = afterCrossKind - parentContinuation
            let universeConstraint = takeQueueKind afterParent evidence.frontier.queueKindCounts.universeConstraint
            let afterUniverse = afterParent - universeConstraint
            let defEqObligation = takeQueueKind afterUniverse evidence.frontier.queueKindCounts.defEqObligation
            let proceduralResidual = max 0L (afterUniverse - defEqObligation)
            let liveQueueKindCounts : TerminalFlowQueueKindCounts =
                { crossKindReplayDriver = crossKindReplayDriver
                  parentContinuation = parentContinuation
                  declaredBodyVerification = declaredBodyQueue
                  universeConstraint = universeConstraint
                  defEqObligation = defEqObligation
                  proceduralResidual = proceduralResidual }
            let liveQueueAttributionComplete =
                terminalFlowQueueKindCountsTotal liveQueueKindCounts = liveQueueDepth
                && semanticQueueObserved + declaredBodyQueue = liveQueueDepth
            let liveFrontier =
                { evidence.frontier with
                    discovered = discoveredCost
                    retired = min discoveredCost completedCost
                    blocked = liveBlockedCost
                    queueDepth = liveQueueDepth
                    activeWorkers = activeCount
                    queueKindCounts = liveQueueKindCounts
                    attributedQueueTop = [] }
            let workLedger =
                terminalFlowWorkLedgerFor evidence.snapshotRef nowMs liveFrontier evidence.semanticDigest
            { evidence with
                snapshotSequence = max evidence.snapshotSequence nowMs
                frontier = liveFrontier
                workLedger = workLedger
                queueAttributionComplete = liveQueueAttributionComplete
                observedAtMs = nowMs }

        let private terminalFlowLiveWorkLedgerSemanticSignature source (evidence:TerminalFlowProgressEvidence) =
            FastRuntimeFormat.format "%s|%s|completed=%d|remaining=%d|scheduler_admitted=%d|scheduler_receipts=%d|scheduler_open=%d|scheduler_unrepresented=%d|attempts=%d|graph_open=%d|graph_suspended=%d|blocked=%d|blocker_authority=%s|blocker_identity=%s" [| box (terminalFlowLiveProgressEvidenceSourceText source); box (terminalFlowWorkLedgerStateText evidence.workLedger.state); box evidence.workLedger.completedCost; box evidence.workLedger.remainingCost; box evidence.workLedger.schedulerAdmittedCount; box evidence.workLedger.schedulerReceiptCount; box evidence.workLedger.schedulerOpenCount; box evidence.workLedger.schedulerOpenNotRepresented; box evidence.workLedger.executionAttemptCount; box evidence.workLedger.operationalGraphOpenCount; box evidence.workLedger.operationalGraphSuspendedCount; box evidence.workLedger.blockedCost; box (terminalFlowBlockedAttributionAuthorityClassText evidence.workLedger.blockedAttributionAuthority); box (terminalFlowBlockedWorkIdentityAuthorityText evidence.workLedger.blockedWorkIdentityAuthority) |]

        let private terminalFlowProjectionEmissionGate nowMs signature state =
            let changed = signature <> state.signature
            let occurrence = if changed then 1L else state.occurrence + 1L
            let heartbeat = nowMs - state.lastEmittedAtMs >= 15000L
            let emitNow = changed || occurrence <= 3L || terminalFlowProjectionOccurrenceIsPowerOfTwo occurrence || heartbeat
            let next = {
                signature = signature
                occurrence = occurrence
                lastEmittedAtMs = if emitNow then nowMs else state.lastEmittedAtMs
            }
            emitNow, changed, heartbeat, occurrence, next

        let private terminalFlowEmitLiveWorkLedgerHeartbeat
            (source:TerminalFlowLiveProgressEvidenceSource)
            (evidence:TerminalFlowProgressEvidence) =
            let sourceText = terminalFlowLiveProgressEvidenceSourceText source
            let liveEvidence = terminalFlowProgressEvidenceWithLiveSchedulerOverlay evidence
            // The live scheduler can become exactly closed without producing another
            // progress projection. Feed that transition back through the installed
            // observer so terminal promotion is not stranded behind a stale active count.
            terminalFlowObserveProgressProjection liveEvidence
            if DiagJson.quiet then () else
            let nowMs = Environment.TickCount64
            let signature = terminalFlowLiveWorkLedgerSemanticSignature source liveEvidence
            let emitNow, changed, heartbeat, occurrence =
                lock terminalFlowLiveWorkLedgerEmissionGate (fun () ->
                    let emitNow, changed, heartbeat, occurrence, next =
                        terminalFlowProjectionEmissionGate nowMs signature terminalFlowLiveWorkLedgerEmissionGateState
                    terminalFlowLiveWorkLedgerEmissionGateState <- next
                    emitNow, changed, heartbeat, occurrence)
            if emitNow then
                terminalFlowEmitTypedDiagnostic (TerminalFlowDiagnosticWorkLedger liveEvidence)
                match liveEvidence.workLedger.state with
                | TerminalFlowWorkLedgerClosed -> ()
                | openState ->
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_terminal_flow_boundary_blocked\",\"event\":\"live_work_ledger_heartbeat\",\"reason_class_du\":%s,\"source_du\":\"live_work_ledger_heartbeat\",\"evidence_source_du\":%s,\"why_not_terminal_commit_du\":%s,\"blocked_attribution_authority_du\":%s,\"blocked_attribution_age_ms\":%d,\"blocked_work_identity_authority_du\":%s,\"blocked_unit_work_unit_id\":%s,\"blocked_unit_method_key\":%s,\"blocked_unit_source\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"execution_attempt_count\":%d,\"operational_graph_open_count\":%d,\"operational_graph_suspended_count\":%d,\"blocked_cost\":%d,\"updated_at_ms\":%d,\"occurrence_count\":%d,\"state_changed\":%b,\"heartbeat\":%b,\"sparse_policy\":\"state_change_first3_power2_15s_heartbeat\",\"authority\":\"latest_typed_progress_observation_plus_live_scheduler_overlay_projection_only\",\"next\":\"retain_diagnosis_until_indexed_closure_proof\"}" [| box (DiagJson.esc (terminalFlowWorkLedgerStateText openState)); box (DiagJson.esc sourceText); box (DiagJson.esc (terminalFlowEtaAuthorityText liveEvidence.workLedger.etaAuthority)); box (DiagJson.esc (terminalFlowBlockedAttributionAuthorityClassText liveEvidence.workLedger.blockedAttributionAuthority)); box (terminalFlowBlockedAttributionAuthorityAgeMs liveEvidence.workLedger.blockedAttributionAuthority); box (DiagJson.esc (terminalFlowBlockedWorkIdentityAuthorityText liveEvidence.workLedger.blockedWorkIdentityAuthority)); box (DiagJson.esc liveEvidence.workLedger.blockedWorkUnitId); box (DiagJson.esc liveEvidence.workLedger.blockedMethodKey); box (DiagJson.esc liveEvidence.workLedger.blockedSource); box liveEvidence.workLedger.schedulerOpenCount; box liveEvidence.frontier.queueDepth; box liveEvidence.workLedger.activeCost; box liveEvidence.workLedger.executionAttemptCount; box liveEvidence.workLedger.operationalGraphOpenCount; box liveEvidence.workLedger.operationalGraphSuspendedCount; box liveEvidence.workLedger.blockedCost; box liveEvidence.workLedger.updatedAtMs; box occurrence; box changed; box heartbeat |])
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_live_work_ledger_heartbeat\",\"evidence_source_du\":%s,\"occurrence_count\":%d,\"state_changed\":%b,\"heartbeat\":%b,\"completed_cost\":%d,\"remaining_cost\":%d,\"scheduler_open_count\":%d,\"execution_attempt_count\":%d,\"operational_graph_open_count\":%d,\"operational_graph_suspended_count\":%d,\"sparse_policy\":\"state_change_first3_power2_15s_heartbeat\",\"authority\":\"live_scheduler_overlay_projection_only\"}" [| box (DiagJson.esc sourceText); box occurrence; box changed; box heartbeat; box liveEvidence.workLedger.completedCost; box liveEvidence.workLedger.remainingCost; box liveEvidence.workLedger.schedulerOpenCount; box liveEvidence.workLedger.executionAttemptCount; box liveEvidence.workLedger.operationalGraphOpenCount; box liveEvidence.workLedger.operationalGraphSuspendedCount |])

        let private terminalFlowEmitProgressProjectionSuite evidence =
            terminalFlowObserveProgressProjection evidence
            if DiagJson.quiet then () else
            let nowMs = Environment.TickCount64
            let signature = terminalFlowProgressProjectionSemanticSignature evidence
            let emitNow, changed, heartbeat, occurrence, next =
                terminalFlowProjectionEmissionGate nowMs signature terminalFlowProjectionEmissionGateState
            terminalFlowProjectionEmissionGateState <- next
            if emitNow then
                terminalFlowEmitTypedDiagnostic (TerminalFlowDiagnosticProgressAuthority evidence)
                terminalFlowEmitTypedDiagnostic (TerminalFlowDiagnosticWorkLedger evidence)
                terminalFlowEmitTypedDiagnostic (TerminalFlowDiagnosticWaitGraphProjection evidence)
                let kernelQueueCount =
                    evidence.frontier.queueKindCounts.universeConstraint
                    + evidence.frontier.queueKindCounts.defEqObligation
                let kernelHasSignal =
                    evidence.frontier.phase = TerminalFlowProgressProofKernel
                    || kernelQueueCount > 0L
                    || CompilerKernelV2.Measured.value evidence.cicKernel.activeWorkers > 0L
                    || CompilerKernelV2.Measured.value evidence.cicKernel.termCount > 0L
                    || CompilerKernelV2.Measured.value evidence.cicKernel.defEqSolvedCount > 0L
                    || CompilerKernelV2.Measured.value evidence.cicKernel.defEqFailedCount > 0L
                // Keep the CIC profile observable even before an owner actor exists.
                // "observed_without_owner" is itself the evidence needed to wire the arena.
                terminalFlowEmitTypedDiagnostic (TerminalFlowDiagnosticCicKernelProfile evidence)
                terminalFlowEmitTypedDiagnostic (TerminalFlowDiagnosticSchedulerFairnessProjection evidence)
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_projection_suite_emitted\",\"occurrence_count\":%d,\"state_changed\":%b,\"heartbeat\":%b,\"kernel_profile_emitted\":true,\"kernel_activity_observed\":%b,\"sparse_policy\":\"state_change_first3_power2_15s_heartbeat\",\"authority\":\"projection_only_no_control\"}" [| box occurrence; box changed; box heartbeat; box kernelHasSignal |])

        let private terminalFlowEmitVerdictImminentSparse evidence =
            let nowMs = Environment.TickCount64
            let signature = terminalFlowProgressProjectionSemanticSignature evidence
            let emitNow, changed, heartbeat, occurrence, next =
                terminalFlowProjectionEmissionGate nowMs signature terminalFlowVerdictImminentEmissionGateState
            terminalFlowVerdictImminentEmissionGateState <- next
            if emitNow then
                terminalFlowEmitTypedDiagnostic (TerminalFlowDiagnosticVerdictImminent evidence)
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_verdict_imminent_occurrence\",\"occurrence_count\":%d,\"state_changed\":%b,\"heartbeat\":%b,\"sparse_policy\":\"state_change_first3_power2_15s_heartbeat\",\"hud_banner_persistent\":true,\"authority\":\"projection_only_no_control\"}" [| box occurrence; box changed; box heartbeat |])

        let private terminalFlowProgressAuthorityInitial = {
            accepted = None
            rejected = None
        }

        let private terminalFlowReducerProgressAdvance
            (authority:TerminalFlowReducerProgressAuthority)
            (incoming:TerminalFlowProgressEvidence) =
            let reject reason = { authority with rejected = Some reason }
            let ledgerInvariantBroken ledger = ledger.completedCost + ledger.provenDeadCost + ledger.remainingCost <> ledger.totalCost
            let cicOwnerMismatch =
                match terminalFlowCicArenaOwnershipCompatibilityFor incoming.workLedger.ownerActorRef incoming.cicKernel with
                | TerminalFlowCicArenaOwnershipMismatch(ledgerActorRef, arenaActorRef) ->
                    Some (TerminalFlowCicArenaOwnerMismatch(ledgerActorRef, arenaActorRef))
                | TerminalFlowCicArenaVacantNoKernelWork
                | TerminalFlowCicArenaOwnedByLedgerActor -> None
            if Option.isSome cicOwnerMismatch then
                reject (Option.get cicOwnerMismatch)
            elif ledgerInvariantBroken incoming.workLedger then
                reject (TerminalFlowWorkLedgerCostInvariantBroken(incoming.workLedger.completedCost, incoming.workLedger.remainingCost, incoming.workLedger.totalCost))
            else
                match authority.accepted with
                | None when incoming.frontier.retired <= incoming.frontier.discovered ->
                    { accepted = Some incoming; rejected = None }
                | None ->
                    reject (TerminalFlowProgressRetiredBeyondDiscovered(incoming.frontier.retired, incoming.frontier.discovered))
                | Some previous
                    when incoming.snapshotSequence = previous.snapshotSequence
                         && terminalFlowIdentityRefDigest incoming.snapshotRef = terminalFlowIdentityRefDigest previous.snapshotRef ->
                    { accepted = Some previous; rejected = None }
                | Some previous when incoming.snapshotSequence < previous.snapshotSequence ->
                    { accepted = Some previous; rejected = None }
                | Some previous when previous.workLedger.ownerActorRef <> 0u && previous.workLedger.ownerActorRef <> incoming.workLedger.ownerActorRef ->
                    reject (TerminalFlowWorkLedgerOwnerMismatch(previous.workLedger.ownerActorRef, incoming.workLedger.ownerActorRef))
                | Some previous when incoming.workLedger.completedCost < previous.workLedger.completedCost ->
                    reject (TerminalFlowWorkLedgerCompletedRegressed(previous.workLedger.completedCost, incoming.workLedger.completedCost))
                | Some previous
                    when incoming.semanticDigest.semanticEpoch = previous.semanticDigest.semanticEpoch
                         && incoming.semanticDigest.inputCorpusRef = previous.semanticDigest.inputCorpusRef
                         && terminalFlowIdentityRefDigest incoming.semanticDigest.digestRef <> terminalFlowIdentityRefDigest previous.semanticDigest.digestRef ->
                    reject (
                        TerminalFlowSemanticFrontierNondeterministic(
                            terminalFlowIdentityRefDigest previous.semanticDigest.digestRef,
                            terminalFlowIdentityRefDigest incoming.semanticDigest.digestRef,
                            incoming.semanticDigest.semanticEpoch))
                | Some previous ->
                    let mergedFrontier =
                        { incoming.frontier with
                            discovered = max previous.frontier.discovered incoming.frontier.discovered
                            retired = max previous.frontier.retired incoming.frontier.retired }
                    let elapsedMs = max 1L (incoming.observedAtMs - previous.observedAtMs)
                    let materialDelta = max 0L (incoming.workLedger.completedCost - previous.workLedger.completedCost)
                    let zeroDeltaStreak = if materialDelta > 0L then 0L else previous.workLedger.zeroDeltaStreak + 1L
                    let milliRate = if materialDelta <= 0L then previous.workLedger.milliCostPerSecond else (materialDelta * 1000000L) / elapsedMs
                    let rawRemaining = max 0L (mergedFrontier.discovered - mergedFrontier.retired - previous.workLedger.provenDeadCost)
                    let residualCanBeProvenDead =
                        rawRemaining > 0L
                        && zeroDeltaStreak >= 64L
                        && incoming.workLedger.activeCost = 0L
                        && incoming.workLedger.readyCost = 0L
                        && incoming.workLedger.blockedCost + incoming.workLedger.residualCost >= rawRemaining
                    let newlyProvenDead = if residualCanBeProvenDead then rawRemaining else 0L
                    let provenDeadCost = previous.workLedger.provenDeadCost + newlyProvenDead
                    let remaining = max 0L (rawRemaining - newlyProvenDead)
                    let noLiveSchedulerWork =
                        incoming.workLedger.schedulerOpenCount = 0L
                        && incoming.workLedger.activeCost = 0L
                        && incoming.workLedger.readyCost = 0L
                    let etaAuthority =
                        if remaining = 0L && noLiveSchedulerWork then TerminalFlowEtaComplete
                        elif remaining = 0L && incoming.workLedger.activeCost > 0L then
                            TerminalFlowEtaCredentialBlocked(TerminalFlowWorkLedgerBlockerActiveWorker, terminalFlowIdentityRefDigest incoming.workLedger.ledgerRef, zeroDeltaStreak * elapsedMs)
                        elif remaining = 0L && incoming.workLedger.schedulerOpenCount > 0L then
                            TerminalFlowEtaCredentialBlocked(TerminalFlowWorkLedgerBlockerQueue, terminalFlowIdentityRefDigest incoming.workLedger.ledgerRef, zeroDeltaStreak * elapsedMs)
                        elif milliRate > 0L then TerminalFlowEtaMaterialRate(remaining, milliRate, max 0L ((remaining * 1000L) / milliRate))
                        elif CompilerKernelV2.Measured.value incoming.cicKernel.obligationCount > 0L then
                            TerminalFlowEtaCredentialBlocked(TerminalFlowWorkLedgerBlockerCicKernel, terminalFlowIdentityRefDigest incoming.cicKernel.arenaRef, zeroDeltaStreak * elapsedMs)
                        elif incoming.workLedger.residualCost > 0L then
                            TerminalFlowEtaCredentialBlocked(TerminalFlowWorkLedgerBlockerResidual, terminalFlowIdentityRefDigest incoming.workLedger.ledgerRef, zeroDeltaStreak * elapsedMs)
                        elif incoming.workLedger.blockedCost > 0L then
                            TerminalFlowEtaCredentialBlocked(TerminalFlowWorkLedgerBlockerQueue, terminalFlowIdentityRefDigest incoming.workLedger.ledgerRef, zeroDeltaStreak * elapsedMs)
                        else TerminalFlowEtaNoMaterialAuthority zeroDeltaStreak
                    let ledgerState =
                        if newlyProvenDead > 0L then TerminalFlowWorkLedgerProvenDead
                        elif remaining = 0L && noLiveSchedulerWork then TerminalFlowWorkLedgerClosed
                        elif incoming.workLedger.residualCost > 0L then TerminalFlowWorkLedgerResidual
                        elif incoming.workLedger.blockedCost > 0L then TerminalFlowWorkLedgerBlocked
                        elif incoming.workLedger.activeCost > 0L
                             || incoming.workLedger.readyCost > 0L
                             || incoming.workLedger.schedulerOpenCount > 0L then TerminalFlowWorkLedgerMaterial
                        else incoming.workLedger.state
                    let workLedger =
                        { incoming.workLedger with
                            state = ledgerState
                            discoveredCost = mergedFrontier.discovered
                            completedCost = mergedFrontier.retired
                            provenDeadCost = provenDeadCost
                            remainingCost = remaining
                            totalCost = mergedFrontier.discovered
                            materialDeltaCost = materialDelta
                            zeroDeltaStreak = zeroDeltaStreak
                            milliCostPerSecond = milliRate
                            etaAuthority = etaAuthority }
                    if mergedFrontier.retired > mergedFrontier.discovered then
                        reject (TerminalFlowProgressRetiredBeyondDiscovered(mergedFrontier.retired, mergedFrontier.discovered))
                    else
                        { accepted = Some { incoming with frontier = mergedFrontier; workLedger = workLedger }; rejected = None }

        // Breakthrough migration MIGRATION: keep minted refs above every CIC/stage
        // producer. The previous placement after the CIC actor made F# treat the
        // ref table as unavailable to proof-kernel constructors, causing the
        // destructive modelling bridge to fail before the Hopac authority seal.
        [<StructuralEquality; NoComparison>]
        type private TerminalFlowRefMintIdentity = {
            kindRef : CompilerIdentityKernel.ContentDigest
            payloadRef : CompilerIdentityKernel.ContentDigest
        }

        let private terminalFlowRefMintGate = obj()
        let private terminalFlowRefMintByPayload = System.Collections.Generic.Dictionary<TerminalFlowRefMintIdentity, uint32>()
        let private terminalFlowRefMintLogCountByKind = System.Collections.Generic.Dictionary<CompilerIdentityKernel.ContentDigest, int64>()
        let mutable private terminalFlowRefMintSequence = 0L
        let mutable private terminalFlowRefMintGlobalLogCount = 0L

        let private terminalFlowMintedRefOf kind payload =
            let kindRef = CompilerIdentityKernel.ContentDigest.ofText "terminal-flow-ref-kind" kind
            let identityKey : TerminalFlowRefMintIdentity =
                { kindRef = kindRef
                  payloadRef = CompilerIdentityKernel.ContentDigest.ofText "terminal-flow-ref-payload" payload }
            lock terminalFlowRefMintGate (fun () ->
                match terminalFlowRefMintByPayload.TryGetValue identityKey with
                | true, existing -> existing
                | false, _ ->
                    terminalFlowRefMintSequence <- terminalFlowRefMintSequence + 1L
                    let mintSeq = terminalFlowRefMintSequence
                    let refValue =
                        CompilerKernelV2.NonZeroRef.derive
                            ("terminal-flow-minted-ref:" + kind)
                            [payload]
                        |> CompilerKernelV2.NonZeroRef.value
                    let mintId = "terminal-ref:" + string refValue
                    terminalFlowRefMintByPayload.[identityKey] <- refValue
                    let kindOccurrence =
                        match terminalFlowRefMintLogCountByKind.TryGetValue kindRef with
                        | true, count -> count + 1L
                        | false, _ -> 1L
                    terminalFlowRefMintLogCountByKind.[kindRef] <- kindOccurrence
                    terminalFlowRefMintGlobalLogCount <- terminalFlowRefMintGlobalLogCount + 1L
                    let globalOccurrence = terminalFlowRefMintGlobalLogCount
                    let globalPowerOfTwo = globalOccurrence > 0L && (globalOccurrence &&& (globalOccurrence - 1L)) = 0L
                    let kindCheckpoint = kindOccurrence % 256L = 0L
                    let emitMint = globalOccurrence <= 12L || globalPowerOfTwo || globalOccurrence % 1024L = 0L || kindCheckpoint
                    if emitMint then
                        DiagJson.emitOutsideHopac (
                            FastRuntimeFormat.format "{\"kind\":\"ref_minted\",\"ref\":%u,\"ref_kind\":%s,\"payload\":%s,\"mint_id\":%s,\"mint_seq\":%d,\"kind_occurrence_count\":%d,\"global_occurrence_count\":%d,\"sparse_policy\":\"global_first12_power2_every1024_or_kind_every256\",\"authority\":\"terminal_flow_ref_table_actor_owned\",\"ref_source\":\"sha256_content_addressed_collision_checked\",\"hash_derived\":false,\"dereferenceable\":true,\"durability\":\"ordinary_telemetry_not_terminal_receipt\"}" [| box refValue; box (DiagJson.esc kind); box (DiagJson.esc payload); box (DiagJson.esc mintId); box mintSeq; box kindOccurrence; box globalOccurrence |])
                    refValue)

        let private terminalFlowRootReceiptRef (rootReceiptRef:TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>) =
            terminalFlowIdentityRefDigest rootReceiptRef

        let private terminalFlowRootReceiptRefText rootReceiptId =
            let typedRef : TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind> = terminalFlowIdentityRefOfText rootReceiptId
            terminalFlowIdentityRefDigest typedRef

        type TerminalFlowAdvancedConsoleLane =
            | TerminalFlowConsoleLaneRefMint
            | TerminalFlowConsoleLaneCicProof
            | TerminalFlowConsoleLaneGreenPath
            | TerminalFlowConsoleLaneQapWatch
            | TerminalFlowConsoleLaneProgressAuthority
            | TerminalFlowConsoleLaneTopologyGate
            | TerminalFlowConsoleLaneWatchdogPetition
            | TerminalFlowConsoleLaneExitSeal
            | TerminalFlowConsoleLaneQueueRecovery
            | TerminalFlowConsoleLaneReplayFairness
            | TerminalFlowConsoleLaneReducerRecovery
            | TerminalFlowConsoleLaneBreakthroughConvergence
            | TerminalFlowConsoleLaneOutcomeMaturity
            | TerminalFlowConsoleLaneCredentialGraph
            | TerminalFlowConsoleLaneTerminalPossession
            | TerminalFlowConsoleLaneArtifactCovenant
            | TerminalFlowConsoleLaneSchedulerChannel
            | TerminalFlowConsoleLaneResidualStall
            | TerminalFlowConsoleLaneReplayFanout
            | TerminalFlowConsoleLaneTotalOrder

        type TerminalFlowQapPublicationPhase =
            | TerminalFlowQapPublicationBeforeDrain
            | TerminalFlowQapPublicationDrainRequested
            | TerminalFlowQapPublicationDrainStranded

        let private terminalFlowQapPublicationPhaseNow () =
            let requestCount = DiagJson.terminalSemanticDrainRequestCountNow()
            let requestAgeMs = DiagJson.terminalSemanticDrainRequestAgeMsNow()
            if requestCount <= 0L then TerminalFlowQapPublicationBeforeDrain
            elif requestAgeMs >= terminalFlowSemanticDrainStrandedAfterMs then TerminalFlowQapPublicationDrainStranded
            else TerminalFlowQapPublicationDrainRequested

        let private terminalFlowQapPublicationPhaseText = function
            | TerminalFlowQapPublicationBeforeDrain -> "BeforeDrain"
            | TerminalFlowQapPublicationDrainRequested -> "DrainRequested"
            | TerminalFlowQapPublicationDrainStranded -> "DrainStranded"

        type TerminalFlowQapMaturityPublicationIdentity = private {
            fixpointRef : uint32
            generation : uint64
            semanticEpoch : int64
            phase : TerminalFlowQapPublicationPhase
        }

        let private terminalFlowQapMaturityPublicationIdentityFor fixpointRefValue generation semanticEpoch =
            { fixpointRef = fixpointRefValue
              generation = generation
              semanticEpoch = semanticEpoch
              phase = terminalFlowQapPublicationPhaseNow() }

        let private terminalFlowQapMaturityPublicationIdentityText (identity:TerminalFlowQapMaturityPublicationIdentity) =
            FastRuntimeFormat.format "%u|generation=%d|semantic=%d|drain_phase=%s" [| box identity.fixpointRef; box identity.generation; box identity.semanticEpoch; box (terminalFlowQapPublicationPhaseText identity.phase) |]

        let private terminalFlowQapMaturityPublicationKey fixpointRefValue generation semanticEpoch =
            terminalFlowQapMaturityPublicationIdentityFor fixpointRefValue generation semanticEpoch

        let private terminalFlowQapMaturityPublicationGenerationFixture () =
            let parentKey = terminalFlowQapMaturityPublicationKey 17u 41UL 9L
            let childKey = terminalFlowQapMaturityPublicationKey 17u 42UL 9L
            let duplicateChildKey = terminalFlowQapMaturityPublicationKey 17u 42UL 9L
            if parentKey = childKey then
                failwith "QAP publication identity must distinguish parent and child generations."
            if childKey <> duplicateChildKey then
                failwith "QAP publication identity must remain exact-once within one generation."

        // QAP identity conformance runs explicitly after main; module initialization stays inert.

        type TerminalFlowConsoleObservedState = struct end

        type TerminalFlowConsoleCausalGraph<'State> =
            | TerminalFlowConsoleProjectionLeaf of lane:TerminalFlowAdvancedConsoleLane * title:string
            | TerminalFlowConsoleRootLeaf of receiptRef:uint32
            | TerminalFlowConsoleActorLeaf of phase:DiagJson.TerminalSchedulerPushActorPhase * ageMs:int64
            | TerminalFlowConsoleDrainLeaf of phase:TerminalFlowQapPublicationPhase * requestAgeMs:int64
            | TerminalFlowConsoleCause of cause:TerminalFlowConsoleCausalGraph<'State> * effect:TerminalFlowConsoleCausalGraph<'State>

        type TerminalFlowConsoleRecommendedAction =
            | TerminalFlowConsoleAwaitEvaluatorRoot
            | TerminalFlowConsoleAwaitOwnerClosure
            | TerminalFlowConsoleArmPendingTerminal
            | TerminalFlowConsoleReobserveQapAtStrandedBoundary
            | TerminalFlowConsoleContinueReducer

        type TerminalFlowConsoleDetailFieldId =
            | TerminalFlowConsoleDetailBare of text:string
            | TerminalFlowConsoleDetailPhase of value:string
            | TerminalFlowConsoleDetailGate of value:string
            | TerminalFlowConsoleDetailSemanticDigest of value:string
            | TerminalFlowConsoleDetailProceduralDigest of value:string
            | TerminalFlowConsoleDetailLane of value:string
            | TerminalFlowConsoleDetailReason of value:string
            | TerminalFlowConsoleDetailOwnedState of value:string
            | TerminalFlowConsoleDetailOtherKeyed of key:string * value:string

        let private terminalFlowConsoleDetailFieldId (field:string) =
            match field.Split([|'='|], 2, StringSplitOptions.None) with
            | [|key; value|] ->
                match key with
                | "phase" -> TerminalFlowConsoleDetailPhase value
                | "gate" -> TerminalFlowConsoleDetailGate value
                | "semantic_digest" -> TerminalFlowConsoleDetailSemanticDigest value
                | "procedural_digest" -> TerminalFlowConsoleDetailProceduralDigest value
                | "lane" -> TerminalFlowConsoleDetailLane value
                | "reason" -> TerminalFlowConsoleDetailReason value
                | "owned_state" -> TerminalFlowConsoleDetailOwnedState value
                | _ -> TerminalFlowConsoleDetailOtherKeyed(key, value)
            | _ -> TerminalFlowConsoleDetailBare field

        let private terminalFlowConsoleDetailFieldText = function
            | TerminalFlowConsoleDetailBare text -> text
            | TerminalFlowConsoleDetailPhase value -> "phase=" + value
            | TerminalFlowConsoleDetailGate value -> "gate=" + value
            | TerminalFlowConsoleDetailSemanticDigest value -> "semantic_digest=" + value
            | TerminalFlowConsoleDetailProceduralDigest value -> "procedural_digest=" + value
            | TerminalFlowConsoleDetailLane value -> "lane=" + value
            | TerminalFlowConsoleDetailReason value -> "reason=" + value
            | TerminalFlowConsoleDetailOwnedState value -> "owned_state=" + value
            | TerminalFlowConsoleDetailOtherKeyed(key, value) -> key + "=" + value

        let private terminalFlowConsoleHeadBeforeColon (value:string) =
            match value.Split([|':'|], 2, StringSplitOptions.None) with
            | [|head; _|] -> head
            | _ -> value

        let private terminalFlowConsoleSemanticDetailFieldText = function
            | TerminalFlowConsoleDetailGate value ->
                "gate=" + terminalFlowConsoleHeadBeforeColon value
            | field -> terminalFlowConsoleDetailFieldText field

        type TerminalFlowAdvancedConsoleProjection = private {
            lane : TerminalFlowAdvancedConsoleLane
            sequence : int64
            progressBp : int
            etaMs : int64 option
            title : string
            detail : string
            authorityRef : uint32
        }

        let private terminalFlowAdvancedConsoleLaneText = function
            | TerminalFlowConsoleLaneRefMint -> "ref_mint"
            | TerminalFlowConsoleLaneCicProof -> "cic_proof"
            | TerminalFlowConsoleLaneGreenPath -> "green_path"
            | TerminalFlowConsoleLaneQapWatch -> "qap_watch"
            | TerminalFlowConsoleLaneProgressAuthority -> "progress_authority"
            | TerminalFlowConsoleLaneTopologyGate -> "topology_gate"
            | TerminalFlowConsoleLaneWatchdogPetition -> "watchdog_petition"
            | TerminalFlowConsoleLaneExitSeal -> "exit_seal"
            | TerminalFlowConsoleLaneQueueRecovery -> "queue_recovery"
            | TerminalFlowConsoleLaneReplayFairness -> "replay_fairness"
            | TerminalFlowConsoleLaneReducerRecovery -> "reducer_recovery"
            | TerminalFlowConsoleLaneBreakthroughConvergence -> "breakthrough_convergence"
            | TerminalFlowConsoleLaneOutcomeMaturity -> "outcome_maturity"
            | TerminalFlowConsoleLaneCredentialGraph -> "credential_graph"
            | TerminalFlowConsoleLaneTerminalPossession -> "terminal_possession"
            | TerminalFlowConsoleLaneArtifactCovenant -> "artifact_covenant"
            | TerminalFlowConsoleLaneSchedulerChannel -> "scheduler_channel"
            | TerminalFlowConsoleLaneResidualStall -> "residual_stall"
            | TerminalFlowConsoleLaneReplayFanout -> "replay_fanout"
            | TerminalFlowConsoleLaneTotalOrder -> "total_order"

        [<StructuralEquality; NoComparison>]
        type private TerminalFlowAdvancedConsoleChangeIdentity = {
            lane : TerminalFlowAdvancedConsoleLane
            titleRef : CompilerIdentityKernel.ContentDigest
            semanticDetailRef : CompilerIdentityKernel.ContentDigest
            progressKey : int
        }

        let private terminalFlowAdvancedConsoleChangeRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<TerminalFlowAdvancedConsoleChangeIdentity,int64>()

        let private terminalFlowAdvancedConsoleSemanticDetail (projection:TerminalFlowAdvancedConsoleProjection) =
            let detailFields () =
                projection.detail.Split([|'|'|], System.StringSplitOptions.RemoveEmptyEntries)
                |> Array.map terminalFlowConsoleDetailFieldId
            match projection.lane with
            | TerminalFlowConsoleLaneProgressAuthority ->
                detailFields()
                |> Array.filter (function
                    | TerminalFlowConsoleDetailPhase _
                    | TerminalFlowConsoleDetailGate _
                    | TerminalFlowConsoleDetailSemanticDigest _
                    | TerminalFlowConsoleDetailProceduralDigest _ -> true
                    | _ -> false)
                |> Array.map terminalFlowConsoleSemanticDetailFieldText
                |> String.concat "|"
            | TerminalFlowConsoleLaneReplayFairness ->
                detailFields()
                |> Array.filter (function
                    | TerminalFlowConsoleDetailBare _
                    | TerminalFlowConsoleDetailLane _
                    | TerminalFlowConsoleDetailReason _
                    | TerminalFlowConsoleDetailOwnedState _ -> true
                    | _ -> false)
                |> Array.map terminalFlowConsoleDetailFieldText
                |> String.concat "|"
            | TerminalFlowConsoleLaneBreakthroughConvergence ->
                terminalFlowConsoleHeadBeforeColon projection.detail
            | TerminalFlowConsoleLaneReducerRecovery ->
                terminalFlowConsoleHeadBeforeColon projection.detail
            | TerminalFlowConsoleLaneExitSeal when DiagJson.terminalQapProvenDeadlockNow() || DiagJson.terminalFailureExitRequestedNow() || DiagJson.nativePromiseFailureClosedNow() ->
                "failclosed_total_order_owns_exit"
            | _ -> projection.detail

        let rec private terminalFlowConsoleCausalGraphText = function
            | TerminalFlowConsoleProjectionLeaf(lane, title) ->
                sprintf "Projection(lane=%s|title=%s)" (terminalFlowAdvancedConsoleLaneText lane) title
            | TerminalFlowConsoleRootLeaf receiptRef -> sprintf "RootResolved(ref=%u)" receiptRef
            | TerminalFlowConsoleActorLeaf(phase, ageMs) ->
                sprintf "Actor(phase=%s|age_ms=%d)" (DiagJson.terminalSchedulerPushActorPhaseText phase) ageMs
            | TerminalFlowConsoleDrainLeaf(phase, requestAgeMs) ->
                sprintf "Drain(phase=%s|request_age_ms=%d)" (terminalFlowQapPublicationPhaseText phase) requestAgeMs
            | TerminalFlowConsoleCause(cause, effect) ->
                "Cause(" + terminalFlowConsoleCausalGraphText cause + "->" + terminalFlowConsoleCausalGraphText effect + ")"

        let private terminalFlowConsoleRecommendedActionText = function
            | TerminalFlowConsoleAwaitEvaluatorRoot -> "AwaitEvaluatorRoot"
            | TerminalFlowConsoleAwaitOwnerClosure -> "AwaitOwnerClosure"
            | TerminalFlowConsoleArmPendingTerminal -> "ArmPendingTerminal"
            | TerminalFlowConsoleReobserveQapAtStrandedBoundary -> "ReobserveQapAtStrandedBoundary"
            | TerminalFlowConsoleContinueReducer -> "ContinueReducer"

        let private terminalFlowAdvancedConsoleCausalGraph (projection:TerminalFlowAdvancedConsoleProjection) =
            let root = DiagJson.canonicalRootAuthoritySnapshot()
            let actor = DiagJson.terminalSchedulerPushActorSnapshot()
            let actorAgeMs = max 0L (Environment.TickCount64 - actor.changedAtMs)
            let drainPhase = terminalFlowQapPublicationPhaseNow()
            let drainAgeMs = DiagJson.terminalSemanticDrainRequestAgeMsNow()
            let rootRef = if String.IsNullOrWhiteSpace root.receiptId then 0u else terminalFlowMintedRefOf "advanced_console_root_receipt_ref" root.receiptId
            let graph : TerminalFlowConsoleCausalGraph<TerminalFlowConsoleObservedState> =
                TerminalFlowConsoleCause(
                    TerminalFlowConsoleRootLeaf rootRef,
                    TerminalFlowConsoleCause(
                        TerminalFlowConsoleActorLeaf(actor.phase, actorAgeMs),
                        TerminalFlowConsoleCause(
                            TerminalFlowConsoleDrainLeaf(drainPhase, drainAgeMs),
                            TerminalFlowConsoleProjectionLeaf(projection.lane, projection.title))))
            let action =
                match root.phase, actor.phase, drainPhase with
                | DiagJson.CanonicalRootUnarmed, _, _
                | DiagJson.CanonicalRootArmed _, _, _ -> TerminalFlowConsoleAwaitEvaluatorRoot
                | DiagJson.CanonicalRootResolved _, DiagJson.PushActorNoop, TerminalFlowQapPublicationDrainStranded ->
                    TerminalFlowConsoleReobserveQapAtStrandedBoundary
                | DiagJson.CanonicalRootResolved _, DiagJson.PushActorNoop, TerminalFlowQapPublicationDrainRequested ->
                    TerminalFlowConsoleAwaitOwnerClosure
                | DiagJson.CanonicalRootResolved _, DiagJson.PushActorNoop, TerminalFlowQapPublicationBeforeDrain ->
                    TerminalFlowConsoleArmPendingTerminal
                | _ -> TerminalFlowConsoleContinueReducer
            graph, actorAgeMs, action

        let private terminalFlowEmitAdvancedConsoleProjection (projection:TerminalFlowAdvancedConsoleProjection) =
            if DiagJson.quiet then () else
            // Minted refs, leases, snapshot clocks and exact queue magnitudes are observer
            // identity, not causal state. Keep the structured console lane bounded: full proof
            // strings belong to their exact-once receipts, not to every repeated projection.
            let detailChars = projection.detail.Length
            let detailHash = terminalFlowMintedRefOf "advanced_console_detail_ref" projection.detail
            let detailLimit = 256
            let detailTruncated = detailChars > detailLimit
            let boundedDetail =
                if detailTruncated then
                    projection.detail.Substring(0, detailLimit)
                    + sprintf "...[truncated|chars=%d|hash=%u]" detailChars detailHash
                else projection.detail
            let emittedProjection = { projection with detail = boundedDetail }
            let semanticDetail = terminalFlowAdvancedConsoleSemanticDetail emittedProjection
            let causalGraph, blockerAgeMs, recommendedAction = terminalFlowAdvancedConsoleCausalGraph projection
            let causalGraphText = terminalFlowConsoleCausalGraphText causalGraph
            let recommendedActionText = terminalFlowConsoleRecommendedActionText recommendedAction
            let progressKey =
                match projection.lane with
                | TerminalFlowConsoleLaneProgressAuthority -> projection.progressBp / 100
                | _ -> projection.progressBp
            let changeIdentity : TerminalFlowAdvancedConsoleChangeIdentity =
                { lane = projection.lane
                  titleRef = CompilerIdentityKernel.ContentDigest.ofText "advanced-console-title" projection.title
                  semanticDetailRef = CompilerIdentityKernel.ContentDigest.ofText "advanced-console-semantic-detail" semanticDetail
                  progressKey = progressKey }
            let occurrence =
                terminalFlowAdvancedConsoleChangeRegistry.AddOrUpdate(changeIdentity, 1L, fun _ count -> count + 1L)
            let powerOfTwo = occurrence > 0L && (occurrence &&& (occurrence - 1L)) = 0L
            let successProjectionSuppressed =
                DiagJson.terminalQapProvenDeadlockNow()
                && (match projection.lane with
                    | TerminalFlowConsoleLaneExitSeal
                    | TerminalFlowConsoleLaneBreakthroughConvergence -> true
                    | _ -> false)
            let shouldEmit =
                not successProjectionSuppressed
                && (occurrence <= 3L || powerOfTwo || occurrence % 256L = 0L)
            if shouldEmit then
                let etaJson = match projection.etaMs with Some eta -> string eta | None -> "null"
                let graphSnapshotRef = terminalFlowMintedRefOf "advanced_console_graph_ref" causalGraphText
                if occurrence = 1L then
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"advanced_console_graph_snapshot\",\"graph_snapshot_ref\":%u,\"lane\":%s,\"causal_graph_du\":%s,\"authority\":\"single_snapshot_per_semantic_change_key\"}" [| box graphSnapshotRef; box (DiagJson.esc (terminalFlowAdvancedConsoleLaneText projection.lane)); box (DiagJson.esc causalGraphText) |])
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"advanced_console_projection\",\"lane\":%s,\"sequence\":%d,\"progress_bp\":%d,\"eta_ms\":%s,\"title\":%s,\"detail\":%s,\"detail_truncated\":%b,\"detail_chars\":%d,\"detail_ref\":%u,\"authority_ref\":%u,\"repeat_count\":%d,\"graph_snapshot_ref\":%u,\"blocker_age_ms\":%d,\"recommended_action_du\":%s,\"emission_policy\":\"first3_power2_every256_change_key\",\"durable\":false}" [| box (DiagJson.esc (terminalFlowAdvancedConsoleLaneText projection.lane)); box projection.sequence; box projection.progressBp; box etaJson; box (DiagJson.esc projection.title); box (DiagJson.esc boundedDetail); box detailTruncated; box detailChars; box detailHash; box projection.authorityRef; box occurrence; box graphSnapshotRef; box blockerAgeMs; box (DiagJson.esc recommendedActionText) |])

        type TerminalFlowCausalIdentity = private {
            canonicalRoot : TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>
            terminalReceipt : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            fill : TerminalFlowIdentityRef<TerminalFlowFillRefKind>
        }

        type TerminalFlowRootCapability<'State> = private {
            rootReceiptId : string
            semanticDebtPaid : bool
        }

        type TerminalFlowRootConsensusDecision =
            | TerminalFlowRootConsensusAccepted of evaluator:TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>
            | TerminalFlowRootConsensusAwaitEvaluator of evidence:string
            | TerminalFlowRootConsensusDiverged of
                evaluator:TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind> *
                terminal:TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>

        let private terminalFlowCompareRoots
            (evaluator:TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>)
            (terminal:TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>) =
            if terminalFlowIdentityRefText evaluator = terminalFlowIdentityRefText terminal then
                TerminalFlowRootConsensusAccepted evaluator
            else
                TerminalFlowRootConsensusDiverged(evaluator, terminal)

        let private terminalFlowCanonicalRootConsensus
            (terminal:TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>)
            evidence =
            let snapshot = DiagJson.canonicalRootAuthoritySnapshot ()
            if String.IsNullOrWhiteSpace snapshot.receiptId then
                TerminalFlowRootConsensusAwaitEvaluator evidence
            else
                terminalFlowCompareRoots
                    (terminalFlowIdentityRefOfText snapshot.receiptId)
                    terminal

        let private terminalFlowRootConsensusText = function
            | TerminalFlowRootConsensusAccepted evaluator ->
                "RootConsensus(Accepted|evaluator=" + terminalFlowIdentityRefText evaluator + "|kind=RootK)"
            | TerminalFlowRootConsensusAwaitEvaluator evidence ->
                "RootConsensus(AwaitEvaluator|evidence_ref=" + string (NativeCutoverStableRef.ref32 "root-consensus-await-evaluator" [evidence]) + ")"
            | TerminalFlowRootConsensusDiverged(evaluator, terminal) ->
                "RootConsensus(Diverged|evaluator=" + terminalFlowIdentityRefText evaluator + "(RootK)|terminal=" + terminalFlowIdentityRefText terminal + "(RootK))"

        type TerminalFlowCommitEligibilityId =
            | TerminalFlowCommitEligible of
                root:TerminalFlowRootCapability<TerminalFlowRootResolvedState> *
                fillKey:string *
                receiptId:string *
                boundary:TerminalFlowCertificateBoundaryId
            | TerminalFlowCommitBlocked of fillKey:string * reason:TerminalFlowWhyNotTerminalCommitId

        type TerminalFlowArtifactPlanBoundState = class end
        type TerminalFlowArtifactsCommittedState = class end
        type TerminalFlowNativeRootBridgeState = class end

        type TerminalFlowArtifactWriteIntentId =
            | TerminalFlowWriteCodeArtifact
            | TerminalFlowWriteManifestArtifact
            | TerminalFlowWriteDiagnosticsArtifact
            | TerminalFlowWriteTerminalReceiptArtifact

        // The terminal corridor no longer asks a global registry to
        // re-authorize a string manifest after the writer has been bound.  A typed
        // NativeWriterCapability is captured exactly once at the root boundary and
        // travels inside the same envelope/IVar/Job.bind chain as the owner receipts.
        type TerminalFlowNativeRootBridgeAuthority =
            | TerminalFlowNativeRootBridgeFromNativeWriterCapability of NativeWriterCapability<TerminalOutcomeKind>
            | TerminalFlowNativeRootBridgeFromStageToken of
                tokenRef:uint32 *
                rootReceiptRef:uint32 *
                ownerLedgerSealRef:uint32 *
                wakerEdgeRef:uint32

        type TerminalFlowNativeRootBridge = private {
            authority : TerminalFlowNativeRootBridgeAuthority
            cellId : string
            proofHash : string
            resolutionRef : uint32
            workDagClosureHash : string
            expectedArtifactSetHash : string
        }

        // Explicit existential boundary between the terminal-proof kind and the
        // EvalWorklist owner-ledger kind.  Neither side is cast; the receipt binds
        // their independently typed identities into one causal transaction.
        type TerminalFlowKindBridgeReceipt = private {
            bridgeId : string
            terminalKindProofHash : string
            evalGraphOwnerTransactionId : string
            ownerClosureCertificateId : string
        }

        type TerminalFlowArtifactManifestDisposition =
            | TerminalFlowBuildDraftManifestRequired
            | TerminalFlowTerminalFailureManifest of reasonRef:uint32 * reason:CompilerKernelV2.OperationalReasonId

        type TerminalFlowArtifactManifestLifecycle =
            | TerminalFlowArtifactManifestArmed of requestId:string * nativeCellId:string
            | TerminalFlowArtifactManifestFilled of
                manifestRef:TerminalFlowIdentityRef<TerminalFlowArtifactManifestRefKind> *
                artifactSetHash:string *
                byteCount:int *
                filledBy:string
            | TerminalFlowArtifactManifestFailureProjected of
                failureManifestRef:TerminalFlowIdentityRef<TerminalFlowArtifactManifestRefKind> * reasonRef:uint32 * reason:CompilerKernelV2.OperationalReasonId
            | TerminalFlowArtifactManifestRejected of reasonRef:uint32 * reason:CompilerKernelV2.OperationalReasonId

        type TerminalFlowWriterCompletionRoute =
            | TerminalFlowWriterCompletionGreenPath of
                manifestRef:TerminalFlowIdentityRef<TerminalFlowArtifactManifestRefKind> * artifactSetHash:string * intentCount:int
            | TerminalFlowWriterCompletionTypedFailure of reasonRef:uint32 * reason:CompilerKernelV2.OperationalReasonId
            | TerminalFlowWriterCompletionRejected of reasonRef:uint32 * reason:CompilerKernelV2.OperationalReasonId

        let private terminalFlowArtifactManifestLifecycleText = function
            | TerminalFlowArtifactManifestArmed(_, _) -> "manifest_armed"
            | TerminalFlowArtifactManifestFilled(_, _, _, _) -> "manifest_filled"
            | TerminalFlowArtifactManifestFailureProjected(_, _, _) -> "manifest_failure_projected"
            | TerminalFlowArtifactManifestRejected(_, _) -> "manifest_rejected"

        let private terminalFlowWriterCompletionRouteText = function
            | TerminalFlowWriterCompletionGreenPath(_, _, _) -> "green_path"
            | TerminalFlowWriterCompletionTypedFailure(_, _) -> "typed_failure"
            | TerminalFlowWriterCompletionRejected(_, _) -> "rejected"

        type TerminalFlowArtifactWritePlan<'State> = private {
            planId : string
            manifestText : string
            manifestDisposition : TerminalFlowArtifactManifestDisposition
            intents : TerminalFlowArtifactWriteIntentId list
            nativeBridge : TerminalFlowNativeRootBridge
            kindBridge : TerminalFlowKindBridgeReceipt
            expectedArtifactSetHash : string
        }

        type TerminalFlowArtifactAuthorizationId =
            | TerminalFlowArtifactsAuthorizedByNativeRootComplete of
                bridge:TerminalFlowNativeRootBridge * committedArtifactSetHash:string
            | TerminalFlowArtifactsAuthorizedByTerminalFailure of
                failureManifestRef:TerminalFlowIdentityRef<TerminalFlowArtifactManifestRefKind> * reasonRef:uint32 * reason:CompilerKernelV2.OperationalReasonId
            | TerminalFlowArtifactsRejectedByNativeRootComplete of reasonRef:uint32 * reason:CompilerKernelV2.OperationalReasonId

        type TerminalFlowArtifactExecutionReceipt =
            | TerminalFlowArtifactsExecuted of
                planId:string * artifactSetHash:string * intents:TerminalFlowArtifactWriteIntentId list
            | TerminalFlowArtifactsTerminalFailureProjected of
                planId:string * failureManifestRef:TerminalFlowIdentityRef<TerminalFlowArtifactManifestRefKind> * reasonRef:uint32 * reason:CompilerKernelV2.OperationalReasonId * intents:TerminalFlowArtifactWriteIntentId list
            | TerminalFlowArtifactsExecutionRejected of planId:string * reasonRef:uint32 * reason:CompilerKernelV2.OperationalReasonId

        type TerminalFlowArtifactWriteReceipt<'State> = private {
            plan : TerminalFlowArtifactWritePlan<TerminalFlowArtifactPlanBoundState>
            authorization : TerminalFlowArtifactAuthorizationId
            execution : TerminalFlowArtifactExecutionReceipt
            manifestLifecycle : TerminalFlowArtifactManifestLifecycle
            writerCompletionRoute : TerminalFlowWriterCompletionRoute
        }

        type TerminalFlowProtocolSurface =
            | TerminalFlowPrimarySurface
            | TerminalFlowLegacyMirrorSurfaceQuarantined of mirrorName:string

        type TerminalFlowReducerMutationAuthority =
            | TerminalFlowMutationReducerChannelOwned of surface:TerminalFlowProtocolSurface
            | TerminalFlowMutationLegacyInterlockedQuarantined of site:string * replacementEvent:string

        let private terminalFlowProtocolSurfaceText = function
            | TerminalFlowPrimarySurface -> "primary_surface"
            | TerminalFlowLegacyMirrorSurfaceQuarantined mirrorName -> "legacy_mirror_quarantined:" + mirrorName

        let private terminalFlowReducerMutationAuthorityText = function
            | TerminalFlowMutationReducerChannelOwned surface -> "reducer_channel_owned:" + terminalFlowProtocolSurfaceText surface
            | TerminalFlowMutationLegacyInterlockedQuarantined(site, replacementEvent) ->
                "legacy_interlocked_quarantined:site=" + site + ":replace_with=" + replacementEvent

        // Round  destructive consolidation: artifact success/failure/rejection
        // must cross one typed corridor before writer exit.  This gives both
        // TerminalFlow copies a single surface to port toward instead of
        // duplicating manifest/route decisions in ad-hoc records.
        type TerminalFlowArtifactCorridor<'State> = private {
            surface : TerminalFlowProtocolSurface
            mutationAuthority : TerminalFlowReducerMutationAuthority
            artifactReceipt : TerminalFlowArtifactWriteReceipt<'State>
            manifestLifecycle : TerminalFlowArtifactManifestLifecycle
            writerCompletionRoute : TerminalFlowWriterCompletionRoute
        }

        let private terminalFlowArtifactCorridorFor (receipt:TerminalFlowArtifactWriteReceipt<'State>) =
            { surface = TerminalFlowPrimarySurface
              mutationAuthority = TerminalFlowMutationReducerChannelOwned TerminalFlowPrimarySurface
              artifactReceipt = receipt
              manifestLifecycle = receipt.manifestLifecycle
              writerCompletionRoute = receipt.writerCompletionRoute }

        // Round  destructive CIC substrate: the proof-checker/kernel work must
        // reuse the same corridor discipline as TerminalFlow.  Terms are interned
        // references, equality is a witnessed relation, and universe constraints
        // are ledger entries instead of strings that a later scheduler can replay
        // out of order.
        type TerminalFlowCicTermRefKind private () =
            static member IdentityKindTag () = 0x050001u
        type TerminalFlowCicUniverseRefKind private () =
            static member IdentityKindTag () = 0x050002u
        type TerminalFlowCicDefEqWitnessRefKind private () =
            static member IdentityKindTag () = 0x050003u
        type TerminalFlowCicCheckReceiptRefKind private () =
            static member IdentityKindTag () = 0x050004u

        // CIC nominal names now use the global witness-driven interner.  The hot
        // kernel never compares lexical strings for scope/binder/definition identity.
        type TerminalFlowCicScopeId = CompilerIdentityKernel.InternedTextId<CompilerIdentityKernel.CicScopeKind>
        type TerminalFlowCicBinderId = CompilerIdentityKernel.InternedTextId<CompilerIdentityKernel.CicBinderKind>
        type TerminalFlowCicConstantNameId = CompilerIdentityKernel.InternedTextId<CompilerIdentityKernel.CicConstantNameKind>
        type TerminalFlowCicMetaNameId = CompilerIdentityKernel.InternedTextId<CompilerIdentityKernel.CicMetaNameKind>
        type TerminalFlowCicDefinitionId = CompilerIdentityKernel.InternedTextId<CompilerIdentityKernel.CicDefinitionNameKind>
        type TerminalFlowCicInvariantNameId = CompilerIdentityKernel.InternedTextId<CompilerIdentityKernel.CicInvariantNameKind>
        type TerminalFlowCicUniverseNameId = CompilerIdentityKernel.InternedTextId<CompilerIdentityKernel.CicUniverseNameKind>

        let private terminalFlowCicScopeId value : TerminalFlowCicScopeId = CompilerIdentityKernel.InternedTextId.create<CompilerIdentityKernel.CicScopeKind> value
        let private terminalFlowCicBinderId value : TerminalFlowCicBinderId = CompilerIdentityKernel.InternedTextId.create<CompilerIdentityKernel.CicBinderKind> value
        let private terminalFlowCicConstantNameId value : TerminalFlowCicConstantNameId = CompilerIdentityKernel.InternedTextId.create<CompilerIdentityKernel.CicConstantNameKind> value
        let private terminalFlowCicMetaNameId value : TerminalFlowCicMetaNameId = CompilerIdentityKernel.InternedTextId.create<CompilerIdentityKernel.CicMetaNameKind> value
        let private terminalFlowCicDefinitionId value : TerminalFlowCicDefinitionId = CompilerIdentityKernel.InternedTextId.create<CompilerIdentityKernel.CicDefinitionNameKind> value
        let private terminalFlowCicInvariantNameId value : TerminalFlowCicInvariantNameId = CompilerIdentityKernel.InternedTextId.create<CompilerIdentityKernel.CicInvariantNameKind> value
        let private terminalFlowCicUniverseNameId value : TerminalFlowCicUniverseNameId = CompilerIdentityKernel.InternedTextId.create<CompilerIdentityKernel.CicUniverseNameKind> value

        [<StructuralEquality; NoComparison>]
        type TerminalFlowCicLevelShape =
            | TerminalFlowCicLevelZero
            | TerminalFlowCicLevelSucc of TerminalFlowCicLevelId
            | TerminalFlowCicLevelMax of TerminalFlowCicLevelId list
            | TerminalFlowCicLevelIMax of TerminalFlowCicLevelId * TerminalFlowCicLevelId
            | TerminalFlowCicLevelParam of TerminalFlowCicUniverseNameId
            | TerminalFlowCicLevelMeta of TerminalFlowCicUniverseNameId

        type TerminalFlowCicLevelInternRequest = private {
            requestRef : uint32
            shape : TerminalFlowCicLevelShape
            structuralHash : uint64
        }

        type TerminalFlowCicLevelInternReceipt = private {
            requestRef : uint32
            levelId : TerminalFlowCicLevelId
            shape : TerminalFlowCicLevelShape
            structuralHash : uint64
            exactOnceRef : uint32
        }

        [<StructuralEquality; NoComparison>]
        type TerminalFlowCicTermShape =
            | TerminalFlowCicSort of universe:TerminalFlowCicLevelId
            | TerminalFlowCicBoundVar of scope:TerminalFlowCicScopeId * binder:TerminalFlowCicBinderId
            | TerminalFlowCicLambda of binder:TerminalFlowCicBinderId * domain:TerminalFlowCicTermId * body:TerminalFlowCicTermId
            | TerminalFlowCicPi of binder:TerminalFlowCicBinderId * domain:TerminalFlowCicTermId * codomain:TerminalFlowCicTermId
            | TerminalFlowCicApp of fn:TerminalFlowCicTermId * arg:TerminalFlowCicTermId
            | TerminalFlowCicLet of binder:TerminalFlowCicBinderId * value:TerminalFlowCicTermId * body:TerminalFlowCicTermId
            | TerminalFlowCicConst of name:TerminalFlowCicConstantNameId * universe:TerminalFlowCicLevelId option
            | TerminalFlowCicMeta of name:TerminalFlowCicMetaNameId

        type TerminalFlowCicTermInternRequest = private {
            requestRef : uint32
            scope : TerminalFlowCicScopeId
            shape : TerminalFlowCicTermShape
            structuralHash : uint64
        }

        type TerminalFlowCicTermInternReceipt = private {
            requestRef : uint32
            termId : TerminalFlowCicTermId
            scope : TerminalFlowCicScopeId
            shape : TerminalFlowCicTermShape
            structuralHash : uint64
            exactOnceRef : uint32
        }

        type TerminalFlowCicAlphaNormalDigest = private | TerminalFlowCicAlphaNormalDigest of uint64

        type TerminalFlowCicTermInternKey = private {
            generation : TerminalFlowCicArenaGenerationId
            scope : TerminalFlowCicScopeId
            shapeDigest : TerminalFlowCicAlphaNormalDigest
            structuralHash : uint64
        }

        type TerminalFlowCicInternTableConflict =
            | TerminalFlowCicInternDuplicateReused of key:TerminalFlowCicTermInternKey * existing:TerminalFlowCicTermId
            | TerminalFlowCicInternHashCollision of key:TerminalFlowCicTermInternKey * existing:TerminalFlowCicTermId * attempted:TerminalFlowCicTermId
            | TerminalFlowCicLevelInternDuplicateReused of existing:TerminalFlowCicLevelId
            | TerminalFlowCicLevelInternHashCollision of structuralHash:uint64 * existing:TerminalFlowCicLevelId * attempted:TerminalFlowCicLevelId

        type TerminalFlowCicInternTable = private {
            generation : TerminalFlowCicArenaGenerationId
            nextTermSlot : uint32
            nextLevelSlot : uint32
            byKey : Map<uint64, TerminalFlowCicTermInternReceipt>
            bySlot : Map<uint32, TerminalFlowCicTermInternReceipt>
            levelsByHash : Map<uint64, TerminalFlowCicLevelInternReceipt>
            levelsBySlot : Map<uint32, TerminalFlowCicLevelInternReceipt>
            conflicts : TerminalFlowCicInternTableConflict list
            deterministicSequence : int64
            exactOnceRef : uint32
        }

        type TerminalFlowCicDefEqWitness =
            | TerminalFlowCicDefEqReflexive of term:TerminalFlowCicTermId
            | TerminalFlowCicDefEqBeta of redex:TerminalFlowCicTermId * normal:TerminalFlowCicTermId
            | TerminalFlowCicDefEqDelta of constantName:TerminalFlowCicConstantNameId * unfolded:TerminalFlowCicTermId
            | TerminalFlowCicDefEqEta of left:TerminalFlowCicTermId * right:TerminalFlowCicTermId
            | TerminalFlowCicDefEqCongruence of left:TerminalFlowCicTermId * right:TerminalFlowCicTermId * children:TerminalFlowIdentityRef<TerminalFlowCicDefEqWitnessRefKind> list
            | TerminalFlowCicDefEqBlocked of left:TerminalFlowCicTermId * right:TerminalFlowCicTermId * reason:CompilerKernelV2.OperationalReasonId

        type TerminalFlowCicUniverseConstraint =
            | TerminalFlowCicUniverseLeq of lower:TerminalFlowCicLevelId * upper:TerminalFlowCicLevelId
            | TerminalFlowCicUniverseEq of left:TerminalFlowCicLevelId * right:TerminalFlowCicLevelId
            | TerminalFlowCicUniverseMax of result:TerminalFlowCicLevelId * operands:TerminalFlowCicLevelId list

        type TerminalFlowCicUniverseLedger = private {
            constraints : TerminalFlowCicUniverseConstraint list
            unionFindEpoch : int64
            unresolved : int
            exactOnceRef : uint32
        }

        // Universe constraints must not ride the generic work queue.  Round 3
        // promotes them into an incremental union-find ledger with explicit
        // acyclicity evidence and blocked edges.
        type TerminalFlowCicUniverseUnionRank = private | TerminalFlowCicUniverseUnionRank of int

        type TerminalFlowCicUniverseEdgeState =
            | TerminalFlowCicUniverseEdgeAccepted of constraintRef:uint32 * epoch:int64
            | TerminalFlowCicUniverseEdgeBlocked of constraintRef:uint32 * blockerRef:uint32
            | TerminalFlowCicUniverseEdgeRejectedCycle of constraintRef:uint32 * cycleRef:uint32

        type TerminalFlowCicUniverseUnionFind = private {
            parent : Map<uint64, uint64>
            rank : Map<uint64, TerminalFlowCicUniverseUnionRank>
            acceptedEdges : Map<uint32, TerminalFlowCicUniverseConstraint>
            edgeStates : Map<uint32, TerminalFlowCicUniverseEdgeState>
            acyclicProofRef : uint32 option
            epoch : int64
            exactOnceRef : uint32
        }

        type TerminalFlowCicDeBruijnIndex = private | TerminalFlowCicDeBruijnIndex of int

        type TerminalFlowCicSubstitution =
            | TerminalFlowCicSubstitutionIdentity of scope:TerminalFlowCicScopeId
            | TerminalFlowCicSubstitutionShift of by:int * scope:TerminalFlowCicScopeId
            | TerminalFlowCicSubstitutionCons of head:TerminalFlowCicTermId * tail:TerminalFlowCicSubstitution
            | TerminalFlowCicSubstitutionCompose of outer:TerminalFlowCicSubstitution * inner:TerminalFlowCicSubstitution

        type TerminalFlowCicReductionRule =
            | TerminalFlowCicReductionBeta
            | TerminalFlowCicReductionDelta of constantName:TerminalFlowCicConstantNameId
            | TerminalFlowCicReductionZeta
            | TerminalFlowCicReductionIota
            | TerminalFlowCicReductionEta

        type TerminalFlowCicReductionReceipt = private {
            input : TerminalFlowCicTermId
            output : TerminalFlowCicTermId
            rule : TerminalFlowCicReductionRule
            substitution : TerminalFlowCicSubstitution option
            deterministicSequence : int64
            exactOnceRef : uint32
        }

        type TerminalFlowCicBlocker =
            | TerminalFlowCicUnboundVariable of scope:TerminalFlowCicScopeId * index:TerminalFlowCicDeBruijnIndex
            | TerminalFlowCicUniverseConstraintBlocked of unresolved:int
            | TerminalFlowCicDefEqBlockedByMeta of name:TerminalFlowCicMetaNameId
            | TerminalFlowCicDefEqCycle of cycleRef:uint32
            | TerminalFlowCicDefinitionDependencyBlocked of definitionName:TerminalFlowCicDefinitionId
            | TerminalFlowCicKernelInvariantViolation of invariantName:TerminalFlowCicInvariantNameId

        type TerminalFlowCicCheckVerdict =
            | TerminalFlowCicCheckAccepted of receipt:TerminalFlowIdentityRef<TerminalFlowCicCheckReceiptRefKind>
            | TerminalFlowCicCheckRejected of blocker:TerminalFlowCicBlocker * witness:TerminalFlowCicDefEqWitness option
            | TerminalFlowCicCheckBlocked of blocker:TerminalFlowCicBlocker

        type TerminalFlowCicDefEqKey = private {
            left : TerminalFlowCicTermId
            right : TerminalFlowCicTermId
            scope : TerminalFlowCicScopeId
            universeEpoch : int64
        }

        type TerminalFlowCicDefEqLedgerEntry =
            | TerminalFlowCicDefEqPending of key:TerminalFlowCicDefEqKey * dependencyRefs:uint32 list
            | TerminalFlowCicDefEqWitnessed of key:TerminalFlowCicDefEqKey * witnessRef:TerminalFlowIdentityRef<TerminalFlowCicDefEqWitnessRefKind> * witness:TerminalFlowCicDefEqWitness
            | TerminalFlowCicDefEqBlockedEntry of key:TerminalFlowCicDefEqKey * blocker:TerminalFlowCicBlocker


        type TerminalFlowCicDefinitionCheckState =
            | TerminalFlowCicDefinitionQueued
            | TerminalFlowCicDefinitionChecking of dependencyReceipts:TerminalFlowIdentityRef<TerminalFlowCicCheckReceiptRefKind> list
            | TerminalFlowCicDefinitionAccepted of receipt:TerminalFlowIdentityRef<TerminalFlowCicCheckReceiptRefKind>
            | TerminalFlowCicDefinitionRejected of blocker:TerminalFlowCicBlocker

        type TerminalFlowCicDefinitionCheckRequest = private {
            definitionId : TerminalFlowCicDefinitionId
            termRef : TerminalFlowCicTermId
            typeRef : TerminalFlowCicTermId
            dependencyIds : TerminalFlowCicDefinitionId list
            resultIvarRef : uint32
        }

        type TerminalFlowCicDefinitionCheckResult =
            | TerminalFlowCicDefinitionCheckAccepted of TerminalFlowIdentityRef<TerminalFlowCicCheckReceiptRefKind>
            | TerminalFlowCicDefinitionCheckRejected of TerminalFlowCicBlocker

        type TerminalFlowCicDefinitionCheckJob = private {
            request : TerminalFlowCicDefinitionCheckRequest
            state : TerminalFlowCicDefinitionCheckState
        }

        // MIGRATION / CIC migration front: DefEq and WHNF are actor-owned.
        // A conversion check must enter through a request, share WHNF promises,
        // publish congruence-closure evidence, and close its proof owner before
        // the kernel corridor may promote an artifact or green terminal path.
        type TerminalFlowCicWhnfTransparencyMode =
            | TerminalFlowCicWhnfTransparencyOpaque
            | TerminalFlowCicWhnfTransparencyReducible
            | TerminalFlowCicWhnfTransparencyInstances
            | TerminalFlowCicWhnfTransparencyAll

        let private terminalFlowCicWhnfTransparencyModeText = function
            | TerminalFlowCicWhnfTransparencyOpaque -> "opaque"
            | TerminalFlowCicWhnfTransparencyReducible -> "reducible"
            | TerminalFlowCicWhnfTransparencyInstances -> "instances"
            | TerminalFlowCicWhnfTransparencyAll -> "all"

        type TerminalFlowCicWhnfPromiseState =
            | TerminalFlowCicWhnfPromiseUnforced
            | TerminalFlowCicWhnfPromiseForcing of waiterCount:int
            | TerminalFlowCicWhnfPromiseResolved of receipt:TerminalFlowCicReductionReceipt
            | TerminalFlowCicWhnfPromiseBlocked of blocker:TerminalFlowCicBlocker

        type TerminalFlowCicWhnfPromiseKey = private {
            input : TerminalFlowCicTermId
            transparencyMode : TerminalFlowCicWhnfTransparencyMode
            unfoldingBudget : int
        }

        type TerminalFlowCicWhnfPromise = private {
            promiseRef : uint32
            key : TerminalFlowCicWhnfPromiseKey
            waiters : uint32 list
            state : TerminalFlowCicWhnfPromiseState
        }

        type TerminalFlowCicDefEqActorRequest = private {
            requestRef : uint32
            key : TerminalFlowCicDefEqKey
            leftWhnf : TerminalFlowCicWhnfPromise
            rightWhnf : TerminalFlowCicWhnfPromise
            resultIvarRef : uint32
            proofOwner : PhantomOwnerId<EvalWorklistTerminalGraphKind, CicProofObligationOwnerKind>
        }

        type TerminalFlowCicCongruenceClosureEdge = private {
            edgeRef : uint32
            left : TerminalFlowCicTermId
            right : TerminalFlowCicTermId
            witness : TerminalFlowCicDefEqWitness
            witnessRef : TerminalFlowIdentityRef<TerminalFlowCicDefEqWitnessRefKind>
            exactOnceRef : uint32
        }

        type TerminalFlowCicUniverseOwnerState =
            | TerminalFlowCicUniverseOwnerOpen of ledger:TerminalFlowCicUniverseLedger
            | TerminalFlowCicUniverseOwnerClosed of receipt:TerminalFlowIdentityRef<TerminalFlowCicCheckReceiptRefKind> * ledger:TerminalFlowCicUniverseLedger
            | TerminalFlowCicUniverseOwnerBlocked of blocker:TerminalFlowCicBlocker

        type TerminalFlowCicWhnfMemoEntry =
            | TerminalFlowCicWhnfMemoMiss of key:TerminalFlowCicWhnfPromiseKey
            | TerminalFlowCicWhnfMemoPending of key:TerminalFlowCicWhnfPromiseKey * promiseRef:uint32
            | TerminalFlowCicWhnfMemoHit of key:TerminalFlowCicWhnfPromiseKey * receipt:TerminalFlowCicReductionReceipt

