            congruenceEdges : Map<uint32, TerminalFlowCicCongruenceClosureEdge>
            universeOwners : Map<uint32, TerminalFlowCicUniverseOwnerState>
            openObligations : (TerminalFlowCicObligationKey * ISomeTerminalFlowCicObligation) list
            closedObligations : (TerminalFlowCicObligationKey * TerminalFlowCicObligationCloseReceipt) list
            definitionJobs : (TerminalFlowCicDefinitionId * TerminalFlowCicDefinitionCheckJob) list
