        type TerminalFlowCicKernelQuiescenceViolation =
            | TerminalFlowCicQuiescenceDefEqInFlight of count:CompilerKernelV2.NodeCount
            | TerminalFlowCicQuiescenceDefEqBlocked of count:CompilerKernelV2.NodeCount
            | TerminalFlowCicQuiescenceWhnfPending of count:CompilerKernelV2.NodeCount
            | TerminalFlowCicQuiescenceUniverseOwnerOpen of count:CompilerKernelV2.NodeCount
            | TerminalFlowCicQuiescenceObligationsOpen of count:CompilerKernelV2.NodeCount
            | TerminalFlowCicQuiescenceDefinitionsPending of count:CompilerKernelV2.NodeCount
            | TerminalFlowCicQuiescenceNativeMetavars of count:CompilerKernelV2.NodeCount
            | TerminalFlowCicQuiescenceInternConflict of count:CompilerKernelV2.NodeCount
            | TerminalFlowCicQuiescenceReplayAmplificationDebt of count:CompilerKernelV2.NodeCount
            | TerminalFlowCicQuiescenceDeterminismViolation of count:CompilerKernelV2.NodeCount

        type TerminalFlowCicKernelQuiescenceCertificate = private {
            certificateRef : uint32
            deterministicSequence : int64
            completedCost : CompilerKernelV2.SemanticCost
            memoHitCount : CompilerKernelV2.NodeCount
            promiseShareCount : CompilerKernelV2.NodeCount
            internReuseCount : CompilerKernelV2.NodeCount
            universeUnionCount : CompilerKernelV2.NodeCount
            exactOnceRef : uint32
        }

        let private terminalFlowCicKernelQuiescenceViolationText = function
            | TerminalFlowCicQuiescenceDefEqInFlight count -> "defeq_in_flight:" + string (CompilerKernelV2.Measured.value count)
            | TerminalFlowCicQuiescenceDefEqBlocked count -> "defeq_blocked:" + string (CompilerKernelV2.Measured.value count)
            | TerminalFlowCicQuiescenceWhnfPending count -> "whnf_pending:" + string (CompilerKernelV2.Measured.value count)
            | TerminalFlowCicQuiescenceUniverseOwnerOpen count -> "universe_owner_open:" + string (CompilerKernelV2.Measured.value count)
            | TerminalFlowCicQuiescenceObligationsOpen count -> "obligations_open:" + string (CompilerKernelV2.Measured.value count)
            | TerminalFlowCicQuiescenceDefinitionsPending count -> "definitions_pending:" + string (CompilerKernelV2.Measured.value count)
            | TerminalFlowCicQuiescenceNativeMetavars count -> "native_metavars:" + string (CompilerKernelV2.Measured.value count)
            | TerminalFlowCicQuiescenceInternConflict count -> "intern_conflict:" + string (CompilerKernelV2.Measured.value count)
            | TerminalFlowCicQuiescenceReplayAmplificationDebt count -> "replay_amplification_debt:" + string (CompilerKernelV2.Measured.value count)
            | TerminalFlowCicQuiescenceDeterminismViolation count -> "determinism_violation:" + string (CompilerKernelV2.Measured.value count)

        let private terminalFlowCicNodeCountOfInt label value : CompilerKernelV2.NodeCount =
            CompilerKernelV2.Measured.ofInt<CompilerKernelV2.NodeCountUnit> label value

        let private terminalFlowCicNodeCountOfInt64 label value : CompilerKernelV2.NodeCount =
            CompilerKernelV2.Measured.create<CompilerKernelV2.NodeCountUnit> label value

        let private terminalFlowCicActorQuiescenceFor (actor:TerminalFlowCicDefEqActorState) =
            let violations = ResizeArray<TerminalFlowCicKernelQuiescenceViolation>()
            if actor.inFlight.Count > 0 then violations.Add(TerminalFlowCicQuiescenceDefEqInFlight(terminalFlowCicNodeCountOfInt "defeqInFlight" actor.inFlight.Count))
            if actor.blocked.Count > 0 then violations.Add(TerminalFlowCicQuiescenceDefEqBlocked(terminalFlowCicNodeCountOfInt "defeqBlocked" actor.blocked.Count))
            let pendingWhnf =
                actor.substrate.whnfMemo
                |> Map.toSeq
                |> Seq.filter (fun (_, entry) -> match entry with | TerminalFlowCicWhnfMemoPending _ -> true | _ -> false)
                |> Seq.length
            if pendingWhnf > 0 then violations.Add(TerminalFlowCicQuiescenceWhnfPending(terminalFlowCicNodeCountOfInt "whnfPending" pendingWhnf))
            let openUniverseOwners =
                actor.universeOwners
                |> Map.toSeq
                |> Seq.filter (fun (_, owner) -> match owner with | TerminalFlowCicUniverseOwnerOpen _ -> true | _ -> false)
                |> Seq.length
            if openUniverseOwners > 0 then violations.Add(TerminalFlowCicQuiescenceUniverseOwnerOpen(terminalFlowCicNodeCountOfInt "universeOwnersOpen" openUniverseOwners))
            let openObligationCount = List.length actor.openObligations
            if openObligationCount > 0 then violations.Add(TerminalFlowCicQuiescenceObligationsOpen(terminalFlowCicNodeCountOfInt "obligationsOpen" openObligationCount))
            let pendingDefinitions =
                actor.definitionJobs
                |> List.filter (fun (_, job) -> match job.state with | TerminalFlowCicDefinitionAccepted _ | TerminalFlowCicDefinitionRejected _ -> false | TerminalFlowCicDefinitionQueued | TerminalFlowCicDefinitionChecking _ -> true)
                |> List.length
            if pendingDefinitions > 0 then violations.Add(TerminalFlowCicQuiescenceDefinitionsPending(terminalFlowCicNodeCountOfInt "definitionsPending" pendingDefinitions))
            if actor.nativeCounters.metavarsInKernel > 0L then violations.Add(TerminalFlowCicQuiescenceNativeMetavars(terminalFlowCicNodeCountOfInt64 "nativeMetavars" actor.nativeCounters.metavarsInKernel))
            if actor.substrate.internTable.conflicts.Length > 0 then violations.Add(TerminalFlowCicQuiescenceInternConflict(terminalFlowCicNodeCountOfInt "internConflicts" actor.substrate.internTable.conflicts.Length))
            if CompilerKernelV2.Measured.value actor.replayAmplificationDebtCount > 0L then violations.Add(TerminalFlowCicQuiescenceReplayAmplificationDebt actor.replayAmplificationDebtCount)
            if CompilerKernelV2.Measured.value actor.determinismViolationCount > 0L then violations.Add(TerminalFlowCicQuiescenceDeterminismViolation actor.determinismViolationCount)
            if violations.Count = 0 then
                let identity =
                    FastRuntimeFormat.format "seq=%d|cost=%d|memo=%d|promise=%d|intern=%d|universe=%d" [| box actor.deterministicSequence; box (CompilerKernelV2.Measured.value actor.completedCost); box (CompilerKernelV2.Measured.value actor.memoHitCount); box (CompilerKernelV2.Measured.value actor.promiseShareCount); box (CompilerKernelV2.Measured.value actor.internReuseCount); box (CompilerKernelV2.Measured.value actor.universeUnionCount) |]
                Ok {
                    certificateRef = terminalFlowMintedRefOf "cic_kernel_quiescence_certificate_ref" identity
                    deterministicSequence = actor.deterministicSequence
                    completedCost = actor.completedCost
                    memoHitCount = actor.memoHitCount
                    promiseShareCount = actor.promiseShareCount
                    internReuseCount = actor.internReuseCount
                    universeUnionCount = actor.universeUnionCount
                    exactOnceRef = terminalFlowMintedRefOf "cic_kernel_quiescence_exact_once" identity
                }
            else Error (List.ofSeq violations)

        let private terminalFlowCicScopeIdText (value:TerminalFlowCicScopeId) = CompilerIdentityKernel.InternedTextId.text value
        let private terminalFlowCicBinderIdText (value:TerminalFlowCicBinderId) = CompilerIdentityKernel.InternedTextId.text value
        let private terminalFlowCicConstantNameText (value:TerminalFlowCicConstantNameId) = CompilerIdentityKernel.InternedTextId.text value
        let private terminalFlowCicMetaNameText (value:TerminalFlowCicMetaNameId) = CompilerIdentityKernel.InternedTextId.text value
        let private terminalFlowCicDefinitionIdText (value:TerminalFlowCicDefinitionId) = CompilerIdentityKernel.InternedTextId.text value
        let private terminalFlowCicInvariantNameText (value:TerminalFlowCicInvariantNameId) = CompilerIdentityKernel.InternedTextId.text value
        let private terminalFlowCicUniverseNameText (value:TerminalFlowCicUniverseNameId) = CompilerIdentityKernel.InternedTextId.text value

        let private terminalFlowCicBlockerText = function
            | TerminalFlowCicUnboundVariable(_, TerminalFlowCicDeBruijnIndex index) -> "unbound_variable:index=" + string index
            | TerminalFlowCicUniverseConstraintBlocked unresolved -> "universe_constraint_blocked:" + string unresolved
            | TerminalFlowCicDefEqBlockedByMeta name -> "defeq_blocked_by_meta:" + terminalFlowCicMetaNameText name
            | TerminalFlowCicDefEqCycle cycleRef -> "defeq_cycle:" + string cycleRef
            | TerminalFlowCicDefinitionDependencyBlocked name -> "definition_dependency_blocked:" + terminalFlowCicDefinitionIdText name
            | TerminalFlowCicKernelInvariantViolation invariantName -> "kernel_invariant_violation:" + terminalFlowCicInvariantNameText invariantName

        let private terminalFlowCicArenaGenerationValue (TerminalFlowCicArenaGenerationId value) = value

        let private terminalFlowCicTermIdText (term:TerminalFlowCicTermId) =
            FastRuntimeFormat.format "g=%u|slot=%u|hash=%s" [| box (terminalFlowCicArenaGenerationValue term.generation); box term.slot; box (string term.structuralHash) |]

        let private terminalFlowCicLevelIdText (level:TerminalFlowCicLevelId) =
            FastRuntimeFormat.format "g=%u|slot=%u|hash=%s" [| box (terminalFlowCicArenaGenerationValue level.generation); box level.slot; box (string level.structuralHash) |]

        let private terminalFlowCicLevelShapeIdentityText = function
            | TerminalFlowCicLevelZero -> "zero"
            | TerminalFlowCicLevelSucc level -> "succ:" + terminalFlowCicLevelIdText level
            | TerminalFlowCicLevelMax levels -> "max:" + (levels |> List.map terminalFlowCicLevelIdText |> String.concat ",")
            | TerminalFlowCicLevelIMax(left, right) -> "imax:" + terminalFlowCicLevelIdText left + ":" + terminalFlowCicLevelIdText right
            | TerminalFlowCicLevelParam name -> "param:" + terminalFlowCicUniverseNameText name
            | TerminalFlowCicLevelMeta name -> "meta:" + terminalFlowCicUniverseNameText name

        let private terminalFlowCicTermShapeIdentityText = function
            | TerminalFlowCicSort universe -> "sort:" + terminalFlowCicLevelIdText universe
            | TerminalFlowCicBoundVar(scope, binder) ->
                "bound:" + terminalFlowCicScopeIdText scope + ":" + terminalFlowCicBinderIdText binder
            | TerminalFlowCicLambda(binder, domain, body) ->
                "lambda:" + terminalFlowCicBinderIdText binder + ":" + terminalFlowCicTermIdText domain + ":" + terminalFlowCicTermIdText body
            | TerminalFlowCicPi(binder, domain, codomain) ->
                "pi:" + terminalFlowCicBinderIdText binder + ":" + terminalFlowCicTermIdText domain + ":" + terminalFlowCicTermIdText codomain
            | TerminalFlowCicApp(fn, arg) ->
                "app:" + terminalFlowCicTermIdText fn + ":" + terminalFlowCicTermIdText arg
            | TerminalFlowCicLet(binder, value, body) ->
                "let:" + terminalFlowCicBinderIdText binder + ":" + terminalFlowCicTermIdText value + ":" + terminalFlowCicTermIdText body
            | TerminalFlowCicConst(name, universe) ->
                "const:" + terminalFlowCicConstantNameText name + ":" + (universe |> Option.map terminalFlowCicLevelIdText |> Option.defaultValue "none")
            | TerminalFlowCicMeta name -> "meta:" + terminalFlowCicMetaNameText name

        let private terminalFlowCicLevelInternRequestFor shape =
            let identity = terminalFlowCicLevelShapeIdentityText shape
            let structuralHash = NativeCutoverStableRef.digest64 "cic-level-shape" [identity]
            { requestRef = NativeCutoverStableRef.ref32 "cic-level-intern-request" [string structuralHash]
              shape = shape
              structuralHash = structuralHash }

        let private terminalFlowCicTermInternRequestFor scope shape =
            let identity = terminalFlowCicTermShapeIdentityText shape
            let structuralHash =
                NativeCutoverStableRef.digest64
                    "cic-term-shape"
                    [ terminalFlowCicScopeIdText scope
                      identity ]
            { requestRef = NativeCutoverStableRef.ref32 "cic-term-intern-request" [terminalFlowCicScopeIdText scope; string structuralHash]
              scope = scope
              shape = shape
              structuralHash = structuralHash }

        let private terminalFlowCicAlphaNormalDigestFor scope shape structuralHash =
            TerminalFlowCicAlphaNormalDigest (
                NativeCutoverStableRef.digest64
                    "cic-alpha-normal-shape"
                    [ terminalFlowCicScopeIdText scope
                      terminalFlowCicTermShapeIdentityText shape
                      string structuralHash ])

        let private terminalFlowCicTermInternKeyFor (receipt:TerminalFlowCicTermInternReceipt) =
            { generation = receipt.termId.generation
              scope = receipt.scope
              shapeDigest = terminalFlowCicAlphaNormalDigestFor receipt.scope receipt.shape receipt.structuralHash
              structuralHash = receipt.structuralHash }

        let private terminalFlowCicInternKeyRef (key:TerminalFlowCicTermInternKey) =
            let (TerminalFlowCicAlphaNormalDigest digest) = key.shapeDigest
            NativeCutoverStableRef.digest64
                "cic-intern-key"
                [ string (terminalFlowCicArenaGenerationValue key.generation)
                  terminalFlowCicScopeIdText key.scope
                  string digest
                  string key.structuralHash ]

        let private terminalFlowCicInternTableEmpty =
            { generation = TerminalFlowCicArenaGenerationId 0u
              nextTermSlot = 1u
              nextLevelSlot = 1u
              byKey = Map.empty
              bySlot = Map.empty
              levelsByHash = Map.empty
              levelsBySlot = Map.empty
              conflicts = []
              deterministicSequence = 0L
              exactOnceRef = NativeCutoverStableRef.ref32 "cic-intern-table-empty" ["empty"] }

        let private terminalFlowCicInternTableForGeneration generation =
            { terminalFlowCicInternTableEmpty with
                generation = generation
                exactOnceRef =
                    NativeCutoverStableRef.ref32
                        "cic-intern-table-generation"
                        [ string (terminalFlowCicArenaGenerationValue generation) ] }

        let private terminalFlowCicInternTableInsert receipt table =
            let key = terminalFlowCicTermInternKeyFor receipt
            let keyRef = terminalFlowCicInternKeyRef key
            let slot = terminalFlowCicTermSlot receipt.termId
            match Map.tryFind keyRef table.byKey with
            | Some existing when existing.termId = receipt.termId ->
                table, TerminalFlowCicInternDuplicateReused(key, existing.termId)
            | Some existing ->
                let conflict = TerminalFlowCicInternHashCollision(key, existing.termId, receipt.termId)
                { table with conflicts = conflict :: table.conflicts; deterministicSequence = table.deterministicSequence + 1L }, conflict
            | None ->
                { table with
                    generation = receipt.termId.generation
                    nextTermSlot = max table.nextTermSlot (slot + 1u)
                    byKey = Map.add keyRef receipt table.byKey
                    bySlot = Map.add slot receipt table.bySlot
                    deterministicSequence = table.deterministicSequence + 1L
                    exactOnceRef =
                        NativeCutoverStableRef.ref32
                            "cic-intern-table-insert"
                            [ string table.exactOnceRef
                              string keyRef
                              string slot
                              string (table.deterministicSequence + 1L) ] },
                TerminalFlowCicInternDuplicateReused(key, receipt.termId)

        let private terminalFlowCicInternTableAllocateTerm (request:TerminalFlowCicTermInternRequest) table =
            let candidateId : TerminalFlowCicTermId =
                { generation = table.generation
                  slot = table.nextTermSlot
                  structuralHash = request.structuralHash }
            let candidate =
                { requestRef = request.requestRef
                  termId = candidateId
                  scope = request.scope
                  shape = request.shape
                  structuralHash = request.structuralHash
                  exactOnceRef =
                    NativeCutoverStableRef.ref32
                        "cic-term-intern-receipt"
                        [ string request.requestRef
                          string (terminalFlowCicArenaGenerationValue table.generation)
                          string table.nextTermSlot
                          string request.structuralHash ] }
            let key = terminalFlowCicTermInternKeyFor candidate
            let keyRef = terminalFlowCicInternKeyRef key
            match Map.tryFind keyRef table.byKey with
            | Some existing -> table, existing, TerminalFlowCicInternDuplicateReused(key, existing.termId)
            | None ->
                let next, disposition = terminalFlowCicInternTableInsert candidate table
                next, candidate, disposition

        let private terminalFlowCicLevelInternKeyRef (receipt:TerminalFlowCicLevelInternReceipt) =
            NativeCutoverStableRef.digest64
                "cic-level-intern-key"
                [ string (terminalFlowCicArenaGenerationValue receipt.levelId.generation)
                  string receipt.structuralHash ]

        let private terminalFlowCicInternTableInsertLevel receipt table =
            let keyRef = terminalFlowCicLevelInternKeyRef receipt
            let slot = terminalFlowCicLevelSlot receipt.levelId
            match Map.tryFind keyRef table.levelsByHash with
            | Some existing when existing.levelId = receipt.levelId ->
                table, TerminalFlowCicLevelInternDuplicateReused existing.levelId
            | Some existing ->
                let conflict = TerminalFlowCicLevelInternHashCollision(receipt.structuralHash, existing.levelId, receipt.levelId)
                { table with conflicts = conflict :: table.conflicts; deterministicSequence = table.deterministicSequence + 1L }, conflict
            | None ->
                { table with
                    generation = receipt.levelId.generation
                    nextLevelSlot = max table.nextLevelSlot (slot + 1u)
                    levelsByHash = Map.add keyRef receipt table.levelsByHash
                    levelsBySlot = Map.add slot receipt table.levelsBySlot
                    deterministicSequence = table.deterministicSequence + 1L
                    exactOnceRef =
                        NativeCutoverStableRef.ref32
                            "cic-level-intern-table-insert"
                            [ string table.exactOnceRef
                              string keyRef
                              string slot
                              string (table.deterministicSequence + 1L) ] },
                TerminalFlowCicLevelInternDuplicateReused receipt.levelId

        let private terminalFlowCicInternTableAllocateLevel (request:TerminalFlowCicLevelInternRequest) table =
            let keyRef =
                NativeCutoverStableRef.digest64
                    "cic-level-intern-key"
                    [ string (terminalFlowCicArenaGenerationValue table.generation)
                      string request.structuralHash ]
            match Map.tryFind keyRef table.levelsByHash with
            | Some existing when existing.shape = request.shape ->
                table, existing, TerminalFlowCicLevelInternDuplicateReused existing.levelId
            | Some existing ->
                let attempted : TerminalFlowCicLevelId =
                    { generation = table.generation
                      slot = table.nextLevelSlot
                      structuralHash = request.structuralHash }
                let conflict = TerminalFlowCicLevelInternHashCollision(request.structuralHash, existing.levelId, attempted)
                { table with conflicts = conflict :: table.conflicts; deterministicSequence = table.deterministicSequence + 1L }, existing, conflict
            | None ->
                let levelId : TerminalFlowCicLevelId =
                    { generation = table.generation
                      slot = table.nextLevelSlot
                      structuralHash = request.structuralHash }
                let receipt =
                    { requestRef = request.requestRef
                      levelId = levelId
                      shape = request.shape
                      structuralHash = request.structuralHash
                      exactOnceRef =
                        NativeCutoverStableRef.ref32
                            "cic-level-intern-receipt"
                            [ string request.requestRef
                              string (terminalFlowCicArenaGenerationValue table.generation)
                              string table.nextLevelSlot
                              string request.structuralHash ] }
                let next, disposition = terminalFlowCicInternTableInsertLevel receipt table
                next, receipt, disposition

        let private terminalFlowCicUniverseUnionFindEmpty (ledger:TerminalFlowCicUniverseLedger) =
            { parent = Map.empty
              rank = Map.empty
              acceptedEdges = Map.empty
              edgeStates = Map.empty
              acyclicProofRef =
                  if ledger.unresolved = 0 then
                      Some (NativeCutoverStableRef.ref32 "cic-universe-acyclic" [string ledger.exactOnceRef])
                  else None
              epoch = ledger.unionFindEpoch
              exactOnceRef = NativeCutoverStableRef.ref32 "cic-universe-union-find" [string ledger.exactOnceRef] }

        let private terminalFlowCicUniverseConstraintIdentityText = function
            | TerminalFlowCicUniverseLeq(lower, upper) ->
                "leq:" + terminalFlowCicLevelIdText lower + ":" + terminalFlowCicLevelIdText upper
            | TerminalFlowCicUniverseEq(left, right) ->
                "eq:" + terminalFlowCicLevelIdText left + ":" + terminalFlowCicLevelIdText right
            | TerminalFlowCicUniverseMax(result, operands) ->
                "max:" + terminalFlowCicLevelIdText result + ":" + (operands |> List.map terminalFlowCicLevelIdText |> String.concat ",")

        let private terminalFlowCicUniverseConstraintRef constraint' =
            NativeCutoverStableRef.ref32
                "cic-universe-constraint"
                [ terminalFlowCicUniverseConstraintIdentityText constraint' ]

        let private terminalFlowCicLevelKey (level:TerminalFlowCicLevelId) =
            (uint64 (terminalFlowCicArenaGenerationValue level.generation) <<< 32)
            ||| uint64 level.slot

        let rec private terminalFlowCicUniverseFindRoot parent key =
            match Map.tryFind key parent with
            | Some parentKey when parentKey <> key -> terminalFlowCicUniverseFindRoot parent parentKey
            | _ -> key

        let private terminalFlowCicUniverseUnionEq left right uf =
            let leftKey = terminalFlowCicLevelKey left
            let rightKey = terminalFlowCicLevelKey right
            let parent0 =
                uf.parent
                |> fun parent -> if Map.containsKey leftKey parent then parent else Map.add leftKey leftKey parent
                |> fun parent -> if Map.containsKey rightKey parent then parent else Map.add rightKey rightKey parent
            let leftRoot = terminalFlowCicUniverseFindRoot parent0 leftKey
            let rightRoot = terminalFlowCicUniverseFindRoot parent0 rightKey
            if leftRoot = rightRoot then
                { uf with parent = parent0 }
            else
                let rankValue key =
                    match Map.tryFind key uf.rank with
                    | Some (TerminalFlowCicUniverseUnionRank rank) -> rank
                    | None -> 0
                let leftRank = rankValue leftRoot
                let rightRank = rankValue rightRoot
                if leftRank < rightRank then
                    { uf with parent = Map.add leftRoot rightRoot parent0 }
                elif leftRank > rightRank then
                    { uf with parent = Map.add rightRoot leftRoot parent0 }
                else
                    { uf with
                        parent = Map.add rightRoot leftRoot parent0
                        rank = Map.add leftRoot (TerminalFlowCicUniverseUnionRank (leftRank + 1)) uf.rank }

        let private terminalFlowCicUniverseUnionFindAssert constraint' uf =
            let edgeRef = terminalFlowCicUniverseConstraintRef constraint'
            let unioned =
                match constraint' with
                | TerminalFlowCicUniverseEq(left, right) -> terminalFlowCicUniverseUnionEq left right uf
                | TerminalFlowCicUniverseLeq _
                | TerminalFlowCicUniverseMax _ -> uf
            let nextEpoch = unioned.epoch + 1L
            { unioned with
                acceptedEdges = Map.add edgeRef constraint' unioned.acceptedEdges
                edgeStates = Map.add edgeRef (TerminalFlowCicUniverseEdgeAccepted(edgeRef, nextEpoch)) unioned.edgeStates
                acyclicProofRef =
                    Some (
                        NativeCutoverStableRef.ref32
                            "cic-universe-edge-acyclic"
                            [ string unioned.exactOnceRef
                              string edgeRef
                              string nextEpoch ])
                epoch = nextEpoch
                exactOnceRef =
                    NativeCutoverStableRef.ref32
                        "cic-universe-edge-assert"
                        [ string unioned.exactOnceRef
                          string edgeRef ] }

        let private terminalFlowCicReplayAmplificationInitial =
            { discoveredWork = 0L
              replayedWork = 0L
              allowedRatioMilli = 1000L
              observedRatioMilli = 0L
              debtRef = None }

        let private terminalFlowCicReplayAmplificationObserve discovered replayed budget =
            let ratio = if discovered <= 0L then 0L else (replayed * 1000L) / discovered
            { budget with
                discoveredWork = discovered
                replayedWork = replayed
                observedRatioMilli = ratio
                debtRef =
                    if ratio > budget.allowedRatioMilli then
                        Some (
                            NativeCutoverStableRef.ref32
                                "cic-replay-amplification-debt"
                                [ string discovered
                                  string replayed
                                  string ratio ])
                    else None }

        let private terminalFlowCicSharedSubstrateInitialForGeneration generation ledger =
            { internTable = terminalFlowCicInternTableForGeneration generation
              whnfMemo = Map.empty
              defEqMemo = Map.empty
              universeUnionFind = terminalFlowCicUniverseUnionFindEmpty ledger
              semanticFrontierDigest = None
              replayAmplification = terminalFlowCicReplayAmplificationInitial
              deterministicSequence = 0L
              exactOnceRef = NativeCutoverStableRef.ref32 "shared-cic-substrate" [string (terminalFlowCicArenaGenerationValue generation); string ledger.exactOnceRef] }

        let private terminalFlowCicSharedSubstrateInitial ledger =
            terminalFlowCicSharedSubstrateInitialForGeneration (TerminalFlowCicArenaGenerationId 0u) ledger

        let private terminalFlowCicWhnfPromiseRef term transparency budget =
            terminalFlowMintedRefOf "cic_whnf_promise_ref" (terminalFlowCicTermIdText term + ":" + terminalFlowCicWhnfTransparencyModeText transparency + ":" + string budget)

        let private terminalFlowCicWhnfPromiseKey term transparency budget =
            { input = term
              transparencyMode = transparency
              unfoldingBudget = budget }

        let private terminalFlowCicWhnfPromiseFor term transparency budget waiter =
            let key = terminalFlowCicWhnfPromiseKey term transparency budget
            { promiseRef = terminalFlowCicWhnfPromiseRef term transparency budget
              key = key
              waiters = [ waiter ]
              state = TerminalFlowCicWhnfPromiseUnforced }

        let private terminalFlowCicCongruenceClosureEdgeFor
            (key:TerminalFlowCicDefEqKey)
            (witness:TerminalFlowCicDefEqWitness)
            (witnessRef:TerminalFlowIdentityRef<TerminalFlowCicDefEqWitnessRefKind>)
            sequence
            : TerminalFlowCicCongruenceClosureEdge =
            let edgeRef = terminalFlowMintedRefOf "cic_congruence_edge" (string sequence + ":" + terminalFlowIdentityRefText witnessRef)
            { edgeRef = edgeRef
              left = key.left
              right = key.right
              witness = witness
              witnessRef = witnessRef
              exactOnceRef = terminalFlowMintedRefOf "cic_congruence_exact_once" (string edgeRef + ":" + string sequence) }

        let private terminalFlowCicDefEqKeyRef (key:TerminalFlowCicDefEqKey) =
            NativeCutoverStableRef.ref32
                "cic-defeq-key"
                [ terminalFlowCicTermIdText key.left
                  terminalFlowCicTermIdText key.right
                  terminalFlowCicScopeIdText key.scope
                  string key.universeEpoch ]

        let private terminalFlowCicWorkAuthorityRef label parts =
            CompilerIdentityKernel.ContentDigest.ofText label (String.concat "|" parts)

        let private terminalFlowCicWorkGeneration (state:TerminalFlowCicDefEqActorState) =
            state.substrate.internTable.generation
            |> terminalFlowCicArenaGenerationValue
            |> int64

        let private terminalFlowCicUnitCost : CompilerKernelV2.SemanticCost =
            CompilerKernelV2.Measured.one<CompilerKernelV2.SemanticCostUnit>

        let private terminalFlowCicRetiredRef authorityRef =
            CompilerIdentityKernel.ContentDigest.ofText "cic-work-retired" (CompilerIdentityKernel.ContentDigest.text authorityRef)

        let private terminalFlowCicFailureRef authorityRef reason =
            CompilerIdentityKernel.ContentDigest.ofText "cic-work-failed" (CompilerIdentityKernel.ContentDigest.text authorityRef + "|" + reason)

        let private terminalFlowCicObligationAuthorityRef (key:TerminalFlowCicObligationKey) =
            terminalFlowCicWorkAuthorityRef "cic-obligation-work" [ string key.kindTag; string key.value ]

        let private terminalFlowCicDefinitionAuthorityRef definitionId =
            terminalFlowCicWorkAuthorityRef "cic-definition-work" [ terminalFlowCicDefinitionIdText definitionId ]

        let private terminalFlowCicSemanticWorkMutationsFor step (state:TerminalFlowCicDefEqActorState) =
            let generation = terminalFlowCicWorkGeneration state
            let cost = terminalFlowCicUnitCost
            let retired authorityRef = CompilerKernelV2.WorkUnitRetired(terminalFlowCicRetiredRef authorityRef)
            let defEqIsOpen key =
                state.inFlight |> Map.exists (fun _ request -> request.key = key)
            let whnfIsOpen key =
                let promiseRef = terminalFlowCicWhnfPromiseRef key.input key.transparencyMode key.unfoldingBudget
                match Map.tryFind promiseRef state.substrate.whnfMemo with
                | Some (TerminalFlowCicWhnfMemoPending _) -> true
                | _ ->
                    match Map.tryFind promiseRef state.whnfPromises with
                    | Some promise ->
                        match promise.state with
                        | TerminalFlowCicWhnfPromiseResolved _ -> false
                        | TerminalFlowCicWhnfPromiseUnforced
                        | TerminalFlowCicWhnfPromiseForcing _
                        | TerminalFlowCicWhnfPromiseBlocked _ -> true
                    | None -> false
            let obligationIsOpen key =
                state.openObligations |> List.exists (fun (candidateKey, _) -> candidateKey = key)
            let obligationIsClosed key =
                state.closedObligations |> List.exists (fun (candidateKey, _) -> candidateKey = key)
            let definitionIsKnown definitionId =
                state.definitionJobs |> List.exists (fun (candidateId, _) -> candidateId = definitionId)
            let definitionIsOpen definitionId =
                state.definitionJobs
                |> List.exists (fun (candidateId, job) ->
                    candidateId = definitionId
                    && (match job.state with
                        | TerminalFlowCicDefinitionQueued
                        | TerminalFlowCicDefinitionChecking _ -> true
                        | TerminalFlowCicDefinitionAccepted _
                        | TerminalFlowCicDefinitionRejected _ -> false))
            match step with
            | TerminalFlowCicActorInternTerm request ->
                let authorityRef = terminalFlowCicWorkAuthorityRef "cic-intern-term-work" [ string request.requestRef ]
                let workUnit = CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.CicKernelPhase,CompilerKernelV2.CicInternWorkKind> authorityRef generation
                [ CompilerKernelV2.SemanticWorkAdmit(CompilerKernelV2.SomeCicInternWorkUnit workUnit, cost)
                  CompilerKernelV2.SemanticWorkApply(CompilerKernelV2.SomeCicInternWorkReceipt(CompilerKernelV2.WorkUnitReceipt.create workUnit (retired authorityRef) cost)) ]
            | TerminalFlowCicActorInternLevel request ->
                let authorityRef = terminalFlowCicWorkAuthorityRef "cic-intern-level-work" [ string request.requestRef ]
                let workUnit = CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.CicKernelPhase,CompilerKernelV2.CicInternWorkKind> authorityRef generation
                [ CompilerKernelV2.SemanticWorkAdmit(CompilerKernelV2.SomeCicInternWorkUnit workUnit, cost)
                  CompilerKernelV2.SemanticWorkApply(CompilerKernelV2.SomeCicInternWorkReceipt(CompilerKernelV2.WorkUnitReceipt.create workUnit (retired authorityRef) cost)) ]
            | TerminalFlowCicActorSubmitDefEq request ->
                let memoRef = terminalFlowCicDefEqKeyRef request.key
                let alreadySolved =
                    match Map.tryFind memoRef state.substrate.defEqMemo with
                    | Some (TerminalFlowCicDefEqMemoWitness _) -> true
                    | _ -> false
                if defEqIsOpen request.key || alreadySolved then []
                else
                    let authorityRef = terminalFlowCicWorkAuthorityRef "cic-defeq-work" [ string memoRef ]
                    let workUnit = CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.CicKernelPhase,CompilerKernelV2.DefEqWorkKind> authorityRef generation
                    [ CompilerKernelV2.SemanticWorkAdmit(CompilerKernelV2.SomeCicDefEqWorkUnit workUnit, cost) ]
            | TerminalFlowCicActorCloseDefEqWithWitness(key, _) when defEqIsOpen key ->
                let authorityRef = terminalFlowCicWorkAuthorityRef "cic-defeq-work" [ string (terminalFlowCicDefEqKeyRef key) ]
                let workUnit = CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.CicKernelPhase,CompilerKernelV2.DefEqWorkKind> authorityRef generation
                [ CompilerKernelV2.SemanticWorkApply(CompilerKernelV2.SomeCicDefEqWorkReceipt(CompilerKernelV2.WorkUnitReceipt.create workUnit (retired authorityRef) cost)) ]
            | TerminalFlowCicActorBlockDefEq(key, blocker) when defEqIsOpen key ->
                let authorityRef = terminalFlowCicWorkAuthorityRef "cic-defeq-work" [ string (terminalFlowCicDefEqKeyRef key) ]
                let workUnit = CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.CicKernelPhase,CompilerKernelV2.DefEqWorkKind> authorityRef generation
                let failureRef = terminalFlowCicFailureRef authorityRef (terminalFlowCicBlockerText blocker)
                [ CompilerKernelV2.SemanticWorkApply(CompilerKernelV2.SomeCicDefEqWorkReceipt(CompilerKernelV2.WorkUnitReceipt.create workUnit (CompilerKernelV2.WorkUnitFailed failureRef) cost)) ]
            | TerminalFlowCicActorShareWhnfPromise(key, _) when not (whnfIsOpen key) ->
                let promiseRef = terminalFlowCicWhnfPromiseRef key.input key.transparencyMode key.unfoldingBudget
                let alreadyResolved =
                    match Map.tryFind promiseRef state.substrate.whnfMemo with
                    | Some (TerminalFlowCicWhnfMemoHit _) -> true
                    | _ -> false
                if alreadyResolved then []
                else
                    let authorityRef = terminalFlowCicWorkAuthorityRef "cic-whnf-work" [ string promiseRef ]
                    let workUnit = CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.CicKernelPhase,CompilerKernelV2.CicWhnfWorkKind> authorityRef generation
                    [ CompilerKernelV2.SemanticWorkAdmit(CompilerKernelV2.SomeCicWhnfWorkUnit workUnit, cost) ]
            | TerminalFlowCicActorResolveWhnfPromise(key, _) when whnfIsOpen key ->
                let promiseRef = terminalFlowCicWhnfPromiseRef key.input key.transparencyMode key.unfoldingBudget
                let authorityRef = terminalFlowCicWorkAuthorityRef "cic-whnf-work" [ string promiseRef ]
                let workUnit = CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.CicKernelPhase,CompilerKernelV2.CicWhnfWorkKind> authorityRef generation
                [ CompilerKernelV2.SemanticWorkApply(CompilerKernelV2.SomeCicWhnfWorkReceipt(CompilerKernelV2.WorkUnitReceipt.create workUnit (retired authorityRef) cost)) ]
            | TerminalFlowCicActorAssertUniverseConstraint constraint' ->
                let authorityRef = terminalFlowCicWorkAuthorityRef "cic-universe-work" [ string (terminalFlowCicUniverseConstraintRef constraint') ]
                let workUnit = CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.CicKernelPhase,CompilerKernelV2.CicUniverseWorkKind> authorityRef generation
                [ CompilerKernelV2.SemanticWorkAdmit(CompilerKernelV2.SomeCicUniverseWorkUnit workUnit, cost)
                  CompilerKernelV2.SemanticWorkApply(CompilerKernelV2.SomeCicUniverseWorkReceipt(CompilerKernelV2.WorkUnitReceipt.create workUnit (retired authorityRef) cost)) ]
            | TerminalFlowCicActorOpenObligation obligation when not (obligationIsOpen obligation.ObligationKey) && not (obligationIsClosed obligation.ObligationKey) ->
                let authorityRef = terminalFlowCicObligationAuthorityRef obligation.ObligationKey
                let workUnit = CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.CicKernelPhase,CompilerKernelV2.CicObligationWorkKind> authorityRef generation
                [ CompilerKernelV2.SemanticWorkAdmit(CompilerKernelV2.SomeCicObligationWorkUnit workUnit, cost) ]
            | TerminalFlowCicActorCloseObligation(obligationKey, _, disposition) when obligationIsOpen obligationKey ->
                let authorityRef = terminalFlowCicObligationAuthorityRef obligationKey
                let workUnit = CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.CicKernelPhase,CompilerKernelV2.CicObligationWorkKind> authorityRef generation
                let workDisposition =
                    match disposition with
                    | TerminalFlowCicObligationSolved -> retired authorityRef
                    | TerminalFlowCicObligationRejected reason -> CompilerKernelV2.WorkUnitFailed(terminalFlowCicFailureRef authorityRef (CompilerKernelV2.OperationalReasonIdOps.text reason))
                [ CompilerKernelV2.SemanticWorkApply(CompilerKernelV2.SomeCicObligationWorkReceipt(CompilerKernelV2.WorkUnitReceipt.create workUnit workDisposition cost)) ]
            | TerminalFlowCicActorSubmitDefinition request when not (definitionIsKnown request.definitionId) ->
                let authorityRef = terminalFlowCicDefinitionAuthorityRef request.definitionId
                let workUnit = CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.CicKernelPhase,CompilerKernelV2.CicDeclarationWorkKind> authorityRef generation
                [ CompilerKernelV2.SemanticWorkAdmit(CompilerKernelV2.SomeCicDeclarationWorkUnit workUnit, cost) ]
            | TerminalFlowCicActorCloseDefinition(definitionId, result) when definitionIsOpen definitionId ->
                let authorityRef = terminalFlowCicDefinitionAuthorityRef definitionId
                let workUnit = CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.CicKernelPhase,CompilerKernelV2.CicDeclarationWorkKind> authorityRef generation
                let disposition =
                    match result with
                    | TerminalFlowCicDefinitionCheckAccepted _ -> retired authorityRef
                    | TerminalFlowCicDefinitionCheckRejected blocker -> CompilerKernelV2.WorkUnitFailed(terminalFlowCicFailureRef authorityRef (terminalFlowCicBlockerText blocker))
                [ CompilerKernelV2.SemanticWorkApply(CompilerKernelV2.SomeCicDeclarationWorkReceipt(CompilerKernelV2.WorkUnitReceipt.create workUnit disposition cost)) ]
            | TerminalFlowCicActorCloseDefEqWithWitness _
            | TerminalFlowCicActorBlockDefEq _
            | TerminalFlowCicActorShareWhnfPromise _
            | TerminalFlowCicActorResolveWhnfPromise _
            | TerminalFlowCicActorOpenObligation _
            | TerminalFlowCicActorCloseObligation _
            | TerminalFlowCicActorSubmitDefinition _
            | TerminalFlowCicActorCloseDefinition _
            | TerminalFlowCicActorCloseUniverseOwner _
            | TerminalFlowCicActorSealFrontierDigest _
            | TerminalFlowCicActorObserveReplayAmplification _
            | TerminalFlowCicActorObserveNativeCounters _ -> []

        let private terminalFlowCicApplySemanticWorkMutations mutations =
            let authoritativeLedger, conflicts =
                CompilerKernelV2.SemanticWorkLedgerAuthority.transactMany mutations
            authoritativeLedger,
            CompilerKernelV2.Measured.ofInt<CompilerKernelV2.NodeCountUnit> "semanticWorkConflictCount" conflicts.Length


        let private terminalFlowCicDefEqActorApply step (state:TerminalFlowCicDefEqActorState) =
            let nextSeq = state.deterministicSequence + 1L
            let workMutations = terminalFlowCicSemanticWorkMutationsFor step state
            let nextWorkLedger, workConflictCount =
                terminalFlowCicApplySemanticWorkMutations workMutations
            let nextState =
                match step with
                | TerminalFlowCicActorInternTerm request ->
                    let table, _, conflict = terminalFlowCicInternTableAllocateTerm request state.substrate.internTable
                    let conflictBump : CompilerKernelV2.NodeCount =
                        match conflict with
                        | TerminalFlowCicInternHashCollision _
                        | TerminalFlowCicLevelInternHashCollision _ -> CompilerKernelV2.Measured.one
                        | TerminalFlowCicInternDuplicateReused _
                        | TerminalFlowCicLevelInternDuplicateReused _ -> CompilerKernelV2.Measured.zero
                    { state with
                        substrate = { state.substrate with internTable = table; deterministicSequence = state.substrate.deterministicSequence + 1L }
                        internReuseCount = CompilerKernelV2.Measured.increment state.internReuseCount
                        determinismViolationCount = CompilerKernelV2.Measured.add state.determinismViolationCount conflictBump
                        deterministicSequence = nextSeq }
                | TerminalFlowCicActorInternLevel request ->
                    let table, _, conflict = terminalFlowCicInternTableAllocateLevel request state.substrate.internTable
                    let conflictBump : CompilerKernelV2.NodeCount =
                        match conflict with
                        | TerminalFlowCicLevelInternHashCollision _ -> CompilerKernelV2.Measured.one
                        | TerminalFlowCicLevelInternDuplicateReused _ -> CompilerKernelV2.Measured.zero
                        | _ -> CompilerKernelV2.Measured.zero
                    { state with
                        substrate = { state.substrate with internTable = table; deterministicSequence = state.substrate.deterministicSequence + 1L }
                        internReuseCount = CompilerKernelV2.Measured.increment state.internReuseCount
                        determinismViolationCount = CompilerKernelV2.Measured.add state.determinismViolationCount conflictBump
                        deterministicSequence = nextSeq }
                | TerminalFlowCicActorSubmitDefEq request ->
                    let memoRef = terminalFlowCicDefEqKeyRef request.key
                    let alreadyInFlight = state.inFlight |> Map.exists (fun _ existing -> existing.key = request.key)
                    let alreadySolved =
                        match Map.tryFind memoRef state.substrate.defEqMemo with
                        | Some (TerminalFlowCicDefEqMemoWitness _) -> true
                        | _ ->
                            state.solved
                            |> Map.exists (fun _ entry ->
                                match entry with
                                | TerminalFlowCicDefEqWitnessed(key, _, _) -> key = request.key
                                | _ -> false)
                    if alreadySolved then
                        { state with
                            memoHitCount = CompilerKernelV2.Measured.increment state.memoHitCount
                            deterministicSequence = nextSeq }
                    elif alreadyInFlight then
                        { state with
                            duplicateRequestCount = CompilerKernelV2.Measured.increment state.duplicateRequestCount
                            deterministicSequence = nextSeq }
                    else
                        let nextInFlight = Map.add request.requestRef request state.inFlight
                        let nextMemo = Map.add memoRef (TerminalFlowCicDefEqMemoPending(request.key, request.requestRef)) state.substrate.defEqMemo
                        { state with
                            substrate = { state.substrate with defEqMemo = nextMemo; deterministicSequence = state.substrate.deterministicSequence + 1L }
                            inFlight = nextInFlight
                            maxObservedInFlight =
                                CompilerKernelV2.Measured.maxValue
                                    state.maxObservedInFlight
                                    (CompilerKernelV2.Measured.ofInt<CompilerKernelV2.NodeCountUnit> "maxObservedInFlight" nextInFlight.Count)
                            deterministicSequence = nextSeq }
                | TerminalFlowCicActorShareWhnfPromise(key, waiter) ->
                    let promiseRef = terminalFlowCicWhnfPromiseRef key.input key.transparencyMode key.unfoldingBudget
                    let promise =
                        match Map.tryFind promiseRef state.whnfPromises with
                        | Some existing -> { existing with waiters = waiter :: existing.waiters }
                        | None -> { promiseRef = promiseRef; key = key; waiters = [ waiter ]; state = TerminalFlowCicWhnfPromiseForcing 1 }
                    let whnfMemo =
                        match Map.tryFind promiseRef state.substrate.whnfMemo with
                        | Some (TerminalFlowCicWhnfMemoHit _) -> state.substrate.whnfMemo
                        | _ -> Map.add promiseRef (TerminalFlowCicWhnfMemoPending(key, promiseRef)) state.substrate.whnfMemo
                    { state with
                        substrate = { state.substrate with whnfMemo = whnfMemo; deterministicSequence = state.substrate.deterministicSequence + 1L }
                        whnfPromises = Map.add promiseRef promise state.whnfPromises
                        promiseShareCount = CompilerKernelV2.Measured.increment state.promiseShareCount
                        deterministicSequence = nextSeq }
                | TerminalFlowCicActorResolveWhnfPromise(key, receipt) ->
                    let promiseRef = terminalFlowCicWhnfPromiseRef key.input key.transparencyMode key.unfoldingBudget
                    let isPending =
                        match Map.tryFind promiseRef state.substrate.whnfMemo with
                        | Some (TerminalFlowCicWhnfMemoPending _) -> true
                        | _ -> false
                    if not isPending then
                        { state with
                            duplicateRequestCount = CompilerKernelV2.Measured.increment state.duplicateRequestCount
                            deterministicSequence = nextSeq }
                    else
                        let promise =
                            match Map.tryFind promiseRef state.whnfPromises with
                            | Some existing -> { existing with state = TerminalFlowCicWhnfPromiseResolved receipt }
                            | None -> { promiseRef = promiseRef; key = key; waiters = []; state = TerminalFlowCicWhnfPromiseResolved receipt }
                        { state with
                            substrate =
                                { state.substrate with
                                    whnfMemo = Map.add promiseRef (TerminalFlowCicWhnfMemoHit(key, receipt)) state.substrate.whnfMemo
                                    deterministicSequence = state.substrate.deterministicSequence + 1L }
                            whnfPromises = Map.add promiseRef promise state.whnfPromises
                            deterministicSequence = nextSeq }
                | TerminalFlowCicActorCloseDefEqWithWitness(key, edge) ->
                    let isPending = state.inFlight |> Map.exists (fun _ request -> request.key = key)
                    if not isPending then
                        { state with
                            duplicateRequestCount = CompilerKernelV2.Measured.increment state.duplicateRequestCount
                            deterministicSequence = nextSeq }
                    else
                        let ledgerEntry = TerminalFlowCicDefEqWitnessed(key, edge.witnessRef, edge.witness)
                        let memoRef = terminalFlowCicDefEqKeyRef key
                        { state with
                            substrate =
                                { state.substrate with
                                    defEqMemo = Map.add memoRef (TerminalFlowCicDefEqMemoWitness(key, edge)) state.substrate.defEqMemo
                                    deterministicSequence = state.substrate.deterministicSequence + 1L }
                            inFlight = state.inFlight |> Map.filter (fun _ request -> request.key <> key)
                            solved = Map.add edge.edgeRef ledgerEntry state.solved
                            congruenceEdges = Map.add edge.edgeRef edge state.congruenceEdges
                            congruenceClosureEpoch = state.congruenceClosureEpoch + 1L
                            deterministicSequence = nextSeq }
                | TerminalFlowCicActorBlockDefEq(key, blocker) ->
                    let isPending = state.inFlight |> Map.exists (fun _ request -> request.key = key)
                    if not isPending then
                        { state with
                            duplicateRequestCount = CompilerKernelV2.Measured.increment state.duplicateRequestCount
                            deterministicSequence = nextSeq }
                    else
                        let blockedRef = terminalFlowMintedRefOf "cic_defeq_blocked" (string nextSeq)
                        let memoRef = terminalFlowCicDefEqKeyRef key
                        { state with
                            substrate =
                                { state.substrate with
                                    defEqMemo = Map.add memoRef (TerminalFlowCicDefEqMemoBlocked(key, blocker)) state.substrate.defEqMemo
                                    deterministicSequence = state.substrate.deterministicSequence + 1L }
                            inFlight = state.inFlight |> Map.filter (fun _ request -> request.key <> key)
                            blocked = Map.add blockedRef blocker state.blocked
                            deterministicSequence = nextSeq }
                | TerminalFlowCicActorAssertUniverseConstraint constraint' ->
                    let uf = terminalFlowCicUniverseUnionFindAssert constraint' state.substrate.universeUnionFind
                    { state with
                        substrate = { state.substrate with universeUnionFind = uf; deterministicSequence = state.substrate.deterministicSequence + 1L }
                        universeUnionCount = CompilerKernelV2.Measured.increment state.universeUnionCount
                        deterministicSequence = nextSeq }
                | TerminalFlowCicActorCloseUniverseOwner(ledger, receipt) ->
                    let ownerRef = ledger.exactOnceRef
                    let uf = terminalFlowCicUniverseUnionFindEmpty ledger
                    { state with
                        substrate = { state.substrate with universeUnionFind = uf; deterministicSequence = state.substrate.deterministicSequence + 1L }
                        universeOwners = Map.add ownerRef (TerminalFlowCicUniverseOwnerClosed(receipt, ledger)) state.universeOwners
                        deterministicSequence = nextSeq }
                | TerminalFlowCicActorSealFrontierDigest digest ->
                    let violation : CompilerKernelV2.NodeCount =
                        match state.substrate.semanticFrontierDigest with
                        | Some existing when existing <> digest -> CompilerKernelV2.Measured.one
                        | _ -> CompilerKernelV2.Measured.zero
                    { state with
                        substrate = { state.substrate with semanticFrontierDigest = Some digest; deterministicSequence = state.substrate.deterministicSequence + 1L }
                        determinismViolationCount = CompilerKernelV2.Measured.add state.determinismViolationCount violation
                        deterministicSequence = nextSeq }
                | TerminalFlowCicActorObserveReplayAmplification(discovered, replayed) ->
                    let replay = terminalFlowCicReplayAmplificationObserve discovered replayed state.substrate.replayAmplification
                    { state with
                        substrate = { state.substrate with replayAmplification = replay; deterministicSequence = state.substrate.deterministicSequence + 1L }
                        replayAmplificationDebtCount =
                            if replay.debtRef.IsSome then CompilerKernelV2.Measured.increment state.replayAmplificationDebtCount
                            else state.replayAmplificationDebtCount
                        deterministicSequence = nextSeq }
                | TerminalFlowCicActorObserveNativeCounters counters ->
                    { state with nativeCounters = counters; deterministicSequence = nextSeq }
                | TerminalFlowCicActorOpenObligation obligation ->
                    let key = obligation.ObligationKey
                    let alreadyOpen = state.openObligations |> List.exists (fun (candidateKey, _) -> candidateKey = key)
                    let alreadyClosed = state.closedObligations |> List.exists (fun (candidateKey, _) -> candidateKey = key)
                    if alreadyOpen || alreadyClosed then
                        { state with
                            duplicateRequestCount = CompilerKernelV2.Measured.increment state.duplicateRequestCount
                            deterministicSequence = nextSeq }
                    else
                        { state with
                            openObligations = (key, obligation) :: state.openObligations
                            maxObservedInFlight =
                                CompilerKernelV2.Measured.maxValue
                                    state.maxObservedInFlight
                                    (CompilerKernelV2.Measured.ofInt<CompilerKernelV2.NodeCountUnit> "maxObservedInFlight" (List.length state.openObligations + 1))
                            deterministicSequence = nextSeq }
                | TerminalFlowCicActorCloseObligation(obligationKey, closeReceiptRef, disposition) ->
                    let existing =
                        state.openObligations
                        |> List.tryPick (fun (candidateKey, obligation) -> if candidateKey = obligationKey then Some obligation else None)
                    match existing with
                    | None ->
                        { state with
                            duplicateRequestCount = CompilerKernelV2.Measured.increment state.duplicateRequestCount
                            deterministicSequence = nextSeq }
                    | Some obligation ->
                        let receipt =
                            { obligation = obligation
                              closeReceiptRef = closeReceiptRef
                              disposition = disposition
                              closedAtSequence = nextSeq }
                        let retainedOpen = state.openObligations |> List.filter (fun (candidateKey, _) -> candidateKey <> obligationKey)
                        let retainedClosed = state.closedObligations |> List.filter (fun (candidateKey, _) -> candidateKey <> obligationKey)
                        { state with
                            openObligations = retainedOpen
                            closedObligations = (obligationKey, receipt) :: retainedClosed
                            deterministicSequence = nextSeq }
                | TerminalFlowCicActorSubmitDefinition request ->
                    let alreadyPresent =
                        state.definitionJobs
                        |> List.exists (fun (definitionId, _) -> definitionId = request.definitionId)
                    if alreadyPresent then
                        { state with
                            duplicateRequestCount = CompilerKernelV2.Measured.increment state.duplicateRequestCount
                            deterministicSequence = nextSeq }
                    else
                        let job : TerminalFlowCicDefinitionCheckJob =
                            { request = request
                              state = TerminalFlowCicDefinitionQueued }
                        { state with
                            definitionJobs = (request.definitionId, job) :: state.definitionJobs
                            maxObservedInFlight =
                                CompilerKernelV2.Measured.maxValue
                                    state.maxObservedInFlight
                                    (CompilerKernelV2.Measured.ofInt<CompilerKernelV2.NodeCountUnit> "maxObservedInFlight" (List.length state.definitionJobs + 1))
                            deterministicSequence = nextSeq }
                | TerminalFlowCicActorCloseDefinition(definitionId, result) ->
                    let existing =
                        state.definitionJobs
                        |> List.tryPick (fun (candidateId, job) -> if candidateId = definitionId then Some job else None)
                    match existing with
                    | None ->
                        { state with
                            duplicateRequestCount = CompilerKernelV2.Measured.increment state.duplicateRequestCount
                            deterministicSequence = nextSeq }
                    | Some job ->
                        match job.state with
                        | TerminalFlowCicDefinitionAccepted _
                        | TerminalFlowCicDefinitionRejected _ ->
                            { state with
                                duplicateRequestCount = CompilerKernelV2.Measured.increment state.duplicateRequestCount
                                deterministicSequence = nextSeq }
                        | TerminalFlowCicDefinitionQueued
                        | TerminalFlowCicDefinitionChecking _ ->
                            let finalState, accepted =
                                match result with
                                | TerminalFlowCicDefinitionCheckAccepted receipt -> TerminalFlowCicDefinitionAccepted receipt, true
                                | TerminalFlowCicDefinitionCheckRejected blocker -> TerminalFlowCicDefinitionRejected blocker, false
                            let closedJob = { job with state = finalState }
                            let retained = state.definitionJobs |> List.filter (fun (candidateId, _) -> candidateId <> definitionId)
                            { state with
                                definitionJobs = (definitionId, closedJob) :: retained
                                declarationReceiptCount =
                                    if accepted then CompilerKernelV2.Measured.increment state.declarationReceiptCount
                                    else state.declarationReceiptCount
                                deterministicSequence = nextSeq }
            let progress =
                CompilerKernelV2.SemanticWorkLedger.project
                    CompilerKernelV2.ProgressDenominatorClosed
                    nextWorkLedger
            { nextState with
                completedCost = progress.completedCost
                determinismViolationCount = CompilerKernelV2.Measured.add nextState.determinismViolationCount workConflictCount }

        let private terminalFlowCicDefEqActorInitialForGeneration generation ledger =
            { substrate = terminalFlowCicSharedSubstrateInitialForGeneration generation ledger
              congruenceClosureEpoch = 0L
              inFlight = Map.empty
              solved = Map.empty
              blocked = Map.empty
              whnfPromises = Map.empty
              congruenceEdges = Map.empty
              universeOwners = Map.empty
              openObligations = []
              closedObligations = []
              definitionJobs = []
              nativeCounters = nativeCutoverCicKernelCountersZero
              declarationReceiptCount = CompilerKernelV2.Measured.zero
              deterministicSequence = 0L
              completedCost = CompilerKernelV2.Measured.zero
              memoHitCount = CompilerKernelV2.Measured.zero
              duplicateRequestCount = CompilerKernelV2.Measured.zero
              promiseShareCount = CompilerKernelV2.Measured.zero
              internReuseCount = CompilerKernelV2.Measured.zero
              universeUnionCount = CompilerKernelV2.Measured.zero
              replayAmplificationDebtCount = CompilerKernelV2.Measured.zero
              determinismViolationCount = CompilerKernelV2.Measured.zero
              maxObservedInFlight = CompilerKernelV2.Measured.zero }


        let private terminalFlowCicEmptyUniverseLedger =
            { constraints = []; unionFindEpoch = 0L; unresolved = 0; exactOnceRef = NativeCutoverStableRef.ref32 "cic-empty-universe-ledger" ["empty"] }


        type TerminalFlowCicOwnedActorLifecycle =
                | TerminalFlowCicActorDetached
                | TerminalFlowCicActorRunning of owner:TerminalFlowCicArenaOwnerCapability<TerminalFlowCicArenaOwnedStage> * actor:TerminalFlowCicDefEqActorState
                | TerminalFlowCicActorClosing of owner:TerminalFlowCicArenaOwnerCapability<TerminalFlowCicArenaClosingStage> * actor:TerminalFlowCicDefEqActorState
                | TerminalFlowCicActorClosed of owner:TerminalFlowCicArenaOwnerCapability<TerminalFlowCicArenaClosedStage> * actor:TerminalFlowCicDefEqActorState * certificate:TerminalFlowCicKernelQuiescenceCertificate

        type TerminalFlowCicOwnerClaimDecision =
            | TerminalFlowCicOwnerClaimed of TerminalFlowCicOwnedActorLifecycle
            | TerminalFlowCicOwnerReused of TerminalFlowCicOwnedActorLifecycle
            | TerminalFlowCicOwnerClaimRejectedActiveOwner of currentOwner:CompilerKernelV2.NonZeroRef<TerminalFlowCicArenaOwnerRefKind> * incomingOwner:CompilerKernelV2.NonZeroRef<TerminalFlowCicArenaOwnerRefKind> * TerminalFlowCicOwnedActorLifecycle

        type TerminalFlowCicOwnedActorStepDecision =
            | TerminalFlowCicOwnedActorStepApplied of stepKind:TerminalFlowCicActorStepKindId * TerminalFlowCicOwnedActorLifecycle
            | TerminalFlowCicOwnedActorStepRejectedNotRunning of stepKind:TerminalFlowCicActorStepKindId * TerminalFlowCicOwnedActorLifecycle
            | TerminalFlowCicOwnedActorStepRejectedOwnerConflict of stepKind:TerminalFlowCicActorStepKindId * currentOwner:CompilerKernelV2.NonZeroRef<TerminalFlowCicArenaOwnerRefKind> * incomingOwner:CompilerKernelV2.NonZeroRef<TerminalFlowCicArenaOwnerRefKind> * TerminalFlowCicOwnedActorLifecycle

        type TerminalFlowCicOwnedActorCloseDecision =
            | TerminalFlowCicOwnedActorCloseCommitted of TerminalFlowCicOwnedActorLifecycle * TerminalFlowCicKernelQuiescenceCertificate
            | TerminalFlowCicOwnedActorCloseBlocked of TerminalFlowCicOwnedActorLifecycle * TerminalFlowCicKernelQuiescenceViolation list
            | TerminalFlowCicOwnedActorCloseRejectedOwnerConflict of currentOwner:CompilerKernelV2.NonZeroRef<TerminalFlowCicArenaOwnerRefKind> * incomingOwner:CompilerKernelV2.NonZeroRef<TerminalFlowCicArenaOwnerRefKind> * TerminalFlowCicOwnedActorLifecycle

        let private terminalFlowCicArenaCapabilityRestage (capability:TerminalFlowCicArenaOwnerCapability<'Stage>) : TerminalFlowCicArenaOwnerCapability<'NextStage> =
            { ownerRef = capability.ownerRef
              arenaRef = capability.arenaRef
              generation = capability.generation
              exactOnceRef = capability.exactOnceRef }

        let private terminalFlowCicOwnedActorClaim (ownerRef:CompilerKernelV2.NonZeroRef<TerminalFlowCicArenaOwnerRefKind>) lifecycle =
            let ownerActorRef = CompilerKernelV2.NonZeroRef.value ownerRef
            match lifecycle with
            | TerminalFlowCicActorDetached ->
                let generation = TerminalFlowCicArenaGenerationId 1u
                let arenaRef : TerminalFlowIdentityRef<TerminalFlowCicArenaRefKind> =
                    terminalFlowIdentityRefOfText (sprintf "cic-arena:owner:%u:g:1" ownerActorRef)
                let capability : TerminalFlowCicArenaOwnerCapability<TerminalFlowCicArenaOwnedStage> =
                    { ownerRef = ownerRef
                      arenaRef = arenaRef
                      generation = generation
                      exactOnceRef = terminalFlowMintedRefOf "cic_arena_owner_capability" (sprintf "%u:1" ownerActorRef) }
                TerminalFlowCicOwnerClaimed(TerminalFlowCicActorRunning(capability, terminalFlowCicDefEqActorInitialForGeneration generation terminalFlowCicEmptyUniverseLedger))
            | TerminalFlowCicActorRunning(capability, _) when capability.ownerRef = ownerRef ->
                TerminalFlowCicOwnerReused lifecycle
            | TerminalFlowCicActorClosing(capability, _) when capability.ownerRef = ownerRef ->
                TerminalFlowCicOwnerReused lifecycle
            | TerminalFlowCicActorClosed(capability, _, _) when capability.ownerRef = ownerRef ->
                TerminalFlowCicOwnerReused lifecycle
            | TerminalFlowCicActorRunning(capability, _) ->
                TerminalFlowCicOwnerClaimRejectedActiveOwner(capability.ownerRef, ownerRef, lifecycle)
            | TerminalFlowCicActorClosing(capability, _) ->
                TerminalFlowCicOwnerClaimRejectedActiveOwner(capability.ownerRef, ownerRef, lifecycle)
            | TerminalFlowCicActorClosed(capability, _, _) ->
                TerminalFlowCicOwnerClaimRejectedActiveOwner(capability.ownerRef, ownerRef, lifecycle)

        let private terminalFlowCicOwnedActorApply step lifecycle =
            match lifecycle with
            | TerminalFlowCicActorRunning(capability, actor) ->
                TerminalFlowCicActorRunning(capability, terminalFlowCicDefEqActorApply step actor)
            | TerminalFlowCicActorDetached
            | TerminalFlowCicActorClosing _
            | TerminalFlowCicActorClosed _ -> lifecycle

        let private terminalFlowCicOwnedActorStepFor ownerActorRef step lifecycle =
            let stepKind = terminalFlowCicActorStepKind step
            match terminalFlowCicOwnedActorClaim ownerActorRef lifecycle with
            | TerminalFlowCicOwnerClaimed claimed
            | TerminalFlowCicOwnerReused claimed ->
                match claimed with
                | TerminalFlowCicActorRunning _ ->
                    TerminalFlowCicOwnedActorStepApplied(stepKind, terminalFlowCicOwnedActorApply step claimed)
                | _ -> TerminalFlowCicOwnedActorStepRejectedNotRunning(stepKind, claimed)
            | TerminalFlowCicOwnerClaimRejectedActiveOwner(currentOwner, incomingOwner, retained) ->
                TerminalFlowCicOwnedActorStepRejectedOwnerConflict(stepKind, currentOwner, incomingOwner, retained)

        let private terminalFlowCicOwnedActorCloseFor ownerActorRef lifecycle =
            match terminalFlowCicOwnedActorClaim ownerActorRef lifecycle with
            | TerminalFlowCicOwnerClaimRejectedActiveOwner(currentOwner, incomingOwner, retained) ->
                TerminalFlowCicOwnedActorCloseRejectedOwnerConflict(currentOwner, incomingOwner, retained)
            | TerminalFlowCicOwnerClaimed claimed
            | TerminalFlowCicOwnerReused claimed ->
                match claimed with
                | TerminalFlowCicActorRunning(capability, actor) ->
                    match terminalFlowCicActorQuiescenceFor actor with
                    | Ok certificate ->
                        let closing : TerminalFlowCicArenaOwnerCapability<TerminalFlowCicArenaClosingStage> = terminalFlowCicArenaCapabilityRestage capability
                        let closed : TerminalFlowCicArenaOwnerCapability<TerminalFlowCicArenaClosedStage> = terminalFlowCicArenaCapabilityRestage closing
                        let lifecycle = TerminalFlowCicActorClosed(closed, actor, certificate)
                        TerminalFlowCicOwnedActorCloseCommitted(lifecycle, certificate)
                    | Error violations -> TerminalFlowCicOwnedActorCloseBlocked(claimed, violations)
                | TerminalFlowCicActorClosed(_, _, certificate) -> TerminalFlowCicOwnedActorCloseCommitted(claimed, certificate)
                | TerminalFlowCicActorDetached
                | TerminalFlowCicActorClosing _ -> TerminalFlowCicOwnedActorCloseBlocked(claimed, [])

        let private terminalFlowCicOwnedActorCountersFor (capability:TerminalFlowCicArenaOwnerCapability<'Stage>) (actor:TerminalFlowCicDefEqActorState) =
            let pendingWhnf =
                actor.whnfPromises
                |> Map.toSeq
                |> Seq.filter (fun (_, promise) -> match promise.state with | TerminalFlowCicWhnfPromiseResolved _ -> false | _ -> true)
                |> Seq.length
            let openUniverse =
                actor.universeOwners
                |> Map.toSeq
                |> Seq.filter (fun (_, owner) -> match owner with | TerminalFlowCicUniverseOwnerOpen _ -> true | _ -> false)
                |> Seq.length
            let ownedActive = List.length actor.openObligations + actor.inFlight.Count + pendingWhnf + openUniverse
            { arenaRef = capability.arenaRef
              owner = TerminalFlowCicArenaOwned capability.ownerRef
              termCount = CompilerKernelV2.Measured.ofInt<CompilerKernelV2.NodeCountUnit> "termCount" actor.substrate.internTable.bySlot.Count
              levelCount = CompilerKernelV2.Measured.ofInt<CompilerKernelV2.NodeCountUnit> "levelCount" actor.substrate.internTable.levelsBySlot.Count
              whnfCacheHits = actor.memoHitCount
              whnfCacheMisses =
                CompilerKernelV2.Measured.create<CompilerKernelV2.NodeCountUnit>
                    "whnfCacheMisses"
                    (max 0L (int64 actor.substrate.whnfMemo.Count - CompilerKernelV2.Measured.value actor.memoHitCount))
              defEqSolvedCount = CompilerKernelV2.Measured.ofInt<CompilerKernelV2.NodeCountUnit> "defEqSolvedCount" actor.solved.Count
              defEqFailedCount = CompilerKernelV2.Measured.ofInt<CompilerKernelV2.NodeCountUnit> "defEqFailedCount" actor.blocked.Count
              universeSolverIterations = actor.universeUnionCount
              obligationCount = CompilerKernelV2.Measured.ofInt<CompilerKernelV2.NodeCountUnit> "obligationCount" ownedActive
              activeWorkers = CompilerKernelV2.Measured.ofInt<CompilerKernelV2.WorkerCountUnit> "activeWorkers" ownedActive }

        let private terminalFlowCicOwnedActorCounters lifecycle =
            match lifecycle with
            | TerminalFlowCicActorDetached -> terminalFlowCicDormantCounters ()
            | TerminalFlowCicActorRunning(capability, actor) -> terminalFlowCicOwnedActorCountersFor capability actor
            | TerminalFlowCicActorClosing(capability, actor) -> terminalFlowCicOwnedActorCountersFor capability actor
            | TerminalFlowCicActorClosed(capability, actor, _) ->
                let counters = terminalFlowCicOwnedActorCountersFor capability actor
                { counters with obligationCount = CompilerKernelV2.Measured.zero; activeWorkers = CompilerKernelV2.Measured.zero }

        let private terminalFlowCicOwnedActorCompletedCost = function
                | TerminalFlowCicActorDetached -> CompilerKernelV2.Measured.zero<CompilerKernelV2.SemanticCostUnit>
                | TerminalFlowCicActorRunning(_, actor)
                | TerminalFlowCicActorClosing(_, actor)
                | TerminalFlowCicActorClosed(_, actor, _) -> actor.completedCost

        let private terminalFlowCicOwnedActorState = function
                | TerminalFlowCicActorDetached -> None
                | TerminalFlowCicActorRunning(_, actor)
                | TerminalFlowCicActorClosing(_, actor)
                | TerminalFlowCicActorClosed(_, actor, _) -> Some actor

        let private terminalFlowCicOwnedActorQuiescenceCertificate = function
            | TerminalFlowCicActorClosed(_, _, certificate) -> Some certificate
            | _ -> None

        let private terminalFlowCicOwnedActorProjectionGate = obj()
        let mutable private terminalFlowCicOwnedActorProjection = TerminalFlowCicActorDetached
        do terminalFlowCicOwnedActorCountersBridge <- (fun () -> lock terminalFlowCicOwnedActorProjectionGate (fun () -> terminalFlowCicOwnedActorCounters terminalFlowCicOwnedActorProjection))

        let private terminalFlowCicOwnedActorPublishProjection lifecycle =
            lock terminalFlowCicOwnedActorProjectionGate (fun () -> terminalFlowCicOwnedActorProjection <- lifecycle)

        let private terminalFlowCicOwnedActorLifecycleStageText = function
                | TerminalFlowCicActorDetached -> "detached"
                | TerminalFlowCicActorRunning _ -> "running"
                | TerminalFlowCicActorClosing _ -> "closing"
                | TerminalFlowCicActorClosed _ -> "closed"

        let private terminalFlowCicOwnedActorStepDecisionLifecycle = function
            | TerminalFlowCicOwnedActorStepApplied(_, lifecycle)
            | TerminalFlowCicOwnedActorStepRejectedNotRunning(_, lifecycle)
            | TerminalFlowCicOwnedActorStepRejectedOwnerConflict(_, _, _, lifecycle) -> lifecycle

        let private terminalFlowCicOwnedActorStepDecisionText = function
            | TerminalFlowCicOwnedActorStepApplied(kind, _) -> "applied:" + terminalFlowCicActorStepKindText kind
            | TerminalFlowCicOwnedActorStepRejectedNotRunning(kind, _) -> "rejected_not_running:" + terminalFlowCicActorStepKindText kind
            | TerminalFlowCicOwnedActorStepRejectedOwnerConflict(kind, currentOwner, incomingOwner, _) ->
                FastRuntimeFormat.format "rejected_owner_conflict:%s:%u:%u" [| box (terminalFlowCicActorStepKindText kind); box (CompilerKernelV2.NonZeroRef.value currentOwner); box (CompilerKernelV2.NonZeroRef.value incomingOwner) |]

        let private terminalFlowCicOwnedActorCloseDecisionLifecycle = function
            | TerminalFlowCicOwnedActorCloseCommitted(lifecycle, _)
            | TerminalFlowCicOwnedActorCloseBlocked(lifecycle, _)
            | TerminalFlowCicOwnedActorCloseRejectedOwnerConflict(_, _, lifecycle) -> lifecycle

        let private terminalFlowCicOwnedActorCloseDecisionText = function
            | TerminalFlowCicOwnedActorCloseCommitted _ -> "closed"
            | TerminalFlowCicOwnedActorCloseBlocked(_, violations) ->
                "blocked:" + (violations |> List.map terminalFlowCicKernelQuiescenceViolationText |> String.concat "|")
            | TerminalFlowCicOwnedActorCloseRejectedOwnerConflict(currentOwner, incomingOwner, _) ->
                FastRuntimeFormat.format "rejected_owner_conflict:%u:%u" [| box (CompilerKernelV2.NonZeroRef.value currentOwner); box (CompilerKernelV2.NonZeroRef.value incomingOwner) |]

        let private terminalFlowCicDefEqActorStatsText (state:TerminalFlowCicDefEqActorState) =
            let replayDebt = if state.substrate.replayAmplification.debtRef.IsSome then 1 else 0
            FastRuntimeFormat.format "in_flight=%d|solved=%d|blocked=%d|whnf_promises=%d|whnf_memo=%d|defeq_memo=%d|interned_terms=%d|intern_conflicts=%d|universe_edges=%d|universe_epoch=%d|congruence_edges=%d|universe_owners=%d|memo_hits=%d|duplicate_requests=%d|promise_shares=%d|intern_reuses=%d|universe_unions=%d|determinism_violations=%d|replay_debt=%d|replay_debt_events=%d|max_in_flight=%d|completed_cost=%d|sequence=%d|substrate_sequence=%d" [| box state.inFlight.Count; box state.solved.Count; box state.blocked.Count; box state.whnfPromises.Count; box state.substrate.whnfMemo.Count; box state.substrate.defEqMemo.Count; box state.substrate.internTable.bySlot.Count; box state.substrate.internTable.conflicts.Length; box state.substrate.universeUnionFind.acceptedEdges.Count; box state.substrate.universeUnionFind.epoch; box state.congruenceEdges.Count; box state.universeOwners.Count; box state.memoHitCount; box state.duplicateRequestCount; box state.promiseShareCount; box state.internReuseCount; box state.universeUnionCount; box state.determinismViolationCount; box replayDebt; box state.replayAmplificationDebtCount; box state.maxObservedInFlight; box state.completedCost; box state.deterministicSequence; box state.substrate.deterministicSequence |]

        type TerminalFlowCicKernelProtocol =
            | TerminalFlowCicProtocolDetached
            | TerminalFlowCicProtocolOwned of ownerActorRef:CompilerKernelV2.NonZeroRef<TerminalFlowCicArenaOwnerRefKind> * generation:TerminalFlowCicArenaGenerationId * actorSequence:int64
            | TerminalFlowCicProtocolClosed of ownerActorRef:CompilerKernelV2.NonZeroRef<TerminalFlowCicArenaOwnerRefKind> * certificateRef:uint32
            | TerminalFlowCicProtocolBlocked of blocker:TerminalFlowCicBlocker

        type TerminalFlowCicPromotionRoute =
            | TerminalFlowCicPromotionToArtifactGreenPath of receipt:TerminalFlowIdentityRef<TerminalFlowCicCheckReceiptRefKind>
            | TerminalFlowCicPromotionToTypedFailure of blocker:TerminalFlowCicBlocker
            | TerminalFlowCicPromotionHeldForDependencies of pendingDefinitions:int

        type TerminalFlowCicKernelCorridor = private {
            surface : TerminalFlowProtocolSurface
            mutationAuthority : TerminalFlowReducerMutationAuthority
            ownedActor : TerminalFlowCicOwnedActorLifecycle
            proofOwnerLedger : RecursiveOwnerLedger<EvalWorklistTerminalGraphKind>
            proofOwnerCloseReceiptRef : uint32 option
            protocol : TerminalFlowCicKernelProtocol
            promotionRoute : TerminalFlowCicPromotionRoute
            verdict : TerminalFlowCicCheckVerdict
        }

        type TerminalFlowCicArtifactPromotionReceipt = private {
            checkReceipt : TerminalFlowIdentityRef<TerminalFlowCicCheckReceiptRefKind>
            manifestRef : TerminalFlowIdentityRef<TerminalFlowArtifactManifestRefKind>
            artifactSetHash : string
            exactOnceRef : uint32
        }

        let private terminalFlowCicArtifactPromotionReceiptFor
            (corridor:TerminalFlowCicKernelCorridor)
            manifestLifecycle
            writerRoute =
            let proofOwnersClosed =
                match corridor.proofOwnerLedger with
                | OwnerLedgerEmpty -> true
                | OwnerLedgerCons(CicProofObligationOwnerNode(OwnerLeaseClosed _), OwnerLedgerEmpty) -> true
                | _ -> false
            let actorClosed = terminalFlowCicOwnedActorQuiescenceCertificate corridor.ownedActor |> Option.isSome
            let actorHasProofEvidence =
                match terminalFlowCicOwnedActorState corridor.ownedActor with
                | None -> false
                | Some actor ->
                    not actor.congruenceEdges.IsEmpty
                    || not actor.substrate.defEqMemo.IsEmpty
                    || CompilerKernelV2.Measured.value actor.declarationReceiptCount > 0L
            let proofAuthorityClosed =
                proofOwnersClosed
                && corridor.proofOwnerCloseReceiptRef.IsSome
                && actorClosed
                && actorHasProofEvidence
            match corridor.verdict, manifestLifecycle, writerRoute with
            | TerminalFlowCicCheckAccepted checkReceipt,
              TerminalFlowArtifactManifestFilled(manifestRef, artifactSetHash, _, _),
              TerminalFlowWriterCompletionGreenPath(routeManifestRef, routeArtifactSetHash, intentCount)
                when proofAuthorityClosed
                     && intentCount > 0
                     && manifestRef = routeManifestRef
                     && artifactSetHash = routeArtifactSetHash ->
                Ok {
                    checkReceipt = checkReceipt
                    manifestRef = manifestRef
                    artifactSetHash = artifactSetHash
                    exactOnceRef =
                        NativeCutoverStableRef.ref32
                            "cic-artifact-promotion"
                            [ terminalFlowIdentityRefText checkReceipt
                              terminalFlowIdentityRefText manifestRef
                              artifactSetHash
                              string corridor.proofOwnerCloseReceiptRef.Value ]
                }
            | TerminalFlowCicCheckRejected(blocker, _), _, _
            | TerminalFlowCicCheckBlocked blocker, _, _ -> Error blocker
            | TerminalFlowCicCheckAccepted _, _, _ when not proofAuthorityClosed ->
                Error (TerminalFlowCicKernelInvariantViolation (terminalFlowCicInvariantNameId "cic_artifact_promotion_before_proof_authority_closed"))
            | _ -> Error (TerminalFlowCicKernelInvariantViolation (terminalFlowCicInvariantNameId "cic_artifact_promotion_route_mismatch"))

        let private terminalFlowCicTermShapeText = function
            | TerminalFlowCicSort _ -> "sort"
            | TerminalFlowCicBoundVar _ -> "bound_var"
            | TerminalFlowCicLambda _ -> "lambda"
            | TerminalFlowCicPi _ -> "pi"
            | TerminalFlowCicApp _ -> "app"
            | TerminalFlowCicLet _ -> "let"
            | TerminalFlowCicConst _ -> "const"
            | TerminalFlowCicMeta _ -> "meta"

        let private terminalFlowCicCheckVerdictText = function
            | TerminalFlowCicCheckAccepted receipt -> "accepted:" + terminalFlowIdentityRefText receipt
            | TerminalFlowCicCheckRejected(blocker, _) -> "rejected:" + terminalFlowCicBlockerText blocker
            | TerminalFlowCicCheckBlocked blocker -> "blocked:" + terminalFlowCicBlockerText blocker

        let private terminalFlowCicProofOwnerLedgerFor (verdict:TerminalFlowCicCheckVerdict) =
            let owner : PhantomOwnerId<EvalWorklistTerminalGraphKind,CicProofObligationOwnerKind> =
                phantomOwnerIdFor "owner:cic-proof-obligation:root"
            let closeKey : PhantomCloseKey<EvalWorklistTerminalGraphKind,CicProofObligationOwnerKind> =
                phantomCloseKeyFor owner "close:cic-proof-obligation:root"
            let obligation : CicProofObligationId<EvalWorklistTerminalGraphKind> =
                cicProofObligationIdFor (NativeCutoverStableRef.ref32 "cic-proof-obligation-root" ["root"])
            match verdict with
            | TerminalFlowCicCheckAccepted receipt ->
                let witness : CicProofWitnessRef<EvalWorklistTerminalGraphKind> =
                    cicProofWitnessRefFor (terminalFlowIdentityRefDigest receipt)
                let closeReceiptRef =
                    NativeCutoverStableRef.ref32
                        "cic-proof-close"
                        [ string (phantomCloseKeyValue closeKey)
                          string (cicProofWitnessRefValue witness) ]
                let state = CicProofObligationClosed(obligation, witness, closeReceiptRef)
                let lease : TypedOwnerLease<_,CicProofObligationOwnerKind,OwnerClosedPhase> =
                    typedOwnerLeaseFor owner (Some closeKey) None 0L (OwnerRequireCicProofWitness state) "cic_proof_witness_accepted_exact_once"
                OwnerLedgerCons(CicProofObligationOwnerNode(OwnerLeaseClosed lease), OwnerLedgerEmpty), Some closeReceiptRef
            | TerminalFlowCicCheckRejected(blocker, _)
            | TerminalFlowCicCheckBlocked blocker ->
                let blockerRef =
                    NativeCutoverStableRef.ref32
                        "cic-proof-blocker"
                        [ terminalFlowCicBlockerText blocker ]
                let state = CicProofObligationBlocked(obligation, blockerRef)
                let lease : TypedOwnerLease<_,CicProofObligationOwnerKind,OwnerOpenPhase> =
                    typedOwnerLeaseFor owner (Some closeKey) None 1L (OwnerRequireCicProofWitness state) "cic_proof_witness_required_before_artifact_or_exit"
                OwnerLedgerCons(CicProofObligationOwnerNode(OwnerLeaseOpen lease), OwnerLedgerEmpty), None

        let private terminalFlowCicKernelCorridorFor (ownerRef:CompilerKernelV2.NonZeroRef<TerminalFlowCicArenaOwnerRefKind>) (steps:TerminalFlowCicActorStep list) (verdict:TerminalFlowCicCheckVerdict) : TerminalFlowCicKernelCorridor =
            let proofOwnerLedger, proofOwnerCloseReceiptRef = terminalFlowCicProofOwnerLedgerFor verdict
            let claimed =
                match terminalFlowCicOwnedActorClaim ownerRef TerminalFlowCicActorDetached with
                | TerminalFlowCicOwnerClaimed lifecycle
                | TerminalFlowCicOwnerReused lifecycle -> lifecycle
                | TerminalFlowCicOwnerClaimRejectedActiveOwner(_, _, lifecycle) -> lifecycle
            let stepped =
                steps
                |> List.fold (fun lifecycle step ->
                    terminalFlowCicOwnedActorStepFor ownerRef step lifecycle
                    |> terminalFlowCicOwnedActorStepDecisionLifecycle) claimed
            let ownedActor =
                match verdict with
                | TerminalFlowCicCheckAccepted _ ->
                    terminalFlowCicOwnedActorCloseFor ownerRef stepped
                    |> terminalFlowCicOwnedActorCloseDecisionLifecycle
                | TerminalFlowCicCheckRejected _
                | TerminalFlowCicCheckBlocked _ -> stepped
            let protocol, promotionRoute =
                match verdict, ownedActor with
                | TerminalFlowCicCheckAccepted receipt, TerminalFlowCicActorClosed(capability, _, certificate) ->
                    TerminalFlowCicProtocolClosed(capability.ownerRef, certificate.certificateRef),
                    TerminalFlowCicPromotionToArtifactGreenPath receipt
                | TerminalFlowCicCheckAccepted _, TerminalFlowCicActorRunning(capability, actor) ->
                    let pendingDefinitions =
                        actor.definitionJobs
                        |> List.filter (fun (_, job) ->
                            match job.state with
                            | TerminalFlowCicDefinitionAccepted _
                            | TerminalFlowCicDefinitionRejected _ -> false
                            | TerminalFlowCicDefinitionQueued
                            | TerminalFlowCicDefinitionChecking _ -> true)
                        |> List.length
                    let pending = actor.inFlight.Count + List.length actor.openObligations + pendingDefinitions
                    TerminalFlowCicProtocolOwned(capability.ownerRef, capability.generation, actor.deterministicSequence),
                    TerminalFlowCicPromotionHeldForDependencies pending
                | TerminalFlowCicCheckAccepted _, TerminalFlowCicActorClosing(capability, actor) ->
                    let pendingDefinitions =
                        actor.definitionJobs
                        |> List.filter (fun (_, job) ->
                            match job.state with
                            | TerminalFlowCicDefinitionAccepted _
                            | TerminalFlowCicDefinitionRejected _ -> false
                            | TerminalFlowCicDefinitionQueued
                            | TerminalFlowCicDefinitionChecking _ -> true)
                        |> List.length
                    let pending = actor.inFlight.Count + List.length actor.openObligations + pendingDefinitions
                    TerminalFlowCicProtocolOwned(capability.ownerRef, capability.generation, actor.deterministicSequence),
                    TerminalFlowCicPromotionHeldForDependencies pending
                | TerminalFlowCicCheckAccepted _, TerminalFlowCicActorDetached ->
                    TerminalFlowCicProtocolDetached,
                    TerminalFlowCicPromotionHeldForDependencies 1
                | TerminalFlowCicCheckRejected(blocker, _), _ ->
                    TerminalFlowCicProtocolBlocked blocker,
                    TerminalFlowCicPromotionToTypedFailure blocker
                | TerminalFlowCicCheckBlocked blocker, _ ->
                    TerminalFlowCicProtocolBlocked blocker,
                    TerminalFlowCicPromotionHeldForDependencies 1
            { surface = TerminalFlowPrimarySurface
              mutationAuthority = TerminalFlowMutationReducerChannelOwned TerminalFlowPrimarySurface
              ownedActor = ownedActor
              proofOwnerLedger = proofOwnerLedger
              proofOwnerCloseReceiptRef = proofOwnerCloseReceiptRef
              protocol = protocol
              promotionRoute = promotionRoute
              verdict = verdict }


        type TerminalFlowRegistryLifecycleId =
            | TerminalFlowRegistryPruneRequired of nativeCellId:string
            | TerminalFlowRegistryPruned of fillKey:TerminalFlowFillKeyId

        type TerminalFlowPhysicalBoundaryAuthorityId =
            | TerminalFlowPhysicalBoundaryOwnedByWriterReceipt of writerJobId:string * artifactSetHash:string
            | TerminalFlowPhysicalBoundaryRejected of CompilerKernelV2.OperationalReasonId

        type TerminalFlowOwnerWakeReceipt = private {
            obligationId : string
            transactionId : string
            ledgerProofHash : string
            closeReceiptRefs : uint32 list
            observedAtMs : int64
        }

        type TerminalFlowOwnerWakeVerdict =
            | TerminalFlowOwnerWakeClosed of TerminalFlowOwnerWakeReceipt
            | TerminalFlowOwnerWakeRejected of obligationId:string * reasonRef:uint32

        type TerminalFlowOwnerWakeCell<'State> = private {
            obligationId : string
            ledgerRef : uint32
            closed : CompilerKernelV2.PortableOneShotCell<TerminalFlowOwnerWakeReceipt>
            rejected : CompilerKernelV2.PortableOneShotCell<uint32>
        }

        // Destructive domain migration : outcome, writer,
        // artifact and exit are indexed by kernel stage capabilities.  These
        // records deliberately carry no renderer text; text is a projection
        // emitted after the typed stage certificate exists.
        [<Struct>]
        type TerminalFlowRootUnresolvedStage = struct end

        // Reuse the earlier BigStack-local TerminalFlowRootResolvedStage phantom.

        [<Struct>]
        type TerminalFlowOutcomeOpenStage = struct end

        [<Struct>]
        type TerminalFlowOutcomeSealedStage = struct end

        [<Struct>]
        type TerminalFlowWriterUnboundStage = struct end

        // Reuse the earlier BigStack-local TerminalFlowWriterBoundStage phantom.

        [<Struct>]
        type TerminalFlowArtifactUncommittedStage = struct end

        [<Struct>]
        type TerminalFlowArtifactCommittedStage = struct end

        [<Struct>]
        type TerminalFlowExitOpenKernelStage = struct end

        [<Struct>]
        type TerminalFlowExitWitnessedKernelStage = struct end

        [<Struct>]
        type TerminalFlowRunEndPreparedKernelStage = struct end

        [<StructuralEquality; NoComparison>]
        type TerminalFlowKernelStageKindId =
            | TerminalFlowKernelStageAwaitRoot
            | TerminalFlowKernelStageAwaitOutcome
            | TerminalFlowKernelStageReadyToDispatch
            | TerminalFlowKernelStageWriterBound
            | TerminalFlowKernelStageArtifactCommitted
            | TerminalFlowKernelStageExitWitnessed
            | TerminalFlowKernelStageRunEndPrepared

        let private terminalFlowKernelStageKindText = function
            | TerminalFlowKernelStageAwaitRoot -> "AwaitRoot"
            | TerminalFlowKernelStageAwaitOutcome -> "AwaitOutcome"
            | TerminalFlowKernelStageReadyToDispatch -> "ReadyToDispatch"
            | TerminalFlowKernelStageWriterBound -> "WriterBound"
            | TerminalFlowKernelStageArtifactCommitted -> "ArtifactCommitted"
            | TerminalFlowKernelStageExitWitnessed -> "ExitWitnessed"
            | TerminalFlowKernelStageRunEndPrepared -> "RunEndPrepared"

        type TerminalFlowStageCapability<'Root,'Outcome,'Writer,'Artifact,'Exit> = private {
            stageId : TerminalFlowKernelStageKindId
            rootRef : TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind> option
            terminalRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind> option
            fillRef : TerminalFlowIdentityRef<TerminalFlowFillRefKind> option
            dispatchRef : TerminalFlowIdentityRef<TerminalFlowDispatchRefKind> option
            writerRef : uint32
            artifactRef : uint32
            exitRef : uint32
        }

        type TerminalFlowAnyKernelStage =
            | TerminalFlowStageAwaitRoot of TerminalFlowStageCapability<TerminalFlowRootUnresolvedStage,TerminalFlowOutcomeOpenStage,TerminalFlowWriterUnboundStage,TerminalFlowArtifactUncommittedStage,TerminalFlowExitOpenKernelStage>
            | TerminalFlowStageAwaitOutcome of TerminalFlowStageCapability<TerminalFlowRootResolvedStage,TerminalFlowOutcomeOpenStage,TerminalFlowWriterUnboundStage,TerminalFlowArtifactUncommittedStage,TerminalFlowExitOpenKernelStage>
            | TerminalFlowStageReadyToDispatch of TerminalFlowStageCapability<TerminalFlowRootResolvedStage,TerminalFlowOutcomeSealedStage,TerminalFlowWriterUnboundStage,TerminalFlowArtifactUncommittedStage,TerminalFlowExitOpenKernelStage>
            | TerminalFlowStageWriterBound of TerminalFlowStageCapability<TerminalFlowRootResolvedStage,TerminalFlowOutcomeSealedStage,TerminalFlowWriterBoundStage,TerminalFlowArtifactUncommittedStage,TerminalFlowExitOpenKernelStage>
            | TerminalFlowStageArtifactCommitted of TerminalFlowStageCapability<TerminalFlowRootResolvedStage,TerminalFlowOutcomeSealedStage,TerminalFlowWriterBoundStage,TerminalFlowArtifactCommittedStage,TerminalFlowExitOpenKernelStage>
            | TerminalFlowStageExitWitnessed of TerminalFlowStageCapability<TerminalFlowRootResolvedStage,TerminalFlowOutcomeSealedStage,TerminalFlowWriterBoundStage,TerminalFlowArtifactCommittedStage,TerminalFlowExitWitnessedKernelStage>
            | TerminalFlowStageRunEndPrepared of TerminalFlowStageCapability<TerminalFlowRootResolvedStage,TerminalFlowOutcomeSealedStage,TerminalFlowWriterBoundStage,TerminalFlowArtifactCommittedStage,TerminalFlowExitWitnessedKernelStage>

        let private terminalFlowStageRef (capability:TerminalFlowStageCapability<'Root,'Outcome,'Writer,'Artifact,'Exit>) =
            let identityValue (value:TerminalFlowIdentityRef<'Kind> option) =
                value |> Option.map terminalFlowIdentityRefDigest |> Option.defaultValue 0u
            terminalFlowMintedRefOf
                "stage_capability_ref"
                (FastRuntimeFormat.format "%s|%u|%u|%u|%u|%u|%u|%u" [| box (terminalFlowKernelStageKindText capability.stageId); box (identityValue capability.rootRef); box (identityValue capability.terminalRef); box (identityValue capability.fillRef); box (identityValue capability.dispatchRef); box capability.writerRef; box capability.artifactRef; box capability.exitRef |])

        let private terminalFlowStageCapability stageId rootRef terminalRef fillRef dispatchRef writerRef artifactRef exitRef =
            { stageId = stageId
              rootRef = rootRef
              terminalRef = terminalRef
              fillRef = fillRef
              dispatchRef = dispatchRef
              writerRef = writerRef
              artifactRef = artifactRef
              exitRef = exitRef }

        let private terminalFlowAnyKernelStageRef = function
            | TerminalFlowStageAwaitRoot capability -> terminalFlowStageRef capability
            | TerminalFlowStageAwaitOutcome capability -> terminalFlowStageRef capability
            | TerminalFlowStageReadyToDispatch capability -> terminalFlowStageRef capability
            | TerminalFlowStageWriterBound capability -> terminalFlowStageRef capability
            | TerminalFlowStageArtifactCommitted capability -> terminalFlowStageRef capability
            | TerminalFlowStageExitWitnessed capability -> terminalFlowStageRef capability
            | TerminalFlowStageRunEndPrepared capability -> terminalFlowStageRef capability

        let private terminalFlowAnyKernelStageKind = function
            | TerminalFlowStageAwaitRoot _ -> TerminalFlowKernelStageAwaitRoot
            | TerminalFlowStageAwaitOutcome _ -> TerminalFlowKernelStageAwaitOutcome
            | TerminalFlowStageReadyToDispatch _ -> TerminalFlowKernelStageReadyToDispatch
            | TerminalFlowStageWriterBound _ -> TerminalFlowKernelStageWriterBound
            | TerminalFlowStageArtifactCommitted _ -> TerminalFlowKernelStageArtifactCommitted
            | TerminalFlowStageExitWitnessed _ -> TerminalFlowKernelStageExitWitnessed
            | TerminalFlowStageRunEndPrepared _ -> TerminalFlowKernelStageRunEndPrepared

        let private terminalFlowAnyKernelStageText stage =
            stage |> terminalFlowAnyKernelStageKind |> terminalFlowKernelStageKindText

        type TerminalFlowWriterCapability<'State> = private {
            writerLeaseId : string
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            ownerClosureCertificateId : string
            ownerTransactionId : string
            ownerLedgerAfter : RecursiveOwnerLedger<EvalWorklistTerminalGraphKind>
            ownerWakeCell : TerminalFlowOwnerWakeCell<TerminalFlowOwnerWakeRegisteredState>
            artifactPlan : TerminalFlowArtifactWritePlan<TerminalFlowArtifactPlanBoundState>
            sealedOutcomeStage : TerminalFlowStageCapability<TerminalFlowRootResolvedStage,TerminalFlowOutcomeSealedStage,TerminalFlowWriterUnboundStage,TerminalFlowArtifactUncommittedStage,TerminalFlowExitOpenKernelStage>
            writerBoundStage : TerminalFlowStageCapability<TerminalFlowRootResolvedStage,TerminalFlowOutcomeSealedStage,TerminalFlowWriterBoundStage,TerminalFlowArtifactUncommittedStage,TerminalFlowExitOpenKernelStage>
        }

        let private terminalFlowWriterTerminalReceiptText (writer:TerminalFlowWriterCapability<'State>) =
            terminalFlowIdentityRefText writer.terminalReceiptRef

        // The semantic scheduler does not fabricate artifact success.  It publishes
        // a typed commit request and suspends on this IVar until the outer codegen
        // boundary supplies the actual artifact manifest and execution receipt.
        type TerminalFlowArtifactCommitRequest = private {
            requestId : string
            requestRef : uint32
            nativeCellId : string
            writer : TerminalFlowWriterCapability<TerminalFlowWriterBoundState>
            completion : CompilerKernelV2.PortableOneShotCell<TerminalFlowArtifactWriteReceipt<TerminalFlowArtifactsCommittedState>>
        }

        let private terminalFlowArtifactCommitRequestCreate
            requestId
            nativeCellId
            writer
            completion
            : TerminalFlowArtifactCommitRequest =
            { requestId = requestId
              requestRef = terminalFlowMintedRefOf "artifact_commit_request_ref" requestId
              nativeCellId = nativeCellId
              writer = writer
              completion = completion }

        type TerminalFlowArtifactCommitRegistryPruneKind =
            | TerminalFlowArtifactCommitRegistryPruned
            | TerminalFlowArtifactCommitRegistryPruneMiss

        let private terminalFlowArtifactCommitRegistryPruneKindText
            (kind:TerminalFlowArtifactCommitRegistryPruneKind) =
            match kind with
            | TerminalFlowArtifactCommitRegistryPruned -> "Pruned"
            | TerminalFlowArtifactCommitRegistryPruneMiss -> "PruneMiss"

        type TerminalFlowArtifactCommitRegistryPruneReceipt = private {
            nativeCellId : string
            requestId : string
            kind : TerminalFlowArtifactCommitRegistryPruneKind
            exactOnceRef : uint32
        }

        type TerminalFlowArtifactPersistenceDecision =
            | TerminalFlowArtifactPersistenceCommitted of artifactCount:int * totalBytes:int64
            | TerminalFlowArtifactPersistenceRejected of CompilerKernelV2.OperationalReasonId

        let terminalFlowArtifactPersistenceDecisionText = function
            | TerminalFlowArtifactPersistenceCommitted(artifactCount, totalBytes) ->
                sprintf "ArtifactPersistence(Committed|artifacts=%d|bytes=%d)" artifactCount totalBytes
            | TerminalFlowArtifactPersistenceRejected reason ->
                "ArtifactPersistence(Rejected|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        type TerminalFlowBuildDraftCommitReceipt = {
            cellId : string
            artifactSetHash : string
            capabilityText : string
            resolutionText : string
            workDagText : string
            terminalSealText : string
            finalize : TerminalFlowArtifactPersistenceDecision -> Hopac.Job<unit>
        }

        type TerminalFlowResidualDrainPass = private {
            passCount : int
            materialDeltaOnPass : int
            pendingDepth : int
            queueDepth : int
            activeDepth : int
            proceduralDepth : int
        }

        // Conserved-credit authority migration: time, repeat count, queue
        // pressure and writer leases are not closure evidence.  The only local
        // force-close token retained here is the typed work-DAG tail receipt used
        // by an exact closed-world/QAP transaction.
        type TerminalFlowWorkDagTailCloseReceiptRefKind private () =
            static member IdentityKindTag () = 0x060003u

        type TerminalFlowForceOwnerCloseAuthority =
            | TerminalFlowForceOwnerCloseQapPostCommitPermit of
                permitRef:uint32 *
                ownerCertificateRef:uint32 *
                workDagProofRef:uint32 *
                recoveryRef:uint32

        type TerminalFlowForceOwnerCloseRatificationRefKind private () =
            static member IdentityKindTag () = 0x060005u
        type TerminalFlowForceOwnerCloseOriginRefKind private () =
            static member IdentityKindTag () = 0x060006u
        type TerminalFlowForceOwnerCloseTotalOrderOriginRefKind private () =
            static member IdentityKindTag () = 0x060007u

        // Five-round migration : ForceOwnerClose is no longer an exterior
        // escape hatch.  Every transaction carries one closed ratification that
        // names its origin, owner/work-DAG/recovery evidence and the total-order
        // origin that must consume it.  A transaction without this proof cannot
        // be represented.
        type TerminalFlowForceOwnerCloseRatification = private {
            origin : TerminalFlowForceOwnerCloseAuthority
            originRef : TerminalFlowIdentityRef<TerminalFlowForceOwnerCloseOriginRefKind>
            ownerCertificateRef : uint32
            workDagProofRef : uint32
            recoveryRef : uint32
            totalOrderOriginRef : TerminalFlowIdentityRef<TerminalFlowForceOwnerCloseTotalOrderOriginRefKind>
            ratificationRef : TerminalFlowIdentityRef<TerminalFlowForceOwnerCloseRatificationRefKind>
            exactOnceRef : uint32
        }

        type TerminalFlowForceOwnerCloseTransaction = private {
            ratification : TerminalFlowForceOwnerCloseRatification
            ownerCloseReceiptId : string
            workDagTailCloseReceipt : TerminalFlowIdentityRef<TerminalFlowWorkDagTailCloseReceiptRefKind>
            queueOnlyRecoveryReady : bool
            fillOnceReadyWitnessRef : uint32
        }

        let private terminalFlowForceOwnerCloseAuthorityText = function
            | TerminalFlowForceOwnerCloseQapPostCommitPermit(permitRef, ownerCertificateRef, workDagProofRef, recoveryRef) ->
                FastRuntimeFormat.format "QapPostCommitPermit(ref=%u|owner_certificate=%u|workdag_proof=%u|recovery=%u)" [| box permitRef; box ownerCertificateRef; box workDagProofRef; box recoveryRef |]

        let private terminalFlowForceOwnerCloseRatificationText ratification =
            FastRuntimeFormat.format "Ratification(origin=%s|origin_ref=%s|owner_certificate=%u|workdag_proof=%u|recovery=%u|total_order_origin=%s|ratification_ref=%s|exact_once=%u)" [| box (terminalFlowForceOwnerCloseAuthorityText ratification.origin); box (terminalFlowIdentityRefText ratification.originRef); box ratification.ownerCertificateRef; box ratification.workDagProofRef; box ratification.recoveryRef; box (terminalFlowIdentityRefText ratification.totalOrderOriginRef); box (terminalFlowIdentityRefText ratification.ratificationRef); box ratification.exactOnceRef |]

        let private terminalFlowForceOwnerCloseTransactionText tx =
            FastRuntimeFormat.format "ForceOwnerCloseTransaction(ratification=%s|owner_close=%s|workdag_close=%s|queue_only_ready=%b|fill_once_ready_ref=%u)" [| box (terminalFlowForceOwnerCloseRatificationText tx.ratification); box tx.ownerCloseReceiptId; box (terminalFlowIdentityRefText tx.workDagTailCloseReceipt); box tx.queueOnlyRecoveryReady; box tx.fillOnceReadyWitnessRef |]

        // MIGRATION / destructive migration migration phase: the green path is no longer
        // inferred from a BuildOk-looking boundary.  It is a linear corridor
        // whose first unforgeable token is the force-close transaction from
        // MIGRATION and whose final token is a neutral physical-exit receipt.
        type TerminalFlowGreenPathOpenStage = class end
        type TerminalFlowGreenPathDispatchReadyStage = class end
        type TerminalFlowGreenPathWriterBoundStage = class end
        type TerminalFlowGreenPathArtifactCommittedStage = class end
        type TerminalFlowGreenPathTerminalCommittedStage = class end
        type TerminalFlowGreenPathRunEndedStage = class end
        type TerminalFlowGreenPathPhysicalExitStage = class end
        type TerminalFlowGreenPathRejectedStage = class end

        type TerminalFlowGreenPathReceipt<'Stage> = private {
            receiptRef : uint32
            predecessorRef : uint32 option
            fillKey : TerminalFlowFillKeyId
            exactOnce : bool
        }

        type TerminalFlowGreenPathRejectReasonId =
            | TerminalFlowGreenPathDispatchRejected of reason:CompilerKernelV2.OperationalReasonId
            | TerminalFlowGreenPathNonzeroExit of exitCode:int

        let private terminalFlowGreenPathRejectReasonText = function
            | TerminalFlowGreenPathDispatchRejected reason ->
                "dispatch_rejected:" + CompilerKernelV2.OperationalReasonIdOps.text reason
            | TerminalFlowGreenPathNonzeroExit exitCode ->
                sprintf "nonzero_exit_on_green_path:%d" exitCode

        type TerminalFlowGreenPathLinearState =
            | TerminalFlowGreenPathOpen of TerminalFlowGreenPathReceipt<TerminalFlowGreenPathOpenStage> * TerminalFlowForceOwnerCloseTransaction
            | TerminalFlowGreenPathWriterBound of TerminalFlowGreenPathReceipt<TerminalFlowGreenPathWriterBoundStage> * TerminalFlowForceOwnerCloseTransaction * writerReceiptId:string
            | TerminalFlowGreenPathArtifactCommitted of TerminalFlowGreenPathReceipt<TerminalFlowGreenPathArtifactCommittedStage> * TerminalFlowArtifactCorridor<TerminalFlowArtifactsCommittedState>
            | TerminalFlowGreenPathTerminalCommitted of TerminalFlowGreenPathReceipt<TerminalFlowGreenPathTerminalCommittedStage> * terminalCommitReceiptRef:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            | TerminalFlowGreenPathRunEnded of TerminalFlowGreenPathReceipt<TerminalFlowGreenPathRunEndedStage> * runEndReceiptId:string
            | TerminalFlowGreenPathPhysicalExit of TerminalFlowGreenPathReceipt<TerminalFlowGreenPathPhysicalExitStage> * exitCode:int
            | TerminalFlowGreenPathRejected of TerminalFlowGreenPathReceipt<TerminalFlowGreenPathRejectedStage> * reason:TerminalFlowGreenPathRejectReasonId

        let private terminalFlowGreenPathStateText = function
            | TerminalFlowGreenPathOpen(receipt, tx) -> sprintf "GreenPathOpen(ref=%u|tx=%s)" receipt.receiptRef (terminalFlowForceOwnerCloseTransactionText tx)
            | TerminalFlowGreenPathWriterBound(receipt, _, writerReceiptId) -> sprintf "GreenPathWriterBound(ref=%u|writer=%s)" receipt.receiptRef writerReceiptId
            | TerminalFlowGreenPathArtifactCommitted(receipt, corridor) -> sprintf "GreenPathArtifactCommitted(ref=%u|route=%s)" receipt.receiptRef (terminalFlowWriterCompletionRouteText corridor.writerCompletionRoute)
            | TerminalFlowGreenPathTerminalCommitted(receipt, terminalCommitReceiptRef) -> sprintf "GreenPathTerminalCommitted(ref=%u|commit=%s)" receipt.receiptRef (terminalFlowIdentityRefText terminalCommitReceiptRef)
            | TerminalFlowGreenPathRunEnded(receipt, runEndReceiptId) -> sprintf "GreenPathRunEnded(ref=%u|run_end=%s)" receipt.receiptRef runEndReceiptId
            | TerminalFlowGreenPathPhysicalExit(receipt, exitCode) -> sprintf "GreenPathPhysicalExit(ref=%u|exit=%d)" receipt.receiptRef exitCode
            | TerminalFlowGreenPathRejected(receipt, reason) ->
                sprintf "GreenPathRejected(ref=%u|reason=%s)"
                    receipt.receiptRef
                    (terminalFlowGreenPathRejectReasonText reason)

        let private terminalFlowGreenPathReceiptRef : TerminalFlowGreenPathLinearState -> uint32 = function
            | TerminalFlowGreenPathOpen(receipt, _) -> receipt.receiptRef
            | TerminalFlowGreenPathWriterBound(receipt, _, _) -> receipt.receiptRef
            | TerminalFlowGreenPathArtifactCommitted(receipt, _) -> receipt.receiptRef
            | TerminalFlowGreenPathTerminalCommitted(receipt, _) -> receipt.receiptRef
            | TerminalFlowGreenPathRunEnded(receipt, _) -> receipt.receiptRef
            | TerminalFlowGreenPathPhysicalExit(receipt, _) -> receipt.receiptRef
            | TerminalFlowGreenPathRejected(receipt, _) -> receipt.receiptRef

        type TerminalFlowGreenPathDispatchMissing =
            | TerminalFlowGreenPathMissingOpenTransaction
            | TerminalFlowGreenPathAlreadyWriterBound
            | TerminalFlowGreenPathAlreadyArtifactCommitted
            | TerminalFlowGreenPathAlreadyTerminalCommitted
            | TerminalFlowGreenPathAlreadyRunEnded
            | TerminalFlowGreenPathAlreadyPhysicalExit
            | TerminalFlowGreenPathRejectedBeforeDispatch of reason:TerminalFlowGreenPathRejectReasonId
            | TerminalFlowGreenPathForceCloseNotRatified of ratificationRef:string

        type TerminalFlowGreenPathDispatchResult<'T> = Result<'T, TerminalFlowGreenPathDispatchMissing list>

        let private terminalFlowGreenPathDispatchMissingText = function
            | TerminalFlowGreenPathMissingOpenTransaction -> "missing_open_transaction"
            | TerminalFlowGreenPathAlreadyWriterBound -> "already_writer_bound"
            | TerminalFlowGreenPathAlreadyArtifactCommitted -> "already_artifact_committed"
            | TerminalFlowGreenPathAlreadyTerminalCommitted -> "already_terminal_committed"
            | TerminalFlowGreenPathAlreadyRunEnded -> "already_run_ended"
            | TerminalFlowGreenPathAlreadyPhysicalExit -> "already_physical_exit"
            | TerminalFlowGreenPathRejectedBeforeDispatch reason ->
                "rejected_before_dispatch:" + terminalFlowGreenPathRejectReasonText reason
            | TerminalFlowGreenPathForceCloseNotRatified ratificationRef -> "force_close_not_ratified:" + ratificationRef

        let private terminalFlowGreenPathDispatchMissingListText missing =
            missing |> List.map terminalFlowGreenPathDispatchMissingText |> String.concat " -> "

        let private terminalFlowGreenPathDispatchReadyReceipt
            (state:TerminalFlowGreenPathLinearState)
            : TerminalFlowGreenPathDispatchResult<TerminalFlowGreenPathReceipt<TerminalFlowGreenPathDispatchReadyStage>> =
            match state with
            | TerminalFlowGreenPathOpen(receipt, tx) ->
                if tx.ratification.exactOnceRef = 0u then
                    Error [TerminalFlowGreenPathForceCloseNotRatified(terminalFlowIdentityRefText tx.ratification.ratificationRef)]
                else
                    Ok {
                        receiptRef = receipt.receiptRef
                        predecessorRef = receipt.predecessorRef
                        fillKey = receipt.fillKey
                        exactOnce = receipt.exactOnce
                    }
            | TerminalFlowGreenPathWriterBound _ ->
                Error [TerminalFlowGreenPathAlreadyWriterBound]
            | TerminalFlowGreenPathArtifactCommitted _ -> Error [TerminalFlowGreenPathAlreadyArtifactCommitted]
            | TerminalFlowGreenPathTerminalCommitted _ -> Error [TerminalFlowGreenPathAlreadyTerminalCommitted]
            | TerminalFlowGreenPathRunEnded _ -> Error [TerminalFlowGreenPathAlreadyRunEnded]
            | TerminalFlowGreenPathPhysicalExit _ -> Error [TerminalFlowGreenPathAlreadyPhysicalExit]
            | TerminalFlowGreenPathRejected(_, reason) -> Error [TerminalFlowGreenPathRejectedBeforeDispatch reason]

        let private terminalFlowGreenPathOpenFor (fillKey:TerminalFlowFillKeyId) tx =
            let fillKeyText = TerminalFlowFillKeyId.text fillKey
            let receipt : TerminalFlowGreenPathReceipt<TerminalFlowGreenPathOpenStage> =
                { receiptRef = terminalFlowMintedRefOf "green_path_open_ref" (fillKeyText + "|" + tx.ownerCloseReceiptId)
                  predecessorRef = Some tx.fillOnceReadyWitnessRef
                  fillKey = fillKey
                  exactOnce = tx.queueOnlyRecoveryReady && tx.ratification.exactOnceRef <> 0u }
            TerminalFlowGreenPathOpen(receipt, tx)

        let private terminalFlowGreenPathBindWriter writerReceiptId state : TerminalFlowGreenPathDispatchResult<TerminalFlowGreenPathLinearState> =
            match state with
            | TerminalFlowGreenPathOpen(openReceipt, tx) when tx.ratification.exactOnceRef <> 0u ->
                let receipt : TerminalFlowGreenPathReceipt<TerminalFlowGreenPathWriterBoundStage> =
                    { receiptRef = terminalFlowMintedRefOf "green_path_writer_bound_ref" (TerminalFlowFillKeyId.text openReceipt.fillKey + "|" + writerReceiptId)
                      predecessorRef = Some openReceipt.receiptRef
                      fillKey = openReceipt.fillKey
                      exactOnce = true }
                Ok(TerminalFlowGreenPathWriterBound(receipt, tx, writerReceiptId))
            | TerminalFlowGreenPathOpen(_, tx) ->
                Error [TerminalFlowGreenPathForceCloseNotRatified(terminalFlowIdentityRefText tx.ratification.ratificationRef)]
            | TerminalFlowGreenPathWriterBound _ -> Error [TerminalFlowGreenPathAlreadyWriterBound]
            | TerminalFlowGreenPathArtifactCommitted _ -> Error [TerminalFlowGreenPathAlreadyArtifactCommitted]
            | TerminalFlowGreenPathTerminalCommitted _ -> Error [TerminalFlowGreenPathAlreadyTerminalCommitted]
            | TerminalFlowGreenPathRunEnded _ -> Error [TerminalFlowGreenPathAlreadyRunEnded]
            | TerminalFlowGreenPathPhysicalExit _ -> Error [TerminalFlowGreenPathAlreadyPhysicalExit]
            | TerminalFlowGreenPathRejected(_, reason) -> Error [TerminalFlowGreenPathRejectedBeforeDispatch reason]

        let private terminalFlowGreenPathConsumeQueueRecovery recoveryRef gate state : TerminalFlowGreenPathDispatchResult<TerminalFlowGreenPathSealIntent * TerminalFlowGreenPathLinearState> =
            match state with
            | TerminalFlowGreenPathOpen(openReceipt, _) ->
                let intent = terminalFlowGreenPathSealIntentFor recoveryRef gate openReceipt.fillKey
                terminalFlowGreenPathBindWriter intent.writerReceiptId state
                |> Result.map (fun writerBound -> intent, writerBound)
            | TerminalFlowGreenPathWriterBound _ -> Error [TerminalFlowGreenPathAlreadyWriterBound]
            | TerminalFlowGreenPathArtifactCommitted _ -> Error [TerminalFlowGreenPathAlreadyArtifactCommitted]
            | TerminalFlowGreenPathTerminalCommitted _ -> Error [TerminalFlowGreenPathAlreadyTerminalCommitted]
            | TerminalFlowGreenPathRunEnded _ -> Error [TerminalFlowGreenPathAlreadyRunEnded]
            | TerminalFlowGreenPathPhysicalExit _ -> Error [TerminalFlowGreenPathAlreadyPhysicalExit]
            | TerminalFlowGreenPathRejected(_, reason) -> Error [TerminalFlowGreenPathRejectedBeforeDispatch reason]

        // Bonus migration: owner closure is no longer a timeout/repeat/pressure
        // policy surface.  Residual owners may only remain live waiting for the
        // conserved-credit/QAP quiescence proof, or close because they are
        // structurally exhausted.  Exact closed-world force-close is a separate
        // capability transaction and cannot be manufactured from this DU.
        type TerminalFlowOwnerCloseDecisionId =
            | TerminalFlowOwnerCloseDeferredMaterialDelta of TerminalFlowResidualDrainPass
            | TerminalFlowOwnerCloseAwaitConservedCreditQuiescence of TerminalFlowResidualDrainPass
            | TerminalFlowOwnerCloseAlreadyExhausted of TerminalFlowResidualDrainPass

        type TerminalFlowOwnerCloseReceipt<'OwnerKind> = private {
            closeKey : PhantomCloseKey<EvalWorklistTerminalGraphKind,'OwnerKind>
            drainPass : TerminalFlowResidualDrainPass
            receiptId : string
            exactOnce : bool
        }

        type TerminalFlowAnyOwnerCloseReceipt =
            | TerminalFlowParentContinuationClosed of TerminalFlowOwnerCloseReceipt<ParentContinuationOwnerKind>
            | TerminalFlowCrossKindClosed of TerminalFlowOwnerCloseReceipt<CrossKindOwnerKind>
            | TerminalFlowSidecarDrainClosed of TerminalFlowOwnerCloseReceipt<SidecarDrainOwnerKind>
            | TerminalFlowDynamicBridgeClosed of TerminalFlowOwnerCloseReceipt<DynamicBridgeOwnerKind>
            | TerminalFlowPoisonTailClosed of TerminalFlowOwnerCloseReceipt<PoisonTailOwnerKind>
            | TerminalFlowJoinPointWaitClosed of TerminalFlowOwnerCloseReceipt<JoinPointWaitOwnerKind>
            | TerminalFlowProceduralResidualClosed of TerminalFlowOwnerCloseReceipt<ProceduralResidualOwnerKind>
            | TerminalFlowCicProofObligationClosed of TerminalFlowOwnerCloseReceipt<CicProofObligationOwnerKind>

        type TerminalFlowOwnerClosureCertificate = private {
            certificateId : string
            transaction : TypedOwnerTransactionReceipt<EvalWorklistTerminalGraphKind>
            emptyOwners : RecursiveOwnerLedgerEmptyProof<EvalWorklistTerminalGraphKind>
            closeReceipts : TerminalFlowAnyOwnerCloseReceipt list
            wakeCell : TerminalFlowOwnerWakeCell<TerminalFlowOwnerWakeRegisteredState>
        }

        type TerminalFlowNativeSchedulerAuthorityId =
            | TerminalFlowNativeSchedulerPreRoot
            | TerminalFlowNativeSchedulerRepair of TerminalFlowOwnerCloseDecisionId
            | TerminalFlowNativeSchedulerEscalate of TerminalFlowOwnerCloseDecisionId
            | TerminalFlowNativeSchedulerCommit of writerReceiptId:string
            | TerminalFlowNativeSchedulerFailClosed of CompilerKernelV2.OperationalReasonId

        // MIGRATION / destructive domain migration migration phase:
        // The terminal outcome is now carried by a concrete Hopac IVar. The only
        // consumer is one composite Job that fills once, binds the resolved envelope,
        // constructs WriterCapability<Bound>, and executes the writer authority job.
        // Alt.choose, HUD caches, and the legacy breakthrough arbiter are intentionally
        // absent from this possession chain.

        // Destructive migration round 3: the scheduler channel is a typed receipt chain.
        // Operational lineage is stored once, in the predecessor receipt. Numeric refs below
        // survive only as derived boundary projections for legacy telemetry during the wave.
        type TerminalFlowSchedulerAdmissionReceiptKind = class end
        type TerminalFlowSchedulerWakerReceiptKind = class end
        type TerminalFlowSchedulerWorkerReceiptKind = class end
        type TerminalFlowSchedulerAuthorityReceiptKind = class end
        type TerminalFlowSchedulerReceiptSealedStage = class end
        type TerminalFlowSchedulerStageTokenWitnessKind = class end
        type TerminalFlowSchedulerWakerRequirementWitnessKind = class end
        type TerminalFlowSchedulerWakerEdgeWitnessKind = class end
        type TerminalFlowSchedulerWakerRegistryWitnessKind = class end
        type TerminalFlowSchedulerWorkerJobWitnessKind = class end
        type TerminalFlowSchedulerArtifactWitnessKind = class end
        type TerminalFlowSchedulerExitWitnessKind = class end
        type TerminalFlowSchedulerActorCommandWitnessKind = class end
        type TerminalFlowSchedulerPredecessorOrderWitnessKind = class end
        type TerminalFlowStageTokenHandoffWitnessKind = class end
        type TerminalFlowDispatchGrantWitnessKind = class end
        type TerminalFlowPushActorOwnerWitnessKind = class end
        type TerminalFlowFillCommandWitnessKind = class end
        type TerminalFlowSealCommandWitnessKind = class end
        type TerminalFlowDispatchPendingTerminalWitnessKind = class end
        type TerminalFlowSchedulerGraphClosureWitnessKind = class end
        type TerminalFlowSchedulerRequirementLedgerWitnessKind = class end

        type TerminalFlowSchedulerReceiptId<'Kind> = private TerminalFlowSchedulerReceiptId of CompilerIdentityKernel.ContentDigest

        // A scheduler receipt has either no predecessor (genesis) or exactly one
        // predecessor digest. Model that cardinality directly instead of using a
        // private two-case DU whose `private |` surface repeatedly broke F# parsing.
        type TerminalFlowSchedulerReceiptPredecessor = private TerminalFlowSchedulerReceiptPredecessor of CompilerIdentityKernel.ContentDigest option

        type TerminalFlowSchedulerReceipt<'Kind,'Stage,'Payload> = private {
            receiptId : TerminalFlowSchedulerReceiptId<'Kind>
            predecessor : TerminalFlowSchedulerReceiptPredecessor
            payload : 'Payload
        }

        // Higher-order projection over the phantom-indexed receipt. Consumers can
        // transform a receipt without reopening its representation or erasing stage/kind.
        type TerminalFlowSchedulerReceiptVisitor<'Kind,'Stage,'Payload,'Result> = private TerminalFlowSchedulerReceiptVisitor of (TerminalFlowSchedulerReceiptId<'Kind> -> TerminalFlowSchedulerReceiptPredecessor -> 'Payload -> 'Result)

        let private terminalFlowSchedulerReceiptVisit
            (TerminalFlowSchedulerReceiptVisitor project)
            (receipt:TerminalFlowSchedulerReceipt<'Kind,'Stage,'Payload>) =
            project receipt.receiptId receipt.predecessor receipt.payload

        let private terminalFlowSchedulerReceiptDigest (TerminalFlowSchedulerReceiptId digest) = digest
        let private terminalFlowSchedulerReceiptPredecessorText (TerminalFlowSchedulerReceiptPredecessor predecessor) =
            match predecessor with
            | None -> "genesis"
            | Some digest -> CompilerIdentityKernel.ContentDigest.text digest
        let private terminalFlowSchedulerReceiptExactOnce receipt =
            receipt
            |> terminalFlowSchedulerReceiptVisit
                (TerminalFlowSchedulerReceiptVisitor(fun receiptId _ _ -> terminalFlowSchedulerReceiptDigest receiptId))
        let private terminalFlowSchedulerReceiptCreate domain payloadText predecessor payload =
            let predecessorText = terminalFlowSchedulerReceiptPredecessorText predecessor
            let digest =
                CompilerIdentityKernel.ContentDigest.ofText
                    domain
                    (payloadText + "|pred=" + predecessorText)
            { receiptId = TerminalFlowSchedulerReceiptId digest
              predecessor = predecessor
              payload = payload }

        let private terminalFlowSchedulerReceiptCreateGenesis domain payloadText payload =
            terminalFlowSchedulerReceiptCreate domain payloadText (TerminalFlowSchedulerReceiptPredecessor None) payload

        let private terminalFlowSchedulerReceiptCreateSuccessor domain payloadText predecessor payload =
            terminalFlowSchedulerReceiptCreate domain payloadText (TerminalFlowSchedulerReceiptPredecessor (Some predecessor)) payload

        type TerminalFlowSchedulerWitness<'Kind> = private {
            sourceRef : uint32
            digest : CompilerIdentityKernel.ContentDigest
        }

        let private terminalFlowSchedulerWitnessFor domain refId : TerminalFlowSchedulerWitness<'Kind> =
            if refId = 0u then invalidOp (domain + " witness cannot be zero")
            { sourceRef = refId
              digest = CompilerIdentityKernel.ContentDigest.ofText domain (string refId) }

        let private terminalFlowSchedulerWitnessSourceRef witness = witness.sourceRef
        let private terminalFlowSchedulerWitnessDigest witness = witness.digest
        let private terminalFlowSchedulerWitnessRef witness =
            terminalFlowMintedRefOf
                "scheduler_witness_boundary_projection"
                (CompilerIdentityKernel.ContentDigest.text witness.digest)

        type TerminalFlowSchedulerGraphClosedReceipt = private {
            closure : TerminalFlowSchedulerWitness<TerminalFlowSchedulerGraphClosureWitnessKind>
            ledger : TerminalFlowSchedulerWitness<TerminalFlowSchedulerRequirementLedgerWitnessKind>
        }
        with
            member this.closureRef = terminalFlowSchedulerWitnessRef this.closure
            member this.ledgerRef = terminalFlowSchedulerWitnessRef this.ledger
            member this.exactOnce =
                CompilerIdentityKernel.ContentDigest.ofText
                    "scheduler-graph-closed"
                    (CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest this.closure)
                     + "|ledger="
                     + CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest this.ledger))

        let private terminalFlowSchedulerGraphClosedFor closureRef ledgerRef =
            let closure : TerminalFlowSchedulerWitness<TerminalFlowSchedulerGraphClosureWitnessKind> =
                terminalFlowSchedulerWitnessFor "scheduler-graph-closure" closureRef
            let ledger : TerminalFlowSchedulerWitness<TerminalFlowSchedulerRequirementLedgerWitnessKind> =
                terminalFlowSchedulerWitnessFor "scheduler-requirement-ledger" ledgerRef
            { closure = closure; ledger = ledger }

