            identity : TerminalFlowAdmissionIdentity
            graph : TerminalFlowSchedulerGraphClosedReceipt
            schedulerRelease : TerminalFlowSchedulerPhysicalReleaseReceipt
            stageToken : TerminalFlowSchedulerWitness<TerminalFlowSchedulerStageTokenWitnessKind>
            wakerRequirement : TerminalFlowSchedulerWitness<TerminalFlowSchedulerWakerRequirementWitnessKind>
            wakerEdge : TerminalFlowSchedulerWitness<TerminalFlowSchedulerWakerEdgeWitnessKind>
        }

        type TerminalFlowSchedulerChannelAdmissionContext = private {
            receipt : TerminalFlowSchedulerReceipt<TerminalFlowSchedulerAdmissionReceiptKind,TerminalFlowSchedulerReceiptSealedStage,TerminalFlowSchedulerAdmissionPayload>
        }
        with
            member this.identity = this.receipt.payload.identity
            member this.graph = this.receipt.payload.graph
            member this.schedulerRelease = this.receipt.payload.schedulerRelease
            member this.stageToken = this.receipt.payload.stageToken
            member this.wakerRequirement = this.receipt.payload.wakerRequirement
            member this.wakerEdge = this.receipt.payload.wakerEdge
            member this.contextDigest = terminalFlowSchedulerReceiptExactOnce this.receipt
            member this.contextRef = terminalFlowMintedRefOf "scheduler_channel_context_projection_ref" (CompilerIdentityKernel.ContentDigest.text this.contextDigest)
            member this.exactOnceRef = terminalFlowMintedRefOf "scheduler_channel_context_projection_exact_once_ref" (CompilerIdentityKernel.ContentDigest.text this.contextDigest)
            member this.admissionRef = terminalFlowAdmissionRawRef this.identity
            member this.admissionIdentityRef = terminalFlowAdmissionIdentityRef this.identity
            member this.actorBindingRef = terminalFlowAdmissionActorBindingRef this.identity
            member this.credentialLedgerRef = terminalFlowAdmissionRequirementLedgerRef this.identity
            member this.credentialGraphClosureRef = this.graph.closureRef
            member this.credentialCycleProofRef = 0u
            member this.fairnessEpochRef = terminalFlowAdmissionFairnessEpochRef this.identity
            member this.fairnessReleaseRef = terminalFlowIdentityRefDigest this.schedulerRelease.fairnessReleaseRef
            member this.actorRef = terminalFlowAdmissionActorRef this.identity
            member this.stageTokenRef = terminalFlowSchedulerWitnessRef this.stageToken
            member this.wakerRequirementRef = terminalFlowSchedulerWitnessRef this.wakerRequirement
            member this.wakerEdgeRef = terminalFlowSchedulerWitnessRef this.wakerEdge

