        type TerminalFlowSchedulerWakerRegistrationReceipt = private {
            receipt : TerminalFlowSchedulerReceipt<TerminalFlowSchedulerWakerReceiptKind,TerminalFlowSchedulerReceiptSealedStage,TerminalFlowSchedulerWakerPayload>
            state : TerminalFlowSchedulerWakerRegistryState
            registeredAtMs : int64
            consumedAtMs : int64
        }
        with
            member this.context = this.receipt.payload.context
            member this.registry = this.receipt.payload.registry
            member this.registryRef = terminalFlowSchedulerWitnessRef this.registry
            member this.contextRef = this.context.contextRef
            member this.admissionRef = this.context.admissionRef
            member this.admissionIdentityRef = this.context.admissionIdentityRef
            member this.actorBindingRef = this.context.actorBindingRef
            member this.credentialLedgerRef = this.context.credentialLedgerRef
            member this.credentialGraphClosureRef = this.context.credentialGraphClosureRef
            member this.credentialCycleProofRef = 0u
            member this.fairnessEpochRef = this.context.fairnessEpochRef
            member this.schedulerReleaseRef = terminalFlowIdentityRefDigest this.context.schedulerRelease.physicalReleaseRef
            member this.requirementRef = this.context.wakerRequirementRef
            member this.edgeRef = this.context.wakerEdgeRef
            member this.actorRef = this.context.actorRef
            member this.exactOnceDigest = terminalFlowSchedulerReceiptExactOnce this.receipt
            member this.exactOnceRef = terminalFlowMintedRefOf "scheduler_waker_projection_exact_once_ref" (CompilerIdentityKernel.ContentDigest.text this.exactOnceDigest)

        type TerminalFlowSchedulerWorkerPayload = private {
