        type TerminalFlowSchedulerWorkerHandoffReceipt = private {
            receipt : TerminalFlowSchedulerReceipt<TerminalFlowSchedulerWorkerReceiptKind,TerminalFlowSchedulerReceiptSealedStage,TerminalFlowSchedulerWorkerPayload>
            completedAtMs : int64
        }
        with
            member this.context = this.receipt.payload.context
            member this.workerJob = this.receipt.payload.workerJob
            member this.artifact = this.receipt.payload.artifact
            member this.exitWitness = this.receipt.payload.exitWitness
            member this.contextRef = this.context.contextRef
            member this.admissionRef = this.context.admissionRef
            member this.admissionIdentityRef = this.context.admissionIdentityRef
            member this.actorBindingRef = this.context.actorBindingRef
            member this.credentialLedgerRef = this.context.credentialLedgerRef
            member this.credentialGraphClosureRef = this.context.credentialGraphClosureRef
            member this.credentialCycleProofRef = 0u
            member this.fairnessEpochRef = this.context.fairnessEpochRef
            member this.schedulerReleaseRef = terminalFlowIdentityRefDigest this.context.schedulerRelease.physicalReleaseRef
            member this.workerHandoffRef = terminalFlowMintedRefOf "scheduler_worker_handoff_projection_ref" (CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerReceiptExactOnce this.receipt))
            member this.workerJobRef = terminalFlowSchedulerWitnessRef this.workerJob
            member this.artifactReceiptRef = terminalFlowSchedulerWitnessRef this.artifact
            member this.exitWitnessRef = terminalFlowSchedulerWitnessRef this.exitWitness
            member this.exactOnceDigest = terminalFlowSchedulerReceiptExactOnce this.receipt
            member this.exactOnceRef = terminalFlowMintedRefOf "scheduler_worker_projection_exact_once_ref" (CompilerIdentityKernel.ContentDigest.text this.exactOnceDigest)


        type TerminalFlowSchedulerChannelStepKind =
            | TerminalFlowSchedulerChannelAdmissionAccepted
            | TerminalFlowSchedulerChannelOutcomeFilled
            | TerminalFlowSchedulerChannelWriterBound
            | TerminalFlowSchedulerChannelArtifactCommitRequested
            | TerminalFlowSchedulerChannelWorkerCompleted
            | TerminalFlowSchedulerChannelWakerConsumedAndRegistryPruned
            | TerminalFlowSchedulerChannelFailedClosed

        let private terminalFlowSchedulerChannelStepKindText = function
            | TerminalFlowSchedulerChannelAdmissionAccepted -> "AdmissionAccepted"
            | TerminalFlowSchedulerChannelOutcomeFilled -> "OutcomeFilled"
            | TerminalFlowSchedulerChannelWriterBound -> "WriterBound"
            | TerminalFlowSchedulerChannelArtifactCommitRequested -> "ArtifactCommitRequested"
            | TerminalFlowSchedulerChannelWorkerCompleted -> "WorkerCompleted"
            | TerminalFlowSchedulerChannelWakerConsumedAndRegistryPruned -> "WakerConsumedAndRegistryPruned"
            | TerminalFlowSchedulerChannelFailedClosed -> "FailedClosed"

        type TerminalFlowSchedulerAuthorityPayload = private {
            kind : TerminalFlowSchedulerChannelStepKind
            context : TerminalFlowSchedulerChannelAdmissionContext
            actorCommand : TerminalFlowSchedulerWitness<TerminalFlowSchedulerActorCommandWitnessKind>
            stageToken : TerminalFlowSchedulerWitness<TerminalFlowSchedulerStageTokenWitnessKind> option
            wakerRegistration : TerminalFlowSchedulerWakerRegistrationReceipt
            workerHandoff : TerminalFlowSchedulerWorkerHandoffReceipt option
        }

        type TerminalFlowSchedulerChannelAuthorityReceipt = private {
            receipt : TerminalFlowSchedulerReceipt<TerminalFlowSchedulerAuthorityReceiptKind,TerminalFlowSchedulerReceiptSealedStage,TerminalFlowSchedulerAuthorityPayload>
        }
        with
            member this.kind = this.receipt.payload.kind
            member this.context = this.receipt.payload.context
            member this.actorCommand = this.receipt.payload.actorCommand
            member this.stageToken = this.receipt.payload.stageToken
            member this.wakerRegistration = this.receipt.payload.wakerRegistration
            member this.workerHandoff = this.receipt.payload.workerHandoff
            member this.contextRef = this.context.contextRef
            member this.admissionRef = this.context.admissionRef
            member this.admissionIdentityRef = this.context.admissionIdentityRef
            member this.actorBindingRef = this.context.actorBindingRef
            member this.credentialLedgerRef = this.context.credentialLedgerRef
            member this.credentialGraphClosureRef = this.context.credentialGraphClosureRef
            member this.credentialCycleProofRef = 0u
            member this.fairnessEpochRef = this.context.fairnessEpochRef
            member this.schedulerReleaseRef = terminalFlowIdentityRefDigest this.context.schedulerRelease.physicalReleaseRef
            member this.actorCommandRef = terminalFlowSchedulerWitnessRef this.actorCommand
            member this.stageTokenRef = this.stageToken |> Option.map terminalFlowSchedulerWitnessRef |> Option.defaultValue 0u
            member this.wakerRegistryRef = this.wakerRegistration.registryRef
            member this.workerHandoffRef = this.workerHandoff |> Option.map (fun handoff -> handoff.workerHandoffRef) |> Option.defaultValue 0u
            member this.exactOnceDigest = terminalFlowSchedulerReceiptExactOnce this.receipt
            member this.exactOnceRef = terminalFlowMintedRefOf "scheduler_authority_projection_exact_once_ref" (CompilerIdentityKernel.ContentDigest.text this.exactOnceDigest)

        type SomeTerminalFlowSchedulerReceipt =
            | SomeTerminalFlowSchedulerAdmissionReceipt of TerminalFlowSchedulerChannelAdmissionContext
            | SomeTerminalFlowSchedulerWakerReceipt of TerminalFlowSchedulerWakerRegistrationReceipt
            | SomeTerminalFlowSchedulerWorkerReceipt of TerminalFlowSchedulerWorkerHandoffReceipt
            | SomeTerminalFlowSchedulerAuthorityReceipt of TerminalFlowSchedulerChannelAuthorityReceipt

        // Closed existential eliminator: heterogeneous scheduler receipts can be
        // consumed through one result-polymorphic boundary instead of leaking their
        // concrete case representation into every projection. This mirrors the
        // `exists`/higher-ranked visitor shape intended for the Spiral self-host.
        type SomeTerminalFlowSchedulerReceiptVisitor<'Result> = private {
            admission : TerminalFlowSchedulerChannelAdmissionContext -> 'Result
            waker : TerminalFlowSchedulerWakerRegistrationReceipt -> 'Result
            worker : TerminalFlowSchedulerWorkerHandoffReceipt -> 'Result
            authority : TerminalFlowSchedulerChannelAuthorityReceipt -> 'Result
        }

        let private someTerminalFlowSchedulerReceiptVisit (visitor:SomeTerminalFlowSchedulerReceiptVisitor<'Result>) = function
            | SomeTerminalFlowSchedulerAdmissionReceipt context -> visitor.admission context
            | SomeTerminalFlowSchedulerWakerReceipt waker -> visitor.waker waker
            | SomeTerminalFlowSchedulerWorkerReceipt worker -> visitor.worker worker
            | SomeTerminalFlowSchedulerAuthorityReceipt authority -> visitor.authority authority

        // The scheduler ledger is now journal-sourced from a non-empty heterogeneous
        // receipt spine. Admission/waker/worker views are derived from that spine;
        // they are no longer separately mutable ledger columns.
        type TerminalFlowSchedulerReceiptSpine =
            | TerminalFlowSchedulerReceiptGenesis of SomeTerminalFlowSchedulerReceipt
            | TerminalFlowSchedulerReceiptStep of SomeTerminalFlowSchedulerReceipt * previous:TerminalFlowSchedulerReceiptSpine

        type TerminalFlowSchedulerChannelLedgerEntry = private {
            receipts : TerminalFlowSchedulerReceiptSpine
            possessionRevision : int64
        }
        with
            member this.exactOnce =
                let head =
                    match this.receipts with
                    | TerminalFlowSchedulerReceiptGenesis receipt
                    | TerminalFlowSchedulerReceiptStep(receipt, _) -> receipt
                head
                |> someTerminalFlowSchedulerReceiptVisit
                    { admission = fun context -> context.contextDigest
                      waker = fun waker -> waker.exactOnceDigest
                      worker = fun worker -> worker.exactOnceDigest
                      authority = fun authority -> authority.exactOnceDigest }
            member this.admission =
                let rec loop = function
                    | TerminalFlowSchedulerReceiptGenesis receipt
                    | TerminalFlowSchedulerReceiptStep(receipt, _) ->
                        receipt
                        |> someTerminalFlowSchedulerReceiptVisit
                            { admission = id
                              waker = fun waker -> waker.context
                              worker = fun worker -> worker.context
                              authority = fun authority -> authority.context }
                loop this.receipts
            member this.wakerRegistration =
                let tryProject receipt =
                    receipt
                    |> someTerminalFlowSchedulerReceiptVisit
                        { admission = fun _ -> None
                          waker = Some
                          worker = fun _ -> None
                          authority = fun authority -> Some authority.wakerRegistration }
                let rec loop = function
                    | TerminalFlowSchedulerReceiptGenesis receipt ->
                        match tryProject receipt with
                        | Some waker -> waker
                        | None -> invalidOp "scheduler receipt spine has no waker receipt"
                    | TerminalFlowSchedulerReceiptStep(receipt, previous) ->
                        match tryProject receipt with
                        | Some waker -> waker
                        | None -> loop previous
                loop this.receipts
            member this.workerHandoff =
                let tryProject receipt =
                    receipt
                    |> someTerminalFlowSchedulerReceiptVisit
                        { admission = fun _ -> None
                          waker = fun _ -> None
                          worker = Some
                          authority = fun authority -> authority.workerHandoff }
                let rec loop = function
                    | TerminalFlowSchedulerReceiptGenesis receipt -> tryProject receipt
                    | TerminalFlowSchedulerReceiptStep(receipt, previous) ->
                        match tryProject receipt with
                        | Some worker -> Some worker
                        | None -> loop previous
                loop this.receipts
            member this.admissionRef = this.admission.admissionRef
            member this.contextRef = this.admission.contextRef
            member this.credentialGraphClosureRef = this.admission.credentialGraphClosureRef
            member this.credentialCycleProofRef = 0u
            member this.exactOnceRef = terminalFlowMintedRefOf "scheduler_ledger_projection_exact_once_ref" (CompilerIdentityKernel.ContentDigest.text this.exactOnce)

        type TerminalFlowResolvedOutcomeEnvelope = private {
            rootCapability : TerminalFlowRootCapability<TerminalFlowRootResolvedState>
            causalIdentity : TerminalFlowCausalIdentity
            boundary : TerminalFlowCertificateBoundaryId
            stickyTailGate : TerminalFlowStickyTailGateId
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            fillKey : TerminalFlowFillKeyId
            ownerClosure : TerminalFlowOwnerClosureCertificate
            nativeRootBridge : TerminalFlowNativeRootBridge
            kindBridge : TerminalFlowKindBridgeReceipt
            schedulerContext : TerminalFlowSchedulerChannelAdmissionContext
        }

        type TerminalFlowOutcomeIvarCell<'State> = private {
