        type TerminalFlowExitReason =
            | TerminalFlowExitReasonWriterBuildOkReceiptConsumed
            | TerminalFlowExitReasonWriterFailClosedReceiptConsumed
            | TerminalFlowExitReasonTerminalAuthorityRejected of reasonRef:uint32

        let private terminalFlowExitReasonText = function
            | TerminalFlowExitReasonWriterBuildOkReceiptConsumed -> "writer_build_ok_receipt_consumed"
            | TerminalFlowExitReasonWriterFailClosedReceiptConsumed -> "writer_fail_closed_receipt_consumed"
            | TerminalFlowExitReasonTerminalAuthorityRejected reasonRef -> sprintf "terminal_authority_rejected:%u" reasonRef

        type TerminalFlowExitWitness = private {
            witnessId : string
            tokenId : string
            writerJobId : string
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            exitCode : int
            reason : TerminalFlowExitReason
            exitStage : TerminalFlowStageCapability<TerminalFlowRootResolvedStage,TerminalFlowOutcomeSealedStage,TerminalFlowWriterBoundStage,TerminalFlowArtifactCommittedStage,TerminalFlowExitWitnessedKernelStage>
        }

        let rec private terminalFlowTerminalStagePossessionStableText = function
            | TerminalFlowTerminalStageGenesis(actorRef, dispatchRef) ->
                sprintf "genesis:%u:%u" actorRef dispatchRef
            | TerminalFlowTerminalStageStep(stageRef, receiptRef, previous) ->
                FastRuntimeFormat.format "step:%u:%u:%s" [| box stageRef; box receiptRef; box (terminalFlowTerminalStagePossessionStableText previous) |]

        let private terminalFlowTerminalStagePossessionRef possession =
            terminalFlowMintedRefOf "terminal_stage_possession_ref" (terminalFlowTerminalStagePossessionStableText possession)

        let private terminalFlowTerminalStageTokenText stage (token:TerminalFlowTerminalStageToken<'Stage,'WakerStage>) =
            FastRuntimeFormat.format "TerminalFlowTerminalStageToken(%s|token_ref=%u|actor_ref=%u|fill_ref=%u|terminal_ref=%u|tx_ref=%u|dispatch_ref=%u|waker_requirement_ref=%u|waker_edge_ref=%u|possession_ref=%u)" [| box stage; box (terminalFlowMintedRefOf "terminal_stage_token_ref" token.tokenId); box token.actorRef; box (TerminalFlowFillKeyId.digest token.fillKey); box (terminalFlowIdentityRefDigest token.terminalReceiptRef); box (terminalFlowMintedRefOf "owner_transaction_ref" token.ownerTransactionId); box (terminalFlowMintedRefOf "dispatch_ref" token.dispatchId); box token.wakerEdge.requirementRef; box token.wakerEdge.edgeRef; box (terminalFlowTerminalStagePossessionRef token.possession) |]

        let private terminalFlowSealedTokenForDispatch dispatchId (envelope:TerminalFlowResolvedOutcomeEnvelope) : Result<TerminalFlowTerminalStageToken<TerminalFlowReceiptSealedStage,TerminalFlowWakerRegisteredStage>,string> =
            let actorRef = terminalFlowMintedRefOf "push_actor_ref" dispatchId
            let requirementRef = terminalFlowMintedRefOf "push_actor_waker_requirement_ref" envelope.ownerClosure.transaction.transactionId
            match envelope.nativeRootBridge.authority with
            | TerminalFlowNativeRootBridgeFromStageToken(_, _, _, wakerEdgeRef) when wakerEdgeRef <> 0u ->
                let tokenId = "terminal-sealed:" + TerminalFlowFillKeyId.text envelope.fillKey + ":" + terminalFlowIdentityRefText envelope.terminalReceiptRef
                let dispatchRef = terminalFlowMintedRefOf "dispatch_ref" dispatchId
                let stageRef = terminalFlowMintedRefOf "terminal_stage_token_ref" tokenId
                let wakerEdge : TerminalFlowPushOwnedWakerEdge<TerminalFlowWakerRegisteredStage> = {
                    requirementRef = requirementRef
                    edgeRef = wakerEdgeRef
                    actorRef = actorRef
                    registeredAtMs = Environment.TickCount64
                    consumedAtMs = 0L
                }
                Ok {
                    tokenId = tokenId
                    fillKey = envelope.fillKey
                    terminalReceiptRef = envelope.terminalReceiptRef
                    ownerTransactionId = envelope.ownerClosure.transaction.transactionId
                    dispatchId = dispatchId
                    actorRef = actorRef
                    wakerEdge = wakerEdge
                    possession = TerminalFlowTerminalStageStep(stageRef, wakerEdgeRef, TerminalFlowTerminalStageGenesis(actorRef, dispatchRef))
                }
            | TerminalFlowNativeRootBridgeFromStageToken _ ->
                Error "push_owned_stage_token_waker_edge_missing"
            | TerminalFlowNativeRootBridgeFromNativeWriterCapability _ ->
                Error "legacy_native_writer_bridge_cannot_mint_push_owned_stage_token"

        let private terminalFlowConsumeSealedToken
            (sealedToken:TerminalFlowTerminalStageToken<TerminalFlowReceiptSealedStage,TerminalFlowWakerRegisteredStage>)
            (writerReceipt:TerminalFlowWriterJobReceipt)
            : Result<TerminalFlowTerminalStageToken<TerminalFlowReceiptConsumedStage,TerminalFlowWakerConsumedStage>,string> =
            if writerReceipt.terminalReceiptRef <> sealedToken.terminalReceiptRef then
                Error ("sealed_token_terminal_receipt_mismatch|sealed=" + terminalFlowIdentityRefText sealedToken.terminalReceiptRef + "|writer=" + terminalFlowIdentityRefText writerReceipt.terminalReceiptRef)
            elif writerReceipt.ownerTransactionId <> sealedToken.ownerTransactionId then
                Error ("sealed_token_owner_transaction_mismatch|sealed=" + sealedToken.ownerTransactionId + "|writer=" + writerReceipt.ownerTransactionId)
            elif sealedToken.wakerEdge.edgeRef = 0u then
                Error "sealed_token_waker_edge_not_registered"
            else
                let consumedAtMs = Environment.TickCount64
                let consumedWaker : TerminalFlowPushOwnedWakerEdge<TerminalFlowWakerConsumedStage> = {
                    requirementRef = sealedToken.wakerEdge.requirementRef
                    edgeRef = sealedToken.wakerEdge.edgeRef
                    actorRef = sealedToken.actorRef
                    registeredAtMs = sealedToken.wakerEdge.registeredAtMs
                    consumedAtMs = consumedAtMs
                }
                let tokenId = "terminal-consumed:" + sealedToken.tokenId
                let stageRef = terminalFlowMintedRefOf "terminal_stage_token_ref" tokenId
                Ok {
                    tokenId = tokenId
                    fillKey = sealedToken.fillKey
                    terminalReceiptRef = sealedToken.terminalReceiptRef
                    ownerTransactionId = sealedToken.ownerTransactionId
                    dispatchId = sealedToken.dispatchId
                    actorRef = sealedToken.actorRef
                    wakerEdge = consumedWaker
                    possession = TerminalFlowTerminalStageStep(stageRef, sealedToken.wakerEdge.edgeRef, sealedToken.possession)
                }

        let private terminalFlowExitWitnessForConsumedToken
            (consumedToken:TerminalFlowTerminalStageToken<TerminalFlowReceiptConsumedStage,TerminalFlowWakerConsumedStage>)
            (writerReceipt:TerminalFlowWriterJobReceipt)
            : TerminalFlowExitWitness =
            let exitCode =
                match writerReceipt.artifactReceipt.execution, writerReceipt.physicalBoundary with
                | TerminalFlowArtifactsExecuted(_, committedHash, intents),
                  TerminalFlowPhysicalBoundaryOwnedByWriterReceipt(writerJobId, boundaryHash)
                    when not (List.isEmpty intents)
                         && committedHash = boundaryHash
                         && writerJobId = writerReceipt.writerJobId -> 0
                | _ -> 1
            let witnessId = "terminal-exit-witness:" + consumedToken.tokenId + ":" + writerReceipt.writerJobId
            let exitStage =
                terminalFlowStageCapability
                    TerminalFlowKernelStageExitWitnessed
                    writerReceipt.artifactCommittedStage.rootRef
                    writerReceipt.artifactCommittedStage.terminalRef
                    writerReceipt.artifactCommittedStage.fillRef
                    writerReceipt.artifactCommittedStage.dispatchRef
                    writerReceipt.artifactCommittedStage.writerRef
                    writerReceipt.artifactCommittedStage.artifactRef
                    (terminalFlowMintedRefOf "exit_witness_ref" witnessId)
            { witnessId = witnessId
              tokenId = consumedToken.tokenId
              writerJobId = writerReceipt.writerJobId
              terminalReceiptRef = consumedToken.terminalReceiptRef
              exitCode = exitCode
              reason = if exitCode = 0 then TerminalFlowExitReasonWriterBuildOkReceiptConsumed else TerminalFlowExitReasonWriterFailClosedReceiptConsumed
              exitStage = exitStage }

        let private terminalFlowExitWitnessText (witness:TerminalFlowExitWitness) =
            FastRuntimeFormat.format "TerminalFlowExitWitness(witness_ref=%u|token_ref=%u|writer_ref=%u|terminal_ref=%u|exit_code=%d|exit_stage_ref=%u|reason=%s)" [| box (terminalFlowMintedRefOf "exit_witness_ref" witness.witnessId); box (terminalFlowMintedRefOf "terminal_stage_token_ref" witness.tokenId); box (terminalFlowMintedRefOf "writer_job_ref" witness.writerJobId); box (terminalFlowIdentityRefDigest witness.terminalReceiptRef); box witness.exitCode; box (terminalFlowStageRef witness.exitStage); box (terminalFlowExitReasonText witness.reason) |]

        type TerminalFlowCommitFilled = private {
            prepared : TerminalFlowCommitPrepared
            filledCell : TerminalFlowOutcomeIvarCell<TerminalFlowOutcomeFilledState>
            fillReceipt : TerminalFlowOutcomeFillReceipt
            sealedToken : TerminalFlowTerminalStageToken<TerminalFlowReceiptSealedStage,TerminalFlowWakerRegisteredStage>
        }

        type TerminalFlowCommitWriterBound = private {
            filled : TerminalFlowCommitFilled
            writer : TerminalFlowWriterCapability<TerminalFlowWriterBoundState>
        }

        type TerminalFlowCommitCompleted = private {
            bound : TerminalFlowCommitWriterBound
            writerReceipt : TerminalFlowWriterJobReceipt
            consumedToken : TerminalFlowTerminalStageToken<TerminalFlowReceiptConsumedStage,TerminalFlowWakerConsumedStage>
            exitWitness : TerminalFlowExitWitness
        }

        type TerminalFlowNativeHandoffId =
            | TerminalFlowNativeHandoffAwaitingResolvedRoot of CompilerKernelV2.OperationalReasonId
            | TerminalFlowNativeHandoffCommitBlocked of fillKey:string * whyNot:TerminalFlowWhyNotTerminalCommitId * TerminalFlowOwnerCloseDecisionId
            | TerminalFlowNativeHandoffAwaitingTerminalOutcome of TerminalFlowRootCapability<TerminalFlowRootResolvedState> * key:string * TerminalFlowOwnerCloseDecisionId
            | TerminalFlowNativeHandoffOutcomeIvarArmed of cellId:string * key:string * TerminalFlowRootCapability<TerminalFlowRootResolvedState> * TerminalFlowOwnerCloseDecisionId
            | TerminalFlowNativeHandoffPushDispatched of dispatchId:string * cellId:string * fillKey:string * TerminalFlowOwnerCloseDecisionId
            | TerminalFlowNativeHandoffGlobalServerQueued of requestId:string * fillKey:string * TerminalFlowOwnerCloseDecisionId
            | TerminalFlowNativeHandoffCompleted of TerminalFlowCommitCompleted
            | TerminalFlowNativeHandoffFailClosed of CompilerKernelV2.OperationalReasonId * TerminalFlowNativeSchedulerAuthorityId

        let private terminalFlowNativeHandoffFailClosed reason =
            let reasonId = CompilerKernelV2.OperationalReasonIdOps.create reason
            TerminalFlowNativeHandoffFailClosed(reasonId, TerminalFlowNativeSchedulerFailClosed reasonId)

        // Destructive scheduler-domain migration:
        // Post-root liveness is push-driven. The join loop may enqueue one typed
        // event and project its dispatch receipt, but it cannot run the terminal
        // pipeline, inspect scheduler queues, bind the writer, or authorize exit.
        // A single Hopac actor owns the monotone event chain and the physical
        // terminal boundary.
        type TerminalFlowSchedulerPushEventId =
            | TerminalFlowPushResolvedOutcome of TerminalFlowCommitPrepared
            | TerminalFlowPushOutcomeFilled of TerminalFlowCommitFilled
            | TerminalFlowPushWriterCapabilityBound of TerminalFlowCommitWriterBound
            | TerminalFlowPushArtifactCommitRequested of TerminalFlowCommitWriterBound
            | TerminalFlowPushWriterCompleted of TerminalFlowCommitCompleted
            | TerminalFlowPushRegistryPrune of fillKey:TerminalFlowFillKeyId * TerminalFlowCommitCompleted
            | TerminalFlowPushFailClosed of fillKey:TerminalFlowFillKeyId * CompilerKernelV2.OperationalReasonId

        let private terminalFlowPushFailClosed (fillKey:TerminalFlowFillKeyId) reason =
            TerminalFlowPushFailClosed(fillKey, CompilerKernelV2.OperationalReasonIdOps.create reason)

        type TerminalFlowSchedulerChannelCommandShape = private {
            eventCode : byte
            kind : TerminalFlowSchedulerChannelStepKind
            actorCommand : TerminalFlowSchedulerWitness<TerminalFlowSchedulerActorCommandWitnessKind>
            stageToken : TerminalFlowSchedulerWitness<TerminalFlowSchedulerStageTokenWitnessKind> option
        }

        type TerminalFlowSchedulerPushPossessionSpine =
            | TerminalFlowPushPossessionGenesis of TerminalFlowSchedulerChannelAuthorityReceipt
            | TerminalFlowPushPossessionStep of TerminalFlowSchedulerChannelAuthorityReceipt * previous:TerminalFlowSchedulerPushPossessionSpine

        type TerminalFlowSchedulerChannelOpenStage = class end
        type TerminalFlowSchedulerChannelSealedStage = class end

        type TerminalFlowSchedulerChannelRootAuthority<'Stage> = private {
            context : TerminalFlowSchedulerChannelAdmissionContext
            ledger : TerminalFlowSchedulerChannelLedgerEntry
            possession : TerminalFlowSchedulerPushPossessionSpine
            rootDigest : CompilerIdentityKernel.ContentDigest
        }
        with
            member this.rootRef =
                terminalFlowMintedRefOf
                    "scheduler_channel_root_projection_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.rootDigest)
            member this.exactOnceRef =
                terminalFlowMintedRefOf
                    "scheduler_channel_root_projection_exact_once_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.rootDigest)

        type TerminalFlowSchedulerPushDispatch = private {
            dispatchIdentity : CompilerIdentityKernel.ContentDigest
            fillKeyId : TerminalFlowFillKeyId
            closeDecision : TerminalFlowOwnerCloseDecisionId
            tag : string
            event : TerminalFlowSchedulerPushEventId
            channelAuthority : TerminalFlowSchedulerChannelRootAuthority<TerminalFlowSchedulerChannelSealedStage>
            completion : CompilerKernelV2.PortableOneShotCell<TerminalFlowNativeHandoffId>
        }
        with
            member this.dispatchId = CompilerIdentityKernel.ContentDigest.text this.dispatchIdentity
            member this.fillKey = TerminalFlowFillKeyId.text this.fillKeyId

        type TerminalFlowSchedulerPushReceipt = private {
            dispatchIdentity : CompilerIdentityKernel.ContentDigest
            accepted : bool
            channelAuthority : TerminalFlowSchedulerChannelRootAuthority<TerminalFlowSchedulerChannelSealedStage>
            wakerRegistration : TerminalFlowSchedulerWakerRegistrationReceipt
            possession : TerminalFlowSchedulerPushPossessionSpine
            eventCode : byte
            completionCellId : string
        }
        with
            member this.dispatchId = CompilerIdentityKernel.ContentDigest.text this.dispatchIdentity
            member this.contextRef = this.channelAuthority.context.contextRef
            member this.admissionRef = this.channelAuthority.context.admissionRef
            member this.admissionIdentityRef = this.channelAuthority.context.admissionIdentityRef
            member this.actorBindingRef = this.channelAuthority.context.actorBindingRef
            member this.credentialLedgerRef = this.channelAuthority.context.credentialLedgerRef
            member this.credentialGraphClosureRef = this.channelAuthority.context.credentialGraphClosureRef
            member this.credentialCycleProofRef = this.channelAuthority.context.credentialCycleProofRef
            member this.fairnessEpochRef = this.channelAuthority.context.fairnessEpochRef
            member this.schedulerReleaseRef = terminalFlowIdentityRefDigest this.channelAuthority.context.schedulerRelease.physicalReleaseRef
            member this.wakerRegistryRef = this.wakerRegistration.registryRef
                member this.channelRootRef = this.channelAuthority.rootRef
            member this.channelRootExactOnceRef = this.channelAuthority.exactOnceRef

        let private terminalFlowRootObservationText = function
            | TerminalFlowRootNotObserved -> "root:not_observed"
            | TerminalFlowRootPending -> "root:pending"
            | TerminalFlowRootResolved receiptId -> "root:resolved:" + receiptId
            | TerminalFlowRootResolvedWithoutReceipt evidence -> "root:resolved_without_receipt:" + evidence

