        let private terminalFlowMaterialActivitySourceText = function
            | TerminalFlowMaterialDelta -> "material_delta"
            | TerminalFlowFreshTopologyWitness -> "fresh_topology_witness"

        let private terminalFlowProceduralActivitySourceText = function
            | TerminalFlowReplayChatter -> "replay_chatter"
            | TerminalFlowOwnerDrainSelfChurn -> "owner_drain_self_churn"
            | TerminalFlowBoundaryTelemetryEcho -> "boundary_telemetry_echo"
            | TerminalFlowRootSignalChurn -> "root_signal_churn"
            | TerminalFlowTerminalSignalChurn -> "terminal_signal_churn"
            | TerminalFlowInjectionChurn -> "injection_churn"

        let private terminalFlowReceiptRefOfText (value:string) : TerminalFlowReceiptRef<'Kind> =
            if String.IsNullOrWhiteSpace value || value = "-" then TerminalFlowReceiptMissing
            else TerminalFlowReceiptPresent value

        let private terminalFlowReceiptRefTextOr fallback = function
            | TerminalFlowReceiptPresent value -> value
            | TerminalFlowReceiptMissing -> fallback

        let private terminalFlowMaterialActivityToken source ageMs count : TerminalFlowActivityToken<TerminalFlowMaterialActivityKind,TerminalFlowMaterialActivitySourceId> =
            { source = source; ageMs = max 0L ageMs; count = max 0L count }

        let private terminalFlowProceduralActivityToken source ageMs count : TerminalFlowActivityToken<TerminalFlowProceduralActivityKind,TerminalFlowProceduralActivitySourceId> =
            { source = source; ageMs = max 0L ageMs; count = max 0L count }

        let private terminalFlowActivityTokenText kind sourceText (token:TerminalFlowActivityToken<'Kind,'Source>) =
            FastRuntimeFormat.format "activity:%s|source=%s|age_ms=%d|count=%d" [| box kind; box (sourceText token.source); box token.ageMs; box token.count |]

        let private terminalFlowActivityObservationText = function
            | TerminalFlowMaterialActivityRecent token -> terminalFlowActivityTokenText "material_recent" terminalFlowMaterialActivitySourceText token
            | TerminalFlowMaterialQuiescent(materialAgeMs, None) -> sprintf "activity:material_quiescent|age_ms=%d|procedural=none" materialAgeMs
            | TerminalFlowMaterialQuiescent(materialAgeMs, Some procedural) ->
                sprintf "activity:material_quiescent|age_ms=%d|%s" materialAgeMs (terminalFlowActivityTokenText "procedural_churn" terminalFlowProceduralActivitySourceText procedural)

        let private terminalFlowQapBoundednessText = function
            | TerminalFlowQapBounded -> "bounded"
            | TerminalFlowQapUnbounded -> "unbounded"

        let private terminalFlowQapOccupancyText = function
            | TerminalFlowQapEmpty -> "empty"
            | TerminalFlowQapResidual -> "residual"

        let private terminalFlowQapIsBounded (x:TerminalFlowQapObservation) =
            match x.boundedness with
            | TerminalFlowQapBounded -> true
            | TerminalFlowQapUnbounded -> false

        let private terminalFlowQapHasResidual (x:TerminalFlowQapObservation) =
            match x.occupancy with
            | TerminalFlowQapResidual -> true
            | TerminalFlowQapEmpty -> false

        let private terminalFlowRejectedQapObservation pending queue active : TerminalFlowQapObservation =
            let sampledEvidence = max 0 pending
            let quarantineRef =
                NativeCutoverStableRef.ref32
                    "rejected-qap-synthetic"
                    [ string sampledEvidence; string queue; string active ]
            let safeCanonical = 1
            let provenance =
                { rawPending = sampledEvidence
                  frontierPending = 0
                  canonicalPending = safeCanonical
                  authority = TerminalFlowPendingFrontierUnavailableQuarantine quarantineRef
                  decrementReceipts = []
                  decision = TerminalFlowPendingDecisionBlockedWithoutFrontier(sampledEvidence, TerminalFlowPendingRejectedSyntheticObservation, quarantineRef) }
            { pending = safeCanonical
              pendingProvenance = provenance
              queue = queue
              active = active
              semanticLedgerState = SemanticWorkOpen(1L, 0L, 1L)
              semanticOpen = 1L
              boundedness = TerminalFlowQapUnbounded
              occupancy = TerminalFlowQapResidual }

        let private terminalFlowQapFixpointMaturityText = function
            | TerminalFlowQapFixpointAwaitingReducerWitness -> "awaiting_reducer_witness"
            | TerminalFlowQapFixpointCandidateObserved -> "candidate_observed"
            | TerminalFlowQapFixpointWitnessedByReducer -> "witnessed_by_reducer"

        let private terminalFlowQapFixpointIsCandidate = function
            | TerminalFlowQapFixpointCandidateObserved -> true
            | TerminalFlowQapFixpointAwaitingReducerWitness
            | TerminalFlowQapFixpointWitnessedByReducer -> false

        let private terminalFlowPendingLedgerAuthorityText = function
            | TerminalFlowPendingFrontierAuthoritative -> "frontier_authoritative"
            | TerminalFlowPendingFrontierReconciledGhosts -> "frontier_reconciled_ghosts"
            | TerminalFlowPendingFrontierUnavailableRawZeroClosed closeReceiptRef -> "frontier_unavailable_raw_zero_closed:" + string closeReceiptRef
            | TerminalFlowPendingFrontierUnavailableReducerClosed closeReceiptRef -> "frontier_unavailable_reducer_closed:" + string closeReceiptRef
            | TerminalFlowPendingFrontierUnavailableQuarantine quarantineRef -> "frontier_unavailable_quarantine:" + string quarantineRef

        let private terminalFlowPendingDecrementSourceText = function
            | TerminalFlowPendingDecrementInlineCallbackCommit -> "inline_callback_commit"
            | TerminalFlowPendingDecrementReducerFrontierReconcile -> "reducer_frontier_reconcile"
            | TerminalFlowPendingDecrementReducerClosedProjection -> "reducer_closed_projection"
            | TerminalFlowPendingDecrementParentCommit -> "parent_commit"
            | TerminalFlowPendingDecrementUnknown raw -> "unknown:" + raw

        let private terminalFlowPendingQuarantineReasonText = function
            | TerminalFlowPendingRejectedSyntheticObservation -> "rejected_synthetic_observation"
            | TerminalFlowPendingFrontierSnapshotMissing -> "frontier_snapshot_missing"

        let private terminalFlowPendingDecisionText = function
            | TerminalFlowPendingDecisionFrontierCanonical canonicalPending -> sprintf "frontier_canonical:%d" canonicalPending
            | TerminalFlowPendingDecisionRawZeroClosedWithoutFrontier closeReceiptRef ->
                sprintf "raw_zero_closed_without_frontier:receipt=%u" closeReceiptRef
            | TerminalFlowPendingDecisionReducerClosedWithoutFrontier closeReceiptRef ->
                sprintf "reducer_closed_without_frontier:receipt=%u" closeReceiptRef
            | TerminalFlowPendingDecisionBlockedWithoutFrontier(sampledEvidence, reason, quarantineRef) ->
                FastRuntimeFormat.format "blocked_without_frontier:sampled=%d:reason=%s:quarantine=%u" [| box sampledEvidence; box (terminalFlowPendingQuarantineReasonText reason); box quarantineRef |]

        let private terminalFlowPendingDecrementReceiptText (x:TerminalFlowPendingDecrementReceipt) =
            FastRuntimeFormat.format "decrement(source=%s|raw=%d->%d|frontier=%d|canonical=%d|receipt=%u)" [| box (terminalFlowPendingDecrementSourceText x.source); box x.beforeRaw; box x.afterRaw; box x.frontierPending; box x.canonicalPending; box x.exactOnceRef |]

        let private terminalFlowPendingDecrementReceiptsFor raw frontier canonical authority =
            if raw > canonical then
                let source =
                    match authority with
                    | TerminalFlowPendingFrontierReconciledGhosts -> TerminalFlowPendingDecrementReducerFrontierReconcile
                    | TerminalFlowPendingFrontierAuthoritative -> TerminalFlowPendingDecrementInlineCallbackCommit
                    | TerminalFlowPendingFrontierUnavailableRawZeroClosed _ -> TerminalFlowPendingDecrementUnknown "raw_zero_closed_no_decrement"
                    | TerminalFlowPendingFrontierUnavailableReducerClosed _ -> TerminalFlowPendingDecrementReducerClosedProjection
                    | TerminalFlowPendingFrontierUnavailableQuarantine _ -> TerminalFlowPendingDecrementUnknown "frontier_unavailable_no_decrement_authority"
                [ { source = source
                    beforeRaw = raw
                    afterRaw = canonical
                    frontierPending = frontier
                    canonicalPending = canonical
                    exactOnceRef =
                        NativeCutoverStableRef.ref32
                            "terminal-pending-decrement"
                            [ terminalFlowPendingDecrementSourceText source
                              string raw
                              string frontier
                              string canonical
                              terminalFlowPendingLedgerAuthorityText authority ] } ]
            else
                []

        let private terminalFlowPendingProvenanceFor rawPending frontierPending frontierAvailable closureProof =
            let raw = max 0 rawPending
            let frontier = max 0 frontierPending
            if frontierAvailable then
                let authority = if raw = frontier then TerminalFlowPendingFrontierAuthoritative else TerminalFlowPendingFrontierReconciledGhosts
                let canonical = frontier
                { rawPending = raw
                  frontierPending = frontier
                  canonicalPending = canonical
                  authority = authority
                  decrementReceipts = terminalFlowPendingDecrementReceiptsFor raw frontier canonical authority
                  decision = TerminalFlowPendingDecisionFrontierCanonical canonical }
            else
                match closureProof with
                | TerminalFlowPendingClosureReducerExact closeReceiptRef ->
                    let authority = TerminalFlowPendingFrontierUnavailableReducerClosed closeReceiptRef
                    { rawPending = raw
                      frontierPending = frontier
                      canonicalPending = 0
                      authority = authority
                      decrementReceipts = terminalFlowPendingDecrementReceiptsFor raw frontier 0 authority
                      decision = TerminalFlowPendingDecisionReducerClosedWithoutFrontier closeReceiptRef }
                | TerminalFlowPendingClosureUnproven when raw = 0 && frontier = 0 ->
                    let closeReceiptRef =
                        NativeCutoverStableRef.ref32
                            "frontier-snapshot-missing-raw-zero-closed"
                            [ string raw; string frontier ]
                    { rawPending = raw
                      frontierPending = frontier
                      canonicalPending = 0
                      authority = TerminalFlowPendingFrontierUnavailableRawZeroClosed closeReceiptRef
                      decrementReceipts = []
                      decision = TerminalFlowPendingDecisionRawZeroClosedWithoutFrontier closeReceiptRef }
                | TerminalFlowPendingClosureUnproven ->
                    let quarantineRef =
                        NativeCutoverStableRef.ref32
                            "frontier-snapshot-missing"
                            [ string raw; string frontier ]
                    let authority = TerminalFlowPendingFrontierUnavailableQuarantine quarantineRef
                    let safeCanonical = max 1 raw
                    { rawPending = raw
                      frontierPending = frontier
                      canonicalPending = safeCanonical
                      authority = authority
                      decrementReceipts = []
                      decision = TerminalFlowPendingDecisionBlockedWithoutFrontier(raw, TerminalFlowPendingFrontierSnapshotMissing, quarantineRef) }

        let private terminalFlowPendingProvenanceText (x:TerminalFlowPendingProvenance) =
            let decrementText = x.decrementReceipts |> List.map terminalFlowPendingDecrementReceiptText |> String.concat ";"
            FastRuntimeFormat.format "pending(raw=%d|frontier=%d|canonical=%d|authority=%s|decision=%s|decrement_receipts=%d|decrements=%s)" [| box x.rawPending; box x.frontierPending; box x.canonicalPending; box (terminalFlowPendingLedgerAuthorityText x.authority); box (terminalFlowPendingDecisionText x.decision); box x.decrementReceipts.Length; box decrementText |]

        let private terminalFlowQapObservationText (x:TerminalFlowQapObservation) =
            FastRuntimeFormat.format "qap:p=%d/q=%d/a=%d|%s|boundedness=%s|occupancy=%s" [| box x.pending; box x.queue; box x.active; box (terminalFlowPendingProvenanceText x.pendingProvenance); box (terminalFlowQapBoundednessText x.boundedness); box (terminalFlowQapOccupancyText x.occupancy) |]

        let private terminalFlowQapFixpointRefText (TerminalFlowQapFixpointRef value) =
            CompilerIdentityKernel.InternedTextId.text value

        let private terminalFlowQapFixpointSiteText = function
            | TerminalFlowQapCacheHandoffApplyArg0Child -> "cache_handoff_child_apply_arg_0"
            | TerminalFlowQapParentContinuationPoison -> "parent_continuation_poison"
            | TerminalFlowQapDynamicBridgePoison -> "dynamic_bridge_poison"
            | TerminalFlowQapPendingOwner -> "pending_owner"
            | TerminalFlowQapUnknownSite raw ->
                "unknown:" + TerminalFlowQapUnknownTextIdOps.text raw

        let private terminalFlowQapNodeIdText = function
            | TerminalFlowQapCacheHandoffChildApplyArg0Node -> "cache_handoff@child:*:apply_arg_0"
            | TerminalFlowQapParentPoisonTerminalTailNode -> "parent_poison@terminal_tail"
            | TerminalFlowQapPendingOwnerTerminalTailNode -> "pending_owner@terminal_tail"
            | TerminalFlowQapUnknownNode raw ->
                "unknown:" + TerminalFlowQapUnknownTextIdOps.text raw

        let private terminalFlowQapEvidenceWitnessText = function
            | TerminalFlowQapPrimaryFixpointWitness -> "terminal_qap_fixpoint_primary"
            | TerminalFlowQapActiveTailWitness -> "terminal_qap_fixpoint_active"
            | TerminalFlowQapPendingOwnerWitness -> "terminal_qap_fixpoint_pending"
            | TerminalFlowQapUnknownWitness raw ->
                "unknown:" + TerminalFlowQapUnknownTextIdOps.text raw

        let private terminalFlowQapRelationKindText = function
            | TerminalFlowQapCacheHandoffEdge -> "cache_handoff"
            | TerminalFlowQapParentContinuationEdge -> "parent_continuation"
            | TerminalFlowQapDynamicBridgeEdge -> "dynamic_bridge"
            | TerminalFlowQapPendingOwnerEdge -> "pending_owner"

        let private terminalFlowQapRelationConsumptionText = function
            | TerminalFlowQapRelationUnconsumed -> "unconsumed"
            | TerminalFlowQapRelationConsumedExactOnce(receiptRef, reducerSequence) -> sprintf "consumed_exact_once:receipt=%u:seq=%d" receiptRef reducerSequence
            | TerminalFlowQapRelationConsumptionRejected reason ->
                "consumption_rejected:" + TerminalFlowQapRelationRejectionReasonId.text reason

        let rec private terminalFlowQapRelationText = function
            | TerminalFlowQapRelationLeaf(node, witness, consumption) ->
                FastRuntimeFormat.format "Leaf(node=%s|witness=%s|consumption=%s)" [| box (terminalFlowQapNodeIdText node); box (terminalFlowQapEvidenceWitnessText witness); box (terminalFlowQapRelationConsumptionText consumption) |]
            | TerminalFlowQapRelationParentChild(parent, edge, child, consumption) ->
                FastRuntimeFormat.format "ParentChild(parent=%s|edge=%s|child=%s|consumption=%s)" [| box (terminalFlowQapNodeIdText parent); box (terminalFlowQapRelationKindText edge); box (terminalFlowQapRelationText child); box (terminalFlowQapRelationConsumptionText consumption) |]
            | TerminalFlowQapRelationCycle(head, edge, path, consumption) ->
                FastRuntimeFormat.format "Cycle(head=%s|edge=%s|path=[%s]|consumption=%s)" [| box (terminalFlowQapNodeIdText head); box (terminalFlowQapRelationKindText edge); box (path |> List.map terminalFlowQapRelationText |> String.concat ";"); box (terminalFlowQapRelationConsumptionText consumption) |]

        let private terminalFlowQapRelationFor site node witness =
            let pendingConsumption = TerminalFlowQapRelationUnconsumed
            let leaf = TerminalFlowQapRelationLeaf(node, witness, pendingConsumption)
            match site with
            | TerminalFlowQapCacheHandoffApplyArg0Child ->
                TerminalFlowQapRelationParentChild(TerminalFlowQapParentPoisonTerminalTailNode, TerminalFlowQapCacheHandoffEdge, leaf, pendingConsumption)
            | TerminalFlowQapParentContinuationPoison ->
                TerminalFlowQapRelationCycle(TerminalFlowQapParentPoisonTerminalTailNode, TerminalFlowQapParentContinuationEdge, [leaf], pendingConsumption)
            | TerminalFlowQapDynamicBridgePoison ->
                TerminalFlowQapRelationParentChild(TerminalFlowQapParentPoisonTerminalTailNode, TerminalFlowQapDynamicBridgeEdge, leaf, pendingConsumption)
            | TerminalFlowQapPendingOwner ->
                TerminalFlowQapRelationParentChild(TerminalFlowQapPendingOwnerTerminalTailNode, TerminalFlowQapPendingOwnerEdge, leaf, pendingConsumption)
            | TerminalFlowQapUnknownSite _ -> leaf

        let rec private terminalFlowQapRelationConsume reducerSequence relation =
            let existingReceiptRef =
                match relation with
                | TerminalFlowQapRelationLeaf(_, _, TerminalFlowQapRelationConsumedExactOnce(existingRef, _))
                | TerminalFlowQapRelationParentChild(_, _, _, TerminalFlowQapRelationConsumedExactOnce(existingRef, _))
                | TerminalFlowQapRelationCycle(_, _, _, TerminalFlowQapRelationConsumedExactOnce(existingRef, _)) -> Some existingRef
                | _ -> None
            match existingReceiptRef with
            | Some existingRef ->
                TerminalFlowQapRelationProtocolConsumed(relation, existingRef)
            | None ->
                // Reducer sequence records when consumption was observed; it is not
                // receipt identity. One causal relation owns one receipt.
                let receiptRef =
                    terminalFlowQapLocalMintedRefOf
                        "qap_relation_consumption_ref"
                        (terminalFlowQapRelationText relation)
                let consumed = TerminalFlowQapRelationConsumedExactOnce(receiptRef, reducerSequence)
                let consumedRelation =
                    match relation with
                    | TerminalFlowQapRelationLeaf(node, witness, TerminalFlowQapRelationUnconsumed) ->
                        TerminalFlowQapRelationLeaf(node, witness, consumed)
                    | TerminalFlowQapRelationParentChild(parent, edge, child, TerminalFlowQapRelationUnconsumed) ->
                        let childState = terminalFlowQapRelationConsume reducerSequence child
                        let childRelation =
                            match childState with
                            | TerminalFlowQapRelationProtocolConsumed(value, _) -> value
                            | TerminalFlowQapRelationProtocolClosed(value, _) -> value
                            | TerminalFlowQapRelationProtocolCanonicalized(value, _)
                            | TerminalFlowQapRelationProtocolObserved value
                            | TerminalFlowQapRelationProtocolPoisoned(value, _) -> value
                        TerminalFlowQapRelationParentChild(parent, edge, childRelation, consumed)
                    | TerminalFlowQapRelationCycle(head, edge, path, TerminalFlowQapRelationUnconsumed) ->
                        let consumedPath =
                            path
                            |> List.map (fun item ->
                                match terminalFlowQapRelationConsume reducerSequence item with
                                | TerminalFlowQapRelationProtocolConsumed(value, _) -> value
                                | TerminalFlowQapRelationProtocolClosed(value, _) -> value
                                | TerminalFlowQapRelationProtocolCanonicalized(value, _)
                                | TerminalFlowQapRelationProtocolObserved value
                                | TerminalFlowQapRelationProtocolPoisoned(value, _) -> value)
                        TerminalFlowQapRelationCycle(head, edge, consumedPath, consumed)
                    | _ -> relation
                TerminalFlowQapRelationProtocolConsumed(consumedRelation, receiptRef)

        let private terminalFlowQapRelationProtocolValue = function
            | TerminalFlowQapRelationProtocolObserved relation -> relation, 0u
            | TerminalFlowQapRelationProtocolCanonicalized(relation, receiptRef)
            | TerminalFlowQapRelationProtocolConsumed(relation, receiptRef)
            | TerminalFlowQapRelationProtocolClosed(relation, receiptRef) -> relation, receiptRef
            | TerminalFlowQapRelationProtocolPoisoned(relation, _) -> relation, 0u

        let private terminalFlowQapFixpointConsumeRelations reducerSequence (fixpoint:TerminalFlowQapFixpointSet) =
            let consumed =
                fixpoint.items
                |> List.map (fun item ->
                    let relation, receiptRef =
                        item.relation
                        |> terminalFlowQapRelationConsume reducerSequence
                        |> terminalFlowQapRelationProtocolValue
                    { item with relation = relation }, receiptRef)
            let consumedItems = consumed |> List.map fst
            let receiptRefs = consumed |> List.map snd |> List.filter (fun receiptRef -> receiptRef <> 0u)
            { fixpoint with
                items = consumedItems
                maturity = TerminalFlowQapFixpointWitnessedByReducer
                terminalDecision = TerminalFlowQapCandidateTerminalErrorOrQuarantine },
            receiptRefs

        let rec private terminalFlowQapRelationIsConsumed = function
            | TerminalFlowQapRelationLeaf(_, _, TerminalFlowQapRelationConsumedExactOnce _)
            | TerminalFlowQapRelationParentChild(_, _, _, TerminalFlowQapRelationConsumedExactOnce _)
            | TerminalFlowQapRelationCycle(_, _, _, TerminalFlowQapRelationConsumedExactOnce _) -> true
            | _ -> false

        let private terminalFlowQapFixpointAllRelationsConsumed (fixpoint:TerminalFlowQapFixpointSet) =
            fixpoint.items |> List.forall (fun item -> terminalFlowQapRelationIsConsumed item.relation)

        let private terminalFlowQapTerminalDecisionText = function
            | TerminalFlowQapAwaitMaterialOrWaker -> "await_material_or_waker"
            | TerminalFlowQapCandidateTerminalErrorOrQuarantine -> "terminal_error_or_quarantine_candidate"
            | TerminalFlowQapAwaitReducerFourClockWitness -> "await_reducer_four_clock_witness"

        let private terminalFlowQapFixpointItemText (x:TerminalFlowQapFixpointItem) =
            FastRuntimeFormat.format "qap_item(ref=%s|site=%s|node=%s|relation=%s|repeat=%d/%d|material_delta=%d|witness=%s)" [| box (terminalFlowQapFixpointRefText x.itemRef); box (terminalFlowQapFixpointSiteText x.site); box (terminalFlowQapNodeIdText x.nodeId); box (terminalFlowQapRelationText x.relation); box x.repeatCount; box x.repeatCap; box x.materialDelta; box (terminalFlowQapEvidenceWitnessText x.lastWitness) |]

        let private terminalFlowQapFixpointSetText (x:TerminalFlowQapFixpointSet) =
            let items = x.items |> List.map terminalFlowQapFixpointItemText |> String.concat ";"
            FastRuntimeFormat.format "QapFixpoint(set=%s|items=%d|material_age_ms=%d|maturity=%s|mature=%b|decision=%s|top_k=%s)" [| box (terminalFlowQapFixpointRefText x.setRef); box x.items.Length; box x.materialQuiescenceAgeMs; box (terminalFlowQapFixpointMaturityText x.maturity); box (terminalFlowQapFixpointIsCandidate x.maturity); box (terminalFlowQapTerminalDecisionText x.terminalDecision); box items |]

        let private terminalFlowAwaitingObservationReasonText = function
            | TerminalFlowAwaitingQapFixpointMaterial(rootReceipt, leaseId, tailId, fixpoint) ->
                "qap_fixpoint_awaiting_material|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|" + terminalFlowQapFixpointSetText fixpoint
            | TerminalFlowAwaitingRecentMaterialActivity token ->
                "recent_material_activity|" + terminalFlowActivityTokenText "material_recent" terminalFlowMaterialActivitySourceText token
            | TerminalFlowAwaitingRejectedTopology qap ->
                "rejected_topology|" + terminalFlowQapObservationText qap
            | TerminalFlowAwaitingWakerRegistrationRequired(leaseId, tailId, obligationId, nextWakeAfterMs) ->
                FastRuntimeFormat.format "waker_registration_required|lease=%s|tail=%s|obligation=%s|next_wake_after_ms=%d" [| box leaseId; box tailId; box obligationId; box nextWakeAfterMs |]
            | TerminalFlowAwaitingWriterLeaseLive(leaseId, tailId, ageMs) ->
                FastRuntimeFormat.format "writer_lease_live|lease=%s|tail=%s|age_ms=%d" [| box leaseId; box tailId; box ageMs |]
            | TerminalFlowAwaitingGenericObservation -> "observe"
            | TerminalFlowAwaitingOperationalReason reason -> CompilerKernelV2.OperationalReasonIdOps.text reason

        let private terminalFlowQapFixpointRefFor nodeId _repeatCount : TerminalFlowQapFixpointRef<TerminalFlowQapFixpointItemRefKind> =
            // Repeat magnitude is evidence, never exact-once identity. The same causal
            // QAP relation must dereference one item while q/a/p churns.
            terminalFlowQapFixpointRefCreate (sprintf "qap-item:%s" (terminalFlowQapNodeIdText nodeId))

        let private terminalFlowQapFixpointSetRefFor (qap:TerminalFlowQapObservation) _materialAgeMs : TerminalFlowQapFixpointRef<TerminalFlowQapFixpointSetRefKind> =
            // Stable causal identity: queue magnitudes and wall-clock age are
            // observations, not identity. This lets the reducer watch one culprit
            // set across structural churn and mature it on semantic quiescence.
            terminalFlowQapFixpointRefCreate (
                FastRuntimeFormat.format "qap-fixpoint:canonical_pending=%b|queue=%b|semantic_ledger_state=%s|pending_authority=%s" [| box (qap.pending > 0); box (qap.queue > 0); box (SemanticWorkLedgerProjection.stateClassTextOf qap.semanticLedgerState); box (terminalFlowPendingLedgerAuthorityText qap.pendingProvenance.authority) |])

        let private terminalFlowQapFixpointFromObservation materialAgeMs repeatCap (qap:TerminalFlowQapObservation) : TerminalFlowQapFixpointSet =
            let mk site node repeat delta witness =
                { itemRef = terminalFlowQapFixpointRefFor node repeat
                  site = site
                  nodeId = node
                  relation = terminalFlowQapRelationFor site node witness
                  repeatCount = max 0L repeat
                  repeatCap = max 1L repeatCap
                  materialDelta = max 0L delta
                  lastWitness = witness }
            let reducerClosedWithoutFrontier =
                match qap.pendingProvenance.authority with
                | TerminalFlowPendingFrontierUnavailableReducerClosed _ -> true
                | _ -> false
            let primarySite = if qap.queue > 0 then TerminalFlowQapCacheHandoffApplyArg0Child elif qap.active > 0 then TerminalFlowQapParentContinuationPoison else TerminalFlowQapDynamicBridgePoison
            // A QAP repeat is an observation of unchanged causal state, not queue magnitude.
            // The MIGRATION tail stayed at q=1/a=1/p=2 for more than twelve minutes, so
            // occupancy-derived repeats could never reach the cap of four.  Quiescence
            // seconds provide a monotonic observation epoch while remaining outside identity.
            let quiescentRepeat = max 1L (materialAgeMs / 1000L)
            let primaryRepeat = quiescentRepeat
            let items =
                [ if qap.queue > 0 || qap.active > 0 || qap.pending > 0 then
                      yield mk primarySite TerminalFlowQapCacheHandoffChildApplyArg0Node primaryRepeat 0L TerminalFlowQapPrimaryFixpointWitness
                  if qap.active > 0 then yield mk TerminalFlowQapParentContinuationPoison TerminalFlowQapParentPoisonTerminalTailNode quiescentRepeat 0L TerminalFlowQapActiveTailWitness
                  if qap.pending > 0 then yield mk TerminalFlowQapPendingOwner TerminalFlowQapPendingOwnerTerminalTailNode quiescentRepeat 0L TerminalFlowQapPendingOwnerWitness ]
            let maturityThresholdMs = if reducerClosedWithoutFrontier then 1000L else 4000L
            let candidateMature =
                (terminalFlowQapHasResidual qap || reducerClosedWithoutFrontier)
                && (terminalFlowQapIsBounded qap || (qap.pending = 0 && qap.active >= 0 && qap.active <= 4))
                && qap.semanticOpen = 0L
                && materialAgeMs >= maturityThresholdMs
                && (items |> List.forall (fun (item:TerminalFlowQapFixpointItem) -> item.materialDelta = 0L && item.repeatCount >= item.repeatCap))
            { setRef = terminalFlowQapFixpointSetRefFor qap materialAgeMs
              items = items
              materialQuiescenceAgeMs = max 0L materialAgeMs
              maturity = if candidateMature then TerminalFlowQapFixpointCandidateObserved else TerminalFlowQapFixpointAwaitingReducerWitness
              terminalDecision = if candidateMature then TerminalFlowQapCandidateTerminalErrorOrQuarantine else TerminalFlowQapAwaitMaterialOrWaker }

        // A physically and semantically closed graph has a positive empty relation-set
        // witness. It must enter the same reducer finalizer as an observed QAP rather
        // than remaining Idle merely because no residual relation existed to open a watch.
        let private terminalFlowQapClosedGraphFixpointFor identity materialAgeMs : TerminalFlowQapFixpointSet =
            { setRef = terminalFlowQapFixpointRefCreate ("qap-fixpoint:closed-graph:" + identity)
              items = []
              materialQuiescenceAgeMs = max 0L materialAgeMs
              maturity = TerminalFlowQapFixpointCandidateObserved
              terminalDecision = TerminalFlowQapAwaitReducerFourClockWitness }

        let private terminalFlowQapProtocolIdValue (TerminalFlowQapProtocolId value) = value

        let private terminalFlowQapRelationRef relation =
            terminalFlowQapLocalMintedRefOf
                "qap_relation_ref"
                (terminalFlowQapRelationText relation)

        let private terminalFlowQapRelationResolutionReceiptFor reducerSequence materialEpoch resolution relation =
            let relationRef = terminalFlowQapRelationRef relation
            let receiptIdentity =
                FastRuntimeFormat.format "qap-relation-resolution:%u:%d:%s" [| box relationRef; box reducerSequence; box (terminalFlowQapRelationResolutionText resolution) |]
            { receiptRef = TerminalFlowQapProtocolId(uint64 (terminalFlowQapLocalMintedRefOf "qap_relation_resolution_receipt_ref" receiptIdentity))
              relationRef = relationRef
              resolution = resolution
              materialEpochBefore = materialEpoch
              materialEpochAfter = materialEpoch
              reducerSequence = reducerSequence }

        let private terminalFlowQapTypedFor<'Stage>
            semanticDigestRef
            proceduralDigestRef
            relationSetRef
            materialEpoch
            (fixpoint:TerminalFlowQapFixpointSet)
            : TerminalFlowQap<TerminalFlowQapFixpointSetRefKind,'Stage> =
            let setText = terminalFlowQapFixpointRefText fixpoint.setRef
            { qapRef = TerminalFlowQapProtocolId(uint64 (terminalFlowQapLocalMintedRefOf "qap_protocol_ref" setText))
              semanticDigestRef = semanticDigestRef
              proceduralDigestRef = proceduralDigestRef
              relationSetRef = relationSetRef
              materialEpoch = materialEpoch
              relations = fixpoint.items |> List.map (fun (item:TerminalFlowQapFixpointItem) -> item.relation)
              fixpoint = fixpoint }

        let private terminalFlowQapResolutionText = function
            | TerminalFlowQapMaterialProgressBox qap ->
                sprintf "MaterialProgress(qap_ref=%d|material_epoch=%d)" (terminalFlowQapProtocolIdValue qap.qapRef) qap.materialEpoch
            | TerminalFlowQapFullyDrainedBox(qap, proof) ->
                FastRuntimeFormat.format "FullyDrained(qap_ref=%d|proof_ref=%d|relations=%d|authority=%s)" [| box (terminalFlowQapProtocolIdValue qap.qapRef); box (terminalFlowQapProtocolIdValue proof.proofRef); box proof.relationReceipts.Length; box (terminalFlowQapDrainAuthorityText proof.drainAuthority) |]
            | TerminalFlowQapProvenDeadlockBox(qap, proof) ->
                FastRuntimeFormat.format "ProvenDeadlock(qap_ref=%d|proof_ref=%d|relations=%d|reducer_sequence=%d)" [| box (terminalFlowQapProtocolIdValue qap.qapRef); box (terminalFlowQapProtocolIdValue proof.proofRef); box proof.relationReceipts.Length; box proof.reducerSequence |]

        let private terminalFlowQapResolutionBoxRef = function
            | TerminalFlowQapMaterialProgressBox qap -> uint32 (terminalFlowQapProtocolIdValue qap.qapRef)
            | TerminalFlowQapFullyDrainedBox(_, proof) -> uint32 (terminalFlowQapProtocolIdValue proof.proofRef)
            | TerminalFlowQapProvenDeadlockBox(_, proof) -> uint32 (terminalFlowQapProtocolIdValue proof.proofRef)

        let private terminalFlowQapResolvePositive
            reducerSequence
            semanticDigestRef
            proceduralDigestRef
            materialEpoch
            quiescenceDigest
            noPendingRebase
            (fixpoint:TerminalFlowQapFixpointSet)
            : TerminalFlowQapResolutionBox =
            let relationSetText =
                fixpoint.items
                |> List.map (fun (item:TerminalFlowQapFixpointItem) -> terminalFlowQapRelationText item.relation)
                |> String.concat "|"
            let relationSetRef = terminalFlowQapLocalMintedRefOf "qap_relation_set_ref" relationSetText
            let allRelationsConsumed = terminalFlowQapFixpointAllRelationsConsumed fixpoint
            let drained = fixpoint.items.IsEmpty || allRelationsConsumed
            let relationReceipts disposition =
                fixpoint.items
                |> List.map (fun item ->
                    let relationRef = terminalFlowQapRelationRef item.relation
                    let receiptRef = terminalFlowQapLocalMintedRefOf "qap_relation_disposition_ref" (string relationRef + ":" + disposition)
                    let resolution =
                        if terminalFlowQapRelationIsConsumed item.relation then
                            TerminalFlowQapRelationConsumed(relationRef, receiptRef)
                        elif disposition = "deadlocked" then
                            TerminalFlowQapRelationDeadlocked(relationRef, receiptRef)
                        else
                            TerminalFlowQapRelationRegistered(relationRef, None)
                    terminalFlowQapRelationResolutionReceiptFor reducerSequence materialEpoch resolution item.relation)
            match quiescenceDigest with
            | Some creditDigest when drained ->
                let qap = terminalFlowQapTypedFor<TerminalFlowQapDrainedStage> semanticDigestRef proceduralDigestRef relationSetRef materialEpoch fixpoint
                let receipts = relationReceipts "drained"
                let proofIdentity = FastRuntimeFormat.format "qap-drain-proof:%d:%u:%d" [| box reducerSequence; box relationSetRef; box materialEpoch |]
                let proof =
                    { proofRef = TerminalFlowQapProtocolId(uint64 (terminalFlowQapLocalMintedRefOf "qap_drain_proof_ref" proofIdentity))
                      qapRef = qap.qapRef
                      relationReceipts = receipts
                      drainAuthority = if fixpoint.items.IsEmpty then TerminalFlowQapDrainByEmptyRelationSet else TerminalFlowQapDrainByExactOnceConsumption (List.length fixpoint.items)
                      materialEpoch = materialEpoch
                      reducerSequence = reducerSequence }
                TerminalFlowQapFullyDrainedBox(qap, proof)
            | Some creditDigest when noPendingRebase ->
                let qap = terminalFlowQapTypedFor<TerminalFlowQapDeadlockedStage> semanticDigestRef proceduralDigestRef relationSetRef materialEpoch fixpoint
                let receipts = relationReceipts "deadlocked"
                let proofIdentity =
                    FastRuntimeFormat.format "qap-deadlock-proof:%d:%u:%s" [| box reducerSequence; box relationSetRef; box (CompilerIdentityKernel.ContentDigest.text creditDigest) |]
                let proof =
                    { proofRef = TerminalFlowQapProtocolId(uint64 (terminalFlowQapLocalMintedRefOf "qap_deadlock_proof_ref" proofIdentity))
                      qapRef = qap.qapRef
                      quiescence = TerminalFlowQapQuiescenceWitness creditDigest
                      noPendingRebase = TerminalFlowQapNoPendingRebaseWitness reducerSequence
                      relationReceipts = receipts
                      reducerSequence = reducerSequence }
                TerminalFlowQapProvenDeadlockBox(qap, proof)
            | _ ->
                let qap = terminalFlowQapTypedFor<TerminalFlowQapProgressingStage> semanticDigestRef proceduralDigestRef relationSetRef materialEpoch fixpoint
                TerminalFlowQapMaterialProgressBox qap

        let private terminalFlowObservationText (x:TerminalFlowObservation) =
            "TerminalFlowObservation("
            + terminalFlowRootObservationText x.root
            + "|" + terminalFlowWriterObservationText x.writer
            + "|" + terminalFlowTailObservationText x.tail
            + "|" + terminalFlowOwnerObservationText x.owners
            + "|" + terminalFlowQapObservationText x.qap
            + "|" + terminalFlowActivityObservationText x.activity
            + ")"

        let private terminalFlowTransitionDecisionText = function
            | TerminalFlowTransitionObserve -> "TerminalFlowTransition(Observe)"
            | TerminalFlowTransitionDeferMaterialActivity token -> terminalFlowActivityTokenText "defer_material" terminalFlowMaterialActivitySourceText token
            | TerminalFlowTransitionRejectTopology qap -> "TerminalFlowTransition(RejectTopology|" + terminalFlowQapObservationText qap + ")"
            | TerminalFlowTransitionRegisterWakerEdge(rootReceipt, leaseId, tailId, obligationId, nextWakeAfterMs) -> FastRuntimeFormat.format "TerminalFlowTransition(RegisterWakerEdge|root=%s|lease=%s|tail=%s|obligation=%s|next_wake_after_ms=%d)" [| box rootReceipt; box leaseId; box tailId; box obligationId; box nextWakeAfterMs |]
            | TerminalFlowTransitionWriterLeaseLive(rootReceipt, leaseId, tailId, ageMs) -> FastRuntimeFormat.format "TerminalFlowTransition(WriterLeaseLive|root=%s|lease=%s|tail=%s|age_ms=%d)" [| box rootReceipt; box leaseId; box tailId; box ageMs |]
            | TerminalFlowTransitionWriterLeaseExpired(rootReceipt, leaseId, tailId, ageMs, qap) -> FastRuntimeFormat.format "TerminalFlowTransition(WriterLeaseExpired|root=%s|lease=%s|tail=%s|age_ms=%d|%s)" [| box rootReceipt; box leaseId; box tailId; box ageMs; box (terminalFlowQapObservationText qap) |]
            | TerminalFlowTransitionQuarantineResidualQap(rootReceipt, leaseId, tailId, ageMs, qap) -> FastRuntimeFormat.format "TerminalFlowTransition(QuarantineResidualQap|root=%s|lease=%s|tail=%s|age_ms=%d|%s)" [| box rootReceipt; box leaseId; box tailId; box ageMs; box (terminalFlowQapObservationText qap) |]
            | TerminalFlowTransitionQapFixpointMatured(rootReceipt, leaseId, tailId, fixpoint) -> "TerminalFlowTransition(QapFixpointMatured|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|" + terminalFlowQapFixpointSetText fixpoint + ")"
            | TerminalFlowTransitionQapFixpointAwaitingMaterial(rootReceipt, leaseId, tailId, fixpoint) -> "TerminalFlowTransition(QapFixpointAwaitingMaterial|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|" + terminalFlowQapFixpointSetText fixpoint + ")"
            | TerminalFlowTransitionForceCloseResidual(rootReceipt, leaseId, tailId, ownerCloseReceiptId, workDagTailCloseReceipt) -> FastRuntimeFormat.format "TerminalFlowTransition(ForceCloseResidual|root=%s|lease=%s|tail=%s|owner_close_receipt=%s|workdag_close=%s)" [| box rootReceipt; box leaseId; box tailId; box ownerCloseReceiptId; box workDagTailCloseReceipt |]
            | TerminalFlowTransitionBindWriter(rootReceipt, writerReceiptId, tailId) -> "TerminalFlowTransition(BindWriter|root=" + rootReceipt + "|writer=" + writerReceiptId + "|tail=" + tailId + ")"
            | TerminalFlowTransitionDeadlockTail(rootReceipt, leaseId, tailId, proof) ->
                "TerminalFlowTransition(DeadlockTail|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|proof=" + CompilerKernelV2.TerminalTailDeadlockProofIdOps.text proof + ")"
            | TerminalFlowTransitionQuarantineTail(rootReceipt, leaseId, tailId, reason) ->
                "TerminalFlowTransition(QuarantineTail|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|reason=" + CompilerKernelV2.TerminalTailQuarantineReasonIdOps.text reason + ")"
            | TerminalFlowTransitionTerminalEmitted terminalReceiptId -> "TerminalFlowTransition(TerminalEmitted|receipt=" + terminalReceiptId + ")"

        let private terminalFlowOutcomeText = function
            | TerminalFlowOutcomeAwaitingObservation reason ->
                "TerminalFlowOutcome(AwaitingObservation|reason=" + terminalFlowAwaitingObservationReasonText reason + ")"
            | TerminalFlowOutcomeWakerRegistrationRequired(rootReceipt, leaseId, tailId, obligationId, nextWakeAfterMs) -> FastRuntimeFormat.format "TerminalFlowOutcome(WakerRegistrationRequired|root=%s|lease=%s|tail=%s|obligation=%s|next_wake_after_ms=%d)" [| box rootReceipt; box leaseId; box tailId; box obligationId; box nextWakeAfterMs |]
            | TerminalFlowOutcomeWriterLeaseStillLive(rootReceipt, leaseId, tailId, ageMs) -> FastRuntimeFormat.format "TerminalFlowOutcome(WriterLeaseStillLive|root=%s|lease=%s|tail=%s|age_ms=%d)" [| box rootReceipt; box leaseId; box tailId; box ageMs |]
            | TerminalFlowOutcomeWriterBound(rootReceipt, writerReceiptId, tailId) -> "TerminalFlowOutcome(WriterBound|root=" + rootReceipt + "|writer=" + writerReceiptId + "|tail=" + tailId + ")"
            | TerminalFlowOutcomeTailDeadlocked(rootReceipt, leaseId, tailId, proof) ->
                "TerminalFlowOutcome(TailDeadlocked|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|proof=" + CompilerKernelV2.TerminalTailDeadlockProofIdOps.text proof + ")"
            | TerminalFlowOutcomeTailQuarantined(rootReceipt, leaseId, tailId, reason) ->
                "TerminalFlowOutcome(TailQuarantined|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|reason=" + CompilerKernelV2.TerminalTailQuarantineReasonIdOps.text reason + ")"
            | TerminalFlowOutcomeTerminalEmitted terminalReceiptId -> "TerminalFlowOutcome(TerminalEmitted|receipt=" + terminalReceiptId + ")"

        let private terminalFlowCertificateIntentText = function
            | TerminalFlowCertificateAwaiting reason ->
                "TerminalFlowCertificateIntent(Awaiting|reason=" + terminalFlowAwaitingObservationReasonText reason + ")"
            | TerminalFlowCertificateBuildOk(rootReceipt, writerReceiptId, tailId) -> "TerminalFlowCertificateIntent(BuildOk|root=" + rootReceipt + "|writer=" + writerReceiptId + "|tail=" + tailId + ")"
            | TerminalFlowCertificateBuildError(rootReceipt, leaseId, tailId, proof) ->
                "TerminalFlowCertificateIntent(BuildError|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|proof=" + CompilerKernelV2.TerminalTailDeadlockProofIdOps.text proof + ")"
            | TerminalFlowCertificateNoFurther terminalReceiptId -> "TerminalFlowCertificateIntent(NoFurther|receipt=" + terminalReceiptId + ")"
            | TerminalFlowCertificateQuarantine(rootReceipt, leaseId, tailId, reason) ->
                "TerminalFlowCertificateIntent(Quarantine|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|reason=" + CompilerKernelV2.TerminalTailQuarantineReasonIdOps.text reason + ")"

        let private terminalFlowCertificateIntentForOutcome = function
            | TerminalFlowOutcomeWriterBound(rootReceipt, writerReceiptId, tailId) -> TerminalFlowCertificateBuildOk(rootReceipt, writerReceiptId, tailId)
            | TerminalFlowOutcomeTailDeadlocked(rootReceipt, leaseId, tailId, proof) -> TerminalFlowCertificateBuildError(rootReceipt, leaseId, tailId, proof)
            | TerminalFlowOutcomeTailQuarantined(rootReceipt, leaseId, tailId, reason) -> TerminalFlowCertificateQuarantine(rootReceipt, leaseId, tailId, reason)
            | TerminalFlowOutcomeTerminalEmitted terminalReceiptId -> TerminalFlowCertificateNoFurther terminalReceiptId
            | TerminalFlowOutcomeWakerRegistrationRequired(_, leaseId, tailId, obligationId, nextWakeAfterMs) ->
                TerminalFlowCertificateAwaiting(
                    TerminalFlowAwaitingWakerRegistrationRequired(leaseId, tailId, obligationId, nextWakeAfterMs))
            | TerminalFlowOutcomeWriterLeaseStillLive(_, leaseId, tailId, ageMs) ->
                TerminalFlowCertificateAwaiting(TerminalFlowAwaitingWriterLeaseLive(leaseId, tailId, ageMs))
            | TerminalFlowOutcomeAwaitingObservation reason -> TerminalFlowCertificateAwaiting reason

        let private terminalFlowTopLevelReceiptIdFor prefix root writer tail =
            prefix
            + ":"
            + string (NativeCutoverStableRef.ref32 "terminal-top-level-receipt" [ prefix; root; writer; tail ])

        let private terminalFlowTopLevelFailureIdFor prefix root lease tail =
            prefix
            + ":"
            + string (NativeCutoverStableRef.ref32 "terminal-top-level-failure" [ prefix; root; lease; tail ])

        let private terminalFlowWhyNotTerminalCommitText = function
            | TerminalFlowWhyNotAwaitingBoundedLease(leaseId, tailId, ageMs) -> FastRuntimeFormat.format "WhyNotTerminalCommit(AwaitingBoundedLease|lease=%s|tail=%s|age_ms=%d)" [| box leaseId; box tailId; box ageMs |]
            | TerminalFlowWhyNotAwaitingObservation reason ->
                "WhyNotTerminalCommit(AwaitingObservation|reason=" + terminalFlowAwaitingObservationReasonText reason + ")"
            | TerminalFlowWhyNotWakerRegistrationRequired(obligationId, nextWakeAfterMs) -> sprintf "WhyNotTerminalCommit(WakerRegistrationRequired|obligation=%s|next_wake_after_ms=%d)" obligationId nextWakeAfterMs
            | TerminalFlowWhyNotMissingRootReceipt evidence -> "WhyNotTerminalCommit(MissingRootReceipt|evidence=" + evidence + ")"
            | TerminalFlowWhyNotRecentMaterialActivity token -> "WhyNotTerminalCommit(RecentMaterialActivity|" + terminalFlowActivityTokenText "material_recent" terminalFlowMaterialActivitySourceText token + ")"
            | TerminalFlowWhyNotRejectedTopology qap -> "WhyNotTerminalCommit(RejectedTopology|" + terminalFlowQapObservationText qap + ")"
            | TerminalFlowWhyNotMissingWriterReceipt(rootReceipt, tailId) -> "WhyNotTerminalCommit(MissingWriterReceipt|root=" + rootReceipt + "|tail=" + tailId + ")"
            | TerminalFlowWhyNotObserverOnly reason -> "WhyNotTerminalCommit(ObserverOnly|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let private terminalFlowWhyNotIdentityText = function
            | TerminalFlowWhyNotAwaitingBoundedLease(leaseId, tailId, _) ->
                "awaiting_bounded_lease|lease=" + leaseId + "|tail=" + tailId
            | TerminalFlowWhyNotWakerRegistrationRequired(obligationId, _) ->
                "waker_registration_required|obligation=" + obligationId
            | TerminalFlowWhyNotRecentMaterialActivity token ->
                sprintf "recent_material_activity|source=%s|count=%d"
                    (terminalFlowMaterialActivitySourceText token.source)
                    token.count
            | whyNot -> terminalFlowWhyNotTerminalCommitText whyNot

        let private terminalFlowTopLevelReceiptText = function
            | TerminalFlowTopLevelBuildOkReceipt(receiptId, rootReceipt, writerReceiptId, tailId) -> "TerminalFlowTopLevelReceipt(BuildOk|receipt=" + receiptId + "|root=" + rootReceipt + "|writer=" + writerReceiptId + "|tail=" + tailId + ")"
            | TerminalFlowTopLevelBuildErrorCertificate(receiptId, rootReceipt, leaseId, tailId, proof) ->
                "TerminalFlowTopLevelReceipt(BuildErrorCertificate|receipt=" + receiptId + "|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|proof=" + CompilerKernelV2.TerminalTailDeadlockProofIdOps.text proof + ")"
            | TerminalFlowTopLevelNoFurtherCertificate receiptId -> "TerminalFlowTopLevelReceipt(NoFurtherCertificate|receipt=" + receiptId + ")"
            | TerminalFlowTopLevelQuarantineCertificate(receiptId, rootReceipt, leaseId, tailId, reason) ->
                "TerminalFlowTopLevelReceipt(QuarantineCertificate|receipt=" + receiptId + "|root=" + rootReceipt + "|lease=" + leaseId + "|tail=" + tailId + "|reason=" + CompilerKernelV2.TerminalTailQuarantineReasonIdOps.text reason + ")"

        let private terminalFlowCertificateBoundaryText = function
            | TerminalFlowBoundaryReceipt receipt -> "TerminalFlowCertificateBoundary(" + terminalFlowTopLevelReceiptText receipt + ")"
            | TerminalFlowBoundaryWhyNotCommit reason -> "TerminalFlowCertificateBoundary(" + terminalFlowWhyNotTerminalCommitText reason + ")"

        let private terminalFlowCertificateBoundaryForOutcome = function
            | TerminalFlowOutcomeWriterBound(rootReceipt, writerReceiptId, tailId) ->
                TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt(terminalFlowTopLevelReceiptIdFor "terminal_commit_receipt" rootReceipt writerReceiptId tailId, rootReceipt, writerReceiptId, tailId))
            | TerminalFlowOutcomeTailDeadlocked(rootReceipt, leaseId, tailId, proof) ->
                TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildErrorCertificate(terminalFlowTopLevelFailureIdFor "post_root_breakthrough_certificate" rootReceipt leaseId tailId, rootReceipt, leaseId, tailId, proof))
            | TerminalFlowOutcomeTailQuarantined(rootReceipt, leaseId, tailId, reason) ->
                TerminalFlowBoundaryReceipt(TerminalFlowTopLevelQuarantineCertificate(terminalFlowTopLevelFailureIdFor "post_root_quarantine_certificate" rootReceipt leaseId tailId, rootReceipt, leaseId, tailId, reason))
            | TerminalFlowOutcomeTerminalEmitted terminalReceiptId ->
                TerminalFlowBoundaryReceipt(TerminalFlowTopLevelNoFurtherCertificate terminalReceiptId)
            | TerminalFlowOutcomeWakerRegistrationRequired(_, _, _, obligationId, nextWakeAfterMs) ->
                TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotWakerRegistrationRequired(obligationId, nextWakeAfterMs))
            | TerminalFlowOutcomeWriterLeaseStillLive(_, leaseId, tailId, ageMs) ->
                TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotAwaitingBoundedLease(leaseId, tailId, ageMs))
            | TerminalFlowOutcomeAwaitingObservation reason ->
                match reason with
                | TerminalFlowAwaitingRecentMaterialActivity token ->
                    TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRecentMaterialActivity token)
                | TerminalFlowAwaitingRejectedTopology rejected ->
                    TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRejectedTopology rejected)
                | _ ->
                    TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotAwaitingObservation reason)

        let private terminalFlowCertificateBoundaryIsReceipt = function
            | TerminalFlowBoundaryReceipt _ -> true
            | TerminalFlowBoundaryWhyNotCommit _ -> false

        let private terminalFlowBoundaryActionForBoundary = function
            | TerminalFlowBoundaryReceipt receipt -> TerminalFlowBoundaryActionEmitReceipt receipt
            | TerminalFlowBoundaryWhyNotCommit reason -> TerminalFlowBoundaryActionBlockCommit reason

        let private terminalFlowBoundaryActionText = function
            | TerminalFlowBoundaryActionEmitReceipt receipt -> "TerminalFlowBoundaryAction(EmitReceipt|" + terminalFlowTopLevelReceiptText receipt + ")"
            | TerminalFlowBoundaryActionBlockCommit reason -> "TerminalFlowBoundaryAction(BlockCommit|" + terminalFlowWhyNotTerminalCommitText reason + ")"
            | TerminalFlowBoundaryActionFatalMissingBoundary reason -> "TerminalFlowBoundaryAction(FatalMissingBoundary|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let private terminalFlowBoundaryTopLevelReceiptText = function
            | TerminalFlowBoundaryReceipt receipt -> terminalFlowTopLevelReceiptText receipt
            | TerminalFlowBoundaryWhyNotCommit _ -> "TerminalFlowTopLevelReceipt(None)"

        let private terminalFlowBoundaryTerminalCommitReceiptId = function
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt(receiptId, _, _, _)) -> receiptId
            | _ -> ""

        let private terminalFlowBoundaryPostRootCertificateId = function
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildErrorCertificate(receiptId, _, _, _, _)) -> receiptId
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelNoFurtherCertificate receiptId) -> receiptId
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelQuarantineCertificate(receiptId, _, _, _, _)) -> receiptId
            | _ -> ""

        let private terminalFlowTopLevelReceiptStableId = function
            | TerminalFlowTopLevelBuildOkReceipt(receiptId, _, _, _)
            | TerminalFlowTopLevelBuildErrorCertificate(receiptId, _, _, _, _)
            | TerminalFlowTopLevelNoFurtherCertificate receiptId
            | TerminalFlowTopLevelQuarantineCertificate(receiptId, _, _, _, _) -> receiptId

        // Domain migration round : the remaining join-wait projection is dataflow-only.
        // A zero sentinel means: do not schedule a local polling timer; wait for a
        // root/outcome/scheduler receipt or for the independent physical deadman.
        let private terminalFlowDataflowWakeSentinelMs = 0L
        // Time values below describe evidence windows only. Terminal authority must not
        // depend on wall-clock milliseconds because constrained machines stretch time.
        // The terminal gate is driven by hardware-invariant evidence: mutating depth,
        // procedural residual pressure, pending emptiness, and bounded/unbounded topology.
        let private terminalFlowWriterLeaseExpiresAfterMs = 30000L
        let private terminalFlowProceduralPressureQueueThreshold = 64
        let private terminalFlowProceduralPressureActiveThreshold = 4
        let private terminalFlowBoundedProceduralTailPressureDepth = 8
        let private terminalFlowBoundedProceduralTailPressureQueue = 16
        let private terminalFlowSmallPendingQuiescentCap = 0
        let private terminalFlowWriterLeaseSmallResidualPendingCap = 4
        let private terminalFlowWriterLeaseSmallResidualQueueCap = 9
        let private terminalFlowWriterLeaseSmallResidualActiveCap = 4
        let private terminalFlowWriterLeaseSmallResidualProceduralCap = 16

        // MIGRATION round : process-global TerminalFlow server contract.
        // The actual transition loop is staged for the authoritative reducer cut, but all local copies
        // now emit through one command/event algebra so join-wait polling cannot
        // remain the owner of level-triggered rechecks.  MIGRATION keeps the
        // dispatch join key below the ref minter, because F# has no forward
        // reference for let-bound minted ref functions.

        // Bonus migration : physical receipts are phantom-indexed.  A writer
        // capability reference can no longer be passed where an artifact, failure,
        // or exit witness reference is required.
        type TerminalFlowWriterWakeReceiptRefKind private () =
            static member IdentityKindTag () = 0x070001u
        type TerminalFlowWriterCapabilityRefKind private () =
            static member IdentityKindTag () = 0x070002u
        type TerminalFlowArtifactReceiptRefKind private () =
            static member IdentityKindTag () = 0x070003u
        type TerminalFlowFailureRefKind private () =
            static member IdentityKindTag () = 0x070004u
        type TerminalFlowExitWitnessRefKind private () =
            static member IdentityKindTag () = 0x070005u
        type TerminalFlowActorPhaseRefKind private () =
            static member IdentityKindTag () = 0x070006u
        type TerminalFlowActorRefKind private () =
            static member IdentityKindTag () = 0x070007u
        type TerminalFlowOwnerDebtRefKind private () =
            static member IdentityKindTag () = 0x070008u
        type TerminalFlowOwnerClosureCertificateRefKind private () =
            static member IdentityKindTag () = 0x070009u
        type TerminalFlowOutcomeIvarFillRefKind private () =
            static member IdentityKindTag () = 0x07000Au
        type TerminalFlowSchedulerPushReceiptRefKind private () =
            static member IdentityKindTag () = 0x07000Bu
        type TerminalFlowStageCapabilityRefKind private () =
            static member IdentityKindTag () = 0x07000Cu
        type TerminalFlowReceiptProjectionRefKind private () =
            static member IdentityKindTag () = 0x07000Du
        type TerminalFlowCausalSpineRefKind private () =
            static member IdentityKindTag () = 0x07000Eu
        type TerminalFlowRunEndReceiptRefKind private () =
            static member IdentityKindTag () = 0x07000Fu
        type TerminalFlowQapFixpointReceiptRefKind private () =
            static member IdentityKindTag () = 0x070010u
        type TerminalFlowExitRequestRefKind private () =
            static member IdentityKindTag () = 0x070011u

        type TerminalFlowDispatchJoinKey = private {
            rootReceiptRef : TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            fillRef : TerminalFlowIdentityRef<TerminalFlowFillRefKind>
            keyRef : uint32
        }

        type TerminalFlowMatureOwnerDebtSubmissionReason =
            | MatureOwnerDebtTransition
            | MatureOwnerDebtCanonicalRootProjectionDispatch
            | MatureOwnerDebtCanonicalRootProjectionAwaitRoot
            | MatureOwnerDebtMissingRootReceipt
            | MatureOwnerDebtEvaluatorIvarUnfilled

        type TerminalFlowMatureOwnerDebtSubmissionWindow =
            | MatureOwnerDebtSubmissionWindow of bucket:int

        type TerminalFlowMatureOwnerDebtSubmissionKey = private {
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            window : TerminalFlowMatureOwnerDebtSubmissionWindow
        }

        let private terminalFlowMatureOwnerDebtSubmissionReasonText = function
            | MatureOwnerDebtTransition -> "mature_owner_debt_transition"
            | MatureOwnerDebtCanonicalRootProjectionDispatch -> "canonical_root_terminal_projection_dispatch"
            | MatureOwnerDebtCanonicalRootProjectionAwaitRoot -> "canonical_root_terminal_projection_await_root"
            | MatureOwnerDebtMissingRootReceipt -> "terminal_outcome_missing_root_receipt"
            | MatureOwnerDebtEvaluatorIvarUnfilled -> "canonical_root_evaluator_ivar_unfilled"

        let private terminalFlowMatureOwnerDebtSubmissionWindowFor proceduralPass =
            // MIGRATION: mature owner debt is level-triggered and exact-once.
            // Do not reopen a new submission window every eight observer passes.
            MatureOwnerDebtSubmissionWindow(if proceduralPass <= 0 then 0 else 1)

        let private terminalFlowMatureOwnerDebtSubmissionKeyFor (terminalReceiptId:string) (_reason:TerminalFlowMatureOwnerDebtSubmissionReason) (proceduralPass:int) : TerminalFlowMatureOwnerDebtSubmissionKey =
            {
                terminalReceiptRef = terminalFlowIdentityRefOfText terminalReceiptId
                window = terminalFlowMatureOwnerDebtSubmissionWindowFor proceduralPass
            }

        let private terminalFlowDispatchJoinKeyForRefs
            (rootReceiptRef:TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>)
            (terminalReceiptRef:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>)
            (fillKey:TerminalFlowFillKeyId) : TerminalFlowDispatchJoinKey =
            let fillRef = TerminalFlowFillKeyId.reference fillKey
            let rootReceiptId = terminalFlowIdentityRefText rootReceiptRef
            let terminalReceiptId = terminalFlowIdentityRefText terminalReceiptRef
            let fillKeyText = TerminalFlowFillKeyId.text fillKey
            { rootReceiptRef = rootReceiptRef
              terminalReceiptRef = terminalReceiptRef
              fillRef = fillRef
              keyRef = terminalFlowMintedRefOf "dispatch_join_key_ref" (rootReceiptId + "|" + terminalReceiptId + "|" + fillKeyText) }

        let private terminalFlowDispatchJoinKeyFor (rootReceiptId:string) (terminalReceiptId:string) (fillKey:string) : TerminalFlowDispatchJoinKey =
            terminalFlowDispatchJoinKeyForRefs
                (terminalFlowIdentityRefOfText rootReceiptId)
                (terminalFlowIdentityRefOfText terminalReceiptId)
                (TerminalFlowFillKeyId.create fillKey)

        let private terminalFlowDispatchJoinRootRef (key:TerminalFlowDispatchJoinKey) = key.rootReceiptRef
        let private terminalFlowDispatchJoinTerminalRef (key:TerminalFlowDispatchJoinKey) = key.terminalReceiptRef
        let private terminalFlowDispatchJoinFillRef (key:TerminalFlowDispatchJoinKey) = key.fillRef
        let private terminalFlowDispatchJoinRootText (key:TerminalFlowDispatchJoinKey) = terminalFlowIdentityRefText key.rootReceiptRef
        let private terminalFlowDispatchJoinTerminalText (key:TerminalFlowDispatchJoinKey) = terminalFlowIdentityRefText key.terminalReceiptRef
        let private terminalFlowDispatchJoinFillText (key:TerminalFlowDispatchJoinKey) = terminalFlowIdentityRefText key.fillRef

        type TerminalFlowDispatchPublication =
            | TerminalFlowDispatchFirstPublication
            | TerminalFlowDispatchDuplicatePublication

        let private terminalFlowDispatchPublicationIsFirst = function
            | TerminalFlowDispatchFirstPublication -> true
            | TerminalFlowDispatchDuplicatePublication -> false

        let private terminalFlowDispatchPublicationText = function
            | TerminalFlowDispatchFirstPublication -> "First"
            | TerminalFlowDispatchDuplicatePublication -> "Duplicate"

        type TerminalFlowDispatchRequestIdentitySource =
            | TerminalFlowDispatchRequestIdentityMintedForFill
            | TerminalFlowDispatchRequestIdentityMintedForFillConfirmedByKernel
            | TerminalFlowDispatchRequestIdentityMintedForFillRejectedStaleKernel

        let private terminalFlowDispatchRequestIdentitySourceText = function
            | TerminalFlowDispatchRequestIdentityMintedForFill -> "MintedForFill"
            | TerminalFlowDispatchRequestIdentityMintedForFillConfirmedByKernel -> "MintedForFillConfirmedByKernel"
            | TerminalFlowDispatchRequestIdentityMintedForFillRejectedStaleKernel -> "MintedForFillRejectedStaleKernel"

        type TerminalFlowDispatchRequestIdentity = private {
            requestRef : TerminalFlowIdentityRef<TerminalFlowDispatchRefKind>
            fillKey : TerminalFlowIdentityRef<TerminalFlowFillRefKind>
        }

        let private terminalFlowDispatchRequestIdentityFor (fillRef:TerminalFlowIdentityRef<TerminalFlowFillRefKind>) =
            let fillKeyText = terminalFlowIdentityRefText fillRef
            let requestIdText = "terminal-global-constituted-dispatch:" + fillKeyText
            { requestRef = terminalFlowIdentityRefOfText requestIdText
              fillKey = fillRef }

        let private terminalFlowDispatchRequestIdentityId (identity:TerminalFlowDispatchRequestIdentity) = terminalFlowIdentityRefText identity.requestRef
        let private terminalFlowDispatchRequestIdentityTypedRef (identity:TerminalFlowDispatchRequestIdentity) = identity.requestRef
        let private terminalFlowDispatchRequestIdentityRef (identity:TerminalFlowDispatchRequestIdentity) = terminalFlowIdentityRefDigest identity.requestRef
        let private terminalFlowDispatchRequestIdentityFillRef (identity:TerminalFlowDispatchRequestIdentity) = identity.fillKey
        let private terminalFlowDispatchRequestIdentityFillKey (identity:TerminalFlowDispatchRequestIdentity) = terminalFlowIdentityRefText identity.fillKey

        type TerminalFlowDispatchConstitutionLineageWitnessKind = class end

        type TerminalFlowGlobalDispatchRequest = private {
            identity : TerminalFlowDispatchRequestIdentity
            joinKey : TerminalFlowDispatchJoinKey
            constitutionLineage : TerminalFlowSchedulerWitness<TerminalFlowDispatchConstitutionLineageWitnessKind>
            pendingTerminal : TerminalFlowSchedulerWitness<TerminalFlowDispatchPendingTerminalWitnessKind>
            admissionIdentity : TerminalFlowAdmissionIdentity
            publication : TerminalFlowDispatchPublication
            execute : unit -> Hopac.Job<TerminalFlowNativeHandoffId>
        }
        with
            member this.requestId = terminalFlowDispatchRequestIdentityId this.identity
            member this.requestRef = terminalFlowDispatchRequestIdentityRef this.identity
            member this.fillRef = terminalFlowDispatchRequestIdentityFillRef this.identity
            member this.fillKeyId = TerminalFlowFillKeyId.ofRef this.fillRef
            member this.fillKey = TerminalFlowFillKeyId.text this.fillKeyId
            member this.constitutionLineageRef = terminalFlowSchedulerWitnessSourceRef this.constitutionLineage
            member this.constitutionLineageProofRef = terminalFlowSchedulerWitnessRef this.constitutionLineage
            member this.pendingTerminalRef = terminalFlowSchedulerWitnessSourceRef this.pendingTerminal
            member this.admissionRef = terminalFlowAdmissionRawRef this.admissionIdentity
            member this.admissionIdentityRef = terminalFlowAdmissionIdentityRef this.admissionIdentity

        type TerminalFlowDurableRef<'Kind> = private TerminalFlowDurableRef of uint32

        let private terminalFlowDurableRefOfText (value:string) : TerminalFlowDurableRef<'Kind> =
            TerminalFlowDurableRef(terminalFlowMintedRefOf "durable_ref" value)

        let private terminalFlowDurableRefValue (TerminalFlowDurableRef reference) = reference

        // A stage-token failure is one semantic identity across possession, total-order,
        // and physical-exit witnesses. Never re-hash the same reason through the generic
        // durable-ref namespace: doing so creates two valid-looking refs for one failure
        // and makes exact lineage matching reject its own exit request.
        let private terminalFlowStageTokenFailureRefOfReason reason : TerminalFlowDurableRef<TerminalFlowFailureRefKind> =
            TerminalFlowDurableRef(terminalFlowMintedRefOf "terminal_stage_token_failure_ref" reason)

        type TerminalFlowPhysicalExitChain =
            | TerminalFlowPhysicalExitWriterCommitted of
                writerCapabilityRef:TerminalFlowDurableRef<TerminalFlowWriterCapabilityRefKind> *
                artifactReceiptRef:TerminalFlowDurableRef<TerminalFlowArtifactReceiptRefKind> *
                exitWitnessRef:TerminalFlowDurableRef<TerminalFlowExitWitnessRefKind>
            | TerminalFlowPhysicalExitTypedFailure of
                failureRef:TerminalFlowDurableRef<TerminalFlowFailureRefKind> *
                exitWitnessRef:TerminalFlowDurableRef<TerminalFlowExitWitnessRefKind>

        // MIGRATION : the physical boundary no longer trusts an
        // ExitWitness alone.  A terminal authority chain is an existential proof
        // that root, outcome, dispatch, actor, writer/artifact/failure and exit
        // all came from the typed reducer/kernel path before System.Environment.Exit.
        type TerminalFlowLegacyTerminalAuthorityState =
            | TerminalFlowLegacyAuthorityQuarantined
            | TerminalFlowLegacyAuthorityRejected of reasonRef:uint32

        type TerminalFlowEndToEndSealCertificate = private {
            sealId : string
            rootReceiptRef : uint32
            terminalReceiptRef : uint32
            fillRef : uint32
            dispatchRef : uint32
            actorRef : uint32
            ownerClosureCertificateRef : uint32
            outcomeIvarFillRef : uint32
            schedulerPushReceiptRef : uint32
            writerWakeReceiptRef : uint32
            writerCapabilityRef : uint32
            artifactReceiptRef : uint32
            failureRef : uint32
            exitWitnessRef : uint32
            stageCapabilityRef : uint32
            receiptProjectionRef : uint32
            causalSpineRef : uint32
            runEndReceiptRef : uint32
            legacyState : TerminalFlowLegacyTerminalAuthorityState
        }

        let private terminalFlowEndToEndSealRef (seal:TerminalFlowEndToEndSealCertificate) =
            terminalFlowMintedRefOf
                "end_to_end_seal_ref"
                (FastRuntimeFormat.format "%s|root=%u|terminal=%u|fill=%u|dispatch=%u|actor=%u|owner=%u|ivar=%u|scheduler=%u|writer_wake=%u|writer=%u|artifact=%u|failure=%u|exit=%u|stage=%u|projection=%u|causal=%u|run_end=%u" [| box seal.sealId; box seal.rootReceiptRef; box seal.terminalReceiptRef; box seal.fillRef; box seal.dispatchRef; box seal.actorRef; box seal.ownerClosureCertificateRef; box seal.outcomeIvarFillRef; box seal.schedulerPushReceiptRef; box seal.writerWakeReceiptRef; box seal.writerCapabilityRef; box seal.artifactReceiptRef; box seal.failureRef; box seal.exitWitnessRef; box seal.stageCapabilityRef; box seal.receiptProjectionRef; box seal.causalSpineRef; box seal.runEndReceiptRef |])

        let private terminalFlowEndToEndSealReady (seal:TerminalFlowEndToEndSealCertificate) =
            seal.rootReceiptRef <> 0u
            && seal.terminalReceiptRef <> 0u
            && seal.fillRef <> 0u
            && seal.dispatchRef <> 0u
            && seal.actorRef <> 0u
            && seal.stageCapabilityRef <> 0u
            && seal.receiptProjectionRef <> 0u
            && seal.causalSpineRef <> 0u
            && seal.runEndReceiptRef <> 0u
            && match seal.legacyState with
               | TerminalFlowLegacyAuthorityQuarantined -> true
               | TerminalFlowLegacyAuthorityRejected _ -> false

        type TerminalFlowTerminalAuthorityPath =
            | TerminalFlowTerminalAuthorityWriterPath of
                writerWakeReceiptRef:TerminalFlowDurableRef<TerminalFlowWriterWakeReceiptRefKind> *
                writerCapabilityRef:TerminalFlowDurableRef<TerminalFlowWriterCapabilityRefKind> *
                artifactReceiptRef:TerminalFlowDurableRef<TerminalFlowArtifactReceiptRefKind>
            | TerminalFlowTerminalAuthorityFailurePath of
                failureRef:TerminalFlowDurableRef<TerminalFlowFailureRefKind>

        type TerminalFlowTerminalAuthorityChain = private {
            authorityId : string
            rootReceiptRef : uint32
            terminalReceiptRef : uint32
            fillRef : uint32
            dispatchRef : uint32
            actorRef : uint32
            ownerClosureCertificateRef : uint32
            outcomeIvarFillRef : uint32
            schedulerPushReceiptRef : uint32
            exitWitnessRef : uint32
            stageCapabilityRef : uint32
            receiptProjectionRef : uint32
            causalSpineRef : uint32
            runEndReceiptRef : uint32
            endToEndSealRef : uint32
            path : TerminalFlowTerminalAuthorityPath
        }

        type TerminalFlowBreakthroughDoneProof = private {
            runEndReceiptRef : uint32
            writerJobRef : uint32
            artifactReceiptRef : uint32
            exitWitnessRef : uint32
            doneAtMs : int64
        }

        type TerminalFlowGlobalExitOrigin =
            | TerminalFlowGlobalExitFromBreakthroughDone of TerminalFlowBreakthroughDoneProof
            | TerminalFlowGlobalExitFromTypedFailure of TerminalFlowDurableRef<TerminalFlowFailureRefKind>

        type TerminalFlowExitRequestIdentity = private {
            requestRef : TerminalFlowIdentityRef<TerminalFlowExitRequestRefKind>
            fillKey : TerminalFlowFillKeyId
        }

        let private terminalFlowNonEmptyExitFillKey requestId fillKey =
            if not (String.IsNullOrWhiteSpace fillKey) then fillKey
            else
                let requestText =
                    if String.IsNullOrWhiteSpace requestId then "missing-request"
                    else requestId
                "terminal-exit-request-fill:" + requestText

        let private terminalFlowExitRequestIdentityFor requestId fillKey =
            let effectiveFillKey = terminalFlowNonEmptyExitFillKey requestId fillKey
            { requestRef = terminalFlowIdentityRefOfText requestId
              fillKey = TerminalFlowFillKeyId.create effectiveFillKey }

        let private terminalFlowExitRequestIdentityTypedRef (identity:TerminalFlowExitRequestIdentity) = identity.requestRef
        let private terminalFlowExitRequestIdentityRef (identity:TerminalFlowExitRequestIdentity) = terminalFlowIdentityRefDigest identity.requestRef
        let private terminalFlowExitRequestIdentityFillRef (identity:TerminalFlowExitRequestIdentity) = TerminalFlowFillKeyId.reference identity.fillKey
        let private terminalFlowExitRequestIdentityFillKey (identity:TerminalFlowExitRequestIdentity) = TerminalFlowFillKeyId.text identity.fillKey

        type TerminalFlowGlobalExitRequest = private {
            identity : TerminalFlowExitRequestIdentity
            exitCode : int
            finalActorPhase : DiagJson.TerminalSchedulerPushActorPhase
            line : string
            physicalChain : TerminalFlowPhysicalExitChain
            origin : TerminalFlowGlobalExitOrigin
        }
        with
            member this.requestId = terminalFlowIdentityRefText this.identity.requestRef
            member this.requestRef = terminalFlowIdentityRefDigest this.identity.requestRef
            member this.fillRef = TerminalFlowFillKeyId.reference this.identity.fillKey
            member this.fillKeyId = this.identity.fillKey
            member this.fillKey = TerminalFlowFillKeyId.text this.identity.fillKey

        let private terminalFlowGlobalExitRequestCreate
            requestId
            fillKey
            exitCode
            finalActorPhase
            line
            physicalChain
            origin
            : TerminalFlowGlobalExitRequest =
            { identity = terminalFlowExitRequestIdentityFor requestId fillKey
              exitCode = exitCode
              finalActorPhase = finalActorPhase
              line = line
              physicalChain = physicalChain
              origin = origin }

        let private terminalFlowGlobalExitOriginText = function
            | TerminalFlowGlobalExitFromBreakthroughDone proof ->
                FastRuntimeFormat.format "breakthrough_done:%u|writer_job=%u|artifact=%u|exit_witness=%u" [| box proof.runEndReceiptRef; box proof.writerJobRef; box proof.artifactReceiptRef; box proof.exitWitnessRef |]
            | TerminalFlowGlobalExitFromTypedFailure failureRef ->
                sprintf "typed_failure:%u" (terminalFlowDurableRefValue failureRef)

        // Bonus migration : drafts and physically-authorized exits are now
        // distinct values.  A TerminalFlowGlobalExitRequest can circulate inside
        // the reducer, but Environment.Exit only receives this private pair,
        // minted after the reducer derives a complete terminal authority chain.
        type TerminalFlowGlobalAuthorizedExit = private {
            request : TerminalFlowGlobalExitRequest
            authority : TerminalFlowTerminalAuthorityChain
            reducerPhysicalExitReceiptRef : uint32
        }

        let private terminalFlowPhysicalExitChainText = function
            | TerminalFlowPhysicalExitWriterCommitted(writerCapabilityRef, artifactReceiptRef, exitWitnessRef) ->
                FastRuntimeFormat.format "PhysicalExitChain(WriterCommitted|writer_ref=%u|artifact_ref=%u|exit_witness_ref=%u)" [| box (terminalFlowDurableRefValue writerCapabilityRef); box (terminalFlowDurableRefValue artifactReceiptRef); box (terminalFlowDurableRefValue exitWitnessRef) |]
            | TerminalFlowPhysicalExitTypedFailure(failureRef, exitWitnessRef) ->
                sprintf "PhysicalExitChain(TypedFailure|failure_ref=%u|exit_witness_ref=%u)"
                    (terminalFlowDurableRefValue failureRef)
                    (terminalFlowDurableRefValue exitWitnessRef)

        let private terminalFlowPhysicalExitChainReason = function
            | TerminalFlowPhysicalExitWriterCommitted _ -> DiagJson.TerminalJsonExitWriterArtifactCommitted
            | TerminalFlowPhysicalExitTypedFailure _ -> DiagJson.TerminalJsonExitTypedFailure

        let private terminalFlowPhysicalExitChainExitWitnessRef = function
            | TerminalFlowPhysicalExitWriterCommitted(_, _, exitWitnessRef) -> terminalFlowDurableRefValue exitWitnessRef
            | TerminalFlowPhysicalExitTypedFailure(_, exitWitnessRef) -> terminalFlowDurableRefValue exitWitnessRef

        type TerminalFlowIndexedClosureExitReplayDisposition =
            | TerminalFlowIndexedClosureExitReplayPublished of requestRef:uint32
            | TerminalFlowIndexedClosureExitReplayAlreadyPublished of requestRef:uint32
            | TerminalFlowIndexedClosureExitReplayRequestMissing

        let private terminalFlowIndexedClosureExitRequestKeyRef requestId =
            CompilerIdentityKernel.ContentDigest.ofText "terminal-indexed-closure-exit-request" requestId

        let private terminalFlowIndexedClosurePendingExitRequests =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, TerminalFlowGlobalExitRequest>()
        // A durable indexed closure can become ready while the reducer is already
        // executing another command. Re-publishing ExitWitnessReady through the
        // control mailbox is still the external wake, but it must not be the sole
        // path back into the single reducer: a saturated/control-busy mailbox can
        // otherwise strand an already-ratified physical-exit witness. Keep one
        // typed request per physical-exit receipt for reducer-inline consumption on
        // the next command turn. The request is removed before reduction, so nested
        // command execution cannot recursively consume it twice.
        let private terminalFlowIndexedClosureInlineExitReplays =
            System.Collections.Concurrent.ConcurrentDictionary<uint32, TerminalFlowGlobalExitRequest>()
        let private terminalFlowIndexedClosureExitReplayKeys =
            System.Collections.Concurrent.ConcurrentDictionary<uint32, byte>()
        let mutable private terminalFlowIndexedClosureExitReplayHook : (TerminalFlowGlobalExitRequest -> unit) = fun _ -> ()
        let mutable private terminalFlowIndexedClosureLateRequestReplayHook : (TerminalFlowGlobalExitRequest -> unit) = fun _ -> ()

        let private terminalFlowInstallIndexedClosureExitReplay hook =
            terminalFlowIndexedClosureExitReplayHook <- hook

        let private terminalFlowInstallIndexedClosureLateRequestReplay hook =
            terminalFlowIndexedClosureLateRequestReplayHook <- hook

        let private terminalFlowRememberIndexedClosureExitRequest (request:TerminalFlowGlobalExitRequest) =
            terminalFlowIndexedClosurePendingExitRequests.[terminalFlowIndexedClosureExitRequestKeyRef request.requestId] <- request
            let occurrence, shouldEmit =
                DiagJson.sparseLogDecision ("indexed_closure_exit_request_retained|" + request.requestId) 8L
            if shouldEmit then
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_indexed_closure_exit_request_retained\",\"request_ref\":%u,\"request_id\":%s,\"fill_ref\":%u,\"exit_witness_ref\":%u,\"exit_code\":%d,\"origin_du\":%s,\"occurrence_count\":%d,\"authority\":\"publisher_and_reducer_share_exit_intent_registry\",\"next\":\"await_indexed_closure_or_direct_reducer_consumption\"}" [| box (terminalFlowMintedRefOf "indexed_closure_exit_request_ref" request.requestId); box (DiagJson.esc request.requestId); box (terminalFlowMintedRefOf "indexed_closure_exit_fill_ref" request.fillKey); box (terminalFlowPhysicalExitChainExitWitnessRef request.physicalChain); box request.exitCode; box (DiagJson.esc (terminalFlowGlobalExitOriginText request.origin)); box occurrence |])
            // The exit intent can arrive after the indexed closure became durable.
            // In that ordering, replay immediately through the late-request hook;
            // exact-once remains guarded by the physical-exit receipt key.
            try terminalFlowIndexedClosureLateRequestReplayHook request with _ -> ()
            request.requestId



        let private terminalFlowReserveIndexedClosureExitReplay physicalExitReceiptRef =
            terminalFlowIndexedClosureExitReplayKeys.TryAdd(physicalExitReceiptRef, 0uy)

        let private terminalFlowRememberIndexedClosureInlineExitReplay physicalExitReceiptRef request =
            terminalFlowIndexedClosureInlineExitReplays.[physicalExitReceiptRef] <- request

        let private terminalFlowTryTakeIndexedClosureInlineExitReplay () =
            terminalFlowIndexedClosureInlineExitReplays.ToArray()
            |> Array.sortBy (fun entry -> entry.Key)
            |> Array.tryPick (fun entry ->
                let mutable request = Unchecked.defaultof<TerminalFlowGlobalExitRequest>
                if terminalFlowIndexedClosureInlineExitReplays.TryRemove(entry.Key, &request) then
                    Some (entry.Key, request)
                else None)

        let private terminalFlowReleaseIndexedClosureExitRequest requestId physicalExitReceiptRef =
            let mutable removedRequest = Unchecked.defaultof<TerminalFlowGlobalExitRequest>
            let mutable removedInlineRequest = Unchecked.defaultof<TerminalFlowGlobalExitRequest>
            let mutable removedReplayKey = 0uy
            terminalFlowIndexedClosurePendingExitRequests.TryRemove(terminalFlowIndexedClosureExitRequestKeyRef requestId, &removedRequest) |> ignore
            terminalFlowIndexedClosureInlineExitReplays.TryRemove(physicalExitReceiptRef, &removedInlineRequest) |> ignore
            terminalFlowIndexedClosureExitReplayKeys.TryRemove(physicalExitReceiptRef, &removedReplayKey) |> ignore



        let private terminalFlowPhysicalExitChainWriterRef = function
            | TerminalFlowPhysicalExitWriterCommitted(writerCapabilityRef, _, _) -> terminalFlowDurableRefValue writerCapabilityRef
            | TerminalFlowPhysicalExitTypedFailure _ -> 0u

        let private terminalFlowPhysicalExitChainArtifactRef = function
            | TerminalFlowPhysicalExitWriterCommitted(_, artifactReceiptRef, _) -> terminalFlowDurableRefValue artifactReceiptRef
            | TerminalFlowPhysicalExitTypedFailure _ -> 0u

        let private terminalFlowPhysicalExitChainFailureRef = function
            | TerminalFlowPhysicalExitWriterCommitted _ -> 0u
            | TerminalFlowPhysicalExitTypedFailure(failureRef, _) -> terminalFlowDurableRefValue failureRef

        let private terminalFlowTypedFailureOriginOfChain = function
            | TerminalFlowPhysicalExitTypedFailure(failureRef, _) -> TerminalFlowGlobalExitFromTypedFailure failureRef
            | TerminalFlowPhysicalExitWriterCommitted _ ->
                invalidOp "typed failure origin requires TerminalFlowPhysicalExitTypedFailure"

        let private terminalFlowPhysicalExitChainMatchesExitCode exitCode actorPhase = function
            | TerminalFlowPhysicalExitWriterCommitted _ ->
                exitCode = 0 && actorPhase = DiagJson.PushActorConsumed
            | TerminalFlowPhysicalExitTypedFailure _ ->
                exitCode <> 0 && actorPhase = DiagJson.PushActorFailedClosed

        let private terminalFlowTerminalAuthorityPathRefs = function
            | TerminalFlowTerminalAuthorityWriterPath(writerWakeRef, writerRef, artifactRef) ->
                "writer", terminalFlowDurableRefValue writerWakeRef, terminalFlowDurableRefValue writerRef, terminalFlowDurableRefValue artifactRef, 0u
            | TerminalFlowTerminalAuthorityFailurePath failureRef ->
                "failure", 0u, 0u, 0u, terminalFlowDurableRefValue failureRef

        let private terminalFlowTerminalAuthorityPathMatches physicalChain path =
            match physicalChain, path with
            | TerminalFlowPhysicalExitWriterCommitted(writerRef, artifactRef, _), TerminalFlowTerminalAuthorityWriterPath(_, authorityWriterRef, authorityArtifactRef) ->
                terminalFlowDurableRefValue writerRef = terminalFlowDurableRefValue authorityWriterRef
                && terminalFlowDurableRefValue artifactRef = terminalFlowDurableRefValue authorityArtifactRef
            | TerminalFlowPhysicalExitTypedFailure(failureRef, _), TerminalFlowTerminalAuthorityFailurePath authorityFailureRef ->
                terminalFlowDurableRefValue failureRef = terminalFlowDurableRefValue authorityFailureRef
            | _ -> false

        let private terminalFlowTerminalAuthorityRef (authority:TerminalFlowTerminalAuthorityChain) =
            let pathTag, writerWakeRef, writerRef, artifactRef, failureRef = terminalFlowTerminalAuthorityPathRefs authority.path
            terminalFlowMintedRefOf
                "terminal_authority_ref"
                (FastRuntimeFormat.format "%s|root=%u|terminal=%u|fill=%u|dispatch=%u|actor=%u|owner=%u|ivar=%u|scheduler=%u|path=%s|writer_wake=%u|writer=%u|artifact=%u|failure=%u|exit=%u|stage=%u|projection=%u|causal=%u|run_end=%u|seal=%u" [| box authority.authorityId; box authority.rootReceiptRef; box authority.terminalReceiptRef; box authority.fillRef; box authority.dispatchRef; box authority.actorRef; box authority.ownerClosureCertificateRef; box authority.outcomeIvarFillRef; box authority.schedulerPushReceiptRef; box pathTag; box writerWakeRef; box writerRef; box artifactRef; box failureRef; box authority.exitWitnessRef; box authority.stageCapabilityRef; box authority.receiptProjectionRef; box authority.causalSpineRef; box authority.runEndReceiptRef; box authority.endToEndSealRef |])

        let private terminalFlowLegacyAuthorityStateText = function
            | TerminalFlowLegacyAuthorityQuarantined -> "legacy_authority_quarantined"
            | TerminalFlowLegacyAuthorityRejected reasonRef -> sprintf "legacy_authority_rejected:%u" reasonRef

        let private terminalFlowTerminalAuthorityText (authority:TerminalFlowTerminalAuthorityChain) =
            let pathTag, writerWakeRef, writerRef, artifactRef, failureRef = terminalFlowTerminalAuthorityPathRefs authority.path
            FastRuntimeFormat.format "TerminalAuthorityChain(id=%s|root=%u|terminal=%u|fill=%u|dispatch=%u|actor=%u|owner_closure=%u|ivar_fill=%u|scheduler_push=%u|path=%s|writer_wake=%u|writer=%u|artifact=%u|failure=%u|exit=%u|stage=%u|projection=%u|causal=%u|run_end=%u|seal=%u)" [| box authority.authorityId; box authority.rootReceiptRef; box authority.terminalReceiptRef; box authority.fillRef; box authority.dispatchRef; box authority.actorRef; box authority.ownerClosureCertificateRef; box authority.outcomeIvarFillRef; box authority.schedulerPushReceiptRef; box pathTag; box writerWakeRef; box writerRef; box artifactRef; box failureRef; box authority.exitWitnessRef; box authority.stageCapabilityRef; box authority.receiptProjectionRef; box authority.causalSpineRef; box authority.runEndReceiptRef; box authority.endToEndSealRef |]

        let private terminalFlowTerminalAuthorityAllowsExit exitCode actorPhase (physicalChain:TerminalFlowPhysicalExitChain) (authority:TerminalFlowTerminalAuthorityChain) =
            authority.endToEndSealRef <> 0u
            && authority.runEndReceiptRef <> 0u
            && authority.exitWitnessRef <> 0u
            && terminalFlowPhysicalExitChainMatchesExitCode exitCode actorPhase physicalChain
            && authority.exitWitnessRef = terminalFlowPhysicalExitChainExitWitnessRef physicalChain
            && terminalFlowTerminalAuthorityPathMatches physicalChain authority.path
            && match physicalChain with
               | TerminalFlowPhysicalExitWriterCommitted _ -> authority.fillRef <> 0u
               | TerminalFlowPhysicalExitTypedFailure _ -> true


        // Destructive domain migration : reconciliation is no
        // longer an untyped retry thunk. A pending terminal candidate owns the
        // only actor-arm continuation and must return a closed transition DU.
        type TerminalFlowDispatchBlocker =
            | TerminalFlowDispatchMissingRoot
            | TerminalFlowDispatchMissingOutcome
            | TerminalFlowDispatchGreenPathMissing
            | TerminalFlowDispatchOutcomeConsumeAlreadyEnqueued of consumeRef:uint32
            | TerminalFlowDispatchTotalOrderNotAwaiting of orderRef:uint32
            | TerminalFlowDispatchPendingTerminalMissing
            | TerminalFlowDispatchCredentialLedgerMissing
            | TerminalFlowDispatchFairnessCredentialMissing of admissionIdentityRef:uint32
            | TerminalFlowDispatchRecoveryCredentialMissing of admissionIdentityRef:uint32
            | TerminalFlowDispatchCredentialGraphOpen of ledgerRef:uint32
            | TerminalFlowDispatchCredentialGraphCycleClosed of cycleRef:uint32
            | TerminalFlowDispatchRecursiveProofMissing
            | TerminalFlowDispatchAdmissionIdentityMismatch of expectedRef:uint32 * actualRef:uint32
            | TerminalFlowDispatchPendingFillMismatch of expectedRef:uint32 * actualRef:uint32
            | TerminalFlowDispatchActorAlreadyAdvanced of DiagJson.TerminalSchedulerPushActorPhase
            | TerminalFlowDispatchJoinKeyMismatch of expectedRef:uint32 * actualRef:uint32
            | TerminalFlowDispatchContinuationRejected of reasonRef:uint32

        let private terminalFlowDispatchBlockerText = function
            | TerminalFlowDispatchMissingRoot -> "missing_root"
            | TerminalFlowDispatchMissingOutcome -> "missing_outcome"
            | TerminalFlowDispatchGreenPathMissing -> "green_path_missing"
            | TerminalFlowDispatchOutcomeConsumeAlreadyEnqueued consumeRef -> sprintf "outcome_consume_already_enqueued:consume_ref=%u" consumeRef
            | TerminalFlowDispatchTotalOrderNotAwaiting orderRef -> sprintf "total_order_not_awaiting:order_ref=%u" orderRef
            | TerminalFlowDispatchPendingTerminalMissing -> "pending_terminal_missing"
            | TerminalFlowDispatchCredentialLedgerMissing -> "credential_ledger_missing"
            | TerminalFlowDispatchFairnessCredentialMissing admissionIdentityRef -> sprintf "fairness_credential_missing:admission=%u" admissionIdentityRef
            | TerminalFlowDispatchRecoveryCredentialMissing admissionIdentityRef -> sprintf "recovery_credential_missing:admission=%u" admissionIdentityRef
            | TerminalFlowDispatchCredentialGraphOpen ledgerRef -> sprintf "credential_graph_open:ledger_ref=%u" ledgerRef
            | TerminalFlowDispatchCredentialGraphCycleClosed cycleRef -> sprintf "credential_graph_cycle_closed:cycle_ref=%u" cycleRef
            | TerminalFlowDispatchRecursiveProofMissing -> "recursive_dispatch_proof_missing"
            | TerminalFlowDispatchAdmissionIdentityMismatch(expectedRef, actualRef) -> sprintf "admission_identity_mismatch:expected=%u:actual=%u" expectedRef actualRef
            | TerminalFlowDispatchPendingFillMismatch(expectedRef, actualRef) -> sprintf "pending_fill_mismatch:expected=%u:actual=%u" expectedRef actualRef
            | TerminalFlowDispatchActorAlreadyAdvanced phase -> "actor_already_advanced:" + DiagJson.terminalSchedulerPushActorPhaseText phase
            | TerminalFlowDispatchJoinKeyMismatch(expectedRef, actualRef) -> sprintf "join_key_mismatch:expected=%u:actual=%u" expectedRef actualRef
            | TerminalFlowDispatchContinuationRejected reasonRef -> sprintf "continuation_rejected:reason_ref=%u" reasonRef

        type TerminalFlowSchedulerPushTransition =
            | TerminalFlowSchedulerPushArmAttempted of fillRef:uint32 * terminalRef:uint32
            | TerminalFlowSchedulerPushDispatchAccepted of requestRef:uint32 * dispatchKeyRef:uint32
            | TerminalFlowSchedulerPushDispatchAlreadyExists of requestRef:uint32 * dispatchKeyRef:uint32
            | TerminalFlowSchedulerPushDispatchRejected of TerminalFlowDispatchBlocker
            | TerminalFlowSchedulerPushDispatchFailClosed of reasonRef:uint32

        type TerminalFlowPendingTerminalIntent =
            | TerminalFlowPendingBuildOk
            | TerminalFlowPendingNoFurther
            | TerminalFlowPendingQuarantine
            | TerminalFlowPendingFailClosed

        // MIGRATION: terminal outcomes now carry a phantom maturity witness.
        // Provisional observations may be replaced while the reducer is still
        // converging; only final outcomes may consume the single dispatch edge.
        type TerminalFlowOutcomeProvisionalStage = class end
        type TerminalFlowOutcomeFinalStage = class end

        type TerminalFlowOutcomeMaturityToken<'Stage> = private {
            intent : TerminalFlowPendingTerminalIntent
            maturityRef : TerminalFlowIdentityRef<TerminalFlowStageCapabilityRefKind>
        }

        type TerminalFlowOutcomeMaturityBox =
            | TerminalFlowOutcomeProvisional of TerminalFlowOutcomeMaturityToken<TerminalFlowOutcomeProvisionalStage>
            | TerminalFlowOutcomeFinal of TerminalFlowOutcomeMaturityToken<TerminalFlowOutcomeFinalStage>

        let private terminalFlowPendingIntentMaturityLabel = function
            | TerminalFlowPendingBuildOk -> "final_build_ok"
            | TerminalFlowPendingFailClosed -> "final_fail_closed"
            | TerminalFlowPendingNoFurther -> "provisional_no_further"
            | TerminalFlowPendingQuarantine -> "provisional_quarantine"

        let private terminalFlowPendingOutcomeMaturity intent =
            let maturityRef =
                terminalFlowIdentityRefOfText
                    (sprintf "terminal_outcome_maturity|intent=%s|stage=%s" (terminalFlowPendingIntentMaturityLabel intent) (terminalFlowPendingIntentMaturityLabel intent))
            match intent with
            | TerminalFlowPendingBuildOk
            | TerminalFlowPendingFailClosed ->
                TerminalFlowOutcomeFinal { intent = intent; maturityRef = maturityRef }
            | TerminalFlowPendingNoFurther
            | TerminalFlowPendingQuarantine ->
                TerminalFlowOutcomeProvisional { intent = intent; maturityRef = maturityRef }

        let private terminalFlowPendingOutcomeIsFinal intent =
            match terminalFlowPendingOutcomeMaturity intent with
            | TerminalFlowOutcomeFinal _ -> true
            | TerminalFlowOutcomeProvisional _ -> false

        let private terminalFlowOutcomeMaturityRef = function
            | TerminalFlowOutcomeFinal token -> terminalFlowIdentityRefDigest token.maturityRef
            | TerminalFlowOutcomeProvisional token -> terminalFlowIdentityRefDigest token.maturityRef

        let private terminalFlowOutcomeMaturityText = function
            | TerminalFlowOutcomeFinal token -> sprintf "Final(%s)" (terminalFlowPendingIntentMaturityLabel token.intent)
            | TerminalFlowOutcomeProvisional token -> sprintf "Provisional(%s)" (terminalFlowPendingIntentMaturityLabel token.intent)

        type TerminalFlowOwnerDebtAdmissionPermit = private {
            decisionRef : uint32
            closeReceiptRef : uint32
        }

        type TerminalFlowPendingAdmission =
            | TerminalFlowPendingAdmissionReducerOwnerDebt of TerminalFlowOwnerDebtAdmissionPermit
            | TerminalFlowPendingAdmissionEvaluatorNotice of sourceRef:uint32
            | TerminalFlowPendingAdmissionSafetyWatchdog of sourceRef:uint32

        let private terminalFlowPendingAdmissionText = function
            | TerminalFlowPendingAdmissionReducerOwnerDebt permit ->
                sprintf "reducer_owner_debt|decision_ref=%u|close_receipt_ref=%u" permit.decisionRef permit.closeReceiptRef
            | TerminalFlowPendingAdmissionEvaluatorNotice sourceRef ->
                sprintf "evaluator_notice|source_ref=%u" sourceRef
            | TerminalFlowPendingAdmissionSafetyWatchdog sourceRef ->
                sprintf "safety_watchdog|source_ref=%u" sourceRef

        let private terminalFlowPendingAdmissionRef = function
            | TerminalFlowPendingAdmissionEvaluatorNotice sourceRef
            | TerminalFlowPendingAdmissionSafetyWatchdog sourceRef -> sourceRef
            | TerminalFlowPendingAdmissionReducerOwnerDebt permit -> permit.decisionRef

        let private terminalFlowPendingAdmissionIsSafetyWatchdog = function
            | TerminalFlowPendingAdmissionSafetyWatchdog _ -> true
            | _ -> false

        // MIGRATION: lineage equality is typed.  Rendering remains diagnostic-only;
        // no admission authority may be reconstructed from text.
        let private terminalFlowPendingAdmissionSame left right =
            match left, right with
            | TerminalFlowPendingAdmissionReducerOwnerDebt leftPermit,
              TerminalFlowPendingAdmissionReducerOwnerDebt rightPermit ->
                leftPermit.decisionRef = rightPermit.decisionRef
                && leftPermit.closeReceiptRef = rightPermit.closeReceiptRef
            | TerminalFlowPendingAdmissionEvaluatorNotice leftRef,
              TerminalFlowPendingAdmissionEvaluatorNotice rightRef
            | TerminalFlowPendingAdmissionSafetyWatchdog leftRef,
              TerminalFlowPendingAdmissionSafetyWatchdog rightRef -> leftRef = rightRef
            | _ -> false


        type TerminalFlowArmedOutcomeJoinedStage = class end
        type TerminalFlowOutcomeFilledByHopacStage = class end
        type TerminalFlowWriterCapabilityBoundByHopacStage = class end
        type TerminalFlowCommitReceiptEmittedStage = class end
        type TerminalFlowWorkDagTailClosedStage = class end
        type TerminalFlowOwnerLedgerClosedStage = class end
        type TerminalFlowWakerEdgeRegisteredStage = class end
        type TerminalFlowDoneSealedStage = class end

        type TerminalFlowPhantomOwnerKind =
            | TerminalFlowPhantomOwnerParentContinuation
            | TerminalFlowPhantomOwnerCrossKind
            | TerminalFlowPhantomOwnerSidecarDrain
            | TerminalFlowPhantomOwnerDynamicBridge
            | TerminalFlowPhantomOwnerProceduralResidual
            | TerminalFlowPhantomOwnerWorkDagTail

        type TerminalFlowPhantomOwnerClose<'Stage> = private {
            ownerKind : TerminalFlowPhantomOwnerKind
            ownerRef : uint32
            closeKeyRef : uint32
            closeReceiptRef : uint32
            materialDelta : int
            remainingObligations : int
        }

        type TerminalFlowWakerEdgeReceipt<'Stage> = private {
            edgeRef : uint32
            sourceOwnerRef : uint32
            targetTokenRef : uint32
            registeredAtMs : int64
        }

        type TerminalFlowWorkDagTailClosureReason =
            | TerminalFlowWorkDagClosedByReducerOwnerDebt
            | TerminalFlowWorkDagClosedByCanonicalTerminalReceipt

        let private terminalFlowWorkDagTailClosureReasonText = function
            | TerminalFlowWorkDagClosedByReducerOwnerDebt -> "workdag_tail_closed_by_reducer_owner_debt"
            | TerminalFlowWorkDagClosedByCanonicalTerminalReceipt -> "workdag_tail_closed_by_canonical_terminal_receipt"

        // MIGRATION / destructive migration migration phase:
        // The owner ledger and WorkDag tail are no longer a pair of counters plus HUD prose.
        // They form a staged close protocol.  QAP finalization may consume only a
        // TerminalFlowOwnerLedgerCloseCertificate whose WorkDag tail proof is already sealed.
        type TerminalFlowOwnerLedgerOpenStage = class end
        type TerminalFlowOwnerLedgerClosingStage = class end
        type TerminalFlowOwnerLedgerSealedStage = class end
        type TerminalFlowWorkDagProgressingStage = class end
        type TerminalFlowWorkDagTerminalEligibleStage = class end
        type TerminalFlowWorkDagKeepDrainingStage = class end
        type TerminalFlowWorkDagClosedByReducerStage = class end

        [<Struct>]
        type TerminalFlowOwnerLedgerProtocolId<'Kind> = private | TerminalFlowOwnerLedgerProtocolId of uint64

        let private terminalFlowOwnerLedgerProtocolIdValue (TerminalFlowOwnerLedgerProtocolId value) = value

        [<Struct>]
        type TerminalFlowWorkDagProtocolId<'Kind> = private | TerminalFlowWorkDagProtocolId of uint64

        [<Struct>]
        type TerminalFlowOwnerLedgerKind = struct end

        [<Struct>]
        type TerminalFlowWorkDagKind = struct end

        [<Struct>]
        type TerminalFlowOwnerCloseKeyKind = struct end

        [<Struct>]
        type TerminalFlowOwnerCloseReceiptKind = struct end

        [<Struct>]
        type TerminalFlowWorkDagTailProofKind = struct end

        type TerminalFlowOwnerLedgerCloseKey<'OwnerKind> = private {
            closeKeyRef : TerminalFlowOwnerLedgerProtocolId<TerminalFlowOwnerCloseKeyKind>
            ownerKind : TerminalFlowPhantomOwnerKind
            ownerRef : uint32
            materialEpoch : int64
            qapFixpointRef : uint32
        }

        type TerminalFlowOwnerLedgerEntry<'OwnerKind,'Stage> = private {
            closeKey : TerminalFlowOwnerLedgerCloseKey<'OwnerKind>
            obligationRef : uint32
            ownerKind : TerminalFlowPhantomOwnerKind
            materialDelta : int64
            wakerRef : uint32 option
            relationRef : uint32 option
        }

        type TerminalFlowOwnerLedgerQuarantineReason =
            | TerminalFlowOwnerLedgerProducerShapeRejected of producerRef:uint32
            | TerminalFlowOwnerLedgerRequirementSatisfierMismatch of requirementRef:uint32 * satisfierRef:uint32
            | TerminalFlowOwnerLedgerQapNotFullyDrained of qapRef:uint32
            | TerminalFlowOwnerLedgerCloseReceiptLineageMismatch of closeReceiptRef:uint32 * ownerRef:uint32

        let private terminalFlowOwnerLedgerQuarantineReasonText = function
            | TerminalFlowOwnerLedgerProducerShapeRejected producerRef -> sprintf "producer_shape_rejected:%u" producerRef
            | TerminalFlowOwnerLedgerRequirementSatisfierMismatch(requirementRef, satisfierRef) -> sprintf "requirement_satisfier_mismatch:%u:%u" requirementRef satisfierRef
            | TerminalFlowOwnerLedgerQapNotFullyDrained qapRef -> sprintf "qap_not_fully_drained:%u" qapRef
            | TerminalFlowOwnerLedgerCloseReceiptLineageMismatch(closeReceiptRef, ownerRef) -> sprintf "close_receipt_lineage_mismatch:%u:%u" closeReceiptRef ownerRef

        type TerminalFlowOwnerLedger<'OwnerKind,'Stage> =
            | TerminalFlowOwnerLedgerEmpty of ledgerRef:TerminalFlowOwnerLedgerProtocolId<TerminalFlowOwnerLedgerKind>
            | TerminalFlowOwnerLedgerCons of TerminalFlowOwnerLedgerEntry<'OwnerKind,'Stage> * TerminalFlowOwnerLedger<'OwnerKind,'Stage>
            | TerminalFlowOwnerLedgerQuarantined of ledgerRef:TerminalFlowOwnerLedgerProtocolId<TerminalFlowOwnerLedgerKind> * reason:TerminalFlowOwnerLedgerQuarantineReason

        // MIGRATION / domain migration migration phase:
        // an obligation may not exist without a total, named satisfier.  The
        // WorkDag tail is now a recursive state machine instead of a bag of
        // counters whose meaning lived in HUD strings.
        type TerminalFlowRequirementOpenStage = class end
        type TerminalFlowRequirementSatisfiedStage = class end
        type TerminalFlowRequirementRejectedStage = class end
        type TerminalFlowWorkDagTailRequirementKind = struct end

        type TerminalFlowRequirementSatisfierRoute =
            | TerminalFlowSatisfierFromReducerCloseReceipt
            | TerminalFlowSatisfierFromQueueRecoveryReceipt
            | TerminalFlowSatisfierFromGreenPathReceipt
            | TerminalFlowSatisfierFromTotalOrderPredecessor
            | TerminalFlowSatisfierFromBreakthroughCertificate
            | TerminalFlowSatisfierFromFinalOutcome
            | TerminalFlowSatisfierFromRootCapability

        type TerminalFlowRequirementSatisfier<'Kind> = private {
            route : TerminalFlowRequirementSatisfierRoute
            routeRef : uint32
            minterRef : uint32
            exactOnceRef : uint32
        }

        type TerminalFlowRequirement<'Kind,'Stage> =
            | TerminalFlowRequirementOpen of requirementRef:uint32 * openedAtMs:int64 * satisfier:TerminalFlowRequirementSatisfier<'Kind>
            | TerminalFlowRequirementSatisfied of requirementRef:uint32 * receiptRef:uint32 * satisfier:TerminalFlowRequirementSatisfier<'Kind> * satisfiedAtSequence:int64
            | TerminalFlowRequirementRejected of requirementRef:uint32 * reasonRef:uint32 * satisfier:TerminalFlowRequirementSatisfier<'Kind> * rejectedAtSequence:int64

        type TerminalFlowWorkDagTailSnapshot = private {
            workDagRef : TerminalFlowWorkDagProtocolId<TerminalFlowWorkDagKind>
            tailRef : uint32
            ownerLedgerRef : uint32
            openEdgeCount : int
            blockedEdgeCount : int
            activeProducerCount : int
            materialEpoch : int64
            qapResolutionRef : uint32
            drainPassCount : int
            zeroDeltaStreak : int
            firstObservedAtMs : int64
            lastMaterialAtMs : int64
        }

        type TerminalFlowWorkDagTail<'Stage> =
            | TerminalFlowWorkDagTailLive of snapshot:TerminalFlowWorkDagTailSnapshot * closeRequirement:TerminalFlowRequirement<TerminalFlowWorkDagTailRequirementKind,TerminalFlowRequirementOpenStage>
            | TerminalFlowWorkDagTailPendingDrain of snapshot:TerminalFlowWorkDagTailSnapshot * writerLeaseRef:uint32 * materialDelta:int64 * closeRequirement:TerminalFlowRequirement<TerminalFlowWorkDagTailRequirementKind,TerminalFlowRequirementOpenStage>
            | TerminalFlowWorkDagTailClosed of snapshot:TerminalFlowWorkDagTailSnapshot * closeReceiptRef:uint32 * closeRequirement:TerminalFlowRequirement<TerminalFlowWorkDagTailRequirementKind,TerminalFlowRequirementSatisfiedStage>
            | TerminalFlowWorkDagTailQuarantined of snapshot:TerminalFlowWorkDagTailSnapshot * reasonRef:uint32 * closeRequirement:TerminalFlowRequirement<TerminalFlowWorkDagTailRequirementKind,TerminalFlowRequirementRejectedStage>

        let private terminalFlowWorkDagTailSnapshot = function
            | TerminalFlowWorkDagTailLive(snapshot, _)
            | TerminalFlowWorkDagTailPendingDrain(snapshot, _, _, _)
            | TerminalFlowWorkDagTailClosed(snapshot, _, _)
            | TerminalFlowWorkDagTailQuarantined(snapshot, _, _) -> snapshot

        let private terminalFlowWorkDagTailRef tail =
            (terminalFlowWorkDagTailSnapshot tail).tailRef

        let private terminalFlowWorkDagTailStateText = function
            | TerminalFlowWorkDagTailLive(snapshot, _) ->
                FastRuntimeFormat.format "Live(tail_ref=%u|open=%d|blocked=%d|active=%d|passes=%d|zero_delta=%d)" [| box snapshot.tailRef; box snapshot.openEdgeCount; box snapshot.blockedEdgeCount; box snapshot.activeProducerCount; box snapshot.drainPassCount; box snapshot.zeroDeltaStreak |]
            | TerminalFlowWorkDagTailPendingDrain(snapshot, writerLeaseRef, materialDelta, _) ->
                FastRuntimeFormat.format "PendingDrain(tail_ref=%u|writer_lease_ref=%u|material_delta=%d|passes=%d|zero_delta=%d)" [| box snapshot.tailRef; box writerLeaseRef; box materialDelta; box snapshot.drainPassCount; box snapshot.zeroDeltaStreak |]
            | TerminalFlowWorkDagTailClosed(snapshot, closeReceiptRef, _) ->
                FastRuntimeFormat.format "Closed(tail_ref=%u|close_receipt_ref=%u|qap_ref=%u)" [| box snapshot.tailRef; box closeReceiptRef; box snapshot.qapResolutionRef |]
            | TerminalFlowWorkDagTailQuarantined(snapshot, reasonRef, _) ->
                sprintf "Quarantined(tail_ref=%u|reason_ref=%u)" snapshot.tailRef reasonRef

        type TerminalFlowWorkDagTailDrainDecision =
            | TerminalFlowWorkDagTailContinueDraining of TerminalFlowWorkDagTailSnapshot
            | TerminalFlowWorkDagTailCloseEligible of TerminalFlowWorkDagTailSnapshot * closeReceiptRef:uint32
            | TerminalFlowWorkDagTailProvenDeadlock of TerminalFlowWorkDagTailSnapshot * reasonRef:uint32

        let private terminalFlowWorkDagTailDrainDecision zeroDeltaCap materialDelta (snapshot:TerminalFlowWorkDagTailSnapshot) =
            let nextPass = snapshot.drainPassCount + 1
            let nextZeroDeltaStreak = if materialDelta = 0L then snapshot.zeroDeltaStreak + 1 else 0
            let next =
                { snapshot with
                    drainPassCount = nextPass
                    zeroDeltaStreak = nextZeroDeltaStreak
                    lastMaterialAtMs = if materialDelta > 0L then Environment.TickCount64 else snapshot.lastMaterialAtMs }
            if materialDelta > 0L then
                TerminalFlowWorkDagTailContinueDraining next
            elif next.openEdgeCount = 0 && next.activeProducerCount = 0 && nextZeroDeltaStreak >= zeroDeltaCap then
                let closeReceiptRef =
                    terminalFlowMintedRefOf
                        "workdag_tail_close_after_zero_delta_ref"
                        (FastRuntimeFormat.format "%u:%d:%d:%d" [| box next.tailRef; box next.materialEpoch; box next.drainPassCount; box nextZeroDeltaStreak |])
                TerminalFlowWorkDagTailCloseEligible(next, closeReceiptRef)
            elif nextZeroDeltaStreak >= zeroDeltaCap then
                let reasonRef =
                    terminalFlowMintedRefOf
                        "workdag_tail_proven_deadlock_ref"
                        (FastRuntimeFormat.format "%u:%d:%d:%d:%d" [| box next.tailRef; box next.openEdgeCount; box next.blockedEdgeCount; box next.activeProducerCount; box nextZeroDeltaStreak |])
                TerminalFlowWorkDagTailProvenDeadlock(next, reasonRef)
            else
                TerminalFlowWorkDagTailContinueDraining next

        type TerminalFlowWorkDagTailCloseProof<'OwnerKind> = private {
            proofRef : TerminalFlowOwnerLedgerProtocolId<TerminalFlowWorkDagTailProofKind>
            workDagTail : TerminalFlowWorkDagTail<TerminalFlowWorkDagClosedByReducerStage>
            ownerLedgerRef : uint32
            closedOwnerCount : int
            openOwnerCount : int
            acyclicByConstruction : bool
            residualQapResolutionRef : uint32
            reducerSequence : int64
        }

        type TerminalFlowOwnerLedgerCloseReceipt<'OwnerKind> = private {
            receiptRef : TerminalFlowOwnerLedgerProtocolId<TerminalFlowOwnerCloseReceiptKind>
            closeKey : TerminalFlowOwnerLedgerCloseKey<'OwnerKind>
            closedEntry : TerminalFlowOwnerLedgerEntry<'OwnerKind,TerminalFlowOwnerLedgerClosingStage>
            workDagTailProof : TerminalFlowWorkDagTailCloseProof<'OwnerKind>
            materialEpochBefore : int64
            materialEpochAfter : int64
            reducerSequence : int64
        }

        type TerminalFlowOwnerLedgerCloseCertificate<'OwnerKind> = private {
            certificateRef : uint32
            ledger : TerminalFlowOwnerLedger<'OwnerKind,TerminalFlowOwnerLedgerSealedStage>
            workDagTailProof : TerminalFlowWorkDagTailCloseProof<'OwnerKind>
            closeReceipts : TerminalFlowOwnerLedgerCloseReceipt<'OwnerKind> list
            qapResolution : TerminalFlowQapResolutionBox
            shutdownReconciliationRef : uint32 option
        }

        // MIGRATION / destructive migration migration phase:
        // The reducer now sees owner closure as one authority algebra.  A sealed
        // ledger certificate and a complete observer bridge are two constructors
        // of the same protocol; projection-only exits are a rejected constructor,
        // not a second truth table.
        type TerminalFlowOwnerClosureAuthority<'OwnerKind> =
            | TerminalFlowOwnerClosureReducerSealed of TerminalFlowOwnerLedgerCloseCertificate<'OwnerKind>
            | TerminalFlowOwnerClosureObserverBridge of DiagJson.ObserverTerminalExitPetitionEvidence
            | TerminalFlowOwnerClosureRejectedProjection of sourceRef:uint32 * reason:CompilerKernelV2.OperationalReasonId

        let private terminalFlowOwnerClosureAuthorityRef = function
            | TerminalFlowOwnerClosureReducerSealed certificate -> certificate.certificateRef
            | TerminalFlowOwnerClosureObserverBridge petition ->
                DiagJson.observerTerminalOwnerClosureAuthorityRef petition.ownerClosureAuthority
            | TerminalFlowOwnerClosureRejectedProjection(sourceRef, reason) ->
                terminalFlowMintedRefOf "owner_closure_projection_rejected_ref" (sprintf "%u:%s" sourceRef (CompilerKernelV2.OperationalReasonIdOps.text reason))

        let private terminalFlowOwnerClosureAuthorityText = function
            | TerminalFlowOwnerClosureReducerSealed certificate ->
                FastRuntimeFormat.format "OwnerClosureAuthoritySpine(ReducerSealed|certificate_ref=%u|workdag_ref=%u|qap_ref=%u|receipts=%d)" [| box certificate.certificateRef; box certificate.workDagTailProof.ownerLedgerRef; box (terminalFlowQapResolutionBoxRef certificate.qapResolution); box certificate.closeReceipts.Length |]
            | TerminalFlowOwnerClosureObserverBridge petition ->
                FastRuntimeFormat.format "OwnerClosureAuthoritySpine(ObserverBridge|petition_ref=%u|authority_ref=%u|authority=%s)" [| box petition.petitionRef; box (DiagJson.observerTerminalOwnerClosureAuthorityRef petition.ownerClosureAuthority); box (DiagJson.observerTerminalOwnerClosureAuthorityText petition.ownerClosureAuthority) |]
            | TerminalFlowOwnerClosureRejectedProjection(sourceRef, reason) ->
                sprintf "OwnerClosureAuthoritySpine(RejectedProjection|source_ref=%u|reason=%s)" sourceRef (CompilerKernelV2.OperationalReasonIdOps.text reason)

        // MIGRATION / destructive migration migration phase:
        // The final terminal order is now a typed corridor.  A Final outcome is not
        // enough by itself: it must consume the QAP resolution and the sealed owner
        // tail certificate before commit/done/run_end/physical-exit authority can be
        // represented.  This intentionally demotes observer shutdown, legacy recovery
        // and HUD progress to projections rather than terminal authorities.
        type TerminalFlowTerminalOrderAwaitFinalOutcomeStage = class end
        type TerminalFlowTerminalOrderPrerequisitesSealedStage = class end
        type TerminalFlowTerminalOrderCommittedStage = class end
        type TerminalFlowTerminalOrderDoneStage = class end
        type TerminalFlowTerminalOrderRunEndedStage = class end
        type TerminalFlowTerminalOrderPhysicalExitSelectedStage = class end

        [<Struct>]
        type TerminalFlowTerminalOrderId<'Stage> = private | TerminalFlowTerminalOrderId of uint64

        type TerminalFlowTerminalOrderPath =
            | TerminalFlowTerminalOrderBuildOkAdmissionPath of dispatchAdmissionRef:uint32 * queueRecoveryRef:uint32 * greenPathCertificateRef:uint32
            | TerminalFlowTerminalOrderFailClosedPath of failureReceiptRef:uint32 * deadlockProofRef:uint32 * typedFailureCommittedRef:uint32

        let private terminalFlowTerminalOrderPathText = function
            | TerminalFlowTerminalOrderBuildOkAdmissionPath(dispatchAdmissionRef, queueRecoveryRef, greenPathCertificateRef) ->
                FastRuntimeFormat.format "build_ok_admission_path|dispatch_admission_ref=%u|queue_recovery_ref=%u|green_path_certificate_ref=%u" [| box dispatchAdmissionRef; box queueRecoveryRef; box greenPathCertificateRef |]
            | TerminalFlowTerminalOrderFailClosedPath(failureReceiptRef, deadlockProofRef, typedFailureCommittedRef) ->
                FastRuntimeFormat.format "fail_closed_path|failure_receipt_ref=%u|deadlock_proof_ref=%u|typed_failure_committed_ref=%u" [| box failureReceiptRef; box deadlockProofRef; box typedFailureCommittedRef |]

        type TerminalFlowFinalOutcomePrerequisites<'OwnerKind> = private {
            finalOutcome : TerminalFlowOutcomeMaturityToken<TerminalFlowOutcomeFinalStage>
            ownerCertificate : TerminalFlowOwnerLedgerCloseCertificate<'OwnerKind>
            workDagTailProof : TerminalFlowWorkDagTailCloseProof<'OwnerKind>
            qapResolution : TerminalFlowQapResolutionBox
            terminalPath : TerminalFlowTerminalOrderPath
            fillOnceRef : uint32
            dispatchRequestRef : uint32
            actorStageTokenRef : uint32
            constitutionRef : uint32
            predecessorOrderRef : uint32
            exactOnceRef : uint32
        }

        type TerminalFlowTerminalOrderReceipt<'Stage,'OwnerKind> = private {
            orderId : TerminalFlowTerminalOrderId<'Stage>
            prerequisites : TerminalFlowFinalOutcomePrerequisites<'OwnerKind>
            totalOrderIndex : int64
            receiptRef : uint32
            reducerSequence : int64
        }

        type TerminalFlowCommitReceipt<'OwnerKind> = private {
            committedOrder : TerminalFlowTerminalOrderReceipt<TerminalFlowTerminalOrderPrerequisitesSealedStage,'OwnerKind>
            commitReceiptId : uint32
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            artifactOrFailureRef : uint32
            committedAtMs : int64
        }

        type TerminalFlowDoneReceipt<'OwnerKind> = private {
            commit : TerminalFlowCommitReceipt<'OwnerKind>
            doneReceiptId : uint32
            terminalDoneTransitionRef : uint32
            doneAtMs : int64
        }

        type TerminalFlowRunEndReceipt<'OwnerKind> = private {
            doneReceipt : TerminalFlowDoneReceipt<'OwnerKind>
            runEndReceiptId : uint32
            runEndSelectedRef : uint32
            durableRunEndRef : uint32
            exactOnceRef : uint32
            runEndedAtMs : int64
        }

        type TerminalFlowReducerProcessExitAuthorization =
            | TerminalFlowReducerProcessExitRatified
            | TerminalFlowReducerProcessExitRejected of CompilerKernelV2.OperationalReasonId

        let terminalFlowReducerProcessExitAuthorizationText = function
            | TerminalFlowReducerProcessExitRatified -> "Ratified"
            | TerminalFlowReducerProcessExitRejected reason -> "Rejected(" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let terminalFlowReducerProcessExitAuthorizationAllows = function
            | TerminalFlowReducerProcessExitRatified -> true
            | TerminalFlowReducerProcessExitRejected _ -> false

        type TerminalFlowPhysicalExitSelection<'OwnerKind> = private {
            runEnd : TerminalFlowRunEndReceipt<'OwnerKind>
            physicalExitReceiptId : uint32
            exitCode : int
            path : TerminalFlowTerminalOrderPath
            processExitAuthorization : TerminalFlowReducerProcessExitAuthorization
            selectedAtMs : int64
        }

        type TerminalFlowTypedFailureOrderReceipt = private {
            failureRef : uint32
            terminalRef : uint32
            fillRef : uint32
            commitReceiptId : uint32
            doneReceiptId : uint32
            runEndReceiptId : uint32
            physicalExitReceiptId : uint32
            exactOnceRef : uint32
            constitutionRef : uint32
            exitCode : int
            processExitAuthorization : TerminalFlowReducerProcessExitAuthorization
            selectedAtMs : int64
        }

        type TerminalFlowTerminalOrderCutover<'OwnerKind> =
            | TerminalFlowTerminalOrderAwaitFinalOutcome of blocker:string
            | TerminalFlowTerminalOrderPrerequisitesSealed of TerminalFlowTerminalOrderReceipt<TerminalFlowTerminalOrderPrerequisitesSealedStage,'OwnerKind>
            | TerminalFlowTerminalOrderCommitReady of TerminalFlowCommitReceipt<'OwnerKind>
            | TerminalFlowTerminalOrderDoneReady of TerminalFlowDoneReceipt<'OwnerKind>
            | TerminalFlowTerminalOrderRunEndReady of TerminalFlowRunEndReceipt<'OwnerKind>
            | TerminalFlowTerminalOrderPhysicalExitReady of TerminalFlowPhysicalExitSelection<'OwnerKind>
            | TerminalFlowTerminalOrderTypedFailureReady of TerminalFlowTypedFailureOrderReceipt
            | TerminalFlowTerminalOrderRejected of blocker:string * blockerRef:uint32

        let private terminalFlowTerminalOrderCutoverText = function
            | TerminalFlowTerminalOrderAwaitFinalOutcome blocker -> "terminal_order_await_final_outcome|blocker=" + blocker
            | TerminalFlowTerminalOrderPrerequisitesSealed receipt -> sprintf "terminal_order_prerequisites_sealed|receipt_ref=%u|total_order_index=%d" receipt.receiptRef receipt.totalOrderIndex
            | TerminalFlowTerminalOrderCommitReady receipt -> sprintf "terminal_order_commit_ready|commit_receipt_id=%u|artifact_or_failure_ref=%u" receipt.commitReceiptId receipt.artifactOrFailureRef
            | TerminalFlowTerminalOrderDoneReady receipt -> sprintf "terminal_order_done_ready|done_receipt_id=%u|commit_receipt_id=%u" receipt.doneReceiptId receipt.commit.commitReceiptId
            | TerminalFlowTerminalOrderRunEndReady receipt -> sprintf "terminal_order_run_end_ready|run_end_receipt_id=%u|done_receipt_id=%u" receipt.runEndReceiptId receipt.doneReceipt.doneReceiptId
            | TerminalFlowTerminalOrderPhysicalExitReady receipt ->
                FastRuntimeFormat.format "terminal_order_physical_exit_ready|physical_exit_receipt_id=%u|exit_code=%d|authorization=%s" [| box receipt.physicalExitReceiptId; box receipt.exitCode; box (terminalFlowReducerProcessExitAuthorizationText receipt.processExitAuthorization) |]
            | TerminalFlowTerminalOrderTypedFailureReady receipt ->
                FastRuntimeFormat.format "terminal_order_typed_failure_ready|failure_ref=%u|terminal_ref=%u|fill_ref=%u|constitution=%u|commit=%u|done=%u|run_end=%u|physical_exit=%u|exit_code=%d|authorization=%s" [| box receipt.failureRef; box receipt.terminalRef; box receipt.fillRef; box receipt.constitutionRef; box receipt.commitReceiptId; box receipt.doneReceiptId; box receipt.runEndReceiptId; box receipt.physicalExitReceiptId; box receipt.exitCode; box (terminalFlowReducerProcessExitAuthorizationText receipt.processExitAuthorization) |]
            | TerminalFlowTerminalOrderRejected(blocker, blockerRef) -> sprintf "terminal_order_rejected|blocker=%s|blocker_ref=%u" blocker blockerRef

        let private terminalFlowTerminalOrderPathAdmissionRef = function
            | TerminalFlowTerminalOrderBuildOkAdmissionPath(admissionRef, _, _) -> Some admissionRef
            | TerminalFlowTerminalOrderFailClosedPath _ -> None

        let private terminalFlowTerminalOrderCutoverAdmissionRef = function
            | TerminalFlowTerminalOrderPrerequisitesSealed receipt -> terminalFlowTerminalOrderPathAdmissionRef receipt.prerequisites.terminalPath
            | TerminalFlowTerminalOrderCommitReady receipt -> terminalFlowTerminalOrderPathAdmissionRef receipt.committedOrder.prerequisites.terminalPath
            | TerminalFlowTerminalOrderDoneReady receipt -> terminalFlowTerminalOrderPathAdmissionRef receipt.commit.committedOrder.prerequisites.terminalPath
            | TerminalFlowTerminalOrderRunEndReady receipt -> terminalFlowTerminalOrderPathAdmissionRef receipt.doneReceipt.commit.committedOrder.prerequisites.terminalPath
            | TerminalFlowTerminalOrderPhysicalExitReady receipt -> terminalFlowTerminalOrderPathAdmissionRef receipt.runEnd.doneReceipt.commit.committedOrder.prerequisites.terminalPath
            | TerminalFlowTerminalOrderAwaitFinalOutcome _
            | TerminalFlowTerminalOrderTypedFailureReady _
            | TerminalFlowTerminalOrderRejected _ -> None

        let private terminalFlowTypedFailureOrderCutover failureRef terminalRef fillRef requestId exitCode : TerminalFlowTerminalOrderCutover<'OwnerKind> =
            let identity = FastRuntimeFormat.format "typed-failure|failure=%u|terminal=%u|fill=%u|request=%s|exit=%d" [| box failureRef; box terminalRef; box fillRef; box requestId; box exitCode |]
            let commitReceiptId = terminalFlowMintedRefOf "typed_failure_commit_receipt" identity
            let doneReceiptId = terminalFlowMintedRefOf "typed_failure_done_receipt" (identity + "|commit=" + string commitReceiptId)
            let runEndReceiptId = terminalFlowMintedRefOf "typed_failure_run_end_receipt" (identity + "|done=" + string doneReceiptId)
            let physicalExitReceiptId = terminalFlowMintedRefOf "typed_failure_physical_exit_receipt" (identity + "|run_end=" + string runEndReceiptId)
            let exactOnceRef = terminalFlowMintedRefOf "typed_failure_total_order_exact_once" identity
            let constitutionRef = terminalFlowMintedRefOf "typed_failure_terminal_constitution" (identity + "|exact_once=" + string exactOnceRef)
            let processExitAuthorization =
                if constitutionRef <> 0u
                   && commitReceiptId <> 0u
                   && doneReceiptId <> 0u
                   && runEndReceiptId <> 0u
                   && physicalExitReceiptId <> 0u
                   && exactOnceRef <> 0u then
                    TerminalFlowReducerProcessExitRatified
                else
                    TerminalFlowReducerProcessExitRejected(CompilerKernelV2.OperationalReasonIdOps.create "typed_failure_total_order_incomplete")
            TerminalFlowTerminalOrderTypedFailureReady {
                failureRef = failureRef
                terminalRef = terminalRef
                fillRef = fillRef
                commitReceiptId = commitReceiptId
                doneReceiptId = doneReceiptId
                runEndReceiptId = runEndReceiptId
                physicalExitReceiptId = physicalExitReceiptId
                exactOnceRef = exactOnceRef
                constitutionRef = constitutionRef
                exitCode = exitCode
                processExitAuthorization = processExitAuthorization
                selectedAtMs = Environment.TickCount64
            }

        // Projection identity is typed separately from human rendering; revision,
        // seq, wall-clock ETA and memory counters are intentionally absent from the
        // change key so sparse policies cannot be defeated by self-mutating fields.
        type TerminalFlowProjectionChangeKind =
            | TerminalFlowProjectionQapDrain
            | TerminalFlowProjectionRelationLedger
            | TerminalFlowProjectionOutcomeMaturity
            | TerminalFlowProjectionTerminalOrder
            | TerminalFlowProjectionOwnerLedger
            | TerminalFlowProjectionWorkDagTail
            | TerminalFlowProjectionShutdown
            | TerminalFlowProjectionCicKernel
            | TerminalFlowProjectionProgressCost
            | TerminalFlowProjectionViolationSet

        [<Struct>]
        type TerminalFlowProjectionChangeKey = private {
            projectionKind : TerminalFlowProjectionChangeKind
            semanticDigestRef : uint32
            proceduralDigestRef : uint32
            materialEpoch : int64
            actorPhaseRef : uint32
            qapResolutionRef : uint32
            ownerCertificateRef : uint32
            workDagTailRef : uint32
            terminalOrderRef : uint32
            violationSetRef : uint32
        }

        type TerminalFlowProjectionCoalescingDirective = private {
            changeKey : TerminalFlowProjectionChangeKey
            repeatFirst : int64
            repeatLast : int64
            repeatCount : int64
            emitFullPayload : bool
            compactPayloadRef : uint32
            droppedSelfMutatingFields : string list
        }

        let private terminalFlowProjectionChangeKindText = function
            | TerminalFlowProjectionQapDrain -> "qap_drain"
            | TerminalFlowProjectionRelationLedger -> "relation_ledger"
            | TerminalFlowProjectionOutcomeMaturity -> "outcome_maturity"
            | TerminalFlowProjectionTerminalOrder -> "terminal_order"
            | TerminalFlowProjectionOwnerLedger -> "owner_ledger"
            | TerminalFlowProjectionWorkDagTail -> "workdag_tail"
            | TerminalFlowProjectionShutdown -> "shutdown"
            | TerminalFlowProjectionCicKernel -> "cic_kernel"
            | TerminalFlowProjectionProgressCost -> "progress_cost"
            | TerminalFlowProjectionViolationSet -> "violation_set"

        let private terminalFlowProjectionChangeKeyText key =
            FastRuntimeFormat.format "kind=%s|semantic=%u|procedural=%u|epoch=%d|actor=%u|qap=%u|owner=%u|tail=%u|terminal=%u|violations=%u" [| box (terminalFlowProjectionChangeKindText key.projectionKind); box key.semanticDigestRef; box key.proceduralDigestRef; box key.materialEpoch; box key.actorPhaseRef; box key.qapResolutionRef; box key.ownerCertificateRef; box key.workDagTailRef; box key.terminalOrderRef; box key.violationSetRef |]

        let private terminalFlowProjectionCoalescingText directive =
            FastRuntimeFormat.format "change_key=(%s)|repeat_first=%d|repeat_last=%d|repeat_count=%d|compact_ref=%u|full_payload=%b|dropped=%s" [| box (terminalFlowProjectionChangeKeyText directive.changeKey); box directive.repeatFirst; box directive.repeatLast; box directive.repeatCount; box directive.compactPayloadRef; box directive.emitFullPayload; box (directive.droppedSelfMutatingFields |> String.concat ",") |]

        let private terminalFlowProjectionChangeKey projectionKind semanticDigestRef proceduralDigestRef materialEpoch actorPhaseRef qapResolutionRef ownerCertificateRef workDagTailRef terminalOrderRef violationSetRef =
            {
                projectionKind = projectionKind
                semanticDigestRef = semanticDigestRef
                proceduralDigestRef = proceduralDigestRef
                materialEpoch = materialEpoch
                actorPhaseRef = actorPhaseRef
                qapResolutionRef = qapResolutionRef
                ownerCertificateRef = ownerCertificateRef
                workDagTailRef = workDagTailRef
                terminalOrderRef = terminalOrderRef
                violationSetRef = violationSetRef
            }

        [<Struct>]
        type TerminalFlowProgressCostRef<'Kind> = private | TerminalFlowProgressCostRef of uint64

        type TerminalFlowWorkCostUnitKind =
            | TerminalFlowWorkCostParse
            | TerminalFlowWorkCostDeclarationElaboration
            | TerminalFlowWorkCostTypeInference
            | TerminalFlowWorkCostPartialEvaluation
            | TerminalFlowWorkCostJoinPointResolution
            | TerminalFlowWorkCostQapRelation
            | TerminalFlowWorkCostCicWhnf
            | TerminalFlowWorkCostCicDefEq
            | TerminalFlowWorkCostBackendLowering
            | TerminalFlowWorkCostArtifactWrite
            | TerminalFlowWorkCostTerminalFinalization

        type TerminalFlowWorkCostSnapshot<'Kind> = private {
            costRef : TerminalFlowProgressCostRef<'Kind>
            workKind : TerminalFlowWorkCostUnitKind
            retiredDuration : CompilerKernelV2.WallTime
            knownRemainingDuration : CompilerKernelV2.WallTime
            undiscoveredP50 : CompilerKernelV2.WallTime
            undiscoveredP90 : CompilerKernelV2.WallTime
            criticalPathP50 : CompilerKernelV2.WallTime
            criticalPathP90 : CompilerKernelV2.WallTime
            effectiveParallelism : CompilerKernelV2.ParallelismPermille
            materialEpoch : int64
            terminalDispositionRef : uint32
        }

        type TerminalFlowCriticalPathEta<'Kind> = private {
            etaRef : uint32
            terminalP50 : CompilerKernelV2.WallTime
            terminalP90 : CompilerKernelV2.WallTime
            buildOkP50 : CompilerKernelV2.WallTime option
            buildOkP90 : CompilerKernelV2.WallTime option
            unavailableReason : CompilerKernelV2.OperationalReasonId option
            retiredDuration : CompilerKernelV2.WallTime
            remainingDuration : CompilerKernelV2.WallTime
            criticalPathP50 : CompilerKernelV2.WallTime
            criticalPathP90 : CompilerKernelV2.WallTime
            computedFromRef : TerminalFlowProgressCostRef<'Kind>
        }

        // MIGRATION / destructive migration 5 of 5: HUD and JSONL consume one
        // reducer-owned progress value. ETA freshness, denominator revisions,
        // QAP generation and terminal seal are carried in the snapshot rather
        // than reconstructed independently by polling projections.
        type TerminalFlowProgressSnapshotFreshnessId =
            | TerminalFlowProgressSnapshotFresh
            | TerminalFlowProgressSnapshotStale
            | TerminalFlowProgressSnapshotFinal

        type TerminalFlowBuildOkEtaAvailabilityId =
            | TerminalFlowBuildOkEtaAvailable of p50:CompilerKernelV2.WallTime * p90:CompilerKernelV2.WallTime
            | TerminalFlowBuildOkEtaUnavailable of blockerRef:uint32 * reason:CompilerKernelV2.OperationalReasonId

        type TerminalFlowProgressNumeratorSourceId =
            | TerminalFlowProgressNumeratorWorkLedgerCompleted
            | TerminalFlowProgressNumeratorSemanticRetiredCost
            | TerminalFlowProgressNumeratorCicWeightedRetiredCost
            | TerminalFlowProgressNumeratorConservedCompletedMax

        let private terminalFlowProgressNumeratorSourceText = function
            | TerminalFlowProgressNumeratorWorkLedgerCompleted -> "WorkLedgerCompleted"
            | TerminalFlowProgressNumeratorSemanticRetiredCost -> "SemanticRetiredCost(RootValuePlusWorkUnitReceipt)"
            | TerminalFlowProgressNumeratorCicWeightedRetiredCost -> "CicWeightedRetiredCost"
            | TerminalFlowProgressNumeratorConservedCompletedMax -> "ConservedCompleted(MaxWorkLedgerSemanticCic)"

        type TerminalFlowAuthoritativeProgressSnapshot = private {
            snapshotRef : uint32
            sourceProgressSnapshotRef : uint32
            reducerSequence : int64
            denominatorRevision : int64
            denominatorCost : CompilerKernelV2.SemanticCost
            semanticEpoch : int64
            observedAt : CompilerKernelV2.MonotonicTimestamp
            validUntil : CompilerKernelV2.MonotonicTimestamp
            freshnessAtCommit : TerminalFlowProgressSnapshotFreshnessId
            bpNumeratorSource : TerminalFlowProgressNumeratorSourceId
            progressLowBp : CompilerKernelV2.BasisPoints
            progressMidBp : CompilerKernelV2.BasisPoints
            progressHighBp : CompilerKernelV2.BasisPoints
            semanticProgressBp : CompilerKernelV2.BasisPoints
            terminalSpineProgressBp : CompilerKernelV2.BasisPoints
            terminalEtaP50 : CompilerKernelV2.WallTime option
            terminalEtaP90 : CompilerKernelV2.WallTime option
            criticalPath : CompilerKernelV2.WorkCriticalPathSnapshot
            buildOkEta : TerminalFlowBuildOkEtaAvailabilityId
            semanticFactCount : CompilerKernelV2.NodeCount
            semanticRootValueFactCount : CompilerKernelV2.NodeCount
            semanticWorkUnitReceiptFactCount : CompilerKernelV2.NodeCount
            semanticRetiredCost : CompilerKernelV2.SemanticCost
            semanticCriticalPathRetiredCost : CompilerKernelV2.CriticalPathCost
            cicWeightedRetiredCost : CompilerKernelV2.SemanticCost
            duplicateSemanticFactCount : CompilerKernelV2.NodeCount
            qapGenerationRef : uint32
            terminalSealRef : uint32
            totalOrderIndex : int64
        }

        let private terminalFlowBuildOkEtaAvailabilityText = function
            | TerminalFlowBuildOkEtaAvailable(p50, p90) ->
                sprintf "available:p50_ms=%d:p90_ms=%d" (CompilerKernelV2.Measured.value p50) (CompilerKernelV2.Measured.value p90)
            | TerminalFlowBuildOkEtaUnavailable(blockerRef, reason) ->
                sprintf "unavailable:blocker_ref=%u:reason=%s" blockerRef (CompilerKernelV2.OperationalReasonIdOps.text reason)

        let private terminalFlowAuthoritativeProgressFreshnessAt nowMs (snapshot:TerminalFlowAuthoritativeProgressSnapshot) =
            match snapshot.freshnessAtCommit with
            | TerminalFlowProgressSnapshotFinal -> TerminalFlowProgressSnapshotFinal
            | _ when nowMs > CompilerKernelV2.Measured.value snapshot.validUntil -> TerminalFlowProgressSnapshotStale
            | _ -> TerminalFlowProgressSnapshotFresh

        let private terminalFlowProgressSnapshotFreshnessText = function
            | TerminalFlowProgressSnapshotFresh -> "fresh"
            | TerminalFlowProgressSnapshotStale -> "stale"
            | TerminalFlowProgressSnapshotFinal -> "final"

        let private terminalFlowOptionalWallTimeText = function
            | Some value -> value |> CompilerKernelV2.Measured.value |> string
            | None -> "none"

        let private terminalFlowAuthoritativeProgressSnapshotText nowMs (snapshot:TerminalFlowAuthoritativeProgressSnapshot) =
            FastRuntimeFormat.format "snapshot_ref=%u|source_ref=%u|sequence=%d|denominator_revision=%d|denominator_cost=%d|semantic_epoch=%d|observed_at_ms=%d|valid_until_ms=%d|freshness=%s|bp_numerator=%s|low_bp=%d|mid_bp=%d|high_bp=%d|semantic_progress_bp=%d|terminal_spine_progress_bp=%d|terminal_p50_ms=%s|terminal_p90_ms=%s|build_ok=%s|semantic_facts=%d|semantic_root_values=%d|semantic_work_unit_receipts=%d|semantic_retired=%d|semantic_critical_path_retired=%d|cic_weighted_retired=%d|semantic_fact_duplicates=%d|qap_generation_ref=%u|terminal_seal_ref=%u|total_order_index=%d" [|
                box snapshot.snapshotRef
                box snapshot.sourceProgressSnapshotRef
                box snapshot.reducerSequence
                box snapshot.denominatorRevision
                box (CompilerKernelV2.Measured.value snapshot.denominatorCost)
                box snapshot.semanticEpoch
                box (CompilerKernelV2.Measured.value snapshot.observedAt)
                box (CompilerKernelV2.Measured.value snapshot.validUntil)
                box (terminalFlowAuthoritativeProgressFreshnessAt nowMs snapshot |> terminalFlowProgressSnapshotFreshnessText)
                box (terminalFlowProgressNumeratorSourceText snapshot.bpNumeratorSource)
                box (CompilerKernelV2.BasisPoints.value snapshot.progressLowBp)
                box (CompilerKernelV2.BasisPoints.value snapshot.progressMidBp)
                box (CompilerKernelV2.BasisPoints.value snapshot.progressHighBp)
                box (CompilerKernelV2.BasisPoints.value snapshot.semanticProgressBp)
                box (CompilerKernelV2.BasisPoints.value snapshot.terminalSpineProgressBp)
                box (terminalFlowOptionalWallTimeText snapshot.terminalEtaP50)
                box (terminalFlowOptionalWallTimeText snapshot.terminalEtaP90)
                box (terminalFlowBuildOkEtaAvailabilityText snapshot.buildOkEta)
                box (CompilerKernelV2.Measured.value snapshot.semanticFactCount)
                box (CompilerKernelV2.Measured.value snapshot.semanticRootValueFactCount)
                box (CompilerKernelV2.Measured.value snapshot.semanticWorkUnitReceiptFactCount)
                box (CompilerKernelV2.Measured.value snapshot.semanticRetiredCost)
                box (CompilerKernelV2.Measured.value snapshot.semanticCriticalPathRetiredCost)
                box (CompilerKernelV2.Measured.value snapshot.cicWeightedRetiredCost)
                box (CompilerKernelV2.Measured.value snapshot.duplicateSemanticFactCount)
                box snapshot.qapGenerationRef
                box snapshot.terminalSealRef
                box snapshot.totalOrderIndex |]

        let private terminalFlowWorkCostKindText = function
            | TerminalFlowWorkCostParse -> "parse"
            | TerminalFlowWorkCostDeclarationElaboration -> "declaration_elaboration"
            | TerminalFlowWorkCostTypeInference -> "type_inference"
            | TerminalFlowWorkCostPartialEvaluation -> "partial_evaluation"
            | TerminalFlowWorkCostJoinPointResolution -> "join_point_resolution"
            | TerminalFlowWorkCostQapRelation -> "qap_relation"
            | TerminalFlowWorkCostCicWhnf -> "cic_whnf"
            | TerminalFlowWorkCostCicDefEq -> "cic_defeq"
            | TerminalFlowWorkCostBackendLowering -> "backend_lowering"
            | TerminalFlowWorkCostArtifactWrite -> "artifact_write"
            | TerminalFlowWorkCostTerminalFinalization -> "terminal_finalization"

        let private terminalFlowCriticalPathEtaText eta =
            let buildOk =
                match eta.buildOkP50, eta.buildOkP90, eta.unavailableReason with
                | Some p50, Some p90, _ ->
                    sprintf "build_ok_p50_ms=%d|build_ok_p90_ms=%d"
                        (CompilerKernelV2.Measured.value p50)
                        (CompilerKernelV2.Measured.value p90)
                | _, _, Some reason ->
                    "build_ok_unavailable=" + CompilerKernelV2.OperationalReasonIdOps.text reason
                | _ -> "build_ok_unavailable=unknown"
            FastRuntimeFormat.format "eta_ref=%u|terminal_p50_ms=%d|terminal_p90_ms=%d|%s|retired_ms=%d|remaining_ms=%d|critical_p50_ms=%d|critical_p90_ms=%d" [|
                box eta.etaRef
                box (CompilerKernelV2.Measured.value eta.terminalP50)
                box (CompilerKernelV2.Measured.value eta.terminalP90)
                box buildOk
                box (CompilerKernelV2.Measured.value eta.retiredDuration)
                box (CompilerKernelV2.Measured.value eta.remainingDuration)
                box (CompilerKernelV2.Measured.value eta.criticalPathP50)
                box (CompilerKernelV2.Measured.value eta.criticalPathP90) |]

        let private terminalFlowCriticalPathEtaFromCost (snapshot:TerminalFlowWorkCostSnapshot<'Kind>) terminalFailureLikely =
            let parallelism = max 1L (CompilerKernelV2.Measured.value snapshot.effectiveParallelism)
            let scaledKnown =
                CompilerKernelV2.Measured.create<CompilerKernelV2.WallTimeUnit>
                    "criticalPathScaledKnown"
                    (CompilerKernelV2.Measured.value snapshot.knownRemainingDuration * 1000L / parallelism)
            let terminalP50 =
                CompilerKernelV2.Measured.maxValue snapshot.criticalPathP50
                    (CompilerKernelV2.Measured.add scaledKnown snapshot.undiscoveredP50)
            let terminalP90 =
                CompilerKernelV2.Measured.maxValue snapshot.criticalPathP90
                    (CompilerKernelV2.Measured.add scaledKnown snapshot.undiscoveredP90)
            let remainingDuration =
                CompilerKernelV2.Measured.add snapshot.knownRemainingDuration snapshot.undiscoveredP50
            {
                etaRef =
                    terminalFlowMintedRefOf "critical_path_eta_ref"
                        (FastRuntimeFormat.format "%d:%d:%d:%d" [|
                            box (CompilerKernelV2.Measured.value snapshot.retiredDuration)
                            box (CompilerKernelV2.Measured.value snapshot.knownRemainingDuration)
                            box (CompilerKernelV2.Measured.value snapshot.criticalPathP50)
                            box snapshot.materialEpoch |])
                terminalP50 = terminalP50
                terminalP90 = terminalP90
                buildOkP50 = if terminalFailureLikely then None else Some terminalP50
                buildOkP90 = if terminalFailureLikely then None else Some terminalP90
                unavailableReason =
                    if terminalFailureLikely then
                        Some (CompilerKernelV2.OperationalReasonIdOps.create "unavailable_current_terminal_failure")
                    else None
                retiredDuration = snapshot.retiredDuration
                remainingDuration = remainingDuration
                criticalPathP50 = snapshot.criticalPathP50
                criticalPathP90 = snapshot.criticalPathP90
                computedFromRef = snapshot.costRef
            }

        type TerminalFlowTerminalOrderMinterInput<'OwnerKind> = private {
            finalOutcome : TerminalFlowOutcomeMaturityToken<TerminalFlowOutcomeFinalStage>
            ownerCertificate : TerminalFlowOwnerLedgerCloseCertificate<'OwnerKind>
            workDagTailProof : TerminalFlowWorkDagTailCloseProof<'OwnerKind>
            terminalPath : TerminalFlowTerminalOrderPath
            fillOnceRef : uint32
            dispatchRequestRef : uint32
            actorStageTokenRef : uint32
            constitutionRef : uint32
            predecessorOrderRef : uint32
            exactOnceRef : uint32
            totalOrderIndex : int64
            reducerSequence : int64
        }

        type TerminalFlowTerminalOrderMinterReceipt<'OwnerKind> = private {
            minterInput : TerminalFlowTerminalOrderMinterInput<'OwnerKind>
            prerequisites : TerminalFlowFinalOutcomePrerequisites<'OwnerKind>
            cutover : TerminalFlowTerminalOrderCutover<'OwnerKind>
            qapResolutionRef : uint32
            ownerCertificateRef : uint32
            workDagTailRef : uint32
            receiptRef : uint32
        }

        let private terminalFlowMintTerminalOrderCutover (input:TerminalFlowTerminalOrderMinterInput<'OwnerKind>) : TerminalFlowTerminalOrderMinterReceipt<'OwnerKind> =
            let prerequisites = {
                finalOutcome = input.finalOutcome
                ownerCertificate = input.ownerCertificate
                workDagTailProof = input.workDagTailProof
                qapResolution = input.ownerCertificate.qapResolution
                terminalPath = input.terminalPath
                fillOnceRef = input.fillOnceRef
                dispatchRequestRef = input.dispatchRequestRef
                actorStageTokenRef = input.actorStageTokenRef
                constitutionRef = input.constitutionRef
                predecessorOrderRef = input.predecessorOrderRef
                exactOnceRef = input.exactOnceRef
            }
            let orderId = TerminalFlowTerminalOrderId(uint64 input.totalOrderIndex)
            let receiptText =
                FastRuntimeFormat.format "final=%s|constitution=%u|qap=%u|owner=%u|tail=%u|path=%s|fill=%u|dispatch=%u|actor=%u|predecessor=%u|exact_once=%u" [| box (terminalFlowPendingIntentMaturityLabel input.finalOutcome.intent); box input.constitutionRef; box (terminalFlowQapResolutionBoxRef prerequisites.qapResolution); box input.ownerCertificate.certificateRef; box (terminalFlowWorkDagTailRef input.workDagTailProof.workDagTail); box (terminalFlowTerminalOrderPathText input.terminalPath); box input.fillOnceRef; box input.dispatchRequestRef; box input.actorStageTokenRef; box input.predecessorOrderRef; box input.exactOnceRef |]
            let receiptRef = terminalFlowMintedRefOf "terminal_order_prerequisites_receipt" receiptText
            let receipt = {
                orderId = orderId
                prerequisites = prerequisites
                totalOrderIndex = input.totalOrderIndex
                receiptRef = receiptRef
                reducerSequence = input.reducerSequence
            }
            {
                minterInput = input
                prerequisites = prerequisites
                cutover = TerminalFlowTerminalOrderPrerequisitesSealed receipt
                qapResolutionRef = terminalFlowQapResolutionBoxRef prerequisites.qapResolution
                ownerCertificateRef = input.ownerCertificate.certificateRef
                workDagTailRef = terminalFlowWorkDagTailRef input.workDagTailProof.workDagTail
                receiptRef = receiptRef
            }

        let private terminalFlowTerminalOrderMinterReceiptText receipt =
            FastRuntimeFormat.format "terminal_order_minted|receipt_ref=%u|qap=%u|owner=%u|tail=%u|cutover=%s" [| box receipt.receiptRef; box receipt.qapResolutionRef; box receipt.ownerCertificateRef; box receipt.workDagTailRef; box (terminalFlowTerminalOrderCutoverText receipt.cutover) |]

