        type TerminalFlowLegacyTerminalAuthorityDemotion =
            | TerminalFlowLegacyRecoveryDemotedBehindFinalOutcome of recoveryRef:uint32
            | TerminalFlowLegacyObserverShutdownDemotedBehindRunEnd of shutdownRef:uint32
            | TerminalFlowLegacyHudProgressDemotedBehindReceipts of projectionRef:uint32
            | TerminalFlowLegacyDirectExitDemotedBehindPhysicalExitSelection of exitWitnessRef:uint32

        let private terminalFlowLegacyTerminalAuthorityDemotionText = function
            | TerminalFlowLegacyRecoveryDemotedBehindFinalOutcome recoveryRef -> sprintf "legacy_recovery_demoted_behind_final_outcome|recovery_ref=%u" recoveryRef
            | TerminalFlowLegacyObserverShutdownDemotedBehindRunEnd shutdownRef -> sprintf "legacy_observer_shutdown_demoted_behind_run_end|shutdown_ref=%u" shutdownRef
            | TerminalFlowLegacyHudProgressDemotedBehindReceipts projectionRef -> sprintf "legacy_hud_progress_demoted_behind_receipts|projection_ref=%u" projectionRef
