        type TerminalFlowOwnerLedgerReducerDecision<'OwnerKind> =
            | TerminalFlowOwnerLedgerRecordMaterial of TerminalFlowOwnerLedger<'OwnerKind,TerminalFlowOwnerLedgerOpenStage> * materialReceiptRef:uint32
            | TerminalFlowOwnerLedgerForceClose of TerminalFlowOwnerLedger<'OwnerKind,TerminalFlowOwnerLedgerClosingStage> * TerminalFlowWorkDagTailCloseProof<'OwnerKind>
            | TerminalFlowOwnerLedgerSealClosed of TerminalFlowOwnerLedgerCloseCertificate<'OwnerKind>
            | TerminalFlowOwnerLedgerQuarantine of reason:TerminalFlowOwnerLedgerQuarantineReason * relationRef:uint32 option

        let private terminalFlowOptionalRefText = function
            | None -> "none"
            | Some reference -> string reference

        let private terminalFlowOwnerLedgerReducerDecisionText = function
            | TerminalFlowOwnerLedgerRecordMaterial(_, materialReceiptRef) -> sprintf "owner_ledger_record_material|material_receipt_ref=%u" materialReceiptRef
            | TerminalFlowOwnerLedgerForceClose(_, proof) -> FastRuntimeFormat.format "owner_ledger_force_close|tail_ref=%u|open=%d|acyclic=%b" [| box (terminalFlowWorkDagTailRef proof.workDagTail); box proof.openOwnerCount; box proof.acyclicByConstruction |]
            | TerminalFlowOwnerLedgerSealClosed certificate -> sprintf "owner_ledger_seal_closed|certificate_ref=%u|receipts=%d" certificate.certificateRef certificate.closeReceipts.Length
            | TerminalFlowOwnerLedgerQuarantine(reason, relationRef) -> sprintf "owner_ledger_quarantine|reason=%s|relation_ref=%s" (terminalFlowOwnerLedgerQuarantineReasonText reason) (terminalFlowOptionalRefText relationRef)

        type TerminalFlowOwnerLedgerSeal<'Stage> = private {
            ledgerSealRef : uint32
            closedOwnerCount : int
            openOwnerCount : int
            workDagTailRef : uint32
            closeReceiptRef : uint32
            witnessReason : TerminalFlowWorkDagTailClosureReason
        }

        type TerminalFlowQueueOnlyRecoveryDecision =
            | TerminalFlowQueueOnlyRecoveryObserve of blockerRef:uint32
            | TerminalFlowQueueOnlyRecoveryDefer of blockerRef:uint32 * ageMs:int64
            | TerminalFlowQueueOnlyRecoveryReady of closeReceiptRef:uint32 * recoveryRef:uint32
            | TerminalFlowQueueOnlyRecoveryRejectTopology of reasonRef:uint32

        let private terminalFlowQueueOnlyRecoveryDecisionText = function
            | TerminalFlowQueueOnlyRecoveryObserve blockerRef -> sprintf "Observe(blocker_ref=%u)" blockerRef
            | TerminalFlowQueueOnlyRecoveryDefer(blockerRef, ageMs) -> sprintf "Defer(blocker_ref=%u|age_ms=%d)" blockerRef ageMs
            | TerminalFlowQueueOnlyRecoveryReady(closeReceiptRef, recoveryRef) -> sprintf "Ready(close_receipt_ref=%u|recovery_ref=%u)" closeReceiptRef recoveryRef
            | TerminalFlowQueueOnlyRecoveryRejectTopology reasonRef -> sprintf "RejectTopology(reason_ref=%u)" reasonRef

        type TerminalFlowRootResolvedByWorkDagCloseStage = class end

        type TerminalFlowWorkDagRootCapability<'Stage> = private {
            capabilityRef : uint32
            rootReceiptRef : uint32
            workDagCloseReceiptRef : uint32
            queueRecoveryRef : uint32
            ownerLedgerSealRef : uint32
            mintedAtMs : int64
        }

        type TerminalFlowWorkDagTailClosure<'Stage> = private {
            ownerRef : uint32
            closeReceiptRef : uint32
            closureReason : TerminalFlowWorkDagTailClosureReason
            ledgerSealRef : uint32
            wakerEdgeRef : uint32
            remainingObligationCount : int
            drainPassCount : int
            zeroDeltaStreak : int
            queueOnlyRecovery : TerminalFlowQueueOnlyRecoveryDecision
            closedAtMs : int64
        }

        // MIGRATION / five-round domain migration, migration phase:
        // owner-ledger and WorkDag values are now produced by one reducer-owned
        // transaction.  The recursive protocol is no longer an unused model next
        // to legacy counters: a fully-drained QAP event constructs the open owner,
        // advances its tail, mints its close receipt, derives queue recovery and
        // yields the only root capability admitted by the success corridor.
        type TerminalFlowOwnerWorkDagProducer =
            | TerminalFlowOwnerWorkDagProducerOpen of
                ledger:TerminalFlowOwnerLedger<ProceduralResidualOwnerKind,TerminalFlowOwnerLedgerOpenStage> *
                tail:TerminalFlowWorkDagTail<TerminalFlowRequirementOpenStage> *
                rootReceiptRef:uint32 *
                qapFixpointRef:uint32
            | TerminalFlowOwnerWorkDagProducerDraining of
                ledger:TerminalFlowOwnerLedger<ProceduralResidualOwnerKind,TerminalFlowOwnerLedgerOpenStage> *
                tail:TerminalFlowWorkDagTail<TerminalFlowRequirementOpenStage> *
                rootReceiptRef:uint32 *
                qapFixpointRef:uint32
            | TerminalFlowOwnerWorkDagProducerSealed of
                certificate:TerminalFlowOwnerLedgerCloseCertificate<ProceduralResidualOwnerKind> *
                proof:TerminalFlowWorkDagTailCloseProof<ProceduralResidualOwnerKind> *
                rootCapability:TerminalFlowWorkDagRootCapability<TerminalFlowRootResolvedByWorkDagCloseStage> *
                queueRecovery:TerminalFlowQueueOnlyRecoveryDecision
            | TerminalFlowOwnerWorkDagProducerQuarantined of
                ledgerRef:uint32 * tailRef:uint32 * requirementRef:uint32 * satisfierRef:uint32 * reasonRef:uint32

        let private terminalFlowOwnerWorkDagProducerText = function
            | TerminalFlowOwnerWorkDagProducerOpen(_, tail, rootReceiptRef, qapFixpointRef) ->
                FastRuntimeFormat.format "OwnerWorkDag(Open|tail_ref=%u|root_ref=%u|qap_ref=%u)" [| box (terminalFlowWorkDagTailRef tail); box rootReceiptRef; box qapFixpointRef |]
            | TerminalFlowOwnerWorkDagProducerDraining(_, tail, rootReceiptRef, qapFixpointRef) ->
                FastRuntimeFormat.format "OwnerWorkDag(Draining|tail=%s|root_ref=%u|qap_ref=%u)" [| box (terminalFlowWorkDagTailStateText tail); box rootReceiptRef; box qapFixpointRef |]
            | TerminalFlowOwnerWorkDagProducerSealed(certificate, proof, rootCapability, recovery) ->
                FastRuntimeFormat.format "OwnerWorkDag(Sealed|certificate_ref=%u|tail_ref=%u|root_capability_ref=%u|recovery=%s)" [| box certificate.certificateRef; box (terminalFlowWorkDagTailRef proof.workDagTail); box rootCapability.capabilityRef; box (terminalFlowQueueOnlyRecoveryDecisionText recovery) |]
            | TerminalFlowOwnerWorkDagProducerQuarantined(ledgerRef, tailRef, requirementRef, satisfierRef, reasonRef) ->
                FastRuntimeFormat.format "OwnerWorkDag(Quarantined|ledger_ref=%u|tail_ref=%u|requirement_ref=%u|satisfier_ref=%u|reason_ref=%u)" [| box ledgerRef; box tailRef; box requirementRef; box satisfierRef; box reasonRef |]

        let private terminalFlowOwnerWorkDagOpenForQap
            reducerSequence
            rootReceiptRef
            qapFixpointRef
            materialEpoch
            queueDepth
            blockedDepth
            activeWorkers
            =
            let ledgerRefValue = terminalFlowMintedRefOf "owner_workdag_ledger_ref" (sprintf "%u:%d" qapFixpointRef reducerSequence)
            let tailRef = terminalFlowMintedRefOf "owner_workdag_tail_ref" (sprintf "%u:%u" qapFixpointRef rootReceiptRef)
            let ownerRef = terminalFlowMintedRefOf "owner_workdag_owner_ref" (sprintf "%u:%u" ledgerRefValue tailRef)
            let closeKeyRefValue = terminalFlowMintedRefOf "owner_workdag_close_key_ref" (FastRuntimeFormat.format "%u:%u:%d" [| box ownerRef; box qapFixpointRef; box materialEpoch |])
            let requirementRef = terminalFlowMintedRefOf "owner_workdag_requirement_ref" (sprintf "%u:%u" tailRef closeKeyRefValue)
            let satisfierRef = terminalFlowMintedRefOf "owner_workdag_satisfier_ref" (sprintf "%u:%u" requirementRef closeKeyRefValue)
            let minterRef = terminalFlowMintedRefOf "owner_workdag_close_minter_ref" (sprintf "%u:%d" tailRef reducerSequence)
            let exactOnceRef = terminalFlowMintedRefOf "owner_workdag_close_exact_once_ref" (sprintf "%u:%u" requirementRef minterRef)
            let satisfier : TerminalFlowRequirementSatisfier<TerminalFlowWorkDagTailRequirementKind> = {
                route = TerminalFlowSatisfierFromReducerCloseReceipt
                routeRef = closeKeyRefValue
                minterRef = minterRef
                exactOnceRef = exactOnceRef
            }
            let requirement = TerminalFlowRequirementOpen(requirementRef, Environment.TickCount64, satisfier)
            let ledgerRef = TerminalFlowOwnerLedgerProtocolId(uint64 ledgerRefValue)
            let closeKey : TerminalFlowOwnerLedgerCloseKey<ProceduralResidualOwnerKind> = {
                closeKeyRef = TerminalFlowOwnerLedgerProtocolId(uint64 closeKeyRefValue)
                ownerKind = TerminalFlowPhantomOwnerProceduralResidual
                ownerRef = ownerRef
                materialEpoch = materialEpoch
                qapFixpointRef = qapFixpointRef
            }
            let entry : TerminalFlowOwnerLedgerEntry<ProceduralResidualOwnerKind,TerminalFlowOwnerLedgerOpenStage> = {
                closeKey = closeKey
                obligationRef = requirementRef
                ownerKind = TerminalFlowPhantomOwnerProceduralResidual
                materialDelta = int64 queueDepth + int64 blockedDepth + int64 activeWorkers
                wakerRef = Some exactOnceRef
                relationRef = Some qapFixpointRef
            }
            let ledger = TerminalFlowOwnerLedgerCons(entry, TerminalFlowOwnerLedgerEmpty ledgerRef)
            let snapshot : TerminalFlowWorkDagTailSnapshot = {
                workDagRef = TerminalFlowWorkDagProtocolId(uint64 tailRef)
                tailRef = tailRef
                ownerLedgerRef = ledgerRefValue
                openEdgeCount = max 0 (int queueDepth)
                blockedEdgeCount = max 0 (int blockedDepth)
                activeProducerCount = max 0 (int activeWorkers)
                materialEpoch = materialEpoch
                qapResolutionRef = qapFixpointRef
                drainPassCount = 0
                zeroDeltaStreak = 0
                firstObservedAtMs = Environment.TickCount64
                lastMaterialAtMs = Environment.TickCount64
            }
            TerminalFlowOwnerWorkDagProducerOpen(ledger, TerminalFlowWorkDagTailLive(snapshot, requirement), rootReceiptRef, qapFixpointRef)

        let private terminalFlowOwnerWorkDagSealFullyDrained
            reducerSequence
            qapResolution
            canonicalRecoveryRef
            producer
            =
            match producer with
            | TerminalFlowOwnerWorkDagProducerOpen(ledger, tail, rootReceiptRef, qapFixpointRef)
            | TerminalFlowOwnerWorkDagProducerDraining(ledger, tail, rootReceiptRef, qapFixpointRef) ->
                let snapshot = terminalFlowWorkDagTailSnapshot tail
                let closeReceiptRef = terminalFlowMintedRefOf "owner_workdag_close_receipt_ref" (FastRuntimeFormat.format "%u:%u:%d" [| box snapshot.tailRef; box qapFixpointRef; box reducerSequence |])
                let requirementRef, satisfier =
                    match tail with
                    | TerminalFlowWorkDagTailLive(_, TerminalFlowRequirementOpen(requirementRef, _, satisfier))
                    | TerminalFlowWorkDagTailPendingDrain(_, _, _, TerminalFlowRequirementOpen(requirementRef, _, satisfier)) -> requirementRef, satisfier
                    | _ -> invalidOp "only an open WorkDag tail can be sealed by the QAP producer"
                let satisfiedRequirement = TerminalFlowRequirementSatisfied(requirementRef, closeReceiptRef, satisfier, reducerSequence)
                let closedTail : TerminalFlowWorkDagTail<TerminalFlowWorkDagClosedByReducerStage> =
                    TerminalFlowWorkDagTailClosed({ snapshot with drainPassCount = snapshot.drainPassCount + 1; zeroDeltaStreak = snapshot.zeroDeltaStreak + 1 }, closeReceiptRef, satisfiedRequirement)
                let proof : TerminalFlowWorkDagTailCloseProof<ProceduralResidualOwnerKind> = {
                    proofRef = TerminalFlowOwnerLedgerProtocolId(uint64 (terminalFlowMintedRefOf "owner_workdag_tail_proof_ref" (sprintf "%u:%u" snapshot.tailRef closeReceiptRef)))
                    workDagTail = closedTail
                    ownerLedgerRef = snapshot.ownerLedgerRef
                    closedOwnerCount = 1
                    openOwnerCount = 0
                    acyclicByConstruction = true
                    residualQapResolutionRef = terminalFlowQapResolutionBoxRef qapResolution
                    reducerSequence = reducerSequence
                }
                let openEntry, ledgerRef =
                    match ledger with
                    | TerminalFlowOwnerLedgerCons(entry, TerminalFlowOwnerLedgerEmpty ledgerRef) -> entry, ledgerRef
                    | _ -> invalidOp "QAP owner producer expects exactly one procedural residual owner"
                let closingEntry : TerminalFlowOwnerLedgerEntry<ProceduralResidualOwnerKind,TerminalFlowOwnerLedgerClosingStage> = {
                    closeKey = openEntry.closeKey
                    obligationRef = openEntry.obligationRef
                    ownerKind = openEntry.ownerKind
                    materialDelta = 0L
                    wakerRef = openEntry.wakerRef
                    relationRef = openEntry.relationRef
                }
                let sealedEntry : TerminalFlowOwnerLedgerEntry<ProceduralResidualOwnerKind,TerminalFlowOwnerLedgerSealedStage> = {
                    closeKey = openEntry.closeKey
                    obligationRef = openEntry.obligationRef
                    ownerKind = openEntry.ownerKind
                    materialDelta = 0L
                    wakerRef = openEntry.wakerRef
                    relationRef = openEntry.relationRef
                }
                let closeReceipt : TerminalFlowOwnerLedgerCloseReceipt<ProceduralResidualOwnerKind> = {
                    receiptRef = TerminalFlowOwnerLedgerProtocolId(uint64 closeReceiptRef)
                    closeKey = openEntry.closeKey
                    closedEntry = closingEntry
                    workDagTailProof = proof
                    materialEpochBefore = snapshot.materialEpoch
                    materialEpochAfter = snapshot.materialEpoch
                    reducerSequence = reducerSequence
                }
                let certificateRef = terminalFlowMintedRefOf "owner_workdag_certificate_ref" (FastRuntimeFormat.format "%u:%u:%d" [| box snapshot.ownerLedgerRef; box closeReceiptRef; box reducerSequence |])
                let certificate : TerminalFlowOwnerLedgerCloseCertificate<ProceduralResidualOwnerKind> = {
                    certificateRef = certificateRef
                    ledger = TerminalFlowOwnerLedgerCons(sealedEntry, TerminalFlowOwnerLedgerEmpty ledgerRef)
                    workDagTailProof = proof
                    closeReceipts = [closeReceipt]
                    qapResolution = qapResolution
                    shutdownReconciliationRef = None
                }
                let recoveryRef = canonicalRecoveryRef
                if recoveryRef = 0u then
                    invalidOp "a sealed owner/workdag producer requires the canonical reducer recovery identity"
                let queueRecovery = TerminalFlowQueueOnlyRecoveryReady(closeReceiptRef, recoveryRef)
                let rootCapability : TerminalFlowWorkDagRootCapability<TerminalFlowRootResolvedByWorkDagCloseStage> = {
                    capabilityRef = terminalFlowMintedRefOf "owner_workdag_root_capability_ref" (FastRuntimeFormat.format "%u:%u:%u" [| box rootReceiptRef; box closeReceiptRef; box recoveryRef |])
                    rootReceiptRef = rootReceiptRef
                    workDagCloseReceiptRef = closeReceiptRef
                    queueRecoveryRef = recoveryRef
                    ownerLedgerSealRef = certificateRef
                    mintedAtMs = Environment.TickCount64
                }
                TerminalFlowOwnerWorkDagProducerSealed(certificate, proof, rootCapability, queueRecovery)
            | current -> current

        let private terminalFlowOwnerWorkDagProducedAuthorities = function
            | TerminalFlowOwnerWorkDagProducerSealed(certificate, proof, rootCapability, queueRecovery) ->
                Some certificate, Some proof, Some rootCapability, queueRecovery
            | producer ->
                None, None, None,
                TerminalFlowQueueOnlyRecoveryObserve(terminalFlowMintedRefOf "owner_workdag_not_sealed_blocker_ref" (terminalFlowOwnerWorkDagProducerText producer))

        type TerminalFlowActorOutcomeJoin<'Stage> = private {
            tokenId : string
            rootReceiptRef : TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            fillKey : TerminalFlowFillKeyId
            admissionIdentity : TerminalFlowAdmissionIdentity
            credentialGraph : TerminalFlowSchedulerGraphClosedReceipt
            fairnessRelease : TerminalFlowFairnessReleaseReceipt
            schedulerRelease : TerminalFlowSchedulerPhysicalReleaseReceipt
            terminalOrderAdmission : TerminalFlowSchedulerWitness<TerminalFlowSchedulerPredecessorOrderWitnessKind>
            actorPhase : DiagJson.TerminalSchedulerPushActorPhase
            workDagTailClosure : TerminalFlowWorkDagTailClosure<TerminalFlowWorkDagTailClosedStage>
            rootCapability : TerminalFlowWorkDagRootCapability<TerminalFlowRootResolvedByWorkDagCloseStage>
            wakerEdge : TerminalFlowPushOwnedWakerEdge<TerminalFlowWakerRegisteredStage>
            joinedAtMs : int64
        }
        with
            member this.terminalOrderAdmissionRef = terminalFlowSchedulerWitnessRef this.terminalOrderAdmission
            member this.credentialGraphClosureRef = this.credentialGraph.closureRef
            member this.credentialCycleProofRef = 0u

        let private terminalFlowActorOutcomeJoinAdmissionRef token = terminalFlowAdmissionRawRef token.admissionIdentity
        let private terminalFlowActorOutcomeJoinAdmissionIdentityRef token = terminalFlowAdmissionIdentityRef token.admissionIdentity
        let private terminalFlowActorOutcomeJoinActorRef token = terminalFlowAdmissionActorRef token.admissionIdentity
        let private terminalFlowActorOutcomeJoinActorBindingRef token = terminalFlowAdmissionActorBindingRef token.admissionIdentity
        let private terminalFlowActorOutcomeJoinCredentialLedgerRef token = terminalFlowAdmissionRequirementLedgerRef token.admissionIdentity
        let private terminalFlowActorOutcomeJoinFairnessEpochRef token = terminalFlowAdmissionFairnessEpochRef token.admissionIdentity
        let private terminalFlowActorOutcomeJoinFairnessReleaseRef token = terminalFlowIdentityRefDigest token.fairnessRelease.releaseRef

        let private terminalFlowSchedulerChannelContextForStageToken
            (stageToken:TerminalFlowActorOutcomeJoin<TerminalFlowArmedOutcomeJoinedStage>)
            =
            let graph = stageToken.credentialGraph
            let identity = stageToken.admissionIdentity
            let schedulerRelease = stageToken.schedulerRelease
            let expectedFairnessEpochRef = terminalFlowAdmissionFairnessEpochRef identity
            let expectedFairnessReleaseRef = terminalFlowIdentityRefDigest stageToken.fairnessRelease.releaseRef
            if schedulerRelease.admissionRef <> terminalFlowAdmissionRawRef identity
               || schedulerRelease.admissionIdentityRef <> terminalFlowAdmissionIdentityRef identity
               || schedulerRelease.actorBindingRef <> terminalFlowAdmissionActorBindingRef identity
               || schedulerRelease.credentialLedgerRef <> terminalFlowAdmissionRequirementLedgerRef identity
               || terminalFlowIdentityRefDigest schedulerRelease.fairnessEpochRef <> expectedFairnessEpochRef
               || terminalFlowIdentityRefDigest schedulerRelease.fairnessReleaseRef <> expectedFairnessReleaseRef then
                invalidOp "scheduler admission rejected because the sealed scheduler release does not own the join identity"
            let stageTokenWitness : TerminalFlowSchedulerWitness<TerminalFlowSchedulerStageTokenWitnessKind> =
                terminalFlowSchedulerWitnessFor "scheduler-stage-token" (terminalFlowMintedRefOf "terminal_stage_token_ref" stageToken.tokenId)
            let wakerRequirement : TerminalFlowSchedulerWitness<TerminalFlowSchedulerWakerRequirementWitnessKind> =
                terminalFlowSchedulerWitnessFor "scheduler-waker-requirement" stageToken.wakerEdge.requirementRef
            let wakerEdge : TerminalFlowSchedulerWitness<TerminalFlowSchedulerWakerEdgeWitnessKind> =
                terminalFlowSchedulerWitnessFor "scheduler-waker-edge" stageToken.wakerEdge.edgeRef
            let payload : TerminalFlowSchedulerAdmissionPayload =
                { identity = identity
                  graph = graph
                  schedulerRelease = schedulerRelease
                  stageToken = stageTokenWitness
                  wakerRequirement = wakerRequirement
                  wakerEdge = wakerEdge }
            let payloadText =
                String.concat "|"
                    [ string (terminalFlowAdmissionRawRef identity)
                      CompilerIdentityKernel.ContentDigest.text graph.exactOnce
                      CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest stageTokenWitness)
                      CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest wakerEdge)
                      string (terminalFlowIdentityRefDigest schedulerRelease.physicalReleaseRef) ]
            let receipt : TerminalFlowSchedulerReceipt<TerminalFlowSchedulerAdmissionReceiptKind,TerminalFlowSchedulerReceiptSealedStage,TerminalFlowSchedulerAdmissionPayload> =
                terminalFlowSchedulerReceiptCreateGenesis "scheduler-channel-admission" payloadText payload
            ({ receipt = receipt } : TerminalFlowSchedulerChannelAdmissionContext)

        let private terminalFlowNativeRootBridgeAuthorityText = function
            | TerminalFlowNativeRootBridgeFromNativeWriterCapability _ ->
                "native_writer_capability_legacy"
            | TerminalFlowNativeRootBridgeFromStageToken(tokenRef, rootReceiptRef, ownerLedgerSealRef, wakerEdgeRef) ->
                FastRuntimeFormat.format "stage_token_root_join|token_ref=%u|root_ref=%u|ledger_seal_ref=%u|waker_edge_ref=%u" [| box tokenRef; box rootReceiptRef; box ownerLedgerSealRef; box wakerEdgeRef |]

        let private terminalFlowNativeRootBridgeForStageToken
            (stageToken:TerminalFlowActorOutcomeJoin<TerminalFlowArmedOutcomeJoinedStage>)
            =
            let tokenRef = terminalFlowMintedRefOf "terminal_stage_token_ref" stageToken.tokenId
            let rootReceiptRef = stageToken.rootCapability.rootReceiptRef
            let ownerLedgerSealRef = stageToken.rootCapability.ownerLedgerSealRef
            let wakerEdgeRef = stageToken.wakerEdge.edgeRef
            let workDagCloseReceiptRef = stageToken.rootCapability.workDagCloseReceiptRef
            let queueRecoveryRef = stageToken.rootCapability.queueRecoveryRef
            let proofHash =
                FastRuntimeFormat.format "terminal-stage-proof:%u:%u:%u:%u:%u:%u" [| box tokenRef; box rootReceiptRef; box ownerLedgerSealRef; box wakerEdgeRef; box workDagCloseReceiptRef; box queueRecoveryRef |]
            let workDagClosureHash =
                FastRuntimeFormat.format "terminal-workdag-tail:%u:%u:%d" [| box stageToken.workDagTailClosure.ownerRef; box stageToken.workDagTailClosure.closeReceiptRef; box stageToken.workDagTailClosure.remainingObligationCount |]
            let expectedArtifactSetHash =
                sprintf "terminal-artifact-authority:%u"
                    (terminalFlowMintedRefOf "native_artifact_plan_ref" (proofHash + "|" + workDagClosureHash))
            {
                authority =
                    TerminalFlowNativeRootBridgeFromStageToken(
                        tokenRef,
                        rootReceiptRef,
                        ownerLedgerSealRef,
                        wakerEdgeRef)
                cellId = "terminal-stage-root:" + terminalFlowIdentityRefText stageToken.rootReceiptRef
                proofHash = proofHash
                resolutionRef = terminalFlowMintedRefOf "native_root_resolution_ref" (terminalFlowIdentityRefText stageToken.rootReceiptRef)
                workDagClosureHash = workDagClosureHash
                expectedArtifactSetHash = expectedArtifactSetHash
            }

        let private terminalFlowNativeRootBridgeIsValid (bridge:TerminalFlowNativeRootBridge) =
            match bridge.authority with
            | TerminalFlowNativeRootBridgeFromNativeWriterCapability capability ->
                let evidence = DiagJson.nativeWriterCapabilityEvidence capability
                evidence.cellId = bridge.cellId
                && evidence.proofHash = bridge.proofHash
                && evidence.workDagClosureHash = bridge.workDagClosureHash
                && evidence.artifactSetHash = bridge.expectedArtifactSetHash
            | TerminalFlowNativeRootBridgeFromStageToken(tokenRef, rootReceiptRef, ownerLedgerSealRef, wakerEdgeRef) ->
                tokenRef <> 0u
                && rootReceiptRef <> 0u
                && ownerLedgerSealRef <> 0u
                && wakerEdgeRef <> 0u
                && not (String.IsNullOrWhiteSpace bridge.cellId)
                && not (String.IsNullOrWhiteSpace bridge.proofHash)
                && not (String.IsNullOrWhiteSpace bridge.workDagClosureHash)
                && not (String.IsNullOrWhiteSpace bridge.expectedArtifactSetHash)

        let private terminalFlowNativeRootBridgeCapabilityText (bridge:TerminalFlowNativeRootBridge) =
            match bridge.authority with
            | TerminalFlowNativeRootBridgeFromNativeWriterCapability capability ->
                DiagJson.nativeWriterCapabilityText capability
            | TerminalFlowNativeRootBridgeFromStageToken _ ->
                "TerminalFlowStageTokenWriterCapability(proof=" + bridge.proofHash
                + "|work_dag=" + bridge.workDagClosureHash
                + "|artifact_authority=" + bridge.expectedArtifactSetHash + ")"

        let private terminalFlowNativeRootBridgeResolutionText (bridge:TerminalFlowNativeRootBridge) =
            match bridge.authority with
            | TerminalFlowNativeRootBridgeFromNativeWriterCapability capability ->
                let evidence = DiagJson.nativeWriterCapabilityEvidence capability
                DiagJson.nativeRootCompleteResolutionText evidence.resolution
            | TerminalFlowNativeRootBridgeFromStageToken _ ->
                "TerminalFlowStageTokenRootResolved(cell=" + bridge.cellId
                + "|resolution_ref=" + string bridge.resolutionRef + ")"

        let private terminalFlowNativeRootBridgeWorkDagText (bridge:TerminalFlowNativeRootBridge) =
            match bridge.authority with
            | TerminalFlowNativeRootBridgeFromNativeWriterCapability capability ->
                let evidence = DiagJson.nativeWriterCapabilityEvidence capability
                DiagJson.phaseIndexedWorkDagStateText
                    (DiagJson.PhaseIndexedWorkDagExhausted evidence.workDag)
            | TerminalFlowNativeRootBridgeFromStageToken _ ->
                "TerminalFlowWorkDagTailClosed(" + bridge.workDagClosureHash + ")"

        type TerminalFlowOutcomeFilledTransition<'Stage> = private {
            stageTokenId : string
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            fillKey : TerminalFlowFillKeyId
            fillReceiptRef : uint32
            dispatchRef : uint32
            filledAtMs : int64
        }

        type TerminalFlowWriterBoundTransition<'Stage> = private {
            filled : TerminalFlowOutcomeFilledTransition<TerminalFlowOutcomeFilledByHopacStage>
            writerCapabilityRef : uint32
            writerLeaseId : string
            ownerTransactionId : string
            boundAtMs : int64
        }

        type TerminalFlowReceiptCommittedTransition<'Stage> = private {
            writerBound : TerminalFlowWriterBoundTransition<TerminalFlowWriterCapabilityBoundByHopacStage>
            writerJobRef : uint32
            artifactReceiptRef : uint32
            exitWitnessRef : uint32
            committedAtMs : int64
        }

        type TerminalFlowDoneTransition<'Stage> = private {
            committed : TerminalFlowReceiptCommittedTransition<TerminalFlowCommitReceiptEmittedStage>
            runEndReceiptRef : uint32
            doneAtMs : int64
        }

        type private TerminalFlowBreakthroughHistory =
            | TerminalFlowBreakthroughJoined of TerminalFlowActorOutcomeJoin<TerminalFlowArmedOutcomeJoinedStage>
            | TerminalFlowBreakthroughOutcomeFilled of TerminalFlowBreakthroughHistory * TerminalFlowOutcomeFilledTransition<TerminalFlowOutcomeFilledByHopacStage>
            | TerminalFlowBreakthroughWriterBound of TerminalFlowBreakthroughHistory * TerminalFlowWriterBoundTransition<TerminalFlowWriterCapabilityBoundByHopacStage>
            | TerminalFlowBreakthroughReceiptCommitted of TerminalFlowBreakthroughHistory * TerminalFlowReceiptCommittedTransition<TerminalFlowCommitReceiptEmittedStage>
            | TerminalFlowBreakthroughDone of TerminalFlowBreakthroughHistory * TerminalFlowDoneTransition<TerminalFlowDoneSealedStage>

        let rec private terminalFlowBreakthroughHistoryDepth = function
            | TerminalFlowBreakthroughJoined _ -> 1
            | TerminalFlowBreakthroughOutcomeFilled(history, _)
            | TerminalFlowBreakthroughWriterBound(history, _)
            | TerminalFlowBreakthroughReceiptCommitted(history, _)
            | TerminalFlowBreakthroughDone(history, _) -> 1 + terminalFlowBreakthroughHistoryDepth history

        let private terminalFlowBreakthroughHistoryTip = function
            | TerminalFlowBreakthroughJoined _ -> "ArmedOutcomeJoined"
            | TerminalFlowBreakthroughOutcomeFilled _ -> "OutcomeFilled"
            | TerminalFlowBreakthroughWriterBound _ -> "WriterBound"
            | TerminalFlowBreakthroughReceiptCommitted _ -> "ReceiptCommitted"
            | TerminalFlowBreakthroughDone _ -> "Done"

        type TerminalFlowBoundCommitEnvelope<'Stage> = private {
            history : TerminalFlowBreakthroughHistory
            filled : TerminalFlowOutcomeFilledTransition<TerminalFlowOutcomeFilledByHopacStage>
            writerBound : TerminalFlowWriterBoundTransition<TerminalFlowWriterCapabilityBoundByHopacStage>
            committed : TerminalFlowReceiptCommittedTransition<TerminalFlowCommitReceiptEmittedStage>
            doneTransition : TerminalFlowDoneTransition<TerminalFlowDoneSealedStage>
            ledgerSeal : TerminalFlowOwnerLedgerSeal<TerminalFlowOwnerLedgerClosedStage>
            wakerEdge : TerminalFlowWakerEdgeReceipt<TerminalFlowWakerEdgeRegisteredStage>
        }

        let private terminalFlowPhantomOwnerKindText = function
            | TerminalFlowPhantomOwnerParentContinuation -> "parent_continuation"
            | TerminalFlowPhantomOwnerCrossKind -> "cross_kind"
            | TerminalFlowPhantomOwnerSidecarDrain -> "sidecar_drain"
            | TerminalFlowPhantomOwnerDynamicBridge -> "dynamic_bridge"
            | TerminalFlowPhantomOwnerProceduralResidual -> "procedural_residual"
            | TerminalFlowPhantomOwnerWorkDagTail -> "workdag_tail"

        [<StructuralEquality; NoComparison>]
        type private TerminalFlowWakerEdgeIdentity = {
            sourceOwnerRef : uint32
            targetTokenRef : uint32
        }

        let private terminalFlowWakerEdgeRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<TerminalFlowWakerEdgeIdentity, uint32>()

        let private terminalFlowRegisterWakerEdge sourceOwnerRef targetTokenId =
            let targetTokenRef = terminalFlowMintedRefOf "terminal_stage_token_ref" targetTokenId
            let edgeIdentity : TerminalFlowWakerEdgeIdentity =
                { sourceOwnerRef = sourceOwnerRef
                  targetTokenRef = targetTokenRef }
            let edgeRef =
                terminalFlowWakerEdgeRegistry.GetOrAdd(edgeIdentity, fun identity ->
                    terminalFlowMintedRefOf
                        "waker_edge_ref"
                        (sprintf "workdag_tail->terminal_stage_token|%u|%u" identity.sourceOwnerRef identity.targetTokenRef))
            { edgeRef = edgeRef
              sourceOwnerRef = sourceOwnerRef
              targetTokenRef = targetTokenRef
              registeredAtMs = Environment.TickCount64 }

        let private terminalFlowOwnerLedgerSealFor (closure:TerminalFlowWorkDagTailClosure<TerminalFlowWorkDagTailClosedStage>) =
            { ledgerSealRef = closure.ledgerSealRef
              closedOwnerCount = 1
              openOwnerCount = closure.remainingObligationCount
              workDagTailRef = closure.ownerRef
              closeReceiptRef = closure.closeReceiptRef
              witnessReason = closure.closureReason }

        let private terminalFlowOutcomeFilledTransitionFor stageTokenId dispatchId (fillReceipt:TerminalFlowOutcomeFillReceipt) : TerminalFlowOutcomeFilledTransition<TerminalFlowOutcomeFilledByHopacStage> =
            { stageTokenId = stageTokenId
              terminalReceiptRef = terminalFlowIdentityRefOfText fillReceipt.receiptId
              fillKey = fillReceipt.fillKey
              fillReceiptRef = terminalFlowMintedRefOf "outcome_fill_receipt_ref" fillReceipt.receiptId
              dispatchRef = terminalFlowMintedRefOf "dispatch_ref" dispatchId
              filledAtMs = Environment.TickCount64 }

        let private terminalFlowWriterBoundTransitionFor filled (writer:TerminalFlowWriterCapability<TerminalFlowWriterBoundState>) =
            { filled = filled
              writerCapabilityRef = terminalFlowMintedRefOf "writer_capability_ref" writer.writerLeaseId
              writerLeaseId = writer.writerLeaseId
              ownerTransactionId = writer.ownerTransactionId
              boundAtMs = Environment.TickCount64 }

        let private terminalFlowReceiptCommittedTransitionFor writerBound (writerReceipt:TerminalFlowWriterJobReceipt) (exitWitness:TerminalFlowExitWitness) =
            { writerBound = writerBound
              writerJobRef = terminalFlowMintedRefOf "writer_job_ref" writerReceipt.writerJobId
              artifactReceiptRef = terminalFlowMintedRefOf "artifact_receipt_ref" writerReceipt.artifactReceipt.plan.planId
              exitWitnessRef = terminalFlowMintedRefOf "exit_witness_ref" exitWitness.witnessId
              committedAtMs = Environment.TickCount64 }

        let private terminalFlowDoneTransitionFor (committed:TerminalFlowReceiptCommittedTransition<TerminalFlowCommitReceiptEmittedStage>) =
            { committed = committed
              runEndReceiptRef = terminalFlowMintedRefOf "run_end_receipt_ref" (FastRuntimeFormat.format "%u|%u|%u" [| box committed.writerJobRef; box committed.artifactReceiptRef; box committed.exitWitnessRef |])
              doneAtMs = Environment.TickCount64 }

        let private terminalFlowBoundCommitEnvelopeFor
            (stageToken:TerminalFlowActorOutcomeJoin<TerminalFlowArmedOutcomeJoinedStage>)
            (completed:TerminalFlowCommitCompleted)
            =
            let filled =
                terminalFlowOutcomeFilledTransitionFor
                    completed.consumedToken.tokenId
                    completed.consumedToken.dispatchId
                    completed.bound.filled.fillReceipt
            let writerBound = terminalFlowWriterBoundTransitionFor filled completed.bound.writer
            let committed = terminalFlowReceiptCommittedTransitionFor writerBound completed.writerReceipt completed.exitWitness
            let doneTransition = terminalFlowDoneTransitionFor committed
            let ledgerSeal = terminalFlowOwnerLedgerSealFor stageToken.workDagTailClosure
            let wakerEdge = terminalFlowRegisterWakerEdge stageToken.workDagTailClosure.ownerRef stageToken.tokenId
            let joinedHistory = TerminalFlowBreakthroughJoined stageToken
            let filledHistory = TerminalFlowBreakthroughOutcomeFilled(joinedHistory, filled)
            let writerHistory = TerminalFlowBreakthroughWriterBound(filledHistory, writerBound)
            let committedHistory = TerminalFlowBreakthroughReceiptCommitted(writerHistory, committed)
            let doneHistory = TerminalFlowBreakthroughDone(committedHistory, doneTransition)
            { history = doneHistory
              filled = filled
              writerBound = writerBound
              committed = committed
              doneTransition = doneTransition
              ledgerSeal = ledgerSeal
              wakerEdge = wakerEdge }

        // Dispatch capability is distinct from semantic outcome maturity.  A canonical-root
        // observation may prove BuildOk without owning the native scheduler edge; encoding
        // that distinction prevents an observer callback from masquerading as executable
        // terminal authority after QAP reaches Applied.
        type TerminalFlowPendingDispatchAuthority =
            | TerminalFlowPendingObserverProjection of sourceRef:uint32
            | TerminalFlowPendingNativeExecutable of capabilityRef:uint32

        let private terminalFlowPendingDispatchAuthorityText = function
            | TerminalFlowPendingObserverProjection sourceRef -> sprintf "ObserverProjection(source_ref=%u)" sourceRef
            | TerminalFlowPendingNativeExecutable capabilityRef -> sprintf "NativeExecutable(capability_ref=%u)" capabilityRef

        let private terminalFlowPendingDispatchAuthorityRef = function
            | TerminalFlowPendingObserverProjection sourceRef -> sourceRef
            | TerminalFlowPendingNativeExecutable capabilityRef -> capabilityRef

        let private terminalFlowPendingDispatchIsExecutable = function
            | TerminalFlowPendingNativeExecutable _ -> true
            | TerminalFlowPendingObserverProjection _ -> false

        let private terminalFlowPendingDispatchAuthoritySame left right =
            match left, right with
            | TerminalFlowPendingObserverProjection leftRef, TerminalFlowPendingObserverProjection rightRef
            | TerminalFlowPendingNativeExecutable leftRef, TerminalFlowPendingNativeExecutable rightRef -> leftRef = rightRef
            | _ -> false

        // Destructive domain migration round : a pending terminal is no longer
        // one flat record whose intent and authority can form arbitrary combinations.
        // Maturity and dispatch authority are phantom-indexed, then existentially
        // packaged at the reducer boundary.  Legacy projections are members only;
        // construction must pass through terminalFlowPendingCandidateCreate.
        [<Struct>]
        type TerminalFlowObserverDispatchAuthorityStage = struct end

        [<Struct>]
        type TerminalFlowExecutableDispatchAuthorityStage = struct end

        type TerminalFlowPendingIntentToken<'Maturity> = private {
            legacyIntent : TerminalFlowPendingTerminalIntent
            maturityRef : TerminalFlowIdentityRef<TerminalFlowStageCapabilityRefKind>
        }

        type TerminalFlowPendingAuthorityToken<'Authority> = private {
            legacyAuthority : TerminalFlowPendingDispatchAuthority
            authorityRef : TerminalFlowIdentityRef<TerminalFlowDispatchRefKind>
        }

        type TerminalFlowPendingCandidate<'Maturity,'Authority> = private {
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            fillRef : TerminalFlowIdentityRef<TerminalFlowFillRefKind>
            intentToken : TerminalFlowPendingIntentToken<'Maturity>
            admission : TerminalFlowPendingAdmission
            admissionIdentity : TerminalFlowAdmissionIdentity
            authorityToken : TerminalFlowPendingAuthorityToken<'Authority>
            armAndDispatch : TerminalFlowActorOutcomeJoin<TerminalFlowArmedOutcomeJoinedStage> -> Hopac.Job<TerminalFlowNativeHandoffId>
        }

        type TerminalFlowGlobalPendingTerminal =
            private
            | TerminalFlowPendingObserverProvisional of TerminalFlowPendingCandidate<TerminalFlowOutcomeProvisionalStage,TerminalFlowObserverDispatchAuthorityStage>
            | TerminalFlowPendingObserverFinal of TerminalFlowPendingCandidate<TerminalFlowOutcomeFinalStage,TerminalFlowObserverDispatchAuthorityStage>
            | TerminalFlowPendingExecutableProvisional of TerminalFlowPendingCandidate<TerminalFlowOutcomeProvisionalStage,TerminalFlowExecutableDispatchAuthorityStage>
            | TerminalFlowPendingExecutableFinal of TerminalFlowPendingCandidate<TerminalFlowOutcomeFinalStage,TerminalFlowExecutableDispatchAuthorityStage>
            with
                member this.terminalReceiptId =
                    match this with
                    | TerminalFlowPendingObserverProvisional candidate -> terminalFlowIdentityRefText candidate.terminalReceiptRef
                    | TerminalFlowPendingObserverFinal candidate -> terminalFlowIdentityRefText candidate.terminalReceiptRef
                    | TerminalFlowPendingExecutableProvisional candidate -> terminalFlowIdentityRefText candidate.terminalReceiptRef
                    | TerminalFlowPendingExecutableFinal candidate -> terminalFlowIdentityRefText candidate.terminalReceiptRef

                member this.terminalReceiptRef =
                    match this with
                    | TerminalFlowPendingObserverProvisional candidate -> candidate.terminalReceiptRef
                    | TerminalFlowPendingObserverFinal candidate -> candidate.terminalReceiptRef
                    | TerminalFlowPendingExecutableProvisional candidate -> candidate.terminalReceiptRef
                    | TerminalFlowPendingExecutableFinal candidate -> candidate.terminalReceiptRef

                member this.fillRef =
                    match this with
                    | TerminalFlowPendingObserverProvisional candidate -> candidate.fillRef
                    | TerminalFlowPendingObserverFinal candidate -> candidate.fillRef
                    | TerminalFlowPendingExecutableProvisional candidate -> candidate.fillRef
                    | TerminalFlowPendingExecutableFinal candidate -> candidate.fillRef

                member this.fillKeyId =
                    TerminalFlowFillKeyId.ofRef this.fillRef

                member this.fillKey =
                    TerminalFlowFillKeyId.text this.fillKeyId

                member this.intent =
                    match this with
                    | TerminalFlowPendingObserverProvisional candidate -> candidate.intentToken.legacyIntent
                    | TerminalFlowPendingObserverFinal candidate -> candidate.intentToken.legacyIntent
                    | TerminalFlowPendingExecutableProvisional candidate -> candidate.intentToken.legacyIntent
                    | TerminalFlowPendingExecutableFinal candidate -> candidate.intentToken.legacyIntent

                member this.admission =
                    match this with
                    | TerminalFlowPendingObserverProvisional candidate -> candidate.admission
                    | TerminalFlowPendingObserverFinal candidate -> candidate.admission
                    | TerminalFlowPendingExecutableProvisional candidate -> candidate.admission
                    | TerminalFlowPendingExecutableFinal candidate -> candidate.admission

                member this.admissionIdentity =
                    match this with
                    | TerminalFlowPendingObserverProvisional candidate -> candidate.admissionIdentity
                    | TerminalFlowPendingObserverFinal candidate -> candidate.admissionIdentity
                    | TerminalFlowPendingExecutableProvisional candidate -> candidate.admissionIdentity
                    | TerminalFlowPendingExecutableFinal candidate -> candidate.admissionIdentity

                member this.dispatchAuthority =
                    match this with
                    | TerminalFlowPendingObserverProvisional candidate -> candidate.authorityToken.legacyAuthority
                    | TerminalFlowPendingObserverFinal candidate -> candidate.authorityToken.legacyAuthority
                    | TerminalFlowPendingExecutableProvisional candidate -> candidate.authorityToken.legacyAuthority
                    | TerminalFlowPendingExecutableFinal candidate -> candidate.authorityToken.legacyAuthority

                member this.armAndDispatch =
                    match this with
                    | TerminalFlowPendingObserverProvisional candidate -> candidate.armAndDispatch
                    | TerminalFlowPendingObserverFinal candidate -> candidate.armAndDispatch
                    | TerminalFlowPendingExecutableProvisional candidate -> candidate.armAndDispatch
                    | TerminalFlowPendingExecutableFinal candidate -> candidate.armAndDispatch

        type TerminalFlowPendingCandidateClass =
            | TerminalFlowObserverProvisionalCandidateClass
            | TerminalFlowObserverFinalCandidateClass
            | TerminalFlowExecutableProvisionalCandidateClass
            | TerminalFlowExecutableFinalCandidateClass

        let private terminalFlowPendingCandidateClass = function
            | TerminalFlowPendingObserverProvisional _ -> TerminalFlowObserverProvisionalCandidateClass
            | TerminalFlowPendingObserverFinal _ -> TerminalFlowObserverFinalCandidateClass
            | TerminalFlowPendingExecutableProvisional _ -> TerminalFlowExecutableProvisionalCandidateClass
            | TerminalFlowPendingExecutableFinal _ -> TerminalFlowExecutableFinalCandidateClass

        let private terminalFlowPendingCandidateClassText = function
            | TerminalFlowObserverProvisionalCandidateClass -> "ObserverProvisional"
            | TerminalFlowObserverFinalCandidateClass -> "ObserverFinal"
            | TerminalFlowExecutableProvisionalCandidateClass -> "ExecutableProvisional"
            | TerminalFlowExecutableFinalCandidateClass -> "ExecutableFinal"

        let private terminalFlowPendingCandidateIsExecutable = function
            | TerminalFlowExecutableProvisionalCandidateClass
            | TerminalFlowExecutableFinalCandidateClass -> true
            | TerminalFlowObserverProvisionalCandidateClass
            | TerminalFlowObserverFinalCandidateClass -> false

        let private terminalFlowPendingCandidateIsFinal = function
            | TerminalFlowObserverFinalCandidateClass
            | TerminalFlowExecutableFinalCandidateClass -> true
            | TerminalFlowObserverProvisionalCandidateClass
            | TerminalFlowExecutableProvisionalCandidateClass -> false

        let private terminalFlowTerminalSemanticWorkAuthorityRefOfRefs terminalRef fillRef =
            CompilerIdentityKernel.ContentDigest.ofText
                "terminal-protocol-semantic-work"
                (FastRuntimeFormat.format "%u|%u" [| box terminalRef; box fillRef |])

        let private terminalFlowTerminalSemanticWorkUnitOfRefs terminalRef fillRef =
            let authorityRef = terminalFlowTerminalSemanticWorkAuthorityRefOfRefs terminalRef fillRef
            CompilerKernelV2.WorkUnitIdOps.createKernel<CompilerKernelV2.TerminalProtocolPhase,CompilerKernelV2.TerminalWorkKind>
                authorityRef
                1L

        let private terminalFlowTerminalSemanticWorkUnitForIdentityRefs
            (terminalReceiptRef:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>)
            (fillKeyId:TerminalFlowFillKeyId) =
            terminalFlowTerminalSemanticWorkUnitOfRefs
                (terminalFlowIdentityRefDigest terminalReceiptRef)
                (TerminalFlowFillKeyId.digest fillKeyId)

        let private terminalFlowTerminalSemanticWorkCost : CompilerKernelV2.SemanticCost =
            CompilerKernelV2.Measured.one

        let private terminalFlowTerminalSemanticWorkAdmitForRefs terminalReceiptRef fillKeyId =
            let workUnit = terminalFlowTerminalSemanticWorkUnitForIdentityRefs terminalReceiptRef fillKeyId
            CompilerKernelV2.SemanticWorkLedgerAuthority.transact
                (CompilerKernelV2.SemanticWorkAdmit(
                    CompilerKernelV2.SomeTerminalWorkUnit workUnit,
                    terminalFlowTerminalSemanticWorkCost))
            |> Result.isOk

        let private terminalFlowTerminalSemanticWorkResolveUnit workUnit disposition =
            let receipt =
                CompilerKernelV2.WorkUnitReceipt.create
                    workUnit
                    disposition
                    terminalFlowTerminalSemanticWorkCost
            CompilerKernelV2.SemanticWorkLedgerAuthority.transact
                (CompilerKernelV2.SemanticWorkApply(CompilerKernelV2.SomeTerminalWorkReceipt receipt))

        let private terminalFlowTerminalSemanticWorkRetireUnit workUnit receiptRef =
            terminalFlowTerminalSemanticWorkResolveUnit
                workUnit
                (CompilerKernelV2.WorkUnitRetired receiptRef)
            |> Result.isOk

        let private terminalFlowTerminalSemanticWorkSupersedeForRefs terminalReceiptRef fillKeyId transitionRef =
            terminalFlowTerminalSemanticWorkResolveUnit
                (terminalFlowTerminalSemanticWorkUnitForIdentityRefs terminalReceiptRef fillKeyId)
                (CompilerKernelV2.WorkUnitSuperseded transitionRef)
            |> Result.isOk

        let private terminalFlowTerminalSemanticWorkFailForRefs terminalReceiptRef fillKeyId failureRef =
            terminalFlowTerminalSemanticWorkResolveUnit
                (terminalFlowTerminalSemanticWorkUnitForIdentityRefs terminalReceiptRef fillKeyId)
                (CompilerKernelV2.WorkUnitFailed failureRef)
            |> Result.isOk

        let private terminalFlowPendingCandidateCreateForRefs
            (terminalReceiptRef:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>)
            (fillKeyId:TerminalFlowFillKeyId)
            intent
            admission
            dispatchAuthority
            armAndDispatch =
            let fillRef = TerminalFlowFillKeyId.reference fillKeyId
            let admissionIdentity =
                terminalFlowAdmissionIdentityForRefs terminalReceiptRef fillKeyId (terminalFlowPendingAdmissionRef admission)
            if not (terminalFlowTerminalSemanticWorkAdmitForRefs terminalReceiptRef fillKeyId) then
                invalidOp "terminal candidate semantic admission was rejected"
            let provisionalIntentToken intent : TerminalFlowPendingIntentToken<TerminalFlowOutcomeProvisionalStage> =
                { legacyIntent = intent
                  maturityRef = terminalFlowIdentityRefOfText ("terminal-pending-provisional|" + terminalFlowPendingIntentMaturityLabel intent) }
            let finalIntentToken intent : TerminalFlowPendingIntentToken<TerminalFlowOutcomeFinalStage> =
                { legacyIntent = intent
                  maturityRef = terminalFlowIdentityRefOfText ("terminal-pending-final|" + terminalFlowPendingIntentMaturityLabel intent) }
            let observerAuthorityToken sourceRef : TerminalFlowPendingAuthorityToken<TerminalFlowObserverDispatchAuthorityStage> =
                { legacyAuthority = TerminalFlowPendingObserverProjection sourceRef
                  authorityRef = terminalFlowIdentityRefOfText (sprintf "terminal-pending-observer-authority:%u" sourceRef) }
            let executableAuthorityToken capabilityRef : TerminalFlowPendingAuthorityToken<TerminalFlowExecutableDispatchAuthorityStage> =
                { legacyAuthority = TerminalFlowPendingNativeExecutable capabilityRef
                  authorityRef = terminalFlowIdentityRefOfText (sprintf "terminal-pending-executable-authority:%u" capabilityRef) }
            match intent, dispatchAuthority with
            | (TerminalFlowPendingNoFurther | TerminalFlowPendingQuarantine), TerminalFlowPendingObserverProjection sourceRef ->
                TerminalFlowPendingObserverProvisional {
                    terminalReceiptRef = terminalReceiptRef
                    fillRef = fillRef
                    intentToken = provisionalIntentToken intent
                    admission = admission
                    admissionIdentity = admissionIdentity
                    authorityToken = observerAuthorityToken sourceRef
                    armAndDispatch = armAndDispatch }
            | (TerminalFlowPendingBuildOk | TerminalFlowPendingFailClosed), TerminalFlowPendingObserverProjection sourceRef ->
                TerminalFlowPendingObserverFinal {
                    terminalReceiptRef = terminalReceiptRef
                    fillRef = fillRef
                    intentToken = finalIntentToken intent
                    admission = admission
                    admissionIdentity = admissionIdentity
                    authorityToken = observerAuthorityToken sourceRef
                    armAndDispatch = armAndDispatch }
            | (TerminalFlowPendingNoFurther | TerminalFlowPendingQuarantine), TerminalFlowPendingNativeExecutable capabilityRef ->
                TerminalFlowPendingExecutableProvisional {
                    terminalReceiptRef = terminalReceiptRef
                    fillRef = fillRef
                    intentToken = provisionalIntentToken intent
                    admission = admission
                    admissionIdentity = admissionIdentity
                    authorityToken = executableAuthorityToken capabilityRef
                    armAndDispatch = armAndDispatch }
            | (TerminalFlowPendingBuildOk | TerminalFlowPendingFailClosed), TerminalFlowPendingNativeExecutable capabilityRef ->
                TerminalFlowPendingExecutableFinal {
                    terminalReceiptRef = terminalReceiptRef
                    fillRef = fillRef
                    intentToken = finalIntentToken intent
                    admission = admission
                    admissionIdentity = admissionIdentity
                    authorityToken = executableAuthorityToken capabilityRef
                    armAndDispatch = armAndDispatch }

        let private terminalFlowPendingCandidateCreate
            terminalReceiptId
            fillKey
            intent
            admission
            dispatchAuthority
            armAndDispatch =
            terminalFlowPendingCandidateCreateForRefs
                (terminalFlowIdentityRefOfText terminalReceiptId)
                (TerminalFlowFillKeyId.create fillKey)
                intent
                admission
                dispatchAuthority
                armAndDispatch

        let private terminalFlowPendingCandidateWithIdentityForRefs
            (terminalReceiptRef:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>)
            (fillKeyId:TerminalFlowFillKeyId)
            (pending:TerminalFlowGlobalPendingTerminal) =
            terminalFlowPendingCandidateCreateForRefs
                terminalReceiptRef
                fillKeyId
                pending.intent
                pending.admission
                pending.dispatchAuthority
                pending.armAndDispatch

        // Round  also retires option from QAP pending-state.  Absence is a
        // protocol state, not a generic container case; later rounds will carry
        // this slot recursively through the proof spine and remove the option
        // adapter at the global reducer ingress.
        type TerminalFlowPendingSlot =
            | TerminalFlowPendingSlotAwaitingCandidate
            | TerminalFlowPendingSlotCandidate of TerminalFlowGlobalPendingTerminal

        let private terminalFlowPendingSlotIsAbsent = function
            | TerminalFlowPendingSlotAwaitingCandidate -> true
            | TerminalFlowPendingSlotCandidate _ -> false

        let private terminalFlowPendingSlotIsPresent pendingSlot =
            not (terminalFlowPendingSlotIsAbsent pendingSlot)

        // Bonus migration  removes the parallel root/outcome/actor mirrors.
        // The kernel is now the only mutable authority; timestamps are carried by
        // the typed phases rather than recovered from renderer-side snapshots.
        type TerminalFlowKernelRoot =
            | KernelRootAwaitingEvaluator
            | KernelRootResolved of receiptRef:TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind> * resolvedAtMs:int64 * evidenceRef:uint32

        type TerminalFlowKernelOutcome =
            | KernelOutcomeOpen
            | KernelOutcomeSealed of terminalReceiptRef:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind> * fillKey:TerminalFlowFillKeyId

        type TerminalFlowKernelActor =
            | KernelActorNoop
            | KernelActorArmed of phase:DiagJson.TerminalSchedulerPushActorPhase * fillKey:TerminalFlowFillKeyId * changedAtMs:int64

        [<StructuralEquality; NoComparison>]
        type TerminalFlowKernelActorFillIngress =
            | TerminalFlowActorFillIngressBootstrap
            | TerminalFlowActorFillIngressUnbound
            | TerminalFlowActorFillIngressBound of fillRef:TerminalFlowIdentityRef<TerminalFlowFillRefKind>

        type TerminalFlowKernelActorFillBinding =
            | TerminalFlowActorFillBootstrapAwaitingOutcome
            | TerminalFlowActorFillUnbound
            | TerminalFlowActorFillBound of fillKey:TerminalFlowFillKeyId

        let private terminalFlowKernelActorFillIngressOfBoundaryText fillKey =
            if String.IsNullOrWhiteSpace fillKey then TerminalFlowActorFillIngressUnbound
            elif fillKey = "terminal-flow-reducer-bootstrap" then TerminalFlowActorFillIngressBootstrap
            else TerminalFlowActorFillIngressBound (terminalFlowIdentityRefOfText fillKey)

        let private terminalFlowKernelActorFillBindingOf = function
            | TerminalFlowActorFillIngressBootstrap -> TerminalFlowActorFillBootstrapAwaitingOutcome
            | TerminalFlowActorFillIngressUnbound -> TerminalFlowActorFillUnbound
            | TerminalFlowActorFillIngressBound fillRef -> TerminalFlowActorFillBound (TerminalFlowFillKeyId.ofRef fillRef)

        type TerminalFlowKernelDispatch =
            | KernelDispatchUnavailable
            | KernelDispatchReady of identity:TerminalFlowDispatchRequestIdentity * rootReceiptRef:TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind> * terminalReceiptRef:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            | KernelDispatchAccepted of identity:TerminalFlowDispatchRequestIdentity

        type TerminalFlowKernelExit =
            | KernelExitOpen
            | KernelExitWitnessed of identity:TerminalFlowExitRequestIdentity * exitCode:int * physicalChain:TerminalFlowPhysicalExitChain

        type TerminalFlowKernelInvariant =
            | KernelInvariantSatisfied
            | KernelInvariantAwaitingRoot
            | KernelInvariantAwaitingOutcome
            | KernelInvariantActorNoopWithJoinReady
            | KernelInvariantExitUnauthorized

        [<StructuralEquality; NoComparison>]
        type TerminalFlowKernelProgressStageId =
            | TerminalFlowKernelProgressLostWakeupCandidate
            | TerminalFlowKernelProgressAwaitRoot
            | TerminalFlowKernelProgressAwaitOutcome
            | TerminalFlowKernelProgressExitUnauthorized
            | TerminalFlowKernelProgressDone
            | TerminalFlowKernelProgressWriterBound
            | TerminalFlowKernelProgressReadyToDispatch
            | TerminalFlowKernelProgressAwaitActor
            | TerminalFlowKernelProgressJoinReady
            | TerminalFlowKernelProgressing

        type TerminalFlowKernelState = private {
            root : TerminalFlowKernelRoot
            outcome : TerminalFlowKernelOutcome
            actor : TerminalFlowKernelActor
            dispatch : TerminalFlowKernelDispatch
            exit : TerminalFlowKernelExit
            stage : TerminalFlowAnyKernelStage
            invariant : TerminalFlowKernelInvariant
            revision : int64
        }

        [<StructuralEquality; NoComparison>]
        type TerminalFlowKernelDecisionAuthorityId =
            | TerminalFlowKernelReducerDurableProjection

        let private terminalFlowKernelDecisionAuthorityText = function
            | TerminalFlowKernelReducerDurableProjection -> "terminal_flow_kernel_durable_projection"

        type TerminalFlowKernelDurableProjection = private {
            stageTag : TerminalFlowKernelProgressStageId
            stageCapabilityTag : TerminalFlowKernelStageKindId
            stageCapabilityRef : uint32
            invariantTag : TerminalFlowKernelInvariant
            rootReceiptRef : uint32
            terminalReceiptRef : uint32
            fillRef : uint32
            dispatchRef : uint32
            writerCapabilityRef : uint32
            artifactReceiptRef : uint32
            exitRef : uint32
            receiptVectorHash : uint32
            captureComplete : bool
            decisionAuthority : TerminalFlowKernelDecisionAuthorityId
        }

        type TerminalFlowReceiptProjectionKind =
            | TerminalFlowReceiptProjectionAwaitRoot
            | TerminalFlowReceiptProjectionAwaitOutcome
            | TerminalFlowReceiptProjectionReadyToDispatch
            | TerminalFlowReceiptProjectionWriterBound
            | TerminalFlowReceiptProjectionArtifactCommitted
            | TerminalFlowReceiptProjectionExitWitnessed
            | TerminalFlowReceiptProjectionRunEndPrepared

        type TerminalFlowExistentialReceiptProjection = private {
            projectionKind : TerminalFlowReceiptProjectionKind
            projectionRef : uint32
            stageCapabilityRef : uint32
            receiptVectorHash : uint32
            rootReceiptRef : uint32
            terminalReceiptRef : uint32
            fillRef : uint32
            dispatchRef : uint32
            writerCapabilityRef : uint32
            artifactReceiptRef : uint32
            exitRef : uint32
            captureComplete : bool
        }

        // Round : projections stop being naked UInt32 bags at the reducer
        // boundary.  The old projection record stays as the JSON-erasure layer,
        // but the kernel now has a kinded vector that proves which lane every
        // ref belongs to before HUD/log rendering can print it.
        type TerminalFlowTypedProjectionVector = private {
            rootReceiptRef : TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind> option
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind> option
            fillRef : TerminalFlowIdentityRef<TerminalFlowFillRefKind> option
            dispatchRef : TerminalFlowIdentityRef<TerminalFlowDispatchRefKind> option
            identitySlots : TerminalFlowExistentialIdentitySlot list
            stageCapabilityRef : TerminalFlowDurableRef<TerminalFlowStageCapabilityRefKind>
            receiptProjectionRef : TerminalFlowDurableRef<TerminalFlowReceiptProjectionRefKind>
            causalSpineRef : TerminalFlowDurableRef<TerminalFlowCausalSpineRefKind>
            writerCapabilityRef : TerminalFlowDurableRef<TerminalFlowWriterCapabilityRefKind> option
            artifactReceiptRef : TerminalFlowDurableRef<TerminalFlowArtifactReceiptRefKind> option
            exitWitnessRef : TerminalFlowDurableRef<TerminalFlowExitWitnessRefKind> option
            receiptVectorHash : uint32
            captureComplete : bool
        }

        type IAnyTerminalFlowKernel =
            abstract member StageTag : string
            abstract member DurableProjection : TerminalFlowKernelDurableProjection
            abstract member RenderJson : unit -> string
            abstract member RenderHotFields : unit -> string
            abstract member RenderHud : unit -> string

        type TerminalFlowGlobalCausalSpine =
            | TerminalFlowGlobalCausalGenesis
            | TerminalFlowGlobalRootReceiptStep of receiptRef:TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind> * prior:TerminalFlowGlobalCausalSpine
            | TerminalFlowGlobalOutcomeReceiptStep of terminalRef:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind> * fillRef:TerminalFlowIdentityRef<TerminalFlowFillRefKind> * prior:TerminalFlowGlobalCausalSpine
            | TerminalFlowGlobalDispatchStep of dispatchRef:TerminalFlowIdentityRef<TerminalFlowDispatchRefKind> * fillRef:TerminalFlowIdentityRef<TerminalFlowFillRefKind> * prior:TerminalFlowGlobalCausalSpine
            | TerminalFlowGlobalActorStep of phaseRef:TerminalFlowDurableRef<TerminalFlowActorPhaseRefKind> * fillRef:TerminalFlowIdentityRef<TerminalFlowFillRefKind> * prior:TerminalFlowGlobalCausalSpine
            | TerminalFlowGlobalCommitStep of artifactReceiptRef:TerminalFlowDurableRef<TerminalFlowArtifactReceiptRefKind> * runEndReceiptRef:TerminalFlowDurableRef<TerminalFlowRunEndReceiptRefKind> * prior:TerminalFlowGlobalCausalSpine
            | TerminalFlowGlobalExitStep of exitRef:TerminalFlowDurableRef<TerminalFlowExitWitnessRefKind> * fillRef:TerminalFlowIdentityRef<TerminalFlowFillRefKind> * prior:TerminalFlowGlobalCausalSpine
            | TerminalFlowGlobalProgressStep of snapshotRef:TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind> * prior:TerminalFlowGlobalCausalSpine
            | TerminalFlowGlobalTopologyGateStep of gateRef:TerminalFlowIdentityRef<TerminalFlowTopologyGateRefKind> * prior:TerminalFlowGlobalCausalSpine
            | TerminalFlowGlobalWatchdogPetitionStep of petitionRef:TerminalFlowIdentityRef<TerminalFlowWatchdogPetitionRefKind> * prior:TerminalFlowGlobalCausalSpine
            | TerminalFlowGlobalQapFixpointStep of fixpointRef:TerminalFlowDurableRef<TerminalFlowQapFixpointReceiptRefKind> * materialAgeMs:int64 * prior:TerminalFlowGlobalCausalSpine
            | TerminalFlowGlobalQapWatchRebaseStep of fixpointRef:TerminalFlowDurableRef<TerminalFlowQapFixpointReceiptRefKind> * fromSemanticEpoch:int64 * toSemanticEpoch:int64 * fromFrontierEpoch:int64 * toFrontierEpoch:int64 * frontierProgressBp:int64 * fromCompletionEpoch:int64 * toCompletionEpoch:int64 * completedCost:int64 * prior:TerminalFlowGlobalCausalSpine
            | TerminalFlowGlobalOwnerDebtStep of ownerDebtRef:TerminalFlowDurableRef<TerminalFlowOwnerDebtRefKind> * prior:TerminalFlowGlobalCausalSpine

        type TerminalFlowReducerOwnerDebt =
            | TerminalFlowReducerOwnerDebtUnobserved
            | TerminalFlowReducerOwnerDebtObserved of stickyTailRef:uint32 * decisionRef:uint32 * decision:TerminalFlowOwnerCloseDecisionId
            | TerminalFlowReducerOwnerDebtAccepted of stickyTailRef:uint32 * decisionRef:uint32 * closeReceiptRef:uint32
            | TerminalFlowReducerOwnerDebtRejected of stickyTailRef:uint32 * decisionRef:uint32 * reasonRef:uint32

        type TerminalFlowOwnerDebtRefreshDisposition =
            | TerminalFlowOwnerDebtObservedAuthorityApplied of observedDecisionRef:uint32
            | TerminalFlowOwnerDebtEvidenceRefreshPreservedInstalledIdentity of installedDecisionRef:uint32 * observedDecisionRef:uint32
            | TerminalFlowOwnerDebtEvidenceRefreshReplacedInstalledIdentity of installedDecisionRef:uint32 * observedDecisionRef:uint32

        let private terminalFlowOwnerDebtRefreshDispositionText = function
            | TerminalFlowOwnerDebtObservedAuthorityApplied observedDecisionRef ->
                sprintf "ObservedAuthorityApplied(observed_decision_ref=%u)" observedDecisionRef
            | TerminalFlowOwnerDebtEvidenceRefreshPreservedInstalledIdentity(installedDecisionRef, observedDecisionRef) ->
                sprintf "EvidenceRefreshPreservedInstalledIdentity(installed_decision_ref=%u|observed_decision_ref=%u)" installedDecisionRef observedDecisionRef
            | TerminalFlowOwnerDebtEvidenceRefreshReplacedInstalledIdentity(installedDecisionRef, observedDecisionRef) ->
                sprintf "EvidenceRefreshReplacedInstalledIdentity(installed_decision_ref=%u|observed_decision_ref=%u)" installedDecisionRef observedDecisionRef

        let private terminalFlowReducerOwnerDebtRef = function
            | TerminalFlowReducerOwnerDebtUnobserved -> 0u
            | TerminalFlowReducerOwnerDebtObserved(_, decisionRef, _)
            | TerminalFlowReducerOwnerDebtAccepted(_, decisionRef, _)
            | TerminalFlowReducerOwnerDebtRejected(_, decisionRef, _) -> decisionRef

        let private terminalFlowReducerOwnerDebtText = function
            | TerminalFlowReducerOwnerDebtUnobserved -> "owner_debt_unobserved"
            | TerminalFlowReducerOwnerDebtObserved(stickyTailRef, decisionRef, decision) ->
                let decisionTag =
                    match decision with
                    | TerminalFlowOwnerCloseDeferredMaterialDelta _ -> "deferred_material_delta"
                    | TerminalFlowOwnerCloseAwaitConservedCreditQuiescence _ -> "await_conserved_credit_quiescence"
                    | TerminalFlowOwnerCloseAlreadyExhausted _ -> "already_exhausted"
                FastRuntimeFormat.format "owner_debt_observed|tail_ref=%u|decision_ref=%u|decision=%s" [| box stickyTailRef; box decisionRef; box decisionTag |]
            | TerminalFlowReducerOwnerDebtAccepted(stickyTailRef, decisionRef, closeReceiptRef) ->
                FastRuntimeFormat.format "owner_debt_accepted|tail_ref=%u|decision_ref=%u|close_receipt_ref=%u" [| box stickyTailRef; box decisionRef; box closeReceiptRef |]
            | TerminalFlowReducerOwnerDebtRejected(stickyTailRef, decisionRef, reasonRef) ->
                FastRuntimeFormat.format "owner_debt_rejected|tail_ref=%u|decision_ref=%u|reason_ref=%u" [| box stickyTailRef; box decisionRef; box reasonRef |]

        let private terminalFlowReducerOwnerDebtTerminalOutcomeAllowed = function
            | TerminalFlowReducerOwnerDebtAccepted _ -> true
            | TerminalFlowReducerOwnerDebtUnobserved
            | TerminalFlowReducerOwnerDebtObserved _
            | TerminalFlowReducerOwnerDebtRejected _ -> false

        type TerminalFlowQapOwnerClosureBridge =
            | TerminalFlowQapOwnerClosureBridgeUnavailable
            | TerminalFlowQapOwnerClosureBridgeExactOnceAccepted of decisionRef:uint32 * closeReceiptRef:uint32 * workDagProofRef:uint32

        let private terminalFlowQapOwnerClosureBridgeFor
            (ownerDebt:TerminalFlowReducerOwnerDebt)
            (workDagTailCloseProof:TerminalFlowWorkDagTailCloseProof<ProceduralResidualOwnerKind> option) =
            match ownerDebt, workDagTailCloseProof with
            | TerminalFlowReducerOwnerDebtAccepted(_, decisionRef, closeReceiptRef), Some proof
                when decisionRef <> 0u
                     && closeReceiptRef <> 0u
                     && proof.openOwnerCount = 0
                     && proof.acyclicByConstruction ->
                TerminalFlowQapOwnerClosureBridgeExactOnceAccepted(
                    decisionRef,
                    closeReceiptRef,
                    uint32 (terminalFlowOwnerLedgerProtocolIdValue proof.proofRef))
            | _ -> TerminalFlowQapOwnerClosureBridgeUnavailable

        let private terminalFlowQapOwnerClosureBridgeText = function
            | TerminalFlowQapOwnerClosureBridgeUnavailable -> "OwnerClosureBridge(Unavailable)"
            | TerminalFlowQapOwnerClosureBridgeExactOnceAccepted(decisionRef, closeReceiptRef, workDagProofRef) ->
                FastRuntimeFormat.format "OwnerClosureBridge(ExactOnceAccepted|decision_ref=%u|close_receipt_ref=%u|workdag_proof_ref=%u)" [| box decisionRef; box closeReceiptRef; box workDagProofRef |]

        type TerminalFlowQapOwnerClosedResidualDisposition =
            | TerminalFlowQapOwnerClosedResidualNotApplicable
            | TerminalFlowQapOwnerClosedResidualExactCycle of bridge:TerminalFlowQapOwnerClosureBridge * relationCount:int

        let private terminalFlowQapOwnerClosedResidualFor bridge (fixpoint:TerminalFlowQapFixpointSet) =
            let relationClosed (item:TerminalFlowQapFixpointItem) =
                terminalFlowQapRelationIsConsumed item.relation
            let hasSite site = fixpoint.items |> List.exists (fun (item:TerminalFlowQapFixpointItem) -> item.site = site)
            let relationCount = List.length fixpoint.items
            let exactResidualShape =
                (relationCount = 2 || relationCount = 3)
                && (fixpoint.items |> List.forall relationClosed)
                && hasSite TerminalFlowQapCacheHandoffApplyArg0Child
                && hasSite TerminalFlowQapParentContinuationPoison
                && (relationCount = 2 || hasSite TerminalFlowQapPendingOwner)
            match bridge with
            | TerminalFlowQapOwnerClosureBridgeExactOnceAccepted _ when exactResidualShape ->
                TerminalFlowQapOwnerClosedResidualExactCycle(bridge, relationCount)
            | _ -> TerminalFlowQapOwnerClosedResidualNotApplicable

        let private terminalFlowQapOwnerClosedResidualText = function
            | TerminalFlowQapOwnerClosedResidualNotApplicable -> "OwnerClosedResidual(NotApplicable)"
            | TerminalFlowQapOwnerClosedResidualExactCycle(bridge, relationCount) ->
                sprintf "OwnerClosedResidual(ExactCycle|relations=%d|%s)" relationCount (terminalFlowQapOwnerClosureBridgeText bridge)

        let private terminalFlowQapOwnerClosedResidualAllowsTerminal = function
            | TerminalFlowQapOwnerClosedResidualExactCycle _ -> true
            | TerminalFlowQapOwnerClosedResidualNotApplicable -> false

        let private terminalFlowOwnerCloseDecisionCanMintCertificate = function
            | TerminalFlowOwnerCloseAlreadyExhausted _ -> true
            | TerminalFlowOwnerCloseDeferredMaterialDelta _
            | TerminalFlowOwnerCloseAwaitConservedCreditQuiescence _ -> false

        type TerminalFlowGlobalCommitObservation = private {
            fillKey : TerminalFlowFillKeyId
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            writerJobRef : TerminalFlowDurableRef<TerminalFlowWriterCapabilityRefKind>
            artifactReceiptRef : TerminalFlowDurableRef<TerminalFlowArtifactReceiptRefKind>
            exitWitnessRef : TerminalFlowDurableRef<TerminalFlowExitWitnessRefKind>
            runEndReceiptRef : TerminalFlowDurableRef<TerminalFlowRunEndReceiptRefKind>
            observedAtMs : int64
        }

        let private terminalFlowGlobalCommitTryFind fillKey (commits:TerminalFlowGlobalCommitObservation list) =
            commits |> List.tryFind (fun commit -> commit.fillKey = fillKey)

        let private terminalFlowGlobalCommitUpsert (commit:TerminalFlowGlobalCommitObservation) commits =
            commit :: (commits |> List.filter (fun existing -> existing.fillKey <> commit.fillKey))

        type TerminalFlowGlobalTerminalOrder =
            | TerminalFlowGlobalOrderOpen
            | TerminalFlowGlobalOrderCommitsObserved of TerminalFlowGlobalCommitObservation list
            | TerminalFlowGlobalOrderExitSelected of TerminalFlowDurableRef<TerminalFlowExitWitnessRefKind> * selectedAtMs:int64

        // MIGRATION / terminal total-order migration.  Stages are phantom markers;
        // a later-stage receipt cannot be constructed without naming its typed
        // predecessor.  The existential union is the only projection allowed to
        // cross the reducer/JSON boundary.
        type TerminalOrderAwaitDispatchStage = class end
        type TerminalOrderDispatchedStage = class end
        type TerminalOrderFilledStage = class end
        type TerminalOrderCommittedStage = class end
        type TerminalOrderDoneStage = class end
        type TerminalOrderRunEndedStage = class end
        type TerminalOrderPhysicalExitStage = class end
        type TerminalOrderRejectedStage = class end

        [<StructuralEquality; NoComparison>]
        type TerminalFlowTotalOrderFillKeyId =
            | TerminalFlowTotalOrderFillUnbound
            | TerminalFlowTotalOrderFillBound of TerminalFlowFillKeyId

        let private terminalFlowTotalOrderFillKeyText = function
            | TerminalFlowTotalOrderFillUnbound -> "unbound"
            | TerminalFlowTotalOrderFillBound fillKey -> TerminalFlowFillKeyId.text fillKey

        let private terminalFlowTotalOrderFillMatches fillKey = function
            | TerminalFlowTotalOrderFillBound bound -> bound = fillKey
            | TerminalFlowTotalOrderFillUnbound -> false

        type TerminalFlowTotalOrderReceipt<'Stage> = private {
            orderIndex : int64
            receiptRef : uint32
            predecessorRef : uint32 option
            fillKey : TerminalFlowTotalOrderFillKeyId
            exactOnce : bool
        }

        type TerminalFlowTotalOrderRejectReasonId =
            | TerminalFlowTotalOrderDispatchWithoutAwaitDispatch
            | TerminalFlowTotalOrderConsumeWithoutTypedDispatchPredecessor
            | TerminalFlowTotalOrderCommitWithoutTypedFillPredecessor
            | TerminalFlowTotalOrderTypedFailureExit of failureRef:uint32
            | TerminalFlowTotalOrderExitWitnessWithoutTypedPredecessor

        let private terminalFlowTotalOrderRejectReasonText = function
            | TerminalFlowTotalOrderDispatchWithoutAwaitDispatch ->
                "dispatch_without_await_dispatch"
            | TerminalFlowTotalOrderConsumeWithoutTypedDispatchPredecessor ->
                "consume_without_typed_dispatch_predecessor"
            | TerminalFlowTotalOrderCommitWithoutTypedFillPredecessor ->
                "commit_without_typed_fill_predecessor"
            | TerminalFlowTotalOrderTypedFailureExit failureRef ->
                sprintf "typed_failure_exit:failure_ref=%u" failureRef
            | TerminalFlowTotalOrderExitWitnessWithoutTypedPredecessor ->
                "exit_witness_without_typed_predecessor"

        type TerminalFlowTypedTotalOrder =
            | TerminalFlowTotalOrderAwaitDispatch of TerminalFlowTotalOrderReceipt<TerminalOrderAwaitDispatchStage>
            | TerminalFlowTotalOrderDispatched of TerminalFlowTotalOrderReceipt<TerminalOrderDispatchedStage>
            | TerminalFlowTotalOrderFilled of TerminalFlowTotalOrderReceipt<TerminalOrderFilledStage>
            | TerminalFlowTotalOrderCommitted of TerminalFlowTotalOrderReceipt<TerminalOrderCommittedStage>
            | TerminalFlowTotalOrderDone of TerminalFlowTotalOrderReceipt<TerminalOrderDoneStage>
            | TerminalFlowTotalOrderRunEnded of TerminalFlowTotalOrderReceipt<TerminalOrderRunEndedStage>
            | TerminalFlowTotalOrderPhysicalExit of TerminalFlowTotalOrderReceipt<TerminalOrderPhysicalExitStage>
            | TerminalFlowTotalOrderRejected of TerminalFlowTotalOrderReceipt<TerminalOrderRejectedStage> * reason:TerminalFlowTotalOrderRejectReasonId

        let private terminalFlowTotalOrderGenesisReceiptRef =
            terminalFlowMintedRefOf "terminal_total_order_genesis_ref" "typed_total_order_genesis"

        let private terminalFlowTotalOrderGenesis : TerminalFlowTypedTotalOrder =
            TerminalFlowTotalOrderAwaitDispatch {
                orderIndex = 0L
                receiptRef = terminalFlowTotalOrderGenesisReceiptRef
                predecessorRef = None
                fillKey = TerminalFlowTotalOrderFillUnbound
                exactOnce = true
            }

        let private terminalFlowTotalOrderReceiptRef = function
            | TerminalFlowTotalOrderAwaitDispatch receipt -> receipt.receiptRef
            | TerminalFlowTotalOrderDispatched receipt -> receipt.receiptRef
            | TerminalFlowTotalOrderFilled receipt -> receipt.receiptRef
            | TerminalFlowTotalOrderCommitted receipt -> receipt.receiptRef
            | TerminalFlowTotalOrderDone receipt -> receipt.receiptRef
            | TerminalFlowTotalOrderRunEnded receipt -> receipt.receiptRef
            | TerminalFlowTotalOrderPhysicalExit receipt -> receipt.receiptRef
            | TerminalFlowTotalOrderRejected(receipt, _) -> receipt.receiptRef

        let private terminalFlowTotalOrderIndex = function
            | TerminalFlowTotalOrderAwaitDispatch receipt -> receipt.orderIndex
            | TerminalFlowTotalOrderDispatched receipt -> receipt.orderIndex
            | TerminalFlowTotalOrderFilled receipt -> receipt.orderIndex
            | TerminalFlowTotalOrderCommitted receipt -> receipt.orderIndex
            | TerminalFlowTotalOrderDone receipt -> receipt.orderIndex
            | TerminalFlowTotalOrderRunEnded receipt -> receipt.orderIndex
            | TerminalFlowTotalOrderPhysicalExit receipt -> receipt.orderIndex
            | TerminalFlowTotalOrderRejected(receipt, _) -> receipt.orderIndex

        let private terminalFlowTypedTotalOrderText = function
            | TerminalFlowTotalOrderAwaitDispatch _ -> "AwaitDispatch"
            | TerminalFlowTotalOrderDispatched _ -> "Dispatched"
            | TerminalFlowTotalOrderFilled _ -> "Filled"
            | TerminalFlowTotalOrderCommitted _ -> "Committed"
            | TerminalFlowTotalOrderDone _ -> "Done"
            | TerminalFlowTotalOrderRunEnded _ -> "RunEnded"
            | TerminalFlowTotalOrderPhysicalExit _ -> "PhysicalExit"
            | TerminalFlowTotalOrderRejected(_, reason) ->
