            | TerminalFlowQapHardZeroDeltaEmptyFixpoint
            | TerminalFlowQapHardZeroDeltaMaterialDeltaPresent
            | TerminalFlowQapHardZeroDeltaRepeatCapNotReached

        [<StructuralEquality; NoComparison>]
        type TerminalFlowQapHardZeroDeltaDecision =
            | TerminalFlowQapHardZeroDeltaBlocked of wallAgeMs:int64 * itemCount:int * blocker:TerminalFlowQapHardZeroDeltaBlocker
            | TerminalFlowQapHardZeroDeltaReady of wallAgeMs:int64 * itemCount:int

        let private terminalFlowQapHardZeroDeltaCanWitness = function
            | TerminalFlowQapHardZeroDeltaReady _ -> true
            | TerminalFlowQapHardZeroDeltaBlocked _ -> false

        let private terminalFlowQapHardZeroDeltaDecisionText = function
            | TerminalFlowQapHardZeroDeltaReady(wallAgeMs, itemCount) ->
                "TerminalFlowQapHardZeroDelta(Ready|wall_age_ms=" + string wallAgeMs + "|item_count=" + string itemCount + ")"
            | TerminalFlowQapHardZeroDeltaBlocked(wallAgeMs, itemCount, blocker) ->
                let blockerText =
                    match blocker with
                    | TerminalFlowQapHardZeroDeltaAgeBelowMinimum -> "age_below_minimum"
                    | TerminalFlowQapHardZeroDeltaEmptyFixpoint -> "empty_fixpoint"
                    | TerminalFlowQapHardZeroDeltaMaterialDeltaPresent -> "material_delta_present"
                    | TerminalFlowQapHardZeroDeltaRepeatCapNotReached -> "repeat_cap_not_reached"
                "TerminalFlowQapHardZeroDelta(Blocked|wall_age_ms=" + string wallAgeMs + "|item_count=" + string itemCount + "|blocker=" + blockerText + ")"

        // QAP is generation-indexed and bound to the operational authority snapshot.
        // A witnessed generation is immutable. Any return to Awaiting must mint a
        // parent->child receipt naming both the relation-set delta and the exact
        // operational graph revision that made the previous generation obsolete.
        let mutable private terminalFlowOperationalAuthoritySnapshotProvider :
            (unit -> CompilerKernelV2.OperationalAuthoritySnapshot) =
            fun () ->
                CompilerKernelV2.OperationalAuthoritySnapshotOps.create
                    CompilerKernelV2.OperationalWorkGraph.empty
                    0
                    0
                    0L
                    (CompilerIdentityKernel.ContentDigest.ofText "portable-runtime-authority" "unbound")

        module TerminalFlowOperationalAuthorityBridge =
            let install
                (provider : unit -> CompilerKernelV2.OperationalAuthoritySnapshot) =
                terminalFlowOperationalAuthoritySnapshotProvider <- provider

        let private terminalFlowOperationalAuthoritySnapshotNow () =
            terminalFlowOperationalAuthoritySnapshotProvider ()
        [<Struct>]
        type TerminalFlowQapGenerationRefKind = struct end

        type TerminalFlowQapGenerationId<'Kind> = private TerminalFlowQapGenerationId of uint64

        type TerminalFlowQapGenerationStageId =
            | TerminalFlowQapGenerationAwaiting
            | TerminalFlowQapGenerationProgressing
            | TerminalFlowQapGenerationDrained
            | TerminalFlowQapGenerationDeadlocked

        type TerminalFlowQapRebaseReasonId =
            | TerminalFlowQapRebaseFrontierRetired
            | TerminalFlowQapRebaseSemanticAndCompletionRetired
            | TerminalFlowQapRebaseCompletionRetired
            | TerminalFlowQapRebaseRelationSetDiscovered
            | TerminalFlowQapRebaseFinalizerDeferred
            | TerminalFlowQapRebaseSemanticDrainRequested
            | TerminalFlowQapRebaseSemanticDrainCompleted
            | TerminalFlowQapRebaseHostShutdownReconcile

        type TerminalFlowQapGenerationFinalizationId =
            | TerminalFlowQapFinalizationProgressed of attemptReceiptRef:uint32
            | TerminalFlowQapFinalizationFullyDrained of drainProofRef:uint32
            | TerminalFlowQapFinalizationProvenDeadlock of deadlockProofRef:uint32

        type TerminalFlowQapRelationGenerationDelta = private {
            parentRelationSetHash : uint32
            childRelationSetHash : uint32
            carriedRelationRefs : uint32 array
            invalidatedRelationRefs : uint32 array
            discoveredRelationRefs : uint32 array
            rediscoveryRequired : bool
        }

        [<NoComparison>]
        type TerminalFlowQapRebaseReceipt = private {
            receiptRef : uint32
            parentGeneration : TerminalFlowQapGenerationId<TerminalFlowQapGenerationRefKind>
            childGeneration : TerminalFlowQapGenerationId<TerminalFlowQapGenerationRefKind>
            fixpointRef : TerminalFlowDurableRef<TerminalFlowQapFixpointReceiptRefKind>
            reason : TerminalFlowQapRebaseReasonId
            stageBefore : TerminalFlowQapGenerationStageId
            stageAfter : TerminalFlowQapGenerationStageId
            relationDelta : TerminalFlowQapRelationGenerationDelta
            fromOperationalRevision : int64
            toOperationalRevision : int64
            operationalSnapshotRef : CompilerIdentityKernel.ContentDigest
            reducerSequence : int64
        }

        [<NoComparison>]
        type TerminalFlowQapGenerationAuthority = private {
            generation : TerminalFlowQapGenerationId<TerminalFlowQapGenerationRefKind>
            parentGeneration : TerminalFlowQapGenerationId<TerminalFlowQapGenerationRefKind> option
            stage : TerminalFlowQapGenerationStageId
            fixpointRef : TerminalFlowDurableRef<TerminalFlowQapFixpointReceiptRefKind>
            relationSetHash : uint32
            operationalRevision : int64
            operationalGraphRef : CompilerIdentityKernel.ContentDigest
            operationalRuntimeAuthorityRef : CompilerIdentityKernel.ContentDigest
            operationalSemanticEpoch : int64
            operationalSnapshotRef : CompilerIdentityKernel.ContentDigest
            lastRebaseReceipt : TerminalFlowQapRebaseReceipt option
            finalization : TerminalFlowQapGenerationFinalizationId option
            finalizationReceiptRef : uint32 option
        }

        [<StructuralEquality; NoComparison>]
        type TerminalFlowQapOperationalWitnessRelationId =
            | TerminalFlowQapOperationalWitnessExactSnapshot
            | TerminalFlowQapOperationalWitnessSemanticRuntimeCompatible of fromRevision:int64 * toRevision:int64
            | TerminalFlowQapOperationalWitnessStaleSemanticEpoch
            | TerminalFlowQapOperationalWitnessStaleRuntimeAuthority

        let private terminalFlowQapOperationalWitnessRelationFor
            (authority:TerminalFlowQapGenerationAuthority)
            (snapshot:CompilerKernelV2.OperationalAuthoritySnapshot) =
            let snapshotRef = CompilerKernelV2.OperationalAuthoritySnapshotOps.snapshotRef snapshot
            let semanticEpoch = CompilerKernelV2.OperationalAuthoritySnapshotOps.semanticEpoch snapshot
            let runtimeAuthorityRef = CompilerKernelV2.OperationalAuthoritySnapshotOps.runtimeAuthorityRef snapshot
            let graphRevision = CompilerKernelV2.OperationalAuthoritySnapshotOps.graphRevision snapshot
            if authority.operationalSnapshotRef = snapshotRef then
                TerminalFlowQapOperationalWitnessExactSnapshot
            elif authority.operationalSemanticEpoch <> semanticEpoch then
                TerminalFlowQapOperationalWitnessStaleSemanticEpoch
            elif authority.operationalRuntimeAuthorityRef <> runtimeAuthorityRef then
                TerminalFlowQapOperationalWitnessStaleRuntimeAuthority
            else
                TerminalFlowQapOperationalWitnessSemanticRuntimeCompatible(authority.operationalRevision, graphRevision)

        let private terminalFlowQapOperationalWitnessRelationAllowsMaturity = function
            | TerminalFlowQapOperationalWitnessExactSnapshot
            | TerminalFlowQapOperationalWitnessSemanticRuntimeCompatible _ -> true
            | TerminalFlowQapOperationalWitnessStaleSemanticEpoch
            | TerminalFlowQapOperationalWitnessStaleRuntimeAuthority -> false

        let private terminalFlowQapOperationalWitnessRelationText = function
            | TerminalFlowQapOperationalWitnessExactSnapshot -> "ExactSnapshot"
            | TerminalFlowQapOperationalWitnessSemanticRuntimeCompatible(fromRevision, toRevision) ->
                FastRuntimeFormat.format "SemanticRuntimeCompatible(from_revision=%d|to_revision=%d)" [| box fromRevision; box toRevision |]
            | TerminalFlowQapOperationalWitnessStaleSemanticEpoch -> "StaleSemanticEpoch"
            | TerminalFlowQapOperationalWitnessStaleRuntimeAuthority -> "StaleRuntimeAuthority"

        // MIGRATION / destructive migration 2 of 5: finalization is total.
        // A reducer attempt always returns one of Progressed, FullyDrained or
        // ProvenDeadlock. Missing dispatch/recovery evidence may block handoff,
        // but it cannot demote a final QAP generation or resurrect a provisional
        // terminal outcome.
        type TerminalFlowQapFinalizerDispositionId =
            | TerminalFlowQapFinalizerContinueProgress
            | TerminalFlowQapFinalizerSealDrained
            | TerminalFlowQapFinalizerSealDeadlock

        let private terminalFlowQapFinalizerDispositionText = function
            | TerminalFlowQapFinalizerContinueProgress -> "ContinueProgress"
            | TerminalFlowQapFinalizerSealDrained -> "SealDrained"
            | TerminalFlowQapFinalizerSealDeadlock -> "SealDeadlock"

        type TerminalFlowQapFinalizerTransition = private {
            attemptReceiptRef : uint32
            generation : TerminalFlowQapGenerationId<TerminalFlowQapGenerationRefKind>
            stageBefore : TerminalFlowQapGenerationStageId
            stageAfter : TerminalFlowQapGenerationStageId
            disposition : TerminalFlowQapFinalizerDispositionId
            result : TerminalFlowQapGenerationFinalizationId
            proofRef : uint32 option
            reducerSequence : int64
        }

        let private terminalFlowQapGenerationFinalize
            reducerSequence
            (resolution:TerminalFlowQapResolutionBox)
            (authority:TerminalFlowQapGenerationAuthority) =
            let (TerminalFlowQapGenerationId generationValue) = authority.generation
            let attemptReceiptRef =
                terminalFlowMintedRefOf
                    "qap_finalization_attempt_receipt_ref"
                    (FastRuntimeFormat.format "%d|%d|%u" [| box reducerSequence; box generationValue; box (terminalFlowQapResolutionBoxRef resolution) |])
            let stageAfter, disposition, result, proofRef =
                match resolution with
                | TerminalFlowQapMaterialProgressBox _ ->
                    TerminalFlowQapGenerationProgressing,
                    TerminalFlowQapFinalizerContinueProgress,
                    TerminalFlowQapFinalizationProgressed attemptReceiptRef,
                    None
                | TerminalFlowQapFullyDrainedBox(_, proof) ->
                    let proofRef = uint32 (terminalFlowQapProtocolIdValue proof.proofRef)
                    TerminalFlowQapGenerationDrained,
                    TerminalFlowQapFinalizerSealDrained,
                    TerminalFlowQapFinalizationFullyDrained proofRef,
                    Some proofRef
                | TerminalFlowQapProvenDeadlockBox(_, proof) ->
                    let proofRef = uint32 (terminalFlowQapProtocolIdValue proof.proofRef)
                    TerminalFlowQapGenerationDeadlocked,
                    TerminalFlowQapFinalizerSealDeadlock,
                    TerminalFlowQapFinalizationProvenDeadlock proofRef,
                    Some proofRef
            let stageAfter, disposition, result, proofRef, receiptRef =
                match authority.stage, authority.finalization with
                | TerminalFlowQapGenerationDrained, Some (TerminalFlowQapFinalizationFullyDrained existing) ->
                    TerminalFlowQapGenerationDrained,
                    TerminalFlowQapFinalizerSealDrained,
                    TerminalFlowQapFinalizationFullyDrained existing,
                    Some existing,
                    existing
                | TerminalFlowQapGenerationDeadlocked, Some (TerminalFlowQapFinalizationProvenDeadlock existing) ->
                    TerminalFlowQapGenerationDeadlocked,
                    TerminalFlowQapFinalizerSealDeadlock,
                    TerminalFlowQapFinalizationProvenDeadlock existing,
                    Some existing,
                    existing
                | _ -> stageAfter, disposition, result, proofRef, (proofRef |> Option.defaultValue attemptReceiptRef)
            let finalized =
                { authority with
                    stage = stageAfter
                    finalization = Some result
                    finalizationReceiptRef = Some receiptRef }
            finalized,
            { attemptReceiptRef = attemptReceiptRef
              generation = authority.generation
              stageBefore = authority.stage
              stageAfter = stageAfter
              disposition = disposition
              result = result
              proofRef = proofRef
              reducerSequence = reducerSequence }

        type TerminalFlowQapFinalOutcomeDispatchBlockerId =
            | TerminalFlowQapDispatchMissingAcceptedProgressEvidence
            | TerminalFlowQapDispatchRejectedProgressEvidencePresent
            | TerminalFlowQapDispatchMissingGreenPathCertificate
            | TerminalFlowQapDispatchMissingPendingTerminal

        type TerminalFlowQapFinalOutcomeDispatchDecision = Result<unit, TerminalFlowQapFinalOutcomeDispatchBlockerId list>

        let private terminalFlowQapFinalOutcomeDispatchBlockerText (blocker:TerminalFlowQapFinalOutcomeDispatchBlockerId) =
            match blocker with
            | TerminalFlowQapDispatchMissingAcceptedProgressEvidence -> "missing_accepted_progress_evidence"
            | TerminalFlowQapDispatchRejectedProgressEvidencePresent -> "rejected_progress_evidence_present"
            | TerminalFlowQapDispatchMissingGreenPathCertificate -> "missing_green_path_certificate"
            | TerminalFlowQapDispatchMissingPendingTerminal -> "missing_pending_terminal"

        let private terminalFlowQapFinalOutcomeDispatchBlockerListText separator (blockers:TerminalFlowQapFinalOutcomeDispatchBlockerId list) =
            blockers
            |> List.map terminalFlowQapFinalOutcomeDispatchBlockerText
            |> String.concat separator

        let private terminalFlowQapFinalOutcomeDispatchDecisionText = function
            | Ok () -> "ready"
            | Error blockers ->
                terminalFlowQapFinalOutcomeDispatchBlockerListText "," blockers
                |> fun text -> "blocked(" + text + ")"

        let private terminalFlowQapFinalOutcomeDispatchDecisionFor accepted rejected greenPath (pendingTerminal:TerminalFlowPendingSlot) : TerminalFlowQapFinalOutcomeDispatchDecision =
            [ if Option.isNone accepted then
                  TerminalFlowQapDispatchMissingAcceptedProgressEvidence
              if Option.isSome rejected then
                  TerminalFlowQapDispatchRejectedProgressEvidencePresent
              if Option.isNone greenPath then
                  TerminalFlowQapDispatchMissingGreenPathCertificate
              if terminalFlowPendingSlotIsAbsent pendingTerminal then
                  TerminalFlowQapDispatchMissingPendingTerminal ]
            |> function
                | [] -> Ok ()
                | blockers -> Error blockers

        type TerminalFlowQapWatchRebaseRequest = private {
            fixpointRef : TerminalFlowDurableRef<TerminalFlowQapFixpointReceiptRefKind>
            parentGeneration : TerminalFlowQapGenerationId<TerminalFlowQapGenerationRefKind>
            childGeneration : TerminalFlowQapGenerationId<TerminalFlowQapGenerationRefKind>
            reason : TerminalFlowQapRebaseReasonId
            relationDelta : TerminalFlowQapRelationGenerationDelta
            stageBefore : TerminalFlowQapGenerationStageId
            stageAfter : TerminalFlowQapGenerationStageId
            fromSemanticEpoch : int64
            toSemanticEpoch : int64
            fromFrontierEpoch : int64
            toFrontierEpoch : int64
            frontierProgressBp : int64
            fromCompletionEpoch : int64
            toCompletionEpoch : int64
            completedCost : int64
            fromOperationalRevision : int64
            toOperationalRevision : int64
            operationalSnapshotRef : CompilerIdentityKernel.ContentDigest
            requestRef : uint32
            rebaseReceiptRef : uint32
        }

        type TerminalFlowQapWatchRebaseAdmissionId =
            | TerminalFlowQapWatchRebaseAdmitted of requestRef:uint32
            | TerminalFlowQapWatchRebaseCoalesced of existingRequestRef:uint32

        let private terminalFlowQapWatchRebaseAdmissionText = function
            | TerminalFlowQapWatchRebaseAdmitted requestRef ->
                sprintf "QapWatchRebaseAdmission(Admitted|request_ref=%u)" requestRef
            | TerminalFlowQapWatchRebaseCoalesced existingRequestRef ->
                sprintf "QapWatchRebaseAdmission(Coalesced|existing_request_ref=%u)" existingRequestRef

        type TerminalFlowQapReducerWitnessAuthority =
            | TerminalFlowQapWitnessActorArmed
            | TerminalFlowQapWitnessRootResolvedStableReducer
            | TerminalFlowQapWitnessBlockedBeforeRoot

        let private terminalFlowQapReducerWitnessAuthorityText = function
            | TerminalFlowQapWitnessActorArmed -> "actor_armed"
            | TerminalFlowQapWitnessRootResolvedStableReducer -> "root_resolved_stable_reducer"
            | TerminalFlowQapWitnessBlockedBeforeRoot -> "blocked_before_root"

        let private terminalFlowQapReducerWitnessAuthorityCanPublish = function
            | TerminalFlowQapWitnessActorArmed
            | TerminalFlowQapWitnessRootResolvedStableReducer -> true
            | TerminalFlowQapWitnessBlockedBeforeRoot -> false

        let private terminalFlowQapWatchClockVerdictText = function
            | TerminalFlowQapWatchRebaseMaterialFrontier -> "rebase_material_frontier"
            | TerminalFlowQapWatchRebaseMaterialSemantic -> "rebase_material_semantic"
            | TerminalFlowQapWatchRebaseMaterialCompletion -> "rebase_material_completion"
            | TerminalFlowQapWatchHoldProceduralClockChurn -> "hold_procedural_clock_churn"
            | TerminalFlowQapWatchClockStable -> "clock_stable"

        let private terminalFlowQapWatchIsAwaiting = function
            | TerminalFlowQapWatchAwaitingWitness -> true
            | TerminalFlowQapWatchWitnessedByReducer -> false

        [<NoComparison>]
        type TerminalFlowGlobalQapMaturityWatch = private {
            fixpointRef : TerminalFlowDurableRef<TerminalFlowQapFixpointReceiptRefKind>
            fixpoint : TerminalFlowQapFixpointSet
            generationAuthority : TerminalFlowQapGenerationAuthority
            observedMaterialAgeMs : int64
            observedSemanticEpoch : int64
            observedFrontierEpoch : int64
            observedFrontierProgressBp : int64
            observedCompletionEpoch : int64
            observedCompletedCost : int64
            observedAtMs : int64
            rebaseCount : int64
            completionRebaseCount : int64
            maturity : TerminalFlowQapWatchMaturity
        }

        let private terminalFlowQapGenerationValue (TerminalFlowQapGenerationId value) = value

        let private terminalFlowQapGenerationOfFixpointRef fixpointRef =
            TerminalFlowQapGenerationId(uint64 (terminalFlowDurableRefValue fixpointRef))

        let private terminalFlowQapGenerationNext generation =
            TerminalFlowQapGenerationId(terminalFlowQapGenerationValue generation + 1UL)

        let private terminalFlowQapGenerationStageText = function
            | TerminalFlowQapGenerationAwaiting -> "Awaiting"
            | TerminalFlowQapGenerationProgressing -> "Progressing"
            | TerminalFlowQapGenerationDrained -> "Drained"
            | TerminalFlowQapGenerationDeadlocked -> "Deadlocked"

        let private terminalFlowQapGenerationAllowsRebase = function
            | TerminalFlowQapGenerationAwaiting
            | TerminalFlowQapGenerationProgressing -> true
            | TerminalFlowQapGenerationDrained
            | TerminalFlowQapGenerationDeadlocked -> false

        let private terminalFlowQapGenerationFinalizationText = function
            | None -> "NotAttempted"
            | Some (TerminalFlowQapFinalizationProgressed receiptRef) -> sprintf "Progressed(receipt=%u)" receiptRef
            | Some (TerminalFlowQapFinalizationFullyDrained proofRef) -> sprintf "FullyDrained(proof=%u)" proofRef
            | Some (TerminalFlowQapFinalizationProvenDeadlock proofRef) -> sprintf "ProvenDeadlock(proof=%u)" proofRef

        let private terminalFlowQapRebaseReasonText = function
            | TerminalFlowQapRebaseFrontierRetired -> "frontier_retired"
            | TerminalFlowQapRebaseSemanticAndCompletionRetired -> "semantic_and_completion_retired"
            | TerminalFlowQapRebaseCompletionRetired -> "completion_retired"
            | TerminalFlowQapRebaseRelationSetDiscovered -> "relation_set_discovered"
            | TerminalFlowQapRebaseFinalizerDeferred -> "finalizer_deferred"
            | TerminalFlowQapRebaseSemanticDrainRequested -> "semantic_drain_requested"
            | TerminalFlowQapRebaseSemanticDrainCompleted -> "semantic_drain_completed"
            | TerminalFlowQapRebaseHostShutdownReconcile -> "host_shutdown_reconcile"

        let private terminalFlowQapFixpointRelationRefs (fixpoint:TerminalFlowQapFixpointSet) =
            fixpoint.items
            |> List.map (fun item -> terminalFlowMintedRefOf "qap_relation_generation_ref" (terminalFlowQapRelationText item.relation))
            |> List.distinct
            |> List.toArray

        let private terminalFlowQapFixpointRelationSetHash (fixpoint:TerminalFlowQapFixpointSet) =
            let refs = terminalFlowQapFixpointRelationRefs fixpoint
            terminalFlowMintedRefOf "qap_relation_set_hash" (refs |> Array.map string |> String.concat ":")

        let private terminalFlowQapRebaseReasonFor
            (watch:TerminalFlowGlobalQapMaturityWatch)
            semanticEpochNow
            frontierEpochNow
            completionEpochNow =
            let semanticAdvanced = semanticEpochNow > watch.observedSemanticEpoch
            let frontierAdvanced = frontierEpochNow > watch.observedFrontierEpoch
            let completionAdvanced = completionEpochNow > watch.observedCompletionEpoch
            if semanticAdvanced && frontierAdvanced then TerminalFlowQapRebaseFrontierRetired
            elif semanticAdvanced && completionAdvanced then TerminalFlowQapRebaseSemanticAndCompletionRetired
            elif completionAdvanced then TerminalFlowQapRebaseCompletionRetired
            else TerminalFlowQapRebaseRelationSetDiscovered

        let private terminalFlowQapWatchRebaseRequestFor
            (reasonOverride:TerminalFlowQapRebaseReasonId option)
            (watch:TerminalFlowGlobalQapMaturityWatch)
            semanticEpochNow
            frontierEpochNow
            frontierProgressBpNow
            completionEpochNow
            completedCostNow =
            let parentGeneration = watch.generationAuthority.generation
            let childGeneration = terminalFlowQapGenerationNext parentGeneration
            let operationalSnapshot = terminalFlowOperationalAuthoritySnapshotNow ()
            let fromOperationalRevision = watch.generationAuthority.operationalRevision
            let toOperationalRevision =
                CompilerKernelV2.OperationalAuthoritySnapshotOps.graphRevision operationalSnapshot
            let operationalSnapshotRef =
                CompilerKernelV2.OperationalAuthoritySnapshotOps.snapshotRef operationalSnapshot
            let relationRefs = terminalFlowQapFixpointRelationRefs watch.fixpoint
            let parentRelationSetHash = watch.generationAuthority.relationSetHash
            let relationDelta =
                { parentRelationSetHash = parentRelationSetHash
                  childRelationSetHash = parentRelationSetHash
                  carriedRelationRefs = relationRefs
                  invalidatedRelationRefs = [||]
                  discoveredRelationRefs = [||]
                  rediscoveryRequired = true }
            let reason =
                match reasonOverride with
                | Some explicitReason -> explicitReason
                | None -> terminalFlowQapRebaseReasonFor watch semanticEpochNow frontierEpochNow completionEpochNow
            let requestRef =
                terminalFlowMintedRefOf
                    "qap_watch_rebase_request_ref"
                    (FastRuntimeFormat.format "%u|%d|%d|%d|%d|%d|%d|%d|%d|%d|%d|%d|%d|%s" [| box (terminalFlowDurableRefValue watch.fixpointRef); box (terminalFlowQapGenerationValue parentGeneration); box (terminalFlowQapGenerationValue childGeneration); box watch.observedSemanticEpoch; box semanticEpochNow; box watch.observedFrontierEpoch; box frontierEpochNow; box frontierProgressBpNow; box watch.observedCompletionEpoch; box completionEpochNow; box completedCostNow; box fromOperationalRevision; box toOperationalRevision; box (CompilerIdentityKernel.ContentDigest.text operationalSnapshotRef) |])
            let rebaseReceiptRef =
                terminalFlowMintedRefOf
                    "qap_rebase_receipt_ref"
                    (FastRuntimeFormat.format "%u|%d|%d|%s|%u|%d|%d|%s" [| box requestRef; box (terminalFlowQapGenerationValue parentGeneration); box (terminalFlowQapGenerationValue childGeneration); box (terminalFlowQapRebaseReasonText reason); box parentRelationSetHash; box fromOperationalRevision; box toOperationalRevision; box (CompilerIdentityKernel.ContentDigest.text operationalSnapshotRef) |])
            { fixpointRef = watch.fixpointRef
              parentGeneration = parentGeneration
              childGeneration = childGeneration
              reason = reason
              relationDelta = relationDelta
              stageBefore = watch.generationAuthority.stage
              stageAfter = TerminalFlowQapGenerationAwaiting
              fromSemanticEpoch = watch.observedSemanticEpoch
              toSemanticEpoch = semanticEpochNow
              fromFrontierEpoch = watch.observedFrontierEpoch
              toFrontierEpoch = frontierEpochNow
              frontierProgressBp = frontierProgressBpNow
              fromCompletionEpoch = watch.observedCompletionEpoch
              toCompletionEpoch = completionEpochNow
              completedCost = completedCostNow
              fromOperationalRevision = fromOperationalRevision
              toOperationalRevision = toOperationalRevision
              operationalSnapshotRef = operationalSnapshotRef
              requestRef = requestRef
              rebaseReceiptRef = rebaseReceiptRef }

        let private terminalFlowQapWatchRebaseFlightGate = obj()
        let mutable private terminalFlowQapWatchRebaseFlight : TerminalFlowQapWatchRebaseRequest option = None

        let private terminalFlowQapWatchRebaseAdmit (request:TerminalFlowQapWatchRebaseRequest) =
            lock terminalFlowQapWatchRebaseFlightGate (fun () ->
                match terminalFlowQapWatchRebaseFlight with
                | None ->
                    terminalFlowQapWatchRebaseFlight <- Some request
                    TerminalFlowQapWatchRebaseAdmitted request.requestRef
                | Some existing ->
                    TerminalFlowQapWatchRebaseCoalesced existing.requestRef)

        let private terminalFlowQapWatchRebaseRelease (request:TerminalFlowQapWatchRebaseRequest) =
            lock terminalFlowQapWatchRebaseFlightGate (fun () ->
                match terminalFlowQapWatchRebaseFlight with
                | Some existing when existing.requestRef = request.requestRef ->
                    terminalFlowQapWatchRebaseFlight <- None
                    true
                | _ -> false)

        let private terminalFlowQapWatchRebaseInFlight () =
            lock terminalFlowQapWatchRebaseFlightGate (fun () -> terminalFlowQapWatchRebaseFlight.IsSome)

        let private terminalFlowQapWatchClockVerdictFor
            materialCompletionCostThreshold
            completionRebaseCap
            (watch:TerminalFlowGlobalQapMaturityWatch)
            semanticEpochNow
            frontierEpochNow
            frontierProgressBpNow
            completionEpochNow
            completedCostNow =
            let semanticEpochAdvanced =
                semanticEpochNow > watch.observedSemanticEpoch
            let frontierRetirementAdvanced =
                frontierEpochNow > watch.observedFrontierEpoch
                && frontierProgressBpNow > watch.observedFrontierProgressBp
            let completionCostDelta = max 0L (completedCostNow - watch.observedCompletedCost)
            let completionRetirementAdvanced =
                completionEpochNow > watch.observedCompletionEpoch
                && completionCostDelta >= materialCompletionCostThreshold
                && watch.completionRebaseCount < completionRebaseCap
            // MIGRATION: a semantic receipt is not by itself proof that the compiler
            // retired any work. Rebase QAP maturity only when semantic authority and
            // a monotone retirement clock advance together. Fact-only replay churn is
            // held as evidence and must pass through the completion fence instead of
            // resetting the positive-stasis window forever.
            let frontierMaterialAdvanced =
                semanticEpochAdvanced && frontierRetirementAdvanced
            let completionMaterialAdvanced =
                semanticEpochAdvanced && completionRetirementAdvanced
            let anyClockAdvanced =
                semanticEpochAdvanced
                || frontierEpochNow > watch.observedFrontierEpoch
                || completionEpochNow > watch.observedCompletionEpoch
            if frontierMaterialAdvanced then TerminalFlowQapWatchRebaseMaterialFrontier
            elif completionMaterialAdvanced then TerminalFlowQapWatchRebaseMaterialCompletion
            elif anyClockAdvanced then TerminalFlowQapWatchHoldProceduralClockChurn
            else TerminalFlowQapWatchClockStable

        let private terminalFlowQapWatchClockVerdictRequiresRebase = function
            | TerminalFlowQapWatchRebaseMaterialFrontier
            | TerminalFlowQapWatchRebaseMaterialSemantic
            | TerminalFlowQapWatchRebaseMaterialCompletion -> true
            | TerminalFlowQapWatchHoldProceduralClockChurn
            | TerminalFlowQapWatchClockStable -> false

        type TerminalFlowQapMaturityObservation =
            | TerminalFlowQapMaturityCandidateObserved
            | TerminalFlowQapMaturityWitnessedByReducer

        let private terminalFlowQapMaturityObservationText = function
            | TerminalFlowQapMaturityCandidateObserved -> "candidate_observed"
            | TerminalFlowQapMaturityWitnessedByReducer -> "witnessed_by_reducer_exact_closed_world"

        let private terminalFlowQapMaturityObservationIsAuthoritative = function
            | TerminalFlowQapMaturityCandidateObserved -> false
            | TerminalFlowQapMaturityWitnessedByReducer -> true

        // Domain migration : submission and installation are distinct states.
        // The reducer owns the only installation transition and telemetry reads
        // this value instead of emitting a painted boolean literal.
        type TerminalFlowOutcomeInstallPath =
            | TerminalFlowOutcomeInstallFromEvaluatorNotice
            | TerminalFlowOutcomeInstallFromSafetyWatchdog
            | TerminalFlowOutcomeInstallFromReducerOwnerDebt
            | TerminalFlowOutcomeInstallFromQapFinalization

        let private terminalFlowOutcomeInstallPathText = function
            | TerminalFlowOutcomeInstallFromEvaluatorNotice -> "evaluator_notice"
            | TerminalFlowOutcomeInstallFromSafetyWatchdog -> "safety_watchdog"
            | TerminalFlowOutcomeInstallFromReducerOwnerDebt -> "reducer_owner_debt"
            | TerminalFlowOutcomeInstallFromQapFinalization -> "qap_finalization"

        let private terminalFlowPendingAdmissionInstallPath = function
            | TerminalFlowPendingAdmissionEvaluatorNotice _ -> TerminalFlowOutcomeInstallFromEvaluatorNotice
            | TerminalFlowPendingAdmissionSafetyWatchdog _ -> TerminalFlowOutcomeInstallFromSafetyWatchdog
            | TerminalFlowPendingAdmissionReducerOwnerDebt _ -> TerminalFlowOutcomeInstallFromReducerOwnerDebt

        // Admission identity is minted at pending-candidate creation above and then
        // threaded through install, actor binding, dispatch, order registration and consume.
        type TerminalFlowOutcomeAdmission = private {
            identity : TerminalFlowAdmissionIdentity
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            fillKey : TerminalFlowFillKeyId
            installPath : TerminalFlowOutcomeInstallPath
        }

        let private terminalFlowOutcomeAdmissionForIdentityRefs
            (terminalReceiptRef:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>)
            (fillKey:TerminalFlowFillKeyId)
            identity
            installPath = {
            identity = identity
            terminalReceiptRef = terminalReceiptRef
            fillKey = fillKey
            installPath = installPath
        }

        let private terminalFlowOutcomeAdmissionForIdentity terminalReceiptId fillKey identity installPath =
            terminalFlowOutcomeAdmissionForIdentityRefs
                (terminalFlowIdentityRefOfText terminalReceiptId)
                (TerminalFlowFillKeyId.create fillKey)
                identity
                installPath

        type TerminalFlowOutcomeActorBinding = private {
            identity : TerminalFlowAdmissionIdentity
            bindingReceiptRef : uint32
            actorRef : uint32
            fillRef : uint32
            boundAtSequence : int64
            boundAtMs : int64
        }

        let private terminalFlowOutcomeActorBindingFor (admission:TerminalFlowOutcomeAdmission) reducerSequence : TerminalFlowOutcomeActorBinding =
            { identity = admission.identity
              bindingReceiptRef = terminalFlowAdmissionActorBindingRef admission.identity
              actorRef = terminalFlowAdmissionActorRef admission.identity
              fillRef = TerminalFlowFillKeyId.digest admission.fillKey
              boundAtSequence = reducerSequence
              boundAtMs = Environment.TickCount64 }

        type TerminalFlowOutcomeInstallation =
            | TerminalFlowOutcomeNotInstalled
            | TerminalFlowOutcomeInstalled of admission:TerminalFlowOutcomeAdmission * installationRef:TerminalFlowIdentityRef<TerminalFlowOutcomeInstallationRefKind> * actorBinding:TerminalFlowOutcomeActorBinding * installedAtSequence:int64
            | TerminalFlowOutcomeConsumeEnqueued of admission:TerminalFlowOutcomeAdmission * installationRef:TerminalFlowIdentityRef<TerminalFlowOutcomeInstallationRefKind> * actorBinding:TerminalFlowOutcomeActorBinding * consumeRef:TerminalFlowIdentityRef<TerminalFlowOutcomeConsumeRefKind> * enqueuedAtSequence:int64

        type TerminalFlowOutcomeInstallTransition =
            | TerminalFlowOutcomeInstallAccepted of TerminalFlowOutcomeInstallation
            | TerminalFlowOutcomeInstallDuplicateSuppressed of existing:TerminalFlowOutcomeInstallation * payloadMismatch:bool
            | TerminalFlowOutcomeInstallIdentityRefreshed of previous:TerminalFlowOutcomeInstallation * refreshed:TerminalFlowOutcomeInstallation

        let private terminalFlowOutcomeInstallationAdmission (installation:TerminalFlowOutcomeInstallation) : TerminalFlowOutcomeAdmission option =
            match installation with
            | TerminalFlowOutcomeInstalled(admission, _, _, _)
            | TerminalFlowOutcomeConsumeEnqueued(admission, _, _, _, _) -> Some admission
            | TerminalFlowOutcomeNotInstalled -> None

        let private terminalFlowOutcomeInstallationActorBinding (installation:TerminalFlowOutcomeInstallation) : TerminalFlowOutcomeActorBinding option =
            match installation with
            | TerminalFlowOutcomeInstalled(_, _, actorBinding, _)
            | TerminalFlowOutcomeConsumeEnqueued(_, _, actorBinding, _, _) -> Some actorBinding
            | TerminalFlowOutcomeNotInstalled -> None

        let private terminalFlowOutcomeInstallationSequence = function
            | TerminalFlowOutcomeInstalled(_, _, _, installedAtSequence) -> Some installedAtSequence
            | TerminalFlowOutcomeConsumeEnqueued(_, _, _, _, enqueuedAtSequence) -> Some enqueuedAtSequence
            | TerminalFlowOutcomeNotInstalled -> None

        let private terminalFlowOutcomeInstallationFairnessEpoch nowMs installation =
            terminalFlowOutcomeInstallationAdmission installation
            |> Option.map (fun admission -> terminalFlowAdmissionFairnessEpochForIdentity admission.identity nowMs)

        let private terminalFlowPendingSlotFairnessEpoch nowMs pendingSlot =
            match pendingSlot with
            | TerminalFlowPendingSlotCandidate pending when terminalFlowPendingDispatchIsExecutable pending.dispatchAuthority ->
                Some (terminalFlowAdmissionFairnessEpochForIdentity pending.admissionIdentity nowMs)
            | _ -> None

        let private terminalFlowOutcomeInstallationFor (admission:TerminalFlowOutcomeAdmission) reducerSequence =
            let installationRef : TerminalFlowIdentityRef<TerminalFlowOutcomeInstallationRefKind> =
                terminalFlowIdentityRefOfText (
                    FastRuntimeFormat.format "terminal-outcome-install:%u:%u:%u:%s" [| box (terminalFlowAdmissionRawRef admission.identity); box (terminalFlowIdentityRefDigest admission.terminalReceiptRef); box (TerminalFlowFillKeyId.digest admission.fillKey); box (terminalFlowOutcomeInstallPathText admission.installPath) |])
            let actorBinding = terminalFlowOutcomeActorBindingFor admission reducerSequence
            TerminalFlowOutcomeInstalled(admission, installationRef, actorBinding, reducerSequence)

        let private terminalFlowOutcomeInstallTransitionFor (current:TerminalFlowOutcomeInstallation) (admission:TerminalFlowOutcomeAdmission) reducerSequence : TerminalFlowOutcomeInstallTransition =
            match terminalFlowOutcomeInstallationAdmission current with
            | Some existing ->
                let sameIdentity = terminalFlowAdmissionIdentitySame existing.identity admission.identity
                let samePayload = existing.terminalReceiptRef = admission.terminalReceiptRef && existing.fillKey = admission.fillKey && existing.installPath = admission.installPath
                if sameIdentity && samePayload then
                    TerminalFlowOutcomeInstallDuplicateSuppressed(current, false)
                elif samePayload then
                    TerminalFlowOutcomeInstallIdentityRefreshed(current, terminalFlowOutcomeInstallationFor admission reducerSequence)
                elif sameIdentity then
                    TerminalFlowOutcomeInstallIdentityRefreshed(current, terminalFlowOutcomeInstallationFor admission reducerSequence)
                else
                    TerminalFlowOutcomeInstallAccepted(terminalFlowOutcomeInstallationFor admission reducerSequence)
            | None ->
                TerminalFlowOutcomeInstallAccepted(terminalFlowOutcomeInstallationFor admission reducerSequence)

        let private terminalFlowOutcomeInstallTransitionState = function
            | TerminalFlowOutcomeInstallAccepted installation -> installation
            | TerminalFlowOutcomeInstallIdentityRefreshed(_, refreshed) -> refreshed
            | TerminalFlowOutcomeInstallDuplicateSuppressed(existing, _) -> existing

        let private terminalFlowOutcomeInstallTransitionIsNew = function
            | TerminalFlowOutcomeInstallAccepted _
            | TerminalFlowOutcomeInstallIdentityRefreshed _ -> true
            | TerminalFlowOutcomeInstallDuplicateSuppressed _ -> false

        let private terminalFlowOutcomeMarkConsumeEnqueued tokenId reducerSequence = function
            | TerminalFlowOutcomeInstalled(admission, installationRef, actorBinding, _) ->
                let consumeRef : TerminalFlowIdentityRef<TerminalFlowOutcomeConsumeRefKind> =
                    terminalFlowIdentityRefOfText (sprintf "terminal-outcome-consume:%u:%s" (terminalFlowAdmissionRawRef admission.identity) tokenId)
                TerminalFlowOutcomeConsumeEnqueued(admission, installationRef, actorBinding, consumeRef, reducerSequence)
            | installation -> installation

        let private terminalFlowOutcomeInstallationText = function
            | TerminalFlowOutcomeNotInstalled -> "not_installed"
            | TerminalFlowOutcomeInstalled(admission, installationRef, actorBinding, installedAtSequence) ->
                FastRuntimeFormat.format "installed:terminal_ref=%u:fill_ref=%u:admission_ref=%u:admission_identity_ref=%u:installation_ref=%u:bound_actor_ref=%u:actor_binding_ref=%u:requirement_ledger_ref=%u:path=%s:reducer_sequence=%d" [| box (terminalFlowIdentityRefDigest admission.terminalReceiptRef); box (TerminalFlowFillKeyId.digest admission.fillKey); box (terminalFlowAdmissionRawRef admission.identity); box (terminalFlowAdmissionIdentityRef admission.identity); box (terminalFlowIdentityRefDigest installationRef); box actorBinding.actorRef; box actorBinding.bindingReceiptRef; box (terminalFlowAdmissionRequirementLedgerRef admission.identity); box (terminalFlowOutcomeInstallPathText admission.installPath); box installedAtSequence |]
            | TerminalFlowOutcomeConsumeEnqueued(admission, installationRef, actorBinding, consumeRef, enqueuedAtSequence) ->
                FastRuntimeFormat.format "consume_enqueued:terminal_ref=%u:fill_ref=%u:admission_ref=%u:admission_identity_ref=%u:installation_ref=%u:bound_actor_ref=%u:actor_binding_ref=%u:requirement_ledger_ref=%u:consume_ref=%u:path=%s:reducer_sequence=%d" [| box (terminalFlowIdentityRefDigest admission.terminalReceiptRef); box (TerminalFlowFillKeyId.digest admission.fillKey); box (terminalFlowAdmissionRawRef admission.identity); box (terminalFlowAdmissionIdentityRef admission.identity); box (terminalFlowIdentityRefDigest installationRef); box actorBinding.actorRef; box actorBinding.bindingReceiptRef; box (terminalFlowAdmissionRequirementLedgerRef admission.identity); box (terminalFlowIdentityRefDigest consumeRef); box (terminalFlowOutcomeInstallPathText admission.installPath); box enqueuedAtSequence |]

        let private terminalFlowOutcomeInstallationIsInstalled = function
            | TerminalFlowOutcomeInstalled _
            | TerminalFlowOutcomeConsumeEnqueued _ -> true
            | TerminalFlowOutcomeNotInstalled -> false

        // MIGRATION / destructive domain migration rounds 1-2 of 5.
        // Round 1 made dispatch legality a reducer-owned phantom constitution.
        // Round 2 makes issuance and consume authorization linear values.  The
        // production interpreter no longer accepts a Ready constitution or a naked
        // stage token: it receives an Issued capability, then a consume capability
        // whose lineage owns fairness, recovery, green-path and total-order evidence.
        type TerminalFlowDispatchConstitutionReadyStage = class end
        type TerminalFlowDispatchConstitutionIssuedStage = class end
        type TerminalFlowDispatchConsumeAuthorizedStage = class end

        type TerminalFlowDispatchCredentialBundle<'Stage> = private {
            bundleDigest : CompilerIdentityKernel.ContentDigest
        }
        with
            member this.bundleRef =
                terminalFlowMintedRefOf
                    "dispatch_credential_bundle_projection_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.bundleDigest)
            member this.exactOnceRef =
                terminalFlowMintedRefOf
                    "dispatch_credential_bundle_projection_exact_once_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.bundleDigest)

        // Destructive migration round 3: dispatch issuance carries an erased view
        // of the recursive admission proof, not a bag of copied authority refs.
        // Legacy numeric fields are projection-only members and cannot be mutated
        // independently from the typed evidence that produced them.
        type TerminalFlowDispatchAdmissionErasure<'Stage> = private {
            admissionIdentity : TerminalFlowAdmissionIdentity
            rootReceiptRef : TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            fillKey : TerminalFlowFillKeyId
            credentialGraph : TerminalFlowSchedulerGraphClosedReceipt
            greenPathDispatchReceipt : TerminalFlowGreenPathReceipt<TerminalFlowGreenPathDispatchReadyStage>
            installationRef : TerminalFlowIdentityRef<TerminalFlowOutcomeInstallationRefKind>
            totalOrderAwaitDispatch : TerminalFlowTotalOrderReceipt<TerminalOrderAwaitDispatchStage>
            pendingTerminal : TerminalFlowSchedulerWitness<TerminalFlowDispatchPendingTerminalWitnessKind>
            proofDigest : CompilerIdentityKernel.ContentDigest
            readyAtRevision : int64
        }
        with
            member this.rootRef = terminalFlowIdentityRefDigest this.rootReceiptRef
            member this.terminalRef = terminalFlowIdentityRefDigest this.terminalReceiptRef
            member this.fillRef = TerminalFlowFillKeyId.digest this.fillKey
            member this.admissionRef = terminalFlowAdmissionRawRef this.admissionIdentity
            member this.admissionIdentityRef = terminalFlowAdmissionIdentityRef this.admissionIdentity
            member this.actorBindingRef = terminalFlowAdmissionActorBindingRef this.admissionIdentity
            member this.credentialLedgerRef = terminalFlowAdmissionRequirementLedgerRef this.admissionIdentity
            member this.credentialGraphClosureRef = this.credentialGraph.closureRef
            member this.pendingTerminalRef = terminalFlowSchedulerWitnessSourceRef this.pendingTerminal
            member this.constitutionRef =
                terminalFlowMintedRefOf
                    "dispatch_admission_erasure_projection_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.proofDigest)
            member this.exactOnceRef =
                terminalFlowMintedRefOf
                    "dispatch_admission_erasure_projection_exact_once_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.proofDigest)

        // Transitional alias: old consumers may still say constitution, but the
        // representable state is now the typed admission erasure above.
        type TerminalFlowDispatchConstitution<'Stage> = TerminalFlowDispatchAdmissionErasure<'Stage>

        type TerminalFlowDispatchIssuance<'Stage> = private {
            admission : TerminalFlowDispatchAdmissionErasure<TerminalFlowDispatchConstitutionReadyStage>
            request : TerminalFlowGlobalDispatchRequest
            credentials : TerminalFlowDispatchCredentialBundle<TerminalFlowDispatchConstitutionIssuedStage>
            issuanceDigest : CompilerIdentityKernel.ContentDigest
            issuedAtRevision : int64
        }
        with
            // Diagnostic compatibility only. There is no separately stored
            // constitution capable of diverging from the sealed admission.
            member this.constitution = this.admission
            member this.requestRef = this.request.requestRef
            member this.issuanceRef =
                terminalFlowMintedRefOf
                    "dispatch_issuance_projection_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.issuanceDigest)
            member this.exactOnceRef =
                terminalFlowMintedRefOf
                    "dispatch_issuance_projection_exact_once_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.issuanceDigest)

        type TerminalFlowDispatchConsumeTokenWitnessKind = class end

        type TerminalFlowDispatchConsumeAuthorization<'Stage> = private {
            issuance : TerminalFlowDispatchIssuance<TerminalFlowDispatchConstitutionIssuedStage>
            ratifiedHandoff : TerminalFlowNativeHandoffId
            token : TerminalFlowSchedulerWitness<TerminalFlowDispatchConsumeTokenWitnessKind>
            pendingTerminal : TerminalFlowSchedulerWitness<TerminalFlowDispatchPendingTerminalWitnessKind>
            authorizationDigest : CompilerIdentityKernel.ContentDigest
            authorizedAtRevision : int64
        }
        with
            member this.tokenRef = terminalFlowSchedulerWitnessRef this.token
            member this.pendingTerminalRef = terminalFlowSchedulerWitnessSourceRef this.pendingTerminal
            member this.consumeAuthorityRef =
                terminalFlowMintedRefOf
                    "dispatch_consume_authority_projection_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.authorizationDigest)
            member this.exactOnceRef =
                terminalFlowMintedRefOf
                    "dispatch_consume_authority_projection_exact_once_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.authorizationDigest)

        // MIGRATION BONUS BREAKTHROUGH: refs in the terminal authority corridor
        // are now derived from a typed identity DU rather than formatted strings.
        // Strings remain diagnostic sinks; they no longer define capability or
        // affine-transaction authority.
        type private TerminalFlowStableAuthorityIdentity =
            | TerminalFlowAppliedPendingLineageIdentity of
                capturedPendingRef:uint32 * currentPendingRef:uint32 * installedAdmissionIdentityRef:uint32 *
                protocolAuthorityRef:uint32 * transactionRef:uint32 * postCommitExactOnceRef:uint32
            | TerminalFlowAppliedCapabilityWithLineageIdentity of
                planRef:uint32 * finalizationTransactionRef:uint32 * finalizationExactOnceRef:uint32 *
                postCommitExactOnceRef:uint32 * qapProofRef:uint32 * qapProofExactOnceRef:uint32 *
                lineageProofRef:uint32 * pendingTerminalRef:uint32 * terminalRef:uint32 * fillRef:uint32 *
                admissionRef:uint32 * admissionIdentityRef:uint32
            | TerminalFlowAppliedCapabilityExactOnceWithLineageIdentity of
                capabilityRef:uint32 * qapProofRef:uint32 * qapProofExactOnceRef:uint32 *
                lineageProofRef:uint32 * finalizationExactOnceRef:uint32 * postCommitExactOnceRef:uint32 *
                pendingTerminalRef:uint32 * terminalRef:uint32 * fillRef:uint32 * admissionRef:uint32 * admissionIdentityRef:uint32
            | TerminalFlowOwnerDebtClosedWorldPlanIdentity of
                decisionRef:uint32 * closeReceiptRef:uint32 * admissionIdentityRef:uint32
            | TerminalFlowOwnerDebtClosedWorldFinalizationIdentity of
                planRef:uint32 * decisionRef:uint32 * closeReceiptRef:uint32
            | TerminalFlowOwnerDebtClosedWorldFinalizationExactOnceIdentity of
                finalizationTransactionRef:uint32 * closeReceiptRef:uint32
            | TerminalFlowOwnerDebtClosedWorldPostCommitExactOnceIdentity of
                planRef:uint32 * finalizationExactOnceRef:uint32 * admissionIdentityRef:uint32
            | TerminalFlowProtocolInstalledLineageIdentity of
                rootRef:uint32 * terminalRef:uint32 * fillRef:uint32 * installationRef:uint32 * admissionIdentityRef:uint32
            | TerminalFlowDispatchMaterialLineageIdentity of
                rootRef:uint32 * terminalRef:uint32 * fillRef:uint32 * installationRef:uint32 * admissionIdentityRef:uint32 *
                pendingTerminalRef:uint32 * credentialGraphClosureRef:uint32 * greenPathReceiptRef:uint32 *
                totalOrderReceiptRef:uint32 * proofRef:uint32
            | TerminalFlowDispatchLifecycleFrameIdentity of
                protocolRef:uint32 * actorStateRef:uint32 * dispatchStateRef:uint32 * possessionActorRef:uint32 *
                possessionTerminalRef:uint32 * possessionFillRef:uint32 * constitutionStateRef:uint32 *
                poisonRef:uint32 * poisonTerminalizationRef:uint32 * rejectionCount:int64
            | TerminalFlowDispatchLifecycleExactOnceIdentity of
                frameRef:uint32 * previousFrameRef:uint32 * reducerRevision:int64 * sourceEventRef:uint32
            | TerminalFlowDispatchLifecycleBlockedConstitutionIdentity of
                blocker:TerminalFlowDispatchBlocker * observedAtRevision:int64
            | TerminalFlowDispatchLifecycleConstitutionStageIdentity of
                stageOrdinal:int * authorityRef:uint32 * exactOnceRef:uint32
            | TerminalFlowDispatchLifecycleActorIdentity of
                phase:DiagJson.TerminalSchedulerPushActorPhase * fillRef:uint32
            | TerminalFlowDispatchLifecycleDispatchIdentity of
                stageOrdinal:int * requestRef:uint32 * fillRef:uint32
            | TerminalFlowQapPostCommitForceClosePermitIdentity of
                planRef:uint32 * ownerCertificateRef:uint32 * workDagProofRef:uint32 * recoveryRef:uint32 * pendingReceiptRef:uint32
            | TerminalFlowNativeHandoffIdentity of TerminalFlowNativeHandoffId

        let private terminalFlowStableAuthorityRefGate = obj()
        let private terminalFlowStableAuthorityRefByIdentity = Dictionary<obj,uint32>(HashIdentity.Structural)
        let private terminalFlowStableAuthorityIdentityByRef = Dictionary<uint32,obj>()
        let mutable private terminalFlowStableAuthorityRefCounter = 0x80000000u

        let private terminalFlowStableAuthorityRef identity =
            let boxedIdentity = box identity
            lock terminalFlowStableAuthorityRefGate (fun () ->
                match terminalFlowStableAuthorityRefByIdentity.TryGetValue boxedIdentity with
                | true, existing -> existing
                | false, _ ->
                    if terminalFlowStableAuthorityRefCounter = UInt32.MaxValue then
                        invalidOp "terminal stable authority reference namespace exhausted"
                    terminalFlowStableAuthorityRefCounter <- terminalFlowStableAuthorityRefCounter + 1u
                    let reference = terminalFlowStableAuthorityRefCounter
                    if terminalFlowStableAuthorityIdentityByRef.ContainsKey reference then
                        invalidOp "terminal stable authority reference collision"
                    terminalFlowStableAuthorityRefByIdentity.[boxedIdentity] <- reference
                    terminalFlowStableAuthorityIdentityByRef.[reference] <- boxedIdentity
                    reference)

        let private terminalFlowDispatchConstitutionLineageRef
            (constitution:TerminalFlowDispatchConstitution<'Stage>) =
            terminalFlowStableAuthorityRef (
                TerminalFlowDispatchMaterialLineageIdentity(
                    constitution.rootRef,
                    constitution.terminalRef,
                    constitution.fillRef,
                    terminalFlowIdentityRefDigest constitution.installationRef,
                    constitution.admissionIdentityRef,
                    constitution.pendingTerminalRef,
                    constitution.credentialGraphClosureRef,
                    constitution.greenPathDispatchReceipt.receiptRef,
                    constitution.totalOrderAwaitDispatch.receiptRef,
                    constitution.constitutionRef))

        // QAP PROOF AUTHORITY CUTOVER: QAP authority is now a recursive
        // proof object.  Pipeline stages cannot carry a bag of missing clauses;
        // they either own a certificate for the exact predecessor chain or a
        // typed missing-evidence result.  The affine capability embeds both the
        // QAP proof and pending lineage, so authority cannot be reconstructed
        // later from scalar refs or rendered blockers.
        type TerminalFlowQapPostCommitFairnessPreparedStage = class end
        type TerminalFlowQapPostCommitRecoveryPreparedStage = class end
        type TerminalFlowQapPostCommitOwnerWorkDagPreparedStage = class end
        type TerminalFlowQapPostCommitCompletedStage = class end
        type TerminalFlowQapAppliedAuthorityStage = class end
        type TerminalFlowQapOwnerDebtAuthorityStage = class end

        type private TerminalFlowQapProofCertificateKind =
            | TerminalFlowQapFairnessPreparedCertificate
            | TerminalFlowQapRecoveryPreparedCertificate
            | TerminalFlowQapOwnerWorkDagPreparedCertificate
            | TerminalFlowQapCompletedCertificate
            | TerminalFlowQapAppliedCertificate
            | TerminalFlowQapOwnerDebtCertificate

        type TerminalFlowQapComponentRefPath =
            | TerminalFlowQapComponentRefLast of uint32
            | TerminalFlowQapComponentRefMore of uint32 * TerminalFlowQapComponentRefPath

        type TerminalFlowQapSccMissingEvidence =
            | TerminalFlowQapSccMissingProgressCapableComponents of TerminalFlowQapComponentRefPath

        type TerminalFlowQapSccMissingEvidencePath =
            | TerminalFlowQapSccMissingEvidenceLast of TerminalFlowQapSccMissingEvidence
            | TerminalFlowQapSccMissingEvidenceMore of TerminalFlowQapSccMissingEvidence * TerminalFlowQapSccMissingEvidencePath

        type TerminalFlowQapProofConstructionStage =
            | TerminalFlowQapProofStartConstruction
            | TerminalFlowQapProofFairnessConstruction
            | TerminalFlowQapProofOwnerWorkDagConstruction
            | TerminalFlowQapProofDispositionReceiptConstruction

        type TerminalFlowQapMissingEvidence =
            | TerminalFlowQapProofMissingRoot
            | TerminalFlowQapProofMissingProgressEvidence
            | TerminalFlowQapProofRejectedProgressEvidence of evidenceRef:uint32
            | TerminalFlowQapProofMissingPendingTerminal
            | TerminalFlowQapProofFairnessNotReleased of fairnessRef:uint32
            | TerminalFlowQapProofSchedulerLineageIncomplete of missing:TerminalFlowSchedulerLineageFieldPath
            | TerminalFlowQapProofSchedulerReleaseRejected of reason:TerminalFlowSchedulerReleaseRejection
            | TerminalFlowQapProofQueueRecoveryNotReady of recoveryRef:uint32
            | TerminalFlowQapProofGreenPathNotReady
            | TerminalFlowQapProofOwnerLedgerNotClosed of ownerRef:uint32
            | TerminalFlowQapProofWorkDagTailNotClosed of tailRef:uint32
            | TerminalFlowQapProofSccUnclosed of TerminalFlowQapSccMissingEvidencePath
            | TerminalFlowQapProofResidualWorkDagBlocked of tailRef:uint32
            | TerminalFlowQapProofFinalizationNotEnqueued
            | TerminalFlowQapProofFinalizationTransactionMismatch of expected:uint32 * observed:uint32
            | TerminalFlowQapProofFinalizationExactOnceMismatch of expected:uint32 * observed:uint32
            | TerminalFlowQapProofDispositionPlanRefZero
            | TerminalFlowQapProofDispositionTransactionRefZero
            | TerminalFlowQapProofPendingLineageRejected of proofRef:uint32
            | TerminalFlowQapProofCompletionLineageMismatch of expected:uint32 * observed:uint32
            | TerminalFlowQapProofConstructionContradiction of stage:TerminalFlowQapProofConstructionStage * evidenceRef:uint32
            | TerminalFlowQapProofOwnerDebtCorridorRejected of evidenceRef:uint32
            | TerminalFlowQapProofPostCommitNotApplied

        type TerminalFlowQapMissingEvidenceSet =
            private TerminalFlowQapMissingEvidenceSet of
                head:TerminalFlowQapMissingEvidence *
                tail:TerminalFlowQapMissingEvidence list

        type TerminalFlowQapDiagnosticProjection =
            | TerminalFlowQapProofSeed of planRef:uint32
            | TerminalFlowQapProofRoot of previous:TerminalFlowQapDiagnosticProjection * rootReceiptRef:uint32
            | TerminalFlowQapProofProgress of previous:TerminalFlowQapDiagnosticProjection * snapshotRef:uint32
            | TerminalFlowQapProofPending of previous:TerminalFlowQapDiagnosticProjection * pendingRef:uint32
            | TerminalFlowQapProofFairness of previous:TerminalFlowQapDiagnosticProjection * releaseReceiptRef:uint32
            | TerminalFlowQapProofRecovery of previous:TerminalFlowQapDiagnosticProjection * recoveryRef:uint32
            | TerminalFlowQapProofGreenPath of previous:TerminalFlowQapDiagnosticProjection * greenPathRef:uint32
            | TerminalFlowQapProofOwnerLedger of previous:TerminalFlowQapDiagnosticProjection * ownerCertificateRef:uint32
            | TerminalFlowQapProofWorkDagTail of previous:TerminalFlowQapDiagnosticProjection * workDagProofRef:uint32
            | TerminalFlowQapProofScc of previous:TerminalFlowQapDiagnosticProjection * certificateRef:uint32 * generationRef:uint32
            | TerminalFlowQapProofResidualClose of previous:TerminalFlowQapDiagnosticProjection * closeRef:uint32
            | TerminalFlowQapProofApplied of previous:TerminalFlowQapDiagnosticProjection * transactionRef:uint32 * exactOnceRef:uint32
            | TerminalFlowQapProofOwnerDebtClosedWorld of previous:TerminalFlowQapDiagnosticProjection * decisionRef:uint32 * closeReceiptRef:uint32

        type TerminalFlowQapRatifiedOrigin =
            | TerminalFlowQapFinalizationRatifiedOrigin of
                planRef:uint32 * transactionRef:uint32 * exactOnceRef:uint32
            | TerminalFlowQapForceOwnerCloseRatifiedOrigin of
                TerminalFlowForceOwnerCloseRatification

        type TerminalFlowQapFairnessPreparedEvidence = private {
            rootReceiptRef : uint32
            progressSnapshotRef : uint32
            pendingTerminalRef : uint32
        }

        type TerminalFlowQapFairnessReleasedEvidence = private {
            releaseReceiptRef : uint32
            schedulerReleaseRef : uint32
        }

        type TerminalFlowQapRecoveryPreparedEvidence = private {
            recoveryRef : uint32
        }

        type TerminalFlowQapOwnerWorkDagPreparedEvidence = private {
            greenPathRef : uint32
            ownerCertificateRef : uint32
            workDagProofRef : uint32
            sccCertificateRef : uint32
            sccGenerationRef : uint32
            residualCloseRef : uint32
        }

        type TerminalFlowQapAppliedEvidence = private {
            finalizationTransactionRef : uint32
            finalizationExactOnceRef : uint32
        }

        type TerminalFlowQapProofStageEvidence =
            | TerminalFlowQapFairnessPreparedStageEvidence of TerminalFlowQapFairnessPreparedEvidence
            | TerminalFlowQapFairnessReleasedStageEvidence of TerminalFlowQapFairnessReleasedEvidence
            | TerminalFlowQapRecoveryPreparedStageEvidence of TerminalFlowQapRecoveryPreparedEvidence
            | TerminalFlowQapOwnerWorkDagPreparedStageEvidence of TerminalFlowQapOwnerWorkDagPreparedEvidence
            | TerminalFlowQapAppliedStageEvidence of TerminalFlowQapAppliedEvidence
            | TerminalFlowQapOwnerDebtRatifiedStageEvidence of TerminalFlowForceOwnerCloseRatification

        type TerminalFlowQapProofPredecessor<'Stage> =
            | TerminalFlowQapProofGenesisPredecessor of TerminalFlowQapRatifiedOrigin
            | TerminalFlowQapProofFairnessPredecessor of TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitFairnessPreparedStage>
            | TerminalFlowQapProofRecoveryPredecessor of TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitRecoveryPreparedStage>
            | TerminalFlowQapProofOwnerWorkDagPredecessor of TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitOwnerWorkDagPreparedStage>
            | TerminalFlowQapProofCompletedPredecessor of TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitCompletedStage>
            | TerminalFlowQapProofForceOwnerClosePredecessor of TerminalFlowForceOwnerCloseRatification

        and TerminalFlowQapProofCertificate<'Stage> = private {
            origin : TerminalFlowQapRatifiedOrigin
            predecessor : TerminalFlowQapProofPredecessor<'Stage>
            evidence : TerminalFlowQapProofStageEvidence
            diagnosticProjection : TerminalFlowQapDiagnosticProjection
            proofRef : uint32
            exactOnceRef : uint32
            depth : int
        }

        type TerminalFlowQapProofBuildResult<'Stage> = Result<TerminalFlowQapProofCertificate<'Stage>, TerminalFlowQapMissingEvidenceSet>

        type private TerminalFlowAppliedPendingLineageSnapshot = {
            pendingRef : uint32
            terminalRef : uint32
            fillRef : uint32
            admissionRef : uint32
            dispatchAuthorityRef : uint32
            maturityRef : uint32
        }

        type private TerminalFlowAppliedPendingLineage =
            | TerminalFlowAppliedPendingCaptured of TerminalFlowAppliedPendingLineageSnapshot
            | TerminalFlowAppliedPendingSupersededBeforeAffine of
                previous:TerminalFlowAppliedPendingLineage *
                current:TerminalFlowAppliedPendingLineageSnapshot *
                installedAdmissionIdentityRef:uint32 *
                protocolAuthorityRef:uint32 *
                proofRef:uint32

        type TerminalFlowQapCapabilityProofKindId =
            | TerminalFlowQapCapabilityProofApplied
            | TerminalFlowQapCapabilityProofOwnerDebt

        let private terminalFlowQapCapabilityProofKindText = function
            | TerminalFlowQapCapabilityProofApplied -> "Applied"
            | TerminalFlowQapCapabilityProofOwnerDebt -> "OwnerDebt"

        type TerminalFlowQapCapabilityProof =
            | TerminalFlowQapCapabilityApplied of TerminalFlowQapProofCertificate<TerminalFlowQapAppliedAuthorityStage>
            | TerminalFlowQapCapabilityOwnerDebt of TerminalFlowQapProofCertificate<TerminalFlowQapOwnerDebtAuthorityStage>

        type TerminalFlowQapCapability<'Authority> = private {
            proof : TerminalFlowQapProofCertificate<'Authority>
            pendingLineage : TerminalFlowAppliedPendingLineage
            planRef : uint32
            finalizationTransactionRef : uint32
            finalizationExactOnceRef : uint32
            postCommitExactOnceRef : uint32
            pending : TerminalFlowGlobalPendingTerminal
            pendingTerminalRef : uint32
            terminalRef : uint32
            fillRef : uint32
            admissionRef : uint32
            admissionIdentityRef : uint32
            capabilityRef : uint32
            exactOnceRef : uint32
        }

        type TerminalFlowQapPostCommitAppliedCapability =
            private
            | TerminalFlowAppliedQapCapability of TerminalFlowQapCapability<TerminalFlowQapAppliedAuthorityStage>
            | TerminalFlowOwnerDebtQapCapability of TerminalFlowQapCapability<TerminalFlowQapOwnerDebtAuthorityStage>
            member x.proof =
                match x with
                | TerminalFlowAppliedQapCapability capability -> TerminalFlowQapCapabilityApplied capability.proof
                | TerminalFlowOwnerDebtQapCapability capability -> TerminalFlowQapCapabilityOwnerDebt capability.proof
            member x.planRef =
                match x with
                | TerminalFlowAppliedQapCapability capability -> capability.planRef
                | TerminalFlowOwnerDebtQapCapability capability -> capability.planRef
            member x.finalizationTransactionRef =
                match x with
                | TerminalFlowAppliedQapCapability capability -> capability.finalizationTransactionRef
                | TerminalFlowOwnerDebtQapCapability capability -> capability.finalizationTransactionRef
            member x.finalizationExactOnceRef =
                match x with
                | TerminalFlowAppliedQapCapability capability -> capability.finalizationExactOnceRef
                | TerminalFlowOwnerDebtQapCapability capability -> capability.finalizationExactOnceRef
            member x.postCommitExactOnceRef =
                match x with
                | TerminalFlowAppliedQapCapability capability -> capability.postCommitExactOnceRef
                | TerminalFlowOwnerDebtQapCapability capability -> capability.postCommitExactOnceRef
            member x.pending =
                match x with
                | TerminalFlowAppliedQapCapability capability -> capability.pending
                | TerminalFlowOwnerDebtQapCapability capability -> capability.pending
            member x.pendingTerminalRef =
                match x with
                | TerminalFlowAppliedQapCapability capability -> capability.pendingTerminalRef
                | TerminalFlowOwnerDebtQapCapability capability -> capability.pendingTerminalRef
            member x.terminalRef =
                match x with
                | TerminalFlowAppliedQapCapability capability -> capability.terminalRef
                | TerminalFlowOwnerDebtQapCapability capability -> capability.terminalRef
            member x.fillRef =
                match x with
                | TerminalFlowAppliedQapCapability capability -> capability.fillRef
                | TerminalFlowOwnerDebtQapCapability capability -> capability.fillRef
            member x.admissionRef =
                match x with
                | TerminalFlowAppliedQapCapability capability -> capability.admissionRef
                | TerminalFlowOwnerDebtQapCapability capability -> capability.admissionRef
            member x.admissionIdentityRef =
                match x with
                | TerminalFlowAppliedQapCapability capability -> capability.admissionIdentityRef
                | TerminalFlowOwnerDebtQapCapability capability -> capability.admissionIdentityRef
            member x.capabilityRef =
                match x with
                | TerminalFlowAppliedQapCapability capability -> capability.capabilityRef
                | TerminalFlowOwnerDebtQapCapability capability -> capability.capabilityRef
            member x.exactOnceRef =
                match x with
                | TerminalFlowAppliedQapCapability capability -> capability.exactOnceRef
                | TerminalFlowOwnerDebtQapCapability capability -> capability.exactOnceRef

        type private TerminalFlowQapCapabilityMutation =
            | TerminalFlowQapCapabilityReplaceCapabilityRef of uint32
            | TerminalFlowQapCapabilityReplacePostCommitExactOnceRef of uint32
            | TerminalFlowQapCapabilityReplacePendingTerminalRef of uint32
            | TerminalFlowQapCapabilityReplaceTerminalRef of uint32
            | TerminalFlowQapCapabilityReplaceFillRef of uint32
            | TerminalFlowQapCapabilityReplacePendingPayload of TerminalFlowGlobalPendingTerminal
            | TerminalFlowQapCapabilityReplaceFinalizationExactOnceRef of uint32
            | TerminalFlowQapCapabilityReplaceAdmissionRef of uint32
            | TerminalFlowQapCapabilityReplaceAdmissionIdentityRef of uint32

        let private terminalFlowQapCapabilityMutate
            mutation
            (capability:TerminalFlowQapCapability<'Authority>)
            : TerminalFlowQapCapability<'Authority> =
            match mutation with
            | TerminalFlowQapCapabilityReplaceCapabilityRef value -> { capability with capabilityRef = value }
            | TerminalFlowQapCapabilityReplacePostCommitExactOnceRef value -> { capability with postCommitExactOnceRef = value }
            | TerminalFlowQapCapabilityReplacePendingTerminalRef value -> { capability with pendingTerminalRef = value }
            | TerminalFlowQapCapabilityReplaceTerminalRef value -> { capability with terminalRef = value }
            | TerminalFlowQapCapabilityReplaceFillRef value -> { capability with fillRef = value }
            | TerminalFlowQapCapabilityReplacePendingPayload value -> { capability with pending = value }
            | TerminalFlowQapCapabilityReplaceFinalizationExactOnceRef value -> { capability with finalizationExactOnceRef = value }
            | TerminalFlowQapCapabilityReplaceAdmissionRef value -> { capability with admissionRef = value }
            | TerminalFlowQapCapabilityReplaceAdmissionIdentityRef value -> { capability with admissionIdentityRef = value }

        let private terminalFlowQapPostCommitAppliedCapabilityMutate mutation = function
            | TerminalFlowAppliedQapCapability capability ->
                capability
                |> terminalFlowQapCapabilityMutate mutation
                |> TerminalFlowAppliedQapCapability
            | TerminalFlowOwnerDebtQapCapability capability ->
                capability
                |> terminalFlowQapCapabilityMutate mutation
                |> TerminalFlowOwnerDebtQapCapability

        let private terminalFlowQapCapabilityProofProjection = function
            | TerminalFlowQapCapabilityApplied certificate ->
                TerminalFlowQapCapabilityProofApplied, certificate.proofRef, certificate.exactOnceRef, certificate.depth
            | TerminalFlowQapCapabilityOwnerDebt certificate ->
                TerminalFlowQapCapabilityProofOwnerDebt, certificate.proofRef, certificate.exactOnceRef, certificate.depth

        let private terminalFlowQapCapabilityProofSame left right =
            let leftKind, leftProofRef, leftExactOnceRef, _ = terminalFlowQapCapabilityProofProjection left
            let rightKind, rightProofRef, rightExactOnceRef, _ = terminalFlowQapCapabilityProofProjection right
            leftKind = rightKind
            && leftProofRef = rightProofRef
            && leftExactOnceRef = rightExactOnceRef

        // AFFINE TERMINAL LIFECYCLE CUTOVER.
        // The affine terminal corridor now has two irreversible boundaries after
        // issue: push-actor-owned fill and reducer-authorized seal.  A fill can no
        // longer smuggle run_end or physical-exit authority into the same event.
        type TerminalFlowAffineDispatchPreparedStage = class end
        type TerminalFlowAffineStageTokenIssuedStage = class end
        type TerminalFlowAffineStageTokenFilledStage = class end
        type TerminalFlowAffineStageTokenSealAuthorizedStage = class end

        type TerminalFlowAffineActorLease<'Stage> = private {
            actorJoin : TerminalFlowActorOutcomeJoin<TerminalFlowArmedOutcomeJoinedStage>
            leaseDigest : CompilerIdentityKernel.ContentDigest
        }
        with
            member this.leaseRef =
                terminalFlowMintedRefOf
                    "affine_actor_lease_projection_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.leaseDigest)
            member this.exactOnceRef =
                terminalFlowMintedRefOf
                    "affine_actor_lease_projection_exact_once_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.leaseDigest)

        type TerminalFlowAffineTransitionOrdinal =
            | TerminalFlowAffinePreparedOrdinal
            | TerminalFlowAffineIssuedOrdinal
            | TerminalFlowAffineFilledOrdinal
            | TerminalFlowAffineSealAuthorizedOrdinal

        let private terminalFlowAffineTransitionOrdinalText = function
            | TerminalFlowAffinePreparedOrdinal -> "Prepared"
            | TerminalFlowAffineIssuedOrdinal -> "Issued"
            | TerminalFlowAffineFilledOrdinal -> "Filled"
            | TerminalFlowAffineSealAuthorizedOrdinal -> "SealAuthorized"

        type TerminalFlowAffineDispatchTransaction<'Stage> = private {
            authorization : TerminalFlowDispatchConsumeAuthorization<TerminalFlowDispatchConsumeAuthorizedStage>
            actorLease : TerminalFlowAffineActorLease<TerminalFlowAffineDispatchPreparedStage>
            postCommitCapability : TerminalFlowQapPostCommitAppliedCapability
            transactionDigest : CompilerIdentityKernel.ContentDigest
            transitionOrdinal : TerminalFlowAffineTransitionOrdinal
            preparedAtRevision : int64
        }
        with
            member this.transactionRef =
                terminalFlowMintedRefOf
                    "affine_dispatch_transaction_projection_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.transactionDigest)
            member this.exactOnceRef =
                terminalFlowMintedRefOf
                    "affine_dispatch_transaction_projection_exact_once_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.transactionDigest)

        type TerminalFlowDispatchConstitutionState =
            | TerminalFlowDispatchConstitutionBlocked of blocker:TerminalFlowDispatchBlocker * observedAtRevision:int64 * observedAtMs:int64
            | TerminalFlowDispatchConstitutionReady of TerminalFlowDispatchConstitution<TerminalFlowDispatchConstitutionReadyStage>
            | TerminalFlowDispatchConstitutionIssued of TerminalFlowDispatchIssuance<TerminalFlowDispatchConstitutionIssuedStage>
            | TerminalFlowDispatchAffinePrepared of TerminalFlowAffineDispatchTransaction<TerminalFlowAffineDispatchPreparedStage>
            | TerminalFlowDispatchAffineIssued of TerminalFlowAffineDispatchTransaction<TerminalFlowAffineStageTokenIssuedStage>
            | TerminalFlowDispatchAffineFilled of TerminalFlowAffineDispatchTransaction<TerminalFlowAffineStageTokenFilledStage>
            | TerminalFlowDispatchAffineSealAuthorized of TerminalFlowAffineDispatchTransaction<TerminalFlowAffineStageTokenSealAuthorizedStage>

        let private terminalFlowAffineTransactionMarkIssued
            (transaction:TerminalFlowAffineDispatchTransaction<TerminalFlowAffineDispatchPreparedStage>)
            : TerminalFlowAffineDispatchTransaction<TerminalFlowAffineStageTokenIssuedStage> =
            { authorization = transaction.authorization
              actorLease = transaction.actorLease
              postCommitCapability = transaction.postCommitCapability
              transactionDigest = transaction.transactionDigest
              transitionOrdinal = TerminalFlowAffineIssuedOrdinal
              preparedAtRevision = transaction.preparedAtRevision }

        let private terminalFlowAffineTransactionMarkFilled
            (transaction:TerminalFlowAffineDispatchTransaction<TerminalFlowAffineStageTokenIssuedStage>)
            : TerminalFlowAffineDispatchTransaction<TerminalFlowAffineStageTokenFilledStage> =
            { authorization = transaction.authorization
              actorLease = transaction.actorLease
              postCommitCapability = transaction.postCommitCapability
              transactionDigest = transaction.transactionDigest
              transitionOrdinal = TerminalFlowAffineFilledOrdinal
              preparedAtRevision = transaction.preparedAtRevision }

        let private terminalFlowAffineTransactionMarkSealAuthorized
            (transaction:TerminalFlowAffineDispatchTransaction<TerminalFlowAffineStageTokenFilledStage>)
            : TerminalFlowAffineDispatchTransaction<TerminalFlowAffineStageTokenSealAuthorizedStage> =
            { authorization = transaction.authorization
              actorLease = transaction.actorLease
              postCommitCapability = transaction.postCommitCapability
              transactionDigest = transaction.transactionDigest
              transitionOrdinal = TerminalFlowAffineSealAuthorizedOrdinal
              preparedAtRevision = transaction.preparedAtRevision }

        let private terminalFlowPendingTerminalAuthorityPayloadSame
            (left:TerminalFlowGlobalPendingTerminal)
            (right:TerminalFlowGlobalPendingTerminal) =
            left.terminalReceiptRef = right.terminalReceiptRef
            && left.fillRef = right.fillRef
            && left.intent = right.intent
            && terminalFlowPendingAdmissionSame left.admission right.admission
            && terminalFlowPendingDispatchAuthoritySame left.dispatchAuthority right.dispatchAuthority

        let private terminalFlowAffineTransactionSameLineage
            (left:TerminalFlowAffineDispatchTransaction<'LeftStage>)
            (right:TerminalFlowAffineDispatchTransaction<'RightStage>) =
            let leftCredentials = left.authorization.issuance.credentials
            let rightCredentials = right.authorization.issuance.credentials
            left.transactionRef = right.transactionRef
            && left.exactOnceRef = right.exactOnceRef
            && left.actorLease.leaseRef = right.actorLease.leaseRef
            && left.actorLease.exactOnceRef = right.actorLease.exactOnceRef
            && terminalFlowActorOutcomeJoinActorRef left.actorLease.actorJoin = terminalFlowActorOutcomeJoinActorRef right.actorLease.actorJoin
            && terminalFlowActorOutcomeJoinActorBindingRef left.actorLease.actorJoin = terminalFlowActorOutcomeJoinActorBindingRef right.actorLease.actorJoin
            && terminalFlowActorOutcomeJoinAdmissionRef left.actorLease.actorJoin = terminalFlowActorOutcomeJoinAdmissionRef right.actorLease.actorJoin
            && terminalFlowActorOutcomeJoinAdmissionIdentityRef left.actorLease.actorJoin = terminalFlowActorOutcomeJoinAdmissionIdentityRef right.actorLease.actorJoin
            && left.authorization.consumeAuthorityRef = right.authorization.consumeAuthorityRef
            && left.authorization.exactOnceRef = right.authorization.exactOnceRef
            && left.authorization.tokenRef = right.authorization.tokenRef
            && left.authorization.pendingTerminalRef = right.authorization.pendingTerminalRef
            && left.authorization.ratifiedHandoff = right.authorization.ratifiedHandoff
            && left.authorization.issuance.issuanceRef = right.authorization.issuance.issuanceRef
            && left.authorization.issuance.constitution.constitutionRef = right.authorization.issuance.constitution.constitutionRef
            && leftCredentials.bundleRef = rightCredentials.bundleRef
            && leftCredentials.exactOnceRef = rightCredentials.exactOnceRef
            && left.postCommitCapability.capabilityRef = right.postCommitCapability.capabilityRef
            && left.postCommitCapability.exactOnceRef = right.postCommitCapability.exactOnceRef
            && terminalFlowQapCapabilityProofSame left.postCommitCapability.proof right.postCommitCapability.proof
            && left.postCommitCapability.planRef = right.postCommitCapability.planRef
            && left.postCommitCapability.finalizationTransactionRef = right.postCommitCapability.finalizationTransactionRef
            && left.postCommitCapability.finalizationExactOnceRef = right.postCommitCapability.finalizationExactOnceRef
            && left.postCommitCapability.postCommitExactOnceRef = right.postCommitCapability.postCommitExactOnceRef
            && left.postCommitCapability.pendingTerminalRef = right.postCommitCapability.pendingTerminalRef
            && left.postCommitCapability.terminalRef = right.postCommitCapability.terminalRef
            && left.postCommitCapability.fillRef = right.postCommitCapability.fillRef
            && left.postCommitCapability.admissionRef = right.postCommitCapability.admissionRef
            && left.postCommitCapability.admissionIdentityRef = right.postCommitCapability.admissionIdentityRef
            && terminalFlowPendingTerminalAuthorityPayloadSame left.postCommitCapability.pending right.postCommitCapability.pending

        let private terminalFlowAffineTransactionAuthorityInternallyConsistent
            (transaction:TerminalFlowAffineDispatchTransaction<'Stage>) =
            let capability = transaction.postCommitCapability
            let token = transaction.actorLease.actorJoin
            let constitution = transaction.authorization.issuance.constitution
            let tokenAdmissionRef = terminalFlowActorOutcomeJoinAdmissionRef token
            let tokenAdmissionIdentityRef = terminalFlowActorOutcomeJoinAdmissionIdentityRef token
            tokenAdmissionRef = capability.admissionRef
            && tokenAdmissionIdentityRef = capability.admissionIdentityRef
            && terminalFlowIdentityRefDigest token.terminalReceiptRef = capability.terminalRef
            && TerminalFlowFillKeyId.digest token.fillKey = capability.fillRef
            && constitution.terminalRef = capability.terminalRef
            && constitution.fillRef = capability.fillRef
            && constitution.admissionRef = capability.admissionRef
            && constitution.admissionIdentityRef = capability.admissionIdentityRef
            && constitution.pendingTerminalRef = capability.pendingTerminalRef
            && transaction.authorization.pendingTerminalRef = capability.pendingTerminalRef

        let private terminalFlowAffineTransactionStaticFixture
            (prepared:TerminalFlowAffineDispatchTransaction<TerminalFlowAffineDispatchPreparedStage>)
            : TerminalFlowAffineDispatchTransaction<TerminalFlowAffineStageTokenFilledStage> =
            prepared
            |> terminalFlowAffineTransactionMarkIssued
            |> terminalFlowAffineTransactionMarkFilled

        // Bonus migration : the five prior migrations are now composed into a
        // single reducer-owned protocol.  Individual DUs are not enough if callers
        // can skip installation, CIC checking, artifact commitment or exit authority.
        type TerminalFlowBreakthroughAuthority =
            | TerminalFlowBreakthroughReducerOwned of reducerSequence:int64
            | TerminalFlowBreakthroughLegacySurfaceRejected of surface:TerminalFlowProtocolSurface

        type TerminalFlowBreakthroughBlocker =
            | TerminalFlowBreakthroughFrontierUnavailable of provenance:TerminalFlowPendingProvenance
            | TerminalFlowBreakthroughRelationNotConsumed of relation:TerminalFlowQapRelation
            | TerminalFlowBreakthroughOutcomeNotInstalled
            | TerminalFlowBreakthroughCicBlocked of blocker:TerminalFlowCicBlocker
            | TerminalFlowBreakthroughArtifactNotCommitted
            | TerminalFlowBreakthroughExitNotAuthorized
            | TerminalFlowBreakthroughIllegalTransition of stateCode:int * eventCode:int

        type TerminalFlowBreakthroughProtocol =
            | TerminalFlowBreakthroughAwaitFrontier of provenance:TerminalFlowPendingProvenance
            | TerminalFlowBreakthroughQapCanonical of provenance:TerminalFlowPendingProvenance * relation:TerminalFlowQapRelationProtocolState
            | TerminalFlowBreakthroughOutcomeInstalled of installation:TerminalFlowOutcomeInstallation
            | TerminalFlowBreakthroughCicChecked of corridor:TerminalFlowCicKernelCorridor
            | TerminalFlowBreakthroughArtifactCommitted of corridor:TerminalFlowArtifactCorridor<TerminalFlowArtifactsCommittedState>
            | TerminalFlowBreakthroughExitAuthorized of exitCode:int * authorityRef:uint32
            | TerminalFlowBreakthroughBlocked of blocker:TerminalFlowBreakthroughBlocker

        type TerminalFlowBreakthroughEvent =
            | TerminalFlowBreakthroughObserveFrontier of provenance:TerminalFlowPendingProvenance
            | TerminalFlowBreakthroughConsumeRelation of relation:TerminalFlowQapRelationProtocolState
            | TerminalFlowBreakthroughInstallOutcome of installation:TerminalFlowOutcomeInstallation
            | TerminalFlowBreakthroughCheckCic of corridor:TerminalFlowCicKernelCorridor
            | TerminalFlowBreakthroughCommitArtifact of corridor:TerminalFlowArtifactCorridor<TerminalFlowArtifactsCommittedState>
            | TerminalFlowBreakthroughAuthorizeExit of exitCode:int * authorityRef:uint32

        type TerminalFlowBreakthroughTransitionReceipt = private {
            authority : TerminalFlowBreakthroughAuthority
            before : TerminalFlowBreakthroughProtocol
            event : TerminalFlowBreakthroughEvent
            after : TerminalFlowBreakthroughProtocol
            exactOnceRef : uint32
        }

        let private terminalFlowBreakthroughStateCode = function
            | TerminalFlowBreakthroughAwaitFrontier _ -> 1
            | TerminalFlowBreakthroughQapCanonical _ -> 2
            | TerminalFlowBreakthroughOutcomeInstalled _ -> 3
            | TerminalFlowBreakthroughCicChecked _ -> 4
            | TerminalFlowBreakthroughArtifactCommitted _ -> 5
            | TerminalFlowBreakthroughExitAuthorized _ -> 6
            | TerminalFlowBreakthroughBlocked _ -> 7

        let private terminalFlowBreakthroughEventCode = function
            | TerminalFlowBreakthroughObserveFrontier _ -> 1
            | TerminalFlowBreakthroughConsumeRelation _ -> 2
            | TerminalFlowBreakthroughInstallOutcome _ -> 3
            | TerminalFlowBreakthroughCheckCic _ -> 4
            | TerminalFlowBreakthroughCommitArtifact _ -> 5
            | TerminalFlowBreakthroughAuthorizeExit _ -> 6

        let private terminalFlowBreakthroughAuthorityText = function
            | TerminalFlowBreakthroughReducerOwned reducerSequence -> sprintf "reducer_owned:%d" reducerSequence
            | TerminalFlowBreakthroughLegacySurfaceRejected surface -> "legacy_surface_rejected:" + terminalFlowProtocolSurfaceText surface

        let private terminalFlowBreakthroughTransition authority reducerSequence state event =
            let after =
                match state, event with
                | TerminalFlowBreakthroughAwaitFrontier _, TerminalFlowBreakthroughObserveFrontier provenance ->
                    match provenance.authority with
                    | TerminalFlowPendingFrontierAuthoritative
                    | TerminalFlowPendingFrontierReconciledGhosts
                    | TerminalFlowPendingFrontierUnavailableRawZeroClosed _
                    | TerminalFlowPendingFrontierUnavailableReducerClosed _ ->
                        TerminalFlowBreakthroughQapCanonical(provenance, TerminalFlowQapRelationProtocolObserved (terminalFlowQapRelationFor TerminalFlowQapPendingOwner TerminalFlowQapPendingOwnerTerminalTailNode TerminalFlowQapPendingOwnerWitness))
                    | TerminalFlowPendingFrontierUnavailableQuarantine _ ->
                        TerminalFlowBreakthroughBlocked (TerminalFlowBreakthroughFrontierUnavailable provenance)
                | TerminalFlowBreakthroughQapCanonical(provenance, _), TerminalFlowBreakthroughConsumeRelation relation ->
                    match relation with
                    | TerminalFlowQapRelationProtocolConsumed _
                    | TerminalFlowQapRelationProtocolClosed _ -> TerminalFlowBreakthroughQapCanonical(provenance, relation)
                    | TerminalFlowQapRelationProtocolObserved relation
                    | TerminalFlowQapRelationProtocolCanonicalized(relation, _) -> TerminalFlowBreakthroughBlocked (TerminalFlowBreakthroughRelationNotConsumed relation)
                    | TerminalFlowQapRelationProtocolPoisoned(relation, _) -> TerminalFlowBreakthroughBlocked (TerminalFlowBreakthroughRelationNotConsumed relation)
                | TerminalFlowBreakthroughQapCanonical _, TerminalFlowBreakthroughInstallOutcome installation when terminalFlowOutcomeInstallationIsInstalled installation ->
                    TerminalFlowBreakthroughOutcomeInstalled installation
                | TerminalFlowBreakthroughOutcomeInstalled _, TerminalFlowBreakthroughCheckCic corridor ->
                    match corridor.verdict with
                    | TerminalFlowCicCheckAccepted _ -> TerminalFlowBreakthroughCicChecked corridor
                    | TerminalFlowCicCheckRejected(blocker, _)
                    | TerminalFlowCicCheckBlocked blocker -> TerminalFlowBreakthroughBlocked (TerminalFlowBreakthroughCicBlocked blocker)
                | TerminalFlowBreakthroughCicChecked _, TerminalFlowBreakthroughCommitArtifact corridor ->
                    match corridor.writerCompletionRoute with
                    | TerminalFlowWriterCompletionGreenPath _ -> TerminalFlowBreakthroughArtifactCommitted corridor
                    | TerminalFlowWriterCompletionTypedFailure _
                    | TerminalFlowWriterCompletionRejected _ ->
                        TerminalFlowBreakthroughBlocked (TerminalFlowBreakthroughIllegalTransition(terminalFlowBreakthroughStateCode state, terminalFlowBreakthroughEventCode event))
                | TerminalFlowBreakthroughArtifactCommitted _, TerminalFlowBreakthroughAuthorizeExit(0, authorityRef) ->
                    TerminalFlowBreakthroughExitAuthorized(0, authorityRef)
                | _, TerminalFlowBreakthroughAuthorizeExit(_, _) -> TerminalFlowBreakthroughBlocked TerminalFlowBreakthroughExitNotAuthorized
                | _ ->
                    TerminalFlowBreakthroughBlocked (
                        TerminalFlowBreakthroughIllegalTransition(
                            terminalFlowBreakthroughStateCode state,
                            terminalFlowBreakthroughEventCode event))
            { authority = authority
              before = state
              event = event
              after = after
              exactOnceRef =
                NativeCutoverStableRef.ref32
                    "terminal-flow-breakthrough-transition"
                    [ terminalFlowBreakthroughAuthorityText authority
                      string reducerSequence
                      string (terminalFlowBreakthroughStateCode state)
                      string (terminalFlowBreakthroughEventCode event)
                      string (terminalFlowBreakthroughStateCode after) ] }

        type TerminalFlowReducerOwnedEventFamily =
            | TerminalFlowReducerOwnsOutcomeInstallation
            | TerminalFlowReducerOwnsArtifactCorridor
            | TerminalFlowReducerOwnsQapFixpointMaturity
            | TerminalFlowReducerOwnsTerminalTotalOrder
            | TerminalFlowReducerOwnsOwnerForceClose
            | TerminalFlowReducerOwnsCicKernelProtocol
            | TerminalFlowReducerOwnsPendingExactOnceLedger
            | TerminalFlowReducerOwnsReplayFairness
            | TerminalFlowReducerOwnsQueueOnlyRecovery
            | TerminalFlowReducerOwnsUnifiedTerminalProtocol
            | TerminalFlowReducerOwnsAffineDispatch

        type TerminalFlowReducerMutationLedger = private {
            primarySurface : TerminalFlowProtocolSurface
            quarantinedInterlockedSites : TerminalFlowReducerMutationAuthority list
            reducerOwnedEventFamilies : TerminalFlowReducerOwnedEventFamily list
        }

        let private terminalFlowReducerMutationLedgerInitial = {
            primarySurface = TerminalFlowPrimarySurface
            quarantinedInterlockedSites = [
                TerminalFlowMutationLegacyInterlockedQuarantined("terminal_flow_json_seq", "TerminalFlowGlobalServerJournalAppend")
                TerminalFlowMutationLegacyInterlockedQuarantined("terminal_frontier_progress", "TerminalFlowGlobalServerQapWatchRebaseRequested")
                TerminalFlowMutationLegacyInterlockedQuarantined("terminal_completion_credit", "TerminalFlowGlobalServerQapWatchRebaseRequested")
                TerminalFlowMutationLegacyInterlockedQuarantined("cross_kind_replay_driver_counter", "TerminalFlowGlobalServerReplayFairnessObserved")
                TerminalFlowMutationLegacyInterlockedQuarantined("queue_only_recovery_cache", "TerminalFlowGlobalServerQueueOnlyRecoveryFolded")
                TerminalFlowMutationLegacyInterlockedQuarantined("owner_debt_tie_breaker", "TerminalFlowGlobalServerOwnerDebtObserved")
            ]
            reducerOwnedEventFamilies = [
                TerminalFlowReducerOwnsOutcomeInstallation
                TerminalFlowReducerOwnsArtifactCorridor
                TerminalFlowReducerOwnsQapFixpointMaturity
                TerminalFlowReducerOwnsTerminalTotalOrder
                TerminalFlowReducerOwnsOwnerForceClose
                TerminalFlowReducerOwnsCicKernelProtocol
                TerminalFlowReducerOwnsPendingExactOnceLedger
                TerminalFlowReducerOwnsReplayFairness
                TerminalFlowReducerOwnsQueueOnlyRecovery
                TerminalFlowReducerOwnsUnifiedTerminalProtocol
                TerminalFlowReducerOwnsAffineDispatch
            ]
        }

        let private terminalFlowReducerMutationLedgerText ledger =
            "surface=" + terminalFlowProtocolSurfaceText ledger.primarySurface
            + "|interlocked_quarantine_count=" + string ledger.quarantinedInterlockedSites.Length
            + "|reducer_owned_event_families=" + string ledger.reducerOwnedEventFamilies.Length

        type TerminalFlowMirrorErasureVerdict =
            | TerminalFlowPrimarySurfaceOnly
            | TerminalFlowLegacyMirrorDiagnosticOnly of mirrorName:string
            | TerminalFlowLegacyMirrorRejected of mirrorName:string * attemptedAuthority:string

        let private terminalFlowMirrorErasureVerdictText = function
            | TerminalFlowPrimarySurfaceOnly -> "primary_surface_only"
            | TerminalFlowLegacyMirrorDiagnosticOnly mirrorName -> "legacy_mirror_diagnostic_only:" + mirrorName
            | TerminalFlowLegacyMirrorRejected (mirrorName, attemptedAuthority) -> "legacy_mirror_rejected:" + mirrorName + ":" + attemptedAuthority

        type TerminalFlowDeadmanErasureVerdict =
            | TerminalFlowDeadmanErasedFromAuthority
            | TerminalFlowDeadmanObserverOnly of observedAgeMs:int64
            | TerminalFlowDeadmanRejectedMutation of attemptedMutation:string

        let private terminalFlowDeadmanErasureVerdictText = function
            | TerminalFlowDeadmanErasedFromAuthority -> "deadman_erased_from_authority"
            | TerminalFlowDeadmanObserverOnly observedAgeMs -> "deadman_observer_only:" + string observedAgeMs
            | TerminalFlowDeadmanRejectedMutation attemptedMutation -> "deadman_rejected_mutation:" + attemptedMutation

        type TerminalFlowStringAuthorityErasureVerdict =
            | TerminalFlowStringsRenderOnly
            | TerminalFlowStringDecisionRejected of site:string * renderedValue:string
            | TerminalFlowTypedReducerAuthorityRequired of site:string

        let private terminalFlowStringAuthorityErasureVerdictText = function
            | TerminalFlowStringsRenderOnly -> "strings_render_only"
            | TerminalFlowStringDecisionRejected (site, renderedValue) -> "string_decision_rejected:" + site + ":" + renderedValue
            | TerminalFlowTypedReducerAuthorityRequired site -> "typed_reducer_authority_required:" + site

        type TerminalFlowAuthorityCutoverState = private {
            mirrorErasure : TerminalFlowMirrorErasureVerdict
            deadmanErasure : TerminalFlowDeadmanErasureVerdict
            stringAuthorityErasure : TerminalFlowStringAuthorityErasureVerdict
            greenPathRequired : bool
            typedTotalOrderRequired : bool
            cicProofOwnerLedgerRequired : bool
            exactOnceRef : uint32
        }

        let private terminalFlowAuthorityCutoverInitial =
            { mirrorErasure = TerminalFlowPrimarySurfaceOnly
              deadmanErasure = TerminalFlowDeadmanErasedFromAuthority
              stringAuthorityErasure = TerminalFlowStringsRenderOnly
              greenPathRequired = true
              typedTotalOrderRequired = true
              cicProofOwnerLedgerRequired = true
              exactOnceRef = terminalFlowMintedRefOf "authority_cutover_exact_once" "greenPath|typedTotalOrder|cicProofOwnerLedger" }

        let private terminalFlowAuthorityCutoverText (state:TerminalFlowAuthorityCutoverState) =
            "mirror=" + terminalFlowMirrorErasureVerdictText state.mirrorErasure
            + "|deadman=" + terminalFlowDeadmanErasureVerdictText state.deadmanErasure
            + "|strings=" + terminalFlowStringAuthorityErasureVerdictText state.stringAuthorityErasure
            + "|green_path_required=" + string state.greenPathRequired
            + "|typed_total_order_required=" + string state.typedTotalOrderRequired
            + "|cic_proof_owner_required=" + string state.cicProofOwnerLedgerRequired
            + "|exact_once=" + string state.exactOnceRef

        // MIGRATION / bonus migration 6 of 5: all breakthrough authority now
        // converges here.  Green-path, terminal total-order and CIC proof
        // evidence are no longer independently promotable surfaces.
        type TerminalFlowKernelProofAuthority =
            | TerminalFlowKernelProofAwaiting
            | TerminalFlowKernelProofVacuouslyClosed of noObligationsReceiptRef:uint32 * quiescenceCertificateRef:uint32
            | TerminalFlowKernelProofClosed of
                checkReceipt:TerminalFlowIdentityRef<TerminalFlowCicCheckReceiptRefKind> *
                proofOwnerCloseReceiptRef:uint32 *
                universeOwnerCloseReceiptRefs:uint32 list *
                defEqWitnessRefs:uint32 list *
                quiescenceCertificateRef:uint32
            | TerminalFlowKernelProofBlocked of blocker:TerminalFlowCicBlocker

        let private terminalFlowKernelProofVacuousInitial =
            let noObligationsReceiptRef = terminalFlowMintedRefOf "cic_no_obligations_receipt_ref" "no_cic_work_registered_at_reducer_genesis"
            let quiescenceCertificateRef = terminalFlowMintedRefOf "cic_vacuous_quiescence_certificate_ref" (string noObligationsReceiptRef)
            TerminalFlowKernelProofVacuouslyClosed(noObligationsReceiptRef, quiescenceCertificateRef)

        let private terminalFlowKernelProofAuthorityFor (corridor:TerminalFlowCicKernelCorridor) =
            match corridor.verdict with
            | TerminalFlowCicCheckRejected(blocker, _) -> TerminalFlowKernelProofBlocked blocker
            | TerminalFlowCicCheckBlocked blocker -> TerminalFlowKernelProofBlocked blocker
            | TerminalFlowCicCheckAccepted checkReceipt ->
                let proofOwnersOpen =
                    match corridor.proofOwnerLedger with
                    | OwnerLedgerEmpty -> false
                    | OwnerLedgerCons(CicProofObligationOwnerNode(OwnerLeaseClosed _), OwnerLedgerEmpty) -> false
                    | _ -> true
                let actorState = terminalFlowCicOwnedActorState corridor.ownedActor
                let actorBlocker =
                    actorState
                    |> Option.bind (fun actor -> actor.blocked |> Map.toSeq |> Seq.tryHead |> Option.map snd)
                let quiescenceCertificate = terminalFlowCicOwnedActorQuiescenceCertificate corridor.ownedActor
                match actorBlocker, proofOwnersOpen, corridor.proofOwnerCloseReceiptRef, actorState, quiescenceCertificate with
                | Some blocker, _, _, _, _ -> TerminalFlowKernelProofBlocked blocker
                | None, false, Some proofOwnerCloseReceiptRef, Some actor, Some quiescenceCertificate ->
                    let universeReceipts =
                        actor.universeOwners
                        |> Map.toSeq
                        |> Seq.choose (fun (_, owner) ->
                            match owner with
                            | TerminalFlowCicUniverseOwnerClosed(receipt, _) -> Some (terminalFlowIdentityRefDigest receipt)
                            | _ -> None)
                        |> Seq.toList
                    let defEqWitnessRefs =
                        actor.congruenceEdges
                        |> Map.toSeq
                        |> Seq.map (fun (_, edge) -> edge.exactOnceRef)
                        |> Seq.toList
                    TerminalFlowKernelProofClosed(checkReceipt, proofOwnerCloseReceiptRef, universeReceipts, defEqWitnessRefs, quiescenceCertificate.certificateRef)
                | _ -> TerminalFlowKernelProofAwaiting

        // MIGRATION: one predecessor-checked proof graph replaces the accidental
        // federation of independently promotable progress/CIC/fairness/recovery/GreenPath surfaces.
        // Phantom stages make the intended ordering explicit even though F# lacks native GADTs.
        type TerminalFlowBreakthroughDeterministicStage private () =
            static member BreakthroughStageTag () = 0x210001u
        type TerminalFlowBreakthroughCicQuiescentStage private () =
            static member BreakthroughStageTag () = 0x210002u
        type TerminalFlowBreakthroughFairStage private () =
            static member BreakthroughStageTag () = 0x210003u
        type TerminalFlowBreakthroughRecoveryStage private () =
            static member BreakthroughStageTag () = 0x210004u
        type TerminalFlowBreakthroughGreenPathStage private () =
            static member BreakthroughStageTag () = 0x210005u
        type TerminalFlowBreakthroughPromotableStage private () =
            static member BreakthroughStageTag () = 0x210006u
        type TerminalFlowCompletionPortOpenStage = class end
        type TerminalFlowCompletionPortFilledStage = class end

        type TerminalFlowCompletionPort<'Stage> = private {
            portRef : uint32
            fillKey : TerminalFlowFillKeyId
            predecessorCertificateRef : uint32 option
            filledAtRevision : int64 option
            exactOnceRef : uint32
        }

        type TerminalFlowBreakthroughCertificate<'Stage> = private {
            certificateRef : uint32
            predecessorRef : uint32 option
            progressSnapshotRef : TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind> option
            evidenceDigest : uint32
            exactOnceRef : uint32
        }

        type TerminalFlowBreakthroughErasedStageId =
            | TerminalFlowBreakthroughErasedDeterministic
            | TerminalFlowBreakthroughErasedCicQuiescent
            | TerminalFlowBreakthroughErasedFair
            | TerminalFlowBreakthroughErasedRecovery
            | TerminalFlowBreakthroughErasedGreenPath
            | TerminalFlowBreakthroughErasedPromotable

        type TerminalFlowBreakthroughCertificateErased = private {
            certificateRef : uint32
            predecessorRef : uint32 option
            progressSnapshotRef : TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind> option
            evidenceDigest : uint32
            exactOnceRef : uint32
            stage : TerminalFlowBreakthroughErasedStageId
        }

        type TerminalFlowBreakthroughConvergenceViolation =
            | TerminalFlowBreakthroughProgressRejected of TerminalFlowProgressRegression
            | TerminalFlowBreakthroughDeterminismMissing
            | TerminalFlowBreakthroughKernelProofAwaiting
            | TerminalFlowBreakthroughKernelProofBlocked of TerminalFlowCicBlocker
            | TerminalFlowBreakthroughFairnessMissing
            | TerminalFlowBreakthroughFairnessStarved of TerminalFlowReplayDriverFairnessSample
            | TerminalFlowBreakthroughFairnessYieldPending of TerminalFlowReplayDriverFairnessSample
            | TerminalFlowBreakthroughRecoveryMissing
            | TerminalFlowBreakthroughRecoveryRejected of TerminalFlowProgressRegression
            | TerminalFlowBreakthroughGreenPathMissing
            | TerminalFlowBreakthroughGreenPathTooEarly of TerminalFlowGreenPathLinearState
            | TerminalFlowBreakthroughGreenPathRejected of reason:TerminalFlowGreenPathRejectReasonId

        type TerminalFlowBreakthroughViolationTransition =
            | TerminalFlowBreakthroughViolationAppeared of TerminalFlowBreakthroughConvergenceViolation
            | TerminalFlowBreakthroughViolationCleared of TerminalFlowBreakthroughConvergenceViolation

        // MIGRATION_ERASED_STAGE_LEDGER: keep phantom typed certificate construction, but store only erased receipts in convergence state so F# cannot collapse the heterogeneous fields to DeterministicStage.
        type TerminalFlowBreakthroughRequirementCredential =
            | TerminalFlowBreakthroughRequireDeterminism
            | TerminalFlowBreakthroughRequireCicQuiescence
            | TerminalFlowBreakthroughRequireFairness
            | TerminalFlowBreakthroughRequireQueueRecovery
            | TerminalFlowBreakthroughRequireGreenPath

        type TerminalFlowBreakthroughRequirementMinter =
            | TerminalFlowBreakthroughProgressReducerMinter
            | TerminalFlowBreakthroughCicKernelReducerMinter
            | TerminalFlowBreakthroughFairnessReducerMinter
            | TerminalFlowBreakthroughQapResolutionMinter
            | TerminalFlowBreakthroughGreenPathReducerMinter

        type TerminalFlowBreakthroughRequirement = private {
            requirementRef : uint32
            credential : TerminalFlowBreakthroughRequirementCredential
            minter : TerminalFlowBreakthroughRequirementMinter
            minterRef : uint32
            predecessorRequirementRef : uint32 option
            exactOnceRef : uint32
        }

        type TerminalFlowBreakthroughRequirementSpine =
            | TerminalFlowBreakthroughAwaitingRequirement of TerminalFlowBreakthroughRequirement
            | TerminalFlowBreakthroughDeterminismSatisfied of certificate:TerminalFlowBreakthroughCertificateErased * nextRequirement:TerminalFlowBreakthroughRequirement
            | TerminalFlowBreakthroughCicSatisfied of prior:TerminalFlowBreakthroughRequirementSpine * certificate:TerminalFlowBreakthroughCertificateErased * nextRequirement:TerminalFlowBreakthroughRequirement
            | TerminalFlowBreakthroughFairnessSatisfied of prior:TerminalFlowBreakthroughRequirementSpine * certificate:TerminalFlowBreakthroughCertificateErased * nextRequirement:TerminalFlowBreakthroughRequirement
            | TerminalFlowBreakthroughRecoverySatisfied of prior:TerminalFlowBreakthroughRequirementSpine * certificate:TerminalFlowBreakthroughCertificateErased * nextRequirement:TerminalFlowBreakthroughRequirement
            | TerminalFlowBreakthroughGreenPathSatisfied of prior:TerminalFlowBreakthroughRequirementSpine * certificate:TerminalFlowBreakthroughCertificateErased

        type TerminalFlowBreakthroughConvergenceState = private {
            deterministic : TerminalFlowBreakthroughCertificateErased option
            cicQuiescent : TerminalFlowBreakthroughCertificateErased option
            fair : TerminalFlowBreakthroughCertificateErased option
            recovery : TerminalFlowBreakthroughCertificateErased option
            greenPath : TerminalFlowBreakthroughCertificateErased option
            promotable : TerminalFlowBreakthroughCertificateErased option
            requirements : TerminalFlowBreakthroughRequirement list
            requirementSpine : TerminalFlowBreakthroughRequirementSpine
            violations : TerminalFlowBreakthroughConvergenceViolation list
            revision : int64
            exactOnceRef : uint32
        }

        let private terminalFlowBreakthroughRequirementCredentialText = function
            | TerminalFlowBreakthroughRequireDeterminism -> "determinism"
            | TerminalFlowBreakthroughRequireCicQuiescence -> "cic_quiescence"
            | TerminalFlowBreakthroughRequireFairness -> "fairness"
            | TerminalFlowBreakthroughRequireQueueRecovery -> "queue_recovery"
            | TerminalFlowBreakthroughRequireGreenPath -> "green_path"

        let private terminalFlowBreakthroughRequirementMinterText = function
            | TerminalFlowBreakthroughProgressReducerMinter -> "progress_reducer"
            | TerminalFlowBreakthroughCicKernelReducerMinter -> "cic_kernel_reducer"
            | TerminalFlowBreakthroughFairnessReducerMinter -> "fairness_reducer"
            | TerminalFlowBreakthroughQapResolutionMinter -> "qap_resolution_reducer"
            | TerminalFlowBreakthroughGreenPathReducerMinter -> "green_path_reducer"

        let private terminalFlowBreakthroughRequirementFor credential minter predecessorRequirementRef =
            let credentialText = terminalFlowBreakthroughRequirementCredentialText credential
            let minterText = terminalFlowBreakthroughRequirementMinterText minter
            let requirementRef = terminalFlowMintedRefOf "breakthrough_requirement_ref" (credentialText + ":" + minterText)
            let minterRef = terminalFlowMintedRefOf "breakthrough_requirement_minter_ref" minterText
            { requirementRef = requirementRef
              credential = credential
              minter = minter
              minterRef = minterRef
              predecessorRequirementRef = predecessorRequirementRef
              exactOnceRef = terminalFlowMintedRefOf "breakthrough_requirement_exact_once" (string requirementRef + ":" + string minterRef) }

        let private terminalFlowBreakthroughGenesisRequirements =
            let determinism = terminalFlowBreakthroughRequirementFor TerminalFlowBreakthroughRequireDeterminism TerminalFlowBreakthroughProgressReducerMinter None
            let cic = terminalFlowBreakthroughRequirementFor TerminalFlowBreakthroughRequireCicQuiescence TerminalFlowBreakthroughCicKernelReducerMinter (Some determinism.requirementRef)
            let fairness = terminalFlowBreakthroughRequirementFor TerminalFlowBreakthroughRequireFairness TerminalFlowBreakthroughFairnessReducerMinter (Some cic.requirementRef)
            let recovery = terminalFlowBreakthroughRequirementFor TerminalFlowBreakthroughRequireQueueRecovery TerminalFlowBreakthroughQapResolutionMinter (Some fairness.requirementRef)
            let green = terminalFlowBreakthroughRequirementFor TerminalFlowBreakthroughRequireGreenPath TerminalFlowBreakthroughGreenPathReducerMinter (Some recovery.requirementRef)
            [ determinism; cic; fairness; recovery; green ]

        let private terminalFlowBreakthroughRequirementSpineFor requirements deterministic cicQuiescent fair recovery green =
            match requirements with
            | [ determinismRequirement; cicRequirement; fairnessRequirement; recoveryRequirement; greenRequirement ] ->
                match deterministic with
                | None -> TerminalFlowBreakthroughAwaitingRequirement determinismRequirement
                | Some deterministicCertificate ->
                    let deterministicSpine = TerminalFlowBreakthroughDeterminismSatisfied(deterministicCertificate, cicRequirement)
                    match cicQuiescent with
                    | None -> deterministicSpine
                    | Some cicCertificate ->
                        let cicSpine = TerminalFlowBreakthroughCicSatisfied(deterministicSpine, cicCertificate, fairnessRequirement)
                        match fair with
                        | None -> cicSpine
                        | Some fairnessCertificate ->
                            let fairnessSpine = TerminalFlowBreakthroughFairnessSatisfied(cicSpine, fairnessCertificate, recoveryRequirement)
                            match recovery with
                            | None -> fairnessSpine
                            | Some recoveryCertificate ->
                                let recoverySpine = TerminalFlowBreakthroughRecoverySatisfied(fairnessSpine, recoveryCertificate, greenRequirement)
                                match green with
                                | None -> recoverySpine
                                | Some greenCertificate -> TerminalFlowBreakthroughGreenPathSatisfied(recoverySpine, greenCertificate)
            | _ -> failwith "Breakthrough requirements must form the five-stage recursive spine."

        let private terminalFlowBreakthroughRequirementSpineText = function
            | TerminalFlowBreakthroughAwaitingRequirement requirement -> sprintf "awaiting:%s:%u" (terminalFlowBreakthroughRequirementCredentialText requirement.credential) requirement.requirementRef
            | TerminalFlowBreakthroughDeterminismSatisfied(certificate, nextRequirement) -> sprintf "determinism_satisfied:%u:next=%u" certificate.certificateRef nextRequirement.requirementRef
            | TerminalFlowBreakthroughCicSatisfied(_, certificate, nextRequirement) -> sprintf "cic_satisfied:%u:next=%u" certificate.certificateRef nextRequirement.requirementRef
            | TerminalFlowBreakthroughFairnessSatisfied(_, certificate, nextRequirement) -> sprintf "fairness_satisfied:%u:next=%u" certificate.certificateRef nextRequirement.requirementRef
            | TerminalFlowBreakthroughRecoverySatisfied(_, certificate, nextRequirement) -> sprintf "recovery_satisfied:%u:next=%u" certificate.certificateRef nextRequirement.requirementRef
            | TerminalFlowBreakthroughGreenPathSatisfied(_, certificate) -> sprintf "green_path_satisfied:%u" certificate.certificateRef

        let private terminalFlowBreakthroughConvergenceInitial = {
            deterministic = None
            cicQuiescent = None
            fair = None
            recovery = None
            greenPath = None
            promotable = None
            requirements = terminalFlowBreakthroughGenesisRequirements
            requirementSpine = terminalFlowBreakthroughGenesisRequirements |> List.head |> TerminalFlowBreakthroughAwaitingRequirement
            violations = [ TerminalFlowBreakthroughDeterminismMissing; TerminalFlowBreakthroughKernelProofAwaiting; TerminalFlowBreakthroughFairnessMissing; TerminalFlowBreakthroughRecoveryMissing; TerminalFlowBreakthroughGreenPathMissing ]
            revision = 0L
            exactOnceRef = terminalFlowMintedRefOf "breakthrough_convergence_exact_once" "genesis"
        }

        let inline private terminalFlowBreakthroughCertificate< ^Stage when ^Stage : (static member BreakthroughStageTag : unit -> uint32)>
            label
            predecessorRef
            progressSnapshotRef
            evidenceText : TerminalFlowBreakthroughCertificate< ^Stage> =
            let evidenceDigest = terminalFlowMintedRefOf (label + "_evidence_digest") evidenceText
            let stageTag = ((^Stage) : (static member BreakthroughStageTag : unit -> uint32) ())
            let certificateRef = terminalFlowMintedRefOf (label + "_certificate_ref") (string predecessorRef + ":" + string evidenceDigest + ":stage=" + string stageTag)
            { certificateRef = certificateRef
              predecessorRef = predecessorRef
              progressSnapshotRef = progressSnapshotRef
              evidenceDigest = evidenceDigest
              exactOnceRef = terminalFlowMintedRefOf (label + "_exact_once") (string certificateRef + ":" + string evidenceDigest) }

        let private terminalFlowBreakthroughEraseCertificate
            stage
            (certificate: TerminalFlowBreakthroughCertificate<'Stage>) : TerminalFlowBreakthroughCertificateErased =
            { certificateRef = certificate.certificateRef
              predecessorRef = certificate.predecessorRef
              progressSnapshotRef = certificate.progressSnapshotRef
              evidenceDigest = certificate.evidenceDigest
              exactOnceRef = certificate.exactOnceRef
              stage = stage }

        let private terminalFlowBreakthroughRestorePromotable
            (certificate:TerminalFlowBreakthroughCertificateErased)
            : TerminalFlowBreakthroughCertificate<TerminalFlowBreakthroughPromotableStage> option =
            if certificate.stage <> TerminalFlowBreakthroughErasedPromotable then None
            else
                Some {
                    certificateRef = certificate.certificateRef
                    predecessorRef = certificate.predecessorRef
                    progressSnapshotRef = certificate.progressSnapshotRef
                    evidenceDigest = certificate.evidenceDigest
                    exactOnceRef = certificate.exactOnceRef
                }

        let private terminalFlowBreakthroughDeterministicCertificate label predecessorRef progressSnapshotRef evidenceText : TerminalFlowBreakthroughCertificateErased =
            terminalFlowBreakthroughCertificate<TerminalFlowBreakthroughDeterministicStage> label predecessorRef progressSnapshotRef evidenceText
            |> terminalFlowBreakthroughEraseCertificate TerminalFlowBreakthroughErasedDeterministic

        let private terminalFlowBreakthroughCicQuiescentCertificate label predecessorRef progressSnapshotRef evidenceText : TerminalFlowBreakthroughCertificateErased =
            terminalFlowBreakthroughCertificate<TerminalFlowBreakthroughCicQuiescentStage> label predecessorRef progressSnapshotRef evidenceText
            |> terminalFlowBreakthroughEraseCertificate TerminalFlowBreakthroughErasedCicQuiescent

        let private terminalFlowBreakthroughFairCertificate label predecessorRef progressSnapshotRef evidenceText : TerminalFlowBreakthroughCertificateErased =
            terminalFlowBreakthroughCertificate<TerminalFlowBreakthroughFairStage> label predecessorRef progressSnapshotRef evidenceText
            |> terminalFlowBreakthroughEraseCertificate TerminalFlowBreakthroughErasedFair

        let private terminalFlowBreakthroughRecoveryCertificate label predecessorRef progressSnapshotRef evidenceText : TerminalFlowBreakthroughCertificateErased =
            terminalFlowBreakthroughCertificate<TerminalFlowBreakthroughRecoveryStage> label predecessorRef progressSnapshotRef evidenceText
            |> terminalFlowBreakthroughEraseCertificate TerminalFlowBreakthroughErasedRecovery

        let private terminalFlowBreakthroughGreenPathCertificate label predecessorRef progressSnapshotRef evidenceText : TerminalFlowBreakthroughCertificateErased =
            terminalFlowBreakthroughCertificate<TerminalFlowBreakthroughGreenPathStage> label predecessorRef progressSnapshotRef evidenceText
            |> terminalFlowBreakthroughEraseCertificate TerminalFlowBreakthroughErasedGreenPath

        let private terminalFlowBreakthroughPromotableCertificate label predecessorRef progressSnapshotRef evidenceText : TerminalFlowBreakthroughCertificateErased =
            terminalFlowBreakthroughCertificate<TerminalFlowBreakthroughPromotableStage> label predecessorRef progressSnapshotRef evidenceText
            |> terminalFlowBreakthroughEraseCertificate TerminalFlowBreakthroughErasedPromotable

        let private terminalFlowBreakthroughConvergenceViolationText = function
            | TerminalFlowBreakthroughProgressRejected regression -> "progress_rejected:" + terminalFlowProgressRegressionText regression
            | TerminalFlowBreakthroughDeterminismMissing -> "determinism_missing"
            | TerminalFlowBreakthroughKernelProofAwaiting -> "kernel_proof_awaiting"
            | TerminalFlowBreakthroughKernelProofBlocked blocker -> "kernel_proof_blocked:" + terminalFlowCicBlockerText blocker
            | TerminalFlowBreakthroughFairnessMissing -> "fairness_missing"
            | TerminalFlowBreakthroughFairnessStarved sample -> FastRuntimeFormat.format "fairness_starved:sample=%u:q=%d:a=%d" [| box (terminalFlowIdentityRefDigest sample.sampleRef); box sample.queueDepth; box sample.activeWorkers |]
            | TerminalFlowBreakthroughFairnessYieldPending sample -> sprintf "fairness_yield_pending:sample=%u:q=%d" (terminalFlowIdentityRefDigest sample.sampleRef) sample.queueDepth
            | TerminalFlowBreakthroughRecoveryMissing -> "recovery_missing"
            | TerminalFlowBreakthroughRecoveryRejected regression -> "recovery_rejected:" + terminalFlowProgressRegressionText regression
            | TerminalFlowBreakthroughGreenPathMissing -> "green_path_missing"
            | TerminalFlowBreakthroughGreenPathTooEarly state -> sprintf "green_path_too_early:ref=%u" (terminalFlowGreenPathReceiptRef state)
            | TerminalFlowBreakthroughGreenPathRejected reason ->
                "green_path_rejected:" + terminalFlowGreenPathRejectReasonText reason

        let private terminalFlowBreakthroughViolationTransitionText = function
            | TerminalFlowBreakthroughViolationAppeared violation -> "appeared:" + terminalFlowBreakthroughConvergenceViolationText violation
            | TerminalFlowBreakthroughViolationCleared violation -> "cleared:" + terminalFlowBreakthroughConvergenceViolationText violation

        let private terminalFlowBreakthroughViolationTransitions previous current =
            let keyed violations =
                violations
                |> List.map (fun violation -> terminalFlowBreakthroughConvergenceViolationText violation, violation)
                |> Map.ofList
            let previousByText = keyed previous
            let currentByText = keyed current
            let appeared =
                currentByText
                |> Map.toList
                |> List.choose (fun (key, violation) -> if Map.containsKey key previousByText then None else Some (TerminalFlowBreakthroughViolationAppeared violation))
            let cleared =
                previousByText
                |> Map.toList
                |> List.choose (fun (key, violation) -> if Map.containsKey key currentByText then None else Some (TerminalFlowBreakthroughViolationCleared violation))
            appeared @ cleared

        let private terminalFlowBreakthroughConvergenceAdvance
            revision
            (progressAuthority:TerminalFlowReducerProgressAuthority)
            (kernelProof:TerminalFlowKernelProofAuthority)
            (fairness:TerminalFlowReducerFairnessState)
            (queueRecovery:TerminalFlowReducerQueueRecoveryState)
            (greenPath:TerminalFlowGreenPathLinearState option) =
            let mutable violations = []
            let snapshotRef = progressAuthority.accepted |> Option.map (fun evidence -> evidence.snapshotRef)
            let deterministic =
                match progressAuthority.accepted, progressAuthority.rejected with
                | Some evidence, None ->
                    Some (terminalFlowBreakthroughDeterministicCertificate
                        "breakthrough_deterministic"
                        None
                        (Some evidence.snapshotRef)
                        (FastRuntimeFormat.format "corpus=%u|semantic=%u|seq=%d|discovered=%d|retired=%d" [| box evidence.semanticDigest.inputCorpusRef; box (terminalFlowIdentityRefDigest evidence.semanticDigest.digestRef); box evidence.snapshotSequence; box evidence.frontier.discovered; box evidence.frontier.retired |]))
                | _, Some regression ->
                    violations <- TerminalFlowBreakthroughProgressRejected regression :: violations
                    None
                | _ ->
                    violations <- TerminalFlowBreakthroughDeterminismMissing :: violations
                    None
            let cicQuiescent =
                match deterministic, kernelProof with
                | Some predecessor, TerminalFlowKernelProofVacuouslyClosed(noObligationsRef, quiescenceRef) ->
                    Some (terminalFlowBreakthroughCicQuiescentCertificate
                        "breakthrough_cic_quiescent_vacuous"
                        (Some predecessor.certificateRef)
                        snapshotRef
                        (sprintf "no_obligations=%u|quiescence=%u" noObligationsRef quiescenceRef))
                | Some predecessor, TerminalFlowKernelProofClosed(checkReceipt, ownerCloseRef, universeRefs, defEqRefs, quiescenceRef) ->
                    Some (terminalFlowBreakthroughCicQuiescentCertificate
                        "breakthrough_cic_quiescent"
                        (Some predecessor.certificateRef)
                        snapshotRef
                        (FastRuntimeFormat.format "check=%u|owner=%u|universes=%d|defeq=%d|quiescence=%u" [| box (terminalFlowIdentityRefDigest checkReceipt); box ownerCloseRef; box universeRefs.Length; box defEqRefs.Length; box quiescenceRef |]))
                | _, TerminalFlowKernelProofBlocked blocker ->
                    violations <- TerminalFlowBreakthroughKernelProofBlocked blocker :: violations
                    None
                | _ ->
                    violations <- TerminalFlowBreakthroughKernelProofAwaiting :: violations
                    None
            let fair =
                match cicQuiescent, fairness.verdict, fairness.releaseReceipt with
                | Some predecessor, Some (TerminalFlowFairnessBalanced sample), Some release
                    when release.admissionRef = sample.admissionRef
                         && release.admissionIdentityRef = sample.admissionIdentityRef
                         && release.actorBindingRef = sample.actorBindingRef
                         && release.credentialLedgerRef = sample.credentialLedgerRef
                         && terminalFlowIdentityRefDigest release.fairnessEpochRef = terminalFlowIdentityRefDigest sample.fairnessEpochRef
                         && (sample.queueDepth = 0L || sample.activeWorkers > 0L) ->
                    Some (terminalFlowBreakthroughFairCertificate
                        "breakthrough_fair_admission_quiescent"
                        (Some predecessor.certificateRef)
                        snapshotRef
                        (FastRuntimeFormat.format "admission=%u|identity=%u|binding=%u|ledger=%u|epoch=%u|release=%u|sample=%u|driver=%u|lane=%s|q=%d|a=%d|score=%d" [| box sample.admissionRef; box sample.admissionIdentityRef; box sample.actorBindingRef; box sample.credentialLedgerRef; box (terminalFlowIdentityRefDigest sample.fairnessEpochRef); box (terminalFlowIdentityRefDigest release.releaseRef); box (terminalFlowIdentityRefDigest sample.sampleRef); box (terminalFlowIdentityRefDigest sample.driverRef); box (terminalFlowReplayDriverLaneText sample.lane); box sample.queueDepth; box sample.activeWorkers; box sample.starvationScore |]))
                | Some predecessor, Some (TerminalFlowFairnessReleasedByQuiescence(sample, creditDigest)), Some release
                    when release.admissionRef = sample.admissionRef
                         && release.admissionIdentityRef = sample.admissionIdentityRef
                         && release.actorBindingRef = sample.actorBindingRef
                         && release.credentialLedgerRef = sample.credentialLedgerRef
                         && (match release.basis with | TerminalFlowFairnessReleaseByQuiescence digest -> digest = creditDigest | _ -> false) ->
                    Some (terminalFlowBreakthroughFairCertificate
                        "breakthrough_fair_admission_credit_returned"
                        (Some predecessor.certificateRef)
                        snapshotRef
                        (FastRuntimeFormat.format "admission=%u|identity=%u|binding=%u|ledger=%u|epoch=%u|release=%u|sample=%u|driver=%u|lane=%s|q=%d|a=%d|score=%d|credit=%s" [| box sample.admissionRef; box sample.admissionIdentityRef; box sample.actorBindingRef; box sample.credentialLedgerRef; box (terminalFlowIdentityRefDigest sample.fairnessEpochRef); box (terminalFlowIdentityRefDigest release.releaseRef); box (terminalFlowIdentityRefDigest sample.sampleRef); box (terminalFlowIdentityRefDigest sample.driverRef); box (terminalFlowReplayDriverLaneText sample.lane); box sample.queueDepth; box sample.activeWorkers; box sample.starvationScore; box (CompilerIdentityKernel.ContentDigest.text creditDigest) |]))
                | Some predecessor, Some (TerminalFlowFairnessBalanced sample), None
                    when sample.admissionRef = 0u
                         && sample.admissionIdentityRef = 0u
                         && sample.actorBindingRef = 0u
                         && sample.credentialLedgerRef = 0u
                         && (match queueRecovery.decision with
                             | TerminalFlowQueueRecoveryReadyForReducerSeal certificate ->
                                 match certificate.trigger with
                                 | TerminalFlowRecoveryFromGhostReconciliation _ -> true
                                 | _ -> false
                             | _ -> false) ->
                    let recoveryRef =
                        match queueRecovery.decision with
                        | TerminalFlowQueueRecoveryReadyForReducerSeal certificate -> terminalFlowIdentityRefDigest certificate.recoveryRef
                        | _ -> 0u
                    Some (terminalFlowBreakthroughFairCertificate
                        "breakthrough_fair_qap_ghost_recovery"
                        (Some predecessor.certificateRef)
                        snapshotRef
                        (FastRuntimeFormat.format "qap_ghost_recovery=%u|sample=%u|lane=%s|q=%d|a=%d|authority=no_scheduler_capability_required" [| box recoveryRef; box (terminalFlowIdentityRefDigest sample.sampleRef); box (terminalFlowReplayDriverLaneText sample.lane); box sample.queueDepth; box sample.activeWorkers |]))
                | _, Some (TerminalFlowFairnessStarved sample), _ ->
                    violations <- TerminalFlowBreakthroughFairnessStarved sample :: violations
                    None
                | _, Some (TerminalFlowFairnessYieldRequired sample), _ ->
                    violations <- TerminalFlowBreakthroughFairnessYieldPending sample :: violations
                    None
                | _ ->
                    violations <- TerminalFlowBreakthroughFairnessMissing :: violations
                    None
            let recovery =
                match fair, queueRecovery.decision with
                | Some predecessor, TerminalFlowQueueRecoveryReadyForReducerSeal certificate ->
                    Some (terminalFlowBreakthroughRecoveryCertificate
                        "breakthrough_recovery"
                        (Some predecessor.certificateRef)
                        snapshotRef
                        (FastRuntimeFormat.format "recovery=%u|gate=%u|before=%d|after=%d|trigger=%s|exact_once=%u" [| box (terminalFlowIdentityRefDigest certificate.recoveryRef); box (terminalFlowIdentityRefDigest certificate.gate.gateRef); box certificate.gate.beforeQueueDepth; box certificate.gate.afterQueueDepth; box (terminalFlowQueueRecoveryTriggerText certificate.trigger); box certificate.exactOnceRef |]))
                | _, TerminalFlowQueueRecoveryRejectedByProgressRegression regression ->
                    violations <- TerminalFlowBreakthroughRecoveryRejected regression :: violations
                    None
                | _ ->
                    violations <- TerminalFlowBreakthroughRecoveryMissing :: violations
                    None
            let greenCertificate predecessor fillKey receiptRef exactOnce =
                Some (terminalFlowBreakthroughGreenPathCertificate
                    "breakthrough_green_path"
                    (Some predecessor.certificateRef)
                    snapshotRef
                    (FastRuntimeFormat.format "fill=%s|receipt=%u|exact_once=%b" [| box (TerminalFlowFillKeyId.text fillKey); box receiptRef; box exactOnce |]))
            let green =
                match recovery, greenPath with
                // Admission is the transition that advances an open green path to
                // WriterBound. Requiring WriterBound before admission creates the
                // impossible cycle admission -> dispatch -> writer bind -> promotable
                // -> admission. The open receipt is already linear, exact-once and
                // predecessor-closed by recovery, so it is the proper pre-dispatch
                // breakthrough certificate. Physical-exit sealing still has its own
                // stronger WriterBound/Artifact/RunEnd/PhysicalExit gates.
                | Some predecessor, Some (TerminalFlowGreenPathOpen(receipt, _)) ->
                    greenCertificate predecessor receipt.fillKey receipt.receiptRef receipt.exactOnce
                | Some predecessor, Some (TerminalFlowGreenPathWriterBound(receipt, _, _)) ->
                    greenCertificate predecessor receipt.fillKey receipt.receiptRef receipt.exactOnce
                | Some predecessor, Some (TerminalFlowGreenPathArtifactCommitted(receipt, _)) ->
                    greenCertificate predecessor receipt.fillKey receipt.receiptRef receipt.exactOnce
                | Some predecessor, Some (TerminalFlowGreenPathTerminalCommitted(receipt, _)) ->
                    greenCertificate predecessor receipt.fillKey receipt.receiptRef receipt.exactOnce
                | Some predecessor, Some (TerminalFlowGreenPathRunEnded(receipt, _)) ->
                    greenCertificate predecessor receipt.fillKey receipt.receiptRef receipt.exactOnce
                | Some predecessor, Some (TerminalFlowGreenPathPhysicalExit(receipt, _)) ->
                    greenCertificate predecessor receipt.fillKey receipt.receiptRef receipt.exactOnce
                | _, Some (TerminalFlowGreenPathRejected(_, reason)) ->
                    violations <- TerminalFlowBreakthroughGreenPathRejected reason :: violations
                    None
                | None, Some _ ->
                    // A GreenPath proposal cannot be judged before its recovery predecessor exists.
                    // Preserve it as inert state instead of reporting a second, causally premature violation.
                    None
                | _ ->
                    violations <- TerminalFlowBreakthroughGreenPathMissing :: violations
                    None
            let requirements = terminalFlowBreakthroughGenesisRequirements
            let requirementSpine =
                terminalFlowBreakthroughRequirementSpineFor requirements deterministic cicQuiescent fair recovery green
            let promotable =
                match requirementSpine, violations with
                | TerminalFlowBreakthroughGreenPathSatisfied(_, predecessor), [] ->
                    Some (terminalFlowBreakthroughPromotableCertificate
                        "breakthrough_promotable"
                        (Some predecessor.certificateRef)
                        snapshotRef
                        (terminalFlowBreakthroughRequirementSpineText requirementSpine))
                | _ -> None
            ({ deterministic = deterministic;
               cicQuiescent = cicQuiescent;
               fair = fair;
               recovery = recovery;
               greenPath = green;
               promotable = promotable;
               requirements = requirements;
               requirementSpine = requirementSpine;
               violations = List.rev violations;
               revision = revision;
               exactOnceRef = terminalFlowMintedRefOf "breakthrough_convergence_exact_once" (string revision + ":" + (violations |> List.map terminalFlowBreakthroughConvergenceViolationText |> String.concat "|")) } : TerminalFlowBreakthroughConvergenceState)

        type TerminalFlowBreakthroughSealBlocker =
            | TerminalFlowBreakthroughSealGreenPathMissing
            | TerminalFlowBreakthroughSealGreenPathNotPhysicalExit of state:TerminalFlowGreenPathLinearState
            | TerminalFlowBreakthroughSealGreenPathNonZeroExit of exitCode:int
            | TerminalFlowBreakthroughSealTotalOrderNotPhysicalExit of state:TerminalFlowTypedTotalOrder
            | TerminalFlowBreakthroughSealKernelProofAwaiting
            | TerminalFlowBreakthroughSealKernelProofBlocked of blocker:TerminalFlowCicBlocker
            | TerminalFlowBreakthroughSealAuthorityCutoverIncomplete
            | TerminalFlowBreakthroughSealConvergenceNotPromotable of TerminalFlowBreakthroughConvergenceState
            | TerminalFlowBreakthroughSealFillKeyMismatch of greenFillKey:TerminalFlowFillKeyId * totalOrderFillKey:TerminalFlowFillKeyId
            | TerminalFlowBreakthroughSealBlockers of TerminalFlowBreakthroughSealBlocker list

        type TerminalFlowBreakthroughSealReceipt = private {
            sealRef : uint32
            greenPathReceiptRef : uint32
            totalOrderReceiptRef : uint32
            kernelCheckReceiptRef : uint32
            proofOwnerCloseReceiptRef : uint32
            kernelQuiescenceRef : uint32
            completionPortRef : uint32
            fillKey : TerminalFlowFillKeyId
            exactOnceRef : uint32
        }

        type TerminalFlowBreakthroughSealState =
            | TerminalFlowBreakthroughAwaiting of TerminalFlowBreakthroughSealBlocker list
            | TerminalFlowBreakthroughSealed of TerminalFlowBreakthroughSealReceipt
            | TerminalFlowBreakthroughRejected of TerminalFlowBreakthroughSealBlocker

        let private terminalFlowKernelProofAuthorityText = function
            | TerminalFlowKernelProofAwaiting -> "kernel_proof_awaiting"
            | TerminalFlowKernelProofVacuouslyClosed(noObligationsReceiptRef, quiescenceRef) ->
                sprintf "kernel_proof_vacuously_closed:no_obligations=%u:quiescence=%u" noObligationsReceiptRef quiescenceRef
            | TerminalFlowKernelProofClosed(checkReceipt, proofOwnerCloseReceiptRef, universeReceipts, defEqWitnesses, quiescenceRef) ->
                FastRuntimeFormat.format "kernel_proof_closed:check=%s:owner_close=%u:universes=%d:defeq=%d:quiescence=%u" [| box (terminalFlowIdentityRefText checkReceipt); box proofOwnerCloseReceiptRef; box universeReceipts.Length; box defEqWitnesses.Length; box quiescenceRef |]
            | TerminalFlowKernelProofBlocked blocker -> "kernel_proof_blocked:" + terminalFlowCicBlockerText blocker

        let private terminalFlowGreenPathFillKey : TerminalFlowGreenPathLinearState -> TerminalFlowFillKeyId = function
            | TerminalFlowGreenPathOpen(receipt, _) -> receipt.fillKey
            | TerminalFlowGreenPathWriterBound(receipt, _, _) -> receipt.fillKey
            | TerminalFlowGreenPathArtifactCommitted(receipt, _) -> receipt.fillKey
            | TerminalFlowGreenPathTerminalCommitted(receipt, _) -> receipt.fillKey
            | TerminalFlowGreenPathRunEnded(receipt, _) -> receipt.fillKey
            | TerminalFlowGreenPathPhysicalExit(receipt, _) -> receipt.fillKey
            | TerminalFlowGreenPathRejected(receipt, _) -> receipt.fillKey

        let rec private terminalFlowBreakthroughBlockerText = function
            | TerminalFlowBreakthroughSealGreenPathMissing -> "green_path_missing"
            | TerminalFlowBreakthroughSealGreenPathNotPhysicalExit state -> sprintf "green_path_not_physical_exit:ref=%u" (terminalFlowGreenPathReceiptRef state)
            | TerminalFlowBreakthroughSealGreenPathNonZeroExit exitCode -> "green_path_nonzero_exit:" + string exitCode
            | TerminalFlowBreakthroughSealTotalOrderNotPhysicalExit state -> "typed_total_order_not_physical_exit:" + terminalFlowTypedTotalOrderText state
            | TerminalFlowBreakthroughSealKernelProofAwaiting -> "kernel_proof_awaiting"
            | TerminalFlowBreakthroughSealKernelProofBlocked blocker -> "kernel_proof_blocked:" + terminalFlowCicBlockerText blocker
            | TerminalFlowBreakthroughSealAuthorityCutoverIncomplete -> "authority_cutover_incomplete"
            | TerminalFlowBreakthroughSealConvergenceNotPromotable convergence -> "convergence_not_promotable:" + (convergence.violations |> List.map terminalFlowBreakthroughConvergenceViolationText |> String.concat "|")
            | TerminalFlowBreakthroughSealFillKeyMismatch(greenFillKey, totalOrderFillKey) ->
                "fill_key_mismatch:" + TerminalFlowFillKeyId.text greenFillKey + ":" + TerminalFlowFillKeyId.text totalOrderFillKey
            | TerminalFlowBreakthroughSealBlockers blockers -> "blockers:[" + (blockers |> List.map terminalFlowBreakthroughBlockerText |> String.concat ";") + "]"

        let private terminalFlowBreakthroughSealBlockerTexts blockers =
            let directTexts =
                blockers
                |> List.choose (function
                    | TerminalFlowBreakthroughSealConvergenceNotPromotable _ -> None
                    | blocker -> Some (terminalFlowBreakthroughBlockerText blocker))
                |> List.distinct
            let directTextSet = Set.ofList directTexts
            let convergenceTexts =
                blockers
                |> List.choose (function
                    | TerminalFlowBreakthroughSealConvergenceNotPromotable convergence ->
                        let residualViolations =
                            convergence.violations
                            |> List.map terminalFlowBreakthroughConvergenceViolationText
                            |> List.distinct
                            |> List.filter (fun violation -> not (Set.contains violation directTextSet))
                        if List.isEmpty residualViolations then None
                        else Some ("convergence_not_promotable:" + String.concat "|" residualViolations)
                    | _ -> None)
            directTexts @ convergenceTexts

        let private terminalFlowBreakthroughSealFor greenPath typedTotalOrder kernelProof authorityCutover convergence =
            let blockers = ResizeArray<TerminalFlowBreakthroughSealBlocker>()
            let mutable greenPhysical = None
            let mutable totalPhysical = None
            match greenPath with
            | Some (TerminalFlowGreenPathPhysicalExit(receipt, exitCode)) ->
                greenPhysical <- Some(receipt, exitCode)
                if exitCode <> 0 then blockers.Add(TerminalFlowBreakthroughSealGreenPathNonZeroExit exitCode)
            | Some state -> blockers.Add(TerminalFlowBreakthroughSealGreenPathNotPhysicalExit state)
            | None -> blockers.Add TerminalFlowBreakthroughSealGreenPathMissing
            match typedTotalOrder with
            | TerminalFlowTotalOrderPhysicalExit receipt -> totalPhysical <- Some receipt
            | state -> blockers.Add(TerminalFlowBreakthroughSealTotalOrderNotPhysicalExit state)
            match kernelProof with
            | TerminalFlowKernelProofAwaiting -> blockers.Add TerminalFlowBreakthroughSealKernelProofAwaiting
            | TerminalFlowKernelProofBlocked blocker -> blockers.Add(TerminalFlowBreakthroughSealKernelProofBlocked blocker)
            | TerminalFlowKernelProofVacuouslyClosed _
            | TerminalFlowKernelProofClosed _ -> ()
            if not authorityCutover.greenPathRequired
               || not authorityCutover.typedTotalOrderRequired
               || not authorityCutover.cicProofOwnerLedgerRequired then
                blockers.Add TerminalFlowBreakthroughSealAuthorityCutoverIncomplete
            match convergence.promotable with
            | Some _ -> ()
            | None -> blockers.Add(TerminalFlowBreakthroughSealConvergenceNotPromotable convergence)
            match greenPhysical, totalPhysical with
            | Some(greenReceipt, _), Some totalReceipt ->
                match totalReceipt.fillKey with
                | TerminalFlowTotalOrderFillBound totalFillKey when greenReceipt.fillKey <> totalFillKey ->
                    blockers.Add(TerminalFlowBreakthroughSealFillKeyMismatch(greenReceipt.fillKey, totalFillKey))
                | TerminalFlowTotalOrderFillBound _
                | TerminalFlowTotalOrderFillUnbound -> ()
            | _ -> ()
            if blockers.Count > 0 then
                let blockerList = List.ofSeq blockers
                // MIGRATION: the breakthrough seal is a BuildOk covenant. Once a
                // reducer-owned FailClosed total order owns physical exit, projecting
                // missing GreenPath/recovery credentials is both noisy and misleading.
                if not (DiagJson.terminalQapProvenDeadlockNow())
                   && not (DiagJson.terminalFailureExitRequestedNow())
                   && not (DiagJson.nativePromiseFailureClosedNow())
                   && not (DiagJson.terminalSemanticDrainActiveNow()) then
                    terminalFlowEmitAdvancedConsoleProjection {
                        lane = TerminalFlowConsoleLaneExitSeal
                        sequence = int64 blockerList.Length
                        progressBp = 9900
                        etaMs = None
                        title = "breakthrough seal awaiting"
                        detail = blockerList |> terminalFlowBreakthroughSealBlockerTexts |> String.concat "|"
                        authorityRef = terminalFlowMintedRefOf "advanced_console_authority_ref" "breakthrough-seal-awaiting"
                    }
                TerminalFlowBreakthroughAwaiting(blockerList)
            else
                let proofSealEvidence =
                    match kernelProof with
                    | TerminalFlowKernelProofVacuouslyClosed(noObligationsReceiptRef, quiescenceRef) ->
                        Some(noObligationsReceiptRef, noObligationsReceiptRef, quiescenceRef, "vacuous-no-obligations")
                    | TerminalFlowKernelProofClosed(checkReceipt, proofOwnerCloseReceiptRef, _, _, quiescenceRef) ->
                        Some(terminalFlowIdentityRefDigest checkReceipt, proofOwnerCloseReceiptRef, quiescenceRef, terminalFlowIdentityRefText checkReceipt)
                    | _ -> None
                match greenPhysical, totalPhysical, proofSealEvidence, convergence.promotable with
                | Some(greenReceipt, 0), Some totalReceipt, Some(kernelCheckReceiptRef, proofOwnerCloseReceiptRef, quiescenceRef, proofIdentity), Some promotableCertificate ->
                    let greenFillKeyText = TerminalFlowFillKeyId.text greenReceipt.fillKey
                    let sealRef = terminalFlowMintedRefOf "breakthrough_seal_ref" (greenFillKeyText + ":" + string greenReceipt.receiptRef + ":" + string totalReceipt.receiptRef + ":" + proofIdentity)
                    let completionPort : TerminalFlowCompletionPort<TerminalFlowCompletionPortFilledStage> =
                        { portRef = terminalFlowMintedRefOf "terminal_completion_port_ref" (greenFillKeyText + ":" + string promotableCertificate.certificateRef)
                          fillKey = greenReceipt.fillKey
                          predecessorCertificateRef = Some promotableCertificate.certificateRef
                          filledAtRevision = Some (int64 totalReceipt.orderIndex)
                          exactOnceRef = terminalFlowMintedRefOf "terminal_completion_port_exact_once" (greenFillKeyText + ":" + string promotableCertificate.exactOnceRef) }
                    let seal = {
                        sealRef = sealRef
                        greenPathReceiptRef = greenReceipt.receiptRef
                        totalOrderReceiptRef = totalReceipt.receiptRef
                        kernelCheckReceiptRef = kernelCheckReceiptRef
                        proofOwnerCloseReceiptRef = proofOwnerCloseReceiptRef
                        kernelQuiescenceRef = quiescenceRef
                        completionPortRef = completionPort.portRef
                        fillKey = greenReceipt.fillKey
                        exactOnceRef = terminalFlowMintedRefOf "breakthrough_seal_exact_once" (string sealRef + ":" + greenFillKeyText + ":q=" + string quiescenceRef + ":port=" + string completionPort.exactOnceRef)
                    }
                    terminalFlowEmitAdvancedConsoleProjection {
                        lane = TerminalFlowConsoleLaneExitSeal
                        sequence = int64 seal.exactOnceRef
                        progressBp = 10000
                        etaMs = Some 0L
                        title = "breakthrough seal closed"
                        detail = "green_path|typed_total_order|cic_proof_authority|" + proofIdentity
                        authorityRef = seal.sealRef
                    }
                    TerminalFlowBreakthroughSealed seal
                | _ -> TerminalFlowBreakthroughRejected(TerminalFlowBreakthroughSealBlockers(List.ofSeq blockers))

        let private terminalFlowBreakthroughSealText = function
            | TerminalFlowBreakthroughAwaiting blockers -> "awaiting:" + (blockers |> terminalFlowBreakthroughSealBlockerTexts |> String.concat "|")
            | TerminalFlowBreakthroughSealed receipt -> FastRuntimeFormat.format "sealed:ref=%u:green=%u:order=%u:kernel=%u:owner_close=%u:quiescence=%u:completion_port=%u:fill=%s" [| box receipt.sealRef; box receipt.greenPathReceiptRef; box receipt.totalOrderReceiptRef; box receipt.kernelCheckReceiptRef; box receipt.proofOwnerCloseReceiptRef; box receipt.kernelQuiescenceRef; box receipt.completionPortRef; box (TerminalFlowFillKeyId.text receipt.fillKey) |]
            | TerminalFlowBreakthroughRejected blocker -> "rejected:" + terminalFlowBreakthroughBlockerText blocker

        type TerminalFlowHostShutdownRequestRefKind private () =
            static member IdentityKindTag () = 0x080007u

        type TerminalFlowHostShutdownFinalizationReceiptRefKind private () =
            static member IdentityKindTag () = 0x080008u

        type TerminalFlowHostShutdownReason =
            | TerminalFlowHostShutdownProcessExit
            | TerminalFlowHostShutdownCancellation
            | TerminalFlowHostShutdownFatalHostException of exceptionRef:uint32

        type TerminalFlowHostShutdownRequest = private {
            requestRef : TerminalFlowIdentityRef<TerminalFlowHostShutdownRequestRefKind>
            reason : TerminalFlowHostShutdownReason
            observedAtMs : int64
            rootReceiptRef : uint32 option
            terminalOutcomeRef : uint32 option
        }

        type TerminalFlowHostShutdownFinalizationReceipt = private {
            receiptRef : TerminalFlowIdentityRef<TerminalFlowHostShutdownFinalizationReceiptRefKind>
            requestRef : TerminalFlowIdentityRef<TerminalFlowHostShutdownRequestRefKind>
            qapResolutionRef : uint32
            totalOrderRef : uint32
            finalizedAtRevision : int64
            exactOnceRef : uint32
        }

        type TerminalFlowHostShutdownReconciliation =
            | TerminalFlowHostShutdownIdle
            | TerminalFlowHostShutdownFinalized of TerminalFlowHostShutdownFinalizationReceipt

        type TerminalFlowHostShutdownReducerDecision =
            | TerminalFlowHostShutdownReconciled of TerminalFlowHostShutdownFinalizationReceipt
            | TerminalFlowHostShutdownFailedClosed of TerminalFlowHostShutdownFinalizationReceipt * failureRef:uint32

        let private terminalFlowHostShutdownReducerDecisionText = function
            | TerminalFlowHostShutdownReconciled receipt ->
                sprintf "shutdown_reconciled|request_ref=%u|total_order_ref=%u" (terminalFlowIdentityRefDigest receipt.requestRef) receipt.totalOrderRef
            | TerminalFlowHostShutdownFailedClosed(receipt, failureRef) ->
                FastRuntimeFormat.format "shutdown_failed_closed|request_ref=%u|failure_ref=%u|total_order_ref=%u" [| box (terminalFlowIdentityRefDigest receipt.requestRef); box failureRef; box receipt.totalOrderRef |]

        type TerminalFlowWakerRegistrationDebtEvidence = {
            ingressRef : uint32
            firstRawLineRef : uint32
            lastRawLineRef : uint32
            authorityRef : uint32
            edgeEvidence : CompilerConsoleHud88.TerminalFlowSemanticIngressEdgeEvidence
            queueDepth : int
            ownerAxis : CompilerConsoleHud88.TerminalFlowSemanticIngressOwnerAxisId
            firstObservedAtMs : int64
            lastObservedAtMs : int64
            distinctObservationCount : int
        }

        type TerminalFlowWakerRegistrationDebtState =
            | TerminalFlowWakerDebtClear
            | TerminalFlowWakerDebtProbation of TerminalFlowWakerRegistrationDebtEvidence
            | TerminalFlowWakerDebtConfirmed of TerminalFlowWakerRegistrationDebtEvidence

        let private terminalFlowWakerRegistrationDebtText = function
            | TerminalFlowWakerDebtClear -> "WakerRegistrationDebt(Clear)"
            | TerminalFlowWakerDebtProbation evidence ->
                FastRuntimeFormat.format "WakerRegistrationDebt(Probation|edge=%s|queue=%d|axis=%s|count=%d|age_ms=%d|authority_ref=%u)" [| box (CompilerConsoleHud88.terminalFlowSemanticIngressEdgeEvidenceText evidence.edgeEvidence); box evidence.queueDepth; box (CompilerConsoleHud88.terminalFlowSemanticIngressOwnerAxisText evidence.ownerAxis); box evidence.distinctObservationCount; box (max 0L (evidence.lastObservedAtMs - evidence.firstObservedAtMs)); box evidence.authorityRef |]
            | TerminalFlowWakerDebtConfirmed evidence ->
                FastRuntimeFormat.format "WakerRegistrationDebt(Confirmed|edge=%s|queue=%d|axis=%s|count=%d|age_ms=%d|authority_ref=%u)" [| box (CompilerConsoleHud88.terminalFlowSemanticIngressEdgeEvidenceText evidence.edgeEvidence); box evidence.queueDepth; box (CompilerConsoleHud88.terminalFlowSemanticIngressOwnerAxisText evidence.ownerAxis); box evidence.distinctObservationCount; box (max 0L (evidence.lastObservedAtMs - evidence.firstObservedAtMs)); box evidence.authorityRef |]

        let private terminalFlowObserveWakerRegistrationDebt previous ingressRef rawLineRef authorityRef edgeEvidence (queueDepthText:string) ownerAxis observedAtMs =
            match System.Int32.TryParse queueDepthText with
            | false, _ -> TerminalFlowWakerDebtClear, false, "waker_debt_projection_only:queue_not_numeric"
            | true, queueDepth when queueDepth <= 0 -> TerminalFlowWakerDebtClear, false, "waker_debt_projection_only:queue_not_positive"
            | true, queueDepth ->
                let freshEvidence = {
                    ingressRef = ingressRef
                    firstRawLineRef = rawLineRef
                    lastRawLineRef = rawLineRef
                    authorityRef = authorityRef
                    edgeEvidence = edgeEvidence
                    queueDepth = queueDepth
                    ownerAxis = ownerAxis
                    firstObservedAtMs = observedAtMs
                    lastObservedAtMs = observedAtMs
                    distinctObservationCount = 1
                }
                let evolve evidence =
                    if evidence.edgeEvidence = edgeEvidence && evidence.ownerAxis = ownerAxis then
                        let distinctObservationCount =
                            if evidence.lastRawLineRef = rawLineRef then evidence.distinctObservationCount
                            else evidence.distinctObservationCount + 1
                        { evidence with
                            lastRawLineRef = rawLineRef
                            authorityRef = authorityRef
                            queueDepth = queueDepth
                            lastObservedAtMs = observedAtMs
                            distinctObservationCount = distinctObservationCount }
                    else freshEvidence
                let evidence =
                    match previous with
                    | TerminalFlowWakerDebtProbation evidence
                    | TerminalFlowWakerDebtConfirmed evidence -> evolve evidence
                    | TerminalFlowWakerDebtClear -> freshEvidence
                let ageMs = max 0L (evidence.lastObservedAtMs - evidence.firstObservedAtMs)
                let confirmed = evidence.distinctObservationCount >= 2 && ageMs >= 30000L
                if confirmed then TerminalFlowWakerDebtConfirmed evidence, true, "waker_debt_confirmed:repeated_positive_queue_after_grace"
                else TerminalFlowWakerDebtProbation evidence, false, "waker_debt_probation:await_distinct_repeat_and_grace"

        // MIGRATION / domain migration migration phase:
        // Dispatch admission and terminal completion remain distinct, but the
        // admission certificate no longer stores an unstructured bag of refs.
        // Every prerequisite is represented by a receipt whose requirement has a
        // named total satisfier.  A missing satisfier is therefore unrepresentable.
        type TerminalFlowDispatchRequirementKind =
            | TerminalFlowDispatchRequireFinalOutcome
            | TerminalFlowDispatchRequireTerminalOutcomeSealed
            | TerminalFlowDispatchRequireActorBinding
            | TerminalFlowDispatchRequireExitOpen
            | TerminalFlowDispatchRequireRootCapability
            | TerminalFlowDispatchRequireWorkDagTailClose
            | TerminalFlowDispatchRequireQueueRecovery
            | TerminalFlowDispatchRequireBreakthrough
            | TerminalFlowDispatchRequireFairness
            | TerminalFlowDispatchRequireSchedulerRelease
            | TerminalFlowDispatchRequireGreenPath
            | TerminalFlowDispatchRequirePredecessorOrder

        let private terminalFlowDispatchRequirementKindText = function
            | TerminalFlowDispatchRequireFinalOutcome -> "final_outcome"
            | TerminalFlowDispatchRequireTerminalOutcomeSealed -> "terminal_outcome_sealed"
            | TerminalFlowDispatchRequireActorBinding -> "actor_binding"
            | TerminalFlowDispatchRequireExitOpen -> "exit_open"
            | TerminalFlowDispatchRequireRootCapability -> "root_capability"
            | TerminalFlowDispatchRequireWorkDagTailClose -> "workdag_tail_close"
            | TerminalFlowDispatchRequireQueueRecovery -> "queue_recovery"
            | TerminalFlowDispatchRequireBreakthrough -> "breakthrough"
            | TerminalFlowDispatchRequireFairness -> "fairness"
            | TerminalFlowDispatchRequireSchedulerRelease -> "scheduler_release"
            | TerminalFlowDispatchRequireGreenPath -> "green_path"
            | TerminalFlowDispatchRequirePredecessorOrder -> "predecessor_order"

        // MIGRATION BONUS : dispatch and total-order minting share one
        // constitution witness.  Loose references are projection data only; the
        // sealed witness proves that owner, WorkDag, recovery, root and order all
        // descend from the same reducer transaction.
        type TerminalFlowConstitutionOpenStage = class end
        type TerminalFlowConstitutionSealedStage = class end

        type TerminalFlowConstitutionViolation =
            | TerminalFlowConstitutionProducerNotSealed
            | TerminalFlowConstitutionWorkDagStillOpen of openOwners:int * acyclic:bool
            | TerminalFlowConstitutionRecoveryMissing
            | TerminalFlowConstitutionRecoveryLineageMismatch of producerRef:uint32 * reducerRef:uint32
            | TerminalFlowConstitutionRootLineageMismatch of producerRef:uint32 * kernelRef:uint32
            | TerminalFlowConstitutionOwnerSealMismatch of producerRef:uint32 * capabilityRef:uint32
            | TerminalFlowConstitutionWorkDagCloseMissing
            | TerminalFlowConstitutionGreenPathMissing
            | TerminalFlowConstitutionPredecessorOrderMissing

        type TerminalFlowConstitutionLineage<'Stage> = private {
            constitutionRef : uint32
            producerCertificateRef : uint32
            workDagTailRef : uint32
            workDagCloseReceiptRef : uint32
            queueRecoveryRef : uint32
            rootCapabilityRef : uint32
            rootReceiptRef : uint32
            greenPathRef : uint32
            predecessorOrderRef : uint32
            exactOnceRef : uint32
        }

        let private terminalFlowConstitutionViolationRequirement = function
            | TerminalFlowConstitutionProducerNotSealed
            | TerminalFlowConstitutionWorkDagStillOpen _
            | TerminalFlowConstitutionWorkDagCloseMissing -> TerminalFlowDispatchRequireWorkDagTailClose
            | TerminalFlowConstitutionRecoveryMissing
            | TerminalFlowConstitutionRecoveryLineageMismatch _ -> TerminalFlowDispatchRequireQueueRecovery
            | TerminalFlowConstitutionRootLineageMismatch _
            | TerminalFlowConstitutionOwnerSealMismatch _ -> TerminalFlowDispatchRequireRootCapability
            | TerminalFlowConstitutionGreenPathMissing -> TerminalFlowDispatchRequireGreenPath
            | TerminalFlowConstitutionPredecessorOrderMissing -> TerminalFlowDispatchRequirePredecessorOrder

        let private terminalFlowConstitutionViolationText = function
            | TerminalFlowConstitutionProducerNotSealed -> "owner_workdag_producer_not_sealed"
            | TerminalFlowConstitutionWorkDagStillOpen(openOwners, acyclic) -> sprintf "workdag_not_closed:open=%d:acyclic=%b" openOwners acyclic
            | TerminalFlowConstitutionRecoveryMissing -> "owner_workdag_queue_recovery_not_ready"
            | TerminalFlowConstitutionRecoveryLineageMismatch(producerRef, reducerRef) -> sprintf "queue_recovery_lineage_mismatch:producer=%u:reducer=%u" producerRef reducerRef
            | TerminalFlowConstitutionRootLineageMismatch(producerRef, kernelRef) -> sprintf "root_capability_lineage_mismatch:producer=%u:kernel=%u" producerRef kernelRef
            | TerminalFlowConstitutionOwnerSealMismatch(producerRef, capabilityRef) -> sprintf "owner_seal_lineage_mismatch:producer=%u:capability=%u" producerRef capabilityRef
            | TerminalFlowConstitutionWorkDagCloseMissing -> "workdag_close_receipt_missing"
            | TerminalFlowConstitutionGreenPathMissing -> "green_path_receipt_zero"
            | TerminalFlowConstitutionPredecessorOrderMissing -> "typed_total_order_predecessor_missing"

        let private terminalFlowConstitutionSeal
            reducerRecoveryRef
            kernelRootReceiptRef
            greenPathRef
            predecessorOrderRef
            producer =
            match producer with
            | TerminalFlowOwnerWorkDagProducerSealed(ownerCertificate, proof, rootCapability, ownerQueueRecovery) ->
                let producerRecoveryRef =
                    match ownerQueueRecovery with
                    | TerminalFlowQueueOnlyRecoveryReady(_, recoveryRef) -> recoveryRef
                    | _ -> 0u
                let workDagTailRef = terminalFlowWorkDagTailRef proof.workDagTail
                if proof.openOwnerCount <> 0 || not proof.acyclicByConstruction then
                    Error (TerminalFlowConstitutionWorkDagStillOpen(proof.openOwnerCount, proof.acyclicByConstruction))
                elif producerRecoveryRef = 0u then
                    Error TerminalFlowConstitutionRecoveryMissing
                elif producerRecoveryRef <> reducerRecoveryRef then
                    Error (TerminalFlowConstitutionRecoveryLineageMismatch(producerRecoveryRef, reducerRecoveryRef))
                elif rootCapability.rootReceiptRef <> kernelRootReceiptRef then
                    Error (TerminalFlowConstitutionRootLineageMismatch(rootCapability.rootReceiptRef, kernelRootReceiptRef))
                elif rootCapability.ownerLedgerSealRef <> ownerCertificate.certificateRef then
                    Error (TerminalFlowConstitutionOwnerSealMismatch(ownerCertificate.certificateRef, rootCapability.ownerLedgerSealRef))
                elif rootCapability.workDagCloseReceiptRef = 0u then
                    Error TerminalFlowConstitutionWorkDagCloseMissing
                elif greenPathRef = 0u then
                    Error TerminalFlowConstitutionGreenPathMissing
                elif predecessorOrderRef = 0u then
                    Error TerminalFlowConstitutionPredecessorOrderMissing
                else
                    let exactOnceRef =
                        terminalFlowMintedRefOf
                            "terminal_constitution_exact_once_ref"
                            (FastRuntimeFormat.format "%u:%u:%u:%u:%u:%u:%u" [| box ownerCertificate.certificateRef; box workDagTailRef; box rootCapability.workDagCloseReceiptRef; box producerRecoveryRef; box rootCapability.capabilityRef; box greenPathRef; box predecessorOrderRef |])
                    let constitutionRef =
                        terminalFlowMintedRefOf
                            "terminal_constitution_ref"
                            (FastRuntimeFormat.format "%u:%u:%u" [| box ownerCertificate.certificateRef; box rootCapability.capabilityRef; box exactOnceRef |])
                    Ok {
                        constitutionRef = constitutionRef
                        producerCertificateRef = ownerCertificate.certificateRef
                        workDagTailRef = workDagTailRef
                        workDagCloseReceiptRef = rootCapability.workDagCloseReceiptRef
                        queueRecoveryRef = producerRecoveryRef
                        rootCapabilityRef = rootCapability.capabilityRef
                        rootReceiptRef = rootCapability.rootReceiptRef
                        greenPathRef = greenPathRef
                        predecessorOrderRef = predecessorOrderRef
                        exactOnceRef = exactOnceRef
                    }
            | _ -> Error TerminalFlowConstitutionProducerNotSealed

        type TerminalFlowConstitutionFixtureExpectation =
            | TerminalFlowConstitutionFixtureShouldSeal
            | TerminalFlowConstitutionFixtureShouldReject of TerminalFlowConstitutionViolation

        type TerminalFlowConstitutionFixtureVector = private {
            fixtureName : string
            decision : Result<TerminalFlowConstitutionLineage<TerminalFlowConstitutionSealedStage>,TerminalFlowConstitutionViolation>
            expectation : TerminalFlowConstitutionFixtureExpectation
        }

        let private terminalFlowConstitutionFixtureVectors qapResolution =
            let opened = terminalFlowOwnerWorkDagOpenForQap 1L 11u 13u 17L 0L 0L 0L
            let canonicalRecoveryRef = 29u
            let producer = terminalFlowOwnerWorkDagSealFullyDrained 2L qapResolution canonicalRecoveryRef opened
            match producer with
            | TerminalFlowOwnerWorkDagProducerSealed(_, _, rootCapability, TerminalFlowQueueOnlyRecoveryReady(_, recoveryRef)) ->
                [ { fixtureName = "positive_same_lineage"
                    decision = terminalFlowConstitutionSeal recoveryRef rootCapability.rootReceiptRef 19u terminalFlowTotalOrderGenesisReceiptRef producer
                    expectation = TerminalFlowConstitutionFixtureShouldSeal }
                  { fixtureName = "negative_recovery_lineage"
                    decision = terminalFlowConstitutionSeal (recoveryRef + 1u) rootCapability.rootReceiptRef 19u terminalFlowTotalOrderGenesisReceiptRef producer
                    expectation = TerminalFlowConstitutionFixtureShouldReject(TerminalFlowConstitutionRecoveryLineageMismatch(recoveryRef, recoveryRef + 1u)) }
                  { fixtureName = "negative_green_path_missing"
                    decision = terminalFlowConstitutionSeal recoveryRef rootCapability.rootReceiptRef 0u terminalFlowTotalOrderGenesisReceiptRef producer
                    expectation = TerminalFlowConstitutionFixtureShouldReject TerminalFlowConstitutionGreenPathMissing }
                  { fixtureName = "negative_predecessor_missing"
                    decision = terminalFlowConstitutionSeal recoveryRef rootCapability.rootReceiptRef 19u 0u producer
                    expectation = TerminalFlowConstitutionFixtureShouldReject TerminalFlowConstitutionPredecessorOrderMissing } ]
            | _ ->
                [ { fixtureName = "producer_failed_to_seal"
                    decision = Error TerminalFlowConstitutionProducerNotSealed
                    expectation = TerminalFlowConstitutionFixtureShouldReject TerminalFlowConstitutionProducerNotSealed } ]

        // MIGRATION / destructive migration migration phase:
        // A requirement is no longer a row whose satisfier happens to be stored
        // beside it. The minter, dependency edges, holder and terminal result are
        // one recursive authority graph. Cycles close with a proof and cannot be
        // overwritten by a later observer projection.
        type TerminalFlowRequirementMinter =
            | TerminalFlowMintFinalOutcome of satisfierRef:uint32
            | TerminalFlowMintTerminalOutcomeSeal of satisfierRef:uint32
            | TerminalFlowMintActorBinding of satisfierRef:uint32
            | TerminalFlowMintExitOpen of satisfierRef:uint32
            | TerminalFlowMintRootCapability of satisfierRef:uint32
            | TerminalFlowMintWorkDagTailClose of satisfierRef:uint32
            | TerminalFlowMintQueueRecovery of satisfierRef:uint32
            | TerminalFlowMintBreakthrough of satisfierRef:uint32
            | TerminalFlowMintFairnessRelease of satisfierRef:uint32
            | TerminalFlowMintSchedulerRelease of satisfierRef:uint32
            | TerminalFlowMintGreenPath of satisfierRef:uint32
            | TerminalFlowMintPredecessorOrder of satisfierRef:uint32

        let private terminalFlowRequirementMinterRef = function
            | TerminalFlowMintFinalOutcome value
            | TerminalFlowMintTerminalOutcomeSeal value
            | TerminalFlowMintActorBinding value
            | TerminalFlowMintExitOpen value
            | TerminalFlowMintRootCapability value
            | TerminalFlowMintWorkDagTailClose value
            | TerminalFlowMintQueueRecovery value
            | TerminalFlowMintBreakthrough value
            | TerminalFlowMintFairnessRelease value
            | TerminalFlowMintSchedulerRelease value
            | TerminalFlowMintGreenPath value
            | TerminalFlowMintPredecessorOrder value -> value

        let private terminalFlowRequirementMinterFor kind identityText =
            let kindText = terminalFlowDispatchRequirementKindText kind
            let satisfierRef = terminalFlowMintedRefOf "terminal_requirement_minter_ref" (identityText + ":" + kindText + ":total")
            match kind with
            | TerminalFlowDispatchRequireFinalOutcome -> TerminalFlowMintFinalOutcome satisfierRef
            | TerminalFlowDispatchRequireTerminalOutcomeSealed -> TerminalFlowMintTerminalOutcomeSeal satisfierRef
            | TerminalFlowDispatchRequireActorBinding -> TerminalFlowMintActorBinding satisfierRef
            | TerminalFlowDispatchRequireExitOpen -> TerminalFlowMintExitOpen satisfierRef
            | TerminalFlowDispatchRequireRootCapability -> TerminalFlowMintRootCapability satisfierRef
            | TerminalFlowDispatchRequireWorkDagTailClose -> TerminalFlowMintWorkDagTailClose satisfierRef
            | TerminalFlowDispatchRequireQueueRecovery -> TerminalFlowMintQueueRecovery satisfierRef
            | TerminalFlowDispatchRequireBreakthrough -> TerminalFlowMintBreakthrough satisfierRef
            | TerminalFlowDispatchRequireFairness -> TerminalFlowMintFairnessRelease satisfierRef
            | TerminalFlowDispatchRequireSchedulerRelease -> TerminalFlowMintSchedulerRelease satisfierRef
            | TerminalFlowDispatchRequireGreenPath -> TerminalFlowMintGreenPath satisfierRef
            | TerminalFlowDispatchRequirePredecessorOrder -> TerminalFlowMintPredecessorOrder satisfierRef

        type TerminalFlowRequirementHolder =
            | TerminalFlowRequirementHeldByRequirement of TerminalFlowDispatchRequirementKind
            | TerminalFlowRequirementHeldByExternalEvidence of observationRef:uint32

        let private terminalFlowRequirementHolderText = function
            | TerminalFlowRequirementHeldByRequirement kind ->
                "Requirement(" + terminalFlowDispatchRequirementKindText kind + ")"
            | TerminalFlowRequirementHeldByExternalEvidence observationRef ->
                sprintf "ExternalEvidence(observation_ref=%u)" observationRef

        type TerminalFlowRequirementCycleProof = private {
            cycleRef : uint32
            path : TerminalFlowDispatchRequirementKind list
            detectedAtMs : int64
            exactOnceRef : uint32
        }

        type TerminalFlowRequirementGraphClosureProof = private {
            closureRef : uint32
            admissionRef : uint32
            ledgerRef : uint32
            nodeCount : int
            evidenceSetRef : uint32
            closedAtMs : int64
            exactOnceRef : uint32
        }

        type TerminalFlowRequirementGraphResult =
            | TerminalFlowRequirementGraphOpen
            | TerminalFlowRequirementGraphSatisfied of TerminalFlowRequirementGraphClosureProof
            | TerminalFlowRequirementGraphCycleClosed of TerminalFlowRequirementCycleProof

        type TerminalFlowRequirementCredentialState =
            | TerminalFlowRequirementCredentialAwaiting of firstObservedAtMs:int64 * lastObservedAtMs:int64
            | TerminalFlowRequirementCredentialHeldBy of holder:TerminalFlowRequirementHolder * observationRef:uint32 * firstObservedAtMs:int64 * lastObservedAtMs:int64
            | TerminalFlowRequirementCredentialSatisfied of evidenceRef:uint32 * satisfiedAtSequence:int64 * satisfiedAtMs:int64
            | TerminalFlowRequirementCredentialCycleClosed of TerminalFlowRequirementCycleProof

        type TerminalFlowRequirementNode = private {
            kind : TerminalFlowDispatchRequirementKind
            requirementRef : uint32
            minter : TerminalFlowRequirementMinter
            credentialRef : uint32
            dependencies : Set<TerminalFlowDispatchRequirementKind>
            state : TerminalFlowRequirementCredentialState
        }

        type TerminalFlowRequirementGraph =
            | TerminalFlowRequirementLeaf of TerminalFlowRequirementNode
            | TerminalFlowRequirementBranch of TerminalFlowRequirementNode * TerminalFlowRequirementGraph list

        type TerminalFlowCredentialLedger = private {
            admissionRef : uint32
            ledgerRef : uint32
            forest : TerminalFlowRequirementGraph list
            index : Map<TerminalFlowDispatchRequirementKind,TerminalFlowRequirementNode>
            result : TerminalFlowRequirementGraphResult
        }

        let private terminalFlowAllDispatchRequirementKinds =
            [ TerminalFlowDispatchRequireFinalOutcome
              TerminalFlowDispatchRequireTerminalOutcomeSealed
              TerminalFlowDispatchRequireActorBinding
              TerminalFlowDispatchRequireExitOpen
              TerminalFlowDispatchRequireRootCapability
              TerminalFlowDispatchRequireWorkDagTailClose
              TerminalFlowDispatchRequireQueueRecovery
              TerminalFlowDispatchRequireBreakthrough
              TerminalFlowDispatchRequireFairness
              TerminalFlowDispatchRequireSchedulerRelease
              TerminalFlowDispatchRequireGreenPath
              TerminalFlowDispatchRequirePredecessorOrder ]

        let private terminalFlowRequirementDependencies = function
            | TerminalFlowDispatchRequireFinalOutcome
            | TerminalFlowDispatchRequireWorkDagTailClose
            | TerminalFlowDispatchRequireFairness -> Set.empty
            | TerminalFlowDispatchRequireTerminalOutcomeSealed -> Set.singleton TerminalFlowDispatchRequireFinalOutcome
            | TerminalFlowDispatchRequireActorBinding -> Set.singleton TerminalFlowDispatchRequireTerminalOutcomeSealed
            | TerminalFlowDispatchRequireExitOpen -> Set.singleton TerminalFlowDispatchRequireActorBinding
            | TerminalFlowDispatchRequireRootCapability -> Set.singleton TerminalFlowDispatchRequireWorkDagTailClose
            | TerminalFlowDispatchRequireSchedulerRelease -> Set.singleton TerminalFlowDispatchRequireFairness
            | TerminalFlowDispatchRequireQueueRecovery -> Set.ofList [ TerminalFlowDispatchRequireFairness; TerminalFlowDispatchRequireSchedulerRelease ]
            | TerminalFlowDispatchRequireGreenPath -> Set.singleton TerminalFlowDispatchRequireQueueRecovery
            | TerminalFlowDispatchRequireBreakthrough -> Set.ofList [ TerminalFlowDispatchRequireRootCapability; TerminalFlowDispatchRequireGreenPath ]
            | TerminalFlowDispatchRequirePredecessorOrder -> Set.singleton TerminalFlowDispatchRequireBreakthrough

        let rec private terminalFlowRequirementGraphFor index visited kind =
            let node = Map.find kind index
            if Set.contains kind visited then TerminalFlowRequirementLeaf node
            else
                let nextVisited = Set.add kind visited
                let children =
                    node.dependencies
                    |> Set.toList
                    |> List.map (terminalFlowRequirementGraphFor index nextVisited)
                if List.isEmpty children then TerminalFlowRequirementLeaf node
                else TerminalFlowRequirementBranch(node, children)

        let private terminalFlowRequirementForestFor index =
            [ TerminalFlowDispatchRequireExitOpen
              TerminalFlowDispatchRequirePredecessorOrder ]
            |> List.map (terminalFlowRequirementGraphFor index Set.empty)

        let rec private terminalFlowRequirementGraphNodes = function
            | TerminalFlowRequirementLeaf node -> [ node ]
            | TerminalFlowRequirementBranch(node, children) ->
                node :: (children |> List.collect terminalFlowRequirementGraphNodes)

        let private terminalFlowRequirementIndexForForest forest =
            forest
            |> List.collect terminalFlowRequirementGraphNodes
            |> List.fold (fun index node -> Map.add node.kind node index) Map.empty

        let private terminalFlowCredentialLedgerWithIndex sourceIndex ledger =
            let forest = terminalFlowRequirementForestFor sourceIndex
            let derivedIndex = terminalFlowRequirementIndexForForest forest
            if derivedIndex.Count <> sourceIndex.Count then
                invalidOp "recursive requirement forest did not preserve every indexed node"
            { ledger with
                forest = forest
                index = derivedIndex }

        let private terminalFlowCredentialLedgerCycleProof ledger =
            match ledger.result with
            | TerminalFlowRequirementGraphCycleClosed proof -> Some proof
            | _ -> None

        let private terminalFlowCredentialLedgerClosureProof ledger =
            match ledger.result with
            | TerminalFlowRequirementGraphSatisfied proof -> Some proof
            | _ -> None

        let private terminalFlowCredentialLedgerClosureRef ledger =
            terminalFlowCredentialLedgerClosureProof ledger
            |> Option.map (fun proof -> proof.closureRef)
            |> Option.defaultValue 0u

        let private terminalFlowRequirementHolderFor kind observationRef =
            match kind with
            | TerminalFlowDispatchRequireFairness -> TerminalFlowRequirementHeldByRequirement TerminalFlowDispatchRequireSchedulerRelease
            | TerminalFlowDispatchRequireSchedulerRelease -> TerminalFlowRequirementHeldByRequirement TerminalFlowDispatchRequireFairness
            | TerminalFlowDispatchRequireQueueRecovery -> TerminalFlowRequirementHeldByRequirement TerminalFlowDispatchRequireFairness
            | TerminalFlowDispatchRequireGreenPath -> TerminalFlowRequirementHeldByRequirement TerminalFlowDispatchRequireQueueRecovery
            | TerminalFlowDispatchRequireBreakthrough -> TerminalFlowRequirementHeldByRequirement TerminalFlowDispatchRequireGreenPath
            | TerminalFlowDispatchRequirePredecessorOrder -> TerminalFlowRequirementHeldByRequirement TerminalFlowDispatchRequireBreakthrough
            | TerminalFlowDispatchRequireRootCapability -> TerminalFlowRequirementHeldByRequirement TerminalFlowDispatchRequireWorkDagTailClose
            | TerminalFlowDispatchRequireTerminalOutcomeSealed -> TerminalFlowRequirementHeldByRequirement TerminalFlowDispatchRequireFinalOutcome
            | TerminalFlowDispatchRequireActorBinding -> TerminalFlowRequirementHeldByRequirement TerminalFlowDispatchRequireTerminalOutcomeSealed
            | TerminalFlowDispatchRequireExitOpen -> TerminalFlowRequirementHeldByRequirement TerminalFlowDispatchRequireActorBinding
            | TerminalFlowDispatchRequireFinalOutcome
            | TerminalFlowDispatchRequireWorkDagTailClose -> TerminalFlowRequirementHeldByExternalEvidence observationRef

        let private terminalFlowCredentialLedgerFor identity nowMs =
            let admissionRef = terminalFlowAdmissionRawRef identity
            let index =
                terminalFlowAllDispatchRequirementKinds
                |> List.map (fun kind ->
                    let kindText = terminalFlowDispatchRequirementKindText kind
                    let identityText = sprintf "%u:%s" admissionRef kindText
                    kind,
                    { kind = kind
                      requirementRef = terminalFlowMintedRefOf "terminal_stable_requirement_ref" identityText
                      minter = terminalFlowRequirementMinterFor kind identityText
                      credentialRef = terminalFlowMintedRefOf "terminal_stable_credential_ref" identityText
                      dependencies = terminalFlowRequirementDependencies kind
                      state = TerminalFlowRequirementCredentialAwaiting(nowMs, nowMs) })
                |> Map.ofList
            let forest = terminalFlowRequirementForestFor index
            { admissionRef = admissionRef
              ledgerRef = terminalFlowAdmissionRequirementLedgerRef identity
              forest = forest
              index = index
              result = TerminalFlowRequirementGraphOpen }

        let private terminalFlowCredentialLedgerEnsure identity nowMs current =
            match current with
            | Some ledger when ledger.admissionRef = terminalFlowAdmissionRawRef identity -> ledger
            | _ -> terminalFlowCredentialLedgerFor identity nowMs

        let private terminalFlowRequirementStateFirstObservedAtMs = function
            | TerminalFlowRequirementCredentialAwaiting(firstObservedAtMs, _)
            | TerminalFlowRequirementCredentialHeldBy(_, _, firstObservedAtMs, _) -> firstObservedAtMs
            | TerminalFlowRequirementCredentialSatisfied(_, _, satisfiedAtMs) -> satisfiedAtMs
            | TerminalFlowRequirementCredentialCycleClosed proof -> proof.detectedAtMs

        let private terminalFlowRequirementStateAuthorityRef = function
            | TerminalFlowRequirementCredentialAwaiting _ ->
                terminalFlowMintedRefOf "terminal_requirement_awaiting_state_ref" "awaiting"
            | TerminalFlowRequirementCredentialHeldBy(holder, observationRef, _, _) ->
                terminalFlowMintedRefOf "terminal_requirement_held_state_ref" (sprintf "%s:%u" (terminalFlowRequirementHolderText holder) observationRef)
            | TerminalFlowRequirementCredentialSatisfied(evidenceRef, satisfiedAtSequence, _) ->
                terminalFlowMintedRefOf "terminal_requirement_satisfied_state_ref" (sprintf "%u:%d" evidenceRef satisfiedAtSequence)
            | TerminalFlowRequirementCredentialCycleClosed proof -> proof.exactOnceRef

        let private terminalFlowCredentialLedgerDetectCycle nowMs ledger =
            let outgoing kind =
                let node = Map.find kind ledger.index
                let holderEdges =
                    match node.state with
                    | TerminalFlowRequirementCredentialHeldBy(TerminalFlowRequirementHeldByRequirement holderKind, _, _, _) -> [ holderKind ]
                    | _ -> []
                (Set.toList node.dependencies) @ holderEdges |> List.distinct
            let rec visit stack kind =
                match stack |> List.tryFindIndex ((=) kind) with
                | Some cycleStart -> Some ((stack |> List.skip cycleStart) @ [ kind ])
                | None -> outgoing kind |> List.tryPick (visit (stack @ [ kind ]))
            terminalFlowAllDispatchRequirementKinds
            |> List.tryPick (visit [])
            |> Option.map (fun path ->
                let pathText = path |> List.map terminalFlowDispatchRequirementKindText |> String.concat "->"
                let pathAuthorityText =
                    path
                    |> List.map (fun kind ->
                        let node = Map.find kind ledger.index
                        FastRuntimeFormat.format "%u:%u:%u:%u" [| box node.requirementRef; box (terminalFlowRequirementMinterRef node.minter); box node.credentialRef; box (terminalFlowRequirementStateAuthorityRef node.state) |])
                    |> String.concat "->"
                let cycleRef = terminalFlowMintedRefOf "terminal_requirement_cycle_ref" (FastRuntimeFormat.format "%u:%s:%s" [| box ledger.admissionRef; box pathText; box pathAuthorityText |])
                { cycleRef = cycleRef
                  path = path
                  detectedAtMs = nowMs
                  exactOnceRef = terminalFlowMintedRefOf "terminal_requirement_cycle_exact_once_ref" (FastRuntimeFormat.format "%u:%u:%s" [| box ledger.ledgerRef; box cycleRef; box pathAuthorityText |]) })

        let private terminalFlowCredentialLedgerCloseCycle nowMs ledger =
            match ledger.result with
            | TerminalFlowRequirementGraphCycleClosed _
            | TerminalFlowRequirementGraphSatisfied _ -> ledger
            | TerminalFlowRequirementGraphOpen ->
                match terminalFlowCredentialLedgerDetectCycle nowMs ledger with
                | None -> ledger
                | Some proof ->
                    let cycleKinds = proof.path |> Set.ofList
                    let index =
                        ledger.index
                        |> Map.map (fun kind node ->
                            if Set.contains kind cycleKinds then { node with state = TerminalFlowRequirementCredentialCycleClosed proof }
                            else node)
                    { ledger with result = TerminalFlowRequirementGraphCycleClosed proof }
                    |> terminalFlowCredentialLedgerWithIndex index

        let private terminalFlowCredentialLedgerRefreshClosure nowMs ledger =
            match ledger.result with
            | TerminalFlowRequirementGraphCycleClosed _
            | TerminalFlowRequirementGraphSatisfied _ -> ledger
            | TerminalFlowRequirementGraphOpen ->
                let allSatisfied =
                    ledger.index
                    |> Map.forall (fun _ node ->
                        match node.state with
                        | TerminalFlowRequirementCredentialSatisfied _ -> true
                        | _ -> false)
                if not allSatisfied then ledger
                else
                    let evidenceSetText =
                        ledger.index
                        |> Map.toList
                        |> List.map (fun (kind, node) ->
                            FastRuntimeFormat.format "%s:%u:%u:%u:%u" [| box (terminalFlowDispatchRequirementKindText kind); box node.requirementRef; box (terminalFlowRequirementMinterRef node.minter); box node.credentialRef; box (terminalFlowRequirementStateAuthorityRef node.state) |])
                        |> String.concat "|"
                    let evidenceSetRef = terminalFlowMintedRefOf "terminal_requirement_graph_evidence_set_ref" evidenceSetText
                    let closureRef = terminalFlowMintedRefOf "terminal_requirement_graph_closure_ref" (FastRuntimeFormat.format "%u:%u:%u" [| box ledger.admissionRef; box ledger.ledgerRef; box evidenceSetRef |])
                    let exactOnceRef = terminalFlowMintedRefOf "terminal_requirement_graph_closure_exact_once_ref" (FastRuntimeFormat.format "%u:%u:%u" [| box closureRef; box evidenceSetRef; box (uint32 ledger.index.Count) |])
                    { ledger with
                        result =
                            TerminalFlowRequirementGraphSatisfied {
                                closureRef = closureRef
                                admissionRef = ledger.admissionRef
                                ledgerRef = ledger.ledgerRef
                                nodeCount = ledger.index.Count
                                evidenceSetRef = evidenceSetRef
                                closedAtMs = nowMs
                                exactOnceRef = exactOnceRef
                            } }

        type TerminalFlowRequirementMinterDecision =
            | TerminalFlowRequirementMinterCommitted
            | TerminalFlowRequirementMinterCoalesced
            | TerminalFlowRequirementMinterRejectedByCycle of cycleRef:uint32

        type TerminalFlowDispatchRequirementReceipt = private {
            kind : TerminalFlowDispatchRequirementKind
            requirementRef : uint32
            satisfierRef : uint32
            credentialRef : uint32
            evidenceRef : uint32
            decision : TerminalFlowRequirementMinterDecision
            satisfiedAtSequence : int64
            ageMs : int64
        }

        type TerminalFlowDispatchRequirementSpine =
            | TerminalFlowDispatchRequirementsClosed
            | TerminalFlowDispatchRequirementCons of TerminalFlowDispatchRequirementReceipt * TerminalFlowDispatchRequirementSpine

        let private terminalFlowRequirementMinterDecisionText = function
            | TerminalFlowRequirementMinterCommitted -> "Committed"
            | TerminalFlowRequirementMinterCoalesced -> "Coalesced"
            | TerminalFlowRequirementMinterRejectedByCycle cycleRef -> sprintf "RejectedByCycle(%u)" cycleRef

        let rec private terminalFlowDispatchRequirementSpineText = function
            | TerminalFlowDispatchRequirementsClosed -> "End"
            | TerminalFlowDispatchRequirementCons(receipt, rest) ->
                FastRuntimeFormat.format "%s(req=%u|satisfier=%u|credential=%u|evidence=%u|decision=%s|age_ms=%d)->%s" [| box (terminalFlowDispatchRequirementKindText receipt.kind); box receipt.requirementRef; box receipt.satisfierRef; box receipt.credentialRef; box receipt.evidenceRef; box (terminalFlowRequirementMinterDecisionText receipt.decision); box receipt.ageMs; box (terminalFlowDispatchRequirementSpineText rest) |]

        type TerminalFlowDispatchRequirementBlocker = private {
            kind : TerminalFlowDispatchRequirementKind
            requirementRef : uint32
            satisfierRef : uint32
            blockerRef : uint32
            ageMs : int64
            reason : CompilerKernelV2.OperationalReasonId
        }

        type TerminalFlowCredentialLedgerObservationMode =
            | TerminalFlowCredentialLedgerSilent
            | TerminalFlowCredentialLedgerObserved

        let private terminalFlowCredentialLedgerObservationEnabled = function
            | TerminalFlowCredentialLedgerSilent -> false
            | TerminalFlowCredentialLedgerObserved -> true

        let private terminalFlowCredentialLedgerBlock observationMode kind reason nowMs ledger =
            let credential = ledger.index.[kind]
            let firstObservedAtMs = terminalFlowRequirementStateFirstObservedAtMs credential.state
            let effectiveReason =
                match credential.state with
                | TerminalFlowRequirementCredentialCycleClosed _ -> "credential_cycle_already_closed"
                | TerminalFlowRequirementCredentialSatisfied _
                | TerminalFlowRequirementCredentialAwaiting _
                | TerminalFlowRequirementCredentialHeldBy _ -> reason
            let observationRef = terminalFlowMintedRefOf "terminal_requirement_block_observation_ref" (FastRuntimeFormat.format "%u:%s:%s" [| box ledger.ledgerRef; box (terminalFlowDispatchRequirementKindText kind); box reason |])
            let updated =
                match ledger.result, credential.state with
                | TerminalFlowRequirementGraphOpen, TerminalFlowRequirementCredentialSatisfied _
                | TerminalFlowRequirementGraphOpen, TerminalFlowRequirementCredentialCycleClosed _ -> credential
                | TerminalFlowRequirementGraphOpen, _ ->
                    { credential with
                        state = TerminalFlowRequirementCredentialHeldBy(terminalFlowRequirementHolderFor kind observationRef, observationRef, firstObservedAtMs, nowMs) }
                | TerminalFlowRequirementGraphSatisfied _, _
                | TerminalFlowRequirementGraphCycleClosed _, _ -> credential
            let beforeCycle = terminalFlowCredentialLedgerCycleProof ledger
            let nextLedger =
                ledger
                |> terminalFlowCredentialLedgerWithIndex (ledger.index.Add(kind, updated))
                |> terminalFlowCredentialLedgerCloseCycle nowMs
            if terminalFlowCredentialLedgerObservationEnabled observationMode then
                match beforeCycle, terminalFlowCredentialLedgerCycleProof nextLedger with
                | None, Some proof ->
                    let pathText = proof.path |> List.map terminalFlowDispatchRequirementKindText |> String.concat "->"
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_requirement_cycle_closed\",\"cycle_ref\":%u,\"exact_once_ref\":%u,\"path_du\":%s,\"detected_at_ms\":%d,\"authority\":\"recursive_requirement_graph\"}" [| box proof.cycleRef; box proof.exactOnceRef; box (DiagJson.esc pathText); box proof.detectedAtMs |])
                    terminalFlowEmitAdvancedConsoleProjection {
                        lane = TerminalFlowConsoleLaneCredentialGraph
                        sequence = int64 proof.exactOnceRef
                        progressBp = 9990
                        etaMs = None
                        title = "credential graph cycle closed"
                        detail = FastRuntimeFormat.format "CycleClosed|cycle_ref=%u|path=%s|exact_once_ref=%u" [| box proof.cycleRef; box pathText; box proof.exactOnceRef |]
                        authorityRef = proof.exactOnceRef
                    }
                | _ -> ()
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_requirement_holder_changed\",\"requirement_du\":%s,\"requirement_ref\":%u,\"minter_ref\":%u,\"credential_ref\":%u,\"observation_ref\":%u,\"cycle_ref\":%u,\"authority\":\"recursive_requirement_graph\"}" [| box (DiagJson.esc (terminalFlowDispatchRequirementKindText kind)); box credential.requirementRef; box (terminalFlowRequirementMinterRef credential.minter); box credential.credentialRef; box observationRef; box (terminalFlowCredentialLedgerCycleProof nextLedger |> Option.map (fun proof -> proof.cycleRef) |> Option.defaultValue 0u) |])
            nextLedger,
            { kind = kind
              requirementRef = credential.requirementRef
              satisfierRef = terminalFlowRequirementMinterRef credential.minter
              blockerRef = credential.credentialRef
              ageMs = max 0L (nowMs - firstObservedAtMs)
              reason = CompilerKernelV2.OperationalReasonIdOps.create effectiveReason }

        let private terminalFlowCredentialLedgerBlockSilent kind reason nowMs ledger =
            terminalFlowCredentialLedgerBlock
                TerminalFlowCredentialLedgerSilent
                kind
                reason
                nowMs
                ledger

        let private terminalFlowCredentialLedgerBlockObserved kind reason nowMs ledger =
            terminalFlowCredentialLedgerBlock
                TerminalFlowCredentialLedgerObserved
                kind
                reason
                nowMs
                ledger

        let private terminalFlowCredentialLedgerSatisfy observationMode kind evidenceRef sequence nowMs ledger =
            let beforeClosureRef = terminalFlowCredentialLedgerClosureRef ledger
            let credential = ledger.index.[kind]
            let firstObservedAtMs = terminalFlowRequirementStateFirstObservedAtMs credential.state
            let decision =
                match ledger.result, credential.state with
                | TerminalFlowRequirementGraphCycleClosed proof, _ ->
                    TerminalFlowRequirementMinterRejectedByCycle proof.cycleRef
                | TerminalFlowRequirementGraphSatisfied _, _ ->
                    TerminalFlowRequirementMinterCoalesced
                | TerminalFlowRequirementGraphOpen, TerminalFlowRequirementCredentialCycleClosed proof ->
                    TerminalFlowRequirementMinterRejectedByCycle proof.cycleRef
                | TerminalFlowRequirementGraphOpen, TerminalFlowRequirementCredentialSatisfied _ ->
                    TerminalFlowRequirementMinterCoalesced
                | TerminalFlowRequirementGraphOpen, _ ->
                    TerminalFlowRequirementMinterCommitted
            let acceptedEvidenceRef =
                match decision, credential.state with
                | TerminalFlowRequirementMinterCoalesced, TerminalFlowRequirementCredentialSatisfied(existingEvidenceRef, _, _) -> existingEvidenceRef
                | TerminalFlowRequirementMinterRejectedByCycle _, _ -> 0u
                | _ -> evidenceRef
            let updated =
                match decision with
                | TerminalFlowRequirementMinterCommitted ->
                    { credential with state = TerminalFlowRequirementCredentialSatisfied(evidenceRef, sequence, nowMs) }
                | TerminalFlowRequirementMinterCoalesced
                | TerminalFlowRequirementMinterRejectedByCycle _ -> credential
            let nextLedger =
                ledger
                |> terminalFlowCredentialLedgerWithIndex (ledger.index.Add(kind, updated))
                |> terminalFlowCredentialLedgerRefreshClosure nowMs
            let eventKind =
                match decision with
                | TerminalFlowRequirementMinterCommitted -> "terminal_requirement_minter_committed"
                | TerminalFlowRequirementMinterCoalesced -> "terminal_requirement_minter_coalesced"
                | TerminalFlowRequirementMinterRejectedByCycle _ -> "terminal_requirement_minter_rejected_by_cycle"
            if terminalFlowCredentialLedgerObservationEnabled observationMode then
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":%s,\"requirement_du\":%s,\"requirement_ref\":%u,\"minter_ref\":%u,\"credential_ref\":%u,\"requested_evidence_ref\":%u,\"accepted_evidence_ref\":%u,\"minter_decision_du\":%s,\"graph_closure_ref\":%u,\"cycle_ref\":%u,\"authority\":\"recursive_requirement_graph\"}" [| box (DiagJson.esc eventKind); box (DiagJson.esc (terminalFlowDispatchRequirementKindText kind)); box credential.requirementRef; box (terminalFlowRequirementMinterRef credential.minter); box credential.credentialRef; box evidenceRef; box acceptedEvidenceRef; box (DiagJson.esc (terminalFlowRequirementMinterDecisionText decision)); box (terminalFlowCredentialLedgerClosureRef nextLedger); box (terminalFlowCredentialLedgerCycleProof nextLedger |> Option.map (fun proof -> proof.cycleRef) |> Option.defaultValue 0u) |])
                if beforeClosureRef = 0u && (terminalFlowCredentialLedgerClosureRef nextLedger) <> 0u then
                    terminalFlowEmitAdvancedConsoleProjection {
                        lane = TerminalFlowConsoleLaneCredentialGraph
                        sequence = sequence
                        progressBp = 9994
                        etaMs = None
                        title = "credential graph closed"
                        detail = FastRuntimeFormat.format "Closed|graph_closure_ref=%u|ledger_ref=%u|requirement_count=%d" [| box (terminalFlowCredentialLedgerClosureRef nextLedger); box nextLedger.ledgerRef; box nextLedger.index.Count |]
                        authorityRef = (terminalFlowCredentialLedgerClosureRef nextLedger)
                    }
            nextLedger,
            { kind = kind
              requirementRef = credential.requirementRef
              satisfierRef = terminalFlowRequirementMinterRef credential.minter
              credentialRef = credential.credentialRef
              evidenceRef = acceptedEvidenceRef
              decision = decision
              satisfiedAtSequence = sequence
              ageMs = max 0L (nowMs - firstObservedAtMs) }

        let private terminalFlowCredentialLedgerSatisfyRequirements observationMode items sequence nowMs ledger =
            let nextLedger, receiptsRev =
                items
                |> List.fold (fun (currentLedger, receipts) (kind, evidenceRef) ->
                    let updatedLedger, receipt = terminalFlowCredentialLedgerSatisfy observationMode kind evidenceRef sequence nowMs currentLedger
                    updatedLedger, receipt :: receipts) (ledger, [])
            let orderedReceipts = List.rev receiptsRev
            let requirements =
                List.foldBack
                    (fun receipt rest -> TerminalFlowDispatchRequirementCons(receipt, rest))
                    orderedReceipts
                    TerminalFlowDispatchRequirementsClosed
            nextLedger, requirements

        let private terminalFlowCredentialLedgerSatisfyRequirementsSilent items sequence nowMs ledger =
            terminalFlowCredentialLedgerSatisfyRequirements
                TerminalFlowCredentialLedgerSilent
                items
                sequence
                nowMs
                ledger

        let private terminalFlowCredentialLedgerSatisfyRequirementsObserved items sequence nowMs ledger =
            terminalFlowCredentialLedgerSatisfyRequirements
                TerminalFlowCredentialLedgerObserved
                items
                sequence
                nowMs
                ledger

        type TerminalFlowCredentialGraphFixtureExpectation =
            | TerminalFlowCredentialGraphExpectOpen
            | TerminalFlowCredentialGraphExpectSatisfied
            | TerminalFlowCredentialGraphExpectCycleClosed

        type TerminalFlowCredentialGraphFixtureVector = private {
            name : string
            expected : TerminalFlowCredentialGraphFixtureExpectation
            observed : TerminalFlowCredentialGraphFixtureExpectation
            allMintersPresent : bool
            forestIndexCoherent : bool
            satisfierContractComplete : bool
        }

        let private terminalFlowCredentialGraphFixtureObservation ledger =
            match ledger.result with
            | TerminalFlowRequirementGraphOpen -> TerminalFlowCredentialGraphExpectOpen
            | TerminalFlowRequirementGraphSatisfied _ -> TerminalFlowCredentialGraphExpectSatisfied
            | TerminalFlowRequirementGraphCycleClosed _ -> TerminalFlowCredentialGraphExpectCycleClosed

        let private terminalFlowCredentialGraphFixtureVectors () =
            let identity = terminalFlowAdmissionIdentityFor "fixture-terminal" "fixture-fill" 71u
            let fresh = terminalFlowCredentialLedgerFor identity 100L
            let oneHold, _ = terminalFlowCredentialLedgerBlockSilent TerminalFlowDispatchRequireFairness "fixture_wait_scheduler" 110L fresh
            let mutualHold, _ = terminalFlowCredentialLedgerBlockSilent TerminalFlowDispatchRequireSchedulerRelease "fixture_wait_fairness" 120L oneHold
            let requirementUniverse = terminalFlowAllDispatchRequirementKinds |> Set.ofList
            let allMinters ledger = ledger.index |> Map.forall (fun _ node -> terminalFlowRequirementMinterRef node.minter <> 0u)
            let forestIndexCoherent ledger = terminalFlowRequirementIndexForForest ledger.forest = ledger.index
            let satisfierContractComplete ledger =
                ledger.index
                |> Map.forall (fun kind node ->
                    node.kind = kind
                    && terminalFlowRequirementMinterRef node.minter <> 0u
                    && not (Set.contains kind node.dependencies)
                    && Set.isSubset node.dependencies requirementUniverse)
            let satisfied, _ =
                terminalFlowAllDispatchRequirementKinds
                |> List.map (fun kind -> kind, terminalFlowMintedRefOf "fixture_evidence" (terminalFlowDispatchRequirementKindText kind))
                |> fun items -> terminalFlowCredentialLedgerSatisfyRequirementsSilent items 3L 130L fresh
            [| { name = "fresh_graph_is_open"; expected = TerminalFlowCredentialGraphExpectOpen; observed = terminalFlowCredentialGraphFixtureObservation fresh; allMintersPresent = allMinters fresh; forestIndexCoherent = forestIndexCoherent fresh; satisfierContractComplete = satisfierContractComplete fresh }
               { name = "fairness_waiting_on_scheduler_closes_cycle"; expected = TerminalFlowCredentialGraphExpectCycleClosed; observed = terminalFlowCredentialGraphFixtureObservation oneHold; allMintersPresent = allMinters oneHold; forestIndexCoherent = forestIndexCoherent oneHold; satisfierContractComplete = satisfierContractComplete oneHold }
               { name = "cycle_proof_survives_later_observation"; expected = TerminalFlowCredentialGraphExpectCycleClosed; observed = terminalFlowCredentialGraphFixtureObservation mutualHold; allMintersPresent = allMinters mutualHold; forestIndexCoherent = forestIndexCoherent mutualHold; satisfierContractComplete = satisfierContractComplete mutualHold }
               { name = "all_minters_produce_positive_closure"; expected = TerminalFlowCredentialGraphExpectSatisfied; observed = terminalFlowCredentialGraphFixtureObservation satisfied; allMintersPresent = allMinters satisfied; forestIndexCoherent = forestIndexCoherent satisfied; satisfierContractComplete = satisfierContractComplete satisfied } |]

        let private terminalFlowCredentialGraphFixtureProven () =
            terminalFlowCredentialGraphFixtureVectors ()
            |> Array.forall (fun vector ->
                vector.expected = vector.observed
                && vector.allMintersPresent
                && vector.forestIndexCoherent
                && vector.satisfierContractComplete)

        // Destructive domain migration round 2/5: dispatch authority is a recursive
        // proof spine, not a bag of refs.  Each later stage owns the typed evidence
        // for the immediately preceding stage, so impossible cross-generation mixes
        // cannot be represented by the sealed admission certificate.
        type TerminalFlowDispatchAdmissionBornProof = private {
            identity : TerminalFlowAdmissionIdentity
        }

        type TerminalFlowDispatchFairnessBoundProof = private {
            admission : TerminalFlowDispatchAdmissionBornProof
            fairnessRelease : TerminalFlowFairnessReleaseReceipt
        }

        type TerminalFlowDispatchSchedulerBoundProof = private {
            fairness : TerminalFlowDispatchFairnessBoundProof
            schedulerRelease : TerminalFlowSchedulerPhysicalReleaseReceipt
        }

        let private terminalFlowDispatchSchedulerBoundProofFor
            (identity:TerminalFlowAdmissionIdentity)
            (fairnessRelease:TerminalFlowFairnessReleaseReceipt)
            (schedulerRelease:TerminalFlowSchedulerPhysicalReleaseReceipt)
            : TerminalFlowDispatchSchedulerBoundProof =
            { fairness =
                { admission = { identity = identity }
                  fairnessRelease = fairnessRelease }
              schedulerRelease = schedulerRelease }

        type TerminalFlowDispatchCredentialGraphBoundProof = private {
            scheduler : TerminalFlowDispatchSchedulerBoundProof
            closure : TerminalFlowRequirementGraphClosureProof
            requirements : TerminalFlowDispatchRequirementSpine
        }

        type TerminalFlowDispatchCredentialGraphBindError =
            | TerminalFlowDispatchCredentialGraphStillOpen
            | TerminalFlowDispatchCredentialGraphCycleClosed of TerminalFlowRequirementCycleProof

        let private terminalFlowDispatchCredentialGraphBoundProofFor scheduler requirements ledger =
            match terminalFlowCredentialLedgerClosureProof ledger with
            | Some closure ->
                Ok { scheduler = scheduler; closure = closure; requirements = requirements }
            | None ->
                match terminalFlowCredentialLedgerCycleProof ledger with
                | Some cycle -> Error (TerminalFlowDispatchCredentialGraphCycleClosed cycle)
                | None -> Error TerminalFlowDispatchCredentialGraphStillOpen

        type TerminalFlowDispatchFinalOutcomeBoundProof = private {
            credentialGraph : TerminalFlowDispatchCredentialGraphBoundProof
            finalOutcome : TerminalFlowOutcomeMaturityToken<TerminalFlowOutcomeFinalStage>
        }

        type TerminalFlowDispatchTerminalOutcomeSealedProof = private {
            finalOutcome : TerminalFlowDispatchFinalOutcomeBoundProof
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            fillKey : TerminalFlowFillKeyId
        }

        type TerminalFlowDispatchOwnerWorkDagBoundProof = private {
            terminalOutcome : TerminalFlowDispatchTerminalOutcomeSealedProof
            ownerCertificate : TerminalFlowOwnerLedgerCloseCertificate<ProceduralResidualOwnerKind>
            workDagTailProof : TerminalFlowWorkDagTailCloseProof<ProceduralResidualOwnerKind>
            rootCapability : TerminalFlowWorkDagRootCapability<TerminalFlowRootResolvedByWorkDagCloseStage>
            kernelRootReceiptRef : TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>
        }

        type TerminalFlowDispatchQueueRecoveryBoundProof = private {
            ownerWorkDag : TerminalFlowDispatchOwnerWorkDagBoundProof
            recovery : TerminalFlowQueueRecoveryCertificate
        }

        type TerminalFlowDispatchBreakthroughBoundProof = private {
            queueRecovery : TerminalFlowDispatchQueueRecoveryBoundProof
            breakthrough : TerminalFlowBreakthroughCertificate<TerminalFlowBreakthroughPromotableStage>
        }

        type TerminalFlowDispatchGreenPathReceiptProjection = private {
            receiptRef : uint32
            predecessorRef : uint32 option
            fillKey : TerminalFlowFillKeyId
            exactOnce : bool
        }

        type TerminalFlowDispatchGreenPathWitness =
            | TerminalFlowDispatchGreenPathOpenWitness of
                receipt:TerminalFlowGreenPathReceipt<TerminalFlowGreenPathOpenStage> *
                transaction:TerminalFlowForceOwnerCloseTransaction
            | TerminalFlowDispatchGreenPathWriterBoundWitness of
                receipt:TerminalFlowGreenPathReceipt<TerminalFlowGreenPathWriterBoundStage> *
                transaction:TerminalFlowForceOwnerCloseTransaction *
                writerReceiptId:string
            with
                member this.receipt : TerminalFlowDispatchGreenPathReceiptProjection =
                    match this with
                    | TerminalFlowDispatchGreenPathOpenWitness(receipt, _) ->
                        { receiptRef = receipt.receiptRef
                          predecessorRef = receipt.predecessorRef
                          fillKey = receipt.fillKey
                          exactOnce = receipt.exactOnce }
                    | TerminalFlowDispatchGreenPathWriterBoundWitness(receipt, _, _) ->
                        { receiptRef = receipt.receiptRef
                          predecessorRef = receipt.predecessorRef
                          fillKey = receipt.fillKey
                          exactOnce = receipt.exactOnce }

        let private terminalFlowDispatchGreenPathWitnessStageText = function
            | TerminalFlowDispatchGreenPathOpenWitness _ -> "Open"
            | TerminalFlowDispatchGreenPathWriterBoundWitness(_, _, writerReceiptId) ->
                "WriterBound(writer=" + writerReceiptId + ")"

        type TerminalFlowDispatchGreenPathBindError =
            | TerminalFlowDispatchGreenPathMissingOpen
            | TerminalFlowDispatchGreenPathAlreadyArtifactCommitted
            | TerminalFlowDispatchGreenPathAlreadyTerminalCommitted
            | TerminalFlowDispatchGreenPathAlreadyRunEnded
            | TerminalFlowDispatchGreenPathAlreadyPhysicalExit
            | TerminalFlowDispatchGreenPathRejected of TerminalFlowGreenPathRejectReasonId

        let private terminalFlowDispatchGreenPathWitnessFor = function
            | TerminalFlowGreenPathOpen(receipt, transaction) ->
                Ok (TerminalFlowDispatchGreenPathOpenWitness(receipt, transaction))
            | TerminalFlowGreenPathWriterBound(receipt, transaction, writerReceiptId) ->
                // WriterBound is a monotone strengthening of Open. Dispatch admission
                // must consume the strongest live green-path witness rather than demand
                // that the corridor regress to its predecessor state.
                Ok (TerminalFlowDispatchGreenPathWriterBoundWitness(receipt, transaction, writerReceiptId))
            | TerminalFlowGreenPathArtifactCommitted _ -> Error TerminalFlowDispatchGreenPathAlreadyArtifactCommitted
            | TerminalFlowGreenPathTerminalCommitted _ -> Error TerminalFlowDispatchGreenPathAlreadyTerminalCommitted
            | TerminalFlowGreenPathRunEnded _ -> Error TerminalFlowDispatchGreenPathAlreadyRunEnded
            | TerminalFlowGreenPathPhysicalExit _ -> Error TerminalFlowDispatchGreenPathAlreadyPhysicalExit
            | TerminalFlowGreenPathRejected(_, reason) -> Error (TerminalFlowDispatchGreenPathRejected reason)

        type TerminalFlowDispatchGreenPathBoundProof = private {
            breakthrough : TerminalFlowDispatchBreakthroughBoundProof
            greenPath : TerminalFlowDispatchGreenPathWitness
        }

        type TerminalFlowDispatchPredecessorOrderWitness = private {
            receipt : TerminalFlowTotalOrderReceipt<TerminalOrderAwaitDispatchStage>
        }

        type TerminalFlowDispatchPredecessorOrderBindError =
            | TerminalFlowDispatchPredecessorAlreadyDispatched
            | TerminalFlowDispatchPredecessorAlreadyFilled
            | TerminalFlowDispatchPredecessorAlreadyCommitted
            | TerminalFlowDispatchPredecessorAlreadyDone
            | TerminalFlowDispatchPredecessorAlreadyRunEnded
            | TerminalFlowDispatchPredecessorAlreadyPhysicalExit
            | TerminalFlowDispatchPredecessorRejected of TerminalFlowTotalOrderRejectReasonId

        let private terminalFlowDispatchPredecessorOrderWitnessFor = function
            | TerminalFlowTotalOrderAwaitDispatch receipt -> Ok { receipt = receipt }
            | TerminalFlowTotalOrderDispatched _ -> Error TerminalFlowDispatchPredecessorAlreadyDispatched
            | TerminalFlowTotalOrderFilled _ -> Error TerminalFlowDispatchPredecessorAlreadyFilled
            | TerminalFlowTotalOrderCommitted _ -> Error TerminalFlowDispatchPredecessorAlreadyCommitted
            | TerminalFlowTotalOrderDone _ -> Error TerminalFlowDispatchPredecessorAlreadyDone
            | TerminalFlowTotalOrderRunEnded _ -> Error TerminalFlowDispatchPredecessorAlreadyRunEnded
            | TerminalFlowTotalOrderPhysicalExit _ -> Error TerminalFlowDispatchPredecessorAlreadyPhysicalExit
            | TerminalFlowTotalOrderRejected(_, reason) -> Error (TerminalFlowDispatchPredecessorRejected reason)

        type TerminalFlowDispatchPredecessorOrderBoundProof = private {
            greenPath : TerminalFlowDispatchGreenPathBoundProof
            predecessorOrder : TerminalFlowDispatchPredecessorOrderWitness
        }

        type TerminalFlowDispatchConstitutionBoundProof = private {
            predecessorOrder : TerminalFlowDispatchPredecessorOrderBoundProof
            constitution : TerminalFlowConstitutionLineage<TerminalFlowConstitutionSealedStage>
        }

        let private terminalFlowDispatchSchedulerBoundIdentity proof = proof.fairness.admission.identity
        let private terminalFlowFairnessReleaseSameIdentity (left:TerminalFlowFairnessReleaseReceipt) (right:TerminalFlowFairnessReleaseReceipt) =
            left.admissionRef = right.admissionRef
            && left.admissionIdentityRef = right.admissionIdentityRef
            && left.actorBindingRef = right.actorBindingRef
            && left.credentialLedgerRef = right.credentialLedgerRef
            && terminalFlowIdentityRefDigest left.fairnessEpochRef = terminalFlowIdentityRefDigest right.fairnessEpochRef
            && terminalFlowIdentityRefDigest left.sampleRef = terminalFlowIdentityRefDigest right.sampleRef
            && left.basis = right.basis
            && terminalFlowIdentityRefDigest left.releaseRef = terminalFlowIdentityRefDigest right.releaseRef
            && left.exactOnceRef = right.exactOnceRef

        type TerminalFlowDispatchAdmissionCertificate = private {
            proof : TerminalFlowDispatchConstitutionBoundProof
            exactOnce : CompilerIdentityKernel.ContentDigest
            reducerSequence : int64
            mintedAtMs : int64
        }
        with
            member this.exactOnceRef =
                terminalFlowMintedRefOf
                    "dispatch_admission_projection_exact_once_ref"
                    (CompilerIdentityKernel.ContentDigest.text this.exactOnce)
            member this.predecessorOrderLineage = this.proof.predecessorOrder
            member this.greenPathLineage = this.predecessorOrderLineage.greenPath
            member this.breakthroughLineage = this.greenPathLineage.breakthrough
            member this.queueRecoveryLineage = this.breakthroughLineage.queueRecovery
            member this.ownerWorkDagLineage = this.queueRecoveryLineage.ownerWorkDag
            member this.terminalOutcomeLineage = this.ownerWorkDagLineage.terminalOutcome
            member this.finalOutcomeLineage = this.terminalOutcomeLineage.finalOutcome
            member this.lineage = this.finalOutcomeLineage.credentialGraph
            member this.schedulerLineage = this.lineage.scheduler
            member this.identity = terminalFlowDispatchSchedulerBoundIdentity this.schedulerLineage
            member this.fairnessRelease = this.schedulerLineage.fairness.fairnessRelease
            member this.schedulerRelease = this.schedulerLineage.schedulerRelease
            member this.requirements = this.lineage.requirements
            member this.finalOutcome = this.finalOutcomeLineage.finalOutcome
            member this.terminalReceiptRef = this.terminalOutcomeLineage.terminalReceiptRef
            member this.fillKey = this.terminalOutcomeLineage.fillKey
            member this.ownerCertificate = this.ownerWorkDagLineage.ownerCertificate
            member this.workDagTailProof = this.ownerWorkDagLineage.workDagTailProof
            member this.rootCapability = this.ownerWorkDagLineage.rootCapability
            member this.queueRecovery = this.queueRecoveryLineage.recovery
            member this.breakthrough = this.breakthroughLineage.breakthrough
            member this.greenPathWitness = this.greenPathLineage.greenPath
            member this.predecessorOrderWitness = this.predecessorOrderLineage.predecessorOrder
            member this.constitution = this.proof.constitution

        type TerminalFlowDispatchAdmissionState =
            | TerminalFlowDispatchAdmissionOpen
            | TerminalFlowDispatchAdmissionSealed of TerminalFlowDispatchAdmissionCertificate

        // Typed missing-evidence boundaries for recursive dispatch proofs.  Missing
        // evidence is accumulated as a nominal non-empty set; first-match failure
        // ordering is no longer allowed to hide simultaneous broken prerequisites.
        type TerminalFlowDispatchLineageMissingEvidence =
            | TerminalFlowDispatchMissingFairnessRelease
            | TerminalFlowDispatchMissingSchedulerPhysicalRelease
            | TerminalFlowDispatchFairnessAdmissionMismatch of expected:uint32 * actual:uint32
            | TerminalFlowDispatchFairnessIdentityMismatch of expected:uint32 * actual:uint32
            | TerminalFlowDispatchFairnessActorBindingMismatch of expected:uint32 * actual:uint32
            | TerminalFlowDispatchFairnessCredentialLedgerMismatch of expected:uint32 * actual:uint32
            | TerminalFlowDispatchFairnessEpochMismatch of expected:uint32 * actual:uint32
            | TerminalFlowDispatchSchedulerPhysicalReleaseIdentityMismatch

        type TerminalFlowDispatchLineageGuard =
            | TerminalFlowDispatchLineageProven of fairness:TerminalFlowFairnessReleaseReceipt * scheduler:TerminalFlowSchedulerPhysicalReleaseReceipt
            | TerminalFlowDispatchLineageMissing of TerminalFlowNonEmptyEvidence<TerminalFlowDispatchLineageMissingEvidence>

        let private terminalFlowDispatchLineageMissingRequirement = function
            | TerminalFlowDispatchMissingSchedulerPhysicalRelease
            | TerminalFlowDispatchSchedulerPhysicalReleaseIdentityMismatch -> TerminalFlowDispatchRequireSchedulerRelease
            | TerminalFlowDispatchMissingFairnessRelease
            | TerminalFlowDispatchFairnessAdmissionMismatch _
            | TerminalFlowDispatchFairnessIdentityMismatch _
            | TerminalFlowDispatchFairnessActorBindingMismatch _
            | TerminalFlowDispatchFairnessCredentialLedgerMismatch _
            | TerminalFlowDispatchFairnessEpochMismatch _ -> TerminalFlowDispatchRequireFairness

        let private terminalFlowDispatchLineageMissingText = function
            | TerminalFlowDispatchMissingFairnessRelease -> "fairness_release_missing_for_admission"
            | TerminalFlowDispatchMissingSchedulerPhysicalRelease -> "scheduler_physical_release_missing_for_admission"
            | TerminalFlowDispatchFairnessAdmissionMismatch(expected, actual) -> sprintf "fairness_admission_mismatch:expected=%u:actual=%u" expected actual
            | TerminalFlowDispatchFairnessIdentityMismatch(expected, actual) -> sprintf "fairness_identity_mismatch:expected=%u:actual=%u" expected actual
            | TerminalFlowDispatchFairnessActorBindingMismatch(expected, actual) -> sprintf "fairness_binding_mismatch:expected=%u:actual=%u" expected actual
            | TerminalFlowDispatchFairnessCredentialLedgerMismatch(expected, actual) -> sprintf "fairness_ledger_mismatch:expected=%u:actual=%u" expected actual
            | TerminalFlowDispatchFairnessEpochMismatch(expected, actual) -> sprintf "fairness_epoch_mismatch:expected=%u:actual=%u" expected actual
            | TerminalFlowDispatchSchedulerPhysicalReleaseIdentityMismatch -> "scheduler_physical_release_identity_mismatch"

        type TerminalFlowDispatchProofMissingEvidence =
            | TerminalFlowDispatchProofBreakthroughMissing
            | TerminalFlowDispatchProofBreakthroughViolated of TerminalFlowNonEmptyEvidence<TerminalFlowBreakthroughConvergenceViolation>
            | TerminalFlowDispatchProofOwnerWorkDagMissing
            | TerminalFlowDispatchProofOwnerWorkDagOpen
            | TerminalFlowDispatchProofOwnerWorkDagDraining
            | TerminalFlowDispatchProofOwnerWorkDagQuarantined
            | TerminalFlowDispatchProofOwnerWorkDagInvalid of openOwners:int * acyclic:bool
            | TerminalFlowDispatchProofQueueRecoveryNotReady of TerminalFlowQueueRecoveryReducerDecision
            | TerminalFlowDispatchProofGreenPathMissing
            | TerminalFlowDispatchProofGreenPathNotOpen of TerminalFlowDispatchGreenPathBindError
            | TerminalFlowDispatchProofRootMissing
            | TerminalFlowDispatchProofTerminalOutcomeOpen
            | TerminalFlowDispatchProofTerminalOutcomeMismatch of expectedTerminalRef:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind> * actualTerminalRef:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind> * expectedFillKey:TerminalFlowFillKeyId * actualFillKey:TerminalFlowFillKeyId
            | TerminalFlowDispatchProofPredecessorOrderNotAwaitDispatch of TerminalFlowDispatchPredecessorOrderBindError
            | TerminalFlowDispatchProofConstitutionRejected of TerminalFlowConstitutionViolation
            | TerminalFlowDispatchProofCredentialGraphStillOpen
            | TerminalFlowDispatchProofCredentialGraphCycleClosed of TerminalFlowRequirementCycleProof
            | TerminalFlowDispatchProofCredentialGraphClosureChanged of sealedClosure:TerminalFlowRequirementGraphClosureProof * currentClosure:TerminalFlowRequirementGraphClosureProof
            | TerminalFlowDispatchProofCredentialGraphReopenedAfterAdmission

        let private terminalFlowDispatchProofMissingRequirement = function
            | TerminalFlowDispatchProofBreakthroughMissing
            | TerminalFlowDispatchProofBreakthroughViolated _ -> TerminalFlowDispatchRequireBreakthrough
            | TerminalFlowDispatchProofOwnerWorkDagMissing
            | TerminalFlowDispatchProofOwnerWorkDagOpen
            | TerminalFlowDispatchProofOwnerWorkDagDraining
            | TerminalFlowDispatchProofOwnerWorkDagQuarantined
            | TerminalFlowDispatchProofOwnerWorkDagInvalid _ -> TerminalFlowDispatchRequireWorkDagTailClose
            | TerminalFlowDispatchProofQueueRecoveryNotReady _ -> TerminalFlowDispatchRequireQueueRecovery
            | TerminalFlowDispatchProofGreenPathMissing
            | TerminalFlowDispatchProofGreenPathNotOpen _ -> TerminalFlowDispatchRequireGreenPath
            | TerminalFlowDispatchProofRootMissing -> TerminalFlowDispatchRequireRootCapability
            | TerminalFlowDispatchProofTerminalOutcomeOpen
            | TerminalFlowDispatchProofTerminalOutcomeMismatch _ -> TerminalFlowDispatchRequireTerminalOutcomeSealed
            | TerminalFlowDispatchProofPredecessorOrderNotAwaitDispatch _ -> TerminalFlowDispatchRequirePredecessorOrder
            | TerminalFlowDispatchProofConstitutionRejected violation -> terminalFlowConstitutionViolationRequirement violation
            | TerminalFlowDispatchProofCredentialGraphStillOpen
            | TerminalFlowDispatchProofCredentialGraphCycleClosed _
            | TerminalFlowDispatchProofCredentialGraphClosureChanged _
            | TerminalFlowDispatchProofCredentialGraphReopenedAfterAdmission -> TerminalFlowDispatchRequirePredecessorOrder

        let private terminalFlowDispatchGreenPathBindErrorText = function
            | TerminalFlowDispatchGreenPathMissingOpen -> "green_path_open_missing"
            | TerminalFlowDispatchGreenPathAlreadyArtifactCommitted -> "green_path_already_artifact_committed"
            | TerminalFlowDispatchGreenPathAlreadyTerminalCommitted -> "green_path_already_terminal_committed"
            | TerminalFlowDispatchGreenPathAlreadyRunEnded -> "green_path_already_run_ended"
            | TerminalFlowDispatchGreenPathAlreadyPhysicalExit -> "green_path_already_physical_exit"
            | TerminalFlowDispatchGreenPathRejected reason -> "green_path_rejected:" + terminalFlowGreenPathRejectReasonText reason

        let private terminalFlowDispatchPredecessorOrderBindErrorText = function
            | TerminalFlowDispatchPredecessorAlreadyDispatched -> "predecessor_already_dispatched"
            | TerminalFlowDispatchPredecessorAlreadyFilled -> "predecessor_already_filled"
            | TerminalFlowDispatchPredecessorAlreadyCommitted -> "predecessor_already_committed"
            | TerminalFlowDispatchPredecessorAlreadyDone -> "predecessor_already_done"
            | TerminalFlowDispatchPredecessorAlreadyRunEnded -> "predecessor_already_run_ended"
            | TerminalFlowDispatchPredecessorAlreadyPhysicalExit -> "predecessor_already_physical_exit"
            | TerminalFlowDispatchPredecessorRejected reason -> "predecessor_rejected:" + terminalFlowTotalOrderRejectReasonText reason

        let private terminalFlowDispatchProofMissingText = function
            | TerminalFlowDispatchProofBreakthroughMissing -> "breakthrough_not_promotable_without_violation_witness"
            | TerminalFlowDispatchProofBreakthroughViolated violations ->
                let detail = violations |> terminalFlowNonEmptyEvidenceToList |> List.map terminalFlowBreakthroughConvergenceViolationText |> String.concat ","
                "breakthrough_not_promotable:" + detail
            | TerminalFlowDispatchProofOwnerWorkDagMissing -> "owner_workdag_missing"
            | TerminalFlowDispatchProofOwnerWorkDagOpen -> "owner_workdag_open"
            | TerminalFlowDispatchProofOwnerWorkDagDraining -> "owner_workdag_draining"
            | TerminalFlowDispatchProofOwnerWorkDagQuarantined -> "owner_workdag_quarantined"
            | TerminalFlowDispatchProofOwnerWorkDagInvalid(openOwners, acyclic) -> sprintf "owner_workdag_invalid:open=%d:acyclic=%b" openOwners acyclic
            | TerminalFlowDispatchProofQueueRecoveryNotReady decision -> "queue_recovery_not_ready:" + terminalFlowQueueRecoveryDecisionText decision
            | TerminalFlowDispatchProofGreenPathMissing -> "green_path_missing"
            | TerminalFlowDispatchProofGreenPathNotOpen error -> terminalFlowDispatchGreenPathBindErrorText error
            | TerminalFlowDispatchProofRootMissing -> "root_missing"
            | TerminalFlowDispatchProofTerminalOutcomeOpen -> "terminal_outcome_open"
            | TerminalFlowDispatchProofTerminalOutcomeMismatch(expectedTerminalRef, actualTerminalRef, expectedFillKey, actualFillKey) ->
                FastRuntimeFormat.format "terminal_outcome_mismatch:expected_terminal=%u:actual_terminal=%u:expected_fill=%u:actual_fill=%u" [| box (terminalFlowIdentityRefDigest expectedTerminalRef); box (terminalFlowIdentityRefDigest actualTerminalRef); box (TerminalFlowFillKeyId.digest expectedFillKey); box (TerminalFlowFillKeyId.digest actualFillKey) |]
            | TerminalFlowDispatchProofPredecessorOrderNotAwaitDispatch error -> terminalFlowDispatchPredecessorOrderBindErrorText error
            | TerminalFlowDispatchProofConstitutionRejected violation -> "constitution_rejected:" + terminalFlowConstitutionViolationText violation
            | TerminalFlowDispatchProofCredentialGraphStillOpen -> "credential_graph_still_open_after_recursive_proof_satisfaction"
            | TerminalFlowDispatchProofCredentialGraphCycleClosed cycleProof -> sprintf "credential_graph_cycle_closed:cycle_ref=%u" cycleProof.cycleRef
            | TerminalFlowDispatchProofCredentialGraphClosureChanged(sealedClosure, currentClosure) -> sprintf "credential_graph_closure_changed:sealed=%u:current=%u" sealedClosure.closureRef currentClosure.closureRef
            | TerminalFlowDispatchProofCredentialGraphReopenedAfterAdmission -> "credential_graph_reopened_after_admission"

        type TerminalFlowDispatchAdmissionBlocker =
            | TerminalFlowDispatchAdmissionRequirementBlocked of TerminalFlowDispatchRequirementBlocker
            | TerminalFlowDispatchAdmissionLineageMissing of TerminalFlowNonEmptyEvidence<TerminalFlowDispatchLineageMissingEvidence>
            | TerminalFlowDispatchAdmissionProofMissing of TerminalFlowNonEmptyEvidence<TerminalFlowDispatchProofMissingEvidence>

        type TerminalFlowDispatchAdmissionMintDecision =
            | TerminalFlowDispatchAdmissionMinted of TerminalFlowDispatchAdmissionCertificate
            | TerminalFlowDispatchAdmissionReused of TerminalFlowDispatchAdmissionCertificate
            | TerminalFlowDispatchAdmissionBlocked of TerminalFlowDispatchAdmissionBlocker

        let private terminalFlowDispatchAdmissionBlockerText = function
            | TerminalFlowDispatchAdmissionRequirementBlocked blocker ->
                FastRuntimeFormat.format "requirement_blocked:%s:reason=%s:requirement_ref=%u:satisfier_ref=%u:blocker_ref=%u:age_ms=%d" [| box (terminalFlowDispatchRequirementKindText blocker.kind); box (CompilerKernelV2.OperationalReasonIdOps.text blocker.reason); box blocker.requirementRef; box blocker.satisfierRef; box blocker.blockerRef; box blocker.ageMs |]
            | TerminalFlowDispatchAdmissionLineageMissing missing ->
                "lineage_missing:" + (missing |> terminalFlowNonEmptyEvidenceToList |> List.map terminalFlowDispatchLineageMissingText |> String.concat ",")
            | TerminalFlowDispatchAdmissionProofMissing missing ->
                "proof_missing:" + (missing |> terminalFlowNonEmptyEvidenceToList |> List.map terminalFlowDispatchProofMissingText |> String.concat ",")

        let private terminalFlowDispatchAdmissionBlockerFields = function
            | TerminalFlowDispatchAdmissionRequirementBlocked blocker ->
                terminalFlowDispatchRequirementKindText blocker.kind,
                blocker.requirementRef,
                blocker.satisfierRef,
                blocker.blockerRef,
                blocker.ageMs,
                (CompilerKernelV2.OperationalReasonIdOps.text blocker.reason)
            | TerminalFlowDispatchAdmissionLineageMissing missing ->
                terminalFlowDispatchRequirementKindText (terminalFlowDispatchLineageMissingRequirement missing.head),
                0u,
                0u,
                0u,
                0L,
                (missing |> terminalFlowNonEmptyEvidenceToList |> List.map terminalFlowDispatchLineageMissingText |> String.concat ",")
            | TerminalFlowDispatchAdmissionProofMissing missing ->
                terminalFlowDispatchRequirementKindText (terminalFlowDispatchProofMissingRequirement missing.head),
                0u,
                0u,
                0u,
                0L,
                (missing |> terminalFlowNonEmptyEvidenceToList |> List.map terminalFlowDispatchProofMissingText |> String.concat ",")

        let private terminalFlowDispatchAdmissionCertificateText (certificate:TerminalFlowDispatchAdmissionCertificate) =
            let identity = certificate.identity
            let scheduler = certificate.schedulerRelease
            FastRuntimeFormat.format "dispatch_admission|admission_ref=%u|admission_identity_ref=%u|bound_actor_ref=%u|actor_binding_ref=%u|credential_ledger_ref=%u|constitution_ref=%u|final_ref=%u|terminal_ref=%u|fill_ref=%u|owner_admission_ref=%u|recovery_ref=%u|breakthrough_ref=%u|fairness_release_ref=%u|scheduler_lease_ref=%u|scheduler_budget_ref=%u|scheduler_lane_ownership_ref=%u|scheduler_driver_ref=%u|scheduler_lane=%s|scheduler_worker_budget=%d|scheduler_physical_release_ref=%u|green_path_ref=%u|green_path_stage=%s|predecessor_ref=%u|exact_once_ref=%u|sequence=%d|requirements=%s" [| box (terminalFlowAdmissionRawRef identity); box (terminalFlowAdmissionIdentityRef identity); box (terminalFlowAdmissionActorRef identity); box (terminalFlowAdmissionActorBindingRef identity); box (terminalFlowAdmissionRequirementLedgerRef identity); box certificate.constitution.constitutionRef; box (terminalFlowIdentityRefDigest certificate.finalOutcome.maturityRef); box (terminalFlowIdentityRefDigest certificate.terminalReceiptRef); box (TerminalFlowFillKeyId.digest certificate.fillKey); box certificate.ownerCertificate.certificateRef; box (terminalFlowIdentityRefDigest certificate.queueRecovery.recoveryRef); box certificate.breakthrough.certificateRef; box (terminalFlowIdentityRefDigest certificate.fairnessRelease.releaseRef); box (terminalFlowIdentityRefDigest scheduler.leaseRef); box (terminalFlowIdentityRefDigest scheduler.budgetRef); box (terminalFlowIdentityRefDigest scheduler.laneOwnershipRef); box (terminalFlowIdentityRefDigest scheduler.driverRef); box (terminalFlowReplayDriverLaneText scheduler.lane); box scheduler.grantedWorkers; box (terminalFlowIdentityRefDigest scheduler.physicalReleaseRef); box certificate.greenPathWitness.receipt.receiptRef; box (terminalFlowDispatchGreenPathWitnessStageText certificate.greenPathWitness); box certificate.predecessorOrderWitness.receipt.receiptRef; box certificate.exactOnceRef; box certificate.reducerSequence; box (terminalFlowDispatchRequirementSpineText certificate.requirements) |]

        type TerminalFlowResidualWorkDagCloseBlockerId =
            | TerminalFlowResidualCloseMissingTerminalEligibleWitness
            | TerminalFlowResidualCloseMissingWriterLease
            | TerminalFlowResidualCloseOwnerDebtStillOpen of openOwnerCount:int
            | TerminalFlowResidualCloseMissingExactOnceWakerEdge
            | TerminalFlowResidualCloseMissingOwnerCloseCertificate
            | TerminalFlowResidualCloseMissingWorkDagTailProof
            | TerminalFlowResidualCloseMaterialProducerStillLive of activeProducerCount:int
            | TerminalFlowResidualCloseMissingExactOnceSemanticRetirement
            | TerminalFlowResidualCloseCicKernelObligationsOpen of defeqBlocked:int64 * universeOpen:int64 * metavars:int64
            | TerminalFlowResidualCloseQapRebaseInFlight
            | TerminalFlowResidualCloseQapGenerationNotFinal of TerminalFlowQapGenerationStageId

        type TerminalFlowResidualWorkDagCloseKey<'OwnerKind> = private {
            closeKeyRef : uint32
            qapGeneration : TerminalFlowQapGenerationId<TerminalFlowQapGenerationRefKind>
            workDagTailRef : uint32
            ownerLedgerRef : uint32
            writerLeaseRef : uint32
            exactOnceWakerEdgeRef : uint32
            semanticFactCount : int64
            semanticRetiredCost : int64
            cicWeightedRetiredCost : int64
        }

        type TerminalFlowResidualWorkDagForceCloseReceipt<'OwnerKind> = private {
            receiptRef : uint32
            closeKey : TerminalFlowResidualWorkDagCloseKey<'OwnerKind>
            terminalEligibleWitnessRef : uint32
            ownerCloseCertificateRef : uint32
            workDagTailProofRef : uint32
            zeroDeltaStreak : int
            materialEpoch : int64
            reducerSequence : int64
        }

        type TerminalFlowResidualWorkDagCloseDecision<'OwnerKind> =
            | TerminalFlowResidualWorkDagForceCloseReady of TerminalFlowResidualWorkDagForceCloseReceipt<'OwnerKind>
            | TerminalFlowResidualWorkDagForceCloseBlocked of blocker:TerminalFlowResidualWorkDagCloseBlockerId list * tailRef:uint32

        let private terminalFlowResidualWorkDagCloseBlockerText = function
            | TerminalFlowResidualCloseMissingTerminalEligibleWitness -> "missing_terminal_eligible_witness"
            | TerminalFlowResidualCloseMissingWriterLease -> "missing_writer_lease"
            | TerminalFlowResidualCloseOwnerDebtStillOpen count -> sprintf "owner_debt_still_open:%d" count
            | TerminalFlowResidualCloseMissingExactOnceWakerEdge -> "missing_exact_once_waker_edge"
            | TerminalFlowResidualCloseMissingOwnerCloseCertificate -> "missing_owner_close_certificate"
            | TerminalFlowResidualCloseMissingWorkDagTailProof -> "missing_workdag_tail_proof"
            | TerminalFlowResidualCloseMaterialProducerStillLive count -> sprintf "material_producer_still_live:%d" count
            | TerminalFlowResidualCloseMissingExactOnceSemanticRetirement -> "missing_exact_once_semantic_retirement"
            | TerminalFlowResidualCloseCicKernelObligationsOpen(defeqBlocked, universeOpen, metavars) -> FastRuntimeFormat.format "cic_kernel_obligations_open:%d/%d/%d" [| box defeqBlocked; box universeOpen; box metavars |]
            | TerminalFlowResidualCloseQapRebaseInFlight -> "qap_rebase_in_flight"
            | TerminalFlowResidualCloseQapGenerationNotFinal stage -> "qap_generation_not_final:" + terminalFlowQapGenerationStageText stage

        let private terminalFlowResidualWorkDagCloseDecisionText = function
            | TerminalFlowResidualWorkDagForceCloseReady receipt -> sprintf "force_close_ready:%u" receipt.receiptRef
            | TerminalFlowResidualWorkDagForceCloseBlocked(blockers, tailRef) ->
                sprintf "force_close_blocked:%u:%s" tailRef (blockers |> List.map terminalFlowResidualWorkDagCloseBlockerText |> String.concat ",")

        let private terminalFlowResidualGreenPathCovenantRefs = function
            | Some (TerminalFlowGreenPathOpen(_, tx)) -> 0u, tx.fillOnceReadyWitnessRef
            | Some (TerminalFlowGreenPathWriterBound(receipt, tx, _)) -> receipt.receiptRef, tx.fillOnceReadyWitnessRef
            | Some (TerminalFlowGreenPathArtifactCommitted(receipt, _)) ->
                receipt.receiptRef, (receipt.predecessorRef |> Option.defaultValue receipt.receiptRef)
            | Some (TerminalFlowGreenPathTerminalCommitted(receipt, _)) ->
                receipt.receiptRef, (receipt.predecessorRef |> Option.defaultValue receipt.receiptRef)
            | Some (TerminalFlowGreenPathRunEnded(receipt, _)) ->
                receipt.receiptRef, (receipt.predecessorRef |> Option.defaultValue receipt.receiptRef)
            | Some (TerminalFlowGreenPathPhysicalExit(receipt, _)) ->
                receipt.receiptRef, (receipt.predecessorRef |> Option.defaultValue receipt.receiptRef)
            | Some (TerminalFlowGreenPathRejected _) -> 0u, 0u
            | None -> 0u, 0u

        let private terminalFlowResidualWorkDagCloseDecisionFor
            reducerSequence
            qapGeneration
            qapStage
            terminalEligibleWitnessRef
            writerLeaseRef
            exactOnceWakerEdgeRef
            semanticFactCount
            semanticRetiredCost
            (cicCounters:NativeCutoverCicKernelCounters option)
            qapRebaseInFlight
            (ownerCertificate:TerminalFlowOwnerLedgerCloseCertificate<'OwnerKind> option)
            (workDagProof:TerminalFlowWorkDagTailCloseProof<'OwnerKind> option) =
            let blockers = ResizeArray<TerminalFlowResidualWorkDagCloseBlockerId>()
            if terminalEligibleWitnessRef = 0u then blockers.Add TerminalFlowResidualCloseMissingTerminalEligibleWitness
            if writerLeaseRef = 0u then blockers.Add TerminalFlowResidualCloseMissingWriterLease
            if exactOnceWakerEdgeRef = 0u then blockers.Add TerminalFlowResidualCloseMissingExactOnceWakerEdge
            if semanticFactCount > 0L && semanticRetiredCost <= 0L then
                blockers.Add TerminalFlowResidualCloseMissingExactOnceSemanticRetirement
            match cicCounters with
            | Some counters when counters.defeqBlockedCount > 0L || counters.universeConstraintCount > 0L || counters.metavarsInKernel > 0L ->
                blockers.Add (TerminalFlowResidualCloseCicKernelObligationsOpen(counters.defeqBlockedCount, counters.universeConstraintCount, counters.metavarsInKernel))
            | _ -> ()
            if qapRebaseInFlight then blockers.Add TerminalFlowResidualCloseQapRebaseInFlight
            if ownerCertificate.IsNone then blockers.Add TerminalFlowResidualCloseMissingOwnerCloseCertificate
            if workDagProof.IsNone then blockers.Add TerminalFlowResidualCloseMissingWorkDagTailProof
            let snapshot =
                match workDagProof with
                | Some proof -> Some (terminalFlowWorkDagTailSnapshot proof.workDagTail)
                | None -> None
            match workDagProof with
            | Some proof when proof.openOwnerCount <> 0 ->
                blockers.Add (TerminalFlowResidualCloseOwnerDebtStillOpen proof.openOwnerCount)
            | _ -> ()
            match qapStage, snapshot with
            | TerminalFlowQapGenerationDrained, _
            | TerminalFlowQapGenerationDeadlocked, _ -> ()
            | _, Some value when value.activeProducerCount <> 0 ->
                blockers.Add (TerminalFlowResidualCloseMaterialProducerStillLive value.activeProducerCount)
            | _ -> ()
            match qapStage with
            | TerminalFlowQapGenerationDrained
            | TerminalFlowQapGenerationDeadlocked -> ()
            | stage -> blockers.Add (TerminalFlowResidualCloseQapGenerationNotFinal stage)
            let tailRef = snapshot |> Option.map (fun value -> value.tailRef) |> Option.defaultValue 0u
            if blockers.Count > 0 then
                TerminalFlowResidualWorkDagForceCloseBlocked(List.ofSeq blockers, tailRef)
            else
                match ownerCertificate, workDagProof, snapshot with
                | Some certificate, Some proof, Some value ->
                    let cicWeightedRetiredCost = cicCounters |> Option.map nativeCutoverCicWeightedCost |> Option.defaultValue 0L
                    let closeKey =
                        { closeKeyRef =
                            terminalFlowMintedRefOf
                                "residual_workdag_close_key_ref"
                                (FastRuntimeFormat.format "%d|%u|%u|%u|%u|%d|%d|%d" [| box (terminalFlowQapGenerationValue qapGeneration); box value.tailRef; box value.ownerLedgerRef; box writerLeaseRef; box exactOnceWakerEdgeRef; box semanticFactCount; box semanticRetiredCost; box cicWeightedRetiredCost |])
                          qapGeneration = qapGeneration
                          workDagTailRef = value.tailRef
                          ownerLedgerRef = value.ownerLedgerRef
                          writerLeaseRef = writerLeaseRef
                          exactOnceWakerEdgeRef = exactOnceWakerEdgeRef
                          semanticFactCount = semanticFactCount
                          semanticRetiredCost = semanticRetiredCost
                          cicWeightedRetiredCost = cicWeightedRetiredCost }
                    let proofRef = uint32 (terminalFlowOwnerLedgerProtocolIdValue proof.proofRef)
                    let receiptRef =
                        terminalFlowMintedRefOf
                            "residual_workdag_force_close_receipt_ref"
                            (FastRuntimeFormat.format "%u|%u|%u|%u|%d" [| box closeKey.closeKeyRef; box certificate.certificateRef; box proofRef; box terminalEligibleWitnessRef; box reducerSequence |])
                    TerminalFlowResidualWorkDagForceCloseReady {
                        receiptRef = receiptRef
                        closeKey = closeKey
                        terminalEligibleWitnessRef = terminalEligibleWitnessRef
                        ownerCloseCertificateRef = certificate.certificateRef
                        workDagTailProofRef = proofRef
                        zeroDeltaStreak = value.zeroDeltaStreak
                        materialEpoch = value.materialEpoch
                        reducerSequence = reducerSequence
                    }
                | _ ->
                    TerminalFlowResidualWorkDagForceCloseBlocked(List.ofSeq blockers, tailRef)

        // MIGRATION / destructive migration 1 of 5: QAP, terminal outcome and
        // scheduler actor are one reducer-owned authority. The old kernel and
        // observer actor remain adapters during this migration window; neither
        // may independently regress QAP maturity or finalize an outcome.
        [<Struct>]
        type TerminalFlowReducerOutcomeProvisionalStage = struct end

        [<Struct>]
        type TerminalFlowReducerOutcomeFinalDrainedStage = struct end

        [<Struct>]
        type TerminalFlowReducerOutcomeFinalDeadlockedStage = struct end

        type TerminalFlowReducerOutcome<'Stage> = private {
            terminalRef : uint32
            fillRef : uint32
            qapGeneration : TerminalFlowQapGenerationId<TerminalFlowQapGenerationRefKind> option
            proofRef : uint32 option
            dispatchConsumable : bool
        }

        type TerminalFlowReducerOutcomeAuthorityId =
            | TerminalFlowReducerOutcomeAwaitingQap
            | TerminalFlowReducerOutcomeProvisional of TerminalFlowReducerOutcome<TerminalFlowReducerOutcomeProvisionalStage>
            | TerminalFlowReducerOutcomeFinalDrained of TerminalFlowReducerOutcome<TerminalFlowReducerOutcomeFinalDrainedStage>
            | TerminalFlowReducerOutcomeFinalDeadlocked of TerminalFlowReducerOutcome<TerminalFlowReducerOutcomeFinalDeadlockedStage>

        type TerminalFlowReducerOutcomeMaturityId =
            | TerminalFlowReducerOutcomeMaturityAwaiting
            | TerminalFlowReducerOutcomeMaturityProvisional
            | TerminalFlowReducerOutcomeMaturityFinalDrained
            | TerminalFlowReducerOutcomeMaturityFinalDeadlocked

        let private terminalFlowReducerOutcomeMaturity = function
            | TerminalFlowReducerOutcomeAwaitingQap -> TerminalFlowReducerOutcomeMaturityAwaiting
            | TerminalFlowReducerOutcomeProvisional _ -> TerminalFlowReducerOutcomeMaturityProvisional
            | TerminalFlowReducerOutcomeFinalDrained _ -> TerminalFlowReducerOutcomeMaturityFinalDrained
            | TerminalFlowReducerOutcomeFinalDeadlocked _ -> TerminalFlowReducerOutcomeMaturityFinalDeadlocked

        let private terminalFlowReducerOutcomeMaturityText = function
            | TerminalFlowReducerOutcomeMaturityAwaiting -> "Awaiting"
            | TerminalFlowReducerOutcomeMaturityProvisional -> "Provisional"
            | TerminalFlowReducerOutcomeMaturityFinalDrained -> "FinalDrained"
            | TerminalFlowReducerOutcomeMaturityFinalDeadlocked -> "FinalDeadlocked"

        let private terminalFlowReducerOutcomeIsFinal outcome =
            match terminalFlowReducerOutcomeMaturity outcome with
            | TerminalFlowReducerOutcomeMaturityFinalDrained
            | TerminalFlowReducerOutcomeMaturityFinalDeadlocked -> true
            | TerminalFlowReducerOutcomeMaturityAwaiting
            | TerminalFlowReducerOutcomeMaturityProvisional -> false

        // MIGRATION: QAP finality and terminal identity may arrive in either order.
        // Binding a late terminal/fill identity must enrich the already-final value,
        // never demote it back to Provisional or discard the pending terminal.
        type TerminalFlowReducerOutcomeIdentityBindingId =
            | TerminalFlowOutcomeIdentityAwaitingBoundProvisional
            | TerminalFlowOutcomeIdentityProvisionalRebound
            | TerminalFlowOutcomeIdentityFinalDrainedBound
            | TerminalFlowOutcomeIdentityFinalDeadlockedBound

        let private terminalFlowReducerOutcomeIdentityBindingText = function
            | TerminalFlowOutcomeIdentityAwaitingBoundProvisional -> "AwaitingBoundProvisional"
            | TerminalFlowOutcomeIdentityProvisionalRebound -> "ProvisionalRebound"
            | TerminalFlowOutcomeIdentityFinalDrainedBound -> "FinalDrainedBound"
            | TerminalFlowOutcomeIdentityFinalDeadlockedBound -> "FinalDeadlockedBound"

        let private terminalFlowReducerOutcomeDispatchDecisionReady = function
            | Ok () -> true
            | Error _ -> false

        let private terminalFlowReducerOutcomeRefreshDispatch dispatchDecision = function
            | TerminalFlowReducerOutcomeFinalDrained outcome ->
                let refreshed : TerminalFlowReducerOutcome<TerminalFlowReducerOutcomeFinalDrainedStage> =
                    { outcome with
                        dispatchConsumable =
                            outcome.dispatchConsumable
                            || (outcome.terminalRef <> 0u
                                && outcome.fillRef <> 0u
                                && Option.isSome outcome.proofRef
                                && terminalFlowReducerOutcomeDispatchDecisionReady dispatchDecision) }
                TerminalFlowReducerOutcomeFinalDrained refreshed
            | TerminalFlowReducerOutcomeFinalDeadlocked outcome ->
                let refreshed : TerminalFlowReducerOutcome<TerminalFlowReducerOutcomeFinalDeadlockedStage> =
                    { outcome with
                        dispatchConsumable =
                            outcome.dispatchConsumable
                            || (outcome.terminalRef <> 0u
                                && outcome.fillRef <> 0u
                                && Option.isSome outcome.proofRef
                                && terminalFlowReducerOutcomeDispatchDecisionReady dispatchDecision) }
                TerminalFlowReducerOutcomeFinalDeadlocked refreshed
            | outcome -> outcome

        // MIGRATION: the stage is the type/constructor, not a mutable field.
        // Filled and Sealed are distinct so a writer fill cannot silently imply
        // run_end or physical-exit authority.
        [<Struct>]
        type TerminalFlowReducerActorVacantStage = struct end

        [<Struct>]
        type TerminalFlowReducerActorArmedStage = struct end

        [<Struct>]
        type TerminalFlowReducerActorFilledStage = struct end

        [<Struct>]
        type TerminalFlowReducerActorSealedStage = struct end

        [<Struct>]
        type TerminalFlowReducerActorFailedClosedStage = struct end

        type TerminalFlowReducerTerminalPossessionRejectionId =
            | TerminalFlowPossessionHandoffNotReady
            | TerminalFlowPossessionLineageContainsZero
            | TerminalFlowPossessionIssueIdentityMismatch
            | TerminalFlowPossessionConsumeWithoutIssue
            | TerminalFlowPossessionConsumeIdentityMismatch
            | TerminalFlowPossessionFillWithoutIssue
            | TerminalFlowPossessionFillIdentityMismatch
            | TerminalFlowPossessionSealWithoutFill
            | TerminalFlowPossessionSealIdentityMismatch
            | TerminalFlowPossessionTerminalConflict
            | TerminalFlowPossessionFailureIdentityMismatch

        let private terminalFlowReducerTerminalPossessionRejectionText = function
            | TerminalFlowPossessionHandoffNotReady -> "HandoffNotReady"
            | TerminalFlowPossessionLineageContainsZero -> "LineageContainsZero"
            | TerminalFlowPossessionIssueIdentityMismatch -> "IssueIdentityMismatch"
            | TerminalFlowPossessionConsumeWithoutIssue -> "ConsumeWithoutIssue"
            | TerminalFlowPossessionConsumeIdentityMismatch -> "ConsumeIdentityMismatch"
            | TerminalFlowPossessionFillWithoutIssue -> "FillWithoutIssue"
            | TerminalFlowPossessionFillIdentityMismatch -> "FillIdentityMismatch"
            | TerminalFlowPossessionSealWithoutFill -> "SealWithoutFill"
            | TerminalFlowPossessionSealIdentityMismatch -> "SealIdentityMismatch"
            | TerminalFlowPossessionTerminalConflict -> "TerminalConflict"
            | TerminalFlowPossessionFailureIdentityMismatch -> "FailureIdentityMismatch"

        type TerminalFlowLinearPossessionFixtureOperation =
            | TerminalFlowFixtureAcquire
            | TerminalFlowFixtureConsume
            | TerminalFlowFixtureFailClose

        type TerminalFlowLinearPossessionFixtureExpectation =
            | TerminalFlowFixtureAdvanced
            | TerminalFlowFixtureRejected of TerminalFlowReducerTerminalPossessionRejectionId

        type TerminalFlowLinearPossessionFixtureVector = private {
            name : string
            operation : TerminalFlowLinearPossessionFixtureOperation
            lineageComplete : bool
            issuePresent : bool
            identityMatches : bool
            terminalConflict : bool
            expected : TerminalFlowLinearPossessionFixtureExpectation
        }

        let private terminalFlowLinearPossessionFixtureDecision vector =
            match vector.operation with
            | TerminalFlowFixtureAcquire when vector.terminalConflict ->
                TerminalFlowFixtureRejected TerminalFlowPossessionTerminalConflict
            | TerminalFlowFixtureAcquire when not vector.lineageComplete ->
                TerminalFlowFixtureRejected TerminalFlowPossessionLineageContainsZero
            | TerminalFlowFixtureAcquire -> TerminalFlowFixtureAdvanced
            | TerminalFlowFixtureConsume when vector.terminalConflict ->
                TerminalFlowFixtureRejected TerminalFlowPossessionTerminalConflict
            | TerminalFlowFixtureConsume when not vector.issuePresent ->
                TerminalFlowFixtureRejected TerminalFlowPossessionConsumeWithoutIssue
            | TerminalFlowFixtureConsume when not vector.identityMatches ->
                TerminalFlowFixtureRejected TerminalFlowPossessionConsumeIdentityMismatch
            | TerminalFlowFixtureConsume -> TerminalFlowFixtureAdvanced
            | TerminalFlowFixtureFailClose when vector.terminalConflict ->
                TerminalFlowFixtureRejected TerminalFlowPossessionTerminalConflict
            | TerminalFlowFixtureFailClose when not vector.identityMatches ->
                TerminalFlowFixtureRejected TerminalFlowPossessionFailureIdentityMismatch
            | TerminalFlowFixtureFailClose -> TerminalFlowFixtureAdvanced

        let private terminalFlowLinearPossessionFixtureVectors () =
            [| { name = "acquire_complete_lineage"; operation = TerminalFlowFixtureAcquire; lineageComplete = true; issuePresent = false; identityMatches = true; terminalConflict = false; expected = TerminalFlowFixtureAdvanced }
               { name = "acquire_rejects_zero_lineage"; operation = TerminalFlowFixtureAcquire; lineageComplete = false; issuePresent = false; identityMatches = true; terminalConflict = false; expected = TerminalFlowFixtureRejected TerminalFlowPossessionLineageContainsZero }
               { name = "consume_requires_issue"; operation = TerminalFlowFixtureConsume; lineageComplete = true; issuePresent = false; identityMatches = true; terminalConflict = false; expected = TerminalFlowFixtureRejected TerminalFlowPossessionConsumeWithoutIssue }
               { name = "consume_requires_same_identity"; operation = TerminalFlowFixtureConsume; lineageComplete = true; issuePresent = true; identityMatches = false; terminalConflict = false; expected = TerminalFlowFixtureRejected TerminalFlowPossessionConsumeIdentityMismatch }
               { name = "consume_complete_lineage"; operation = TerminalFlowFixtureConsume; lineageComplete = true; issuePresent = true; identityMatches = true; terminalConflict = false; expected = TerminalFlowFixtureAdvanced }
               { name = "fail_close_cannot_replace_consumed"; operation = TerminalFlowFixtureFailClose; lineageComplete = true; issuePresent = true; identityMatches = true; terminalConflict = true; expected = TerminalFlowFixtureRejected TerminalFlowPossessionTerminalConflict } |]

        let private terminalFlowLinearPossessionFixtureProven () =
            terminalFlowLinearPossessionFixtureVectors ()
            |> Array.forall (fun vector -> terminalFlowLinearPossessionFixtureDecision vector = vector.expected)

        // MIGRATION destructive migration : authority-bearing identities are
        // private, kinded and nonzero. Absence is represented by a constructor or
        // option at the owning stage; the number zero is no longer a legal
        // terminal capability value.
        [<Struct>]
        type TerminalFlowActorAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowTerminalAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowFillAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowAdmissionAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowAdmissionIdentityAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowActorBindingAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowCredentialLedgerAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowCredentialGraphClosureAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowCredentialGraphAcyclicAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowCredentialCycleRejectionAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowConstitutionAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowRatificationAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowFairnessEpochAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowFairnessReleaseAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowSchedulerReleaseAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowHandoffAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowDispatchGrantAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowStageTokenAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowIssueReceiptAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowConsumeReceiptAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowFillReceiptAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowWakerEdgeAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowExactOnceAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowTransitionAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowRunEndReceiptAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowPhysicalExitAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowFailureAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowOutcomeIvarOwnerAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowFillCommandAuthorityRefKind = struct end
        [<Struct>]
        type TerminalFlowSealCommandAuthorityRefKind = struct end

        // Bonus migration : terminal authority now uses the compiler-wide
        // nonzero capability representation.  TerminalFlow can no longer drift
        // into a private parallel implementation of the same invariant.
        type TerminalFlowAuthorityRef<'Kind> = CompilerKernelV2.NonZeroRef<'Kind>

        let private terminalFlowTryAuthorityRef (value:uint32) : TerminalFlowAuthorityRef<'Kind> option =
            CompilerKernelV2.NonZeroRef.tryCreate value

        let private terminalFlowRequireAuthorityRef label (value:uint32) : TerminalFlowAuthorityRef<'Kind> =
            CompilerKernelV2.NonZeroRef.require label value

        let private terminalFlowAuthorityRefValue (reference:TerminalFlowAuthorityRef<'Kind>) =
            CompilerKernelV2.NonZeroRef.value reference

        type TerminalFlowPossessionClock = private {
            version : int64
            changedAtMs : int64
            lastTransitionRef : TerminalFlowAuthorityRef<TerminalFlowTransitionAuthorityRefKind> option
        }

        type TerminalFlowCredentialCycleEvidence =
            | TerminalFlowCredentialGraphAcyclic of TerminalFlowAuthorityRef<TerminalFlowCredentialGraphAcyclicAuthorityRefKind>
            | TerminalFlowCredentialGraphRejected of TerminalFlowAuthorityRef<TerminalFlowCredentialCycleRejectionAuthorityRefKind>

        let private terminalFlowCredentialCycleEvidenceFor credentialGraphClosureRef credentialCycleProofRef =
            if credentialCycleProofRef = 0u then
                let acyclicProofRef =
                    terminalFlowMintedRefOf
                        "credential_graph_acyclic_authority_ref"
                        (sprintf "%u" credentialGraphClosureRef)
                TerminalFlowCredentialGraphAcyclic (
                    terminalFlowRequireAuthorityRef "credential_graph_acyclic_authority_ref" acyclicProofRef)
            else
                TerminalFlowCredentialGraphRejected (
                    terminalFlowRequireAuthorityRef "credential_cycle_rejection_authority_ref" credentialCycleProofRef)

        type TerminalFlowPossessionLineage = private {
            actorRef : TerminalFlowAuthorityRef<TerminalFlowActorAuthorityRefKind>
            terminalRef : TerminalFlowAuthorityRef<TerminalFlowTerminalAuthorityRefKind>
            fillRef : TerminalFlowAuthorityRef<TerminalFlowFillAuthorityRefKind>
            admissionRef : TerminalFlowAuthorityRef<TerminalFlowAdmissionAuthorityRefKind>
            admissionIdentityRef : TerminalFlowAuthorityRef<TerminalFlowAdmissionIdentityAuthorityRefKind>
            actorBindingRef : TerminalFlowAuthorityRef<TerminalFlowActorBindingAuthorityRefKind>
            credentialLedgerRef : TerminalFlowAuthorityRef<TerminalFlowCredentialLedgerAuthorityRefKind>
            credentialGraphClosureRef : TerminalFlowAuthorityRef<TerminalFlowCredentialGraphClosureAuthorityRefKind>
            credentialCycleEvidence : TerminalFlowCredentialCycleEvidence
            constitutionRef : TerminalFlowAuthorityRef<TerminalFlowConstitutionAuthorityRefKind>
            fairnessEpochRef : TerminalFlowAuthorityRef<TerminalFlowFairnessEpochAuthorityRefKind>
            fairnessReleaseRef : TerminalFlowAuthorityRef<TerminalFlowFairnessReleaseAuthorityRefKind>
            schedulerReleaseRef : TerminalFlowAuthorityRef<TerminalFlowSchedulerReleaseAuthorityRefKind>
            handoffRef : TerminalFlowAuthorityRef<TerminalFlowHandoffAuthorityRefKind>
            dispatchGrantRef : TerminalFlowAuthorityRef<TerminalFlowDispatchGrantAuthorityRefKind>
            exactOnceRef : TerminalFlowAuthorityRef<TerminalFlowExactOnceAuthorityRefKind>
        }

        type TerminalFlowRatifiedPossessionLineage = private {
            issuedLineage : TerminalFlowPossessionLineage
            ratificationRef : TerminalFlowAuthorityRef<TerminalFlowRatificationAuthorityRefKind>
        }

        type TerminalFlowVacantPossession = private {
            clock : TerminalFlowPossessionClock
        }

        type TerminalFlowIssuedStageToken = private {
            tokenRef : TerminalFlowAuthorityRef<TerminalFlowStageTokenAuthorityRefKind>
            issueReceiptRef : TerminalFlowAuthorityRef<TerminalFlowIssueReceiptAuthorityRefKind>
            wakerEdgeRef : TerminalFlowAuthorityRef<TerminalFlowWakerEdgeAuthorityRefKind>
        }

        type TerminalFlowPushActorOutcomeIvarOwnership = private {
            ownerRef : TerminalFlowAuthorityRef<TerminalFlowOutcomeIvarOwnerAuthorityRefKind>
            actorRef : TerminalFlowAuthorityRef<TerminalFlowActorAuthorityRefKind>
            terminalRef : TerminalFlowAuthorityRef<TerminalFlowTerminalAuthorityRefKind>
            fillRef : TerminalFlowAuthorityRef<TerminalFlowFillAuthorityRefKind>
            tokenRef : TerminalFlowAuthorityRef<TerminalFlowStageTokenAuthorityRefKind>
            claimedAtMs : int64
        }

        type TerminalFlowArmedPossession = private {
            clock : TerminalFlowPossessionClock
            lineage : TerminalFlowPossessionLineage
            issued : TerminalFlowIssuedStageToken
            outcomeIvarOwnership : TerminalFlowPushActorOutcomeIvarOwnership
        }

        type TerminalFlowPushActorFillAuthority = private {
            commandRef : TerminalFlowAuthorityRef<TerminalFlowFillCommandAuthorityRefKind>
            ownership : TerminalFlowPushActorOutcomeIvarOwnership
            consumeReceiptRef : TerminalFlowAuthorityRef<TerminalFlowConsumeReceiptAuthorityRefKind>
            fillReceiptRef : TerminalFlowAuthorityRef<TerminalFlowFillReceiptAuthorityRefKind>
            filledAtMs : int64
        }

        type TerminalFlowFilledPossession = private {
            clock : TerminalFlowPossessionClock
            armed : TerminalFlowArmedPossession
            ratifiedLineage : TerminalFlowRatifiedPossessionLineage
            fillAuthority : TerminalFlowPushActorFillAuthority
        }

        type TerminalFlowSealedPossession = private {
            clock : TerminalFlowPossessionClock
            filled : TerminalFlowFilledPossession
            runEndReceiptRef : TerminalFlowAuthorityRef<TerminalFlowRunEndReceiptAuthorityRefKind>
            physicalExitAuthorityRef : TerminalFlowAuthorityRef<TerminalFlowPhysicalExitAuthorityRefKind>
        }

        type TerminalFlowFailureContext =
            | TerminalFlowFailureBeforePossession of
                failureRef:TerminalFlowAuthorityRef<TerminalFlowFailureAuthorityRefKind> *
                exactOnceRef:TerminalFlowAuthorityRef<TerminalFlowExactOnceAuthorityRefKind>
            | TerminalFlowFailureAfterIssue of
                armed:TerminalFlowArmedPossession *
                failureRef:TerminalFlowAuthorityRef<TerminalFlowFailureAuthorityRefKind> *
                exactOnceRef:TerminalFlowAuthorityRef<TerminalFlowExactOnceAuthorityRefKind>
            | TerminalFlowFailureAfterFill of
                filled:TerminalFlowFilledPossession *
                failureRef:TerminalFlowAuthorityRef<TerminalFlowFailureAuthorityRefKind> *
                exactOnceRef:TerminalFlowAuthorityRef<TerminalFlowExactOnceAuthorityRefKind>

        type TerminalFlowFailedClosedPossession = private {
            clock : TerminalFlowPossessionClock
            context : TerminalFlowFailureContext
        }

        let private terminalFlowFailureContextFailureRef = function
            | TerminalFlowFailureBeforePossession(failureRef, _)
            | TerminalFlowFailureAfterIssue(_, failureRef, _)
            | TerminalFlowFailureAfterFill(_, failureRef, _) -> terminalFlowAuthorityRefValue failureRef

        let private terminalFlowFailureContextExactOnceRef = function
            | TerminalFlowFailureBeforePossession(_, exactOnceRef)
            | TerminalFlowFailureAfterIssue(_, _, exactOnceRef)
            | TerminalFlowFailureAfterFill(_, _, exactOnceRef) -> terminalFlowAuthorityRefValue exactOnceRef

        type TerminalFlowPossession<'Stage,'Payload> = private | TerminalFlowPossession of 'Payload

        let private terminalFlowPossessionOf (payload:'Payload) : TerminalFlowPossession<'Stage,'Payload> =
            TerminalFlowPossession payload

        let private terminalFlowPossessionPayload (TerminalFlowPossession payload) = payload

        type TerminalFlowReducerActorAuthorityId =
            | TerminalFlowReducerActorVacant of TerminalFlowPossession<TerminalFlowReducerActorVacantStage,TerminalFlowVacantPossession>
            | TerminalFlowReducerActorArmed of TerminalFlowPossession<TerminalFlowReducerActorArmedStage,TerminalFlowArmedPossession>
            | TerminalFlowReducerActorFilled of TerminalFlowPossession<TerminalFlowReducerActorFilledStage,TerminalFlowFilledPossession>
            | TerminalFlowReducerActorSealed of TerminalFlowPossession<TerminalFlowReducerActorSealedStage,TerminalFlowSealedPossession>
            | TerminalFlowReducerActorFailedClosed of TerminalFlowPossession<TerminalFlowReducerActorFailedClosedStage,TerminalFlowFailedClosedPossession>

        // MIGRATION / terminal constitution closeout: every positive stage-token
        // issue carries one proof that the admission, requirement graph, fairness,
        // scheduler, actor, WorkDag/root, terminal and waker identities are the
        // same lineage. Fail-close paths carry a distinct bounded constitution.
        type TerminalFlowTerminalConstitutionDisposition =
            | TerminalFlowTerminalConstitutionSuccess
            | TerminalFlowTerminalConstitutionFailClosed of failureRef:uint32

        type TerminalFlowTerminalConstitutionViolation =
            | TerminalFlowTerminalConstitutionLineageContainsZero of fieldName:string
            | TerminalFlowTerminalConstitutionCredentialGraphOpen
            | TerminalFlowTerminalConstitutionCredentialCyclePresent of cycleProofRef:uint32
            | TerminalFlowTerminalConstitutionSchedulerLineageMismatch
            | TerminalFlowTerminalConstitutionWorkDagLineageMismatch
            | TerminalFlowTerminalConstitutionRecoveryLineageMismatch
            | TerminalFlowTerminalConstitutionTerminalIdentityMismatch
            | TerminalFlowTerminalConstitutionWakerLineageMismatch

        type TerminalFlowTerminalConstitutionReceipt = private {
            constitutionRef : uint32
            disposition : TerminalFlowTerminalConstitutionDisposition
            admissionRef : uint32
            admissionIdentityRef : uint32
            actorBindingRef : uint32
            credentialLedgerRef : uint32
            credentialGraphClosureRef : uint32
            fairnessEpochRef : uint32
            fairnessReleaseRef : uint32
            schedulerReleaseRef : uint32
            terminalOrderAdmissionRef : uint32
            actorRef : uint32
            terminalRef : uint32
            fillRef : uint32
            workDagCloseReceiptRef : uint32
            rootCapabilityRef : uint32
            queueRecoveryRef : uint32
            wakerEdgeRef : uint32
            tokenRef : uint32
            exactOnceRef : uint32
            sealedAtMs : int64
        }

        // MIGRATION: fill ratification and seal evidence are different proofs.
        // The push actor owns the outcome IVar and may commit one fill after the
        // artifact exists.  Exit witness and run_end evidence are consumed only by
        // the later reducer seal command; they cannot hitchhike on the fill event.
        type TerminalFlowTerminalFillRatificationViolation =
            | TerminalFlowTerminalFillRatificationConstitutionMissing
            | TerminalFlowTerminalFillRatificationIdentityMismatch
            | TerminalFlowTerminalFillRatificationPushActorOwnerMissing
            | TerminalFlowTerminalFillRatificationWriterMissing
            | TerminalFlowTerminalFillRatificationArtifactMissing
            | TerminalFlowTerminalFillRatificationWakerMismatch

        type TerminalFlowTerminalSealEvidenceViolation =
            | TerminalFlowTerminalSealEvidenceFillRatificationMissing
            | TerminalFlowTerminalSealEvidenceExitWitnessMissing
            | TerminalFlowTerminalSealEvidenceRunEndMissing

        type TerminalFlowTerminalFillRatificationReceipt = private {
            ratificationRef : uint32
            constitutionRef : uint32
            issueReceiptRef : uint32
            pushActorOwnerRef : uint32
            artifactWriterCapabilityRef : uint32
            writerJobRef : uint32
            artifactReceiptRef : uint32
            fillReceiptRef : uint32
            wakerEdgeRef : uint32
            exactOnceRef : uint32
            ratifiedAtMs : int64
        }

        type TerminalFlowTerminalSealEvidence = private {
            evidenceRef : uint32
            fillRatificationRef : uint32
