        }

        let private terminalFlowTerminalFillRatificationViolationText = function
            | TerminalFlowTerminalFillRatificationConstitutionMissing -> "constitution_missing"
            | TerminalFlowTerminalFillRatificationIdentityMismatch -> "terminal_identity_mismatch"
            | TerminalFlowTerminalFillRatificationPushActorOwnerMissing -> "push_actor_owner_missing"
            | TerminalFlowTerminalFillRatificationWriterMissing -> "artifact_writer_missing"
            | TerminalFlowTerminalFillRatificationArtifactMissing -> "artifact_missing"
            | TerminalFlowTerminalFillRatificationWakerMismatch -> "waker_mismatch"

        let private terminalFlowTerminalSealEvidenceViolationText = function
            | TerminalFlowTerminalSealEvidenceFillRatificationMissing -> "fill_ratification_missing"
            | TerminalFlowTerminalSealEvidenceExitWitnessMissing -> "exit_witness_missing"
            | TerminalFlowTerminalSealEvidenceRunEndMissing -> "run_end_evidence_missing"

        let private terminalFlowTerminalConstitutionViolationText = function
            | TerminalFlowTerminalConstitutionLineageContainsZero fieldName -> "lineage_zero:" + fieldName
            | TerminalFlowTerminalConstitutionCredentialGraphOpen -> "credential_graph_open"
            | TerminalFlowTerminalConstitutionCredentialCyclePresent cycleProofRef -> sprintf "credential_cycle_present:%u" cycleProofRef
            | TerminalFlowTerminalConstitutionSchedulerLineageMismatch -> "scheduler_lineage_mismatch"
            | TerminalFlowTerminalConstitutionWorkDagLineageMismatch -> "workdag_lineage_mismatch"
            | TerminalFlowTerminalConstitutionRecoveryLineageMismatch -> "recovery_lineage_mismatch"
            | TerminalFlowTerminalConstitutionTerminalIdentityMismatch -> "terminal_identity_mismatch"
            | TerminalFlowTerminalConstitutionWakerLineageMismatch -> "waker_lineage_mismatch"

        let private terminalFlowTerminalConstitutionSealForStageToken
            (stageToken:TerminalFlowActorOutcomeJoin<TerminalFlowArmedOutcomeJoinedStage>)
            (pending:TerminalFlowGlobalPendingTerminal)
            =
            let tokenRef = terminalFlowMintedRefOf "terminal_stage_token_ref" stageToken.tokenId
            let terminalRef = terminalFlowIdentityRefDigest pending.terminalReceiptRef
            let fillRef = terminalFlowIdentityRefDigest pending.fillRef
            let fairnessEpochRef = terminalFlowIdentityRefDigest stageToken.schedulerRelease.fairnessEpochRef
            let fairnessReleaseRef = terminalFlowIdentityRefDigest stageToken.schedulerRelease.fairnessReleaseRef
            let schedulerReleaseRef = terminalFlowIdentityRefDigest stageToken.schedulerRelease.physicalReleaseRef
            let recoveryRef = stageToken.rootCapability.queueRecoveryRef
            let requiredRefs =
                [ "admission_ref", (terminalFlowActorOutcomeJoinAdmissionRef stageToken)
                  "admission_identity_ref", (terminalFlowActorOutcomeJoinAdmissionIdentityRef stageToken)
                  "actor_binding_ref", (terminalFlowActorOutcomeJoinActorBindingRef stageToken)
                  "credential_ledger_ref", (terminalFlowActorOutcomeJoinCredentialLedgerRef stageToken)
                  "fairness_epoch_ref", (terminalFlowActorOutcomeJoinFairnessEpochRef stageToken)
                  "fairness_release_ref", (terminalFlowActorOutcomeJoinFairnessReleaseRef stageToken)
                  "scheduler_release_ref", schedulerReleaseRef
                  "terminal_order_admission_ref", stageToken.terminalOrderAdmissionRef
                  "actor_ref", (terminalFlowActorOutcomeJoinActorRef stageToken)
                  "terminal_ref", terminalRef
                  "fill_ref", fillRef
                  "workdag_close_receipt_ref", stageToken.workDagTailClosure.closeReceiptRef
                  "root_capability_ref", stageToken.rootCapability.capabilityRef
                  "queue_recovery_ref", recoveryRef
                  "waker_edge_ref", stageToken.wakerEdge.edgeRef
                  "token_ref", tokenRef ]
            match requiredRefs |> List.tryFind (fun (_, value) -> value = 0u) with
            | Some(fieldName, _) -> Error (TerminalFlowTerminalConstitutionLineageContainsZero fieldName)
            | None when stageToken.credentialCycleProofRef <> 0u ->
                Error (TerminalFlowTerminalConstitutionCredentialCyclePresent stageToken.credentialCycleProofRef)
            | None when stageToken.credentialGraphClosureRef = 0u ->
                Error TerminalFlowTerminalConstitutionCredentialGraphOpen
            | None when stageToken.terminalReceiptRef <> pending.terminalReceiptRef
                        || stageToken.fillKey <> pending.fillKeyId ->
                Error TerminalFlowTerminalConstitutionTerminalIdentityMismatch
            | None when stageToken.schedulerRelease.admissionRef <> (terminalFlowActorOutcomeJoinAdmissionRef stageToken)
                        || stageToken.schedulerRelease.admissionIdentityRef <> (terminalFlowActorOutcomeJoinAdmissionIdentityRef stageToken)
                        || stageToken.schedulerRelease.actorBindingRef <> (terminalFlowActorOutcomeJoinActorBindingRef stageToken)
                        || stageToken.schedulerRelease.credentialLedgerRef <> (terminalFlowActorOutcomeJoinCredentialLedgerRef stageToken)
                        || fairnessEpochRef <> (terminalFlowActorOutcomeJoinFairnessEpochRef stageToken)
                        || fairnessReleaseRef <> (terminalFlowActorOutcomeJoinFairnessReleaseRef stageToken) ->
                Error TerminalFlowTerminalConstitutionSchedulerLineageMismatch
            | None when stageToken.rootCapability.workDagCloseReceiptRef <> stageToken.workDagTailClosure.closeReceiptRef
                        || stageToken.workDagTailClosure.remainingObligationCount <> 0 ->
                Error TerminalFlowTerminalConstitutionWorkDagLineageMismatch
            | None ->
                match stageToken.workDagTailClosure.queueOnlyRecovery with
                | TerminalFlowQueueOnlyRecoveryReady(closeReceiptRef, queueRecoveryRef)
                    when closeReceiptRef = stageToken.workDagTailClosure.closeReceiptRef
                         && queueRecoveryRef = recoveryRef ->
                    if stageToken.wakerEdge.edgeRef <> stageToken.workDagTailClosure.wakerEdgeRef
                       || stageToken.wakerEdge.actorRef <> (terminalFlowActorOutcomeJoinActorRef stageToken) then
                        Error TerminalFlowTerminalConstitutionWakerLineageMismatch
                    else
                        let exactOnceRef =
                            terminalFlowMintedRefOf
                                "terminal_constitution_v2_exact_once_ref"
                                (FastRuntimeFormat.format "%u:%u:%u:%u:%u:%u:%u:%u:%u:%u:%u:%u:%u:%u:%u:%u:%u:%u" [| box (terminalFlowActorOutcomeJoinAdmissionRef stageToken); box (terminalFlowActorOutcomeJoinAdmissionIdentityRef stageToken); box (terminalFlowActorOutcomeJoinActorBindingRef stageToken); box (terminalFlowActorOutcomeJoinCredentialLedgerRef stageToken); box stageToken.credentialGraphClosureRef; box (terminalFlowActorOutcomeJoinFairnessEpochRef stageToken); box (terminalFlowActorOutcomeJoinFairnessReleaseRef stageToken); box schedulerReleaseRef; box stageToken.terminalOrderAdmissionRef; box (terminalFlowActorOutcomeJoinActorRef stageToken); box terminalRef; box fillRef; box stageToken.workDagTailClosure.closeReceiptRef; box stageToken.rootCapability.capabilityRef; box recoveryRef; box stageToken.wakerEdge.edgeRef; box tokenRef; box stageToken.wakerEdge.actorRef |])
                        let constitutionRef =
                            terminalFlowMintedRefOf
                                "terminal_constitution_v2_ref"
                                (FastRuntimeFormat.format "%u:%u:%u" [| box (terminalFlowActorOutcomeJoinAdmissionIdentityRef stageToken); box exactOnceRef; box stageToken.credentialGraphClosureRef |])
                        Ok {
                            constitutionRef = constitutionRef
                            disposition = TerminalFlowTerminalConstitutionSuccess
                            admissionRef = (terminalFlowActorOutcomeJoinAdmissionRef stageToken)
                            admissionIdentityRef = (terminalFlowActorOutcomeJoinAdmissionIdentityRef stageToken)
                            actorBindingRef = (terminalFlowActorOutcomeJoinActorBindingRef stageToken)
                            credentialLedgerRef = (terminalFlowActorOutcomeJoinCredentialLedgerRef stageToken)
                            credentialGraphClosureRef = stageToken.credentialGraphClosureRef
                            fairnessEpochRef = (terminalFlowActorOutcomeJoinFairnessEpochRef stageToken)
                            fairnessReleaseRef = (terminalFlowActorOutcomeJoinFairnessReleaseRef stageToken)
                            schedulerReleaseRef = schedulerReleaseRef
                            terminalOrderAdmissionRef = stageToken.terminalOrderAdmissionRef
                            actorRef = (terminalFlowActorOutcomeJoinActorRef stageToken)
                            terminalRef = terminalRef
                            fillRef = fillRef
                            workDagCloseReceiptRef = stageToken.workDagTailClosure.closeReceiptRef
                            rootCapabilityRef = stageToken.rootCapability.capabilityRef
                            queueRecoveryRef = recoveryRef
                            wakerEdgeRef = stageToken.wakerEdge.edgeRef
                            tokenRef = tokenRef
                            exactOnceRef = exactOnceRef
                            sealedAtMs = Environment.TickCount64
                        }
                | _ -> Error TerminalFlowTerminalConstitutionRecoveryLineageMismatch

        let private terminalFlowTerminalFailClosedConstitution
            terminalRef
            fillRef
            admissionIdentityRef
            schedulerReleaseRef
            failureRef
            =
            let exactOnceRef =
                terminalFlowMintedRefOf
                    "terminal_failclosed_constitution_exact_once_ref"
                    (FastRuntimeFormat.format "%u:%u:%u:%u:%u" [| box terminalRef; box fillRef; box admissionIdentityRef; box schedulerReleaseRef; box failureRef |])
            { constitutionRef = terminalFlowMintedRefOf "terminal_failclosed_constitution_ref" (sprintf "%u:%u" failureRef exactOnceRef)
              disposition = TerminalFlowTerminalConstitutionFailClosed failureRef
              admissionRef = 0u
              admissionIdentityRef = admissionIdentityRef
              actorBindingRef = 0u
              credentialLedgerRef = 0u
              credentialGraphClosureRef = 0u
              fairnessEpochRef = 0u
              fairnessReleaseRef = 0u
              schedulerReleaseRef = schedulerReleaseRef
              terminalOrderAdmissionRef = 0u
              actorRef = 0u
              terminalRef = terminalRef
              fillRef = fillRef
              workDagCloseReceiptRef = 0u
              rootCapabilityRef = 0u
              queueRecoveryRef = 0u
              wakerEdgeRef = 0u
              tokenRef = 0u
              exactOnceRef = exactOnceRef
              sealedAtMs = Environment.TickCount64 }

