        type TerminalFlowReducerStageTokenFailureReceipt = private {
            receiptRef : uint32
            constitutionRef : uint32
            ratificationRef : uint32
            issueReceiptRef : uint32
            tokenRef : uint32 option
            actorRef : uint32 option
            terminalRef : uint32
            fillRef : uint32
            admissionRef : uint32
            admissionIdentityRef : uint32
            schedulerReleaseRef : uint32
            failureRef : uint32
            exactOnceRef : uint32
            failedAtMs : int64
        }

        // MIGRATION / destructive migration 4 of 5: the terminal order is now
        // minted by the reducer as one typed linear covenant. Host shutdown is
        // not an observer shortcut; it either reconciles to this chain or mints
        // the same bounded fail-closed chain with explicit predecessors.
        type TerminalFlowReducerCommitSealStage = class end
        type TerminalFlowReducerDoneSealStage = class end
        type TerminalFlowReducerRunEndSealStage = class end
        type TerminalFlowReducerPhysicalExitSealStage = class end

        type TerminalFlowReducerTotalOrderReceipt<'Stage> = private {
            receiptRef : uint32
            predecessorReceiptRef : uint32
            constitutionRef : uint32
            actorRef : uint32
            terminalRef : uint32
            fillRef : uint32
            exactOnceRef : uint32
            totalOrderIndex : int64
            reducerSequence : int64
            issuedAtMs : int64
        }

        type TerminalFlowReducerTotalOrderChain = private {
            commit : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerCommitSealStage>
            doneReceipt : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerDoneSealStage>
            runEnd : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerRunEndSealStage>
            physicalExit : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerPhysicalExitSealStage>
            ratificationRef : uint32
            exitCode : int
            failureRef : uint32 option
            processExitAuthorization : TerminalFlowReducerProcessExitAuthorization
        }

        let private terminalFlowIndexedClosureDurableChains =
            System.Collections.Concurrent.ConcurrentDictionary<uint32, TerminalFlowReducerTotalOrderChain * string>()

        type TerminalFlowReducerFailureLineage =
            | TerminalFlowReducerSuccessLineage
            | TerminalFlowReducerTypedFailureLineage of TerminalFlowDurableRef<TerminalFlowFailureRefKind>

        let private terminalFlowReducerFailureLineage (chain:TerminalFlowReducerTotalOrderChain) =
            match chain.failureRef with
            | Some failureRef ->
                TerminalFlowReducerTypedFailureLineage (TerminalFlowDurableRef failureRef)
            | None ->
                TerminalFlowReducerSuccessLineage

        let private terminalFlowReducerFailureLineageValue = function
            | TerminalFlowReducerSuccessLineage -> 0u
            | TerminalFlowReducerTypedFailureLineage failureRef -> terminalFlowDurableRefValue failureRef

        type TerminalFlowIndexedClosureExitRequestMatchId =
            | TerminalFlowIndexedClosureExitRequestExactLineage
            | TerminalFlowIndexedClosureExitRequestExitCodeMismatch of requestExitCode:int * chainExitCode:int
            | TerminalFlowIndexedClosureExitRequestRunEndMismatch of requestRunEndRef:uint32 * chainRunEndRef:uint32
            | TerminalFlowIndexedClosureExitRequestFailureMismatch of requestFailureRef:uint32 * chainFailureRef:uint32
            | TerminalFlowIndexedClosureExitRequestLineageKindMismatch

        let private terminalFlowIndexedClosureExitRequestMatchText = function
            | TerminalFlowIndexedClosureExitRequestExactLineage -> "ExactLineage"
            | TerminalFlowIndexedClosureExitRequestExitCodeMismatch(requestExitCode, chainExitCode) ->
                FastRuntimeFormat.format "ExitCodeMismatch(request=%d|chain=%d)" [| box requestExitCode; box chainExitCode |]
            | TerminalFlowIndexedClosureExitRequestRunEndMismatch(requestRunEndRef, chainRunEndRef) ->
                FastRuntimeFormat.format "RunEndMismatch(request=%u|chain=%u)" [| box requestRunEndRef; box chainRunEndRef |]
            | TerminalFlowIndexedClosureExitRequestFailureMismatch(requestFailureRef, chainFailureRef) ->
                FastRuntimeFormat.format "FailureMismatch(request=%u|chain=%u)" [| box requestFailureRef; box chainFailureRef |]
            | TerminalFlowIndexedClosureExitRequestLineageKindMismatch -> "LineageKindMismatch"

        let private terminalFlowIndexedClosureExitRequestMatch
            (chain:TerminalFlowReducerTotalOrderChain)
            (request:TerminalFlowGlobalExitRequest) =
            if request.exitCode <> chain.exitCode then
                TerminalFlowIndexedClosureExitRequestExitCodeMismatch(request.exitCode, chain.exitCode)
            else
                match request.origin, terminalFlowReducerFailureLineage chain with
                | TerminalFlowGlobalExitFromBreakthroughDone proof, TerminalFlowReducerSuccessLineage ->
                    if proof.runEndReceiptRef = chain.runEnd.receiptRef then
                        TerminalFlowIndexedClosureExitRequestExactLineage
                    else
                        TerminalFlowIndexedClosureExitRequestRunEndMismatch(proof.runEndReceiptRef, chain.runEnd.receiptRef)
                | TerminalFlowGlobalExitFromTypedFailure requestFailureRef,
                  TerminalFlowReducerTypedFailureLineage chainFailureRef ->
                    let requestFailureRef = terminalFlowDurableRefValue requestFailureRef
                    let chainFailureRef = terminalFlowDurableRefValue chainFailureRef
                    if requestFailureRef = chainFailureRef then
                        TerminalFlowIndexedClosureExitRequestExactLineage
                    else
                        TerminalFlowIndexedClosureExitRequestFailureMismatch(requestFailureRef, chainFailureRef)
                | _ -> TerminalFlowIndexedClosureExitRequestLineageKindMismatch

        let private terminalFlowIndexedClosureExitRequestMatchIsExact = function
            | TerminalFlowIndexedClosureExitRequestExactLineage -> true
            | _ -> false

        let private terminalFlowFindIndexedClosureExitRequest (chain:TerminalFlowReducerTotalOrderChain) =
            terminalFlowIndexedClosurePendingExitRequests.ToArray()
            |> Array.filter (fun entry ->
                terminalFlowIndexedClosureExitRequestMatch chain entry.Value
                |> terminalFlowIndexedClosureExitRequestMatchIsExact)
            |> Array.sortBy (fun entry -> entry.Key)
            |> Array.tryHead
            |> Option.map (fun entry -> entry.Value)

        let private terminalFlowReplayIndexedClosureExit
            (chain:TerminalFlowReducerTotalOrderChain)
            closureProofRef =
            let physicalExitReceiptRef = chain.physicalExit.receiptRef
            match terminalFlowFindIndexedClosureExitRequest chain with
            | Some request when terminalFlowIndexedClosureExitReplayKeys.TryAdd(physicalExitReceiptRef, 0uy) ->
                let requestRef = terminalFlowMintedRefOf "indexed_closure_exit_replay_request_ref" request.requestId
                terminalFlowRememberIndexedClosureInlineExitReplay physicalExitReceiptRef request
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_indexed_closure_exit_republished\",\"request_ref\":%u,\"physical_exit_receipt_ref\":%u,\"closure_proof_ref\":%s,\"exit_code\":%d,\"match_authority_du\":\"RunEndOrTypedFailureLineage\",\"inline_reducer_replay_pending\":true,\"control_wake_pending\":true,\"authority\":\"indexed_closure_ready_replays_exit_witness_to_single_reducer\",\"next\":\"consume_inline_on_next_reducer_turn_or_control_wake_first\"}" [| box requestRef; box physicalExitReceiptRef; box (DiagJson.esc closureProofRef); box request.exitCode |])
                terminalFlowIndexedClosureExitReplayHook request
                TerminalFlowIndexedClosureExitReplayPublished requestRef
            | Some request ->
                TerminalFlowIndexedClosureExitReplayAlreadyPublished(
                    terminalFlowMintedRefOf "indexed_closure_exit_replay_request_ref" request.requestId)
            | None ->
                let pendingRequests = terminalFlowIndexedClosurePendingExitRequests.ToArray()
                let sameExitCodeCount =
                    pendingRequests
                    |> Array.sumBy (fun entry -> if entry.Value.exitCode = chain.exitCode then 1 else 0)
                let mismatchSampleDu =
                    pendingRequests
                    |> Array.sortBy (fun entry -> entry.Key)
                    |> Array.tryHead
                    |> Option.map (fun entry ->
                        terminalFlowIndexedClosureExitRequestMatch chain entry.Value
                        |> terminalFlowIndexedClosureExitRequestMatchText)
                    |> Option.defaultValue "NoPendingRequests"
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_indexed_closure_exit_replay_missing\",\"physical_exit_receipt_ref\":%u,\"run_end_receipt_ref\":%u,\"failure_ref\":%u,\"closure_proof_ref\":%s,\"pending_request_count\":%d,\"same_exit_code_request_count\":%d,\"request_match_sample_du\":%s,\"authority\":\"indexed_closure_ready_without_matching_exit_lineage\",\"physical_exit\":false}" [| box physicalExitReceiptRef; box chain.runEnd.receiptRef; box (terminalFlowReducerFailureLineageValue (terminalFlowReducerFailureLineage chain)); box (DiagJson.esc closureProofRef); box pendingRequests.Length; box sameExitCodeCount; box (DiagJson.esc mismatchSampleDu) |])
                TerminalFlowIndexedClosureExitReplayRequestMissing

        let private terminalFlowReplayLateIndexedClosureExitRequest (request:TerminalFlowGlobalExitRequest) =
            terminalFlowIndexedClosureDurableChains.ToArray()
            |> Array.map (fun entry -> entry.Key, entry.Value)
            |> Array.filter (fun (_, (chain, _)) -> terminalFlowIndexedClosureExitRequestMatch chain request |> terminalFlowIndexedClosureExitRequestMatchIsExact)
            |> Array.sortBy fst
            |> Array.tryHead
            |> Option.iter (fun (physicalExitReceiptRef, (chain, closureProofRef)) ->
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_indexed_closure_late_exit_request_matched\",\"request_ref\":%u,\"physical_exit_receipt_ref\":%u,\"closure_proof_ref\":%s,\"exit_code\":%d,\"authority\":\"durable_closure_plus_late_exit_lineage\",\"next\":\"replay_exit_witness_exact_once\"}" [| box (terminalFlowMintedRefOf "indexed_closure_exit_request_ref" request.requestId); box physicalExitReceiptRef; box (DiagJson.esc closureProofRef); box request.exitCode |])
                terminalFlowReplayIndexedClosureExit chain closureProofRef |> ignore)

        do
            terminalFlowInstallIndexedClosureLateRequestReplay terminalFlowReplayLateIndexedClosureExitRequest

        let terminalFlowReducerProcessExitAllowed chain =
            match chain.processExitAuthorization with
            | TerminalFlowReducerProcessExitRatified -> true
            | TerminalFlowReducerProcessExitRejected _ -> false

        type TerminalFlowReducerTerminalSealAuthority =
            | TerminalFlowReducerTerminalSealAwaitStageToken
            | TerminalFlowReducerTerminalSealPhysicalExitSelected of TerminalFlowReducerTotalOrderChain
            | TerminalFlowReducerTerminalSealFailClosedSelected of TerminalFlowReducerTotalOrderChain

        // MIGRATION: observer exit petitions now enter the reducer as a typed
        // authority decision instead of an option plus stringly reason branches.
        // A ratified total-order chain is a first-class authority witness; a
        // projection without ratification remains dataflow-only and cannot exit.
        type private TerminalFlowObserverExitPetitionAuthority =
            | TerminalFlowObserverExitPetitionRatifiedTotalOrder of TerminalFlowReducerTotalOrderChain
            | TerminalFlowObserverExitPetitionOwnerClosure
            | TerminalFlowObserverExitPetitionProjectionWithoutRatification of sourceRef:uint32

        let private terminalFlowObserverExitPetitionAuthorityText = function
            | TerminalFlowObserverExitPetitionRatifiedTotalOrder _ ->
                "ObserverExitPetitionAuthority(RatifiedReducerTotalOrder)"
            | TerminalFlowObserverExitPetitionOwnerClosure ->
                "ObserverExitPetitionAuthority(OwnerClosure)"
            | TerminalFlowObserverExitPetitionProjectionWithoutRatification _ ->
                "ObserverExitPetitionAuthority(ProjectionWithoutRatification)"

        type TerminalFlowReducerHostShutdownResultId =
            | TerminalFlowReducerHostShutdownReconciledToTotalOrder of requestRef:uint32 * physicalExitReceiptRef:uint32
            | TerminalFlowReducerHostShutdownFailClosedTotalOrder of requestRef:uint32 * failureRef:uint32 * physicalExitReceiptRef:uint32

        let private terminalFlowReducerTotalOrderReceipt
            (label:string)
            (predecessorReceiptRef:uint32)
            (constitutionRef:uint32)
            (actorRef:uint32)
            (terminalRef:uint32)
            (fillRef:uint32)
            (exactOnceSeed:uint32)
            (totalOrderIndex:int64)
            (reducerSequence:int64)
            : TerminalFlowReducerTotalOrderReceipt<'Stage> =
            if constitutionRef = 0u then
                invalidOp (label + " requires a nonzero terminal constitution")
            let receiptRef =
                terminalFlowMintedRefOf
                    label
                    (FastRuntimeFormat.format "%u:%u:%u:%u:%u:%u:%d:%d" [| box predecessorReceiptRef; box constitutionRef; box actorRef; box terminalRef; box fillRef; box exactOnceSeed; box totalOrderIndex; box reducerSequence |])
            { receiptRef = receiptRef
              predecessorReceiptRef = predecessorReceiptRef
              constitutionRef = constitutionRef
              actorRef = actorRef
              terminalRef = terminalRef
              fillRef = fillRef
              exactOnceRef = terminalFlowMintedRefOf (label + "_exact_once") (FastRuntimeFormat.format "%u:%u:%u" [| box receiptRef; box constitutionRef; box exactOnceSeed |])
              totalOrderIndex = totalOrderIndex
              reducerSequence = reducerSequence
              issuedAtMs = Environment.TickCount64 }

        let private terminalFlowReducerTotalOrderLinear
            (commit:TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerCommitSealStage>)
            (doneReceipt:TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerDoneSealStage>)
            (runEnd:TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerRunEndSealStage>)
            (physicalExit:TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerPhysicalExitSealStage>)
            =
            let sameIdentity leftActor leftTerminal leftFill rightActor rightTerminal rightFill =
                leftActor = rightActor && leftTerminal = rightTerminal && leftFill = rightFill
            commit.constitutionRef <> 0u
            && doneReceipt.constitutionRef = commit.constitutionRef
            && runEnd.constitutionRef = commit.constitutionRef
            && physicalExit.constitutionRef = commit.constitutionRef
            && doneReceipt.predecessorReceiptRef = commit.receiptRef
            && runEnd.predecessorReceiptRef = doneReceipt.receiptRef
            && physicalExit.predecessorReceiptRef = runEnd.receiptRef
            && commit.totalOrderIndex = 1L
            && doneReceipt.totalOrderIndex = 2L
            && runEnd.totalOrderIndex = 3L
            && physicalExit.totalOrderIndex = 4L
            && sameIdentity commit.actorRef commit.terminalRef commit.fillRef doneReceipt.actorRef doneReceipt.terminalRef doneReceipt.fillRef
            && sameIdentity commit.actorRef commit.terminalRef commit.fillRef runEnd.actorRef runEnd.terminalRef runEnd.fillRef
            && sameIdentity commit.actorRef commit.terminalRef commit.fillRef physicalExit.actorRef physicalExit.terminalRef physicalExit.fillRef

        type TerminalFlowTerminalConstitutionFixtureVector = private {
            name : string
            observed : bool
            expected : bool
        }

        let private terminalFlowTerminalConstitutionFixtureVectors () =
            let constitutionRef = 101u
            let actorRef = 103u
            let terminalRef = 107u
            let fillRef = 109u
            let commit : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerCommitSealStage> =
                terminalFlowReducerTotalOrderReceipt "fixture_commit" 97u constitutionRef actorRef terminalRef fillRef 113u 1L 127L
            let doneReceipt : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerDoneSealStage> =
                terminalFlowReducerTotalOrderReceipt "fixture_done" commit.receiptRef constitutionRef actorRef terminalRef fillRef commit.exactOnceRef 2L 127L
            let runEnd : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerRunEndSealStage> =
                terminalFlowReducerTotalOrderReceipt "fixture_run_end" doneReceipt.receiptRef constitutionRef actorRef terminalRef fillRef doneReceipt.exactOnceRef 3L 127L
            let physicalExit : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerPhysicalExitSealStage> =
                terminalFlowReducerTotalOrderReceipt "fixture_physical_exit" runEnd.receiptRef constitutionRef actorRef terminalRef fillRef runEnd.exactOnceRef 4L 127L
            let wrongConstitutionDone : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerDoneSealStage> =
                terminalFlowReducerTotalOrderReceipt "fixture_wrong_constitution" commit.receiptRef (constitutionRef + 1u) actorRef terminalRef fillRef commit.exactOnceRef 2L 127L
            let wrongPredecessorRunEnd : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerRunEndSealStage> =
                terminalFlowReducerTotalOrderReceipt "fixture_wrong_predecessor" 999u constitutionRef actorRef terminalRef fillRef doneReceipt.exactOnceRef 3L 127L
            let wrongIdentityExit : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerPhysicalExitSealStage> =
                terminalFlowReducerTotalOrderReceipt "fixture_wrong_identity" runEnd.receiptRef constitutionRef actorRef terminalRef (fillRef + 1u) runEnd.exactOnceRef 4L 127L
            let failClosed = terminalFlowTerminalFailClosedConstitution terminalRef fillRef 0u 0u 131u
            [| { name = "positive_linear_total_order"; observed = terminalFlowReducerTotalOrderLinear commit doneReceipt runEnd physicalExit; expected = true }
               { name = "reject_constitution_change"; observed = terminalFlowReducerTotalOrderLinear commit wrongConstitutionDone runEnd physicalExit; expected = false }
               { name = "reject_predecessor_gap"; observed = terminalFlowReducerTotalOrderLinear commit doneReceipt wrongPredecessorRunEnd physicalExit; expected = false }
               { name = "reject_identity_change"; observed = terminalFlowReducerTotalOrderLinear commit doneReceipt runEnd wrongIdentityExit; expected = false }
               { name = "failclosed_constitution_nonzero"; observed = failClosed.constitutionRef <> 0u && failClosed.exactOnceRef <> 0u; expected = true }
               { name = "success_constitution_distinct_from_failclose"; observed = failClosed.constitutionRef <> constitutionRef; expected = true } |]

        type TerminalFlowTerminalRatificationFixtureVector = private {
            name : string
            constitutionRef : uint32
            writerCapabilityRef : uint32
            writerJobRef : uint32
            artifactReceiptRef : uint32
            exitWitnessRef : uint32
            fillReceiptRef : uint32
            runEndReceiptRef : uint32
            wakerEdgeRef : uint32
            expected : bool
        }

        let private terminalFlowTerminalRatificationFixtureDecision vector =
            vector.constitutionRef <> 0u
            && vector.writerCapabilityRef <> 0u
            && vector.writerJobRef <> 0u
            && vector.artifactReceiptRef <> 0u
            && vector.exitWitnessRef <> 0u
            && vector.fillReceiptRef <> 0u
            && vector.runEndReceiptRef <> 0u
            && vector.wakerEdgeRef <> 0u

        let private terminalFlowTerminalRatificationFixtureVectors () =
            let positive =
                { name = "real_artifact_ratifies_constitution"; constitutionRef = 151u; writerCapabilityRef = 157u; writerJobRef = 163u; artifactReceiptRef = 167u; exitWitnessRef = 173u; fillReceiptRef = 179u; runEndReceiptRef = 181u; wakerEdgeRef = 191u; expected = true }
            [| positive
               { positive with name = "reject_missing_writer"; writerCapabilityRef = 0u; expected = false }
               { positive with name = "reject_missing_artifact"; artifactReceiptRef = 0u; expected = false }
               { positive with name = "reject_missing_exit_witness"; exitWitnessRef = 0u; expected = false }
               { positive with name = "reject_missing_run_end"; runEndReceiptRef = 0u; expected = false }
               { positive with name = "reject_missing_waker"; wakerEdgeRef = 0u; expected = false } |]

        let private terminalFlowTerminalRatificationFixtureProven () =
            terminalFlowTerminalRatificationFixtureVectors ()
            |> Array.forall (fun vector -> terminalFlowTerminalRatificationFixtureDecision vector = vector.expected)

        let private terminalFlowTerminalConstitutionFixtureProven () =
            terminalFlowTerminalConstitutionFixtureVectors ()
            |> Array.forall (fun vector -> vector.observed = vector.expected)

        let private terminalFlowRunLocalConformance () =
            CompilerRuntimeActivation.requireInProcessEntered "terminal_flow_local_conformance"
            if terminalFlowTotalOrderReceiptRef terminalFlowTotalOrderGenesis = 0u then
                invalidOp "terminal total-order genesis receipt must be non-zero"
            if not (terminalFlowCredentialGraphFixtureProven ()) then
                invalidOp "terminal credential graph fixture matrix failed"
            if not (terminalFlowLinearPossessionFixtureProven ()) then
                invalidOp "terminal linear possession fixture matrix failed"
            if not (terminalFlowTerminalConstitutionFixtureProven ()) then
                invalidOp "terminal constitution and total-order fixture matrix failed"
            if not (terminalFlowTerminalRatificationFixtureProven ()) then
                invalidOp "terminal artifact ratification fixture matrix failed"

        let private terminalFlowReducerTotalOrderChainForSealAuthorization
            reducerSequence
            (receipt:TerminalFlowReducerStageTokenSealAuthorizationReceipt) =
            let commit : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerCommitSealStage> =
                terminalFlowReducerTotalOrderReceipt
                    "terminal_reducer_commit_receipt"
                    receipt.receiptRef
                    receipt.constitutionRef
                    receipt.actorRef
                    receipt.terminalRef
                    receipt.fillRef
                    receipt.exactOnceRef
                    1L
                    reducerSequence
            let doneReceipt : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerDoneSealStage> =
                terminalFlowReducerTotalOrderReceipt
                    "terminal_reducer_done_receipt"
                    commit.receiptRef
                    receipt.constitutionRef
                    receipt.actorRef
                    receipt.terminalRef
                    receipt.fillRef
                    commit.exactOnceRef
                    2L
                    reducerSequence
            let runEnd : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerRunEndSealStage> =
                terminalFlowReducerTotalOrderReceipt
                    "terminal_reducer_run_end_receipt"
                    doneReceipt.receiptRef
                    receipt.constitutionRef
                    receipt.actorRef
                    receipt.terminalRef
                    receipt.fillRef
                    doneReceipt.exactOnceRef
                    3L
                    reducerSequence
            let physicalExit : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerPhysicalExitSealStage> =
                terminalFlowReducerTotalOrderReceipt
                    "terminal_reducer_physical_exit_receipt"
                    runEnd.receiptRef
                    receipt.constitutionRef
                    receipt.actorRef
                    receipt.terminalRef
                    receipt.fillRef
                    runEnd.exactOnceRef
                    4L
                    reducerSequence
            let processExitAllowed = terminalFlowReducerTotalOrderLinear commit doneReceipt runEnd physicalExit
            { commit = commit
              doneReceipt = doneReceipt
              runEnd = runEnd
              physicalExit = physicalExit
              ratificationRef = receipt.ratificationRef
              exitCode = 0
              failureRef = None
              processExitAuthorization =
                if processExitAllowed && receipt.ratificationRef <> 0u then TerminalFlowReducerProcessExitRatified
                else TerminalFlowReducerProcessExitRejected(CompilerKernelV2.OperationalReasonIdOps.create "linear_or_ratification_rejected") }

