                    "terminal_stage_token_failure_done_receipt"
                    commit.receiptRef
                    receipt.constitutionRef
                    actorRef
                    receipt.terminalRef
                    receipt.fillRef
                    commit.exactOnceRef
                    2L
                    reducerSequence
            let runEnd : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerRunEndSealStage> =
                terminalFlowReducerTotalOrderReceipt
                    "terminal_stage_token_failure_run_end_receipt"
                    doneReceipt.receiptRef
