              processExitAuthorization =
                if processExitAllowed && receipt.ratificationRef <> 0u then TerminalFlowReducerProcessExitRatified
                else TerminalFlowReducerProcessExitRejected(CompilerKernelV2.OperationalReasonIdOps.create "linear_or_ratification_rejected") }

        let private terminalFlowHostShutdownReasonText = function
            | TerminalFlowHostShutdownProcessExit -> "process_exit"
            | TerminalFlowHostShutdownCancellation -> "cancellation"
            | TerminalFlowHostShutdownFatalHostException exceptionRef -> sprintf "fatal_host_exception:%u" exceptionRef

        let private terminalFlowReducerTotalOrderChainForHostShutdown
            reducerSequence
            (request:TerminalFlowHostShutdownRequest)
            actorRef
            terminalRef
            fillRef =
            let requestRef = terminalFlowIdentityRefDigest request.requestRef
            let failureRef =
                terminalFlowMintedRefOf
                    "terminal_host_shutdown_failclosed_ref"
                    (FastRuntimeFormat.format "%u:%s:%d" [| box requestRef; box (terminalFlowHostShutdownReasonText request.reason); box request.observedAtMs |])
            let constitution = terminalFlowTerminalFailClosedConstitution terminalRef fillRef 0u 0u failureRef
            let ratificationRef =
                terminalFlowMintedRefOf
                    "terminal_host_shutdown_ratification_ref"
                    (FastRuntimeFormat.format "%u:%u:%u" [| box constitution.constitutionRef; box failureRef; box requestRef |])
            let commit : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerCommitSealStage> =
                terminalFlowReducerTotalOrderReceipt
                    "terminal_host_shutdown_commit_receipt"
                    failureRef
                    constitution.constitutionRef
                    actorRef
                    terminalRef
                    fillRef
                    failureRef
                    1L
                    reducerSequence
            let doneReceipt : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerDoneSealStage> =
                terminalFlowReducerTotalOrderReceipt
                    "terminal_host_shutdown_done_receipt"
                    commit.receiptRef
                    constitution.constitutionRef
                    actorRef
                    terminalRef
                    fillRef
                    commit.exactOnceRef
                    2L
                    reducerSequence
            let runEnd : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerRunEndSealStage> =
                terminalFlowReducerTotalOrderReceipt
                    "terminal_host_shutdown_run_end_receipt"
                    doneReceipt.receiptRef
                    constitution.constitutionRef
                    actorRef
                    terminalRef
                    fillRef
                    doneReceipt.exactOnceRef
                    3L
                    reducerSequence
            let physicalExit : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerPhysicalExitSealStage> =
                terminalFlowReducerTotalOrderReceipt
                    "terminal_host_shutdown_physical_exit_receipt"
                    runEnd.receiptRef
                    constitution.constitutionRef
                    actorRef
                    terminalRef
                    fillRef
                    runEnd.exactOnceRef
                    4L
                    reducerSequence
            let processExitAllowed = terminalFlowReducerTotalOrderLinear commit doneReceipt runEnd physicalExit
            failureRef,
            { commit = commit
              doneReceipt = doneReceipt
              runEnd = runEnd
              physicalExit = physicalExit
              ratificationRef = ratificationRef
              exitCode = 1
              failureRef = Some failureRef
              processExitAuthorization =
                if processExitAllowed && ratificationRef <> 0u then TerminalFlowReducerProcessExitRatified
                else TerminalFlowReducerProcessExitRejected(CompilerKernelV2.OperationalReasonIdOps.create "linear_or_ratification_rejected") }

        let private terminalFlowReducerFailClosedChainFromTypedFailure
            (reducerSequence:int64)
            (receipt:TerminalFlowTypedFailureOrderReceipt) =
            let commit : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerCommitSealStage> =
                { receiptRef = receipt.commitReceiptId
                  predecessorReceiptRef = receipt.constitutionRef
                  constitutionRef = receipt.constitutionRef
                  actorRef = 0u
                  terminalRef = receipt.terminalRef
                  fillRef = receipt.fillRef
                  exactOnceRef = receipt.exactOnceRef
                  totalOrderIndex = 1L
                  reducerSequence = reducerSequence
                  issuedAtMs = receipt.selectedAtMs }
            let doneReceipt : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerDoneSealStage> =
                { receiptRef = receipt.doneReceiptId
                  predecessorReceiptRef = receipt.commitReceiptId
                  constitutionRef = receipt.constitutionRef
                  actorRef = 0u
                  terminalRef = receipt.terminalRef
                  fillRef = receipt.fillRef
                  exactOnceRef = receipt.exactOnceRef
                  totalOrderIndex = 2L
                  reducerSequence = reducerSequence
                  issuedAtMs = receipt.selectedAtMs }
            let runEnd : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerRunEndSealStage> =
                { receiptRef = receipt.runEndReceiptId
                  predecessorReceiptRef = receipt.doneReceiptId
                  constitutionRef = receipt.constitutionRef
                  actorRef = 0u
                  terminalRef = receipt.terminalRef
                  fillRef = receipt.fillRef
                  exactOnceRef = receipt.exactOnceRef
                  totalOrderIndex = 3L
                  reducerSequence = reducerSequence
                  issuedAtMs = receipt.selectedAtMs }
            let physicalExit : TerminalFlowReducerTotalOrderReceipt<TerminalFlowReducerPhysicalExitSealStage> =
                { receiptRef = receipt.physicalExitReceiptId
                  predecessorReceiptRef = receipt.runEndReceiptId
                  constitutionRef = receipt.constitutionRef
                  actorRef = 0u
                  terminalRef = receipt.terminalRef
                  fillRef = receipt.fillRef
                  exactOnceRef = receipt.exactOnceRef
                  totalOrderIndex = 4L
                  reducerSequence = reducerSequence
                  issuedAtMs = receipt.selectedAtMs }
            { commit = commit
              doneReceipt = doneReceipt
              runEnd = runEnd
              physicalExit = physicalExit
              ratificationRef = receipt.exactOnceRef
              exitCode = receipt.exitCode
              failureRef = Some receipt.failureRef
              processExitAuthorization =
                if terminalFlowReducerProcessExitAuthorizationAllows receipt.processExitAuthorization
                   && terminalFlowReducerTotalOrderLinear commit doneReceipt runEnd physicalExit then
                    TerminalFlowReducerProcessExitRatified
                else
                    TerminalFlowReducerProcessExitRejected(CompilerKernelV2.OperationalReasonIdOps.create "typed_failure_total_order_rejected") }

        let private terminalFlowReducerTotalOrderChainText (chain:TerminalFlowReducerTotalOrderChain) =
            FastRuntimeFormat.format "constitution=%u|ratification=%u|commit=%u|done=%u|run_end=%u|physical_exit=%u|exit_code=%d|failure_ref=%u|allowed=%b" [| box chain.commit.constitutionRef; box chain.ratificationRef; box chain.commit.receiptRef; box chain.doneReceipt.receiptRef; box chain.runEnd.receiptRef; box chain.physicalExit.receiptRef; box chain.exitCode; box (chain.failureRef |> Option.defaultValue 0u); box (terminalFlowReducerProcessExitAllowed chain) |]

        type private TerminalFlowIndexedClosureTrigger =
            | TerminalFlowIndexedClosureStageTokenSealAuthorized
            | TerminalFlowIndexedClosureStageTokenFailedClosed
            | TerminalFlowIndexedClosureHostShutdownFailClosed
            | TerminalFlowIndexedClosureTypedFailureCutover

        type private TerminalFlowIndexedClosureAttempt =
            | TerminalFlowIndexedClosureInitial of TerminalFlowIndexedClosureTrigger
            | TerminalFlowIndexedClosureRetry of TerminalFlowIndexedClosureTrigger

        let private terminalFlowIndexedClosureTriggerText = function
            | TerminalFlowIndexedClosureStageTokenSealAuthorized -> "StageTokenSealAuthorized"
            | TerminalFlowIndexedClosureStageTokenFailedClosed -> "StageTokenFailedClosed"
            | TerminalFlowIndexedClosureHostShutdownFailClosed -> "HostShutdownFailClosed"
            | TerminalFlowIndexedClosureTypedFailureCutover -> "typed_failure_cutover"

        let private terminalFlowIndexedClosureAttemptText = function
            | TerminalFlowIndexedClosureInitial trigger -> terminalFlowIndexedClosureTriggerText trigger
            | TerminalFlowIndexedClosureRetry trigger -> terminalFlowIndexedClosureTriggerText trigger + ":retry"

        let private terminalFlowIndexedClosureTriggerOfAttempt = function
            | TerminalFlowIndexedClosureInitial trigger
            | TerminalFlowIndexedClosureRetry trigger -> trigger

        let private terminalFlowReducerTotalOrderEdgeEmissionKeys =
            System.Collections.Concurrent.ConcurrentDictionary<uint32, byte>()

        let private terminalFlowReducerTotalOrderClosureEmissionKeys =
            System.Collections.Concurrent.ConcurrentDictionary<uint32, byte>()

        let private terminalFlowReducerPendingClosureChains =
            System.Collections.Concurrent.ConcurrentDictionary<uint32, TerminalFlowIndexedClosureTrigger * TerminalFlowReducerTotalOrderChain>()
        let private terminalFlowReducerPendingClosureRetryGate = obj()
        let mutable private terminalFlowReducerPendingClosureRetryRunning = false

        type TerminalFlowIndexedClosureCreditRefusalId =
            | TerminalFlowTerminalSemanticCreditRetireRefused
            | TerminalFlowSemanticCreditOutstandingAfterTerminalRetire

        let private terminalFlowIndexedClosureCreditRefusalText = function
            | TerminalFlowTerminalSemanticCreditRetireRefused -> "TerminalSemanticCreditRetireRefused"
            | TerminalFlowSemanticCreditOutstandingAfterTerminalRetire -> "SemanticCreditOutstandingAfterTerminalRetire"

        type TerminalFlowTerminalSemanticCreditResolutionId =
            | TerminalFlowTerminalSemanticCreditResolvedExact
            | TerminalFlowTerminalSemanticCreditResolvedFailClosedUnique of reconciliationRef:CompilerIdentityKernel.ContentDigest
            | TerminalFlowTerminalSemanticCreditAlreadyReturned of reconciliationRef:CompilerIdentityKernel.ContentDigest
            | TerminalFlowTerminalSemanticCreditRejectedSuccessIdentityMissing
            | TerminalFlowTerminalSemanticCreditRejectedOperationalCreditOpen of openCount:int
            | TerminalFlowTerminalSemanticCreditRejectedMultiplicity of openCount:int
            | TerminalFlowTerminalSemanticCreditRejectedLedgerConflict

        let private terminalFlowTerminalSemanticCreditResolutionText = function
            | TerminalFlowTerminalSemanticCreditResolvedExact -> "ResolvedExactIdentity"
            | TerminalFlowTerminalSemanticCreditResolvedFailClosedUnique reconciliationRef ->
                "ResolvedFailClosedUnique(" + CompilerIdentityKernel.ContentDigest.text reconciliationRef + ")"
            | TerminalFlowTerminalSemanticCreditAlreadyReturned reconciliationRef ->
                "AlreadyReturned(" + CompilerIdentityKernel.ContentDigest.text reconciliationRef + ")"
            | TerminalFlowTerminalSemanticCreditRejectedSuccessIdentityMissing -> "RejectedSuccessIdentityMissing"
            | TerminalFlowTerminalSemanticCreditRejectedOperationalCreditOpen openCount ->
                "RejectedOperationalCreditStillOpen(" + string openCount + ")"
            | TerminalFlowTerminalSemanticCreditRejectedMultiplicity openCount ->
                "RejectedTerminalReservationMultiplicity(" + string openCount + ")"
            | TerminalFlowTerminalSemanticCreditRejectedLedgerConflict -> "RejectedTerminalReservationLedgerConflict"

        let private terminalFlowTerminalSemanticCreditResolutionIsResolved = function
            | TerminalFlowTerminalSemanticCreditResolvedExact
            | TerminalFlowTerminalSemanticCreditResolvedFailClosedUnique _
            | TerminalFlowTerminalSemanticCreditAlreadyReturned _ -> true
            | TerminalFlowTerminalSemanticCreditRejectedSuccessIdentityMissing
            | TerminalFlowTerminalSemanticCreditRejectedOperationalCreditOpen _
            | TerminalFlowTerminalSemanticCreditRejectedMultiplicity _
            | TerminalFlowTerminalSemanticCreditRejectedLedgerConflict -> false

        type TerminalFlowPhysicalExitFailsafeWithholdReasonId =
            | TerminalFlowFailsafeSemanticCreditOutstanding
            | TerminalFlowFailsafeClosureCapabilityUnavailableAfterCreditReturn

        let private terminalFlowPhysicalExitFailsafeWithholdReasonText = function
            | TerminalFlowFailsafeSemanticCreditOutstanding -> "SemanticCreditOutstanding"
            | TerminalFlowFailsafeClosureCapabilityUnavailableAfterCreditReturn -> "ClosureCapabilityUnavailableAfterCreditReturn"

        let private terminalFlowPhysicalExitFailsafeWithholdNextText = function
            | TerminalFlowFailsafeSemanticCreditOutstanding -> "retry_indexed_closure_after_credit_or_subsystem_drain"
            | TerminalFlowFailsafeClosureCapabilityUnavailableAfterCreditReturn -> "retry_indexed_closure_after_closure_capability_reconciliation"

        let private terminalFlowReducerTotalOrderChainEmit (attempt:TerminalFlowIndexedClosureAttempt) (chain:TerminalFlowReducerTotalOrderChain) =
            let source = terminalFlowIndexedClosureAttemptText attempt
            if not (terminalFlowReducerProcessExitAllowed chain) then
                invalidOp ("terminal total order rejected by constitutional verifier: " + terminalFlowReducerTotalOrderChainText chain)

            let physicalExitIntentRef =
                terminalFlowMintedRefOf
                    "physical_exit_intent_receipt"
                    (terminalFlowReducerTotalOrderChainText chain)
            let newDurableEdges =
                terminalFlowReducerTotalOrderEdgeEmissionKeys.TryAdd(chain.physicalExit.receiptRef, 0uy)

            if newDurableEdges then
                let constitutionLine =
                    FastRuntimeFormat.format "{\"kind\":\"terminal_constitution_total_order_selected\",\"constitution_ref\":%u,\"ratification_ref\":%u,\"commit_receipt_ref\":%u,\"run_end_receipt_ref\":%u,\"physical_exit_receipt_ref\":%u,\"exit_code\":%d,\"source_du\":%s,\"authority\":\"single_reducer_terminal_constitution\"}" [| box chain.commit.constitutionRef; box chain.ratificationRef; box chain.commit.receiptRef; box chain.runEnd.receiptRef; box chain.physicalExit.receiptRef; box chain.exitCode; box (DiagJson.esc source) |]
                let commitLine =
                    FastRuntimeFormat.format "{\"kind\":\"terminal_commit_receipt\",\"receipt_ref\":%u,\"predecessor_receipt_ref\":%u,\"constitution_ref\":%u,\"ratification_ref\":%u,\"actor_ref\":%u,\"terminal_ref\":%u,\"fill_ref\":%u,\"total_order_index\":%d,\"reducer_sequence\":%d,\"authority\":\"single_reducer_total_order\",\"source_du\":%s}" [| box chain.commit.receiptRef; box chain.commit.predecessorReceiptRef; box chain.commit.constitutionRef; box chain.ratificationRef; box chain.commit.actorRef; box chain.commit.terminalRef; box chain.commit.fillRef; box chain.commit.totalOrderIndex; box chain.commit.reducerSequence; box (DiagJson.esc source) |]
                let doneLine =
                    FastRuntimeFormat.format "{\"kind\":\"terminal_done_transition\",\"receipt_ref\":%u,\"predecessor_receipt_ref\":%u,\"constitution_ref\":%u,\"ratification_ref\":%u,\"total_order_index\":%d,\"reducer_sequence\":%d,\"authority\":\"single_reducer_total_order\",\"source_du\":%s}" [| box chain.doneReceipt.receiptRef; box chain.doneReceipt.predecessorReceiptRef; box chain.doneReceipt.constitutionRef; box chain.ratificationRef; box chain.doneReceipt.totalOrderIndex; box chain.doneReceipt.reducerSequence; box (DiagJson.esc source) |]
                let runEndIntentLine =
                    FastRuntimeFormat.format "{\"kind\":\"run_end_intent_receipt\",\"receipt_ref\":%u,\"predecessor_receipt_ref\":%u,\"constitution_ref\":%u,\"ratification_ref\":%u,\"run_end_emitted\":false,\"total_order_index\":%d,\"reducer_sequence\":%d,\"authority\":\"preproof_run_end_intent\",\"source_du\":%s}" [| box chain.runEnd.receiptRef; box chain.runEnd.predecessorReceiptRef; box chain.runEnd.constitutionRef; box chain.ratificationRef; box chain.runEnd.totalOrderIndex; box chain.runEnd.reducerSequence; box (DiagJson.esc source) |]
                let physicalExitIntentLine =
                    FastRuntimeFormat.format "{\"kind\":\"physical_exit_intent_receipt\",\"receipt_ref\":%u,\"physical_exit_receipt_ref\":%u,\"predecessor_receipt_ref\":%u,\"constitution_ref\":%u,\"ratification_ref\":%u,\"exit_code\":%d,\"process_exit_allowed\":false,\"requested_process_exit_allowed\":%b,\"failure_ref\":%u,\"total_order_index\":%d,\"reducer_sequence\":%d,\"authority\":\"preproof_physical_exit_intent\",\"source_du\":%s}" [| box physicalExitIntentRef; box chain.physicalExit.receiptRef; box chain.physicalExit.predecessorReceiptRef; box chain.physicalExit.constitutionRef; box chain.ratificationRef; box chain.exitCode; box (terminalFlowReducerProcessExitAllowed chain); box (chain.failureRef |> Option.defaultValue 0u); box chain.physicalExit.totalOrderIndex; box chain.physicalExit.reducerSequence; box (DiagJson.esc source) |]
                let durableEdgeLines =
                    [ constitutionLine; commitLine; doneLine; runEndIntentLine; physicalExitIntentLine ]
                try
                    durableEdgeLines |> List.iter DiagJson.emitTerminalJsonDurable
                with _ ->
                    let mutable removedEdgeKey = 0uy
                    terminalFlowReducerTotalOrderEdgeEmissionKeys.TryRemove(chain.physicalExit.receiptRef, &removedEdgeKey) |> ignore
                    reraise()

            match chain.failureRef, TerminalFlowOperationalGraphSnapshotBridge.read () with
            | Some failureRef, Some(graphRevision, 0L, 0L, graphRef) ->
                let failureDigest =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "terminal-fail-closed-replay-credit-cause"
                        (FastRuntimeFormat.format
                            "%u|physical_exit=%u"
                            [| box failureRef
                               box chain.physicalExit.receiptRef |])
                match CompilerKernelV2.SemanticWorkLedgerAuthority.reconcileFailClosedReplayCredits failureDigest with
                | Error _ ->
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format
                            "{\"kind\":\"terminal_fail_closed_replay_credit_reconciliation_rejected\",\"physical_exit_receipt_ref\":%u,\"graph_revision\":%d,\"graph_ref\":%s,\"authority\":\"typed_semantic_ledger_conflict_fail_closed\",\"next\":\"preserve_credit_blocker\"}"
                            [| box chain.physicalExit.receiptRef
                               box graphRevision
                               box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text graphRef)) |])
                | Ok receipt ->
                    let cancelledCount =
                        CompilerKernelV2.SemanticWorkFailClosedReplayCreditReconciliationOps.cancelledCount receipt
                    if cancelledCount > 0 then
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format
                                "{\"kind\":\"terminal_fail_closed_replay_credit_reconciled\",\"physical_exit_receipt_ref\":%u,\"cancelled_replay_count\":%d,\"remaining_operational_open_count\":%d,\"reconciliation_ref\":%s,\"graph_revision\":%d,\"graph_ref\":%s,\"terminal_protocol_credit_untouched\":true,\"authority\":\"typed_fail_closed_cancels_only_orphan_replay_after_operational_graph_closure\",\"next\":\"retry_indexed_closure_with_recomputed_semantic_credit\"}"
                                [| box chain.physicalExit.receiptRef
                                   box cancelledCount
                                   box (CompilerKernelV2.SemanticWorkFailClosedReplayCreditReconciliationOps.remainingOperationalOpenCount receipt)
                                   box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text (CompilerKernelV2.SemanticWorkFailClosedReplayCreditReconciliationOps.receiptDigest receipt)))
                                   box graphRevision
                                   box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text graphRef)) |])
            | _ -> ()

            let terminalSemanticWorkUnit =
                if chain.commit.terminalRef <> 0u && chain.commit.fillRef <> 0u then
                    Some (terminalFlowTerminalSemanticWorkUnitOfRefs chain.commit.terminalRef chain.commit.fillRef)
                else
                    None
            let semanticAdmitted, semanticReceipts =
                CompilerKernelV2.SemanticWorkLedgerAuthority.counts ()
            let operationalSemanticCreditDecisionBeforeClosure =
                CompilerKernelV2.SemanticWorkLedgerAuthority.creditDecisionForScope
                    CompilerKernelV2.SemanticWorkOperational
            let semanticOpenCount =
                operationalSemanticCreditDecisionBeforeClosure
                |> CompilerKernelV2.SemanticWorkCreditDecision.openUnitCount
            let terminalProtocolCreditDecisionBeforeClosure =
                CompilerKernelV2.SemanticWorkLedgerAuthority.creditDecisionForScope
                    CompilerKernelV2.SemanticWorkTerminalProtocol
            let terminalProtocolReservationCountBeforeClosure =
                terminalProtocolCreditDecisionBeforeClosure
                |> CompilerKernelV2.SemanticWorkCreditDecision.openUnitCount
            let terminalProtocolReservationWitnessesBeforeClosureDu =
                terminalProtocolCreditDecisionBeforeClosure
                |> CompilerKernelV2.SemanticWorkCreditDecision.openWorkUnitTexts
                |> function
                    | [] -> "none"
                    | witnesses -> String.concat "|" witnesses
            let disposition =
                match chain.failureRef with
                | Some failureRef -> CompilerConsoleHud88.TerminalClosureFailedClosed failureRef
                | None -> CompilerConsoleHud88.TerminalClosureSuccessful
            let closureSeed : CompilerConsoleHud88.TerminalClosureSeed = {
                generation = CacheGeneration.current ()
                disposition = disposition
                semanticOpenCount = semanticOpenCount
                constitutionRef = chain.commit.constitutionRef
                commitRef = chain.commit.receiptRef
                doneRef = chain.doneReceipt.receiptRef
                runEndIntentRef = chain.runEnd.receiptRef
                physicalExitIntentRef = physicalExitIntentRef
                durableWriterRef = physicalExitIntentRef
                exitCode = chain.exitCode
            }

            match CompilerConsoleHud88.tryBuildTerminalClosureCapability closureSeed with
            | None ->
                terminalFlowReducerPendingClosureChains.[chain.physicalExit.receiptRef] <-
                    (terminalFlowIndexedClosureTriggerOfAttempt attempt, chain)
                let failsafeWithholdReason =
                    if semanticOpenCount > 0 then TerminalFlowFailsafeSemanticCreditOutstanding
                    else TerminalFlowFailsafeClosureCapabilityUnavailableAfterCreditReturn
                let failsafeWithholdReasonText = terminalFlowPhysicalExitFailsafeWithholdReasonText failsafeWithholdReason
                let failsafeWithholdNext = terminalFlowPhysicalExitFailsafeWithholdNextText failsafeWithholdReason
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_total_order_edges_durable_but_closure_unproven\",\"physical_exit_receipt_ref\":%u,\"semantic_open_count\":%d,\"operational_semantic_open_count\":%d,\"terminal_protocol_reservation_count\":%d,\"terminal_protocol_reservation_du\":%s,\"semantic_admitted\":%d,\"semantic_receipts\":%d,\"source_du\":%s,\"preproof_edge_rows_durable\":true,\"edge_rows_durable\":false,\"aggregate_committed\":false,\"next\":%s,\"authority\":\"unified_semantic_work_ledger_plus_indexed_terminal_closure_gate\"}" [| box chain.physicalExit.receiptRef; box semanticOpenCount; box semanticOpenCount; box terminalProtocolReservationCountBeforeClosure; box (DiagJson.esc terminalProtocolReservationWitnessesBeforeClosureDu); box semanticAdmitted; box semanticReceipts; box (DiagJson.esc source); box (DiagJson.esc failsafeWithholdNext) |])
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"physical_exit_failsafe_withheld\",\"physical_exit_receipt_ref\":%u,\"semantic_open_count\":%d,\"operational_semantic_open_count\":%d,\"terminal_protocol_reservation_count\":%d,\"terminal_protocol_reservation_du\":%s,\"failsafe_armed\":false,\"reason_du\":%s,\"policy\":\"semantic_success_never_bypasses_credit_but_stable_failed_closed_residual_may_arm_host_deadman\",\"next\":%s}" [| box chain.physicalExit.receiptRef; box semanticOpenCount; box semanticOpenCount; box terminalProtocolReservationCountBeforeClosure; box (DiagJson.esc terminalProtocolReservationWitnessesBeforeClosureDu); box (DiagJson.esc failsafeWithholdReasonText); box (DiagJson.esc failsafeWithholdNext) |])
            | Some candidateCapability ->
                let candidateClosureProofRef =
                    CompilerConsoleHud88.terminalFinalRowCapabilityRefText candidateCapability
                let terminalClosureReceiptRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "terminal-indexed-closure"
                        (candidateClosureProofRef + "|" + string chain.physicalExit.receiptRef)
                let terminalSemanticCreditResolution =
                    match terminalSemanticWorkUnit with
                    | Some workUnit ->
                        if terminalFlowTerminalSemanticWorkRetireUnit workUnit terminalClosureReceiptRef then
                            TerminalFlowTerminalSemanticCreditResolvedExact
                        else
                            TerminalFlowTerminalSemanticCreditRejectedLedgerConflict
                    | None ->
                        match chain.failureRef with
                        | Some _ ->
                            match CompilerKernelV2.SemanticWorkLedgerAuthority.reconcileFailClosedTerminalReservation terminalClosureReceiptRef with
                            | Ok reconciliation ->
                                let reconciliationRef =
                                    CompilerKernelV2.SemanticWorkFailClosedTerminalReservationReconciliationOps.receiptDigest reconciliation
                                if CompilerKernelV2.SemanticWorkFailClosedTerminalReservationReconciliationOps.retiredCount reconciliation = 0 then
                                    TerminalFlowTerminalSemanticCreditAlreadyReturned reconciliationRef
                                else
                                    TerminalFlowTerminalSemanticCreditResolvedFailClosedUnique reconciliationRef
                            | Error (CompilerKernelV2.SemanticWorkTerminalReservationOperationalCreditStillOpen(openCount, _)) ->
                                TerminalFlowTerminalSemanticCreditRejectedOperationalCreditOpen openCount
                            | Error (CompilerKernelV2.SemanticWorkTerminalReservationMultiplicityViolation(openCount, _)) ->
                                TerminalFlowTerminalSemanticCreditRejectedMultiplicity openCount
                            | Error (CompilerKernelV2.SemanticWorkTerminalReservationLedgerConflict _) ->
                                TerminalFlowTerminalSemanticCreditRejectedLedgerConflict
                        | None ->
                            TerminalFlowTerminalSemanticCreditRejectedSuccessIdentityMissing
                let terminalSemanticCreditResolved =
                    terminalFlowTerminalSemanticCreditResolutionIsResolved terminalSemanticCreditResolution
                let semanticAdmittedAfterTerminalCredit, semanticReceiptsAfterTerminalCredit =
                    CompilerKernelV2.SemanticWorkLedgerAuthority.counts ()
                let operationalSemanticCreditDecisionAfterTerminalCredit =
                    CompilerKernelV2.SemanticWorkLedgerAuthority.creditDecisionForScope
                        CompilerKernelV2.SemanticWorkOperational
                let terminalProtocolCreditDecisionAfterTerminalCredit =
                    CompilerKernelV2.SemanticWorkLedgerAuthority.creditDecisionForScope
                        CompilerKernelV2.SemanticWorkTerminalProtocol
                let semanticCreditDecisionAfterTerminalCredit =
                    CompilerKernelV2.SemanticWorkLedgerAuthority.creditDecision ()
                let operationalSemanticOpenAfterTerminalCredit =
                    CompilerKernelV2.SemanticWorkCreditDecision.openUnitCount operationalSemanticCreditDecisionAfterTerminalCredit
                let terminalProtocolReservationCountAfterTerminalCredit =
                    CompilerKernelV2.SemanticWorkCreditDecision.openUnitCount terminalProtocolCreditDecisionAfterTerminalCredit
                let terminalProtocolReservationWitnessesAfterTerminalCreditDu =
                    terminalProtocolCreditDecisionAfterTerminalCredit
                    |> CompilerKernelV2.SemanticWorkCreditDecision.openWorkUnitTexts
                    |> function
                        | [] -> "none"
                        | witnesses -> String.concat "|" witnesses
                let semanticOpenAfterTerminalCredit =
                    CompilerKernelV2.SemanticWorkCreditDecision.openUnitCount semanticCreditDecisionAfterTerminalCredit
                let semanticCreditReturnedAfterTerminalCredit =
                    CompilerKernelV2.SemanticWorkCreditDecision.isReturned semanticCreditDecisionAfterTerminalCredit
                DiagJson.emit (
                    FastRuntimeFormat.format
                        "{\"kind\":\"terminal_protocol_reservation_resolution\",\"physical_exit_receipt_ref\":%u,\"terminal_closure_proof_ref\":%s,\"resolution_du\":%s,\"fail_closed\":%b,\"exact_terminal_identity_present\":%b,\"operational_semantic_open_count\":%d,\"terminal_protocol_reservation_count_before\":%d,\"terminal_protocol_reservation_count_after\":%d,\"terminal_protocol_reservation_du_after\":%s,\"authority\":\"typed_exact_identity_or_unique_fail_closed_terminal_reservation\",\"next\":\"evaluate_total_semantic_credit_after_terminal_reservation\"}"
                        [| box chain.physicalExit.receiptRef
                           box (DiagJson.esc candidateClosureProofRef)
                           box (DiagJson.esc (terminalFlowTerminalSemanticCreditResolutionText terminalSemanticCreditResolution))
                           box (Option.isSome chain.failureRef)
                           box (Option.isSome terminalSemanticWorkUnit)
                           box operationalSemanticOpenAfterTerminalCredit
                           box terminalProtocolReservationCountBeforeClosure
                           box terminalProtocolReservationCountAfterTerminalCredit
                           box (DiagJson.esc terminalProtocolReservationWitnessesAfterTerminalCreditDu) |])
                let creditRefusal =
                    if not terminalSemanticCreditResolved then
                        Some TerminalFlowTerminalSemanticCreditRetireRefused
                    elif not semanticCreditReturnedAfterTerminalCredit then
                        Some TerminalFlowSemanticCreditOutstandingAfterTerminalRetire
                    else None
                let allowDurableClosure = Option.isNone creditRefusal
                match creditRefusal with
                | Some refusal ->
                    terminalFlowReducerPendingClosureChains.[chain.physicalExit.receiptRef] <-
                        (terminalFlowIndexedClosureTriggerOfAttempt attempt, chain)
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_indexed_closure_credit_refused\",\"physical_exit_receipt_ref\":%u,\"terminal_closure_proof_ref\":%s,\"reason_du\":%s,\"terminal_credit_resolution_du\":%s,\"semantic_admitted_count\":%d,\"semantic_receipt_count\":%d,\"semantic_open_count\":%d,\"operational_semantic_open_count\":%d,\"terminal_protocol_reservation_count\":%d,\"terminal_protocol_reservation_du\":%s,\"run_end_emitted\":false,\"physical_exit_emitted\":false,\"next\":\"retry_indexed_closure_after_credit_or_subsystem_drain\",\"authority\":\"typed_pending_indexed_closure_credit_refusal\"}" [| box chain.physicalExit.receiptRef; box (DiagJson.esc candidateClosureProofRef); box (DiagJson.esc (terminalFlowIndexedClosureCreditRefusalText refusal)); box (DiagJson.esc (terminalFlowTerminalSemanticCreditResolutionText terminalSemanticCreditResolution)); box semanticAdmittedAfterTerminalCredit; box semanticReceiptsAfterTerminalCredit; box semanticOpenAfterTerminalCredit; box operationalSemanticOpenAfterTerminalCredit; box terminalProtocolReservationCountAfterTerminalCredit; box (DiagJson.esc terminalProtocolReservationWitnessesAfterTerminalCreditDu) |])
                | None -> ()
                let semanticCreditDigestAfterTerminalCredit =
                    CompilerKernelV2.SemanticWorkCreditDecision.digest semanticCreditDecisionAfterTerminalCredit
                if allowDurableClosure then
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_outcome_winner_semantic_credit_resolved\",\"physical_exit_receipt_ref\":%u,\"terminal_closure_proof_ref\":%s,\"resolved\":true,\"terminal_credit_resolution_du\":%s,\"semantic_admitted_count\":%d,\"semantic_receipt_count\":%d,\"semantic_open_count\":%d,\"operational_semantic_open_count\":%d,\"terminal_protocol_reservation_count\":%d,\"semantic_credit_digest\":%s,\"authority\":\"indexed_closure_capability_precedes_durable_run_end_and_physical_exit\",\"next\":\"emit_durable_run_end_and_physical_exit_receipt\"}" [| box chain.physicalExit.receiptRef; box (DiagJson.esc candidateClosureProofRef); box (DiagJson.esc (terminalFlowTerminalSemanticCreditResolutionText terminalSemanticCreditResolution)); box semanticAdmittedAfterTerminalCredit; box semanticReceiptsAfterTerminalCredit; box semanticOpenAfterTerminalCredit; box operationalSemanticOpenAfterTerminalCredit; box terminalProtocolReservationCountAfterTerminalCredit; box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text semanticCreditDigestAfterTerminalCredit)) |])
                let mutable newDurableClosure = false
                if allowDurableClosure && terminalFlowReducerTotalOrderClosureEmissionKeys.TryAdd(chain.physicalExit.receiptRef, 0uy) then
                    try
                        DiagJson.emitRunEndJsonDurable chain.exitCode (
                            FastRuntimeFormat.format "{\"kind\":\"run_end\",\"receipt_ref\":%u,\"predecessor_receipt_ref\":%u,\"constitution_ref\":%u,\"ratification_ref\":%u,\"terminal_closure_proof_ref\":%s,\"run_end_emitted\":true,\"total_order_index\":%d,\"reducer_sequence\":%d,\"authority\":\"indexed_terminal_closure_run_end\",\"source_du\":%s}" [| box chain.runEnd.receiptRef; box chain.runEnd.predecessorReceiptRef; box chain.runEnd.constitutionRef; box chain.ratificationRef; box (DiagJson.esc candidateClosureProofRef); box chain.runEnd.totalOrderIndex; box chain.runEnd.reducerSequence; box (DiagJson.esc source) |])
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"physical_exit_receipt\",\"receipt_ref\":%u,\"predecessor_receipt_ref\":%u,\"constitution_ref\":%u,\"ratification_ref\":%u,\"terminal_closure_proof_ref\":%s,\"exit_code\":%d,\"process_exit_allowed\":true,\"process_exit_authority_du\":\"ratified_total_order_chain_pending_exit_witness_reauthorization\",\"physical_exit_boundary_committed\":false,\"physical_exit_boundary_commit_state_du\":\"PendingPhysicalBoundary\",\"failure_ref\":%u,\"total_order_index\":%d,\"reducer_sequence\":%d,\"authority\":\"indexed_terminal_closure_physical_exit\",\"source_du\":%s}" [| box chain.physicalExit.receiptRef; box chain.physicalExit.predecessorReceiptRef; box chain.physicalExit.constitutionRef; box chain.ratificationRef; box (DiagJson.esc candidateClosureProofRef); box chain.exitCode; box (chain.failureRef |> Option.defaultValue 0u); box chain.physicalExit.totalOrderIndex; box chain.physicalExit.reducerSequence; box (DiagJson.esc source) |])
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_total_order_chain_committed\",\"constitution_ref\":%u,\"ratification_ref\":%u,\"commit_receipt_ref\":%u,\"done_receipt_ref\":%u,\"run_end_receipt_ref\":%u,\"physical_exit_receipt_ref\":%u,\"terminal_closure_proof_ref\":%s,\"exit_code\":%d,\"failure_ref\":%u,\"reducer_sequence\":%d,\"total_order_row_index_expected\":4,\"total_order_row_index_emitted\":4,\"edge_rows_durable\":true,\"source_du\":%s,\"authority\":\"indexed_terminal_closure_exact_once\"}" [| box chain.commit.constitutionRef; box chain.ratificationRef; box chain.commit.receiptRef; box chain.doneReceipt.receiptRef; box chain.runEnd.receiptRef; box chain.physicalExit.receiptRef; box (DiagJson.esc candidateClosureProofRef); box chain.exitCode; box (chain.failureRef |> Option.defaultValue 0u); box chain.physicalExit.reducerSequence; box (DiagJson.esc source) |])
                        newDurableClosure <- true
                    with _ ->
                        let mutable removedClosureKey = 0uy
                        terminalFlowReducerTotalOrderClosureEmissionKeys.TryRemove(chain.physicalExit.receiptRef, &removedClosureKey) |> ignore
                        reraise()
                let capability =
                    if allowDurableClosure then CompilerConsoleHud88.publishTerminalClosureCapability candidateCapability
                    else candidateCapability
                let closureProofRef =
                    CompilerConsoleHud88.terminalFinalRowCapabilityRefText capability
                if allowDurableClosure then
                    terminalFlowIndexedClosureDurableChains.[chain.physicalExit.receiptRef] <- (chain, closureProofRef)
                let mutable removedPending = Unchecked.defaultof<TerminalFlowIndexedClosureTrigger * TerminalFlowReducerTotalOrderChain>
                if allowDurableClosure then
                    terminalFlowReducerPendingClosureChains.TryRemove(chain.physicalExit.receiptRef, &removedPending) |> ignore
                if newDurableClosure then
                    let finalActorPhase = if chain.exitCode = 0 then DiagJson.PushActorConsumed else DiagJson.PushActorFailedClosed
                    DiagJson.terminalSchedulerPushActorProjectReducer
                        finalActorPhase
                        ""
                        chain.runEnd.receiptRef
                        chain.physicalExit.receiptRef
                        Environment.TickCount64
                        chain.physicalExit.receiptRef
                    terminalFlowEmitAdvancedConsoleProjection {
                        lane = TerminalFlowConsoleLaneTotalOrder
                        sequence = chain.physicalExit.reducerSequence
                        progressBp = if chain.exitCode = 0 then 10000 else 9999
                        etaMs = if chain.exitCode = 0 then Some 0L else None
                        title = if chain.exitCode = 0 then "terminal indexed closure sealed" else "terminal indexed fail-close sealed"
                        detail = terminalFlowReducerTotalOrderChainText chain + "|closure_proof_ref=" + closureProofRef
                        authorityRef = chain.physicalExit.receiptRef
                    }
                    terminalFlowReplayIndexedClosureExit chain closureProofRef |> ignore
                elif allowDurableClosure then
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_total_order_chain_reused\",\"physical_exit_receipt_ref\":%u,\"run_end_receipt_ref\":%u,\"terminal_closure_proof_ref\":%s,\"source_du\":%s,\"new_durable_emission\":false,\"authority\":\"indexed_terminal_closure_exact_once\"}" [| box chain.physicalExit.receiptRef; box chain.runEnd.receiptRef; box (DiagJson.esc closureProofRef); box (DiagJson.esc source) |])

        let terminalFlowRetryPendingIndexedClosure () =
            let candidates =
                lock terminalFlowReducerPendingClosureRetryGate (fun () ->
                    if terminalFlowReducerPendingClosureRetryRunning then None
                    else
                        terminalFlowReducerPendingClosureRetryRunning <- true
                        Some (terminalFlowReducerPendingClosureChains.ToArray()))
            match candidates with
            | None -> ()
            | Some pending ->
                try
                    pending
                    |> Array.iter (fun entry ->
                        let trigger, chain = entry.Value
                        terminalFlowReducerTotalOrderChainEmit (TerminalFlowIndexedClosureRetry trigger) chain)
                finally
                    lock terminalFlowReducerPendingClosureRetryGate (fun () ->
                        terminalFlowReducerPendingClosureRetryRunning <- false)

        type TerminalFlowIndexedClosureRetryWakeId =
            | TerminalFlowIndexedClosureReducerTurnOperationalCreditClosed

        let private terminalFlowIndexedClosureRetryWakeText = function
            | TerminalFlowIndexedClosureReducerTurnOperationalCreditClosed -> "ReducerTurnOperationalCreditClosed"

        let private terminalFlowRetryPendingIndexedClosureForWake (wake:TerminalFlowIndexedClosureRetryWakeId) (reducerRevision:int64) : bool =
            let pendingCount = terminalFlowReducerPendingClosureChains.Count
            if pendingCount <= 0 then false
            else
                let operationalCreditDecision =
                    CompilerKernelV2.SemanticWorkLedgerAuthority.creditDecisionForScope
                        CompilerKernelV2.SemanticWorkOperational
                let operationalOpenCount =
                    CompilerKernelV2.SemanticWorkCreditDecision.openUnitCount operationalCreditDecision
                if operationalOpenCount <> 0 then false
                else
                    let wakeText = terminalFlowIndexedClosureRetryWakeText wake
                    let wakeRef =
                        terminalFlowMintedRefOf
                            "terminal_indexed_closure_retry_wake"
                            (wakeText + "|revision=" + string reducerRevision + "|pending=" + string pendingCount)
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_indexed_closure_retry_wake\",\"wake_ref\":%u,\"wake_du\":%s,\"pending_closure_count\":%d,\"operational_semantic_open_count\":0,\"reducer_revision\":%d,\"authority\":\"typed_closed_operational_credit_reducer_turn\",\"next\":\"retry_pending_indexed_closure_exact_once\"}" [| box wakeRef; box (DiagJson.esc wakeText); box pendingCount; box reducerRevision |])
                    terminalFlowRetryPendingIndexedClosure ()
                    true

        let private terminalFlowRetryPendingIndexedClosureForWakeJob (wake:TerminalFlowIndexedClosureRetryWakeId) (reducerRevision:int64) : Hopac.Job<bool> =
            job {
                let retried, durableLines =
                    CompilerConsoleHud88.withDurableJsonHopacJobContext (fun () ->
                        terminalFlowRetryPendingIndexedClosureForWake wake reducerRevision)
                do! CompilerConsoleHud88.submitProgressJsonLinesTerminalDurableJob durableLines
                return retried
            }

        let terminalFlowResetPendingIndexedClosure () =
            lock terminalFlowReducerPendingClosureRetryGate (fun () ->
                terminalFlowReducerPendingClosureChains.Clear())

        do
            CompilerConsoleHud88.installTerminalClosureReset terminalFlowResetPendingIndexedClosure
            CompilerConsoleHud88.installTerminalClosureRetry terminalFlowRetryPendingIndexedClosure

        type TerminalFlowFinalOutcomeHandoffId =
            | TerminalFlowFinalOutcomeHandoffAwaiting
            | TerminalFlowFinalOutcomeHandoffBlocked of generation:TerminalFlowQapGenerationId<TerminalFlowQapGenerationRefKind> option * terminalRef:uint32 * proofRef:uint32 option
            | TerminalFlowFinalOutcomeHandoffDispatchReady of generation:TerminalFlowQapGenerationId<TerminalFlowQapGenerationRefKind> option * terminalRef:uint32 * fillRef:uint32 * proofRef:uint32 option

        [<NoEquality; NoComparison>]
        type private TerminalFlowFinalOutcomeHandoffProjection = {
            text : string
            terminalRef : uint32
            fillRef : uint32
        }

        let private terminalFlowFinalOutcomeHandoffProjection = function
            | TerminalFlowFinalOutcomeHandoffAwaiting ->
                { text = "Awaiting"; terminalRef = 0u; fillRef = 0u }
            | TerminalFlowFinalOutcomeHandoffBlocked(generation, terminalRef, proofRef) ->
                { text = FastRuntimeFormat.format "Blocked(generation=%d|terminal_ref=%u|proof_ref=%u)" [| box (generation |> Option.map terminalFlowQapGenerationValue |> Option.defaultValue 0UL); box terminalRef; box (proofRef |> Option.defaultValue 0u) |]
                  terminalRef = terminalRef
                  fillRef = 0u }
            | TerminalFlowFinalOutcomeHandoffDispatchReady(generation, terminalRef, fillRef, proofRef) ->
                { text = FastRuntimeFormat.format "DispatchReady(generation=%d|terminal_ref=%u|fill_ref=%u|proof_ref=%u)" [| box (generation |> Option.map terminalFlowQapGenerationValue |> Option.defaultValue 0UL); box terminalRef; box fillRef; box (proofRef |> Option.defaultValue 0u) |]
                  terminalRef = terminalRef
                  fillRef = fillRef }

        let private terminalFlowFinalOutcomeHandoffText handoff =
            (terminalFlowFinalOutcomeHandoffProjection handoff).text

        let private terminalFlowFinalOutcomeHandoffFor = function
            | TerminalFlowReducerOutcomeAwaitingQap
            | TerminalFlowReducerOutcomeProvisional _ -> TerminalFlowFinalOutcomeHandoffAwaiting
            | TerminalFlowReducerOutcomeFinalDrained outcome ->
                if outcome.dispatchConsumable then
                    TerminalFlowFinalOutcomeHandoffDispatchReady(outcome.qapGeneration, outcome.terminalRef, outcome.fillRef, outcome.proofRef)
                else
                    TerminalFlowFinalOutcomeHandoffBlocked(outcome.qapGeneration, outcome.terminalRef, outcome.proofRef)
            | TerminalFlowReducerOutcomeFinalDeadlocked outcome ->
                if outcome.dispatchConsumable then
                    TerminalFlowFinalOutcomeHandoffDispatchReady(outcome.qapGeneration, outcome.terminalRef, outcome.fillRef, outcome.proofRef)
                else
                    TerminalFlowFinalOutcomeHandoffBlocked(outcome.qapGeneration, outcome.terminalRef, outcome.proofRef)

        type TerminalFlowReducerAuthorityTransitionReceipt = private {
            receiptRef : uint32
            qapGeneration : TerminalFlowQapGenerationId<TerminalFlowQapGenerationRefKind> option
            qapStageBefore : TerminalFlowQapGenerationStageId option
            qapStageAfter : TerminalFlowQapGenerationStageId option
            outcomeBeforeRef : uint32
            outcomeAfterRef : uint32
            actorVersionBefore : int64
            actorVersionAfter : int64
            stageTokenRef : uint32 option
            constitutionRef : uint32
            ratificationRef : uint32
            reducerSequence : int64
        }

        type TerminalFlowReducerQapOutcomeActorAuthority = private {
            qapGeneration : TerminalFlowQapGenerationAuthority option
            outcome : TerminalFlowReducerOutcomeAuthorityId
            handoff : TerminalFlowFinalOutcomeHandoffId
            actor : TerminalFlowReducerActorAuthorityId
            version : int64
            lastTransition : TerminalFlowReducerAuthorityTransitionReceipt option
        }

        let private terminalFlowReducerQapOutcomeActorInitial =
            { qapGeneration = None
              outcome = TerminalFlowReducerOutcomeAwaitingQap
              handoff = TerminalFlowFinalOutcomeHandoffAwaiting
              actor =
                TerminalFlowReducerActorVacant (
                    terminalFlowPossessionOf {
                        clock = {
                            version = 0L
                            changedAtMs = Environment.TickCount64
                            lastTransitionRef = None
                        }
                    })
              version = 0L
              lastTransition = None }

        let private terminalFlowReducerActorCoordinates = function
            | TerminalFlowReducerActorVacant _ -> 0u, 0u, 0u
            | TerminalFlowReducerActorArmed wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                terminalFlowAuthorityRefValue actor.lineage.actorRef,
                terminalFlowAuthorityRefValue actor.lineage.terminalRef,
                terminalFlowAuthorityRefValue actor.lineage.fillRef
            | TerminalFlowReducerActorFilled wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                terminalFlowAuthorityRefValue actor.armed.lineage.actorRef,
                terminalFlowAuthorityRefValue actor.armed.lineage.terminalRef,
                terminalFlowAuthorityRefValue actor.armed.lineage.fillRef
            | TerminalFlowReducerActorSealed wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                terminalFlowAuthorityRefValue actor.filled.armed.lineage.actorRef,
                terminalFlowAuthorityRefValue actor.filled.armed.lineage.terminalRef,
                terminalFlowAuthorityRefValue actor.filled.armed.lineage.fillRef
            | TerminalFlowReducerActorFailedClosed wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                match actor.context with
                | TerminalFlowFailureBeforePossession _ -> 0u, 0u, 0u
                | TerminalFlowFailureAfterIssue(armed, _, _) ->
                    terminalFlowAuthorityRefValue armed.lineage.actorRef,
                    terminalFlowAuthorityRefValue armed.lineage.terminalRef,
                    terminalFlowAuthorityRefValue armed.lineage.fillRef
                | TerminalFlowFailureAfterFill(filled, _, _) ->
                    terminalFlowAuthorityRefValue filled.armed.lineage.actorRef,
                    terminalFlowAuthorityRefValue filled.armed.lineage.terminalRef,
                    terminalFlowAuthorityRefValue filled.armed.lineage.fillRef

        [<StructuralEquality; NoComparison>]
        type private TerminalFlowHostShutdownCoordinateSourceId =
            | TerminalFlowHostShutdownCoordinatesFromActor
            | TerminalFlowHostShutdownCoordinatesFromPendingTerminal
            | TerminalFlowHostShutdownCoordinatesUnavailable

        let private terminalFlowHostShutdownCoordinateSourceText = function
            | TerminalFlowHostShutdownCoordinatesFromActor -> "actor"
            | TerminalFlowHostShutdownCoordinatesFromPendingTerminal -> "pending_terminal"
            | TerminalFlowHostShutdownCoordinatesUnavailable -> "unavailable"

        type private TerminalFlowHostShutdownCoordinates = {
            actorRef : uint32
            terminalRef : uint32
            fillRef : uint32
            source : TerminalFlowHostShutdownCoordinateSourceId
        }

        let private terminalFlowReducerHostShutdownCoordinates actor pendingTerminal =
            let actorRef, actorTerminalRef, actorFillRef = terminalFlowReducerActorCoordinates actor
            if actorTerminalRef <> 0u && actorFillRef <> 0u then
                { actorRef = actorRef
                  terminalRef = actorTerminalRef
                  fillRef = actorFillRef
                  source = TerminalFlowHostShutdownCoordinatesFromActor }
            else
                match pendingTerminal with
                | TerminalFlowPendingSlotCandidate pending ->
                    let terminalRef = terminalFlowIdentityRefDigest pending.terminalReceiptRef
                    let fillRef = terminalFlowIdentityRefDigest pending.fillRef
                    if terminalRef <> 0u && fillRef <> 0u then
                        { actorRef = actorRef
                          terminalRef = terminalRef
                          fillRef = fillRef
                          source = TerminalFlowHostShutdownCoordinatesFromPendingTerminal }
                    else
                        { actorRef = actorRef
                          terminalRef = 0u
                          fillRef = 0u
                          source = TerminalFlowHostShutdownCoordinatesUnavailable }
                | TerminalFlowPendingSlotAwaitingCandidate ->
                    { actorRef = actorRef
                      terminalRef = 0u
                      fillRef = 0u
                      source = TerminalFlowHostShutdownCoordinatesUnavailable }

        let private terminalFlowReducerStageTokenIssueFor
            (transaction:TerminalFlowAffineDispatchTransaction<TerminalFlowAffineDispatchPreparedStage>)
            =
            let authorization = transaction.authorization
            let stageToken = transaction.actorLease.actorJoin
            let pending = transaction.postCommitCapability.pending
            let constitution =
                match terminalFlowTerminalConstitutionSealForStageToken stageToken pending with
                | Ok receipt -> receipt
                | Error violation ->
                    invalidOp ("stage token terminal constitution rejected: " + terminalFlowTerminalConstitutionViolationText violation)
            let tokenRef = constitution.tokenRef
            let terminalRef = constitution.terminalRef
            let fillRef = constitution.fillRef
            let schedulerReleaseRef = constitution.schedulerReleaseRef
            let handoffRef =
                terminalFlowMintedRefOf
                    "terminal_final_outcome_handoff_ref"
                    (FastRuntimeFormat.format "%u:%u:%u:%u:%u:%u" [| box terminalRef; box fillRef; box (terminalFlowActorOutcomeJoinAdmissionIdentityRef stageToken); box schedulerReleaseRef; box stageToken.credentialGraphClosureRef; box constitution.constitutionRef |])
            let dispatchGrantRef =
                terminalFlowMintedRefOf
                    "terminal_linear_dispatch_grant_ref"
                    (FastRuntimeFormat.format "%u:%u:%u:%u:%u:%u" [| box (terminalFlowActorOutcomeJoinActorBindingRef stageToken); box (terminalFlowActorOutcomeJoinFairnessReleaseRef stageToken); box schedulerReleaseRef; box stageToken.terminalOrderAdmissionRef; box stageToken.credentialGraphClosureRef; box constitution.constitutionRef |])
            let handoff : TerminalFlowSchedulerWitness<TerminalFlowStageTokenHandoffWitnessKind> =
                terminalFlowSchedulerWitnessFor "terminal-stage-token-handoff" handoffRef
            let dispatchGrant : TerminalFlowSchedulerWitness<TerminalFlowDispatchGrantWitnessKind> =
                terminalFlowSchedulerWitnessFor "terminal-dispatch-grant" dispatchGrantRef
            let issueDigest =
                CompilerIdentityKernel.ContentDigest.ofText
                    "terminal-stage-token-issue"
                    (CompilerIdentityKernel.ContentDigest.text authorization.authorizationDigest
                     + "|constitution=" + string constitution.constitutionRef
                     + "|handoff=" + CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest handoff)
                     + "|grant=" + CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest dispatchGrant))
            { transaction = transaction
              constitution = constitution
              handoff = handoff
              dispatchGrant = dispatchGrant
              issueDigest = issueDigest
              issuedAtMs = Environment.TickCount64 }

        let private terminalFlowTerminalFillRatificationFor
            pushActorOwnerRef
            (issue:TerminalFlowReducerStageTokenIssueReceipt)
            (envelope:TerminalFlowBoundCommitEnvelope<TerminalFlowDoneSealedStage>)
            =
            let envelopeTerminalRef = terminalFlowIdentityRefDigest envelope.filled.terminalReceiptRef
            let envelopeFillRef = TerminalFlowFillKeyId.digest envelope.filled.fillKey
            if issue.constitutionRef = 0u then
                Error TerminalFlowTerminalFillRatificationConstitutionMissing
            elif pushActorOwnerRef = 0u then
                Error TerminalFlowTerminalFillRatificationPushActorOwnerMissing
            elif envelopeTerminalRef <> issue.terminalRef
                 || envelopeFillRef <> issue.fillRef
                 || envelope.writerBound.filled.fillReceiptRef <> envelope.filled.fillReceiptRef
                 || envelope.committed.writerBound.writerCapabilityRef <> envelope.writerBound.writerCapabilityRef then
                Error TerminalFlowTerminalFillRatificationIdentityMismatch
            elif envelope.writerBound.writerCapabilityRef = 0u || envelope.committed.writerJobRef = 0u then
                Error TerminalFlowTerminalFillRatificationWriterMissing
            elif envelope.committed.artifactReceiptRef = 0u then
                Error TerminalFlowTerminalFillRatificationArtifactMissing
            elif envelope.filled.fillReceiptRef = 0u then
                Error TerminalFlowTerminalFillRatificationIdentityMismatch
            elif envelope.wakerEdge.edgeRef = 0u || envelope.wakerEdge.targetTokenRef <> issue.tokenRef then
                Error TerminalFlowTerminalFillRatificationWakerMismatch
            else
                let exactOnceRef =
                    terminalFlowMintedRefOf
                        "terminal_fill_ratification_exact_once_ref"
                        (FastRuntimeFormat.format "%u:%u:%u:%u:%u:%u:%u:%u:%u" [| box issue.constitutionRef; box issue.receiptRef; box pushActorOwnerRef; box envelope.writerBound.writerCapabilityRef; box envelope.committed.writerJobRef; box envelope.committed.artifactReceiptRef; box envelope.filled.fillReceiptRef; box envelope.wakerEdge.edgeRef; box issue.exactOnceRef |])
                let ratificationRef =
                    terminalFlowMintedRefOf
                        "terminal_fill_ratification_ref"
                        (FastRuntimeFormat.format "%u:%u:%u:%u" [| box issue.constitutionRef; box pushActorOwnerRef; box envelope.filled.fillReceiptRef; box exactOnceRef |])
                Ok {
                    ratificationRef = ratificationRef
                    constitutionRef = issue.constitutionRef
                    issueReceiptRef = issue.receiptRef
                    pushActorOwnerRef = pushActorOwnerRef
                    artifactWriterCapabilityRef = envelope.writerBound.writerCapabilityRef
                    writerJobRef = envelope.committed.writerJobRef
                    artifactReceiptRef = envelope.committed.artifactReceiptRef
                    fillReceiptRef = envelope.filled.fillReceiptRef
                    wakerEdgeRef = envelope.wakerEdge.edgeRef
                    exactOnceRef = exactOnceRef
                    ratifiedAtMs = Environment.TickCount64
                }

        let private terminalFlowTerminalSealEvidenceFor
            (fillRatification:TerminalFlowTerminalFillRatificationReceipt)
            (envelope:TerminalFlowBoundCommitEnvelope<TerminalFlowDoneSealedStage>)
            =
            if fillRatification.ratificationRef = 0u then
                Error TerminalFlowTerminalSealEvidenceFillRatificationMissing
            elif envelope.committed.exitWitnessRef = 0u then
                Error TerminalFlowTerminalSealEvidenceExitWitnessMissing
            elif envelope.doneTransition.runEndReceiptRef = 0u then
                Error TerminalFlowTerminalSealEvidenceRunEndMissing
            else
                let exactOnceRef =
                    terminalFlowMintedRefOf
                        "terminal_seal_evidence_exact_once_ref"
                        (FastRuntimeFormat.format "%u:%u:%u:%u" [| box fillRatification.ratificationRef; box envelope.committed.exitWitnessRef; box envelope.doneTransition.runEndReceiptRef; box fillRatification.exactOnceRef |])
                Ok {
                    evidenceRef = terminalFlowMintedRefOf "terminal_seal_evidence_ref" (sprintf "%u:%u" fillRatification.ratificationRef exactOnceRef)
                    fillRatificationRef = fillRatification.ratificationRef
                    exitWitnessRef = envelope.committed.exitWitnessRef
                    runEndEvidenceRef = envelope.doneTransition.runEndReceiptRef
                    exactOnceRef = exactOnceRef
                    observedAtMs = Environment.TickCount64
                }

        let private terminalFlowPushActorOutcomeIvarOwnerRef
            (issue:TerminalFlowReducerStageTokenIssueReceipt) =
            terminalFlowMintedRefOf
                "terminal_push_actor_outcome_ivar_owner_ref"
                (FastRuntimeFormat.format "%u:%u:%u:%u:%u" [| box issue.actorRef; box issue.terminalRef; box issue.fillRef; box issue.tokenRef; box issue.receiptRef |])

        let private terminalFlowReducerStageTokenFillFor
            (issued:TerminalFlowAffineStageTokenIssue<TerminalFlowAffineStageTokenIssuedStage>)
            (envelope:TerminalFlowBoundCommitEnvelope<TerminalFlowDoneSealedStage>)
            =
            let issue = issued.issueReceipt
            let pushActorOwnerRef = terminalFlowPushActorOutcomeIvarOwnerRef issue
            let ratification =
                match terminalFlowTerminalFillRatificationFor pushActorOwnerRef issue envelope with
                | Ok receipt -> receipt
                | Error violation ->
                    invalidOp ("stage token fill ratification rejected: " + terminalFlowTerminalFillRatificationViolationText violation)
            let fillCommandRef =
                terminalFlowMintedRefOf
                    "terminal_push_actor_fill_command_ref"
                    (FastRuntimeFormat.format "%u:%u:%u" [| box pushActorOwnerRef; box issue.receiptRef; box ratification.ratificationRef |])
            let pushActorOwner : TerminalFlowSchedulerWitness<TerminalFlowPushActorOwnerWitnessKind> =
                terminalFlowSchedulerWitnessFor "terminal-push-actor-owner" pushActorOwnerRef
            let fillCommand : TerminalFlowSchedulerWitness<TerminalFlowFillCommandWitnessKind> =
                terminalFlowSchedulerWitnessFor "terminal-fill-command" fillCommandRef
            let fillDigest =
                CompilerIdentityKernel.ContentDigest.ofText
                    "terminal-stage-token-fill"
                    (CompilerIdentityKernel.ContentDigest.text issue.issueDigest
                     + "|ratification=" + string ratification.ratificationRef
                     + "|owner=" + CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest pushActorOwner)
                     + "|command=" + CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest fillCommand))
            ratification,
            { issue = issue
              ratification = ratification
              pushActorOwner = pushActorOwner
              fillCommand = fillCommand
              fillDigest = fillDigest
              filledAtMs = Environment.TickCount64 }

        let private terminalFlowReducerStageTokenSealAuthorizationFor
            (filled:TerminalFlowAffineStageTokenFillCommit<TerminalFlowAffineStageTokenFilledStage>) =
            let fill = filled.fillReceipt
            let sealEvidence =
                match terminalFlowTerminalSealEvidenceFor filled.fillRatification filled.completedEnvelope with
                | Ok evidence -> evidence
                | Error violation ->
                    invalidOp ("stage token seal evidence rejected: " + terminalFlowTerminalSealEvidenceViolationText violation)
            let sealCommandRef =
                terminalFlowMintedRefOf
                    "terminal_stage_token_seal_command_ref"
                    (FastRuntimeFormat.format "%u:%u:%u" [| box fill.receiptRef; box sealEvidence.evidenceRef; box filled.exactOnceRef |])
            let sealCommand : TerminalFlowSchedulerWitness<TerminalFlowSealCommandWitnessKind> =
                terminalFlowSchedulerWitnessFor "terminal-seal-command" sealCommandRef
            let authorizationDigest =
                CompilerIdentityKernel.ContentDigest.ofText
                    "terminal-stage-token-seal-authorization"
                    (CompilerIdentityKernel.ContentDigest.text fill.fillDigest
                     + "|evidence=" + string sealEvidence.exactOnceRef
                     + "|command=" + CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest sealCommand))
            { fill = fill
              sealEvidence = sealEvidence
              sealCommand = sealCommand
              authorizationDigest = authorizationDigest
              authorizedAtMs = Environment.TickCount64 }

        // Destructive domain migration round : the live interpreter and the
        // production fixture share the issue/fill/seal constructors. A fixture may
        // supply synthetic effects, but it cannot mint fill or seal authority through
        // an observer/writer-owned parallel path.
        let private terminalFlowAffineStageTokenIssueFor
            (transaction:TerminalFlowAffineDispatchTransaction<TerminalFlowAffineDispatchPreparedStage>)
            : TerminalFlowAffineStageTokenIssue<TerminalFlowAffineStageTokenIssuedStage> =
            let issueReceipt = terminalFlowReducerStageTokenIssueFor transaction
            let issueEventDigest =
                CompilerIdentityKernel.ContentDigest.ofText
                    "terminal-affine-stage-token-issue"
                    (CompilerIdentityKernel.ContentDigest.text transaction.transactionDigest
                     + "|issue=" + CompilerIdentityKernel.ContentDigest.text issueReceipt.issueDigest
                     + "|ordinal=" + terminalFlowAffineTransitionOrdinalText transaction.transitionOrdinal)
            { transaction = transaction
              issueReceipt = issueReceipt
              issueEventDigest = issueEventDigest }

        let private terminalFlowAffineStageTokenFillCommitFor
            (issued:TerminalFlowAffineStageTokenIssue<TerminalFlowAffineStageTokenIssuedStage>)
            (envelope:TerminalFlowBoundCommitEnvelope<TerminalFlowDoneSealedStage>)
            : TerminalFlowAffineStageTokenFillCommit<TerminalFlowAffineStageTokenFilledStage> =
            let transaction = issued.transaction
            let fillRatification, fillReceipt = terminalFlowReducerStageTokenFillFor issued envelope
            let fillEventDigest =
                CompilerIdentityKernel.ContentDigest.ofText
                    "terminal-affine-stage-token-fill"
                    (CompilerIdentityKernel.ContentDigest.text issued.issueEventDigest
                     + "|fill=" + CompilerIdentityKernel.ContentDigest.text fillReceipt.fillDigest
                     + "|transaction=" + CompilerIdentityKernel.ContentDigest.text transaction.transactionDigest)
            { issued = issued
              completedEnvelope = envelope
              fillRatification = fillRatification
              fillReceipt = fillReceipt
              fillEventDigest = fillEventDigest }

        let private terminalFlowAffineStageTokenSealAuthorizationFor
            (filled:TerminalFlowAffineStageTokenFillCommit<TerminalFlowAffineStageTokenFilledStage>)
            : TerminalFlowAffineStageTokenSealAuthorization<TerminalFlowAffineStageTokenSealAuthorizedStage> =
            let transaction = filled.issued.transaction
            let authorizationReceipt = terminalFlowReducerStageTokenSealAuthorizationFor filled
            let authorizationEventDigest =
                CompilerIdentityKernel.ContentDigest.ofText
                    "terminal-affine-stage-token-seal"
                    (CompilerIdentityKernel.ContentDigest.text filled.fillEventDigest
                     + "|authorization=" + string authorizationReceipt.exactOnceRef
                     + "|transaction=" + CompilerIdentityKernel.ContentDigest.text transaction.transactionDigest)
            { filled = filled
              authorizationReceipt = authorizationReceipt
              authorizationEventDigest = authorizationEventDigest }

        // MIGRATION / bonus migration 6 of 5: one recursive terminal protocol is
        // the reducer-owned authority for the full production path.  The older
        // seal, convergence, actor and dispatch records remain projections until
        // their consumers are removed, but exit authorization must agree with this
        // monotone protocol.  No renderer, fixture or Hopac worker can construct a
        // later stage without carrying the private predecessor value.
        // MIGRATION / bonus migration 7 of 5: the unified protocol no
        // longer erases root/outcome/installation lineage into unrelated scalar
        // fields.  Each stage contains its typed predecessor.  The reducer can
        // therefore reject a candidate that belongs to another build even when
        // its coarse stage rank appears monotone.
        type TerminalFlowProtocolRootLineage = private {
            rootRef : uint32
        }

        type TerminalFlowProtocolOutcomeLineage = private {
            root : TerminalFlowProtocolRootLineage
            terminalRef : uint32
            fillRef : uint32
        }

        type TerminalFlowProtocolInstalledLineage = private {
            outcome : TerminalFlowProtocolOutcomeLineage
            installationRef : uint32
            admissionIdentityRef : uint32
        }

        type TerminalFlowDispatchProtocolState =
            | TerminalFlowProtocolAwaitRoot
            | TerminalFlowProtocolAwaitOutcome of TerminalFlowProtocolRootLineage
            | TerminalFlowProtocolAwaitInstallation of TerminalFlowProtocolOutcomeLineage
            | TerminalFlowProtocolOutcomeInstalled of TerminalFlowProtocolInstalledLineage
            | TerminalFlowProtocolDispatchBlocked of lineage:TerminalFlowProtocolInstalledLineage * blocker:TerminalFlowDispatchBlocker * observedAtRevision:int64
            | TerminalFlowProtocolDispatchReady of TerminalFlowDispatchConstitution<TerminalFlowDispatchConstitutionReadyStage>
            | TerminalFlowProtocolDispatchIssued of TerminalFlowDispatchIssuance<TerminalFlowDispatchConstitutionIssuedStage>
            | TerminalFlowProtocolAffinePrepared of TerminalFlowAffineDispatchTransaction<TerminalFlowAffineDispatchPreparedStage>
            | TerminalFlowProtocolAffineIssued of TerminalFlowAffineDispatchTransaction<TerminalFlowAffineStageTokenIssuedStage>
            | TerminalFlowProtocolAffineFilled of TerminalFlowAffineDispatchTransaction<TerminalFlowAffineStageTokenFilledStage>
            | TerminalFlowProtocolSealAuthorized of TerminalFlowAffineDispatchTransaction<TerminalFlowAffineStageTokenSealAuthorizedStage>
            | TerminalFlowProtocolExitAuthorized of TerminalFlowReducerTotalOrderChain
            | TerminalFlowProtocolFailClosed of TerminalFlowReducerTotalOrderChain

        // Every accepted step is named.  Rank is now a rendering convenience,
        // not transition authority.  Success may not skip a production edge;
        // typed failure is the only edge allowed to close from any nonterminal
        // stage.
        type TerminalFlowProtocolEdge =
            | TerminalFlowProtocolRootResolvedEdge
            | TerminalFlowProtocolOutcomeSealedEdge
            | TerminalFlowProtocolOutcomeInstalledEdge
            | TerminalFlowProtocolOutcomeReinstalledBeforeIssueEdge
            | TerminalFlowProtocolDispatchBlockerObservedEdge
            | TerminalFlowProtocolDispatchBlockerChangedEdge
            | TerminalFlowProtocolDispatchBlockedReconstitutedEdge
            | TerminalFlowProtocolDispatchConstitutedEdge
            | TerminalFlowProtocolDispatchReconstitutedEdge
            | TerminalFlowProtocolDispatchIssuedEdge
            | TerminalFlowProtocolDispatchRedrivenEdge
            | TerminalFlowProtocolDispatchIssuanceSupersededBeforeAffineEdge
            | TerminalFlowProtocolAffinePreparedEdge
            | TerminalFlowProtocolStageTokenIssuedEdge
            | TerminalFlowProtocolStageTokenFilledEdge
            | TerminalFlowProtocolSealAuthorizedEdge
            | TerminalFlowProtocolExitAuthorizedEdge
            | TerminalFlowProtocolFailClosedEdge

        type TerminalFlowDispatchProtocolStateAdvance =
            | TerminalFlowProtocolAdvanced of edge:TerminalFlowProtocolEdge * beforeRank:int * afterRank:int
            | TerminalFlowProtocolCoalesced of rank:int
            | TerminalFlowProtocolRegressionRejected of beforeRank:int * candidateRank:int
            | TerminalFlowProtocolSkippedStageRejected of beforeRank:int * candidateRank:int
            | TerminalFlowProtocolLineageDivergenceRejected of edge:TerminalFlowProtocolEdge * expectedRef:uint32 * candidateRef:uint32
            | TerminalFlowProtocolPoisonedRejected of poisonRef:uint32 * candidateRef:uint32
            | TerminalFlowProtocolPoisonCoalesced of poisonRef:uint32 * candidateRef:uint32
            | TerminalFlowProtocolPoisonFailClosedIssued of poisonRef:uint32 * commandRef:uint32
            | TerminalFlowProtocolTerminalConflictRejected of beforeRef:uint32 * candidateRef:uint32

        type TerminalFlowProtocolPoison =
            | TerminalFlowProtocolSkippedStagePoison of beforeRank:int * candidateRank:int
            | TerminalFlowProtocolLineagePoison of edge:TerminalFlowProtocolEdge * expectedRef:uint32 * candidateRef:uint32
            | TerminalFlowProtocolTerminalConflictPoison of beforeRef:uint32 * candidateRef:uint32

        type TerminalFlowProtocolPoisonLatch =
            | TerminalFlowProtocolPoisonHealthy
            | TerminalFlowProtocolPoisonLatched of poison:TerminalFlowProtocolPoison * poisonRef:uint32 * latchedAtRevision:int64

        let private terminalFlowProtocolPoisonLatchIsPoisoned = function
            | TerminalFlowProtocolPoisonHealthy -> false
            | TerminalFlowProtocolPoisonLatched _ -> true

        let private terminalFlowProtocolPoisonLatchRef = function
            | TerminalFlowProtocolPoisonHealthy -> 0u
            | TerminalFlowProtocolPoisonLatched(_, poisonRef, _) -> poisonRef

        type TerminalFlowProtocolPoisonTerminalization =
            | TerminalFlowProtocolPoisonNotTerminalized
            | TerminalFlowProtocolPoisonFailClosedTerminalized of poisonRef:uint32 * commandRef:uint32 * issuedAtRevision:int64

        let private terminalFlowProtocolPoisonTerminalizationRef = function
            | TerminalFlowProtocolPoisonNotTerminalized -> 0u
            | TerminalFlowProtocolPoisonFailClosedTerminalized(poisonRef, commandRef, issuedAtRevision) ->
                terminalFlowMintedRefOf
                    "terminal_dispatch_protocol_poison_terminalization_ref"
                    (FastRuntimeFormat.format "%u:%u:%d" [| box poisonRef; box commandRef; box issuedAtRevision |])

        // Actor, scheduler dispatch, reducer possession, constitution and protocol
        // advance through one immutable lifecycle frame. The phantom stage selects
        // which frame may be consumed, while every transaction preserves its
        // consumed while the recursive predecessor preserves the complete affine
        // chain without reconstructing it from rendered refs.
        type TerminalFlowDispatchLifecycleAwaitRootStage = class end
        type TerminalFlowDispatchLifecycleAwaitOutcomeStage = class end
        type TerminalFlowDispatchLifecycleAwaitInstallationStage = class end
        type TerminalFlowDispatchLifecycleOutcomeInstalledStage = class end
        type TerminalFlowDispatchLifecycleBlockedStage = class end
        type TerminalFlowDispatchLifecycleReadyStage = class end
        type TerminalFlowDispatchLifecycleIssuedStage = class end
        type TerminalFlowDispatchLifecycleAffinePreparedStage = class end
        type TerminalFlowDispatchLifecycleAffineIssuedStage = class end
        type TerminalFlowDispatchLifecycleAffineFilledStage = class end
        type TerminalFlowDispatchLifecycleSealAuthorizedStage = class end
        type TerminalFlowDispatchLifecycleExitAuthorizedStage = class end
        type TerminalFlowDispatchLifecycleFailClosedStage = class end

        type private TerminalFlowDispatchLifecycleFrame = {
            protocol : TerminalFlowDispatchProtocolState
            kernelActor : TerminalFlowKernelActor
            kernelDispatch : TerminalFlowKernelDispatch
            reducerPossession : TerminalFlowReducerActorAuthorityId
            dispatchConstitution : TerminalFlowDispatchConstitutionState
            reducerRevision : int64
            sourceEventRef : uint32
            frameRef : uint32
            exactOnceRef : uint32
            transition : TerminalFlowDispatchProtocolStateAdvance
            poison : TerminalFlowProtocolPoisonLatch
            poisonTerminalization : TerminalFlowProtocolPoisonTerminalization
            rejectionCount : int64
            depth : int
            previous : TerminalFlowDispatchLifecycleFrame option
        }

        type TerminalFlowDispatchLifecycle<'Stage> = private {
            frame : TerminalFlowDispatchLifecycleFrame
        }

        type TerminalFlowAnyDispatchLifecycle =
            | TerminalFlowLifecycleAwaitRoot of TerminalFlowDispatchLifecycle<TerminalFlowDispatchLifecycleAwaitRootStage>
            | TerminalFlowLifecycleAwaitOutcome of TerminalFlowDispatchLifecycle<TerminalFlowDispatchLifecycleAwaitOutcomeStage>
            | TerminalFlowLifecycleAwaitInstallation of TerminalFlowDispatchLifecycle<TerminalFlowDispatchLifecycleAwaitInstallationStage>
            | TerminalFlowLifecycleOutcomeInstalled of TerminalFlowDispatchLifecycle<TerminalFlowDispatchLifecycleOutcomeInstalledStage>
            | TerminalFlowLifecycleBlocked of TerminalFlowDispatchLifecycle<TerminalFlowDispatchLifecycleBlockedStage>
            | TerminalFlowLifecycleReady of TerminalFlowDispatchLifecycle<TerminalFlowDispatchLifecycleReadyStage>
            | TerminalFlowLifecycleIssued of TerminalFlowDispatchLifecycle<TerminalFlowDispatchLifecycleIssuedStage>
            | TerminalFlowLifecycleAffinePrepared of TerminalFlowDispatchLifecycle<TerminalFlowDispatchLifecycleAffinePreparedStage>
            | TerminalFlowLifecycleAffineIssued of TerminalFlowDispatchLifecycle<TerminalFlowDispatchLifecycleAffineIssuedStage>
            | TerminalFlowLifecycleAffineFilled of TerminalFlowDispatchLifecycle<TerminalFlowDispatchLifecycleAffineFilledStage>
            | TerminalFlowLifecycleSealAuthorized of TerminalFlowDispatchLifecycle<TerminalFlowDispatchLifecycleSealAuthorizedStage>
            | TerminalFlowLifecycleExitAuthorized of TerminalFlowDispatchLifecycle<TerminalFlowDispatchLifecycleExitAuthorizedStage>
            | TerminalFlowLifecycleFailClosed of TerminalFlowDispatchLifecycle<TerminalFlowDispatchLifecycleFailClosedStage>

        let private terminalFlowDispatchProtocolStateRank = function
            | TerminalFlowProtocolAwaitRoot -> 0
            | TerminalFlowProtocolAwaitOutcome _ -> 1
            | TerminalFlowProtocolAwaitInstallation _ -> 2
            | TerminalFlowProtocolOutcomeInstalled _ -> 3
            | TerminalFlowProtocolDispatchBlocked _ -> 4
            | TerminalFlowProtocolDispatchReady _ -> 5
            | TerminalFlowProtocolDispatchIssued _ -> 6
            | TerminalFlowProtocolAffinePrepared _ -> 7
            | TerminalFlowProtocolAffineIssued _ -> 8
            | TerminalFlowProtocolAffineFilled _ -> 9
            | TerminalFlowProtocolSealAuthorized _ -> 10
            | TerminalFlowProtocolExitAuthorized _
            | TerminalFlowProtocolFailClosed _ -> 11

        let private terminalFlowDispatchProtocolStateText = function
            | TerminalFlowProtocolAwaitRoot -> "AwaitRoot"
            | TerminalFlowProtocolAwaitOutcome lineage ->
                sprintf "AwaitOutcome(root_ref=%u)" lineage.rootRef
            | TerminalFlowProtocolAwaitInstallation lineage ->
                FastRuntimeFormat.format "AwaitInstallation(root_ref=%u|terminal_ref=%u|fill_ref=%u)" [| box lineage.root.rootRef; box lineage.terminalRef; box lineage.fillRef |]
            | TerminalFlowProtocolOutcomeInstalled lineage ->
                FastRuntimeFormat.format "OutcomeInstalled(root_ref=%u|terminal_ref=%u|fill_ref=%u|installation_ref=%u|admission_identity_ref=%u)" [| box lineage.outcome.root.rootRef; box lineage.outcome.terminalRef; box lineage.outcome.fillRef; box lineage.installationRef; box lineage.admissionIdentityRef |]
            | TerminalFlowProtocolDispatchBlocked(lineage, blocker, revision) ->
                FastRuntimeFormat.format "DispatchBlocked(root_ref=%u|terminal_ref=%u|fill_ref=%u|installation_ref=%u|admission_identity_ref=%u|blocker=%s|revision=%d)" [| box lineage.outcome.root.rootRef; box lineage.outcome.terminalRef; box lineage.outcome.fillRef; box lineage.installationRef; box lineage.admissionIdentityRef; box (terminalFlowDispatchBlockerText blocker); box revision |]
            | TerminalFlowProtocolDispatchReady constitution ->
                FastRuntimeFormat.format "DispatchReady(constitution_ref=%u|material_lineage_ref=%u|exact_once_ref=%u)" [| box constitution.constitutionRef; box (terminalFlowDispatchConstitutionLineageRef constitution); box constitution.exactOnceRef |]
            | TerminalFlowProtocolDispatchIssued issuance ->
                FastRuntimeFormat.format "DispatchIssued(issuance_ref=%u|constitution_ref=%u|exact_once_ref=%u)" [| box issuance.issuanceRef; box issuance.constitution.constitutionRef; box issuance.exactOnceRef |]
            | TerminalFlowProtocolAffinePrepared transaction ->
                sprintf "AffinePrepared(transaction_ref=%u|exact_once_ref=%u)" transaction.transactionRef transaction.exactOnceRef
            | TerminalFlowProtocolAffineIssued transaction ->
                sprintf "AffineIssued(transaction_ref=%u|exact_once_ref=%u)" transaction.transactionRef transaction.exactOnceRef
            | TerminalFlowProtocolAffineFilled transaction ->
                sprintf "AffineFilled(transaction_ref=%u|exact_once_ref=%u)" transaction.transactionRef transaction.exactOnceRef
            | TerminalFlowProtocolSealAuthorized transaction ->
                sprintf "SealAuthorized(transaction_ref=%u|exact_once_ref=%u)" transaction.transactionRef transaction.exactOnceRef
            | TerminalFlowProtocolExitAuthorized chain ->
                FastRuntimeFormat.format "ExitAuthorized(run_end_ref=%u|physical_exit_ref=%u|exit=%d)" [| box chain.runEnd.receiptRef; box chain.physicalExit.receiptRef; box chain.exitCode |]
            | TerminalFlowProtocolFailClosed chain ->
                FastRuntimeFormat.format "FailClosed(run_end_ref=%u|physical_exit_ref=%u|exit=%d|failure_ref=%u)" [| box chain.runEnd.receiptRef; box chain.physicalExit.receiptRef; box chain.exitCode; box (chain.failureRef |> Option.defaultValue 0u) |]

        let private terminalFlowDispatchProtocolStateRef protocol =
            terminalFlowMintedRefOf "terminal_dispatch_protocol_ref" (terminalFlowDispatchProtocolStateText protocol)

        let private terminalFlowDispatchLifecycleFrame = function
            | TerminalFlowLifecycleAwaitRoot lifecycle -> lifecycle.frame
            | TerminalFlowLifecycleAwaitOutcome lifecycle -> lifecycle.frame
            | TerminalFlowLifecycleAwaitInstallation lifecycle -> lifecycle.frame
            | TerminalFlowLifecycleOutcomeInstalled lifecycle -> lifecycle.frame
            | TerminalFlowLifecycleBlocked lifecycle -> lifecycle.frame
            | TerminalFlowLifecycleReady lifecycle -> lifecycle.frame
            | TerminalFlowLifecycleIssued lifecycle -> lifecycle.frame
            | TerminalFlowLifecycleAffinePrepared lifecycle -> lifecycle.frame
            | TerminalFlowLifecycleAffineIssued lifecycle -> lifecycle.frame
            | TerminalFlowLifecycleAffineFilled lifecycle -> lifecycle.frame
            | TerminalFlowLifecycleSealAuthorized lifecycle -> lifecycle.frame
            | TerminalFlowLifecycleExitAuthorized lifecycle -> lifecycle.frame
            | TerminalFlowLifecycleFailClosed lifecycle -> lifecycle.frame

        let private terminalFlowDispatchLifecycleProtocol lifecycle =
            (terminalFlowDispatchLifecycleFrame lifecycle).protocol

        let private terminalFlowDispatchLifecycleConstitution lifecycle =
            (terminalFlowDispatchLifecycleFrame lifecycle).dispatchConstitution

        let private terminalFlowDispatchLifecycleRef lifecycle =
            (terminalFlowDispatchLifecycleFrame lifecycle).frameRef

        let private terminalFlowDispatchLifecycleExactOnceRef lifecycle =
            (terminalFlowDispatchLifecycleFrame lifecycle).exactOnceRef

        let private terminalFlowDispatchLifecycleActorStateRef = function
            | KernelActorNoop -> 0u
            | KernelActorArmed(phase, fillKey, _) ->
                terminalFlowStableAuthorityRef (
                    TerminalFlowDispatchLifecycleActorIdentity(
                        phase,
                        TerminalFlowFillKeyId.digest fillKey))

        let private terminalFlowDispatchLifecycleDispatchStateRef = function
            | KernelDispatchUnavailable -> 0u
            | KernelDispatchReady(identity, _, _) ->
                terminalFlowStableAuthorityRef (
                    TerminalFlowDispatchLifecycleDispatchIdentity(
                        1,
                        terminalFlowDispatchRequestIdentityRef identity,
                        terminalFlowIdentityRefDigest (terminalFlowDispatchRequestIdentityFillRef identity)))
            | KernelDispatchAccepted identity ->
                terminalFlowStableAuthorityRef (
                    TerminalFlowDispatchLifecycleDispatchIdentity(
                        2,
                        terminalFlowDispatchRequestIdentityRef identity,
                        terminalFlowIdentityRefDigest (terminalFlowDispatchRequestIdentityFillRef identity)))

        let private terminalFlowDispatchLifecycleConstitutionStateRef = function
            | TerminalFlowDispatchConstitutionBlocked(blocker, revision, _) ->
                terminalFlowStableAuthorityRef (
                    TerminalFlowDispatchLifecycleBlockedConstitutionIdentity(blocker, revision))
            | TerminalFlowDispatchConstitutionReady constitution ->
                terminalFlowStableAuthorityRef (
                    TerminalFlowDispatchLifecycleConstitutionStageIdentity(
                        1,
                        terminalFlowDispatchConstitutionLineageRef constitution,
                        constitution.exactOnceRef))
            | TerminalFlowDispatchConstitutionIssued issuance ->
                terminalFlowStableAuthorityRef (
                    TerminalFlowDispatchLifecycleConstitutionStageIdentity(
                        2,
                        issuance.issuanceRef,
                        issuance.exactOnceRef))
            | TerminalFlowDispatchAffinePrepared transaction ->
                terminalFlowStableAuthorityRef (
                    TerminalFlowDispatchLifecycleConstitutionStageIdentity(
                        3,
                        transaction.transactionRef,
                        transaction.exactOnceRef))
            | TerminalFlowDispatchAffineIssued transaction ->
                terminalFlowStableAuthorityRef (
                    TerminalFlowDispatchLifecycleConstitutionStageIdentity(
                        4,
                        transaction.transactionRef,
                        transaction.exactOnceRef))
            | TerminalFlowDispatchAffineFilled transaction ->
                terminalFlowStableAuthorityRef (
                    TerminalFlowDispatchLifecycleConstitutionStageIdentity(
                        5,
                        transaction.transactionRef,
                        transaction.exactOnceRef))
            | TerminalFlowDispatchAffineSealAuthorized transaction ->
                terminalFlowStableAuthorityRef (
                    TerminalFlowDispatchLifecycleConstitutionStageIdentity(
                        6,
                        transaction.transactionRef,
                        transaction.exactOnceRef))

        let private terminalFlowDispatchLifecycleBox frame =
            match frame.protocol with
            | TerminalFlowProtocolAwaitRoot -> TerminalFlowLifecycleAwaitRoot { frame = frame }
            | TerminalFlowProtocolAwaitOutcome _ -> TerminalFlowLifecycleAwaitOutcome { frame = frame }
            | TerminalFlowProtocolAwaitInstallation _ -> TerminalFlowLifecycleAwaitInstallation { frame = frame }
            | TerminalFlowProtocolOutcomeInstalled _ -> TerminalFlowLifecycleOutcomeInstalled { frame = frame }
            | TerminalFlowProtocolDispatchBlocked _ -> TerminalFlowLifecycleBlocked { frame = frame }
            | TerminalFlowProtocolDispatchReady _ -> TerminalFlowLifecycleReady { frame = frame }
            | TerminalFlowProtocolDispatchIssued _ -> TerminalFlowLifecycleIssued { frame = frame }
            | TerminalFlowProtocolAffinePrepared _ -> TerminalFlowLifecycleAffinePrepared { frame = frame }
            | TerminalFlowProtocolAffineIssued _ -> TerminalFlowLifecycleAffineIssued { frame = frame }
            | TerminalFlowProtocolAffineFilled _ -> TerminalFlowLifecycleAffineFilled { frame = frame }
            | TerminalFlowProtocolSealAuthorized _ -> TerminalFlowLifecycleSealAuthorized { frame = frame }
            | TerminalFlowProtocolExitAuthorized _ -> TerminalFlowLifecycleExitAuthorized { frame = frame }
            | TerminalFlowProtocolFailClosed _ -> TerminalFlowLifecycleFailClosed { frame = frame }

        let private terminalFlowDispatchLifecycleFrameFor
            previous
            transition
            reducerRevision
            sourceEventRef
            kernelActor
            kernelDispatch
            reducerPossession
            dispatchConstitution
            poison
            poisonTerminalization
            rejectionCount
            protocol =
            let previousFrame =
                previous
                |> Option.map terminalFlowDispatchLifecycleFrame
            let previousFrameRef =
                previousFrame
                |> Option.map (fun frame -> frame.frameRef)
                |> Option.defaultValue 0u
            let depth =
                previousFrame
                |> Option.map (fun frame -> frame.depth + 1)
                |> Option.defaultValue 0
            let possessionActorRef, possessionTerminalRef, possessionFillRef =
                terminalFlowReducerActorCoordinates reducerPossession
            let protocolRef = terminalFlowDispatchProtocolStateRef protocol
            let actorStateRef = terminalFlowDispatchLifecycleActorStateRef kernelActor
            let dispatchStateRef = terminalFlowDispatchLifecycleDispatchStateRef kernelDispatch
            let constitutionStateRef = terminalFlowDispatchLifecycleConstitutionStateRef dispatchConstitution
            let frameRef =
                terminalFlowStableAuthorityRef (
                    TerminalFlowDispatchLifecycleFrameIdentity(
                        protocolRef,
                        actorStateRef,
                        dispatchStateRef,
                        possessionActorRef,
                        possessionTerminalRef,
                        possessionFillRef,
                        constitutionStateRef,
                        terminalFlowProtocolPoisonLatchRef poison,
                        terminalFlowProtocolPoisonTerminalizationRef poisonTerminalization,
                        rejectionCount))
            let exactOnceRef =
                terminalFlowStableAuthorityRef (
                    TerminalFlowDispatchLifecycleExactOnceIdentity(
                        frameRef,
                        previousFrameRef,
                        reducerRevision,
                        sourceEventRef))
            { protocol = protocol
              kernelActor = kernelActor
              kernelDispatch = kernelDispatch
              reducerPossession = reducerPossession
              dispatchConstitution = dispatchConstitution
              reducerRevision = reducerRevision
              sourceEventRef = sourceEventRef
              frameRef = frameRef
              exactOnceRef = exactOnceRef
              transition = transition
              poison = poison
              poisonTerminalization = poisonTerminalization
              rejectionCount = rejectionCount
              depth = depth
              previous = previousFrame }
            |> terminalFlowDispatchLifecycleBox

        let private terminalFlowDispatchLifecycleInitial () =
            terminalFlowDispatchLifecycleFrameFor
                None
                (TerminalFlowProtocolCoalesced 0)
                0L
                0u
                KernelActorNoop
                KernelDispatchUnavailable
                terminalFlowReducerQapOutcomeActorInitial.actor
                (TerminalFlowDispatchConstitutionBlocked(
                    TerminalFlowDispatchGreenPathMissing,
                    0L,
                    0L))
                TerminalFlowProtocolPoisonHealthy
                TerminalFlowProtocolPoisonNotTerminalized
                0L
                TerminalFlowProtocolAwaitRoot

        let private terminalFlowDispatchProtocolStateIsTerminal = function
            | TerminalFlowProtocolExitAuthorized _
            | TerminalFlowProtocolFailClosed _ -> true
            | _ -> false

        let private terminalFlowReducerStageTokenFailureFor
            (issue:TerminalFlowReducerStageTokenIssueReceipt)
            reason
            =
            let failureRef = terminalFlowStageTokenFailureRefOfReason reason |> terminalFlowDurableRefValue
            let ratificationRef =
                terminalFlowMintedRefOf
                    "terminal_failclosed_ratification_ref"
                    (FastRuntimeFormat.format "%u:%u:%u:%u" [| box issue.constitutionRef; box issue.receiptRef; box failureRef; box issue.exactOnceRef |])
            let exactOnceRef = terminalFlowMintedRefOf "terminal_stage_token_failure_exact_once_ref" (FastRuntimeFormat.format "%u:%u:%u:%u:%u:%u" [| box issue.constitutionRef; box ratificationRef; box issue.exactOnceRef; box issue.admissionIdentityRef; box issue.schedulerReleaseRef; box failureRef |])
            { receiptRef = terminalFlowMintedRefOf "terminal_stage_token_failure_receipt_ref" (FastRuntimeFormat.format "%u:%u:%u:%u" [| box issue.receiptRef; box issue.constitutionRef; box ratificationRef; box exactOnceRef |])
              constitutionRef = issue.constitutionRef
              ratificationRef = ratificationRef
              issueReceiptRef = issue.receiptRef
              tokenRef = Some issue.tokenRef
              actorRef = Some issue.actorRef
              terminalRef = issue.terminalRef
              fillRef = issue.fillRef
              admissionRef = issue.admissionRef
              admissionIdentityRef = issue.admissionIdentityRef
              schedulerReleaseRef = issue.schedulerReleaseRef
              failureRef = failureRef
              exactOnceRef = exactOnceRef
              failedAtMs = Environment.TickCount64 }

        type TerminalFlowQapFinalizationPreparedStage = class end
        type TerminalFlowQapFinalizationCommittedStage = class end
        type TerminalFlowQapFinalizationHandoffEnqueuedStage = class end

        type TerminalFlowQapFinalizationTransaction<'Stage> = private {
            transactionRef : uint32
            sourceEventRef : uint32
            generation : TerminalFlowQapGenerationAuthority
            proofRef : uint32
            resolution : TerminalFlowQapResolutionBox
            outcome : TerminalFlowReducerOutcomeAuthorityId
            handoff : TerminalFlowFinalOutcomeHandoffId
            dispatchDecision : TerminalFlowQapFinalOutcomeDispatchDecision
            stateRevisionBefore : int64
            stateRevisionAfter : int64
            exactOnceRef : uint32
        }

        type TerminalFlowQapFinalizationState =
            | TerminalFlowQapFinalizationIdle
            | TerminalFlowQapFinalizationPrepared of TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationPreparedStage>
            | TerminalFlowQapFinalizationCommitted of TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationCommittedStage>
            | TerminalFlowQapFinalizationHandoffEnqueued of TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationHandoffEnqueuedStage>

        // QAP PROOF AUTHORITY CUTOVER: post-finality work executes only
        // from recursive proof decisions declared beside the affine capability.
        // This section owns renderers and stage transitions; the old parallel
        // proven/missing records and stage-local blocker accumulation are gone.

        let rec private terminalFlowQapComponentRefPathText = function
            | TerminalFlowQapComponentRefLast componentRef -> string componentRef
            | TerminalFlowQapComponentRefMore(componentRef, rest) ->
                string componentRef + "," + terminalFlowQapComponentRefPathText rest

        let rec private terminalFlowQapComponentRefPathToList = function
            | TerminalFlowQapComponentRefLast componentRef -> [ componentRef ]
            | TerminalFlowQapComponentRefMore(componentRef, rest) ->
                componentRef :: terminalFlowQapComponentRefPathToList rest

        let rec private terminalFlowQapComponentRefPathOfList = function
            | [] -> None
            | [ componentRef ] -> Some(TerminalFlowQapComponentRefLast componentRef)
            | componentRef :: rest ->
                terminalFlowQapComponentRefPathOfList rest
                |> Option.map (fun path -> TerminalFlowQapComponentRefMore(componentRef, path))

        let private terminalFlowQapSccMissingEvidenceText (missing:TerminalFlowQapSccMissingEvidence) =
            match missing with
            | TerminalFlowQapSccMissingProgressCapableComponents componentRefs ->
                "progress_capable_components=" + terminalFlowQapComponentRefPathText componentRefs

        let rec private terminalFlowQapSccMissingEvidencePathText = function
            | TerminalFlowQapSccMissingEvidenceLast missing ->
                terminalFlowQapSccMissingEvidenceText missing
            | TerminalFlowQapSccMissingEvidenceMore(missing, rest) ->
                terminalFlowQapSccMissingEvidenceText missing + ";" + terminalFlowQapSccMissingEvidencePathText rest

        type TerminalFlowQapSccProofAssessment =
            | TerminalFlowQapSccProofCertified of certificateRef:uint32 * generationRef:uint32
            | TerminalFlowQapSccProofUnclosed of TerminalFlowQapSccMissingEvidencePath

        let rec private terminalFlowQapDiagnosticProjectionText = function
            | TerminalFlowQapProofSeed planRef -> sprintf "Seed(plan_ref=%u)" planRef
            | TerminalFlowQapProofRoot(previous, rootReceiptRef) -> sprintf "Root(%s|root_ref=%u)" (terminalFlowQapDiagnosticProjectionText previous) rootReceiptRef
            | TerminalFlowQapProofProgress(previous, snapshotRef) -> sprintf "Progress(%s|snapshot_ref=%u)" (terminalFlowQapDiagnosticProjectionText previous) snapshotRef
            | TerminalFlowQapProofPending(previous, pendingRef) -> sprintf "Pending(%s|pending_ref=%u)" (terminalFlowQapDiagnosticProjectionText previous) pendingRef
            | TerminalFlowQapProofFairness(previous, releaseReceiptRef) -> sprintf "Fairness(%s|release_ref=%u)" (terminalFlowQapDiagnosticProjectionText previous) releaseReceiptRef
            | TerminalFlowQapProofRecovery(previous, recoveryRef) -> sprintf "Recovery(%s|recovery_ref=%u)" (terminalFlowQapDiagnosticProjectionText previous) recoveryRef
            | TerminalFlowQapProofGreenPath(previous, greenPathRef) -> sprintf "GreenPath(%s|green_ref=%u)" (terminalFlowQapDiagnosticProjectionText previous) greenPathRef
            | TerminalFlowQapProofOwnerLedger(previous, ownerCertificateRef) -> sprintf "OwnerLedger(%s|owner_ref=%u)" (terminalFlowQapDiagnosticProjectionText previous) ownerCertificateRef
            | TerminalFlowQapProofWorkDagTail(previous, workDagProofRef) -> sprintf "WorkDagTail(%s|proof_ref=%u)" (terminalFlowQapDiagnosticProjectionText previous) workDagProofRef
            | TerminalFlowQapProofScc(previous, certificateRef, generationRef) -> FastRuntimeFormat.format "Scc(%s|certificate_ref=%u|generation_ref=%u)" [| box (terminalFlowQapDiagnosticProjectionText previous); box certificateRef; box generationRef |]
            | TerminalFlowQapProofResidualClose(previous, closeRef) -> sprintf "ResidualClose(%s|close_ref=%u)" (terminalFlowQapDiagnosticProjectionText previous) closeRef
            | TerminalFlowQapProofApplied(previous, transactionRef, exactOnceRef) -> FastRuntimeFormat.format "Applied(%s|transaction_ref=%u|exact_once_ref=%u)" [| box (terminalFlowQapDiagnosticProjectionText previous); box transactionRef; box exactOnceRef |]
            | TerminalFlowQapProofOwnerDebtClosedWorld(previous, decisionRef, closeReceiptRef) -> FastRuntimeFormat.format "OwnerDebtClosedWorld(%s|decision_ref=%u|close_receipt_ref=%u)" [| box (terminalFlowQapDiagnosticProjectionText previous); box decisionRef; box closeReceiptRef |]

        let rec private terminalFlowQapDiagnosticProjectionDepth = function
            | TerminalFlowQapProofSeed _ -> 1
            | TerminalFlowQapProofRoot(previous, _)
            | TerminalFlowQapProofProgress(previous, _)
            | TerminalFlowQapProofPending(previous, _)
            | TerminalFlowQapProofFairness(previous, _)
            | TerminalFlowQapProofRecovery(previous, _)
            | TerminalFlowQapProofGreenPath(previous, _)
            | TerminalFlowQapProofOwnerLedger(previous, _)
            | TerminalFlowQapProofWorkDagTail(previous, _)
            | TerminalFlowQapProofResidualClose(previous, _)
            | TerminalFlowQapProofApplied(previous, _, _)
            | TerminalFlowQapProofOwnerDebtClosedWorld(previous, _, _)
            | TerminalFlowQapProofScc(previous, _, _) -> 1 + terminalFlowQapDiagnosticProjectionDepth previous

        let private terminalFlowQapProofConstructionStageText = function
            | TerminalFlowQapProofStartConstruction -> "ProofStart"
            | TerminalFlowQapProofFairnessConstruction -> "Fairness"
            | TerminalFlowQapProofOwnerWorkDagConstruction -> "OwnerWorkDag"
            | TerminalFlowQapProofDispositionReceiptConstruction -> "DispositionReceipt"

        let private terminalFlowQapMissingEvidenceItemText = function
            | TerminalFlowQapProofMissingRoot -> "missing_root"
            | TerminalFlowQapProofMissingProgressEvidence -> "missing_progress_evidence"
            | TerminalFlowQapProofRejectedProgressEvidence evidenceRef -> sprintf "rejected_progress_evidence:%u" evidenceRef
            | TerminalFlowQapProofMissingPendingTerminal -> "missing_pending_terminal"
            | TerminalFlowQapProofFairnessNotReleased fairnessRef -> sprintf "fairness_not_released:%u" fairnessRef
            | TerminalFlowQapProofSchedulerLineageIncomplete missing ->
                "scheduler_lineage_incomplete:" + terminalFlowSchedulerLineageFieldPathText missing
            | TerminalFlowQapProofSchedulerReleaseRejected reason -> "scheduler_release_rejected:" + terminalFlowSchedulerReleaseRejectionText reason
            | TerminalFlowQapProofQueueRecoveryNotReady recoveryRef -> sprintf "queue_recovery_not_ready:%u" recoveryRef
            | TerminalFlowQapProofGreenPathNotReady -> "green_path_not_ready"
            | TerminalFlowQapProofOwnerLedgerNotClosed ownerRef -> sprintf "owner_ledger_not_closed:%u" ownerRef
            | TerminalFlowQapProofWorkDagTailNotClosed tailRef -> sprintf "workdag_tail_not_closed:%u" tailRef
            | TerminalFlowQapProofSccUnclosed missing -> "qap_scc_unclosed:" + terminalFlowQapSccMissingEvidencePathText missing
            | TerminalFlowQapProofResidualWorkDagBlocked tailRef -> sprintf "residual_workdag_blocked:%u" tailRef
            | TerminalFlowQapProofFinalizationNotEnqueued -> "finalization_not_enqueued"
            | TerminalFlowQapProofFinalizationTransactionMismatch(expected, observed) -> sprintf "finalization_transaction_mismatch:%u/%u" expected observed
            | TerminalFlowQapProofFinalizationExactOnceMismatch(expected, observed) -> sprintf "finalization_exact_once_mismatch:%u/%u" expected observed
            | TerminalFlowQapProofDispositionPlanRefZero -> "disposition_plan_ref_zero"
            | TerminalFlowQapProofDispositionTransactionRefZero -> "disposition_transaction_ref_zero"
            | TerminalFlowQapProofPendingLineageRejected proofRef -> sprintf "pending_lineage_rejected:%u" proofRef
            | TerminalFlowQapProofCompletionLineageMismatch(expected, observed) -> sprintf "completion_lineage_mismatch:%u/%u" expected observed
            | TerminalFlowQapProofConstructionContradiction(stage, evidenceRef) ->
                sprintf "construction_contradiction:%s:%u" (terminalFlowQapProofConstructionStageText stage) evidenceRef
            | TerminalFlowQapProofOwnerDebtCorridorRejected evidenceRef -> sprintf "owner_debt_corridor_rejected:%u" evidenceRef
            | TerminalFlowQapProofPostCommitNotApplied -> "post_commit_not_applied"

        let private terminalFlowQapMissingEvidenceSingleton missing =
            TerminalFlowQapMissingEvidenceSet(missing, [])

        let private terminalFlowQapMissingEvidenceSetOfList stage evidenceRef missing =
            match missing with
            | head :: tail -> TerminalFlowQapMissingEvidenceSet(head, tail)
            | [] ->
                terminalFlowQapMissingEvidenceSingleton (
                    TerminalFlowQapProofConstructionContradiction(stage, evidenceRef))

        let private terminalFlowQapMissingEvidenceToList (TerminalFlowQapMissingEvidenceSet(head, tail)) =
            head :: tail

        let private terminalFlowQapMissingEvidenceCount missing =
            missing |> terminalFlowQapMissingEvidenceToList |> List.length

        let private terminalFlowQapMissingEvidenceText missing =
            missing
            |> terminalFlowQapMissingEvidenceToList
            |> List.map terminalFlowQapMissingEvidenceItemText
            |> String.concat " -> "

        let private terminalFlowQapSccMissingEvidenceProgressCapableComponents = function
            | TerminalFlowQapSccMissingProgressCapableComponents componentRefs ->
                terminalFlowQapComponentRefPathToList componentRefs

        let rec private terminalFlowQapSccMissingEvidencePathProgressCapableComponents = function
            | TerminalFlowQapSccMissingEvidenceLast missing ->
                terminalFlowQapSccMissingEvidenceProgressCapableComponents missing
            | TerminalFlowQapSccMissingEvidenceMore(missing, rest) ->
                terminalFlowQapSccMissingEvidenceProgressCapableComponents missing
                @ terminalFlowQapSccMissingEvidencePathProgressCapableComponents rest

        let private terminalFlowQapMissingEvidenceProgressCapableComponents = function
            | TerminalFlowQapProofSccUnclosed missing ->
                terminalFlowQapSccMissingEvidencePathProgressCapableComponents missing
            | _ -> []

        let private terminalFlowQapProofCertificateKindText = function
            | TerminalFlowQapFairnessPreparedCertificate -> "FairnessPrepared"
            | TerminalFlowQapRecoveryPreparedCertificate -> "RecoveryPrepared"
            | TerminalFlowQapOwnerWorkDagPreparedCertificate -> "OwnerWorkDagPrepared"
            | TerminalFlowQapCompletedCertificate -> "Completed"
            | TerminalFlowQapAppliedCertificate -> "Applied"
            | TerminalFlowQapOwnerDebtCertificate -> "OwnerDebt"

        let private terminalFlowQapRatifiedOriginText = function
            | TerminalFlowQapFinalizationRatifiedOrigin(planRef, transactionRef, exactOnceRef) ->
                FastRuntimeFormat.format "Finalization(plan=%u|transaction=%u|exact_once=%u)" [| box planRef; box transactionRef; box exactOnceRef |]
            | TerminalFlowQapForceOwnerCloseRatifiedOrigin ratification ->
                "ForceOwnerClose(" + terminalFlowForceOwnerCloseRatificationText ratification + ")"

        let private terminalFlowQapStageEvidenceText = function
            | TerminalFlowQapFairnessPreparedStageEvidence evidence ->
                FastRuntimeFormat.format "FairnessPrepared(root=%u|progress=%u|pending=%u)" [| box evidence.rootReceiptRef; box evidence.progressSnapshotRef; box evidence.pendingTerminalRef |]
            | TerminalFlowQapFairnessReleasedStageEvidence evidence ->
                sprintf "FairnessReleased(release=%u|scheduler=%u)" evidence.releaseReceiptRef evidence.schedulerReleaseRef
            | TerminalFlowQapRecoveryPreparedStageEvidence evidence ->
                sprintf "Recovery(recovery=%u)" evidence.recoveryRef
            | TerminalFlowQapOwnerWorkDagPreparedStageEvidence evidence ->
                FastRuntimeFormat.format "OwnerWorkDag(green=%u|owner=%u|workdag=%u|scc=%u|scc_generation=%u|residual=%u)" [| box evidence.greenPathRef; box evidence.ownerCertificateRef; box evidence.workDagProofRef; box evidence.sccCertificateRef; box evidence.sccGenerationRef; box evidence.residualCloseRef |]
            | TerminalFlowQapAppliedStageEvidence evidence ->
                sprintf "Applied(transaction=%u|exact_once=%u)" evidence.finalizationTransactionRef evidence.finalizationExactOnceRef
            | TerminalFlowQapOwnerDebtRatifiedStageEvidence ratification ->
                "OwnerDebt(" + terminalFlowForceOwnerCloseRatificationText ratification + ")"

        let private terminalFlowQapPredecessorIdentity = function
            | TerminalFlowQapProofGenesisPredecessor origin ->
                terminalFlowMintedRefOf "terminal_qap_proof_genesis_ref" (terminalFlowQapRatifiedOriginText origin), 0
            | TerminalFlowQapProofFairnessPredecessor previous -> previous.proofRef, previous.depth
            | TerminalFlowQapProofRecoveryPredecessor previous -> previous.proofRef, previous.depth
            | TerminalFlowQapProofOwnerWorkDagPredecessor previous -> previous.proofRef, previous.depth
            | TerminalFlowQapProofCompletedPredecessor previous -> previous.proofRef, previous.depth
            | TerminalFlowQapProofForceOwnerClosePredecessor ratification ->
                terminalFlowIdentityRefDigest ratification.ratificationRef, 0

        let private terminalFlowQapProofCertificateIdentity origin predecessor evidence parentExactOnce kind =
            let kindText = terminalFlowQapProofCertificateKindText kind
            let originText = terminalFlowQapRatifiedOriginText origin
            let predecessorRef, predecessorDepth = terminalFlowQapPredecessorIdentity predecessor
            let evidenceText = terminalFlowQapStageEvidenceText evidence
            let proofRef =
                terminalFlowMintedRefOf
                    "terminal_qap_proof_certificate_ref"
                    (FastRuntimeFormat.format "%s|origin=%s|predecessor=%u|evidence=%s" [| box kindText; box originText; box predecessorRef; box evidenceText |])
            let exactOnceRef =
                terminalFlowMintedRefOf
                    "terminal_qap_proof_certificate_exact_once_ref"
                    (FastRuntimeFormat.format "%s:%u:%u:%u" [| box kindText; box proofRef; box predecessorRef; box parentExactOnce |])
            proofRef, exactOnceRef, predecessorDepth + 1

        let private terminalFlowQapCertificate
            kind
            origin
            predecessor
            evidence
            diagnosticProjection
            parentExactOnce
            : TerminalFlowQapProofCertificate<'Stage> =
            let proofRef, exactOnceRef, depth =
                terminalFlowQapProofCertificateIdentity origin predecessor evidence parentExactOnce kind
            { origin = origin
              predecessor = predecessor
              evidence = evidence
              diagnosticProjection = diagnosticProjection
              proofRef = proofRef
              exactOnceRef = exactOnceRef
              depth = depth }

        let private terminalFlowQapFairnessPreparedCertificateFor
            origin
            (evidence:TerminalFlowQapFairnessPreparedEvidence)
            tree
            parentExactOnce
            : TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitFairnessPreparedStage> =
            terminalFlowQapCertificate
                TerminalFlowQapFairnessPreparedCertificate
                origin
                (TerminalFlowQapProofGenesisPredecessor origin)
                (TerminalFlowQapFairnessPreparedStageEvidence evidence)
                tree
                parentExactOnce

        let private terminalFlowQapRecoveryPreparedCertificateFor
            (previous:TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitFairnessPreparedStage>)
            (evidence:TerminalFlowQapFairnessReleasedEvidence)
            tree
            : TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitRecoveryPreparedStage> =
            terminalFlowQapCertificate
                TerminalFlowQapRecoveryPreparedCertificate
                previous.origin
                (TerminalFlowQapProofFairnessPredecessor previous)
                (TerminalFlowQapFairnessReleasedStageEvidence evidence)
                tree
                previous.exactOnceRef

        let private terminalFlowQapOwnerWorkDagPreparedCertificateFor
            (previous:TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitRecoveryPreparedStage>)
            (evidence:TerminalFlowQapRecoveryPreparedEvidence)
            tree
            : TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitOwnerWorkDagPreparedStage> =
            terminalFlowQapCertificate
                TerminalFlowQapOwnerWorkDagPreparedCertificate
                previous.origin
                (TerminalFlowQapProofRecoveryPredecessor previous)
                (TerminalFlowQapRecoveryPreparedStageEvidence evidence)
                tree
                previous.exactOnceRef

        let private terminalFlowQapCompletedCertificateFor
            (previous:TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitOwnerWorkDagPreparedStage>)
            (evidence:TerminalFlowQapOwnerWorkDagPreparedEvidence)
            tree
            : TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitCompletedStage> =
            terminalFlowQapCertificate
                TerminalFlowQapCompletedCertificate
                previous.origin
                (TerminalFlowQapProofOwnerWorkDagPredecessor previous)
                (TerminalFlowQapOwnerWorkDagPreparedStageEvidence evidence)
                tree
                previous.exactOnceRef

        let private terminalFlowQapAppliedCertificateFor
            (previous:TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitCompletedStage>)
            (evidence:TerminalFlowQapAppliedEvidence)
            tree
            : TerminalFlowQapProofCertificate<TerminalFlowQapAppliedAuthorityStage> =
            terminalFlowQapCertificate
                TerminalFlowQapAppliedCertificate
                previous.origin
                (TerminalFlowQapProofCompletedPredecessor previous)
                (TerminalFlowQapAppliedStageEvidence evidence)
                tree
                previous.exactOnceRef

        let private terminalFlowQapOwnerDebtCertificateFor
            (ratification:TerminalFlowForceOwnerCloseRatification)
            tree
            parentExactOnce
            : TerminalFlowQapProofCertificate<TerminalFlowQapOwnerDebtAuthorityStage> =
            let origin = TerminalFlowQapForceOwnerCloseRatifiedOrigin ratification
            terminalFlowQapCertificate
                TerminalFlowQapOwnerDebtCertificate
                origin
                (TerminalFlowQapProofForceOwnerClosePredecessor ratification)
                (TerminalFlowQapOwnerDebtRatifiedStageEvidence ratification)
                tree
                parentExactOnce

        type TerminalFlowDomainCutoverFixtureFailure =
            | TerminalFlowFixtureLifecycleDidNotStartAtRoot of observed:TerminalFlowDispatchProtocolState
            | TerminalFlowFixtureLifecycleIdentityMissing of frameRef:uint32 * exactOnceRef:uint32
            | TerminalFlowFixtureLifecycleHadPredecessor
            | TerminalFlowFixtureFairnessCertificateInvalid of proofRef:uint32 * exactOnceRef:uint32 * depth:int
            | TerminalFlowFixtureAppliedCertificateInvalid of proofRef:uint32 * exactOnceRef:uint32 * depth:int

        type TerminalFlowDomainCutoverFixtureDecision =
            | TerminalFlowDomainCutoverFixturePassed
            | TerminalFlowDomainCutoverFixtureFailed of TerminalFlowDomainCutoverFixtureFailure

        // Source-only fixture: the cutover is valid only when the lifecycle starts as
        // one predecessor-free root frame and QAP certificates preserve stage-specific
        // identities while extending the same recursive proof tree.
        let terminalFlowDomainCutoverFixture () =
            let lifecycle = terminalFlowDispatchLifecycleInitial ()
            let frame = terminalFlowDispatchLifecycleFrame lifecycle
            let lifecycleStartsAtRoot =
                match frame.protocol with
                | TerminalFlowProtocolAwaitRoot -> true
                | _ -> false
            if not lifecycleStartsAtRoot then
                TerminalFlowDomainCutoverFixtureFailed(TerminalFlowFixtureLifecycleDidNotStartAtRoot frame.protocol)
            elif frame.frameRef = 0u || frame.exactOnceRef = 0u then
                TerminalFlowDomainCutoverFixtureFailed(TerminalFlowFixtureLifecycleIdentityMissing(frame.frameRef, frame.exactOnceRef))
            elif frame.previous.IsSome then
                TerminalFlowDomainCutoverFixtureFailed TerminalFlowFixtureLifecycleHadPredecessor
            else
                let seed = TerminalFlowQapProofSeed 101u
                let origin = TerminalFlowQapFinalizationRatifiedOrigin(101u, 102u, 103u)
                let fairnessEvidence =
                    { rootReceiptRef = 104u
                      progressSnapshotRef = 105u
                      pendingTerminalRef = 106u }
                let fairness =
                    terminalFlowQapFairnessPreparedCertificateFor
                        origin
                        fairnessEvidence
                        seed
                        103u
                if fairness.proofRef = 0u || fairness.exactOnceRef = 0u || fairness.depth <> 1 then
                    TerminalFlowDomainCutoverFixtureFailed(TerminalFlowFixtureFairnessCertificateInvalid(fairness.proofRef, fairness.exactOnceRef, fairness.depth))
                else
                    let recoveryEvidence = { releaseReceiptRef = 107u; schedulerReleaseRef = 108u }
                    let recoveryProjection = TerminalFlowQapProofFairness(fairness.diagnosticProjection, recoveryEvidence.releaseReceiptRef)
                    let recovery = terminalFlowQapRecoveryPreparedCertificateFor fairness recoveryEvidence recoveryProjection
                    let ownerPreparationEvidence = { recoveryRef = 109u }
                    let ownerPreparationProjection = TerminalFlowQapProofRecovery(recovery.diagnosticProjection, ownerPreparationEvidence.recoveryRef)
                    let ownerPreparation = terminalFlowQapOwnerWorkDagPreparedCertificateFor recovery ownerPreparationEvidence ownerPreparationProjection
                    let completionEvidence =
                        { greenPathRef = 110u
                          ownerCertificateRef = 111u
                          workDagProofRef = 112u
                          sccCertificateRef = 113u
                          sccGenerationRef = 114u
                          residualCloseRef = 115u }
                    let completedProjection = TerminalFlowQapProofResidualClose(ownerPreparation.diagnosticProjection, completionEvidence.residualCloseRef)
                    let completed = terminalFlowQapCompletedCertificateFor ownerPreparation completionEvidence completedProjection
                    let appliedEvidence = { finalizationTransactionRef = 116u; finalizationExactOnceRef = 117u }
                    let appliedProjection = TerminalFlowQapProofApplied(completed.diagnosticProjection, appliedEvidence.finalizationTransactionRef, appliedEvidence.finalizationExactOnceRef)
                    let applied = terminalFlowQapAppliedCertificateFor completed appliedEvidence appliedProjection
                    if applied.proofRef = 0u || applied.exactOnceRef = 0u || applied.depth <> 5 || applied.exactOnceRef = fairness.exactOnceRef then
                        TerminalFlowDomainCutoverFixtureFailed(TerminalFlowFixtureAppliedCertificateInvalid(applied.proofRef, applied.exactOnceRef, applied.depth))
                    else
                        TerminalFlowDomainCutoverFixturePassed

        let rec private terminalFlowQapDiagnosticProjectionSccCertificateRef = function
            | TerminalFlowQapProofScc(_, certificateRef, _) -> Some certificateRef
            | TerminalFlowQapProofRoot(previous, _)
            | TerminalFlowQapProofProgress(previous, _)
            | TerminalFlowQapProofPending(previous, _)
            | TerminalFlowQapProofFairness(previous, _)
            | TerminalFlowQapProofRecovery(previous, _)
            | TerminalFlowQapProofGreenPath(previous, _)
            | TerminalFlowQapProofOwnerLedger(previous, _)
            | TerminalFlowQapProofWorkDagTail(previous, _)
            | TerminalFlowQapProofResidualClose(previous, _)
            | TerminalFlowQapProofApplied(previous, _, _)
            | TerminalFlowQapProofOwnerDebtClosedWorld(previous, _, _) -> terminalFlowQapDiagnosticProjectionSccCertificateRef previous
            | TerminalFlowQapProofSeed _ -> None

        let rec private terminalFlowQapDiagnosticProjectionSccGenerationRef = function
            | TerminalFlowQapProofScc(_, _, generationRef) -> Some generationRef
            | TerminalFlowQapProofRoot(previous, _)
            | TerminalFlowQapProofProgress(previous, _)
            | TerminalFlowQapProofPending(previous, _)
            | TerminalFlowQapProofFairness(previous, _)
            | TerminalFlowQapProofRecovery(previous, _)
            | TerminalFlowQapProofGreenPath(previous, _)
            | TerminalFlowQapProofOwnerLedger(previous, _)
            | TerminalFlowQapProofWorkDagTail(previous, _)
            | TerminalFlowQapProofResidualClose(previous, _)
            | TerminalFlowQapProofApplied(previous, _, _)
            | TerminalFlowQapProofOwnerDebtClosedWorld(previous, _, _) -> terminalFlowQapDiagnosticProjectionSccGenerationRef previous
            | TerminalFlowQapProofSeed _ -> None

        let private terminalFlowQapPostCommitProofStart
            (planRef:uint32)
            (transactionRef:uint32)
            (rootReceiptRef:uint32)
            (progressAuthority:TerminalFlowReducerProgressAuthority)
            (pendingSlot:TerminalFlowPendingSlot)
            (exactOnceRef:uint32)
            : TerminalFlowQapProofBuildResult<TerminalFlowQapPostCommitFairnessPreparedStage> =
            let missingEvidence =
                [ if planRef = 0u then yield TerminalFlowQapProofDispositionPlanRefZero
                  if transactionRef = 0u then yield TerminalFlowQapProofDispositionTransactionRefZero
                  if rootReceiptRef = 0u then yield TerminalFlowQapProofMissingRoot
                  if Option.isNone progressAuthority.accepted then yield TerminalFlowQapProofMissingProgressEvidence
                  match progressAuthority.rejected with
                  | Some regression ->
                      yield TerminalFlowQapProofRejectedProgressEvidence(
                          terminalFlowMintedRefOf "terminal_progress_regression_ref" (terminalFlowProgressRegressionText regression))
                  | None -> ()
                  if terminalFlowPendingSlotIsAbsent pendingSlot then yield TerminalFlowQapProofMissingPendingTerminal ]
            if not (List.isEmpty missingEvidence) then
                Error (terminalFlowQapMissingEvidenceSetOfList TerminalFlowQapProofStartConstruction exactOnceRef missingEvidence)
            else
                match progressAuthority.accepted, pendingSlot with
                | Some evidence, TerminalFlowPendingSlotCandidate pending ->
                    let pendingRef = terminalFlowMintedRefOf "terminal_qap_proof_pending_ref" (FastRuntimeFormat.format "%s:%s:%u" [| box pending.terminalReceiptId; box pending.fillKey; box (terminalFlowPendingAdmissionRef pending.admission) |])
                    let tree =
                        TerminalFlowQapProofSeed planRef
                        |> fun previous -> TerminalFlowQapProofRoot(previous, rootReceiptRef)
                        |> fun previous -> TerminalFlowQapProofProgress(previous, terminalFlowIdentityRefDigest evidence.snapshotRef)
                        |> fun previous -> TerminalFlowQapProofPending(previous, pendingRef)
                    let origin = TerminalFlowQapFinalizationRatifiedOrigin(planRef, transactionRef, exactOnceRef)
                    let stageEvidence =
                        { rootReceiptRef = rootReceiptRef
                          progressSnapshotRef = terminalFlowIdentityRefDigest evidence.snapshotRef
                          pendingTerminalRef = pendingRef }
                    terminalFlowQapFairnessPreparedCertificateFor origin stageEvidence tree exactOnceRef |> Ok
                | _ ->
                    Error (
                        terminalFlowQapMissingEvidenceSingleton (
                            TerminalFlowQapProofConstructionContradiction(
                                TerminalFlowQapProofStartConstruction,
                                terminalFlowMintedRefOf "terminal_qap_proof_start_contradiction_ref" (FastRuntimeFormat.format "%u:%u:%u" [| box planRef; box transactionRef; box exactOnceRef |]))))

        let private terminalFlowQapPostCommitProofFairness
            (certificate:TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitFairnessPreparedStage>)
            (fairness:TerminalFlowReducerFairnessState)
            : TerminalFlowQapProofBuildResult<TerminalFlowQapPostCommitRecoveryPreparedStage> =
            match fairness.releaseReceipt, fairness.schedule.schedulerLease with
            | Some release, Some (TerminalFlowAdmissionSchedulerReleased physicalRelease) ->
                let evidence =
                    { releaseReceiptRef = terminalFlowIdentityRefDigest release.releaseRef
                      schedulerReleaseRef = terminalFlowIdentityRefDigest physicalRelease.physicalReleaseRef }
                let tree = TerminalFlowQapProofFairness(certificate.diagnosticProjection, evidence.releaseReceiptRef)
                terminalFlowQapRecoveryPreparedCertificateFor certificate evidence tree |> Ok
            | _, Some (TerminalFlowAdmissionSchedulerLineageIncomplete(_, _, missing)) ->
                Error (terminalFlowQapMissingEvidenceSingleton (TerminalFlowQapProofSchedulerLineageIncomplete missing))
            | _, Some (TerminalFlowAdmissionSchedulerRejected(_, _, reason)) ->
                Error (terminalFlowQapMissingEvidenceSingleton (TerminalFlowQapProofSchedulerReleaseRejected reason))
            | _ ->
                Error (terminalFlowQapMissingEvidenceSingleton (TerminalFlowQapProofFairnessNotReleased fairness.exactOnceRef))

        let private terminalFlowQapPostCommitProofRecovery
            (certificate:TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitRecoveryPreparedStage>)
            (queueRecovery:TerminalFlowReducerQueueRecoveryState)
            : TerminalFlowQapProofBuildResult<TerminalFlowQapPostCommitOwnerWorkDagPreparedStage> =
            match queueRecovery.decision with
            | TerminalFlowQueueRecoveryReadyForReducerSeal recovery ->
                let evidence = { recoveryRef = terminalFlowIdentityRefDigest recovery.recoveryRef }
                let tree = TerminalFlowQapProofRecovery(certificate.diagnosticProjection, evidence.recoveryRef)
                terminalFlowQapOwnerWorkDagPreparedCertificateFor certificate evidence tree |> Ok
            | _ -> Error (terminalFlowQapMissingEvidenceSingleton (TerminalFlowQapProofQueueRecoveryNotReady queueRecovery.exactOnceRef))

        let private terminalFlowQapPostCommitProofOwnerWorkDag
            (certificate:TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitOwnerWorkDagPreparedStage>)
            (ownerProducer:TerminalFlowOwnerWorkDagProducer)
            (ownerCertificate:TerminalFlowOwnerLedgerCloseCertificate<ProceduralResidualOwnerKind> option)
            (workDagProof:TerminalFlowWorkDagTailCloseProof<ProceduralResidualOwnerKind> option)
            (greenPath:TerminalFlowGreenPathLinearState option)
            (residualDecision:TerminalFlowResidualWorkDagCloseDecision<ProceduralResidualOwnerKind> option)
            (sccAssessment:TerminalFlowQapSccProofAssessment)
            : TerminalFlowQapProofBuildResult<TerminalFlowQapPostCommitCompletedStage> =
            let missingEvidence =
                [ match ownerProducer with
                  | TerminalFlowOwnerWorkDagProducerSealed _ -> ()
                  | _ ->
                      yield TerminalFlowQapProofOwnerLedgerNotClosed(
                          terminalFlowMintedRefOf "terminal_owner_workdag_post_commit_ref" (terminalFlowOwnerWorkDagProducerText ownerProducer))
                  if Option.isNone ownerCertificate then
                      yield TerminalFlowQapProofOwnerLedgerNotClosed(
                          terminalFlowMintedRefOf "terminal_owner_certificate_missing_ref" (string certificate.proofRef))
                  if Option.isNone workDagProof then
                      yield TerminalFlowQapProofWorkDagTailNotClosed certificate.proofRef
                  if Option.isNone greenPath then
                      yield TerminalFlowQapProofGreenPathNotReady
                  match residualDecision with
                  | Some (TerminalFlowResidualWorkDagForceCloseReady _) -> ()
                  | Some (TerminalFlowResidualWorkDagForceCloseBlocked(_, tailRef)) ->
                      yield TerminalFlowQapProofResidualWorkDagBlocked tailRef
                  | None ->
                      yield TerminalFlowQapProofResidualWorkDagBlocked certificate.proofRef
                  match sccAssessment with
                  | TerminalFlowQapSccProofCertified _ -> ()
                  | TerminalFlowQapSccProofUnclosed missing ->
                      yield TerminalFlowQapProofSccUnclosed missing ]
            if not (List.isEmpty missingEvidence) then
                Error (terminalFlowQapMissingEvidenceSetOfList TerminalFlowQapProofOwnerWorkDagConstruction certificate.proofRef missingEvidence)
            else
                match ownerCertificate, workDagProof, greenPath, residualDecision, sccAssessment with
                | Some owner,
                  Some workDag,
                  Some green,
                  Some (TerminalFlowResidualWorkDagForceCloseReady residual),
                  TerminalFlowQapSccProofCertified(certificateRef, generationRef) ->
                    let workDagProofRef = uint32 (terminalFlowOwnerLedgerProtocolIdValue workDag.proofRef)
                    let stageEvidence =
                        { greenPathRef = terminalFlowGreenPathReceiptRef green
                          ownerCertificateRef = owner.certificateRef
                          workDagProofRef = workDagProofRef
                          sccCertificateRef = certificateRef
                          sccGenerationRef = generationRef
                          residualCloseRef = residual.receiptRef }
                    let tree =
                        certificate.diagnosticProjection
                        |> fun previous -> TerminalFlowQapProofGreenPath(previous, stageEvidence.greenPathRef)
                        |> fun previous -> TerminalFlowQapProofOwnerLedger(previous, stageEvidence.ownerCertificateRef)
                        |> fun previous -> TerminalFlowQapProofWorkDagTail(previous, stageEvidence.workDagProofRef)
                        |> fun previous -> TerminalFlowQapProofScc(previous, stageEvidence.sccCertificateRef, stageEvidence.sccGenerationRef)
                        |> fun previous -> TerminalFlowQapProofResidualClose(previous, stageEvidence.residualCloseRef)
                    terminalFlowQapCompletedCertificateFor certificate stageEvidence tree |> Ok
                | _ ->
                    Error (
                        terminalFlowQapMissingEvidenceSingleton (
                            TerminalFlowQapProofConstructionContradiction(
                                TerminalFlowQapProofOwnerWorkDagConstruction,
                                terminalFlowMintedRefOf "terminal_qap_proof_owner_workdag_contradiction_ref" (string certificate.proofRef))))

        // A completed certificate is already a constructive witness. Applying an
        // enqueued finalization is therefore a total stage transition, not a
        // fallible guard. Missing evidence can only occur before Completed.
        let private terminalFlowQapPostCommitProofApplied
            (certificate:TerminalFlowQapProofCertificate<TerminalFlowQapPostCommitCompletedStage>)
            (finalization:TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationHandoffEnqueuedStage>)
            : TerminalFlowQapProofCertificate<TerminalFlowQapAppliedAuthorityStage> =
            let stageEvidence =
                { finalizationTransactionRef = finalization.transactionRef
                  finalizationExactOnceRef = finalization.exactOnceRef }
            let tree = TerminalFlowQapProofApplied(certificate.diagnosticProjection, stageEvidence.finalizationTransactionRef, stageEvidence.finalizationExactOnceRef)
            terminalFlowQapAppliedCertificateFor certificate stageEvidence tree

        type TerminalFlowQapPostCommitProjection = private {
            progressAuthority : TerminalFlowReducerProgressAuthority
            nativeEvalAuthority : NativeCutoverReducerEvalAuthority<ProceduralResidualOwnerKind>
            cicKernelCounters : NativeCutoverCicKernelCounters option
            outcomeInstallation : TerminalFlowOutcomeInstallation
            topologyGate : TerminalFlowTopologyGateState
            fairness : TerminalFlowReducerFairnessState
            queueRecovery : TerminalFlowReducerQueueRecoveryState
            greenPath : TerminalFlowGreenPathLinearState option
            ownerWorkDagProducer : TerminalFlowOwnerWorkDagProducer option
            ownerLedgerCloseCertificate : TerminalFlowOwnerLedgerCloseCertificate<ProceduralResidualOwnerKind> option
            workDagTailCloseProof : TerminalFlowWorkDagTailCloseProof<ProceduralResidualOwnerKind> option
            residualWorkDagCloseDecision : TerminalFlowResidualWorkDagCloseDecision<ProceduralResidualOwnerKind> option
        }

        // The envelope carries one certified recursive spine plus a clearly
        // observer-only projection. Optional runtime observations cannot
        // masquerade as proof authority merely by sharing the envelope record.
        type TerminalFlowQapPostCommitEnvelope<'Stage> = private {
            planRef : uint32
            transaction : TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationCommittedStage>
            rootReceiptRef : uint32
            pendingTerminal : TerminalFlowPendingSlot
            projection : TerminalFlowQapPostCommitProjection
            proof : TerminalFlowQapProofCertificate<'Stage>
            stageOrdinal : int
            exactOnceRef : uint32
        }

        // Applied proof does not merely relabel an observer candidate.  It installs
        // a new dispatch continuation whose authority is the completed recursive
        // proof spine.  The actual executor is installed after the native writer
        // corridor has been defined, keeping this type boundary free of forward
        // references while still making a missing installation fail closed.
        type TerminalFlowAppliedDispatchPlan = private {
            planRef : uint32
            transactionRef : uint32
            proofRef : uint32
            proofExactOnceRef : uint32
            writerLeaseRef : uint32
            exactOnceWakerEdgeRef : uint32
        }

        type TerminalFlowAppliedDispatchExecutor =
            TerminalFlowAppliedDispatchPlan
                -> TerminalFlowGlobalPendingTerminal
                -> TerminalFlowActorOutcomeJoin<TerminalFlowArmedOutcomeJoinedStage>
                -> Hopac.Job<TerminalFlowNativeHandoffId>

        let mutable private terminalFlowAppliedDispatchExecutor : TerminalFlowAppliedDispatchExecutor =
            fun _ _ _ -> job { return TerminalFlowNativeHandoffAwaitingResolvedRoot(CompilerKernelV2.OperationalReasonIdOps.create "applied_dispatch_executor_not_installed") }

        let private terminalFlowInstallAppliedDispatchExecutor executor =
            terminalFlowAppliedDispatchExecutor <- executor

        let private terminalFlowAppliedDispatchArmAndDispatchFor plan pending =
            fun stageToken -> terminalFlowAppliedDispatchExecutor plan pending stageToken

        let private terminalFlowQapPostCommitAppliedEnvelopeFor
            (envelope:TerminalFlowQapPostCommitEnvelope<TerminalFlowQapPostCommitCompletedStage>)
            (committedTransaction:TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationCommittedStage>)
            (enqueued:TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationHandoffEnqueuedStage>)
            : TerminalFlowQapPostCommitEnvelope<TerminalFlowQapAppliedAuthorityStage> =
            { planRef = envelope.planRef
              transaction = committedTransaction
              rootReceiptRef = envelope.rootReceiptRef
              pendingTerminal = envelope.pendingTerminal
              projection = envelope.projection
              proof = terminalFlowQapPostCommitProofApplied envelope.proof enqueued
              stageOrdinal = 5
              exactOnceRef =
                terminalFlowMintedRefOf
                    "terminal_qap_post_commit_applied_exact_once_ref"
                    (FastRuntimeFormat.format "%u:%u:%u" [| box envelope.planRef; box envelope.exactOnceRef; box enqueued.exactOnceRef |]) }

        let private terminalFlowQapPostCommitProofProjection
            (certificate:TerminalFlowQapProofCertificate<'Stage>) =
            terminalFlowQapDiagnosticProjectionText certificate.diagnosticProjection,
            "",
            (terminalFlowQapDiagnosticProjectionSccCertificateRef certificate.diagnosticProjection |> Option.defaultValue 0u),
            (terminalFlowQapDiagnosticProjectionSccGenerationRef certificate.diagnosticProjection |> Option.defaultValue 0u),
            certificate.proofRef,
            certificate.exactOnceRef

        let private terminalFlowQapMissingEvidenceProjection missingEvidence =
            let missingText = terminalFlowQapMissingEvidenceText missingEvidence
            "MissingEvidence",
            missingText,
            0u,
            0u,
            terminalFlowMintedRefOf "terminal_qap_missing_evidence_ref" missingText,
            0u

        type TerminalFlowQapPostCommitDisposition =
            | TerminalFlowQapPostCommitReady
            | TerminalFlowQapPostCommitAwaitEvidence of TerminalFlowQapMissingEvidenceSet
            | TerminalFlowQapPostCommitFatal of TerminalFlowQapMissingEvidenceSet

        // Destructive domain migration round : the residual QAP is now a
        // first-class work graph.  A fixpoint can only advance after every SCC
        // has either closed exact-once or produced typed stranded-producer
        // evidence.  Repeat counters and prose are observations, never closure.
        type TerminalFlowQapWorkNodeKind private () =
            static member InternedKindTag () = 0x160001u

        type TerminalFlowQapWorkNodeId =
            private
            | TerminalFlowQapWorkNodeId of CompilerIdentityKernel.InternedTextId<TerminalFlowQapWorkNodeKind>

        let private terminalFlowQapWorkNodeIdCreate value : TerminalFlowQapWorkNodeId =
            value
            |> CompilerIdentityKernel.InternedTextId.create<TerminalFlowQapWorkNodeKind>
            |> TerminalFlowQapWorkNodeId

        let private terminalFlowQapWorkNodeIdValue (TerminalFlowQapWorkNodeId value) =
            CompilerIdentityKernel.InternedTextId.text value

        type TerminalFlowQapWorkEdgeState =
            | TerminalFlowQapWorkEdgeOpen
            | TerminalFlowQapWorkEdgeConsumed of receiptRef:uint32 * reducerSequence:int64
            | TerminalFlowQapWorkEdgeRejected of reason:TerminalFlowQapRelationRejectionReasonId

        type TerminalFlowQapWorkNode = private {
            nodeId : TerminalFlowQapWorkNodeId
            sourceNode : TerminalFlowQapNodeId
            itemRef : TerminalFlowQapFixpointRef<TerminalFlowQapFixpointItemRefKind>
            repeatCount : int64
            repeatCap : int64
            materialDelta : int64
        }

        type TerminalFlowQapWorkEdge = private {
            fromNode : TerminalFlowQapWorkNodeId
            toNode : TerminalFlowQapWorkNodeId
            relationKind : TerminalFlowQapRelationKind
            state : TerminalFlowQapWorkEdgeState
        }

        type TerminalFlowQapWorkDag = private {
            dagRef : uint32
            qapRef : uint32
            generationRef : uint32
            materialEpoch : int64
            nodes : TerminalFlowQapWorkNode list
            edges : TerminalFlowQapWorkEdge list
        }

        type TerminalFlowQapSccClosureEvidence =
            | TerminalFlowQapSccClosedWorld of closeReceiptRef:uint32
            | TerminalFlowQapSccStrandedProducer of openEdges:TerminalFlowQapWorkEdge list * strandedRef:uint32
            | TerminalFlowQapSccProgressCapable of unstableNodes:TerminalFlowQapWorkNode list
            | TerminalFlowQapSccFinalGenerationSealed of stage:TerminalFlowQapGenerationStageId * finalizationRef:uint32

        type TerminalFlowQapSccComponent = private {
            componentRef : uint32
            members : TerminalFlowQapWorkNode list
            internalEdges : TerminalFlowQapWorkEdge list
            outgoingEdges : TerminalFlowQapWorkEdge list
            closure : TerminalFlowQapSccClosureEvidence
        }

        type TerminalFlowQapSccCertificate = private {
            certificateRef : uint32
            dag : TerminalFlowQapWorkDag
            components : TerminalFlowQapSccComponent list
            closedWorld : bool
            exactOnceRef : uint32
        }

        type TerminalFlowQapSccAssessment =
            | TerminalFlowQapSccCertified of TerminalFlowQapSccCertificate
            | TerminalFlowQapSccUnclosed of TerminalFlowQapSccMissingEvidencePath

        let private terminalFlowQapRelationConsumptionEdgeState = function
            | TerminalFlowQapRelationUnconsumed -> TerminalFlowQapWorkEdgeOpen
            | TerminalFlowQapRelationConsumedExactOnce(receiptRef, reducerSequence) ->
                TerminalFlowQapWorkEdgeConsumed(receiptRef, reducerSequence)
            | TerminalFlowQapRelationConsumptionRejected reason -> TerminalFlowQapWorkEdgeRejected reason

        let rec private terminalFlowQapRelationHeadNode = function
            | TerminalFlowQapRelationLeaf(node, _, _) -> node
            | TerminalFlowQapRelationParentChild(parent, _, _, _) -> parent
            | TerminalFlowQapRelationCycle(head, _, _, _) -> head

        let private terminalFlowQapWorkNodeFor (item:TerminalFlowQapFixpointItem) =
            let nodeText = terminalFlowQapNodeIdText item.nodeId
            { nodeId = terminalFlowQapWorkNodeIdCreate nodeText
              sourceNode = item.nodeId
              itemRef = item.itemRef
              repeatCount = item.repeatCount
              repeatCap = item.repeatCap
              materialDelta = item.materialDelta }

        let private terminalFlowQapWorkEdgeFor (item:TerminalFlowQapFixpointItem) =
            match item.relation with
            | TerminalFlowQapRelationLeaf _ -> None
            | TerminalFlowQapRelationParentChild(parent, relationKind, child, consumption) ->
                Some {
                    fromNode = terminalFlowQapWorkNodeIdCreate (terminalFlowQapNodeIdText parent)
                    toNode = terminalFlowQapWorkNodeIdCreate (terminalFlowQapNodeIdText (terminalFlowQapRelationHeadNode child))
                    relationKind = relationKind
                    state = terminalFlowQapRelationConsumptionEdgeState consumption
                }
            | TerminalFlowQapRelationCycle(head, relationKind, path, consumption) ->
                let target =
                    path
                    |> List.tryHead
                    |> Option.map terminalFlowQapRelationHeadNode
                    |> Option.defaultValue head
                Some {
                    fromNode = terminalFlowQapWorkNodeIdCreate (terminalFlowQapNodeIdText head)
                    toNode = terminalFlowQapWorkNodeIdCreate (terminalFlowQapNodeIdText target)
                    relationKind = relationKind
                    state = terminalFlowQapRelationConsumptionEdgeState consumption
                }

        let private terminalFlowQapResolutionParts = function
            | TerminalFlowQapMaterialProgressBox qap -> qap.fixpoint, qap.materialEpoch, terminalFlowQapResolutionBoxRef (TerminalFlowQapMaterialProgressBox qap)
            | TerminalFlowQapFullyDrainedBox(qap, proof) -> qap.fixpoint, qap.materialEpoch, uint32 (terminalFlowQapProtocolIdValue proof.proofRef)
            | TerminalFlowQapProvenDeadlockBox(qap, proof) -> qap.fixpoint, qap.materialEpoch, uint32 (terminalFlowQapProtocolIdValue proof.proofRef)

        let private terminalFlowQapWorkDagFor (generation:TerminalFlowQapGenerationAuthority) resolution =
            let fixpoint, materialEpoch, qapRef = terminalFlowQapResolutionParts resolution
            let generationRef = uint32 (terminalFlowQapGenerationValue generation.generation)
            let nodes = fixpoint.items |> List.map terminalFlowQapWorkNodeFor |> List.distinctBy (fun node -> node.nodeId)
            let edges = fixpoint.items |> List.choose terminalFlowQapWorkEdgeFor |> List.distinct
            let identity =
                nodes
                |> List.map (fun node -> terminalFlowQapWorkNodeIdValue node.nodeId)
                |> List.sort
                |> String.concat ";"
            { dagRef = terminalFlowMintedRefOf "terminal_qap_workdag_ref" (FastRuntimeFormat.format "%u:%u:%d:%s:%d" [| box qapRef; box generationRef; box materialEpoch; box identity; box edges.Length |])
              qapRef = qapRef
              generationRef = generationRef
              materialEpoch = materialEpoch
              nodes = nodes
              edges = edges }

        let private terminalFlowQapReachableNodes edges origin =
            let adjacency =
                edges
                |> List.groupBy (fun edge -> edge.fromNode)
                |> List.map (fun (node, outgoing) -> node, (outgoing |> List.map (fun edge -> edge.toNode)))
                |> Map.ofList
            let rec loop frontier visited =
                match frontier with
                | [] -> visited
                | node :: rest when Set.contains node visited -> loop rest visited
                | node :: rest ->
                    let next = Map.tryFind node adjacency |> Option.defaultValue []
                    loop (next @ rest) (Set.add node visited)
            loop [origin] Set.empty

        let private terminalFlowQapSccComponentsFor (dag:TerminalFlowQapWorkDag) =
            let nodeIds = dag.nodes |> List.map (fun node -> node.nodeId)
            let rec build remaining components =
                match remaining with
                | [] -> List.rev components
                | head :: _ ->
                    let headReach = terminalFlowQapReachableNodes dag.edges head
                    let members =
                        remaining
                        |> List.filter (fun candidate ->
                            Set.contains candidate headReach
                            && Set.contains head (terminalFlowQapReachableNodes dag.edges candidate))
                    let memberSet = Set.ofList members
                    let rest = remaining |> List.filter (fun node -> not (Set.contains node memberSet))
                    let memberNodes = dag.nodes |> List.filter (fun node -> Set.contains node.nodeId memberSet)
                    let internalEdges =
                        dag.edges
                        |> List.filter (fun edge -> Set.contains edge.fromNode memberSet && Set.contains edge.toNode memberSet)
                    let outgoingEdges =
                        dag.edges
                        |> List.filter (fun edge -> Set.contains edge.fromNode memberSet)
                    let stableNodes =
                        memberNodes
                        |> List.filter (fun node -> node.materialDelta = 0L && node.repeatCount >= node.repeatCap)
                    let componentIdentity =
                        members
                        |> List.map terminalFlowQapWorkNodeIdValue
                        |> List.sort
                        |> String.concat ";"
                    let componentRef = terminalFlowMintedRefOf "terminal_qap_scc_component_ref" (sprintf "%u:%s" dag.dagRef componentIdentity)
                    let closure =
                        if stableNodes.Length <> memberNodes.Length then
                            TerminalFlowQapSccProgressCapable(
                                memberNodes
                                |> List.filter (fun node -> node.materialDelta <> 0L || node.repeatCount < node.repeatCap))
                        else
                            let openEdges =
                                outgoingEdges
                                |> List.filter (fun edge ->
                                    match edge.state with
                                    | TerminalFlowQapWorkEdgeOpen -> true
                                    | _ -> false)
                            if List.isEmpty openEdges then
                                TerminalFlowQapSccClosedWorld(
                                    terminalFlowMintedRefOf "terminal_qap_scc_closed_world_ref" (sprintf "%u:%s" componentRef componentIdentity))
                            else
                                TerminalFlowQapSccStrandedProducer(
                                    openEdges,
                                    terminalFlowMintedRefOf "terminal_qap_scc_stranded_producer_ref" (sprintf "%u:%d" componentRef openEdges.Length))
                    let qapComponent = {
                        componentRef = componentRef
                        members = memberNodes
                        internalEdges = internalEdges
                        outgoingEdges = outgoingEdges
                        closure = closure
                    }
                    build rest (qapComponent :: components)
            build nodeIds []

        let private terminalFlowQapSccCertificateFor (dag:TerminalFlowQapWorkDag) components =
            let componentRefs = components |> List.map (fun qapComponent -> qapComponent.componentRef) |> List.sort
            let certificateRef =
                terminalFlowMintedRefOf
                    "terminal_qap_scc_certificate_ref"
                    (FastRuntimeFormat.format "%u:%u:%s" [| box dag.dagRef; box dag.generationRef; box (componentRefs |> List.map string |> String.concat ";") |])
            TerminalFlowQapSccCertified {
                certificateRef = certificateRef
                dag = dag
                components = components
                closedWorld = true
                exactOnceRef = terminalFlowMintedRefOf "terminal_qap_scc_certificate_exact_once_ref" (FastRuntimeFormat.format "%u:%u:%u" [| box certificateRef; box dag.qapRef; box dag.generationRef |])
            }

        let private terminalFlowQapSccSealFinalGeneration
            (generation:TerminalFlowQapGenerationAuthority)
            (qapComponent:TerminalFlowQapSccComponent) =
            match generation.stage, generation.finalizationReceiptRef, qapComponent.closure with
            | TerminalFlowQapGenerationDrained, Some finalizationRef, TerminalFlowQapSccProgressCapable _
            | TerminalFlowQapGenerationDeadlocked, Some finalizationRef, TerminalFlowQapSccProgressCapable _ ->
                { qapComponent with
                    closure = TerminalFlowQapSccFinalGenerationSealed(generation.stage, finalizationRef) }
            | _ -> qapComponent

        let private terminalFlowQapSccAssessmentFor generation resolution =
            let dag = terminalFlowQapWorkDagFor generation resolution
            if List.isEmpty dag.nodes then
                // Empty is the strongest closed-world certificate, not missing
                // evidence.  Fully drained generations must not manufacture one
                // residual node merely to pass the SCC gate.
                terminalFlowQapSccCertificateFor dag []
            else
                let components =
                    terminalFlowQapSccComponentsFor dag
                    |> List.map (terminalFlowQapSccSealFinalGeneration generation)
                let progressCapable =
                    components
                    |> List.choose (fun qapComponent ->
                        match qapComponent.closure with
                        | TerminalFlowQapSccProgressCapable _ -> Some qapComponent.componentRef
                        | _ -> None)
                match terminalFlowQapComponentRefPathOfList progressCapable with
                | None -> terminalFlowQapSccCertificateFor dag components
                | Some componentPath ->
                    TerminalFlowQapSccUnclosed(
                        TerminalFlowQapSccMissingEvidenceLast(
                            TerminalFlowQapSccMissingProgressCapableComponents componentPath))

        type TerminalFlowNonZeroRef<'Kind> = private | TerminalFlowNonZeroRef of uint32

        let private terminalFlowNonZeroRefResult
            (missing:TerminalFlowQapMissingEvidence)
            (value:uint32)
            : Result<TerminalFlowNonZeroRef<'Kind>, TerminalFlowQapMissingEvidence> =
            if value = 0u then Error missing else Ok (TerminalFlowNonZeroRef value)

        let private terminalFlowNonZeroRefValue (TerminalFlowNonZeroRef value) = value

