            match result with
            | Ok envelope ->
                envelope.planRef,
                envelope.transaction.transactionRef,
                envelope.stageOrdinal,
                0
            | Error missingEvidence ->
                0u, 0u, 0, terminalFlowQapMissingEvidenceCount missingEvidence

