        type TerminalFlowImmutableTerminalStage =
            | TerminalFlowTerminalSnapshotMaterial
            | TerminalFlowTerminalSnapshotQapAwaiting
            | TerminalFlowTerminalSnapshotQapProgressing
            | TerminalFlowTerminalSnapshotQapFinal
            | TerminalFlowTerminalSnapshotOutcomeArmed
            | TerminalFlowTerminalSnapshotOutcomeFilled
            | TerminalFlowTerminalSnapshotRunEnded
            | TerminalFlowTerminalSnapshotPhysicalExit
            | TerminalFlowTerminalSnapshotFailedClosed

        let private terminalFlowImmutableTerminalStageText = function
            | TerminalFlowTerminalSnapshotMaterial -> "Material"
            | TerminalFlowTerminalSnapshotQapAwaiting -> "QapAwaiting"
            | TerminalFlowTerminalSnapshotQapProgressing -> "QapProgressing"
            | TerminalFlowTerminalSnapshotQapFinal -> "QapFinal"
            | TerminalFlowTerminalSnapshotOutcomeArmed -> "OutcomeArmed"
            | TerminalFlowTerminalSnapshotOutcomeFilled -> "OutcomeFilled"
            | TerminalFlowTerminalSnapshotRunEnded -> "RunEnded"
            | TerminalFlowTerminalSnapshotPhysicalExit -> "PhysicalExit"
            | TerminalFlowTerminalSnapshotFailedClosed -> "FailedClosed"

        type TerminalFlowImmutableTerminalSnapshot = private {
            reducerRevision : int64
            operationalRevision : int64
            operationalGraphRef : CompilerIdentityKernel.ContentDigest
            operationalSnapshotRef : CompilerIdentityKernel.ContentDigest
            runtimeAuthorityRef : CompilerIdentityKernel.ContentDigest
            semanticEpoch : int64
            qapGenerationValue : uint64 option
            qapStage : TerminalFlowQapGenerationStageId option
            qapFinalization : TerminalFlowQapGenerationFinalizationId option
            actorRef : uint32
            terminalRef : uint32
            fillRef : uint32
            commitReceiptRef : uint32
            doneReceiptRef : uint32
            runEndReceiptRef : uint32
            physicalExitReceiptRef : uint32
            exitCode : int option
            terminalStage : TerminalFlowImmutableTerminalStage
            snapshotRef : CompilerIdentityKernel.ContentDigest
        }

        let private terminalFlowImmutableTerminalSnapshotFor (state:TerminalFlowGlobalReducerState) =
            let operational = terminalFlowOperationalAuthoritySnapshotNow ()
            let operationalRevision =
                CompilerKernelV2.OperationalAuthoritySnapshotOps.graphRevision operational
            let operationalGraphRef =
                CompilerKernelV2.OperationalAuthoritySnapshotOps.graphRef operational
            let operationalSnapshotRef =
                CompilerKernelV2.OperationalAuthoritySnapshotOps.snapshotRef operational
            let runtimeAuthorityRef =
                CompilerKernelV2.OperationalAuthoritySnapshotOps.runtimeAuthorityRef operational
            let semanticEpoch =
                CompilerKernelV2.OperationalAuthoritySnapshotOps.semanticEpoch operational
            let qapGeneration, qapStage, qapFinalization =
                match state.qapOutcomeActorAuthority.qapGeneration with
                | None -> None, None, None
                | Some generation ->
                    Some (terminalFlowQapGenerationValue generation.generation),
                    Some generation.stage,
                    generation.finalization
            let actorRef, actorTerminalRef, actorFillRef =
                terminalFlowReducerActorCoordinates state.qapOutcomeActorAuthority.actor
            let sealedChain =
                match state.reducerTerminalSeal with
                | TerminalFlowReducerTerminalSealPhysicalExitSelected chain
                | TerminalFlowReducerTerminalSealFailClosedSelected chain -> Some chain
                | TerminalFlowReducerTerminalSealAwaitStageToken -> None
            let terminalRef, fillRef =
                if actorTerminalRef <> 0u && actorFillRef <> 0u then
                    actorTerminalRef, actorFillRef
                else
                    match sealedChain with
                    | Some chain when chain.commit.terminalRef <> 0u && chain.commit.fillRef <> 0u ->
                        chain.commit.terminalRef, chain.commit.fillRef
                    | _ -> actorTerminalRef, actorFillRef
            let commitReceiptRef, doneReceiptRef, runEndReceiptRef, physicalExitReceiptRef, exitCode =
                match sealedChain with
                | None -> 0u, 0u, 0u, 0u, None
                | Some chain ->
                    chain.commit.receiptRef,
                    chain.doneReceipt.receiptRef,
                    chain.runEnd.receiptRef,
                    chain.physicalExit.receiptRef,
                    Some chain.exitCode
            let stage =
                match state.reducerTerminalSeal with
                | TerminalFlowReducerTerminalSealFailClosedSelected _ ->
                    TerminalFlowTerminalSnapshotFailedClosed
                | TerminalFlowReducerTerminalSealPhysicalExitSelected _ ->
                    TerminalFlowTerminalSnapshotPhysicalExit
                | TerminalFlowReducerTerminalSealAwaitStageToken ->
                    match state.typedTotalOrder with
                    | TerminalFlowTotalOrderRejected _ ->
                        TerminalFlowTerminalSnapshotFailedClosed
                    | TerminalFlowTotalOrderPhysicalExit _ ->
                        TerminalFlowTerminalSnapshotPhysicalExit
                    | TerminalFlowTotalOrderRunEnded _ ->
                        TerminalFlowTerminalSnapshotRunEnded
                    | TerminalFlowTotalOrderDone _
                    | TerminalFlowTotalOrderCommitted _
                    | TerminalFlowTotalOrderFilled _ ->
                        TerminalFlowTerminalSnapshotOutcomeFilled
                    | TerminalFlowTotalOrderDispatched _
                    | TerminalFlowTotalOrderAwaitDispatch _ ->
                        match state.qapOutcomeActorAuthority.actor with
                        | TerminalFlowReducerActorFilled _
                        | TerminalFlowReducerActorSealed _
                        | TerminalFlowReducerActorFailedClosed _ ->
                            TerminalFlowTerminalSnapshotOutcomeFilled
                        | TerminalFlowReducerActorArmed _ ->
                            TerminalFlowTerminalSnapshotOutcomeArmed
                        | TerminalFlowReducerActorVacant _ ->
                            match qapStage with
                            | Some TerminalFlowQapGenerationDrained
                            | Some TerminalFlowQapGenerationDeadlocked ->
                                TerminalFlowTerminalSnapshotQapFinal
                            | Some TerminalFlowQapGenerationProgressing ->
                                TerminalFlowTerminalSnapshotQapProgressing
                            | Some TerminalFlowQapGenerationAwaiting ->
                                TerminalFlowTerminalSnapshotQapAwaiting
                            | None ->
                                TerminalFlowTerminalSnapshotMaterial
            let snapshotRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "terminal-immutable-snapshot"
                    (string state.revision
                     + "|operational=" + CompilerIdentityKernel.ContentDigest.text operationalSnapshotRef
                     + "|runtime_authority=" + CompilerIdentityKernel.ContentDigest.text runtimeAuthorityRef
                     + "|qap_generation=" + (qapGeneration |> Option.map string |> Option.defaultValue "none")
                     + "|qap_stage=" + (qapStage |> Option.map terminalFlowQapGenerationStageText |> Option.defaultValue "none")
                     + "|actor=" + string actorRef
                     + "|terminal=" + string terminalRef
                     + "|fill=" + string fillRef
                     + "|commit=" + string commitReceiptRef
                     + "|done=" + string doneReceiptRef
                     + "|run_end=" + string runEndReceiptRef
                     + "|physical_exit=" + string physicalExitReceiptRef
                     + "|stage=" + terminalFlowImmutableTerminalStageText stage)
            { reducerRevision = state.revision
              operationalRevision = operationalRevision
              operationalGraphRef = operationalGraphRef
              operationalSnapshotRef = operationalSnapshotRef
              runtimeAuthorityRef = runtimeAuthorityRef
              semanticEpoch = semanticEpoch
              qapGenerationValue = qapGeneration
              qapStage = qapStage
              qapFinalization = qapFinalization
              actorRef = actorRef
              terminalRef = terminalRef
              fillRef = fillRef
              commitReceiptRef = commitReceiptRef
              doneReceiptRef = doneReceiptRef
              runEndReceiptRef = runEndReceiptRef
              physicalExitReceiptRef = physicalExitReceiptRef
              exitCode = exitCode
              terminalStage = stage
              snapshotRef = snapshotRef }

        let private terminalFlowQapFinalizationTransactionPreparedFor
            (sourceEventRef:uint32)
            (stateRevisionBefore:int64)
            (stateRevisionAfter:int64)
            (generation:TerminalFlowQapGenerationAuthority)
            (proofRef:uint32)
            (resolution:TerminalFlowQapResolutionBox)
            (outcome:TerminalFlowReducerOutcomeAuthorityId)
            (dispatchDecision:TerminalFlowQapFinalOutcomeDispatchDecision)
            : TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationPreparedStage> =
            let handoff = terminalFlowFinalOutcomeHandoffFor outcome
            let outcomeRef =
                match outcome with
                | TerminalFlowReducerOutcomeAwaitingQap -> 0u
                | TerminalFlowReducerOutcomeProvisional value -> value.terminalRef
                | TerminalFlowReducerOutcomeFinalDrained value -> value.terminalRef
                | TerminalFlowReducerOutcomeFinalDeadlocked value -> value.terminalRef
            let transactionRef =
                terminalFlowMintedRefOf
                    "terminal_qap_finalization_transaction_ref"
                    (FastRuntimeFormat.format "%u:%d:%u:%u:%u:%s" [| box sourceEventRef; box (terminalFlowQapGenerationValue generation.generation); box proofRef; box (terminalFlowQapResolutionBoxRef resolution); box outcomeRef; box (terminalFlowQapFinalOutcomeDispatchDecisionText dispatchDecision) |])
            let exactOnceRef =
                terminalFlowMintedRefOf
                    "terminal_qap_finalization_transaction_exact_once_ref"
                    (FastRuntimeFormat.format "%u:%u:%u:%d:%d" [| box transactionRef; box sourceEventRef; box (terminalFlowQapResolutionBoxRef resolution); box stateRevisionBefore; box stateRevisionAfter |])
            { transactionRef = transactionRef
              sourceEventRef = sourceEventRef
              generation = generation
              proofRef = proofRef
              resolution = resolution
              outcome = outcome
              handoff = handoff
              dispatchDecision = dispatchDecision
              stateRevisionBefore = stateRevisionBefore
              stateRevisionAfter = stateRevisionAfter
              exactOnceRef = exactOnceRef }

        let private terminalFlowQapFinalizationTransactionCommit
            (transaction:TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationPreparedStage>)
            : TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationCommittedStage> =
            { transactionRef = transaction.transactionRef
              sourceEventRef = transaction.sourceEventRef
              generation = transaction.generation
              proofRef = transaction.proofRef
              resolution = transaction.resolution
              outcome = transaction.outcome
              handoff = transaction.handoff
              dispatchDecision = transaction.dispatchDecision
              stateRevisionBefore = transaction.stateRevisionBefore
              stateRevisionAfter = transaction.stateRevisionAfter
              exactOnceRef = transaction.exactOnceRef }

        let private terminalFlowQapFinalizationTransactionMarkHandoffEnqueued
            (transaction:TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationCommittedStage>)
            : TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationHandoffEnqueuedStage> =
            { transactionRef = transaction.transactionRef
              sourceEventRef = transaction.sourceEventRef
              generation = transaction.generation
              proofRef = transaction.proofRef
              resolution = transaction.resolution
              outcome = transaction.outcome
              handoff = transaction.handoff
              dispatchDecision = transaction.dispatchDecision
              stateRevisionBefore = transaction.stateRevisionBefore
              stateRevisionAfter = transaction.stateRevisionAfter
              exactOnceRef = transaction.exactOnceRef }

        let private terminalFlowProtocolRootLineageFor (rootReceiptRef:TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>) =
            { rootRef = terminalFlowIdentityRefDigest rootReceiptRef }

        let private terminalFlowProtocolOutcomeLineageFor
            (rootReceiptRef:TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind>)
            (terminalReceiptRef:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>)
            (fillKey:TerminalFlowFillKeyId) =
            { root = terminalFlowProtocolRootLineageFor rootReceiptRef
              terminalRef = terminalFlowIdentityRefDigest terminalReceiptRef
              fillRef = TerminalFlowFillKeyId.digest fillKey }

        let private terminalFlowProtocolInstalledLineageForState
            (kernel:TerminalFlowKernelState)
            (outcomeInstallation:TerminalFlowOutcomeInstallation) =
            let lineageFor
                (admission:TerminalFlowOutcomeAdmission)
                (installationRef:TerminalFlowIdentityRef<TerminalFlowOutcomeInstallationRefKind>)
                rootReceiptId
                (terminalReceiptId:TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>)
                (fillKey:TerminalFlowFillKeyId) =
                if admission.terminalReceiptRef = terminalReceiptId
                   && admission.fillKey = fillKey then
                    Some {
                        outcome = terminalFlowProtocolOutcomeLineageFor rootReceiptId terminalReceiptId fillKey
                        installationRef = terminalFlowIdentityRefDigest installationRef
                        admissionIdentityRef = terminalFlowAdmissionIdentityRef admission.identity
                    }
                else None
            match outcomeInstallation, kernel.root, kernel.outcome with
            | TerminalFlowOutcomeInstalled(admission, installationRef, _, _),
              KernelRootResolved(rootReceiptId, _, _),
              KernelOutcomeSealed(terminalReceiptId, fillKey) ->
                lineageFor admission installationRef rootReceiptId terminalReceiptId fillKey
            | TerminalFlowOutcomeConsumeEnqueued(admission, installationRef, _, _, _),
              KernelRootResolved(rootReceiptId, _, _),
              KernelOutcomeSealed(terminalReceiptId, fillKey) ->
                lineageFor admission installationRef rootReceiptId terminalReceiptId fillKey
            | _ -> None

        let private terminalFlowProtocolInstalledLineageForConstitution
            (constitution:TerminalFlowDispatchConstitution<TerminalFlowDispatchConstitutionReadyStage>)
            : TerminalFlowProtocolInstalledLineage =
            { outcome =
                { root = { rootRef = constitution.rootRef }
                  terminalRef = constitution.terminalRef
                  fillRef = constitution.fillRef }
              installationRef = terminalFlowIdentityRefDigest constitution.installationRef
              admissionIdentityRef = constitution.admissionIdentityRef }

        let private terminalFlowProtocolInstalledLineageSame
            (left:TerminalFlowProtocolInstalledLineage)
            (right:TerminalFlowProtocolInstalledLineage) =
            left = right

        let private terminalFlowDispatchConstitutionSameMaterialLineage
            (left:TerminalFlowDispatchConstitution<TerminalFlowDispatchConstitutionReadyStage>)
            (right:TerminalFlowDispatchConstitution<TerminalFlowDispatchConstitutionReadyStage>) =
            terminalFlowProtocolInstalledLineageSame
                (terminalFlowProtocolInstalledLineageForConstitution left)
                (terminalFlowProtocolInstalledLineageForConstitution right)
            && left.pendingTerminalRef = right.pendingTerminalRef
            && left.credentialGraphClosureRef = right.credentialGraphClosureRef
            && left.greenPathDispatchReceipt.receiptRef = right.greenPathDispatchReceipt.receiptRef
            && left.totalOrderAwaitDispatch.receiptRef = right.totalOrderAwaitDispatch.receiptRef
            && left.proofDigest = right.proofDigest

        let private terminalFlowDispatchLifecycleCandidateProtocol
            (protocol:TerminalFlowDispatchProtocolState)
            (kernel:TerminalFlowKernelState)
            (outcomeInstallation:TerminalFlowOutcomeInstallation)
            (dispatchConstitution:TerminalFlowDispatchConstitutionState)
            (reducerTerminalSeal:TerminalFlowReducerTerminalSealAuthority) =
            match reducerTerminalSeal with
            | TerminalFlowReducerTerminalSealPhysicalExitSelected chain ->
                TerminalFlowProtocolExitAuthorized chain
            | TerminalFlowReducerTerminalSealFailClosedSelected chain ->
                TerminalFlowProtocolFailClosed chain
            | TerminalFlowReducerTerminalSealAwaitStageToken ->
                match protocol with
                | TerminalFlowProtocolAwaitRoot ->
                    match kernel.root with
                    | KernelRootResolved(rootReceiptId, _, _) ->
                        TerminalFlowProtocolAwaitOutcome(
                            terminalFlowProtocolRootLineageFor rootReceiptId)
                    | _ -> protocol

                | TerminalFlowProtocolAwaitOutcome _ ->
                    match kernel.root, kernel.outcome with
                    | KernelRootResolved(rootReceiptId, _, _),
                      KernelOutcomeSealed(terminalReceiptId, fillKey) ->
                        TerminalFlowProtocolAwaitInstallation(
                            terminalFlowProtocolOutcomeLineageFor rootReceiptId terminalReceiptId fillKey)
                    | _ -> protocol

                | TerminalFlowProtocolAwaitInstallation _ ->
                    match terminalFlowProtocolInstalledLineageForState kernel outcomeInstallation with
                    | Some installedLineage -> TerminalFlowProtocolOutcomeInstalled installedLineage
                    | None -> protocol

                | TerminalFlowProtocolOutcomeInstalled installedLineage ->
                    match terminalFlowProtocolInstalledLineageForState kernel outcomeInstallation with
                    | Some currentInstalledLineage
                        when not (terminalFlowProtocolInstalledLineageSame installedLineage currentInstalledLineage) ->
                        TerminalFlowProtocolOutcomeInstalled currentInstalledLineage
                    | _ ->
                        match dispatchConstitution with
                        | TerminalFlowDispatchConstitutionReady constitution
                            when terminalFlowProtocolInstalledLineageSame installedLineage (terminalFlowProtocolInstalledLineageForConstitution constitution) ->
                            TerminalFlowProtocolDispatchReady constitution
                        | TerminalFlowDispatchConstitutionIssued issuance
                            when terminalFlowProtocolInstalledLineageSame installedLineage (terminalFlowProtocolInstalledLineageForConstitution issuance.constitution) ->
                            TerminalFlowProtocolDispatchReady issuance.constitution
                        | TerminalFlowDispatchAffinePrepared transaction
                            when terminalFlowProtocolInstalledLineageSame installedLineage (terminalFlowProtocolInstalledLineageForConstitution transaction.authorization.issuance.constitution) ->
                            TerminalFlowProtocolDispatchReady transaction.authorization.issuance.constitution
                        | TerminalFlowDispatchAffineIssued transaction
                            when terminalFlowProtocolInstalledLineageSame installedLineage (terminalFlowProtocolInstalledLineageForConstitution transaction.authorization.issuance.constitution) ->
                            TerminalFlowProtocolDispatchReady transaction.authorization.issuance.constitution
                        | TerminalFlowDispatchAffineFilled transaction
                            when terminalFlowProtocolInstalledLineageSame installedLineage (terminalFlowProtocolInstalledLineageForConstitution transaction.authorization.issuance.constitution) ->
                            TerminalFlowProtocolDispatchReady transaction.authorization.issuance.constitution
                        | TerminalFlowDispatchConstitutionBlocked(blocker, revision, _)
                            when blocker <> TerminalFlowDispatchGreenPathMissing ->
                            TerminalFlowProtocolDispatchBlocked(installedLineage, blocker, revision)
                        | _ -> protocol

                | TerminalFlowProtocolDispatchBlocked(installedLineage, currentBlocker, currentRevision) ->
                    match terminalFlowProtocolInstalledLineageForState kernel outcomeInstallation with
                    | Some currentInstalledLineage
                        when not (terminalFlowProtocolInstalledLineageSame installedLineage currentInstalledLineage) ->
                        TerminalFlowProtocolDispatchBlocked(currentInstalledLineage, currentBlocker, currentRevision)
                    | _ ->
                        match dispatchConstitution with
                        | TerminalFlowDispatchConstitutionReady constitution
                            when terminalFlowProtocolInstalledLineageSame installedLineage (terminalFlowProtocolInstalledLineageForConstitution constitution) ->
                            TerminalFlowProtocolDispatchReady constitution
                        | TerminalFlowDispatchConstitutionBlocked(blocker, revision, _)
                            when blocker <> currentBlocker ->
                            TerminalFlowProtocolDispatchBlocked(installedLineage, blocker, revision)
                        | TerminalFlowDispatchConstitutionBlocked(_, revision, _)
                            when revision < currentRevision ->
                            protocol
                        | _ -> protocol

                | TerminalFlowProtocolDispatchReady previousConstitution ->
                    let previousInstalledLineage = terminalFlowProtocolInstalledLineageForConstitution previousConstitution
                    match terminalFlowProtocolInstalledLineageForState kernel outcomeInstallation with
                    | Some currentInstalledLineage
                        when not (terminalFlowProtocolInstalledLineageSame previousInstalledLineage currentInstalledLineage) ->
                        TerminalFlowProtocolOutcomeInstalled currentInstalledLineage
                    | _ ->
                        match dispatchConstitution with
                        | TerminalFlowDispatchConstitutionReady candidateConstitution
                            when not (terminalFlowDispatchConstitutionSameMaterialLineage previousConstitution candidateConstitution) ->
                            TerminalFlowProtocolDispatchReady candidateConstitution
                        | TerminalFlowDispatchConstitutionIssued issuance ->
                            TerminalFlowProtocolDispatchIssued issuance
                        | TerminalFlowDispatchAffinePrepared transaction ->
                            TerminalFlowProtocolDispatchIssued transaction.authorization.issuance
                        | TerminalFlowDispatchAffineIssued transaction ->
                            TerminalFlowProtocolDispatchIssued transaction.authorization.issuance
                        | TerminalFlowDispatchAffineFilled transaction ->
                            TerminalFlowProtocolDispatchIssued transaction.authorization.issuance
                        | _ -> protocol

                | TerminalFlowProtocolDispatchIssued committedIssuance ->
                    match dispatchConstitution with
                    | TerminalFlowDispatchConstitutionReady candidateConstitution
                        when not (terminalFlowDispatchConstitutionSameMaterialLineage committedIssuance.constitution candidateConstitution) ->
                        // Dispatch issuance remains rebasable until the first affine
                        // transaction is prepared. This is a typed supersession edge,
                        // not a generic rank regression.
                        TerminalFlowProtocolDispatchReady candidateConstitution
                    | TerminalFlowDispatchConstitutionIssued candidateIssuance
                        when candidateIssuance.issuanceRef <> committedIssuance.issuanceRef
                             && terminalFlowDispatchConstitutionLineageRef candidateIssuance.constitution = terminalFlowDispatchConstitutionLineageRef committedIssuance.constitution
                             && candidateIssuance.requestRef = committedIssuance.requestRef ->
                        TerminalFlowProtocolDispatchIssued candidateIssuance
                    | TerminalFlowDispatchAffinePrepared transaction ->
                        TerminalFlowProtocolAffinePrepared transaction
                    | _ -> protocol

                | TerminalFlowProtocolAffinePrepared _ ->
                    match dispatchConstitution with
                    | TerminalFlowDispatchAffineIssued transaction ->
                        TerminalFlowProtocolAffineIssued transaction
                    | _ -> protocol

                | TerminalFlowProtocolAffineIssued _ ->
                    match dispatchConstitution with
                    | TerminalFlowDispatchAffineFilled transaction ->
                        TerminalFlowProtocolAffineFilled transaction
                    | _ -> protocol

                | TerminalFlowProtocolAffineFilled _ ->
                    match dispatchConstitution with
                    | TerminalFlowDispatchAffineSealAuthorized transaction ->
                        TerminalFlowProtocolSealAuthorized transaction
                    | _ -> protocol

                | TerminalFlowProtocolSealAuthorized _
                | TerminalFlowProtocolExitAuthorized _
                | TerminalFlowProtocolFailClosed _ ->
                    protocol

        let private terminalFlowProtocolEdgeText = function
            | TerminalFlowProtocolRootResolvedEdge -> "RootResolved"
            | TerminalFlowProtocolOutcomeSealedEdge -> "OutcomeSealed"
            | TerminalFlowProtocolOutcomeInstalledEdge -> "OutcomeInstalled"
            | TerminalFlowProtocolOutcomeReinstalledBeforeIssueEdge -> "OutcomeReinstalledBeforeIssue"
            | TerminalFlowProtocolDispatchBlockerObservedEdge -> "DispatchBlockerObserved"
            | TerminalFlowProtocolDispatchBlockerChangedEdge -> "DispatchBlockerChanged"
            | TerminalFlowProtocolDispatchBlockedReconstitutedEdge -> "DispatchBlockedReconstitutedBeforeIssue"
            | TerminalFlowProtocolDispatchConstitutedEdge -> "DispatchConstituted"
            | TerminalFlowProtocolDispatchReconstitutedEdge -> "DispatchReconstitutedBeforeIssue"
            | TerminalFlowProtocolDispatchIssuedEdge -> "DispatchIssued"
            | TerminalFlowProtocolDispatchRedrivenEdge -> "DispatchRedriven"
            | TerminalFlowProtocolDispatchIssuanceSupersededBeforeAffineEdge -> "DispatchIssuanceSupersededBeforeAffine"
            | TerminalFlowProtocolAffinePreparedEdge -> "AffinePrepared"
            | TerminalFlowProtocolStageTokenIssuedEdge -> "StageTokenIssued"
            | TerminalFlowProtocolStageTokenFilledEdge -> "StageTokenFilled"
            | TerminalFlowProtocolSealAuthorizedEdge -> "SealAuthorized"
            | TerminalFlowProtocolExitAuthorizedEdge -> "ExitAuthorized"
            | TerminalFlowProtocolFailClosedEdge -> "FailClosed"

        let private terminalFlowProtocolPoisonText = function
            | TerminalFlowProtocolSkippedStagePoison(beforeRank, candidateRank) ->
                sprintf "SkippedStagePoison(%d->%d)" beforeRank candidateRank
            | TerminalFlowProtocolLineagePoison(edge, expectedRef, candidateRef) ->
                FastRuntimeFormat.format "LineagePoison(edge=%s|expected_ref=%u|candidate_ref=%u)" [| box (terminalFlowProtocolEdgeText edge); box expectedRef; box candidateRef |]
            | TerminalFlowProtocolTerminalConflictPoison(beforeRef, candidateRef) ->
                sprintf "TerminalConflictPoison(before_ref=%u|candidate_ref=%u)" beforeRef candidateRef

        let private terminalFlowProtocolPoisonRef poison =
            terminalFlowMintedRefOf
                "terminal_dispatch_protocol_poison_ref"
                (terminalFlowProtocolPoisonText poison)

        let private terminalFlowProtocolInstalledLineageRef (lineage:TerminalFlowProtocolInstalledLineage) =
            terminalFlowStableAuthorityRef (
                TerminalFlowProtocolInstalledLineageIdentity(
                    lineage.outcome.root.rootRef,
                    lineage.outcome.terminalRef,
                    lineage.outcome.fillRef,
                    lineage.installationRef,
                    lineage.admissionIdentityRef))

        let private terminalFlowProtocolConstitutionLineageRef
            (constitution:TerminalFlowDispatchConstitution<TerminalFlowDispatchConstitutionReadyStage>) =
            constitution
            |> terminalFlowProtocolInstalledLineageForConstitution
            |> terminalFlowProtocolInstalledLineageRef

        type private TerminalFlowProtocolEdgeDecision =
            | TerminalFlowProtocolEdgeAllowed of TerminalFlowProtocolEdge
            | TerminalFlowProtocolEdgeLineageRejected of TerminalFlowProtocolEdge * expectedRef:uint32 * candidateRef:uint32
            | TerminalFlowProtocolEdgeNotAllowed

        let private terminalFlowProtocolEdgeDecision (previous:TerminalFlowDispatchProtocolState) (candidate:TerminalFlowDispatchProtocolState) =
            let same expected candidateRef edge =
                if expected = candidateRef then
                    TerminalFlowProtocolEdgeAllowed edge
                else
                    TerminalFlowProtocolEdgeLineageRejected(edge, expected, candidateRef)
            match previous, candidate with
            | TerminalFlowProtocolAwaitRoot,
              TerminalFlowProtocolAwaitOutcome _ ->
                TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolRootResolvedEdge

            | TerminalFlowProtocolAwaitOutcome previousRoot,
              TerminalFlowProtocolAwaitInstallation candidateOutcome ->
                same previousRoot.rootRef candidateOutcome.root.rootRef TerminalFlowProtocolOutcomeSealedEdge

            | TerminalFlowProtocolAwaitInstallation previousOutcome,
              TerminalFlowProtocolOutcomeInstalled candidateInstalled ->
                let expected =
                    terminalFlowMintedRefOf
                        "terminal_dispatch_outcome_lineage_ref"
                        (FastRuntimeFormat.format "%u:%u:%u" [| box previousOutcome.root.rootRef; box previousOutcome.terminalRef; box previousOutcome.fillRef |])
                let candidateRef =
                    terminalFlowMintedRefOf
                        "terminal_dispatch_outcome_lineage_ref"
                        (FastRuntimeFormat.format "%u:%u:%u" [| box candidateInstalled.outcome.root.rootRef; box candidateInstalled.outcome.terminalRef; box candidateInstalled.outcome.fillRef |])
                same expected candidateRef TerminalFlowProtocolOutcomeInstalledEdge

            | TerminalFlowProtocolOutcomeInstalled previousInstalled,
              TerminalFlowProtocolOutcomeInstalled candidateInstalled
                when not (terminalFlowProtocolInstalledLineageSame previousInstalled candidateInstalled) ->
                TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolOutcomeReinstalledBeforeIssueEdge

            | TerminalFlowProtocolOutcomeInstalled previousInstalled,
              TerminalFlowProtocolDispatchBlocked(candidateInstalled, _, _) ->
                same
                    (terminalFlowProtocolInstalledLineageRef previousInstalled)
                    (terminalFlowProtocolInstalledLineageRef candidateInstalled)
                    TerminalFlowProtocolDispatchBlockerObservedEdge

            | TerminalFlowProtocolDispatchBlocked(previousInstalled, _, _),
              TerminalFlowProtocolDispatchBlocked(candidateInstalled, _, _) ->
                if terminalFlowProtocolInstalledLineageSame previousInstalled candidateInstalled then
                    TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolDispatchBlockerChangedEdge
                else
                    TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolDispatchBlockedReconstitutedEdge

            | TerminalFlowProtocolOutcomeInstalled previousInstalled,
              TerminalFlowProtocolDispatchReady constitution ->
                let candidateInstalled = terminalFlowProtocolInstalledLineageForConstitution constitution
                if terminalFlowProtocolInstalledLineageSame previousInstalled candidateInstalled then
                    TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolDispatchConstitutedEdge
                else
                    TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolDispatchReconstitutedEdge

            | TerminalFlowProtocolDispatchBlocked(previousInstalled, _, _),
              TerminalFlowProtocolDispatchReady constitution ->
                let candidateInstalled = terminalFlowProtocolInstalledLineageForConstitution constitution
                if terminalFlowProtocolInstalledLineageSame previousInstalled candidateInstalled then
                    TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolDispatchConstitutedEdge
                else
                    TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolDispatchReconstitutedEdge

            | TerminalFlowProtocolDispatchReady previousConstitution,
              TerminalFlowProtocolOutcomeInstalled candidateInstalled ->
                let previousInstalled = terminalFlowProtocolInstalledLineageForConstitution previousConstitution
                if terminalFlowProtocolInstalledLineageSame previousInstalled candidateInstalled then
                    TerminalFlowProtocolEdgeNotAllowed
                else
                    TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolOutcomeReinstalledBeforeIssueEdge

            | TerminalFlowProtocolDispatchReady previousConstitution,
              TerminalFlowProtocolDispatchReady candidateConstitution
                when not (terminalFlowDispatchConstitutionSameMaterialLineage previousConstitution candidateConstitution) ->
                // Reconstitution is legal only across pre-issue states. No request,
                // issuance or affine stage-token capability has crossed the ownership boundary.
                TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolDispatchReconstitutedEdge

            | TerminalFlowProtocolDispatchReady constitution,
              TerminalFlowProtocolDispatchIssued issuance ->
                let expectedLineageRef = terminalFlowDispatchConstitutionLineageRef constitution
                let issuedLineageRef = terminalFlowDispatchConstitutionLineageRef issuance.constitution
                if expectedLineageRef = issuedLineageRef
                   && issuedLineageRef = issuance.request.constitutionLineageRef then
                    TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolDispatchIssuedEdge
                else
                    TerminalFlowProtocolEdgeLineageRejected(
                        TerminalFlowProtocolDispatchIssuedEdge,
                        expectedLineageRef,
                        issuedLineageRef)

            | TerminalFlowProtocolDispatchIssued previousIssuance,
              TerminalFlowProtocolDispatchReady candidateConstitution
                when not (terminalFlowDispatchConstitutionSameMaterialLineage previousIssuance.constitution candidateConstitution) ->
                // An issued request may be superseded only before AffinePrepared.
                // The explicit edge makes the backwards rank transition legal while
                // preserving the ownership boundary for all later affine stages.
                TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolDispatchIssuanceSupersededBeforeAffineEdge

            | TerminalFlowProtocolDispatchIssued previousIssuance,
              TerminalFlowProtocolDispatchIssued candidateIssuance ->
                let previousLineageRef = terminalFlowDispatchConstitutionLineageRef previousIssuance.constitution
                let candidateLineageRef = terminalFlowDispatchConstitutionLineageRef candidateIssuance.constitution
                if previousLineageRef = candidateLineageRef
                   && previousIssuance.requestRef = candidateIssuance.requestRef
                   && previousIssuance.issuanceRef <> candidateIssuance.issuanceRef
                   && previousIssuance.exactOnceRef <> candidateIssuance.exactOnceRef then
                    TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolDispatchRedrivenEdge
                else
                    TerminalFlowProtocolEdgeLineageRejected(
                        TerminalFlowProtocolDispatchRedrivenEdge,
                        previousLineageRef,
                        candidateLineageRef)

            | TerminalFlowProtocolDispatchIssued issuance,
              TerminalFlowProtocolAffinePrepared transaction ->
                same issuance.issuanceRef transaction.authorization.issuance.issuanceRef TerminalFlowProtocolAffinePreparedEdge

            | TerminalFlowProtocolAffinePrepared previousTransaction,
              TerminalFlowProtocolAffineIssued candidateTransaction ->
                same previousTransaction.transactionRef candidateTransaction.transactionRef TerminalFlowProtocolStageTokenIssuedEdge

            | TerminalFlowProtocolAffineIssued previousTransaction,
              TerminalFlowProtocolAffineFilled candidateTransaction ->
                same previousTransaction.transactionRef candidateTransaction.transactionRef TerminalFlowProtocolStageTokenFilledEdge

            | TerminalFlowProtocolAffineFilled previousTransaction,
              TerminalFlowProtocolSealAuthorized candidateTransaction ->
                same previousTransaction.transactionRef candidateTransaction.transactionRef TerminalFlowProtocolSealAuthorizedEdge

            | TerminalFlowProtocolSealAuthorized transaction,
              TerminalFlowProtocolExitAuthorized chain ->
                same
                    transaction.authorization.issuance.constitution.fillRef
                    chain.physicalExit.fillRef
                    TerminalFlowProtocolExitAuthorizedEdge

            | _, TerminalFlowProtocolFailClosed chain when chain.exitCode <> 0 ->
                TerminalFlowProtocolEdgeAllowed TerminalFlowProtocolFailClosedEdge

            | _ -> TerminalFlowProtocolEdgeNotAllowed

        let private terminalFlowDispatchProtocolStateAdvanceText = function
            | TerminalFlowProtocolAdvanced(edge, beforeRank, afterRank) ->
                FastRuntimeFormat.format "Advanced(%s:%d->%d)" [| box (terminalFlowProtocolEdgeText edge); box beforeRank; box afterRank |]
            | TerminalFlowProtocolCoalesced rank -> sprintf "Coalesced(%d)" rank
            | TerminalFlowProtocolRegressionRejected(beforeRank, candidateRank) ->
                sprintf "RegressionRejected(%d->%d)" beforeRank candidateRank
            | TerminalFlowProtocolSkippedStageRejected(beforeRank, candidateRank) ->
                sprintf "SkippedStageRejected(%d->%d)" beforeRank candidateRank
            | TerminalFlowProtocolLineageDivergenceRejected(edge, expectedRef, candidateRef) ->
                FastRuntimeFormat.format "LineageDivergenceRejected(edge=%s|expected_ref=%u|candidate_ref=%u)" [| box (terminalFlowProtocolEdgeText edge); box expectedRef; box candidateRef |]
            | TerminalFlowProtocolPoisonedRejected(poisonRef, candidateRef) ->
                sprintf "PoisonedRejected(poison_ref=%u|candidate_ref=%u)" poisonRef candidateRef
            | TerminalFlowProtocolPoisonCoalesced(poisonRef, candidateRef) ->
                sprintf "PoisonCoalesced(poison_ref=%u|candidate_ref=%u)" poisonRef candidateRef
            | TerminalFlowProtocolPoisonFailClosedIssued(poisonRef, commandRef) ->
                sprintf "PoisonFailClosedIssued(poison_ref=%u|command_ref=%u)" poisonRef commandRef
            | TerminalFlowProtocolTerminalConflictRejected(beforeRef, candidateRef) ->
                sprintf "TerminalConflictRejected(before_ref=%u|candidate_ref=%u)" beforeRef candidateRef

        let private terminalFlowDispatchLifecycleAdvance
            sourceEventRef
            reducerRevision
            (kernel:TerminalFlowKernelState)
            (outcomeInstallation:TerminalFlowOutcomeInstallation)
            (reducerPossession:TerminalFlowReducerActorAuthorityId)
            (dispatchConstitution:TerminalFlowDispatchConstitutionState)
            (reducerTerminalSeal:TerminalFlowReducerTerminalSealAuthority)
            (lifecycle:TerminalFlowAnyDispatchLifecycle) =
            let rec converge remaining current =
                let currentFrame = terminalFlowDispatchLifecycleFrame current
                let previousProtocol = currentFrame.protocol
                let candidate =
                    terminalFlowDispatchLifecycleCandidateProtocol
                        previousProtocol
                        kernel
                        outcomeInstallation
                        dispatchConstitution
                        reducerTerminalSeal
                let beforeRank = terminalFlowDispatchProtocolStateRank previousProtocol
                let candidateRank = terminalFlowDispatchProtocolStateRank candidate
                let beforeRef = terminalFlowDispatchProtocolStateRef previousProtocol
                let candidateRef = terminalFlowDispatchProtocolStateRef candidate
                let candidateIsFailClosed =
                    match candidate with
                    | TerminalFlowProtocolFailClosed _ -> true
                    | _ -> false
                let verdict, committedProtocol =
                    match currentFrame.poison, candidateIsFailClosed with
                    | TerminalFlowProtocolPoisonLatched(_, poisonRef, _), false ->
                        if beforeRef = candidateRef then
                            TerminalFlowProtocolPoisonCoalesced(poisonRef, candidateRef),
                            previousProtocol
                        else
                            TerminalFlowProtocolPoisonedRejected(poisonRef, candidateRef),
                            previousProtocol
                    | _ when terminalFlowDispatchProtocolStateIsTerminal previousProtocol ->
                        if beforeRef = candidateRef then
                            TerminalFlowProtocolCoalesced beforeRank,
                            previousProtocol
                        else
                            TerminalFlowProtocolTerminalConflictRejected(beforeRef, candidateRef),
                            previousProtocol
                    | _ when beforeRef = candidateRef ->
                        TerminalFlowProtocolCoalesced beforeRank,
                        previousProtocol
                    | _ ->
                        match terminalFlowProtocolEdgeDecision previousProtocol candidate with
                        | TerminalFlowProtocolEdgeAllowed edge ->
                            TerminalFlowProtocolAdvanced(edge, beforeRank, candidateRank),
                            candidate
                        | TerminalFlowProtocolEdgeLineageRejected(edge, expectedRef, observedRef) ->
                            TerminalFlowProtocolLineageDivergenceRejected(edge, expectedRef, observedRef),
                            previousProtocol
                        | TerminalFlowProtocolEdgeNotAllowed when candidateRank < beforeRank ->
                            TerminalFlowProtocolRegressionRejected(beforeRank, candidateRank),
                            previousProtocol
                        | TerminalFlowProtocolEdgeNotAllowed when candidateRank > beforeRank ->
                            TerminalFlowProtocolSkippedStageRejected(beforeRank, candidateRank),
                            previousProtocol
                        | TerminalFlowProtocolEdgeNotAllowed ->
                            TerminalFlowProtocolTerminalConflictRejected(beforeRef, candidateRef),
                            previousProtocol
                match currentFrame.poison, candidateIsFailClosed with
                | TerminalFlowProtocolPoisonLatched _, false -> current
                | _ ->
                    let nextPoison =
                        match verdict with
                        | TerminalFlowProtocolSkippedStageRejected(beforeRank, afterRank) ->
                            let poison = TerminalFlowProtocolSkippedStagePoison(beforeRank, afterRank)
                            TerminalFlowProtocolPoisonLatched(poison, terminalFlowProtocolPoisonRef poison, reducerRevision)
                        | TerminalFlowProtocolLineageDivergenceRejected(edge, expectedRef, observedRef) ->
                            let poison = TerminalFlowProtocolLineagePoison(edge, expectedRef, observedRef)
                            TerminalFlowProtocolPoisonLatched(poison, terminalFlowProtocolPoisonRef poison, reducerRevision)
                        | TerminalFlowProtocolTerminalConflictRejected(previousRef, observedRef) ->
                            let poison = TerminalFlowProtocolTerminalConflictPoison(previousRef, observedRef)
                            TerminalFlowProtocolPoisonLatched(poison, terminalFlowProtocolPoisonRef poison, reducerRevision)
                        | _ -> currentFrame.poison
                    let nextRejectionCount =
                        match verdict with
                        | TerminalFlowProtocolAdvanced _
                        | TerminalFlowProtocolCoalesced _
                        | TerminalFlowProtocolPoisonCoalesced _ -> currentFrame.rejectionCount
                        | _ -> currentFrame.rejectionCount + 1L
                    let next =
                        terminalFlowDispatchLifecycleFrameFor
                            (Some current)
                            verdict
                            reducerRevision
                            sourceEventRef
                            kernel.actor
                            kernel.dispatch
                            reducerPossession
                            dispatchConstitution
                            nextPoison
                            currentFrame.poisonTerminalization
                            nextRejectionCount
                            committedProtocol
                    let nextFrame = terminalFlowDispatchLifecycleFrame next
                    if nextFrame.frameRef = currentFrame.frameRef then
                        current
                    else
                        match verdict with
                        | TerminalFlowProtocolAdvanced _ when remaining > 1 ->
                            converge (remaining - 1) next
                        | _ -> next
            converge 12 lifecycle

        let private terminalFlowDispatchLifecycleMarkPoisonFailClosedIssued reducerRevision commandRef lifecycle =
            let frame = terminalFlowDispatchLifecycleFrame lifecycle
            match frame.poison, frame.poisonTerminalization with
            | TerminalFlowProtocolPoisonLatched(_, poisonRef, _), TerminalFlowProtocolPoisonNotTerminalized ->
                terminalFlowDispatchLifecycleFrameFor
                    (Some lifecycle)
                    (TerminalFlowProtocolPoisonFailClosedIssued(poisonRef, commandRef))
                    reducerRevision
                    frame.sourceEventRef
                    frame.kernelActor
                    frame.kernelDispatch
                    frame.reducerPossession
                    frame.dispatchConstitution
                    frame.poison
                    (TerminalFlowProtocolPoisonFailClosedTerminalized(poisonRef, commandRef, reducerRevision))
                    frame.rejectionCount
                    frame.protocol
            | _ -> lifecycle

        // The parallel unified-authority fixture was deleted during the lifecycle
        // cutover.  Round 5 will add fixtures against the lifecycle constructor itself.

        let private terminalFlowReducerQapGenerationRef (authority:TerminalFlowReducerQapOutcomeActorAuthority) =
            match authority.qapGeneration with
            | None -> 0u
            | Some generationAuthority ->
                let (TerminalFlowQapGenerationId generationValue) = generationAuthority.generation
                uint32 (generationValue ^^^ (generationValue >>> 32))

        let private terminalFlowReducerSealCoordinates seal =
            match seal with
            | TerminalFlowReducerTerminalSealAwaitStageToken -> 0u, 0L, false, false, None
            | TerminalFlowReducerTerminalSealPhysicalExitSelected chain ->
                chain.physicalExit.receiptRef,
                chain.physicalExit.totalOrderIndex,
                true,
                chain.exitCode = 0,
                chain.failureRef
            | TerminalFlowReducerTerminalSealFailClosedSelected chain ->
                chain.physicalExit.receiptRef,
                chain.physicalExit.totalOrderIndex,
                true,
                false,
                chain.failureRef

        let private terminalFlowAuthoritativeProgressSnapshotFor
            nowMs
            (state:TerminalFlowGlobalReducerState)
            (evidence:TerminalFlowProgressEvidence) =
            let ledger = evidence.workLedger
            let semanticCost value =
                CompilerKernelV2.Measured.create<CompilerKernelV2.SemanticCostUnit> "terminalFlowAuthoritativeSemanticCost" (max 0L value)
            let nodeCount value =
                CompilerKernelV2.Measured.create<CompilerKernelV2.NodeCountUnit> "terminalFlowAuthoritativeNodeCount" (max 0L value)
            let workerCount value =
                CompilerKernelV2.Measured.create<CompilerKernelV2.WorkerCountUnit> "terminalFlowAuthoritativeWorkerCount" (max 0L value)
            let wallTime value =
                CompilerKernelV2.Measured.create<CompilerKernelV2.WallTimeUnit> "terminalFlowAuthoritativeWallTime" (max 0L value)
            let criticalCost value =
                CompilerKernelV2.Measured.create<CompilerKernelV2.CriticalPathCostUnit> "terminalFlowAuthoritativeCriticalPathCost" (max 0L value)
            let ledgerCompleted = semanticCost (ledger.completedCost + ledger.provenDeadCost)
            let bridgedSemanticFacts = semanticFactBridgeSnapshot ()
            let semanticAuthorityLedger = CompilerKernelV2.SemanticWorkLedgerAuthority.snapshot ()
            let semanticAuthorityAdmitted, semanticAuthorityReceipts =
                CompilerKernelV2.SemanticWorkLedgerAuthority.counts ()
            let semanticAuthorityProjection =
                CompilerKernelV2.SemanticWorkLedger.project
                    CompilerKernelV2.ProgressDenominatorClosed
                    semanticAuthorityLedger
            let semanticAuthorityOpenCount = max 0 (semanticAuthorityAdmitted - semanticAuthorityReceipts)
            let _, parsedAstSeedTotal = parsedAstStructuralSeedSnapshot ()
            let parsedAstStructuralFloor = semanticCost parsedAstSeedTotal
            let semanticFactCount =
                nodeCount ((max state.nativeEvalAuthority.semanticFactCount bridgedSemanticFacts.rootValueFactCount) + int64 semanticAuthorityReceipts)
            let semanticRetiredCost =
                CompilerKernelV2.Measured.add
                    (semanticCost (max state.nativeEvalAuthority.semanticRetiredCost bridgedSemanticFacts.rootValueRetiredCost))
                    semanticAuthorityProjection.completedCost
            let semanticCriticalPathRetiredCost =
                criticalCost
                    ((max state.nativeEvalAuthority.criticalPathRetiredCost bridgedSemanticFacts.rootValueCriticalPathRetiredCost)
                     + CompilerKernelV2.Measured.value semanticAuthorityProjection.completedCost)
            let cicWeightedRetiredCost = semanticCost state.cicKernelAuthority.retiredWeightedCost
            let completed =
                CompilerKernelV2.Measured.maxValue ledgerCompleted
                    (CompilerKernelV2.Measured.maxValue semanticRetiredCost cicWeightedRetiredCost)
            let discoveredAndOpen =
                CompilerKernelV2.Measured.maxValue
                    (semanticCost ledger.totalCost)
                    semanticAuthorityProjection.totalHigh
            let denominatorCost =
                CompilerKernelV2.Measured.maxValue completed
                    (CompilerKernelV2.Measured.maxValue parsedAstStructuralFloor discoveredAndOpen)
            // Basis points describe the whole compilation denominator, so the numerator must
            // have the same scope.  Semantic-only retirement remains available separately as
            // semanticProgressBp; using it against the whole-work denominator caused the 0.73%
            // terminal collapse despite 7651/7653 retired work.
            let bpNumeratorSource = TerminalFlowProgressNumeratorConservedCompletedMax
            let denominatorRevision =
                match state.authoritativeProgress with
                | None -> 1L
                | Some previous
                    when previous.denominatorCost <> denominatorCost
                         || previous.semanticEpoch <> evidence.semanticDigest.semanticEpoch ->
                    previous.denominatorRevision + 1L
                | Some previous -> previous.denominatorRevision
            let ratioBp (numerator:CompilerKernelV2.SemanticCost) (denominator:CompilerKernelV2.SemanticCost) =
                let denominatorValue = CompilerKernelV2.Measured.value denominator
                if denominatorValue <= 0L then CompilerKernelV2.BasisPoints.zero
                else
                    CompilerKernelV2.BasisPoints.create
                        (min 10000L ((CompilerKernelV2.Measured.value numerator * 10000L) / denominatorValue))
            let residualPenalty = semanticCost (ledger.blockedCost + ledger.residualCost)
            let denominatorLow = CompilerKernelV2.Measured.add denominatorCost residualPenalty
            let openCost = semanticCost (int64 semanticAuthorityOpenCount)
            let wholeProgressBp = ratioBp completed denominatorCost
            let highNumerator =
                CompilerKernelV2.Measured.minValue denominatorCost
                    (CompilerKernelV2.Measured.add completed openCost)
            let progressLowBp = ratioBp completed denominatorLow
            let semanticProgressBp = ratioBp semanticRetiredCost denominatorCost
            let exactClosedWorld = terminalFlowProgressEvidenceIsExactClosedWorld evidence
            let rawProgressMidBp =
                if exactClosedWorld then wholeProgressBp
                else CompilerKernelV2.BasisPoints.create (min 9999L (CompilerKernelV2.BasisPoints.value wholeProgressBp))
            // Display monotonicity is valid only while the denominator revision is unchanged.
            // New discovery may legitimately increase the denominator and lower progress; within one
            // revision, however, a backwards mid-point is projection jitter rather than new work.
            let progressMidBp, progressMidClamped =
                match state.authoritativeProgress with
                | Some previous when previous.denominatorRevision = denominatorRevision ->
                    let previousValue = CompilerKernelV2.BasisPoints.value previous.progressMidBp
                    let rawValue = CompilerKernelV2.BasisPoints.value rawProgressMidBp
                    if previousValue > rawValue then previous.progressMidBp, true
                    else rawProgressMidBp, false
                | _ -> rawProgressMidBp, false
            let rawProgressHighBp = ratioBp highNumerator denominatorCost
            let progressHighBp =
                CompilerKernelV2.BasisPoints.create
                    (max (CompilerKernelV2.BasisPoints.value rawProgressHighBp)
                         (CompilerKernelV2.BasisPoints.value progressMidBp))
            if progressMidClamped then
                DiagJson.emit (
                    FastRuntimeFormat.format
                        "{\"kind\":\"authoritative_progress_same_denominator_regression_clamped\",\"denominator_revision\":%d,\"raw_progress_mid_bp\":%d,\"published_progress_mid_bp\":%d,\"semantic_progress_bp\":%d,\"control_authority\":false,\"terminal_stage_authority\":false,\"authority\":\"display_monotonicity_only_same_denominator_revision\",\"next\":\"allow_regression_only_after_explicit_denominator_revision\"}"
                        [| box denominatorRevision; box (CompilerKernelV2.BasisPoints.value rawProgressMidBp); box (CompilerKernelV2.BasisPoints.value progressMidBp); box (CompilerKernelV2.BasisPoints.value semanticProgressBp) |])
            let sealRef, totalOrderIndex, terminalFinal, buildOkFinal, failureRef =
                terminalFlowReducerSealCoordinates state.reducerTerminalSeal
            // A reducer seal is structural authority, but progress is not final while
            // conserved work credit is still outstanding.  Keep those two facts distinct.
            let terminalProgressFinal = terminalFinal && exactClosedWorld
            let terminalSpineRank =
                state.dispatchLifecycle
                |> terminalFlowDispatchLifecycleProtocol
                |> terminalFlowDispatchProtocolStateRank
                |> int64
            let terminalSpineProgressBp =
                if terminalProgressFinal then CompilerKernelV2.BasisPoints.create 10000L
                else CompilerKernelV2.BasisPoints.create (min 9999L ((terminalSpineRank * 10000L) / 11L))
            let etaFresh =
                match state.criticalPathEtaObservedAtMs with
                | Some observedAtMs -> nowMs - observedAtMs <= 5000L
                | None -> false
            let terminalP50, terminalP90 =
                if terminalProgressFinal then Some (wallTime 0L), Some (wallTime 0L)
                elif etaFresh then
                    state.criticalPathEta |> Option.map (fun eta -> eta.terminalP50),
                    state.criticalPathEta |> Option.map (fun eta -> eta.terminalP90)
                else None, None
            let buildOkEta =
                if terminalProgressFinal && buildOkFinal then
                    TerminalFlowBuildOkEtaAvailable(wallTime 0L, wallTime 0L)
                elif terminalProgressFinal then
                    TerminalFlowBuildOkEtaUnavailable(
                        failureRef |> Option.defaultValue sealRef,
                        CompilerKernelV2.OperationalReasonIdOps.create "terminal_fail_closed")
                elif not etaFresh then
                    TerminalFlowBuildOkEtaUnavailable(
                        terminalFlowIdentityRefDigest evidence.snapshotRef,
                        CompilerKernelV2.OperationalReasonIdOps.create "stale_or_missing_critical_path_eta")
                else
                    match state.criticalPathEta with
                    | Some eta ->
                        match eta.buildOkP50, eta.buildOkP90, eta.unavailableReason with
                        | Some p50, Some p90, _ -> TerminalFlowBuildOkEtaAvailable(p50, p90)
                        | _, _, Some reason -> TerminalFlowBuildOkEtaUnavailable(eta.etaRef, reason)
                        | _ -> TerminalFlowBuildOkEtaUnavailable(eta.etaRef, CompilerKernelV2.OperationalReasonIdOps.create "build_ok_eta_unavailable")
                    | None ->
                        TerminalFlowBuildOkEtaUnavailable(
                            terminalFlowIdentityRefDigest evidence.snapshotRef,
                            CompilerKernelV2.OperationalReasonIdOps.create "critical_path_eta_missing")
            let semanticRemaining =
                CompilerKernelV2.Measured.subtractFloor denominatorCost semanticRetiredCost
            let criticalPath =
                CompilerKernelV2.WorkCriticalPathSnapshot.create
                    (criticalCost (CompilerKernelV2.Measured.value semanticRemaining))
                    terminalP50
                    terminalP90
                    (nodeCount (evidence.frontier.queueDepth + evidence.frontier.blocked))
                    (workerCount evidence.frontier.activeWorkers)
            let qapGenerationRef = terminalFlowReducerQapGenerationRef state.qapOutcomeActorAuthority
            let snapshotRef =
                terminalFlowMintedRefOf
                    "authoritative_progress_snapshot_ref"
                    (FastRuntimeFormat.format "%u:%d:%d:%d:%d:%u:%u" [|
                        box (terminalFlowIdentityRefDigest evidence.snapshotRef)
                        box state.revision
                        box denominatorRevision
                        box (CompilerKernelV2.Measured.value denominatorCost)
                        box evidence.semanticDigest.semanticEpoch
                        box qapGenerationRef
                        box sealRef |])
            { snapshotRef = snapshotRef
              sourceProgressSnapshotRef = terminalFlowIdentityRefDigest evidence.snapshotRef
              reducerSequence = state.revision
              denominatorRevision = denominatorRevision
              denominatorCost = denominatorCost
              semanticEpoch = evidence.semanticDigest.semanticEpoch
              observedAt = CompilerKernelV2.Measured.create<CompilerKernelV2.MonotonicTimeUnit> "authoritativeProgressObservedAt" nowMs
              validUntil = CompilerKernelV2.Measured.create<CompilerKernelV2.MonotonicTimeUnit> "authoritativeProgressValidUntil" (if terminalProgressFinal then System.Int64.MaxValue else nowMs + 5000L)
              freshnessAtCommit = if terminalProgressFinal then TerminalFlowProgressSnapshotFinal else TerminalFlowProgressSnapshotFresh
              bpNumeratorSource = bpNumeratorSource
              progressLowBp = progressLowBp
              progressMidBp = progressMidBp
              progressHighBp = progressHighBp
              semanticProgressBp = semanticProgressBp
              terminalSpineProgressBp = terminalSpineProgressBp
              terminalEtaP50 = terminalP50
              terminalEtaP90 = terminalP90
              criticalPath = criticalPath
              buildOkEta = buildOkEta
              semanticFactCount = semanticFactCount
              semanticRootValueFactCount = nodeCount bridgedSemanticFacts.rootValueFactCount
              semanticWorkUnitReceiptFactCount = nodeCount (int64 semanticAuthorityReceipts)
              semanticRetiredCost = semanticRetiredCost
              semanticCriticalPathRetiredCost = semanticCriticalPathRetiredCost
              cicWeightedRetiredCost = cicWeightedRetiredCost
              duplicateSemanticFactCount = nodeCount state.nativeEvalAuthority.duplicateSemanticFactCount
              qapGenerationRef = qapGenerationRef
              terminalSealRef = sealRef
              totalOrderIndex = totalOrderIndex }

        let private terminalFlowPublishAuthoritativeProgressToHud
            nowMs
            (evidence:TerminalFlowProgressEvidence)
            (snapshot:TerminalFlowAuthoritativeProgressSnapshot) =
            let current = ReducerHudAuthorityBridge.read()
            let projectedDenominator = max 1L (CompilerKernelV2.Measured.value snapshot.denominatorCost)
            let frontierDiscovered = max 0L evidence.frontier.discovered
            let frontierRetired = max 0L evidence.frontier.retired
            let denominator = max projectedDenominator frontierDiscovered
            let ratioCompleted =
                min denominator ((denominator * CompilerKernelV2.BasisPoints.value snapshot.progressMidBp) / 10000L)
            let completed = min denominator (max ratioCompleted frontierRetired)
            let frontierRemaining = max 0L (frontierDiscovered - frontierRetired)
            let remaining = max frontierRemaining (max 0L (denominator - completed))
            let physicalWorkLive =
                frontierRemaining > 0L
                || evidence.frontier.blocked > 0L
                || evidence.frontier.queueDepth > 0L
                || evidence.frontier.activeWorkers > 0L
                || evidence.workLedger.schedulerOpenCount > 0L
                || evidence.workLedger.remainingCost > 0L
            let blockersWithoutWorkDag =
                current.blockers
                |> List.filter ((<>) CompilerConsoleHud88.ReducerHudWorkDagClosure)
            let phase, blockers =
                if physicalWorkLive then
                    CompilerConsoleHud88.ReducerHudTerminalizing,
                    CompilerConsoleHud88.ReducerHudWorkDagClosure :: blockersWithoutWorkDag
                else
                    match snapshot.freshnessAtCommit with
                    | TerminalFlowProgressSnapshotFinal ->
                        CompilerConsoleHud88.ReducerHudComplete, blockersWithoutWorkDag
                    | _ when CompilerKernelV2.BasisPoints.value snapshot.progressMidBp >= 9900L ->
                        CompilerConsoleHud88.ReducerHudTerminalizing, blockersWithoutWorkDag
                    | _ -> current.phase, blockersWithoutWorkDag
            let terminalP50Ms =
                match snapshot.terminalEtaP50 with
                | Some value ->
                    let raw = CompilerKernelV2.Measured.value value
                    Some(if physicalWorkLive then max 1000L raw else max 0L raw)
                | None -> current.eta.terminalP50Ms
            let terminalP90Ms =
                match snapshot.terminalEtaP90 with
                | Some value ->
                    let raw = CompilerKernelV2.Measured.value value
                    Some(if physicalWorkLive then max 1000L raw else max 0L raw)
                | None -> current.eta.terminalP90Ms
            let terminalSemanticExact =
                snapshot.freshnessAtCommit = TerminalFlowProgressSnapshotFinal
                && not physicalWorkLive
                && completed = denominator
            let preserveExactSemanticSeed =
                current.work.semantic.exact
                && current.work.ast.exact
                && current.work.ast.totalCost > 0L
                && current.work.semantic.retiredCost >= current.work.ast.totalCost
                && current.work.semantic.knownRemainingCost = 0L
                && current.work.semantic.totalHigh = current.work.ast.totalCost
                && evidence.workLedger.schedulerOpenCount = 0L
                && evidence.workLedger.remainingCost = 0L
            let semanticProjection =
                if preserveExactSemanticSeed then current.work.semantic
                else
                    { current.work.semantic with
                        retiredCost = completed
                        discoveredCost = denominator
                        knownRemainingCost = remaining
                        blockedCost = max 0L evidence.frontier.blocked
                        reserveP50Cost = 0L
                        reserveP90Cost = 0L
                        totalLow = denominator
                        totalMid = denominator
                        totalHigh = denominator
                        exact = terminalSemanticExact
                        revision = max current.work.semantic.revision snapshot.reducerSequence }
            let physicalRemaining = max remaining (max 0L evidence.workLedger.remainingCost)
            let physicalProgressCapBp =
                if not physicalWorkLive || physicalRemaining <= 0L then 10000L
                else
                    let totalWithPhysicalResidual = max 1L (completed + physicalRemaining)
                    min 9999L ((max 0L completed * 10000L) / totalWithPhysicalResidual)
            let displayedLowBp = min physicalProgressCapBp (CompilerKernelV2.BasisPoints.value snapshot.progressLowBp)
            let displayedMidBp = min physicalProgressCapBp (CompilerKernelV2.BasisPoints.value snapshot.progressMidBp)
            let displayedHighBp = min physicalProgressCapBp (CompilerKernelV2.BasisPoints.value snapshot.progressHighBp)
            ReducerHudAuthorityBridge.tryUpdate {
                current with
                    generation = max (current.generation + 1L) nowMs
                    snapshotMs = nowMs
                    phase = phase
                    work =
                        { current.work with
                            semantic = semanticProjection
                            lowBp = displayedLowBp
                            midBp = displayedMidBp
                            highBp = displayedHighBp }
                    rates =
                        { current.rates with
                            phase = phase }
                    eta =
                        { current.eta with
                            phase = phase
                            terminalP50Ms = terminalP50Ms
                            terminalP90Ms = terminalP90Ms
                            criticalPath = CompilerConsoleHud88.ReducerHudCriticalPathSemanticRemaining(remaining, "terminal_authoritative_progress")
                            rateAuthorityRef = "terminal_authoritative_progress" }
                    blockers = blockers } |> ignore

        type TerminalFlowAdmissionRunEndPromotionCertificate = {
            certificateRef : uint32
            fixtureRef : uint32
            admissionRef : uint32
            installationRef : uint32
            consumeRef : uint32
            recoveryRef : uint32
            fairnessReleaseRef : uint32
            commitRef : uint32
            doneRef : uint32
