        }

        // Migration round : fixture evidence is now explicit about which
        // production boundaries it traversed.  The legacy certificate remains
        // representable only as quarantined evidence and can never authorize exit.
        type TerminalFlowProductionFixtureNegativeCase =
            | TerminalFlowProductionFixtureForeignLineage
            | TerminalFlowProductionFixtureDuplicateIssue
            | TerminalFlowProductionFixtureStageRegression
            | TerminalFlowProductionFixtureProjectionAuthority
            | TerminalFlowProductionFixtureForeignRunEnd
            | TerminalFlowProductionFixtureForeignCapability
            | TerminalFlowProductionFixtureStaleCapability
            | TerminalFlowProductionFixtureReplayedCapability
            | TerminalFlowProductionFixturePendingCapabilityMismatch
            | TerminalFlowProductionFixturePendingPayloadMismatch
            | TerminalFlowProductionFixtureTerminalCapabilityMismatch
            | TerminalFlowProductionFixtureFillCapabilityMismatch
            | TerminalFlowProductionFixtureFinalizationExactOnceMismatch
            | TerminalFlowProductionFixtureAdmissionCapabilityMismatch
            | TerminalFlowProductionFixtureAdmissionIdentityCapabilityMismatch
            | TerminalFlowProductionFixtureMixedAuthorityEnvelope

        type TerminalFlowProductionFixtureNegativeVerdict = private {
            caseId : TerminalFlowProductionFixtureNegativeCase
            rejected : bool
            blockerRef : uint32
            reducerRevision : int64
        }

        let private terminalFlowProductionFixtureNegativeSuiteComplete verdicts =
            let cases = verdicts |> List.map (fun verdict -> verdict.caseId) |> Set.ofList
            let required =
                Set.ofList
                    [ TerminalFlowProductionFixtureForeignLineage
                      TerminalFlowProductionFixtureDuplicateIssue
                      TerminalFlowProductionFixtureStageRegression
                      TerminalFlowProductionFixtureProjectionAuthority
                      TerminalFlowProductionFixtureForeignRunEnd
                      TerminalFlowProductionFixtureForeignCapability
                      TerminalFlowProductionFixtureStaleCapability
                      TerminalFlowProductionFixtureReplayedCapability
                      TerminalFlowProductionFixturePendingCapabilityMismatch
                      TerminalFlowProductionFixturePendingPayloadMismatch
                      TerminalFlowProductionFixtureTerminalCapabilityMismatch
                      TerminalFlowProductionFixtureFillCapabilityMismatch
                      TerminalFlowProductionFixtureFinalizationExactOnceMismatch
                      TerminalFlowProductionFixtureAdmissionCapabilityMismatch
                      TerminalFlowProductionFixtureAdmissionIdentityCapabilityMismatch
                      TerminalFlowProductionFixtureMixedAuthorityEnvelope ]
            cases = required
            && verdicts.Length = required.Count
            && (verdicts |> List.forall (fun verdict -> verdict.rejected && verdict.blockerRef <> 0u))

        type TerminalFlowProductionFixtureCertificate = private {
