            transactionRef : uint32
            issuanceRef : uint32
            issueEventRef : uint32
            consumptionEventRef : uint32
            runEndReceiptRef : uint32
            physicalExitReceiptRef : uint32
            exactOnceRef : uint32
            finalRevision : int64
            negativeVerdicts : TerminalFlowProductionFixtureNegativeVerdict list
