        type TerminalFlowDeferredOutcomeDisposition =
            | TerminalFlowDeferredOutcomeEnqueued
            | TerminalFlowDeferredOutcomeDuplicate
            | TerminalFlowDeferredOutcomeEquivalentObserverCoalesced of existingTerminalRef:uint32 * incomingTerminalRef:uint32
            | TerminalFlowDeferredOutcomeRetainedExistingClass of existingTerminalRef:uint32 * incomingTerminalRef:uint32 * existingClass:TerminalFlowPendingCandidateClass * incomingClass:TerminalFlowPendingCandidateClass
            | TerminalFlowDeferredOutcomeReplacedByIncomingClass of existingTerminalRef:uint32 * incomingTerminalRef:uint32 * existingClass:TerminalFlowPendingCandidateClass * incomingClass:TerminalFlowPendingCandidateClass
            | TerminalFlowDeferredOutcomeConflict of existingTerminalRef:uint32 * incomingTerminalRef:uint32 * existingClass:TerminalFlowPendingCandidateClass * incomingClass:TerminalFlowPendingCandidateClass

        let private terminalFlowDeferredOutcomeGate = obj()
        let mutable private terminalFlowDeferredOutcome : TerminalFlowGlobalPendingTerminal option = None

        let private terminalFlowDeferredOutcomeTerminalRef _label (pending:TerminalFlowGlobalPendingTerminal) =
            terminalFlowIdentityRefDigest pending.terminalReceiptRef

        let private terminalFlowDeferredOutcomeIsObserver pending =
            match terminalFlowPendingCandidateClass pending with
            | TerminalFlowObserverProvisionalCandidateClass
            | TerminalFlowObserverFinalCandidateClass -> true
            | TerminalFlowExecutableProvisionalCandidateClass
            | TerminalFlowExecutableFinalCandidateClass -> false

        let private terminalFlowDeferOutcomeForReducer (pending:TerminalFlowGlobalPendingTerminal) =
            lock terminalFlowDeferredOutcomeGate (fun () ->
                match terminalFlowDeferredOutcome with
                | None ->
                    terminalFlowDeferredOutcome <- Some pending
                    TerminalFlowDeferredOutcomeEnqueued
                | Some existing when existing.terminalReceiptRef = pending.terminalReceiptRef && existing.fillRef = pending.fillRef ->
                    let existingRef = terminalFlowDeferredOutcomeTerminalRef "deferred_existing_terminal_ref" existing
                    let incomingRef = terminalFlowDeferredOutcomeTerminalRef "deferred_incoming_terminal_ref" pending
                    let existingClass = terminalFlowPendingCandidateClass existing
                    let incomingClass = terminalFlowPendingCandidateClass pending
                    if terminalFlowPendingCandidateIsExecutable incomingClass
                       && not (terminalFlowPendingCandidateIsExecutable existingClass) then
                        terminalFlowDeferredOutcome <- Some pending
                        TerminalFlowDeferredOutcomeReplacedByIncomingClass(existingRef, incomingRef, existingClass, incomingClass)
                    elif terminalFlowPendingCandidateIsFinal incomingClass
                         && not (terminalFlowPendingCandidateIsFinal existingClass) then
                        terminalFlowDeferredOutcome <- Some pending
                        TerminalFlowDeferredOutcomeReplacedByIncomingClass(existingRef, incomingRef, existingClass, incomingClass)
                    else
                        TerminalFlowDeferredOutcomeDuplicate
                | Some existing ->
                    let existingRef = terminalFlowDeferredOutcomeTerminalRef "deferred_existing_terminal_ref" existing
                    let incomingRef = terminalFlowDeferredOutcomeTerminalRef "deferred_incoming_terminal_ref" pending
                    let existingClass = terminalFlowPendingCandidateClass existing
                    let incomingClass = terminalFlowPendingCandidateClass pending
                    let equivalentObserver =
                        existing.intent = pending.intent
                        && terminalFlowDeferredOutcomeIsObserver existing
                        && terminalFlowDeferredOutcomeIsObserver pending
                    if equivalentObserver then
                        TerminalFlowDeferredOutcomeEquivalentObserverCoalesced(existingRef, incomingRef)
                    elif terminalFlowPendingCandidateIsExecutable incomingClass
                         && not (terminalFlowPendingCandidateIsExecutable existingClass) then
                        terminalFlowDeferredOutcome <- Some pending
                        TerminalFlowDeferredOutcomeReplacedByIncomingClass(existingRef, incomingRef, existingClass, incomingClass)
                    elif terminalFlowPendingCandidateIsExecutable existingClass
                         && not (terminalFlowPendingCandidateIsExecutable incomingClass) then
                        TerminalFlowDeferredOutcomeRetainedExistingClass(existingRef, incomingRef, existingClass, incomingClass)
                    elif terminalFlowPendingCandidateIsFinal incomingClass
                         && not (terminalFlowPendingCandidateIsFinal existingClass) then
                        terminalFlowDeferredOutcome <- Some pending
                        TerminalFlowDeferredOutcomeReplacedByIncomingClass(existingRef, incomingRef, existingClass, incomingClass)
                    elif terminalFlowPendingCandidateIsFinal existingClass
                         && not (terminalFlowPendingCandidateIsFinal incomingClass) then
                        TerminalFlowDeferredOutcomeRetainedExistingClass(existingRef, incomingRef, existingClass, incomingClass)
                    else
                        TerminalFlowDeferredOutcomeConflict(existingRef, incomingRef, existingClass, incomingClass))

        let private terminalFlowTakeDeferredOutcomeForReducer () =
            lock terminalFlowDeferredOutcomeGate (fun () ->
                let pending = terminalFlowDeferredOutcome
                terminalFlowDeferredOutcome <- None
                pending)

        type TerminalFlowPredecessorOrderDiagnosis =
            | TerminalFlowPredecessorOrderAdmissionMissing of expectedAdmissionRef:uint32
            | TerminalFlowPredecessorOrderAdmissionMismatched of expectedAdmissionRef:uint32 * actualAdmissionRef:uint32
            | TerminalFlowPredecessorOrderTerminalOrderMissing of expectedAdmissionRef:uint32
            | TerminalFlowPredecessorOrderTerminalOrderMismatched of expectedAdmissionRef:uint32 * actualAdmissionRef:uint32

        let private terminalFlowPredecessorOrderDiagnosisText = function
            | TerminalFlowPredecessorOrderAdmissionMissing expectedAdmissionRef ->
                sprintf "AdmissionMissing(expected_admission_ref=%u)" expectedAdmissionRef
            | TerminalFlowPredecessorOrderAdmissionMismatched(expectedAdmissionRef, actualAdmissionRef) ->
                sprintf "AdmissionMismatched(expected_admission_ref=%u|actual_admission_ref=%u)" expectedAdmissionRef actualAdmissionRef
            | TerminalFlowPredecessorOrderTerminalOrderMissing expectedAdmissionRef ->
                sprintf "TerminalOrderMissing(expected_admission_ref=%u)" expectedAdmissionRef
            | TerminalFlowPredecessorOrderTerminalOrderMismatched(expectedAdmissionRef, actualAdmissionRef) ->
                sprintf "TerminalOrderMismatched(expected_admission_ref=%u|actual_admission_ref=%u)" expectedAdmissionRef actualAdmissionRef

        let private terminalFlowPredecessorOrderDiagnosisFor
            (state:TerminalFlowGlobalReducerState)
            (pending:TerminalFlowGlobalPendingTerminal) =
            let expectedAdmissionRef = terminalFlowPendingAdmissionRef pending.admission
            match state.dispatchAdmission with
            | TerminalFlowDispatchAdmissionOpen ->
                Some(TerminalFlowPredecessorOrderAdmissionMissing expectedAdmissionRef)
            | TerminalFlowDispatchAdmissionSealed certificate when terminalFlowAdmissionRawRef certificate.identity <> expectedAdmissionRef ->
                Some(TerminalFlowPredecessorOrderAdmissionMismatched(expectedAdmissionRef, terminalFlowAdmissionRawRef certificate.identity))
            | TerminalFlowDispatchAdmissionSealed _ ->
                match state.terminalOrderCutover with
                | None -> Some(TerminalFlowPredecessorOrderTerminalOrderMissing expectedAdmissionRef)
                | Some terminalOrder ->
                    let actualAdmissionRef =
                        terminalFlowTerminalOrderCutoverAdmissionRef terminalOrder
                        |> Option.defaultValue 0u
                    if actualAdmissionRef = expectedAdmissionRef then None
                    else Some(TerminalFlowPredecessorOrderTerminalOrderMismatched(expectedAdmissionRef, actualAdmissionRef))

        type TerminalFlowConsumeRequirementBlocker = private {
            kind : TerminalFlowDispatchRequirementKind
            requirementRef : uint32
            satisfierRef : uint32
            blockerRef : uint32
            ageMs : int64
            reason : CompilerKernelV2.OperationalReasonId
        }

        type TerminalFlowConsumeCredentialAuthority =
            | TerminalFlowConsumeCredentialSatisfied of requirementRef:uint32 * evidenceRef:uint32 * credentialRef:uint32 * satisfiedAtSequence:int64 * satisfiedAtMs:int64
            | TerminalFlowConsumeCredentialCycleClosed of requirementRef:uint32 * cycleRef:uint32 * credentialRef:uint32 * detectedAtMs:int64
            | TerminalFlowConsumeCredentialUnsatisfied
            | TerminalFlowConsumeCredentialUnavailable

        let private terminalFlowConsumeCredentialAuthorityFor credentialLedger kind =
            match credentialLedger with
            | Some ledger ->
                match Map.tryFind kind ledger.index with
                | Some credential ->
                    match credential.state with
                    | TerminalFlowRequirementCredentialSatisfied(evidenceRef, satisfiedAtSequence, satisfiedAtMs) ->
                        TerminalFlowConsumeCredentialSatisfied(
                            credential.requirementRef,
                            evidenceRef,
                            credential.credentialRef,
                            satisfiedAtSequence,
                            satisfiedAtMs)
                    | TerminalFlowRequirementCredentialCycleClosed proof ->
                        TerminalFlowConsumeCredentialCycleClosed(
                            credential.requirementRef,
                            proof.cycleRef,
                            credential.credentialRef,
                            proof.detectedAtMs)
                    | TerminalFlowRequirementCredentialAwaiting _
                    | TerminalFlowRequirementCredentialHeldBy _ ->
                        TerminalFlowConsumeCredentialUnsatisfied
                | None -> TerminalFlowConsumeCredentialUnavailable
            | None -> TerminalFlowConsumeCredentialUnavailable

        let private terminalFlowConsumeCredentialIsSatisfied credentialLedger kind =
            match terminalFlowConsumeCredentialAuthorityFor credentialLedger kind with
            | TerminalFlowConsumeCredentialSatisfied _ -> true
            | TerminalFlowConsumeCredentialCycleClosed _
            | TerminalFlowConsumeCredentialUnsatisfied
            | TerminalFlowConsumeCredentialUnavailable -> false

        let private terminalFlowConsumeCredentialAuthorityText = function
            | TerminalFlowConsumeCredentialSatisfied(requirementRef, evidenceRef, credentialRef, satisfiedAtSequence, satisfiedAtMs) ->
                FastRuntimeFormat.format "Satisfied(requirement=%u|evidence=%u|credential=%u|sequence=%d|at_ms=%d)" [| box requirementRef; box evidenceRef; box credentialRef; box satisfiedAtSequence; box satisfiedAtMs |]
            | TerminalFlowConsumeCredentialCycleClosed(requirementRef, cycleRef, credentialRef, detectedAtMs) ->
                FastRuntimeFormat.format "CycleClosed(requirement=%u|cycle=%u|credential=%u|at_ms=%d)" [| box requirementRef; box cycleRef; box credentialRef; box detectedAtMs |]
            | TerminalFlowConsumeCredentialUnsatisfied -> "Unsatisfied"
            | TerminalFlowConsumeCredentialUnavailable -> "Unavailable"

        let private terminalFlowConsumeRequirementBlocker credentialLedger kind reason nowMs =
            match credentialLedger with
            | Some ledger ->
                let credential = Map.find kind ledger.index
                let firstObservedAtMs = terminalFlowRequirementStateFirstObservedAtMs credential.state
                let effectiveReason, satisfierRef =
                    match credential.state with
                    | TerminalFlowRequirementCredentialCycleClosed proof ->
                        sprintf "credential_cycle_closed:%u" proof.cycleRef, proof.cycleRef
                    | TerminalFlowRequirementCredentialSatisfied(evidenceRef, _, _) ->
                        // Satisfaction is evidence, not a replacement diagnosis.  The
                        // caller's clause remains the causal blocker; contradictions
                        // are derived from the typed join-missing list.
                        reason, evidenceRef
                    | _ ->
                        reason, terminalFlowRequirementMinterRef credential.minter
                { kind = kind
                  requirementRef = credential.requirementRef
                  satisfierRef = satisfierRef
                  blockerRef = credential.credentialRef
                  ageMs = max 0L (nowMs - firstObservedAtMs)
                  reason = CompilerKernelV2.OperationalReasonIdOps.create effectiveReason }
            | None ->
                let kindText = terminalFlowDispatchRequirementKindText kind
                { kind = kind
                  requirementRef = terminalFlowMintedRefOf "terminal_preledger_requirement_ref" kindText
                  satisfierRef = terminalFlowMintedRefOf "terminal_preledger_satisfier_ref" (kindText + ":total")
                  blockerRef = terminalFlowMintedRefOf "terminal_preledger_credential_ref" kindText
                  ageMs = 0L
                  reason = CompilerKernelV2.OperationalReasonIdOps.create reason }

        type TerminalFlowConsumeHandoffBlocker =
            | TerminalFlowConsumeRequirementBlocked of TerminalFlowConsumeRequirementBlocker
            | TerminalFlowConsumeActorBoundElsewhere of expectedFillRef:uint32 * actorFillRef:uint32
            | TerminalFlowConsumeExitAlreadyClosed of exitRef:uint32

        // Consume/join is a proof boundary.  Every failed clause is carried from
        // the builder that evaluated it; no later matcher may invent a different
        // blocker or erase the causal reason.
        type TerminalFlowActorOutcomeJoinMissing =
            | TerminalFlowActorOutcomeJoinPendingOutcomeNotFinal
            | TerminalFlowActorOutcomeJoinPendingDispatchObserverOnly of sourceRef:uint32
            | TerminalFlowActorOutcomeJoinReducerActorDoesNotAdmitIssue
            | TerminalFlowActorOutcomeJoinReducerHandoffNotDispatchReady
            | TerminalFlowActorOutcomeJoinReducerHandoffTerminalMismatch of expected:uint32 * actual:uint32
            | TerminalFlowActorOutcomeJoinReducerHandoffFillMismatch of expected:uint32 * actual:uint32
            | TerminalFlowActorOutcomeJoinRootNotResolved
            | TerminalFlowActorOutcomeJoinOutcomeNotSealed
            | TerminalFlowActorOutcomeJoinExitNotOpen
            | TerminalFlowActorOutcomeJoinWorkDagTailClosureMissing
            | TerminalFlowActorOutcomeJoinInstalledAdmissionMissing
            | TerminalFlowActorOutcomeJoinActorBindingMissing
            | TerminalFlowActorOutcomeJoinDispatchAdmissionNotSealed
            | TerminalFlowActorOutcomeJoinPendingTerminalMismatch
            | TerminalFlowActorOutcomeJoinPendingFillMismatch
            | TerminalFlowActorOutcomeJoinInstalledAdmissionTerminalMismatch
            | TerminalFlowActorOutcomeJoinInstalledAdmissionFillMismatch
            | TerminalFlowActorOutcomeJoinAdmissionRefMismatch
            | TerminalFlowActorOutcomeJoinAdmissionIdentityMismatch
            | TerminalFlowActorOutcomeJoinBoundActorMismatch
            | TerminalFlowActorOutcomeJoinActorBindingRefMismatch
            | TerminalFlowActorOutcomeJoinCredentialLedgerRefMismatch
            | TerminalFlowActorOutcomeJoinPredecessorOrderUnsatisfied
            | TerminalFlowActorOutcomeJoinKernelRootProofMismatch
            | TerminalFlowActorOutcomeJoinTerminalOutcomeProofMismatch
            | TerminalFlowActorOutcomeJoinWorkDagProofMismatch
            | TerminalFlowActorOutcomeJoinQueueRecoveryProofMismatch
            | TerminalFlowActorOutcomeJoinRootCapabilityRejected
            | TerminalFlowActorOutcomeJoinStateShapeRejected

        let private terminalFlowActorOutcomeJoinMissingText = function
            | TerminalFlowActorOutcomeJoinPendingOutcomeNotFinal -> "pending_outcome_not_final"
            | TerminalFlowActorOutcomeJoinPendingDispatchObserverOnly sourceRef -> sprintf "pending_dispatch_observer_only:source_ref=%u" sourceRef
            | TerminalFlowActorOutcomeJoinReducerActorDoesNotAdmitIssue -> "reducer_actor_does_not_admit_issue"
            | TerminalFlowActorOutcomeJoinReducerHandoffNotDispatchReady -> "reducer_handoff_not_dispatch_ready"
