            | TerminalFlowActorOutcomeJoinReducerHandoffFillMismatch(expected, actual) -> sprintf "reducer_handoff_fill_mismatch:expected=%u:actual=%u" expected actual
            | TerminalFlowActorOutcomeJoinRootNotResolved -> "root_not_resolved"
            | TerminalFlowActorOutcomeJoinOutcomeNotSealed -> "outcome_not_sealed"
            | TerminalFlowActorOutcomeJoinExitNotOpen -> "exit_not_open"
            | TerminalFlowActorOutcomeJoinWorkDagTailClosureMissing -> "workdag_tail_closure_missing"
            | TerminalFlowActorOutcomeJoinInstalledAdmissionMissing -> "installed_admission_missing"
            | TerminalFlowActorOutcomeJoinActorBindingMissing -> "actor_binding_missing"
            | TerminalFlowActorOutcomeJoinDispatchAdmissionNotSealed -> "dispatch_admission_not_sealed"
            | TerminalFlowActorOutcomeJoinPendingTerminalMismatch -> "pending_terminal_mismatch"
            | TerminalFlowActorOutcomeJoinPendingFillMismatch -> "pending_fill_mismatch"
            | TerminalFlowActorOutcomeJoinInstalledAdmissionTerminalMismatch -> "installed_admission_terminal_mismatch"
            | TerminalFlowActorOutcomeJoinInstalledAdmissionFillMismatch -> "installed_admission_fill_mismatch"
            | TerminalFlowActorOutcomeJoinAdmissionRefMismatch -> "admission_ref_mismatch"
            | TerminalFlowActorOutcomeJoinAdmissionIdentityMismatch -> "admission_identity_mismatch"
            | TerminalFlowActorOutcomeJoinBoundActorMismatch -> "bound_actor_mismatch"
            | TerminalFlowActorOutcomeJoinActorBindingRefMismatch -> "actor_binding_ref_mismatch"
            | TerminalFlowActorOutcomeJoinCredentialLedgerRefMismatch -> "credential_ledger_ref_mismatch"
            | TerminalFlowActorOutcomeJoinPredecessorOrderUnsatisfied -> "predecessor_order_unsatisfied"
            | TerminalFlowActorOutcomeJoinKernelRootProofMismatch -> "kernel_root_proof_mismatch"
            | TerminalFlowActorOutcomeJoinTerminalOutcomeProofMismatch -> "terminal_outcome_proof_mismatch"
            | TerminalFlowActorOutcomeJoinWorkDagProofMismatch -> "workdag_proof_mismatch"
            | TerminalFlowActorOutcomeJoinQueueRecoveryProofMismatch -> "queue_recovery_proof_mismatch"
            | TerminalFlowActorOutcomeJoinRootCapabilityRejected -> "root_capability_rejected"
            | TerminalFlowActorOutcomeJoinStateShapeRejected -> "state_shape_rejected"

        let private terminalFlowActorOutcomeJoinProjectionContradiction = function
            | TerminalFlowActorOutcomeJoinInstalledAdmissionTerminalMismatch
            | TerminalFlowActorOutcomeJoinInstalledAdmissionFillMismatch
            | TerminalFlowActorOutcomeJoinAdmissionRefMismatch
            | TerminalFlowActorOutcomeJoinAdmissionIdentityMismatch
