            | TerminalFlowDispatchAffinePrepared transaction ->
                FastRuntimeFormat.format "AffinePrepared(transaction=%u|issuance=%u|consume=%u|actor_lease=%u|token=%u|pending=%u|ordinal=%s|revision=%d)" [| box transaction.transactionRef; box transaction.authorization.issuance.issuanceRef; box transaction.authorization.consumeAuthorityRef; box transaction.actorLease.leaseRef; box transaction.authorization.tokenRef; box transaction.authorization.pendingTerminalRef; box (terminalFlowAffineTransitionOrdinalText transaction.transitionOrdinal); box transaction.preparedAtRevision |]
