        let private terminalFlowSchedulerPushTransitionText = function
            | TerminalFlowSchedulerPushArmAttempted(fillRef, terminalRef) -> sprintf "ArmAttempted(fill_ref=%u|terminal_ref=%u)" fillRef terminalRef
            | TerminalFlowSchedulerPushDispatchAccepted(requestRef, dispatchKeyRef) -> sprintf "DispatchAccepted(request_ref=%u|dispatch_key_ref=%u)" requestRef dispatchKeyRef
            | TerminalFlowSchedulerPushDispatchAlreadyExists(requestRef, dispatchKeyRef) -> sprintf "DispatchAlreadyExists(request_ref=%u|dispatch_key_ref=%u)" requestRef dispatchKeyRef
