        let private terminalFlowOutcomeFilledTransitionFromStageToken
            (stageToken:TerminalFlowActorOutcomeJoin<TerminalFlowArmedOutcomeJoinedStage>)
            (transition:TerminalFlowSchedulerPushTransition)
            : TerminalFlowOutcomeFilledTransition<TerminalFlowOutcomeFilledByHopacStage>
            =
            let dispatchRef =
                match transition with
                | TerminalFlowSchedulerPushDispatchAccepted(requestRef, _)
                | TerminalFlowSchedulerPushDispatchAlreadyExists(requestRef, _) -> requestRef
                | TerminalFlowSchedulerPushDispatchRejected blocker -> terminalFlowMintedRefOf "dispatch_rejected_ref" (terminalFlowDispatchBlockerText blocker)
                | TerminalFlowSchedulerPushDispatchFailClosed reasonRef -> reasonRef
                | TerminalFlowSchedulerPushArmAttempted(fillRef, terminalRef) -> terminalFlowMintedRefOf "dispatch_arm_only_ref" (sprintf "%u:%u" fillRef terminalRef)
            { stageTokenId = stageToken.tokenId
              terminalReceiptRef = stageToken.terminalReceiptRef
              fillKey = stageToken.fillKey
              fillReceiptRef = terminalFlowMintedRefOf "terminal_outcome_fill_receipt_ref" (stageToken.tokenId + "|" + TerminalFlowFillKeyId.text stageToken.fillKey)
              dispatchRef = dispatchRef
              filledAtMs = Environment.TickCount64 }

