        [<NoComparison>]
        type TerminalFlowPendingPromotionDecision =
            | TerminalFlowPendingPromotionNotRequired
            | TerminalFlowPendingPromotionAwaitRecovery of intent:TerminalFlowPendingTerminalIntent
            | TerminalFlowPendingPromotionReady of priorIntent:TerminalFlowPendingTerminalIntent * promoted:TerminalFlowGlobalPendingTerminal * recoveryRef:TerminalFlowIdentityRef<TerminalFlowQueueRecoveryRefKind>

        [<NoComparison>]
        type TerminalFlowPendingExecutablePromotionDecision =
            | TerminalFlowPendingExecutablePromotionNotRequired of current:TerminalFlowGlobalPendingTerminal
            | TerminalFlowPendingExecutablePromotionContinuationRebound of capabilityRef:uint32 * promoted:TerminalFlowGlobalPendingTerminal
            | TerminalFlowPendingExecutablePromotionAuthorized of priorSourceRef:uint32 * capabilityRef:uint32 * promoted:TerminalFlowGlobalPendingTerminal

        let private terminalFlowPendingPromotionFor recoveryDecision (pending:TerminalFlowGlobalPendingTerminal) =
            match pending.intent, recoveryDecision with
            | TerminalFlowPendingQuarantine, TerminalFlowQueueRecoveryReadyForReducerSeal certificate
            | TerminalFlowPendingNoFurther, TerminalFlowQueueRecoveryReadyForReducerSeal certificate ->
                let promoted =
                    terminalFlowPendingCandidateCreateForRefs
                        pending.terminalReceiptRef
                        pending.fillKeyId
                        TerminalFlowPendingBuildOk
                        pending.admission
                        pending.dispatchAuthority
                        pending.armAndDispatch
                TerminalFlowPendingPromotionReady(pending.intent, promoted, certificate.recoveryRef)
            | TerminalFlowPendingBuildOk, TerminalFlowQueueRecoveryReadyForReducerSeal _ ->
                TerminalFlowPendingPromotionNotRequired
            | TerminalFlowPendingFailClosed, _ -> TerminalFlowPendingPromotionNotRequired
            | intent, _ -> TerminalFlowPendingPromotionAwaitRecovery intent

        let private terminalFlowPendingExecutablePromotionForAppliedProof
            planRef
            transactionRef
            proofRef
            proofExactOnceRef
            writerLeaseRef
            exactOnceWakerEdgeRef
            armAndDispatch
            (pending:TerminalFlowGlobalPendingTerminal) =
            match pending.dispatchAuthority with
            | TerminalFlowPendingNativeExecutable capabilityRef ->
                let rebound =
                    terminalFlowPendingCandidateCreateForRefs
                        pending.terminalReceiptRef
                        pending.fillKeyId
                        pending.intent
                        pending.admission
                        pending.dispatchAuthority
                        armAndDispatch
                TerminalFlowPendingExecutablePromotionContinuationRebound(capabilityRef, rebound)
            | TerminalFlowPendingObserverProjection sourceRef ->
                let capabilityRef =
                    NativeCutoverStableRef.ref32
                        "terminal-qap-applied-pending-executable"
                        [ string planRef
                          string transactionRef
                          string proofRef
                          string proofExactOnceRef
                          string writerLeaseRef
                          string exactOnceWakerEdgeRef
                          string (terminalFlowPendingTerminalRef pending) ]
                let promoted =
                    terminalFlowPendingCandidateCreateForRefs
                        pending.terminalReceiptRef
                        pending.fillKeyId
                        pending.intent
                        pending.admission
                        (TerminalFlowPendingNativeExecutable capabilityRef)
                        armAndDispatch
                TerminalFlowPendingExecutablePromotionAuthorized(sourceRef, capabilityRef, promoted)

