            | TerminalFlowSemanticSeedClosureFromReducerProgress
            | TerminalFlowSemanticSeedClosureFromReducerHudExactSeed

        let private terminalFlowSemanticSeedClosureProgressSourceText = function
            | TerminalFlowSemanticSeedClosureFromReducerProgress -> "reducer_progress"
            | TerminalFlowSemanticSeedClosureFromReducerHudExactSeed -> "reducer_hud_exact_seed"

        [<NoEquality; NoComparison>]
        type private TerminalFlowSemanticSeedClosureProgressEvidence = {
            snapshotRef : uint32
            denominatorRevision : int64
            observedAtMs : int64
            semanticRetiredCost : int64
            denominatorCost : int64
            progressLowBp : int64
            source : TerminalFlowSemanticSeedClosureProgressSource
        }

        [<NoEquality; NoComparison>]
        type private TerminalFlowSemanticSeedClosureEvidence = {
            rootEvidenceRef : uint32
            parsedAstSeedTotal : int64
            semanticSeedRetiredCost : int64
            semanticSeedGeneration : int64
            semanticSeedRevision : int64
            progress : TerminalFlowSemanticSeedClosureProgressEvidence
        }

        let private terminalFlowSemanticSeedClosureEvidenceFor (state:TerminalFlowGlobalReducerState) =
            match state.kernel.root with
            | KernelRootResolved(_, _, rootEvidenceRef) ->
                let _, parsedAstSeedTotal = parsedAstStructuralSeedSnapshot ()
                let hud = ReducerHudAuthorityBridge.read()
                let semantic = hud.work.semantic
                let ast = hud.work.ast
                let discoveryClosed =
                    match hud.discovery with
                    | CompilerConsoleHud88.ReducerHudDiscoveryClosed -> true
                    | CompilerConsoleHud88.ReducerHudDiscoveryOpen _ -> false
                if parsedAstSeedTotal > 0L
                   && discoveryClosed
                   && ast.exact
                   && ast.totalCost = parsedAstSeedTotal
                   && ast.completedCost >= parsedAstSeedTotal
                   && semantic.exact
                   && semantic.retiredCost >= parsedAstSeedTotal
                   && semantic.knownRemainingCost = 0L
                   && semantic.totalHigh = parsedAstSeedTotal then
                    let progress =
                        match state.authoritativeProgress with
                        | Some (reducerProgress:TerminalFlowAuthoritativeProgressSnapshot) ->
                            { snapshotRef = reducerProgress.snapshotRef
                              denominatorRevision = reducerProgress.denominatorRevision
                              observedAtMs = CompilerKernelV2.Measured.value reducerProgress.observedAt
                              semanticRetiredCost = CompilerKernelV2.Measured.value reducerProgress.semanticRetiredCost
                              denominatorCost = CompilerKernelV2.Measured.value reducerProgress.denominatorCost
                              progressLowBp = CompilerKernelV2.Measured.value reducerProgress.progressLowBp
                              source = TerminalFlowSemanticSeedClosureFromReducerProgress }
                        | None ->
                            let snapshotRef =
                                terminalFlowMintedRefOf
                                    "semantic_seed_closure_hud_snapshot_ref"
                                    (FastRuntimeFormat.format "%u:%d:%d:%d" [| box rootEvidenceRef; box hud.generation; box semantic.revision; box parsedAstSeedTotal |])
                            { snapshotRef = snapshotRef
                              denominatorRevision = semantic.revision
                              observedAtMs = hud.snapshotMs
                              semanticRetiredCost = semantic.retiredCost
                              denominatorCost = semantic.totalMid
                              progressLowBp = hud.work.lowBp
                              source = TerminalFlowSemanticSeedClosureFromReducerHudExactSeed }
                    Some {
                        rootEvidenceRef = rootEvidenceRef
                        parsedAstSeedTotal = parsedAstSeedTotal
                        semanticSeedRetiredCost = semantic.retiredCost
                        semanticSeedGeneration = hud.generation
                        semanticSeedRevision = semantic.revision
                        progress = progress
                    }
                else None
            | _ -> None

        [<StructuralEquality; NoComparison>]
        type private TerminalFlowQapWitnessSemanticClosureGateId =
            | TerminalFlowQapWitnessAwaitSemanticSeedClosure
            | TerminalFlowQapWitnessAwaitExactClosedWorld of rootEvidenceRef:uint32 * semanticSeedRevision:int64
            | TerminalFlowQapWitnessSemanticSeedAndClosedWorld of rootEvidenceRef:uint32 * semanticSeedRevision:int64

        let private terminalFlowQapWitnessSemanticClosureGateFor (state:TerminalFlowGlobalReducerState) =
            match terminalFlowSemanticSeedClosureEvidenceFor state with
            | None -> TerminalFlowQapWitnessAwaitSemanticSeedClosure
            | Some closure ->
                match state.progressAuthority.accepted with
                | Some evidence when terminalFlowProgressEvidenceIsExactClosedWorld evidence ->
                    TerminalFlowQapWitnessSemanticSeedAndClosedWorld(closure.rootEvidenceRef, closure.semanticSeedRevision)
                | _ ->
                    TerminalFlowQapWitnessAwaitExactClosedWorld(closure.rootEvidenceRef, closure.semanticSeedRevision)

        let private terminalFlowQapWitnessSemanticClosureGateText = function
            | TerminalFlowQapWitnessAwaitSemanticSeedClosure -> "AwaitSemanticSeedClosure"
            | TerminalFlowQapWitnessAwaitExactClosedWorld(rootEvidenceRef, semanticSeedRevision) ->
                FastRuntimeFormat.format "AwaitExactClosedWorld(root_evidence_ref=%u|semantic_seed_revision=%d)" [| box rootEvidenceRef; box semanticSeedRevision |]
            | TerminalFlowQapWitnessSemanticSeedAndClosedWorld(rootEvidenceRef, semanticSeedRevision) ->
                FastRuntimeFormat.format "SemanticSeedAndClosedWorld(root_evidence_ref=%u|semantic_seed_revision=%d)" [| box rootEvidenceRef; box semanticSeedRevision |]

        let private terminalFlowPendingExecutablePromotionForSemanticClosure
            (state:TerminalFlowGlobalReducerState)
            (pending:TerminalFlowGlobalPendingTerminal) =
            match pending.intent, pending.dispatchAuthority, terminalFlowSemanticSeedClosureEvidenceFor state with
            | TerminalFlowPendingBuildOk,
              TerminalFlowPendingObserverProjection sourceRef,
              Some closure ->
                let progress = closure.progress
                let capabilityRef =
                    NativeCutoverStableRef.ref32
                        "terminal-semantic-closure-native-executable"
                        [ string sourceRef
                          string closure.rootEvidenceRef
                          string progress.snapshotRef
                          string progress.denominatorRevision
                          string closure.semanticSeedRetiredCost
                          string closure.semanticSeedGeneration
                          string closure.semanticSeedRevision
                          string closure.parsedAstSeedTotal
                          string (terminalFlowPendingTerminalRef pending) ]
                let promoted =
                    terminalFlowPendingCandidateCreateForRefs
                        pending.terminalReceiptRef
                        pending.fillKeyId
                        pending.intent
                        pending.admission
                        (TerminalFlowPendingNativeExecutable capabilityRef)
                        pending.armAndDispatch
                Some(sourceRef, closure.rootEvidenceRef, progress.snapshotRef, progress.source, capabilityRef, promoted)
            | _ -> None

        [<StructuralEquality; NoComparison>]
        type private TerminalFlowSemanticClosureBuildOkRequestIdentity = {
            rootEvidenceRef : uint32
            parsedAstSeedTotal : int64
        }

        let private terminalFlowSemanticClosureBuildOkRequestRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<TerminalFlowSemanticClosureBuildOkRequestIdentity,byte>()

        let private terminalFlowRequestBuildOkForSemanticClosure (state:TerminalFlowGlobalReducerState) =
            match state.pendingTerminal, terminalFlowSemanticSeedClosureEvidenceFor state with
            | TerminalFlowPendingSlotAwaitingCandidate,
              Some closure ->
                let progress = closure.progress
                let rootEvidenceRef = closure.rootEvidenceRef
                let identity = {
                    rootEvidenceRef = rootEvidenceRef
                    parsedAstSeedTotal = closure.parsedAstSeedTotal
                }
                if terminalFlowSemanticClosureBuildOkRequestRegistry.TryAdd(identity, 0uy) then
                    let terminalReceiptId =
                        FastRuntimeFormat.format "reducer-semantic-closure:%u:%d:%d" [| box rootEvidenceRef; box closure.semanticSeedGeneration; box closure.semanticSeedRevision |]
                    let fillKey =
                        FastRuntimeFormat.format "reducer-semantic-closure-fill:%u:%d:%d" [| box rootEvidenceRef; box closure.semanticSeedGeneration; box closure.semanticSeedRevision |]
                    let delivery =
                        DiagJson.publishTerminalOutcomeCandidate
                            DiagJson.TerminalOutcomeCandidateBuildOk
                            terminalReceiptId
                            fillKey
                            "TerminalBuildOk(reducer_semantic_closure_exact)"
                    match delivery with
                    | DiagJson.TerminalOutcomeCandidatePublisherFaulted _ ->
                        let mutable ignored = 0uy
                        terminalFlowSemanticClosureBuildOkRequestRegistry.TryRemove(identity, &ignored) |> ignore
                    | _ -> ()
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_semantic_closure_build_ok_requested\",\"root_evidence_ref\":%u,\"progress_snapshot_ref\":%u,\"progress_source_du\":%s,\"denominator_revision\":%d,\"semantic_retired_cost\":%d,\"semantic_seed_generation\":%d,\"semantic_seed_revision\":%d,\"parsed_ast_seed_total\":%d,\"terminal_progress_semantic_retired_cost\":%d,\"operational_denominator_cost\":%d,\"operational_progress_low_bp\":%d,\"semantic_closure_age_ms\":%d,\"delivery_du\":%s,\"closure_basis_du\":\"reducer_hud_semantic_seed_receipt_independent_of_operational_residual\",\"authority\":\"single_reducer_consumes_exact_semantic_seed_receipt\",\"next\":\"reduce_terminal_outcome_ready_then_promote_native\"}" [| box rootEvidenceRef; box progress.snapshotRef; box (DiagJson.esc (terminalFlowSemanticSeedClosureProgressSourceText progress.source)); box progress.denominatorRevision; box closure.semanticSeedRetiredCost; box closure.semanticSeedGeneration; box closure.semanticSeedRevision; box closure.parsedAstSeedTotal; box progress.semanticRetiredCost; box progress.denominatorCost; box progress.progressLowBp; box (max 0L (Environment.TickCount64 - progress.observedAtMs)); box (DiagJson.esc (DiagJson.terminalOutcomeCandidateDeliveryDecisionText delivery)) |])
                    true
                else false
            | _ -> false

        let private terminalFlowQapWatchRearmForSemanticClosure (state:TerminalFlowGlobalReducerState) =
            match state.qapMaturityWatch with
            | Some watch when terminalFlowQapGenerationAllowsRebase watch.generationAuthority.stage ->
                let semanticEpochNow = DiagJson.terminalSemanticAuthorityCountNow()
                let frontierEpochNow = DiagJson.terminalFrontierProgressEpochNow()
                let frontierProgressBpNow = DiagJson.terminalFrontierProgressBpNow()
                let completionEpochNow = DiagJson.terminalCompletionCreditEpochNow()
                let completedCostNow = DiagJson.terminalCompletionCreditCostNow()
                let request =
                    terminalFlowQapWatchRebaseRequestFor
                        (Some TerminalFlowQapRebaseFinalizerDeferred)
                        watch
                        semanticEpochNow
                        frontierEpochNow
                        frontierProgressBpNow
                        completionEpochNow
                        completedCostNow
                let operationalSnapshot = terminalFlowOperationalAuthoritySnapshotNow ()
                let operationalGraphRef = CompilerKernelV2.OperationalAuthoritySnapshotOps.graphRef operationalSnapshot
                let operationalRuntimeAuthorityRef = CompilerKernelV2.OperationalAuthoritySnapshotOps.runtimeAuthorityRef operationalSnapshot
                let operationalSemanticEpoch = CompilerKernelV2.OperationalAuthoritySnapshotOps.semanticEpoch operationalSnapshot
                let operationalSnapshotRef = CompilerKernelV2.OperationalAuthoritySnapshotOps.snapshotRef operationalSnapshot
                let rebaseReceipt =
                    { receiptRef = request.rebaseReceiptRef
                      parentGeneration = request.parentGeneration
                      childGeneration = request.childGeneration
                      fixpointRef = request.fixpointRef
                      reason = request.reason
                      stageBefore = request.stageBefore
                      stageAfter = request.stageAfter
                      relationDelta = request.relationDelta
                      fromOperationalRevision = request.fromOperationalRevision
                      toOperationalRevision = request.toOperationalRevision
                      operationalSnapshotRef = request.operationalSnapshotRef
                      reducerSequence = state.revision }
                let generationAuthority =
                    { generation = request.childGeneration
                      parentGeneration = Some request.parentGeneration
                      stage = TerminalFlowQapGenerationAwaiting
                      fixpointRef = watch.fixpointRef
                      relationSetHash = request.relationDelta.childRelationSetHash
                      operationalRevision = request.toOperationalRevision
                      operationalGraphRef = operationalGraphRef
                      operationalRuntimeAuthorityRef = operationalRuntimeAuthorityRef
                      operationalSemanticEpoch = operationalSemanticEpoch
                      operationalSnapshotRef = operationalSnapshotRef
                      lastRebaseReceipt = Some rebaseReceipt
                      finalization = None
                      finalizationReceiptRef = None }
                let rearmed =
                    { watch with
                        generationAuthority = generationAuthority
                        observedMaterialAgeMs = 0L
                        observedSemanticEpoch = semanticEpochNow
                        observedFrontierEpoch = frontierEpochNow
                        observedFrontierProgressBp = frontierProgressBpNow
                        observedCompletionEpoch = completionEpochNow
                        observedCompletedCost = completedCostNow
                        observedAtMs = Environment.TickCount64
                        rebaseCount = watch.rebaseCount + 1L
                        maturity = TerminalFlowQapWatchAwaitingWitness }
                Some(request, rearmed)
            | _ -> None

        [<StructuralEquality; NoComparison>]
        type private TerminalFlowQapSemanticClosureRearmDecisionId =
            | TerminalFlowQapSemanticClosureRearmNotRequired
            | TerminalFlowQapSemanticClosureRearmProgressEpochAdvanced of observedEpoch:int64 * currentEpoch:int64
            | TerminalFlowQapSemanticClosureRearmOperationalWitnessStale of TerminalFlowQapOperationalWitnessRelationId

        let private terminalFlowQapSemanticClosureRearmDecisionFor (watch:TerminalFlowGlobalQapMaturityWatch) =
            let progressSemanticEpochNow = DiagJson.terminalSemanticAuthorityCountNow()
            let operationalSnapshotNow = terminalFlowOperationalAuthoritySnapshotNow ()
            let operationalRelation =
                terminalFlowQapOperationalWitnessRelationFor watch.generationAuthority operationalSnapshotNow
            if watch.observedSemanticEpoch <> progressSemanticEpochNow then
                TerminalFlowQapSemanticClosureRearmProgressEpochAdvanced(watch.observedSemanticEpoch, progressSemanticEpochNow)
            elif not (terminalFlowQapOperationalWitnessRelationAllowsMaturity operationalRelation) then
                TerminalFlowQapSemanticClosureRearmOperationalWitnessStale operationalRelation
            else
                TerminalFlowQapSemanticClosureRearmNotRequired

        let private terminalFlowQapSemanticClosureRearmDecisionText = function
            | TerminalFlowQapSemanticClosureRearmNotRequired -> "NotRequired"
            | TerminalFlowQapSemanticClosureRearmProgressEpochAdvanced(observedEpoch, currentEpoch) ->
                FastRuntimeFormat.format "ProgressEpochAdvanced(observed=%d|current=%d)" [| box observedEpoch; box currentEpoch |]
            | TerminalFlowQapSemanticClosureRearmOperationalWitnessStale relation ->
                "OperationalWitnessStale(" + terminalFlowQapOperationalWitnessRelationText relation + ")"

        let private terminalFlowPendingIntentMonotoneCompatible captured current =
            captured = current
            || (match captured, current with
                | TerminalFlowPendingQuarantine, TerminalFlowPendingBuildOk
                | TerminalFlowPendingNoFurther, TerminalFlowPendingBuildOk -> true
                | _ -> false)

        let private terminalFlowPendingPromotionText = function
            | TerminalFlowPendingPromotionNotRequired -> "not_required"
            | TerminalFlowPendingPromotionAwaitRecovery intent -> "await_recovery:" + terminalFlowPendingIntentText intent
            | TerminalFlowPendingPromotionReady(priorIntent, promoted, recoveryRef) ->
                let admissionRef = terminalFlowPendingAdmissionRef promoted.admission
                FastRuntimeFormat.format "promoted:%s->%s|recovery_ref=%u|admission_ref=%u" [| box (terminalFlowPendingIntentText priorIntent); box (terminalFlowPendingIntentText promoted.intent); box (terminalFlowIdentityRefDigest recoveryRef); box admissionRef |]

        let private terminalFlowQapPostCommitStageResultText stageName = function
            | Ok envelope ->
                let proofText, _, _, _, proofRef, _ = terminalFlowQapPostCommitProofProjection envelope.proof
                FastRuntimeFormat.format "%sCompleted(plan_ref=%u|transaction_ref=%u|proof_ref=%u|proof=%s)" [| box stageName; box envelope.planRef; box envelope.transaction.transactionRef; box proofRef; box proofText |]
            | Error missingEvidence ->
                FastRuntimeFormat.format "%sMissingEvidence(count=%d|missing=%s)" [| box stageName; box ((terminalFlowQapMissingEvidenceCount missingEvidence)); box (terminalFlowQapMissingEvidenceText missingEvidence) |]

        let private terminalFlowQapPostCommitCompletionText = function
            | TerminalFlowQapPostCommitFairnessCompleted result ->
                terminalFlowQapPostCommitStageResultText "PostCommitFairness" result
            | TerminalFlowQapPostCommitRecoveryCompleted result ->
                terminalFlowQapPostCommitStageResultText "PostCommitRecovery" result
            | TerminalFlowQapPostCommitOwnerWorkDagCompleted result ->
                terminalFlowQapPostCommitStageResultText "PostCommitOwnerWorkDag" result

        let private terminalFlowOwnerCloseDecisionTag = function
            | TerminalFlowOwnerCloseDeferredMaterialDelta _ -> "deferred_material_delta"
            | TerminalFlowOwnerCloseAwaitConservedCreditQuiescence _ -> "await_conserved_credit_quiescence"
            | TerminalFlowOwnerCloseAlreadyExhausted _ -> "already_exhausted"

        let private terminalFlowGlobalServerEventText = function
            | TerminalFlowGlobalServerEvaluatorRootResolved(receiptId, resolvedAtMs, evidenceRef, resolvedNow) ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(EvaluatorRootResolved|receipt_ref=%u|resolved_at_ms=%d|evidence_ref=%u|resolved_now=%b)" [| box (terminalFlowRootReceiptRefText receiptId); box resolvedAtMs; box evidenceRef; box resolvedNow |]
            | TerminalFlowGlobalServerTerminalOutcomeReady pending ->
                let maturity = terminalFlowPendingOutcomeMaturity pending.intent
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(TerminalOutcomeReady|intent=%s|maturity_du=%s|maturity_ref=%u|terminal_ref=%u|fill_ref=%u)" [| box (terminalFlowPendingIntentText pending.intent); box (terminalFlowOutcomeMaturityText maturity); box (terminalFlowOutcomeMaturityRef maturity); box (terminalFlowPendingTerminalReceiptDigest pending); box (terminalFlowPendingFillDigest pending) |]
            | TerminalFlowGlobalServerDispatchRequested request ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(DispatchRequested|request_ref=%u|dispatch_key_ref=%u|root_ref=%u|terminal_ref=%u|fill_ref=%u|constitution_lineage_ref=%u|pending_ref=%u|admission_ref=%u|admission_identity_ref=%u|publication=%s)" [| box (request.requestRef); box request.joinKey.keyRef; box (terminalFlowIdentityRefDigest (terminalFlowDispatchJoinRootRef request.joinKey)); box (terminalFlowIdentityRefDigest (terminalFlowDispatchJoinTerminalRef request.joinKey)); box (terminalFlowIdentityRefDigest (terminalFlowDispatchJoinFillRef request.joinKey)); box request.constitutionLineageRef; box request.pendingTerminalRef; box request.admissionRef; box request.admissionIdentityRef; box (terminalFlowDispatchPublicationText request.publication) |]
            | TerminalFlowGlobalServerDispatchExecuted(issuance, handoff) ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(DispatchExecuted|issuance_ref=%u|credential_bundle_ref=%u|constitution_ref=%u|request_ref=%u|handoff_ref=%u)" [| box issuance.issuanceRef; box issuance.credentials.bundleRef; box issuance.constitution.constitutionRef; box issuance.requestRef; box (terminalFlowStableAuthorityRef (TerminalFlowNativeHandoffIdentity handoff)) |]
            | TerminalFlowGlobalServerQapFixpointObserved(fixpointRef, fixpoint, materialAgeMs, maturity) ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(QapFixpointObserved|fixpoint_ref=%u|material_progress_age_ms=%d|maturity_du=%s|terminal_mature=%b|relations_consumed=%b)" [| box (terminalFlowDurableRefValue fixpointRef); box materialAgeMs; box (terminalFlowQapMaturityObservationText maturity); box (terminalFlowQapMaturityObservationIsAuthoritative maturity); box (terminalFlowQapFixpointAllRelationsConsumed fixpoint) |]
            | TerminalFlowGlobalServerQapPostCommitEffectCompleted completion ->
                "TerminalFlowGlobalServerEvent(" + terminalFlowQapPostCommitCompletionText completion + ")"
            | TerminalFlowGlobalServerQapWatchRebaseRequested request ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(QapWatchRebaseRequested|request_ref=%u|rebase_receipt_ref=%u|fixpoint_ref=%u|parent_generation=%d|child_generation=%d|reason=%s|stage=%s->%s|relation_set=%u->%u|carried=%d|invalidated=%d|discovered=%d|rediscovery_required=%b|from_semantic_epoch=%d|to_semantic_epoch=%d|from_frontier_epoch=%d|to_frontier_epoch=%d|frontier_progress_bp=%d|from_completion_epoch=%d|to_completion_epoch=%d|completed_cost=%d)" [| box request.requestRef; box request.rebaseReceiptRef; box (terminalFlowDurableRefValue request.fixpointRef); box (terminalFlowQapGenerationValue request.parentGeneration); box (terminalFlowQapGenerationValue request.childGeneration); box (terminalFlowQapRebaseReasonText request.reason); box (terminalFlowQapGenerationStageText request.stageBefore); box (terminalFlowQapGenerationStageText request.stageAfter); box request.relationDelta.parentRelationSetHash; box request.relationDelta.childRelationSetHash; box request.relationDelta.carriedRelationRefs.Length; box request.relationDelta.invalidatedRelationRefs.Length; box request.relationDelta.discoveredRelationRefs.Length; box request.relationDelta.rediscoveryRequired; box request.fromSemanticEpoch; box request.toSemanticEpoch; box request.fromFrontierEpoch; box request.toFrontierEpoch; box request.frontierProgressBp; box request.fromCompletionEpoch; box request.toCompletionEpoch; box request.completedCost |]
            | TerminalFlowGlobalServerProgressEvidenceObserved evidence ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(ProgressEvidenceObserved|snapshot_ref=%u|snapshot_seq=%d|phase=%s|phase_progress_bp=%d|discovered=%d|retired=%d|remaining=%d|blocked=%d|queue_depth=%d|active_workers=%d|queue_kinds=%s|gate=%s|semantic_digest_ref=%u|semantic_epoch=%d|semantic_receipts=%d|canonical_roots=%d)" [| box (terminalFlowIdentityRefDigest evidence.snapshotRef); box evidence.snapshotSequence; box (terminalFlowProgressPhaseText evidence.frontier.phase); box (terminalFlowProgressPhaseBp evidence); box evidence.frontier.discovered; box evidence.frontier.retired; box (terminalFlowProgressRemaining evidence); box evidence.frontier.blocked; box evidence.frontier.queueDepth; box evidence.frontier.activeWorkers; box (terminalFlowQueueKindCountsText evidence.frontier.queueKindCounts); box (terminalFlowProgressGateConditionFor evidence |> terminalFlowProgressGateConditionText); box (terminalFlowIdentityRefDigest evidence.semanticDigest.digestRef); box evidence.semanticDigest.semanticEpoch; box evidence.semanticDigest.semanticReceiptCount; box evidence.semanticDigest.canonicalRootCount |]
            | TerminalFlowGlobalServerTopologyGateTransitionObserved transition ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(TopologyGateTransitionObserved|gate_ref=%u|cause=%s|before_queue=%d|after_queue=%d|progress_snapshot_ref=%u|opened_at_ms=%d)" [| box (terminalFlowIdentityRefDigest transition.gateRef); box (terminalFlowTopologyGateCauseText transition.cause); box transition.beforeQueueDepth; box transition.afterQueueDepth; box (terminalFlowIdentityRefDigest transition.progressSnapshotRef); box transition.openedAtMs |]
            | TerminalFlowGlobalServerReplayFairnessObserved sample ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(ReplayFairnessObserved|admission_ref=%u|admission_identity_ref=%u|actor_binding_ref=%u|credential_ledger_ref=%u|fairness_epoch_ref=%u|sample_ref=%u|driver_ref=%u|lane=%s|q=%d|a=%d|retired=%d|score=%d|snapshot_ref=%u|sampled_at_ms=%d)" [| box sample.admissionRef; box sample.admissionIdentityRef; box sample.actorBindingRef; box sample.credentialLedgerRef; box (terminalFlowIdentityRefDigest sample.fairnessEpochRef); box (terminalFlowIdentityRefDigest sample.sampleRef); box (terminalFlowIdentityRefDigest sample.driverRef); box (terminalFlowReplayDriverLaneText sample.lane); box sample.queueDepth; box sample.activeWorkers; box sample.retiredWork; box sample.starvationScore; box (terminalFlowIdentityRefDigest sample.progressSnapshotRef); box sample.sampledAtMs |]
            | TerminalFlowGlobalServerAdmissionRunEndFixtureProven certificate ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(AdmissionRunEndFixtureProduction|certificate_ref=%u|fixture_ref=%u|genesis_ref=%u|reducer_path_ref=%u|interpreter_kernel_ref=%u|transaction_ref=%u|issuance_ref=%u|issue_event_ref=%u|consumption_event_ref=%u|run_end_ref=%u|physical_exit_ref=%u|negative_count=%d|final_revision=%d)" [| box certificate.certificateRef; box certificate.fixtureRef; box certificate.reducerGenesisRef; box certificate.reducerPathRef; box certificate.interpreterKernelRef; box certificate.transactionRef; box certificate.issuanceRef; box certificate.issueEventRef; box certificate.consumptionEventRef; box certificate.runEndReceiptRef; box certificate.physicalExitReceiptRef; box certificate.negativeVerdicts.Length; box certificate.finalRevision |]
            | TerminalFlowGlobalServerQueueOnlyRecoveryFolded decision ->
                sprintf "TerminalFlowGlobalServerEvent(QueueOnlyRecoveryFolded|decision=%s|authority=single_reducer_fairness_ledger)" (terminalFlowQueueRecoveryDecisionText decision)
            | TerminalFlowGlobalServerArtifactCommitObserved commit ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(ArtifactCommitObserved|terminal_ref=%u|fill_ref=%u|writer_job_ref=%u|artifact_receipt_ref=%u|exit_witness_ref=%u|run_end_receipt_ref=%u)" [| box (terminalFlowIdentityRefDigest commit.terminalReceiptRef); box (TerminalFlowFillKeyId.digest commit.fillKey); box (terminalFlowDurableRefValue commit.writerJobRef); box (terminalFlowDurableRefValue commit.artifactReceiptRef); box (terminalFlowDurableRefValue commit.exitWitnessRef); box (terminalFlowDurableRefValue commit.runEndReceiptRef) |]
            | TerminalFlowGlobalServerExitWitnessReady request ->
                let reasonId = terminalFlowPhysicalExitChainReason request.physicalChain
                let reasonText = DiagJson.terminalJsonPhysicalExitReasonText reasonId
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(ExitWitnessReady|request_ref=%u|fill_ref=%u|exit=%d|reason_ref=%u|chain=%s|draft_authority=false)" [| box (request.requestRef); box (terminalFlowMintedRefOf "fill_ref" request.fillKey); box request.exitCode; box (terminalFlowMintedRefOf "exit_reason_ref" reasonText); box (terminalFlowPhysicalExitChainText request.physicalChain) |]
            | TerminalFlowGlobalServerWatchdogPetitioned petition ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(WatchdogPetitioned|petition_ref=%u|reason=%s|observed_age_ms=%d|progress_snapshot_ref=%u|requested_at_ms=%d|authority=petition_only)" [| box (terminalFlowIdentityRefDigest petition.petitionRef); box (terminalFlowWatchdogPetitionReasonText petition.reason); box petition.observedAgeMs; box (petition.progressSnapshotRef |> Option.map terminalFlowIdentityRefDigest |> Option.defaultValue 0u); box petition.requestedAtMs |]
            | TerminalFlowGlobalServerHostShutdownRequested request ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerEvent(HostShutdownRequested|request_ref=%u|reason=%s|observed_at_ms=%d|root_ref=%u|terminal_ref=%u|authority=single_reducer_reconciliation_required)" [| box (terminalFlowIdentityRefDigest request.requestRef); box (terminalFlowHostShutdownReasonText request.reason); box request.observedAtMs; box (request.rootReceiptRef |> Option.defaultValue 0u); box (request.terminalOutcomeRef |> Option.defaultValue 0u) |]
            | TerminalFlowGlobalServerOwnerWorkDagProduced producer ->
                sprintf "TerminalFlowGlobalServerEvent(OwnerWorkDagProduced|producer=%s|authority=single_reducer_owner_workdag_transaction)"
                    (terminalFlowOwnerWorkDagProducerText producer)
            | TerminalFlowGlobalServerTerminalOrderCutoverObserved cutover ->
                sprintf "TerminalFlowGlobalServerEvent(TerminalOrderCutoverObserved|cutover=%s|authority=typed_terminal_order_corridor)"
                    (terminalFlowTerminalOrderCutoverText cutover)
            | TerminalFlowGlobalServerTerminalOrderCutoverMinted receipt ->
                sprintf "TerminalFlowGlobalServerEvent(TerminalOrderCutoverMinted|%s|authority=qap_owner_workdag_terminal_order_minter)"
                    (terminalFlowTerminalOrderMinterReceiptText receipt)
            | TerminalFlowGlobalServerProjectionCoalesced directive ->
                sprintf "TerminalFlowGlobalServerEvent(ProjectionCoalesced|%s|authority=change_key_no_self_mutation)"
                    (terminalFlowProjectionCoalescingText directive)
            | TerminalFlowGlobalServerCriticalPathEtaObserved eta ->
