        let private terminalFlowQapProofRejectionIsFatal = function
            | TerminalFlowQapProofRejectedProgressEvidence _
            | TerminalFlowQapProofSchedulerReleaseRejected _
            | TerminalFlowQapProofFinalizationTransactionMismatch _
            | TerminalFlowQapProofFinalizationExactOnceMismatch _
            | TerminalFlowQapProofDispositionPlanRefZero
            | TerminalFlowQapProofDispositionTransactionRefZero
            | TerminalFlowQapProofPendingLineageRejected _
            | TerminalFlowQapProofCompletionLineageMismatch _
            | TerminalFlowQapProofConstructionContradiction _
            | TerminalFlowQapProofOwnerDebtCorridorRejected _ -> true
            | TerminalFlowQapProofMissingRoot
            | TerminalFlowQapProofMissingProgressEvidence
            | TerminalFlowQapProofMissingPendingTerminal
            | TerminalFlowQapProofFairnessNotReleased _
            | TerminalFlowQapProofSchedulerLineageIncomplete _
            | TerminalFlowQapProofQueueRecoveryNotReady _
            | TerminalFlowQapProofGreenPathNotReady
            | TerminalFlowQapProofOwnerLedgerNotClosed _
            | TerminalFlowQapProofWorkDagTailNotClosed _
            | TerminalFlowQapProofSccUnclosed _
            | TerminalFlowQapProofResidualWorkDagBlocked _
            | TerminalFlowQapProofFinalizationNotEnqueued
            | TerminalFlowQapProofPostCommitNotApplied -> false

        let private terminalFlowQapProofHudBlockerFor = function
            | TerminalFlowQapProofMissingRoot
            | TerminalFlowQapProofOwnerLedgerNotClosed _ -> CompilerConsoleHud88.ReducerHudOwnerClosure
            | TerminalFlowQapProofWorkDagTailNotClosed _
            | TerminalFlowQapProofSccUnclosed _
            | TerminalFlowQapProofResidualWorkDagBlocked _ -> CompilerConsoleHud88.ReducerHudWorkDagClosure
            | TerminalFlowQapProofFairnessNotReleased _
            | TerminalFlowQapProofSchedulerLineageIncomplete _
            | TerminalFlowQapProofSchedulerReleaseRejected _
            | TerminalFlowQapProofQueueRecoveryNotReady _
            | TerminalFlowQapProofFinalizationNotEnqueued
            | TerminalFlowQapProofFinalizationTransactionMismatch _
            | TerminalFlowQapProofFinalizationExactOnceMismatch _
            | TerminalFlowQapProofDispositionPlanRefZero
            | TerminalFlowQapProofDispositionTransactionRefZero
            | TerminalFlowQapProofPendingLineageRejected _
            | TerminalFlowQapProofCompletionLineageMismatch _
            | TerminalFlowQapProofConstructionContradiction _
            | TerminalFlowQapProofOwnerDebtCorridorRejected _
            | TerminalFlowQapProofPostCommitNotApplied -> CompilerConsoleHud88.ReducerHudSchedulerCausality
            | TerminalFlowQapProofMissingProgressEvidence
            | TerminalFlowQapProofRejectedProgressEvidence _
            | TerminalFlowQapProofMissingPendingTerminal
            | TerminalFlowQapProofGreenPathNotReady -> CompilerConsoleHud88.ReducerHudSemanticFactDebt

        let private terminalFlowQapPostCommitDispositionFor
            (proofDecision:TerminalFlowQapProofBuildResult<'Stage>) =
            match proofDecision with
            | Ok _ -> TerminalFlowQapPostCommitReady
            | Error missingEvidence ->
                missingEvidence
                |> terminalFlowQapMissingEvidenceToList
                |> List.map terminalFlowQapProofHudBlockerFor
                |> List.distinct
                |> CompilerConsoleHud88.publishReducerHudTerminalBlockers
                if missingEvidence |> terminalFlowQapMissingEvidenceToList |> List.exists terminalFlowQapProofRejectionIsFatal then
                    TerminalFlowQapPostCommitFatal missingEvidence
                else
                    TerminalFlowQapPostCommitAwaitEvidence missingEvidence

        let private terminalFlowQapPostCommitDispositionText = function
            | TerminalFlowQapPostCommitReady -> "Ready"
            | TerminalFlowQapPostCommitAwaitEvidence missingEvidence -> "AwaitEvidence(" + terminalFlowQapMissingEvidenceText missingEvidence + ")"
            | TerminalFlowQapPostCommitFatal missingEvidence -> "Fatal(" + terminalFlowQapMissingEvidenceText missingEvidence + ")"

        let private terminalFlowQapPostCommitDispositionReceiptFor reducerRevision planRef transactionRef disposition =
            let planWitness =
                terminalFlowNonZeroRefResult
                    TerminalFlowQapProofDispositionPlanRefZero
                    planRef
            let transactionWitness =
                terminalFlowNonZeroRefResult
                    TerminalFlowQapProofDispositionTransactionRefZero
                    transactionRef
            match planWitness, transactionWitness with
            | Ok planRefWitness, Ok transactionRefWitness ->
                let dispositionText = terminalFlowQapPostCommitDispositionText disposition
                TerminalFlowQapPostCommitDispositionReceiptCommitted {
                    receiptRef =
                        TerminalFlowDurableRef(
                            terminalFlowMintedRefOf
                                "terminal_qap_post_commit_disposition_receipt_ref"
                                (FastRuntimeFormat.format "%u:%u:%d:%s" [| box planRef; box transactionRef; box reducerRevision; box dispositionText |]))
                    planRef = planRefWitness
                    transactionRef = transactionRefWitness
                    disposition = disposition
                    reducerRevision = reducerRevision }
            | _ ->
                let missingEvidence =
                    [ match planWitness with
                      | Error missing -> yield missing
                      | Ok _ -> ()
                      match transactionWitness with
                      | Error missing -> yield missing
                      | Ok _ -> () ]
                TerminalFlowQapPostCommitDispositionReceiptRejected (
                    terminalFlowQapMissingEvidenceSetOfList
                        TerminalFlowQapProofDispositionReceiptConstruction
                        (if planRef <> 0u then planRef else transactionRef)
                        missingEvidence)

