            | TerminalFlowQapPostCommitRunRecovery envelope -> FastRuntimeFormat.format "PostCommitRecovery(plan_ref=%u|transaction_ref=%u|stage=%d)" [| box envelope.planRef; box envelope.transaction.transactionRef; box envelope.stageOrdinal |]
            | TerminalFlowQapPostCommitRunOwnerWorkDag envelope -> FastRuntimeFormat.format "PostCommitOwnerWorkDag(plan_ref=%u|transaction_ref=%u|stage=%d)" [| box envelope.planRef; box envelope.transaction.transactionRef; box envelope.stageOrdinal |]

