            | TerminalFlowQapPostCommitAwaitingCertifiedEvidence -> "awaiting_certified_evidence"
            | TerminalFlowQapPostCommitActivePlan -> "active_plan"
            | TerminalFlowQapPostCommitAppliedPlan -> "applied_plan"

        let private terminalFlowQapPostCommitStateProjection = function
            | TerminalFlowQapPostCommitIdle -> TerminalFlowQapPostCommitStageIdle, 0u, 0u, 0, 0
            | TerminalFlowQapPostCommitAwaitingEvidence awaiting ->
                TerminalFlowQapPostCommitStageAwaitingEvidence, awaiting.planRef, awaiting.transaction.transactionRef, awaiting.stageOrdinal, (terminalFlowQapMissingEvidenceCount awaiting.missingEvidence)
            | TerminalFlowQapPostCommitFairnessScheduled envelope -> TerminalFlowQapPostCommitStageFairnessScheduled, envelope.planRef, envelope.transaction.transactionRef, envelope.stageOrdinal, 0
            | TerminalFlowQapPostCommitRecoveryScheduled envelope -> TerminalFlowQapPostCommitStageRecoveryScheduled, envelope.planRef, envelope.transaction.transactionRef, envelope.stageOrdinal, 0
            | TerminalFlowQapPostCommitOwnerWorkDagScheduled envelope -> TerminalFlowQapPostCommitStageOwnerWorkDagScheduled, envelope.planRef, envelope.transaction.transactionRef, envelope.stageOrdinal, 0
            | TerminalFlowQapPostCommitApplied envelope -> TerminalFlowQapPostCommitStageApplied, envelope.planRef, envelope.transaction.transactionRef, envelope.stageOrdinal, 0

        let private terminalFlowQapPostCommitProofDepth = function
            | TerminalFlowQapPostCommitIdle
            | TerminalFlowQapPostCommitAwaitingEvidence _ -> 0
            | TerminalFlowQapPostCommitFairnessScheduled envelope -> envelope.proof.depth
            | TerminalFlowQapPostCommitRecoveryScheduled envelope -> envelope.proof.depth
            | TerminalFlowQapPostCommitOwnerWorkDagScheduled envelope -> envelope.proof.depth
            | TerminalFlowQapPostCommitApplied envelope -> envelope.proof.depth

        let private terminalFlowGlobalFailureText = function
            | TerminalFlowFailureCanonicalRootReceiptDiverged(existingRef, incomingRef) ->
                sprintf "canonical_root_receipt_diverged|existing_ref=%u|incoming_ref=%u" existingRef incomingRef
            | TerminalFlowFailureOutcomeFillKeyDiverged(existingRef, incomingRef) ->
                sprintf "terminal_outcome_fill_key_diverged|existing_ref=%u|incoming_ref=%u" existingRef incomingRef
            | TerminalFlowFailureDispatchWithoutEvaluatorRoot requestRef ->
                sprintf "dispatch_without_evaluator_root|request_ref=%u" requestRef
            | TerminalFlowFailureDispatchWithoutTerminalOutcome requestRef ->
                sprintf "dispatch_without_terminal_outcome|request_ref=%u" requestRef
            | TerminalFlowFailureDispatchJoinKeyDiverged(requestRef, mismatches) ->
                let mismatchText =
                    mismatches
                    |> terminalFlowNonEmptyEvidenceToList
                    |> List.map terminalFlowDispatchJoinMismatchText
                    |> String.concat ","
                FastRuntimeFormat.format "dispatch_join_key_diverged|request_ref=%u|mismatches=%s" [| box requestRef; box mismatchText |]
            | TerminalFlowFailureDispatchExecutedWithoutIssuance(requestRef, observedStateRef) ->
                sprintf "dispatch_executed_without_issued_capability|request_ref=%u|observed_state_ref=%u" requestRef observedStateRef
            | TerminalFlowFailureDispatchLifecyclePoisoned(poisonRef, protocolRef, commandRef, rejectionCount) ->
                FastRuntimeFormat.format "dispatch_lifecycle_poisoned|poison_ref=%u|protocol_ref=%u|command_ref=%u|rejection_count=%d" [| box poisonRef; box protocolRef; box commandRef; box rejectionCount |]
            | TerminalFlowFailureExitUnauthorized(requestRef, failure) ->
                sprintf "exit_unauthorized|request_ref=%u|failure=%s" requestRef (terminalFlowGlobalExitAuthorizationFailureText failure)
            | TerminalFlowFailureObserverQuarantineRejected sourceRef ->
                sprintf "observer_quarantine_rejected|source_ref=%u|required_admission=reducer_owner_debt" sourceRef
            | TerminalFlowFailureObserverExitPetition petition ->
                FastRuntimeFormat.format "observer_exit_petition|petition_ref=%u|terminal_receipt_ref=%u|owner_closure_ref=%u|owner_closure_authority_ref=%u|owner_closure_authority=%s|workdag_closure_ref=%u|scheduler_causality_ref=%u|semantic_debt_ref=%u|exit=%d|source=%s" [| box petition.petitionRef; box petition.terminalReceiptRef; box petition.ownerClosureRef; box (DiagJson.observerTerminalOwnerClosureAuthorityRef petition.ownerClosureAuthority); box (DiagJson.observerTerminalOwnerClosureAuthorityText petition.ownerClosureAuthority); box petition.workDagClosureRef; box petition.schedulerCausalityRef; box petition.semanticDebtRef; box petition.requestedExitCode; box petition.sourceRowRef |]
            | TerminalFlowFailureTypedSemanticIngressEffect(effect, authorityRef) ->
                sprintf "typed_semantic_ingress_effect_failed_closed|authority_ref=%u|effect=%s"
                    authorityRef
                    (CompilerConsoleHud88.terminalFlowSemanticIngressEffectPlanText effect)
            | TerminalFlowFailurePendingOutcomeFailClosed(terminalReceiptRef, fillKey, admissionRef) ->
                FastRuntimeFormat.format "pending_outcome_fail_closed|terminal_ref=%u|fill_ref=%u|admission_ref=%u|fill=%s" [| box (terminalFlowIdentityRefDigest terminalReceiptRef); box (TerminalFlowFillKeyId.digest fillKey); box admissionRef; box (TerminalFlowFillKeyId.text fillKey) |]
            | TerminalFlowFailureQapFixpointMatured seal ->
                FastRuntimeFormat.format "qap_fixpoint_quarantine_sealed|seal_ref=%u|fixpoint_ref=%u|semantic_epoch=%d|frontier_epoch=%d|completion_epoch=%d|completed_cost=%d|stable_age_ms=%d|rebase_count=%d" [| box (terminalFlowDurableRefValue seal.sealRef); box (terminalFlowDurableRefValue seal.fixpointRef); box seal.semanticEpoch; box seal.frontierEpoch; box seal.completionEpoch; box seal.completedCost; box seal.stableAgeMs; box seal.rebaseCount |]
            | TerminalFlowFailureArtifactPromotionWithoutBreakthroughCovenant(fillKey, violations) ->
                sprintf "artifact_promotion_without_breakthrough_covenant|fill=%s|violations=%s"
                    (TerminalFlowFillKeyId.text fillKey)
                    (violations |> List.map terminalFlowBreakthroughConvergenceViolationText |> String.concat ";")
            | TerminalFlowFailureHostReturnedWithoutTotalOrder(rootRef, elapsedMs, remainingWork) ->
                FastRuntimeFormat.format "host_returned_without_terminal_total_order|root_ref=%u|elapsed_ms=%d|remaining_work=%d" [| box rootRef; box elapsedMs; box remainingWork |]
            | TerminalFlowFailureDeadmanExpired ageMs ->
                sprintf "process_global_material_deadman_expired|material_progress_age_ms=%d" ageMs
            | TerminalFlowFailureFinalQapDispatchBlocked(transactionRef, terminalRef, proofRef, blockers) ->
                FastRuntimeFormat.format "final_qap_dispatch_blocked|transaction_ref=%u|terminal_ref=%u|proof_ref=%u|blockers=%s" [| box transactionRef; box terminalRef; box proofRef; box (terminalFlowQapFinalOutcomeDispatchBlockerListText ";" blockers) |]
            | TerminalFlowFailureQapPostCommitBlocked(transactionRef, planRef, missingEvidence) ->
                FastRuntimeFormat.format "qap_post_commit_blocked|transaction_ref=%u|plan_ref=%u|missing_evidence=%s" [| box transactionRef; box planRef; box (terminalFlowQapMissingEvidenceText missingEvidence) |]
            | TerminalFlowFailureTypedTerminalExitRequested(requestedExitCode, reason, observationRef) ->
                FastRuntimeFormat.format "typed_terminal_exit_requested|requested_exit_code=%d|reason=%s|observation_ref=%u" [| box requestedExitCode; box (terminalFlowTypedTerminalExitReasonText reason); box observationRef |]

        let private terminalFlowPendingFailClosedFailure (pending:TerminalFlowGlobalPendingTerminal) =
            TerminalFlowFailurePendingOutcomeFailClosed(
                pending.terminalReceiptRef,
                pending.fillKeyId,
                terminalFlowPendingAdmissionRef pending.admission)

        let private terminalFlowGlobalFailureFillKey fallbackFillKey failure =
            match failure with
            | TerminalFlowFailurePendingOutcomeFailClosed(_, fillKey, _) -> TerminalFlowFillKeyId.text fillKey
            | TerminalFlowFailureObserverExitPetition petition -> sprintf "observer-petition:%u" petition.terminalReceiptRef
            | _ when not (String.IsNullOrWhiteSpace fallbackFillKey) -> fallbackFillKey
            | _ ->
                let failureRef = terminalFlowDurableRefOfText ("global-failure-fill|" + terminalFlowGlobalFailureText failure)
                "global-failure-fill:" + string (terminalFlowDurableRefValue failureRef)

        [<StructuralEquality; NoComparison>]
        type private TerminalFlowFailureSemanticIdentitySourceId =
            | TerminalFlowFailureSemanticIdentityFromFailurePayload
            | TerminalFlowFailureSemanticIdentityFromPendingTerminal
            | TerminalFlowFailureSemanticIdentityFromInstalledOutcome
            | TerminalFlowFailureSemanticIdentityFromKernelOutcome
            | TerminalFlowFailureSemanticIdentityFromActor
            | TerminalFlowFailureSemanticIdentityUnavailable

        let private terminalFlowFailureSemanticIdentitySourceText = function
            | TerminalFlowFailureSemanticIdentityFromFailurePayload -> "failure_payload"
            | TerminalFlowFailureSemanticIdentityFromPendingTerminal -> "pending_terminal"
            | TerminalFlowFailureSemanticIdentityFromInstalledOutcome -> "installed_outcome"
            | TerminalFlowFailureSemanticIdentityFromKernelOutcome -> "kernel_outcome"
            | TerminalFlowFailureSemanticIdentityFromActor -> "actor"
            | TerminalFlowFailureSemanticIdentityUnavailable -> "unavailable"

        type private TerminalFlowFailureSemanticIdentity = {
            terminalRef : uint32
            fillRef : uint32
            source : TerminalFlowFailureSemanticIdentitySourceId
        }

        let private terminalFlowGlobalFailureTerminalSemanticIdentity
            (state:TerminalFlowGlobalReducerState)
            failure
            : TerminalFlowFailureSemanticIdentity =
            let fromRefs source terminalRef fillRef =
                { terminalRef = terminalRef; fillRef = fillRef; source = source }
            let tryTyped source terminalReceiptRef fillKey =
                let terminalRef = terminalFlowIdentityRefDigest terminalReceiptRef
                let fillRef = TerminalFlowFillKeyId.digest fillKey
                if terminalRef <> 0u && fillRef <> 0u then Some (fromRefs source terminalRef fillRef)
                else None
            let actorOrUnavailable () =
                let _, terminalRef, fillRef =
                    terminalFlowReducerActorCoordinates state.qapOutcomeActorAuthority.actor
                if terminalRef <> 0u && fillRef <> 0u then
                    fromRefs TerminalFlowFailureSemanticIdentityFromActor terminalRef fillRef
                else
                    fromRefs TerminalFlowFailureSemanticIdentityUnavailable 0u 0u
            let kernelOrActor () =
                match state.kernel.outcome with
                | KernelOutcomeSealed(terminalReceiptRef, fillKey) ->
                    match tryTyped TerminalFlowFailureSemanticIdentityFromKernelOutcome terminalReceiptRef fillKey with
                    | Some identity -> identity
                    | None -> actorOrUnavailable ()
                | KernelOutcomeOpen -> actorOrUnavailable ()
            let installedOrKernel () =
                match terminalFlowOutcomeInstallationAdmission state.outcomeInstallation with
                | Some admission ->
                    match tryTyped TerminalFlowFailureSemanticIdentityFromInstalledOutcome admission.terminalReceiptRef admission.fillKey with
                    | Some identity -> identity
                    | None -> kernelOrActor ()
                | None -> kernelOrActor ()
            let pendingOrInstalled () =
                match state.pendingTerminal with
                | TerminalFlowPendingSlotCandidate pending ->
                    match tryTyped TerminalFlowFailureSemanticIdentityFromPendingTerminal pending.terminalReceiptRef pending.fillKeyId with
                    | Some identity -> identity
                    | None -> installedOrKernel ()
                | TerminalFlowPendingSlotAwaitingCandidate -> installedOrKernel ()
            match failure with
            | TerminalFlowFailurePendingOutcomeFailClosed(terminalReceiptRef, fillKey, _) ->
                match tryTyped TerminalFlowFailureSemanticIdentityFromFailurePayload terminalReceiptRef fillKey with
                | Some identity -> identity
                | None -> pendingOrInstalled ()
            | _ -> pendingOrInstalled ()

        let private terminalFlowGlobalServerCommandText = function
            | TerminalFlowGlobalServerAwaitDataflow reason ->
                sprintf "TerminalFlowGlobalServerCommand(AwaitDataflow|reason=%s)" (terminalFlowGlobalWaitReasonText reason)
            | TerminalFlowGlobalServerDrainQueuedReplay request ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerCommand(DrainQueuedReplay|request_ref=%u|sample_ref=%u|lane=%s|q=%d|a=%d|revision=%d)" [| box (terminalFlowIdentityRefDigest request.requestRef); box (terminalFlowIdentityRefDigest request.fairnessSampleRef); box (terminalFlowReplayDriverLaneText request.lane); box request.queueDepth; box request.activeWorkers; box request.requestedAtRevision |]
            | TerminalFlowGlobalServerRunQapPostCommitEffect effect ->
                "TerminalFlowGlobalServerCommand(" + terminalFlowQapPostCommitCommandText effect + ")"
            | TerminalFlowGlobalServerPublishDispatchRequest (request:TerminalFlowGlobalDispatchRequest) ->
                FastRuntimeFormat.format "TerminalFlowGlobalServerCommand(PublishDispatchRequest|request_ref=%u|dispatch_key_ref=%u|root_ref=%u|terminal_ref=%u|fill_ref=%u|publication=%s)" [| box (request.requestRef); box request.joinKey.keyRef; box (terminalFlowIdentityRefDigest (terminalFlowDispatchJoinRootRef request.joinKey)); box (terminalFlowIdentityRefDigest (terminalFlowDispatchJoinTerminalRef request.joinKey)); box (terminalFlowIdentityRefDigest (terminalFlowDispatchJoinFillRef request.joinKey)); box (terminalFlowDispatchPublicationText request.publication) |]
            | TerminalFlowGlobalServerConsumeStageToken transaction ->
                let authorization = transaction.authorization
                let token = transaction.actorLease.actorJoin
                let pending = transaction.postCommitCapability.pending
                FastRuntimeFormat.format "TerminalFlowGlobalServerCommand(ConsumeStageToken|transaction_ref=%u|actor_lease_ref=%u|consume_authority_ref=%u|issuance_ref=%u|credential_bundle_ref=%u|post_commit_plan_ref=%u|finalization_exact_once_ref=%u|post_commit_exact_once_ref=%u|post_commit_capability_ref=%u|capability_exact_once_ref=%u|admission_ref=%u|admission_identity_ref=%u|handoff_ref=%u|token_ref=%u|root_ref=%u|terminal_ref=%u|fill_ref=%u|stage=AffineDispatchPrepared)" [| box transaction.transactionRef; box transaction.actorLease.leaseRef; box authorization.consumeAuthorityRef; box authorization.issuance.issuanceRef; box authorization.issuance.credentials.bundleRef; box transaction.postCommitCapability.planRef; box transaction.postCommitCapability.finalizationExactOnceRef; box transaction.postCommitCapability.postCommitExactOnceRef; box transaction.postCommitCapability.capabilityRef; box transaction.postCommitCapability.exactOnceRef; box transaction.postCommitCapability.admissionRef; box transaction.postCommitCapability.admissionIdentityRef; box (terminalFlowStableAuthorityRef (TerminalFlowNativeHandoffIdentity authorization.ratifiedHandoff)); box (terminalFlowMintedRefOf "terminal_stage_token_ref" token.tokenId); box (terminalFlowRootReceiptRef token.rootReceiptRef); box (terminalFlowIdentityRefDigest pending.terminalReceiptRef); box (TerminalFlowFillKeyId.digest pending.fillKeyId) |]
            | TerminalFlowGlobalServerAuthorizeStageTokenSeal filled ->
                let fill = filled.fillReceipt
                FastRuntimeFormat.format "TerminalFlowGlobalServerCommand(AuthorizeStageTokenSeal|fill_commit_receipt_ref=%u|fill_command_ref=%u|push_actor_owner_ref=%u|token_ref=%u|actor_ref=%u|terminal_ref=%u|fill_ref=%u|ratification_ref=%u|stage=AffineStageTokenFilled)" [| box fill.receiptRef; box fill.fillCommandRef; box fill.pushActorOwnerRef; box fill.tokenRef; box fill.actorRef; box fill.terminalRef; box fill.fillRef; box fill.ratificationRef |]
            | TerminalFlowGlobalServerExecuteDispatch issuance ->
                let constitution = issuance.constitution
                let request = issuance.request
                FastRuntimeFormat.format "TerminalFlowGlobalServerCommand(ExecuteDispatch|issuance_ref=%u|credential_bundle_ref=%u|constitution_ref=%u|admission_ref=%u|admission_identity_ref=%u|green_path_ref=%u|order_ref=%u|request_ref=%u|fill_ref=%u|terminal_ref=%u)" [| box issuance.issuanceRef; box issuance.credentials.bundleRef; box constitution.constitutionRef; box constitution.admissionRef; box constitution.admissionIdentityRef; box constitution.greenPathDispatchReceipt.receiptRef; box constitution.totalOrderAwaitDispatch.receiptRef; box issuance.requestRef; box (terminalFlowIdentityRefDigest (terminalFlowDispatchJoinFillRef request.joinKey)); box (terminalFlowIdentityRefDigest (terminalFlowDispatchJoinTerminalRef request.joinKey)) |]
            | TerminalFlowGlobalServerCommitExit authorized ->
                let request = authorized.request
                let reasonId = terminalFlowPhysicalExitChainReason request.physicalChain
                let reasonText = DiagJson.terminalJsonPhysicalExitReasonText reasonId
                FastRuntimeFormat.format "TerminalFlowGlobalServerCommand(CommitExit|request_ref=%u|fill_ref=%u|exit=%d|reason_ref=%u|chain=%s|origin=%s|terminal_authority_ref=%u|reducer_physical_exit_receipt_ref=%u)" [| box (request.requestRef); box (terminalFlowMintedRefOf "fill_ref" request.fillKey); box request.exitCode; box (terminalFlowMintedRefOf "exit_reason_ref" reasonText); box (terminalFlowPhysicalExitChainText request.physicalChain); box (terminalFlowGlobalExitOriginText request.origin); box (terminalFlowTerminalAuthorityRef authorized.authority); box authorized.reducerPhysicalExitReceiptRef |]
            | TerminalFlowGlobalServerFailClosed failure ->
                sprintf "TerminalFlowGlobalServerCommand(FailClosed|failure=%s)" (terminalFlowGlobalFailureText failure)

        let private terminalFlowKernelInvariantFor root outcome actor dispatch exit =
            match root, outcome, actor, dispatch, exit with
            | KernelRootAwaitingEvaluator, _, _, _, _ -> KernelInvariantAwaitingRoot
            | _, KernelOutcomeOpen, _, _, _ -> KernelInvariantAwaitingOutcome
            | KernelRootResolved _, KernelOutcomeSealed _, KernelActorNoop, KernelDispatchReady _, _ -> KernelInvariantActorNoopWithJoinReady
            | KernelRootResolved _, KernelOutcomeSealed _, KernelActorArmed _, KernelDispatchAccepted _, KernelExitOpen -> KernelInvariantSatisfied
            | KernelRootResolved _, KernelOutcomeSealed _, KernelActorArmed _, KernelDispatchReady _, KernelExitOpen -> KernelInvariantSatisfied
            | KernelRootResolved _, KernelOutcomeSealed _, KernelActorArmed(phase, actorFillKey, _), KernelDispatchAccepted identity, KernelExitWitnessed(exitIdentity, exitCode, physicalChain)
                when TerminalFlowFillKeyId.reference actorFillKey = terminalFlowDispatchRequestIdentityFillRef identity
                     && terminalFlowDispatchRequestIdentityFillRef identity = terminalFlowExitRequestIdentityFillRef exitIdentity
                     && terminalFlowPhysicalExitChainMatchesExitCode exitCode phase physicalChain -> KernelInvariantSatisfied
            | _, _, _, _, KernelExitWitnessed _ -> KernelInvariantExitUnauthorized
            | _ -> KernelInvariantSatisfied

        let private terminalFlowKernelStageFor root outcome actor dispatch exit =
            let rootRef =
                match root with
                | KernelRootResolved(receiptRef, _, _) -> Some receiptRef
                | KernelRootAwaitingEvaluator -> None
            let terminalRef, fillRef =
                match outcome with
                | KernelOutcomeSealed(terminalReceiptRef, fillKey) -> Some terminalReceiptRef, Some (TerminalFlowFillKeyId.reference fillKey)
                | KernelOutcomeOpen -> None, None
            let dispatchRef =
                match dispatch with
                | KernelDispatchReady(identity, _, _) -> Some (terminalFlowDispatchRequestIdentityTypedRef identity)
                | KernelDispatchAccepted identity -> Some (terminalFlowDispatchRequestIdentityTypedRef identity)
                | KernelDispatchUnavailable -> None
            let writerRef, artifactRef, exitWitnessRef =
                match exit with
                | KernelExitWitnessed(_, _, physicalChain) ->
                    terminalFlowPhysicalExitChainWriterRef physicalChain,
                    terminalFlowPhysicalExitChainArtifactRef physicalChain,
                    terminalFlowPhysicalExitChainExitWitnessRef physicalChain
                | KernelExitOpen -> 0u, 0u, 0u
            let cap stageId = terminalFlowStageCapability stageId rootRef terminalRef fillRef dispatchRef writerRef artifactRef exitWitnessRef
            match root, outcome, actor, dispatch, exit with
            | KernelRootAwaitingEvaluator, _, _, _, _ ->
                TerminalFlowStageAwaitRoot (cap TerminalFlowKernelStageAwaitRoot)
            | KernelRootResolved _, KernelOutcomeOpen, _, _, _ ->
                TerminalFlowStageAwaitOutcome (cap TerminalFlowKernelStageAwaitOutcome)
            | KernelRootResolved _, KernelOutcomeSealed _, KernelActorArmed _, KernelDispatchAccepted _, KernelExitWitnessed _ ->
                TerminalFlowStageExitWitnessed (cap TerminalFlowKernelStageExitWitnessed)
            | KernelRootResolved _, KernelOutcomeSealed _, KernelActorArmed _, KernelDispatchAccepted _, _ when artifactRef <> 0u ->
                TerminalFlowStageArtifactCommitted (cap TerminalFlowKernelStageArtifactCommitted)
            | KernelRootResolved _, KernelOutcomeSealed _, KernelActorArmed _, KernelDispatchAccepted _, _ ->
                TerminalFlowStageWriterBound (cap TerminalFlowKernelStageWriterBound)
            | KernelRootResolved _, KernelOutcomeSealed _, _, KernelDispatchReady _, _
            | KernelRootResolved _, KernelOutcomeSealed _, KernelActorNoop, _, _ ->
                TerminalFlowStageReadyToDispatch (cap TerminalFlowKernelStageReadyToDispatch)
            | KernelRootResolved _, KernelOutcomeSealed _, _, _, _ ->
                TerminalFlowStageReadyToDispatch (cap TerminalFlowKernelStageReadyToDispatch)

        let private terminalFlowKernelStateFor revision root outcome actor dispatch exit =
            { root = root
              outcome = outcome
              actor = actor
              dispatch = dispatch
              exit = exit
              stage = terminalFlowKernelStageFor root outcome actor dispatch exit
              invariant = terminalFlowKernelInvariantFor root outcome actor dispatch exit
              revision = revision }

        let private terminalFlowKernelInitialState =
            // Migration : the process-global actor is not armed
            // at bootstrap.  The reducer must first own root, sealed outcome
            // and WorkDag-tail closure, then mint the causal stage token.
            terminalFlowKernelStateFor 0L KernelRootAwaitingEvaluator KernelOutcomeOpen KernelActorNoop KernelDispatchUnavailable KernelExitOpen

        let private terminalFlowKernelDispatchForRequest (request: TerminalFlowGlobalDispatchRequest) =
            KernelDispatchReady(
                request.identity,
                terminalFlowDispatchJoinRootRef request.joinKey,
                terminalFlowDispatchJoinTerminalRef request.joinKey)

        let private terminalFlowKernelAcceptedDispatchForRequest (request: TerminalFlowGlobalDispatchRequest) =
            KernelDispatchAccepted request.identity

        let private terminalFlowKernelExitForRequest (request: TerminalFlowGlobalExitRequest) =
            KernelExitWitnessed(
                request.identity,
                request.exitCode,
                request.physicalChain)

        let private terminalFlowKernelStageCode kernel =
            match kernel.invariant with
            | KernelInvariantActorNoopWithJoinReady -> TerminalFlowKernelProgressLostWakeupCandidate
            | KernelInvariantAwaitingRoot -> TerminalFlowKernelProgressAwaitRoot
            | KernelInvariantAwaitingOutcome -> TerminalFlowKernelProgressAwaitOutcome
            | KernelInvariantExitUnauthorized -> TerminalFlowKernelProgressExitUnauthorized
            | KernelInvariantSatisfied ->
                match kernel.root, kernel.outcome, kernel.actor, kernel.dispatch, kernel.exit with
                | KernelRootResolved _, KernelOutcomeSealed _, KernelActorArmed _, KernelDispatchAccepted _, KernelExitWitnessed _ -> TerminalFlowKernelProgressDone
                | KernelRootResolved _, KernelOutcomeSealed _, KernelActorArmed _, KernelDispatchAccepted _, _ -> TerminalFlowKernelProgressWriterBound
                | KernelRootResolved _, KernelOutcomeSealed _, KernelActorArmed _, KernelDispatchReady _, _ -> TerminalFlowKernelProgressReadyToDispatch
                | KernelRootResolved _, KernelOutcomeSealed _, KernelActorNoop, _, _ -> TerminalFlowKernelProgressAwaitActor
                | KernelRootResolved _, KernelOutcomeSealed _, _, _, _ -> TerminalFlowKernelProgressJoinReady
                | _ -> TerminalFlowKernelProgressing

        let private terminalFlowKernelProgressStageText = function
            | TerminalFlowKernelProgressLostWakeupCandidate -> "lost_wakeup_candidate"
            | TerminalFlowKernelProgressAwaitRoot -> "await_root"
            | TerminalFlowKernelProgressAwaitOutcome -> "await_outcome"
            | TerminalFlowKernelProgressExitUnauthorized -> "exit_unauthorized"
            | TerminalFlowKernelProgressDone -> "done"
            | TerminalFlowKernelProgressWriterBound -> "writer_bound"
            | TerminalFlowKernelProgressReadyToDispatch -> "ready_to_dispatch"
            | TerminalFlowKernelProgressAwaitActor -> "await_actor"
            | TerminalFlowKernelProgressJoinReady -> "join_ready"
            | TerminalFlowKernelProgressing -> "progressing"

        let private terminalFlowKernelInvariantText = function
            | KernelInvariantSatisfied -> "KernelInvariant(Satisfied)"
            | KernelInvariantAwaitingRoot -> "KernelInvariant(AwaitingRoot)"
            | KernelInvariantAwaitingOutcome -> "KernelInvariant(AwaitingOutcome)"
            | KernelInvariantActorNoopWithJoinReady -> "KernelInvariant(ActorNoopWithJoinReady)"
            | KernelInvariantExitUnauthorized -> "KernelInvariant(ExitUnauthorized)"

        let private terminalFlowKernelDurableProjectionFor (kernel:TerminalFlowKernelState) =
            let rootRef =
                match kernel.root with
                | KernelRootResolved(receiptRef, _, _) -> terminalFlowIdentityRefDigest receiptRef
                | KernelRootAwaitingEvaluator -> 0u
            let terminalRef, fillRef =
                match kernel.outcome with
                | KernelOutcomeSealed(terminalReceiptRef, fillKey) -> terminalFlowIdentityRefDigest terminalReceiptRef, TerminalFlowFillKeyId.digest fillKey
                | KernelOutcomeOpen -> 0u, 0u
            let dispatchRef =
                match kernel.dispatch with
                | KernelDispatchReady(identity, _, _) -> terminalFlowDispatchRequestIdentityRef identity
                | KernelDispatchAccepted identity -> terminalFlowDispatchRequestIdentityRef identity
                | KernelDispatchUnavailable -> 0u
            let writerRef, artifactRef, exitRef =
                match kernel.exit with
                | KernelExitWitnessed(_, _, physicalChain) ->
                    terminalFlowPhysicalExitChainWriterRef physicalChain,
                    terminalFlowPhysicalExitChainArtifactRef physicalChain,
                    terminalFlowPhysicalExitChainExitWitnessRef physicalChain
                | KernelExitOpen -> 0u, 0u, 0u
            let stage = terminalFlowKernelStageCode kernel
            let stageCapabilityTag = terminalFlowAnyKernelStageKind kernel.stage
            let stageCapabilityRef = terminalFlowAnyKernelStageRef kernel.stage
            let invariant = kernel.invariant
            let vectorHash = (((((((rootRef * 16777619u) ^^^ terminalRef) * 16777619u) ^^^ fillRef) * 16777619u) ^^^ dispatchRef) * 16777619u) ^^^ stageCapabilityRef ^^^ writerRef ^^^ artifactRef ^^^ exitRef
            { stageTag = stage
              stageCapabilityTag = stageCapabilityTag
              stageCapabilityRef = stageCapabilityRef
              invariantTag = invariant
              rootReceiptRef = rootRef
              terminalReceiptRef = terminalRef
              fillRef = fillRef
              dispatchRef = dispatchRef
              writerCapabilityRef = writerRef
              artifactReceiptRef = artifactRef
              exitRef = exitRef
              receiptVectorHash = vectorHash
              captureComplete = stage = TerminalFlowKernelProgressDone && (stageCapabilityTag = TerminalFlowKernelStageExitWitnessed || stageCapabilityTag = TerminalFlowKernelStageRunEndPrepared) && exitRef <> 0u
              decisionAuthority = TerminalFlowKernelReducerDurableProjection }

        let private terminalFlowReceiptProjectionKindText = function
            | TerminalFlowReceiptProjectionAwaitRoot -> "await_root"
            | TerminalFlowReceiptProjectionAwaitOutcome -> "await_outcome"
            | TerminalFlowReceiptProjectionReadyToDispatch -> "ready_to_dispatch"
            | TerminalFlowReceiptProjectionWriterBound -> "writer_bound"
            | TerminalFlowReceiptProjectionArtifactCommitted -> "artifact_committed"
            | TerminalFlowReceiptProjectionExitWitnessed -> "exit_witnessed"
            | TerminalFlowReceiptProjectionRunEndPrepared -> "run_end_prepared"

        let private terminalFlowExistentialReceiptProjectionFor (projection:TerminalFlowKernelDurableProjection) =
            let kind =
                match projection.stageCapabilityTag with
                | TerminalFlowKernelStageAwaitRoot -> TerminalFlowReceiptProjectionAwaitRoot
                | TerminalFlowKernelStageAwaitOutcome -> TerminalFlowReceiptProjectionAwaitOutcome
                | TerminalFlowKernelStageReadyToDispatch -> TerminalFlowReceiptProjectionReadyToDispatch
                | TerminalFlowKernelStageWriterBound -> TerminalFlowReceiptProjectionWriterBound
                | TerminalFlowKernelStageArtifactCommitted -> TerminalFlowReceiptProjectionArtifactCommitted
                | TerminalFlowKernelStageExitWitnessed -> TerminalFlowReceiptProjectionExitWitnessed
                | TerminalFlowKernelStageRunEndPrepared -> TerminalFlowReceiptProjectionRunEndPrepared
            let projectionRef =
                NativeCutoverStableRef.ref32
                    "terminal-receipt-projection"
                    [ terminalFlowReceiptProjectionKindText kind
                      string projection.stageCapabilityRef
                      string projection.receiptVectorHash
                      string projection.captureComplete ]
            { projectionKind = kind
              projectionRef = projectionRef
              stageCapabilityRef = projection.stageCapabilityRef
              receiptVectorHash = projection.receiptVectorHash
              rootReceiptRef = projection.rootReceiptRef
              terminalReceiptRef = projection.terminalReceiptRef
              fillRef = projection.fillRef
              dispatchRef = projection.dispatchRef
              writerCapabilityRef = projection.writerCapabilityRef
              artifactReceiptRef = projection.artifactReceiptRef
              exitRef = projection.exitRef
              captureComplete = projection.captureComplete }

        let inline private terminalFlowProjectionIdentityRefOrNone< ^Kind when ^Kind : (static member IdentityKindTag : unit -> uint32)> refValue =
            if refValue = 0u then None else Some (terminalFlowIdentityRefOfText (string refValue) : TerminalFlowIdentityRef< ^Kind>)

        let private terminalFlowProjectionDurableRefOrNone<'Kind> refValue =
            if refValue = 0u then None else Some (TerminalFlowDurableRef refValue : TerminalFlowDurableRef<'Kind>)

        let private terminalFlowTypedProjectionVectorFor causalSpineRef (projection:TerminalFlowKernelDurableProjection) : TerminalFlowTypedProjectionVector =
            let receiptProjection = terminalFlowExistentialReceiptProjectionFor projection
            let rootReceiptRef = terminalFlowProjectionIdentityRefOrNone<TerminalFlowCanonicalRootRefKind> projection.rootReceiptRef
            let terminalReceiptRef = terminalFlowProjectionIdentityRefOrNone<TerminalFlowTerminalReceiptRefKind> projection.terminalReceiptRef
            let fillRef = terminalFlowProjectionIdentityRefOrNone<TerminalFlowFillRefKind> projection.fillRef
            let dispatchRef = terminalFlowProjectionIdentityRefOrNone<TerminalFlowDispatchRefKind> projection.dispatchRef
            let identitySlots =
                [ match rootReceiptRef with
                  | Some value -> yield terminalFlowExistentialIdentitySlot TerminalFlowIdentityLaneRoot value
                  | None -> ()
                  match terminalReceiptRef with
                  | Some value -> yield terminalFlowExistentialIdentitySlot TerminalFlowIdentityLaneTerminalReceipt value
                  | None -> ()
                  match fillRef with
                  | Some value -> yield terminalFlowExistentialIdentitySlot TerminalFlowIdentityLaneFill value
                  | None -> ()
                  match dispatchRef with
                  | Some value -> yield terminalFlowExistentialIdentitySlot TerminalFlowIdentityLaneDispatch value
                  | None -> () ]
            { rootReceiptRef = rootReceiptRef
              terminalReceiptRef = terminalReceiptRef
              fillRef = fillRef
              dispatchRef = dispatchRef
              identitySlots = identitySlots
              stageCapabilityRef = TerminalFlowDurableRef projection.stageCapabilityRef
              receiptProjectionRef = TerminalFlowDurableRef receiptProjection.projectionRef
              causalSpineRef = TerminalFlowDurableRef causalSpineRef
              writerCapabilityRef = terminalFlowProjectionDurableRefOrNone<TerminalFlowWriterCapabilityRefKind> projection.writerCapabilityRef
              artifactReceiptRef = terminalFlowProjectionDurableRefOrNone<TerminalFlowArtifactReceiptRefKind> projection.artifactReceiptRef
              exitWitnessRef = terminalFlowProjectionDurableRefOrNone<TerminalFlowExitWitnessRefKind> projection.exitRef
              receiptVectorHash = projection.receiptVectorHash
              captureComplete = projection.captureComplete }

        let private terminalFlowOptionalIdentityDigest = function
            | Some r -> terminalFlowIdentityRefDigest r
            | None -> 0u

        let private terminalFlowOptionalDurableValue = function
            | Some r -> terminalFlowDurableRefValue r
            | None -> 0u

        let private terminalFlowTypedProjectionVectorRef (vector:TerminalFlowTypedProjectionVector) =
            let identityVectorHash =
                vector.identitySlots
                |> List.fold (fun state slot -> (state * 16777619u) ^^^ terminalFlowExistentialIdentitySlotDigest slot) 2166136261u
            let raw =
                FastRuntimeFormat.format "identity_vector=%u|identity_slots=%d|stage=%u|projection=%u|causal=%u|writer=%u|artifact=%u|exit=%u|capture=%b" [| box identityVectorHash; box vector.identitySlots.Length; box (terminalFlowDurableRefValue vector.stageCapabilityRef); box (terminalFlowDurableRefValue vector.receiptProjectionRef); box (terminalFlowDurableRefValue vector.causalSpineRef); box (terminalFlowOptionalDurableValue vector.writerCapabilityRef); box (terminalFlowOptionalDurableValue vector.artifactReceiptRef); box (terminalFlowOptionalDurableValue vector.exitWitnessRef); box vector.captureComplete |]
            terminalFlowMintedRefOf "typed_projection_vector_ref" raw

        let private terminalFlowTypedProjectionVectorJson (vector:TerminalFlowTypedProjectionVector) =
            FastRuntimeFormat.format "{\"typed_projection_ref\":%u,\"root_kind\":\"RootK\",\"terminal_kind\":\"TerminalReceiptK\",\"fill_kind\":\"FillK\",\"dispatch_kind\":\"DispatchK\",\"identity_slot_count\":%d,\"stage_capability_ref\":%u,\"receipt_projection_ref\":%u,\"causal_spine_ref\":%u,\"writer_ref\":%u,\"artifact_ref\":%u,\"exit_ref\":%u,\"capture_complete\":%b,\"erasure_authority\":\"terminal_flow_rank2_identity_projection\"}" [| box (terminalFlowTypedProjectionVectorRef vector); box vector.identitySlots.Length; box (terminalFlowDurableRefValue vector.stageCapabilityRef); box (terminalFlowDurableRefValue vector.receiptProjectionRef); box (terminalFlowDurableRefValue vector.causalSpineRef); box (terminalFlowOptionalDurableValue vector.writerCapabilityRef); box (terminalFlowOptionalDurableValue vector.artifactReceiptRef); box (terminalFlowOptionalDurableValue vector.exitWitnessRef); box vector.captureComplete |]

