            FastRuntimeFormat.format "kernel_stage=%s | stage_capability=%s | stage_capability_ref=%u | invariant_ref=%u | root_ref=%u | terminal_ref=%u | fill_ref=%u | dispatch_ref=%u | writer_ref=%u | artifact_ref=%u | exit_ref=%u | vector=%u | capture=%b" [| box (terminalFlowKernelProgressStageText projection.stageTag); box (terminalFlowKernelStageKindText projection.stageCapabilityTag); box projection.stageCapabilityRef; box (NativeCutoverStableRef.ref32 "terminal-projection-invariant" [terminalFlowKernelInvariantText projection.invariantTag]); box projection.rootReceiptRef; box projection.terminalReceiptRef; box projection.fillRef; box projection.dispatchRef; box projection.writerCapabilityRef; box projection.artifactReceiptRef; box projection.exitRef; box projection.receiptVectorHash; box projection.captureComplete |]

