            let projection = terminalFlowKernelDurableProjectionFor kernel
            { new IAnyTerminalFlowKernel with
                member _.StageTag = terminalFlowKernelProgressStageText projection.stageTag
                member _.DurableProjection = projection
                member _.RenderJson () = terminalFlowKernelProjectionJson projection
                member _.RenderHotFields () = terminalFlowKernelProjectionHotFields projection
                member _.RenderHud () =
                    "kernel=" + terminalFlowKernelProgressStageText projection.stageTag + " | stage_cap=" + terminalFlowKernelStageKindText projection.stageCapabilityTag + " | stage_ref=" + string projection.stageCapabilityRef + " | invariant=" + terminalFlowKernelInvariantText projection.invariantTag + " | refs=" + string projection.receiptVectorHash }

        let private terminalFlowStickyTailSnapshotHasNoResidual (snapshot:TerminalFlowStickyTailSnapshot) =
            snapshot.mutatingDepth = 0
            && snapshot.proceduralDepth = 0
            && snapshot.globalPending = 0
            && snapshot.globalQueue = 0
            && snapshot.globalActive = 0

        let private terminalFlowMutatingTailCapabilityOpenFor (snapshot:TerminalFlowStickyTailSnapshot) : TerminalFlowMutatingTailCapability<TerminalFlowMutatingTailOpenPhase> =
            { tailId = snapshot.tailId
              depth = max 0 snapshot.mutatingDepth
              evidenceRef =
                  NativeCutoverStableRef.ref32
                      "terminal-mutating-tail-open"
                      [ snapshot.tailId
                        string snapshot.mutatingDepth
                        snapshot.evidence ] }

        let private terminalFlowMutatingTailCapabilityDrainedFor (snapshot:TerminalFlowStickyTailSnapshot) : TerminalFlowMutatingTailCapability<TerminalFlowMutatingTailDrainedPhase> =
            { tailId = snapshot.tailId
              depth = 0
              evidenceRef =
                  NativeCutoverStableRef.ref32
                      "terminal-mutating-tail-drained"
                      [ snapshot.tailId
                        string snapshot.proceduralDrainPassCount
                        snapshot.evidence ] }

        let private terminalFlowProceduralResidualDetachedOwnerFor (snapshot:TerminalFlowStickyTailSnapshot) : TerminalFlowProceduralResidualOwner<TerminalFlowProceduralResidualDetachedPhase> =
            { ownerId = "owner:procedural-residual:" + snapshot.tailId
              closeKey = "close:procedural-residual:" + snapshot.tailId
              depth = max 0 snapshot.proceduralDepth
              drainPassCount = max 0 snapshot.proceduralDrainPassCount
              materialDeltaOnPass = max 0 snapshot.materialDeltaOnProceduralPass
              fixedPointRepeatCap = max 1 snapshot.fixedPointRepeatCap
              wakerStatus = snapshot.wakerStatus }

        let private terminalFlowTerminalizationPermitFor (snapshot:TerminalFlowStickyTailSnapshot) =
            if snapshot.mutatingDepth > 0 || not snapshot.mutatingTailDrained then
                TerminalFlowTerminalizationBlockedByMutatingTail(terminalFlowMutatingTailCapabilityOpenFor snapshot)
            elif terminalFlowStickyTailSnapshotHasNoResidual snapshot then
                TerminalFlowTerminalizationReady(terminalFlowMutatingTailCapabilityDrainedFor snapshot, None)
            else
                TerminalFlowTerminalizationReady(
                    terminalFlowMutatingTailCapabilityDrainedFor snapshot,
                    Some (terminalFlowProceduralResidualDetachedOwnerFor snapshot))

        let private terminalFlowWriterReadyGateFor (snapshot:TerminalFlowStickyTailSnapshot) =
            match terminalFlowTerminalizationPermitFor snapshot with
            | TerminalFlowTerminalizationBlockedByMutatingTail _ ->
                TerminalFlowStickyTailAwaitMutatingAggregate snapshot
            | TerminalFlowTerminalizationReady(_, proceduralOwner) ->
                TerminalFlowStickyTailWriterReady(snapshot, proceduralOwner)

        let private terminalFlowStickyTailSnapshotForGate = function
            | TerminalFlowStickyTailAwaitMutatingAggregate snapshot
            | TerminalFlowStickyTailWriterReady(snapshot, _)
            | TerminalFlowStickyTailDrained snapshot
            | TerminalFlowStickyTailQuarantineProceduralResidual(snapshot, _)
            | TerminalFlowStickyTailRejectUnboundedMutatingTail(snapshot, _) -> snapshot

        let private terminalFlowResidualDrainPassFor (snapshot:TerminalFlowStickyTailSnapshot) =
