            terminalFlowProceduralResidualOwnerFor snapshot
            |> fun owner -> phantomCloseKeyFor owner ("close:procedural-residual:" + snapshot.tailId)

        let private terminalFlowResidualForceClosePermitFor
            (snapshot:TerminalFlowStickyTailSnapshot)
            (matureEvidence:TerminalFlowResidualEvidence<TerminalFlowResidualMatureStage>)
            (lease:TerminalFlowOwnerLease)
            : TerminalFlowResidualForceClosePermit =
            let owner = terminalFlowProceduralResidualOwnerFor snapshot
            let closeKey = terminalFlowProceduralResidualCloseKeyFor snapshot
            let pureSidecarReceiptRef : TerminalFlowIdentityRef<TerminalFlowPureSidecarSemanticReceiptRefKind> =
                terminalFlowIdentityRefOfText ("pure-sidecar-semantic-receipt:" + snapshot.tailId)
            let writerLeaseBoundRef : TerminalFlowIdentityRef<TerminalFlowWriterLeaseBoundRefKind> =
                terminalFlowIdentityRefOfText (lease.leaseId + ":tail=" + snapshot.tailId)
            let workDagTailCloseReceiptRef : TerminalFlowIdentityRef<TerminalFlowWorkDagTailCloseReceiptRefKind> =
