                // exact-once identity. Repeated zero-delta passes must dereference
                // the same closure receipt instead of minting an unbounded series.
                terminalFlowIdentityRefOfText ("workdag-tail-close:" + snapshot.tailId + ":evidence=" + string matureEvidence.evidenceRef)
            let permitRef : TerminalFlowIdentityRef<TerminalFlowOwnerForceCloseReceiptRefKind> =
                terminalFlowIdentityRefOfText (phantomCloseKeyValue closeKey + ":writer=" + lease.leaseId + ":evidence=" + string matureEvidence.evidenceRef)
            { owner = owner
              closeKey = closeKey
              matureEvidence = matureEvidence
              pureSidecarReceiptRef = pureSidecarReceiptRef
              writerLeaseBoundRef = writerLeaseBoundRef
              workDagTailCloseReceiptRef = workDagTailCloseReceiptRef
