        let private terminalFlowForceOwnerCloseTransactionForClosedWorld
            (evidence:TerminalFlowProgressEvidence)
            (pending:TerminalFlowGlobalPendingTerminal)
            : TerminalFlowForceOwnerCloseTransaction =
            let snapshotRef = terminalFlowIdentityRefDigest evidence.snapshotRef
            let ledgerRef = terminalFlowIdentityRefDigest evidence.workLedger.ledgerRef
            let semanticRef = terminalFlowIdentityRefDigest evidence.semanticDigest.digestRef
            let permitRef =
                terminalFlowMintedRefOf
                    "qap_post_commit_closed_world_permit_ref"
                    (FastRuntimeFormat.format "fill=%s|snapshot=%u|ledger=%u|semantic=%u" [| box pending.fillKey; box snapshotRef; box ledgerRef; box semanticRef |])
            let ownerCloseReceiptId =
                sprintf "owner-close:qap-post-commit-closed-world:%u" permitRef
            let workDagTailCloseReceipt : TerminalFlowIdentityRef<TerminalFlowWorkDagTailCloseReceiptRefKind> =
                terminalFlowIdentityRefOfText
                    (FastRuntimeFormat.format "workdag-tail-close:closed-world:fill=%s|snapshot=%u|semantic=%u" [| box pending.fillKey; box snapshotRef; box semanticRef |])
            { ratification =
                terminalFlowForceOwnerCloseRatificationForQapPostCommit
                    permitRef
                    ledgerRef
                    semanticRef
                    snapshotRef
                    snapshotRef
              ownerCloseReceiptId = ownerCloseReceiptId
              workDagTailCloseReceipt = workDagTailCloseReceipt
              queueOnlyRecoveryReady = terminalFlowProgressEvidenceIsExactClosedWorld evidence
              fillOnceReadyWitnessRef =
                terminalFlowMintedRefOf
                    "fill_once_ready_closed_world_witness_ref"
                    ownerCloseReceiptId }

        let private terminalFlowOwnerCloseDecisionFor stickyTailGate =
            let snapshot = terminalFlowStickyTailSnapshotForGate stickyTailGate
            let drainPass = terminalFlowResidualDrainPassFor snapshot
            let mutatingDrained = snapshot.mutatingTailDrained && snapshot.mutatingDepth = 0
            if terminalFlowStickyTailSnapshotHasNoResidual snapshot then
                TerminalFlowOwnerCloseAlreadyExhausted drainPass
            elif drainPass.materialDeltaOnPass > 0 || not mutatingDrained then
                TerminalFlowOwnerCloseDeferredMaterialDelta drainPass
            else
                // Bonus breakthrough: residual age, repeat count, queue pressure,
                // writer leases and "zero delta" are observations only. None of
                // them may manufacture an owner-close capability. A residual owner
                // can now advance only when the conserved-credit / QAP quiescence
                // protocol supplies an exact closed-world transaction elsewhere.
                TerminalFlowOwnerCloseAwaitConservedCreditQuiescence drainPass

        let private terminalFlowOwnerCloseReceiptFor stickyTailGate decision : TerminalFlowOwnerCloseReceipt<ProceduralResidualOwnerKind> option =
            let snapshot = terminalFlowStickyTailSnapshotForGate stickyTailGate
            let closeKey = terminalFlowProceduralResidualCloseKeyFor snapshot
            let receipt drainPass reason : TerminalFlowOwnerCloseReceipt<ProceduralResidualOwnerKind> option =
                Some ({
                    closeKey = closeKey
                    drainPass = drainPass
                    receiptId = FastRuntimeFormat.format "owner-close:%s:pass-%d:%s" [| box (phantomCloseKeyValue closeKey); box drainPass.passCount; box reason |]
                    exactOnce = true
                })
            match decision with
            | TerminalFlowOwnerCloseAlreadyExhausted drainPass -> receipt drainPass "already_exhausted"
            | TerminalFlowOwnerCloseDeferredMaterialDelta _
            | TerminalFlowOwnerCloseAwaitConservedCreditQuiescence _ -> None

        let private terminalFlowOwnerClosureKeyRef receiptId =
            CompilerIdentityKernel.ContentDigest.ofText "terminal-owner-closure" receiptId

        let private terminalFlowOwnerClosureRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, TerminalFlowOwnerClosureCertificate>()

        let private terminalFlowOwnerClosureCertificateFor stickyTailGate (closeReceipt:TerminalFlowOwnerCloseReceipt<ProceduralResidualOwnerKind> option) : TerminalFlowOwnerClosureCertificate option =
            match closeReceipt with
            | None -> None
            | Some receipt ->
                let snapshot = terminalFlowStickyTailSnapshotForGate stickyTailGate
                let ownerId = terminalFlowProceduralResidualOwnerFor snapshot
                let closeKey = receipt.closeKey
                let state =
                    ProceduralResidualOwnerCloseReady(
                        snapshot.tailId,
                        phantomCloseKeyValue closeKey,
                        int64 receipt.drainPass.passCount,
                        int64 receipt.drainPass.materialDeltaOnPass)
                let lease : TypedOwnerLease<EvalWorklistTerminalGraphKind,ProceduralResidualOwnerKind,OwnerCloseReadyPhase> =
                    typedOwnerLeaseFor
                        ownerId
                        (Some closeKey)
                        None
                        0L
                        (OwnerRequireProceduralResidualDrain state)
                        "terminal_flow_owner_kind_closed_world_ready"
                let before = OwnerLedgerCons(ProceduralResidualOwnerNode(OwnerLeaseCloseReady lease), OwnerLedgerEmpty)
                match executeTypedOwnerTransaction
                          ("terminal-flow-owner-transaction:" + receipt.receiptId)
                          "root_to_terminal_to_writer_requires_recursive_kind_indexed_owner_closure"
                          [CloseProceduralResidualWith(closeKey, state, receipt.receiptId)]
                          before with
                | TypedOwnerTransactionRejected(transactionId, reason, rejectedLedger) ->
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_flow_owner_closure_rejected\",\"transaction_id\":%s,\"reason\":%s,\"open_owners\":%d,\"receipt_id\":%s,\"physical_exit\":false}" [| box (DiagJson.esc transactionId); box (DiagJson.esc (CompilerKernelV2.OperationalReasonIdOps.text reason)); box (recursiveOwnerLedgerOpenCount rejectedLedger); box (DiagJson.esc receipt.receiptId) |])
                    None
                | TypedOwnerTransactionCommitted committed ->
                    match tryRecursiveOwnerLedgerEmptyProof committed.afterLedger with
                    | Error reason ->
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_flow_owner_empty_proof_rejected\",\"transaction_id\":%s,\"reason\":%s,\"open_owners\":%d,\"receipt_id\":%s,\"physical_exit\":false}" [| box (DiagJson.esc committed.transactionId); box (DiagJson.esc reason); box committed.openAfter; box (DiagJson.esc receipt.receiptId) |])
                        None
                    | Ok emptyOwners ->
                        let certificateId = "owner-closure-certificate:" + committed.transactionId
                        let obligationId = "owner-waker:" + certificateId
                        let wakeCell : TerminalFlowOwnerWakeCell<TerminalFlowOwnerWakeRegisteredState> =
                            { obligationId = obligationId
                              ledgerRef = terminalFlowMintedRefOf "owner_ledger_proof_ref" (recursiveOwnerLedgerEmptyProofHash emptyOwners)
                              closed =
                                CompilerKernelV2.CompilerRuntimeKernel.oneShot<TerminalFlowOwnerWakeReceipt>
                                    ("terminal-owner-wake-closed:" + obligationId)
                              rejected =
                                CompilerKernelV2.CompilerRuntimeKernel.oneShot<uint32>
                                    ("terminal-owner-wake-rejected:" + obligationId) }
                        let wakeReceipt =
                            { obligationId = obligationId
                              transactionId = committed.transactionId
                              ledgerProofHash = (recursiveOwnerLedgerEmptyProofHash emptyOwners)
                              closeReceiptRefs = [ terminalFlowMintedRefOf "owner_close_receipt_ref" receipt.receiptId ]
                              observedAtMs = int64 Environment.TickCount64 }
                        let candidate : TerminalFlowOwnerClosureCertificate =
                            { certificateId = certificateId
                              transaction = committed
                              emptyOwners = emptyOwners
                              closeReceipts = [ TerminalFlowProceduralResidualClosed receipt ]
                              wakeCell = wakeCell }
                        let ownerClosureKeyRef = terminalFlowOwnerClosureKeyRef receipt.receiptId
                        let firstPublication = terminalFlowOwnerClosureRegistry.TryAdd(ownerClosureKeyRef, candidate)
                        let selected =
                            if firstPublication then candidate
                            else
                                match terminalFlowOwnerClosureRegistry.TryGetValue ownerClosureKeyRef with
                                | true, existing -> existing
                                | false, _ -> candidate
                        if firstPublication then
                            HopacExtensions.start
                                (CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                    selected.wakeCell.closed
                                    wakeReceipt)
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_flow_force_owner_close_transaction_ready\",\"transaction_id\":%s,\"owner_close_receipt_id\":%s,\"close_key\":%s,\"workdag_tail_close_receipt\":%s,\"owner_transaction_open_after\":%d,\"exact_once\":true,\"writer_lease_bound\":true,\"pure_sidecar_receipt\":true,\"queue_only_recovery_next\":\"ReadyAfterForceOwnerClose\"}" [| box (DiagJson.esc committed.transactionId); box (DiagJson.esc receipt.receiptId); box (DiagJson.esc (phantomCloseKeyValue receipt.closeKey)); box (DiagJson.esc ("workdag-tail-close:" + receipt.receiptId)); box committed.openAfter |])
                        Some selected

        let private terminalFlowResidualDrainPassText pass =
            FastRuntimeFormat.format "ResidualDrainPass(pass=%d|material_delta=%d|pending=%d|queue=%d|active=%d|procedural=%d)" [| box pass.passCount; box pass.materialDeltaOnPass; box pass.pendingDepth; box pass.queueDepth; box pass.activeDepth; box pass.proceduralDepth |]

        let private terminalFlowOwnerCloseDecisionText = function
            | TerminalFlowOwnerCloseDeferredMaterialDelta pass -> "OwnerCloseDecision(DeferredMaterialDelta|" + terminalFlowResidualDrainPassText pass + ")"
            | TerminalFlowOwnerCloseAwaitConservedCreditQuiescence pass -> "OwnerCloseDecision(AwaitConservedCreditQuiescence|" + terminalFlowResidualDrainPassText pass + ")"
            | TerminalFlowOwnerCloseAlreadyExhausted pass -> "OwnerCloseDecision(AlreadyExhausted|" + terminalFlowResidualDrainPassText pass + ")"

        let private terminalFlowOwnerCloseReceiptText (receiptOpt: TerminalFlowOwnerCloseReceipt<ProceduralResidualOwnerKind> option) =
            match receiptOpt with
            | Some receipt -> FastRuntimeFormat.format "OwnerCloseReceipt(id=%s|close_key=%s|pass=%d|exact_once=%b)" [| box receipt.receiptId; box (phantomCloseKeyValue receipt.closeKey); box receipt.drainPass.passCount; box receipt.exactOnce |]
            | None -> "OwnerCloseReceipt(None)"

        let private terminalFlowAnyOwnerCloseReceiptKeyAndExactOnce (receipt:TerminalFlowAnyOwnerCloseReceipt) =
            match receipt with
            | TerminalFlowParentContinuationClosed receipt -> (phantomCloseKeyValue receipt.closeKey), receipt.exactOnce
            | TerminalFlowCrossKindClosed receipt -> (phantomCloseKeyValue receipt.closeKey), receipt.exactOnce
            | TerminalFlowSidecarDrainClosed receipt -> (phantomCloseKeyValue receipt.closeKey), receipt.exactOnce
            | TerminalFlowDynamicBridgeClosed receipt -> (phantomCloseKeyValue receipt.closeKey), receipt.exactOnce
            | TerminalFlowPoisonTailClosed receipt -> (phantomCloseKeyValue receipt.closeKey), receipt.exactOnce
            | TerminalFlowJoinPointWaitClosed receipt -> (phantomCloseKeyValue receipt.closeKey), receipt.exactOnce
            | TerminalFlowProceduralResidualClosed receipt -> (phantomCloseKeyValue receipt.closeKey), receipt.exactOnce
            | TerminalFlowCicProofObligationClosed receipt -> (phantomCloseKeyValue receipt.closeKey), receipt.exactOnce

        let private terminalFlowOwnerClosurePrimaryCloseKey (certificate:TerminalFlowOwnerClosureCertificate) =
            certificate.closeReceipts
            |> List.tryHead
            |> Option.map (terminalFlowAnyOwnerCloseReceiptKeyAndExactOnce >> fst)
            |> Option.defaultValue ""

        let private terminalFlowOwnerClosureAllExactOnce (certificate:TerminalFlowOwnerClosureCertificate) =
            not (List.isEmpty certificate.closeReceipts)
            && (certificate.closeReceipts |> List.forall (terminalFlowAnyOwnerCloseReceiptKeyAndExactOnce >> snd))

        let private terminalFlowOwnerWakeAlt (cell:TerminalFlowOwnerWakeCell<'State>) =
            CompilerKernelV2.CompilerRuntimeKernel.raceOneShots
                ("terminal-owner-wake:" + cell.obligationId)
                cell.closed
                TerminalFlowOwnerWakeClosed
                cell.rejected
                (fun reasonRef -> TerminalFlowOwnerWakeRejected(cell.obligationId, reasonRef))
            |> CompilerKernelV2.CompilerRuntimeKernel.toJob

        let private terminalFlowStickyTailSnapshotSmallResidualBoundable snapshot =
            let drainPass = terminalFlowResidualDrainPassFor snapshot
            drainPass.materialDeltaOnPass = 0
            && (snapshot.mutatingTailDrained || snapshot.mutatingDepth = 0)
            && drainPass.pendingDepth <= terminalFlowWriterLeaseSmallResidualPendingCap
            && drainPass.queueDepth <= terminalFlowWriterLeaseSmallResidualQueueCap
            && drainPass.activeDepth <= terminalFlowWriterLeaseSmallResidualActiveCap
            && drainPass.proceduralDepth <= terminalFlowWriterLeaseSmallResidualProceduralCap
            && (drainPass.pendingDepth + drainPass.queueDepth + drainPass.activeDepth + drainPass.proceduralDepth) > 0

        let private terminalFlowStickyTailGateIsTerminalReady = function
            // Conserved-credit migration: sticky-tail shape is not a terminal
            // proof.  Only structural exhaustion is locally terminal-ready;
            // residual closure must arrive through the exact closed-world/QAP
            // quiescence transaction.
            | TerminalFlowStickyTailDrained snapshot -> terminalFlowStickyTailSnapshotHasNoResidual snapshot
            | TerminalFlowStickyTailWriterReady _
            | TerminalFlowStickyTailQuarantineProceduralResidual _
            | TerminalFlowStickyTailRejectUnboundedMutatingTail _
            | TerminalFlowStickyTailAwaitMutatingAggregate _ -> false

        let private terminalFlowSnapshotHasProceduralPressure snapshot =
            snapshot.mutatingDepth = 0
            && snapshot.proceduralDepth > 0
            && (snapshot.globalPending <= terminalFlowSmallPendingQuiescentCap
                || snapshot.globalQueue >= terminalFlowBoundedProceduralTailPressureQueue
                || snapshot.globalActive >= terminalFlowProceduralPressureActiveThreshold)

        let private terminalFlowSnapshotHasStrongProceduralPressure snapshot =
            terminalFlowSnapshotHasProceduralPressure snapshot
            && (snapshot.proceduralDepth >= terminalFlowBoundedProceduralTailPressureDepth
                || snapshot.globalQueue >= terminalFlowProceduralPressureQueueThreshold
                || snapshot.globalActive >= terminalFlowProceduralPressureActiveThreshold)

        let private terminalFlowWhyNotCanMintProceduralQuarantineReceipt _ stickyTailGate =
            // Quarantine is projection only in the conserved-credit model.  No
            // why-not reason, pressure threshold or drained mutating tail may mint
            // terminal authority.  The only local positive case is literal
            // structural exhaustion; residual closure is owned by QAP credit proof.
            match stickyTailGate with
            | TerminalFlowStickyTailDrained snapshot -> terminalFlowStickyTailSnapshotHasNoResidual snapshot
            | _ -> false

        let private terminalFlowReceiptFillOnceKey receiptId =
            if String.IsNullOrWhiteSpace receiptId then "terminal-outcome:missing-receipt"
            else "terminal-outcome:fill-once:" + receiptId

        let private terminalFlowWhyNotQuarantineReceiptIdentity = function
            | TerminalFlowWhyNotRejectedTopology qap ->
                FastRuntimeFormat.format "rejected_topology:%s:%s:%s" [| box (terminalFlowQapBoundednessText qap.boundedness); box (terminalFlowQapOccupancyText qap.occupancy); box (terminalFlowPendingLedgerAuthorityText qap.pendingProvenance.authority) |]
            | whyNot -> terminalFlowWhyNotIdentityText whyNot

        let private terminalFlowTerminalOutcomeForBoundary stickyTailGate boundary =
            match boundary with
            | TerminalFlowBoundaryReceipt receipt ->
                let receiptId = terminalFlowTopLevelReceiptStableId receipt
                let fillKey = terminalFlowReceiptFillOnceKey receiptId
                if terminalFlowStickyTailGateIsTerminalReady stickyTailGate then
                    TerminalFlowTerminalOutcomeSealed {
                        boundary = boundary
                        stickyTailGate = stickyTailGate
                        receiptId = receiptId
                        receiptDurable = not (String.IsNullOrWhiteSpace receiptId)
                        ivarFillOnceKey = fillKey
                        physicalExitIntent = TerminalFlowPhysicalExitAllowedAfterDurableReceipt receiptId
                    }
                else
                    TerminalFlowTerminalOutcomeOpen {
                        boundary = boundary
                        stickyTailGate = stickyTailGate
                        receiptId = receiptId
                        receiptDurable = false
                        ivarFillOnceKey = fillKey
                        physicalExitIntent = TerminalFlowPhysicalExitBlockedUntilReceipt(CompilerKernelV2.OperationalReasonIdOps.create "sticky_tail_mutating_aggregate_not_drained")
                    }
            | TerminalFlowBoundaryWhyNotCommit whyNot when terminalFlowWhyNotCanMintProceduralQuarantineReceipt whyNot stickyTailGate ->
                let reason = terminalFlowWhyNotTerminalCommitText whyNot
                let rootSnapshot = DiagJson.canonicalRootAuthoritySnapshot ()
                if String.IsNullOrWhiteSpace rootSnapshot.receiptId then
                    TerminalFlowTerminalOutcomeOpen {
                        boundary = boundary
                        stickyTailGate = stickyTailGate
                        receiptId = ""
                        receiptDurable = false
                        ivarFillOnceKey = "terminal-outcome:await-canonical-root"
                        physicalExitIntent = TerminalFlowPhysicalExitBlockedUntilReceipt(CompilerKernelV2.OperationalReasonIdOps.create "procedural_quarantine_requires_evaluator_root_ref")
                    }
                else
                    let stableReason = terminalFlowWhyNotQuarantineReceiptIdentity whyNot
                    let receiptId = "post_root_breakthrough_certificate|terminal_flow_why_not_quarantine|" + stableReason
                    let receipt =
                        TerminalFlowTopLevelQuarantineCertificate(
                            receiptId,
                            rootSnapshot.receiptId,
                            "lease:terminal-flow-boundary",
                            "tail:terminal-flow-boundary",
                            CompilerKernelV2.TerminalTailQuarantineEvidence(
                                CompilerKernelV2.OperationalReasonIdOps.create reason))
                    let sealedBoundary = TerminalFlowBoundaryReceipt receipt
                    TerminalFlowTerminalOutcomeSealed {
                        boundary = sealedBoundary
                        stickyTailGate = stickyTailGate
                        receiptId = receiptId
                        receiptDurable = true
                        ivarFillOnceKey = terminalFlowReceiptFillOnceKey receiptId
                        physicalExitIntent = TerminalFlowPhysicalExitAllowedAfterDurableReceipt receiptId
                    }
            | TerminalFlowBoundaryWhyNotCommit whyNot ->
                TerminalFlowTerminalOutcomeOpen {
                    boundary = boundary
                    stickyTailGate = stickyTailGate
                    receiptId = ""
                    receiptDurable = false
                    ivarFillOnceKey = "terminal-outcome:blocked:" + terminalFlowWhyNotIdentityText whyNot
                    physicalExitIntent = TerminalFlowPhysicalExitBlockedByWhyNot whyNot
                }

        let private terminalFlowPhysicalExitIntentText = function
            | TerminalFlowPhysicalExitBlockedUntilReceipt reason -> "TerminalFlowPhysicalExitIntent(BlockedUntilReceipt|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | TerminalFlowPhysicalExitBlockedByWhyNot whyNot -> "TerminalFlowPhysicalExitIntent(BlockedByWhyNot|" + terminalFlowWhyNotTerminalCommitText whyNot + ")"
            | TerminalFlowPhysicalExitAllowedAfterDurableReceipt receiptId -> "TerminalFlowPhysicalExitIntent(AllowedAfterDurableReceipt|receipt=" + receiptId + ")"

        let private terminalFlowTerminalOutcomeText = function
            | TerminalFlowTerminalOutcomeOpen outcome ->
                "TerminalOutcome(Open|receipt=" + outcome.receiptId + "|durable=" + string outcome.receiptDurable + "|ivar_key=" + outcome.ivarFillOnceKey + "|exit=" + terminalFlowPhysicalExitIntentText outcome.physicalExitIntent + "|boundary=" + terminalFlowCertificateBoundaryText outcome.boundary + "|sticky=" + terminalFlowStickyTailGateText outcome.stickyTailGate + ")"
            | TerminalFlowTerminalOutcomeSealed outcome ->
                "TerminalOutcome(Sealed|receipt=" + outcome.receiptId + "|durable=" + string outcome.receiptDurable + "|ivar_key=" + outcome.ivarFillOnceKey + "|exit=" + terminalFlowPhysicalExitIntentText outcome.physicalExitIntent + "|boundary=" + terminalFlowCertificateBoundaryText outcome.boundary + "|sticky=" + terminalFlowStickyTailGateText outcome.stickyTailGate + ")"
            | TerminalFlowTerminalOutcomeEmitted outcome ->
                "TerminalOutcome(Emitted|receipt=" + outcome.receiptId + "|durable=" + string outcome.receiptDurable + "|ivar_key=" + outcome.ivarFillOnceKey + "|exit=" + terminalFlowPhysicalExitIntentText outcome.physicalExitIntent + "|boundary=" + terminalFlowCertificateBoundaryText outcome.boundary + "|sticky=" + terminalFlowStickyTailGateText outcome.stickyTailGate + ")"

        let private terminalFlowTerminalOutcomeReceiptBoundary = function
            | TerminalFlowTerminalOutcomeSealed outcome -> Some outcome.boundary
            | TerminalFlowTerminalOutcomeEmitted outcome -> Some outcome.boundary
            | TerminalFlowTerminalOutcomeOpen outcome when outcome.receiptDurable -> Some outcome.boundary
            | TerminalFlowTerminalOutcomeOpen _ -> None

        let private terminalFlowTerminalOutcomeTopLevelReceiptText outcome =
            match terminalFlowTerminalOutcomeReceiptBoundary outcome with
            | Some (TerminalFlowBoundaryReceipt receipt) -> terminalFlowTopLevelReceiptText receipt
            | _ -> "TerminalFlowTopLevelReceipt(None)"

        let private terminalFlowTerminalOutcomeTerminalCommitReceiptId outcome =
            match terminalFlowTerminalOutcomeReceiptBoundary outcome with
            | Some boundary -> terminalFlowBoundaryTerminalCommitReceiptId boundary
            | None -> ""

        let private terminalFlowTerminalOutcomePostRootCertificateId outcome =
            match terminalFlowTerminalOutcomeReceiptBoundary outcome with
            | Some boundary -> terminalFlowBoundaryPostRootCertificateId boundary
            | None -> ""

        let private terminalFlowTerminalOutcomeHasDurableReceipt outcome =
            match outcome with
            | TerminalFlowTerminalOutcomeSealed o -> o.receiptDurable && not (String.IsNullOrWhiteSpace o.receiptId)
            | TerminalFlowTerminalOutcomeEmitted o -> o.receiptDurable && not (String.IsNullOrWhiteSpace o.receiptId)
            | TerminalFlowTerminalOutcomeOpen o -> o.receiptDurable && not (String.IsNullOrWhiteSpace o.receiptId)

        let private terminalFlowRootReceiptIdForBoundary = function
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt(_, rootReceipt, _, _)) -> rootReceipt
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildErrorCertificate(_, rootReceipt, _, _, _)) -> rootReceipt
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelQuarantineCertificate(_, rootReceipt, _, _, _)) -> rootReceipt
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelNoFurtherCertificate receiptId) -> receiptId
            | TerminalFlowBoundaryWhyNotCommit _ -> ""

        let private terminalFlowCommitEligibilityForResolvedOutcome (outcome: TerminalFlowTerminalOutcome<'State>) =
            match outcome.boundary with
            | TerminalFlowBoundaryReceipt _ ->
                let rootReceiptId = terminalFlowRootReceiptIdForBoundary outcome.boundary
                if String.IsNullOrWhiteSpace rootReceiptId
                   || String.IsNullOrWhiteSpace outcome.receiptId
                   || String.IsNullOrWhiteSpace outcome.ivarFillOnceKey then
                    TerminalFlowCommitBlocked(
                        outcome.ivarFillOnceKey,
                        TerminalFlowWhyNotMissingRootReceipt "sealed_or_emitted_outcome_missing_typed_identity")
                else
                    TerminalFlowCommitEligible(
                        { rootReceiptId = rootReceiptId; semanticDebtPaid = true },
                        outcome.ivarFillOnceKey,
                        outcome.receiptId,
                        outcome.boundary)
            | TerminalFlowBoundaryWhyNotCommit whyNot ->
                TerminalFlowCommitBlocked(outcome.ivarFillOnceKey, whyNot)

        let private terminalFlowCommitEligibilityForTerminalOutcome = function
            | TerminalFlowTerminalOutcomeSealed outcome -> terminalFlowCommitEligibilityForResolvedOutcome outcome
            | TerminalFlowTerminalOutcomeEmitted outcome -> terminalFlowCommitEligibilityForResolvedOutcome outcome
            | TerminalFlowTerminalOutcomeOpen outcome ->
                match outcome.boundary with
                | TerminalFlowBoundaryWhyNotCommit whyNot ->
                    TerminalFlowCommitBlocked(outcome.ivarFillOnceKey, whyNot)
                | TerminalFlowBoundaryReceipt _ ->
                    TerminalFlowCommitBlocked(
                        outcome.ivarFillOnceKey,
                        TerminalFlowWhyNotObserverOnly (CompilerKernelV2.OperationalReasonIdOps.create "open_outcome_cannot_own_terminal_commit"))

        let private terminalFlowFillKeyRef fillKey =
            CompilerIdentityKernel.ContentDigest.ofText "terminal-flow-fill-key" fillKey

        let private terminalFlowFillKeyRefForId (fillKey:TerminalFlowFillKeyId) =
            terminalFlowFillKeyRef (TerminalFlowFillKeyId.text fillKey)

        let private terminalFlowNativeCellKeyRef nativeCellId =
            CompilerIdentityKernel.ContentDigest.ofText "terminal-flow-native-cell-key" nativeCellId

        let private terminalFlowOutcomeIvarRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, TerminalFlowOutcomeIvarCell<TerminalFlowOutcomeUnfilledState>>()

        let private terminalFlowOutcomeFillRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, TerminalFlowOutcomeFillReceipt>()

        let private terminalFlowSchedulerPushDispatchRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, byte>()

        let private terminalFlowSchedulerPushCompletionRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, CompilerKernelV2.PortableOneShotCell<TerminalFlowNativeHandoffId>>()

        let private terminalFlowArtifactCommitRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, TerminalFlowArtifactCommitRequest>()

        // Symmetric rendezvous between the outer BuildDraft producer and the
        // terminal writer. Hopac channel semantics preserve either arrival order
        // without polling, retries, or an empty-queue race.
        let private terminalFlowArtifactCommitRequestChannel =
            CompilerKernelV2.CompilerRuntimeKernel.mailbox<TerminalFlowArtifactCommitRequest>
                "terminal-artifact-commit"
                CompilerKernelV2.PortableControlLane
                0
                CompilerKernelV2.MailboxFailClosed

        let private terminalFlowSchedulerPushRegistryPrune (fillKey:TerminalFlowFillKeyId) =
            let fillKeyRef = terminalFlowFillKeyRefForId fillKey
            let mutable removedDispatch = 0uy
            terminalFlowSchedulerPushDispatchRegistry.TryRemove(fillKeyRef, &removedDispatch) |> ignore
            let mutable removedCompletion = Unchecked.defaultof<CompilerKernelV2.PortableOneShotCell<TerminalFlowNativeHandoffId>>
            terminalFlowSchedulerPushCompletionRegistry.TryRemove(fillKeyRef, &removedCompletion) |> ignore

        let private terminalFlowSchedulerChannelLedgerGate = obj()
        let mutable private terminalFlowSchedulerChannelLedger : Map<CompilerIdentityKernel.ContentDigest, TerminalFlowSchedulerChannelLedgerEntry> = Map.empty


        let private terminalFlowSchedulerWakerRegistrationFor (context:TerminalFlowSchedulerChannelAdmissionContext) : TerminalFlowSchedulerWakerRegistrationReceipt =
            lock terminalFlowSchedulerChannelLedgerGate (fun () ->
                let key = context.contextDigest
                match Map.tryFind key terminalFlowSchedulerChannelLedger with
                | Some entry when entry.admission.contextDigest = context.contextDigest -> entry.wakerRegistration
                | Some _ -> invalidOp "scheduler channel receipt digest collision"
                | None ->
                    let nowMs = Environment.TickCount64
                    let registryRef =
                        terminalFlowMintedRefOf
                            "scheduler_waker_registry_projection_ref"
                            (String.concat "|"
                                [ CompilerIdentityKernel.ContentDigest.text context.contextDigest
                                  CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest context.wakerEdge) ])
                    let registry : TerminalFlowSchedulerWitness<TerminalFlowSchedulerWakerRegistryWitnessKind> =
                        terminalFlowSchedulerWitnessFor "scheduler-waker-registry" registryRef
                    let payload : TerminalFlowSchedulerWakerPayload =
                        { context = context; registry = registry }
                    let typedReceipt : TerminalFlowSchedulerReceipt<TerminalFlowSchedulerWakerReceiptKind,TerminalFlowSchedulerReceiptSealedStage,TerminalFlowSchedulerWakerPayload> =
                        terminalFlowSchedulerReceiptCreateSuccessor
                            "scheduler-waker-registered"
                            (CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest registry))
                            context.contextDigest
                            payload
                    let receipt : TerminalFlowSchedulerWakerRegistrationReceipt =
                        { receipt = typedReceipt
                          state = TerminalFlowSchedulerWakerRegistered
                          registeredAtMs = nowMs
                          consumedAtMs = 0L }
                    let entry : TerminalFlowSchedulerChannelLedgerEntry =
                        { receipts =
                            TerminalFlowSchedulerReceiptStep(
                                SomeTerminalFlowSchedulerWakerReceipt receipt,
                                TerminalFlowSchedulerReceiptGenesis(SomeTerminalFlowSchedulerAdmissionReceipt context))
                          possessionRevision = 1L }
                    terminalFlowSchedulerChannelLedger <- Map.add key entry terminalFlowSchedulerChannelLedger
                    receipt)

        let private terminalFlowSchedulerWakerConsume (context:TerminalFlowSchedulerChannelAdmissionContext) : TerminalFlowSchedulerWakerRegistrationReceipt =
            lock terminalFlowSchedulerChannelLedgerGate (fun () ->
                match Map.tryFind context.contextDigest terminalFlowSchedulerChannelLedger with
                | Some entry when entry.admission.contextDigest = context.contextDigest ->
                    match entry.wakerRegistration.state with
                    | TerminalFlowSchedulerWakerRegistered ->
                        let previous = entry.wakerRegistration
                        let typedReceipt : TerminalFlowSchedulerReceipt<TerminalFlowSchedulerWakerReceiptKind,TerminalFlowSchedulerReceiptSealedStage,TerminalFlowSchedulerWakerPayload> =
                            terminalFlowSchedulerReceiptCreateSuccessor
                                "scheduler-waker-consumed"
                                (CompilerIdentityKernel.ContentDigest.text previous.exactOnceDigest)
                                previous.exactOnceDigest
                                previous.receipt.payload
                        let consumed : TerminalFlowSchedulerWakerRegistrationReceipt =
                            { receipt = typedReceipt
                              state = TerminalFlowSchedulerWakerConsumed
                              registeredAtMs = previous.registeredAtMs
                              consumedAtMs = Environment.TickCount64 }
                        let advanced =
                            { entry with
                                receipts = TerminalFlowSchedulerReceiptStep(SomeTerminalFlowSchedulerWakerReceipt consumed, entry.receipts)
                                possessionRevision = entry.possessionRevision + 1L }
                        terminalFlowSchedulerChannelLedger <- Map.add context.contextDigest advanced terminalFlowSchedulerChannelLedger
                        consumed
                    | _ -> entry.wakerRegistration
                | Some _ -> invalidOp "scheduler channel waker context receipt mismatch"
                | None -> invalidOp "scheduler channel waker consumed before registration")

        let private terminalFlowSchedulerWorkerHandoffFor (context:TerminalFlowSchedulerChannelAdmissionContext) (completed:TerminalFlowCommitCompleted) : TerminalFlowSchedulerWorkerHandoffReceipt =
            let workerJob : TerminalFlowSchedulerWitness<TerminalFlowSchedulerWorkerJobWitnessKind> =
                terminalFlowSchedulerWitnessFor "scheduler-worker-job" (terminalFlowMintedRefOf "scheduler_worker_job_ref" completed.writerReceipt.writerJobId)
            let artifact : TerminalFlowSchedulerWitness<TerminalFlowSchedulerArtifactWitnessKind> =
                terminalFlowSchedulerWitnessFor
                    "scheduler-worker-artifact"
                    (terminalFlowMintedRefOf "scheduler_worker_artifact_receipt_ref" (completed.writerReceipt.writerJobId + "|" + terminalFlowIdentityRefText completed.writerReceipt.terminalReceiptRef))
            let exitWitness : TerminalFlowSchedulerWitness<TerminalFlowSchedulerExitWitnessKind> =
                terminalFlowSchedulerWitnessFor "scheduler-worker-exit" (terminalFlowMintedRefOf "scheduler_worker_exit_witness_ref" completed.exitWitness.witnessId)
            lock terminalFlowSchedulerChannelLedgerGate (fun () ->
                match Map.tryFind context.contextDigest terminalFlowSchedulerChannelLedger with
                | Some entry when entry.admission.contextDigest = context.contextDigest ->
                    match entry.workerHandoff with
                    | Some receipt when receipt.workerJob.digest = workerJob.digest -> receipt
                    | Some _ -> invalidOp "scheduler channel worker handoff receipt already belongs to another worker"
                    | None ->
                        let payload : TerminalFlowSchedulerWorkerPayload =
                            { context = context
                              workerJob = workerJob
                              artifact = artifact
                              exitWitness = exitWitness }
                        let payloadText =
                            String.concat "|"
                                [ CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest workerJob)
                                  CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest artifact)
                                  CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest exitWitness) ]
                        let typedReceipt : TerminalFlowSchedulerReceipt<TerminalFlowSchedulerWorkerReceiptKind,TerminalFlowSchedulerReceiptSealedStage,TerminalFlowSchedulerWorkerPayload> =
                            terminalFlowSchedulerReceiptCreateSuccessor
                                "scheduler-worker-handoff"
                                payloadText
                                entry.wakerRegistration.exactOnceDigest
                                payload
                        let receipt : TerminalFlowSchedulerWorkerHandoffReceipt =
                            { receipt = typedReceipt
                              completedAtMs = Environment.TickCount64 }
                        let advanced =
                            { entry with
                                receipts = TerminalFlowSchedulerReceiptStep(SomeTerminalFlowSchedulerWorkerReceipt receipt, entry.receipts)
                                possessionRevision = entry.possessionRevision + 1L }
                        terminalFlowSchedulerChannelLedger <- Map.add context.contextDigest advanced terminalFlowSchedulerChannelLedger
                        receipt
                | Some _ -> invalidOp "scheduler channel worker context receipt mismatch"
                | None -> invalidOp "scheduler channel worker completed before admission receipt registration")


        let private terminalFlowSchedulerChannelLedgerEntryFor (context:TerminalFlowSchedulerChannelAdmissionContext) : TerminalFlowSchedulerChannelLedgerEntry =
            lock terminalFlowSchedulerChannelLedgerGate (fun () ->
                match Map.tryFind context.contextDigest terminalFlowSchedulerChannelLedger with
                | Some entry when entry.admission.contextDigest = context.contextDigest -> entry
                | Some _ -> invalidOp "scheduler channel ledger digest collision"
                | None -> invalidOp "scheduler channel ledger missing for admission receipt")

        let private terminalFlowSchedulerChannelLedgerAdvance
            (context:TerminalFlowSchedulerChannelAdmissionContext)
            (authority:TerminalFlowSchedulerChannelAuthorityReceipt)
            : TerminalFlowSchedulerChannelLedgerEntry =
            lock terminalFlowSchedulerChannelLedgerGate (fun () ->
                match Map.tryFind context.contextDigest terminalFlowSchedulerChannelLedger with
                | Some entry when entry.admission.contextDigest = context.contextDigest ->
                    if authority.context.contextDigest <> context.contextDigest then
                        invalidOp "scheduler channel authority belongs to a different admission receipt"
                    if authority.wakerRegistration.exactOnceDigest <> entry.wakerRegistration.exactOnceDigest then
                        invalidOp "scheduler channel authority does not own the current waker receipt"
                    match entry.workerHandoff, authority.workerHandoff with
                    | Some ledgerWorker, Some authorityWorker when ledgerWorker.exactOnceDigest <> authorityWorker.exactOnceDigest ->
                        invalidOp "scheduler channel authority worker receipt diverged from ledger"
                    | None, Some _ -> invalidOp "scheduler channel authority references a worker receipt not present in ledger"
                    | _ -> ()
                    let nextRevision = entry.possessionRevision + 1L
                    let advanced =
                        { entry with
                            receipts = TerminalFlowSchedulerReceiptStep(SomeTerminalFlowSchedulerAuthorityReceipt authority, entry.receipts)
                            possessionRevision = nextRevision }
                    terminalFlowSchedulerChannelLedger <- Map.add context.contextDigest advanced terminalFlowSchedulerChannelLedger
                    advanced
                | Some _ -> invalidOp "scheduler channel ledger advance digest collision"
                | None -> invalidOp "scheduler channel ledger advance before admission receipt registration")

        let private terminalFlowOutcomeIvarCellFor (fillKey:TerminalFlowFillKeyId) =
            let fillKeyText = TerminalFlowFillKeyId.text fillKey
            let fillKeyRef = terminalFlowFillKeyRefForId fillKey
            terminalFlowOutcomeIvarRegistry.GetOrAdd(
                fillKeyRef,
                fun _ ->
                    { cellId = "terminal-outcome-ivar:" + fillKeyText
                      fillKey = fillKey
                      ivar =
                        CompilerKernelV2.CompilerRuntimeKernel.oneShot<TerminalFlowResolvedOutcomeEnvelope>
                            ("terminal-outcome:" + fillKeyText) })

        let private terminalFlowNativeRootBridgeForCurrentAuthority () =
            match DiagJson.tryNativeWriterCapabilityLatest () with
            | None -> Error "native_root_complete_writer_capability_not_ready"
            | Some capability ->
                let evidence = DiagJson.nativeWriterCapabilityEvidence capability
                let resolutionText = DiagJson.nativeRootCompleteResolutionText evidence.resolution
                Ok {
                    authority = TerminalFlowNativeRootBridgeFromNativeWriterCapability capability
                    cellId = evidence.cellId
                    proofHash = evidence.proofHash
                    resolutionRef = terminalFlowMintedRefOf "native_root_resolution_ref" resolutionText
                    workDagClosureHash = evidence.workDagClosureHash
                    expectedArtifactSetHash = evidence.artifactSetHash
                }

        let private terminalFlowResolvedOutcomeEnvelopeFor (root:TerminalFlowRootCapability<TerminalFlowRootResolvedState>) (terminalOutcome:TerminalFlowTerminalOutcomeBox) (ownerClosure:TerminalFlowOwnerClosureCertificate) (key:string) (receiptId:string) (nativeRootBridge:TerminalFlowNativeRootBridge) (schedulerContext:TerminalFlowSchedulerChannelAdmissionContext) =
            let ownerTransaction = ownerClosure.transaction
            let terminalReceiptRef = terminalFlowIdentityRefOfText receiptId
            let fillKeyId = TerminalFlowFillKeyId.create key
            let kindBridge =
                { bridgeId =
                    "kind-bridge:" + nativeRootBridge.proofHash
                    + ":" + ownerTransaction.transactionId
                  terminalKindProofHash = nativeRootBridge.proofHash
                  evalGraphOwnerTransactionId = ownerTransaction.transactionId
                  ownerClosureCertificateId = ownerClosure.certificateId }
            let mk boundary stickyTailGate =
                let causalIdentity =
                    { canonicalRoot = terminalFlowIdentityRefOfText root.rootReceiptId
                      terminalReceipt = terminalReceiptRef
                      fill = TerminalFlowFillKeyId.reference fillKeyId }
                { rootCapability = root
                  causalIdentity = causalIdentity
                  boundary = boundary
                  stickyTailGate = stickyTailGate
                  terminalReceiptRef = terminalReceiptRef
                  fillKey = fillKeyId
                  ownerClosure = ownerClosure
                  nativeRootBridge = nativeRootBridge
                  kindBridge = kindBridge
                  schedulerContext = schedulerContext }
            match terminalOutcome with
            | TerminalFlowTerminalOutcomeSealed outcome -> Some (mk outcome.boundary outcome.stickyTailGate)
            | TerminalFlowTerminalOutcomeEmitted outcome -> Some (mk outcome.boundary outcome.stickyTailGate)
            | TerminalFlowTerminalOutcomeOpen _ -> None

        let private terminalFlowOutcomeFillOnceJob
            (cell:TerminalFlowOutcomeIvarCell<TerminalFlowOutcomeUnfilledState>)
            (envelope:TerminalFlowResolvedOutcomeEnvelope)
            : Hopac.Job<TerminalFlowOutcomeIvarCell<TerminalFlowOutcomeFilledState> * TerminalFlowOutcomeFillReceipt * TerminalFlowResolvedOutcomeEnvelope> =
            job {
                let candidate =
                    { cellId = cell.cellId
                      fillKey = cell.fillKey
                      receiptId = terminalFlowIdentityRefText envelope.terminalReceiptRef
                      ownerTransactionId = envelope.ownerClosure.transaction.transactionId
                      firstFill = true }
                let fillKeyRef = terminalFlowFillKeyRefForId cell.fillKey
                let firstFill = terminalFlowOutcomeFillRegistry.TryAdd(fillKeyRef, candidate)
                if firstFill then
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                            cell.ivar
                            envelope
                let! filledEnvelope =
                    CompilerKernelV2.CompilerRuntimeKernel.readOneShot cell.ivar
                let fillReceipt =
                    match terminalFlowOutcomeFillRegistry.TryGetValue fillKeyRef with
                    | true, receipt -> { receipt with firstFill = firstFill }
                    | false, _ -> { candidate with firstFill = firstFill }
                let filledCell : TerminalFlowOutcomeIvarCell<TerminalFlowOutcomeFilledState> =
                    { cellId = cell.cellId
                      fillKey = cell.fillKey
                      ivar = cell.ivar }
                return filledCell, fillReceipt, filledEnvelope
            }

        let private terminalFlowArtifactWritePlanForEnvelope (envelope:TerminalFlowResolvedOutcomeEnvelope) =
            let intents, manifestDisposition =
                match envelope.boundary with
                | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt _) ->
                    [ TerminalFlowWriteCodeArtifact
                      TerminalFlowWriteManifestArtifact
                      TerminalFlowWriteDiagnosticsArtifact
                      TerminalFlowWriteTerminalReceiptArtifact ],
                    TerminalFlowBuildDraftManifestRequired
                | TerminalFlowBoundaryReceipt receipt ->
                    let reason = "terminal_failure_manifest|" + terminalFlowTopLevelReceiptText receipt
                    [ TerminalFlowWriteDiagnosticsArtifact
                      TerminalFlowWriteTerminalReceiptArtifact ],
                    TerminalFlowTerminalFailureManifest(NativeCutoverStableRef.ref32 "terminal-failure-reason" [reason], CompilerKernelV2.OperationalReasonIdOps.create reason)
                | TerminalFlowBoundaryWhyNotCommit whyNot ->
                    let reason = "terminal_failure_manifest|" + terminalFlowWhyNotTerminalCommitText whyNot
                    [ TerminalFlowWriteDiagnosticsArtifact
                      TerminalFlowWriteTerminalReceiptArtifact ],
                    TerminalFlowTerminalFailureManifest(NativeCutoverStableRef.ref32 "terminal-failure-reason" [reason], CompilerKernelV2.OperationalReasonIdOps.create reason)
            let bridge = envelope.nativeRootBridge
            let manifestText =
                "terminal_receipt=" + terminalFlowIdentityRefText envelope.terminalReceiptRef
                + "|fill_key=" + TerminalFlowFillKeyId.text envelope.fillKey
                + "|owner_transaction=" + envelope.ownerClosure.transaction.transactionId
                + "|owner_closure_certificate=" + envelope.ownerClosure.certificateId
                + "|owner_close_key=" + terminalFlowOwnerClosurePrimaryCloseKey envelope.ownerClosure
                + "|owner_waker_obligation=" + envelope.ownerClosure.wakeCell.obligationId
                + "|native_root_cell=" + bridge.cellId
                + "|native_root_proof=" + bridge.proofHash
                + "|kind_bridge=" + envelope.kindBridge.bridgeId
                + "|workdag_closure=" + bridge.workDagClosureHash
                + "|native_artifact_hash=" + bridge.expectedArtifactSetHash
                + "|intent_count=" + string intents.Length
            {
                planId = "artifact-plan:" + TerminalFlowFillKeyId.text envelope.fillKey
                manifestText = manifestText
                manifestDisposition = manifestDisposition
                intents = intents
                nativeBridge = bridge
                kindBridge = envelope.kindBridge
                expectedArtifactSetHash = bridge.expectedArtifactSetHash
            }

        let private terminalFlowOutcomeSealedStageForEnvelope (envelope:TerminalFlowResolvedOutcomeEnvelope) : TerminalFlowStageCapability<TerminalFlowRootResolvedStage,TerminalFlowOutcomeSealedStage,TerminalFlowWriterUnboundStage,TerminalFlowArtifactUncommittedStage,TerminalFlowExitOpenKernelStage> =
            terminalFlowStageCapability
                TerminalFlowKernelStageReadyToDispatch
                (Some (terminalFlowIdentityRefOfText envelope.rootCapability.rootReceiptId))
                (Some envelope.terminalReceiptRef)
                (Some (TerminalFlowFillKeyId.reference envelope.fillKey))
                None 0u 0u 0u

        let private terminalFlowWriterBoundStageForEnvelope (writerLeaseId:string) (envelope:TerminalFlowResolvedOutcomeEnvelope) : TerminalFlowStageCapability<TerminalFlowRootResolvedStage,TerminalFlowOutcomeSealedStage,TerminalFlowWriterBoundStage,TerminalFlowArtifactUncommittedStage,TerminalFlowExitOpenKernelStage> =
            terminalFlowStageCapability
                TerminalFlowKernelStageWriterBound
                (Some (terminalFlowIdentityRefOfText envelope.rootCapability.rootReceiptId))
                (Some envelope.terminalReceiptRef)
                (Some (TerminalFlowFillKeyId.reference envelope.fillKey))
                None
                (NativeCutoverStableRef.ref32 "terminal-writer-lease" [writerLeaseId])
                0u 0u

        let private terminalFlowArtifactCommittedStageForWriter (writer:TerminalFlowWriterCapability<TerminalFlowWriterBoundState>) (artifactReceipt:TerminalFlowArtifactWriteReceipt<TerminalFlowArtifactsCommittedState>) : TerminalFlowStageCapability<TerminalFlowRootResolvedStage,TerminalFlowOutcomeSealedStage,TerminalFlowWriterBoundStage,TerminalFlowArtifactCommittedStage,TerminalFlowExitOpenKernelStage> =
            let artifactRef =
                match artifactReceipt.writerCompletionRoute with
                | TerminalFlowWriterCompletionGreenPath(manifestRef, artifactSetHash, _) ->
                    terminalFlowMintedRefOf "artifact_manifest_success_ref" (terminalFlowIdentityRefText manifestRef + "|" + artifactSetHash)
                | TerminalFlowWriterCompletionTypedFailure(reasonRef, reason) ->
                    terminalFlowMintedRefOf "artifact_manifest_failure_ref" (string reasonRef + "|" + CompilerKernelV2.OperationalReasonIdOps.text reason)
                | TerminalFlowWriterCompletionRejected(reasonRef, reason) ->
                    terminalFlowMintedRefOf "artifact_manifest_rejection_ref" (string reasonRef + "|" + CompilerKernelV2.OperationalReasonIdOps.text reason)
            terminalFlowStageCapability
                TerminalFlowKernelStageArtifactCommitted
                writer.writerBoundStage.rootRef
                writer.writerBoundStage.terminalRef
                writer.writerBoundStage.fillRef
                writer.writerBoundStage.dispatchRef
                writer.writerBoundStage.writerRef
                artifactRef
                0u

        let private terminalFlowWriterCapabilityForEnvelope (envelope:TerminalFlowResolvedOutcomeEnvelope) =
            let nativeBridge = envelope.nativeRootBridge
            let ownerCloseKey = terminalFlowOwnerClosurePrimaryCloseKey envelope.ownerClosure
            if not envelope.rootCapability.semanticDebtPaid then
                Error "writer_capability_requires_semantic_debt_paid_root"
            elif not (terminalFlowOwnerClosureAllExactOnce envelope.ownerClosure) then
                Error "writer_capability_requires_exact_once_kind_indexed_owner_close_receipts"
            elif envelope.ownerClosure.transaction.openAfter <> 0L then
                Error (sprintf "writer_capability_requires_zero_open_owners|open_after=%d" envelope.ownerClosure.transaction.openAfter)
            elif String.IsNullOrWhiteSpace ownerCloseKey then
                Error "writer_capability_requires_nonempty_kind_indexed_close_key"
            elif (recursiveOwnerLedgerEmptyProofHash envelope.ownerClosure.emptyOwners) = "" then
                Error "writer_capability_requires_recursive_owner_ledger_empty_proof"
            elif not (terminalFlowNativeRootBridgeIsValid nativeBridge) then
                Error "writer_capability_requires_valid_typed_native_root_bridge"
            elif envelope.kindBridge.terminalKindProofHash <> nativeBridge.proofHash
                 || envelope.kindBridge.evalGraphOwnerTransactionId <> envelope.ownerClosure.transaction.transactionId
                 || envelope.kindBridge.ownerClosureCertificateId <> envelope.ownerClosure.certificateId then
                Error "writer_capability_requires_exact_terminal_to_eval_owner_closure_bridge"
            elif String.IsNullOrWhiteSpace nativeBridge.expectedArtifactSetHash then
                Error "writer_capability_requires_nonempty_artifact_authority_hash"
            else
                let artifactPlan = terminalFlowArtifactWritePlanForEnvelope envelope
                if List.isEmpty artifactPlan.intents then
                    Error "writer_capability_requires_receipt_bearing_artifact_plan"
                else
                    let writerLeaseId = "writer-lease:terminal-outcome:" + TerminalFlowFillKeyId.text envelope.fillKey
                    Ok {
                        writerLeaseId = writerLeaseId
                        terminalReceiptRef = envelope.terminalReceiptRef
                        ownerClosureCertificateId = envelope.ownerClosure.certificateId
                        ownerTransactionId = envelope.ownerClosure.transaction.transactionId
                        ownerLedgerAfter = envelope.ownerClosure.transaction.afterLedger
                        ownerWakeCell = envelope.ownerClosure.wakeCell
                        artifactPlan = artifactPlan
                        sealedOutcomeStage = terminalFlowOutcomeSealedStageForEnvelope envelope
                        writerBoundStage = terminalFlowWriterBoundStageForEnvelope writerLeaseId envelope
                    }

        let private terminalFlowArtifactAuthorizationAllowsCommit = function
            | TerminalFlowArtifactsAuthorizedByNativeRootComplete _
            | TerminalFlowArtifactsAuthorizedByTerminalFailure _ -> true
            | TerminalFlowArtifactsRejectedByNativeRootComplete _ -> false

        let private terminalFlowRejectedArtifactReceipt
            (writer:TerminalFlowWriterCapability<TerminalFlowWriterBoundState>)
            (reason:CompilerKernelV2.OperationalReasonId) =
            let reasonText = CompilerKernelV2.OperationalReasonIdOps.text reason
            let reasonRef = NativeCutoverStableRef.ref32 "terminal-failure-reason" [reasonText]
            {
                plan = writer.artifactPlan
                authorization = TerminalFlowArtifactsRejectedByNativeRootComplete(reasonRef, reason)
                execution = TerminalFlowArtifactsExecutionRejected(writer.artifactPlan.planId, reasonRef, reason)
                manifestLifecycle = TerminalFlowArtifactManifestRejected(reasonRef, reason)
                writerCompletionRoute = TerminalFlowWriterCompletionRejected(reasonRef, reason)
            }

        let private terminalFlowWriterJob
            (dispatch:TerminalFlowSchedulerPushDispatch)
            (writer:TerminalFlowWriterCapability<TerminalFlowWriterBoundState>)
            : Hopac.Job<TerminalFlowWriterJobReceipt> =
            job {
                let openAfter = recursiveOwnerLedgerOpenCount writer.ownerLedgerAfter
                let writerJobId = "writer-job:" + terminalFlowWriterTerminalReceiptText writer
                let requestId = "artifact-commit-request:" + writer.artifactPlan.nativeBridge.cellId
                let! ownerWakeVerdict = terminalFlowOwnerWakeAlt writer.ownerWakeCell
                let ownerWakeReceiptOpt, ownerWakeRejectedRef =
                    match ownerWakeVerdict with
                    | TerminalFlowOwnerWakeClosed receipt -> Some receipt, 0u
                    | TerminalFlowOwnerWakeRejected(_, reasonRef) -> None, reasonRef
                let ownerWakeMatches =
                    match ownerWakeReceiptOpt with
                    | Some receipt ->
                        receipt.obligationId = writer.ownerWakeCell.obligationId
                        && receipt.transactionId = writer.ownerTransactionId
                        && not (String.IsNullOrWhiteSpace receipt.ledgerProofHash)
                    | None -> false
                let ownerWakeTransactionRef = ownerWakeReceiptOpt |> Option.map (fun receipt -> NativeCutoverStableRef.ref32 "owner-wake-transaction" [receipt.transactionId]) |> Option.defaultValue 0u
                let ownerWakeLedgerRef = ownerWakeReceiptOpt |> Option.map (fun receipt -> NativeCutoverStableRef.ref32 "owner-wake-ledger-proof" [receipt.ledgerProofHash]) |> Option.defaultValue 0u
                let ownerWakeReceiptCount = ownerWakeReceiptOpt |> Option.map (fun receipt -> receipt.closeReceiptRefs.Length) |> Option.defaultValue 0
                let ownerWakeObligationRef = NativeCutoverStableRef.ref32 "owner-wake-obligation" [writer.ownerWakeCell.obligationId]
                let ownerWakeRegistryVerdict = TerminalFlowWakerRegistryObservedByAltChoose(TerminalFlowWakerRegistryStickyTail, ownerWakeObligationRef)
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_flow_owner_waker_observed\",\"obligation_ref\":%u,\"owner_transaction_ref\":%u,\"ledger_proof_ref\":%u,\"close_receipt_count\":%d,\"waker_rejected_ref\":%u,\"waker_registration_status\":%s,\"waker_registry_source_du\":\"sticky_tail\",\"owner_wake_matches\":%b,\"authority\":\"Hopac.Alt.choose\"}" [| box ownerWakeObligationRef; box ownerWakeTransactionRef; box ownerWakeLedgerRef; box ownerWakeReceiptCount; box ownerWakeRejectedRef; box (DiagJson.esc (terminalFlowWakerRegistryVerdictText ownerWakeRegistryVerdict)); box ownerWakeMatches |])
                let! artifactReceipt =
                    if not ownerWakeMatches then
                        job { return terminalFlowRejectedArtifactReceipt writer (CompilerKernelV2.OperationalReasonIdOps.create "writer_owner_waker_alt_rejected_or_receipt_mismatch") }
                    elif openAfter <> 0L then
                        job { return terminalFlowRejectedArtifactReceipt writer (CompilerKernelV2.OperationalReasonIdOps.create "writer_owner_ledger_not_empty") }
                    elif String.IsNullOrWhiteSpace writer.ownerClosureCertificateId
                         || String.IsNullOrWhiteSpace writer.ownerTransactionId
                         || String.IsNullOrWhiteSpace (terminalFlowWriterTerminalReceiptText writer) then
                        job { return terminalFlowRejectedArtifactReceipt writer (CompilerKernelV2.OperationalReasonIdOps.create "writer_owner_closure_identity_missing") }
                    else
                        match writer.artifactPlan.manifestDisposition with
                        | TerminalFlowTerminalFailureManifest(reasonRef, reason) ->
                            job {
                                let failureManifestId = "terminal-failure-manifest:" + writer.artifactPlan.planId
                                let failureManifestRef : TerminalFlowIdentityRef<TerminalFlowArtifactManifestRefKind> =
                                    terminalFlowIdentityRefOfText failureManifestId
                                let receipt =
                                    { plan = writer.artifactPlan
                                      authorization = TerminalFlowArtifactsAuthorizedByTerminalFailure(failureManifestRef, reasonRef, reason)
                                      execution = TerminalFlowArtifactsTerminalFailureProjected(writer.artifactPlan.planId, failureManifestRef, reasonRef, reason, writer.artifactPlan.intents)
                                      manifestLifecycle = TerminalFlowArtifactManifestFailureProjected(failureManifestRef, reasonRef, reason)
                                      writerCompletionRoute = TerminalFlowWriterCompletionTypedFailure(reasonRef, reason) }
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"terminal_artifact_manifest_lifecycle\",\"lifecycle_du\":\"TerminalFailureManifest(ProjectedWithoutBuildDraft)\",\"dispatch_ref\":%u,\"fill_ref\":%u,\"failure_manifest_ref\":%u,\"reason_ref\":%u,\"filled_by\":\"scheduler_push_actor\",\"build_draft_required\":false,\"actor_hopac_continuation_state\":\"ArtifactFailureReceiptReady\",\"terminal_completion_open\":true,\"reducer_released_before_terminal_completion\":false,\"polling_authority\":false}" [| box (terminalFlowMintedRefOf "dispatch_ref" dispatch.dispatchId); box (terminalFlowMintedRefOf "fill_ref" dispatch.fillKey); box (terminalFlowMintedRefOf "artifact_failure_manifest_ref" failureManifestId); box reasonRef |])
                                return receipt
                            }
                        | TerminalFlowBuildDraftManifestRequired ->
                            job {
                                let completion =
                                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<TerminalFlowArtifactWriteReceipt<TerminalFlowArtifactsCommittedState>>
                                        "terminal-artifact-commit-completion"
                                let candidate =
                                    terminalFlowArtifactCommitRequestCreate
                                        requestId
                                        writer.artifactPlan.nativeBridge.cellId
                                        writer
                                        completion
                                let nativeCellKeyRef = terminalFlowNativeCellKeyRef candidate.nativeCellId
                                let request =
                                    if terminalFlowArtifactCommitRegistry.TryAdd(nativeCellKeyRef, candidate) then
                                        candidate
                                    else
                                        match terminalFlowArtifactCommitRegistry.TryGetValue nativeCellKeyRef with
                                        | true, existing -> existing
                                        | false, _ -> candidate
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"terminal_artifact_commit_request\",\"cell_ref\":%u,\"request_ref\":%u,\"plan_ref\":%u,\"kind_bridge_ref\":%u,\"sealed_stage_ref\":%u,\"writer_stage_ref\":%u,\"intent_count\":%d,\"stage_authority\":\"typed_kernel_stage_capability\",\"artifact_manifest_lifecycle_du\":\"BuildDraftManifest(Armed)\"}" [| box (NativeCutoverStableRef.ref32 "artifact-native-cell" [request.nativeCellId]); box (request.requestRef); box (NativeCutoverStableRef.ref32 "artifact-plan" [writer.artifactPlan.planId]); box (NativeCutoverStableRef.ref32 "artifact-kind-bridge" [writer.artifactPlan.kindBridge.bridgeId]); box (terminalFlowStageRef writer.sealedOutcomeStage); box (terminalFlowStageRef writer.writerBoundStage); box writer.artifactPlan.intents.Length |])
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"terminal_artifact_commit_rendezvous_ready\",\"dispatch_ref\":%u,\"fill_ref\":%u,\"request_ref\":%u,\"native_cell_ref\":%u,\"actor_hopac_continuation_state\":\"AwaitingArtifactManifestIVar\",\"artifact_rendezvous_state_du\":\"ArtifactRendezvous(Ready|caller_released=false|actor_waiting=artifact_manifest)\",\"terminal_outcome_ivar_fill_status\":\"Filled\",\"unresolved_phantom_refs\":0,\"probation_drain_target_id\":\"none\",\"completion_released_before_artifact_manifest\":false,\"actor_continues_on_request_ivar\":true,\"reducer_waits_for_terminal_completion\":true,\"polling_authority\":false}" [| box (terminalFlowMintedRefOf "dispatch_ref" dispatch.dispatchId); box (terminalFlowMintedRefOf "fill_ref" dispatch.fillKey); box (request.requestRef); box (NativeCutoverStableRef.ref32 "artifact-native-cell" [request.nativeCellId]) |])
                                do!
                                    CompilerKernelV2.CompilerRuntimeKernel.send
                                        terminalFlowArtifactCommitRequestChannel
                                        request
                                return!
                                    CompilerKernelV2.CompilerRuntimeKernel.readOneShot request.completion
                            }
                let artifactCorridor = terminalFlowArtifactCorridorFor artifactReceipt
                let boundary =
                    match artifactCorridor.writerCompletionRoute with
                    | TerminalFlowWriterCompletionGreenPath(_, artifactSetHash, intentCount) when intentCount > 0 ->
                        TerminalFlowPhysicalBoundaryOwnedByWriterReceipt(writerJobId, artifactSetHash)
                    | TerminalFlowWriterCompletionGreenPath(_, _, _) ->
                        TerminalFlowPhysicalBoundaryRejected(CompilerKernelV2.OperationalReasonIdOps.create "artifact_manifest_green_path_has_no_intents")
                    | TerminalFlowWriterCompletionTypedFailure(_, reason) ->
                        TerminalFlowPhysicalBoundaryRejected(CompilerKernelV2.OperationalReasonIdOps.create ("terminal_failure_manifest_projected|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason))
                    | TerminalFlowWriterCompletionRejected(_, reason) ->
                        TerminalFlowPhysicalBoundaryRejected reason
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_writer_completion_route\",\"writer_job_ref\":%u,\"terminal_receipt_ref\":%u,\"manifest_lifecycle_du\":\"%s\",\"writer_completion_route_du\":\"%s\",\"artifact_corridor_surface_du\":\"%s\",\"artifact_corridor_mutation_authority_du\":\"%s\",\"green_path_authority\":%b,\"polling_authority\":false}" [| box (terminalFlowMintedRefOf "writer_job_ref" writerJobId); box (terminalFlowIdentityRefDigest writer.terminalReceiptRef); box (terminalFlowArtifactManifestLifecycleText artifactCorridor.manifestLifecycle); box (terminalFlowWriterCompletionRouteText artifactCorridor.writerCompletionRoute); box (terminalFlowProtocolSurfaceText artifactCorridor.surface); box (terminalFlowReducerMutationAuthorityText artifactCorridor.mutationAuthority); box (match artifactCorridor.writerCompletionRoute with | TerminalFlowWriterCompletionGreenPath _ -> true | _ -> false) |])
                return {
                    writerJobId = writerJobId
                    writerLeaseId = writer.writerLeaseId
                    terminalReceiptRef = writer.terminalReceiptRef
                    ownerTransactionId = writer.ownerTransactionId
                    ownerLedgerOpenAfter = openAfter
                    artifactReceipt = artifactReceipt
                    artifactCorridor = artifactCorridor
                    registryLifecycle = TerminalFlowRegistryPruneRequired writer.artifactPlan.nativeBridge.cellId
                    physicalBoundary = boundary
                    artifactCommittedStage = terminalFlowArtifactCommittedStageForWriter writer artifactReceipt
                }
            }

        // The outer BuildDraft producer and terminal writer rendezvous on a Hopac
        // channel. No mutable projection queue or empty-queue retry surface remains.

        let private terminalFlowCommitArtifactsForRequest
            (request:TerminalFlowArtifactCommitRequest)
            (artifactManifestText:string)
            : Result<TerminalFlowBuildDraftCommitReceipt,CompilerKernelV2.OperationalReasonId> =
            let bridge = request.writer.artifactPlan.nativeBridge
            let kindBridge = request.writer.artifactPlan.kindBridge
            let bridgeValid = terminalFlowNativeRootBridgeIsValid bridge
            let cellId = request.nativeCellId
            let artifactSetHash =
                DiagJson.nativeWriterArtifactSetHashForText
                    bridge.expectedArtifactSetHash
                    artifactManifestText
            let receipt =
                if not bridgeValid
                   || bridge.cellId <> cellId
                   || kindBridge.terminalKindProofHash <> bridge.proofHash
                   || kindBridge.evalGraphOwnerTransactionId <> request.writer.ownerTransactionId
                   || kindBridge.ownerClosureCertificateId <> request.writer.ownerClosureCertificateId
                   || String.IsNullOrWhiteSpace bridge.workDagClosureHash
                   || String.IsNullOrWhiteSpace bridge.expectedArtifactSetHash then
                    terminalFlowRejectedArtifactReceipt request.writer (CompilerKernelV2.OperationalReasonIdOps.create "artifact_commit_native_capability_mismatch")
                else
                    let manifestId = "buildok-artifact-manifest:" + request.writer.artifactPlan.planId
                    let manifestRef : TerminalFlowIdentityRef<TerminalFlowArtifactManifestRefKind> =
                        terminalFlowIdentityRefOfText manifestId
                    {
                        plan = request.writer.artifactPlan
                        authorization = TerminalFlowArtifactsAuthorizedByNativeRootComplete(bridge, artifactSetHash)
                        execution = TerminalFlowArtifactsExecuted(request.writer.artifactPlan.planId, artifactSetHash, request.writer.artifactPlan.intents)
                        manifestLifecycle = TerminalFlowArtifactManifestFilled(manifestRef, artifactSetHash, artifactManifestText.Length, "BuildDraft.Provisional")
                        writerCompletionRoute = TerminalFlowWriterCompletionGreenPath(manifestRef, artifactSetHash, request.writer.artifactPlan.intents.Length)
                    }
            DiagJson.emit (
                FastRuntimeFormat.format "{\"kind\":\"terminal_artifact_manifest_lifecycle\",\"lifecycle_du\":\"%s\",\"request_ref\":%u,\"native_cell_ref\":%u,\"manifest_ref\":%u,\"writer_completion_route_du\":\"%s\",\"filled_by\":\"BuildDraft.Provisional\",\"build_draft_required\":true,\"manifest_byte_count\":%d,\"persistence_state_du\":\"PreparedAwaitingFilesystemCommit\",\"polling_authority\":false}" [| box (terminalFlowArtifactManifestLifecycleText receipt.manifestLifecycle); box (request.requestRef); box (terminalFlowMintedRefOf "native_cell_ref" request.nativeCellId); box (match receipt.manifestLifecycle with | TerminalFlowArtifactManifestFilled(manifestRef, _, _, _) -> terminalFlowMintedRefOf "artifact_manifest_ref" (terminalFlowIdentityRefText manifestRef) | _ -> 0u); box (terminalFlowWriterCompletionRouteText receipt.writerCompletionRoute); box artifactManifestText.Length |])
            match receipt.execution with
            | TerminalFlowArtifactsExecuted(_, committedHash, _) ->
                let capabilityText = terminalFlowNativeRootBridgeCapabilityText bridge
                let resolutionText = terminalFlowNativeRootBridgeResolutionText bridge
                let workDagText = terminalFlowNativeRootBridgeWorkDagText bridge
                let terminalSealText =
                    DiagJson.nativeWriterBuildOkSealText
                        cellId
                        capabilityText
                        committedHash
                        resolutionText
                        workDagText
                let persistenceDecision =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<TerminalFlowArtifactPersistenceDecision>
                        "terminal-artifact-persistence-decision"
                let persistenceFinalizer =
                    CompilerKernelV2.CompilerRuntimeKernel.effect
                        "terminal-artifact-persistence-finalizer"
                        (job {
                            let! decision =
                                CompilerKernelV2.CompilerRuntimeKernel.readOneShot persistenceDecision
                            let completionReceipt =
                                match decision with
                                | TerminalFlowArtifactPersistenceCommitted _ -> receipt
                                | TerminalFlowArtifactPersistenceRejected reason ->
                                    terminalFlowRejectedArtifactReceipt request.writer (CompilerKernelV2.OperationalReasonIdOps.create ("artifact_filesystem_persistence_rejected|" + CompilerKernelV2.OperationalReasonIdOps.text reason))
                            do!
                                CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                    request.completion
                                    completionReceipt
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_artifact_persistence_finalized\",\"request_ref\":%u,\"native_cell_ref\":%u,\"decision_du\":%s,\"artifact_set_hash\":%s,\"authority\":\"filesystem_write_after_writeguard\"}" [| box (request.requestRef); box (terminalFlowMintedRefOf "native_cell_ref" request.nativeCellId); box (DiagJson.esc (terminalFlowArtifactPersistenceDecisionText decision)); box (DiagJson.esc committedHash) |])
                        })
                HopacExtensions.start
                    (CompilerKernelV2.CompilerRuntimeKernel.toJob persistenceFinalizer)
                Ok {
                    cellId = cellId
                    artifactSetHash = committedHash
                    capabilityText = capabilityText
                    resolutionText = resolutionText
                    workDagText = workDagText
                    terminalSealText = terminalSealText
                    finalize =
                        fun decision ->
                            CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                persistenceDecision
                                decision
                }
            | TerminalFlowArtifactsTerminalFailureProjected(_, _, _, reason, _)
            | TerminalFlowArtifactsExecutionRejected(_, _, reason) ->
                let rejectionRelease =
                    CompilerKernelV2.CompilerRuntimeKernel.effect
                        "terminal-artifact-preflight-rejection"
                        (CompilerKernelV2.CompilerRuntimeKernel.fillOneShot request.completion receipt)
                HopacExtensions.start
                    (CompilerKernelV2.CompilerRuntimeKernel.toJob rejectionRelease)
                Error (CompilerKernelV2.OperationalReasonIdOps.create ("artifact_commit_preflight_rejected|" + CompilerKernelV2.OperationalReasonIdOps.text reason))

        let terminalFlowCommitArtifactsFromBuildDraftJob
            (artifactManifestText:string)
            : Hopac.Job<Result<TerminalFlowBuildDraftCommitReceipt,CompilerKernelV2.OperationalReasonId>> =
            job {
                let! request =
                    CompilerKernelV2.CompilerRuntimeKernel.take terminalFlowArtifactCommitRequestChannel
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_artifact_manifest_rendezvous_matched\",\"request_ref\":%u,\"native_cell_ref\":%u,\"manifest_byte_count\":%d,\"authority\":\"hopac_symmetric_channel\",\"polling_authority\":false,\"next\":\"prepare_then_wait_filesystem_commit\"}" [| box (request.requestRef); box (NativeCutoverStableRef.ref32 "artifact-native-cell" [request.nativeCellId]); box artifactManifestText.Length |])
                return terminalFlowCommitArtifactsForRequest request artifactManifestText
            }

        let terminalFlowRejectArtifactsFromBuildDraft (reason:CompilerKernelV2.OperationalReasonId) =
            let reasonText = CompilerKernelV2.OperationalReasonIdOps.text reason
            let rejectionEffect =
                CompilerKernelV2.CompilerRuntimeKernel.effect
                    "terminal-artifact-build-draft-rejection"
                    (job {
                        let! request =
                            CompilerKernelV2.CompilerRuntimeKernel.take terminalFlowArtifactCommitRequestChannel
                        let receipt =
                            terminalFlowRejectedArtifactReceipt
                                request.writer
                                (CompilerKernelV2.OperationalReasonIdOps.create ("build_draft_failed_before_persistence|" + reasonText))
                        do!
                            CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                request.completion
                                receipt
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_artifact_build_draft_rejected\",\"request_ref\":%u,\"native_cell_ref\":%u,\"reason\":%s,\"authority\":\"build_draft_failure_releases_writer\"}" [| box (request.requestRef); box (NativeCutoverStableRef.ref32 "artifact-native-cell" [request.nativeCellId]); box (DiagJson.esc reasonText) |])
                    })
            HopacExtensions.start
                (CompilerKernelV2.CompilerRuntimeKernel.toJob rejectionEffect)

        type TerminalFlowSyntheticBuildOkHarnessReceipt = private {
            manifestLifecycle : TerminalFlowArtifactManifestLifecycle
            writerCompletionRoute : TerminalFlowWriterCompletionRoute
            cicCorridor : TerminalFlowCicKernelCorridor
            kernelProofAuthority : TerminalFlowKernelProofAuthority
            cicPromotionReceipt : Result<TerminalFlowCicArtifactPromotionReceipt, TerminalFlowCicBlocker>
            breakthroughReceipts : TerminalFlowBreakthroughTransitionReceipt list
            breakthroughProtocol : TerminalFlowBreakthroughProtocol
            manifestIvarFilled : bool
            writerWouldExitCode : int
        }


        // Migration round : executable admission-to-run_end fixture.  The fixture
        // composes the real admission/install/consume, ghost-recovery and fairness
        // domains, then materializes the commit/done/run_end total-order receipts.
        // Each stage is phantom-indexed and every proof node retains its predecessor,
        // so skipping a stage requires constructing an impossible value.
        type TerminalFlowAdmissionRunEndFixtureRefKind private () =
            static member IdentityKindTag () = 0x090001u
        type TerminalFlowAdmissionFixtureAdmittedStage = class end
        type TerminalFlowAdmissionFixtureInstalledStage = class end
        type TerminalFlowAdmissionFixtureConsumeEnqueuedStage = class end
        type TerminalFlowAdmissionFixtureRecoveredStage = class end
        type TerminalFlowAdmissionFixtureFairnessReleasedStage = class end
        type TerminalFlowAdmissionFixtureCommittedStage = class end
        type TerminalFlowAdmissionFixtureDoneStage = class end
        type TerminalFlowAdmissionFixtureRunEndedStage = class end

        type TerminalFlowAdmissionRunEndProof =
            | TerminalFlowAdmissionFixtureAdmitted of TerminalFlowOutcomeAdmission
            | TerminalFlowAdmissionFixtureInstalled of previous:TerminalFlowAdmissionRunEndProof * installation:TerminalFlowOutcomeInstallation * duplicateSuppressed:bool
            | TerminalFlowAdmissionFixtureConsumeEnqueued of previous:TerminalFlowAdmissionRunEndProof * installation:TerminalFlowOutcomeInstallation
            | TerminalFlowAdmissionFixtureRecovered of previous:TerminalFlowAdmissionRunEndProof * recovery:TerminalFlowQueueRecoveryCertificate
            | TerminalFlowAdmissionFixtureFairnessReleased of previous:TerminalFlowAdmissionRunEndProof * release:TerminalFlowFairnessReleaseReceipt
            | TerminalFlowAdmissionFixtureCommitted of previous:TerminalFlowAdmissionRunEndProof * receipt:TerminalFlowTotalOrderReceipt<TerminalOrderCommittedStage>
            | TerminalFlowAdmissionFixtureDone of previous:TerminalFlowAdmissionRunEndProof * receipt:TerminalFlowTotalOrderReceipt<TerminalOrderDoneStage>
            | TerminalFlowAdmissionFixtureRunEnded of previous:TerminalFlowAdmissionRunEndProof * receipt:TerminalFlowTotalOrderReceipt<TerminalOrderRunEndedStage>

        type TerminalFlowAdmissionRunEndTxn<'Stage> = private {
            fixtureRef : TerminalFlowIdentityRef<TerminalFlowAdmissionRunEndFixtureRefKind>
            proof : TerminalFlowAdmissionRunEndProof
        }

        type TerminalFlowAdmissionRunEndFixtureReceipt = private {
            fixtureRef : uint32
            admissionRef : uint32
            installationRef : uint32
            consumeRef : uint32
            recoveryRef : uint32
            fairnessReleaseRef : uint32
            commitRef : uint32
            doneRef : uint32
            runEndRef : uint32
            duplicateInstallSuppressed : bool
            consumeEnqueued : bool
            fairnessReleased : bool
            reducerOwned : bool
            expectedJsonKind : string
        }

        let private terminalFlowAdmissionRunEndFixtureOpen planId : TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureAdmittedStage> =
            let fixtureRef : TerminalFlowIdentityRef<TerminalFlowAdmissionRunEndFixtureRefKind> =
                terminalFlowIdentityRefOfText ("admission-run-end-fixture:" + planId)
            let admissionRawRef = NativeCutoverStableRef.ref32 "fixture-admission" [planId]
            let terminalReceiptId = "fixture-terminal-receipt:" + planId
            let fillKey = "fixture-fill:" + planId
            let identity = terminalFlowAdmissionIdentityFor terminalReceiptId fillKey admissionRawRef
            let admission =
                terminalFlowOutcomeAdmissionForIdentity
                    terminalReceiptId
                    fillKey
                    identity
                    TerminalFlowOutcomeInstallFromEvaluatorNotice
            { fixtureRef = fixtureRef
              proof = TerminalFlowAdmissionFixtureAdmitted admission }

        let private terminalFlowAdmissionRunEndFixtureInstall (txn:TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureAdmittedStage>) =
            match txn.proof with
            | TerminalFlowAdmissionFixtureAdmitted admission ->
                match terminalFlowOutcomeInstallTransitionFor TerminalFlowOutcomeNotInstalled admission 1L with
                | TerminalFlowOutcomeInstallAccepted installation ->
                    match terminalFlowOutcomeInstallTransitionFor installation admission 2L with
                    | TerminalFlowOutcomeInstallDuplicateSuppressed(existing, false) ->
                        Ok ({ fixtureRef = txn.fixtureRef
                              proof = TerminalFlowAdmissionFixtureInstalled(txn.proof, existing, true) } : TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureInstalledStage>)
                    | TerminalFlowOutcomeInstallIdentityRefreshed _ ->
                        Error "fixture_duplicate_payload_mismatch_refreshed"
                    | TerminalFlowOutcomeInstallDuplicateSuppressed(_, true) ->
                        Error "fixture_duplicate_payload_mismatch"
                    | TerminalFlowOutcomeInstallAccepted _ ->
                        Error "fixture_admission_identity_not_exact_once"
                | TerminalFlowOutcomeInstallIdentityRefreshed _ ->
                    Error "fixture_first_install_refreshed"
                | TerminalFlowOutcomeInstallDuplicateSuppressed _ ->
                    Error "fixture_first_install_was_suppressed"
            | _ -> Error "fixture_admission_stage_corrupt"

        let private terminalFlowAdmissionRunEndFixtureConsume (txn:TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureInstalledStage>) =
            match txn.proof with
            | TerminalFlowAdmissionFixtureInstalled(_, installation, _) ->
                let tokenId = sprintf "fixture-stage-token:%u" (terminalFlowIdentityRefDigest txn.fixtureRef)
                match terminalFlowOutcomeMarkConsumeEnqueued tokenId 3L installation with
                | TerminalFlowOutcomeConsumeEnqueued _ as consumed ->
                    Ok ({ fixtureRef = txn.fixtureRef
                          proof = TerminalFlowAdmissionFixtureConsumeEnqueued(txn.proof, consumed) } : TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureConsumeEnqueuedStage>)
                | _ -> Error "fixture_consume_was_not_enqueued"
            | _ -> Error "fixture_install_stage_corrupt"

        let private terminalFlowAdmissionRunEndFixtureRecover (txn:TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureConsumeEnqueuedStage>) =
            let fixtureDigest = terminalFlowIdentityRefDigest txn.fixtureRef
            let gateRef : TerminalFlowIdentityRef<TerminalFlowTopologyGateRefKind> =
                terminalFlowIdentityRefOfText (sprintf "fixture-topology-gate:%u" fixtureDigest)
            let progressSnapshotRef : TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind> =
                terminalFlowIdentityRefOfText (sprintf "fixture-progress-snapshot:%u" fixtureDigest)
            let gate : TerminalFlowTopologyGateTransition =
                { gateRef = gateRef
                  cause = TerminalFlowTopologyGateQapRelationsConsumed(fixtureDigest, 1)
                  beforeQueueDepth = 1L
                  afterQueueDepth = 0L
                  progressSnapshotRef = progressSnapshotRef
                  openedAtMs = 4L }
            let recovery =
                TerminalFlowRecoveryFromGhostReconciliation(gate, fixtureDigest, 1)
                |> terminalFlowQueueRecoveryCertificateFor
            { fixtureRef = txn.fixtureRef
              proof = TerminalFlowAdmissionFixtureRecovered(txn.proof, recovery) } : TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureRecoveredStage>

        let private terminalFlowAdmissionRunEndFixtureCompleteFairness _epochRebase workerBudget completedWorkers (txn:TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureRecoveredStage>) =
            let fixtureDigest = terminalFlowIdentityRefDigest txn.fixtureRef
            let sampleRef : TerminalFlowIdentityRef<TerminalFlowFairnessEpochRefKind> =
                terminalFlowIdentityRefOfText (sprintf "fixture-fairness-sample:%u" fixtureDigest)
            let driverRef : TerminalFlowIdentityRef<TerminalFlowReplayDriverRefKind> =
                terminalFlowIdentityRefOfText (sprintf "fixture-fairness-driver:%u" fixtureDigest)
            let progressSnapshotRef : TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind> =
                terminalFlowIdentityRefOfText (sprintf "fixture-fairness-progress:%u" fixtureDigest)
            let fairnessEpochRef : TerminalFlowIdentityRef<TerminalFlowFairnessEpochRefKind> =
                terminalFlowIdentityRefOfText (sprintf "fixture-fairness-epoch:%u" fixtureDigest)
            let sample : TerminalFlowReplayDriverFairnessSample =
                { sampleRef = sampleRef
                  driverRef = driverRef
                  lineage =
                    TerminalFlowAdmissionFairnessLineage(
                        fixtureDigest,
                        terminalFlowMintedRefOf "fixture-admission-identity" (string fixtureDigest),
                        terminalFlowMintedRefOf "fixture-actor-binding" (string fixtureDigest),
                        terminalFlowMintedRefOf "fixture-credential-ledger" (string fixtureDigest),
                        fairnessEpochRef)
                  lane = TerminalFlowReplayDriverLaneCrossKindActive
                  queueDepth = 0L
                  activeWorkers = 0L
                  retiredWork = int64 (max 0 completedWorkers)
                  starvationScore = 0L
                  progressSnapshotRef = progressSnapshotRef
                  sampledAtMs = 7L }
            let creditConserved = max 0 workerBudget = max 0 completedWorkers
            let creditDigest =
                CompilerIdentityKernel.ContentDigest.ofText
                    "fixture-terminal-credit-return"
                    (FastRuntimeFormat.format "%u|%d|%d" [| box fixtureDigest; box workerBudget; box completedWorkers |])
            let release =
                terminalFlowFairnessReleaseFor
                    sample
                    (TerminalFlowFairnessReleaseByQuiescence creditDigest)
                    7L
            let verdict = TerminalFlowFairnessReleasedByQuiescence(sample, creditDigest)
            let schedule =
                terminalFlowReplayDriverScheduleAdvance
                    6L
                    verdict
                    (Some release)
                    terminalFlowReplayDriverScheduleInitial
            match creditConserved, schedule.schedulerLease with
            | false, _ -> Error "fixture_credit_conservation_mismatch"
            | true, Some (TerminalFlowAdmissionSchedulerReleased schedulerRelease)
                when terminalFlowIdentityRefDigest schedulerRelease.fairnessReleaseRef = terminalFlowIdentityRefDigest release.releaseRef ->
                Ok ({ fixtureRef = txn.fixtureRef
                      proof = TerminalFlowAdmissionFixtureFairnessReleased(txn.proof, release) } : TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureFairnessReleasedStage>)
            | true, Some (TerminalFlowAdmissionSchedulerRejected(_, _, reason)) ->
                Error ("fixture_fairness_scheduler_rejected:" + terminalFlowSchedulerReleaseRejectionText reason)
            | _ -> Error "fixture_fairness_quiescence_release_missing_scheduler_physical_release"

        let private terminalFlowAdmissionRunEndFixtureCommit (txn:TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureFairnessReleasedStage>) =
            let fixtureDigest = terminalFlowIdentityRefDigest txn.fixtureRef
            let predecessorRef =
                match txn.proof with
                | TerminalFlowAdmissionFixtureFairnessReleased(_, release) -> terminalFlowIdentityRefDigest release.releaseRef
                | _ -> 0u
            let commitRef = terminalFlowMintedRefOf "fixture_total_order_commit" (sprintf "%u:%u" fixtureDigest predecessorRef)
            let receipt : TerminalFlowTotalOrderReceipt<TerminalOrderCommittedStage> =
                { orderIndex = 8L
                  receiptRef = commitRef
                  predecessorRef = Some predecessorRef
                  fillKey = TerminalFlowTotalOrderFillBound (TerminalFlowFillKeyId.create (sprintf "fixture-fill:%u" fixtureDigest))
                  exactOnce = true }
            { fixtureRef = txn.fixtureRef
              proof = TerminalFlowAdmissionFixtureCommitted(txn.proof, receipt) } : TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureCommittedStage>

        let private terminalFlowAdmissionRunEndFixtureDone (txn:TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureCommittedStage>) =
            let commitRef =
                match txn.proof with
                | TerminalFlowAdmissionFixtureCommitted(_, receipt) -> receipt.receiptRef
                | _ -> 0u
            let doneRef = terminalFlowMintedRefOf "fixture_total_order_done" (string commitRef)
            let receipt : TerminalFlowTotalOrderReceipt<TerminalOrderDoneStage> =
                { orderIndex = 9L
                  receiptRef = doneRef
                  predecessorRef = Some commitRef
                  fillKey = TerminalFlowTotalOrderFillBound (TerminalFlowFillKeyId.create (sprintf "fixture-fill:%u" (terminalFlowIdentityRefDigest txn.fixtureRef)))
                  exactOnce = true }
            { fixtureRef = txn.fixtureRef
              proof = TerminalFlowAdmissionFixtureDone(txn.proof, receipt) } : TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureDoneStage>

        let private terminalFlowAdmissionRunEndFixtureRunEnd (txn:TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureDoneStage>) =
            let doneRef =
                match txn.proof with
                | TerminalFlowAdmissionFixtureDone(_, receipt) -> receipt.receiptRef
                | _ -> 0u
            let runEndRef = terminalFlowMintedRefOf "fixture_total_order_run_end" (string doneRef)
            let receipt : TerminalFlowTotalOrderReceipt<TerminalOrderRunEndedStage> =
                { orderIndex = 10L
                  receiptRef = runEndRef
                  predecessorRef = Some doneRef
                  fillKey = TerminalFlowTotalOrderFillBound (TerminalFlowFillKeyId.create (sprintf "fixture-fill:%u" (terminalFlowIdentityRefDigest txn.fixtureRef)))
                  exactOnce = true }
            { fixtureRef = txn.fixtureRef
              proof = TerminalFlowAdmissionFixtureRunEnded(txn.proof, receipt) } : TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureRunEndedStage>

        let private terminalFlowAdmissionRunEndFixtureReceipt (txn:TerminalFlowAdmissionRunEndTxn<TerminalFlowAdmissionFixtureRunEndedStage>) =
            match txn.proof with
            | TerminalFlowAdmissionFixtureRunEnded(
                TerminalFlowAdmissionFixtureDone(
                    TerminalFlowAdmissionFixtureCommitted(
                        TerminalFlowAdmissionFixtureFairnessReleased(
                            TerminalFlowAdmissionFixtureRecovered(
                                TerminalFlowAdmissionFixtureConsumeEnqueued(
                                    TerminalFlowAdmissionFixtureInstalled(
                                        TerminalFlowAdmissionFixtureAdmitted admission,
                                        _,
                                        duplicateSuppressed),
                                    TerminalFlowOutcomeConsumeEnqueued(_, installationRef, _, consumeRef, _)),
                                recovery),
                            release),
                        commitReceipt),
                    doneReceipt),
                runEndReceipt) ->
                Ok {
                    fixtureRef = terminalFlowIdentityRefDigest txn.fixtureRef
                    admissionRef = terminalFlowAdmissionIdentityRef admission.identity
                    installationRef = terminalFlowIdentityRefDigest installationRef
                    consumeRef = terminalFlowIdentityRefDigest consumeRef
                    recoveryRef = terminalFlowIdentityRefDigest recovery.recoveryRef
                    fairnessReleaseRef = terminalFlowIdentityRefDigest release.releaseRef
                    commitRef = commitReceipt.receiptRef
                    doneRef = doneReceipt.receiptRef
                    runEndRef = runEndReceipt.receiptRef
                    duplicateInstallSuppressed = duplicateSuppressed
                    consumeEnqueued = true
                    fairnessReleased = true
                    reducerOwned = true
                    expectedJsonKind = "run_end"
                }
            | _ -> Error "fixture_proof_chain_not_total"

        let private terminalFlowAdmissionToRunEndFixture planId epochRebase workerBudget completedWorkers =
            let opened = terminalFlowAdmissionRunEndFixtureOpen planId
            match terminalFlowAdmissionRunEndFixtureInstall opened with
            | Error reason -> Error reason
            | Ok installed ->
                match terminalFlowAdmissionRunEndFixtureConsume installed with
                | Error reason -> Error reason
                | Ok consumed ->
                    let recovered = terminalFlowAdmissionRunEndFixtureRecover consumed
                    match terminalFlowAdmissionRunEndFixtureCompleteFairness epochRebase workerBudget completedWorkers recovered with
                    | Error reason -> Error reason
                    | Ok fair ->
                        fair
                        |> terminalFlowAdmissionRunEndFixtureCommit
                        |> terminalFlowAdmissionRunEndFixtureDone
                        |> terminalFlowAdmissionRunEndFixtureRunEnd
                        |> terminalFlowAdmissionRunEndFixtureReceipt

        type TerminalFlowAdmissionRunEndFixtureVector = private {
            name : string
            epochRebase : bool
            workerBudget : int
            completedWorkers : int
            expectRunEnd : bool
            expectedFailure : string option
        }

        let private terminalFlowAdmissionRunEndFixtureVectors =
            [ { name = "admission_install_consume_recovery_fairness_run_end"
                epochRebase = false
                workerBudget = 2
                completedWorkers = 2
                expectRunEnd = true
                expectedFailure = None }
              { name = "admission_epoch_rebase_completion_run_end"
                epochRebase = true
                workerBudget = 3
                completedWorkers = 3
                expectRunEnd = true
                expectedFailure = None }
              { name = "fairness_scheduling_is_not_completion"
                epochRebase = false
                workerBudget = 2
                completedWorkers = 1
                expectRunEnd = false
                expectedFailure = Some "fixture_credit_conservation_mismatch" } ]

        let private terminalFlowAdmissionRunEndFixtureVectorReceipts () =
            terminalFlowAdmissionRunEndFixtureVectors
            |> List.map (fun vector ->
                vector,
                terminalFlowAdmissionToRunEndFixture vector.name vector.epochRebase vector.workerBudget vector.completedWorkers)

        type TerminalFlowCompileRescueGate =
            | TerminalFlowCompileRescueParseAndTypecheck
            | TerminalFlowCompileRescueInstallExactOnce
            | TerminalFlowCompileRescueConsumeHandoff
            | TerminalFlowCompileRescueRecoveryCertificate
            | TerminalFlowCompileRescueFairnessCompletion
            | TerminalFlowCompileRescueAdmissionIdentity
            | TerminalFlowCompileRescueSchedulerPhysicalRelease
            | TerminalFlowCompileRescueChannelRootAuthority
            | TerminalFlowCompileRescueWakerWorkerLedger
            | TerminalFlowCompileRescueTotalOrder
            | TerminalFlowCompileRescueNegativeFixture
            | TerminalFlowCompileRescueAntiDrift
            | TerminalFlowCompileRescueBundleGates
            | TerminalFlowCompileRescueRuntimeAuthorization

        type TerminalFlowCompileRescueExternalAuditReasonId =
            | TerminalFlowCompileRescueProductionFixtureRequiresLiveReducer
            | TerminalFlowCompileRescueStaticSourceAuditRequired
            | TerminalFlowCompileRescueEoieBundleReceiptsRequired
            | TerminalFlowCompileRescueExternalBuildAndBoundedRunRequired

        type TerminalFlowCompileRescueGateAuthority =
            | TerminalFlowCompileRescueSatisfiedByModuleLoad of authorityRef:uint32
            | TerminalFlowCompileRescueSatisfiedByFixture of authorityRef:uint32
            | TerminalFlowCompileRescuePendingExternalAudit of reason:TerminalFlowCompileRescueExternalAuditReasonId
            | TerminalFlowCompileRescueBlocked of reason:CompilerKernelV2.OperationalReasonId

        type TerminalFlowCompileRescueManifest = private {
            gates : (TerminalFlowCompileRescueGate * TerminalFlowCompileRescueGateAuthority) list
            promotionCertificate : TerminalFlowAdmissionRunEndPromotionCertificate option
        }

        let private terminalFlowAdmissionRunEndPromotionCertificate () =
            let positive =
                terminalFlowAdmissionRunEndFixtureVectorReceipts ()
                |> List.tryPick (fun (vector, result) ->
                    if vector.expectRunEnd then
                        match result with
                        | Ok receipt -> Some receipt
                        | Error _ -> None
                    else None)
            let negativeSatisfied =
                terminalFlowAdmissionRunEndFixtureVectorReceipts ()
                |> List.exists (fun (vector, result) ->
                    match vector.expectedFailure, result with
                    | Some expected, Error actual when expected = actual -> true
                    | _ -> false)
            match positive, negativeSatisfied with
            | Some receipt, true ->
                let proofDigest =
                    NativeCutoverStableRef.ref32
                        "admission-run-end-proof-digest"
                        [ string receipt.fixtureRef
                          string receipt.admissionRef
                          string receipt.installationRef
                          string receipt.consumeRef
                          string receipt.recoveryRef
                          string receipt.fairnessReleaseRef
                          string receipt.commitRef
                          string receipt.doneRef
                          string receipt.runEndRef ]
                Some {
                    certificateRef = NativeCutoverStableRef.ref32 "admission-run-end-promotion-certificate" [string proofDigest]
                    fixtureRef = receipt.fixtureRef
                    admissionRef = receipt.admissionRef
                    installationRef = receipt.installationRef
                    consumeRef = receipt.consumeRef
                    recoveryRef = receipt.recoveryRef
                    fairnessReleaseRef = receipt.fairnessReleaseRef
                    commitRef = receipt.commitRef
                    doneRef = receipt.doneRef
                    runEndRef = receipt.runEndRef
                    gateMask = 127us
                    proofDigest = proofDigest
                }
            | _ -> None

        let private terminalFlowCompileRescueManifestCurrent () =
            let moduleAuthority = NativeCutoverStableRef.ref32 "compile-rescue-module-loaded" ["loaded"]
            let productionFixtureGate gate =
                match terminalFlowProductionFixtureCertificateAuthority with
                | Some certificate
                    when certificate.reducerGenesisRef <> 0u
                         && certificate.reducerPathRef <> 0u
                         && certificate.interpreterKernelRef <> 0u
                         && certificate.postCommitPlanRef <> 0u
                         && certificate.postCommitTransactionRef <> 0u
                         && certificate.appliedCapabilityRef <> 0u
                         && certificate.appliedCapabilityExactOnceRef <> 0u
                         && certificate.postCommitStageMask = 31us
                         && certificate.transactionRef <> 0u
                         && certificate.issuanceRef <> 0u
                         && certificate.issueEventRef <> 0u
                         && certificate.consumptionEventRef <> 0u
                         && certificate.runEndReceiptRef <> 0u
                         && certificate.physicalExitReceiptRef <> 0u
                         && certificate.exactOnceRef <> 0u
                         && terminalFlowProductionFixtureNegativeSuiteComplete certificate.negativeVerdicts ->
                    gate, TerminalFlowCompileRescueSatisfiedByFixture certificate.certificateRef
                | _ ->
                    gate,
                    TerminalFlowCompileRescuePendingExternalAudit
                        TerminalFlowCompileRescueProductionFixtureRequiresLiveReducer
            { gates =
                [ TerminalFlowCompileRescueParseAndTypecheck, TerminalFlowCompileRescueSatisfiedByModuleLoad moduleAuthority
                  productionFixtureGate TerminalFlowCompileRescueInstallExactOnce
                  productionFixtureGate TerminalFlowCompileRescueConsumeHandoff
                  productionFixtureGate TerminalFlowCompileRescueRecoveryCertificate
                  productionFixtureGate TerminalFlowCompileRescueFairnessCompletion
                  productionFixtureGate TerminalFlowCompileRescueAdmissionIdentity
                  productionFixtureGate TerminalFlowCompileRescueSchedulerPhysicalRelease
                  productionFixtureGate TerminalFlowCompileRescueChannelRootAuthority
                  productionFixtureGate TerminalFlowCompileRescueWakerWorkerLedger
                  productionFixtureGate TerminalFlowCompileRescueTotalOrder
                  productionFixtureGate TerminalFlowCompileRescueNegativeFixture
                  TerminalFlowCompileRescueAntiDrift,
                  TerminalFlowCompileRescuePendingExternalAudit TerminalFlowCompileRescueStaticSourceAuditRequired
                  TerminalFlowCompileRescueBundleGates,
                  TerminalFlowCompileRescuePendingExternalAudit TerminalFlowCompileRescueEoieBundleReceiptsRequired
                  TerminalFlowCompileRescueRuntimeAuthorization,
                  TerminalFlowCompileRescuePendingExternalAudit TerminalFlowCompileRescueExternalBuildAndBoundedRunRequired ]
              // Archival only.  This certificate no longer satisfies any gate.
              promotionCertificate = terminalFlowAdmissionRunEndPromotionCertificate () }

        let private terminalFlowOutcomeRegistryPrune (fillKey:TerminalFlowFillKeyId) =
            let fillKeyRef = terminalFlowFillKeyRefForId fillKey
            let fillKeyText = TerminalFlowFillKeyId.text fillKey
            let mutable ivarRemoved =
                { cellId = "terminal-outcome-ivar-tombstone"
                  fillKey = fillKey
                  ivar =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<TerminalFlowResolvedOutcomeEnvelope>
                        ("terminal-outcome-tombstone:" + fillKeyText) }
            let mutable fillRemoved = { cellId = "terminal-outcome-fill-tombstone"; fillKey = fillKey; receiptId = ""; ownerTransactionId = ""; firstFill = false }
            terminalFlowOutcomeIvarRegistry.TryRemove(fillKeyRef, &ivarRemoved) |> ignore
            terminalFlowOutcomeFillRegistry.TryRemove(fillKeyRef, &fillRemoved) |> ignore
            // Dispatch and completion remain as exact-once tombstones until the
            // physical process boundary. Removing them here allowed a late
            // owner-debt replay to start a second terminal pipeline.

        let private terminalFlowArtifactCommitRegistryPrune (nativeCellId:string) : TerminalFlowArtifactCommitRegistryPruneReceipt =
            let nativeCellKeyRef = terminalFlowNativeCellKeyRef nativeCellId
            let receipt kind requestId : TerminalFlowArtifactCommitRegistryPruneReceipt =
                { nativeCellId = nativeCellId
                  requestId = requestId
                  kind = kind
                  exactOnceRef =
                    terminalFlowMintedRefOf
                        "artifact_commit_registry_prune_exact_once_ref"
                        (String.concat ":" [nativeCellId; requestId; terminalFlowArtifactCommitRegistryPruneKindText kind]) }
            match terminalFlowArtifactCommitRegistry.TryGetValue nativeCellKeyRef with
            | true, request ->
                let removed =
                    terminalFlowArtifactCommitRegistry.TryRemove(
                        System.Collections.Generic.KeyValuePair<CompilerIdentityKernel.ContentDigest,TerminalFlowArtifactCommitRequest>(nativeCellKeyRef, request))
                if removed then receipt TerminalFlowArtifactCommitRegistryPruned request.requestId
                else receipt TerminalFlowArtifactCommitRegistryPruneMiss request.requestId
            | false, _ -> receipt TerminalFlowArtifactCommitRegistryPruneMiss "missing"

        let private terminalFlowSchedulerChannelCommandShapeFor (event:TerminalFlowSchedulerPushEventId) : TerminalFlowSchedulerChannelCommandShape =
            let actor domain refId : TerminalFlowSchedulerWitness<TerminalFlowSchedulerActorCommandWitnessKind> =
                terminalFlowSchedulerWitnessFor domain refId
            let stage refId : TerminalFlowSchedulerWitness<TerminalFlowSchedulerStageTokenWitnessKind> option =
                if refId = 0u then None else Some (terminalFlowSchedulerWitnessFor "scheduler-stage-token" refId)
            match event with
            | TerminalFlowPushResolvedOutcome prepared ->
                { eventCode = 1uy
                  kind = TerminalFlowSchedulerChannelAdmissionAccepted
                  actorCommand = actor "scheduler-command-resolved-outcome" (terminalFlowMintedRefOf "push_actor_resolved_outcome_command_ref" (terminalFlowIdentityRefText prepared.envelope.terminalReceiptRef))
                  stageToken = None }
            | TerminalFlowPushOutcomeFilled filled ->
                { eventCode = 2uy
                  kind = TerminalFlowSchedulerChannelOutcomeFilled
                  actorCommand = actor "scheduler-command-fill" (terminalFlowMintedRefOf "push_actor_fill_command_ref" filled.fillReceipt.receiptId)
                  stageToken = stage (terminalFlowMintedRefOf "terminal_stage_token_ref" filled.sealedToken.tokenId) }
            | TerminalFlowPushWriterCapabilityBound bound ->
                { eventCode = 3uy
                  kind = TerminalFlowSchedulerChannelWriterBound
                  actorCommand = actor "scheduler-command-writer-bound" (terminalFlowMintedRefOf "push_actor_writer_command_ref" bound.writer.writerLeaseId)
                  stageToken = stage (terminalFlowMintedRefOf "terminal_stage_token_ref" bound.filled.sealedToken.tokenId) }
            | TerminalFlowPushArtifactCommitRequested bound ->
                { eventCode = 4uy
                  kind = TerminalFlowSchedulerChannelArtifactCommitRequested
                  actorCommand = actor "scheduler-command-artifact-commit" (terminalFlowMintedRefOf "push_actor_writer_command_ref" bound.writer.writerLeaseId)
                  stageToken = stage (terminalFlowMintedRefOf "terminal_stage_token_ref" bound.filled.sealedToken.tokenId) }
            | TerminalFlowPushWriterCompleted completed ->
                { eventCode = 5uy
                  kind = TerminalFlowSchedulerChannelWorkerCompleted
                  actorCommand = actor "scheduler-command-worker-completed" (terminalFlowMintedRefOf "push_actor_writer_completed_command_ref" completed.writerReceipt.writerJobId)
                  stageToken = stage (terminalFlowMintedRefOf "terminal_stage_token_ref" completed.consumedToken.tokenId) }
            | TerminalFlowPushRegistryPrune(fillKey, completed) ->
                { eventCode = 6uy
                  kind = TerminalFlowSchedulerChannelWakerConsumedAndRegistryPruned
                  actorCommand = actor "scheduler-command-registry-prune" (terminalFlowMintedRefOf "push_actor_registry_prune_command_ref" (TerminalFlowFillKeyId.text fillKey))
                  stageToken = stage (terminalFlowMintedRefOf "terminal_stage_token_ref" completed.consumedToken.tokenId) }
            | TerminalFlowPushFailClosed(_, reason) ->
                { eventCode = 7uy
                  kind = TerminalFlowSchedulerChannelFailedClosed
                  actorCommand = actor "scheduler-command-fail-closed" (terminalFlowMintedRefOf "push_actor_fail_closed_command_ref" (CompilerKernelV2.OperationalReasonIdOps.text reason))
                  stageToken = None }


        let private terminalFlowSchedulerChannelAuthorityFor
            (channelAuthority:TerminalFlowSchedulerChannelRootAuthority<TerminalFlowSchedulerChannelSealedStage>)
            (event:TerminalFlowSchedulerPushEventId)
            : TerminalFlowSchedulerChannelAuthorityReceipt * TerminalFlowSchedulerWakerRegistrationReceipt =
            let context = channelAuthority.context
            let command = terminalFlowSchedulerChannelCommandShapeFor event
            let wakerRegistration =
                match event with
                | TerminalFlowPushRegistryPrune _ -> terminalFlowSchedulerWakerConsume context
                | _ -> channelAuthority.ledger.wakerRegistration
            let workerHandoff =
                match event with
                | TerminalFlowPushWriterCompleted completed
                | TerminalFlowPushRegistryPrune(_, completed) -> Some (terminalFlowSchedulerWorkerHandoffFor context completed)
                | _ -> channelAuthority.ledger.workerHandoff
            let actorCommand = command.actorCommand
            let stageToken = command.stageToken
            let kind = command.kind
            let payload : TerminalFlowSchedulerAuthorityPayload =
                { kind = kind
                  context = context
                  actorCommand = actorCommand
                  stageToken = stageToken
                  wakerRegistration = wakerRegistration
                  workerHandoff = workerHandoff }
            let currentAuthority =
                match channelAuthority.possession with
                | TerminalFlowPushPossessionGenesis receipt
                | TerminalFlowPushPossessionStep(receipt, _) -> receipt
            let payloadText =
                String.concat "|"
                    [ terminalFlowSchedulerChannelStepKindText kind
                      CompilerIdentityKernel.ContentDigest.text context.contextDigest
                      CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest actorCommand)
                      CompilerIdentityKernel.ContentDigest.text wakerRegistration.exactOnceDigest
                      (workerHandoff |> Option.map (fun receipt -> CompilerIdentityKernel.ContentDigest.text receipt.exactOnceDigest) |> Option.defaultValue "no-worker") ]
            let typedReceipt : TerminalFlowSchedulerReceipt<TerminalFlowSchedulerAuthorityReceiptKind,TerminalFlowSchedulerReceiptSealedStage,TerminalFlowSchedulerAuthorityPayload> =
                terminalFlowSchedulerReceiptCreateSuccessor
                    "scheduler-channel-authority"
                    payloadText
                    currentAuthority.exactOnceDigest
                    payload
            { receipt = typedReceipt }, wakerRegistration

        let private terminalFlowSchedulerChannelGenesisAuthority
            (context:TerminalFlowSchedulerChannelAdmissionContext)
            (wakerRegistration:TerminalFlowSchedulerWakerRegistrationReceipt)
            (armReceiptRef:uint32)
            : TerminalFlowSchedulerChannelAuthorityReceipt =
            let actorCommand : TerminalFlowSchedulerWitness<TerminalFlowSchedulerActorCommandWitnessKind> =
                terminalFlowSchedulerWitnessFor "scheduler-actor-command" armReceiptRef
            let payload : TerminalFlowSchedulerAuthorityPayload =
                { kind = TerminalFlowSchedulerChannelAdmissionAccepted
                  context = context
                  actorCommand = actorCommand
                  stageToken = Some context.stageToken
                  wakerRegistration = wakerRegistration
                  workerHandoff = None }
            let payloadText =
                String.concat "|"
                    [ "AdmissionAccepted"
                      CompilerIdentityKernel.ContentDigest.text context.contextDigest
                      CompilerIdentityKernel.ContentDigest.text (terminalFlowSchedulerWitnessDigest actorCommand)
                      CompilerIdentityKernel.ContentDigest.text wakerRegistration.exactOnceDigest ]
            let typedReceipt : TerminalFlowSchedulerReceipt<TerminalFlowSchedulerAuthorityReceiptKind,TerminalFlowSchedulerReceiptSealedStage,TerminalFlowSchedulerAuthorityPayload> =
                terminalFlowSchedulerReceiptCreateSuccessor
                    "scheduler-channel-genesis"
                    payloadText
                    context.contextDigest
                    payload
            { receipt = typedReceipt }

        let rec private terminalFlowPushPossessionDepth = function
            | TerminalFlowPushPossessionGenesis _ -> 1
            | TerminalFlowPushPossessionStep(_, previous) -> 1 + terminalFlowPushPossessionDepth previous

        let rec private terminalFlowPushPossessionDigest = function
            | TerminalFlowPushPossessionGenesis receipt ->
                NativeCutoverStableRef.ref32
                    "scheduler-push-possession-genesis"
                    [ terminalFlowSchedulerChannelStepKindText receipt.kind
                      CompilerIdentityKernel.ContentDigest.text receipt.context.contextDigest
                      CompilerIdentityKernel.ContentDigest.text receipt.exactOnceDigest ]
            | TerminalFlowPushPossessionStep(receipt, previous) ->
                NativeCutoverStableRef.ref32
                    "scheduler-push-possession-step"
                    [ terminalFlowSchedulerChannelStepKindText receipt.kind
                      CompilerIdentityKernel.ContentDigest.text receipt.context.contextDigest
                      CompilerIdentityKernel.ContentDigest.text receipt.exactOnceDigest
                      string (terminalFlowPushPossessionDigest previous) ]

        let private terminalFlowPushPossessionHead = function
            | TerminalFlowPushPossessionGenesis receipt
            | TerminalFlowPushPossessionStep(receipt, _) -> receipt

        let private terminalFlowSchedulerChannelTransitionAllowed currentKind nextKind =
            match currentKind, nextKind with
            | TerminalFlowSchedulerChannelAdmissionAccepted, TerminalFlowSchedulerChannelOutcomeFilled
            | TerminalFlowSchedulerChannelOutcomeFilled, TerminalFlowSchedulerChannelWriterBound
            | TerminalFlowSchedulerChannelWriterBound, TerminalFlowSchedulerChannelArtifactCommitRequested
            | TerminalFlowSchedulerChannelArtifactCommitRequested, TerminalFlowSchedulerChannelWorkerCompleted
            | TerminalFlowSchedulerChannelWorkerCompleted, TerminalFlowSchedulerChannelWakerConsumedAndRegistryPruned -> true
            | _, TerminalFlowSchedulerChannelFailedClosed -> true
            | _ -> false


        let private terminalFlowSchedulerChannelRootAuthorityFor
            (context:TerminalFlowSchedulerChannelAdmissionContext)
            (wakerRegistration:TerminalFlowSchedulerWakerRegistrationReceipt)
            (possession:TerminalFlowSchedulerPushPossessionSpine)
            : TerminalFlowSchedulerChannelRootAuthority<TerminalFlowSchedulerChannelSealedStage> =
            let ledger = terminalFlowSchedulerChannelLedgerEntryFor context
            let head = terminalFlowPushPossessionHead possession
            if ledger.admission.contextDigest <> context.contextDigest then
                invalidOp "scheduler channel root ledger belongs to another admission receipt"
            if ledger.wakerRegistration.exactOnceDigest <> wakerRegistration.exactOnceDigest then
                invalidOp "scheduler channel root waker receipt diverged from ledger"
            if head.context.contextDigest <> context.contextDigest then
                invalidOp "scheduler channel root head belongs to another admission receipt"
            if head.wakerRegistration.exactOnceDigest <> wakerRegistration.exactOnceDigest then
                invalidOp "scheduler channel root head owns a different waker receipt"
            let rootDigest =
                CompilerIdentityKernel.ContentDigest.ofText
                    "scheduler-channel-root"
                    (String.concat "|"
                        [ CompilerIdentityKernel.ContentDigest.text context.contextDigest
                          CompilerIdentityKernel.ContentDigest.text ledger.exactOnce
                          CompilerIdentityKernel.ContentDigest.text head.exactOnceDigest
                          CompilerIdentityKernel.ContentDigest.text wakerRegistration.exactOnceDigest ])
            { context = context
              ledger = ledger
              possession = possession
              rootDigest = rootDigest }

        let private terminalFlowSchedulerChannelRootAdvance
            (root:TerminalFlowSchedulerChannelRootAuthority<TerminalFlowSchedulerChannelSealedStage>)
            (event:TerminalFlowSchedulerPushEventId)
            : TerminalFlowSchedulerChannelRootAuthority<TerminalFlowSchedulerChannelSealedStage> * TerminalFlowSchedulerChannelAuthorityReceipt * TerminalFlowSchedulerWakerRegistrationReceipt =
            let nextAuthority, nextWakerRegistration = terminalFlowSchedulerChannelAuthorityFor root event
            let nextLedger = terminalFlowSchedulerChannelLedgerAdvance root.context nextAuthority
            if nextLedger.wakerRegistration.exactOnceDigest <> nextWakerRegistration.exactOnceDigest then
                invalidOp "scheduler channel root advance diverged from typed waker receipt"
            match nextLedger.workerHandoff, nextAuthority.workerHandoff with
            | Some ledgerWorker, Some authorityWorker when ledgerWorker.exactOnceDigest <> authorityWorker.exactOnceDigest ->
                invalidOp "scheduler channel root advance diverged from typed worker receipt"
            | None, Some _ -> invalidOp "scheduler channel root authority introduced a worker receipt outside the ledger"
            | _ -> ()
            let currentAuthority = terminalFlowPushPossessionHead root.possession
            if currentAuthority.context.contextDigest <> nextAuthority.context.contextDigest then
                invalidOp "scheduler channel root admission receipt changed across a message boundary"
            if not (terminalFlowSchedulerChannelTransitionAllowed currentAuthority.kind nextAuthority.kind) then
                invalidOp
                    (sprintf
                        "scheduler channel transition rejected: %s -> %s"
                        (terminalFlowSchedulerChannelStepKindText currentAuthority.kind)
                        (terminalFlowSchedulerChannelStepKindText nextAuthority.kind))
            terminalFlowEmitAdvancedConsoleProjection {
                lane = TerminalFlowConsoleLaneSchedulerChannel
                sequence = nextLedger.possessionRevision
                progressBp = 0
                etaMs = None
                title = "scheduler channel authority advanced"
                detail =
                    FastRuntimeFormat.format "kind=%s|context=%u|waker=%u|worker=%u|actor_command=%u|stage=%u|ledger_exact=%u" [| box (terminalFlowSchedulerChannelStepKindText nextAuthority.kind); box nextAuthority.contextRef; box nextAuthority.wakerRegistryRef; box nextAuthority.workerHandoffRef; box nextAuthority.actorCommandRef; box nextAuthority.stageTokenRef; box nextLedger.exactOnceRef |]
                authorityRef = nextAuthority.exactOnceRef
            }
            let nextPossession = TerminalFlowPushPossessionStep(nextAuthority, root.possession)
            let nextRootDigest =
                CompilerIdentityKernel.ContentDigest.ofText
                    "scheduler-channel-root-advance"
                    (String.concat "|"
                        [ CompilerIdentityKernel.ContentDigest.text root.rootDigest
                          CompilerIdentityKernel.ContentDigest.text nextAuthority.exactOnceDigest
                          CompilerIdentityKernel.ContentDigest.text nextLedger.exactOnce
                          string (terminalFlowPushPossessionDigest nextPossession) ])
            let nextRoot : TerminalFlowSchedulerChannelRootAuthority<TerminalFlowSchedulerChannelSealedStage> =
                { context = root.context
                  ledger = nextLedger
                  possession = nextPossession
                  rootDigest = nextRootDigest }
            nextRoot, nextAuthority, nextWakerRegistration

        let private terminalFlowSchedulerPushExitCode writerReceipt =
            match writerReceipt.artifactReceipt.execution, writerReceipt.physicalBoundary with
            | TerminalFlowArtifactsExecuted(_, committedHash, intents),
              TerminalFlowPhysicalBoundaryOwnedByWriterReceipt(writerJobId, boundaryHash)
                when not (List.isEmpty intents)
                     && committedHash = boundaryHash
                     && writerJobId = writerReceipt.writerJobId -> 0
            | _ -> 1

        let private terminalFlowSchedulerPushPhysicalExitLine (dispatch: TerminalFlowSchedulerPushDispatch) (completed: TerminalFlowCommitCompleted) =
            let writer = completed.bound.writer
            let fillReceipt = completed.bound.filled.fillReceipt
            let writerReceipt = completed.writerReceipt
            let envelope = completed.bound.filled.prepared.envelope
            let channelLedger = terminalFlowSchedulerChannelLedgerEntryFor dispatch.channelAuthority.context
            let workerHandoffRef = channelLedger.workerHandoff |> Option.map (fun receipt -> receipt.workerHandoffRef) |> Option.defaultValue 0u
            let wakerConsumed = channelLedger.wakerRegistration.state = TerminalFlowSchedulerWakerConsumed
            let committedArtifactSetHash =
                match writerReceipt.artifactReceipt.execution with
                | TerminalFlowArtifactsExecuted(_, artifactSetHash, _) -> artifactSetHash
                | TerminalFlowArtifactsTerminalFailureProjected(_, failureManifestRef, _, _, _) -> terminalFlowIdentityRefText failureManifestRef
                | TerminalFlowArtifactsExecutionRejected _ -> ""
            let flags =
                (match writerReceipt.artifactReceipt.authorization with
                 | TerminalFlowArtifactsAuthorizedByNativeRootComplete _
                 | TerminalFlowArtifactsAuthorizedByTerminalFailure _ -> 1
                 | TerminalFlowArtifactsRejectedByNativeRootComplete _ -> 0)
                ||| (match writerReceipt.registryLifecycle with
                     | TerminalFlowRegistryPruneRequired _ -> 2
                     | TerminalFlowRegistryPruned _ -> 0)
                ||| (match writerReceipt.physicalBoundary with
                     | TerminalFlowPhysicalBoundaryOwnedByWriterReceipt _ -> 4
                     | TerminalFlowPhysicalBoundaryRejected _ -> 0)
            FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_exit\",\"event_code\":6,\"dispatch_ref\":%u,\"admission_ref\":%u,\"admission_identity_ref\":%u,\"actor_binding_ref\":%u,\"credential_ledger_ref\":%u,\"fairness_epoch_ref\":%u,\"scheduler_release_ref\":%u,\"waker_registry_ref\":%u,\"waker_consumed\":%b,\"worker_handoff_ref\":%u,\"channel_revision\":%d,\"channel_exact_once_ref\":%u,\"possession_depth\":%d,\"possession_ref\":%u,\"fill_ref\":%u,\"cell_ref\":%u,\"writer_ref\":%u,\"artifact_plan_ref\":%u,\"artifact_stage_ref\":%u,\"artifact_set_ref\":%u,\"lease_ref\":%u,\"receipt_ref\":%u,\"transaction_ref\":%u,\"token_ref\":%u,\"exit_witness_ref\":%u,\"open_after\":%d,\"flags\":%d,\"stage_authority\":\"typed_kernel_stage_capability\"}" [| box (NativeCutoverStableRef.ref32 "terminal-dispatch" [dispatch.dispatchId]); box dispatch.channelAuthority.context.admissionRef; box dispatch.channelAuthority.context.admissionIdentityRef; box dispatch.channelAuthority.context.actorBindingRef; box dispatch.channelAuthority.context.credentialLedgerRef; box dispatch.channelAuthority.context.fairnessEpochRef; box (terminalFlowIdentityRefDigest dispatch.channelAuthority.context.schedulerRelease.physicalReleaseRef); box channelLedger.wakerRegistration.registryRef; box wakerConsumed; box workerHandoffRef; box channelLedger.possessionRevision; box channelLedger.exactOnceRef; box (terminalFlowPushPossessionDepth dispatch.channelAuthority.possession); box (terminalFlowPushPossessionDigest dispatch.channelAuthority.possession); box (NativeCutoverStableRef.ref32 "terminal-envelope-fill" [TerminalFlowFillKeyId.text envelope.fillKey]); box (NativeCutoverStableRef.ref32 "terminal-fill-cell" [fillReceipt.cellId]); box (NativeCutoverStableRef.ref32 "terminal-writer-job" [writerReceipt.writerJobId]); box (NativeCutoverStableRef.ref32 "artifact-plan" [writer.artifactPlan.planId]); box (terminalFlowStageRef writerReceipt.artifactCommittedStage); box (NativeCutoverStableRef.ref32 "terminal-artifact-set" [committedArtifactSetHash]); box (NativeCutoverStableRef.ref32 "terminal-writer-lease" [writer.writerLeaseId]); box (NativeCutoverStableRef.ref32 "terminal-writer-receipt" [terminalFlowWriterTerminalReceiptText writer]); box (NativeCutoverStableRef.ref32 "terminal-owner-transaction" [writer.ownerTransactionId]); box (NativeCutoverStableRef.ref32 "terminal-consumed-token" [completed.consumedToken.tokenId]); box (NativeCutoverStableRef.ref32 "terminal-exit-witness" [completed.exitWitness.witnessId]); box writerReceipt.ownerLedgerOpenAfter; box flags |]

        // Destructive domain migration round : process-global TerminalFlow reducer.
        // Root, outcome, actor and exit receipts are the only progression inputs.
        // The timer below is a fail-closed deadman and owns no reconciliation.
        // HUD/metronome are projections and cannot cross the physical boundary.
        let private terminalFlowGlobalServerDeadmanAfterMs = 30000L

        type TerminalFlowDeadmanObservation =
            | TerminalFlowDeadmanAwaitingRoot
            | TerminalFlowDeadmanActorTerminal
            | TerminalFlowDeadmanWatching of livenessAgeMs:int64 * materialAgeMs:int64
            | TerminalFlowDeadmanExpired of livenessAgeMs:int64 * materialAgeMs:int64

        let mutable private terminalFlowDeadmanOutstandingGraphProbe : (unit -> int * int * int) =
            fun () -> 0, 0, 0

        let terminalFlowInstallDeadmanOutstandingGraphProbe probe =
            terminalFlowDeadmanOutstandingGraphProbe <- probe

        type TerminalFlowDeadmanLiveSnapshot = private {
            requestedMaterialAgeMs : int64
            pendingDepth : int
            queueDepth : int
            activeDepth : int
            promisePendingDepth : int
            worklistRegisteredDepth : int
            worklistRunningDepth : int
            qapWatchPresent : bool
            durableRunEndCommitted : bool
        }

        type TerminalFlowDeadmanSuppressionReasonId =
            | TerminalFlowDeadmanSuppressedByDurableRunEnd
            | TerminalFlowDeadmanSuppressedByQapWatch
            | TerminalFlowDeadmanSuppressedByLiveWork
            | TerminalFlowDeadmanSuppressedByOutstandingPromiseGraph

        type TerminalFlowDeadmanAuthorizationReasonId =
            | TerminalFlowDeadmanAuthorizedByEmptyTopology
            | TerminalFlowDeadmanAuthorizedByOutstandingGraphGraceExhausted

        type TerminalFlowDeadmanFailClosedRevalidationId =
            | TerminalFlowDeadmanFailClosedAuthorized of TerminalFlowDeadmanAuthorizationReasonId * TerminalFlowDeadmanLiveSnapshot
            | TerminalFlowDeadmanFailClosedSuppressed of TerminalFlowDeadmanSuppressionReasonId * TerminalFlowDeadmanLiveSnapshot

        // Success dispatch owns a bounded terminal tail. Once the recursive dispatch
        // proof is sealed and the reducer exposes DispatchReady, a Noop actor is a
        // temporary state only. The QAP watch is observer evidence at this point and
        // cannot keep an otherwise empty process alive forever.
        type TerminalFlowPostQuiescenceDispatchDeadmanDecision =
            | TerminalFlowPostQuiescenceDispatchDeadmanInactive
            | TerminalFlowPostQuiescenceDispatchDeadmanGrace of pendingRef:uint32 * ageMs:int64
            | TerminalFlowPostQuiescenceDispatchDeadmanExpired of pendingRef:uint32 * ageMs:int64

        let private terminalFlowPostQuiescenceDispatchDeadmanDecisionFor nowMs (state:TerminalFlowGlobalReducerState) =
            match state.pendingTerminal, state.kernel.actor, state.dispatchAdmission, state.qapOutcomeActorAuthority.handoff with
            | TerminalFlowPendingSlotCandidate pending,
              KernelActorNoop,
              TerminalFlowDispatchAdmissionSealed admission,
              TerminalFlowFinalOutcomeHandoffDispatchReady(_, terminalRef, fillRef, _)
                when pending.intent = TerminalFlowPendingBuildOk
                     && terminalFlowPendingOutcomeIsFinal pending.intent
                     && terminalFlowPendingDispatchIsExecutable pending.dispatchAuthority
                     && admission.finalOutcome.intent = pending.intent
                     && terminalFlowAdmissionIdentitySame admission.identity pending.admissionIdentity
                     && admission.terminalReceiptRef = pending.terminalReceiptRef
                     && admission.fillKey = pending.fillKeyId
                     && terminalRef = terminalFlowIdentityRefDigest pending.terminalReceiptRef
                     && fillRef = terminalFlowIdentityRefDigest pending.fillRef ->
                let pendingRef = terminalFlowPendingTerminalRef pending
                let ageMs = max 0L (nowMs - admission.mintedAtMs)
                if ageMs >= terminalFlowGlobalServerDeadmanAfterMs then
                    TerminalFlowPostQuiescenceDispatchDeadmanExpired(pendingRef, ageMs)
                else
                    TerminalFlowPostQuiescenceDispatchDeadmanGrace(pendingRef, ageMs)
            | _ -> TerminalFlowPostQuiescenceDispatchDeadmanInactive

        let private terminalFlowDeadmanOutstandingGraphGraceMs = 90000L

        let private terminalFlowDeadmanAuthorizationReasonText = function
            | TerminalFlowDeadmanAuthorizedByEmptyTopology -> "EmptyLiveTopology"
            | TerminalFlowDeadmanAuthorizedByOutstandingGraphGraceExhausted -> "OutstandingGraphGraceExhausted"

        let private terminalFlowDeadmanSuppressionReasonText = function
            | TerminalFlowDeadmanSuppressedByDurableRunEnd -> "DurableRunEndCommitted"
            | TerminalFlowDeadmanSuppressedByQapWatch -> "QapMaturityWatchPresent"
            | TerminalFlowDeadmanSuppressedByLiveWork -> "LiveEvaluatorWorkPresent"
            | TerminalFlowDeadmanSuppressedByOutstandingPromiseGraph -> "OutstandingPromiseOrWorklistGraphPresent"

        let private terminalFlowDeadmanFailClosedRevalidationFor requestedMaterialAgeMs (state:TerminalFlowGlobalReducerState) =
            let promisePendingDepth, worklistRegisteredDepth, worklistRunningDepth =
                terminalFlowDeadmanOutstandingGraphProbe()
            let postQuiescenceDispatchDeadman =
                terminalFlowPostQuiescenceDispatchDeadmanDecisionFor Environment.TickCount64 state
            let qapWatchStillOwnsDeadmanSuppression =
                match postQuiescenceDispatchDeadman with
                | TerminalFlowPostQuiescenceDispatchDeadmanExpired _ -> false
                | TerminalFlowPostQuiescenceDispatchDeadmanInactive
                | TerminalFlowPostQuiescenceDispatchDeadmanGrace _ -> true
            let snapshot =
                { requestedMaterialAgeMs = requestedMaterialAgeMs
                  pendingDepth = EvalWorklist.pendingCount()
                  queueDepth = EvalWorklist.replayQueueDepth()
                  activeDepth = EvalWorklist.replayDriverActiveDepthValue()
                  promisePendingDepth = promisePendingDepth
                  worklistRegisteredDepth = worklistRegisteredDepth
                  worklistRunningDepth = worklistRunningDepth
                  qapWatchPresent = state.qapMaturityWatch.IsSome
                  durableRunEndCommitted = DiagJson.terminalFlowRunEndEmittedNow() }
            if snapshot.durableRunEndCommitted then
                TerminalFlowDeadmanFailClosedSuppressed(TerminalFlowDeadmanSuppressedByDurableRunEnd, snapshot)
            elif snapshot.qapWatchPresent && qapWatchStillOwnsDeadmanSuppression then
                TerminalFlowDeadmanFailClosedSuppressed(TerminalFlowDeadmanSuppressedByQapWatch, snapshot)
            elif snapshot.pendingDepth > 0 || snapshot.queueDepth > 0 || snapshot.activeDepth > 0 then
                TerminalFlowDeadmanFailClosedSuppressed(TerminalFlowDeadmanSuppressedByLiveWork, snapshot)
            elif snapshot.promisePendingDepth > 0 || snapshot.worklistRegisteredDepth > 0 || snapshot.worklistRunningDepth > 0 then
                if snapshot.requestedMaterialAgeMs < terminalFlowDeadmanOutstandingGraphGraceMs then
                    TerminalFlowDeadmanFailClosedSuppressed(TerminalFlowDeadmanSuppressedByOutstandingPromiseGraph, snapshot)
                else
                    TerminalFlowDeadmanFailClosedAuthorized(TerminalFlowDeadmanAuthorizedByOutstandingGraphGraceExhausted, snapshot)
            else
                TerminalFlowDeadmanFailClosedAuthorized(TerminalFlowDeadmanAuthorizedByEmptyTopology, snapshot)

        type TerminalFlowResidualStallEscalationId =
            | TerminalFlowResidualStallObserve
            | TerminalFlowResidualStallObserveExtended of materialAgeMs:int64

        let private terminalFlowResidualStallEscalationFor qapWatchPresent materialAgeMs =
            if qapWatchPresent && materialAgeMs >= 60000L then
                TerminalFlowResidualStallObserveExtended materialAgeMs
            else
                TerminalFlowResidualStallObserve

        let private terminalFlowResidualStallEscalationText = function
            | TerminalFlowResidualStallObserve -> "TerminalFlowResidualStallEscalation(Observe)"
            | TerminalFlowResidualStallObserveExtended materialAgeMs ->
                sprintf "TerminalFlowResidualStallEscalation(ObserveExtended|material_age_ms=%d)" materialAgeMs

        let private terminalFlowMaterialDeadmanAgeMs nowMs fallbackLivenessAgeMs =
            let ledgerAgeMs = DiagJson.ownerDebtLiveWorkTieBreakerMaterialDeltaAgeMsNow()
            if ledgerAgeMs = Int64.MaxValue then
                // Unknown material clock must be visible and conservative.  It may
                // seed the first observation with fallback liveness, but subsequent
                // heartbeats cannot reset it because the fallback is recomputed from
                // root/actor causality, not from log emission.
                max 0L fallbackLivenessAgeMs
            else
                max 0L ledgerAgeMs

        let private terminalFlowDeadmanObservationFor nowMs (state:TerminalFlowGlobalReducerState) =
            let classify livenessAgeMs =
                let materialAgeMs = terminalFlowMaterialDeadmanAgeMs nowMs livenessAgeMs
                if materialAgeMs >= terminalFlowGlobalServerDeadmanAfterMs then
                    TerminalFlowDeadmanExpired(livenessAgeMs, materialAgeMs)
                else
                    TerminalFlowDeadmanWatching(livenessAgeMs, materialAgeMs)
            match state.kernel.root, state.kernel.outcome, state.pendingTerminal, state.kernel.actor with
            | KernelRootAwaitingEvaluator, _, _, _ -> TerminalFlowDeadmanAwaitingRoot
            | KernelRootResolved(_, _, _), _, _, KernelActorArmed(DiagJson.PushActorConsumed, _, _)
            | KernelRootResolved(_, _, _), _, _, KernelActorArmed(DiagJson.PushActorFailedClosed, _, _) ->
                TerminalFlowDeadmanActorTerminal
            | KernelRootResolved(_, resolvedAtMs, _), _, _, KernelActorArmed(_, _, changedAtMs) ->
                // An armed actor is already a terminal continuation.  It must not be
                // hidden by the broader KernelOutcomeOpen case: that shadowing let a
                // blocked QAP actor livelock forever while material age exceeded 9 min.
                classify (max 0L (nowMs - max resolvedAtMs changedAtMs))
            | KernelRootResolved _, KernelOutcomeOpen, TerminalFlowPendingSlotAwaitingCandidate, KernelActorNoop ->
                // A root without an actor or pending terminal remains ordinary evaluator
                // progress and cannot be killed by the terminal deadman.
                TerminalFlowDeadmanWatching(0L, 0L)
            | KernelRootResolved(_, resolvedAtMs, _), _, _, KernelActorNoop ->
                classify (max 0L (nowMs - resolvedAtMs))

