            | TerminalFlowCandidatePhysicalExitIntentDurable
            | TerminalFlowCandidateReceiptChainInconsistent of commitDurable:bool * doneDurable:bool * runEndDurable:bool * physicalExitIntentRecorded:bool

        let private terminalFlowExecutableCandidateReceiptChainFor commitDurable doneDurable runEndDurable physicalExitIntentRecorded =
            match commitDurable, doneDurable, runEndDurable, physicalExitIntentRecorded with
            | false, false, false, false -> TerminalFlowCandidateAwaitCommit
            | true, false, false, false -> TerminalFlowCandidateAwaitDone
            | true, true, false, false -> TerminalFlowCandidateAwaitRunEnd
            | true, true, true, false -> TerminalFlowCandidateAwaitPhysicalExitIntent
            | true, true, true, true -> TerminalFlowCandidatePhysicalExitIntentDurable
            | commitDurable, doneDurable, runEndDurable, physicalExitIntentRecorded ->
                TerminalFlowCandidateReceiptChainInconsistent(commitDurable, doneDurable, runEndDurable, physicalExitIntentRecorded)

        let private terminalFlowExecutableCandidateReceiptChainText = function
            | TerminalFlowCandidateAwaitCommit -> "AwaitCommit"
            | TerminalFlowCandidateAwaitDone -> "AwaitDone"
            | TerminalFlowCandidateAwaitRunEnd -> "AwaitRunEnd"
            | TerminalFlowCandidateAwaitPhysicalExitIntent -> "AwaitPhysicalExitIntent"
            | TerminalFlowCandidatePhysicalExitIntentDurable -> "PhysicalExitIntentDurable"
            | TerminalFlowCandidateReceiptChainInconsistent(commitDurable, doneDurable, runEndDurable, physicalExitIntentRecorded) ->
                FastRuntimeFormat.format "Inconsistent(commit=%b|done=%b|run_end=%b|physical_intent=%b)" [| box commitDurable; box doneDurable; box runEndDurable; box physicalExitIntentRecorded |]

