        let private terminalFlowGlobalServerCounterAdvance kind =
            lock terminalFlowGlobalServerCounterGate (fun () ->
                let next =
                    match kind with
                    | TerminalFlowGlobalServerCounterPublished -> { terminalFlowGlobalServerCounterState with published = terminalFlowGlobalServerCounterState.published + 1L }
                    | TerminalFlowGlobalServerCounterConsumed -> { terminalFlowGlobalServerCounterState with consumed = terminalFlowGlobalServerCounterState.consumed + 1L }
                    | TerminalFlowGlobalServerCounterExecuted -> { terminalFlowGlobalServerCounterState with executed = terminalFlowGlobalServerCounterState.executed + 1L }
                terminalFlowGlobalServerCounterState <- next
                match kind with
                | TerminalFlowGlobalServerCounterPublished -> next.published
                | TerminalFlowGlobalServerCounterConsumed -> next.consumed
                | TerminalFlowGlobalServerCounterExecuted -> next.executed)

