        let private terminalFlowLiveProgressEvidenceGate = obj()
        let mutable private terminalFlowLiveProgressEvidence :
            (TerminalFlowLiveProgressEvidenceSource * TerminalFlowProgressEvidence) option = None

        let private terminalFlowLiveProgressEvidenceObserve source evidence =
            lock terminalFlowLiveProgressEvidenceGate (fun () ->
                match terminalFlowLiveProgressEvidence with
                | Some(_, current) when current.snapshotSequence > evidence.snapshotSequence -> ()
                | Some(TerminalFlowLiveProgressAcceptedForControl, current)
                    when current.snapshotSequence = evidence.snapshotSequence
                         && source = TerminalFlowLiveProgressObservedProjectionOnly -> ()
                | _ ->
                    terminalFlowLiveProgressEvidence <- Some(source, evidence))

        let private terminalFlowLiveProgressEvidenceRead () =
            lock terminalFlowLiveProgressEvidenceGate (fun () -> terminalFlowLiveProgressEvidence)

        // Exit credit and work-ledger observation must not depend on QAP having emitted
        // a projection.  This snapshot is reconstructed from the live scheduler ledgers
        // and JP lane authorities.  Unknown semantic queue classification remains
        // explicitly unattributed until that queue reaches zero, so this path cannot
        // manufacture closed-world authority from a missing projection.
        let private terminalFlowOperationalProgressEvidenceNow () =
            let nowMs = Environment.TickCount64
            let laneSnapshot = terminalFlowJpLaneSnapshotBridge ()
            let schedulerState = SemanticWorkLedgerProjection.readOperational ()
            let schedulerAdmittedCount, _, schedulerOpenCount =
                SemanticWorkLedgerProjection.countsOf schedulerState
            let activeAuthorityCount, dependencyCount = JpActiveWorkIdentityAuthority.readCounts ()
            let semanticQueueDepth = max 0L laneSnapshot.semanticQueueDepth
            let declaredBodyQueueDepth = max 0L laneSnapshot.declaredBodyQueueDepth
            let queueDepth = semanticQueueDepth + declaredBodyQueueDepth
            let laneActiveCount = max 0L (laneSnapshot.semanticActive + laneSnapshot.declaredBodyActive)
            let activeWorkers = max laneActiveCount (max 0L activeAuthorityCount)
            let completedCost = max 0L (DiagJson.terminalCompletionCreditCostNow())
            // Queue and lane ownership locate already-admitted scheduler credit; they do
            // not mint extra semantic work.  Counting queueDepth+activeWorkers as new
            // cost made retired lane wrappers inflate the operational frontier after the
            // semantic graph itself was closed.
            let openCost = max 0L schedulerOpenCount
            let discoveredCost = completedCost + openCost
            let blockedCost = min openCost (max 0L dependencyCount)
            let rootSnapshot = DiagJson.canonicalRootAuthoritySnapshot ()
            let rootReceipt = rootSnapshot.receiptId
            let semanticEpoch = DiagJson.terminalSemanticAuthorityCountNow()
            let semanticReceiptCount = max 0L semanticEpoch
            let canonicalRootCount = if String.IsNullOrWhiteSpace rootReceipt then 0L else 1L
            let snapshotRef : TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind> =
                terminalFlowIdentityRefOfText (
                    FastRuntimeFormat.format
                        "operational-progress:%d:%d:%d:%d:%d:%d"
                        [| box completedCost; box schedulerAdmittedCount; box schedulerOpenCount; box queueDepth; box activeWorkers; box dependencyCount |])
            let semanticDigestRef : TerminalFlowIdentityRef<TerminalFlowSemanticFrontierDigestRefKind> =
                terminalFlowIdentityRefOfText (
                    FastRuntimeFormat.format
                        "operational-semantic-frontier:%s:%d:%d"
                        [| box rootReceipt; box semanticEpoch; box canonicalRootCount |])
            let proceduralDigestRef : TerminalFlowIdentityRef<TerminalFlowProceduralFrontierDigestRefKind> =
                terminalFlowIdentityRefOfText (
                    FastRuntimeFormat.format
                        "operational-procedural-frontier:%d:%d:%d:%d"
                        [| box semanticQueueDepth; box declaredBodyQueueDepth; box activeWorkers; box dependencyCount |])
            let queueKindCounts : TerminalFlowQueueKindCounts =
                { crossKindReplayDriver = 0L
                  parentContinuation = 0L
                  declaredBodyVerification = declaredBodyQueueDepth
                  universeConstraint = 0L
                  defEqObligation = 0L
                  proceduralResidual = 0L }
            { snapshotRef = snapshotRef
              snapshotSequence = nowMs
              frontier =
                { phase = if openCost = 0L then TerminalFlowProgressTerminal else TerminalFlowProgressSemantic
                  discovered = discoveredCost
                  retired = completedCost
                  blocked = blockedCost
                  queueDepth = queueDepth
                  activeWorkers = activeWorkers
                  queueKindCounts = queueKindCounts
                  attributedQueueTop = [] }
              semanticDigest =
                { digestRef = semanticDigestRef
                  semanticEpoch = semanticEpoch
                  semanticReceiptCount = semanticReceiptCount
                  canonicalRootCount = canonicalRootCount
                  inputCorpusRef =
                    terminalFlowMintedRefOf
                        "progress_input_corpus_ref"
                        (if String.IsNullOrWhiteSpace rootReceipt then "operational-no-root" else rootReceipt) }
              proceduralDigestRef = proceduralDigestRef
              queueAttributionComplete = semanticQueueDepth = 0L
              observedAtMs = nowMs }
            |> terminalFlowProgressEvidenceWithActorOwnedLedgers

