            authorityCutover = terminalFlowAuthorityCutoverInitial
            kernelProofAuthority = terminalFlowKernelProofVacuousInitial
            breakthroughSeal = TerminalFlowBreakthroughAwaiting [ TerminalFlowBreakthroughSealGreenPathMissing; TerminalFlowBreakthroughSealConvergenceNotPromotable terminalFlowBreakthroughConvergenceInitial ]
            breakthroughConvergence = terminalFlowBreakthroughConvergenceInitial
            progressAuthority = terminalFlowProgressAuthorityInitial
            authoritativeProgress = None
            criticalPathEta = None
            criticalPathEtaObservedAtMs = None
            nativeEvalAuthority = nativeCutoverReducerEvalAuthorityInitial<ProceduralResidualOwnerKind> ()
            cicKernelCounters = None
            cicKernelAuthority = nativeCutoverCicKernelAuthorityInitial
            cicOwnedActor = TerminalFlowCicActorDetached
            backendRuntimeWitness = None
            topologyGate = TerminalFlowTopologyGateClosed
            replayFairness = terminalFlowFairnessInitial
