            ownerLedgerCloseCertificate = None
            workDagTailCloseProof = None
            residualWorkDagCloseDecision = None
            terminalOrderCutover = None
            legacyTerminalAuthorityDemotions = []
            causalSpine = TerminalFlowGlobalCausalGenesis
            mutationLedger = terminalFlowReducerMutationLedgerInitial
