        }

        let mutable private terminalFlowGlobalReducerProjectionMirror = terminalFlowGlobalReducerInitialState ()

        let private terminalFlowNoWorkBuildOutcomeAuthoritySnapshot () =
            lock terminalFlowGlobalReducerProjectionGate (fun () ->
                let state = terminalFlowGlobalReducerProjectionMirror
                match state.pendingTerminal with
                | TerminalFlowPendingSlotCandidate pending
                    when pending.intent = TerminalFlowPendingBuildOk ->
                    let candidateClass = terminalFlowPendingCandidateClass pending
                    if terminalFlowPendingCandidateIsFinal candidateClass && terminalFlowPendingCandidateIsExecutable candidateClass then
                        let proof =
                            CompilerIdentityKernel.ContentDigest.ofText
                                "terminal-flow-proven-build-ok"
                                (FastRuntimeFormat.format "%u|%u|%u" [|
                                    box (terminalFlowIdentityRefDigest pending.terminalReceiptRef)
                                    box (terminalFlowIdentityRefDigest pending.fillRef)
                                    box (terminalFlowPendingDispatchAuthorityRef pending.dispatchAuthority) |])
                        DiagJson.NoWorkBuildOutcomeAuthorityProvenBuildOk proof
                    else
                        DiagJson.NoWorkBuildOutcomeAuthorityUnknown
                | TerminalFlowPendingSlotCandidate pending
                    when terminalFlowPendingOutcomeIsFinal pending.intent
                         && terminalFlowPendingDispatchIsExecutable pending.dispatchAuthority ->
                    match state.progressAuthority.accepted, state.qapPostCommit with
                    | Some evidence, TerminalFlowQapPostCommitApplied applied
                        when terminalFlowProgressEvidenceIsExactClosedWorld evidence ->
                        match applied.pendingTerminal with
                        | TerminalFlowPendingSlotCandidate appliedPending
                            when appliedPending.intent = pending.intent
                                 && appliedPending.terminalReceiptRef = pending.terminalReceiptRef
                                 && appliedPending.fillRef = pending.fillRef
                                 && terminalFlowPendingDispatchAuthoritySame appliedPending.dispatchAuthority pending.dispatchAuthority ->
                            let proof =
                                CompilerIdentityKernel.ContentDigest.ofText
                                    "terminal-flow-no-proven-build-ok"
                                    (FastRuntimeFormat.format "%u|%u|%u|%u" [|
                                        box (terminalFlowIdentityRefDigest evidence.snapshotRef)
                                        box applied.proof.proofRef
                                        box applied.exactOnceRef
                                        box (terminalFlowPendingTerminalRef pending) |])
                            DiagJson.NoWorkBuildOutcomeAuthorityNoProvenBuildOk proof
                        | _ -> DiagJson.NoWorkBuildOutcomeAuthorityUnknown
                    | _ -> DiagJson.NoWorkBuildOutcomeAuthorityUnknown
                | TerminalFlowPendingSlotCandidate _
                | TerminalFlowPendingSlotAwaitingCandidate ->
                    DiagJson.NoWorkBuildOutcomeAuthorityUnknown)

        do DiagJson.installNoWorkBuildOutcomeAuthorityProvider terminalFlowNoWorkBuildOutcomeAuthoritySnapshot

        let private terminalFlowHostLedgerHeartbeat () =
            match terminalFlowLiveProgressEvidenceRead () with
            | Some(source, evidence) ->
                terminalFlowEmitLiveWorkLedgerHeartbeat source evidence
            | None ->
                let evidence = terminalFlowOperationalProgressEvidenceNow ()
                terminalFlowLiveProgressEvidenceObserve TerminalFlowLiveProgressOperationalAuthority evidence
                terminalFlowEmitLiveWorkLedgerHeartbeat TerminalFlowLiveProgressOperationalAuthority evidence
            CompilerConsoleHud88.retryTerminalClosure ()

        do CompilerConsoleHud88.installTerminalLedgerHeartbeat terminalFlowHostLedgerHeartbeat

