        // Command admission is a closed domain value rather than a boolean guard
        // plus a free-form reason string. Actor, dispatch, possession and protocol
        // disagreements are materialized as one recursive witness consumed by the
        // single lifecycle integration point.
        type TerminalFlowLifecycleCommandKind =
            | TerminalFlowProtocolAwaitDataflowCommand
            | TerminalFlowProtocolReplayDrainCommand
            | TerminalFlowProtocolQapPostCommitCommand
            | TerminalFlowProtocolPublishDispatchCommand
            | TerminalFlowProtocolExecuteDispatchCommand
            | TerminalFlowProtocolConsumeStageTokenCommand
            | TerminalFlowProtocolAuthorizeStageTokenSealCommand
            | TerminalFlowProtocolCommitExitCommand
            | TerminalFlowProtocolFailClosedCommand

        let private terminalFlowLifecycleCommandKindText = function
            | TerminalFlowProtocolAwaitDataflowCommand -> "AwaitDataflow"
            | TerminalFlowProtocolReplayDrainCommand -> "DrainQueuedReplay"
            | TerminalFlowProtocolQapPostCommitCommand -> "RunQapPostCommit"
            | TerminalFlowProtocolPublishDispatchCommand -> "PublishDispatch"
            | TerminalFlowProtocolExecuteDispatchCommand -> "ExecuteDispatch"
            | TerminalFlowProtocolConsumeStageTokenCommand -> "ConsumeStageToken"
            | TerminalFlowProtocolAuthorizeStageTokenSealCommand -> "AuthorizeStageTokenSeal"
            | TerminalFlowProtocolCommitExitCommand -> "CommitExit"
            | TerminalFlowProtocolFailClosedCommand -> "FailClosed"

        let private terminalFlowLifecycleCommandKindFor = function
            | TerminalFlowGlobalServerAwaitDataflow _ -> TerminalFlowProtocolAwaitDataflowCommand
            | TerminalFlowGlobalServerDrainQueuedReplay _ -> TerminalFlowProtocolReplayDrainCommand
            | TerminalFlowGlobalServerRunQapPostCommitEffect _ -> TerminalFlowProtocolQapPostCommitCommand
            | TerminalFlowGlobalServerPublishDispatchRequest _ -> TerminalFlowProtocolPublishDispatchCommand
            | TerminalFlowGlobalServerExecuteDispatch _ -> TerminalFlowProtocolExecuteDispatchCommand
            | TerminalFlowGlobalServerConsumeStageToken _ -> TerminalFlowProtocolConsumeStageTokenCommand
            | TerminalFlowGlobalServerAuthorizeStageTokenSeal _ -> TerminalFlowProtocolAuthorizeStageTokenSealCommand
            | TerminalFlowGlobalServerCommitExit _ -> TerminalFlowProtocolCommitExitCommand
            | TerminalFlowGlobalServerFailClosed _ -> TerminalFlowProtocolFailClosedCommand

