            | TerminalFlowActorStateDivergent of TerminalFlowActorStateViolationPath

        type TerminalFlowActorStateWitness = private {
            scheduler : TerminalFlowSchedulerActorObservation
            dispatch : TerminalFlowKernelDispatchObservation
            possession : TerminalFlowReducerPossessionObservation
            protocol : TerminalFlowDispatchProtocolObservation
            requestRef : uint32
            requestLineageRef : uint32
            requestRootRef : uint32
            requestTerminalRef : uint32
            requestFillRef : uint32
            lifecycleRef : uint32
            lifecycleExactOnceRef : uint32
            lifecycleRevision : int64
            coherence : TerminalFlowActorStateCoherence
            violationCount : int
        }

        let rec private terminalFlowActorStateViolationPathOf = function
            | [] -> None
            | [violation] -> Some (TerminalFlowActorStateViolationLast violation)
            | violation :: rest ->
                terminalFlowActorStateViolationPathOf rest
                |> Option.map (fun tail -> TerminalFlowActorStateViolationMore(violation, tail))

