            | TerminalFlowReducerPossessionVacantObserved -> "ReducerPossession(Vacant)"
            | TerminalFlowReducerPossessionArmedObserved(actorRef, terminalRef, fillRef) -> FastRuntimeFormat.format "ReducerPossession(Armed|actor_ref=%u|terminal_ref=%u|fill_ref=%u)" [| box actorRef; box terminalRef; box fillRef |]
            | TerminalFlowReducerPossessionFilledObserved(actorRef, terminalRef, fillRef) -> FastRuntimeFormat.format "ReducerPossession(Filled|actor_ref=%u|terminal_ref=%u|fill_ref=%u)" [| box actorRef; box terminalRef; box fillRef |]
            | TerminalFlowReducerPossessionSealedObserved(actorRef, terminalRef, fillRef) -> FastRuntimeFormat.format "ReducerPossession(Sealed|actor_ref=%u|terminal_ref=%u|fill_ref=%u)" [| box actorRef; box terminalRef; box fillRef |]
            | TerminalFlowReducerPossessionFailedClosedObserved(actorRef, terminalRef, fillRef) -> FastRuntimeFormat.format "ReducerPossession(FailedClosed|actor_ref=%u|terminal_ref=%u|fill_ref=%u)" [| box actorRef; box terminalRef; box fillRef |]

        let private terminalFlowDispatchProtocolObservationText = function
            | TerminalFlowDispatchProtocolReadyObserved(constitutionRef, lineageRef, rootRef, terminalRef, fillRef) ->
                FastRuntimeFormat.format "Protocol(DispatchReady|constitution_ref=%u|lineage_ref=%u|root_ref=%u|terminal_ref=%u|fill_ref=%u)" [| box constitutionRef; box lineageRef; box rootRef; box terminalRef; box fillRef |]
            | TerminalFlowDispatchProtocolIssuedObserved(issuanceRef, constitutionRef, lineageRef, rootRef, terminalRef, fillRef) ->
                FastRuntimeFormat.format "Protocol(DispatchIssued|issuance_ref=%u|constitution_ref=%u|lineage_ref=%u|root_ref=%u|terminal_ref=%u|fill_ref=%u)" [| box issuanceRef; box constitutionRef; box lineageRef; box rootRef; box terminalRef; box fillRef |]
            | TerminalFlowDispatchProtocolNonDispatchObserved protocol ->
                "Protocol(" + terminalFlowDispatchProtocolStateText protocol + ")"

        let private terminalFlowActorStateViolationText = function
            | TerminalFlowActorSchedulerFillMismatch(expectedRef, actualRef) -> sprintf "SchedulerFillMismatch(observed=%u|request=%u)" expectedRef actualRef
            | TerminalFlowActorKernelDispatchRequestMismatch(expectedRef, actualRef) -> sprintf "KernelDispatchRequestMismatch(observed=%u|request=%u)" expectedRef actualRef
            | TerminalFlowActorKernelDispatchFillMismatch(expectedRef, actualRef) -> sprintf "KernelDispatchFillMismatch(observed=%u|request=%u)" expectedRef actualRef
            | TerminalFlowActorPossessionTerminalMismatch(expectedRef, actualRef) -> sprintf "PossessionTerminalMismatch(observed=%u|request=%u)" expectedRef actualRef
            | TerminalFlowActorPossessionFillMismatch(expectedRef, actualRef) -> sprintf "PossessionFillMismatch(observed=%u|request=%u)" expectedRef actualRef
            | TerminalFlowActorProtocolLineageMismatch(expectedRef, actualRef) -> sprintf "ProtocolLineageMismatch(observed=%u|request=%u)" expectedRef actualRef
            | TerminalFlowActorProtocolRootMismatch(expectedRef, actualRef) -> sprintf "ProtocolRootMismatch(observed=%u|request=%u)" expectedRef actualRef
            | TerminalFlowActorProtocolTerminalMismatch(expectedRef, actualRef) -> sprintf "ProtocolTerminalMismatch(observed=%u|request=%u)" expectedRef actualRef
            | TerminalFlowActorProtocolFillMismatch(expectedRef, actualRef) -> sprintf "ProtocolFillMismatch(observed=%u|request=%u)" expectedRef actualRef
            | TerminalFlowActorAcceptedWithoutPossession requestRef -> sprintf "AcceptedWithoutPossession(request_ref=%u)" requestRef
            | TerminalFlowActorAdvancedPossessionWithoutAcceptedDispatch requestRef -> sprintf "AdvancedPossessionWithoutAcceptedDispatch(request_ref=%u)" requestRef

        let rec private terminalFlowActorStateViolationPathText = function
            | TerminalFlowActorStateViolationLast violation -> terminalFlowActorStateViolationText violation
            | TerminalFlowActorStateViolationMore(violation, rest) -> terminalFlowActorStateViolationText violation + "->" + terminalFlowActorStateViolationPathText rest

        let private terminalFlowActorStateCoherenceText = function
            | TerminalFlowActorStateCoherent -> "Coherent"
            | TerminalFlowActorStateDivergent path -> "Divergent(" + terminalFlowActorStateViolationPathText path + ")"

        let private terminalFlowActorStateWitnessFor
            (state:TerminalFlowGlobalReducerState)
            (request:TerminalFlowGlobalDispatchRequest) =
            let requestRef = request.requestRef
            let requestRootRef = terminalFlowIdentityRefDigest (terminalFlowDispatchJoinRootRef request.joinKey)
            let requestTerminalRef = terminalFlowIdentityRefDigest (terminalFlowDispatchJoinTerminalRef request.joinKey)
            let requestFillRef = terminalFlowIdentityRefDigest (terminalFlowDispatchJoinFillRef request.joinKey)
            let lifecycleFrame = terminalFlowDispatchLifecycleFrame state.dispatchLifecycle
            let scheduler =
                match lifecycleFrame.kernelActor with
                | KernelActorNoop -> TerminalFlowSchedulerActorNoopObserved
                | KernelActorArmed(phase, fillKey, _) -> TerminalFlowSchedulerActorArmedObserved(phase, TerminalFlowFillKeyId.digest fillKey)
            let dispatch =
                match lifecycleFrame.kernelDispatch with
                | KernelDispatchUnavailable -> TerminalFlowKernelDispatchUnavailableObserved
                | KernelDispatchReady(identity, _, _) -> TerminalFlowKernelDispatchReadyObserved(terminalFlowDispatchRequestIdentityRef identity, terminalFlowIdentityRefDigest (terminalFlowDispatchRequestIdentityFillRef identity))
                | KernelDispatchAccepted identity -> TerminalFlowKernelDispatchAcceptedObserved(terminalFlowDispatchRequestIdentityRef identity, terminalFlowIdentityRefDigest (terminalFlowDispatchRequestIdentityFillRef identity))
            let possessionActorRef, possessionTerminalRef, possessionFillRef =
                terminalFlowReducerActorCoordinates lifecycleFrame.reducerPossession
            let possession =
                match lifecycleFrame.reducerPossession with
                | TerminalFlowReducerActorVacant _ -> TerminalFlowReducerPossessionVacantObserved
                | TerminalFlowReducerActorArmed _ -> TerminalFlowReducerPossessionArmedObserved(possessionActorRef, possessionTerminalRef, possessionFillRef)
                | TerminalFlowReducerActorFilled _ -> TerminalFlowReducerPossessionFilledObserved(possessionActorRef, possessionTerminalRef, possessionFillRef)
                | TerminalFlowReducerActorSealed _ -> TerminalFlowReducerPossessionSealedObserved(possessionActorRef, possessionTerminalRef, possessionFillRef)
                | TerminalFlowReducerActorFailedClosed _ -> TerminalFlowReducerPossessionFailedClosedObserved(possessionActorRef, possessionTerminalRef, possessionFillRef)
            let protocol =
                match lifecycleFrame.protocol with
                | TerminalFlowProtocolDispatchReady constitution ->
                    TerminalFlowDispatchProtocolReadyObserved(
                        constitution.constitutionRef,
                        terminalFlowDispatchConstitutionLineageRef constitution,
                        constitution.rootRef,
                        constitution.terminalRef,
                        constitution.fillRef)
                | TerminalFlowProtocolDispatchIssued issuance ->
                    TerminalFlowDispatchProtocolIssuedObserved(
                        issuance.issuanceRef,
                        issuance.constitution.constitutionRef,
                        terminalFlowDispatchConstitutionLineageRef issuance.constitution,
                        issuance.constitution.rootRef,
                        issuance.constitution.terminalRef,
                        issuance.constitution.fillRef)
                | observed -> TerminalFlowDispatchProtocolNonDispatchObserved observed
            let mutable violations = []
            let add violation = violations <- violation :: violations
            match scheduler with
            | TerminalFlowSchedulerActorArmedObserved(_, schedulerFillRef) when schedulerFillRef <> requestFillRef -> add (TerminalFlowActorSchedulerFillMismatch(schedulerFillRef, requestFillRef))
            | _ -> ()
            match dispatch with
            | TerminalFlowKernelDispatchReadyObserved(dispatchRequestRef, dispatchFillRef)
            | TerminalFlowKernelDispatchAcceptedObserved(dispatchRequestRef, dispatchFillRef) ->
                if dispatchRequestRef <> requestRef then add (TerminalFlowActorKernelDispatchRequestMismatch(dispatchRequestRef, requestRef))
                if dispatchFillRef <> requestFillRef then add (TerminalFlowActorKernelDispatchFillMismatch(dispatchFillRef, requestFillRef))
            | TerminalFlowKernelDispatchUnavailableObserved -> ()
            match possession with
            | TerminalFlowReducerPossessionArmedObserved(_, terminalRef, fillRef)
            | TerminalFlowReducerPossessionFilledObserved(_, terminalRef, fillRef)
            | TerminalFlowReducerPossessionSealedObserved(_, terminalRef, fillRef)
            | TerminalFlowReducerPossessionFailedClosedObserved(_, terminalRef, fillRef) ->
                if terminalRef <> requestTerminalRef then add (TerminalFlowActorPossessionTerminalMismatch(terminalRef, requestTerminalRef))
                if fillRef <> requestFillRef then add (TerminalFlowActorPossessionFillMismatch(fillRef, requestFillRef))
            | TerminalFlowReducerPossessionVacantObserved -> ()
            match dispatch, possession with
            | TerminalFlowKernelDispatchAcceptedObserved _, TerminalFlowReducerPossessionVacantObserved -> add (TerminalFlowActorAcceptedWithoutPossession requestRef)
            | TerminalFlowKernelDispatchUnavailableObserved, TerminalFlowReducerPossessionFilledObserved _
            | TerminalFlowKernelDispatchUnavailableObserved, TerminalFlowReducerPossessionSealedObserved _
            | TerminalFlowKernelDispatchReadyObserved _, TerminalFlowReducerPossessionFilledObserved _
            | TerminalFlowKernelDispatchReadyObserved _, TerminalFlowReducerPossessionSealedObserved _ ->
                add (TerminalFlowActorAdvancedPossessionWithoutAcceptedDispatch requestRef)
            | _ -> ()
            match protocol with
            | TerminalFlowDispatchProtocolReadyObserved(_, lineageRef, rootRef, terminalRef, fillRef)
            | TerminalFlowDispatchProtocolIssuedObserved(_, _, lineageRef, rootRef, terminalRef, fillRef) ->
                if lineageRef <> request.constitutionLineageRef then add (TerminalFlowActorProtocolLineageMismatch(lineageRef, request.constitutionLineageRef))
                if rootRef <> requestRootRef then add (TerminalFlowActorProtocolRootMismatch(rootRef, requestRootRef))
                if terminalRef <> requestTerminalRef then add (TerminalFlowActorProtocolTerminalMismatch(terminalRef, requestTerminalRef))
                if fillRef <> requestFillRef then add (TerminalFlowActorProtocolFillMismatch(fillRef, requestFillRef))
            | TerminalFlowDispatchProtocolNonDispatchObserved _ -> ()
            let violations = List.rev violations
            let coherence =
                match terminalFlowActorStateViolationPathOf violations with
                | None -> TerminalFlowActorStateCoherent
                | Some path -> TerminalFlowActorStateDivergent path
            { scheduler = scheduler
              dispatch = dispatch
              possession = possession
              protocol = protocol
              requestRef = requestRef
              requestLineageRef = request.constitutionLineageRef
              requestRootRef = requestRootRef
              requestTerminalRef = requestTerminalRef
              requestFillRef = requestFillRef
              lifecycleRef = lifecycleFrame.frameRef
              lifecycleExactOnceRef = lifecycleFrame.exactOnceRef
              lifecycleRevision = lifecycleFrame.reducerRevision
              coherence = coherence
              violationCount = List.length violations }

        let private terminalFlowActorStateWitnessSparseKey witness =
            FastRuntimeFormat.format "%s|%s|%s|%s|request_ref=%u|lineage_ref=%u|root_ref=%u|terminal_ref=%u|fill_ref=%u|coherence=%s|violations=%d" [| box (terminalFlowSchedulerActorObservationText witness.scheduler); box (terminalFlowKernelDispatchObservationText witness.dispatch); box (terminalFlowReducerPossessionObservationText witness.possession); box (terminalFlowDispatchProtocolObservationText witness.protocol); box witness.requestRef; box witness.requestLineageRef; box witness.requestRootRef; box witness.requestTerminalRef; box witness.requestFillRef; box (terminalFlowActorStateCoherenceText witness.coherence); box witness.violationCount |]

        let private terminalFlowActorStateWitnessRef witness =
            terminalFlowMintedRefOf "terminal_actor_state_witness_ref" (terminalFlowActorStateWitnessSparseKey witness)

        let private terminalFlowEmitActorStateWitness witness =
            let witnessRef = terminalFlowActorStateWitnessRef witness
            let occurrenceCount, shouldEmit = sparseLogDecision ("terminal_actor_state_witness|" + terminalFlowActorStateWitnessSparseKey witness) 64L
            if shouldEmit then
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_actor_state_witness\",\"witness_ref\":%u,\"scheduler_du\":%s,\"dispatch_du\":%s,\"possession_du\":%s,\"protocol_du\":%s,\"request_ref\":%u,\"request_lineage_ref\":%u,\"request_root_ref\":%u,\"request_terminal_ref\":%u,\"request_fill_ref\":%u,\"lifecycle_ref\":%u,\"lifecycle_exact_once_ref\":%u,\"lifecycle_revision\":%d,\"coherence_du\":%s,\"violation_count\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"state_first3_power2_every64\",\"authority\":\"typed_recursive_dispatch_lifecycle_witness\"}" [| box witnessRef; box (DiagJson.esc (terminalFlowSchedulerActorObservationText witness.scheduler)); box (DiagJson.esc (terminalFlowKernelDispatchObservationText witness.dispatch)); box (DiagJson.esc (terminalFlowReducerPossessionObservationText witness.possession)); box (DiagJson.esc (terminalFlowDispatchProtocolObservationText witness.protocol)); box witness.requestRef; box witness.requestLineageRef; box witness.requestRootRef; box witness.requestTerminalRef; box witness.requestFillRef; box witness.lifecycleRef; box witness.lifecycleExactOnceRef; box witness.lifecycleRevision; box (DiagJson.esc (terminalFlowActorStateCoherenceText witness.coherence)); box witness.violationCount; box occurrenceCount |])
            witnessRef

        type TerminalFlowLifecycleCommandIdentityMismatch =
            | TerminalFlowProtocolRequestIdMismatch of expectedId:string * actualId:string
            | TerminalFlowProtocolLineageRefMismatch of expectedRef:uint32 * actualRef:uint32
            | TerminalFlowProtocolRootRefMismatch of expectedRef:uint32 * actualRef:uint32
            | TerminalFlowProtocolTerminalRefMismatch of expectedRef:uint32 * actualRef:uint32
            | TerminalFlowProtocolFillRefMismatch of expectedRef:uint32 * actualRef:uint32
            | TerminalFlowProtocolIssuanceRefMismatch of expectedRef:uint32 * actualRef:uint32
            | TerminalFlowProtocolTransactionRefMismatch of expectedRef:uint32 * actualRef:uint32
            | TerminalFlowProtocolExactOnceRefMismatch of expectedRef:uint32 * actualRef:uint32
            | TerminalFlowProtocolExitCodeMismatch of expectedCode:int * actualCode:int
            | TerminalFlowProtocolPhysicalExitRefMismatch of expectedRef:uint32 * actualRef:uint32

        type TerminalFlowLifecycleCommandMismatchPath =
            | TerminalFlowLifecycleCommandMismatchLast of TerminalFlowLifecycleCommandIdentityMismatch
            | TerminalFlowLifecycleCommandMismatchMore of TerminalFlowLifecycleCommandIdentityMismatch * TerminalFlowLifecycleCommandMismatchPath

        type TerminalFlowLifecycleCommandRejection =
            | TerminalFlowProtocolStageMismatch of commandKind:TerminalFlowLifecycleCommandKind * observed:TerminalFlowDispatchProtocolState
            | TerminalFlowProtocolIdentityMismatch of commandKind:TerminalFlowLifecycleCommandKind * requestRef:uint32 * mismatches:TerminalFlowLifecycleCommandMismatchPath

        type TerminalFlowLifecycleCommandAdmission =
            | TerminalFlowProtocolObserverCommandAdmitted of TerminalFlowLifecycleCommandKind
            | TerminalFlowProtocolReplayDrainAdmitted of requestRef:TerminalFlowIdentityRef<TerminalFlowReplayDrainRequestRefKind> * sampleRef:TerminalFlowIdentityRef<TerminalFlowFairnessEpochRefKind>
            | TerminalFlowProtocolDispatchReadyAdmitted of requestRef:uint32 * constitutionRef:uint32 * witnessRef:uint32
            | TerminalFlowProtocolDispatchReplayAdmitted of requestRef:uint32 * issuanceRef:uint32 * witnessRef:uint32
            | TerminalFlowProtocolDispatchExecutionAdmitted of requestRef:uint32 * issuanceRef:uint32
            | TerminalFlowProtocolAffineConsumeAdmitted of requestRef:uint32 * transactionRef:uint32
            | TerminalFlowProtocolAffineSealAdmitted of requestRef:uint32 * transactionRef:uint32
            | TerminalFlowProtocolExitAdmitted of requestRef:uint32 * exitCode:int * physicalExitRef:uint32

        type TerminalFlowLifecycleCommandDecision =
            | TerminalFlowLifecycleCommandAdmitted of TerminalFlowLifecycleCommandAdmission
            | TerminalFlowLifecycleCommandRejected of requestRef:uint32 * TerminalFlowLifecycleCommandRejection

        let rec private terminalFlowLifecycleCommandMismatchPathOf = function
            | [] -> None
            | [mismatch] -> Some (TerminalFlowLifecycleCommandMismatchLast mismatch)
            | mismatch :: rest ->
                terminalFlowLifecycleCommandMismatchPathOf rest
                |> Option.map (fun tail -> TerminalFlowLifecycleCommandMismatchMore(mismatch, tail))

        let private terminalFlowLifecycleCommandIdentityMismatchText = function
            | TerminalFlowProtocolRequestIdMismatch(expectedId, actualId) -> sprintf "RequestIdMismatch(expected=%s|actual=%s)" expectedId actualId
            | TerminalFlowProtocolLineageRefMismatch(expectedRef, actualRef) -> sprintf "LineageRefMismatch(expected=%u|actual=%u)" expectedRef actualRef
            | TerminalFlowProtocolRootRefMismatch(expectedRef, actualRef) -> sprintf "RootRefMismatch(expected=%u|actual=%u)" expectedRef actualRef
            | TerminalFlowProtocolTerminalRefMismatch(expectedRef, actualRef) -> sprintf "TerminalRefMismatch(expected=%u|actual=%u)" expectedRef actualRef
            | TerminalFlowProtocolFillRefMismatch(expectedRef, actualRef) -> sprintf "FillRefMismatch(expected=%u|actual=%u)" expectedRef actualRef
            | TerminalFlowProtocolIssuanceRefMismatch(expectedRef, actualRef) -> sprintf "IssuanceRefMismatch(expected=%u|actual=%u)" expectedRef actualRef
            | TerminalFlowProtocolTransactionRefMismatch(expectedRef, actualRef) -> sprintf "TransactionRefMismatch(expected=%u|actual=%u)" expectedRef actualRef
            | TerminalFlowProtocolExactOnceRefMismatch(expectedRef, actualRef) -> sprintf "ExactOnceRefMismatch(expected=%u|actual=%u)" expectedRef actualRef
            | TerminalFlowProtocolExitCodeMismatch(expectedCode, actualCode) -> sprintf "ExitCodeMismatch(expected=%d|actual=%d)" expectedCode actualCode
            | TerminalFlowProtocolPhysicalExitRefMismatch(expectedRef, actualRef) -> sprintf "PhysicalExitRefMismatch(expected=%u|actual=%u)" expectedRef actualRef

        let rec private terminalFlowLifecycleCommandMismatchPathText = function
            | TerminalFlowLifecycleCommandMismatchLast mismatch -> terminalFlowLifecycleCommandIdentityMismatchText mismatch
            | TerminalFlowLifecycleCommandMismatchMore(mismatch, rest) -> terminalFlowLifecycleCommandIdentityMismatchText mismatch + "->" + terminalFlowLifecycleCommandMismatchPathText rest

        let private terminalFlowLifecycleCommandRejectionText = function
            | TerminalFlowProtocolStageMismatch(kind, protocol) ->
                sprintf "ProtocolStageMismatch(command=%s|observed=%s)" (terminalFlowLifecycleCommandKindText kind) (terminalFlowDispatchProtocolStateText protocol)
            | TerminalFlowProtocolIdentityMismatch(kind, requestRef, mismatches) ->
                FastRuntimeFormat.format "IdentityMismatch(command=%s|request_ref=%u|path=%s)" [| box (terminalFlowLifecycleCommandKindText kind); box requestRef; box (terminalFlowLifecycleCommandMismatchPathText mismatches) |]

        let private terminalFlowLifecycleCommandAdmissionText = function
            | TerminalFlowProtocolObserverCommandAdmitted kind -> "ObserverCommand(" + terminalFlowLifecycleCommandKindText kind + ")"
            | TerminalFlowProtocolReplayDrainAdmitted(requestRef, sampleRef) -> FastRuntimeFormat.format "ReplayDrain(request_ref=%u|sample_ref=%u)" [| box (terminalFlowIdentityRefDigest requestRef); box (terminalFlowIdentityRefDigest sampleRef) |]
            | TerminalFlowProtocolDispatchReadyAdmitted(requestRef, constitutionRef, witnessRef) -> FastRuntimeFormat.format "DispatchReady(request_ref=%u|constitution_ref=%u|witness_ref=%u)" [| box requestRef; box constitutionRef; box witnessRef |]
            | TerminalFlowProtocolDispatchReplayAdmitted(requestRef, issuanceRef, witnessRef) -> FastRuntimeFormat.format "DispatchReplay(request_ref=%u|issuance_ref=%u|witness_ref=%u)" [| box requestRef; box issuanceRef; box witnessRef |]
            | TerminalFlowProtocolDispatchExecutionAdmitted(requestRef, issuanceRef) -> sprintf "DispatchExecution(request_ref=%u|issuance_ref=%u)" requestRef issuanceRef
            | TerminalFlowProtocolAffineConsumeAdmitted(requestRef, transactionRef) -> sprintf "AffineConsume(request_ref=%u|transaction_ref=%u)" requestRef transactionRef
            | TerminalFlowProtocolAffineSealAdmitted(requestRef, transactionRef) -> sprintf "AffineSeal(request_ref=%u|transaction_ref=%u)" requestRef transactionRef
            | TerminalFlowProtocolExitAdmitted(requestRef, exitCode, physicalExitRef) -> FastRuntimeFormat.format "Exit(request_ref=%u|exit_code=%d|physical_exit_ref=%u)" [| box requestRef; box exitCode; box physicalExitRef |]

        let private terminalFlowLifecycleCommandDecisionFor
            (state:TerminalFlowGlobalReducerState)
            (command:TerminalFlowGlobalServerCommand) =
            let lifecycleFrame = terminalFlowDispatchLifecycleFrame state.dispatchLifecycle
            let protocol = lifecycleFrame.protocol
            let rejectStage requestRef kind =
                TerminalFlowLifecycleCommandRejected(requestRef, TerminalFlowProtocolStageMismatch(kind, protocol))
            let decideIdentity requestRef kind mismatches onAdmitted =
                match terminalFlowLifecycleCommandMismatchPathOf mismatches with
                | None -> TerminalFlowLifecycleCommandAdmitted onAdmitted
                | Some path -> TerminalFlowLifecycleCommandRejected(requestRef, TerminalFlowProtocolIdentityMismatch(kind, requestRef, path))
            match command with
            | TerminalFlowGlobalServerAwaitDataflow _ -> TerminalFlowLifecycleCommandAdmitted (TerminalFlowProtocolObserverCommandAdmitted TerminalFlowProtocolAwaitDataflowCommand)
            | TerminalFlowGlobalServerDrainQueuedReplay request ->
                TerminalFlowLifecycleCommandAdmitted(
                    TerminalFlowProtocolReplayDrainAdmitted(request.requestRef, request.fairnessSampleRef))
            | TerminalFlowGlobalServerRunQapPostCommitEffect _ ->
                // The command DU can only contain a certified stage envelope.
                // Missing evidence is represented before command construction.
                TerminalFlowLifecycleCommandAdmitted(
                    TerminalFlowProtocolObserverCommandAdmitted TerminalFlowProtocolQapPostCommitCommand)
            | TerminalFlowGlobalServerFailClosed _ -> TerminalFlowLifecycleCommandAdmitted (TerminalFlowProtocolObserverCommandAdmitted TerminalFlowProtocolFailClosedCommand)
            | TerminalFlowGlobalServerPublishDispatchRequest (request:TerminalFlowGlobalDispatchRequest) ->
                let kind = TerminalFlowProtocolPublishDispatchCommand
                let witness = terminalFlowActorStateWitnessFor state request
                let witnessRef = terminalFlowActorStateWitnessRef witness
                let requestRef = witness.requestRef
                match protocol with
                | TerminalFlowProtocolDispatchReady constitution ->
                    let mismatches =
                        [ if constitution.rootRef <> witness.requestRootRef then yield TerminalFlowProtocolRootRefMismatch(constitution.rootRef, witness.requestRootRef)
                          if constitution.terminalRef <> witness.requestTerminalRef then yield TerminalFlowProtocolTerminalRefMismatch(constitution.terminalRef, witness.requestTerminalRef)
                          if constitution.fillRef <> witness.requestFillRef then yield TerminalFlowProtocolFillRefMismatch(constitution.fillRef, witness.requestFillRef) ]
                    decideIdentity requestRef kind mismatches (TerminalFlowProtocolDispatchReadyAdmitted(requestRef, constitution.constitutionRef, witnessRef))
                | TerminalFlowProtocolDispatchIssued issuance ->
                    let mismatches =
                        [ if issuance.request.requestId <> request.requestId then yield TerminalFlowProtocolRequestIdMismatch(issuance.request.requestId, request.requestId)
                          let lineageRef = terminalFlowDispatchConstitutionLineageRef issuance.constitution
                          if lineageRef <> request.constitutionLineageRef then yield TerminalFlowProtocolLineageRefMismatch(lineageRef, request.constitutionLineageRef)
                          if issuance.constitution.rootRef <> witness.requestRootRef then yield TerminalFlowProtocolRootRefMismatch(issuance.constitution.rootRef, witness.requestRootRef)
                          if issuance.constitution.terminalRef <> witness.requestTerminalRef then yield TerminalFlowProtocolTerminalRefMismatch(issuance.constitution.terminalRef, witness.requestTerminalRef)
                          if issuance.constitution.fillRef <> witness.requestFillRef then yield TerminalFlowProtocolFillRefMismatch(issuance.constitution.fillRef, witness.requestFillRef) ]
                    decideIdentity requestRef kind mismatches (TerminalFlowProtocolDispatchReplayAdmitted(requestRef, issuance.issuanceRef, witnessRef))
                | _ -> rejectStage requestRef kind
            | TerminalFlowGlobalServerExecuteDispatch issuance ->
                let kind = TerminalFlowProtocolExecuteDispatchCommand
                match protocol with
                | TerminalFlowProtocolDispatchIssued committed ->
                    let mismatches =
                        [ if committed.issuanceRef <> issuance.issuanceRef then yield TerminalFlowProtocolIssuanceRefMismatch(committed.issuanceRef, issuance.issuanceRef)
                          if committed.exactOnceRef <> issuance.exactOnceRef then yield TerminalFlowProtocolExactOnceRefMismatch(committed.exactOnceRef, issuance.exactOnceRef) ]
                    decideIdentity issuance.requestRef kind mismatches (TerminalFlowProtocolDispatchExecutionAdmitted(issuance.requestRef, issuance.issuanceRef))
                | _ -> rejectStage issuance.requestRef kind
            | TerminalFlowGlobalServerConsumeStageToken transaction ->
                let kind = TerminalFlowProtocolConsumeStageTokenCommand
                let requestRef = transaction.authorization.issuance.requestRef
                match protocol with
                | TerminalFlowProtocolAffinePrepared committed ->
                    let mismatches =
                        [ if committed.transactionRef <> transaction.transactionRef then yield TerminalFlowProtocolTransactionRefMismatch(committed.transactionRef, transaction.transactionRef)
                          if committed.exactOnceRef <> transaction.exactOnceRef then yield TerminalFlowProtocolExactOnceRefMismatch(committed.exactOnceRef, transaction.exactOnceRef) ]
                    decideIdentity requestRef kind mismatches (TerminalFlowProtocolAffineConsumeAdmitted(requestRef, transaction.transactionRef))
                | _ -> rejectStage requestRef kind
            | TerminalFlowGlobalServerAuthorizeStageTokenSeal filled ->
                let kind = TerminalFlowProtocolAuthorizeStageTokenSealCommand
                let requestRef = filled.issued.transaction.authorization.issuance.requestRef
                let transaction = filled.issued.transaction
                match protocol with
                | TerminalFlowProtocolAffineFilled committed ->
                    let mismatches =
                        [ if committed.transactionRef <> transaction.transactionRef then yield TerminalFlowProtocolTransactionRefMismatch(committed.transactionRef, transaction.transactionRef)
                          if committed.exactOnceRef <> transaction.exactOnceRef then yield TerminalFlowProtocolExactOnceRefMismatch(committed.exactOnceRef, transaction.exactOnceRef) ]
                    decideIdentity requestRef kind mismatches (TerminalFlowProtocolAffineSealAdmitted(requestRef, transaction.transactionRef))
                | _ -> rejectStage requestRef kind
            | TerminalFlowGlobalServerCommitExit authorized ->
                let kind = TerminalFlowProtocolCommitExitCommand
                let requestRef = authorized.request.requestRef
                match protocol with
                | TerminalFlowProtocolExitAuthorized chain ->
                    let mismatches =
                        [ if authorized.request.exitCode <> 0 then yield TerminalFlowProtocolExitCodeMismatch(0, authorized.request.exitCode)
                          if chain.exitCode <> 0 then yield TerminalFlowProtocolExitCodeMismatch(0, chain.exitCode)
                          if chain.physicalExit.receiptRef <> authorized.reducerPhysicalExitReceiptRef then yield TerminalFlowProtocolPhysicalExitRefMismatch(chain.physicalExit.receiptRef, authorized.reducerPhysicalExitReceiptRef) ]
                    decideIdentity requestRef kind mismatches (TerminalFlowProtocolExitAdmitted(requestRef, authorized.request.exitCode, authorized.reducerPhysicalExitReceiptRef))
                | TerminalFlowProtocolFailClosed chain ->
                    let mismatches =
                        [ if authorized.request.exitCode = 0 then yield TerminalFlowProtocolExitCodeMismatch(chain.exitCode, authorized.request.exitCode)
                          if chain.exitCode <> authorized.request.exitCode then yield TerminalFlowProtocolExitCodeMismatch(chain.exitCode, authorized.request.exitCode)
                          if chain.physicalExit.receiptRef <> authorized.reducerPhysicalExitReceiptRef then yield TerminalFlowProtocolPhysicalExitRefMismatch(chain.physicalExit.receiptRef, authorized.reducerPhysicalExitReceiptRef) ]
                    decideIdentity requestRef kind mismatches (TerminalFlowProtocolExitAdmitted(requestRef, authorized.request.exitCode, authorized.reducerPhysicalExitReceiptRef))
                | _ -> rejectStage requestRef kind

        let private terminalFlowLifecycleCommandGate
            (state:TerminalFlowGlobalReducerState)
            (command:TerminalFlowGlobalServerCommand) =
            let kind = terminalFlowLifecycleCommandKindFor command
            let witnessRef =
                match command with
                | TerminalFlowGlobalServerPublishDispatchRequest (request:TerminalFlowGlobalDispatchRequest) ->
                    terminalFlowActorStateWitnessFor state request |> terminalFlowEmitActorStateWitness |> Some
                | _ -> None
            let lifecycleFrameAtGate = terminalFlowDispatchLifecycleFrame state.dispatchLifecycle
            let gatedDecision =
                match lifecycleFrameAtGate.poison, lifecycleFrameAtGate.poisonTerminalization with
                | TerminalFlowProtocolPoisonLatched _, TerminalFlowProtocolPoisonFailClosedTerminalized(poisonRef, terminalizedCommandRef, _) ->
                    Choice1Of2(poisonRef, terminalizedCommandRef)
                | _ ->
                    Choice2Of2(terminalFlowLifecycleCommandDecisionFor state command)
            match gatedDecision with
            | Choice1Of2(poisonRef, terminalizedCommandRef) ->
                TerminalFlowGlobalServerAwaitDataflow(
                    TerminalFlowWaitDispatchLifecyclePoisonTerminalized(poisonRef, terminalizedCommandRef))
            | Choice2Of2(TerminalFlowLifecycleCommandAdmitted admission) ->
                let admissionText = terminalFlowLifecycleCommandAdmissionText admission
                let admissionRef = terminalFlowMintedRefOf "terminal_lifecycle_command_admission_ref" admissionText
                let occurrenceCount, shouldEmit = sparseLogDecision ("terminal_lifecycle_command_admitted|" + admissionText) 64L
                if shouldEmit then
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_lifecycle_command_admitted\",\"command_kind_du\":%s,\"admission_ref\":%u,\"admission_du\":%s,\"actor_state_witness_ref\":%u,\"occurrence_count\":%d,\"sparse_policy\":\"state_first3_power2_every64\",\"authority_ref\":%u,\"exact_once_ref\":%u,\"authority\":\"typed_exhaustive_lifecycle_command_admission\"}" [| box (DiagJson.esc (terminalFlowLifecycleCommandKindText kind)); box admissionRef; box (DiagJson.esc admissionText); box (defaultArg witnessRef 0u); box occurrenceCount; box (terminalFlowDispatchLifecycleRef state.dispatchLifecycle); box (terminalFlowDispatchLifecycleExactOnceRef state.dispatchLifecycle) |])
                command
            | Choice2Of2(TerminalFlowLifecycleCommandRejected(requestRef, rejection)) ->
                let commandRef = terminalFlowGlobalServerCommandRef command
                let protocolRef =
                    state.dispatchLifecycle
                    |> terminalFlowDispatchLifecycleProtocol
                    |> terminalFlowDispatchProtocolStateRef
                let lifecycleFrame = terminalFlowDispatchLifecycleFrame state.dispatchLifecycle
                let rejectionText = terminalFlowLifecycleCommandRejectionText rejection
                let reasonRef = terminalFlowMintedRefOf "terminal_lifecycle_command_rejection_ref" rejectionText
                let poisoned = terminalFlowProtocolPoisonLatchIsPoisoned lifecycleFrame.poison
                let rejectionSparseKey =
                    FastRuntimeFormat.format "terminal_lifecycle_command_rejected|command=%s|rejection=%s|poisoned=%b" [| box (terminalFlowLifecycleCommandKindText kind); box rejectionText; box poisoned |]
                let occurrenceCount, shouldEmit = sparseLogDecision rejectionSparseKey 64L
                if shouldEmit then
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_lifecycle_command_rejected\",\"command_kind_du\":%s,\"command_ref\":%u,\"protocol_ref\":%u,\"reason_ref\":%u,\"rejection_du\":%s,\"actor_state_witness_ref\":%u,\"poisoned\":%b,\"rejection_count\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"state_first3_power2_every64\",\"authority_ref\":%u,\"exact_once_ref\":%u,\"authority\":\"typed_exhaustive_lifecycle_command_admission\"}" [| box (DiagJson.esc (terminalFlowLifecycleCommandKindText kind)); box commandRef; box protocolRef; box reasonRef; box (DiagJson.esc rejectionText); box (defaultArg witnessRef 0u); box poisoned; box lifecycleFrame.rejectionCount; box occurrenceCount; box (terminalFlowDispatchLifecycleRef state.dispatchLifecycle); box (terminalFlowDispatchLifecycleExactOnceRef state.dispatchLifecycle) |])
                match lifecycleFrame.poison, lifecycleFrame.poisonTerminalization, rejection with
                | TerminalFlowProtocolPoisonLatched _, TerminalFlowProtocolPoisonFailClosedTerminalized(poisonRef, terminalizedCommandRef, _), _ ->
                    TerminalFlowGlobalServerAwaitDataflow(
                        TerminalFlowWaitDispatchLifecyclePoisonTerminalized(poisonRef, terminalizedCommandRef))
                | TerminalFlowProtocolPoisonLatched(_, poisonRef, _), TerminalFlowProtocolPoisonNotTerminalized, _ ->
                    TerminalFlowGlobalServerFailClosed(
                        TerminalFlowFailureDispatchLifecyclePoisoned(
                            poisonRef,
                            protocolRef,
                            commandRef,
                            lifecycleFrame.rejectionCount))
                | TerminalFlowProtocolPoisonHealthy, _, _ -> TerminalFlowGlobalServerAwaitDataflow(TerminalFlowWaitDispatchDuplicate requestRef)

        type TerminalFlowGlobalServerEventPriorityId =
            | TerminalFlowGlobalEventTerminalPriority
            | TerminalFlowGlobalEventOrdinaryPriority

        let private terminalFlowGlobalServerEventPriorityText = function
            | TerminalFlowGlobalEventTerminalPriority -> "terminal"
            | TerminalFlowGlobalEventOrdinaryPriority -> "ordinary"

        let private terminalFlowGlobalServerEventPriorityFor = function
            | TerminalFlowGlobalServerEvaluatorRootResolved _
            | TerminalFlowGlobalServerTerminalOutcomeReady _
            | TerminalFlowGlobalServerDispatchRequested _
            | TerminalFlowGlobalServerDispatchExecuted _
            | TerminalFlowGlobalServerQapFixpointObserved _
            | TerminalFlowGlobalServerQapWatchRebaseRequested _
            | TerminalFlowGlobalServerQapPostCommitEffectCompleted _
            | TerminalFlowGlobalServerArtifactCommitObserved _
            | TerminalFlowGlobalServerExitWitnessReady _
            | TerminalFlowGlobalServerHostShutdownRequested _
            | TerminalFlowGlobalServerTerminalOrderCutoverObserved _
            | TerminalFlowGlobalServerTerminalOrderCutoverMinted _
            | TerminalFlowGlobalServerObserverExitPetitioned _
            | TerminalFlowGlobalServerTopologyGateTransitionObserved _
            | TerminalFlowGlobalServerReplayFairnessObserved _
            | TerminalFlowGlobalServerAdmissionRunEndFixtureProven _
            | TerminalFlowGlobalServerQueueOnlyRecoveryFolded _
            | TerminalFlowGlobalServerOwnerWorkDagProduced _
            | TerminalFlowGlobalServerCicKernelProofObserved _
            | TerminalFlowGlobalServerStageTokenIssued _
            | TerminalFlowGlobalServerStageTokenFillCommitted _
            | TerminalFlowGlobalServerStageTokenSealAuthorized _
            | TerminalFlowGlobalServerStageTokenFailedClosed _
            | TerminalFlowGlobalServerOwnerDebtObserved(_, _, _, _, Some _) -> TerminalFlowGlobalEventTerminalPriority
            | TerminalFlowGlobalServerProgressEvidenceObserved _ ->
                // Progress evidence is reducer control data, not observer telemetry.
                // Route it with the QAP event that consumes it so the fixpoint can never
                // overtake the snapshot and manufacture CompletionFence(NoSnapshot).
                TerminalFlowGlobalEventTerminalPriority
            | _ -> TerminalFlowGlobalEventOrdinaryPriority

        let private terminalFlowGlobalServerEventKind = function
            | TerminalFlowGlobalServerEvaluatorRootResolved _ -> "root_resolved"
            | TerminalFlowGlobalServerTerminalOutcomeReady _ -> "terminal_outcome_ready"
            | TerminalFlowGlobalServerDispatchRequested _ -> "dispatch_requested"
            | TerminalFlowGlobalServerDispatchExecuted _ -> "dispatch_executed"
            | TerminalFlowGlobalServerQapFixpointObserved _ -> "qap_fixpoint_observed"
            | TerminalFlowGlobalServerQapWatchRebaseRequested _ -> "qap_watch_rebase_requested"
            | TerminalFlowGlobalServerQapPostCommitEffectCompleted _ -> "qap_post_commit_effect_completed"
            | TerminalFlowGlobalServerProgressEvidenceObserved _ -> "progress_evidence_observed"
            | TerminalFlowGlobalServerTopologyGateTransitionObserved _ -> "topology_gate_transition_observed"
            | TerminalFlowGlobalServerReplayFairnessObserved _ -> "replay_fairness_observed"
            | TerminalFlowGlobalServerAdmissionRunEndFixtureProven _ -> "admission_run_end_fixture_proven"
            | TerminalFlowGlobalServerQueueOnlyRecoveryFolded _ -> "queue_only_recovery_folded"
            | TerminalFlowGlobalServerArtifactCommitObserved _ -> "artifact_commit_observed"
            | TerminalFlowGlobalServerExitWitnessReady _ -> "exit_witness_ready"
            | TerminalFlowGlobalServerWatchdogPetitioned _ -> "watchdog_petitioned"
            | TerminalFlowGlobalServerHostShutdownRequested _ -> "host_shutdown_requested"
            | TerminalFlowGlobalServerOwnerWorkDagProduced _ -> "owner_workdag_produced"
            | TerminalFlowGlobalServerTerminalOrderCutoverObserved _ -> "terminal_order_cutover_observed"
            | TerminalFlowGlobalServerTerminalOrderCutoverMinted _ -> "terminal_order_cutover_minted"
            | TerminalFlowGlobalServerProjectionCoalesced _ -> "projection_coalesced"
            | TerminalFlowGlobalServerCriticalPathEtaObserved _ -> "critical_path_eta_observed"
            | TerminalFlowGlobalServerCompactHudPaneProjected _ -> "compact_hud_pane_projected"
            | TerminalFlowGlobalServerEvalWorklistShimDemoted _ -> "eval_worklist_shim_demoted"
            | TerminalFlowGlobalServerSemanticFactMinted _ -> "semantic_fact_minted"
            | TerminalFlowGlobalServerNativeEvalNoFactRejected _ -> "native_eval_no_fact_rejected"
            | TerminalFlowGlobalServerSchedulerSpawnGrantObserved _ -> "scheduler_spawn_grant_observed"
            | TerminalFlowGlobalServerCicKernelWorkObserved _ -> "cic_kernel_work_observed"
            | TerminalFlowGlobalServerHvmLoweringPrepared _ -> "hvm_lowering_prepared"
            | TerminalFlowGlobalServerBreakthroughTransitionObserved _ -> "breakthrough_transition_observed"
            | TerminalFlowGlobalServerLegacyTerminalAuthorityDemoted _ -> "legacy_terminal_authority_demoted"
            | TerminalFlowGlobalServerObserverExitPetitioned _ -> "observer_exit_petitioned"
            | TerminalFlowGlobalServerTypedSemanticIngressObserved _ -> "typed_semantic_ingress_observed"
            | TerminalFlowGlobalServerDeadmanExpired _ -> "legacy_deadman_observed"
            | TerminalFlowGlobalServerOwnerDebtObserved _ -> "owner_debt_observed"
            | TerminalFlowGlobalServerCicKernelProofObserved _ -> "cic_kernel_proof_observed"
            | TerminalFlowGlobalServerCicActorStepObserved _ -> "cic_actor_step_observed"
            | TerminalFlowGlobalServerCicActorCloseRequested _ -> "cic_actor_close_requested"
            | TerminalFlowGlobalServerStageTokenIssued _ -> "stage_token_issued"
            | TerminalFlowGlobalServerStageTokenFillCommitted _ -> "stage_token_fill_committed"
            | TerminalFlowGlobalServerStageTokenSealAuthorized _ -> "stage_token_seal_authorized"
            | TerminalFlowGlobalServerStageTokenFailedClosed _ -> "stage_token_failed_closed"
            | TerminalFlowGlobalServerActorProjectionObserved _ -> "actor_projection_observed"

        let private terminalFlowGlobalServerPublishJob event : Hopac.Job<unit> =
            job {
                match event with
                | TerminalFlowGlobalServerExitWitnessReady request ->
                    terminalFlowRememberIndexedClosureExitRequest request |> ignore
                | _ -> ()
                let eventText = terminalFlowGlobalServerEventText event
                let eventKind = terminalFlowGlobalServerEventKind event
                let eventPriority = terminalFlowGlobalServerEventPriorityFor event
                let terminalPriority, publishChannel, channelText =
                    match eventPriority with
                    | TerminalFlowGlobalEventTerminalPriority ->
                        true, terminalFlowGlobalServerControlChannel, "terminal_flow_global_control"
                    | TerminalFlowGlobalEventOrdinaryPriority ->
                        false, terminalFlowGlobalServerChannel, "terminal_flow_global_data"
                let publishSeq = terminalFlowGlobalServerCounterAdvance TerminalFlowGlobalServerCounterPublished
                let occurrence, shouldEmit = DiagJson.sparseLogDecision ("published|" + eventKind) 128L
                if shouldEmit then
                    DiagJson.emitOutsideHopac (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_flow_global_event_published\",\"event_kind_du\":%s,\"event_ref\":%u,\"event\":%s,\"publish_seq\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"first3_power2_every128\",\"channel\":%s,\"priority_du\":%s,\"terminal_priority\":%b,\"publish_mode\":\"PortableMailboxOps.send\",\"polling_authority\":false}" [| box (DiagJson.esc eventKind); box (terminalFlowMintedRefOf "global_server_event_ref" eventText); box (DiagJson.esc eventText); box publishSeq; box occurrence; box (DiagJson.esc channelText); box (DiagJson.esc (terminalFlowGlobalServerEventPriorityText eventPriority)); box terminalPriority |])
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.send
                        publishChannel
                        (TerminalFlowReducerActorApply event)
            }

        let private terminalFlowGlobalReducerReadActorState () =
            job {
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<TerminalFlowGlobalReducerState>
                        "terminal-flow-reducer-read"
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.send
                        terminalFlowGlobalServerControlChannel
                        (TerminalFlowReducerActorRead reply)
                return!
                    CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
            }

        let private terminalFlowGlobalServerPublish event =
            match terminalFlowGlobalServerEventPriorityFor event with
            | TerminalFlowGlobalEventTerminalPriority ->
                // Terminal evidence has a physical control lane.  The producer remains a
                // Hopac job; no CLR task may own reducer delivery or outlive its scope.
                let eventKind = terminalFlowGlobalServerEventKind event
                let occurrence, shouldEmit = DiagJson.sparseLogDecision ("terminal_priority_route|" + eventKind) 64L
                if shouldEmit then
                    DiagJson.emitOutsideHopac (
                        sprintf "{\"kind\":\"terminal_flow_global_terminal_priority_routed\",\"event_kind_du\":%s,\"occurrence_count\":%d,\"launch_mode_du\":\"hopac_control_lane\",\"channel\":\"terminal_flow_global_control\",\"authority\":\"typed_terminal_priority_control_plane\",\"polling_authority\":false}"
                            (DiagJson.esc eventKind)
                            occurrence)
                HopacExtensions.start (terminalFlowGlobalServerPublishJob event)
            | TerminalFlowGlobalEventOrdinaryPriority ->
                HopacExtensions.start (terminalFlowGlobalServerPublishJob event)

        do
            terminalFlowInstallIndexedClosureExitReplay (fun request ->
                // Keep exit-witness liveness inside one ordered control-lane job. The
                // follow-up reducer read is not exit authority: its one-shot reply only
                // proves that the single reducer got an opportunity after the witness
                // publication was accepted by the control mailbox.
                HopacExtensions.start (job {
                    do! terminalFlowGlobalServerPublishJob (TerminalFlowGlobalServerExitWitnessReady request)
                    let! stateAfterPulse = terminalFlowGlobalReducerReadActorState ()
                    let snapshotAfterPulse = terminalFlowImmutableTerminalSnapshotFor stateAfterPulse
                    let requestRef = terminalFlowMintedRefOf "indexed_closure_exit_request_ref" request.requestId
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format
                            "{\"kind\":\"terminal_indexed_closure_exit_control_pulse_observed\",\"request_ref\":%u,\"exit_witness_ref\":%u,\"exit_code\":%d,\"reducer_revision_after_pulse\":%d,\"terminal_stage_after_du\":%s,\"pulse_authority_du\":\"ReducerReadAfterExitWitnessMailboxPublication\",\"physical_exit_authority\":false,\"authority\":\"typed_exit_witness_control_lane_liveness_receipt\",\"next\":\"observe_physical_boundary_or_typed_blocker\"}"
                            [| box requestRef; box (terminalFlowPhysicalExitChainExitWitnessRef request.physicalChain); box request.exitCode; box snapshotAfterPulse.reducerRevision; box (DiagJson.esc (terminalFlowImmutableTerminalStageText snapshotAfterPulse.terminalStage)) |])
                    return ()
                }))

        [<Struct; StructuralEquality; NoComparison>]
        type private TerminalFlowDeferredOutcomeMailboxPublicationIdentity = {
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            fillRef : TerminalFlowIdentityRef<TerminalFlowFillRefKind>
            admission : TerminalFlowPendingAdmission
            intent : TerminalFlowPendingTerminalIntent
            dispatchAuthority : TerminalFlowPendingDispatchAuthority
        }

        let private terminalFlowDeferredOutcomeMailboxPublicationRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<TerminalFlowDeferredOutcomeMailboxPublicationIdentity,byte>()

        let private terminalFlowPublishDeferredOutcomeMailboxOnce (pending:TerminalFlowGlobalPendingTerminal) =
            let publicationIdentity : TerminalFlowDeferredOutcomeMailboxPublicationIdentity =
                { terminalReceiptRef = pending.terminalReceiptRef
                  fillRef = pending.fillRef
                  admission = pending.admission
                  intent = pending.intent
                  dispatchAuthority = pending.dispatchAuthority }
            let publicationRef =
                terminalFlowMintedRefOf
                    "deferred_outcome_mailbox_publication_ref"
                    (FastRuntimeFormat.format "%u|%u|%u|%s|%s" [| box (terminalFlowIdentityRefDigest publicationIdentity.terminalReceiptRef); box (terminalFlowIdentityRefDigest publicationIdentity.fillRef); box (terminalFlowPendingAdmissionRef publicationIdentity.admission); box (terminalFlowPendingIntentText publicationIdentity.intent); box (terminalFlowPendingDispatchAuthorityText publicationIdentity.dispatchAuthority) |])
            if terminalFlowDeferredOutcomeMailboxPublicationRegistry.TryAdd(publicationIdentity, 0uy) then
                terminalFlowGlobalServerPublish (TerminalFlowGlobalServerTerminalOutcomeReady pending)
                true, publicationRef
            else
                false, publicationRef

        [<Struct; StructuralEquality; NoComparison>]
        type private TerminalFlowProgressControlIngressIdentity = {
            semanticEpoch : int64
            discovered : int64
            retired : int64
            blocked : int64
            queueDepth : int64
            activeWorkers : int64
            schedulerOpenCount : int64
            queueAttributionComplete : bool
        }

        let private terminalFlowProgressControlIngressRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<TerminalFlowProgressControlIngressIdentity,byte>()

        let private terminalFlowProgressProjectionObserveForReducer (evidence:TerminalFlowProgressEvidence) =
            let liveEvidence = terminalFlowProgressEvidenceWithLiveSchedulerOverlay evidence
            let alreadyAccepted =
                match terminalFlowLiveProgressEvidenceRead () with
                | Some(TerminalFlowLiveProgressAcceptedForControl, accepted)
                    when accepted.snapshotSequence >= liveEvidence.snapshotSequence -> true
                | _ -> false
            terminalFlowLiveProgressEvidenceObserve
                TerminalFlowLiveProgressObservedProjectionOnly
                liveEvidence
            let promotionGate = terminalFlowClosedWorldPromotionGateFor liveEvidence
            if not alreadyAccepted then
                let ingressIdentity : TerminalFlowProgressControlIngressIdentity =
                    { semanticEpoch = liveEvidence.semanticDigest.semanticEpoch
                      discovered = liveEvidence.frontier.discovered
                      retired = liveEvidence.frontier.retired
                      blocked = liveEvidence.frontier.blocked
                      queueDepth = liveEvidence.frontier.queueDepth
                      activeWorkers = liveEvidence.frontier.activeWorkers
                      schedulerOpenCount = liveEvidence.workLedger.schedulerOpenCount
                      queueAttributionComplete = liveEvidence.queueAttributionComplete }
                let ingressRef =
                    terminalFlowMintedRefOf
                        "progress_control_ingress_ref"
                        (FastRuntimeFormat.format "semantic_epoch=%d|discovered=%d|retired=%d|blocked=%d|q=%d|a=%d|open=%d|attributed=%b" [| box ingressIdentity.semanticEpoch; box ingressIdentity.discovered; box ingressIdentity.retired; box ingressIdentity.blocked; box ingressIdentity.queueDepth; box ingressIdentity.activeWorkers; box ingressIdentity.schedulerOpenCount; box ingressIdentity.queueAttributionComplete |])
                if terminalFlowProgressControlIngressRegistry.TryAdd(ingressIdentity, 0uy) then
                    let gateText = terminalFlowClosedWorldPromotionGateText promotionGate
                    let gateStructuralText = terminalFlowClosedWorldPromotionGateStructuralText promotionGate
                    let terminalPromotionEligible = promotionGate = TerminalFlowClosedWorldPromotionEligible
                    DiagJson.emitOutsideHopac (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_projected_progress_control_ingress\",\"ingress_ref\":%u,\"snapshot_ref\":%u,\"snapshot_sequence\":%d,\"semantic_epoch\":%d,\"discovered\":%d,\"retired\":%d,\"remaining\":%d,\"blocked\":%d,\"queue_depth\":%d,\"active_workers\":%d,\"scheduler_open_count\":%d,\"queue_attribution_complete\":%b,\"closed_world_promotion_eligible\":%b,\"promotion_gate_du\":%s,\"authority\":\"typed_progress_control_ingress_not_terminal_authority\",\"next\":\"publish_progress_evidence_to_single_reducer\"}" [| box ingressRef; box (terminalFlowIdentityRefDigest liveEvidence.snapshotRef); box liveEvidence.snapshotSequence; box liveEvidence.semanticDigest.semanticEpoch; box liveEvidence.frontier.discovered; box liveEvidence.frontier.retired; box (terminalFlowProgressRemaining liveEvidence); box liveEvidence.frontier.blocked; box liveEvidence.frontier.queueDepth; box liveEvidence.frontier.activeWorkers; box liveEvidence.workLedger.schedulerOpenCount; box liveEvidence.queueAttributionComplete; box terminalPromotionEligible; box (DiagJson.esc gateStructuralText) |])
                    terminalFlowGlobalServerPublish
                        (TerminalFlowGlobalServerProgressEvidenceObserved liveEvidence)
                    if not terminalPromotionEligible then
                        let gateAgeMs = terminalFlowClosedWorldPromotionGateAgeMs promotionGate
                        let occurrence, shouldEmit =
                            DiagJson.sparseLogDecision ("closed_world_progress_promotion_blocked|" + gateStructuralText) 128L
                        if shouldEmit then
                            DiagJson.emitOutsideHopac (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_projected_progress_promotion_blocked\",\"gate_du\":%s,\"gate_detail_du\":%s,\"gate_age_ms\":%d,\"occurrence_count\":%d,\"snapshot_ref\":%u,\"snapshot_sequence\":%d,\"queue_attribution_complete\":%b,\"discovered\":%d,\"retired\":%d,\"remaining\":%d,\"blocked\":%d,\"queue_depth\":%d,\"active_workers\":%d,\"scheduler_open_count\":%d,\"work_ledger_state_du\":%s,\"authority\":\"terminal_promotion_gate_only_control_ingress_already_published\",\"next\":\"wait_for_typed_closed_world_before_terminal_promotion\"}" [| box (DiagJson.esc gateStructuralText); box (DiagJson.esc gateText); box gateAgeMs; box occurrence; box (terminalFlowIdentityRefDigest liveEvidence.snapshotRef); box liveEvidence.snapshotSequence; box liveEvidence.queueAttributionComplete; box liveEvidence.frontier.discovered; box liveEvidence.frontier.retired; box (terminalFlowProgressRemaining liveEvidence); box liveEvidence.frontier.blocked; box liveEvidence.frontier.queueDepth; box liveEvidence.frontier.activeWorkers; box liveEvidence.workLedger.schedulerOpenCount; box (DiagJson.esc (terminalFlowWorkLedgerStateText liveEvidence.workLedger.state)) |])

        do terminalFlowInstallProgressProjectionObserver terminalFlowProgressProjectionObserveForReducer

        let private terminalFlowGlobalObserveCicKernelCorridor (corridor:TerminalFlowCicKernelCorridor) =
            let authority = terminalFlowKernelProofAuthorityFor corridor
            let actorStats =
                corridor.ownedActor
                |> terminalFlowCicOwnedActorState
                |> Option.map terminalFlowCicDefEqActorStatsText
                |> Option.defaultValue "detached"
            terminalFlowGlobalServerPublish (TerminalFlowGlobalServerCicKernelProofObserved authority)
            DiagJson.emit (
                FastRuntimeFormat.format "{\"kind\":\"terminal_cic_kernel_corridor_observed\",\"proof_authority_du\":%s,\"actor_lifecycle_du\":%s,\"defeq_actor_stats\":%s,\"proof_owner_close_receipt_ref\":%u,\"promotion_requires_breakthrough_seal\":true,\"polling_authority\":false}" [| box (DiagJson.esc (terminalFlowKernelProofAuthorityText authority)); box (DiagJson.esc (terminalFlowCicOwnedActorLifecycleStageText corridor.ownedActor)); box (DiagJson.esc actorStats); box (corridor.proofOwnerCloseReceiptRef |> Option.defaultValue 0u) |])

        let private terminalFlowGlobalDispatchRequestPrune fillKey =
            let mutable removed = 0uy
            for key in terminalFlowGlobalDispatchRequestRegistry.Keys do
                if terminalFlowDispatchJoinFillText key = fillKey then
                    terminalFlowGlobalDispatchRequestRegistry.TryRemove(key, &removed) |> ignore

        let private terminalFlowGlobalKernelProjection (kernel:TerminalFlowKernelState) =
            let rootReady, rootRef =
                match kernel.root with
                | KernelRootAwaitingEvaluator -> false, 0u
                | KernelRootResolved(receiptId, _, _) -> true, terminalFlowRootReceiptRef receiptId
            let outcomeReady, outcomeRef, fillRef =
                match kernel.outcome with
                | KernelOutcomeOpen -> false, 0u, 0u
                | KernelOutcomeSealed(terminalReceiptId, fillKey) ->
                    true,
                    terminalFlowIdentityRefDigest terminalReceiptId,
                    TerminalFlowFillKeyId.digest fillKey
            let actorPhase, actorFillRef =
                match kernel.actor with
                | KernelActorNoop -> "Noop", 0u
                | KernelActorArmed(phase, fillKey, _) -> DiagJson.terminalSchedulerPushActorPhaseText phase, TerminalFlowFillKeyId.digest fillKey
            let dispatchReady, dispatchRef =
                match kernel.dispatch with
                | KernelDispatchUnavailable -> false, 0u
                | KernelDispatchReady(identity, _, _)
                | KernelDispatchAccepted identity -> true, terminalFlowDispatchRequestIdentityRef identity
            rootReady, rootRef, outcomeReady, outcomeRef, fillRef, actorPhase, actorFillRef, dispatchReady, dispatchRef

        let private terminalFlowTerminalAuthorityFromKernel (state:TerminalFlowGlobalReducerState) (request:TerminalFlowGlobalExitRequest) =
            let projection = terminalFlowKernelDurableProjectionFor state.kernel
            let receiptProjection = terminalFlowExistentialReceiptProjectionFor projection
            let _, rootRef, _, terminalRef, fillRef, actorPhase, actorFillRef, dispatchReady, dispatchRef =
                terminalFlowGlobalKernelProjection state.kernel
            let actorRef =
                terminalFlowMintedRefOf
                    "actor_ref"
                    (FastRuntimeFormat.format "%s|actor_fill=%u|final=%s|fill=%s" [| box actorPhase; box actorFillRef; box (DiagJson.terminalSchedulerPushActorPhaseText request.finalActorPhase); box request.fillKey |])
            let chain = request.physicalChain
            let writerRef = terminalFlowPhysicalExitChainWriterRef chain
            let artifactRef = terminalFlowPhysicalExitChainArtifactRef chain
            let failureRef = terminalFlowPhysicalExitChainFailureRef chain
            let exitRef = terminalFlowPhysicalExitChainExitWitnessRef chain
            let causalRef =
                terminalFlowMintedRefOf "causal_spine_ref" (sprintf "revision=%d|last_event=%u" state.revision state.lastEventRef)
            let ownerClosureRef =
                terminalFlowMintedRefOf "owner_closure_certificate_ref" (FastRuntimeFormat.format "root=%u|terminal=%u|fill=%u|dispatch=%u|vector=%u" [| box rootRef; box terminalRef; box fillRef; box dispatchRef; box projection.receiptVectorHash |])
            let outcomeIvarFillRef =
                terminalFlowMintedRefOf "outcome_ivar_fill_ref" (FastRuntimeFormat.format "terminal=%u|fill=%u|owner=%u" [| box terminalRef; box fillRef; box ownerClosureRef |])
            let schedulerPushRef =
                terminalFlowMintedRefOf "scheduler_push_receipt_ref" (FastRuntimeFormat.format "dispatch=%u|actor=%u|fill=%u" [| box dispatchRef; box actorRef; box fillRef |])
            let writerWakeRef =
                if writerRef = 0u then 0u
                else terminalFlowMintedRefOf "writer_wake_receipt_ref" (FastRuntimeFormat.format "writer=%u|owner=%u|ivar=%u" [| box writerRef; box ownerClosureRef; box outcomeIvarFillRef |])
            let originRunEndRef =
                match request.origin with
                | TerminalFlowGlobalExitFromBreakthroughDone proof when proof.runEndReceiptRef <> 0u -> proof.runEndReceiptRef
                | TerminalFlowGlobalExitFromTypedFailure failureReceiptRef when terminalFlowDurableRefValue failureReceiptRef <> 0u ->
                    terminalFlowMintedRefOf
                        "run_end_receipt_ref"
                        (FastRuntimeFormat.format "typed_failure|request=%s|failure=%u|exit=%u|vector=%u" [| box request.requestId; box (terminalFlowDurableRefValue failureReceiptRef); box exitRef; box projection.receiptVectorHash |])
                | _ -> 0u
            let runEndRef =
                match DiagJson.terminalFlowRunEndDurableReceiptRefNow() with
                | Some canonicalRunEndRef when canonicalRunEndRef <> 0u -> canonicalRunEndRef
                | _ -> originRunEndRef
            let seal =
                { sealId = "breakthrough-seal:" + request.requestId
                  rootReceiptRef = rootRef
                  terminalReceiptRef = terminalRef
                  fillRef = fillRef
                  dispatchRef = dispatchRef
                  actorRef = actorRef
                  ownerClosureCertificateRef = ownerClosureRef
                  outcomeIvarFillRef = outcomeIvarFillRef
                  schedulerPushReceiptRef = schedulerPushRef
                  writerWakeReceiptRef = writerWakeRef
                  writerCapabilityRef = writerRef
                  artifactReceiptRef = artifactRef
                  failureRef = failureRef
                  exitWitnessRef = exitRef
                  stageCapabilityRef = projection.stageCapabilityRef
                  receiptProjectionRef = receiptProjection.projectionRef
                  causalSpineRef = causalRef
                  runEndReceiptRef = runEndRef
                  legacyState = TerminalFlowLegacyAuthorityQuarantined }
            let authorityPath =
                match chain with
                | TerminalFlowPhysicalExitWriterCommitted(writerCapabilityRef, artifactReceiptRef, _) when writerWakeRef <> 0u ->
                    Some (TerminalFlowTerminalAuthorityWriterPath(TerminalFlowDurableRef writerWakeRef, writerCapabilityRef, artifactReceiptRef))
                | TerminalFlowPhysicalExitTypedFailure(failureRef, _) ->
                    Some (TerminalFlowTerminalAuthorityFailurePath failureRef)
                | _ -> None
            let originMatchesPhysicalChain =
                match request.origin, chain with
                | TerminalFlowGlobalExitFromBreakthroughDone proof, TerminalFlowPhysicalExitWriterCommitted(writerCapabilityRef, artifactReceiptRef, exitWitnessRef) ->
                    proof.runEndReceiptRef <> 0u
                    && proof.artifactReceiptRef = terminalFlowDurableRefValue artifactReceiptRef
                    && proof.exitWitnessRef = terminalFlowDurableRefValue exitWitnessRef
                    && proof.writerJobRef <> 0u
                    && terminalFlowDurableRefValue writerCapabilityRef <> 0u
                | TerminalFlowGlobalExitFromTypedFailure failureReceiptRef, TerminalFlowPhysicalExitTypedFailure(failureRef, _) ->
                    terminalFlowDurableRefValue failureReceiptRef <> 0u
                    && terminalFlowDurableRefValue failureReceiptRef = terminalFlowDurableRefValue failureRef
                | _ -> false
            let sealReady =
                match chain with
                | TerminalFlowPhysicalExitWriterCommitted _ -> terminalFlowEndToEndSealReady seal
                | TerminalFlowPhysicalExitTypedFailure _ ->
                    seal.rootReceiptRef <> 0u
                    && seal.actorRef <> 0u
                    && seal.failureRef <> 0u
                    && seal.exitWitnessRef <> 0u
                    && seal.stageCapabilityRef <> 0u
                    && seal.receiptProjectionRef <> 0u
                    && seal.causalSpineRef <> 0u
                    && seal.runEndReceiptRef <> 0u
            let allowed =
                originMatchesPhysicalChain
                && sealReady
                && match chain with
                   | TerminalFlowPhysicalExitWriterCommitted _ ->
                       dispatchReady
                       && fillRef <> 0u
                       && actorFillRef = fillRef
                       && projection.stageCapabilityTag = TerminalFlowKernelStageExitWitnessed
                   | TerminalFlowPhysicalExitTypedFailure _ ->
                       rootRef <> 0u
                       && failureRef <> 0u
                       && exitRef <> 0u
                       && request.exitCode <> 0
                       && request.finalActorPhase = DiagJson.PushActorFailedClosed
