        let private terminalFlowGlobalCausalSpineSummary spine =
            let nodes = ResizeArray<TerminalFlowGlobalCausalSpine>()
            let mutable current = spine
            let mutable walking = true
            while walking do
                match current with
                | TerminalFlowGlobalCausalGenesis ->
                    walking <- false
                | TerminalFlowGlobalRootReceiptStep(_, prior) as node ->
                    nodes.Add node
                    current <- prior
                | TerminalFlowGlobalOutcomeReceiptStep(_, _, prior) as node ->
                    nodes.Add node
                    current <- prior
                | TerminalFlowGlobalDispatchStep(_, _, prior) as node ->
                    nodes.Add node
                    current <- prior
                | TerminalFlowGlobalActorStep(_, _, prior) as node ->
                    nodes.Add node
                    current <- prior
                | TerminalFlowGlobalCommitStep(_, _, prior) as node ->
                    nodes.Add node
                    current <- prior
                | TerminalFlowGlobalExitStep(_, _, prior) as node ->
                    nodes.Add node
                    current <- prior
                | TerminalFlowGlobalProgressStep(_, prior) as node ->
                    nodes.Add node
                    current <- prior
                | TerminalFlowGlobalTopologyGateStep(_, prior) as node ->
                    nodes.Add node
                    current <- prior
                | TerminalFlowGlobalWatchdogPetitionStep(_, prior) as node ->
                    nodes.Add node
                    current <- prior
                | TerminalFlowGlobalQapFixpointStep(_, _, prior) as node ->
                    nodes.Add node
                    current <- prior
                | TerminalFlowGlobalQapWatchRebaseStep(_, _, _, _, _, _, _, _, _, prior) as node ->
                    nodes.Add node
                    current <- prior
                | TerminalFlowGlobalOwnerDebtStep(_, prior) as node ->
                    nodes.Add node
                    current <- prior

            let mutable digest = 2166136261u
            for index = nodes.Count - 1 downto 0 do
                match nodes.[index] with
                | TerminalFlowGlobalCausalGenesis -> ()
                | TerminalFlowGlobalRootReceiptStep(receiptRef, _) ->
                    digest <- (digest * 16777619u) ^^^ terminalFlowIdentityRefDigest receiptRef ^^^ 1u
                | TerminalFlowGlobalOutcomeReceiptStep(terminalRef, fillRef, _) ->
                    digest <- (digest * 16777619u) ^^^ terminalFlowIdentityRefDigest terminalRef ^^^ terminalFlowIdentityRefDigest fillRef ^^^ 2u
                | TerminalFlowGlobalDispatchStep(dispatchRef, fillRef, _) ->
                    digest <- (digest * 16777619u) ^^^ terminalFlowIdentityRefDigest dispatchRef ^^^ terminalFlowIdentityRefDigest fillRef ^^^ 3u
                | TerminalFlowGlobalActorStep(phaseRef, fillRef, _) ->
                    digest <- (digest * 16777619u) ^^^ terminalFlowDurableRefValue phaseRef ^^^ terminalFlowIdentityRefDigest fillRef ^^^ 4u
                | TerminalFlowGlobalCommitStep(artifactReceiptRef, runEndReceiptRef, _) ->
                    digest <- (digest * 16777619u) ^^^ terminalFlowDurableRefValue artifactReceiptRef ^^^ terminalFlowDurableRefValue runEndReceiptRef ^^^ 5u
                | TerminalFlowGlobalExitStep(exitRef, fillRef, _) ->
                    digest <- (digest * 16777619u) ^^^ terminalFlowDurableRefValue exitRef ^^^ terminalFlowIdentityRefDigest fillRef ^^^ 6u
                | TerminalFlowGlobalProgressStep(snapshotRef, _) ->
                    digest <- (digest * 16777619u) ^^^ terminalFlowIdentityRefDigest snapshotRef ^^^ 7u
                | TerminalFlowGlobalTopologyGateStep(gateRef, _) ->
                    digest <- (digest * 16777619u) ^^^ terminalFlowIdentityRefDigest gateRef ^^^ 8u
                | TerminalFlowGlobalWatchdogPetitionStep(petitionRef, _) ->
                    digest <- (digest * 16777619u) ^^^ terminalFlowIdentityRefDigest petitionRef ^^^ 9u
                | TerminalFlowGlobalQapFixpointStep(fixpointRef, materialAgeMs, _) ->
                    digest <- (digest * 16777619u) ^^^ terminalFlowDurableRefValue fixpointRef ^^^ uint32 materialAgeMs ^^^ 8u
                | TerminalFlowGlobalQapWatchRebaseStep(fixpointRef, fromSemanticEpoch, toSemanticEpoch, fromFrontierEpoch, toFrontierEpoch, frontierProgressBp, fromCompletionEpoch, toCompletionEpoch, completedCost, _) ->
                    digest <-
                        (digest * 16777619u)
                        ^^^ terminalFlowDurableRefValue fixpointRef
                        ^^^ uint32 fromSemanticEpoch
                        ^^^ uint32 toSemanticEpoch
                        ^^^ uint32 fromFrontierEpoch
                        ^^^ uint32 toFrontierEpoch
                        ^^^ uint32 frontierProgressBp
                        ^^^ uint32 fromCompletionEpoch
                        ^^^ uint32 toCompletionEpoch
                        ^^^ uint32 completedCost
                        ^^^ 9u
                | TerminalFlowGlobalOwnerDebtStep(ownerDebtRef, _) ->
                    digest <- (digest * 16777619u) ^^^ terminalFlowDurableRefValue ownerDebtRef ^^^ 10u
            nodes.Count, digest

