            let queueRecoveryKey =
                match state.queueRecovery.decision with
                | TerminalFlowQueueRecoveryAwaitingEvidence -> "awaiting_evidence"
                | TerminalFlowQueueRecoveryHeldByFairness hold ->
                    FastRuntimeFormat.format "held:%u:%s:completion=%b" [| box (terminalFlowIdentityRefDigest hold.requirementRef); box (terminalFlowFairnessHoldReasonText hold.reason); box hold.basisRef.IsSome |]
                | TerminalFlowQueueRecoveryReadyForReducerSeal certificate ->
                    sprintf "ready:%u" (terminalFlowIdentityRefDigest certificate.recoveryRef)
                | TerminalFlowQueueRecoveryRejectedByProgressRegression _ -> queueRecoveryText
            let _, shouldEmitQueueRecovery = DiagJson.sparseLogDecision ("queue_recovery_projection|" + queueRecoveryKey) 256L
            if shouldEmitQueueRecovery then
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_queue_recovery_projection\",\"decision_du\":%s,\"folded_at_revision\":%d,\"exact_once_ref\":%u,\"sparse_policy\":\"state_change_first3_power2_every256\",\"authority\":\"single_reducer_queue_recovery\"}" [| box (DiagJson.esc queueRecoveryText); box (state.queueRecovery.foldedAtRevision |> Option.defaultValue -1L); box state.queueRecovery.exactOnceRef |])
            let postCommitStage, postCommitPlanRef, postCommitTransactionRef, postCommitOrdinal, postCommitMissingEvidenceCount =
                terminalFlowQapPostCommitStateProjection state.qapPostCommit
            let postCommitStageText = terminalFlowQapPostCommitStageText postCommitStage
            let postCommitEligibility =
                match state.qapPostCommit with
                | TerminalFlowQapPostCommitIdle
                    when DiagJson.terminalFailureExitRequestedNow()
                         || DiagJson.nativePromiseFailureClosedNow() ->
                    TerminalFlowQapPostCommitSuppressedByTypedFailure
                | TerminalFlowQapPostCommitIdle ->
                    TerminalFlowQapPostCommitNotEligibleYet
                | TerminalFlowQapPostCommitAwaitingEvidence _ ->
                    TerminalFlowQapPostCommitAwaitingCertifiedEvidence
                | TerminalFlowQapPostCommitApplied _ ->
                    TerminalFlowQapPostCommitAppliedPlan
                | _ ->
                    TerminalFlowQapPostCommitActivePlan
            let postCommitEligibilityText =
                terminalFlowQapPostCommitEligibilityText postCommitEligibility
            let fairnessAdmissionRef, fairnessAdmissionIdentityRef, fairnessActorBindingRef, fairnessCredentialLedgerRef, fairnessEpochRef, fairnessLineageMissingText =
                match state.replayFairness.lastSample with
                | Some sample ->
                    let lineageInspection = terminalFlowSchedulerLineageInspection sample
                    sample.admissionRef,
                    sample.admissionIdentityRef,
                    sample.actorBindingRef,
                    sample.credentialLedgerRef,
                    terminalFlowIdentityRefDigest sample.fairnessEpochRef,
                    terminalFlowSchedulerLineageInspectionText lineageInspection
                | None -> 0u, 0u, 0u, 0u, 0u, "sample_missing"
            let fairnessReleaseReceiptRef =
                state.replayFairness.releaseReceipt
                |> Option.map (fun receipt -> terminalFlowIdentityRefDigest receipt.releaseRef)
                |> Option.defaultValue 0u
            let schedulerLeaseText =
                state.replayFairness.schedule.schedulerLease
                |> Option.map terminalFlowAdmissionSchedulerLeaseText
                |> Option.defaultValue "none"
            let pendingTerminalRef, pendingFillRef =
                match state.pendingTerminal with
                | TerminalFlowPendingSlotCandidate pending -> terminalFlowPendingTerminalRef pending, terminalFlowIdentityRefDigest pending.fillRef
                | TerminalFlowPendingSlotAwaitingCandidate -> 0u, 0u
            let writerLeaseRef, exactOnceWakerEdgeRef = terminalFlowResidualGreenPathCovenantRefs state.greenPath
            let ownerWorkDagPresent = state.ownerWorkDagProducer.IsSome
            let residualCloseDecisionPresent = state.residualWorkDagCloseDecision.IsSome
            let proofDecisionText, proofMissingEvidenceText, qapSccCertificateRef, qapSccGenerationRef, postCommitProofRef, postCommitProofExactOnceRef =
                match state.qapPostCommit with
                | TerminalFlowQapPostCommitAwaitingEvidence awaiting ->
                    "MissingEvidence", terminalFlowQapMissingEvidenceText awaiting.missingEvidence, 0u, 0u, awaiting.proofRef, awaiting.exactOnceRef
                | TerminalFlowQapPostCommitFairnessScheduled envelope -> terminalFlowQapPostCommitProofProjection envelope.proof
                | TerminalFlowQapPostCommitRecoveryScheduled envelope -> terminalFlowQapPostCommitProofProjection envelope.proof
                | TerminalFlowQapPostCommitOwnerWorkDagScheduled envelope -> terminalFlowQapPostCommitProofProjection envelope.proof
                | TerminalFlowQapPostCommitApplied envelope -> terminalFlowQapPostCommitProofProjection envelope.proof
                | TerminalFlowQapPostCommitIdle -> "Nothing", "post_commit_idle", 0u, 0u, 0u, 0u
            let postCommitProofDepth = terminalFlowQapPostCommitProofDepth state.qapPostCommit
            let postCommitMissingEvidenceRef =
                terminalFlowMintedRefOf "terminal_qap_post_commit_missing_evidence_ref" proofMissingEvidenceText
            let postCommitKey =
                FastRuntimeFormat.format "%s:%s:%u:%u:%d:%u:%s:%u:%u:%u:dispatch_lifecycle=%d:%u" [| box postCommitStageText; box postCommitEligibilityText; box postCommitPlanRef; box postCommitTransactionRef; box postCommitOrdinal; box postCommitMissingEvidenceRef; box schedulerLeaseText; box postCommitProofRef; box qapSccCertificateRef; box qapSccGenerationRef; box dispatchLifecycleProjectionRank; box dispatchLifecycleProjectionRef |]
            let postCommitOccurrence, shouldEmitPostCommit = DiagJson.sparseLogDecision ("qap_post_commit_projection|" + postCommitKey) 256L
            if shouldEmitPostCommit then
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_qap_post_commit_projection\",\"stage_du\":%s,\"eligibility_du\":%s,\"plan_ref\":%u,\"plan_ref_present\":%b,\"finalization_transaction_id\":%u,\"stage_ordinal\":%d,\"dispatch_lifecycle_rank\":%d,\"dispatch_lifecycle_ref\":%u,\"missing_evidence_count\":%d,\"missing_evidence_du\":%s,\"missing_evidence_ref\":%u,\"proof_state_repeat_count\":%d,\"fairness_lineage\":{\"admission_ref\":%u,\"admission_identity_ref\":%u,\"actor_binding_ref\":%u,\"credential_ledger_ref\":%u,\"fairness_epoch_ref\":%u},\"lineage_ready\":%b,\"lineage_missing_du\":%s,\"scheduler_lease_du\":%s,\"release_receipt_ref\":%u,\"pending_terminal_receipt_ref\":%u,\"pending_fill_ref\":%u,\"green_path_present\":%b,\"writer_lease_ref\":%u,\"exact_once_waker_edge_ref\":%u,\"owner_workdag_present\":%b,\"residual_close_decision_present\":%b,\"queue_recovery_du\":%s,\"proof_decision_du\":%s,\"proof_depth\":%d,\"post_commit_proof_ref\":%u,\"post_commit_proof_exact_once_ref\":%u,\"qap_scc_certificate_ref\":%u,\"qap_scc_generation_ref\":%u,\"reducer_revision\":%d,\"authority\":\"single_reducer_recursive_post_commit_proof\"}" [| box (DiagJson.esc postCommitStageText); box (DiagJson.esc postCommitEligibilityText); box postCommitPlanRef; box (postCommitPlanRef <> 0u); box postCommitTransactionRef; box postCommitOrdinal; box dispatchLifecycleProjectionRank; box dispatchLifecycleProjectionRef; box postCommitMissingEvidenceCount; box (DiagJson.esc proofMissingEvidenceText); box postCommitMissingEvidenceRef; box postCommitOccurrence; box fairnessAdmissionRef; box fairnessAdmissionIdentityRef; box fairnessActorBindingRef; box fairnessCredentialLedgerRef; box fairnessEpochRef; box (String.IsNullOrWhiteSpace fairnessLineageMissingText); box (DiagJson.esc fairnessLineageMissingText); box (DiagJson.esc schedulerLeaseText); box fairnessReleaseReceiptRef; box pendingTerminalRef; box pendingFillRef; box state.greenPath.IsSome; box writerLeaseRef; box exactOnceWakerEdgeRef; box ownerWorkDagPresent; box residualCloseDecisionPresent; box (DiagJson.esc queueRecoveryText); box (DiagJson.esc proofDecisionText); box postCommitProofDepth; box postCommitProofRef; box postCommitProofExactOnceRef; box qapSccCertificateRef; box qapSccGenerationRef; box state.revision |])
            match state.watchdogPetition with
            | TerminalFlowWatchdogPending petition ->
                terminalFlowEmitTypedDiagnostic (TerminalFlowDiagnosticWatchdogPetition petition)
            | TerminalFlowWatchdogConsumed(petition, consumedAtRevision) ->
                DiagJson.emitTerminalJsonDurable (
                    sprintf "{\"kind\":\"terminal_watchdog_petition_consumed\",\"petition_ref\":%u,\"consumed_at_revision\":%d,\"terminal_authority\":false,\"authority\":\"single_reducer_petition_lane\"}"
                        (terminalFlowIdentityRefDigest petition.petitionRef)
                        consumedAtRevision)
            | TerminalFlowWatchdogIdle -> ()

        let private terminalFlowGlobalCausalStep event prior =
            match event with
            | TerminalFlowGlobalServerEvaluatorRootResolved(receiptId, _, _, _) ->
                TerminalFlowGlobalRootReceiptStep(terminalFlowIdentityRefOfText receiptId, prior)
            | TerminalFlowGlobalServerTerminalOutcomeReady pending ->
                TerminalFlowGlobalOutcomeReceiptStep(pending.terminalReceiptRef, pending.fillRef, prior)
            | TerminalFlowGlobalServerDispatchRequested request ->
                TerminalFlowGlobalDispatchStep(terminalFlowIdentityRefOfText request.requestId, terminalFlowIdentityRefOfText (terminalFlowDispatchJoinFillText request.joinKey), prior)
            | TerminalFlowGlobalServerDispatchExecuted(issuance, handoff) ->
                TerminalFlowGlobalDispatchStep(
                    terminalFlowIdentityRefOfText (string issuance.issuanceRef),
                    terminalFlowIdentityRefOfText (string (terminalFlowStableAuthorityRef (TerminalFlowNativeHandoffIdentity handoff))),
                    prior)
            | TerminalFlowGlobalServerQapFixpointObserved(fixpointRef, _, materialAgeMs, _) ->
                TerminalFlowGlobalQapFixpointStep(fixpointRef, materialAgeMs, prior)
            | TerminalFlowGlobalServerQapPostCommitEffectCompleted completion ->
                let stageResultRef (result:TerminalFlowQapPostCommitStageResult<'Stage>) : uint32 =
                    match result with
                    | Ok envelope -> envelope.planRef
                    | Error missingEvidence ->
                        terminalFlowMintedRefOf
                            "terminal_qap_missing_evidence_causal_ref"
                            (terminalFlowQapMissingEvidenceText missingEvidence)
                let planRef =
                    match completion with
                    | TerminalFlowQapPostCommitFairnessCompleted result -> stageResultRef result
                    | TerminalFlowQapPostCommitRecoveryCompleted result -> stageResultRef result
                    | TerminalFlowQapPostCommitOwnerWorkDagCompleted result -> stageResultRef result
                TerminalFlowGlobalOwnerDebtStep(TerminalFlowDurableRef planRef, prior)
            | TerminalFlowGlobalServerQapWatchRebaseRequested request ->
                TerminalFlowGlobalQapWatchRebaseStep(
                    request.fixpointRef,
                    request.fromSemanticEpoch,
                    request.toSemanticEpoch,
                    request.fromFrontierEpoch,
                    request.toFrontierEpoch,
                    request.frontierProgressBp,
                    request.fromCompletionEpoch,
                    request.toCompletionEpoch,
                    request.completedCost,
                    prior)
            | TerminalFlowGlobalServerCicKernelProofObserved authority ->
                TerminalFlowGlobalOwnerDebtStep(
                    TerminalFlowDurableRef(terminalFlowMintedRefOf "cic_kernel_proof_causal_ref" (terminalFlowKernelProofAuthorityText authority)),
                    prior)
            | TerminalFlowGlobalServerStageTokenIssued issued ->
                let receipt = issued.issueReceipt
                TerminalFlowGlobalActorStep(
                    TerminalFlowDurableRef issued.issueEventRef,
                    terminalFlowIdentityRefOfText (string receipt.fillRef),
                    TerminalFlowGlobalDispatchStep(
                        terminalFlowIdentityRefOfText (string issued.transaction.transactionRef),
                        terminalFlowIdentityRefOfText (string issued.transaction.actorLease.leaseRef),
                        prior))
            | TerminalFlowGlobalServerStageTokenFillCommitted filled ->
                let receipt = filled.fillReceipt
                TerminalFlowGlobalActorStep(
                    TerminalFlowDurableRef filled.fillEventRef,
                    terminalFlowIdentityRefOfText (string receipt.fillRef),
                    TerminalFlowGlobalDispatchStep(
                        terminalFlowIdentityRefOfText (string filled.issued.transaction.transactionRef),
                        terminalFlowIdentityRefOfText (string filled.issued.transaction.actorLease.leaseRef),
                        prior))
            | TerminalFlowGlobalServerStageTokenSealAuthorized sealAuthorization ->
                let receipt = sealAuthorization.authorizationReceipt
                TerminalFlowGlobalCommitStep(
                    TerminalFlowDurableRef receipt.fillCommitReceiptRef,
                    TerminalFlowDurableRef receipt.receiptRef,
                    TerminalFlowGlobalActorStep(
                        TerminalFlowDurableRef sealAuthorization.authorizationEventRef,
                        terminalFlowIdentityRefOfText (string receipt.fillRef),
                        prior))
            | TerminalFlowGlobalServerStageTokenFailedClosed receipt ->
                TerminalFlowGlobalActorStep(
                    TerminalFlowDurableRef receipt.failureRef,
                    terminalFlowIdentityRefOfText (string receipt.fillRef),
                    prior)
            | TerminalFlowGlobalServerActorProjectionObserved _ -> prior
            | TerminalFlowGlobalServerArtifactCommitObserved commit ->
                TerminalFlowGlobalCommitStep(commit.artifactReceiptRef, commit.runEndReceiptRef, prior)
            | TerminalFlowGlobalServerExitWitnessReady request ->
                TerminalFlowGlobalExitStep(TerminalFlowDurableRef(terminalFlowPhysicalExitChainExitWitnessRef request.physicalChain), terminalFlowIdentityRefOfText request.fillKey, prior)
            | TerminalFlowGlobalServerProgressEvidenceObserved evidence ->
                TerminalFlowGlobalProgressStep(evidence.snapshotRef, prior)
            | TerminalFlowGlobalServerTopologyGateTransitionObserved transition ->
                TerminalFlowGlobalTopologyGateStep(transition.gateRef, prior)
            | TerminalFlowGlobalServerReplayFairnessObserved sample ->
                TerminalFlowGlobalTopologyGateStep(
                    terminalFlowIdentityRefOfText (sprintf "fairness-causal:%u" (terminalFlowIdentityRefDigest sample.sampleRef)),
                    prior)
            | TerminalFlowGlobalServerAdmissionRunEndFixtureProven _ ->
                // Fixture evidence is an audit gate only.  It must not mutate the
                // live causal spine, green path, actor authority or terminal order.
                prior
            | TerminalFlowGlobalServerQueueOnlyRecoveryFolded decision ->
                TerminalFlowGlobalOwnerDebtStep(
                    TerminalFlowDurableRef(terminalFlowMintedRefOf "queue_recovery_folded_ref" (terminalFlowQueueRecoveryDecisionText decision)),
                    prior)
            | TerminalFlowGlobalServerWatchdogPetitioned petition ->
                TerminalFlowGlobalWatchdogPetitionStep(petition.petitionRef, prior)
            | TerminalFlowGlobalServerHostShutdownRequested request ->
                TerminalFlowGlobalOwnerDebtStep(
                    TerminalFlowDurableRef(terminalFlowIdentityRefDigest request.requestRef),
                    prior)
            | TerminalFlowGlobalServerOwnerWorkDagProduced producer ->
                let authorityRef =
                    match terminalFlowOwnerWorkDagProducedAuthorities producer with
                    | Some certificate, Some proof, _, _ -> terminalFlowMintedRefOf "owner_workdag_causal_ref" (sprintf "%u:%u" certificate.certificateRef (terminalFlowWorkDagTailRef proof.workDagTail))
                    | _ -> terminalFlowMintedRefOf "owner_workdag_causal_ref" (terminalFlowOwnerWorkDagProducerText producer)
                TerminalFlowGlobalOwnerDebtStep(TerminalFlowDurableRef authorityRef, prior)
            | TerminalFlowGlobalServerTerminalOrderCutoverObserved cutover ->
                TerminalFlowGlobalCommitStep(
                    TerminalFlowDurableRef(terminalFlowMintedRefOf "terminal_order_cutover_ref" (terminalFlowTerminalOrderCutoverText cutover)),
                    TerminalFlowDurableRef(terminalFlowMintedRefOf "terminal_order_total_ref" (terminalFlowTerminalOrderCutoverText cutover)),
                    prior)
            | TerminalFlowGlobalServerTerminalOrderCutoverMinted receipt ->
                TerminalFlowGlobalCommitStep(
                    TerminalFlowDurableRef receipt.receiptRef,
                    TerminalFlowDurableRef(terminalFlowMintedRefOf "terminal_order_minter_total_ref" (terminalFlowTerminalOrderMinterReceiptText receipt)),
                    prior)
            | TerminalFlowGlobalServerProjectionCoalesced directive ->
                TerminalFlowGlobalProgressStep(
                    terminalFlowIdentityRefOfText (sprintf "projection-coalesced:%u" directive.compactPayloadRef),
                    prior)
            | TerminalFlowGlobalServerCriticalPathEtaObserved eta ->
                TerminalFlowGlobalProgressStep(
                    terminalFlowIdentityRefOfText (sprintf "critical-path-eta:%u" eta.etaRef),
                    prior)
            | TerminalFlowGlobalServerCompactHudPaneProjected pane ->
                TerminalFlowGlobalProgressStep(
                    terminalFlowIdentityRefOfText (sprintf "compact-hud-pane:%u" pane.paneRef),
                    prior)
            | TerminalFlowGlobalServerEvalWorklistShimDemoted shim ->
                TerminalFlowGlobalOwnerDebtStep(
                    TerminalFlowDurableRef shim.shimRef,
                    prior)
            | TerminalFlowGlobalServerSemanticFactMinted fact ->
                TerminalFlowGlobalProgressStep(
                    terminalFlowIdentityRefOfText (sprintf "semantic-fact:%u" fact.payloadRef),
                    prior)
            | TerminalFlowGlobalServerNativeEvalNoFactRejected _ ->
                TerminalFlowGlobalOwnerDebtStep(
                    TerminalFlowDurableRef(terminalFlowMintedRefOf "native_eval_no_fact_rejection_ref" (terminalFlowGlobalServerEventText event)),
                    prior)
            | TerminalFlowGlobalServerSchedulerSpawnGrantObserved grant ->
                TerminalFlowGlobalProgressStep(
                    terminalFlowIdentityRefOfText (sprintf "scheduler-spawn-grant:%u" grant.grantRef),
                    prior)
            | TerminalFlowGlobalServerCicKernelWorkObserved counters ->
                TerminalFlowGlobalProgressStep(
                    terminalFlowIdentityRefOfText (sprintf "cic-kernel-counter:%u" (terminalFlowMintedRefOf "cic_kernel_counter_ref" (FastRuntimeFormat.format "%d:%d:%d:%d" [| box counters.kernelTermCount; box counters.defeqSolvedCount; box counters.universeConstraintCount; box counters.universeSolverIterations |]))),
                    prior)
            | TerminalFlowGlobalServerCicActorStepObserved(ownerRef, step) ->
                TerminalFlowGlobalProgressStep(
                    terminalFlowIdentityRefOfText (FastRuntimeFormat.format "cic-actor-step:%u:%s" [| box (CompilerKernelV2.NonZeroRef.value ownerRef); box (terminalFlowCicActorStepKind step |> terminalFlowCicActorStepKindText) |]),
                    prior)
            | TerminalFlowGlobalServerCicActorCloseRequested(ownerRef, sealRef) ->
                TerminalFlowGlobalProgressStep(
                    terminalFlowIdentityRefOfText (FastRuntimeFormat.format "cic-actor-close:%u:%u" [| box (CompilerKernelV2.NonZeroRef.value ownerRef); box sealRef |]),
                    prior)
            | TerminalFlowGlobalServerHvmLoweringPrepared lowering ->
                TerminalFlowGlobalProgressStep(
                    terminalFlowIdentityRefOfText (sprintf "hvm-interaction-graph:%u" lowering.interactionGraphRef),
                    prior)
            | TerminalFlowGlobalServerBreakthroughTransitionObserved receipt ->
                TerminalFlowGlobalProgressStep(
                    terminalFlowIdentityRefOfText (sprintf "breakthrough-transition:%u" (TerminalFlowBreakthrough.transitionRefOf receipt)),
                    prior)
            | TerminalFlowGlobalServerLegacyTerminalAuthorityDemoted demotion ->
                TerminalFlowGlobalOwnerDebtStep(
                    TerminalFlowDurableRef(terminalFlowMintedRefOf "legacy_terminal_authority_demotion_ref" (terminalFlowLegacyTerminalAuthorityDemotionText demotion)),
                    prior)
            | TerminalFlowGlobalServerObserverExitPetitioned petition ->
                let ownerAuthorityRef = DiagJson.observerTerminalOwnerClosureAuthorityRef petition.ownerClosureAuthority
                TerminalFlowGlobalExitStep(
                    TerminalFlowDurableRef petition.petitionRef,
                    terminalFlowIdentityRefOfText (sprintf "observer-petition-fill:%u" petition.terminalReceiptRef),
                    TerminalFlowGlobalOwnerDebtStep(
                        TerminalFlowDurableRef ownerAuthorityRef,
                        TerminalFlowGlobalOwnerDebtStep(
                            TerminalFlowDurableRef petition.ownerClosureRef,
                            TerminalFlowGlobalProgressStep(
                                terminalFlowIdentityRefOfText (FastRuntimeFormat.format "observer-petition-covenant:%u:%u:%u" [| box petition.workDagClosureRef; box petition.schedulerCausalityRef; box petition.semanticDebtRef |]),
                                prior))))
            | TerminalFlowGlobalServerTypedSemanticIngressObserved envelope ->
                TerminalFlowGlobalProgressStep(
                    terminalFlowIdentityRefOfText (sprintf "typed-semantic-ingress:%u:%u" envelope.ingressRef envelope.authorityWitnessRef),
                    prior)
            | TerminalFlowGlobalServerDeadmanExpired ageMs ->
                TerminalFlowGlobalWatchdogPetitionStep(
                    terminalFlowIdentityRefOfText (sprintf "legacy-deadman-adapter:%d" ageMs),
                    prior)
            | TerminalFlowGlobalServerOwnerDebtObserved(_, _, decisionRef, _, _) ->
                TerminalFlowGlobalOwnerDebtStep(TerminalFlowDurableRef decisionRef, prior)

        let private terminalFlowGreenPathEnsureClosedWorld
            (pendingTerminal:TerminalFlowPendingSlot)
            (progressAuthority:TerminalFlowReducerProgressAuthority)
            (current:TerminalFlowGreenPathLinearState option) =
            match current, pendingTerminal, progressAuthority.accepted with
            | None, TerminalFlowPendingSlotCandidate pending, Some evidence
                when pending.intent = TerminalFlowPendingBuildOk ->
                match terminalFlowProgressEvidenceRefreshOperationalAuthority evidence with
                | Some closedWorld ->
                    let tx = terminalFlowForceOwnerCloseTransactionForClosedWorld closedWorld pending
                    let opened = terminalFlowGreenPathOpenFor (TerminalFlowFillKeyId.ofRef pending.fillRef) tx
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format
                            "{\"kind\":\"terminal_green_path_opened_from_operational_graph_quiescence\",\"pending_ref\":%u,\"fill_ref\":%u,\"progress_snapshot_ref\":%u,\"work_ledger_ref\":%u,\"operational_graph_open_count\":%d,\"operational_graph_suspended_count\":%d,\"execution_attempt_count\":%d,\"authority\":\"typed_operational_graph_closed_world_refresh\",\"next\":\"mint_recursive_dispatch_proof\"}"
                            [| box (terminalFlowPendingTerminalRef pending)
                               box (terminalFlowIdentityRefDigest pending.fillRef)
                               box (terminalFlowIdentityRefDigest closedWorld.snapshotRef)
                               box (terminalFlowIdentityRefDigest closedWorld.workLedger.ledgerRef)
                               box closedWorld.workLedger.operationalGraphOpenCount
                               box closedWorld.workLedger.operationalGraphSuspendedCount
                               box closedWorld.workLedger.executionAttemptCount |])
                    Some opened
                | None -> current
            | _ -> current

        let private terminalFlowGreenPathAdvance
            (state:TerminalFlowGlobalReducerState)
            (event:TerminalFlowGlobalServerEvent)
            : TerminalFlowGreenPathLinearState option =
            let current = state.greenPath
            let rejectFrom (fillKey:TerminalFlowFillKeyId) reason prior =
                let reasonText = terminalFlowGreenPathRejectReasonText reason
                let predecessor = prior |> Option.map terminalFlowGreenPathReceiptRef
                let fillKeyText = TerminalFlowFillKeyId.text fillKey
                let receipt : TerminalFlowGreenPathReceipt<TerminalFlowGreenPathRejectedStage> =
                    { receiptRef = terminalFlowMintedRefOf "green_path_rejected_ref" (fillKeyText + ":" + reasonText)
                      predecessorRef = predecessor
                      fillKey = fillKey
                      exactOnce = true }
                Some (TerminalFlowGreenPathRejected(receipt, reason))
            match event, current with
            | TerminalFlowGlobalServerProgressEvidenceObserved evidence, None
                when terminalFlowProgressEvidenceIsExactClosedWorld evidence ->
                match state.pendingTerminal with
                | TerminalFlowPendingSlotCandidate pending when pending.intent = TerminalFlowPendingBuildOk ->
                    let tx = terminalFlowForceOwnerCloseTransactionForClosedWorld evidence pending
                    Some (terminalFlowGreenPathOpenFor (TerminalFlowFillKeyId.ofRef pending.fillRef) tx)
                | TerminalFlowPendingSlotCandidate _
                | TerminalFlowPendingSlotAwaitingCandidate -> current
            | TerminalFlowGlobalServerTerminalOutcomeReady pending, Some (TerminalFlowGreenPathOpen(_, tx)) when pending.intent = TerminalFlowPendingBuildOk ->
                let fillKey = TerminalFlowFillKeyId.ofRef pending.fillRef
                let fillKeyText = TerminalFlowFillKeyId.text fillKey
                let writerReceiptId = "writer-receipt:fill-once-ready:" + fillKeyText + ":" + tx.ownerCloseReceiptId
                let reopened =
                    TerminalFlowGreenPathOpen(
                        { receiptRef = terminalFlowMintedRefOf "green_path_open_ref" (fillKeyText + "|" + tx.ownerCloseReceiptId)
                          predecessorRef = Some tx.fillOnceReadyWitnessRef
                          fillKey = fillKey
                          exactOnce = tx.queueOnlyRecoveryReady },
                        tx)
                match terminalFlowGreenPathBindWriter writerReceiptId reopened with
                | Ok writerBound -> Some writerBound
                | Error missing ->
                    missing
                    |> terminalFlowGreenPathDispatchMissingListText
                    |> CompilerKernelV2.OperationalReasonIdOps.create
                    |> TerminalFlowGreenPathDispatchRejected
                    |> fun reason -> rejectFrom fillKey reason current
            | TerminalFlowGlobalServerArtifactCommitObserved commit, Some (TerminalFlowGreenPathWriterBound(writerReceipt, _, _)) when writerReceipt.fillKey = commit.fillKey ->
                let committed : TerminalFlowGreenPathReceipt<TerminalFlowGreenPathTerminalCommittedStage> =
                    { receiptRef = terminalFlowDurableRefValue commit.artifactReceiptRef
                      predecessorRef = Some writerReceipt.receiptRef
                      fillKey = commit.fillKey
                      exactOnce = true }
                Some (TerminalFlowGreenPathTerminalCommitted(committed, commit.terminalReceiptRef))
            | TerminalFlowGlobalServerExitWitnessReady request, Some (TerminalFlowGreenPathTerminalCommitted(commitReceipt, terminalCommitReceiptId))
                when request.exitCode = 0 && commitReceipt.fillKey = TerminalFlowFillKeyId.ofRef request.fillRef ->
                let requestFillKey = TerminalFlowFillKeyId.ofRef request.fillRef
                let runEnded : TerminalFlowGreenPathReceipt<TerminalFlowGreenPathRunEndedStage> =
                    { receiptRef = terminalFlowPhysicalExitChainExitWitnessRef request.physicalChain
                      predecessorRef = Some commitReceipt.receiptRef
                      fillKey = requestFillKey
                      exactOnce = true }
                Some (TerminalFlowGreenPathRunEnded(runEnded, "run-end:" + terminalFlowIdentityRefText terminalCommitReceiptId))
            | TerminalFlowGlobalServerExitWitnessReady request, Some (TerminalFlowGreenPathRunEnded(runEndReceipt, _))
                when request.exitCode = 0 && runEndReceipt.fillKey = TerminalFlowFillKeyId.ofRef request.fillRef ->
                let requestFillKey = TerminalFlowFillKeyId.ofRef request.fillRef
                let physical : TerminalFlowGreenPathReceipt<TerminalFlowGreenPathPhysicalExitStage> =
                    { receiptRef = terminalFlowMintedRefOf "green_path_physical_exit_ref" (TerminalFlowFillKeyId.text requestFillKey + ":exit0")
                      predecessorRef = Some runEndReceipt.receiptRef
                      fillKey = requestFillKey
                      exactOnce = true }
                Some (TerminalFlowGreenPathPhysicalExit(physical, 0))
            | TerminalFlowGlobalServerExitWitnessReady request, Some state when request.exitCode <> 0 ->
                rejectFrom
                    (TerminalFlowFillKeyId.ofRef request.fillRef)
                    (TerminalFlowGreenPathNonzeroExit request.exitCode)
                    (Some state)
            | _ -> current

        let private terminalFlowTypedTotalOrderAdvance
            (state:TerminalFlowGlobalReducerState)
            (event:TerminalFlowGlobalServerEvent)
            nextRevision
            : TerminalFlowTypedTotalOrder =
            let predecessorRef = terminalFlowTotalOrderReceiptRef state.typedTotalOrder
            let predecessor = if predecessorRef = 0u then None else Some predecessorRef
            let rejected (fillKey:TerminalFlowFillKeyId) reason =
                let reasonText = terminalFlowTotalOrderRejectReasonText reason
                let fillText = TerminalFlowFillKeyId.text fillKey
                let receipt : TerminalFlowTotalOrderReceipt<TerminalOrderRejectedStage> =
                    { orderIndex = nextRevision
                      receiptRef = terminalFlowMintedRefOf "terminal_total_order_rejected_ref" (fillText + ":" + reasonText)
                      predecessorRef = predecessor
                      fillKey = TerminalFlowTotalOrderFillBound fillKey
                      exactOnce = true }
                TerminalFlowTotalOrderRejected(receipt, reason)
            match event with
            | TerminalFlowGlobalServerDispatchRequested request ->
                let fillKey = TerminalFlowFillKeyId.ofRef (terminalFlowDispatchJoinFillRef request.joinKey)
                match state.typedTotalOrder with
                | TerminalFlowTotalOrderAwaitDispatch _ ->
                    let receipt : TerminalFlowTotalOrderReceipt<TerminalOrderDispatchedStage> =
                        { orderIndex = nextRevision
                          receiptRef = terminalFlowMintedRefOf "terminal_total_order_dispatch_ref" request.requestId
                          predecessorRef = predecessor
                          fillKey = TerminalFlowTotalOrderFillBound fillKey
                          exactOnce = true }
                    TerminalFlowTotalOrderDispatched receipt
                | _ ->
                    rejected fillKey TerminalFlowTotalOrderDispatchWithoutAwaitDispatch
            | TerminalFlowGlobalServerTerminalOutcomeReady _ ->
                // A ready outcome is a candidate, not the fill receipt. The typed
                // order advances only after the push actor reports OutcomeFilled.
                state.typedTotalOrder
            | TerminalFlowGlobalServerStageTokenFillCommitted consumed ->
                let fillKey = consumed.issued.transaction.postCommitCapability.pending.fillKeyId
                match state.typedTotalOrder with
                | TerminalFlowTotalOrderDispatched dispatch when terminalFlowTotalOrderFillMatches fillKey dispatch.fillKey ->
                    let receipt : TerminalFlowTotalOrderReceipt<TerminalOrderFilledStage> =
                        { orderIndex = nextRevision
                          receiptRef = terminalFlowMintedRefOf "terminal_total_order_fill_ref" (TerminalFlowFillKeyId.text fillKey)
                          predecessorRef = Some dispatch.receiptRef
                          fillKey = TerminalFlowTotalOrderFillBound fillKey
                          exactOnce = true }
                    TerminalFlowTotalOrderFilled receipt
                | TerminalFlowTotalOrderFilled fill when terminalFlowTotalOrderFillMatches fillKey fill.fillKey ->
                    state.typedTotalOrder
                | _ ->
                    rejected fillKey TerminalFlowTotalOrderConsumeWithoutTypedDispatchPredecessor
            | TerminalFlowGlobalServerActorProjectionObserved _ ->
                // Projection-only events are forbidden from minting total-order authority.
                state.typedTotalOrder
            | TerminalFlowGlobalServerArtifactCommitObserved commit ->
                match state.typedTotalOrder with
                | TerminalFlowTotalOrderFilled fill when terminalFlowTotalOrderFillMatches commit.fillKey fill.fillKey ->
                    let receipt : TerminalFlowTotalOrderReceipt<TerminalOrderCommittedStage> =
                        { orderIndex = nextRevision
                          receiptRef = terminalFlowDurableRefValue commit.runEndReceiptRef
                          predecessorRef = Some fill.receiptRef
                          fillKey = TerminalFlowTotalOrderFillBound commit.fillKey
                          exactOnce = true }
                    TerminalFlowTotalOrderCommitted receipt
                | _ ->
                    rejected commit.fillKey TerminalFlowTotalOrderCommitWithoutTypedFillPredecessor
            | TerminalFlowGlobalServerExitWitnessReady request
                when (match request.origin with TerminalFlowGlobalExitFromTypedFailure _ -> true | _ -> false) ->
                let failureRef =
                    match request.origin with
                    | TerminalFlowGlobalExitFromTypedFailure value -> terminalFlowDurableRefValue value
                    | TerminalFlowGlobalExitFromBreakthroughDone _ -> 0u
                let fillKey = request.fillKeyId
                let receipt : TerminalFlowTotalOrderReceipt<TerminalOrderRejectedStage> =
                    { orderIndex = nextRevision
                      receiptRef = terminalFlowMintedRefOf "terminal_total_order_typed_failure_ref" (request.fillKey + ":" + string failureRef)
                      predecessorRef = predecessor
                      fillKey = TerminalFlowTotalOrderFillBound fillKey
                      exactOnce = true }
                TerminalFlowTotalOrderRejected(
                    receipt,
                    TerminalFlowTotalOrderTypedFailureExit failureRef)
            | TerminalFlowGlobalServerExitWitnessReady request ->
                let fillKey = request.fillKeyId
                match state.typedTotalOrder with
                | TerminalFlowTotalOrderCommitted commit when terminalFlowTotalOrderFillMatches fillKey commit.fillKey ->
                    let doneReceipt : TerminalFlowTotalOrderReceipt<TerminalOrderDoneStage> =
                        { orderIndex = nextRevision
                          receiptRef = terminalFlowPhysicalExitChainExitWitnessRef request.physicalChain
                          predecessorRef = Some commit.receiptRef
                          fillKey = TerminalFlowTotalOrderFillBound fillKey
                          exactOnce = true }
                    TerminalFlowTotalOrderDone doneReceipt
                | TerminalFlowTotalOrderDone doneReceipt when terminalFlowTotalOrderFillMatches fillKey doneReceipt.fillKey ->
                    let runEndReceipt : TerminalFlowTotalOrderReceipt<TerminalOrderRunEndedStage> =
                        { orderIndex = nextRevision
                          receiptRef = terminalFlowMintedRefOf "terminal_total_order_run_end_ref" (request.fillKey + ":" + string (terminalFlowPhysicalExitChainExitWitnessRef request.physicalChain))
                          predecessorRef = Some doneReceipt.receiptRef
                          fillKey = TerminalFlowTotalOrderFillBound fillKey
                          exactOnce = true }
                    TerminalFlowTotalOrderRunEnded runEndReceipt
                | TerminalFlowTotalOrderRunEnded runEndReceipt when terminalFlowTotalOrderFillMatches fillKey runEndReceipt.fillKey ->
                    let physicalReceipt : TerminalFlowTotalOrderReceipt<TerminalOrderPhysicalExitStage> =
                        { orderIndex = nextRevision
                          receiptRef = terminalFlowMintedRefOf "terminal_total_order_physical_exit_ref" (request.fillKey + ":" + string request.exitCode)
                          predecessorRef = Some runEndReceipt.receiptRef
                          fillKey = TerminalFlowTotalOrderFillBound fillKey
                          exactOnce = true }
                    TerminalFlowTotalOrderPhysicalExit physicalReceipt
                | _ ->
                    rejected fillKey TerminalFlowTotalOrderExitWitnessWithoutTypedPredecessor
            | _ -> state.typedTotalOrder

        let private terminalFlowReducerOutcomeAuthorityRef = function
            | TerminalFlowReducerOutcomeAwaitingQap -> 0u
            | TerminalFlowReducerOutcomeProvisional outcome -> outcome.terminalRef
            | TerminalFlowReducerOutcomeFinalDrained outcome -> outcome.terminalRef
            | TerminalFlowReducerOutcomeFinalDeadlocked outcome -> outcome.terminalRef

        let private terminalFlowReducerOutcomeDispatchConsumable = function
            | TerminalFlowReducerOutcomeAwaitingQap -> false
            | TerminalFlowReducerOutcomeProvisional outcome -> outcome.dispatchConsumable
            | TerminalFlowReducerOutcomeFinalDrained outcome -> outcome.dispatchConsumable
            | TerminalFlowReducerOutcomeFinalDeadlocked outcome -> outcome.dispatchConsumable

        let private terminalFlowReducerActorVersion = function
            | TerminalFlowReducerActorVacant wrapped -> (terminalFlowPossessionPayload wrapped).clock.version
            | TerminalFlowReducerActorArmed wrapped -> (terminalFlowPossessionPayload wrapped).clock.version
            | TerminalFlowReducerActorFilled wrapped -> (terminalFlowPossessionPayload wrapped).clock.version
            | TerminalFlowReducerActorSealed wrapped -> (terminalFlowPossessionPayload wrapped).clock.version
            | TerminalFlowReducerActorFailedClosed wrapped -> (terminalFlowPossessionPayload wrapped).clock.version

        let private terminalFlowReducerActorStageTokenRef = function
            | TerminalFlowReducerActorVacant _ -> None
            | TerminalFlowReducerActorArmed wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                Some (terminalFlowAuthorityRefValue actor.issued.tokenRef)
            | TerminalFlowReducerActorFilled wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                Some (terminalFlowAuthorityRefValue actor.armed.issued.tokenRef)
            | TerminalFlowReducerActorSealed wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                Some (terminalFlowAuthorityRefValue actor.filled.armed.issued.tokenRef)
            | TerminalFlowReducerActorFailedClosed wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                match actor.context with
                | TerminalFlowFailureBeforePossession _ -> None
                | TerminalFlowFailureAfterIssue(armed, _, _) -> Some (terminalFlowAuthorityRefValue armed.issued.tokenRef)
                | TerminalFlowFailureAfterFill(filled, _, _) -> Some (terminalFlowAuthorityRefValue filled.armed.issued.tokenRef)

        let private terminalFlowReducerActorConstitutionRef = function
            | TerminalFlowReducerActorVacant _ -> 0u
            | TerminalFlowReducerActorArmed wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                terminalFlowAuthorityRefValue actor.lineage.constitutionRef
            | TerminalFlowReducerActorFilled wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                terminalFlowAuthorityRefValue actor.ratifiedLineage.issuedLineage.constitutionRef
            | TerminalFlowReducerActorSealed wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                terminalFlowAuthorityRefValue actor.filled.ratifiedLineage.issuedLineage.constitutionRef
            | TerminalFlowReducerActorFailedClosed wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                match actor.context with
                | TerminalFlowFailureBeforePossession _ -> 0u
                | TerminalFlowFailureAfterIssue(armed, _, _) -> terminalFlowAuthorityRefValue armed.lineage.constitutionRef
                | TerminalFlowFailureAfterFill(filled, _, _) -> terminalFlowAuthorityRefValue filled.ratifiedLineage.issuedLineage.constitutionRef

        let private terminalFlowReducerActorRatificationRef = function
            | TerminalFlowReducerActorVacant _
            | TerminalFlowReducerActorArmed _ -> 0u
            | TerminalFlowReducerActorFilled wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                terminalFlowAuthorityRefValue actor.ratifiedLineage.ratificationRef
            | TerminalFlowReducerActorSealed wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                terminalFlowAuthorityRefValue actor.filled.ratifiedLineage.ratificationRef
            | TerminalFlowReducerActorFailedClosed wrapped ->
                let actor = terminalFlowPossessionPayload wrapped
                match actor.context with
                | TerminalFlowFailureBeforePossession _
                | TerminalFlowFailureAfterIssue _ -> 0u
                | TerminalFlowFailureAfterFill(filled, _, _) -> terminalFlowAuthorityRefValue filled.ratifiedLineage.ratificationRef

        let private terminalFlowReducerQapOutcomeActorCommit
            (nextRevision:int64)
            (qapAfter:TerminalFlowQapGenerationAuthority option)
            (outcomeAfterCandidate:TerminalFlowReducerOutcomeAuthorityId)
            (actorAfter:TerminalFlowReducerActorAuthorityId)
            (authority:TerminalFlowReducerQapOutcomeActorAuthority) =
            let qapBefore = authority.qapGeneration
            let outcomeBefore = authority.outcome
            let actorBefore = authority.actor
            let qapAfter =
                match qapBefore, qapAfter with
                | Some before, Some after
                    when (before.stage = TerminalFlowQapGenerationDrained || before.stage = TerminalFlowQapGenerationDeadlocked)
                         && terminalFlowQapGenerationValue before.generation = terminalFlowQapGenerationValue after.generation
                         && after.stage <> before.stage -> Some before
                | _ -> qapAfter
            let actorStillBeforePossession =
                match actorBefore with
                | TerminalFlowReducerActorVacant _ -> true
                | TerminalFlowReducerActorArmed _
                | TerminalFlowReducerActorFilled _
                | TerminalFlowReducerActorSealed _
                | TerminalFlowReducerActorFailedClosed _ -> false
            let qapRebasedToOpenGeneration =
                match qapBefore, qapAfter with
                | Some before, Some after ->
                    terminalFlowQapGenerationValue before.generation <> terminalFlowQapGenerationValue after.generation
                    && (after.stage = TerminalFlowQapGenerationAwaiting || after.stage = TerminalFlowQapGenerationProgressing)
                | _ -> false
            let rebaseFinalOutcomeToOpenGeneration (after:TerminalFlowQapGenerationAuthority) = function
                | TerminalFlowReducerOutcomeFinalDrained existing ->
                    let reopened : TerminalFlowReducerOutcome<TerminalFlowReducerOutcomeProvisionalStage> =
                        { terminalRef = existing.terminalRef
                          fillRef = existing.fillRef
                          qapGeneration = Some after.generation
                          proofRef = None
                          dispatchConsumable = false }
                    TerminalFlowReducerOutcomeProvisional reopened
                | TerminalFlowReducerOutcomeFinalDeadlocked existing ->
                    let reopened : TerminalFlowReducerOutcome<TerminalFlowReducerOutcomeProvisionalStage> =
                        { terminalRef = existing.terminalRef
                          fillRef = existing.fillRef
                          qapGeneration = Some after.generation
                          proofRef = None
                          dispatchConsumable = false }
                    TerminalFlowReducerOutcomeProvisional reopened
                | outcome -> outcome
            let outcomeAfter, finalityRebase =
                match qapAfter with
                | Some after
                    when actorStillBeforePossession
                         && qapRebasedToOpenGeneration
                         && terminalFlowReducerOutcomeIsFinal outcomeBefore ->
                    rebaseFinalOutcomeToOpenGeneration after outcomeBefore, Some after
                | _ ->
                    (if terminalFlowReducerOutcomeIsFinal outcomeBefore
                        && not (terminalFlowReducerOutcomeIsFinal outcomeAfterCandidate)
                     then outcomeBefore
                     else outcomeAfterCandidate),
                    None
            match finalityRebase with
            | Some after ->
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_qap_finality_rebased_before_possession\",\"qap_generation_before\":%d,\"qap_generation_after\":%d,\"outcome_maturity_before_du\":%s,\"outcome_maturity_after_du\":%s,\"terminal_ref\":%u,\"actor_uncommitted\":true,\"authority\":\"single_reducer_explicit_rebase_invalidation\"}" [| box (qapBefore |> Option.map (fun qap -> terminalFlowQapGenerationValue qap.generation) |> Option.defaultValue 0UL); box (terminalFlowQapGenerationValue after.generation); box (DiagJson.esc (terminalFlowReducerOutcomeMaturityText (terminalFlowReducerOutcomeMaturity outcomeBefore))); box (DiagJson.esc (terminalFlowReducerOutcomeMaturityText (terminalFlowReducerOutcomeMaturity outcomeAfter))); box (terminalFlowReducerOutcomeAuthorityRef outcomeBefore) |])
            | None -> ()
            let handoffBefore = authority.handoff
            let handoffAfter = terminalFlowFinalOutcomeHandoffFor outcomeAfter
            let changed =
                qapAfter <> qapBefore
                || outcomeAfter <> outcomeBefore
                || handoffAfter <> handoffBefore
                || actorAfter <> actorBefore
            if not changed then authority
            else
                let qapStageBefore = qapBefore |> Option.map (fun qap -> qap.stage)
                let qapStageAfter = qapAfter |> Option.map (fun qap -> qap.stage)
                let qapGeneration = qapAfter |> Option.map (fun qap -> qap.generation)
                let qapParentGeneration = qapAfter |> Option.bind (fun qap -> qap.parentGeneration)
                let qapRebaseReceiptRef = qapAfter |> Option.bind (fun qap -> qap.lastRebaseReceipt |> Option.map (fun receipt -> receipt.receiptRef))
                let stageTokenRef = terminalFlowReducerActorStageTokenRef actorAfter
                let constitutionRef = terminalFlowReducerActorConstitutionRef actorAfter
                let ratificationRef = terminalFlowReducerActorRatificationRef actorAfter
                let transitionIdentityText =
                    FastRuntimeFormat.format "revision=%d|qap_stage=%s|outcome_maturity=%s|outcome_ref=%u|actor_version=%d|stage_token=%u|constitution=%u|ratification=%u" [| box nextRevision; box (qapStageAfter |> Option.map terminalFlowQapGenerationStageText |> Option.defaultValue "none"); box (terminalFlowReducerOutcomeMaturity outcomeAfter |> terminalFlowReducerOutcomeMaturityText); box (terminalFlowReducerOutcomeAuthorityRef outcomeAfter); box (terminalFlowReducerActorVersion actorAfter); box (stageTokenRef |> Option.defaultValue 0u); box constitutionRef; box ratificationRef |]
                let receipt =
                    { receiptRef = terminalFlowMintedRefOf "qap_outcome_actor_transition_ref" transitionIdentityText
                      qapGeneration = qapGeneration
                      qapStageBefore = qapStageBefore
                      qapStageAfter = qapStageAfter
                      outcomeBeforeRef = terminalFlowReducerOutcomeAuthorityRef outcomeBefore
                      outcomeAfterRef = terminalFlowReducerOutcomeAuthorityRef outcomeAfter
                      actorVersionBefore = terminalFlowReducerActorVersion actorBefore
                      actorVersionAfter = terminalFlowReducerActorVersion actorAfter
                      stageTokenRef = stageTokenRef
                      constitutionRef = constitutionRef
                      ratificationRef = ratificationRef
                      reducerSequence = nextRevision }
                let maturityBefore = terminalFlowReducerOutcomeMaturity outcomeBefore
                let maturityAfter = terminalFlowReducerOutcomeMaturity outcomeAfter
                let finalizationResult =
                    qapAfter
                    |> Option.bind (fun qap -> qap.finalization)
                    |> terminalFlowQapGenerationFinalizationText
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"qap_finalization_transition\",\"transition_receipt_id\":%u,\"qap_generation_id\":%d,\"qap_parent_generation_id\":%d,\"qap_rebase_receipt_id\":%u,\"qap_stage_before_du\":%s,\"qap_stage_after_du\":%s,\"qap_finalization_attempted\":%b,\"qap_finalization_result_du\":%s,\"outcome_maturity_before_du\":%s,\"outcome_maturity_after_du\":%s,\"dispatch_consumable\":%b,\"final_outcome_handoff_du\":%s,\"actor_state_version_before\":%d,\"actor_state_version_after\":%d,\"stage_token_id\":%u,\"constitution_ref\":%u,\"ratification_ref\":%u,\"reducer_sequence\":%d,\"authority\":\"single_reducer_total_qap_finalizer\"}" [| box receipt.receiptRef; box (qapGeneration |> Option.map terminalFlowQapGenerationValue |> Option.defaultValue 0UL); box (qapParentGeneration |> Option.map terminalFlowQapGenerationValue |> Option.defaultValue 0UL); box (qapRebaseReceiptRef |> Option.defaultValue 0u); box (DiagJson.esc (qapStageBefore |> Option.map terminalFlowQapGenerationStageText |> Option.defaultValue "None")); box (DiagJson.esc (qapStageAfter |> Option.map terminalFlowQapGenerationStageText |> Option.defaultValue "None")); box (qapAfter |> Option.exists (fun qap -> qap.finalization.IsSome)); box (DiagJson.esc finalizationResult); box (DiagJson.esc (terminalFlowReducerOutcomeMaturityText maturityBefore)); box (DiagJson.esc (terminalFlowReducerOutcomeMaturityText maturityAfter)); box (terminalFlowReducerOutcomeDispatchConsumable outcomeAfter); box (DiagJson.esc (terminalFlowFinalOutcomeHandoffText handoffAfter)); box receipt.actorVersionBefore; box receipt.actorVersionAfter; box (stageTokenRef |> Option.defaultValue 0u); box receipt.constitutionRef; box receipt.ratificationRef; box nextRevision |])
                { qapGeneration = qapAfter
                  outcome = outcomeAfter
                  handoff = handoffAfter
                  actor = actorAfter
                  version = nextRevision
                  lastTransition = Some receipt }

        let private terminalFlowReducerQapOutcomeActorAdvance
            (nextRevision:int64)
            dispatchDecision
            event
            (authority:TerminalFlowReducerQapOutcomeActorAuthority) =
            let qapBefore = authority.qapGeneration
            let outcomeBefore = authority.outcome
            let actorBefore = authority.actor
            let qapAfter, outcomeAfter, actorAfter =
                match event with
                | TerminalFlowGlobalServerQapFixpointObserved(fixpointRef, fixpoint, _, maturity) ->
                    let operationalSnapshot = terminalFlowOperationalAuthoritySnapshotNow ()
                    let operationalRevision =
                        CompilerKernelV2.OperationalAuthoritySnapshotOps.graphRevision operationalSnapshot
                    let operationalGraphRef =
                        CompilerKernelV2.OperationalAuthoritySnapshotOps.graphRef operationalSnapshot
                    let operationalRuntimeAuthorityRef =
                        CompilerKernelV2.OperationalAuthoritySnapshotOps.runtimeAuthorityRef operationalSnapshot
                    let operationalSemanticEpoch =
                        CompilerKernelV2.OperationalAuthoritySnapshotOps.semanticEpoch operationalSnapshot
                    let operationalSnapshotRef =
                        CompilerKernelV2.OperationalAuthoritySnapshotOps.snapshotRef operationalSnapshot
                    let generationAuthority =
                        match authority.qapGeneration with
                        | Some existing
                            when terminalFlowDurableRefValue existing.fixpointRef = terminalFlowDurableRefValue fixpointRef
                                 && existing.operationalSnapshotRef = operationalSnapshotRef ->
                            let stage =
                                match existing.stage, maturity with
                                | TerminalFlowQapGenerationDrained, _
                                | TerminalFlowQapGenerationDeadlocked, _ -> existing.stage
                                | _, TerminalFlowQapMaturityCandidateObserved -> existing.stage
                                | _, TerminalFlowQapMaturityWitnessedByReducer -> TerminalFlowQapGenerationProgressing
                            { existing with
                                stage = stage
                                relationSetHash = terminalFlowQapFixpointRelationSetHash fixpoint }
                        | Some existing ->
                            { generation = terminalFlowQapGenerationNext existing.generation
                              parentGeneration = Some existing.generation
                              stage = TerminalFlowQapGenerationAwaiting
                              fixpointRef = fixpointRef
                              relationSetHash = terminalFlowQapFixpointRelationSetHash fixpoint
                              operationalRevision = operationalRevision
                              operationalGraphRef = operationalGraphRef
                              operationalRuntimeAuthorityRef = operationalRuntimeAuthorityRef
                              operationalSemanticEpoch = operationalSemanticEpoch
                              operationalSnapshotRef = operationalSnapshotRef
                              lastRebaseReceipt = None
                              finalization = None
                              finalizationReceiptRef = None }
                        | None ->
                            { generation = terminalFlowQapGenerationOfFixpointRef fixpointRef
                              parentGeneration = None
                              stage = TerminalFlowQapGenerationAwaiting
                              fixpointRef = fixpointRef
                              relationSetHash = terminalFlowQapFixpointRelationSetHash fixpoint
                              operationalRevision = operationalRevision
                              operationalGraphRef = operationalGraphRef
                              operationalRuntimeAuthorityRef = operationalRuntimeAuthorityRef
                              operationalSemanticEpoch = operationalSemanticEpoch
                              operationalSnapshotRef = operationalSnapshotRef
                              lastRebaseReceipt = None
                              finalization = None
                              finalizationReceiptRef = None }
                    let generationValue = terminalFlowQapGenerationValue generationAuthority.generation
                    let parentGenerationValue =
                        generationAuthority.parentGeneration
                        |> Option.map terminalFlowQapGenerationValue
                        |> Option.defaultValue 0UL
                    match authority.qapGeneration with
                    | None ->
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_qap_generation_minted\",\"qap_generation_ref\":%d,\"parent_generation_ref\":%d,\"fixpoint_ref\":%u,\"relation_set_hash\":%u,\"relation_count\":%d,\"operational_revision\":%d,\"operational_semantic_epoch\":%d,\"qap_stage_du\":%s,\"authority\":\"single_reducer_observation_plan_to_qap_generation\",\"next\":\"watch_generation_then_rebase_or_finalize\"}" [| box generationValue; box parentGenerationValue; box (terminalFlowDurableRefValue generationAuthority.fixpointRef); box generationAuthority.relationSetHash; box fixpoint.items.Length; box generationAuthority.operationalRevision; box generationAuthority.operationalSemanticEpoch; box (DiagJson.esc (terminalFlowQapGenerationStageText generationAuthority.stage)) |])
                    | Some existing
                        when terminalFlowQapGenerationValue existing.generation <> generationValue ->
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_qap_generation_rebased\",\"qap_generation_ref\":%d,\"parent_generation_ref\":%d,\"fixpoint_ref\":%u,\"relation_set_hash\":%u,\"relation_count\":%d,\"operational_revision\":%d,\"operational_semantic_epoch\":%d,\"qap_stage_du\":%s,\"authority\":\"single_reducer_monotone_qap_generation_rebase\",\"next\":\"watch_rebased_generation_then_finalize\"}" [| box generationValue; box parentGenerationValue; box (terminalFlowDurableRefValue generationAuthority.fixpointRef); box generationAuthority.relationSetHash; box fixpoint.items.Length; box generationAuthority.operationalRevision; box generationAuthority.operationalSemanticEpoch; box (DiagJson.esc (terminalFlowQapGenerationStageText generationAuthority.stage)) |])
                    | _ -> ()
                    Some generationAuthority, outcomeBefore, actorBefore
                | TerminalFlowGlobalServerQapWatchRebaseRequested _ ->
                    // Rebase is committed only by the guarded reducer branch after
                    // parent generation, stage and monotone clocks are validated.
                    qapBefore, outcomeBefore, actorBefore
                | TerminalFlowGlobalServerTerminalOutcomeReady pending ->
                    let terminalRef = terminalFlowPendingTerminalReceiptDigest pending
                    let fillRef = terminalFlowPendingFillDigest pending
                    let outcomeAfter, binding =
                        match outcomeBefore with
                        | TerminalFlowReducerOutcomeAwaitingQap ->
                            let provisional : TerminalFlowReducerOutcome<TerminalFlowReducerOutcomeProvisionalStage> =
                                { terminalRef = terminalRef
                                  fillRef = fillRef
                                  qapGeneration = qapBefore |> Option.map (fun qap -> qap.generation)
                                  proofRef = None
                                  dispatchConsumable = false }
                            TerminalFlowReducerOutcomeProvisional provisional,
                            TerminalFlowOutcomeIdentityAwaitingBoundProvisional
                        | TerminalFlowReducerOutcomeProvisional existing ->
                            let rebound : TerminalFlowReducerOutcome<TerminalFlowReducerOutcomeProvisionalStage> =
                                { existing with
                                    terminalRef = terminalRef
                                    fillRef = fillRef
                                    qapGeneration =
                                        match existing.qapGeneration with
                                        | Some _ -> existing.qapGeneration
                                        | None -> qapBefore |> Option.map (fun qap -> qap.generation) }
                            TerminalFlowReducerOutcomeProvisional rebound,
                            TerminalFlowOutcomeIdentityProvisionalRebound
                        | TerminalFlowReducerOutcomeFinalDrained existing ->
                            let bound : TerminalFlowReducerOutcome<TerminalFlowReducerOutcomeFinalDrainedStage> =
                                { existing with terminalRef = terminalRef; fillRef = fillRef }
                            TerminalFlowReducerOutcomeFinalDrained bound,
                            TerminalFlowOutcomeIdentityFinalDrainedBound
                        | TerminalFlowReducerOutcomeFinalDeadlocked existing ->
                            let bound : TerminalFlowReducerOutcome<TerminalFlowReducerOutcomeFinalDeadlockedStage> =
                                { existing with terminalRef = terminalRef; fillRef = fillRef }
                            TerminalFlowReducerOutcomeFinalDeadlocked bound,
                            TerminalFlowOutcomeIdentityFinalDeadlockedBound
                    let maturityBefore = terminalFlowReducerOutcomeMaturity outcomeBefore
                    let maturityAfter = terminalFlowReducerOutcomeMaturity outcomeAfter
                    let bindingText = terminalFlowReducerOutcomeIdentityBindingText binding
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_final_outcome_identity_binding\",\"pending_intent_du\":%s,\"pending_dispatch_authority_du\":%s,\"binding_du\":%s,\"terminal_ref\":%u,\"fill_ref\":%u,\"qap_generation_id\":%d,\"outcome_maturity_before_du\":%s,\"outcome_maturity_after_du\":%s,\"finality_preserved\":%b,\"dispatch_decision_du\":%s,\"reducer_sequence\":%d,\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"authority\":\"single_reducer_late_identity_binding\",\"next\":\"correlate_candidate_publication_to_reducer_consumption_and_possession\"}" [| box (DiagJson.esc (terminalFlowPendingIntentText pending.intent)); box (DiagJson.esc (terminalFlowPendingDispatchAuthorityText pending.dispatchAuthority)); box (DiagJson.esc bindingText); box terminalRef; box fillRef; box (qapBefore |> Option.map (fun qap -> terminalFlowQapGenerationValue qap.generation) |> Option.defaultValue 0UL); box (DiagJson.esc (terminalFlowReducerOutcomeMaturityText maturityBefore)); box (DiagJson.esc (terminalFlowReducerOutcomeMaturityText maturityAfter)); box (terminalFlowReducerOutcomeIsFinal outcomeBefore = terminalFlowReducerOutcomeIsFinal outcomeAfter); box (DiagJson.esc (terminalFlowQapFinalOutcomeDispatchDecisionText dispatchDecision)); box nextRevision |])
                    terminalFlowEmitAdvancedConsoleProjection {
                        lane = TerminalFlowConsoleLaneOutcomeMaturity
                        sequence = nextRevision
                        progressBp = if terminalFlowReducerOutcomeIsFinal outcomeAfter then 10000 else 0
                        etaMs = if terminalFlowReducerOutcomeIsFinal outcomeAfter then Some 0L else None
                        title = if terminalFlowReducerOutcomeIsFinal outcomeAfter then "final outcome identity bound" else "provisional outcome identity bound"
                        detail = FastRuntimeFormat.format "%s|terminal_ref=%u|fill_ref=%u|maturity=%s->%s|dispatch=%s" [| box bindingText; box terminalRef; box fillRef; box (terminalFlowReducerOutcomeMaturityText maturityBefore); box (terminalFlowReducerOutcomeMaturityText maturityAfter); box (terminalFlowQapFinalOutcomeDispatchDecisionText dispatchDecision) |]
                        authorityRef = terminalRef
                    }
                    qapBefore, outcomeAfter, actorBefore
                | TerminalFlowGlobalServerStageTokenIssued issued ->
                    let receipt = issued.issueReceipt
                    let transaction = issued.transaction
                    let lineageComplete =
                        transaction.transitionOrdinal = TerminalFlowAffinePreparedOrdinal
                        && transaction.actorLease.leaseRef <> 0u
                        && transaction.actorLease.exactOnceRef <> 0u
                        && issued.issueEventRef <> 0u
                        && issued.exactOnceRef <> 0u
                        &&
                        receipt.actorRef <> 0u
                        && receipt.terminalRef <> 0u
                        && receipt.fillRef <> 0u
                        && receipt.admissionRef <> 0u
                        && receipt.admissionIdentityRef <> 0u
                        && receipt.actorBindingRef <> 0u
                        && receipt.credentialLedgerRef <> 0u
                        && receipt.credentialGraphClosureRef <> 0u
                        && receipt.credentialCycleProofRef = 0u
                        && receipt.constitutionRef <> 0u
                        && receipt.fairnessEpochRef <> 0u
                        && receipt.fairnessReleaseRef <> 0u
                        && receipt.schedulerReleaseRef <> 0u
                        && receipt.handoffRef <> 0u
                        && receipt.dispatchGrantRef <> 0u
                        && receipt.tokenRef <> 0u
                        && receipt.wakerEdgeRef <> 0u
                        && receipt.exactOnceRef <> 0u
                    match authority.handoff, actorBefore with
                    | TerminalFlowFinalOutcomeHandoffDispatchReady(_, terminalRef, fillRef, _), TerminalFlowReducerActorVacant _
                        when lineageComplete
                             && terminalRef = receipt.terminalRef
                             && fillRef = receipt.fillRef
                             && (terminalFlowActorOutcomeJoinActorRef transaction.actorLease.actorJoin) = receipt.actorRef
                             && (terminalFlowActorOutcomeJoinActorBindingRef transaction.actorLease.actorJoin) = receipt.actorBindingRef
                             && (terminalFlowActorOutcomeJoinAdmissionIdentityRef transaction.actorLease.actorJoin) = receipt.admissionIdentityRef
                             && transaction.authorization.tokenRef = receipt.tokenRef
