                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_linear_possession_rejected\",\"operation_du\":\"SealAuthorize\",\"reason_du\":%s,\"seal_authorization_receipt_ref\":%u,\"fill_commit_receipt_ref\":%u,\"token_ref\":%u,\"actor_ref\":%u,\"admission_identity_ref\":%u,\"scheduler_release_ref\":%u,\"authority\":\"single_reducer_terminal_possession\"}" [| box (DiagJson.esc (terminalFlowReducerTerminalPossessionRejectionText rejection)); box receipt.receiptRef; box receipt.fillCommitReceiptRef; box receipt.tokenRef; box receipt.actorRef; box receipt.admissionIdentityRef; box receipt.schedulerReleaseRef |])
