        let private terminalFlowDispatchConstitutionFor
            revision
            (kernel:TerminalFlowKernelState)
            (outcomeInstallation:TerminalFlowOutcomeInstallation)
            (typedTotalOrder:TerminalFlowTypedTotalOrder)
            (pendingTerminal:TerminalFlowPendingSlot)
            (dispatchAdmission:TerminalFlowDispatchAdmissionState)
            : TerminalFlowDispatchConstitutionState =
            let blocked blocker =
                TerminalFlowDispatchConstitutionBlocked(blocker, revision, Environment.TickCount64)
            match dispatchAdmission, kernel.root, kernel.outcome, outcomeInstallation, typedTotalOrder, pendingTerminal with
            | TerminalFlowDispatchAdmissionOpen, _, _, _, _, _ ->
                blocked TerminalFlowDispatchRecursiveProofMissing
            | TerminalFlowDispatchAdmissionSealed certificate,
              KernelRootResolved(rootReceiptId, _, _),
              KernelOutcomeSealed(terminalReceiptId, kernelFillKey),
              TerminalFlowOutcomeInstalled(installedAdmission, installationRef, actorBinding, _),
              TerminalFlowTotalOrderAwaitDispatch totalOrderAwaitDispatch,
              TerminalFlowPendingSlotCandidate pending ->
                let identity = certificate.identity
                let admissionRef = terminalFlowAdmissionRawRef identity
                let admissionIdentityRef = terminalFlowAdmissionIdentityRef identity
                let expectedTerminalRef = terminalFlowIdentityRefDigest certificate.terminalReceiptRef
                let actualTerminalRef = terminalFlowIdentityRefDigest terminalReceiptId
                let expectedFillRef = TerminalFlowFillKeyId.digest certificate.fillKey
                let actualFillRef = TerminalFlowFillKeyId.digest kernelFillKey
                let expectedRootRef = terminalFlowRootReceiptRef certificate.ownerWorkDagLineage.kernelRootReceiptRef
                let actualRootRef = terminalFlowRootReceiptRef rootReceiptId
                if not (terminalFlowAdmissionIdentitySame identity installedAdmission.identity)
                   || not (terminalFlowAdmissionIdentitySame identity actorBinding.identity)
                   || not (terminalFlowAdmissionIdentitySame identity pending.admissionIdentity) then
                    blocked (TerminalFlowDispatchAdmissionIdentityMismatch(admissionIdentityRef, terminalFlowAdmissionIdentityRef installedAdmission.identity))
                elif expectedRootRef <> actualRootRef
                     || certificate.rootCapability.rootReceiptRef <> actualRootRef then
                    blocked (TerminalFlowDispatchJoinKeyMismatch(expectedRootRef, actualRootRef))
                elif installedAdmission.terminalReceiptRef <> terminalReceiptId then
                    blocked (
                        TerminalFlowDispatchJoinKeyMismatch(
                            actualTerminalRef,
                            terminalFlowIdentityRefDigest installedAdmission.terminalReceiptRef))
                elif certificate.terminalReceiptRef <> terminalReceiptId
                     || terminalReceiptId <> pending.terminalReceiptRef then
                    blocked (TerminalFlowDispatchJoinKeyMismatch(expectedTerminalRef, actualTerminalRef))
                elif installedAdmission.fillKey <> kernelFillKey then
                    blocked (
                        TerminalFlowDispatchPendingFillMismatch(
                            actualFillRef,
                            TerminalFlowFillKeyId.digest installedAdmission.fillKey))
                elif certificate.fillKey <> kernelFillKey
                     || kernelFillKey <> pending.fillKeyId then
                    blocked (TerminalFlowDispatchPendingFillMismatch(expectedFillRef, actualFillRef))
                elif actorBinding.actorRef <> terminalFlowAdmissionActorRef identity
                     || actorBinding.bindingReceiptRef <> terminalFlowAdmissionActorBindingRef identity then
                    blocked (TerminalFlowDispatchAdmissionIdentityMismatch(terminalFlowAdmissionActorBindingRef identity, actorBinding.bindingReceiptRef))
                elif totalOrderAwaitDispatch.receiptRef <> certificate.predecessorOrderWitness.receipt.receiptRef then
                    blocked (TerminalFlowDispatchTotalOrderNotAwaiting totalOrderAwaitDispatch.receiptRef)
                else
                    let openReceipt = certificate.greenPathWitness.receipt
                    let greenPathDispatchReceipt : TerminalFlowGreenPathReceipt<TerminalFlowGreenPathDispatchReadyStage> = {
                        receiptRef = openReceipt.receiptRef
                        predecessorRef = openReceipt.predecessorRef
                        fillKey = openReceipt.fillKey
                        exactOnce = openReceipt.exactOnce
                    }
                    let pendingTerminalRef = terminalFlowPendingTerminalRef pending
                    TerminalFlowDispatchConstitutionReady {
                        admissionIdentity = identity
                        rootReceiptRef = certificate.ownerWorkDagLineage.kernelRootReceiptRef
                        terminalReceiptRef = certificate.terminalReceiptRef
                        fillKey = certificate.fillKey
                        credentialGraph =
                            terminalFlowSchedulerGraphClosedFor
                                certificate.lineage.closure.closureRef
                                (terminalFlowAdmissionRequirementLedgerRef identity)
                        greenPathDispatchReceipt = greenPathDispatchReceipt
                        installationRef = installationRef
                        totalOrderAwaitDispatch = certificate.predecessorOrderWitness.receipt
                        pendingTerminal =
                            terminalFlowSchedulerWitnessFor
                                "dispatch_admission_pending_terminal"
                                pendingTerminalRef
                        proofDigest = certificate.exactOnce
                        readyAtRevision = revision
                    }
            | TerminalFlowDispatchAdmissionSealed _, KernelRootAwaitingEvaluator, _, _, _, _ ->
                blocked TerminalFlowDispatchMissingRoot
            | TerminalFlowDispatchAdmissionSealed _, _, KernelOutcomeOpen, _, _, _ ->
                blocked TerminalFlowDispatchMissingOutcome
            | TerminalFlowDispatchAdmissionSealed _, _, _, TerminalFlowOutcomeNotInstalled, _, _ ->
                blocked TerminalFlowDispatchMissingOutcome
            | TerminalFlowDispatchAdmissionSealed _, _, _, TerminalFlowOutcomeConsumeEnqueued(_, _, _, consumeRef, _), _, _ ->
                blocked (TerminalFlowDispatchOutcomeConsumeAlreadyEnqueued(terminalFlowIdentityRefDigest consumeRef))
            | TerminalFlowDispatchAdmissionSealed _, _, _, _, typedOrder, _ when not (match typedOrder with TerminalFlowTotalOrderAwaitDispatch _ -> true | _ -> false) ->
                blocked (TerminalFlowDispatchTotalOrderNotAwaiting(terminalFlowTotalOrderReceiptRef typedOrder))
            | TerminalFlowDispatchAdmissionSealed _, _, _, _, _, TerminalFlowPendingSlotAwaitingCandidate ->
                blocked TerminalFlowDispatchPendingTerminalMissing
            | _ ->
                blocked (TerminalFlowDispatchContinuationRejected(terminalFlowMintedRefOf "dispatch_constitution_recursive_proof_projection_rejected" (string revision)))

        let private terminalFlowGlobalWithDispatchConstitution constitution (state:TerminalFlowGlobalReducerState) =
            let lifecycle =
                terminalFlowDispatchLifecycleAdvance
                    state.lastEventRef
                    state.revision
                    state.kernel
                    state.outcomeInstallation
                    state.qapOutcomeActorAuthority.actor
                    constitution
                    state.reducerTerminalSeal
                    state.dispatchLifecycle
            { state with dispatchLifecycle = lifecycle }

        let private terminalFlowDispatchConstitutionRefresh (state:TerminalFlowGlobalReducerState) =
            let currentConstitution = terminalFlowDispatchLifecycleConstitution state.dispatchLifecycle
            match currentConstitution with
            | TerminalFlowDispatchConstitutionIssued _
            | TerminalFlowDispatchAffinePrepared _
            | TerminalFlowDispatchAffineIssued _
            | TerminalFlowDispatchAffineFilled _
            | TerminalFlowDispatchAffineSealAuthorized _ -> state
            | TerminalFlowDispatchConstitutionReady _
            | TerminalFlowDispatchConstitutionBlocked _ ->
                let recomputed =
                    terminalFlowDispatchConstitutionFor
                        state.revision
                        state.kernel
                        state.outcomeInstallation
                        state.typedTotalOrder
                        state.pendingTerminal
                        state.dispatchAdmission
                let lifecycle =
                    terminalFlowDispatchLifecycleAdvance
                        state.lastEventRef
                        state.revision
                        state.kernel
                        state.outcomeInstallation
                        state.qapOutcomeActorAuthority.actor
                        recomputed
                        state.reducerTerminalSeal
                        state.dispatchLifecycle
                { state with dispatchLifecycle = lifecycle }

        let private terminalFlowGlobalReducerAdvance (state:TerminalFlowGlobalReducerState) (event:TerminalFlowGlobalServerEvent) (kernel:TerminalFlowKernelState) (pendingTerminal:TerminalFlowPendingSlot) =
            let nextRevision = state.revision + 1L
            let nextKernel =
                terminalFlowKernelStateFor nextRevision kernel.root kernel.outcome kernel.actor kernel.dispatch kernel.exit
            let nextTypedTotalOrder = terminalFlowTypedTotalOrderAdvance state event nextRevision
            let eventGreenPath = terminalFlowGreenPathAdvance state event
            let currentDispatchConstitution = terminalFlowDispatchLifecycleConstitution state.dispatchLifecycle
            let nextDispatchConstitution =
                match event, currentDispatchConstitution with
                | TerminalFlowGlobalServerStageTokenIssued issued, TerminalFlowDispatchAffinePrepared committed
                    when terminalFlowAffineTransactionSameLineage committed issued.transaction
                         && issued.issueEventRef <> 0u
                         && issued.exactOnceRef <> 0u ->
                    TerminalFlowDispatchAffineIssued(terminalFlowAffineTransactionMarkIssued committed)
                | TerminalFlowGlobalServerStageTokenFillCommitted filled, TerminalFlowDispatchAffineIssued committed
                    when terminalFlowAffineTransactionSameLineage committed filled.issued.transaction
                         && filled.fillEventRef <> 0u
                         && filled.exactOnceRef <> 0u ->
                    TerminalFlowDispatchAffineFilled(terminalFlowAffineTransactionMarkFilled committed)
                | TerminalFlowGlobalServerStageTokenSealAuthorized authorized, TerminalFlowDispatchAffineFilled committed
                    when terminalFlowAffineTransactionSameLineage committed authorized.filled.issued.transaction
                         && authorized.authorizationEventRef <> 0u
                         && authorized.exactOnceRef <> 0u ->
                    TerminalFlowDispatchAffineSealAuthorized(terminalFlowAffineTransactionMarkSealAuthorized committed)
                | _, ((TerminalFlowDispatchConstitutionIssued _
                    | TerminalFlowDispatchAffinePrepared _
                    | TerminalFlowDispatchAffineIssued _
                    | TerminalFlowDispatchAffineFilled _
                    | TerminalFlowDispatchAffineSealAuthorized _) as linearState) -> linearState
                | _, ((TerminalFlowDispatchConstitutionReady _
                    | TerminalFlowDispatchConstitutionBlocked _) as previousConstitution) ->
                    let recomputed =
                        terminalFlowDispatchConstitutionFor
                            nextRevision
                            nextKernel
                            state.outcomeInstallation
                            nextTypedTotalOrder
                            pendingTerminal
                            state.dispatchAdmission
                    match previousConstitution, recomputed with
                    | TerminalFlowDispatchConstitutionBlocked(previousBlocker, _, _),
                      TerminalFlowDispatchConstitutionBlocked(nextBlocker, _, _)
                        when previousBlocker = nextBlocker ->
                        // Blocker age belongs to the first observation. Re-emitting the
                        // same blocker on every reducer revision hides semantic changes.
                        previousConstitution
                    | TerminalFlowDispatchConstitutionReady previousReady,
                      TerminalFlowDispatchConstitutionReady nextReady
                        when terminalFlowDispatchConstitutionSameMaterialLineage previousReady nextReady ->
                        // Ready is a capability, not a revision ticker. Preserve the first
                        // minted credential set only while the full material lineage remains equal.
                        previousConstitution
                    | _ -> recomputed
            let priorDispatchConstitutionText = terminalFlowDispatchConstitutionStateText currentDispatchConstitution
            let nextDispatchConstitutionText = terminalFlowDispatchConstitutionStateText nextDispatchConstitution
            let nextDispatchAuthority =
                match nextDispatchConstitution with
                | TerminalFlowDispatchConstitutionBlocked _ -> false
                | TerminalFlowDispatchConstitutionReady _
                | TerminalFlowDispatchConstitutionIssued _
                | TerminalFlowDispatchAffinePrepared _
                | TerminalFlowDispatchAffineIssued _
                | TerminalFlowDispatchAffineFilled _
                | TerminalFlowDispatchAffineSealAuthorized _ -> true
            if priorDispatchConstitutionText <> nextDispatchConstitutionText then
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_dispatch_constitution_state_changed\",\"before_du\":%s,\"after_du\":%s,\"before_ref\":%u,\"after_ref\":%u,\"reducer_revision\":%d,\"dispatch_authority\":%b,\"next\":\"await_constituted_dispatch_request\",\"authority\":\"single_reducer_dispatch_constitution\"}" [| box (DiagJson.esc priorDispatchConstitutionText); box (DiagJson.esc nextDispatchConstitutionText); box (terminalFlowMintedRefOf "dispatch_constitution_state_ref" priorDispatchConstitutionText); box (terminalFlowMintedRefOf "dispatch_constitution_state_ref" nextDispatchConstitutionText); box nextRevision; box nextDispatchAuthority |])
            let dispatchProgressAuthority =
                match event with
                | TerminalFlowGlobalServerProgressEvidenceObserved evidence ->
                    terminalFlowReducerProgressAdvance state.progressAuthority evidence
                | _ -> state.progressAuthority
            let nextGreenPath =
                terminalFlowGreenPathEnsureClosedWorld
                    pendingTerminal
                    dispatchProgressAuthority
                    eventGreenPath
            let nextQapDispatchDecision =
                terminalFlowQapFinalOutcomeDispatchDecisionFor
                    dispatchProgressAuthority.accepted
                    dispatchProgressAuthority.rejected
                    nextGreenPath
                    pendingTerminal
            let nextQapOutcomeActorAuthority =
                terminalFlowReducerQapOutcomeActorAdvance
                    nextRevision
                    nextQapDispatchDecision
                    event
                    state.qapOutcomeActorAuthority
            let qapResolutionRef =
                nextQapOutcomeActorAuthority.qapGeneration
                |> Option.map (fun generation -> terminalFlowDurableRefValue generation.fixpointRef)
                |> Option.defaultValue 0u
            let hostShutdownFinalized
                (request:TerminalFlowHostShutdownRequest)
                (chain:TerminalFlowReducerTotalOrderChain)
                : TerminalFlowHostShutdownFinalizationReceipt =
                let requestRef = terminalFlowIdentityRefDigest request.requestRef
                { receiptRef = terminalFlowIdentityRefOfText (sprintf "host-shutdown-reducer-finalized:%u:%u" requestRef chain.physicalExit.receiptRef)
                  requestRef = request.requestRef
                  qapResolutionRef = qapResolutionRef
                  totalOrderRef = chain.physicalExit.receiptRef
                  finalizedAtRevision = nextRevision
                  exactOnceRef = terminalFlowMintedRefOf "host_shutdown_reducer_finalization_exact_once" (FastRuntimeFormat.format "%u:%u:%d" [| box requestRef; box chain.physicalExit.receiptRef; box nextRevision |]) }
            let nextReducerTerminalSeal, nextHostShutdown =
                match event, state.reducerTerminalSeal with
                | TerminalFlowGlobalServerStageTokenFillCommitted _, TerminalFlowReducerTerminalSealAwaitStageToken ->
                    // Filling the push-actor-owned outcome IVar is not exit authority.
                    // Total order remains closed until a distinct reducer-owned seal command arrives.
                    state.reducerTerminalSeal, state.hostShutdown
                | TerminalFlowGlobalServerStageTokenSealAuthorized authorized, TerminalFlowReducerTerminalSealAwaitStageToken ->
                    let receipt = authorized.authorizationReceipt
                    let chain = terminalFlowReducerTotalOrderChainForSealAuthorization nextRevision receipt
                    terminalFlowReducerTotalOrderChainEmit (TerminalFlowIndexedClosureInitial TerminalFlowIndexedClosureStageTokenSealAuthorized) chain
                    TerminalFlowReducerTerminalSealPhysicalExitSelected chain,
                    state.hostShutdown
                | TerminalFlowGlobalServerStageTokenSealAuthorized authorized, TerminalFlowReducerTerminalSealPhysicalExitSelected chain
                    when chain.commit.predecessorReceiptRef = authorized.authorizationReceipt.receiptRef ->
                    let receipt = authorized.authorizationReceipt
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_total_order_chain_coalesced\",\"seal_authorization_receipt_ref\":%u,\"fill_commit_receipt_ref\":%u,\"physical_exit_receipt_ref\":%u,\"authority\":\"single_reducer_total_order\"}" [| box receipt.receiptRef; box receipt.fillCommitReceiptRef; box chain.physicalExit.receiptRef |])
                    state.reducerTerminalSeal, state.hostShutdown
                | TerminalFlowGlobalServerStageTokenFailedClosed receipt, TerminalFlowReducerTerminalSealAwaitStageToken ->
                    let chain = terminalFlowReducerTotalOrderChainForStageTokenFailure nextRevision receipt
                    terminalFlowReducerTotalOrderChainEmit (TerminalFlowIndexedClosureInitial TerminalFlowIndexedClosureStageTokenFailedClosed) chain
                    TerminalFlowReducerTerminalSealFailClosedSelected chain,
                    state.hostShutdown
                | TerminalFlowGlobalServerStageTokenFailedClosed receipt, TerminalFlowReducerTerminalSealFailClosedSelected chain
                    when chain.commit.predecessorReceiptRef = receipt.receiptRef ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"terminal_failclosed_total_order_chain_coalesced\",\"stage_token_failure_receipt_ref\":%u,\"physical_exit_receipt_ref\":%u,\"authority\":\"single_reducer_total_order\"}"
                            receipt.receiptRef chain.physicalExit.receiptRef)
                    state.reducerTerminalSeal, state.hostShutdown
                | TerminalFlowGlobalServerHostShutdownRequested request, TerminalFlowReducerTerminalSealPhysicalExitSelected chain
                | TerminalFlowGlobalServerHostShutdownRequested request, TerminalFlowReducerTerminalSealFailClosedSelected chain ->
                    let finalized = hostShutdownFinalized request chain
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"host_shutdown_reconciled_to_total_order\",\"request_ref\":%u,\"qap_resolution_ref\":%u,\"physical_exit_receipt_ref\":%u,\"exit_code\":%d,\"shutdown_result_du\":\"ReconciledToExistingTotalOrder\",\"authority\":\"single_reducer_total_order\"}" [| box (terminalFlowIdentityRefDigest request.requestRef); box qapResolutionRef; box chain.physicalExit.receiptRef; box chain.exitCode |])
                    state.reducerTerminalSeal,
                    TerminalFlowHostShutdownFinalized finalized
                | TerminalFlowGlobalServerHostShutdownRequested request, TerminalFlowReducerTerminalSealAwaitStageToken ->
                    let coordinates =
                        terminalFlowReducerHostShutdownCoordinates
                            nextQapOutcomeActorAuthority.actor
                            pendingTerminal
                    let failureRef, chain =
                        terminalFlowReducerTotalOrderChainForHostShutdown
                            nextRevision
                            request
                            coordinates.actorRef
                            coordinates.terminalRef
                            coordinates.fillRef
                    terminalFlowReducerTotalOrderChainEmit (TerminalFlowIndexedClosureInitial TerminalFlowIndexedClosureHostShutdownFailClosed) chain
                    let finalized = hostShutdownFinalized request chain
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"host_shutdown_failclosed_total_order\",\"request_ref\":%u,\"failure_ref\":%u,\"qap_resolution_ref\":%u,\"terminal_identity_source_du\":%s,\"actor_ref\":%u,\"terminal_ref\":%u,\"fill_ref\":%u,\"commit_receipt_ref\":%u,\"done_receipt_ref\":%u,\"run_end_receipt_ref\":%u,\"physical_exit_receipt_ref\":%u,\"shutdown_result_du\":\"FailClosedTotalOrderMinted\",\"authority\":\"single_reducer_total_order\"}" [| box (terminalFlowIdentityRefDigest request.requestRef); box failureRef; box qapResolutionRef; box (DiagJson.esc (terminalFlowHostShutdownCoordinateSourceText coordinates.source)); box coordinates.actorRef; box coordinates.terminalRef; box coordinates.fillRef; box chain.commit.receiptRef; box chain.doneReceipt.receiptRef; box chain.runEnd.receiptRef; box chain.physicalExit.receiptRef |])
                    TerminalFlowReducerTerminalSealFailClosedSelected chain,
                    TerminalFlowHostShutdownFinalized finalized
                | _ -> state.reducerTerminalSeal, state.hostShutdown
            match nextQapOutcomeActorAuthority.lastTransition with
            | Some transition when transition.reducerSequence = nextRevision ->
                let generationValue =
                    transition.qapGeneration
                    |> Option.map terminalFlowQapGenerationValue
                    |> Option.defaultValue 0UL
                let stageBefore =
                    transition.qapStageBefore
                    |> Option.map terminalFlowQapGenerationStageText
                    |> Option.defaultValue "None"
                let stageAfter =
                    transition.qapStageAfter
                    |> Option.map terminalFlowQapGenerationStageText
                    |> Option.defaultValue "None"
                let finalizationResult =
                    nextQapOutcomeActorAuthority.qapGeneration
                    |> Option.map (fun generation -> terminalFlowQapGenerationFinalizationText generation.finalization)
                    |> Option.defaultValue "NotAttempted"
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"qap_outcome_actor_authority_transition\",\"qap_generation_id\":%d,\"qap_stage_before_du\":%s,\"qap_stage_after_du\":%s,\"qap_finalization_result_du\":%s,\"outcome_before_ref\":%u,\"outcome_after_ref\":%u,\"actor_state_version_before\":%d,\"actor_state_version_after\":%d,\"stage_token_id\":%u,\"transition_receipt_id\":%u,\"reducer_sequence\":%d,\"authority\":\"single_reducer_qap_outcome_actor\"}" [| box generationValue; box (DiagJson.esc stageBefore); box (DiagJson.esc stageAfter); box (DiagJson.esc finalizationResult); box transition.outcomeBeforeRef; box transition.outcomeAfterRef; box transition.actorVersionBefore; box transition.actorVersionAfter; box (transition.stageTokenRef |> Option.defaultValue 0u); box transition.receiptRef; box transition.reducerSequence |])
            | _ -> ()
            let nextKernelProofAuthority =
                match event with
                | TerminalFlowGlobalServerCicKernelProofObserved authority -> authority
                | _ -> state.kernelProofAuthority
            let nextBreakthroughConvergence =
                terminalFlowBreakthroughConvergenceAdvance
                    nextRevision
                    dispatchProgressAuthority
                    nextKernelProofAuthority
                    state.replayFairness
                    state.queueRecovery
                    nextGreenPath
            let nextBreakthroughSeal =
                terminalFlowBreakthroughSealFor nextGreenPath nextTypedTotalOrder nextKernelProofAuthority state.authorityCutover nextBreakthroughConvergence
            let nextEventRef =
                terminalFlowMintedRefOf "global_server_event_ref" (terminalFlowGlobalServerEventText event)
            let nextDispatchLifecycle =
                terminalFlowDispatchLifecycleAdvance
                    nextEventRef
                    nextRevision
                    nextKernel
                    state.outcomeInstallation
                    nextQapOutcomeActorAuthority.actor
                    nextDispatchConstitution
                    nextReducerTerminalSeal
                    state.dispatchLifecycle
            { kernel = nextKernel
              pendingTerminal = pendingTerminal
              outcomeInstallation = state.outcomeInstallation
              ownerDebt = state.ownerDebt
              terminalOrder = state.terminalOrder
              typedTotalOrder = nextTypedTotalOrder
              greenPath = nextGreenPath
              dispatchLifecycle = nextDispatchLifecycle
              authorityCutover = state.authorityCutover
              kernelProofAuthority = nextKernelProofAuthority
              breakthroughSeal = nextBreakthroughSeal
              breakthroughConvergence = nextBreakthroughConvergence
              progressAuthority = dispatchProgressAuthority
              authoritativeProgress = state.authoritativeProgress
              criticalPathEta = state.criticalPathEta
              criticalPathEtaObservedAtMs = state.criticalPathEtaObservedAtMs
              nativeEvalAuthority = state.nativeEvalAuthority
              cicKernelCounters = state.cicKernelCounters
              cicKernelAuthority = state.cicKernelAuthority
              cicOwnedActor = state.cicOwnedActor
              backendRuntimeWitness = state.backendRuntimeWitness
              topologyGate = state.topologyGate
              replayFairness = state.replayFairness
              queueRecovery = state.queueRecovery
              watchdogPetition = state.watchdogPetition
              wakerRegistrationDebt = state.wakerRegistrationDebt
              qapMaturityWatch = state.qapMaturityWatch
              qapOutcomeActorAuthority = nextQapOutcomeActorAuthority
              qapFinalization = state.qapFinalization
              qapPostCommit = state.qapPostCommit
              reducerQuiescence = state.reducerQuiescence
              reducerTerminalSeal = nextReducerTerminalSeal
              hostShutdown = nextHostShutdown
              dispatchAdmission = state.dispatchAdmission
              credentialLedger = state.credentialLedger
              ownerWorkDagProducer = state.ownerWorkDagProducer
              ownerLedgerCloseCertificate = state.ownerLedgerCloseCertificate
              workDagTailCloseProof = state.workDagTailCloseProof
              residualWorkDagCloseDecision = state.residualWorkDagCloseDecision
              terminalOrderCutover = state.terminalOrderCutover
              legacyTerminalAuthorityDemotions = state.legacyTerminalAuthorityDemotions
              causalSpine = terminalFlowGlobalCausalStep event state.causalSpine
              mutationLedger = state.mutationLedger
              revision = nextRevision
              lastEventRef = nextEventRef }

        let private terminalFlowGlobalCommitDispatchLifecycle (state:TerminalFlowGlobalReducerState) =
            let frame = terminalFlowDispatchLifecycleFrame state.dispatchLifecycle
            if frame.sourceEventRef <> state.lastEventRef || frame.reducerRevision <> state.revision then
                state
            else
                match frame.transition with
                | TerminalFlowProtocolCoalesced _
                | TerminalFlowProtocolPoisonCoalesced _ -> state
                | advance ->
                    let beforeProtocol =
                        frame.previous
                        |> Option.map (fun previous -> previous.protocol)
                        |> Option.defaultValue TerminalFlowProtocolAwaitRoot
                    let beforeText = terminalFlowDispatchProtocolStateText beforeProtocol
                    let afterText = terminalFlowDispatchProtocolStateText frame.protocol
                    let advanceText = terminalFlowDispatchProtocolStateAdvanceText advance
                    let protocolRef = terminalFlowDispatchProtocolStateRef frame.protocol
                    let depth = frame.depth
                    let poisonText =
                        match frame.poison with
                        | TerminalFlowProtocolPoisonHealthy -> "none"
                        | TerminalFlowProtocolPoisonLatched(poison, poisonRef, latchedAtRevision) ->
                            FastRuntimeFormat.format "Latched(poison_ref=%u|latched_at_revision=%d|%s)" [| box poisonRef; box latchedAtRevision; box (terminalFlowProtocolPoisonText poison) |]
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_dispatch_lifecycle_committed\",\"transition_du\":%s,\"before_du\":%s,\"after_du\":%s,\"before_rank\":%d,\"after_rank\":%d,\"protocol_ref\":%u,\"lifecycle_ref\":%u,\"exact_once_ref\":%u,\"source_event_ref\":%u,\"lifecycle_depth\":%d,\"rejection_count\":%d,\"poison_du\":%s,\"actor_state_ref\":%u,\"dispatch_state_ref\":%u,\"constitution_state_ref\":%u,\"reducer_revision\":%d,\"catchup_bounded\":true,\"authority\":\"recursive_single_reducer_dispatch_lifecycle\",\"fixture_authority\":false,\"renderer_authority\":false}" [| box (DiagJson.esc advanceText); box (DiagJson.esc beforeText); box (DiagJson.esc afterText); box (terminalFlowDispatchProtocolStateRank beforeProtocol); box (terminalFlowDispatchProtocolStateRank frame.protocol); box protocolRef; box frame.frameRef; box frame.exactOnceRef; box frame.sourceEventRef; box depth; box frame.rejectionCount; box (DiagJson.esc poisonText); box (terminalFlowDispatchLifecycleActorStateRef frame.kernelActor); box (terminalFlowDispatchLifecycleDispatchStateRef frame.kernelDispatch); box (terminalFlowDispatchLifecycleConstitutionStateRef frame.dispatchConstitution); box frame.reducerRevision |])
                    terminalFlowEmitAdvancedConsoleProjection {
                        lane = TerminalFlowConsoleLaneBreakthroughConvergence
                        sequence = state.revision
                        progressBp = terminalFlowDispatchProtocolStateRank frame.protocol * 1000
                        etaMs = None
                        title = "dispatch lifecycle transition"
                        detail =
                            advanceText
                            + "|" + afterText
                            + FastRuntimeFormat.format "|lifecycle_depth=%d|rejections=%d|poison=%s|catchup=bounded" [| box depth; box frame.rejectionCount; box poisonText |]
                        authorityRef = frame.frameRef
                    }
                    state

        let private terminalFlowQapSeedForSemanticClosure (state:TerminalFlowGlobalReducerState) =
            match state.qapMaturityWatch, terminalFlowSemanticSeedClosureEvidenceFor state with
            | None, Some closure ->
                let progress = closure.progress
                let identity =
                    FastRuntimeFormat.format
                        "semantic-closure:%u:%d:%d:%d"
                        [| box closure.rootEvidenceRef
                           box closure.semanticSeedGeneration
                           box closure.semanticSeedRevision
                           box closure.parsedAstSeedTotal |]
                let materialAgeMs = max 0L (Environment.TickCount64 - progress.observedAtMs)
                let fixpoint = terminalFlowQapClosedGraphFixpointFor identity materialAgeMs
                let fixpointRef : TerminalFlowDurableRef<TerminalFlowQapFixpointReceiptRefKind> =
                    TerminalFlowDurableRef(
                        terminalFlowQapLocalMintedRefOf
                            "qap_semantic_closure_seed_fixpoint_receipt_ref"
                            identity)
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format
                        "{\"kind\":\"terminal_semantic_closure_qap_generation_seeded\",\"qap_fixpoint_ref\":%u,\"root_evidence_ref\":%u,\"progress_snapshot_ref\":%u,\"semantic_seed_generation\":%d,\"semantic_seed_revision\":%d,\"parsed_ast_seed_total\":%d,\"semantic_retired_cost\":%d,\"terminal_progress_semantic_retired_cost\":%d,\"material_age_ms\":%d,\"relation_count\":0,\"authority\":\"single_reducer_semantic_seed_receipt_closure_seed\",\"next\":\"observe_empty_fixpoint_then_reducer_witness\"}"
                        [| box (terminalFlowDurableRefValue fixpointRef)
                           box closure.rootEvidenceRef
                           box progress.snapshotRef
                           box closure.semanticSeedGeneration
                           box closure.semanticSeedRevision
                           box closure.parsedAstSeedTotal
                           box closure.semanticSeedRetiredCost
                           box progress.semanticRetiredCost
                           box materialAgeMs |])
                terminalFlowGlobalServerPublish (
                    TerminalFlowGlobalServerQapFixpointObserved(
                        fixpointRef,
                        fixpoint,
                        materialAgeMs,
                        TerminalFlowQapMaturityCandidateObserved))
                Some fixpointRef
            | _ -> None

        type TerminalFlowPromotedPendingAuthorityReceipt = {
            priorInstallationRef : uint32
            installationRef : uint32
            installationRefreshed : bool
            installationPayloadMatchesPending : bool
            priorKernelOutcomeRef : uint32
            kernelOutcomeRef : uint32
            kernelOutcomeRefreshed : bool
        }

        let private terminalFlowGlobalInstallPromotedPending
            (state:TerminalFlowGlobalReducerState)
            (promoted:TerminalFlowGlobalPendingTerminal) =
            let installPath = terminalFlowPendingAdmissionInstallPath promoted.admission
            let promotedAdmission =
                terminalFlowOutcomeAdmissionForIdentityRefs
                    promoted.terminalReceiptRef
                    promoted.fillKeyId
                    promoted.admissionIdentity
                    installPath
            let priorInstallationRef =
                match state.outcomeInstallation with
                | TerminalFlowOutcomeInstalled(_, installationRef, _, _)
                | TerminalFlowOutcomeConsumeEnqueued(_, installationRef, _, _, _) -> terminalFlowIdentityRefDigest installationRef
                | TerminalFlowOutcomeNotInstalled -> 0u
            let installTransition =
                terminalFlowOutcomeInstallTransitionFor
                    state.outcomeInstallation
                    promotedAdmission
                    state.kernel.revision
            let promotedInstallation = terminalFlowOutcomeInstallTransitionState installTransition
            let installationRef =
                match promotedInstallation with
                | TerminalFlowOutcomeInstalled(_, installationRef, _, _)
                | TerminalFlowOutcomeConsumeEnqueued(_, installationRef, _, _, _) -> terminalFlowIdentityRefDigest installationRef
                | TerminalFlowOutcomeNotInstalled -> 0u
            let installationPayloadMatchesPending =
                match terminalFlowOutcomeInstallationAdmission promotedInstallation with
                | Some installed ->
                    installed.terminalReceiptRef = promoted.terminalReceiptRef
                    && installed.fillKey = promoted.fillKeyId
                | None -> false
            let priorKernelOutcomeRef, priorKernelFillRef =
                match state.kernel.outcome with
                | KernelOutcomeOpen -> 0u, 0u
                | KernelOutcomeSealed(terminalReceiptRef, fillKey) ->
                    terminalFlowIdentityRefDigest terminalReceiptRef,
                    TerminalFlowFillKeyId.digest fillKey
            let promotedTerminalReceiptRef = promoted.terminalReceiptRef
            let promotedFillKey = promoted.fillKeyId
            let kernelOutcomeRef = terminalFlowIdentityRefDigest promotedTerminalReceiptRef
            let kernelFillRef = TerminalFlowFillKeyId.digest promotedFillKey
            let promotedKernel =
                terminalFlowKernelStateFor
                    state.kernel.revision
                    state.kernel.root
                    (KernelOutcomeSealed(promotedTerminalReceiptRef, promotedFillKey))
                    state.kernel.actor
                    state.kernel.dispatch
                    state.kernel.exit
            let nextState =
                { state with
                    kernel = promotedKernel
                    pendingTerminal = TerminalFlowPendingSlotCandidate promoted
                    outcomeInstallation = promotedInstallation }
                |> terminalFlowDispatchConstitutionRefresh
            nextState,
            { priorInstallationRef = priorInstallationRef
              installationRef = installationRef
              installationRefreshed = terminalFlowOutcomeInstallTransitionIsNew installTransition
              installationPayloadMatchesPending = installationPayloadMatchesPending
              priorKernelOutcomeRef = priorKernelOutcomeRef
              kernelOutcomeRef = kernelOutcomeRef
              kernelOutcomeRefreshed = priorKernelOutcomeRef <> kernelOutcomeRef || priorKernelFillRef <> kernelFillRef }

        let private terminalFlowGlobalRefreshBreakthrough (state:TerminalFlowGlobalReducerState) =
            let state =
                match state.pendingTerminal with
                | TerminalFlowPendingSlotAwaitingCandidate -> state
                | TerminalFlowPendingSlotCandidate pending ->
                    match terminalFlowPendingExecutablePromotionForSemanticClosure state pending with
                    | None -> state
                    | Some(sourceRef, rootEvidenceRef, progressSnapshotRef, progressSource, capabilityRef, promoted) ->
                        // Native BuildOk promotion is owned by exact semantic seed closure.
                        // QAP/fence machinery may observe that closure, but it cannot be a
                        // prerequisite or side effect of granting executable authority.
                        // Promotion is an authority-class replacement, not a sibling candidate.
                        // The deferred mailbox may still hold the observer form with the same
                        // terminal/fill identity; replace that slot before any later redrive can
                        // reintroduce ObserverProjection into the reducer.
                        let deferredPromotionDisposition = terminalFlowDeferOutcomeForReducer promoted
                        let observerAuthorityPromoted =
                            match deferredPromotionDisposition with
                            | TerminalFlowDeferredOutcomeReplacedByIncomingClass(_, _, existingClass, incomingClass) ->
                                not (terminalFlowPendingCandidateIsExecutable existingClass)
                                && terminalFlowPendingCandidateIsExecutable incomingClass
                            | _ -> false
                        let promotedState, installationReceipt =
                            terminalFlowGlobalInstallPromotedPending state promoted
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_semantic_closure_native_executable_promoted\",\"source_ref\":%u,\"root_evidence_ref\":%u,\"progress_snapshot_ref\":%u,\"progress_source_du\":%s,\"capability_ref\":%u,\"prior_pending_ref\":%u,\"promoted_pending_ref\":%u,\"prior_installation_ref\":%u,\"installation_ref\":%u,\"installation_refreshed\":%b,\"installation_payload_matches_pending\":%b,\"prior_kernel_outcome_ref\":%u,\"kernel_outcome_ref\":%u,\"kernel_outcome_refreshed\":%b,\"qap_rearm_owner_du\":\"None\",\"qap_seeded\":false,\"authority\":\"single_reducer_semantic_closure_native_executable\",\"observer_authority_promoted\":%b,\"green_path_promotion_dependency_du\":\"ExactSemanticSeedClosureOnly\",\"next\":\"reconcile_executable_build_ok_without_qap_fence\"}" [| box sourceRef; box rootEvidenceRef; box progressSnapshotRef; box (DiagJson.esc (terminalFlowSemanticSeedClosureProgressSourceText progressSource)); box capabilityRef; box (terminalFlowPendingTerminalRef pending); box (terminalFlowPendingTerminalRef promoted); box installationReceipt.priorInstallationRef; box installationReceipt.installationRef; box installationReceipt.installationRefreshed; box installationReceipt.installationPayloadMatchesPending; box installationReceipt.priorKernelOutcomeRef; box installationReceipt.kernelOutcomeRef; box installationReceipt.kernelOutcomeRefreshed; box observerAuthorityPromoted |])
                        promotedState
            let successCorridorRetired =
                match state.reducerTerminalSeal with
                | TerminalFlowReducerTerminalSealPhysicalExitSelected _
                | TerminalFlowReducerTerminalSealFailClosedSelected _ -> true
                | TerminalFlowReducerTerminalSealAwaitStageToken ->
                    match state.kernel.actor, state.terminalOrder with
                    | KernelActorArmed(DiagJson.PushActorFailedClosed, _, _), _ -> true
                    | _, TerminalFlowGlobalOrderExitSelected _ -> true
                    | _ -> false
            if successCorridorRetired then
                terminalFlowGlobalCommitDispatchLifecycle state
            else
                let convergence =
                    terminalFlowBreakthroughConvergenceAdvance
                        state.revision
                        state.progressAuthority
                        state.kernelProofAuthority
                        state.replayFairness
                        state.queueRecovery
                        state.greenPath
                let seal =
                    terminalFlowBreakthroughSealFor
                        state.greenPath
                        state.typedTotalOrder
                        state.kernelProofAuthority
                        state.authorityCutover
                        convergence
                let violationTransitions =
                    terminalFlowBreakthroughViolationTransitions state.breakthroughConvergence.violations convergence.violations
                for transition in violationTransitions do
                    let transitionText = terminalFlowBreakthroughViolationTransitionText transition
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_breakthrough_violation_transition\",\"transition_du\":%s,\"transition_ref\":%u,\"revision\":%d,\"authority\":\"single_reducer\",\"restatement\":false}" [| box (DiagJson.esc transitionText); box (terminalFlowMintedRefOf "breakthrough_violation_transition_ref" transitionText); box state.revision |])
                let spineText = terminalFlowBreakthroughRequirementSpineText convergence.requirementSpine
                let detail =
                    match convergence.promotable with
                    | Some certificate -> FastRuntimeFormat.format "promotable:cert=%u:predecessor=%u:exact_once=%u:spine=%s" [| box certificate.certificateRef; box (certificate.predecessorRef |> Option.defaultValue 0u); box certificate.exactOnceRef; box spineText |]
                    | None -> "blocked:spine=" + spineText + ":violations=" + (convergence.violations |> List.map terminalFlowBreakthroughConvergenceViolationText |> String.concat "|")
                terminalFlowEmitAdvancedConsoleProjection {
                    lane = TerminalFlowConsoleLaneBreakthroughConvergence
                    sequence = state.revision
                    progressBp = if Option.isSome convergence.promotable then 9999 else 0
                    etaMs = None
                    title = if Option.isSome convergence.promotable then "breakthrough covenant promotable" else "breakthrough covenant blocked"
                    detail = detail
                    authorityRef = convergence.exactOnceRef
                }
                { state with breakthroughConvergence = convergence; breakthroughSeal = seal }
                |> terminalFlowGlobalCommitDispatchLifecycle

        type private TerminalFlowTypedFailureExitLineageId =
            | TerminalFlowTypedFailureExitLineageMatched
            | TerminalFlowTypedFailureExitCodeMismatch
            | TerminalFlowTypedFailureReferenceMismatch
            | TerminalFlowTypedFailureProcessExitRejected
            | TerminalFlowTypedFailureActorPhaseMismatch

        let private terminalFlowTypedFailureExitLineageFor
            (chain:TerminalFlowReducerTotalOrderChain)
            (request:TerminalFlowGlobalExitRequest) =
            let requestFailureRef = terminalFlowPhysicalExitChainFailureRef request.physicalChain
            if request.exitCode = 0 || chain.exitCode <> request.exitCode then
                TerminalFlowTypedFailureExitCodeMismatch
            elif request.finalActorPhase <> DiagJson.PushActorFailedClosed then
                TerminalFlowTypedFailureActorPhaseMismatch
            elif chain.failureRef <> Some requestFailureRef then
                TerminalFlowTypedFailureReferenceMismatch
            elif not (terminalFlowReducerProcessExitAllowed chain) then
                TerminalFlowTypedFailureProcessExitRejected
            else
                TerminalFlowTypedFailureExitLineageMatched

        let private terminalFlowTypedFailureExitLineageMatches chain request =
            terminalFlowTypedFailureExitLineageFor chain request = TerminalFlowTypedFailureExitLineageMatched

        let private terminalFlowGlobalExitAuthorization (state: TerminalFlowGlobalReducerState) (request: TerminalFlowGlobalExitRequest) =
            let typedFailure =
                match request.origin with
                | TerminalFlowGlobalExitFromTypedFailure _ -> true
                | TerminalFlowGlobalExitFromBreakthroughDone _ -> false
            let lifecycleFrame = terminalFlowDispatchLifecycleFrame state.dispatchLifecycle
            let actorOk =
                match typedFailure, lifecycleFrame.kernelActor, state.terminalOrderCutover, state.reducerTerminalSeal with
                // Success remains actor-owned: only the consumed actor can authorize exit zero.
                | false, KernelActorArmed(DiagJson.PushActorConsumed, actorFillKey, _), _, _ ->
                    actorFillKey = request.fillKeyId && request.exitCode = 0
                // A typed failure is already owned by the reducer's committed fail-closed total order.
                // Requiring the push actor to move from Noop to FailedClosed after that order was minted
                // stranded MIGRATION in normal dataflow even though process_exit_allowed=true.
                | true, _, Some (TerminalFlowTerminalOrderTypedFailureReady receipt), TerminalFlowReducerTerminalSealFailClosedSelected chain ->
                    receipt.failureRef = terminalFlowPhysicalExitChainFailureRef request.physicalChain
                    && receipt.exitCode = request.exitCode
                    && terminalFlowReducerProcessExitAuthorizationAllows receipt.processExitAuthorization
                    && chain.exitCode = request.exitCode
                    && terminalFlowReducerProcessExitAllowed chain
                    && request.exitCode <> 0
                | _ -> false
            let dispatchOk =
                match lifecycleFrame.kernelDispatch with
                | KernelDispatchAccepted identity -> terminalFlowDispatchRequestIdentityFillRef identity = request.fillRef
                | _ -> false
            let terminalAuthority = terminalFlowTerminalAuthorityFromKernel state request
            let exitCreditEvidence = terminalFlowOperationalProgressEvidenceNow ()
            let exitCreditDecision =
                exitCreditEvidence
                |> Some
                |> terminalFlowTerminationCreditDecisionFor
            // MIGRATION: exit authority is granted by the single monotone
            // protocol.  breakthroughSeal remains a renderer/compatibility
            // projection and no longer gates process exit.
            let requestedFillRef = terminalFlowIdentityRefDigest request.fillRef
            let dispatchProtocolOk =
                match typedFailure, lifecycleFrame.poison, lifecycleFrame.protocol with
                | false, TerminalFlowProtocolPoisonHealthy, TerminalFlowProtocolExitAuthorized chain ->
                    chain.exitCode = request.exitCode
                    && chain.physicalExit.fillRef = requestedFillRef
                    && terminalFlowReducerProcessExitAllowed chain
                | true, _, TerminalFlowProtocolFailClosed chain ->
                    terminalFlowTypedFailureExitLineageMatches chain request
                | true, _, _ ->
                    match state.reducerTerminalSeal with
                    | TerminalFlowReducerTerminalSealFailClosedSelected chain ->
                        terminalFlowTypedFailureExitLineageMatches chain request
                    | _ -> false
                | _ -> false
            let reducerTotalOrderOk =
                match typedFailure, state.reducerTerminalSeal with
                | false, TerminalFlowReducerTerminalSealPhysicalExitSelected chain ->
                    chain.exitCode = request.exitCode
                    && chain.physicalExit.fillRef = requestedFillRef
                    && terminalFlowReducerProcessExitAllowed chain
                | true, TerminalFlowReducerTerminalSealFailClosedSelected chain ->
                    chain.exitCode = request.exitCode
                    && chain.failureRef = Some (terminalFlowPhysicalExitChainFailureRef request.physicalChain)
                    && terminalFlowReducerProcessExitAllowed chain
                | _ -> false
            let reducerPhysicalExitReceiptRef, reducerIndexedClosureDurable =
                match state.reducerTerminalSeal with
                | TerminalFlowReducerTerminalSealPhysicalExitSelected chain
                | TerminalFlowReducerTerminalSealFailClosedSelected chain ->
                    chain.physicalExit.receiptRef,
                    terminalFlowIndexedClosureDurableChains.ContainsKey(chain.physicalExit.receiptRef)
                | TerminalFlowReducerTerminalSealAwaitStageToken -> 0u, false
            match exitCreditDecision with
            | TerminalFlowTerminationCreditOutstanding blockers ->
                Error (TerminalFlowExitCreditOutstanding blockers)
            | TerminalFlowTerminationCreditReturned _ when not reducerTotalOrderOk ->
                Error TerminalFlowExitReducerTotalOrderMissing
            | TerminalFlowTerminationCreditReturned _ when not reducerIndexedClosureDurable ->
                Error (TerminalFlowExitIndexedClosureNotDurable reducerPhysicalExitReceiptRef)
            | TerminalFlowTerminationCreditReturned _ when not actorOk ->
                Error TerminalFlowExitActorNotReady
            | TerminalFlowTerminationCreditReturned _ when (not typedFailure) && not dispatchOk ->
                Error TerminalFlowExitDispatchNotAccepted
            | TerminalFlowTerminationCreditReturned _ when not dispatchProtocolOk ->
                Error (
                    TerminalFlowExitDispatchLifecycleMissing(
                        lifecycleFrame.frameRef,
                        terminalFlowDispatchProtocolStateRef lifecycleFrame.protocol,
                        terminalFlowProtocolPoisonLatchIsPoisoned lifecycleFrame.poison,
                        lifecycleFrame.rejectionCount))
            | TerminalFlowTerminationCreditReturned quiescence ->
                match terminalAuthority with
                | Some authority when terminalFlowTerminalAuthorityAllowsExit request.exitCode request.finalActorPhase request.physicalChain authority ->
                    let reducerPhysicalExitReceiptRef =
                        match state.reducerTerminalSeal with
                        | TerminalFlowReducerTerminalSealPhysicalExitSelected chain
                        | TerminalFlowReducerTerminalSealFailClosedSelected chain -> chain.physicalExit.receiptRef
                        | TerminalFlowReducerTerminalSealAwaitStageToken -> 0u
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format
                            "{\"kind\":\"terminal_physical_boundary_credit_authorized\",\"quiescence_digest\":%s,\"requested_exit_code\":%d,\"reducer_physical_exit_receipt_ref\":%u,\"scheduler_open_count\":%d,\"terminal_protocol_open_count\":%d,\"active_workers_diagnostic\":%d,\"queue_depth_diagnostic\":%d,\"authority\":\"sealed_outcome_plus_zero_operational_credit_with_single_terminal_reservation\"}"
                            [| box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text quiescence.receiptDigest))
                               box request.exitCode
                               box reducerPhysicalExitReceiptRef
                               box exitCreditEvidence.workLedger.schedulerOpenCount
                               box quiescence.terminalProtocolOpen
                               box exitCreditEvidence.frontier.activeWorkers
                               box exitCreditEvidence.frontier.queueDepth |])
                    Ok {
                        request = request
                        authority = authority
                        reducerPhysicalExitReceiptRef = reducerPhysicalExitReceiptRef
                    }
                | _ -> Error TerminalFlowExitPhysicalChainInvalid

        type TerminalFlowPendingIntentClass =
            | TerminalFlowPendingIntentFinalFailClosed
            | TerminalFlowPendingIntentFinalBuildOk
            | TerminalFlowPendingIntentProvisionalNoFurther
            | TerminalFlowPendingIntentProvisionalQuarantine

        let private terminalFlowPendingIntentClass = function
            | TerminalFlowPendingFailClosed -> TerminalFlowPendingIntentFinalFailClosed
            | TerminalFlowPendingBuildOk -> TerminalFlowPendingIntentFinalBuildOk
            | TerminalFlowPendingNoFurther -> TerminalFlowPendingIntentProvisionalNoFurther
            | TerminalFlowPendingQuarantine -> TerminalFlowPendingIntentProvisionalQuarantine

        let private terminalFlowPendingIntentClassText = function
            | TerminalFlowPendingIntentFinalFailClosed -> "FinalFailClosed"
            | TerminalFlowPendingIntentFinalBuildOk -> "FinalBuildOk"
            | TerminalFlowPendingIntentProvisionalNoFurther -> "ProvisionalNoFurther"
            | TerminalFlowPendingIntentProvisionalQuarantine -> "ProvisionalQuarantine"

        type TerminalFlowOutcomeAuthorityClass =
            | TerminalFlowOutcomeProvenSemanticBuildOk
            | TerminalFlowOutcomeSemanticFailClosed
            | TerminalFlowOutcomeWatchdogFailClosed
            | TerminalFlowOutcomeUnprovenBuildOk
            | TerminalFlowOutcomeAuthorityProvisional

        let private terminalFlowOutcomeAuthorityClassText = function
            | TerminalFlowOutcomeProvenSemanticBuildOk -> "ProvenSemanticBuildOk"
            | TerminalFlowOutcomeSemanticFailClosed -> "SemanticFailClosed"
            | TerminalFlowOutcomeWatchdogFailClosed -> "WatchdogFailClosed"
            | TerminalFlowOutcomeUnprovenBuildOk -> "UnprovenBuildOk"
            | TerminalFlowOutcomeAuthorityProvisional -> "Provisional"

        let private terminalFlowOutcomeAuthorityClassFor (state:TerminalFlowGlobalReducerState) (pending:TerminalFlowGlobalPendingTerminal) =
            let exactSemanticClosure = terminalFlowSemanticSeedClosureEvidenceFor state |> Option.isSome
            match pending.intent with
            | TerminalFlowPendingBuildOk when exactSemanticClosure && terminalFlowPendingDispatchIsExecutable pending.dispatchAuthority ->
                TerminalFlowOutcomeProvenSemanticBuildOk
            | TerminalFlowPendingBuildOk -> TerminalFlowOutcomeUnprovenBuildOk
            | TerminalFlowPendingFailClosed when terminalFlowPendingAdmissionIsSafetyWatchdog pending.admission ->
                TerminalFlowOutcomeWatchdogFailClosed
            | TerminalFlowPendingFailClosed -> TerminalFlowOutcomeSemanticFailClosed
            | TerminalFlowPendingNoFurther
            | TerminalFlowPendingQuarantine -> TerminalFlowOutcomeAuthorityProvisional

        type TerminalFlowOutcomeLatticeDecision =
            | TerminalFlowOutcomeLatticeExistingWins
            | TerminalFlowOutcomeLatticeIncomingWins
            | TerminalFlowOutcomeLatticeEquivalent

        type TerminalFlowOutcomeLatticeReason =
            | TerminalFlowOutcomeLatticeSemanticFailureOverBuildOk
            | TerminalFlowOutcomeLatticeBuildOkOverWatchdog
            | TerminalFlowOutcomeLatticeSemanticFailureOverWatchdog
            | TerminalFlowOutcomeLatticeProvenBuildOkOverUnprovenBuildOk
            | TerminalFlowOutcomeLatticeSameClassLaterArrival
            | TerminalFlowOutcomeLatticeForeignLineageCannotSupersede

        let private terminalFlowOutcomeLatticeReasonText = function
            | TerminalFlowOutcomeLatticeSemanticFailureOverBuildOk -> "semantic_failure_over_buildok_global_typed_failure"
            | TerminalFlowOutcomeLatticeBuildOkOverWatchdog -> "proven_buildok_over_watchdog"
            | TerminalFlowOutcomeLatticeSemanticFailureOverWatchdog -> "semantic_failure_over_watchdog"
            | TerminalFlowOutcomeLatticeProvenBuildOkOverUnprovenBuildOk -> "proven_buildok_over_unproven_buildok"
            | TerminalFlowOutcomeLatticeSameClassLaterArrival -> "same_authority_class_later_arrival"
            | TerminalFlowOutcomeLatticeForeignLineageCannotSupersede -> "foreign_lineage_cannot_supersede"

        let private terminalFlowPendingSameOutcomeLineage (left:TerminalFlowGlobalPendingTerminal) (right:TerminalFlowGlobalPendingTerminal) =
            terminalFlowAdmissionIdentitySame left.admissionIdentity right.admissionIdentity
            && left.terminalReceiptRef = right.terminalReceiptRef
            && left.fillRef = right.fillRef

        let private terminalFlowOutcomeLatticeFor state existing incoming =
            let existingAuthority = terminalFlowOutcomeAuthorityClassFor state existing
            let incomingAuthority = terminalFlowOutcomeAuthorityClassFor state incoming
            // A typed semantic failure is global build authority: it must defeat a
            // BuildOk candidate even when the two notices were minted by different
            // terminal work lineages. Watchdog/provisional outcomes remain lineage-
            // scoped, so this does not create a generic cross-lineage supersession path.
            match existingAuthority, incomingAuthority with
            | TerminalFlowOutcomeSemanticFailClosed, TerminalFlowOutcomeProvenSemanticBuildOk
            | TerminalFlowOutcomeSemanticFailClosed, TerminalFlowOutcomeUnprovenBuildOk ->
                TerminalFlowOutcomeLatticeExistingWins, TerminalFlowOutcomeLatticeSemanticFailureOverBuildOk, existingAuthority, incomingAuthority
            | TerminalFlowOutcomeProvenSemanticBuildOk, TerminalFlowOutcomeSemanticFailClosed
            | TerminalFlowOutcomeUnprovenBuildOk, TerminalFlowOutcomeSemanticFailClosed ->
                TerminalFlowOutcomeLatticeIncomingWins, TerminalFlowOutcomeLatticeSemanticFailureOverBuildOk, existingAuthority, incomingAuthority
            | _ when not (terminalFlowPendingSameOutcomeLineage existing incoming) ->
                TerminalFlowOutcomeLatticeExistingWins,
                TerminalFlowOutcomeLatticeForeignLineageCannotSupersede,
                existingAuthority,
                incomingAuthority
            | _ ->
                match existingAuthority, incomingAuthority with
                | TerminalFlowOutcomeProvenSemanticBuildOk, TerminalFlowOutcomeWatchdogFailClosed ->
                    TerminalFlowOutcomeLatticeExistingWins, TerminalFlowOutcomeLatticeBuildOkOverWatchdog, existingAuthority, incomingAuthority
                | TerminalFlowOutcomeWatchdogFailClosed, TerminalFlowOutcomeProvenSemanticBuildOk ->
                    TerminalFlowOutcomeLatticeIncomingWins, TerminalFlowOutcomeLatticeBuildOkOverWatchdog, existingAuthority, incomingAuthority
                | TerminalFlowOutcomeSemanticFailClosed, TerminalFlowOutcomeWatchdogFailClosed ->
                    TerminalFlowOutcomeLatticeExistingWins, TerminalFlowOutcomeLatticeSemanticFailureOverWatchdog, existingAuthority, incomingAuthority
                | TerminalFlowOutcomeWatchdogFailClosed, TerminalFlowOutcomeSemanticFailClosed ->
                    TerminalFlowOutcomeLatticeIncomingWins, TerminalFlowOutcomeLatticeSemanticFailureOverWatchdog, existingAuthority, incomingAuthority
                | TerminalFlowOutcomeProvenSemanticBuildOk, TerminalFlowOutcomeUnprovenBuildOk ->
                    TerminalFlowOutcomeLatticeExistingWins, TerminalFlowOutcomeLatticeProvenBuildOkOverUnprovenBuildOk, existingAuthority, incomingAuthority
                | TerminalFlowOutcomeUnprovenBuildOk, TerminalFlowOutcomeProvenSemanticBuildOk ->
                    TerminalFlowOutcomeLatticeIncomingWins, TerminalFlowOutcomeLatticeProvenBuildOkOverUnprovenBuildOk, existingAuthority, incomingAuthority
                | _ ->
                    TerminalFlowOutcomeLatticeEquivalent, TerminalFlowOutcomeLatticeSameClassLaterArrival, existingAuthority, incomingAuthority

        type TerminalFlowCandidatePrecedenceReason =
            | TerminalFlowCandidateReducerAlreadyClosed
            | TerminalFlowCandidateIncomingExecutableAuthority
            | TerminalFlowCandidateExistingExecutableAuthority
            | TerminalFlowCandidateIncomingFinalMaturity
            | TerminalFlowCandidateExistingFinalMaturity
            | TerminalFlowCandidateOutcomeLattice of TerminalFlowOutcomeLatticeReason
            | TerminalFlowCandidateIncomingNoFurtherOverQuarantine
            | TerminalFlowCandidateExistingNoFurtherOverQuarantine

        let private terminalFlowCandidatePrecedenceReasonText = function
            | TerminalFlowCandidateReducerAlreadyClosed -> "reducer_already_closed"
            | TerminalFlowCandidateIncomingExecutableAuthority -> "incoming_executable_authority"
            | TerminalFlowCandidateExistingExecutableAuthority -> "existing_executable_authority"
            | TerminalFlowCandidateIncomingFinalMaturity -> "incoming_final_maturity"
            | TerminalFlowCandidateExistingFinalMaturity -> "existing_final_maturity"
            | TerminalFlowCandidateOutcomeLattice reason -> "outcome_lattice:" + terminalFlowOutcomeLatticeReasonText reason
            | TerminalFlowCandidateIncomingNoFurtherOverQuarantine -> "incoming_no_further_over_quarantine"
            | TerminalFlowCandidateExistingNoFurtherOverQuarantine -> "existing_no_further_over_quarantine"

        let private terminalFlowDispatchLineageGuardFor identity (replayFairness:TerminalFlowReducerFairnessState) =
            let schedulerPhysicalRelease =
                match replayFairness.schedule.schedulerLease with
                | Some (TerminalFlowAdmissionSchedulerReleased receipt) -> Some receipt
                | _ -> None
            let missing = ResizeArray<TerminalFlowDispatchLineageMissingEvidence>()
            match replayFairness.releaseReceipt with
            | None -> missing.Add TerminalFlowDispatchMissingFairnessRelease
            | Some release ->
                if release.admissionRef <> terminalFlowAdmissionRawRef identity then
                    missing.Add(TerminalFlowDispatchFairnessAdmissionMismatch(terminalFlowAdmissionRawRef identity, release.admissionRef))
                if release.admissionIdentityRef <> terminalFlowAdmissionIdentityRef identity then
                    missing.Add(TerminalFlowDispatchFairnessIdentityMismatch(terminalFlowAdmissionIdentityRef identity, release.admissionIdentityRef))
                if release.actorBindingRef <> terminalFlowAdmissionActorBindingRef identity then
                    missing.Add(TerminalFlowDispatchFairnessActorBindingMismatch(terminalFlowAdmissionActorBindingRef identity, release.actorBindingRef))
                if release.credentialLedgerRef <> terminalFlowAdmissionRequirementLedgerRef identity then
                    missing.Add(TerminalFlowDispatchFairnessCredentialLedgerMismatch(terminalFlowAdmissionRequirementLedgerRef identity, release.credentialLedgerRef))
                if terminalFlowIdentityRefDigest release.fairnessEpochRef <> terminalFlowAdmissionFairnessEpochRef identity then
                    missing.Add(TerminalFlowDispatchFairnessEpochMismatch(terminalFlowAdmissionFairnessEpochRef identity, terminalFlowIdentityRefDigest release.fairnessEpochRef))
            match schedulerPhysicalRelease with
            | None -> missing.Add TerminalFlowDispatchMissingSchedulerPhysicalRelease
            | Some schedulerRelease ->
                match replayFairness.releaseReceipt with
                | Some release when schedulerRelease.admissionRef <> release.admissionRef
                                     || schedulerRelease.admissionIdentityRef <> release.admissionIdentityRef
                                     || schedulerRelease.actorBindingRef <> release.actorBindingRef
                                     || schedulerRelease.credentialLedgerRef <> release.credentialLedgerRef
                                     || terminalFlowIdentityRefDigest schedulerRelease.fairnessEpochRef <> terminalFlowIdentityRefDigest release.fairnessEpochRef
                                     || terminalFlowIdentityRefDigest schedulerRelease.fairnessReleaseRef <> terminalFlowIdentityRefDigest release.releaseRef
                                     || terminalFlowSchedulerCapabilitySpinePhysicalReleaseRef schedulerRelease.capabilitySpine <> Some (terminalFlowIdentityRefDigest schedulerRelease.physicalReleaseRef)
                                     || terminalFlowSchedulerCapabilitySpineDepth schedulerRelease.capabilitySpine < 5 ->
                    missing.Add TerminalFlowDispatchSchedulerPhysicalReleaseIdentityMismatch
                | _ -> ()
            if missing.Count > 0 then
                TerminalFlowDispatchLineageMissing(terminalFlowNonEmptyEvidenceOfList (List.ofSeq missing))
            else
                match replayFairness.releaseReceipt, schedulerPhysicalRelease with
                | Some release, Some schedulerRelease -> TerminalFlowDispatchLineageProven(release, schedulerRelease)
                | _ ->
                    TerminalFlowDispatchLineageMissing(
                        terminalFlowNonEmptyEvidence
                            TerminalFlowDispatchMissingFairnessRelease
                            [ TerminalFlowDispatchMissingSchedulerPhysicalRelease ])

        let private terminalFlowDispatchAdmissionExactOnceDigest
            (constitution:TerminalFlowConstitutionLineage<TerminalFlowConstitutionSealedStage>)
            (fairnessRelease:TerminalFlowFairnessReleaseReceipt)
            (schedulerRelease:TerminalFlowSchedulerPhysicalReleaseReceipt)
            (credentialGraphClosureRef:uint32) =
            let constitutionDigest =
                CompilerIdentityKernel.ContentDigest.ofText "dispatch-constitution-receipt" (string constitution.exactOnceRef)
            let fairnessDigest =
                CompilerIdentityKernel.ContentDigest.ofText "dispatch-fairness-receipt" (string fairnessRelease.exactOnceRef)
            let schedulerDigest =
                CompilerIdentityKernel.ContentDigest.ofText
                    "dispatch-scheduler-receipt"
                    (CompilerIdentityKernel.ContentDigest.text fairnessDigest + "|" + string schedulerRelease.exactOnceRef)
            let graphDigest =
                CompilerIdentityKernel.ContentDigest.ofText
                    "dispatch-credential-graph-receipt"
                    (CompilerIdentityKernel.ContentDigest.text schedulerDigest + "|" + string credentialGraphClosureRef)
            CompilerIdentityKernel.ContentDigest.ofText
                "dispatch-admission-receipt"
                (String.concat "|"
                    [ CompilerIdentityKernel.ContentDigest.text constitutionDigest
                      CompilerIdentityKernel.ContentDigest.text fairnessDigest
                      CompilerIdentityKernel.ContentDigest.text schedulerDigest
                      CompilerIdentityKernel.ContentDigest.text graphDigest ])

        let private terminalFlowTryMintDispatchAdmission (state:TerminalFlowGlobalReducerState) (pending:TerminalFlowGlobalPendingTerminal) =
            // Pending owns the lineage. Installation can only agree with it or be treated
            // as stale/foreign evidence; it no longer creates a replacement identity.
            let identity = pending.admissionIdentity
            let nowMs = Environment.TickCount64
            let ledger = terminalFlowCredentialLedgerEnsure identity nowMs state.credentialLedger
            let state = { state with credentialLedger = Some ledger }
            let blocked kind reason =
                let nextLedger, blocker = terminalFlowCredentialLedgerBlockObserved kind reason nowMs ledger
                { state with credentialLedger = Some nextLedger },
                TerminalFlowDispatchAdmissionBlocked(TerminalFlowDispatchAdmissionRequirementBlocked blocker)
            let blockedLineage missing =
                let nextLedger =
                    missing
                    |> terminalFlowNonEmptyEvidenceToList
                    |> List.fold (fun current missingEvidence ->
                        let kind = terminalFlowDispatchLineageMissingRequirement missingEvidence
                        let reason = terminalFlowDispatchLineageMissingText missingEvidence
                        let next, _ = terminalFlowCredentialLedgerBlockObserved kind reason nowMs current
                        next) ledger
                { state with credentialLedger = Some nextLedger },
                TerminalFlowDispatchAdmissionBlocked(TerminalFlowDispatchAdmissionLineageMissing missing)
            let blockedProof missing =
                let nonEmptyMissing = terminalFlowNonEmptyEvidenceOfList missing
                let missingItems = terminalFlowNonEmptyEvidenceToList nonEmptyMissing
                let missingText = missingItems |> List.map terminalFlowDispatchProofMissingText |> String.concat "|"
                let nextLedger =
                    missingItems
                    |> List.fold (fun current missingEvidence ->
                        let kind = terminalFlowDispatchProofMissingRequirement missingEvidence
                        let reason = terminalFlowDispatchProofMissingText missingEvidence
                        let next, _ = terminalFlowCredentialLedgerBlockObserved kind reason nowMs current
                        next) ledger
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_dispatch_recursive_proof_blocked\",\"pending_intent_du\":%s,\"missing_count\":%d,\"missing_proof_du\":%s,\"reducer_revision\":%d,\"authority\":\"typed_recursive_dispatch_proof_requirements\",\"next\":\"satisfy_named_proof_requirements_without_bypass\"}" [| box (DiagJson.esc (terminalFlowPendingIntentText pending.intent)); box (List.length missingItems); box (DiagJson.esc missingText); box state.revision |])
                { state with credentialLedger = Some nextLedger },
                TerminalFlowDispatchAdmissionBlocked(TerminalFlowDispatchAdmissionProofMissing nonEmptyMissing)
            let lineageGuard = terminalFlowDispatchLineageGuardFor identity state.replayFairness
            let existingReuse =
                match state.dispatchAdmission with
                | TerminalFlowDispatchAdmissionSealed existing
                    when terminalFlowAdmissionIdentitySame existing.identity identity -> Some existing
                | _ -> None
            match existingReuse, ledger.result, terminalFlowPendingOutcomeMaturity pending.intent, lineageGuard with
            | Some existing, TerminalFlowRequirementGraphSatisfied closure, _, _
                when existing.lineage.closure.closureRef = closure.closureRef ->
                state, TerminalFlowDispatchAdmissionReused existing
            | Some existing, TerminalFlowRequirementGraphSatisfied closure, _, _ ->
                blockedProof [ TerminalFlowDispatchProofCredentialGraphClosureChanged(existing.lineage.closure, closure) ]
            | Some _, TerminalFlowRequirementGraphOpen, _, _ ->
                blockedProof [ TerminalFlowDispatchProofCredentialGraphReopenedAfterAdmission ]
            | Some _, TerminalFlowRequirementGraphCycleClosed cycleProof, _, _
            | None, TerminalFlowRequirementGraphCycleClosed cycleProof, _, _ ->
                blockedProof [ TerminalFlowDispatchProofCredentialGraphCycleClosed cycleProof ]
            | None, _, TerminalFlowOutcomeProvisional _, _ ->
                blocked TerminalFlowDispatchRequireFinalOutcome "outcome_not_final"
            | None, _, TerminalFlowOutcomeFinal _, TerminalFlowDispatchLineageMissing missing ->
                blockedLineage missing
            | None, _, TerminalFlowOutcomeFinal finalOutcome, TerminalFlowDispatchLineageProven(fairnessRelease, schedulerRelease) ->
                let proofMissing = ResizeArray<TerminalFlowDispatchProofMissingEvidence>()
                match state.breakthroughConvergence.promotable, state.breakthroughConvergence.violations with
                | None, head :: tail ->
                    proofMissing.Add(TerminalFlowDispatchProofBreakthroughViolated(terminalFlowNonEmptyEvidence head tail))
                | None, [] -> proofMissing.Add TerminalFlowDispatchProofBreakthroughMissing
                | Some _, _ -> ()
                match state.ownerWorkDagProducer with
                | None -> proofMissing.Add TerminalFlowDispatchProofOwnerWorkDagMissing
                | Some (TerminalFlowOwnerWorkDagProducerOpen _) -> proofMissing.Add TerminalFlowDispatchProofOwnerWorkDagOpen
                | Some (TerminalFlowOwnerWorkDagProducerDraining _) -> proofMissing.Add TerminalFlowDispatchProofOwnerWorkDagDraining
                | Some (TerminalFlowOwnerWorkDagProducerQuarantined _) -> proofMissing.Add TerminalFlowDispatchProofOwnerWorkDagQuarantined
                | Some (TerminalFlowOwnerWorkDagProducerSealed(_, proof, _, _)) when proof.openOwnerCount <> 0 || not proof.acyclicByConstruction ->
                    proofMissing.Add(TerminalFlowDispatchProofOwnerWorkDagInvalid(proof.openOwnerCount, proof.acyclicByConstruction))
                | Some (TerminalFlowOwnerWorkDagProducerSealed _) -> ()
                match state.queueRecovery.decision with
                | TerminalFlowQueueRecoveryReadyForReducerSeal _ -> ()
                | decision -> proofMissing.Add(TerminalFlowDispatchProofQueueRecoveryNotReady decision)
                let greenPathWitnessResult =
                    match state.greenPath with
                    | None -> Error TerminalFlowDispatchGreenPathMissingOpen
                    | Some greenPath -> terminalFlowDispatchGreenPathWitnessFor greenPath
                match greenPathWitnessResult with
                | Ok _ -> ()
                | Error TerminalFlowDispatchGreenPathMissingOpen ->
                    proofMissing.Add TerminalFlowDispatchProofGreenPathMissing
                | Error error ->
                    proofMissing.Add(TerminalFlowDispatchProofGreenPathNotOpen error)
                match state.kernel.root with
                | KernelRootAwaitingEvaluator -> proofMissing.Add TerminalFlowDispatchProofRootMissing
                | KernelRootResolved _ -> ()
                let expectedTerminalRef = pending.terminalReceiptRef
                let expectedFillKey = pending.fillKeyId
                match state.kernel.outcome with
                | KernelOutcomeOpen -> proofMissing.Add TerminalFlowDispatchProofTerminalOutcomeOpen
                | KernelOutcomeSealed(terminalReceiptRef, fillKey) ->
                    if terminalReceiptRef <> expectedTerminalRef
                       || fillKey <> expectedFillKey then
                        proofMissing.Add(TerminalFlowDispatchProofTerminalOutcomeMismatch(expectedTerminalRef, terminalReceiptRef, expectedFillKey, fillKey))
                match terminalFlowDispatchPredecessorOrderWitnessFor state.typedTotalOrder with
                | Ok _ -> ()
                | Error error -> proofMissing.Add(TerminalFlowDispatchProofPredecessorOrderNotAwaitDispatch error)
                if proofMissing.Count > 0 then
                    blockedProof (List.ofSeq proofMissing)
                else
                    match (state.breakthroughConvergence.promotable |> Option.bind terminalFlowBreakthroughRestorePromotable),
                          state.ownerWorkDagProducer,
                          state.queueRecovery.decision,
                          greenPathWitnessResult,
                          state.kernel.root,
                          state.kernel.outcome,
                          state.typedTotalOrder with
                    | Some breakthrough,
                      Some (TerminalFlowOwnerWorkDagProducerSealed(ownerCertificate, workDagTailProof, rootCapability, ownerQueueRecovery)),
                      TerminalFlowQueueRecoveryReadyForReducerSeal recovery,
                      Ok greenPathWitness,
                      KernelRootResolved(kernelRootReceiptRef, _, _),
                      KernelOutcomeSealed(terminalReceiptId, fillKey),
                      TerminalFlowTotalOrderAwaitDispatch predecessorReceipt ->
                        let finalOutcomeRef = terminalFlowIdentityRefDigest finalOutcome.maturityRef
                        let terminalOutcomeRef = terminalFlowIdentityRefDigest terminalReceiptId
                        let fillRef = TerminalFlowFillKeyId.digest fillKey
                        let queueRecoveryRef = terminalFlowIdentityRefDigest recovery.recoveryRef
                        let kernelRootRef = terminalFlowRootReceiptRef kernelRootReceiptRef
                        let greenPathReceipt = greenPathWitness.receipt
                        let predecessorWitness : TerminalFlowDispatchPredecessorOrderWitness = {
                            receipt = predecessorReceipt
                        }
                        let producer = TerminalFlowOwnerWorkDagProducerSealed(ownerCertificate, workDagTailProof, rootCapability, ownerQueueRecovery)
                        match terminalFlowConstitutionSeal queueRecoveryRef kernelRootRef greenPathReceipt.receiptRef predecessorReceipt.receiptRef producer with
                        | Error violation ->
                            blockedProof [ TerminalFlowDispatchProofConstitutionRejected violation ]
                        | Ok constitution ->
                            let nextLedger, requirements =
                                terminalFlowCredentialLedgerSatisfyRequirementsObserved
                                    [ TerminalFlowDispatchRequireFinalOutcome, finalOutcomeRef
                                      TerminalFlowDispatchRequireTerminalOutcomeSealed, terminalOutcomeRef
                                      TerminalFlowDispatchRequireActorBinding, terminalFlowAdmissionActorBindingRef identity
                                      TerminalFlowDispatchRequireExitOpen, terminalFlowIdentityRefDigest pending.fillRef
                                      TerminalFlowDispatchRequireRootCapability, rootCapability.capabilityRef
                                      TerminalFlowDispatchRequireWorkDagTailClose, terminalFlowWorkDagTailRef workDagTailProof.workDagTail
                                      TerminalFlowDispatchRequireQueueRecovery, queueRecoveryRef
                                      TerminalFlowDispatchRequireBreakthrough, breakthrough.certificateRef
                                      TerminalFlowDispatchRequireFairness, terminalFlowIdentityRefDigest fairnessRelease.releaseRef
                                      TerminalFlowDispatchRequireSchedulerRelease, terminalFlowIdentityRefDigest schedulerRelease.physicalReleaseRef
                                      TerminalFlowDispatchRequireGreenPath, greenPathReceipt.receiptRef
                                      TerminalFlowDispatchRequirePredecessorOrder, predecessorReceipt.receiptRef ]
                                    state.revision
                                    nowMs
                                    ledger
                            let schedulerLineage = terminalFlowDispatchSchedulerBoundProofFor identity fairnessRelease schedulerRelease
                            match terminalFlowDispatchCredentialGraphBoundProofFor schedulerLineage requirements nextLedger with
                            | Error TerminalFlowDispatchCredentialGraphStillOpen ->
                                blockedProof [ TerminalFlowDispatchProofCredentialGraphStillOpen ]
                            | Error (TerminalFlowDispatchCredentialGraphCycleClosed cycleProof) ->
                                blockedProof [ TerminalFlowDispatchProofCredentialGraphCycleClosed cycleProof ]
                            | Ok credentialGraph ->
                                let finalOutcomeLineage : TerminalFlowDispatchFinalOutcomeBoundProof = {
                                    credentialGraph = credentialGraph
                                    finalOutcome = finalOutcome
                                }
                                let terminalOutcomeLineage : TerminalFlowDispatchTerminalOutcomeSealedProof = {
                                    finalOutcome = finalOutcomeLineage
                                    terminalReceiptRef = terminalReceiptId
                                    fillKey = fillKey
                                }
                                let ownerWorkDagLineage : TerminalFlowDispatchOwnerWorkDagBoundProof = {
                                    terminalOutcome = terminalOutcomeLineage
                                    ownerCertificate = ownerCertificate
                                    workDagTailProof = workDagTailProof
                                    rootCapability = rootCapability
                                    kernelRootReceiptRef = kernelRootReceiptRef
                                }
                                let queueRecoveryLineage : TerminalFlowDispatchQueueRecoveryBoundProof = {
                                    ownerWorkDag = ownerWorkDagLineage
                                    recovery = recovery
                                }
                                let breakthroughLineage : TerminalFlowDispatchBreakthroughBoundProof = {
                                    queueRecovery = queueRecoveryLineage
                                    breakthrough = breakthrough
                                }
                                let greenPathLineage : TerminalFlowDispatchGreenPathBoundProof = {
                                    breakthrough = breakthroughLineage
                                    greenPath = greenPathWitness
                                }
                                let predecessorOrderLineage : TerminalFlowDispatchPredecessorOrderBoundProof = {
                                    greenPath = greenPathLineage
                                    predecessorOrder = predecessorWitness
                                }
                                let proof : TerminalFlowDispatchConstitutionBoundProof = {
                                    predecessorOrder = predecessorOrderLineage
                                    constitution = constitution
                                }
                                let exactOnce =
                                    terminalFlowDispatchAdmissionExactOnceDigest
                                        constitution
                                        fairnessRelease
                                        schedulerRelease
                                        credentialGraph.closure.closureRef
                                let certificate = {
                                    proof = proof
                                    exactOnce = exactOnce
                                    reducerSequence = state.revision
                                    mintedAtMs = Environment.TickCount64
                                }
                                match state.dispatchAdmission with
                                | TerminalFlowDispatchAdmissionSealed existing
                                    when terminalFlowAdmissionIdentitySame existing.identity certificate.identity ->
                                    { state with credentialLedger = Some nextLedger }, TerminalFlowDispatchAdmissionReused existing
                                | _ ->
                                    { state with
                                        dispatchAdmission = TerminalFlowDispatchAdmissionSealed certificate
                                        credentialLedger = Some nextLedger },
                                    TerminalFlowDispatchAdmissionMinted certificate
                    | _ ->
                        blockedProof [ TerminalFlowDispatchProofRootMissing ]

        let private terminalFlowTryMintRetainedTerminalOrder (state:TerminalFlowGlobalReducerState) (pending:TerminalFlowGlobalPendingTerminal) =
            match state.terminalOrderCutover,
                  state.dispatchAdmission,
                  terminalFlowOutcomeInstallationAdmission state.outcomeInstallation,
                  terminalFlowOutcomeInstallationActorBinding state.outcomeInstallation,
                  state.typedTotalOrder with
            | None,
              TerminalFlowDispatchAdmissionSealed admission,
              Some installedAdmission,
              Some actorBinding,
              TerminalFlowTotalOrderAwaitDispatch currentPredecessor
                when pending.intent = TerminalFlowPendingBuildOk
                     && admission.finalOutcome.intent = pending.intent
                     && terminalFlowAdmissionIdentitySame admission.identity installedAdmission.identity
                     && terminalFlowAdmissionIdentitySame actorBinding.identity installedAdmission.identity
                     && terminalFlowAdmissionActorRef admission.identity = actorBinding.actorRef
                     && terminalFlowAdmissionActorBindingRef admission.identity = actorBinding.bindingReceiptRef
                     && admission.terminalReceiptRef = pending.terminalReceiptRef
                     && admission.fillKey = pending.fillKeyId
                     && admission.workDagTailProof.openOwnerCount = 0
                     && admission.workDagTailProof.acyclicByConstruction
                     && admission.rootCapability.ownerLedgerSealRef = admission.ownerCertificate.certificateRef
                     && admission.predecessorOrderWitness.receipt.receiptRef = currentPredecessor.receiptRef ->
                let expectedExactOnce =
                    terminalFlowDispatchAdmissionExactOnceDigest
                        admission.constitution
                        admission.fairnessRelease
                        admission.schedulerRelease
                        admission.lineage.closure.closureRef
                if admission.exactOnce = expectedExactOnce then
                    let admissionRef = terminalFlowAdmissionRawRef admission.identity
                    let input : TerminalFlowTerminalOrderMinterInput<ProceduralResidualOwnerKind> = {
                        finalOutcome = admission.finalOutcome
                        ownerCertificate = admission.ownerCertificate
                        workDagTailProof = admission.workDagTailProof
                        terminalPath = TerminalFlowTerminalOrderBuildOkAdmissionPath(admissionRef, terminalFlowIdentityRefDigest admission.queueRecovery.recoveryRef, admission.greenPathWitness.receipt.receiptRef)
                        fillOnceRef = TerminalFlowFillKeyId.digest admission.fillKey
                        dispatchRequestRef = admissionRef
                        actorStageTokenRef = admission.breakthrough.certificateRef
                        constitutionRef = admission.constitution.constitutionRef
                        predecessorOrderRef = admission.predecessorOrderWitness.receipt.receiptRef
                        exactOnceRef = admission.exactOnceRef
                        totalOrderIndex = currentPredecessor.orderIndex + 1L
                        reducerSequence = state.revision
                    }
                    let receipt = terminalFlowMintTerminalOrderCutover input
                    { state with terminalOrderCutover = Some receipt.cutover }, Some receipt
                else
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_order_mint_blocked_by_recursive_dispatch_proof\",\"admission_ref\":%u,\"constitution_ref\":%u,\"admission_exact_once_ref\":%u,\"expected_exact_once_digest\":\"%s\",\"credential_graph_closure_ref\":%u,\"authority\":\"sealed_recursive_dispatch_proof\"}" [| box (terminalFlowAdmissionRawRef admission.identity); box admission.constitution.constitutionRef; box admission.exactOnceRef; box (CompilerIdentityKernel.ContentDigest.text expectedExactOnce); box admission.lineage.closure.closureRef |])
                    state, None
            | _ -> state, None

        let private terminalFlowPendingTerminalHasSealedTerminalOrder (state:TerminalFlowGlobalReducerState) (pending:TerminalFlowGlobalPendingTerminal) =
            if not (terminalFlowPendingOutcomeIsFinal pending.intent) then false
            else
                match terminalFlowOutcomeInstallationAdmission state.outcomeInstallation,
                      terminalFlowOutcomeInstallationActorBinding state.outcomeInstallation,
                      state.dispatchAdmission,
                      state.terminalOrderCutover with
                | Some installedAdmission,
                  Some actorBinding,
                  TerminalFlowDispatchAdmissionSealed certificate,
                  Some terminalOrder ->
                    let admissionRef = terminalFlowAdmissionRawRef certificate.identity
                    terminalFlowAdmissionIdentitySame certificate.identity installedAdmission.identity
                    && terminalFlowAdmissionIdentitySame actorBinding.identity installedAdmission.identity
                    && terminalFlowAdmissionActorRef certificate.identity = actorBinding.actorRef
                    && terminalFlowAdmissionActorBindingRef certificate.identity = actorBinding.bindingReceiptRef
                    && terminalFlowAdmissionRequirementLedgerRef certificate.identity = terminalFlowAdmissionRequirementLedgerRef installedAdmission.identity
                    && certificate.terminalReceiptRef = pending.terminalReceiptRef
                    && certificate.fillKey = pending.fillKeyId
                    && certificate.finalOutcome.intent = pending.intent
                    && terminalFlowTerminalOrderCutoverAdmissionRef terminalOrder = Some admissionRef
                | _, _, _, Some (TerminalFlowTerminalOrderTypedFailureReady _) ->
                    pending.intent = TerminalFlowPendingFailClosed
                | _ -> false

        let private terminalFlowPendingTerminalOrderBlocker (state:TerminalFlowGlobalReducerState) (pending:TerminalFlowGlobalPendingTerminal) =
            if not (terminalFlowPendingOutcomeIsFinal pending.intent) then "outcome_not_final"
            elif terminalFlowPendingTerminalHasSealedTerminalOrder state pending then "none"
            else
                match state.dispatchAdmission, state.terminalOrderCutover with
                | TerminalFlowDispatchAdmissionOpen, None -> "recursive_dispatch_proof_missing"
                | TerminalFlowDispatchAdmissionSealed _, None -> "terminal_order_entry_missing_for_recursive_dispatch_proof"
                | TerminalFlowDispatchAdmissionOpen, Some _ -> "terminal_order_without_recursive_dispatch_proof"
                | TerminalFlowDispatchAdmissionSealed _, Some _ -> "terminal_order_entry_identity_mismatch_against_recursive_dispatch_proof"

        type TerminalFlowPendingCandidateArbitrationId =
            | TerminalFlowIncomingCandidatePrecedesExisting
            | TerminalFlowEquivalentCandidateLaterReducerArrival
            | TerminalFlowExistingCandidatePrecedesIncoming
            | TerminalFlowCandidateArbitrationClosed

        type TerminalFlowPendingCandidateArbitration = private {
            decision : TerminalFlowPendingCandidateArbitrationId
            reason : TerminalFlowCandidatePrecedenceReason
            existingClass : TerminalFlowPendingCandidateClass
            incomingClass : TerminalFlowPendingCandidateClass
            existingIntentClass : TerminalFlowPendingIntentClass
            incomingIntentClass : TerminalFlowPendingIntentClass
            reducerClosed : bool
        }

        let private terminalFlowPendingCandidateArbitrationDecisionText = function
            | TerminalFlowIncomingCandidatePrecedesExisting -> "incoming_precedes_existing"
            | TerminalFlowEquivalentCandidateLaterReducerArrival -> "equivalent_candidate_later_reducer_arrival"
            | TerminalFlowExistingCandidatePrecedesIncoming -> "existing_precedes_incoming"
            | TerminalFlowCandidateArbitrationClosed -> "arbitration_closed_after_dispatch_or_exit"

        let private terminalFlowPendingCandidateArbitrationFor
            (state:TerminalFlowGlobalReducerState)
            (existing:TerminalFlowGlobalPendingTerminal)
            (incoming:TerminalFlowGlobalPendingTerminal) =
            let existingClass = terminalFlowPendingCandidateClass existing
            let incomingClass = terminalFlowPendingCandidateClass incoming
            let existingIntentClass = terminalFlowPendingIntentClass existing.intent
            let incomingIntentClass = terminalFlowPendingIntentClass incoming.intent
            let reducerClosed =
                match state.kernel.dispatch, state.kernel.exit with
                | KernelDispatchAccepted _, _
                | _, KernelExitWitnessed _ -> true
                | _ -> false
            let decision, reason =
                if reducerClosed then
                    TerminalFlowCandidateArbitrationClosed,
                    TerminalFlowCandidateReducerAlreadyClosed
                elif terminalFlowPendingCandidateIsExecutable incomingClass
                     && not (terminalFlowPendingCandidateIsExecutable existingClass) then
                    TerminalFlowIncomingCandidatePrecedesExisting,
                    TerminalFlowCandidateIncomingExecutableAuthority
                elif terminalFlowPendingCandidateIsExecutable existingClass
                     && not (terminalFlowPendingCandidateIsExecutable incomingClass) then
                    TerminalFlowExistingCandidatePrecedesIncoming,
                    TerminalFlowCandidateExistingExecutableAuthority
                elif terminalFlowPendingCandidateIsFinal incomingClass
                     && not (terminalFlowPendingCandidateIsFinal existingClass) then
                    TerminalFlowIncomingCandidatePrecedesExisting,
                    TerminalFlowCandidateIncomingFinalMaturity
                elif terminalFlowPendingCandidateIsFinal existingClass
                     && not (terminalFlowPendingCandidateIsFinal incomingClass) then
                    TerminalFlowExistingCandidatePrecedesIncoming,
                    TerminalFlowCandidateExistingFinalMaturity
                else
                    match existingIntentClass, incomingIntentClass with
                    | TerminalFlowPendingIntentProvisionalQuarantine, TerminalFlowPendingIntentProvisionalNoFurther ->
                        TerminalFlowIncomingCandidatePrecedesExisting,
                        TerminalFlowCandidateIncomingNoFurtherOverQuarantine
                    | TerminalFlowPendingIntentProvisionalNoFurther, TerminalFlowPendingIntentProvisionalQuarantine ->
                        TerminalFlowExistingCandidatePrecedesIncoming,
                        TerminalFlowCandidateExistingNoFurtherOverQuarantine
                    | _ ->
                        let latticeDecision, latticeReason, _, _ = terminalFlowOutcomeLatticeFor state existing incoming
                        match latticeDecision with
                        | TerminalFlowOutcomeLatticeExistingWins ->
                            TerminalFlowExistingCandidatePrecedesIncoming,
                            TerminalFlowCandidateOutcomeLattice latticeReason
                        | TerminalFlowOutcomeLatticeIncomingWins ->
                            TerminalFlowIncomingCandidatePrecedesExisting,
                            TerminalFlowCandidateOutcomeLattice latticeReason
                        | TerminalFlowOutcomeLatticeEquivalent ->
                            TerminalFlowEquivalentCandidateLaterReducerArrival,
                            TerminalFlowCandidateOutcomeLattice latticeReason
            { decision = decision
              reason = reason
              existingClass = existingClass
              incomingClass = incomingClass
              existingIntentClass = existingIntentClass
              incomingIntentClass = incomingIntentClass
              reducerClosed = reducerClosed }

        let private terminalFlowPreferIncomingPendingTerminal state existing incoming =
            match (terminalFlowPendingCandidateArbitrationFor state existing incoming).decision with
            | TerminalFlowIncomingCandidatePrecedesExisting
            | TerminalFlowEquivalentCandidateLaterReducerArrival -> true
            | TerminalFlowExistingCandidatePrecedesIncoming
            | TerminalFlowCandidateArbitrationClosed -> false

        let private terminalFlowReducerActorAdmitsIssue terminalRef fillRef actor =
            match actor with
            | TerminalFlowReducerActorVacant _ -> true
            | TerminalFlowReducerActorArmed wrapped ->
                let armed = terminalFlowPossessionPayload wrapped
                terminalFlowAuthorityRefValue armed.lineage.terminalRef = terminalRef
                && terminalFlowAuthorityRefValue armed.lineage.fillRef = fillRef
            | TerminalFlowReducerActorFilled _
            | TerminalFlowReducerActorSealed _
            | TerminalFlowReducerActorFailedClosed _ -> false

        let private terminalFlowGlobalArmPendingTerminal (state:TerminalFlowGlobalReducerState) (pending:TerminalFlowGlobalPendingTerminal) =
            match state.kernel.root, state.kernel.outcome, state.kernel.exit,
                  terminalFlowOutcomeInstallationAdmission state.outcomeInstallation,
                  terminalFlowOutcomeInstallationActorBinding state.outcomeInstallation with
            | KernelRootResolved(_, _, _), KernelOutcomeSealed(terminalReceiptRef, fillKey), KernelExitOpen,
              Some admission, Some actorBinding
                when terminalReceiptRef = pending.terminalReceiptRef
                     && fillKey = pending.fillKeyId
                     && admission.terminalReceiptRef = terminalReceiptRef
                     && admission.fillKey = fillKey
                     && terminalFlowAdmissionIdentitySame admission.identity pending.admissionIdentity
                     && terminalFlowAdmissionIdentityRef actorBinding.identity = terminalFlowAdmissionIdentityRef admission.identity
                     && actorBinding.actorRef = terminalFlowAdmissionActorRef admission.identity
                     && actorBinding.bindingReceiptRef = terminalFlowAdmissionActorBindingRef admission.identity
                     && terminalFlowPendingOutcomeIsFinal pending.intent
                     && terminalFlowPendingDispatchIsExecutable pending.dispatchAuthority
                     && terminalFlowPendingTerminalHasSealedTerminalOrder state pending
                     && (match state.qapOutcomeActorAuthority.handoff, state.qapOutcomeActorAuthority.actor with
                         | TerminalFlowFinalOutcomeHandoffDispatchReady(_, terminalRef, handoffFillRef, _), actor ->
                             terminalRef = terminalFlowIdentityRefDigest terminalReceiptRef
                             && handoffFillRef = TerminalFlowFillKeyId.digest fillKey
                             && terminalFlowReducerActorAdmitsIssue terminalRef handoffFillRef actor
                         | _ -> false) ->
                let requestIdentity = terminalFlowDispatchRequestIdentityFor pending.fillRef
                let requestRef = terminalFlowDispatchRequestIdentityRef requestIdentity
                let kernel =
                    terminalFlowKernelStateFor
                        state.kernel.revision
                        state.kernel.root
                        state.kernel.outcome
                        state.kernel.actor
                        (KernelDispatchAccepted requestIdentity)
                        state.kernel.exit
                { state with kernel = kernel }, true
            | _ -> state, false

        let private terminalFlowGlobalPendingTerminalNeedsDispatchRedrive (state:TerminalFlowGlobalReducerState) (pending:TerminalFlowGlobalPendingTerminal) =
            let terminalRef = terminalFlowIdentityRefDigest pending.terminalReceiptRef
            let fillRef = terminalFlowIdentityRefDigest pending.fillRef
            let reducerReady =
                match state.qapOutcomeActorAuthority.handoff, state.qapOutcomeActorAuthority.actor with
                | TerminalFlowFinalOutcomeHandoffDispatchReady(_, handoffTerminalRef, handoffFillRef, _), actor ->
                    handoffTerminalRef = terminalRef
                    && handoffFillRef = fillRef
                    && terminalFlowReducerActorAdmitsIssue handoffTerminalRef handoffFillRef actor
                | _ -> false
            match state.kernel.root, state.kernel.outcome, state.kernel.dispatch, state.kernel.exit with
            | KernelRootResolved(_, _, _), KernelOutcomeSealed(terminalReceiptRef, fillKey), KernelDispatchReady(dispatchIdentity, _, _), KernelExitOpen
            | KernelRootResolved(_, _, _), KernelOutcomeSealed(terminalReceiptRef, fillKey), KernelDispatchAccepted dispatchIdentity, KernelExitOpen
                when terminalFlowPendingDispatchIsExecutable pending.dispatchAuthority
                     && reducerReady
                     && terminalReceiptRef = pending.terminalReceiptRef
                     && fillKey = pending.fillKeyId
                     && terminalFlowDispatchRequestIdentityFillRef dispatchIdentity = pending.fillRef -> true
            | _ -> false

        // The actor join must consume the reducer-owned proof that originally
        // sealed dispatch admission. Re-minting a closure from pending scalar refs
        // creates a typed shadow whose certificate/recovery identities can diverge
        // after quiescence even though the underlying WorkDag is already closed.
        let private terminalFlowWorkDagTailClosureFor
            (state:TerminalFlowGlobalReducerState)
            (pending:TerminalFlowGlobalPendingTerminal) =
            match state.dispatchAdmission with
            | TerminalFlowDispatchAdmissionSealed admission
                when pending.intent = TerminalFlowPendingBuildOk
                     && admission.finalOutcome.intent = pending.intent
                     && admission.terminalReceiptRef = pending.terminalReceiptRef
                     && admission.fillKey = pending.fillKeyId
                     && terminalFlowAdmissionIdentitySame admission.identity pending.admissionIdentity
                     && admission.workDagTailProof.openOwnerCount = 0 ->
                match admission.ownerCertificate.closeReceipts with
                | [closeReceipt] ->
                    let snapshot = terminalFlowWorkDagTailSnapshot admission.workDagTailProof.workDagTail
                    let recoveryRef = terminalFlowIdentityRefDigest admission.queueRecovery.recoveryRef
                    let wakerEdgeRef =
                        terminalFlowMintedRefOf
                            "waker_edge_from_dispatch_admission_ref"
                            (FastRuntimeFormat.format "%u:%u:%u:%u" [| box admission.ownerCertificate.certificateRef; box admission.rootCapability.workDagCloseReceiptRef; box recoveryRef; box admission.rootCapability.rootReceiptRef |])
                    let closureReason =
                        match pending.admission with
                        | TerminalFlowPendingAdmissionReducerOwnerDebt _ -> TerminalFlowWorkDagClosedByReducerOwnerDebt
                        | TerminalFlowPendingAdmissionEvaluatorNotice _
                        | TerminalFlowPendingAdmissionSafetyWatchdog _ -> TerminalFlowWorkDagClosedByCanonicalTerminalReceipt
                    Some {
                        ownerRef = closeReceipt.closeKey.ownerRef
                        closeReceiptRef = admission.rootCapability.workDagCloseReceiptRef
                        closureReason = closureReason
                        ledgerSealRef = admission.ownerCertificate.certificateRef
                        wakerEdgeRef = wakerEdgeRef
                        remainingObligationCount = admission.workDagTailProof.openOwnerCount
                        drainPassCount = snapshot.drainPassCount
                        zeroDeltaStreak = snapshot.zeroDeltaStreak
                        queueOnlyRecovery = TerminalFlowQueueOnlyRecoveryReady(admission.rootCapability.workDagCloseReceiptRef, recoveryRef)
                        closedAtMs = admission.rootCapability.mintedAtMs
                    }
                | _ -> None
            // Failure, quarantine and no-further outcomes do not borrow the success
            // corridor. They require an explicit typed fail-closed receipt and can
            // never mint RootCapability<Resolved> by pretending the WorkDag closed.
            | _ -> None

        let private terminalFlowActorOutcomeJoinBuildResultFor
            (state:TerminalFlowGlobalReducerState)
            (pending:TerminalFlowGlobalPendingTerminal)
            : Result<TerminalFlowActorOutcomeJoin<TerminalFlowArmedOutcomeJoinedStage>, TerminalFlowNonEmptyEvidence<TerminalFlowActorOutcomeJoinMissing>> =
            let handoffTerminalRef = terminalFlowIdentityRefDigest pending.terminalReceiptRef
            let handoffFillRef = terminalFlowIdentityRefDigest pending.fillRef
            let workDagTailClosure = terminalFlowWorkDagTailClosureFor state pending
            let installedAdmission = terminalFlowOutcomeInstallationAdmission state.outcomeInstallation
            let actorBinding = terminalFlowOutcomeInstallationActorBinding state.outcomeInstallation
            let missing = ResizeArray<TerminalFlowActorOutcomeJoinMissing>()
            if not (terminalFlowPendingOutcomeIsFinal pending.intent) then
                missing.Add TerminalFlowActorOutcomeJoinPendingOutcomeNotFinal
            match pending.dispatchAuthority with
            | TerminalFlowPendingObserverProjection sourceRef -> missing.Add(TerminalFlowActorOutcomeJoinPendingDispatchObserverOnly sourceRef)
            | TerminalFlowPendingNativeExecutable _ -> ()
            match state.kernel.root with
            | KernelRootAwaitingEvaluator -> missing.Add TerminalFlowActorOutcomeJoinRootNotResolved
            | KernelRootResolved _ -> ()
            match state.kernel.outcome with
            | KernelOutcomeOpen -> missing.Add TerminalFlowActorOutcomeJoinOutcomeNotSealed
            | KernelOutcomeSealed _ -> ()
            match state.kernel.exit with
            | KernelExitOpen -> ()
            | KernelExitWitnessed _ -> missing.Add TerminalFlowActorOutcomeJoinExitNotOpen
            if Option.isNone workDagTailClosure then missing.Add TerminalFlowActorOutcomeJoinWorkDagTailClosureMissing
            if Option.isNone installedAdmission then missing.Add TerminalFlowActorOutcomeJoinInstalledAdmissionMissing
            if Option.isNone actorBinding then missing.Add TerminalFlowActorOutcomeJoinActorBindingMissing
            match state.dispatchAdmission with
            | TerminalFlowDispatchAdmissionOpen -> missing.Add TerminalFlowActorOutcomeJoinDispatchAdmissionNotSealed
            | TerminalFlowDispatchAdmissionSealed _ -> ()
            match state.kernel.root,
                  state.kernel.outcome,
                  state.kernel.exit,
                  workDagTailClosure,
                  installedAdmission,
                  actorBinding,
                  state.dispatchAdmission,
                  state.terminalOrderCutover with
            | KernelRootResolved(rootReceiptId, _, _), KernelOutcomeSealed(terminalReceiptId, fillKey), KernelExitOpen,
              Some workDagTailClosure, Some installedAdmission, Some actorBinding,
              TerminalFlowDispatchAdmissionSealed admission, cutover ->
                let admissionRef = terminalFlowAdmissionRawRef admission.identity
                let admissionIdentityRef = terminalFlowAdmissionIdentityRef admission.identity
                let actorBindingRef = terminalFlowAdmissionActorBindingRef admission.identity
                let credentialLedgerRef = terminalFlowAdmissionRequirementLedgerRef admission.identity
                match state.qapOutcomeActorAuthority.handoff, state.qapOutcomeActorAuthority.actor with
                | TerminalFlowFinalOutcomeHandoffDispatchReady(_, terminalRef, fillRef, _), actor ->
                    if terminalRef <> handoffTerminalRef then
                        missing.Add(TerminalFlowActorOutcomeJoinReducerHandoffTerminalMismatch(handoffTerminalRef, terminalRef))
                    if fillRef <> handoffFillRef then
                        missing.Add(TerminalFlowActorOutcomeJoinReducerHandoffFillMismatch(handoffFillRef, fillRef))
                    if terminalRef = handoffTerminalRef
                       && fillRef = handoffFillRef
                       && not (terminalFlowReducerActorAdmitsIssue terminalRef fillRef actor) then
                        missing.Add TerminalFlowActorOutcomeJoinReducerActorDoesNotAdmitIssue
                | _ ->
                    missing.Add TerminalFlowActorOutcomeJoinReducerHandoffNotDispatchReady
                if terminalReceiptId <> pending.terminalReceiptRef then missing.Add TerminalFlowActorOutcomeJoinPendingTerminalMismatch
                if fillKey <> pending.fillKeyId then missing.Add TerminalFlowActorOutcomeJoinPendingFillMismatch
                if installedAdmission.terminalReceiptRef <> terminalReceiptId then missing.Add TerminalFlowActorOutcomeJoinInstalledAdmissionTerminalMismatch
                if installedAdmission.fillKey <> fillKey then missing.Add TerminalFlowActorOutcomeJoinInstalledAdmissionFillMismatch
                if not (terminalFlowAdmissionIdentitySame installedAdmission.identity admission.identity) then missing.Add TerminalFlowActorOutcomeJoinAdmissionIdentityMismatch
                if not (terminalFlowAdmissionIdentitySame actorBinding.identity admission.identity) then missing.Add TerminalFlowActorOutcomeJoinAdmissionRefMismatch
                if actorBinding.actorRef <> terminalFlowAdmissionActorRef admission.identity then missing.Add TerminalFlowActorOutcomeJoinBoundActorMismatch
                if actorBinding.bindingReceiptRef <> actorBindingRef then missing.Add TerminalFlowActorOutcomeJoinActorBindingRefMismatch
                if terminalFlowAdmissionRequirementLedgerRef installedAdmission.identity <> credentialLedgerRef then missing.Add TerminalFlowActorOutcomeJoinCredentialLedgerRefMismatch
                if terminalFlowRootReceiptRef rootReceiptId <> terminalFlowRootReceiptRef admission.ownerWorkDagLineage.kernelRootReceiptRef
                   || admission.rootCapability.rootReceiptRef <> terminalFlowRootReceiptRef rootReceiptId then
                    missing.Add TerminalFlowActorOutcomeJoinKernelRootProofMismatch
                if terminalReceiptId <> admission.terminalReceiptRef
                   || fillKey <> admission.fillKey then
                    missing.Add TerminalFlowActorOutcomeJoinTerminalOutcomeProofMismatch
                if workDagTailClosure.closeReceiptRef <> admission.rootCapability.workDagCloseReceiptRef
                   || workDagTailClosure.ledgerSealRef <> admission.ownerCertificate.certificateRef
                   || workDagTailClosure.remainingObligationCount <> 0 then
                    missing.Add TerminalFlowActorOutcomeJoinWorkDagProofMismatch
                match workDagTailClosure.queueOnlyRecovery with
                | TerminalFlowQueueOnlyRecoveryReady(closeReceiptRef, recoveryRef)
                    when closeReceiptRef = admission.rootCapability.workDagCloseReceiptRef
                         && recoveryRef = terminalFlowIdentityRefDigest admission.queueRecovery.recoveryRef -> ()
                | _ -> missing.Add TerminalFlowActorOutcomeJoinQueueRecoveryProofMismatch
                match cutover |> Option.bind terminalFlowTerminalOrderCutoverAdmissionRef with
                | Some orderAdmissionRef when orderAdmissionRef = admissionRef -> ()
                | _ -> missing.Add TerminalFlowActorOutcomeJoinPredecessorOrderUnsatisfied
                if missing.Count > 0 then
                    Error(terminalFlowNonEmptyEvidenceOfList (List.ofSeq missing))
                else
                    let joinedAtMs = Environment.TickCount64
                    let tokenId = "terminal-stage:armed-outcome-joined:" + terminalFlowIdentityRefText rootReceiptId + ":" + terminalFlowIdentityRefText terminalReceiptId + ":" + TerminalFlowFillKeyId.text fillKey
                    let wakerEdge : TerminalFlowPushOwnedWakerEdge<TerminalFlowWakerRegisteredStage> = {
                        requirementRef = terminalFlowMintedRefOf "stage_token_waker_requirement_ref" (string credentialLedgerRef)
                        edgeRef = workDagTailClosure.wakerEdgeRef
                        actorRef = actorBinding.actorRef
                        registeredAtMs = joinedAtMs
                        consumedAtMs = 0L
                    }
                    Ok {
                        tokenId = tokenId
                        rootReceiptRef = rootReceiptId
                        terminalReceiptRef = terminalReceiptId
                        fillKey = fillKey
                        admissionIdentity = admission.identity
                        credentialGraph =
                            terminalFlowSchedulerGraphClosedFor
                                admission.lineage.closure.closureRef
                                credentialLedgerRef
                        fairnessRelease = admission.fairnessRelease
                        schedulerRelease = admission.schedulerRelease
                        terminalOrderAdmission =
                            terminalFlowSchedulerWitnessFor "terminal_scheduler_predecessor_order" admissionRef
                        actorPhase = DiagJson.PushActorArmed
                        workDagTailClosure = workDagTailClosure
                        rootCapability = admission.rootCapability
                        wakerEdge = wakerEdge
                        joinedAtMs = joinedAtMs
                    }
            | _ ->
                if missing.Count = 0 then missing.Add TerminalFlowActorOutcomeJoinStateShapeRejected
                Error(terminalFlowNonEmptyEvidenceOfList (List.ofSeq missing))

        let private terminalFlowConsumeHandoffBlockerFor (state:TerminalFlowGlobalReducerState) (pending:TerminalFlowGlobalPendingTerminal) =
            let blocked kind reason =
                TerminalFlowConsumeRequirementBlocked(terminalFlowConsumeRequirementBlocker state.credentialLedger kind reason Environment.TickCount64)
            if not (terminalFlowPendingDispatchIsExecutable pending.dispatchAuthority) then
                blocked TerminalFlowDispatchRequireFinalOutcome
                    ("observer_only_pending_not_dispatchable|authority=" + terminalFlowPendingDispatchAuthorityText pending.dispatchAuthority)
            elif not (terminalFlowPendingOutcomeIsFinal pending.intent) then
                blocked TerminalFlowDispatchRequireFinalOutcome "outcome_not_final"
            else
                match state.kernel.root, state.kernel.outcome, state.kernel.actor, state.kernel.exit with
                | KernelRootAwaitingEvaluator, _, _, _ ->
                    blocked TerminalFlowDispatchRequireRootCapability "root_missing"
                | _, KernelOutcomeOpen, _, _ ->
                    blocked TerminalFlowDispatchRequireTerminalOutcomeSealed "outcome_not_sealed"
                | _, _, _, KernelExitWitnessed _ ->
                    TerminalFlowConsumeExitAlreadyClosed(terminalFlowIdentityRefDigest pending.fillRef)
                | _, _, _, _ when not (terminalFlowPendingTerminalHasSealedTerminalOrder state pending) ->
                    let diagnosisText =
                        terminalFlowPredecessorOrderDiagnosisFor state pending
                        |> Option.map terminalFlowPredecessorOrderDiagnosisText
                        |> Option.defaultValue "PredecessorOrderLineageMismatchAfterAdmissionAndTerminalOrderMatch"
                    blocked TerminalFlowDispatchRequirePredecessorOrder diagnosisText
                | _, _, _, _ when Option.isNone (terminalFlowWorkDagTailClosureFor state pending) ->
                    blocked TerminalFlowDispatchRequireWorkDagTailClose "workdag_tail_closure_missing"
                | _, _, KernelActorNoop, _ ->
                    blocked TerminalFlowDispatchRequireActorBinding "actor_noop"
                | _, _, KernelActorArmed(DiagJson.PushActorArmed, actorFillKey, _), _ ->
                    match TerminalFlowActorFillBound actorFillKey with
                    | TerminalFlowActorFillBootstrapAwaitingOutcome ->
                        blocked TerminalFlowDispatchRequireActorBinding "actor_bootstrap_awaiting_outcome"
                    | TerminalFlowActorFillUnbound ->
                        blocked TerminalFlowDispatchRequireActorBinding "actor_unbound"
                    | TerminalFlowActorFillBound boundFillKey when boundFillKey <> pending.fillKeyId ->
                        TerminalFlowConsumeActorBoundElsewhere(
                            terminalFlowIdentityRefDigest pending.fillRef,
                            TerminalFlowFillKeyId.digest boundFillKey)
                    | _ ->
                        blocked TerminalFlowDispatchRequireActorBinding "actor_not_joinable"
                | _ ->
                    blocked TerminalFlowDispatchRequireActorBinding "actor_not_armed_for_consume"

        type TerminalFlowActorOutcomeJoinAssessment =
            | TerminalFlowActorOutcomeJoinReady of TerminalFlowActorOutcomeJoin<TerminalFlowArmedOutcomeJoinedStage>
            | TerminalFlowActorOutcomeJoinMissing of TerminalFlowNonEmptyEvidence<TerminalFlowActorOutcomeJoinMissing>

        let private terminalFlowActorOutcomeJoinAssessmentFor state pending =
            match terminalFlowActorOutcomeJoinBuildResultFor state pending with
            | Ok token -> TerminalFlowActorOutcomeJoinReady token
            | Error missing -> TerminalFlowActorOutcomeJoinMissing missing

        let private terminalFlowGlobalArmOrRedrivePendingTerminal
            (state:TerminalFlowGlobalReducerState)
            (pending:TerminalFlowGlobalPendingTerminal) =
            if not (terminalFlowPendingDispatchIsExecutable pending.dispatchAuthority) then
                let missing =
                    terminalFlowNonEmptyEvidence
                        (TerminalFlowActorOutcomeJoinPendingDispatchObserverOnly(
                            terminalFlowPendingDispatchAuthorityRef pending.dispatchAuthority))
                        []
                state, TerminalFlowConsumeHandoffBlocked(terminalFlowConsumeHandoffBlockerFor state pending, missing)
            elif not (terminalFlowPendingOutcomeIsFinal pending.intent) then
                let missing = terminalFlowNonEmptyEvidence TerminalFlowActorOutcomeJoinPendingOutcomeNotFinal []
                state, TerminalFlowConsumeHandoffBlocked(terminalFlowConsumeHandoffBlockerFor state pending, missing)
            else
                let armedState, _ = terminalFlowGlobalArmPendingTerminal state pending
                let blocked missing =
                    armedState, TerminalFlowConsumeHandoffBlocked(terminalFlowConsumeHandoffBlockerFor armedState pending, missing)
                match terminalFlowActorOutcomeJoinAssessmentFor armedState pending with
                | TerminalFlowActorOutcomeJoinReady token -> armedState, TerminalFlowConsumeHandoffReady token
                | TerminalFlowActorOutcomeJoinMissing _ when terminalFlowGlobalPendingTerminalNeedsDispatchRedrive armedState pending ->
                    match terminalFlowActorOutcomeJoinAssessmentFor armedState pending with
                    | TerminalFlowActorOutcomeJoinReady token -> armedState, TerminalFlowConsumeHandoffReady token
                    | TerminalFlowActorOutcomeJoinMissing missing -> blocked missing
                | TerminalFlowActorOutcomeJoinMissing missing -> blocked missing

        // Applied and owner-debt capabilities are minted only through recursive
        // pending lineage. An Applied envelope owns no frozen scalar identity: the
        // lineage may be superseded exactly once before affine issuance when the
        // installed admission proves the current final pending.
        let private terminalFlowAppliedPendingLineageSnapshotFor (pending:TerminalFlowGlobalPendingTerminal) =
            { pendingRef = terminalFlowPendingTerminalRef pending
              terminalRef = terminalFlowIdentityRefDigest pending.terminalReceiptRef
              fillRef = terminalFlowIdentityRefDigest pending.fillRef
              admissionRef = terminalFlowPendingAdmissionRef pending.admission
              dispatchAuthorityRef = terminalFlowPendingDispatchAuthorityRef pending.dispatchAuthority
              maturityRef = pending.intent |> terminalFlowPendingOutcomeMaturity |> terminalFlowOutcomeMaturityRef }

        let rec private terminalFlowAppliedPendingLineageDepth = function
            | TerminalFlowAppliedPendingCaptured _ -> 0
            | TerminalFlowAppliedPendingSupersededBeforeAffine(previous, _, _, _, _) ->
                1 + terminalFlowAppliedPendingLineageDepth previous

        let rec private terminalFlowAppliedPendingLineageRootRef = function
            | TerminalFlowAppliedPendingCaptured snapshot -> snapshot.pendingRef
            | TerminalFlowAppliedPendingSupersededBeforeAffine(previous, _, _, _, _) ->
                terminalFlowAppliedPendingLineageRootRef previous

        let private terminalFlowAppliedPendingLineageCurrentSnapshot = function
            | TerminalFlowAppliedPendingCaptured snapshot -> snapshot
            | TerminalFlowAppliedPendingSupersededBeforeAffine(_, current, _, _, _) -> current

        let private terminalFlowAppliedPendingLineageProofRef = function
            | TerminalFlowAppliedPendingCaptured snapshot -> snapshot.pendingRef
            | TerminalFlowAppliedPendingSupersededBeforeAffine(_, _, _, _, proofRef) -> proofRef

        let private terminalFlowAppliedPendingLineageText lineage =
            let current = terminalFlowAppliedPendingLineageCurrentSnapshot lineage
            FastRuntimeFormat.format "AppliedPendingLineage(root_pending_ref=%u|current_pending_ref=%u|terminal_ref=%u|fill_ref=%u|admission_ref=%u|dispatch_ref=%u|maturity_ref=%u|depth=%d|proof_ref=%u)" [| box (terminalFlowAppliedPendingLineageRootRef lineage); box current.pendingRef; box current.terminalRef; box current.fillRef; box current.admissionRef; box current.dispatchAuthorityRef; box current.maturityRef; box (terminalFlowAppliedPendingLineageDepth lineage); box (terminalFlowAppliedPendingLineageProofRef lineage) |]

        type private TerminalFlowAppliedPendingAffineBoundaryStage =
            | TerminalFlowAppliedPendingAfterDispatchIssue
            | TerminalFlowAppliedPendingAfterAffinePreparation
            | TerminalFlowAppliedPendingAfterStageTokenIssue
            | TerminalFlowAppliedPendingAfterStageTokenFill
            | TerminalFlowAppliedPendingAfterSealAuthorization
            | TerminalFlowAppliedPendingAfterExitAuthorization
            | TerminalFlowAppliedPendingAfterFailClosed

        let private terminalFlowAppliedPendingAffineBoundaryStageText = function
            | TerminalFlowAppliedPendingAfterDispatchIssue -> "DispatchIssued"
            | TerminalFlowAppliedPendingAfterAffinePreparation -> "AffinePrepared"
            | TerminalFlowAppliedPendingAfterStageTokenIssue -> "StageTokenIssued"
            | TerminalFlowAppliedPendingAfterStageTokenFill -> "StageTokenFilled"
            | TerminalFlowAppliedPendingAfterSealAuthorization -> "SealAuthorized"
            | TerminalFlowAppliedPendingAfterExitAuthorization -> "ExitAuthorized"
            | TerminalFlowAppliedPendingAfterFailClosed -> "FailClosed"

        type private TerminalFlowAppliedPendingRebaseBoundary =
            | TerminalFlowAppliedPendingRebaseOpenBeforeDispatchIssue of protocolAuthorityRef:uint32
            | TerminalFlowAppliedPendingRebaseClosedAfterDispatchIssue of protocolAuthorityRef:uint32 * stage:TerminalFlowAppliedPendingAffineBoundaryStage

        let private terminalFlowAppliedPendingRebaseBoundaryFor (state:TerminalFlowGlobalReducerState) =
            let authorityRef = terminalFlowDispatchLifecycleRef state.dispatchLifecycle
            match terminalFlowDispatchLifecycleProtocol state.dispatchLifecycle with
            | TerminalFlowProtocolAwaitRoot
            | TerminalFlowProtocolAwaitOutcome _
            | TerminalFlowProtocolAwaitInstallation _
            | TerminalFlowProtocolOutcomeInstalled _
            | TerminalFlowProtocolDispatchBlocked _
            | TerminalFlowProtocolDispatchReady _ ->
                TerminalFlowAppliedPendingRebaseOpenBeforeDispatchIssue authorityRef
            | TerminalFlowProtocolDispatchIssued _ ->
                TerminalFlowAppliedPendingRebaseClosedAfterDispatchIssue(authorityRef, TerminalFlowAppliedPendingAfterDispatchIssue)
            | TerminalFlowProtocolAffinePrepared _ ->
                TerminalFlowAppliedPendingRebaseClosedAfterDispatchIssue(authorityRef, TerminalFlowAppliedPendingAfterAffinePreparation)
            | TerminalFlowProtocolAffineIssued _ ->
                TerminalFlowAppliedPendingRebaseClosedAfterDispatchIssue(authorityRef, TerminalFlowAppliedPendingAfterStageTokenIssue)
            | TerminalFlowProtocolAffineFilled _ ->
                TerminalFlowAppliedPendingRebaseClosedAfterDispatchIssue(authorityRef, TerminalFlowAppliedPendingAfterStageTokenFill)
            | TerminalFlowProtocolSealAuthorized _ ->
                TerminalFlowAppliedPendingRebaseClosedAfterDispatchIssue(authorityRef, TerminalFlowAppliedPendingAfterSealAuthorization)
            | TerminalFlowProtocolExitAuthorized _ ->
                TerminalFlowAppliedPendingRebaseClosedAfterDispatchIssue(authorityRef, TerminalFlowAppliedPendingAfterExitAuthorization)
            | TerminalFlowProtocolFailClosed _ ->
                TerminalFlowAppliedPendingRebaseClosedAfterDispatchIssue(authorityRef, TerminalFlowAppliedPendingAfterFailClosed)

        type private TerminalFlowAppliedPendingLineageViolation =
            | TerminalFlowAppliedCurrentOutcomeNotFinal of maturityRef:uint32
            | TerminalFlowAppliedCurrentDispatchNotExecutable of dispatchAuthorityRef:uint32
            | TerminalFlowAppliedCapturedIntentRegressed of capturedMaturityRef:uint32 * currentMaturityRef:uint32
            | TerminalFlowAppliedInstalledReceiptMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedInstalledFillMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedInstalledAdmissionMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedPendingRebaseCrossedAffineBoundary of protocolAuthorityRef:uint32 * stage:TerminalFlowAppliedPendingAffineBoundaryStage

        type private TerminalFlowAppliedPendingLineageViolationPath =
            | TerminalFlowAppliedPendingLineageViolationLast of TerminalFlowAppliedPendingLineageViolation
            | TerminalFlowAppliedPendingLineageViolationMore of TerminalFlowAppliedPendingLineageViolation * TerminalFlowAppliedPendingLineageViolationPath

        let rec private terminalFlowAppliedPendingLineageViolationPathOf = function
            | [] -> None
            | [ violation ] -> Some(TerminalFlowAppliedPendingLineageViolationLast violation)
            | violation :: rest ->
                terminalFlowAppliedPendingLineageViolationPathOf rest
                |> Option.map (fun path -> TerminalFlowAppliedPendingLineageViolationMore(violation, path))

        let rec private terminalFlowAppliedPendingLineageViolationPathCount = function
            | TerminalFlowAppliedPendingLineageViolationLast _ -> 1
            | TerminalFlowAppliedPendingLineageViolationMore(_, rest) ->
                1 + terminalFlowAppliedPendingLineageViolationPathCount rest

        let private terminalFlowAppliedPendingLineageViolationText = function
            | TerminalFlowAppliedCurrentOutcomeNotFinal maturityRef ->
                sprintf "CurrentOutcomeNotFinal(maturity_ref=%u)" maturityRef
            | TerminalFlowAppliedCurrentDispatchNotExecutable dispatchAuthorityRef ->
                sprintf "CurrentDispatchNotExecutable(dispatch_ref=%u)" dispatchAuthorityRef
            | TerminalFlowAppliedCapturedIntentRegressed(capturedMaturityRef, currentMaturityRef) ->
                sprintf "CapturedIntentRegressed(captured_maturity_ref=%u|current_maturity_ref=%u)" capturedMaturityRef currentMaturityRef
            | TerminalFlowAppliedInstalledReceiptMismatch(expectedRef, observedRef) ->
                sprintf "InstalledReceiptMismatch(expected_ref=%u|observed_ref=%u)" expectedRef observedRef
            | TerminalFlowAppliedInstalledFillMismatch(expectedRef, observedRef) ->
                sprintf "InstalledFillMismatch(expected_ref=%u|observed_ref=%u)" expectedRef observedRef
            | TerminalFlowAppliedInstalledAdmissionMismatch(expectedRef, observedRef) ->
                sprintf "InstalledAdmissionMismatch(expected_ref=%u|observed_ref=%u)" expectedRef observedRef
            | TerminalFlowAppliedPendingRebaseCrossedAffineBoundary(protocolAuthorityRef, stage) ->
                sprintf "PendingRebaseCrossedAffineBoundary(protocol_ref=%u|stage=%s)"
                    protocolAuthorityRef
                    (terminalFlowAppliedPendingAffineBoundaryStageText stage)

        let rec private terminalFlowAppliedPendingLineageViolationPathText = function
            | TerminalFlowAppliedPendingLineageViolationLast violation ->
                terminalFlowAppliedPendingLineageViolationText violation
            | TerminalFlowAppliedPendingLineageViolationMore(violation, rest) ->
                terminalFlowAppliedPendingLineageViolationText violation
                + " -> "
                + terminalFlowAppliedPendingLineageViolationPathText rest

        type private TerminalFlowAppliedPendingLineageDecision =
            | TerminalFlowAppliedPendingLineageAccepted of TerminalFlowAppliedPendingLineage
            | TerminalFlowAppliedPendingLineageRejected of TerminalFlowAppliedPendingLineageViolationPath

        let private terminalFlowAppliedPendingLineageDecisionFor
            (state:TerminalFlowGlobalReducerState)
            (envelope:TerminalFlowQapPostCommitEnvelope<TerminalFlowQapAppliedAuthorityStage>)
            (captured:TerminalFlowGlobalPendingTerminal)
            (installed:TerminalFlowOutcomeAdmission)
            (current:TerminalFlowGlobalPendingTerminal) =
            let capturedSnapshot = terminalFlowAppliedPendingLineageSnapshotFor captured
            let currentSnapshot = terminalFlowAppliedPendingLineageSnapshotFor current
            let installedReceiptRef = terminalFlowIdentityRefDigest installed.terminalReceiptRef
            let installedFillRef = TerminalFlowFillKeyId.digest installed.fillKey
            let installedAdmissionRef = terminalFlowAdmissionRawRef installed.identity
            let exactCapture =
                captured.terminalReceiptRef = current.terminalReceiptRef
                && captured.fillRef = current.fillRef
                && captured.intent = current.intent
                && terminalFlowPendingAdmissionSame captured.admission current.admission
                && terminalFlowPendingDispatchAuthoritySame captured.dispatchAuthority current.dispatchAuthority
            let violations = ResizeArray<TerminalFlowAppliedPendingLineageViolation>()
            if installedReceiptRef <> currentSnapshot.terminalRef then
                violations.Add(TerminalFlowAppliedInstalledReceiptMismatch(currentSnapshot.terminalRef, installedReceiptRef))
            if installedFillRef <> currentSnapshot.fillRef then
                violations.Add(TerminalFlowAppliedInstalledFillMismatch(currentSnapshot.fillRef, installedFillRef))
            if installedAdmissionRef <> currentSnapshot.admissionRef then
                violations.Add(TerminalFlowAppliedInstalledAdmissionMismatch(currentSnapshot.admissionRef, installedAdmissionRef))
            if not (terminalFlowPendingOutcomeIsFinal current.intent) then
                violations.Add(TerminalFlowAppliedCurrentOutcomeNotFinal currentSnapshot.maturityRef)
            if not (terminalFlowPendingDispatchIsExecutable current.dispatchAuthority) then
                violations.Add(TerminalFlowAppliedCurrentDispatchNotExecutable currentSnapshot.dispatchAuthorityRef)
            if not (terminalFlowPendingIntentMonotoneCompatible captured.intent current.intent) then
                violations.Add(TerminalFlowAppliedCapturedIntentRegressed(capturedSnapshot.maturityRef, currentSnapshot.maturityRef))
            if exactCapture then
                match terminalFlowAppliedPendingLineageViolationPathOf (List.ofSeq violations) with
                | None -> TerminalFlowAppliedPendingLineageAccepted(TerminalFlowAppliedPendingCaptured capturedSnapshot)
                | Some path -> TerminalFlowAppliedPendingLineageRejected path
            else
                match terminalFlowAppliedPendingRebaseBoundaryFor state with
                | TerminalFlowAppliedPendingRebaseClosedAfterDispatchIssue(protocolAuthorityRef, stage) ->
                    violations.Add(TerminalFlowAppliedPendingRebaseCrossedAffineBoundary(protocolAuthorityRef, stage))
                | TerminalFlowAppliedPendingRebaseOpenBeforeDispatchIssue _ -> ()
                match terminalFlowAppliedPendingLineageViolationPathOf (List.ofSeq violations) with
                | Some path -> TerminalFlowAppliedPendingLineageRejected path
                | None ->
                    let protocolAuthorityRef = terminalFlowDispatchLifecycleRef state.dispatchLifecycle
                    let installedAdmissionIdentityRef = terminalFlowAdmissionIdentityRef installed.identity
                    let proofRef =
                        terminalFlowStableAuthorityRef (
                            TerminalFlowAppliedPendingLineageIdentity(
                                capturedSnapshot.pendingRef,
                                currentSnapshot.pendingRef,
                                installedAdmissionIdentityRef,
                                protocolAuthorityRef,
                                envelope.transaction.transactionRef,
                                envelope.exactOnceRef))
                    TerminalFlowAppliedPendingLineageAccepted(
                        TerminalFlowAppliedPendingSupersededBeforeAffine(
                            TerminalFlowAppliedPendingCaptured capturedSnapshot,
                            currentSnapshot,
                            installedAdmissionIdentityRef,
                            protocolAuthorityRef,
                            proofRef))

        let private terminalFlowEmitAppliedPendingLineageDecision decision =
            match decision with
            | TerminalFlowAppliedPendingLineageAccepted lineage ->
                let lineageText = terminalFlowAppliedPendingLineageText lineage
                let occurrenceCount, shouldEmit = sparseLogDecision ("terminal_qap_applied_pending_lineage|" + lineageText) 64L
                if shouldEmit then
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_qap_applied_pending_lineage_decided\",\"decision_du\":%s,\"lineage_depth\":%d,\"root_pending_ref\":%u,\"current_pending_ref\":%u,\"proof_ref\":%u,\"occurrence_count\":%d,\"sparse_policy\":\"state_first3_power2_every64\",\"authority\":\"recursive_pending_lineage_before_affine_issue\"}" [| box (DiagJson.esc lineageText); box (terminalFlowAppliedPendingLineageDepth lineage); box (terminalFlowAppliedPendingLineageRootRef lineage); box ((terminalFlowAppliedPendingLineageCurrentSnapshot lineage).pendingRef); box (terminalFlowAppliedPendingLineageProofRef lineage); box occurrenceCount |])
            | TerminalFlowAppliedPendingLineageRejected path ->
                let rejectionText = terminalFlowAppliedPendingLineageViolationPathText path
                let occurrenceCount, shouldEmit = sparseLogDecision ("terminal_qap_applied_pending_lineage_rejected|" + rejectionText) 64L
                if shouldEmit then
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_qap_applied_pending_lineage_rejected\",\"violations_du\":%s,\"violation_count\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"state_first3_power2_every64\",\"authority\":\"nonempty_typed_lineage_missing_evidence\"}" [| box (DiagJson.esc rejectionText); box (terminalFlowAppliedPendingLineageViolationPathCount path); box occurrenceCount |])

        let private terminalFlowAppliedCapabilityForLineage
            (envelope:TerminalFlowQapPostCommitEnvelope<TerminalFlowQapAppliedAuthorityStage>)
            (finalization:TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationHandoffEnqueuedStage>)
            (installed:TerminalFlowOutcomeAdmission)
            (pending:TerminalFlowGlobalPendingTerminal)
            lineage
            (appliedProof:TerminalFlowQapProofCertificate<TerminalFlowQapAppliedAuthorityStage>) =
            let pendingTerminalRef = terminalFlowPendingTerminalRef pending
            let terminalRef = terminalFlowPendingTerminalReceiptDigest pending
            let fillRef = terminalFlowPendingFillDigest pending
            let admissionRef = terminalFlowPendingAdmissionRef pending.admission
            let admissionIdentityRef = terminalFlowAdmissionIdentityRef installed.identity
            let lineageProofRef = terminalFlowAppliedPendingLineageProofRef lineage
            let capabilityRef =
                terminalFlowStableAuthorityRef (
                    TerminalFlowAppliedCapabilityWithLineageIdentity(
                        envelope.planRef,
                        finalization.transactionRef,
                        finalization.exactOnceRef,
                        envelope.exactOnceRef,
                        appliedProof.proofRef,
                        appliedProof.exactOnceRef,
                        lineageProofRef,
                        pendingTerminalRef,
                        terminalRef,
                        fillRef,
                        admissionRef,
                        admissionIdentityRef))
            TerminalFlowAppliedQapCapability {
                proof = appliedProof
                pendingLineage = lineage
                planRef = envelope.planRef
                finalizationTransactionRef = finalization.transactionRef
                finalizationExactOnceRef = finalization.exactOnceRef
                postCommitExactOnceRef = envelope.exactOnceRef
                pending = pending
                pendingTerminalRef = pendingTerminalRef
                terminalRef = terminalRef
                fillRef = fillRef
                admissionRef = admissionRef
                admissionIdentityRef = admissionIdentityRef
                capabilityRef = capabilityRef
                exactOnceRef =
                    terminalFlowStableAuthorityRef (
                        TerminalFlowAppliedCapabilityExactOnceWithLineageIdentity(
                            capabilityRef,
                            appliedProof.proofRef,
                            appliedProof.exactOnceRef,
                            lineageProofRef,
                            finalization.exactOnceRef,
                            envelope.exactOnceRef,
                            pendingTerminalRef,
                            terminalRef,
                            fillRef,
                            admissionRef,
                            admissionIdentityRef)) }

        let private terminalFlowOwnerDebtClosedWorldCapabilityBuildResultFor (state:TerminalFlowGlobalReducerState) =
            match state.qapPostCommit,
                  state.qapFinalization,
                  state.pendingTerminal,
                  state.ownerDebt,
                  state.kernel.root,
                  terminalFlowOutcomeInstallationAdmission state.outcomeInstallation with
            | TerminalFlowQapPostCommitIdle,
              TerminalFlowQapFinalizationIdle,
              TerminalFlowPendingSlotCandidate pending,
              TerminalFlowReducerOwnerDebtAccepted(_, decisionRef, closeReceiptRef),
              KernelRootResolved(rootReceiptId, _, _),
              Some installed
                when terminalFlowPendingOutcomeIsFinal pending.intent
                     && terminalFlowPendingDispatchIsExecutable pending.dispatchAuthority ->
                match pending.admission, terminalFlowAppliedPendingRebaseBoundaryFor state with
                | TerminalFlowPendingAdmissionReducerOwnerDebt permit,
                  TerminalFlowAppliedPendingRebaseOpenBeforeDispatchIssue protocolAuthorityRef
                    when permit.decisionRef = decisionRef
                         && permit.closeReceiptRef = closeReceiptRef
                         && terminalFlowAdmissionRawRef installed.identity = terminalFlowPendingAdmissionRef pending.admission
                         && installed.terminalReceiptRef = pending.terminalReceiptRef
                         && installed.fillKey = pending.fillKeyId ->
                    let snapshot = terminalFlowAppliedPendingLineageSnapshotFor pending
                    let lineage = TerminalFlowAppliedPendingCaptured snapshot
                    let lineageProofRef = terminalFlowAppliedPendingLineageProofRef lineage
                    let pendingTerminalRef = snapshot.pendingRef
                    let terminalRef = snapshot.terminalRef
                    let fillRef = snapshot.fillRef
                    let admissionRef = snapshot.admissionRef
                    let admissionIdentityRef = terminalFlowAdmissionIdentityRef installed.identity
                    let planRef =
                        terminalFlowStableAuthorityRef (
                            TerminalFlowOwnerDebtClosedWorldPlanIdentity(
                                decisionRef,
                                closeReceiptRef,
                                admissionIdentityRef))
                    let finalizationTransactionRef =
                        terminalFlowStableAuthorityRef (
                            TerminalFlowOwnerDebtClosedWorldFinalizationIdentity(
                                planRef,
                                decisionRef,
                                closeReceiptRef))
                    let finalizationExactOnceRef =
                        terminalFlowStableAuthorityRef (
                            TerminalFlowOwnerDebtClosedWorldFinalizationExactOnceIdentity(
                                finalizationTransactionRef,
                                closeReceiptRef))
                    let postCommitExactOnceRef =
                        terminalFlowStableAuthorityRef (
                            TerminalFlowOwnerDebtClosedWorldPostCommitExactOnceIdentity(
                                planRef,
                                finalizationExactOnceRef,
                                admissionIdentityRef))
                    let rootProofRef = terminalFlowRootReceiptRef rootReceiptId
                    let ownerDebtRatification =
                        terminalFlowForceOwnerCloseRatificationForQapPostCommit
                            decisionRef
                            rootProofRef
                            closeReceiptRef
                            decisionRef
                            finalizationTransactionRef
                    let ownerDebtTree =
                        TerminalFlowQapProofSeed planRef
                        |> fun previous -> TerminalFlowQapProofRoot(previous, rootProofRef)
                        |> fun previous -> TerminalFlowQapProofPending(previous, pendingTerminalRef)
                        |> fun previous -> TerminalFlowQapProofOwnerDebtClosedWorld(previous, decisionRef, closeReceiptRef)
                    let ownerDebtProof : TerminalFlowQapProofCertificate<TerminalFlowQapOwnerDebtAuthorityStage> =
                        terminalFlowQapOwnerDebtCertificateFor ownerDebtRatification ownerDebtTree postCommitExactOnceRef
                    let capabilityRef =
                        terminalFlowStableAuthorityRef (
                            TerminalFlowAppliedCapabilityWithLineageIdentity(
                                planRef,
                                finalizationTransactionRef,
                                finalizationExactOnceRef,
                                postCommitExactOnceRef,
                                ownerDebtProof.proofRef,
                                ownerDebtProof.exactOnceRef,
                                lineageProofRef,
                                pendingTerminalRef,
                                terminalRef,
                                fillRef,
                                admissionRef,
                                admissionIdentityRef))
                    terminalFlowEmitAppliedPendingLineageDecision (
                        TerminalFlowAppliedPendingLineageAccepted lineage)
                    Ok(
                        TerminalFlowOwnerDebtQapCapability {
                            proof = ownerDebtProof
                            pendingLineage = lineage
                            planRef = planRef
                            finalizationTransactionRef = finalizationTransactionRef
                            finalizationExactOnceRef = finalizationExactOnceRef
                            postCommitExactOnceRef = postCommitExactOnceRef
                            pending = pending
                            pendingTerminalRef = pendingTerminalRef
                            terminalRef = terminalRef
                            fillRef = fillRef
                            admissionRef = admissionRef
                            admissionIdentityRef = admissionIdentityRef
                            capabilityRef = capabilityRef
                            exactOnceRef =
                                terminalFlowStableAuthorityRef (
                                    TerminalFlowAppliedCapabilityExactOnceWithLineageIdentity(
                                        capabilityRef,
                                        ownerDebtProof.proofRef,
                                        ownerDebtProof.exactOnceRef,
                                        lineageProofRef,
                                        finalizationExactOnceRef,
                                        postCommitExactOnceRef,
                                        pendingTerminalRef,
                                        terminalRef,
                                        fillRef,
                                        admissionRef,
                                        admissionIdentityRef)) })
                | _ ->
                    Error (
                        terminalFlowQapMissingEvidenceSingleton (
                            TerminalFlowQapProofOwnerDebtCorridorRejected(
                                terminalFlowMintedRefOf "terminal_owner_debt_proof_rejected_ref" (sprintf "%u:%u" decisionRef closeReceiptRef))))
            | _ ->
                Error (terminalFlowQapMissingEvidenceSingleton TerminalFlowQapProofPostCommitNotApplied)

        let private terminalFlowQapPostCommitAppliedCapabilityBuildResultFor
            (state:TerminalFlowGlobalReducerState)
            : Result<TerminalFlowQapPostCommitAppliedCapability, TerminalFlowQapMissingEvidenceSet> =
            match state.qapPostCommit, state.qapFinalization, state.pendingTerminal with
            | TerminalFlowQapPostCommitApplied envelope,
              TerminalFlowQapFinalizationHandoffEnqueued finalization,
              TerminalFlowPendingSlotCandidate pending ->
                let finalizationMissing =
                    [ if finalization.transactionRef <> envelope.transaction.transactionRef then
                          TerminalFlowQapProofFinalizationTransactionMismatch(
                              envelope.transaction.transactionRef,
                              finalization.transactionRef)
                      if finalization.exactOnceRef <> envelope.transaction.exactOnceRef then
                          TerminalFlowQapProofFinalizationExactOnceMismatch(
                              envelope.transaction.exactOnceRef,
                              finalization.exactOnceRef) ]
                if not (List.isEmpty finalizationMissing) then
                    Error (terminalFlowQapMissingEvidenceSetOfList TerminalFlowQapProofDispositionReceiptConstruction envelope.proof.proofRef finalizationMissing)
                else
                    match envelope.pendingTerminal, terminalFlowOutcomeInstallationAdmission state.outcomeInstallation with
                    | TerminalFlowPendingSlotCandidate captured, Some installed ->
                        let lineageDecision = terminalFlowAppliedPendingLineageDecisionFor state envelope captured installed pending
                        terminalFlowEmitAppliedPendingLineageDecision lineageDecision
                        match lineageDecision with
                        | TerminalFlowAppliedPendingLineageAccepted lineage ->
                            terminalFlowAppliedCapabilityForLineage envelope finalization installed pending lineage envelope.proof
                            |> Ok
                        | TerminalFlowAppliedPendingLineageRejected path ->
                            Error (
                                terminalFlowQapMissingEvidenceSingleton (
                                    TerminalFlowQapProofPendingLineageRejected(
                                        terminalFlowMintedRefOf
                                            "terminal_pending_lineage_rejection_ref"
                                            (terminalFlowAppliedPendingLineageViolationPathText path))))
                    | _ -> Error (terminalFlowQapMissingEvidenceSingleton TerminalFlowQapProofMissingPendingTerminal)
            | TerminalFlowQapPostCommitAwaitingEvidence awaiting, _, _ ->
                Error awaiting.missingEvidence
            | TerminalFlowQapPostCommitIdle, _, _ ->
                terminalFlowOwnerDebtClosedWorldCapabilityBuildResultFor state
            | _ -> Error (terminalFlowQapMissingEvidenceSingleton TerminalFlowQapProofPostCommitNotApplied)

        type TerminalFlowOwnerDebtCorridorContradictionId =
            | TerminalFlowOwnerDebtCorridorNotRequiredAfterApplied
            | TerminalFlowOwnerDebtAcceptedWithoutPendingTerminal
            | TerminalFlowOwnerDebtPostCommitStateContradiction

        let private terminalFlowOwnerDebtCorridorContradictionText = function
            | TerminalFlowOwnerDebtCorridorNotRequiredAfterApplied -> "corridor_not_required_after_applied"
            | TerminalFlowOwnerDebtAcceptedWithoutPendingTerminal -> "accepted_owner_debt_without_pending_terminal"
            | TerminalFlowOwnerDebtPostCommitStateContradiction -> "post_commit_not_idle_or_applied"

        type TerminalFlowOwnerDebtCorridorEvidence =
            | TerminalFlowOwnerDebtCorridorClosed of decisionRef:uint32 * closeReceiptRef:uint32 * pendingTerminalRef:uint32
            | TerminalFlowOwnerDebtCorridorAwaitingObservation
            | TerminalFlowOwnerDebtCorridorAwaitingCertificate of decisionRef:uint32 * closeCapable:bool
            | TerminalFlowOwnerDebtCorridorAwaitingFinalPending of decisionRef:uint32 * closeReceiptRef:uint32
            | TerminalFlowOwnerDebtCorridorRejected of decisionRef:uint32 * reasonRef:uint32
            | TerminalFlowOwnerDebtCorridorContradiction of reason:TerminalFlowOwnerDebtCorridorContradictionId * evidenceRef:uint32

        let private terminalFlowOwnerDebtCorridorEvidenceText = function
            | TerminalFlowOwnerDebtCorridorClosed(decisionRef, closeReceiptRef, pendingTerminalRef) ->
                FastRuntimeFormat.format "Closed(decision_ref=%u|close_receipt_ref=%u|pending_ref=%u)" [| box decisionRef; box closeReceiptRef; box pendingTerminalRef |]
            | TerminalFlowOwnerDebtCorridorAwaitingObservation -> "AwaitingObservation"
            | TerminalFlowOwnerDebtCorridorAwaitingCertificate(decisionRef, closeCapable) ->
                sprintf "AwaitingCertificate(decision_ref=%u|close_capable=%b)" decisionRef closeCapable
            | TerminalFlowOwnerDebtCorridorAwaitingFinalPending(decisionRef, closeReceiptRef) ->
                sprintf "AwaitingFinalPending(decision_ref=%u|close_receipt_ref=%u)" decisionRef closeReceiptRef
            | TerminalFlowOwnerDebtCorridorRejected(decisionRef, reasonRef) ->
                sprintf "Rejected(decision_ref=%u|reason_ref=%u)" decisionRef reasonRef
            | TerminalFlowOwnerDebtCorridorContradiction(reason, evidenceRef) ->
                sprintf "Contradiction(reason=%s|evidence_ref=%u)" (terminalFlowOwnerDebtCorridorContradictionText reason) evidenceRef

        let private terminalFlowOwnerDebtCorridorEvidenceFor (state:TerminalFlowGlobalReducerState) =
            match state.qapPostCommit, state.ownerDebt, state.pendingTerminal with
            | TerminalFlowQapPostCommitApplied _, _, _ ->
                TerminalFlowOwnerDebtCorridorContradiction(TerminalFlowOwnerDebtCorridorNotRequiredAfterApplied, terminalFlowReducerOwnerDebtRef state.ownerDebt)
            | TerminalFlowQapPostCommitIdle, TerminalFlowReducerOwnerDebtAccepted(_, decisionRef, closeReceiptRef), TerminalFlowPendingSlotCandidate pending
                when terminalFlowPendingOutcomeIsFinal pending.intent ->
                TerminalFlowOwnerDebtCorridorClosed(decisionRef, closeReceiptRef, terminalFlowPendingTerminalRef pending)
            | TerminalFlowQapPostCommitIdle, TerminalFlowReducerOwnerDebtAccepted(_, decisionRef, closeReceiptRef), TerminalFlowPendingSlotCandidate _ ->
                TerminalFlowOwnerDebtCorridorAwaitingFinalPending(decisionRef, closeReceiptRef)
            | TerminalFlowQapPostCommitIdle, TerminalFlowReducerOwnerDebtAccepted(_, decisionRef, closeReceiptRef), TerminalFlowPendingSlotAwaitingCandidate ->
                TerminalFlowOwnerDebtCorridorContradiction(
                    TerminalFlowOwnerDebtAcceptedWithoutPendingTerminal,
                    terminalFlowMintedRefOf
                        "owner_debt_accepted_without_pending_ref"
                        (sprintf "%u:%u" decisionRef closeReceiptRef))
            | TerminalFlowQapPostCommitIdle, TerminalFlowReducerOwnerDebtObserved(_, decisionRef, decision), _ ->
                TerminalFlowOwnerDebtCorridorAwaitingCertificate(decisionRef, terminalFlowOwnerCloseDecisionCanMintCertificate decision)
            | TerminalFlowQapPostCommitIdle, TerminalFlowReducerOwnerDebtRejected(_, decisionRef, reasonRef), _ ->
                TerminalFlowOwnerDebtCorridorRejected(decisionRef, reasonRef)
            | TerminalFlowQapPostCommitIdle, TerminalFlowReducerOwnerDebtUnobserved, _ ->
                TerminalFlowOwnerDebtCorridorAwaitingObservation
            | _, ownerDebt, _ ->
                TerminalFlowOwnerDebtCorridorContradiction(TerminalFlowOwnerDebtPostCommitStateContradiction, terminalFlowReducerOwnerDebtRef ownerDebt)

        type TerminalFlowAppliedCapabilityAssessment =
            | TerminalFlowAppliedCapabilityReady of TerminalFlowQapPostCommitAppliedCapability
            | TerminalFlowAppliedCapabilityRejected of TerminalFlowQapMissingEvidenceSet

        let private terminalFlowQapPostCommitAppliedCapabilityAssessmentFor (state:TerminalFlowGlobalReducerState) =
            match terminalFlowQapPostCommitAppliedCapabilityBuildResultFor state with
            | Ok capability -> TerminalFlowAppliedCapabilityReady capability
            | Error missingEvidence -> TerminalFlowAppliedCapabilityRejected missingEvidence

        let private terminalFlowAppliedCapabilityAssessmentText = function
            | TerminalFlowAppliedCapabilityReady capability ->
                sprintf "Ready(capability_ref=%u|exact_once_ref=%u)" capability.capabilityRef capability.exactOnceRef
            | TerminalFlowAppliedCapabilityRejected missingEvidence ->
                sprintf "Rejected(missing=%s|count=%d)"
                    (terminalFlowQapMissingEvidenceText missingEvidence)
                    (terminalFlowQapMissingEvidenceCount missingEvidence)

        type TerminalFlowQapPostCommitIdleRecoveryDisposition =
            | TerminalFlowQapPostCommitIdleAwaitRevisionBound of idleForRevisions:int64 * requiredRevisions:int64
            | TerminalFlowQapPostCommitIdleAwaitQapWatch of idleForRevisions:int64
            | TerminalFlowQapPostCommitIdleSeedClosedGraphFixpoint of idleForRevisions:int64 * recoveryRef:uint32 * fixpointRef:TerminalFlowDurableRef<TerminalFlowQapFixpointReceiptRefKind> * fixpoint:TerminalFlowQapFixpointSet * sourceSnapshotRef:uint32
            | TerminalFlowQapPostCommitIdleReobserveFixpoint of idleForRevisions:int64 * recoveryRef:uint32 * watch:TerminalFlowGlobalQapMaturityWatch

        let private terminalFlowQapPostCommitIdleRecoveryRevisionBound = 4L
        let private terminalFlowQapPostCommitIdleWatchdogRevisionBound = 32L
        let private terminalFlowQapPostCommitIdleRecoveryRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<uint32, byte>()
        let private terminalFlowQapPostCommitIdleWatchdogRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<uint32, byte>()

        let private terminalFlowTryPublishQapIdleFailClosed
            (state:TerminalFlowGlobalReducerState)
            idleForRevisions =
            if idleForRevisions < terminalFlowQapPostCommitIdleWatchdogRevisionBound then false
            else
                let pendingRef =
                    match state.pendingTerminal with
                    | TerminalFlowPendingSlotCandidate pending -> terminalFlowPendingTerminalRef pending
                    | TerminalFlowPendingSlotAwaitingCandidate -> 0u
                let failureRef =
                    terminalFlowMintedRefOf
                        "terminal_qap_idle_watchdog_failure_ref"
                        (sprintf "%u" pendingRef)
                if terminalFlowQapPostCommitIdleWatchdogRegistry.TryAdd(failureRef, 0uy) then
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_dispatch_gate_unmet\",\"gate_du\":\"QapPostCommitAppliedRequired\",\"pending_terminal_ref\":%u,\"idle_for_revisions\":%d,\"watchdog_revision_bound\":%d,\"failure_ref\":%u,\"missing_inputs\":[\"qap_plan_ref\",\"finalization_transaction_ref\",\"post_commit_applied_capability\"],\"authority\":\"single_reducer_bounded_qap_watchdog\",\"next\":\"publish_single_terminal_actor_failure\"}" [| box pendingRef; box idleForRevisions; box terminalFlowQapPostCommitIdleWatchdogRevisionBound; box failureRef |])
                    DiagJson.publishTerminalOutcomeCandidateObserved
                        DiagJson.TerminalOutcomeCandidateFailClosed
                        ("terminal-qap-idle-watchdog:" + string failureRef)
                        ("pending-terminal:" + string pendingRef)
                        "TerminalQapPostCommitNotAttempted|plan_ref=0|transaction_ref=0"
                    true
                else false

        let private terminalFlowQapClosedWorkFixpointFor installedAtSequence (pendingIntent:TerminalFlowPendingTerminalIntent) (state:TerminalFlowGlobalReducerState) =
            match state.progressAuthority.accepted, state.authoritativeProgress with
            | Some evidence, Some progress ->
                let frontier = evidence.frontier
                let terminalSemanticWorkUnitForQap =
                    terminalFlowOutcomeInstallationAdmission state.outcomeInstallation
                    |> Option.map (fun admission -> terminalFlowTerminalSemanticWorkUnitOfRefs (terminalFlowIdentityRefDigest admission.terminalReceiptRef) (TerminalFlowFillKeyId.digest admission.fillKey))
                let semanticAuthorityOpenCountForQap =
                    CompilerKernelV2.SemanticWorkLedgerAuthority.creditDecisionForScope
                        CompilerKernelV2.SemanticWorkOperational
                    |> CompilerKernelV2.SemanticWorkCreditDecision.openUnitCount
                let physicallyClosed =
                    frontier.discovered <= frontier.retired
                    && frontier.blocked = 0L
                    && frontier.queueDepth = 0L
                    && frontier.activeWorkers = 0L
                let semanticSeedClosed =
                    terminalFlowSemanticSeedClosureEvidenceFor state |> Option.isSome
                let progressClosed =
                    (CompilerKernelV2.BasisPoints.value progress.progressLowBp = 10000L
                     && CompilerKernelV2.BasisPoints.value progress.progressMidBp = 10000L
                     && CompilerKernelV2.BasisPoints.value progress.progressHighBp = 10000L)
                    || (semanticSeedClosed && terminalSemanticWorkUnitForQap.IsSome && semanticAuthorityOpenCountForQap = 0)
                if physicallyClosed && progressClosed && semanticAuthorityOpenCountForQap > 0 then
                    let creditDecision =
                        CompilerKernelV2.SemanticWorkLedgerAuthority.creditDecisionForScope
                            CompilerKernelV2.SemanticWorkOperational
                    let creditDigest = CompilerKernelV2.SemanticWorkCreditDecision.digest creditDecision
                    let openUnits =
                        CompilerKernelV2.SemanticWorkCreditDecision.openUnitTexts creditDecision
                        |> List.truncate 12
                        |> String.concat ";"
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format
                            "{\"kind\":\"terminal_credit_return_blocked_by_open_semantic_units\",\"open_count\":%d,\"open_units\":%s,\"credit_digest\":%s,\"legacy_close_open_mutation\":false,\"authority\":\"per_work_unit_credit_must_retire_or_transfer\",\"next\":\"await_exact_once_work_receipts\"}"
                            [| box semanticAuthorityOpenCountForQap
                               box (DiagJson.esc openUnits)
                               box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text creditDigest)) |])
                    None
                elif physicallyClosed && progressClosed && semanticAuthorityOpenCountForQap = 0 then
                    let sourceSnapshotRef = terminalFlowIdentityRefDigest evidence.snapshotRef
                    let identity =
                        FastRuntimeFormat.format "%u:%d:%d:%d" [| box sourceSnapshotRef; box progress.denominatorRevision; box progress.semanticEpoch; box installedAtSequence |]
                    let fixpoint =
                        terminalFlowQapClosedGraphFixpointFor
                            identity
                            (max 0L (Environment.TickCount64 - evidence.observedAtMs))
                    let fixpointRef : TerminalFlowDurableRef<TerminalFlowQapFixpointReceiptRefKind> =
                        TerminalFlowDurableRef(terminalFlowQapLocalMintedRefOf "qap_closed_graph_fixpoint_receipt_ref" identity)
                    Some (fixpointRef, fixpoint, sourceSnapshotRef)
                else
                    None
            | _ -> None

        let private terminalFlowQapPostCommitIdleRecoveryDispositionFor (state:TerminalFlowGlobalReducerState) =
            match state.qapPostCommit, state.qapFinalization, state.pendingTerminal,
                  terminalFlowOutcomeInstallationSequence state.outcomeInstallation with
            | TerminalFlowQapPostCommitIdle,
              TerminalFlowQapFinalizationIdle,
              TerminalFlowPendingSlotCandidate pending,
              Some installedAtSequence
                when terminalFlowPendingOutcomeIsFinal pending.intent ->
                let idleForRevisions = max 0L (state.revision - installedAtSequence)
                match state.qapMaturityWatch with
                | None ->
                    match terminalFlowQapClosedWorkFixpointFor installedAtSequence pending.intent state with
                    | Some (fixpointRef, fixpoint, sourceSnapshotRef) ->
                        let recoveryRef =
                            terminalFlowMintedRefOf
                                "terminal_qap_post_commit_idle_closed_graph_seed_ref"
                                (sprintf "%u:%d" (terminalFlowDurableRefValue fixpointRef) installedAtSequence)
                        Some (TerminalFlowQapPostCommitIdleSeedClosedGraphFixpoint(idleForRevisions, recoveryRef, fixpointRef, fixpoint, sourceSnapshotRef))
                    | None when idleForRevisions < terminalFlowQapPostCommitIdleRecoveryRevisionBound ->
                        Some (TerminalFlowQapPostCommitIdleAwaitRevisionBound(idleForRevisions, terminalFlowQapPostCommitIdleRecoveryRevisionBound))
                    | None -> Some (TerminalFlowQapPostCommitIdleAwaitQapWatch idleForRevisions)
                | Some watch when idleForRevisions < terminalFlowQapPostCommitIdleRecoveryRevisionBound ->
                    Some (TerminalFlowQapPostCommitIdleAwaitRevisionBound(idleForRevisions, terminalFlowQapPostCommitIdleRecoveryRevisionBound))
                | Some watch ->
                    let replayFairness : TerminalFlowReducerFairnessState = state.replayFairness
                    let schedulerLease =
                        replayFairness.schedule.schedulerLease
                        |> terminalFlowAdmissionSchedulerLeaseCausalIdentity
                        |> terminalFlowAdmissionSchedulerLeaseCausalIdentityText
                    let recoveryDecision = terminalFlowQueueRecoveryDecisionText state.queueRecovery.decision
                    let recoveryRef =
                        terminalFlowMintedRefOf
                            "terminal_qap_post_commit_idle_reobserve_ref"
                            (FastRuntimeFormat.format "%u:%d:%s:%s" [| box (terminalFlowDurableRefValue watch.fixpointRef); box installedAtSequence; box recoveryDecision; box schedulerLease |])
                    Some (TerminalFlowQapPostCommitIdleReobserveFixpoint(idleForRevisions, recoveryRef, watch))
            | _ -> None

        type TerminalFlowAppliedCapabilityAuthorizationFailure =
            | TerminalFlowAppliedCapabilityDispatchNotPrepared
            | TerminalFlowAppliedCapabilityStateNotApplied
            | TerminalFlowAppliedCapabilityTransactionLineageMismatch
            | TerminalFlowAppliedCapabilityInternalAuthorityMismatch
            | TerminalFlowAppliedCapabilityTransitionOrdinalMismatch
            | TerminalFlowAppliedCapabilityRefMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedCapabilityExactOnceMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedCapabilityProofKindMismatch of expectedKind:TerminalFlowQapCapabilityProofKindId * observedKind:TerminalFlowQapCapabilityProofKindId
            | TerminalFlowAppliedCapabilityProofRefMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedCapabilityProofExactOnceMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedCapabilityPlanMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedCapabilityFinalizationMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedCapabilityAuthorizationFinalizationExactOnceMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedCapabilityPostCommitExactOnceMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedCapabilityPendingMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedCapabilityPendingPayloadMismatch
            | TerminalFlowAppliedCapabilityTerminalMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedCapabilityFillMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedCapabilityAdmissionMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowAppliedCapabilityAdmissionIdentityMismatch of expectedRef:uint32 * observedRef:uint32

        let private terminalFlowAppliedCapabilityAuthorizationFailureText = function
            | TerminalFlowAppliedCapabilityDispatchNotPrepared -> "dispatch_not_prepared"
            | TerminalFlowAppliedCapabilityStateNotApplied -> "post_commit_state_not_applied"
            | TerminalFlowAppliedCapabilityTransactionLineageMismatch -> "transaction_lineage_mismatch"
            | TerminalFlowAppliedCapabilityInternalAuthorityMismatch -> "internal_authority_mismatch"
            | TerminalFlowAppliedCapabilityTransitionOrdinalMismatch -> "transition_ordinal_mismatch"
            | TerminalFlowAppliedCapabilityRefMismatch(expectedRef, observedRef) -> sprintf "capability_ref_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowAppliedCapabilityExactOnceMismatch(expectedRef, observedRef) -> sprintf "capability_exact_once_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowAppliedCapabilityProofKindMismatch(expectedKind, observedKind) -> sprintf "capability_proof_kind_mismatch:%s:%s" (terminalFlowQapCapabilityProofKindText expectedKind) (terminalFlowQapCapabilityProofKindText observedKind)
            | TerminalFlowAppliedCapabilityProofRefMismatch(expectedRef, observedRef) -> sprintf "capability_proof_ref_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowAppliedCapabilityProofExactOnceMismatch(expectedRef, observedRef) -> sprintf "capability_proof_exact_once_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowAppliedCapabilityPlanMismatch(expectedRef, observedRef) -> sprintf "plan_ref_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowAppliedCapabilityFinalizationMismatch(expectedRef, observedRef) -> sprintf "finalization_transaction_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowAppliedCapabilityAuthorizationFinalizationExactOnceMismatch(expectedRef, observedRef) -> sprintf "finalization_exact_once_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowAppliedCapabilityPostCommitExactOnceMismatch(expectedRef, observedRef) -> sprintf "post_commit_exact_once_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowAppliedCapabilityPendingMismatch(expectedRef, observedRef) -> sprintf "pending_ref_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowAppliedCapabilityPendingPayloadMismatch -> "pending_payload_mismatch"
            | TerminalFlowAppliedCapabilityTerminalMismatch(expectedRef, observedRef) -> sprintf "terminal_ref_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowAppliedCapabilityFillMismatch(expectedRef, observedRef) -> sprintf "fill_ref_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowAppliedCapabilityAdmissionMismatch(expectedRef, observedRef) -> sprintf "admission_ref_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowAppliedCapabilityAdmissionIdentityMismatch(expectedRef, observedRef) -> sprintf "admission_identity_ref_mismatch:%u:%u" expectedRef observedRef

        let private terminalFlowAppliedCapabilityAuthorizationFor
            (state:TerminalFlowGlobalReducerState)
            (transaction:TerminalFlowAffineDispatchTransaction<TerminalFlowAffineDispatchPreparedStage>) =
            let failures = ResizeArray<TerminalFlowAppliedCapabilityAuthorizationFailure>()
            if not (terminalFlowAffineTransactionAuthorityInternallyConsistent transaction) then
                failures.Add TerminalFlowAppliedCapabilityInternalAuthorityMismatch
            match (terminalFlowDispatchLifecycleConstitution state.dispatchLifecycle) with
            | TerminalFlowDispatchAffinePrepared committed ->
                if not (terminalFlowAffineTransactionSameLineage committed transaction) then
                    failures.Add TerminalFlowAppliedCapabilityTransactionLineageMismatch
                if committed.transitionOrdinal <> TerminalFlowAffinePreparedOrdinal
                   || transaction.transitionOrdinal <> TerminalFlowAffinePreparedOrdinal then
                    failures.Add TerminalFlowAppliedCapabilityTransitionOrdinalMismatch
            | _ -> failures.Add TerminalFlowAppliedCapabilityDispatchNotPrepared
            match terminalFlowQapPostCommitAppliedCapabilityAssessmentFor state with
            | TerminalFlowAppliedCapabilityReady appliedCapability ->
                let observed = transaction.postCommitCapability
                if appliedCapability.capabilityRef <> observed.capabilityRef then
                    failures.Add(TerminalFlowAppliedCapabilityRefMismatch(appliedCapability.capabilityRef, observed.capabilityRef))
                if appliedCapability.exactOnceRef <> observed.exactOnceRef then
                    failures.Add(TerminalFlowAppliedCapabilityExactOnceMismatch(appliedCapability.exactOnceRef, observed.exactOnceRef))
                let expectedProofKind, expectedProofRef, expectedProofExactOnceRef, _ =
                    terminalFlowQapCapabilityProofProjection appliedCapability.proof
                let observedProofKind, observedProofRef, observedProofExactOnceRef, _ =
                    terminalFlowQapCapabilityProofProjection observed.proof
                if expectedProofKind <> observedProofKind then
                    failures.Add(TerminalFlowAppliedCapabilityProofKindMismatch(expectedProofKind, observedProofKind))
                if expectedProofRef <> observedProofRef then
                    failures.Add(TerminalFlowAppliedCapabilityProofRefMismatch(expectedProofRef, observedProofRef))
                if expectedProofExactOnceRef <> observedProofExactOnceRef then
                    failures.Add(TerminalFlowAppliedCapabilityProofExactOnceMismatch(expectedProofExactOnceRef, observedProofExactOnceRef))
                if appliedCapability.planRef <> observed.planRef then
                    failures.Add(TerminalFlowAppliedCapabilityPlanMismatch(appliedCapability.planRef, observed.planRef))
                if appliedCapability.finalizationTransactionRef <> observed.finalizationTransactionRef then
                    failures.Add(TerminalFlowAppliedCapabilityFinalizationMismatch(appliedCapability.finalizationTransactionRef, observed.finalizationTransactionRef))
                if appliedCapability.finalizationExactOnceRef <> observed.finalizationExactOnceRef then
                    failures.Add(TerminalFlowAppliedCapabilityAuthorizationFinalizationExactOnceMismatch(appliedCapability.finalizationExactOnceRef, observed.finalizationExactOnceRef))
                if appliedCapability.postCommitExactOnceRef <> observed.postCommitExactOnceRef then
                    failures.Add(TerminalFlowAppliedCapabilityPostCommitExactOnceMismatch(appliedCapability.postCommitExactOnceRef, observed.postCommitExactOnceRef))
                if appliedCapability.pendingTerminalRef <> observed.pendingTerminalRef then
                    failures.Add(TerminalFlowAppliedCapabilityPendingMismatch(appliedCapability.pendingTerminalRef, observed.pendingTerminalRef))
                if not (terminalFlowPendingTerminalAuthorityPayloadSame appliedCapability.pending observed.pending) then
                    failures.Add TerminalFlowAppliedCapabilityPendingPayloadMismatch
                if appliedCapability.terminalRef <> observed.terminalRef then
                    failures.Add(TerminalFlowAppliedCapabilityTerminalMismatch(appliedCapability.terminalRef, observed.terminalRef))
                if appliedCapability.fillRef <> observed.fillRef then
                    failures.Add(TerminalFlowAppliedCapabilityFillMismatch(appliedCapability.fillRef, observed.fillRef))
                if appliedCapability.admissionRef <> observed.admissionRef then
                    failures.Add(TerminalFlowAppliedCapabilityAdmissionMismatch(appliedCapability.admissionRef, observed.admissionRef))
                if appliedCapability.admissionIdentityRef <> observed.admissionIdentityRef then
                    failures.Add(TerminalFlowAppliedCapabilityAdmissionIdentityMismatch(appliedCapability.admissionIdentityRef, observed.admissionIdentityRef))
            | TerminalFlowAppliedCapabilityRejected _ -> failures.Add TerminalFlowAppliedCapabilityStateNotApplied
            if failures.Count = 0 then Ok () else Error (List.ofSeq failures)

        let private terminalFlowQapPostCommitAppliedWaitReason (state:TerminalFlowGlobalReducerState) =
            match state.qapPostCommit with
            | TerminalFlowQapPostCommitAwaitingEvidence awaiting ->
                TerminalFlowWaitQapPostCommitEvidence(
                    awaiting.planRef,
                    awaiting.transaction.transactionRef,
                    awaiting.missingEvidence)
            | _ ->
                let _, planRef, transactionRef, stageOrdinal, _ = terminalFlowQapPostCommitStateProjection state.qapPostCommit
                TerminalFlowWaitQapPostCommitApplied(planRef, transactionRef, stageOrdinal)

        type TerminalFlowOwnerDebtFairnessBridgeBlockReasonId =
            | TerminalFlowOwnerDebtBridgeAdmissionFairnessEpochMissing
            | TerminalFlowOwnerDebtBridgeOwnerClosedGreenPathNotMaterialized
            | TerminalFlowOwnerDebtBridgeDispatchConstitutionNotReady of TerminalFlowDispatchConstitutionState
            | TerminalFlowOwnerDebtBridgeQueueRecoveryNotReady of TerminalFlowQueueRecoveryReducerDecision * releaseRef:uint32 * physicalReleaseRef:uint32
            | TerminalFlowOwnerDebtBridgeFairnessOrSchedulerReleaseNotMinted

        let private terminalFlowOwnerDebtFairnessBridgeBlockReasonText = function
            | TerminalFlowOwnerDebtBridgeAdmissionFairnessEpochMissing ->
                "admission_fairness_epoch_missing"
            | TerminalFlowOwnerDebtBridgeOwnerClosedGreenPathNotMaterialized ->
                "owner_closed_green_path_not_materialized"
            | TerminalFlowOwnerDebtBridgeDispatchConstitutionNotReady constitution ->
                "dispatch_constitution_not_ready:" + terminalFlowDispatchConstitutionStateText constitution
            | TerminalFlowOwnerDebtBridgeQueueRecoveryNotReady(decision, releaseRef, physicalReleaseRef) ->
                FastRuntimeFormat.format "queue_recovery_not_ready:%s:release=%u:physical=%u" [| box (terminalFlowQueueRecoveryDecisionText decision); box releaseRef; box physicalReleaseRef |]
            | TerminalFlowOwnerDebtBridgeFairnessOrSchedulerReleaseNotMinted ->
                "fairness_or_scheduler_release_not_minted"

        type TerminalFlowOwnerDebtFairnessBridgeDisposition =
            | TerminalFlowOwnerDebtFairnessBridgeNotApplicable
            | TerminalFlowOwnerDebtFairnessBridgeAlreadyReady of releaseRef:uint32 * physicalReleaseRef:uint32
            | TerminalFlowOwnerDebtFairnessBridgeAlreadyReadyCycleDischarged of releaseRef:uint32 * physicalReleaseRef:uint32 * recoveryRef:uint32 * dischargedCredentialCycleRef:uint32
            | TerminalFlowOwnerDebtFairnessBridgeReconciled of releaseRef:uint32 * physicalReleaseRef:uint32 * recoveryRef:uint32 * dischargedCredentialCycleRef:uint32
            | TerminalFlowOwnerDebtFairnessBridgeBlocked of TerminalFlowOwnerDebtFairnessBridgeBlockReasonId

        let private terminalFlowOwnerDebtFairnessBridgeDispositionText = function
            | TerminalFlowOwnerDebtFairnessBridgeNotApplicable -> "NotApplicable"
            | TerminalFlowOwnerDebtFairnessBridgeAlreadyReady(releaseRef, physicalReleaseRef) ->
                sprintf "AlreadyReady(release_ref=%u|physical_release_ref=%u)" releaseRef physicalReleaseRef
            | TerminalFlowOwnerDebtFairnessBridgeAlreadyReadyCycleDischarged(releaseRef, physicalReleaseRef, recoveryRef, dischargedCredentialCycleRef) ->
                FastRuntimeFormat.format "AlreadyReadyCycleDischarged(release_ref=%u|physical_release_ref=%u|recovery_ref=%u|discharged_credential_cycle_ref=%u)" [| box releaseRef; box physicalReleaseRef; box recoveryRef; box dischargedCredentialCycleRef |]
            | TerminalFlowOwnerDebtFairnessBridgeReconciled(releaseRef, physicalReleaseRef, recoveryRef, dischargedCredentialCycleRef) ->
                FastRuntimeFormat.format "Reconciled(release_ref=%u|physical_release_ref=%u|recovery_ref=%u|discharged_credential_cycle_ref=%u)" [| box releaseRef; box physicalReleaseRef; box recoveryRef; box dischargedCredentialCycleRef |]
            | TerminalFlowOwnerDebtFairnessBridgeBlocked reason ->
                "Blocked(reason=" + terminalFlowOwnerDebtFairnessBridgeBlockReasonText reason + ")"

        let private terminalFlowGlobalOwnerDebtFairnessBridge
            (state:TerminalFlowGlobalReducerState)
            (capability:TerminalFlowQapPostCommitAppliedCapability) =
            let alreadyReady =
                match state.replayFairness.releaseReceipt, state.replayFairness.schedule.schedulerLease with
                | Some release, Some (TerminalFlowAdmissionSchedulerReleased schedulerRelease)
                    when release.admissionRef = capability.admissionRef
                         && release.admissionIdentityRef = capability.admissionIdentityRef
                         && schedulerRelease.admissionRef = release.admissionRef
                         && schedulerRelease.admissionIdentityRef = release.admissionIdentityRef
                         && terminalFlowIdentityRefDigest schedulerRelease.fairnessReleaseRef = terminalFlowIdentityRefDigest release.releaseRef
                         && Option.isSome state.greenPath
                         && (match (terminalFlowDispatchLifecycleConstitution state.dispatchLifecycle) with TerminalFlowDispatchConstitutionReady _ -> true | _ -> false)
                         && (match state.queueRecovery.decision with TerminalFlowQueueRecoveryReadyForReducerSeal _ -> true | _ -> false) ->
                    Some(release, schedulerRelease)
                | _ -> None
            let nextState, disposition =
                match alreadyReady with
                | Some(release, schedulerRelease) ->
                    match state.greenPath,
                          (terminalFlowDispatchLifecycleConstitution state.dispatchLifecycle),
                          state.queueRecovery.decision,
                          (state.credentialLedger |> Option.bind terminalFlowCredentialLedgerCycleProof) with
                    | Some _,
                      TerminalFlowDispatchConstitutionReady _,
                      TerminalFlowQueueRecoveryReadyForReducerSeal recovery,
                      Some cycleProof ->
                        { state with credentialLedger = None },
                        TerminalFlowOwnerDebtFairnessBridgeAlreadyReadyCycleDischarged(
                            terminalFlowIdentityRefDigest release.releaseRef,
                            terminalFlowIdentityRefDigest schedulerRelease.physicalReleaseRef,
                            terminalFlowIdentityRefDigest recovery.recoveryRef,
                            cycleProof.cycleRef)
                    | _ ->
                        state,
                        TerminalFlowOwnerDebtFairnessBridgeAlreadyReady(
                            terminalFlowIdentityRefDigest release.releaseRef,
                            terminalFlowIdentityRefDigest schedulerRelease.physicalReleaseRef)
                | None ->
                    match state.qapPostCommit, state.ownerDebt, state.progressAuthority.accepted with
                    | TerminalFlowQapPostCommitIdle,
                      TerminalFlowReducerOwnerDebtAccepted(_, decisionRef, closeReceiptRef),
                      Some evidence ->
                        let fairnessEpoch =
                            terminalFlowOutcomeInstallationFairnessEpoch evidence.observedAtMs state.outcomeInstallation
                        match fairnessEpoch with
                        | None ->
                            state,
                            TerminalFlowOwnerDebtFairnessBridgeBlocked TerminalFlowOwnerDebtBridgeAdmissionFairnessEpochMissing
                        | Some _ ->
                            let observedFairness =
                                terminalFlowFairnessAdvance fairnessEpoch state.topologyGate evidence state.replayFairness
                            let topologyGate, topologyTransition =
                                match state.topologyGate with
                                | TerminalFlowTopologyGateOpened transition -> state.topologyGate, Some transition
                                | TerminalFlowTopologyGateClosed ->
                                    let gateRef : TerminalFlowIdentityRef<TerminalFlowTopologyGateRefKind> =
                                        terminalFlowIdentityRefOfText (
                                            FastRuntimeFormat.format "owner-debt-fairness-bridge:%u:%u:%u:%u" [| box capability.planRef; box decisionRef; box closeReceiptRef; box capability.admissionIdentityRef |])
                                    let transition =
                                        { gateRef = gateRef
                                          cause = TerminalFlowTopologyGateOwnerLedgerClosed closeReceiptRef
                                          beforeQueueDepth = evidence.frontier.queueDepth
                                          afterQueueDepth = evidence.frontier.queueDepth
                                          progressSnapshotRef = evidence.snapshotRef
                                          openedAtMs = evidence.observedAtMs }
                                    TerminalFlowTopologyGateOpened transition, Some transition
                            let fairness, releaseAndScheduler =
                                match observedFairness.releaseReceipt, observedFairness.schedule.schedulerLease with
                                | Some release, Some (TerminalFlowAdmissionSchedulerReleased schedulerRelease) ->
                                    observedFairness, Some(release, schedulerRelease)
                                | _ ->
                                    let releaseCandidate =
                                        match observedFairness.verdict, topologyTransition with
                                        | Some (TerminalFlowFairnessReleasedByTopologyGate(sample, transition)), _ ->
                                            Some(sample, transition)
                                        | Some (TerminalFlowFairnessBalanced sample), Some transition
                                            when sample.queueDepth = 0L && sample.activeWorkers = 0L ->
                                            Some(sample, transition)
                                        | _ -> None
                                    match releaseCandidate with
                                    | None -> observedFairness, None
                                    | Some(sample, transition) ->
                                        let release =
                                            terminalFlowFairnessReleaseFor
                                                sample
                                                (TerminalFlowFairnessReleaseByTopologyGate transition.gateRef)
                                                evidence.observedAtMs
                                        let releasedVerdict = TerminalFlowFairnessReleasedByTopologyGate(sample, transition)
                                        let schedule =
                                            terminalFlowReplayDriverScheduleAdvance
                                                evidence.snapshotSequence
                                                releasedVerdict
                                                (Some release)
                                                observedFairness.schedule
                                        match schedule.schedulerLease with
                                        | Some (TerminalFlowAdmissionSchedulerReleased schedulerRelease) ->
                                            let nextEpoch =
                                                observedFairness.admissionEpoch
                                                |> Option.map (fun epoch ->
                                                    { epoch with
                                                        phase = TerminalFlowAdmissionFairnessReleased release.releaseRef
                                                        updatedAtMs = release.releasedAtMs
                                                        exactOnceRef =
                                                            terminalFlowStableAuthorityRef (
                                                                "owner_debt_fairness_epoch_release",
                                                                epoch.exactOnceRef,
                                                                terminalFlowIdentityRefDigest release.releaseRef) })
                                            let releaseCredential = TerminalFlowFairnessCredentialMinted release
                                            let reconciled =
                                                { observedFairness with
                                                    admissionEpoch = nextEpoch
                                                    verdict = Some (TerminalFlowFairnessBalanced sample)
                                                    releasedEvents = observedFairness.releasedEvents + (if Option.isNone observedFairness.releaseReceipt then 1L else 0L)
                                                    schedule = schedule
                                                    releaseReceipt = Some release
                                                    releaseCredential = releaseCredential
                                                    exactOnceRef =
                                                        terminalFlowStableAuthorityRef (
                                                            "owner_debt_fairness_bridge",
                                                            observedFairness.exactOnceRef,
                                                            terminalFlowIdentityRefDigest release.releaseRef,
                                                            terminalFlowIdentityRefDigest schedulerRelease.physicalReleaseRef,
                                                            capability.exactOnceRef) }
                                            reconciled, Some(release, schedulerRelease)
                                        | _ -> observedFairness, None
                            let queueRecovery =
                                terminalFlowQueueRecoveryAdvance
                                    state.revision
                                    topologyGate
                                    state.progressAuthority
                                    fairness
                                    state.queueRecovery
                            let reconciledState =
                                { state with
                                    topologyGate = topologyGate
                                    replayFairness = fairness
                                    queueRecovery = queueRecovery }
                            match releaseAndScheduler, queueRecovery.decision with
                            | Some(release, schedulerRelease), TerminalFlowQueueRecoveryReadyForReducerSeal recovery ->
                                let ownerCertificate, workDagProof =
                                    match reconciledState.ownerLedgerCloseCertificate, reconciledState.workDagTailCloseProof with
                                    | Some certificate, Some proof -> Some certificate, Some proof
                                    | _ ->
                                        match reconciledState.ownerWorkDagProducer with
                                        | Some producer ->
                                            let certificate, proof, _, _ = terminalFlowOwnerWorkDagProducedAuthorities producer
                                            certificate, proof
                                        | None -> None, None
                                let greenPath =
                                    match reconciledState.greenPath, reconciledState.pendingTerminal, ownerCertificate, workDagProof with
                                    | Some current, _, _, _ -> Some current
                                    | None, TerminalFlowPendingSlotCandidate pending, Some certificate, Some proof ->
                                        let workDagProofRef = uint32 (terminalFlowOwnerLedgerProtocolIdValue proof.proofRef)
                                        let recoveryRef = terminalFlowIdentityRefDigest recovery.recoveryRef
                                        let pendingReceiptRef = terminalFlowMintedRefOf "pending_terminal_receipt_ref" pending.terminalReceiptId
                                        let permitRef =
                                            terminalFlowStableAuthorityRef (
                                                TerminalFlowQapPostCommitForceClosePermitIdentity(
                                                    capability.planRef,
                                                    certificate.certificateRef,
                                                    workDagProofRef,
                                                    recoveryRef,
                                                    pendingReceiptRef))
                                        let ownerCloseReceiptId = sprintf "owner-close:owner-debt-fairness-bridge:%u" permitRef
                                        let workDagCloseReceipt : TerminalFlowIdentityRef<TerminalFlowWorkDagTailCloseReceiptRefKind> =
                                            terminalFlowIdentityRefOfText (sprintf "owner-debt-fairness-workdag-close:%u" workDagProofRef)
                                        let tx : TerminalFlowForceOwnerCloseTransaction =
                                            { ratification =
                                                terminalFlowForceOwnerCloseRatificationForQapPostCommit
                                                    permitRef
                                                    certificate.certificateRef
                                                    workDagProofRef
                                                    recoveryRef
                                                    capability.planRef
                                              ownerCloseReceiptId = ownerCloseReceiptId
                                              workDagTailCloseReceipt = workDagCloseReceipt
                                              queueOnlyRecoveryReady = true
                                              fillOnceReadyWitnessRef = terminalFlowMintedRefOf "fill_once_ready_witness_ref" ownerCloseReceiptId }
                                        let opened = terminalFlowGreenPathOpenFor (TerminalFlowFillKeyId.ofRef pending.fillRef) tx
                                        match terminalFlowGreenPathConsumeQueueRecovery recovery.recoveryRef recovery.gate opened with
                                        | Ok(_, writerBound) -> Some writerBound
                                        | Error _ -> Some opened
                                    | _ -> None
                                let bridgedState =
                                    { reconciledState with
                                        greenPath = greenPath
                                        ownerLedgerCloseCertificate = ownerCertificate
                                        workDagTailCloseProof = workDagProof }
                                    |> terminalFlowDispatchConstitutionRefresh
                                match bridgedState.greenPath, (terminalFlowDispatchLifecycleConstitution bridgedState.dispatchLifecycle) with
                                | Some _, TerminalFlowDispatchConstitutionReady _ ->
                                    let dischargedCredentialCycleRef =
                                        bridgedState.credentialLedger
                                        |> Option.bind terminalFlowCredentialLedgerCycleProof
                                        |> Option.map (fun proof -> proof.cycleRef)
                                        |> Option.defaultValue 0u
                                    let dischargeState =
                                        if dischargedCredentialCycleRef = 0u then bridgedState
                                        else { bridgedState with credentialLedger = None }
                                    dischargeState,
                                    TerminalFlowOwnerDebtFairnessBridgeReconciled(
                                        terminalFlowIdentityRefDigest release.releaseRef,
                                        terminalFlowIdentityRefDigest schedulerRelease.physicalReleaseRef,
                                        terminalFlowIdentityRefDigest recovery.recoveryRef,
                                        dischargedCredentialCycleRef)
                                | None, _ ->
                                    bridgedState,
                                    TerminalFlowOwnerDebtFairnessBridgeBlocked TerminalFlowOwnerDebtBridgeOwnerClosedGreenPathNotMaterialized
                                | Some _, constitution ->
                                    bridgedState,
                                    TerminalFlowOwnerDebtFairnessBridgeBlocked(
                                        TerminalFlowOwnerDebtBridgeDispatchConstitutionNotReady constitution)
                            | Some(release, schedulerRelease), decision ->
                                reconciledState,
                                TerminalFlowOwnerDebtFairnessBridgeBlocked(
                                    TerminalFlowOwnerDebtBridgeQueueRecoveryNotReady(
                                        decision,
                                        terminalFlowIdentityRefDigest release.releaseRef,
                                        terminalFlowIdentityRefDigest schedulerRelease.physicalReleaseRef))
                            | None, _ ->
                                reconciledState,
                                TerminalFlowOwnerDebtFairnessBridgeBlocked TerminalFlowOwnerDebtBridgeFairnessOrSchedulerReleaseNotMinted
                    | _ -> state, TerminalFlowOwnerDebtFairnessBridgeNotApplicable
            let dispositionText = terminalFlowOwnerDebtFairnessBridgeDispositionText disposition
            let greenPathRef = nextState.greenPath |> Option.map terminalFlowGreenPathReceiptRef |> Option.defaultValue 0u
            let constitutionText = terminalFlowDispatchConstitutionStateText (terminalFlowDispatchLifecycleConstitution nextState.dispatchLifecycle)
            let bridgeOccurrence, emitBridge =
                DiagJson.sparseLogDecision
                    (FastRuntimeFormat.format "owner_debt_fairness_bridge|%u|%s|%u|%s" [| box capability.capabilityRef; box dispositionText; box greenPathRef; box constitutionText |])
                    256L
            if emitBridge then
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_owner_debt_fairness_bridge\",\"disposition_du\":%s,\"capability_ref\":%u,\"admission_ref\":%u,\"admission_identity_ref\":%u,\"green_path_ref\":%u,\"dispatch_constitution_du\":%s,\"dispatch_constitution_ref\":%u,\"occurrence_count\":%d,\"sparse_policy\":\"state_first3_power2_every256\",\"authority\":\"owner_debt_closed_world_plus_balanced_physical_quiescence\",\"next\":\"retry_dispatch_admission_with_reconciled_fairness_and_constitution\"}" [| box (DiagJson.esc dispositionText); box capability.capabilityRef; box capability.admissionRef; box capability.admissionIdentityRef; box greenPathRef; box (DiagJson.esc constitutionText); box (terminalFlowMintedRefOf "owner_debt_fairness_bridge_constitution_ref" constitutionText); box bridgeOccurrence |])
            nextState

        let private terminalFlowGlobalConsumeHandoff
            (state:TerminalFlowGlobalReducerState)
            (capability:TerminalFlowQapPostCommitAppliedCapability)
            (ratifiedHandoff:TerminalFlowNativeHandoffId option) =
            let state = terminalFlowGlobalOwnerDebtFairnessBridge state capability
            let pending = capability.pending
            let state, pending, capability =
                match terminalFlowPendingPromotionFor state.queueRecovery.decision pending, state.breakthroughConvergence.promotable with
                | (TerminalFlowPendingPromotionReady(priorIntent, promoted, recoveryRef) as promotion), Some _
                    when priorIntent <> TerminalFlowPendingBuildOk ->
                    let promotedState, installationReceipt =
                        terminalFlowGlobalInstallPromotedPending state promoted
                    match terminalFlowQapPostCommitAppliedCapabilityAssessmentFor promotedState with
                    | TerminalFlowAppliedCapabilityReady promotedCapability ->
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_outcome_promotion_transition\",\"promotion_du\":%s,\"source_du\":\"consume_handoff_convergence\",\"promotable\":true,\"recovery_ref\":%u,\"prior_pending_ref\":%u,\"promoted_pending_ref\":%u,\"prior_capability_ref\":%u,\"promoted_capability_ref\":%u,\"prior_installation_ref\":%u,\"installation_ref\":%u,\"installation_refreshed\":%b,\"installation_payload_matches_pending\":%b,\"prior_kernel_outcome_ref\":%u,\"kernel_outcome_ref\":%u,\"kernel_outcome_refreshed\":%b,\"owner\":\"single_reducer_promotion_boundary\"}" [| box (DiagJson.esc (terminalFlowPendingPromotionText promotion)); box (terminalFlowIdentityRefDigest recoveryRef); box capability.pendingTerminalRef; box promotedCapability.pendingTerminalRef; box capability.capabilityRef; box promotedCapability.capabilityRef; box installationReceipt.priorInstallationRef; box installationReceipt.installationRef; box installationReceipt.installationRefreshed; box installationReceipt.installationPayloadMatchesPending; box installationReceipt.priorKernelOutcomeRef; box installationReceipt.kernelOutcomeRef; box installationReceipt.kernelOutcomeRefreshed |])
                        promotedState, promoted, promotedCapability
                    | missing ->
                        DiagJson.emitTerminalJsonDurable (
                            sprintf "{\"kind\":\"terminal_outcome_promotion_capability_rejected\",\"promotion_du\":%s,\"capability_assessment_du\":%s,\"owner\":\"single_reducer_promotion_boundary\",\"next\":\"retain_pre_promotion_capability\"}"
                                (DiagJson.esc (terminalFlowPendingPromotionText promotion))
                                (DiagJson.esc (terminalFlowAppliedCapabilityAssessmentText missing)))
                        state, pending, capability
                | _ -> state, pending, capability
            let state, admissionDecision = terminalFlowTryMintDispatchAdmission state pending
            // The compatibility affine lifecycle is now a projection of the sealed
            // recursive proof. Refresh only after the proof state has been updated.
            let state = terminalFlowDispatchConstitutionRefresh state
            match admissionDecision with
            | TerminalFlowDispatchAdmissionMinted certificate ->
                let requirementsText = terminalFlowDispatchRequirementSpineText certificate.requirements
                let producerCertificateRef = certificate.ownerCertificate.certificateRef
                let producerTailRef = terminalFlowWorkDagTailRef certificate.workDagTailProof.workDagTail
                let producerRootCapabilityRef = certificate.rootCapability.capabilityRef
                let producerCloseReceiptRef = certificate.rootCapability.workDagCloseReceiptRef
                let producerText =
                    FastRuntimeFormat.format "OwnerWorkDag(RecursiveDispatchProof|certificate_ref=%u|tail_ref=%u|root_capability_ref=%u|recovery_ref=%u)" [| box producerCertificateRef; box producerTailRef; box producerRootCapabilityRef; box (terminalFlowIdentityRefDigest certificate.queueRecovery.recoveryRef) |]
                let dispatchIdentity = certificate.identity
                let dispatchAdmissionRef = terminalFlowAdmissionRawRef dispatchIdentity
                let dispatchAdmissionIdentityRef = terminalFlowAdmissionIdentityRef dispatchIdentity
                let dispatchActorRef = terminalFlowAdmissionActorRef dispatchIdentity
                let dispatchActorBindingRef = terminalFlowAdmissionActorBindingRef dispatchIdentity
                let dispatchCredentialLedgerRef = terminalFlowAdmissionRequirementLedgerRef dispatchIdentity
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_dispatch_admission_minted\",\"admission_ref\":%u,\"admission_identity_ref\":%u,\"bound_actor_ref\":%u,\"actor_binding_ref\":%u,\"credential_ledger_ref\":%u,\"credential_graph_closure_ref\":%u,\"constitution_ref\":%u,\"final_outcome_ref\":%u,\"terminal_outcome_ref\":%u,\"fill_ref\":%u,\"owner_admission_ref\":%u,\"queue_recovery_ref\":%u,\"breakthrough_ref\":%u,\"fairness_release_ref\":%u,\"scheduler_lease_ref\":%u,\"scheduler_physical_release_ref\":%u,\"green_path_ref\":%u,\"green_path_witness_stage_du\":%s,\"predecessor_ref\":%u,\"exact_once_ref\":%u,\"requirements_du\":%s,\"reducer_sequence\":%d,\"minted_at_ms\":%d,\"authority\":\"recursive_dispatch_proof_projection_only\"}" [| box dispatchAdmissionRef; box dispatchAdmissionIdentityRef; box dispatchActorRef; box dispatchActorBindingRef; box dispatchCredentialLedgerRef; box certificate.lineage.closure.closureRef; box certificate.constitution.constitutionRef; box (terminalFlowIdentityRefDigest certificate.finalOutcome.maturityRef); box (terminalFlowIdentityRefDigest certificate.terminalReceiptRef); box (TerminalFlowFillKeyId.digest certificate.fillKey); box certificate.ownerCertificate.certificateRef; box (terminalFlowIdentityRefDigest certificate.queueRecovery.recoveryRef); box certificate.breakthrough.certificateRef; box (terminalFlowIdentityRefDigest certificate.fairnessRelease.releaseRef); box (terminalFlowIdentityRefDigest certificate.schedulerRelease.leaseRef); box (terminalFlowIdentityRefDigest certificate.schedulerRelease.physicalReleaseRef); box certificate.greenPathWitness.receipt.receiptRef; box (DiagJson.esc (terminalFlowDispatchGreenPathWitnessStageText certificate.greenPathWitness)); box certificate.predecessorOrderWitness.receipt.receiptRef; box certificate.exactOnceRef; box (DiagJson.esc requirementsText); box certificate.reducerSequence; box certificate.mintedAtMs |])
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_credential_ledger_sealed\",\"admission_ref\":%u,\"admission_identity_ref\":%u,\"credential_ledger_ref\":%u,\"bound_actor_ref\":%u,\"actor_binding_ref\":%u,\"requirements_du\":%s,\"reducer_sequence\":%d,\"authority\":\"recursive_dispatch_proof_projection_only\"}" [| box dispatchAdmissionRef; box dispatchAdmissionIdentityRef; box dispatchCredentialLedgerRef; box dispatchActorRef; box dispatchActorBindingRef; box (DiagJson.esc requirementsText); box certificate.reducerSequence |])
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_seal_credentials\",\"state_du\":\"DispatchAdmissionSealed\",\"requirements_du\":%s,\"owner_workdag_producer_du\":%s,\"admission_ref\":%u,\"constitution_ref\":%u,\"owner_certificate_ref\":%u,\"workdag_tail_ref\":%u,\"workdag_close_receipt_ref\":%u,\"root_capability_ref\":%u,\"queue_recovery_ref\":%u,\"green_path_ref\":%u,\"predecessor_ref\":%u,\"owner\":\"single_reducer_credential_ledger\"}" [| box (DiagJson.esc requirementsText); box (DiagJson.esc producerText); box dispatchAdmissionRef; box certificate.constitution.constitutionRef; box producerCertificateRef; box producerTailRef; box producerCloseReceiptRef; box producerRootCapabilityRef; box (terminalFlowIdentityRefDigest certificate.queueRecovery.recoveryRef); box certificate.greenPathWitness.receipt.receiptRef; box certificate.predecessorOrderWitness.receipt.receiptRef |])
                terminalFlowEmitAdvancedConsoleProjection {
                    lane = TerminalFlowConsoleLaneExitSeal
                    sequence = state.revision
                    progressBp = 9996
                    etaMs = None
                    title = "dispatch admission sealed before consume"
                    detail = terminalFlowDispatchAdmissionCertificateText certificate
                    authorityRef = dispatchAdmissionRef
                }
            | TerminalFlowDispatchAdmissionReused _ -> ()
            | TerminalFlowDispatchAdmissionBlocked blocker ->
                let requirementKind, requirementRef, satisfierRef, blockerRef, blockerAgeMs, blockerReason =
                    terminalFlowDispatchAdmissionBlockerFields blocker
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_dispatch_admission_blocked\",\"blocking_requirement_du\":%s,\"blocking_requirement_ref\":%u,\"blocking_satisfier_ref\":%u,\"blocking_credential_ref\":%u,\"blocking_credential_age_ms\":%d,\"blocking_reason\":%s,\"blocker_du\":%s,\"owner\":\"single_reducer_credential_ledger\"}" [| box (DiagJson.esc requirementKind); box requirementRef; box satisfierRef; box blockerRef; box blockerAgeMs; box (DiagJson.esc blockerReason); box (DiagJson.esc (terminalFlowDispatchAdmissionBlockerText blocker)) |])
                terminalFlowEmitAdvancedConsoleProjection {
                    lane = TerminalFlowConsoleLaneExitSeal
                    sequence = state.revision
                    progressBp = 9950
                    etaMs = None
                    title = "dispatch admission awaiting typed prerequisite"
                    detail = terminalFlowDispatchAdmissionBlockerText blocker
                    authorityRef = blockerRef
                }
            let state, terminalOrderReceipt = terminalFlowTryMintRetainedTerminalOrder state pending
            match terminalOrderReceipt with
            | Some receipt ->
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_order_prerequisites_minted\",\"receipt_ref\":%u,\"owner_certificate_ref\":%u,\"workdag_tail_ref\":%u,\"qap_resolution_ref\":%u,\"authority\":\"retained_typed_evidence_minter\"}" [| box receipt.receiptRef; box receipt.ownerCertificateRef; box receipt.workDagTailRef; box receipt.qapResolutionRef |])
                match state.dispatchAdmission,
                      terminalFlowOutcomeInstallationAdmission state.outcomeInstallation,
                      terminalFlowOutcomeInstallationActorBinding state.outcomeInstallation,
                      state.terminalOrderCutover with
                | TerminalFlowDispatchAdmissionSealed admission, Some installedAdmission, Some actorBinding, Some cutover ->
                    let dispatchIdentity = admission.identity
                    let dispatchAdmissionRef = terminalFlowAdmissionRawRef dispatchIdentity
                    let installAdmissionRef = terminalFlowAdmissionRawRef installedAdmission.identity
                    let orderAdmissionRef = terminalFlowTerminalOrderCutoverAdmissionRef cutover |> Option.defaultValue 0u
                    let recursiveDispatchProofMatches =
                        terminalFlowAdmissionIdentitySame dispatchIdentity installedAdmission.identity
                        && terminalFlowAdmissionIdentitySame actorBinding.identity installedAdmission.identity
                        && installAdmissionRef = dispatchAdmissionRef
                        && orderAdmissionRef = dispatchAdmissionRef
