                        FastRuntimeFormat.format "{\"kind\":\"terminal_order_entry_registered\",\"install_admission_ref\":%u,\"dispatch_admission_ref\":%u,\"order_admission_ref\":%u,\"admission_identity_ref\":%u,\"bound_actor_ref\":%u,\"actor_binding_ref\":%u,\"credential_ledger_ref\":%u,\"fairness_epoch_ref\":%u,\"fairness_release_ref\":%u,\"scheduler_lease_ref\":%u,\"scheduler_budget_ref\":%u,\"scheduler_lane_ownership_ref\":%u,\"scheduler_driver_ref\":%u,\"scheduler_lane_du\":%s,\"scheduler_worker_budget\":%d,\"scheduler_physical_release_ref\":%u,\"recursive_dispatch_proof_match\":%b,\"receipt_ref\":%u,\"authority\":\"recursive_dispatch_proof_projection_only\"}" [| box installAdmissionRef; box dispatchAdmissionRef; box orderAdmissionRef; box (terminalFlowAdmissionIdentityRef dispatchIdentity); box (terminalFlowAdmissionActorRef dispatchIdentity); box (terminalFlowAdmissionActorBindingRef dispatchIdentity); box (terminalFlowAdmissionRequirementLedgerRef dispatchIdentity); box (terminalFlowAdmissionFairnessEpochRef dispatchIdentity); box (terminalFlowIdentityRefDigest admission.fairnessRelease.releaseRef); box (terminalFlowIdentityRefDigest scheduler.leaseRef); box (terminalFlowIdentityRefDigest scheduler.budgetRef); box (terminalFlowIdentityRefDigest scheduler.laneOwnershipRef); box (terminalFlowIdentityRefDigest scheduler.driverRef); box (DiagJson.esc (terminalFlowReplayDriverLaneText scheduler.lane)); box scheduler.grantedWorkers; box (terminalFlowIdentityRefDigest scheduler.physicalReleaseRef); box recursiveDispatchProofMatches; box receipt.receiptRef |])
