                            FastRuntimeFormat.format "{\"kind\":\"terminal_actor_join_proof_projection\",\"workdag_close_receipt_ref_actual\":%u,\"workdag_close_receipt_ref_expected\":%u,\"workdag_close_match\":%b,\"ledger_seal_ref_actual\":%u,\"ledger_seal_ref_expected\":%u,\"ledger_seal_match\":%b,\"queue_close_receipt_ref_actual\":%u,\"queue_close_receipt_ref_expected\":%u,\"queue_close_match\":%b,\"queue_recovery_ref_actual\":%u,\"queue_recovery_ref_expected\":%u,\"queue_recovery_match\":%b,\"open_owner_count\":%d,\"owner\":\"sealed_dispatch_admission\",\"authority\":\"actor_join_proof_projection_only\"}" [| box closure.closeReceiptRef; box expectedCloseRef; box (closure.closeReceiptRef = expectedCloseRef); box closure.ledgerSealRef; box expectedLedgerRef; box (closure.ledgerSealRef = expectedLedgerRef); box queueCloseRef; box expectedCloseRef; box (queueCloseRef = expectedCloseRef); box queueRecoveryRef; box expectedRecoveryRef; box (queueRecoveryRef = expectedRecoveryRef); box admission.workDagTailProof.openOwnerCount |])
                    | _ -> ()
                    DiagJson.emitTerminalJsonDurable (
