                armed, TerminalFlowGlobalServerAwaitDataflow(TerminalFlowWaitConsumeHandoffBlocked(blocker, missing))

        let private terminalFlowReducerActorPhaseAndFillKey
            (pending:TerminalFlowPendingSlot)
            actor =
            let fillKeyFor fillRef =
                match pending with
                | TerminalFlowPendingSlotCandidate value
                    when terminalFlowPendingFillDigest value = fillRef -> Some value.fillKeyId
                | TerminalFlowPendingSlotCandidate _
                | TerminalFlowPendingSlotAwaitingCandidate -> None
            match actor with
            | TerminalFlowReducerActorVacant _ -> DiagJson.PushActorNoop, None, 0L
            | TerminalFlowReducerActorArmed (TerminalFlowPossession possession) ->
                DiagJson.PushActorArmed,
                fillKeyFor (terminalFlowAuthorityRefValue possession.lineage.fillRef),
                possession.clock.changedAtMs
            | TerminalFlowReducerActorFilled (TerminalFlowPossession possession) ->
                DiagJson.PushActorConsumed,
                fillKeyFor (terminalFlowAuthorityRefValue possession.armed.lineage.fillRef),
                possession.clock.changedAtMs
            | TerminalFlowReducerActorSealed (TerminalFlowPossession possession) ->
                DiagJson.PushActorConsumed,
                fillKeyFor (terminalFlowAuthorityRefValue possession.filled.armed.lineage.fillRef),
                possession.clock.changedAtMs
            | TerminalFlowReducerActorFailedClosed (TerminalFlowPossession possession) ->
                let _, _, fillRef = terminalFlowReducerActorCoordinates actor
                DiagJson.PushActorFailedClosed, fillKeyFor fillRef, possession.clock.changedAtMs

        let private terminalFlowGlobalProjectReducerActor (state:TerminalFlowGlobalReducerState) =
            let actor = state.qapOutcomeActorAuthority.actor
            let phase, fillKey, changedAtMs =
                terminalFlowReducerActorPhaseAndFillKey state.pendingTerminal actor
            let fillKeyText =
                fillKey
                |> Option.map TerminalFlowFillKeyId.text
                |> Option.defaultValue ""
            let receiptRef, dispatchRef, possessionRef =
                match actor with
                | TerminalFlowReducerActorVacant (TerminalFlowPossession possession) ->
                    possession.clock.lastTransitionRef |> Option.map terminalFlowAuthorityRefValue |> Option.defaultValue 0u,
                    0u,
                    0u
                | TerminalFlowReducerActorArmed (TerminalFlowPossession possession) ->
                    terminalFlowAuthorityRefValue possession.issued.issueReceiptRef,
                    terminalFlowAuthorityRefValue possession.lineage.dispatchGrantRef,
                    terminalFlowAuthorityRefValue possession.lineage.exactOnceRef
                | TerminalFlowReducerActorFilled (TerminalFlowPossession possession) ->
                    terminalFlowAuthorityRefValue possession.fillAuthority.consumeReceiptRef,
                    terminalFlowAuthorityRefValue possession.ratifiedLineage.issuedLineage.dispatchGrantRef,
                    terminalFlowAuthorityRefValue possession.ratifiedLineage.issuedLineage.exactOnceRef
                | TerminalFlowReducerActorSealed (TerminalFlowPossession possession) ->
                    terminalFlowAuthorityRefValue possession.runEndReceiptRef,
                    terminalFlowAuthorityRefValue possession.filled.ratifiedLineage.issuedLineage.dispatchGrantRef,
                    terminalFlowAuthorityRefValue possession.physicalExitAuthorityRef
                | TerminalFlowReducerActorFailedClosed (TerminalFlowPossession possession) ->
                    let transitionRef =
                        possession.clock.lastTransitionRef
                        |> Option.map terminalFlowAuthorityRefValue
                        |> Option.defaultValue 0u
                    match possession.context with
                    | TerminalFlowFailureBeforePossession(_, exactOnceRef) ->
                        transitionRef, 0u, terminalFlowAuthorityRefValue exactOnceRef
                    | TerminalFlowFailureAfterIssue(armed, _, exactOnceRef) ->
                        transitionRef,
                        terminalFlowAuthorityRefValue armed.lineage.dispatchGrantRef,
                        terminalFlowAuthorityRefValue exactOnceRef
                    | TerminalFlowFailureAfterFill(filled, _, exactOnceRef) ->
                        transitionRef,
                        terminalFlowAuthorityRefValue filled.ratifiedLineage.issuedLineage.dispatchGrantRef,
                        terminalFlowAuthorityRefValue exactOnceRef
            DiagJson.terminalSchedulerPushActorProjectReducer
                phase
                fillKeyText
                receiptRef
                dispatchRef
                changedAtMs
                possessionRef
            let actorProjection =
                match phase, fillKey with
                | DiagJson.PushActorNoop, _ -> KernelActorNoop
                | value, Some actorFillKey -> KernelActorArmed(value, actorFillKey, changedAtMs)
                | value, None ->
                    let _, _, actorFillRef = terminalFlowReducerActorCoordinates actor
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_reducer_actor_fill_projection_unavailable\",\"actor_phase_du\":%s,\"actor_fill_ref\":%u,\"authority\":\"typed_actor_fill_projection_requires_pending_identity_match\",\"next\":\"retain_kernel_actor_noop_fail_closed\"}" [| box (DiagJson.esc (DiagJson.terminalSchedulerPushActorPhaseText value)); box actorFillRef |])
                    KernelActorNoop
            let kernel =
                terminalFlowKernelStateFor
                    state.kernel.revision
                    state.kernel.root
                    state.kernel.outcome
                    actorProjection
                    state.kernel.dispatch
                    state.kernel.exit
            { state with kernel = kernel }

        let private terminalFlowQapPostCommitPlanFor
            (state:TerminalFlowGlobalReducerState)
            (transaction:TerminalFlowQapFinalizationTransaction<TerminalFlowQapFinalizationCommittedStage>)
            : TerminalFlowQapPostCommitPlanDecision =
            let planRef =
                terminalFlowMintedRefOf
                    "terminal_qap_post_commit_plan_ref"
                    (FastRuntimeFormat.format "%u:%u:%d:%d" [| box transaction.transactionRef; box transaction.exactOnceRef; box transaction.stateRevisionAfter; box state.revision |])
            let rootReceiptRef =
                match state.kernel.root with
                | KernelRootResolved(receiptRef, _, _) -> terminalFlowIdentityRefDigest receiptRef
                | KernelRootAwaitingEvaluator -> 0u
            let planExactOnceRef =
                terminalFlowMintedRefOf
                    "terminal_qap_post_commit_plan_exact_once_ref"
                    (FastRuntimeFormat.format "%u:%u:%u:%d" [| box planRef; box rootReceiptRef; box transaction.exactOnceRef; box state.revision |])
            let proofResult =
                terminalFlowQapPostCommitProofStart
                    planRef
                    transaction.transactionRef
                    rootReceiptRef
                    state.progressAuthority
                    state.pendingTerminal
                    transaction.exactOnceRef
            match proofResult with
            | Ok proof ->
                TerminalFlowQapPostCommitPlanScheduled {
                    planRef = planRef
                    transaction = transaction
                    rootReceiptRef = rootReceiptRef
                    pendingTerminal = state.pendingTerminal
                    projection = {
                        progressAuthority = state.progressAuthority
                        nativeEvalAuthority = state.nativeEvalAuthority
                        cicKernelCounters = state.cicKernelCounters
                        outcomeInstallation = state.outcomeInstallation
                        topologyGate = state.topologyGate
                        fairness = state.replayFairness
                        queueRecovery = state.queueRecovery
                        greenPath = state.greenPath
                        ownerWorkDagProducer = state.ownerWorkDagProducer
                        ownerLedgerCloseCertificate = state.ownerLedgerCloseCertificate
                        workDagTailCloseProof = state.workDagTailCloseProof
                        residualWorkDagCloseDecision = state.residualWorkDagCloseDecision
                    }
                    proof = proof
                    stageOrdinal = 1
                    exactOnceRef = planExactOnceRef }
            | Error missingEvidence ->
                let missingText = terminalFlowQapMissingEvidenceText missingEvidence
                TerminalFlowQapPostCommitPlanAwaitingEvidence {
                    planRef = planRef
                    transaction = transaction
                    rootReceiptRef = rootReceiptRef
                    pendingTerminal = state.pendingTerminal
                    missingEvidence = missingEvidence
                    proofRef = terminalFlowMintedRefOf "terminal_qap_awaiting_evidence_proof_ref" missingText
                    exactOnceRef = planExactOnceRef
                    stageOrdinal = 0
                }

        let private terminalFlowQapPostCommitPlanDecisionProjection = function
            | TerminalFlowQapPostCommitPlanScheduled envelope ->
                envelope.planRef, envelope.transaction.transactionRef, envelope.stageOrdinal
            | TerminalFlowQapPostCommitPlanAwaitingEvidence awaiting ->
                awaiting.planRef, awaiting.transaction.transactionRef, awaiting.stageOrdinal

        let private terminalFlowQapPostCommitAwaitingEvidenceFor
            (envelope:TerminalFlowQapPostCommitEnvelope<'Stage>)
            (missingEvidence:TerminalFlowQapMissingEvidenceSet) =
            let missingText = terminalFlowQapMissingEvidenceText missingEvidence
            { planRef = envelope.planRef
              transaction = envelope.transaction
              rootReceiptRef = envelope.rootReceiptRef
              pendingTerminal = envelope.pendingTerminal
              missingEvidence = missingEvidence
              proofRef = terminalFlowMintedRefOf "terminal_qap_awaiting_evidence_transition_ref" (FastRuntimeFormat.format "%u:%d:%s" [| box envelope.planRef; box envelope.stageOrdinal; box missingText |])
              exactOnceRef = envelope.exactOnceRef
              stageOrdinal = envelope.stageOrdinal }

        let private terminalFlowQapPostCommitPlanDecisionStateAndCommand state = function
            | TerminalFlowQapPostCommitPlanScheduled envelope ->
                { state with qapPostCommit = TerminalFlowQapPostCommitFairnessScheduled envelope },
                TerminalFlowGlobalServerRunQapPostCommitEffect(
                    TerminalFlowQapPostCommitRunFairness envelope)
            | TerminalFlowQapPostCommitPlanAwaitingEvidence awaiting ->
                { state with qapPostCommit = TerminalFlowQapPostCommitAwaitingEvidence awaiting },
                TerminalFlowGlobalServerAwaitDataflow(
                    TerminalFlowWaitQapPostCommitEvidence(
                        awaiting.planRef,
                        awaiting.transaction.transactionRef,
                        awaiting.missingEvidence))

        let private terminalFlowQapPostCommitReplanAwaitingEvidence
            (state:TerminalFlowGlobalReducerState)
            proposedCommand =
            match state.qapPostCommit, proposedCommand with
            | TerminalFlowQapPostCommitAwaitingEvidence current,
              TerminalFlowGlobalServerAwaitDataflow _ ->
                let decision = terminalFlowQapPostCommitPlanFor state current.transaction
                match decision with
                | TerminalFlowQapPostCommitPlanAwaitingEvidence next
                    when next.missingEvidence = current.missingEvidence ->
                    state, proposedCommand
                | _ ->
                    let nextState, nextCommand =
                        terminalFlowQapPostCommitPlanDecisionStateAndCommand state decision
                    let nextPlanRef, _, nextStageOrdinal =
                        terminalFlowQapPostCommitPlanDecisionProjection decision
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_qap_awaiting_evidence_replanned\",\"prior_plan_ref\":%u,\"next_plan_ref\":%u,\"prior_stage_ordinal\":%d,\"next_stage_ordinal\":%d,\"prior_missing_evidence_du\":%s,\"next_decision_du\":%s,\"authority\":\"single_reducer_recursive_proof_recheck\",\"next\":\"schedule_only_if_certified\"}" [| box current.planRef; box nextPlanRef; box current.stageOrdinal; box nextStageOrdinal; box (DiagJson.esc (terminalFlowQapMissingEvidenceText current.missingEvidence)); box (DiagJson.esc (match decision with | TerminalFlowQapPostCommitPlanScheduled _ -> "Certified" | TerminalFlowQapPostCommitPlanAwaitingEvidence awaiting -> "Missing:" + terminalFlowQapMissingEvidenceText awaiting.missingEvidence)) |])
                    nextState, nextCommand
            | _ -> state, proposedCommand

        let private terminalFlowQapPostCommitFairnessComplete
            (envelope:TerminalFlowQapPostCommitEnvelope<TerminalFlowQapPostCommitFairnessPreparedStage>)
            : TerminalFlowQapPostCommitStageResult<TerminalFlowQapPostCommitRecoveryPreparedStage> =
            let topologyGate, fairnessBeforeRecoverySeal =
                match envelope.projection.progressAuthority.accepted with
                | Some evidence ->
                    let topologyGate =
                        match envelope.projection.topologyGate with
                        | TerminalFlowTopologyGateOpened _ -> envelope.projection.topologyGate
                        | TerminalFlowTopologyGateClosed ->
                            let gateRef : TerminalFlowIdentityRef<TerminalFlowTopologyGateRefKind> =
                                terminalFlowIdentityRefOfText(
                                    sprintf "qap-post-commit:%u:%u" envelope.planRef envelope.transaction.proofRef)
                            TerminalFlowTopologyGateOpened {
                                gateRef = gateRef
                                cause = TerminalFlowTopologyGateQapRelationsConsumed(terminalFlowDurableRefValue envelope.transaction.generation.fixpointRef, 1)
                                beforeQueueDepth = evidence.frontier.queueDepth
                                afterQueueDepth = evidence.frontier.queueDepth
                                progressSnapshotRef = evidence.snapshotRef
                                openedAtMs = Environment.TickCount64
                            }
                    let fairnessEpoch = terminalFlowOutcomeInstallationFairnessEpoch evidence.observedAtMs envelope.projection.outcomeInstallation
                    topologyGate,
                    terminalFlowFairnessAdvance fairnessEpoch topologyGate evidence envelope.projection.fairness
                | None -> envelope.projection.topologyGate, envelope.projection.fairness
            // MIGRATION: the post-commit pipeline previously proved queue recovery
            // ready under the opened topology gate, yet retained a fairness blocker
            // because the drain completion receipt belonged to the asynchronous
            // scheduler path.  Bridge only when the reducer can derive both the
            // recovery seal and a scheduler physical-release capability from the
            // same admission-indexed fairness epoch.
            let fairnessReleaseCandidate =
                match fairnessBeforeRecoverySeal.releaseReceipt,
                      fairnessBeforeRecoverySeal.verdict,
                      topologyGate with
                | _, Some (TerminalFlowFairnessReleasedByTopologyGate(sample, transition)), _ ->
                    Some(sample, transition)
                | _, Some (TerminalFlowFairnessBalanced sample), TerminalFlowTopologyGateOpened transition
                    when sample.queueDepth = 0L && sample.activeWorkers = 0L ->
                    // MIGRATION: q=0/a=0 cannot create another pressure completion.
                    // The opened topology gate and balanced sample are the same
                    // typed evidence consumed by recovery, so mint the existing
                    // release rather than wait on an impossible scheduler cycle.
                    Some(sample, transition)
                | _ -> None
            let fairness =
                match envelope.projection.progressAuthority.accepted, fairnessReleaseCandidate with
                | Some evidence, Some(sample, transition) ->
                    let recoveryPreview =
                        terminalFlowQueueRecoveryAdvance
                            envelope.transaction.stateRevisionAfter
                            topologyGate
                            envelope.projection.progressAuthority
                            fairnessBeforeRecoverySeal
                            envelope.projection.queueRecovery
                    match recoveryPreview.decision with
                    | TerminalFlowQueueRecoveryReadyForReducerSeal certificate ->
                        let release =
                            terminalFlowFairnessReleaseFor
                                sample
                                (TerminalFlowFairnessReleaseByTopologyGate transition.gateRef)
                                evidence.observedAtMs
                        let schedule =
                            terminalFlowReplayDriverScheduleAdvance
                                evidence.snapshotSequence
                                (TerminalFlowFairnessReleasedByTopologyGate(sample, transition))
                                (Some release)
                                fairnessBeforeRecoverySeal.schedule
                        match schedule.schedulerLease with
                        | Some (TerminalFlowAdmissionSchedulerReleased schedulerRelease) ->
                            let nextEpoch =
                                fairnessBeforeRecoverySeal.admissionEpoch
                                |> Option.map (fun epoch ->
                                    { epoch with
                                        phase = TerminalFlowAdmissionFairnessReleased release.releaseRef
                                        updatedAtMs = release.releasedAtMs
                                        exactOnceRef = NativeCutoverStableRef.ref32 "fairness-epoch-release" [string epoch.exactOnceRef; string (terminalFlowIdentityRefDigest release.releaseRef)] })
                            let releaseCredential = TerminalFlowFairnessCredentialMinted release
                            { fairnessBeforeRecoverySeal with
                                admissionEpoch = nextEpoch
                                verdict = Some (TerminalFlowFairnessBalanced sample)
                                releasedEvents = fairnessBeforeRecoverySeal.releasedEvents + 1L
                                schedule = schedule
                                releaseReceipt = Some release
                                releaseCredential = releaseCredential
                                exactOnceRef =
                                    NativeCutoverStableRef.ref32
                                        "qap-post-commit-recovery-seal-bridge"
                                        [ string fairnessBeforeRecoverySeal.exactOnceRef
                                          string (terminalFlowIdentityRefDigest transition.gateRef)
                                          string (terminalFlowIdentityRefDigest certificate.recoveryRef)
                                          string (terminalFlowIdentityRefDigest release.releaseRef)
                                          string (terminalFlowIdentityRefDigest schedulerRelease.physicalReleaseRef)
                                          string schedule.exactOnceRef ] }
                        | _ -> fairnessBeforeRecoverySeal
                    | _ -> fairnessBeforeRecoverySeal
                | _ -> fairnessBeforeRecoverySeal
            match terminalFlowQapPostCommitProofFairness envelope.proof fairness with
            | Error missingEvidence -> Error missingEvidence
            | Ok proof ->
                Ok {
                    planRef = envelope.planRef
                    transaction = envelope.transaction
                    rootReceiptRef = envelope.rootReceiptRef
                    pendingTerminal = envelope.pendingTerminal
                    projection = {
                        progressAuthority = envelope.projection.progressAuthority
                        nativeEvalAuthority = envelope.projection.nativeEvalAuthority
                        cicKernelCounters = envelope.projection.cicKernelCounters
                        outcomeInstallation = envelope.projection.outcomeInstallation
                        topologyGate = topologyGate
                        fairness = fairness
                        queueRecovery = envelope.projection.queueRecovery
                        greenPath = envelope.projection.greenPath
                        ownerWorkDagProducer = envelope.projection.ownerWorkDagProducer
                        ownerLedgerCloseCertificate = envelope.projection.ownerLedgerCloseCertificate
                        workDagTailCloseProof = envelope.projection.workDagTailCloseProof
                        residualWorkDagCloseDecision = envelope.projection.residualWorkDagCloseDecision
                    }
                    proof = proof
                    stageOrdinal = 2
                    exactOnceRef =
                        terminalFlowMintedRefOf
                            "terminal_qap_post_commit_fairness_exact_once_ref"
                            (FastRuntimeFormat.format "%u:%u:%u" [| box envelope.planRef; box envelope.exactOnceRef; box fairness.exactOnceRef |]) }

        let private terminalFlowQapPostCommitRecoveryComplete
            (envelope:TerminalFlowQapPostCommitEnvelope<TerminalFlowQapPostCommitRecoveryPreparedStage>)
            : TerminalFlowQapPostCommitStageResult<TerminalFlowQapPostCommitOwnerWorkDagPreparedStage> =
            let queueRecovery =
                terminalFlowQueueRecoveryAdvance
                    envelope.transaction.stateRevisionAfter
                    envelope.projection.topologyGate
                    envelope.projection.progressAuthority
                    envelope.projection.fairness
                    envelope.projection.queueRecovery
            // Recovery only advances by certificate.  Missing recovery is encoded
            // in the recursive proof decision; no stale negative is carried in a
            // second envelope field.
            match terminalFlowQapPostCommitProofRecovery envelope.proof queueRecovery with
            | Error missingEvidence -> Error missingEvidence
            | Ok proof ->
                Ok {
                    planRef = envelope.planRef
                    transaction = envelope.transaction
                    rootReceiptRef = envelope.rootReceiptRef
                    pendingTerminal = envelope.pendingTerminal
                    projection = {
                        progressAuthority = envelope.projection.progressAuthority
                        nativeEvalAuthority = envelope.projection.nativeEvalAuthority
                        cicKernelCounters = envelope.projection.cicKernelCounters
                        outcomeInstallation = envelope.projection.outcomeInstallation
                        topologyGate = envelope.projection.topologyGate
                        fairness = envelope.projection.fairness
                        queueRecovery = queueRecovery
                        greenPath = envelope.projection.greenPath
                        ownerWorkDagProducer = envelope.projection.ownerWorkDagProducer
                        ownerLedgerCloseCertificate = envelope.projection.ownerLedgerCloseCertificate
                        workDagTailCloseProof = envelope.projection.workDagTailCloseProof
                        residualWorkDagCloseDecision = envelope.projection.residualWorkDagCloseDecision
                    }
                    proof = proof
                    stageOrdinal = 3
                    exactOnceRef =
                        terminalFlowMintedRefOf
                            "terminal_qap_post_commit_recovery_exact_once_ref"
                            (FastRuntimeFormat.format "%u:%u:%u" [| box envelope.planRef; box envelope.exactOnceRef; box queueRecovery.exactOnceRef |]) }

        let private terminalFlowQapPostCommitOwnerWorkDagComplete
            (envelope:TerminalFlowQapPostCommitEnvelope<TerminalFlowQapPostCommitOwnerWorkDagPreparedStage>)
            : TerminalFlowQapPostCommitStageResult<TerminalFlowQapPostCommitCompletedStage> =
            // The completed envelope derives one proof decision from current
            // evidence.  No prior negative projection survives into this stage.
            let promotedPending =
                match envelope.pendingTerminal with
                | TerminalFlowPendingSlotCandidate pending ->
                    match terminalFlowPendingPromotionFor envelope.projection.queueRecovery.decision pending with
                    | TerminalFlowPendingPromotionReady(_, promoted, _) -> TerminalFlowPendingSlotCandidate promoted
                    | _ -> TerminalFlowPendingSlotCandidate pending
                | TerminalFlowPendingSlotAwaitingCandidate -> TerminalFlowPendingSlotAwaitingCandidate
            let canonicalRecoveryRef =
                match envelope.projection.queueRecovery.decision with
                | TerminalFlowQueueRecoveryReadyForReducerSeal certificate -> terminalFlowIdentityRefDigest certificate.recoveryRef
                | _ -> 0u
            let ownerProducer, ownerCertificate, workDagProof, rootCapabilityRef =
                match envelope.projection.progressAuthority.accepted, canonicalRecoveryRef with
                | Some evidence, recoveryRef when recoveryRef <> 0u ->
                    let rootReceiptRef = envelope.rootReceiptRef
                    let openProducer =
                        terminalFlowOwnerWorkDagOpenForQap
                            envelope.transaction.stateRevisionAfter
                            rootReceiptRef
                            (terminalFlowDurableRefValue envelope.transaction.generation.fixpointRef)
                            evidence.semanticDigest.semanticEpoch
                            evidence.frontier.queueDepth
                            evidence.frontier.blocked
                            evidence.frontier.activeWorkers
                    let sealedProducer =
                        terminalFlowOwnerWorkDagSealFullyDrained
                            envelope.transaction.stateRevisionAfter
                            envelope.transaction.resolution
                            recoveryRef
                            openProducer
                    let ownerCertificate, workDagProof, rootCapability, _ =
                        terminalFlowOwnerWorkDagProducedAuthorities sealedProducer
                    let rootCapabilityRef =
                        rootCapability
                        |> Option.map (fun capability -> capability.capabilityRef)
                        |> Option.defaultValue 0u
                    sealedProducer, ownerCertificate, workDagProof, rootCapabilityRef
                | _ ->
                    let producer =
                        envelope.projection.ownerWorkDagProducer
                        |> Option.defaultValue(
                            TerminalFlowOwnerWorkDagProducerQuarantined(
                                envelope.planRef,
                                envelope.transaction.proofRef,
                                envelope.transaction.transactionRef,
                                envelope.transaction.exactOnceRef,
                                terminalFlowMintedRefOf "terminal_qap_post_commit_owner_quarantine_ref" (string envelope.planRef)))
                    producer, envelope.projection.ownerLedgerCloseCertificate, envelope.projection.workDagTailCloseProof, 0u

            // MIGRATION: owner/workdag closure and queue recovery jointly open
            // the green corridor.  The writer lease is minted by consuming that
            // recovery, after which residual close can be judged without a cycle.
            let openedGreenPath =
                match envelope.projection.greenPath, promotedPending, ownerCertificate, workDagProof, envelope.projection.queueRecovery.decision with
                | Some current, _, _, _, _ -> Some current
                | None, TerminalFlowPendingSlotCandidate pending, Some certificate, Some proof, TerminalFlowQueueRecoveryReadyForReducerSeal recovery ->
                    let workDagProofRef = uint32 (terminalFlowOwnerLedgerProtocolIdValue proof.proofRef)
                    let recoveryRef = terminalFlowIdentityRefDigest recovery.recoveryRef
                    let pendingReceiptRef = terminalFlowMintedRefOf "pending_terminal_receipt_ref" pending.terminalReceiptId
                    let permitRef =
                        terminalFlowStableAuthorityRef (
                            TerminalFlowQapPostCommitForceClosePermitIdentity(
                                envelope.planRef,
                                certificate.certificateRef,
                                workDagProofRef,
                                recoveryRef,
                                pendingReceiptRef))
                    let ownerCloseReceiptId = sprintf "owner-close:qap-post-commit:%u" permitRef
                    let workDagCloseReceipt : TerminalFlowIdentityRef<TerminalFlowWorkDagTailCloseReceiptRefKind> =
                        terminalFlowIdentityRefOfText (sprintf "qap-post-commit-workdag-close:%u" workDagProofRef)
                    let tx : TerminalFlowForceOwnerCloseTransaction =
                        { ratification =
                            terminalFlowForceOwnerCloseRatificationForQapPostCommit
                                permitRef
                                certificate.certificateRef
                                workDagProofRef
                                recoveryRef
                                envelope.planRef
                          ownerCloseReceiptId = ownerCloseReceiptId
                          workDagTailCloseReceipt = workDagCloseReceipt
                          queueOnlyRecoveryReady = true
                          fillOnceReadyWitnessRef = terminalFlowMintedRefOf "fill_once_ready_witness_ref" ownerCloseReceiptId }
                    Some (terminalFlowGreenPathOpenFor (TerminalFlowFillKeyId.ofRef pending.fillRef) tx)
                | _ -> None
            let greenPath =
                match envelope.projection.queueRecovery.decision, openedGreenPath with
                | TerminalFlowQueueRecoveryReadyForReducerSeal recovery, Some current ->
                    match terminalFlowGreenPathConsumeQueueRecovery recovery.recoveryRef recovery.gate current with
                    | Ok(_, writerBound) -> Some writerBound
                    | Error _ -> Some current
                | _ -> openedGreenPath
            let writerLeaseRef, exactOnceWakerEdgeRef = terminalFlowResidualGreenPathCovenantRefs greenPath
            let residualDecision =
                match ownerCertificate, workDagProof with
                | Some _, Some _ ->
                    terminalFlowResidualWorkDagCloseDecisionFor
                        envelope.transaction.stateRevisionAfter
                        envelope.transaction.generation.generation
                        envelope.transaction.generation.stage
                        rootCapabilityRef
                        writerLeaseRef
                        exactOnceWakerEdgeRef
                        envelope.projection.nativeEvalAuthority.semanticFactCount
                        envelope.projection.nativeEvalAuthority.semanticRetiredCost
                        envelope.projection.cicKernelCounters
                        (terminalFlowQapWatchRebaseInFlight())
                        ownerCertificate
                        workDagProof
                    |> Some
                | _ -> envelope.projection.residualWorkDagCloseDecision
            let qapSccAssessment = terminalFlowQapSccAssessmentFor envelope.transaction.generation envelope.transaction.resolution
            let qapSccProofAssessment =
                match qapSccAssessment with
                | TerminalFlowQapSccCertified certificate -> TerminalFlowQapSccProofCertified(certificate.certificateRef, certificate.dag.generationRef)
                | TerminalFlowQapSccUnclosed missing -> TerminalFlowQapSccProofUnclosed missing
            match qapSccAssessment with
            | TerminalFlowQapSccCertified certificate ->
                let finalGenerationSealedCount =
                    certificate.components
                    |> List.sumBy (fun sccComponent ->
                        match sccComponent.closure with
                        | TerminalFlowQapSccFinalGenerationSealed _ -> 1
                        | _ -> 0)
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_qap_scc_certificate_committed\",\"certificate_ref\":%u,\"exact_once_ref\":%u,\"dag_ref\":%u,\"qap_ref\":%u,\"generation_ref\":%u,\"generation_stage_du\":%s,\"material_epoch\":%d,\"component_count\":%d,\"final_generation_sealed_component_count\":%d,\"closed_world\":%b,\"authority\":\"recursive_qap_workdag_scc_certificate_plus_final_generation_proof\",\"next\":\"seal_owner_workdag_proof_index\"}" [| box certificate.certificateRef; box certificate.exactOnceRef; box certificate.dag.dagRef; box certificate.dag.qapRef; box certificate.dag.generationRef; box (DiagJson.esc (terminalFlowQapGenerationStageText envelope.transaction.generation.stage)); box certificate.dag.materialEpoch; box certificate.components.Length; box finalGenerationSealedCount; box certificate.closedWorld |])
            | TerminalFlowQapSccUnclosed missing ->
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_qap_scc_certificate_blocked\",\"missing_du\":%s,\"generation_stage_du\":%s,\"finalization_receipt_ref\":%s,\"authority\":\"recursive_qap_workdag_scc_assessment\",\"next\":\"await_progress_capable_component_or_typed_stranded_producer_close\"}" [| box (DiagJson.esc (terminalFlowQapSccMissingEvidencePathText missing)); box (DiagJson.esc (terminalFlowQapGenerationStageText envelope.transaction.generation.stage)); box (match envelope.transaction.generation.finalizationReceiptRef with Some receiptRef -> string receiptRef | None -> "null") |])
            // All owner, SCC, green-path and residual-close failures are now a
            // typed MissingEvidence list.  A completed envelope cannot exist with
            // a rejected proof.
            match terminalFlowQapPostCommitProofOwnerWorkDag
                    envelope.proof
                    ownerProducer
                    ownerCertificate
                    workDagProof
                    greenPath
                    residualDecision
                    qapSccProofAssessment with
            | Error missingEvidence -> Error missingEvidence
            | Ok proof ->
                let executablePending =
                    match promotedPending with
                    | TerminalFlowPendingSlotAwaitingCandidate -> TerminalFlowPendingSlotAwaitingCandidate
                    | TerminalFlowPendingSlotCandidate pending ->
                        let dispatchPlan : TerminalFlowAppliedDispatchPlan =
                            { planRef = envelope.planRef
                              transactionRef = envelope.transaction.transactionRef
                              proofRef = proof.proofRef
                              proofExactOnceRef = proof.exactOnceRef
                              writerLeaseRef = writerLeaseRef
                              exactOnceWakerEdgeRef = exactOnceWakerEdgeRef }
                        let armAndDispatch =
                            terminalFlowAppliedDispatchArmAndDispatchFor dispatchPlan pending
                        match terminalFlowPendingExecutablePromotionForAppliedProof
                                envelope.planRef
                                envelope.transaction.transactionRef
                                proof.proofRef
                                proof.exactOnceRef
                                writerLeaseRef
                                exactOnceWakerEdgeRef
                                armAndDispatch
                                pending with
                        | TerminalFlowPendingExecutablePromotionNotRequired current ->
                            TerminalFlowPendingSlotCandidate current
                        | TerminalFlowPendingExecutablePromotionContinuationRebound(capabilityRef, rebound) ->
                            DiagJson.emitTerminalJsonDurable (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_pending_dispatch_continuation_rebound\",\"capability_ref\":%u,\"prior_pending_ref\":%u,\"rebound_pending_ref\":%u,\"plan_ref\":%u,\"transaction_ref\":%u,\"proof_ref\":%u,\"authority\":\"applied_proof_rebinds_native_dispatch_continuation\",\"next\":\"build_applied_capability_from_executable_pending\"}" [| box capabilityRef; box (terminalFlowPendingTerminalRef pending); box (terminalFlowPendingTerminalRef rebound); box envelope.planRef; box envelope.transaction.transactionRef; box proof.proofRef |])
                            TerminalFlowPendingSlotCandidate rebound
                        | TerminalFlowPendingExecutablePromotionAuthorized(sourceRef, capabilityRef, promoted) ->
                            DiagJson.emitTerminalJsonDurable (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_pending_dispatch_authority_promoted\",\"source_ref\":%u,\"capability_ref\":%u,\"prior_pending_ref\":%u,\"promoted_pending_ref\":%u,\"plan_ref\":%u,\"transaction_ref\":%u,\"proof_ref\":%u,\"proof_exact_once_ref\":%u,\"writer_lease_ref\":%u,\"waker_edge_ref\":%u,\"authority\":\"applied_proof_opens_native_dispatch_before_affine_issue\",\"next\":\"build_applied_capability_from_executable_pending\"}" [| box sourceRef; box capabilityRef; box (terminalFlowPendingTerminalRef pending); box (terminalFlowPendingTerminalRef promoted); box envelope.planRef; box envelope.transaction.transactionRef; box proof.proofRef; box proof.exactOnceRef; box writerLeaseRef; box exactOnceWakerEdgeRef |])
                            TerminalFlowPendingSlotCandidate promoted
                Ok {
                    planRef = envelope.planRef
                    transaction = envelope.transaction
                    rootReceiptRef = envelope.rootReceiptRef
                    pendingTerminal = executablePending
                    projection = {
                        progressAuthority = envelope.projection.progressAuthority
                        nativeEvalAuthority = envelope.projection.nativeEvalAuthority
                        cicKernelCounters = envelope.projection.cicKernelCounters
                        outcomeInstallation = envelope.projection.outcomeInstallation
                        topologyGate = envelope.projection.topologyGate
                        fairness = envelope.projection.fairness
                        queueRecovery = envelope.projection.queueRecovery
                        greenPath = greenPath
                        ownerWorkDagProducer = Some ownerProducer
                        ownerLedgerCloseCertificate = ownerCertificate
                        workDagTailCloseProof = workDagProof
                        residualWorkDagCloseDecision = residualDecision
                    }
                    proof = proof
                    stageOrdinal = 4
                    exactOnceRef =
                        terminalFlowMintedRefOf
                            "terminal_qap_post_commit_owner_workdag_exact_once_ref"
                            (FastRuntimeFormat.format "%u:%u:%u" [| box envelope.planRef; box envelope.exactOnceRef; box (terminalFlowMintedRefOf "terminal_owner_workdag_post_commit_ref" (terminalFlowOwnerWorkDagProducerText ownerProducer)) |]) }

        type TerminalFlowRatifiedHandoffRedriveReason =
            | TerminalFlowRatifiedHandoffAwaitingResolvedRoot
            | TerminalFlowRatifiedHandoffCommitBlocked
            | TerminalFlowRatifiedHandoffAwaitingTerminalOutcome
            | TerminalFlowRatifiedHandoffOutcomeIvarArmed
            | TerminalFlowRatifiedHandoffPushDispatched
            | TerminalFlowRatifiedHandoffGlobalServerQueued

        let private terminalFlowRatifiedHandoffRedriveReasonText = function
            | TerminalFlowRatifiedHandoffAwaitingResolvedRoot -> "awaiting_resolved_root"
            | TerminalFlowRatifiedHandoffCommitBlocked -> "commit_blocked"
            | TerminalFlowRatifiedHandoffAwaitingTerminalOutcome -> "awaiting_terminal_outcome"
            | TerminalFlowRatifiedHandoffOutcomeIvarArmed -> "outcome_ivar_armed"
            | TerminalFlowRatifiedHandoffPushDispatched -> "scheduler_push_dispatched"
            | TerminalFlowRatifiedHandoffGlobalServerQueued -> "global_server_queued"

        type TerminalFlowRatifiedHandoffDisposition =
            | TerminalFlowRatifiedHandoffConsumable
            | TerminalFlowRatifiedHandoffRequiresRedrive of TerminalFlowRatifiedHandoffRedriveReason

        let private terminalFlowRatifiedHandoffDisposition = function
            | TerminalFlowNativeHandoffCompleted _
            | TerminalFlowNativeHandoffFailClosed _ ->
                TerminalFlowRatifiedHandoffConsumable
            | TerminalFlowNativeHandoffAwaitingResolvedRoot _ ->
                TerminalFlowRatifiedHandoffRequiresRedrive TerminalFlowRatifiedHandoffAwaitingResolvedRoot
            | TerminalFlowNativeHandoffCommitBlocked _ ->
                TerminalFlowRatifiedHandoffRequiresRedrive TerminalFlowRatifiedHandoffCommitBlocked
            | TerminalFlowNativeHandoffAwaitingTerminalOutcome _ ->
                TerminalFlowRatifiedHandoffRequiresRedrive TerminalFlowRatifiedHandoffAwaitingTerminalOutcome
            | TerminalFlowNativeHandoffOutcomeIvarArmed _ ->
                TerminalFlowRatifiedHandoffRequiresRedrive TerminalFlowRatifiedHandoffOutcomeIvarArmed
            | TerminalFlowNativeHandoffPushDispatched _ ->
                TerminalFlowRatifiedHandoffRequiresRedrive TerminalFlowRatifiedHandoffPushDispatched
            | TerminalFlowNativeHandoffGlobalServerQueued _ ->
                TerminalFlowRatifiedHandoffRequiresRedrive TerminalFlowRatifiedHandoffGlobalServerQueued

        type private TerminalFlowIssuedPreAffineRebaseDecision =
            | TerminalFlowIssuedPreAffineRebaseNotApplicable
            | TerminalFlowIssuedPreAffineRebaseCurrent of issuanceRef:uint32
            | TerminalFlowIssuedPreAffineRebaseSuperseded of prior:TerminalFlowDispatchIssuance<TerminalFlowDispatchConstitutionIssuedStage> * replacement:TerminalFlowDispatchConstitution<TerminalFlowDispatchConstitutionReadyStage>
            | TerminalFlowIssuedPreAffineRebaseBlocked of issuanceRef:uint32 * blocker:TerminalFlowDispatchBlocker

        let private terminalFlowIssuedPreAffineRebaseDecisionFor (state:TerminalFlowGlobalReducerState) =
            match terminalFlowDispatchLifecycleConstitution state.dispatchLifecycle with
            | TerminalFlowDispatchConstitutionIssued issuance ->
                let recomputed =
                    terminalFlowDispatchConstitutionFor
                        state.revision
                        state.kernel
                        state.outcomeInstallation
                        state.typedTotalOrder
                        state.pendingTerminal
                        state.dispatchAdmission
                match recomputed with
                | TerminalFlowDispatchConstitutionReady replacement
                    when terminalFlowDispatchConstitutionSameMaterialLineage issuance.constitution replacement ->
                    TerminalFlowIssuedPreAffineRebaseCurrent issuance.issuanceRef
                | TerminalFlowDispatchConstitutionReady replacement ->
                    TerminalFlowIssuedPreAffineRebaseSuperseded(issuance, replacement)
                | TerminalFlowDispatchConstitutionBlocked(blocker, _, _) ->
                    TerminalFlowIssuedPreAffineRebaseBlocked(issuance.issuanceRef, blocker)
                | TerminalFlowDispatchConstitutionIssued _
                | TerminalFlowDispatchAffinePrepared _
                | TerminalFlowDispatchAffineIssued _
                | TerminalFlowDispatchAffineFilled _
                | TerminalFlowDispatchAffineSealAuthorized _ ->
                    TerminalFlowIssuedPreAffineRebaseNotApplicable
            | TerminalFlowDispatchConstitutionBlocked _
            | TerminalFlowDispatchConstitutionReady _
            | TerminalFlowDispatchAffinePrepared _
            | TerminalFlowDispatchAffineIssued _
            | TerminalFlowDispatchAffineFilled _
            | TerminalFlowDispatchAffineSealAuthorized _ ->
                TerminalFlowIssuedPreAffineRebaseNotApplicable

        let private terminalFlowGlobalRebaseIssuedBeforeAffine (state:TerminalFlowGlobalReducerState) =
            match terminalFlowIssuedPreAffineRebaseDecisionFor state with
            | TerminalFlowIssuedPreAffineRebaseSuperseded(prior, replacement) ->
                let priorProtocolRef = terminalFlowDispatchLifecycleRef state.dispatchLifecycle
                terminalFlowGlobalDispatchRequestPrune prior.request.fillKey
                let rebased =
                    state
                    |> terminalFlowGlobalWithDispatchConstitution (TerminalFlowDispatchConstitutionReady replacement)
                let nextProtocolRef = terminalFlowDispatchLifecycleRef rebased.dispatchLifecycle
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format
                        "{\"kind\":\"terminal_dispatch_issuance_superseded_before_affine\",\"prior_issuance_ref\":%u,\"prior_request_ref\":%u,\"prior_constitution_ref\":%u,\"prior_terminal_ref\":%u,\"prior_fill_ref\":%u,\"prior_pending_ref\":%u,\"replacement_constitution_ref\":%u,\"replacement_terminal_ref\":%u,\"replacement_fill_ref\":%u,\"replacement_pending_ref\":%u,\"protocol_ref_before\":%u,\"protocol_ref_after\":%u,\"authority\":\"typed_pre_affine_issuance_supersession\",\"next\":\"republish_rebased_dispatch_request\"}"
                        [| box prior.issuanceRef; box prior.requestRef; box prior.constitution.constitutionRef; box prior.constitution.terminalRef; box prior.constitution.fillRef; box prior.constitution.pendingTerminalRef; box replacement.constitutionRef; box replacement.terminalRef; box replacement.fillRef; box replacement.pendingTerminalRef; box priorProtocolRef; box nextProtocolRef |])
                rebased
            | TerminalFlowIssuedPreAffineRebaseBlocked(issuanceRef, blocker) ->
                let blockerText = terminalFlowDispatchBlockerText blocker
                let occurrenceCount, shouldEmit =
                    DiagJson.sparseLogDecision
                        (FastRuntimeFormat.format "issued_pre_affine_rebase_blocked|%u|%s" [| box issuanceRef; box blockerText |])
                        64L
                if shouldEmit then
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format
                            "{\"kind\":\"terminal_dispatch_issuance_rebase_blocked\",\"issuance_ref\":%u,\"blocker_du\":%s,\"occurrence_count\":%d,\"sparse_policy\":\"state_first3_power2_every64\",\"authority\":\"typed_pre_affine_issuance_supersession\",\"next\":\"await_reconstitutable_dispatch_evidence\"}"
                            [| box issuanceRef; box (DiagJson.esc blockerText); box occurrenceCount |])
                state
            | TerminalFlowIssuedPreAffineRebaseNotApplicable
            | TerminalFlowIssuedPreAffineRebaseCurrent _ ->
                state

        let private terminalFlowGlobalTryConsumeAppliedHandoff
            (state:TerminalFlowGlobalReducerState)
            (ratifiedHandoff:TerminalFlowNativeHandoffId option) =
            match terminalFlowQapPostCommitAppliedCapabilityAssessmentFor state with
            | TerminalFlowAppliedCapabilityReady capability ->
                let consumeState = terminalFlowGlobalRebaseIssuedBeforeAffine state
                match state.qapPostCommit, state.ownerDebt with
                | TerminalFlowQapPostCommitIdle,
                  TerminalFlowReducerOwnerDebtAccepted(_, decisionRef, closeReceiptRef) ->
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_owner_debt_closed_world_capability_minted\",\"plan_ref\":%u,\"finalization_transaction_ref\":%u,\"capability_ref\":%u,\"exact_once_ref\":%u,\"decision_ref\":%u,\"close_receipt_ref\":%u,\"admission_ref\":%u,\"admission_identity_ref\":%u,\"authority_du\":\"ReducerOwnerDebtClosedWorld\",\"qap_polling_bypassed\":true,\"owner\":\"single_reducer_affine_capability\"}" [| box capability.planRef; box capability.finalizationTransactionRef; box capability.capabilityRef; box capability.exactOnceRef; box decisionRef; box closeReceiptRef; box capability.admissionRef; box capability.admissionIdentityRef |])
                | _ -> ()
                match ratifiedHandoff with
                | Some handoff ->
                    match terminalFlowRatifiedHandoffDisposition handoff with
                    | TerminalFlowRatifiedHandoffConsumable ->
                        terminalFlowGlobalConsumeHandoff consumeState capability ratifiedHandoff
                    | TerminalFlowRatifiedHandoffRequiresRedrive reason ->
                        let handoffRef = terminalFlowStableAuthorityRef (TerminalFlowNativeHandoffIdentity handoff)
                        let reasonText = terminalFlowRatifiedHandoffRedriveReasonText reason
                        let redriveOccurrence, emitRedrive =
                            DiagJson.sparseLogDecision
                                (sprintf "ratified_handoff_redrive|%u|%s" handoffRef reasonText)
                                256L
                        if emitRedrive then
                            DiagJson.emitTerminalJsonDurable (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_ratified_handoff_redrive_required\",\"handoff_ref\":%u,\"reason_du\":%s,\"actor_phase_du\":%s,\"occurrence_count\":%d,\"sparse_policy\":\"state_first3_power2_every256\",\"authority\":\"nonterminal_handoff_cannot_consume_affine_stage_token\",\"next\":\"redrive_dispatch_without_stage_token_issue\"}" [| box handoffRef; box (DiagJson.esc reasonText); box (DiagJson.esc (DiagJson.terminalSchedulerPushActorPhaseText (DiagJson.terminalSchedulerPushActorSnapshot()).phase)); box redriveOccurrence |])
                        terminalFlowGlobalDispatchRequestPrune capability.pending.fillKey
                        let redriveState =
                            match terminalFlowDispatchLifecycleConstitution consumeState.dispatchLifecycle with
                            | TerminalFlowDispatchConstitutionIssued issuance ->
                                let lineageRef = terminalFlowDispatchConstitutionLineageRef issuance.constitution
                                if emitRedrive then
                                    DiagJson.emitTerminalJsonDurable (
                                        FastRuntimeFormat.format "{\"kind\":\"terminal_dispatch_redrive_protocol_armed\",\"prior_issuance_ref\":%u,\"prior_exact_once_ref\":%u,\"constitution_ref\":%u,\"constitution_lineage_ref\":%u,\"request_ref\":%u,\"reason_du\":%s,\"occurrence_count\":%d,\"sparse_policy\":\"state_first3_power2_every256\",\"rank_regression\":false,\"next\":\"republish_same_lineage_then_mint_new_issuance\",\"authority\":\"single_reducer_typed_redrive_edge\"}" [| box issuance.issuanceRef; box issuance.exactOnceRef; box issuance.constitution.constitutionRef; box lineageRef; box issuance.requestRef; box (DiagJson.esc reasonText); box redriveOccurrence |])
                                terminalFlowGlobalWithDispatchConstitution (TerminalFlowDispatchConstitutionReady issuance.constitution) consumeState
                            | _ -> consumeState
                        terminalFlowGlobalConsumeHandoff redriveState capability None
                | None ->
                    terminalFlowGlobalConsumeHandoff consumeState capability None
            | TerminalFlowAppliedCapabilityRejected missingEvidence ->
                let missingEvidenceText = terminalFlowQapMissingEvidenceText missingEvidence
                let missingEvidenceCount = (terminalFlowQapMissingEvidenceCount missingEvidence)
                let qapFinalizationState, finalizationTransactionRef, finalizationExactOnceRef =
                    match state.qapFinalization with
                    | TerminalFlowQapFinalizationIdle -> "Idle", 0u, 0u
                    | TerminalFlowQapFinalizationPrepared finalization -> "Prepared", finalization.transactionRef, finalization.exactOnceRef
                    | TerminalFlowQapFinalizationCommitted finalization -> "Committed", finalization.transactionRef, finalization.exactOnceRef
                    | TerminalFlowQapFinalizationHandoffEnqueued finalization -> "HandoffEnqueued", finalization.transactionRef, finalization.exactOnceRef
                let envelopeTransactionRef, envelopeExactOnceRef, capturedPendingReceiptId, capturedFillKey, proofDecisionText, proofMissingEvidenceText, proofRef, qapSccCertificateRef, qapSccGenerationRef =
                    match state.qapPostCommit with
                    | TerminalFlowQapPostCommitApplied envelope ->
                        let capturedReceipt, capturedFill =
                            match envelope.pendingTerminal with
                            | TerminalFlowPendingSlotCandidate captured -> captured.terminalReceiptId, captured.fillKey
                            | TerminalFlowPendingSlotAwaitingCandidate -> "", ""
                        let proofDecisionText, proofMissingEvidenceText, qapSccCertificateRef, qapSccGenerationRef, proofRef, _ = terminalFlowQapPostCommitProofProjection envelope.proof
                        envelope.transaction.transactionRef, envelope.transaction.exactOnceRef, capturedReceipt, capturedFill, proofDecisionText, proofMissingEvidenceText, proofRef, qapSccCertificateRef, qapSccGenerationRef
                    | _ -> 0u, 0u, "", "", "Nothing", "post_commit_not_applied", 0u, 0u, 0u
                let pendingReceiptId, pendingFillKey, pendingAdmissionRef =
                    match state.pendingTerminal with
                    | TerminalFlowPendingSlotCandidate pending -> pending.terminalReceiptId, pending.fillKey, terminalFlowPendingAdmissionRef pending.admission
                    | TerminalFlowPendingSlotAwaitingCandidate -> "", "", 0u
                let installedReceiptId, installedFillKey, installedAdmissionRef =
                    match terminalFlowOutcomeInstallationAdmission state.outcomeInstallation with
                    | Some installed -> terminalFlowIdentityRefText installed.terminalReceiptRef, TerminalFlowFillKeyId.text installed.fillKey, terminalFlowAdmissionRawRef installed.identity
                    | None -> "", "", 0u
                let capabilityBlockKey =
                    FastRuntimeFormat.format "qap_applied_capability_blocked|%s|%s|%u|%u|%u|%u" [| box missingEvidenceText; box qapFinalizationState; box finalizationTransactionRef; box envelopeTransactionRef; box installedAdmissionRef; box pendingAdmissionRef |]
                let capabilityBlockOccurrenceCount, shouldEmitCapabilityBlock = DiagJson.sparseLogDecision capabilityBlockKey 64L
                if shouldEmitCapabilityBlock then
                    let assessmentFields =
                        FastRuntimeFormat.format "\"applied_capability_du\":%s,\"missing_evidence_count\":%d,\"missing_evidence_du\":%s,\"qap_finalization_state_du\":%s" [| box (DiagJson.esc (terminalFlowAppliedCapabilityAssessmentText (TerminalFlowAppliedCapabilityRejected missingEvidence))); box missingEvidenceCount; box (DiagJson.esc missingEvidenceText); box (DiagJson.esc qapFinalizationState) |]
                    let transactionFields =
                        FastRuntimeFormat.format "\"finalization_transaction_ref\":%u,\"envelope_transaction_ref\":%u,\"finalization_exact_once_ref\":%u,\"envelope_exact_once_ref\":%u" [| box finalizationTransactionRef; box envelopeTransactionRef; box finalizationExactOnceRef; box envelopeExactOnceRef |]
                    let pendingFields =
                        FastRuntimeFormat.format "\"captured_pending_receipt_id\":%s,\"pending_receipt_id\":%s,\"captured_fill_key\":%s,\"pending_fill_key\":%s" [| box (DiagJson.esc capturedPendingReceiptId); box (DiagJson.esc pendingReceiptId); box (DiagJson.esc capturedFillKey); box (DiagJson.esc pendingFillKey) |]
                    let installationFields =
                        FastRuntimeFormat.format "\"installed_terminal_receipt_id\":%s,\"installed_fill_key\":%s,\"installed_admission_ref\":%u,\"pending_admission_ref\":%u" [| box (DiagJson.esc installedReceiptId); box (DiagJson.esc installedFillKey); box installedAdmissionRef; box pendingAdmissionRef |]
                    let proofFields =
                        FastRuntimeFormat.format "\"proof_decision_du\":%s,\"proof_missing_evidence_du\":%s,\"post_commit_proof_ref\":%u,\"qap_scc_certificate_ref\":%u,\"qap_scc_generation_ref\":%u" [| box (DiagJson.esc proofDecisionText); box (DiagJson.esc proofMissingEvidenceText); box proofRef; box qapSccCertificateRef; box qapSccGenerationRef |]
                    let capabilityBlockJson =
                        FastRuntimeFormat.format "{\"kind\":\"terminal_qap_applied_capability_blocked\",%s,%s,%s,%s,%s,\"occurrence_count\":%d,\"sparse_policy\":\"state_first3_power2_every64\",\"authority\":\"typed_applied_capability_assessment\",\"next\":\"await_typed_missing_evidence_transition\"}" [| box assessmentFields; box transactionFields; box pendingFields; box installationFields; box proofFields; box capabilityBlockOccurrenceCount |]
                    DiagJson.emitTerminalJsonDurable capabilityBlockJson
                match state.qapPostCommit with
                | TerminalFlowQapPostCommitApplied envelope ->
                    let capturedProgressSequence =
                        envelope.projection.progressAuthority.accepted
                        |> Option.map (fun evidence -> evidence.snapshotSequence)
                        |> Option.defaultValue 0L
                    let currentProgressSequence =
                        state.progressAuthority.accepted
                        |> Option.map (fun evidence -> evidence.snapshotSequence)
                        |> Option.defaultValue 0L
                    let progressCapableComponents =
                        missingEvidence
                        |> terminalFlowQapMissingEvidenceToList
                        |> List.collect terminalFlowQapMissingEvidenceProgressCapableComponents
                        |> List.distinct
                    if currentProgressSequence > capturedProgressSequence
                       && not (List.isEmpty progressCapableComponents) then
                        let replanDecision = terminalFlowQapPostCommitPlanFor state envelope.transaction
                        let nextPlanRef, _, _ = terminalFlowQapPostCommitPlanDecisionProjection replanDecision
                        let replannedState, replannedCommand =
                            terminalFlowQapPostCommitPlanDecisionStateAndCommand state replanDecision
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_qap_scc_replanned_after_progress\",\"prior_plan_ref\":%u,\"next_plan_ref\":%u,\"finalization_transaction_id\":%u,\"captured_progress_sequence\":%d,\"current_progress_sequence\":%d,\"progress_capable_component_count\":%d,\"progress_capable_component_refs\":%s,\"plan_decision_du\":%s,\"authority\":\"single_reducer_progress_versioned_qap_replan\",\"next\":\"schedule_only_if_proof_certified\"}" [| box envelope.planRef; box nextPlanRef; box envelope.transaction.transactionRef; box capturedProgressSequence; box currentProgressSequence; box progressCapableComponents.Length; box (DiagJson.esc (progressCapableComponents |> List.map string |> String.concat ";")); box (DiagJson.esc (match replanDecision with | TerminalFlowQapPostCommitPlanScheduled _ -> "Scheduled" | TerminalFlowQapPostCommitPlanAwaitingEvidence awaiting -> "AwaitingEvidence:" + terminalFlowQapMissingEvidenceText awaiting.missingEvidence)) |])
                        replannedState, replannedCommand
                    else
                        state,
                        TerminalFlowGlobalServerAwaitDataflow(terminalFlowQapPostCommitAppliedWaitReason state)
                | _ ->
                    state,
                    TerminalFlowGlobalServerAwaitDataflow(terminalFlowQapPostCommitAppliedWaitReason state)

        let private terminalFlowGlobalReduce state event =
            match event with
            | TerminalFlowGlobalServerEvaluatorRootResolved(receiptId, resolvedAtMs, evidenceRef, _) ->
                match state.kernel.root with
                | KernelRootResolved(existingReceipt, _, _) when terminalFlowIdentityRefText existingReceipt <> receiptId ->
                    state, TerminalFlowGlobalServerFailClosed(
                        TerminalFlowFailureCanonicalRootReceiptDiverged(
                            terminalFlowRootReceiptRef existingReceipt,
                            terminalFlowRootReceiptRefText receiptId))
                | _ ->
                    let kernel =
                        terminalFlowKernelStateFor
                            state.kernel.revision
                            (KernelRootResolved(terminalFlowIdentityRefOfText receiptId, resolvedAtMs, evidenceRef))
                            state.kernel.outcome
                            state.kernel.actor
                            state.kernel.dispatch
                            state.kernel.exit
                    let next = terminalFlowGlobalReducerAdvance state event kernel state.pendingTerminal
                    match next.pendingTerminal with
                    | TerminalFlowPendingSlotCandidate pending when pending.intent = TerminalFlowPendingFailClosed ->
                        next, TerminalFlowGlobalServerFailClosed(terminalFlowPendingFailClosedFailure pending)
                    | TerminalFlowPendingSlotCandidate _ ->
                        terminalFlowGlobalTryConsumeAppliedHandoff next None
                    | TerminalFlowPendingSlotAwaitingCandidate -> next, TerminalFlowGlobalServerAwaitDataflow TerminalFlowWaitRootResolvedAwaitOutcome
            | TerminalFlowGlobalServerTerminalOutcomeReady pending
                when (match pending.intent, pending.admission with
                      | TerminalFlowPendingQuarantine, TerminalFlowPendingAdmissionEvaluatorNotice _ -> true
                      | _ -> false) ->
                let sourceRef = terminalFlowPendingAdmissionRef pending.admission
                let failureRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "terminal-outcome-observer-quarantine-rejected"
                        (FastRuntimeFormat.format "%s|%s|%u" [| box pending.terminalReceiptId; box pending.fillKey; box sourceRef |])
                if not (terminalFlowTerminalSemanticWorkFailForRefs pending.terminalReceiptRef pending.fillKeyId failureRef) then
                    invalidOp "rejected quarantine terminal candidate semantic credit could not be failed"
                state, TerminalFlowGlobalServerFailClosed(TerminalFlowFailureObserverQuarantineRejected sourceRef)
            | TerminalFlowGlobalServerTerminalOutcomeReady pending ->
                let acceptPendingTerminal (pendingTerminal:TerminalFlowGlobalPendingTerminal) waitReason =
                    let admissionRef = terminalFlowPendingAdmissionRef pendingTerminal.admission
                    let installPath = terminalFlowPendingAdmissionInstallPath pendingTerminal.admission
                    let pendingTerminal =
                        match terminalFlowOutcomeInstallationAdmission state.outcomeInstallation with
                        | Some existing
                            when terminalFlowAdmissionRawRef existing.identity = admissionRef
                                 && existing.terminalReceiptRef = pendingTerminal.terminalReceiptRef
                                 && existing.fillKey = pendingTerminal.fillKeyId
                                 && existing.installPath = installPath ->
                            terminalFlowPendingCandidateWithIdentityForRefs existing.terminalReceiptRef existing.fillKey pendingTerminal
                        | _ -> pendingTerminal
                    let admission =
                        terminalFlowOutcomeAdmissionForIdentityRefs
                            pendingTerminal.terminalReceiptRef
                            pendingTerminal.fillKeyId
                            pendingTerminal.admissionIdentity
                            installPath
                    let installTransition = terminalFlowOutcomeInstallTransitionFor state.outcomeInstallation admission (state.kernel.revision + 1L)
                    let installation = terminalFlowOutcomeInstallTransitionState installTransition
                    let kernel =
                        terminalFlowKernelStateFor
                            state.kernel.revision
                            state.kernel.root
                            (KernelOutcomeSealed(pendingTerminal.terminalReceiptRef, pendingTerminal.fillKeyId))
                            state.kernel.actor
                            state.kernel.dispatch
                            state.kernel.exit
                    let advanced = terminalFlowGlobalReducerAdvance state event kernel (TerminalFlowPendingSlotCandidate pendingTerminal)
                    let next =
                        { advanced with outcomeInstallation = installation }
                        |> terminalFlowDispatchConstitutionRefresh
                        |> terminalFlowGlobalRefreshBreakthrough
                    let maturity = terminalFlowPendingOutcomeMaturity pendingTerminal.intent
                    let progressSnapshotRef, progressBp =
                        match state.progressAuthority.accepted with
                        | Some evidence ->
                            terminalFlowIdentityRefDigest evidence.snapshotRef,
                            if evidence.frontier.discovered <= 0L then 0
                            else int (min 10000L ((evidence.frontier.retired * 10000L) / evidence.frontier.discovered))
                        | None -> 0u, 0
                    terminalFlowEmitAdvancedConsoleProjection {
                        lane = TerminalFlowConsoleLaneOutcomeMaturity
                        sequence = next.revision
                        progressBp = progressBp
                        etaMs = if terminalFlowPendingOutcomeIsFinal pendingTerminal.intent && progressBp >= 10000 then Some 0L else None
                        title = if terminalFlowPendingOutcomeIsFinal pendingTerminal.intent then "final terminal outcome accepted" else "provisional terminal outcome retained"
                        detail = FastRuntimeFormat.format "%s|terminal_ref=%u|fill_ref=%u|snapshot_ref=%u|dispatch_authority=%s|dispatch_consumable=%b" [| box (terminalFlowOutcomeMaturityText maturity); box (terminalFlowPendingTerminalReceiptDigest pendingTerminal); box (terminalFlowPendingFillDigest pendingTerminal); box progressSnapshotRef; box (terminalFlowPendingDispatchAuthorityText pendingTerminal.dispatchAuthority); box (terminalFlowPendingOutcomeIsFinal pendingTerminal.intent && terminalFlowPendingDispatchIsExecutable pendingTerminal.dispatchAuthority) |]
                        authorityRef = terminalFlowOutcomeMaturityRef maturity
                    }
                    match next.kernel.root with
                    | KernelRootResolved _ when pendingTerminal.intent = TerminalFlowPendingFailClosed ->
                        next, TerminalFlowGlobalServerFailClosed(terminalFlowPendingFailClosedFailure pendingTerminal)
                    | KernelRootResolved _ ->
                        let replanAfterLateOutcome priorStage priorPlanRef transaction =
                            let replanDecision = terminalFlowQapPostCommitPlanFor next transaction
                            let nextPlanRef, _, _ = terminalFlowQapPostCommitPlanDecisionProjection replanDecision
                            let replannedState, replannedCommand =
                                terminalFlowQapPostCommitPlanDecisionStateAndCommand next replanDecision
                            DiagJson.emitTerminalJsonDurable (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_qap_post_commit_replanned_after_late_outcome\",\"prior_stage_du\":%s,\"prior_plan_ref\":%u,\"next_plan_ref\":%u,\"finalization_transaction_id\":%u,\"terminal_ref\":%u,\"fill_ref\":%u,\"stale_pending_capture_repaired\":true,\"plan_decision_du\":%s,\"authority\":\"single_reducer_late_outcome_rebind\",\"next\":\"schedule_only_if_proof_certified\"}" [| box (DiagJson.esc priorStage); box priorPlanRef; box nextPlanRef; box transaction.transactionRef; box (terminalFlowPendingTerminalReceiptDigest pendingTerminal); box (terminalFlowPendingFillDigest pendingTerminal); box (DiagJson.esc (match replanDecision with | TerminalFlowQapPostCommitPlanScheduled _ -> "Scheduled" | TerminalFlowQapPostCommitPlanAwaitingEvidence awaiting -> "AwaitingEvidence:" + terminalFlowQapMissingEvidenceText awaiting.missingEvidence)) |])
                            terminalFlowEmitAdvancedConsoleProjection {
                                lane = TerminalFlowConsoleLaneReducerRecovery
                                sequence = next.revision
                                progressBp = progressBp
                                etaMs = None
                                title = "late terminal outcome rebound into post-commit"
                                detail = FastRuntimeFormat.format "prior_stage=%s|prior_plan=%u|next_plan=%u|terminal_ref=%u|fill_ref=%u" [| box priorStage; box priorPlanRef; box nextPlanRef; box (terminalFlowPendingTerminalReceiptDigest pendingTerminal); box (terminalFlowPendingFillDigest pendingTerminal) |]
                                authorityRef = nextPlanRef
                            }
                            replannedState, replannedCommand
                        match next.qapPostCommit with
                        | TerminalFlowQapPostCommitAwaitingEvidence awaiting when terminalFlowPendingSlotIsAbsent awaiting.pendingTerminal ->
                            replanAfterLateOutcome "AwaitingEvidence" awaiting.planRef awaiting.transaction
                        | TerminalFlowQapPostCommitFairnessScheduled envelope when terminalFlowPendingSlotIsAbsent envelope.pendingTerminal ->
                            replanAfterLateOutcome "FairnessScheduled" envelope.planRef envelope.transaction
                        | TerminalFlowQapPostCommitRecoveryScheduled envelope when terminalFlowPendingSlotIsAbsent envelope.pendingTerminal ->
                            replanAfterLateOutcome "RecoveryScheduled" envelope.planRef envelope.transaction
                        | TerminalFlowQapPostCommitOwnerWorkDagScheduled envelope when terminalFlowPendingSlotIsAbsent envelope.pendingTerminal ->
                            replanAfterLateOutcome "OwnerWorkDagScheduled" envelope.planRef envelope.transaction
                        | TerminalFlowQapPostCommitApplied appliedEnvelope when terminalFlowPendingSlotIsAbsent appliedEnvelope.pendingTerminal ->
                            match terminalFlowQapPostCommitDispositionFor (Ok appliedEnvelope.proof) with
                            | TerminalFlowQapPostCommitAwaitEvidence _
                            | TerminalFlowQapPostCommitReady ->
                                replanAfterLateOutcome "Applied" appliedEnvelope.planRef appliedEnvelope.transaction
                            | _ -> terminalFlowGlobalTryConsumeAppliedHandoff next None
                        | TerminalFlowQapPostCommitIdle ->
                            match next.qapFinalization with
                            | TerminalFlowQapFinalizationCommitted transaction ->
                                replanAfterLateOutcome "IdleCommitted" 0u transaction
                            | TerminalFlowQapFinalizationPrepared _
                            | TerminalFlowQapFinalizationHandoffEnqueued _
                            | TerminalFlowQapFinalizationIdle ->
                                terminalFlowGlobalTryConsumeAppliedHandoff next None
                        | _ -> terminalFlowGlobalTryConsumeAppliedHandoff next None
                    | KernelRootAwaitingEvaluator -> next, TerminalFlowGlobalServerAwaitDataflow waitReason
                let supersedePendingTerminal existing =
                    let existingRef = terminalFlowPendingTerminalRef existing
                    let incomingRef = terminalFlowPendingTerminalRef pending
                    let supersedeSemanticWork (loser:TerminalFlowGlobalPendingTerminal) (winner:TerminalFlowGlobalPendingTerminal) =
                        let loserRef = terminalFlowPendingTerminalRef loser
                        let winnerRef = terminalFlowPendingTerminalRef winner
                        let sameSemanticWorkUnit =
                            loser.terminalReceiptRef = winner.terminalReceiptRef
                            && loser.fillRef = winner.fillRef
                        let transitionRef =
                            CompilerIdentityKernel.ContentDigest.ofText
                                "terminal-outcome-candidate-superseded"
                                (FastRuntimeFormat.format "%u|%u" [| box loserRef; box winnerRef |])
                        let resolved =
                            if sameSemanticWorkUnit then false
                            else terminalFlowTerminalSemanticWorkSupersedeForRefs loser.terminalReceiptRef loser.fillKeyId transitionRef
                        if (not sameSemanticWorkUnit) && not resolved then
                            invalidOp "distinct terminal loser semantic credit could not be superseded"
                        let admittedCount, receiptCount = CompilerKernelV2.SemanticWorkLedgerAuthority.counts ()
                        let semanticCreditDecision = CompilerKernelV2.SemanticWorkLedgerAuthority.creditDecision ()
                        let semanticOpenCount = CompilerKernelV2.SemanticWorkCreditDecision.openUnitCount semanticCreditDecision
                        let semanticCreditDigest = CompilerKernelV2.SemanticWorkCreditDecision.digest semanticCreditDecision
                        let semanticWorkKeyRelation =
                            if sameSemanticWorkUnit then "shared_work_unit_retained"
                            else "distinct_loser_work_unit_superseded"
                        let disposition =
                            if sameSemanticWorkUnit then "SharedWorkUnitRetained"
                            else "WorkUnitSuperseded"
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_outcome_candidate_semantic_credit_resolved\",\"loser_ref\":%u,\"winner_ref\":%u,\"transition_ref\":%s,\"resolved\":%b,\"semantic_admitted_count\":%d,\"semantic_receipt_count\":%d,\"semantic_open_count\":%d,\"semantic_credit_digest\":%s,\"semantic_work_key_relation_du\":%s,\"disposition_du\":%s,\"authority\":\"terminal_outcome_arbitration_conserved_credit\"}" [| box loserRef; box winnerRef; box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text transitionRef)); box resolved; box admittedCount; box receiptCount; box semanticOpenCount; box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text semanticCreditDigest)); box (DiagJson.esc semanticWorkKeyRelation); box (DiagJson.esc disposition) |])
                    let arbitration = terminalFlowPendingCandidateArbitrationFor state existing pending
                    let existingMaturity = terminalFlowPendingOutcomeMaturity existing.intent
                    let incomingMaturity = terminalFlowPendingOutcomeMaturity pending.intent
                    let existingGreenPathReady =
                        match state.greenPath with
                        | Some green -> terminalFlowGreenPathDispatchReadyReceipt green |> Result.isOk
                        | None -> false
                    let existingRedriveEligible =
                        match arbitration.decision with
                        | TerminalFlowExistingCandidatePrecedesIncoming ->
                            terminalFlowPendingDispatchIsExecutable existing.dispatchAuthority
                            && terminalFlowPendingOutcomeIsFinal existing.intent
                            && existingGreenPathReady
                        | _ -> false
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_outcome_candidate_arbitration\",\"decision_du\":%s,\"precedence_reason_du\":%s,\"existing_ref\":%u,\"incoming_ref\":%u,\"existing_candidate_class_du\":%s,\"incoming_candidate_class_du\":%s,\"existing_intent_class_du\":%s,\"incoming_intent_class_du\":%s,\"existing_intent_du\":%s,\"incoming_intent_du\":%s,\"existing_dispatch_authority_du\":%s,\"incoming_dispatch_authority_du\":%s,\"numeric_rank_authority_retired\":true,\"reducer_closed\":%b,\"existing_green_path_ready\":%b,\"existing_redrive_eligible\":%b,\"authority\":\"typed_candidate_precedence_relation\"}" [| box (DiagJson.esc (terminalFlowPendingCandidateArbitrationDecisionText arbitration.decision)); box (DiagJson.esc (terminalFlowCandidatePrecedenceReasonText arbitration.reason)); box existingRef; box incomingRef; box (DiagJson.esc (terminalFlowPendingCandidateClassText arbitration.existingClass)); box (DiagJson.esc (terminalFlowPendingCandidateClassText arbitration.incomingClass)); box (DiagJson.esc (terminalFlowPendingIntentClassText arbitration.existingIntentClass)); box (DiagJson.esc (terminalFlowPendingIntentClassText arbitration.incomingIntentClass)); box (DiagJson.esc (terminalFlowPendingIntentText existing.intent)); box (DiagJson.esc (terminalFlowPendingIntentText pending.intent)); box (DiagJson.esc (terminalFlowPendingDispatchAuthorityText existing.dispatchAuthority)); box (DiagJson.esc (terminalFlowPendingDispatchAuthorityText pending.dispatchAuthority)); box arbitration.reducerClosed; box existingGreenPathReady; box existingRedriveEligible |])
                    match arbitration.decision with
                    | TerminalFlowIncomingCandidatePrecedesExisting
                    | TerminalFlowEquivalentCandidateLaterReducerArrival ->
                        supersedeSemanticWork existing pending
                        let progressSnapshotRef, progressBp =
                            match state.progressAuthority.accepted with
                            | Some evidence ->
                                terminalFlowIdentityRefDigest evidence.snapshotRef,
                                if evidence.frontier.discovered <= 0L then 0
                                else int (min 10000L ((evidence.frontier.retired * 10000L) / evidence.frontier.discovered))
                            | None -> 0u, 0
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_outcome_supersession\",\"superseded_ref\":%u,\"superseding_ref\":%u,\"superseded_intent_du\":%s,\"superseding_intent_du\":%s,\"superseded_maturity_du\":%s,\"superseding_maturity_du\":%s,\"superseded_dispatch_authority_du\":%s,\"superseding_dispatch_authority_du\":%s,\"superseded_dispatch_authority_ref\":%u,\"superseding_dispatch_authority_ref\":%u,\"superseded_maturity_ref\":%u,\"superseding_maturity_ref\":%u,\"progress_snapshot_ref\":%u,\"dispatch_open\":true,\"fill_once_applies_to\":\"Final\",\"authority\":\"terminal_flow_global_reducer\"}" [| box existingRef; box incomingRef; box (DiagJson.esc (terminalFlowPendingIntentText existing.intent)); box (DiagJson.esc (terminalFlowPendingIntentText pending.intent)); box (DiagJson.esc (terminalFlowOutcomeMaturityText existingMaturity)); box (DiagJson.esc (terminalFlowOutcomeMaturityText incomingMaturity)); box (DiagJson.esc (terminalFlowPendingDispatchAuthorityText existing.dispatchAuthority)); box (DiagJson.esc (terminalFlowPendingDispatchAuthorityText pending.dispatchAuthority)); box (terminalFlowPendingDispatchAuthorityRef existing.dispatchAuthority); box (terminalFlowPendingDispatchAuthorityRef pending.dispatchAuthority); box (terminalFlowOutcomeMaturityRef existingMaturity); box (terminalFlowOutcomeMaturityRef incomingMaturity); box progressSnapshotRef |])
                        terminalFlowEmitAdvancedConsoleProjection {
                            lane = TerminalFlowConsoleLaneOutcomeMaturity
                            sequence = state.revision + 1L
                            progressBp = progressBp
                            etaMs = None
                            title = "terminal outcome superseded"
                            detail = FastRuntimeFormat.format "%s -> %s|final_dispatch_only=true|snapshot_ref=%u" [| box (terminalFlowOutcomeMaturityText existingMaturity); box (terminalFlowOutcomeMaturityText incomingMaturity); box progressSnapshotRef |]
                            authorityRef = incomingRef
                        }
                        acceptPendingTerminal pending (TerminalFlowWaitOutcomeCandidateReplaced(existingRef, incomingRef))
                    | TerminalFlowExistingCandidatePrecedesIncoming when existingRedriveEligible ->
                        supersedeSemanticWork pending existing
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_outcome_candidate_retained_redrive\",\"kept_ref\":%u,\"incoming_ref\":%u,\"green_path_ref\":%u,\"kept_dispatch_authority_ref\":%u,\"incoming_dispatch_authority_ref\":%u,\"authority\":\"higher_rank_executable_candidate_redrive\",\"next\":\"consume_owner_debt_applied_capability_or_emit_typed_blocker\"}" [| box existingRef; box incomingRef; box (state.greenPath |> Option.map terminalFlowGreenPathReceiptRef |> Option.defaultValue 0u); box (terminalFlowPendingDispatchAuthorityRef existing.dispatchAuthority); box (terminalFlowPendingDispatchAuthorityRef pending.dispatchAuthority) |])
