                match state.pendingTerminal with
                | TerminalFlowPendingSlotCandidate existing when existing.fillRef <> pending.fillRef && existing.terminalReceiptRef = pending.terminalReceiptRef ->
                    let pendingTerminalText = terminalFlowIdentityRefText pending.terminalReceiptRef
                    let existingFillText = TerminalFlowFillKeyId.text existing.fillKeyId
                    let pendingFillText = TerminalFlowFillKeyId.text pending.fillKeyId
                    let failureRef =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "terminal-outcome-fill-key-diverged"
                            (FastRuntimeFormat.format "%s|%s|%s" [| box pendingTerminalText; box existingFillText; box pendingFillText |])
