            | TerminalFlowGlobalServerDispatchRequested request ->
                let requestRef = request.requestRef
                let requestRootRef = terminalFlowIdentityRefDigest (terminalFlowDispatchJoinRootRef request.joinKey)
                let requestTerminalRef = terminalFlowIdentityRefDigest (terminalFlowDispatchJoinTerminalRef request.joinKey)
                let requestFillRef = terminalFlowIdentityRefDigest (terminalFlowDispatchJoinFillRef request.joinKey)
                match (terminalFlowDispatchLifecycleConstitution state.dispatchLifecycle) with
                | TerminalFlowDispatchConstitutionReady constitution
                    when request.publication = TerminalFlowDispatchFirstPublication
                         && constitution.rootRef = requestRootRef
                         && constitution.terminalRef = requestTerminalRef
                         && constitution.fillRef = requestFillRef
                         && terminalFlowDispatchConstitutionLineageRef constitution = request.constitutionLineageRef
                         && constitution.pendingTerminalRef = request.pendingTerminalRef
                         && constitution.admissionRef = request.admissionRef
                         && constitution.admissionIdentityRef = request.admissionIdentityRef ->
                    let requestDigest =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "dispatch-request"
                            (FastRuntimeFormat.format "%u:%u" [| box requestRef; box request.constitutionLineageRef |])
                    let credentialBundleDigest =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "dispatch-credential-bundle"
                            (CompilerIdentityKernel.ContentDigest.text constitution.proofDigest
                             + "|request=" + CompilerIdentityKernel.ContentDigest.text requestDigest)
