                            (CompilerIdentityKernel.ContentDigest.text constitution.proofDigest
                             + "|bundle=" + CompilerIdentityKernel.ContentDigest.text credentialBundle.bundleDigest
                             + "|request=" + CompilerIdentityKernel.ContentDigest.text requestDigest)
                    let issuance : TerminalFlowDispatchIssuance<TerminalFlowDispatchConstitutionIssuedStage> =
                        { admission = constitution
                          request = request
                          credentials = credentialBundle
                          issuanceDigest = issuanceDigest
                          issuedAtRevision = state.revision + 1L }
                    let dispatchKernel = terminalFlowKernelAcceptedDispatchForRequest request
                    let kernel =
                        terminalFlowKernelStateFor
