                        advanced
                        |> terminalFlowGlobalWithDispatchConstitution (TerminalFlowDispatchConstitutionIssued issued)
                        |> terminalFlowGlobalRefreshBreakthrough
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format
                            "{\"kind\":\"terminal_dispatch_admission_erasure_issued\",\"credential_bundle_ref\":%u,\"issuance_ref\":%u,\"admission_ref\":%u,\"admission_identity_ref\":%u,\"constitution_lineage_ref\":%u,\"request_constitution_lineage_ref\":%u,\"request_constitution_lineage_proof_ref\":%u,\"proof_digest\":%s,\"reducer_revision\":%d,\"authority\":\"recursive_dispatch_admission_erasure\",\"next\":\"execute_issued_dispatch\"}"
                            [| box issued.credentials.bundleRef
                               box issued.issuanceRef
                               box issued.constitution.admissionRef
                               box issued.constitution.admissionIdentityRef
                               box (terminalFlowDispatchConstitutionLineageRef issued.constitution)
                               box issued.request.constitutionLineageRef
                               box issued.request.constitutionLineageProofRef
                               box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text issued.constitution.proofDigest))
