                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format
                            "{\"kind\":\"terminal_dispatch_attempted\",\"decision_du\":\"issued_recursive_admission\",\"issuance_ref\":%u,\"constitution_ref\":%u,\"request_ref\":%u,\"credential_bundle_ref\":%u,\"constitution_lineage_ref\":%u,\"request_constitution_lineage_ref\":%u,\"request_constitution_lineage_proof_ref\":%u,\"green_path_ref\":%u,\"installation_ref\":%u,\"order_ref\":%u,\"fill_ref\":%u,\"blocker_du\":\"none\",\"authority\":\"recursive_dispatch_admission_erasure\"}"
                            [| box issued.issuanceRef
