                               box issued.credentials.bundleRef
                               box (terminalFlowDispatchConstitutionLineageRef issued.constitution)
                               box issued.request.constitutionLineageRef
                               box issued.request.constitutionLineageProofRef
                               box issued.constitution.greenPathDispatchReceipt.receiptRef
                               box (terminalFlowIdentityRefDigest issued.constitution.installationRef)
                               box issued.constitution.totalOrderAwaitDispatch.receiptRef
                               box issued.constitution.fillRef |])
                    next, TerminalFlowGlobalServerExecuteDispatch issued
                | TerminalFlowDispatchConstitutionReady constitution when request.publication = TerminalFlowDispatchDuplicatePublication ->
                    DiagJson.emitTerminalJsonDurable (
                        sprintf "{\"kind\":\"terminal_dispatch_attempted\",\"decision_du\":\"duplicate_suppressed\",\"constitution_ref\":%u,\"request_ref\":%u,\"blocker_du\":\"dispatch_duplicate\",\"authority\":\"single_reducer_dispatch_constitution\"}"
                            constitution.constitutionRef requestRef)
                    state, TerminalFlowGlobalServerAwaitDataflow(TerminalFlowWaitDispatchDuplicate requestRef)
                | TerminalFlowDispatchConstitutionReady constitution ->
                    let constitutionLineageMatches = terminalFlowDispatchConstitutionLineageRef constitution = request.constitutionLineageRef
                    let rootMatches = constitution.rootRef = requestRootRef
                    let terminalMatches = constitution.terminalRef = requestTerminalRef
                    let fillMatches = constitution.fillRef = requestFillRef
                    let pendingMatches = constitution.pendingTerminalRef = request.pendingTerminalRef
                    let admissionMatches = constitution.admissionRef = request.admissionRef
                    let admissionIdentityMatches = constitution.admissionIdentityRef = request.admissionIdentityRef
                    let mismatches =
                        terminalFlowDispatchJoinMismatchEvidenceFor
                            constitutionLineageMatches
