                            terminalMatches
                            fillMatches
                            pendingMatches
                            admissionMatches
                            admissionIdentityMatches
                    let mismatchText =
                        mismatches
                        |> terminalFlowNonEmptyEvidenceToList
                        |> List.map terminalFlowDispatchJoinMismatchText
                        |> String.concat ","
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_dispatch_attempted\",\"decision_du\":\"join_rejected\",\"constitution_ref\":%u,\"request_ref\":%u,\"mismatches_du\":%s,\"constitution_lineage_ref\":%u,\"request_constitution_lineage_ref\":%u,\"request_constitution_lineage_proof_ref\":%u,\"constitution_pending_ref\":%u,\"request_pending_ref\":%u,\"constitution_admission_ref\":%u,\"request_admission_ref\":%u,\"constitution_admission_identity_ref\":%u,\"request_admission_identity_ref\":%u,\"blocker_du\":\"join_key_diverged\",\"authority\":\"typed_nonempty_dispatch_join_mismatch_set\"}" [| box constitution.constitutionRef; box requestRef; box (DiagJson.esc mismatchText); box (terminalFlowDispatchConstitutionLineageRef constitution); box request.constitutionLineageRef; box request.constitutionLineageProofRef; box constitution.pendingTerminalRef; box request.pendingTerminalRef; box constitution.admissionRef; box request.admissionRef; box constitution.admissionIdentityRef; box request.admissionIdentityRef |])
