                | TerminalFlowDispatchAffineIssued transaction ->
                    state, TerminalFlowGlobalServerAwaitDataflow(TerminalFlowWaitDispatchDuplicate transaction.authorization.issuance.requestRef)
                | TerminalFlowDispatchAffineFilled transaction ->
