                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_qap_post_commit_idle_closed_graph_seeded\",\"idle_for_revisions\":%d,\"revision_bound\":%d,\"recovery_ref\":%u,\"qap_fixpoint_ref\":%u,\"source_snapshot_ref\":%u,\"relation_count\":0,\"disposition_du\":\"SeedClosedGraphFixpoint\",\"actor_mailbox_requeue\":true,\"trigger_du\":\"ProgressEvidenceClosedGraph\",\"authority\":\"single_reducer_physical_semantic_closed_graph\",\"next\":\"observe_empty_fixpoint_then_reenter_qap_finalizer\"}" [| box idleForRevisions; box terminalFlowQapPostCommitIdleRecoveryRevisionBound; box recoveryRef; box (terminalFlowDurableRefValue fixpointRef); box sourceSnapshotRef |])
