                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_qap_post_commit_idle_fixpoint_reobserved\",\"idle_for_revisions\":%d,\"revision_bound\":%d,\"recovery_ref\":%u,\"qap_fixpoint_ref\":%u,\"material_age_ms\":%d,\"disposition_du\":\"ReobserveWitnessedFixpoint\",\"actor_mailbox_requeue\":true,\"trigger_du\":\"ProgressEvidenceRevision\",\"authority\":\"single_reducer_installed_outcome_plus_existing_qap_watch\",\"next\":\"reenter_qap_finalizer_then_plan_post_commit\"}" [| box idleForRevisions; box terminalFlowQapPostCommitIdleRecoveryRevisionBound; box recoveryRef; box (terminalFlowDurableRefValue watch.fixpointRef); box materialAgeMs |])
