                             && terminalFlowDurableRefValue existing.writerJobRef = terminalFlowDurableRefValue commit.writerJobRef
                             && terminalFlowDurableRefValue existing.artifactReceiptRef = terminalFlowDurableRefValue commit.artifactReceiptRef
                             && terminalFlowDurableRefValue existing.exitWitnessRef = terminalFlowDurableRefValue commit.exitWitnessRef
