                        state, TerminalFlowGlobalServerAwaitDataflow(TerminalFlowWaitTerminalOrderAlreadyChosen(terminalFlowGlobalTerminalOrderRef state.terminalOrder))
                    | _ ->
                        let advanced = terminalFlowGlobalReducerAdvance state event state.kernel state.pendingTerminal
                        let next =
                            { advanced with
                                terminalOrder = TerminalFlowGlobalOrderCommitsObserved (terminalFlowGlobalCommitUpsert commit commits)
                                qapMaturityWatch = None }
                        next, TerminalFlowGlobalServerAwaitDataflow(TerminalFlowWaitActorProgress DiagJson.PushActorExitWitnessQueued)
