                    state, TerminalFlowGlobalServerAwaitDataflow(TerminalFlowWaitTerminalOrderAlreadyChosen(terminalFlowGlobalTerminalOrderRef state.terminalOrder))
            | TerminalFlowGlobalServerExitWitnessReady request ->
                terminalFlowRememberIndexedClosureExitRequest request |> ignore
                let matchingCommit : TerminalFlowGlobalCommitObservation option =
                    match request.origin, state.terminalOrder with
                    | TerminalFlowGlobalExitFromBreakthroughDone proof, TerminalFlowGlobalOrderCommitsObserved commits ->
                        match terminalFlowGlobalCommitTryFind request.fillKeyId commits with
                        | Some commit
                            when proof.writerJobRef = terminalFlowDurableRefValue commit.writerJobRef
                                 && proof.artifactReceiptRef = terminalFlowDurableRefValue commit.artifactReceiptRef
                                 && proof.exitWitnessRef = terminalFlowDurableRefValue commit.exitWitnessRef
                                 && proof.runEndReceiptRef = terminalFlowDurableRefValue commit.runEndReceiptRef -> Some commit
                        | _ -> None
