                | TerminalFlowQapPostCommitOwnerWorkDagCompleted (Error missingEvidence), _ ->
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_qap_post_commit_missing_evidence_superseded\",\"missing_evidence_du\":%s,\"missing_evidence_count\":%d,\"reducer_revision\":%d,\"authority\":\"typed_completion_without_matching_stage_is_observer_only\",\"next\":\"await_matching_generation_or_replan\"}" [| box (DiagJson.esc (terminalFlowQapMissingEvidenceText missingEvidence)); box (terminalFlowQapMissingEvidenceCount missingEvidence); box advanced.revision |])
                    advanced, TerminalFlowGlobalServerAwaitDataflow(TerminalFlowWaitQapPostCommitEvidence(0u, 0u, missingEvidence))
            | TerminalFlowGlobalServerStageTokenIssued _ ->
                let advanced =
                    terminalFlowGlobalReducerAdvance state event state.kernel state.pendingTerminal
                    |> terminalFlowGlobalProjectReducerActor
                    |> terminalFlowGlobalRefreshBreakthrough
                let phase, _, _ = terminalFlowReducerActorPhaseAndFillKey advanced.pendingTerminal advanced.qapOutcomeActorAuthority.actor
                advanced, TerminalFlowGlobalServerAwaitDataflow(TerminalFlowWaitActorProgress phase)
            | TerminalFlowGlobalServerStageTokenFillCommitted _ ->
                let advanced =
                    terminalFlowGlobalReducerAdvance state event state.kernel state.pendingTerminal
                    |> fun next -> { next with qapMaturityWatch = None }
                    |> terminalFlowGlobalProjectReducerActor
                    |> terminalFlowGlobalRefreshBreakthrough
                let phase, _, _ = terminalFlowReducerActorPhaseAndFillKey advanced.pendingTerminal advanced.qapOutcomeActorAuthority.actor
                advanced, TerminalFlowGlobalServerAwaitDataflow(TerminalFlowWaitActorProgress phase)
            | TerminalFlowGlobalServerStageTokenSealAuthorized _ ->
                let advanced =
                    terminalFlowGlobalReducerAdvance state event state.kernel state.pendingTerminal
                    |> fun next -> { next with qapMaturityWatch = None }
                    |> terminalFlowGlobalProjectReducerActor
                    |> terminalFlowGlobalRefreshBreakthrough
                let phase, _, _ = terminalFlowReducerActorPhaseAndFillKey advanced.pendingTerminal advanced.qapOutcomeActorAuthority.actor
                advanced, TerminalFlowGlobalServerAwaitDataflow(TerminalFlowWaitActorProgress phase)
            | TerminalFlowGlobalServerStageTokenFailedClosed _ ->
                let advanced =
                    terminalFlowGlobalReducerAdvance state event state.kernel state.pendingTerminal
                    |> fun next -> { next with qapMaturityWatch = None }
                    |> terminalFlowGlobalProjectReducerActor
                    |> terminalFlowGlobalRefreshBreakthrough
                let phase, _, _ = terminalFlowReducerActorPhaseAndFillKey advanced.pendingTerminal advanced.qapOutcomeActorAuthority.actor
                advanced, TerminalFlowGlobalServerAwaitDataflow(TerminalFlowWaitActorProgress phase)
            | TerminalFlowGlobalServerActorProjectionObserved snapshot ->
                let advanced = terminalFlowGlobalReducerAdvance state event state.kernel state.pendingTerminal
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_flow_actor_possession_projection_compared\",\"observed_phase_du\":%s,\"observed_fill_ref\":%u,\"observed_dispatch_ref\":%u,\"actor_authority_mutated\":false,\"kernel_authority_mutated\":false,\"authority\":\"single_reducer_terminal_possession_projection\"}" [| box (DiagJson.esc (DiagJson.terminalSchedulerPushActorPhaseText snapshot.phase)); box (terminalFlowMintedRefOf "observed_actor_fill_ref" snapshot.fillKey); box (terminalFlowMintedRefOf "observed_actor_dispatch_ref" snapshot.dispatchId) |])
                advanced, TerminalFlowGlobalServerAwaitDataflow(TerminalFlowWaitActorProgress snapshot.phase)

        type private TerminalFlowProductionAuditObserver =
            private TerminalFlowProductionAuditObserver of
                (TerminalFlowGlobalServerEvent -> TerminalFlowGlobalReducerState -> TerminalFlowGlobalServerCommand -> unit)

        let mutable private terminalFlowProductionAuditObserver : TerminalFlowProductionAuditObserver option = None

        let private terminalFlowProductionAuditObserve event next command =
            match terminalFlowProductionAuditObserver with
            | Some (TerminalFlowProductionAuditObserver observer) -> observer event next command
            | None -> ()

        let private terminalFlowProductionAuditInstall observer =
            match terminalFlowProductionAuditObserver with
            | None ->
                terminalFlowProductionAuditObserver <-
                    Some (TerminalFlowProductionAuditObserver observer)
            | Some _ ->
                invalidOp "terminal production audit observer is single-assignment"

        type TerminalFlowQapFinalizationCommitReceipt = private {
            transactionRef : uint32
            sourceEventRef : uint32
            qapGeneration : uint64
            proofRef : uint32
            stateRevisionBefore : int64
            stateRevisionAfter : int64
            dispatchConstitutionBeforeRef : uint32
            dispatchConstitutionAfterRef : uint32
            commandRef : uint32
            postCommitPlanRef : uint32
            postCommitStageOrdinal : int
            handoffEnqueued : bool
            openCicObligationsCount : int64
            hopacLaneWaitReason : string
            causalParentRef : uint32
            reducerAdvanceBlockerId : uint32
            exactOnceRef : uint32
        }

        let private terminalFlowGlobalCommitPreparedQapFinalization
            (state:TerminalFlowGlobalReducerState)
            (proposedCommand:TerminalFlowGlobalServerCommand)
            : TerminalFlowGlobalReducerState * TerminalFlowGlobalServerCommand * TerminalFlowQapFinalizationCommitReceipt option =
            match state.qapFinalization with
            | TerminalFlowQapFinalizationPrepared prepared ->
                let constitutionBeforeRef =
                    (terminalFlowDispatchLifecycleConstitution state.dispatchLifecycle)
                    |> terminalFlowDispatchConstitutionStateText
                    |> terminalFlowMintedRefOf "terminal_dispatch_constitution_before_commit_ref"
                let committedPreRefresh = terminalFlowQapFinalizationTransactionCommit prepared
                let committedState =
                    { state with qapFinalization = TerminalFlowQapFinalizationCommitted committedPreRefresh }
                    |> terminalFlowDispatchConstitutionRefresh
                    |> terminalFlowGlobalRefreshBreakthrough
                let committedDecision =
                    terminalFlowQapFinalOutcomeDispatchDecisionFor
                        committedState.progressAuthority.accepted
                        committedState.progressAuthority.rejected
                        committedState.greenPath
                        committedState.pendingTerminal
                let committed =
                    { committedPreRefresh with dispatchDecision = committedDecision }
                let committedState =
                    { committedState with qapFinalization = TerminalFlowQapFinalizationCommitted committed }
                // MIGRATION: commit remains a pure state transformation.  Fairness,
                // recovery and owner/workdag work is represented as a post-commit
                // command; no global cell assignment or consume helper runs here.
                let postCommitPlanDecision = terminalFlowQapPostCommitPlanFor committedState committed
                let postCommitPlanRef, _, postCommitStageOrdinal =
                    terminalFlowQapPostCommitPlanDecisionProjection postCommitPlanDecision
                let committedState =
                    { committedState with qapFinalization = TerminalFlowQapFinalizationCommitted committed }
                let finalState, handoffCommand =
                    terminalFlowQapPostCommitPlanDecisionStateAndCommand committedState postCommitPlanDecision
                let constitutionAfterRef =
                    (terminalFlowDispatchLifecycleConstitution finalState.dispatchLifecycle)
                    |> terminalFlowDispatchConstitutionStateText
                    |> terminalFlowMintedRefOf "terminal_dispatch_constitution_after_commit_ref"
                let commandRef = terminalFlowGlobalServerCommandRef handoffCommand
                let receipt =
                    { transactionRef = committed.transactionRef
                      sourceEventRef = committed.sourceEventRef
                      qapGeneration = terminalFlowQapGenerationValue committed.generation.generation
                      proofRef = committed.proofRef
                      stateRevisionBefore = committed.stateRevisionBefore
                      stateRevisionAfter = finalState.revision
                      dispatchConstitutionBeforeRef = constitutionBeforeRef
                      dispatchConstitutionAfterRef = constitutionAfterRef
                      commandRef = commandRef
                      postCommitPlanRef = postCommitPlanRef
                      postCommitStageOrdinal = postCommitStageOrdinal
                      handoffEnqueued =
                        match handoffCommand with
                        | TerminalFlowGlobalServerPublishDispatchRequest _
                        | TerminalFlowGlobalServerConsumeStageToken _
                        | TerminalFlowGlobalServerFailClosed _ -> true
                        | _ -> false
                      openCicObligationsCount =
                        match finalState.progressAuthority.accepted with
                        | Some evidence ->
                            evidence.frontier.queueKindCounts.universeConstraint
                            + evidence.frontier.queueKindCounts.defEqObligation
                        | None -> 0L
                      hopacLaneWaitReason =
                        match handoffCommand with
                        | TerminalFlowGlobalServerRunQapPostCommitEffect _ -> "AwaitPostCommitEffect"
                        | TerminalFlowGlobalServerPublishDispatchRequest _ -> "AwaitWorkerLease"
                        | TerminalFlowGlobalServerConsumeStageToken _ -> "AwaitConsumeAuth"
                        | TerminalFlowGlobalServerFailClosed _ -> "FailClosed"
                        | _ -> "AwaitCredentialProof"
                      causalParentRef = committed.sourceEventRef
                      reducerAdvanceBlockerId =
                        match handoffCommand with
                        | TerminalFlowGlobalServerFailClosed failure ->
                            terminalFlowMintedRefOf "terminal_reducer_advance_blocker_ref" (terminalFlowGlobalFailureText failure)
                        | TerminalFlowGlobalServerAwaitDataflow reason ->
                            terminalFlowMintedRefOf "terminal_reducer_advance_blocker_ref" (terminalFlowGlobalWaitReasonText reason)
                        | _ -> 0u
                      exactOnceRef =
                        terminalFlowMintedRefOf
                            "terminal_qap_finalization_commit_exact_once_ref"
                            (FastRuntimeFormat.format "%u:%u:%u:%u:%d:%d" [| box committed.transactionRef; box committed.exactOnceRef; box commandRef; box postCommitPlanRef; box postCommitStageOrdinal; box finalState.revision |]) }
                finalState, handoffCommand, Some receipt
            | _ -> state, proposedCommand, None

        let private terminalFlowQapFinalizationCommitReceiptEmit
            (receipt:TerminalFlowQapFinalizationCommitReceipt) =
            DiagJson.emitTerminalJsonDurable (
                FastRuntimeFormat.format "{\"kind\":\"terminal_qap_finalization_transaction_committed\",\"finalization_transaction_id\":%u,\"source_event_ref\":%u,\"causal_parent_ref\":%u,\"qap_generation_id\":%d,\"proof_ref\":%u,\"state_revision_before\":%d,\"state_revision_after\":%d,\"state_commit_attempted\":true,\"state_commit_applied\":true,\"state_commit_receipt_id\":%u,\"dispatch_constitution_before_ref\":%u,\"dispatch_constitution_after_ref\":%u,\"commands_enqueued\":1,\"final_outcome_handoff_enqueued\":%b,\"command_ref\":%u,\"post_commit_plan_ref\":%u,\"post_commit_stage_ordinal\":%d,\"open_cic_obligations_count\":%d,\"hopac_lane_wait_reason\":%s,\"reducer_advance_blocker_id\":%u,\"authority\":\"single_reducer_atomic_commit_before_effects\"}" [| box receipt.transactionRef; box receipt.sourceEventRef; box receipt.causalParentRef; box receipt.qapGeneration; box receipt.proofRef; box receipt.stateRevisionBefore; box receipt.stateRevisionAfter; box receipt.exactOnceRef; box receipt.dispatchConstitutionBeforeRef; box receipt.dispatchConstitutionAfterRef; box receipt.handoffEnqueued; box receipt.commandRef; box receipt.postCommitPlanRef; box receipt.postCommitStageOrdinal; box receipt.openCicObligationsCount; box (DiagJson.esc receipt.hopacLaneWaitReason); box receipt.reducerAdvanceBlockerId |])

        // The reducer transition remains a pure actor-owned state transformation.
        // The wrapper publishes only a read-only Processing mirror before entering it;
        // no observer may mutate reducer authority through that compatibility state.
        // Internal events are reduced synchronously after this function returns, so the
        // actor advances without a deadlocking mailbox round-trip.
        let private terminalFlowGlobalReduceOwned
            (state:TerminalFlowGlobalReducerState)
            (event:TerminalFlowGlobalServerEvent) =
            let reducerEventRef =
                terminalFlowMintedRefOf
                    "terminal_reducer_event_ref"
                    (terminalFlowGlobalServerEventText event)
            let revisionBefore = state.revision
            let processingStartedAtMs = Environment.TickCount64
            let processingState =
                { state with
                    reducerQuiescence =
                        TerminalFlowReducerProcessing(
                            reducerEventRef,
                            processingStartedAtMs,
                            revisionBefore) }
            // Publish Processing before entering the synchronous reducer transition.
            // Previously the compatibility mirror remained Idle until reduce returned,
            // so callbacks described a wedged actor as quiescent and filled the deferred
            // slot with conflicting observer envelopes. This write changes observation
            // truth only; the actor remains the sole transition owner.
            lock terminalFlowGlobalReducerProjectionGate (fun () ->
                terminalFlowGlobalReducerProjectionMirror <- processingState)
            DiagJson.emitTerminalJsonDurable (
                FastRuntimeFormat.format "{\"kind\":\"terminal_reducer_transition_entered\",\"event_ref\":%u,\"event_kind_du\":%s,\"revision_before\":%d,\"processing_started_at_ms\":%d,\"reducer_quiescence_du\":\"Processing\",\"authority\":\"single_reducer_actor_pretransition_mirror\",\"next\":\"reduce_owned_event\"}" [| box reducerEventRef; box (DiagJson.esc (terminalFlowGlobalServerEventKind event)); box revisionBefore; box processingStartedAtMs |])
            let reducedNext, proposedCommand = terminalFlowGlobalReduce processingState event
            DiagJson.emitTerminalJsonDurable (
                FastRuntimeFormat.format "{\"kind\":\"terminal_reducer_transition_reduced\",\"event_ref\":%u,\"event_kind_du\":%s,\"revision_before\":%d,\"revision_after_reduce\":%d,\"reduce_elapsed_ms\":%d,\"proposed_command_ref\":%u,\"authority\":\"single_reducer_actor_posttransition_receipt\",\"next\":\"commit_prepared_qap_finalization\"}" [| box reducerEventRef; box (DiagJson.esc (terminalFlowGlobalServerEventKind event)); box revisionBefore; box reducedNext.revision; box (max 0L (Environment.TickCount64 - processingStartedAtMs)); box (terminalFlowGlobalServerCommandRef proposedCommand) |])
            let committedNext, committedCommand, commitReceipt =
                terminalFlowGlobalCommitPreparedQapFinalization reducedNext proposedCommand
            let replannedNext, replannedCommand =
                terminalFlowQapPostCommitReplanAwaitingEvidence committedNext committedCommand
            let next =
                { replannedNext with
                    reducerQuiescence = TerminalFlowReducerIdle replannedNext.revision }
            let gatedCommand = terminalFlowLifecycleCommandGate next replannedCommand
            let next, command =
                match gatedCommand with
                | TerminalFlowGlobalServerFailClosed(
                    TerminalFlowFailureDispatchLifecyclePoisoned(_, _, commandRef, _)) ->
                    let lifecycle =
                        terminalFlowDispatchLifecycleMarkPoisonFailClosedIssued
                            next.revision
                            commandRef
                            next.dispatchLifecycle
                    { next with dispatchLifecycle = lifecycle }, gatedCommand
                | _ -> next, gatedCommand
            commitReceipt |> Option.iter terminalFlowQapFinalizationCommitReceiptEmit
            // Semantic completion is reducer-owned evidence and must not depend on an
            // optional ProgressEvidenceObserved publication.  Every reducer revision
            // gets one exact-once chance to request the BuildOk once the static seed is
            // proven closed; the registry inside the request keeps this side effect
            // idempotent while the resulting candidate re-enters through the mailbox.
            let _semanticClosureBuildOkRequested =
                terminalFlowRequestBuildOkForSemanticClosure next
            // Every reducer event advances the revision clock. Idle recovery therefore
            // cannot depend on an optional progress-observer event being published.
            match terminalFlowQapPostCommitIdleRecoveryDispositionFor next with
            | Some (TerminalFlowQapPostCommitIdleSeedClosedGraphFixpoint(idleForRevisions, recoveryRef, fixpointRef, fixpoint, sourceSnapshotRef))
                when terminalFlowQapPostCommitIdleRecoveryRegistry.TryAdd(recoveryRef, 0uy) ->
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_qap_post_commit_idle_closed_graph_seeded\",\"idle_for_revisions\":%d,\"revision_bound\":%d,\"recovery_ref\":%u,\"qap_fixpoint_ref\":%u,\"source_snapshot_ref\":%u,\"relation_count\":0,\"disposition_du\":\"SeedClosedGraphFixpoint\",\"actor_mailbox_requeue\":true,\"trigger_du\":\"AnyReducerRevisionClosedGraph\",\"authority\":\"single_reducer_physical_semantic_closed_graph\",\"next\":\"observe_empty_fixpoint_then_reenter_qap_finalizer\"}" [| box idleForRevisions; box terminalFlowQapPostCommitIdleRecoveryRevisionBound; box recoveryRef; box (terminalFlowDurableRefValue fixpointRef); box sourceSnapshotRef |])
                terminalFlowGlobalServerPublish (
                    TerminalFlowGlobalServerQapFixpointObserved(
                        fixpointRef,
                        fixpoint,
                        fixpoint.materialQuiescenceAgeMs,
                        TerminalFlowQapMaturityCandidateObserved))
            | Some (TerminalFlowQapPostCommitIdleReobserveFixpoint(idleForRevisions, recoveryRef, watch))
                when terminalFlowQapPostCommitIdleRecoveryRegistry.TryAdd(recoveryRef, 0uy) ->
                let materialAgeMs =
                    max watch.observedMaterialAgeMs (max 0L (Environment.TickCount64 - watch.observedAtMs))
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_qap_post_commit_idle_fixpoint_reobserved\",\"idle_for_revisions\":%d,\"revision_bound\":%d,\"recovery_ref\":%u,\"qap_fixpoint_ref\":%u,\"material_age_ms\":%d,\"disposition_du\":\"ReobserveWitnessedFixpoint\",\"actor_mailbox_requeue\":true,\"trigger_du\":\"AnyReducerRevision\",\"authority\":\"single_reducer_installed_outcome_plus_existing_qap_watch\",\"next\":\"reenter_qap_finalizer_then_plan_post_commit\"}" [| box idleForRevisions; box terminalFlowQapPostCommitIdleRecoveryRevisionBound; box recoveryRef; box (terminalFlowDurableRefValue watch.fixpointRef); box materialAgeMs |])
                terminalFlowGlobalServerPublish (
                    TerminalFlowGlobalServerQapFixpointObserved(
                        watch.fixpointRef,
                        watch.fixpoint,
                        materialAgeMs,
                        TerminalFlowQapMaturityWitnessedByReducer))
            | Some (TerminalFlowQapPostCommitIdleAwaitQapWatch idleForRevisions) ->
                terminalFlowTryPublishQapIdleFailClosed next idleForRevisions |> ignore
            | _ -> ()
            match event with
            | TerminalFlowGlobalServerQapPostCommitEffectCompleted completion ->
                let planRef, transactionRef, stageOrdinal, proofRejectionCount =
                    match completion with
                    | TerminalFlowQapPostCommitFairnessCompleted result ->
                        terminalFlowQapPostCommitStageResultProjection result
                    | TerminalFlowQapPostCommitRecoveryCompleted result ->
                        terminalFlowQapPostCommitStageResultProjection result
                    | TerminalFlowQapPostCommitOwnerWorkDagCompleted result ->
                        terminalFlowQapPostCommitStageResultProjection result
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_qap_post_commit_effect_applied\",\"plan_ref\":%u,\"finalization_transaction_id\":%u,\"stage_ordinal\":%d,\"missing_evidence_count\":%d,\"state_revision_after\":%d,\"authority\":\"single_reducer_actor_recursive_proof_commit\"}" [| box planRef; box transactionRef; box stageOrdinal; box proofRejectionCount; box next.revision |])
            | _ -> ()
            terminalFlowProductionAuditObserve event next command
            match terminalFlowTakeDeferredOutcomeForReducer () with
            | Some pending ->
                let mailboxWakePublished, publicationRef =
                    terminalFlowPublishDeferredOutcomeMailboxOnce pending
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_flow_global_deferred_outcome_reducer_requeued\",\"terminal_outcome_ref\":%u,\"fill_ref\":%u,\"source_event_ref\":%u,\"reducer_revision_before_requeue\":%d,\"mailbox_publication_ref\":%u,\"mailbox_wake_published\":%b,\"delivery_du\":\"ReducerActorMailboxExactOnceRequeue\",\"nested_reduce\":false,\"authority\":\"single_reducer_actor\"}" [| box (terminalFlowPendingTerminalReceiptDigest pending); box (terminalFlowPendingFillDigest pending); box (terminalFlowMintedRefOf "terminal_reducer_event_ref" (terminalFlowGlobalServerEventText event)); box next.revision; box publicationRef; box mailboxWakePublished |])
            | None -> ()
            next, command

        let private terminalFlowQapObservationPlanAdmissionRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,byte>()

        let private terminalFlowGlobalReducerProjectionPublish (state:TerminalFlowGlobalReducerState) =
            state.progressAuthority.accepted
            |> Option.iter (terminalFlowLiveProgressEvidenceObserve TerminalFlowLiveProgressAcceptedForControl)
            lock terminalFlowGlobalReducerProjectionGate (fun () ->
                terminalFlowGlobalReducerProjectionMirror <- state)
            DiagJson.installPostRootWriterLeaseReducerAuthorityProvider (fun () ->
                let projected =
                    lock terminalFlowGlobalReducerProjectionGate (fun () -> terminalFlowGlobalReducerProjectionMirror)
                let projectedSnapshot = terminalFlowImmutableTerminalSnapshotFor projected
                let active =
                    match projectedSnapshot.terminalStage with
                    | TerminalFlowTerminalSnapshotOutcomeArmed
                    | TerminalFlowTerminalSnapshotOutcomeFilled -> true
                    | _ -> false
                let terminalReceipt =
                    if projectedSnapshot.runEndReceiptRef = 0u then None
                    else Some (string projectedSnapshot.runEndReceiptRef)
                Some (active, projectedSnapshot.reducerRevision, terminalReceipt))
            let terminalSnapshot = terminalFlowImmutableTerminalSnapshotFor state
            let terminalSnapshotRef = CompilerIdentityKernel.ContentDigest.text terminalSnapshot.snapshotRef
            let operationalGraphRef = CompilerIdentityKernel.ContentDigest.text terminalSnapshot.operationalGraphRef
            let runtimeAuthorityRef = CompilerIdentityKernel.ContentDigest.text terminalSnapshot.runtimeAuthorityRef
            let qapObservationPlanRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "terminal-qap-observation-plan"
                    (string terminalSnapshot.operationalRevision
                     + "|" + operationalGraphRef
                     + "|epoch=" + string terminalSnapshot.semanticEpoch
                     + "|runtime=" + runtimeAuthorityRef)
            let qapObservationPlanText = CompilerIdentityKernel.ContentDigest.text qapObservationPlanRef
            let qapGenerationRef =
                terminalSnapshot.qapGenerationValue |> Option.map string |> Option.defaultValue ""
            let qapStageId =
                match terminalSnapshot.qapStage with
                | Some TerminalFlowQapGenerationAwaiting -> CompilerConsoleHud88.ReducerHudQapAwaiting
                | Some TerminalFlowQapGenerationProgressing -> CompilerConsoleHud88.ReducerHudQapProgressing
                | Some TerminalFlowQapGenerationDrained -> CompilerConsoleHud88.ReducerHudQapDrained
                | Some TerminalFlowQapGenerationDeadlocked -> CompilerConsoleHud88.ReducerHudQapDeadlocked
                | None -> CompilerConsoleHud88.ReducerHudQapAwaiting
            let qapStageText = CompilerConsoleHud88.reducerHudQapStageText qapStageId
            if terminalSnapshot.qapGenerationValue.IsNone && terminalSnapshot.operationalRevision > 0L then
                let occurrence, emitObservationPlan =
                    DiagJson.sparseLogDecision ("terminal_qap_observation_plan_seeded|" + qapObservationPlanText) 64L
                if emitObservationPlan then
                    DiagJson.emitOutsideHopac (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_qap_observation_plan_seeded\",\"observation_plan_ref\":%s,\"operational_revision\":%d,\"operational_graph_ref\":%s,\"semantic_epoch\":%d,\"runtime_authority_ref\":%s,\"qap_generation_present\":false,\"terminal_authority\":false,\"occurrence_count\":%d,\"authority\":\"operational_snapshot_seeds_non_authorizing_qap_observation_plan\",\"next\":\"qap_watch_consumes_plan_then_mints_generation\"}" [| box (DiagJson.esc qapObservationPlanText); box terminalSnapshot.operationalRevision; box (DiagJson.esc operationalGraphRef); box terminalSnapshot.semanticEpoch; box (DiagJson.esc runtimeAuthorityRef); box occurrence |])
                if terminalFlowQapObservationPlanAdmissionRegistry.TryAdd(qapObservationPlanRef, 0uy) then
                    let planFixpointSetRef : TerminalFlowQapFixpointRef<TerminalFlowQapFixpointSetRefKind> =
                        terminalFlowQapFixpointRefCreate qapObservationPlanText
                    let planFixpoint : TerminalFlowQapFixpointSet =
                        { setRef = planFixpointSetRef
                          items = []
                          materialQuiescenceAgeMs = 0L
                          maturity = TerminalFlowQapFixpointAwaitingReducerWitness
                          terminalDecision = TerminalFlowQapAwaitMaterialOrWaker }
                    let planFixpointRef : TerminalFlowDurableRef<TerminalFlowQapFixpointReceiptRefKind> =
                        TerminalFlowDurableRef(
                            terminalFlowMintedRefOf
                                "qap_observation_plan_fixpoint_ref"
                                qapObservationPlanText)
                    terminalFlowGlobalServerPublish (
                        TerminalFlowGlobalServerQapFixpointObserved(
                            planFixpointRef,
                            planFixpoint,
                            0L,
                            TerminalFlowQapMaturityCandidateObserved))
                    DiagJson.emitOutsideHopac (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_qap_observation_plan_admitted\",\"observation_plan_ref\":%s,\"qap_fixpoint_ref\":%u,\"operational_revision\":%d,\"semantic_epoch\":%d,\"terminal_authority\":false,\"authority\":\"reducer_mailbox_admits_observation_plan_as_awaiting_qap_generation\",\"next\":\"qap_generation_created_then_real_fixpoint_rebases\"}" [| box (DiagJson.esc qapObservationPlanText); box (terminalFlowDurableRefValue planFixpointRef); box terminalSnapshot.operationalRevision; box terminalSnapshot.semanticEpoch |])
            let refText value = if value = 0u then "" else string value
            let possession, terminalPhase =
                match terminalSnapshot.terminalStage with
                | TerminalFlowTerminalSnapshotMaterial
                | TerminalFlowTerminalSnapshotQapAwaiting
                | TerminalFlowTerminalSnapshotQapProgressing
                | TerminalFlowTerminalSnapshotQapFinal ->
                    CompilerConsoleHud88.ReducerHudPossessionVacant, CompilerConsoleHud88.ReducerHudMaterial
                | TerminalFlowTerminalSnapshotOutcomeArmed ->
                    CompilerConsoleHud88.ReducerHudPossessionArmed, CompilerConsoleHud88.ReducerHudTerminalizing
                | TerminalFlowTerminalSnapshotOutcomeFilled ->
                    CompilerConsoleHud88.ReducerHudPossessionFilled, CompilerConsoleHud88.ReducerHudTerminalizing
                | TerminalFlowTerminalSnapshotRunEnded ->
                    CompilerConsoleHud88.ReducerHudPossessionExitWitnessQueued, CompilerConsoleHud88.ReducerHudTerminalizing
                | TerminalFlowTerminalSnapshotPhysicalExit ->
                    CompilerConsoleHud88.ReducerHudPossessionSealed, CompilerConsoleHud88.ReducerHudComplete
                | TerminalFlowTerminalSnapshotFailedClosed ->
                    CompilerConsoleHud88.ReducerHudPossessionFailedClosed, CompilerConsoleHud88.ReducerHudComplete
            let sealedAtMs =
                match state.reducerTerminalSeal with
                | TerminalFlowReducerTerminalSealAwaitStageToken -> None
                | TerminalFlowReducerTerminalSealPhysicalExitSelected chain
                | TerminalFlowReducerTerminalSealFailClosedSelected chain ->
                    Some chain.physicalExit.issuedAtMs
            let occurrence, emit =
                DiagJson.sparseLogDecision ("terminal_immutable_snapshot_committed|" + terminalSnapshotRef) 256L
            if emit
               || terminalSnapshot.terminalStage = TerminalFlowTerminalSnapshotRunEnded
               || terminalSnapshot.terminalStage = TerminalFlowTerminalSnapshotPhysicalExit
               || terminalSnapshot.terminalStage = TerminalFlowTerminalSnapshotFailedClosed then
                DiagJson.emitOutsideHopac (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_immutable_snapshot_committed\",\"terminal_snapshot_ref\":%s,\"reducer_revision\":%d,\"operational_revision\":%d,\"operational_graph_ref\":%s,\"runtime_authority_ref\":%s,\"semantic_epoch\":%d,\"qap_generation_ref\":%s,\"qap_stage_du\":%s,\"terminal_stage_du\":%s,\"actor_ref\":%u,\"terminal_ref\":%u,\"fill_ref\":%u,\"commit_receipt_ref\":%u,\"done_receipt_ref\":%u,\"run_end_receipt_ref\":%u,\"physical_exit_receipt_ref\":%u,\"exit_code\":%s,\"occurrence_count\":%d,\"authority\":\"operational_graph_semantic_epoch_runtime_contract_qap_total_order_snapshot\"}" [| box (DiagJson.esc terminalSnapshotRef); box terminalSnapshot.reducerRevision; box terminalSnapshot.operationalRevision; box (DiagJson.esc operationalGraphRef); box (DiagJson.esc runtimeAuthorityRef); box terminalSnapshot.semanticEpoch; box (DiagJson.esc qapGenerationRef); box (DiagJson.esc qapStageText); box (DiagJson.esc (terminalFlowImmutableTerminalStageText terminalSnapshot.terminalStage)); box terminalSnapshot.actorRef; box terminalSnapshot.terminalRef; box terminalSnapshot.fillRef; box terminalSnapshot.commitReceiptRef; box terminalSnapshot.doneReceiptRef; box terminalSnapshot.runEndReceiptRef; box terminalSnapshot.physicalExitReceiptRef; box (terminalSnapshot.exitCode |> Option.map string |> Option.defaultValue "null"); box occurrence |])
            match CompilerConsoleHud88.readReducerHudSnapshot () with
            | None -> None
            | Some snapshot ->
                Some {
                    snapshot with
                        generation = max snapshot.generation terminalSnapshot.reducerRevision
                        snapshotMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                        phase = terminalPhase
                        possession = possession
                        actorRef = refText terminalSnapshot.actorRef
                        stageTokenRef = refText terminalSnapshot.terminalRef
                        fillReceiptRef = refText terminalSnapshot.fillRef
                        runEndReceiptRef = refText terminalSnapshot.runEndReceiptRef
                        physicalExitReceiptRef = refText terminalSnapshot.physicalExitReceiptRef
                        terminalSnapshotRef = terminalSnapshotRef
                        operationalRevision = terminalSnapshot.operationalRevision
                        operationalGraphRef = operationalGraphRef
                        runtimeAuthorityRef = runtimeAuthorityRef
                        semanticEpoch = terminalSnapshot.semanticEpoch
                        qapGenerationRef = qapGenerationRef
                        qapStage = qapStageId
                        commitReceiptRef = refText terminalSnapshot.commitReceiptRef
                        doneReceiptRef = refText terminalSnapshot.doneReceiptRef
                        exitCode = terminalSnapshot.exitCode
                        sealedAtMs = sealedAtMs
                }
 

        let private terminalFlowGlobalReducerPublishHudSnapshot (state:TerminalFlowGlobalReducerState) =
            job {
                let projectionStartedAtMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                match terminalFlowGlobalReducerProjectionPublish state with
                | None ->
                    DiagJson.emitOutsideHopac (
                        sprintf "{\"kind\":\"reducer_hud_snapshot_unavailable\",\"reducer_revision\":%d,\"authority\":\"single_reducer_actor\",\"legacy_cache_authority\":false}" state.revision)
                | Some snapshot ->
                    // Presentation is an observer. Enqueue the snapshot and immediately
                    // return ownership to the reducer; a stalled HUD mailbox may never hold
                    // root, outcome, QAP or physical-exit evidence behind an acknowledgement.
                    CompilerConsoleHud88.publishReducerHudSnapshot snapshot
                    let possessionText =
                        match snapshot.possession with
                        | CompilerConsoleHud88.ReducerHudPossessionVacant -> "vacant"
                        | CompilerConsoleHud88.ReducerHudPossessionArmed -> "armed"
                        | CompilerConsoleHud88.ReducerHudPossessionFilled -> "filled"
                        | CompilerConsoleHud88.ReducerHudPossessionWriterBound -> "writer_bound"
                        | CompilerConsoleHud88.ReducerHudPossessionArtifactsCommitted -> "artifacts_committed"
                        | CompilerConsoleHud88.ReducerHudPossessionExitWitnessQueued -> "exit_witness_queued"
                        | CompilerConsoleHud88.ReducerHudPossessionSealed -> "sealed"
                        | CompilerConsoleHud88.ReducerHudPossessionFailedClosed -> "failed_closed"
                    let transitionKey =
                        possessionText + "|" + snapshot.runEndReceiptRef + "|" + snapshot.physicalExitReceiptRef
                    let occurrence, emit = DiagJson.sparseLogDecision ("reducer_hud_snapshot_enqueued|" + transitionKey) 256L
                    if emit || not (String.IsNullOrWhiteSpace snapshot.physicalExitReceiptRef) then
                        DiagJson.emitOutsideHopac (
                            FastRuntimeFormat.format "{\"kind\":\"reducer_hud_snapshot_enqueued\",\"reducer_revision\":%d,\"snapshot_generation\":%d,\"terminal_snapshot_ref\":%s,\"operational_revision\":%d,\"operational_graph_ref\":%s,\"runtime_authority_ref\":%s,\"semantic_epoch\":%d,\"qap_generation_ref\":%s,\"qap_stage_du\":%s,\"possession_stage_du\":%s,\"commit_receipt_ref\":%s,\"done_receipt_ref\":%s,\"run_end_receipt_ref\":%s,\"physical_exit_receipt_ref\":%s,\"exit_code\":%s,\"sealed_at_ms\":%s,\"occurrence_count\":%d,\"delivery_du\":\"NonBlockingObserverMailbox\",\"reducer_waited_for_ack\":false,\"authority\":\"operational_graph_semantic_epoch_runtime_contract_qap_total_order_snapshot\",\"legacy_cache_authority\":false}" [| box state.revision; box snapshot.generation; box (DiagJson.esc snapshot.terminalSnapshotRef); box snapshot.operationalRevision; box (DiagJson.esc snapshot.operationalGraphRef); box (DiagJson.esc snapshot.runtimeAuthorityRef); box snapshot.semanticEpoch; box (DiagJson.esc snapshot.qapGenerationRef); box (DiagJson.esc (CompilerConsoleHud88.reducerHudQapStageText snapshot.qapStage)); box (DiagJson.esc possessionText); box (DiagJson.esc snapshot.commitReceiptRef); box (DiagJson.esc snapshot.doneReceiptRef); box (DiagJson.esc snapshot.runEndReceiptRef); box (DiagJson.esc snapshot.physicalExitReceiptRef); box (DiagJson.esc (snapshot.exitCode |> Option.map string |> Option.defaultValue "")); box (DiagJson.esc (snapshot.sealedAtMs |> Option.map string |> Option.defaultValue "")); box occurrence |])
                let projectionElapsedMs =
                    max 0L (DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - projectionStartedAtMs)
                if projectionElapsedMs >= 250L then
                    DiagJson.emitOutsideHopac (
                        sprintf "{\"kind\":\"terminal_reducer_projection_slow\",\"reducer_revision\":%d,\"projection_elapsed_ms\":%d,\"threshold_ms\":250,\"hud_delivery_du\":\"NonBlockingObserverMailbox\",\"telemetry_delivery_du\":\"OutsideHopac\",\"authority\":\"single_reducer_projection_timing\"}"
                            state.revision
                            projectionElapsedMs)
            }

        // MIGRATION MIGRATION : the fixture is a deterministic driver over the
        // production reducer, the atomic finalization commit boundary and the shared
        // post-commit/interpreter kernels. It owns a local reducer state; it never
        // mutates terminalFlowGlobalReducerProjectionMirror or consumes live sidecar authority.
        type TerminalFlowProductionFixtureStageId =
            | TerminalFlowProductionFixtureStageFinalization
            | TerminalFlowProductionFixtureStageFairness
            | TerminalFlowProductionFixtureStageRecovery
            | TerminalFlowProductionFixtureStageOwnerWorkDag
            | TerminalFlowProductionFixtureStageApplied

        let private terminalFlowProductionFixtureStageText = function
            | TerminalFlowProductionFixtureStageFinalization -> "finalization"
            | TerminalFlowProductionFixtureStageFairness -> "fairness"
            | TerminalFlowProductionFixtureStageRecovery -> "recovery"
            | TerminalFlowProductionFixtureStageOwnerWorkDag -> "owner_workdag"
            | TerminalFlowProductionFixtureStageApplied -> "applied"

        type TerminalFlowProductionFixturePostCommitStage =
            | TerminalFlowProductionFixtureFinalizationCommitted of planRef:uint32 * transactionRef:uint32 * exactOnceRef:uint32
            | TerminalFlowProductionFixtureFairnessCompleted of planRef:uint32 * transactionRef:uint32 * exactOnceRef:uint32
            | TerminalFlowProductionFixtureRecoveryCompleted of planRef:uint32 * transactionRef:uint32 * exactOnceRef:uint32
            | TerminalFlowProductionFixtureOwnerWorkDagCompleted of planRef:uint32 * transactionRef:uint32 * exactOnceRef:uint32
            | TerminalFlowProductionFixtureAppliedCapabilityAdmitted of planRef:uint32 * transactionRef:uint32 * capabilityRef:uint32 * exactOnceRef:uint32
            | TerminalFlowProductionFixtureMissingEvidence of stage:TerminalFlowProductionFixtureStageId * evidenceRef:uint32 * count:int

        let private terminalFlowProductionFixturePostCommitStageBit = function
            | TerminalFlowProductionFixtureFinalizationCommitted _ -> 1us
            | TerminalFlowProductionFixtureFairnessCompleted _ -> 2us
            | TerminalFlowProductionFixtureRecoveryCompleted _ -> 4us
            | TerminalFlowProductionFixtureOwnerWorkDagCompleted _ -> 8us
            | TerminalFlowProductionFixtureAppliedCapabilityAdmitted _ -> 16us
            | TerminalFlowProductionFixtureMissingEvidence _ -> 0us

        let private terminalFlowProductionFixturePostCommitStageText = function
            | TerminalFlowProductionFixtureFinalizationCommitted(planRef, transactionRef, exactOnceRef) ->
                FastRuntimeFormat.format "FinalizationCommitted(plan=%u,transaction=%u,exact_once=%u)" [| box planRef; box transactionRef; box exactOnceRef |]
            | TerminalFlowProductionFixtureFairnessCompleted(planRef, transactionRef, exactOnceRef) ->
                FastRuntimeFormat.format "FairnessCompleted(plan=%u,transaction=%u,exact_once=%u)" [| box planRef; box transactionRef; box exactOnceRef |]
            | TerminalFlowProductionFixtureRecoveryCompleted(planRef, transactionRef, exactOnceRef) ->
                FastRuntimeFormat.format "RecoveryCompleted(plan=%u,transaction=%u,exact_once=%u)" [| box planRef; box transactionRef; box exactOnceRef |]
            | TerminalFlowProductionFixtureOwnerWorkDagCompleted(planRef, transactionRef, exactOnceRef) ->
                FastRuntimeFormat.format "OwnerWorkDagCompleted(plan=%u,transaction=%u,exact_once=%u)" [| box planRef; box transactionRef; box exactOnceRef |]
            | TerminalFlowProductionFixtureAppliedCapabilityAdmitted(planRef, transactionRef, capabilityRef, exactOnceRef) ->
                FastRuntimeFormat.format "AppliedCapabilityAdmitted(plan=%u,transaction=%u,capability=%u,exact_once=%u)" [| box planRef; box transactionRef; box capabilityRef; box exactOnceRef |]
            | TerminalFlowProductionFixtureMissingEvidence(stage, evidenceRef, count) ->
                FastRuntimeFormat.format "MissingEvidence(stage=%s,evidence_ref=%u,count=%d)" [| box (terminalFlowProductionFixtureStageText stage); box evidenceRef; box count |]

        type TerminalFlowProductionFixturePostCommitTraceFailure =
            | TerminalFlowProductionFixtureTraceShapeMismatch of observed:string
            | TerminalFlowProductionFixtureTracePlanMismatch of stage:TerminalFlowProductionFixtureStageId * expectedRef:uint32 * observedRef:uint32
            | TerminalFlowProductionFixtureTraceTransactionMismatch of stage:TerminalFlowProductionFixtureStageId * expectedRef:uint32 * observedRef:uint32
            | TerminalFlowProductionFixtureTracePostCommitExactOnceMismatch of stage:TerminalFlowProductionFixtureStageId * expectedRef:uint32 * observedRef:uint32
            | TerminalFlowProductionFixtureTraceCapabilityRefMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowProductionFixtureTraceCapabilityExactOnceMismatch of expectedRef:uint32 * observedRef:uint32
            | TerminalFlowProductionFixtureTraceFinalizationReceiptMissing

        let private terminalFlowProductionFixturePostCommitTraceFailureText = function
            | TerminalFlowProductionFixtureTraceShapeMismatch observed -> "shape_mismatch:" + observed
            | TerminalFlowProductionFixtureTracePlanMismatch(stage, expectedRef, observedRef) -> FastRuntimeFormat.format "plan_mismatch:%s:%u:%u" [| box (terminalFlowProductionFixtureStageText stage); box expectedRef; box observedRef |]
            | TerminalFlowProductionFixtureTraceTransactionMismatch(stage, expectedRef, observedRef) -> FastRuntimeFormat.format "transaction_mismatch:%s:%u:%u" [| box (terminalFlowProductionFixtureStageText stage); box expectedRef; box observedRef |]
            | TerminalFlowProductionFixtureTracePostCommitExactOnceMismatch(stage, expectedRef, observedRef) -> FastRuntimeFormat.format "post_commit_exact_once_mismatch:%s:%u:%u" [| box (terminalFlowProductionFixtureStageText stage); box expectedRef; box observedRef |]
            | TerminalFlowProductionFixtureTraceCapabilityRefMismatch(expectedRef, observedRef) -> sprintf "capability_ref_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowProductionFixtureTraceCapabilityExactOnceMismatch(expectedRef, observedRef) -> sprintf "capability_exact_once_mismatch:%u:%u" expectedRef observedRef
            | TerminalFlowProductionFixtureTraceFinalizationReceiptMissing -> "finalization_receipt_missing"

        let private terminalFlowProductionFixturePostCommitTraceValidate
            (expectedCapability:TerminalFlowQapPostCommitAppliedCapability)
            (stagesRev:TerminalFlowProductionFixturePostCommitStage list) =
            let chronological = List.rev stagesRev
            match chronological with
            | [ TerminalFlowProductionFixtureFinalizationCommitted(finalizationPlanRef, finalizationTransactionRef, finalizationExactOnceRef);
                TerminalFlowProductionFixtureFairnessCompleted(fairnessPlanRef, fairnessTransactionRef, fairnessExactOnceRef);
                TerminalFlowProductionFixtureRecoveryCompleted(recoveryPlanRef, recoveryTransactionRef, recoveryExactOnceRef);
                TerminalFlowProductionFixtureOwnerWorkDagCompleted(ownerPlanRef, ownerTransactionRef, ownerExactOnceRef);
                TerminalFlowProductionFixtureAppliedCapabilityAdmitted(appliedPlanRef, appliedTransactionRef, capabilityRef, capabilityExactOnceRef) ] ->
                let failures = ResizeArray<TerminalFlowProductionFixturePostCommitTraceFailure>()
                let checkPlan stage observedRef =
                    if expectedCapability.planRef <> observedRef then
                        failures.Add(TerminalFlowProductionFixtureTracePlanMismatch(stage, expectedCapability.planRef, observedRef))
                let checkTransaction stage observedRef =
                    if expectedCapability.finalizationTransactionRef <> observedRef then
                        failures.Add(TerminalFlowProductionFixtureTraceTransactionMismatch(stage, expectedCapability.finalizationTransactionRef, observedRef))
                let checkPostCommitExactOnce stage observedRef =
                    if expectedCapability.postCommitExactOnceRef <> observedRef then
                        failures.Add(TerminalFlowProductionFixtureTracePostCommitExactOnceMismatch(stage, expectedCapability.postCommitExactOnceRef, observedRef))
                checkPlan TerminalFlowProductionFixtureStageFinalization finalizationPlanRef
                checkPlan TerminalFlowProductionFixtureStageFairness fairnessPlanRef
                checkPlan TerminalFlowProductionFixtureStageRecovery recoveryPlanRef
                checkPlan TerminalFlowProductionFixtureStageOwnerWorkDag ownerPlanRef
                checkPlan TerminalFlowProductionFixtureStageApplied appliedPlanRef
                checkTransaction TerminalFlowProductionFixtureStageFinalization finalizationTransactionRef
                checkTransaction TerminalFlowProductionFixtureStageFairness fairnessTransactionRef
                checkTransaction TerminalFlowProductionFixtureStageRecovery recoveryTransactionRef
                checkTransaction TerminalFlowProductionFixtureStageOwnerWorkDag ownerTransactionRef
                checkTransaction TerminalFlowProductionFixtureStageApplied appliedTransactionRef
                checkPostCommitExactOnce TerminalFlowProductionFixtureStageFairness fairnessExactOnceRef
                checkPostCommitExactOnce TerminalFlowProductionFixtureStageRecovery recoveryExactOnceRef
                checkPostCommitExactOnce TerminalFlowProductionFixtureStageOwnerWorkDag ownerExactOnceRef
                if finalizationExactOnceRef = 0u then
                    failures.Add TerminalFlowProductionFixtureTraceFinalizationReceiptMissing
                if expectedCapability.capabilityRef <> capabilityRef then
                    failures.Add(TerminalFlowProductionFixtureTraceCapabilityRefMismatch(expectedCapability.capabilityRef, capabilityRef))
                if expectedCapability.exactOnceRef <> capabilityExactOnceRef then
                    failures.Add(TerminalFlowProductionFixtureTraceCapabilityExactOnceMismatch(expectedCapability.exactOnceRef, capabilityExactOnceRef))
                if failures.Count = 0 then Ok () else Error (List.ofSeq failures)
            | _ ->
                Error [ TerminalFlowProductionFixtureTraceShapeMismatch(
                            chronological
                            |> List.map terminalFlowProductionFixturePostCommitStageText
                            |> String.concat "->") ]

        type TerminalFlowProductionFixtureSeed = private {
            fixtureName : string
            initialEvents : TerminalFlowGlobalServerEvent list
            preparedTransaction : TerminalFlowAffineDispatchTransaction<TerminalFlowAffineDispatchPreparedStage>
            completedEnvelope : TerminalFlowBoundCommitEnvelope<TerminalFlowDoneSealedStage>
            commitObservation : TerminalFlowGlobalCommitObservation
            exitRequest : TerminalFlowGlobalExitRequest
        }

        type TerminalFlowProductionFixtureReplay = private {
            reducerState : TerminalFlowGlobalReducerState
            lastCommand : TerminalFlowGlobalServerCommand
            reducedEvents : TerminalFlowGlobalServerEvent list
            postCommitStagesRev : TerminalFlowProductionFixturePostCommitStage list
            issued : TerminalFlowAffineStageTokenIssue<TerminalFlowAffineStageTokenIssuedStage> option
            consumed : TerminalFlowAffineStageTokenFillCommit<TerminalFlowAffineStageTokenFilledStage> option
        }

        let private terminalFlowProductionFixtureGenesisRef () =
            let state = terminalFlowGlobalReducerInitialState ()
            terminalFlowMintedRefOf
                "terminal_production_fixture_genesis_ref"
                (FastRuntimeFormat.format "%d:%u:%u:%s" [| box state.revision; box state.lastEventRef; box (terminalFlowTotalOrderReceiptRef state.typedTotalOrder); box (terminalFlowReducerMutationLedgerText state.mutationLedger) |])

        let private terminalFlowProductionFixtureReduce event replay =
            let reducerEventRef =
                terminalFlowMintedRefOf
                    "terminal_production_fixture_reducer_event_ref"
                    (terminalFlowGlobalServerEventText event)
            let processingState =
                { replay.reducerState with
                    reducerQuiescence =
                        TerminalFlowReducerProcessing(
                            reducerEventRef,
                            Environment.TickCount64,
                            replay.reducerState.revision) }
            let reducedNext, proposedCommand = terminalFlowGlobalReduce processingState event
            let committedNext, committedCommand, commitReceipt =
                terminalFlowGlobalCommitPreparedQapFinalization reducedNext proposedCommand
            let replannedNext, replannedCommand =
                terminalFlowQapPostCommitReplanAwaitingEvidence committedNext committedCommand
            let next =
                { replannedNext with
                    reducerQuiescence = TerminalFlowReducerIdle replannedNext.revision }
            let gatedCommand = terminalFlowLifecycleCommandGate next replannedCommand
            let next, command =
                match gatedCommand with
                | TerminalFlowGlobalServerFailClosed(
                    TerminalFlowFailureDispatchLifecyclePoisoned(_, _, commandRef, _)) ->
                    let lifecycle =
                        terminalFlowDispatchLifecycleMarkPoisonFailClosedIssued
                            next.revision
                            commandRef
                            next.dispatchLifecycle
                    { next with dispatchLifecycle = lifecycle }, gatedCommand
                | _ -> next, gatedCommand
            let commitStages =
                match commitReceipt with
                | Some receipt ->
                    [ TerminalFlowProductionFixtureFinalizationCommitted(
                        receipt.postCommitPlanRef,
                        receipt.transactionRef,
                        receipt.exactOnceRef) ]
                | None -> []
            let fixtureMissing stage missingEvidence =
                let stageText = terminalFlowProductionFixtureStageText stage
                [ TerminalFlowProductionFixtureMissingEvidence(
                    stage,
                    terminalFlowMintedRefOf "terminal_fixture_missing_evidence_ref" (stageText + ":" + terminalFlowQapMissingEvidenceText missingEvidence),
                    (terminalFlowQapMissingEvidenceCount missingEvidence)) ]
            let completionStages =
                match event with
                | TerminalFlowGlobalServerQapPostCommitEffectCompleted completion ->
                    match completion with
                    | TerminalFlowQapPostCommitFairnessCompleted (Ok envelope) ->
                        [ TerminalFlowProductionFixtureFairnessCompleted(envelope.planRef, envelope.transaction.transactionRef, envelope.exactOnceRef) ]
                    | TerminalFlowQapPostCommitRecoveryCompleted (Ok envelope) ->
                        [ TerminalFlowProductionFixtureRecoveryCompleted(envelope.planRef, envelope.transaction.transactionRef, envelope.exactOnceRef) ]
                    | TerminalFlowQapPostCommitOwnerWorkDagCompleted (Ok envelope) ->
                        [ TerminalFlowProductionFixtureOwnerWorkDagCompleted(envelope.planRef, envelope.transaction.transactionRef, envelope.exactOnceRef) ]
                    | TerminalFlowQapPostCommitFairnessCompleted (Error missingEvidence) -> fixtureMissing TerminalFlowProductionFixtureStageFairness missingEvidence
                    | TerminalFlowQapPostCommitRecoveryCompleted (Error missingEvidence) -> fixtureMissing TerminalFlowProductionFixtureStageRecovery missingEvidence
                    | TerminalFlowQapPostCommitOwnerWorkDagCompleted (Error missingEvidence) -> fixtureMissing TerminalFlowProductionFixtureStageOwnerWorkDag missingEvidence
                | _ -> []
            let appliedStages =
                match command, terminalFlowQapPostCommitAppliedCapabilityAssessmentFor next with
                | TerminalFlowGlobalServerConsumeStageToken transaction, TerminalFlowAppliedCapabilityReady capability
                    when transaction.postCommitCapability.capabilityRef = capability.capabilityRef
                         && transaction.postCommitCapability.exactOnceRef = capability.exactOnceRef ->
                    [ TerminalFlowProductionFixtureAppliedCapabilityAdmitted(
                        capability.planRef,
                        capability.finalizationTransactionRef,
                        capability.capabilityRef,
                        capability.exactOnceRef) ]
                | _ -> []
            { replay with
                reducerState = next
                lastCommand = command
                reducedEvents = event :: replay.reducedEvents
                postCommitStagesRev = List.rev (List.concat [ commitStages; completionStages; appliedStages ]) @ replay.postCommitStagesRev }

        let rec private terminalFlowProductionFixtureDrainPostCommit fuel replay =
            match replay.lastCommand with
            | TerminalFlowGlobalServerRunQapPostCommitEffect _ when fuel <= 0 ->
                invalidOp "production fixture exceeded the bounded post-commit effect chain"
            | TerminalFlowGlobalServerRunQapPostCommitEffect effect ->
                let completion =
                    match effect with
                    | TerminalFlowQapPostCommitRunFairness envelope ->
                        TerminalFlowQapPostCommitFairnessCompleted(terminalFlowQapPostCommitFairnessComplete envelope)
                    | TerminalFlowQapPostCommitRunRecovery envelope ->
                        TerminalFlowQapPostCommitRecoveryCompleted(terminalFlowQapPostCommitRecoveryComplete envelope)
                    | TerminalFlowQapPostCommitRunOwnerWorkDag envelope ->
                        TerminalFlowQapPostCommitOwnerWorkDagCompleted(terminalFlowQapPostCommitOwnerWorkDagComplete envelope)
                let advanced =
                    terminalFlowProductionFixtureReduce
                        (TerminalFlowGlobalServerQapPostCommitEffectCompleted completion)
                        replay
                terminalFlowProductionFixtureDrainPostCommit (fuel - 1) advanced
            | _ -> replay

        let private terminalFlowProductionFixtureInterpretIssue replay =
            match replay.lastCommand with
            | TerminalFlowGlobalServerConsumeStageToken transaction ->
                match terminalFlowAppliedCapabilityAuthorizationFor replay.reducerState transaction with
                | Error failures ->
                    invalidOp
                        ("production fixture issue boundary rejected reducer command: "
                         + (failures |> List.map terminalFlowAppliedCapabilityAuthorizationFailureText |> String.concat ";"))
                | Ok () ->
                    let issued = terminalFlowAffineStageTokenIssueFor transaction
                    let advanced = terminalFlowProductionFixtureReduce (TerminalFlowGlobalServerStageTokenIssued issued) replay
                    { advanced with issued = Some issued }
            | command ->
                invalidOp ("production fixture expected reducer-owned consume command, got " + terminalFlowGlobalServerCommandText command)

        let private terminalFlowProductionFixtureInterpretConsumption envelope replay =
            match replay.issued with
            | Some issued ->
                let consumed = terminalFlowAffineStageTokenFillCommitFor issued envelope
                let advanced = terminalFlowProductionFixtureReduce (TerminalFlowGlobalServerStageTokenFillCommitted consumed) replay
                { advanced with consumed = Some consumed }
            | None -> invalidOp "production fixture attempted consumption before issue"

        let private terminalFlowProductionFixtureNegativeVerdict caseId rejected reducerRevision detail =
            { caseId = caseId
              rejected = rejected
              blockerRef = terminalFlowMintedRefOf "terminal_production_fixture_negative_blocker_ref" detail
              reducerRevision = reducerRevision }

        let private terminalFlowProductionFixtureNegativeSuite
            (preparedTransaction:TerminalFlowAffineDispatchTransaction<TerminalFlowAffineDispatchPreparedStage>)
            (seed:TerminalFlowProductionFixtureSeed)
            (preparedReplay:TerminalFlowProductionFixtureReplay)
            (consumedReplay:TerminalFlowProductionFixtureReplay)
            (exitedReplay:TerminalFlowProductionFixtureReplay) =
            let consumed =
                exitedReplay.consumed
                |> Option.defaultWith (fun () -> invalidOp "production fixture negative suite requires consumed transaction")
            let issued = consumed.issued
            let transaction = issued.transaction
            let foreignTransaction : TerminalFlowAffineDispatchTransaction<TerminalFlowAffineDispatchPreparedStage> =
                { transaction with
                    transactionDigest =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "terminal-production-fixture-foreign-transaction"
                            (CompilerIdentityKernel.ContentDigest.text transaction.transactionDigest + "|foreign") }
            let foreignIssued = terminalFlowAffineStageTokenIssueFor foreignTransaction
            let foreignReplay =
                terminalFlowProductionFixtureReduce
                    (TerminalFlowGlobalServerStageTokenIssued foreignIssued)
                    exitedReplay
            let foreignRejected =
                match (terminalFlowDispatchLifecycleConstitution foreignReplay.reducerState.dispatchLifecycle) with
                | TerminalFlowDispatchAffineFilled committed ->
                    terminalFlowAffineTransactionSameLineage committed transaction
                    && not (terminalFlowAffineTransactionSameLineage committed foreignTransaction)
                | _ -> false
            let duplicateReplay =
                terminalFlowProductionFixtureReduce
                    (TerminalFlowGlobalServerStageTokenIssued issued)
                    exitedReplay
            let duplicateIssueRejected =
                match (terminalFlowDispatchLifecycleConstitution duplicateReplay.reducerState.dispatchLifecycle),
                      duplicateReplay.lastCommand with
                | TerminalFlowDispatchAffineFilled committed,
                  TerminalFlowGlobalServerConsumeStageToken _ -> false
                | TerminalFlowDispatchAffineFilled committed, _ ->
                    terminalFlowAffineTransactionSameLineage committed transaction
                    && committed.transitionOrdinal = TerminalFlowAffineFilledOrdinal
                | _ -> false
            let stageRegressionRejected =
                match (terminalFlowDispatchLifecycleConstitution duplicateReplay.reducerState.dispatchLifecycle) with
                | TerminalFlowDispatchAffineFilled committed ->
                    committed.transitionOrdinal = TerminalFlowAffineFilledOrdinal
                    && terminalFlowAffineTransactionSameLineage committed transaction
                | _ -> false
            let projectionReplay =
                terminalFlowProductionFixtureReduce
                    (TerminalFlowGlobalServerActorProjectionObserved (DiagJson.terminalSchedulerPushActorSnapshot()))
                    exitedReplay
            let projectionAuthorityRejected =
                match (terminalFlowDispatchLifecycleConstitution projectionReplay.reducerState.dispatchLifecycle) with
                | TerminalFlowDispatchAffineFilled committed ->
                    terminalFlowAffineTransactionSameLineage committed transaction
                    && committed.transitionOrdinal = TerminalFlowAffineFilledOrdinal
                | _ -> false
            let foreignCommit : TerminalFlowGlobalCommitObservation =
                { seed.commitObservation with
                    runEndReceiptRef =
                        terminalFlowDurableRefOfText
                            (sprintf "production-fixture-foreign-run-end:%u" consumed.fillEventRef)
            }
            let foreignCommitted =
                terminalFlowProductionFixtureReduce
                    (TerminalFlowGlobalServerArtifactCommitObserved foreignCommit)
                    consumedReplay
            let foreignExited =
                terminalFlowProductionFixtureReduce
                    (TerminalFlowGlobalServerExitWitnessReady seed.exitRequest)
                    foreignCommitted
            let foreignRunEndRejected =
                match foreignExited.lastCommand with
                | TerminalFlowGlobalServerCommitExit _ -> false
                | _ -> true
            let capabilityRejected state candidate =
                match terminalFlowAppliedCapabilityAuthorizationFor state candidate with
                | Error failures ->
                    true,
                    (failures
                     |> List.map terminalFlowAppliedCapabilityAuthorizationFailureText
                     |> String.concat ";")
                | Ok () -> false, "capability_unexpectedly_authorized"
            let appliedCapability = preparedTransaction.postCommitCapability
            let foreignCapabilityTransaction =
                { preparedTransaction with
                    postCommitCapability =
                        terminalFlowQapPostCommitAppliedCapabilityMutate
                            (TerminalFlowQapCapabilityReplaceCapabilityRef(appliedCapability.capabilityRef ^^^ 0x27d4eb2du))
                            appliedCapability }
            let staleCapabilityTransaction =
                { preparedTransaction with
                    postCommitCapability =
                        terminalFlowQapPostCommitAppliedCapabilityMutate
                            (TerminalFlowQapCapabilityReplacePostCommitExactOnceRef(appliedCapability.postCommitExactOnceRef ^^^ 0x165667b1u))
                            appliedCapability }
            let pendingMismatchTransaction =
                { preparedTransaction with
                    postCommitCapability =
                        terminalFlowQapPostCommitAppliedCapabilityMutate
                            (TerminalFlowQapCapabilityReplacePendingTerminalRef(appliedCapability.pendingTerminalRef ^^^ 0xd3a2646cu))
                            appliedCapability }
            let terminalMismatchTransaction =
                { preparedTransaction with
                    postCommitCapability =
                        terminalFlowQapPostCommitAppliedCapabilityMutate
                            (TerminalFlowQapCapabilityReplaceTerminalRef(appliedCapability.terminalRef ^^^ 0xa24baed4u))
                            appliedCapability }
            let fillMismatchTransaction =
                { preparedTransaction with
                    postCommitCapability =
                        terminalFlowQapPostCommitAppliedCapabilityMutate
                            (TerminalFlowQapCapabilityReplaceFillRef(appliedCapability.fillRef ^^^ 0x9fb21c65u))
                            appliedCapability }
            let pendingPayloadMismatchTransaction =
                let pendingPayload =
                    terminalFlowPendingCandidateWithIdentityForRefs
                        appliedCapability.pending.terminalReceiptRef
                        (TerminalFlowFillKeyId.create (appliedCapability.pending.fillKey + ":foreign-payload"))
                        appliedCapability.pending
                { preparedTransaction with
                    postCommitCapability =
                        terminalFlowQapPostCommitAppliedCapabilityMutate
                            (TerminalFlowQapCapabilityReplacePendingPayload pendingPayload)
                            appliedCapability }
            let finalizationExactOnceMismatchTransaction =
                { preparedTransaction with
                    postCommitCapability =
                        terminalFlowQapPostCommitAppliedCapabilityMutate
                            (TerminalFlowQapCapabilityReplaceFinalizationExactOnceRef(appliedCapability.finalizationExactOnceRef ^^^ 0xc2b2ae35u))
                            appliedCapability }
            let admissionMismatchTransaction =
                { preparedTransaction with
                    postCommitCapability =
                        terminalFlowQapPostCommitAppliedCapabilityMutate
                            (TerminalFlowQapCapabilityReplaceAdmissionRef(appliedCapability.admissionRef ^^^ 0x85ebca6bu))
                            appliedCapability }
            let admissionIdentityMismatchTransaction =
                { preparedTransaction with
                    postCommitCapability =
                        terminalFlowQapPostCommitAppliedCapabilityMutate
                            (TerminalFlowQapCapabilityReplaceAdmissionIdentityRef(appliedCapability.admissionIdentityRef ^^^ 0x7f4a7c15u))
                            appliedCapability }
            let mixedAuthorityJoin = preparedTransaction.actorLease.actorJoin
            let mixedAuthorityIdentity =
                terminalFlowAdmissionIdentityForRefs
                    mixedAuthorityJoin.terminalReceiptRef
                    mixedAuthorityJoin.fillKey
                    ((terminalFlowActorOutcomeJoinAdmissionRef mixedAuthorityJoin) ^^^ 0x6a09e667u)
            let mixedAuthorityTransaction =
                { preparedTransaction with
                    actorLease =
                        { preparedTransaction.actorLease with
                            actorJoin = { mixedAuthorityJoin with admissionIdentity = mixedAuthorityIdentity } } }
            let foreignCapabilityRejected, foreignCapabilityDetail =
                capabilityRejected preparedReplay.reducerState foreignCapabilityTransaction
            let staleCapabilityRejected, staleCapabilityDetail =
                capabilityRejected preparedReplay.reducerState staleCapabilityTransaction
            let pendingCapabilityRejected, pendingCapabilityDetail =
                capabilityRejected preparedReplay.reducerState pendingMismatchTransaction
            let terminalCapabilityRejected, terminalCapabilityDetail =
                capabilityRejected preparedReplay.reducerState terminalMismatchTransaction
            let fillCapabilityRejected, fillCapabilityDetail =
                capabilityRejected preparedReplay.reducerState fillMismatchTransaction
            let pendingPayloadRejected, pendingPayloadDetail =
                capabilityRejected preparedReplay.reducerState pendingPayloadMismatchTransaction
            let finalizationExactOnceRejected, finalizationExactOnceDetail =
                capabilityRejected preparedReplay.reducerState finalizationExactOnceMismatchTransaction
            let admissionCapabilityRejected, admissionCapabilityDetail =
                capabilityRejected preparedReplay.reducerState admissionMismatchTransaction
            let admissionIdentityCapabilityRejected, admissionIdentityCapabilityDetail =
                capabilityRejected preparedReplay.reducerState admissionIdentityMismatchTransaction
            let mixedAuthorityRejected, mixedAuthorityDetail =
                capabilityRejected preparedReplay.reducerState mixedAuthorityTransaction
            let replayedCapabilityRejected, replayedCapabilityDetail =
                capabilityRejected exitedReplay.reducerState preparedTransaction
            [ terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureForeignLineage foreignRejected exitedReplay.reducerState.revision "foreign_lineage_reduced"
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureDuplicateIssue duplicateIssueRejected duplicateReplay.reducerState.revision "duplicate_issue_reduced"
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureStageRegression stageRegressionRejected duplicateReplay.reducerState.revision "stage_regression_reduced"
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureProjectionAuthority projectionAuthorityRejected projectionReplay.reducerState.revision "projection_authority_reduced"
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureForeignRunEnd foreignRunEndRejected foreignExited.reducerState.revision "foreign_run_end_reduced"
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureForeignCapability foreignCapabilityRejected preparedReplay.reducerState.revision foreignCapabilityDetail
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureStaleCapability staleCapabilityRejected preparedReplay.reducerState.revision staleCapabilityDetail
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureReplayedCapability replayedCapabilityRejected exitedReplay.reducerState.revision replayedCapabilityDetail
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixturePendingCapabilityMismatch pendingCapabilityRejected preparedReplay.reducerState.revision pendingCapabilityDetail
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixturePendingPayloadMismatch pendingPayloadRejected preparedReplay.reducerState.revision pendingPayloadDetail
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureTerminalCapabilityMismatch terminalCapabilityRejected preparedReplay.reducerState.revision terminalCapabilityDetail
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureFillCapabilityMismatch fillCapabilityRejected preparedReplay.reducerState.revision fillCapabilityDetail
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureFinalizationExactOnceMismatch finalizationExactOnceRejected preparedReplay.reducerState.revision finalizationExactOnceDetail
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureAdmissionCapabilityMismatch admissionCapabilityRejected preparedReplay.reducerState.revision admissionCapabilityDetail
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureAdmissionIdentityCapabilityMismatch admissionIdentityCapabilityRejected preparedReplay.reducerState.revision admissionIdentityCapabilityDetail
              terminalFlowProductionFixtureNegativeVerdict TerminalFlowProductionFixtureMixedAuthorityEnvelope mixedAuthorityRejected preparedReplay.reducerState.revision mixedAuthorityDetail ]

        let private terminalFlowProductionFixtureRun (seed:TerminalFlowProductionFixtureSeed) =
            let genesis = terminalFlowGlobalReducerInitialState ()
            let replay0 =
                { reducerState = genesis
                  lastCommand = TerminalFlowGlobalServerAwaitDataflow TerminalFlowWaitRootResolvedAwaitOutcome
                  reducedEvents = []
                  postCommitStagesRev = []
                  issued = None
                  consumed = None }
            let reduced =
                seed.initialEvents
                |> List.fold (fun replay event ->
                    let advanced = terminalFlowProductionFixtureReduce event replay
                    terminalFlowProductionFixtureDrainPostCommit 4 advanced) replay0
            let prepared, preparedTransaction =
                match reduced.lastCommand with
                | TerminalFlowGlobalServerConsumeStageToken transaction when terminalFlowAffineTransactionSameLineage transaction seed.preparedTransaction -> reduced, transaction
                | _ -> invalidOp "production fixture did not reach the reducer-owned affine consume command"
            let appliedCapability = preparedTransaction.postCommitCapability
            let postCommitTraceText =
                prepared.postCommitStagesRev
                |> List.rev
                |> List.map terminalFlowProductionFixturePostCommitStageText
                |> String.concat "->"
            let postCommitTraceRef =
                terminalFlowMintedRefOf "terminal_production_fixture_post_commit_trace_ref" postCommitTraceText
            let postCommitStageMask =
                prepared.postCommitStagesRev
                |> List.fold (fun mask stage -> mask ||| terminalFlowProductionFixturePostCommitStageBit stage) 0us
            if postCommitStageMask <> 31us then
                invalidOp
                    ("production fixture did not prove all post-commit stages; trace=" + postCommitTraceText)
            match terminalFlowProductionFixturePostCommitTraceValidate appliedCapability prepared.postCommitStagesRev with
            | Ok () -> ()
            | Error failures ->
                invalidOp
                    ("production fixture post-commit trace was not exact and ordered: "
                     + (failures |> List.map terminalFlowProductionFixturePostCommitTraceFailureText |> String.concat ";"))
            let revisionProbeState =
                { prepared.reducerState with revision = prepared.reducerState.revision + 1L }
            let capabilityRevisionStable =
                match terminalFlowQapPostCommitAppliedCapabilityAssessmentFor revisionProbeState with
                | TerminalFlowAppliedCapabilityReady observed ->
                    observed.capabilityRef = appliedCapability.capabilityRef
                    && observed.exactOnceRef = appliedCapability.exactOnceRef
                    && observed.planRef = appliedCapability.planRef
                    && observed.finalizationTransactionRef = appliedCapability.finalizationTransactionRef
                    && observed.finalizationExactOnceRef = appliedCapability.finalizationExactOnceRef
                    && observed.postCommitExactOnceRef = appliedCapability.postCommitExactOnceRef
                    && observed.pendingTerminalRef = appliedCapability.pendingTerminalRef
                    && terminalFlowPendingTerminalAuthorityPayloadSame observed.pending appliedCapability.pending
                    && observed.terminalRef = appliedCapability.terminalRef
                    && observed.fillRef = appliedCapability.fillRef
                    && observed.admissionRef = appliedCapability.admissionRef
                    && observed.admissionIdentityRef = appliedCapability.admissionIdentityRef
                | TerminalFlowAppliedCapabilityRejected _ -> false
            if not capabilityRevisionStable then
                invalidOp "production fixture capability identity changed across a projection-only reducer revision"
            let issued = terminalFlowProductionFixtureInterpretIssue prepared
            let consumed = terminalFlowProductionFixtureInterpretConsumption seed.completedEnvelope issued
            let committed = terminalFlowProductionFixtureReduce (TerminalFlowGlobalServerArtifactCommitObserved seed.commitObservation) consumed
            let exited = terminalFlowProductionFixtureReduce (TerminalFlowGlobalServerExitWitnessReady seed.exitRequest) committed
            let negatives = terminalFlowProductionFixtureNegativeSuite preparedTransaction seed prepared consumed exited
            let consumedValue = exited.consumed |> Option.defaultWith (fun () -> invalidOp "production fixture lost consumed envelope")
            let receipt = consumedValue.fillReceipt
            let authorizedExit =
                match exited.lastCommand with
                | TerminalFlowGlobalServerCommitExit authorized -> authorized
                | command ->
                    invalidOp
                        ("production fixture did not reach reducer-authorized physical exit; command="
                         + terminalFlowGlobalServerCommandText command)
            let allNegative = terminalFlowProductionFixtureNegativeSuiteComplete negatives
            if not allNegative then invalidOp "production fixture negative suite admitted an illegal transition"
            { certificateRef = terminalFlowMintedRefOf "terminal_production_fixture_certificate_ref" (FastRuntimeFormat.format "%s:%u:%u:%u" [| box seed.fixtureName; box receipt.receiptRef; box authorizedExit.authority.runEndReceiptRef; box authorizedExit.reducerPhysicalExitReceiptRef |])
              fixtureRef = terminalFlowMintedRefOf "terminal_production_fixture_ref" seed.fixtureName
              reducerGenesisRef = terminalFlowProductionFixtureGenesisRef ()
              reducerPathRef = terminalFlowMintedRefOf "terminal_production_fixture_reducer_path_ref" (exited.reducedEvents |> List.rev |> List.map terminalFlowGlobalServerEventText |> String.concat "->")
              interpreterKernelRef = terminalFlowMintedRefOf "terminal_production_fixture_interpreter_kernel_ref" (sprintf "%u:%u" consumedValue.issued.issueEventRef consumedValue.fillEventRef)
              postCommitPlanRef = appliedCapability.planRef
              postCommitTransactionRef = appliedCapability.finalizationTransactionRef
              appliedCapabilityRef = appliedCapability.capabilityRef
              appliedCapabilityExactOnceRef = appliedCapability.exactOnceRef
              capabilityRevisionStable = capabilityRevisionStable
              postCommitStageMask = postCommitStageMask
              postCommitTraceRef = postCommitTraceRef
              transactionRef = consumedValue.issued.transaction.transactionRef
              issuanceRef = consumedValue.issued.transaction.authorization.issuance.issuanceRef
              issueEventRef = consumedValue.issued.issueEventRef
              consumptionEventRef = consumedValue.fillEventRef
              runEndReceiptRef = authorizedExit.authority.runEndReceiptRef
              physicalExitReceiptRef = authorizedExit.reducerPhysicalExitReceiptRef
              exactOnceRef = terminalFlowMintedRefOf "terminal_production_fixture_exact_once_ref" (FastRuntimeFormat.format "%u:%u:%u:%u" [| box consumedValue.issued.exactOnceRef; box consumedValue.exactOnceRef; box receipt.exactOnceRef; box authorizedExit.reducerPhysicalExitReceiptRef |])
              finalRevision = exited.reducerState.revision
              negativeVerdicts = negatives }

        // Migration round : the production fixture seed is captured from the
        // serialized live reducer path.  No public constructor and no parallel
        // synthetic model can mint these values.  The callback observes reducer
        // results only; it never changes reducer authority or command selection.
        type TerminalFlowProductionFixtureCapture = private {
            rootEvidenceRef : uint32 option
            preparationEventsRev : TerminalFlowGlobalServerEvent list
            preparedTransaction : TerminalFlowAffineDispatchTransaction<TerminalFlowAffineDispatchPreparedStage> option
            completedEnvelope : TerminalFlowBoundCommitEnvelope<TerminalFlowDoneSealedStage> option
            commitObservation : TerminalFlowGlobalCommitObservation option
            exitRequest : TerminalFlowGlobalExitRequest option
            publishedCertificateRef : uint32 option
        }

        let mutable private terminalFlowProductionFixtureCapture = {
            rootEvidenceRef = None
            preparationEventsRev = []
            preparedTransaction = None
            completedEnvelope = None
            commitObservation = None
            exitRequest = None
            publishedCertificateRef = None
        }

        let private terminalFlowProductionFixtureCaptureObserve event reducerState command =
            let current =
                match event with
                | TerminalFlowGlobalServerEvaluatorRootResolved(_, _, evidenceRef, true)
                    when terminalFlowProductionFixtureCapture.rootEvidenceRef <> Some evidenceRef ->
                    { rootEvidenceRef = Some evidenceRef
                      preparationEventsRev = []
                      preparedTransaction = None
                      completedEnvelope = None
                      commitObservation = None
                      exitRequest = None
                      publishedCertificateRef = None }
                | _ -> terminalFlowProductionFixtureCapture
            let preparationEventsRev =
                match current.preparedTransaction, event with
                | None, TerminalFlowGlobalServerQapPostCommitEffectCompleted _ ->
                    // Generated completions are replayed through the shared effect kernels.
                    current.preparationEventsRev
                | None, _ -> event :: current.preparationEventsRev
                | Some _, _ -> current.preparationEventsRev
            let preparedTransaction =
                match current.preparedTransaction, command with
                | None, TerminalFlowGlobalServerConsumeStageToken transaction -> Some transaction
                | existing, _ -> existing
            let completedEnvelope =
                match event with
                | TerminalFlowGlobalServerStageTokenFillCommitted consumed -> Some consumed.completedEnvelope
                | _ -> current.completedEnvelope
            let commitObservation =
                match event with
                | TerminalFlowGlobalServerArtifactCommitObserved commit -> Some commit
                | _ -> current.commitObservation
            let exitRequest =
                match event with
                | TerminalFlowGlobalServerExitWitnessReady request -> Some request
                | _ -> current.exitRequest
            let next = {
                rootEvidenceRef = current.rootEvidenceRef
                preparationEventsRev = preparationEventsRev
                preparedTransaction = preparedTransaction
                completedEnvelope = completedEnvelope
                commitObservation = commitObservation
                exitRequest = exitRequest
                publishedCertificateRef = current.publishedCertificateRef
            }
            terminalFlowProductionFixtureCapture <- next
            match next.preparedTransaction,
                  next.completedEnvelope,
                  next.commitObservation,
                  next.exitRequest,
                  next.publishedCertificateRef with
            | Some transaction, Some envelope, Some commit, Some exitRequest, None ->
                let seed = {
                    fixtureName = sprintf "live-production-affine:%u:%u" transaction.transactionRef reducerState.lastEventRef
                    initialEvents = List.rev next.preparationEventsRev
                    preparedTransaction = transaction
                    completedEnvelope = envelope
                    commitObservation = commit
                    exitRequest = exitRequest
                }
                try
                    let certificate = terminalFlowProductionFixtureRun seed
                    terminalFlowProductionFixtureCapture <- {
                        next with publishedCertificateRef = Some certificate.certificateRef
                    }
                    terminalFlowProductionFixtureCertificateAuthority <- Some certificate
                    let compileRescue = terminalFlowCompileRescueManifestCurrent ()
                    let satisfiedGateCount =
                        compileRescue.gates
                        |> List.sumBy (fun (_, authority) ->
                            match authority with
                            | TerminalFlowCompileRescueSatisfiedByModuleLoad _
                            | TerminalFlowCompileRescueSatisfiedByFixture _ -> 1
                            | _ -> 0)
                    let pendingGateCount =
                        compileRescue.gates
                        |> List.sumBy (fun (_, authority) ->
                            match authority with
                            | TerminalFlowCompileRescuePendingExternalAudit _ -> 1
                            | _ -> 0)
                    let blockedGateCount = compileRescue.gates.Length - satisfiedGateCount - pendingGateCount
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_compile_rescue_fixture_gate_rollup\",\"certificate_ref\":%u,\"satisfied_gate_count\":%d,\"pending_gate_count\":%d,\"blocked_gate_count\":%d,\"runtime_authorization\":false,\"authority\":\"fixture_gate_only\"}" [| box certificate.certificateRef; box satisfiedGateCount; box pendingGateCount; box blockedGateCount |])
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_production_fixture_live_seed_proven\",\"certificate_ref\":%u,\"post_commit_plan_ref\":%u,\"post_commit_transaction_ref\":%u,\"applied_capability_ref\":%u,\"applied_capability_exact_once_ref\":%u,\"capability_revision_stable\":%b,\"post_commit_stage_mask\":%d,\"post_commit_trace_ref\":%u,\"negative_case_count\":%d,\"transaction_ref\":%u,\"run_end_receipt_ref\":%u,\"physical_exit_receipt_ref\":%u,\"reducer_revision\":%d,\"authority\":\"fixture_gate_only\",\"runtime_authorization\":false}" [| box certificate.certificateRef; box certificate.postCommitPlanRef; box certificate.postCommitTransactionRef; box certificate.appliedCapabilityRef; box certificate.appliedCapabilityExactOnceRef; box certificate.capabilityRevisionStable; box (int certificate.postCommitStageMask); box certificate.postCommitTraceRef; box certificate.negativeVerdicts.Length; box certificate.transactionRef; box certificate.runEndReceiptRef; box certificate.physicalExitReceiptRef; box reducerState.revision |])
                    terminalFlowEmitAdvancedConsoleProjection {
                        lane = TerminalFlowConsoleLaneExitSeal
                        sequence = reducerState.revision
                        progressBp = 9999
                        etaMs = Some 0L
                        title = "production post-QAP fixture proven"
                        detail = FastRuntimeFormat.format "plan=%u|transaction=%u|capability=%u|revision_stable=%b|stage_mask=%d|trace_ref=%u|negative_cases=%d" [| box certificate.postCommitPlanRef; box certificate.postCommitTransactionRef; box certificate.appliedCapabilityRef; box certificate.capabilityRevisionStable; box (int certificate.postCommitStageMask); box certificate.postCommitTraceRef; box certificate.negativeVerdicts.Length |]
                        authorityRef = certificate.certificateRef
                    }
                    terminalFlowGlobalServerPublish
                        (TerminalFlowGlobalServerAdmissionRunEndFixtureProven certificate)
                with ex ->
                    let failureRef =
                        terminalFlowMintedRefOf
                            "terminal_production_fixture_live_seed_failure_ref"
                            (FastRuntimeFormat.format "%u:%d:%s" [| box transaction.transactionRef; box reducerState.revision; box ex.Message |])
                    terminalFlowProductionFixtureCapture <- {
                        next with publishedCertificateRef = Some failureRef
                    }
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_production_fixture_live_seed_rejected\",\"failure_ref\":%u,\"transaction_ref\":%u,\"reducer_revision\":%d,\"blocker\":%s,\"authority\":\"fixture_gate_only\",\"runtime_authorization\":false}" [| box failureRef; box transaction.transactionRef; box reducerState.revision; box (DiagJson.esc ex.Message) |])
            | _ -> ()

        let private terminalFlowInstallProductionAudit () =
            terminalFlowProductionAuditInstall terminalFlowProductionFixtureCaptureObserve

        type TerminalFlowProductionFixtureVectorContract = private {
            name : string
            requiredReducerEvents : string list
            requiredInterpreterStages : string list
            negativeCases : TerminalFlowProductionFixtureNegativeCase list
        }

        let private terminalFlowProductionFixtureVectorContracts =
            [ { name = "production_post_qap_applied_to_physical_exit"
                requiredReducerEvents =
                    [ "EvaluatorRootResolved"
                      "TerminalOutcomeReady"
                      "QapFinalizationCommitted"
                      "QapPostCommitFairnessCompleted"
                      "QapPostCommitRecoveryCompleted"
                      "QapPostCommitOwnerWorkDagCompleted"
                      "AppliedCapabilityAdmitted"
                      "DispatchRequested"
                      "DispatchExecuted"
                      "StageTokenIssued"
                      "StageTokenConsumed"
                      "ArtifactCommitObserved"
                      "ExitWitnessReady" ]
                requiredInterpreterStages =
                    [ "RunQapPostCommitFairness"
                      "RunQapPostCommitRecovery"
                      "RunQapPostCommitOwnerWorkDag"
                      "ConsumeStageToken"
                      "terminalFlowAffineStageTokenIssueFor"
                      "terminalFlowAffineStageTokenFillCommitFor" ]
                negativeCases =
                    [ TerminalFlowProductionFixtureForeignLineage
                      TerminalFlowProductionFixtureDuplicateIssue
                      TerminalFlowProductionFixtureStageRegression
                      TerminalFlowProductionFixtureProjectionAuthority
                      TerminalFlowProductionFixtureForeignRunEnd
                      TerminalFlowProductionFixtureForeignCapability
                      TerminalFlowProductionFixtureStaleCapability
                      TerminalFlowProductionFixtureReplayedCapability
                      TerminalFlowProductionFixturePendingCapabilityMismatch
                      TerminalFlowProductionFixturePendingPayloadMismatch
                      TerminalFlowProductionFixtureTerminalCapabilityMismatch
                      TerminalFlowProductionFixtureFillCapabilityMismatch
                      TerminalFlowProductionFixtureFinalizationExactOnceMismatch
                      TerminalFlowProductionFixtureAdmissionCapabilityMismatch
                      TerminalFlowProductionFixtureAdmissionIdentityCapabilityMismatch
                      TerminalFlowProductionFixtureMixedAuthorityEnvelope ] } ]

        let private terminalFlowReducerStageTokenIssueCommitted
            (issued:TerminalFlowAffineStageTokenIssue<TerminalFlowAffineStageTokenIssuedStage>) =
            let receipt = issued.issueReceipt
            let transaction = issued.transaction
            let authorization = transaction.authorization
            lock terminalFlowGlobalReducerProjectionGate (fun () ->
                match (terminalFlowDispatchLifecycleFrame terminalFlowGlobalReducerProjectionMirror.dispatchLifecycle).reducerPossession,
                      (terminalFlowDispatchLifecycleConstitution terminalFlowGlobalReducerProjectionMirror.dispatchLifecycle) with
                | TerminalFlowReducerActorArmed (TerminalFlowPossession actor), TerminalFlowDispatchAffineIssued committed ->
                    terminalFlowAffineTransactionSameLineage committed transaction
                    && committed.transitionOrdinal = TerminalFlowAffineIssuedOrdinal
                    && issued.issueEventRef <> 0u
                    && issued.exactOnceRef <> 0u
                    && receipt.dispatchIssuanceRef = authorization.issuance.issuanceRef
                    && receipt.credentialBundleRef = authorization.issuance.credentials.bundleRef
                    && receipt.consumeAuthorityRef = authorization.consumeAuthorityRef
                    && receipt.constitutionRef <> 0u
                    && terminalFlowAuthorityRefValue actor.lineage.actorRef = (terminalFlowActorOutcomeJoinActorRef transaction.actorLease.actorJoin)
                    && terminalFlowAuthorityRefValue actor.lineage.actorRef = receipt.actorRef
                    && terminalFlowAuthorityRefValue actor.lineage.terminalRef = receipt.terminalRef
                    && terminalFlowAuthorityRefValue actor.lineage.fillRef = receipt.fillRef
                    && terminalFlowAuthorityRefValue actor.lineage.admissionRef = transaction.postCommitCapability.admissionRef
                    && terminalFlowAuthorityRefValue actor.lineage.admissionRef = receipt.admissionRef
                    && terminalFlowAuthorityRefValue actor.lineage.admissionIdentityRef = (terminalFlowActorOutcomeJoinAdmissionIdentityRef transaction.actorLease.actorJoin)
                    && terminalFlowAuthorityRefValue actor.lineage.admissionIdentityRef = receipt.admissionIdentityRef
                    && terminalFlowAuthorityRefValue actor.lineage.actorBindingRef = (terminalFlowActorOutcomeJoinActorBindingRef transaction.actorLease.actorJoin)
                    && terminalFlowAuthorityRefValue actor.lineage.schedulerReleaseRef = receipt.schedulerReleaseRef
                    && terminalFlowAuthorityRefValue actor.issued.tokenRef = receipt.tokenRef
                    && terminalFlowAuthorityRefValue actor.issued.issueReceiptRef = receipt.receiptRef
                    && terminalFlowAuthorityRefValue actor.lineage.exactOnceRef = receipt.exactOnceRef
                | _ -> false)

        let private terminalFlowReducerStageTokenFillCommitted
            (filledEvent:TerminalFlowAffineStageTokenFillCommit<TerminalFlowAffineStageTokenFilledStage>) =
            let receipt = filledEvent.fillReceipt
            let issued = filledEvent.issued
            let transaction = issued.transaction
            let authorization = transaction.authorization
            lock terminalFlowGlobalReducerProjectionGate (fun () ->
                match (terminalFlowDispatchLifecycleFrame terminalFlowGlobalReducerProjectionMirror.dispatchLifecycle).reducerPossession,
                      (terminalFlowDispatchLifecycleConstitution terminalFlowGlobalReducerProjectionMirror.dispatchLifecycle) with
                | TerminalFlowReducerActorFilled (TerminalFlowPossession actor), TerminalFlowDispatchAffineFilled committed ->
                    let lineage = actor.ratifiedLineage.issuedLineage
                    terminalFlowAffineTransactionSameLineage committed transaction
                    && committed.transitionOrdinal = TerminalFlowAffineFilledOrdinal
                    && filledEvent.fillEventRef <> 0u
                    && filledEvent.exactOnceRef <> 0u
                    && receipt.dispatchIssuanceRef = authorization.issuance.issuanceRef
                    && receipt.credentialBundleRef = authorization.issuance.credentials.bundleRef
                    && receipt.consumeAuthorityRef = authorization.consumeAuthorityRef
                    && receipt.constitutionRef <> 0u
                    && receipt.ratificationRef <> 0u
                    && receipt.pushActorOwnerRef <> 0u
                    && receipt.fillCommandRef <> 0u
                    && terminalFlowAuthorityRefValue actor.ratifiedLineage.ratificationRef = receipt.ratificationRef
                    && terminalFlowAuthorityRefValue actor.fillAuthority.ownership.ownerRef = receipt.pushActorOwnerRef
                    && terminalFlowAuthorityRefValue actor.fillAuthority.commandRef = receipt.fillCommandRef
                    && terminalFlowAuthorityRefValue actor.fillAuthority.consumeReceiptRef = receipt.receiptRef
                    && terminalFlowAuthorityRefValue actor.fillAuthority.fillReceiptRef = receipt.fillReceiptRef
                    && terminalFlowAuthorityRefValue lineage.actorRef = (terminalFlowActorOutcomeJoinActorRef transaction.actorLease.actorJoin)
                    && terminalFlowAuthorityRefValue lineage.actorRef = receipt.actorRef
                    && terminalFlowAuthorityRefValue lineage.terminalRef = receipt.terminalRef
                    && terminalFlowAuthorityRefValue lineage.fillRef = receipt.fillRef
                    && terminalFlowAuthorityRefValue lineage.admissionRef = transaction.postCommitCapability.admissionRef
                    && terminalFlowAuthorityRefValue lineage.admissionRef = receipt.admissionRef
                    && terminalFlowAuthorityRefValue lineage.admissionIdentityRef = (terminalFlowActorOutcomeJoinAdmissionIdentityRef transaction.actorLease.actorJoin)
                    && terminalFlowAuthorityRefValue lineage.admissionIdentityRef = receipt.admissionIdentityRef
                    && terminalFlowAuthorityRefValue lineage.schedulerReleaseRef = receipt.schedulerReleaseRef
                    && terminalFlowAuthorityRefValue actor.armed.issued.tokenRef = receipt.tokenRef
                    && terminalFlowAuthorityRefValue actor.armed.issued.issueReceiptRef = receipt.issueReceiptRef
                    && terminalFlowAuthorityRefValue lineage.exactOnceRef = receipt.exactOnceRef
                | _ -> false)

        let private terminalFlowReducerStageTokenSealAuthorized
            (authorized:TerminalFlowAffineStageTokenSealAuthorization<TerminalFlowAffineStageTokenSealAuthorizedStage>) =
            let receipt = authorized.authorizationReceipt
            let filledEvent = authorized.filled
            let transaction = filledEvent.issued.transaction
            lock terminalFlowGlobalReducerProjectionGate (fun () ->
                match (terminalFlowDispatchLifecycleFrame terminalFlowGlobalReducerProjectionMirror.dispatchLifecycle).reducerPossession,
                      (terminalFlowDispatchLifecycleConstitution terminalFlowGlobalReducerProjectionMirror.dispatchLifecycle),
                      terminalFlowGlobalReducerProjectionMirror.reducerTerminalSeal with
                | TerminalFlowReducerActorSealed (TerminalFlowPossession actor),
                  TerminalFlowDispatchAffineSealAuthorized committed,
                  TerminalFlowReducerTerminalSealPhysicalExitSelected chain ->
                    terminalFlowAffineTransactionSameLineage committed transaction
                    && committed.transitionOrdinal = TerminalFlowAffineSealAuthorizedOrdinal
                    && authorized.authorizationEventRef <> 0u
                    && authorized.exactOnceRef <> 0u
                    && receipt.receiptRef <> 0u
                    && receipt.sealCommandRef <> 0u
                    && terminalFlowAuthorityRefValue actor.filled.fillAuthority.consumeReceiptRef = receipt.fillCommitReceiptRef
                    && terminalFlowAuthorityRefValue actor.filled.armed.issued.tokenRef = receipt.tokenRef
                    && terminalFlowAuthorityRefValue actor.filled.ratifiedLineage.ratificationRef = receipt.ratificationRef
                    && terminalFlowAuthorityRefValue actor.runEndReceiptRef = chain.runEnd.receiptRef
                    && terminalFlowAuthorityRefValue actor.physicalExitAuthorityRef = chain.physicalExit.receiptRef
                    && chain.commit.predecessorReceiptRef = receipt.receiptRef
                    && terminalFlowReducerProcessExitAllowed chain
                | _ -> false)

        let private terminalFlowReducerAffineDispatchTransactionCommitted
            (transaction:TerminalFlowAffineDispatchTransaction<TerminalFlowAffineDispatchPreparedStage>) =
            let decision, reducerRevision =
                lock terminalFlowGlobalReducerProjectionGate (fun () ->
                    terminalFlowAppliedCapabilityAuthorizationFor terminalFlowGlobalReducerProjectionMirror transaction,
                    terminalFlowGlobalReducerProjectionMirror.revision)
            match decision with
            | Ok () -> true
            | Error failures ->
                let detail =
                    failures
                    |> List.map terminalFlowAppliedCapabilityAuthorizationFailureText
                    |> String.concat ";"
                let rejectionRef =
                    terminalFlowMintedRefOf
