                        do! emitDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_writer_envelope_committed\",\"writer_job_ref\":%u,\"artifact_receipt_ref\":%u,\"exit_witness_ref\":%u,\"run_end_receipt_ref\":%u,\"stage_du\":\"WriterCommitted\",\"authority\":\"linear_terminal_covenant_journal\",\"next\":\"seal_authorization\"}" [| box envelope.committed.writerJobRef; box envelope.committed.artifactReceiptRef; box envelope.committed.exitWitnessRef; box envelope.doneTransition.runEndReceiptRef |])
