                        let requestId = "terminal-global-inline-failclosed-exit:" + pending.fillKey
                        let line =
                            FastRuntimeFormat.format "{\"kind\":\"terminal_flow_global_arm_failclosed_exit_witness\",\"request_ref\":%u,\"fill_ref\":%u,\"reason_ref\":%u,\"decision_authority\":\"arm_dispatch_inline_typed_failure_chain\"}" [| box (terminalFlowMintedRefOf "request_ref" requestId); box (terminalFlowPendingFillDigest pending); box (terminalFlowMintedRefOf "reason_ref" reasonText) |]
