                        let failureRatificationRef = terminalFlowMintedRefOf "terminal_dispatch_failclosed_ratification_ref" (FastRuntimeFormat.format "%u:%u:%u" [| box terminalRef; box fillRef; box constitution.constitutionRef |])
                        let failureExactOnceRef = terminalFlowMintedRefOf "terminal_stage_token_failure_exact_once_ref" (FastRuntimeFormat.format "%u:%u:%u:%u:%u" [| box terminalRef; box fillRef; box failureRef; box constitution.constitutionRef; box failureRatificationRef |])
