                        let! _ =
                            DiagJson.emitTerminalJsonDurableJob (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_flow_deadman_fail_closed_revalidated\",\"disposition_du\":\"Authorized\",\"authorization_reason_du\":%s,\"suppression_reason_du\":\"None\",\"requested_material_age_ms\":%d,\"outstanding_graph_grace_ms\":%d,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"promise_pending_depth\":%d,\"worklist_registered_depth\":%d,\"worklist_running_depth\":%d,\"qap_watch_present\":%b,\"durable_run_end_committed\":%b,\"failure_cutover\":true,\"authority\":\"reducer_live_topology_plus_bounded_outstanding_graph_revalidation\",\"next\":\"mint_typed_failure_total_order\"}" [| box (DiagJson.esc (terminalFlowDeadmanAuthorizationReasonText authorizationReason)); box snapshot.requestedMaterialAgeMs; box terminalFlowDeadmanOutstandingGraphGraceMs; box snapshot.pendingDepth; box snapshot.queueDepth; box snapshot.activeDepth; box snapshot.promisePendingDepth; box snapshot.worklistRegisteredDepth; box snapshot.worklistRunningDepth; box snapshot.qapWatchPresent; box snapshot.durableRunEndCommitted |])
