                    | _ ->
                        let failureExitCode =
                            match failure with
                            | TerminalFlowFailureTypedTerminalExitRequested(requestedExitCode, _, _) -> requestedExitCode
                            | _ -> 227
                        let semanticIdentity =
                            terminalFlowGlobalFailureTerminalSemanticIdentity
                                commandState
                                failure
                        let line =
                            FastRuntimeFormat.format "{\"kind\":\"terminal_flow_global_server_fail_closed\",\"exit_code\":%d,\"root_receipt_ref\":%u,\"actor_phase\":%s,\"actor_age_ms\":%d,\"failure\":%s,\"terminal_identity_source_du\":%s,\"terminal_ref\":%u,\"fill_ref\":%u,\"decision_authority\":\"typed_global_failure\",\"physical_exit\":false,\"next\":\"publish_typed_failure_exit_witness\"}" [| box failureExitCode; box (terminalFlowRootReceiptRefText root.receiptId); box (DiagJson.esc (DiagJson.terminalSchedulerPushActorPhaseText actor.phase)); box (max 0L (Environment.TickCount64 - actor.changedAtMs)); box (DiagJson.esc reason); box (DiagJson.esc (terminalFlowFailureSemanticIdentitySourceText semanticIdentity.source)); box semanticIdentity.terminalRef; box semanticIdentity.fillRef |]
                        DiagJson.emitTerminalJsonDurable line
                        let failureRef = terminalFlowDurableRefOfText ("global_failure|" + reason)
                        let requestId = "terminal-global-failure:" + string (terminalFlowDurableRefValue failureRef)
                        let physicalChain =
                            TerminalFlowPhysicalExitTypedFailure(
                                failureRef,
                                terminalFlowDurableRefOfText ("global-failure-exit-witness:" + requestId))
                        let exitRequest =
                            terminalFlowGlobalExitRequestCreate
                                requestId
                                failureFillKey
                                failureExitCode
                                DiagJson.PushActorFailedClosed
                                line
                                physicalChain
                                (terminalFlowTypedFailureOriginOfChain physicalChain)
                        let typedFailureCutover =
                            terminalFlowTypedFailureOrderCutover
                                (terminalFlowPhysicalExitChainFailureRef exitRequest.physicalChain)
                                semanticIdentity.terminalRef
                                semanticIdentity.fillRef
                                exitRequest.requestId
                                exitRequest.exitCode
                        // MIGRATION: latch the typed failure boundary before the
                        // reducer emits its constitutional total-order chain. This
                        // prevents run_end from inheriting the pre-cutover progress
                        // and terminal-failure projection observed in MIGRATION.
                        terminalFlowRememberIndexedClosureExitRequest exitRequest |> ignore
                        DiagJson.terminalFailureExitMarkCommitted exitRequest.exitCode
                        do! executeInternalEvent (TerminalFlowGlobalServerTerminalOrderCutoverObserved typedFailureCutover)
                        do! executeInternalEvent (TerminalFlowGlobalServerExitWitnessReady exitRequest)
                // A durable indexed closure may have been completed by the reducer-owned
                // retry that follows the previous command. Its control-lane wake is useful
                // for liveness, but re-entering the mailbox is not a proof obligation.
                // Consume one retained request inline on this reducer turn. Removal happens
                // before reduction; a control wake that won the race therefore leaves no
                // inline request, while an inline winner remains protected by the existing
                // total-order / physical-exit exact-once keys.
                match terminalFlowTryTakeIndexedClosureInlineExitReplay () with
                | Some (physicalExitReceiptRef, exitRequest) ->
                    let! _ =
                        DiagJson.emitTerminalJsonDurableJob (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_indexed_closure_exit_replay_consumed_inline\",\"request_ref\":%u,\"physical_exit_receipt_ref\":%u,\"exit_code\":%d,\"owner\":\"single_reducer_interpreter\",\"channel_roundtrip\":false,\"exact_once_replay_key_reserved\":true,\"authority\":\"durable_indexed_closure_reducer_inline_reauthorization\",\"next\":\"reduce_exit_witness_then_commit_physical_boundary\"}" [| box exitRequest.requestRef; box physicalExitReceiptRef; box exitRequest.exitCode |])
                    do! executeInternalEvent (TerminalFlowGlobalServerExitWitnessReady exitRequest)
                | None -> ()
                let executedSeq = terminalFlowGlobalServerCounterAdvance TerminalFlowGlobalServerCounterExecuted
                let commandText = terminalFlowGlobalServerCommandText command
                let commandOccurrence, emitCommand =
                    DiagJson.sparseLogDecision ("command_completed|" + commandText) 256L
                if emitCommand
                   && not (DiagJson.terminalQapProvenDeadlockNow())
                   && not (DiagJson.terminalFailureExitRequestedNow())
                   && not (DiagJson.nativePromiseFailureClosedNow()) then
                    let mutationLedgerText =
                        lock terminalFlowGlobalReducerProjectionGate (fun () -> terminalFlowReducerMutationLedgerText terminalFlowGlobalReducerProjectionMirror.mutationLedger)
                    let authorityCutoverText =
                        lock terminalFlowGlobalReducerProjectionGate (fun () -> terminalFlowAuthorityCutoverText terminalFlowGlobalReducerProjectionMirror.authorityCutover)
                    DiagJson.emitOutsideHopac (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_flow_global_command_completed\",\"command_ref\":%u,\"command\":%s,\"executed_seq\":%d,\"consumed_seq_snapshot\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"first3_power2_every256_per_command\",\"owner\":\"single_reducer_interpreter\",\"mutation_ledger\":%s,\"authority_cutover\":%s,\"legacy_mirror_authority\":false,\"deadman_terminal_authority\":false,\"string_decision_authority\":false,\"interlocked_quarantine_active\":false,\"polling_authority\":false}" [| box (terminalFlowGlobalServerCommandRef command); box (DiagJson.esc commandText); box executedSeq; box ((terminalFlowGlobalServerCounterSnapshot()).consumed); box commandOccurrence; box (DiagJson.esc mutationLedgerText); box (DiagJson.esc authorityCutoverText) |])
                return commandState
            }

        let private terminalFlowGlobalExitCodeFromState (state:TerminalFlowGlobalReducerState) =
            match state.reducerTerminalSeal with
            | TerminalFlowReducerTerminalSealAwaitStageToken -> None
            | TerminalFlowReducerTerminalSealPhysicalExitSelected chain
            | TerminalFlowReducerTerminalSealFailClosedSelected chain ->
                if terminalFlowReducerProcessExitAllowed chain then Some chain.exitCode else None

        let rec private terminalFlowGlobalServerLoop
            (state:TerminalFlowGlobalReducerState)
            : Hopac.Job<unit> =
            job {
                let! message =
                    CompilerKernelV2.CompilerRuntimeKernel.chooseTake
                        "terminal-flow-global-control-before-data"
                        terminalFlowGlobalServerControlChannel
                        terminalFlowGlobalServerChannel
                    |> CompilerKernelV2.CompilerRuntimeKernel.toJob
                match message with
                | TerminalFlowReducerActorRead reply ->
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                            reply
                            state
                    return! Hopac.Job.delay (fun () -> terminalFlowGlobalServerLoop state)
                | TerminalFlowReducerActorExecuteCommand(command, reply) ->
                    let! finalState = terminalFlowGlobalExecuteCommand state command
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                            reply
                            finalState
                    return! Hopac.Job.delay (fun () -> terminalFlowGlobalServerLoop finalState)
                | TerminalFlowReducerActorReconcileHostReturn(request, reply) ->
                    let event = TerminalFlowGlobalServerHostShutdownRequested request
                    let ((next, command), journalRequests), durableLines =
                        try
                            CompilerConsoleHud88.withDurableJsonHopacJobContext (fun () ->
                                DiagJson.withTerminalFlowKernelJournalJobContext (fun () ->
                                    terminalFlowGlobalReduceOwned state event))
                        with ex ->
                            CompilerConsoleHud88.emitImmediateFailureEvent
                                "terminal_flow_reducer_unhandled_exception"
                                "terminalFlowGlobalServerLoop"
                                (terminalFlowGlobalServerEventKind event + "|" + terminalFlowGlobalServerEventText event)
                                (ex.GetType().FullName)
                                "capture_bounded_reducer_boundary_then_rethrow"
                            CompilerConsoleHud88.captureReducerBoundaryException "terminal_flow_global_reduce_owned" ex
                            reraise()
                    do! DiagJson.terminalFlowKernelJournalSubmitCapturedJob journalRequests
                    do! CompilerConsoleHud88.submitProgressJsonLinesTerminalDurableJob durableLines
                    do! Hopac.Job.start (terminalFlowGlobalReducerPublishHudSnapshot next)
                    let _, serverDurableLines =
                        CompilerConsoleHud88.withDurableJsonHopacJobContext (fun () ->
                            terminalFlowGlobalServerEmit next event command "typed_host_return_reconciliation_actor_owned")
                    do! CompilerConsoleHud88.submitProgressJsonLinesTerminalDurableJob serverDurableLines
                    let! finalState = terminalFlowGlobalExecuteCommand next command
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                            reply
                            (terminalFlowGlobalExitCodeFromState finalState)
                    return! Hopac.Job.delay (fun () -> terminalFlowGlobalServerLoop finalState)
                | TerminalFlowReducerActorApply event ->
                    terminalFlowGlobalServerLastEventAtMs <- Environment.TickCount64
                    let consumedSeq = terminalFlowGlobalServerCounterAdvance TerminalFlowGlobalServerCounterConsumed
                    let eventText = terminalFlowGlobalServerEventText event
                    let eventKind = terminalFlowGlobalServerEventKind event
                    let eventPriority = terminalFlowGlobalServerEventPriorityFor event
                    let eventChannelText =
                        match eventPriority with
                        | TerminalFlowGlobalEventTerminalPriority -> "terminal_flow_global_control"
                        | TerminalFlowGlobalEventOrdinaryPriority -> "terminal_flow_global_data"
                    let occurrence, shouldEmit = DiagJson.sparseLogDecision ("taken|" + eventKind) 128L
                    if shouldEmit then
                        DiagJson.emitOutsideHopac (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_flow_global_event_taken\",\"event_kind_du\":%s,\"event_ref\":%u,\"event\":%s,\"consume_seq\":%d,\"published_seq_snapshot\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"first3_power2_every128\",\"priority_du\":%s,\"channel\":%s,\"owner\":\"single_reducer_actor\",\"polling_authority\":false}" [| box (DiagJson.esc eventKind); box (terminalFlowMintedRefOf "global_server_event_ref" eventText); box (DiagJson.esc eventText); box consumedSeq; box ((terminalFlowGlobalServerCounterSnapshot()).published); box occurrence; box (DiagJson.esc (terminalFlowGlobalServerEventPriorityText eventPriority)); box (DiagJson.esc eventChannelText) |])
                    let ((next, command), journalRequests), durableLines =
                        try
                            CompilerConsoleHud88.withDurableJsonHopacJobContext (fun () ->
                                DiagJson.withTerminalFlowKernelJournalJobContext (fun () ->
                                    terminalFlowGlobalReduceOwned state event))
                        with ex ->
                            CompilerConsoleHud88.emitImmediateFailureEvent
                                "terminal_flow_reducer_unhandled_exception"
                                "terminalFlowGlobalServerLoop"
                                (terminalFlowGlobalServerEventKind event + "|" + terminalFlowGlobalServerEventText event)
                                (ex.GetType().FullName)
                                "capture_bounded_reducer_boundary_then_rethrow"
                            CompilerConsoleHud88.captureReducerBoundaryException "terminal_flow_global_reduce_owned" ex
                            reraise()
                    do! DiagJson.terminalFlowKernelJournalSubmitCapturedJob journalRequests
                    do! CompilerConsoleHud88.submitProgressJsonLinesTerminalDurableJob durableLines
                    let commandKindId = terminalFlowGlobalServerCommandKindFor command
                    let commandKind = terminalFlowGlobalServerCommandKindText commandKindId
                    let commandOccurrence, shouldEmitCommand = DiagJson.sparseLogDecision ("selected|" + commandKind) 128L
                    if shouldEmitCommand then
                        DiagJson.emitOutsideHopac (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_flow_global_command_selected\",\"command_kind_du\":%s,\"event_ref\":%u,\"command_ref\":%u,\"event\":%s,\"command\":%s,\"consume_seq\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"first3_power2_every128\",\"owner\":\"single_reducer_actor\",\"polling_authority\":false}" [| box (DiagJson.esc commandKind); box (terminalFlowMintedRefOf "global_server_event_ref" eventText); box (terminalFlowGlobalServerCommandRef command); box (DiagJson.esc eventText); box (DiagJson.esc (terminalFlowGlobalServerCommandText command)); box consumedSeq; box commandOccurrence |])
                    let terminalCommand = terminalFlowGlobalServerCommandKindIsTerminal commandKindId
                    let _, serverDurableLines =
                        CompilerConsoleHud88.withDurableJsonHopacJobContext (fun () ->
                            terminalFlowGlobalServerEmit next event command "typed_reducer_actor_transition")
                    do! CompilerConsoleHud88.submitProgressJsonLinesTerminalDurableJob serverDurableLines
                    if terminalCommand then
                        // Terminal commands are control-plane work.  Execute them before the
                        // 50-row HUD projection so presentation cannot delay a dispositive
                        // FailClosed/CommitExit boundary or lose it to external interruption.
                        let! finalState = terminalFlowGlobalExecuteCommand next command
                        let! _indexedClosureRetried =
                            terminalFlowRetryPendingIndexedClosureForWakeJob
                                TerminalFlowIndexedClosureReducerTurnOperationalCreditClosed
                                finalState.revision
                        do! Hopac.Job.start (terminalFlowGlobalReducerPublishHudSnapshot finalState)
                        return! Hopac.Job.delay (fun () -> terminalFlowGlobalServerLoop finalState)
                    else
                        do! Hopac.Job.start (terminalFlowGlobalReducerPublishHudSnapshot next)
                        let! finalState = terminalFlowGlobalExecuteCommand next command
                        let! _indexedClosureRetried =
                            terminalFlowRetryPendingIndexedClosureForWakeJob
                                TerminalFlowIndexedClosureReducerTurnOperationalCreditClosed
                                finalState.revision
                        return! Hopac.Job.delay (fun () -> terminalFlowGlobalServerLoop finalState)
            }

        // MIGRATION: independent liveness receipt for the reducer QAP clock.  The main
        // deadman lane remains authoritative, while a second Hopac supervisor may republish
        // an already-mature watch only when this heartbeat has stopped for a bounded window.

        let private terminalFlowGlobalDeadmanHeartbeatGate = obj()
        let mutable private terminalFlowGlobalDeadmanHeartbeatMs = Environment.TickCount64

        let private terminalFlowGlobalDeadmanHeartbeatObserve nowMs =
            lock terminalFlowGlobalDeadmanHeartbeatGate (fun () -> terminalFlowGlobalDeadmanHeartbeatMs <- nowMs)

        let private terminalFlowGlobalDeadmanHeartbeatAgeMs nowMs =
            lock terminalFlowGlobalDeadmanHeartbeatGate (fun () -> max 0L (nowMs - terminalFlowGlobalDeadmanHeartbeatMs))

        [<StructuralEquality; NoComparison>]
        type private TerminalFlowOutcomeCandidateIngressDispositionId =
            | TerminalFlowOutcomeCandidateIngressBuildOkObserver
            | TerminalFlowOutcomeCandidateIngressQuarantineObserver
            | TerminalFlowOutcomeCandidateIngressFailClosedExecutable

        let private terminalFlowOutcomeCandidateIngressDispositionFor = function
            | DiagJson.TerminalOutcomeCandidateBuildOk -> TerminalFlowOutcomeCandidateIngressBuildOkObserver
            | DiagJson.TerminalOutcomeCandidateQuarantine -> TerminalFlowOutcomeCandidateIngressQuarantineObserver
            | DiagJson.TerminalOutcomeCandidateFailClosed
            | DiagJson.TerminalOutcomeCandidateSafetyWatchdogFailClosed -> TerminalFlowOutcomeCandidateIngressFailClosedExecutable

        let private terminalFlowOutcomeCandidateIngressPendingIntent = function
            | TerminalFlowOutcomeCandidateIngressBuildOkObserver -> TerminalFlowPendingBuildOk
            | TerminalFlowOutcomeCandidateIngressQuarantineObserver -> TerminalFlowPendingQuarantine
            | TerminalFlowOutcomeCandidateIngressFailClosedExecutable -> TerminalFlowPendingFailClosed

        let private terminalFlowOutcomeCandidateIngressDispositionText = function
            | TerminalFlowOutcomeCandidateIngressBuildOkObserver -> "BuildOkObserver"
            | TerminalFlowOutcomeCandidateIngressQuarantineObserver -> "QuarantineObserver"
            | TerminalFlowOutcomeCandidateIngressFailClosedExecutable -> "FailClosedExecutable"

        type TerminalFlowLegacyProvisionalFailureArbitrationId =
            | TerminalFlowFinalBuildOkOutranksLegacyProvisionalFailure
            | TerminalFlowClosedReducerBuildOkOutranksLegacyProvisionalFailure

        let private terminalFlowLegacyProvisionalFailureArbitrationText = function
            | TerminalFlowFinalBuildOkOutranksLegacyProvisionalFailure -> "final_build_ok_outranks_legacy_provisional_failure"
            | TerminalFlowClosedReducerBuildOkOutranksLegacyProvisionalFailure -> "closed_reducer_build_ok_outranks_legacy_provisional_failure"

        let rec private terminalFlowGlobalServerDeadmanLoop () : Hopac.Job<unit> =
            job {
                // Safety timer only: it never advances TerminalFlow. It may project
                // the retained work ledger, but dataflow progression remains exclusively
                // driven by root, outcome, actor and exit receipts.
                do! Hopac.timeOutMillis 1000
                terminalFlowGlobalDeadmanHeartbeatObserve Environment.TickCount64
                let! state = terminalFlowGlobalReducerReadActorState ()
                match terminalFlowLiveProgressEvidenceRead () with
                | Some(source, evidence) ->
                    terminalFlowEmitLiveWorkLedgerHeartbeat source evidence
                | None -> ()
                let topologyMaterialAgeMsNow = terminalFlowMaterialDeadmanAgeMs Environment.TickCount64 0L
                let topologyMaterialEpochNow = DiagJson.ownerDebtLiveWorkTieBreakerMaterialDeltaCountNow()
                let semanticEpochNow = DiagJson.terminalSemanticAuthorityCountNow()
                let frontierEpochNow = DiagJson.terminalFrontierProgressEpochNow()
                let frontierProgressBpNow =
                    state.authoritativeProgress
                    |> Option.map (fun snapshot -> CompilerKernelV2.BasisPoints.value snapshot.progressMidBp)
                    |> Option.defaultWith DiagJson.terminalFrontierProgressBpNow
                let frontierProgressAgeMsNow =
                    state.authoritativeProgress
                    |> Option.map (fun snapshot -> max 0L (Environment.TickCount64 - CompilerKernelV2.Measured.value snapshot.observedAt))
                    |> Option.defaultWith DiagJson.terminalFrontierProgressAgeMsNow
                let completionEpochNow = DiagJson.terminalCompletionCreditEpochNow()
                let completedCostNow = DiagJson.terminalCompletionCreditCostNow()
                let completionAgeMsNow = DiagJson.terminalCompletionCreditAgeMsNow()
                let qapWitnessClosureGate = terminalFlowQapWitnessSemanticClosureGateFor state
                match qapWitnessClosureGate with
                | TerminalFlowQapWitnessSemanticSeedAndClosedWorld _ ->
                    match state.qapMaturityWatch with
                    | Some watch ->
                        let rearmDecision = terminalFlowQapSemanticClosureRearmDecisionFor watch
                        match rearmDecision with
                        | TerminalFlowQapSemanticClosureRearmNotRequired -> ()
                        | _ ->
                            match terminalFlowQapWatchRearmForSemanticClosure state with
                            | Some(request, _) ->
                                let admission = terminalFlowQapWatchRebaseAdmit request
                                match admission with
                                | TerminalFlowQapWatchRebaseAdmitted requestRef ->
                                    DiagJson.emitTerminalJsonDurable (
                                        FastRuntimeFormat.format "{\"kind\":\"terminal_qap_semantic_closure_rearm_requested\",\"request_ref\":%u,\"rebase_receipt_ref\":%u,\"parent_generation_id\":%d,\"child_generation_id\":%d,\"from_progress_semantic_epoch\":%d,\"to_progress_semantic_epoch\":%d,\"from_operational_revision\":%d,\"to_operational_revision\":%d,\"rearm_attempt_ordinal\":%d,\"closure_gate_du\":%s,\"rearm_decision_du\":%s,\"admission_du\":%s,\"authority\":\"semantic_seed_closure_rearms_qap_watch_single_flight\",\"next\":\"consume_rebase_then_publish_maturity_witness\"}" [| box requestRef; box request.rebaseReceiptRef; box (terminalFlowQapGenerationValue request.parentGeneration); box (terminalFlowQapGenerationValue request.childGeneration); box request.fromSemanticEpoch; box request.toSemanticEpoch; box request.fromOperationalRevision; box request.toOperationalRevision; box (watch.rebaseCount + 1L); box (DiagJson.esc (terminalFlowQapWitnessSemanticClosureGateText qapWitnessClosureGate)); box (DiagJson.esc (terminalFlowQapSemanticClosureRearmDecisionText rearmDecision)); box (DiagJson.esc (terminalFlowQapWatchRebaseAdmissionText admission)) |])
                                    do! terminalFlowGlobalServerPublishJob (TerminalFlowGlobalServerQapWatchRebaseRequested request)
                                | TerminalFlowQapWatchRebaseCoalesced existingRequestRef ->
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"terminal_qap_semantic_closure_rearm_coalesced\",\"existing_request_ref\":%u,\"rearm_attempt_ordinal\":%d,\"closure_gate_du\":%s,\"rearm_decision_du\":%s,\"authority\":\"semantic_seed_closure_rearm_single_flight\"}" [| box existingRequestRef; box (watch.rebaseCount + 1L); box (DiagJson.esc (terminalFlowQapWitnessSemanticClosureGateText qapWitnessClosureGate)); box (DiagJson.esc (terminalFlowQapSemanticClosureRearmDecisionText rearmDecision)) |])
                            | None -> ()
                    | None -> ()
                | TerminalFlowQapWitnessAwaitSemanticSeedClosure
                | TerminalFlowQapWitnessAwaitExactClosedWorld _ -> ()
                let mutable legacyExitObservation = Unchecked.defaultof<LegacyProcessExitObserverRequest>
                let mutable typedTerminalFailureRequest : (LegacyProcessExitObserverRequest * uint32) option = None
                let takeLegacyExitObservation () =
                    match legacyProcessExitObserverTryRemove () with
                    | LegacyProcessExitObserverRemoved observation ->
                        legacyExitObservation <- observation
                        true
                    | LegacyProcessExitObserverEmpty -> false
                while takeLegacyExitObservation () do
                    let legacyExitReasonText = legacyProcessExitReasonText legacyExitObservation.reason
                    let observationRef = terminalFlowMintedRefOf "legacy_exit_observation_ref" (string legacyExitObservation.code + ":" + legacyExitReasonText)
                    let reducerAction =
                        match legacyExitObservation.kind with
                        | LegacyProvisionalTypedTerminalFailureRequested -> "typed_fail_closed_only_if_native_failure_latch_survives_material_progress"
                        | LegacyTypedTerminalFailureRequested _ -> "typed_fail_closed_command"
                        | LegacyPostRootWriterLeaseExpired -> "redrive_consume_if_pending"
                        | _ -> "observation_only"
                    terminalFlowEmitAdvancedConsoleProjection {
                        lane = TerminalFlowConsoleLaneExitSeal
                        sequence = state.revision
                        progressBp = int (max 0L (min 10000L frontierProgressBpNow))
                        etaMs = None
                        title = "legacy exit observation consumed"
                        detail =
                            FastRuntimeFormat.format "kind=%s|requested_exit=%d|reason=%s|reducer_action=%s" [| box (legacyProcessExitObservationKindTextPublic legacyExitObservation.kind); box legacyExitObservation.code; box legacyExitReasonText; box reducerAction |]
                        authorityRef = observationRef
                    }
                    let reducerHudSnapshot = ReducerHudAuthorityBridge.read ()
                    let reducerClosedBuildOk =
                        match reducerHudSnapshot.phase, reducerHudSnapshot.discovery with
                        | CompilerConsoleHud88.ReducerHudTerminalizing, CompilerConsoleHud88.ReducerHudDiscoveryClosed
                        | CompilerConsoleHud88.ReducerHudComplete, CompilerConsoleHud88.ReducerHudDiscoveryClosed ->
                            reducerHudSnapshot.work.semantic.totalMid > 0L
                            && reducerHudSnapshot.work.semantic.retiredCost + reducerHudSnapshot.work.semantic.provenDeadCost = reducerHudSnapshot.work.semantic.totalMid
                            && reducerHudSnapshot.work.semantic.knownRemainingCost = 0L
                            && reducerHudSnapshot.work.semantic.blockedCost = 0L
                            && reducerHudSnapshot.work.semantic.reserveP50Cost = 0L
                            && reducerHudSnapshot.work.semantic.reserveP90Cost = 0L
                            && List.isEmpty reducerHudSnapshot.blockers
                            && not (DiagJson.terminalSemanticAuthorityActiveNow())
                        | _ -> false
                    match legacyExitObservation.kind, state.pendingTerminal with
                    | LegacyProvisionalTypedTerminalFailureRequested, TerminalFlowPendingSlotCandidate pending
                        when pending.intent = TerminalFlowPendingBuildOk ->
                        let liveSemanticLedger = DiagJson.semanticWorkLedgerSnapshot()
                        let progressSnapshotRef =
                            state.authoritativeProgress
                            |> Option.map (fun snapshot -> snapshot.snapshotRef)
                            |> Option.defaultValue 0u
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"legacy_provisional_typed_failure_quarantined_by_final_build_ok\",\"observation_ref\":%u,\"requested_exit_code\":%d,\"reason\":%s,\"pending_terminal_ref\":%s,\"pending_fill_ref\":%s,\"progress_snapshot_ref\":%u,\"live_semantic_open_count\":%d,\"arbitration_du\":%s,\"legacy_observer_authority\":false,\"physical_exit_authority\":false,\"next\":\"continue_final_build_ok_total_order\"}" [| box observationRef; box legacyExitObservation.code; box (DiagJson.esc legacyExitReasonText); box (DiagJson.esc pending.terminalReceiptId); box (DiagJson.esc pending.fillKey); box progressSnapshotRef; box liveSemanticLedger.openCount; box (DiagJson.esc (terminalFlowLegacyProvisionalFailureArbitrationText TerminalFlowFinalBuildOkOutranksLegacyProvisionalFailure)) |])
                    | LegacyProvisionalTypedTerminalFailureRequested, TerminalFlowPendingSlotAwaitingCandidate when reducerClosedBuildOk ->
                        let liveSemanticLedger = DiagJson.semanticWorkLedgerSnapshot()
                        let progressSnapshotRef =
                            state.authoritativeProgress
                            |> Option.map (fun snapshot -> snapshot.snapshotRef)
                            |> Option.defaultValue 0u
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"legacy_provisional_typed_failure_quarantined_by_closed_reducer_projection\",\"observation_ref\":%u,\"requested_exit_code\":%d,\"reason\":%s,\"progress_snapshot_ref\":%u,\"live_semantic_open_count\":%d,\"reducer_generation\":%d,\"arbitration_du\":%s,\"legacy_observer_authority\":false,\"physical_exit_authority\":false,\"next\":\"continue_terminal_possession\"}" [| box observationRef; box legacyExitObservation.code; box (DiagJson.esc legacyExitReasonText); box progressSnapshotRef; box liveSemanticLedger.openCount; box reducerHudSnapshot.generation; box (DiagJson.esc (terminalFlowLegacyProvisionalFailureArbitrationText TerminalFlowClosedReducerBuildOkOutranksLegacyProvisionalFailure)) |])
                    | LegacyProvisionalTypedTerminalFailureRequested, _ ->
                        let recoveryDisposition = DiagJson.nativePromiseFailureRecoveryDispositionNow()
                        match recoveryDisposition with
                        | DiagJson.NativePromiseFailureRecoveredAfterMaterialProgress(closedMs, progressMs, _) ->
                            DiagJson.emitTerminalJsonDurable (
                                FastRuntimeFormat.format "{\"kind\":\"legacy_typed_failure_quarantined_after_native_failure_recovery\",\"observation_ref\":%u,\"requested_exit_code\":%d,\"reason\":%s,\"native_failure_closed_ms\":%d,\"material_progress_ms\":%d,\"recovery_disposition_du\":%s,\"legacy_observer_authority\":false,\"physical_exit_authority\":false,\"next\":\"continue_live_graph\"}" [| box observationRef; box legacyExitObservation.code; box (DiagJson.esc legacyExitReasonText); box closedMs; box progressMs; box (DiagJson.esc (DiagJson.nativePromiseFailureRecoveryDispositionText recoveryDisposition)) |])
                        | DiagJson.NativePromiseFailureRecoveryNotApplicable ->
                            DiagJson.emitTerminalJsonDurable (
                                FastRuntimeFormat.format "{\"kind\":\"legacy_typed_failure_quarantined_without_live_native_failure_latch\",\"observation_ref\":%u,\"requested_exit_code\":%d,\"reason\":%s,\"recovery_disposition_du\":%s,\"legacy_observer_authority\":false,\"physical_exit_authority\":false,\"next\":\"continue_live_graph\"}" [| box observationRef; box legacyExitObservation.code; box (DiagJson.esc legacyExitReasonText); box (DiagJson.esc (DiagJson.nativePromiseFailureRecoveryDispositionText recoveryDisposition)) |])
                        | DiagJson.NativePromiseFailureRecoveryAwaitingMaterialProgress _
                        | DiagJson.NativePromiseFailureRecoveryIrrevocable _ ->
                            typedTerminalFailureRequest <- Some(legacyExitObservation, observationRef)
                    | LegacyTypedTerminalFailureRequested _, _ ->
                        let liveSemanticLedger = DiagJson.semanticWorkLedgerSnapshot()
                        let quiescenceRequirement = legacyExitQuiescenceRequirementFor legacyExitObservation.reason
                        match quiescenceRequirement with
                        | LegacyExitRequiresSemanticQuiescence when liveSemanticLedger.openCount > 0L ->
                            DiagJson.emitTerminalJsonDurable (
                                FastRuntimeFormat.format "{\"kind\":\"legacy_typed_failure_quarantined_by_open_semantic_ledger\",\"observation_ref\":%u,\"requested_exit_code\":%d,\"reason\":%s,\"quiescence_requirement_du\":%s,\"live_semantic_open_count\":%d,\"live_semantic_admitted\":%d,\"live_semantic_receipts\":%d,\"legacy_observer_authority\":false,\"physical_exit_authority\":false,\"next\":\"continue_live_graph\"}" [| box observationRef; box legacyExitObservation.code; box (DiagJson.esc legacyExitReasonText); box (DiagJson.esc (legacyExitQuiescenceRequirementText quiescenceRequirement)); box liveSemanticLedger.openCount; box liveSemanticLedger.admitted; box liveSemanticLedger.receipts |])
                        | _ ->
                            typedTerminalFailureRequest <- Some(legacyExitObservation, observationRef)
                    | LegacyPostRootWriterLeaseExpired, TerminalFlowPendingSlotCandidate pending ->
                        let fillRef : TerminalFlowIdentityRef<TerminalFlowFillRefKind> =
                            terminalFlowIdentityRefOfText pending.fillKey
                        DiagJson.emitTerminalJsonDurable (
                            sprintf "{\"kind\":\"post_root_writer_lease_reducer_redrive_requested\",\"observation_ref\":%u,\"fill_ref\":%u,\"actor_phase_du\":\"Armed\",\"authority\":\"observer_evidence_to_reducer_redrive_only\",\"physical_exit_authority\":false}"
                                observationRef
                                (terminalFlowIdentityRefDigest fillRef))
                        terminalFlowGlobalServerPublish (TerminalFlowGlobalServerActorProjectionObserved(DiagJson.terminalSchedulerPushActorSnapshot()))
                    | LegacyPostRootWriterLeaseExpired, _ -> ()
                    | LegacyTrueMetronomeStalled, _ -> ()
                    // The failed-closed residual deadman is a host-liveness observation only.
                    // Its caller owns the physical failsafe; the semantic reducer must not promote it.
                    | LegacyFailedClosedResidualDeadman, _ -> ()
                    | LegacyOtherExitObservation _, _ -> ()
                if Option.isSome typedTerminalFailureRequest then
                    let request, observationRef = Option.get typedTerminalFailureRequest
                    let requestReasonText = legacyProcessExitReasonText request.reason
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"typed_terminal_exit_observation_promoted\",\"observation_ref\":%u,\"requested_exit_code\":%d,\"reason\":%s,\"authority\":\"single_reducer_fail_closed_command\",\"legacy_observer_authority\":false,\"next\":\"terminal_order_cutover_then_physical_exit\"}" [| box observationRef; box request.code; box (DiagJson.esc requestReasonText) |])
                    let reply =
                        CompilerKernelV2.CompilerRuntimeKernel.oneShot<TerminalFlowGlobalReducerState>
                            "terminal-flow-typed-failure-command"
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.send
                            terminalFlowGlobalServerControlChannel
                            (TerminalFlowReducerActorExecuteCommand(
                                TerminalFlowGlobalServerFailClosed(
                                    TerminalFlowFailureTypedTerminalExitRequested(
                                        request.code,
                                        terminalFlowTypedTerminalExitReasonCreate requestReasonText,
                                        observationRef)), 
                                reply))
                    let! _ =
                        CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
                    return! terminalFlowGlobalServerDeadmanLoop ()
                let qapWatchClockVerdictFor (watch:TerminalFlowGlobalQapMaturityWatch) =
                    terminalFlowQapWatchClockVerdictFor
                        terminalFlowQapWatchMaterialCompletionCostThreshold
                        terminalFlowQapWatchCompletionRebaseCap
                        watch
                        semanticEpochNow
                        frontierEpochNow
                        frontierProgressBpNow
                        completionEpochNow
                        completedCostNow
                let qapStableAgeFor (watch:TerminalFlowGlobalQapMaturityWatch) =
                    let watchAgeMs = max 0L (Environment.TickCount64 - watch.observedAtMs)
                    match qapWatchClockVerdictFor watch with
                    | TerminalFlowQapWatchRebaseMaterialFrontier
                    | TerminalFlowQapWatchRebaseMaterialSemantic
                    | TerminalFlowQapWatchRebaseMaterialCompletion -> 0L
                    | TerminalFlowQapWatchHoldProceduralClockChurn
                    | TerminalFlowQapWatchClockStable -> watchAgeMs
                let qapReducerWitnessAuthority =
                    match state.kernel.actor, state.kernel.root with
                    | KernelActorArmed(DiagJson.PushActorArmed, _, _), _ -> TerminalFlowQapWitnessActorArmed
                    | _, KernelRootResolved(_, _, _) -> TerminalFlowQapWitnessRootResolvedStableReducer
                    | _ -> TerminalFlowQapWitnessBlockedBeforeRoot
                let qapWatchCanWitness =
                    terminalFlowQapReducerWitnessAuthorityCanPublish qapReducerWitnessAuthority
                let qapWatchHardZeroDeltaDecision (watch:TerminalFlowGlobalQapMaturityWatch) =
                    let wallAgeMs = max 0L (Environment.TickCount64 - watch.observedAtMs)
                    let items = watch.fixpoint.items
                    let itemCount = items.Length
                    if wallAgeMs < 30000L then
                        TerminalFlowQapHardZeroDeltaBlocked(wallAgeMs, itemCount, TerminalFlowQapHardZeroDeltaAgeBelowMinimum)
                    elif List.isEmpty items then
                        TerminalFlowQapHardZeroDeltaBlocked(wallAgeMs, itemCount, TerminalFlowQapHardZeroDeltaEmptyFixpoint)
                    elif items |> List.exists (fun (item:TerminalFlowQapFixpointItem) -> item.materialDelta <> 0L) then
                        TerminalFlowQapHardZeroDeltaBlocked(wallAgeMs, itemCount, TerminalFlowQapHardZeroDeltaMaterialDeltaPresent)
                    elif items |> List.exists (fun (item:TerminalFlowQapFixpointItem) -> item.repeatCount < item.repeatCap) then
                        TerminalFlowQapHardZeroDeltaBlocked(wallAgeMs, itemCount, TerminalFlowQapHardZeroDeltaRepeatCapNotReached)
                    else
                        TerminalFlowQapHardZeroDeltaReady(wallAgeMs, itemCount)
                let qapWatchHardZeroDeltaCanWitness watch =
                    qapWatchHardZeroDeltaDecision watch |> terminalFlowQapHardZeroDeltaCanWitness
                let mutable qapWatchWonThisTick = false
                match state.qapMaturityWatch, state.terminalOrder, qapWitnessClosureGate with
                | Some watch, TerminalFlowGlobalOrderOpen, _
                    when terminalFlowQapGenerationAllowsRebase watch.generationAuthority.stage
                         && qapWatchCanWitness
                         && not (qapWatchHardZeroDeltaCanWitness watch)
                         && terminalFlowQapWatchClockVerdictRequiresRebase (qapWatchClockVerdictFor watch) ->
                    // A rebase is a typed single-flight reducer request. Repeated deadman
                    // observations coalesce into the existing request and no longer suppress
                    // residual-stall recovery while the global actor is busy.
                    let clockVerdict = qapWatchClockVerdictFor watch
                    let request =
                        terminalFlowQapWatchRebaseRequestFor
                            None
                            watch
                            semanticEpochNow
                            frontierEpochNow
                            frontierProgressBpNow
                            completionEpochNow
                            completedCostNow
                    let admission = terminalFlowQapWatchRebaseAdmit request
                    match admission with
                    | TerminalFlowQapWatchRebaseAdmitted requestRef ->
                        qapWatchWonThisTick <- true
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_qap_fixpoint_watch_rebase_requested\",\"request_ref\":%u,\"qap_rebase_receipt_id\":%u,\"fixpoint_ref\":%u,\"qap_parent_generation_id\":%d,\"qap_generation_id\":%d,\"qap_rebase_reason_du\":%s,\"qap_stage_before_du\":%s,\"qap_stage_after_du\":%s,\"qap_relation_set_hash\":%u,\"qap_relations_carried_count\":%d,\"qap_relations_invalidated_count\":%d,\"qap_relations_discovered_count\":%d,\"admission_du\":%s,\"clock_verdict_du\":%s,\"from_semantic_epoch\":%d,\"to_semantic_epoch\":%d,\"from_frontier_epoch\":%d,\"to_frontier_epoch\":%d,\"frontier_progress_bp\":%d,\"frontier_progress_pct\":%.2f,\"frontier_progress_age_ms\":%d,\"from_completion_epoch\":%d,\"to_completion_epoch\":%d,\"completed_cost\":%d,\"completion_age_ms\":%d,\"rebase_count_before\":%d,\"topology_material_age_ms\":%d,\"deadman_suppressed_this_tick\":true,\"authority\":\"single_reducer_qap_generation\"}" [| box requestRef; box request.rebaseReceiptRef; box (terminalFlowDurableRefValue request.fixpointRef); box (terminalFlowQapGenerationValue request.parentGeneration); box (terminalFlowQapGenerationValue request.childGeneration); box (DiagJson.esc (terminalFlowQapRebaseReasonText request.reason)); box (DiagJson.esc (terminalFlowQapGenerationStageText request.stageBefore)); box (DiagJson.esc (terminalFlowQapGenerationStageText request.stageAfter)); box request.relationDelta.childRelationSetHash; box request.relationDelta.carriedRelationRefs.Length; box request.relationDelta.invalidatedRelationRefs.Length; box request.relationDelta.discoveredRelationRefs.Length; box (DiagJson.esc (terminalFlowQapWatchRebaseAdmissionText admission)); box (DiagJson.esc (terminalFlowQapWatchClockVerdictText clockVerdict)); box request.fromSemanticEpoch; box request.toSemanticEpoch; box request.fromFrontierEpoch; box request.toFrontierEpoch; box request.frontierProgressBp; box (float request.frontierProgressBp / 100.0); box frontierProgressAgeMsNow; box request.fromCompletionEpoch; box request.toCompletionEpoch; box request.completedCost; box completionAgeMsNow; box watch.rebaseCount; box topologyMaterialAgeMsNow |])
                        terminalFlowEmitAdvancedConsoleProjection {
                            lane = TerminalFlowConsoleLaneQapWatch
                            sequence = watch.rebaseCount + 1L
                            progressBp = int (max 0L (min 10000L request.frontierProgressBp))
                            etaMs = Some terminalFlowResidualMaturityMinimumMaterialQuiescenceAgeMs
                            title = "qap rebase single-flight admitted"
                            detail =
                                terminalFlowQapWatchRebaseAdmissionText admission
                                + "|"
                                + terminalFlowQapWatchClockVerdictText clockVerdict
                                + sprintf "|completion_rebases=%d/%d" watch.completionRebaseCount terminalFlowQapWatchCompletionRebaseCap
                            authorityRef = requestRef
                        }
                        do! terminalFlowGlobalServerPublishJob (TerminalFlowGlobalServerQapWatchRebaseRequested request)
                    | TerminalFlowQapWatchRebaseCoalesced existingRequestRef ->
                        let occurrence, shouldEmit = DiagJson.sparseLogDecision "qap_watch_rebase_coalesced" 128L
                        if shouldEmit then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_qap_fixpoint_watch_rebase_coalesced\",\"request_ref\":%u,\"existing_request_ref\":%u,\"fixpoint_ref\":%u,\"admission_du\":%s,\"clock_verdict_du\":%s,\"occurrence_count\":%d,\"deadman_suppressed_this_tick\":false,\"authority\":\"typed_qap_rebase_single_flight\",\"next\":\"allow_residual_stall_observation\"}" [| box request.requestRef; box existingRequestRef; box (terminalFlowDurableRefValue request.fixpointRef); box (DiagJson.esc (terminalFlowQapWatchRebaseAdmissionText admission)); box (DiagJson.esc (terminalFlowQapWatchClockVerdictText clockVerdict)); box occurrence |])
                            terminalFlowEmitAdvancedConsoleProjection {
                                lane = TerminalFlowConsoleLaneQapWatch
                                sequence = occurrence
                                progressBp = int (max 0L (min 10000L request.frontierProgressBp))
                                etaMs = None
                                title = "qap rebase single-flight coalesced"
                                detail = terminalFlowQapWatchRebaseAdmissionText admission + "|deadman_released=true"
                                authorityRef = existingRequestRef
                            }
                | Some watch, TerminalFlowGlobalOrderOpen, TerminalFlowQapWitnessSemanticSeedAndClosedWorld _
                    when terminalFlowQapWatchIsAwaiting watch.maturity
                         && qapWatchCanWitness
                         && (state.progressAuthority.accepted |> Option.exists terminalFlowProgressEvidenceIsExactClosedWorld) ->
                    let hardZeroDeltaDecision = qapWatchHardZeroDeltaDecision watch
                    let hardZeroDeltaClosure = terminalFlowQapHardZeroDeltaCanWitness hardZeroDeltaDecision
                    let stableQuiescenceAgeMs =
                        match hardZeroDeltaDecision with
                        | TerminalFlowQapHardZeroDeltaReady(wallAgeMs, _) -> wallAgeMs
                        | TerminalFlowQapHardZeroDeltaBlocked _ -> qapStableAgeFor watch
                    let fixpointRefValue = terminalFlowDurableRefValue watch.fixpointRef
                    if hardZeroDeltaClosure then
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_qap_hard_zero_delta_observation\",\"fixpoint_ref\":%u,\"wall_age_ms\":%d,\"item_count\":%d,\"authority\":\"observer_only_repeat_zero_delta_no_terminal_authority\",\"decision_du\":%s,\"next_du\":\"consume_relations_and_fail_close_instead_of_dead_cpu_spin\"}" [| box fixpointRefValue; box stableQuiescenceAgeMs; box watch.fixpoint.items.Length; box (DiagJson.esc (terminalFlowQapHardZeroDeltaDecisionText hardZeroDeltaDecision)) |])
                    let maturityKey =
                        // Publication identity follows semantic lineage plus the typed
                        // drain-maturity phase. This preserves exact-once delivery while
                        // permitting one re-observation when a requested drain becomes
                        // positive StrandedProducer evidence.
                        terminalFlowQapMaturityPublicationKey fixpointRefValue (terminalFlowQapGenerationValue watch.generationAuthority.generation) semanticEpochNow
                    // QAP maturity has priority over the generic deadman, but only
                    // after both semantic authority and the monotonic compilation
                    // frontier have remained unchanged for the same bounded window.
                    qapWatchWonThisTick <- true
                    if terminalFlowQapMaturityPublicationRegistry.TryAdd(maturityKey, 0uy) then
                        let consumedFixpoint, relationReceiptRefs =
                            terminalFlowQapFixpointConsumeRelations (state.revision + 1L) watch.fixpoint
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_qap_relation_consumed_by_reducer\",\"fixpoint_ref\":%u,\"qap_generation_ref\":%d,\"witness_authority_du\":%s,\"relation_count\":%d,\"empty_relation_set\":%b,\"relation_receipt_count\":%d,\"relation_receipt_refs\":%s,\"reducer_sequence\":%d,\"exact_once\":true}" [| box fixpointRefValue; box (terminalFlowQapGenerationValue watch.generationAuthority.generation); box (DiagJson.esc (terminalFlowQapReducerWitnessAuthorityText qapReducerWitnessAuthority)); box watch.fixpoint.items.Length; box (List.isEmpty watch.fixpoint.items); box relationReceiptRefs.Length; box (DiagJson.esc (relationReceiptRefs |> List.map string |> String.concat ";")); box (state.revision + 1L) |])
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_qap_fixpoint_maturity_witness\",\"fixpoint_ref\":%u,\"maturity_key\":%s,\"observed_material_age_ms\":%d,\"stable_quiescence_age_ms\":%d,\"observed_semantic_epoch\":%d,\"semantic_epoch_now\":%d,\"observed_frontier_epoch\":%d,\"frontier_epoch_now\":%d,\"observed_frontier_progress_bp\":%d,\"frontier_progress_bp_now\":%d,\"frontier_progress_pct\":%.2f,\"frontier_progress_age_ms\":%d,\"observed_completion_epoch\":%d,\"completion_epoch_now\":%d,\"observed_completed_cost\":%d,\"completed_cost_now\":%d,\"completion_age_ms\":%d,\"qap_watch_rebase_count\":%d,\"topology_material_age_ms\":%d,\"topology_material_epoch\":%d,\"minimum_stable_age_ms\":%d,\"single_flight\":true,\"deadman_suppressed_this_tick\":true,\"authority\":\"semantic_plus_frontier_plus_completion_clock_reducer_watch\"}" [| box fixpointRefValue; box (DiagJson.esc (terminalFlowQapMaturityPublicationIdentityText maturityKey)); box watch.observedMaterialAgeMs; box stableQuiescenceAgeMs; box watch.observedSemanticEpoch; box semanticEpochNow; box watch.observedFrontierEpoch; box frontierEpochNow; box watch.observedFrontierProgressBp; box frontierProgressBpNow; box (float frontierProgressBpNow / 100.0); box frontierProgressAgeMsNow; box watch.observedCompletionEpoch; box completionEpochNow; box watch.observedCompletedCost; box completedCostNow; box completionAgeMsNow; box watch.rebaseCount; box topologyMaterialAgeMsNow; box topologyMaterialEpochNow; box terminalFlowResidualMaturityMinimumMaterialQuiescenceAgeMs |])
                        terminalFlowEmitAdvancedConsoleProjection {
                            lane = TerminalFlowConsoleLaneQapWatch
                            sequence = state.revision + 1L
                            progressBp = 10000
                            etaMs = Some 0L
                            title = "qap fixpoint witnessed"
                            detail = terminalFlowQapReducerWitnessAuthorityText qapReducerWitnessAuthority
                            authorityRef = fixpointRefValue
                        }
                        do! terminalFlowGlobalServerPublishJob (TerminalFlowGlobalServerQapFixpointObserved(watch.fixpointRef, consumedFixpoint, stableQuiescenceAgeMs, TerminalFlowQapMaturityWitnessedByReducer))
                | _ -> ()
                let postQuiescenceDispatchDeadman =
                    terminalFlowPostQuiescenceDispatchDeadmanDecisionFor Environment.TickCount64 state
                match postQuiescenceDispatchDeadman with
                | TerminalFlowPostQuiescenceDispatchDeadmanExpired(pendingRef, ageMs) ->
                    let pendingDepth = EvalWorklist.pendingCount()
                    let queueDepth = EvalWorklist.replayQueueDepth()
                    let activeDepth = EvalWorklist.replayDriverActiveDepthValue()
                    let promisePendingDepth, worklistRegisteredDepth, worklistRunningDepth =
                        terminalFlowDeadmanOutstandingGraphProbe()
                    let topologyEmpty =
                        pendingDepth = 0
                        && queueDepth = 0
                        && activeDepth = 0
                        && promisePendingDepth = 0
                        && worklistRegisteredDepth = 0
                        && worklistRunningDepth = 0
                    if topologyEmpty && terminalFlowPostQuiescenceDispatchDeadmanPublicationRegistry.TryAdd(pendingRef, 0uy) then
                        let! _ =
                            DiagJson.emitTerminalJsonDurableJob (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_post_quiescence_dispatch_deadman_published\",\"pending_ref\":%u,\"age_ms\":%d,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"promise_pending_depth\":%d,\"worklist_registered_depth\":%d,\"worklist_running_depth\":%d,\"actor_binding_du\":\"Noop\",\"handoff_du\":\"DispatchReady\",\"authority\":\"sealed_dispatch_admission_plus_empty_live_topology\",\"next\":\"publish_typed_deadman_fail_closed\"}" [| box pendingRef; box ageMs; box pendingDepth; box queueDepth; box activeDepth; box promisePendingDepth; box worklistRegisteredDepth; box worklistRunningDepth |])
                        ()
                        let reply =
                            CompilerKernelV2.CompilerRuntimeKernel.oneShot<TerminalFlowGlobalReducerState>
                                "terminal-flow-post-quiescence-deadman-command"
                        do!
                            CompilerKernelV2.CompilerRuntimeKernel.send
                                terminalFlowGlobalServerControlChannel
                                (TerminalFlowReducerActorExecuteCommand(
                                    TerminalFlowGlobalServerFailClosed(TerminalFlowFailureDeadmanExpired ageMs),
                                    reply))
                        let! _ =
                            CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
                        ()
                | TerminalFlowPostQuiescenceDispatchDeadmanGrace(pendingRef, ageMs) ->
                    let occurrence, shouldEmit =
                        DiagJson.sparseLogDecision "post_quiescence_dispatch_deadman_grace" 64L
                    if shouldEmit then
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_post_quiescence_dispatch_deadman_grace\",\"pending_ref\":%u,\"age_ms\":%d,\"deadline_ms\":%d,\"occurrence_count\":%d,\"actor_binding_du\":\"Noop\",\"handoff_du\":\"DispatchReady\",\"authority\":\"bounded_post_quiescence_dispatch_grace\"}" [| box pendingRef; box ageMs; box terminalFlowGlobalServerDeadmanAfterMs; box occurrence |])
                | TerminalFlowPostQuiescenceDispatchDeadmanInactive -> ()
                let replayFanoutCoalescedCount = DiagJson.snapshotKindCount "eval_worklist_owner_debt_pressure_coalesced_active_owner"
                let replayFanoutSuppressedCount = DiagJson.snapshotKindCount "eval_worklist_owner_debt_pressure_suppressed_by_scheduled_pulse"
                let replayCrossKindCoalescedCount = DiagJson.snapshotKindCount "eval_worklist_cross_kind_replay_coalesced_active_owner"
                let replayFanoutProtectionCount = replayFanoutCoalescedCount + replayFanoutSuppressedCount + replayCrossKindCoalescedCount
                if replayFanoutProtectionCount > 0 then
                    terminalFlowEmitAdvancedConsoleProjection {
                        lane = TerminalFlowConsoleLaneReplayFanout
                        sequence = int64 replayFanoutProtectionCount
                        progressBp = int (max 0L (min 10000L frontierProgressBpNow))
                        etaMs = None
                        title = "parallel replay fanout prevented"
                        detail =
                            FastRuntimeFormat.format "owner_coalesced=%d|pulse_suppressed=%d|cross_kind_coalesced=%d|pending=%d|queue=%d|active=%d|authority=single_replay_owner" [| box replayFanoutCoalescedCount; box replayFanoutSuppressedCount; box replayCrossKindCoalescedCount; box (EvalWorklist.pendingCount()); box (EvalWorklist.replayQueueDepth()); box (EvalWorklist.replayDriverActiveDepthValue()) |]
                        authorityRef = terminalFlowStableAuthorityRef "owner_debt_pressure_single_replay_owner"
                    }
                if not qapWatchWonThisTick then
                    match terminalFlowDeadmanObservationFor Environment.TickCount64 state with
                    | TerminalFlowDeadmanExpired(livenessAgeMs, materialAgeMs) ->
                        let pendingDepth = EvalWorklist.pendingCount()
                        let queueDepth = EvalWorklist.replayQueueDepth()
                        let activeDepth = EvalWorklist.replayDriverActiveDepthValue()
                        let durableRunEndCommitted = DiagJson.terminalFlowRunEndEmittedNow()
                        let legacySnapshotAppearsExhausted =
                            not durableRunEndCommitted
                            && state.qapMaturityWatch.IsNone
                            && pendingDepth = 0
                            && queueDepth = 0
                            && activeDepth = 0
                            && materialAgeMs >= terminalFlowGlobalServerDeadmanAfterMs
                        let failClosedPublished = false
                        let occurrence, shouldEmit =
                            DiagJson.sparseLogDecision
                                (if legacySnapshotAppearsExhausted then
                                     "legacy_deadman_snapshot_exhausted_observer"
                                 else
                                     "legacy_deadman_quarantined")
                                256L
                        let residualStallEscalation =
                            terminalFlowResidualStallEscalationFor state.qapMaturityWatch.IsSome materialAgeMs
                        let residualStallDrainScheduled = false
                        if shouldEmit then
                            let residualStallAuthorityRef =
                                match state.qapMaturityWatch with
                                | Some watch -> terminalFlowDurableRefValue watch.fixpointRef
                                | None -> 0u
                            let nextAction =
                                if durableRunEndCommitted then "durable_run_end_already_committed"
                                else "await_credit_return_or_semantic_outcome"
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_flow_legacy_deadman_quarantined\",\"liveness_age_ms\":%d,\"material_progress_age_ms\":%d,\"semantic_epoch\":%d,\"frontier_epoch\":%d,\"completion_epoch\":%d,\"qap_watch_present\":%b,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"legacy_snapshot_exhausted_observer\":%b,\"fail_closed_published\":%b,\"occurrence_count\":%d,\"residual_stall_escalation_du\":%s,\"force_replay_driver_drain_scheduled\":%b,\"semantic_drain_dispatch_scheduled\":%b,\"authority_du\":%s,\"can_fail_closed\":%b,\"can_dispatch\":%b,\"can_exit\":false,\"next\":%s}" [| box livenessAgeMs; box materialAgeMs; box semanticEpochNow; box frontierEpochNow; box completionEpochNow; box state.qapMaturityWatch.IsSome; box pendingDepth; box queueDepth; box activeDepth; box legacySnapshotAppearsExhausted; box failClosedPublished; box occurrence; box (DiagJson.esc (terminalFlowResidualStallEscalationText residualStallEscalation)); box residualStallDrainScheduled; box residualStallDrainScheduled; box (DiagJson.esc (if durableRunEndCommitted then "DurableRunEndSuppressesDeadman" elif legacySnapshotAppearsExhausted then "ObserverOnlySnapshotExhaustion" else "ObserverOnlyNoTerminalAuthority")); box false; box false; box (DiagJson.esc nextAction) |])
                            terminalFlowEmitAdvancedConsoleProjection {
                                lane = TerminalFlowConsoleLaneResidualStall
                                sequence = occurrence
                                progressBp = int (max 0L (min 10000L frontierProgressBpNow))
                                etaMs = None
                                title = if legacySnapshotAppearsExhausted then "legacy snapshot exhausted observer" else "residual stall observed"
                                detail =
                                    terminalFlowResidualStallEscalationText residualStallEscalation
                                    + FastRuntimeFormat.format "|qap_watch=%b|pending=%d|queue=%d|active=%d|drain_scheduled=%b|fail_closed=%b" [| box state.qapMaturityWatch.IsSome; box pendingDepth; box queueDepth; box activeDepth; box residualStallDrainScheduled; box failClosedPublished |]
                                authorityRef = residualStallAuthorityRef
                            }
                    | TerminalFlowDeadmanAwaitingRoot
                    | TerminalFlowDeadmanActorTerminal
                    | TerminalFlowDeadmanWatching _ -> ()
                return! Hopac.Job.delay (fun () -> terminalFlowGlobalServerDeadmanLoop ())
            }

        type TerminalFlowQapMonitorTrigger =
            | TerminalFlowQapMonitorHeartbeatStale of heartbeatAgeMs:int64
            | TerminalFlowQapMonitorWatchStableUnderProceduralChurn of watchAgeMs:int64 * heartbeatAgeMs:int64
            | TerminalFlowQapMonitorNotReady of watchAgeMs:int64 * heartbeatAgeMs:int64

        let private terminalFlowQapMonitorTriggerFor heartbeatAgeMs watchAgeMs =
            if heartbeatAgeMs >= 5000L then
                TerminalFlowQapMonitorHeartbeatStale heartbeatAgeMs
            elif watchAgeMs >= terminalFlowResidualMaturityMinimumMaterialQuiescenceAgeMs then
                TerminalFlowQapMonitorWatchStableUnderProceduralChurn(watchAgeMs, heartbeatAgeMs)
            else
                TerminalFlowQapMonitorNotReady(watchAgeMs, heartbeatAgeMs)

        let private terminalFlowQapMonitorTriggerCanPublish = function
            | TerminalFlowQapMonitorHeartbeatStale _
            | TerminalFlowQapMonitorWatchStableUnderProceduralChurn _ -> true
            | TerminalFlowQapMonitorNotReady _ -> false

        let private terminalFlowQapMonitorTriggerText = function
            | TerminalFlowQapMonitorHeartbeatStale heartbeatAgeMs ->
                sprintf "heartbeat_stale|heartbeat_age_ms=%d" heartbeatAgeMs
            | TerminalFlowQapMonitorWatchStableUnderProceduralChurn(watchAgeMs, heartbeatAgeMs) ->
                sprintf "watch_stable_under_procedural_churn|watch_age_ms=%d|heartbeat_age_ms=%d" watchAgeMs heartbeatAgeMs
            | TerminalFlowQapMonitorNotReady(watchAgeMs, heartbeatAgeMs) ->
                sprintf "not_ready|watch_age_ms=%d|heartbeat_age_ms=%d" watchAgeMs heartbeatAgeMs

        let private terminalFlowQapMonitorTriggerFixture () =
            let threshold = terminalFlowResidualMaturityMinimumMaterialQuiescenceAgeMs
            let proceduralChurnTrigger = terminalFlowQapMonitorTriggerFor 0L threshold
            let coldTrigger = terminalFlowQapMonitorTriggerFor 0L (max 0L (threshold - 1L))
            if not (terminalFlowQapMonitorTriggerCanPublish proceduralChurnTrigger) then
                failwith "Stable QAP watches must remain observable under procedural heartbeat chatter."
            if terminalFlowQapMonitorTriggerCanPublish coldTrigger then
                failwith "Young QAP watches must not bypass the maturity window."

        type TerminalFlowDeferredConformanceResult =
            | TerminalFlowDeferredConformancePassed
            | TerminalFlowDeferredConformanceFailed of reason:CompilerKernelV2.OperationalReasonId

        let runDeferredTerminalFlowConformanceInProcess () =
            CompilerRuntimeActivation.requireInProcessEntered "terminal_flow_deferred_conformance"
            try
                terminalFlowRunLocalConformance ()
                terminalFlowQapMaturityPublicationGenerationFixture ()
                terminalFlowQapMonitorTriggerFixture ()
                TerminalFlowDeferredConformancePassed
            with ex ->
                TerminalFlowDeferredConformanceFailed (CompilerKernelV2.OperationalReasonIdOps.create ex.Message)

        // MIGRATION: the MIGRATION trace kept the global heartbeat fresh with boundary
        // telemetry while a child QAP watch remained Awaiting for more than four minutes.
        // This in-process monitor is still not a second terminal authority: it republishes only an
        // existing watch, shares the exact-once maturity registry and requires the reducer
        // clock verdict.  A stable watch may now win even when procedural chatter pets the
        // generic heartbeat.
        let rec private terminalFlowGlobalServerQapLivenessMonitorLoop () : Hopac.Job<unit> =
            job {
                do! Hopac.timeOutMillis 2000
                let nowMs = Environment.TickCount64
                let heartbeatAgeMs = terminalFlowGlobalDeadmanHeartbeatAgeMs nowMs
                let! state = terminalFlowGlobalReducerReadActorState ()
                let qapWitnessClosureGate = terminalFlowQapWitnessSemanticClosureGateFor state
                match state.qapMaturityWatch, state.terminalOrder, qapWitnessClosureGate with
                | Some watch, TerminalFlowGlobalOrderOpen, TerminalFlowQapWitnessSemanticSeedAndClosedWorld _
                    when terminalFlowQapWatchIsAwaiting watch.maturity ->
                    let stableAgeMs = max 0L (nowMs - watch.observedAtMs)
                    let monitorTrigger = terminalFlowQapMonitorTriggerFor heartbeatAgeMs stableAgeMs
                    if terminalFlowQapMonitorTriggerCanPublish monitorTrigger then
                        let semanticEpochNow = DiagJson.terminalSemanticAuthorityCountNow()
                        let frontierEpochNow = DiagJson.terminalFrontierProgressEpochNow()
                        let frontierProgressBpNow = DiagJson.terminalFrontierProgressBpNow()
                        let completionEpochNow = DiagJson.terminalCompletionCreditEpochNow()
                        let completedCostNow = DiagJson.terminalCompletionCreditCostNow()
                        let clockVerdict =
                            terminalFlowQapWatchClockVerdictFor
                                terminalFlowQapWatchMaterialCompletionCostThreshold
                                terminalFlowQapWatchCompletionRebaseCap
                                watch
                                semanticEpochNow
                                frontierEpochNow
                                frontierProgressBpNow
                                completionEpochNow
                                completedCostNow
                        let witnessAuthority =
                            match state.kernel.actor, state.kernel.root with
                            | KernelActorArmed(DiagJson.PushActorArmed, _, _), _ -> TerminalFlowQapWitnessActorArmed
                            | _, KernelRootResolved(_, _, _) -> TerminalFlowQapWitnessRootResolvedStableReducer
                            | _ -> TerminalFlowQapWitnessBlockedBeforeRoot
                        let proceduralRebaseOverride =
                            stableAgeMs >= 30000L
                            && not (DiagJson.terminalSemanticAuthorityActiveNow())
                            && (match clockVerdict with
                                | TerminalFlowQapWatchRebaseMaterialFrontier
                                | TerminalFlowQapWatchRebaseMaterialCompletion
                                | TerminalFlowQapWatchRebaseMaterialSemantic -> true
                                | TerminalFlowQapWatchHoldProceduralClockChurn
                                | TerminalFlowQapWatchClockStable -> false)
                        if terminalFlowQapReducerWitnessAuthorityCanPublish witnessAuthority
                           && (not (terminalFlowQapWatchClockVerdictRequiresRebase clockVerdict)
                               || proceduralRebaseOverride) then
                            let fixpointRefValue = terminalFlowDurableRefValue watch.fixpointRef
                            let maturityKey = terminalFlowQapMaturityPublicationKey fixpointRefValue (terminalFlowQapGenerationValue watch.generationAuthority.generation) semanticEpochNow
                            if terminalFlowQapMaturityPublicationRegistry.TryAdd(maturityKey, 0uy) then
                                let consumedFixpoint, relationReceiptRefs =
                                    terminalFlowQapFixpointConsumeRelations (state.revision + 1L) watch.fixpoint
                                DiagJson.emitTerminalJsonDurable (
                                    FastRuntimeFormat.format "{\"kind\":\"terminal_qap_liveness_supervisor_recovered\",\"fixpoint_ref\":%u,\"trigger_du\":%s,\"heartbeat_age_ms\":%d,\"stable_age_ms\":%d,\"clock_verdict_du\":%s,\"procedural_rebase_override\":%b,\"relation_receipt_count\":%d,\"semantic_drain_request_age_ms\":%d,\"authority\":\"same_registry_reducer_qap_rescue\",\"duplicate_terminal_authority\":false}" [| box fixpointRefValue; box (DiagJson.esc (terminalFlowQapMonitorTriggerText monitorTrigger)); box heartbeatAgeMs; box stableAgeMs; box (DiagJson.esc (terminalFlowQapWatchClockVerdictText clockVerdict)); box proceduralRebaseOverride; box relationReceiptRefs.Length; box (DiagJson.terminalSemanticDrainRequestAgeMsNow()) |])
                                terminalFlowEmitAdvancedConsoleProjection {
                                    lane = TerminalFlowConsoleLaneQapWatch
                                    sequence = state.revision + 1L
                                    progressBp = int (max 0L (min 10000L frontierProgressBpNow))
                                    etaMs = None
                                    title = "qap child generation reobserved"
                                    detail = terminalFlowQapMonitorTriggerText monitorTrigger + "|" + terminalFlowQapWatchClockVerdictText clockVerdict
                                    authorityRef = fixpointRefValue
                                }
                                do! terminalFlowGlobalServerPublishJob (
                                    TerminalFlowGlobalServerQapFixpointObserved(
                                        watch.fixpointRef,
                                        consumedFixpoint,
                                        stableAgeMs,
                                        TerminalFlowQapMaturityWitnessedByReducer))
                | _ -> ()
                return! Hopac.Job.delay (fun () -> terminalFlowGlobalServerQapLivenessMonitorLoop ())
            }

        let private terminalFlowCanonicalRootReceiptBridge () : Hopac.Job<unit> =
            job {
                let! read = DiagJson.canonicalRootAuthorityAwait DiagJson.CanonicalRootConsumerTerminalFlow
                terminalFlowGlobalServerPublish (
                    TerminalFlowGlobalServerEvaluatorRootResolved(
                        read.notice.receiptId,
                        read.notice.resolvedAtMs,
                        read.notice.evidenceRef,
                        true))
                return ()
            }

        // Intent is carried by the typed publisher notice. The reason remains diagnostic text only.
        // Canonical-root bridge starts from the explicit in-process runtime boundary.
        let private terminalFlowInstallOutcomeCandidatePublisher () =
            DiagJson.terminalOutcomeCandidateInstallPublisher (fun notice ->
                let fillKey = notice.fillKey
                let terminalReceiptId = notice.terminalReceiptId
                let reason = CompilerKernelV2.OperationalReasonIdOps.text notice.reason
                let root = DiagJson.canonicalRootAuthoritySnapshot()
                let rootReceiptId =
                    if String.IsNullOrWhiteSpace root.receiptId then "root:awaiting-canonical-receipt" else root.receiptId
                let closeDecision =
                    TerminalFlowOwnerCloseAlreadyExhausted {
                        passCount = 1
                        materialDeltaOnPass = 0
                        pendingDepth = 0
                        queueDepth = 0
                        activeDepth = 0
                        proceduralDepth = 0
                    }
                let ingressDisposition = terminalFlowOutcomeCandidateIngressDispositionFor notice.intent
                let pendingIntent = terminalFlowOutcomeCandidateIngressPendingIntent ingressDisposition
                let noticeSourceRef =
                    terminalFlowMintedRefOf "terminal_notice_source_ref" (terminalReceiptId + "|" + fillKey)
                let pending =
                    terminalFlowPendingCandidateCreate
                        terminalReceiptId
                        fillKey
                        pendingIntent
                        (match notice.intent with
                         | DiagJson.TerminalOutcomeCandidateSafetyWatchdogFailClosed -> TerminalFlowPendingAdmissionSafetyWatchdog noticeSourceRef
                         | _ -> TerminalFlowPendingAdmissionEvaluatorNotice noticeSourceRef)
                        (match ingressDisposition with
                         | TerminalFlowOutcomeCandidateIngressFailClosedExecutable -> TerminalFlowPendingNativeExecutable noticeSourceRef
                         | TerminalFlowOutcomeCandidateIngressBuildOkObserver
                         | TerminalFlowOutcomeCandidateIngressQuarantineObserver -> TerminalFlowPendingObserverProjection noticeSourceRef)
                        (fun stageToken ->
                            job {
                                let resolvedRootReceiptId = terminalFlowIdentityRefText stageToken.rootReceiptRef
                                let actorBefore = DiagJson.terminalSchedulerPushActorSnapshot()
                                terminalFlowGlobalServerPublish (TerminalFlowGlobalServerActorProjectionObserved actorBefore)
                                let joinKey = terminalFlowDispatchJoinKeyFor resolvedRootReceiptId terminalReceiptId fillKey
                                let handoff =
                                    match ingressDisposition with
                                    | TerminalFlowOutcomeCandidateIngressFailClosedExecutable ->
                                        terminalFlowNativeHandoffFailClosed reason
                                    | TerminalFlowOutcomeCandidateIngressBuildOkObserver
                                    | TerminalFlowOutcomeCandidateIngressQuarantineObserver ->
                                        TerminalFlowNativeHandoffCommitBlocked(
                                            fillKey,
                                            TerminalFlowWhyNotObserverOnly(CompilerKernelV2.OperationalReasonIdOps.create ("diagjson_candidate_observation_only|" + reason)),
                                            closeDecision)
                                let handoffRef = terminalFlowStableAuthorityRef (TerminalFlowNativeHandoffIdentity handoff)
                                let transition =
                                    match ingressDisposition with
                                    | TerminalFlowOutcomeCandidateIngressFailClosedExecutable -> TerminalFlowSchedulerPushDispatchFailClosed handoffRef
                                    | TerminalFlowOutcomeCandidateIngressBuildOkObserver
                                    | TerminalFlowOutcomeCandidateIngressQuarantineObserver ->
                                        TerminalFlowSchedulerPushDispatchRejected(TerminalFlowDispatchContinuationRejected handoffRef)
                                let actorAfter = DiagJson.terminalSchedulerPushActorSnapshot()
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_push_transition\",\"actor_phase_before_du\":%s,\"actor_phase_after_du\":%s,\"actor_arm_attempted\":true,\"actor_arm_result_du\":%s,\"ingress_disposition_du\":%s,\"dispatch_idempotency_key\":%u,\"handoff_ref\":%u,\"terminal_outcome_fill_key\":%s,\"terminal_outcome_receipt_id\":%s,\"request_publication\":\"owned_by_reducer\",\"duplicate_request_published\":false,\"authority\":\"reducer_owned_materialized_request_execution\"}" [| box (DiagJson.esc (DiagJson.terminalSchedulerPushActorPhaseText actorBefore.phase)); box (DiagJson.esc (DiagJson.terminalSchedulerPushActorPhaseText actorAfter.phase)); box (DiagJson.esc (terminalFlowSchedulerPushTransitionText transition)); box (DiagJson.esc (terminalFlowOutcomeCandidateIngressDispositionText ingressDisposition)); box joinKey.keyRef; box handoffRef; box (DiagJson.esc fillKey); box (DiagJson.esc terminalReceiptId) |])
                                return handoff
                            })
                match ingressDisposition with
                | TerminalFlowOutcomeCandidateIngressFailClosedExecutable ->
                    // Typed failures are executable reducer commands. They must supersede
                    // provisional success through the same actor rather than escaping via a
                    // footer/direct-exit side channel.
                    let reducerRevisionBeforeWake, reducerQuiescenceBefore =
                        lock terminalFlowGlobalReducerProjectionGate (fun () ->
                            let revision = terminalFlowGlobalReducerProjectionMirror.revision
                            let quiescence =
                                match terminalFlowGlobalReducerProjectionMirror.reducerQuiescence with
                                | TerminalFlowReducerIdle committedRevision -> sprintf "Idle(revision=%d)" committedRevision
                                | TerminalFlowReducerProcessing(eventRef, startedAtMs, revisionBefore) ->
                                    FastRuntimeFormat.format "Processing(event_ref=%u|age_ms=%d|revision_before=%d)" [| box eventRef; box (max 0L (Environment.TickCount64 - startedAtMs)); box revisionBefore |]
                            revision, quiescence)
                    let executableMailboxWakeRequested = true
                    let executableMailboxWakePublished, executableMailboxPublicationRef =
                        terminalFlowPublishDeferredOutcomeMailboxOnce pending
                    // A read request is a control-lane pulse only: it cannot create or
                    // duplicate a terminal candidate. It makes reducer liveness independent
                    // of whether the actor had already reached Idle when the exact-once
                    // candidate publication was scheduled.
                    let reducerControlPulseRequested = true
                    HopacExtensions.start (job {
                        let! stateAfterPulse = terminalFlowGlobalReducerReadActorState ()
                        let snapshotAfterPulse = terminalFlowImmutableTerminalSnapshotFor stateAfterPulse
                        let reducerQuiescenceAfterPulse =
                            match stateAfterPulse.reducerQuiescence with
                            | TerminalFlowReducerIdle committedRevision -> sprintf "Idle(revision=%d)" committedRevision
                            | TerminalFlowReducerProcessing(eventRef, startedAtMs, revisionBefore) ->
                                FastRuntimeFormat.format "Processing(event_ref=%u|age_ms=%d|revision_before=%d)" [| box eventRef; box (max 0L (Environment.TickCount64 - startedAtMs)); box revisionBefore |]
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format
                                "{\"kind\":\"terminal_flow_executable_candidate_control_pulse_observed\",\"candidate_terminal_outcome_ref\":%u,\"reducer_revision_before_pulse\":%d,\"reducer_revision_after_pulse\":%d,\"reducer_revision_advanced\":%b,\"reducer_quiescence_after_du\":%s,\"terminal_stage_after_du\":%s,\"mailbox_wake_published\":%b,\"pulse_observation_du\":\"control_lane_read_may_observe_before_or_after_candidate\",\"pulse_observation_ordering_authority\":false,\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"authority\":\"typed_executable_candidate_control_lane_liveness_receipt\",\"next\":\"observe_reducer_possession_or_bounded_failed_closed_deadman\"}"
                                [| box (terminalFlowMintedRefOf "candidate_terminal_outcome_ref" terminalReceiptId); box reducerRevisionBeforeWake; box snapshotAfterPulse.reducerRevision; box (snapshotAfterPulse.reducerRevision <> reducerRevisionBeforeWake); box (DiagJson.esc reducerQuiescenceAfterPulse); box (DiagJson.esc (terminalFlowImmutableTerminalStageText snapshotAfterPulse.terminalStage)); box executableMailboxWakePublished |])
                        return ()
                    })
                    let candidateIdentity : TerminalFlowObservedOutcomeCandidateIdentity =
                        { terminalReceiptRef = CompilerIdentityKernel.ContentDigest.ofText "terminal-flow-observed-outcome-receipt" terminalReceiptId
                          fillRef = CompilerIdentityKernel.ContentDigest.ofText "terminal-flow-observed-outcome-fill" fillKey }
                    if terminalFlowObservedOutcomeCandidateRegistry.TryAdd(candidateIdentity, 0uy) then
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_flow_global_outcome_candidate_observed\",\"candidate_terminal_outcome_ref\":%u,\"candidate_fill_ref\":%u,\"candidate_root_receipt_ref\":%u,\"candidate_reason_ref\":%u,\"candidate_reason_du\":%s,\"pending_intent\":%s,\"ingress_disposition_du\":%s,\"source\":\"diagjson_terminal_outcome_candidate_hook\",\"observer_only_failclosed_suppressed\":false,\"reducer_authority\":true,\"authoritative_cache_mutated\":false,\"dedupe_first_seen\":true,\"candidate_identity_du\":\"terminal_receipt_plus_fill\",\"reason_identity_authority\":false,\"mailbox_wake_requested\":%b,\"mailbox_wake_published\":%b,\"mailbox_publication_ref\":%u,\"control_lane_pulse_requested\":%b,\"control_lane_pulse_ordering_authority\":false,\"reducer_revision_before_wake\":%d,\"reducer_quiescence_before_du\":%s,\"delivery_du\":\"ReducerOwnedExactOnceTerminalPriorityMailboxWake\",\"control_authority_inputs_du\":\"typed_ingress_disposition+candidate_identity+reducer_projection\",\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"next\":\"await_single_reducer_terminal_possession_and_receipts\"}" [| box (terminalFlowMintedRefOf "candidate_terminal_outcome_ref" terminalReceiptId); box (terminalFlowMintedRefOf "candidate_fill_ref" fillKey); box (terminalFlowMintedRefOf "candidate_root_receipt_ref" rootReceiptId); box (terminalFlowMintedRefOf "candidate_reason_ref" reason); box (DiagJson.esc reason); box (DiagJson.esc (terminalFlowPendingIntentText pendingIntent)); box (DiagJson.esc (terminalFlowOutcomeCandidateIngressDispositionText ingressDisposition)); box executableMailboxWakeRequested; box executableMailboxWakePublished; box executableMailboxPublicationRef; box reducerControlPulseRequested; box reducerRevisionBeforeWake; box (DiagJson.esc reducerQuiescenceBefore) |])
                        let reducerRevisionAtCandidate = reducerRevisionBeforeWake
                        let executableCandidateReceiptWatchdogMs = 1500
                        let receiptWatchdog =
                            System.Threading.Thread(System.Threading.ThreadStart(fun () ->
                                try
                                    System.Threading.Thread.Sleep(executableCandidateReceiptWatchdogMs)
                                    let snapshotAfterDeadman =
                                        lock terminalFlowGlobalReducerProjectionGate (fun () ->
                                            terminalFlowImmutableTerminalSnapshotFor terminalFlowGlobalReducerProjectionMirror)
                                    let revisionAfter = snapshotAfterDeadman.reducerRevision
                                    let stageAfter = snapshotAfterDeadman.terminalStage
                                    // The reducer snapshot carries a pre-proof physical-exit intent ref.
                                    // It is not proof that Environment.Exit actually ran. A watchdog
                                    // that is still executing in this process has positive evidence
                                    // that host exit has not yet been observed, regardless of intent.
                                    let physicalExitIntentRecorded = snapshotAfterDeadman.physicalExitReceiptRef <> 0u
                                    let hostExitObserved = false
                                    let runEndDurable = snapshotAfterDeadman.runEndReceiptRef <> 0u
                                    let commitDurable = snapshotAfterDeadman.commitReceiptRef <> 0u
                                    let doneDurable = snapshotAfterDeadman.doneReceiptRef <> 0u
                                    let exitRequestObserved = DiagJson.terminalFailureExitRequestedNow()
                                    let failedClosedExitCode =
                                        snapshotAfterDeadman.exitCode
                                        |> Option.filter (fun code -> code <> 0)
                                        |> Option.defaultValue 1
                                    let receiptChain =
                                        terminalFlowExecutableCandidateReceiptChainFor
                                            commitDurable
                                            doneDurable
                                            runEndDurable
                                            physicalExitIntentRecorded
                                    let watchdogDisposition =
                                        terminalFlowExecutableCandidateWatchdogDispositionFor
                                            failedClosedExitCode
                                            receiptChain
                                    let nextAction =
                                        match watchdogDisposition with
                                        | TerminalFlowCandidateWatchdogArmPhysicalFailsafe _ ->
                                            "arm_physical_failure_exit_failsafe_after_durable_receipt_chain"
                                        | TerminalFlowCandidateWatchdogAwaitReducerProof _ ->
                                            "repulse_reducer_without_host_exit_and_await_durable_receipt_chain"
                                    if not hostExitObserved then
                                        DiagJson.emitTerminalJsonDurable (
                                            FastRuntimeFormat.format
                                                "{\"kind\":\"terminal_executable_candidate_receipt_watchdog_expired\",\"candidate_terminal_outcome_ref\":%u,\"reducer_revision_at_candidate\":%d,\"reducer_revision_after\":%d,\"reducer_revision_advanced\":%b,\"terminal_stage_after_du\":%s,\"watchdog_delay_ms\":%d,\"commit_receipt_ref\":%u,\"done_receipt_ref\":%u,\"run_end_receipt_ref\":%u,\"physical_exit_intent_ref\":%u,\"commit_durable\":%b,\"done_durable\":%b,\"run_end_durable\":%b,\"physical_exit_intent_recorded\":%b,\"receipt_chain_du\":%s,\"watchdog_disposition_du\":%s,\"host_exit_observed\":%b,\"exit_request_observed\":%b,\"failed_closed_exit_code\":%d,\"semantic_success_authorized\":false,\"failure_exit_only\":true,\"terminal_stage_authority\":false,\"physical_exit_intent_is_host_exit_authority\":false,\"host_exit_observation_authority\":true,\"exit_request_observation_authority\":false,\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"authority\":\"live_watchdog_observes_host_exit_and_defers_to_typed_receipt_chain\",\"next\":%s}"
                                                [| box (terminalFlowMintedRefOf "candidate_terminal_outcome_ref" terminalReceiptId); box reducerRevisionAtCandidate; box revisionAfter; box (revisionAfter <> reducerRevisionAtCandidate); box (DiagJson.esc (terminalFlowImmutableTerminalStageText stageAfter)); box executableCandidateReceiptWatchdogMs; box snapshotAfterDeadman.commitReceiptRef; box snapshotAfterDeadman.doneReceiptRef; box snapshotAfterDeadman.runEndReceiptRef; box snapshotAfterDeadman.physicalExitReceiptRef; box commitDurable; box doneDurable; box runEndDurable; box physicalExitIntentRecorded; box (DiagJson.esc (terminalFlowExecutableCandidateReceiptChainText receiptChain)); box (DiagJson.esc (terminalFlowExecutableCandidateWatchdogDispositionText watchdogDisposition)); box hostExitObserved; box exitRequestObserved; box failedClosedExitCode; box (DiagJson.esc nextAction) |])
                                        match watchdogDisposition with
                                        | TerminalFlowCandidateWatchdogArmPhysicalFailsafe(_, exitCode) ->
                                            DiagJson.forceProcessExitDirect exitCode DiagJson.LegacyExitFailedClosedResidualDeadman
                                        | TerminalFlowCandidateWatchdogAwaitReducerProof _ ->
                                            // A candidate is not a physical-exit authority. If the reducer has
                                            // not produced the durable receipt chain yet, keep liveness pressure
                                            // on the control lane and leave failed-closed residual escape to the
                                            // indexed closure deadman, which also sees executable owner state.
                                            HopacExtensions.start (job {
                                                let! _ = terminalFlowGlobalReducerReadActorState ()
                                                return ()
                                            })
                                with _ -> ()))
                        receiptWatchdog.IsBackground <- true
                        receiptWatchdog.Name <- "spiral-terminal-executable-candidate-receipt-watchdog"
                        receiptWatchdog.Start()
                | TerminalFlowOutcomeCandidateIngressBuildOkObserver
                | TerminalFlowOutcomeCandidateIngressQuarantineObserver ->
                    // A callback may arrive while the reducer is processing or after it has
                    // become idle. Preserve one exact-once deferred receipt and publish a
                    // terminal-priority wake only for a new slot or a higher-authority
                    // replacement; equivalent observer churn must not flood the actor mailbox.
                    let reducerQuiescenceText =
                        lock terminalFlowGlobalReducerProjectionGate (fun () ->
                            match terminalFlowGlobalReducerProjectionMirror.reducerQuiescence with
                            | TerminalFlowReducerIdle committedRevision -> sprintf "Idle(revision=%d)" committedRevision
                            | TerminalFlowReducerProcessing(eventRef, startedAtMs, revisionBefore) ->
                                FastRuntimeFormat.format "Processing(event_ref=%u|age_ms=%d|revision_before=%d)" [| box eventRef; box (max 0L (Environment.TickCount64 - startedAtMs)); box revisionBefore |])
                    let deferredDisposition = terminalFlowDeferOutcomeForReducer pending
                    let deferredDispositionText, conflictExistingRef, conflictIncomingRef, existingCandidateClass, incomingCandidateClass =
                        match deferredDisposition with
                        | TerminalFlowDeferredOutcomeEnqueued -> "enqueued", 0u, 0u, "none", "none"
                        | TerminalFlowDeferredOutcomeDuplicate -> "duplicate", 0u, 0u, "none", "none"
                        | TerminalFlowDeferredOutcomeEquivalentObserverCoalesced(existingRef, incomingRef) ->
                            "equivalent_observer_coalesced", existingRef, incomingRef, "Observer", "Observer"
                        | TerminalFlowDeferredOutcomeRetainedExistingClass(existingRef, incomingRef, existingClass, incomingClass) ->
                            "retained_existing_candidate_class", existingRef, incomingRef, terminalFlowPendingCandidateClassText existingClass, terminalFlowPendingCandidateClassText incomingClass
                        | TerminalFlowDeferredOutcomeReplacedByIncomingClass(existingRef, incomingRef, existingClass, incomingClass) ->
                            "replaced_by_incoming_candidate_class", existingRef, incomingRef, terminalFlowPendingCandidateClassText existingClass, terminalFlowPendingCandidateClassText incomingClass
                        | TerminalFlowDeferredOutcomeConflict(existingRef, incomingRef, existingClass, incomingClass) ->
                            "conflict_same_candidate_class_incompatible_lineage", existingRef, incomingRef, terminalFlowPendingCandidateClassText existingClass, terminalFlowPendingCandidateClassText incomingClass
                    let deferredMailboxWakeRequested =
                        match deferredDisposition with
                        | TerminalFlowDeferredOutcomeEnqueued
                        | TerminalFlowDeferredOutcomeReplacedByIncomingClass _ -> true
                        | TerminalFlowDeferredOutcomeDuplicate
                        | TerminalFlowDeferredOutcomeEquivalentObserverCoalesced _
                        | TerminalFlowDeferredOutcomeRetainedExistingClass _
                        | TerminalFlowDeferredOutcomeConflict _ -> false
                    let deferredMailboxWakePublished, mailboxPublicationRef =
                        if deferredMailboxWakeRequested then
                            terminalFlowPublishDeferredOutcomeMailboxOnce pending
                        else
                            false, 0u
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_flow_global_outcome_candidate_deferred\",\"terminal_outcome_ref\":%u,\"fill_ref\":%u,\"root_receipt_ref\":%u,\"reason_ref\":%u,\"pending_intent\":%s,\"ingress_disposition_du\":%s,\"pending_dispatch_authority_du\":%s,\"pending_dispatch_authority_ref\":%u,\"dispatch_consumable\":false,\"deferred_disposition_du\":%s,\"conflict_existing_ref\":%u,\"conflict_incoming_ref\":%u,\"existing_candidate_class_du\":%s,\"incoming_candidate_class_du\":%s,\"numeric_rank_authority_retired\":true,\"mailbox_wake_requested\":%b,\"mailbox_wake_published\":%b,\"mailbox_publication_ref\":%u,\"reducer_quiescence_du\":%s,\"delivery_du\":\"ReducerOwnedDeferredPlusExactOnceTerminalPriorityMailboxWake\",\"authority\":\"typed_pending_candidate_class_plus_mailbox_liveness\",\"next\":\"await_native_executable_candidate_or_reducer_reconciliation\"}" [| box (terminalFlowPendingTerminalReceiptDigest pending); box (terminalFlowPendingFillDigest pending); box (terminalFlowRootReceiptRefText rootReceiptId); box (terminalFlowMintedRefOf "reason_ref" reason); box (DiagJson.esc (terminalFlowPendingIntentText pendingIntent)); box (DiagJson.esc (terminalFlowOutcomeCandidateIngressDispositionText ingressDisposition)); box (DiagJson.esc (terminalFlowPendingDispatchAuthorityText pending.dispatchAuthority)); box (terminalFlowPendingDispatchAuthorityRef pending.dispatchAuthority); box (DiagJson.esc deferredDispositionText); box conflictExistingRef; box conflictIncomingRef; box (DiagJson.esc existingCandidateClass); box (DiagJson.esc incomingCandidateClass); box deferredMailboxWakeRequested; box deferredMailboxWakePublished; box mailboxPublicationRef; box (DiagJson.esc reducerQuiescenceText) |])

                )

        [<StructuralEquality; NoComparison>]
        type private TerminalFlowInstalledBuildOkRedriveIdentity = {
            terminalReceiptRef : TerminalFlowIdentityRef<TerminalFlowTerminalReceiptRefKind>
            fillKey : TerminalFlowFillKeyId
            reducerRevision : int64
        }

        let private terminalFlowInstalledBuildOkRedriveRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<TerminalFlowInstalledBuildOkRedriveIdentity,byte>()

        let terminalFlowGlobalRedriveInstalledBuildOk allowCrossKindReplayCheck reason =
            let installedSnapshot =
                lock terminalFlowGlobalReducerProjectionGate (fun () ->
                    match terminalFlowGlobalReducerProjectionMirror.pendingTerminal,
                          terminalFlowOutcomeInstallationAdmission terminalFlowGlobalReducerProjectionMirror.outcomeInstallation with
                    | TerminalFlowPendingSlotCandidate pending, Some installed
                        when pending.intent = TerminalFlowPendingBuildOk
                             && installed.terminalReceiptRef = pending.terminalReceiptRef
                             && installed.fillKey = pending.fillKeyId ->
                        Some(pending, terminalFlowGlobalReducerProjectionMirror.revision)
                    | _ -> None)
            match installedSnapshot with
            | Some(pending, reducerRevision) ->
                let strandedCrossKind =
                    if allowCrossKindReplayCheck then
                        EvalWorklist.crossKindReplayHotSnapshotNow ()
                        |> Option.filter (fun snapshot -> snapshot.repeatCount >= 8L && snapshot.ageMs >= 12000L)
                    else None
                match strandedCrossKind with
                | Some snapshot ->
                    let failureReceiptId = sprintf "cross-kind-missing-prefetch:%s" snapshot.obligationId
                    let failureFillKey = sprintf "cross-kind-missing-prefetch-fill:%s" snapshot.obligationId
                    let failureMessage =
                        FastRuntimeFormat.format "CrossKindMissingAfterPrefetchFailClosed(obligation=%s|source=%s|target=%s|target_node=%s|repeat=%d|age_ms=%d)" [| box snapshot.obligationId; box snapshot.sourceSite; box snapshot.targetSite; box snapshot.targetNode; box snapshot.repeatCount; box snapshot.ageMs |]
                    let delivery =
                        DiagJson.publishTerminalOutcomeCandidate
                            DiagJson.TerminalOutcomeCandidateFailClosed
                            failureReceiptId
                            failureFillKey
                            failureMessage
                    let terminalRef = terminalFlowMintedRefOf "terminal_outcome_ref" failureReceiptId
                    let fillRef = terminalFlowMintedRefOf "fill_ref" failureFillKey
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_cross_kind_missing_prefetch_fail_closed_requested\",\"terminal_ref\":%u,\"fill_ref\":%u,\"reducer_revision\":%d,\"obligation_id\":%s,\"obligation_repeat\":%d,\"obligation_age_ms\":%d,\"source_site\":%s,\"target_site\":%s,\"target_node\":%s,\"delivery_du\":%s,\"cross_kind_replay_check_authority\":\"typed_redrive_reason_du\",\"diagnostic_reason_authority\":false,\"source_site_authority\":false,\"target_site_authority\":false,\"authority\":\"typed_cross_kind_bounded_failure\",\"next\":\"replace_buildok_with_failclosed_then_seed_qap_fixpoint\"}" [| box terminalRef; box fillRef; box reducerRevision; box (DiagJson.esc snapshot.obligationId); box snapshot.repeatCount; box snapshot.ageMs; box (DiagJson.esc snapshot.sourceSite); box (DiagJson.esc snapshot.targetSite); box (DiagJson.esc snapshot.targetNode); box (DiagJson.esc (DiagJson.terminalOutcomeCandidateDeliveryDecisionText delivery)) |])
                    Some(true, reducerRevision, terminalRef, fillRef)
                | None ->
                    let terminalRef = terminalFlowIdentityRefDigest pending.terminalReceiptRef
                    let fillRef = TerminalFlowFillKeyId.digest pending.fillKeyId
                    let redriveIdentity : TerminalFlowInstalledBuildOkRedriveIdentity =
                        { terminalReceiptRef = pending.terminalReceiptRef
                          fillKey = pending.fillKeyId
                          reducerRevision = reducerRevision }
                    let redriveKeyText =
                        FastRuntimeFormat.format "%s|%u|%u|%d" [| box reason; box terminalRef; box fillRef; box reducerRevision |]
                    let published = terminalFlowInstalledBuildOkRedriveRegistry.TryAdd(redriveIdentity, 0uy)
                    if published then
                        terminalFlowGlobalServerPublish (TerminalFlowGlobalServerTerminalOutcomeReady pending)
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_installed_buildok_redrive_requested\",\"terminal_ref\":%u,\"fill_ref\":%u,\"reducer_revision\":%d,\"reason\":%s,\"dedupe_first_seen\":true,\"redrive_key_ref\":%u,\"redrive_identity_du\":\"terminal_receipt_plus_fill_plus_reducer_revision\",\"reason_identity_authority\":false,\"diagnostic_text_authority\":false,\"authority\":\"installed_buildok_reducer_mailbox_redrive\",\"next\":\"reassess_qap_or_consume_handoff\"}" [| box terminalRef; box fillRef; box reducerRevision; box (DiagJson.esc reason); box (terminalFlowMintedRefOf "installed_buildok_redrive_key_ref" redriveKeyText) |])
                    Some(published, reducerRevision, terminalRef, fillRef)
            | None -> None

        let private terminalFlowGlobalReducerExitCodeSnapshot () =
            lock terminalFlowGlobalReducerProjectionGate (fun () ->
                match terminalFlowGlobalReducerProjectionMirror.reducerTerminalSeal with
                | TerminalFlowReducerTerminalSealAwaitStageToken -> None
                | TerminalFlowReducerTerminalSealPhysicalExitSelected chain
                | TerminalFlowReducerTerminalSealFailClosedSelected chain ->
                    if terminalFlowReducerProcessExitAllowed chain then Some chain.exitCode else None)

        let private terminalFlowGlobalReducerQuiescenceSnapshot () =
            let waitStartedAtMs = Environment.TickCount64
            lock terminalFlowGlobalReducerProjectionGate (fun () ->
                let waitedMs = max 0L (Environment.TickCount64 - waitStartedAtMs)
                match terminalFlowGlobalReducerProjectionMirror.reducerQuiescence with
                | TerminalFlowReducerIdle committedRevision ->
                    "Idle", 0u, 0L, committedRevision, waitedMs
                | TerminalFlowReducerProcessing(eventRef, startedAtMs, revisionBefore) ->
                    "Processing", eventRef, max 0L (Environment.TickCount64 - startedAtMs), revisionBefore, waitedMs)

        let terminalFlowGlobalReconcileHostReturnThroughReducer () =
            match terminalFlowGlobalReducerExitCodeSnapshot () with
            | Some exitCode -> Some exitCode
            | None ->
                let observedAtMs = Environment.TickCount64
                // Acquiring the reducer gate is the shutdown join.  An in-flight QAP
                // transaction must commit and return the state to Idle before this
                // snapshot can be observed.
                let quiescenceState, inflightEventRef, inflightAgeMs, committedRevision, quiescenceWaitMs =
                    terminalFlowGlobalReducerQuiescenceSnapshot ()
                let root = DiagJson.canonicalRootAuthoritySnapshot()
                let rootRef = terminalFlowRootReceiptRefText root.receiptId
                let request =
                    { requestRef = terminalFlowIdentityRefOfText (sprintf "host-return:%u:%d" rootRef observedAtMs)
                      reason = TerminalFlowHostShutdownProcessExit
                      observedAtMs = observedAtMs
                      rootReceiptRef = Some rootRef
                      terminalOutcomeRef = None }
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_host_shutdown_reducer_joined\",\"shutdown_request_id\":%u,\"reducer_quiescence_state_du\":%s,\"inflight_reducer_event_id\":%u,\"inflight_event_age_ms\":%d,\"last_committed_state_revision\":%d,\"quiescence_wait_ms\":%d,\"authority\":\"host_shutdown_joins_single_reducer_before_reconciliation\"}" [| box (terminalFlowIdentityRefDigest request.requestRef); box (DiagJson.esc quiescenceState); box inflightEventRef; box inflightAgeMs; box committedRevision; box quiescenceWaitMs |])
                let actorResult =
                    CompilerKernelV2.CompilerRuntimeKernel.runHostBoundary
                        "terminal-flow-host-return"
                        (job {
                            let reply =
                                CompilerKernelV2.CompilerRuntimeKernel.oneShot<int option>
                                    "terminal-flow-host-return-reply"
                            do!
                                CompilerKernelV2.CompilerRuntimeKernel.send
                                    terminalFlowGlobalServerControlChannel
                                    (TerminalFlowReducerActorReconcileHostReturn(request, reply))
                            return!
                                CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
                        })
                match actorResult with
                | Some exitCode -> Some exitCode
                | None ->
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_host_return_reducer_invariant_failed\",\"request_ref\":%u,\"root_ref\":%u,\"observed_at_ms\":%d,\"run_end_emitted\":false,\"physical_exit_receipt_missing\":true,\"direct_exit_fallback\":false,\"legacy_failclosed_command\":false,\"authority\":\"single_reducer_actor\"}" [| box (terminalFlowIdentityRefDigest request.requestRef); box rootRef; box observedAtMs |])
                    None

        // Job-composed reconciliation is the only path legal from compiler jobs.
        // Host callers may still use the synchronous wrapper above after leaving Hopac.
        let terminalFlowGlobalReconcileHostReturnThroughReducerJob () : Hopac.Job<int option> =
            job {
                match terminalFlowGlobalReducerExitCodeSnapshot () with
                | Some exitCode -> return Some exitCode
                | None ->
                    let observedAtMs = Environment.TickCount64
                    let quiescenceState, inflightEventRef, inflightAgeMs, committedRevision, quiescenceWaitMs =
                        terminalFlowGlobalReducerQuiescenceSnapshot ()
                    let root = DiagJson.canonicalRootAuthoritySnapshot()
                    let rootRef = terminalFlowRootReceiptRefText root.receiptId
                    let request =
                        { requestRef = terminalFlowIdentityRefOfText (sprintf "host-return-job:%u:%d" rootRef observedAtMs)
                          reason = TerminalFlowHostShutdownProcessExit
                          observedAtMs = observedAtMs
                          rootReceiptRef = Some rootRef
                          terminalOutcomeRef = None }
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_host_shutdown_reducer_join_job_composed\",\"shutdown_request_id\":%u,\"reducer_quiescence_state_du\":%s,\"inflight_reducer_event_id\":%u,\"inflight_event_age_ms\":%d,\"last_committed_state_revision\":%d,\"quiescence_wait_ms\":%d,\"authority\":\"hopac_job_composed_single_reducer_reconciliation\"}" [| box (terminalFlowIdentityRefDigest request.requestRef); box (DiagJson.esc quiescenceState); box inflightEventRef; box inflightAgeMs; box committedRevision; box quiescenceWaitMs |])
                    let reply =
                        CompilerKernelV2.CompilerRuntimeKernel.oneShot<int option>
                            "terminal-flow-host-return-job-reply"
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.send
                            terminalFlowGlobalServerControlChannel
                            (TerminalFlowReducerActorReconcileHostReturn(request, reply))
                    let! result =
                        CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
                    return result
            }

        // Terminal-flow actors, publishers and startup receipts are installed only by
        // startTerminalFlowRuntimeInProcess after the typed in-process session activation.

        let rec private terminalFlowSchedulerPushLoop
            (channel:CompilerKernelV2.PortableMailbox<TerminalFlowSchedulerPushDispatch>)
            : Hopac.Job<unit> =
            job {
                let! dispatch = CompilerKernelV2.CompilerRuntimeKernel.take channel
                let eventCode = (terminalFlowSchedulerChannelCommandShapeFor dispatch.event).eventCode
                let possessionDepth = terminalFlowPushPossessionDepth dispatch.channelAuthority.possession
                let possessionDigest = terminalFlowPushPossessionDigest dispatch.channelAuthority.possession
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_push\",\"event_code\":%d,\"tag_ref\":%u,\"dispatch_ref\":%u,\"admission_ref\":%u,\"admission_identity_ref\":%u,\"actor_binding_ref\":%u,\"credential_ledger_ref\":%u,\"fairness_epoch_ref\":%u,\"scheduler_release_ref\":%u,\"waker_registry_ref\":%u,\"possession_depth\":%d,\"possession_ref\":%u,\"polling_authority\":false,\"authority\":\"admission_indexed_scheduler_channel_possession\"}" [| box eventCode; box (terminalFlowMintedRefOf "scheduler_tag_ref" dispatch.tag); box (terminalFlowMintedRefOf "dispatch_ref" dispatch.dispatchId); box dispatch.channelAuthority.context.admissionRef; box dispatch.channelAuthority.context.admissionIdentityRef; box dispatch.channelAuthority.context.actorBindingRef; box dispatch.channelAuthority.context.credentialLedgerRef; box dispatch.channelAuthority.context.fairnessEpochRef; box (terminalFlowIdentityRefDigest dispatch.channelAuthority.context.schedulerRelease.physicalReleaseRef); box dispatch.channelAuthority.ledger.wakerRegistration.registryRef; box possessionDepth; box possessionDigest |])
                let forward event =
                    let nextRoot, nextAuthority, nextWakerRegistration =
                        terminalFlowSchedulerChannelRootAdvance dispatch.channelAuthority event
                    let channelLedger = nextRoot.ledger
                    let nextPossession = nextRoot.possession
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_channel_possession_advanced\",\"step_du\":%s,\"admission_ref\":%u,\"admission_identity_ref\":%u,\"actor_binding_ref\":%u,\"credential_ledger_ref\":%u,\"fairness_epoch_ref\":%u,\"scheduler_release_ref\":%u,\"actor_command_ref\":%u,\"stage_token_ref\":%u,\"waker_registry_ref\":%u,\"worker_handoff_ref\":%u,\"exact_once_ref\":%u,\"channel_revision\":%d,\"channel_exact_once_ref\":%u,\"channel_root_ref\":%u,\"channel_root_exact_once_ref\":%u,\"possession_depth\":%d,\"authority\":\"sealed_channel_root_transaction\"}" [| box (DiagJson.esc (terminalFlowSchedulerChannelStepKindText nextAuthority.kind)); box nextAuthority.admissionRef; box nextAuthority.admissionIdentityRef; box nextAuthority.actorBindingRef; box nextAuthority.credentialLedgerRef; box nextAuthority.fairnessEpochRef; box nextAuthority.schedulerReleaseRef; box nextAuthority.actorCommandRef; box nextAuthority.stageTokenRef; box nextAuthority.wakerRegistryRef; box nextAuthority.workerHandoffRef; box nextAuthority.exactOnceRef; box channelLedger.possessionRevision; box channelLedger.exactOnceRef; box nextRoot.rootRef; box nextRoot.exactOnceRef; box (terminalFlowPushPossessionDepth nextPossession) |])
                    match event with
                    | TerminalFlowPushWriterCompleted _ ->
                        let handoff =
                            channelLedger.workerHandoff
                            |> Option.defaultWith (fun () -> invalidOp "worker completion advanced without a handoff receipt")
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_worker_handoff_completed\",\"admission_ref\":%u,\"admission_identity_ref\":%u,\"actor_binding_ref\":%u,\"credential_ledger_ref\":%u,\"fairness_epoch_ref\":%u,\"scheduler_release_ref\":%u,\"worker_handoff_ref\":%u,\"worker_job_ref\":%u,\"artifact_receipt_ref\":%u,\"exit_witness_ref\":%u,\"waker_registry_ref\":%u,\"channel_root_ref\":%u,\"exact_once_ref\":%u,\"authority\":\"sealed_channel_root_transaction\"}" [| box handoff.admissionRef; box handoff.admissionIdentityRef; box handoff.actorBindingRef; box handoff.credentialLedgerRef; box handoff.fairnessEpochRef; box handoff.schedulerReleaseRef; box handoff.workerHandoffRef; box handoff.workerJobRef; box handoff.artifactReceiptRef; box handoff.exitWitnessRef; box nextWakerRegistration.registryRef; box nextRoot.rootRef; box handoff.exactOnceRef |])
                    | TerminalFlowPushRegistryPrune _ ->
                        let handoff =
                            channelLedger.workerHandoff
                            |> Option.defaultWith (fun () -> invalidOp "registry prune advanced without a worker handoff")
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_channel_committed\",\"admission_ref\":%u,\"context_ref\":%u,\"scheduler_release_ref\":%u,\"waker_registry_ref\":%u,\"waker_consumed\":%b,\"worker_handoff_ref\":%u,\"channel_root_ref\":%u,\"channel_root_exact_once_ref\":%u,\"possession_ref\":%u,\"authority\":\"sealed_channel_root_terminal_receipt\"}" [| box nextRoot.context.admissionRef; box nextRoot.context.contextRef; box (terminalFlowIdentityRefDigest nextRoot.context.schedulerRelease.physicalReleaseRef); box nextWakerRegistration.registryRef; box (nextWakerRegistration.state = TerminalFlowSchedulerWakerConsumed); box handoff.workerHandoffRef; box nextRoot.rootRef; box nextRoot.exactOnceRef; box (terminalFlowPushPossessionDigest nextPossession) |])
                    | _ -> ()
                    job {
                        let nextEventCode = (terminalFlowSchedulerChannelCommandShapeFor event).eventCode
                        // The portable mailbox remains a synchronous rendezvous. Queue the
                        // producer as an owned portable effect so the sole consumer can return
                        // to chooseTake before the next possession step commits.
                        let forwardEffect =
                            CompilerKernelV2.CompilerRuntimeKernel.effect
                                "terminal-scheduler-channel-forward"
                                (CompilerKernelV2.CompilerRuntimeKernel.send
                                    channel
                                    { dispatch with event = event; channelAuthority = nextRoot })
                        do! CompilerKernelV2.CompilerRuntimeKernel.start forwardEffect
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_channel_forward_queued\",\"from_event_code\":%d,\"to_event_code\":%d,\"channel_revision\":%d,\"channel_root_ref\":%u,\"possession_depth\":%d,\"forward_du\":\"AsyncProducerUntilSameActorNextReceive\",\"polling_authority\":false,\"threadpool_authority\":false,\"authority\":\"hopac_scheduler_rendezvous\"}" [| box eventCode; box nextEventCode; box channelLedger.possessionRevision; box nextRoot.rootRef; box (terminalFlowPushPossessionDepth nextPossession) |])
                        return ()
                    }
                let publishActorProgress
                    (requestedPhase:DiagJson.TerminalSchedulerPushActorPhase)
                    (requestedFillKey:TerminalFlowFillKeyId)
                    (receiptId:string)
                    (commandRef:uint32)
                    (reason:string) =
                    let snapshot = DiagJson.terminalSchedulerPushActorSnapshot()
                    let requestedFillKeyText = TerminalFlowFillKeyId.text requestedFillKey
                    terminalFlowGlobalServerPublish (TerminalFlowGlobalServerActorProjectionObserved snapshot)
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"scheduler_push_actor_possession\",\"owned_phase_du\":%s,\"requested_phase_du\":%s,\"phase_matches\":%b,\"owned_fill_ref\":%u,\"requested_fill_ref\":%u,\"fill_matches\":%b,\"receipt_ref\":%u,\"dispatch_ref\":%u,\"actor_command_ref\":%u,\"reason\":%s,\"global_server_event\":true,\"authority\":\"push_actor_snapshot_only\"}" [| box (DiagJson.esc (DiagJson.terminalSchedulerPushActorPhaseText snapshot.phase)); box (DiagJson.esc (DiagJson.terminalSchedulerPushActorPhaseText requestedPhase)); box (snapshot.phase = requestedPhase); box (terminalFlowMintedRefOf "owned_actor_fill_ref" snapshot.fillKey); box (terminalFlowMintedRefOf "requested_actor_fill_ref" requestedFillKeyText); box (snapshot.fillKey = requestedFillKeyText); box (terminalFlowMintedRefOf "scheduler_actor_receipt_ref" receiptId); box (terminalFlowMintedRefOf "owned_actor_dispatch_ref" snapshot.dispatchId); box commandRef; box (DiagJson.esc reason) |])
                match dispatch.event with
                | TerminalFlowPushResolvedOutcome prepared ->
                    let requestedEnvelope = prepared.envelope
                    let! filledCell, fillReceipt, resolvedEnvelope = terminalFlowOutcomeFillOnceJob prepared.cell requestedEnvelope
                    let fillDecision = if fillReceipt.firstFill then TerminalFlowOutcomeFillOnceReady else TerminalFlowOutcomeAlreadyFilled
                    let stickySnapshot = terminalFlowStickyTailSnapshotForGate resolvedEnvelope.stickyTailGate
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_outcome_ivar_fill_decision\",\"decision_du\":%s,\"cell_ref\":%u,\"fill_ref\":%u,\"receipt_ref\":%u,\"owner_transaction_ref\":%u,\"first_fill\":%b,\"waker_registration_status\":%s,\"procedural_residual_drain_pass_count\":%d,\"material_delta_on_procedural_pass\":%d,\"authority\":\"scheduler_push_exact_once_ivar\"}" [| box (DiagJson.esc (terminalFlowOutcomeFillDecisionText fillDecision)); box (terminalFlowMintedRefOf "terminal_outcome_cell_ref" fillReceipt.cellId); box (terminalFlowMintedRefOf "terminal_outcome_fill_ref" (TerminalFlowFillKeyId.text fillReceipt.fillKey)); box (terminalFlowMintedRefOf "terminal_outcome_receipt_ref" fillReceipt.receiptId); box (terminalFlowMintedRefOf "terminal_outcome_owner_transaction_ref" fillReceipt.ownerTransactionId); box fillReceipt.firstFill; box (DiagJson.esc (terminalFlowWakerRegistryVerdictText (terminalFlowWakerRegistryVerdictFor TerminalFlowWakerRegistryStickyTail stickySnapshot.wakerStatus))); box stickySnapshot.proceduralDrainPassCount; box stickySnapshot.materialDeltaOnProceduralPass |])
                    if filledCell.cellId <> fillReceipt.cellId
                       || resolvedEnvelope.terminalReceiptRef <> requestedEnvelope.terminalReceiptRef
                       || resolvedEnvelope.ownerClosure.transaction.transactionId <> requestedEnvelope.ownerClosure.transaction.transactionId then
                        let reason =
                            "terminal_outcome_ivar_fill_conflict|requested_receipt=" + terminalFlowIdentityRefText requestedEnvelope.terminalReceiptRef
                            + "|resolved_receipt=" + terminalFlowIdentityRefText resolvedEnvelope.terminalReceiptRef
                            + "|requested_tx=" + requestedEnvelope.ownerClosure.transaction.transactionId
                            + "|resolved_tx=" + resolvedEnvelope.ownerClosure.transaction.transactionId
                        do! forward (terminalFlowPushFailClosed requestedEnvelope.fillKey reason)
                    else
                        match terminalFlowSealedTokenForDispatch dispatch.dispatchId resolvedEnvelope with
                        | Error reason ->
                            do! forward (terminalFlowPushFailClosed resolvedEnvelope.fillKey reason)
                        | Ok sealedToken ->
                            DiagJson.emit (
                                sprintf "{\"kind\":\"terminal_stage_token\",\"stage\":\"sealed\",\"token\":%s,\"actor_phase\":\"OutcomeFilled\",\"waker_edge_owned_by_actor\":true}"
                                    (DiagJson.esc (terminalFlowTerminalStageTokenText "sealed" sealedToken)))
                            let filledTransition = terminalFlowOutcomeFilledTransitionFor sealedToken.tokenId dispatch.dispatchId fillReceipt
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_outcome_filled\",\"terminal_stage_token_state_du\":\"OutcomeFilled\",\"terminal_stage_token_id\":%s,\"terminal_outcome_fill_key\":%s,\"terminal_outcome_receipt_id\":%s,\"outcome_fill_attempted\":true,\"outcome_fill_result_du\":%s,\"fill_receipt_ref\":%u,\"dispatch_ref\":%u,\"waker_requirement_ref\":%u,\"waker_edge_ref\":%u,\"actor_phase_after_du\":\"OutcomeFilled\",\"authority\":\"push_actor_possession_spine\"}" [| box (DiagJson.esc filledTransition.stageTokenId); box (DiagJson.esc (TerminalFlowFillKeyId.text filledTransition.fillKey)); box (DiagJson.esc (terminalFlowIdentityRefText filledTransition.terminalReceiptRef)); box (DiagJson.esc (terminalFlowOutcomeFillDecisionText fillDecision)); box filledTransition.fillReceiptRef; box filledTransition.dispatchRef; box sealedToken.wakerEdge.requirementRef; box sealedToken.wakerEdge.edgeRef |])
                            let filled : TerminalFlowCommitFilled =
                                { prepared = { prepared with envelope = resolvedEnvelope }
                                  filledCell = filledCell
                                  fillReceipt = fillReceipt
                                  sealedToken = sealedToken }
                            let command =
                                DiagJson.PushActorRecordOutcomeFilled(
                                    filledTransition.fillReceiptRef,
                                    terminalFlowMintedRefOf "terminal_stage_token_ref" sealedToken.tokenId,
                                    sealedToken.wakerEdge.edgeRef)
                            do! DiagJson.terminalSchedulerPushActorApplyJob command
                            publishActorProgress
                                DiagJson.PushActorOutcomeFilled
                                resolvedEnvelope.fillKey
                                filled.fillReceipt.receiptId
                                (terminalFlowMintedRefOf "push_actor_command_progress_ref" (DiagJson.terminalSchedulerPushActorCommandStableText command))
                                "terminal_outcome_ivar_filled_push_owned_stage_token_minted"
                            do! forward (TerminalFlowPushOutcomeFilled filled)
                | TerminalFlowPushOutcomeFilled filled ->
                    let resolvedEnvelope : TerminalFlowResolvedOutcomeEnvelope = filled.prepared.envelope
                    match terminalFlowWriterCapabilityForEnvelope resolvedEnvelope with
                    | Error reason -> do! forward (terminalFlowPushFailClosed resolvedEnvelope.fillKey reason)
                    | Ok writer ->
                        let filledTransition = terminalFlowOutcomeFilledTransitionFor filled.sealedToken.tokenId dispatch.dispatchId filled.fillReceipt
                        let writerBoundTransition = terminalFlowWriterBoundTransitionFor filledTransition writer
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_writer_capability_bound\",\"terminal_stage_token_state_du\":\"WriterBound\",\"terminal_stage_token_id\":%s,\"writer_capability_ref\":%u,\"writer_lease_id\":%s,\"owner_transaction_ref\":%u,\"filled_receipt_ref\":%u,\"actor_phase_after_du\":\"WriterBound\",\"authority\":\"hopac_writer_capability_bind\"}" [| box (DiagJson.esc writerBoundTransition.filled.stageTokenId); box writerBoundTransition.writerCapabilityRef; box (DiagJson.esc writerBoundTransition.writerLeaseId); box (terminalFlowMintedRefOf "owner_transaction_ref" writerBoundTransition.ownerTransactionId); box writerBoundTransition.filled.fillReceiptRef |])
                        let command = DiagJson.PushActorRecordWriterBound writerBoundTransition.writerCapabilityRef
                        do! DiagJson.terminalSchedulerPushActorApplyJob command
                        publishActorProgress
                            DiagJson.PushActorWriterBound
                            resolvedEnvelope.fillKey
                            filled.fillReceipt.receiptId
                            (terminalFlowMintedRefOf "push_actor_command_progress_ref" (DiagJson.terminalSchedulerPushActorCommandStableText command))
                            "writer_capability_bound_by_push_actor"
                        do! forward (TerminalFlowPushWriterCapabilityBound { filled = filled; writer = writer })
                | TerminalFlowPushWriterCapabilityBound bound ->
                    do! forward (TerminalFlowPushArtifactCommitRequested bound)
                | TerminalFlowPushArtifactCommitRequested bound ->
                    let! writerReceipt = terminalFlowWriterJob dispatch bound.writer
                    match writerReceipt.artifactReceipt.authorization, writerReceipt.artifactReceipt.execution with
                    | TerminalFlowArtifactsAuthorizedByNativeRootComplete _, TerminalFlowArtifactsExecuted _
                    | TerminalFlowArtifactsAuthorizedByTerminalFailure _, TerminalFlowArtifactsTerminalFailureProjected _ ->
                        let envelope = bound.filled.prepared.envelope
                        match terminalFlowConsumeSealedToken bound.filled.sealedToken writerReceipt with
                        | Error reason ->
                            do! forward (terminalFlowPushFailClosed envelope.fillKey reason)
                        | Ok consumedToken ->
                            let exitWitness = terminalFlowExitWitnessForConsumedToken consumedToken writerReceipt
                            let filledTransition = terminalFlowOutcomeFilledTransitionFor bound.filled.sealedToken.tokenId dispatch.dispatchId bound.filled.fillReceipt
                            let writerBoundTransition = terminalFlowWriterBoundTransitionFor filledTransition bound.writer
                            let committedTransition = terminalFlowReceiptCommittedTransitionFor writerBoundTransition writerReceipt exitWitness
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_commit_receipt\",\"terminal_stage_token_state_du\":\"ReceiptCommitted\",\"terminal_stage_token_id\":%s,\"writer_job_ref\":%u,\"artifact_receipt_ref\":%u,\"exit_witness_ref\":%u,\"terminal_commit_receipt_emitted\":true,\"terminal_physical_exit_witness_id\":%s,\"actor_phase_after_du\":\"ArtifactsCommitted\",\"authority\":\"hopac_writer_artifact_commit\"}" [| box (DiagJson.esc committedTransition.writerBound.filled.stageTokenId); box committedTransition.writerJobRef; box committedTransition.artifactReceiptRef; box committedTransition.exitWitnessRef; box (DiagJson.esc exitWitness.witnessId) |])
                            DiagJson.emit (
                                sprintf "{\"kind\":\"terminal_stage_token\",\"stage\":\"consumed\",\"token\":%s,\"exit_witness\":%s}"
                                    (DiagJson.esc (terminalFlowTerminalStageTokenText "consumed" consumedToken))
                                    (DiagJson.esc (terminalFlowExitWitnessText exitWitness)))
                            let command = DiagJson.PushActorRecordArtifactsCommitted committedTransition.artifactReceiptRef
                            do! DiagJson.terminalSchedulerPushActorApplyJob command
                            publishActorProgress
                                DiagJson.PushActorArtifactsCommitted
                                envelope.fillKey
                                (terminalFlowIdentityRefText envelope.terminalReceiptRef)
                                (terminalFlowMintedRefOf "push_actor_command_progress_ref" (DiagJson.terminalSchedulerPushActorCommandStableText command))
                                "artifact_commit_completed_push_owned_waker_consumed"
                            do! forward (TerminalFlowPushWriterCompleted { bound = bound; writerReceipt = writerReceipt; consumedToken = consumedToken; exitWitness = exitWitness })
                    | _ ->
                        let envelope = bound.filled.prepared.envelope
                        do! forward (terminalFlowPushFailClosed envelope.fillKey "native_writer_artifact_commit_rejected")
                | TerminalFlowPushWriterCompleted completed ->
                    let envelope = completed.bound.filled.prepared.envelope
                    do! forward (TerminalFlowPushRegistryPrune(envelope.fillKey, completed))
                | TerminalFlowPushRegistryPrune(fillKey, completed) ->
                    terminalFlowGlobalDispatchRequestPrune (TerminalFlowFillKeyId.text fillKey)
                    terminalFlowOutcomeRegistryPrune fillKey
                    let artifactPruneReceipt = terminalFlowArtifactCommitRegistryPrune completed.bound.writer.artifactPlan.nativeBridge.cellId
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_artifact_commit_registry_prune\",\"native_cell_id\":%s,\"request_id\":%s,\"prune_kind_du\":%s,\"exact_once_ref\":%u,\"authority\":\"scheduler_channel_root_registry_prune\"}" [| box (DiagJson.esc artifactPruneReceipt.nativeCellId); box (DiagJson.esc artifactPruneReceipt.requestId); box (DiagJson.esc (terminalFlowArtifactCommitRegistryPruneKindText artifactPruneReceipt.kind)); box artifactPruneReceipt.exactOnceRef |])
                    let prunedReceipt =
                        { completed.writerReceipt with
                            registryLifecycle = TerminalFlowRegistryPruned fillKey }
                    let prunedCompleted = { completed with writerReceipt = prunedReceipt }
                    let writer = prunedCompleted.bound.writer
                    let handoff = TerminalFlowNativeHandoffCompleted prunedCompleted
                    let exitWitnessRef = terminalFlowMintedRefOf "exit_witness_ref" prunedCompleted.exitWitness.witnessId
                    let command = DiagJson.PushActorRecordExitWitness exitWitnessRef
                    do! DiagJson.terminalSchedulerPushActorApplyJob command
                    publishActorProgress
                        DiagJson.PushActorExitWitnessQueued
                        fillKey
                        (terminalFlowWriterTerminalReceiptText writer)
                        (terminalFlowMintedRefOf "push_actor_command_progress_ref" (DiagJson.terminalSchedulerPushActorCommandStableText command))
                        "writer_receipt_consumed_registries_pruned_exit_witness_owned"
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.tryFillOneShot
                            dispatch.completion
                            handoff
                    terminalFlowSchedulerPushRegistryPrune fillKey
                    let line = terminalFlowSchedulerPushPhysicalExitLine dispatch prunedCompleted
                    DiagJson.emit (
                        sprintf "{\"kind\":\"terminal_stage_token\",\"stage\":\"exit_witness\",\"token\":%s,\"exit_witness\":%s}"
                            (DiagJson.esc (terminalFlowTerminalStageTokenText "consumed" prunedCompleted.consumedToken))
                            (DiagJson.esc (terminalFlowExitWitnessText prunedCompleted.exitWitness)))
                    let filledTransition = terminalFlowOutcomeFilledTransitionFor prunedCompleted.consumedToken.tokenId dispatch.dispatchId prunedCompleted.bound.filled.fillReceipt
                    let writerBoundTransition = terminalFlowWriterBoundTransitionFor filledTransition writer
                    let committedTransition = terminalFlowReceiptCommittedTransitionFor writerBoundTransition prunedReceipt prunedCompleted.exitWitness
                    let doneTransition = terminalFlowDoneTransitionFor committedTransition
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_commit_receipt\",\"terminal_commit_receipt_kind_du\":\"WriterJobCommitReceipt\",\"terminal_stage_token_id\":%s,\"run_end_receipt_ref\":%u,\"writer_job_ref\":%u,\"artifact_receipt_ref\":%u,\"exit_witness_ref\":%u,\"terminal_total_order_du\":\"Committed\",\"predecessor_required\":true,\"polling_authority\":false}" [| box (DiagJson.esc filledTransition.stageTokenId); box doneTransition.runEndReceiptRef; box committedTransition.writerJobRef; box committedTransition.artifactReceiptRef; box committedTransition.exitWitnessRef |])
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_done_transition\",\"terminal_stage_token_state_du\":\"Done\",\"terminal_stage_token_id\":%s,\"run_end_receipt_ref\":%u,\"writer_job_ref\":%u,\"artifact_receipt_ref\":%u,\"exit_witness_ref\":%u,\"committed_to_done\":true,\"run_end_emitted\":false,\"capture_complete\":false,\"commit_exit_reduced_to_physical_boundary\":true,\"polling_authority\":false}" [| box (DiagJson.esc filledTransition.stageTokenId); box doneTransition.runEndReceiptRef; box committedTransition.writerJobRef; box committedTransition.artifactReceiptRef; box committedTransition.exitWitnessRef |])
                    let successOrigin =
                        TerminalFlowGlobalExitFromBreakthroughDone {
                            runEndReceiptRef = doneTransition.runEndReceiptRef
                            writerJobRef = committedTransition.writerJobRef
                            artifactReceiptRef = committedTransition.artifactReceiptRef
                            exitWitnessRef = committedTransition.exitWitnessRef
                            doneAtMs = doneTransition.doneAtMs
                        }
                    let physicalChain, finalActorPhase, exitOrigin =
                        match prunedReceipt.artifactReceipt.execution with
                        | TerminalFlowArtifactsExecuted _ ->
                            let chain =
                                TerminalFlowPhysicalExitWriterCommitted(
                                    terminalFlowDurableRefOfText writer.writerLeaseId,
                                    terminalFlowDurableRefOfText prunedReceipt.writerJobId,
                                    terminalFlowDurableRefOfText prunedCompleted.exitWitness.witnessId)
                            chain, DiagJson.PushActorConsumed, successOrigin
                        | TerminalFlowArtifactsTerminalFailureProjected(planId, failureManifestRef, reasonRef, reason, _) ->
                            let failureIdentity =
                                FastRuntimeFormat.format "writer_terminal_failure|plan=%s|manifest=%s|reason_ref=%u|reason=%s" [| box planId; box (terminalFlowIdentityRefText failureManifestRef); box reasonRef; box (CompilerKernelV2.OperationalReasonIdOps.text reason) |]
                            let chain =
                                TerminalFlowPhysicalExitTypedFailure(
                                    terminalFlowDurableRefOfText failureIdentity,
                                    terminalFlowDurableRefOfText prunedCompleted.exitWitness.witnessId)
                            chain, DiagJson.PushActorFailedClosed, terminalFlowTypedFailureOriginOfChain chain
                        | TerminalFlowArtifactsExecutionRejected(planId, reasonRef, reason) ->
                            let failureIdentity =
                                FastRuntimeFormat.format "writer_execution_rejected|plan=%s|reason_ref=%u|reason=%s" [| box planId; box reasonRef; box (CompilerKernelV2.OperationalReasonIdOps.text reason) |]
                            let chain =
                                TerminalFlowPhysicalExitTypedFailure(
                                    terminalFlowDurableRefOfText failureIdentity,
                                    terminalFlowDurableRefOfText prunedCompleted.exitWitness.witnessId)
                            chain, DiagJson.PushActorFailedClosed, terminalFlowTypedFailureOriginOfChain chain
                    let finalCommand =
                        match finalActorPhase with
                        | DiagJson.PushActorConsumed ->
                            DiagJson.PushActorRecordConsumed doneTransition.runEndReceiptRef
                        | DiagJson.PushActorFailedClosed ->
                            let failureReceiptRef = terminalFlowMintedRefOf "push_actor_failure_receipt_ref" (terminalFlowPhysicalExitChainText physicalChain)
                            let reasonText = physicalChain |> terminalFlowPhysicalExitChainReason |> DiagJson.terminalJsonPhysicalExitReasonText
                            let reasonRef = terminalFlowMintedRefOf "push_actor_failure_reason_ref" reasonText
                            DiagJson.PushActorRecordFailedClosed(failureReceiptRef, reasonRef)
                        | phase ->
                            invalidOp ("terminal writer classified into nonterminal actor phase: " + DiagJson.terminalSchedulerPushActorPhaseText phase)
                    do! DiagJson.terminalSchedulerPushActorApplyJob finalCommand
                    publishActorProgress
                        finalActorPhase
                        fillKey
                        (terminalFlowWriterTerminalReceiptText writer)
                        (terminalFlowMintedRefOf "push_actor_final_command_progress_ref" (DiagJson.terminalSchedulerPushActorCommandStableText finalCommand))
                        "physical_exit_classified_by_push_actor_receipt"
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_writer_completion_classified\",\"fill_ref\":%u,\"physical_chain_du\":%s,\"physical_chain_ref\":%u,\"final_actor_phase\":%s,\"exit_code\":%d,\"decision_authority\":\"push_actor_possession_spine\"}" [| box (TerminalFlowFillKeyId.digest fillKey); box (DiagJson.esc (physicalChain |> terminalFlowPhysicalExitChainReason |> DiagJson.terminalJsonPhysicalExitReasonText)); box (terminalFlowMintedRefOf "physical_chain_ref" (terminalFlowPhysicalExitChainText physicalChain)); box (DiagJson.esc (DiagJson.terminalSchedulerPushActorPhaseText finalActorPhase)); box prunedCompleted.exitWitness.exitCode |])
                    let exitRequestId =
                        "terminal-global-exit:" + prunedCompleted.exitWitness.witnessId
                    let exitRequest =
                        terminalFlowGlobalExitRequestCreate
                            exitRequestId
                            (TerminalFlowFillKeyId.text fillKey)
                            prunedCompleted.exitWitness.exitCode
                            finalActorPhase
                            line
                            physicalChain
                            exitOrigin
                    let commitObservation : TerminalFlowGlobalCommitObservation =
                        { fillKey = fillKey
                          terminalReceiptRef = writer.terminalReceiptRef
                          writerJobRef = TerminalFlowDurableRef committedTransition.writerJobRef
                          artifactReceiptRef = TerminalFlowDurableRef committedTransition.artifactReceiptRef
                          exitWitnessRef = TerminalFlowDurableRef committedTransition.exitWitnessRef
                          runEndReceiptRef = TerminalFlowDurableRef doneTransition.runEndReceiptRef
                          observedAtMs = Environment.TickCount64 }
                    do! terminalFlowGlobalServerPublishJob (TerminalFlowGlobalServerArtifactCommitObserved commitObservation)
                    do! terminalFlowGlobalServerPublishJob (TerminalFlowGlobalServerExitWitnessReady exitRequest)
                | TerminalFlowPushFailClosed(fillKey, reason) ->
                    let reasonText = CompilerKernelV2.OperationalReasonIdOps.text reason
                    let failureReceiptRef = terminalFlowMintedRefOf "push_actor_failure_receipt_ref" (dispatch.dispatchId + "|" + reasonText)
                    let reasonRef = terminalFlowMintedRefOf "push_actor_failure_reason_ref" reasonText
                    let command = DiagJson.PushActorRecordFailedClosed(failureReceiptRef, reasonRef)
                    do! DiagJson.terminalSchedulerPushActorApplyJob command
                    publishActorProgress
                        DiagJson.PushActorFailedClosed
                        fillKey
                        ""
                        (terminalFlowMintedRefOf "push_actor_command_progress_ref" (DiagJson.terminalSchedulerPushActorCommandStableText command))
                        "typed_fail_closed_owned_by_push_actor"
                    terminalFlowGlobalDispatchRequestPrune (TerminalFlowFillKeyId.text fillKey)
                    terminalFlowOutcomeRegistryPrune fillKey
                    let handoff = TerminalFlowNativeHandoffFailClosed(reason, TerminalFlowNativeSchedulerFailClosed reason)
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.tryFillOneShot
                            dispatch.completion
                            handoff
                    terminalFlowSchedulerPushRegistryPrune fillKey
                    let line =
                        FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_fail_closed\",\"event_code\":7,\"tag_ref\":%u,\"dispatch_ref\":%u,\"fill_ref\":%u,\"reason_ref\":%u}" [| box (terminalFlowMintedRefOf "scheduler_tag_ref" dispatch.tag); box (terminalFlowMintedRefOf "dispatch_ref" dispatch.dispatchId); box (TerminalFlowFillKeyId.digest fillKey); box (terminalFlowMintedRefOf "reason_ref" reasonText) |]
                    let physicalChain =
                        TerminalFlowPhysicalExitTypedFailure(
                            terminalFlowStageTokenFailureRefOfReason reasonText,
                            terminalFlowDurableRefOfText ("fail-closed-exit-witness:" + dispatch.dispatchId))
                    let exitRequestId =
                        "terminal-global-fail-closed:" + dispatch.dispatchId
                    let exitRequest =
                        terminalFlowGlobalExitRequestCreate
                            exitRequestId
                            (TerminalFlowFillKeyId.text fillKey)
                            1
                            DiagJson.PushActorFailedClosed
                            line
                            physicalChain
                            (terminalFlowTypedFailureOriginOfChain physicalChain)
                    terminalFlowGlobalServerPublish (TerminalFlowGlobalServerExitWitnessReady exitRequest)
                return! Hopac.Job.delay (fun () -> terminalFlowSchedulerPushLoop channel)
            }

        let private terminalFlowSchedulerPushChannel =
            CompilerKernelV2.CompilerRuntimeKernel.mailbox<TerminalFlowSchedulerPushDispatch>
                "terminal-scheduler-push"
                CompilerKernelV2.PortableControlLane
                0
                CompilerKernelV2.MailboxFailClosed

        type TerminalFlowRuntimeStartState =
            | TerminalFlowRuntimeCold
            | TerminalFlowRuntimeStarting of startedAtMs:int64
            | TerminalFlowRuntimeStarted of startedAtMs:int64
            | TerminalFlowRuntimeStartFailed of failedAtMs:int64 * reason:CompilerKernelV2.OperationalReasonId

        let private terminalFlowRuntimeStartGate = obj()
        let mutable private terminalFlowRuntimeStartState = TerminalFlowRuntimeCold

        let startTerminalFlowRuntimeInProcess () =
            CompilerRuntimeActivation.requireInProcessEntered "terminal_flow_runtime_in_process"
            let startedAtMs = Environment.TickCount64
            let shouldStart =
                lock terminalFlowRuntimeStartGate (fun () ->
                    match terminalFlowRuntimeStartState with
                    | TerminalFlowRuntimeCold ->
                        terminalFlowRuntimeStartState <- TerminalFlowRuntimeStarting startedAtMs
                        true
                    | TerminalFlowRuntimeStarting _
                    | TerminalFlowRuntimeStarted _ -> false
                    | TerminalFlowRuntimeStartFailed(_, reason) ->
                        invalidOp ("terminal_flow_runtime_start_failed|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason))
            if shouldStart then
                try
                    CompilerKernelV2.PortableRuntimeInProcessEvidenceGate.refresh () |> ignore
                    HopacExtensions.start (terminalFlowGlobalServerLoop (terminalFlowGlobalReducerInitialState ()))
                    HopacExtensions.start (terminalFlowCanonicalRootReceiptBridge ())
                    HopacExtensions.start (terminalFlowSchedulerPushLoop terminalFlowSchedulerPushChannel)
                    HopacExtensions.start (terminalFlowGlobalServerDeadmanLoop ())
                    HopacExtensions.start (terminalFlowGlobalServerQapLivenessMonitorLoop ())
                    terminalFlowInstallOutcomeCandidatePublisher ()
                    terminalFlowInstallProductionAudit ()
                    DiagJson.installObserverTerminalExitPetitionPublisher (fun petition ->
                        terminalFlowGlobalServerPublish (TerminalFlowGlobalServerObserverExitPetitioned petition))
                    CompilerConsoleHud88.installTypedSemanticIngressPublisher (fun envelope ->
                        terminalFlowGlobalServerPublish (TerminalFlowGlobalServerTypedSemanticIngressObserved envelope))
                    let shim : NativeCutoverLegacyEvalWorklistShim<ProceduralResidualOwnerKind> =
                        nativeCutoverShimOnly
                            (terminalFlowMintedRefOf "eval_worklist_ingress_shim_ref" "reducer_eval_ingress_cutover")
                            (terminalFlowMintedRefOf "eval_worklist_native_event_adapter_ref" "legacy_to_native_compiler_event")
                    terminalFlowGlobalServerPublish (TerminalFlowGlobalServerEvalWorklistShimDemoted shim)
                    let queued, dropped = DiagJson.externalDiagLaneSnapshot()
                    DiagJson.emitOutsideHopac (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_flow_startup_phase\",\"phase_du\":\"InProcessRuntimeStarted\",\"activation_source_du\":%s,\"portable_runtime_evidence_du\":%s,\"portable_runtime_evidence_execution_du\":\"ClrTaskOwnedNeverNestedHopacRun\",\"external_diag_queue_depth\":%d,\"external_diag_dropped\":%d,\"hud_bootstrap_expected\":true,\"server_admission_open\":true,\"authority\":\"explicit_in_process_session_runtime_start\"}" [| box (DiagJson.esc (CompilerRuntimeActivation.currentSourceText ())); box (DiagJson.esc (CompilerKernelV2.PortableRuntimeInProcessEvidenceGate.stableText ())); box queued; box dropped |])
                    let bootstrapSnapshot = DiagJson.terminalSchedulerPushActorSnapshot()
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_push_actor_bootstrap_projection\",\"actor_phase_du\":%s,\"fill_ref\":%u,\"dispatch_ref\":%u,\"arming_witness_du\":\"NoAuthorityUntilDispatchAcceptance\",\"dispatch_gate_du\":\"RootOutcomeOwnerTailCertificatesRequired\",\"root_required_for_dispatch\":true,\"terminal_outcome_required_for_dispatch\":true,\"workdag_tail_close_required_for_dispatch\":true,\"owner\":\"push_actor_possession_spine\",\"polling_authority\":false}" [| box (DiagJson.esc (DiagJson.terminalSchedulerPushActorPhaseText bootstrapSnapshot.phase)); box (terminalFlowMintedRefOf "bootstrap_actor_fill_ref" bootstrapSnapshot.fillKey); box (terminalFlowMintedRefOf "bootstrap_actor_dispatch_ref" bootstrapSnapshot.dispatchId) |])
                    lock terminalFlowRuntimeStartGate (fun () ->
                        terminalFlowRuntimeStartState <- TerminalFlowRuntimeStarted startedAtMs)
                with ex ->
                    lock terminalFlowRuntimeStartGate (fun () ->
                        terminalFlowRuntimeStartState <- TerminalFlowRuntimeStartFailed(Environment.TickCount64, CompilerKernelV2.OperationalReasonIdOps.create ex.Message))
                    reraise()

        // Bonus migration : the renderer-side watchdog was deleted.  The only
        // remaining liveness timer is the kernel-owned fail-closed deadman above.

        let private terminalFlowSchedulerPushDispatch
            (tag:string)
            (cell:TerminalFlowOutcomeIvarCell<TerminalFlowOutcomeUnfilledState>)
            (envelope:TerminalFlowResolvedOutcomeEnvelope)
            (closeDecision:TerminalFlowOwnerCloseDecisionId)
            : Hopac.Job<TerminalFlowNativeHandoffId> =
            job {
                let fillKeyRef = terminalFlowFillKeyRefForId envelope.fillKey
                let completion =
                    terminalFlowSchedulerPushCompletionRegistry.GetOrAdd(
                        fillKeyRef,
                        fun _ ->
                            CompilerKernelV2.CompilerRuntimeKernel.oneShot<TerminalFlowNativeHandoffId>
                                ("terminal-scheduler-push-completion:" + TerminalFlowFillKeyId.text envelope.fillKey))
                let fillKeyId = envelope.fillKey
                let dispatchIdentity =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "terminal-push-dispatch"
                        (TerminalFlowFillKeyId.text fillKeyId)
                let dispatchId = CompilerIdentityKernel.ContentDigest.text dispatchIdentity
                let schedulerContext = envelope.schedulerContext
                let wakerRegistration = terminalFlowSchedulerWakerRegistrationFor schedulerContext
                let armReceiptRef = terminalFlowMintedRefOf "push_actor_arm_receipt_ref" dispatchId
                DiagJson.emitTerminalJsonDurable (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_waker_registered\",\"admission_ref\":%u,\"admission_identity_ref\":%u,\"actor_binding_ref\":%u,\"credential_ledger_ref\":%u,\"fairness_epoch_ref\":%u,\"scheduler_release_ref\":%u,\"waker_requirement_ref\":%u,\"waker_edge_ref\":%u,\"waker_registry_ref\":%u,\"exact_once_ref\":%u,\"authority\":\"admission_indexed_channel_registry\"}" [| box wakerRegistration.admissionRef; box wakerRegistration.admissionIdentityRef; box wakerRegistration.actorBindingRef; box wakerRegistration.credentialLedgerRef; box wakerRegistration.fairnessEpochRef; box wakerRegistration.schedulerReleaseRef; box wakerRegistration.requirementRef; box wakerRegistration.edgeRef; box wakerRegistration.registryRef; box wakerRegistration.exactOnceRef |])
                let accepted = terminalFlowSchedulerPushDispatchRegistry.TryAdd(fillKeyRef, 0uy)
                let genesisAuthority = terminalFlowSchedulerChannelGenesisAuthority schedulerContext wakerRegistration armReceiptRef
                let genesisPossession = TerminalFlowPushPossessionGenesis genesisAuthority
                let channelAuthority = terminalFlowSchedulerChannelRootAuthorityFor schedulerContext wakerRegistration genesisPossession
                if accepted then
                    let actorIdentity =
                        DiagJson.terminalSchedulerPushActorIdentityFor
                            (DiagJson.TerminalSchedulerPushActorFillKeyId.create (TerminalFlowFillKeyId.text envelope.fillKey))
                            (terminalFlowIdentityRefText envelope.terminalReceiptRef)
                            dispatchId
                            envelope.ownerClosure.transaction.transactionId
                    let wakerRequirementRef = schedulerContext.wakerRequirementRef
                    let armCommand = DiagJson.PushActorArmOwned(actorIdentity, armReceiptRef, wakerRequirementRef)
                    do! DiagJson.terminalSchedulerPushActorApplyJob armCommand
                    terminalFlowGlobalServerPublish (TerminalFlowGlobalServerActorProjectionObserved(DiagJson.terminalSchedulerPushActorSnapshot()))
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_push_actor_command\",\"command_du\":\"ArmOwned\",\"actor_ref\":%u,\"arm_receipt_ref\":%u,\"waker_requirement_ref\":%u,\"dispatch_ref\":%u,\"authority\":\"dispatch_acceptance_exact_once\"}" [| box (terminalFlowMintedRefOf "push_actor_ref" dispatchId); box armReceiptRef; box wakerRequirementRef; box (terminalFlowMintedRefOf "dispatch_ref" dispatchId) |])
                let receipt =
                    { dispatchIdentity = dispatchIdentity
                      accepted = accepted
                      channelAuthority = channelAuthority
                      wakerRegistration = wakerRegistration
                      possession = genesisPossession
                      eventCode = 1uy
                      completionCellId = "terminal-push-completion:" + TerminalFlowFillKeyId.text envelope.fillKey }
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_dispatch\",\"event_code\":%d,\"tag_ref\":%u,\"dispatch_ref\":%u,\"completion_ref\":%u,\"admission_ref\":%u,\"admission_identity_ref\":%u,\"actor_binding_ref\":%u,\"credential_ledger_ref\":%u,\"fairness_epoch_ref\":%u,\"scheduler_release_ref\":%u,\"waker_registry_ref\":%u,\"channel_context_ref\":%u,\"channel_root_ref\":%u,\"channel_root_exact_once_ref\":%u,\"accepted\":%b,\"completion_awaited\":true,\"redrive_joins_existing_completion\":true,\"polling_authority\":false,\"authority\":\"sealed_channel_root\"}" [| box receipt.eventCode; box (terminalFlowMintedRefOf "scheduler_tag_ref" tag); box (terminalFlowMintedRefOf "dispatch_ref" receipt.dispatchId); box (terminalFlowMintedRefOf "completion_ref" receipt.completionCellId); box schedulerContext.admissionRef; box schedulerContext.admissionIdentityRef; box schedulerContext.actorBindingRef; box schedulerContext.credentialLedgerRef; box schedulerContext.fairnessEpochRef; box (terminalFlowIdentityRefDigest schedulerContext.schedulerRelease.physicalReleaseRef); box wakerRegistration.registryRef; box schedulerContext.contextRef; box receipt.channelRootRef; box receipt.channelRootExactOnceRef; box receipt.accepted |])
                if accepted then
                    let dispatch =
                        { dispatchIdentity = dispatchIdentity
                          fillKeyId = fillKeyId
                          closeDecision = closeDecision
                          tag = tag
                          event = TerminalFlowPushResolvedOutcome { cell = cell; envelope = envelope }
                          channelAuthority = channelAuthority
                          completion = completion }
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.send
                            terminalFlowSchedulerPushChannel
                            dispatch
                let! handoff =
                    CompilerKernelV2.CompilerRuntimeKernel.readOneShot completion
                return handoff
            }

        let private terminalFlowAppliedDispatchBoundaryFor
            (plan:TerminalFlowAppliedDispatchPlan)
            (pending:TerminalFlowGlobalPendingTerminal)
            rootReceiptId
            tailId =
            let writerReceiptId = sprintf "writer:qap-applied:%u" plan.writerLeaseRef
            match pending.intent with
            | TerminalFlowPendingBuildOk ->
                TerminalFlowBoundaryReceipt(
                    TerminalFlowTopLevelBuildOkReceipt(
                        pending.terminalReceiptId,
                        rootReceiptId,
                        writerReceiptId,
                        tailId))
            | TerminalFlowPendingNoFurther ->
                TerminalFlowBoundaryReceipt(TerminalFlowTopLevelNoFurtherCertificate pending.terminalReceiptId)
            | TerminalFlowPendingQuarantine ->
                TerminalFlowBoundaryReceipt(
                    TerminalFlowTopLevelQuarantineCertificate(
                        pending.terminalReceiptId,
                        rootReceiptId,
                        "lease:qap-applied",
                        tailId,
                        CompilerKernelV2.TerminalTailQuarantineEvidence(
                            CompilerKernelV2.OperationalReasonIdOps.create "qap_applied_proof_quarantine")))
            | TerminalFlowPendingFailClosed ->
                TerminalFlowBoundaryReceipt(
                    TerminalFlowTopLevelBuildErrorCertificate(
                        pending.terminalReceiptId,
                        rootReceiptId,
                        "lease:qap-applied-failclosed",
                        tailId,
                        CompilerKernelV2.TerminalTailDeadlockEvidence(
                            CompilerKernelV2.OperationalReasonIdOps.create (
                                sprintf "qap_applied_proof=%u" plan.proofRef))))

        let private terminalFlowAppliedProofDispatchJob
            (plan:TerminalFlowAppliedDispatchPlan)
            (pending:TerminalFlowGlobalPendingTerminal)
            (stageToken:TerminalFlowActorOutcomeJoin<TerminalFlowArmedOutcomeJoinedStage>)
            : Hopac.Job<TerminalFlowNativeHandoffId> =
            job {
                let tailId = sprintf "qap-applied-tail:%u:%s" plan.proofRef pending.fillKey
                let now = Environment.TickCount64
                let snapshot : TerminalFlowStickyTailSnapshot =
                    { tailId = tailId
                      mutatingDepth = 0
                      proceduralDepth = 0
                      globalPending = 0
                      globalQueue = 0
                      globalActive = 0
                      fixedPointRepeat = 1
                      proceduralDrainPassCount = 1
                      materialDeltaOnProceduralPass = 0
                      fixedPointRepeatCap = 1
                      materialQuiescenceAgeMs = 0L
                      evaluatorFrontierResolved = true
                      wakerStatus = TerminalFlowWakerRegistered(sprintf "qap-applied-waker:%u" plan.exactOnceWakerEdgeRef, now)
                      aggregatePromiseArmed = true
                      mutatingTailDrained = true
                      evidence = FastRuntimeFormat.format "qap_applied|plan=%u|transaction=%u|proof=%u|exact_once=%u" [| box plan.planRef; box plan.transactionRef; box plan.proofRef; box plan.proofExactOnceRef |]
                      residualTopK = [] }
                let stickyTailGate = TerminalFlowStickyTailDrained snapshot
                let closeDecision = terminalFlowOwnerCloseDecisionFor stickyTailGate
                let closeReceipt = terminalFlowOwnerCloseReceiptFor stickyTailGate closeDecision
                match terminalFlowOwnerClosureCertificateFor stickyTailGate closeReceipt with
                | None ->
                    let reason = sprintf "qap_applied_owner_closure_adapter_rejected|proof=%u" plan.proofRef
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_applied_dispatch_executor_rejected\",\"plan_ref\":%u,\"transaction_ref\":%u,\"proof_ref\":%u,\"reason_du\":%s,\"authority\":\"completed_qap_proof_to_native_writer_adapter\",\"next\":\"fail_closed_no_redrive\"}" [| box plan.planRef; box plan.transactionRef; box plan.proofRef; box (DiagJson.esc reason) |])
                    return terminalFlowNativeHandoffFailClosed reason
                | Some ownerClosure ->
                    let stageTokenRootReceiptId = terminalFlowIdentityRefText stageToken.rootReceiptRef
                    let root : TerminalFlowRootCapability<TerminalFlowRootResolvedState> =
                        { rootReceiptId = stageTokenRootReceiptId
                          semanticDebtPaid = true }
                    let boundary =
                        terminalFlowAppliedDispatchBoundaryFor plan pending stageTokenRootReceiptId tailId
                    let terminalOutcome =
                        TerminalFlowTerminalOutcomeSealed {
                            boundary = boundary
                            stickyTailGate = stickyTailGate
                            receiptId = pending.terminalReceiptId
                            receiptDurable = not (String.IsNullOrWhiteSpace pending.terminalReceiptId)
                            ivarFillOnceKey = pending.fillKey
                            physicalExitIntent = TerminalFlowPhysicalExitAllowedAfterDurableReceipt pending.terminalReceiptId
                        }
                    let nativeRootBridge = terminalFlowNativeRootBridgeForStageToken stageToken
                    let schedulerContext = terminalFlowSchedulerChannelContextForStageToken stageToken
                    match terminalFlowResolvedOutcomeEnvelopeFor
                            root
                            terminalOutcome
                            ownerClosure
                            pending.fillKey
                            pending.terminalReceiptId
                            nativeRootBridge
                            schedulerContext with
                    | None ->
                        let reason = sprintf "qap_applied_resolved_envelope_missing|proof=%u" plan.proofRef
                        return terminalFlowNativeHandoffFailClosed reason
                    | Some resolvedEnvelope ->
                        let cell = terminalFlowOutcomeIvarCellFor pending.fillKeyId
                        DiagJson.emitTerminalJsonDurable (
                            FastRuntimeFormat.format "{\"kind\":\"terminal_applied_dispatch_executor_started\",\"plan_ref\":%u,\"transaction_ref\":%u,\"proof_ref\":%u,\"proof_exact_once_ref\":%u,\"writer_lease_ref\":%u,\"waker_edge_ref\":%u,\"owner_closure_ref\":%u,\"pending_ref\":%u,\"authority\":\"completed_qap_proof_installs_native_writer_continuation\",\"observer_continuation_reused\":false,\"next\":\"scheduler_push_dispatch\"}" [| box plan.planRef; box plan.transactionRef; box plan.proofRef; box plan.proofExactOnceRef; box plan.writerLeaseRef; box plan.exactOnceWakerEdgeRef; box (terminalFlowMintedRefOf "applied_owner_closure_ref" ownerClosure.certificateId); box (terminalFlowPendingTerminalRef pending) |])
                        return! terminalFlowSchedulerPushDispatch
                                    "qap-applied-proof"
                                    cell
                                    resolvedEnvelope
                                    closeDecision
            }

        do terminalFlowInstallAppliedDispatchExecutor terminalFlowAppliedProofDispatchJob

        let private terminalFlowTerminalOutcomeFillKey = function
            | TerminalFlowTerminalOutcomeOpen outcome -> outcome.ivarFillOnceKey
            | TerminalFlowTerminalOutcomeSealed outcome -> outcome.ivarFillOnceKey
            | TerminalFlowTerminalOutcomeEmitted outcome -> outcome.ivarFillOnceKey

        let private terminalFlowTerminalOutcomeReceiptId = function
            | TerminalFlowTerminalOutcomeOpen outcome -> outcome.receiptId
            | TerminalFlowTerminalOutcomeSealed outcome -> outcome.receiptId
            | TerminalFlowTerminalOutcomeEmitted outcome -> outcome.receiptId

        let private terminalFlowPendingIntentForBoundary = function
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt _) -> TerminalFlowPendingBuildOk
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelNoFurtherCertificate _) -> TerminalFlowPendingNoFurther
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelQuarantineCertificate _) -> TerminalFlowPendingQuarantine
            | TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildErrorCertificate _) -> TerminalFlowPendingFailClosed
            | TerminalFlowBoundaryWhyNotCommit whyNot ->
                invalidOp ("WhyNotCommit cannot construct a pending terminal: " + terminalFlowWhyNotTerminalCommitText whyNot)

        let private terminalFlowPendingIntentForOutcome = function
            | TerminalFlowTerminalOutcomeOpen outcome -> terminalFlowPendingIntentForBoundary outcome.boundary
            | TerminalFlowTerminalOutcomeSealed outcome -> terminalFlowPendingIntentForBoundary outcome.boundary
            | TerminalFlowTerminalOutcomeEmitted outcome -> terminalFlowPendingIntentForBoundary outcome.boundary

        let rec private terminalFlowNativeHandoffFor publishCandidate tag stickyTailGate terminalOutcome =
            let closeDecision = terminalFlowOwnerCloseDecisionFor stickyTailGate
            let stickyTailSnapshot = terminalFlowStickyTailSnapshotForGate stickyTailGate
            let closeDecisionIdentity = terminalFlowOwnerCloseDecisionText closeDecision
            let closeDecisionRef = terminalFlowMintedRefOf "owner_close_decision_ref" closeDecisionIdentity
            let stickyTailRef = terminalFlowMintedRefOf "sticky_tail_ref" stickyTailSnapshot.tailId
            let closeReceipt = terminalFlowOwnerCloseReceiptFor stickyTailGate closeDecision
            let ownerClosure = terminalFlowOwnerClosureCertificateFor stickyTailGate closeReceipt
            let eligibility = terminalFlowCommitEligibilityForTerminalOutcome terminalOutcome
            let pendingTerminal () =
                let terminalReceiptId = terminalFlowTerminalOutcomeReceiptId terminalOutcome
                let fillKey = terminalFlowTerminalOutcomeFillKey terminalOutcome
                terminalFlowPendingCandidateCreate
                    terminalReceiptId
                    fillKey
                    (terminalFlowPendingIntentForOutcome terminalOutcome)
                    (TerminalFlowPendingAdmissionEvaluatorNotice closeDecisionRef)
                    (TerminalFlowPendingNativeExecutable closeDecisionRef)
                    (fun stageToken ->
                        job {
                            let resolvedRootReceiptId = terminalFlowIdentityRefText stageToken.rootReceiptRef
                            let actorBefore = DiagJson.terminalSchedulerPushActorSnapshot()
                            terminalFlowGlobalServerPublish (TerminalFlowGlobalServerActorProjectionObserved actorBefore)
                            let! handoff =
                                job {
                                    match eligibility, ownerClosure with
                                    | TerminalFlowCommitEligible(root, key, receiptId, _), Some ownerClosureCertificate
                                        when key = fillKey && receiptId = terminalReceiptId ->
                                        let nativeRootBridge = terminalFlowNativeRootBridgeForStageToken stageToken
                                        let schedulerContext = terminalFlowSchedulerChannelContextForStageToken stageToken
                                        match terminalFlowResolvedOutcomeEnvelopeFor root terminalOutcome ownerClosureCertificate key receiptId nativeRootBridge schedulerContext with
                                        | Some envelope ->
                                            let cell = terminalFlowOutcomeIvarCellFor (TerminalFlowFillKeyId.create key)
                                            return! terminalFlowSchedulerPushDispatch tag cell envelope closeDecision
                                        | None ->
                                            return TerminalFlowNativeHandoffAwaitingResolvedRoot(CompilerKernelV2.OperationalReasonIdOps.create "stage_token_envelope_missing")
                                    | _ ->
                                        return terminalFlowNativeHandoffFor false tag stickyTailGate terminalOutcome
                                }
                            let stageJoinKey =
                                terminalFlowDispatchJoinKeyForRefs
                                    stageToken.rootReceiptRef
                                    stageToken.terminalReceiptRef
                                    stageToken.fillKey
                            let transition =
                                match handoff with
                                | TerminalFlowNativeHandoffGlobalServerQueued(_, _, _) ->
                                    let requestIdentity = terminalFlowDispatchRequestIdentityFor (TerminalFlowFillKeyId.reference stageToken.fillKey)
                                    TerminalFlowSchedulerPushDispatchAccepted(terminalFlowDispatchRequestIdentityRef requestIdentity, stageJoinKey.keyRef)
                                | TerminalFlowNativeHandoffPushDispatched(dispatchId, _, _, _) ->
                                    TerminalFlowSchedulerPushDispatchAccepted(terminalFlowMintedRefOf "dispatch_ref" dispatchId, stageJoinKey.keyRef)
                                | TerminalFlowNativeHandoffFailClosed(reason, _) ->
                                    TerminalFlowSchedulerPushDispatchFailClosed(terminalFlowMintedRefOf "dispatch_failure_ref" (CompilerKernelV2.OperationalReasonIdOps.text reason))
                                | TerminalFlowNativeHandoffAwaitingResolvedRoot _ ->
                                    TerminalFlowSchedulerPushDispatchRejected TerminalFlowDispatchMissingRoot
                                | TerminalFlowNativeHandoffAwaitingTerminalOutcome _
                                | TerminalFlowNativeHandoffOutcomeIvarArmed _
                                | TerminalFlowNativeHandoffCommitBlocked _ ->
                                    TerminalFlowSchedulerPushDispatchRejected(TerminalFlowDispatchContinuationRejected(terminalFlowStableAuthorityRef (TerminalFlowNativeHandoffIdentity handoff)))
                                | TerminalFlowNativeHandoffCompleted completed ->
                                    TerminalFlowSchedulerPushDispatchAccepted(terminalFlowMintedRefOf "dispatch_ref" completed.exitWitness.witnessId, stageJoinKey.keyRef)
                            let actorAfter = DiagJson.terminalSchedulerPushActorSnapshot()
                            let stageBridge = terminalFlowNativeRootBridgeForStageToken stageToken
                            let schedulerContext = terminalFlowSchedulerChannelContextForStageToken stageToken
                            let wakerRegistration = terminalFlowSchedulerWakerRegistrationFor schedulerContext
                            let wakerStatus =
                                match wakerRegistration.state with
                                | TerminalFlowSchedulerWakerRegistered -> FastRuntimeFormat.format "registered:admission=%u:registry=%u:edge=%u" [| box wakerRegistration.admissionRef; box wakerRegistration.registryRef; box wakerRegistration.edgeRef |]
                                | TerminalFlowSchedulerWakerConsumed -> FastRuntimeFormat.format "consumed:admission=%u:registry=%u:edge=%u" [| box wakerRegistration.admissionRef; box wakerRegistration.registryRef; box wakerRegistration.edgeRef |]
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_scheduler_push_transition\",\"actor_phase_before_du\":%s,\"actor_phase_after_du\":%s,\"actor_arm_attempted\":true,\"actor_arm_result_du\":%s,\"terminal_outcome_fill_key\":%s,\"terminal_outcome_receipt_id\":%s,\"waker_registration_status\":%s,\"native_bridge_authority_du\":%s,\"legacy_writer_capability_dependency\":false,\"authority\":\"typed_reducer_arm_and_dispatch\"}" [| box (DiagJson.esc (DiagJson.terminalSchedulerPushActorPhaseText actorBefore.phase)); box (DiagJson.esc (DiagJson.terminalSchedulerPushActorPhaseText actorAfter.phase)); box (DiagJson.esc (terminalFlowSchedulerPushTransitionText transition)); box (DiagJson.esc fillKey); box (DiagJson.esc terminalReceiptId); box (DiagJson.esc wakerStatus); box (DiagJson.esc (terminalFlowNativeRootBridgeAuthorityText stageBridge.authority)) |])
                            return handoff
                        })
            let publishPendingTerminal (reason:TerminalFlowMatureOwnerDebtSubmissionReason) =
                let actorOwnsTerminal =
                    match (DiagJson.terminalSchedulerPushActorSnapshot()).phase with
                    | DiagJson.PushActorNoop -> false
                    | _ -> true
                if publishCandidate && not actorOwnsTerminal then
                    let terminalReceiptId = terminalFlowTerminalOutcomeReceiptId terminalOutcome
                    let closeAllowed = terminalFlowOwnerCloseDecisionCanMintCertificate closeDecision
                    let submissionKey = terminalFlowMatureOwnerDebtSubmissionKeyFor terminalReceiptId reason stickyTailSnapshot.proceduralDrainPassCount
                    if closeAllowed && Option.isSome ownerClosure && terminalFlowMatureOwnerDebtSubmissionRegistry.TryAdd(submissionKey, 0uy) then
                        let pending = pendingTerminal ()
                        terminalFlowGlobalServerPublish (
                            TerminalFlowGlobalServerOwnerDebtObserved(
                                stickyTailGate,
                                stickyTailRef,
                                closeDecisionRef,
                                closeDecision,
                                Some pending))
                        let reasonText = terminalFlowMatureOwnerDebtSubmissionReasonText reason
                        let wakerVerdictText =
                            terminalFlowWakerRegistryVerdictText
                                (terminalFlowWakerRegistryVerdictFor TerminalFlowWakerRegistryStickyTail stickyTailSnapshot.wakerStatus)
                        let submissionWindow = if stickyTailSnapshot.proceduralDrainPassCount <= 0 then 0 else 1
                        let fixedPointReached = stickyTailSnapshot.proceduralDrainPassCount >= stickyTailSnapshot.fixedPointRepeatCap
                        let candidateSparseKey =
                            FastRuntimeFormat.format "pending_terminal_candidate_submitted|%s|window=%d|fixed=%b|waker=%s" [| box reasonText; box submissionWindow; box fixedPointReached; box wakerVerdictText |]
                        let candidateOccurrence, emitCandidate = DiagJson.sparseLogDecision candidateSparseKey 64L
                        if emitCandidate then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"terminal_flow_pending_terminal_candidate_submitted\",\"candidate_terminal_outcome_ref\":%u,\"candidate_fill_ref\":%u,\"decision_ref\":%u,\"reason\":%s,\"submission_window\":%d,\"procedural_residual_drain_pass_count\":%d,\"material_delta_on_procedural_pass\":%d,\"fixed_point_repeat_cap_reached\":%b,\"waker_registration_status\":%s,\"occurrence_count\":%d,\"sparse_policy\":\"state_first3_power2_every64\",\"owner\":\"single_reducer_interpreter\",\"registry_side_channel\":false,\"terminal_outcome_installation_du\":\"candidate_not_reduced\",\"authoritative_cache_mutated\":false,\"mature_submission\":true,\"timer_driven\":false}" [| box (terminalFlowMintedRefOf "candidate_terminal_outcome_ref" pending.terminalReceiptId); box (terminalFlowMintedRefOf "candidate_fill_ref" pending.fillKey); box closeDecisionRef; box (DiagJson.esc reasonText); box submissionWindow; box stickyTailSnapshot.proceduralDrainPassCount; box stickyTailSnapshot.materialDeltaOnProceduralPass; box fixedPointReached; box (DiagJson.esc wakerVerdictText); box candidateOccurrence |])
            // Eligibility owns candidate publication.  A WhyNotCommit observation is
            // evidence that the terminal corridor is not ready, never a FailClosed
            // candidate.  Publishing before this match caused MIGRATION to terminate
            // on AwaitingObservation("observe") even though the same function returned
            // TerminalFlowNativeHandoffCommitBlocked a few lines later.
            match eligibility with
            | TerminalFlowCommitEligible(root, fillKey, receiptId, _) ->
                // MIGRATION: TerminalFlow consumes evaluator-owned root truth.
                // A terminal-ready receipt can no longer fabricate RootPromiseResolved;
                // it either projects the evaluator receipt or blocks as an explicit
                // root-consensus divergence until the evaluator IVar is filled.
                let terminalRootRef : TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind> =
                    terminalFlowIdentityRefOfText root.rootReceiptId
                let rootConsensus =
                    terminalFlowCanonicalRootConsensus terminalRootRef ("terminal_projection|terminal=" + receiptId + "|fill=" + fillKey)
                let consensusText = terminalFlowRootConsensusText rootConsensus
                let projectionDedupeKey : TerminalFlowCanonicalProjectionIdentity =
                    { evaluatorRootRef = CompilerIdentityKernel.ContentDigest.ofText "terminal-flow-canonical-projection-root" root.rootReceiptId
                      terminalReceiptRef = CompilerIdentityKernel.ContentDigest.ofText "terminal-flow-canonical-projection-receipt" receiptId
                      fillRef = CompilerIdentityKernel.ContentDigest.ofText "terminal-flow-canonical-projection-fill" fillKey
                      consensus = rootConsensus }
                if terminalFlowCanonicalProjectionRegistry.TryAdd(projectionDedupeKey, 0uy) then
                    let evaluatorText =
                        match rootConsensus with
                        | TerminalFlowRootConsensusAccepted evaluator
                        | TerminalFlowRootConsensusDiverged(evaluator, _) -> terminalFlowIdentityRefText evaluator
                        | TerminalFlowRootConsensusAwaitEvaluator _ -> ""
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"canonical_root_terminal_projection\",\"decision\":%s,\"evaluator_operand\":%s,\"evaluator_operand_kind\":\"RootK\",\"terminal_root_operand\":%s,\"terminal_root_operand_kind\":\"RootK\",\"terminal_receipt_operand\":%s,\"terminal_receipt_operand_kind\":\"TerminalReceiptK\",\"candidate_terminal_receipt_ref\":%u,\"candidate_fill_ref\":%u,\"kind_safe_comparison\":true,\"dedupe_owner\":\"single_reducer_projection_registry\",\"emit_on_ref_set_change\":true,\"authoritative_cache_mutated\":false}" [| box (DiagJson.esc consensusText); box (DiagJson.esc evaluatorText); box (DiagJson.esc (terminalFlowIdentityRefText terminalRootRef)); box (DiagJson.esc receiptId); box (terminalFlowMintedRefOf "candidate_terminal_outcome_ref" receiptId); box (terminalFlowMintedRefOf "candidate_fill_ref" fillKey) |])
                match rootConsensus with
                | TerminalFlowRootConsensusAccepted _ ->
                    publishPendingTerminal MatureOwnerDebtCanonicalRootProjectionDispatch
                | TerminalFlowRootConsensusAwaitEvaluator _ ->
                    publishPendingTerminal MatureOwnerDebtCanonicalRootProjectionAwaitRoot
                | TerminalFlowRootConsensusDiverged _ ->
                    ()
            | TerminalFlowCommitBlocked(fillKey, TerminalFlowWhyNotMissingRootReceipt reason) ->
                DiagJson.canonicalRootAuthorityArm "terminal_flow_commit_observed_before_root_resolution" |> ignore
                DiagJson.emit (
                    sprintf "{\"kind\":\"terminal_flow_commit_blocked_awaiting_root\",\"fill_ref\":%u,\"reason_ref\":%u,\"pending_terminal_published\":false,\"authority\":\"commit_eligibility\",\"next\":\"await_evaluator_root_receipt\"}"
                        (terminalFlowMintedRefOf "fill_ref" fillKey)
                        (terminalFlowMintedRefOf "why_not_root_ref" reason))
            | TerminalFlowCommitBlocked _ ->
                DiagJson.canonicalRootAuthorityArm "terminal_flow_commit_observed_before_root_resolution" |> ignore
            match eligibility, closeReceipt, ownerClosure with
            | TerminalFlowCommitBlocked(fillKey, whyNot), _, _ ->
                TerminalFlowNativeHandoffCommitBlocked(fillKey, whyNot, closeDecision)
            | TerminalFlowCommitEligible(root, key, receiptId, _), None, _ ->
                TerminalFlowNativeHandoffAwaitingTerminalOutcome(root, key, closeDecision)
            | TerminalFlowCommitEligible(_, _, _, _), Some _, None ->
                let reason = "typed_owner_closure_certificate_rejected_after_exact_once_close_receipt"
                terminalFlowNativeHandoffFailClosed reason
            | TerminalFlowCommitEligible(root, key, receiptId, _), Some _, Some ownerClosureCertificate ->
                let terminalRootRef : TerminalFlowIdentityRef<TerminalFlowCanonicalRootRefKind> =
                    terminalFlowIdentityRefOfText root.rootReceiptId
                match terminalFlowCanonicalRootConsensus terminalRootRef ("terminal_outcome_commit|fill=" + key + "|receipt=" + receiptId) with
                | TerminalFlowRootConsensusAwaitEvaluator _ ->
                    publishPendingTerminal MatureOwnerDebtEvaluatorIvarUnfilled
                    TerminalFlowNativeHandoffAwaitingResolvedRoot(CompilerKernelV2.OperationalReasonIdOps.create "canonical_root_evaluator_ivar_unfilled")
                | TerminalFlowRootConsensusDiverged(evaluatorRoot, terminalRoot) ->
                    let failReason =
                        "canonical_root_consensus_diverged|evaluator=" + terminalFlowIdentityRefText evaluatorRoot
                        + "|evaluator_kind=RootK|terminal=" + terminalFlowIdentityRefText terminalRoot
                        + "|terminal_kind=RootK|terminal_receipt=" + receiptId
                        + "|terminal_receipt_kind=TerminalReceiptK"
                    terminalFlowNativeHandoffFailClosed failReason
                | TerminalFlowRootConsensusAccepted _ ->
                    match terminalFlowNativeRootBridgeForCurrentAuthority () with
                    | Error reason ->
                        let failReason = "native_root_bridge_missing_after_terminal_outcome_eligible|" + reason
                        terminalFlowNativeHandoffFailClosed failReason
                    | Ok _ ->
                        let failReason = "legacy_native_scheduler_authority_cannot_construct_admission_indexed_channel_possession"
                        terminalFlowNativeHandoffFailClosed failReason

        let private terminalFlowNativeSchedulerAuthorityFor handoff =
            match handoff with
            | TerminalFlowNativeHandoffAwaitingResolvedRoot _ -> TerminalFlowNativeSchedulerPreRoot
            | TerminalFlowNativeHandoffCommitBlocked(_, _, decision)
            | TerminalFlowNativeHandoffAwaitingTerminalOutcome(_, _, decision)
            | TerminalFlowNativeHandoffOutcomeIvarArmed(_, _, _, decision)
            | TerminalFlowNativeHandoffPushDispatched(_, _, _, decision)
            | TerminalFlowNativeHandoffGlobalServerQueued(_, _, decision) ->
                match decision with
                | TerminalFlowOwnerCloseDeferredMaterialDelta _
                | TerminalFlowOwnerCloseAwaitConservedCreditQuiescence _ -> TerminalFlowNativeSchedulerRepair decision
                | TerminalFlowOwnerCloseAlreadyExhausted _ -> TerminalFlowNativeSchedulerEscalate decision
            | TerminalFlowNativeHandoffCompleted completed ->
                TerminalFlowNativeSchedulerCommit (terminalFlowWriterTerminalReceiptText completed.bound.writer)
            | TerminalFlowNativeHandoffFailClosed(reason, _) -> TerminalFlowNativeSchedulerFailClosed reason

        let private terminalFlowNativeHandoffLiveGraphPhaseText = function
            | TerminalFlowNativeHandoffAwaitingResolvedRoot _ -> "Progressing"
            | TerminalFlowNativeHandoffCommitBlocked _ -> "TerminalBlocked"
            | TerminalFlowNativeHandoffAwaitingTerminalOutcome _ -> "TerminalEligibleSticky"
            | TerminalFlowNativeHandoffOutcomeIvarArmed _ -> "TerminalOutcomeIvarArmed"
            | TerminalFlowNativeHandoffPushDispatched _ -> "SchedulerPushDispatched"
            | TerminalFlowNativeHandoffGlobalServerQueued _ -> "GlobalServerQueued"
            | TerminalFlowNativeHandoffCompleted _ -> "Done"
            | TerminalFlowNativeHandoffFailClosed _ -> "Quarantined"

        let private terminalFlowNativeSchedulerAuthorityText = function
            | TerminalFlowNativeSchedulerPreRoot -> "NativeHopacSchedulerAuthority(PreRoot)"
            | TerminalFlowNativeSchedulerRepair decision -> "NativeHopacSchedulerAuthority(Repair|" + terminalFlowOwnerCloseDecisionText decision + ")"
            | TerminalFlowNativeSchedulerEscalate decision -> "NativeHopacSchedulerAuthority(Escalate|" + terminalFlowOwnerCloseDecisionText decision + ")"
            | TerminalFlowNativeSchedulerCommit receiptId -> "NativeHopacSchedulerAuthority(Commit|receipt=" + receiptId + ")"
            | TerminalFlowNativeSchedulerFailClosed reason -> "NativeHopacSchedulerAuthority(FailClosed|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let private terminalFlowNativeHandoffText = function
            | TerminalFlowNativeHandoffAwaitingResolvedRoot reason -> "TerminalOutcomeHandoff(AwaitingResolvedRoot|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | TerminalFlowNativeHandoffCommitBlocked(fillKey, whyNot, closeDecision) -> "TerminalOutcomeHandoff(CommitBlocked|key=" + fillKey + "|why_not=" + terminalFlowWhyNotTerminalCommitText whyNot + "|owner=" + terminalFlowOwnerCloseDecisionText closeDecision + ")"
            | TerminalFlowNativeHandoffAwaitingTerminalOutcome(root, key, closeDecision) -> "TerminalOutcomeHandoff(AwaitingTerminalOutcome|root=" + root.rootReceiptId + "|key=" + key + "|owner=" + terminalFlowOwnerCloseDecisionText closeDecision + ")"
            | TerminalFlowNativeHandoffOutcomeIvarArmed(cellId, key, root, closeDecision) -> "TerminalOutcomeHandoff(OutcomeIvarArmed|cell=" + cellId + "|root=" + root.rootReceiptId + "|key=" + key + "|owner=" + terminalFlowOwnerCloseDecisionText closeDecision + ")"
            | TerminalFlowNativeHandoffPushDispatched(dispatchId, cellId, fillKey, closeDecision) -> "TerminalOutcomeHandoff(SchedulerPushDispatched|dispatch=" + dispatchId + "|cell=" + cellId + "|key=" + fillKey + "|owner=" + terminalFlowOwnerCloseDecisionText closeDecision + ")"
            | TerminalFlowNativeHandoffGlobalServerQueued(requestId, fillKey, closeDecision) -> "TerminalOutcomeHandoff(GlobalServerQueued|request=" + requestId + "|key=" + fillKey + "|owner=" + terminalFlowOwnerCloseDecisionText closeDecision + ")"
            | TerminalFlowNativeHandoffCompleted completed ->
                let writer = completed.bound.writer
                let fillReceipt = completed.bound.filled.fillReceipt
                let writerReceipt = completed.writerReceipt
                "TerminalOutcomeHandoff(Done|concrete_ivar=true|job_bind=true|cell=" + fillReceipt.cellId
                + "|first_fill=" + string fillReceipt.firstFill
                + "|writer_job=" + writerReceipt.writerJobId
                + "|writer_lease=" + writer.writerLeaseId
                + "|receipt=" + terminalFlowWriterTerminalReceiptText writer
                + "|owner_closure=" + writer.ownerClosureCertificateId
                + "|owner_transaction=" + writer.ownerTransactionId
                + "|exit_witness=" + completed.exitWitness.witnessId
                + "|open_after=" + string writerReceipt.ownerLedgerOpenAfter + ")"
            | TerminalFlowNativeHandoffFailClosed(reason, authority) -> "TerminalOutcomeHandoff(FailClosed|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + "|authority=" + terminalFlowNativeSchedulerAuthorityText authority + ")"

        let private terminalFlowNativeWriterCapabilityText = function
            | TerminalFlowNativeHandoffCompleted completed ->
                let writer = completed.bound.writer
                let fillReceipt = completed.bound.filled.fillReceipt
                let writerReceipt = completed.writerReceipt
                let artifactAuthority =
                    match writerReceipt.artifactReceipt.authorization with
                    | TerminalFlowArtifactsAuthorizedByNativeRootComplete(bridge, artifactSetHash) ->
                        "Authorized(cell=" + bridge.cellId
                        + "|proof=" + bridge.proofHash
                        + "|artifact_set=" + artifactSetHash
                        + "|resolution_ref=" + string bridge.resolutionRef + ")"
                    | TerminalFlowArtifactsAuthorizedByTerminalFailure(failureManifestRef, reasonRef, reason) ->
                        "AuthorizedTerminalFailure(manifest=" + terminalFlowIdentityRefText failureManifestRef
                        + "|reason_ref=" + string reasonRef + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
                    | TerminalFlowArtifactsRejectedByNativeRootComplete(reasonRef, reason) ->
                        "Rejected(reason_ref=" + string reasonRef + "|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
                let registryState =
                    match writerReceipt.registryLifecycle with
                    | TerminalFlowRegistryPruneRequired nativeCellId -> "PruneRequired(native_cell=" + nativeCellId + ")"
                    | TerminalFlowRegistryPruned fillKey -> "Pruned(fill=" + TerminalFlowFillKeyId.text fillKey + ")"
                let boundaryState =
                    match writerReceipt.physicalBoundary with
                    | TerminalFlowPhysicalBoundaryOwnedByWriterReceipt(writerJobId, artifactSetHash) ->
                        "Owned(" + writerJobId + "|artifact_set=" + artifactSetHash + ")"
                    | TerminalFlowPhysicalBoundaryRejected reason -> "Rejected(" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
                "WriterCapability<Bound>(lease=" + writer.writerLeaseId
                + "|receipt=" + terminalFlowWriterTerminalReceiptText writer
                + "|ivar_cell=" + fillReceipt.cellId
                + "|fill_once=" + string fillReceipt.firstFill
                + "|writer_job=" + writerReceipt.writerJobId
                + "|artifact_plan=" + writer.artifactPlan.planId
                + "|artifact_authority=" + artifactAuthority
                + "|registry=" + registryState
                + "|physical_boundary=" + boundaryState
                + "|owner_closure=" + writer.ownerClosureCertificateId
                + "|owner_transaction=" + writer.ownerTransactionId
                + "|owner_ledger=" + recursiveOwnerLedgerText writer.ownerLedgerAfter + ")"
            | _ -> "WriterCapability<Unbound>"

        let private terminalFlowNativeHandoffWhyNotText = function
            | TerminalFlowNativeHandoffCompleted _ -> "WhyNotTerminalCommit(None|breakthrough_done=true|concrete_ivar_bound_writer_job_completed=true)"
            | TerminalFlowNativeHandoffAwaitingResolvedRoot reason -> "WhyNotTerminalCommit(MissingRootCapability|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | TerminalFlowNativeHandoffCommitBlocked(key, whyNot, decision) -> "WhyNotTerminalCommit(Blocked|key=" + key + "|reason=" + terminalFlowWhyNotTerminalCommitText whyNot + "|decision=" + terminalFlowOwnerCloseDecisionText decision + ")"
            | TerminalFlowNativeHandoffAwaitingTerminalOutcome(_, key, decision) -> "WhyNotTerminalCommit(AwaitingTypedOwnerClose|key=" + key + "|decision=" + terminalFlowOwnerCloseDecisionText decision + ")"
            | TerminalFlowNativeHandoffOutcomeIvarArmed(cellId, key, _, _) -> "WhyNotTerminalCommit(AwaitingConcreteIvarConsumer|cell=" + cellId + "|key=" + key + ")"
            | TerminalFlowNativeHandoffPushDispatched(dispatchId, cellId, key, _) -> "WhyNotTerminalCommit(AwaitingSchedulerPushCompletion|dispatch=" + dispatchId + "|cell=" + cellId + "|key=" + key + ")"
            | TerminalFlowNativeHandoffGlobalServerQueued(requestId, key, _) -> "WhyNotTerminalCommit(AwaitingGlobalServerDispatch|request=" + requestId + "|key=" + key + ")"
            | TerminalFlowNativeHandoffFailClosed(reason, _) -> "WhyNotTerminalCommit(FailClosed|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        // MIGRATION migration : queue-only parent-continuation recovery is
        // now authorized by a typed post-root terminal-flow shape rather than by
        // the particular payload that happened to appear in the previous log.
        // The writer gate may keep polling QAP, but this DU names the real
        // contract: root is resolved, owners are closed or sticky-terminal, the
        // writer-tail is bounded, and no recent semantic material delta is being
        // produced.  Renderers may print strings; they do not decide.
        type QueueOnlyParentContinuationRecoveryAuthorityId =
            | QueueOnlyRecoveryPreRootOrUnarmed
            | QueueOnlyRecoveryRecentSemanticActivity of ageMs:int64
            | QueueOnlyRecoveryTopologyRejected of pending:int * queue:int * active:int
            | QueueOnlyRecoveryReadyPostRootTerminalFlow of rootReceipt:string * writerLease:string * tailId:string
            | QueueOnlyRecoveryReadyAfterForceOwnerClose of rootReceipt:string * writerLease:string * tailId:string * ownerCloseReceiptId:string * workDagTailCloseReceipt:string
            | QueueOnlyRecoveryTerminalFlowTransition of observation:TerminalFlowObservation * decision:TerminalFlowTransitionDecisionId
            | QueueOnlyRecoveryTerminalFlowOutcome of observation:TerminalFlowObservation * decision:TerminalFlowTransitionDecisionId * outcome:TerminalFlowOutcomeId
            | QueueOnlyRecoveryTerminalFlowBoundary of observation:TerminalFlowObservation * decision:TerminalFlowTransitionDecisionId * outcome:TerminalFlowOutcomeId * boundary:TerminalFlowCertificateBoundaryId

        let private queueOnlyParentContinuationRecoveryAuthorityText = function
            | QueueOnlyRecoveryPreRootOrUnarmed -> "QueueOnlyRecoveryAuthority(PreRootOrUnarmed)"
            | QueueOnlyRecoveryRecentSemanticActivity ageMs -> sprintf "QueueOnlyRecoveryAuthority(RecentSemanticActivity|age_ms=%d)" ageMs
            | QueueOnlyRecoveryTopologyRejected(pending, queue, active) -> FastRuntimeFormat.format "QueueOnlyRecoveryAuthority(TopologyRejected|p=%d|q=%d|a=%d)" [| box pending; box queue; box active |]
            | QueueOnlyRecoveryReadyPostRootTerminalFlow(rootReceipt, writerLease, tailId) -> "QueueOnlyRecoveryAuthority(ReadyPostRootTerminalFlow|root=" + rootReceipt + "|lease=" + writerLease + "|tail=" + tailId + ")"
            | QueueOnlyRecoveryReadyAfterForceOwnerClose(rootReceipt, writerLease, tailId, ownerCloseReceiptId, workDagTailCloseReceipt) -> FastRuntimeFormat.format "QueueOnlyRecoveryAuthority(ReadyAfterForceOwnerClose|root=%s|lease=%s|tail=%s|owner_close_receipt=%s|workdag_close=%s)" [| box rootReceipt; box writerLease; box tailId; box ownerCloseReceiptId; box workDagTailCloseReceipt |]
            | QueueOnlyRecoveryTerminalFlowTransition(observation, decision) -> "QueueOnlyRecoveryAuthority(TerminalFlow|" + terminalFlowObservationText observation + "|" + terminalFlowTransitionDecisionText decision + ")"
            | QueueOnlyRecoveryTerminalFlowOutcome(observation, decision, outcome) -> "QueueOnlyRecoveryAuthority(TerminalFlowOutcome|" + terminalFlowObservationText observation + "|" + terminalFlowTransitionDecisionText decision + "|" + terminalFlowOutcomeText outcome + "|" + terminalFlowCertificateIntentText (terminalFlowCertificateIntentForOutcome outcome) + ")"
            | QueueOnlyRecoveryTerminalFlowBoundary(observation, decision, outcome, boundary) -> "QueueOnlyRecoveryAuthority(TerminalFlowBoundary|" + terminalFlowObservationText observation + "|" + terminalFlowTransitionDecisionText decision + "|" + terminalFlowOutcomeText outcome + "|" + terminalFlowCertificateIntentText (terminalFlowCertificateIntentForOutcome outcome) + "|" + terminalFlowCertificateBoundaryText boundary + ")"

        let private queueOnlyParentContinuationRecoveryBoundaryText = function
            | QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, boundary) -> terminalFlowCertificateBoundaryText boundary
            | QueueOnlyRecoveryTerminalFlowOutcome(_, _, outcome) -> terminalFlowCertificateBoundaryText (terminalFlowCertificateBoundaryForOutcome outcome)
            | QueueOnlyRecoveryTerminalFlowTransition _ -> "TerminalFlowCertificateBoundary(WhyNotTerminalCommit(ObserverOnly|reason=transition_without_outcome_boundary))"
            | QueueOnlyRecoveryReadyPostRootTerminalFlow(rootReceipt, writerLease, tailId) -> terminalFlowCertificateBoundaryText (TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotMissingWriterReceipt(rootReceipt, tailId)))
            | QueueOnlyRecoveryReadyAfterForceOwnerClose(rootReceipt, _, tailId, ownerCloseReceiptId, workDagTailCloseReceipt) -> terminalFlowCertificateBoundaryText (TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt("terminal-commit:force-close-owner:" + ownerCloseReceiptId, rootReceipt, "writer-receipt:force-close-owner:" + ownerCloseReceiptId + ":" + workDagTailCloseReceipt, tailId)))
            | QueueOnlyRecoveryRecentSemanticActivity ageMs -> terminalFlowCertificateBoundaryText (TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRecentMaterialActivity(terminalFlowMaterialActivityToken TerminalFlowFreshTopologyWitness ageMs 1L)))
            | QueueOnlyRecoveryTopologyRejected(pending, queue, active) -> FastRuntimeFormat.format "TerminalFlowCertificateBoundary(WhyNotTerminalCommit(RejectedTopology|p=%d|q=%d|a=%d))" [| box pending; box queue; box active |]
            | QueueOnlyRecoveryPreRootOrUnarmed -> "TerminalFlowCertificateBoundary(WhyNotTerminalCommit(ObserverOnly|reason=pre_root_or_unarmed))"

        let private queueOnlyParentContinuationRecoveryWhyNotText = function
            | QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, TerminalFlowBoundaryWhyNotCommit reason) -> terminalFlowWhyNotTerminalCommitText reason
            | QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, TerminalFlowBoundaryReceipt _) -> "WhyNotTerminalCommit(None|terminal_receipt_ready=true)"
            | x -> queueOnlyParentContinuationRecoveryBoundaryText x

        let private queueOnlyParentContinuationRecoveryBoundaryActionText = function
            | QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, boundary) -> terminalFlowBoundaryActionText (terminalFlowBoundaryActionForBoundary boundary)
            | QueueOnlyRecoveryTerminalFlowOutcome(_, _, outcome) ->
                let boundary = terminalFlowCertificateBoundaryForOutcome outcome
                terminalFlowBoundaryActionText (terminalFlowBoundaryActionForBoundary boundary)
            | QueueOnlyRecoveryTerminalFlowTransition _ -> terminalFlowBoundaryActionText (TerminalFlowBoundaryActionBlockCommit(TerminalFlowWhyNotObserverOnly (CompilerKernelV2.OperationalReasonIdOps.create "transition_without_outcome_boundary")))
            | QueueOnlyRecoveryReadyPostRootTerminalFlow(rootReceipt, _, tailId) -> terminalFlowBoundaryActionText (TerminalFlowBoundaryActionBlockCommit(TerminalFlowWhyNotMissingWriterReceipt(rootReceipt, tailId)))
            | QueueOnlyRecoveryReadyAfterForceOwnerClose(rootReceipt, _, tailId, ownerCloseReceiptId, workDagTailCloseReceipt) ->
                terminalFlowBoundaryActionText (terminalFlowBoundaryActionForBoundary (TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt("terminal-commit:force-close-owner:" + ownerCloseReceiptId, rootReceipt, "writer-receipt:force-close-owner:" + ownerCloseReceiptId + ":" + workDagTailCloseReceipt, tailId))))
            | QueueOnlyRecoveryRecentSemanticActivity ageMs -> terminalFlowBoundaryActionText (TerminalFlowBoundaryActionBlockCommit(TerminalFlowWhyNotRecentMaterialActivity(terminalFlowMaterialActivityToken TerminalFlowFreshTopologyWitness ageMs 1L)))
            | QueueOnlyRecoveryTopologyRejected(pending, queue, active) -> terminalFlowBoundaryActionText (TerminalFlowBoundaryActionBlockCommit(TerminalFlowWhyNotRejectedTopology(terminalFlowRejectedQapObservation pending queue active)))
            | QueueOnlyRecoveryPreRootOrUnarmed -> terminalFlowBoundaryActionText (TerminalFlowBoundaryActionBlockCommit(TerminalFlowWhyNotObserverOnly (CompilerKernelV2.OperationalReasonIdOps.create "pre_root_or_unarmed")))

        let private queueOnlyParentContinuationRecoveryTopLevelReceiptText = function
            | QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, boundary) -> terminalFlowBoundaryTopLevelReceiptText boundary
            | QueueOnlyRecoveryTerminalFlowOutcome(_, _, outcome) -> terminalFlowBoundaryTopLevelReceiptText (terminalFlowCertificateBoundaryForOutcome outcome)
            | QueueOnlyRecoveryReadyAfterForceOwnerClose(rootReceipt, _, tailId, ownerCloseReceiptId, workDagTailCloseReceipt) ->
                terminalFlowBoundaryTopLevelReceiptText (TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt("terminal-commit:force-close-owner:" + ownerCloseReceiptId, rootReceipt, "writer-receipt:force-close-owner:" + ownerCloseReceiptId + ":" + workDagTailCloseReceipt, tailId)))
            | _ -> "TerminalFlowTopLevelReceipt(None)"

        let private queueOnlyParentContinuationRecoveryTerminalCommitReceiptIdText = function
            | QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, boundary) -> terminalFlowBoundaryTerminalCommitReceiptId boundary
            | QueueOnlyRecoveryTerminalFlowOutcome(_, _, outcome) -> terminalFlowBoundaryTerminalCommitReceiptId (terminalFlowCertificateBoundaryForOutcome outcome)
            | QueueOnlyRecoveryReadyAfterForceOwnerClose(rootReceipt, _, tailId, ownerCloseReceiptId, workDagTailCloseReceipt) ->
                terminalFlowBoundaryTerminalCommitReceiptId (TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt("terminal-commit:force-close-owner:" + ownerCloseReceiptId, rootReceipt, "writer-receipt:force-close-owner:" + ownerCloseReceiptId + ":" + workDagTailCloseReceipt, tailId)))
            | _ -> ""

        let private queueOnlyParentContinuationRecoveryPostRootCertificateIdText = function
            | QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, boundary) -> terminalFlowBoundaryPostRootCertificateId boundary
            | QueueOnlyRecoveryTerminalFlowOutcome(_, _, outcome) -> terminalFlowBoundaryPostRootCertificateId (terminalFlowCertificateBoundaryForOutcome outcome)
            | QueueOnlyRecoveryReadyAfterForceOwnerClose(rootReceipt, _, tailId, ownerCloseReceiptId, workDagTailCloseReceipt) ->
                terminalFlowBoundaryPostRootCertificateId (TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt("terminal-commit:force-close-owner:" + ownerCloseReceiptId, rootReceipt, "writer-receipt:force-close-owner:" + ownerCloseReceiptId + ":" + workDagTailCloseReceipt, tailId)))
            | _ -> ""

        let private queueOnlyParentContinuationRecoveryBoundaryObject = function
            | QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, boundary) -> boundary
            | QueueOnlyRecoveryTerminalFlowOutcome(_, _, outcome) -> terminalFlowCertificateBoundaryForOutcome outcome
            | QueueOnlyRecoveryTerminalFlowTransition _ -> TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotObserverOnly (CompilerKernelV2.OperationalReasonIdOps.create "transition_without_outcome_boundary"))
            | QueueOnlyRecoveryReadyPostRootTerminalFlow(rootReceipt, _, tailId) -> TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotMissingWriterReceipt(rootReceipt, tailId))
            | QueueOnlyRecoveryReadyAfterForceOwnerClose(rootReceipt, _, tailId, ownerCloseReceiptId, workDagTailCloseReceipt) -> TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt("terminal-commit:force-close-owner:" + ownerCloseReceiptId, rootReceipt, "writer-receipt:force-close-owner:" + ownerCloseReceiptId + ":" + workDagTailCloseReceipt, tailId))
            | QueueOnlyRecoveryRecentSemanticActivity ageMs -> TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRecentMaterialActivity(terminalFlowMaterialActivityToken TerminalFlowFreshTopologyWitness ageMs 1L))
            | QueueOnlyRecoveryTopologyRejected(pending, queue, active) -> TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRejectedTopology(terminalFlowRejectedQapObservation pending queue active))
            | QueueOnlyRecoveryPreRootOrUnarmed -> TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotObserverOnly (CompilerKernelV2.OperationalReasonIdOps.create "pre_root_or_unarmed"))

        [<StructuralEquality; NoComparison>]
        type private TerminalFlowBoundaryBlockedIdentity =
            | TerminalFlowBoundaryBlockedWhyNot of CompilerIdentityKernel.ContentDigest
            | TerminalFlowBoundaryBlockedReceipt of CompilerIdentityKernel.ContentDigest

        let private terminalFlowBoundaryBlockedSparseRegistry =
            System.Collections.Concurrent.ConcurrentDictionary<TerminalFlowBoundaryBlockedIdentity,int64>()

        let private terminalFlowBoundaryBlockedStableKey authority _pending _queue _active =
            let boundary = queueOnlyParentContinuationRecoveryBoundaryObject authority
            match boundary with
            | TerminalFlowBoundaryWhyNotCommit whyNot ->
                TerminalFlowBoundaryBlockedWhyNot(
                    CompilerIdentityKernel.ContentDigest.ofText "terminal-boundary-why-not" (terminalFlowWhyNotIdentityText whyNot))
            | TerminalFlowBoundaryReceipt receipt ->
                TerminalFlowBoundaryBlockedReceipt(
                    CompilerIdentityKernel.ContentDigest.ofText "terminal-boundary-receipt" (terminalFlowTopLevelReceiptText receipt))

        let private terminalFlowBoundaryBlockedOccurrence authority pending queue active =
            let key = terminalFlowBoundaryBlockedStableKey authority pending queue active
            terminalFlowBoundaryBlockedSparseRegistry.AddOrUpdate(key, 1L, fun _ count -> count + 1L)

        let private terminalFlowSparseOccurrenceShouldEmit occurrence =
            occurrence > 0L
            && (occurrence <= 3L
                || (occurrence &&& (occurrence - 1L)) = 0L
                || occurrence % 64L = 0L)

