        let private terminalFlowObservationMarkers =
            [ TerminalObservationMarkerTerminalAfterRoot
              TerminalObservationMarkerWorkDagTail
              TerminalObservationMarkerWriterLease
              TerminalObservationMarkerPostRoot
              TerminalObservationMarkerBoundaryAction
              TerminalObservationMarkerWhyNotTerminalCommit
              TerminalObservationMarkerRootPromiseResolved
              TerminalObservationMarkerBlockedOnQap
              TerminalObservationMarkerLiveQapDrain
              TerminalObservationMarkerKeepDraining
              TerminalObservationMarkerTailDeadlocked
              TerminalObservationMarkerDeadlock
              TerminalObservationMarkerTailQuarantined
              TerminalObservationMarkerQuarantine
              TerminalObservationMarkerTailDrained
              TerminalObservationMarkerWriterBound
              TerminalObservationMarkerPendingDrain
              TerminalObservationMarkerTerminalEligible
              TerminalObservationMarkerOwnerDebtNotOpen
              TerminalObservationMarkerClosed
              TerminalObservationMarkerOwnerLedgerQuorumClosed
              TerminalObservationMarkerOwnersNotReopened
              TerminalObservationMarkerOpenZeroEq
