              TerminalObservationMarkerWriterTailScheduler
              TerminalObservationMarkerOpen ]

        let private terminalFlowObservationMarkerPresent marker (text:string) =
            if String.IsNullOrWhiteSpace text then false
            else
                let needle = terminalFlowObservationMarkerText marker
                if needle.Length = 0 then true
                elif needle.Length > text.Length then false
                else
                    let mutable offset = 0
                    let mutable found = false
                    let lastOffset = text.Length - needle.Length
                    while not found && offset <= lastOffset do
                        if System.String.Compare(text, offset, needle, 0, needle.Length, StringComparison.OrdinalIgnoreCase) = 0 then
                            found <- true
                        else
                            offset <- offset + 1
                    found

        let private terminalFlowObservationSignals (text:string) =
            if String.IsNullOrWhiteSpace text then Set.empty
            else
                terminalFlowObservationMarkers
                |> List.choose (fun marker ->
                    if terminalFlowObservationMarkerPresent marker text then
                        Some (terminalFlowObservationMarkerSignal marker)
                    else None)
                |> Set.ofList

        let private terminalFlowObservationHas signal signals = Set.contains signal signals

        let private terminalFlowObservationFromPostRootQueueOnly pending queueDepth activeDepth injectionActive materialDeltaActive sampledDelta rootDelta terminalDelta richTickAgeMs writerTailAgeMs =
            let rootStatus = CompilerConsoleHud88.cachedHudTextOrDash ["root_promise_status_du"; "root_promise_status"]
            let canonicalRoot = DiagJson.canonicalRootAuthoritySnapshot()
            let terminalAfterRoot = CompilerConsoleHud88.cachedHudTextOrDash ["terminal_after_root_du"; "root_terminal_outcome_du"]
            let liveGraphPhase = CompilerConsoleHud88.cachedHudTextOrDash ["live_graph_phase_du"; "terminal_quorum_after_drain_du"]
            let ownerReason = CompilerConsoleHud88.cachedHudTextOrDash ["terminal_owner_closure_verdict_du"; "owner_debt_still_open_reason_du"; "owner_ledger_quorum_du"; "terminal_owners_du"; "terminal_owners_quorum_du"; "owner_close_results"]
            let rootReceipt = canonicalRoot.receiptId
            let rootReceiptRef : TerminalFlowReceiptRef<TerminalFlowRootReceiptRefKind> = terminalFlowReceiptRefOfText rootReceipt
            let writerLease = CompilerConsoleHud88.cachedHudTextOrDash ["writer_capability_lease_id"]
            let writerReceipt = CompilerConsoleHud88.cachedHudTextOrDash ["writer_receipt_id"; "terminal_writer_receipt_id"]
            let writerReceiptRef : TerminalFlowReceiptRef<TerminalFlowWriterReceiptRefKind> = terminalFlowReceiptRefOfText writerReceipt
            let tailId = CompilerConsoleHud88.cachedHudTextOrDash ["workdag_tail_id"]
            let terminalReceipt = CompilerConsoleHud88.cachedHudTextOrDash ["terminal_commit_receipt_id"; "post_root_breakthrough_certificate_id"; "terminal_receipt_id"]
            let terminalReceiptRef : TerminalFlowReceiptRef<TerminalFlowTerminalReceiptRefKind> = terminalFlowReceiptRefOfText terminalReceipt
            let terminalBoundaryEvidence =
                CompilerConsoleHud88.cachedHudTextOrDash ["terminal_flow_breakthrough_protocol_du"; "terminal_flow_sticky_tail_gate_du"; "terminal_outcome_du"; "terminal_outcome_ivar_intent_du"; "terminal_flow_boundary_action_du"; "why_not_terminal_commit_du"; "terminal_flow_certificate_boundary_du"]
            let ownerDrainDemoted =
                CompilerConsoleHud88.cachedHudTextOrDash ["owner_drain_demoted_to_writer_tail"; "owner_drain_demoted"]
            let rootStatusSignals = terminalFlowObservationSignals rootStatus
            let terminalAfterRootSignals = terminalFlowObservationSignals terminalAfterRoot
            let liveGraphPhaseSignals = terminalFlowObservationSignals liveGraphPhase
            let ownerReasonSignals = terminalFlowObservationSignals ownerReason
            let terminalBoundaryEvidenceSignals = terminalFlowObservationSignals terminalBoundaryEvidence
            let ownerDrainDemotedSignals = terminalFlowObservationSignals ownerDrainDemoted
            let has signal signals = terminalFlowObservationHas signal signals
            let pick fallback value = if String.IsNullOrWhiteSpace value || value = "-" then fallback else value
            let effectiveTerminalFlowAgeMs = max richTickAgeMs writerTailAgeMs
            let canonicalRootResolved =
                match canonicalRoot.phase with
                | DiagJson.CanonicalRootResolved _ -> true
                | _ -> false
            let postRootEvidenceActive =
                canonicalRootResolved
                || has TerminalObservationTerminalAfterRoot terminalAfterRootSignals
                || has TerminalObservationWorkDagTail terminalAfterRootSignals
                || has TerminalObservationWriterLease terminalAfterRootSignals
                || has TerminalObservationPostRoot terminalAfterRootSignals
                || has TerminalObservationBoundaryAction terminalBoundaryEvidenceSignals
                || has TerminalObservationWhyNotTerminalCommit terminalBoundaryEvidenceSignals
            let hudRootClaimsResolved = has TerminalObservationRootPromiseResolved rootStatusSignals
            if hudRootClaimsResolved <> canonicalRootResolved then
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"root_authority_consensus\",\"canonical\":%s,\"hud\":%s,\"consensus\":\"diverged\",\"canonical_receipt_ref\":%u}" [| box (DiagJson.esc (DiagJson.canonicalRootAuthorityText())); box (DiagJson.esc rootStatus); box (NativeCutoverStableRef.ref32 "canonical-root-receipt" [canonicalRoot.receiptId]) |])
            let root =
                match canonicalRoot.phase, rootReceiptRef with
                | DiagJson.CanonicalRootResolved _, TerminalFlowReceiptPresent receiptId -> TerminalFlowRootResolved receiptId
                | DiagJson.CanonicalRootArmed _, _ -> TerminalFlowRootPending
                | DiagJson.CanonicalRootUnarmed, _ -> TerminalFlowRootNotObserved
                | DiagJson.CanonicalRootResolved _, TerminalFlowReceiptMissing ->
                    TerminalFlowRootResolvedWithoutReceipt "canonical_root_resolved_without_receipt_id"
            let writer =
                match writerReceiptRef with
                | TerminalFlowReceiptPresent receiptId -> TerminalFlowWriterBoundObserved receiptId
                | TerminalFlowReceiptMissing
                    when has TerminalObservationBlockedOnQap terminalAfterRootSignals
                      || has TerminalObservationLiveQapDrain terminalAfterRootSignals
                      || has TerminalObservationKeepDraining terminalAfterRootSignals ->
                    TerminalFlowWriterBlockedOnQap(pick "writer-lease:observed" writerLease)
                | TerminalFlowReceiptMissing when not (String.IsNullOrWhiteSpace writerLease) && writerLease <> "-" -> TerminalFlowWriterPending writerLease
                | TerminalFlowReceiptMissing -> TerminalFlowWriterNotObserved
            let tail =
                match terminalReceiptRef with
                | TerminalFlowReceiptPresent receiptId -> TerminalFlowTailTerminalEmittedObserved receiptId
                | TerminalFlowReceiptMissing
                    when has TerminalObservationTailDeadlocked terminalAfterRootSignals
                      || has TerminalObservationDeadlock terminalAfterRootSignals ->
                    TerminalFlowTailDeadlockedObserved(
                        pick "workdag-tail:observed" tailId,
                        CompilerKernelV2.TerminalTailPostRootFlowDeadlock)
                | TerminalFlowReceiptMissing
                    when has TerminalObservationTailQuarantined terminalAfterRootSignals
                      || has TerminalObservationQuarantine terminalAfterRootSignals ->
                    TerminalFlowTailQuarantinedObserved(
                        pick "workdag-tail:observed" tailId,
                        CompilerKernelV2.TerminalTailPostRootFlowQuarantine)
                | TerminalFlowReceiptMissing
                    when has TerminalObservationTailDrained terminalAfterRootSignals
                      || has TerminalObservationWriterBound terminalAfterRootSignals ->
                    TerminalFlowTailDrained(pick "workdag-tail:observed" tailId)
                | TerminalFlowReceiptMissing
                    when has TerminalObservationPendingDrain terminalAfterRootSignals
                      || has TerminalObservationKeepDraining terminalAfterRootSignals ->
                    TerminalFlowTailPendingDrain(pick "workdag-tail:observed" tailId)
                | TerminalFlowReceiptMissing -> TerminalFlowTailUnknown
            let owners =
                if has TerminalObservationTerminalEligible liveGraphPhaseSignals then TerminalFlowOwnersStickyTerminalEligible
                elif has TerminalObservationOwnerDebtNotOpen ownerReasonSignals
                  || has TerminalObservationClosed ownerReasonSignals
                  || has TerminalObservationOwnerLedgerQuorumClosed ownerReasonSignals
                  || has TerminalObservationOwnersNotReopened liveGraphPhaseSignals then TerminalFlowOwnersClosed
                elif has TerminalObservationOpenZeroEq ownerReasonSignals
                  || has TerminalObservationOpenZeroColon ownerReasonSignals then TerminalFlowOwnersClosed
                elif has TerminalObservationMissingWakerEdge ownerReasonSignals
                  || has TerminalObservationZeroDeltaStillOpen ownerReasonSignals
                  || has TerminalObservationCrossKind ownerReasonSignals then
                    TerminalFlowOwnersWakerRegistrationRequired(1L, pick "cross-kind:missing-waker-edge" ownerReason)
                elif postRootEvidenceActive
                  && (has TerminalObservationTrue ownerDrainDemotedSignals
                      || has TerminalObservationWriterTailScheduler terminalAfterRootSignals) then
                    TerminalFlowOwnersQuarantinable(
                        1L,
                        CompilerKernelV2.TerminalOwnerDrainDemotedToWriterTail)
                elif has TerminalObservationOpen ownerReasonSignals then TerminalFlowOwnersOpen 1L
                else TerminalFlowOwnersUnknown
            let rawPendingText = CompilerConsoleHud88.cachedHudTextOrDash ["raw_pending"; "sampled_pending"; "pending"]
            let frontierPendingText = CompilerConsoleHud88.cachedHudTextOrDash ["canonical_pending"; "frontier_pending"; "front_worklist_pending"]
            let parsePending fallback (text:string) =
                let mutable parsed = 0
                let normalized = if isNull text then "" else text.Trim()
                if System.Int32.TryParse(normalized, &parsed) then max 0 parsed else max 0 fallback
            let frontierPendingAvailable =
                not (System.String.IsNullOrWhiteSpace frontierPendingText)
                && frontierPendingText <> "-"
            let sampledRawPending = parsePending pending rawPendingText
            let sampledFrontierPending =
                if frontierPendingAvailable then parsePending 0 frontierPendingText
                else 0
            let reducerHudSnapshot = ReducerHudAuthorityBridge.read ()
            let reducerRetiredCost =
                reducerHudSnapshot.work.semantic.retiredCost
                + reducerHudSnapshot.work.semantic.provenDeadCost
            let reducerClosedProjection =
                match reducerHudSnapshot.phase, reducerHudSnapshot.discovery with
                | CompilerConsoleHud88.ReducerHudTerminalizing, CompilerConsoleHud88.ReducerHudDiscoveryClosed ->
                    canonicalRootResolved
                    && queueDepth = 0
                    && activeDepth = 0
                    && sampledRawPending <= 1
                    && reducerHudSnapshot.work.semantic.totalMid > 0L
                    && reducerRetiredCost = reducerHudSnapshot.work.semantic.totalMid
                    && reducerHudSnapshot.work.semantic.knownRemainingCost = 0L
                    && reducerHudSnapshot.work.semantic.blockedCost = 0L
                    && reducerHudSnapshot.work.semantic.reserveP50Cost = 0L
                    && reducerHudSnapshot.work.semantic.reserveP90Cost = 0L
                    && List.isEmpty reducerHudSnapshot.blockers
                    && not (DiagJson.terminalSemanticAuthorityActiveNow ())
                | _ -> false
            let pendingClosureProof =
                if not frontierPendingAvailable && reducerClosedProjection then
                    let closeReceiptRef =
                        terminalFlowMintedRefOf
                            "pending_frontier_reducer_closed_ref"
                            (FastRuntimeFormat.format "%s|generation=%d|retired=%d|total=%d|raw=%d" [| box rootReceipt; box reducerHudSnapshot.generation; box reducerRetiredCost; box reducerHudSnapshot.work.semantic.totalMid; box sampledRawPending |])
                    TerminalFlowPendingClosureReducerExact closeReceiptRef
                else
                    TerminalFlowPendingClosureUnproven
            let pendingProvenance =
                terminalFlowPendingProvenanceFor
                    sampledRawPending
                    sampledFrontierPending
                    frontierPendingAvailable
                    pendingClosureProof
            match pendingProvenance.authority with
            | TerminalFlowPendingFrontierUnavailableReducerClosed closeReceiptRef ->
                let occurrence, shouldEmit =
                    let reconcileStateKey =
                        FastRuntimeFormat.format "pending_frontier_reducer_closed|raw=%d|frontier=%d|retired=%d|total=%d|queue=%d|active=%d" [| box sampledRawPending; box sampledFrontierPending; box reducerRetiredCost; box reducerHudSnapshot.work.semantic.totalMid; box queueDepth; box activeDepth |]
                    DiagJson.sparseLogDecision reconcileStateKey 64L
                if shouldEmit then
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_pending_frontier_reconciled_by_reducer_close\",\"close_receipt_ref\":%u,\"raw_pending\":%d,\"frontier_pending\":%d,\"canonical_pending\":0,\"reducer_generation\":%d,\"retired_cost\":%d,\"total_cost\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"occurrence_count\":%d,\"authority\":\"exact_reducer_hud_close_projection\",\"next\":\"open_reducer_four_clock_witness\"}" [| box closeReceiptRef; box sampledRawPending; box sampledFrontierPending; box reducerHudSnapshot.generation; box reducerRetiredCost; box reducerHudSnapshot.work.semantic.totalMid; box queueDepth; box activeDepth; box occurrence |])
            | _ -> ()
            let canonicalPending = pendingProvenance.canonicalPending
            let semanticLedgerState = SemanticWorkLedgerProjection.readOperational ()
            let semanticTerminalDebtCount =
                SemanticWorkLedgerProjection.terminalDebtCountOf semanticLedgerState
            let qap = {
                pending = canonicalPending
                pendingProvenance = pendingProvenance
                queue = queueDepth
                active = activeDepth
                semanticLedgerState = semanticLedgerState
                semanticOpen = semanticTerminalDebtCount
                boundedness =
                    if canonicalPending >= 0
                       && canonicalPending <= 3
                       && queueDepth >= 0
                       && queueDepth <= (if postRootEvidenceActive then 32 else 16)
                       && activeDepth >= 0
                       && activeDepth <= 4
                       && semanticTerminalDebtCount = 0L then
                        TerminalFlowQapBounded
                    else
                        TerminalFlowQapUnbounded
                occupancy =
                    if canonicalPending <= 0
                       && queueDepth <= 0
                       && activeDepth <= 0
                       && semanticTerminalDebtCount = 0L then
                        TerminalFlowQapEmpty
                    else
                        TerminalFlowQapResidual
            }
            let activity =
                // MIGRATION: terminal/QAP quiescence follows semantic authority,
                // not raw topology work. Structural exact-once graph credits keep
                // the process deadman alive but cannot postpone a stable semantic
                // fixpoint forever.
                let semanticLedgerAgeMs = DiagJson.terminalSemanticAuthorityAgeMsNow()
                let semanticAuthorityActive = DiagJson.terminalSemanticAuthorityActiveNow()
                let materialAgeMs =
                    if semanticLedgerAgeMs = Int64.MaxValue then max writerTailAgeMs richTickAgeMs
                    else semanticLedgerAgeMs
                let boundarySelfEcho =
                    postRootEvidenceActive
                    && (has TerminalObservationBoundaryAction terminalBoundaryEvidenceSignals
                        || has TerminalObservationWhyNotTerminalCommit terminalBoundaryEvidenceSignals)
                    && not injectionActive
                    && not semanticAuthorityActive
                    && sampledDelta <= 0L
                let procedural =
                    if boundarySelfEcho then
                        Some (terminalFlowProceduralActivityToken TerminalFlowBoundaryTelemetryEcho richTickAgeMs 1L)
                    elif injectionActive then
                        Some (terminalFlowProceduralActivityToken TerminalFlowInjectionChurn (DiagJson.ownerDebtLiveWorkTieBreakerInjectionAgeMsNow()) 1L)
                    elif sampledDelta > 0L then
                        Some (terminalFlowProceduralActivityToken TerminalFlowReplayChatter richTickAgeMs sampledDelta)
                    elif rootDelta > 0L then
                        Some (terminalFlowProceduralActivityToken TerminalFlowRootSignalChurn richTickAgeMs rootDelta)
                    elif terminalDelta > 0L then
                        Some (terminalFlowProceduralActivityToken TerminalFlowTerminalSignalChurn richTickAgeMs terminalDelta)
                    elif has TerminalObservationOwnerDrain ownerReasonSignals
                         || has TerminalObservationMissingWakerEdge ownerReasonSignals
                         || has TerminalObservationZeroDeltaStillOpen ownerReasonSignals then
                        Some (terminalFlowProceduralActivityToken TerminalFlowOwnerDrainSelfChurn richTickAgeMs 1L)
                    else None
                if semanticAuthorityActive then
                    TerminalFlowMaterialActivityRecent(terminalFlowMaterialActivityToken TerminalFlowMaterialDelta materialAgeMs 1L)
                else
                    TerminalFlowMaterialQuiescent(materialAgeMs, procedural)
            {
                root = root
                writer = writer
                tail = tail
                owners = owners
                qap = qap
                activity = activity
            }

        let private terminalFlowNextWakeAfterMs _ageMs _deadlineMs =
            terminalFlowDataflowWakeSentinelMs

        let private terminalFlowQapFixpointTransition rootReceipt leaseId tailId ageMs qap =
            let fixpoint = terminalFlowQapFixpointFromObservation ageMs 4L qap
            let topK = fixpoint.items |> List.map terminalFlowQapFixpointItemText |> String.concat ";"
            match qap.pendingProvenance.authority, fixpoint.maturity, fixpoint.items with
            | TerminalFlowPendingFrontierUnavailableReducerClosed closeReceiptRef,
              TerminalFlowQapFixpointCandidateObserved,
              [] ->
                let emptyOccurrence, emitEmptyClosed =
                    DiagJson.sparseLogDecision
                        ("qap_empty_closed_candidate|" + string closeReceiptRef)
                        64L
                if emitEmptyClosed then
                    DiagJson.emitTerminalJsonDurable (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_qap_empty_closed_candidate\",\"close_receipt_ref\":%u,\"raw_pending\":%d,\"frontier_pending\":%d,\"canonical_pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"material_progress_age_ms\":%d,\"maturity_threshold_ms\":1000,\"relation_count\":0,\"occurrence_count\":%d,\"authority\":\"exact_reducer_close_plus_empty_relation_set\",\"next\":\"await_reducer_four_clock_witness\"}" [| box closeReceiptRef; box qap.pendingProvenance.rawPending; box qap.pendingProvenance.frontierPending; box qap.pendingProvenance.canonicalPending; box qap.queue; box qap.active; box fixpoint.materialQuiescenceAgeMs; box emptyOccurrence |])
            | _ -> ()
            let sparseKey =
                "qap_fixpoint|"
                + terminalFlowQapTerminalDecisionText fixpoint.terminalDecision
                + "|"
                + terminalFlowQapFixpointRefText fixpoint.setRef
            let occurrence, shouldEmit = DiagJson.sparseLogDecision sparseKey 64L
            if shouldEmit then
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_qap_fixpoint_decision\",\"set_ref\":%s,\"top_k\":%s,\"material_progress_age_ms\":%d,\"maturity_du\":%s,\"terminal_mature\":%s,\"boundedness_du\":%s,\"occupancy_du\":%s,\"semantic_ledger_terminal_debt\":%d,\"semantic_ledger_state_du\":%s,\"raw_pending\":%d,\"frontier_pending\":%d,\"canonical_pending\":%d,\"pending_authority_du\":%s,\"pending_decision_du\":%s,\"pending_decrement_receipt_count\":%d,\"pending_decrement_receipts\":%s,\"decision_du\":%s,\"decision_domain_du\":\"TerminalFlowQapTerminalDecision\",\"repeat_basis_du\":\"material_quiescence_seconds_plus_occupancy_floor_plus_semantic_ledger_terminal_debt_zero\",\"occurrence_count\":%d,\"sparse_policy\":\"first3_power2_every64\",\"poison_replay_trampoline_bypassed\":true}" [| box (DiagJson.esc (terminalFlowQapFixpointRefText fixpoint.setRef)); box (DiagJson.esc topK); box fixpoint.materialQuiescenceAgeMs; box (DiagJson.esc (terminalFlowQapFixpointMaturityText fixpoint.maturity)); box (if terminalFlowQapFixpointIsCandidate fixpoint.maturity then "true" else "false"); box (DiagJson.esc (terminalFlowQapBoundednessText qap.boundedness)); box (DiagJson.esc (terminalFlowQapOccupancyText qap.occupancy)); box qap.semanticOpen; box (DiagJson.esc (SemanticWorkLedgerProjection.stateTextOf qap.semanticLedgerState)); box qap.pendingProvenance.rawPending; box qap.pendingProvenance.frontierPending; box qap.pendingProvenance.canonicalPending; box (DiagJson.esc (terminalFlowPendingLedgerAuthorityText qap.pendingProvenance.authority)); box (DiagJson.esc (terminalFlowPendingDecisionText qap.pendingProvenance.decision)); box qap.pendingProvenance.decrementReceipts.Length; box (DiagJson.esc (qap.pendingProvenance.decrementReceipts |> List.map terminalFlowPendingDecrementReceiptText |> String.concat ";")); box (DiagJson.esc (terminalFlowQapTerminalDecisionText fixpoint.terminalDecision)); box occurrence |])
            let fixpointLineage =
                // Eligibility-scoped lineage: stable across queue magnitude churn, but
                // never across bounded/unbounded or empty/residual transitions.  A
                // reducer witness opened while the QAP is bounded therefore cannot
                // seal a later unbounded shape merely because root/lease/tail match.
                FastRuntimeFormat.format "qap-lineage|root=%s|lease=%s|tail=%s|boundedness=%s|occupancy=%s|semantic_ledger_state=%s|semantic_debt=%d" [| box rootReceipt; box leaseId; box tailId; box (terminalFlowQapBoundednessText qap.boundedness); box (terminalFlowQapOccupancyText qap.occupancy); box (SemanticWorkLedgerProjection.stateClassTextOf qap.semanticLedgerState); box qap.semanticOpen |]
            let fixpointShapeRef =
                terminalFlowQapLocalMintedRefOf "qap_fixpoint_shape_ref" (terminalFlowQapFixpointRefText fixpoint.setRef)
            let fixpointReceiptRef =
                TerminalFlowDurableRef(terminalFlowQapLocalMintedRefOf "qap_fixpoint_receipt_ref" fixpointLineage)
            if shouldEmit then
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_qap_fixpoint_lineage_observed\",\"lineage_ref\":%u,\"shape_ref\":%u,\"lineage\":%s,\"set_ref\":%s,\"root\":%s,\"lease\":%s,\"tail\":%s,\"authority\":\"eligibility_scoped_root_lease_tail_lineage\",\"lineage_scope_du\":\"root_lease_tail_plus_boundedness_occupancy\"}" [| box (terminalFlowDurableRefValue fixpointReceiptRef); box fixpointShapeRef; box (DiagJson.esc fixpointLineage); box (DiagJson.esc (terminalFlowQapFixpointRefText fixpoint.setRef)); box (DiagJson.esc rootReceipt); box (DiagJson.esc leaseId); box (DiagJson.esc tailId) |])
            if terminalFlowQapFixpointIsCandidate fixpoint.maturity && shouldEmit then
                // MIGRATION: maturity is transition/heartbeat evidence, not a 500ms
                // projection stream. Reuse the QAP sparse decision so the HUD keeps
                // the banner while JSONL records only state changes and sparse heartbeats.
                // Compact console clock vector: the same append-only line feeds CI,
                // redirected logs and the interactive HUD cache.  It exposes the
                // reducer clocks without copying the large actor/proof payloads.
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"terminal_qap_fixpoint_maturity_candidate\",\"console_lane_du\":\"terminal_qap_clock_vector\",\"fixpoint_ref\":%u,\"shape_ref\":%u,\"lineage_scope_du\":\"root_lease_tail_plus_boundedness_occupancy\",\"boundedness_du\":%s,\"occupancy_du\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"material_progress_age_ms\":%d,\"semantic_epoch\":%d,\"frontier_epoch\":%d,\"frontier_progress_bp\":%d,\"completion_epoch\":%d,\"completed_cost\":%d,\"maturity_du\":%s,\"candidate_mature\":true,\"authoritative\":false,\"required_authority_du\":\"reducer_four_clock_witness\",\"direct_terminal_publication\":false,\"payload_policy_du\":\"compact_clock_vector_no_actor_proof_blob\"}" [| box (terminalFlowDurableRefValue fixpointReceiptRef); box fixpointShapeRef; box (DiagJson.esc (terminalFlowQapBoundednessText qap.boundedness)); box (DiagJson.esc (terminalFlowQapOccupancyText qap.occupancy)); box qap.pending; box qap.queue; box qap.active; box fixpoint.materialQuiescenceAgeMs; box (DiagJson.terminalSemanticAuthorityCountNow()); box (DiagJson.terminalFrontierProgressEpochNow()); box (DiagJson.terminalFrontierProgressBpNow()); box (DiagJson.terminalCompletionCreditEpochNow()); box (DiagJson.terminalCompletionCreditCostNow()); box (DiagJson.esc (terminalFlowQapFixpointMaturityText fixpoint.maturity)) |])
            // The local observer may identify a mature-looking residual, but only the
            // reducer-owned four-clock watch can authorize terminal maturity. Publishing
            // false here prevents a renderer/observer path from bypassing the witness.
            let reducerObservedFixpoint =
                if terminalFlowQapFixpointIsCandidate fixpoint.maturity then
                    { fixpoint with
                        maturity = TerminalFlowQapFixpointAwaitingReducerWitness
                        terminalDecision = TerminalFlowQapAwaitReducerFourClockWitness }
                else fixpoint
            let progressSnapshotSequence = Environment.TickCount64
            let progressSnapshotRef : TerminalFlowIdentityRef<TerminalFlowProgressSnapshotRefKind> =
                terminalFlowIdentityRefOfText (
                    FastRuntimeFormat.format "progress-snapshot:%d:%u:%s" [| box progressSnapshotSequence; box (terminalFlowDurableRefValue fixpointReceiptRef); box (terminalFlowQapFixpointRefText reducerObservedFixpoint.setRef) |])
            let queueItemKindForSite = function
                | TerminalFlowQapCacheHandoffApplyArg0Child
                | TerminalFlowQapDynamicBridgePoison -> TerminalFlowQueueCrossKindReplayDriver
                | TerminalFlowQapParentContinuationPoison -> TerminalFlowQueueParentContinuation
                | TerminalFlowQapPendingOwner -> TerminalFlowQueueProceduralResidual
                | TerminalFlowQapUnknownSite _ -> TerminalFlowQueueProceduralResidual
            let emptyQueueKindCounts : TerminalFlowQueueKindCounts =
                { crossKindReplayDriver = 0L
                  parentContinuation = 0L
                  declaredBodyVerification = 0L
                  universeConstraint = 0L
                  defEqObligation = 0L
                  proceduralResidual = 0L }
            let queueKindCounts : TerminalFlowQueueKindCounts =
                if reducerObservedFixpoint.items.IsEmpty then
                    { emptyQueueKindCounts with
                        crossKindReplayDriver = int64 (max 0 qap.queue)
                        parentContinuation = int64 (max 0 qap.pending)
                        proceduralResidual = int64 (max 0 qap.active) }
                else
                    reducerObservedFixpoint.items
                    |> List.fold (fun counts item ->
                        match queueItemKindForSite item.site with
                        | TerminalFlowQueueCrossKindReplayDriver -> { counts with crossKindReplayDriver = counts.crossKindReplayDriver + 1L }
                        | TerminalFlowQueueParentContinuation -> { counts with parentContinuation = counts.parentContinuation + 1L }
                        | TerminalFlowQueueDeclaredBodyVerification -> { counts with declaredBodyVerification = counts.declaredBodyVerification + 1L }
                        | TerminalFlowQueueUniverseConstraint -> { counts with universeConstraint = counts.universeConstraint + 1L }
                        | TerminalFlowQueueDefEqObligation -> { counts with defEqObligation = counts.defEqObligation + 1L }
                        | TerminalFlowQueueProceduralResidual -> { counts with proceduralResidual = counts.proceduralResidual + 1L })
                        emptyQueueKindCounts
            let syntheticQueueAttributions itemKind count label =
                [ for ordinal in 1 .. min 8 (max 0 count) do
                    let identity = FastRuntimeFormat.format "%s:%d:%u" [| box label; box ordinal; box (terminalFlowIdentityRefDigest progressSnapshotRef) |]
                    yield
                        { itemRef = terminalFlowQueueItemRefOfText ("synthetic-queue-item:" + identity)
                          itemKind = itemKind
                          producerRef = terminalFlowMintedRefOf "progress_queue_item_producer_ref" identity
                          ownerRef = None
                          discoveredAtSnapshotRef = progressSnapshotRef } ]
            let attributedQueueTop =
                if reducerObservedFixpoint.items.IsEmpty then
                    [ yield! syntheticQueueAttributions TerminalFlowQueueCrossKindReplayDriver qap.queue "cross-kind-replay"
                      yield! syntheticQueueAttributions TerminalFlowQueueParentContinuation qap.pending "parent-continuation" ]
                    |> List.truncate 8
                else
                    reducerObservedFixpoint.items
                    |> List.truncate 8
                    |> List.map (fun item ->
                        { itemRef = terminalFlowQueueItemRefOfText (terminalFlowQapFixpointRefText item.itemRef)
                          itemKind = queueItemKindForSite item.site
                          producerRef = terminalFlowMintedRefOf "progress_queue_item_producer_ref" (terminalFlowQapFixpointSiteText item.site)
                          ownerRef = None
                          discoveredAtSnapshotRef = progressSnapshotRef })
            let semanticEpoch = DiagJson.terminalSemanticAuthorityCountNow()
            let semanticReceiptCount = max 0L semanticEpoch
            let canonicalRootCount = if String.IsNullOrWhiteSpace rootReceipt then 0L else 1L
            let semanticDigestRef : TerminalFlowIdentityRef<TerminalFlowSemanticFrontierDigestRefKind> =
                // MIGRATION: semantic identity may not depend on procedural QAP lineage.
                // The previous digest included fixpointLineage, so the same semantic epoch
                // produced different digests whenever cache_handoff/parent_poison counts moved.
                terminalFlowIdentityRefOfText (
                    FastRuntimeFormat.format "semantic-frontier:%s:%d:%d:%d" [| box rootReceipt; box semanticEpoch; box semanticReceiptCount; box canonicalRootCount |])
            let proceduralDigestRef : TerminalFlowIdentityRef<TerminalFlowProceduralFrontierDigestRefKind> =
                terminalFlowIdentityRefOfText ("procedural-frontier:" + fixpointLineage)
            let completedCost = max 0L (DiagJson.terminalCompletionCreditCostNow())
            let discoveredCost =
                max completedCost (
                    completedCost
                    + int64 (max 0 qap.queue)
                    + int64 (max 0 qap.pending)
                    + int64 (max 0 qap.active))
            let progressEvidence =
                { snapshotRef = progressSnapshotRef
                  snapshotSequence = progressSnapshotSequence
                  frontier =
                    { phase = TerminalFlowProgressTerminal
                      discovered = discoveredCost
                      retired = completedCost
                      blocked = int64 (max 0 (qap.queue + qap.pending))
                      queueDepth = int64 (max 0 qap.queue)
                      activeWorkers = int64 (max 0 qap.active)
                      queueKindCounts = queueKindCounts
                      attributedQueueTop = attributedQueueTop }
                  semanticDigest =
                    { digestRef = semanticDigestRef
                      semanticEpoch = semanticEpoch
                      semanticReceiptCount = semanticReceiptCount
                      canonicalRootCount = canonicalRootCount
                      inputCorpusRef = terminalFlowMintedRefOf "progress_input_corpus_ref" rootReceipt }
                  proceduralDigestRef = proceduralDigestRef

                  queueAttributionComplete = true
                  observedAtMs = Environment.TickCount64 }
                |> terminalFlowProgressEvidenceWithActorOwnedLedgers
            // The QAP event pair is asynchronous, but exact terminal evidence may not
            // depend on mailbox timing. Seed the reducer-visible live evidence and its
            // installed control observer synchronously before publishing the pair.
            terminalFlowLiveProgressEvidenceObserve
                TerminalFlowLiveProgressObservedProjectionOnly
                progressEvidence
            terminalFlowObserveProgressProjection progressEvidence
            // The QAP fixpoint consumes this progress snapshot. Publish both through
            // one Hopac job, in causal order, so the control-lane fixpoint cannot
            // overtake its own CompletionFence evidence.
            HopacExtensions.start (
                job {
                    do!
                        terminalFlowGlobalServerPublishJob
                            (TerminalFlowGlobalServerProgressEvidenceObserved progressEvidence)
                    do!
                        terminalFlowGlobalServerPublishJob (
                            TerminalFlowGlobalServerQapFixpointObserved(
                                fixpointReceiptRef,
                                reducerObservedFixpoint,
                                reducerObservedFixpoint.materialQuiescenceAgeMs,
                                TerminalFlowQapMaturityCandidateObserved))
                })
            TerminalFlowTransitionQapFixpointAwaitingMaterial(rootReceipt, leaseId, tailId, reducerObservedFixpoint)

        let private terminalFlowTransitionDecisionForQueueOnly (observation:TerminalFlowObservation) =
            match observation.root, observation.writer, observation.tail, observation.owners, observation.activity with
            | _, _, TerminalFlowTailTerminalEmittedObserved receiptId, _, _ -> TerminalFlowTransitionTerminalEmitted receiptId
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterBoundObserved writerReceipt, TerminalFlowTailDrained tailId, _, _ -> TerminalFlowTransitionBindWriter(rootReceipt, writerReceipt, tailId)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterPending leaseId, TerminalFlowTailDeadlockedObserved(tailId, proof), _, _
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterBlockedOnQap leaseId, TerminalFlowTailDeadlockedObserved(tailId, proof), _, _ -> TerminalFlowTransitionDeadlockTail(rootReceipt, leaseId, tailId, proof)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterPending leaseId, TerminalFlowTailQuarantinedObserved(tailId, reason), _, _
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterBlockedOnQap leaseId, TerminalFlowTailQuarantinedObserved(tailId, reason), _, _ -> TerminalFlowTransitionQuarantineTail(rootReceipt, leaseId, tailId, reason)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterPending leaseId, TerminalFlowTailPendingDrain tailId, _, TerminalFlowMaterialActivityRecent token
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterBlockedOnQap leaseId, TerminalFlowTailPendingDrain tailId, _, TerminalFlowMaterialActivityRecent token
                when terminalFlowQapHasResidual observation.qap
                     && terminalFlowQapIsBounded observation.qap
                     && observation.qap.pending <= terminalFlowWriterLeaseSmallResidualPendingCap ->
                // Opening the watch is not a terminal decision. The semantic
                // epoch guard invalidates it if real authority moves.
                terminalFlowQapFixpointTransition rootReceipt leaseId tailId 0L observation.qap
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterNotObserved, TerminalFlowTailDeadlockedObserved(tailId, _), _, TerminalFlowMaterialActivityRecent token
                when terminalFlowQapHasResidual observation.qap
                     && terminalFlowQapIsBounded observation.qap
                     && observation.qap.pending <= terminalFlowWriterLeaseSmallResidualPendingCap ->
                terminalFlowQapFixpointTransition rootReceipt "writer-lease:qap-watch" tailId 0L observation.qap
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterNotObserved, TerminalFlowTailUnknown, _, TerminalFlowMaterialActivityRecent token
                when terminalFlowQapHasResidual observation.qap
                     && terminalFlowQapIsBounded observation.qap
                     && observation.qap.pending <= terminalFlowWriterLeaseSmallResidualPendingCap ->
                terminalFlowQapFixpointTransition rootReceipt "writer-lease:qap-watch" "workdag-tail:qap-watch" 0L observation.qap
            | _, _, _, _, TerminalFlowMaterialActivityRecent token -> TerminalFlowTransitionDeferMaterialActivity token
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterNotObserved, TerminalFlowTailDeadlockedObserved(tailId, _), _, TerminalFlowMaterialQuiescent(ageMs, _)
                when terminalFlowQapHasResidual observation.qap
                     && terminalFlowQapIsBounded observation.qap
                     && observation.qap.pending <= terminalFlowWriterLeaseSmallResidualPendingCap ->
                terminalFlowQapFixpointTransition rootReceipt "writer-lease:qap-watch" tailId ageMs observation.qap
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterNotObserved, TerminalFlowTailUnknown, _, TerminalFlowMaterialQuiescent(ageMs, _)
                when terminalFlowQapHasResidual observation.qap
                     && terminalFlowQapIsBounded observation.qap
                     && observation.qap.pending <= terminalFlowWriterLeaseSmallResidualPendingCap ->
                terminalFlowQapFixpointTransition rootReceipt "writer-lease:qap-watch" "workdag-tail:qap-watch" ageMs observation.qap
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterNotObserved, TerminalFlowTailUnknown, _, TerminalFlowMaterialQuiescent(ageMs, _)
                when not (terminalFlowQapIsBounded observation.qap) && observation.qap.pending = 0 && (observation.qap.queue >= terminalFlowProceduralPressureQueueThreshold || observation.qap.active >= terminalFlowProceduralPressureActiveThreshold) ->
                terminalFlowQapFixpointTransition rootReceipt "writer-lease:frontier-waker" "workdag-tail:frontier-waker" ageMs observation.qap
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterNotObserved, TerminalFlowTailUnknown, _, TerminalFlowMaterialQuiescent(ageMs, _) when terminalFlowQapHasResidual observation.qap ->
                TerminalFlowTransitionRegisterWakerEdge(rootReceipt, "writer-lease:frontier-waker", "workdag-tail:frontier-waker", "frontier-qap-waker", terminalFlowDataflowWakeSentinelMs)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterPending leaseId, TerminalFlowTailPendingDrain tailId, _, TerminalFlowMaterialQuiescent(ageMs, _)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterBlockedOnQap leaseId, TerminalFlowTailPendingDrain tailId, _, TerminalFlowMaterialQuiescent(ageMs, _)
                when not (terminalFlowQapIsBounded observation.qap) && observation.qap.pending = 0 && (observation.qap.queue >= terminalFlowProceduralPressureQueueThreshold || observation.qap.active >= terminalFlowProceduralPressureActiveThreshold) ->
                terminalFlowQapFixpointTransition rootReceipt leaseId tailId ageMs observation.qap
            | _, _, _, _, _ when not (terminalFlowQapIsBounded observation.qap) -> TerminalFlowTransitionRejectTopology observation.qap
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterPending leaseId, TerminalFlowTailPendingDrain tailId, TerminalFlowOwnersWakerRegistrationRequired(_, obligationId), TerminalFlowMaterialQuiescent(ageMs, _)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterBlockedOnQap leaseId, TerminalFlowTailPendingDrain tailId, TerminalFlowOwnersWakerRegistrationRequired(_, obligationId), TerminalFlowMaterialQuiescent(ageMs, _) ->
                if not (terminalFlowQapHasResidual observation.qap) then TerminalFlowTransitionBindWriter(rootReceipt, "writer-receipt:typed-waker-tail-empty", tailId)
                elif observation.qap.pending <= terminalFlowWriterLeaseSmallResidualPendingCap && (observation.qap.queue >= terminalFlowBoundedProceduralTailPressureQueue || observation.qap.active >= terminalFlowProceduralPressureActiveThreshold) then terminalFlowQapFixpointTransition rootReceipt leaseId tailId ageMs observation.qap
                else TerminalFlowTransitionRegisterWakerEdge(rootReceipt, leaseId, tailId, obligationId, terminalFlowDataflowWakeSentinelMs)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterPending leaseId, TerminalFlowTailPendingDrain tailId, TerminalFlowOwnersWakerRegistrationRejected(_, obligationId, reason), TerminalFlowMaterialQuiescent(ageMs, _)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterBlockedOnQap leaseId, TerminalFlowTailPendingDrain tailId, TerminalFlowOwnersWakerRegistrationRejected(_, obligationId, reason), TerminalFlowMaterialQuiescent(ageMs, _) ->
                TerminalFlowTransitionQuarantineTail(
                    rootReceipt,
                    leaseId,
                    tailId,
                    CompilerKernelV2.TerminalTailQuarantineEvidence(
                        CompilerKernelV2.OperationalReasonIdOps.create (
                            FastRuntimeFormat.format "waker_registration_rejected|obligation=%s|reason=%s|material_age_ms=%d" [| box obligationId; box (CompilerKernelV2.TerminalOwnerWakerRejectionReasonIdOps.text reason); box ageMs |])))
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterPending leaseId, TerminalFlowTailPendingDrain tailId, TerminalFlowOwnersQuarantinable(_, reason), TerminalFlowMaterialQuiescent(ageMs, _)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterBlockedOnQap leaseId, TerminalFlowTailPendingDrain tailId, TerminalFlowOwnersQuarantinable(_, reason), TerminalFlowMaterialQuiescent(ageMs, _)
                when observation.qap.pending = 0 && ageMs >= terminalFlowResidualMaturityMinimumMaterialQuiescenceAgeMs ->
                let ownerCloseReceiptId =
                    FastRuntimeFormat.format "owner-close:force-close:%s:%s:%s:%s" [| box rootReceipt; box leaseId; box tailId; box (CompilerKernelV2.TerminalOwnerQuarantineReasonIdOps.text reason) |]
                let workDagTailCloseReceipt = sprintf "workdag-tail-close:%s:force-close-pass" tailId
                TerminalFlowTransitionForceCloseResidual(rootReceipt, leaseId, tailId, ownerCloseReceiptId, workDagTailCloseReceipt)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterPending leaseId, TerminalFlowTailPendingDrain tailId, TerminalFlowOwnersQuarantinable(_, _), TerminalFlowMaterialQuiescent(ageMs, _)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterBlockedOnQap leaseId, TerminalFlowTailPendingDrain tailId, TerminalFlowOwnersQuarantinable(_, _), TerminalFlowMaterialQuiescent(ageMs, _) ->
                if not (terminalFlowQapHasResidual observation.qap) then TerminalFlowTransitionBindWriter(rootReceipt, "writer-receipt:qap-empty-quarantinable-owner", tailId)
                elif observation.qap.pending <= terminalFlowWriterLeaseSmallResidualPendingCap && (observation.qap.queue >= terminalFlowBoundedProceduralTailPressureQueue || observation.qap.active >= terminalFlowProceduralPressureActiveThreshold) then terminalFlowQapFixpointTransition rootReceipt leaseId tailId ageMs observation.qap
                else TerminalFlowTransitionWriterLeaseLive(rootReceipt, leaseId, tailId, ageMs)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterPending leaseId, TerminalFlowTailPendingDrain tailId, TerminalFlowOwnersClosed, TerminalFlowMaterialQuiescent(ageMs, _)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterBlockedOnQap leaseId, TerminalFlowTailPendingDrain tailId, TerminalFlowOwnersClosed, TerminalFlowMaterialQuiescent(ageMs, _)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterPending leaseId, TerminalFlowTailPendingDrain tailId, TerminalFlowOwnersStickyTerminalEligible, TerminalFlowMaterialQuiescent(ageMs, _)
            | TerminalFlowRootResolved rootReceipt, TerminalFlowWriterBlockedOnQap leaseId, TerminalFlowTailPendingDrain tailId, TerminalFlowOwnersStickyTerminalEligible, TerminalFlowMaterialQuiescent(ageMs, _) ->
                if not (terminalFlowQapHasResidual observation.qap) then TerminalFlowTransitionBindWriter(rootReceipt, "writer-receipt:qap-empty", tailId)
                elif observation.qap.pending <= terminalFlowWriterLeaseSmallResidualPendingCap && observation.qap.queue >= terminalFlowBoundedProceduralTailPressureQueue && observation.qap.active <= terminalFlowProceduralPressureActiveThreshold then terminalFlowQapFixpointTransition rootReceipt leaseId tailId ageMs observation.qap
                else TerminalFlowTransitionWriterLeaseLive(rootReceipt, leaseId, tailId, ageMs)
            | _ -> TerminalFlowTransitionObserve

        let private terminalFlowOutcomeForTransition = function
            | TerminalFlowTransitionTerminalEmitted receiptId -> TerminalFlowOutcomeTerminalEmitted receiptId
            | TerminalFlowTransitionBindWriter(rootReceipt, writerReceiptId, tailId) -> TerminalFlowOutcomeWriterBound(rootReceipt, writerReceiptId, tailId)
            | TerminalFlowTransitionDeadlockTail(rootReceipt, leaseId, tailId, proof) -> TerminalFlowOutcomeTailDeadlocked(rootReceipt, leaseId, tailId, proof)
            | TerminalFlowTransitionQuarantineTail(rootReceipt, leaseId, tailId, reason) -> TerminalFlowOutcomeTailQuarantined(rootReceipt, leaseId, tailId, reason)
            | TerminalFlowTransitionWriterLeaseExpired(rootReceipt, leaseId, tailId, ageMs, qap) ->
                TerminalFlowOutcomeTailDeadlocked(
                    rootReceipt,
                    leaseId,
                    tailId,
                    CompilerKernelV2.TerminalTailWriterLeaseExpired(
                        ageMs,
                        CompilerKernelV2.OperationalReasonIdOps.create (terminalFlowQapObservationText qap)))
            | TerminalFlowTransitionQuarantineResidualQap(rootReceipt, leaseId, tailId, ageMs, qap) ->
                TerminalFlowOutcomeTailQuarantined(
                    rootReceipt,
                    leaseId,
                    tailId,
                    CompilerKernelV2.TerminalTailResidualQapQuarantine(
                        ageMs,
                        CompilerKernelV2.OperationalReasonIdOps.create (terminalFlowQapObservationText qap)))
            | TerminalFlowTransitionQapFixpointMatured(rootReceipt, leaseId, tailId, fixpoint) ->
                TerminalFlowOutcomeTailQuarantined(
                    rootReceipt,
                    leaseId,
                    tailId,
                    CompilerKernelV2.TerminalTailQapFixpointTerminal(
                        CompilerKernelV2.OperationalReasonIdOps.create (terminalFlowQapFixpointSetText fixpoint)))
            | TerminalFlowTransitionQapFixpointAwaitingMaterial(rootReceipt, leaseId, tailId, fixpoint) ->
                TerminalFlowOutcomeAwaitingObservation(
                    TerminalFlowAwaitingQapFixpointMaterial(rootReceipt, leaseId, tailId, fixpoint))
            | TerminalFlowTransitionForceCloseResidual(rootReceipt, _, tailId, ownerCloseReceiptId, workDagTailCloseReceipt) ->
                TerminalFlowOutcomeWriterBound(rootReceipt, "writer-receipt:force-close-owner:" + ownerCloseReceiptId + ":" + workDagTailCloseReceipt, tailId)
            | TerminalFlowTransitionRegisterWakerEdge(rootReceipt, leaseId, tailId, obligationId, nextWakeAfterMs) -> TerminalFlowOutcomeWakerRegistrationRequired(rootReceipt, leaseId, tailId, obligationId, nextWakeAfterMs)
            | TerminalFlowTransitionWriterLeaseLive(rootReceipt, leaseId, tailId, ageMs) -> TerminalFlowOutcomeWriterLeaseStillLive(rootReceipt, leaseId, tailId, ageMs)
            | TerminalFlowTransitionDeferMaterialActivity token ->
                TerminalFlowOutcomeAwaitingObservation(TerminalFlowAwaitingRecentMaterialActivity token)
            | TerminalFlowTransitionRejectTopology qap ->
                TerminalFlowOutcomeAwaitingObservation(TerminalFlowAwaitingRejectedTopology qap)
            | TerminalFlowTransitionObserve ->
                TerminalFlowOutcomeAwaitingObservation TerminalFlowAwaitingGenericObservation

        let private terminalFlowOutcomeIsTerminalLike = function
            | TerminalFlowOutcomeWriterBound _
            | TerminalFlowOutcomeTailDeadlocked _
            | TerminalFlowOutcomeTailQuarantined _
            | TerminalFlowOutcomeTerminalEmitted _ -> true
            | TerminalFlowOutcomeWakerRegistrationRequired _
            | TerminalFlowOutcomeWriterLeaseStillLive _
            | TerminalFlowOutcomeAwaitingObservation _ -> false

        let private queueOnlyParentContinuationRecoveryDecisionText = function
            | QueueOnlyParentContinuationRecoveryObserve -> "observe"
            | QueueOnlyParentContinuationRecoveryDeferRecentSemanticActivity -> "defer_recent_semantic_activity"
            | QueueOnlyParentContinuationRecoveryRejectTopology -> "reject_topology"
            | QueueOnlyParentContinuationRecoveryReady -> "ready_quiescent_queue_reentry"

        let private queueOnlyParentContinuationRecoveryDecisionShouldAttempt = function
            | QueueOnlyParentContinuationRecoveryReady -> true
            | QueueOnlyParentContinuationRecoveryObserve
            | QueueOnlyParentContinuationRecoveryDeferRecentSemanticActivity
            | QueueOnlyParentContinuationRecoveryRejectTopology -> false

        let private queueOnlyParentContinuationRecoveryMinWaitMs = 30000L
        let private queueOnlyParentContinuationRecoveryMinRepeatCount = 16L
        let private queueOnlyParentContinuationRecoveryMinRichStaleAgeMs = 15000L

        let private queueOnlyParentContinuationRecoveryDecisionFor waitedMs pending queueDepth activeDepth tieBreakerCount injectionActive materialDeltaActive sampledDelta rootDelta terminalDelta richTickAgeMs replayComplete writeWitness =
            if replayComplete || writeWitness then
                QueueOnlyParentContinuationRecoveryObserve
            elif waitedMs < queueOnlyParentContinuationRecoveryMinWaitMs
                 || tieBreakerCount < queueOnlyParentContinuationRecoveryMinRepeatCount
                 || richTickAgeMs < queueOnlyParentContinuationRecoveryMinRichStaleAgeMs then
                QueueOnlyParentContinuationRecoveryObserve
            elif injectionActive || materialDeltaActive || sampledDelta > 0L || rootDelta > 0L || terminalDelta > 0L then
                QueueOnlyParentContinuationRecoveryDeferRecentSemanticActivity
            elif pending <= 0 || pending > 3 || queueDepth < 0 || queueDepth > 16 || activeDepth < 0 || activeDepth > 4 then
                QueueOnlyParentContinuationRecoveryRejectTopology
            else
                QueueOnlyParentContinuationRecoveryReady

        let private postRootQueueOnlyRecoveryAuthorityFor pending queueDepth activeDepth injectionActive materialDeltaActive sampledDelta rootDelta terminalDelta richTickAgeMs writerTailAgeMs replayComplete writeWitness =
            let observation =
                terminalFlowObservationFromPostRootQueueOnly
                    pending
                    queueDepth
                    activeDepth
                    injectionActive
                    materialDeltaActive
                    sampledDelta
                    rootDelta
                    terminalDelta
                    richTickAgeMs
                    writerTailAgeMs
            let transition = terminalFlowTransitionDecisionForQueueOnly observation
            let outcome = terminalFlowOutcomeForTransition transition
            let boundary =
                match transition with
                | TerminalFlowTransitionDeferMaterialActivity token -> TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRecentMaterialActivity token)
                | TerminalFlowTransitionRegisterWakerEdge(_, _, _, obligationId, nextWakeAfterMs) -> TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotWakerRegistrationRequired(obligationId, nextWakeAfterMs))
                | TerminalFlowTransitionRejectTopology qap -> TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRejectedTopology qap)
                | TerminalFlowTransitionObserve ->
                    match observation.root with
                    | TerminalFlowRootResolvedWithoutReceipt evidence -> TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotMissingRootReceipt evidence)
                    | _ -> terminalFlowCertificateBoundaryForOutcome outcome
                | _ -> terminalFlowCertificateBoundaryForOutcome outcome
            match transition, outcome, boundary with
            | _, _, _ when replayComplete || writeWitness -> QueueOnlyRecoveryPreRootOrUnarmed
            | TerminalFlowTransitionForceCloseResidual(rootReceipt, leaseId, tailId, ownerCloseReceiptId, workDagTailCloseReceipt), _, _ ->
                QueueOnlyRecoveryReadyAfterForceOwnerClose(rootReceipt, leaseId, tailId, ownerCloseReceiptId, workDagTailCloseReceipt)
            | TerminalFlowTransitionObserve, _, TerminalFlowBoundaryWhyNotCommit _ -> QueueOnlyRecoveryTerminalFlowBoundary(observation, transition, outcome, boundary)
            | TerminalFlowTransitionDeferMaterialActivity _, _, TerminalFlowBoundaryWhyNotCommit _ -> QueueOnlyRecoveryTerminalFlowBoundary(observation, transition, outcome, boundary)
            | TerminalFlowTransitionRejectTopology _, _, TerminalFlowBoundaryWhyNotCommit _ -> QueueOnlyRecoveryTerminalFlowBoundary(observation, transition, outcome, boundary)
            | TerminalFlowTransitionObserve, _, _ -> QueueOnlyRecoveryPreRootOrUnarmed
            | _, _, _ -> QueueOnlyRecoveryTerminalFlowBoundary(observation, transition, outcome, boundary)

        let private queueOnlyParentContinuationRecoveryDecisionWithPostRootAuthority fallback authorityId =
            match fallback, authorityId with
            | QueueOnlyParentContinuationRecoveryReady, _ -> QueueOnlyParentContinuationRecoveryReady
            | _, QueueOnlyRecoveryReadyPostRootTerminalFlow _ -> QueueOnlyParentContinuationRecoveryReady
            | _, QueueOnlyRecoveryReadyAfterForceOwnerClose _ -> QueueOnlyParentContinuationRecoveryReady
            | _, QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, boundary) when terminalFlowCertificateBoundaryIsReceipt boundary -> QueueOnlyParentContinuationRecoveryReady
            | _, QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotAwaitingBoundedLease _)) -> QueueOnlyParentContinuationRecoveryObserve
            | _, QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotAwaitingObservation _)) -> QueueOnlyParentContinuationRecoveryObserve
            | _, QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotWakerRegistrationRequired _)) -> QueueOnlyParentContinuationRecoveryObserve
            | _, QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRecentMaterialActivity _)) -> QueueOnlyParentContinuationRecoveryDeferRecentSemanticActivity
            | _, QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRejectedTopology _)) -> QueueOnlyParentContinuationRecoveryRejectTopology
            | _, QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, TerminalFlowBoundaryWhyNotCommit _) -> QueueOnlyParentContinuationRecoveryObserve
            | _, QueueOnlyRecoveryTerminalFlowOutcome(_, _, outcome) when terminalFlowOutcomeIsTerminalLike outcome -> QueueOnlyParentContinuationRecoveryReady
            | _, QueueOnlyRecoveryTerminalFlowOutcome(_, _, TerminalFlowOutcomeWakerRegistrationRequired _) -> QueueOnlyParentContinuationRecoveryObserve
            | _, QueueOnlyRecoveryTerminalFlowOutcome(_, _, TerminalFlowOutcomeWriterLeaseStillLive _) -> QueueOnlyParentContinuationRecoveryObserve
            | _, QueueOnlyRecoveryTerminalFlowOutcome(_, _, TerminalFlowOutcomeAwaitingObservation _) -> QueueOnlyParentContinuationRecoveryObserve
            | _, QueueOnlyRecoveryTerminalFlowTransition(_, TerminalFlowTransitionRegisterWakerEdge _) -> QueueOnlyParentContinuationRecoveryObserve
            | _, QueueOnlyRecoveryTerminalFlowTransition(_, TerminalFlowTransitionWriterLeaseLive _) -> QueueOnlyParentContinuationRecoveryObserve
            | _, QueueOnlyRecoveryTerminalFlowTransition(_, TerminalFlowTransitionWriterLeaseExpired _) -> QueueOnlyParentContinuationRecoveryReady
            | _, QueueOnlyRecoveryTerminalFlowTransition(_, TerminalFlowTransitionQuarantineResidualQap _) -> QueueOnlyParentContinuationRecoveryReady
            | _, QueueOnlyRecoveryTerminalFlowTransition(_, TerminalFlowTransitionBindWriter _) -> QueueOnlyParentContinuationRecoveryReady
            | _, QueueOnlyRecoveryTerminalFlowTransition(_, TerminalFlowTransitionDeadlockTail _) -> QueueOnlyParentContinuationRecoveryReady
            | _, QueueOnlyRecoveryTerminalFlowTransition(_, TerminalFlowTransitionQuarantineTail _) -> QueueOnlyParentContinuationRecoveryReady
            | _, QueueOnlyRecoveryTerminalFlowTransition(_, TerminalFlowTransitionTerminalEmitted _) -> QueueOnlyParentContinuationRecoveryObserve
            | _, QueueOnlyRecoveryTerminalFlowTransition(_, TerminalFlowTransitionDeferMaterialActivity _) -> QueueOnlyParentContinuationRecoveryDeferRecentSemanticActivity
            | _, QueueOnlyRecoveryTerminalFlowTransition(_, TerminalFlowTransitionRejectTopology _) -> QueueOnlyParentContinuationRecoveryRejectTopology
            | _, QueueOnlyRecoveryRecentSemanticActivity _ -> QueueOnlyParentContinuationRecoveryDeferRecentSemanticActivity
            | _, QueueOnlyRecoveryTopologyRejected _ -> QueueOnlyParentContinuationRecoveryRejectTopology
            | _ -> fallback

        // Level-triggered terminal server contract.  The current
        // join loop remains the interpreter for this round, but the decision
        // now carries an explicit wake cause and deadline instead of relying on
        // another incidental scheduler event to re-evaluate true quiescence.
        type TerminalFlowWakeReasonId =
            | TerminalFlowWakeOnSchedulerEvent
            | TerminalFlowWakeOnMaterialQuiescenceDeadline
            | TerminalFlowWakeOnWakerRegistrationDeadline
            | TerminalFlowWakeOnWriterLeaseDeadline
            | TerminalFlowWakeTerminalBoundaryReady

        type TerminalFlowWakePlan = private {
            reason : TerminalFlowWakeReasonId
            afterMs : int64
            levelTriggered : bool
        }

        type TerminalFlowLocalJoinWaitKind =
            | TerminalFlowLocalJoinWaitRootReceipt
            | TerminalFlowLocalJoinWaitTerminalOutcome
            | TerminalFlowLocalJoinWaitSchedulerPush
            | TerminalFlowLocalJoinWaitWriterLease
            | TerminalFlowLocalJoinWaitPhysicalDeadman

        type TerminalFlowLocalJoinWaitContract = private {
            waitKind : TerminalFlowLocalJoinWaitKind
            receiptRef : uint32
            dataflowOnly : bool
            pollAfterMs : int64 option
        }

        let private terminalFlowLocalJoinWaitKindText = function
            | TerminalFlowLocalJoinWaitRootReceipt -> "root_receipt"
            | TerminalFlowLocalJoinWaitTerminalOutcome -> "terminal_outcome"
            | TerminalFlowLocalJoinWaitSchedulerPush -> "scheduler_push"
            | TerminalFlowLocalJoinWaitWriterLease -> "writer_lease"
            | TerminalFlowLocalJoinWaitPhysicalDeadman -> "physical_deadman"

        let private terminalFlowLocalJoinWaitText (contract:TerminalFlowLocalJoinWaitContract) =
            let pollText = match contract.pollAfterMs with | Some ms -> string ms | None -> "none"
            FastRuntimeFormat.format "TerminalFlowLocalJoinWait(kind=%s|receipt_ref=%u|dataflow_only=%b|poll_after_ms=%s)" [| box (terminalFlowLocalJoinWaitKindText contract.waitKind); box contract.receiptRef; box contract.dataflowOnly; box pollText |]

        let private terminalFlowLocalDataflowWait kind receiptId =
            { waitKind = kind
              receiptRef = NativeCutoverStableRef.ref32 "terminal-receipt-id" [receiptId]
              dataflowOnly = true
              pollAfterMs = None }

        let private terminalFlowWakeReasonText = function
            | TerminalFlowWakeOnSchedulerEvent -> "scheduler_event"
            | TerminalFlowWakeOnMaterialQuiescenceDeadline -> "material_quiescence_deadline"
            | TerminalFlowWakeOnWakerRegistrationDeadline -> "waker_registration_deadline"
            | TerminalFlowWakeOnWriterLeaseDeadline -> "writer_lease_deadline"
            | TerminalFlowWakeTerminalBoundaryReady -> "terminal_boundary_ready"

        let private terminalFlowWakePlanText (plan:TerminalFlowWakePlan) =
            FastRuntimeFormat.format "TerminalFlowWakePlan(reason=%s|after_ms=%d|level_triggered=%b)" [| box (terminalFlowWakeReasonText plan.reason); box plan.afterMs; box plan.levelTriggered |]

        type TerminalFlowSchedulerEventId =
            | TerminalFlowSchedulerEventBoundaryObserved
            | TerminalFlowSchedulerEventMaterialDelta
            | TerminalFlowSchedulerEventProceduralChurn
            | TerminalFlowSchedulerEventWakeRegistration
            | TerminalFlowSchedulerEventWriterLeaseDeadline
            | TerminalFlowSchedulerEventPhysicalDeadman

        type TerminalFlowServerOrderSlotId =
            | TerminalFlowServerOrderSchedulerEvent
            | TerminalFlowServerOrderWakeTimeout
            | TerminalFlowServerOrderWriterLeaseTimeout
            | TerminalFlowServerOrderDeadmanTimeout
            | TerminalFlowServerOrderReceiptEmission

        type TerminalFlowServerCommandId =
            | TerminalFlowServerObserveOnly of CompilerKernelV2.OperationalReasonId
            | TerminalFlowServerEmitBoundaryReceipt of receipt:string
            | TerminalFlowServerBlockCommit of CompilerKernelV2.OperationalReasonId
            | TerminalFlowServerEscalateDeadmanIntoReceipt of CompilerKernelV2.OperationalReasonId

        let private terminalFlowServerObserveOnly reason =
            TerminalFlowServerObserveOnly(CompilerKernelV2.OperationalReasonIdOps.create reason)

        let private terminalFlowServerBlockCommit whyNot =
            TerminalFlowServerBlockCommit(CompilerKernelV2.OperationalReasonIdOps.create whyNot)

        type TerminalFlowServerPlan = private {
            eventId : TerminalFlowSchedulerEventId
            orderSlot : TerminalFlowServerOrderSlotId
            command : TerminalFlowServerCommandId
            wakePlan : TerminalFlowWakePlan
        }

        let private terminalFlowSchedulerEventText = function
            | TerminalFlowSchedulerEventBoundaryObserved -> "boundary_observed"
            | TerminalFlowSchedulerEventMaterialDelta -> "material_delta"
            | TerminalFlowSchedulerEventProceduralChurn -> "procedural_churn"
            | TerminalFlowSchedulerEventWakeRegistration -> "wake_registration"
            | TerminalFlowSchedulerEventWriterLeaseDeadline -> "writer_lease_deadline"
            | TerminalFlowSchedulerEventPhysicalDeadman -> "physical_deadman"

        let private terminalFlowServerOrderSlotText = function
            | TerminalFlowServerOrderSchedulerEvent -> "scheduler_event"
            | TerminalFlowServerOrderWakeTimeout -> "wake_timeout"
            | TerminalFlowServerOrderWriterLeaseTimeout -> "writer_lease_timeout"
            | TerminalFlowServerOrderDeadmanTimeout -> "deadman_timeout"
            | TerminalFlowServerOrderReceiptEmission -> "receipt_emission"

        let private terminalFlowServerCommandText = function
            | TerminalFlowServerObserveOnly reason -> "TerminalFlowServerCommand(ObserveOnly|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | TerminalFlowServerEmitBoundaryReceipt receipt -> "TerminalFlowServerCommand(EmitBoundaryReceipt|receipt=" + receipt + ")"
            | TerminalFlowServerBlockCommit whyNot -> "TerminalFlowServerCommand(BlockCommit|why_not=" + CompilerKernelV2.OperationalReasonIdOps.text whyNot + ")"
            | TerminalFlowServerEscalateDeadmanIntoReceipt reason -> "TerminalFlowServerCommand(EscalateDeadmanIntoReceipt|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let private terminalFlowServerPlanText (plan:TerminalFlowServerPlan) =
            FastRuntimeFormat.format "TerminalFlowServerPlan(event=%s|slot=%s|cmd=%s|wake=%s)" [| box (terminalFlowSchedulerEventText plan.eventId); box (terminalFlowServerOrderSlotText plan.orderSlot); box (terminalFlowServerCommandText plan.command); box (terminalFlowWakePlanText plan.wakePlan) |]

        type TerminalFlowServerSelectedArmId =
            | TerminalFlowServerArmReceiptEmission
            | TerminalFlowServerArmDeadmanTimeout
            | TerminalFlowServerArmSchedulerEvent

        type TerminalFlowServerLoopActionId =
            | TerminalFlowServerLoopEmitReceipt of receipt:string
            | TerminalFlowServerLoopBlockCommit of CompilerKernelV2.OperationalReasonId
            | TerminalFlowServerLoopEscalateDeadmanIntoReceipt of CompilerKernelV2.OperationalReasonId
            | TerminalFlowServerLoopObserveScheduler of CompilerKernelV2.OperationalReasonId

        type TerminalFlowServerLoopFrame = private {
            plan : TerminalFlowServerPlan
            selectedArm : TerminalFlowServerSelectedArmId
            action : TerminalFlowServerLoopActionId
        }

        let private terminalFlowServerSelectedArmText = function
            | TerminalFlowServerArmReceiptEmission -> "receipt_emission"
            | TerminalFlowServerArmDeadmanTimeout -> "deadman_timeout"
            | TerminalFlowServerArmSchedulerEvent -> "scheduler_event"

        let private terminalFlowServerLoopActionText = function
            | TerminalFlowServerLoopEmitReceipt receipt -> "TerminalFlowServerLoopAction(EmitReceipt|receipt=" + receipt + ")"
            | TerminalFlowServerLoopBlockCommit whyNot -> "TerminalFlowServerLoopAction(BlockCommit|why_not=" + CompilerKernelV2.OperationalReasonIdOps.text whyNot + ")"
            | TerminalFlowServerLoopEscalateDeadmanIntoReceipt reason -> "TerminalFlowServerLoopAction(EscalateDeadmanIntoReceipt|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | TerminalFlowServerLoopObserveScheduler reason -> "TerminalFlowServerLoopAction(ObserveScheduler|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let private terminalFlowServerLoopFrameText (frame:TerminalFlowServerLoopFrame) =
            FastRuntimeFormat.format "TerminalFlowServerLoopFrame(arm=%s|action=%s|dataflow_only=true|plan=%s)" [| box (terminalFlowServerSelectedArmText frame.selectedArm); box (terminalFlowServerLoopActionText frame.action); box (terminalFlowServerPlanText frame.plan) |]

        let private terminalFlowServerLoopFrameFor _waitedMs _richTickAgeMs (plan:TerminalFlowServerPlan) =
            let selectedArm =
                match plan.command, plan.orderSlot with
                | TerminalFlowServerEmitBoundaryReceipt _, _ -> TerminalFlowServerArmReceiptEmission
                | TerminalFlowServerEscalateDeadmanIntoReceipt _, _ -> TerminalFlowServerArmDeadmanTimeout
                | TerminalFlowServerBlockCommit _, TerminalFlowServerOrderDeadmanTimeout -> TerminalFlowServerArmDeadmanTimeout
                | TerminalFlowServerBlockCommit _, _ -> TerminalFlowServerArmSchedulerEvent
                | TerminalFlowServerObserveOnly _, _ -> TerminalFlowServerArmSchedulerEvent
            let action =
                match plan.command with
                | TerminalFlowServerEmitBoundaryReceipt receipt -> TerminalFlowServerLoopEmitReceipt receipt
                | TerminalFlowServerBlockCommit whyNot -> TerminalFlowServerLoopBlockCommit whyNot
                | TerminalFlowServerEscalateDeadmanIntoReceipt reason -> TerminalFlowServerLoopEscalateDeadmanIntoReceipt reason
                | TerminalFlowServerObserveOnly reason -> TerminalFlowServerLoopObserveScheduler reason
            { plan = plan
              selectedArm = selectedArm
              action = action }

        type TerminalFlowBreakthroughProtocolId =
            | TerminalFlowBreakthroughCommitReady of receiptId:string * ivarKey:string * selectedArm:TerminalFlowServerSelectedArmId
            | TerminalFlowBreakthroughNeedsMutatingStickyTail of CompilerKernelV2.OperationalReasonId
            | TerminalFlowBreakthroughRegisterWakerEdge of obligationId:string * afterMs:int64
            | TerminalFlowBreakthroughQuarantineProceduralResidual of CompilerKernelV2.OperationalReasonId
            | TerminalFlowBreakthroughBlockCommit of CompilerKernelV2.OperationalReasonId
            | TerminalFlowBreakthroughEscalateDeadmanReceipt of CompilerKernelV2.OperationalReasonId
            | TerminalFlowBreakthroughObserveServer of CompilerKernelV2.OperationalReasonId

        [<Struct>]
        type TerminalFlowBreakthroughExitSealedState = struct end

        type TerminalFlowBreakthroughExitAuthority<'State> = private | TerminalFlowBreakthroughExitAuthority of receiptId:string * ivarKey:string * selectedArm:TerminalFlowServerSelectedArmId

        let private terminalFlowBreakthroughExitAuthorityFor = function
            | TerminalFlowBreakthroughCommitReady(receiptId, ivarKey, selectedArm)
                when not (String.IsNullOrWhiteSpace receiptId)
                     && not (String.IsNullOrWhiteSpace ivarKey) ->
                Some (TerminalFlowBreakthroughExitAuthority(receiptId, ivarKey, selectedArm) : TerminalFlowBreakthroughExitAuthority<TerminalFlowBreakthroughExitSealedState>)
            | _ -> None

        let private terminalFlowBreakthroughExitAuthorityText = function
            | Some (TerminalFlowBreakthroughExitAuthority(receiptId, ivarKey, selectedArm)) ->
                "TerminalFlowBreakthroughExitAuthority(Sealed|receipt=" + receiptId + "|ivar_key=" + ivarKey + "|arm=" + terminalFlowServerSelectedArmText selectedArm + ")"
            | None -> "TerminalFlowBreakthroughExitAuthority(NotSealed)"

        let private terminalFlowBreakthroughProtocolText = function
            | TerminalFlowBreakthroughCommitReady(receiptId, ivarKey, selectedArm) ->
                "TerminalFlowBreakthroughProtocol(CommitReady|receipt=" + receiptId + "|ivar_key=" + ivarKey + "|arm=" + terminalFlowServerSelectedArmText selectedArm + ")"
            | TerminalFlowBreakthroughNeedsMutatingStickyTail reason ->
                "TerminalFlowBreakthroughProtocol(NeedsMutatingStickyTail|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | TerminalFlowBreakthroughRegisterWakerEdge(obligationId, afterMs) ->
                sprintf "TerminalFlowBreakthroughProtocol(RegisterWakerEdge|obligation=%s|after_ms=%d)" obligationId afterMs
            | TerminalFlowBreakthroughQuarantineProceduralResidual reason ->
                "TerminalFlowBreakthroughProtocol(QuarantineProceduralResidual|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | TerminalFlowBreakthroughBlockCommit reason ->
                "TerminalFlowBreakthroughProtocol(BlockCommit|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | TerminalFlowBreakthroughEscalateDeadmanReceipt reason ->
                "TerminalFlowBreakthroughProtocol(EscalateDeadmanReceipt|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
            | TerminalFlowBreakthroughObserveServer reason ->
                "TerminalFlowBreakthroughProtocol(ObserveServer|reason=" + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

        let private terminalFlowBreakthroughProtocolFor stickyTailGate terminalOutcome _ivarIntent (serverFrame:TerminalFlowServerLoopFrame) =
            // MIGRATION compile rescue: the old IVAR-intent DU was erased by the
            // scheduler-push corridor.  This legacy projection is diagnostic only;
            // it can no longer fabricate writer capability or physical exit.
            match stickyTailGate, serverFrame.action with
            | gate, _ when terminalFlowStickyTailGateIsTerminalReady gate
                       && terminalFlowTerminalOutcomeHasDurableReceipt terminalOutcome ->
                TerminalFlowBreakthroughCommitReady(
                    terminalFlowTerminalOutcomeTerminalCommitReceiptId terminalOutcome,
                    terminalFlowTerminalOutcomeFillKey terminalOutcome,
                    serverFrame.selectedArm)
            | TerminalFlowStickyTailQuarantineProceduralResidual(_, reason), _ ->
                TerminalFlowBreakthroughQuarantineProceduralResidual reason
            | _, TerminalFlowServerLoopBlockCommit reason ->
                TerminalFlowBreakthroughBlockCommit reason
            | TerminalFlowStickyTailAwaitMutatingAggregate snapshot, _ ->
                TerminalFlowBreakthroughNeedsMutatingStickyTail(CompilerKernelV2.OperationalReasonIdOps.create (terminalFlowStickyTailSnapshotText snapshot))
            | TerminalFlowStickyTailRejectUnboundedMutatingTail(_, reason), _ ->
                TerminalFlowBreakthroughBlockCommit(CompilerKernelV2.OperationalReasonIdOps.create ("unbounded_mutating_tail|" + CompilerKernelV2.OperationalReasonIdOps.text reason))
            | _, TerminalFlowServerLoopEscalateDeadmanIntoReceipt reason ->
                TerminalFlowBreakthroughEscalateDeadmanReceipt reason
            | _, TerminalFlowServerLoopObserveScheduler reason ->
                TerminalFlowBreakthroughObserveServer reason
            | _, TerminalFlowServerLoopEmitReceipt receipt ->
                TerminalFlowBreakthroughCommitReady(receipt, "server-emit-boundary-receipt", serverFrame.selectedArm)

        let private terminalFlowBreakthroughProtocolAllowsPhysicalExit = function
            | TerminalFlowBreakthroughCommitReady _ -> true
            | _ -> false

        let private terminalFlowWakePlanForAuthority = function
            | QueueOnlyRecoveryReadyAfterForceOwnerClose _ ->
                { reason = TerminalFlowWakeTerminalBoundaryReady; afterMs = 0L; levelTriggered = true }
            | QueueOnlyRecoveryTerminalFlowBoundary(_, TerminalFlowTransitionRegisterWakerEdge(_, _, _, _, _), _, _) ->
                { reason = TerminalFlowWakeOnSchedulerEvent; afterMs = terminalFlowDataflowWakeSentinelMs; levelTriggered = false }
            | QueueOnlyRecoveryTerminalFlowBoundary(_, TerminalFlowTransitionDeferMaterialActivity _, _, _) ->
                { reason = TerminalFlowWakeOnSchedulerEvent; afterMs = terminalFlowDataflowWakeSentinelMs; levelTriggered = false }
            | QueueOnlyRecoveryTerminalFlowBoundary(_, TerminalFlowTransitionWriterLeaseLive(_, _, _, _), _, _) ->
                { reason = TerminalFlowWakeOnSchedulerEvent; afterMs = terminalFlowDataflowWakeSentinelMs; levelTriggered = false }
            | QueueOnlyRecoveryTerminalFlowBoundary(_, TerminalFlowTransitionRejectTopology _, _, _) ->
                { reason = TerminalFlowWakeOnSchedulerEvent; afterMs = terminalFlowDataflowWakeSentinelMs; levelTriggered = false }
            | QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, TerminalFlowBoundaryReceipt _) ->
                { reason = TerminalFlowWakeTerminalBoundaryReady; afterMs = 0L; levelTriggered = true }
            | QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRejectedTopology _)) ->
                { reason = TerminalFlowWakeOnSchedulerEvent; afterMs = terminalFlowDataflowWakeSentinelMs; levelTriggered = false }
            | _ ->
                { reason = TerminalFlowWakeOnSchedulerEvent; afterMs = terminalFlowDataflowWakeSentinelMs; levelTriggered = false }

        let private terminalFlowServerPlanForAuthority authorityId =
            let wakePlan = terminalFlowWakePlanForAuthority authorityId
            match authorityId with
            | QueueOnlyRecoveryReadyAfterForceOwnerClose(rootReceipt, writerLease, tailId, ownerCloseReceiptId, workDagTailCloseReceipt) ->
                let boundary = TerminalFlowBoundaryReceipt(TerminalFlowTopLevelBuildOkReceipt("terminal-commit:force-close-owner:" + ownerCloseReceiptId, rootReceipt, "writer-receipt:force-close-owner:" + ownerCloseReceiptId + ":" + workDagTailCloseReceipt, tailId))
                { eventId = TerminalFlowSchedulerEventBoundaryObserved
                  orderSlot = TerminalFlowServerOrderReceiptEmission
                  command = TerminalFlowServerEmitBoundaryReceipt(terminalFlowBoundaryTopLevelReceiptText boundary)
                  wakePlan = wakePlan }
            | QueueOnlyRecoveryTerminalFlowBoundary(_, TerminalFlowTransitionRejectTopology _, _, TerminalFlowBoundaryWhyNotCommit _) ->
                { eventId = TerminalFlowSchedulerEventProceduralChurn
                  orderSlot = TerminalFlowServerOrderSchedulerEvent
                  command = terminalFlowServerObserveOnly (terminalFlowLocalJoinWaitText (terminalFlowLocalDataflowWait TerminalFlowLocalJoinWaitTerminalOutcome "material_quiescence_receipt"))
                  wakePlan = wakePlan }
            | QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, TerminalFlowBoundaryReceipt boundaryReceipt) ->
                { eventId = TerminalFlowSchedulerEventBoundaryObserved
                  orderSlot = TerminalFlowServerOrderReceiptEmission
                  command = TerminalFlowServerEmitBoundaryReceipt(terminalFlowTopLevelReceiptText boundaryReceipt)
                  wakePlan = wakePlan }
            | QueueOnlyRecoveryTerminalFlowBoundary(_, TerminalFlowTransitionRegisterWakerEdge(_, _, _, obligationId, _), _, _) ->
                { eventId = TerminalFlowSchedulerEventWakeRegistration
                  orderSlot = TerminalFlowServerOrderSchedulerEvent
                  command = terminalFlowServerObserveOnly (terminalFlowLocalJoinWaitText (terminalFlowLocalDataflowWait TerminalFlowLocalJoinWaitSchedulerPush obligationId))
                  wakePlan = wakePlan }
            | QueueOnlyRecoveryTerminalFlowBoundary(_, TerminalFlowTransitionDeferMaterialActivity _, _, TerminalFlowBoundaryWhyNotCommit _) ->
                { eventId = TerminalFlowSchedulerEventMaterialDelta
                  orderSlot = TerminalFlowServerOrderSchedulerEvent
                  command = terminalFlowServerObserveOnly (terminalFlowLocalJoinWaitText (terminalFlowLocalDataflowWait TerminalFlowLocalJoinWaitTerminalOutcome "material_quiescence_receipt"))
                  wakePlan = wakePlan }
            | QueueOnlyRecoveryTerminalFlowBoundary(_, TerminalFlowTransitionWriterLeaseLive(_, _, _, _), _, TerminalFlowBoundaryWhyNotCommit _) ->
                { eventId = TerminalFlowSchedulerEventWriterLeaseDeadline
                  orderSlot = TerminalFlowServerOrderSchedulerEvent
                  command = terminalFlowServerObserveOnly (terminalFlowLocalJoinWaitText (terminalFlowLocalDataflowWait TerminalFlowLocalJoinWaitWriterLease "writer_lease_receipt"))
                  wakePlan = wakePlan }
            | QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRejectedTopology _)) ->
                { eventId = TerminalFlowSchedulerEventProceduralChurn
                  orderSlot = TerminalFlowServerOrderSchedulerEvent
                  command = terminalFlowServerObserveOnly (terminalFlowLocalJoinWaitText (terminalFlowLocalDataflowWait TerminalFlowLocalJoinWaitTerminalOutcome "material_quiescence_receipt"))
                  wakePlan = wakePlan }
            | QueueOnlyRecoveryTerminalFlowBoundary(_, _, _, TerminalFlowBoundaryWhyNotCommit whyNot) ->
                { eventId = TerminalFlowSchedulerEventBoundaryObserved
                  orderSlot = TerminalFlowServerOrderWakeTimeout
                  command = terminalFlowServerBlockCommit (terminalFlowWhyNotTerminalCommitText whyNot)
                  wakePlan = wakePlan }
            | QueueOnlyRecoveryTerminalFlowOutcome(_, _, outcome) when terminalFlowOutcomeIsTerminalLike outcome ->
                let boundary = terminalFlowCertificateBoundaryForOutcome outcome
                { eventId = TerminalFlowSchedulerEventBoundaryObserved
                  orderSlot = TerminalFlowServerOrderReceiptEmission
                  command = TerminalFlowServerEmitBoundaryReceipt(terminalFlowBoundaryTopLevelReceiptText boundary)
                  wakePlan = wakePlan }
            | QueueOnlyRecoveryRecentSemanticActivity ageMs ->
                { eventId = TerminalFlowSchedulerEventProceduralChurn
                  orderSlot = TerminalFlowServerOrderSchedulerEvent
                  command = terminalFlowServerObserveOnly (sprintf "legacy_recent_semantic_activity|age_ms=%d" ageMs)
                  wakePlan = wakePlan }
            | _ ->
                { eventId = TerminalFlowSchedulerEventProceduralChurn
                  orderSlot = TerminalFlowServerOrderSchedulerEvent
                  command = terminalFlowServerObserveOnly "no_terminal_flow_boundary"
                  wakePlan = wakePlan }

        let private terminalFlowActivityTextForAuthority = function
            | QueueOnlyRecoveryTerminalFlowBoundary(observation, _, _, _)
            | QueueOnlyRecoveryTerminalFlowOutcome(observation, _, _)
            | QueueOnlyRecoveryTerminalFlowTransition(observation, _) -> terminalFlowActivityObservationText observation.activity
            | _ -> "activity:not_observed"

        let private terminalFlowResidualPassCountFor tailId materialDepth =
            let tailIdentity = terminalFlowResidualTailIdentityFor tailId
            lock terminalFlowResidualPassGate (fun () ->
                if materialDepth > 0 then
                    terminalFlowResidualPassByTail.Remove tailIdentity |> ignore
                    0
                else
                    let timeBucket = Environment.TickCount64 / 1000L
                    match terminalFlowResidualPassByTail.TryGetValue tailIdentity with
                    | true, (lastBucket, count) when lastBucket = timeBucket -> count
                    | true, (_, count) ->
                        let next = min 100000 (count + 1)
                        terminalFlowResidualPassByTail.[tailIdentity] <- (timeBucket, next)
                        next
                    | false, _ ->
                        terminalFlowResidualPassByTail.[tailIdentity] <- (timeBucket, 1)
                        1)

        let private terminalFlowStickyTailGateForAuthority waitedMs authorityId =
            let snapshotFor (observation:TerminalFlowObservation) fallbackReason =
                let tailId =
                    match observation.tail with
                    | TerminalFlowTailPendingDrain tailId
                    | TerminalFlowTailDrained tailId -> tailId
                    | TerminalFlowTailDeadlockedObserved(tailId, _)
                    | TerminalFlowTailQuarantinedObserved(tailId, _) -> tailId
                    | TerminalFlowTailTerminalEmittedObserved receiptId -> receiptId
                    | TerminalFlowTailUnknown -> "tail:unknown"
                let materialDepth =
                    match observation.activity with
                    | TerminalFlowMaterialActivityRecent token
                        when observation.qap.pending <= terminalFlowWriterLeaseSmallResidualPendingCap
                             && observation.qap.queue >= terminalFlowBoundedProceduralTailPressureQueue -> 0
                    | TerminalFlowMaterialActivityRecent token -> max 1 (int token.count)
                    | TerminalFlowMaterialQuiescent _ -> 0
                let qapTotal = max 0 (observation.qap.pending + observation.qap.queue + observation.qap.active)
                let proceduralDepth = max 0 (qapTotal - materialDepth)
                let fixedPointRepeat =
                    let raw = CompilerConsoleHud88.cachedHudTextOrDash ["same_state_repeat"; "pressure_pinned_repeat_count"; "terminal_flow_residual_fixed_point_repeat"]
                    let mutable parsed = 0
                    if Int32.TryParse(raw, &parsed) then max 0 parsed else 0
                let materialQuiescenceAgeMs =
                    match observation.activity with
                    | TerminalFlowMaterialActivityRecent _ -> 0L
                    | TerminalFlowMaterialQuiescent(ageMs, _) -> max 0L ageMs
                let canonicalRoot = DiagJson.canonicalRootAuthoritySnapshot()
                let evaluatorFrontierResolved = not (String.IsNullOrWhiteSpace canonicalRoot.receiptId)
                let residualTopK =
                    [ CompilerConsoleHud88.cachedHudTextOrDash ["hot_node"; "hot_term"; "top_wait_node"]
                      CompilerConsoleHud88.cachedHudTextOrDash ["hot_node_2"; "hot_term_2"; "top_wait_node_2"]
                      CompilerConsoleHud88.cachedHudTextOrDash ["hot_node_3"; "hot_term_3"; "top_wait_node_3"] ]
                    |> List.filter (fun nodeId -> not (String.IsNullOrWhiteSpace nodeId) && nodeId <> "-")
                    |> List.distinct
                    |> List.truncate 3
                    |> function
                       | [] -> [ tailId ]
                       | nodes -> nodes
                { tailId = tailId
                  mutatingDepth = materialDepth
                  proceduralDepth = proceduralDepth
                  globalPending = observation.qap.pending
                  globalQueue = observation.qap.queue
                  globalActive = observation.qap.active
                  fixedPointRepeat = fixedPointRepeat
                  proceduralDrainPassCount = terminalFlowResidualPassCountFor tailId materialDepth
                  materialDeltaOnProceduralPass = materialDepth
                  fixedPointRepeatCap = 8
                  materialQuiescenceAgeMs = materialQuiescenceAgeMs
                  evaluatorFrontierResolved = evaluatorFrontierResolved
                  wakerStatus = TerminalFlowWakerMissing
                  aggregatePromiseArmed =
                    match observation.tail with
                    | TerminalFlowTailPendingDrain _ -> true
                    | _ -> false
                  mutatingTailDrained = materialDepth = 0
                  evidence = fallbackReason
                  residualTopK = residualTopK }
            match authorityId with
            | QueueOnlyRecoveryTerminalFlowBoundary(observation, transition, _, boundary) ->
                let snapshot = snapshotFor observation (terminalFlowCertificateBoundaryText boundary)
                match transition, boundary with
                | TerminalFlowTransitionRegisterWakerEdge(_, _, _, obligationId, _), _ when snapshot.mutatingTailDrained ->
                    terminalFlowWriterReadyGateFor { snapshot with wakerStatus = TerminalFlowWakerRegistered(obligationId, Environment.TickCount64) }
                | TerminalFlowTransitionRegisterWakerEdge(_, _, _, obligationId, _), _ ->
                    TerminalFlowStickyTailAwaitMutatingAggregate { snapshot with wakerStatus = TerminalFlowWakerRegistered(obligationId, Environment.TickCount64) }
                | TerminalFlowTransitionDeferMaterialActivity _, _ when terminalFlowSnapshotHasStrongProceduralPressure snapshot ->
                    TerminalFlowStickyTailQuarantineProceduralResidual(snapshot, CompilerKernelV2.OperationalReasonIdOps.create "material_activity_reclassified_by_zero_mutating_tail_and_procedural_pressure")
                | TerminalFlowTransitionDeferMaterialActivity _, _ when snapshot.mutatingTailDrained ->
                    terminalFlowWriterReadyGateFor snapshot
                | TerminalFlowTransitionDeferMaterialActivity _, _ ->
                    TerminalFlowStickyTailAwaitMutatingAggregate snapshot
                | _, TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotAwaitingBoundedLease _) ->
                    TerminalFlowStickyTailAwaitMutatingAggregate
                        { snapshot with
                            evidence = snapshot.evidence + "|bounded_lease_is_provisional_writer_ownership_not_quarantine_authority" }
                | _, TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotWakerRegistrationRequired _) when terminalFlowSnapshotHasProceduralPressure snapshot && not (terminalFlowQapIsBounded observation.qap) ->
                    TerminalFlowStickyTailQuarantineProceduralResidual(snapshot, CompilerKernelV2.OperationalReasonIdOps.create "waker_registration_unbounded_procedural_queue_after_mutating_tail_drained")
                | _, TerminalFlowBoundaryWhyNotCommit(TerminalFlowWhyNotRejectedTopology _) when terminalFlowSnapshotHasProceduralPressure snapshot && not (terminalFlowQapIsBounded observation.qap) ->
                    TerminalFlowStickyTailQuarantineProceduralResidual(snapshot, CompilerKernelV2.OperationalReasonIdOps.create "unbounded_procedural_qap_after_mutating_tail_drained")
                | _, _ when terminalFlowSnapshotHasProceduralPressure snapshot && not (terminalFlowQapIsBounded observation.qap) ->
                    TerminalFlowStickyTailQuarantineProceduralResidual(snapshot, CompilerKernelV2.OperationalReasonIdOps.create "unbounded_procedural_qap_after_mutating_tail_drained")
                | _, TerminalFlowBoundaryReceipt _ when terminalFlowStickyTailSnapshotHasNoResidual snapshot ->
                    TerminalFlowStickyTailDrained snapshot
                | _, TerminalFlowBoundaryReceipt _ when snapshot.mutatingTailDrained ->
                    terminalFlowWriterReadyGateFor snapshot
                | _, _ when snapshot.mutatingTailDrained && snapshot.aggregatePromiseArmed && terminalFlowStickyTailSnapshotHasNoResidual snapshot ->
                    TerminalFlowStickyTailDrained snapshot
                | _, _ when snapshot.mutatingTailDrained && snapshot.aggregatePromiseArmed ->
                    terminalFlowWriterReadyGateFor snapshot
                | _, _ when not (terminalFlowQapIsBounded observation.qap) ->
                    TerminalFlowStickyTailRejectUnboundedMutatingTail(snapshot, CompilerKernelV2.OperationalReasonIdOps.create "sticky_tail_qap_unbounded")
                | _, _ ->
                    TerminalFlowStickyTailAwaitMutatingAggregate snapshot
            | QueueOnlyRecoveryTerminalFlowOutcome(observation, _, outcome) ->
                let snapshot = snapshotFor observation (terminalFlowOutcomeText outcome)
                if terminalFlowStickyTailSnapshotHasNoResidual snapshot then TerminalFlowStickyTailDrained snapshot
                elif snapshot.mutatingTailDrained then terminalFlowWriterReadyGateFor snapshot
                else TerminalFlowStickyTailAwaitMutatingAggregate snapshot
            | QueueOnlyRecoveryTerminalFlowTransition(observation, transition) ->
                let snapshot = snapshotFor observation (terminalFlowTransitionDecisionText transition)
                if terminalFlowStickyTailSnapshotHasNoResidual snapshot then TerminalFlowStickyTailDrained snapshot
                elif snapshot.mutatingTailDrained then terminalFlowWriterReadyGateFor snapshot
                else TerminalFlowStickyTailAwaitMutatingAggregate snapshot
            | _ ->
                let snapshot =
                    { tailId = "tail:not_observed"
                      mutatingDepth = 0
                      proceduralDepth = 0
                      globalPending = 0
                      globalQueue = 0
                      globalActive = 0
                      fixedPointRepeat = 0
                      proceduralDrainPassCount = 0
                      materialDeltaOnProceduralPass = 0
                      fixedPointRepeatCap = 8
                      materialQuiescenceAgeMs = 0L
                      evaluatorFrontierResolved = false
                      wakerStatus = TerminalFlowWakerMissing
                      aggregatePromiseArmed = false
                      mutatingTailDrained = false
                      evidence = "no_terminal_flow_authority"
                      residualTopK = [ "tail:not_observed" ] }
                TerminalFlowStickyTailRejectUnboundedMutatingTail(snapshot, CompilerKernelV2.OperationalReasonIdOps.create "no_terminal_flow_authority")

        type BigStackSchedulerWorkId =
            | BigStackSchedulerWorkPresent
            | BigStackSchedulerWorkAbsentHotFrontierOnly
            | BigStackSchedulerWorkWriteWitnessTail
            | BigStackSchedulerWorkReplayComplete
            | BigStackSchedulerWorkCycleFuse

        let private bigStackSchedulerWorkText = function
            | BigStackSchedulerWorkPresent -> "scheduler_work_present"
            | BigStackSchedulerWorkAbsentHotFrontierOnly -> "scheduler_work_absent_hot_frontier_only"
            | BigStackSchedulerWorkWriteWitnessTail -> "write_witness_tail"
            | BigStackSchedulerWorkReplayComplete -> "replay_complete"
            | BigStackSchedulerWorkCycleFuse -> "replay_repeat_guard"

        type CyclePoisonPolicyId =
            | CyclePoisonNone
            | CyclePoisonObserveHotFrontierOnly
            | CyclePoisonCandidateRetry
            | CyclePoisonCandidateRepeatedAbort

        let private cyclePoisonPolicyText = function
            | CyclePoisonNone -> "none"
            | CyclePoisonObserveHotFrontierOnly -> "observe_hot_frontier_only"
            | CyclePoisonCandidateRetry -> "poison_candidate_retry"
            | CyclePoisonCandidateRepeatedAbort -> "poison_candidate_repeated_abort"

        type HotFrontierProgressVerdictId =
            | HotFrontierNoHotWork
            | HotFrontierRisingNoSchedulerWork
            | HotFrontierCappedPoisonCandidate
            | HotFrontierSchedulerWorkPresent
            | HotFrontierReplayOrWriteWitness
            | HotFrontierCycleFuseTripped

        let private hotFrontierProgressVerdictText = function
            | HotFrontierNoHotWork -> "no_hot_work"
            | HotFrontierRisingNoSchedulerWork -> "rising_no_scheduler_work"
            | HotFrontierCappedPoisonCandidate -> "capped_poison_candidate"
            | HotFrontierSchedulerWorkPresent -> "scheduler_work_present"
            | HotFrontierReplayOrWriteWitness -> "replay_or_write_witness"
            | HotFrontierCycleFuseTripped -> "replay_repeat_guard_tripped"

        let private hotFrontierProgressVerdictFor schedulerWorkId capReached activityStillRising activityGraceActive =
            match schedulerWorkId with
            | BigStackSchedulerWorkCycleFuse -> HotFrontierCycleFuseTripped
            | BigStackSchedulerWorkReplayComplete
            | BigStackSchedulerWorkWriteWitnessTail -> HotFrontierReplayOrWriteWitness
            | BigStackSchedulerWorkPresent -> HotFrontierSchedulerWorkPresent
            | BigStackSchedulerWorkAbsentHotFrontierOnly when capReached -> HotFrontierCappedPoisonCandidate
            | BigStackSchedulerWorkAbsentHotFrontierOnly when activityStillRising || activityGraceActive -> HotFrontierRisingNoSchedulerWork
            | BigStackSchedulerWorkAbsentHotFrontierOnly -> HotFrontierNoHotWork

        type ActivePendingDesyncDecisionId =
            | ActivePendingNoDesync
            | ActivePendingSmallQueueHotMixed
            | ActivePendingExtremeCrossKind
            | ActivePendingNoSchedulerSeedMixed
            | ActivePendingNoSchedulerWarmMixed
            | ActivePendingNoSchedulerHotMixed
            | ActivePendingNoSchedulerExtremeMixed

        let private activePendingDesyncDecisionText = function
            | ActivePendingNoDesync -> "no_desync"
            | ActivePendingSmallQueueHotMixed -> "small_queue_hot_mixed"
            | ActivePendingExtremeCrossKind -> "extreme_cross_kind"
            | ActivePendingNoSchedulerSeedMixed -> "no_scheduler_seed_mixed"
            | ActivePendingNoSchedulerWarmMixed -> "no_scheduler_warm_mixed"
            | ActivePendingNoSchedulerHotMixed -> "no_scheduler_hot_mixed"
            | ActivePendingNoSchedulerExtremeMixed -> "no_scheduler_extreme_mixed"

        let private activePendingDesyncDecisionFor active pending queueDepth termHot tyHot replayComplete =
            let totalHot = termHot + tyHot
            if replayComplete then ActivePendingNoDesync
            elif pending = 0 && queueDepth = 0 && active = 0 && termHot >= 60000 && tyHot >= 40000 then ActivePendingNoSchedulerExtremeMixed
            elif pending = 0 && queueDepth = 0 && active = 0 && totalHot >= 20000 && termHot > 0 && tyHot > 0 then ActivePendingNoSchedulerHotMixed
            elif pending = 0 && queueDepth = 0 && active = 0 && totalHot >= 3000 && termHot > 0 && tyHot > 0 then ActivePendingNoSchedulerWarmMixed
            elif pending = 0 && queueDepth = 0 && active = 0 && totalHot >= 1200 && termHot > 0 && tyHot > 0 then ActivePendingNoSchedulerSeedMixed
            elif active >= 4 && pending <= 2 && queueDepth <= 1 && termHot >= 60000 && tyHot >= 40000 then ActivePendingExtremeCrossKind
            elif active >= 4 && pending <= 2 && queueDepth <= 1 && totalHot >= 20000 then ActivePendingSmallQueueHotMixed
            else ActivePendingNoDesync

        let private activePendingDesyncCapDeferrals = function
            | ActivePendingExtremeCrossKind -> 3
            | ActivePendingNoSchedulerExtremeMixed -> 3
            | ActivePendingNoSchedulerHotMixed -> 4
            | ActivePendingNoSchedulerWarmMixed -> 4
            | ActivePendingNoSchedulerSeedMixed -> 6
            | ActivePendingSmallQueueHotMixed -> 8
            | ActivePendingNoDesync -> 768

        let private activePendingDesyncCapWaitMs = function
            | ActivePendingExtremeCrossKind -> 6000
            | ActivePendingNoSchedulerExtremeMixed -> 8000
            | ActivePendingNoSchedulerHotMixed -> 10000
            | ActivePendingNoSchedulerWarmMixed -> 12000
            | ActivePendingNoSchedulerSeedMixed -> 16000
            | ActivePendingSmallQueueHotMixed -> 16000
            | ActivePendingNoDesync -> 180000

        let private activePendingDesyncExtendedWaitMs = function
            | ActivePendingExtremeCrossKind -> 12000
            | ActivePendingNoSchedulerExtremeMixed -> 8000
            | ActivePendingNoSchedulerHotMixed -> 10000
            | ActivePendingNoSchedulerWarmMixed -> 12000
            | ActivePendingNoSchedulerSeedMixed -> 16000
            | ActivePendingSmallQueueHotMixed -> 32000
            | ActivePendingNoDesync -> 360000

        type HotFrontierRisingExtensionDecisionId =
            | HotFrontierNoRisingExtension
            | HotFrontierAllowRisingExtension

        let private hotFrontierRisingExtensionText = function
            | HotFrontierNoRisingExtension -> "no_rising_extension"
            | HotFrontierAllowRisingExtension -> "allow_rising_extension"

        let private hotFrontierRisingExtensionFor = function
            | ActivePendingNoSchedulerSeedMixed
            | ActivePendingNoSchedulerWarmMixed
            | ActivePendingNoSchedulerHotMixed
            | ActivePendingNoSchedulerExtremeMixed -> HotFrontierNoRisingExtension
            | _ -> HotFrontierAllowRisingExtension

        type SidecarPrefetchOutcomeId =
            | SidecarPrefetchFrameAvailable
            | SidecarPrefetchMissingAfterPrefetch

        let sidecarPrefetchOutcomeText = function
            | SidecarPrefetchFrameAvailable -> "frame_available"
            | SidecarPrefetchMissingAfterPrefetch -> "missing_after_prefetch"

        let sidecarPrefetchStatusText = function
            | SidecarPrefetchFrameAvailable -> "frame_available"
            | SidecarPrefetchMissingAfterPrefetch -> "semantic_missing_after_prefetch_blocked"

        type RetryDiagnosticLineProjectionId =
            | RetryDiagnosticLineEmpty
            | RetryDiagnosticLineAlreadyPrefixed of line:string
            | RetryDiagnosticLineNeedsPrefix of line:string

        let retryDiagnosticLineProjectionFor (prefix:string) (line:string) =
            let safe = if System.Object.ReferenceEquals(line, null) then "" else line
            if System.String.IsNullOrEmpty safe then
                RetryDiagnosticLineEmpty
            elif safe.Length >= prefix.Length
                 && System.String.Equals(safe.Substring(0, prefix.Length), prefix, System.StringComparison.Ordinal) then
                RetryDiagnosticLineAlreadyPrefixed safe
            else
                RetryDiagnosticLineNeedsPrefix safe

        let retryDiagnosticLineProjectionText (prefix:string) = function
            | RetryDiagnosticLineEmpty -> prefix.TrimEnd()
            | RetryDiagnosticLineAlreadyPrefixed line -> line
            | RetryDiagnosticLineNeedsPrefix line -> prefix + line

        type RetryHotkeyPressureId =
            | RetryHotkeyCold
            | RetryHotkeyTermDominant
            | RetryHotkeyTyDominant
            | RetryHotkeyMixedHot
            | RetryHotkeyExtremeMixed

        let retryHotkeyPressureText = function
            | RetryHotkeyCold -> "cold"
            | RetryHotkeyTermDominant -> "term_dominant"
            | RetryHotkeyTyDominant -> "ty_dominant"
            | RetryHotkeyMixedHot -> "mixed_hot"
            | RetryHotkeyExtremeMixed -> "extreme_mixed"

        let retryHotkeyPressureFor termCount tyCount =
            let total = termCount + tyCount
            if total <= 0 then RetryHotkeyCold
            elif total >= 20000 && termCount > 0 && tyCount > 0 then RetryHotkeyExtremeMixed
            elif termCount > tyCount * 2 then RetryHotkeyTermDominant
            elif tyCount > termCount * 2 then RetryHotkeyTyDominant
            else RetryHotkeyMixedHot

        let retryHotkeyTermRatioPct termCount tyCount =
            let total = termCount + tyCount
            if total <= 0 then 0
            else int ((int64 termCount * 100L) / int64 total)

        type RetryWaitObservationId =
            | RetryWaitNotPresent
            | RetryWaitMalformed
            | RetryWaitObserved of waitedMs:int64

        let retryWaitObservationText = function
            | RetryWaitNotPresent -> "not_present"
            | RetryWaitMalformed -> "malformed"
            | RetryWaitObserved _ -> "observed"

        let retryWaitObservationMs = function
            | RetryWaitObserved waitedMs -> waitedMs
            | RetryWaitNotPresent
            | RetryWaitMalformed -> -1L

        let retryWaitObservationFor (message:string) =
            if System.String.IsNullOrWhiteSpace message then RetryWaitNotPresent
            else
                let waitedField =
                    message.Split(
                        [| ' '; '|'; ','; ';'; '('; ')'; '['; ']'; '{'; '}'; '\t'; '\r'; '\n' |],
                        System.StringSplitOptions.RemoveEmptyEntries)
                    |> Array.tryPick (fun field ->
                        let parts = field.Split([|'='|], 2, System.StringSplitOptions.None)
                        if parts.Length = 2 && parts.[0] = "waited" then Some parts.[1]
                        else None)
                match waitedField with
                | None -> RetryWaitNotPresent
                | Some value ->
                    let digitText =
                        value
                        |> Seq.takeWhile System.Char.IsDigit
                        |> Seq.toArray
                        |> fun chars -> System.String(chars)
                    let mutable parsed = 0L
                    if digitText.Length > 0 && System.Int64.TryParse(digitText, &parsed) then
                        RetryWaitObserved parsed
                    else RetryWaitMalformed

        type RetryWaitPressureId =
            | RetryWaitUnknown
            | RetryWaitBrief
            | RetryWaitStalled
            | RetryWaitCapped

        let retryWaitPressureText = function
            | RetryWaitUnknown -> "unknown"
            | RetryWaitBrief -> "brief"
            | RetryWaitStalled -> "stalled"
            | RetryWaitCapped -> "capped"

        let retryWaitPressureFor waitedMs stalledMs cappedMs =
            if waitedMs < 0L then RetryWaitUnknown
            elif waitedMs >= int64 cappedMs then RetryWaitCapped
            elif waitedMs > int64 stalledMs then RetryWaitStalled
            else RetryWaitBrief

        type RetryReentrySignalId =
            | RetryReentryNone
            | RetryReentryTermCycleFuse
            | RetryReentryHotFrontierRetry
            | RetryReentryWaitCap
            | RetryReentryMixedPressure

        let retryReentrySignalText = function
            | RetryReentryNone -> "none"
            | RetryReentryTermCycleFuse -> "term_reentry_fuse"
            | RetryReentryHotFrontierRetry -> "hot_frontier_retry"
            | RetryReentryWaitCap -> "wait_cap"
            | RetryReentryMixedPressure -> "mixed_pressure"

        let retryReentrySignalFor (codeId:DiagnosticClassifier.DiagnosticCodeId) termCount tyCount waitedMs =
            let total = termCount + tyCount
            if codeId = DiagnosticClassifier.DiagnosticEJP0011 then RetryReentryTermCycleFuse
            elif waitedMs >= 45000L then RetryReentryWaitCap
            elif total >= 20000 && waitedMs > 0L then RetryReentryMixedPressure
            elif total > 0 then RetryReentryHotFrontierRetry
            else RetryReentryNone

        // MIGRATION: Bigger first-stack for deep Spiral list recursion (listm.spi foldBack/map).
        // Prefer a single large stack to avoid BigStack nesting (parent stacks remain parked).
        let private stackBytesFor (tagId: BigStackJoinTagId) (nestLevel: int) : int * int =
            let mb =
                match tagId with
                | BigStackTerm
                | BigStackTy
                | BigStackApply ->
                    // MIGRATION: grow first stacks so we don't trampoline-nest into BigStack until exhaustion.
                    // NOTE: Thread stack size is an Int32; keep < 2GB to avoid overflow.
                    if nestLevel <= 4 then 1792 else 1536
                | BigStackJoinPoint ->
                    if nestLevel <= 2 then 512 else stackMb
