        type BigStackExecutionCarrierState = private | BigStackExecutionCarrierState of obj

        let executionCarrierState value = BigStackExecutionCarrierState value
        let executionCarrierStateValue (BigStackExecutionCarrierState value) = value

        type BigStackExecutionCarrier = private {
            capture : unit -> BigStackExecutionCarrierState
            run : BigStackExecutionCarrierState -> (unit -> obj) -> obj
        }

        let mutable private executionCarrier : BigStackExecutionCarrier option = None

        let installExecutionCarrier capture run =
            executionCarrier <- Some { capture = capture; run = run }

        let private captureExecutionCarrier () =
