                        let joinLocalEvidenceAtCompletion = DiagJson.bigStackJoinLocalEvidenceSnapshot joinEvidence
                        let joinLocalEvidenceDeltaAtCompletion = DiagJson.bigStackJoinLocalEvidenceDelta generationChangeJoinLocalEvidenceBaseline joinLocalEvidenceAtCompletion
                        let generationEvidenceAtCompletion = JpGenerationLocalEvidenceAuthority.read g1
                        let generationEvidenceDeltaAtCompletion = jpGenerationLocalEvidenceDelta generationChangeLocalEvidenceBaseline generationEvidenceAtCompletion
                        let productivityEvidence =
                            match joinLocalEvidenceDeltaAtCompletion with
                            | DiagJson.BigStackJoinLocalEvidenceCompleted current ->
                                JoinObservedJoinLocalCompletion(joinLocalRef, current.evidenceRef)
                            | DiagJson.BigStackJoinLocalEvidenceAdvanced(producedDelta, retiredDelta, semanticFactDelta, closureCaptureDelta, current)
                                when producedDelta > 0L || retiredDelta > 0L || semanticFactDelta > 0L || closureCaptureDelta > 0L ->
                                JoinObservedJoinLocalProgress(joinLocalRef, producedDelta, retiredDelta, semanticFactDelta, closureCaptureDelta, current.evidenceRef)
                            | _ ->
                                match generationEvidenceDeltaAtCompletion with
                                | JpGenerationLocalEvidenceClosed(generation, retiredDelta, current) ->
                                    JoinObservedGenerationClosure(generation, retiredDelta, current.evidenceRef)
                                | JpGenerationLocalEvidenceAdvanced(generation, _, retiredDelta, liveDelta, current) when retiredDelta > 0 ->
                                    JoinObservedGenerationRetirement(generation, retiredDelta, liveDelta, current.evidenceRef)
                                | _ when factsDeltaSinceGenerationChange > 0L && activePairsDeltaSinceGenerationChange > 0L ->
                                    JoinObservedFactsAndPairs(factsDeltaSinceGenerationChange, activePairsDeltaSinceGenerationChange)
                                | _ when factsDeltaSinceGenerationChange > 0L -> JoinObservedFactDelta factsDeltaSinceGenerationChange
                                | _ when activePairsDeltaSinceGenerationChange > 0L -> JoinObservedActivePairDelta activePairsDeltaSinceGenerationChange
                                | _ -> JoinChildRetiredWithoutNewGlobalFacts
                        let completionAccepted = err.IsNone && not (TermCycleFuse.isTripped())
                        if completionAccepted then
                            joinProof <- BigStackJoinCompleted(joinProof, gEnd, bigStackJoinNodeCount semanticFactCountAtCompletion, bigStackJoinNodeCount activePairCountAtCompletion, bigStackJoinWallTime waited)
                            let joinProofRef = bigStackJoinProofRef joinProof
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"bigstack_join_proof_terminal\",\"event\":\"join_complete\",\"tag\":%s,\"join_proof_ref\":%s,\"join_proof_du\":%s,\"productivity_evidence_du\":%s,\"authority\":\"completed_child_is_dispositive_productivity_may_only_extend\",\"next\":\"consume_completed_join_result\"}" [| box (DiagJson.esc tag); box (DiagJson.esc joinProofRef); box (DiagJson.esc (bigStackJoinProofStableText joinProof)); box (DiagJson.esc (joinProductivityEvidenceText productivityEvidence)) |])
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"bigstack_generation_change_completion_accepted\",\"event\":\"join_complete\",\"tag\":%s,\"waited_ms\":%d,\"since_gen_change_ms\":%d,\"grace_ms\":%d,\"grace_basis_du\":%s,\"unit_p99_ms\":%d,\"duration_sample_count\":%d,\"duration_shape_du\":%s,\"duration_basis_ref\":%s,\"productivity_evidence_du\":%s,\"facts_delta_since_generation_change\":%d,\"active_pairs_delta_since_generation_change\":%d,\"semantic_fact_count_at_change\":%d,\"semantic_fact_count_now\":%d,\"active_pairs_at_change\":%d,\"active_pairs_now\":%d,\"gen_before\":%d,\"gen_after\":%d,\"gen_end\":%d,\"guard_polarity_du\":\"completion_success_dispositive_productivity_extend_only\",\"authority\":\"completed_child_exact_once\",\"next\":\"consume_completed_join_result\"}" [| box (DiagJson.esc tag); box waited; box (waited - w1); box join_gen_change_abort_ms; box (DiagJson.esc (timingBasisText joinGenerationChangeGraceBasis)); box join_unit_p99_ms; box join_duration_sample_count; box (DiagJson.esc join_duration_shape); box (DiagJson.esc join_duration_basis_ref); box (DiagJson.esc (joinProductivityEvidenceText productivityEvidence)); box factsDeltaSinceGenerationChange; box activePairsDeltaSinceGenerationChange; box generationChangeSemanticFactBaseline; box semanticFactCountAtCompletion; box generationChangeActivePairBaseline; box activePairCountAtCompletion; box g0; box g1; box gEnd |])
                        else
                            let msg =
                                FastRuntimeFormat.format "[spiral_compiler] EJP0018: BigStack join child failed after generation change (from %d to %d; end=%d) tag=%s waited=%dms grace=%dms cycle_tripped=%b" [| box g0; box g1; box gEnd; box tag; box waited; box join_gen_change_abort_ms; box (TermCycleFuse.isTripped()) |]
                            try DiagSidecar.emit msg with _ -> ()
                            raise (PartEvalTypeError([], msg))
                    | None ->
                        let semanticFactCountAtCompletion = (DiagJson.semanticFactBridgeSnapshot()).factCount
                        let activePairCountAtCompletion = (DiagJson.specializationInteractionBridgeSnapshot()).consumedActivePairs
                        joinProof <- BigStackJoinCompleted(joinProof, CacheGeneration.current(), bigStackJoinNodeCount semanticFactCountAtCompletion, bigStackJoinNodeCount activePairCountAtCompletion, bigStackJoinWallTime waited)

                    try
                        let ok = err.IsNone
                        let sanitize (s: string) =
                            if obj.ReferenceEquals(s,null) then ""
                            else s.Replace("\r"," ").Replace("\n"," ").Trim()
                        let truncate n (s: string) =
                            let s = sanitize s
                            if s.Length > n then s.Substring(0,n) + "..." else s
                        let et =
                            match err with
                            | Some e -> e.GetType().FullName
                            | None -> ""
                        let em =
                            match err with
                            | Some e -> truncate 220 e.Message
                            | None -> ""
                        let inner =
                            match err with
                            | Some e when not (obj.ReferenceEquals(e.InnerException,null)) -> truncate 180 e.InnerException.Message
                            | _ -> ""
                        DiagSidecar.emit (FastRuntimeFormat.format "[spiral_compiler] BIGSTACK done tag=%s child_tid=%d ok=%b err=%s msg=%s inner=%s nest=%d/%d parent_tid=%d" [| box tag; box childTid; box ok; box et; box em; box inner; box nestLevel; box maxNestingLevels; box Thread.CurrentThread.ManagedThreadId |])
                    with _ -> ()
                    match err with
                    | Some (:? System.InsufficientExecutionStackException) -> None
                    | Some e -> raise e
                    | None -> Some res

            if parentNest > 0 && hasSufficientExecutionStack () then
                if tagId = BigStackApply then
                    DiagJson.emitSurvival (
                        FastRuntimeFormat.format "{\"kind\":\"bigstack_apply_inline_execution_entered_receipt\",\"tag_du\":\"apply\",\"nest_level\":%d,\"parent_depth\":%d,\"managed_thread_id\":%d,\"authority\":\"existing_bigstack_has_sufficient_execution_stack\",\"next\":\"distinguish_inline_apply_overflow_from_spawned_apply_overflow\"}" [| box parentNest; box parentDepth; box Thread.CurrentThread.ManagedThreadId |])
                Some (f context)
            else
                spawn ()

        let tryRunApply context f =
            tryRun context BigStackApply (bigStackJoinTagText BigStackApply) f
    

    /// ### EvalCycleGuard — explicit traversal capability
    /// Round  removes thread identity from semantic cycle authority.  A
    /// traversal path is an immutable value carried by the evaluator.  Work
    /// stealing therefore cannot reset the guard merely by moving to another
    /// host thread.
    module EvalCycleGuard =
        open System.Runtime.CompilerServices

        let empty =
            { nodes = []
              pathRef = lazy (CompilerIdentityKernel.ContentDigest.ofText "eval-node-path" "empty") }

        let private nodeCount node path =
            path.nodes
            |> List.filter (fun existing -> obj.ReferenceEquals(existing, node))
            |> List.length

        /// Returns the advanced path and the re-entry count.  Callers must thread
        /// the returned path into recursive evaluation; no ambient ThreadLocal is
        /// consulted or mutated.
        let enter (path:EvalNodePath) (node:obj) : EvalNodePath * int =
            let nextNodes = node :: path.nodes
            let count = nodeCount node path + 1
            let pathRef =
                lazy (
                    nextNodes
                    |> List.map (RuntimeHelpers.GetHashCode >> string)
                    |> String.concat "/"
                    |> CompilerIdentityKernel.ContentDigest.ofText "eval-node-path")
            { nodes = nextNodes; pathRef = pathRef }, count

        let exit (path:EvalNodePath) (node:obj) : EvalNodePath =
            let rec removeFirst acc = function
                | [] -> List.rev acc
                | head :: tail when obj.ReferenceEquals(head, node) -> List.rev acc @ tail
                | head :: tail -> removeFirst (head :: acc) tail
            let nextNodes = removeFirst [] path.nodes
            let pathRef =
                lazy (
                    nextNodes
                    |> List.map (RuntimeHelpers.GetHashCode >> string)
                    |> String.concat "/"
                    |> CompilerIdentityKernel.ContentDigest.ofText "eval-node-path")
            { nodes = nextNodes; pathRef = pathRef }

        let snapshotHashes n (path:EvalNodePath) =
            path.nodes
            |> Seq.truncate n
            |> Seq.map RuntimeHelpers.GetHashCode
            |> Seq.toArray

        let pathRef (path:EvalNodePath) = path.pathRef.Value

    /// Diagnostic stack depth is also explicit.  It is not authority, but it
    /// must survive fiber migration and therefore cannot live in ThreadLocal.
    module EvalStackDepthGuard =
        let empty =
            { keys = []
              counts = Map.empty
              pathRef = lazy (CompilerIdentityKernel.ContentDigest.ofText "eval-key-path" "empty") }

        let private keyPathRef (keys: string list) =
            keys
            |> String.concat "/"
            |> CompilerIdentityKernel.ContentDigest.ofText "eval-key-path"

        let enter (path:EvalKeyPath) (key:string) : EvalKeyPath * int =
            let count = 1 + (match Map.tryFind key path.counts with Some n -> n | None -> 0)
            let nextKeys = key :: path.keys
            { keys = nextKeys; counts = Map.add key count path.counts; pathRef = lazy (keyPathRef nextKeys) }, count

        let exit (path:EvalKeyPath) (key:string) : EvalKeyPath =
            let rec removeFirst acc = function
                | [] -> List.rev acc
                | head :: tail when head = key -> List.rev acc @ tail
                | head :: tail -> removeFirst (head :: acc) tail
            let nextKeys = removeFirst [] path.keys
            let counts =
                match Map.tryFind key path.counts with
                | Some n when n > 1 -> Map.add key (n - 1) path.counts
                | Some _ -> Map.remove key path.counts
                | None -> path.counts
            { keys = nextKeys; counts = counts; pathRef = lazy (keyPathRef nextKeys) }

        let snapshotKeys n (path:EvalKeyPath) =
            path.keys
            |> Seq.truncate n
            |> Seq.toArray

        let pathRef (path:EvalKeyPath) = path.pathRef.Value

    /// ### Range helpers (prepass / evaluation)
    /// These helpers are used by diagnostics and recursion guards. They intentionally prefer
    /// whatever range is available in the node itself, and fall back to the current trace (if any)
    /// or to an unknown range.
    let private vscpos0 : VSCPos = {| line = 0; character = 0 |}
    let private vscrange0 : VSCRange = (vscpos0, vscpos0)
    let private range0 : Range = { path = "<unknown>"; range = vscrange0 }
    

    let rec range_of_tprepass_or (fallback: Range) (x: TPrepass) : Range =
        match x with
        | TForall'(r,_,_,_) -> r
        | TForall(r,_,_) -> r
        | TJoinPoint'(r,_,_) -> r
        | TJoinPoint(r,_) -> r
        | TB r -> r
        | TLit(r,_) -> r
        | TPair(r,_,_) -> r
        | TRecord(r,_) -> r
        | TUnion(r,_) -> r
        | TSymbol(r,_) -> r
        | TApply(r,_,_) -> r
        | TTerm(r,_) -> r
        | TMacro(r,_) -> r
        | TTypecase(r,_,_) -> r
        | TArrow(_,b) -> range_of_tprepass_or fallback b
        | TArrow'(_,_,b) -> range_of_tprepass_or fallback b
        | TFun(a,b,_) ->
            // Prefer left, but if it is also unknown fall back to right.
            let ra = range_of_tprepass_or fallback a
            if ra.path <> "<unknown>" then ra else range_of_tprepass_or fallback b
        | TLayout(a,_) -> range_of_tprepass_or fallback a
        | TArray a -> range_of_tprepass_or fallback a
        | TPatternRef a -> range_of_tprepass_or fallback !a
        | TV _ | TPrim _ | TNominal _ | TExists | TModule _ | TMetaV _ -> fallback
    

    let rec range_of_e_or (fallback: Range) (x: E) : Range =
        match x with
        | EFun(r,_,_,_) -> r
        | EFun'(r,_,_,_,_) -> r
        | EForall(r,_,_) -> r
        | EForall'(r,_,_,_) -> r
        | ERecursiveFun'(r,_,_,_,_) -> r
        | ERecursiveForall'(r,_,_,_) -> r
        | EJoinPoint(r,_,_,_,_) -> r
        | EJoinPoint'(r,_,_,_,_,_) -> r
        | EB r -> r
        | ELit(r,_) -> r
        | EDefaultLit(r,_,_) -> r
        | ESymbol(r,_) -> r
        | EType(r,_) -> r
        | EApply(r,_,_) -> r
        | EArray(r,_,_) -> r
        | ETypeApply(r,_,_) -> r
        | ERecBlock(r,_,_) -> r
        | ERecordWith(r,_,_,_) -> r
        | EOp(r,_,_) -> r
        | EAnnot(r,_,_) -> r
        | EIfThenElse(r,_,_,_) -> r
        | EIfThen(r,_,_) -> r
        | EPair(r,_,_) -> r
        | ESeq(r,_,_) -> r
        | EMutableSet(r,_,_,_) -> r
        | EReal(r,_) -> r
        | EExists(r,_,_) -> r
        | EMacro(r,_,_) -> r
        | EPrototypeApply(r,_,_) -> r
        | ENominal(r,_,_) -> r
        | ELet(r,_,_,_) -> r
        | EUnbox(r,_,_,_,_,_) -> r
        | EExistsTest(r,_,_,_,_,_) -> r
        | EPairTest(r,_,_,_,_,_) -> r
        | ESymbolTest(r,_,_,_,_) -> r
        | ERecordTest(r,_,_,_,_) -> r
        | EAnnotTest(r,_,_,_,_) -> r
        | EUnitTest(r,_,_,_) -> r
        | ENominalTest(r,_,_,_,_,_) -> r
        | ELitTest(r,_,_,_,_) -> r
        | EDefaultLitTest(r,_,_,_,_,_) -> r
        | ETypecase(r,_,_) -> r
        | EV _ -> fallback
        | EModule _ -> fallback
        | ERecursive a -> range_of_e_or fallback !a
        | EPatternRef a -> range_of_e_or fallback !a
        | EPatternMiss a -> range_of_e_or fallback a
        | ETypePatternMiss a -> range_of_tprepass_or fallback a
        | EPatternMemo a -> range_of_e_or fallback a
    /// ### SuspectCache
    /// Track cache keys that produced type mismatches (EJP0007).
    /// Keys marked as suspect are treated with extra caution during retry.
    module SuspectCache =
        open System
        open System.Collections.Concurrent
    

        type SuspectEntry = {
            generation: int64
            timestamp: DateTime
            depth: int
            errorType: string
            hitCount: int
        }
    

        let private suspects = System.Collections.Concurrent.ConcurrentDictionary<int, SuspectEntry>()  // key hash -> entry
        let private maxEntries = 1000
    

        /// Hash a cache key for tracking
        let private hashKey (key: obj) : int =
            try key.GetHashCode() with _ -> 0
    

        /// Mark a key as suspect
        let mark (key: obj) (errorType: string) =
            let h = hashKey key
            let depth = RecursionTracker.observerDepthUnavailable
            let gen = CacheGeneration.current ()
            let entry = {
                generation = gen
                timestamp = DateTime.UtcNow
                depth = depth
                errorType = errorType
                hitCount = 1
            }
            suspects.AddOrUpdate(h, entry, (fun _ existing ->
                { existing with hitCount = existing.hitCount + 1; timestamp = DateTime.UtcNow }
            )) |> ignore
            // Trim if too large (remove oldest 10%)
            if suspects.Count > maxEntries then
                let toRemove =
                    suspects.ToArray()
                    |> Array.sortBy (fun kv -> kv.Value.timestamp)
                    |> Array.take (maxEntries / 10)
                for kv in toRemove do
                    suspects.TryRemove(kv.Key) |> ignore
            DiagSidecar.emit (FastRuntimeFormat.format "SuspectCache.mark: hash=%d depth=%d error=%s" [| box h; box depth; box errorType |])
        let private isActive (entry: SuspectEntry) =
            let cur = CacheGeneration.current ()
            // Keep suspects alive across a small retry window (current + next 2 generations).
            entry.generation + 2L >= cur
    
    
    



        /// Check if a key is suspect in current generation
        let isSuspect (key: obj) : bool =
            let h = hashKey key
            match suspects.TryGetValue(h) with
            | true, entry -> isActive entry
            | _ -> false
    

        /// Check if a key is suspect and return entry
        let tryGetSuspect (key: obj) : SuspectEntry option =
            let h = hashKey key
            match suspects.TryGetValue(h) with
            | true, entry when isActive entry -> Some entry
            | _ -> None
    

        /// Clear suspects for a generation (after successful retry)
        let clearForGeneration (gen: int64) =
            let toRemove =
                suspects.ToArray()
                |> Array.filter (fun kv -> kv.Value.generation <= gen)
            for kv in toRemove do
                suspects.TryRemove(kv.Key) |> ignore
            DiagSidecar.emit (sprintf "SuspectCache.clearForGeneration: gen=%d removed=%d" gen toRemove.Length)
    

        /// Get recent suspects for diagnostics
        let getRecent (n: int) : (int * SuspectEntry) list =
            suspects.ToArray()
            |> Array.sortByDescending (fun kv -> kv.Value.timestamp)
            |> Array.truncate n
            |> Array.map (fun kv -> kv.Key, kv.Value)
            |> Array.toList
    

        /// Get count of suspects in current generation
        let currentCount () =
            suspects.ToArray()
            |> Array.filter (fun kv -> isActive kv.Value)
            |> Array.length
    

    /// ### BitMamba (BitNet B1.58)
    /// True ternary neural network for predictive cache management.
    /// Uses BitNet B1.58 architecture: weights quantized to {-1, 0, +1}.
    /// This achieves similar accuracy to full-precision at ~10x lower memory/compute.
    ///
    /// ARCHITECTURE:
    /// - Input features: [depth, failRate, accessCount, timeSinceLastFail, isSuspect]
    /// - Hidden layer: 16 neurons with ternary weights
    /// - Output: 3-way classification [Valid, Suspect, Unknown]
    /// - Online learning: Updates weights based on actual outcomes
    module BitMamba =
        open System
        open System.Collections.Concurrent
    

        type AccessPattern = {
            keyHash: int
            depth: int
            generation: int64
            threadId: int
            timestamp: DateTime
            wasSuspect: bool
        }
    

        type Prediction =
            | LikelyValid
            | LikelySuspect
            | Unknown
    

        type KeyStat = {
            accesses: int
            failures: int
            generation: int64
            lastTs: DateTime
            lastFailTs: DateTime option
        }
    

        /// B1.58 ternary weight: -1, 0, or +1
        type TernaryWeight = int8
    

        /// BitNet B1.58 layer with ternary weights
        type BitNetLayer = {
            weights: TernaryWeight[,]  // [input_dim, output_dim]
            biases: int[]              // Integer biases for efficiency
        }
    

        let private inputDim = 5      // depth, failRate, accessCount, timeSinceLastFail, isSuspect
        let private hiddenDim = 16
        let private outputDim = 3     // Valid, Suspect, Unknown
    

        // Online-learned weights (initialized with heuristic priors)
        let private layer1Weights = Array2D.init inputDim hiddenDim (fun i j ->
            // Prior: depth and failRate strongly predict suspicion
            match i, j % 4 with
            | 0, 0 -> 1y   // depth -> suspicion detectors
            | 0, 1 -> 1y
            | 1, 2 -> 1y   // failRate -> suspicion
            | 1, 3 -> 1y
            | 4, 0 -> 1y   // isSuspect -> suspicion
            | 4, 1 -> 1y
            | 2, 2 -> -1y  // high accessCount -> likely valid
            | 2, 3 -> -1y
            | _ -> 0y      // Pruned connections
        )
    

        let private layer2Weights = Array2D.init hiddenDim outputDim (fun i j ->
            // Map hidden activations to predictions
            match j with
            | 0 -> if i % 4 = 2 || i % 4 = 3 then 1y else 0y   // Valid
            | 1 -> if i % 4 = 0 || i % 4 = 1 then 1y else 0y   // Suspect
            | 2 -> 0y  // Unknown is default
            | _ -> 0y
        )
    

        let private layer1Biases = Array.init hiddenDim (fun _ -> 0)
        let private layer2Biases = [| 0; -2; 1 |]  // Bias toward Unknown, against Suspect
    

        // Statistics tracking
        let private recentAccesses = ConcurrentQueue<AccessPattern>()
        let private maxHistory = 256
        let private keyStats = System.Collections.Concurrent.ConcurrentDictionary<int, KeyStat>()
    

        // Online learning: track prediction accuracy (mutable for Interlocked)
        let mutable private predictionCount = 0L
        let mutable private correctPredictions = 0L
        let private predictionStatsGate = obj()
    

        /// Quantize float feature to int8 range [-127, 127]
        let  private quantize (x: float) : int =
            int (Math.Clamp(x * 127.0, -127.0, 127.0))
    

        /// B1.58 forward pass: compute activations using ternary weights
        let private forward (features: float[]) : int[] =
            // Quantize inputs
            let qInput = features |> Array.map quantize
    

            // Hidden layer: sum of ternary-weighted inputs
            let hidden = Array.init hiddenDim (fun j ->
                let mutable sum = layer1Biases.[j]
                for i = 0 to inputDim - 1 do
                    let w = int layer1Weights.[i, j]
                    if w <> 0 then sum <- sum + w * qInput.[i]
                // ReLU activation (implemented as max 0)
                max 0 sum
            )
    

            // Output layer
            let output = Array.init outputDim (fun j ->
                let mutable sum = layer2Biases.[j]
                for i = 0 to hiddenDim - 1 do
                    let w = int layer2Weights.[i, j]
                    if w <> 0 then sum <- sum + w * hidden.[i]
                sum
            )
            output
    

        let private updateStat (h: int) (f: KeyStat -> KeyStat) =
            let gen = CacheGeneration.current ()
            let now = DateTime.UtcNow
            keyStats.AddOrUpdate(
                h,
                (fun _ -> f { accesses = 0; failures = 0; generation = gen; lastTs = now; lastFailTs = None }),
                (fun _ old ->
                    let baseStat =
                        if old.generation = gen then old
                        else { accesses = 0; failures = 0; generation = gen; lastTs = now; lastFailTs = None }
                    f { baseStat with lastTs = now }
                )
            ) |> ignore
    

        /// Extract features from key statistics
        let private extractFeatures (h: int) : float[] =
            let depth = float (RecursionTracker.observerDepthUnavailable)
            let gen = CacheGeneration.current ()
            let now = DateTime.UtcNow
    

            match keyStats.TryGetValue(h) with
            | true, st when st.generation = gen ->
                let failRate = if st.accesses > 0 then float st.failures / float st.accesses else 0.0
                let accessCount = float st.accesses / 100.0  // Normalize
                let timeSinceLastFail =
                    match st.lastFailTs with
                    | Some ts -> min 1.0 ((now - ts).TotalSeconds / 10.0)
                    | None -> 1.0
                let isSuspect = if SuspectCache.currentCount () > 0 then 1.0 else 0.0
                [| depth / 1000.0; failRate; accessCount; timeSinceLastFail; isSuspect |]
            | _ ->
                let isSuspect = if SuspectCache.currentCount () > 0 then 1.0 else 0.0
                [| depth / 1000.0; 0.0; 0.0; 1.0; isSuspect |]
    

        /// Record a cache access for pattern learning
        let recordAccess (key: obj) =
            let h = try key.GetHashCode() with _ -> 0
            let pattern = {
                keyHash = h
                depth = RecursionTracker.observerDepthUnavailable
                generation = CacheGeneration.current ()
                threadId = try System.Threading.Thread.CurrentThread.ManagedThreadId with _ -> 0
                timestamp = DateTime.UtcNow
                wasSuspect = SuspectCache.isSuspect key
            }
            recentAccesses.Enqueue(pattern)
            while recentAccesses.Count > maxHistory do
                let mutable v = Unchecked.defaultof<AccessPattern>
                recentAccesses.TryDequeue(&v) |> ignore
            updateStat h (fun st -> { st with accesses = st.accesses + 1 })
    

        /// Record a failure for a key (updates weights via online learning)
        let recordFailure (key: obj) =
            let h = try key.GetHashCode() with _ -> 0
            let now = DateTime.UtcNow
            updateStat h (fun st -> { st with accesses = st.accesses + 1; failures = st.failures + 1; lastFailTs = Some now })
            // Online learning: this was a miss, should have predicted Suspect
            // (Full weight update would go here in a real implementation)
    

        /// Verify prediction outcome (for online learning accuracy tracking)
        let verifyPrediction (key: obj) (actuallyFailed: bool) =
            let h = try key.GetHashCode() with _ -> 0
            let features = extractFeatures h
            let output = forward features
            let predictedSuspect = output.[1] > output.[0] && output.[1] > output.[2]
            

            // Track if prediction was correct
            if (predictedSuspect && actuallyFailed) || (not predictedSuspect && not actuallyFailed) then
                lock predictionStatsGate (fun () -> correctPredictions <- correctPredictions + 1L)
    

        /// Predict if a key access is likely to succeed or fail using B1.58 network
        let predict (key: obj) : Prediction =
            let h = try key.GetHashCode() with _ -> 0
            let features = extractFeatures h
            let output = forward features
    

            // Argmax to get prediction
            let maxIdx =
                if output.[0] > output.[1] && output.[0] > output.[2] then 0
                elif output.[1] > output.[0] && output.[1] > output.[2] then 1
                else 2
    

            lock predictionStatsGate (fun () -> predictionCount <- predictionCount + 1L)
    

            match maxIdx with
            | 0 -> LikelyValid
            | 1 -> LikelySuspect
            | _ -> Unknown
    

        /// Should we preemptively retry before waiting for cache?
        let shouldPreemptiveRetry () : bool =
            match predict (box 0) with  // Use dummy key for global check
            | LikelySuspect -> true
            | _ ->
                // Fallback heuristic: deep recursion with suspects
                let depth = RecursionTracker.observerDepthUnavailable
                let suspectCount = SuspectCache.currentCount ()
                depth > 75 && suspectCount > 0
    

        /// Get pattern summary for diagnostics (includes B1.58 accuracy)
        let getSummary () : string =
            let patterns = recentAccesses.ToArray()
            let depths = patterns |> Array.map (fun p -> p.depth)
            let avgDepth = if depths.Length > 0 then Array.averageBy float depths else 0.0
            let suspectRate =
                if patterns.Length > 0 then
                    float (patterns |> Array.filter (fun p -> p.wasSuspect) |> Array.length) / float patterns.Length
                else 0.0
    

            let gen = CacheGeneration.current ()
            let stats = keyStats.ToArray()
            let keys = stats.Length
            let genFailKeys =
                stats
                |> Array.filter (fun kv -> kv.Value.generation = gen && kv.Value.failures > 0)
                |> Array.length
    

            let preds, correct = lock predictionStatsGate (fun () -> predictionCount, correctPredictions)
            let accuracy = if preds > 0L then float correct / float preds else 0.0
    

            FastRuntimeFormat.format "b158=patterns=%d avgDepth=%.1f suspectRate=%.2f keys=%d genFailKeys=%d preds=%d acc=%.2f" [| box patterns.Length; box avgDepth; box suspectRate; box keys; box genFailKeys; box preds; box accuracy |]
    

    type JpLoopSpecializationClass =
        | JpLoopSpecializationLoopish
        | JpLoopSpecializationOrdinary

    let private jpLoopSpecializationIdentityHead (identity:string) =
        if System.String.IsNullOrWhiteSpace identity then
            ""
        else
            let tokens =
                identity.Trim().Split(
                    [| ' '; '@'; ':'; '('; ')'; '['; ']'; '/'; '\\' |],
                    StringSplitOptions.RemoveEmptyEntries)
            if tokens.Length = 0 then "" else tokens.[0]

    let jpLoopSpecializationClassOfName (identity:string) =
        match jpLoopSpecializationIdentityHead identity with
        | "<anon>"
        | "루프" -> JpLoopSpecializationLoopish
        | head when head.Equals("loop", StringComparison.OrdinalIgnoreCase) -> JpLoopSpecializationLoopish
        | _ -> JpLoopSpecializationOrdinary

    type JpMethodSpecializationBudgetExhaustedEvent =
        {
            kind : string
            method_identity : string
            budget_class_du : string
            count : int64
            cap : int
            sequential_requested : bool
            authority : string
            next : string
        }
        interface DiagJson.ITypedDiagEvent

    /// ### LoopSpecializationGuard
    /// Prevents unbounded specialization from loop patterns like loop in listm'.spi.
    /// These patterns create unique JP keys per iteration, causing exponential growth.
    /// The guard caps specializations per JP name and emits EJP0012 when exceeded.
    module LoopSpecializationGuard =
        open System.Collections.Concurrent
        open System.Threading

        /// Budgets are keyed by the full method identity, never by the display name alone.
        let private capOrdinary = 5000
        let private capLoopishParallel = 256
        let private capLoopishSequential = 1024

        let  isLoopishIdentity (methodIdentity: string) =
            match jpLoopSpecializationClassOfName methodIdentity with
            | JpLoopSpecializationLoopish -> true
            | JpLoopSpecializationOrdinary -> false

        let  capForName (methodIdentity: string) =
            if isLoopishIdentity methodIdentity then
                if CacheGeneration.isSequentialRequested() then capLoopishSequential else capLoopishParallel
            else
                capOrdinary

        /// Maximum unique JP names to track (prevent unbounded memory)
        let private maxTrackedNames = 10000

        type JpMethodIdentityKind private () =
            static member InternedKindTag () = 0x170001u
        type private JpMethodIdentityId = CompilerIdentityKernel.InternedTextId<JpMethodIdentityKind>

        module private JpMethodIdentityIdOps =
            let create value : JpMethodIdentityId =
                CompilerIdentityKernel.InternedTextId.create<JpMethodIdentityKind> value
            let text (value:JpMethodIdentityId) = CompilerIdentityKernel.InternedTextIdOps.text value

        /// Count of specializations per JP name
        let private specCounts = System.Collections.Concurrent.ConcurrentDictionary<JpMethodIdentityId, int64>()

        /// Names that have exceeded their cap (for fast rejection)
        let private cappedNames = System.Collections.Concurrent.ConcurrentDictionary<JpMethodIdentityId, bool>()

        /// Total rejections (mutable for Interlocked)
        let mutable private rejections: int64 = 0L
        let private rejectionStatsGate = obj()

        /// Get current count for a full method identity.
        let getCount (methodIdentity: string) : int64 =
            let methodId = JpMethodIdentityIdOps.create methodIdentity
            match specCounts.TryGetValue(methodId) with
            | true, count -> count
            | _ -> 0L

        /// Get the active cap for a full method identity.
        let getCapForName (methodIdentity: string) : int =
            capForName methodIdentity

        /// Check whether a full method identity has exhausted its specialization budget.
        let isExceeded (methodIdentity: string) : bool =
            if System.String.IsNullOrEmpty(methodIdentity) then false
            else cappedNames.ContainsKey(JpMethodIdentityIdOps.create methodIdentity)

        /// Record a specialization attempt. The budget never forces global sequential mode.
        let tryRecordSpecialization (methodIdentity: string) : bool =
            if System.String.IsNullOrEmpty(methodIdentity) then
                true
            else
                let methodId = JpMethodIdentityIdOps.create methodIdentity
                if cappedNames.ContainsKey(methodId) then
                    // Sequential recovery may reopen a loopish identity under its larger explicit budget,
                    // but exhausting the parallel budget never requests sequential execution by itself.
                    if CacheGeneration.isSequentialRequested() && isLoopishIdentity methodIdentity then
                        let count = getCount methodIdentity
                        let cap = capForName methodIdentity
                        if count > 0L && count <= int64 cap then
                            let mutable removed = false
                            cappedNames.TryRemove(methodId, &removed) |> ignore
                            true
                        else
                            lock rejectionStatsGate (fun () -> rejections <- rejections + 1L)
                            false
                    else
                        lock rejectionStatsGate (fun () -> rejections <- rejections + 1L)
                        false
                elif specCounts.Count >= maxTrackedNames && not (specCounts.ContainsKey(methodId)) then
                    true
                else
                    let newCount =
                        specCounts.AddOrUpdate(methodId, 1L, (fun _ count -> count + 1L))
                    let cap = capForName methodIdentity
                    if newCount > int64 cap then
                        cappedNames.TryAdd(methodId, true) |> ignore
                        let budgetClass =
                            match jpLoopSpecializationClassOfName methodIdentity with
                            | JpLoopSpecializationLoopish -> "Loopish"
                            | JpLoopSpecializationOrdinary -> "Ordinary"
                        DiagJson.emitRecord
                            ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpMethodSpecializationBudgetExhausted
                               method_identity = methodIdentity
                               budget_class_du = budgetClass
                               count = newCount
                               cap = cap
                               sequential_requested = CacheGeneration.isSequentialRequested()
                               authority = "full_method_identity_budget"
                               next = "typed_placeholder_or_annotation_degradation_without_global_sequential_cutover" }
                             : JpMethodSpecializationBudgetExhaustedEvent)
                        lock rejectionStatsGate (fun () -> rejections <- rejections + 1L)
                        false
                    else
                        true

        /// Get summary for diagnostics
        let getSummary () : string =
            let topNames =
                specCounts.ToArray()
                |> Array.sortByDescending (fun kv -> kv.Value)
                |> Array.truncate 5
                |> Array.map (fun kv -> sprintf "%s=%d" (JpMethodIdentityIdOps.text kv.Key) kv.Value)
                |> String.concat "; "
            let totalRej: int64 = lock rejectionStatsGate (fun () -> rejections)
            let cappedCount = cappedNames.Count
            FastRuntimeFormat.format "loopGuard: tracked=%d capped=%d rejections=%d top=[%s]" [| box specCounts.Count; box cappedCount; box totalRej; box topNames |]

        /// Reset (for testing)
        let reset () =
            specCounts.Clear()
            cappedNames.Clear()
            rejections <- 0L
    

    type JpSymbolSaltId =
        | JpMethodSaltSymbol of TermNameId
        | JpTypeSaltSymbol of TypeNameId
        | JpNonSaltSymbol

    let private jpSymbolSaltId (value:string) =
        if System.String.IsNullOrWhiteSpace value then
            JpNonSaltSymbol
        else
            let parts = value.Split([|'@'|], 2, StringSplitOptions.None)
            if parts.Length <> 2 then
                JpNonSaltSymbol
            else
                match parts.[0] with
                | "jp" -> JpMethodSaltSymbol(TermNameIdOps.create value)
                | "jp_type" -> JpTypeSaltSymbol(TypeNameIdOps.create value)
                | _ -> JpNonSaltSymbol

    /// ### format_jp_annot_mismatch
    /// Rust-ish, multi-line diagnostic for join-point annotation mismatches.
    /// Keep this definition after Ty + show_ty (no forward references).
    let format_jp_annot_mismatch
        (d: LangEnv)
        (kind: string)
        (tag: int)
        (key: obj)
        (jp_name: string option)
        (got: Ty)
        (expected: Ty)
        : string =
            let name_from_tables =
                match kind with
                | "method" ->
                    match key with
                    | :? ConsedNode<RData [] * Ty [] * Ty> as k ->
                        match d.join_point_method_key_names.TryGetValue k with
                        | true, n -> Some (JpNameIdOps.text n)
                        | _ -> None
                    | _ -> None
                | "closure" ->
                    match key with
                    | :? ConsedNode<RData [] * Ty [] * Ty> as k ->
                        match d.join_point_closure_key_names.TryGetValue k with
                        | true, n -> Some (JpNameIdOps.text n)
                        | _ -> None
                    | _ -> None
                | _ -> None
    

            let name =
                match jp_name, name_from_tables with
                | Some n, _ when n <> "" -> n
                | _, Some n when n <> "" -> n
                | _ -> "<anonymous>"
    

            let backend = d.backend.node
    

            let show_pos (p: VSCPos) = sprintf "%d:%d" (p.line + 1) (p.character + 1)
    

            let show_site (r: Range) =
                let (p0, p1) = r.range
                FastRuntimeFormat.format "%s:({ line = %d; character = %d }, { line = %d; character = %d })" [| box r.path; box (p0.line + 1); box (p0.character + 1); box (p1.line + 1); box (p1.character + 1) |]
    

            let primary_site =
                match d.trace with
                | r :: _ ->
                    let (p0, _) = r.range
                    sprintf "%s:%s" r.path (show_pos p0)
                | [] -> "<unknown>"
    

            let sha1_12 (s: string) : string =
                try
                    let bytes = System.Text.Encoding.UTF8.GetBytes s
                    use sha1 = System.Security.Cryptography.SHA1.Create()
                    sha1.ComputeHash(bytes)
                    |> Seq.take 6
                    |> Seq.map (fun b -> b.ToString("x2"))
                    |> String.concat ""
                with _ -> "000000000000"
    
    


            let trace_pretty =
                match d.trace with
                | [] -> "<empty trace>"
                | _ ->
                    let rec dedup acc = function
                        | a :: b :: rest when a = b -> dedup acc (b :: rest)
                        | a :: rest -> dedup (a :: acc) rest
                        | [] -> List.rev acc
    

                    let frames =
                        d.trace
                        |> List.map show_site
                        |> dedup []
    

                    // Always include full trace for better diagnostics
                    let shown = frames |> List.truncate 80
    

                    let body =
                        shown
                        |> List.mapi (fun i s -> sprintf "  %2d: %s" (i + 1) s)
                        |> String.concat "\n"
    

                    let frames_len = List.length frames
                    let shown_len = List.length shown
    

                    if frames_len > shown_len then
                        body + sprintf "\n  ... (%d more)" (frames_len - shown_len)
                    else body
    

            let fun_diff =
                match expected, got with
                | YFun (arg_expected, ret_expected, _), YFun (arg_got, ret_got, _) ->
                    if show_ty arg_expected = show_ty arg_got && show_ty ret_expected = show_ty ret_got then
                        ""
                    else
                        FastRuntimeFormat.format "  = note: param differs: expected %s, found %s\n  = note: return differs: expected %s, found %s\n" [| box (show_ty arg_expected); box (show_ty arg_got); box (show_ty ret_expected); box (show_ty ret_got) |]
                | _ -> ""
            let fun_hint =
                match expected, got with
                | YFun (arg_expected, ret_expected, _), YFun (arg_got, ret_got, _) ->
                    if show_ty ret_expected = show_ty arg_got && show_ty arg_expected <> show_ty arg_got then
                        sprintf "  = hint: expected return matches found param (%s). This often looks like a map_ok/map_error mix-up or a join-point key collision under concurrent builds.\n" (show_ty ret_expected)
                    elif show_ty arg_expected = show_ty ret_got && show_ty ret_expected <> show_ty ret_got then
                        sprintf "  = hint: expected param matches found return (%s). This can look like a swapped arrow direction or capture confusion.\n" (show_ty arg_expected)
                    else ""
                | _ -> ""
    

            let fun_diff = fun_diff + fun_hint
    
    


            let inflight_method_tags_sample =
                d.jp_method_stack |> Seq.truncate 12 |> Seq.map (fun x -> x.tag) |> Seq.toArray
            let inflight_type_tags_sample =
                d.jp_type_stack |> Seq.truncate 12 |> Seq.map (fun x -> x.tag) |> Seq.toArray
    

            let inflight_method =
                if d.jp_method_stack.Count > 0 then
                    sprintf "  = note: inflight(method) count=%d sample_tags=%A\n" d.jp_method_stack.Count inflight_method_tags_sample
                else ""
    

            let inflight_type =
                if d.jp_type_stack.Count > 0 then
                    sprintf "  = note: inflight(type) count=%d sample_tags=%A\n" d.jp_type_stack.Count inflight_type_tags_sample
                else ""
    

            let sidecar_pretty =
                match DiagSidecar.snapshot 12 with
                | [] -> ""
                | xs ->
                    let body =
                        xs
                        |> List.mapi (fun i s -> sprintf "  %2d: %s" (i + 1) s)
                        |> String.concat "\n"
                    sprintf "  |\n  = sidecar:\n%s\n" body
    

            let fingerprint = sha1_12 (FastRuntimeFormat.format "%s|%s|%d|%s|%s|%s" [| box kind; box name; box tag; box (show_ty expected); box (show_ty got); box primary_site |])
    

            let key_repr_pretty =
                match key with
                | :? ConsedNode<RData [] * Ty [] * Ty> as k ->
                    let (env_term, env_type, annot) = k.node
                    let salt =
                        if env_term.Length > 0 then
                            match env_term.[env_term.Length - 1] with
                            | ReSymbol s ->
                                match jpSymbolSaltId s with
                                | JpMethodSaltSymbol value -> Some (TermNameIdOps.text value)
                                | JpTypeSaltSymbol value -> Some (TypeNameIdOps.text value)
                                | JpNonSaltSymbol -> None
                            | _ -> None
                        else None
                    let salt_line =
                        match salt with
                        | Some s -> sprintf " (salt=%s)" s
                        | None -> ""
                    FastRuntimeFormat.format "<tag %d>%s env_term.len=%d env_type.len=%d annot=%s fingerprint=%s" [| box k.tag; box salt_line; box env_term.Length; box env_type.Length; box (show_ty annot); box fingerprint |]
                | _ -> FastRuntimeFormat.objectText (box key)
    

            // Always include source snippet for better error messages
            let source_snip =
                match d.trace with
                | r :: _ ->
                    try
                        if System.IO.File.Exists r.path then
                            let lines = System.IO.File.ReadAllLines r.path
                            let (p0, _) = r.range
                            if p0.line >= 0 && p0.line < lines.Length then
                                let ltxt = lines.[p0.line].Replace("\t","    ")
                                let caretPad = Microsoft.FSharp.Core.String.replicate (max 0 p0.character) " "
                                FastRuntimeFormat.format "  |\n  = source:\n  | %s | %s\n  |      | %s^\n" [| box (sprintf "%4d" (p0.line + 1)); box ltxt; box caretPad |]
                            else ""
                        else ""
                    with _ -> ""
                | _ -> ""
    
    


            let nn_pretty =
                match DiagNN.record ("[spiral_compiler] EJP0002|" + sha1_12 (sprintf "%s->%s" (show_ty expected) (show_ty got)))
                        (FastRuntimeFormat.format "%s|%s|%s|%d|%s|%s" [| box kind; box name; box primary_site; box tag; box (show_ty expected); box (show_ty got) |]) with
                | Some s -> sprintf "  = nn: %s\n" s
                | None -> ""
            FastRuntimeFormat.format
                """error[EJP0002]: join point annotation mismatch
      --> %s
    %s  |
      = join-point: %s (kind=%s, tag=%d)
      = backend: %s
      = key: <tag %d>
      = key_repr: %s
      |
      = declared (annotation): %s
      = found (body): %s
    %s%s%s%s%s  |
      = trace:
    %s
      |
      help: make the annotation match the body. If this appears only under concurrent builds, try a sequential run to confirm an interleaving/cache race.
    """
                [| box primary_site; box source_snip; box name; box kind; box tag; box backend; box tag; box key_repr_pretty; box (show_ty expected); box (show_ty got); box fun_diff; box inflight_method; box inflight_type; box nn_pretty; box sidecar_pretty; box trace_pretty |]
    

    /// ### PartEvalTopEnv
    type PartEvalTopEnv = {
        prototypes_instances : Dictionary<GlobalId * GlobalId, E>
        nominals : Dictionary<GlobalId, Nominal>
        backend : string
        }
    

    /// ### PartEvalTypeError
    // [EJP-212-001] PartEvalTypeError moved above BigStack (forward reference fix).
    

    type PartEvalCompilerEnvelopeId =
        | PartEvalCompilerEnvelopePresent
        | PartEvalCompilerEnvelopeAbsent

    let private partEvalCompilerEnvelopeId (text:string) =
        if System.String.IsNullOrEmpty text then
            PartEvalCompilerEnvelopeAbsent
        else
            let hasCompilerEnvelope =
                text.Split([|'\r'; '\n'|], StringSplitOptions.RemoveEmptyEntries)
                |> Array.exists (fun line -> line.Trim() = "Compiler: par")
            if hasCompilerEnvelope then PartEvalCompilerEnvelopePresent
            else PartEvalCompilerEnvelopeAbsent

    /// ### raise_type_error
    let raise_type_error (d: LangEnv) (x: string) : 'a =
        let envelope = compactPartEvalTrace d.trace
        let x =
            match partEvalCompilerEnvelopeId x with
            | PartEvalCompilerEnvelopePresent -> x
            | PartEvalCompilerEnvelopeAbsent ->
                x
                + FastRuntimeFormat.format "\nCompiler: par\nTraceDepth: %d\nTraceRetained: %d\nTraceCompacted: %b" [| box envelope.originalDepth; box envelope.retained.Length; box envelope.compacted |]
        raise (partEvalTypeError envelope.retained x)

    let raise_type_error_no_trace (d: LangEnv) (x: string) : 'a =
        let envelope = compactPartEvalTrace d.trace
        let x =
            match partEvalCompilerEnvelopeId x with
            | PartEvalCompilerEnvelopePresent -> x
            | PartEvalCompilerEnvelopeAbsent ->
                x
                + FastRuntimeFormat.format "\nCompiler: par\nTraceDepth: %d\nTraceRetained: %d\nTraceCompacted: %b" [| box envelope.originalDepth; box envelope.retained.Length; box envelope.compacted |]
        raise (partEvalTypeError envelope.retained x)

    type EvalStackProbeDecision =
        | EvalStackProbeAvailable
        | EvalStackProbeInsufficient

    type EvalCoreStackPivotReason =
        | EvalCoreTyStackProbe
        | EvalCoreTermStackProbe
        | EvalCoreRecordWithEntryStackProbe
        | EvalCoreRecordWithBatchStackProbe
        | EvalCoreRecordTestBatchStackProbe

    let private evalCoreStackPivotReasonText = function
        | EvalCoreTyStackProbe -> "ty_stack_probe"
        | EvalCoreTermStackProbe -> "term_stack_probe"
        | EvalCoreRecordWithEntryStackProbe -> "record_with_entry_stack_probe"
        | EvalCoreRecordWithBatchStackProbe -> "record_with_batch_stack_probe"
        | EvalCoreRecordTestBatchStackProbe -> "record_test_batch_stack_probe"

    exception EvalCoreStackPivotRequested of EvalCoreStackPivotReason

    type EvalCoreDirectAttempt<'a> =
        | EvalCoreDirectCompleted of 'a
        | EvalCoreDirectPivotRequested of EvalCoreStackPivotReason

    let private evalCoreDirectAttempt (s:LangEnv) impl =
        try
            EvalCoreDirectCompleted (impl s)
        with EvalCoreStackPivotRequested reason ->
            EvalCoreDirectPivotRequested reason

    let private evalStackProbeDecision () =
        if BigStack.hasSufficientExecutionStack () then
            EvalStackProbeAvailable
        else
            EvalStackProbeInsufficient

    type EvalReplayRegistrationExecution =
        | EvalReplayRegistrationCompleted
        | EvalReplayRegistrationBigStackExhausted

    [<NoEquality; NoComparison>]
    type EvalReplayRegistrationFrame =
        | EvalReplayRegistrationTermFrame of nodeId:int * expr:E

    let private evalReplayRegistrationRun
        (context:BigStackExecutionContext)
        (tagId:BigStack.BigStackJoinTagId)
        tag
        (runDirect:BigStackExecutionContext -> unit) =
        match evalStackProbeDecision () with
        | EvalStackProbeAvailable ->
            runDirect context
            EvalReplayRegistrationCompleted
        | EvalStackProbeInsufficient ->
            match BigStack.tryRun context tagId tag runDirect with
            | Some () -> EvalReplayRegistrationCompleted
            | None -> EvalReplayRegistrationBigStackExhausted

    let private evalReplayRegistrationStackFailure s siteId nodeId : 'a =
        raise_type_error s (
            FastRuntimeFormat.format
                "%s: replay registration stack budget exhausted after BigStack fallback site=%s node_id=%d"
                [| box DiagnosticClassifier.EJP0010
                   box (CompilerIdentityKernel.WorkSiteIdOps.text siteId)
                   box nodeId |])

    type EvalCoreStackExecution<'a> =
        | EvalCoreStackCompleted of 'a
        | EvalCoreStackBigStackExhausted

    type EvalCoreEntryRoute =
        | EvalCoreEntryDirect
        | EvalCoreEntryBigStack

    let private evalCoreEntryRoute (s:LangEnv) depthLimit =
        if BigStack.isActive s.bigStack then EvalCoreEntryDirect
        elif RecursionTracker.currentDepth s.recursion > depthLimit then EvalCoreEntryBigStack
        else EvalCoreEntryDirect

    let private evalCoreEntryRun s depthLimit kind tag impl =
        match evalCoreEntryRoute s depthLimit with
        | EvalCoreEntryDirect -> EvalCoreStackCompleted (impl s)
        | EvalCoreEntryBigStack ->
            match BigStack.tryRun s.bigStack kind tag (fun child -> impl (langEnvWithBigStack child s)) with
            | Some value -> EvalCoreStackCompleted value
            | None -> EvalCoreStackBigStackExhausted

    let private evalCoreWithBigStack s kind tag impl =
        let runBigStack () =
            match BigStack.tryRun s.bigStack kind tag (fun child -> impl (langEnvWithBigStack child s)) with
            | Some value -> EvalCoreStackCompleted value
            | None -> EvalCoreStackBigStackExhausted
        match evalStackProbeDecision () with
        | EvalStackProbeInsufficient -> runBigStack ()
        | EvalStackProbeAvailable ->
            match evalCoreDirectAttempt s impl with
            | EvalCoreDirectCompleted value -> EvalCoreStackCompleted value
            | EvalCoreDirectPivotRequested reason ->
                DiagSidecar.emit (
                    FastRuntimeFormat.format
                        "[spiral_compiler] eval core stack pivot reason=%s tag=%s authority=typed_stack_pivot_result_lane next=bigstack"
                        [| box (evalCoreStackPivotReasonText reason); box tag |])
                runBigStack ()
    

    [<NoEquality; NoComparison>]
    type DataPostorderTraversalFrame =
        | DataPostorderVisit of Data
        | DataPostorderBuild of Data

    [<NoEquality; NoComparison>]
    type DataPostorderChildRelation =
        | DataPostorderLeaf
        | DataPostorderChildren of Data array

    [<NoEquality; NoComparison>]
    type TyToDataTraversalFrame =
        | TyToDataVisit of Ty
        | TyToDataBuildPair
        | TyToDataBuildRecord of ((int * string) * Ty) array
        | TyToDataBuildNominal of original:Ty

    [<NoEquality; NoComparison>]
    type DynDataTraversalFrame =
        | DynDataVisit of Data
        | DynDataBuild of Data

    [<NoEquality; NoComparison>]
    type TPrepassReplayOwner =
        | TPrepassReplayGeneral
        | TPrepassReplayTypeApplyArgument
        | TPrepassReplayMacro

    [<NoEquality; NoComparison>]
    type TPrepassReplayChildRole =
        | TPrepassReplayApplyFunction
        | TPrepassReplayApplyArgument
        | TPrepassReplayPairLeft of TPrepassReplayOwner
        | TPrepassReplayPairRight of TPrepassReplayOwner
        | TPrepassReplayFunctionArgument of TPrepassReplayOwner
        | TPrepassReplayFunctionBody of TPrepassReplayOwner
        | TPrepassReplayFunctionBodyImmediateBinder of TPrepassReplayOwner
        | TPrepassReplayArrayItem
        | TPrepassReplayLayoutInner
        | TPrepassReplayModuleField of name:string
        | TPrepassReplayRecordField of order:int * name:string
        | TPrepassReplayMacroTypeItem of index:int
        | TPrepassReplayMacroLiteralTypeItem of index:int

    [<NoEquality; NoComparison>]
    type MacroReplayCachedItemKind =
        | MacroReplayCachedTerm
        | MacroReplayCachedType
        | MacroReplayCachedLiteralType

    let private macroReplayCachedItemKindText = function
        | MacroReplayCachedTerm -> "MTerm"
        | MacroReplayCachedType -> "MType"
        | MacroReplayCachedLiteralType -> "MLitType"

    let private tPrepassReplayOwnerPrefix = function
        | TPrepassReplayGeneral -> ""
        | TPrepassReplayTypeApplyArgument -> "TApplyArg."
        | TPrepassReplayMacro -> "EMacro."

    let private tPrepassReplayChildRoleText = function
        | TPrepassReplayApplyFunction -> "TApply.fn"
        | TPrepassReplayApplyArgument -> "TApply.arg"
        | TPrepassReplayPairLeft owner -> tPrepassReplayOwnerPrefix owner + "TPair.left"
        | TPrepassReplayPairRight owner -> tPrepassReplayOwnerPrefix owner + "TPair.right"
        | TPrepassReplayFunctionArgument owner -> tPrepassReplayOwnerPrefix owner + "TFun.arg"
        | TPrepassReplayFunctionBody owner -> tPrepassReplayOwnerPrefix owner + "TFun.body"
        | TPrepassReplayFunctionBodyImmediateBinder owner -> tPrepassReplayOwnerPrefix owner + "TFun.body_immediate_binder"
        | TPrepassReplayArrayItem -> "TArray.item"
        | TPrepassReplayLayoutInner -> "TLayout.inner"
        | TPrepassReplayModuleField name -> "TModule." + name
        | TPrepassReplayRecordField(order, name) -> sprintf "TRecord.%d.%s" order name
        | TPrepassReplayMacroTypeItem index -> sprintf "TMacro.type.%d" index
        | TPrepassReplayMacroLiteralTypeItem index -> sprintf "TMacro.lit.%d" index

    let private dataPostorderChildRelation = function
        | DPair(left, right) ->
            // Pair traversal is intentionally tail-first.  The modern evaluator already
            // depends on this ordering for call-argument and variable-renaming stability.
            DataPostorderChildren [| right; left |]
        | DFunction(_,_,captured,_,_,_)
        | DForall(_,captured,_,_,_) -> DataPostorderChildren captured
        | DExists(_, child)
        | DUnion(child, _)
        | DNominal(child, _) -> DataPostorderChildren [| child |]
        | DRecord fields ->
            fields
            |> Seq.map (fun (KeyValue(_, child)) -> child)
            |> Seq.toArray
            |> DataPostorderChildren
        | DHashMap(entries, _) ->
            let children = ResizeArray<Data>(entries.Count * 2)
            for entry in entries do
                children.Add entry.Key
                children.Add entry.Value
            DataPostorderChildren(children.ToArray())
        | DSymbol _ | DV _ | DLit _ | DTLit _ | DB | DHashSet _ -> DataPostorderLeaf

    let private pushDataPostorderChildren
        (stack:System.Collections.Generic.Stack<DataPostorderTraversalFrame>)
        source =
        match dataPostorderChildRelation source with
        | DataPostorderLeaf -> ()
        | DataPostorderChildren children ->
            for childIndex = children.Length - 1 downto 0 do
                stack.Push(DataPostorderVisit children.[childIndex])

    /// ### data_to_rdata
    let data_to_rdata (d: LangEnv) (hc_table : HashConsTable) call_data =
        let hc x = lock hc_table (fun () -> hc_table.Add x)
        let m = System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Reference)
        let call_args = ResizeArray()
        let convertRoot root =
            let visiting = HashSet<Data>(HashIdentity.Reference)
            let stack = System.Collections.Generic.Stack<DataPostorderTraversalFrame>()
            let lookup source =
                match m.TryGetValue source with
                | true, value -> value
                | false, _ -> invalidOp "Data→RData postorder invariant: child result missing."
            let commit source value =
                visiting.Remove source |> ignore
                m.TryAdd(source, value) |> ignore
            let pushChildren source = pushDataPostorderChildren stack source
            stack.Push(DataPostorderVisit root)
            while stack.Count > 0 do
                match stack.Pop() with
                | DataPostorderVisit source ->
                    match m.TryGetValue source with
                    | true, _ -> ()
                    | false, _ ->
                        if visiting.Add source = false then
                            raise_type_error d "Compiler error: Cyclic compile-time value detected while hashing join point environment."
                        match source with
                        | DSymbol value -> commit source (ReSymbol value)
                        | DV(L(_,ty) as term) ->
                            call_args.Add term
                            commit source (ReV(hc(call_args.Count - 1, ty)))
                        | DLit value -> commit source (ReLit value)
                        | DTLit value -> commit source (ReTLit value)
                        | DB -> commit source ReB
                        | DHashMap(_, isWritable) when isWritable.Value ->
                            raise_type_error d "error[EJP0005]: mutable compile-time HashMap cannot cross a join point boundary\n  |\n  help: freeze/clone the HashMap into an immutable representation before passing it through a join point; mutable state across join points breaks determinism (and races under parallel compilation).\n"
                        | DHashSet _ ->
                            raise_type_error d "error[EJP0006]: mutable compile-time HashSet cannot cross a join point boundary\n  |\n  help: rewrite the HashSet usage to an immutable set (or convert to an array/list) before passing it through a join point; mutable shared state can corrupt evaluation under parallel compilation.\n"
                        | _ ->
                            stack.Push(DataPostorderBuild source)
                            pushChildren source
                | DataPostorderBuild source ->
                    let value =
                        match source with
                        | DPair(left, right) -> RePair(hc(lookup left, lookup right))
                        | DFunction(body, annotation, captured, typeEnv, _, _) ->
                            ReFunction(hc(body, rFunctionAnnotationIdentity annotation, HopacExtensions.S.map lookup captured, typeEnv))
                        | DForall(body, captured, typeEnv, _, _) ->
                            ReForall(hc(body, HopacExtensions.S.map lookup captured, typeEnv))
                        | DExists(annotation, child) -> ReExists(hc(annotation, lookup child))
                        | DRecord fields -> ReRecord(hc(Map.map (fun _ child -> lookup child) fields))
                        | DUnion(child, unionType) -> ReUnion(hc(lookup child, unionType))
                        | DNominal(child, nominalType) -> ReNominal(hc(lookup child, nominalType))
                        | DHashMap(entries, isWritable) when isWritable.Value = false ->
                            entries
                            |> Seq.map (fun entry -> lookup entry.Key, lookup entry.Value)
                            |> Seq.toArray
                            |> hc
                            |> ReHashMap
                        | _ -> invalidOp "Data→RData postorder build frame reached a leaf."
                    commit source value
            lookup root
        let x = HopacExtensions.S.map convertRoot call_data
        call_args.ToArray(),x
    

    /// ### rename_global_term
    // This rename is a consideration for when I do incremental compilation.
    // In order to allow them to be cleaned by the garbage collection, I do not want the
    // references to unused nodes to end up in anywhere other than join point keys (which will be weak).
    let rename_global_term (s : LangEnv) =
        let m = System.Collections.Concurrent.ConcurrentDictionary<Data,Data>(HashIdentity.Reference)
        let convertRoot root =
            let visiting = HashSet<Data>(HashIdentity.Reference)
            let stack = System.Collections.Generic.Stack<DataPostorderTraversalFrame>()
            let lookup source =
                match m.TryGetValue source with
                | true, value -> value
                | false, _ -> invalidOp "Global-term postorder invariant: child result missing."
            let commit source value =
                visiting.Remove source |> ignore
                m.TryAdd(source, value) |> ignore
            let pushChildren source = pushDataPostorderChildren stack source
            stack.Push(DataPostorderVisit root)
            while stack.Count > 0 do
                match stack.Pop() with
                | DataPostorderVisit source ->
                    match m.TryGetValue source with
                    | true, _ -> ()
                    | false, _ ->
                        if visiting.Add source = false then
                            raise_type_error s "Compiler error: Cyclic compile-time value detected during global-term renaming."
                        match source with
                        | DSymbol _ | DLit _ | DTLit _ | DB -> commit source source
                        | DV(L(_,ty)) ->
                            let renamed = DV(L(s.i.Value,ty))
                            s.i.Value <- s.i.Value + 1
                            commit source renamed
                        | DHashMap(_, isWritable) when isWritable.Value ->
                            raise_type_error s "The mutable compile time HashMap needs to be made immutable before it can be renamed."
                        | DHashSet _ ->
                            raise_type_error s "The mutable compile-time HashSets cannot be renamed."
                        | _ ->
                            stack.Push(DataPostorderBuild source)
                            pushChildren source
                | DataPostorderBuild source ->
                    let renamed =
                        match source with
                        | DPair(left, right) -> DPair(lookup left, lookup right)
                        | DForall(body,captured,b,c,d) -> DForall(body,HopacExtensions.S.map lookup captured,b,c,d)
                        | DFunction(body,annot,captured,b,c,d) -> DFunction(body,annot,HopacExtensions.S.map lookup captured,b,c,d)
                        | DExists(annot,child) -> DExists(annot, lookup child)
                        | DRecord fields -> DRecord(Map.map (fun _ child -> lookup child) fields)
                        | DUnion(child,unionType) -> DUnion(lookup child,unionType)
                        | DNominal(child,nominalType) -> DNominal(lookup child,nominalType)
                        | DHashMap(entries,isWritable) when isWritable.Value = false ->
                            let renamedEntries = OrderedDictionary(HashIdentity.Reference)
                            for entry in entries do renamedEntries.Add(lookup entry.Key, lookup entry.Value)
                            DHashMap(renamedEntries,isWritable)
                        | _ -> invalidOp "Global-term postorder build frame reached a leaf."
                    commit source renamed
            lookup root
        {s with env_global_term = HopacExtensions.S.map convertRoot s.env_global_term}
    

    /// ### data_free_vars
    let data_free_vars call_data =
        let free_vars = ResizeArray()
        walkDataCapturedValuesDepthFirst true call_data (function
            | DV(L _ as termVar) -> free_vars.Add termVar; DataWalkPrune
            | _ -> DataWalkDescend)
        free_vars.ToArray()
    

    /// ### data_free_vars_replace
    let data_free_vars_replace s (d : Dictionary<TyV,TyV>) (x : Data) =
        let m = System.Collections.Concurrent.ConcurrentDictionary<Data,Data>(HashIdentity.Reference)
        let visiting = HashSet<Data>(HashIdentity.Reference)
        let stack = System.Collections.Generic.Stack<DataPostorderTraversalFrame>()
        let lookup source =
            match m.TryGetValue source with
            | true, value -> value
            | false, _ -> invalidOp "Free-var replacement postorder invariant: child result missing."
        let commit source value =
            visiting.Remove source |> ignore
            m.TryAdd(source, value) |> ignore
        let pushChildren source = pushDataPostorderChildren stack source
        stack.Push(DataPostorderVisit x)
        while stack.Count > 0 do
            match stack.Pop() with
            | DataPostorderVisit source ->
                match m.TryGetValue source with
                | true, _ -> ()
                | false, _ ->
                    if visiting.Add source = false then
                        raise_type_error s "Compiler error: Cyclic compile-time value detected during free-var replacement."
                    match source with
                    | DSymbol _ | DLit _ | DTLit _ | DB -> commit source source
                    | DV tyv -> commit source (DV(d[tyv]))
                    | DHashSet _ ->
                        raise_type_error s "The mutable compile-time HashSets cannot have their free vars replaced."
                    | _ ->
                        stack.Push(DataPostorderBuild source)
                        pushChildren source
            | DataPostorderBuild source ->
                let replaced =
                    match source with
                    | DPair(left, right) -> DPair(lookup left, lookup right)
                    | DForall(body,captured,b,c,d') -> DForall(body,HopacExtensions.S.map lookup captured,b,c,d')
                    | DFunction(body,annot,captured,b,c,d') -> DFunction(body,annot,HopacExtensions.S.map lookup captured,b,c,d')
                    | DExists(annot,child) -> DExists(annot, lookup child)
                    | DRecord fields -> DRecord(Map.map (fun _ child -> lookup child) fields)
                    | DUnion(child,unionType) -> DUnion(lookup child,unionType)
                    | DNominal(child,nominalType) -> DNominal(lookup child,nominalType)
                    | DHashMap(entries,isWritable) ->
                        let replacedEntries = OrderedDictionary(HashIdentity.Reference)
                        for entry in entries do replacedEntries.Add(lookup entry.Key, lookup entry.Value)
                        DHashMap(replacedEntries,ref isWritable.Value)
                    | _ -> invalidOp "Free-var replacement postorder build frame reached a leaf."
                commit source replaced
        lookup x
    

    /// ### (|C|)
    let inline (|C|) (x : _ ConsedNode) = x.node
    

    /// ### (|C'|)
    let inline (|C'|) (x : _ ConsedNode) = x.node, x.tag
    

    /// ### rdata_free_vars
    let rdata_free_vars (call_data:RData[]) =
        let visitedTags = HashSet<int>()
        let free_vars = ResizeArray()
        let pending = ResizeArray<RData>()
        let push value = pending.Add value
        // LIFO push in reverse preserves the old left-to-right depth-first visitation order
        // while removing host-stack growth from deeply nested captured environments.
        for i = call_data.Length - 1 downto 0 do push call_data.[i]
        while pending.Count > 0 do
            let last = pending.Count - 1
            let current = pending.[last]
            pending.RemoveAt last
            match current with
            | RePair(C'((a,b),tag)) ->
                if visitedTags.Add tag then push b; push a
            | ReForall(C'((_,captured,_),tag))
            | ReFunction(C'((_,_,captured,_),tag)) ->
                if visitedTags.Add tag then
                    for i = captured.Length - 1 downto 0 do push captured.[i]
            | ReRecord(C'(fields,tag)) ->
                if visitedTags.Add tag then
                    let values = fields |> Seq.map (fun (KeyValue(_,value)) -> value) |> Seq.toArray
                    for i = values.Length - 1 downto 0 do push values.[i]
            | ReV(C'((a,b),tag)) ->
                if visitedTags.Add tag then free_vars.Add(L(a,b))
            | ReExists(C'((_,a),tag))
            | ReUnion(C'((a,_),tag))
            | ReNominal(C'((a,_),tag)) ->
                if visitedTags.Add tag then push a
            | ReHashMap(C'(entries,tag)) ->
                if visitedTags.Add tag then
                    for i = entries.Length - 1 downto 0 do
                        let k,v = entries.[i]
                        push v
                        push k
            | ReSymbol _ | ReLit _ | ReTLit _ | ReB -> ()
        // A ReV's index is its position in the call arguments (`data_to_rdata`), which walks pairs tail-first
        // (`dataPostorderChildRelation`) while this walk is head-first. Parameters must line up with the
        // arguments, so order them by that index rather than by visit order.
        free_vars.ToArray() |> Array.sortBy (fun (L(i,_)) -> i)


    /// ### data_term_vars'
    let data_term_vars' call_data =
        let term_vars = ResizeArray(64)
        walkDataCapturedValuesDepthFirst false call_data (function
            | DLit _ | DV _ as x -> term_vars.Add x; DataWalkPrune
            | _ -> DataWalkDescend)
        term_vars.ToArray()
    

    /// ### data_nominals
    let data_nominals call_data =
        let term_vars = ResizeArray(64)
        walkDataCapturedValuesDepthFirst false call_data (function
            | DLit _ | DV _
            | DExists _ | DUnion _ | DNominal _ as x -> term_vars.Add x; DataWalkPrune
            | _ -> DataWalkDescend)
        term_vars.ToArray()
    

    /// ### data_term_vars
    let data_term_vars call_data =
        let term_vars = ResizeArray(64)
        walkDataCapturedValuesDepthFirst false call_data (function
            | DLit x -> term_vars.Add(WLit x); DataWalkPrune
            | DV x -> term_vars.Add(WV x); DataWalkPrune
            | _ -> DataWalkDescend)
        term_vars.ToArray()
    

    /// ### lit_to_primitive_type
    let lit_to_primitive_type = function
        | LitUInt8 _ -> UInt8T
        | LitUInt16 _ -> UInt16T
        | LitUInt32 _ -> UInt32T
        | LitUInt64 _ -> UInt64T
        | LitInt8 _ -> Int8T
        | LitInt16 _ -> Int16T
        | LitInt32 _ -> Int32T
        | LitInt64 _ -> Int64T
        | LitFloat32 _ -> Float32T
        | LitFloat64 _ -> Float64T
        | LitBool _ -> BoolT
        | LitString _ -> StringT
        | LitChar _ -> CharT
    

    /// ### lit_to_ty
    let lit_to_ty x = lit_to_primitive_type x |> YPrim
    

    /// ### isReplayAtomCondition
    /// An `if` condition the replay driver may evaluate ahead of the direct evaluator: one that emits no code.
    let isReplayAtomCondition = function
        | EV _ | ELit _ | ESymbol _ -> true
        | _ -> false
    

    /// ### is_tco_compatible
    let is_tco_compatible = function
        | TyApply _ | TyJoinPoint _ | TyArrayLiteral _ | TyUnionBox _ | TyToLayout _
        | TyIf _ | TyIntSwitch _ | TyUnionUnbox _ | TyArrayCreate _ | TyFailwith _ -> true
        | _ -> false
    

    /// ### seq_apply
    let seq_apply (d: LangEnv) end_dat =
        let end_ () = d.seq.Add(TyLocalReturnData(end_dat,d.trace))
        // Replay rebuilds values, so the returned data can be a new object for what the last let binds (e.g. a
        // new `DNominal` around the same `DV` for an `array`). Compare variable ids through nominals and pairs,
        // not references, or a tail `if`/call stays let-bound and loses its tail call.
        let rec sameReturn (a : Data) (b : Data) =
            Object.ReferenceEquals(a, b)
            || (match a, b with
                | DV(L(i,_)), DV(L(j,_)) -> i = j
                | DNominal(a,ta), DNominal(b,tb) -> ta = tb && sameReturn a b
                | DPair(a1,b1), DPair(a2,b2) -> sameReturn a1 a2 && sameReturn b1 b2
                | _ -> false)
        if d.seq.Count > 0 then
            match d.seq.[d.seq.Count-1] with
            | TyLet(end_dat',a,b) when sameReturn end_dat end_dat' && is_tco_compatible b -> d.seq.[d.seq.Count-1] <- TyLocalReturnOp(a,b,end_dat')
            | _ -> end_()
        else end_()
        d.seq.ToArray()
    

    /// ### cse_tryfind
    let cse_tryfind (d: LangEnv) key =
        // The tables are ConcurrentDictionary: an enclosing scope's table can be written by another Hopac
        // job while this one reads it, and a plain Dictionary read during a write is undefined. Reads stay
        // lock-free (a monitor here serialized every lookup through the outer scopes and cost ~20%).
        d.cse |> List.tryPick (fun x ->
            match x.TryGetValue key with
            | true, v -> Some v
            | _ -> None
            )
    

    /// ### debugTermTrace
    /// SPIRAL_DEBUG_TERM_TRACE=<path-suffix>:<line> (1-based) logs every `term` evaluation of an application
    /// on that source line, with its scope's `seq` identity and the compiler frames, to
    /// SPIRAL_DEBUG_TERM_TRACE_FILE (default %TEMP%/spiral-term-trace.txt). Finds which path evaluates a
    /// term in which scope (a `while` body evaluated once in its parent scope).
    let debugTermTrace =
        lazy (
            match Environment.GetEnvironmentVariable "SPIRAL_DEBUG_TERM_TRACE" with
            | null | "" -> None
            | spec ->
                let split = spec.LastIndexOf ':'
                match (if split > 0 then Int32.TryParse(spec.Substring(split + 1)) else (false, 0)) with
                | true, line ->
                    let file =
                        match Environment.GetEnvironmentVariable "SPIRAL_DEBUG_TERM_TRACE_FILE" with
                        | null | "" -> IO.Path.Combine(IO.Path.GetTempPath(), "spiral-term-trace.txt")
                        | path -> path
                    Some (spec.Substring(0, split).Replace('\\', '/'), line - 1, file)
                | _ -> None)
    let debugTermTraceLock = obj ()

    /// Appends `tag` and the compiler stack to the SPIRAL_DEBUG_TERM_TRACE file when `r` starts on the
    /// traced line; `seqId`/`seqCount` identify the statement sequence being appended to.
    let debugTraceAt (r: Range) (tag: string) (seqId: int) (seqCount: int) =
        match debugTermTrace.Value with
        | Some (suffix, line, file) when (fst r.range).line = line && r.path.Replace('\\', '/').EndsWith suffix ->
            let frames =
                Environment.StackTrace.Split('\n')
                |> Array.map (fun frame -> frame.Trim())
                |> Array.filter (fun frame -> frame.Contains "Polyglot")
                |> Array.truncate 30
            let entry =
                sprintf "=== %s at %d:%d seq=%d count=%d thread=%d\n%s\n"
                    tag ((fst r.range).line + 1) (fst r.range).character seqId seqCount
                    Threading.Thread.CurrentThread.ManagedThreadId (String.concat "\n" frames)
            lock debugTermTraceLock (fun () -> IO.File.AppendAllText(file, entry))
        | _ -> ()

    /// ### cse_add
    let cse_add (d: LangEnv) k v = (List.head d.cse).TryAdd(k,v) |> ignore
    

    /// ### show_data
    let show_data x =
        let maxDepth = 96
        let rec f depth prec x =
            if depth >= maxDepth then "…"
            else
                let p = p prec
                let next = depth + 1
                match x with
                | DB -> "()"
                | DPair(a,b) -> p 25 (sprintf "%s, %s" (f next 25 a) (f next 24 b))
                | DSymbol x -> sprintf ".%s" x
                | DFunction _ -> p 20 "? -> ?"
                | DForall _ -> p 0 "forall ?. ?"
                | DExists(a,b) ->
                    let a = HopacExtensions.S.map (show_ty >> sprintf "(%s)") a |> String.concat " "
                    p 0 $"exists {a}. %s{f next 0 b}"
                | DRecord l -> sprintf "{%s}" (l |> Map.toList |> List.map (fun ((_,k),v) -> sprintf "%s : %s" k (f next -1 v)) |> String.concat "; ")
                | DLit a -> show_lit a
                | DTLit a -> $"`{show_lit a}"
                | DV(L(_,ty)) -> show_ty ty
                | DUnion(a,_) -> f next prec a
                | DNominal(a,b) -> p 0 (sprintf "%s : %s" (f next 0 a) (show_ty b))
                | DHashSet _ -> p 0 "<HashSet>"
                | DHashMap _ -> p 0 "<HashMap>"
    

        f 0 -1 x
    

    type JpRecPlaceholderKind =
        | JpMethodRecPlaceholder
        | JpTypeRecPlaceholder
        | JpClosureRecPlaceholder
        | JpArrayElementRecPlaceholder
        | JpMethodUnknownReturn

    let jpRecPlaceholderKindText = function
        | JpMethodRecPlaceholder -> "JPMethodRecPlaceholder"
        | JpTypeRecPlaceholder -> "JPTypeRecPlaceholder"
        | JpClosureRecPlaceholder -> "JPClosureRecPlaceholder"
        | JpArrayElementRecPlaceholder -> "JPArrayElementRecPlaceholder"
        | JpMethodUnknownReturn -> "JPMethodUnknownRet"

    let jpRecPlaceholderSymbol kind payload =
        jpRecPlaceholderKindText kind + "(" + payload + ")"

    let jpMethodUnknownReturnTy =
        YSymbol (jpRecPlaceholderSymbol JpMethodUnknownReturn "par")

    let tryDecodeJpRecPlaceholderText (symbol:string) =
        let symbol =
            if not (String.IsNullOrEmpty symbol) && symbol.[0] = '.' then symbol.Substring 1
            else symbol
        let constructor = symbol.Split([|'('|], 2, StringSplitOptions.None).[0]
        match constructor with
        | "JPMethodRecPlaceholder" -> Some JpMethodRecPlaceholder
        | "JPTypeRecPlaceholder" -> Some JpTypeRecPlaceholder
        | "JPClosureRecPlaceholder" -> Some JpClosureRecPlaceholder
        | "JPArrayElementRecPlaceholder" -> Some JpArrayElementRecPlaceholder
        | "JPMethodUnknownRet" -> Some JpMethodUnknownReturn
        | _ -> None

    let tryDecodeJpRecPlaceholder = function
        | YSymbol symbol -> tryDecodeJpRecPlaceholderText symbol
        | _ -> None

    let rec tryDecodeJpRecPlaceholderData = function
        | DNominal(value,_) -> tryDecodeJpRecPlaceholderData value
        | DSymbol symbol
        | DV(L(_,YSymbol symbol)) -> tryDecodeJpRecPlaceholderText symbol
        | _ -> None

    let jpRecPlaceholderKindIsMethodOrType = function
        | JpMethodRecPlaceholder
        | JpTypeRecPlaceholder
        | JpArrayElementRecPlaceholder -> true
        | JpClosureRecPlaceholder
        | JpMethodUnknownReturn -> false

    let isJpMethodUnknownReturnData value =
        match tryDecodeJpRecPlaceholderData value with
        | Some JpMethodUnknownReturn -> true
        | _ -> false

    let isJpMethodOrTypePlaceholderType value =
        match tryDecodeJpRecPlaceholder value with
        | Some kind -> jpRecPlaceholderKindIsMethodOrType kind
        | None -> false

    let isJpMethodOrTypePlaceholderData value =
        match tryDecodeJpRecPlaceholderData value with
        | Some kind -> jpRecPlaceholderKindIsMethodOrType kind
        | None -> false

    let isJpMethodUnknownReturnType value =
        match tryDecodeJpRecPlaceholder value with
        | Some JpMethodUnknownReturn -> true
        | _ -> false

    let isJpRecPlaceholderType value = Option.isSome (tryDecodeJpRecPlaceholder value)
    let isJpRecPlaceholderData value = Option.isSome (tryDecodeJpRecPlaceholderData value)

    type JpArrayLiteralTypeDecisionId =
        | JpArrayLiteralDeclaredArray
        | JpArrayLiteralRecursivePlaceholderInferred of JpRecPlaceholderKind
        | JpArrayLiteralRecursivePlaceholderEmptyRejected of JpRecPlaceholderKind
        | JpArrayLiteralElementMismatch
        | JpArrayLiteralTypeRejected

    let jpArrayLiteralTypeDecisionText = function
        | JpArrayLiteralDeclaredArray -> "declared_array"
        | JpArrayLiteralRecursivePlaceholderInferred kind ->
            "recursive_placeholder_inferred:" + jpRecPlaceholderKindText kind
        | JpArrayLiteralRecursivePlaceholderEmptyRejected kind ->
            "recursive_placeholder_empty_rejected:" + jpRecPlaceholderKindText kind
        | JpArrayLiteralElementMismatch -> "element_mismatch"
        | JpArrayLiteralTypeRejected -> "type_rejected"

    type JpArrayOperationId =
        | JpArrayLengthOperation
        | JpArrayIndexOperation
        | JpArrayIndexSetOperation

    type JpArrayPlaceholderDecisionId =
        | JpArrayPlaceholderKnownResultDeferred of operation:JpArrayOperationId * placeholderKind:JpRecPlaceholderKind
        | JpArrayPlaceholderElementIdentityDeferred of operation:JpArrayOperationId * placeholderKind:JpRecPlaceholderKind
        | JpArrayPlaceholderResolvedElementReused of operation:JpArrayOperationId * placeholderKind:JpRecPlaceholderKind

    let jpArrayOperationText = function
        | JpArrayLengthOperation -> "array_length"
        | JpArrayIndexOperation -> "array_index"
        | JpArrayIndexSetOperation -> "array_index_set"

    let jpArrayPlaceholderDecisionText = function
        | JpArrayPlaceholderKnownResultDeferred(operation, placeholderKind) ->
            "known_result_deferred:" + jpArrayOperationText operation + ":" + jpRecPlaceholderKindText placeholderKind
        | JpArrayPlaceholderElementIdentityDeferred(operation, placeholderKind) ->
            "element_identity_deferred:" + jpArrayOperationText operation + ":" + jpRecPlaceholderKindText placeholderKind
        | JpArrayPlaceholderResolvedElementReused(operation, placeholderKind) ->
            "resolved_element_reused:" + jpArrayOperationText operation + ":" + jpRecPlaceholderKindText placeholderKind

    type JpRecursiveArrayResolutionDecisionId =
        | JpRecursiveArrayResolvedCompatible
        | JpRecursiveArrayResolvedElementMismatch
        | JpRecursiveArrayResolvedNonArray
        | JpRecursiveArrayResolutionStaleGeneration

    let jpRecursiveArrayResolutionDecisionText = function
        | JpRecursiveArrayResolvedCompatible -> "resolved_compatible"
        | JpRecursiveArrayResolvedElementMismatch -> "resolved_element_mismatch"
        | JpRecursiveArrayResolvedNonArray -> "resolved_non_array"
        | JpRecursiveArrayResolutionStaleGeneration -> "stale_generation_ignored"

    type JpRecursiveArrayObligation = private {
        obligationRef : CompilerIdentityKernel.ContentDigest
        generation : int64
        placeholderKind : JpRecPlaceholderKind
        inferredElementTy : Ty
        elementCount : int
    }

    // MIGRATION: sequence/unit recovery records observation provenance rather than
    // inferring authority from a source path. Direct ESeq evaluation keeps the historical
    // unit-only law. Only replay or a typed child carrier may classify the narrow EApply
    // residual forms below as control/replay witnesses; arbitrary non-unit Data is rejected.
    type SequenceUnitObservationId =
        | SequenceUnitDirectObservation
        | SequenceUnitReplayObservation
        | SequenceUnitTypedChildCarrierObservation

    let sequenceUnitObservationText = function
        | SequenceUnitDirectObservation -> "direct"
        | SequenceUnitReplayObservation -> "replay"
        | SequenceUnitTypedChildCarrierObservation -> "typed_child_carrier"

    type SequenceUnitCoercionDecisionId =
        | SequenceUnitAlreadyUnit
        | SequenceUnitPlaceholderAsUnit
        | SequenceApplyReplayWitnessAsUnit
        | SequenceApplyResidualRuntimeValueAsUnit
        | SequenceUnitRejected

    let sequenceUnitCoercionDecisionText = function
        | SequenceUnitAlreadyUnit -> "already_unit"
        | SequenceUnitPlaceholderAsUnit -> "placeholder_as_unit"
        | SequenceApplyReplayWitnessAsUnit -> "apply_replay_witness_as_unit"
        | SequenceApplyResidualRuntimeValueAsUnit -> "apply_residual_runtime_value_as_unit"
        | SequenceUnitRejected -> "rejected"

    let sequenceUnitObservationAllowsApplyWitnessDiscard = function
        | SequenceUnitReplayObservation
        | SequenceUnitTypedChildCarrierObservation -> true
        | SequenceUnitDirectObservation -> false

    let sequenceUnitCoercionDecisionFor observation firstExpr value =
        let applyWitnessDiscardAllowed =
            evalNodeIsApply firstExpr
            && sequenceUnitObservationAllowsApplyWitnessDiscard observation
        match value with
        | DB -> SequenceUnitAlreadyUnit
        | value when isJpRecPlaceholderData value -> SequenceUnitPlaceholderAsUnit
        | DLit _ when applyWitnessDiscardAllowed -> SequenceApplyReplayWitnessAsUnit
        | DSymbol _ when applyWitnessDiscardAllowed -> SequenceApplyReplayWitnessAsUnit
        | DV _ when applyWitnessDiscardAllowed -> SequenceApplyResidualRuntimeValueAsUnit
        | _ -> SequenceUnitRejected

    /// ### is_lit
    let is_lit = function
        | DLit _ -> true
        | _ -> false
    

    /// ### is_numeric
    let is_numeric = function
        | YPrim (UInt8T | UInt16T | UInt32T | UInt64T
            | Int8T | Int16T | Int32T | Int64T
            | Float32T | Float64T) -> true
        | _ -> false
    

    /// ### is_signed_numeric
    let is_signed_numeric = function
        | YPrim (Int8T | Int16T | Int32T | Int64T | Float32T | Float64T) -> true
        | _ -> false
    

    /// ### is_non_float_primitive
    let is_non_float_primitive = function
        | YPrim (Float32T | Float64T) -> false
        | YPrim _ -> true
        | _ -> false
    

    /// ### is_primitive
    let is_primitive = function
        | YPrim _ -> true
        | _ -> false
    

    /// ### is_string
    let is_string = function
        | YPrim StringT -> true
        | _ -> false
    

    /// ### is_char
    let is_char = function
        | YPrim CharT -> true
        | _ -> false
    

    /// ### is_float
    let is_float = function
        | YPrim (Float32T | Float64T) -> true
        | _ -> false
    

    /// ### is_bool
    let is_bool = function
        | YPrim BoolT -> true
        | _ -> false
    

    /// ### is_int
    let is_int = function
        | YPrim (UInt32T | UInt64T | Int32T | Int64T) -> true
        | _ -> false
    

    /// ### is_int
    let is_any_int = function
        | YPrim (UInt8T | UInt16T | UInt32T | UInt64T
            | Int8T | Int16T | Int32T | Int64T) -> true
        | _ -> false
    

    let is_any_int_allow_jp_placeholders value =
        match tryDecodeJpRecPlaceholder value with
        | Some JpMethodRecPlaceholder
        | Some JpTypeRecPlaceholder
        | Some JpArrayElementRecPlaceholder -> true
        | Some JpClosureRecPlaceholder
        | Some JpMethodUnknownReturn -> false
        | None -> is_any_int value

    let is_string_allow_jp_placeholders value =
        match tryDecodeJpRecPlaceholder value with
        | Some _ -> true
        | None -> is_string value
    
    


    /// ### is_int64
    let is_int64 = function
        | YPrim Int64T -> true
        | _ -> false
    

    /// ### is_int32
    let is_int32 = function
        | YPrim Int32T -> true
        | _ -> false
    

    /// ### is_lit_zero
    let is_lit_zero = function
        | DLit a ->
            match a with
            | LitInt8 0y | LitInt16 0s | LitInt32 0 | LitInt64 0L
            | LitUInt8 0uy | LitUInt16 0us | LitUInt32 0u | LitUInt64 0UL
            | LitFloat32 0.0f | LitFloat64 0.0 -> true
            | _ -> false
        | _ -> false
    

    /// ### is_lit_one
    let is_lit_one = function
        | DLit a ->
            match a with
            | LitInt8 1y | LitInt16 1s | LitInt32 1 | LitInt64 1L
            | LitUInt8 1uy | LitUInt16 1us | LitUInt32 1u | LitUInt64 1UL
            | LitFloat32 1.0f | LitFloat64 1.0 -> true
            | _ -> false
        | _ -> false
    

    /// ### is_int_lit_zero
    let is_int_lit_zero = function
        | DLit a ->
            match a with
            | LitInt8 0y | LitInt16 0s | LitInt32 0 | LitInt64 0L
            | LitUInt8 0uy | LitUInt16 0us | LitUInt32 0u | LitUInt64 0UL -> true
            | _ -> false
        | _ -> false
    

    /// ### is_int_lit_one
    let is_int_lit_one = function
        | DLit a ->
            match a with
            | LitInt8 1y | LitInt16 1s | LitInt32 1 | LitInt64 1L
            | LitUInt8 1uy | LitUInt16 1us | LitUInt32 1u | LitUInt64 1UL -> true
            | _ -> false
        | _ -> false
    

    /// ### lit_zero
    let lit_zero = function
        | YPrim Int8T -> LitInt8 0y
        | YPrim Int16T -> LitInt16 0s
        | YPrim Int32T -> LitInt32 0
        | YPrim Int64T -> LitInt64 0L
        | YPrim UInt8T -> LitUInt8 0uy
        | YPrim UInt16T -> LitUInt16 0us
        | YPrim UInt32T -> LitUInt32 0u
        | YPrim UInt64T -> LitUInt64 0UL
        | YPrim Float32T -> LitFloat32 0.0f
        | YPrim Float64T -> LitFloat64 0.0
        | _ -> failwith "Compiler error: Expected a numeric value."
    

    /// ### vt
    let vt s i = if i < s.env_global_type.Length then s.env_global_type.[i] else s.env_stack_type.[i-s.env_global_type.Length]
    

    /// ### v
    let v s i = if i < s.env_global_term.Length then s.env_global_term.[i] else s.env_stack_term.[i-s.env_global_term.Length]
    

    /// ### add_trace
    // Trace growth is owned by the immutable language environment.  A scheduler
    // migration or BigStack pivot therefore cannot reset or share a hidden budget.
    let trace_budget_default = 4096

    let trace_trunc_range : Range =
        { path = "<trace truncated>"
          range = ({| line = 0; character = 0 |}, {| line = 0; character = 0 |}) }

    let add_trace (s : LangEnv) r =
        if TraceBudgetState.exhausted s.traceBudget then s
        else
            let remaining = s.traceBudget.remaining - 1
            if remaining <= 0 then
                { s with
                    trace = trace_trunc_range :: s.trace
                    traceBudget = { remaining = 0; truncated = true } }
            else
                { s with
                    trace = r :: s.trace
                    traceBudget = { remaining = remaining; truncated = false } }

    let  globals_add (s : LangEnv) (x : string) =
        // Thread-safe global snippet accumulation (used during codegen).
        // Avoids global locks in the hot path by using a concurrent membership set; only new inserts take the lock.
        if s.globals_seen.TryAdd(GlobalNameIdOps.create x, 0uy) then
            lock s.globals_lock (fun () -> s.globals.Add x)
        x
    

    let  globals_flush (_s : LangEnv) = ()
    

    /// ### store_term
    let store_term (s : LangEnv) i v = s.env_stack_term.[i-s.env_global_term.Length] <- v
    

    /// ### store_ty
    let store_ty (s : LangEnv) i v = s.env_stack_type.[i-s.env_global_type.Length] <- v
    

    /// ### is_unify
    let is_unify s x =
        let is_metavar = HashSet()
        let rec f = function
            | YB, YB | YExists, YExists | YForall, YForall -> true
            | YFun(a,b,t), YFun(a',b',t') -> t = t' && f (a,a') && f (b,b')
            | YApply(a,b), YApply(a',b')
            | YPair(a,b), YPair(a',b') -> f (a,a') && f (b,b')
            | YSymbol a, YSymbol b -> a = b
            | YTypeFunction(a,b,c,d), YTypeFunction(a',b',c',d') -> a = a' && Array.forall2 (fun b b' -> f (b,b')) b b' && c = c' && d = d'
            | YRecord a, YRecord a' -> Map.forall (fun k v' -> match Map.tryFind k a with Some v -> f (v, v') | None -> false) a'
            | YPrim a, YPrim a' -> a = a'
            | YArray a, YArray a' -> f (a, a')
            | YMacro a, YMacro a' ->
                List.forall2 (fun a a' ->
                    match a, a' with
                    | Text a, Text a' -> a = a'
                    | Type a, Type a' -> f (a,a')
                    | _ -> false
                    ) a a'
            | YNominal a, YNominal a' -> a = a'
            | YLayout(a,b), YLayout(a',b') -> f (a,a') && b = b'
            | YUnion a, YUnion a' -> a = a'
            | YLit a, YLit b -> a = b
            | a, YMetavar i -> (is_metavar.Add i && (store_ty s i a; true)) || a = vt s i
            | _ -> false
        f x
    
    


    [<StructuralEquality; NoComparison>]
    type JpRequiredBodyProgressAuthorityId =
        | JpRequiredBodyNoFreshCheckpoint
        | JpRequiredBodyProceduralCheckpointWithinMaterialWindow of checkpointOrdinal:int64 * operationCount:int64 * checkpointAgeMs:int64 * materialSilenceAgeMs:int64 * materialSilenceFloorMs:int64 * checkpointRef:CompilerIdentityKernel.ContentDigest * durationBasisRef:CompilerIdentityKernel.ContentDigest
        | JpRequiredBodyProceduralCheckpointOutrankedByMaterialSilence of checkpointOrdinal:int64 * operationCount:int64 * checkpointAgeMs:int64 * materialSilenceAgeMs:int64 * materialSilenceFloorMs:int64 * checkpointRef:CompilerIdentityKernel.ContentDigest * durationBasisRef:CompilerIdentityKernel.ContentDigest

    module JpRequiredBodyProgressAuthorityId =
        let text = function
            | JpRequiredBodyNoFreshCheckpoint ->
                "NoFreshCheckpoint"
            | JpRequiredBodyProceduralCheckpointWithinMaterialWindow(checkpointOrdinal, operationCount, checkpointAgeMs, materialSilenceAgeMs, materialSilenceFloorMs, checkpointRef, durationBasisRef) ->
                FastRuntimeFormat.format
                    "ProceduralCheckpointWithinMaterialWindow(ordinal=%d|operations=%d|checkpoint_age_ms=%d|material_silence_age_ms=%d|material_silence_floor_ms=%d|checkpoint_ref=%s|duration_basis_ref=%s)"
                    [| box checkpointOrdinal; box operationCount; box checkpointAgeMs; box materialSilenceAgeMs; box materialSilenceFloorMs; box (CompilerIdentityKernel.ContentDigest.text checkpointRef); box (CompilerIdentityKernel.ContentDigest.text durationBasisRef) |]
            | JpRequiredBodyProceduralCheckpointOutrankedByMaterialSilence(checkpointOrdinal, operationCount, checkpointAgeMs, materialSilenceAgeMs, materialSilenceFloorMs, checkpointRef, durationBasisRef) ->
                FastRuntimeFormat.format
                    "ProceduralCheckpointOutrankedByMaterialSilence(ordinal=%d|operations=%d|checkpoint_age_ms=%d|material_silence_age_ms=%d|material_silence_floor_ms=%d|checkpoint_ref=%s|duration_basis_ref=%s)"
                    [| box checkpointOrdinal; box operationCount; box checkpointAgeMs; box materialSilenceAgeMs; box materialSilenceFloorMs; box (CompilerIdentityKernel.ContentDigest.text checkpointRef); box (CompilerIdentityKernel.ContentDigest.text durationBasisRef) |]

    [<StructuralEquality; NoComparison>]
    type JpCodegenPatternMissStasisBasisId =
        | JpCodegenPatternMissRepeatCountBasis of repeatLimit:int64
        | JpCodegenPatternMissMeasuredDurationBasis of observedP99Ms:int64 * sampleCount:int64 * durationBasisRef:CompilerIdentityKernel.ContentDigest
        | JpCodegenPatternMissRequiredBodyProgressBasis of progress:JpRequiredBodyProgressAuthorityId
        | JpCodegenPatternMissDeclaredCheckpointCycleCandidateBasis of period:int * matchedPrefix:int * sampleCount:int * candidateRef:CompilerIdentityKernel.ContentDigest
        | JpCodegenPatternMissDeclaredCheckpointStationaryBasis of repetitions:int * sampleCount:int * stateRef:CompilerIdentityKernel.ContentDigest
        | JpCodegenPatternMissDeclaredCheckpointCycleBasis of period:int * repetitions:int * sampleCount:int * cycleRef:CompilerIdentityKernel.ContentDigest

    module JpCodegenPatternMissStasisBasisId =
        let text = function
            | JpCodegenPatternMissRepeatCountBasis repeatLimit ->
                FastRuntimeFormat.format "RepeatCount(limit=%d)" [| box repeatLimit |]
            | JpCodegenPatternMissMeasuredDurationBasis(observedP99Ms, sampleCount, durationBasisRef) ->
                FastRuntimeFormat.format
                    "MeasuredDuration(p99_ms=%d|samples=%d|basis_ref=%s)"
                    [| box observedP99Ms; box sampleCount; box (CompilerIdentityKernel.ContentDigest.text durationBasisRef) |]
            | JpCodegenPatternMissRequiredBodyProgressBasis progress ->
                "RequiredBodyProgress(" + JpRequiredBodyProgressAuthorityId.text progress + ")"
            | JpCodegenPatternMissDeclaredCheckpointCycleCandidateBasis(period, matchedPrefix, sampleCount, candidateRef) ->
                FastRuntimeFormat.format
                    "DeclaredCheckpointCycleCandidate(period=%d|matched_prefix=%d|samples=%d|candidate_ref=%s)"
                    [| box period; box matchedPrefix; box sampleCount; box (CompilerIdentityKernel.ContentDigest.text candidateRef) |]
            | JpCodegenPatternMissDeclaredCheckpointStationaryBasis(repetitions, sampleCount, stateRef) ->
                FastRuntimeFormat.format
                    "DeclaredCheckpointStationary(repetitions=%d|samples=%d|state_ref=%s)"
                    [| box repetitions; box sampleCount; box (CompilerIdentityKernel.ContentDigest.text stateRef) |]
            | JpCodegenPatternMissDeclaredCheckpointCycleBasis(period, repetitions, sampleCount, cycleRef) ->
                FastRuntimeFormat.format
                    "DeclaredCheckpointCycle(period=%d|repetitions=%d|samples=%d|cycle_ref=%s)"
                    [| box period; box repetitions; box sampleCount; box (CompilerIdentityKernel.ContentDigest.text cycleRef) |]

    type JpMethodControlCancellation =
        | JpMethodPatternMissStasisCancellation of cancellationRef:CompilerIdentityKernel.ContentDigest * repeatCount:int64 * repeatLimit:int64 * stableAgeMs:int64 * stableAgeFloorMs:int64 * stasisBasis:JpCodegenPatternMissStasisBasisId

    /// The owner-local one-shot cell carries its terminal meaning with the value.
    /// Generation teardown may prune indexes, but it cannot erase whether a Full cell
    /// represents a body, an operational cancellation, or a semantic/runtime failure.
    type JpMethodBodyCellPayload =
        | JpMethodBodyCellReadyPayload of body:TypedBind [] * bodyType:Ty * methodName:string option
        | JpMethodBodyCellCancelledPayload of cancellation:JpMethodControlCancellation
        | JpMethodBodyCellFailedPayload of failure:System.Runtime.ExceptionServices.ExceptionDispatchInfo

    type JpClosureControlCancellation =
        | JpClosurePatternMissStasisCancellation of cancellationRef:CompilerIdentityKernel.ContentDigest * repeatCount:int64 * repeatLimit:int64 * stableAgeMs:int64 * stableAgeFloorMs:int64 * stasisBasis:JpCodegenPatternMissStasisBasisId

    /// Closure cells share the same terminal one-shot discipline as methods:
    /// Pending is the empty IVar; completed payloads are Ready, operationally
    /// Cancelled, or Failed with the original exception dispatch preserved.
    type JpClosureBodyCellPayload =
        | JpClosureBodyCellReadyPayload of domainData:Data * body:TypedBind []
        | JpClosureBodyCellCancelledPayload of cancellation:JpClosureControlCancellation
        | JpClosureBodyCellFailedPayload of failure:System.Runtime.ExceptionServices.ExceptionDispatchInfo

    /// ### PartEvalResult
    /// MIGRATION: Simplified type using Hopac IVar for coordination
    type PartEvalResult = {
        join_point_method : System.Collections.Concurrent.ConcurrentDictionary<JpBodyOwnerIdentity, System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<RData [] * Ty [] * Ty>, Hopac.IVar<JpMethodBodyCellPayload>> * HashConsTable * int64>
        join_point_closure : System.Collections.Concurrent.ConcurrentDictionary<JpBodyOwnerIdentity, System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<RData [] * Ty [] * Ty>, Hopac.IVar<JpClosureBodyCellPayload>> * HashConsTable * int64>
        ty_to_data : Ty -> Data
        nominal_apply : Ty -> Ty
        globals : ResizeArray<string>
        }
    /// MIGRATION: JPTypeCell now uses Hopac IVar plus a typed owner authority.
    type JpTypeOwner =
        | JpTypeUnowned
        | JpTypeOwned of threadId:int

    type JpTypeOwnershipDecision =
        | JpTypeOwnershipAcquired of threadId:int
        | JpTypeOwnershipAlreadyHeldBySelf of threadId:int
        | JpTypeOwnershipHeldByOther of ownerThreadId:int

    type JPTypeCell<'a> = private {
        ivar : Hopac.IVar<'a option>
        mutable owner : JpTypeOwner
    }

    module JpTypeCellAuthority =
        let snapshot cell = lock cell (fun () -> cell.owner)

        let tryAcquire threadId cell =
            lock cell (fun () ->
                match cell.owner with
                | JpTypeUnowned ->
                    cell.owner <- JpTypeOwned threadId
                    JpTypeOwnershipAcquired threadId
                | JpTypeOwned ownerThreadId when ownerThreadId = threadId ->
                    JpTypeOwnershipAlreadyHeldBySelf threadId
                | JpTypeOwned ownerThreadId ->
                    JpTypeOwnershipHeldByOther ownerThreadId)

        let release threadId cell =
            lock cell (fun () ->
                match cell.owner with
                | JpTypeOwned ownerThreadId when ownerThreadId = threadId ->
                    cell.owner <- JpTypeUnowned
                    true
                | _ -> false)
    

    [<Struct>]
    type JpMethodRecPlaceholderCell =
        val gen: int64
        val ph: Ty
        val v: Ty
        new(gen, ph, v) = { gen = gen; ph = ph; v = v }
    
    
    



