    type HardPoisonInferenceSourceId =
        | HardPoisonInferenceCrossKindYieldThrashOrObligationCap
        | HardPoisonInferenceUnknown

    let hardPoisonInferenceSourceText = function
        | HardPoisonInferenceCrossKindYieldThrashOrObligationCap -> "cross_kind_yield_thrash_or_hard_poison_obligation_cap"
        | HardPoisonInferenceUnknown -> "unknown"

    type CycleStopSignalId =
        | CycleStopJpWait
        | CycleStopSequentialRetry
        | CycleStopOther

    let private cycleBoundaryAtoms (text:string) =
        if System.String.IsNullOrWhiteSpace text then []
        else
            text.ToLowerInvariant().Split(
                [| '_'; '-'; '|'; ':'; '@'; '/'; ' '; '\t'; '\r'; '\n'; '('; ')'; '['; ']'; '{'; '}'; ','; ';'; '='; '"'; '\'' |],
                StringSplitOptions.RemoveEmptyEntries)
            |> Array.toList

    type PinnedReplayKeySignalId =
        | PinnedReplayTermTyBridge
        | PinnedReplayOther

    let private pinnedReplayKeySignalId (key:EvalWorklist.ReplayKeyId) =
        match cycleBoundaryAtoms (EvalWorklist.ReplayKeyIdOps.text key) with
        | "term" :: "ty" :: _ -> PinnedReplayTermTyBridge
        | _ -> PinnedReplayOther

    type TermCycleFuseSourceId =
        | TermCycleFuseSourceSequentialJpWait
        | TermCycleFuseSourceSidecarTyReentryPrefetch
        | TermCycleFuseSourceSidecarTermReentryPrefetch
        | TermCycleFuseSourceSpiralSourceCycle
        | TermCycleFuseSourceBlockedByReentry
        | TermCycleFuseSourceParentContinuationDeferred
        | TermCycleFuseSourceUnknown

    let termCycleFuseSourceText = function
        | TermCycleFuseSourceSequentialJpWait -> "sequential_jp_wait"
        | TermCycleFuseSourceSidecarTyReentryPrefetch -> "sidecar_ty_reentry_prefetch"
        | TermCycleFuseSourceSidecarTermReentryPrefetch -> "sidecar_term_reentry_prefetch"
        | TermCycleFuseSourceSpiralSourceCycle -> "spiral_source_cycle"
        | TermCycleFuseSourceBlockedByReentry -> "blocked_by_reentry"
        | TermCycleFuseSourceParentContinuationDeferred -> "semantic_parent_continuation_cycle_deferred"
        | TermCycleFuseSourceUnknown -> "unknown"

    let termCycleFuseSourceFor (diagnostic:DiagnosticClassifier.DiagnosticClassification) =
        if DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticSidecarTyReentryPrefetch diagnostic then TermCycleFuseSourceSidecarTyReentryPrefetch
        elif DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticSidecarTermReentryPrefetch diagnostic then TermCycleFuseSourceSidecarTermReentryPrefetch
        elif DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticSpiralSourceSite diagnostic
             && (DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticReentrantTermCycle diagnostic
                 || DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticReentrantTypeCycle diagnostic
                 || DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticGlobalTermCycleFuseTripped diagnostic) then
            TermCycleFuseSourceSpiralSourceCycle
        elif DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticBlockedByReentry diagnostic then TermCycleFuseSourceBlockedByReentry
        elif DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticParentContinuationDeferred diagnostic then TermCycleFuseSourceParentContinuationDeferred
        elif DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticJpWaitObservedSequentialTermCycle diagnostic then TermCycleFuseSourceSequentialJpWait
        else TermCycleFuseSourceUnknown

    type JpWaitTermCycleFuseLiveOverrideDecisionId =
        | JpWaitTermCycleFuseLiveOverrideNotAttempted
        | JpWaitTermCycleFuseLiveOverrideGranted
        | JpWaitTermCycleFuseLiveOverrideDeniedNoLiveTail
        | JpWaitTermCycleFuseLiveOverrideDeniedNoRootOrSemanticEvidence
        | JpWaitTermCycleFuseLiveOverrideDeniedRetryBudgetExhausted
        | JpWaitTermCycleFuseLiveOverrideDeniedNotSidecarOrBlockedReentry

    let jpWaitTermCycleFuseLiveOverrideDecisionText = function
        | JpWaitTermCycleFuseLiveOverrideNotAttempted -> "not_attempted"
        | JpWaitTermCycleFuseLiveOverrideGranted -> "granted"
        | JpWaitTermCycleFuseLiveOverrideDeniedNoLiveTail -> "denied_no_live_tail"
        | JpWaitTermCycleFuseLiveOverrideDeniedNoRootOrSemanticEvidence -> "denied_no_root_or_semantic_evidence"
        | JpWaitTermCycleFuseLiveOverrideDeniedRetryBudgetExhausted -> "denied_retry_budget_exhausted"
        | JpWaitTermCycleFuseLiveOverrideDeniedNotSidecarOrBlockedReentry -> "denied_not_sidecar_or_blocked_reentry"

    let jpWaitTermCycleFuseLiveOverrideRetries = function
        | JpWaitTermCycleFuseLiveOverrideGranted -> true
        | _ -> false

    let jpWaitTermCycleFuseLiveOverrideDecisionFor sourceId pending queue active semanticReceipts rootReceipts terminalSignals attempt maxAttempts =
        let liveTail = pending > 0 || queue > 0 || active > 0
        let evidence = semanticReceipts > 0 || rootReceipts > 0 || terminalSignals > 0
        let sourceEligible =
            match sourceId with
            | TermCycleFuseSourceSidecarTyReentryPrefetch
            | TermCycleFuseSourceSidecarTermReentryPrefetch
            | TermCycleFuseSourceSpiralSourceCycle
            | TermCycleFuseSourceBlockedByReentry
            | TermCycleFuseSourceParentContinuationDeferred
            | TermCycleFuseSourceSequentialJpWait -> true
            | TermCycleFuseSourceUnknown -> false
        if not sourceEligible then JpWaitTermCycleFuseLiveOverrideDeniedNotSidecarOrBlockedReentry
        elif not liveTail then JpWaitTermCycleFuseLiveOverrideDeniedNoLiveTail
        elif not evidence then JpWaitTermCycleFuseLiveOverrideDeniedNoRootOrSemanticEvidence
        elif attempt + 1 >= maxAttempts then JpWaitTermCycleFuseLiveOverrideDeniedRetryBudgetExhausted
        else JpWaitTermCycleFuseLiveOverrideGranted

    type JpStallPinnedTerminalStatusId =
        | JpStallPinnedTerminalParentContinuationCycleDeferred
        | JpStallPinnedTerminalParentReplayCycleBreakPoisoned
        | JpStallPinnedTerminalMissingAfterPrefetchBlocked
        | JpStallPinnedTerminalOther of CompilerKernelV2.OperationalReasonId

    let private jpStallPinnedTerminalStatusFor = function
        | EvalWorklist.FrameSemanticStatus SemanticParentContinuationCycleDeferred -> JpStallPinnedTerminalParentContinuationCycleDeferred
        | EvalWorklist.FrameSemanticStatus SemanticParentReplayCycleBreakPoisoned -> JpStallPinnedTerminalParentReplayCycleBreakPoisoned
        | EvalWorklist.FrameSemanticStatus SemanticMissingAfterPrefetchBlocked -> JpStallPinnedTerminalMissingAfterPrefetchBlocked
        | other -> JpStallPinnedTerminalOther(CompilerKernelV2.OperationalReasonIdOps.create (EvalWorklist.frameStatusToString other))

    let jpStallPinnedTerminalDecisionRetries = function
        | JpStallPinnedTerminalRetryLiveReplay
        | JpStallPinnedTerminalRetryLiveContinuationTail
        | JpStallPinnedTerminalRetryCycleBreakPoisonLiveTailOverride
        | JpStallPinnedTerminalRetryGenerationPrefetchMissingDependency -> true
        | JpStallPinnedTerminalAbort -> false

    let jpStallPinnedTerminalDecisionFor status rank pending replayQueue activeDepth attempt maxAttempts semanticReceipts rootReceipts terminalSignals =
        let statusId = jpStallPinnedTerminalStatusFor status
        let liveReplayOrPending = pending > 0 || replayQueue > 0 || activeDepth > 0
        let semanticOrRootEvidence = semanticReceipts > 0 || rootReceipts > 0 || terminalSignals > 0
        let liveContinuationTail =
            statusId = JpStallPinnedTerminalParentContinuationCycleDeferred
            && rank < 90
            && pending > 0
            && (replayQueue > 0 || activeDepth > 0)
            && attempt + 1 < maxAttempts
        let cycleBreakPoisonLiveTailOverride =
            statusId = JpStallPinnedTerminalParentReplayCycleBreakPoisoned
            && rank < 90
            && liveReplayOrPending
            && semanticOrRootEvidence
            && attempt + 1 <= maxAttempts + 2
        let generationPrefetchMissingDependencyRetry =
            statusId = JpStallPinnedTerminalMissingAfterPrefetchBlocked
            && liveReplayOrPending
            && attempt + 1 < maxAttempts
        if cycleBreakPoisonLiveTailOverride then
            JpStallPinnedTerminalRetryCycleBreakPoisonLiveTailOverride
        elif generationPrefetchMissingDependencyRetry then
            JpStallPinnedTerminalRetryGenerationPrefetchMissingDependency
        elif statusId = JpStallPinnedTerminalParentReplayCycleBreakPoisoned
           && rank < 90
           && liveReplayOrPending
           && attempt + 1 < maxAttempts then
            JpStallPinnedTerminalRetryLiveReplay
        elif liveContinuationTail then
            JpStallPinnedTerminalRetryLiveContinuationTail
        else
            JpStallPinnedTerminalAbort

    let jpWaitForceCloseDecision pendingNow localQueueCount explicitPending replayQueue activeDepth =
        if pendingNow > 0L then JpWaitForceCloseDeferLocalPending
        elif localQueueCount > 0 then JpWaitForceCloseDeferLocalQueue
        elif explicitPending > 0 then JpWaitForceCloseDeferExplicitWorklist
        elif replayQueue > 0 then JpWaitForceCloseDeferReplayQueue
        elif activeDepth > 0 then JpWaitForceCloseDeferReplayDriver
        else JpWaitForceCloseNoWork

    // MIGRATION: lift MIGRATION term-cycle fuse guard out of peval local scope.
    // F# does not allow this DU cluster inside the peval let-body; keeping it
    // here also migrates the remaining raw frame.status string checks into a
    // typed status DU so the next build does not depend on ad-hoc string tests.
    type TermCycleFuseFrameStatusId =
        | TermCycleFuseStatusRootComplete
        | TermCycleFuseStatusParentCyclePoisoned
        | TermCycleFuseStatusReplayObligationDeferred
        | TermCycleFuseStatusParentRepeatBlocked
        | TermCycleFuseStatusDynamicJoinBlocked
        | TermCycleFuseStatusContinuationEnvelope
        | TermCycleFuseStatusTracingExplicitLoop
        | TermCycleFuseStatusOther of CompilerKernelV2.OperationalReasonId

    let private termCycleFuseFrameStatusFor (frame: EvalWorklist.Frame) =
        match EvalWorklist.frameSemanticStatusId frame, frame.status with
        | EvalReplayValueStore.SemanticRootComplete, _ -> TermCycleFuseStatusRootComplete
        | EvalReplayValueStore.SemanticParentReplayCycleBreakPoisoned, _ -> TermCycleFuseStatusParentCyclePoisoned
        | EvalReplayValueStore.SemanticReplayObligationDeferred, _ -> TermCycleFuseStatusReplayObligationDeferred
        | EvalReplayValueStore.SemanticParentReplayStatusPreservedRepeatBlocked, _ -> TermCycleFuseStatusParentRepeatBlocked
        | EvalReplayValueStore.SemanticDynamicJoinApplyBlocked, _ -> TermCycleFuseStatusDynamicJoinBlocked
        | _, EvalWorklist.FrameContinuationEnvelope -> TermCycleFuseStatusContinuationEnvelope
        | _, EvalWorklist.FrameTracingExplicitLoop -> TermCycleFuseStatusTracingExplicitLoop
        | EvalReplayValueStore.SemanticOther reasonId, _ -> TermCycleFuseStatusOther reasonId
        | _, other -> TermCycleFuseStatusOther(CompilerKernelV2.OperationalReasonIdOps.create (EvalWorklist.frameStatusToString other))

    let private termCycleFuseFrameStatusText = function
        | TermCycleFuseStatusRootComplete -> "semantic_root_complete"
        | TermCycleFuseStatusParentCyclePoisoned -> "semantic_parent_replay_cycle_break_poisoned"
        | TermCycleFuseStatusReplayObligationDeferred -> "semantic_replay_obligation_deferred"
        | TermCycleFuseStatusParentRepeatBlocked -> "semantic_parent_replay_status_preserved_repeat_blocked"
        | TermCycleFuseStatusDynamicJoinBlocked -> "semantic_dynamic_join_apply_blocked"
        | TermCycleFuseStatusContinuationEnvelope -> "continuation_envelope"
        | TermCycleFuseStatusTracingExplicitLoop -> "tracing_explicit_loop"
        | TermCycleFuseStatusOther reasonId -> CompilerKernelV2.OperationalReasonIdOps.text reasonId

    let private termCycleFuseFrameStatusIsCrossKindLive = function
        | TermCycleFuseStatusParentCyclePoisoned
        | TermCycleFuseStatusReplayObligationDeferred
        | TermCycleFuseStatusParentRepeatBlocked
        | TermCycleFuseStatusDynamicJoinBlocked -> true
        | _ -> false

    let private termCycleFuseFrameStatusIsContinuationLive = function
        | TermCycleFuseStatusContinuationEnvelope
        | TermCycleFuseStatusTracingExplicitLoop -> true
        | _ -> false

    type TermCycleFuseLiveReplayDecisionId =
        | TermCycleFuseRaiseEjp
        | TermCycleFuseDeferLiveCrossKindReplay
        | TermCycleFuseDeferPendingJpBodies
        | TermCycleFuseDeferReplayRootWitness

    let private termCycleFuseLiveReplayDecisionText = function
        | TermCycleFuseRaiseEjp -> "raise_ejp"
        | TermCycleFuseDeferLiveCrossKindReplay -> "defer_live_cross_kind_replay"
        | TermCycleFuseDeferPendingJpBodies -> "defer_pending_jp_bodies"
        | TermCycleFuseDeferReplayRootWitness -> "defer_replay_root_witness"

    let private termCycleFuseLiveReplayDecisionFor
        (frameStatusId: TermCycleFuseFrameStatusId)
        (frame: EvalWorklist.Frame)
        (pendingJpBodies: int64)
        (enqueuedJpBodies: int64)
        (doneJpBodies: int64)
        (currentCount: int64)
        (explicitPending: int)
        (replayQueueDepth: int)
        (replayActiveDepth: int)
        =
        let liveEvalWorklist = explicitPending > 0 || replayQueueDepth > 0 || replayActiveDepth > 0
        let jpBodiesStillPending = pendingJpBodies > 0L || doneJpBodies < enqueuedJpBodies || currentCount > 1L
        let hasSemanticEvidence = EvalWorklist.frameHasSemanticEvidence frame
        if termCycleFuseFrameStatusIsCrossKindLive frameStatusId && liveEvalWorklist then
            TermCycleFuseDeferLiveCrossKindReplay
        elif jpBodiesStillPending && liveEvalWorklist && hasSemanticEvidence then
            TermCycleFuseDeferPendingJpBodies
        elif liveEvalWorklist && hasSemanticEvidence then
            TermCycleFuseDeferReplayRootWitness
        else
            TermCycleFuseRaiseEjp

    // MIGRATION: JP work-ledger record is module-level. F# rejects type declarations inside peval; keep the transacted ledger local but its shape outside the function.
    type JpWorkLedger = private {
        pending : CompilerKernelV2.NodeCount
        totalEnqueued : CompilerKernelV2.NodeCount
        lastEnqueueAt : CompilerKernelV2.MonotonicTimestamp
        frozenTotal : CompilerKernelV2.NodeCount
        totalDone : CompilerKernelV2.NodeCount
        progressStarted : bool
        workerActive : CompilerKernelV2.WorkerCount
        jobId : CompilerKernelV2.RevisionOrdinal
        totalStarted : CompilerKernelV2.NodeCount
    }

    // JP work identities and confluent outcomes are module-level domain types.
    // F# forbids local type declarations inside peval.
    type JpPartEvalFailureCauseId =
        | JpPartEvalArrayBaseExpected
        | JpPartEvalRecursiveArrayTypeUnresolved
        | JpPartEvalRecursiveArrayElementMismatch
        | JpPartEvalRecursiveArrayResolvedNonArray
        | JpPartEvalOtherTypeError

    let jpPartEvalFailureCauseText = function
        | JpPartEvalArrayBaseExpected -> "array_base_expected"
        | JpPartEvalRecursiveArrayTypeUnresolved -> "recursive_array_type_unresolved"
        | JpPartEvalRecursiveArrayElementMismatch -> "recursive_array_element_mismatch"
        | JpPartEvalRecursiveArrayResolvedNonArray -> "recursive_array_resolved_non_array"
        | JpPartEvalOtherTypeError -> "other_type_error"

    let jpPartEvalFailureCauseFor (message:string) =
        let firstLine =
            if System.String.IsNullOrWhiteSpace message then ""
            else
                message.Split([|'\r'; '\n'|], StringSplitOptions.RemoveEmptyEntries)
                |> Array.tryHead
                |> Option.defaultValue ""
                |> fun line -> line.Trim()
        match firstLine with
        | "Expected an array_base." -> JpPartEvalArrayBaseExpected
        | "Cannot infer an empty array literal while the recursive array type is unresolved." ->
            JpPartEvalRecursiveArrayTypeUnresolved
        | "Recursive array placeholder resolved with an incompatible element type." ->
            JpPartEvalRecursiveArrayElementMismatch
        | "Recursive array placeholder resolved to a non-array type." ->
            JpPartEvalRecursiveArrayResolvedNonArray
        | _ -> JpPartEvalOtherTypeError

    type JpExceptionTypeKind private () =
        static member InternedKindTag () = 0x170002u
    type JpExceptionTypeId = CompilerIdentityKernel.InternedTextId<JpExceptionTypeKind>

    module JpExceptionTypeIdOps =
        let create value : JpExceptionTypeId =
            CompilerIdentityKernel.InternedTextId.create<JpExceptionTypeKind> value
        let text (value:JpExceptionTypeId) = CompilerIdentityKernel.InternedTextIdOps.text value

    [<StructuralEquality; NoComparison>]
    type JpSemanticFailureOriginId =
        | JpSemanticFailureException of JpExceptionTypeId
        | JpSemanticFailureOperationalReason of CompilerKernelV2.OperationalReasonId

    [<StructuralEquality; NoComparison>]
    type JpWorkFailure =
        | JpObserverVerificationFailure of exceptionType:JpExceptionTypeId * failureRef:CompilerIdentityKernel.ContentDigest
        | JpPartEvalTypeFailure of causeId:JpPartEvalFailureCauseId * semanticReasonId:CompilerKernelV2.OperationalReasonId * failureRef:CompilerIdentityKernel.ContentDigest
        | JpSemanticSpecializationFailure of origin:JpSemanticFailureOriginId * failureRef:CompilerIdentityKernel.ContentDigest
        | JpCodegenBodyFailure of exceptionType:JpExceptionTypeId * failureRef:CompilerIdentityKernel.ContentDigest
        | JpPromiseProducerBindingConflictFailure of failureRef:CompilerIdentityKernel.ContentDigest
        | JpWitnessConflictFailure of failureRef:CompilerIdentityKernel.ContentDigest

    [<StructuralEquality; NoComparison>]
    type JpWorkCancellation =
        | JpGenerationCancellation of reasonId:CompilerKernelV2.OperationalReasonId * cancellationRef:CompilerIdentityKernel.ContentDigest
        | JpDuplicateAdmissionCancellation of cancellationRef:CompilerIdentityKernel.ContentDigest
        | JpPatternMissReplaySentinelCancellation of cancellationRef:CompilerIdentityKernel.ContentDigest
        | JpQueueBackpressureWorkCancellation of reasonId:CompilerKernelV2.OperationalReasonId * cancellationRef:CompilerIdentityKernel.ContentDigest
        | JpHostCancellation of reasonId:CompilerKernelV2.OperationalReasonId * cancellationRef:CompilerIdentityKernel.ContentDigest

    [<StructuralEquality; NoComparison>]
    type JpWorkCancellationRequest =
        | JpDuplicateAdmissionLocalCancellation of reasonId:CompilerKernelV2.OperationalReasonId
        | JpRejectedAdmissionCancellation of reasonId:CompilerKernelV2.OperationalReasonId
        | JpQueueBackpressureCancellation of reasonId:CompilerKernelV2.OperationalReasonId * cancellationRef:CompilerIdentityKernel.ContentDigest
        | JpGenerationScopeCancellation of reasonId:CompilerKernelV2.OperationalReasonId
        | JpHostRequestedCancellation of reasonId:CompilerKernelV2.OperationalReasonId

    let jpWorkCancellationRequestReasonId = function
        | JpDuplicateAdmissionLocalCancellation reasonId
        | JpRejectedAdmissionCancellation reasonId
        | JpQueueBackpressureCancellation(reasonId, _)
        | JpGenerationScopeCancellation reasonId
        | JpHostRequestedCancellation reasonId -> reasonId

    let jpWorkCancellationRequestReason request =
        request
        |> jpWorkCancellationRequestReasonId
        |> CompilerKernelV2.OperationalReasonIdOps.text

    let jpWorkCancellationRequestCancelsPromise = function
        | JpDuplicateAdmissionLocalCancellation _
        | JpRejectedAdmissionCancellation _
        | JpQueueBackpressureCancellation _ -> false
        | JpGenerationScopeCancellation _
        | JpHostRequestedCancellation _ -> true

    type JpFailureDeliveryOwnership =
        | JpFailureDeliveryAcquired
        | JpFailureDeliveryAlreadyTerminal of CompilerKernelV2.WorkTerminalDisposition
        | JpFailureDeliveryLostTerminalRace of CompilerKernelV2.WorkTerminalDisposition

    type JpFailureDeliveryOwnerPhase =
        | JpFailureDeliveryUnstartedOwner
        | JpFailureDeliveryWorkerOwner

    type JpCancellationDeliveryOwnership =
        | JpCancellationDeliveryAcquired
        | JpCancellationDeliveryAlreadyTerminal of CompilerKernelV2.WorkTerminalDisposition
        | JpCancellationDeliveryLostTerminalRace of CompilerKernelV2.WorkTerminalDisposition

    type JpWorkResult =
        | JpWorkSpecializationSucceeded of receiptRef:CompilerIdentityKernel.ContentDigest
        | JpWorkSpecializationFailed of JpWorkFailure
        | JpWorkSpecializationCancelled of JpWorkCancellation
        | JpWorkSpecializationSuperseded of transitionRef:CompilerIdentityKernel.ContentDigest

    let jpSemanticFailureOriginText = function
        | JpSemanticFailureException exceptionType -> "exception_type=" + JpExceptionTypeIdOps.text exceptionType
        | JpSemanticFailureOperationalReason reasonId -> "reason=" + CompilerKernelV2.OperationalReasonIdOps.text reasonId

    let jpWorkFailureText = function
        | JpObserverVerificationFailure(exceptionType, failureRef) ->
            "ObserverVerificationFailure(exception_type=" + JpExceptionTypeIdOps.text exceptionType + "|ref=" + CompilerIdentityKernel.ContentDigest.text failureRef + ")"
        | JpPartEvalTypeFailure(causeId, semanticReasonId, failureRef) ->
            "PartEvalTypeFailure(cause=" + jpPartEvalFailureCauseText causeId + "|message_ref=" + (semanticReasonId |> CompilerKernelV2.OperationalReasonIdOps.text |> CompilerIdentityKernel.ContentDigest.ofText "jp-part-eval-type-error-message" |> CompilerIdentityKernel.ContentDigest.text) + "|ref=" + CompilerIdentityKernel.ContentDigest.text failureRef + ")"
        | JpSemanticSpecializationFailure(origin, failureRef) ->
            "SemanticSpecializationFailure(" + jpSemanticFailureOriginText origin + "|ref=" + CompilerIdentityKernel.ContentDigest.text failureRef + ")"
        | JpCodegenBodyFailure(exceptionType, failureRef) ->
            "CodegenBodyFailure(exception_type=" + JpExceptionTypeIdOps.text exceptionType + "|ref=" + CompilerIdentityKernel.ContentDigest.text failureRef + ")"
        | JpPromiseProducerBindingConflictFailure failureRef ->
            "PromiseProducerBindingConflictFailure(ref=" + CompilerIdentityKernel.ContentDigest.text failureRef + ")"
        | JpWitnessConflictFailure failureRef ->
            "WitnessConflictFailure(ref=" + CompilerIdentityKernel.ContentDigest.text failureRef + ")"

    let jpWorkFailureRef = function
        | JpObserverVerificationFailure(_, failureRef)
        | JpPartEvalTypeFailure(_, _, failureRef)
        | JpSemanticSpecializationFailure(_, failureRef)
        | JpCodegenBodyFailure(_, failureRef)
        | JpPromiseProducerBindingConflictFailure failureRef
        | JpWitnessConflictFailure failureRef -> failureRef

    let jpWorkCancellationText = function
        | JpGenerationCancellation(reasonId, cancellationRef) ->
            "GenerationCancellation(reason=" + CompilerKernelV2.OperationalReasonIdOps.text reasonId + "|ref=" + CompilerIdentityKernel.ContentDigest.text cancellationRef + ")"
        | JpDuplicateAdmissionCancellation cancellationRef ->
            "DuplicateAdmissionCancellation(ref=" + CompilerIdentityKernel.ContentDigest.text cancellationRef + ")"
        | JpPatternMissReplaySentinelCancellation cancellationRef ->
            "PatternMissReplaySentinelCancellation(ref=" + CompilerIdentityKernel.ContentDigest.text cancellationRef + ")"
        | JpQueueBackpressureWorkCancellation(reasonId, cancellationRef) ->
            "QueueBackpressureCancellation(reason=" + CompilerKernelV2.OperationalReasonIdOps.text reasonId + "|ref=" + CompilerIdentityKernel.ContentDigest.text cancellationRef + ")"
        | JpHostCancellation(reasonId, cancellationRef) ->
            "HostCancellation(reason=" + CompilerKernelV2.OperationalReasonIdOps.text reasonId + "|ref=" + CompilerIdentityKernel.ContentDigest.text cancellationRef + ")"

    let jpWorkCancellationRef = function
        | JpGenerationCancellation(_, cancellationRef)
        | JpDuplicateAdmissionCancellation cancellationRef
        | JpPatternMissReplaySentinelCancellation cancellationRef
        | JpQueueBackpressureWorkCancellation(_, cancellationRef)
        | JpHostCancellation(_, cancellationRef) -> cancellationRef

    let jpWorkCancellationRequestFor = function
        | JpGenerationCancellation(reasonId, _) -> JpGenerationScopeCancellation reasonId
        | JpQueueBackpressureWorkCancellation(reasonId, cancellationRef) -> JpQueueBackpressureCancellation(reasonId, cancellationRef)
        | JpHostCancellation(reasonId, _) -> JpHostRequestedCancellation reasonId
        | JpDuplicateAdmissionCancellation _ ->
            JpDuplicateAdmissionLocalCancellation(
                CompilerKernelV2.OperationalReasonIdOps.create "typed_execution_duplicate_admission_cancelled")
        | JpPatternMissReplaySentinelCancellation _ ->
            JpRejectedAdmissionCancellation(
                CompilerKernelV2.OperationalReasonIdOps.create "typed_execution_pattern_miss_replay_sentinel_cancelled")

    let jpWorkResultText = function
        | JpWorkSpecializationSucceeded receiptRef ->
            "SpecializationSucceeded(ref=" + CompilerIdentityKernel.ContentDigest.text receiptRef + ")"
        | JpWorkSpecializationFailed failure ->
            jpWorkFailureText failure
        | JpWorkSpecializationCancelled cancellation ->
            jpWorkCancellationText cancellation
        | JpWorkSpecializationSuperseded transitionRef ->
            "SpecializationSuperseded(ref=" + CompilerIdentityKernel.ContentDigest.text transitionRef + ")"

    let jpWorkResultRef result =
        match result with
        | JpWorkSpecializationSucceeded receiptRef -> receiptRef
        | JpWorkSpecializationFailed failure -> jpWorkFailureRef failure
        | JpWorkSpecializationCancelled cancellation -> jpWorkCancellationRef cancellation
        | JpWorkSpecializationSuperseded transitionRef -> transitionRef

    type JpWorkFinalizationState =
        | JpWorkFinalizationPending
        | JpWorkFinalizationApplied

    type JpWorkFinalizationDecision =
        | JpWorkFinalizationGranted
        | JpWorkFinalizationDuplicateIgnored

    type JpWorkAdmissionDecision =
        | JpWorkAdmissionGranted
        | JpWorkAdmissionDuplicateSuppressed of existingState:CompilerKernelV2.OperationalWorkGraphNodeState
        | JpWorkAdmissionRejected of conflict:CompilerKernelV2.SemanticWorkLedgerConflict
        | JpWorkAdmissionTerminalCutoverSuppressed of reasonId:CompilerKernelV2.OperationalReasonId

    type JpActiveChildWaitDisposition =
        | JpActiveChildWaitExactAcyclic
        | JpActiveChildWaitExactCycle
        | JpActiveChildWaitProducerUnavailable

    let jpActiveChildWaitDispositionText = function
        | JpActiveChildWaitExactAcyclic -> "ExactAcyclic"
        | JpActiveChildWaitExactCycle -> "ExactCycle"
        | JpActiveChildWaitProducerUnavailable -> "ProducerUnavailable"

    type JpActiveChildWaitIdentity = private {
        waitRef : CompilerIdentityKernel.ContentDigest
        promiseRef : CompilerIdentityKernel.ContentDigest
        producerWorkId : int64
        producerBindingId : CompilerKernelV2.StableBindingId
        disposition : JpActiveChildWaitDisposition
        dispositionId : CompilerKernelV2.OperationalReasonId
    }

    type JpActiveChildWaitState =
        | JpActiveChildWaitIdle
        | JpActiveChildWaitRunning of startedAtMs:int64 * identity:JpActiveChildWaitIdentity

    [<Struct>]
    type JpCpuWorkerRef = private | JpCpuWorkerRef of CompilerIdentityKernel.ContentDigest

    module JpCpuWorkerRef =
        let create value = JpCpuWorkerRef (CompilerIdentityKernel.ContentDigest.ofText "jp-cpu-worker" value)
        let digest (JpCpuWorkerRef value) = value
        let text value = value |> digest |> CompilerIdentityKernel.ContentDigest.text

    type JpCpuTimeUnavailableReasonId =
        | JpCpuClockFault of exceptionType:CompilerKernelV2.OperationalReasonId
        | JpCpuClockAdapterNotInstalled
        | JpCpuThreadUnavailable of nativeThreadId:int
        | JpCpuNoActiveTiming
        | JpCpuWorkerMigration of startWorker:JpCpuWorkerRef * currentWorker:JpCpuWorkerRef

    let jpCpuTimeUnavailableReasonText = function
        | JpCpuClockFault exceptionType ->
            "clock_fault:" + CompilerKernelV2.OperationalReasonIdOps.text exceptionType
        | JpCpuClockAdapterNotInstalled ->
            "exclusive_cpu_clock_adapter_not_installed"
        | JpCpuThreadUnavailable nativeThreadId ->
            "native_thread_unavailable:" + string nativeThreadId
        | JpCpuNoActiveTiming ->
            "no_active_timing"
        | JpCpuWorkerMigration(startWorker, currentWorker) ->
            "worker_migration:start=" + JpCpuWorkerRef.text startWorker
            + "|current=" + JpCpuWorkerRef.text currentWorker

    type JpCpuTimeSample =
        | JpCpuTimeUnavailable of reason:JpCpuTimeUnavailableReasonId
        | JpCpuTimeExclusive of workerRef:JpCpuWorkerRef * nativeThreadId:int * cpu:CompilerKernelV2.CpuTime

    type JpCpuProgressStateId =
        | JpCpuProgressUnavailable
        | JpCpuProgressObserved of cpuMs:int64 * progressedAtMs:int64

    type JpCpuWallActivityId =
        | JpCpuWallActivityUnavailable
        | JpCpuWallActivityCpuDominant
        | JpCpuWallActivityMixed
        | JpCpuWallActivityWallDominant

    let jpCpuWallActivityFor wallExclusiveMs cpuExclusiveMs =
        match cpuExclusiveMs with
        | None -> JpCpuWallActivityUnavailable
        | Some cpu when wallExclusiveMs <= 0L ->
            if CompilerKernelV2.Measured.value cpu > 0L then JpCpuWallActivityCpuDominant
            else JpCpuWallActivityUnavailable
        | Some cpu ->
            let cpuMs = max 0L (CompilerKernelV2.Measured.value cpu)
            if cpuMs * 4L >= wallExclusiveMs * 3L then JpCpuWallActivityCpuDominant
            elif cpuMs * 4L >= wallExclusiveMs then JpCpuWallActivityMixed
            else JpCpuWallActivityWallDominant

    let jpCpuWallActivityText = function
        | JpCpuWallActivityUnavailable -> "Unavailable"
        | JpCpuWallActivityCpuDominant -> "CpuDominant"
        | JpCpuWallActivityMixed -> "Mixed"
        | JpCpuWallActivityWallDominant -> "WallDominant"

    type JpCpuClock = private {
        clockRef : CompilerIdentityKernel.ContentDigest
        sampleCurrent : unit -> JpCpuTimeSample
        sampleSameWorker : JpCpuTimeSample -> JpCpuTimeSample
    }

    module private JpNativeThreadCpuClock =
        [<System.Runtime.InteropServices.DllImport("kernel32.dll", EntryPoint = "GetCurrentThreadId")>]
        extern uint32 getCurrentThreadId()

        let private sampleWindowsThreadById nativeThreadId =
            use currentProcess = System.Diagnostics.Process.GetCurrentProcess()
            match
                currentProcess.Threads
                |> Seq.cast<System.Diagnostics.ProcessThread>
                |> Seq.tryFind (fun thread -> thread.Id = nativeThreadId)
            with
            | Some thread ->
                let cpuMs = max 0L (int64 thread.TotalProcessorTime.TotalMilliseconds)
                JpCpuTimeExclusive(
                    JpCpuWorkerRef.create ("windows-native-thread:" + string nativeThreadId),
                    nativeThreadId,
                    CompilerKernelV2.Measured.create<CompilerKernelV2.CpuTimeUnit>
                        "threadCpuMs"
                        cpuMs)
            | None ->
                JpCpuTimeUnavailable(JpCpuThreadUnavailable nativeThreadId)

        let sampleCurrentWindowsThread () =
            int (getCurrentThreadId())
            |> sampleWindowsThreadById

        let sampleSameWindowsThread = function
            | JpCpuTimeExclusive(_, nativeThreadId, _) ->
                sampleWindowsThreadById nativeThreadId
            | JpCpuTimeUnavailable reason ->
                JpCpuTimeUnavailable reason

    type JpCpuWallNormalizationId =
        | JpCpuWallNotMeasured
        | JpCpuWallWithinInclusive
        | JpCpuWallClampedToInclusive of observedCpuMs:int64 * wallInclusiveMs:int64 * toleranceMs:int64
        | JpCpuWallRejectedBeyondTolerance of observedCpuMs:int64 * wallInclusiveMs:int64 * toleranceMs:int64

    let jpCpuWallNormalizationText = function
        | JpCpuWallNotMeasured -> "NotMeasured"
        | JpCpuWallWithinInclusive -> "WithinInclusiveWall"
        | JpCpuWallClampedToInclusive(observedCpuMs, wallInclusiveMs, toleranceMs) ->
            FastRuntimeFormat.format "ClampedToInclusiveWall(observed_cpu_ms=%d|wall_inclusive_ms=%d|tolerance_ms=%d)" [| box observedCpuMs; box wallInclusiveMs; box toleranceMs |]
        | JpCpuWallRejectedBeyondTolerance(observedCpuMs, wallInclusiveMs, toleranceMs) ->
            FastRuntimeFormat.format "RejectedBeyondTolerance(observed_cpu_ms=%d|wall_inclusive_ms=%d|tolerance_ms=%d)" [| box observedCpuMs; box wallInclusiveMs; box toleranceMs |]

    let jpCpuWallQuantizationToleranceMs = 32L

    type JpWorkTimingPartition = private {
        wallExclusive : CompilerKernelV2.WallTime
        receipt : CompilerKernelV2.WorkTimingReceipt
        childWaitCount : int
        cpuNormalization : JpCpuWallNormalizationId
    }

    type private JpCpuClockStateId =
        | JpCpuClockUninstalled
        | JpCpuClockInstalled of JpCpuClock

    let private jpCpuClockGate = obj()
    let mutable private jpCpuClockState = JpCpuClockUninstalled

    let installJpCpuClock clockRef sampleCurrent sampleSameWorker =
        let clock =
            { clockRef = CompilerIdentityKernel.ContentDigest.ofText "jp-cpu-clock" clockRef
              sampleCurrent = sampleCurrent
              sampleSameWorker = sampleSameWorker }
        lock jpCpuClockGate (fun () -> jpCpuClockState <- JpCpuClockInstalled clock)

    let private installDefaultJpCpuClock () =
        if System.Runtime.InteropServices.RuntimeInformation.IsOSPlatform(
                System.Runtime.InteropServices.OSPlatform.Windows) then
            installJpCpuClock
                "windows-process-thread-total-processor-time"
                JpNativeThreadCpuClock.sampleCurrentWindowsThread
                JpNativeThreadCpuClock.sampleSameWindowsThread
            true
        else false

    do installDefaultJpCpuClock () |> ignore

    let private jpCpuClockFault ex =
        JpCpuTimeUnavailable(
            JpCpuClockFault(
                CompilerKernelV2.OperationalReasonIdOps.create (ex.GetType().Name)))

    let private jpCpuTimeSampleNow () =
        lock jpCpuClockGate (fun () ->
            match jpCpuClockState with
            | JpCpuClockInstalled clock ->
                try clock.sampleCurrent()
                with ex -> jpCpuClockFault ex
            | JpCpuClockUninstalled ->
                JpCpuTimeUnavailable JpCpuClockAdapterNotInstalled)

    let private jpCpuTimeSampleFor started =
        lock jpCpuClockGate (fun () ->
            match jpCpuClockState with
            | JpCpuClockInstalled clock ->
                try clock.sampleSameWorker started
                with ex -> jpCpuClockFault ex
            | JpCpuClockUninstalled ->
                JpCpuTimeUnavailable JpCpuClockAdapterNotInstalled)

    let private jpCpuTimeSampleAffinity = function
        | JpCpuTimeExclusive(workerRef, nativeThreadId, _) ->
            Some(JpCpuWorkerRef.text workerRef, nativeThreadId)
        | JpCpuTimeUnavailable _ -> None

    let private jpCpuTimeDelta started current =
        match started, current with
        | JpCpuTimeExclusive(startWorker, startNativeThreadId, startCpu),
          JpCpuTimeExclusive(currentWorker, currentNativeThreadId, currentCpu)
            when startWorker = currentWorker
                 && startNativeThreadId = currentNativeThreadId
                 && CompilerKernelV2.Measured.value currentCpu >= CompilerKernelV2.Measured.value startCpu ->
            let delta =
                CompilerKernelV2.Measured.create<CompilerKernelV2.CpuTimeUnit>
                    "cpuExclusive"
                    (CompilerKernelV2.Measured.value currentCpu - CompilerKernelV2.Measured.value startCpu)
            Some delta,
            CompilerKernelV2.CpuTimeExclusiveWorker (JpCpuWorkerRef.digest currentWorker)
        | JpCpuTimeExclusive(startWorker, _, _), JpCpuTimeExclusive(currentWorker, _, _) ->
            None,
            JpCpuWorkerMigration(startWorker, currentWorker)
            |> jpCpuTimeUnavailableReasonText
            |> CompilerKernelV2.OperationalReasonIdOps.create
            |> CompilerKernelV2.CpuTimeUnavailable
        | JpCpuTimeUnavailable reason, _
        | _, JpCpuTimeUnavailable reason ->
            None,
            reason
            |> jpCpuTimeUnavailableReasonText
            |> CompilerKernelV2.OperationalReasonIdOps.create
            |> CompilerKernelV2.CpuTimeUnavailable

    [<Struct>]
    type JpMethodIdentity = private | JpMethodIdentity of CompilerKernelV2.StableBindingId

    let jpMethodIdentityOfBinding (identity:CompilerKernelV2.StableBindingId) =
        JpMethodIdentity identity

    let jpMethodIdentityBinding (JpMethodIdentity value) = value
    let jpMethodIdentityText identity = identity |> jpMethodIdentityBinding |> CompilerKernelV2.StableBindingId.text

    [<Struct>]
    type JpClosureIdentity = private | JpClosureIdentity of CompilerKernelV2.StableBindingId

    let jpClosureIdentityBinding (JpClosureIdentity value) = value
    let jpClosureIdentityText identity = identity |> jpClosureIdentityBinding |> CompilerKernelV2.StableBindingId.text

    type JpComputationIdentity =
        | JpMethodComputation of methodIdentity:JpMethodIdentity * source:CompilerIdentityKernel.WorkSiteId
        | JpClosureComputation of closureIdentity:JpClosureIdentity * source:CompilerIdentityKernel.WorkSiteId
        | JpAnonymousComputation of bindingIdentity:CompilerKernelV2.StableBindingId * source:CompilerIdentityKernel.WorkSiteId

    let jpComputationIdentityText = function
        | JpMethodComputation(methodIdentity, _) -> jpMethodIdentityText methodIdentity
        | JpClosureComputation(closureIdentity, _) -> jpClosureIdentityText closureIdentity
        | JpAnonymousComputation(bindingIdentity, _) -> CompilerKernelV2.StableBindingId.text bindingIdentity

    let jpComputationIdentitySourceId = function
        | JpMethodComputation(_, source)
        | JpClosureComputation(_, source)
        | JpAnonymousComputation(_, source) -> source

    let jpComputationIdentitySource computation =
        computation
        |> jpComputationIdentitySourceId
        |> CompilerIdentityKernel.WorkSiteIdOps.text

    let jpComputationIdentityKindText = function
        | JpMethodComputation _ -> "Method"
        | JpClosureComputation _ -> "Closure"
        | JpAnonymousComputation _ -> "Anonymous"

    // Program symbols are opaque compiler identities. Runtime effects may only
    // enter this model from structural language/compiler evidence; symbol names
    // never classify behavior.
    type JpRuntimeEffectKind =
        | JpStructurallyDeclaredRuntimeEffect of CompilerIdentityKernel.ContentDigest

    type JpRuntimeEffectScope =
        | JpRuntimeEffectProcessStable
        | JpRuntimeEffectGenerationStable
        | JpRuntimeEffectInvocationVolatile

    type JpRuntimeSymbolNameKind private () =
        static member InternedKindTag () = 0x170003u
    type JpRuntimeSymbolNameId = CompilerIdentityKernel.InternedTextId<JpRuntimeSymbolNameKind>

    module JpRuntimeSymbolNameIdOps =
        let create value : JpRuntimeSymbolNameId =
            CompilerIdentityKernel.InternedTextId.create<JpRuntimeSymbolNameKind> value

        let text (value:JpRuntimeSymbolNameId) =
            CompilerIdentityKernel.InternedTextIdOps.text value

    type JpRuntimeEffectSymbolId =
        | JpRuntimeSymbol of JpRuntimeSymbolNameId

    let jpRuntimeEffectSymbolText = function
        | JpRuntimeSymbol symbolId -> JpRuntimeSymbolNameIdOps.text symbolId

    type JpRuntimeEffectOrigin =
        | JpStructuralRuntimeEffectOrigin of CompilerIdentityKernel.ContentDigest

    type JpRuntimeEffectWitness = private {
        effectKind : JpRuntimeEffectKind
        effectScope : JpRuntimeEffectScope
        effectOrigin : JpRuntimeEffectOrigin
        computationIdentity : JpComputationIdentity
        instantiationId : CompilerKernelV2.InstantiationId
        generation : int64
        witnessRef : CompilerIdentityKernel.ContentDigest
    }

    type JpRuntimeEffectRequirement =
        | JpRuntimeEffectPure
        | JpRuntimeEffectRequired of JpRuntimeEffectWitness

    type JpRuntimeEffectIngress =
        | JpRuntimeEffectIngressPure of symbol:JpRuntimeEffectSymbolId
        | JpRuntimeEffectIngressEffectful of symbol:JpRuntimeEffectSymbolId * effectKind:JpRuntimeEffectKind * effectScope:JpRuntimeEffectScope * effectOrigin:JpRuntimeEffectOrigin

    type JpRuntimeEffectSignature = private {
        ingress : JpRuntimeEffectIngress
        signatureRef : CompilerIdentityKernel.ContentDigest
    }

    type JpRuntimeEffectSignatureBindDecision =
        | JpRuntimeEffectSignatureBound of JpRuntimeEffectSignature
        | JpRuntimeEffectSignatureReused of JpRuntimeEffectSignature
        | JpRuntimeEffectSignatureConflict of existing:JpRuntimeEffectSignature * incoming:JpRuntimeEffectSignature * conflictRef:CompilerIdentityKernel.ContentDigest

    type JpRuntimeEffectClaim =
        | JpRuntimeEffectNotApplicable
        | JpRuntimeEffectClaimed of JpRuntimeEffectWitness
        | JpRuntimeEffectReused of JpRuntimeEffectWitness * receiptRef:CompilerIdentityKernel.ContentDigest
        | JpRuntimeEffectDeclaredInterfaceAccepted of JpRuntimeEffectWitness * contractRef:CompilerIdentityKernel.ContentDigest
        | JpRuntimeEffectVolatile of JpRuntimeEffectWitness

    type JpDeclaredInterfaceBodyRequirementId =
        | JpRuntimeEffectContractBodyRequired
        | JpRuntimeEffectWitnessBodyRequired
        | JpDeclaredInterfaceBodyVerificationRequired

    let jpDeclaredInterfaceBodyRequirementText = function
        | JpRuntimeEffectContractBodyRequired -> "RuntimeEffectContractAcceptedButCodegenBodyRequired"
        | JpRuntimeEffectWitnessBodyRequired -> "RuntimeEffectWitnessReusedButCodegenBodyRequired"
        | JpDeclaredInterfaceBodyVerificationRequired -> "DeclaredInterfaceBodyVerificationRequired"

    type JpSpecializationIntent =
        | JpComputeUnannotatedMethod
        | JpVerifyDeclaredMethodBody
        | JpMaterializeClosureBody
        | JpConsumeRuntimeEffectWitness
        | JpConsumePromiseTerminalState
        | JpDrainObserverVerification
        | JpAnonymousSpecializationIntent

    type JpSpecializationStage =
        | JpSpecializationQueued
        | JpSpecializationAcquireInputs
        | JpSpecializationNormalize
        | JpSpecializationReadback
        | JpSpecializationVerify
        | JpSpecializationPublishPromise
        | JpSpecializationTerminal

    type JpSpecializationInput =
        | JpComputationInput of computation:JpComputationIdentity * instantiationId:CompilerKernelV2.InstantiationId
        | JpRuntimeEffectInput of witness:JpRuntimeEffectWitness
        | JpPromiseCellInput of promiseRef:CompilerIdentityKernel.ContentDigest * cellRef:CompilerIdentityKernel.ContentDigest
        | JpPromiseTerminalInput of promiseRef:CompilerIdentityKernel.ContentDigest * terminalRef:CompilerIdentityKernel.ContentDigest
        | JpObserverRegistrationInput of observerRef:CompilerIdentityKernel.ContentDigest * verificationRef:CompilerIdentityKernel.ContentDigest
        | JpObserverTerminalInput of observerRef:CompilerIdentityKernel.ContentDigest * terminalRef:CompilerIdentityKernel.ContentDigest

    type JpSpecializationAdmissionDisposition =
        | JpSpecializationAdmitOwnedCell
        | JpSpecializationAwaitSharedCell
        | JpSpecializationReuseRuntimeEffect of receiptRef:CompilerIdentityKernel.ContentDigest
        | JpSpecializationRecomputeSuspect of activeSuspects:int * keyMarked:bool
        | JpSpecializationCapExceeded of classId:JpLoopSpecializationClass * count:int64 * cap:int
        | JpSpecializationRejectWitnessConflict of conflictRef:CompilerIdentityKernel.ContentDigest

    type JpSpecializationWorkNode = private {
        nodeRef : CompilerIdentityKernel.ContentDigest
        generation : int64
        intent : JpSpecializationIntent
        stage : JpSpecializationStage
        inputs : JpSpecializationInput list
        runtimeEffect : JpRuntimeEffectRequirement
        admission : JpSpecializationAdmissionDisposition
    }

    type JpSpecializationWorkReceipt = private {
        nodeRef : CompilerIdentityKernel.ContentDigest
        generation : int64
        terminalStage : JpSpecializationStage
        inputRef : CompilerIdentityKernel.ContentDigest
        normalizedRef : CompilerIdentityKernel.ContentDigest option
        readbackRef : CompilerIdentityKernel.ContentDigest option
        promiseReceiptRef : CompilerIdentityKernel.ContentDigest option
        receiptRef : CompilerIdentityKernel.ContentDigest
    }

    type JpSpecializationWorkSuspensionReason =
        | JpSpecializationCooperativeYieldSuspension of continuationRef:CompilerIdentityKernel.ContentDigest
        | JpSpecializationTypedCarrierBlockedSuspension of continuationRef:CompilerIdentityKernel.ContentDigest
        | JpSpecializationPatternMissSuspension of dependencyRef:CompilerIdentityKernel.ContentDigest

    type JpSpecializationWorkState =
        | JpSpecializationWorkRegistered of JpSpecializationWorkNode
        | JpSpecializationWorkRunning of JpSpecializationWorkNode
        | JpSpecializationWorkSuspended of JpSpecializationWorkNode * reason:JpSpecializationWorkSuspensionReason
        | JpSpecializationWorkCompleted of JpSpecializationWorkReceipt
        | JpSpecializationWorkFailed of JpSpecializationWorkNode * failureRef:CompilerIdentityKernel.ContentDigest
        | JpSpecializationWorkCancelled of JpSpecializationWorkNode * cancellationRef:CompilerIdentityKernel.ContentDigest

    type JpSpecializationWorkStartDecision =
        | JpSpecializationWorkStartAcquired of JpSpecializationWorkNode
        | JpSpecializationWorkStartAlreadyRunning of JpSpecializationWorkNode
        | JpSpecializationWorkStartTerminal of CompilerKernelV2.WorkTerminalDisposition

    type JpSpecializationWorklistClosureDisposition =
        | JpSpecializationWorklistOpen of openNodeRefs:CompilerIdentityKernel.ContentDigest list
        | JpSpecializationWorklistClosed of terminalReceiptRefs:CompilerIdentityKernel.ContentDigest list

    type JpSpecializationWorklistClosureSnapshot = private {
        generation : int64
        registeredCount : int
        runningCount : int
        suspendedCount : int
        runnableSuspendedCount : int
        typedCarrierBlockedSuspendedCount : int
        completedCount : int
        failedCount : int
        cancelledCount : int
        disposition : JpSpecializationWorklistClosureDisposition
        closureRef : CompilerIdentityKernel.ContentDigest
    }

    let jpRuntimeEffectKindText = function
        | JpStructurallyDeclaredRuntimeEffect effectRef ->
            "Structural(" + CompilerIdentityKernel.ContentDigest.text effectRef + ")"

    let jpRuntimeEffectScopeText = function
        | JpRuntimeEffectProcessStable -> "ProcessStable"
        | JpRuntimeEffectGenerationStable -> "GenerationStable"
        | JpRuntimeEffectInvocationVolatile -> "InvocationVolatile"

    let jpRuntimeEffectOriginText = function
        | JpStructuralRuntimeEffectOrigin originRef ->
            "Structural(" + CompilerIdentityKernel.ContentDigest.text originRef + ")"

    let jpSpecializationIntentText = function
        | JpComputeUnannotatedMethod -> "ComputeUnannotatedMethod"
        | JpVerifyDeclaredMethodBody -> "VerifyDeclaredMethodBody"
        | JpMaterializeClosureBody -> "MaterializeClosureBody"
        | JpConsumeRuntimeEffectWitness -> "ConsumeRuntimeEffectWitness"
        | JpConsumePromiseTerminalState -> "ConsumePromiseTerminalState"
        | JpDrainObserverVerification -> "DrainObserverVerification"
        | JpAnonymousSpecializationIntent -> "AnonymousSpecialization"

    let jpSpecializationStageText = function
        | JpSpecializationQueued -> "Queued"
        | JpSpecializationAcquireInputs -> "AcquireInputs"
        | JpSpecializationNormalize -> "Normalize"
        | JpSpecializationReadback -> "Readback"
        | JpSpecializationVerify -> "Verify"
        | JpSpecializationPublishPromise -> "PublishPromise"
        | JpSpecializationTerminal -> "Terminal"

    let jpSpecializationInputText = function
        | JpComputationInput(computation, instantiationId) ->
            "Computation(kind=" + jpComputationIdentityKindText computation
            + "|key=" + jpComputationIdentityText computation
            + "|source=" + jpComputationIdentitySource computation
            + "|instantiation=" + CompilerKernelV2.InstantiationIdOps.text instantiationId + ")"
        | JpRuntimeEffectInput witness ->
            "RuntimeEffect(kind=" + jpRuntimeEffectKindText witness.effectKind
            + "|scope=" + jpRuntimeEffectScopeText witness.effectScope
            + "|origin=" + jpRuntimeEffectOriginText witness.effectOrigin
            + "|ref=" + CompilerIdentityKernel.ContentDigest.text witness.witnessRef + ")"
        | JpPromiseCellInput(promiseRef, cellRef) ->
            "PromiseCell(promise=" + CompilerIdentityKernel.ContentDigest.text promiseRef
            + "|cell=" + CompilerIdentityKernel.ContentDigest.text cellRef + ")"
        | JpPromiseTerminalInput(promiseRef, terminalRef) ->
            "PromiseTerminal(promise=" + CompilerIdentityKernel.ContentDigest.text promiseRef
            + "|terminal=" + CompilerIdentityKernel.ContentDigest.text terminalRef + ")"
        | JpObserverRegistrationInput(observerRef, verificationRef) ->
            "ObserverRegistration(observer=" + CompilerIdentityKernel.ContentDigest.text observerRef
            + "|verification=" + CompilerIdentityKernel.ContentDigest.text verificationRef + ")"
        | JpObserverTerminalInput(observerRef, terminalRef) ->
            "ObserverTerminal(observer=" + CompilerIdentityKernel.ContentDigest.text observerRef
            + "|terminal=" + CompilerIdentityKernel.ContentDigest.text terminalRef + ")"

    let private jpSpecializationInputDigest = function
        | JpComputationInput(computation, instantiationId) ->
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-specialization-input-computation"
                (jpComputationIdentityKindText computation
                 + "|" + jpComputationIdentityText computation
                 + "|" + jpComputationIdentitySource computation
                 + "|" + CompilerIdentityKernel.ContentDigest.text (CompilerKernelV2.InstantiationIdOps.digest instantiationId))
        | JpRuntimeEffectInput witness ->
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-specialization-input-runtime-effect"
                (jpRuntimeEffectKindText witness.effectKind
                 + "|" + jpRuntimeEffectScopeText witness.effectScope
                 + "|" + jpRuntimeEffectOriginText witness.effectOrigin
                 + "|" + CompilerIdentityKernel.ContentDigest.text witness.witnessRef)
        | JpPromiseCellInput(promiseRef, cellRef) ->
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-specialization-input-promise-cell"
                (CompilerIdentityKernel.ContentDigest.text promiseRef
                 + "|" + CompilerIdentityKernel.ContentDigest.text cellRef)
        | JpPromiseTerminalInput(promiseRef, terminalRef) ->
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-specialization-input-promise-terminal"
                (CompilerIdentityKernel.ContentDigest.text promiseRef
                 + "|" + CompilerIdentityKernel.ContentDigest.text terminalRef)
        | JpObserverRegistrationInput(observerRef, verificationRef) ->
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-specialization-input-observer-registration"
                (CompilerIdentityKernel.ContentDigest.text observerRef
                 + "|" + CompilerIdentityKernel.ContentDigest.text verificationRef)
        | JpObserverTerminalInput(observerRef, terminalRef) ->
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-specialization-input-observer-terminal"
                (CompilerIdentityKernel.ContentDigest.text observerRef
                 + "|" + CompilerIdentityKernel.ContentDigest.text terminalRef)

    let jpSpecializationInputRef inputs =
        inputs
        |> List.map jpSpecializationInputDigest
        |> List.map CompilerIdentityKernel.ContentDigest.text
        |> String.concat "|"
        |> CompilerIdentityKernel.ContentDigest.ofText "jp-specialization-input-sequence"

    // Source-level method symbols are opaque identity/diagnostic data.  They are
    // never converted into runtime-effect evidence or memo-policy authority.

    module JpRuntimeEffectSignatureAuthority =
        let private signatures =
            System.Collections.Concurrent.ConcurrentDictionary<JpMethodIdentity,JpRuntimeEffectSignature>()

        let bind (methodIdentity:JpMethodIdentity) (incoming:JpRuntimeEffectSignature) =
            let accepted = signatures.GetOrAdd(methodIdentity, incoming)
            if accepted.signatureRef = incoming.signatureRef then
                if obj.ReferenceEquals(box accepted, box incoming) then JpRuntimeEffectSignatureBound accepted
                else JpRuntimeEffectSignatureReused accepted
            else
                let conflictRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-runtime-effect-signature-conflict"
                        (jpMethodIdentityText methodIdentity
                         + "|existing=" + CompilerIdentityKernel.ContentDigest.text accepted.signatureRef
                         + "|incoming=" + CompilerIdentityKernel.ContentDigest.text incoming.signatureRef)
                JpRuntimeEffectSignatureConflict(accepted, incoming, conflictRef)

    let private jpRuntimeEffectWitnessSubject computationIdentity instantiationId sourceId _origin =
        let source = CompilerIdentityKernel.WorkSiteIdOps.text sourceId
        let instantiation = CompilerKernelV2.InstantiationIdOps.text instantiationId
        "computation=" + jpComputationIdentityText computationIdentity
        + "|instantiation=" + instantiation
        + "|source=" + source

    let jpRuntimeEffectRequirementFor generation computationIdentity instantiationId signature =
        match signature.ingress with
        | JpRuntimeEffectIngressPure _ -> JpRuntimeEffectPure
        | JpRuntimeEffectIngressEffectful(_, effectKind, effectScope, effectOrigin) ->
            let scopeGeneration =
                match effectScope with
                | JpRuntimeEffectProcessStable -> 0L
                | JpRuntimeEffectGenerationStable
                | JpRuntimeEffectInvocationVolatile -> generation
            let sourceId = jpComputationIdentitySourceId computationIdentity
            let witnessSubject =
                jpRuntimeEffectWitnessSubject computationIdentity instantiationId sourceId effectOrigin
            let witnessRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-runtime-effect-witness"
                    (jpRuntimeEffectKindText effectKind
                     + "|scope=" + jpRuntimeEffectScopeText effectScope
                     + "|origin=" + jpRuntimeEffectOriginText effectOrigin
                     + "|signature=" + CompilerIdentityKernel.ContentDigest.text signature.signatureRef
                     + "|" + witnessSubject
                     + "|generation=" + string scopeGeneration)
            JpRuntimeEffectRequired {
                effectKind = effectKind
                effectScope = effectScope
                effectOrigin = effectOrigin
                computationIdentity = computationIdentity
                instantiationId = instantiationId
                generation = scopeGeneration
                witnessRef = witnessRef
            }

    let jpRuntimeEffectRequirementFromSignature generation computationIdentity instantiationId signature =
        jpRuntimeEffectRequirementFor generation computationIdentity instantiationId signature

    type JpRuntimeEffectCompletedEntry = private {
        witness : JpRuntimeEffectWitness
        payloadRef : CompilerIdentityKernel.ContentDigest
        receiptRef : CompilerIdentityKernel.ContentDigest
    }

    module JpRuntimeEffectWitnessAuthority =
        let private completed =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,JpRuntimeEffectCompletedEntry>()

        let claim observation =
            match observation with
            | JpRuntimeEffectPure -> JpRuntimeEffectNotApplicable
            | JpRuntimeEffectRequired witness ->
                // Structural effect evidence may choose a lifetime scope, but no
                // program symbol or library operation receives privileged policy.
                match witness.effectScope with
                | JpRuntimeEffectInvocationVolatile -> JpRuntimeEffectVolatile witness
                | JpRuntimeEffectProcessStable
                | JpRuntimeEffectGenerationStable ->
                    let mutable entry = Unchecked.defaultof<JpRuntimeEffectCompletedEntry>
                    if completed.TryGetValue(witness.witnessRef, &entry) then
                        JpRuntimeEffectReused(witness, entry.receiptRef)
                    else JpRuntimeEffectClaimed witness

        let complete witness payloadRef =
            let receiptRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-runtime-effect-completed"
                    (CompilerIdentityKernel.ContentDigest.text witness.witnessRef
                     + "|payload=" + CompilerIdentityKernel.ContentDigest.text payloadRef)
            let candidate = {
                witness = witness
                payloadRef = payloadRef
                receiptRef = receiptRef
            }
            let accepted = completed.AddOrUpdate(witness.witnessRef, candidate, fun _ previous -> previous)
            accepted.receiptRef

        let retireGeneration generation =
            completed.ToArray()
            |> Array.fold (fun retired entry ->
                let candidate = entry.Value
                match candidate.witness.effectScope with
                | JpRuntimeEffectProcessStable
                | JpRuntimeEffectInvocationVolatile -> retired
                | JpRuntimeEffectGenerationStable when candidate.witness.generation <= generation ->
                    let mutable removed = Unchecked.defaultof<JpRuntimeEffectCompletedEntry>
                    if completed.TryRemove(entry.Key, &removed) then retired + 1 else retired
                | JpRuntimeEffectGenerationStable -> retired) 0

        let snapshot () = completed.ToArray() |> Array.map (fun entry -> entry.Value)

    module JpSpecializationWorklistAuthority =
        let private states = System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,JpSpecializationWorkState>()

        let private nodeFromState (fallback:JpSpecializationWorkNode) (state:JpSpecializationWorkState) : JpSpecializationWorkNode =
            match state with
            | JpSpecializationWorkRegistered node
            | JpSpecializationWorkRunning node
            | JpSpecializationWorkSuspended(node, _)
            | JpSpecializationWorkFailed(node, _)
            | JpSpecializationWorkCancelled(node, _) -> node
            | JpSpecializationWorkCompleted _ -> fallback

        let private latestNode (fallback:JpSpecializationWorkNode) : JpSpecializationWorkNode =
            let mutable current = Unchecked.defaultof<JpSpecializationWorkState>
            if states.TryGetValue(fallback.nodeRef, &current) then nodeFromState fallback current
            else fallback

        let register (node:JpSpecializationWorkNode) : JpSpecializationWorkNode =
            states.TryAdd(node.nodeRef, JpSpecializationWorkRegistered node) |> ignore
            node

        let rec start (node:JpSpecializationWorkNode) : JpSpecializationWorkStartDecision =
            let mutable current = Unchecked.defaultof<JpSpecializationWorkState>
            if not (states.TryGetValue(node.nodeRef, &current)) then
                invalidOp ("specialization start requires registration: " + CompilerIdentityKernel.ContentDigest.text node.nodeRef)
            match current with
            | JpSpecializationWorkRegistered existing
            | JpSpecializationWorkSuspended(existing, _) ->
                let runningNode = { existing with stage = JpSpecializationAcquireInputs }
                if states.TryUpdate(node.nodeRef, JpSpecializationWorkRunning runningNode, current) then
                    JpSpecializationWorkStartAcquired runningNode
                else
                    start node
            | JpSpecializationWorkRunning existing ->
                JpSpecializationWorkStartAlreadyRunning existing
            | JpSpecializationWorkCompleted receipt ->
                JpSpecializationWorkStartTerminal (CompilerKernelV2.WorkTerminalSucceeded receipt.receiptRef)
            | JpSpecializationWorkFailed(_, failureRef) ->
                JpSpecializationWorkStartTerminal (CompilerKernelV2.WorkTerminalFailed failureRef)
            | JpSpecializationWorkCancelled(_, cancellationRef) ->
                JpSpecializationWorkStartTerminal (CompilerKernelV2.WorkTerminalCancelled cancellationRef)

        let suspend (node:JpSpecializationWorkNode) (reason:JpSpecializationWorkSuspensionReason) =
            let suspendedNode = latestNode node
            states.AddOrUpdate(
                node.nodeRef,
                JpSpecializationWorkSuspended(suspendedNode, reason),
                fun _ current ->
                    match current with
                    | JpSpecializationWorkRegistered existing
                    | JpSpecializationWorkRunning existing
                    | JpSpecializationWorkSuspended(existing, _) -> JpSpecializationWorkSuspended(existing, reason)
                    | JpSpecializationWorkCompleted _
                    | JpSpecializationWorkFailed _
                    | JpSpecializationWorkCancelled _ -> current)
            |> ignore

        let tryTerminalDisposition (node:JpSpecializationWorkNode) : CompilerKernelV2.WorkTerminalDisposition option =
            let mutable current = Unchecked.defaultof<JpSpecializationWorkState>
            if states.TryGetValue(node.nodeRef, &current) then
                match current with
                | JpSpecializationWorkCompleted receipt ->
                    Some (CompilerKernelV2.WorkTerminalSucceeded receipt.receiptRef)
                | JpSpecializationWorkFailed(_, failureRef) ->
                    Some (CompilerKernelV2.WorkTerminalFailed failureRef)
                | JpSpecializationWorkCancelled(_, cancellationRef) ->
                    Some (CompilerKernelV2.WorkTerminalCancelled cancellationRef)
                | JpSpecializationWorkRegistered _
                | JpSpecializationWorkRunning _
                | JpSpecializationWorkSuspended _ -> None
            else None

        let observeInput (node:JpSpecializationWorkNode) (input:JpSpecializationInput) : JpSpecializationWorkNode =
            let currentNode = latestNode node
            let nextNode = { currentNode with inputs = currentNode.inputs @ [input] }
            states.AddOrUpdate(
                node.nodeRef,
                JpSpecializationWorkRegistered nextNode,
                fun _ current ->
                    match current with
                    | JpSpecializationWorkRegistered _ -> JpSpecializationWorkRegistered nextNode
                    | JpSpecializationWorkRunning _ -> JpSpecializationWorkRunning nextNode
                    | JpSpecializationWorkSuspended(_, reason) -> JpSpecializationWorkSuspended(nextNode, reason)
                    | JpSpecializationWorkCompleted _
                    | JpSpecializationWorkFailed _
                    | JpSpecializationWorkCancelled _ -> current)
            |> ignore
            nextNode

        let private promiseCellRef (node:JpSpecializationWorkNode) : CompilerIdentityKernel.ContentDigest option =
            node.inputs
            |> List.tryPick (function
                | JpPromiseCellInput(promiseRef, _) -> Some promiseRef
                | _ -> None)

        let private appendPromiseTerminal (node:JpSpecializationWorkNode) (terminalRef:CompilerIdentityKernel.ContentDigest) : JpSpecializationWorkNode =
            match promiseCellRef node with
            | None -> node
            | Some promiseRef ->
                { node with
                    stage = JpSpecializationPublishPromise
                    inputs = node.inputs @ [JpPromiseTerminalInput(promiseRef, terminalRef)] }

        let prepareCompletion (node:JpSpecializationWorkNode) (normalizedRef:CompilerIdentityKernel.ContentDigest option) (readbackRef:CompilerIdentityKernel.ContentDigest option) (promiseReceiptRef:CompilerIdentityKernel.ContentDigest option) : JpSpecializationWorkReceipt =
            let mutable registeredState = Unchecked.defaultof<JpSpecializationWorkState>
            if not (states.TryGetValue(node.nodeRef, &registeredState)) then
                // A cache invalidation retires every registration up to its generation (retireGeneration) while
                // work items of that generation may still be running; one finishing afterwards is a late, stale
                // completion, not a broken invariant (apps/spiral, 36 min in: FatalError "specialization
                // completion requires registration"; FRONTIER.md fix 47). Record it instead of aborting the build.
                states.TryAdd(node.nodeRef, JpSpecializationWorkRegistered node) |> ignore
                DiagJson.emit (
                    "{\"kind\":\"jp_specialization_late_completion_after_generation_retired\",\"node_ref\":"
                    + DiagJson.esc (CompilerIdentityKernel.ContentDigest.text node.nodeRef)
                    + ",\"generation\":" + string node.generation
                    + ",\"authority\":\"stale_generation_completion_recorded\",\"next\":\"complete_without_build_failure\"}")
            let currentNode = latestNode node
            let effectivePromiseReceiptRef =
                match promiseReceiptRef, promiseCellRef currentNode with
                | Some receiptRef, _ -> Some receiptRef
                | None, Some promiseRef ->
                    Some(
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-specialization-promise-terminal-from-readback"
                            (CompilerIdentityKernel.ContentDigest.text promiseRef
                             + "|readback=" + (readbackRef |> Option.map CompilerIdentityKernel.ContentDigest.text |> Option.defaultValue "")))
                | None, None -> None
            let terminalNode =
                match effectivePromiseReceiptRef with
                | Some terminalRef -> appendPromiseTerminal currentNode terminalRef
                | None -> { currentNode with stage = JpSpecializationTerminal }
            let inputRef = jpSpecializationInputRef terminalNode.inputs
            let receiptRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-specialization-work-receipt"
                    (CompilerIdentityKernel.ContentDigest.text terminalNode.nodeRef
                     + "|generation=" + string terminalNode.generation
                     + "|stage=terminal"
                     + "|inputs=" + CompilerIdentityKernel.ContentDigest.text inputRef
                     + "|normalized=" + (normalizedRef |> Option.map CompilerIdentityKernel.ContentDigest.text |> Option.defaultValue "")
                     + "|readback=" + (readbackRef |> Option.map CompilerIdentityKernel.ContentDigest.text |> Option.defaultValue "")
                     + "|promise=" + (effectivePromiseReceiptRef |> Option.map CompilerIdentityKernel.ContentDigest.text |> Option.defaultValue ""))
            { nodeRef = terminalNode.nodeRef
              generation = terminalNode.generation
              terminalStage = JpSpecializationTerminal
              inputRef = inputRef
              normalizedRef = normalizedRef
              readbackRef = readbackRef
              promiseReceiptRef = effectivePromiseReceiptRef
              receiptRef = receiptRef }

        let commitCompletion (node:JpSpecializationWorkNode) (receipt:JpSpecializationWorkReceipt) : JpSpecializationWorkReceipt =
            let accepted =
                states.AddOrUpdate(
                    node.nodeRef,
                    JpSpecializationWorkCompleted receipt,
                    fun _ current ->
                        match current with
                        | JpSpecializationWorkCompleted _
                        | JpSpecializationWorkFailed _
                        | JpSpecializationWorkCancelled _ -> current
                        | JpSpecializationWorkRegistered _
                        | JpSpecializationWorkRunning _
                        | JpSpecializationWorkSuspended _ -> JpSpecializationWorkCompleted receipt)
            match accepted with
            | JpSpecializationWorkCompleted acceptedReceipt -> acceptedReceipt
            | JpSpecializationWorkFailed(_, failureRef) ->
                invalidOp ("specialization completion followed failure: " + CompilerIdentityKernel.ContentDigest.text failureRef)
            | JpSpecializationWorkCancelled(_, cancellationRef) ->
                invalidOp ("specialization completion followed cancellation: " + CompilerIdentityKernel.ContentDigest.text cancellationRef)
            | JpSpecializationWorkRegistered _
            | JpSpecializationWorkRunning _
            | JpSpecializationWorkSuspended _ ->
                invalidOp "specialization completion did not reach a terminal state"


        let fail (node:JpSpecializationWorkNode) (failureRef:CompilerIdentityKernel.ContentDigest) =
            let mutable registeredState = Unchecked.defaultof<JpSpecializationWorkState>
            if states.TryGetValue(node.nodeRef, &registeredState) then
                let terminalNode = appendPromiseTerminal (latestNode node) failureRef
                states.AddOrUpdate(
                    terminalNode.nodeRef,
                    JpSpecializationWorkFailed(terminalNode, failureRef),
                    fun _ current ->
                        match current with
                        | JpSpecializationWorkCompleted _
                        | JpSpecializationWorkFailed _
                        | JpSpecializationWorkCancelled _ -> current
                        | JpSpecializationWorkRegistered _
                        | JpSpecializationWorkRunning _
                        | JpSpecializationWorkSuspended _ -> JpSpecializationWorkFailed(terminalNode, failureRef))
                |> ignore

        let cancel (node:JpSpecializationWorkNode) (cancellationRef:CompilerIdentityKernel.ContentDigest) =
            let mutable registeredState = Unchecked.defaultof<JpSpecializationWorkState>
            if states.TryGetValue(node.nodeRef, &registeredState) then
                let terminalNode = appendPromiseTerminal (latestNode node) cancellationRef
                states.AddOrUpdate(
                    terminalNode.nodeRef,
                    JpSpecializationWorkCancelled(terminalNode, cancellationRef),
                    fun _ current ->
                        match current with
                        | JpSpecializationWorkCompleted _
                        | JpSpecializationWorkFailed _
                        | JpSpecializationWorkCancelled _ -> current
                        | JpSpecializationWorkRegistered _
                        | JpSpecializationWorkRunning _
                        | JpSpecializationWorkSuspended _ -> JpSpecializationWorkCancelled(terminalNode, cancellationRef))
                |> ignore

        let retireGeneration generation =
            states.ToArray()
            |> Array.fold (fun retired entry ->
                let nodeGeneration =
                    match entry.Value with
                    | JpSpecializationWorkRegistered node
                    | JpSpecializationWorkRunning node
                    | JpSpecializationWorkSuspended(node, _)
                    | JpSpecializationWorkFailed(node, _)
                    | JpSpecializationWorkCancelled(node, _) -> node.generation
                    | JpSpecializationWorkCompleted receipt -> receipt.generation
                if nodeGeneration <= generation then
                    let mutable removed = Unchecked.defaultof<JpSpecializationWorkState>
                    if states.TryRemove(entry.Key, &removed) then retired + 1 else retired
                else retired) 0

        let closureSnapshot (generation:int64) : JpSpecializationWorklistClosureSnapshot =
            let snapshot = states.ToArray() |> Array.map (fun entry -> entry.Value)
            let mutable registeredCount = 0
            let mutable runningCount = 0
            let mutable suspendedCount = 0
            let mutable runnableSuspendedCount = 0
            let mutable typedCarrierBlockedSuspendedCount = 0
            let mutable completedCount = 0
            let mutable failedCount = 0
            let mutable cancelledCount = 0
            let mutable openRefs : CompilerIdentityKernel.ContentDigest list = []
            let mutable terminalRefs : CompilerIdentityKernel.ContentDigest list = []
            snapshot
            |> Array.iter (fun state ->
                match state with
                | JpSpecializationWorkRegistered node when node.generation = generation ->
                    registeredCount <- registeredCount + 1
                    openRefs <- node.nodeRef :: openRefs
                | JpSpecializationWorkRunning node when node.generation = generation ->
                    runningCount <- runningCount + 1
                    openRefs <- node.nodeRef :: openRefs
                | JpSpecializationWorkSuspended(node, reason) when node.generation = generation ->
                    suspendedCount <- suspendedCount + 1
                    (match reason with
                     | JpSpecializationCooperativeYieldSuspension _
                     | JpSpecializationPatternMissSuspension _ ->
                         runnableSuspendedCount <- runnableSuspendedCount + 1
                     | JpSpecializationTypedCarrierBlockedSuspension _ ->
                         typedCarrierBlockedSuspendedCount <- typedCarrierBlockedSuspendedCount + 1)
                    openRefs <- node.nodeRef :: openRefs
                | JpSpecializationWorkFailed(node, failureRef) when node.generation = generation ->
                    failedCount <- failedCount + 1
                    terminalRefs <- failureRef :: terminalRefs
                | JpSpecializationWorkCancelled(node, cancellationRef) when node.generation = generation ->
                    cancelledCount <- cancelledCount + 1
                    terminalRefs <- cancellationRef :: terminalRefs
                | JpSpecializationWorkCompleted receipt when receipt.generation = generation ->
                    completedCount <- completedCount + 1
                    terminalRefs <- receipt.receiptRef :: terminalRefs
                | JpSpecializationWorkRegistered _
                | JpSpecializationWorkRunning _
                | JpSpecializationWorkSuspended _
                | JpSpecializationWorkCompleted _
                | JpSpecializationWorkFailed _
                | JpSpecializationWorkCancelled _ -> ())
            let stableOpenRefs =
                openRefs |> List.sort |> List.map CompilerIdentityKernel.ContentDigest.text |> String.concat ";"
            let stableTerminalRefs =
                terminalRefs |> List.sort |> List.map CompilerIdentityKernel.ContentDigest.text |> String.concat ";"
            let disposition =
                if List.isEmpty openRefs then
                    JpSpecializationWorklistClosed (terminalRefs |> List.sort)
                else
                    JpSpecializationWorklistOpen (openRefs |> List.sort)
            { generation = generation
              registeredCount = registeredCount
              runningCount = runningCount
              suspendedCount = suspendedCount
              runnableSuspendedCount = runnableSuspendedCount
              typedCarrierBlockedSuspendedCount = typedCarrierBlockedSuspendedCount
              completedCount = completedCount
              failedCount = failedCount
              cancelledCount = cancelledCount
              disposition = disposition
              closureRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-specialization-worklist-closure-proof"
                    (FastRuntimeFormat.format "generation=%d|registered=%d|running=%d|suspended=%d|runnable_suspended=%d|typed_carrier_blocked_suspended=%d|completed=%d|failed=%d|cancelled=%d|open=%s|terminal=%s" [| box generation; box registeredCount; box runningCount; box suspendedCount; box runnableSuspendedCount; box typedCarrierBlockedSuspendedCount; box completedCount; box failedCount; box cancelledCount; box stableOpenRefs; box stableTerminalRefs |]) }

        let snapshot () = states.ToArray()

    let jpSpecializationWorkNodeCreate (generation:int64) (intent:JpSpecializationIntent) (computationIdentity:JpComputationIdentity) (instantiationId:CompilerKernelV2.InstantiationId) (runtimeEffect:JpRuntimeEffectRequirement) (admission:JpSpecializationAdmissionDisposition) : JpSpecializationWorkNode =
        let effectText =
            match runtimeEffect with
            | JpRuntimeEffectPure -> "pure"
            | JpRuntimeEffectRequired witness -> CompilerIdentityKernel.ContentDigest.text witness.witnessRef
        let nodeRef =
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-specialization-work-node"
                ("generation=" + string generation
                 + "|intent=" + jpSpecializationIntentText intent
                 + "|computation=" + jpComputationIdentityText computationIdentity
                 + "|instantiation=" + CompilerIdentityKernel.ContentDigest.text (CompilerKernelV2.InstantiationIdOps.digest instantiationId)
                 + "|effect=" + effectText)
        { nodeRef = nodeRef
          generation = generation
          intent = intent
          stage = JpSpecializationQueued
          inputs =
              [ JpComputationInput(computationIdentity, instantiationId) ]
              @ (match runtimeEffect with
                 | JpRuntimeEffectPure -> []
                 | JpRuntimeEffectRequired witness -> [JpRuntimeEffectInput witness])
          runtimeEffect = runtimeEffect
          admission = admission }

    [<Struct>]
    type JpMethodMemoCellIdentity = private | JpMethodMemoCellIdentity of methodIdentity:JpMethodIdentity * instantiationId:CompilerKernelV2.InstantiationId * generation:int64

    type JpMethodMemoWitness = private {
        environmentValues : RData []
        environmentTypes : Ty []
        annotation : Ty
    }

    type JpMethodMemoCompletedEntry = private {
        witness : JpMethodMemoWitness
        cell : CompilerKernelV2.ConfluentWorkCell<Ty>
    }

    type JpMethodMemoDeclaredBodyVerificationId =
        | JpMethodMemoDeclaredBodyEquivalent
        | JpMethodMemoDeclaredBodyMismatch

    type JpDeclaredInterfaceMismatchEvidence =
        | JpMismatchBodyMatchesCapturedTermOnly
        | JpMismatchDeclaredMatchesCapturedTermOnly
        | JpMismatchBothMatchCapturedTerms
        | JpMismatchNoCapturedTermMatch
        | JpMismatchNoCapturedTerms

    let jpDeclaredInterfaceMismatchEvidenceText = function
        | JpMismatchBodyMatchesCapturedTermOnly -> "BodyMatchesCapturedTermOnly"
        | JpMismatchDeclaredMatchesCapturedTermOnly -> "DeclaredMatchesCapturedTermOnly"
        | JpMismatchBothMatchCapturedTerms -> "BothMatchCapturedTerms"
        | JpMismatchNoCapturedTermMatch -> "NoCapturedTermMatch"
        | JpMismatchNoCapturedTerms -> "NoCapturedTerms"

    type JpMethodMemoTypeEvidenceId =
        | JpMethodMemoInferredBodyType of inferredType:Ty
        | JpMethodMemoDeclaredInterfaceType of declaredType:Ty * verificationRef:CompilerIdentityKernel.ContentDigest
        | JpMethodMemoVerifiedDeclaredInterfaceType of declaredType:Ty * inferredBodyType:Ty * verification:JpMethodMemoDeclaredBodyVerificationId * verificationRef:CompilerIdentityKernel.ContentDigest

    type JpMethodMemoConflictObservationId =
        | JpMethodMemoConflictObservedOnRead
        | JpMethodMemoConflictObservedOnPublish

    type JpMethodSharedCompletedMemoPolicy =
        | JpMethodSharedCompletedMemoConfluent
        | JpMethodSharedCompletedMemoOwnerLocalRuntimeEffect of JpRuntimeEffectKind

    // Shared method memo semantics are generic.  A user program symbol cannot
    // downgrade confluence; conflicting results remain compiler evidence.
    let jpMethodSharedCompletedMemoPolicyFor _ =
        JpMethodSharedCompletedMemoConfluent

    let jpMethodSharedCompletedMemoPolicyText = function
        | JpMethodSharedCompletedMemoConfluent -> "SharedConfluent"
        | JpMethodSharedCompletedMemoOwnerLocalRuntimeEffect effectKind ->
            "OwnerLocalRuntimeEffect(" + jpRuntimeEffectKindText effectKind + ")"

    let jpMethodMemoTypeEvidenceCanonicalType = function
        | JpMethodMemoInferredBodyType inferredType -> inferredType
        | JpMethodMemoDeclaredInterfaceType (declaredType, _) -> declaredType
        | JpMethodMemoVerifiedDeclaredInterfaceType (declaredType, _, JpMethodMemoDeclaredBodyEquivalent, _) -> declaredType
        | JpMethodMemoVerifiedDeclaredInterfaceType (_, inferredBodyType, JpMethodMemoDeclaredBodyMismatch, _) -> inferredBodyType

    let jpMethodMemoTypeEvidenceAuthorityText = function
        | JpMethodMemoInferredBodyType _ -> "InferredBodyTypeAuthority"
        | JpMethodMemoDeclaredInterfaceType _ -> "DeclaredInterfaceTypeAuthority"
        | JpMethodMemoVerifiedDeclaredInterfaceType (_, _, JpMethodMemoDeclaredBodyEquivalent, _) -> "VerifiedDeclaredInterfaceEquivalent"
        | JpMethodMemoVerifiedDeclaredInterfaceType (_, _, JpMethodMemoDeclaredBodyMismatch, _) -> "VerifiedDeclaredInterfaceMismatch"

    let jpMethodMemoDeclaredBodyVerificationText = function
        | JpMethodMemoDeclaredBodyEquivalent -> "Equivalent"
        | JpMethodMemoDeclaredBodyMismatch -> "Mismatch"

    let jpMethodMemoConflictObservationText = function
        | JpMethodMemoConflictObservedOnRead -> "Read"
        | JpMethodMemoConflictObservedOnPublish -> "Publish"

    let jpMethodMemoConflictNextText = function
        | JpMethodMemoConflictObservedOnRead -> "bypass_shared_cell_and_preserve_owner_local_computation"
        | JpMethodMemoConflictObservedOnPublish -> "mark_shared_cell_conflict_and_preserve_typed_failure_evidence"

    [<Struct>]
    type JpMethodMemoOwnerIdentity =
        | JpMethodMemoWorkOwner of workId:int64
        | JpMethodMemoHostThreadOwner of managedThreadId:int

    type JpMethodMemoPendingEntry = private {
        witness : JpMethodMemoWitness
        cell : CompilerKernelV2.PortableOneShotCell<JpMethodBodyCellPayload>
        ownerIdentity : JpMethodMemoOwnerIdentity
    }

    type JpMethodPendingMemoObservation =
        | JpMethodPendingMemoAbsent
        | JpMethodPendingMemoWait of CompilerKernelV2.PortableOneShotCell<JpMethodBodyCellPayload>
        | JpMethodPendingMemoReentrant
        | JpMethodPendingMemoWitnessConflict

    let jpMethodMemoWitnessEquivalent left right =
        LanguagePrimitives.GenericEquality left.environmentValues right.environmentValues
        && LanguagePrimitives.GenericEquality left.environmentTypes right.environmentTypes
        && LanguagePrimitives.GenericEquality left.annotation right.annotation

    let jpMethodMemoResultText ty =
        let typeText = show_ty ty
        let resultRef =
            CompilerIdentityKernel.ContentDigest.ofText "jp-method-memo-result" typeText
            |> CompilerIdentityKernel.ContentDigest.text
        sprintf "structural_ref=%s|type=%s" resultRef typeText

    let jpRDataIdentityText = function
        | ReB -> "B"
        | ReSymbol value -> "Symbol(" + value + ")"
        | ReLit value -> "Literal(" + show_lit value + ")"
        | ReTLit value -> "TypeLiteral(" + show_lit value + ")"
        | RePair node -> sprintf "Pair(tag=%d|hkey=%d)" node.tag node.hkey
        | ReFunction node -> sprintf "Function(tag=%d|hkey=%d)" node.tag node.hkey
        | ReForall node -> sprintf "Forall(tag=%d|hkey=%d)" node.tag node.hkey
        | ReExists node -> sprintf "Exists(tag=%d|hkey=%d)" node.tag node.hkey
        | ReRecord node -> sprintf "Record(tag=%d|hkey=%d)" node.tag node.hkey
        | ReUnion node -> sprintf "Union(tag=%d|hkey=%d)" node.tag node.hkey
        | ReNominal node -> sprintf "Nominal(tag=%d|hkey=%d)" node.tag node.hkey
        | ReV node -> sprintf "Variable(tag=%d|hkey=%d)" node.tag node.hkey
        | ReHashMap node -> sprintf "HashMap(tag=%d|hkey=%d)" node.tag node.hkey

    let jpRDataArrayIdentityRef values =
        values
        |> Array.map jpRDataIdentityText
        |> String.concat ";"
        |> CompilerIdentityKernel.ContentDigest.ofText "jp-rdata-array-identity"

    let jpTyArrayIdentityRef values =
        values
        |> Array.map show_ty
        |> String.concat ";"
        |> CompilerIdentityKernel.ContentDigest.ofText "jp-type-array-identity"

    type JpMethodMemoProbe =
        | JpMethodMemoCellCreated
        | JpMethodMemoSharedReadyHit
        | JpMethodMemoSharedWaitHit
        | JpMethodMemoReadyHit
        | JpMethodMemoWaitHit
        | JpMethodMemoDeclaredInterfaceHit
        | JpMethodMemoSharedReentrantBypass
        | JpMethodMemoSharedConflictBypass
        | JpMethodMemoSuspectBypass
        | JpMethodMemoNotApplicable

    [<Struct>]
    type JpClosureMemoCellIdentity = private | JpClosureMemoCellIdentity of backendId:CompilerKernelV2.BackendId * backendNode:string ConsedNode * body:E * environment:ConsedNode<RData [] * Ty [] * Ty> * generation:int64

    type JpClosureMemoWitness = private {
        backendId : CompilerKernelV2.BackendId
        backendNode : string ConsedNode
        body : E
        environment : ConsedNode<RData [] * Ty [] * Ty>
        annotatedFunctionType : Ty
    }

    [<Struct>]
    type JpClosureMemoOwnerIdentity =
        | JpClosureMemoWorkOwner of workId:int64
        | JpClosureMemoHostThreadOwner of managedThreadId:int

    let jpClosureMemoOwnerIdentityText = function
        | JpClosureMemoWorkOwner workId -> "WorkOwner(" + string workId + ")"
        | JpClosureMemoHostThreadOwner managedThreadId -> "HostThreadOwner(" + string managedThreadId + ")"

    type JpClosureMemoCompletedEntry = private {
        witness : JpClosureMemoWitness
        cell : CompilerKernelV2.ConfluentWorkCell<JpClosureBodyCellPayload>
    }

    type JpClosureMemoPendingEntry = private {
        witness : JpClosureMemoWitness
        cell : CompilerKernelV2.PortableOneShotCell<JpClosureBodyCellPayload>
        ownerIdentity : JpClosureMemoOwnerIdentity
        ownerCapabilityRef : CompilerIdentityKernel.ContentDigest
    }

    type JpClosurePendingMemoObservation =
        | JpClosurePendingMemoAbsent
        | JpClosurePendingMemoWait of CompilerKernelV2.PortableOneShotCell<JpClosureBodyCellPayload> * ownerCapabilityRef:CompilerIdentityKernel.ContentDigest
        | JpClosurePendingMemoReentrant of ownerCapabilityRef:CompilerIdentityKernel.ContentDigest
        | JpClosurePendingMemoWitnessConflict of existingOwnerCapabilityRef:CompilerIdentityKernel.ContentDigest

    let jpClosureMemoWitnessEquivalent left right =
        left.backendId = right.backendId
        && LanguagePrimitives.GenericEquality left.backendNode right.backendNode
        && LanguagePrimitives.GenericEquality left.body right.body
        && LanguagePrimitives.GenericEquality left.environment right.environment
        && LanguagePrimitives.GenericEquality left.annotatedFunctionType right.annotatedFunctionType

    type JpClosureMemoProbe =
        | JpClosureMemoCellCreated
        | JpClosureMemoSharedReadyHit
        | JpClosureMemoSharedWaitHit
        | JpClosureMemoWaitHit
        | JpClosureMemoReentrantBypass
        | JpClosureMemoWitnessConflictBypass
        | JpClosureMemoMissingCell

    let jpClosureMemoProbeText = function
        | JpClosureMemoCellCreated -> "CellCreated"
        | JpClosureMemoSharedReadyHit -> "SharedReadyHit"
        | JpClosureMemoSharedWaitHit -> "SharedWaitHit"
        | JpClosureMemoWaitHit -> "WaitHit"
        | JpClosureMemoReentrantBypass -> "ReentrantBypass"
        | JpClosureMemoWitnessConflictBypass -> "WitnessConflictBypass"
        | JpClosureMemoMissingCell -> "MissingCell"

    type JpComputationMemoProbe =
        | JpMethodMemoObservation of JpMethodMemoProbe
        | JpClosureMemoObservation of JpClosureMemoProbe
        | JpComputationMemoNotApplicable

    let jpComputationMemoProbeText = function
        | JpMethodMemoObservation probe ->
            match probe with
            | JpMethodMemoCellCreated -> "CellCreated"
            | JpMethodMemoSharedReadyHit -> "SharedReadyHit"
            | JpMethodMemoSharedWaitHit -> "SharedWaitHit"
            | JpMethodMemoReadyHit -> "ReadyHit"
            | JpMethodMemoWaitHit -> "WaitHit"
            | JpMethodMemoDeclaredInterfaceHit -> "DeclaredInterfaceHit"
            | JpMethodMemoSharedReentrantBypass -> "SharedReentrantBypass"
            | JpMethodMemoSharedConflictBypass -> "SharedConflictBypass"
            | JpMethodMemoSuspectBypass -> "SuspectBypass"
            | JpMethodMemoNotApplicable -> "NotApplicable"
        | JpClosureMemoObservation probe -> jpClosureMemoProbeText probe
        | JpComputationMemoNotApplicable -> "NotApplicable"

    let jpComputationMemoProbeIsHit = function
        | JpMethodMemoObservation(JpMethodMemoSharedReadyHit
                                | JpMethodMemoSharedWaitHit
                                | JpMethodMemoReadyHit
                                | JpMethodMemoWaitHit
                                | JpMethodMemoDeclaredInterfaceHit)
        | JpClosureMemoObservation(JpClosureMemoSharedReadyHit
                                 | JpClosureMemoSharedWaitHit
                                 | JpClosureMemoWaitHit) -> true
        | JpMethodMemoObservation _
        | JpClosureMemoObservation _
        | JpComputationMemoNotApplicable -> false

    type JpWorkAuthorityRole =
        | JpSemanticProducer
        | JpCodegenBodyProducer of verificationRef:CompilerIdentityKernel.ContentDigest
        | JpObserverVerification of verificationRef:CompilerIdentityKernel.ContentDigest

    let jpWorkAuthorityRoleText = function
        | JpSemanticProducer -> "SemanticProducer"
        | JpCodegenBodyProducer verificationRef ->
            "CodegenBodyProducer(ref=" + CompilerIdentityKernel.ContentDigest.text verificationRef + ")"
        | JpObserverVerification verificationRef ->
            "ObserverVerification(ref=" + CompilerIdentityKernel.ContentDigest.text verificationRef + ")"

    let jpWorkAuthorityRoleOwnsSemanticLedger = function
        | JpSemanticProducer -> true
        | JpCodegenBodyProducer _
        | JpObserverVerification _ -> false

    let jpWorkAuthorityRoleIsObserverVerification = function
        | JpObserverVerification _ -> true
        | JpSemanticProducer
        | JpCodegenBodyProducer _ -> false

    let jpWorkAuthorityRoleParticipatesInRequiredWorkRecovery = function
        | JpSemanticProducer
        | JpCodegenBodyProducer _ -> true
        | JpObserverVerification _ -> false

    type JpSchedulingLane =
        | JpSemanticProducerLane
        | JpDeclaredBodyVerificationLane
        | JpObserverVerificationLane

    let jpSchedulingLaneFor authorityRole intent =
        match authorityRole, intent with
        | JpSemanticProducer, JpVerifyDeclaredMethodBody -> JpDeclaredBodyVerificationLane
        | JpSemanticProducer, _ -> JpSemanticProducerLane
        | JpCodegenBodyProducer _, _ -> JpDeclaredBodyVerificationLane
        | JpObserverVerification _, _ -> JpObserverVerificationLane

    let jpSchedulingLaneText = function
        | JpSemanticProducerLane -> "SemanticProducer"
        | JpDeclaredBodyVerificationLane -> "DeclaredBodyVerification"
        | JpObserverVerificationLane -> "ObserverVerification"

    type JpDeclaredBodyLanePolicyId =
        | JpDeclaredBodyForegroundPressureSingleFlight
        | JpDeclaredBodyBootstrapSingleFlight
        | JpDeclaredBodyBootstrapBoundedRamp of queueDepth:int * verifierLimit:int
        | JpDeclaredBodyRetirementRamp of retiredCount:int64 * longRetiredCount:int64 * verifierLimit:int

    let jpDeclaredBodyLanePolicyText = function
        | JpDeclaredBodyForegroundPressureSingleFlight -> "ForegroundPressureSingleFlight"
        | JpDeclaredBodyBootstrapSingleFlight -> "BootstrapSingleFlight"
        | JpDeclaredBodyBootstrapBoundedRamp(queueDepth, verifierLimit) ->
            FastRuntimeFormat.format "BootstrapBoundedRamp(queue=%d|limit=%d)" [| box queueDepth; box verifierLimit |]
        | JpDeclaredBodyRetirementRamp(retiredCount, longRetiredCount, verifierLimit) ->
            FastRuntimeFormat.format "RetirementRamp(retired=%d|long_retired=%d|limit=%d)" [| box retiredCount; box longRetiredCount; box verifierLimit |]

    type JpWorkerLaneAdmission =
        | JpWorkerSemanticLaneGranted
        | JpWorkerDeclaredBodyLaneGranted
        | JpWorkerObserverLaneGranted

    type JpObserverLifecycle =
        | JpObserverRegistered
        | JpObserverRunning
        | JpObserverCompleted of receiptRef:CompilerIdentityKernel.ContentDigest
        | JpObserverCancellationRequested of cancellationRef:CompilerIdentityKernel.ContentDigest
        | JpObserverCancelled of receiptRef:CompilerIdentityKernel.ContentDigest

    type JpObserverDrainPolicy =
        | JpObserverDrainBeforeTerminalFinalRow
        | JpObserverDrainBeforeGenerationRetirement
        | JpObserverDrainBeforeHostReturn

    let jpObserverDrainPolicyText = function
        | JpObserverDrainBeforeTerminalFinalRow -> "BeforeTerminalFinalRow"
        | JpObserverDrainBeforeGenerationRetirement -> "BeforeGenerationRetirement"
        | JpObserverDrainBeforeHostReturn -> "BeforeHostReturn"

    type JpObserverDrainReasonId =
        | JpObserverDrainTerminalRequest of CompilerConsoleHud88.TerminalObserverDrainRequestReason
        | JpObserverDrainCacheInvalidation
        | JpObserverDrainIndexedTerminalClosure of physicalExitIntentRef:uint32

    let jpObserverDrainReasonText = function
        | JpObserverDrainTerminalRequest reason ->
            CompilerConsoleHud88.terminalObserverDrainRequestReasonText reason
        | JpObserverDrainCacheInvalidation -> "cache_invalidation"
        | JpObserverDrainIndexedTerminalClosure physicalExitIntentRef ->
            "indexed-terminal-closure:" + string physicalExitIntentRef

    let jpObserverDrainOperationalReason reason =
        reason
        |> jpObserverDrainReasonText
        |> CompilerKernelV2.OperationalReasonIdOps.create

    type JpObserverRegistration = private {
        observerRef : CompilerIdentityKernel.ContentDigest
        verificationRef : CompilerIdentityKernel.ContentDigest
        generation : int64
        computationIdentity : JpComputationIdentity
        cancel : JpWorkCancellationRequest -> CompilerKernelV2.PortableEffect<unit>
        mutable lifecycle : JpObserverLifecycle
    }

    let jpSpecializationWorkNodeBindObserver (registration:JpObserverRegistration) (node:JpSpecializationWorkNode) : JpSpecializationWorkNode =
        { node with
            inputs =
                node.inputs
                @ [ JpObserverRegistrationInput(
                        registration.observerRef,
                        registration.verificationRef) ] }

    let jpSpecializationWorkNodeConsumeObserverTerminal (registration:JpObserverRegistration) (terminalRef:CompilerIdentityKernel.ContentDigest) (node:JpSpecializationWorkNode) : JpSpecializationWorkNode =
        { node with
            stage = JpSpecializationTerminal
            inputs = node.inputs @ [ JpObserverTerminalInput(registration.observerRef, terminalRef) ] }

    type JpObserverDrainDisposition =
        | JpObserverDrainOpen of undecidedObserverRefs:CompilerIdentityKernel.ContentDigest list
        | JpObserverDrainClosed of terminalObserverRefs:CompilerIdentityKernel.ContentDigest list

    type JpObserverDrainReceipt = private {
        policy : JpObserverDrainPolicy
        observed : int
        cancellationRequested : int
        terminal : int
        disposition : JpObserverDrainDisposition
        drainRef : CompilerIdentityKernel.ContentDigest
    }

    type JpWorkLedgerApplication =
        | SemanticWorkLedgerApplied of Result<unit,CompilerKernelV2.SemanticWorkLedgerConflict>
        | JpObserverLedgerBypassed

    let jpWorkLedgerApplicationText = function
        | SemanticWorkLedgerApplied(Ok ()) -> "Ok"
        | SemanticWorkLedgerApplied(Error _) -> "Conflict"
        | JpObserverLedgerBypassed -> "ObserverVerificationBypass"

    let jpWorkLedgerApplicationAdmitted = function
        | SemanticWorkLedgerApplied result -> Result.isOk result
        | JpObserverLedgerBypassed -> false

    type JpMethodDeclaredInterface = private {
        methodIdentity : JpMethodIdentity
        instantiationId : CompilerKernelV2.InstantiationId
        declaredType : Ty
        verificationRef : CompilerIdentityKernel.ContentDigest
    }

    type JpMethodDeclaredInterfaceClaim =
        | JpMethodDeclaredInterfaceAbsent
        | JpMethodDeclaredInterfaceClaimed of JpMethodDeclaredInterface
        | JpMethodDeclaredInterfaceExisting of JpMethodDeclaredInterface

    type JpYieldTimingLifecycleId =
        | JpYieldTimingDeclaredBodySuspended
        | JpYieldTimingGeneralWorkRemoved

    let jpYieldTimingLifecycleText = function
        | JpYieldTimingDeclaredBodySuspended -> "DeclaredBodySuspendedCumulative"
        | JpYieldTimingGeneralWorkRemoved -> "GeneralWorkRemovedLegacyParity"

    type JpWorkExecutionBudgetPolicyId =
        | JpStableRuntimeEffectDeclaredBodyBudget of effectKind:JpRuntimeEffectKind
        | JpMeasuredGeneralWorkBudget of sampleCount:int64 * observedP99Ms:int64

    let jpWorkExecutionBudgetPolicyText = function
        | JpStableRuntimeEffectDeclaredBodyBudget effectKind ->
            "StableRuntimeEffectDeclaredBodyBudget(effect=" + jpRuntimeEffectKindText effectKind + ")"
        | JpMeasuredGeneralWorkBudget(sampleCount, observedP99Ms) ->
            sprintf "MeasuredGeneralWorkBudget(samples=%d|p99_ms=%d)" sampleCount observedP99Ms

    type JpWorkExecutionBudgetDecisionId =
        | JpWorkExecutionWithinBudget
        | JpWorkExecutionDiagnosticBudgetExceeded
        | JpWorkExecutionHardBudgetExceeded

    let jpWorkExecutionBudgetDecision diagnosticBudgetMs hardBudgetMs ageMs =
        if ageMs >= hardBudgetMs then JpWorkExecutionHardBudgetExceeded
        elif ageMs >= diagnosticBudgetMs then JpWorkExecutionDiagnosticBudgetExceeded
        else JpWorkExecutionWithinBudget

    type JpWorkHardDeadlineProgressEvidence =
        | JpWorkHardDeadlineDeclaredCheckpointProgress of checkpointOperationCount:int64 * checkpointAgeMs:int64
        | JpWorkHardDeadlineOperationProgress of observedSteps:int64 * idleMs:int64
        | JpWorkHardDeadlinePublicationProgress of stage:CompilerKernelV2.OperationalReasonId * idleMs:int64
        | JpWorkHardDeadlineNoProgress

    type JpWorkHardDeadlineProgressLeaseId =
        | JpWorkHardDeadlineProgressLeaseRenewed of evidence:JpWorkHardDeadlineProgressEvidence
        | JpWorkHardDeadlineProgressLeaseExpired

    let jpWorkHardDeadlineProgressLeaseText = function
        | JpWorkHardDeadlineProgressLeaseRenewed(JpWorkHardDeadlineDeclaredCheckpointProgress(checkpointOperationCount, checkpointAgeMs)) ->
            sprintf "RenewedByDeclaredCheckpoint(operations=%d|age_ms=%d)" checkpointOperationCount checkpointAgeMs
        | JpWorkHardDeadlineProgressLeaseRenewed(JpWorkHardDeadlineOperationProgress(observedSteps, idleMs)) ->
            sprintf "RenewedByOperationProgress(steps=%d|idle_ms=%d)" observedSteps idleMs
        | JpWorkHardDeadlineProgressLeaseRenewed(JpWorkHardDeadlinePublicationProgress(stage, idleMs)) ->
            sprintf "RenewedByPublicationProgress(stage=%s|idle_ms=%d)" (CompilerKernelV2.OperationalReasonIdOps.text stage) idleMs
        | JpWorkHardDeadlineProgressLeaseRenewed JpWorkHardDeadlineNoProgress
        | JpWorkHardDeadlineProgressLeaseExpired -> "Expired"

    type JpDeclaredCheckpointCancellationHandoffProofId =
        | JpDeclaredCheckpointStationaryCancellationProof of repetitions:int * sampleCount:int * stateRef:CompilerIdentityKernel.ContentDigest
        | JpDeclaredCheckpointAlternatingPairCancellationProof of repetitions:int * sampleCount:int * pairRef:CompilerIdentityKernel.ContentDigest
        | JpDeclaredCheckpointRepeatingSuffixCancellationProof of period:int * repetitions:int * sampleCount:int * cycleRef:CompilerIdentityKernel.ContentDigest

    let jpDeclaredCheckpointCancellationHandoffProofText = function
        | JpDeclaredCheckpointStationaryCancellationProof(repetitions, sampleCount, stateRef) ->
            FastRuntimeFormat.format
                "Stationary(repetitions=%d|samples=%d|state_ref=%s)"
                [| box repetitions; box sampleCount; box (CompilerIdentityKernel.ContentDigest.text stateRef) |]
        | JpDeclaredCheckpointAlternatingPairCancellationProof(repetitions, sampleCount, pairRef) ->
            FastRuntimeFormat.format
                "AlternatingPair(repetitions=%d|samples=%d|pair_ref=%s)"
                [| box repetitions; box sampleCount; box (CompilerIdentityKernel.ContentDigest.text pairRef) |]
        | JpDeclaredCheckpointRepeatingSuffixCancellationProof(period, repetitions, sampleCount, cycleRef) ->
            FastRuntimeFormat.format
                "RepeatingSuffix(period=%d|repetitions=%d|samples=%d|cycle_ref=%s)"
                [| box period; box repetitions; box sampleCount; box (CompilerIdentityKernel.ContentDigest.text cycleRef) |]

    [<NoEquality; NoComparison>]
    type JpDeclaredCheckpointCancellationSafePointHandoffId = private {
        proof : JpDeclaredCheckpointCancellationHandoffProofId
        observedSteps : int64
        publishedAtMs : int64
    }

    type JpWorkHardDeadlineDispositionId =
        | JpWorkHardDeadlineWithinBoundary
        | JpWorkHardDeadlineDeferredByDeclaredCheckpointProgress of checkpointOperationCount:int64 * checkpointAgeMs:int64
        | JpWorkHardDeadlineDeferredByOperationProgress of observedSteps:int64 * idleMs:int64
        | JpWorkHardDeadlineDeferredByPublicationProgress of stage:CompilerKernelV2.OperationalReasonId * idleMs:int64
        | JpWorkHardDeadlineExpiredAfterOperationStall of observedSteps:int64 * idleMs:int64
        | JpWorkHardDeadlineExpiredAfterCpuBudget of cpuMs:int64 * cpuBudgetMs:int64 * observedSteps:int64
        | JpWorkHardDeadlineExpiredAfterProgressLeaseStall of ageMs:int64 * diagnosticThresholdMs:int64 * observedSteps:int64 * publicationStageTransitions:int64
        | JpWorkHardDeadlineExpiredAfterRepeatingOperationCycle of period:int * repetitions:int * observedSteps:int64 * operationIdleMs:int64
        | JpWorkHardDeadlineDeferredToPatternMissDeclaredCheckpointCycleCancellation of proof:JpDeclaredCheckpointCancellationHandoffProofId * observedSteps:int64
        | JpWorkHardDeadlineExpiredAfterCpuAndOperationStall of cpuMs:int64 * cpuIdleMs:int64 * observedSteps:int64 * operationIdleMs:int64
        | JpWorkHardDeadlineExpiredAfterPublicationStall of stage:CompilerKernelV2.OperationalReasonId * idleMs:int64

    let jpWorkHardDeadlineDispositionText = function
        | JpWorkHardDeadlineWithinBoundary -> "within_boundary"
        | JpWorkHardDeadlineDeferredByDeclaredCheckpointProgress(checkpointOperationCount, checkpointAgeMs) ->
            sprintf "deferred_by_declared_checkpoint_progress(checkpoint_operations=%d|checkpoint_age_ms=%d)" checkpointOperationCount checkpointAgeMs
        | JpWorkHardDeadlineDeferredByOperationProgress(observedSteps, idleMs) ->
            sprintf "deferred_by_operation_progress(steps=%d|idle_ms=%d)" observedSteps idleMs
        | JpWorkHardDeadlineDeferredByPublicationProgress(stage, idleMs) ->
            sprintf "deferred_by_publication_progress(stage=%s|idle_ms=%d)"
                (CompilerKernelV2.OperationalReasonIdOps.text stage)
                idleMs
        | JpWorkHardDeadlineExpiredAfterOperationStall(observedSteps, idleMs) ->
            sprintf "expired_after_operation_stall(steps=%d|idle_ms=%d)" observedSteps idleMs
        | JpWorkHardDeadlineExpiredAfterCpuBudget(cpuMs, cpuBudgetMs, observedSteps) ->
            FastRuntimeFormat.format "expired_after_cpu_budget(cpu_ms=%d|cpu_budget_ms=%d|steps=%d)" [| box cpuMs; box cpuBudgetMs; box observedSteps |]
        | JpWorkHardDeadlineExpiredAfterProgressLeaseStall(ageMs, diagnosticThresholdMs, observedSteps, publicationStageTransitions) ->
            FastRuntimeFormat.format "expired_after_progress_lease_stall(age_ms=%d|diagnostic_threshold_ms=%d|steps=%d|publication_stage_transitions=%d)" [| box ageMs; box diagnosticThresholdMs; box observedSteps; box publicationStageTransitions |]
        | JpWorkHardDeadlineExpiredAfterRepeatingOperationCycle(period, repetitions, observedSteps, operationIdleMs) ->
            FastRuntimeFormat.format "expired_after_repeating_operation_cycle(period=%d|repetitions=%d|steps=%d|operation_idle_ms=%d)" [| box period; box repetitions; box observedSteps; box operationIdleMs |]
        | JpWorkHardDeadlineDeferredToPatternMissDeclaredCheckpointCycleCancellation(proof, observedSteps) ->
            FastRuntimeFormat.format
                "deferred_to_pattern_miss_declared_checkpoint_cycle_cancellation(proof=%s|steps=%d)"
                [| box (jpDeclaredCheckpointCancellationHandoffProofText proof); box observedSteps |]
        | JpWorkHardDeadlineExpiredAfterCpuAndOperationStall(cpuMs, cpuIdleMs, observedSteps, operationIdleMs) ->
            FastRuntimeFormat.format "expired_after_cpu_and_operation_stall(cpu_ms=%d|cpu_idle_ms=%d|steps=%d|operation_idle_ms=%d)" [| box cpuMs; box cpuIdleMs; box observedSteps; box operationIdleMs |]
        | JpWorkHardDeadlineExpiredAfterPublicationStall(stage, idleMs) ->
            sprintf "expired_after_publication_stall(stage=%s|idle_ms=%d)"
                (CompilerKernelV2.OperationalReasonIdOps.text stage)
                idleMs

