    type JpMethodBodyExecutionStage =
        | JpMethodBodyQueued
        | JpMethodBodyPreparingEnvironment
        | JpMethodBodyRenamingGlobals
        | JpMethodBodyEnteringRecursion
        | JpMethodBodyEvaluating
        | JpMethodBodyTypeResolved
        | JpMethodBodyResolvingRecursivePlaceholder
        | JpMethodBodyVerifyingAnnotation
        | JpMethodBodyPublishingPromise
        | JpMethodBodyPublished
        | JpMethodBodyDeferredControl
        | JpMethodBodyCancelledControl
        | JpMethodBodyFailed

    let jpMethodBodyExecutionStageText = function
        | JpMethodBodyQueued -> "Queued"
        | JpMethodBodyPreparingEnvironment -> "PreparingEnvironment"
        | JpMethodBodyRenamingGlobals -> "RenamingGlobals"
        | JpMethodBodyEnteringRecursion -> "EnteringRecursion"
        | JpMethodBodyEvaluating -> "Evaluating"
        | JpMethodBodyTypeResolved -> "TypeResolved"
        | JpMethodBodyResolvingRecursivePlaceholder -> "ResolvingRecursivePlaceholder"
        | JpMethodBodyVerifyingAnnotation -> "VerifyingAnnotation"
        | JpMethodBodyPublishingPromise -> "PublishingPromise"
        | JpMethodBodyPublished -> "Published"
        | JpMethodBodyDeferredControl -> "DeferredControl"
        | JpMethodBodyCancelledControl -> "CancelledControl"
        | JpMethodBodyFailed -> "Failed"

    type JpWorkExecutionDeadlineReasonId =
        | JpWorkExecutionHardDeadline of policy:JpWorkExecutionBudgetPolicyId * stage:JpMethodBodyExecutionStage
        | JpWorkExecutionHardDeadlineUntracked of policy:JpWorkExecutionBudgetPolicyId
        | JpWorkPublicationHardDeadline of policy:JpWorkExecutionBudgetPolicyId * publicationStage:CompilerKernelV2.OperationalReasonId

    let jpWorkExecutionDeadlineReasonText = function
        | JpWorkExecutionHardDeadline(policy, stage) ->
            "execution_deadline_expired|policy=" + jpWorkExecutionBudgetPolicyText policy
            + "|stage=" + jpMethodBodyExecutionStageText stage
        | JpWorkExecutionHardDeadlineUntracked policy ->
            "execution_deadline_expired|policy=" + jpWorkExecutionBudgetPolicyText policy
            + "|stage=Untracked"
        | JpWorkPublicationHardDeadline(policy, publicationStage) ->
            "publication_deadline_expired|policy=" + jpWorkExecutionBudgetPolicyText policy
            + "|stage=" + CompilerKernelV2.OperationalReasonIdOps.text publicationStage

    type JpMethodBodyStageKey = private {
        computationIdentity : JpComputationIdentity
        instantiationId : CompilerKernelV2.InstantiationId
    }

    type JpMethodBodyStageSnapshot = private {
        stage : JpMethodBodyExecutionStage
        changedAtMs : int64
        transitionCount : int64
    }

    module JpMethodBodyStageAuthority =
        let private stages =
            System.Collections.Concurrent.ConcurrentDictionary<JpMethodBodyStageKey,JpMethodBodyStageSnapshot>()

        let private key computationIdentity instantiationId =
            { computationIdentity = computationIdentity
              instantiationId = instantiationId }

        let advance computationIdentity instantiationId stage =
            let nowMs = max 0L System.Environment.TickCount64
            stages.AddOrUpdate(
                key computationIdentity instantiationId,
                { stage = stage; changedAtMs = nowMs; transitionCount = 1L },
                fun _ existing ->
                    if existing.stage = stage then existing
                    else
                        { stage = stage
                          changedAtMs = nowMs
                          transitionCount = existing.transitionCount + 1L })
            |> ignore

        let tryRead computationIdentity instantiationId =
            match stages.TryGetValue(key computationIdentity instantiationId) with
            | true, snapshot ->
                Some(
                    snapshot.stage,
                    max 0L (System.Environment.TickCount64 - snapshot.changedAtMs),
                    snapshot.transitionCount)
            | _ -> None

        let retire computationIdentity instantiationId =
            let mutable removed = Unchecked.defaultof<JpMethodBodyStageSnapshot>
            stages.TryRemove(key computationIdentity instantiationId, &removed) |> ignore

    type JpWorkPublicationStageId =
        | JpWorkPublicationExecuting
        | JpWorkPublicationTimingPartition
        | JpWorkPublicationOperationalRetirement
        | JpWorkPublicationGenerationRetirement
        | JpWorkPublicationCellMerge
        | JpWorkPublicationEffectWitness
        | JpWorkPublicationWorklistCommit
        | JpWorkPublicationCommitted

    let jpWorkPublicationStageText = function
        | JpWorkPublicationExecuting -> "Executing"
        | JpWorkPublicationTimingPartition -> "TimingPartition"
        | JpWorkPublicationOperationalRetirement -> "OperationalRetirement"
        | JpWorkPublicationGenerationRetirement -> "GenerationRetirement"
        | JpWorkPublicationCellMerge -> "CellMerge"
        | JpWorkPublicationEffectWitness -> "EffectWitness"
        | JpWorkPublicationWorklistCommit -> "WorklistCommit"
        | JpWorkPublicationCommitted -> "Committed"

