    [<Struct>]
    type JpOperationPhaseSampleId = private JpOperationPhaseSample of phase:JpActiveOperationPhaseId * nodeId:int

    let jpOperationPhaseSamplePhase (JpOperationPhaseSample(phase, _)) = phase

    let jpOperationPhaseSampleText (JpOperationPhaseSample(phase, nodeId)) =
        jpActiveOperationPhaseText phase + "@node=" + string nodeId

    type JpOperationPhaseRingLivenessId =
        | JpOperationPhaseRingInsufficientEvidence of sampleCount:int
        | JpOperationPhaseRingAdvancing of sampleCount:int
        | JpOperationPhaseRingRepeatingSuffix of period:int * repetitions:int * sampleCount:int

    let jpOperationPhaseRingLivenessText = function
        | JpOperationPhaseRingInsufficientEvidence sampleCount ->
            "InsufficientEvidence(samples=" + string sampleCount + ")"
        | JpOperationPhaseRingAdvancing sampleCount ->
            "Advancing(samples=" + string sampleCount + ")"
        | JpOperationPhaseRingRepeatingSuffix(period, repetitions, sampleCount) ->
            "RepeatingSuffix(period=" + string period + "|repetitions=" + string repetitions + "|samples=" + string sampleCount + ")"

    let jpOperationPhaseRingLivenessForSamples (samples:JpOperationPhaseSampleId array) =
        let sampleCount = samples.Length
        let requiredRepetitions = 4
        if sampleCount < 8 then
            JpOperationPhaseRingInsufficientEvidence sampleCount
        else
            let maxPeriod = min 8 (sampleCount / requiredRepetitions)
            let rec findPeriod period =
                if period > maxPeriod then
                    JpOperationPhaseRingAdvancing sampleCount
                else
                    let span = period * requiredRepetitions
                    let start = sampleCount - span
                    let mutable repeated = true
                    let mutable offset = period
                    while repeated && offset < span do
                        if samples.[start + offset] <> samples.[start + (offset % period)] then
                            repeated <- false
                        offset <- offset + 1
                    if repeated then
                        JpOperationPhaseRingRepeatingSuffix(period, requiredRepetitions, sampleCount)
                    else
                        findPeriod (period + 1)
            findPeriod 1

