    type JpDeclaredBodyResumeCapabilityId =
        | JpDeclaredResumeObserverOnly
        | JpDeclaredResumeApplySpineCandidateMissing
        | JpDeclaredResumeApplySpineStored
        | JpDeclaredResumeLetChainCandidateMissing
        | JpDeclaredResumeLetSpineStored

    let jpDeclaredBodyResumeCapabilityFor resumePoint nodeId =
        match resumePoint with
        | JpDeclaredResumeApplySpineFlatten
        | JpDeclaredResumeApplyHead
        | JpDeclaredResumeApplyArgument
        | JpDeclaredResumeApplyDispatch ->
            if EvalReplayValueStore.hasApplySpine nodeId then JpDeclaredResumeApplySpineStored
            else JpDeclaredResumeApplySpineCandidateMissing
        | JpDeclaredResumeLetBinding
        | JpDeclaredResumeLetBody ->
            match EvalReplayValueStore.tryLetSpine nodeId with
            | Some _ -> JpDeclaredResumeLetSpineStored
            | None -> JpDeclaredResumeLetChainCandidateMissing
        | _ -> JpDeclaredResumeObserverOnly

    let jpDeclaredBodyResumeCapabilityText = function
        | JpDeclaredResumeObserverOnly -> "ObserverOnly"
        | JpDeclaredResumeApplySpineCandidateMissing -> "ApplySpineCandidateMissing"
        | JpDeclaredResumeApplySpineStored -> "ApplySpineStored"
        | JpDeclaredResumeLetChainCandidateMissing -> "LetChainCandidateMissing"
        | JpDeclaredResumeLetSpineStored -> "LetSpineStored"

    type JpDeclaredBodyResumeEvidenceId =
        | JpDeclaredResumeEvidenceObserverOnly
        | JpDeclaredResumeEvidenceApplySpine of headNodeId:int * argCount:int
        | JpDeclaredResumeEvidenceLetSpine of bindingCount:int * successNodeId:int
        | JpDeclaredResumeEvidenceCandidateMissing of capability:JpDeclaredBodyResumeCapabilityId

    let jpDeclaredBodyResumeEvidenceFor resumePoint nodeId =
        match jpDeclaredBodyResumeCapabilityFor resumePoint nodeId with
        | JpDeclaredResumeApplySpineStored ->
            match EvalReplayValueStore.tryApplySpine nodeId with
            | Some spine -> JpDeclaredResumeEvidenceApplySpine(spine.headNodeId, spine.argCount)
            | None -> JpDeclaredResumeEvidenceCandidateMissing JpDeclaredResumeApplySpineCandidateMissing
        | JpDeclaredResumeLetSpineStored ->
            match EvalReplayValueStore.tryLetSpine nodeId with
            | Some spine -> JpDeclaredResumeEvidenceLetSpine(spine.bodyNodeIds.Length, spine.successNodeId)
            | None -> JpDeclaredResumeEvidenceCandidateMissing JpDeclaredResumeLetChainCandidateMissing
        | JpDeclaredResumeObserverOnly -> JpDeclaredResumeEvidenceObserverOnly
        | missing -> JpDeclaredResumeEvidenceCandidateMissing missing

    let jpDeclaredBodyResumeEvidenceCapability = function
        | JpDeclaredResumeEvidenceObserverOnly -> JpDeclaredResumeObserverOnly
        | JpDeclaredResumeEvidenceApplySpine _ -> JpDeclaredResumeApplySpineStored
        | JpDeclaredResumeEvidenceLetSpine _ -> JpDeclaredResumeLetSpineStored
        | JpDeclaredResumeEvidenceCandidateMissing capability -> capability

    let jpDeclaredBodyResumeEvidenceText = function
        | JpDeclaredResumeEvidenceObserverOnly -> "ObserverOnly"
        | JpDeclaredResumeEvidenceApplySpine(headNodeId, argCount) ->
            "ApplySpine(head_node=" + string headNodeId + "|arg_count=" + string argCount + ")"
        | JpDeclaredResumeEvidenceLetSpine(bindingCount, successNodeId) ->
