    [<Struct>]
    type JpDeclaredBodyCheckpointCycleSampleId = private | JpDeclaredBodyCheckpointCycleSample of phase:JpActiveOperationPhaseId * nodeId:int * resumePoint:JpDeclaredBodyResumePointId * resumeNodeId:int

    let jpDeclaredBodyCheckpointCycleSampleText (JpDeclaredBodyCheckpointCycleSample(phase, nodeId, resumePoint, resumeNodeId)) =
        jpActiveOperationPhaseText phase
        + "@node=" + string nodeId
        + "|resume=" + jpDeclaredBodyResumePointText resumePoint
        + "@node=" + string resumeNodeId

    type JpDeclaredBodyCheckpointCycleLivenessId =
        | JpDeclaredBodyCheckpointCycleInsufficientEvidence of sampleCount:int
        | JpDeclaredBodyCheckpointCycleAdvancing of sampleCount:int
        | JpDeclaredBodyCheckpointCycleStationary of repetitions:int * sampleCount:int * stateRef:CompilerIdentityKernel.ContentDigest
        | JpDeclaredBodyCheckpointCycleAlternatingPair of repetitions:int * sampleCount:int * pairRef:CompilerIdentityKernel.ContentDigest
        | JpDeclaredBodyCheckpointCycleRecurrentPrefix of period:int * matchedPrefix:int * sampleCount:int * candidateRef:CompilerIdentityKernel.ContentDigest
        | JpDeclaredBodyCheckpointCycleRepeatingSuffix of period:int * repetitions:int * sampleCount:int * cycleRef:CompilerIdentityKernel.ContentDigest

    let jpDeclaredBodyCheckpointCycleLivenessText = function
        | JpDeclaredBodyCheckpointCycleInsufficientEvidence sampleCount ->
            "InsufficientEvidence(samples=" + string sampleCount + ")"
        | JpDeclaredBodyCheckpointCycleAdvancing sampleCount ->
            "Advancing(samples=" + string sampleCount + ")"
        | JpDeclaredBodyCheckpointCycleStationary(repetitions, sampleCount, stateRef) ->
            "Stationary(repetitions=" + string repetitions
            + "|samples=" + string sampleCount
            + "|state_ref=" + CompilerIdentityKernel.ContentDigest.text stateRef + ")"
        | JpDeclaredBodyCheckpointCycleAlternatingPair(repetitions, sampleCount, pairRef) ->
            "AlternatingPair(repetitions=" + string repetitions
            + "|samples=" + string sampleCount
            + "|pair_ref=" + CompilerIdentityKernel.ContentDigest.text pairRef + ")"
        | JpDeclaredBodyCheckpointCycleRecurrentPrefix(period, matchedPrefix, sampleCount, candidateRef) ->
            "RecurrentPrefix(period=" + string period
            + "|matched_prefix=" + string matchedPrefix
            + "|samples=" + string sampleCount
            + "|candidate_ref=" + CompilerIdentityKernel.ContentDigest.text candidateRef + ")"
        | JpDeclaredBodyCheckpointCycleRepeatingSuffix(period, repetitions, sampleCount, cycleRef) ->
            "RepeatingSuffix(period=" + string period
            + "|repetitions=" + string repetitions
            + "|samples=" + string sampleCount
            + "|cycle_ref=" + CompilerIdentityKernel.ContentDigest.text cycleRef + ")"

    let jpDeclaredBodyCheckpointCycleLivenessForSamples (samples:JpDeclaredBodyCheckpointCycleSampleId array) =
        let sampleCount = samples.Length
        let repeatedSuffixMinimumPeriod = 2
        let recurrentPrefixMinimumPeriod = 3
        let maximumPeriod = 16
        let requiredRepetitions = 3
        let alternatingPairRequiredRepetitions = 6
        let requiredMatchedPrefix = 3
        let minimumDistinctCycleStates = 3
        let stationaryMinimumRepetitions = 4
        let stationarySuffix =
            if sampleCount < stationaryMinimumRepetitions then None
            else
                let last = samples.[sampleCount - 1]
                let mutable repetitions = 1
                while repetitions < sampleCount
                      && samples.[sampleCount - 1 - repetitions] = last do
                    repetitions <- repetitions + 1
                if repetitions >= stationaryMinimumRepetitions then
                    let stateRef =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-declared-body-checkpoint-stationary"
                            (jpDeclaredBodyCheckpointCycleSampleText last)
                    Some(JpDeclaredBodyCheckpointCycleStationary(repetitions, sampleCount, stateRef))
                else None
        match stationarySuffix with
        | Some liveness -> liveness
        | None when sampleCount < requiredRepetitions * recurrentPrefixMinimumPeriod ->
            JpDeclaredBodyCheckpointCycleInsufficientEvidence sampleCount
        | None ->
            let maxRepeatedPeriod = min maximumPeriod (sampleCount / requiredRepetitions)
            let rec findRepeatedSuffix period =
                if period > maxRepeatedPeriod then None
                else
                    let repetitions =
                        if period = repeatedSuffixMinimumPeriod then alternatingPairRequiredRepetitions
                        else requiredRepetitions
                    let span = period * repetitions
                    if span > sampleCount then
                        findRepeatedSuffix (period + 1)
                    else
                        let start = sampleCount - span
                        let mutable repeated = true
                        let mutable offset = period
                        while repeated && offset < span do
                            if samples.[start + offset] <> samples.[start + (offset % period)] then
                                repeated <- false
                            offset <- offset + 1
                        if repeated then
                            let distinctSamples = System.Collections.Generic.HashSet<JpDeclaredBodyCheckpointCycleSampleId>()
                            for i in 0 .. (period - 1) do
                                distinctSamples.Add(samples.[start + i]) |> ignore
                            let minimumDistinctSamples =
                                if period = repeatedSuffixMinimumPeriod then 2
                                else minimumDistinctCycleStates
                            if distinctSamples.Count >= minimumDistinctSamples then
                                let cycleText =
                                    [| for i in 0 .. (period - 1) -> jpDeclaredBodyCheckpointCycleSampleText samples.[start + i] |]
                                    |> String.concat ">"
                                let cycleRef =
                                    CompilerIdentityKernel.ContentDigest.ofText
                                        (if period = repeatedSuffixMinimumPeriod
                                         then "jp-declared-body-checkpoint-alternating-pair"
                                         else "jp-declared-body-checkpoint-cycle")
                                        cycleText
                                if period = repeatedSuffixMinimumPeriod then
                                    Some(JpDeclaredBodyCheckpointCycleAlternatingPair(repetitions, sampleCount, cycleRef))
                                else
                                    Some(JpDeclaredBodyCheckpointCycleRepeatingSuffix(period, repetitions, sampleCount, cycleRef))
                            else
                                findRepeatedSuffix (period + 1)
                        else
                            findRepeatedSuffix (period + 1)
            match findRepeatedSuffix repeatedSuffixMinimumPeriod with
            | Some liveness -> liveness
            | None ->
                // A long PatternMiss producer can be cancelled safely before a third complete
                // circuit only when the checkpoint ring already contains one full typed
                // period and the current suffix re-enters that period for several distinct
                // checkpoints. The PatternMiss stable-age gate below is the second half of
                // this authority: this liveness state alone never cancels work.
                let maxCandidatePeriod = min maximumPeriod (sampleCount - requiredMatchedPrefix)
                let rec findRecurrentPrefix period =
                    if period > maxCandidatePeriod then
                        JpDeclaredBodyCheckpointCycleAdvancing sampleCount
                    else
                        let suffixStart = sampleCount - requiredMatchedPrefix
                        let priorStart = suffixStart - period
                        let mutable matched = priorStart >= 0
                        let mutable offset = 0
                        while matched && offset < requiredMatchedPrefix do
                            if samples.[suffixStart + offset] <> samples.[priorStart + offset] then
                                matched <- false
                            offset <- offset + 1
                        if matched then
                            let distinctSamples = System.Collections.Generic.HashSet<JpDeclaredBodyCheckpointCycleSampleId>()
                            for i in 0 .. (period - 1) do
                                distinctSamples.Add(samples.[priorStart + i]) |> ignore
                            if distinctSamples.Count >= minimumDistinctCycleStates then
                                let cycleText =
                                    [| for i in 0 .. (period - 1) -> jpDeclaredBodyCheckpointCycleSampleText samples.[priorStart + i] |]
                                    |> String.concat ">"
                                let candidateRef =
                                    CompilerIdentityKernel.ContentDigest.ofText
                                        "jp-declared-body-checkpoint-cycle-candidate"
                                        (cycleText + "|matched_prefix=" + string requiredMatchedPrefix)
                                JpDeclaredBodyCheckpointCycleRecurrentPrefix(
                                    period,
                                    requiredMatchedPrefix,
                                    sampleCount,
                                    candidateRef)
                            else
                                findRecurrentPrefix (period + 1)
                        else
                            findRecurrentPrefix (period + 1)
                findRecurrentPrefix recurrentPrefixMinimumPeriod

