        | UnionUntagSingletonSymbol _ -> "SingletonSymbol"

    type UnionUntagTagValidityId =
        | UnionUntagTagInRange of tagIndex:int * tagCount:int
        | UnionUntagTagOutOfRange of tagIndex:int * tagCount:int

    type UnionUntagTagSourceId =
        | UnionUntagLiteralTag
        | UnionUntagCseLiteralTag

    let unionUntagTagSourceText = function
        | UnionUntagLiteralTag -> "Literal"
        | UnionUntagCseLiteralTag -> "CseLiteral"

    let unionUntagTagValidity tagCount tagIndex =
        if 0 <= tagIndex && tagIndex < tagCount then UnionUntagTagInRange(tagIndex, tagCount)
        else UnionUntagTagOutOfRange(tagIndex, tagCount)

    let unionUntagTagValidityText = function
        | UnionUntagTagInRange(tagIndex, tagCount) ->
            "InRange(tag=" + string tagIndex + "|count=" + string tagCount + ")"
        | UnionUntagTagOutOfRange(tagIndex, tagCount) ->
            "OutOfRange(tag=" + string tagIndex + "|count=" + string tagCount + ")"

    type JpPromiseResumptionCauseId =
        | JpPromiseResolvedResumption
        | JpPromiseFailedResumption
        | JpPromiseCancelledResumption

    let jpPromiseResumptionCauseText = function
        | JpPromiseResolvedResumption -> "Resolved"
        | JpPromiseFailedResumption -> "Failed"
        | JpPromiseCancelledResumption -> "Cancelled"

    // Destructive operational-domain cutover, pass 2/5.
    // A work item now carries a typed operational cursor rather than pretending
    // every replay is still in the queued phase.  Deferral becomes an actual
    // Running -> Suspended -> Running relationship and no lifecycle shadow is
    // required to remember which transition is legal next.
    type JpWorkOperationalCursor =
        | JpWorkQueuedCursor of CompilerKernelV2.WorkItem<
            CompilerKernelV2.ElaboratedPhase,
            CompilerKernelV2.JoinPointWorkKind,
            CompilerKernelV2.WorkOwnerBoundState,
            CompilerKernelV2.WorkQueuedState>
        | JpWorkSuspendedCursor of CompilerKernelV2.WorkSuspension<
            CompilerKernelV2.ElaboratedPhase,
            CompilerKernelV2.JoinPointWorkKind,
            CompilerKernelV2.WorkOwnerBoundState,
            unit>

    module JpWorkOperationalCursor =
        let queued item = JpWorkQueuedCursor item

        let private itemOf = function
            | JpWorkQueuedCursor item ->
                CompilerKernelV2.WorkItemOps.workUnit item,
                CompilerKernelV2.WorkItemOps.owner item,
                CompilerKernelV2.WorkItemOps.generation item,
                CompilerKernelV2.WorkItemOps.semanticCost item,
                CompilerKernelV2.WorkItemOps.getCommitOrdinal item
            | JpWorkSuspendedCursor suspension ->
                let item = CompilerKernelV2.WorkItemOps.suspendedWork suspension
                CompilerKernelV2.WorkItemOps.workUnit item,
                CompilerKernelV2.WorkItemOps.owner item,
                CompilerKernelV2.WorkItemOps.generation item,
                CompilerKernelV2.WorkItemOps.semanticCost item,
                CompilerKernelV2.WorkItemOps.getCommitOrdinal item

        let workUnit cursor = let workUnit,_,_,_,_ = itemOf cursor in workUnit
        let owner cursor = let _,owner,_,_,_ = itemOf cursor in owner
        let generation cursor = let _,_,generation,_,_ = itemOf cursor in generation
        let semanticCost cursor = let _,_,_,cost,_ = itemOf cursor in cost
        let commitOrdinal cursor = let _,_,_,_,ordinal = itemOf cursor in ordinal

        let start = function
            | JpWorkQueuedCursor queued ->
                let running = CompilerKernelV2.WorkItemOps.start queued
                running,
                CompilerKernelV2.WorkTransitionOps.start queued running,
                None
            | JpWorkSuspendedCursor suspension ->
                let running = CompilerKernelV2.WorkItemOps.resume suspension
                running,
                CompilerKernelV2.WorkTransitionOps.resume suspension running,
                Some (CompilerKernelV2.WorkItemOps.continuation suspension)

        let suspend dependencyRef running =
            let continuation =
                CompilerKernelV2.WorkContinuation.create<unit>
                    (CompilerKernelV2.WorkItemOps.generation running)
                    (CompilerKernelV2.WorkItemOps.identityRef running)
                    (CompilerKernelV2.WorkItemOps.getStateRef running)
                    dependencyRef
            let suspension =
                CompilerKernelV2.WorkItemOps.suspend
                    (CompilerKernelV2.WorkSuspendedOnDependency dependencyRef)
                    continuation
                    running
            JpWorkSuspendedCursor suspension,
            CompilerKernelV2.WorkTransitionOps.suspend running suspension

        let retireBeforeStart disposition = function
            | JpWorkQueuedCursor queued ->
                let retired, terminalDisposition =
                    CompilerKernelV2.WorkItemOps.retireQueued disposition queued
                retired,
                [ CompilerKernelV2.WorkTransitionOps.retireQueued queued retired terminalDisposition ],
                None
            | JpWorkSuspendedCursor suspension ->
                let running = CompilerKernelV2.WorkItemOps.resume suspension
                let resumeTransition = CompilerKernelV2.WorkTransitionOps.resume suspension running
                let retired, terminalDisposition =
                    CompilerKernelV2.WorkItemOps.retire disposition running
                retired,
                [ resumeTransition
                  CompilerKernelV2.WorkTransitionOps.retire running retired terminalDisposition ],
                Some (CompilerKernelV2.WorkItemOps.continuation suspension)

    type JpWorkContinuationRef = private JpWorkContinuationRef of CompilerIdentityKernel.ContentDigest
    module JpWorkContinuationRefOps =
        let create digest = JpWorkContinuationRef digest
        let digest (JpWorkContinuationRef digest) = digest
        let text value = value |> digest |> CompilerIdentityKernel.ContentDigest.text

    // Result-transparent AST wrappers and stage-local child carriers are typed topology, not a depth exception.
    // A bridge certifies only that the selected child result reaches the named continuation stage unchanged;
    // stage-local bridges such as LetBinding/ApplyArgument do not claim to be the whole expression result.
    type JpDeclaredTailResultBridgeId =
        | JpDeclaredFunctionBodyResultBridge
        | JpDeclaredRecursiveTermResultBridge
        | JpDeclaredLiteralConditionalBranchResultBridge
        | JpDeclaredPatternBranchResultBridge
        | JpDeclaredLetBodyResultBridge
        | JpDeclaredLetBindingResultBridge
        | JpDeclaredAnnotationResultBridge
        | JpDeclaredSequenceTailResultBridge
        | JpDeclaredApplyHeadResultBridge
        | JpDeclaredApplyArgumentResultBridge
        | JpDeclaredApplyDispatchResultBridge
        | JpDeclaredTypecaseBranchResultBridge

    let jpDeclaredTailResultBridgeText = function
        | JpDeclaredFunctionBodyResultBridge -> "FunctionBody"
        | JpDeclaredRecursiveTermResultBridge -> "RecursiveTerm"
        | JpDeclaredLiteralConditionalBranchResultBridge -> "LiteralConditionalBranch"
        | JpDeclaredPatternBranchResultBridge -> "PatternBranch"
        | JpDeclaredLetBodyResultBridge -> "LetBody"
        | JpDeclaredLetBindingResultBridge -> "LetBinding"
        | JpDeclaredAnnotationResultBridge -> "Annotation"
        | JpDeclaredSequenceTailResultBridge -> "SequenceTail"
        | JpDeclaredApplyHeadResultBridge -> "ApplyHead"
        | JpDeclaredApplyArgumentResultBridge -> "ApplyArgument"
        | JpDeclaredApplyDispatchResultBridge -> "ApplyDispatch"
        | JpDeclaredTypecaseBranchResultBridge -> "TypecaseBranch"

    type JpDeclaredTailResultBridgeTransparencyId =
        | JpDeclaredExpressionTransparentBridge
        | JpDeclaredStageLocalCarrierBridge

    let jpDeclaredTailResultBridgeTransparency = function
        | JpDeclaredFunctionBodyResultBridge
        | JpDeclaredRecursiveTermResultBridge
        | JpDeclaredLiteralConditionalBranchResultBridge
        | JpDeclaredPatternBranchResultBridge
        | JpDeclaredLetBodyResultBridge
        | JpDeclaredAnnotationResultBridge
        | JpDeclaredSequenceTailResultBridge
        | JpDeclaredTypecaseBranchResultBridge
        | JpDeclaredApplyDispatchResultBridge ->
            JpDeclaredExpressionTransparentBridge
        | JpDeclaredLetBindingResultBridge
        | JpDeclaredApplyHeadResultBridge
        | JpDeclaredApplyArgumentResultBridge ->
            JpDeclaredStageLocalCarrierBridge

    type JpDeclaredTailResultBridgePath =
        | JpDeclaredTailResultBridgeSingle of JpDeclaredTailResultBridgeId
        | JpDeclaredTailResultBridgeCompose of outer:JpDeclaredTailResultBridgePath * inner:JpDeclaredTailResultBridgeId

    let rec jpDeclaredTailResultBridgePathText = function
        | JpDeclaredTailResultBridgeSingle bridge -> jpDeclaredTailResultBridgeText bridge
        | JpDeclaredTailResultBridgeCompose(outer, inner) ->
            jpDeclaredTailResultBridgePathText outer + ">" + jpDeclaredTailResultBridgeText inner

    let rec jpDeclaredTailResultBridgePathIsExpressionTransparent = function
        | JpDeclaredTailResultBridgeSingle bridge ->
            jpDeclaredTailResultBridgeTransparency bridge = JpDeclaredExpressionTransparentBridge
        | JpDeclaredTailResultBridgeCompose(outer, inner) ->
            jpDeclaredTailResultBridgePathIsExpressionTransparent outer
            && jpDeclaredTailResultBridgeTransparency inner = JpDeclaredExpressionTransparentBridge

    type JpDeclaredEvaluatorParentPc =
        | JpDeclaredEvaluatorRootPc
        | JpDeclaredEvaluatorNestedPc of parentContinuation:JpWorkContinuationRef
        | JpDeclaredEvaluatorTailBridgePc of parentContinuation:JpWorkContinuationRef * bridgePath:JpDeclaredTailResultBridgePath * termDepthDelta:int
        | JpDeclaredEvaluatorOpaquePc of nearestTypedParent:JpWorkContinuationRef option * termDepthDelta:int

    type JpDeclaredEvaluatorPcKey =
        private JpDeclaredEvaluatorPcKey of jobId:int64 * nodeId:int * parentPc:JpDeclaredEvaluatorParentPc

    type JpDeclaredApplyFrame = private JpDeclaredApplyFrame of environment:LangEnv * expression:E

    module JpDeclaredApplyFrameOps =
        let create environment expression = JpDeclaredApplyFrame(environment, expression)
        let environment (JpDeclaredApplyFrame(environment, _)) = environment
        let expression (JpDeclaredApplyFrame(_, expression)) = expression

    type JpDeclaredApplyStage =
        | JpDeclaredApplyHeadPending
        | JpDeclaredApplyBeforeArgument
        | JpDeclaredApplyArgumentReadyDispatchPending of argumentValue:Data

    let jpDeclaredApplyStageText = function
        | JpDeclaredApplyHeadPending -> "HeadPending"
        | JpDeclaredApplyBeforeArgument -> "BeforeArgument"
        | JpDeclaredApplyArgumentReadyDispatchPending _ -> "ArgumentReadyDispatchPending"

    type JpDeclaredApplyContinuation = private {
        frames : JpDeclaredApplyFrame array
        nextFrameIndex : int
        currentValue : Data option
        stage : JpDeclaredApplyStage
        continuationRef : JpWorkContinuationRef
    }

    let jp_declared_apply_continuations =
        System.Collections.Concurrent.ConcurrentDictionary<JpDeclaredEvaluatorPcKey,JpDeclaredApplyContinuation>()

    type JpDeclaredLetStage =
        | JpDeclaredLetBindingPending
        | JpDeclaredLetCheckpointReady
        | JpDeclaredLetBodyPending

    let jpDeclaredLetStageText = function
        | JpDeclaredLetBindingPending -> "BindingPending"
        | JpDeclaredLetCheckpointReady -> "CheckpointReady"
        | JpDeclaredLetBodyPending -> "BodyPending"

    type JpDeclaredLetContinuation = private {
        environment : LangEnv
        remainingExpression : E
        bindingCount : int
        stage : JpDeclaredLetStage
        continuationRef : JpWorkContinuationRef
    }

    let jp_declared_let_continuations =
        System.Collections.Concurrent.ConcurrentDictionary<JpDeclaredEvaluatorPcKey,JpDeclaredLetContinuation>()

    // Sequence first expressions are unit-producing control frames.  The final tail is
    // expression-transparent.  Keep both stages as typed continuations so a cooperative
    // yield can never promote an intermediate unit value to the result of the whole ESeq.
    type JpDeclaredSequenceStage =
        | JpDeclaredSequenceFirstPending of sequenceRange:Range * firstExpression:E
        | JpDeclaredSequenceTailPending

    type JpDeclaredSequenceContinuation = private {
        environment : LangEnv
        remainingExpression : E
        stage : JpDeclaredSequenceStage
        continuationRef : JpWorkContinuationRef
    }

    let jp_declared_sequence_continuations =
        System.Collections.Concurrent.ConcurrentDictionary<JpDeclaredEvaluatorPcKey,JpDeclaredSequenceContinuation>()

    // Binary numeric operations are value-transforming frames, not tail-result bridges.
    // Div/Mod are the first migrated pair because the remaining external residual lives
    // in the trace formatting arithmetic path.  Their continuation owns the left/right
    // carrier explicitly so a cooperative yield never requires ancestor expression replay.
    type JpDeclaredBinaryNumericOperationId =
        | JpDeclaredBinaryNumericDiv
        | JpDeclaredBinaryNumericMod

    [<Struct>]
    type JpDeclaredBinaryNumericTypeRelationId =
        | JpDeclaredBinaryNumericEqualNumeric
        | JpDeclaredBinaryNumericEqualNonNumeric
        | JpDeclaredBinaryNumericLeftPlaceholderRightNumeric
        | JpDeclaredBinaryNumericRightPlaceholderLeftNumeric
        | JpDeclaredBinaryNumericRejectedMismatch

    let jpDeclaredBinaryNumericOperationText = function
        | JpDeclaredBinaryNumericDiv -> "Div"
        | JpDeclaredBinaryNumericMod -> "Mod"

    let jpDeclaredBinaryNumericOperationToOp = function
        | JpDeclaredBinaryNumericDiv -> Div
        | JpDeclaredBinaryNumericMod -> Mod

    type JpDeclaredBinaryNumericStage =
        | JpDeclaredBinaryNumericLeftPending
        | JpDeclaredBinaryNumericRightPending of leftValue:Data

    let jpDeclaredBinaryNumericStageText = function
        | JpDeclaredBinaryNumericLeftPending -> "LeftPending"
        | JpDeclaredBinaryNumericRightPending _ -> "RightPending"

    type JpDeclaredBinaryNumericContinuation = private {
        environment : LangEnv
        operation : JpDeclaredBinaryNumericOperationId
        leftExpression : E
        rightExpression : E
        stage : JpDeclaredBinaryNumericStage
        continuationRef : JpWorkContinuationRef
    }

    let jp_declared_binary_numeric_continuations =
        System.Collections.Concurrent.ConcurrentDictionary<JpDeclaredEvaluatorPcKey,JpDeclaredBinaryNumericContinuation>()

    type JpDeclaredRecordTypeFoldBackState =
        | JpDeclaredRecordTypeFoldBackFolderPending of environment:LangEnv
        | JpDeclaredRecordTypeFoldBackInitialStatePending of environment:LangEnv * folder:Data
        | JpDeclaredRecordTypeFoldBackRecordTypePending of environment:LangEnv * folder:Data * initialStateValue:Data
        | JpDeclaredRecordTypeFoldBackFieldPending of environment:LangEnv * folder:Data * fields:((int * string) * Ty) array * nextFieldIndex:int * currentState:Data
        | JpDeclaredRecordTypeFoldBackKeyApplied of environment:LangEnv * folder:Data * fields:((int * string) * Ty) array * nextFieldIndex:int * currentState:Data * typedFolder:Data
        | JpDeclaredRecordTypeFoldBackTypeApplied of environment:LangEnv * folder:Data * fields:((int * string) * Ty) array * nextFieldIndex:int * currentState:Data * specializedFolder:Data

    let jpDeclaredRecordTypeFoldBackStateText = function
        | JpDeclaredRecordTypeFoldBackFolderPending _ -> "FolderPending"
        | JpDeclaredRecordTypeFoldBackInitialStatePending _ -> "InitialStatePending"
        | JpDeclaredRecordTypeFoldBackRecordTypePending _ -> "RecordTypePending"
        | JpDeclaredRecordTypeFoldBackFieldPending(_, _, _, nextFieldIndex, _) -> "FieldPending:" + string nextFieldIndex
        | JpDeclaredRecordTypeFoldBackKeyApplied(_, _, _, nextFieldIndex, _, _) -> "KeyApplied:" + string nextFieldIndex
        | JpDeclaredRecordTypeFoldBackTypeApplied(_, _, _, nextFieldIndex, _, _) -> "TypeApplied:" + string nextFieldIndex

    type JpDeclaredApplyProgressStageId =
        | JpDeclaredApplyProgressHeadPending
        | JpDeclaredApplyProgressBeforeArgument
        | JpDeclaredApplyProgressDispatchPending

    type JpDeclaredLetProgressStageId =
        | JpDeclaredLetProgressBindingPending
        | JpDeclaredLetProgressCheckpointReady
        | JpDeclaredLetProgressBodyPending

    type JpDeclaredSequenceProgressStageId =
        | JpDeclaredSequenceProgressFirstPending
        | JpDeclaredSequenceProgressTailPending

    type JpDeclaredBinaryNumericProgressStageId =
        | JpDeclaredBinaryNumericProgressLeftPending
        | JpDeclaredBinaryNumericProgressRightPending

    type JpDeclaredFoldProgressStageId =
        | JpDeclaredFoldProgressFolderPending
        | JpDeclaredFoldProgressInitialStatePending
        | JpDeclaredFoldProgressRecordTypePending
        | JpDeclaredFoldProgressFieldPending of nextFieldIndex:int
        | JpDeclaredFoldProgressKeyApplied of nextFieldIndex:int
        | JpDeclaredFoldProgressTypeApplied of nextFieldIndex:int

    type JpDeclaredResumeProgressPositionId =
        | JpDeclaredApplyProgressPosition of nextFrameIndex:int * stage:JpDeclaredApplyProgressStageId
        | JpDeclaredLetProgressPosition of bindingCount:int * stage:JpDeclaredLetProgressStageId
        | JpDeclaredSequenceProgressPosition of stage:JpDeclaredSequenceProgressStageId
        | JpDeclaredBinaryNumericProgressPosition of operation:JpDeclaredBinaryNumericOperationId * stage:JpDeclaredBinaryNumericProgressStageId
        | JpDeclaredFoldProgressPosition of stage:JpDeclaredFoldProgressStageId

    type JpDeclaredRecordTypePrepassSource = private | JpDeclaredRecordTypePrepassSource of TPrepass

    let jpDeclaredRecordTypePrepass (JpDeclaredRecordTypePrepassSource source) = source

    type JpDeclaredRecordTypeFoldBackContinuation = private {
        folderExpression : E
        initialStateExpression : E
        recordTypeSource : JpDeclaredRecordTypePrepassSource
        state : JpDeclaredRecordTypeFoldBackState
        continuationRef : JpWorkContinuationRef
    }

    let jp_declared_record_type_foldback_continuations =
        System.Collections.Concurrent.ConcurrentDictionary<JpDeclaredEvaluatorPcKey,JpDeclaredRecordTypeFoldBackContinuation>()

    type JpDeclaredResumeLocatorId =
        | JpDeclaredApplyResumeLocator of JpDeclaredEvaluatorPcKey
        | JpDeclaredLetResumeLocator of JpDeclaredEvaluatorPcKey
        | JpDeclaredSequenceResumeLocator of JpDeclaredEvaluatorPcKey
        | JpDeclaredBinaryNumericResumeLocator of JpDeclaredEvaluatorPcKey
        | JpDeclaredRecordTypeFoldBackResumeLocator of JpDeclaredEvaluatorPcKey

    type JpDeclaredResumeSnapshotId =
        | JpDeclaredApplyResumeSnapshot of key:JpDeclaredEvaluatorPcKey * continuation:JpDeclaredApplyContinuation
        | JpDeclaredLetResumeSnapshot of key:JpDeclaredEvaluatorPcKey * continuation:JpDeclaredLetContinuation
        | JpDeclaredSequenceResumeSnapshot of key:JpDeclaredEvaluatorPcKey * continuation:JpDeclaredSequenceContinuation
        | JpDeclaredBinaryNumericResumeSnapshot of key:JpDeclaredEvaluatorPcKey * continuation:JpDeclaredBinaryNumericContinuation
        | JpDeclaredRecordTypeFoldBackResumeSnapshot of key:JpDeclaredEvaluatorPcKey * continuation:JpDeclaredRecordTypeFoldBackContinuation

    let jpDeclaredResumeProgressPositionOf = function
        | JpDeclaredApplyResumeSnapshot(_, continuation) ->
            let stage =
                match continuation.stage with
                | JpDeclaredApplyHeadPending -> JpDeclaredApplyProgressHeadPending
                | JpDeclaredApplyBeforeArgument -> JpDeclaredApplyProgressBeforeArgument
                | JpDeclaredApplyArgumentReadyDispatchPending _ -> JpDeclaredApplyProgressDispatchPending
            JpDeclaredApplyProgressPosition(continuation.nextFrameIndex, stage)
        | JpDeclaredLetResumeSnapshot(_, continuation) ->
            let stage =
                match continuation.stage with
                | JpDeclaredLetBindingPending -> JpDeclaredLetProgressBindingPending
                | JpDeclaredLetCheckpointReady -> JpDeclaredLetProgressCheckpointReady
                | JpDeclaredLetBodyPending -> JpDeclaredLetProgressBodyPending
            JpDeclaredLetProgressPosition(continuation.bindingCount, stage)
        | JpDeclaredSequenceResumeSnapshot(_, continuation) ->
            let stage =
                match continuation.stage with
                | JpDeclaredSequenceFirstPending _ -> JpDeclaredSequenceProgressFirstPending
                | JpDeclaredSequenceTailPending -> JpDeclaredSequenceProgressTailPending
            JpDeclaredSequenceProgressPosition stage
        | JpDeclaredBinaryNumericResumeSnapshot(_, continuation) ->
            let stage =
                match continuation.stage with
                | JpDeclaredBinaryNumericLeftPending -> JpDeclaredBinaryNumericProgressLeftPending
                | JpDeclaredBinaryNumericRightPending _ -> JpDeclaredBinaryNumericProgressRightPending
            JpDeclaredBinaryNumericProgressPosition(continuation.operation, stage)
        | JpDeclaredRecordTypeFoldBackResumeSnapshot(_, continuation) ->
            let stage =
                match continuation.state with
                | JpDeclaredRecordTypeFoldBackFolderPending _ -> JpDeclaredFoldProgressFolderPending
                | JpDeclaredRecordTypeFoldBackInitialStatePending _ -> JpDeclaredFoldProgressInitialStatePending
                | JpDeclaredRecordTypeFoldBackRecordTypePending _ -> JpDeclaredFoldProgressRecordTypePending
                | JpDeclaredRecordTypeFoldBackFieldPending(_, _, _, nextFieldIndex, _) -> JpDeclaredFoldProgressFieldPending nextFieldIndex
                | JpDeclaredRecordTypeFoldBackKeyApplied(_, _, _, nextFieldIndex, _, _) -> JpDeclaredFoldProgressKeyApplied nextFieldIndex
                | JpDeclaredRecordTypeFoldBackTypeApplied(_, _, _, nextFieldIndex, _, _) -> JpDeclaredFoldProgressTypeApplied nextFieldIndex
            JpDeclaredFoldProgressPosition stage

    let jpDeclaredResumeProgressPositionDigest (jobId:int64) (nodeId:int) = function
        | JpDeclaredApplyProgressPosition(nextFrameIndex, stage) ->
            let stageCode =
                match stage with
                | JpDeclaredApplyProgressHeadPending -> 0
                | JpDeclaredApplyProgressBeforeArgument -> 1
                | JpDeclaredApplyProgressDispatchPending -> 2
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-declared-apply-progress-position"
                (FastRuntimeFormat.format "%d|%d|%d|%d" [| box jobId; box nodeId; box nextFrameIndex; box stageCode |])
        | JpDeclaredLetProgressPosition(bindingCount, stage) ->
            let stageCode =
                match stage with
                | JpDeclaredLetProgressBindingPending -> 0
                | JpDeclaredLetProgressCheckpointReady -> 1
                | JpDeclaredLetProgressBodyPending -> 2
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-declared-let-progress-position"
                (FastRuntimeFormat.format "%d|%d|%d|%d" [| box jobId; box nodeId; box bindingCount; box stageCode |])
        | JpDeclaredSequenceProgressPosition stage ->
            let stageCode =
                match stage with
                | JpDeclaredSequenceProgressFirstPending -> 0
                | JpDeclaredSequenceProgressTailPending -> 1
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-declared-sequence-progress-position"
                (FastRuntimeFormat.format "%d|%d|%d" [| box jobId; box nodeId; box stageCode |])
        | JpDeclaredBinaryNumericProgressPosition(operation, stage) ->
            let operationCode =
                match operation with
                | JpDeclaredBinaryNumericDiv -> 0
                | JpDeclaredBinaryNumericMod -> 1
            let stageCode =
                match stage with
                | JpDeclaredBinaryNumericProgressLeftPending -> 0
                | JpDeclaredBinaryNumericProgressRightPending -> 1
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-declared-binary-numeric-progress-position"
                (FastRuntimeFormat.format "%d|%d|%d|%d" [| box jobId; box nodeId; box operationCode; box stageCode |])
        | JpDeclaredFoldProgressPosition stage ->
            let stageCode, cursor =
                match stage with
                | JpDeclaredFoldProgressFolderPending -> 0, -1
                | JpDeclaredFoldProgressInitialStatePending -> 1, -1
                | JpDeclaredFoldProgressRecordTypePending -> 2, -1
                | JpDeclaredFoldProgressFieldPending nextFieldIndex -> 3, nextFieldIndex
                | JpDeclaredFoldProgressKeyApplied nextFieldIndex -> 4, nextFieldIndex
                | JpDeclaredFoldProgressTypeApplied nextFieldIndex -> 5, nextFieldIndex
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-declared-fold-progress-position"
                (FastRuntimeFormat.format "%d|%d|%d|%d" [| box jobId; box nodeId; box stageCode; box cursor |])

    type JpDeclaredDataResultAcceptorId =
        | JpDeclaredApplyHeadResultAcceptor
        | JpDeclaredApplyArgumentResultAcceptor
        | JpDeclaredApplyDispatchResultAcceptor
        | JpDeclaredLetBindingResultAcceptor
        | JpDeclaredLetBodyResultAcceptor
        | JpDeclaredSequenceFirstResultAcceptor
        | JpDeclaredSequenceTailResultAcceptor
        | JpDeclaredBinaryNumericLeftResultAcceptor
        | JpDeclaredBinaryNumericRightResultAcceptor
        | JpDeclaredFoldFolderResultAcceptor
        | JpDeclaredFoldInitialStateResultAcceptor
        | JpDeclaredFoldKeyApplyResultAcceptor
        | JpDeclaredFoldTypeApplyResultAcceptor
        | JpDeclaredFoldStateApplyResultAcceptor

    type JpDeclaredResumeResultChannelId =
        | JpDeclaredResumeDataResult of JpDeclaredDataResultAcceptorId
        | JpDeclaredResumeFoldRecordTypeResult
        | JpDeclaredResumeLetCheckpointCursorOnly

    let jpDeclaredDataResultAcceptorText = function
        | JpDeclaredApplyHeadResultAcceptor -> "ApplyHeadResult"
        | JpDeclaredApplyArgumentResultAcceptor -> "ApplyArgumentResult"
        | JpDeclaredApplyDispatchResultAcceptor -> "ApplyDispatchResult"
        | JpDeclaredLetBindingResultAcceptor -> "LetBindingResult"
        | JpDeclaredLetBodyResultAcceptor -> "LetBodyResult"
        | JpDeclaredSequenceFirstResultAcceptor -> "SequenceFirstResult"
        | JpDeclaredSequenceTailResultAcceptor -> "SequenceTailResult"
        | JpDeclaredBinaryNumericLeftResultAcceptor -> "BinaryNumericLeftResult"
        | JpDeclaredBinaryNumericRightResultAcceptor -> "BinaryNumericRightResult"
        | JpDeclaredFoldFolderResultAcceptor -> "FoldFolderResult"
        | JpDeclaredFoldInitialStateResultAcceptor -> "FoldInitialStateResult"
        | JpDeclaredFoldKeyApplyResultAcceptor -> "FoldKeyApplyResult"
        | JpDeclaredFoldTypeApplyResultAcceptor -> "FoldTypeApplyResult"
        | JpDeclaredFoldStateApplyResultAcceptor -> "FoldStateApplyResult"

    let jpDeclaredResumeResultChannelText (channel:JpDeclaredResumeResultChannelId) =
        match channel with
        | JpDeclaredResumeDataResult acceptor -> "Data(" + jpDeclaredDataResultAcceptorText acceptor + ")"
        | JpDeclaredResumeFoldRecordTypeResult -> "FoldRecordTypeResult"
        | JpDeclaredResumeLetCheckpointCursorOnly -> "LetCheckpointCursorOnly"

    let jpDeclaredResumeSnapshotKindText = function
        | JpDeclaredApplyResumeSnapshot _ -> "Apply"
        | JpDeclaredLetResumeSnapshot _ -> "Let"
        | JpDeclaredSequenceResumeSnapshot _ -> "Sequence"
        | JpDeclaredBinaryNumericResumeSnapshot _ -> "BinaryNumeric"
        | JpDeclaredRecordTypeFoldBackResumeSnapshot _ -> "Fold"

    let jpDeclaredResumeSnapshotResultChannel (snapshot:JpDeclaredResumeSnapshotId) : JpDeclaredResumeResultChannelId =
        match snapshot with
        | JpDeclaredApplyResumeSnapshot(_, continuation) ->
            match continuation.stage with
            | JpDeclaredApplyHeadPending -> JpDeclaredResumeDataResult JpDeclaredApplyHeadResultAcceptor
            | JpDeclaredApplyBeforeArgument -> JpDeclaredResumeDataResult JpDeclaredApplyArgumentResultAcceptor
            | JpDeclaredApplyArgumentReadyDispatchPending _ -> JpDeclaredResumeDataResult JpDeclaredApplyDispatchResultAcceptor
        | JpDeclaredLetResumeSnapshot(_, continuation) ->
            match continuation.stage with
            | JpDeclaredLetBindingPending -> JpDeclaredResumeDataResult JpDeclaredLetBindingResultAcceptor
            | JpDeclaredLetCheckpointReady -> JpDeclaredResumeLetCheckpointCursorOnly
            | JpDeclaredLetBodyPending -> JpDeclaredResumeDataResult JpDeclaredLetBodyResultAcceptor
        | JpDeclaredSequenceResumeSnapshot(_, continuation) ->
            match continuation.stage with
            | JpDeclaredSequenceFirstPending _ -> JpDeclaredResumeDataResult JpDeclaredSequenceFirstResultAcceptor
            | JpDeclaredSequenceTailPending -> JpDeclaredResumeDataResult JpDeclaredSequenceTailResultAcceptor
        | JpDeclaredBinaryNumericResumeSnapshot(_, continuation) ->
            match continuation.stage with
            | JpDeclaredBinaryNumericLeftPending -> JpDeclaredResumeDataResult JpDeclaredBinaryNumericLeftResultAcceptor
            | JpDeclaredBinaryNumericRightPending _ -> JpDeclaredResumeDataResult JpDeclaredBinaryNumericRightResultAcceptor
        | JpDeclaredRecordTypeFoldBackResumeSnapshot(_, continuation) ->
            match continuation.state with
            | JpDeclaredRecordTypeFoldBackFolderPending _ -> JpDeclaredResumeDataResult JpDeclaredFoldFolderResultAcceptor
            | JpDeclaredRecordTypeFoldBackInitialStatePending _ -> JpDeclaredResumeDataResult JpDeclaredFoldInitialStateResultAcceptor
            | JpDeclaredRecordTypeFoldBackRecordTypePending _ -> JpDeclaredResumeFoldRecordTypeResult
            | JpDeclaredRecordTypeFoldBackFieldPending _ -> JpDeclaredResumeDataResult JpDeclaredFoldKeyApplyResultAcceptor
            | JpDeclaredRecordTypeFoldBackKeyApplied _ -> JpDeclaredResumeDataResult JpDeclaredFoldTypeApplyResultAcceptor
            | JpDeclaredRecordTypeFoldBackTypeApplied _ -> JpDeclaredResumeDataResult JpDeclaredFoldStateApplyResultAcceptor

    type JpDeclaredApplySeedCapabilityId =
        | JpDeclaredApplySeedReplayable
        | JpDeclaredApplySeedNeedsDataCarrier of JpDeclaredDataResultAcceptorId

    let jpDeclaredApplySeedCapability = function
        | JpDeclaredApplyHeadPending ->
            JpDeclaredApplySeedNeedsDataCarrier JpDeclaredApplyHeadResultAcceptor
        | JpDeclaredApplyBeforeArgument -> JpDeclaredApplySeedReplayable
        | JpDeclaredApplyArgumentReadyDispatchPending _ ->
            JpDeclaredApplySeedNeedsDataCarrier JpDeclaredApplyDispatchResultAcceptor

    let jpDeclaredApplyStageCanSeed stage =
        match jpDeclaredApplySeedCapability stage with
        | JpDeclaredApplySeedReplayable -> true
        | JpDeclaredApplySeedNeedsDataCarrier _ -> false

    let jpDeclaredApplySeedCurrentValue (continuation:JpDeclaredApplyContinuation) =
        match jpDeclaredApplySeedCapability continuation.stage with
        | JpDeclaredApplySeedReplayable ->
            match continuation.currentValue with
            | Some value -> value
            | None -> invalidOp "Replayable Apply continuation is missing its current value."
        | JpDeclaredApplySeedNeedsDataCarrier _ ->
            invalidOp "Non-replayable Apply continuation requires its direct typed child result carrier; ancestor head replay is forbidden."

    let jp_declared_resume_snapshots =
        System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,JpDeclaredResumeSnapshotId>()

    let jp_declared_resume_targets =
        System.Collections.Concurrent.ConcurrentDictionary<int64,JpWorkContinuationRef>()

    let jp_declared_continuation_ordinals =
        System.Collections.Concurrent.ConcurrentDictionary<int64,int64>()

    // Resume evidence has its own monotone revision.  A yielded work item wakes
    // only when continuation identity or structural snapshot evidence changes;
    // queue scans never poll the planner itself.
    let jp_declared_resume_evidence_revisions =
        System.Collections.Concurrent.ConcurrentDictionary<int64,int64>()

    type JpDeclaredResumeSnapshotRegistrationEvidence = private {
        job_id : int64
        registration_revision : int64
        node_id : int
    }

    // Preserve a bounded registration-order witness even after an affine snapshot
    // is retired.  A stale target may be rebased only to a same-job safe checkpoint
    // whose snapshot was registered strictly later; the ledger is removed with the job.
    let jp_declared_resume_snapshot_registration_evidence =
        System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,JpDeclaredResumeSnapshotRegistrationEvidence>()

    type JpDeclaredResumeSnapshotRetirementCauseId =
        | JpDeclaredResumeSnapshotExplicitRetirement
        | JpDeclaredResumeSnapshotUnreachablePrune

    let jpDeclaredResumeSnapshotRetirementCauseText = function
        | JpDeclaredResumeSnapshotExplicitRetirement -> "ExplicitRetirement"
        | JpDeclaredResumeSnapshotUnreachablePrune -> "UnreachablePrune"

    type JpDeclaredResumeSnapshotRetirementEvidence = private {
        job_id : int64
        cause : JpDeclaredResumeSnapshotRetirementCauseId
        retired_at_ms : int64
    }

    let jp_declared_resume_snapshot_retirement_evidence =
        System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,JpDeclaredResumeSnapshotRetirementEvidence>()

    let jpRememberDeclaredResumeSnapshotRetirementEvidence digest jobId cause =
        jp_declared_resume_snapshot_retirement_evidence.[digest] <-
            { job_id = jobId
              cause = cause
              retired_at_ms = max 0L (jp_progress_clock()) }

    let jpTryDeclaredResumeSnapshotRetirementEvidence continuationRef =
        let digest = JpWorkContinuationRefOps.digest continuationRef
        let mutable evidence = Unchecked.defaultof<JpDeclaredResumeSnapshotRetirementEvidence>
        if jp_declared_resume_snapshot_retirement_evidence.TryGetValue(digest, &evidence) then Some evidence else None

    // Queued/suspended work owns its semantic resume PC just as strongly as an installed
    // execution target.  Snapshot pruning must not collect a continuation while a work item
    // carrying it is waiting for lane admission or typed-carrier evidence.  Ref-counted
    // ownership keeps queue liveness explicit without making historical locator indexes roots.
    type JpDeclaredQueuedResumeRoot = private {
        jobId : int64
        continuationRef : JpWorkContinuationRef
        ownerCount : int
    }

    let jp_declared_queued_resume_roots =
        System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,JpDeclaredQueuedResumeRoot>()

    let jpRetainDeclaredQueuedResumeRoot jobId continuationRef =
        let digest = JpWorkContinuationRefOps.digest continuationRef
        jp_declared_queued_resume_roots.AddOrUpdate(
            digest,
            { jobId = jobId; continuationRef = continuationRef; ownerCount = 1 },
            fun _ current ->
                if current.jobId <> jobId then
                    invalidOp "queued resume root digest cannot cross declared-body jobs"
                { current with ownerCount = current.ownerCount + 1 })
        |> ignore

    let jpReleaseDeclaredQueuedResumeRoot jobId continuationRef =
        let digest = JpWorkContinuationRefOps.digest continuationRef
        let rec release () =
            let mutable current = Unchecked.defaultof<JpDeclaredQueuedResumeRoot>
            if jp_declared_queued_resume_roots.TryGetValue(digest, &current) then
                if current.jobId <> jobId then
                    invalidOp "queued resume root release cannot cross declared-body jobs"
                elif current.ownerCount <= 0 then
                    false
                else
                    let next = { current with ownerCount = current.ownerCount - 1 }
                    if jp_declared_queued_resume_roots.TryUpdate(digest, next, current) then true
                    else release ()
            else false
        release () |> ignore

    let jpDeclaredQueuedResumeRootsForJob jobId =
        jp_declared_queued_resume_roots.ToArray()
        |> Array.choose (fun entry ->
            let root = entry.Value
            if root.jobId = jobId && root.ownerCount > 0 then Some root.continuationRef else None)

    // A running evaluator can create a newer safe continuation before that continuation
    // is copied into a queued successor. That transient-but-live PC is an affine execution
    // root too; otherwise periodic pruning can collect it between creation and yield.
    type JpDeclaredActiveResumeRoot = private {
        jobId : int64
        continuationRef : JpWorkContinuationRef
        ownerCount : int
    }

    let jp_declared_active_resume_roots =
        System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,JpDeclaredActiveResumeRoot>()

    let jpRetainDeclaredActiveResumeRoot jobId continuationRef =
        let digest = JpWorkContinuationRefOps.digest continuationRef
        jp_declared_active_resume_roots.AddOrUpdate(
            digest,
            { jobId = jobId; continuationRef = continuationRef; ownerCount = 1 },
            fun _ current ->
                if current.jobId <> jobId then
                    invalidOp "active resume root digest cannot cross declared-body jobs"
                { current with ownerCount = current.ownerCount + 1 })
        |> ignore

    let jpReleaseDeclaredActiveResumeRoot jobId continuationRef =
        let digest = JpWorkContinuationRefOps.digest continuationRef
        let rec release () =
            let mutable current = Unchecked.defaultof<JpDeclaredActiveResumeRoot>
            if jp_declared_active_resume_roots.TryGetValue(digest, &current) then
                if current.jobId <> jobId then
                    invalidOp "active resume root release cannot cross declared-body jobs"
                elif current.ownerCount <= 0 then
                    false
                else
                    let next = { current with ownerCount = current.ownerCount - 1 }
                    if jp_declared_active_resume_roots.TryUpdate(digest, next, current) then true
                    else release ()
            else false
        release () |> ignore

    let jpDeclaredActiveResumeRootsForJob jobId =
        jp_declared_active_resume_roots.ToArray()
        |> Array.choose (fun entry ->
            let root = entry.Value
            if root.jobId = jobId && root.ownerCount > 0 then Some root.continuationRef else None)

    // Direct mixed/apply resume execution is a third affine owner domain. Keep its
    // count beside queue/active ownership so explicit retirement cannot invalidate a
    // continuation while a direct-resume prefix is still executing against it.
    let jp_declared_direct_resume_execution_roots =
        System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,int>()

    // Snapshot retirement is affine with respect to work ownership. A queued successor,
    // the currently executing evaluator, or a direct-resume prefix may still own the PC
    // after another path has finished with that same snapshot. Physical removal must
    // therefore wait until all three ownership domains have released it.
    type JpDeclaredResumeSnapshotLiveOwnerCounts = private {
        queuedOwners : int
        activeOwners : int
        directExecutionOwners : int
    }

    module JpDeclaredResumeSnapshotLiveOwnerCountsOps =
        let total owners = owners.queuedOwners + owners.activeOwners + owners.directExecutionOwners
        let queued owners = owners.queuedOwners
        let active owners = owners.activeOwners
        let directExecution owners = owners.directExecutionOwners

    let jpDeclaredResumeSnapshotLiveOwnerCounts continuationRef =
        let digest = JpWorkContinuationRefOps.digest continuationRef
        let mutable queuedRoot = Unchecked.defaultof<JpDeclaredQueuedResumeRoot>
        let queuedOwners =
            if jp_declared_queued_resume_roots.TryGetValue(digest, &queuedRoot) then max 0 queuedRoot.ownerCount
            else 0
        let mutable activeRoot = Unchecked.defaultof<JpDeclaredActiveResumeRoot>
        let activeOwners =
            if jp_declared_active_resume_roots.TryGetValue(digest, &activeRoot) then max 0 activeRoot.ownerCount
            else 0
        let mutable directExecutionOwnerCount = 0
        let directExecutionOwners =
            if jp_declared_direct_resume_execution_roots.TryGetValue(digest, &directExecutionOwnerCount) then max 0 directExecutionOwnerCount
            else 0
        { queuedOwners = queuedOwners
          activeOwners = activeOwners
          directExecutionOwners = directExecutionOwners }

    let jpDeclaredResumeSnapshotJobId = function
        | JpDeclaredApplyResumeSnapshot(JpDeclaredEvaluatorPcKey(jobId, _, _), _)
        | JpDeclaredLetResumeSnapshot(JpDeclaredEvaluatorPcKey(jobId, _, _), _)
        | JpDeclaredSequenceResumeSnapshot(JpDeclaredEvaluatorPcKey(jobId, _, _), _)
        | JpDeclaredBinaryNumericResumeSnapshot(JpDeclaredEvaluatorPcKey(jobId, _, _), _)
        | JpDeclaredRecordTypeFoldBackResumeSnapshot(JpDeclaredEvaluatorPcKey(jobId, _, _), _) -> jobId

    let jpDeclaredResumeSnapshotNodeId = function
        | JpDeclaredApplyResumeSnapshot(JpDeclaredEvaluatorPcKey(_, nodeId, _), _)
        | JpDeclaredLetResumeSnapshot(JpDeclaredEvaluatorPcKey(_, nodeId, _), _)
        | JpDeclaredSequenceResumeSnapshot(JpDeclaredEvaluatorPcKey(_, nodeId, _), _)
        | JpDeclaredBinaryNumericResumeSnapshot(JpDeclaredEvaluatorPcKey(_, nodeId, _), _)
        | JpDeclaredRecordTypeFoldBackResumeSnapshot(JpDeclaredEvaluatorPcKey(_, nodeId, _), _) -> nodeId

    // One level-trigger-like pulse wakes a worker whenever the queue or typed resume
    // evidence may have become runnable. Timed waits remain the fail-safe against a lost pulse.
    let jp_specialization_runnable_signal = new System.Threading.AutoResetEvent(false)

    let jpSignalSpecializationRunnablePotential () =
        jp_specialization_runnable_signal.Set() |> ignore

    let jpNoteDeclaredResumeEvidence jobId =
        let revision =
            jp_declared_resume_evidence_revisions.AddOrUpdate(jobId, 1L, fun _ current -> current + 1L)
        jpSignalSpecializationRunnablePotential ()
        revision

    let jpDeclaredResumeEvidenceRevisionCurrent jobId =
        let mutable current = 0L
        if jp_declared_resume_evidence_revisions.TryGetValue(jobId, &current) then current else 0L

    let jpDeclaredResumeWakeEvidenceDigest () =
        let ordinalText =
            jp_declared_continuation_ordinals.ToArray()
            |> Array.sortBy (fun entry -> entry.Key)
            |> Array.map (fun entry -> string entry.Key + ":" + string entry.Value)
            |> String.concat ";"
        let revisionText =
            jp_declared_resume_evidence_revisions.ToArray()
            |> Array.sortBy (fun entry -> entry.Key)
            |> Array.map (fun entry -> string entry.Key + ":" + string entry.Value)
            |> String.concat ";"
        CompilerIdentityKernel.ContentDigest.ofText
            "jp-declared-resume-wake-evidence"
            ("ordinals=" + ordinalText + "|revisions=" + revisionText)

    let jp_current_declared_direct_resume_execution_roots =
        System.Threading.AsyncLocal<JpWorkContinuationRef array>()

    let jpCurrentDeclaredDirectResumeExecutionRoots () =
        let roots = jp_current_declared_direct_resume_execution_roots.Value
        if obj.ReferenceEquals(roots, null) then [||] else roots

    type JpDeclaredCurrentParentEndpointId =
        | JpDeclaredParentEndpointExecutionRoot of JpWorkContinuationRef
        | JpDeclaredParentEndpointInstalledResumeTarget of JpWorkContinuationRef
        | JpDeclaredParentEndpointUnavailable

    let jpDeclaredCurrentParentEndpointText = function
        | JpDeclaredParentEndpointExecutionRoot continuationRef ->
            "ExecutionRoot(" + JpWorkContinuationRefOps.text continuationRef + ")"
        | JpDeclaredParentEndpointInstalledResumeTarget continuationRef ->
            "InstalledResumeTarget(" + JpWorkContinuationRefOps.text continuationRef + ")"
        | JpDeclaredParentEndpointUnavailable -> "Unavailable"

    let jpReleaseDeclaredDirectResumeExecutionRoots digests =
        for digest in digests do
            let mutable released = false
            while not released do
                let mutable current = 0
                if jp_declared_direct_resume_execution_roots.TryGetValue(digest, &current) then
                    if current <= 1 then
                        let mutable removed = 0
                        if jp_declared_direct_resume_execution_roots.TryRemove(digest, &removed) then released <- true
                    elif jp_declared_direct_resume_execution_roots.TryUpdate(digest, current - 1, current) then
                        released <- true
                else
                    released <- true

    let jpWithDeclaredDirectResumeExecutionRoots continuationRefs run =
        let digests =
            continuationRefs
            |> Array.map (fun continuationRef ->
                let digest = JpWorkContinuationRefOps.digest continuationRef
                jp_declared_direct_resume_execution_roots.AddOrUpdate(digest, 1, fun _ current -> current + 1) |> ignore
                digest)
        let previousRoots = jp_current_declared_direct_resume_execution_roots.Value
        jp_current_declared_direct_resume_execution_roots.Value <- continuationRefs
        try run()
        finally
            jp_current_declared_direct_resume_execution_roots.Value <- previousRoots
            jpReleaseDeclaredDirectResumeExecutionRoots digests

    let jpWithCurrentDeclaredDirectResumeExecutionRoot continuationRef run =
        let previousRoots = jp_current_declared_direct_resume_execution_roots.Value
        // Retained roots protect snapshot lifetime; this singleton scope identifies the
        // specific continuation whose body is executing so nested descendants inherit a
        // live typed parent endpoint instead of interpreting a multi-root array as ambiguity.
        jp_current_declared_direct_resume_execution_roots.Value <- [| continuationRef |]
        try run()
        finally jp_current_declared_direct_resume_execution_roots.Value <- previousRoots

    let jpNextDeclaredContinuationOrdinal jobId =
        let ordinal =
            jp_declared_continuation_ordinals.AddOrUpdate(jobId, 1L, fun _ current -> current + 1L)
        jpSignalSpecializationRunnablePotential ()
        ordinal

    let jpDeclaredContinuationIdentityRef identityDomain (jobId:int64) (nodeId:int) (continuationOrdinal:int64) =
        CompilerIdentityKernel.ContentDigest.ofText
            identityDomain
            (FastRuntimeFormat.format "%d|%d|%d" [| box jobId; box nodeId; box continuationOrdinal |])
        |> JpWorkContinuationRefOps.create

    let jpRegisterDeclaredResumeSnapshot continuationRef snapshot =
        let digest = JpWorkContinuationRefOps.digest continuationRef
        if not (jp_declared_resume_snapshots.TryAdd(digest, snapshot)) then
            invalidOp ("duplicate declared continuation identity: " + CompilerIdentityKernel.ContentDigest.text digest)
        let jobId = jpDeclaredResumeSnapshotJobId snapshot
        let nodeId = jpDeclaredResumeSnapshotNodeId snapshot
        let registrationRevision = jpNoteDeclaredResumeEvidence jobId
        jp_declared_resume_snapshot_registration_evidence.[digest] <-
            { job_id = jobId
              registration_revision = registrationRevision
              node_id = nodeId }

    type JpDeclaredResumeSnapshotRetirementId =
        | JpDeclaredResumeSnapshotRetired
        | JpDeclaredResumeSnapshotDeferredByLiveOwner of JpDeclaredResumeSnapshotLiveOwnerCounts
        | JpDeclaredResumeSnapshotAlreadyAbsent

    let jpDeclaredResumeSnapshotRetirementText = function
        | JpDeclaredResumeSnapshotRetired -> "Retired"
        | JpDeclaredResumeSnapshotDeferredByLiveOwner owners ->
            FastRuntimeFormat.format
                "DeferredByLiveOwner(queue=%d|active=%d|direct=%d)"
                [| box (JpDeclaredResumeSnapshotLiveOwnerCountsOps.queued owners)
                   box (JpDeclaredResumeSnapshotLiveOwnerCountsOps.active owners)
                   box (JpDeclaredResumeSnapshotLiveOwnerCountsOps.directExecution owners) |]
        | JpDeclaredResumeSnapshotAlreadyAbsent -> "AlreadyAbsent"

    let jpRetireDeclaredResumeSnapshot continuationRef =
        let digest = JpWorkContinuationRefOps.digest continuationRef
        let liveOwners = jpDeclaredResumeSnapshotLiveOwnerCounts continuationRef
        let mutable removed = Unchecked.defaultof<JpDeclaredResumeSnapshotId>
        let retirement =
            if JpDeclaredResumeSnapshotLiveOwnerCountsOps.total liveOwners > 0 then
                JpDeclaredResumeSnapshotDeferredByLiveOwner liveOwners
            elif jp_declared_resume_snapshots.TryRemove(digest, &removed) then
                JpDeclaredResumeSnapshotRetired
            else
                JpDeclaredResumeSnapshotAlreadyAbsent
        match retirement with
        | JpDeclaredResumeSnapshotRetired ->
            let jobId = jpDeclaredResumeSnapshotJobId removed
            jpRememberDeclaredResumeSnapshotRetirementEvidence digest jobId JpDeclaredResumeSnapshotExplicitRetirement
            jpNoteDeclaredResumeEvidence jobId |> ignore
        | JpDeclaredResumeSnapshotDeferredByLiveOwner owners ->
            let occurrence, shouldEmit =
                DiagJson.sparseLogDecision
                    ("jp_declared_resume_snapshot_retirement_deferred_live_owner|" + CompilerIdentityKernel.ContentDigest.text digest)
                    64L
            if shouldEmit then
                DiagJson.emit (
                    FastRuntimeFormat.format
                        "{\"kind\":\"jp_declared_resume_snapshot_retirement_deferred_live_owner\",\"continuation_ref\":%s,\"queued_owner_count\":%d,\"active_owner_count\":%d,\"direct_execution_owner_count\":%d,\"occurrence_count\":%d,\"semantic_failure\":false,\"authority\":\"affine_resume_snapshot_live_owner_blocks_physical_retirement\",\"next\":\"allow_prune_or_job_teardown_after_all_live_owners_release\"}"
                        [| box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text digest))
                           box (JpDeclaredResumeSnapshotLiveOwnerCountsOps.queued owners)
                           box (JpDeclaredResumeSnapshotLiveOwnerCountsOps.active owners)
                           box (JpDeclaredResumeSnapshotLiveOwnerCountsOps.directExecution owners)
                           box occurrence |])
        | JpDeclaredResumeSnapshotAlreadyAbsent ->
            let occurrence, shouldEmit = DiagJson.sparseLogDecision "jp_declared_resume_snapshot_retirement_anomaly" 64L
            if shouldEmit then
                DiagJson.emit (
                    FastRuntimeFormat.format
                        "{\"kind\":\"jp_declared_resume_snapshot_retirement_anomaly\",\"continuation_ref\":%s,\"retirement_du\":%s,\"occurrence_count\":%d,\"authority\":\"affine_snapshot_remove_result_without_peval_execution_context\",\"next\":\"retain_yielded_parent_and_retire_exactly_once_after_success\"}"
                        [| box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text digest)); box (DiagJson.esc (jpDeclaredResumeSnapshotRetirementText retirement)); box occurrence |])

    let jpDeclaredResumeSnapshotLocator = function
        | JpDeclaredApplyResumeSnapshot(key, _) -> JpDeclaredApplyResumeLocator key
        | JpDeclaredLetResumeSnapshot(key, _) -> JpDeclaredLetResumeLocator key
        | JpDeclaredSequenceResumeSnapshot(key, _) -> JpDeclaredSequenceResumeLocator key
        | JpDeclaredBinaryNumericResumeSnapshot(key, _) -> JpDeclaredBinaryNumericResumeLocator key
        | JpDeclaredRecordTypeFoldBackResumeSnapshot(key, _) -> JpDeclaredRecordTypeFoldBackResumeLocator key

    let jpDeclaredResumeSnapshotKey = function
        | JpDeclaredApplyResumeSnapshot(key, _)
        | JpDeclaredLetResumeSnapshot(key, _)
        | JpDeclaredSequenceResumeSnapshot(key, _)
        | JpDeclaredBinaryNumericResumeSnapshot(key, _)
        | JpDeclaredRecordTypeFoldBackResumeSnapshot(key, _) -> key

    let jpInstallDeclaredResumeTarget jobId = function
        | Some continuationRef -> jp_declared_resume_targets.[jobId] <- continuationRef
        | None ->
            let mutable removed = Unchecked.defaultof<JpWorkContinuationRef>
            jp_declared_resume_targets.TryRemove(jobId, &removed) |> ignore

    let jpClearDeclaredResumeTarget jobId =
        let mutable removed = Unchecked.defaultof<JpWorkContinuationRef>
        jp_declared_resume_targets.TryRemove(jobId, &removed) |> ignore

    let jpTryDeclaredResumeSnapshotByRef continuationRef =
        let mutable snapshot = Unchecked.defaultof<JpDeclaredResumeSnapshotId>
        if jp_declared_resume_snapshots.TryGetValue(JpWorkContinuationRefOps.digest continuationRef, &snapshot) then Some snapshot
        else None

    let jpTryDeclaredResumeSnapshotRegistrationEvidence continuationRef =
        let digest = JpWorkContinuationRefOps.digest continuationRef
        let mutable evidence = Unchecked.defaultof<JpDeclaredResumeSnapshotRegistrationEvidence>
        if jp_declared_resume_snapshot_registration_evidence.TryGetValue(digest, &evidence) then
            Some(evidence.job_id, evidence.registration_revision, evidence.node_id)
        else None

    let jpDeclaredResumeProgressFingerprint continuationRef =
        // Snapshot identity is unique/affine; liveness identity is intentionally
        // ordinal-free. Position identity is derived from typed stage/cursor DUs,
        // never from diagnostic renderers whose spelling may change independently.
        let positionRefs = ResizeArray<CompilerIdentityKernel.ContentDigest>()
        let seen = System.Collections.Generic.HashSet<CompilerIdentityKernel.ContentDigest>()
        let mutable cursor = Some continuationRef
        while cursor.IsSome do
            let current = Option.get cursor
            let digest = JpWorkContinuationRefOps.digest current
            if not (seen.Add digest) then
                positionRefs.Add(
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-declared-resume-progress-cycle"
                        (CompilerIdentityKernel.ContentDigest.text digest))
                cursor <- None
            else
                match jpTryDeclaredResumeSnapshotByRef current with
                | None ->
                    positionRefs.Add(
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-declared-resume-progress-missing"
                            (CompilerIdentityKernel.ContentDigest.text digest))
                    cursor <- None
                | Some snapshot ->
                    let jobId, nodeId, parentPc =
                        match jpDeclaredResumeSnapshotKey snapshot with
                        | JpDeclaredEvaluatorPcKey(jobId, nodeId, parentPc) -> jobId, nodeId, parentPc
                    snapshot
                    |> jpDeclaredResumeProgressPositionOf
                    |> jpDeclaredResumeProgressPositionDigest jobId nodeId
                    |> positionRefs.Add
                    match parentPc with
                    | JpDeclaredEvaluatorRootPc -> cursor <- None
                    | JpDeclaredEvaluatorNestedPc parentContinuation -> cursor <- Some parentContinuation
                    | JpDeclaredEvaluatorTailBridgePc(parentContinuation, bridgePath, depthDelta) ->
                        positionRefs.Add(
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-declared-resume-progress-tail-bridge"
                                (JpWorkContinuationRefOps.text parentContinuation
                                 + "|path=" + jpDeclaredTailResultBridgePathText bridgePath
                                 + "|depth_delta=" + string depthDelta))
                        cursor <- Some parentContinuation
                    | JpDeclaredEvaluatorOpaquePc(nearestTypedParent, depthDelta) ->
                        let nearestText =
                            match nearestTypedParent with
                            | Some continuationRef -> JpWorkContinuationRefOps.text continuationRef
                            | None -> "root"
                        positionRefs.Add(
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-declared-resume-progress-opaque-parent"
                                (nearestText + "|depth_delta=" + string depthDelta))
                        cursor <- None
        positionRefs
        |> Seq.map CompilerIdentityKernel.ContentDigest.text
        |> String.concat ">"
        |> CompilerIdentityKernel.ContentDigest.ofText "jp-declared-resume-progress-position"

    let jpTryDeclaredResumeSnapshot jobId =
        let mutable target = Unchecked.defaultof<JpWorkContinuationRef>
        if jp_declared_resume_targets.TryGetValue(jobId, &target) then
            match jpTryDeclaredResumeSnapshotByRef target with
            | Some snapshot -> Some(target, snapshot)
            | None -> None
        else None

    let jpCurrentDeclaredParentEndpoint jobId =
        let executionRoots = jpCurrentDeclaredDirectResumeExecutionRoots ()
        match executionRoots with
        | [| continuationRef |] ->
            match jpTryDeclaredResumeSnapshotByRef continuationRef with
            | Some snapshot when jpDeclaredResumeSnapshotJobId snapshot = jobId ->
                JpDeclaredParentEndpointExecutionRoot continuationRef
            | _ -> JpDeclaredParentEndpointUnavailable
        | _ ->
            match jpTryDeclaredResumeSnapshot jobId with
            | Some(targetRef, snapshot) when jpDeclaredResumeSnapshotJobId snapshot = jobId ->
                JpDeclaredParentEndpointInstalledResumeTarget targetRef
            | _ -> JpDeclaredParentEndpointUnavailable

    // Pattern-miss deferral can happen after a direct mixed plan consumed its old
    // entry snapshot.  Requeue must not preserve that stale target when the current
    // attempt has already materialized a newer, explicitly safe continuation.
    // Require the checkpoint to be created after this attempt's starting checkpoint
    // ordinal and after its progress-clock start, so an older still-live checkpoint
    // cannot become backward replay even if two attempts share the same millisecond.
    // The checkpoint authority stores the typed continuation digest; no nearest-
    // snapshot search or ancestor/root replay is permitted here.
    let jpTryDeclaredCheckpointSafeResumeTarget jobId attemptCheckpointOrdinal attemptProgressStartedAtMs =
        let mutable checkpoint = Unchecked.defaultof<JpDeclaredBodyCheckpoint>
        if attemptProgressStartedAtMs > 0L
           && jp_declared_body_checkpoints.TryGetValue(jobId, &checkpoint)
           && checkpoint.checkpointOrdinal > attemptCheckpointOrdinal
           && checkpoint.capturedAtMs >= attemptProgressStartedAtMs then
            match checkpoint.resumePointAuthority with
            | JpDeclaredResumePointSafeContinuationSnapshot continuationDigest ->
                let continuationRef = JpWorkContinuationRefOps.create continuationDigest
                match jpTryDeclaredResumeSnapshotByRef continuationRef with
                | Some snapshot when jpDeclaredResumeSnapshotJobId snapshot = jobId -> Some continuationRef
                | _ -> None
            | JpDeclaredResumePointObservedPhase -> None
        else None

    let jpTryDeclaredStaleResumeTargetRebase jobId staleTarget =
        let mutable checkpoint = Unchecked.defaultof<JpDeclaredBodyCheckpoint>
        if jp_declared_body_checkpoints.TryGetValue(jobId, &checkpoint) then
            match checkpoint.resumePointAuthority with
            | JpDeclaredResumePointSafeContinuationSnapshot continuationDigest ->
                let checkpointRef = JpWorkContinuationRefOps.create continuationDigest
                match jpTryDeclaredResumeSnapshotByRef checkpointRef,
                      jpTryDeclaredResumeSnapshotRegistrationEvidence staleTarget,
                      jpTryDeclaredResumeSnapshotRegistrationEvidence checkpointRef with
                | Some checkpointSnapshot, Some(staleJobId, staleRevision, staleNodeId), Some(checkpointJobId, checkpointRevision, checkpointNodeId)
                    when jpDeclaredResumeSnapshotJobId checkpointSnapshot = jobId
                         && jpDeclaredResumeSnapshotNodeId checkpointSnapshot = checkpointNodeId
                         && staleJobId = jobId
                         && checkpointJobId = jobId
                         && staleNodeId = checkpointNodeId
                         && checkpointRevision > staleRevision ->
                    Some(checkpointRef, staleRevision, checkpointRevision, staleNodeId)
                | _ -> None
            | JpDeclaredResumePointObservedPhase -> None
        else None

    let jpDeclaredDeferredResumeTarget jobId attemptCheckpointOrdinal attemptProgressStartedAtMs currentTarget =
        match currentTarget with
        | Some continuationRef when Option.isSome (jpTryDeclaredResumeSnapshotByRef continuationRef) -> currentTarget
        | Some _ ->
            match jpTryDeclaredCheckpointSafeResumeTarget jobId attemptCheckpointOrdinal attemptProgressStartedAtMs with
            | Some continuationRef -> Some continuationRef
            | None -> currentTarget
        | None -> None

    type JpDeclaredResumeSpineId =
        | JpDeclaredResumeSpineRoot
        | JpDeclaredResumeSpineOpaque of nearestTypedParent:JpWorkContinuationRef option * termDepthDelta:int
        | JpDeclaredResumeSpineMissing of continuationRef:JpWorkContinuationRef
        | JpDeclaredResumeSpineCycle of continuationRef:JpWorkContinuationRef
        | JpDeclaredResumeSpineNode of continuationRef:JpWorkContinuationRef * locator:JpDeclaredResumeLocatorId * parent:JpDeclaredResumeSpineId

    let jpDeclaredResumeLocatorParentPc = function
        | JpDeclaredApplyResumeLocator (JpDeclaredEvaluatorPcKey(_, _, parentPc))
        | JpDeclaredLetResumeLocator (JpDeclaredEvaluatorPcKey(_, _, parentPc))
        | JpDeclaredSequenceResumeLocator (JpDeclaredEvaluatorPcKey(_, _, parentPc))
        | JpDeclaredBinaryNumericResumeLocator (JpDeclaredEvaluatorPcKey(_, _, parentPc))
        | JpDeclaredRecordTypeFoldBackResumeLocator (JpDeclaredEvaluatorPcKey(_, _, parentPc)) -> parentPc

    let jpBuildDeclaredResumeSpine continuationRef =
        let links = ResizeArray<JpWorkContinuationRef * JpDeclaredResumeLocatorId>()
        let seen = System.Collections.Generic.HashSet<CompilerIdentityKernel.ContentDigest>()
        let mutable cursor = Some continuationRef
        let mutable terminal = JpDeclaredResumeSpineRoot
        let mutable terminalText = "Root"
        while cursor.IsSome do
            let current = Option.get cursor
            let digest = JpWorkContinuationRefOps.digest current
            if not (seen.Add digest) then
                terminal <- JpDeclaredResumeSpineCycle current
                terminalText <- "Cycle"
                cursor <- None
            else
                let mutable snapshot = Unchecked.defaultof<JpDeclaredResumeSnapshotId>
                if jp_declared_resume_snapshots.TryGetValue(digest, &snapshot) then
                    let locator = jpDeclaredResumeSnapshotLocator snapshot
                    links.Add(current, locator)
                    match jpDeclaredResumeLocatorParentPc locator with
                    | JpDeclaredEvaluatorRootPc ->
                        terminal <- JpDeclaredResumeSpineRoot
                        terminalText <- "Root"
                        cursor <- None
                    | JpDeclaredEvaluatorNestedPc parentContinuation ->
                        cursor <- Some parentContinuation
                    | JpDeclaredEvaluatorTailBridgePc(parentContinuation, _, _) ->
                        cursor <- Some parentContinuation
                    | JpDeclaredEvaluatorOpaquePc(nearestTypedParent, depthDelta) ->
                        terminal <- JpDeclaredResumeSpineOpaque(nearestTypedParent, depthDelta)
                        terminalText <- "Opaque"
                        cursor <- None
                else
                    terminal <- JpDeclaredResumeSpineMissing current
                    terminalText <- "Missing"
                    cursor <- None
        let mutable spine = terminal
        for index = links.Count - 1 downto 0 do
            let linkContinuation, locator = links.[index]
            spine <- JpDeclaredResumeSpineNode(linkContinuation, locator, spine)
        spine, links.Count, terminalText

    [<Struct>]
    type JpDeclaredResumeSpineShapeId = private {
        applyCount : int
        letCount : int
        sequenceCount : int
        binaryNumericCount : int
        foldCount : int
    }

    let jpDeclaredResumeSpineShape (spine:JpDeclaredResumeSpineId) : JpDeclaredResumeSpineShapeId =
        let mutable applyCount = 0
        let mutable letCount = 0
        let mutable sequenceCount = 0
        let mutable binaryNumericCount = 0
        let mutable foldCount = 0
        let mutable cursor = Some spine
        while Option.isSome cursor do
            match Option.get cursor with
            | JpDeclaredResumeSpineNode(_, locator, parent) ->
                match locator with
                | JpDeclaredApplyResumeLocator _ -> applyCount <- applyCount + 1
                | JpDeclaredLetResumeLocator _ -> letCount <- letCount + 1
                | JpDeclaredSequenceResumeLocator _ -> sequenceCount <- sequenceCount + 1
                | JpDeclaredBinaryNumericResumeLocator _ -> binaryNumericCount <- binaryNumericCount + 1
                | JpDeclaredRecordTypeFoldBackResumeLocator _ -> foldCount <- foldCount + 1
                cursor <- Some parent
            | JpDeclaredResumeSpineRoot
            | JpDeclaredResumeSpineOpaque _
            | JpDeclaredResumeSpineMissing _
            | JpDeclaredResumeSpineCycle _ -> cursor <- None
        { applyCount = applyCount; letCount = letCount; sequenceCount = sequenceCount; binaryNumericCount = binaryNumericCount; foldCount = foldCount }

    let jpConsumeDeclaredResumeTarget jobId continuationRef =
        let mutable target = Unchecked.defaultof<JpWorkContinuationRef>
        if jp_declared_resume_targets.TryGetValue(jobId, &target)
           && JpWorkContinuationRefOps.digest target = JpWorkContinuationRefOps.digest continuationRef then
            jpClearDeclaredResumeTarget jobId

    type JpDeclaredApplyResumeStep = private {
        continuationRef : JpWorkContinuationRef
        nodeId : int
        continuation : JpDeclaredApplyContinuation
    }

    type JpDeclaredApplyResumePlan = private {
        applyTargetRef : JpWorkContinuationRef
        applySteps : JpDeclaredApplyResumeStep array
    }

    let jpTryBuildDeclaredApplyResumePlan (jobId:int64) : JpDeclaredApplyResumePlan option =
        match jpTryDeclaredResumeSnapshot jobId with
        | Some(targetRef, JpDeclaredApplyResumeSnapshot(_, continuation)) when jpDeclaredApplyStageCanSeed continuation.stage ->
            let steps = ResizeArray<JpDeclaredApplyResumeStep>()
            let seen = System.Collections.Generic.HashSet<CompilerIdentityKernel.ContentDigest>()
            let mutable cursor = Some targetRef
            let mutable valid = true
            let mutable reachedRoot = false
            while valid && Option.isSome cursor do
                let current = Option.get cursor
                let digest = JpWorkContinuationRefOps.digest current
                if not (seen.Add digest) then
                    valid <- false
                else
                    let mutable snapshot = Unchecked.defaultof<JpDeclaredResumeSnapshotId>
                    if jp_declared_resume_snapshots.TryGetValue(digest, &snapshot) then
                        match snapshot with
                        | JpDeclaredApplyResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, nodeId, parentPc), continuation)
                            when ownerJobId = jobId ->
                            steps.Add({ continuationRef = current; nodeId = nodeId; continuation = continuation })
                            match parentPc with
                            | JpDeclaredEvaluatorRootPc ->
                                reachedRoot <- true
                                cursor <- None
                            | JpDeclaredEvaluatorNestedPc parentContinuation ->
                                cursor <- Some parentContinuation
                            | JpDeclaredEvaluatorTailBridgePc(parentContinuation, _, _) ->
                                cursor <- Some parentContinuation
                            | JpDeclaredEvaluatorOpaquePc _ ->
                                valid <- false
                                cursor <- None
                        | _ -> valid <- false
                    else
                        valid <- false
            if valid && reachedRoot && steps.Count > 0 then
                Some { applyTargetRef = targetRef; applySteps = steps.ToArray() }
            else None
        | _ -> None

    type JpDeclaredLetResumeStep = private {
        continuationRef : JpWorkContinuationRef
        nodeId : int
        continuation : JpDeclaredLetContinuation
    }

    type JpDeclaredSequenceResumeStep = private {
        continuationRef : JpWorkContinuationRef
        nodeId : int
        continuation : JpDeclaredSequenceContinuation
    }

    type JpDeclaredBinaryNumericResumeStep = private {
        continuationRef : JpWorkContinuationRef
        nodeId : int
        continuation : JpDeclaredBinaryNumericContinuation
    }

    type JpDeclaredFoldResumeStep = private {
        continuationRef : JpWorkContinuationRef
        nodeId : int
        continuation : JpDeclaredRecordTypeFoldBackContinuation
        resultAcceptor : JpDeclaredDataResultAcceptorId
    }

    type JpDeclaredDirectResumeSnapshotSupportId =
        | JpDeclaredDirectResumeSupportedApply
        | JpDeclaredDirectResumeSupportedLet
        | JpDeclaredDirectResumeSupportedSequence
        | JpDeclaredDirectResumeSupportedFoldData of JpDeclaredDataResultAcceptorId
        | JpDeclaredDirectResumeNeedsDataCarrier of JpDeclaredDataResultAcceptorId
        | JpDeclaredDirectResumeNeedsFoldRecordTypeCarrier
        | JpDeclaredDirectResumeLetCheckpointCursorOnly

    let jpDeclaredDirectResumeSnapshotSupport (snapshot:JpDeclaredResumeSnapshotId) : JpDeclaredDirectResumeSnapshotSupportId =
        match snapshot with
        | JpDeclaredApplyResumeSnapshot(_, continuation) ->
            match jpDeclaredApplySeedCapability continuation.stage with
            | JpDeclaredApplySeedReplayable -> JpDeclaredDirectResumeSupportedApply
            | JpDeclaredApplySeedNeedsDataCarrier acceptor -> JpDeclaredDirectResumeNeedsDataCarrier acceptor
        | JpDeclaredLetResumeSnapshot(_, continuation) ->
            match continuation.stage with
            | JpDeclaredLetBindingPending -> JpDeclaredDirectResumeNeedsDataCarrier JpDeclaredLetBindingResultAcceptor
            | JpDeclaredLetBodyPending -> JpDeclaredDirectResumeSupportedLet
            | JpDeclaredLetCheckpointReady -> JpDeclaredDirectResumeLetCheckpointCursorOnly
        | JpDeclaredSequenceResumeSnapshot(_, continuation) ->
            match continuation.stage with
            | JpDeclaredSequenceFirstPending _ -> JpDeclaredDirectResumeNeedsDataCarrier JpDeclaredSequenceFirstResultAcceptor
            | JpDeclaredSequenceTailPending -> JpDeclaredDirectResumeSupportedSequence
        | JpDeclaredBinaryNumericResumeSnapshot(_, continuation) ->
            match continuation.stage with
            | JpDeclaredBinaryNumericLeftPending -> JpDeclaredDirectResumeNeedsDataCarrier JpDeclaredBinaryNumericLeftResultAcceptor
            | JpDeclaredBinaryNumericRightPending _ -> JpDeclaredDirectResumeNeedsDataCarrier JpDeclaredBinaryNumericRightResultAcceptor
        | JpDeclaredRecordTypeFoldBackResumeSnapshot(_, continuation) ->
            match continuation.state with
            | JpDeclaredRecordTypeFoldBackFolderPending _ -> JpDeclaredDirectResumeSupportedFoldData JpDeclaredFoldFolderResultAcceptor
            | JpDeclaredRecordTypeFoldBackInitialStatePending _ -> JpDeclaredDirectResumeSupportedFoldData JpDeclaredFoldInitialStateResultAcceptor
            | JpDeclaredRecordTypeFoldBackRecordTypePending _ -> JpDeclaredDirectResumeNeedsFoldRecordTypeCarrier
            | JpDeclaredRecordTypeFoldBackFieldPending _ -> JpDeclaredDirectResumeSupportedFoldData JpDeclaredFoldKeyApplyResultAcceptor
            | JpDeclaredRecordTypeFoldBackKeyApplied _ -> JpDeclaredDirectResumeSupportedFoldData JpDeclaredFoldTypeApplyResultAcceptor
            | JpDeclaredRecordTypeFoldBackTypeApplied _ -> JpDeclaredDirectResumeSupportedFoldData JpDeclaredFoldStateApplyResultAcceptor

    type JpDeclaredDirectResumeSeedId =
        | JpDeclaredApplyBeforeArgumentResumeSeed
        | JpDeclaredLetBodyResumeSeed
        | JpDeclaredSequenceTailResumeSeed
        | JpDeclaredFoldDataResumeSeed of JpDeclaredDataResultAcceptorId

    let jpDeclaredDirectResumeSeedText = function
        | JpDeclaredApplyBeforeArgumentResumeSeed -> "ApplyBeforeArgument"
        | JpDeclaredLetBodyResumeSeed -> "LetBody"
        | JpDeclaredSequenceTailResumeSeed -> "SequenceTail"
        | JpDeclaredFoldDataResumeSeed acceptor -> "FoldData(" + jpDeclaredDataResultAcceptorText acceptor + ")"

    let jpDeclaredDirectResumeSeed = function
        | JpDeclaredApplyResumeSnapshot(_, continuation) ->
            match jpDeclaredApplySeedCapability continuation.stage with
            | JpDeclaredApplySeedReplayable -> Some JpDeclaredApplyBeforeArgumentResumeSeed
            | JpDeclaredApplySeedNeedsDataCarrier _ -> None
        | JpDeclaredLetResumeSnapshot(_, continuation) ->
            match continuation.stage with
            | JpDeclaredLetBindingPending
            | JpDeclaredLetCheckpointReady -> None
            | JpDeclaredLetBodyPending -> Some JpDeclaredLetBodyResumeSeed
        | JpDeclaredSequenceResumeSnapshot(_, continuation) ->
            match continuation.stage with
            | JpDeclaredSequenceFirstPending _ -> None
            | JpDeclaredSequenceTailPending -> Some JpDeclaredSequenceTailResumeSeed
        | JpDeclaredBinaryNumericResumeSnapshot(_, continuation) ->
            match continuation.stage with
            | JpDeclaredBinaryNumericLeftPending
            | JpDeclaredBinaryNumericRightPending _ -> None
        | JpDeclaredRecordTypeFoldBackResumeSnapshot _ as snapshot ->
            match jpDeclaredResumeSnapshotResultChannel snapshot with
            | JpDeclaredResumeDataResult acceptor -> Some (JpDeclaredFoldDataResumeSeed acceptor)
            | _ -> None

    let jpDeclaredDirectResumeCanEnterMixedPlan snapshot =
        match jpDeclaredDirectResumeSeed snapshot, jpDeclaredDirectResumeSnapshotSupport snapshot with
        | Some _, _
        | None, JpDeclaredDirectResumeLetCheckpointCursorOnly
        | None, JpDeclaredDirectResumeNeedsDataCarrier _
        | None, JpDeclaredDirectResumeSupportedFoldData _ -> true
        | None, _ -> false

    let jpDeclaredResumeSnapshotParentPc snapshot =
        match jpDeclaredResumeSnapshotKey snapshot with
        | JpDeclaredEvaluatorPcKey(_, _, parentPc) -> parentPc

    let jpDeclaredResumeSnapshotHasDirectRootRoute (jobId:int64) = function
        | JpDeclaredLetResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, _, JpDeclaredEvaluatorRootPc), continuation)
            when ownerJobId = jobId ->
            match continuation.stage with
            | JpDeclaredLetBindingPending
            | JpDeclaredLetCheckpointReady -> false
            | JpDeclaredLetBodyPending -> true
        | JpDeclaredSequenceResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, _, JpDeclaredEvaluatorRootPc), continuation)
            when ownerJobId = jobId ->
            match continuation.stage with
            | JpDeclaredSequenceFirstPending _ -> false
            | JpDeclaredSequenceTailPending -> true
        | JpDeclaredBinaryNumericResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, _, JpDeclaredEvaluatorRootPc), _)
            when ownerJobId = jobId -> false
        | JpDeclaredRecordTypeFoldBackResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, _, JpDeclaredEvaluatorRootPc), _)
            when ownerJobId = jobId -> true
        | _ -> false

    // A data-carrier continuation is a consumer, not a replay seed.  Producer ownership
    // is recovered by following the inverse typed parent relation: a child snapshot whose
    // parentPc names the consumer is the computation that can produce the missing Data.
    // Ownership edges are preserved: Nested and TailBridge are executable topology.
    // Opaque is only lineage evidence until a dedicated carrier bridge proves value preservation.
    type JpDeclaredDataCarrierOwnershipEdge =
        | JpDeclaredDataCarrierNestedEdge
        | JpDeclaredDataCarrierTailBridgeEdge of bridgePath:JpDeclaredTailResultBridgePath * termDepthDelta:int
        | JpDeclaredDataCarrierOpaqueEdge of termDepthDelta:int

    type JpDeclaredDataCarrierOwnershipPath =
        | JpDeclaredDataCarrierConsumer of JpWorkContinuationRef
        | JpDeclaredDataCarrierProducerChild of parent:JpDeclaredDataCarrierOwnershipPath * child:JpWorkContinuationRef * edge:JpDeclaredDataCarrierOwnershipEdge

    type JpDeclaredDataCarrierProducerProof = private {
        requestedConsumerRef : JpWorkContinuationRef
        resultAcceptor : JpDeclaredDataResultAcceptorId
        producerSeedRef : JpWorkContinuationRef
        producerSeed : JpDeclaredDirectResumeSeedId
        ownershipPath : JpDeclaredDataCarrierOwnershipPath
        producerDepth : int
        opaqueBridgeCount : int
        maxOpaqueDepth : int
    }

    type JpDeclaredDataCarrierProducerResolution =
        | JpDeclaredDataCarrierProducerResolved of JpDeclaredDataCarrierProducerProof
        | JpDeclaredDataCarrierProducerMissing of consumer:JpWorkContinuationRef * acceptor:JpDeclaredDataResultAcceptorId
        | JpDeclaredDataCarrierProducerAmbiguous of consumer:JpWorkContinuationRef * acceptor:JpDeclaredDataResultAcceptorId * producerRefs:JpWorkContinuationRef list

    let jpDeclaredDataCarrierOwnershipEdgeText = function
        | JpDeclaredDataCarrierNestedEdge -> "Nested"
        | JpDeclaredDataCarrierTailBridgeEdge(bridgePath, depth) ->
            "TailBridge(path=" + jpDeclaredTailResultBridgePathText bridgePath + "|depth=" + string depth + ")"
        | JpDeclaredDataCarrierOpaqueEdge depth -> $"Opaque(depth={depth})"

    let jpDeclaredDataCarrierOwnershipPathText path =
        let refs = ResizeArray<string>()
        let mutable cursor = Some path
        while Option.isSome cursor do
            match Option.get cursor with
            | JpDeclaredDataCarrierConsumer continuationRef ->
                refs.Add(JpWorkContinuationRefOps.text continuationRef)
                cursor <- None
            | JpDeclaredDataCarrierProducerChild(parent, child, edge) ->
                refs.Add($"{JpWorkContinuationRefOps.text child}[{jpDeclaredDataCarrierOwnershipEdgeText edge}]")
                cursor <- Some parent
        refs |> Seq.rev |> String.concat "->"

    let jpDeclaredDataCarrierOwnershipOpaqueSummary path =
        let mutable bridgeCount = 0
        let mutable maxDepth = 0
        let mutable cursor = Some path
        while Option.isSome cursor do
            match Option.get cursor with
            | JpDeclaredDataCarrierConsumer _ -> cursor <- None
            | JpDeclaredDataCarrierProducerChild(parent, _, JpDeclaredDataCarrierNestedEdge)
            | JpDeclaredDataCarrierProducerChild(parent, _, JpDeclaredDataCarrierTailBridgeEdge _) ->
                cursor <- Some parent
            | JpDeclaredDataCarrierProducerChild(parent, _, JpDeclaredDataCarrierOpaqueEdge depth) ->
                bridgeCount <- bridgeCount + 1
                maxDepth <- max maxDepth depth
                cursor <- Some parent
        bridgeCount, maxDepth

    let jpDeclaredDataCarrierOwnershipPathCurrentRef = function
        | JpDeclaredDataCarrierConsumer continuationRef -> continuationRef
        | JpDeclaredDataCarrierProducerChild(_, childRef, _) -> childRef

    let jpDeclaredDataCarrierOwnershipFirstOpaqueParentRef path =
        let mutable current = path
        let mutable result = None
        let mutable completed = false
        while not completed do
            match current with
            | JpDeclaredDataCarrierConsumer _ -> completed <- true
            | JpDeclaredDataCarrierProducerChild(parentPath, _, JpDeclaredDataCarrierOpaqueEdge _) ->
                result <- Some (jpDeclaredDataCarrierOwnershipPathCurrentRef parentPath)
                completed <- true
            | JpDeclaredDataCarrierProducerChild(parentPath, _, _) -> current <- parentPath
        result

    type JpDeclaredTypedOpaqueCarrierRelationId =
        | JpDeclaredOpaqueApplyDispatchIdentityRelation
        | JpDeclaredOpaqueApplyDispatchToApplyArgumentRelation
        | JpDeclaredOpaqueApplyDispatchToLetBindingRelation
        | JpDeclaredOpaqueApplyDispatchToLetBodyRelation
        | JpDeclaredOpaqueLetBodyToApplyArgumentRelation
        | JpDeclaredOpaqueLetBodyToApplyDispatchRelation
        | JpDeclaredOpaqueLetBodyToLetBindingRelation
        | JpDeclaredOpaqueLetBodyToLetBodyRelation

    let jpDeclaredTypedOpaqueCarrierRelationText = function
        | JpDeclaredOpaqueApplyDispatchIdentityRelation -> "ApplyDispatchResult<-Apply/Data(ApplyDispatchResult)"
        | JpDeclaredOpaqueApplyDispatchToApplyArgumentRelation -> "ApplyArgumentResult<-Apply/Data(ApplyDispatchResult)"
        | JpDeclaredOpaqueApplyDispatchToLetBindingRelation -> "LetBindingResult<-Apply/Data(ApplyDispatchResult)"
        | JpDeclaredOpaqueApplyDispatchToLetBodyRelation -> "LetBodyResult<-Apply/Data(ApplyDispatchResult)"
        | JpDeclaredOpaqueLetBodyToApplyArgumentRelation -> "ApplyArgumentResult<-Let/Data(LetBodyResult)"
        | JpDeclaredOpaqueLetBodyToApplyDispatchRelation -> "ApplyDispatchResult<-Let/Data(LetBodyResult)"
        | JpDeclaredOpaqueLetBodyToLetBindingRelation -> "LetBindingResult<-Let/Data(LetBodyResult)"
        | JpDeclaredOpaqueLetBodyToLetBodyRelation -> "LetBodyResult<-Let/Data(LetBodyResult)"

    type JpDeclaredDataCarrierTransportWitness =
        | JpDeclaredNestedOrTailCarrierTransport
        | JpDeclaredExactOpaqueCarrierTransport of JpDeclaredTypedOpaqueCarrierRelationId

    let jpDeclaredDataCarrierTransportWitnessText = function
        | JpDeclaredNestedOrTailCarrierTransport -> "nested_or_tail_bridge"
        | JpDeclaredExactOpaqueCarrierTransport relation ->
            "exact_typed_opaque_bridge(" + jpDeclaredTypedOpaqueCarrierRelationText relation + ")"

    // A resume snapshot names the Data value it currently accepts.  Executing a
    // complete Apply or Let continuation, however, produces the expression result
    // that is handed to its outer typed continuation.  Keep those two roles separate:
    // opaque traversal is authorized only by a closed produced-result -> acceptor relation.
    type JpDeclaredCarrierProducedChannelId =
        | JpDeclaredCarrierProducedApplyDispatch
        | JpDeclaredCarrierProducedLetBody
        | JpDeclaredCarrierProducedNotYetModeled

    let jpDeclaredCarrierProducedChannelForSeed = function
        | JpDeclaredApplyBeforeArgumentResumeSeed -> JpDeclaredCarrierProducedApplyDispatch
        | JpDeclaredLetBodyResumeSeed -> JpDeclaredCarrierProducedLetBody
        | JpDeclaredSequenceTailResumeSeed -> JpDeclaredCarrierProducedNotYetModeled
        | JpDeclaredFoldDataResumeSeed _ -> JpDeclaredCarrierProducedNotYetModeled

    // Once a typed continuation is resumed with its direct child Data, these are
    // the result channels its expression can hand to an outer continuation.
    let jpDeclaredCarrierProducedChannelAfterResumeSnapshot = function
        | JpDeclaredApplyResumeSnapshot _ -> JpDeclaredCarrierProducedApplyDispatch
        | JpDeclaredLetResumeSnapshot _ -> JpDeclaredCarrierProducedLetBody
        | JpDeclaredSequenceResumeSnapshot _
        | JpDeclaredBinaryNumericResumeSnapshot _
        | JpDeclaredRecordTypeFoldBackResumeSnapshot _ -> JpDeclaredCarrierProducedNotYetModeled

    let jpDeclaredTypedOpaqueCarrierRelationForChannels producedChannel consumerAcceptor =
        match producedChannel, consumerAcceptor with
        | JpDeclaredCarrierProducedApplyDispatch, JpDeclaredApplyDispatchResultAcceptor ->
            Some JpDeclaredOpaqueApplyDispatchIdentityRelation
        | JpDeclaredCarrierProducedApplyDispatch, JpDeclaredApplyArgumentResultAcceptor ->
            Some JpDeclaredOpaqueApplyDispatchToApplyArgumentRelation
        | JpDeclaredCarrierProducedApplyDispatch, JpDeclaredLetBindingResultAcceptor ->
            Some JpDeclaredOpaqueApplyDispatchToLetBindingRelation
        | JpDeclaredCarrierProducedApplyDispatch, JpDeclaredLetBodyResultAcceptor ->
            Some JpDeclaredOpaqueApplyDispatchToLetBodyRelation
        | JpDeclaredCarrierProducedLetBody, JpDeclaredApplyArgumentResultAcceptor ->
            Some JpDeclaredOpaqueLetBodyToApplyArgumentRelation
        | JpDeclaredCarrierProducedLetBody, JpDeclaredApplyDispatchResultAcceptor ->
            Some JpDeclaredOpaqueLetBodyToApplyDispatchRelation
        | JpDeclaredCarrierProducedLetBody, JpDeclaredLetBindingResultAcceptor ->
            Some JpDeclaredOpaqueLetBodyToLetBindingRelation
        | JpDeclaredCarrierProducedLetBody, JpDeclaredLetBodyResultAcceptor ->
            Some JpDeclaredOpaqueLetBodyToLetBodyRelation
        | _ -> None

    let jpDeclaredTypedOpaqueCarrierRelationForProducedChannel producedChannel consumerSnapshot =
        match jpDeclaredResumeSnapshotResultChannel consumerSnapshot with
        | JpDeclaredResumeDataResult consumerAcceptor ->
            jpDeclaredTypedOpaqueCarrierRelationForChannels producedChannel consumerAcceptor
        | _ -> None

    // One typed helper owns snapshot-edge directionality everywhere a resumed child
    // crosses an opaque parent: child snapshot = producer, parent snapshot = consumer.
    let jpDeclaredTypedOpaqueCarrierRelationForSnapshotEdge childSnapshot parentSnapshot =
        jpDeclaredTypedOpaqueCarrierRelationForProducedChannel
            (jpDeclaredCarrierProducedChannelAfterResumeSnapshot childSnapshot)
            parentSnapshot

    type JpDeclaredOpaqueCarrierRelationConformanceReceipt = private {
        applyDispatchIdentity : bool
        applyDispatchToApplyArgument : bool
        applyDispatchToLetBinding : bool
        applyDispatchToLetBody : bool
        letBodyToApplyArgument : bool
        letBodyToApplyDispatch : bool
        letBodyToLetBinding : bool
        letBodyToLetBody : bool
        keepsUnprovenLetBodyToLetBodyClosed : bool
        allPassed : bool
    }

    let jpDeclaredOpaqueCarrierRelationConformanceReceipt () =
        let relation produced consumer =
            jpDeclaredTypedOpaqueCarrierRelationForChannels produced consumer
        let applyDispatchIdentity =
            relation JpDeclaredCarrierProducedApplyDispatch JpDeclaredApplyDispatchResultAcceptor = Some JpDeclaredOpaqueApplyDispatchIdentityRelation
        let applyDispatchToApplyArgument =
            relation JpDeclaredCarrierProducedApplyDispatch JpDeclaredApplyArgumentResultAcceptor = Some JpDeclaredOpaqueApplyDispatchToApplyArgumentRelation
        let applyDispatchToLetBinding =
            relation JpDeclaredCarrierProducedApplyDispatch JpDeclaredLetBindingResultAcceptor = Some JpDeclaredOpaqueApplyDispatchToLetBindingRelation
        let applyDispatchToLetBody =
            relation JpDeclaredCarrierProducedApplyDispatch JpDeclaredLetBodyResultAcceptor = Some JpDeclaredOpaqueApplyDispatchToLetBodyRelation
        let letBodyToApplyArgument =
            relation JpDeclaredCarrierProducedLetBody JpDeclaredApplyArgumentResultAcceptor = Some JpDeclaredOpaqueLetBodyToApplyArgumentRelation
        let letBodyToApplyDispatch =
            relation JpDeclaredCarrierProducedLetBody JpDeclaredApplyDispatchResultAcceptor = Some JpDeclaredOpaqueLetBodyToApplyDispatchRelation
        let letBodyToLetBinding =
            relation JpDeclaredCarrierProducedLetBody JpDeclaredLetBindingResultAcceptor = Some JpDeclaredOpaqueLetBodyToLetBindingRelation
        let letBodyToLetBody =
            relation JpDeclaredCarrierProducedLetBody JpDeclaredLetBodyResultAcceptor = Some JpDeclaredOpaqueLetBodyToLetBodyRelation
        // Retain the former diagnostic field for telemetry compatibility. The 2879
        // workload proved this relation necessary, so conformant policy expects it false.
        let keepsUnprovenLetBodyToLetBodyClosed =
            relation JpDeclaredCarrierProducedLetBody JpDeclaredLetBodyResultAcceptor = None
        { applyDispatchIdentity = applyDispatchIdentity
          applyDispatchToApplyArgument = applyDispatchToApplyArgument
          applyDispatchToLetBinding = applyDispatchToLetBinding
          applyDispatchToLetBody = applyDispatchToLetBody
          letBodyToApplyArgument = letBodyToApplyArgument
          letBodyToApplyDispatch = letBodyToApplyDispatch
          letBodyToLetBinding = letBodyToLetBinding
          letBodyToLetBody = letBodyToLetBody
          keepsUnprovenLetBodyToLetBodyClosed = keepsUnprovenLetBodyToLetBodyClosed
          allPassed =
            applyDispatchIdentity
            && applyDispatchToApplyArgument
            && applyDispatchToLetBinding
            && applyDispatchToLetBody
            && letBodyToApplyArgument
            && letBodyToApplyDispatch
            && letBodyToLetBinding
            && letBodyToLetBody
            && not keepsUnprovenLetBodyToLetBodyClosed }

    type JpDeclaredTypedOpaqueBridgeDepthId =
        | JpDeclaredTypedOpaqueBridgeObservedDepth of int

    let jpDeclaredTryTypedOpaqueBridgeDepth _relation depth =
        // Opaque depth is evidence about how far the nearest typed parent was
        // when the snapshot was taken; it is not a program-specific capability.
        // Authority comes from closed producer->consumer relations on every opaque
        // ownership edge and live typed endpoints. Keeping the observed
        // depth in the witness preserves diagnostics without whitelisting a depth
        // learned from any particular source program.
        if depth > 0 then Some (JpDeclaredTypedOpaqueBridgeObservedDepth depth)
        else None

    let jpDeclaredDataCarrierTypedOpaqueBridgeRelations (proof:JpDeclaredDataCarrierProducerProof) =
        if proof.opaqueBridgeCount <= 0 then None
        else
            // Opaque transport is compositional: the number of opaque edges is evidence,
            // never a whitelist. Admission requires every opaque ownership edge to have
            // live typed endpoints and a closed producer-result -> consumer-acceptor
            // relation. The mixed planner still revalidates each edge while executing the
            // spine, so this proof cannot authorize a later unrelated opaque boundary.
            let relations = ResizeArray<JpDeclaredTypedOpaqueCarrierRelationId>()
            let rec walk path =
                match path with
                | JpDeclaredDataCarrierConsumer _ -> true
                | JpDeclaredDataCarrierProducerChild(parentPath, childRef, JpDeclaredDataCarrierOpaqueEdge depth) ->
                    let parentRef = jpDeclaredDataCarrierOwnershipPathCurrentRef parentPath
                    match jpTryDeclaredResumeSnapshotByRef childRef, jpTryDeclaredResumeSnapshotByRef parentRef with
                    | Some childSnapshot, Some parentSnapshot ->
                        match jpDeclaredTypedOpaqueCarrierRelationForSnapshotEdge childSnapshot parentSnapshot with
                        | Some relation when Option.isSome (jpDeclaredTryTypedOpaqueBridgeDepth relation depth) ->
                            relations.Add relation
                            walk parentPath
                        | _ -> false
                    | _ -> false
                | JpDeclaredDataCarrierProducerChild(parentPath, _, _) -> walk parentPath
            let allOpaqueEdgesProven = walk proof.ownershipPath
            if allOpaqueEdgesProven && relations.Count = proof.opaqueBridgeCount && relations.Count > 0 then
                Some (relations.ToArray())
            else None

    let jpDeclaredDataCarrierExactTypedOpaqueBridgeRelation (proof:JpDeclaredDataCarrierProducerProof) =
        match jpDeclaredDataCarrierTypedOpaqueBridgeRelations proof with
        | Some relations when relations.Length > 0 -> Some relations.[0]
        | _ -> None

    // A directly executable target seed may itself sit behind one opaque evaluator
    // frame.  The seed's produced channel, not its awaited input channel, decides
    // whether the parent can consume the value after the seed runs exactly once.
    let jpDeclaredTargetSeedExactTypedOpaqueBridgeRelation (targetSnapshot:JpDeclaredResumeSnapshotId) =
        match jpDeclaredDirectResumeSeed targetSnapshot, jpDeclaredResumeSnapshotParentPc targetSnapshot with
        | Some seed, JpDeclaredEvaluatorOpaquePc(Some parentRef, depth) ->
            match jpTryDeclaredResumeSnapshotByRef parentRef with
            | Some parentSnapshot ->
                match
                    seed
                    |> jpDeclaredCarrierProducedChannelForSeed
                    |> fun producedChannel -> jpDeclaredTypedOpaqueCarrierRelationForProducedChannel producedChannel parentSnapshot
                with
                | Some relation when Option.isSome (jpDeclaredTryTypedOpaqueBridgeDepth relation depth) -> Some relation
                | _ -> None
            | None -> None
        | _ -> None

    let jpResolveDeclaredDataCarrierProducer
        (jobId:int64)
        (consumerRef:JpWorkContinuationRef)
        (acceptor:JpDeclaredDataResultAcceptorId)
        : JpDeclaredDataCarrierProducerResolution =
        let childrenByParent =
            System.Collections.Generic.Dictionary<CompilerIdentityKernel.ContentDigest,ResizeArray<JpWorkContinuationRef * JpDeclaredResumeSnapshotId * JpDeclaredDataCarrierOwnershipEdge>>()
        let addChild parentRef childRef snapshot edge =
            let parentDigest = JpWorkContinuationRefOps.digest parentRef
            let mutable children = Unchecked.defaultof<ResizeArray<JpWorkContinuationRef * JpDeclaredResumeSnapshotId * JpDeclaredDataCarrierOwnershipEdge>>
            if not (childrenByParent.TryGetValue(parentDigest, &children)) then
                children <- ResizeArray<JpWorkContinuationRef * JpDeclaredResumeSnapshotId * JpDeclaredDataCarrierOwnershipEdge>()
                childrenByParent.[parentDigest] <- children
            children.Add((childRef, snapshot, edge))
        for entry in jp_declared_resume_snapshots do
            let snapshot = entry.Value
            let childRef = JpWorkContinuationRefOps.create entry.Key
            match jpDeclaredResumeSnapshotKey snapshot with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, JpDeclaredEvaluatorNestedPc parentRef) when ownerJobId = jobId ->
                addChild parentRef childRef snapshot JpDeclaredDataCarrierNestedEdge
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, JpDeclaredEvaluatorTailBridgePc(parentRef, bridgePath, depthDelta)) when ownerJobId = jobId ->
                addChild parentRef childRef snapshot (JpDeclaredDataCarrierTailBridgeEdge(bridgePath, depthDelta))
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, JpDeclaredEvaluatorOpaquePc(Some parentRef, depthDelta)) when ownerJobId = jobId ->
                addChild parentRef childRef snapshot (JpDeclaredDataCarrierOpaqueEdge depthDelta)
            | _ -> ()
        let candidates = ResizeArray<JpDeclaredDataCarrierProducerProof>()
        let stack = System.Collections.Generic.Stack<JpWorkContinuationRef * JpDeclaredDataCarrierOwnershipPath * int>()
        stack.Push((consumerRef, JpDeclaredDataCarrierConsumer consumerRef, 0))
        let seen = System.Collections.Generic.HashSet<CompilerIdentityKernel.ContentDigest>()
        while stack.Count > 0 do
            let currentConsumer, currentPath, currentDepth = stack.Pop()
            let currentDigest = JpWorkContinuationRefOps.digest currentConsumer
            if seen.Add currentDigest then
                let mutable children = Unchecked.defaultof<ResizeArray<JpWorkContinuationRef * JpDeclaredResumeSnapshotId * JpDeclaredDataCarrierOwnershipEdge>>
                if childrenByParent.TryGetValue(currentDigest, &children) then
                    for childRef, childSnapshot, edge in children do
                        let childPath = JpDeclaredDataCarrierProducerChild(currentPath, childRef, edge)
                        match jpDeclaredDirectResumeSeed childSnapshot with
                        | Some producerSeed ->
                            let opaqueBridgeCount, maxOpaqueDepth = jpDeclaredDataCarrierOwnershipOpaqueSummary childPath
                            candidates.Add {
                                requestedConsumerRef = consumerRef
                                resultAcceptor = acceptor
                                producerSeedRef = childRef
                                producerSeed = producerSeed
                                ownershipPath = childPath
                                producerDepth = currentDepth + 1
                                opaqueBridgeCount = opaqueBridgeCount
                                maxOpaqueDepth = maxOpaqueDepth
                            }
                        | None ->
                            match jpDeclaredDirectResumeSnapshotSupport childSnapshot with
                            | JpDeclaredDirectResumeNeedsDataCarrier _
                            | JpDeclaredDirectResumeSupportedFoldData _ ->
                                stack.Push((childRef, childPath, currentDepth + 1))
                            | JpDeclaredDirectResumeSupportedApply
                            | JpDeclaredDirectResumeSupportedLet
                            | JpDeclaredDirectResumeSupportedSequence
                            | JpDeclaredDirectResumeNeedsFoldRecordTypeCarrier
                            | JpDeclaredDirectResumeLetCheckpointCursorOnly -> ()
        match candidates.Count with
        | 0 -> JpDeclaredDataCarrierProducerMissing(consumerRef, acceptor)
        | 1 -> JpDeclaredDataCarrierProducerResolved candidates.[0]
        | _ ->
            let producerRefs =
                candidates
                |> Seq.map (fun proof -> proof.producerSeedRef)
                |> Seq.sortBy JpWorkContinuationRefOps.text
                |> Seq.toList
            JpDeclaredDataCarrierProducerAmbiguous(consumerRef, acceptor, producerRefs)

    type JpDeclaredMixedResumeEntryAuthority =
        | JpDeclaredMixedResumeTargetSeed of JpDeclaredDataCarrierTransportWitness option
        | JpDeclaredMixedResumeTargetCursor
        | JpDeclaredMixedResumeDataCarrierProducer of JpDeclaredDataCarrierProducerProof * JpDeclaredDataCarrierTransportWitness

    let jpDeclaredMixedResumeEntryAuthorityText = function
        | JpDeclaredMixedResumeTargetSeed transportWitness ->
            match transportWitness with
            | Some witness -> "TargetSeed(transport=" + jpDeclaredDataCarrierTransportWitnessText witness + ")"
            | None -> "TargetSeed"
        | JpDeclaredMixedResumeTargetCursor -> "TargetCursor"
        | JpDeclaredMixedResumeDataCarrierProducer(proof, transportWitness) ->
            "DataCarrierProducer(acceptor=" + jpDeclaredDataResultAcceptorText proof.resultAcceptor
            + "|depth=" + string proof.producerDepth
            + "|opaque_bridges=" + string proof.opaqueBridgeCount
            + "|max_opaque_depth=" + string proof.maxOpaqueDepth
            + "|path=" + jpDeclaredDataCarrierOwnershipPathText proof.ownershipPath
            + "|transport=" + jpDeclaredDataCarrierTransportWitnessText transportWitness
            + ")"

    type JpDeclaredMixedResumeEntryPoint =
        | JpDeclaredMixedResumeDataSeed of JpDeclaredDirectResumeSeedId
        | JpDeclaredMixedResumeLetCheckpointCursor

    let jpDeclaredMixedResumeEntryPointText = function
        | JpDeclaredMixedResumeDataSeed seed -> "DataSeed(" + jpDeclaredDirectResumeSeedText seed + ")"
        | JpDeclaredMixedResumeLetCheckpointCursor -> "LetCheckpointCursor"

    type JpDeclaredMixedResumeStep =
        // Apply child-result continuations are carrier consumers; replayable Apply is entry-only.
        | JpDeclaredMixedApplyCarrierStep of JpDeclaredApplyResumeStep
        | JpDeclaredMixedApplyStep of JpDeclaredApplyResumeStep
        // BindingPending is a carrier-consuming relation, not a replayable Let seed.
        // Keeping it distinct prevents an index convention from becoming execution authority.
        | JpDeclaredMixedLetBindingCarrierStep of JpDeclaredLetResumeStep
        | JpDeclaredMixedLetStep of JpDeclaredLetResumeStep
        // Sequence first/tail states preserve whether an intermediate unit or the final value is owed.
        | JpDeclaredMixedSequenceCarrierStep of JpDeclaredSequenceResumeStep
        | JpDeclaredMixedSequenceStep of JpDeclaredSequenceResumeStep
        // BinaryNumeric left/right pending states consume a typed child result; keep that relation explicit.
        | JpDeclaredMixedBinaryNumericCarrierStep of JpDeclaredBinaryNumericResumeStep
        | JpDeclaredMixedFoldStep of JpDeclaredFoldResumeStep

    // Mixed execution uses the same produced-channel algebra as producer proofs and
    // target seeds.  One DU now owns all opaque Apply/Let transport semantics.
    let jpDeclaredMixedStepProducedChannel = function
        | JpDeclaredMixedApplyCarrierStep _
        | JpDeclaredMixedApplyStep _ ->
            JpDeclaredCarrierProducedApplyDispatch
        | JpDeclaredMixedLetBindingCarrierStep _
        | JpDeclaredMixedLetStep _ ->
            JpDeclaredCarrierProducedLetBody
        | JpDeclaredMixedSequenceCarrierStep _
        | JpDeclaredMixedSequenceStep _
        | JpDeclaredMixedBinaryNumericCarrierStep _
        | JpDeclaredMixedFoldStep _ ->
            JpDeclaredCarrierProducedNotYetModeled

    let jpDeclaredTypedOpaqueCarrierRelationForMixedStepOutput step parentSnapshot =
        jpDeclaredTypedOpaqueCarrierRelationForProducedChannel
            (jpDeclaredMixedStepProducedChannel step)
            parentSnapshot

    type JpDeclaredMixedResumePlan = private {
        // target = consumer originally selected by the scheduler; entry may be either
        // a Data-producing seed or a control cursor that advances without replaying work.
        mixedTargetRef : JpWorkContinuationRef
        mixedEntryRef : JpWorkContinuationRef
        mixedEntryAuthority : JpDeclaredMixedResumeEntryAuthority
        mixedEntryPoint : JpDeclaredMixedResumeEntryPoint
        mixedSteps : JpDeclaredMixedResumeStep array
        mixedOpaqueEdgeRelations : JpDeclaredTypedOpaqueCarrierRelationId array
    }

    let jpDeclaredMixedResumePlanOpaqueEdgeRelationsText (plan:JpDeclaredMixedResumePlan) =
        match plan.mixedOpaqueEdgeRelations with
        | [||] -> "none"
        | relations -> relations |> Array.map jpDeclaredTypedOpaqueCarrierRelationText |> String.concat ">"

    type JpDeclaredMixedResumePlanRejectionId =
        | JpDeclaredMixedResumeCarrierPolicyNonconformant
        | JpDeclaredMixedResumeTargetSnapshotMissing
        | JpDeclaredMixedResumeEntryUnavailable of targetChannel:JpDeclaredResumeResultChannelId
        | JpDeclaredMixedResumeCycleDetected of continuationRef:JpWorkContinuationRef
        | JpDeclaredMixedResumeSnapshotMissing of continuationRef:JpWorkContinuationRef
        | JpDeclaredMixedResumeUnsupportedSnapshotStep of continuationRef:JpWorkContinuationRef * channel:JpDeclaredResumeResultChannelId
        | JpDeclaredMixedResumeOpaqueCarrierRelationMissing of continuationRef:JpWorkContinuationRef * parentContinuation:JpWorkContinuationRef * depth:int
        | JpDeclaredMixedResumeOpaqueParentMissing of continuationRef:JpWorkContinuationRef * depth:int
        | JpDeclaredMixedResumePostconditionRejected of reachedRoot:bool * reachedRequestedTarget:bool * stepCount:int * sawNonApply:bool * producerSeeded:bool

    let jpDeclaredMixedResumePlanRejectionText = function
        | JpDeclaredMixedResumeCarrierPolicyNonconformant -> "CarrierPolicyNonconformant"
        | JpDeclaredMixedResumeTargetSnapshotMissing -> "TargetSnapshotMissing"
        | JpDeclaredMixedResumeEntryUnavailable targetChannel ->
            "EntryUnavailable(target_channel=" + jpDeclaredResumeResultChannelText targetChannel + ")"
        | JpDeclaredMixedResumeCycleDetected continuationRef ->
            "CycleDetected(continuation=" + JpWorkContinuationRefOps.text continuationRef + ")"
        | JpDeclaredMixedResumeSnapshotMissing continuationRef ->
            "SnapshotMissing(continuation=" + JpWorkContinuationRefOps.text continuationRef + ")"
        | JpDeclaredMixedResumeUnsupportedSnapshotStep(continuationRef, channel) ->
            "UnsupportedSnapshotStep(continuation=" + JpWorkContinuationRefOps.text continuationRef + "|channel=" + jpDeclaredResumeResultChannelText channel + ")"
        | JpDeclaredMixedResumeOpaqueCarrierRelationMissing(continuationRef, parentContinuation, depth) ->
            "OpaqueCarrierRelationMissing(continuation=" + JpWorkContinuationRefOps.text continuationRef + "|parent=" + JpWorkContinuationRefOps.text parentContinuation + "|depth=" + string depth + ")"
        | JpDeclaredMixedResumeOpaqueParentMissing(continuationRef, depth) ->
            "OpaqueParentMissing(continuation=" + JpWorkContinuationRefOps.text continuationRef + "|depth=" + string depth + ")"
        | JpDeclaredMixedResumePostconditionRejected(reachedRoot, reachedRequestedTarget, stepCount, sawNonApply, producerSeeded) ->
            sprintf "PostconditionRejected(root=%b|target=%b|steps=%d|non_apply=%b|producer_seeded=%b)" reachedRoot reachedRequestedTarget stepCount sawNonApply producerSeeded

    let jpTryDeclaredMixedResumeEntry
        (jobId:int64)
        (targetRef:JpWorkContinuationRef)
        (targetSnapshot:JpDeclaredResumeSnapshotId) =
        // ApplyBeforeArgument may only self-seed while no suspended child producer owns
        // its argument result. If a child producer exists, requiring its Data carrier
        // prevents argument replay from re-entering an already-started Let binding.
        let preferredApplyArgumentCarrierRequired =
            match targetSnapshot with
            | JpDeclaredApplyResumeSnapshot(_, continuation) when continuation.stage = JpDeclaredApplyBeforeArgument ->
                match jpResolveDeclaredDataCarrierProducer jobId targetRef JpDeclaredApplyArgumentResultAcceptor with
                | JpDeclaredDataCarrierProducerResolved _
                | JpDeclaredDataCarrierProducerAmbiguous _ -> true
                | JpDeclaredDataCarrierProducerMissing _ -> false
            | _ -> false
        let preferredDirectResumeSeed =
            if preferredApplyArgumentCarrierRequired then None
            else jpDeclaredDirectResumeSeed targetSnapshot
        let preferredDirectResumeSupport =
            if preferredApplyArgumentCarrierRequired then
                JpDeclaredDirectResumeNeedsDataCarrier JpDeclaredApplyArgumentResultAcceptor
            else jpDeclaredDirectResumeSnapshotSupport targetSnapshot
        match preferredDirectResumeSeed with
        | Some seed ->
            let transportWitness =
                jpDeclaredTargetSeedExactTypedOpaqueBridgeRelation targetSnapshot
                |> Option.map JpDeclaredExactOpaqueCarrierTransport
            Some(targetRef, JpDeclaredMixedResumeTargetSeed transportWitness, JpDeclaredMixedResumeDataSeed seed)
        | None ->
            match preferredDirectResumeSupport with
            | JpDeclaredDirectResumeNeedsDataCarrier acceptor
            | JpDeclaredDirectResumeSupportedFoldData acceptor ->
                match jpResolveDeclaredDataCarrierProducer jobId targetRef acceptor with
                | JpDeclaredDataCarrierProducerResolved proof ->
                    let transportWitness =
                        if proof.opaqueBridgeCount = 0 then Some JpDeclaredNestedOrTailCarrierTransport
                        else
                            jpDeclaredDataCarrierExactTypedOpaqueBridgeRelation proof
                            |> Option.map JpDeclaredExactOpaqueCarrierTransport
                    match transportWitness with
                    | Some transportWitness ->
                        if proof.opaqueBridgeCount > 1 then
                            let relationPathText =
                                match jpDeclaredDataCarrierTypedOpaqueBridgeRelations proof with
                                | Some relations -> relations |> Array.map jpDeclaredTypedOpaqueCarrierRelationText |> String.concat ">"
                                | None -> "Unavailable"
                            let occurrence, shouldEmit =
                                DiagJson.sparseLogDecision
                                    ("jp_declared_composed_opaque_carrier_path_admitted|" + string jobId + "|" + string proof.opaqueBridgeCount)
                                    64L
                            if shouldEmit then
                                DiagJson.emit (
                                    FastRuntimeFormat.format
                                        "{\"kind\":\"jp_declared_composed_opaque_carrier_path_admitted\",\"work_job_id\":%d,\"opaque_bridge_count\":%d,\"max_opaque_depth\":%d,\"producer_depth\":%d,\"ownership_path_du\":%s,\"opaque_relation_path_du\":%s,\"transport_du\":%s,\"all_opaque_edges_typed\":true,\"ancestor_replay_hops\":0,\"edge_count_authority\":false,\"observed_depth_authority\":false,\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"occurrence_count\":%d,\"authority\":\"every_opaque_ownership_edge_has_live_typed_closed_relation\",\"next\":\"mixed_planner_revalidates_each_edge_before_execution\"}"
                                        [| box jobId; box proof.opaqueBridgeCount; box proof.maxOpaqueDepth; box proof.producerDepth; box (DiagJson.esc (jpDeclaredDataCarrierOwnershipPathText proof.ownershipPath)); box (DiagJson.esc relationPathText); box (DiagJson.esc (jpDeclaredDataCarrierTransportWitnessText transportWitness)); box occurrence |])
                        Some(proof.producerSeedRef, JpDeclaredMixedResumeDataCarrierProducer(proof, transportWitness), JpDeclaredMixedResumeDataSeed proof.producerSeed)
                    | None -> None
                | JpDeclaredDataCarrierProducerMissing _
                | JpDeclaredDataCarrierProducerAmbiguous _ -> None
            | JpDeclaredDirectResumeLetCheckpointCursorOnly ->
                Some(targetRef, JpDeclaredMixedResumeTargetCursor, JpDeclaredMixedResumeLetCheckpointCursor)
            | JpDeclaredDirectResumeSupportedApply
            | JpDeclaredDirectResumeSupportedLet
            | JpDeclaredDirectResumeSupportedSequence
            | JpDeclaredDirectResumeNeedsFoldRecordTypeCarrier -> None

    let jpBuildDeclaredMixedResumePlanDetailed (jobId:int64) : Result<JpDeclaredMixedResumePlan,JpDeclaredMixedResumePlanRejectionId> =
        let carrierPolicy = jpDeclaredOpaqueCarrierRelationConformanceReceipt ()
        let carrierPolicyOccurrence, shouldEmitCarrierPolicy =
            DiagJson.sparseLogDecision "jp_declared_opaque_carrier_policy_conformance" 4096L
        if carrierPolicy.allPassed && shouldEmitCarrierPolicy then
            DiagJson.emit (
                FastRuntimeFormat.format
                    "{\"kind\":\"jp_declared_opaque_carrier_policy_conformance\",\"work_job_id\":%d,\"apply_dispatch_identity\":%b,\"apply_dispatch_to_apply_argument\":%b,\"apply_dispatch_to_let_binding\":%b,\"apply_dispatch_to_let_body\":%b,\"let_body_to_apply_argument\":%b,\"let_body_to_apply_dispatch\":%b,\"let_body_to_let_binding\":%b,\"let_body_to_let_body\":%b,\"legacy_keeps_unproven_let_body_to_let_body_closed\":%b,\"occurrence_count\":%d,\"authority\":\"closed_typed_carrier_relation_conformance\",\"control_authority\":false,\"opaque_depth_authority_du\":\"observed_depth_only_every_opaque_edge_requires_closed_relation_and_live_typed_endpoints\",\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"next\":\"build_mixed_resume_plan_with_typed_output_to_parent_input_edges\"}"
                    [| box jobId; box carrierPolicy.applyDispatchIdentity; box carrierPolicy.applyDispatchToApplyArgument; box carrierPolicy.applyDispatchToLetBinding; box carrierPolicy.applyDispatchToLetBody; box carrierPolicy.letBodyToApplyArgument; box carrierPolicy.letBodyToApplyDispatch; box carrierPolicy.letBodyToLetBinding; box carrierPolicy.letBodyToLetBody; box carrierPolicy.keepsUnprovenLetBodyToLetBodyClosed; box carrierPolicyOccurrence |])
        if not carrierPolicy.allPassed then
            let occurrence, shouldEmit = DiagJson.sparseLogDecision "jp_declared_opaque_carrier_policy_nonconformant" 64L
            if shouldEmit then
                DiagJson.emit (
                    FastRuntimeFormat.format
                        "{\"kind\":\"jp_declared_opaque_carrier_policy_nonconformant\",\"work_job_id\":%d,\"apply_dispatch_identity\":%b,\"apply_dispatch_to_apply_argument\":%b,\"apply_dispatch_to_let_binding\":%b,\"apply_dispatch_to_let_body\":%b,\"let_body_to_apply_argument\":%b,\"let_body_to_apply_dispatch\":%b,\"let_body_to_let_binding\":%b,\"let_body_to_let_body\":%b,\"legacy_keeps_unproven_let_body_to_let_body_closed\":%b,\"occurrence_count\":%d,\"authority\":\"closed_typed_carrier_relation_conformance\",\"control_authority\":false,\"opaque_depth_authority_du\":\"observed_depth_only_every_opaque_edge_requires_closed_relation_and_live_typed_endpoints\",\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"next\":\"fail_closed_without_opaque_carrier_execution\"}"
                        [| box jobId; box carrierPolicy.applyDispatchIdentity; box carrierPolicy.applyDispatchToApplyArgument; box carrierPolicy.applyDispatchToLetBinding; box carrierPolicy.applyDispatchToLetBody; box carrierPolicy.letBodyToApplyArgument; box carrierPolicy.letBodyToApplyDispatch; box carrierPolicy.letBodyToLetBinding; box carrierPolicy.letBodyToLetBody; box carrierPolicy.keepsUnprovenLetBodyToLetBodyClosed; box occurrence |])
        match jpTryDeclaredResumeSnapshot jobId with
        | Some(targetRef, targetSnapshot) when carrierPolicy.allPassed ->
            match jpTryDeclaredMixedResumeEntry jobId targetRef targetSnapshot with
            | None -> Error (JpDeclaredMixedResumeEntryUnavailable (jpDeclaredResumeSnapshotResultChannel targetSnapshot))
            | Some(entryRef, entryAuthority, entryPoint) ->
                let steps = ResizeArray<JpDeclaredMixedResumeStep>()
                let opaqueEdgeRelations = ResizeArray<JpDeclaredTypedOpaqueCarrierRelationId>()
                let seen = System.Collections.Generic.HashSet<CompilerIdentityKernel.ContentDigest>()
                let mutable cursor = Some entryRef
                let mutable rejection : JpDeclaredMixedResumePlanRejectionId option = None
                let mutable reachedRoot = false
                let mutable reachedRequestedTarget = false
                let mutable sawNonApply = false
                let targetDigest = JpWorkContinuationRefOps.digest targetRef
                while Option.isNone rejection && Option.isSome cursor do
                    let current = Option.get cursor
                    let digest = JpWorkContinuationRefOps.digest current
                    if digest = targetDigest then reachedRequestedTarget <- true
                    if not (seen.Add digest) then
                        rejection <- Some (JpDeclaredMixedResumeCycleDetected current)
                    else
                        let mutable snapshot = Unchecked.defaultof<JpDeclaredResumeSnapshotId>
                        if jp_declared_resume_snapshots.TryGetValue(digest, &snapshot) then
                            let mixedSnapshotSupport =
                                if digest = targetDigest then
                                    match snapshot with
                                    | JpDeclaredApplyResumeSnapshot(_, continuation) when continuation.stage = JpDeclaredApplyBeforeArgument ->
                                        match jpResolveDeclaredDataCarrierProducer jobId current JpDeclaredApplyArgumentResultAcceptor with
                                        | JpDeclaredDataCarrierProducerResolved _
                                        | JpDeclaredDataCarrierProducerAmbiguous _ ->
                                            JpDeclaredDirectResumeNeedsDataCarrier JpDeclaredApplyArgumentResultAcceptor
                                        | JpDeclaredDataCarrierProducerMissing _ -> jpDeclaredDirectResumeSnapshotSupport snapshot
                                    | _ -> jpDeclaredDirectResumeSnapshotSupport snapshot
                                else jpDeclaredDirectResumeSnapshotSupport snapshot
                            let parentPc =
                                match mixedSnapshotSupport, snapshot with
                                | JpDeclaredDirectResumeSupportedApply,
                                  JpDeclaredApplyResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, nodeId, parentPc), continuation)
                                    when ownerJobId = jobId && steps.Count = 0 ->
                                    steps.Add(JpDeclaredMixedApplyStep {
                                        continuationRef = current
                                        nodeId = nodeId
                                        continuation = continuation
                                    })
                                    Some parentPc
                                | JpDeclaredDirectResumeSupportedApply,
                                  JpDeclaredApplyResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, nodeId, parentPc), continuation)
                                    when ownerJobId = jobId && steps.Count > 0 ->
                                    // A replayable ApplyBeforeArgument is only a seed at the entry.
                                    // Higher in a mixed spine it consumes the Data produced by the prior
                                    // child step as its exact argument, then dispatches once.
                                    steps.Add(JpDeclaredMixedApplyCarrierStep {
                                        continuationRef = current
                                        nodeId = nodeId
                                        continuation = continuation
                                    })
                                    Some parentPc
                                | JpDeclaredDirectResumeNeedsDataCarrier (JpDeclaredApplyHeadResultAcceptor | JpDeclaredApplyArgumentResultAcceptor | JpDeclaredApplyDispatchResultAcceptor),
                                  JpDeclaredApplyResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, nodeId, parentPc), continuation)
                                    when ownerJobId = jobId && steps.Count > 0 ->
                                    steps.Add(JpDeclaredMixedApplyCarrierStep {
                                        continuationRef = current
                                        nodeId = nodeId
                                        continuation = continuation
                                    })
                                    Some parentPc
                                | JpDeclaredDirectResumeNeedsDataCarrier JpDeclaredLetBindingResultAcceptor,
                                  JpDeclaredLetResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, nodeId, parentPc), continuation)
                                    when ownerJobId = jobId && steps.Count > 0 ->
                                    // BindingPending is a carrier-consuming parent step, never an entry seed.
                                    // The immediately preceding mixed step already produced the binding Data;
                                    // admitting it here preserves the old evaluator law without replaying the binding.
                                    sawNonApply <- true
                                    steps.Add(JpDeclaredMixedLetBindingCarrierStep {
                                        continuationRef = current
                                        nodeId = nodeId
                                        continuation = continuation
                                    })
                                    Some parentPc
                                | JpDeclaredDirectResumeSupportedLet,
                                  JpDeclaredLetResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, nodeId, parentPc), continuation)
                                    when ownerJobId = jobId ->
                                    sawNonApply <- true
                                    steps.Add(JpDeclaredMixedLetStep {
                                        continuationRef = current
                                        nodeId = nodeId
                                        continuation = continuation
                                    })
                                    Some parentPc
                                | JpDeclaredDirectResumeLetCheckpointCursorOnly,
                                  JpDeclaredLetResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, nodeId, parentPc), continuation)
                                    when ownerJobId = jobId && digest = targetDigest ->
                                    sawNonApply <- true
                                    steps.Add(JpDeclaredMixedLetStep {
                                        continuationRef = current
                                        nodeId = nodeId
                                        continuation = continuation
                                    })
                                    Some parentPc
                                | JpDeclaredDirectResumeSupportedSequence,
                                  JpDeclaredSequenceResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, nodeId, parentPc), continuation)
                                    when ownerJobId = jobId && steps.Count = 0 ->
                                    sawNonApply <- true
                                    steps.Add(JpDeclaredMixedSequenceStep {
                                        continuationRef = current
                                        nodeId = nodeId
                                        continuation = continuation
                                    })
                                    Some parentPc
                                | JpDeclaredDirectResumeSupportedSequence,
                                  JpDeclaredSequenceResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, nodeId, parentPc), continuation)
                                    when ownerJobId = jobId && steps.Count > 0 ->
                                    sawNonApply <- true
                                    steps.Add(JpDeclaredMixedSequenceCarrierStep {
                                        continuationRef = current
                                        nodeId = nodeId
                                        continuation = continuation
                                    })
                                    Some parentPc
                                | JpDeclaredDirectResumeNeedsDataCarrier (JpDeclaredSequenceFirstResultAcceptor | JpDeclaredSequenceTailResultAcceptor),
                                  JpDeclaredSequenceResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, nodeId, parentPc), continuation)
                                    when ownerJobId = jobId && steps.Count > 0 ->
                                    sawNonApply <- true
                                    steps.Add(JpDeclaredMixedSequenceCarrierStep {
                                        continuationRef = current
                                        nodeId = nodeId
                                        continuation = continuation
                                    })
                                    Some parentPc
                                | JpDeclaredDirectResumeNeedsDataCarrier (JpDeclaredBinaryNumericLeftResultAcceptor | JpDeclaredBinaryNumericRightResultAcceptor),
                                  JpDeclaredBinaryNumericResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, nodeId, parentPc), continuation)
                                    when ownerJobId = jobId && steps.Count > 0 ->
                                    sawNonApply <- true
                                    steps.Add(JpDeclaredMixedBinaryNumericCarrierStep {
                                        continuationRef = current
                                        nodeId = nodeId
                                        continuation = continuation
                                    })
                                    Some parentPc
                                | JpDeclaredDirectResumeSupportedFoldData resultAcceptor,
                                  JpDeclaredRecordTypeFoldBackResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, nodeId, parentPc), continuation)
                                    when ownerJobId = jobId ->
                                    sawNonApply <- true
                                    steps.Add(JpDeclaredMixedFoldStep {
                                        continuationRef = current
                                        nodeId = nodeId
                                        continuation = continuation
                                        resultAcceptor = resultAcceptor
                                    })
                                    Some parentPc
                                | _ -> None
                            match parentPc with
                            | None ->
                                rejection <- Some (JpDeclaredMixedResumeUnsupportedSnapshotStep(current, jpDeclaredResumeSnapshotResultChannel snapshot))
                            | Some JpDeclaredEvaluatorRootPc ->
                                reachedRoot <- true
                                cursor <- None
                            | Some (JpDeclaredEvaluatorNestedPc parentContinuation) ->
                                cursor <- Some parentContinuation
                            | Some (JpDeclaredEvaluatorTailBridgePc(parentContinuation, _, _)) ->
                                cursor <- Some parentContinuation
                            | Some (JpDeclaredEvaluatorOpaquePc(Some parentContinuation, depth)) ->
                                // Opaque parentage remains non-executable by default.  An entry proof
                                // may authorize its own exact bridge, but an already-executed mixed step
                                // can also cross one opaque parent only when its typed output channel and
                                // the parent's typed Data acceptor form one of the closed relations above.
                                let exactEntryOpaqueCarrierRelation =
                                    match entryAuthority with
                                    | JpDeclaredMixedResumeDataCarrierProducer(_, JpDeclaredExactOpaqueCarrierTransport _) ->
                                        // Revalidate the live edge being crossed. The producer proof establishes
                                        // that its ownership path was typed when admitted, but edge count/depth
                                        // are evidence rather than a capability whitelist. This prevents a
                                        // multi-edge proof from depending on a special count=1 entry case.
                                        match jpTryDeclaredResumeSnapshotByRef parentContinuation with
                                        | Some parentSnapshot ->
                                            match jpDeclaredTypedOpaqueCarrierRelationForSnapshotEdge snapshot parentSnapshot with
                                            | Some relation when Option.isSome (jpDeclaredTryTypedOpaqueBridgeDepth relation depth) -> Some relation
                                            | _ -> None
                                        | None -> None
                                    | JpDeclaredMixedResumeTargetSeed(Some (JpDeclaredExactOpaqueCarrierTransport relation))
                                        when digest = targetDigest
                                             && Option.isSome (jpDeclaredTryTypedOpaqueBridgeDepth relation depth) ->
                                        Some relation
                                    | JpDeclaredMixedResumeDataCarrierProducer(_, JpDeclaredNestedOrTailCarrierTransport)
                                    | JpDeclaredMixedResumeTargetSeed None
                                    | JpDeclaredMixedResumeTargetSeed(Some JpDeclaredNestedOrTailCarrierTransport)
                                    | JpDeclaredMixedResumeTargetCursor -> None
                                    | _ -> None
                                let exactStepOutputOpaqueCarrierRelation =
                                    if steps.Count = 0 then None
                                    else
                                        match jpTryDeclaredResumeSnapshotByRef parentContinuation with
                                        | Some parentSnapshot ->
                                            match
                                                jpDeclaredTypedOpaqueCarrierRelationForMixedStepOutput
                                                    steps.[steps.Count - 1]
                                                    parentSnapshot
                                            with
                                            | Some relation when Option.isSome (jpDeclaredTryTypedOpaqueBridgeDepth relation depth) -> Some relation
                                            | _ -> None
                                        | None -> None
                                let exactOpaqueCarrierRelation =
                                    match exactStepOutputOpaqueCarrierRelation with
                                    | Some _ as relation -> relation
                                    | None -> exactEntryOpaqueCarrierRelation
                                match exactOpaqueCarrierRelation with
                                | Some relation ->
                                    opaqueEdgeRelations.Add relation
                                    cursor <- Some parentContinuation
                                | None ->
                                    rejection <- Some (JpDeclaredMixedResumeOpaqueCarrierRelationMissing(current, parentContinuation, depth))
                                    cursor <- None
                            | Some (JpDeclaredEvaluatorOpaquePc(None, depth)) ->
                                let childChannelText = jpDeclaredResumeSnapshotResultChannel snapshot |> jpDeclaredResumeResultChannelText
                                let childNodeId = jpDeclaredResumeSnapshotNodeId snapshot
                                let occurrence, shouldEmit =
                                    DiagJson.sparseLogDecision
                                        ("jp_declared_opaque_parent_missing_fail_closed|" + string jobId + "|" + string childNodeId + "|" + childChannelText)
                                        64L
                                if shouldEmit then
                                    DiagJson.emit (
                                        FastRuntimeFormat.format
                                            "{\"kind\":\"jp_declared_opaque_parent_missing_fail_closed\",\"work_job_id\":%d,\"child_continuation_ref\":%s,\"child_node_id\":%d,\"child_result_channel_du\":%s,\"observed_opaque_depth\":%d,\"typed_parent_present\":false,\"ancestor_replay_hops\":0,\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"occurrence_count\":%d,\"authority\":\"typed_snapshot_parent_endpoint_absence\",\"control_authority\":false,\"next\":\"remain_fail_closed_until_a_live_typed_parent_endpoint_exists\"}"
                                            [| box jobId; box (DiagJson.esc (JpWorkContinuationRefOps.text current)); box childNodeId; box (DiagJson.esc childChannelText); box depth; box occurrence |])
                                rejection <- Some (JpDeclaredMixedResumeOpaqueParentMissing(current, depth))
                                cursor <- None
                        else
                            rejection <- Some (JpDeclaredMixedResumeSnapshotMissing current)
                let producerSeeded = JpWorkContinuationRefOps.digest entryRef <> targetDigest
                let crossedTypedOpaqueCarrierEdge = opaqueEdgeRelations.Count > 0
                if Option.isNone rejection && reachedRoot && reachedRequestedTarget && steps.Count > 0 && (sawNonApply || producerSeeded || crossedTypedOpaqueCarrierEdge) then
                    Ok {
                        mixedTargetRef = targetRef
                        mixedEntryRef = entryRef
                        mixedEntryAuthority = entryAuthority
                        mixedEntryPoint = entryPoint
                        mixedSteps = steps.ToArray()
                        mixedOpaqueEdgeRelations = opaqueEdgeRelations.ToArray()
                    }
                else
                    Error (
                        defaultArg rejection (
                            JpDeclaredMixedResumePostconditionRejected(
                                reachedRoot,
                                reachedRequestedTarget,
                                steps.Count,
                                sawNonApply,
                                producerSeeded)))
        | Some _ -> Error JpDeclaredMixedResumeCarrierPolicyNonconformant
        | None -> Error JpDeclaredMixedResumeTargetSnapshotMissing

    let jpTryBuildDeclaredMixedResumePlan (jobId:int64) : JpDeclaredMixedResumePlan option =
        match jpBuildDeclaredMixedResumePlanDetailed jobId with
        | Ok plan -> Some plan
        | Error rejection ->
            let rejectionText = jpDeclaredMixedResumePlanRejectionText rejection
            let targetRefText, targetChannelText, targetNodeId =
                match jpTryDeclaredResumeSnapshot jobId with
                | Some(targetRef, targetSnapshot) ->
                    JpWorkContinuationRefOps.text targetRef,
                    jpDeclaredResumeSnapshotResultChannel targetSnapshot |> jpDeclaredResumeResultChannelText,
                    jpDeclaredResumeSnapshotNodeId targetSnapshot
                | None -> "Missing", "Missing", 0
            let occurrence, shouldEmit =
                DiagJson.sparseLogDecision ("jp_declared_mixed_resume_plan_rejected|" + rejectionText) 64L
            if shouldEmit then
                DiagJson.emit (
                    FastRuntimeFormat.format
                        "{\"kind\":\"jp_declared_mixed_resume_plan_rejected\",\"work_job_id\":%d,\"target_ref\":%s,\"target_node_id\":%d,\"target_channel_du\":%s,\"rejection_du\":%s,\"ancestor_replay_hops\":0,\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"occurrence_count\":%d,\"authority\":\"typed_mixed_resume_plan_builder\",\"control_authority\":false,\"next\":\"surface_exact_rejection_without_ancestor_replay\"}"
                        [| box jobId; box (DiagJson.esc targetRefText); box targetNodeId; box (DiagJson.esc targetChannelText); box (DiagJson.esc rejectionText); box occurrence |])
            None

    let jpDeclaredApplyResumePlanRootNodeId (plan:JpDeclaredApplyResumePlan) =
        plan.applySteps.[plan.applySteps.Length - 1].nodeId

    let jpDeclaredMixedResumePlanRootNodeId (plan:JpDeclaredMixedResumePlan) =
        match plan.mixedSteps.[plan.mixedSteps.Length - 1] with
        | JpDeclaredMixedApplyCarrierStep step
        | JpDeclaredMixedApplyStep step -> step.nodeId
        | JpDeclaredMixedLetBindingCarrierStep step -> step.nodeId
        | JpDeclaredMixedLetStep step -> step.nodeId
        | JpDeclaredMixedSequenceCarrierStep step
        | JpDeclaredMixedSequenceStep step -> step.nodeId
        | JpDeclaredMixedBinaryNumericCarrierStep step -> step.nodeId
        | JpDeclaredMixedFoldStep step -> step.nodeId

    type JpDeclaredDirectResumePlanId =
        | JpDeclaredDirectApplyPlan of JpDeclaredApplyResumePlan
        | JpDeclaredDirectMixedPlan of JpDeclaredMixedResumePlan

    type JpDeclaredDirectResumeBlockerId =
        | JpDeclaredDirectResumeTargetMissing
        | JpDeclaredDirectResumeTargetCannotEnterMixedPlan of JpDeclaredResumeResultChannelId
        | JpDeclaredDirectResumeDataCarrierProducerMissing of consumerRef:JpWorkContinuationRef * acceptor:JpDeclaredDataResultAcceptorId
        | JpDeclaredDirectResumeDataCarrierProducerAmbiguous of consumerRef:JpWorkContinuationRef * acceptor:JpDeclaredDataResultAcceptorId * producerRefs:JpWorkContinuationRef list
        | JpDeclaredDirectResumeOpaqueCarrierBridgeRequired of JpDeclaredDataResultAcceptorId * bridgeCount:int * maxDepth:int * ownershipPath:JpDeclaredDataCarrierOwnershipPath option * opaqueParentRef:JpWorkContinuationRef option
        | JpDeclaredDirectResumeTypedOpaqueCarrierRelationDidNotPlan of relation:JpDeclaredTypedOpaqueCarrierRelationId * acceptor:JpDeclaredDataResultAcceptorId * opaqueParentRef:JpWorkContinuationRef option
        | JpDeclaredDirectResumeCycle of JpWorkContinuationRef
        | JpDeclaredDirectResumeSnapshotMissing of JpWorkContinuationRef
        | JpDeclaredDirectResumeOwnerMismatch of ownerJobId:int64
        | JpDeclaredDirectResumeOpaqueParent of nearestTypedParent:JpWorkContinuationRef option * termDepthDelta:int
        | JpDeclaredDirectResumeFoldRecordTypeCarrierRequired
        | JpDeclaredDirectResumeLetCheckpointCursorOnlyBlocker
        | JpDeclaredDirectResumeMixedPlanRejected of JpDeclaredMixedResumePlanRejectionId
        | JpDeclaredDirectResumeSupportedSpineDidNotPlan of JpDeclaredResumeResultChannelId

    let jpDeclaredDirectResumeBlockerText = function
        | JpDeclaredDirectResumeTargetMissing -> "TargetMissing"
        | JpDeclaredDirectResumeTargetCannotEnterMixedPlan channel -> "TargetCannotEnterMixedPlan(" + jpDeclaredResumeResultChannelText channel + ")"
        | JpDeclaredDirectResumeDataCarrierProducerMissing(consumerRef, acceptor) -> "DataCarrierProducerMissing(consumer=" + JpWorkContinuationRefOps.text consumerRef + "|acceptor=" + jpDeclaredDataResultAcceptorText acceptor + ")"
        | JpDeclaredDirectResumeDataCarrierProducerAmbiguous(consumerRef, acceptor, producerRefs) ->
            let producersText = producerRefs |> List.map JpWorkContinuationRefOps.text |> String.concat ","
            "DataCarrierProducerAmbiguous(consumer=" + JpWorkContinuationRefOps.text consumerRef + "|acceptor=" + jpDeclaredDataResultAcceptorText acceptor + "|producers=" + producersText + ")"
        | JpDeclaredDirectResumeOpaqueCarrierBridgeRequired(acceptor, bridgeCount, maxDepth, ownershipPath, opaqueParentRef) ->
            let pathText = ownershipPath |> Option.map jpDeclaredDataCarrierOwnershipPathText |> Option.defaultValue "unavailable"
            let opaqueParentText = opaqueParentRef |> Option.map JpWorkContinuationRefOps.text |> Option.defaultValue "unavailable"
            "OpaqueCarrierBridgeRequired(" + jpDeclaredDataResultAcceptorText acceptor + "|count=" + string bridgeCount + "|max_depth=" + string maxDepth + "|path=" + pathText + "|opaque_parent=" + opaqueParentText + ")"
        | JpDeclaredDirectResumeTypedOpaqueCarrierRelationDidNotPlan(relation, acceptor, opaqueParentRef) ->
            let opaqueParentText = opaqueParentRef |> Option.map JpWorkContinuationRefOps.text |> Option.defaultValue "unavailable"
            "TypedOpaqueCarrierRelationDidNotPlan(relation=" + jpDeclaredTypedOpaqueCarrierRelationText relation + "|acceptor=" + jpDeclaredDataResultAcceptorText acceptor + "|opaque_parent=" + opaqueParentText + ")"
        | JpDeclaredDirectResumeCycle continuationRef -> "Cycle(" + JpWorkContinuationRefOps.text continuationRef + ")"
        | JpDeclaredDirectResumeSnapshotMissing continuationRef -> "SnapshotMissing(" + JpWorkContinuationRefOps.text continuationRef + ")"
        | JpDeclaredDirectResumeOwnerMismatch ownerJobId -> "OwnerMismatch(" + string ownerJobId + ")"
        | JpDeclaredDirectResumeOpaqueParent(nearestTypedParent, depthDelta) ->
            let nearestText =
                match nearestTypedParent with
                | Some continuationRef -> JpWorkContinuationRefOps.text continuationRef
                | None -> "root"
            "OpaqueParent(nearest=" + nearestText + "|depth_delta=" + string depthDelta + ")"
        | JpDeclaredDirectResumeFoldRecordTypeCarrierRequired -> "FoldRecordTypeCarrierRequired"
        | JpDeclaredDirectResumeLetCheckpointCursorOnlyBlocker -> "LetCheckpointCursorOnly"
        | JpDeclaredDirectResumeMixedPlanRejected rejection -> "MixedPlanRejected(" + jpDeclaredMixedResumePlanRejectionText rejection + ")"
        | JpDeclaredDirectResumeSupportedSpineDidNotPlan channel -> "SupportedSpineDidNotPlan(target_channel=" + jpDeclaredResumeResultChannelText channel + ")"

    let jpDeclaredDirectResumeBlockerOpaqueParentText = function
        | JpDeclaredDirectResumeOpaqueCarrierBridgeRequired(_, _, _, _, Some opaqueParentRef)
        | JpDeclaredDirectResumeTypedOpaqueCarrierRelationDidNotPlan(_, _, Some opaqueParentRef) ->
            JpWorkContinuationRefOps.text opaqueParentRef
        | JpDeclaredDirectResumeOpaqueParent(Some opaqueParentRef, _)
        | JpDeclaredDirectResumeMixedPlanRejected (JpDeclaredMixedResumeOpaqueCarrierRelationMissing(_, opaqueParentRef, _)) ->
            JpWorkContinuationRefOps.text opaqueParentRef
        | _ -> "unavailable"

    let jpDeclaredDirectResumeBlockerOpaqueParentSnapshotKindText blocker =
        let opaqueParentRef =
            match blocker with
            | JpDeclaredDirectResumeOpaqueCarrierBridgeRequired(_, _, _, _, Some opaqueParentRef)
            | JpDeclaredDirectResumeTypedOpaqueCarrierRelationDidNotPlan(_, _, Some opaqueParentRef)
            | JpDeclaredDirectResumeOpaqueParent(Some opaqueParentRef, _)
            | JpDeclaredDirectResumeMixedPlanRejected (JpDeclaredMixedResumeOpaqueCarrierRelationMissing(_, opaqueParentRef, _)) -> Some opaqueParentRef
            | _ -> None
        match opaqueParentRef with
        | Some opaqueParentRef ->
            match jpTryDeclaredResumeSnapshotByRef opaqueParentRef with
            | Some snapshot -> jpDeclaredResumeSnapshotKindText snapshot
            | None -> "Missing"
        | None -> "Unavailable"

    let jpDeclaredDirectResumeBlockerOpaqueParentResultChannelText blocker =
        let opaqueParentRef =
            match blocker with
            | JpDeclaredDirectResumeOpaqueCarrierBridgeRequired(_, _, _, _, Some opaqueParentRef)
            | JpDeclaredDirectResumeTypedOpaqueCarrierRelationDidNotPlan(_, _, Some opaqueParentRef)
            | JpDeclaredDirectResumeOpaqueParent(Some opaqueParentRef, _)
            | JpDeclaredDirectResumeMixedPlanRejected (JpDeclaredMixedResumeOpaqueCarrierRelationMissing(_, opaqueParentRef, _)) -> Some opaqueParentRef
            | _ -> None
        match opaqueParentRef with
        | Some opaqueParentRef ->
            match jpTryDeclaredResumeSnapshotByRef opaqueParentRef with
            | Some snapshot -> snapshot |> jpDeclaredResumeSnapshotResultChannel |> jpDeclaredResumeResultChannelText
            | None -> "Missing"
        | None -> "Unavailable"

    let jpDeclaredDirectResumeBlocker (jobId:int64) : JpDeclaredDirectResumeBlockerId =
        match jpTryDeclaredResumeSnapshot jobId with
        | None -> JpDeclaredDirectResumeTargetMissing
        | Some(targetRef, targetSnapshot) ->
            match targetSnapshot with
            | _ when jpDeclaredDirectResumeCanEnterMixedPlan targetSnapshot ->
                let seen = System.Collections.Generic.HashSet<CompilerIdentityKernel.ContentDigest>()
                let targetDigest = JpWorkContinuationRefOps.digest targetRef
                let mutable cursor = Some targetRef
                let mutable blocker : JpDeclaredDirectResumeBlockerId option = None
                while Option.isSome cursor && Option.isNone blocker do
                    let current = Option.get cursor
                    let digest = JpWorkContinuationRefOps.digest current
                    if not (seen.Add digest) then
                        blocker <- Some (JpDeclaredDirectResumeCycle current)
                    else
                        let mutable snapshot = Unchecked.defaultof<JpDeclaredResumeSnapshotId>
                        if not (jp_declared_resume_snapshots.TryGetValue(digest, &snapshot)) then
                            blocker <- Some (JpDeclaredDirectResumeSnapshotMissing current)
                        else
                            match jpDeclaredResumeSnapshotKey snapshot with
                            | JpDeclaredEvaluatorPcKey(ownerJobId, _, parentPc) when ownerJobId <> jobId ->
                                blocker <- Some (JpDeclaredDirectResumeOwnerMismatch ownerJobId)
                            | JpDeclaredEvaluatorPcKey(_, _, parentPc) ->
                                match jpDeclaredDirectResumeSnapshotSupport snapshot with
                                | JpDeclaredDirectResumeSupportedApply
                                | JpDeclaredDirectResumeSupportedLet
                                | JpDeclaredDirectResumeSupportedSequence
                                | JpDeclaredDirectResumeSupportedFoldData _ -> ()
                                | JpDeclaredDirectResumeNeedsDataCarrier acceptor ->
                                    // A Data channel is an obligation, not itself the root cause. Resolve the
                                    // producer graph before reporting so a real opaque bridge/missing producer
                                    // is not hidden behind the generic channel requirement.
                                    match jpResolveDeclaredDataCarrierProducer jobId current acceptor with
                                    | JpDeclaredDataCarrierProducerResolved proof when proof.opaqueBridgeCount > 0 ->
                                        let opaqueParentRef = jpDeclaredDataCarrierOwnershipFirstOpaqueParentRef proof.ownershipPath
                                        match jpDeclaredDataCarrierExactTypedOpaqueBridgeRelation proof with
                                        | Some _ ->
                                            // A closed typed relation is positive transport authority, not a blocker.
                                            // Keep scanning the mixed spine so the detailed planner can surface the
                                            // first actual structural rejection (for example OpaqueParentMissing).
                                            ()
                                        | None ->
                                            blocker <- Some (JpDeclaredDirectResumeOpaqueCarrierBridgeRequired(acceptor, proof.opaqueBridgeCount, proof.maxOpaqueDepth, Some proof.ownershipPath, opaqueParentRef))
                                    | JpDeclaredDataCarrierProducerResolved _ -> ()
                                    | JpDeclaredDataCarrierProducerMissing _ ->
                                        blocker <- Some (JpDeclaredDirectResumeDataCarrierProducerMissing(current, acceptor))
                                    | JpDeclaredDataCarrierProducerAmbiguous(_, _, producerRefs) ->
                                        blocker <- Some (JpDeclaredDirectResumeDataCarrierProducerAmbiguous(current, acceptor, producerRefs))
                                | JpDeclaredDirectResumeNeedsFoldRecordTypeCarrier ->
                                    blocker <- Some JpDeclaredDirectResumeFoldRecordTypeCarrierRequired
                                | JpDeclaredDirectResumeLetCheckpointCursorOnly ->
                                    if digest <> targetDigest then
                                        blocker <- Some JpDeclaredDirectResumeLetCheckpointCursorOnlyBlocker
                                if Option.isNone blocker then
                                    match parentPc with
                                    | JpDeclaredEvaluatorRootPc -> cursor <- None
                                    | JpDeclaredEvaluatorNestedPc parentContinuation -> cursor <- Some parentContinuation
                                    | JpDeclaredEvaluatorTailBridgePc(parentContinuation, _, _) -> cursor <- Some parentContinuation
                                    | JpDeclaredEvaluatorOpaquePc(Some parentContinuation, depthDelta) ->
                                        match jpTryDeclaredResumeSnapshotByRef parentContinuation with
                                        | Some parentSnapshot ->
                                            match jpDeclaredTypedOpaqueCarrierRelationForSnapshotEdge snapshot parentSnapshot with
                                            | Some relation when Option.isSome (jpDeclaredTryTypedOpaqueBridgeDepth relation depthDelta) ->
                                                cursor <- Some parentContinuation
                                            | _ ->
                                                blocker <-
                                                    match jpDeclaredResumeSnapshotResultChannel snapshot with
                                                    | JpDeclaredResumeDataResult acceptor ->
                                                        Some (JpDeclaredDirectResumeOpaqueCarrierBridgeRequired(acceptor, 1, max 1 depthDelta, None, Some parentContinuation))
                                                    | _ -> Some (JpDeclaredDirectResumeOpaqueParent(Some parentContinuation, depthDelta))
                                                cursor <- None
                                        | None ->
                                            blocker <- Some (JpDeclaredDirectResumeSnapshotMissing parentContinuation)
                                            cursor <- None
                                    | JpDeclaredEvaluatorOpaquePc(None, depthDelta) ->
                                        // Without a typed parent there is no carrier endpoint to relate against.
                                        // Preserve the exact structural rejection instead of misclassifying this
                                        // root-descendant boundary as a bridge that could be widened by policy.
                                        blocker <-
                                            Some (JpDeclaredDirectResumeMixedPlanRejected(
                                                JpDeclaredMixedResumeOpaqueParentMissing(current, depthDelta)))
                                        cursor <- None
                defaultArg blocker (
                    match jpBuildDeclaredMixedResumePlanDetailed jobId with
                    | Error rejection -> JpDeclaredDirectResumeMixedPlanRejected rejection
                    | Ok _ -> JpDeclaredDirectResumeSupportedSpineDidNotPlan (jpDeclaredResumeSnapshotResultChannel targetSnapshot))
            | _ ->
                match jpDeclaredDirectResumeSnapshotSupport targetSnapshot with
                | JpDeclaredDirectResumeSupportedFoldData acceptor
                | JpDeclaredDirectResumeNeedsDataCarrier acceptor ->
                    match jpResolveDeclaredDataCarrierProducer jobId targetRef acceptor with
                    | JpDeclaredDataCarrierProducerResolved proof when proof.opaqueBridgeCount > 0 ->
                        let opaqueParentRef = jpDeclaredDataCarrierOwnershipFirstOpaqueParentRef proof.ownershipPath
                        match jpDeclaredDataCarrierExactTypedOpaqueBridgeRelation proof with
                        | Some relation ->
                            // The carrier relation itself is already closed.  Preserve the
                            // detailed mixed-plan rejection so a structural defect such as
                            // OpaqueParentMissing is not mislabeled as a relation failure.
                            match jpBuildDeclaredMixedResumePlanDetailed jobId with
                            | Error rejection -> JpDeclaredDirectResumeMixedPlanRejected rejection
                            | Ok _ -> JpDeclaredDirectResumeTypedOpaqueCarrierRelationDidNotPlan(relation, acceptor, opaqueParentRef)
                        | None -> JpDeclaredDirectResumeOpaqueCarrierBridgeRequired(acceptor, proof.opaqueBridgeCount, proof.maxOpaqueDepth, Some proof.ownershipPath, opaqueParentRef)
                    | JpDeclaredDataCarrierProducerResolved _ -> JpDeclaredDirectResumeSupportedSpineDidNotPlan (jpDeclaredResumeSnapshotResultChannel targetSnapshot)
                    | JpDeclaredDataCarrierProducerMissing _ -> JpDeclaredDirectResumeDataCarrierProducerMissing(targetRef, acceptor)
                    | JpDeclaredDataCarrierProducerAmbiguous(_, _, producerRefs) -> JpDeclaredDirectResumeDataCarrierProducerAmbiguous(targetRef, acceptor, producerRefs)
                | JpDeclaredDirectResumeNeedsFoldRecordTypeCarrier -> JpDeclaredDirectResumeFoldRecordTypeCarrierRequired
                | _ -> JpDeclaredDirectResumeTargetCannotEnterMixedPlan (jpDeclaredResumeSnapshotResultChannel targetSnapshot)

    let jpTryBuildDeclaredDirectResumePlan (jobId:int64) : JpDeclaredDirectResumePlanId option =
        // Hot probes without an installed target cannot build either direct plan.
        // Gate before policy conformance/detailed rejection logging to avoid TargetSnapshotMissing churn.
        match jpTryDeclaredResumeSnapshot jobId with
        | None -> None
        | Some _ ->
            // A root-complete Apply-only spine is the narrower plan and avoids
            // exercising mixed-plan diagnostics for a case that needs no mixed carrier.
            match jpTryBuildDeclaredApplyResumePlan jobId with
            | Some applyPlan -> Some (JpDeclaredDirectApplyPlan applyPlan)
            | None -> jpTryBuildDeclaredMixedResumePlan jobId |> Option.map JpDeclaredDirectMixedPlan

    // Ancestor replay is deliberately unrepresentable. A suspended child owns a concrete
    // result obligation; moving the cursor upward can duplicate Apply/effects and discard
    // that result. Validate the selected target in place and expose its typed blocker instead.
    let jpValidateDeclaredResumeTargetPlanability (jobId:int64) (targetRef:JpWorkContinuationRef) =
        jpInstallDeclaredResumeTarget jobId (Some targetRef)
        try
            let planable =
                match jpTryBuildDeclaredDirectResumePlan jobId with
                | Some _ -> true
                | None ->
                    match jpTryDeclaredResumeSnapshotByRef targetRef with
                    | Some snapshot when jpDeclaredResumeSnapshotHasDirectRootRoute jobId snapshot -> true
                    | _ -> false
            let blocker = if planable then None else Some (jpDeclaredDirectResumeBlocker jobId)
            targetRef, blocker, 0
        finally
            jpClearDeclaredResumeTarget jobId

    type JpDeclaredRootResumeId =
        | JpDeclaredRootLetResume of JpDeclaredLetContinuation
        | JpDeclaredRootSequenceResume of JpDeclaredSequenceContinuation
        | JpDeclaredRootBinaryNumericResume of JpDeclaredBinaryNumericContinuation
        | JpDeclaredRootRecordTypeFoldBackResume of JpDeclaredRecordTypeFoldBackContinuation

    let jpTryDeclaredRootResume jobId nodeId =
        match jpTryDeclaredResumeSnapshot jobId with
        | Some(target, JpDeclaredLetResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, ownerNodeId, JpDeclaredEvaluatorRootPc), continuation))
            when ownerJobId = jobId && ownerNodeId = nodeId ->
            match continuation.stage with
            | JpDeclaredLetBindingPending
            | JpDeclaredLetCheckpointReady -> None
            | JpDeclaredLetBodyPending -> Some(target, JpDeclaredRootLetResume continuation)
        | Some(target, JpDeclaredSequenceResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, ownerNodeId, JpDeclaredEvaluatorRootPc), continuation))
            when ownerJobId = jobId && ownerNodeId = nodeId ->
            match continuation.stage with
            | JpDeclaredSequenceFirstPending _ -> None
            | JpDeclaredSequenceTailPending -> Some(target, JpDeclaredRootSequenceResume continuation)
        | Some(_, JpDeclaredBinaryNumericResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, ownerNodeId, JpDeclaredEvaluatorRootPc), _))
            when ownerJobId = jobId && ownerNodeId = nodeId ->
            None
        | Some(target, JpDeclaredRecordTypeFoldBackResumeSnapshot(JpDeclaredEvaluatorPcKey(ownerJobId, ownerNodeId, JpDeclaredEvaluatorRootPc), continuation))
            when ownerJobId = jobId && ownerNodeId = nodeId ->
            Some(target, JpDeclaredRootRecordTypeFoldBackResume continuation)
        | _ -> None

    let jpRemoveDeclaredEvaluatorContinuationsForJob jobId =
        jpClearDeclaredResumeTarget jobId
        let mutable removedOrdinal = 0L
        jp_declared_continuation_ordinals.TryRemove(jobId, &removedOrdinal) |> ignore
        let mutable removedEvidenceRevision = 0L
        jp_declared_resume_evidence_revisions.TryRemove(jobId, &removedEvidenceRevision) |> ignore
        for entry in jp_declared_resume_snapshot_registration_evidence do
            if entry.Value.job_id = jobId then
                let mutable removedRegistrationEvidence = Unchecked.defaultof<JpDeclaredResumeSnapshotRegistrationEvidence>
                jp_declared_resume_snapshot_registration_evidence.TryRemove(entry.Key, &removedRegistrationEvidence) |> ignore
        for entry in jp_declared_resume_snapshot_retirement_evidence do
            if entry.Value.job_id = jobId then
                let mutable removedRetirementEvidence = Unchecked.defaultof<JpDeclaredResumeSnapshotRetirementEvidence>
                jp_declared_resume_snapshot_retirement_evidence.TryRemove(entry.Key, &removedRetirementEvidence) |> ignore
        for entry in jp_declared_queued_resume_roots do
            if entry.Value.jobId = jobId then
                let mutable removedQueuedRoot = Unchecked.defaultof<JpDeclaredQueuedResumeRoot>
                jp_declared_queued_resume_roots.TryRemove(entry.Key, &removedQueuedRoot) |> ignore
        for entry in jp_declared_active_resume_roots do
            if entry.Value.jobId = jobId then
                let mutable removedActiveRoot = Unchecked.defaultof<JpDeclaredActiveResumeRoot>
                jp_declared_active_resume_roots.TryRemove(entry.Key, &removedActiveRoot) |> ignore
        for key in jp_declared_apply_continuations.Keys do
            match key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId ->
                let mutable removed = Unchecked.defaultof<JpDeclaredApplyContinuation>
                jp_declared_apply_continuations.TryRemove(key, &removed) |> ignore
            | _ -> ()
        for key in jp_declared_let_continuations.Keys do
            match key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId ->
                let mutable removed = Unchecked.defaultof<JpDeclaredLetContinuation>
                jp_declared_let_continuations.TryRemove(key, &removed) |> ignore
            | _ -> ()
        for key in jp_declared_sequence_continuations.Keys do
            match key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId ->
                let mutable removed = Unchecked.defaultof<JpDeclaredSequenceContinuation>
                jp_declared_sequence_continuations.TryRemove(key, &removed) |> ignore
            | _ -> ()
        for key in jp_declared_binary_numeric_continuations.Keys do
            match key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId ->
                let mutable removed = Unchecked.defaultof<JpDeclaredBinaryNumericContinuation>
                jp_declared_binary_numeric_continuations.TryRemove(key, &removed) |> ignore
            | _ -> ()
        for key in jp_declared_record_type_foldback_continuations.Keys do
            match key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId ->
                let mutable removed = Unchecked.defaultof<JpDeclaredRecordTypeFoldBackContinuation>
                jp_declared_record_type_foldback_continuations.TryRemove(key, &removed) |> ignore
            | _ -> ()
        for entry in jp_declared_resume_snapshots do
            match jpDeclaredResumeSnapshotKey entry.Value with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId ->
                let mutable removed = Unchecked.defaultof<JpDeclaredResumeSnapshotId>
                jp_declared_resume_snapshots.TryRemove(entry.Key, &removed) |> ignore
            | _ -> ()

    type JpDeclaredResumeLocatorPruneReceipt = private {
        applyLocatorsPruned : int
        letLocatorsPruned : int
        sequenceLocatorsPruned : int
        binaryNumericLocatorsPruned : int
        foldLocatorsPruned : int
        applyLocatorsLiveAfter : int
        letLocatorsLiveAfter : int
        sequenceLocatorsLiveAfter : int
        binaryNumericLocatorsLiveAfter : int
        foldLocatorsLiveAfter : int
    }

    let jpPruneStaleDeclaredResumeLocatorsForJob jobId : JpDeclaredResumeLocatorPruneReceipt =
        let mutable applyLocatorsPruned = 0
        let mutable letLocatorsPruned = 0
        let mutable sequenceLocatorsPruned = 0
        let mutable binaryNumericLocatorsPruned = 0
        let mutable foldLocatorsPruned = 0
        for entry in jp_declared_apply_continuations do
            match entry.Key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId && Option.isNone (jpTryDeclaredResumeSnapshotByRef entry.Value.continuationRef) ->
                let mutable removed = Unchecked.defaultof<JpDeclaredApplyContinuation>
                if jp_declared_apply_continuations.TryRemove(entry.Key, &removed) then applyLocatorsPruned <- applyLocatorsPruned + 1
            | _ -> ()
        for entry in jp_declared_let_continuations do
            match entry.Key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId && Option.isNone (jpTryDeclaredResumeSnapshotByRef entry.Value.continuationRef) ->
                let mutable removed = Unchecked.defaultof<JpDeclaredLetContinuation>
                if jp_declared_let_continuations.TryRemove(entry.Key, &removed) then letLocatorsPruned <- letLocatorsPruned + 1
            | _ -> ()
        for entry in jp_declared_sequence_continuations do
            match entry.Key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId && Option.isNone (jpTryDeclaredResumeSnapshotByRef entry.Value.continuationRef) ->
                let mutable removed = Unchecked.defaultof<JpDeclaredSequenceContinuation>
                if jp_declared_sequence_continuations.TryRemove(entry.Key, &removed) then sequenceLocatorsPruned <- sequenceLocatorsPruned + 1
            | _ -> ()
        for entry in jp_declared_binary_numeric_continuations do
            match entry.Key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId && Option.isNone (jpTryDeclaredResumeSnapshotByRef entry.Value.continuationRef) ->
                let mutable removed = Unchecked.defaultof<JpDeclaredBinaryNumericContinuation>
                if jp_declared_binary_numeric_continuations.TryRemove(entry.Key, &removed) then binaryNumericLocatorsPruned <- binaryNumericLocatorsPruned + 1
            | _ -> ()
        for entry in jp_declared_record_type_foldback_continuations do
            match entry.Key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId && Option.isNone (jpTryDeclaredResumeSnapshotByRef entry.Value.continuationRef) ->
                let mutable removed = Unchecked.defaultof<JpDeclaredRecordTypeFoldBackContinuation>
                if jp_declared_record_type_foldback_continuations.TryRemove(entry.Key, &removed) then foldLocatorsPruned <- foldLocatorsPruned + 1
            | _ -> ()
        let mutable applyLocatorsLiveAfter = 0
        let mutable letLocatorsLiveAfter = 0
        let mutable sequenceLocatorsLiveAfter = 0
        let mutable binaryNumericLocatorsLiveAfter = 0
        let mutable foldLocatorsLiveAfter = 0
        for entry in jp_declared_apply_continuations do
            match entry.Key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId -> applyLocatorsLiveAfter <- applyLocatorsLiveAfter + 1
            | _ -> ()
        for entry in jp_declared_let_continuations do
            match entry.Key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId -> letLocatorsLiveAfter <- letLocatorsLiveAfter + 1
            | _ -> ()
        for entry in jp_declared_sequence_continuations do
            match entry.Key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId -> sequenceLocatorsLiveAfter <- sequenceLocatorsLiveAfter + 1
            | _ -> ()
        for entry in jp_declared_binary_numeric_continuations do
            match entry.Key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId -> binaryNumericLocatorsLiveAfter <- binaryNumericLocatorsLiveAfter + 1
            | _ -> ()
        for entry in jp_declared_record_type_foldback_continuations do
            match entry.Key with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId -> foldLocatorsLiveAfter <- foldLocatorsLiveAfter + 1
            | _ -> ()
        { applyLocatorsPruned = applyLocatorsPruned
          letLocatorsPruned = letLocatorsPruned
          sequenceLocatorsPruned = sequenceLocatorsPruned
          binaryNumericLocatorsPruned = binaryNumericLocatorsPruned
          foldLocatorsPruned = foldLocatorsPruned
          applyLocatorsLiveAfter = applyLocatorsLiveAfter
          letLocatorsLiveAfter = letLocatorsLiveAfter
          sequenceLocatorsLiveAfter = sequenceLocatorsLiveAfter
          binaryNumericLocatorsLiveAfter = binaryNumericLocatorsLiveAfter
          foldLocatorsLiveAfter = foldLocatorsLiveAfter }

    type JpDeclaredResumeSnapshotPruneReceipt = private {
        liveBefore : int
        reachable : int
        pruned : int
        liveOwnerProtected : int
        liveAfter : int
        staleLocatorsPruned : int
        applyLocatorsPruned : int
        letLocatorsPruned : int
        sequenceLocatorsPruned : int
        binaryNumericLocatorsPruned : int
        foldLocatorsPruned : int
        applyLocatorsLiveAfter : int
        letLocatorsLiveAfter : int
        sequenceLocatorsLiveAfter : int
        binaryNumericLocatorsLiveAfter : int
        foldLocatorsLiveAfter : int
    }

    let jpPruneUnreachableDeclaredResumeSnapshotsForJob jobId freshContinuationRef : JpDeclaredResumeSnapshotPruneReceipt =
        let roots = System.Collections.Generic.Stack<JpWorkContinuationRef>()
        let reachable = System.Collections.Generic.HashSet<CompilerIdentityKernel.ContentDigest>()
        let addRoot continuationRef =
            let digest = JpWorkContinuationRefOps.digest continuationRef
            if reachable.Add digest then roots.Push continuationRef
        // Locator dictionaries are indexes, not liveness authority. Rooting every historical locator
        // makes the graph self-justifying because stale child and parent snapshots keep each other alive.
        // The just-registered continuation is the only fresh root; traversal preserves its typed ancestry.
        addRoot freshContinuationRef
        let mutable installedTarget = Unchecked.defaultof<JpWorkContinuationRef>
        if jp_declared_resume_targets.TryGetValue(jobId, &installedTarget) then addRoot installedTarget
        for executionRoot in jp_declared_direct_resume_execution_roots do
            if executionRoot.Value > 0 then
                let mutable snapshot = Unchecked.defaultof<JpDeclaredResumeSnapshotId>
                if jp_declared_resume_snapshots.TryGetValue(executionRoot.Key, &snapshot) then
                    match jpDeclaredResumeSnapshotKey snapshot with
                    | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId ->
                        match snapshot with
                        | JpDeclaredApplyResumeSnapshot(_, continuation) -> addRoot continuation.continuationRef
                        | JpDeclaredLetResumeSnapshot(_, continuation) -> addRoot continuation.continuationRef
                        | JpDeclaredSequenceResumeSnapshot(_, continuation) -> addRoot continuation.continuationRef
                        | JpDeclaredBinaryNumericResumeSnapshot(_, continuation) -> addRoot continuation.continuationRef
                        | JpDeclaredRecordTypeFoldBackResumeSnapshot(_, continuation) -> addRoot continuation.continuationRef
                    | _ -> ()
        // A queue item is an affine owner of its resume PC.  Root it before walking
        // ancestry so periodic/pressure pruning cannot turn a live suspended item into
        // TargetMissing merely because it is not currently installed as the executor target.
        for queuedRoot in jpDeclaredQueuedResumeRootsForJob jobId do
            addRoot queuedRoot
        // The current evaluator-safe PC is owned by the running attempt before it
        // becomes a queued resume target. Keep that attempt-local root in the same
        // ancestry walk so pruning cannot manufacture TargetMissing mid-slice.
        for activeRoot in jpDeclaredActiveResumeRootsForJob jobId do
            addRoot activeRoot
        while roots.Count > 0 do
            let current = roots.Pop()
            match jpTryDeclaredResumeSnapshotByRef current with
            | Some snapshot ->
                match jpDeclaredResumeSnapshotKey snapshot with
                | JpDeclaredEvaluatorPcKey(ownerJobId, _, JpDeclaredEvaluatorNestedPc parentContinuation)
                    when ownerJobId = jobId -> addRoot parentContinuation
                | JpDeclaredEvaluatorPcKey(ownerJobId, _, JpDeclaredEvaluatorTailBridgePc(parentContinuation, _, _))
                    when ownerJobId = jobId -> addRoot parentContinuation
                | JpDeclaredEvaluatorPcKey(ownerJobId, _, JpDeclaredEvaluatorOpaquePc(Some parentContinuation, _))
                    when ownerJobId = jobId -> addRoot parentContinuation
                | _ -> ()
            | None -> ()
        let mutable liveBefore = 0
        let mutable pruned = 0
        let mutable liveOwnerProtected = 0
        for entry in jp_declared_resume_snapshots do
            match jpDeclaredResumeSnapshotKey entry.Value with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId ->
                liveBefore <- liveBefore + 1
                if not (reachable.Contains entry.Key) then
                    // Re-read affine owners at the destructive edge. Root discovery is a
                    // snapshot; a successor may acquire queue/active ownership after that
                    // snapshot but before this loop reaches the same continuation.
                    let continuationRef = JpWorkContinuationRefOps.create entry.Key
                    let liveOwners = jpDeclaredResumeSnapshotLiveOwnerCounts continuationRef
                    if JpDeclaredResumeSnapshotLiveOwnerCountsOps.total liveOwners > 0 then
                        liveOwnerProtected <- liveOwnerProtected + 1
                    else
                        let mutable removed = Unchecked.defaultof<JpDeclaredResumeSnapshotId>
                        if jp_declared_resume_snapshots.TryRemove(entry.Key, &removed) then
                            jpRememberDeclaredResumeSnapshotRetirementEvidence entry.Key jobId JpDeclaredResumeSnapshotUnreachablePrune
                            pruned <- pruned + 1
            | _ -> ()
        if pruned > 0 then jpNoteDeclaredResumeEvidence jobId |> ignore
        let locatorPrune = jpPruneStaleDeclaredResumeLocatorsForJob jobId
        let staleLocatorsPruned =
            locatorPrune.applyLocatorsPruned
            + locatorPrune.letLocatorsPruned
            + locatorPrune.sequenceLocatorsPruned
            + locatorPrune.binaryNumericLocatorsPruned
            + locatorPrune.foldLocatorsPruned
        { liveBefore = liveBefore
          reachable = reachable.Count
          pruned = pruned
          liveOwnerProtected = liveOwnerProtected
          liveAfter = liveBefore - pruned
          staleLocatorsPruned = staleLocatorsPruned
          applyLocatorsPruned = locatorPrune.applyLocatorsPruned
          letLocatorsPruned = locatorPrune.letLocatorsPruned
          sequenceLocatorsPruned = locatorPrune.sequenceLocatorsPruned
          binaryNumericLocatorsPruned = locatorPrune.binaryNumericLocatorsPruned
          foldLocatorsPruned = locatorPrune.foldLocatorsPruned
          applyLocatorsLiveAfter = locatorPrune.applyLocatorsLiveAfter
          letLocatorsLiveAfter = locatorPrune.letLocatorsLiveAfter
          sequenceLocatorsLiveAfter = locatorPrune.sequenceLocatorsLiveAfter
          binaryNumericLocatorsLiveAfter = locatorPrune.binaryNumericLocatorsLiveAfter
          foldLocatorsLiveAfter = locatorPrune.foldLocatorsLiveAfter }

    type JpDeclaredResumeSnapshotPruneBasisId =
        | JpDeclaredResumeSnapshotPeriodicPrune
        | JpDeclaredResumeSnapshotPressurePrune

    let jpDeclaredResumeSnapshotPruneBasisText = function
        | JpDeclaredResumeSnapshotPeriodicPrune -> "Periodic256"
        | JpDeclaredResumeSnapshotPressurePrune -> "Pressure64"

    // A prune scans every snapshot (all jobs), so its trigger must be geometric: prune once the live count has doubled
    // since the last prune left it. Pruning every 64/256 continuations while most snapshots stayed reachable cost
    // O(live x continuations): apps/spiral's declared bodies ground in this scan at under one core (FRONTIER.md 55).
    let mutable private jpDeclaredResumeSnapshotPruneHighWater = 0

    let jpDeclaredResumeSnapshotPruneBasis (_continuationOrdinal:int64) (liveSnapshotCount:int) : JpDeclaredResumeSnapshotPruneBasisId option =
        if liveSnapshotCount >= max 1024 (2 * jpDeclaredResumeSnapshotPruneHighWater) then
            Some JpDeclaredResumeSnapshotPressurePrune
        else None

    let jpMaybePruneDeclaredResumeSnapshots jobId continuationOrdinal freshContinuationRef =
        match jpDeclaredResumeSnapshotPruneBasis continuationOrdinal jp_declared_resume_snapshots.Count with
        | None -> ()
        | Some pruneBasis ->
            let receipt = jpPruneUnreachableDeclaredResumeSnapshotsForJob jobId freshContinuationRef
            jpDeclaredResumeSnapshotPruneHighWater <- jp_declared_resume_snapshots.Count
            let occurrence, shouldEmit =
                DiagJson.sparseLogDecision ("jp_declared_resume_snapshot_pruned|" + string jobId + "|" + jpDeclaredResumeSnapshotPruneBasisText pruneBasis) 64L
            if receipt.pruned > 0 || receipt.staleLocatorsPruned > 0 || shouldEmit then
                DiagJson.emit (
                    FastRuntimeFormat.format
                        "{\"kind\":\"jp_declared_resume_snapshot_pruned\",\"work_job_id\":%d,\"continuation_ordinal\":%d,\"prune_basis_du\":%s,\"live_before\":%d,\"reachable\":%d,\"pruned\":%d,\"live_owner_protected\":%d,\"live_after\":%d,\"stale_locators_pruned\":%d,\"apply_locators_pruned\":%d,\"let_locators_pruned\":%d,\"sequence_locators_pruned\":%d,\"binary_numeric_locators_pruned\":%d,\"fold_locators_pruned\":%d,\"apply_locators_live_after\":%d,\"let_locators_live_after\":%d,\"sequence_locators_live_after\":%d,\"binary_numeric_locators_live_after\":%d,\"fold_locators_live_after\":%d,\"occurrence_count\":%d,\"authority\":\"fresh_pc_installed_target_queue_and_active_execution_roots_ancestry_plus_destructive_edge_owner_recheck\",\"next\":\"keep_affine_snapshot_and_locator_memory_bounded_without_deleting_live_ancestry\"}"
                        [| box jobId; box continuationOrdinal; box (DiagJson.esc (jpDeclaredResumeSnapshotPruneBasisText pruneBasis)); box receipt.liveBefore; box receipt.reachable; box receipt.pruned; box receipt.liveOwnerProtected; box receipt.liveAfter; box receipt.staleLocatorsPruned; box receipt.applyLocatorsPruned; box receipt.letLocatorsPruned; box receipt.sequenceLocatorsPruned; box receipt.binaryNumericLocatorsPruned; box receipt.foldLocatorsPruned; box receipt.applyLocatorsLiveAfter; box receipt.letLocatorsLiveAfter; box receipt.sequenceLocatorsLiveAfter; box receipt.binaryNumericLocatorsLiveAfter; box receipt.foldLocatorsLiveAfter; box occurrence |])

    let jpDeclaredResumeSnapshotLiveCountForJob jobId =
        let mutable count = 0
        for entry in jp_declared_resume_snapshots do
            match jpDeclaredResumeSnapshotKey entry.Value with
            | JpDeclaredEvaluatorPcKey(ownerJobId, _, _) when ownerJobId = jobId -> count <- count + 1
            | _ -> ()
        count

    type JpDeclaredEvaluatorSliceYieldCause =
        | JpDeclaredSliceYieldCheckpointInterval
        | JpDeclaredSliceYieldOperationBudget
        | JpDeclaredSliceYieldOperationBoundaryBudget
        | JpDeclaredSliceYieldTypedCarrierBlocked

    let jpDeclaredEvaluatorSliceYieldCauseText = function
        | JpDeclaredSliceYieldCheckpointInterval -> "CheckpointInterval"
        | JpDeclaredSliceYieldOperationBudget -> "OperationBudget"
        | JpDeclaredSliceYieldOperationBoundaryBudget -> "OperationBoundaryBudget"
        | JpDeclaredSliceYieldTypedCarrierBlocked -> "TypedCarrierBlocked"

    exception JpDeclaredEvaluatorSliceYield of JpDeclaredEvaluatorSliceYieldCause * JpWorkContinuationRef
    // Terminal failure cutover is cooperative: the worker that owns Running is the
    // only authority allowed to retire it. A local evaluator unwind is caught at the
    // execution-plan boundary and reified as JpWorkExecutionCancelled; the scheduler
    // then writes the normal cancellation receipt without letting an observer steal
    // the running cursor.
    exception JpTerminalFailureRunningCutoverCancellation

    type JpWorkDependencyRef = private JpWorkDependencyRef of CompilerIdentityKernel.ContentDigest
    module JpWorkDependencyRefOps =
        let create digest = JpWorkDependencyRef digest
        let digest (JpWorkDependencyRef digest) = digest
        let text value = value |> digest |> CompilerIdentityKernel.ContentDigest.text

    type JpChildWorkRef = private JpChildWorkRef of CompilerIdentityKernel.ContentDigest
    module JpChildWorkRefOps =
        let create digest = JpChildWorkRef digest
        let digest (JpChildWorkRef digest) = digest
        let text value = value |> digest |> CompilerIdentityKernel.ContentDigest.text

    type JpPatternMissDeferralAuthority =
        | JpPatternMissControlOnlyReplay
        | JpPatternMissRequiredCodegenBody

    let jpPatternMissDeferralAuthorityText = function
        | JpPatternMissControlOnlyReplay -> "ControlOnlyReplay"
        | JpPatternMissRequiredCodegenBody -> "RequiredCodegenBody"

    type JpPatternMissDeferralCommand = private {
        signal : EvalReplayValueStore.EvaluatorPatternMissDeferredSignal
        decision : EvalReplayValueStore.EvaluatorPatternMissDecision
        reservation : EvalReplayValueStore.EvaluatorPatternMissDeferralReservation
        rawDisposition : EvalReplayValueStore.EvaluatorPatternMissDeferralDisposition
        effectiveDisposition : EvalReplayValueStore.EvaluatorPatternMissDeferralDisposition
        authority : JpPatternMissDeferralAuthority
        repeatCount : int64
        stableAgeMs : int64
    }

    module JpPatternMissDeferralCommandOps =
        let create signal authorityRole =
            let decision = EvalReplayValueStore.evaluatorPatternMissDeferredSignalDecision signal
            let reservation = EvalReplayValueStore.evaluatorPatternMissDeferredSignalReservation signal
            let rawDisposition =
                EvalReplayValueStore.evaluatorPatternMissDeferralDisposition decision reservation
            let authority, effectiveDisposition =
                match rawDisposition, authorityRole with
                | EvalReplayValueStore.EvaluatorPatternMissDeferralRetireStableReplaySentinel, JpCodegenBodyProducer _ ->
                    JpPatternMissRequiredCodegenBody,
                    EvalReplayValueStore.EvaluatorPatternMissDeferralRequeue
                | _ ->
                    JpPatternMissControlOnlyReplay,
                    rawDisposition
            let repeatCount, stableAgeMs =
                EvalReplayValueStore.evaluatorPatternMissDeferralStasis reservation
            { signal = signal
              decision = decision
              reservation = reservation
              rawDisposition = rawDisposition
              effectiveDisposition = effectiveDisposition
              authority = authority
              repeatCount = repeatCount
              stableAgeMs = stableAgeMs }

        let preservesRequiredCodegenBody command =
            match command.authority with
            | JpPatternMissRequiredCodegenBody -> true
            | JpPatternMissControlOnlyReplay -> false

        let decisionText command =
            EvalReplayValueStore.evaluatorPatternMissDecisionText command.decision

        let rawDispositionText command =
            EvalReplayValueStore.evaluatorPatternMissDeferralDispositionText command.rawDisposition

        let effectiveDispositionText command =
            EvalReplayValueStore.evaluatorPatternMissDeferralDispositionText command.effectiveDisposition

        let authorityText command =
            jpPatternMissDeferralAuthorityText command.authority

        let originText command =
            command.signal
            |> EvalReplayValueStore.evaluatorPatternMissDeferredSignalOrigin
            |> EvalReplayValueStore.evaluatorPatternMissProducerOriginText

        let signalText command =
            EvalReplayValueStore.evaluatorPatternMissDeferredSignalText command.signal

        let diagnosticFacts command =
            let baseFacts =
                EvalReplayValueStore.evaluatorPatternMissDeferredSignalFacts command.signal
            match command.authority with
            | JpPatternMissRequiredCodegenBody ->
                baseFacts
                |> Set.add DiagnosticClassifier.DiagnosticPatternMissRequiredCodegenBody
            | JpPatternMissControlOnlyReplay ->
                baseFacts
                |> Set.add DiagnosticClassifier.DiagnosticPatternMissControlOnlyReplay

        let diagnosticFactText command =
            diagnosticFacts command
            |> DiagnosticClassifier.factSetText

        let diagnosticFactsWithStasisCancelled command =
            diagnosticFacts command
            |> Set.add DiagnosticClassifier.DiagnosticPatternMissStasisCancelled

        let diagnosticFactTextWithStasisCancelled command =
            diagnosticFactsWithStasisCancelled command
            |> DiagnosticClassifier.factSetText

    type JpWorkExecutionOutcome =
        | JpWorkExecutionCompleted
        | JpWorkExecutionYielded of continuationRef:JpWorkContinuationRef * cause:JpDeclaredEvaluatorSliceYieldCause
        | JpWorkExecutionAwaiting of dependencyRef:JpWorkDependencyRef * continuationRef:JpWorkContinuationRef
        | JpWorkExecutionSpawned of childWorkRef:JpChildWorkRef * continuationRef:JpWorkContinuationRef
        | JpWorkExecutionFailed of failure:JpWorkFailure
        | JpWorkExecutionCancelled of cancellation:JpWorkCancellation
        | JpWorkExecutionPatternMissDeferredControl of signal:EvalReplayValueStore.EvaluatorPatternMissDeferredSignal

    // Declared-body work now uses a bounded execution policy. EApply and ELet persist
    // typed evaluator PCs before child calls and at slice boundaries; a slice yield
    // unwinds to executeWork, releases the worker, and re-enters through the saved PC.
    // Synthetic entrance yield was retired once executable evaluator PCs became available; bounded yields now originate only at persisted evaluator safe points.
    type JpWorkSliceBudget = private {
        maxOperations : int
        checkpointInterval : int
    }

    module JpWorkSliceBudgetOps =
        let tryCreate maxOperations checkpointInterval =
            if maxOperations <= 0 || checkpointInterval <= 0 || checkpointInterval > maxOperations then None
            else Some { maxOperations = maxOperations; checkpointInterval = checkpointInterval }
        let maxOperations budget = budget.maxOperations
        let checkpointInterval budget = budget.checkpointInterval

    type JpWorkSliceBudgetBasisId =
        | JpDeclaredBodyDefaultSlice
        | JpDeclaredBodyPureSlice
        | JpDeclaredBodyStableRuntimeEffectSlice of effectKind:JpRuntimeEffectKind * effectScope:JpRuntimeEffectScope

    let jpWorkSliceBudgetBasisText = function
        | JpDeclaredBodyDefaultSlice -> "DeclaredBodyDefaultSlice"
        | JpDeclaredBodyPureSlice -> "DeclaredBodyPureSlice"
        | JpDeclaredBodyStableRuntimeEffectSlice(effectKind, effectScope) ->
            "DeclaredBodyStableRuntimeEffectSlice(effect=" + jpRuntimeEffectKindText effectKind
            + "|scope=" + jpRuntimeEffectScopeText effectScope + ")"

    type JpWorkExecutionPolicy =
        | JpWorkExecutionRunToCompletionLegacy
        | JpWorkExecutionBoundedSlice of basis:JpWorkSliceBudgetBasisId * budget:JpWorkSliceBudget

    let jpWorkExecutionPolicyText = function
        | JpWorkExecutionRunToCompletionLegacy -> "RunToCompletionLegacy"
        | JpWorkExecutionBoundedSlice(basis, budget) ->
            sprintf "BoundedSlice(basis=%s|max_operations=%d|checkpoint_interval=%d)"
                (jpWorkSliceBudgetBasisText basis)
                (JpWorkSliceBudgetOps.maxOperations budget)
                (JpWorkSliceBudgetOps.checkpointInterval budget)

    type JpWorkExecutionPlan = private {
        specializationPlan : CompilerKernelV2.JoinPointSpecializationPlan
        specializationInteractionReceipt : CompilerKernelV2.SpecializationInteractionReceipt
        computationMetadata : JpWorkComputationMetadata
        workNode : JpSpecializationWorkNode
        authorityRole : JpWorkAuthorityRole
        siteId : CompilerIdentityKernel.WorkSiteId
        shapeId : CompilerIdentityKernel.WorkShapeId
        executionPolicy : JpWorkExecutionPolicy
        execute : JpSpecializationWorkNode -> CompilerKernelV2.PortableEffect<JpWorkExecutionOutcome>
        cancel : JpWorkCancellationRequest -> CompilerKernelV2.PortableEffect<unit>
    }

    // A typed-carrier blocker is not runnable merely because time passed. It wakes
    // only when typed continuation identity or structural resume evidence changes.
    // Queue scans compare only this cheap typed evidence; planability itself is revalidated at execution entry.
    type JpTypedCarrierWakeEvidence = private {
        continuationOrdinal : int64
        structuralEvidenceRevision : int64
    }

    type JpTypedCarrierProofGate =
        | JpTypedCarrierProofGateOpen
        | JpTypedCarrierProofGateAwaitingEvidence of observed:JpTypedCarrierWakeEvidence

    let jpTypedCarrierProofGateText = function
        | JpTypedCarrierProofGateOpen -> "Open"
        | JpTypedCarrierProofGateAwaitingEvidence _ -> "AwaitTypedResumeEvidenceRevision"

    type JpWorkItem = private {
        operational : JpWorkOperationalCursor
        executionPlan : JpWorkExecutionPlan
        semanticResumeContinuation : JpWorkContinuationRef option
        typedCarrierProofGate : JpTypedCarrierProofGate
    }
    with
        member item.workUnit = JpWorkOperationalCursor.workUnit item.operational
        member item.identity = item.workUnit |> CompilerKernelV2.WorkUnitIdOps.binding
        member item.generation = JpWorkOperationalCursor.generation item.operational
        member item.ownerIdentity = item.operational |> JpWorkOperationalCursor.owner |> CompilerKernelV2.WorkOwnerCapabilityOps.owner
        member item.specializationPlan = item.executionPlan.specializationPlan
        member item.specializationInteractionReceipt = item.executionPlan.specializationInteractionReceipt
        member item.computationMetadata = item.executionPlan.computationMetadata
        member item.workNode = item.executionPlan.workNode
        member item.authorityRole = item.executionPlan.authorityRole
        member item.siteId = item.executionPlan.siteId
        member item.shapeId = item.executionPlan.shapeId
        member item.executionPolicy = item.executionPlan.executionPolicy
        member item.site = CompilerIdentityKernel.WorkSiteIdOps.text item.executionPlan.siteId
        member item.shape = CompilerIdentityKernel.WorkShapeIdOps.text item.executionPlan.shapeId
        member item.cost = JpWorkOperationalCursor.semanticCost item.operational
        member item.commitOrdinal = JpWorkOperationalCursor.commitOrdinal item.operational
        member item.execute = item.executionPlan.execute
        member item.cancel = item.executionPlan.cancel
        member item.semanticResume = item.semanticResumeContinuation

    let jpTerminalFailureCutoverCancellation workUnit commitOrdinal =
        let reasonId =
            CompilerKernelV2.OperationalReasonIdOps.create
                "typed_terminal_failure_cutover_running_owner_cancel"
        let cancellationRef =
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-terminal-failure-running-owner-cancel"
                (CompilerKernelV2.WorkUnitIdOps.digestText workUnit
                 + "|job=" + string commitOrdinal)
        JpHostCancellation(reasonId, cancellationRef)

    let jpTerminalFailureCutoverCancellationOutcome workUnit commitOrdinal =
        jpTerminalFailureCutoverCancellation workUnit commitOrdinal
        |> JpWorkExecutionCancelled

    let jpDeclaredContinuationOrdinalCurrent jobId =
        let mutable current = 0L
        if jp_declared_continuation_ordinals.TryGetValue(jobId, &current) then current else 0L

    let jpTypedCarrierWakeEvidenceCurrent jobId : JpTypedCarrierWakeEvidence = {
        continuationOrdinal = jpDeclaredContinuationOrdinalCurrent jobId
        structuralEvidenceRevision = jpDeclaredResumeEvidenceRevisionCurrent jobId
    }

    let jpWorkItemTypedCarrierProofRunnable (item:JpWorkItem) =
        match item.typedCarrierProofGate with
        | JpTypedCarrierProofGateOpen -> true
        | JpTypedCarrierProofGateAwaitingEvidence observed ->
            let current = jpTypedCarrierWakeEvidenceCurrent item.commitOrdinal
            current.continuationOrdinal > observed.continuationOrdinal
            || current.structuralEvidenceRevision > observed.structuralEvidenceRevision

    let jpRetainWorkItemQueuedResumeRoot (item:JpWorkItem) =
        match item.semanticResume with
        | Some continuationRef -> jpRetainDeclaredQueuedResumeRoot item.commitOrdinal continuationRef
        | None -> ()

    let jpReleaseWorkItemQueuedResumeRoot (item:JpWorkItem) =
        match item.semanticResume with
        | Some continuationRef -> jpReleaseDeclaredQueuedResumeRoot item.commitOrdinal continuationRef
        | None -> ()

    let jpWorkItemDeclarationBindingId (item:JpWorkItem) =
        match item.identity with
        | CompilerKernelV2.WorkDeclarationBinding binding -> binding
        | CompilerKernelV2.WorkKernelAuthorityBinding authorityRef ->
            invalidOp ("join-point work unexpectedly carried kernel authority binding: " + CompilerIdentityKernel.ContentDigest.text authorityRef)

    let jpWorkItemOwnerBindingId (item:JpWorkItem) =
        match item.ownerIdentity with
        | CompilerKernelV2.WorkOwnerBinding binding -> binding
        | CompilerKernelV2.WorkOwnerAuthority authorityRef ->
            invalidOp ("join-point work unexpectedly carried kernel owner authority: " + CompilerIdentityKernel.ContentDigest.text authorityRef)


    type JpSpecializationQueueAdmission =
        | JpSpecializationQueueAdmitted of depthAfter:int
        | JpSpecializationQueueBackpressured of depth:int * capacity:int

    type JpSpecializationQueueRemoval =
        | JpSpecializationQueueRemoved of item:JpWorkItem * depthAfter:int
        | JpSpecializationQueueEmpty

    type JpSpecializationRunnableQueueRemoval =
        | JpSpecializationRunnableQueueRemoved of item:JpWorkItem * depthAfter:int * laneAdmission:JpWorkerLaneAdmission
        | JpSpecializationRunnableQueueDeferred of physicalDepth:int
        | JpSpecializationRunnableQueueEmpty

    type JpSpecializationWorkerIdleWaitPolicy =
        | JpWorkerIdleWaitEmptyQueue of fallbackTimeoutMs:int
        | JpWorkerIdleWaitDeferredTypedCarrierEvidence of fallbackTimeoutMs:int

    let jpSpecializationWorkerIdleWaitTimeoutMs = function
        | JpWorkerIdleWaitEmptyQueue fallbackTimeoutMs
        | JpWorkerIdleWaitDeferredTypedCarrierEvidence fallbackTimeoutMs -> fallbackTimeoutMs

    // Idle workers wake on jp_specialization_runnable_signal (and a worker that takes an item passes the signal
    // on while more are queued); this timeout is only the lost-pulse fail-safe. At 2 ms, idle workers rescanned
    // every queue ~500 times a second each: ~22% of a slow compile's CPU.
    let jp_worker_idle_empty_queue_policy = JpWorkerIdleWaitEmptyQueue 20
    let jp_worker_idle_deferred_typed_carrier_policy = JpWorkerIdleWaitDeferredTypedCarrierEvidence 256

    let jpSpecializationQueueAdmissionText = function
        | JpSpecializationQueueAdmitted depthAfter -> sprintf "Admitted(depth_after=%d)" depthAfter
        | JpSpecializationQueueBackpressured(depth, capacity) -> sprintf "Backpressured(depth=%d|capacity=%d)" depth capacity

    let jpWorkComputationMetadataForItem (item:JpWorkItem) fallbackInstantiationId =
        match item.computationMetadata with
        | JpWorkComputationMetadata descriptor ->
            descriptor.computationIdentity,
            descriptor.instantiationId,
            descriptor.memoProbe,
            descriptor.authorityRole
        | JpWorkComputationMetadataUnavailable ->
            JpAnonymousComputation(jpWorkItemDeclarationBindingId item, item.siteId),
            fallbackInstantiationId,
            JpComputationMemoNotApplicable,
            item.authorityRole

    type JpDurationProfileEntry = private {
        workUnitRef : CompilerIdentityKernel.ContentDigest
        bindingId : CompilerKernelV2.StableBindingId
        siteId : CompilerIdentityKernel.WorkSiteId
        shapeId : CompilerIdentityKernel.WorkShapeId
        intent : JpSpecializationIntent
        authorityRole : JpWorkAuthorityRole
        memoProbe : JpComputationMemoProbe
        duration : CompilerKernelV2.WallTime
        semanticCost : CompilerKernelV2.SemanticCost
        proofRef : CompilerIdentityKernel.ContentDigest
    }

    type JpDurationShapeSummary = private {
        shapeId : CompilerIdentityKernel.WorkShapeId
        sampleCount : CompilerKernelV2.NodeCount
        p50 : CompilerKernelV2.WallTime
        p90 : CompilerKernelV2.WallTime
        p99 : CompilerKernelV2.WallTime
        maxDuration : CompilerKernelV2.WallTime
        totalDuration : CompilerKernelV2.WallTime
        slowCount : CompilerKernelV2.NodeCount
        summaryRef : CompilerIdentityKernel.ContentDigest
    }

    type JpDurationCohortSummary = private {
        shapeId : CompilerIdentityKernel.WorkShapeId
        intent : JpSpecializationIntent
        authorityRole : JpWorkAuthorityRole
        memoProbe : JpComputationMemoProbe
        sampleCount : CompilerKernelV2.NodeCount
        p50 : CompilerKernelV2.WallTime
        p90 : CompilerKernelV2.WallTime
        p99 : CompilerKernelV2.WallTime
        maxDuration : CompilerKernelV2.WallTime
        totalDuration : CompilerKernelV2.WallTime
        slowCount : CompilerKernelV2.NodeCount
        summaryRef : CompilerIdentityKernel.ContentDigest
    }

    type JpDurationHeavyTailClass =
        | JpDurationBalanced
        | JpDurationConcentrated of top10ConcentrationBp:CompilerKernelV2.BasisPoints
        | JpDurationTopTenDominated of top10ConcentrationBp:CompilerKernelV2.BasisPoints

    let jpDurationHeavyTailClassText = function
        | JpDurationBalanced -> "balanced"
        | JpDurationConcentrated concentrationBp ->
            sprintf "concentrated(top10_bp=%d)" (CompilerKernelV2.BasisPoints.value concentrationBp)
        | JpDurationTopTenDominated concentrationBp ->
            sprintf "top10_dominated(top10_bp=%d)" (CompilerKernelV2.BasisPoints.value concentrationBp)

    type JpDurationProfileSnapshot = private {
        completedCount : CompilerKernelV2.NodeCount
        totalDuration : CompilerKernelV2.WallTime
        top10Duration : CompilerKernelV2.WallTime
        top10ConcentrationBp : CompilerKernelV2.BasisPoints
        heavyTailClass : JpDurationHeavyTailClass
        topEntries : JpDurationProfileEntry list
        shapeSummaries : JpDurationShapeSummary list
        cohortSummaries : JpDurationCohortSummary list
        profileRef : CompilerIdentityKernel.ContentDigest
    }

    type JpDurationProfileMessage =
        | JpDurationProfileNote of
            entry:JpDurationProfileEntry
            * reply:CompilerKernelV2.PortableOneShotCell<JpDurationProfileSnapshot option>
        | JpDurationProfileRead of
            reply:CompilerKernelV2.PortableOneShotCell<JpDurationProfileSnapshot>

    let jpDurationProfileMailbox =
        CompilerKernelV2.CompilerRuntimeKernel.mailbox<JpDurationProfileMessage>
            "jp-duration-profile"
            CompilerKernelV2.PortableObserverLane
            0
            CompilerKernelV2.MailboxFailClosed

    let jpDurationPercentile percentileValue (values:CompilerKernelV2.WallTime list) =
        match values |> List.map CompilerKernelV2.Measured.value |> List.sort with
        | [] -> CompilerKernelV2.Measured.zero<CompilerKernelV2.WallTimeUnit>
        | sorted ->
            let ordinal =
                System.Math.Ceiling((float percentileValue / 100.0) * float sorted.Length)
                |> int
                |> max 1
                |> min sorted.Length
            CompilerKernelV2.Measured.create<CompilerKernelV2.WallTimeUnit> "jpDurationPercentile" sorted.[ordinal - 1]

    let jpDurationProfileSnapshot entries completedCount =
        let wall value = CompilerKernelV2.Measured.create<CompilerKernelV2.WallTimeUnit> "jpDurationProfileWall" (max 0L value)
        let nodeCount value = CompilerKernelV2.Measured.ofInt<CompilerKernelV2.NodeCountUnit> "jpDurationProfileNodeCount" (max 0 value)
        let totalDuration =
            entries
            |> List.fold (fun total entry -> CompilerKernelV2.Measured.add total entry.duration)
                (CompilerKernelV2.Measured.zero<CompilerKernelV2.WallTimeUnit>)
        let rankedEntries = entries |> List.sortByDescending (fun entry -> CompilerKernelV2.Measured.value entry.duration)
        let topEntries = rankedEntries |> List.truncate 20
        let top10Duration =
            rankedEntries
            |> List.truncate 10
            |> List.fold (fun total entry -> CompilerKernelV2.Measured.add total entry.duration)
                (CompilerKernelV2.Measured.zero<CompilerKernelV2.WallTimeUnit>)
        let totalDurationValue = CompilerKernelV2.Measured.value totalDuration
        let top10DurationValue = CompilerKernelV2.Measured.value top10Duration
        let top10ConcentrationBp =
            if totalDurationValue <= 0L then CompilerKernelV2.BasisPoints.zero
            else CompilerKernelV2.BasisPoints.create (min 10000L ((top10DurationValue * 10000L) / totalDurationValue))
        let heavyTailClass =
            let bp = CompilerKernelV2.BasisPoints.value top10ConcentrationBp
            if bp >= 6000L then JpDurationTopTenDominated top10ConcentrationBp
            elif bp >= 3500L then JpDurationConcentrated top10ConcentrationBp
            else JpDurationBalanced
        let shapeSummaries =
            entries
            |> List.groupBy (fun entry -> entry.shapeId)
            |> List.map (fun (shapeId, grouped) ->
                let shapeText = CompilerIdentityKernel.WorkShapeIdOps.text shapeId
                let durations = grouped |> List.map (fun entry -> entry.duration)
                let p50 = jpDurationPercentile 50 durations
                let p90 = jpDurationPercentile 90 durations
                let p99 = jpDurationPercentile 99 durations
                let maxDuration = durations |> List.fold CompilerKernelV2.Measured.maxValue (wall 0L)
                let totalDuration = durations |> List.fold CompilerKernelV2.Measured.add (wall 0L)
                let slowCount =
                    durations
                    |> List.filter (fun duration -> CompilerKernelV2.Measured.value duration >= 3000L)
                    |> List.length
                    |> nodeCount
                let sampleCount = nodeCount grouped.Length
                let summaryRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-duration-shape-summary"
                        (FastRuntimeFormat.format "shape=%s|count=%d|p50=%d|p90=%d|p99=%d|max=%d|total=%d|slow=%d" [|
                            box shapeText
                            box (CompilerKernelV2.Measured.value sampleCount)
                            box (CompilerKernelV2.Measured.value p50)
                            box (CompilerKernelV2.Measured.value p90)
                            box (CompilerKernelV2.Measured.value p99)
                            box (CompilerKernelV2.Measured.value maxDuration)
                            box (CompilerKernelV2.Measured.value totalDuration)
                            box (CompilerKernelV2.Measured.value slowCount) |])
                { shapeId = shapeId
                  sampleCount = sampleCount
                  p50 = p50
                  p90 = p90
                  p99 = p99
                  maxDuration = maxDuration
                  totalDuration = totalDuration
                  slowCount = slowCount
                  summaryRef = summaryRef })
            |> List.sortByDescending (fun summary -> CompilerKernelV2.Measured.value summary.totalDuration)
        let cohortSummaries =
            entries
            |> List.groupBy (fun entry -> struct(entry.shapeId, entry.intent, entry.authorityRole, entry.memoProbe))
            |> List.map (fun (struct(shapeId, intent, authorityRole, memoProbe), grouped) ->
                let shapeText = CompilerIdentityKernel.WorkShapeIdOps.text shapeId
                let intentText = jpSpecializationIntentText intent
                let authorityRoleText = jpWorkAuthorityRoleText authorityRole
                let memoProbeText = jpComputationMemoProbeText memoProbe
                let durations = grouped |> List.map (fun entry -> entry.duration)
                let p50 = jpDurationPercentile 50 durations
                let p90 = jpDurationPercentile 90 durations
                let p99 = jpDurationPercentile 99 durations
                let maxDuration = durations |> List.fold CompilerKernelV2.Measured.maxValue (wall 0L)
                let totalDuration = durations |> List.fold CompilerKernelV2.Measured.add (wall 0L)
                let slowCount =
                    durations
                    |> List.filter (fun duration -> CompilerKernelV2.Measured.value duration >= 3000L)
                    |> List.length
                    |> nodeCount
                let sampleCount = nodeCount grouped.Length
                let summaryRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-duration-cohort-summary"
                        (FastRuntimeFormat.format "shape=%s|intent=%s|role=%s|memo=%s|count=%d|p50=%d|p90=%d|p99=%d|max=%d|total=%d|slow=%d" [|
                            box shapeText
                            box intentText
                            box authorityRoleText
                            box memoProbeText
                            box (CompilerKernelV2.Measured.value sampleCount)
                            box (CompilerKernelV2.Measured.value p50)
                            box (CompilerKernelV2.Measured.value p90)
                            box (CompilerKernelV2.Measured.value p99)
                            box (CompilerKernelV2.Measured.value maxDuration)
                            box (CompilerKernelV2.Measured.value totalDuration)
                            box (CompilerKernelV2.Measured.value slowCount) |])
                { shapeId = shapeId
                  intent = intent
                  authorityRole = authorityRole
                  memoProbe = memoProbe
                  sampleCount = sampleCount
                  p50 = p50
                  p90 = p90
                  p99 = p99
                  maxDuration = maxDuration
                  totalDuration = totalDuration
                  slowCount = slowCount
                  summaryRef = summaryRef })
            |> List.sortByDescending (fun summary -> CompilerKernelV2.Measured.value summary.totalDuration)
        let completedCountMeasured =
            CompilerKernelV2.Measured.create<CompilerKernelV2.NodeCountUnit> "jpDurationCompletedCount" (max 0L completedCount)
        let heavyTailClassText = jpDurationHeavyTailClassText heavyTailClass
        let profileRef =
            CompilerIdentityKernel.ContentDigest.ofText
                "jp-duration-profile"
                (FastRuntimeFormat.format "completed=%d|total_ms=%d|top10_ms=%d|top10_bp=%d|heavy_tail=%s|top=%s|shapes=%s|cohorts=%s" [|
                    box (CompilerKernelV2.Measured.value completedCountMeasured)
                    box totalDurationValue
                    box top10DurationValue
                    box (CompilerKernelV2.BasisPoints.value top10ConcentrationBp)
                    box heavyTailClassText
                    box (topEntries
                         |> List.map (fun entry -> CompilerIdentityKernel.ContentDigest.text entry.workUnitRef + ":" + string (CompilerKernelV2.Measured.value entry.duration))
                         |> String.concat ",")
                    box (shapeSummaries |> List.map (fun summary -> CompilerIdentityKernel.ContentDigest.text summary.summaryRef) |> String.concat ",")
                    box (cohortSummaries |> List.map (fun summary -> CompilerIdentityKernel.ContentDigest.text summary.summaryRef) |> String.concat ",") |])
        { completedCount = completedCountMeasured
          totalDuration = totalDuration
          top10Duration = top10Duration
          top10ConcentrationBp = top10ConcentrationBp
          heavyTailClass = heavyTailClass
          topEntries = topEntries
          shapeSummaries = shapeSummaries
          cohortSummaries = cohortSummaries
          profileRef = profileRef }

    let rec jpDurationProfileLoop entries completedCount =
        job {
            let! message =
                CompilerKernelV2.CompilerRuntimeKernel.take jpDurationProfileMailbox
            match message with
            | JpDurationProfileNote(entry, reply) ->
                let nextEntries = entry :: entries |> List.truncate 4096
                let nextCount = completedCount + 1L
                let shouldEmit =
                    nextCount <= 3L
                    || (nextCount &&& (nextCount - 1L)) = 0L
                    || nextCount % 128L = 0L
                let snapshot = if shouldEmit then Some(jpDurationProfileSnapshot nextEntries nextCount) else None
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.fillOneShot reply snapshot
                return! jpDurationProfileLoop nextEntries nextCount
            | JpDurationProfileRead reply ->
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                        reply
                        (jpDurationProfileSnapshot entries completedCount)
                return! jpDurationProfileLoop entries completedCount
        }

    let private jpDurationProfileStarted = lazy (startHopacJob (jpDurationProfileLoop [] 0L))

    let private ensureJpDurationProfileStarted () =
        CompilerRuntimeActivation.requireInProcessEntered "jp_duration_profile"
        jpDurationProfileStarted.Force()

    let jpDurationProfileNoteJob (item:JpWorkItem) (durationMs:int64) : Job<JpDurationProfileSnapshot option> =
        job {
            ensureJpDurationProfileStarted()
            DiagJson.noteJpDurationPhaseSample item.shape item.site durationMs
            let reply =
                CompilerKernelV2.CompilerRuntimeKernel.oneShot<JpDurationProfileSnapshot option>
                    "jp-duration-profile-note"
            let memoProbe =
                match item.computationMetadata with
                | JpWorkComputationMetadata descriptor -> descriptor.memoProbe
                | JpWorkComputationMetadataUnavailable -> JpComputationMemoNotApplicable
            let entry =
                { workUnitRef =
                    CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                    |> CompilerIdentityKernel.ContentDigest.requireParsed "workUnitRef"
                  bindingId = jpWorkItemDeclarationBindingId item
                  siteId = item.siteId
                  shapeId = item.shapeId
                  intent = item.workNode.intent
                  authorityRole = item.authorityRole
                  memoProbe = memoProbe
                  duration = CompilerKernelV2.Measured.create<CompilerKernelV2.WallTimeUnit> "jpDurationProfileEntryDuration" (max 0L durationMs)
                  semanticCost = item.cost
                  proofRef =
                    item.specializationInteractionReceipt
                    |> CompilerKernelV2.SpecializationInteractionReceiptView.proofRef }
            do!
                CompilerKernelV2.CompilerRuntimeKernel.send
                    jpDurationProfileMailbox
                    (JpDurationProfileNote(entry, reply))
            let! snapshot =
                CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
            match snapshot with
            | None -> ()
            | Some profile ->
                profile.shapeSummaries
                |> List.iter (fun (summary:JpDurationShapeSummary) ->
                    let shapeText = CompilerIdentityKernel.WorkShapeIdOps.text summary.shapeId
                    let p99Ms = CompilerKernelV2.Measured.value summary.p99
                    let sampleCount = CompilerKernelV2.Measured.value summary.sampleCount
                    BigStackDurationBasisAuthority.observe shapeText p99Ms sampleCount)
            return snapshot
        }

    let jpDurationProfileReadJob () : Job<JpDurationProfileSnapshot> =
        job {
            ensureJpDurationProfileStarted()
            let reply =
                CompilerKernelV2.CompilerRuntimeKernel.oneShot<JpDurationProfileSnapshot>
                    "jp-duration-profile-read"
            do!
                CompilerKernelV2.CompilerRuntimeKernel.send
                    jpDurationProfileMailbox
                    (JpDurationProfileRead reply)
            return!
                CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
        }

    type JpOperationalSemanticMutation = CompilerKernelV2.SemanticWorkMutation

    let jpOperationalNoSemanticMutation : JpOperationalSemanticMutation =
        CompilerKernelV2.SemanticWorkNoMutation

    let jpOperationalSemanticAdmit workUnit cost : JpOperationalSemanticMutation =
        CompilerKernelV2.SemanticWorkAdmit(CompilerKernelV2.SomeJoinPointWorkUnit workUnit, cost)

    let jpOperationalSemanticApply receipt : JpOperationalSemanticMutation =
        CompilerKernelV2.SemanticWorkApply(CompilerKernelV2.SomeJoinPointWorkReceipt receipt)

    type JpOperationalWorkTransaction =
        | JpOperationalWorkAdmitTransaction of
            node:CompilerKernelV2.OperationalWorkGraphNode
            * semanticMutation:JpOperationalSemanticMutation
        | JpOperationalWorkTransitionTransaction of
            transition:CompilerKernelV2.SomeWorkTransition
            * semanticMutation:JpOperationalSemanticMutation

    type JpOperationalWorkTransactionDisposition =
        | JpOperationalWorkTransactionApplied
        | JpOperationalWorkDuplicateAdmission of existingState:CompilerKernelV2.OperationalWorkGraphNodeState
        | JpOperationalWorkDuplicateTransition

    type JpOperationalWorkTransactionRejection =
        | JpOperationalWorkSemanticConflict of CompilerKernelV2.SemanticWorkLedgerConflict
        | JpOperationalWorkStaleTransition of
            transitionRef:CompilerIdentityKernel.ContentDigest
            * expectedStateRef:CompilerIdentityKernel.ContentDigest
            * currentState:CompilerKernelV2.OperationalWorkGraphNodeState
            * currentStateRef:CompilerIdentityKernel.ContentDigest
        | JpOperationalWorkProtocolViolation of violationRef:CompilerIdentityKernel.ContentDigest * message:string

    type JpOperationalWorkTransactionReceipt = private {
        disposition : JpOperationalWorkTransactionDisposition
        graphEvent : CompilerKernelV2.OperationalWorkGraphEvent
        semanticMutationApplied : bool
        semanticAdmittedCount : int
        semanticReceiptCount : int
        transactionRef : CompilerIdentityKernel.ContentDigest
    }

    let jpOperationalWorkTransactionDispositionText = function
        | JpOperationalWorkTransactionApplied -> "Applied"
        | JpOperationalWorkDuplicateAdmission state ->
            "DuplicateAdmission(state=" + CompilerKernelV2.operationalWorkGraphNodeStateText state + ")"
        | JpOperationalWorkDuplicateTransition -> "DuplicateTransition"

    let semanticWorkLedgerConflictText = function
        | CompilerKernelV2.SemanticWorkUnitAlreadyAdmittedWithDifferentCost(workUnit, previousCost, nextCost) ->
            FastRuntimeFormat.format "AlreadyAdmittedDifferentCost(work_unit=%s|previous=%d|next=%d)" [| box (CompilerKernelV2.SemanticWorkUnitKeyId.text workUnit); box (CompilerKernelV2.Measured.value previousCost); box (CompilerKernelV2.Measured.value nextCost) |]
        | CompilerKernelV2.SemanticWorkUnitIdentityConflict workUnit ->
            "IdentityConflict(work_unit=" + CompilerKernelV2.SemanticWorkUnitKeyId.text workUnit + ")"
        | CompilerKernelV2.SemanticWorkUnitReceiptConflict(workUnit, previousReceipt, nextReceipt) ->
            FastRuntimeFormat.format "ReceiptConflict(work_unit=%s|previous=%s|next=%s)" [| box (CompilerKernelV2.SemanticWorkUnitKeyId.text workUnit); box (CompilerIdentityKernel.ContentDigest.text previousReceipt); box (CompilerIdentityKernel.ContentDigest.text nextReceipt) |]
        | CompilerKernelV2.SemanticWorkUnitReceiptBeforeAdmission workUnit ->
            sprintf "ReceiptBeforeAdmission(work_unit=%s)" (CompilerKernelV2.SemanticWorkUnitKeyId.text workUnit)

    let jpOperationalWorkTransactionRejectionText = function
        | JpOperationalWorkSemanticConflict conflict ->
            "SemanticConflict(" + semanticWorkLedgerConflictText conflict + ")"
        | JpOperationalWorkStaleTransition(transitionRef,expectedStateRef,currentState,currentStateRef) ->
            "StaleTransition(transition=" + CompilerIdentityKernel.ContentDigest.text transitionRef
            + "|expected=" + CompilerIdentityKernel.ContentDigest.text expectedStateRef
            + "|current_state=" + CompilerKernelV2.operationalWorkGraphNodeStateText currentState
            + "|current_ref=" + CompilerIdentityKernel.ContentDigest.text currentStateRef + ")"
        | JpOperationalWorkProtocolViolation(violationRef,message) ->
            "ProtocolViolation(ref=" + CompilerIdentityKernel.ContentDigest.text violationRef + "|message=" + message + ")"

    let jpOperationalWorkStaleTransitionSupersedesAttempt = function
        | CompilerKernelV2.OperationalWorkSuspended _
        | CompilerKernelV2.OperationalWorkRetired _ -> true
        | CompilerKernelV2.OperationalWorkQueued
        | CompilerKernelV2.OperationalWorkRunning -> false

    let semanticWorkLedgerResultText = function
        | Ok () -> "Ok"
        | Error conflict -> "Error(" + semanticWorkLedgerConflictText conflict + ")"

    let jpWorkUnitDispositionText = function
        | CompilerKernelV2.WorkUnitAdmitted -> "Admitted"
        | CompilerKernelV2.WorkUnitRunning -> "Running"
        | CompilerKernelV2.WorkUnitRetired receipt -> "Retired(" + CompilerIdentityKernel.ContentDigest.text receipt + ")"
        | CompilerKernelV2.WorkUnitBlocked blocker -> "Blocked(" + CompilerIdentityKernel.ContentDigest.text blocker + ")"
        | CompilerKernelV2.WorkUnitFailed failure -> "Failed(" + CompilerIdentityKernel.ContentDigest.text failure + ")"
        | CompilerKernelV2.WorkUnitCancelled reason -> "Cancelled(" + CompilerIdentityKernel.ContentDigest.text reason + ")"
        | CompilerKernelV2.WorkUnitSuperseded transition -> "Superseded(" + CompilerIdentityKernel.ContentDigest.text transition + ")"

    type JpGenerationScopeCloseReason =
        | JpGenerationScopeCacheInvalidation

    let jpGenerationScopeCloseReasonText = function
        | JpGenerationScopeCacheInvalidation -> "CacheInvalidation"

    type JpGenerationScopeMessage =
        | JpGenerationScopeAdmit of generation:int64 * workUnitId:string
        | JpGenerationScopeRetire of generation:int64 * workUnitId:string
        | JpGenerationScopeClose of
            generation:int64
            * reason:JpGenerationScopeCloseReason
            * reply:CompilerKernelV2.PortableOneShotCell<CompilerIdentityKernel.ContentDigest>
        | JpGenerationScopeSnapshot of
            reply:CompilerKernelV2.PortableOneShotCell<Map<int64,Set<string>>>

    type JpOperationalDomainMessage =
        | JpWorkCellMerge of
            identity:CompilerKernelV2.StableBindingId
            * next:CompilerKernelV2.ConfluentWorkCell<JpWorkResult>
            * reply:CompilerKernelV2.PortableOneShotCell<CompilerKernelV2.ConfluentWorkCell<JpWorkResult>>
        | JpWorkCellReadAll of
            reply:CompilerKernelV2.PortableOneShotCell<Map<CompilerKernelV2.StableBindingId, CompilerKernelV2.ConfluentWorkCell<JpWorkResult>>>
        | JpOperationalWorkTransact of
            transaction:JpOperationalWorkTransaction
            * reply:CompilerKernelV2.PortableOneShotCell<Result<JpOperationalWorkTransactionReceipt,JpOperationalWorkTransactionRejection>>
        | JpOperationalWorkSnapshot of
            reply:CompilerKernelV2.PortableOneShotCell<CompilerKernelV2.OperationalWorkGraph>
        | JpOperationalWorkAwaitQuiescence of
            reply:CompilerKernelV2.PortableOneShotCell<CompilerIdentityKernel.ContentDigest>

    // Join-point IVar wait policy is a module-level domain model.  F# rejects
    // type declarations inside peval; keep only the runtime classifiers local.
    type JpIvarWaitKind =
        | JpIvarWaitType
        | JpIvarWaitMethod
        | JpIvarWaitOther

    type JpWaiterWorkIdentity = private JpWaiterWorkIdentity of int64
    type JpPromiseIdentity = private JpPromiseIdentity of CompilerIdentityKernel.ContentDigest

    type JpPromiseCellKind =
        | JpMethodPromiseCell
        | JpClosurePromiseCell
        | JpTypePromiseCell
        | JpAnonymousPromiseCell

    let jpPromiseCellKindText = function
        | JpMethodPromiseCell -> "Method"
        | JpClosurePromiseCell -> "Closure"
        | JpTypePromiseCell -> "Type"
        | JpAnonymousPromiseCell -> "Anonymous"

    type JpPromiseCellWitness =
        | JpPromiseComputationWitness of computation:JpComputationIdentity * instantiationId:CompilerKernelV2.InstantiationId
        | JpPromiseTypeWitness of typeKeyRef:CompilerIdentityKernel.ContentDigest
        | JpPromiseAnonymousWitness of authorityRef:CompilerIdentityKernel.ContentDigest

    let jpPromiseCellWitnessText = function
        | JpPromiseComputationWitness(computation, instantiationId) ->
            jpComputationIdentityKindText computation
            + "|" + jpComputationIdentityText computation
            + "|" + CompilerKernelV2.InstantiationIdOps.text instantiationId
        | JpPromiseTypeWitness typeKeyRef ->
            "Type|" + CompilerIdentityKernel.ContentDigest.text typeKeyRef
        | JpPromiseAnonymousWitness authorityRef ->
            "Anonymous|" + CompilerIdentityKernel.ContentDigest.text authorityRef

    type JpPromiseOwnerCapability =
        | JpPromiseOwnerRoot of owner:JpWaiterWorkIdentity * capabilityRef:CompilerIdentityKernel.ContentDigest
        | JpPromiseOwnerDelegated of parent:JpPromiseOwnerCapability * producerWorkId:int64 * capabilityRef:CompilerIdentityKernel.ContentDigest
        | JpPromiseOwnerUnbound of promise:JpPromiseIdentity * capabilityRef:CompilerIdentityKernel.ContentDigest

    let jpPromiseOwnerCapabilityRef = function
        | JpPromiseOwnerRoot(_, capabilityRef)
        | JpPromiseOwnerDelegated(_, _, capabilityRef)
        | JpPromiseOwnerUnbound(_, capabilityRef) -> capabilityRef

    let jpPromiseOwnerCapabilityText = function
        | JpPromiseOwnerRoot(JpWaiterWorkIdentity owner, capabilityRef) ->
            sprintf "Root(owner=%d|ref=%s)" owner (CompilerIdentityKernel.ContentDigest.text capabilityRef)
        | JpPromiseOwnerDelegated(parent, producerWorkId, capabilityRef) ->
            FastRuntimeFormat.format "Delegated(parent=%s|producer=%d|ref=%s)" [| box (CompilerIdentityKernel.ContentDigest.text (jpPromiseOwnerCapabilityRef parent)); box producerWorkId; box (CompilerIdentityKernel.ContentDigest.text capabilityRef) |]
        | JpPromiseOwnerUnbound(JpPromiseIdentity promiseRef, capabilityRef) ->
            sprintf "Unbound(promise=%s|ref=%s)"
                (CompilerIdentityKernel.ContentDigest.text promiseRef)
                (CompilerIdentityKernel.ContentDigest.text capabilityRef)

    type JpPromiseCellState =
        | JpPromiseCellPending of owner:JpPromiseOwnerCapability
        | JpPromiseCellResolved of receiptRef:CompilerIdentityKernel.ContentDigest
        | JpPromiseCellFailed of failureRef:CompilerIdentityKernel.ContentDigest
        | JpPromiseCellCancelled of cancellationRef:CompilerIdentityKernel.ContentDigest

    type JpProducerWorkIdentity =
        | JpProducerExact of owner:JpPromiseOwnerCapability * producerWorkId:int64
        | JpProducerUnbound of JpPromiseOwnerCapability
        | JpProducerGenerationMismatch of expectedGeneration:int64 * actualGeneration:int64 * bindingRef:CompilerIdentityKernel.ContentDigest

    type JpProducerSchedulingState =
        | JpProducerInlineDonationExecuted
        | JpProducerQueuedPriorityDonated
        | JpProducerKnownNotQueuedForDonation
        | JpProducerUnavailable

    let jpProducerSchedulingStateText = function
        | JpProducerInlineDonationExecuted -> "InlineDonationExecuted"
        | JpProducerQueuedPriorityDonated -> "QueuedPriorityDonated"
        | JpProducerKnownNotQueuedForDonation -> "KnownProducerNotQueuedForDonation"
        | JpProducerUnavailable -> "ProducerUnavailable"

    type JpPromiseProducerRegistration = private {
        portableCellId : CompilerKernelV2.PortableResourceId
        promiseIdentity : JpPromiseIdentity
        generation : int64
        cellKind : JpPromiseCellKind
        witness : JpPromiseCellWitness
        cellRef : CompilerIdentityKernel.ContentDigest
    }

    let jpPromiseIdentityRef (JpPromiseIdentity promiseRef) = promiseRef

    let jpSpecializationWorkNodeBindPromise (registration:JpPromiseProducerRegistration) (node:JpSpecializationWorkNode) : JpSpecializationWorkNode =
        { node with
            inputs =
                node.inputs
                @ [ JpPromiseCellInput(
                        jpPromiseIdentityRef registration.promiseIdentity,
                        registration.cellRef) ] }

    type JpPromiseTerminalObservation =
        | JpPromiseTerminalResolved of receiptRef:CompilerIdentityKernel.ContentDigest
        | JpPromiseTerminalFailed of failureRef:CompilerIdentityKernel.ContentDigest
        | JpPromiseTerminalCancelled of cancellationRef:CompilerIdentityKernel.ContentDigest

    let jpSpecializationWorkNodeConsumePromiseTerminal (registration:JpPromiseProducerRegistration) (terminal:JpPromiseTerminalObservation) (node:JpSpecializationWorkNode) : JpSpecializationWorkNode =
        let terminalRef =
            match terminal with
            | JpPromiseTerminalResolved receiptRef
            | JpPromiseTerminalFailed receiptRef
            | JpPromiseTerminalCancelled receiptRef -> receiptRef
        { node with
            stage = JpSpecializationPublishPromise
            inputs =
                node.inputs
                @ [ JpPromiseTerminalInput(
                        jpPromiseIdentityRef registration.promiseIdentity,
                        terminalRef) ] }

    type JpPromiseProducerBinding = private {
        promiseIdentity : JpPromiseIdentity
        producerWorkId : int64
        generation : int64
        ownerCapability : JpPromiseOwnerCapability
        bindingRef : CompilerIdentityKernel.ContentDigest
        state : JpPromiseCellState
    }

    type JpPromiseProducerBindDecision =
        | JpPromiseProducerBound of JpPromiseProducerBinding
        | JpPromiseProducerBindingReused of JpPromiseProducerBinding
        | JpPromiseProducerBindingConflict of existing:JpPromiseProducerBinding * proposed:JpPromiseProducerBinding

    type JpPromiseProducerResolution =
        | JpPromiseProducerResolved of JpPromiseProducerBinding
        | JpPromiseProducerUnbound of JpPromiseOwnerCapability
        | JpPromiseProducerGenerationMismatch of expectedGeneration:int64 * actualGeneration:int64 * JpPromiseProducerBinding

    type JpPromiseProducerRetirementReceipt = private {
        retiredThroughGeneration : int64
        retiredBindings : int
        retainedBindings : int
        retirementRef : CompilerIdentityKernel.ContentDigest
    }

    type JpPromiseClosureDisposition =
        | JpPromiseClosureOpen of pendingCellRefs:CompilerIdentityKernel.ContentDigest list * unboundCellRefs:CompilerIdentityKernel.ContentDigest list
        | JpPromiseClosureClosed of terminalCellRefs:CompilerIdentityKernel.ContentDigest list

    type JpPromiseClosureSnapshot = private {
        generation : int64
        pendingCount : int
        resolvedCount : int
        failedCount : int
        cancelledCount : int
        unboundPendingCount : int
        disposition : JpPromiseClosureDisposition
        closureRef : CompilerIdentityKernel.ContentDigest
    }

    module JpPromiseProducerAuthority =
        // Runtime object handles are a lookup bridge only. Promise identity, owner,
        // generation and state are represented by typed cells keyed by ContentDigest.
        let private identitiesByRuntimeHandle =
            System.Collections.Concurrent.ConcurrentDictionary<obj,JpPromiseIdentity>(HashIdentity.Reference)
        let private runtimeHandleByIdentity =
            System.Collections.Concurrent.ConcurrentDictionary<JpPromiseIdentity,obj>()
        let private cells =
            System.Collections.Concurrent.ConcurrentDictionary<JpPromiseIdentity,JpPromiseProducerBinding>()
        let private registrations =
            System.Collections.Concurrent.ConcurrentDictionary<JpPromiseIdentity,JpPromiseProducerRegistration>()
        let private resumptionTickets =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,byte>()

        type private JpPromiseResumptionDriveResultId =
            | JpPromiseResumptionFrameExecuted
            | JpPromiseResumptionSemanticDrainPulseScheduled
            | JpPromiseResumptionOrphanDrainScheduled
            | JpPromiseResumptionNoRunnableFrameOrPulse

        let private jpPromiseResumptionFramePresent = function
            | JpPromiseResumptionFrameExecuted -> true
            | JpPromiseResumptionSemanticDrainPulseScheduled
            | JpPromiseResumptionOrphanDrainScheduled
            | JpPromiseResumptionNoRunnableFrameOrPulse -> false

        let private jpPromiseResumptionDrainPulseScheduled = function
            | JpPromiseResumptionSemanticDrainPulseScheduled -> true
            | JpPromiseResumptionFrameExecuted
            | JpPromiseResumptionOrphanDrainScheduled
            | JpPromiseResumptionNoRunnableFrameOrPulse -> false

        let private jpPromiseResumptionOrphanDrainScheduled = function
            | JpPromiseResumptionOrphanDrainScheduled -> true
            | JpPromiseResumptionFrameExecuted
            | JpPromiseResumptionSemanticDrainPulseScheduled
            | JpPromiseResumptionNoRunnableFrameOrPulse -> false

        type private JpPromiseResumptionDispatchId =
            | JpPromiseResumptionQueued
            | JpPromiseResumptionDriven of JpPromiseResumptionDriveResultId
            | JpPromiseResumptionDuplicateSuppressed

        let private jpPromiseResumptionDispatchText = function
            | JpPromiseResumptionQueued -> "Queued"
            | JpPromiseResumptionDriven JpPromiseResumptionFrameExecuted -> "DrivenWithFrame"
            | JpPromiseResumptionDriven JpPromiseResumptionSemanticDrainPulseScheduled -> "DrivenWithSemanticDrainPulse"
            | JpPromiseResumptionDriven JpPromiseResumptionOrphanDrainScheduled -> "DrivenWithOrphanDrain"
            | JpPromiseResumptionDriven JpPromiseResumptionNoRunnableFrameOrPulse -> "DrivenWithoutRunnableFrameOrPulse"
            | JpPromiseResumptionDuplicateSuppressed -> "DuplicateSuppressed"

        type private JpPromiseResumptionSlicePolicyId =
            | JpPromiseResumptionStackSafeSlice of budget:int * schedulerYieldMs:int

        type private JpPromiseResumptionRetryPolicyId =
            | JpPromiseResumptionEventDrivenNoRetry

        let private resumptionSlicePolicy =
            JpPromiseResumptionStackSafeSlice(64, 1)

        let private resumptionRetryPolicy =
            JpPromiseResumptionEventDrivenNoRetry

        let private jpPromiseResumptionSliceBudget = function
            | JpPromiseResumptionStackSafeSlice(budget, _) -> budget

        let private jpPromiseResumptionSliceYieldMs = function
            | JpPromiseResumptionStackSafeSlice(_, schedulerYieldMs) -> schedulerYieldMs

        let private jpPromiseResumptionSlicePolicyText = function
            | JpPromiseResumptionStackSafeSlice(budget, schedulerYieldMs) ->
                sprintf "StackSafeSlice(budget=%d|scheduler_yield_ms=%d)" budget schedulerYieldMs

        let private jpPromiseResumptionRetryPolicyText = function
            | JpPromiseResumptionEventDrivenNoRetry -> "EventDrivenNoRetry"

        type private JpPromiseResumptionRetryDecisionId =
            | JpPromiseResumptionRetryNotRequired
            | JpPromiseResumptionRetrySuppressedByCatchupDrain
            | JpPromiseResumptionRetryGenerationChanged of requestGeneration:int64 * currentGeneration:int64
            | JpPromiseResumptionNoRegisteredContinuationAtTerminal of observedAttempt:int

        let private jpPromiseResumptionRetryDecisionText = function
            | JpPromiseResumptionRetryNotRequired -> "NotRequired"
            | JpPromiseResumptionRetrySuppressedByCatchupDrain -> "SuppressedByCatchupDrain"
            | JpPromiseResumptionRetryGenerationChanged(requestGeneration, currentGeneration) ->
                sprintf "GenerationChanged(request=%d|current=%d)" requestGeneration currentGeneration
            | JpPromiseResumptionNoRegisteredContinuationAtTerminal observedAttempt ->
                sprintf "NoRegisteredContinuationAtTerminal(observed_attempt=%d)" observedAttempt

        type private JpPromiseResumptionRequest = {
            registration : JpPromiseProducerRegistration
            cause : JpPromiseResumptionCauseId
            terminalRef : CompilerIdentityKernel.ContentDigest
            ticketRef : CompilerIdentityKernel.ContentDigest
            attempt : int
        }

        let private resumptionMailbox =
            CompilerKernelV2.CompilerRuntimeKernel.mailbox<JpPromiseResumptionRequest>
                "jp-promise-resumption"
                CompilerKernelV2.PortableSemanticLane
                0
                CompilerKernelV2.MailboxFailClosed

        let rec private resumptionLoop (handledCount:int64) =
            job {
                let! request =
                    CompilerKernelV2.CompilerRuntimeKernel.take resumptionMailbox
                let registration = request.registration
                let (JpPromiseIdentity promiseRef) = registration.promiseIdentity
                // Stack-safety boundary: promise completion may happen while the
                // evaluator is already active.  A single actor serializes every
                // bounded replay slice, so no completion can recursively re-enter
                // EvalWorklist on the same host stack or race another replay slice.
                let replayEventId =
                    match request.cause with
                    | JpPromiseResolvedResumption -> EvalWorklist.ReplayTickEventJpPromiseResolvedResumption
                    | JpPromiseFailedResumption -> EvalWorklist.ReplayTickEventJpPromiseFailedResumption
                    | JpPromiseCancelledResumption -> EvalWorklist.ReplayTickEventJpPromiseCancelledResumption
                let frame =
                    try
                        EvalWorklist.ensureCapturedAndRunId
                            (CompilerKernelV2.OperationalReasonIdOps.create "jp_promise_terminal_resumption")
                            replayEventId
                            (jpPromiseResumptionSliceBudget resumptionSlicePolicy)
                    with e ->
                        DiagJson.emitRecord {
                            kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpPromiseTerminalResumptionFaulted
                            ticket_ref = CompilerIdentityKernel.ContentDigest.text request.ticketRef
                            exception_type = e.GetType().FullName
                            authority = "single_actor_stack_safe_promise_resumption"
                            next = "continue_actor_without_recursive_reentry"
                        }
                        None
                let driveResult =
                    match frame with
                    | Some _ -> JpPromiseResumptionFrameExecuted
                    | None ->
                        let reason =
                            "promise_terminal_without_frame|ticket="
                            + CompilerIdentityKernel.ContentDigest.text request.ticketRef
                        let pulseScheduled =
                            try
                                EvalWorklist.requestSemanticDrainPulse
                                    EvalWorklist.ReplayTickEventJpPromiseTerminalResumption
                                    (EvalWorklist.ReplayTickReasonJpPromiseTerminalWithoutFrame request.ticketRef)
                            with _ -> false
                        if pulseScheduled then JpPromiseResumptionSemanticDrainPulseScheduled
                        else
                            let orphanDrainScheduled =
                                try
                                    EvalWorklist.forceReplayDriverDrainPassId
                                        "jp_promise_terminal_resumption_orphan"
                                        (CompilerKernelV2.OperationalReasonIdOps.create reason)
                                        8
                                with _ -> false
                            if orphanDrainScheduled then JpPromiseResumptionOrphanDrainScheduled
                            else JpPromiseResumptionNoRunnableFrameOrPulse
                let catchupDrainScheduled =
                    try
                        EvalWorklist.forceReplayDriverDrainPassId
                            "jp_promise_terminal_resumption_catchup"
                            (CompilerKernelV2.OperationalReasonIdOps.create ("terminal_ticket=" + CompilerIdentityKernel.ContentDigest.text request.ticketRef))
                            8
                    with _ -> false
                let currentGeneration = CacheGeneration.current ()
                let retryDecision =
                    match driveResult with
                    | JpPromiseResumptionNoRunnableFrameOrPulse when catchupDrainScheduled ->
                        JpPromiseResumptionRetrySuppressedByCatchupDrain
                    | JpPromiseResumptionNoRunnableFrameOrPulse
                        when registration.generation <> currentGeneration ->
                        JpPromiseResumptionRetryGenerationChanged(registration.generation, currentGeneration)
                    | JpPromiseResumptionNoRunnableFrameOrPulse ->
                        JpPromiseResumptionNoRegisteredContinuationAtTerminal request.attempt
                    | _ -> JpPromiseResumptionRetryNotRequired
                let retryScheduled = false
                let retryExhausted = false
                let dispatch = JpPromiseResumptionDriven driveResult
                DiagJson.emitRecord {
                    kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpPromiseTerminalResumptionDriven
                    promise_ref = CompilerIdentityKernel.ContentDigest.text promiseRef
                    ticket_ref = CompilerIdentityKernel.ContentDigest.text request.ticketRef
                    terminal_ref = CompilerIdentityKernel.ContentDigest.text request.terminalRef
                    generation = registration.generation
                    cause_du = jpPromiseResumptionCauseText request.cause
                    dispatch_du = jpPromiseResumptionDispatchText dispatch
                    actor_sequence = handledCount + 1L
                    attempt = request.attempt
                    frame_present = jpPromiseResumptionFramePresent driveResult
                    semantic_drain_pulse_scheduled = jpPromiseResumptionDrainPulseScheduled driveResult
                    orphan_drain_scheduled = jpPromiseResumptionOrphanDrainScheduled driveResult
                    catchup_drain_scheduled = catchupDrainScheduled
                    retry_scheduled = retryScheduled
                    retry_exhausted = retryExhausted
                    retry_decision_du = jpPromiseResumptionRetryDecisionText retryDecision
                    retry_policy_du = jpPromiseResumptionRetryPolicyText resumptionRetryPolicy
                    slice_policy_du = jpPromiseResumptionSlicePolicyText resumptionSlicePolicy
                    authority = "single_actor_stack_safe_event_driven_promise_resumption_no_retry_polling"
                    next = "resume_registered_continuation_or_retire_terminal_promise_immediately"
                }
                // Force a scheduler turn between bounded slices.  Even if a slice
                // completes synchronously, the actor cannot build an unbounded host
                // continuation chain across a burst of promise completions.
                do! Hopac.timeOutMillis (jpPromiseResumptionSliceYieldMs resumptionSlicePolicy)
                return! resumptionLoop (handledCount + 1L)
            }

        let private resumptionStarted = lazy (startHopacJob (resumptionLoop 0L))

        let private ensureResumptionStarted () =
            CompilerRuntimeActivation.requireInProcessEntered "jp_promise_resumption_actor"
            resumptionStarted.Force()

        let private scheduleResumption
            (registration:JpPromiseProducerRegistration)
            (cause:JpPromiseResumptionCauseId)
            (terminalRef:CompilerIdentityKernel.ContentDigest) =
            let (JpPromiseIdentity promiseRef) = registration.promiseIdentity
            let ticketRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-promise-terminal-resumption-ticket"
                    (CompilerIdentityKernel.ContentDigest.text promiseRef
                     + "|generation=" + string registration.generation
                     + "|cause=" + jpPromiseResumptionCauseText cause
                     + "|terminal=" + CompilerIdentityKernel.ContentDigest.text terminalRef)
            if resumptionTickets.TryAdd(ticketRef, 0uy) then
                ensureResumptionStarted()
                let request =
                    { registration = registration
                      cause = cause
                      terminalRef = terminalRef
                      ticketRef = ticketRef
                      attempt = 0 }
                let dispatch = JpPromiseResumptionQueued
                DiagJson.emitRecord {
                    kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpPromiseTerminalResumptionQueued
                    promise_ref = CompilerIdentityKernel.ContentDigest.text promiseRef
                    ticket_ref = CompilerIdentityKernel.ContentDigest.text ticketRef
                    generation = registration.generation
                    cause_du = jpPromiseResumptionCauseText cause
                    dispatch_du = jpPromiseResumptionDispatchText dispatch
                    authority = "single_actor_stack_safe_promise_resumption"
                    next = "actor_drives_one_bounded_replay_slice"
                }
                startHopacJob (
                    CompilerKernelV2.CompilerRuntimeKernel.send
                        resumptionMailbox
                        request)
            else
                let dispatch = JpPromiseResumptionDuplicateSuppressed
                let occurrenceCount, emitDuplicate =
                    DiagJson.sparseLogDecision
                        ("jp_promise_terminal_resumption_duplicate_suppressed|" + jpPromiseResumptionCauseText cause)
                        256L
                if emitDuplicate then
                    let duplicateEvent : JpPromiseTerminalResumptionDuplicateSuppressedEvent =
                        { kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpPromiseTerminalResumptionDuplicateSuppressed
                          promise_ref = CompilerIdentityKernel.ContentDigest.text promiseRef
                          ticket_ref = CompilerIdentityKernel.ContentDigest.text ticketRef
                          generation = registration.generation
                          cause_du = jpPromiseResumptionCauseText cause
                          dispatch_du = jpPromiseResumptionDispatchText dispatch
                          occurrence_count = occurrenceCount
                          sparse_policy = "cause_first3_power2_every256"
                          authority = "content_addressed_resumption_ticket" }
                    DiagJson.emitRecord duplicateEvent

        let private identityFor generation cellKind witness =
            JpPromiseIdentity (
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-generation-affine-promise-cell"
                    (jpPromiseCellKindText cellKind
                     + "|generation=" + string generation
                     + "|witness=" + jpPromiseCellWitnessText witness))

        let registrationFor<'T> generation cellKind witness (ivar:Hopac.IVar<'T>) : JpPromiseProducerRegistration =
            // Raw IVar identity is confined to this F# adapter ingress.  The
            // operational registration stores only the portable resource id.
            let runtimeHandle = box ivar
            let portableCell : CompilerKernelV2.PortableOneShotCell<'T> =
                CompilerKernelV2.CompilerRuntimeKernel.wrapOneShot<'T>
                    "jp-promise-cell"
                    ivar
            let promiseIdentity = identityFor generation cellKind witness
            let (JpPromiseIdentity promiseRef) = promiseIdentity
            let registration : JpPromiseProducerRegistration =
                { portableCellId = CompilerKernelV2.PortableOneShotCellOps.resourceId portableCell
                  promiseIdentity = promiseIdentity
                  generation = generation
                  cellKind = cellKind
                  witness = witness
                  cellRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-promise-cell-registration"
                        (CompilerIdentityKernel.ContentDigest.text promiseRef
                         + "|kind=" + jpPromiseCellKindText cellKind
                         + "|witness=" + jpPromiseCellWitnessText witness) }
            identitiesByRuntimeHandle.[runtimeHandle] <- promiseIdentity
            runtimeHandleByIdentity.[promiseIdentity] <- runtimeHandle
            registrations.[promiseIdentity] <- registration
            registration

        let registrationForExisting<'T> generation (ivar:Hopac.IVar<'T>) : JpPromiseProducerRegistration =
            let runtimeHandle = box ivar
            let mutable promiseIdentity = Unchecked.defaultof<JpPromiseIdentity>
            if identitiesByRuntimeHandle.TryGetValue(runtimeHandle, &promiseIdentity) then
                let mutable registration = Unchecked.defaultof<JpPromiseProducerRegistration>
                if registrations.TryGetValue(promiseIdentity, &registration) then registration
                else
                    registrationFor
                        generation
                        JpAnonymousPromiseCell
                        (JpPromiseAnonymousWitness (
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-existing-promise-registration-missing"
                                (string generation)))
                        ivar
            else
                registrationFor
                    generation
                    JpAnonymousPromiseCell
                    (JpPromiseAnonymousWitness (
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-unregistered-runtime-promise"
                            (string generation)))
                    ivar

        let rec bind (registration:JpPromiseProducerRegistration) (producerWorkId:int64) : JpPromiseProducerBindDecision =
            let (JpPromiseIdentity promiseRef) = registration.promiseIdentity
            let rootCapabilityRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-promise-owner-root"
                    (CompilerIdentityKernel.ContentDigest.text promiseRef
                     + "|generation=" + string registration.generation)
            let rootCapability =
                JpPromiseOwnerRoot(JpWaiterWorkIdentity producerWorkId, rootCapabilityRef)
            let delegatedCapabilityRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-promise-owner-delegated"
                    (CompilerIdentityKernel.ContentDigest.text rootCapabilityRef
                     + "|producer=" + string producerWorkId)
            let ownerCapability =
                JpPromiseOwnerDelegated(rootCapability, producerWorkId, delegatedCapabilityRef)
            let proposed : JpPromiseProducerBinding =
                { promiseIdentity = registration.promiseIdentity
                  producerWorkId = producerWorkId
                  generation = registration.generation
                  ownerCapability = ownerCapability
                  bindingRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-promise-producer-binding"
                        (CompilerIdentityKernel.ContentDigest.text promiseRef
                         + "|producer=" + string producerWorkId
                         + "|generation=" + string registration.generation)
                  state = JpPromiseCellPending ownerCapability }
            let mutable existing = Unchecked.defaultof<JpPromiseProducerBinding>
            if cells.TryGetValue(registration.promiseIdentity, &existing) then
                if existing.generation = registration.generation
                   && existing.producerWorkId = producerWorkId then
                    JpPromiseProducerBindingReused existing
                else
                    JpPromiseProducerBindingConflict(existing, proposed)
            elif cells.TryAdd(registration.promiseIdentity, proposed) then
                JpPromiseProducerBound proposed
            else
                // A concurrent producer won the exact same promise identity between
                // TryGetValue and TryAdd. Re-read and classify; never overwrite it.
                bind registration producerWorkId

        let resolveRegistration generation (registration:JpPromiseProducerRegistration) =
            let mutable binding = Unchecked.defaultof<JpPromiseProducerBinding>
            if cells.TryGetValue(registration.promiseIdentity, &binding) then
                if binding.generation = generation then JpPromiseProducerResolved binding
                else JpPromiseProducerGenerationMismatch(generation, binding.generation, binding)
            else
                let capabilityRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-promise-owner-unbound"
                        (let (JpPromiseIdentity promiseRef) = registration.promiseIdentity
                         CompilerIdentityKernel.ContentDigest.text promiseRef
                         + "|generation=" + string generation)
                JpPromiseProducerUnbound (
                    JpPromiseOwnerUnbound(registration.promiseIdentity, capabilityRef))

        let resolve generation (ivar:Hopac.IVar<'a>) =
            registrationForExisting generation ivar
            |> resolveRegistration generation

        let complete (registration:JpPromiseProducerRegistration) (receiptRef:CompilerIdentityKernel.ContentDigest) =
            let accepted = cells.AddOrUpdate(
                registration.promiseIdentity,
                (let capabilityRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-promise-owner-unbound-complete"
                        (CompilerIdentityKernel.ContentDigest.text registration.cellRef)
                 let capability = JpPromiseOwnerUnbound(registration.promiseIdentity, capabilityRef)
                 { promiseIdentity = registration.promiseIdentity
                   producerWorkId = 0L
                   generation = registration.generation
                   ownerCapability = capability
                   bindingRef = registration.cellRef
                   state = JpPromiseCellResolved receiptRef }),
                fun _ previous ->
                    match previous.state with
                    | JpPromiseCellResolved _
                    | JpPromiseCellFailed _
                    | JpPromiseCellCancelled _ -> previous
                    | JpPromiseCellPending _ -> { previous with state = JpPromiseCellResolved receiptRef })
            match accepted.state with
            | JpPromiseCellResolved acceptedRef when acceptedRef = receiptRef ->
                scheduleResumption registration JpPromiseResolvedResumption receiptRef
            | _ -> ()

        let fail (registration:JpPromiseProducerRegistration) (failureRef:CompilerIdentityKernel.ContentDigest) =
            let accepted = cells.AddOrUpdate(
                registration.promiseIdentity,
                (let capabilityRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-promise-owner-unbound-fail"
                        (CompilerIdentityKernel.ContentDigest.text registration.cellRef)
                 let capability = JpPromiseOwnerUnbound(registration.promiseIdentity, capabilityRef)
                 { promiseIdentity = registration.promiseIdentity
                   producerWorkId = 0L
                   generation = registration.generation
                   ownerCapability = capability
                   bindingRef = registration.cellRef
                   state = JpPromiseCellFailed failureRef }),
                fun _ previous ->
                    match previous.state with
                    | JpPromiseCellResolved _
                    | JpPromiseCellFailed _
                    | JpPromiseCellCancelled _ -> previous
                    | JpPromiseCellPending _ -> { previous with state = JpPromiseCellFailed failureRef })
            match accepted.state with
            | JpPromiseCellFailed acceptedRef when acceptedRef = failureRef ->
                scheduleResumption registration JpPromiseFailedResumption failureRef
            | _ -> ()

        let cancel (registration:JpPromiseProducerRegistration) (cancellationRef:CompilerIdentityKernel.ContentDigest) =
            let accepted = cells.AddOrUpdate(
                registration.promiseIdentity,
                (let capabilityRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-promise-owner-unbound-cancel"
                        (CompilerIdentityKernel.ContentDigest.text registration.cellRef)
                 let capability = JpPromiseOwnerUnbound(registration.promiseIdentity, capabilityRef)
                 { promiseIdentity = registration.promiseIdentity
                   producerWorkId = 0L
                   generation = registration.generation
                   ownerCapability = capability
                   bindingRef = registration.cellRef
                   state = JpPromiseCellCancelled cancellationRef }),
                fun _ previous ->
                    match previous.state with
                    | JpPromiseCellResolved _
                    | JpPromiseCellFailed _
                    | JpPromiseCellCancelled _ -> previous
                    | JpPromiseCellPending _ -> { previous with state = JpPromiseCellCancelled cancellationRef })
            match accepted.state with
            | JpPromiseCellCancelled acceptedRef when acceptedRef = cancellationRef ->
                scheduleResumption registration JpPromiseCancelledResumption cancellationRef
            | _ -> ()

        let retireThrough retiredThroughGeneration =
            let retiredBindings, retainedBindings =
                cells.ToArray()
                |> Array.fold (fun (retiredCount, retainedCount) entry ->
                    if entry.Value.generation <= retiredThroughGeneration then
                        let mutable removed = Unchecked.defaultof<JpPromiseProducerBinding>
                        if cells.TryRemove(entry.Key, &removed) then
                            let mutable registration = Unchecked.defaultof<JpPromiseProducerRegistration>
                            if registrations.TryRemove(entry.Key, &registration) then
                                let mutable runtimeHandle = Unchecked.defaultof<obj>
                                if runtimeHandleByIdentity.TryRemove(entry.Key, &runtimeHandle) then
                                    let mutable removedIdentity = Unchecked.defaultof<JpPromiseIdentity>
                                    identitiesByRuntimeHandle.TryRemove(runtimeHandle, &removedIdentity) |> ignore
                            retiredCount + 1, retainedCount
                        else retiredCount, retainedCount
                    else
                        retiredCount, retainedCount + 1) (0, 0)
            { retiredThroughGeneration = retiredThroughGeneration
              retiredBindings = retiredBindings
              retainedBindings = retainedBindings
              retirementRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-promise-producer-retirement"
                    (FastRuntimeFormat.format "%d|retired=%d|retained=%d" [| box retiredThroughGeneration; box retiredBindings; box retainedBindings |]) }

        let closureSnapshot (generation:int64) : JpPromiseClosureSnapshot =
            let relevant =
                cells.ToArray()
                |> Array.map (fun entry -> entry.Value)
                |> Array.filter (fun binding -> binding.generation = generation)
            let mutable pendingCount = 0
            let mutable resolvedCount = 0
            let mutable failedCount = 0
            let mutable cancelledCount = 0
            let mutable unboundPendingCount = 0
            let mutable pendingCellRefs : CompilerIdentityKernel.ContentDigest list = []
            let mutable unboundCellRefs : CompilerIdentityKernel.ContentDigest list = []
            let mutable terminalCellRefs : CompilerIdentityKernel.ContentDigest list = []
            relevant
            |> Array.iter (fun binding ->
                match binding.state with
                | JpPromiseCellPending owner ->
                    pendingCount <- pendingCount + 1
                    pendingCellRefs <- binding.bindingRef :: pendingCellRefs
                    match owner with
                    | JpPromiseOwnerUnbound _ ->
                        unboundPendingCount <- unboundPendingCount + 1
                        unboundCellRefs <- binding.bindingRef :: unboundCellRefs
                    | JpPromiseOwnerRoot _
                    | JpPromiseOwnerDelegated _ -> ()
                | JpPromiseCellResolved receiptRef ->
                    resolvedCount <- resolvedCount + 1
                    terminalCellRefs <-
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-promise-resolved-cell"
                            (CompilerIdentityKernel.ContentDigest.text binding.bindingRef
                             + "|receipt=" + CompilerIdentityKernel.ContentDigest.text receiptRef)
                        :: terminalCellRefs
                | JpPromiseCellFailed failureRef ->
                    failedCount <- failedCount + 1
                    terminalCellRefs <-
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-promise-failed-cell"
                            (CompilerIdentityKernel.ContentDigest.text binding.bindingRef
                             + "|failure=" + CompilerIdentityKernel.ContentDigest.text failureRef)
                        :: terminalCellRefs
                | JpPromiseCellCancelled cancellationRef ->
                    cancelledCount <- cancelledCount + 1
                    terminalCellRefs <-
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-promise-cancelled-cell"
                            (CompilerIdentityKernel.ContentDigest.text binding.bindingRef
                             + "|cancellation=" + CompilerIdentityKernel.ContentDigest.text cancellationRef)
                        :: terminalCellRefs)
            let cellRefs =
                relevant
                |> Array.map (fun binding -> CompilerIdentityKernel.ContentDigest.text binding.bindingRef)
                |> Array.sort
                |> String.concat ";"
            let disposition =
                if List.isEmpty pendingCellRefs && List.isEmpty unboundCellRefs then
                    JpPromiseClosureClosed (terminalCellRefs |> List.sort)
                else
                    JpPromiseClosureOpen(
                        pendingCellRefs |> List.sort,
                        unboundCellRefs |> List.sort)
            let terminalCellsText =
                terminalCellRefs
                |> List.sort
                |> List.map CompilerIdentityKernel.ContentDigest.text
                |> String.concat ";"
            let closurePayload =
                FastRuntimeFormat.format
                    "generation=%d|pending=%d|resolved=%d|failed=%d|cancelled=%d|unbound=%d|cells=%s|terminal=%s"
                    [| box generation
                       box pendingCount
                       box resolvedCount
                       box failedCount
                       box cancelledCount
                       box unboundPendingCount
                       box cellRefs
                       box terminalCellsText |]
            { generation = generation
              pendingCount = pendingCount
              resolvedCount = resolvedCount
              failedCount = failedCount
              cancelledCount = cancelledCount
              unboundPendingCount = unboundPendingCount
              disposition = disposition
              closureRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-promise-closure-proof"
                    closurePayload }

    let private deadmanOutstandingGraphProbeInstall : unit =
        BigStack.terminalFlowInstallDeadmanOutstandingGraphProbe (fun () ->
            let generation = CacheGeneration.current()
            let promiseSnapshot = JpPromiseProducerAuthority.closureSnapshot generation
            let worklistSnapshot = JpSpecializationWorklistAuthority.closureSnapshot generation
            promiseSnapshot.pendingCount,
            worklistSnapshot.registeredCount,
            worklistSnapshot.runningCount)

    type JpWaitGraphEdge = private {
        waitRef : CompilerIdentityKernel.ContentDigest
        generation : int64
        waiter : JpWaiterWorkIdentity
        promise : JpPromiseIdentity
        producer : JpProducerWorkIdentity
        waitKind : JpIvarWaitKind
        waitShapeId : CompilerIdentityKernel.WorkShapeId
        siteId : CompilerIdentityKernel.WorkSiteId
        admittedAtMs : int64
        edgeRef : CompilerIdentityKernel.ContentDigest
    }

    type JpWaitGraphMember =
        | JpWaitGraphMemberOne of edge:JpWaitGraphEdge * owner:JpPromiseOwnerCapability
        | JpWaitGraphMemberMore of edge:JpWaitGraphEdge * owner:JpPromiseOwnerCapability * rest:JpWaitGraphMember

    type JpWaitGraphSccMembership =
        | JpWaitGraphAcyclicMembership of members:JpWaitGraphMember option
        | JpWaitGraphClosedSccMembership of cycle:JpWaitGraphMember * owner:JpPromiseOwnerCapability
        | JpWaitGraphUnownedMembership of edge:JpWaitGraphEdge * owner:JpPromiseOwnerCapability

    type JpWaitGraphDecision =
        | JpWaitGraphAcyclic of membership:JpWaitGraphSccMembership * graphRef:CompilerIdentityKernel.ContentDigest
        | JpWaitGraphProducerUnavailable of membership:JpWaitGraphSccMembership * graphRef:CompilerIdentityKernel.ContentDigest
        | JpWaitGraphCycle of membership:JpWaitGraphSccMembership * graphRef:CompilerIdentityKernel.ContentDigest

    type private JpWaitGraphMessage =
        | JpWaitGraphAdmit of
            edge:JpWaitGraphEdge
            * reply:CompilerKernelV2.PortableOneShotCell<JpWaitGraphDecision>
        | JpWaitGraphResolve of
            waitRef:CompilerIdentityKernel.ContentDigest
            * reply:CompilerKernelV2.PortableOneShotCell<bool>
        | JpWaitGraphSnapshot of
            reply:CompilerKernelV2.PortableOneShotCell<JpWaitGraphDecision>

    module JpWaitGraphAuthority =
        let private mailbox =
            CompilerKernelV2.CompilerRuntimeKernel.mailbox<JpWaitGraphMessage>
                "jp-wait-graph"
                CompilerKernelV2.PortableSemanticLane
                0
                CompilerKernelV2.MailboxFailClosed

        let private waiterId (JpWaiterWorkIdentity value) = value
        let private producerId = function
            | JpProducerExact(_, value) -> Some value
            | JpProducerUnbound _
            | JpProducerGenerationMismatch _ -> None
        let private ownerCapability = function
            | JpProducerExact(owner, _)
            | JpProducerUnbound owner -> owner
            | JpProducerGenerationMismatch(_, _, bindingRef) ->
                JpPromiseOwnerUnbound(
                    JpPromiseIdentity bindingRef,
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-generation-mismatch-owner-capability"
                        (CompilerIdentityKernel.ContentDigest.text bindingRef))
        let private edgeText edge =
            let producerText =
                match edge.producer with
                | JpProducerExact(owner, producer) ->
                    "Exact(producer=" + string producer
                    + "|owner=" + jpPromiseOwnerCapabilityText owner + ")"
                | JpProducerUnbound owner ->
                    "Unbound(owner=" + jpPromiseOwnerCapabilityText owner + ")"
                | JpProducerGenerationMismatch(expectedGeneration, actualGeneration, bindingRef) ->
                    FastRuntimeFormat.format "GenerationMismatch(expected=%d|actual=%d|binding_ref=%s)" [| box expectedGeneration; box actualGeneration; box (CompilerIdentityKernel.ContentDigest.text bindingRef) |]
            FastRuntimeFormat.format "%d|%s|%s|%s|%s|%d" [| box (waiterId edge.waiter); box (CompilerIdentityKernel.ContentDigest.text (let (JpPromiseIdentity value) = edge.promise in value)); box producerText; box (CompilerIdentityKernel.WorkShapeIdOps.text edge.waitShapeId); box (CompilerIdentityKernel.WorkSiteIdOps.text edge.siteId); box edge.generation |]

        let private graphRefOf (edges:Map<CompilerIdentityKernel.ContentDigest,JpWaitGraphEdge>) =
            edges
            |> Map.toSeq
            |> Seq.map (snd >> edgeText)
            |> String.concat "||"
            |> CompilerIdentityKernel.ContentDigest.ofText "jp-wait-graph"

        let private memberOf edge =
            JpWaitGraphMemberOne(edge, ownerCapability edge.producer)

        let private tryPathFrom start edges =
            let byWaiter =
                edges
                |> Map.toSeq
                |> Seq.map snd
                |> Seq.groupBy (fun edge -> waiterId edge.waiter)
                |> Seq.map (fun (key, values) -> key, values |> Seq.toList)
                |> Map.ofSeq
            let rec walk visited current path =
                if Set.contains current visited then path
                else
                    let visited = Set.add current visited
                    match Map.tryFind current byWaiter with
                    | None -> None
                    | Some candidates ->
                        candidates
                        |> List.tryPick (fun edge ->
                            match producerId edge.producer with
                            | None -> None
                            | Some next ->
                                let nextPath =
                                    match path with
                                    | None -> memberOf edge
                                    | Some existing ->
                                        JpWaitGraphMemberMore(edge, ownerCapability edge.producer, existing)
                                if next = start then Some nextPath
                                else walk visited next (Some nextPath))
            walk Set.empty start None

        let private acyclicMembership edges =
            edges
            |> Map.toSeq
            |> Seq.map snd
            |> Seq.fold (fun state edge ->
                match state with
                | None -> Some(memberOf edge)
                | Some existing ->
                    Some(JpWaitGraphMemberMore(edge, ownerCapability edge.producer, existing))) None
            |> JpWaitGraphAcyclicMembership

        let private decide edges =
            let graphRef = graphRefOf edges
            match edges |> Map.toSeq |> Seq.map snd |> Seq.tryPick (fun edge -> tryPathFrom (waiterId edge.waiter) edges) with
            | Some cycle ->
                let cycleOwner =
                    match cycle with
                    | JpWaitGraphMemberOne(_, owner)
                    | JpWaitGraphMemberMore(_, owner, _) -> owner
                JpWaitGraphCycle(JpWaitGraphClosedSccMembership(cycle, cycleOwner), graphRef)
            | None ->
                match edges |> Map.toSeq |> Seq.map snd |> Seq.tryFind (fun edge -> producerId edge.producer |> Option.isNone) with
                | Some unavailable ->
                    JpWaitGraphProducerUnavailable(
                        JpWaitGraphUnownedMembership(unavailable, ownerCapability unavailable.producer),
                        graphRef)
                | None -> JpWaitGraphAcyclic(acyclicMembership edges, graphRef)

        let rec private loop edges =
            job {
                let! message =
                    CompilerKernelV2.CompilerRuntimeKernel.take mailbox
                match message with
                | JpWaitGraphAdmit(edge, reply) ->
                    let next = Map.add edge.waitRef edge edges
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                            reply
                            (decide next)
                    return! loop next
                | JpWaitGraphResolve(waitRef, reply) ->
                    let existed = Map.containsKey waitRef edges
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                            reply
                            existed
                    return! loop (Map.remove waitRef edges)
                | JpWaitGraphSnapshot reply ->
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                            reply
                            (decide edges)
                    return! loop edges
            }

        let private started = lazy (startHopacJob (loop Map.empty))
        let private ensureStarted () =
            CompilerRuntimeActivation.requireInProcessEntered "jp_wait_graph"
            started.Force()

        let admit edge : Job<JpWaitGraphDecision> =
            ensureStarted()
            job {
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<JpWaitGraphDecision>
                        "jp-wait-graph-admit"
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.send
                        mailbox
                        (JpWaitGraphAdmit(edge, reply))
                return!
                    CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
            }

        let resolve waitRef : Job<bool> =
            ensureStarted()
            job {
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<bool>
                        "jp-wait-graph-resolve"
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.send
                        mailbox
                        (JpWaitGraphResolve(waitRef, reply))
                return!
                    CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
            }

        let snapshot () : Job<JpWaitGraphDecision> =
            ensureStarted()
            job {
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<JpWaitGraphDecision>
                        "jp-wait-graph-snapshot"
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.send
                        mailbox
                        (JpWaitGraphSnapshot reply)
                return!
                    CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
            }

    module JpOperationalWorkGraphAuthority =
        // Pass 4 removes the shadow actor entirely.  These cold bootstrap
        // functions are replaced by JpOperationalDomain during module
        // initialization; invoking them before cutover is a protocol error.
        let private removed () =
            invalidOp "legacy operational work graph authority was removed by the portable runtime cutover"

        let apply (_:CompilerKernelV2.OperationalWorkGraphCommand) : Job<CompilerKernelV2.OperationalWorkGraphEvent> =
            removed ()

        let snapshot () : Job<CompilerKernelV2.OperationalWorkGraph> =
            removed ()

        let awaitQuiescence () : Job<CompilerIdentityKernel.ContentDigest> =
            removed ()

    type JpLogicalSuspension<'T> = private {
        waitRef : CompilerIdentityKernel.ContentDigest
        waiterWork : CompilerKernelV2.WorkItem<
            CompilerKernelV2.ElaboratedPhase,
            CompilerKernelV2.JoinPointWorkKind,
            CompilerKernelV2.WorkOwnerBoundState,
            CompilerKernelV2.WorkRunningState>
        suspension : CompilerKernelV2.WorkSuspension<
            CompilerKernelV2.ElaboratedPhase,
            CompilerKernelV2.JoinPointWorkKind,
            CompilerKernelV2.WorkOwnerBoundState,
            'T>
        waitGraphEdge : JpWaitGraphEdge
    }

    type JpLogicalWaitResolution<'T> =
        | JpLogicalWaitResolved of result:Result<'T,CompilerKernelV2.WorkResumeFailure>
        | JpLogicalWaitGenerationSuperseded of CacheGeneration.GenerationChange

    type JpIvarWaitOwnershipSnapshot = private {
        pending : int64
        active : int64
        jobs : int
        queueDepth : int
        countdownRemaining : int64
        oldestActiveAgeMs : int64
        ownedSetDigest : CompilerIdentityKernel.ContentDigest
        oldestActiveJobId : int64
        oldestActiveJobName : string
    }

    type JpIvarWaitWindow = private {
        baseWaitMs : int64
        idleMs : int64
        probeMs : int64
        hardAbortMs : int64
    }

    type JpIvarWaitStallDecision =
        | JpIvarWaitBelowProbe
        | JpIvarWaitDeferredByOwnedWork of JpIvarWaitOwnershipSnapshot
        | JpIvarWaitAwaitingHardWindow of JpIvarWaitOwnershipSnapshot
        | JpIvarWaitHardStall of JpIvarWaitOwnershipSnapshot

    type JpIvarWaitResolution<'T> =
        | JpIvarWaitResolved of value:'T
        | JpIvarWaitGenerationSuperseded of CacheGeneration.GenerationChange
        | JpIvarWaitWindowElapsed

    type JpIvarWaitStallAgeBasis =
        | JpIvarWaitStallAgeOldestActiveJob
        | JpIvarWaitStallAgeWaitElapsedWithoutActiveJob

    // Recovery claims are scoped to the actual liveness proof. A generation-wide
    // latch poisoned unrelated semantic waiters after material progress changed the
    // graph. The scope therefore includes generation, semantic graph epoch, target
    // promise, owned-set digest and authority role.
    [<Struct>]
    type JpOwnedStallRecoveryClaimScope = private {
        generation : int64
        graphEpoch : int64
        targetPromiseRef : string
        ownedSetDigest : string
        authorityRole : JpWorkAuthorityRole
    }

    type JpOwnedStallRecoveryClaimDecision =
        | JpOwnedStallRecoveryClaimGranted of scope:JpOwnedStallRecoveryClaimScope
        | JpOwnedStallRecoveryClaimAlreadyHeld of scope:JpOwnedStallRecoveryClaimScope
        | JpOwnedStallRecoveryClaimRejectedStale of requested:JpOwnedStallRecoveryClaimScope * claimed:JpOwnedStallRecoveryClaimScope

    type JpBlockingCompensationDecision =
        | JpBlockingCompensationNotRequired
        | JpBlockingCompensationNotInstalled of generation:int64
        | JpBlockingCompensationStarted of generation:int64 * workerCount:int
        | JpBlockingCompensationExpanded of generation:int64 * addedWorkerCount:int * totalWorkerCount:int
        | JpBlockingCompensationAlreadyStarted of generation:int64 * workerCount:int
        | JpBlockingCompensationAtCapacity of generation:int64 * workerCount:int
        | JpBlockingCompensationRefusedAtRunnableCapacity of generation:int64 * runnableWorkers:int * runnableLimit:int * totalWorkers:int * populationLimit:int * parkedWaiters:int * queueDepth:int
        | JpBlockingCompensationRefusedAtPopulationCapacity of generation:int64 * runnableWorkers:int * runnableLimit:int * totalWorkers:int * populationLimit:int * parkedWaiters:int * queueDepth:int
        | JpBlockingCompensationRejectedStale of requestedGeneration:int64 * currentGeneration:int64

    type JpBlockingCompensationRequest =
        | JpBlockingCompensationWaitAdmission of waitName:string
        | JpBlockingCompensationOwnedStall of failureText:string
        | JpBlockingCompensationLegacyQueuePressure

    let jpBlockingCompensationRequestText = function
        | JpBlockingCompensationWaitAdmission waitName ->
            "WaitAdmission(wait=" + waitName + ")"
        | JpBlockingCompensationOwnedStall failureText ->
            "OwnedStall(" + failureText + ")"
        | JpBlockingCompensationLegacyQueuePressure ->
            "LegacyQueuePressure"

    let jpBlockingCompensationRequestAllowsStallEscalation = function
        | JpBlockingCompensationOwnedStall _ -> true
        | JpBlockingCompensationWaitAdmission _
        | JpBlockingCompensationLegacyQueuePressure -> false

    // A missing codegen dictionary has three semantically distinct meanings.
    // Keep the distinction in the type system so a generation reset cannot fall
    // through to the generic observer-only codegen failure path.
    type CodegenJpClosureBodyCellResolution<'Body,'Range> =
        | CodegenJpClosureBodyCellReady of body:'Body * range:'Range
        | CodegenJpClosureBodyCellCancelled of JpClosureControlCancellation
        | CodegenJpClosureBodyCellFailed of System.Runtime.ExceptionServices.ExceptionDispatchInfo
        | CodegenJpClosureBodyCellPending of Hopac.IVar<JpClosureBodyCellPayload>
        | CodegenJpClosureBodyCellMissing

    type CodegenJpMethodBodyCellResolution<'Body,'Range> =
        | CodegenJpMethodBodyCellReady of body:'Body * range:'Range
        | CodegenJpMethodBodyCellCancelled of JpMethodControlCancellation
        | CodegenJpMethodBodyCellFailed of System.Runtime.ExceptionServices.ExceptionDispatchInfo
        | CodegenJpMethodBodyCellPending of Hopac.IVar<JpMethodBodyCellPayload>
        | CodegenJpMethodBodyCellMissing

    [<NoEquality; NoComparison>]
