    type JpIvarWaitFailure =
        | JpIvarWaitFailureGenerationChanged of CacheGeneration.GenerationChange
        | JpIvarWaitFailureMissingProducer of JpIvarWaitOwnershipSnapshot
        | JpIvarWaitFailureOwnedButStalled of ownership:JpIvarWaitOwnershipSnapshot * unchangedWindows:int * stallAgeMs:int64 * stallAgeBasis:JpIvarWaitStallAgeBasis
        | JpIvarWaitFailureHardStall of JpIvarWaitOwnershipSnapshot

    let jpIvarWaitFailureText = function
        | JpIvarWaitFailureGenerationChanged change -> CacheGeneration.generationChangeText change
        | JpIvarWaitFailureMissingProducer ownership ->
            FastRuntimeFormat.format "JpIvarWaitFailureMissingProducer(pending=%d|active=%d|jobs=%d|queue=%d|countdown=%d|oldest=%d)" [| box ownership.pending; box ownership.active; box ownership.jobs; box ownership.queueDepth; box ownership.countdownRemaining; box ownership.oldestActiveAgeMs |]
        | JpIvarWaitFailureOwnedButStalled(ownership, unchangedWindows, stallAgeMs, stallAgeBasis) ->
            FastRuntimeFormat.format "JpIvarWaitFailureOwnedButStalled(pending=%d|active=%d|jobs=%d|queue=%d|countdown=%d|oldest=%d|stall_age=%d|stall_age_basis=%s|unchanged_windows=%d|owned_set=%s|oldest_job=%d:%s)" [| box ownership.pending; box ownership.active; box ownership.jobs; box ownership.queueDepth; box ownership.countdownRemaining; box ownership.oldestActiveAgeMs; box stallAgeMs; box (jpIvarWaitStallAgeBasisText stallAgeBasis); box unchangedWindows; box (CompilerIdentityKernel.ContentDigest.text ownership.ownedSetDigest); box ownership.oldestActiveJobId; box ownership.oldestActiveJobName |]
        | JpIvarWaitFailureHardStall ownership ->
            FastRuntimeFormat.format "JpIvarWaitFailureHardStall(pending=%d|active=%d|jobs=%d|queue=%d|countdown=%d|oldest=%d)" [| box ownership.pending; box ownership.active; box ownership.jobs; box ownership.queueDepth; box ownership.countdownRemaining; box ownership.oldestActiveAgeMs |]

    let private jpIvarWaitStallDecisionFor (window:JpIvarWaitWindow) (ownership:JpIvarWaitOwnershipSnapshot) =
        let ownedWorkPresent =
            ownership.pending > 0L
            || ownership.active > 0L
            || ownership.jobs > 0
            || ownership.queueDepth > 0
            || ownership.countdownRemaining > 0L
        let hardWindowReached =
            window.hardAbortMs > 0L
            && window.baseWaitMs >= window.hardAbortMs
            && window.idleMs >= window.hardAbortMs
        if window.baseWaitMs < window.probeMs || window.idleMs < window.probeMs then
            JpIvarWaitBelowProbe
        elif ownedWorkPresent && not hardWindowReached then
            JpIvarWaitDeferredByOwnedWork ownership
        elif hardWindowReached then
            JpIvarWaitHardStall ownership
        else
            JpIvarWaitAwaitingHardWindow ownership

    type JpProcessorCapacityAuthority =
        | JpProcessorCapacityEnvironment
        | JpProcessorCapacityAffinityExpanded

    type JpProcessorAffinityObservation =
        | JpProcessorAffinityUnavailable
        | JpProcessorAffinityObserved of count:int

    type JpProcessorCapacitySnapshot = private {
        environmentCount : int
        affinityObservation : JpProcessorAffinityObservation
        affinityCount : int
        parallelCapacity : int
        authority : JpProcessorCapacityAuthority
    }

    let private jpCountAffinityBits (value:uint64) =
        let mutable bits = value
        let mutable count = 0
        while bits <> 0UL do
            count <- count + 1
            bits <- bits &&& (bits - 1UL)
        count

    let private jpProcessorCapacitySnapshot () =
        let environmentCount = max 1 Environment.ProcessorCount
        let affinityObservation =
            try
                use currentProcess = System.Diagnostics.Process.GetCurrentProcess()
                let count =
                    currentProcess.ProcessorAffinity.ToInt64()
                    |> uint64
                    |> jpCountAffinityBits
                if count > 0 then JpProcessorAffinityObserved count
                else JpProcessorAffinityUnavailable
            with _ -> JpProcessorAffinityUnavailable
        let affinityCount =
            match affinityObservation with
            | JpProcessorAffinityUnavailable -> 0
            | JpProcessorAffinityObserved count -> count
        if affinityCount > environmentCount then
            {
                environmentCount = environmentCount
                affinityObservation = affinityObservation
                affinityCount = affinityCount
                parallelCapacity = affinityCount
                authority = JpProcessorCapacityAffinityExpanded
            }
        else
            {
                environmentCount = environmentCount
                affinityObservation = affinityObservation
                affinityCount = affinityCount
                parallelCapacity = environmentCount
                authority = JpProcessorCapacityEnvironment
            }

    let jpProcessorCapacityAuthorityText = function
        | JpProcessorCapacityEnvironment -> "EnvironmentProcessorCount"
        | JpProcessorCapacityAffinityExpanded -> "ProcessAffinityExpanded"

    let jpProcessorAffinityObservationText = function
        | JpProcessorAffinityUnavailable -> "Unavailable"
        | JpProcessorAffinityObserved count -> sprintf "Observed(count=%d)" count

    type JpInstalledBuildOkRedriveReason =
        | JpRootCompletePendingPinnedTerminal
        | JpRootCompleteStalePending
        | JpStallPinnedTerminal

    let private jpInstalledBuildOkRedriveReasonText = function
        | JpRootCompletePendingPinnedTerminal -> "jp_wait_root_complete_pending_pinned_terminal"
        | JpRootCompleteStalePending -> "jp_wait_root_complete_stale_pending"
        | JpStallPinnedTerminal -> "jp_wait_stall_pinned_terminal"

    let private jpInstalledBuildOkRedriveUnavailableRegistry =
        System.Collections.Concurrent.ConcurrentDictionary<JpInstalledBuildOkRedriveReason,byte>()

    let private tryInstalledBuildOkRedrive reason =
        let reasonText = jpInstalledBuildOkRedriveReasonText reason
        let allowCrossKindReplayCheck = reason = JpStallPinnedTerminal
        let result = BigStack.terminalFlowGlobalRedriveInstalledBuildOk allowCrossKindReplayCheck reasonText
        match result with
        | Some(false, reducerRevision, terminalRef, fillRef) ->
            DiagJson.emit (
                FastRuntimeFormat.format "{\"kind\":\"terminal_installed_buildok_redrive_suppressed\",\"terminal_ref\":%u,\"fill_ref\":%u,\"reducer_revision\":%d,\"reason\":%s,\"dedupe_first_seen\":false,\"authority\":\"installed_buildok_reducer_mailbox_redrive\",\"next\":\"await_reducer_revision_change\"}" [| box terminalRef; box fillRef; box reducerRevision; box (DiagJson.esc reasonText) |])
        | None when jpInstalledBuildOkRedriveUnavailableRegistry.TryAdd(reason, 0uy) ->
            DiagJson.emit (
                sprintf "{\"kind\":\"terminal_installed_buildok_redrive_unavailable\",\"reason\":%s,\"dedupe_first_seen\":true,\"authority\":\"installed_buildok_projection_check\",\"next\":\"preserve_existing_jp_failure_policy\"}"
                    (DiagJson.esc reasonText))
        | _ -> ()
        result

