    type JpSlowJobSensitivityId =
        | JpSlowJobSensitiveCommandBoundary
        | JpSlowJobOrdinary

    let private jpSlowJobSensitivityId (name:string) =
        let safe = if System.String.IsNullOrEmpty name then "" else name
        let tokens =
            safe.Split(
                [| '|'; ':'; ','; ';'; ' '; '='; '('; ')'; '['; ']'; '/'; '\\'; '\n'; '\r'; '\t' |],
                StringSplitOptions.RemoveEmptyEntries)
            |> Set.ofArray
        if Set.contains "execute_with_options" tokens
           || Set.contains "split_command" tokens
           || Set.contains "split_args" tokens then
            JpSlowJobSensitiveCommandBoundary
        else
            JpSlowJobOrdinary

    type RecordMapNonRecordShapeId =
        | RecordMapNullShape
        | RecordMapFunctionLikeNonRecord
        | RecordMapRecordLikeTextNonRecord
        | RecordMapUnknownPlaceholder
        | RecordMapNonRecord

    let private recordMapFirstSignificantChar (text:string) =
        if System.Object.ReferenceEquals(text,null) then None
        else
            let mutable i = 0
            while i < text.Length && System.Char.IsWhiteSpace text.[i] do
                i <- i + 1
            if i < text.Length then Some text.[i] else None

    let private recordMapContainsFunctionArrow (text:string) =
        if System.Object.ReferenceEquals(text,null) then false
        else
            let mutable found = false
            let mutable i = 0
            while not found && i + 1 < text.Length do
                if text.[i] = '-' && text.[i + 1] = '>' then found <- true
                else i <- i + 1
            found

    let private recordMapNonRecordShapeId (text:string) =
        if System.Object.ReferenceEquals(text,null) then RecordMapNullShape
        elif recordMapContainsFunctionArrow text then RecordMapFunctionLikeNonRecord
        elif recordMapFirstSignificantChar text = Some '{' then RecordMapRecordLikeTextNonRecord
        elif text = "?" then RecordMapUnknownPlaceholder
        else RecordMapNonRecord

    let private recordMapNonRecordShapeText = function
        | RecordMapNullShape -> "null"
        | RecordMapFunctionLikeNonRecord -> "function_like_non_record"
        | RecordMapRecordLikeTextNonRecord -> "record_like_text_non_record"
        | RecordMapUnknownPlaceholder -> "unknown_placeholder"
        | RecordMapNonRecord -> "non_record"

