    type TyMacroControlId =
        | TyMacroPragma
        | TyMacroBreak
        | TyMacroReturn
        | TyMacroBody

    let private textHasOrdinalPrefix (prefix:string) (text:string) =
        not (System.String.IsNullOrEmpty text)
        && text.Length >= prefix.Length
        && System.String.CompareOrdinal(text, 0, prefix, 0, prefix.Length) = 0

    let private tyMacroControlFor (text:string) =
        if textHasOrdinalPrefix "#pragma" text then TyMacroPragma
        elif text = "break" then TyMacroBreak
        elif textHasOrdinalPrefix "return" text then TyMacroReturn
        else TyMacroBody

