    let jp_codegen_body_materialization_recovery =
        System.Collections.Concurrent.ConcurrentDictionary<
            CompilerIdentityKernel.ContentDigest,
            JpCodegenBodyMaterializationRecoveryStateId>()

    let jpCodegenBodyMaterializationRecoveryTryRequest verificationRef triggerRef =
        let initialAttempt = JpCodegenBodyInitialMaterializationAttempt triggerRef
        if jp_codegen_body_materialization_recovery.TryAdd(
            verificationRef,
            JpCodegenBodyMaterializationRecoveryRequested initialAttempt) then true
        else
            let mutable current = Unchecked.defaultof<JpCodegenBodyMaterializationRecoveryStateId>
            if jp_codegen_body_materialization_recovery.TryGetValue(verificationRef, &current) then
                match current with
                | JpCodegenBodyMaterializationRecoveryRequested _ -> true
                | JpCodegenBodyMaterializationRecoveryAttempted((JpCodegenBodyInitialMaterializationAttempt _ as previousAttempt), _) ->
                    let restartRef =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-codegen-body-fresh-root-rematerialization-recovery"
                            (jpCodegenBodyMaterializationAttemptText previousAttempt
                             + "|trigger=" + CompilerIdentityKernel.ContentDigest.text triggerRef)
                    let restartAttempt =
                        JpCodegenBodyFreshRootRestartAttempt(previousAttempt, restartRef)
                    if jp_codegen_body_materialization_recovery.TryUpdate(
                        verificationRef,
                        JpCodegenBodyMaterializationRecoveryRequested restartAttempt,
                        current) then true
                    else
                        let mutable concurrent = Unchecked.defaultof<JpCodegenBodyMaterializationRecoveryStateId>
                        if jp_codegen_body_materialization_recovery.TryGetValue(verificationRef, &concurrent) then
                            match concurrent with
                            | JpCodegenBodyMaterializationRecoveryRequested _ -> true
                            | JpCodegenBodyMaterializationRecoveryAttempted _ -> false
                        else false
                | JpCodegenBodyMaterializationRecoveryAttempted((JpCodegenBodyFreshRootRestartAttempt _), _) -> false
            else false

    let jpCodegenBodyMaterializationRecoveryIsRequested verificationRef =
        let mutable current = Unchecked.defaultof<JpCodegenBodyMaterializationRecoveryStateId>
        if jp_codegen_body_materialization_recovery.TryGetValue(verificationRef, &current) then
            match current with
            | JpCodegenBodyMaterializationRecoveryRequested _ -> true
            | JpCodegenBodyMaterializationRecoveryAttempted _ -> false
        else false

    let jpCodegenBodyMaterializationRecoveryTryEnter verificationRef =
        let mutable current = Unchecked.defaultof<JpCodegenBodyMaterializationRecoveryStateId>
        if jp_codegen_body_materialization_recovery.TryGetValue(verificationRef, &current) then
            match current with
            | JpCodegenBodyMaterializationRecoveryRequested attempt ->
                let next = JpCodegenBodyMaterializationRecoveryAttempted(attempt, System.Environment.TickCount64)
                if jp_codegen_body_materialization_recovery.TryUpdate(verificationRef, next, current) then
                    Some (JpCodegenBodyMaterializationRecoveryExecutionStarted attempt)
                else None
            | JpCodegenBodyMaterializationRecoveryAttempted(attempt, _) ->
                Some (JpCodegenBodyMaterializationRecoveryExecutionContinued attempt)
        else None

    let jpCodegenBodyMaterializationRecoveryTryGetAttempted verificationRef =
        let mutable current = Unchecked.defaultof<JpCodegenBodyMaterializationRecoveryStateId>
        if jp_codegen_body_materialization_recovery.TryGetValue(verificationRef, &current) then
            match current with
            | JpCodegenBodyMaterializationRecoveryAttempted(attempt, _) -> Some (jpCodegenBodyMaterializationAttemptRef attempt)
            | JpCodegenBodyMaterializationRecoveryRequested _ -> None
        else None

    let jpCodegenBodyMaterializationRecoveryAttemptClock verificationRef =
        let mutable current = Unchecked.defaultof<JpCodegenBodyMaterializationRecoveryStateId>
        if jp_codegen_body_materialization_recovery.TryGetValue(verificationRef, &current) then
            match current with
            | JpCodegenBodyMaterializationRecoveryAttempted(attempt, startedAtMs) ->
                Some(attempt, max 0L (System.Environment.TickCount64 - startedAtMs))
            | JpCodegenBodyMaterializationRecoveryRequested _ -> None
        else None

    let jpCodegenBodyMaterializationRecoverySnapshotText verificationRef =
        let mutable current = Unchecked.defaultof<JpCodegenBodyMaterializationRecoveryStateId>
        if jp_codegen_body_materialization_recovery.TryGetValue(verificationRef, &current) then
            jpCodegenBodyMaterializationRecoveryStateText current
        else "Absent"

    let jpCodegenBodyMaterializationRecoveryRetire verificationRef =
        let mutable removed = Unchecked.defaultof<JpCodegenBodyMaterializationRecoveryStateId>
        jp_codegen_body_materialization_recovery.TryRemove(verificationRef, &removed) |> ignore

    // F# does not permit this DU as a local declaration inside peval; keep the lookup algebra at module type scope.
