        | JpUnionCaseConcreteSymbol of symbol:string
        | JpUnionCaseResolvedPlaceholder of placeholderKind:JpRecPlaceholderKind * originalSymbol:string * resolvedSymbol:string
        | JpUnionCasePendingPlaceholder of placeholderKind:JpRecPlaceholderKind * symbol:string
        | JpUnionCaseResolvedNonSymbol of placeholderKind:JpRecPlaceholderKind * symbol:string * resolvedTy:Ty

    let private jpUnionCaseSymbolResolutionText = function
        | JpUnionCaseConcreteSymbol _ -> "ConcreteSymbol"
        | JpUnionCaseResolvedPlaceholder _ -> "ResolvedPlaceholder"
        | JpUnionCasePendingPlaceholder _ -> "PendingPlaceholder"
        | JpUnionCaseResolvedNonSymbol _ -> "ResolvedNonSymbol"

    let private jpReplayQuiescenceDecisionText = function
        | JpReplayQuiescenceReadyForTerminal -> "ready_for_terminal"
        | JpReplayQuiescenceDrainQueuedReplay -> "drain_queued_replay"
        | JpReplayQuiescenceAwaitActiveReplay -> "await_active_replay"
        | JpReplayQuiescenceCreditWithoutQueue -> "operational_credit_without_queue"

    let private jpReplayQuiescenceDecisionFor queueDepth activeDepth operationalOpen =
        if activeDepth > 0 then JpReplayQuiescenceAwaitActiveReplay
        elif queueDepth > 0 then JpReplayQuiescenceDrainQueuedReplay
        elif operationalOpen > 0L then JpReplayQuiescenceCreditWithoutQueue
        else JpReplayQuiescenceReadyForTerminal

    let private jpReplayQuiescenceActionFor decision drainScheduled operationalOpenAfterReconciliation =
        match decision, drainScheduled, operationalOpenAfterReconciliation with
        | JpReplayQuiescenceCreditWithoutQueue, _, 0L -> JpReplayRetryAfterClosedCredit
        | JpReplayQuiescenceReadyForTerminal, _, _ -> JpReplayRetryReadyForTerminal
        | JpReplayQuiescenceDrainQueuedReplay, true, _ -> JpReplayDrainQueuedBeforeTerminal
        | JpReplayQuiescenceDrainQueuedReplay, false, _ -> JpReplayRetryAfterDrainRace
        | JpReplayQuiescenceAwaitActiveReplay, _, _ -> JpReplayAwaitActiveDriver
        | JpReplayQuiescenceCreditWithoutQueue, _, _ -> JpReplayRetainOperationalCredit

    let private jpReplayQuiescenceActionText = function
        | JpReplayRetryAfterClosedCredit -> "refresh_terminal_progress_then_retry_closure_after_closed_replay_liveness_credit_return"
        | JpReplayRetryReadyForTerminal -> "refresh_terminal_progress_then_retry_closure_with_closed_replay_credit"
        | JpReplayDrainQueuedBeforeTerminal -> "drain_queued_replay_before_terminal_closure"
        | JpReplayRetryAfterDrainRace -> "refresh_terminal_progress_then_retry_closure_after_replay_drain_race"
        | JpReplayAwaitActiveDriver -> "await_active_replay_driver_then_retry_terminal_closure"
        | JpReplayRetainOperationalCredit -> "retain_non_replay_or_conflicted_operational_credit"

    let private jpReplayQuiescenceActionRetriesTerminal = function
        | JpReplayRetryAfterClosedCredit
        | JpReplayRetryReadyForTerminal
        | JpReplayRetryAfterDrainRace -> true
        | JpReplayDrainQueuedBeforeTerminal
        | JpReplayAwaitActiveDriver
        | JpReplayRetainOperationalCredit -> false

    /// ### peval
    /// Rust-style report for partial evaluation that unrolls without end (typically an `inl` recursion on a
    /// value only known at run time): the source span, the repeating cycle with counts, the entry path, why it
    /// happens and how to fix it. Frames are innermost first: (path, 0-based line, 0-based column).
    module RunawayUnrollDiagnostic =
        let private sourceLines = System.Collections.Concurrent.ConcurrentDictionary<string, string[]>()
        let private lineText (path: string) (line: int) =
            let lines = sourceLines.GetOrAdd(path, fun p -> try System.IO.File.ReadAllLines p with _ -> [||])
            if line >= 0 && line < lines.Length then lines.[line] else ""
        let private shortPath (path: string) =
            let p = path.Replace('\\', '/')
            match p.LastIndexOf "/lib/" with
            | i when i >= 0 -> p.Substring(i + 1)
            | _ -> System.IO.Path.GetFileName p
        let private collapse (frames: (string * int * int) list) =
            frames
            |> List.fold (fun acc (p, l, c) -> match acc with (p', l', _) :: _ when p' = p && l' = l -> acc | _ -> (p, l, c) :: acc) []
            |> List.rev
        let render (code: string) (headline: string) (frames: (string * int * int) list) (limitNote: string) =
            let sb = System.Text.StringBuilder()
            let add (s: string) = sb.Append(s).Append('\n') |> ignore
            add (sprintf "error[%s]: %s" code headline)
            let counts = frames |> List.countBy (fun (p, l, _) -> p, l) |> Map.ofList
            let count p l = Map.tryFind (p, l) counts |> Option.defaultValue 0
            match frames with
            | (p, l, c) :: _ ->
                let number = string (l + 1)
                let pad = String.replicate number.Length " "
                add (sprintf "%s--> %s:%d:%d" pad p (l + 1) (c + 1))
                add (sprintf "%s |" pad)
                add (sprintf "%s | %s" number ((lineText p l).TrimEnd()))
                add (sprintf "%s | %s^ reached %d times on the current evaluation path" pad (String.replicate (max 0 c) " ") (count p l))
                add (sprintf "%s |" pad)
            | [] -> ()
            // The cycle is what repeats on the scale of the hottest frame; a frame that recurs a few times (the
            // entry call, an outer wrapper) belongs to the entry path.
            let hottest = if counts.IsEmpty then 0 else counts |> Map.toSeq |> Seq.map snd |> Seq.max
            let inCycle p l = count p l > 1 && count p l * 4 >= hottest
            let cycle =
                frames
                |> List.filter (fun (p, l, _) -> inCycle p l)
                |> List.distinctBy (fun (p, l, _) -> p, l)
                |> List.truncate 12
            if not cycle.IsEmpty then
                add "  = note: the repeating cycle (innermost first):"
                for (p, l, _) in cycle do
                    add (sprintf "          %s:%d  %s  (x%d)" (shortPath p) (l + 1) ((lineText p l).Trim()) (count p l))
            let entry = frames |> List.filter (fun (p, l, _) -> not (inCycle p l)) |> List.rev |> collapse
            if not entry.IsEmpty then
                add "  = note: entered from (outermost first):"
                let shown = if entry.Length <= 14 then entry else List.take 7 entry @ List.skip (entry.Length - 7) entry
                if entry.Length > 14 then add (sprintf "          (%d frames, showing the first and last 7)" entry.Length)
                for (p, l, _) in shown do
                    add (sprintf "          %s:%d  %s" (shortPath p) (l + 1) ((lineText p l).Trim()))
            add "  = note: an `inl` function is inlined at every call site; when it recurses on a value only known at run time"
            add "          (an index, a list, a length), every level adds another branch and partial evaluation never reaches a base case"
            add "  = help: make the recursive function a join point (`let rec`, or `join` the recursive call) so the recursion runs"
            add "          at run time, or decide on a bound known at compile time (`join_body_unit body len i`, not on the index)"
            add (sprintf "  = help: %s" limitNote)
            sb.ToString().TrimEnd()

    /// What a stalled build waits on in partial evaluation, for the BuildFile stall message: `peval` installs a
    /// probe over its join-point tables (join points whose specialization is still pending, by name).
    module PevalStallProbe =
        let mutable pendingJoinPoints : unit -> string = fun () -> "not_started"
        /// Set when a match ran into a join-point placeholder and the build switched to inline JP recompute
        /// (FRONTIER.md fix 44). That recovery requests sequential mode, which the output write guard would
        /// otherwise read as an unstable run. Reset at the start of each BuildFile transaction.
        type PevalRecoveryCause =
            | RecoveryPlaceholderPatternMiss of patternNodeId: int
            | RecoveryOrphanedCells
            | RecoveryRequestedByEnvironment
        type PevalRecoveryState =
            | RecoveryNotEntered
            | RecoveryEntered of PevalRecoveryCause
        let mutable private recovery = RecoveryNotEntered
        let recoveryActive () = match recovery with RecoveryEntered _ -> true | RecoveryNotEntered -> false
        /// The first cause wins; later ones do not overwrite it.
        let enterRecovery cause = match recovery with RecoveryNotEntered -> recovery <- RecoveryEntered cause | RecoveryEntered _ -> ()
        let resetRecovery () = recovery <- RecoveryNotEntered
        let recoveryText () =
            match recovery with
            | RecoveryNotEntered -> "not_entered"
            | RecoveryEntered (RecoveryPlaceholderPatternMiss nodeId) -> sprintf "entered(placeholder_pattern_miss node=%d)" nodeId
            | RecoveryEntered RecoveryOrphanedCells -> "entered(orphaned_cells)"
            | RecoveryEntered RecoveryRequestedByEnvironment -> "entered(SPIRAL_HOPAC_INLINE_JP)"
        /// Raised by peval's root when join-point cells stay orphaned after inline recovery: the BuildFile caller
        /// runs a fresh peval (fresh tables, a reset replay store) with inline recovery still on (fix 51).
        exception PevalInlineRestart of string
        /// Codegen runs after peval's join-point graph is quiescent, so a body cell still pending then has no
        /// producer left. Codegen used to wait on it without limit (and outside the build budget); it now waits
        /// this long and then fails closed with the key (FRONTIER.md fix 46).
        let codegenPendingCellWaitMs =
            match System.Int32.TryParse(System.Environment.GetEnvironmentVariable "SPIRAL_CODEGEN_PENDING_CELL_WAIT_MS") with
            | true, ms when ms > 0 -> ms
            | _ -> 30000
        let awaitCodegenCellOrFail (ivar: Hopac.IVar<'T>) (describe: unit -> string) =
            let filled =
                Hopac.run (
                    Hopac.Alt.choose [
                        Hopac.IVar.read ivar |> Hopac.Alt.afterFun (fun _ -> true)
                        Hopac.timeOutMillis codegenPendingCellWaitMs |> Hopac.Alt.afterFun (fun () -> false) ])
            if not filled then
                raise (PartEvalTypeError([], sprintf "[spiral_compiler] EJP0014: codegen JP body cell still pending after %d ms with the join-point graph quiescent (orphaned cell, no producer left): %s" codegenPendingCellWaitMs (describe ())))

    let peval (env : PartEvalTopEnv) (x : E) : (TypedBind [] * Ty) * PartEvalResult =
        // Emit effective runtime knobs once per process; diagnostics are not execution authority.
        DiagSidecar.emitEnvSnapshotOnce()
        try
            DiagSidecar.emit (FastRuntimeFormat.format "SETTINGS bigstack_mb_global=%d bigstack_max_nest=%d term_mb=%d ty_mb=%d apply_mb=%d if_mb=%d" [| box (BigStack.getGlobalMb()); box (BigStack.getMaxNest()); box (BigStack.getMb BigStack.rootContext BigStack.BigStackTerm); box (BigStack.getMb BigStack.rootContext BigStack.BigStackTy); box (BigStack.getMb BigStack.rootContext BigStack.BigStackApply); box (BigStack.getMb BigStack.rootContext BigStack.BigStackIfEmergency) |])
        with _ -> ()
        // Join-point cache equality is semantic. Object address and runtime object hash
        // are forbidden as authority; the hash is only a bucket hint and full structural
        // equality decides every collision.
        let jp_type_key_comparer =
            { new System.Collections.Generic.IEqualityComparer<ConsedNode<Ty []>> with
                member _.Equals(a,b) = LanguagePrimitives.GenericEquality a b
                member _.GetHashCode(a) = LanguagePrimitives.GenericHash a
            }
        let jp_type_body_comparer : System.Collections.Generic.IEqualityComparer<TPrepass> =
            HashIdentity.Structural
        let jp_type_inflight = System.Threading.AsyncLocal<System.Collections.Generic.HashSet<ConsedNode<Ty []>>>()
        let mk_jp_type_inflight () = System.Collections.Generic.HashSet<ConsedNode<Ty []>>(jp_type_key_comparer)
        let get_async_local (slot : System.Threading.AsyncLocal<'T>) (mk : unit -> 'T) : 'T =
            let v = slot.Value
            if obj.ReferenceEquals(v, null) then
                let v2 = mk()
                slot.Value <- v2
                v2
            else v
        let jp_body_key_comparer =
            { new System.Collections.Generic.IEqualityComparer<JpBodyOwnerIdentity> with
                member _.Equals(left,right) = JpBodyOwnerIdentity.equals left right
                member _.GetHashCode(identity) = JpBodyOwnerIdentity.hash identity
            }
    

        let join_point_method = System.Collections.Concurrent.ConcurrentDictionary<_,_>(jp_body_key_comparer)
        let jp_method_completed_cells =
            System.Collections.Concurrent.ConcurrentDictionary<JpMethodMemoCellIdentity,JpMethodMemoCompletedEntry>()
        let jp_method_pending_cells =
            System.Collections.Concurrent.ConcurrentDictionary<JpMethodMemoCellIdentity,JpMethodMemoPendingEntry>()
        let jp_method_declared_interfaces =
            System.Collections.Concurrent.ConcurrentDictionary<JpMethodMemoCellIdentity,JpMethodDeclaredInterface>()
        let jp_closure_completed_cells =
            System.Collections.Concurrent.ConcurrentDictionary<JpClosureMemoCellIdentity,JpClosureMemoCompletedEntry>()
        let jp_closure_pending_cells =
            System.Collections.Concurrent.ConcurrentDictionary<JpClosureMemoCellIdentity,JpClosureMemoPendingEntry>()
        let join_point_closure = System.Collections.Concurrent.ConcurrentDictionary<_,_>(jp_body_key_comparer)
        let join_point_type = System.Collections.Concurrent.ConcurrentDictionary<_,_>(jp_type_body_comparer)
        /// Inline recompute for each owned JP body cell, keyed by the cell (its IVar object). A cell still pending once
        /// the JP graph is quiescent has no producer left (its work unit was retired, e.g. as a control-only replay
        /// sentinel); peval's root recomputes exactly those cells in place (FRONTIER.md fix 50).
        let jp_orphan_recompute = System.Collections.Concurrent.ConcurrentDictionary<obj, unit -> unit>(HashIdentity.Reference)
        let backend_strings = StripedHashConsTable(32)  // MIGRATION: striped for parallel access
        let backend_strings_lock = obj()
        let backend_switch_validate_all = ref false  // par: validate only current backend branch by default
        let backend_switch_lock = obj()
        // JP: Track JP dict clear callbacks - multiple subsystems (peval, compiler) may register.
        let jp_dict_clear_lock = obj()
        let mutable jp_dict_clear_callbacks : (unit -> unit) list = []
        let register_jp_dict_clear_callback (f: unit -> unit) =
            lock jp_dict_clear_lock (fun () ->
                jp_dict_clear_callbacks <- f :: jp_dict_clear_callbacks
            )
        let run_jp_dict_clear_callbacks (reasonId: CacheGeneration.GenerationChangeReasonId) =
            let cbs =
                lock jp_dict_clear_lock (fun () -> jp_dict_clear_callbacks |> List.rev)
            for f in cbs do
                try f () with _ -> ()
            let reasonText = CacheGeneration.GenerationChangeReasonIdOps.text reasonId
            try DiagSidecar.emit (sprintf "JP: cache invalidation reason=%s jp_clear_callbacks=%d" reasonText cbs.Length) with _ -> ()
    

        // Hopac: parallel join point workers (peval)
    

        let capture_edi (e: exn) =
            System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture e
    

        // Global join-point exception queue (fast path) + exact producer-failure registry.
        let jp_exns : System.Collections.Concurrent.ConcurrentQueue<System.Runtime.ExceptionServices.ExceptionDispatchInfo> =
            System.Collections.Concurrent.ConcurrentQueue()

        // A dependent promise observes the exact producer failure even when another
        // waiter already dequeued the process-wide fast-path exception.
        let jp_work_exns : System.Collections.Concurrent.ConcurrentDictionary<int64,System.Runtime.ExceptionServices.ExceptionDispatchInfo> =
            System.Collections.Concurrent.ConcurrentDictionary()

        let jp_observers =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest,JpObserverRegistration>()

        let jpObserverRegister
            (generation:int64)
            (computationIdentity:JpComputationIdentity)
            (verificationRef:CompilerIdentityKernel.ContentDigest)
            (cancel:JpWorkCancellationRequest -> CompilerKernelV2.PortableEffect<unit>)
            : JpObserverRegistration =
            let observerRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-observer-registration"
                    (string generation
                     + "|" + jpComputationIdentityKindText computationIdentity
                     + "|" + jpComputationIdentityText computationIdentity
                     + "|" + CompilerIdentityKernel.ContentDigest.text verificationRef)
            let registration : JpObserverRegistration = {
                observerRef = observerRef
                verificationRef = verificationRef
                generation = generation
                computationIdentity = computationIdentity
                cancel = cancel
                lifecycle = JpObserverRegistered
            }
            jp_observers.GetOrAdd(observerRef, registration)

        let jpObserverAdvance (registration:JpObserverRegistration) (lifecycle:JpObserverLifecycle) =
            registration.lifecycle <- lifecycle
            jp_observers.[registration.observerRef] <- registration

        let jpObserverDrain (policy:JpObserverDrainPolicy) (reason:JpObserverDrainReasonId) : JpObserverDrainReceipt =
            let snapshot = jp_observers.ToArray() |> Array.map (fun entry -> entry.Value)
            let reasonText = jpObserverDrainReasonText reason
            let operationalReason = jpObserverDrainOperationalReason reason
            let cancellationRequest =
                match policy with
                | JpObserverDrainBeforeGenerationRetirement -> JpGenerationScopeCancellation operationalReason
                | JpObserverDrainBeforeTerminalFinalRow
                | JpObserverDrainBeforeHostReturn -> JpHostRequestedCancellation operationalReason
            let mutable cancellationRequested = 0
            let mutable terminal = 0
            let mutable terminalObserverRefs : CompilerIdentityKernel.ContentDigest list = []
            let mutable undecidedObserverRefs : CompilerIdentityKernel.ContentDigest list = []
            snapshot
            |> Array.iter (fun registration ->
                match registration.lifecycle with
                | JpObserverCompleted receiptRef
                | JpObserverCancelled receiptRef ->
                    terminal <- terminal + 1
                    terminalObserverRefs <- receiptRef :: terminalObserverRefs
                | JpObserverCancellationRequested _ ->
                    cancellationRequested <- cancellationRequested + 1
                    undecidedObserverRefs <- registration.observerRef :: undecidedObserverRefs
                | JpObserverRegistered
                | JpObserverRunning ->
                    let cancellationRef =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-observer-cancellation-request"
                            (CompilerIdentityKernel.ContentDigest.text registration.observerRef
                             + "|policy=" + jpObserverDrainPolicyText policy
                             + "|reason=" + reasonText)
                    registration.lifecycle <- JpObserverCancellationRequested cancellationRef
