                        Some previousChanged
                    else None)
            match changed with
            | Some signal -> startHopacJob (Hopac.IVar.fill signal ())
            | None -> ()

        let rec jpSpawnAdmissionAwaitZero () : Job<int64> =
            job {
                let snapshot = jpSpawnAdmissionSnapshot ()
                if snapshot.activeCount = 0 then
                    return snapshot.epoch
                else
                    let! _ = Hopac.IVar.read snapshot.changed
                    return! jpSpawnAdmissionAwaitZero ()
            }

        let jp_quiescence_authority = JpQuiescenceOwnedByOperationalGraph
        let mutable jp_operational_work_snapshot_provider : unit -> Job<CompilerKernelV2.OperationalWorkGraph> =
            JpOperationalWorkGraphAuthority.snapshot
        let mutable jp_operational_work_await_quiescence_provider : unit -> Job<CompilerIdentityKernel.ContentDigest> =
            JpOperationalWorkGraphAuthority.awaitQuiescence

        // The provider is rebound to the peval-local work-domain actor as soon as
        // that actor is constructed.  The global graph adapter remains cold and
        // will be deleted in the portable-runtime pass.
        let jp_quiescence_state () : Hopac.Job<JpQuiescenceState> =
            job {
                let! graph = jp_operational_work_snapshot_provider ()
                let openCount = CompilerKernelV2.OperationalWorkGraph.openCount graph
                let suspendedCount = CompilerKernelV2.OperationalWorkGraph.suspendedCount graph
                let spawnSnapshot = jpSpawnAdmissionSnapshot ()
                if openCount = 0 && spawnSnapshot.activeCount = 0 then
                    return
                        JpQuiescenceClosed(
                            CompilerKernelV2.OperationalWorkGraph.getGraphRef graph,
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-quiescence-closed"
                                (CompilerIdentityKernel.ContentDigest.text (CompilerKernelV2.OperationalWorkGraph.getGraphRef graph)
                                 + "|spawn_epoch=" + string spawnSnapshot.epoch))
                else
                    return
                        JpQuiescenceOpen(
                            CompilerKernelV2.OperationalWorkGraph.getGraphRef graph,
                            openCount,
                            suspendedCount,
                            spawnSnapshot.activeCount)
            }

        let jp_pending_jobs () : Hopac.Job<int> =
            job {
                let! state = jp_quiescence_state ()
                match state with
                | JpQuiescenceOpen(_, openCount, _, spawnInFlight) -> return openCount + spawnInFlight
                | JpQuiescenceClosed _ -> return 0
            }
    

        // One scheduler authority owns three typed lanes. Semantic producers are
        // always dequeued before declared-body/observer work, and exact waiters
        // may donate priority to the producer they are waiting on without executing
        // arbitrary observer work inline.
        let jp_semantic_work_q : System.Collections.Concurrent.ConcurrentQueue<JpWorkItem> = System.Collections.Concurrent.ConcurrentQueue()
        let jp_declared_body_work_q : System.Collections.Concurrent.ConcurrentQueue<JpWorkItem> = System.Collections.Concurrent.ConcurrentQueue()
        let jp_observer_work_q : System.Collections.Concurrent.ConcurrentQueue<JpWorkItem> = System.Collections.Concurrent.ConcurrentQueue()
        let mutable jp_declared_body_lane_try_reserve : unit -> JpWorkerLaneAdmission option = fun () -> None
        let mutable jp_observer_lane_try_reserve : unit -> JpWorkerLaneAdmission option = fun () -> None
        let mutable jp_reserved_lane_release : JpWorkerLaneAdmission -> unit = fun _ -> ()
        let jp_exact_producer_donation_q : System.Collections.Concurrent.ConcurrentQueue<int64> = System.Collections.Concurrent.ConcurrentQueue()
        // Round : inline producer execution is forbidden. Donation changes
        // queue priority only; the logical waiter remains suspended and never
        // grows a nested host stack.
        let jp_inline_donation_depth_limit = 0
        let jp_specialization_queue_capacity = max 1024 (max 1 System.Environment.ProcessorCount * 1024)

        let jpSpecializationQueueDepth () =
            jp_semantic_work_q.Count + jp_declared_body_work_q.Count + jp_observer_work_q.Count

        let jpSpecializationSemanticQueueDepth () = jp_semantic_work_q.Count
        let jpSpecializationDeclaredBodyQueueDepth () = jp_declared_body_work_q.Count
        let jpSpecializationObserverQueueDepth () = jp_observer_work_q.Count

        let jpSpecializationQueueEnqueue (item:JpWorkItem) =
            let depth = (jpSpecializationQueueDepth ())
            if depth >= jp_specialization_queue_capacity then
                JpSpecializationQueueBackpressured(depth, jp_specialization_queue_capacity)
            else
                // Affine publication order: establish the resume-PC ownership lease before
                // making the item visible to another worker. Explicit snapshot retirement
                // can therefore never win the enqueue/retain race for a live successor.
                jpRetainWorkItemQueuedResumeRoot item
                let depthAfter =
                    match jpSchedulingLaneFor item.authorityRole item.workNode.intent with
                    | JpSemanticProducerLane ->
                        jp_semantic_work_q.Enqueue item
                        jpSpecializationQueueDepth ()
                    | JpDeclaredBodyVerificationLane ->
                        jp_declared_body_work_q.Enqueue item
                        jpSpecializationQueueDepth ()
                    | JpObserverVerificationLane ->
                        jp_observer_work_q.Enqueue item
                        jpSpecializationQueueDepth ()
                jpSignalSpecializationRunnablePotential ()
                JpSpecializationQueueAdmitted depthAfter

        let jpSpecializationQueueRequestDonation producerWorkId =
            if producerWorkId > 0L then
                jp_exact_producer_donation_q.Enqueue producerWorkId
                jpSignalSpecializationRunnablePotential ()
                true
            else false

        let jpWorkItemQueueSelectable (item:JpWorkItem) =
            // Typed-carrier proof gates normal execution.  Once terminal failure is irrevocable,
            // a queued item is selectable only so a worker can run the existing before-start
            // cancellation transaction and return its conserved semantic credit; its body still
            // cannot execute because executeWorkerItem checks the same terminal latch first.
            DiagJson.terminalFailureExitRequestedNow()
            || jpWorkItemTypedCarrierProofRunnable item

        let jpSpecializationQueueTryDequeueRunnableFrom (queue:System.Collections.Concurrent.ConcurrentQueue<JpWorkItem>) =
            let retained = ResizeArray<JpWorkItem>()
            let mutable selected : JpWorkItem option = None
            let mutable scanned = 0
            let scanLimit = queue.Count
            while selected.IsNone && scanned < scanLimit do
                let mutable candidate = Unchecked.defaultof<JpWorkItem>
                if queue.TryDequeue(&candidate) then
                    scanned <- scanned + 1
                    if jpWorkItemQueueSelectable candidate then selected <- Some candidate
                    else retained.Add candidate
                else
                    scanned <- scanLimit
            for candidate in retained do queue.Enqueue candidate
            selected

        let jpSpecializationQueueTryRemoveDonated producerWorkId =
            let scanQueue (queue:System.Collections.Concurrent.ConcurrentQueue<JpWorkItem>) =
                let retained = ResizeArray<JpWorkItem>()
                let mutable selected : JpWorkItem option = None
                let mutable keepScanning = true
                let scanLimit = queue.Count
                while keepScanning && retained.Count < scanLimit do
                    let mutable candidate = Unchecked.defaultof<JpWorkItem>
                    if queue.TryDequeue(&candidate) then
                        if candidate.commitOrdinal = producerWorkId && selected.IsNone && jpWorkItemQueueSelectable candidate then
                            selected <- Some candidate
                            keepScanning <- false
                        else
                            retained.Add candidate
                    else
                        keepScanning <- false
                for candidate in retained do
                    queue.Enqueue candidate
                selected
            match scanQueue jp_semantic_work_q with
            | Some item -> Some item
            | None ->
                match scanQueue jp_declared_body_work_q with
                | Some item -> Some item
                | None -> scanQueue jp_observer_work_q

        let jpSpecializationQueueRestore (item:JpWorkItem) =
            match jpSchedulingLaneFor item.authorityRole item.workNode.intent with
            | JpSemanticProducerLane -> jp_semantic_work_q.Enqueue item
            | JpDeclaredBodyVerificationLane -> jp_declared_body_work_q.Enqueue item
            | JpObserverVerificationLane -> jp_observer_work_q.Enqueue item
            // Restore transfers the same queue-owned resume root back to its lane;
            // no new owner is created because execution never started.
            jpSignalSpecializationRunnablePotential ()

        let jpSpecializationQueueTryRemoveAny () =
            let mutable donatedProducer = 0L
            let donated =
                if jp_exact_producer_donation_q.TryDequeue(&donatedProducer) then
                    jpSpecializationQueueTryRemoveDonated donatedProducer
                else None
            match donated with
            | Some item ->
                jpReleaseWorkItemQueuedResumeRoot item
                JpSpecializationQueueRemoved(item, (jpSpecializationQueueDepth ()))
            | None ->
                let mutable item = Unchecked.defaultof<JpWorkItem>
                if jp_semantic_work_q.TryDequeue(&item) then
                    jpReleaseWorkItemQueuedResumeRoot item
                    JpSpecializationQueueRemoved(item, (jpSpecializationQueueDepth ()))
                elif jp_declared_body_work_q.TryDequeue(&item) then
                    jpReleaseWorkItemQueuedResumeRoot item
                    JpSpecializationQueueRemoved(item, (jpSpecializationQueueDepth ()))
                elif jp_observer_work_q.TryDequeue(&item) then
                    jpReleaseWorkItemQueuedResumeRoot item
                    JpSpecializationQueueRemoved(item, (jpSpecializationQueueDepth ()))
                else JpSpecializationQueueEmpty

        let jpSpecializationQueueTryRemoveRunnable () =
            let reserveFor (item:JpWorkItem) =
                match jpSchedulingLaneFor item.authorityRole item.workNode.intent with
                | JpSemanticProducerLane -> Some JpWorkerSemanticLaneGranted
                | JpDeclaredBodyVerificationLane -> jp_declared_body_lane_try_reserve ()
                | JpObserverVerificationLane -> jp_observer_lane_try_reserve ()
            let removed item admission =
                JpSpecializationRunnableQueueRemoved(item, jpSpecializationQueueDepth (), admission)
            let emptyOrDeferred () =
                let physicalDepth = jpSpecializationQueueDepth ()
                if physicalDepth > 0 then JpSpecializationRunnableQueueDeferred physicalDepth
                else JpSpecializationRunnableQueueEmpty
            let mutable donatedProducer = 0L
            let donated =
                if jp_exact_producer_donation_q.TryDequeue(&donatedProducer) then
                    match jpSpecializationQueueTryRemoveDonated donatedProducer with
                    | Some item ->
                        match reserveFor item with
                        | Some admission -> Some(removed item admission)
                        | None ->
                            jpSpecializationQueueRestore item
                            jp_exact_producer_donation_q.Enqueue donatedProducer
                            None
                    | None -> None
                else None
            match donated with
            | Some selection -> selection
            | None ->
                match jpSpecializationQueueTryDequeueRunnableFrom jp_semantic_work_q with
                | Some item -> removed item JpWorkerSemanticLaneGranted
                | None ->
                    match jp_declared_body_lane_try_reserve () with
                    | Some admission ->
                        match jpSpecializationQueueTryDequeueRunnableFrom jp_declared_body_work_q with
                        | Some item -> removed item admission
                        | None ->
                            jp_reserved_lane_release admission
                            match jp_observer_lane_try_reserve () with
                            | Some observerAdmission ->
                                match jpSpecializationQueueTryDequeueRunnableFrom jp_observer_work_q with
                                | Some item -> removed item observerAdmission
                                | None ->
                                    jp_reserved_lane_release observerAdmission
                                    emptyOrDeferred ()
                            | None -> emptyOrDeferred ()
                    | None ->
                        match jp_observer_lane_try_reserve () with
                        | Some admission ->
                            match jpSpecializationQueueTryDequeueRunnableFrom jp_observer_work_q with
                            | Some item -> removed item admission
                            | None ->
                                jp_reserved_lane_release admission
                                emptyOrDeferred ()
                        | None -> emptyOrDeferred ()

        let jp_generation_scope_mailbox =
            CompilerKernelV2.CompilerRuntimeKernel.mailbox<JpGenerationScopeMessage>
                "jp-generation-scope"
                CompilerKernelV2.PortableControlLane
                0
                CompilerKernelV2.MailboxFailClosed

        let rec jp_generation_scope_loop live waiters =
            job {
                let! message =
                    CompilerKernelV2.CompilerRuntimeKernel.take
                        jp_generation_scope_mailbox
                match message with
                | JpGenerationScopeAdmit(generation, workUnitId) ->
                    let current = Map.tryFind generation live |> Option.defaultValue Set.empty
                    let nextLive = Map.add generation (Set.add workUnitId current) live
                    return! jp_generation_scope_loop nextLive waiters
                | JpGenerationScopeRetire(generation, workUnitId) ->
                    let current = Map.tryFind generation live |> Option.defaultValue Set.empty
                    let remaining = Set.remove workUnitId current
                    let nextLive =
                        if Set.isEmpty remaining then Map.remove generation live
                        else Map.add generation remaining live
                    match Map.tryFind generation waiters with
                    | Some pending when Set.isEmpty remaining ->
                        for reason, reply in pending do
                            let receipt =
                                CompilerIdentityKernel.ContentDigest.ofText
                                    "jp-generation-closed"
                                    (sprintf "%d|%s|live=0" generation (jpGenerationScopeCloseReasonText reason))
                            do!
                                CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                    reply
                                    receipt
                        return! jp_generation_scope_loop nextLive (Map.remove generation waiters)
                    | _ ->
                        return! jp_generation_scope_loop nextLive waiters
                | JpGenerationScopeClose(generation, reason, reply) ->
                    let current = Map.tryFind generation live |> Option.defaultValue Set.empty
                    if Set.isEmpty current then
                        let receipt =
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-generation-closed"
                                (sprintf "%d|%s|live=0" generation (jpGenerationScopeCloseReasonText reason))
                        do!
                            CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                reply
                                receipt
                        return! jp_generation_scope_loop live waiters
                    else
                        let pending = Map.tryFind generation waiters |> Option.defaultValue []
                        return! jp_generation_scope_loop live (Map.add generation ((reason,reply)::pending) waiters)
                | JpGenerationScopeSnapshot reply ->
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                            reply
                            live
                    return! jp_generation_scope_loop live waiters
            }

        let jpGenerationScopeStarted = lazy (startHopacJob (jp_generation_scope_loop Map.empty Map.empty))

        let ensureJpGenerationScopeStarted () =
            CompilerRuntimeActivation.requireInProcessEntered "jp_generation_scope"
            jpGenerationScopeStarted.Force()

        let jp_generation_scope_admit (item:JpWorkItem) : Job<unit> =
            ensureJpGenerationScopeStarted()
            job {
                let workUnitId = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                BigStack.JpGenerationLocalEvidenceAuthority.noteAdmitted item.generation workUnitId
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.send
                        jp_generation_scope_mailbox
                        (JpGenerationScopeAdmit(item.generation, workUnitId))
            }

        let jp_generation_scope_retire (item:JpWorkItem) : Job<unit> =
            ensureJpGenerationScopeStarted()
            job {
                let workUnitId = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                BigStack.JpGenerationLocalEvidenceAuthority.noteRetired item.generation workUnitId
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.send
                        jp_generation_scope_mailbox
                        (JpGenerationScopeRetire(item.generation, workUnitId))
            }

        let jp_generation_scope_close generation reason =
            ensureJpGenerationScopeStarted()
            job {
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<CompilerIdentityKernel.ContentDigest>
                        "jp-generation-scope-close"
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.send
                        jp_generation_scope_mailbox
                        (JpGenerationScopeClose(generation, reason, reply))
                return!
                    CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
            }

        let jp_operational_domain_mailbox =
            CompilerKernelV2.CompilerRuntimeKernel.mailbox<JpOperationalDomainMessage>
                "jp-operational-domain"
                CompilerKernelV2.PortableSemanticLane
                0
                CompilerKernelV2.MailboxFailClosed

        // The operational actor is the only writer. Terminal/QAP/HUD consumers
        // receive this immutable mirror and cannot mutate graph or semantic state.
        let jpOperationalAuthorityProjectionGate = obj()
        let mutable jpOperationalAuthorityProjection =
            CompilerKernelV2.OperationalAuthoritySnapshotOps.create
                CompilerKernelV2.OperationalWorkGraph.empty
                0
                0
                0L
                (CompilerIdentityKernel.ContentDigest.ofText "portable-runtime-authority" "unbound")

        let jpInstallOperationalAuthorityProjection operationalGraph =
            let authoritativeLedger = CompilerKernelV2.SemanticWorkLedgerAuthority.snapshot ()
            let admitted, receipts = CompilerKernelV2.SemanticWorkLedger.counts authoritativeLedger
            let runtimeAuthorityRef =
                CompilerKernelV2.PortableRuntimeOperationalAdapterAuthority.installFSharpHopac ()
                |> CompilerKernelV2.PortableRuntimeAdapterReceiptOps.receiptRef
            let snapshot =
                CompilerKernelV2.OperationalAuthoritySnapshotOps.create
                    operationalGraph
                    admitted
                    receipts
                    (DiagJson.terminalSemanticAuthorityCountNow())
                    runtimeAuthorityRef
            lock jpOperationalAuthorityProjectionGate (fun () ->
                jpOperationalAuthorityProjection <- snapshot)
            snapshot

        let jpReadOperationalAuthoritySnapshot () =
            lock jpOperationalAuthorityProjectionGate (fun () -> jpOperationalAuthorityProjection)

        do TerminalFlowOperationalGraphSnapshotBridge.install (fun () ->
            let snapshot = jpReadOperationalAuthoritySnapshot ()
            CompilerKernelV2.OperationalAuthoritySnapshotOps.graphRevision snapshot,
            int64 (CompilerKernelV2.OperationalAuthoritySnapshotOps.openCount snapshot),
            int64 (CompilerKernelV2.OperationalAuthoritySnapshotOps.suspendedCount snapshot),
            CompilerKernelV2.OperationalAuthoritySnapshotOps.graphRef snapshot)

        let jpApplySemanticMutation mutation =
            let semanticApplied =
                match mutation with
                | CompilerKernelV2.SemanticWorkNoMutation -> false
                | CompilerKernelV2.SemanticWorkAdmit _
                | CompilerKernelV2.SemanticWorkApply _ -> true
            CompilerKernelV2.SemanticWorkLedgerAuthority.transact mutation
            |> Result.map (fun authoritativeLedger -> authoritativeLedger, semanticApplied)


        let jpOperationalAuthoritySnapshotEmissionClassText = function
            | JpOperationalAuthoritySemanticMutation -> "semantic_mutation"
            | JpOperationalAuthorityProceduralChurn -> "procedural_churn"

        let jpOperationalOpenWorkSamplePolicy openCount =
            if openCount <= 16L then
                JpOperationalOpenWorkFullTail(max 0 (int openCount))
            else
                JpOperationalOpenWorkHeadSample 4

        let jpOperationalOpenWorkSampleLimit = function
            | JpOperationalOpenWorkFullTail limit
            | JpOperationalOpenWorkHeadSample limit -> limit

        let jpOperationalOpenWorkSamplePolicyText = function
            | JpOperationalOpenWorkFullTail limit -> sprintf "FullTail(limit=%d)" limit
            | JpOperationalOpenWorkHeadSample limit -> sprintf "HeadSample(limit=%d)" limit

        let jpOperationalTransactionReceipt
            (disposition:JpOperationalWorkTransactionDisposition)
            (graphEvent:CompilerKernelV2.OperationalWorkGraphEvent)
            (semanticApplied:bool)
            : JpOperationalWorkTransactionReceipt =
            let authoritativeLedger = CompilerKernelV2.SemanticWorkLedgerAuthority.snapshot ()
            let admitted, receipts = CompilerKernelV2.SemanticWorkLedger.counts authoritativeLedger
            let transactionRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-operational-work-transaction"
                    (jpOperationalWorkTransactionDispositionText disposition
                     + "|graph=" + CompilerIdentityKernel.ContentDigest.text (CompilerKernelV2.OperationalWorkGraph.eventGraphRef graphEvent)
                     + "|admitted=" + string admitted
                     + "|receipts=" + string receipts)
            { disposition = disposition
              graphEvent = graphEvent
              semanticMutationApplied = semanticApplied
              semanticAdmittedCount = admitted
              semanticReceiptCount = receipts
              transactionRef = transactionRef }

        let rec jp_operational_domain_loop cells operationalGraph quiescenceWaiters =
            job {
                let! message =
                    CompilerKernelV2.CompilerRuntimeKernel.take
                        jp_operational_domain_mailbox
                match message with
                | JpWorkCellMerge(identity, next, reply) ->
                    let merged =
                        match Map.tryFind identity cells with
                        | Some current -> CompilerKernelV2.ConfluentWorkCell.merge current next
                        | None -> next
                    let nextCells = Map.add identity merged cells
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                            reply
                            merged
                    return! jp_operational_domain_loop nextCells operationalGraph quiescenceWaiters

                | JpWorkCellReadAll reply ->
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                            reply
                            cells
                    return! jp_operational_domain_loop cells operationalGraph quiescenceWaiters

                | JpOperationalWorkTransact(transaction, reply) ->
                    let complete nextGraph receipt =
                        job {
                            let authoritySnapshot =
                                jpInstallOperationalAuthorityProjection nextGraph
                            let graphRevision =
                                CompilerKernelV2.OperationalAuthoritySnapshotOps.graphRevision authoritySnapshot
                            let graphRef =
                                CompilerKernelV2.OperationalAuthoritySnapshotOps.graphRef authoritySnapshot
                            let semanticEpoch =
                                CompilerKernelV2.OperationalAuthoritySnapshotOps.semanticEpoch authoritySnapshot
                            let runtimeAuthorityRef =
                                CompilerKernelV2.OperationalAuthoritySnapshotOps.runtimeAuthorityRef authoritySnapshot
                            let snapshotRef =
                                CompilerKernelV2.OperationalAuthoritySnapshotOps.snapshotRef authoritySnapshot
                            let openCount = CompilerKernelV2.OperationalAuthoritySnapshotOps.openCount authoritySnapshot
                            let suspendedCount = CompilerKernelV2.OperationalAuthoritySnapshotOps.suspendedCount authoritySnapshot
                            // Open-work diagnostic projection is intentionally deferred until the
                            // sparse policy has actually selected this snapshot for emission.
                            let emissionClass =
                                if receipt.semanticMutationApplied then JpOperationalAuthoritySemanticMutation
                                else JpOperationalAuthorityProceduralChurn
                            let sparseKey =
                                match emissionClass with
                                | JpOperationalAuthoritySemanticMutation ->
                                    "operational_authority_snapshot|semantic|" + CompilerIdentityKernel.ContentDigest.text snapshotRef
                                | JpOperationalAuthorityProceduralChurn ->
                                    // Runtime-authority revisions have their own typed lifecycle events.
                                    // Do not smuggle their content digest into this sparse key or every
                                    // procedural snapshot becomes a unique key and defeats conflation.
                                    FastRuntimeFormat.format "operational_authority_snapshot|procedural|open=%d|suspended=%d" [| box openCount; box suspendedCount |]
                            let _, emitAuthoritySnapshot =
                                DiagJson.sparseLogDecision sparseKey 256L
                            if emitAuthoritySnapshot then
                                // Residual tails are where ownership bugs become diagnosable. Once the
                                // operational graph is small, emit the complete typed tail instead of an
                                // arbitrary head-4 sample; large graphs stay bounded and sparse. Building
                                // these projections only after sparse admission avoids hot-path formatting
                                // allocations for snapshots that will never cross the diagnostic boundary.
                                let openWorkSamplePolicy = jpOperationalOpenWorkSamplePolicy openCount
                                let openWorkSampleLimit = jpOperationalOpenWorkSampleLimit openWorkSamplePolicy
                                let openIdentitySample =
                                    CompilerKernelV2.OperationalWorkGraph.openIdentityRefs openWorkSampleLimit nextGraph
                                    |> List.map CompilerIdentityKernel.ContentDigest.text
                                    |> String.concat "|"
                                let openWorkSample =
                                    CompilerKernelV2.OperationalWorkGraph.openWorkProjections openWorkSampleLimit nextGraph
                                    |> List.map (fun projection ->
                                        FastRuntimeFormat.format
                                            "identity=%s|work_unit=%s|site=%s|state=%s"
                                            [| box (projection |> CompilerKernelV2.OperationalOpenWorkProjectionOps.identityRef |> CompilerIdentityKernel.ContentDigest.text)
                                               box (projection |> CompilerKernelV2.OperationalOpenWorkProjectionOps.workUnitRef |> CompilerIdentityKernel.ContentDigest.text)
                                               box (projection |> CompilerKernelV2.OperationalOpenWorkProjectionOps.siteId |> CompilerIdentityKernel.WorkSiteIdOps.text)
                                               box (projection |> CompilerKernelV2.OperationalOpenWorkProjectionOps.state |> CompilerKernelV2.operationalWorkGraphNodeStateText) |])
                                    |> String.concat ";"
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"operational_authority_snapshot_committed\",\"graph_revision\":%d,\"graph_ref\":%s,\"semantic_epoch\":%d,\"open_count\":%d,\"suspended_count\":%d,\"open_identity_sample\":%s,\"open_work_sample\":%s,\"open_work_sample_policy_du\":%s,\"runtime_authority_ref\":%s,\"snapshot_ref\":%s,\"emission_class_du\":%s,\"semantic_mutation_applied\":%b,\"sparse_policy\":\"semantic_every_change_procedural_first3_power2_every256\",\"authority\":\"operational_graph_plus_semantic_ledger_plus_portable_runtime_contract\"}" [| box graphRevision; box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text graphRef)); box semanticEpoch; box openCount; box suspendedCount; box (DiagJson.esc openIdentitySample); box (DiagJson.esc openWorkSample); box (DiagJson.esc (jpOperationalOpenWorkSamplePolicyText openWorkSamplePolicy)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text runtimeAuthorityRef)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text snapshotRef)); box (DiagJson.esc (jpOperationalAuthoritySnapshotEmissionClassText emissionClass)); box receipt.semanticMutationApplied |])
                            do!
                                CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                    reply
                                    (Ok receipt)
                            if CompilerKernelV2.OperationalWorkGraph.openCount nextGraph = 0 then
                                let graphRef = CompilerKernelV2.OperationalWorkGraph.getGraphRef nextGraph
                                for waiter in quiescenceWaiters do
                                    do!
                                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                            waiter
                                            graphRef
                                return! jp_operational_domain_loop cells nextGraph []
                            else
                                return! jp_operational_domain_loop cells nextGraph quiescenceWaiters
                        }
                    try
                        match transaction with
                        | JpOperationalWorkAdmitTransaction(node, semanticMutation) ->
                            let identityRef = CompilerKernelV2.OperationalWorkGraph.nodeIdentityRef node
                            match CompilerKernelV2.OperationalWorkGraph.tryState identityRef operationalGraph with
                            | Some existingState ->
                                // Operational replay and semantic-credit replay are component-wise
                                // idempotent. A duplicate graph admission must still converge the
                                // semantic half of the transaction instead of preserving a ghost credit.
                                match jpApplySemanticMutation semanticMutation with
                                | Error conflict ->
                                    do!
                                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                            reply
                                            (Error(JpOperationalWorkSemanticConflict conflict))
                                    return! jp_operational_domain_loop cells operationalGraph quiescenceWaiters
                                | Ok(_, semanticApplied) ->
                                    let _, graphEvent =
                                        CompilerKernelV2.OperationalWorkGraph.apply
                                            (CompilerKernelV2.OperationalWorkAdmit node)
                                            operationalGraph
                                    let receipt =
                                        jpOperationalTransactionReceipt
                                            (JpOperationalWorkDuplicateAdmission existingState)
                                            graphEvent
                                            semanticApplied
                                    return! complete operationalGraph receipt
                            | None ->
                                match jpApplySemanticMutation semanticMutation with
                                | Error conflict ->
                                    do!
                                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                            reply
                                            (Error(JpOperationalWorkSemanticConflict conflict))
                                    return! jp_operational_domain_loop cells operationalGraph quiescenceWaiters
                                | Ok(_, semanticApplied) ->
                                    let nextGraph, graphEvent =
                                        CompilerKernelV2.OperationalWorkGraph.apply
                                            (CompilerKernelV2.OperationalWorkAdmit node)
                                            operationalGraph
                                    let receipt =
                                        jpOperationalTransactionReceipt
                                            JpOperationalWorkTransactionApplied
                                            graphEvent
                                            semanticApplied
                                    return! complete nextGraph receipt

                        | JpOperationalWorkTransitionTransaction(transition, semanticMutation) ->
                            let transitionRef = CompilerKernelV2.WorkTransitionOps.transitionRef transition
                            let expectedStateRef = CompilerKernelV2.WorkTransitionOps.fromStateRef transition
                            match CompilerKernelV2.OperationalWorkGraph.transitionAuthority transition operationalGraph with
                            | CompilerKernelV2.OperationalWorkTransitionAlreadyApplied ->
                                // Replaying an already-applied operational transition may be exactly
                                // how a delayed semantic receipt catches up. Preserve graph idempotence
                                // while still applying the semantic mutation idempotently.
                                match jpApplySemanticMutation semanticMutation with
                                | Error conflict ->
                                    do!
                                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                            reply
                                            (Error(JpOperationalWorkSemanticConflict conflict))
                                    return! jp_operational_domain_loop cells operationalGraph quiescenceWaiters
                                | Ok(_, semanticApplied) ->
                                    let _, graphEvent =
                                        CompilerKernelV2.OperationalWorkGraph.apply
                                            (CompilerKernelV2.OperationalWorkTransition transition)
                                            operationalGraph
                                    let receipt =
                                        jpOperationalTransactionReceipt
                                            JpOperationalWorkDuplicateTransition
                                            graphEvent
                                            semanticApplied
                                    return! complete operationalGraph receipt
                            | CompilerKernelV2.OperationalWorkTransitionStale(currentState,currentStateRef) ->
                                do!
                                    CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                        reply
                                        (Error(
                                            JpOperationalWorkStaleTransition(
                                                transitionRef,
                                                expectedStateRef,
                                                currentState,
                                                currentStateRef)))
                                return! jp_operational_domain_loop cells operationalGraph quiescenceWaiters
                            | CompilerKernelV2.OperationalWorkTransitionMissingNode ->
                                let violationRef =
                                    CompilerIdentityKernel.ContentDigest.ofText
                                        "jp-operational-work-transition-missing-node"
                                        (CompilerIdentityKernel.ContentDigest.text transitionRef)
                                do!
                                    CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                        reply
                                        (Error(
                                            JpOperationalWorkProtocolViolation(
                                                violationRef,
                                                "operational work transition references a missing node")))
                                return! jp_operational_domain_loop cells operationalGraph quiescenceWaiters
                            | CompilerKernelV2.OperationalWorkTransitionReady ->
                                match jpApplySemanticMutation semanticMutation with
                                | Error conflict ->
                                    do!
                                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                            reply
                                            (Error(JpOperationalWorkSemanticConflict conflict))
                                    return! jp_operational_domain_loop cells operationalGraph quiescenceWaiters
                                | Ok(_, semanticApplied) ->
                                    let nextGraph, graphEvent =
                                        CompilerKernelV2.OperationalWorkGraph.apply
                                            (CompilerKernelV2.OperationalWorkTransition transition)
                                            operationalGraph
                                    let receipt =
                                        jpOperationalTransactionReceipt
                                            JpOperationalWorkTransactionApplied
                                            graphEvent
                                            semanticApplied
                                    return! complete nextGraph receipt
                    with ex ->
                        let violationRef =
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-operational-work-transaction-protocol-violation"
                                (ex.GetType().FullName + "|" + ex.Message)
                        do!
                            CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                reply
                                (Error(JpOperationalWorkProtocolViolation(violationRef,ex.Message)))
                        return! jp_operational_domain_loop cells operationalGraph quiescenceWaiters

                | JpOperationalWorkSnapshot reply ->
                    do!
                        CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                            reply
                            operationalGraph
                    return! jp_operational_domain_loop cells operationalGraph quiescenceWaiters

                | JpOperationalWorkAwaitQuiescence reply ->
                    if CompilerKernelV2.OperationalWorkGraph.openCount operationalGraph = 0 then
                        do!
                            CompilerKernelV2.CompilerRuntimeKernel.fillOneShot
                                reply
                                (CompilerKernelV2.OperationalWorkGraph.getGraphRef operationalGraph)
                        return! jp_operational_domain_loop cells operationalGraph quiescenceWaiters
                    else
                        return! jp_operational_domain_loop cells operationalGraph (reply :: quiescenceWaiters)

            }

        let jpPortableRuntimeOperationalAdapterInstalled =
            lazy (
                let receipt =
                    CompilerKernelV2.PortableRuntimeOperationalAdapterAuthority.installFSharpHopac ()
                DiagJson.emit (
                    FastRuntimeFormat.format "{\"kind\":\"portable_runtime_operational_adapter_installed\",\"adapter_du\":\"FSharpHopac\",\"contract_ref\":%s,\"adapter_receipt_ref\":%s,\"effect_count\":%d,\"mailbox_count\":%d,\"one_shot_count\":%d,\"fiber_count\":%d,\"authority\":\"in_process_differential_contract_plus_operational_adapter_receipt\",\"next\":\"preserve_same_laws_in_rust_and_beam_adapters\"}" [| box (DiagJson.esc (
                            receipt
                            |> CompilerKernelV2.PortableRuntimeAdapterReceiptOps.contractRef
                            |> CompilerIdentityKernel.ContentDigest.text)); box (DiagJson.esc (
                            receipt
                            |> CompilerKernelV2.PortableRuntimeAdapterReceiptOps.receiptRef
                            |> CompilerIdentityKernel.ContentDigest.text)); box (CompilerKernelV2.PortableRuntimeAdapterReceiptOps.effectCount receipt); box (CompilerKernelV2.PortableRuntimeAdapterReceiptOps.mailboxCount receipt); box (CompilerKernelV2.PortableRuntimeAdapterReceiptOps.oneShotCount receipt); box (CompilerKernelV2.PortableRuntimeAdapterReceiptOps.fiberCount receipt) |])
                receipt)

        let jpOperationalDomainStarted =
            lazy (
                jpPortableRuntimeOperationalAdapterInstalled.Force() |> ignore
                BigStack.TerminalFlowOperationalAuthorityBridge.install jpReadOperationalAuthoritySnapshot
                startHopacJob (
                    jp_operational_domain_loop
                        Map.empty
                        CompilerKernelV2.OperationalWorkGraph.empty
                        []))

        let ensureJpOperationalDomainStarted () =
            CompilerRuntimeActivation.requireInProcessEntered "jp_operational_work_domain"
            jpOperationalDomainStarted.Force()

        let jp_merge_work_cell identity next : Job<unit> =
            ensureJpOperationalDomainStarted()
            job {
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<CompilerKernelV2.ConfluentWorkCell<JpWorkResult>>
                        "jp-work-cell-merge"
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.send
                        jp_operational_domain_mailbox
                        (JpWorkCellMerge(identity, next, reply))
                let! _ = CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
                return ()
            }

        let jp_operational_work_transact transaction : Job<Result<JpOperationalWorkTransactionReceipt,JpOperationalWorkTransactionRejection>> =
            ensureJpOperationalDomainStarted()
            job {
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<Result<JpOperationalWorkTransactionReceipt,JpOperationalWorkTransactionRejection>>
                        "jp-operational-work-transact"
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.send
                        jp_operational_domain_mailbox
                        (JpOperationalWorkTransact(transaction, reply))
                return!
                    CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
            }

        let jp_operational_work_transact_required context transaction : Job<JpOperationalWorkTransactionReceipt> =
            job {
                let! result = jp_operational_work_transact transaction
                match result with
                | Ok receipt -> return receipt
                | Error rejection ->
                    return raise (
                        PartEvalTypeError(
                            [],
                            context + ": " + jpOperationalWorkTransactionRejectionText rejection))
            }

        let jp_operational_work_snapshot () : Job<CompilerKernelV2.OperationalWorkGraph> =
            ensureJpOperationalDomainStarted()
            job {
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<CompilerKernelV2.OperationalWorkGraph>
                        "jp-operational-work-snapshot"
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.send
                        jp_operational_domain_mailbox
                        (JpOperationalWorkSnapshot reply)
                return!
                    CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
            }

        let jp_operational_work_await_quiescence () : Job<CompilerIdentityKernel.ContentDigest> =
            ensureJpOperationalDomainStarted()
            job {
                let reply =
                    CompilerKernelV2.CompilerRuntimeKernel.oneShot<CompilerIdentityKernel.ContentDigest>
                        "jp-operational-work-quiescence"
                do!
                    CompilerKernelV2.CompilerRuntimeKernel.send
                        jp_operational_domain_mailbox
                        (JpOperationalWorkAwaitQuiescence reply)
                return!
                    CompilerKernelV2.CompilerRuntimeKernel.readOneShot reply
            }


        do
            jp_operational_work_snapshot_provider <- jp_operational_work_snapshot
            jp_operational_work_await_quiescence_provider <- jp_operational_work_await_quiescence

        let jp_register_work_item (item:JpWorkItem) : Job<JpWorkAdmissionDecision> =
            job {
                if not (CompilerKernelV2.JoinPointSpecializationPlanView.isClosed item.specializationPlan)
                   || not (CompilerKernelV2.SpecializationInteractionReceiptView.closed item.specializationInteractionReceipt) then
                    return invalidOp "unproven join-point specialization reached semantic work admission"

                let queued =
                    match item.operational with
                    | JpWorkQueuedCursor queued -> queued
                    | JpWorkSuspendedCursor _ ->
                        invalidOp "suspended JP work attempted a second admission transaction"

                let semanticMutation =
                    if jpWorkAuthorityRoleOwnsSemanticLedger item.authorityRole then
                        jpOperationalSemanticAdmit item.workUnit item.cost
                    else
                        jpOperationalNoSemanticMutation
                let transaction =
                    JpOperationalWorkAdmitTransaction(
                        CompilerKernelV2.OperationalWorkGraph.nodeOfQueued queued,
                        semanticMutation)
                let! transactionResult = jp_operational_work_transact transaction
                match transactionResult with
                | Error(JpOperationalWorkSemanticConflict conflict) ->
                    return JpWorkAdmissionRejected conflict
                | Error rejection ->
                    return raise (PartEvalTypeError([], "operational admission rejected: " + jpOperationalWorkTransactionRejectionText rejection))
                | Ok receipt ->
                    match receipt.disposition with
                    | JpOperationalWorkDuplicateAdmission existingState ->
                        let _, shouldEmit =
                            DiagJson.sparseLogDecision
                                ("jp_work_unit_admission_duplicate|" + CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)
                                64L
                        if shouldEmit then
                            DiagJson.emitRecord {
                                kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitAdmissionDuplicateSuppressed
                                work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                                binding_id = CompilerKernelV2.StableBindingId.text (jpWorkItemDeclarationBindingId item)
                                generation = item.generation
                                site = item.site
                                existing_operational_state_du = CompilerKernelV2.operationalWorkGraphNodeStateText existingState
                                semantic_mutation_applied = receipt.semanticMutationApplied
                                authority = "single_operational_graph_semantic_transaction"
                            }
                        return JpWorkAdmissionDuplicateSuppressed existingState

                    | JpOperationalWorkDuplicateTransition ->
                        return raise (PartEvalTypeError([], "admission transaction returned a duplicate transition"))

                    | JpOperationalWorkTransactionApplied ->
                        JpSpecializationWorklistAuthority.register item.workNode |> ignore
                        let specializationProofAdmitted =
                            DiagJson.noteSpecializationInteractionReceipt item.specializationInteractionReceipt
                        do! jp_merge_work_cell (jpWorkItemDeclarationBindingId item) (CompilerKernelV2.WorkCellPending (jpWorkItemDeclarationBindingId item))
                        if jpWorkAuthorityRoleOwnsSemanticLedger item.authorityRole then
                            do! jp_generation_scope_admit item
                        let computationIdentity, instantiationId, memoProbe, authorityRole =
                            jpWorkComputationMetadataForItem
                                item
                                (item.specializationPlan
                                 |> CompilerKernelV2.JoinPointSpecializationPlanView.planRef
                                 |> CompilerIdentityKernel.ContentDigest.text
                                 |> CompilerKernelV2.InstantiationIdOps.create)
                        let eventKind =
                            match item.authorityRole with
                            | JpObserverVerification _ -> DiagJson.TypedDiagJpObserverVerificationAdmitted
                            | JpSemanticProducer
                            | JpCodegenBodyProducer _ -> DiagJson.TypedDiagJpWorkUnitAdmitted
                        DiagJson.emitRecord {
                            kind = DiagJson.typedDiagEventKindText eventKind
                            work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                            binding_id = CompilerKernelV2.StableBindingId.text (jpWorkItemDeclarationBindingId item)
                            owner_id = CompilerKernelV2.StableBindingId.text (jpWorkItemOwnerBindingId item)
                            generation = item.generation
                            site = item.site
                            shape = item.shape
                            computation_kind_du = jpComputationIdentityKindText computationIdentity
                            computation_key = jpComputationIdentityText computationIdentity
                            computation_instantiation_ref = CompilerKernelV2.InstantiationIdOps.text instantiationId
                            memo_probe_du = jpComputationMemoProbeText memoProbe
                            authority_role_du = jpWorkAuthorityRoleText authorityRole
                            semantic_completion_credit = jpWorkAuthorityRoleOwnsSemanticLedger authorityRole
                            operational_completion_required = jpWorkAuthorityRoleParticipatesInRequiredWorkRecovery authorityRole
                            specialization_proof_admitted = specializationProofAdmitted
                            semantic_cost = CompilerKernelV2.Measured.value item.cost
                            semantic_mutation_applied = receipt.semanticMutationApplied
                            semantic_ledger_admitted = receipt.semanticAdmittedCount
                            semantic_ledger_receipts = receipt.semanticReceiptCount
                            transaction_ref = CompilerIdentityKernel.ContentDigest.text receipt.transactionRef
                            authority = "single_operational_graph_semantic_transaction"
                        }
                        return JpWorkAdmissionGranted
            }

        // Method-instantiation authority is lexically available to both completion
        // writers and active timing.  One map owns the nominal method -> exact
        // specialization set relationship for the current evaluator generation.
        let jp_computation_instantiation_ids : System.Collections.Concurrent.ConcurrentDictionary<JpComputationIdentity,System.Collections.Concurrent.ConcurrentDictionary<CompilerKernelV2.InstantiationId,byte>> =
            System.Collections.Concurrent.ConcurrentDictionary<JpComputationIdentity,System.Collections.Concurrent.ConcurrentDictionary<CompilerKernelV2.InstantiationId,byte>>()

        let jpComputationInstantiationCount computationIdentity instantiationId =
            let mutable existing = Unchecked.defaultof<System.Collections.Concurrent.ConcurrentDictionary<CompilerKernelV2.InstantiationId,byte>>
            let bucket =
                if jp_computation_instantiation_ids.TryGetValue(computationIdentity, &existing) then existing
                else
                    let candidate = System.Collections.Concurrent.ConcurrentDictionary<CompilerKernelV2.InstantiationId,byte>()
                    jp_computation_instantiation_ids.TryAdd(computationIdentity, candidate) |> ignore
                    if jp_computation_instantiation_ids.TryGetValue(computationIdentity, &existing) then existing else candidate
            bucket.TryAdd(instantiationId, 0uy) |> ignore
            bucket.Count

        let jpComputationInstantiationCountSnapshot computationIdentity =
            let mutable existing = Unchecked.defaultof<System.Collections.Concurrent.ConcurrentDictionary<CompilerKernelV2.InstantiationId,byte>>
            if jp_computation_instantiation_ids.TryGetValue(computationIdentity, &existing) then existing.Count else 0

        // Active timing authority must be lexically available before work execution.
        // The method key is derived from the stable binding identity; the human site
        // remains diagnostic-only and cannot merge same-named declarations.
        let jp_active_job_timings : System.Collections.Concurrent.ConcurrentDictionary<int64,JpActiveWorkTiming> =
            System.Collections.Concurrent.ConcurrentDictionary<int64,JpActiveWorkTiming>()
        let jpActiveWorkSourceSiteSnapshot () =
            jp_active_job_timings
            |> Seq.map (fun entry -> entry.Value)
            |> Seq.sortBy (fun timing -> timing.startedAtMs)
            |> Seq.tryHead
            |> Option.map (fun timing -> jpComputationIdentitySourceId timing.computationIdentity)
        do DiagJson.installActiveWorkSourceSiteProvider jpActiveWorkSourceSiteSnapshot
        let jp_active_operation_profiles : System.Collections.Concurrent.ConcurrentDictionary<int64,JpActiveOperationProfile> =
            System.Collections.Concurrent.ConcurrentDictionary<int64,JpActiveOperationProfile>()
        let jpDeclaredBodyCheckpointCycleLiveness jobId =
            let mutable profile = Unchecked.defaultof<JpActiveOperationProfile>
            if jp_active_operation_profiles.TryGetValue(jobId, &profile) then
                lock profile.profileGate (fun () ->
                    profile.recentDeclaredCheckpointSamples
                    |> Seq.toArray
                    |> jpDeclaredBodyCheckpointCycleLivenessForSamples)
            else
                JpDeclaredBodyCheckpointCycleInsufficientEvidence 0
        let jp_active_work_items : System.Collections.Concurrent.ConcurrentDictionary<int64,JpWorkItem> =
            System.Collections.Concurrent.ConcurrentDictionary<int64,JpWorkItem>()
        let jp_execution_deadline_claims : System.Collections.Concurrent.ConcurrentDictionary<int64,byte> =
            System.Collections.Concurrent.ConcurrentDictionary<int64,byte>()
        // The watchdog may prove a typed declared-checkpoint cycle while an isolated
        // codegen-body attempt is still running. Store that proof until the same job
        // reaches a bounded evaluator safe point; the watchdog itself never mutates
        // the promise or steals the running owner.
        let jp_declared_checkpoint_cancellation_safe_point_handoffs =
            System.Collections.Concurrent.ConcurrentDictionary<int64,JpDeclaredCheckpointCancellationSafePointHandoffId>()
        let jpPublishDeclaredCheckpointCancellationSafePointHandoff jobId proof observedSteps =
            jp_declared_checkpoint_cancellation_safe_point_handoffs.[jobId] <-
                { proof = proof
                  observedSteps = max 0L observedSteps
                  publishedAtMs = max 0L (jp_progress_clock()) }
        let jpTryTakeDeclaredCheckpointCancellationSafePointHandoff jobId =
            let mutable handoff = Unchecked.defaultof<JpDeclaredCheckpointCancellationSafePointHandoffId>
            if jp_declared_checkpoint_cancellation_safe_point_handoffs.TryRemove(jobId, &handoff) then Some handoff
            else None
        let jpRetireDeclaredCheckpointCancellationSafePointHandoff jobId =
            let mutable ignored = Unchecked.defaultof<JpDeclaredCheckpointCancellationSafePointHandoffId>
            jp_declared_checkpoint_cancellation_safe_point_handoffs.TryRemove(jobId, &ignored) |> ignore
        let jp_cpu_baseline_rebound_emitted : System.Collections.Concurrent.ConcurrentDictionary<int64,byte> =
            System.Collections.Concurrent.ConcurrentDictionary<int64,byte>()

        let jp_declared_body_lifetime_states : System.Collections.Concurrent.ConcurrentDictionary<int64,JpDeclaredBodyLifetimeState> =
            System.Collections.Concurrent.ConcurrentDictionary<int64,JpDeclaredBodyLifetimeState>()

        let jpDeclaredBodyLifetimeSeed (item:JpWorkItem) nowMs previousOperationCount =
            match item.workNode.intent with
            | JpVerifyDeclaredMethodBody ->
                let candidate =
                    { lifetimeGate = obj()
                      startedAtMs = nowMs
                      lastObservedOperationCount = max 0L previousOperationCount
                      lastOperationProgressAtMs = nowMs
                      operationProgressDeferralCount = 0L
                      diagnosticBudgetExceeded = false }
                let state = jp_declared_body_lifetime_states.GetOrAdd(item.commitOrdinal, candidate)
                lock state.lifetimeGate (fun () ->
                    if previousOperationCount > state.lastObservedOperationCount then
                        state.lastObservedOperationCount <- previousOperationCount
                        state.lastOperationProgressAtMs <- nowMs
                    state.startedAtMs,
                    state.lastObservedOperationCount,
                    state.lastOperationProgressAtMs,
                    state.operationProgressDeferralCount,
                    state.diagnosticBudgetExceeded)
            | _ -> nowMs, 0L, nowMs, 0L, false

        let jpDeclaredBodyLifetimeCapture jobId (timing:JpActiveWorkTiming) =
            let mutable state = Unchecked.defaultof<JpDeclaredBodyLifetimeState>
            if jp_declared_body_lifetime_states.TryGetValue(jobId, &state) then
                lock timing.timingGate (fun () ->
                    lock state.lifetimeGate (fun () ->
                        state.lastObservedOperationCount <-
                            max state.lastObservedOperationCount timing.lastObservedOperationCount
                        state.lastOperationProgressAtMs <-
                            max state.lastOperationProgressAtMs timing.lastOperationProgressAtMs
                        state.operationProgressDeferralCount <-
                            max state.operationProgressDeferralCount timing.operationProgressDeferralCount
                        state.diagnosticBudgetExceeded <-
                            state.diagnosticBudgetExceeded || timing.executionDiagnosticBudgetExceeded))

        let jpDeclaredBodyLifetimeRetire jobId =
            let mutable removedLifetime = Unchecked.defaultof<JpDeclaredBodyLifetimeState>
            if jp_declared_body_lifetime_states.TryRemove(jobId, &removedLifetime) then
                jp_declared_body_finish_through_release jobId

        let jpDeclaredBodyLifetimeSnapshot jobId nowMs =
            let mutable state = Unchecked.defaultof<JpDeclaredBodyLifetimeState>
            if jp_declared_body_lifetime_states.TryGetValue(jobId, &state) then
                lock state.lifetimeGate (fun () ->
                    Some(
                        max 0L (nowMs - state.startedAtMs),
                        state.lastObservedOperationCount,
                        max 0L (nowMs - state.lastOperationProgressAtMs),
                        state.operationProgressDeferralCount))
            else None

        let jpAdvanceActiveWorkPublicationStage jobId stage =
            let mutable timing = Unchecked.defaultof<JpActiveWorkTiming>
            if jp_active_job_timings.TryGetValue(jobId, &timing) then
                lock timing.timingGate (fun () ->
                    if timing.publicationStage <> stage then
                        let nowMs = max 0L (jp_progress_clock())
                        timing.publicationStage <- stage
                        timing.publicationStageChangedAtMs <- nowMs
                        timing.publicationStageTransitions <- timing.publicationStageTransitions + 1L)

        let jpActiveWorkPublicationStageSnapshot jobId nowMs =
            let mutable timing = Unchecked.defaultof<JpActiveWorkTiming>
            if jp_active_job_timings.TryGetValue(jobId, &timing) then
                lock timing.timingGate (fun () ->
                    Some(
                        timing.publicationStage,
                        max 0L (nowMs - timing.publicationStageChangedAtMs),
                        timing.publicationStageTransitions))
            else None

        let jpSuspendActiveWorkTiming jobId =
            let mutable removedTiming = Unchecked.defaultof<JpActiveWorkTiming>
            let mutable removedItem = Unchecked.defaultof<JpWorkItem>
            let mutable removedCpuBaselineReceipt = 0uy
            let removedStageAuthority =
                if jp_active_job_timings.TryRemove(jobId, &removedTiming) then
                    jpDeclaredBodyLifetimeCapture jobId removedTiming
                    Some(removedTiming.computationIdentity, removedTiming.instantiationId)
                else
                    None
            jp_active_work_items.TryRemove(jobId, &removedItem) |> ignore
            jp_cpu_baseline_rebound_emitted.TryRemove(jobId, &removedCpuBaselineReceipt) |> ignore
            JpActiveWorkIdentityAuthority.retire jobId
            removedStageAuthority

        let jpRetireExecutionDeadlineClaim jobId =
            let mutable removedDeadlineClaim = 0uy
            jp_execution_deadline_claims.TryRemove(jobId, &removedDeadlineClaim) |> ignore

        let jpRemoveActiveWorkTiming jobId =
            match jpSuspendActiveWorkTiming jobId with
            | Some(computationIdentity, instantiationId) ->
                JpMethodBodyStageAuthority.retire computationIdentity instantiationId
            | None -> ()
            let mutable removedProfile = Unchecked.defaultof<JpActiveOperationProfile>
            let mutable removedDeclaredBodyCheckpoint = Unchecked.defaultof<JpDeclaredBodyCheckpoint>
            jp_active_operation_profiles.TryRemove(jobId, &removedProfile) |> ignore
            jp_declared_body_checkpoints.TryRemove(jobId, &removedDeclaredBodyCheckpoint) |> ignore
            jpRetireDeclaredCheckpointCancellationSafePointHandoff jobId
            // Hard-deadline ownership is scoped to the logical work lifetime, not
            // to one cooperative execution attempt.  A declared body may suspend
            // and resume many times after its age crosses the hard budget; keeping
            // the claim through suspension makes the advertised exact-once
            // deadline authority real.  Only final logical retirement releases it.
            jpRetireExecutionDeadlineClaim jobId
            jpDeclaredBodyLifetimeRetire jobId

        let jpYieldActiveWorkTiming (item:JpWorkItem) =
            match item.workNode.intent with
            | JpVerifyDeclaredMethodBody ->
                jpSuspendActiveWorkTiming item.commitOrdinal |> ignore
                JpYieldTimingDeclaredBodySuspended
            | _ ->
                jpRemoveActiveWorkTiming item.commitOrdinal
                JpYieldTimingGeneralWorkRemoved

        let jpWorkExecutionBudgetPolicyFor (item:JpWorkItem) =
            match item.workNode.intent, item.workNode.runtimeEffect with
            | JpVerifyDeclaredMethodBody, JpRuntimeEffectRequired witness ->
                // Structurally declared runtime effects share one compiler policy.
                // Program/library symbols never select budgets or liveness authority.
                JpStableRuntimeEffectDeclaredBodyBudget witness.effectKind, 90000L, 240000L
            | _ ->
                let snapshot = BigStackDurationBasisAuthority.readHottestNonBlocking ()
                let p99Ms = max 0L (BigStackDurationBasisAuthority.observedP99Ms snapshot)
                let samples = BigStackDurationBasisAuthority.sampleCount snapshot
                let diagnosticBudgetMs =
                    // Cold-start diagnostics use the same conservative floor as the
                    // measured policy; diagnostics remain observer-only and never own exit.
                    if samples < 32L then 45000L
                    else max 45000L (min 90000L p99Ms)
                let hardBudgetMs =
                    if samples < 32L then 180000L
                    else max 90000L (min 180000L (p99Ms * 2L))
                JpMeasuredGeneralWorkBudget(samples, p99Ms), diagnosticBudgetMs, hardBudgetMs

        let jpInstallActiveWorkTiming (item:JpWorkItem) =
            let workUnitRef =
                CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                |> CompilerIdentityKernel.ContentDigest.requireParsed "workUnitRef"
            let fallbackInstantiationId =
                item.specializationPlan
                |> CompilerKernelV2.JoinPointSpecializationPlanView.planRef
                |> CompilerIdentityKernel.ContentDigest.text
                |> CompilerKernelV2.InstantiationIdOps.create
            let computationIdentity, instantiationId, memoProbe, authorityRole =
                jpWorkComputationMetadataForItem item fallbackInstantiationId
            let executionBudgetPolicy, executionDiagnosticBudgetMs, executionBudgetMs =
                jpWorkExecutionBudgetPolicyFor item
            let admissionStartedAtMs = max 0L (jp_progress_clock())
            let cpuStarted = jpCpuTimeSampleNow()
            let cpuProgressState =
                match cpuStarted with
                | JpCpuTimeExclusive _ ->
                    JpCpuProgressObserved(0L, admissionStartedAtMs)
                | JpCpuTimeUnavailable _ ->
                    JpCpuProgressUnavailable
            let previousOperationCount =
                match item.workNode.intent with
                | JpVerifyDeclaredMethodBody ->
                    let mutable profile = Unchecked.defaultof<JpActiveOperationProfile>
                    if jp_active_operation_profiles.TryGetValue(item.commitOrdinal, &profile) then
                        lock profile.profileGate (fun () -> max 0L profile.operationCount)
                    else 0L
                | _ -> 0L
            let lifetimeStartedAtMs, lifetimeObservedOperationCount, lifetimeLastOperationProgressAtMs, lifetimeDeferralCount, lifetimeDiagnosticBudgetExceeded =
                jpDeclaredBodyLifetimeSeed item admissionStartedAtMs previousOperationCount
            let lifetimeAgeAtAdmissionMs = max 0L (admissionStartedAtMs - lifetimeStartedAtMs)
            let remainingExecutionBudgetMs = max 1L (executionBudgetMs - lifetimeAgeAtAdmissionMs)
            let deadlineTimer =
                CompilerKernelV2.CompilerRuntimeKernel.timer
                    ("jp-work-deadline:" + CompilerIdentityKernel.ContentDigest.text workUnitRef)
                    (int remainingExecutionBudgetMs)
            let timing =
                { timingGate = obj()
                  workUnitRef = workUnitRef
                  bindingId = jpWorkItemDeclarationBindingId item
                  startedAtMs = lifetimeStartedAtMs
                  cpuStarted = cpuStarted
                  cpuProgressState = cpuProgressState
                  computationIdentity = computationIdentity
                  instantiationId = instantiationId
                  instantiationCount = jpComputationInstantiationCount computationIdentity instantiationId
                  memoProbe = memoProbe
                  authorityRole = authorityRole
                  executionBudgetPolicy = executionBudgetPolicy
                  executionDiagnosticBudgetMs = executionDiagnosticBudgetMs
                  executionBudgetMs = executionBudgetMs
                  deadlineTimer = deadlineTimer
                  executionDiagnosticBudgetExceeded = lifetimeDiagnosticBudgetExceeded
                  executionBudgetExceeded = false
                  lastObservedOperationCount = lifetimeObservedOperationCount
                  lastOperationProgressAtMs = lifetimeLastOperationProgressAtMs
                  operationProgressDeferralCount = lifetimeDeferralCount
                  publicationStage = JpWorkPublicationExecuting
                  publicationStageChangedAtMs = admissionStartedAtMs
                  publicationStageTransitions = 1L
                  blockedOnChildCompletedMs = 0L
                  activeChildWait = JpActiveChildWaitIdle
                  childWaitCount = 0 }
            jp_active_job_timings.[item.commitOrdinal] <- timing
            jp_active_work_items.[item.commitOrdinal] <- item
            JpActiveWorkIdentityAuthority.register
                item.commitOrdinal
                workUnitRef
                (jpWorkItemDeclarationBindingId item)
                (jpComputationIdentitySourceId computationIdentity)
                timing.startedAtMs

        let jpActiveWorkTimingSnapshot jobId nowMs =
            let mutable timing = Unchecked.defaultof<JpActiveWorkTiming>
            if jp_active_job_timings.TryGetValue(jobId, &timing) then
                lock timing.timingGate (fun () ->
                    let activeWaitMs, activeChildWait =
                        match timing.activeChildWait with
                        | JpActiveChildWaitRunning(startedAtMs, childWait) ->
                            max 0L (nowMs - startedAtMs), JpActiveChildWaitRunning(startedAtMs, childWait)
                        | JpActiveChildWaitIdle -> 0L, JpActiveChildWaitIdle
                    let blockedOnChildMs = timing.blockedOnChildCompletedMs + activeWaitMs
                    let cpuExclusiveMs, cpuAuthorityDu =
                        jpCpuTimeDelta timing.cpuStarted (jpCpuTimeSampleFor timing.cpuStarted)
                    Some(
                        CompilerIdentityKernel.ContentDigest.text timing.workUnitRef,
                        CompilerKernelV2.StableBindingId.text timing.bindingId,
                        timing.startedAtMs,
                        jpComputationIdentityKindText timing.computationIdentity,
                        jpComputationIdentityText timing.computationIdentity,
                        jpComputationIdentitySource timing.computationIdentity,
                        CompilerKernelV2.InstantiationIdOps.text timing.instantiationId,
                        max timing.instantiationCount (jpComputationInstantiationCountSnapshot timing.computationIdentity),
                        timing.memoProbe,
                        timing.authorityRole,
                        cpuExclusiveMs,
                        cpuAuthorityDu,
                        blockedOnChildMs,
                        timing.childWaitCount,
                        activeChildWait))
            else None

        let jpActiveWorkTimingNowMs () =
            max 0L (jp_progress_clock())

        let jpActiveWorkTimingPartition jobId inclusiveMs =
            jpAdvanceActiveWorkPublicationStage jobId JpWorkPublicationTimingPartition
            match jpActiveWorkTimingSnapshot jobId (jpActiveWorkTimingNowMs()) with
            | Some(workUnitId, _, _, _, _, _, _, _, _, _, cpuExclusive, cpuAuthority, blockedOnChildMs, childWaitCount, _) ->
                let boundedInclusiveMs = max 0L inclusiveMs
                let boundedBlockedMs = min boundedInclusiveMs (max 0L blockedOnChildMs)
                let normalizedCpuExclusive, normalizedCpuAuthority, cpuNormalization =
                    match cpuExclusive, cpuAuthority with
                    | Some cpu, CompilerKernelV2.CpuTimeExclusiveWorker _ ->
                        let observedCpuMs = max 0L (CompilerKernelV2.Measured.value cpu)
                        if observedCpuMs <= boundedInclusiveMs then
                            Some cpu, cpuAuthority, JpCpuWallWithinInclusive
                        elif observedCpuMs <= boundedInclusiveMs + jpCpuWallQuantizationToleranceMs then
                            Some(
                                CompilerKernelV2.Measured.create<CompilerKernelV2.CpuTimeUnit>
                                    "cpuExclusive"
                                    boundedInclusiveMs),
                            cpuAuthority,
                            JpCpuWallClampedToInclusive(
                                observedCpuMs,
                                boundedInclusiveMs,
                                jpCpuWallQuantizationToleranceMs)
                        else
                            let reason =
                                CompilerKernelV2.OperationalReasonIdOps.create (
                                    FastRuntimeFormat.format "cpu_exclusive_exceeds_wall_after_tolerance|observed_ms=%d|wall_ms=%d|tolerance_ms=%d" [| box observedCpuMs; box boundedInclusiveMs; box jpCpuWallQuantizationToleranceMs |])
                            None,
                            CompilerKernelV2.CpuTimeUnavailable reason,
                            JpCpuWallRejectedBeyondTolerance(
                                observedCpuMs,
                                boundedInclusiveMs,
                                jpCpuWallQuantizationToleranceMs)
                    | None, _ ->
                        None, cpuAuthority, JpCpuWallNotMeasured
                    | Some cpu, CompilerKernelV2.CpuTimeUnavailable _ ->
                        let observedCpuMs = max 0L (CompilerKernelV2.Measured.value cpu)
                        None,
                        cpuAuthority,
                        JpCpuWallRejectedBeyondTolerance(observedCpuMs, boundedInclusiveMs, 0L)
                let rawCpuMsPresent = Option.isSome cpuExclusive
                let rawCpuMs =
                    cpuExclusive
                    |> Option.map CompilerKernelV2.Measured.value
                    |> Option.defaultValue 0L
                let normalizedCpuMsPresent = Option.isSome normalizedCpuExclusive
                let normalizedCpuMs =
                    normalizedCpuExclusive
                    |> Option.map CompilerKernelV2.Measured.value
                    |> Option.defaultValue 0L
                match cpuNormalization with
                | JpCpuWallNotMeasured -> ()
                | normalization ->
                    let occurrenceCount, shouldEmit =
                        DiagJson.sparseLogDecision
                            ("jp_work_timing_cpu_normalized|" + workUnitId + "|" + jpCpuWallNormalizationText normalization)
                            64L
                    if shouldEmit then
                        DiagJson.emitRecord {
                            kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkTimingCpuNormalized
                            job_id = jobId
                            work_unit_id = workUnitId
                            normalization_du = jpCpuWallNormalizationText normalization
                            raw_cpu_ms_present = rawCpuMsPresent
                            raw_cpu_ms = rawCpuMs
                            normalized_cpu_ms_present = normalizedCpuMsPresent
                            normalized_cpu_ms = normalizedCpuMs
                            wall_inclusive_ms = boundedInclusiveMs
                            blocked_child_ms = boundedBlockedMs
                            occurrence_count = occurrenceCount
                            authority = "typed_cpu_wall_partition_observation"
                            next = "preserve_timing_receipt_and_surface_cpu_exclusive_authority"
                        }
                let wallInclusive =
                    CompilerKernelV2.Measured.create<CompilerKernelV2.WallTimeUnit>
                        "wallInclusive"
                        boundedInclusiveMs
                let wallExclusive =
                    CompilerKernelV2.Measured.create<CompilerKernelV2.WallTimeUnit>
                        "wallExclusive"
                        (boundedInclusiveMs - boundedBlockedMs)
                let blockedOnChild =
                    CompilerKernelV2.Measured.create<CompilerKernelV2.BlockedOnChildTimeUnit>
                        "blockedOnChild"
                        boundedBlockedMs
                let queueDelay = CompilerKernelV2.Measured.zero<CompilerKernelV2.QueueDelayUnit>
                let makePartition receipt normalization =
                    Some {
                        wallExclusive = wallExclusive
                        receipt = receipt
                        childWaitCount = childWaitCount
                        cpuNormalization = normalization
                    }
                match
                    CompilerKernelV2.WorkTimingReceiptOps.tryCreate
                        normalizedCpuExclusive
                        normalizedCpuAuthority
                        wallInclusive
                        queueDelay
                        blockedOnChild
                with
                | Ok receipt ->
                    makePartition receipt cpuNormalization
                | Error rejection ->
                    let rejectionText =
                        CompilerKernelV2.workTimingReceiptCreationErrorText rejection
                    let fallbackAuthority =
                        CompilerKernelV2.CpuTimeUnavailable(
                            CompilerKernelV2.OperationalReasonIdOps.create
                                ("work_timing_receipt_rejected|" + rejectionText))
                    let occurrenceCount, shouldEmit =
                        DiagJson.sparseLogDecision
                            ("jp_work_timing_receipt_rejected|" + rejectionText)
                            64L
                    if shouldEmit then
                        DiagJson.emitRecord {
                            kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkTimingReceiptRejected
                            job_id = jobId
                            work_unit_id = workUnitId
                            rejection_du = rejectionText
                            cpu_measurement_dropped = true
                            worker_continues = true
                            occurrence_count = occurrenceCount
                            authority = "typed_nonthrowing_timing_receipt_boundary"
                            next = "commit_with_cpu_unavailable_receipt"
                        }
                    match
                        CompilerKernelV2.WorkTimingReceiptOps.tryCreate
                            None
                            fallbackAuthority
                            wallInclusive
                            queueDelay
                            blockedOnChild
                    with
                    | Ok fallbackReceipt ->
                        makePartition fallbackReceipt cpuNormalization
                    | Error fallbackRejection ->
                        let fallbackText =
                            CompilerKernelV2.workTimingReceiptCreationErrorText fallbackRejection
                        DiagJson.emitRecord {
                            kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkTimingReceiptFallbackRejected
                            job_id = jobId
                            work_unit_id = workUnitId
                            rejection_du = fallbackText
                            terminal_authority = false
                            authority = "typed_nonthrowing_timing_receipt_boundary"
                            next = "publish_without_optional_timing_partition"
                        }
                        None
            | None -> None

        let jpPortableEffectBoundaryDispositionForException (error:exn) =
            match EvalReplayValueStore.tryEvaluatorPatternMissBreakthroughEscape error with
            | Some _ ->
                JpPortableEffectPatternMissControlPreserved
            | None ->
                match error with
                | JpDeclaredEvaluatorSliceYield _ ->
                    JpPortableEffectDeclaredSliceYieldControlPreserved
                | PartEvalTypeError _ ->
                    JpPortableEffectPartEvalTypeFailurePreserved
                | _ ->
                    JpPortableEffectRuntimeFailurePreserved

        let jpCodegenPatternMissUnchangedDependencyRepeatLimit = 8L
        let jpCodegenPatternMissMinimumMeasuredRepeatCount = 2L
        let jpCodegenPatternMissRecurrentPrefixMinimumStableAgeMs = 60000L

        let jpCodegenPatternMissStasisDecisionText = function
            | JpCodegenPatternMissDependencyProgressExpected(repeatCount, stableAgeMs, basis) ->
                FastRuntimeFormat.format
                    "ProgressExpected(repeat=%d|stable_age_ms=%d|basis=%s)"
                    [| box repeatCount; box stableAgeMs; box (JpCodegenPatternMissStasisBasisId.text basis) |]
            | JpCodegenPatternMissDependencyStasisEscalated(repeatCount, repeatLimit, stableAgeMs, stableAgeFloorMs, basis) ->
                FastRuntimeFormat.format
                    "StasisEscalated(repeat=%d|repeat_limit=%d|stable_age_ms=%d|stable_age_floor_ms=%d|basis=%s)"
                    [| box repeatCount; box repeatLimit; box stableAgeMs; box stableAgeFloorMs; box (JpCodegenPatternMissStasisBasisId.text basis) |]

        let jpRequiredBodyProgressAuthorityFor currentWorkJobId materialSilenceAgeMs materialSilenceFloorMs durationBasisRef =
            if currentWorkJobId <= 0L then JpRequiredBodyNoFreshCheckpoint
            else
                let mutable checkpoint = Unchecked.defaultof<JpDeclaredBodyCheckpoint>
                if jp_declared_body_checkpoints.TryGetValue(currentWorkJobId, &checkpoint) then
                    let checkpointAgeMs = max 0L (jp_progress_clock() - checkpoint.capturedAtMs)
                    if checkpoint.operationCount > 0L
                       && checkpointAgeMs <= jp_declared_body_checkpoint_max_progress_age_ms then
                        if materialSilenceAgeMs >= materialSilenceFloorMs then
                            JpRequiredBodyProceduralCheckpointOutrankedByMaterialSilence(
                                checkpoint.checkpointOrdinal,
                                checkpoint.operationCount,
                                checkpointAgeMs,
                                materialSilenceAgeMs,
                                materialSilenceFloorMs,
                                checkpoint.checkpointRef,
                                durationBasisRef)
                        else
                            JpRequiredBodyProceduralCheckpointWithinMaterialWindow(
                                checkpoint.checkpointOrdinal,
                                checkpoint.operationCount,
                                checkpointAgeMs,
                                materialSilenceAgeMs,
                                materialSilenceFloorMs,
                                checkpoint.checkpointRef,
                                durationBasisRef)
                    else JpRequiredBodyNoFreshCheckpoint
                else JpRequiredBodyNoFreshCheckpoint

        let jpCodegenPatternMissStasisDecisionForCheckpointCycleLiveness currentWorkJobId repeatCount stableAgeMs checkpointCycleLiveness =
            let durationBasis = BigStackDurationBasisAuthority.readHottestNonBlocking ()
            let observedP99Ms = max 1L (BigStackDurationBasisAuthority.observedP99Ms durationBasis)
            let durationSampleCount = max 1L (BigStackDurationBasisAuthority.sampleCount durationBasis)
            let measuredBasis =
                JpCodegenPatternMissMeasuredDurationBasis(
                    observedP99Ms,
                    durationSampleCount,
                    BigStackDurationBasisAuthority.basisRef durationBasis)

            let checkpointCycleCandidateStableAgeFloorMs =
                max
                    jpCodegenPatternMissRecurrentPrefixMinimumStableAgeMs
                    (max observedP99Ms (jp_declared_body_checkpoint_max_progress_age_ms * 4L))
            let requiredBodyProgressAuthority =
                jpRequiredBodyProgressAuthorityFor
                    currentWorkJobId
                    stableAgeMs
                    checkpointCycleCandidateStableAgeFloorMs
                    (BigStackDurationBasisAuthority.basisRef durationBasis)
            match checkpointCycleLiveness, requiredBodyProgressAuthority with
            | JpDeclaredBodyCheckpointCycleStationary(repetitions, sampleCount, stateRef), _
                when repeatCount >= jpCodegenPatternMissUnchangedDependencyRepeatLimit
                     && stableAgeMs >= checkpointCycleCandidateStableAgeFloorMs ->
                JpCodegenPatternMissDependencyStasisEscalated(
                    repeatCount,
                    jpCodegenPatternMissUnchangedDependencyRepeatLimit,
                    stableAgeMs,
                    checkpointCycleCandidateStableAgeFloorMs,
                    JpCodegenPatternMissDeclaredCheckpointStationaryBasis(repetitions, sampleCount, stateRef))
            | JpDeclaredBodyCheckpointCycleStationary(repetitions, sampleCount, stateRef), _ ->
                JpCodegenPatternMissDependencyProgressExpected(
                    repeatCount,
                    stableAgeMs,
                    JpCodegenPatternMissDeclaredCheckpointStationaryBasis(repetitions, sampleCount, stateRef))
            | JpDeclaredBodyCheckpointCycleRepeatingSuffix(period, repetitions, sampleCount, cycleRef), _
                when repeatCount >= jpCodegenPatternMissUnchangedDependencyRepeatLimit ->
                JpCodegenPatternMissDependencyStasisEscalated(
                    repeatCount,
                    jpCodegenPatternMissUnchangedDependencyRepeatLimit,
                    stableAgeMs,
                    0L,
                    JpCodegenPatternMissDeclaredCheckpointCycleBasis(period, repetitions, sampleCount, cycleRef))
            | JpDeclaredBodyCheckpointCycleAlternatingPair(repetitions, sampleCount, pairRef), _
                when repeatCount >= jpCodegenPatternMissUnchangedDependencyRepeatLimit
                     && stableAgeMs >= checkpointCycleCandidateStableAgeFloorMs ->
                JpCodegenPatternMissDependencyStasisEscalated(
                    repeatCount,
                    jpCodegenPatternMissUnchangedDependencyRepeatLimit,
                    stableAgeMs,
                    checkpointCycleCandidateStableAgeFloorMs,
                    JpCodegenPatternMissDeclaredCheckpointCycleBasis(2, repetitions, sampleCount, pairRef))
            | JpDeclaredBodyCheckpointCycleAlternatingPair(repetitions, sampleCount, pairRef), _ ->
                JpCodegenPatternMissDependencyProgressExpected(
                    repeatCount,
                    stableAgeMs,
                    JpCodegenPatternMissDeclaredCheckpointCycleBasis(2, repetitions, sampleCount, pairRef))
            | JpDeclaredBodyCheckpointCycleRecurrentPrefix(period, matchedPrefix, sampleCount, candidateRef), _
                when repeatCount >= jpCodegenPatternMissUnchangedDependencyRepeatLimit
                     && stableAgeMs >= checkpointCycleCandidateStableAgeFloorMs ->
                JpCodegenPatternMissDependencyStasisEscalated(
                    repeatCount,
                    jpCodegenPatternMissUnchangedDependencyRepeatLimit,
                    stableAgeMs,
                    checkpointCycleCandidateStableAgeFloorMs,
                    JpCodegenPatternMissDeclaredCheckpointCycleCandidateBasis(
                        period,
                        matchedPrefix,
                        sampleCount,
                        candidateRef))
            | JpDeclaredBodyCheckpointCycleRecurrentPrefix(period, matchedPrefix, sampleCount, candidateRef), _ ->
                JpCodegenPatternMissDependencyProgressExpected(
                    repeatCount,
                    stableAgeMs,
                    JpCodegenPatternMissDeclaredCheckpointCycleCandidateBasis(
                        period,
                        matchedPrefix,
                        sampleCount,
                        candidateRef))
            | _, (JpRequiredBodyProceduralCheckpointOutrankedByMaterialSilence _ as progressAuthority)
                when repeatCount >= jpCodegenPatternMissMinimumMeasuredRepeatCount ->
                JpCodegenPatternMissDependencyStasisEscalated(
                    repeatCount,
                    jpCodegenPatternMissMinimumMeasuredRepeatCount,
                    stableAgeMs,
                    checkpointCycleCandidateStableAgeFloorMs,
                    JpCodegenPatternMissRequiredBodyProgressBasis progressAuthority)
            | _, (JpRequiredBodyProceduralCheckpointWithinMaterialWindow _ as progressAuthority) ->
                JpCodegenPatternMissDependencyProgressExpected(
                    repeatCount,
                    stableAgeMs,
                    JpCodegenPatternMissRequiredBodyProgressBasis progressAuthority)
            | _, (JpRequiredBodyProceduralCheckpointOutrankedByMaterialSilence _ as progressAuthority) ->
                JpCodegenPatternMissDependencyProgressExpected(
                    repeatCount,
                    stableAgeMs,
                    JpCodegenPatternMissRequiredBodyProgressBasis progressAuthority)
            | _, JpRequiredBodyNoFreshCheckpoint when repeatCount >= jpCodegenPatternMissUnchangedDependencyRepeatLimit ->
                JpCodegenPatternMissDependencyStasisEscalated(
                    repeatCount,
                    jpCodegenPatternMissUnchangedDependencyRepeatLimit,
                    stableAgeMs,
                    0L,
                    JpCodegenPatternMissRepeatCountBasis jpCodegenPatternMissUnchangedDependencyRepeatLimit)
            | _, JpRequiredBodyNoFreshCheckpoint when repeatCount >= jpCodegenPatternMissMinimumMeasuredRepeatCount
                           && stableAgeMs >= observedP99Ms ->
                JpCodegenPatternMissDependencyStasisEscalated(
                    repeatCount,
                    jpCodegenPatternMissMinimumMeasuredRepeatCount,
                    stableAgeMs,
                    observedP99Ms,
                    measuredBasis)
            | _, JpRequiredBodyNoFreshCheckpoint ->
                JpCodegenPatternMissDependencyProgressExpected(repeatCount, stableAgeMs, measuredBasis)

        let jpCodegenPatternMissStasisDecisionFor verificationRef currentWorkJobId repeatCount stableAgeMs =
            let checkpointCycleLiveness =
                jpDeclaredBodyCheckpointCycleLiveness currentWorkJobId
            let attemptScopedStableAgeMs =
                match jpCodegenBodyMaterializationRecoveryAttemptClock verificationRef with
                | Some(_, attemptAgeMs) -> min stableAgeMs attemptAgeMs
                | None -> stableAgeMs
            jpCodegenPatternMissStasisDecisionForCheckpointCycleLiveness
                currentWorkJobId
                repeatCount
                attemptScopedStableAgeMs
                checkpointCycleLiveness

        let jpPromiseProducerBoundaryDispositionForCodegen authorityRole verificationRef currentWorkJobId (error:exn) =
            let boundaryDisposition = jpPortableEffectBoundaryDispositionForException error
            match error, boundaryDisposition with
            | EvalReplayValueStore.PatternMissBreakthroughEscapeTransport escape,
              JpPortableEffectPatternMissControlPreserved ->
                let signal = EvalReplayValueStore.evaluatorPatternMissDeferredEscapeSignal escape
                let decision = EvalReplayValueStore.evaluatorPatternMissDeferredSignalDecision signal
                let signalText = EvalReplayValueStore.evaluatorPatternMissDeferredSignalText signal
                let escapeText = EvalReplayValueStore.evaluatorPatternMissDeferredEscapeText escape
                let reservation = EvalReplayValueStore.evaluatorPatternMissDeferredSignalReservation signal
                let repeatCount, stableAgeMs =
                    EvalReplayValueStore.evaluatorPatternMissDeferralStasis reservation
                match jpCodegenPatternMissStasisDecisionFor verificationRef currentWorkJobId repeatCount stableAgeMs with
                | JpCodegenPatternMissDependencyProgressExpected _ ->
                    JpPromiseProducerPreservePendingWithoutFailureFill boundaryDisposition
                | JpCodegenPatternMissDependencyStasisEscalated(repeatCount, repeatLimit, stableAgeMs, stableAgeFloorMs, stasisBasis) ->
                    let recoveryRef =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-codegen-body-isolated-materialization-recovery"
                            (CompilerIdentityKernel.ContentDigest.text verificationRef
                             + "|signal=" + signalText
                             + "|escape=" + escapeText
                             + "|decision=" + EvalReplayValueStore.evaluatorPatternMissDecisionText decision
                             + "|repeat=" + string repeatCount
                             + "|stable_age_ms=" + string stableAgeMs
                             + "|basis=" + JpCodegenPatternMissStasisBasisId.text stasisBasis)
                    let isolatedMaterializationRequested =
                        match authorityRole with
                        | JpCodegenBodyProducer ownerVerificationRef when ownerVerificationRef = verificationRef ->
                            jpCodegenBodyMaterializationRecoveryTryRequest verificationRef recoveryRef
                        | JpSemanticProducer
                        | JpCodegenBodyProducer _
                        | JpObserverVerification _ -> false
                    if isolatedMaterializationRequested then
                        JpPromiseProducerPreservePendingWithoutFailureFill boundaryDisposition
                    else
                        let cancellationRef =
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-codegen-pattern-miss-material-revision-stasis-cancelled"
                                (CompilerIdentityKernel.ContentDigest.text verificationRef
                                 + "|signal=" + signalText
                                 + "|escape=" + escapeText
                                 + "|decision=" + EvalReplayValueStore.evaluatorPatternMissDecisionText decision
                                 + "|repeat=" + string repeatCount
                                 + "|stable_age_ms=" + string stableAgeMs
                                 + "|basis=" + JpCodegenPatternMissStasisBasisId.text stasisBasis)
                        JpPromiseProducerPublishPatternMissCancellation(
                            boundaryDisposition,
                            repeatCount,
                            repeatLimit,
                            stableAgeMs,
                            stableAgeFloorMs,
                            stasisBasis,
                            cancellationRef)
            | _, JpPortableEffectPatternMissControlPreserved
            | _, JpPortableEffectDeclaredSliceYieldControlPreserved ->
                JpPromiseProducerPreservePendingWithoutFailureFill boundaryDisposition
            | _, JpPortableEffectPartEvalTypeFailurePreserved
            | _, JpPortableEffectRuntimeFailurePreserved ->
                JpPromiseProducerPublishFailure boundaryDisposition

        let jpPromiseProducerExceptionDispositionForException (error:exn) =
            let boundaryDisposition = jpPortableEffectBoundaryDispositionForException error
            match boundaryDisposition with
            | JpPortableEffectPatternMissControlPreserved
            | JpPortableEffectDeclaredSliceYieldControlPreserved ->
                JpPromiseProducerPreservePendingWithoutFailureFill boundaryDisposition
            | JpPortableEffectPartEvalTypeFailurePreserved
            | JpPortableEffectRuntimeFailurePreserved ->
                JpPromiseProducerPublishFailure boundaryDisposition

        let jpPortableEffectBoundaryDispositionText = function
            | JpPortableEffectPatternMissControlPreserved -> "PreservedPatternMissControl"
            | JpPortableEffectDeclaredSliceYieldControlPreserved -> "PreservedDeclaredSliceYieldControl"
            | JpPortableEffectPartEvalTypeFailurePreserved -> "PreservedPartEvalTypeFailure"
            | JpPortableEffectRuntimeFailurePreserved -> "PreservedRuntimeFailure"

        let jpPortableEffectBoundaryEventKind = function
            | JpPortableEffectPatternMissControlPreserved
            | JpPortableEffectDeclaredSliceYieldControlPreserved -> "jp_portable_effect_control_preserved"
            | JpPortableEffectPartEvalTypeFailurePreserved
            | JpPortableEffectRuntimeFailurePreserved -> "jp_portable_effect_boundary_failed"

        let jpAuthorityBoundaryFailureFor (workUnitId:string) (error:exn) =
            let exceptionTypeText =
                let t = error.GetType()
                if System.String.IsNullOrWhiteSpace t.FullName then t.Name else t.FullName
            let exceptionType = JpExceptionTypeIdOps.create exceptionTypeText
            let failureKind =
                match EvalReplayValueStore.tryEvaluatorPatternMissBreakthroughEscape error with
                | Some _ -> JpAuthorityBoundaryPatternMissEscape
                | None ->
                    match error with
                    | JpDeclaredEvaluatorSliceYield _ -> JpAuthorityBoundaryDeclaredSliceYieldEscape
                    | PartEvalTypeError _ -> JpAuthorityBoundaryPartEvalTypeError
                    | _ -> JpAuthorityBoundaryRuntimeException
            { workUnitId = workUnitId
              exceptionType = exceptionType
              messageRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-authority-boundary-exception-message"
                    (exceptionTypeText + "|" + error.Message)
              failureKind = failureKind }

        let jpEmitAuthorityBoundaryFailure (phase:string) (failure:JpAuthorityBoundaryFailure) =
            DiagJson.emitRecord
                ({ kind = "jp_authority_boundary_failure_classified"
                   work_unit_id = failure.workUnitId
                   failure_du = jpAuthorityBoundaryFailureText failure
                   failure_kind_du = jpAuthorityBoundaryFailureKindText failure.failureKind
                   exception_type = JpExceptionTypeIdOps.text failure.exceptionType
                   message_ref = CompilerIdentityKernel.ContentDigest.text failure.messageRef
                   phase = phase
                   authority = "typed_authority_boundary_failure_not_stacktrace_authority"
                   next = "retire_or_cancel_owner_without_rethrowing_when_caller_has_safe_result_lane" }
                 : JpAuthorityBoundaryFailureClassifiedEvent)

        let runJpAuthorityJobAtDedicatedWorkerBoundaryResult (workUnitId:string) (authorityJob:Job<'T>) : JpAuthorityBoundaryResult<'T> =
            try
                CompilerKernelV2.CompilerRuntimeKernel.runHostBoundary
                    ("jp-authority|" + workUnitId)
                    authorityJob
                |> JpAuthorityBoundaryAccepted
            with e ->
                let failure = jpAuthorityBoundaryFailureFor workUnitId e
                jpEmitAuthorityBoundaryFailure "result" failure
                JpAuthorityBoundaryRejected failure

        let jpEmitAuthorityBoundaryResultAbsorbed (phase:string) (failure:JpAuthorityBoundaryFailure) =
            DiagJson.emitRecord
                ({ kind = "jp_authority_boundary_result_absorbed"
                   work_unit_id = failure.workUnitId
                   failure_du = jpAuthorityBoundaryFailureText failure
                   failure_kind_du = jpAuthorityBoundaryFailureKindText failure.failureKind
                   phase = phase
                   authority = "typed_authority_boundary_rejection_absorbed_by_result_lane"
                   next = "continue_without_recursive_worker_boundary_exception" }
                 : JpAuthorityBoundaryResultAbsorbedEvent)

        let jpIgnoreAuthorityBoundaryResult = function
            | JpAuthorityBoundaryAccepted _ -> ()
            | JpAuthorityBoundaryRejected failure ->
                jpEmitAuthorityBoundaryResultAbsorbed "ignore" failure

        let runJpPortableEffectAtDedicatedWorkerBoundary
            (workUnitId:string)
            (effect:CompilerKernelV2.PortableEffect<'T>)
            : 'T =
            let capturedAuthorityJob =
                job {
                    try
                        let! value = CompilerKernelV2.CompilerRuntimeKernel.toJob effect
                        return Choice1Of2 value
                    with error ->
                        return Choice2Of2 (capture_edi error)
                }
            match
                CompilerKernelV2.CompilerRuntimeKernel.runHostBoundary
                    ("jp-portable-effect|" + workUnitId)
                    capturedAuthorityJob
            with
            | Choice1Of2 value -> value
            | Choice2Of2 errorDispatch ->
                let error = errorDispatch.SourceException
                let patternMissEscape = EvalReplayValueStore.tryEvaluatorPatternMissBreakthroughEscape error
                let patternMissEscapeText =
                    patternMissEscape
                    |> Option.map EvalReplayValueStore.evaluatorPatternMissDeferredEscapeText
                    |> Option.defaultValue "none"
                let boundaryDisposition =
                    jpPortableEffectBoundaryDispositionForException error
                let eventKind = jpPortableEffectBoundaryEventKind boundaryDisposition
                let occurrenceCount, emitBoundary =
                    match boundaryDisposition with
                    | JpPortableEffectPatternMissControlPreserved ->
                        DiagJson.sparseLogDecision "jp_portable_effect_control_preserved|pattern_miss" 256L
                    | JpPortableEffectDeclaredSliceYieldControlPreserved ->
                        DiagJson.sparseLogDecision "jp_portable_effect_control_preserved|declared_slice_yield" 256L
                    | JpPortableEffectPartEvalTypeFailurePreserved
                    | JpPortableEffectRuntimeFailurePreserved -> 1L, true
                if emitBoundary then
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":%s,\"work_unit_id\":%s,\"effect_ref\":%s,\"exception_type\":%s,\"pattern_miss_escape_du\":%s,\"boundary_disposition_du\":%s,\"occurrence_count\":%d,\"sparse_policy\":\"pattern_miss_first3_power2_every256_real_failure_always\",\"exception_identity_preserved\":true,\"authority\":\"portable_runtime_fsharp_hopac_adapter_captured_inside_job\"}" [| box (DiagJson.esc eventKind); box (DiagJson.esc workUnitId); box (DiagJson.esc (CompilerKernelV2.PortableEffectOps.effectRef effect |> CompilerIdentityKernel.ContentDigest.text)); box (DiagJson.esc (error.GetType().FullName)); box (DiagJson.esc patternMissEscapeText); box (DiagJson.esc (jpPortableEffectBoundaryDispositionText boundaryDisposition)); box occurrenceCount |])
                errorDispatch.Throw()
                Unchecked.defaultof<'T>

        let runJpWorkPlanAtDedicatedWorkerBoundary
            (item:JpWorkItem)
            (effect:CompilerKernelV2.PortableEffect<'T>)
            : 'T =
            runJpPortableEffectAtDedicatedWorkerBoundary
                (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)
                effect

        let runJpWorkExecutionPlanAtDedicatedWorkerBoundary
            (item:JpWorkItem)
            (effect:CompilerKernelV2.PortableEffect<JpWorkExecutionOutcome>)
            : JpWorkExecutionOutcome =
            let workUnitId = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
            let capturedAuthorityJob =
                job {
                    try
                        let! value = CompilerKernelV2.CompilerRuntimeKernel.toJob effect
                        return Choice1Of3 value
                    with
                    | EvalReplayValueStore.PatternMissBreakthroughEscapeTransport escape ->
                        return Choice2Of3 (EvalReplayValueStore.evaluatorPatternMissDeferredEscapeSignal escape)
                    | error ->
                        return Choice3Of3(capture_edi error)
                }
            match
                CompilerKernelV2.CompilerRuntimeKernel.runHostBoundary
                    ("jp-execution-effect|" + workUnitId)
                    capturedAuthorityJob
            with
            | Choice1Of3 value -> value
            | Choice2Of3 signal ->
                JpWorkExecutionPatternMissDeferredControl signal
            | Choice3Of3 errorDispatch ->
                let error = errorDispatch.SourceException
                let patternMissEscape = EvalReplayValueStore.tryEvaluatorPatternMissBreakthroughEscape error
                let patternMissEscapeText =
                    patternMissEscape
                    |> Option.map EvalReplayValueStore.evaluatorPatternMissDeferredEscapeText
                    |> Option.defaultValue "none"
                let boundaryDisposition =
                    jpPortableEffectBoundaryDispositionForException error
                let eventKind = jpPortableEffectBoundaryEventKind boundaryDisposition
                let occurrenceCount, emitBoundary =
                    match boundaryDisposition with
                    | JpPortableEffectPatternMissControlPreserved ->
                        DiagJson.sparseLogDecision "jp_execution_effect_control_preserved|pattern_miss_fallback" 256L
                    | JpPortableEffectDeclaredSliceYieldControlPreserved ->
                        DiagJson.sparseLogDecision "jp_execution_effect_control_preserved|declared_slice_yield_fallback" 256L
                    | JpPortableEffectPartEvalTypeFailurePreserved
                    | JpPortableEffectRuntimeFailurePreserved -> 1L, true
                if emitBoundary then
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":%s,\"work_unit_id\":%s,\"effect_ref\":%s,\"exception_type\":%s,\"pattern_miss_escape_du\":%s,\"boundary_disposition_du\":%s,\"occurrence_count\":%d,\"sparse_policy\":\"pattern_miss_fallback_first3_power2_every256_real_failure_always\",\"exception_identity_preserved\":true,\"authority\":\"portable_runtime_fsharp_hopac_adapter_captured_inside_execution_job\"}" [| box (DiagJson.esc eventKind); box (DiagJson.esc workUnitId); box (DiagJson.esc (CompilerKernelV2.PortableEffectOps.effectRef effect |> CompilerIdentityKernel.ContentDigest.text)); box (DiagJson.esc (error.GetType().FullName)); box (DiagJson.esc patternMissEscapeText); box (DiagJson.esc (jpPortableEffectBoundaryDispositionText boundaryDisposition)); box occurrenceCount |])
                errorDispatch.Throw()
                Unchecked.defaultof<JpWorkExecutionOutcome>

        let jpRetirePortableFiber
            (item:JpWorkItem)
            (fiberLease:CompilerKernelV2.PortableFiberLease) =
            let receiptRef, applied =
                CompilerKernelV2.CompilerRuntimeKernel.retireFiber fiberLease
            if applied then
                DiagJson.emitRecord {
                    kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagPortableRuntimeFiberRetired
                    work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                    scope_ref =
                        fiberLease
                        |> CompilerKernelV2.PortableFiberLeaseOps.scopeRef
                        |> CompilerIdentityKernel.ContentDigest.text
                    fiber_ref =
                        fiberLease
                        |> CompilerKernelV2.PortableFiberLeaseOps.fiberRef
                        |> CompilerIdentityKernel.ContentDigest.text
                    cancellation_ref =
                        fiberLease
                        |> CompilerKernelV2.PortableFiberLeaseOps.cancellation
                        |> CompilerKernelV2.PortableCancellationHandleOps.cancellationRef
                        |> CompilerIdentityKernel.ContentDigest.text
                    retirement_receipt_ref = CompilerIdentityKernel.ContentDigest.text receiptRef
                    authority = "portable_scope_exact_once_fiber_retirement"
                }

        let jp_worker_lane_gate = obj()
        let mutable jp_active_declared_body_workers = 0
        let mutable jp_declared_body_retired_count = 0L
        let mutable jp_declared_body_long_retired_count = 0L
        let mutable jp_declared_body_max_retirement_duration_ms = 0L
        let jp_declared_body_long_retirement_threshold_ms = 3000L
        let mutable jp_active_observer_workers = 0
        let mutable jp_semantic_lane_last_open_ms = Environment.TickCount64

        let jpNoteDeclaredBodyRetirement durationMs =
            lock jp_worker_lane_gate (fun () ->
                jp_declared_body_retired_count <- jp_declared_body_retired_count + 1L
                jp_declared_body_max_retirement_duration_ms <-
                    max jp_declared_body_max_retirement_duration_ms durationMs
                if durationMs >= jp_declared_body_long_retirement_threshold_ms then
                    jp_declared_body_long_retired_count <- jp_declared_body_long_retired_count + 1L
                jp_declared_body_retired_count,
                jp_declared_body_long_retired_count,
                jp_declared_body_max_retirement_duration_ms)

        let jpEmitDurationProfileSnapshot (snapshot:JpDurationProfileSnapshot option) =
            match snapshot with
            | None -> ()
            | Some snapshot ->
                let topText =
                    snapshot.topEntries
                    |> List.map (fun entry ->
                        FastRuntimeFormat.format "%s@%s:%dms" [|
                            box (CompilerIdentityKernel.ContentDigest.text entry.workUnitRef)
                            box (CompilerIdentityKernel.WorkShapeIdOps.text entry.shapeId)
                            box (CompilerKernelV2.Measured.value entry.duration) |])
                    |> String.concat ","
                let shapeText =
                    snapshot.shapeSummaries
                    |> List.map (fun summary ->
                        FastRuntimeFormat.format "%s(count=%d|p50=%d|p90=%d|p99=%d|max=%d|total=%d|slow=%d|ref=%s)" [|
                            box (CompilerIdentityKernel.WorkShapeIdOps.text summary.shapeId)
                            box (CompilerKernelV2.Measured.value summary.sampleCount)
                            box (CompilerKernelV2.Measured.value summary.p50)
                            box (CompilerKernelV2.Measured.value summary.p90)
                            box (CompilerKernelV2.Measured.value summary.p99)
                            box (CompilerKernelV2.Measured.value summary.maxDuration)
                            box (CompilerKernelV2.Measured.value summary.totalDuration)
                            box (CompilerKernelV2.Measured.value summary.slowCount)
                            box (CompilerIdentityKernel.ContentDigest.text summary.summaryRef) |])
                    |> String.concat ";"
                let cohortText =
                    snapshot.cohortSummaries
                    |> List.map (fun summary ->
                        FastRuntimeFormat.format "%s/%s/%s/%s(count=%d|p50=%d|p90=%d|p99=%d|max=%d|total=%d|slow=%d|ref=%s)" [|
                            box (CompilerIdentityKernel.WorkShapeIdOps.text summary.shapeId)
                            box (jpSpecializationIntentText summary.intent)
                            box (jpWorkAuthorityRoleText summary.authorityRole)
                            box (jpComputationMemoProbeText summary.memoProbe)
                            box (CompilerKernelV2.Measured.value summary.sampleCount)
                            box (CompilerKernelV2.Measured.value summary.p50)
                            box (CompilerKernelV2.Measured.value summary.p90)
                            box (CompilerKernelV2.Measured.value summary.p99)
                            box (CompilerKernelV2.Measured.value summary.maxDuration)
                            box (CompilerKernelV2.Measured.value summary.totalDuration)
                            box (CompilerKernelV2.Measured.value summary.slowCount)
                            box (CompilerIdentityKernel.ContentDigest.text summary.summaryRef) |])
                    |> String.concat ";"
                DiagJson.emitRecord {
                    kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitProfileSnapshot
                    completed_count = CompilerKernelV2.Measured.value snapshot.completedCount
                    total_inclusive_duration_ms = CompilerKernelV2.Measured.value snapshot.totalDuration
                    aggregate_overlap_du = "ParallelAndNestedInclusiveDurationsNotWallClock"
                    top10_duration_ms = CompilerKernelV2.Measured.value snapshot.top10Duration
                    top10_concentration_bp = CompilerKernelV2.BasisPoints.value snapshot.top10ConcentrationBp
                    heavy_tail_class_du = jpDurationHeavyTailClassText snapshot.heavyTailClass
                    top20_du = topText
                    shape_histograms_du = shapeText
                    cohort_histograms_du = cohortText
                    profile_ref = CompilerIdentityKernel.ContentDigest.text snapshot.profileRef
                    authority = "single_actor_duration_profile"
                    next = "consume_heavy_tail_class_in_eta_and_grace"
                }

        let rec jp_execute_work_item (item:JpWorkItem) =
            let workUnitIdText = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
            let attemptFiberLease =
                CompilerKernelV2.CompilerRuntimeKernel.leaseFiber
                    "jp-specialization-workers"
                    (CompilerKernelV2.OperationalReasonIdOps.create
                        ("execution-attempt:" + workUnitIdText))
            let currentGeneration = CacheGeneration.current()
            if currentGeneration <> item.generation then
                let reason = JpGenerationSupersededBeforeStart
                let change =
                    CacheGeneration.superseded
                        item.generation
                        (CacheGeneration.GenerationChangeReasonIdOps.create
                            (jpGenerationSupersessionReasonText reason))
                runJpWorkPlanAtDedicatedWorkerBoundary
                    item
                    (item.cancel
                        (JpGenerationScopeCancellation
                            (CompilerKernelV2.OperationalReasonIdOps.create
                                (jpGenerationSupersessionReasonText reason))))
                |> ignore
                JpSpecializationWorklistAuthority.cancel item.workNode change.transitionRef
                let semanticReceipt =
                    CompilerKernelV2.WorkUnitReceipt.create
                        item.workUnit
                        (CompilerKernelV2.WorkUnitSuperseded change.transitionRef)
                        item.cost
                let _, supersededTransitions, suspendedContinuation =
                    JpWorkOperationalCursor.retireBeforeStart
                        (CompilerKernelV2.WorkTerminalSuperseded change.transitionRef)
                        item.operational
                supersededTransitions
                |> List.iteri (fun index transition ->
                    let isFinal = index = supersededTransitions.Length - 1
                    let semanticMutation =
                        if isFinal && jpWorkAuthorityRoleOwnsSemanticLedger item.authorityRole then
                            jpOperationalSemanticApply semanticReceipt
                        else
                            jpOperationalNoSemanticMutation
                    let transactionResult =
                        runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                            (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)
                            (jp_operational_work_transact
                                (JpOperationalWorkTransitionTransaction(transition,semanticMutation)))
                    match transactionResult with
                    | JpAuthorityBoundaryAccepted (Ok _) -> ()
                    | JpAuthorityBoundaryAccepted (Error rejection) ->
                        raise (PartEvalTypeError([], "superseded work transaction rejected: " + jpOperationalWorkTransactionRejectionText rejection))
                    | JpAuthorityBoundaryRejected _ -> ())
                match suspendedContinuation with
                | Some continuation ->
                    runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                        (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)
                        (CompilerKernelV2.WorkContinuation.resume
                            continuation
                            (Error(CompilerKernelV2.WorkResumeGenerationSuperseded change.transitionRef)))
                    |> jpIgnoreAuthorityBoundaryResult
                | None -> ()
                if jpWorkAuthorityRoleOwnsSemanticLedger item.authorityRole then
                    runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                        (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)
                        (jp_generation_scope_retire item)
                    |> jpIgnoreAuthorityBoundaryResult
                if jpWorkAuthorityRoleParticipatesInRequiredWorkRecovery item.authorityRole then
                    jp_required_work_slice_progress_forget item.generation item.commitOrdinal
                match item.workNode.intent with
                | JpVerifyDeclaredMethodBody ->
                    jpDeclaredBodyLifetimeRetire item.commitOrdinal
                    jpRemoveDeclaredEvaluatorContinuationsForJob item.commitOrdinal
                | _ -> ()
                let reasonText = jpGenerationSupersessionReasonText reason
                let resultIdentity =
                    reasonText
                    + "|work_unit=" + CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                    + "|exact_once=" + (CompilerKernelV2.workUnitReceiptExactOnceRef semanticReceipt |> CompilerIdentityKernel.ContentDigest.text)
                CompilerKernelV2.ConfluentWorkCell.complete
                    (jpWorkItemDeclarationBindingId item)
                    item.commitOrdinal
                    resultIdentity
                    (JpWorkSpecializationCancelled(JpGenerationCancellation(CompilerKernelV2.OperationalReasonIdOps.create reasonText, change.transitionRef)))
                |> jp_merge_work_cell (jpWorkItemDeclarationBindingId item)
                |> runJpAuthorityJobAtDedicatedWorkerBoundaryResult (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)
                |> jpIgnoreAuthorityBoundaryResult
                jpRetirePortableFiber item attemptFiberLease
            else
                let startedAtMs = System.Environment.TickCount64
                let attemptProgressStartedAtMs = max 0L (jp_progress_clock())
                let attemptCheckpointOrdinal =
                    let mutable checkpoint = Unchecked.defaultof<JpDeclaredBodyCheckpoint>
                    if jp_declared_body_checkpoints.TryGetValue(item.commitOrdinal, &checkpoint) then checkpoint.checkpointOrdinal
                    else 0L
                let runningWork, startTransition, resumedContinuation =
                    JpWorkOperationalCursor.start item.operational
                let startTransaction =
                    runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                        (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)
                        (jp_operational_work_transact
                            (JpOperationalWorkTransitionTransaction(
                                startTransition,
                                jpOperationalNoSemanticMutation)))
                match startTransaction with
                | JpAuthorityBoundaryAccepted (Error rejection) ->
                    raise (PartEvalTypeError([], "operational start rejected: " + jpOperationalWorkTransactionRejectionText rejection))
                | JpAuthorityBoundaryAccepted (Ok _) -> ()
                | JpAuthorityBoundaryRejected _ -> ()
                match resumedContinuation with
                | Some continuation ->
                    runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                        (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)
                        (CompilerKernelV2.WorkContinuation.resume continuation (Ok()))
                    |> jpIgnoreAuthorityBoundaryResult
                | None -> ()
                jpInstallActiveWorkTiming item
                let tryRetireTerminalSuspendedWork suspendedCursor durationMs =
                    let mutable deadlineClaim = 0uy
                    let deadlineClaimPresent =
                        jp_execution_deadline_claims.TryGetValue(item.commitOrdinal, &deadlineClaim)
                    let terminalRetirement =
                        match JpSpecializationWorklistAuthority.tryTerminalDisposition item.workNode with
                        | Some (CompilerKernelV2.WorkTerminalFailed failureRef) ->
                            Some(
                                failureRef,
                                CompilerKernelV2.WorkTerminalFailed failureRef,
                                JpWorkSpecializationFailed(
                                    JpSemanticSpecializationFailure(
                                        JpSemanticFailureOperationalReason(
                                            CompilerKernelV2.OperationalReasonIdOps.create "terminal_failure_before_requeue"),
                                        failureRef)),
                                CompilerKernelV2.WorkResumeProducerFailed failureRef)
                        | Some (CompilerKernelV2.WorkTerminalCancelled cancellationRef) ->
                            Some(
                                cancellationRef,
                                CompilerKernelV2.WorkTerminalCancelled cancellationRef,
                                JpWorkSpecializationCancelled(
                                    JpHostCancellation(
                                        CompilerKernelV2.OperationalReasonIdOps.create "terminal_cancellation_before_requeue",
                                        cancellationRef)),
                                CompilerKernelV2.WorkResumeCancelled cancellationRef)
                        | Some (CompilerKernelV2.WorkTerminalSuperseded transitionRef) ->
                            Some(
                                transitionRef,
                                CompilerKernelV2.WorkTerminalSuperseded transitionRef,
                                JpWorkSpecializationSuperseded transitionRef,
                                CompilerKernelV2.WorkResumeGenerationSuperseded transitionRef)
                        | Some (CompilerKernelV2.WorkTerminalSucceeded _) -> None
                        | None when DiagJson.terminalFailureExitRequestedNow() ->
                            let cancellation =
                                jpTerminalFailureCutoverCancellation item.workUnit item.commitOrdinal
                            let cancellationRef = jpWorkCancellationRef cancellation
                            Some(
                                cancellationRef,
                                CompilerKernelV2.WorkTerminalCancelled cancellationRef,
                                JpWorkSpecializationCancelled cancellation,
                                CompilerKernelV2.WorkResumeCancelled cancellationRef)
                        | None -> None
                    match terminalRetirement with
                    | Some(terminalRef, terminalDispositionId, terminalResult, continuationFailure) ->
                        jpInstallActiveWorkTiming item
                        let resumedWork, resumeTransition, suspendedContinuation =
                            JpWorkOperationalCursor.start suspendedCursor
                        let resumeResult =
                            runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                workUnitIdText
                                (jp_operational_work_transact
                                    (JpOperationalWorkTransitionTransaction(
                                        resumeTransition,
                                        jpOperationalNoSemanticMutation)))
                        match resumeResult with
                        | JpAuthorityBoundaryAccepted (Error rejection) ->
                            raise (PartEvalTypeError([], "terminal suspension resume rejected: " + jpOperationalWorkTransactionRejectionText rejection))
                        | JpAuthorityBoundaryAccepted (Ok _) ->
                            match suspendedContinuation with
                            | Some continuation ->
                                runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                    workUnitIdText
                                    (CompilerKernelV2.WorkContinuation.resume
                                        continuation
                                        (Error continuationFailure))
                                |> jpIgnoreAuthorityBoundaryResult
                            | None -> ()
                            let timingPartition = jpActiveWorkTimingPartition item.commitOrdinal durationMs
                            try
                                runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                    workUnitIdText
                                    (jp_complete_work_item
                                        item
                                        resumedWork
                                        terminalResult
                                        durationMs
                                        timingPartition)
                                |> jpIgnoreAuthorityBoundaryResult
                            finally
                                jpRemoveDeclaredEvaluatorContinuationsForJob item.commitOrdinal
                                jpRemoveActiveWorkTiming item.commitOrdinal
                            DiagJson.emitRecord
                                ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitTerminalRetrySuppressed
                                   work_unit_id = workUnitIdText
                                   job_id = item.commitOrdinal
                                   failure_ref = CompilerIdentityKernel.ContentDigest.text terminalRef
                                   terminal_disposition_du = CompilerKernelV2.WorkTerminalDispositionOps.text terminalDispositionId
                                   retry_published = false
                                   deadline_claim_lifetime_scoped = deadlineClaimPresent
                                   authority = "terminal_disposition_or_irrevocable_failure_cutover_precedes_suspended_successor_publication"
                                   next = "retire_without_requeue" }
                                 : JpWorkUnitTerminalRetrySuppressedEvent)
                            true
                        | JpAuthorityBoundaryRejected _ ->
                            false
                    | None -> false
                let tryPromoteIsolatedMaterializationCheckpointCycleAtSafePoint () =
                    match item.authorityRole with
                    | JpCodegenBodyProducer verificationRef ->
                        match jpCodegenBodyMaterializationRecoveryTryGetAttempted verificationRef with
                        | Some attemptRef ->
                            match jpTryTakeDeclaredCheckpointCancellationSafePointHandoff item.commitOrdinal with
                            | Some handoff ->
                                let proofText = jpDeclaredCheckpointCancellationHandoffProofText handoff.proof
                                let cancellationRef =
                                    CompilerIdentityKernel.ContentDigest.ofText
                                        "jp-isolated-codegen-body-checkpoint-cycle-safe-point-cancelled"
                                        (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                                         + "|verification=" + CompilerIdentityKernel.ContentDigest.text verificationRef
                                         + "|attempt=" + CompilerIdentityKernel.ContentDigest.text attemptRef
                                         + "|proof=" + proofText)
                                let cancellationReason =
                                    CompilerKernelV2.OperationalReasonIdOps.create
                                        "isolated_codegen_body_checkpoint_cycle_safe_point"
                                // The running evaluator owns this safe point. The watchdog supplied
                                // only typed cycle evidence; it never mutates the promise directly.
                                // Promise and worklist cancellation become authoritative together here.
                                JpSpecializationWorklistAuthority.cancel item.workNode cancellationRef
                                runJpWorkPlanAtDedicatedWorkerBoundary
                                    item
                                    (item.cancel (JpHostRequestedCancellation cancellationReason))
                                |> ignore
                                jpCodegenBodyMaterializationRecoveryRetire verificationRef
                                let safePointAgeMs =
                                    max 0L (max 0L (jp_progress_clock()) - handoff.publishedAtMs)
                                DiagJson.emit (
                                    FastRuntimeFormat.format
                                        "{\"kind\":\"jp_codegen_body_isolated_materialization_checkpoint_cycle_safe_point_cancelled\",\"work_job_id\":%d,\"work_unit_id\":%s,\"verification_ref\":%s,\"attempt_ref\":%s,\"checkpoint_cycle_proof_du\":%s,\"observed_steps_lower_bound\":%d,\"handoff_age_ms\":%d,\"semantic_failure\":false,\"watchdog_terminal_authority\":false,\"bounded_safe_point_authority\":true,\"promise_cancel_requested\":true,\"authority\":\"typed_checkpoint_cycle_watchdog_handoff_plus_exact_owner_attempted_recovery_plus_owner_safe_point\",\"next\":\"retire_cancelled_suspended_owner_without_requeue\"}"
                                        [| box item.commitOrdinal; box (DiagJson.esc (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text verificationRef)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text attemptRef)); box (DiagJson.esc proofText); box handoff.observedSteps; box safePointAgeMs |])
                                true
                            | None -> false
                        | None -> false
                    | JpSemanticProducer
                    | JpObserverVerification _ -> false
                let handlePatternMissDeferredControl signal =
                    let durationMs = max 0L (System.Environment.TickCount64 - startedAtMs)
                    let decision = EvalReplayValueStore.evaluatorPatternMissDeferredSignalDecision signal
                    let deferralReservation = EvalReplayValueStore.evaluatorPatternMissDeferredSignalReservation signal
                    let deferralCommand =
                        JpPatternMissDeferralCommandOps.create
                            signal
                            item.authorityRole
                    let decisionText =
                        JpPatternMissDeferralCommandOps.decisionText deferralCommand
                    let signalText =
                        JpPatternMissDeferralCommandOps.signalText deferralCommand
                    let diagnosticFactsText =
                        JpPatternMissDeferralCommandOps.diagnosticFactText deferralCommand
                    let rawDeferralDisposition = deferralCommand.rawDisposition
                    let deferralDisposition = deferralCommand.effectiveDisposition
                    let deferralDispositionText =
                        JpPatternMissDeferralCommandOps.effectiveDispositionText deferralCommand
                    let deferralRepeatCount = deferralCommand.repeatCount
                    let deferralStableAgeMs = deferralCommand.stableAgeMs
                    let requiredCodegenBodyPreserved =
                        JpPatternMissDeferralCommandOps.preservesRequiredCodegenBody deferralCommand
                    let isolatedMaterializationRecoveryRequested =
                        match item.authorityRole with
                        | JpCodegenBodyProducer verificationRef ->
                            jpCodegenBodyMaterializationRecoveryIsRequested verificationRef
                        | JpSemanticProducer
                        | JpObserverVerification _ -> false
                    let directCheckpointCycleLiveness =
                        if requiredCodegenBodyPreserved then
                            Some (jpDeclaredBodyCheckpointCycleLiveness item.commitOrdinal)
                        else None
                    let directStasisDecision =
                        directCheckpointCycleLiveness
                        |> Option.map (fun checkpointCycleLiveness ->
                            jpCodegenPatternMissStasisDecisionForCheckpointCycleLiveness
                                item.commitOrdinal
                                deferralRepeatCount
                                deferralStableAgeMs
                                checkpointCycleLiveness)
                    let workUnitIdText = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                    if requiredCodegenBodyPreserved then
                        let checkpointCycleLivenessText =
                            directCheckpointCycleLiveness
                            |> Option.map jpDeclaredBodyCheckpointCycleLivenessText
                            |> Option.defaultValue "NotApplicable"
                        let checkpointCycleLivenessKindText =
                            match directCheckpointCycleLiveness with
                            | Some (JpDeclaredBodyCheckpointCycleInsufficientEvidence _) -> "InsufficientEvidence"
                            | Some (JpDeclaredBodyCheckpointCycleAdvancing _) -> "Advancing"
                            | Some (JpDeclaredBodyCheckpointCycleStationary _) -> "Stationary"
                            | Some (JpDeclaredBodyCheckpointCycleAlternatingPair _) -> "AlternatingPair"
                            | Some (JpDeclaredBodyCheckpointCycleRecurrentPrefix _) -> "RecurrentPrefix"
                            | Some (JpDeclaredBodyCheckpointCycleRepeatingSuffix _) -> "RepeatingSuffix"
                            | None -> "NotApplicable"
                        let stasisDecisionText =
                            directStasisDecision
                            |> Option.map jpCodegenPatternMissStasisDecisionText
