                                FastRuntimeFormat.format
                                    "{\"kind\":\"jp_work_unit_pattern_miss_required_codegen_body_preserved\",\"work_unit_id\":%s,\"producer_origin_du\":%s,\"signal_du\":%s,\"diagnostic_facts_du\":%s,\"raw_disposition_du\":%s,\"effective_disposition_du\":%s,\"deferral_authority_du\":%s,\"repeat_count\":%d,\"stable_age_ms\":%d,\"checkpoint_cycle_liveness_du\":%s,\"stasis_decision_du\":%s,\"required_body_progress_authority_du\":%s,\"occurrence_count\":%d,\"sparse_policy\":\"semantic_state_first3_power2_every64\",\"stasis_key_du\":\"GenerationPatternDependencyMaterialRevisionPlusRequiredBodyProgressAuthority\",\"operational_completion_required\":true,\"semantic_completion_credit\":false,\"authority\":\"typed_codegen_body_producer_cannot_retire_as_control_only_replay\",\"next\":\"requeue_until_dependency_material_revision_advances_or_typed_stasis_escalates\"}"
                                    [| box (DiagJson.esc workUnitIdText); box (DiagJson.esc (JpPatternMissDeferralCommandOps.originText deferralCommand)); box (DiagJson.esc signalText); box (DiagJson.esc diagnosticFactsText); box (DiagJson.esc (JpPatternMissDeferralCommandOps.rawDispositionText deferralCommand)); box (DiagJson.esc deferralDispositionText); box (DiagJson.esc (JpPatternMissDeferralCommandOps.authorityText deferralCommand)); box deferralRepeatCount; box deferralStableAgeMs; box (DiagJson.esc checkpointCycleLivenessText); box (DiagJson.esc stasisDecisionText); box (DiagJson.esc requiredBodyProgressAuthorityText); box preservedSparseOccurrence |])
                    let dependencyRef =
