                    let retireStableReplaySentinelFromSuspended () =
                        let resumedWork, resumeTransition, continuation =
                            JpWorkOperationalCursor.start suspendedCursor
                        let resumeAuthorityResult =
                            runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                workUnitIdText
                                (jp_operational_work_transact
