                                    [| box (DiagJson.esc workUnitIdText); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text dependencyRef)); box (DiagJson.esc signalText); box (DiagJson.esc (JpPatternMissDeferralCommandOps.diagnosticFactTextWithStasisCancelled deferralCommand)); box (DiagJson.esc decisionText); box (DiagJson.esc (JpPatternMissDeferralCommandOps.authorityText deferralCommand)); box repeatCount; box repeatLimit; box stableAgeMs; box stableAgeFloorMs; box (DiagJson.esc (JpCodegenPatternMissStasisBasisId.text stasisBasis)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text cancellationRef)) |])
