                                        [| box item.commitOrdinal; box (DiagJson.esc (JpWorkContinuationRefOps.text resumeRef)); box blockerNodeId; box (DiagJson.esc blockerChannelText); box (DiagJson.esc blockerText); box (jpDeclaredContinuationOrdinalCurrent item.commitOrdinal); box (jpDeclaredResumeEvidenceRevisionCurrent item.commitOrdinal); box (DiagJson.esc (jpTypedCarrierProofGateText (JpTypedCarrierProofGateAwaitingEvidence(jpTypedCarrierWakeEvidenceCurrent item.commitOrdinal)))); box occurrence |])
                            JpWorkExecutionYielded(resumeRef, JpDeclaredSliceYieldTypedCarrierBlocked), false
                        | false, _, _ ->
                            jpInstallDeclaredResumeTarget item.commitOrdinal effectiveSemanticResume
                            try
                                let outcome =
                                    runJpWorkExecutionPlanAtDedicatedWorkerBoundary item (item.execute item.workNode)
                                let targetStillPending = jp_declared_resume_targets.ContainsKey item.commitOrdinal
                                outcome, (match effectiveSemanticResume with Some _ -> not targetStillPending | None -> false)
                            finally
                                jpClearDeclaredResumeTarget item.commitOrdinal
                    match effectiveSemanticResume with
                    | Some resumeRef ->
                        let occurrence, shouldEmitResumeTarget =
                            DiagJson.sparseLogDecision ("jp_declared_semantic_resume_target_observed|" + string item.commitOrdinal) 64L
                        if shouldEmitResumeTarget then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"jp_declared_semantic_resume_target_observed\",\"work_job_id\":%d,\"continuation_ref\":%s,\"consumed\":%b,\"resume_spine_depth\":%d,\"resume_spine_terminal_du\":%s,\"resume_result_channel_du\":%s,\"resume_spine_apply_count\":%d,\"resume_spine_let_count\":%d,\"resume_spine_sequence_count\":%d,\"resume_spine_binary_numeric_count\":%d,\"resume_spine_fold_count\":%d,\"resume_snapshot_live_count\":%d,\"resume_snapshot_job_live_count\":%d,\"occurrence_count\":%d,\"authority\":\"typed_work_item_resume_target_observation_only\",\"next\":\"measure_direct_entry_hit_rate_remaining_prefix_replay_and_snapshot_bound\"}" [| box item.commitOrdinal; box (DiagJson.esc (JpWorkContinuationRefOps.text resumeRef)); box semanticResumeTargetConsumed; box semanticResumeSpineDepth; box (DiagJson.esc semanticResumeSpineTerminal); box (DiagJson.esc semanticResumeResultChannel); box semanticResumeApplyCount; box semanticResumeLetCount; box semanticResumeSequenceCount; box semanticResumeBinaryNumericCount; box semanticResumeFoldCount; box jp_declared_resume_snapshots.Count; box (jpDeclaredResumeSnapshotLiveCountForJob item.commitOrdinal); box occurrence |])
                    | None -> ()
                    let mutable executionOutcomeHandled = false
