                    | JpWorkExecutionCompleted -> ()
                    | JpWorkExecutionPatternMissDeferredControl signal ->
                        // Pattern miss is terminal for this physical execution attempt: the handler
                        // either suspends/requeues, cancels, retires, or emits a typed failure. Never
                        // fall through into the generic success-completion path for the old Running cursor.
                        handlePatternMissDeferredControl signal
                        executionOutcomeHandled <- true
                    | JpWorkExecutionYielded(continuationRef, yieldCause) ->
                        let durationMs = max 0L (System.Environment.TickCount64 - startedAtMs)
                        let workUnitIdText = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                        let continuationText = JpWorkContinuationRefOps.text continuationRef
                        let dependencyRef =
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-cooperative-yield-dependency"
                                (workUnitIdText + "|continuation=" + continuationText)
                        let suspendedCursor, suspendTransition =
                            JpWorkOperationalCursor.suspend dependencyRef runningWork
                        let suspendAuthorityResult =
                            runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                workUnitIdText
                                (jp_operational_work_transact
                                    (JpOperationalWorkTransitionTransaction(
                                        suspendTransition,
