                        match suspendAuthorityResult with
                        | JpAuthorityBoundaryRejected failure ->
                            jpEmitAuthorityBoundaryResultAbsorbed "cooperative_yield_suspend" failure
                            raise (PartEvalTypeError([], "cooperative yield boundary rejected: " + jpAuthorityBoundaryFailureText failure))
                        | JpAuthorityBoundaryAccepted (Error (JpOperationalWorkStaleTransition(transitionRef,expectedStateRef,currentState,currentStateRef)))
                            when jpOperationalWorkStaleTransitionSupersedesAttempt currentState ->
                            executionOutcomeHandled <- true
                            DiagJson.emit (
                                FastRuntimeFormat.format
                                    "{\"kind\":\"jp_work_execution_yield_stale_owner_suppressed\",\"work_unit_id\":%s,\"dependency_ref\":%s,\"transition_ref\":%s,\"expected_state_ref\":%s,\"current_state_du\":%s,\"current_state_ref\":%s,\"semantic_failure\":false,\"semantic_credit_retired\":false,\"current_owner_preserved\":true,\"authority\":\"typed_operational_stale_attempt_superseded_by_current_owner\",\"next\":\"drain_next_unrelated_work_item\"}"
                                    [| box (DiagJson.esc workUnitIdText)
                                       box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text dependencyRef))
                                       box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text transitionRef))
                                       box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text expectedStateRef))
                                       box (DiagJson.esc (CompilerKernelV2.operationalWorkGraphNodeStateText currentState))
                                       box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text currentStateRef)) |])
                        | JpAuthorityBoundaryAccepted (Error rejection) ->
                            raise (PartEvalTypeError([], "cooperative yield transition rejected: " + jpOperationalWorkTransactionRejectionText rejection))
