                            JpSpecializationWorklistAuthority.suspend item.workNode suspensionReason
                            let typedCarrierProofGate =
                                if typedCarrierBlockedYield then
                                    JpTypedCarrierProofGateAwaitingEvidence(
                                        jpTypedCarrierWakeEvidenceCurrent item.commitOrdinal)
                                else JpTypedCarrierProofGateOpen
                            let yieldedItem =
