                                    jp_note_required_work_slice_progress
                                        item.generation
                                        item.commitOrdinal
                                        progressFingerprint
                                else false, 0
                            let sameContinuationYieldCount =
                                if item.workNode.intent = JpVerifyDeclaredMethodBody then
                                    observedSameContinuationYieldCount
                                else 0
                            if item.workNode.intent = JpVerifyDeclaredMethodBody && requiredWorkSliceProgressed then
