                                if jp_active_operation_profiles.TryGetValue(item.commitOrdinal, &profile) then
                                    lock profile.profileGate (fun () -> max 0L profile.operationCount)
                                else 0L
                            // A typed checkpoint-cycle handoff may have arrived from the watchdog
