                            match queueDisposition with
                            | None -> executionOutcomeHandled <- true
                            | Some (JpSpecializationQueueAdmitted depthAfter) ->
                                let lifetimeAgeMs, lifetimeOperationIdleMs, lifetimeDeferralCount =
                                    match jpDeclaredBodyLifetimeSnapshot item.commitOrdinal (max 0L (jp_progress_clock())) with
                                    | Some(ageMs, _, operationIdleMs, deferralCount) -> ageMs, operationIdleMs, deferralCount
                                    | None -> 0L, 0L, 0L
                                let finishThroughOwned =
                                    match finishThroughClaim with
                                    | JpDeclaredBodyFinishThroughAcquired _
                                    | JpDeclaredBodyFinishThroughOwned _ -> true
                                    | JpDeclaredBodyFinishThroughNotEligible _
                                    | JpDeclaredBodyFinishThroughHeldByOther _ -> false
                                let recoverySlicePolicy =
