                                        finishThroughOwned
                                        (jpSpecializationSemanticQueueDepth ())
                                        lifetimeAgeMs
                                        cumulativeOperationCount
                                        lifetimeOperationIdleMs
                                let recoverySliceMultiplier =
                                    jpDeclaredBodyRecoverySliceMultiplier recoverySlicePolicy
                                let _, sparseYieldEvidence =
                                    DiagJson.sparseLogDecision
                                        ("jp_work_unit_cooperative_yielded|" + workUnitIdText + "|" + jpDeclaredEvaluatorSliceYieldCauseText yieldCause)
                                        64L
