                                if yieldEvidenceMilestone then DiagJson.emitRecord {
                                    kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitCooperativeYielded
                                    work_unit_id = workUnitIdText
                                    continuation_ref = continuationText
                                    yield_cause_du = jpDeclaredEvaluatorSliceYieldCauseText yieldCause
                                    duration_before_yield_ms = durationMs
                                    queue_depth_after = depthAfter
                                    execution_policy_du = jpWorkExecutionPolicyText item.executionPolicy
                                    same_continuation_yield_count = sameContinuationYieldCount
                                    finish_through_claim_du = jpDeclaredBodyFinishThroughClaimText finishThroughClaim
                                    cumulative_operation_count = cumulativeOperationCount
                                    cumulative_lifetime_age_ms = lifetimeAgeMs
                                    cumulative_operation_idle_ms = lifetimeOperationIdleMs
                                    cumulative_deferral_count = lifetimeDeferralCount
                                    recovery_slice_policy_du = jpDeclaredBodyRecoverySlicePolicyText recoverySlicePolicy
                                    recovery_slice_multiplier = recoverySliceMultiplier
                                    timing_lifecycle_du = jpYieldTimingLifecycleText timingLifecycle
                                    operational_state_du = "Suspended"
                                    authority = "typed_execution_outcome_running_to_suspended_declared_body_lifetime_scoped"
