                                        DiagJson.sparseLogDecision ("jp_required_work_slice_progress|" + workUnitIdText) 64L
                                    if shouldEmitRequiredWorkSliceProgress then
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"jp_required_work_slice_progress\",\"generation\":%d,\"commit_ordinal\":%d,\"work_unit_id\":%s,\"continuation_ref\":%s,\"progress_fingerprint\":%s,\"slice_sequence\":%d,\"occurrence_count\":%d,\"work_authority_role_du\":%s,\"sparse_policy\":\"first3_power2_every64_per_work_unit\",\"semantic_completion_credit\":false,\"terminal_authority\":false,\"authority\":\"changed_required_work_position_receipt\",\"next\":\"refresh_scheduler_liveness_without_retirement\"}" [| box item.generation; box item.commitOrdinal; box (DiagJson.esc workUnitIdText); box (DiagJson.esc continuationText); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text progressFingerprint)); box (jp_required_work_slice_progress_read ()); box requiredWorkSliceOccurrence; box (DiagJson.esc (jpWorkAuthorityRoleText item.authorityRole)) |])
