                                            workUnitIdText
                                            (CompilerKernelV2.WorkContinuation.resume continuation (Ok()))
                                        |> jpIgnoreAuthorityBoundaryResult
                                    | None -> ()
                                    let cancellationRef =
                                        CompilerIdentityKernel.ContentDigest.ofText
                                            "jp-cooperative-yield-backpressure"
                                            (workUnitIdText + "|depth=" + string depth + "|capacity=" + string capacity)
                                    let cancellationReason =
                                        CompilerKernelV2.OperationalReasonIdOps.create "cooperative_yield_queue_backpressure"
                                    let cancellation = JpQueueBackpressureWorkCancellation(cancellationReason, cancellationRef)
                                    JpSpecializationWorklistAuthority.cancel item.workNode cancellationRef
                                    let timingPartition = jpActiveWorkTimingPartition item.commitOrdinal durationMs
                                    try
