                    | JpWorkExecutionSpawned(childWorkRef, continuationRef) ->
                        raise (PartEvalTypeError([], "declared-body spawned before resumable continuation execution is wired: child=" + JpChildWorkRefOps.text childWorkRef + "|continuation=" + JpWorkContinuationRefOps.text continuationRef))
                    | JpWorkExecutionFailed failure ->
                        let failedResult = JpWorkSpecializationFailed failure
                        let failureRef = jpWorkResultRef failedResult
                        JpSpecializationWorklistAuthority.fail item.workNode failureRef
                        let durationMs = max 0L (System.Environment.TickCount64 - startedAtMs)
                        let timingPartition = jpActiveWorkTimingPartition item.commitOrdinal durationMs
                        try
                            let failureCompleteResult =
                                runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                    (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)
                                    (jp_complete_work_item
                                        item
                                        runningWork
                                        failedResult
                                        durationMs
                                        timingPartition)
                            match failureCompleteResult with
