                                    ("jp_worker_item_typed_failure_recovered|typed|" + CompilerIdentityKernel.ContentDigest.text failureRef)
                                    64L
                            if shouldEmitIsolation then
                                DiagJson.emitRecord
                                    ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkerItemTypedFailureRecovered
                                       work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                                       failure_ref = CompilerIdentityKernel.ContentDigest.text failureRef
                                       exception_type = "TypedExecutionOutcome"
                                       occurrence_count = isolationOccurrence
                                       worker_continues = true
                                       authority = "per_item_typed_failure_isolation_without_exception_roundtrip"
                                       next = "drain_next_unrelated_work_item" }
                                     : JpWorkerItemTypedFailureRecoveredEvent)
                        finally
                            jpRemoveDeclaredEvaluatorContinuationsForJob item.commitOrdinal
                            jpRemoveActiveWorkTiming item.commitOrdinal
                        executionOutcomeHandled <- true
                    | JpWorkExecutionCancelled cancellation ->
