                                        [| box item.generation; box item.commitOrdinal; box (DiagJson.esc (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)); box durationMs; box (DiagJson.esc (jpWorkCancellationText cancellation)); box (DiagJson.esc (jpWorkExecutionPolicyText item.executionPolicy)) |])
