                        | JpWorkExecutionAwaiting _
                        | JpWorkExecutionSpawned _
                        | JpWorkExecutionFailed _
                        | JpWorkExecutionCancelled _ -> false
                    if genericSuccessCompletionAllowed then
                        let normalizedRef =
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-specialization-normalized"
                                (CompilerIdentityKernel.ContentDigest.text item.workNode.nodeRef
                                 + "|intent=" + jpSpecializationIntentText item.workNode.intent)
                        let readbackRef =
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-specialization-readback"
                                (CompilerIdentityKernel.ContentDigest.text normalizedRef
                                 + "|site=" + item.site)
