                            JpSpecializationWorklistAuthority.prepareCompletion
                                item.workNode
                                (Some normalizedRef)
                                (Some readbackRef)
                                None
                        DiagJson.emitRecord {
                            kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpSpecializationBodyEvaluated
                            work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                            node_ref = CompilerIdentityKernel.ContentDigest.text item.workNode.nodeRef
                            generation = specializationReceipt.generation
                            intent_du = jpSpecializationIntentText item.workNode.intent
                            prepared_terminal_stage_du = jpSpecializationStageText specializationReceipt.terminalStage
                            input_ref = CompilerIdentityKernel.ContentDigest.text specializationReceipt.inputRef
                            normalized_ref = CompilerIdentityKernel.ContentDigest.text normalizedRef
                            readback_ref = CompilerIdentityKernel.ContentDigest.text readbackRef
                            receipt_ref = CompilerIdentityKernel.ContentDigest.text specializationReceipt.receiptRef
                            authority = "typed_evaluation_receipt_precedes_operational_retirement"
                            next = "commit_operational_retirement_then_specialization_terminal"
                        }
                        let durationMs = max 0L (System.Environment.TickCount64 - startedAtMs)
                        let timingPartition = jpActiveWorkTimingPartition item.commitOrdinal durationMs
                        let _ =
                            let terminalOverride =
                                match
                                    runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                        (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)
                                        (jp_complete_work_item
                                            item
                                            runningWork
                                            (JpWorkSpecializationSucceeded specializationReceipt.receiptRef)
                                            durationMs
                                            timingPartition)
                                with
                                | JpAuthorityBoundaryRejected failure ->
                                    jpEmitAuthorityBoundaryResultAbsorbed "specialization_success_complete" failure
                                    false
                                | JpAuthorityBoundaryAccepted value -> value
