                                jpRemoveActiveWorkTiming item.commitOrdinal
                                executionOutcomeHandled <- true
                            if not terminalOverride then
                                jpAdvanceActiveWorkPublicationStage
                                    item.commitOrdinal
                                    JpWorkPublicationEffectWitness
                                match item.workNode.runtimeEffect with
                                | JpRuntimeEffectRequired witness ->
                                    JpRuntimeEffectWitnessAuthority.complete witness readbackRef |> ignore
                                | JpRuntimeEffectPure -> ()
                                jpAdvanceActiveWorkPublicationStage
                                    item.commitOrdinal
