                                // Operational retirement is already durable; re-run closure only after
                                // the specialization worklist publishes the matching terminal receipt.
                                CompilerConsoleHud88.retryTerminalClosure ()
                                match item.workNode.intent with
                                | JpVerifyDeclaredMethodBody ->
                                    let retiredCount, longRetiredCount, maxDurationMs =
                                        jpNoteDeclaredBodyRetirement durationMs
                                    let shouldEmit =
                                        retiredCount <= 3L
                                        || (retiredCount &&& (retiredCount - 1L)) = 0L
                                        || durationMs >= jp_declared_body_long_retirement_threshold_ms
                                    if shouldEmit then
                                        DiagJson.emitRecord {
                                            kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpDeclaredBodyRetirementWitness
                                            work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                                            generation = committedReceipt.generation
                                            duration_ms = durationMs
                                            retired_count = retiredCount
                                            long_retired_count = longRetiredCount
                                            max_duration_ms = maxDurationMs
                                            long_retirement_threshold_ms = jp_declared_body_long_retirement_threshold_ms
                                            authority = "committed_declared_body_receipt_calibrates_parallel_lane"
                                            next = "bootstrap_bounded_two_then_receipt_calibrated_ramp"
                                        }
                                | _ -> ()
                                jpAdvanceActiveWorkPublicationStage
                                    item.commitOrdinal
                                    JpWorkPublicationCommitted
                                DiagJson.emitRecord {
                                    kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpSpecializationWorkCompleted
                                    work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                                    node_ref = CompilerIdentityKernel.ContentDigest.text item.workNode.nodeRef
                                    generation = committedReceipt.generation
                                    receipt_ref = CompilerIdentityKernel.ContentDigest.text committedReceipt.receiptRef
                                    publication_stage_du = "Committed"
                                    authority = "operational_retirement_precedes_specialization_terminal"
                                    next = "remove_active_timing_and_continue"
                                }
                                jpRemoveDeclaredEvaluatorContinuationsForJob item.commitOrdinal
                                jpRemoveActiveWorkTiming item.commitOrdinal
                        ()
                  finally
                        // Portable execution attempts end exactly once here. Logical declared-body
                        // continuations/timing survive suspension; explicit terminal branches own
                        // logical retirement, while the outer worker boundary owns only lane bookkeeping.
                        jpRetirePortableFiber item attemptFiberLease
                with
                | EvalReplayValueStore.PatternMissBreakthroughEscapeTransport escape ->
                    handlePatternMissDeferredControl (EvalReplayValueStore.evaluatorPatternMissDeferredEscapeSignal escape)
                | e ->
                    let durationMs = max 0L (System.Environment.TickCount64 - startedAtMs)
                    let diagnostic = DiagnosticClassifier.classifyIngress e.Message
                    let rootCompleteHandoff =
                        DiagnosticClassifier.ingressFacts diagnostic
                        |> Set.contains DiagnosticClassifier.DiagnosticBigStackSemanticRootCompleteHandoff
                    let canonicalRoot = DiagJson.canonicalRootAuthoritySnapshot()
                    if rootCompleteHandoff && not (System.String.IsNullOrWhiteSpace canonicalRoot.receiptId) then
                        let workUnitId = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                        let handoffIdentity =
                            canonicalRoot.receiptId
                            + "|" + workUnitId
                            + "|" + CompilerKernelV2.StableBindingId.text (jpWorkItemDeclarationBindingId item)
                        let handoffRef =
                            CompilerIdentityKernel.ContentDigest.ofText "jp-bigstack-root-complete-handoff" handoffIdentity
                            |> CompilerIdentityKernel.ContentDigest.text
                        // A root-complete handoff retires this work unit but does not
                        // prove that the operational graph is quiescent.  QAP finality
                        // owns the later BuildOk candidate.
                        DiagJson.emitRecord {
                            kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpBigStackRootCompleteHandoffDeferred
                            canonical_root_receipt_id = canonicalRoot.receiptId
                            work_unit_id = workUnitId
                            handoff_ref = handoffRef
                            terminal_candidate_published = false
                            operational_quiescence_required = true
                            work_completion_du = "SucceededByCanonicalRootHandoff"
                            authority = "canonical_root_plus_typed_diagnostic_fact_not_global_quiescence"
                            next = "retire_work_then_await_qap_finality"
                        }
                        let handoffDigest = CompilerIdentityKernel.ContentDigest.ofText "jp-specialization-root-handoff" handoffRef
                        let handoffReceipt =
                            JpSpecializationWorklistAuthority.prepareCompletion
                                item.workNode
                                None
                                None
                                (Some handoffDigest)
                        let timingPartition = jpActiveWorkTimingPartition item.commitOrdinal durationMs
                        try
                            let terminalOverride =
                                match
                                    runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                        (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)
                                        (jp_complete_work_item
                                            item
                                            runningWork
                                            (JpWorkSpecializationSucceeded handoffDigest)
                                            durationMs
                                            timingPartition) with
                                | JpAuthorityBoundaryAccepted terminalOverride -> terminalOverride
                                | JpAuthorityBoundaryRejected failure ->
                                    DiagJson.emitRecord
                                        ({ kind = "jp_root_handoff_completion_authority_boundary_deferred"
                                           work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                                           failure_du = jpAuthorityBoundaryFailureText failure
                                           terminal_override = false
                                           authority = "root_handoff_completion_failure_preserves_worker_boundary"
                                           next = "continue_terminal_retry_without_rethrowing_root_handoff_completion" }
                                         : JpRootHandoffCompletionAuthorityBoundaryDeferredEvent)
                                    false
                            if terminalOverride then
                                jpRemoveDeclaredEvaluatorContinuationsForJob item.commitOrdinal
                                jpRemoveActiveWorkTiming item.commitOrdinal
                            else
                                jpAdvanceActiveWorkPublicationStage
                                    item.commitOrdinal
                                    JpWorkPublicationWorklistCommit
                                let committedReceipt =
                                    JpSpecializationWorklistAuthority.commitCompletion
                                        item.workNode
                                        handoffReceipt
                                CompilerConsoleHud88.retryTerminalClosure ()
                                match item.workNode.intent with
                                | JpVerifyDeclaredMethodBody ->
                                    let retiredCount, longRetiredCount, maxDurationMs =
                                        jpNoteDeclaredBodyRetirement durationMs
                                    let shouldEmit =
                                        retiredCount <= 3L
                                        || (retiredCount &&& (retiredCount - 1L)) = 0L
                                        || durationMs >= jp_declared_body_long_retirement_threshold_ms
                                    if shouldEmit then
                                        DiagJson.emitRecord {
                                            kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpDeclaredBodyRetirementWitness
                                            work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                                            generation = committedReceipt.generation
                                            duration_ms = durationMs
                                            retired_count = retiredCount
                                            long_retired_count = longRetiredCount
                                            max_duration_ms = maxDurationMs
                                            long_retirement_threshold_ms = jp_declared_body_long_retirement_threshold_ms
                                            authority = "committed_root_handoff_receipt_calibrates_parallel_lane"
                                            next = "bootstrap_bounded_two_then_receipt_calibrated_ramp"
                                        }
                                | _ -> ()
                                jpAdvanceActiveWorkPublicationStage
                                    item.commitOrdinal
                                    JpWorkPublicationCommitted
                        finally
                            jpRemoveDeclaredEvaluatorContinuationsForJob item.commitOrdinal
                            jpRemoveActiveWorkTiming item.commitOrdinal
                    elif jpWorkAuthorityRoleIsObserverVerification item.authorityRole then
                        let exceptionType =
                            let observedType = e.GetType()
                            if System.String.IsNullOrWhiteSpace observedType.FullName then observedType.Name
                            else observedType.FullName
                        let computationIdentity, instantiationId, _, authorityRole =
                            jpWorkComputationMetadataForItem
                                item
                                (item.specializationPlan
                                 |> CompilerKernelV2.JoinPointSpecializationPlanView.planRef
                                 |> CompilerIdentityKernel.ContentDigest.text
                                 |> CompilerKernelV2.InstantiationIdOps.create)
                        DiagJson.emitRecord {
                            kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpObserverVerificationFailed
                            work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                            computation_kind_du = jpComputationIdentityKindText computationIdentity
                            computation_key = jpComputationIdentityText computationIdentity
                            computation_instantiation_ref = CompilerKernelV2.InstantiationIdOps.text instantiationId
                            authority_role_du = jpWorkAuthorityRoleText authorityRole
                            exception_type = exceptionType
                            semantic_ledger_apply = false
                            global_exception_broadcast = false
                            terminal_authority = false
                            next = "preserve_declared_interface_and_retire_observer"
                        }
                        let failureRef =
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-observer-specialization-failure"
                                (CompilerIdentityKernel.ContentDigest.text item.workNode.nodeRef
                                 + "|exception=" + exceptionType)
                        JpSpecializationWorklistAuthority.fail item.workNode failureRef
                        let timingPartition = jpActiveWorkTimingPartition item.commitOrdinal durationMs
                        try
                            match
                                runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                    (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)
                                    (jp_complete_work_item
                                        item
                                        runningWork
                                        (JpWorkSpecializationFailed(JpObserverVerificationFailure(JpExceptionTypeIdOps.create exceptionType, failureRef)))
                                        durationMs
                                        timingPartition)
                            with
                            | JpAuthorityBoundaryAccepted _ -> ()
                            | JpAuthorityBoundaryRejected failure ->
                                jpEmitAuthorityBoundaryResultAbsorbed "observer_verification_failure_complete" failure
                        finally
                            jpRemoveDeclaredEvaluatorContinuationsForJob item.commitOrdinal
                            jpRemoveActiveWorkTiming item.commitOrdinal
                    else
                        let exceptionType =
                            let observedType = e.GetType()
                            if System.String.IsNullOrWhiteSpace observedType.FullName then observedType.Name
                            else observedType.FullName
                        let partEvalTypeTrace, rawPartEvalTypeMessage =
                            match e with
                            | PartEvalTypeError(trace, message) ->
                                Some trace, Some (if obj.ReferenceEquals(message, null) then "" else message)
                            | _ -> None, None
                        let partEvalTypeMessage =
                            rawPartEvalTypeMessage
                            |> Option.map (fun message ->
                                let safe = message.Replace("\r", " ").Replace("\n", " ").Replace("\t", " ")
                                if safe.Length <= 512 then safe else safe.Substring(0, 512))
                        let partEvalFailureSite, partEvalFailureNodeId, retainedTraceFrames =
                            match partEvalTypeTrace with
                            | Some (r :: _ as trace) ->
                                let p0, p1 = r.range
                                let site =
                                    FastRuntimeFormat.format
                                        "jp@%s:%d:%d-%d:%d"
                                        [| box r.path; box (p0.line + 1); box (p0.character + 1); box (p1.line + 1); box (p1.character + 1) |]
                                let nodeId =
                                    CompilerIdentityKernel.ContentDigest.ofText "jp-part-eval-failure-node" site
                                    |> CompilerIdentityKernel.ContentDigest.text
                                site, nodeId, trace.Length
                            | Some [] ->
                                let site = "jp@unknown"
                                let nodeId =
                                    CompilerIdentityKernel.ContentDigest.ofText "jp-part-eval-failure-node" site
                                    |> CompilerIdentityKernel.ContentDigest.text
                                site, nodeId, 0
                            | None -> "", "", 0
                        let failureRef =
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-specialization-failure"
                                (CompilerIdentityKernel.ContentDigest.text item.workNode.nodeRef
                                 + "|exception=" + exceptionType
                                 + "|message=" + (partEvalTypeMessage |> Option.defaultValue ""))
                        let partEvalFailureCause =
                            rawPartEvalTypeMessage
                            |> Option.map jpPartEvalFailureCauseFor
                        let workFailure =
                            match partEvalTypeMessage, partEvalFailureCause, item.authorityRole with
                            | Some message, Some causeId, _ ->
                                JpPartEvalTypeFailure(causeId, CompilerKernelV2.OperationalReasonIdOps.create message, failureRef)
                            | _, _, JpCodegenBodyProducer _ ->
                                JpCodegenBodyFailure(JpExceptionTypeIdOps.create exceptionType, failureRef)
                            | _ ->
                                JpSemanticSpecializationFailure(JpSemanticFailureException (JpExceptionTypeIdOps.create exceptionType), failureRef)
                        JpSpecializationWorklistAuthority.fail item.workNode failureRef
                        // A typed PartEvalTypeFailure is already the semantic authority. Do not
                        // duplicate it into the generic runtime-exception channel, which made one
                        // compiler fact look like two unrelated failures in the JSONL.
                        match partEvalTypeMessage with
                        | Some _ -> ()
                        | None -> CompilerConsoleHud88.captureWorkerBoundaryException "jp_execute_work_item" e
                        match partEvalTypeMessage, partEvalFailureCause with
                        | Some message, Some causeId ->
                            let failureRefText = CompilerIdentityKernel.ContentDigest.text failureRef
                            let workUnitIdText = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                            let causeText = jpPartEvalFailureCauseText causeId
                            let failureDetailRef =
                                CompilerIdentityKernel.ContentDigest.ofText
                                    "jp-part-eval-failure-detail"
                                    (partEvalFailureNodeId + "|" + message)
                                |> CompilerIdentityKernel.ContentDigest.text
                            let semanticMessageRef =
                                CompilerIdentityKernel.ContentDigest.ofText
                                    "jp-part-eval-semantic-message"
                                    message
                                |> CompilerIdentityKernel.ContentDigest.text
                            DiagJson.emitRecord {
                                kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpPartEvalTypeErrorFailClosed
                                current_work_job_id = item.commitOrdinal
                                work_unit_id = workUnitIdText
                                authority_role_du = jpWorkAuthorityRoleText item.authorityRole
                                failure_ref = failureRefText
                                cause_du = causeText
                                semantic_message = message
                                semantic_message_ref = semanticMessageRef
                                failure_site = partEvalFailureSite
                                failure_site_present = not (System.String.IsNullOrWhiteSpace partEvalFailureSite)
                                failure_node_id = partEvalFailureNodeId
                                failure_detail_ref = failureDetailRef
                                retained_trace_frames = retainedTraceFrames
                                exception_type = exceptionType
                                terminal_intent_du = "FailClosed"
                                control_authority_inputs_du = "typed_work_job+work_unit+authority_role+typed_failure_cause+failure_ref"
                                source_identity_control_authority = false
                                source_path_authority = false
                                source_span_authority = false
                                symbol_name_authority = false
                                diagnostic_text_authority = false
                                diagnostic_schema_version = 2
                                authority = "typed_worker_boundary_part_eval_error_with_preserved_trace_and_stable_refs"
                                next = "publish_single_terminal_actor_failure_with_typed_job_authority_source_identity_diagnostic_only"
                            }
                            DiagJson.publishTerminalOutcomeCandidateObserved
                                DiagJson.TerminalOutcomeCandidateFailClosed
                                ("jp-part-eval-type-error:" + failureRefText)
                                workUnitIdText
                                ("PartEvalTypeError|cause=" + causeText + "|" + message)
                        | _ -> ()
                        match partEvalTypeMessage with
                        | Some _ -> ()
                        | None ->
                            let edi = capture_edi e
                            jp_work_exns.[item.commitOrdinal] <- edi
                            jp_exns.Enqueue edi
                        let timingPartition = jpActiveWorkTimingPartition item.commitOrdinal durationMs
                        try
                            match
                                runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                    (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)
                                    (jp_complete_work_item
                                        item
                                        runningWork
                                        (JpWorkSpecializationFailed workFailure)
                                        durationMs
                                        timingPartition) with
                            | JpAuthorityBoundaryAccepted _ -> ()
                            | JpAuthorityBoundaryRejected failure ->
                                DiagJson.emitRecord
                                    ({ kind = "jp_failure_completion_authority_boundary_deferred"
                                       work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                                       failure_du = jpAuthorityBoundaryFailureText failure
                                       terminal_failure_preserved = true
                                       authority = "failure_completion_boundary_result_lane_prevents_recursive_worker_exception"
                                       next = "terminal_deadman_or_retry_can_observe_typed_failure_without_extra_system_exception" }
                                     : JpFailureCompletionAuthorityBoundaryDeferredEvent)
                            match partEvalTypeMessage with
                            | Some _ ->
                                let isolationOccurrence, shouldEmitIsolation =
                                    DiagJson.sparseLogDecision
                                        ("jp_worker_item_typed_failure_recovered|boundary|" + CompilerIdentityKernel.ContentDigest.text failureRef)
                                        64L
                                if shouldEmitIsolation then
                                    DiagJson.emitRecord
                                        ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkerItemTypedFailureRecovered
                                           work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                                           failure_ref = CompilerIdentityKernel.ContentDigest.text failureRef
                                           exception_type = exceptionType
                                           occurrence_count = isolationOccurrence
                                           worker_continues = true
                                           authority = "per_item_part_eval_failure_isolation_after_typed_retirement"
                                           next = "drain_next_unrelated_work_item_or_terminal_cutover" }
                                         : JpWorkerItemTypedFailureRecoveredEvent)
                            | None -> ()
                        finally
                            jpRemoveDeclaredEvaluatorContinuationsForJob item.commitOrdinal
                            jpRemoveActiveWorkTiming item.commitOrdinal

        and jp_complete_work_item
            (item:JpWorkItem)
            (runningWork:CompilerKernelV2.WorkItem<
                CompilerKernelV2.ElaboratedPhase,
                CompilerKernelV2.JoinPointWorkKind,
                CompilerKernelV2.WorkOwnerBoundState,
                CompilerKernelV2.WorkRunningState>)
            (result:JpWorkResult)
            (durationMs:int64)
            (timingPartition:JpWorkTimingPartition option)
            : Job<bool> =
            job {
                jpAdvanceActiveWorkPublicationStage
                    item.commitOrdinal
                    JpWorkPublicationOperationalRetirement
                let preexistingTerminalOverride =
                    match result, JpSpecializationWorklistAuthority.tryTerminalDisposition item.workNode with
                    | JpWorkSpecializationSucceeded _, Some (CompilerKernelV2.WorkTerminalFailed failureRef) ->
                        Some(
                            JpWorkSpecializationFailed(
                                JpSemanticSpecializationFailure(
                                    JpSemanticFailureOperationalReason(
                                        CompilerKernelV2.OperationalReasonIdOps.create "worklist_terminal_failure_precedes_late_success"),
                                    failureRef)))
                    | JpWorkSpecializationSucceeded _, Some (CompilerKernelV2.WorkTerminalCancelled cancellationRef) ->
                        Some(
                            JpWorkSpecializationCancelled(
                                JpHostCancellation(
                                    CompilerKernelV2.OperationalReasonIdOps.create "worklist_terminal_cancellation_precedes_late_success",
                                    cancellationRef)))
                    | JpWorkSpecializationSucceeded _, Some (CompilerKernelV2.WorkTerminalSuperseded transitionRef) ->
                        Some(JpWorkSpecializationSuperseded transitionRef)
                    | _ -> None
                let result = preexistingTerminalOverride |> Option.defaultValue result
                let resultRef = jpWorkResultRef result
                let semanticDisposition, operationalDisposition =
                    match result with
                    | JpWorkSpecializationSucceeded receiptRef ->
                        CompilerKernelV2.WorkUnitRetired receiptRef,
                        CompilerKernelV2.WorkTerminalSucceeded receiptRef
                    | JpWorkSpecializationFailed _ ->
                        CompilerKernelV2.WorkUnitFailed resultRef,
                        CompilerKernelV2.WorkTerminalFailed resultRef
                    | JpWorkSpecializationCancelled _ ->
                        CompilerKernelV2.WorkUnitCancelled resultRef,
                        CompilerKernelV2.WorkTerminalCancelled resultRef
                    | JpWorkSpecializationSuperseded transitionRef ->
                        CompilerKernelV2.WorkUnitSuperseded transitionRef,
                        CompilerKernelV2.WorkTerminalSuperseded transitionRef

                let semanticReceipt =
                    CompilerKernelV2.WorkUnitReceipt.create
                        item.workUnit
                        semanticDisposition
                        item.cost
                let receiptDigest = CompilerKernelV2.workUnitReceiptExactOnceRef semanticReceipt
                let retiredWork, terminalDisposition =
                    CompilerKernelV2.WorkItemOps.retire operationalDisposition runningWork
                let retirementTransition =
                    CompilerKernelV2.WorkTransitionOps.retire
                        runningWork
                        retiredWork
                        terminalDisposition
                let semanticMutation =
                    if jpWorkAuthorityRoleOwnsSemanticLedger item.authorityRole then
                        jpOperationalSemanticApply semanticReceipt
                    else
                        jpOperationalNoSemanticMutation
                let! transactionResult =
                    jp_operational_work_transact
                        (JpOperationalWorkTransitionTransaction(
                            retirementTransition,
                            semanticMutation))
                match transactionResult with
                | Error rejection ->
                    return raise (PartEvalTypeError([], "operational retirement rejected: " + jpOperationalWorkTransactionRejectionText rejection))
                | Ok transactionReceipt ->
                    // Operational retirement and the specialization worklist are one logical
                    // terminal transaction. Confirm/repair failure or cancellation in the
                    // worklist after the operational+semantic retirement transaction is accepted;
                    // eager terminal intent may already be present to defeat a concurrent late success.
                    match result with
                    | JpWorkSpecializationFailed _ ->
                        JpSpecializationWorklistAuthority.fail item.workNode resultRef
                    | JpWorkSpecializationCancelled _ ->
                        JpSpecializationWorklistAuthority.cancel item.workNode resultRef
                    | JpWorkSpecializationSucceeded _
                    | JpWorkSpecializationSuperseded _ -> ()
                    if jpWorkAuthorityRoleOwnsSemanticLedger item.authorityRole then
                        jpAdvanceActiveWorkPublicationStage
                            item.commitOrdinal
                            JpWorkPublicationGenerationRetirement
                        do! jp_generation_scope_retire item
                    if jpWorkAuthorityRoleParticipatesInRequiredWorkRecovery item.authorityRole then
                        jp_required_work_slice_progress_forget item.generation item.commitOrdinal
                    jpAdvanceActiveWorkPublicationStage
                        item.commitOrdinal
                        JpWorkPublicationCellMerge
                    do! jp_merge_work_cell
                            (jpWorkItemDeclarationBindingId item)
                            (CompilerKernelV2.ConfluentWorkCell.complete
                                (jpWorkItemDeclarationBindingId item)
                                item.commitOrdinal
                                (jpWorkResultText result)
                                result)
                    let wallExclusiveMs, cpuMsPresent, cpuMsValue, cpuAuthorityText, cpuNormalizationText, childWaitCount =
                        match timingPartition with
                        | Some partition ->
                            let cpuExclusive =
                                partition.receipt
                                |> CompilerKernelV2.WorkTimingReceiptOps.cpuExclusive
                            let cpuAuthority =
                                partition.receipt
                                |> CompilerKernelV2.WorkTimingReceiptOps.cpuAuthority
                                |> CompilerKernelV2.CpuTimeAuthority.stableText
                            CompilerKernelV2.Measured.value partition.wallExclusive,
                            Option.isSome cpuExclusive,
                            cpuExclusive |> Option.map CompilerKernelV2.Measured.value |> Option.defaultValue 0L,
                            cpuAuthority,
                            jpCpuWallNormalizationText partition.cpuNormalization,
                            partition.childWaitCount
                        | None ->
                            max 0L durationMs,
                            false,
                            0L,
                            "unavailable:no_active_timing_partition",
                            jpCpuWallNormalizationText JpCpuWallNotMeasured,
                            0
                    DiagJson.emitRecord {
                        kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpOperationalWorkRetired
                        work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                        binding_id = CompilerKernelV2.StableBindingId.text (jpWorkItemDeclarationBindingId item)
                        generation = item.generation
                        duration_ms = durationMs
                        wall_exclusive_ms = wallExclusiveMs
                        cpu_ms_present = cpuMsPresent
                        cpu_ms = cpuMsValue
                        cpu_authority_du = cpuAuthorityText
                        cpu_normalization_du = cpuNormalizationText
                        child_wait_count = childWaitCount
                        publication_stage_du = "Committed"
                        result_du = jpWorkResultText result
                        operational_state_du = "Retired"
                        semantic_mutation_applied = transactionReceipt.semanticMutationApplied
                        semantic_ledger_admitted = transactionReceipt.semanticAdmittedCount
                        semantic_ledger_receipts = transactionReceipt.semanticReceiptCount
                        receipt_ref = CompilerIdentityKernel.ContentDigest.text receiptDigest
                        transaction_ref = CompilerIdentityKernel.ContentDigest.text transactionReceipt.transactionRef
                        transaction_disposition_du = jpOperationalWorkTransactionDispositionText transactionReceipt.disposition
                        authority = "single_operational_graph_semantic_transaction"
                    }
                    let! durationProfileSnapshot = jpDurationProfileNoteJob item durationMs
                    jpEmitDurationProfileSnapshot durationProfileSnapshot
                    CompilerConsoleHud88.retryTerminalClosure ()
                    return Option.isSome preexistingTerminalOverride
            }

        let jp_start_work_for_terminal (item:JpWorkItem) : Job<CompilerKernelV2.WorkItem<
            CompilerKernelV2.ElaboratedPhase,
            CompilerKernelV2.JoinPointWorkKind,
            CompilerKernelV2.WorkOwnerBoundState,
            CompilerKernelV2.WorkRunningState>> =
            job {
                let runningWork, startTransition, continuation =
                    JpWorkOperationalCursor.start item.operational
                let! transactionResult =
                    jp_operational_work_transact
                        (JpOperationalWorkTransitionTransaction(
                            startTransition,
                            jpOperationalNoSemanticMutation))
                match transactionResult with
                | Error rejection ->
                    return raise (PartEvalTypeError([], "terminal start transition rejected: " + jpOperationalWorkTransactionRejectionText rejection))
                | Ok _ ->
                    match continuation with
                    | Some continuation ->
                        do! CompilerKernelV2.WorkContinuation.resume continuation (Ok())
                    | None -> ()
                    return runningWork
            }

        let jpTerminalDispositionRef = function
            | CompilerKernelV2.WorkTerminalSucceeded receiptRef
            | CompilerKernelV2.WorkTerminalFailed receiptRef
            | CompilerKernelV2.WorkTerminalCancelled receiptRef
            | CompilerKernelV2.WorkTerminalSuperseded receiptRef -> receiptRef

        let jpTerminalDispositionSemanticRetirement = function
            | CompilerKernelV2.WorkTerminalSucceeded receiptRef -> CompilerKernelV2.WorkUnitRetired receiptRef
            | CompilerKernelV2.WorkTerminalFailed failureRef -> CompilerKernelV2.WorkUnitFailed failureRef
            | CompilerKernelV2.WorkTerminalCancelled cancellationRef -> CompilerKernelV2.WorkUnitCancelled cancellationRef
            | CompilerKernelV2.WorkTerminalSuperseded transitionRef -> CompilerKernelV2.WorkUnitSuperseded transitionRef

        let jp_retire_terminal_unstarted_admission terminalDisposition (item:JpWorkItem) : Job<bool> =
            job {
                let semanticMutationExpected =
                    jpWorkAuthorityRoleOwnsSemanticLedger item.authorityRole
                let semanticDisposition =
                    jpTerminalDispositionSemanticRetirement terminalDisposition
                let semanticMutation =
                    if semanticMutationExpected then
                        CompilerKernelV2.WorkUnitReceipt.create item.workUnit semanticDisposition item.cost
                        |> jpOperationalSemanticApply
                    else
                        jpOperationalNoSemanticMutation
                let _, retirementTransitions, suspendedContinuation =
                    JpWorkOperationalCursor.retireBeforeStart terminalDisposition item.operational
                match retirementTransitions, suspendedContinuation with
                | [ retirementTransition ], None ->
                    let! transactionResult =
                        jp_operational_work_transact
                            (JpOperationalWorkTransitionTransaction(
                                retirementTransition,
                                semanticMutation))
                    match transactionResult with
                    | Error rejection ->
                        return raise (PartEvalTypeError([], "unstarted terminal retirement rejected: " + jpOperationalWorkTransactionRejectionText rejection))
                    | Ok transactionReceipt ->
                        if semanticMutationExpected then
                            do! jp_generation_scope_retire item
                        if jpWorkAuthorityRoleParticipatesInRequiredWorkRecovery item.authorityRole then
                            jp_required_work_slice_progress_forget item.generation item.commitOrdinal
                        jpRemoveDeclaredEvaluatorContinuationsForJob item.commitOrdinal
                        jpRemoveActiveWorkTiming item.commitOrdinal
                        CompilerConsoleHud88.retryTerminalClosure ()
                        return transactionReceipt.semanticMutationApplied
                | _ ->
                    return raise (PartEvalTypeError([], "unstarted terminal retirement requires one queued transition and no suspended continuation"))
            }

        let jpFailureDeliveryOwnershipText = function
            | JpFailureDeliveryAcquired -> "Acquired"
            | JpFailureDeliveryAlreadyTerminal terminal ->
                "AlreadyTerminal(" + CompilerKernelV2.WorkTerminalDispositionOps.text terminal + ")"
            | JpFailureDeliveryLostTerminalRace terminal ->
                "LostTerminalRace(" + CompilerKernelV2.WorkTerminalDispositionOps.text terminal + ")"

        let jp_fail_work_item ownerPhase request failure (item:JpWorkItem) : Job<unit> =
            job {
                let failureRef = jpWorkResultRef (JpWorkSpecializationFailed failure)
                let preexistingTerminal =
                    JpSpecializationWorklistAuthority.tryTerminalDisposition item.workNode
                let deliveryOwnership =
                    match preexistingTerminal with
                    | Some terminal -> JpFailureDeliveryAlreadyTerminal terminal
                    | None ->
                        JpSpecializationWorklistAuthority.fail item.workNode failureRef
                        match JpSpecializationWorklistAuthority.tryTerminalDisposition item.workNode with
                        | Some (CompilerKernelV2.WorkTerminalFailed acceptedFailureRef)
                            when acceptedFailureRef = failureRef -> JpFailureDeliveryAcquired
                        | Some terminal -> JpFailureDeliveryLostTerminalRace terminal
                        | None ->
                            invalidOp
                                ("specialization failure did not reach a terminal state: "
                                 + CompilerIdentityKernel.ContentDigest.text item.workNode.nodeRef)
                match deliveryOwnership with
                | JpFailureDeliveryAcquired ->
                    do!
                        item.cancel request
                        |> CompilerKernelV2.CompilerRuntimeKernel.toJob
                    let! runningWork = jp_start_work_for_terminal item
                    let! _ =
                        jp_complete_work_item
                            item
                            runningWork
                            (JpWorkSpecializationFailed failure)
                            0L
                            None
                    return ()
                | JpFailureDeliveryAlreadyTerminal terminal
                | JpFailureDeliveryLostTerminalRace terminal ->
                    match ownerPhase with
                    | JpFailureDeliveryUnstartedOwner ->
                        let! semanticMutationApplied =
                            jp_retire_terminal_unstarted_admission terminal item
                        let occurrenceCount, shouldEmit =
                            DiagJson.sparseLogDecision
                                ("jp_failure_delivery_terminal_owner_retired_unstarted|"
                                 + CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                                 + "|" + CompilerKernelV2.WorkTerminalDispositionOps.text terminal)
                                64L
                        if shouldEmit then
                            DiagJson.emit (
                                FastRuntimeFormat.format
                                    "{\"kind\":\"jp_failure_delivery_terminal_owner_retired_unstarted\",\"work_unit_id\":%s,\"failure_ref\":%s,\"delivery_ownership_du\":%s,\"existing_terminal_du\":%s,\"body_restarted\":false,\"semantic_completion_credit\":%b,\"worker_replacement_authority\":false,\"occurrence_count\":%d,\"authority\":\"unstarted_failure_owner_retires_against_canonical_terminal\",\"next\":\"continue_draining_with_terminal_owner_credit_returned\"}"
                                    [| box (DiagJson.esc (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text failureRef)); box (DiagJson.esc (jpFailureDeliveryOwnershipText deliveryOwnership)); box (DiagJson.esc (CompilerKernelV2.WorkTerminalDispositionOps.text terminal)); box semanticMutationApplied; box occurrenceCount |])
                        return ()
                    | JpFailureDeliveryWorkerOwner ->
                        let occurrenceCount, shouldEmit =
                            DiagJson.sparseLogDecision
                                ("jp_failure_delivery_terminal_worker_owner_deferred|"
                                 + CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                                 + "|" + CompilerKernelV2.WorkTerminalDispositionOps.text terminal)
                                64L
                        if shouldEmit then
                            DiagJson.emit (
                                FastRuntimeFormat.format
                                    "{\"kind\":\"jp_failure_delivery_terminal_worker_owner_deferred\",\"work_unit_id\":%s,\"failure_ref\":%s,\"delivery_ownership_du\":%s,\"existing_terminal_du\":%s,\"body_restarted\":false,\"semantic_completion_credit\":false,\"worker_replacement_authority\":false,\"occurrence_count\":%d,\"authority\":\"running_owner_must_retire_at_worker_safe_point\",\"next\":\"preserve_running_owner_retirement_protocol\"}"
                                    [| box (DiagJson.esc (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text failureRef)); box (DiagJson.esc (jpFailureDeliveryOwnershipText deliveryOwnership)); box (DiagJson.esc (CompilerKernelV2.WorkTerminalDispositionOps.text terminal)); box occurrenceCount |])
                        return ()
            }

        let jpCancellationDeliveryOwnershipText = function
            | JpCancellationDeliveryAcquired -> "Acquired"
            | JpCancellationDeliveryAlreadyTerminal terminal ->
                "AlreadyTerminal(" + CompilerKernelV2.WorkTerminalDispositionOps.text terminal + ")"
            | JpCancellationDeliveryLostTerminalRace terminal ->
                "LostTerminalRace(" + CompilerKernelV2.WorkTerminalDispositionOps.text terminal + ")"

        let jp_cancel_work_item request (item:JpWorkItem) : Job<unit> =
            job {
                let reasonId = jpWorkCancellationRequestReasonId request
                let reason = CompilerKernelV2.OperationalReasonIdOps.text reasonId
                let cancellationRef =
                    match request with
                    | JpQueueBackpressureCancellation(_, requestCancellationRef) -> requestCancellationRef
                    | _ ->
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-specialization-cancelled"
                            (CompilerIdentityKernel.ContentDigest.text item.workNode.nodeRef + "|reason=" + reason)
                let cancellation =
                    match request with
                    | JpGenerationScopeCancellation _ -> JpGenerationCancellation(reasonId, cancellationRef)
                    | JpDuplicateAdmissionLocalCancellation _ -> JpDuplicateAdmissionCancellation cancellationRef
                    | JpQueueBackpressureCancellation _ -> JpQueueBackpressureWorkCancellation(reasonId, cancellationRef)
                    | JpRejectedAdmissionCancellation _
                    | JpHostRequestedCancellation _ -> JpHostCancellation(reasonId, cancellationRef)
                let preexistingTerminal =
                    JpSpecializationWorklistAuthority.tryTerminalDisposition item.workNode
                let deliveryOwnership =
                    match preexistingTerminal with
                    | Some terminal -> JpCancellationDeliveryAlreadyTerminal terminal
                    | None ->
                        JpSpecializationWorklistAuthority.cancel item.workNode cancellationRef
                        match JpSpecializationWorklistAuthority.tryTerminalDisposition item.workNode with
                        | Some (CompilerKernelV2.WorkTerminalCancelled acceptedCancellationRef)
                            when acceptedCancellationRef = cancellationRef -> JpCancellationDeliveryAcquired
                        | Some terminal -> JpCancellationDeliveryLostTerminalRace terminal
                        | None ->
                            invalidOp
                                ("specialization cancellation did not reach a terminal state: "
                                 + CompilerIdentityKernel.ContentDigest.text item.workNode.nodeRef)
                match deliveryOwnership with
                | JpCancellationDeliveryAcquired ->
                    do!
                        item.cancel request
                        |> CompilerKernelV2.CompilerRuntimeKernel.toJob
                    let! runningWork = jp_start_work_for_terminal item
                    let! _ =
                        jp_complete_work_item
                            item
                            runningWork
                            (JpWorkSpecializationCancelled cancellation)
                            0L
                            None
                    return ()
                | JpCancellationDeliveryAlreadyTerminal terminal
                | JpCancellationDeliveryLostTerminalRace terminal ->
                    let! semanticMutationApplied =
                        jp_retire_terminal_unstarted_admission terminal item
                    let occurrenceCount, shouldEmit =
                        DiagJson.sparseLogDecision
                            ("jp_cancellation_delivery_terminal_owner_retired_unstarted|"
                             + CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                             + "|" + CompilerKernelV2.WorkTerminalDispositionOps.text terminal)
                            64L
                    if shouldEmit then
                        DiagJson.emit (
                            FastRuntimeFormat.format
                                "{\"kind\":\"jp_cancellation_delivery_terminal_owner_retired_unstarted\",\"work_unit_id\":%s,\"cancellation_ref\":%s,\"delivery_ownership_du\":%s,\"existing_terminal_du\":%s,\"body_restarted\":false,\"semantic_completion_credit\":%b,\"worker_replacement_authority\":false,\"occurrence_count\":%d,\"authority\":\"unstarted_cancellation_owner_retires_against_canonical_terminal\",\"next\":\"continue_draining_with_terminal_owner_credit_returned\"}"
                                [| box (DiagJson.esc (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text cancellationRef)); box (DiagJson.esc (jpCancellationDeliveryOwnershipText deliveryOwnership)); box (DiagJson.esc (CompilerKernelV2.WorkTerminalDispositionOps.text terminal)); box semanticMutationApplied; box occurrenceCount |])
                    return ()
            }

        // Generation teardown is structured: cancel queued children, await exact-once
        // retirement of every admitted work unit in G, then clear G's caches.  G+1 may
        // exist, but no table is cleared while G still owns work.
        register_jp_dict_clear_callback (fun () ->
            let closingGeneration = max 0L (CacheGeneration.current() - 1L)
            let retained = ResizeArray<JpWorkItem>()
            let mutable drainingGeneration = true
            while drainingGeneration do
                match jpSpecializationQueueTryRemoveAny () with
                | JpSpecializationQueueRemoved(queued, _) ->
                    if queued.generation <= closingGeneration then
                        startHopacJob (jp_cancel_work_item (JpGenerationScopeCancellation (CompilerKernelV2.OperationalReasonIdOps.create "generation_scope_closing")) queued)
                    else
                        retained.Add queued
                | JpSpecializationQueueEmpty -> drainingGeneration <- false
            for item in retained do
                match jpSpecializationQueueEnqueue item with
                | JpSpecializationQueueAdmitted _ -> ()
                | disposition ->
                    invalidOp ("retained generation work could not be re-enqueued: " + jpSpecializationQueueAdmissionText disposition)
            startHopacJob (job {
                let! closeReceipt = jp_generation_scope_close closingGeneration JpGenerationScopeCacheInvalidation
                // Retained causal evidence survives generation teardown. It is
                // rendered as stale until an explicit new-compilation boundary clears it.
                let promiseRetirement = JpPromiseProducerAuthority.retireThrough closingGeneration
                let runtimeEffectWitnessesRetired = JpRuntimeEffectWitnessAuthority.retireGeneration closingGeneration
                let specializationNodesRetired = JpSpecializationWorklistAuthority.retireGeneration closingGeneration
                let methodOwnerCountBefore, c0, t0 = join_point_method.Count, join_point_closure.Count, join_point_type.Count
                let ex0 = 0
                let nextGeneration = CacheGeneration.current()
                let mutable methodReadyCellsRetained = 0
                let mutable methodCellsDropped = 0
                let mutable methodCancelledCellsDropped = 0
                let mutable methodFailedCellsDropped = 0
                let mutable methodPendingCellsDropped = 0
                let mutable methodOwnersRetained = 0
                for KeyValue(ownerKey, (cells, hashConsTable, _)) in join_point_method do
                    let retained =
                        System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<RData [] * Ty [] * Ty>, Hopac.IVar<JpMethodBodyCellPayload>>(HashIdentity.Reference)
                    for KeyValue(key, cell) in cells do
                        let cell : Hopac.IVar<JpMethodBodyCellPayload> = cell
                        let payloadReadyForRetention =
                            if cell.Full then
                                match Hopac.IVar.Now.get cell with
                                | JpMethodBodyCellReadyPayload _ -> true
                                | JpMethodBodyCellCancelledPayload _ ->
                                    methodCancelledCellsDropped <- methodCancelledCellsDropped + 1
                                    false
                                | JpMethodBodyCellFailedPayload _ ->
                                    methodFailedCellsDropped <- methodFailedCellsDropped + 1
                                    false
                            else
                                methodPendingCellsDropped <- methodPendingCellsDropped + 1
                                false
                        if payloadReadyForRetention && not (SuspectCache.isSuspect key) then
                            if retained.TryAdd(key, cell) then
                                methodReadyCellsRetained <- methodReadyCellsRetained + 1
                        else
                            methodCellsDropped <- methodCellsDropped + 1
                    if retained.IsEmpty then
                        let mutable removedOwner = Unchecked.defaultof<_>
                        join_point_method.TryRemove(ownerKey, &removedOwner) |> ignore
                    else
                        join_point_method.[ownerKey] <- (retained, hashConsTable, nextGeneration)
                        methodOwnersRetained <- methodOwnersRetained + 1
                DiagJson.emit (
                    FastRuntimeFormat.format
                        "{\"kind\":\"jp_method_generation_payload_retention_summary\",\"closing_generation\":%d,\"next_generation\":%d,\"ready_payloads_retained\":%d,\"cancelled_payloads_dropped\":%d,\"failed_payloads_dropped\":%d,\"pending_cells_dropped\":%d,\"total_cells_dropped\":%d,\"authority\":\"owner_local_method_cell_payload\",\"next\":\"retain_only_ready_payloads_across_generation\"}"
                        [| box closingGeneration; box nextGeneration; box methodReadyCellsRetained; box methodCancelledCellsDropped; box methodFailedCellsDropped; box methodPendingCellsDropped; box methodCellsDropped |])
                ignore (jpObserverDrain JpObserverDrainBeforeGenerationRetirement JpObserverDrainCacheInvalidation)
                let closurePendingBefore = jp_closure_pending_cells.Count
                let closureCompletedBefore = jp_closure_completed_cells.Count
                join_point_closure.Clear()
                jp_closure_pending_cells.Clear()
                jp_closure_completed_cells.Clear()
                join_point_type.Clear()
                let mutable edi = Unchecked.defaultof<_>
                let mutable drained = 0
                while jp_exns.TryDequeue(&edi) do drained <- drained + 1
                jp_method_pending_cells.Clear()
                jp_method_declared_interfaces.Clear()
                DiagJson.emitRecord
                    ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpGenerationScopeClosed
                       generation = closingGeneration
                       close_reason_du = "CacheInvalidation"
                       close_receipt_ref = CompilerIdentityKernel.ContentDigest.text closeReceipt
                       promise_bindings_retired = promiseRetirement.retiredBindings
                       promise_bindings_retained = promiseRetirement.retainedBindings
                       promise_retirement_ref = CompilerIdentityKernel.ContentDigest.text promiseRetirement.retirementRef
                       runtime_effect_witnesses_retired = runtimeEffectWitnessesRetired
                       specialization_nodes_retired = specializationNodesRetired
                       method_owner_tables_before = methodOwnerCountBefore
                       method_owner_tables_retained = methodOwnersRetained
                       method_ready_cells_retained = methodReadyCellsRetained
                       method_cells_dropped = methodCellsDropped
                       method_memo_policy_du = "RetainExactReadyNonSuspectAcrossGeneration"
                       closure_cells_cleared = c0
                       type_cells_cleared = t0
                       exception_cells_cleared = ex0
                       exception_queue_drained = drained
                       authority = "generation_scope_actor_plus_exact_promise_binding_authority_plus_generation_stable_ready_memo"
                       next = "admit_next_generation_without_recomputing_ready_methods" }
                     : JpGenerationScopeClosedEvent)
            }))

        // [HOPAC-PEVAL-245-001] Stopwatch for per-peval timing (avoid forward refs).
        let peval_sw = System.Diagnostics.Stopwatch.StartNew()
        // MIGRATION: install the peval-relative clock used by out-of-scope replay helpers
        // when they refresh jp_last_progress_ms after real semantic_root_complete returns.
        jp_progress_clock <- fun () -> peval_sw.ElapsedMilliseconds
        // The JP progress ledger is derived synchronized state. Pending, totals,
        // progress start and worker activity are observed as one lock-protected snapshot.
        let jpWorkLedgerInitial =
            { pending = CompilerKernelV2.Measured.zero<CompilerKernelV2.NodeCountUnit>
              totalEnqueued = CompilerKernelV2.Measured.zero<CompilerKernelV2.NodeCountUnit>
              lastEnqueueAt = CompilerKernelV2.Measured.zero<CompilerKernelV2.MonotonicTimeUnit>
              frozenTotal = CompilerKernelV2.Measured.zero<CompilerKernelV2.NodeCountUnit>
              totalDone = CompilerKernelV2.Measured.zero<CompilerKernelV2.NodeCountUnit>
              progressStarted = false
              workerActive = CompilerKernelV2.Measured.zero<CompilerKernelV2.WorkerCountUnit>
              jobId = CompilerKernelV2.Measured.zero<CompilerKernelV2.RevisionOrdinalUnit>
              totalStarted = CompilerKernelV2.Measured.zero<CompilerKernelV2.NodeCountUnit> }

        // The progress/work-count ledger is derived synchronous state, not a
        // scheduler actor.  It is read from inside Hopac jobs, so routing a read
        // through a Hopac mailbox and Hopac.run would recursively enter the
        // scheduler.  A short critical section provides the same exact ordering
        // without creating a blocking scheduler boundary.
        let jpWorkLedgerGate = obj()
        let mutable jpWorkLedgerState = jpWorkLedgerInitial

        let ensureJpWorkLedgerAvailable () =
            CompilerRuntimeActivation.requireInProcessEntered "jp_work_ledger"

        let jpWorkLedgerRead () =
            ensureJpWorkLedgerAvailable()
            lock jpWorkLedgerGate (fun () -> jpWorkLedgerState)

        let jpWorkLedgerUpdate update =
            ensureJpWorkLedgerAvailable()
            lock jpWorkLedgerGate (fun () ->
                let previous = jpWorkLedgerState
                let next = update previous
                jpWorkLedgerState <- next
                previous, next)

        let jpNodeCount value = CompilerKernelV2.Measured.create<CompilerKernelV2.NodeCountUnit> "jpNodeCount" (max 0L value)
        let jpWorkerCount value = CompilerKernelV2.Measured.create<CompilerKernelV2.WorkerCountUnit> "jpWorkerCount" (max 0L value)
        let jpRevisionOrdinal value = CompilerKernelV2.Measured.create<CompilerKernelV2.RevisionOrdinalUnit> "jpRevisionOrdinal" (max 0L value)
        let jpMonotonicTimestamp value = CompilerKernelV2.Measured.create<CompilerKernelV2.MonotonicTimeUnit> "jpMonotonicTimestamp" (max 0L value)
        let jpMeasuredValue value = CompilerKernelV2.Measured.value value

        let jpWorkLedgerExchangePending value =
            jpWorkLedgerUpdate (fun x -> { x with pending = jpNodeCount value }) |> fst |> fun x -> jpMeasuredValue x.pending

        let jpWorkLedgerIncrementPending () =
            jpWorkLedgerUpdate (fun x -> { x with pending = CompilerKernelV2.Measured.increment x.pending }) |> snd |> fun x -> jpMeasuredValue x.pending

        let jpWorkLedgerDecrementPending () =
            jpWorkLedgerUpdate (fun x -> { x with pending = CompilerKernelV2.Measured.subtractFloor x.pending (jpNodeCount 1L) }) |> snd |> fun x -> jpMeasuredValue x.pending

        let jpWorkLedgerIncrementEnqueued () =
            jpWorkLedgerUpdate (fun x -> { x with totalEnqueued = CompilerKernelV2.Measured.increment x.totalEnqueued }) |> snd |> fun x -> jpMeasuredValue x.totalEnqueued

        let jpWorkLedgerExchangeLastEnqueueMs value =
            jpWorkLedgerUpdate (fun x -> { x with lastEnqueueAt = jpMonotonicTimestamp value }) |> fst |> fun x -> jpMeasuredValue x.lastEnqueueAt

        let jpWorkLedgerExchangeFrozenTotal value =
            jpWorkLedgerUpdate (fun x -> { x with frozenTotal = jpNodeCount value }) |> fst |> fun x -> jpMeasuredValue x.frozenTotal

        let jpWorkLedgerCompareExchangeFrozenTotal value comparand =
            ensureJpWorkLedgerAvailable()
            lock jpWorkLedgerGate (fun () ->
                let previous = jpWorkLedgerState.frozenTotal
                if previous = jpNodeCount comparand then
                    jpWorkLedgerState <- { jpWorkLedgerState with frozenTotal = jpNodeCount value }
                jpMeasuredValue previous)

        let jpWorkLedgerExchangeDone value =
            jpWorkLedgerUpdate (fun x -> { x with totalDone = jpNodeCount value }) |> fst |> fun x -> jpMeasuredValue x.totalDone

        let jpWorkLedgerIncrementDone () =
            jpWorkLedgerUpdate (fun x -> { x with totalDone = CompilerKernelV2.Measured.increment x.totalDone }) |> snd |> fun x -> jpMeasuredValue x.totalDone

        let jpWorkLedgerTryStartProgress () =
            ensureJpWorkLedgerAvailable()
            lock jpWorkLedgerGate (fun () ->
                let alreadyStarted = jpWorkLedgerState.progressStarted
                if not alreadyStarted then
                    jpWorkLedgerState <- { jpWorkLedgerState with progressStarted = true }
                alreadyStarted)

        let jpWorkLedgerIncrementWorkerActive () =
            jpWorkLedgerUpdate (fun x -> { x with workerActive = CompilerKernelV2.Measured.increment x.workerActive }) |> snd |> fun x -> jpMeasuredValue x.workerActive

        let jpWorkLedgerDecrementWorkerActive () =
            jpWorkLedgerUpdate (fun x -> { x with workerActive = CompilerKernelV2.Measured.subtractFloor x.workerActive (jpWorkerCount 1L) }) |> snd |> fun x -> jpMeasuredValue x.workerActive

        let jpWorkLedgerIncrementJobId () =
            jpWorkLedgerUpdate (fun x -> { x with jobId = CompilerKernelV2.Measured.increment x.jobId }) |> snd |> fun x -> jpMeasuredValue x.jobId

        let jpWorkLedgerIncrementStarted () =
            jpWorkLedgerUpdate (fun x -> { x with totalStarted = CompilerKernelV2.Measured.increment x.totalStarted }) |> snd |> fun x -> jpMeasuredValue x.totalStarted

        // MIGRATION: track active JP work-item runtimes so the progress bar can explain long "stalls"
        // (e.g. done stays constant while a single heavy join-point specialization is running).
        let jp_active_jobs : System.Collections.Concurrent.ConcurrentDictionary<int64,int64> =
            System.Collections.Concurrent.ConcurrentDictionary<int64,int64>()
        let jp_active_job_sites : System.Collections.Concurrent.ConcurrentDictionary<int64,CompilerIdentityKernel.WorkSiteId> =
            System.Collections.Concurrent.ConcurrentDictionary<int64,CompilerIdentityKernel.WorkSiteId>()
        let jp_job_admitted_at_ms : System.Collections.Concurrent.ConcurrentDictionary<int64,int64> =
            System.Collections.Concurrent.ConcurrentDictionary<int64,int64>()

        let jpWorkAdmissionTimingRegister jobId admittedAtMs =
            jp_job_admitted_at_ms.[jobId] <- max 0L admittedAtMs

        let jpWorkAdmissionTimingRead jobId fallback =
            let mutable admittedAtMs = 0L
            if jp_job_admitted_at_ms.TryGetValue(jobId, &admittedAtMs) then admittedAtMs
            else fallback

        let jpWorkAdmissionTimingRemove jobId =
            let mutable ignored = 0L
            jp_job_admitted_at_ms.TryRemove(jobId, &ignored) |> ignore

        // Execution identity is intentionally peval-instance-local. Moving this AsyncLocal to
        // module scope couples independent execution carriers and regresses general JPClosure liveness.
        let jp_current_work_identity = System.Threading.AsyncLocal<int64>()
        let jpCurrentWorkJobId () = max 0L jp_current_work_identity.Value
        let jp_current_operation_counter = System.Threading.AsyncLocal<int64>()
        let jp_current_declared_recovery_slice_multiplier = System.Threading.AsyncLocal<int>()
        let jp_current_declared_term_depth = System.Threading.AsyncLocal<int>()
        let jp_current_declared_safe_continuation_term_depth = System.Threading.AsyncLocal<int>()
        let jp_current_declared_safe_continuation = System.Threading.AsyncLocal<JpDeclaredSafeContinuation>()
        let jp_current_declared_tail_result_bridge = System.Threading.AsyncLocal<JpDeclaredTailResultBridgeScope>()
        let jp_current_declared_direct_resume_quarantine = System.Threading.AsyncLocal<bool>()
        let jp_current_declared_root_resume_quarantine = System.Threading.AsyncLocal<bool>()
        let jp_current_declared_bounded_slice_quarantine = System.Threading.AsyncLocal<bool>()
        let jp_current_declared_mixed_resume_completed_job_id = System.Threading.AsyncLocal<int64>()
        let jp_current_declared_mixed_resume_completed_root_node_id = System.Threading.AsyncLocal<int>()
        let jp_current_declared_mixed_resume_completed_root_identity = System.Threading.AsyncLocal<obj>()

        let jpActiveChildWaitBegin waiterIdentity nowMs childWait =
            let (JpWaiterWorkIdentity jobId) = waiterIdentity
            if jobId > 0L then
                let mutable timing = Unchecked.defaultof<JpActiveWorkTiming>
                if jp_active_job_timings.TryGetValue(jobId, &timing) then
                    lock timing.timingGate (fun () ->
                        match timing.activeChildWait with
                        | JpActiveChildWaitRunning _ -> ()
                        | JpActiveChildWaitIdle ->
                            timing.activeChildWait <- JpActiveChildWaitRunning(nowMs, childWait)
                            timing.childWaitCount <- timing.childWaitCount + 1)
                JpActiveWorkIdentityAuthority.beginDependency
                    jobId
                    nowMs
                    childWait.producerWorkId
                    childWait.producerBindingId
                    childWait.promiseRef
                    childWait.waitRef
                    childWait.dispositionId

        let jpActiveChildWaitEnd waiterIdentity nowMs =
            let (JpWaiterWorkIdentity jobId) = waiterIdentity
            if jobId > 0L then
                let mutable timing = Unchecked.defaultof<JpActiveWorkTiming>
                if jp_active_job_timings.TryGetValue(jobId, &timing) then
                    lock timing.timingGate (fun () ->
                        match timing.activeChildWait with
                        | JpActiveChildWaitRunning(startedAtMs, _) ->
                            timing.blockedOnChildCompletedMs <-
                                timing.blockedOnChildCompletedMs + max 0L (nowMs - startedAtMs)
                            timing.activeChildWait <- JpActiveChildWaitIdle
                        | JpActiveChildWaitIdle -> ())
                JpActiveWorkIdentityAuthority.endDependency jobId

        let jpActiveJobsExactAcyclicWaitCount nowMs (jobs:System.Collections.Generic.KeyValuePair<int64,int64> array) =
            jobs
            |> Array.sumBy (fun job ->
                match jpActiveWorkTimingSnapshot job.Key nowMs with
                | Some(_, _, _, _, _, _, _, _, _, _, _, _, _, _, JpActiveChildWaitRunning(_, childWait)) ->
                    match childWait.disposition with
                    | JpActiveChildWaitExactAcyclic -> 1
                    | JpActiveChildWaitExactCycle
                    | JpActiveChildWaitProducerUnavailable -> 0
                | _ -> 0)

        let jpActiveJobsDelegatedToExactAcyclicWait nowMs (jobs:System.Collections.Generic.KeyValuePair<int64,int64> array) =
            jobs.Length > 0
            && jpActiveJobsExactAcyclicWaitCount nowMs jobs = jobs.Length

        let jpCurrentWorkIdentity () =
            let value = jpCurrentWorkJobId ()
            if value > 0L then Some (JpWaiterWorkIdentity value) else None

        let jpDeclaredBodyRecoverySliceMultiplierForItem (item:JpWorkItem) =
            if DiagJson.terminalFailureExitRequestedNow() then
                1
            elif item.workNode.intent = JpVerifyDeclaredMethodBody then
                let nowMs = max 0L (jp_progress_clock())
                let lifetimeAgeMs, observedOperations, operationIdleMs =
                    match jpDeclaredBodyLifetimeSnapshot item.commitOrdinal nowMs with
                    | Some(ageMs, operations, idleMs, _) -> ageMs, operations, idleMs
                    | None -> 0L, 0L, 0L
                let semanticQueueDepth = jpSpecializationSemanticQueueDepth ()
                let recoveryPolicy =
                    jpDeclaredBodyRecoverySlicePolicyFor
                        (jp_declared_body_finish_through_owns item.commitOrdinal)
                        semanticQueueDepth
                        lifetimeAgeMs
                        observedOperations
                        operationIdleMs
                let multiplier = jpDeclaredBodyRecoverySliceMultiplier recoveryPolicy
                if multiplier > 1 then
                    let workUnitIdText = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                    let policyText = jpDeclaredBodyRecoverySlicePolicyText recoveryPolicy
                    let occurrence, shouldEmit =
                        DiagJson.sparseLogDecision
                            ("jp_declared_body_recovery_slice_selected|" + workUnitIdText + "|" + policyText)
                            64L
                    if shouldEmit then
                        DiagJson.emit (
                            FastRuntimeFormat.format
                                "{\"kind\":\"jp_declared_body_recovery_slice_selected\",\"work_unit_id\":%s,\"policy_du\":%s,\"multiplier\":%d,\"lifetime_age_ms\":%d,\"observed_operations\":%d,\"operation_idle_ms\":%d,\"semantic_queue_depth\":%d,\"occurrence_count\":%d,\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"authority\":\"structural_declared_body_lifetime_progress_plus_queue_pressure\",\"next\":\"run_bounded_slice_without_changing_type_or_carrier_authority\"}"
                                [| box (DiagJson.esc workUnitIdText); box (DiagJson.esc policyText); box multiplier; box lifetimeAgeMs; box observedOperations; box operationIdleMs; box semanticQueueDepth; box occurrence |])
                multiplier
            else
                1

        let jpCurrentDeclaredBodySliceContext () =
            if jp_current_declared_bounded_slice_quarantine.Value then None
            else
                match jpCurrentWorkIdentity () with
                | Some (JpWaiterWorkIdentity jobId) ->
                    let mutable item = Unchecked.defaultof<JpWorkItem>
                    if jp_active_work_items.TryGetValue(jobId, &item) then
                        match item.workNode.intent, item.executionPolicy with
                        | JpVerifyDeclaredMethodBody, JpWorkExecutionBoundedSlice(_, budget) ->
                            let baseMaxOperations = max 1 (JpWorkSliceBudgetOps.maxOperations budget)
                            let checkpointInterval = max 1 (JpWorkSliceBudgetOps.checkpointInterval budget)
                            let recoverySliceMultiplier =
                                max 1 jp_current_declared_recovery_slice_multiplier.Value
                            let maxOperations =
                                baseMaxOperations * recoverySliceMultiplier
                            Some (JpDeclaredBodySliceContext(jobId, maxOperations, checkpointInterval))
                        | _ -> None
                    else None
                | None -> None

        let jpCurrentDeclaredDirectResumeSliceContext () =
            if jp_current_declared_direct_resume_quarantine.Value then None
            else jpCurrentDeclaredBodySliceContext ()

        let jpWithDeclaredDirectResumeQuarantine run =
            let previousDirect = jp_current_declared_direct_resume_quarantine.Value
            let previousRoot = jp_current_declared_root_resume_quarantine.Value
            let previousSlice = jp_current_declared_bounded_slice_quarantine.Value
            jp_current_declared_direct_resume_quarantine.Value <- true
            jp_current_declared_root_resume_quarantine.Value <- true
            jp_current_declared_bounded_slice_quarantine.Value <- true
            try run()
            finally
                jp_current_declared_direct_resume_quarantine.Value <- previousDirect
                jp_current_declared_root_resume_quarantine.Value <- previousRoot
                jp_current_declared_bounded_slice_quarantine.Value <- previousSlice

        let jpWithDeclaredDirectResumeOnlyQuarantine run =
            let previousDirect = jp_current_declared_direct_resume_quarantine.Value
            let previousRoot = jp_current_declared_root_resume_quarantine.Value
            jp_current_declared_direct_resume_quarantine.Value <- true
            jp_current_declared_root_resume_quarantine.Value <- true
            try run()
            finally
                jp_current_declared_direct_resume_quarantine.Value <- previousDirect
                jp_current_declared_root_resume_quarantine.Value <- previousRoot

        let jpWithDeclaredRootResumeOnlyQuarantine run =
            let previousRoot = jp_current_declared_root_resume_quarantine.Value
            jp_current_declared_root_resume_quarantine.Value <- true
            try run()
            finally jp_current_declared_root_resume_quarantine.Value <- previousRoot

        let jpCurrentDeclaredSafeContinuation () =
            let value = jp_current_declared_safe_continuation.Value
            if obj.ReferenceEquals(value, null) then None else Some value

        let jpSetCurrentDeclaredSafeContinuationAtDepth safeContinuation termDepth =
            let ownership = function
                | JpDeclaredApplySafeContinuation(jobId, _, continuationRef)
                | JpDeclaredLetSafeContinuation(jobId, _, continuationRef)
                | JpDeclaredSequenceSafeContinuation(jobId, _, continuationRef)
                | JpDeclaredBinaryNumericSafeContinuation(jobId, _, continuationRef)
                | JpDeclaredRecordTypeFoldBackSafeContinuation(jobId, _, continuationRef) -> jobId, continuationRef
            let previous = jpCurrentDeclaredSafeContinuation ()
            // Retain the next execution root before releasing the previous one so a
            // concurrent prune can never observe a zero-owner window during a safe-PC
            // handoff. If both values name the same continuation, this is balanced.
            match safeContinuation with
            | Some value ->
                let jobId, continuationRef = ownership value
                jpRetainDeclaredActiveResumeRoot jobId continuationRef
            | None -> ()
            match previous with
            | Some value ->
                let jobId, continuationRef = ownership value
                jpReleaseDeclaredActiveResumeRoot jobId continuationRef
            | None -> ()
            match safeContinuation with
            | Some value ->
                jp_current_declared_safe_continuation.Value <- value
                jp_current_declared_safe_continuation_term_depth.Value <- max 0 termDepth
            | None ->
                jp_current_declared_safe_continuation.Value <- Unchecked.defaultof<JpDeclaredSafeContinuation>
                jp_current_declared_safe_continuation_term_depth.Value <- 0

        let jpSetCurrentDeclaredSafeContinuation safeContinuation =
            jpSetCurrentDeclaredSafeContinuationAtDepth safeContinuation jp_current_declared_term_depth.Value

        let jpDeclaredSafeContinuationJobId = function
            | JpDeclaredApplySafeContinuation(jobId, _, _)
            | JpDeclaredLetSafeContinuation(jobId, _, _)
            | JpDeclaredSequenceSafeContinuation(jobId, _, _)
            | JpDeclaredBinaryNumericSafeContinuation(jobId, _, _)
            | JpDeclaredRecordTypeFoldBackSafeContinuation(jobId, _, _) -> jobId

        let jpDeclaredSafeContinuationRef = function
            | JpDeclaredApplySafeContinuation(_, _, continuationRef)
            | JpDeclaredLetSafeContinuation(_, _, continuationRef)
            | JpDeclaredSequenceSafeContinuation(_, _, continuationRef)
            | JpDeclaredBinaryNumericSafeContinuation(_, _, continuationRef)
            | JpDeclaredRecordTypeFoldBackSafeContinuation(_, _, continuationRef) -> continuationRef

        let jpDeclaredSafeContinuationNodeId = function
            | JpDeclaredApplySafeContinuation(_, nodeId, _)
            | JpDeclaredLetSafeContinuation(_, nodeId, _)
            | JpDeclaredSequenceSafeContinuation(_, nodeId, _)
            | JpDeclaredBinaryNumericSafeContinuation(_, nodeId, _)
            | JpDeclaredRecordTypeFoldBackSafeContinuation(_, nodeId, _) -> nodeId

        let jpDeclaredSafeContinuationKindText = function
            | JpDeclaredApplySafeContinuation _ -> "Apply"
            | JpDeclaredLetSafeContinuation _ -> "Let"
            | JpDeclaredSequenceSafeContinuation _ -> "Sequence"
            | JpDeclaredBinaryNumericSafeContinuation _ -> "BinaryNumeric"
            | JpDeclaredRecordTypeFoldBackSafeContinuation _ -> "RecordTypeFoldBack"

        let jpDeclaredBodyResumePointForSafeContinuation fallback safeContinuation =
            let continuationRef = jpDeclaredSafeContinuationRef safeContinuation
            let authority =
                JpDeclaredResumePointSafeContinuationSnapshot (JpWorkContinuationRefOps.digest continuationRef)
            match safeContinuation, jpTryDeclaredResumeSnapshotByRef continuationRef with
            | JpDeclaredApplySafeContinuation _, Some (JpDeclaredApplyResumeSnapshot(_, continuation)) ->
                let resumePoint =
                    match continuation.stage with
                    | JpDeclaredApplyHeadPending -> JpDeclaredResumeApplyHead
                    | JpDeclaredApplyBeforeArgument -> JpDeclaredResumeApplyArgument
                    | JpDeclaredApplyArgumentReadyDispatchPending _ -> JpDeclaredResumeApplyDispatch
                resumePoint, authority
            | JpDeclaredLetSafeContinuation _, Some (JpDeclaredLetResumeSnapshot(_, continuation)) ->
                let resumePoint =
                    match continuation.stage with
                    | JpDeclaredLetBindingPending -> JpDeclaredResumeLetBinding
                    | JpDeclaredLetCheckpointReady
                    | JpDeclaredLetBodyPending -> JpDeclaredResumeLetBody
                resumePoint, authority
            | JpDeclaredSequenceSafeContinuation _, Some (JpDeclaredSequenceResumeSnapshot(_, continuation)) ->
                let resumePoint =
                    match continuation.stage with
                    | JpDeclaredSequenceFirstPending _ -> JpDeclaredResumeSequenceFirst
                    | JpDeclaredSequenceTailPending -> JpDeclaredResumeSequenceTail
                resumePoint, authority
            | JpDeclaredRecordTypeFoldBackSafeContinuation _, Some (JpDeclaredRecordTypeFoldBackResumeSnapshot(_, continuation)) ->
                let resumePoint =
                    match continuation.state with
                    | JpDeclaredRecordTypeFoldBackFolderPending _ -> JpDeclaredResumeFoldFolder
                    | JpDeclaredRecordTypeFoldBackInitialStatePending _ -> JpDeclaredResumeFoldInitialState
                    | JpDeclaredRecordTypeFoldBackRecordTypePending _ -> JpDeclaredResumeFoldRecordType
                    | JpDeclaredRecordTypeFoldBackFieldPending(_, _, _, nextFieldIndex, _) -> JpDeclaredResumeFoldField nextFieldIndex
                    | JpDeclaredRecordTypeFoldBackKeyApplied(_, _, _, nextFieldIndex, _, _) -> JpDeclaredResumeFoldKeyApplied nextFieldIndex
                    | JpDeclaredRecordTypeFoldBackTypeApplied(_, _, _, nextFieldIndex, _, _) -> JpDeclaredResumeFoldTypeApplied nextFieldIndex
                resumePoint, authority
            | _ -> fallback, JpDeclaredResumePointObservedPhase

        let jpCurrentDeclaredTailResultBridge () =
            let value = jp_current_declared_tail_result_bridge.Value
            if obj.ReferenceEquals(value, null) then None else Some value

        let jpSetCurrentDeclaredTailResultBridge bridgeScope =
            match bridgeScope with
            | Some value -> jp_current_declared_tail_result_bridge.Value <- value
            | None -> jp_current_declared_tail_result_bridge.Value <- Unchecked.defaultof<JpDeclaredTailResultBridgeScope>

        let jpWithDeclaredSafeContinuation safeContinuation run =
            let previous = jpCurrentDeclaredSafeContinuation ()
            let previousDepth = jp_current_declared_safe_continuation_term_depth.Value
            let previousBridge = jpCurrentDeclaredTailResultBridge ()
            jpSetCurrentDeclaredSafeContinuationAtDepth (Some safeContinuation) jp_current_declared_term_depth.Value
            // A new explicit continuation starts a new result topology. Tail-result bridges
            // from an outer continuation may not leak across this ownership boundary.
            jpSetCurrentDeclaredTailResultBridge None
            try run()
            finally
                jpSetCurrentDeclaredSafeContinuationAtDepth previous previousDepth
                jpSetCurrentDeclaredTailResultBridge previousBridge

        let jpWithCurrentDeclaredTailResultBridge
            (bridge:JpDeclaredTailResultBridgeId)
            run =
            let previousBridge = jpCurrentDeclaredTailResultBridge ()
            let installBridge () =
                let bridgePath =
                    match previousBridge with
                    | Some (JpDeclaredTailResultBridgeScope(path, _)) ->
                        JpDeclaredTailResultBridgeCompose(path, bridge)
                    | None -> JpDeclaredTailResultBridgeSingle bridge
                jpSetCurrentDeclaredTailResultBridge (
                    Some (JpDeclaredTailResultBridgeScope(bridgePath, jp_current_declared_term_depth.Value)))
                try run()
                finally jpSetCurrentDeclaredTailResultBridge previousBridge
            match jpCurrentDeclaredSafeContinuation (), jpDeclaredTailResultBridgeTransparency bridge with
            | Some _, _
            | None, JpDeclaredExpressionTransparentBridge ->
                installBridge ()
            | None, JpDeclaredStageLocalCarrierBridge ->
                // A root-level stage-local carrier is not the result of its enclosing expression.
                // Mask any outer root-tail proof while this child executes, then restore it.
                jpSetCurrentDeclaredTailResultBridge None
                try run()
                finally jpSetCurrentDeclaredTailResultBridge previousBridge

        let jpCurrentDeclaredContinuationScope jobId =
            let termDepth = max 0 jp_current_declared_term_depth.Value
            match jpCurrentDeclaredSafeContinuation () with
            | Some safeContinuation when jpDeclaredSafeContinuationJobId safeContinuation = jobId ->
                let continuationRef = jpDeclaredSafeContinuationRef safeContinuation
                let safeDepth = max 0 jp_current_declared_safe_continuation_term_depth.Value
                let depthDelta = max 0 (termDepth - safeDepth)
                if depthDelta <= 1 then JpDeclaredContinuationScopeDirect continuationRef
                else
                    match jpCurrentDeclaredTailResultBridge () with
                    | Some (JpDeclaredTailResultBridgeScope(bridgePath, installedAtTermDepth))
                        when termDepth = max 0 installedAtTermDepth + 1 ->
                        JpDeclaredContinuationScopeTailBridge(continuationRef, bridgePath, depthDelta)
                    | _ -> JpDeclaredContinuationScopeOpaque(Some continuationRef, depthDelta)
            | _ when termDepth <= 1 -> JpDeclaredContinuationScopeRoot
            | _ ->
                // True tail-result wrappers preserve the lexical root relation even when no
                // explicit safe continuation has been minted yet. Stage-local carriers are
                // deliberately excluded by the bridge transparency classifier above.
                match jpCurrentDeclaredTailResultBridge () with
                | Some (JpDeclaredTailResultBridgeScope(bridgePath, installedAtTermDepth))
                    when termDepth = max 0 installedAtTermDepth + 1
                         && jpDeclaredTailResultBridgePathIsExpressionTransparent bridgePath ->
                    let bridgePathText = jpDeclaredTailResultBridgePathText bridgePath
                    let bridgeOccurrence, shouldEmitBridge =
                        DiagJson.sparseLogDecision
                            ("jp_declared_root_tail_parent_projection|" + string jobId + "|" + bridgePathText)
                            64L
                    if shouldEmitBridge then
                        DiagJson.emit (
                            FastRuntimeFormat.format
                                "{\"kind\":\"jp_declared_root_tail_parent_projection\",\"work_job_id\":%d,\"term_depth\":%d,\"bridge_path_du\":%s,\"expression_transparent\":true,\"typed_parent_present\":true,\"ancestor_replay_hops\":0,\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"occurrence_count\":%d,\"authority\":\"typed_expression_tail_bridge_preserves_root_provenance_observation_only\",\"control_authority\":false,\"next\":\"key_descendant_as_root_without_ancestor_replay\"}"
                                [| box jobId; box termDepth; box (DiagJson.esc bridgePathText); box bridgeOccurrence |])
                    JpDeclaredContinuationScopeRoot
                | _ ->
                    // A singleton direct-resume execution root is the strongest live parent endpoint.
                    // Outside that narrow scope, the work item may still own an explicitly installed
                    // semantic resume target; preserve that typed endpoint across nested evaluator
                    // calls instead of degrading the descendant to Opaque(None). No nearest-snapshot
                    // or ancestor search is permitted: unavailable current ownership stays fail-closed.
                    let parentEndpoint = jpCurrentDeclaredParentEndpoint jobId
                    let parentEndpointText = jpDeclaredCurrentParentEndpointText parentEndpoint
                    let parentEndpointPresent =
                        match parentEndpoint with
                        | JpDeclaredParentEndpointUnavailable -> false
                        | JpDeclaredParentEndpointExecutionRoot _
                        | JpDeclaredParentEndpointInstalledResumeTarget _ -> true
                    let endpointOccurrence, shouldEmitEndpoint =
                        DiagJson.sparseLogDecision
                            ("jp_declared_current_parent_endpoint_projection|" + string jobId + "|" + parentEndpointText)
                            64L
                    if shouldEmitEndpoint then
                        DiagJson.emit (
                            FastRuntimeFormat.format
                                "{\"kind\":\"jp_declared_current_parent_endpoint_projection\",\"work_job_id\":%d,\"term_depth\":%d,\"parent_endpoint_du\":%s,\"typed_parent_present\":%b,\"ancestor_replay_hops\":0,\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"occurrence_count\":%d,\"authority\":\"current_execution_scope_parent_endpoint_observation_only\",\"control_authority\":false,\"next\":\"preserve_typed_parent_into_opaque_snapshot_or_remain_fail_closed\"}"
                                [| box jobId; box termDepth; box (DiagJson.esc parentEndpointText); box parentEndpointPresent; box endpointOccurrence |])
                    match parentEndpoint with
                    | JpDeclaredParentEndpointExecutionRoot continuationRef
                    | JpDeclaredParentEndpointInstalledResumeTarget continuationRef ->
                        JpDeclaredContinuationScopeOpaque(Some continuationRef, termDepth - 1)
                    | JpDeclaredParentEndpointUnavailable ->
                        JpDeclaredContinuationScopeOpaque(None, termDepth - 1)

        let jpTryCurrentDeclaredBodyContinuationRef jobId =
            match jpCurrentDeclaredContinuationScope jobId with
            | JpDeclaredContinuationScopeDirect continuationRef -> Some continuationRef
            | JpDeclaredContinuationScopeRoot
            | JpDeclaredContinuationScopeTailBridge _
            | JpDeclaredContinuationScopeOpaque _ -> None

        let jpDeclaredEvaluatorParentPcFor jobId =
            match jpCurrentDeclaredContinuationScope jobId with
            | JpDeclaredContinuationScopeDirect continuationRef -> JpDeclaredEvaluatorNestedPc continuationRef
            | JpDeclaredContinuationScopeRoot -> JpDeclaredEvaluatorRootPc
            | JpDeclaredContinuationScopeTailBridge(continuationRef, bridgePath, depthDelta) ->
                JpDeclaredEvaluatorTailBridgePc(continuationRef, bridgePath, depthDelta)
            | JpDeclaredContinuationScopeOpaque(nearestTypedParent, depthDelta) ->
                JpDeclaredEvaluatorOpaquePc(nearestTypedParent, depthDelta)

        let jpDeclaredEvaluatorParentPcText = function
            | JpDeclaredEvaluatorRootPc -> "root"
            | JpDeclaredEvaluatorNestedPc continuationRef -> JpWorkContinuationRefOps.text continuationRef
            | JpDeclaredEvaluatorTailBridgePc(continuationRef, bridgePath, depthDelta) ->
                "tail_bridge(parent=" + JpWorkContinuationRefOps.text continuationRef + "|path=" + jpDeclaredTailResultBridgePathText bridgePath + "|depth_delta=" + string depthDelta + ")"
            | JpDeclaredEvaluatorOpaquePc(Some continuationRef, depthDelta) ->
                "opaque(nearest=" + JpWorkContinuationRefOps.text continuationRef + "|depth_delta=" + string depthDelta + ")"
            | JpDeclaredEvaluatorOpaquePc(None, depthDelta) ->
                "opaque(root_descendant|depth_delta=" + string depthDelta + ")"

        let jpDeclaredEvaluatorPcKey jobId nodeId =
            JpDeclaredEvaluatorPcKey(jobId, nodeId, jpDeclaredEvaluatorParentPcFor jobId)

        let jpDeclaredOperationBudgetPosition operationCount operationBudget retryInterval =
            if operationCount <= 0L then JpDeclaredOperationNoProgress
            elif operationCount = operationBudget then JpDeclaredOperationAtBoundary
            elif operationCount > operationBudget && (operationCount - operationBudget) % retryInterval = 0L then JpDeclaredOperationAtBoundary
            else JpDeclaredOperationInsideSlice

        let jpDeclaredOperationBoundaryDecision () =
            match jpCurrentDeclaredBodySliceContext () with
            | None -> JpDeclaredOperationBoundaryNotApplicable
            | Some (JpDeclaredBodySliceContext(jobId, maxOperations, checkpointInterval)) ->
                let operationCount = max 0L jp_current_operation_counter.Value
                let operationBudget = int64 (max 1 maxOperations)
                let boundaryRetryInterval = int64 (max 1 checkpointInterval)
                match jpDeclaredOperationBudgetPosition operationCount operationBudget boundaryRetryInterval with
                | JpDeclaredOperationNoProgress
                | JpDeclaredOperationInsideSlice -> JpDeclaredOperationBoundaryBelowBudget
                | JpDeclaredOperationAtBoundary ->
                    match jpTryCurrentDeclaredBodyContinuationRef jobId with
                    | Some continuationRef ->
                        match jpTryDeclaredResumeSnapshotByRef continuationRef with
                        | Some snapshot ->
                            match jpDeclaredDirectResumeSnapshotSupport snapshot with
                            | JpDeclaredDirectResumeNeedsDataCarrier acceptor ->
                                JpDeclaredOperationBoundaryAwaitDataCarrier acceptor
                            | _ -> JpDeclaredOperationBoundaryYield continuationRef
                        | None -> JpDeclaredOperationBoundaryYield continuationRef
                    | None -> JpDeclaredOperationBoundaryAwaitContinuation

        let jpYieldCurrentDeclaredBodyAtOperationBoundary () =
            // Once a typed failure is irrevocable, long-running declared bodies must
            // stop at the next evaluator safe point. This is not an external cancel:
            // the current worker keeps retirement authority and closes its own credit.
            if DiagJson.terminalFailureExitRequestedNow() then
                raise JpTerminalFailureRunningCutoverCancellation
            match jpDeclaredOperationBoundaryDecision () with
            | JpDeclaredOperationBoundaryYield continuationRef ->
                raise (JpDeclaredEvaluatorSliceYield(JpDeclaredSliceYieldOperationBoundaryBudget, continuationRef))
            | JpDeclaredOperationBoundaryAwaitDataCarrier acceptor ->
                let operationCount = max 0L jp_current_operation_counter.Value
                let operationBudget, boundaryRetryInterval =
                    match jpCurrentDeclaredBodySliceContext () with
                    | Some (JpDeclaredBodySliceContext(_, maxOperations, checkpointInterval)) ->
                        int64 (max 1 maxOperations), int64 (max 1 checkpointInterval)
                    | None -> 0L, 0L
                let occurrence, shouldEmit =
                    DiagJson.sparseLogDecision
                        ("jp_declared_operation_boundary_data_carrier_held|" + jpDeclaredDataResultAcceptorText acceptor)
                        64L
                if shouldEmit then
                    DiagJson.emit (
                        FastRuntimeFormat.format
                            "{\"kind\":\"jp_declared_operation_boundary_data_carrier_held\",\"result_acceptor_du\":%s,\"operation_count\":%d,\"operation_budget\":%d,\"boundary_retry_interval\":%d,\"over_initial_budget\":%b,\"boundary_retry_policy_du\":\"checkpoint_interval_after_initial_budget\",\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"occurrence_count\":%d,\"authority\":\"typed_data_result_acceptor_is_not_a_replay_checkpoint\",\"next\":\"retry_boundary_at_checkpoint_interval_until_executable_pc_or_result\"}"
                            [| box (DiagJson.esc (jpDeclaredDataResultAcceptorText acceptor)); box operationCount; box operationBudget; box boundaryRetryInterval; box (operationBudget > 0L && operationCount > operationBudget); box occurrence |])
            | JpDeclaredOperationBoundaryNotApplicable
            | JpDeclaredOperationBoundaryBelowBudget
            | JpDeclaredOperationBoundaryAwaitContinuation -> ()

        let jpDeclaredEvaluatorPcKeyAllowsDirectLookup (key:JpDeclaredEvaluatorPcKey) : bool =
            match key with
            | JpDeclaredEvaluatorPcKey(_, _, JpDeclaredEvaluatorTailBridgePc _) -> false
            | JpDeclaredEvaluatorPcKey(_, _, JpDeclaredEvaluatorOpaquePc _) -> false
            | JpDeclaredEvaluatorPcKey _ -> true

        let jpDeclaredBodyContinuationAvailabilityForJob (jobId:int64) (nodeId:int) (evidence:JpDeclaredBodyResumeEvidenceId) : JpDeclaredBodyContinuationAvailabilityId =
            let currentPcKey = jpDeclaredEvaluatorPcKey jobId nodeId
            let availabilityForSnapshot (continuationRef:JpWorkContinuationRef) (snapshot:JpDeclaredResumeSnapshotId) : JpDeclaredBodyContinuationAvailabilityId option =
                let continuationDigest = JpWorkContinuationRefOps.digest continuationRef
                match jpDeclaredDirectResumeSnapshotSupport snapshot, jpDeclaredDirectResumeSeed snapshot with
                | JpDeclaredDirectResumeSupportedApply, Some _
                | JpDeclaredDirectResumeSupportedLet, Some _
                | JpDeclaredDirectResumeSupportedSequence, Some _ ->
                    Some (JpDeclaredExecutableContinuationAvailable continuationDigest)
                | JpDeclaredDirectResumeSupportedFoldData _, _
                | JpDeclaredDirectResumeNeedsDataCarrier _, _ ->
                    Some (JpDeclaredDataCarrierContinuationAvailable continuationDigest)
                | JpDeclaredDirectResumeNeedsFoldRecordTypeCarrier, _ ->
                    Some (JpDeclaredTypeCarrierContinuationAvailable continuationDigest)
                | JpDeclaredDirectResumeLetCheckpointCursorOnly, _
                | JpDeclaredDirectResumeSupportedApply, None
                | JpDeclaredDirectResumeSupportedLet, None
                | JpDeclaredDirectResumeSupportedSequence, None -> None
            let matchingContinuations =
                seq {
                    for entry in jp_declared_apply_continuations do
                        match entry.Key with
                        | JpDeclaredEvaluatorPcKey(ownerJobId, ownerNodeId, _) when ownerJobId = jobId && ownerNodeId = nodeId && jpDeclaredEvaluatorPcKeyAllowsDirectLookup currentPcKey && entry.Key = currentPcKey ->
                            match jpTryDeclaredResumeSnapshotByRef entry.Value.continuationRef with
                            | Some snapshot ->
                                match availabilityForSnapshot entry.Value.continuationRef snapshot with
                                | Some availability -> yield availability
                                | None -> ()
                            | None -> ()
                        | _ -> ()
                    for entry in jp_declared_let_continuations do
                        match entry.Key with
                        | JpDeclaredEvaluatorPcKey(ownerJobId, ownerNodeId, _) when ownerJobId = jobId && ownerNodeId = nodeId && jpDeclaredEvaluatorPcKeyAllowsDirectLookup currentPcKey && entry.Key = currentPcKey ->
                            match jpTryDeclaredResumeSnapshotByRef entry.Value.continuationRef with
                            | Some snapshot ->
                                match availabilityForSnapshot entry.Value.continuationRef snapshot with
                                | Some availability -> yield availability
                                | None -> ()
                            | None -> ()
                        | _ -> ()
                    for entry in jp_declared_sequence_continuations do
                        match entry.Key with
                        | JpDeclaredEvaluatorPcKey(ownerJobId, ownerNodeId, _) when ownerJobId = jobId && ownerNodeId = nodeId && jpDeclaredEvaluatorPcKeyAllowsDirectLookup currentPcKey && entry.Key = currentPcKey ->
                            match jpTryDeclaredResumeSnapshotByRef entry.Value.continuationRef with
                            | Some snapshot ->
                                match availabilityForSnapshot entry.Value.continuationRef snapshot with
                                | Some availability -> yield availability
                                | None -> ()
                            | None -> ()
                        | _ -> ()
                    for entry in jp_declared_binary_numeric_continuations do
                        match entry.Key with
                        | JpDeclaredEvaluatorPcKey(ownerJobId, ownerNodeId, _) when ownerJobId = jobId && ownerNodeId = nodeId && jpDeclaredEvaluatorPcKeyAllowsDirectLookup currentPcKey && entry.Key = currentPcKey ->
                            match jpTryDeclaredResumeSnapshotByRef entry.Value.continuationRef with
                            | Some snapshot ->
                                match availabilityForSnapshot entry.Value.continuationRef snapshot with
                                | Some availability -> yield availability
                                | None -> ()
                            | None -> ()
                        | _ -> ()
                    for entry in jp_declared_record_type_foldback_continuations do
                        match entry.Key with
                        | JpDeclaredEvaluatorPcKey(ownerJobId, ownerNodeId, _) when ownerJobId = jobId && ownerNodeId = nodeId && jpDeclaredEvaluatorPcKeyAllowsDirectLookup currentPcKey && entry.Key = currentPcKey ->
                            match jpTryDeclaredResumeSnapshotByRef entry.Value.continuationRef with
                            | Some snapshot ->
                                match availabilityForSnapshot entry.Value.continuationRef snapshot with
                                | Some availability -> yield availability
                                | None -> ()
                            | None -> ()
                        | _ -> ()
                }
                |> Seq.truncate 2
                |> Seq.toArray
            match matchingContinuations with
            | [| availability |] -> availability
            | [| _; _ |] -> JpDeclaredExecutableContinuationAmbiguous 2
            | _ -> jpDeclaredBodyContinuationAvailabilityFor evidence

        let jpDeclaredEvaluatorPcKeyMatches (jobId:int64) (nodeId:int) (resumeKey:JpDeclaredEvaluatorPcKey) : bool =
            let currentKey = jpDeclaredEvaluatorPcKey jobId nodeId
            jpDeclaredEvaluatorPcKeyAllowsDirectLookup currentKey
            && jpDeclaredEvaluatorPcKeyAllowsDirectLookup resumeKey
            && currentKey = resumeKey

        let jpDeclaredContinuationLookupValue = function
            | JpDeclaredContinuationFromSnapshot(_, continuation)
            | JpDeclaredContinuationFromLocator(_, continuation) -> continuation

        let jpDeclaredContinuationLookupRef = function
            | JpDeclaredContinuationFromSnapshot(continuationRef, _)
            | JpDeclaredContinuationFromLocator(continuationRef, _) -> continuationRef

        let jpCommitDeclaredContinuationLookup jobId = function
            | JpDeclaredContinuationFromSnapshot(targetRef, _) ->
                jpConsumeDeclaredResumeTarget jobId targetRef
                jpRetireDeclaredResumeSnapshot targetRef
            | JpDeclaredContinuationFromLocator(continuationRef, _) ->
                jpRetireDeclaredResumeSnapshot continuationRef

        let jpRunDeclaredContinuationLookup jobId lookup run =
            match lookup with
            | JpDeclaredContinuationFromSnapshot(targetRef, continuation) ->
                let value =
                    jpWithDeclaredDirectResumeExecutionRoots [|targetRef|] (fun () -> run continuation)
                jpCommitDeclaredContinuationLookup jobId lookup
                value
            | JpDeclaredContinuationFromLocator(continuationRef, continuation) ->
                let value =
                    jpWithDeclaredDirectResumeExecutionRoots [|continuationRef|] (fun () -> run continuation)
                jpCommitDeclaredContinuationLookup jobId lookup
                value

        let jpTryGetDeclaredApplyContinuation jobId nodeId =
            let tryKey key =
                let mutable continuation = Unchecked.defaultof<JpDeclaredApplyContinuation>
                if jp_declared_apply_continuations.TryGetValue(key, &continuation) then
                    if Option.isSome (jpTryDeclaredResumeSnapshotByRef continuation.continuationRef) then
                        if jpDeclaredApplyStageCanSeed continuation.stage then
                            Some (JpDeclaredContinuationFromLocator(continuation.continuationRef, continuation))
                        else None
                    else
                        let mutable stale = Unchecked.defaultof<JpDeclaredApplyContinuation>
                        jp_declared_apply_continuations.TryRemove(key, &stale) |> ignore
                        None
                else None
            match jpTryDeclaredResumeSnapshot jobId with
            | Some(target, JpDeclaredApplyResumeSnapshot(resumeKey, continuation)) when jpDeclaredEvaluatorPcKeyMatches jobId nodeId resumeKey && jpDeclaredApplyStageCanSeed continuation.stage ->
                Some (JpDeclaredContinuationFromSnapshot(target, continuation))
            | _ ->
                let currentKey = jpDeclaredEvaluatorPcKey jobId nodeId
                if jpDeclaredEvaluatorPcKeyAllowsDirectLookup currentKey then tryKey currentKey else None


        let jpStoreDeclaredApplyContinuation jobId nodeId frames nextFrameIndex currentValue stage =
            match stage, currentValue with
            | JpDeclaredApplyHeadPending, None
            | JpDeclaredApplyBeforeArgument, Some _
            | JpDeclaredApplyArgumentReadyDispatchPending _, Some _ -> ()
            | JpDeclaredApplyHeadPending, Some _ ->
                invalidOp "ApplyHeadPending continuation must not carry a precomputed current value."
            | JpDeclaredApplyBeforeArgument, None
            | JpDeclaredApplyArgumentReadyDispatchPending _, None ->
                invalidOp "Apply continuation stage requires a current value before it can be stored."
            let parentPc = jpDeclaredEvaluatorParentPcFor jobId
            let continuationOrdinal = jpNextDeclaredContinuationOrdinal jobId
            let continuationRef =
                jpDeclaredContinuationIdentityRef
                    "jp-declared-apply-evaluator-pc"
                    jobId
                    nodeId
                    continuationOrdinal
            let continuation =
                { frames = frames
                  nextFrameIndex = nextFrameIndex
                  currentValue = currentValue
                  stage = stage
                  continuationRef = continuationRef }
            let key = JpDeclaredEvaluatorPcKey(jobId, nodeId, parentPc)
            jpRegisterDeclaredResumeSnapshot continuationRef (JpDeclaredApplyResumeSnapshot(key, continuation))
            jp_declared_apply_continuations.[key] <- continuation
            jpMaybePruneDeclaredResumeSnapshots jobId continuationOrdinal continuationRef
            continuationRef

        let jpClearDeclaredApplyContinuation jobId nodeId =
            let key = jpDeclaredEvaluatorPcKey jobId nodeId
            let mutable removed = Unchecked.defaultof<JpDeclaredApplyContinuation>
            jp_declared_apply_continuations.TryRemove(key, &removed) |> ignore

        let jpTryGetDeclaredLetContinuation jobId nodeId =
            let tryKey key =
                let mutable continuation = Unchecked.defaultof<JpDeclaredLetContinuation>
                if jp_declared_let_continuations.TryGetValue(key, &continuation) then
                    if Option.isSome (jpTryDeclaredResumeSnapshotByRef continuation.continuationRef) then
                        Some (JpDeclaredContinuationFromLocator(continuation.continuationRef, continuation))
                    else
                        let mutable stale = Unchecked.defaultof<JpDeclaredLetContinuation>
                        jp_declared_let_continuations.TryRemove(key, &stale) |> ignore
                        None
                else None
            match jpTryDeclaredResumeSnapshot jobId with
            | Some(target, JpDeclaredLetResumeSnapshot(resumeKey, continuation)) when jpDeclaredEvaluatorPcKeyMatches jobId nodeId resumeKey ->
                Some (JpDeclaredContinuationFromSnapshot(target, continuation))
            | _ ->
                let currentKey = jpDeclaredEvaluatorPcKey jobId nodeId
                if jpDeclaredEvaluatorPcKeyAllowsDirectLookup currentKey then tryKey currentKey else None

        let jpStoreDeclaredLetContinuation jobId nodeId environment remainingExpression bindingCount stage =
            let observedParentPc = jpDeclaredEvaluatorParentPcFor jobId
            let parentPc =
                match observedParentPc, stage with
                | JpDeclaredEvaluatorOpaquePc(None, 1), JpDeclaredLetCheckpointReady
                | JpDeclaredEvaluatorOpaquePc(None, 1), JpDeclaredLetBodyPending ->
                    // Let body/checkpoint results are expression-transparent. At exactly one
                    // opaque level below the lexical root there is no missing Data consumer:
                    // the continuation's result is the root expression result itself. Capture
                    // that root relation when the snapshot is minted, rather than waiting for
                    // a later resume target and then trying to reconstruct ancestry.
                    let occurrence, shouldEmit =
                        DiagJson.sparseLogDecision
                            ("jp_declared_transparent_root_parent_materialized|" + string jobId + "|" + string nodeId + "|" + jpDeclaredLetStageText stage)
                            64L
                    if shouldEmit then
                        DiagJson.emit (
                            FastRuntimeFormat.format
                                "{\"kind\":\"jp_declared_transparent_root_parent_materialized\",\"work_job_id\":%d,\"node_id\":%d,\"stage_du\":%s,\"observed_opaque_depth\":1,\"parent_endpoint_du\":\"LexicalRoot\",\"typed_parent_present\":true,\"ancestor_replay_hops\":0,\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"occurrence_count\":%d,\"authority\":\"typed_expression_transparency_materializes_root_parent_at_snapshot_creation\",\"control_authority\":false,\"next\":\"build_resume_spine_to_root_without_ancestor_replay\"}"
                                [| box jobId; box nodeId; box (DiagJson.esc (jpDeclaredLetStageText stage)); box occurrence |])
                    JpDeclaredEvaluatorRootPc
                | _ -> observedParentPc
            let continuationOrdinal = jpNextDeclaredContinuationOrdinal jobId
            let continuationRef =
                jpDeclaredContinuationIdentityRef
                    "jp-declared-let-evaluator-pc"
                    jobId
                    nodeId
                    continuationOrdinal
            let continuation =
                { environment = environment
                  remainingExpression = remainingExpression
                  bindingCount = bindingCount
                  stage = stage
                  continuationRef = continuationRef }
            let key = JpDeclaredEvaluatorPcKey(jobId, nodeId, parentPc)
            jpRegisterDeclaredResumeSnapshot continuationRef (JpDeclaredLetResumeSnapshot(key, continuation))
            jp_declared_let_continuations.[key] <- continuation
            jpMaybePruneDeclaredResumeSnapshots jobId continuationOrdinal continuationRef
            continuationRef

        let jpClearDeclaredLetContinuation jobId nodeId =
            let key = jpDeclaredEvaluatorPcKey jobId nodeId
            let mutable removed = Unchecked.defaultof<JpDeclaredLetContinuation>
            jp_declared_let_continuations.TryRemove(key, &removed) |> ignore

        let jpTryGetDeclaredSequenceContinuation jobId nodeId =
            let tryKey key =
                let mutable continuation = Unchecked.defaultof<JpDeclaredSequenceContinuation>
                if jp_declared_sequence_continuations.TryGetValue(key, &continuation) then
                    if Option.isSome (jpTryDeclaredResumeSnapshotByRef continuation.continuationRef) then
                        Some (JpDeclaredContinuationFromLocator(continuation.continuationRef, continuation))
                    else
                        let mutable stale = Unchecked.defaultof<JpDeclaredSequenceContinuation>
                        jp_declared_sequence_continuations.TryRemove(key, &stale) |> ignore
                        None
                else None
            match jpTryDeclaredResumeSnapshot jobId with
            | Some(target, JpDeclaredSequenceResumeSnapshot(resumeKey, continuation)) when jpDeclaredEvaluatorPcKeyMatches jobId nodeId resumeKey ->
                Some (JpDeclaredContinuationFromSnapshot(target, continuation))
            | _ ->
                let currentKey = jpDeclaredEvaluatorPcKey jobId nodeId
                if jpDeclaredEvaluatorPcKeyAllowsDirectLookup currentKey then tryKey currentKey else None

        let jpStoreDeclaredSequenceContinuation jobId nodeId environment remainingExpression stage =
            let parentPc = jpDeclaredEvaluatorParentPcFor jobId
            let continuationOrdinal = jpNextDeclaredContinuationOrdinal jobId
            let continuationRef =
                jpDeclaredContinuationIdentityRef
                    "jp-declared-sequence-evaluator-pc"
                    jobId
                    nodeId
                    continuationOrdinal
            let continuation =
                { environment = environment
                  remainingExpression = remainingExpression
                  stage = stage
                  continuationRef = continuationRef }
            let key = JpDeclaredEvaluatorPcKey(jobId, nodeId, parentPc)
            jpRegisterDeclaredResumeSnapshot continuationRef (JpDeclaredSequenceResumeSnapshot(key, continuation))
            jp_declared_sequence_continuations.[key] <- continuation
            jpMaybePruneDeclaredResumeSnapshots jobId continuationOrdinal continuationRef
            continuationRef

        let jpClearDeclaredSequenceContinuation jobId nodeId =
            let key = jpDeclaredEvaluatorPcKey jobId nodeId
            let mutable removed = Unchecked.defaultof<JpDeclaredSequenceContinuation>
            jp_declared_sequence_continuations.TryRemove(key, &removed) |> ignore

        let jpTryGetDeclaredBinaryNumericContinuation jobId nodeId =
            let tryKey key =
                let mutable continuation = Unchecked.defaultof<JpDeclaredBinaryNumericContinuation>
                if jp_declared_binary_numeric_continuations.TryGetValue(key, &continuation) then
                    if Option.isSome (jpTryDeclaredResumeSnapshotByRef continuation.continuationRef) then
                        Some (JpDeclaredContinuationFromLocator(continuation.continuationRef, continuation))
                    else
                        let mutable stale = Unchecked.defaultof<JpDeclaredBinaryNumericContinuation>
                        jp_declared_binary_numeric_continuations.TryRemove(key, &stale) |> ignore
                        None
                else None
            match jpTryDeclaredResumeSnapshot jobId with
            | Some(target, JpDeclaredBinaryNumericResumeSnapshot(resumeKey, continuation)) when jpDeclaredEvaluatorPcKeyMatches jobId nodeId resumeKey ->
                Some (JpDeclaredContinuationFromSnapshot(target, continuation))
            | _ ->
                let currentKey = jpDeclaredEvaluatorPcKey jobId nodeId
                if jpDeclaredEvaluatorPcKeyAllowsDirectLookup currentKey then tryKey currentKey else None

        let jpStoreDeclaredBinaryNumericContinuation jobId nodeId environment operation leftExpression rightExpression stage =
            let parentPc = jpDeclaredEvaluatorParentPcFor jobId
            let continuationOrdinal = jpNextDeclaredContinuationOrdinal jobId
            let continuationRef =
                jpDeclaredContinuationIdentityRef
                    "jp-declared-binary-numeric-evaluator-pc"
                    jobId
                    nodeId
                    continuationOrdinal
            let continuation =
                { environment = environment
                  operation = operation
                  leftExpression = leftExpression
                  rightExpression = rightExpression
                  stage = stage
                  continuationRef = continuationRef }
            let key = JpDeclaredEvaluatorPcKey(jobId, nodeId, parentPc)
            jpRegisterDeclaredResumeSnapshot continuationRef (JpDeclaredBinaryNumericResumeSnapshot(key, continuation))
            jp_declared_binary_numeric_continuations.[key] <- continuation
            jpMaybePruneDeclaredResumeSnapshots jobId continuationOrdinal continuationRef
            continuationRef

        let jpClearDeclaredBinaryNumericContinuation jobId nodeId =
            let key = jpDeclaredEvaluatorPcKey jobId nodeId
            let mutable removed = Unchecked.defaultof<JpDeclaredBinaryNumericContinuation>
            jp_declared_binary_numeric_continuations.TryRemove(key, &removed) |> ignore

        let jpTryGetDeclaredRecordTypeFoldBackContinuation jobId nodeId =
            let tryKey key =
                let mutable continuation = Unchecked.defaultof<JpDeclaredRecordTypeFoldBackContinuation>
                if jp_declared_record_type_foldback_continuations.TryGetValue(key, &continuation) then
                    if Option.isSome (jpTryDeclaredResumeSnapshotByRef continuation.continuationRef) then
                        Some (JpDeclaredContinuationFromLocator(continuation.continuationRef, continuation))
                    else
                        let mutable stale = Unchecked.defaultof<JpDeclaredRecordTypeFoldBackContinuation>
                        jp_declared_record_type_foldback_continuations.TryRemove(key, &stale) |> ignore
                        None
                else None
            match jpTryDeclaredResumeSnapshot jobId with
            | Some(target, JpDeclaredRecordTypeFoldBackResumeSnapshot(resumeKey, continuation)) when jpDeclaredEvaluatorPcKeyMatches jobId nodeId resumeKey ->
                Some (JpDeclaredContinuationFromSnapshot(target, continuation))
            | _ ->
                let currentKey = jpDeclaredEvaluatorPcKey jobId nodeId
                if jpDeclaredEvaluatorPcKeyAllowsDirectLookup currentKey then tryKey currentKey else None

        let jpStoreDeclaredRecordTypeFoldBackContinuation jobId nodeId folderExpression initialStateExpression recordType state =
            let parentPc = jpDeclaredEvaluatorParentPcFor jobId
            let continuationOrdinal = jpNextDeclaredContinuationOrdinal jobId
            let continuationRef =
                jpDeclaredContinuationIdentityRef
                    "jp-declared-record-type-foldback-evaluator-pc"
                    jobId
                    nodeId
                    continuationOrdinal
            let continuation =
                { folderExpression = folderExpression
                  initialStateExpression = initialStateExpression
                  recordTypeSource = JpDeclaredRecordTypePrepassSource recordType
                  state = state
                  continuationRef = continuationRef }
            let key = JpDeclaredEvaluatorPcKey(jobId, nodeId, parentPc)
            jpRegisterDeclaredResumeSnapshot continuationRef (JpDeclaredRecordTypeFoldBackResumeSnapshot(key, continuation))
            jp_declared_record_type_foldback_continuations.[key] <- continuation
            jpMaybePruneDeclaredResumeSnapshots jobId continuationOrdinal continuationRef
            continuationRef

        let jpClearDeclaredRecordTypeFoldBackContinuation jobId nodeId =
            let key = jpDeclaredEvaluatorPcKey jobId nodeId
            let mutable removed = Unchecked.defaultof<JpDeclaredRecordTypeFoldBackContinuation>
            jp_declared_record_type_foldback_continuations.TryRemove(key, &removed) |> ignore

        let jpWithCurrentWorkIdentity (item:JpWorkItem) run =
            let jobId = item.commitOrdinal
            let previous = jp_current_work_identity.Value
            let previousOperationCounter = jp_current_operation_counter.Value
            let previousRecoverySliceMultiplier = jp_current_declared_recovery_slice_multiplier.Value
            let previousTermDepth = jp_current_declared_term_depth.Value
            let previousSafeContinuationDepth = jp_current_declared_safe_continuation_term_depth.Value
            let previousSafeContinuation = jpCurrentDeclaredSafeContinuation ()
            let previousTailResultBridge = jpCurrentDeclaredTailResultBridge ()
            let previousDirectResumeQuarantine = jp_current_declared_direct_resume_quarantine.Value
            let previousDirectRootResumeQuarantine = jp_current_declared_root_resume_quarantine.Value
            let previousBoundedSliceQuarantine = jp_current_declared_bounded_slice_quarantine.Value
            let previousMixedResumeCompletedJobId = jp_current_declared_mixed_resume_completed_job_id.Value
            let previousMixedResumeCompletedRootNodeId = jp_current_declared_mixed_resume_completed_root_node_id.Value
            let previousMixedResumeCompletedRootIdentity = jp_current_declared_mixed_resume_completed_root_identity.Value
            jp_current_work_identity.Value <- jobId
            if previous <> jobId then
                jp_current_operation_counter.Value <- 0L
                jp_current_declared_term_depth.Value <- 0
                // Admission owns the concrete work item, so recovery policy must be
                // derived from it directly rather than from jp_active_work_items, which
                // is intentionally installed later by jpInstallActiveWorkTiming.
                jp_current_declared_recovery_slice_multiplier.Value <-
                    jpDeclaredBodyRecoverySliceMultiplierForItem item
                jpSetCurrentDeclaredSafeContinuation None
                jpSetCurrentDeclaredTailResultBridge None
                jp_current_declared_direct_resume_quarantine.Value <- false
                jp_current_declared_root_resume_quarantine.Value <- false
                jp_current_declared_bounded_slice_quarantine.Value <- false
                jp_current_declared_mixed_resume_completed_job_id.Value <- 0L
                jp_current_declared_mixed_resume_completed_root_node_id.Value <- 0
                jp_current_declared_mixed_resume_completed_root_identity.Value <- null
            try run()
            finally
                jp_current_work_identity.Value <- previous
                jp_current_operation_counter.Value <- previousOperationCounter
                jp_current_declared_recovery_slice_multiplier.Value <- previousRecoverySliceMultiplier
                jp_current_declared_term_depth.Value <- previousTermDepth
                jpSetCurrentDeclaredSafeContinuationAtDepth previousSafeContinuation previousSafeContinuationDepth
                jpSetCurrentDeclaredTailResultBridge previousTailResultBridge
                jp_current_declared_direct_resume_quarantine.Value <- previousDirectResumeQuarantine
                jp_current_declared_root_resume_quarantine.Value <- previousDirectRootResumeQuarantine
                jp_current_declared_bounded_slice_quarantine.Value <- previousBoundedSliceQuarantine
                jp_current_declared_mixed_resume_completed_job_id.Value <- previousMixedResumeCompletedJobId
                jp_current_declared_mixed_resume_completed_root_node_id.Value <- previousMixedResumeCompletedRootNodeId
                jp_current_declared_mixed_resume_completed_root_identity.Value <- previousMixedResumeCompletedRootIdentity

        do
            BigStack.installExecutionCarrier
                (fun () ->
                    BigStack.executionCarrierState(
                        box (JpDeclaredExecutionCarrierState(
                            jp_current_work_identity.Value,
                            jp_current_operation_counter.Value,
                            max 1 jp_current_declared_recovery_slice_multiplier.Value,
                            max 0 jp_current_declared_term_depth.Value,
                            max 0 jp_current_declared_safe_continuation_term_depth.Value,
                            jpCurrentDeclaredSafeContinuation (),
                            jpCurrentDeclaredTailResultBridge (),
                            jpCurrentDeclaredDirectResumeExecutionRoots (),
                            jp_current_declared_direct_resume_quarantine.Value,
                            jp_current_declared_root_resume_quarantine.Value,
                            jp_current_declared_bounded_slice_quarantine.Value,
                            jp_current_declared_mixed_resume_completed_job_id.Value,
                            jp_current_declared_mixed_resume_completed_root_node_id.Value,
                            jp_current_declared_mixed_resume_completed_root_identity.Value))))
                (fun carrierState run ->
                    let state = BigStack.executionCarrierStateValue carrierState
                    let (JpDeclaredExecutionCarrierState(jobId, operationCounter, recoverySliceMultiplier, termDepth, safeContinuationTermDepth, safeContinuation, tailResultBridge, directResumeExecutionRoots, directResumeQuarantine, directRootResumeQuarantine, boundedSliceQuarantine, mixedResumeCompletedJobId, mixedResumeCompletedRootNodeId, mixedResumeCompletedRootIdentity)) =
                        unbox<JpDeclaredExecutionCarrierState> state
                    let previousJobId = jp_current_work_identity.Value
                    let previousOperationCounter = jp_current_operation_counter.Value
                    let previousRecoverySliceMultiplier = jp_current_declared_recovery_slice_multiplier.Value
                    let previousTermDepth = jp_current_declared_term_depth.Value
                    let previousSafeContinuationDepth = jp_current_declared_safe_continuation_term_depth.Value
                    let previousSafeContinuation = jpCurrentDeclaredSafeContinuation ()
                    let previousTailResultBridge = jpCurrentDeclaredTailResultBridge ()
                    let previousDirectResumeExecutionRoots = jp_current_declared_direct_resume_execution_roots.Value
                    let previousDirectResumeQuarantine = jp_current_declared_direct_resume_quarantine.Value
                    let previousDirectRootResumeQuarantine = jp_current_declared_root_resume_quarantine.Value
                    let previousBoundedSliceQuarantine = jp_current_declared_bounded_slice_quarantine.Value
                    let previousMixedResumeCompletedJobId = jp_current_declared_mixed_resume_completed_job_id.Value
                    let previousMixedResumeCompletedRootNodeId = jp_current_declared_mixed_resume_completed_root_node_id.Value
                    let previousMixedResumeCompletedRootIdentity = jp_current_declared_mixed_resume_completed_root_identity.Value
                    jp_current_work_identity.Value <- jobId
                    jp_current_operation_counter.Value <- operationCounter
                    jp_current_declared_recovery_slice_multiplier.Value <- max 1 recoverySliceMultiplier
                    jp_current_declared_term_depth.Value <- max 0 termDepth
                    jpSetCurrentDeclaredSafeContinuationAtDepth safeContinuation safeContinuationTermDepth
                    jpSetCurrentDeclaredTailResultBridge tailResultBridge
                    jp_current_declared_direct_resume_execution_roots.Value <- directResumeExecutionRoots
                    jp_current_declared_direct_resume_quarantine.Value <- directResumeQuarantine
                    jp_current_declared_root_resume_quarantine.Value <- directRootResumeQuarantine
                    jp_current_declared_bounded_slice_quarantine.Value <- boundedSliceQuarantine
                    jp_current_declared_mixed_resume_completed_job_id.Value <- mixedResumeCompletedJobId
                    jp_current_declared_mixed_resume_completed_root_node_id.Value <- mixedResumeCompletedRootNodeId
                    jp_current_declared_mixed_resume_completed_root_identity.Value <- mixedResumeCompletedRootIdentity
                    if jobId > 0L then
                        let mutable timing = Unchecked.defaultof<JpActiveWorkTiming>
                        if jp_active_job_timings.TryGetValue(jobId, &timing) then
                            let cpuStarted = jpCpuTimeSampleNow()
                            lock timing.timingGate (fun () ->
                                timing.cpuStarted <- cpuStarted)
                            match jpCpuTimeSampleAffinity cpuStarted with
                            | Some(workerRef, nativeThreadId)
                                when jp_cpu_baseline_rebound_emitted.TryAdd(jobId, 0uy) ->
                                DiagJson.emitRecord
                                    ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitCpuBaselineRebound
                                       job_id = jobId
                                       worker_ref = workerRef
                                       native_thread_id = nativeThreadId
                                       phase_du = "BigStackChild"
                                       sparse_policy = "first_productive_bigstack_thread_per_job"
                                       authority = "explicit_execution_carrier_rebinds_cpu_baseline_to_productive_native_thread"
                                       next = "sample_same_native_thread_from_watchdog" }
                                     : JpWorkUnitCpuBaselineReboundEvent)
                            | Some _
                            | None -> ()
                        let mutable profile = Unchecked.defaultof<JpActiveOperationProfile>
                        if jp_active_operation_profiles.TryGetValue(jobId, &profile) then
                            lock profile.profileGate (fun () ->
                                profile.lastPhase <- JpOperationPhaseBigStackChild
                                profile.recentPhaseSamples.Enqueue (JpOperationPhaseSample(JpOperationPhaseBigStackChild, profile.lastNodeId))
                                while profile.recentPhaseSamples.Count > 64 do
                                    profile.recentPhaseSamples.Dequeue() |> ignore
                                let mutable current = 0L
                                if profile.phaseCounts.TryGetValue(JpOperationPhaseBigStackChild, &current) then
                                    profile.phaseCounts.[JpOperationPhaseBigStackChild] <- current + 1L
                                else
                                    profile.phaseCounts.[JpOperationPhaseBigStackChild] <- 1L)
                    try run()
                    finally
                        jp_current_work_identity.Value <- previousJobId
                        jp_current_operation_counter.Value <- previousOperationCounter
                        jp_current_declared_recovery_slice_multiplier.Value <- previousRecoverySliceMultiplier
                        jp_current_declared_term_depth.Value <- previousTermDepth
                        jpSetCurrentDeclaredSafeContinuationAtDepth previousSafeContinuation previousSafeContinuationDepth
                        jpSetCurrentDeclaredTailResultBridge previousTailResultBridge
                        jp_current_declared_direct_resume_execution_roots.Value <- previousDirectResumeExecutionRoots
                        jp_current_declared_direct_resume_quarantine.Value <- previousDirectResumeQuarantine
                        jp_current_declared_root_resume_quarantine.Value <- previousDirectRootResumeQuarantine
                        jp_current_declared_bounded_slice_quarantine.Value <- previousBoundedSliceQuarantine
                        jp_current_declared_mixed_resume_completed_job_id.Value <- previousMixedResumeCompletedJobId
                        jp_current_declared_mixed_resume_completed_root_node_id.Value <- previousMixedResumeCompletedRootNodeId
                        jp_current_declared_mixed_resume_completed_root_identity.Value <- previousMixedResumeCompletedRootIdentity)

        let jpRecordCurrentWorkOperation
            (kind:JpActiveOperationKindId)
            (siteId:CompilerIdentityKernel.WorkSiteId)
            (shapeText:string)
            (nodeId:int) =
            match jpCurrentWorkIdentity () with
            | Some (JpWaiterWorkIdentity jobId) ->
                // Every recorded evaluator operation is an owner-local cancellation safe point.
                // Terminal fail-closed may not steal a Running cursor, but the owner must retire
                // itself promptly instead of waiting for a rarer term/ty boundary.
                if DiagJson.terminalFailureExitRequestedNow() then
                    raise JpTerminalFailureRunningCutoverCancellation
                let nextStep = jp_current_operation_counter.Value + 1L
                jp_current_operation_counter.Value <- nextStep
                let sampleShape = nextStep = 1L || (nextStep &&& 1023L) = 0L
                let shapeId = CompilerKernelV2.OperationalReasonIdOps.create shapeText
                let profile =
                    jp_active_operation_profiles.GetOrAdd(
                        jobId,
                        fun _ ->
                            { profileGate = obj()
                              shapeCounts = System.Collections.Generic.Dictionary<CompilerKernelV2.OperationalReasonId,int64>()
                              phaseCounts = System.Collections.Generic.Dictionary<JpActiveOperationPhaseId,int64>()
                              recentPhaseSamples = System.Collections.Generic.Queue<JpOperationPhaseSampleId>(64)
                              recentDeclaredCheckpointSamples = System.Collections.Generic.Queue<JpDeclaredBodyCheckpointCycleSampleId>(64)
                              operationCount = 0L
                              lastKind = kind
                              lastSite = siteId
                              lastShape = shapeId
                              lastNodeId = nodeId
                              lastPhase = JpOperationPhaseEntry })
                lock profile.profileGate (fun () ->
                    // Cumulative operation progress survives cooperative re-admission; the AsyncLocal
                    // counter is slice-local and exists only for bounded-slice preemption.
                    // CPU consumption never substitutes for advancing this counter.
                    profile.operationCount <- profile.operationCount + 1L
                    profile.lastKind <- kind
                    profile.lastSite <- siteId
                    profile.lastShape <- shapeId
                    profile.lastNodeId <- nodeId
                    if sampleShape then
                        let sampledCost = if nextStep = 1L then 1L else 1024L
                        let mutable current = 0L
                        if profile.shapeCounts.TryGetValue(shapeId, &current) then
                            profile.shapeCounts.[shapeId] <- current + sampledCost
                        else
                            profile.shapeCounts.[shapeId] <- sampledCost)
                if sampleShape then JpActiveOperationProfiled else JpActiveOperationCounted
            | None -> JpActiveOperationUntracked

        let jpPersistDeclaredBodyCheckpoint jobId phase =
            let mutable progressProfile = Unchecked.defaultof<JpActiveOperationProfile>
            let operationCount =
                if jp_active_operation_profiles.TryGetValue(jobId, &progressProfile) then
                    lock progressProfile.profileGate (fun () -> max 0L progressProfile.operationCount)
                else
                    max 0L jp_current_operation_counter.Value
            let mutable previous = Unchecked.defaultof<JpDeclaredBodyCheckpoint>
            let previousAvailable = jp_declared_body_checkpoints.TryGetValue(jobId, &previous)
            let previousOperationCount =
                if previousAvailable then previous.operationCount
                else 0L
            let nowMs = max 0L (jp_progress_clock())
            let operationDelta = max 0L (operationCount - previousOperationCount)
            let checkpointAgeMs =
                if previousAvailable then max 0L (nowMs - previous.capturedAtMs)
                else 0L
            let checkpointBoundary =
                if operationCount = 1L && not previousAvailable then
                    JpDeclaredBodyCheckpointInitial
                elif operationDelta >= jp_declared_body_checkpoint_interval_operations then
                    JpDeclaredBodyCheckpointOperationStride operationDelta
                elif operationDelta > 0L && checkpointAgeMs >= jp_declared_body_checkpoint_max_progress_age_ms then
                    JpDeclaredBodyCheckpointProgressAge(checkpointAgeMs, operationDelta)
                else
                    JpDeclaredBodyCheckpointNotDue
            match checkpointBoundary with
            | JpDeclaredBodyCheckpointNotDue -> ()
            | checkpointBoundary ->
                let mutable item = Unchecked.defaultof<JpWorkItem>
                let mutable profile = Unchecked.defaultof<JpActiveOperationProfile>
                if operationCount > previousOperationCount
                   && jp_active_work_items.TryGetValue(jobId, &item)
                   && item.workNode.intent = JpVerifyDeclaredMethodBody
                   && jp_active_operation_profiles.TryGetValue(jobId, &profile) then
                    let operationKind, siteId, shapeId, observedNodeId, observedSteps, phaseRingRef =
                        lock profile.profileGate (fun () ->
                            let phaseRingText =
                                profile.recentPhaseSamples
                                |> Seq.map jpOperationPhaseSampleText
                                |> String.concat ">"
                            let phaseRingRef =
                                CompilerIdentityKernel.ContentDigest.ofText
                                    "jp-declared-body-checkpoint-phase-ring"
                                    phaseRingText
                            profile.lastKind, profile.lastSite, profile.lastShape, profile.lastNodeId, max 0L profile.operationCount, phaseRingRef)
                    let checkpointOrdinal =
                        if previousAvailable then previous.checkpointOrdinal + 1L
                        else 1L
                    let observedResumePoint = jpDeclaredBodyResumePointFor phase
                    let resumePoint, resumePointAuthority, resumeNode =
                        match jpCurrentDeclaredSafeContinuation () with
                        | Some safeContinuation when jpDeclaredSafeContinuationJobId safeContinuation = jobId ->
                            let continuationRef = jpDeclaredSafeContinuationRef safeContinuation
                            let resumePoint, resumePointAuthority =
                                jpDeclaredBodyResumePointForSafeContinuation observedResumePoint safeContinuation
                            resumePoint,
                            resumePointAuthority,
                            JpDeclaredContinuationOwnedResumeNode(
                                jpDeclaredSafeContinuationNodeId safeContinuation,
                                JpWorkContinuationRefOps.digest continuationRef)
                        | _ ->
                            observedResumePoint,
                            JpDeclaredResumePointObservedPhase,
                            JpDeclaredObservedResumeNode observedNodeId
                    let resumeNodeId = jpDeclaredBodyResumeNodeValue resumeNode
                    let resumeEvidence = jpDeclaredBodyResumeEvidenceFor resumePoint resumeNodeId
                    let resumeCapability = jpDeclaredBodyResumeEvidenceCapability resumeEvidence
                    let checkpointRef =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-declared-body-checkpoint"
                            (CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                             + "|job=" + string jobId
                             + "|operations=" + string operationCount
                             + "|ordinal=" + string checkpointOrdinal
                             + "|boundary=" + jpDeclaredBodyCheckpointBoundaryText checkpointBoundary
                             + "|kind=" + jpActiveOperationKindText operationKind
                             + "|phase=" + jpActiveOperationPhaseText phase
                             + "|resume_point=" + jpDeclaredBodyResumePointText resumePoint
                             + "|resume_point_authority=" + jpDeclaredBodyResumePointAuthorityText resumePointAuthority
                             + "|resume_capability=" + jpDeclaredBodyResumeCapabilityText resumeCapability
                             + "|resume_evidence=" + jpDeclaredBodyResumeEvidenceText resumeEvidence
                             + "|observed_steps=" + string observedSteps
                             + "|phase_ring_ref=" + CompilerIdentityKernel.ContentDigest.text phaseRingRef
                             + "|site=" + CompilerIdentityKernel.WorkSiteIdOps.text siteId
                             + "|shape=" + CompilerKernelV2.OperationalReasonIdOps.text shapeId
                             + "|observed_node_id=" + string observedNodeId
                             + "|resume_node_id=" + string resumeNodeId
                             + "|resume_node_authority=" + jpDeclaredBodyResumeNodeAuthorityText resumeNode)
                    let checkpoint =
                        { checkpointOrdinal = checkpointOrdinal
                          operationCount = operationCount
                          operationKind = operationKind
                          resumePoint = resumePoint
                          resumePointAuthority = resumePointAuthority
                          resumeEvidence = resumeEvidence
                          observedSteps = observedSteps
                          phaseRingRef = phaseRingRef
                          siteId = siteId
                          shapeId = shapeId
                          resumeNode = resumeNode
                          capturedAtMs = nowMs
                          checkpointRef = checkpointRef }
                    let checkpointCycleSample =
                        JpDeclaredBodyCheckpointCycleSample(
                            phase,
                            observedNodeId,
                            resumePoint,
                            resumeNodeId)
                    lock profile.profileGate (fun () ->
                        profile.recentDeclaredCheckpointSamples.Enqueue checkpointCycleSample
                        while profile.recentDeclaredCheckpointSamples.Count > 64 do
                            profile.recentDeclaredCheckpointSamples.Dequeue() |> ignore)
                    jp_declared_body_checkpoints.[jobId] <- checkpoint
                    DiagJson.emitRecord
                        ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpDeclaredBodyCheckpointPersisted
                           work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                           producer_work_id = jobId
                           operation_count = operationCount
                           checkpoint_ordinal = checkpointOrdinal
                           checkpoint_boundary_du = jpDeclaredBodyCheckpointBoundaryText checkpointBoundary
                           operation_kind_du = jpActiveOperationKindText operationKind
                           phase_du = jpActiveOperationPhaseText phase
                           resume_point_du = jpDeclaredBodyResumePointText resumePoint
                           resume_point_authority_du = jpDeclaredBodyResumePointAuthorityText resumePointAuthority
                           resume_capability_du = jpDeclaredBodyResumeCapabilityText resumeCapability
                           resume_evidence_du = jpDeclaredBodyResumeEvidenceText resumeEvidence
                           observed_steps = observedSteps
                           phase_ring_ref = CompilerIdentityKernel.ContentDigest.text phaseRingRef
                           site = CompilerIdentityKernel.WorkSiteIdOps.text siteId
                           shape = CompilerKernelV2.OperationalReasonIdOps.text shapeId
                           node_id = observedNodeId
                           resume_node_id = resumeNodeId
                           resume_node_authority_du = jpDeclaredBodyResumeNodeAuthorityText resumeNode
                           checkpoint_ref = CompilerIdentityKernel.ContentDigest.text checkpointRef
                           continuation_availability_du =
                               jpDeclaredBodyContinuationAvailabilityForJob jobId resumeNodeId resumeEvidence
                               |> jpDeclaredBodyContinuationAvailabilityText
                           execution_policy_du = jpWorkExecutionPolicyText item.executionPolicy
                           authority = "declared_body_checkpoint_reports_typed_resume_evidence_and_executable_pc_when_materialized"
                           next = "resume_materialized_apply_let_or_record_type_foldback_pc_or_continue_until_next_slice" }
                         : JpDeclaredBodyCheckpointPersistedEvent)

        let jpRecordCurrentWorkPhase phase =
            match jpCurrentWorkIdentity () with
            | Some (JpWaiterWorkIdentity jobId) ->
                let mutable profile = Unchecked.defaultof<JpActiveOperationProfile>
                if jp_active_operation_profiles.TryGetValue(jobId, &profile) then
                    lock profile.profileGate (fun () ->
                        profile.lastPhase <- phase
                        profile.recentPhaseSamples.Enqueue (JpOperationPhaseSample(phase, profile.lastNodeId))
                        while profile.recentPhaseSamples.Count > 64 do
                            profile.recentPhaseSamples.Dequeue() |> ignore
                        let mutable current = 0L
                        if profile.phaseCounts.TryGetValue(phase, &current) then
                            profile.phaseCounts.[phase] <- current + 1L
                        else
                            profile.phaseCounts.[phase] <- 1L)
                    jpPersistDeclaredBodyCheckpoint jobId phase
            | None -> ()

        let jpActiveOperationProfileSnapshot jobId =
            let mutable profile = Unchecked.defaultof<JpActiveOperationProfile>
            if jp_active_operation_profiles.TryGetValue(jobId, &profile) then
                lock profile.profileGate (fun () ->
                    let topShapes =
                        profile.shapeCounts
                        |> Seq.map (fun (KeyValue(shapeId, count)) ->
                            CompilerKernelV2.OperationalReasonIdOps.text shapeId, count)
                        |> Seq.sortByDescending snd
                        |> Seq.truncate 6
                        |> Seq.map (fun (shape, count) -> shape + "=" + string count)
                        |> String.concat ";"
                    let topPhases =
                        profile.phaseCounts
                        |> Seq.map (fun (KeyValue(phase, count)) ->
                            jpActiveOperationPhaseText phase, count)
                        |> Seq.sortByDescending snd
                        |> Seq.truncate 6
                        |> Seq.map (fun (phase, count) -> phase + "=" + string count)
                        |> String.concat ";"
                    let recentPhaseSamples =
                        profile.recentPhaseSamples
                        |> Seq.toArray
                    let recentPhases =
                        recentPhaseSamples
                        |> Seq.map (jpOperationPhaseSamplePhase >> jpActiveOperationPhaseText)
                        |> String.concat ">"
                    let recentPhaseSampleText =
                        recentPhaseSamples
                        |> Seq.map jpOperationPhaseSampleText
                        |> String.concat ">"
                    let recentPhaseFingerprint =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-operation-phase-node-ring"
                            recentPhaseSampleText
                        |> CompilerIdentityKernel.ContentDigest.text
                    Some(
                        profile.operationCount,
                        jpActiveOperationKindText profile.lastKind,
                        CompilerIdentityKernel.WorkSiteIdOps.text profile.lastSite,
                        CompilerKernelV2.OperationalReasonIdOps.text profile.lastShape,
                        topShapes,
                        jpActiveOperationPhaseText profile.lastPhase,
                        topPhases,
                        recentPhases,
                        recentPhaseFingerprint))
            else None

        let jpActiveOperationPhaseRingLiveness jobId =
            let mutable profile = Unchecked.defaultof<JpActiveOperationProfile>
            if jp_active_operation_profiles.TryGetValue(jobId, &profile) then
                lock profile.profileGate (fun () ->
                    profile.recentPhaseSamples
                    |> Seq.toArray
                    |> jpOperationPhaseRingLivenessForSamples)
            else
                JpOperationPhaseRingInsufficientEvidence 0

        let jpActiveOperationObservedSteps jobId =
            let mutable profile = Unchecked.defaultof<JpActiveOperationProfile>
            if jp_active_operation_profiles.TryGetValue(jobId, &profile) then
                lock profile.profileGate (fun () -> max 0L profile.operationCount)
            else 0L

        let jpDeclaredBodyCheckpointSnapshot jobId nowMs =
            let mutable checkpoint = Unchecked.defaultof<JpDeclaredBodyCheckpoint>
            if jp_declared_body_checkpoints.TryGetValue(jobId, &checkpoint) then
                Some {
                    checkpointRefText = CompilerIdentityKernel.ContentDigest.text checkpoint.checkpointRef
                    checkpointOrdinal = checkpoint.checkpointOrdinal
                    checkpointOperationCount = checkpoint.operationCount
                    checkpointResumePointText = jpDeclaredBodyResumePointText checkpoint.resumePoint
                    checkpointResumePointAuthorityText = jpDeclaredBodyResumePointAuthorityText checkpoint.resumePointAuthority
                    checkpointResumeCapabilityText = jpDeclaredBodyResumeCapabilityText (jpDeclaredBodyResumeEvidenceCapability checkpoint.resumeEvidence)
                    checkpointResumeNodeId = jpDeclaredBodyResumeNodeValue checkpoint.resumeNode
                    checkpointResumeNodeAuthorityText = jpDeclaredBodyResumeNodeAuthorityText checkpoint.resumeNode
                    checkpointAgeMs = max 0L (nowMs - checkpoint.capturedAtMs)
                }
            else None

        let jpDeclaredBodyCheckpointReplayAssist jobId =
            let mutable checkpoint = Unchecked.defaultof<JpDeclaredBodyCheckpoint>
            if jp_declared_body_checkpoints.TryGetValue(jobId, &checkpoint) then
                let resumeNodeId = jpDeclaredBodyResumeNodeValue checkpoint.resumeNode
                let checkpointCapability = jpDeclaredBodyResumeEvidenceCapability checkpoint.resumeEvidence
                let observedEvidence = jpDeclaredBodyResumeEvidenceFor checkpoint.resumePoint resumeNodeId
                let observedCapability = jpDeclaredBodyResumeEvidenceCapability observedEvidence
                let continuationAvailability =
                    jpDeclaredBodyContinuationAvailabilityForJob jobId resumeNodeId observedEvidence
                let scheduleDrain () =
                    EvalWorklist.requestSemanticDrainPulse
                        EvalWorklist.ReplayTickEventJpDeclaredBodyCheckpoint
                        (EvalWorklist.ReplayTickReasonJpDeclaredBodyCheckpoint checkpoint.checkpointRef)
                match continuationAvailability with
                | JpDeclaredExecutableContinuationAvailable _ ->
                    Some(checkpointCapability, checkpoint.resumeEvidence, observedCapability, observedEvidence, continuationAvailability, checkpoint.checkpointRef, resumeNodeId, false)
                | JpDeclaredDataCarrierContinuationAvailable _
                | JpDeclaredTypeCarrierContinuationAvailable _ ->
                    let scheduled = scheduleDrain ()
                    Some(checkpointCapability, checkpoint.resumeEvidence, observedCapability, observedEvidence, continuationAvailability, checkpoint.checkpointRef, resumeNodeId, scheduled)
                | JpDeclaredExecutableContinuationAmbiguous _
                | JpDeclaredReplayResumeCandidateAvailable _
                | JpDeclaredContinuationUnavailable ->
                    match observedCapability with
                    | JpDeclaredResumeApplySpineStored
                    | JpDeclaredResumeLetSpineStored ->
                        let scheduled = scheduleDrain ()
                        Some(checkpointCapability, checkpoint.resumeEvidence, observedCapability, observedEvidence, continuationAvailability, checkpoint.checkpointRef, resumeNodeId, scheduled)
                    | _ -> Some(checkpointCapability, checkpoint.resumeEvidence, observedCapability, observedEvidence, continuationAvailability, checkpoint.checkpointRef, resumeNodeId, false)
            else None

        let jpProbeCurrentWorkExecutionBudget (siteId:CompilerIdentityKernel.WorkSiteId) =
            match jpCurrentWorkIdentity () with
            | Some (JpWaiterWorkIdentity jobId) ->
                let mutable timing = Unchecked.defaultof<JpActiveWorkTiming>
                if jp_active_job_timings.TryGetValue(jobId, &timing) then
                    let nowMs = jpActiveWorkTimingNowMs ()
                    let mutable diagnostic : (int64 * int64 * int64 * string * string * string * string * JpWorkAuthorityRole) option = None
                    lock timing.timingGate (fun () ->
                        let ageMs = max 0L (nowMs - timing.startedAtMs)
                        match jpWorkExecutionBudgetDecision timing.executionDiagnosticBudgetMs timing.executionBudgetMs ageMs with
                        | JpWorkExecutionWithinBudget -> ()
                        | JpWorkExecutionDiagnosticBudgetExceeded
                        | JpWorkExecutionHardBudgetExceeded
                            when not timing.executionDiagnosticBudgetExceeded ->
                            timing.executionDiagnosticBudgetExceeded <- true
                            diagnostic <- Some(
                                ageMs,
                                timing.executionDiagnosticBudgetMs,
                                timing.executionBudgetMs,
                                (CompilerIdentityKernel.ContentDigest.text timing.workUnitRef),
                                jpComputationIdentityKindText timing.computationIdentity,
                                jpComputationIdentityText timing.computationIdentity,
                                jpComputationIdentitySource timing.computationIdentity,
                                timing.authorityRole)
                        | JpWorkExecutionDiagnosticBudgetExceeded
                        | JpWorkExecutionHardBudgetExceeded -> ())
                    match diagnostic with
                    | Some(ageMs, diagnosticBudgetMs, hardBudgetMs, workUnitId, computationKind, computationKey, computationSource, authorityRole) ->
                        let publicationStageText, publicationStageAgeMs, publicationStageTransitions =
                            match jpActiveWorkPublicationStageSnapshot jobId nowMs with
                            | Some(stage, stageAgeMs, transitionCount) ->
                                jpWorkPublicationStageText stage, stageAgeMs, transitionCount
                            | None -> "Untracked", 0L, 0L
                        DiagJson.emitRecord
                            ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitExecutionBudgetDiagnostic
                               job_id = jobId
                               work_unit_id = workUnitId
                               computation_kind_du = computationKind
                               computation_key = computationKey
                               computation_source = computationSource
                               authority_role_du = jpWorkAuthorityRoleText authorityRole
                               site = CompilerIdentityKernel.WorkSiteIdOps.text siteId
                               publication_stage_du = publicationStageText
                               publication_stage_age_ms = publicationStageAgeMs
                               publication_stage_transitions = publicationStageTransitions
                               age_ms = ageMs
                               diagnostic_budget_ms = diagnosticBudgetMs
                               hard_budget_ms = hardBudgetMs
                               budget_du = jpWorkExecutionBudgetPolicyText timing.executionBudgetPolicy
                               terminal_authority = false
                               authority = "typed_current_work_budget_probe"
                               next = "continue_isolated_body_and_sample_cpu_before_hard_boundary" }
                             : JpWorkUnitExecutionBudgetDiagnosticEvent)
                    | None -> ()
            | None -> ()

        let jpInFlightSlowThresholdMs = 3000L
        let jpInFlightSlowThresholdBasisText =
            "FixedMs(value=3000|rationale=completion_profile_threshold)"
        let jpInFlightSlowAgeBuckets =
            System.Collections.Concurrent.ConcurrentDictionary<int64,int>()

        let jpInFlightSlowAgeBucket ageMs =
            let mutable scaled = max 1L (ageMs / jpInFlightSlowThresholdMs)
            let mutable bucket = 0
            while scaled > 1L do
                scaled <- scaled >>> 1
                bucket <- bucket + 1
            bucket

        let jpInFlightSlowAgeBucketShouldEmit jobId bucket =
            let mutable previous = 0
            if jpInFlightSlowAgeBuckets.TryGetValue(jobId, &previous) then
                bucket > previous && jpInFlightSlowAgeBuckets.TryUpdate(jobId, bucket, previous)
            else
                jpInFlightSlowAgeBuckets.TryAdd(jobId, bucket)

        let jpTryExpireActiveWorkDeadline nowMs jobId =
            let mutable timing = Unchecked.defaultof<JpActiveWorkTiming>
            let mutable item = Unchecked.defaultof<JpWorkItem>
            if jp_active_job_timings.TryGetValue(jobId, &timing)
               && jp_active_work_items.TryGetValue(jobId, &item) then
                let observedSteps = jpActiveOperationObservedSteps jobId
                let phaseRingLiveness = jpActiveOperationPhaseRingLiveness jobId
                let phaseRingRepeating =
                    match phaseRingLiveness with
                    | JpOperationPhaseRingRepeatingSuffix _ -> true
                    | JpOperationPhaseRingInsufficientEvidence _
                    | JpOperationPhaseRingAdvancing _ -> false
                let checkpointCycleLiveness =
                    jpDeclaredBodyCheckpointCycleLiveness jobId
                let checkpointCycleRepeating =
                    match checkpointCycleLiveness with
                    | JpDeclaredBodyCheckpointCycleStationary _
                    | JpDeclaredBodyCheckpointCycleRepeatingSuffix _
                    | JpDeclaredBodyCheckpointCycleAlternatingPair _ -> true
                    | JpDeclaredBodyCheckpointCycleInsufficientEvidence _
                    | JpDeclaredBodyCheckpointCycleAdvancing _
                    | JpDeclaredBodyCheckpointCycleRecurrentPrefix _ -> false
                let publicationStage, publicationStageText, publicationStageAgeMs, publicationStageTransitions =
                    match jpActiveWorkPublicationStageSnapshot jobId nowMs with
                    | Some(stage, stageAgeMs, transitionCount) ->
                        stage, jpWorkPublicationStageText stage, stageAgeMs, transitionCount
                    | None ->
                        JpWorkPublicationExecuting, "Untracked", 0L, 0L
                let publicationStageId =
                    CompilerKernelV2.OperationalReasonIdOps.create publicationStageText
                let cpuProgressSample =
                    match jpCpuTimeDelta timing.cpuStarted (jpCpuTimeSampleFor timing.cpuStarted) with
                    | Some cpu, _ -> Some(max 0L (CompilerKernelV2.Measured.value cpu))
                    | None, _ -> None
                let declaredBodyCheckpoint = jpDeclaredBodyCheckpointSnapshot jobId nowMs
                let diagnostic, deferral, expiration =
                    lock timing.timingGate (fun () ->
                        let ageMs = max 0L (nowMs - timing.startedAtMs)
                        if observedSteps > timing.lastObservedOperationCount then
                            timing.lastObservedOperationCount <- observedSteps
                            timing.lastOperationProgressAtMs <- nowMs
                        let operationIdleMs = max 0L (nowMs - timing.lastOperationProgressAtMs)
                        let cpuProgress =
                            match cpuProgressSample, timing.cpuProgressState with
                            | Some currentCpuMs, JpCpuProgressObserved(previousCpuMs, _)
                                when currentCpuMs > previousCpuMs ->
                                timing.cpuProgressState <- JpCpuProgressObserved(currentCpuMs, nowMs)
                                Some(currentCpuMs, 0L)
                            | Some currentCpuMs, JpCpuProgressObserved(_, progressedAtMs) ->
                                Some(currentCpuMs, max 0L (nowMs - progressedAtMs))
                            | Some currentCpuMs, JpCpuProgressUnavailable ->
                                timing.cpuProgressState <- JpCpuProgressObserved(currentCpuMs, nowMs)
                                Some(currentCpuMs, 0L)
                            | None, _ -> None
                        let operationProgressGraceMs =
                            max 30000L (min 90000L timing.executionDiagnosticBudgetMs)
                        let boundedProgressExtensionDeadlineMs =
                            timing.executionBudgetMs + operationProgressGraceMs
                        let declaredBodyProgressExtensionDeadlineMs =
                            boundedProgressExtensionDeadlineMs
                        let declaredBodyCheckpointProgress =
                            match declaredBodyCheckpoint with
                            | Some checkpoint
                                when checkpoint.checkpointOperationCount > 0L
                                     && checkpoint.checkpointAgeMs < operationProgressGraceMs
                                     && not phaseRingRepeating
                                     && not checkpointCycleRepeating ->
                                Some(checkpoint.checkpointOperationCount, checkpoint.checkpointAgeMs)
                            | _ -> None
                        let effectiveProgressExtensionDeadlineMs =
                            match declaredBodyCheckpointProgress with
                            | Some _ -> declaredBodyProgressExtensionDeadlineMs
                            | None -> boundedProgressExtensionDeadlineMs
                        let diagnostic =
                            if not timing.executionDiagnosticBudgetExceeded
                               && ageMs >= timing.executionDiagnosticBudgetMs then
                                timing.executionDiagnosticBudgetExceeded <- true
                                Some(ageMs, timing.executionDiagnosticBudgetMs, timing.executionBudgetMs, timing.executionBudgetPolicy)
                            else None
                        let deferral, expiration =
                            if not timing.executionBudgetExceeded && ageMs >= timing.executionBudgetMs then
                                let progressEvidence =
                                    if publicationStage <> JpWorkPublicationExecuting
                                       && publicationStageTransitions > 1L
                                       && publicationStageAgeMs < operationProgressGraceMs then
                                        JpWorkHardDeadlinePublicationProgress(publicationStageId, publicationStageAgeMs)
                                    else
                                        match declaredBodyCheckpointProgress with
                                        | Some(checkpointOperationCount, checkpointAgeMs) ->
                                            JpWorkHardDeadlineDeclaredCheckpointProgress(checkpointOperationCount, checkpointAgeMs)
                                        | _ when observedSteps > 0L
                                                 && operationIdleMs < operationProgressGraceMs
                                                 && not phaseRingRepeating
                                                 && not checkpointCycleRepeating ->
                                            JpWorkHardDeadlineOperationProgress(observedSteps, operationIdleMs)
                                        | _ -> JpWorkHardDeadlineNoProgress
                                let progressLease =
                                    match progressEvidence with
                                    | JpWorkHardDeadlineNoProgress -> JpWorkHardDeadlineProgressLeaseExpired
                                    | evidence -> JpWorkHardDeadlineProgressLeaseRenewed evidence
                                match progressLease with
                                | JpWorkHardDeadlineProgressLeaseRenewed(JpWorkHardDeadlineDeclaredCheckpointProgress(checkpointOperationCount, checkpointAgeMs)) ->
                                    timing.operationProgressDeferralCount <- timing.operationProgressDeferralCount + 1L
                                    let count = timing.operationProgressDeferralCount
                                    let sparse = count <= 2L || (count &&& (count - 1L)) = 0L
                                    let disposition = JpWorkHardDeadlineDeferredByDeclaredCheckpointProgress(checkpointOperationCount, checkpointAgeMs)
                                    (if sparse then Some(ageMs, operationProgressGraceMs, declaredBodyProgressExtensionDeadlineMs, count, disposition) else None), None
                                | JpWorkHardDeadlineProgressLeaseRenewed(JpWorkHardDeadlinePublicationProgress(stage, idleMs)) ->
                                    timing.operationProgressDeferralCount <- timing.operationProgressDeferralCount + 1L
                                    let count = timing.operationProgressDeferralCount
                                    let sparse = count <= 2L || (count &&& (count - 1L)) = 0L
                                    let disposition = JpWorkHardDeadlineDeferredByPublicationProgress(stage, idleMs)
                                    (if sparse then Some(ageMs, operationProgressGraceMs, boundedProgressExtensionDeadlineMs, count, disposition) else None), None
                                | JpWorkHardDeadlineProgressLeaseRenewed(JpWorkHardDeadlineOperationProgress(steps, idleMs)) ->
                                    timing.operationProgressDeferralCount <- timing.operationProgressDeferralCount + 1L
                                    let count = timing.operationProgressDeferralCount
                                    let sparse = count <= 2L || (count &&& (count - 1L)) = 0L
                                    let disposition = JpWorkHardDeadlineDeferredByOperationProgress(steps, idleMs)
                                    (if sparse then Some(ageMs, operationProgressGraceMs, boundedProgressExtensionDeadlineMs, count, disposition) else None), None
                                | JpWorkHardDeadlineProgressLeaseRenewed JpWorkHardDeadlineNoProgress ->
                                    invalidOp "hard-deadline progress lease invariant failed: renewed without progress evidence"
                                | JpWorkHardDeadlineProgressLeaseExpired ->
                                    match checkpointCycleLiveness with
                                    | JpDeclaredBodyCheckpointCycleStationary(repetitions, sampleCount, stateRef) ->
                                        // A stationary declared-body checkpoint is stronger than a raw
                                        // operation-ring loop: phase, operation node, resume point, and resume
                                        // node are unchanged across multiple bounded checkpoints.  The PatternMiss
                                        // owner still supplies the repeat+stable-age authority for cancellation;
                                        // the watchdog only yields to that owner instead of manufacturing failure.
                                        timing.operationProgressDeferralCount <- timing.operationProgressDeferralCount + 1L
                                        let count = timing.operationProgressDeferralCount
                                        let disposition =
                                            JpWorkHardDeadlineDeferredToPatternMissDeclaredCheckpointCycleCancellation(
                                                JpDeclaredCheckpointStationaryCancellationProof(
                                                    repetitions,
                                                    sampleCount,
                                                    stateRef),
                                                observedSteps)
                                        Some(ageMs, operationProgressGraceMs, boundedProgressExtensionDeadlineMs, count, disposition), None
                                    | JpDeclaredBodyCheckpointCycleAlternatingPair(repetitions, sampleCount, pairRef) ->
                                        // A stable two-state declared-body ping-pong is an operational
                                        // PatternMiss cycle, but only after the stronger stable-age gate in
                                        // jpCodegenPatternMissStasisDecisionForCheckpointCycleLiveness.
                                        // Keep the watchdog subordinate to that owner rather than converting
                                        // the cycle into a process-wide semantic failure.
                                        timing.operationProgressDeferralCount <- timing.operationProgressDeferralCount + 1L
                                        let count = timing.operationProgressDeferralCount
                                        let disposition =
                                            JpWorkHardDeadlineDeferredToPatternMissDeclaredCheckpointCycleCancellation(
                                                JpDeclaredCheckpointAlternatingPairCancellationProof(
                                                    repetitions,
                                                    sampleCount,
                                                    pairRef),
                                                observedSteps)
                                        Some(ageMs, operationProgressGraceMs, boundedProgressExtensionDeadlineMs, count, disposition), None
                                    | JpDeclaredBodyCheckpointCycleRepeatingSuffix(period, repetitions, sampleCount, cycleRef) ->
                                        // A declared checkpoint cycle is the same typed stasis evidence consumed by
                                        // the PatternMiss owner. The watchdog must not race that operational
                                        // cancellation by promoting the cycle to a process-wide semantic failure.
                                        // Preserve the running owner until its next bounded control yield; the
                                        // PatternMiss boundary will publish the exact cancellation into the body
                                        // cell and retire the operational credit.
                                        timing.operationProgressDeferralCount <- timing.operationProgressDeferralCount + 1L
                                        let count = timing.operationProgressDeferralCount
                                        let disposition =
                                            JpWorkHardDeadlineDeferredToPatternMissDeclaredCheckpointCycleCancellation(
                                                JpDeclaredCheckpointRepeatingSuffixCancellationProof(
                                                    period,
                                                    repetitions,
                                                    sampleCount,
                                                    cycleRef),
                                                observedSteps)
                                        Some(ageMs, operationProgressGraceMs, boundedProgressExtensionDeadlineMs, count, disposition), None
                                    | _ ->
                                        timing.executionBudgetExceeded <- true
                                        let disposition =
                                            match phaseRingLiveness with
                                            | JpOperationPhaseRingRepeatingSuffix(period, repetitions, _) ->
                                                JpWorkHardDeadlineExpiredAfterRepeatingOperationCycle(
                                                    period,
                                                    repetitions,
                                                    observedSteps,
                                                    operationIdleMs)
                                            | _ when ageMs >= effectiveProgressExtensionDeadlineMs ->
                                                JpWorkHardDeadlineExpiredAfterProgressLeaseStall(
                                                    ageMs,
                                                    effectiveProgressExtensionDeadlineMs,
                                                    observedSteps,
                                                    publicationStageTransitions)
                                            | _ ->
                                                if publicationStage <> JpWorkPublicationExecuting then
                                                    JpWorkHardDeadlineExpiredAfterPublicationStall(publicationStageId, publicationStageAgeMs)
                                                else
                                                    match cpuProgress with
                                                    | Some(cpuMs, _) when cpuMs >= timing.executionBudgetMs ->
                                                        JpWorkHardDeadlineExpiredAfterCpuBudget(cpuMs, timing.executionBudgetMs, observedSteps)
                                                    | Some(cpuMs, cpuIdleMs) ->
                                                        JpWorkHardDeadlineExpiredAfterCpuAndOperationStall(cpuMs, cpuIdleMs, observedSteps, operationIdleMs)
                                                    | None ->
                                                        JpWorkHardDeadlineExpiredAfterOperationStall(observedSteps, operationIdleMs)
                                        None, Some(ageMs, timing.executionBudgetMs, timing.executionBudgetPolicy, disposition)
                            else None, None
                        diagnostic, deferral, expiration)
                match diagnostic with
                | Some(ageMs, diagnosticBudgetMs, hardBudgetMs, budgetPolicy) ->
                    let workUnitId = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                    DiagJson.emitRecord {
                        kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitExecutionBudgetDiagnostic
                        job_id = jobId
                        work_unit_id = workUnitId
                        computation_kind_du = jpComputationIdentityKindText timing.computationIdentity
                        computation_key = jpComputationIdentityText timing.computationIdentity
                        computation_source = jpComputationIdentitySource timing.computationIdentity
                        authority_role_du = jpWorkAuthorityRoleText timing.authorityRole
                        site = jpComputationIdentitySource timing.computationIdentity
                        publication_stage_du = publicationStageText
                        publication_stage_age_ms = publicationStageAgeMs
                        publication_stage_transitions = publicationStageTransitions
                        age_ms = ageMs
                        diagnostic_budget_ms = diagnosticBudgetMs
                        hard_budget_ms = hardBudgetMs
                        budget_du = jpWorkExecutionBudgetPolicyText budgetPolicy
                        terminal_authority = false
                        authority = "independent_watchdog_diagnostic_boundary"
                        next = "continue_isolated_body_and_sample_cpu_before_hard_boundary"
                    }
                    match jpActiveOperationProfileSnapshot jobId with
                    | Some(steps, operationKind, operationSite, operationShape, topShapes, lastPhase, topPhases, recentPhases, recentPhaseFingerprint) ->
                        let cpuMsPresent, cpuMs =
                            match cpuProgressSample with
                            | Some value -> true, value
                            | None -> false, 0L
                        let checkpointPresent, checkpointRef, checkpointOrdinal, checkpointOperationCount, checkpointPhase, checkpointResumePointAuthority, checkpointResumeCapability, checkpointNodeId, checkpointResumeNodeAuthority, checkpointAgeMs =
                            match jpDeclaredBodyCheckpointSnapshot jobId (jpActiveWorkTimingNowMs()) with
                            | Some checkpoint ->
                                true, checkpoint.checkpointRefText, checkpoint.checkpointOrdinal, checkpoint.checkpointOperationCount,
                                checkpoint.checkpointResumePointText, checkpoint.checkpointResumePointAuthorityText, checkpoint.checkpointResumeCapabilityText,
                                checkpoint.checkpointResumeNodeId, checkpoint.checkpointResumeNodeAuthorityText, checkpoint.checkpointAgeMs
                            | None -> false, "", 0L, 0L, "", "", "", 0, "", 0L
                        DiagJson.emitRecord {
                            kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitStallBundle
                            job_id = jobId
                            work_unit_id = workUnitId
                            site = jpComputationIdentitySource timing.computationIdentity
                            age_ms = ageMs
                            diagnostic_budget_ms = diagnosticBudgetMs
                            hard_budget_ms = hardBudgetMs
                            cpu_ms_present = cpuMsPresent
                            cpu_ms = cpuMs
                            observed_steps_lower_bound = steps
                            last_operation_kind_du = operationKind
                            last_operation_site = operationSite
                            last_operation_shape_du = operationShape
                            last_operation_phase_du = lastPhase
                            top_operation_shapes_du = topShapes
                            top_operation_phases_du = topPhases
                            recent_operation_phases_du = recentPhases
                            recent_operation_phase_fingerprint = recentPhaseFingerprint
                            declared_body_checkpoint_present = checkpointPresent
                            declared_body_checkpoint_ref = checkpointRef
                            declared_body_checkpoint_ordinal = checkpointOrdinal
                            declared_body_checkpoint_operation_count = checkpointOperationCount
                            declared_body_checkpoint_phase_du = checkpointPhase
                            declared_body_checkpoint_resume_point_authority_du = checkpointResumePointAuthority
                            declared_body_checkpoint_resume_capability_du = checkpointResumeCapability
                            declared_body_checkpoint_node_id = checkpointNodeId
                            declared_body_checkpoint_resume_node_authority_du = checkpointResumeNodeAuthority
                            declared_body_checkpoint_age_ms = checkpointAgeMs
                            publication_stage_du = publicationStageText
                            publication_stage_age_ms = publicationStageAgeMs
                            authority = "single_diagnostic_threshold_compact_stall_bundle"
                            next = "compare_phase_and_step_fingerprint_before_any_deadline_change"
                        }
                        let operationsSinceCheckpoint =
                            if checkpointPresent then max 0L (steps - checkpointOperationCount) else 0L
                        let cpuDutyBp =
                            if cpuMsPresent && ageMs > 0L then min 10000L (cpuMs * 10000L / ageMs) else -1L
                        DiagJson.emit (
                            FastRuntimeFormat.format
                                "{\"kind\":\"jp_work_unit_stall_control_authority_audit\",\"job_id\":%d,\"work_unit_id\":%s,\"site\":%s,\"last_operation_kind_du\":%s,\"last_operation_phase_du\":%s,\"recent_operation_phase_fingerprint\":%s,\"observed_steps_lower_bound\":%d,\"cpu_duty_bp\":%d,\"publication_stage_du\":%s,\"publication_stage_transitions\":%d,\"checkpoint_present\":%b,\"checkpoint_operation_count\":%d,\"operations_since_checkpoint\":%d,\"checkpoint_age_ms\":%d,\"checkpoint_resume_capability_du\":%s,\"checkpoint_node_id\":%d,\"control_authority_inputs_du\":\"typed_work_identity+operation_phase_ring+publication_stage+checkpoint_capability\",\"site_authority\":false,\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"terminal_authority\":false,\"authority\":\"diagnostic_projection_only\",\"next\":\"compare_structural_progress_without_program_identity_special_cases\"}"
                                [| box jobId; box (DiagJson.esc workUnitId); box (DiagJson.esc (jpComputationIdentitySource timing.computationIdentity)); box (DiagJson.esc operationKind); box (DiagJson.esc lastPhase); box (DiagJson.esc recentPhaseFingerprint); box steps; box cpuDutyBp; box (DiagJson.esc publicationStageText); box publicationStageTransitions; box checkpointPresent; box checkpointOperationCount; box operationsSinceCheckpoint; box checkpointAgeMs; box (DiagJson.esc checkpointResumeCapability); box checkpointNodeId |])
                        match jpDeclaredBodyCheckpointReplayAssist jobId with
                        | Some(checkpointCapability, checkpointEvidence, observedCapability, observedEvidence, continuationAvailability, checkpointRef, checkpointNodeId, scheduled) ->
                            DiagJson.emitRecord
                                ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpDeclaredBodyCheckpointReplayAssist
                                   job_id = jobId
                                   work_unit_id = workUnitId
                                   checkpoint_ref = CompilerIdentityKernel.ContentDigest.text checkpointRef
                                   node_id = checkpointNodeId
                                   checkpoint_resume_capability_du = jpDeclaredBodyResumeCapabilityText checkpointCapability
                                   checkpoint_resume_evidence_du = jpDeclaredBodyResumeEvidenceText checkpointEvidence
                                   observed_resume_capability_du = jpDeclaredBodyResumeCapabilityText observedCapability
                                   observed_resume_evidence_du = jpDeclaredBodyResumeEvidenceText observedEvidence
                                   continuation_availability_du = jpDeclaredBodyContinuationAvailabilityText continuationAvailability
                                   scheduled = scheduled
                                   authority = "typed_checkpoint_prefers_executable_pc_and_requests_replay_only_for_unmaterialized_candidate"
                                   next = if scheduled then "observe_material_replay_delta_without_restarting_evaluator" else "resume_executable_pc_or_retain_checkpoint_without_parallel_rescue_front" }
                                 : JpDeclaredBodyCheckpointReplayAssistEvent)
                        | None -> ()
                    | None -> ()
                | None -> ()
                match deferral with
                | Some(ageMs, operationProgressGraceMs, boundedProgressExtensionDeadlineMs, occurrenceCount, disposition) ->
                    let isDeclaredCheckpointCycleHandoff =
                        match disposition with
                        | JpWorkHardDeadlineDeferredToPatternMissDeclaredCheckpointCycleCancellation(proof, observedSteps) ->
                            jpPublishDeclaredCheckpointCancellationSafePointHandoff jobId proof observedSteps
                            true
                        | _ -> false
                    let dispositionText = jpWorkHardDeadlineDispositionText disposition
                    let progressLeaseText =
                        if isDeclaredCheckpointCycleHandoff then
                            "StasisAuthorityHandoff(" + dispositionText + ")"
                        else
                            "Renewed(" + dispositionText + ")"
                    let absoluteAgeThresholdDu =
                        if isDeclaredCheckpointCycleHandoff then
                            "NotTerminalWhileTypedCheckpointCycleHandoffAwaitsOwnerSafePoint"
                        else
                            "DiagnosticOnlyWhileTypedProgressLeaseIsFresh"
                    let deferralAuthority =
                        if isDeclaredCheckpointCycleHandoff then
                            "typed_declared_checkpoint_cycle_stasis_handoff_to_pattern_miss_or_attempted_codegen_owner_safe_point"
                        else
                            "typed_renewable_progress_lease"
                    let deferralNext =
                        if isDeclaredCheckpointCycleHandoff then
                            "pattern_miss_owner_or_attempted_codegen_owner_consumes_cycle_handoff_at_next_bounded_safe_point"
                        else
                            "renew_while_typed_progress_remains_fresh_or_fail_closed_on_stasis"
                    DiagJson.emitRecord {
                        kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitHardDeadlineDeferred
                        job_id = jobId
                        work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                        computation_key = jpComputationIdentityText timing.computationIdentity
                        site = jpComputationIdentitySource timing.computationIdentity
                        publication_stage_du = publicationStageText
                        publication_stage_age_ms = publicationStageAgeMs
                        publication_stage_transitions = publicationStageTransitions
                        age_ms = ageMs
                        hard_budget_ms = timing.executionBudgetMs
                        operation_progress_grace_ms = operationProgressGraceMs
                        bounded_extension_deadline_ms = boundedProgressExtensionDeadlineMs
                        progress_lease_du = progressLeaseText
                        age_is_terminal_authority = false
                        absolute_age_threshold_du = absoluteAgeThresholdDu
                        observed_steps_lower_bound = timing.lastObservedOperationCount
                        phase_ring_liveness_du = jpOperationPhaseRingLivenessText phaseRingLiveness
                        occurrence_count = occurrenceCount
                        disposition_du = dispositionText
                        terminal_authority = false
                        authority = deferralAuthority
                        next = deferralNext
                    }
                | None -> ()
                match expiration with
                | Some(ageMs, _, _, _) when publicationStage = JpWorkPublicationCommitted ->
                    jpRemoveActiveWorkTiming jobId
                    let occurrenceCount, shouldEmit =
                        DiagJson.sparseLogDecision
                            "jp_work_publication_committed_timing_reaped"
                            64L
                    if shouldEmit then
                        DiagJson.emitRecord {
                            kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkPublicationCommittedTimingReaped
                            job_id = jobId
                            work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                            publication_stage_age_ms = publicationStageAgeMs
                            age_ms = ageMs
                            occurrence_count = occurrenceCount
                            terminal_authority = false
                            authority = "committed_publication_cannot_be_failed_by_stale_timing"
                            next = "continue_without_false_deadline"
                        }
                    false
                | Some(ageMs, budgetMs, budgetPolicy, deadlineDisposition) when jp_execution_deadline_claims.TryAdd(jobId, 0uy) ->
                    let workUnitId = CompilerKernelV2.WorkUnitIdOps.digestText item.workUnit
                    let policyText = jpWorkExecutionBudgetPolicyText budgetPolicy
                    let operationIdleMs = max 0L (nowMs - timing.lastOperationProgressAtMs)
                    let deadlineDispositionText = jpWorkHardDeadlineDispositionText deadlineDisposition
                    let executionStage, executionStageText, executionStageAgeMs, executionStageTransitions =
                        match JpMethodBodyStageAuthority.tryRead
                                timing.computationIdentity
                                timing.instantiationId with
                        | Some(stage, stageAgeMs, transitionCount) ->
                            Some stage, jpMethodBodyExecutionStageText stage, stageAgeMs, transitionCount
                        | None -> None, "Untracked", 0L, 0L
                    let cpuExclusiveMs, cpuAuthorityDu =
                        jpCpuTimeDelta timing.cpuStarted (jpCpuTimeSampleFor timing.cpuStarted)
                    let cpuMsPresent = Option.isSome cpuExclusiveMs
                    let cpuMsValue =
                        cpuExclusiveMs
                        |> Option.map CompilerKernelV2.Measured.value
                        |> Option.defaultValue 0L
                    let cpuAuthorityText =
                        CompilerKernelV2.CpuTimeAuthority.stableText cpuAuthorityDu
                    let wallExclusiveMs =
                        max 0L (ageMs - timing.blockedOnChildCompletedMs)
                    let executionActivityText =
                        jpCpuWallActivityFor wallExclusiveMs cpuExclusiveMs
                        |> jpCpuWallActivityText
                    let failureRef =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-work-execution-hard-deadline"
                            (workUnitId + "|job=" + string jobId + "|age_ms=" + string ageMs + "|budget_ms=" + string budgetMs + "|policy=" + policyText + "|publication_stage=" + publicationStageText)
                    let deadlineReason =
                        match publicationStage with
                        | JpWorkPublicationExecuting ->
                            match executionStage with
                            | Some stage -> JpWorkExecutionHardDeadline(budgetPolicy, stage)
                            | None -> JpWorkExecutionHardDeadlineUntracked budgetPolicy
                        | stage ->
                            JpWorkPublicationHardDeadline(
                                budgetPolicy,
                                CompilerKernelV2.OperationalReasonIdOps.create (jpWorkPublicationStageText stage))
                    let reason = jpWorkExecutionDeadlineReasonText deadlineReason
                    let checkpointPresent, checkpointRef, checkpointOrdinal, checkpointOperationCount, checkpointPhaseText, checkpointResumeCapability, checkpointNodeId, checkpointAgeMs =
                        match jpDeclaredBodyCheckpointSnapshot jobId nowMs with
                        | Some checkpoint ->
                            true, checkpoint.checkpointRefText, checkpoint.checkpointOrdinal, checkpoint.checkpointOperationCount,
                            checkpoint.checkpointResumePointText, checkpoint.checkpointResumeCapabilityText, checkpoint.checkpointResumeNodeId, checkpoint.checkpointAgeMs
                        | None -> false, "", 0L, 0L, "none", "none", 0, 0L
                    JpSpecializationWorklistAuthority.fail item.workNode failureRef
                    try
                        item.cancel (JpHostRequestedCancellation (CompilerKernelV2.OperationalReasonIdOps.create reason))
                        |> CompilerKernelV2.CompilerRuntimeKernel.toJob
                        |> startHopacJob
                    with _ -> ()
                    DiagJson.emitRecord {
                        kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitHardDeadlineExpired
                        job_id = jobId
                        work_unit_id = workUnitId
                        computation_key = jpComputationIdentityText timing.computationIdentity
                        site = jpComputationIdentitySource timing.computationIdentity
                        execution_stage_du = executionStageText
                        execution_stage_age_ms = executionStageAgeMs
                        execution_stage_transitions = executionStageTransitions
                        publication_stage_du = publicationStageText
                        publication_stage_age_ms = publicationStageAgeMs
                        publication_stage_transitions = publicationStageTransitions
                        age_ms = ageMs
                        wall_exclusive_ms = wallExclusiveMs
                        cpu_ms_present = cpuMsPresent
                        cpu_ms = cpuMsValue
                        cpu_authority_du = cpuAuthorityText
                        execution_activity_du = executionActivityText
                        budget_ms = budgetMs
                        budget_du = policyText
                        observed_steps_lower_bound = timing.lastObservedOperationCount
                        operation_idle_ms = operationIdleMs
                        phase_ring_liveness_du = jpOperationPhaseRingLivenessText phaseRingLiveness
                        declared_body_checkpoint_present = checkpointPresent
                        declared_body_checkpoint_ref = checkpointRef
                        declared_body_checkpoint_ordinal = checkpointOrdinal
                        declared_body_checkpoint_operation_count = checkpointOperationCount
                        declared_body_checkpoint_phase_du = checkpointPhaseText
                        declared_body_checkpoint_resume_capability_du = checkpointResumeCapability
                        declared_body_checkpoint_node_id = checkpointNodeId
                        declared_body_checkpoint_age_ms = checkpointAgeMs
                        deadline_disposition_du = deadlineDispositionText
                        deadline_timer_ref =
                            timing.deadlineTimer
                            |> CompilerKernelV2.PortableTimerOps.timerRef
                            |> CompilerIdentityKernel.ContentDigest.text
                        failure_ref = CompilerIdentityKernel.ContentDigest.text failureRef
                        promise_cancellation_requested = true
                        terminal_intent_du = "FailClosed"
                        authority = "typed_expired_progress_lease_receipt_precedes_process_failure_latch"
                        next = "mark_process_failure_latch_then_publish_typed_failclosed_candidate"
                    }
                    DiagJson.terminalFailureExitMarkRequested
                        (CompilerKernelV2.OperationalReasonIdOps.create reason)
                    DiagJson.publishTerminalOutcomeCandidateObserved
                        DiagJson.TerminalOutcomeCandidateSafetyWatchdogFailClosed
                        ("jp-work-execution-hard-deadline:" + CompilerIdentityKernel.ContentDigest.text failureRef)
                        workUnitId
                        reason
                    CompilerConsoleHud88.retryTerminalClosure ()
                    true
                | _ -> false
            else false

        let jpEmitInFlightSlowUnits nowMs =
            let thresholdMs = jpInFlightSlowThresholdMs
            let lastProgressMs = jp_progress_clock_read()
            let progressAgeMs = max 0L (nowMs - lastProgressMs)
            let progressDisposition =
                if progressAgeMs >= thresholdMs then JpInFlightGlobalProgressStalled progressAgeMs
                else JpInFlightGlobalProgressRecent progressAgeMs
            let progressDispositionText = jpInFlightProgressDispositionText progressDisposition
            for KeyValue(jobId, _) in jp_active_job_timings do
                jpTryExpireActiveWorkDeadline nowMs jobId |> ignore
            for KeyValue(jobId, startedAtMs) in jp_active_jobs do
                let ageMs = max 0L (nowMs - startedAtMs)
                if ageMs >= thresholdMs then
                    let ageBucket = jpInFlightSlowAgeBucket ageMs
                    if jpInFlightSlowAgeBucketShouldEmit jobId ageBucket then
                        let occurrenceCount = int64 (ageBucket + 1)
                        let mutable siteValue = Unchecked.defaultof<CompilerIdentityKernel.WorkSiteId>
                        let site =
                            if jp_active_job_sites.TryGetValue(jobId, &siteValue) then CompilerIdentityKernel.WorkSiteIdOps.text siteValue
                            else "unknown"
                        let workUnitId, bindingId, timingStartedAtMs, computationKind, computationKey, computationSource, instantiationRef, instantiationCount, memoProbe, authorityRole, cpuExclusiveMs, cpuAuthorityDu, blockedOnChildMs, childWaitCount, activeChildWait =
                            match jpActiveWorkTimingSnapshot jobId nowMs with
                            | Some(workUnitId, bindingId, timingStartedAtMs, computationKind, computationKey, computationSource, instantiationRef, instantiationCount, memoProbe, authorityRole, cpuExclusiveMs, cpuAuthorityDu, blockedOnChildMs, childWaitCount, activeChildWait) ->
                                workUnitId, bindingId, timingStartedAtMs, computationKind, computationKey, computationSource, instantiationRef, instantiationCount, memoProbe, authorityRole, cpuExclusiveMs, cpuAuthorityDu, blockedOnChildMs, childWaitCount, activeChildWait
                            | None ->
                                let cpuAuthority =
                                    JpCpuNoActiveTiming
                                    |> jpCpuTimeUnavailableReasonText
                                    |> CompilerKernelV2.OperationalReasonIdOps.create
                                    |> CompilerKernelV2.CpuTimeUnavailable
                                "", "", startedAtMs, "Anonymous", site, "unknown", "", 0, JpComputationMemoNotApplicable, JpSemanticProducer, None, cpuAuthority, 0L, 0, JpActiveChildWaitIdle
                        let admittedAtMs = jpWorkAdmissionTimingRead jobId timingStartedAtMs
                        let queueDelayMs = max 0L (timingStartedAtMs - admittedAtMs)
                        let admissionAgeMs = max 0L (nowMs - admittedAtMs)
                        let timingAgeMs = max 0L (nowMs - timingStartedAtMs)
                        let ageClockDeltaMs = abs (ageMs - timingAgeMs)
                        let ageBasis =
                            if ageClockDeltaMs <= 5L then JpInFlightPerUnitExecutionStart
                            else JpInFlightRegistryTimingMismatch ageClockDeltaMs
                        let wallExclusiveMs = max 0L (ageMs - blockedOnChildMs)
                        let cpuMsPresent = Option.isSome cpuExclusiveMs
                        let cpuMsValue =
                            cpuExclusiveMs
                            |> Option.map CompilerKernelV2.Measured.value
                            |> Option.defaultValue 0L
                        let cpuAuthorityText = CompilerKernelV2.CpuTimeAuthority.stableText cpuAuthorityDu
                        let executionActivityText =
                            jpCpuWallActivityFor wallExclusiveMs cpuExclusiveMs
                            |> jpCpuWallActivityText
                        let waitingOnChild =
                            match activeChildWait with
                            | JpActiveChildWaitRunning _ -> true
                            | JpActiveChildWaitIdle -> false
                        let childWaitRef, childPromiseRef, childProducerWorkId, childProducerBindingRef, childWaitDisposition, childWaitGraphDecision =
                            match activeChildWait with
                            | JpActiveChildWaitRunning(_, childWait) ->
                                CompilerIdentityKernel.ContentDigest.text childWait.waitRef,
                                CompilerIdentityKernel.ContentDigest.text childWait.promiseRef,
                                childWait.producerWorkId,
                                CompilerKernelV2.StableBindingId.text childWait.producerBindingId,
                                jpActiveChildWaitDispositionText childWait.disposition,
                                CompilerKernelV2.OperationalReasonIdOps.text childWait.dispositionId
                            | JpActiveChildWaitIdle -> "", "", 0L, "", "Idle", "None"
                        let mutable profiledItem = Unchecked.defaultof<JpWorkItem>
                        let mutable profiledTiming = Unchecked.defaultof<JpActiveWorkTiming>
                        if jp_active_work_items.TryGetValue(jobId, &profiledItem)
                           && jp_active_job_timings.TryGetValue(jobId, &profiledTiming) then
                            let runtimeEffectText =
                                match profiledItem.workNode.runtimeEffect with
                                | JpRuntimeEffectPure -> "Pure"
                                | JpRuntimeEffectRequired witness ->
                                    jpRuntimeEffectKindText witness.effectKind
                                    + "@" + jpRuntimeEffectScopeText witness.effectScope
                            let executionStageText, executionStageAgeMs, executionStageTransitions =
                                match JpMethodBodyStageAuthority.tryRead
                                        profiledTiming.computationIdentity
                                        profiledTiming.instantiationId with
                                | Some(stage, stageAgeMs, transitionCount) ->
                                    jpMethodBodyExecutionStageText stage, stageAgeMs, transitionCount
                                | None -> "Untracked", 0L, 0L
                            let publicationStageText, publicationStageAgeMs, publicationStageTransitions =
                                match jpActiveWorkPublicationStageSnapshot jobId nowMs with
                                | Some(stage, stageAgeMs, transitionCount) ->
                                    jpWorkPublicationStageText stage, stageAgeMs, transitionCount
                                | None -> "Untracked", 0L, 0L
                            let checkpointPresent, checkpointRef, checkpointOrdinal, checkpointOperationCount, checkpointPhase, checkpointResumePointAuthority, checkpointResumeCapability, checkpointNodeId, checkpointResumeNodeAuthority, checkpointAgeMs =
                                match jpDeclaredBodyCheckpointSnapshot jobId nowMs with
                                | Some checkpoint ->
                                    true, checkpoint.checkpointRefText, checkpoint.checkpointOrdinal, checkpoint.checkpointOperationCount,
                                    checkpoint.checkpointResumePointText, checkpoint.checkpointResumePointAuthorityText, checkpoint.checkpointResumeCapabilityText,
                                    checkpoint.checkpointResumeNodeId, checkpoint.checkpointResumeNodeAuthorityText, checkpoint.checkpointAgeMs
                                | None -> false, "", 0L, 0L, "none", "none", "none", 0, "none", 0L
                            DiagJson.emitRecord {
                                kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitInFlightStageProfile
                                job_id = jobId
                                work_unit_id = workUnitId
                                site = site
                                intent_du = jpSpecializationIntentText profiledItem.workNode.intent
                                runtime_effect_du = runtimeEffectText
                                execution_stage_du = executionStageText
                                execution_stage_age_ms = executionStageAgeMs
                                execution_stage_transitions = executionStageTransitions
                                publication_stage_du = publicationStageText
                                publication_stage_age_ms = publicationStageAgeMs
                                publication_stage_transitions = publicationStageTransitions
                                budget_du = jpWorkExecutionBudgetPolicyText profiledTiming.executionBudgetPolicy
                                diagnostic_budget_ms = profiledTiming.executionDiagnosticBudgetMs
                                budget_ms = profiledTiming.executionBudgetMs
                                age_ms = ageMs
                                wall_exclusive_ms = wallExclusiveMs
                                cpu_ms_present = cpuMsPresent
                                cpu_ms = cpuMsValue
                                cpu_authority_du = cpuAuthorityText
                                execution_activity_du = executionActivityText
                                blocked_on_child_ms = blockedOnChildMs
                                child_wait_count = childWaitCount
                                declared_body_checkpoint_present = checkpointPresent
                                declared_body_checkpoint_ref = checkpointRef
                                declared_body_checkpoint_ordinal = checkpointOrdinal
                                declared_body_checkpoint_operation_count = checkpointOperationCount
                                declared_body_checkpoint_phase_du = checkpointPhase
                                declared_body_checkpoint_resume_capability_du = checkpointResumeCapability
                                declared_body_checkpoint_node_id = checkpointNodeId
                                declared_body_checkpoint_age_ms = checkpointAgeMs
