        let jp_worker_population_core_limit =
            if CacheGeneration.isSequentialRequested() then 1
            else max 1 jp_dop
        let jp_exact_wait_worker_population_limit =
            if CacheGeneration.isSequentialRequested() then 1
            else jp_worker_population_core_limit * 2
        let jp_assist_max_concurrent_leases = max 1 (jp_worker_population_core_limit / 2)
        let jp_blocking_compensation_wave = jp_assist_max_concurrent_leases
        let jp_blocking_compensation_limit =
