        // pure work. Give it a bounded lane so four verifiers cannot occupy every
        // worker while ordinary semantic producers remain queued. Detached observer
        // verification remains lower priority than both semantic lanes.
        // External assessments showed that the three-verifier lane improved throughput
        // without allowing long declared bodies to consume an arbitrarily large host.
        // Keep that empirical bound explicit instead of scaling to core_count-1.
        let jp_declared_body_parallel_verifier_cap = 3

        let jpDeclaredBodyWorkerPolicy foregroundDepth =
            if foregroundDepth > 0 then
                JpDeclaredBodyForegroundPressureSingleFlight, 1
            elif jp_declared_body_retired_count = 0L then
                // A single exceptionally long first verifier must not serialize an
                // already-populated declared-body queue after foreground work drains.
                // Bootstrap with at most two verifiers; retirement receipts still own
                // every wider ramp decision.
                let queuedDeclaredBodies = jpSpecializationDeclaredBodyQueueDepth ()
                let bootstrapLimit =
                    if queuedDeclaredBodies >= 2 then
                        min 2 (max 1 (jp_worker_population_core_limit - 1))
                    else 1
                if bootstrapLimit > 1 then
                    JpDeclaredBodyBootstrapBoundedRamp(queuedDeclaredBodies, bootstrapLimit), bootstrapLimit
                else
                    JpDeclaredBodyBootstrapSingleFlight, 1
            else
                // One committed retirement receipt is enough to prove that the lane
                // can make forward progress.  Do not fall back to single-flight merely
                // because the first completed verifier was short: the remaining queue
                // may contain a much more expensive verifier that would otherwise
                // monopolize the only lane, as observed in the runtime evidence.
                let maximumVerifierLimit =
                    max 1 (min jp_declared_body_parallel_verifier_cap (jp_worker_population_core_limit - 1))
                let receiptRampLimit =
                    max 2 (1 + int (jp_declared_body_retired_count / 2L))
                let verifierLimit = min maximumVerifierLimit receiptRampLimit
                JpDeclaredBodyRetirementRamp(
                    jp_declared_body_retired_count,
                    jp_declared_body_long_retired_count,
                    verifierLimit),
                verifierLimit

