                let _, verifierLimit = jpDeclaredBodyWorkerPolicy foregroundDepth
                if jp_active_declared_body_workers < verifierLimit then
                    jp_active_declared_body_workers <- jp_active_declared_body_workers + 1
                    Some JpWorkerDeclaredBodyLaneGranted
                else None)

        let jpTryReserveObserverLane () =
            lock jp_worker_lane_gate (fun () ->
