        // ids are forbidden because they are not stable across replay or backends.
        let jp_method_rec_placeholder_ids : System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, ConsedNode<RData [] * Ty [] * Ty>> =
            System.Collections.Concurrent.ConcurrentDictionary<CompilerIdentityKernel.ContentDigest, ConsedNode<RData [] * Ty [] * Ty>>()

        let mutable jp_recursive_array_method_resolution_hook : Ty -> Ty -> unit =
            fun _ _ -> ()
    
        // MIGRATION: when generation invalidates, clear JP recursion placeholder cells and their reverse maps.

        CacheGeneration.registerOnInvalidate (fun _reason ->
            try
                jp_method_rec_placeholders.Clear()
                jp_method_rec_placeholder_keys.Clear()
                jp_method_rec_placeholder_ids.Clear()
            with _ -> ()
        )
    
    
    



        let jp_method_try_key_of_rec_placeholder (ty: Ty) : ConsedNode<RData [] * Ty [] * Ty> option =
            // Fast-path: exact placeholder Ty -> key mapping.
            match jp_method_rec_placeholder_keys.TryGetValue ty with
            | true, k -> Some k
            | false, _ ->
                // Round-trip path parses the content-addressed digest suffix.  The
                // digest text itself is the lookup key; it is never coerced to an int.
                let try_parse_id (s: string) : CompilerIdentityKernel.ContentDigest option =
                    let i = s.LastIndexOf '#'
                    if i <= 0 then None
                    else
                        let j0 = s.LastIndexOf ')'
                        let j = if j0 > i then j0 else s.Length
                        let digestText = s.Substring(i+1, j-i-1)
                        CompilerIdentityKernel.ContentDigest.tryParse digestText
                match ty with
                | YSymbol s ->
                    match try_parse_id s with
                    | Some id ->
                        match jp_method_rec_placeholder_ids.TryGetValue id with
                        | true, k -> Some k
                        | false, _ -> None
                    | None -> None
                | _ -> None
    

        let jp_method_deref_rec_placeholder (ty: Ty) : Ty =
            match jp_method_try_key_of_rec_placeholder ty with
            | Some k ->
                let curGen = CacheGeneration.current()
                let mutable liveCell = Unchecked.defaultof<JpMethodRecPlaceholderCell>
                let cell =
                    if jp_method_rec_placeholders.TryGetValue(k, &liveCell) then liveCell
                    else
                        // Generation invalidation clears the forward and reverse maps independently.
                        // A reverse-map hit followed by a missing cell is therefore a stale observation,
                        // not a semantic failure.  Feed it through the existing stale-generation fallback.
                        JpMethodRecPlaceholderCell(System.Int64.MinValue, ty, ty)
    

                // Always compute the safe-annotation fallback once; we also apply it when the placeholder is stale.
                // Without this, a placeholder from a previous cache generation can leak as a term-level DV and explode later
                // as an apply-mismatch (the .JPMethodRecPlaceholder(...) crash seen in MIGRATION logs).
                let (_, _, ret_ty) = k.node
                let is_hard_primitive_like (t: Ty) =
                    match t with
                    | YLit _ | YPrim _ -> true
                    | _ -> false
                let is_jp_placeholder_like (t: Ty) =
                    match tryDecodeJpRecPlaceholder t with
                    | Some JpMethodRecPlaceholder
                    | Some JpTypeRecPlaceholder -> true
                    | _ -> false
                let fallback () =
                    // allow non-primitive annotated return types to break recursion, but never substitute primitives.
                    if is_jp_placeholder_like ret_ty || is_hard_primitive_like ret_ty then ty else ret_ty
    

                if cell.gen <> curGen then
                    // Stale generation: treat as unresolved placeholder for this retry attempt.
                    // Critical: still apply fallback so the stale placeholder cannot leak into term evaluation.
                    fallback ()
                else
                    let v = cell.v
                    if v = cell.ph then
                        // par: conservative fallback. Only trust annotated return types that are
                        // union-ish; returning a primitive here (ex: i32) can create spurious EJP0007 apply-mismatch.
                        fallback ()
                    else v
            | None -> ty
    

        let ty_is_jp_method_rec_placeholder (ty: Ty) : bool =
            match jp_method_try_key_of_rec_placeholder ty, tryDecodeJpRecPlaceholder ty with
            | Some _, _
            | _, Some JpMethodRecPlaceholder -> true
            | _ -> false
    

        let ty_is_jp_type_rec_placeholder (ty: Ty) : bool =
            match tryDecodeJpRecPlaceholder ty with
            | Some JpTypeRecPlaceholder
            | Some JpArrayElementRecPlaceholder -> true
            | _ -> false
    

        let ty_is_jp_method_unknown_ret_placeholder (ty: Ty) : bool =
            match tryDecodeJpRecPlaceholder ty with
            | Some JpMethodUnknownReturn -> true
            | _ -> false
    
    


        let ty_eq_allow_jp_placeholders_with_nominal_authority
            nominalAuthority
            (a: Ty)
            (b: Ty)
            : bool =
            // Stack-safe structural comparison. JP recursion placeholders remain wildcards,
            // while the caller selects whether nominal equality is compatibility-by-name or exact identity.
            let pending = System.Collections.Generic.Stack<struct (Ty * Ty)>()
            let mutable equal = true
            let mutable steps = 0
            let maxSteps = 1000000
            pending.Push(struct (a, b))
            while equal && pending.Count > 0 do
                steps <- steps + 1
                if steps > maxSteps then
                    equal <- false
                else
                    let struct (left0, right0) = pending.Pop()
                    if ty_is_jp_method_rec_placeholder left0
                       || ty_is_jp_method_rec_placeholder right0
                       || ty_is_jp_type_rec_placeholder left0
                       || ty_is_jp_type_rec_placeholder right0
                       || ty_is_jp_method_unknown_ret_placeholder left0
                       || ty_is_jp_method_unknown_ret_placeholder right0 then
                        ()
                    else
                        let left = jp_method_deref_rec_placeholder left0
                        let right = jp_method_deref_rec_placeholder right0
                        if ty_is_jp_method_rec_placeholder left
                           || ty_is_jp_method_rec_placeholder right
                           || ty_is_jp_type_rec_placeholder left
                           || ty_is_jp_type_rec_placeholder right
                           || ty_is_jp_method_unknown_ret_placeholder left
                           || ty_is_jp_method_unknown_ret_placeholder right then
                            ()
                        else
                            match left, right with
                            | YVoid, YVoid
                            | YB, YB
                            | YForall, YForall
                            | YExists, YExists -> ()
                            | YLit x, YLit y ->
                                if x <> y then equal <- false
                            | YSymbol x, YSymbol y ->
                                if x <> y then equal <- false
                            | YPrim x, YPrim y ->
                                if x <> y then equal <- false
                            | YPair(a1,a2), YPair(b1,b2)
                            | YApply(a1,a2), YApply(b1,b2) ->
                                pending.Push(struct (a2, b2))
                                pending.Push(struct (a1, b1))
                            | YFun(a1,a2,kind1), YFun(b1,b2,kind2) ->
                                if kind1 <> kind2 then equal <- false
                                else
                                    pending.Push(struct (a2, b2))
                                    pending.Push(struct (a1, b1))
                            | YArray a1, YArray b1 ->
                                pending.Push(struct (a1, b1))
                            | YLayout(a1,l1), YLayout(b1,l2) ->
                                if l1 <> l2 then equal <- false
                                else pending.Push(struct (a1, b1))
                            | YTypeFunction(body1, types1, termStack1, typeStack1), YTypeFunction(body2, types2, termStack2, typeStack2) ->
                                match nominalAuthority with
                                | JpTypeNominalNameCompatibility -> ()
                                | JpTypeNominalExactIdentity ->
                                    if body1 <> body2
                                       || termStack1 <> termStack2
                                       || typeStack1 <> typeStack2
                                       || types1.Length <> types2.Length then
                                        equal <- false
                                    else
                                        for index = 0 to types1.Length - 1 do
                                            if equal then pending.Push(struct (types1.[index], types2.[index]))
                            | YNominal n1, YNominal n2 ->
                                if not (jpTypeNominalEqual nominalAuthority n1 n2) then equal <- false
                            | YMetavar id1, YMetavar id2 ->
                                match nominalAuthority with
                                | JpTypeNominalNameCompatibility ->
                                    // show_ty historically rendered every unresolved metavar as '?'.
                                    ()
                                | JpTypeNominalExactIdentity ->
                                    if id1 <> id2 then equal <- false
                            | YRecord fields1, YRecord fields2 ->
                                let items1 = fields1 |> Map.toArray
                                let items2 = fields2 |> Map.toArray
                                if items1.Length <> items2.Length then equal <- false
                                else
                                    for index = 0 to items1.Length - 1 do
                                        if equal then
                                            let key1, value1 = items1.[index]
                                            let key2, value2 = items2.[index]
                                            if key1 <> key2 then equal <- false
                                            else pending.Push(struct (value1, value2))
                            | YUnion union1, YUnion union2 ->
                                let view1 = union_view union1
                                let view2 = union_view union2
                                let items1 = view1.cases |> Map.toArray
                                let items2 = view2.cases |> Map.toArray
                                if (nominalAuthority = JpTypeNominalExactIdentity && view1.layout <> view2.layout)
                                   || items1.Length <> items2.Length then
                                    equal <- false
                                else
                                    for index = 0 to items1.Length - 1 do
                                        if equal then
                                            let key1, value1 = items1.[index]
                                            let key2, value2 = items2.[index]
                                            if key1 <> key2 then equal <- false
                                            else pending.Push(struct (value1, value2))
                            | YMacro macro1, YMacro macro2 ->
                                let items1 = macro1 |> List.toArray
                                let items2 = macro2 |> List.toArray
                                if items1.Length <> items2.Length then equal <- false
                                else
                                    for index = 0 to items1.Length - 1 do
                                        if equal then
                                            match items1.[index], items2.[index] with
                                            | Text text1, Text text2 ->
                                                if text1 <> text2 then equal <- false
                                            | Type type1, Type type2
                                            | TypeLit type1, TypeLit type2 ->
                                                pending.Push(struct (type1, type2))
                                            | Type type1, TypeLit type2
                                            | TypeLit type1, Type type2 ->
                                                match nominalAuthority with
                                                | JpTypeNominalNameCompatibility -> pending.Push(struct (type1, type2))
                                                | JpTypeNominalExactIdentity -> equal <- false
                                            | _ -> equal <- false
                            | _ ->
                                match nominalAuthority with
                                | JpTypeNominalExactIdentity ->
                                    equal <- false
                                | JpTypeNominalNameCompatibility ->
                                    // Preserve the historical opaque compatibility edge only for callers
                                    // that explicitly selected name-compatible nominal authority.
                                    equal <- show_ty left = show_ty right
            equal

        let ty_eq_allow_jp_placeholders (a: Ty) (b: Ty) : bool =
            ty_eq_allow_jp_placeholders_with_nominal_authority
                JpTypeNominalNameCompatibility
                a b

        let ty_eq_allow_jp_placeholders_exact_nominals (a: Ty) (b: Ty) : bool =
            ty_eq_allow_jp_placeholders_with_nominal_authority
                JpTypeNominalExactIdentity
                a b
    
    
    
    
    





        let jp_method_rec_placeholder (key: ConsedNode<RData [] * Ty [] * Ty>) (jp: string) : Ty =
            let curGen = CacheGeneration.current()
            let cell =
                jp_method_rec_placeholders.GetOrAdd(
                    key,
                    System.Func<ConsedNode<RData [] * Ty [] * Ty>, JpMethodRecPlaceholderCell>(fun key ->
                        let placeholderId = jpMethodRecPlaceholderId key jp curGen
                        let placeholderDigest = jpMethodRecPlaceholderIdDigest placeholderId
                        let idText = jpMethodRecPlaceholderIdText placeholderId
                        let ph = YSymbol (sprintf "JPMethodRecPlaceholder(par;%s#%s)" jp idText)
                        jp_method_rec_placeholder_keys.TryAdd(ph, key) |> ignore
                        jp_method_rec_placeholder_ids.TryAdd(placeholderDigest, key) |> ignore
                        JpMethodRecPlaceholderCell(curGen, ph, ph)
                    )
                )
            if cell.gen = curGen then cell.v
            else
                // Stale cell from a previous generation: reset to placeholder so the retry can re-infer deterministically.
                let resetCell = JpMethodRecPlaceholderCell(curGen, cell.ph, cell.ph)
                jp_method_rec_placeholders.AddOrUpdate(key, resetCell, (fun _ old -> if old.gen = curGen then old else resetCell)) |> ignore
                resetCell.v
    

        let jp_method_resolve_rec_placeholder (key: ConsedNode<RData [] * Ty [] * Ty>) (ty: Ty) : unit =
            // par: generation-aware placeholder resolution + anti-clobber.
            // We still keep the 'hard primitive vs expected non-primitive' guard, but we also prevent a hard primitive (ex: i32)
            // from overwriting a richer resolved type within the same generation (a common source of spurious EJP0007 apply-mismatch).
            let is_primitive_like (t: Ty) =
                match t with
                | YVoid | YB | YLit _ | YPrim _ -> true
                | _ -> false
            let is_hard_primitive_like (t: Ty) =
                match t with
                | YB | YLit _ | YPrim _ -> true
                | _ -> false
            let is_jp_method_placeholder (t: Ty) =
                match tryDecodeJpRecPlaceholder t with
                | Some JpMethodRecPlaceholder -> true
                | _ -> false
    

            let is_unknown_ret (t: Ty) = isJpMethodUnknownReturnType t
    

            let (_, _, expected_ret_ty) = key.node
            let curGen = CacheGeneration.current()
    

            if is_hard_primitive_like ty && not (is_primitive_like expected_ret_ty) && not (is_jp_method_placeholder expected_ret_ty) && not (is_unknown_ret expected_ret_ty) then
                if jp_diag_verbose then
                    let jp_name =
                        match jp_method_key_names.TryGetValue key with
                        | true, n -> n
                        | _ -> "<unknown>"
                    let snap = jp_diag_snapshot_short (sprintf "[spiral_compiler] EJP0007 guard (jp_resolve_hard_primitive) jp=%s" jp_name)
                    DiagSidecar.emit (
                        FastRuntimeFormat.format "[spiral_compiler] EJP0007 guard: refused cementing hard primitive\n      jp=%s\n      expected_ret=%s\n      got=%s\n      key=%s\n    %s" [| box jp_name; box (show_ty expected_ret_ty); box (show_ty ty); box (FastRuntimeFormat.objectText (box key)); box snap |]
                    )
                ()
            else
                // Add case should be unreachable in normal flow (placeholder is created first), but keep it safe.
                let addCell = JpMethodRecPlaceholderCell(curGen, ty, ty)
                let resolvedCell =
                    jp_method_rec_placeholders.AddOrUpdate(
                        key,
                        addCell,
                        (fun _ old ->
                            let ph = old.ph
                            let oldv =
                                if old.gen = curGen then old.v
                                else ph // stale generation: treat as unresolved
                            // Do not allow a hard primitive to clobber a richer type within the same generation.
                            if is_hard_primitive_like ty && oldv <> ph && not (is_hard_primitive_like oldv) then
                                JpMethodRecPlaceholderCell(curGen, ph, oldv)
                            else
                                JpMethodRecPlaceholderCell(curGen, ph, ty)
                        )
                    )
                jp_recursive_array_method_resolution_hook resolvedCell.ph resolvedCell.v
    

    
    


        let jp_method_stack_preview (stack: System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>) =
            try
                stack
                |> Seq.truncate 16
                |> Seq.map (fun k ->
                    match jp_method_key_names.TryGetValue k with
                    | true, name -> name
                    | _ -> FastRuntimeFormat.objectText (box k))
                |> Seq.toArray
                |> fun a -> System.String.Join(" ; ", a)
            with _ -> "<unavailable>"
    

        let jp_type_stack_preview (stack: System.Collections.Generic.HashSet<ConsedNode<Ty []>>) =
            try
                stack
                |> Seq.truncate 16
                |> Seq.map (fun k -> FastRuntimeFormat.objectText (box k))
                |> Seq.toArray
                |> fun a -> System.String.Join(" ; ", a)
            with _ -> "<unavailable>"
    

        let  trace_frame_short (x: Range) =
            let line = (fst x.range).line + 1
            let col = (fst x.range).character + 1
            FastRuntimeFormat.format "%s:%d:%d" [| box x.path; box line; box col |]
    
        /// MIGRATION: Concise trace frame: filename only (no directory), line:col

        let  trace_frame_concise (x: Range) =
            let filename = System.IO.Path.GetFileName(x.path)
            let line = (fst x.range).line + 1
            let col = (fst x.range).character + 1
            FastRuntimeFormat.format "%s:%d:%d" [| box filename; box line; box col |]
    

        let  trace_frame_rust (x: Range) =
            let (p0, p1) = x.range
            FastRuntimeFormat.format "%s:({ line = %d; character = %d }, { line = %d; character = %d })" [| box x.path; box (p0.line + 1); box (p0.character + 1); box (p1.line + 1); box (p1.character + 1) |]
    

        let trace_dedup (xs: Trace) =
            let rec loop (last: Range option) (acc: Range list) (xs: Trace) =
                match xs with
                | [] -> List.rev acc
                | x :: rest ->
                    match last with
                    | Some y when x.path = y.path && fst x.range = fst y.range -> loop last acc rest
                    | _ -> loop (Some x) (x :: acc) rest
            loop None [] xs
    

        let trace_to_string_short (xs: Trace) =
            let frames = trace_dedup xs |> List.map trace_frame_short
            if frames.IsEmpty then "<no-trace>"
            else
                let top = if frames.Length > 8 then frames |> List.take 8 else frames
                System.String.Join(" <- ", top)
    
        /// MIGRATION: Concise trace string: filename only (no full paths), line:col, max 20 frames

        let trace_to_string_concise (xs: Trace) =
            let frames = trace_dedup xs |> List.map trace_frame_concise
            if frames.IsEmpty then "<no-trace>"
            else
                let maxFrames = 20
                let shown = if frames.Length > maxFrames then frames |> List.take maxFrames else frames
                let body =
                    shown
                    |> List.mapi (fun i s -> sprintf "   %2d: %s" (i + 1) s)
                    |> String.concat "\n"
                if frames.Length > shown.Length then body + sprintf "\n   ... (+%d)" (frames.Length - shown.Length)
                else body
    

        let trace_to_string_full (xs: Trace) =
            let frames = trace_dedup xs |> List.map trace_frame_rust
            if frames.IsEmpty then "<no-trace>"
            else
                let maxFrames = 200
                let shown = if frames.Length > maxFrames then frames |> List.take maxFrames else frames
                let body =
                    shown
                    |> List.mapi (fun i s -> sprintf "  %2d: %s" (i + 1) s)
                    |> String.concat "\n"
                if frames.Length > shown.Length then body + sprintf "\n  ... (%d more)" (frames.Length - shown.Length)
                else body
    

        let record_jp_diag (jp_name: string option) (trace: Trace) : JpSpawnContext =
            let name = defaultArg jp_name "<anon>"
            let context = jpSpawnContextCreate name
            let nameId = JpNameIdOps.create name
            jp_name_counts.AddOrUpdate(nameId, 1, (fun _ v -> v + 1)) |> ignore
            jp_name_traces.AddOrUpdate(nameId, trace, (fun _ _ -> trace)) |> ignore
            context

        let record_jp_diag_method
            (key: ConsedNode<RData [] * Ty [] * Ty>)
            (jp_name: string option)
            (trace: Trace)
            : JpSpawnContext =
            DiagSidecar.emit (sprintf "[spiral_compiler] jp.method tag=%d name=%s" key.tag (defaultArg jp_name "<anon>"))
            let context = record_jp_diag jp_name trace
            let name = defaultArg jp_name "<anon>"
            jp_method_key_names.AddOrUpdate(key, name, (fun _ _ -> name)) |> ignore
            jp_method_key_traces.AddOrUpdate(key, trace, (fun _ _ -> trace)) |> ignore
            context
    

        let record_jp_diag_type (key: ConsedNode<Ty []>) (trace: Trace) : JpSpawnContext =
            DiagSidecar.emit (sprintf "[spiral_compiler] jp.type tag=%d" key.tag)
            let context = record_jp_diag (Some "<type>") trace
            jp_type_key_traces.AddOrUpdate(key, trace, (fun _ _ -> trace)) |> ignore
            context
    

        let mutable diag_last_ms = 0L
        let mutable diag_last_wait : string = ""
        DiagLastWait.reset ()
    

        let  get_private_bytes () =
            try
                System.Diagnostics.Process.GetCurrentProcess().PrivateMemorySize64
            with _ -> 0L
    

        let  diag_specs_total () =
            let mutable total = 0
            for KeyValue(_, (dict, _, _)) in join_point_method do
                let dict = (dict : System.Collections.Concurrent.ConcurrentDictionary<_,_>)
                total <- total + dict.Count
            for KeyValue(_, (dict, _, _)) in join_point_closure do
                let dict = (dict : System.Collections.Concurrent.ConcurrentDictionary<_,_>)
                total <- total + dict.Count
            for KeyValue(_, (dict, _, _)) in join_point_type do
                let dict = (dict : System.Collections.Concurrent.ConcurrentDictionary<_,_>)
                total <- total + dict.Count
            total
    

        let diag_snapshot_impl (reason: string) (include_top_traces: bool) =
    

            let elapsed_ms = peval_sw.ElapsedMilliseconds
            let pb = get_private_bytes ()
            let gc_total = System.GC.GetTotalMemory(false)
            let server_gc =
                try System.Runtime.GCSettings.IsServerGC
                with _ -> false
    

            let mutable method_groups = 0
            let mutable method_specs = 0
            let mutable closure_groups = 0
            let mutable closure_specs = 0
            let mutable type_groups = 0
            let mutable type_specs = 0
            let events_total, events_retired = CompilerKernelV2.SemanticWorkLedgerAuthority.counts ()
            let events_not_set = max 0 (events_total - events_retired)
            // Diagnostics consume the exact-once semantic ledger rather than polling IVars.
            for KeyValue(_, (dict, _, _)) in join_point_method do
                let dict = (dict : System.Collections.Concurrent.ConcurrentDictionary<_, Hopac.IVar<_>>)
                method_groups <- method_groups + 1
                method_specs <- method_specs + dict.Count
    

            for KeyValue(_, (dict, _, _)) in join_point_closure do
                let dict = (dict : System.Collections.Concurrent.ConcurrentDictionary<_, Hopac.IVar<_>>)
                closure_groups <- closure_groups + 1
                closure_specs <- closure_specs + dict.Count
    

            for KeyValue(_, (dict, _, _)) in join_point_type do
                let dict = (dict : System.Collections.Concurrent.ConcurrentDictionary<_,_>)
                type_groups <- type_groups + 1
                type_specs <- type_specs + dict.Count
    
    
    



            let entries0 : System.Collections.Generic.KeyValuePair<JpNameId,int>[] = jp_name_counts.ToArray()
            let entries = entries0 |> Array.sortByDescending (fun kv -> kv.Value)
    

            let top_names =
                let sbn = System.Text.StringBuilder()
                let n = min 20 entries.Length
                for i = 0 to n - 1 do
                    let kv = entries.[i]
                    let nameId = kv.Key
                    let name = JpNameIdOps.text nameId
                    let count = kv.Value
                    let mutable tr = ""
                    match jp_name_traces.TryGetValue nameId with
                    | true, t -> tr <- trace_to_string_short t
                    | _ -> ()
                    if i > 0 then sbn.Append("; ") |> ignore
                    if tr <> "" then sbn.AppendFormat("{0}={1} @ {2}", name, count, tr) |> ignore
                    else sbn.AppendFormat("{0}={1}", name, count) |> ignore
                sbn.ToString()
    

            let top_traces =
                if include_top_traces then
                    let sbt = System.Text.StringBuilder()
                    let n = min 5 entries.Length
                    for i = 0 to n - 1 do
                        let kv = entries.[i]
                        let nameId = kv.Key
                        let name = JpNameIdOps.text nameId
                        let count = kv.Value
                        let tr =
                            match jp_name_traces.TryGetValue nameId with
                            | true, t -> trace_to_string_concise t
                            | _ -> "<no trace>"
                        sbt.AppendFormat("  - {0} ({1})\n{2}\n", name, count, tr) |> ignore
                    sbt.ToString()
                else ""
            let sb = System.Text.StringBuilder()
            sb.AppendLine("SPIRAL PEVAL DIAG") |> ignore
            sb.AppendFormat("  reason={0}", reason) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  elapsed_ms={0}", elapsed_ms) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  private_bytes={0}", pb) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  gc_total_bytes={0}", gc_total) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  server_gc={0}", server_gc) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  workers={0} (ProcessorCount={1} affinity={2} authority={3})", jp_dop, jp_environment_processor_count, jp_affinity_processor_count, jpProcessorCapacityAuthorityText jp_processor_capacity_authority) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  jp_sched_mode={0}", (if jp_use_threadpool then "threadpool" else "custom")) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  jp_parallel_enabled={0} jp_parallel_effective={1} jp_sequential_requested={2} quiescence_authority=operational_graph", jp_parallel_enabled, (jp_parallel_effective()), CacheGeneration.isSequentialRequested ()) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  jp_total_started={0}", ((jpWorkLedgerRead()).totalStarted |> CompilerKernelV2.Measured.value)) |> ignore; sb.AppendLine() |> ignore
            // MIGRATION: Hopac-based metrics (no custom thread pool)
            sb.AppendFormat("  pending_jobs={0} hopac_scheduler=active", (jpSpecializationQueueDepth ()) + jp_active_jobs.Count) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  jp_method_groups={0} jp_method_specs={1}", method_groups, method_specs) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  jp_closure_groups={0} jp_closure_specs={1}", closure_groups, closure_specs) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  jp_type_groups={0} jp_type_specs={1}", type_groups, type_specs) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  jp_events_total={0} jp_events_not_set={1}", events_total, events_not_set) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  cache_generation={0}", CacheGeneration.current ()) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  suspect_keys={0}", SuspectCache.currentCount ()) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  bitmamba={0}", BitMamba.getSummary ()) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  loopguard={0}", LoopSpecializationGuard.getSummary ()) |> ignore; sb.AppendLine() |> ignore
            let reasons =
                try CacheGeneration.getRecentReasons () |> List.truncate 5 |> String.concat " | "
                with _ -> ""
            if reasons <> "" then
                sb.AppendFormat("  cache_invalidation_reasons={0}", reasons) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  last_wait={0}", diag_last_wait) |> ignore; sb.AppendLine() |> ignore
            sb.AppendFormat("  top_jp_names={0}", top_names) |> ignore; sb.AppendLine() |> ignore
            if include_top_traces then
                sb.AppendLine("  top_jp_traces=") |> ignore
                if top_traces <> "" then sb.AppendLine(top_traces) |> ignore
            sb.ToString()

        let diag_snapshot (reason: string) = diag_snapshot_impl reason jp_diag_include_top_traces
        let diag_snapshot_full (reason: string) = diag_snapshot_impl reason true

    
    


        let diag_snapshot_short (reason: string) =
            // MIGRATION: single-line, bounded diagnostic string for stderr / exceptions.
            // Full snapshot is captured via DiagSidecar when force/verbose triggers.
            let elapsed_ms = peval_sw.ElapsedMilliseconds
            let pb = try System.Diagnostics.Process.GetCurrentProcess().PrivateMemorySize64 with _ -> 0L
            let gc_total = try GC.GetTotalMemory(false) with _ -> 0L
            let gen = CacheGeneration.current()
            let pend = (jpSpecializationQueueDepth ()) + jp_active_jobs.Count
            let seq = CacheGeneration.isSequentialRequested ()
            let jpExtra0 = try jp_extra_provider () with _ -> ""
            let jpExtra =
                if System.String.IsNullOrEmpty jpExtra0 then ""
                else " " + (jpExtra0.Replace("\r", " ").Replace("\n", " "))
            FastRuntimeFormat.format "DIAG reason=%s elapsed_ms=%d gen=%d pending=%d seq=%b private_bytes=%d gc_total_bytes=%d last_wait=%s%s" [| box reason; box elapsed_ms; box gen; box pend; box seq; box pb; box gc_total; box diag_last_wait; box jpExtra |]
        let diag_write_err (s: string) =
            // Keep diagnostic mirrors JSONL-safe; no raw stderr text in the compiler log.
            if not (System.String.IsNullOrEmpty s) then
                let msg = diag_json_compact 768 s
                try
                    DiagJson.emit (
                        sprintf "{\"kind\":\"peval_diag_short\",\"msg\":%s,\"jsonl_diag\":true,\"plain_text_suppressed\":true,\"single_flight\":1,\"next\":\"continue_or_terminal_timeout_gate\"}"
                            (DiagJson.esc msg))
                with _ -> ()


        let diag_print (force: bool) (reason: string) =
            let now = peval_sw.ElapsedMilliseconds
            if force || (diag_period_ms > 0L && now - diag_last_ms >= diag_period_ms) then
                diag_last_ms <- now
                if force || jp_diag_verbose then
                    let snap_full = diag_snapshot reason
                    let _ = diag_write_file ("diag_" + reason) snap_full
                    DiagSidecar.emit snap_full
                    diag_write_err (diag_snapshot_short reason)
                else
                    let snap = diag_snapshot_short reason
                    DiagSidecar.emit snap
                    diag_write_err snap
        let  get_private_mb () =
            int64 (System.Diagnostics.Process.GetCurrentProcess().PrivateMemorySize64 / 1024L / 1024L)
    

        let peval_abort (reason: string) =
            diag_print true reason
            let full = diag_snapshot_full reason
            let diag_file = diag_write_file ("peval_abort_" + reason) full
            match diag_file with
            | Some p -> DiagSidecar.emit ("diag_file=" + p)
            | None -> ()
            if jp_diag_stderr_full then
                try
                    DiagJson.emit (
                        sprintf "{\"kind\":\"peval_diag_full\",\"reason\":%s,\"msg\":%s,\"jsonl_diag\":true,\"plain_text_suppressed\":true,\"single_flight\":1,\"next\":\"continue_or_terminal_timeout_gate\"}"
                            (DiagJson.esc reason) (DiagJson.esc (diag_json_compact 4096 full)))
                with _ -> ()
            let timeoutAbort = pevalAbortReasonFor (CompilerKernelV2.OperationalReasonIdOps.create reason) = PevalAbortTimedOut
            if timeoutAbort then
                try
                    let q = try EvalWorklist.replayQueueDepth() with _ -> -1
                    let a = try EvalWorklist.replayDriverActiveDepthValue() with _ -> -1
                    let p = try EvalWorklist.pendingCount() with _ -> -1
                    let py = try EvalWorklist.hasProgressYield() with _ -> false
                    let mdActive = try DiagJson.ownerDebtLiveWorkTieBreakerMaterialDeltaActiveNow() with _ -> false
                    let mdCount = try DiagJson.ownerDebtLiveWorkTieBreakerMaterialDeltaCountNow() with _ -> -1L
                    let tbCount = try DiagJson.ownerDebtLiveWorkTieBreakerCountNow() with _ -> -1L
                    let injActive = try DiagJson.ownerDebtLiveWorkTieBreakerInjectionActiveNow() with _ -> false
                    let injCount = try DiagJson.ownerDebtLiveWorkTieBreakerInjectedCountNow() with _ -> -1L
                    let short = diag_snapshot_short reason
                    DiagJson.emitTerminalJsonDurableAndExitSingleFlight DiagJson.ObserverProjectionPevalTimeoutOwnerDebtDrainDeadline (
                        FastRuntimeFormat.format "{\"kind\":\"terminal_peval_timeout_owner_debt_drain_deadline_exit\",\"reason\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"progress_yield_pending\":%b,\"recent_material_delta_active\":%b,\"recent_material_delta_count\":%d,\"productive_tie_breaker_active\":%b,\"productive_tie_breaker_count\":%d,\"tie_breaker_attempt_count\":%d,\"semantic_tie_breaker_progress_du\":\"SemanticTieBreaker(PevalDeadlineAfterBoundedDrain)\",\"terminal_quorum_after_timeout_du\":\"TerminalQuorum(peval_timeout_after_owner_debt_drain_deadline)\",\"root_promise_status_du\":\"RootPromiseFailed(peval_timeout_after_owner_debt_drain_deadline)\",\"root_complete_await_contract_du\":\"RootCompleteAwaitArmed(reason=peval_timeout_after_owner_debt_drain_deadline)\",\"root_complete_exit_policy_du\":\"fail_closed_after_peval_timeout_owner_debt_drain_deadline\",\"diag_short\":%s,\"plain_text_suppressed\":true,\"terminal_collapse_to_build_error_trace\":true,\"finish_fast_terminal\":true,\"single_flight\":1,\"next\":\"await_native_root_complete_alt\"}" [| box (DiagJson.esc reason); box p; box q; box a; box py; box mdActive; box mdCount; box injActive; box injCount; box tbCount; box (DiagJson.esc short) |])
                with _ -> ()
            let short = diag_snapshot_short reason
            let msg =
                match diag_file with
                | Some p -> short + " diag_file=" + p
                | None -> short
            raise (System.Exception(msg))
    

        let diag_soft_abort (where: string) (reason: string) =
            // MIGRATION: do not disable parallelism on soft diagnostic triggers; keep full concurrency and just emit snapshots.
            let r = sprintf "soft_abort where=%s reason=%s" where reason
            DiagSidecar.emit ("SPIRAL PEVAL DIAG " + r)
            diag_print true r
    

        let diag_abort_if_needed (where: string) =
            let now = peval_sw.ElapsedMilliseconds
            // Legacy watchdog variables (optional). These remain hard aborts.
            if peval_abort_ms > 0L && now >= peval_abort_ms then
                diag_last_wait <- where
                DiagLastWait.set diag_last_wait
                peval_abort (sprintf "Timed out (ms=%d)" peval_abort_ms)
            if peval_mem_limit_mb > 0L then
                let mb = get_private_mb ()
                if mb >= peval_mem_limit_mb then
                    diag_last_wait <- where
                    DiagLastWait.set diag_last_wait
                    peval_abort (sprintf "Memory limit reached (limit_mb=%d, private_mb=%d)" peval_mem_limit_mb mb)
    

            // Diagnostic aborts. Soft by default: disable parallel join-points and keep going.
            if diag_abort_armed then
                if diag_abort_ms > 0L && now >= diag_abort_ms then
                    diag_last_wait <- where
                    DiagLastWait.set diag_last_wait
                    if jp_diag_hard_abort then
                        peval_abort (sprintf "Timed out (ms=%d)" diag_abort_ms)
                    else
                        diag_abort_armed <- false
                        diag_soft_abort where (sprintf "Timed out (ms=%d)" diag_abort_ms)
    

                if diag_jp_spec_cap > 0L then
                    let total = diag_specs_total () |> int64
                    if total >= diag_jp_spec_cap then
                        diag_last_wait <- where
                        DiagLastWait.set diag_last_wait
                        if jp_diag_hard_abort then
                            peval_abort (sprintf "Join-point spec cap exceeded (cap=%d, total=%d)" diag_jp_spec_cap total)
                        else
                            diag_abort_armed <- false
                            diag_soft_abort where (sprintf "Join-point spec cap exceeded. cap=%d total=%d" diag_jp_spec_cap total)
    

                if diag_jp_name_spec_cap > 0L then
                    for KeyValue(nameId, count) in jp_name_counts do
                        if int64 count >= diag_jp_name_spec_cap then
                            let name = JpNameIdOps.text nameId
                            diag_last_wait <- where
                            DiagLastWait.set diag_last_wait
                            if jp_diag_hard_abort then
                                peval_abort (FastRuntimeFormat.format "Join-point name cap exceeded (cap=%d, name=%s, count=%d)" [| box diag_jp_name_spec_cap; box name; box count |])
                            else
                                diag_abort_armed <- false
                                diag_soft_abort where (FastRuntimeFormat.format "Join-point name cap exceeded. cap=%d name=%s count=%d" [| box diag_jp_name_spec_cap; box name; box count |])
    

        // ════════════════════════════════════════════════════════════════════════
        // MIGRATION: HOPAC IVAR-BASED WAITING
        // ════════════════════════════════════════════════════════════════════════
        // This replaces ManualResetEventSlim blocking with cooperative Hopac waiting.
        // The key insight: we run IVar.read synchronously on the calling thread but
        // with periodic yields to allow Hopac scheduler to make progress.
    

        let jpIvarWaitKind = function
            | JpIvarWaitTypeSite -> JpIvarWaitType
            | JpIvarWaitMethodSite -> JpIvarWaitMethod
            | JpIvarWaitClosureSharedSite
            | JpIvarWaitClosureLocalSite
            | JpIvarWaitClosurePostRaceSite
            | JpIvarWaitGenericSite -> JpIvarWaitOther

        let jpIvarWaitSiteText = function
            | JpIvarWaitTypeSite -> "JPType.wait"
            | JpIvarWaitMethodSite -> "JPMethod.wait"
            | JpIvarWaitClosureSharedSite -> "JPClosure.shared_wait"
            | JpIvarWaitClosureLocalSite -> "JPClosure.wait"
            | JpIvarWaitClosurePostRaceSite -> "JPClosure.shared_wait_after_race"
            | JpIvarWaitGenericSite -> "JP.wait"

        let jpIvarWaitKindText = function
            | JpIvarWaitType -> "JpIvarWaitType"
            | JpIvarWaitMethod -> "JpIvarWaitMethod"
            | JpIvarWaitOther -> "JpIvarWaitOther"

        let jpTypeSynchronousBoundaryDispositionText = function
            | JpTypeDeferredFromOwnedProducer -> "OwnedProducerDeferredPlaceholder"
            | JpTypeDeferredFromForeignProducer ownerThreadId -> "ForeignProducerDeferredPlaceholder(owner=" + string ownerThreadId + ")"
            | JpTypeDeferredAfterOwnershipRace -> "OwnershipRaceDeferredPlaceholder"

        let jpMethodSynchronousBoundaryDispositionText = function
            | JpMethodDeferredFromExistingCell -> "ExistingCellDeferredPlaceholder"
            | JpMethodDeferredFromSharedPendingCell -> "SharedPendingCellDeferredPlaceholder"
            | JpMethodDeferredFromOwnedProducer -> "OwnedProducerDeferredPlaceholder"
            | JpMethodDeferredAfterOwnershipRace -> "OwnershipRaceDeferredPlaceholder"
            | JpMethodDeferredFromSharedRaceCell -> "SharedRaceCellDeferredPlaceholder"

        let jpClosureSynchronousProjectionDispositionText = function
            | JpClosureSharedPendingCellProjected -> "SharedPendingCellProjected"
            | JpClosureOwnerLocalPendingCellRetained -> "OwnerLocalPendingCellRetained"
            | JpClosurePostRacePendingCellProjected -> "PostRacePendingCellProjected"

        let rec jpWaitGraphMemberText = function
            | JpWaitGraphMemberOne(edge, owner) ->
                FastRuntimeFormat.format "WaitMember(wait_ref=%s|edge_ref=%s|site=%s|owner=%s)" [| box (CompilerIdentityKernel.ContentDigest.text edge.waitRef); box (CompilerIdentityKernel.ContentDigest.text edge.edgeRef); box (CompilerIdentityKernel.WorkSiteIdOps.text edge.siteId); box (jpPromiseOwnerCapabilityText owner) |]
            | JpWaitGraphMemberMore(edge, owner, rest) ->
                FastRuntimeFormat.format "WaitMember(wait_ref=%s|edge_ref=%s|site=%s|owner=%s)->%s" [| box (CompilerIdentityKernel.ContentDigest.text edge.waitRef); box (CompilerIdentityKernel.ContentDigest.text edge.edgeRef); box (CompilerIdentityKernel.WorkSiteIdOps.text edge.siteId); box (jpPromiseOwnerCapabilityText owner); box (jpWaitGraphMemberText rest) |]

        let jpWaitGraphMembershipText = function
            | JpWaitGraphAcyclicMembership None -> "AcyclicMembership(empty)"
            | JpWaitGraphAcyclicMembership(Some members) ->
                "AcyclicMembership(" + jpWaitGraphMemberText members + ")"
            | JpWaitGraphClosedSccMembership(members, owner) ->
                "ClosedScc(members=" + jpWaitGraphMemberText members
                + "|owner=" + jpPromiseOwnerCapabilityText owner + ")"
            | JpWaitGraphUnownedMembership(edge, owner) ->
                FastRuntimeFormat.format "Unowned(wait_ref=%s|edge_ref=%s|owner=%s)" [| box (CompilerIdentityKernel.ContentDigest.text edge.waitRef); box (CompilerIdentityKernel.ContentDigest.text edge.edgeRef); box (jpPromiseOwnerCapabilityText owner) |]

        let jpWaitGraphDecisionText = function
            | JpWaitGraphAcyclic(membership, graphRef) ->
                sprintf "Acyclic(membership=%s|graph_ref=%s)"
                    (jpWaitGraphMembershipText membership)
                    (CompilerIdentityKernel.ContentDigest.text graphRef)
            | JpWaitGraphProducerUnavailable(membership, graphRef) ->
                sprintf "ProducerUnavailable(membership=%s|graph_ref=%s)"
                    (jpWaitGraphMembershipText membership)
                    (CompilerIdentityKernel.ContentDigest.text graphRef)
            | JpWaitGraphCycle(membership, graphRef) ->
                sprintf "Cycle(membership=%s|graph_ref=%s)"
                    (jpWaitGraphMembershipText membership)
                    (CompilerIdentityKernel.ContentDigest.text graphRef)

        let jpIvarWaitProbeMs waitKind =
            let baseProbeMs =
                if CacheGeneration.isSequentialRequested() then min jp_stall_abort_ms 5000L else jp_stall_abort_ms
            match waitKind with
            | JpIvarWaitType -> min baseProbeMs 15000L
            | JpIvarWaitMethod -> min baseProbeMs 20000L
            | JpIvarWaitOther -> baseProbeMs

        let jpIvarWaitOwnershipSnapshot now : Job<JpIvarWaitOwnershipSnapshot> =
            job {
                let ledger = jpWorkLedgerRead()
                let activeJobs = jp_active_jobs.ToArray() |> Array.sortBy (fun kv -> kv.Key)
                let jobs = activeJobs.Length
                let! graph = jp_operational_work_snapshot ()
                let queueDepth = CompilerKernelV2.OperationalWorkGraph.openCount graph
                let suspendedCount = CompilerKernelV2.OperationalWorkGraph.suspendedCount graph
                let countdownRemaining = int64 queueDepth
                let oldestActiveJobId, oldestActiveJobName, oldestActiveAgeMs =
                    if jobs = 0 then -1L, "", 0L
                    else
                        let oldest = activeJobs |> Array.minBy (fun kv -> kv.Value)
                        let mutable siteId = Unchecked.defaultof<CompilerIdentityKernel.WorkSiteId>
                        let site = if jp_active_job_sites.TryGetValue(oldest.Key, &siteId) then CompilerIdentityKernel.WorkSiteIdOps.text siteId else ""
                        oldest.Key, site, max 0L (now - oldest.Value)
                let ownedSetText =
                    let activeIdentity =
                        activeJobs
                        |> Array.map (fun kv ->
                            let mutable siteId = Unchecked.defaultof<CompilerIdentityKernel.WorkSiteId>
                            let site = if jp_active_job_sites.TryGetValue(kv.Key, &siteId) then CompilerIdentityKernel.WorkSiteIdOps.text siteId else ""
                            sprintf "%d:%s" kv.Key site)
                        |> String.concat ";"
                    FastRuntimeFormat.format "pending=%d|active=%d|jobs=%d|open=%d|suspended=%d|active_set=%s" [| box (CompilerKernelV2.Measured.value ledger.pending); box (CompilerKernelV2.Measured.value ledger.workerActive); box jobs; box queueDepth; box suspendedCount; box activeIdentity |]
                return {
                    pending = CompilerKernelV2.Measured.value ledger.pending
                    active = CompilerKernelV2.Measured.value ledger.workerActive
                    jobs = jobs
                    queueDepth = queueDepth
                    countdownRemaining = countdownRemaining
                    oldestActiveAgeMs = oldestActiveAgeMs
                    ownedSetDigest = CompilerIdentityKernel.ContentDigest.ofText "jp-owned-set" ownedSetText
                    oldestActiveJobId = oldestActiveJobId
                    oldestActiveJobName = oldestActiveJobName
                }
            }

        /// Wait for an IVar to be filled, with cooperative yielding and diagnostics.
        /// This is the Hopac equivalent of the old jp_ev_wait.

        // Native JP wait: one Alt owns completion, generation supersession and
        // the bounded watchdog window. Waiters never execute arbitrary queue work,
        // but exact acyclic dependencies donate priority to their named semantic
        // producer. A typed unchanged-owned-set stall is claimed exactly once, while every
        // waiter observing that same failed set unwinds under the durable claim.

        let jp_ivar_wait_job (site:JpIvarWaitSiteId) (details:string) (ivar:Hopac.IVar<'T>) : Job<'T> =
            job {
                let w = jpIvarWaitSiteText site
                let armedGeneration = CacheGeneration.current()
                let admittedAtMs = peval_sw.ElapsedMilliseconds
                let waitKind = jpIvarWaitKind site
                let siteId = CompilerIdentityKernel.WorkSiteIdOps.create details
                let instantiationId = CompilerKernelV2.InstantiationIdOps.create (w + "|" + details)
                let backendId = CompilerKernelV2.BackendIdOps.create "host"
                let generationCell = CacheGeneration.watch armedGeneration
                let portablePromiseCell : CompilerKernelV2.PortableOneShotCell<'T> =
                    CompilerKernelV2.CompilerRuntimeKernel.wrapOneShot<'T>
                        ("jp-wait-promise:" + w)
                        ivar
                let portableGenerationCell : CompilerKernelV2.PortableOneShotCell<CacheGeneration.GenerationChange> =
                    CompilerKernelV2.CompilerRuntimeKernel.wrapOneShot<CacheGeneration.GenerationChange>
                        ("jp-wait-generation:" + w)
                        generationCell
                let promiseRegistration =
                    JpPromiseProducerAuthority.registrationForExisting armedGeneration ivar
                let promiseResolution =
                    JpPromiseProducerAuthority.resolveRegistration armedGeneration promiseRegistration
                let promiseIdentity = promiseRegistration.promiseIdentity
                let (JpPromiseIdentity promiseRef) = promiseIdentity
                let producerIdentity, producerWorkId =
                    match promiseResolution with
                    | JpPromiseProducerResolved binding ->
                        JpProducerExact(binding.ownerCapability, binding.producerWorkId), binding.producerWorkId
                    | JpPromiseProducerUnbound owner ->
                        JpProducerUnbound owner, 0L
                    | JpPromiseProducerGenerationMismatch(expectedGeneration, actualGeneration, binding) ->
                        JpProducerGenerationMismatch(expectedGeneration, actualGeneration, binding.bindingRef), 0L

                let waitBinding =
                    CompilerKernelV2.StableBindingId.createSemantic
                        0
                        "jp-logical-wait"
                        w
                        details
                        (CompilerIdentityKernel.ContentDigest.text promiseRef)
                        "host"
                let ownerBinding =
                    CompilerKernelV2.StableBindingId.createSemantic
                        0
                        "jp-logical-wait-owner"
                        w
                        details
                        "logical-suspension-owner"
                        "portable-runtime"
                let workUnit =
                    CompilerKernelV2.WorkUnitIdOps.create<
                        CompilerKernelV2.ElaboratedPhase,
                        CompilerKernelV2.JoinPointWorkKind>
                        waitBinding
                        armedGeneration
                        instantiationId
                        backendId
                let owner = CompilerKernelV2.WorkOwnerCapabilityOps.bind ownerBinding
                let queuedWork =
                    CompilerKernelV2.WorkItemOps.createQueued
                        workUnit
                        owner
                        armedGeneration
                        [ promiseRef ]
                        siteId
                        (CompilerKernelV2.Measured.create<CompilerKernelV2.SemanticCostUnit> "logicalWaitCost" 1L)
                        admittedAtMs
                let runningWork = CompilerKernelV2.WorkItemOps.start queuedWork
                let continuation : CompilerKernelV2.WorkContinuation<'T> =
                    CompilerKernelV2.WorkContinuation.create<'T>
                        armedGeneration
                        (CompilerKernelV2.WorkItemOps.identityRef runningWork)
                        (CompilerKernelV2.WorkItemOps.getStateRef runningWork)
                        promiseRef
                let suspension =
                    CompilerKernelV2.WorkItemOps.suspend
                        (CompilerKernelV2.WorkSuspendedOnPromise promiseRef)
                        continuation
                        runningWork
                let suspendedWork = CompilerKernelV2.WorkItemOps.suspendedWork suspension
                let waitRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-logical-suspension"
                        (CompilerIdentityKernel.ContentDigest.text (CompilerKernelV2.WorkItemOps.identityRef runningWork)
                         + "|continuation="
                         + CompilerIdentityKernel.ContentDigest.text (CompilerKernelV2.WorkContinuation.idRef continuation))

                let waiterIdentity =
                    JpWaiterWorkIdentity (CompilerKernelV2.WorkItemOps.getCommitOrdinal runningWork)
                let waitEdge =
                    { waitRef = waitRef
                      generation = armedGeneration
                      waiter = waiterIdentity
                      promise = promiseIdentity
                      producer = producerIdentity
                      waitKind = waitKind
                      waitShapeId = CompilerIdentityKernel.WorkShapeIdOps.create w
                      siteId = CompilerIdentityKernel.WorkSiteIdOps.create details
                      admittedAtMs = admittedAtMs
                      edgeRef =
                        CompilerIdentityKernel.ContentDigest.ofText
                            "jp-logical-wait-edge"
                            (CompilerIdentityKernel.ContentDigest.text waitRef
                             + "|promise=" + CompilerIdentityKernel.ContentDigest.text promiseRef) }

                let! _ =
                    jp_operational_work_transact_required
                        "logical JP wait admission"
                        (JpOperationalWorkAdmitTransaction(
                            CompilerKernelV2.OperationalWorkGraph.nodeOfQueued queuedWork,
                            jpOperationalNoSemanticMutation))
                let startTransition =
                    CompilerKernelV2.WorkTransitionOps.start queuedWork runningWork
                let suspensionTransition =
                    CompilerKernelV2.WorkTransitionOps.suspend runningWork suspension
                let! _ =
                    jp_operational_work_transact_required
                        "logical JP wait start"
                        (JpOperationalWorkTransitionTransaction(
                            startTransition,
                            jpOperationalNoSemanticMutation))
                let! _ =
                    jp_operational_work_transact_required
                        "logical JP wait suspension"
                        (JpOperationalWorkTransitionTransaction(
                            suspensionTransition,
                            jpOperationalNoSemanticMutation))
                let! waitGraphDecision = JpWaitGraphAuthority.admit waitEdge

                if producerWorkId > 0L then
                    jpSpecializationQueueRequestDonation producerWorkId |> ignore

                DiagJson.emitRecord
                    ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpLogicalSuspensionParked
                       wait_ref = CompilerIdentityKernel.ContentDigest.text waitRef
                       work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText workUnit
                       continuation_ref = CompilerIdentityKernel.ContentDigest.text (CompilerKernelV2.WorkContinuation.idRef continuation)
                       promise_ref = CompilerIdentityKernel.ContentDigest.text promiseRef
                       producer_work_unit_id = producerWorkId
                       wait_kind_du = jpIvarWaitKindText waitKind
                       wait_graph_decision_du = jpWaitGraphDecisionText waitGraphDecision
                       generation = armedGeneration
                       authority = "indexed_work_graph_plus_exact_once_continuation"
                       next = "resume_fiber_without_blocking_worker" }
                     : JpLogicalSuspensionParkedEvent)

                let waitRace : CompilerKernelV2.PortableEffect<JpLogicalWaitResolution<'T>> =
                    CompilerKernelV2.CompilerRuntimeKernel.raceOneShots<'T,CacheGeneration.GenerationChange,JpLogicalWaitResolution<'T>>
                        ("jp-logical-wait-race:" + w)
                        portablePromiseCell
                        (Ok >> JpLogicalWaitResolved)
                        portableGenerationCell
                        JpLogicalWaitGenerationSuperseded
                do! CompilerKernelV2.CompilerRuntimeKernel.start (
                    CompilerKernelV2.CompilerRuntimeKernel.effect
                        ("jp-logical-wait-resume:" + w)
                        (job {
                            let! resolution : JpLogicalWaitResolution<'T> =
                                CompilerKernelV2.CompilerRuntimeKernel.toJob<JpLogicalWaitResolution<'T>> waitRace
                            match resolution with
                            | JpLogicalWaitResolved result ->
                                do! CompilerKernelV2.WorkContinuation.resume<'T> continuation result
                            | JpLogicalWaitGenerationSuperseded change ->
                                do! CompilerKernelV2.WorkContinuation.resume<'T>
                                        continuation
                                        (Error (CompilerKernelV2.WorkResumeGenerationSuperseded change.transitionRef))
                        }))

                let! result : Result<'T,CompilerKernelV2.WorkResumeFailure> =
                    CompilerKernelV2.WorkContinuation.awaitResult<'T> continuation
                let resumedWork = CompilerKernelV2.WorkItemOps.resume suspension
                let resumeTransition =
                    CompilerKernelV2.WorkTransitionOps.resume suspension resumedWork
                let! _ =
                    jp_operational_work_transact_required
                        "logical JP wait resume"
                        (JpOperationalWorkTransitionTransaction(
                            resumeTransition,
                            jpOperationalNoSemanticMutation))
                let terminalDisposition =
                    match result with
                    | Ok _ ->
                        CompilerKernelV2.WorkTerminalSucceeded (
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-logical-wait-resolved"
                                (CompilerIdentityKernel.ContentDigest.text waitRef))
                    | Error (CompilerKernelV2.WorkResumeGenerationSuperseded transitionRef) ->
                        CompilerKernelV2.WorkTerminalSuperseded transitionRef
                    | Error (CompilerKernelV2.WorkResumeProducerFailed failureRef) ->
                        CompilerKernelV2.WorkTerminalFailed failureRef
                    | Error (CompilerKernelV2.WorkResumeCancelled cancellationRef) ->
                        CompilerKernelV2.WorkTerminalCancelled cancellationRef
                    | Error (CompilerKernelV2.WorkResumeProtocolViolation violationRef) ->
                        CompilerKernelV2.WorkTerminalFailed violationRef
                let retiredWork, terminalDisposition =
                    CompilerKernelV2.WorkItemOps.retire terminalDisposition resumedWork
                let retirementTransition =
                    CompilerKernelV2.WorkTransitionOps.retire
                        resumedWork
                        retiredWork
                        terminalDisposition
                let! _ =
                    jp_operational_work_transact_required
                        "logical JP wait retirement"
                        (JpOperationalWorkTransitionTransaction(
                            retirementTransition,
                            jpOperationalNoSemanticMutation))
                let! _ = JpWaitGraphAuthority.resolve waitRef
                match result with
                | Ok value -> return value
                | Error failure ->
                    return raise (PartEvalTypeError([], "logical JP suspension failed: " + string failure))
            }

        let jp_ivar_try_read (ivar:Hopac.IVar<'T>) : 'T option =
            let portableCell : CompilerKernelV2.PortableOneShotCell<'T> =
                CompilerKernelV2.CompilerRuntimeKernel.wrapOneShot<'T>
                    "jp-try-read"
                    ivar
            CompilerKernelV2.CompilerRuntimeKernel.tryReadOneShotNow<'T> portableCell

        let (|JpIvarReady|JpIvarPending|) (ivar:Hopac.IVar<'a>) =
            match jp_ivar_try_read ivar with
            | Some value -> JpIvarReady value
            | None -> JpIvarPending ivar

        let jp_type_rec_placeholder_cells : System.Collections.Concurrent.ConcurrentDictionary<Ty, JPTypeCell<Ty>> =
            System.Collections.Concurrent.ConcurrentDictionary<Ty, JPTypeCell<Ty>>(HashIdentity.Structural)

        let jp_recursive_array_obligations : System.Collections.Concurrent.ConcurrentDictionary<Ty, System.Collections.Concurrent.ConcurrentQueue<JpRecursiveArrayObligation>> =
            System.Collections.Concurrent.ConcurrentDictionary<Ty, System.Collections.Concurrent.ConcurrentQueue<JpRecursiveArrayObligation>>(HashIdentity.Structural)

        let jp_recursive_array_inferred_elements : System.Collections.Concurrent.ConcurrentDictionary<Ty, Ty> =
            System.Collections.Concurrent.ConcurrentDictionary<Ty, Ty>(HashIdentity.Structural)

        let jp_recursive_array_element_by_parent : System.Collections.Concurrent.ConcurrentDictionary<Ty, Ty> =
            System.Collections.Concurrent.ConcurrentDictionary<Ty, Ty>(HashIdentity.Structural)

        let jp_recursive_array_parent_by_element : System.Collections.Concurrent.ConcurrentDictionary<Ty, Ty> =
            System.Collections.Concurrent.ConcurrentDictionary<Ty, Ty>(HashIdentity.Structural)

        let jp_type_register_rec_placeholder (placeholderTy:Ty) (cell:JPTypeCell<Ty>) =
            jp_type_rec_placeholder_cells.[placeholderTy] <- cell
            placeholderTy

        let jp_recursive_array_element_placeholder_for (placeholderTy:Ty) =
            match jp_recursive_array_inferred_elements.TryGetValue placeholderTy with
            | true, inferredElementTy -> inferredElementTy, true
            | _ ->
                let elementPlaceholder =
                    jp_recursive_array_element_by_parent.GetOrAdd(
                        placeholderTy,
                        System.Func<Ty,Ty>(fun parentTy ->
                            let identity =
                                CompilerIdentityKernel.ContentDigest.ofText
                                    "jp-recursive-array-element-placeholder"
                                    (show_ty parentTy)
                            let elementTy =
                                YSymbol ("JPArrayElementRecPlaceholder(#" + CompilerIdentityKernel.ContentDigest.text identity + ")")
                            jp_recursive_array_parent_by_element.[elementTy] <- parentTy
                            elementTy))
                elementPlaceholder, false

        let rec jp_type_deref_rec_placeholder (ty:Ty) =
            match tryDecodeJpRecPlaceholder ty with
            | Some JpTypeRecPlaceholder ->
                match jp_type_rec_placeholder_cells.TryGetValue ty with
                | true, cell ->
                    match jp_ivar_try_read cell.ivar with
                    | Some (Some resolvedTy) -> resolvedTy
                    | _ -> ty
                | _ -> ty
            | Some JpArrayElementRecPlaceholder ->
                match jp_recursive_array_parent_by_element.TryGetValue ty with
                | true, parentTy ->
                    let resolvedParentTy =
                        parentTy
                        |> jp_method_deref_rec_placeholder
                        |> jp_type_deref_rec_placeholder
                    match resolvedParentTy with
                    | YArray elementTy -> elementTy
                    | _ ->
                        match jp_recursive_array_inferred_elements.TryGetValue parentTy with
                        | true, inferredElementTy -> inferredElementTy
                        | _ -> ty
                | _ -> ty
            | _ -> ty

        let jpUnionCaseSymbolResolution (symbol:string) =
            let originalTy = YSymbol symbol
            match tryDecodeJpRecPlaceholder originalTy with
            | None -> JpUnionCaseConcreteSymbol symbol
            | Some placeholderKind ->
                let resolvedTy =
                    originalTy
                    |> jp_method_deref_rec_placeholder
                    |> jp_type_deref_rec_placeholder
                match resolvedTy with
                | YSymbol resolvedSymbol when resolvedSymbol <> symbol && Option.isNone (tryDecodeJpRecPlaceholder (YSymbol resolvedSymbol)) ->
                    JpUnionCaseResolvedPlaceholder(placeholderKind, symbol, resolvedSymbol)
                | YSymbol _ ->
                    JpUnionCasePendingPlaceholder(placeholderKind, symbol)
                | resolvedTy ->
                    JpUnionCaseResolvedNonSymbol(placeholderKind, symbol, resolvedTy)

        let jp_recursive_array_try_element_type (placeholderTy:Ty) =
            let resolvedTy =
                placeholderTy
                |> jp_method_deref_rec_placeholder
                |> jp_type_deref_rec_placeholder
            match resolvedTy with
            | YArray elementTy -> Some elementTy
            | _ ->
                match jp_recursive_array_inferred_elements.TryGetValue placeholderTy with
                | true, inferredElementTy -> Some inferredElementTy
                | _ -> None

        let jp_recursive_array_register_obligation placeholderKind placeholderTy inferredElementTy elementCount =
            let generation = CacheGeneration.current()
            let obligationRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-recursive-array-obligation"
                    ("kind=" + jpRecPlaceholderKindText placeholderKind
                     + "|placeholder=" + show_ty placeholderTy
                     + "|element=" + show_ty inferredElementTy
                     + "|count=" + string elementCount
                     + "|generation=" + string generation)
            let obligation = {
                obligationRef = obligationRef
                generation = generation
                placeholderKind = placeholderKind
                inferredElementTy = inferredElementTy
                elementCount = elementCount
            }
            let queue =
                jp_recursive_array_obligations.GetOrAdd(
                    placeholderTy,
                    System.Func<Ty, System.Collections.Concurrent.ConcurrentQueue<JpRecursiveArrayObligation>>(fun _ ->
                        System.Collections.Concurrent.ConcurrentQueue<JpRecursiveArrayObligation>()))
            jp_recursive_array_inferred_elements.TryAdd(placeholderTy, inferredElementTy) |> ignore
            queue.Enqueue obligation
            DiagJson.emitRecord
                ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpRecursiveArrayObligationRegistered
                   obligation_ref = CompilerIdentityKernel.ContentDigest.text obligationRef
                   generation = generation
                   placeholder_kind_du = jpRecPlaceholderKindText placeholderKind
                   placeholder_ty = show_ty placeholderTy
                   inferred_element_ty = show_ty inferredElementTy
                   element_count = elementCount
                   terminal_authority = false
                   next = "resolve_against_jp_placeholder_producer" }
                 : JpRecursiveArrayObligationRegisteredEvent)
            obligationRef

        let jp_recursive_array_resolve_obligations placeholderTy resolvedTy =
            let mutable obligations = Unchecked.defaultof<System.Collections.Concurrent.ConcurrentQueue<JpRecursiveArrayObligation>>
            if jp_recursive_array_obligations.TryRemove(placeholderTy, &obligations) then
                let currentGeneration = CacheGeneration.current()
                let resolvedTy =
                    resolvedTy
                    |> jp_method_deref_rec_placeholder
                    |> jp_type_deref_rec_placeholder
                for obligation in obligations do
                    let decision, failureMessage =
                        if obligation.generation <> currentGeneration then
                            JpRecursiveArrayResolutionStaleGeneration, None
                        else
                            match resolvedTy with
                            | YArray resolvedElementTy when ty_eq_allow_jp_placeholders obligation.inferredElementTy resolvedElementTy ->
                                JpRecursiveArrayResolvedCompatible, None
                            | YArray resolvedElementTy ->
                                JpRecursiveArrayResolvedElementMismatch,
                                Some ($"Recursive array placeholder resolved with an incompatible element type.\nExpected: {show_ty obligation.inferredElementTy}\nGot: {show_ty resolvedElementTy}")
                            | _ ->
                                JpRecursiveArrayResolvedNonArray,
                                Some ($"Recursive array placeholder resolved to a non-array type.\nExpected element: {show_ty obligation.inferredElementTy}\nGot: {show_ty resolvedTy}")
                    DiagJson.emitRecord
                        ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpRecursiveArrayObligationResolved
                           obligation_ref = CompilerIdentityKernel.ContentDigest.text obligation.obligationRef
                           decision_du = jpRecursiveArrayResolutionDecisionText decision
                           placeholder_kind_du = jpRecPlaceholderKindText obligation.placeholderKind
                           obligation_generation = obligation.generation
                           current_generation = currentGeneration
                           element_count = obligation.elementCount
                           inferred_element_ty = show_ty obligation.inferredElementTy
                           resolved_ty = show_ty resolvedTy
                           terminal_authority = false
                           next = "continue_or_surface_typed_resolution_failure" }
                         : JpRecursiveArrayObligationResolvedEvent)
                    match failureMessage with
                    | Some message -> jp_exns.Enqueue(capture_edi (PartEvalTypeError([], message)))
                    | None -> ()

        jp_recursive_array_method_resolution_hook <- jp_recursive_array_resolve_obligations

        CacheGeneration.registerOnInvalidate (fun _ ->
            jp_type_rec_placeholder_cells.Clear()
            jp_recursive_array_obligations.Clear()
            jp_recursive_array_inferred_elements.Clear()
            jp_recursive_array_element_by_parent.Clear()
            jp_recursive_array_parent_by_element.Clear())

        let jp_recursive_array_obligation_count () =
            jp_recursive_array_obligations.Values
            |> Seq.sumBy (fun queue -> int64 queue.Count)

        let jp_recursive_array_placeholder_count () =
            int64 jp_type_rec_placeholder_cells.Count
            + int64 jp_method_rec_placeholder_keys.Count
            + int64 jp_recursive_array_parent_by_element.Count

        // MIGRATION: surface JP scheduler counters in heartbeat without touching hot paths.


        let jp_extra_provider_impl () : string =
            try
                let now = peval_sw.ElapsedMilliseconds
                let q = (jpSpecializationQueueDepth ())
                let pend = ((jpWorkLedgerRead()).pending |> CompilerKernelV2.Measured.value)
                let cdRem = 0L
                let active = ((jpWorkLedgerRead()).workerActive |> CompilerKernelV2.Measured.value)
                let doneCount = ((jpWorkLedgerRead()).totalDone |> CompilerKernelV2.Measured.value)
                let enq = ((jpWorkLedgerRead()).totalEnqueued |> CompilerKernelV2.Measured.value)
                let frozen = ((jpWorkLedgerRead()).frozenTotal |> CompilerKernelV2.Measured.value)
                let lastProg = jp_progress_clock_read()
                let progAge = if lastProg = 0L then -1L else let d = now - lastProg in if d < 0L then 0L else d
                let rem = max 0L (max active (max pend cdRem))
                let denom = max (if frozen > 0L then frozen else enq) (doneCount + rem)
                let pct = if denom > 0L then (100.0 * float doneCount / float denom) else 0.0
                let jobs = jp_active_jobs.Count
                let activeAge =
                    if jobs = 0 then -1L else
                        let mutable minStart = System.Int64.MaxValue
                        for KeyValue(_, start) in jp_active_jobs do
                            if start < minStart then minStart <- start
                        if minStart = System.Int64.MaxValue then -1L else
                            let d = now - minStart
                            if d < 0L then 0L else d
                let seq = if CacheGeneration.isSequentialRequested() then 1 else 0
                let inv = CacheGeneration.invalidationCount()
                let arrayObligations = jp_recursive_array_obligation_count ()
                let arrayPlaceholders = jp_recursive_array_placeholder_count ()
                let stallWarn = 30000L
                let stalled =
                    rem > 0L
                    && progAge >= stallWarn
                    && ((active = 0L) || (activeAge >= stallWarn && jobs > 0))
                let semanticDenominator =
                    if rem = 0L then CompilerKernelV2.ProgressDenominatorClosed
                    else CompilerKernelV2.ProgressDenominatorOpen(CompilerKernelV2.Measured.create<CompilerKernelV2.SemanticCostUnit> "semanticRemaining" rem, CompilerKernelV2.Measured.create<CompilerKernelV2.SemanticCostUnit> "semanticReserveP90" (max rem (rem * 2L)))
                let semanticProjection = CompilerKernelV2.SemanticWorkLedgerAuthority.project semanticDenominator
                FastRuntimeFormat.format "jp[q=%d rem=%d act=%d legacy=%d/%d (%.2f%%) semantic_bp=%d..%d..%d exact=%b age=%dms run=%dms jobs=%d stall=%d seq=%d inv=%d array_obligations=%d array_placeholders=%d]" [| box q; box rem; box active; box doneCount; box denom; box pct; box (CompilerKernelV2.BasisPoints.value semanticProjection.lowBp); box (CompilerKernelV2.BasisPoints.value semanticProjection.midBp); box (CompilerKernelV2.BasisPoints.value semanticProjection.highBp); box semanticProjection.exact; box progAge; box activeAge; box jobs; box (if stalled then 1 else 0); box seq; box inv; box arrayObligations; box arrayPlaceholders |]
            with _ -> ""
        jp_extra_provider <- jp_extra_provider_impl
        Progress88.set_extra_provider (fun () ->
            try
                let now = peval_sw.ElapsedMilliseconds
                jpEmitInFlightSlowUnits now
                let q = (jpSpecializationQueueDepth ())
                let pend = ((jpWorkLedgerRead()).pending |> CompilerKernelV2.Measured.value)
                let cdRem = 0L
                let active = ((jpWorkLedgerRead()).workerActive |> CompilerKernelV2.Measured.value)
                let doneCount = ((jpWorkLedgerRead()).totalDone |> CompilerKernelV2.Measured.value)
                let enq = ((jpWorkLedgerRead()).totalEnqueued |> CompilerKernelV2.Measured.value)
                let frozen = ((jpWorkLedgerRead()).frozenTotal |> CompilerKernelV2.Measured.value)
                let lastProg = jp_progress_clock_read()
                let progAge = if lastProg = 0L then -1L else let d = now - lastProg in if d < 0L then 0L else d
                let rem = max 0L (max active (max pend cdRem))
                let denom = max (if frozen > 0L then frozen else enq) (doneCount + rem)
                let pct = if denom > 0L then (100.0 * float doneCount / float denom) else 0.0
                let jobs = jp_active_jobs.Count
                let activeAge =
                    if jobs = 0 then -1L else
                        let mutable minStart = System.Int64.MaxValue
                        for KeyValue(_, start) in jp_active_jobs do
                            if start < minStart then minStart <- start
                        if minStart = System.Int64.MaxValue then -1L else
                            let d = now - minStart
                            if d < 0L then 0L else d
                let seq = if CacheGeneration.isSequentialRequested() then 1 else 0
                let inv = CacheGeneration.invalidationCount()
                let arrayObligations = jp_recursive_array_obligation_count ()
                let arrayPlaceholders = jp_recursive_array_placeholder_count ()
                let stallWarn = 30000L
                let stalled =
                    rem > 0L
                    && progAge >= stallWarn
                    && ((active = 0L) || (activeAge >= stallWarn && jobs > 0))
                let semanticDenominator =
                    if rem = 0L then CompilerKernelV2.ProgressDenominatorClosed
                    else CompilerKernelV2.ProgressDenominatorOpen(CompilerKernelV2.Measured.create<CompilerKernelV2.SemanticCostUnit> "semanticRemaining" rem, CompilerKernelV2.Measured.create<CompilerKernelV2.SemanticCostUnit> "semanticReserveP90" (max rem (rem * 2L)))
                let semanticProjection = CompilerKernelV2.SemanticWorkLedgerAuthority.project semanticDenominator
                FastRuntimeFormat.format "jp[q=%d rem=%d act=%d legacy=%d/%d (%.2f%%) semantic_bp=%d..%d..%d exact=%b age=%dms run=%dms jobs=%d stall=%d seq=%d inv=%d array_obligations=%d array_placeholders=%d]" [| box q; box rem; box active; box doneCount; box denom; box pct; box (CompilerKernelV2.BasisPoints.value semanticProjection.lowBp); box (CompilerKernelV2.BasisPoints.value semanticProjection.midBp); box (CompilerKernelV2.BasisPoints.value semanticProjection.highBp); box semanticProjection.exact; box progAge; box activeAge; box jobs; box (if stalled then 1 else 0); box seq; box inv; box arrayObligations; box arrayPlaceholders |]
            with _ -> ""
        )

        
        // MIGRATION: optional ANSI panel UI for debugging JP stalls/races.

        // Keep it cheap: this runs only on the 4s heartbeat thread.
        let jp_panel_provider () : string =
            try
                let now = peval_sw.ElapsedMilliseconds
                let seq = if CacheGeneration.isSequentialRequested() then 1 else 0
                let gen = CacheGeneration.current()
                let inv = CacheGeneration.invalidationCount()
                let reasons = CacheGeneration.reasonsSnapshot 1
                let reason1 = match reasons with | h :: _ -> h | _ -> ""
                let jobs = jp_active_jobs.ToArray()
                let top =
                    jobs
                    |> Array.map (fun kv ->
                        let id = kv.Key
                        let start = kv.Value
                        let age = let d = now - start in if d < 0L then 0L else d
                        (age, id))
                    |> Array.sortWith (fun (a,_) (b,_) -> compare b a)
                    |> (fun a -> if a.Length > 3 then a.[0..2] else a)
                let sb = System.Text.StringBuilder()
                sb.AppendFormat("jp.panel seq={0} gen={1} inv={2}", seq, gen, inv) |> ignore
                if reason1 <> "" then
                    sb.AppendLine() |> ignore
                    sb.Append("invalidate: ") |> ignore
                    sb.Append(reason1) |> ignore
                if top.Length > 0 then
                    sb.AppendLine() |> ignore
                    sb.Append("slow jobs (age ms):") |> ignore
                    for (age, id) in top do
                        sb.AppendLine() |> ignore
                        let mutable siteId = Unchecked.defaultof<CompilerIdentityKernel.WorkSiteId>
                        let site = if jp_active_job_sites.TryGetValue(id, &siteId) then CompilerIdentityKernel.WorkSiteIdOps.text siteId else ""
                        let nm =
                            if System.String.IsNullOrEmpty site then ""
                            elif site.Length > 60 then site.Substring(0,57) + "..."
                            else site
                        sb.AppendFormat("  #{0} age={1} {2}", id, age, nm) |> ignore
                let worklistPanel = EvalWorklist.panel()
                if not (System.String.IsNullOrWhiteSpace worklistPanel) then
                    sb.AppendLine() |> ignore
                    sb.Append(worklistPanel) |> ignore
                sb.ToString().TrimEnd()
            with _ -> ""

        // MIGRATION: richer stall diagnostics (append-only). Capture more than the 3-line jp.panel summary.
        let jp_slow_jobs_snapshot (maxn: int) : string list =
            try
                if maxn <= 0 then [] else
                let now = peval_sw.ElapsedMilliseconds
                let jobs = jp_active_jobs.ToArray()
                let top =
                    jobs
                    |> Array.map (fun kv ->
                        let id = kv.Key
                        let start = kv.Value
                        let age = let d = now - start in if d < 0L then 0L else d
                        (age, id))
                    |> Array.sortWith (fun (a,_) (b,_) -> compare b a)
                    |> (fun a -> if a.Length > maxn then a.[0..maxn-1] else a)
                top
                |> Array.map (fun (age, id) ->
                    let mutable siteId = Unchecked.defaultof<CompilerIdentityKernel.WorkSiteId>
                    let site = if jp_active_job_sites.TryGetValue(id, &siteId) then CompilerIdentityKernel.WorkSiteIdOps.text siteId else ""
                    let site =
                        if System.String.IsNullOrEmpty site then ""
                        elif site.Length > 140 then site.Substring(0,137) + "..."
                        else site
                    FastRuntimeFormat.format "  #%d age=%dms %s" [| box id; box age; box site |])
                |> Array.toList
            with _ -> []
        Progress88.set_panel_provider jp_panel_provider

        // MIGRATION: cache invalidation should also shed stale queued JP work, otherwise
        // we can accumulate thousands of specs and then hit EJP0008 while waiting.
        CacheGeneration.registerOnInvalidate (fun reasonId ->
            let reasonText = CacheGeneration.GenerationChangeReasonIdOps.text reasonId
            try
                // Drain *and execute* stale queued JP work so their finally blocks run
                // (decrement pending_count and publish graph retirement).
                // Dropping work without executing leads to mismatched counters and hangs.
                let mutable drained = 0
                let mutable draining = true
                while draining do
                    match jpSpecializationQueueTryRemoveAny () with
                    | JpSpecializationQueueRemoved(work, _) ->
                        drained <- drained + 1
                        startHopacJob (jp_cancel_work_item (JpGenerationScopeCancellation (CompilerKernelV2.OperationalReasonIdOps.create reasonText)) work)
                    | JpSpecializationQueueEmpty -> draining <- false
                if drained > 0 then DiagSidecar.emit (sprintf "JPWorkQ.invalidate: drained_and_canceled=%d reason=%s" drained reasonText)

                // Best-effort: clear per-name traces so next generation does not inherit loop hot-spots.
                try jp_name_counts.Clear() with _ -> ()
                try jp_mismatch_counts.Clear() with _ -> ()
                try jp_name_traces.Clear() with _ -> ()

                // MIGRATION: jp_active_jobs is diagnostic-only; clear to avoid leak across generations when workers are canceled.
                // (We prefer losing a few in-flight entries over unbounded growth across retries.)
                try jp_active_jobs.Clear() with _ -> ()
                try jp_active_job_sites.Clear() with _ -> ()
                try jp_active_job_timings.Clear() with _ -> ()
                try jp_work_exns.Clear() with _ -> ()
                jp_required_work_slice_progress_forget_continuations ()

                // Reset progress timestamps to avoid negative ages after fast retries.
                let now = peval_sw.ElapsedMilliseconds
                jp_progress_clock_mark peval_sw.ElapsedMilliseconds
                jpWorkLedgerExchangeLastEnqueueMs now |> ignore
                jpWorkLedgerExchangeFrozenTotal 0L |> ignore

                // [JP-INT-210-001] Poke main thread so any Wait/Sleep/Join can observe invalidation promptly.
                // [JP-INT-211-001] Disabled: Thread.Interrupt causes fatal BigStack Join interruptions (see 210.txt).
                ()
            with _ -> ()
        )
    
    
    



        // ════════════════════════════════════════════════════════════════════════
        // 
        //
        // MIGRATION: In sequential fallback we still run the JP scheduler, but we serialize dequeue+exec via a gate.
        let jp_seq_gate = obj()

        let jp_seq_lock (f: unit -> 'a) : 'a =
            if CacheGeneration.isSequentialRequested() then lock jp_seq_gate (fun () -> f())
            else f()

        // MIGRATION SOTA: HOPAC WORK QUEUE WITH WORK-STEALING
        // ════════════════════════════════════════════════════════════════════════
        // Quiescence is a graph fact, never a process-global scheduling gate.
        // Parallelism is always enabled; work is throttled via backpressure only.
        

        let jp_cancel = new System.Threading.CancellationTokenSource()
        

        // Progress tracking for stall detection
        let mutable jp_last_progress_ms_local = 0L
        let mutable jp_last_done_local = -1L
        let mutable jp_last_den_local = -1L
        let mutable jp_last_rem_local = -1L
        let mutable jp_last_worker_population_local = -1
        let jp_note_progress () =
            // [JP-WD-204-001] Always rethrow cooperative-abort exceptions on the main thread.
            jp_throw_if_any()
            let now = peval_sw.ElapsedMilliseconds
            // MIGRATION: Only bump last_progress_ms on *real* progress changes, so `age=` reflects stalls.
            if not (jpWorkLedgerTryStartProgress ()) then
                Progress88.stage 2 4
                jp_last_progress_ms_local <- now
                jp_progress_clock_mark now

            let enq_now = ((jpWorkLedgerRead()).totalEnqueued |> CompilerKernelV2.Measured.value)
            let enq_last = (jpWorkLedgerRead()).lastEnqueueAt |> CompilerKernelV2.Measured.value
            let enq_age = if enq_last = 0L then -1L else now - enq_last
            let frozen = ((jpWorkLedgerRead()).frozenTotal |> CompilerKernelV2.Measured.value)
            let enq_for_pct =
                if frozen > 0L then frozen
                elif enq_now > 0L && enq_age >= 2000L then
                    jpWorkLedgerCompareExchangeFrozenTotal enq_now 0L |> ignore
                    enq_now
                else enq_now
            let doneCount = ((jpWorkLedgerRead()).totalDone |> CompilerKernelV2.Measured.value)
            let pendNow = ((jpWorkLedgerRead()).pending |> CompilerKernelV2.Measured.value)
            let cdRem = 0L
            let activeNow = ((jpWorkLedgerRead()).workerActive |> CompilerKernelV2.Measured.value)
            let rem = max 0L (max activeNow (max pendNow cdRem))
            let den1 = max enq_for_pct (doneCount + rem)
            let workerPopulation = jp_worker_thread_registry.Count

            let changed =
                doneCount <> jp_last_done_local
                || den1 <> jp_last_den_local
                || rem <> jp_last_rem_local
                || workerPopulation <> jp_last_worker_population_local

            if changed then
                jp_last_done_local <- doneCount
                jp_last_den_local <- den1
                jp_last_rem_local <- rem
                jp_last_worker_population_local <- workerPopulation
                jp_last_progress_ms_local <- now
                jp_progress_clock_mark now
                let activeJobs = jp_active_jobs.ToArray()
                let parkedExactWaiters = jpActiveJobsExactAcyclicWaitCount now activeJobs
                let runnableWorkers = max 0 (workerPopulation - parkedExactWaiters)
                let activeDeclaredBody = jpActiveDeclaredBodyWorkerCount ()
                let activeObservers = jpActiveObserverWorkerCount ()
                let activeSemantic = max 0L (activeNow - int64 activeDeclaredBody - int64 activeObservers)
                let declaredBodyPolicy, declaredBodyVerifierLimit =
                    jpDeclaredBodyWorkerPolicy (jpSpecializationSemanticQueueDepth ())
                let declaredBodyRecoveryOwner = jp_declared_body_finish_through_owner_snapshot ()
                DiagJson.emitRecord
                    ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpSchedulerCapacity
                       generation = CacheGeneration.current()
                       runnable_workers = runnableWorkers
                       runnable_limit = jp_worker_population_core_limit
                       worker_population = workerPopulation
                       population_limit = jp_exact_wait_worker_population_limit
                       parked_exact_waiters = parkedExactWaiters
                       semantic_queue_depth = jpSpecializationSemanticQueueDepth ()
                       declared_body_queue_depth = jpSpecializationDeclaredBodyQueueDepth ()
                       observer_queue_depth = jpSpecializationObserverQueueDepth ()
                       queue_depth = jpSpecializationQueueDepth ()
                       semantic_active = activeSemantic
                       declared_body_active = activeDeclaredBody
                       declared_body_policy_du = jpDeclaredBodyLanePolicyText declaredBodyPolicy
                       declared_body_verifier_limit = declaredBodyVerifierLimit
                       declared_body_retired_count = jp_declared_body_retired_count
                       declared_body_long_retired_count = jp_declared_body_long_retired_count
                       declared_body_lifetime_count = jp_declared_body_lifetime_states.Count
                       declared_body_recovery_owner_present = Option.isSome declaredBodyRecoveryOwner
                       declared_body_recovery_owner = defaultArg declaredBodyRecoveryOwner 0L
                       observer_active = activeObservers
                       pending = pendNow
                       active = activeNow
                       donatable_count = jpSpecializationSemanticQueueDepth ()
                       authority = "single_scheduler_three_typed_lanes_material_or_worker_population_change"
                       next = "donate_producer_run_foreground_or_replace_lost_worker" }
                     : JpSchedulerCapacityEvent)

            Progress88.sub doneCount (max 1L den1)
            Progress88.pulse
                Progress88.ProgressHeartbeatJpWorkLedgerProgress
                (CacheGeneration.current())
        

        // Hopac worker fibers

        let mutable jp_workers_started = false
        let jp_workers_started_sync = obj()
        
        // MIGRATION: watchdog for "hung" JP jobs. If there is no scheduler progress for jp_stall_abort_ms
        let mutable jp_workers_shutdown = false

        // and the work queue is empty while active jobs keep aging, abort fast with diagnostics.
        let jp_watchdog_enabled = true  // fixed default; no env var override

        let mutable jp_watchdog_started = false
        let jp_watchdog_started_sync = obj()
        let mutable jp_watchdog_last_trip_gen = -1L
        // [JP-WD-233-001] Slow-job watchdog: abort earlier if a *specific* job exceeds a smaller per-op timeout.
        // This catches the "stuck near 99.xx%" case where progress still ticks occasionally, so progAge never reaches jp_stall_abort_ms.
        let jp_slow_sensitive_ms = 60000L   // 60s (fixed default)
        let jp_slow_default_ms   = 0L       // 0=disabled by default (fixed)
        let jp_slow_anon_ms      = 0L       // 0=disabled by default (fixed)
        


        let mutable jp_watchdog_last_slow_trip_gen = -1L
        
        



        let start_jp_watchdog () =
            if jp_watchdog_enabled && not jp_watchdog_started then
                lock jp_watchdog_started_sync (fun () ->
                    if jp_watchdog_enabled && not jp_watchdog_started then
                        jp_watchdog_started <- true
                        let thread_body () =
                            try
                                try
                                    while not jp_workers_shutdown do
                                        System.Threading.Thread.Sleep(250)
                                        try
                                            let jobs = jp_active_jobs.ToArray()
                                            let now = peval_sw.ElapsedMilliseconds
                                            // The watchdog thread is the only periodic path guaranteed to run
                                            // in redirected builds; UI/extra-provider callbacks are optional.
                                            jpEmitInFlightSlowUnits now
                                            if jobs.Length > 0 && (jpSpecializationQueueDepth ()) = 0 then
                                                let lastProg0 = jp_progress_clock_read()
                                                let lastProg = if lastProg0 = 0L then now else lastProg0
                                                let progAge = let d = now - lastProg in if d < 0L then 0L else d
                                                let delegatedToExactAcyclicWaits =
                                                    jpActiveJobsDelegatedToExactAcyclicWait now jobs
                                                if delegatedToExactAcyclicWaits && progAge >= jp_stall_abort_ms then
                                                    let occurrenceCount, shouldEmit =
                                                        DiagJson.sparseLogDecision
                                                            (sprintf "jp_watchdog_wait_graph_delegated|generation=%d|jobs=%d" (CacheGeneration.current()) jobs.Length)
                                                            64L
                                                    if shouldEmit then
                                                        DiagJson.emit (
                                                            FastRuntimeFormat.format "{\"kind\":\"jp_watchdog_wait_graph_delegated\",\"generation\":%d,\"jobs\":%d,\"progress_age_ms\":%d,\"wait_graph_decision_du\":\"AllActiveJobsExactAcyclicChildWait\",\"global_invalidation_apply\":false,\"local_wait_recovery_authority\":true,\"occurrence_count\":%d,\"sparse_policy\":\"state_first3_power2_every64\",\"authority\":\"active_job_typed_child_wait_identity\",\"next\":\"allow_probe_cadence_owned_set_recovery\"}" [| box (CacheGeneration.current()); box jobs.Length; box progAge; box occurrenceCount |])
                                                // [JP-WD-233-002] Early abort on slow active job (named or anon).
                                                // We only trip once per cache generation to avoid log storms.
                                                let mutable slowId = -1L
                                                let mutable slowName = ""
                                                let mutable slowAge = 0L
                                                let mutable slowThr = 0L
                                                for kv in jobs do
                                                    let id = kv.Key
                                                    let st = kv.Value
                                                    let age = let d = now - st in if d < 0L then 0L else d
                                                    let mutable siteId = Unchecked.defaultof<CompilerIdentityKernel.WorkSiteId>
                                                    let nm = if jp_active_job_sites.TryGetValue(id, &siteId) then CompilerIdentityKernel.WorkSiteIdOps.text siteId else ""
                                                    let thr =
                                                        if System.String.IsNullOrEmpty nm then jp_slow_anon_ms
                                                        else
                                                            match jpSlowJobSensitivityId nm with
                                                            | JpSlowJobSensitiveCommandBoundary -> jp_slow_sensitive_ms
                                                            | JpSlowJobOrdinary -> jp_slow_default_ms
                                                    if thr > 0L && age >= thr && age > slowAge then
                                                        slowId <- id
                                                        slowName <- nm
                                                        slowAge <- age
                                                        slowThr <- thr
                                

                                                if slowId <> -1L && not delegatedToExactAcyclicWaits then
                                                    let gen0 = CacheGeneration.current()
                                                    let prev = lock jp_watchdog_started_sync (fun () -> let previous = jp_watchdog_last_slow_trip_gen in jp_watchdog_last_slow_trip_gen <- gen0; previous)
                                                    if prev <> gen0 then
                                                        let inv = CacheGeneration.invalidationCount()
                                                        let msg = FastRuntimeFormat.format "%s: jp_slow_job abort id=%d name=%s age=%dms thr=%dms jobs=%d progAge=%dms gen=%d inv=%d last_wait=%s" [| box DiagnosticClassifier.EJP0031; box slowId; box slowName; box slowAge; box slowThr; box jobs.Length; box progAge; box gen0; box inv; box diag_last_wait |]
                                                        let snap = diag_snapshot "jp_watchdog slow_job"
                                                        let panel0 = try jp_panel_provider () with _ -> ""
                                                        let panel = if System.String.IsNullOrEmpty panel0 then "" else "---- jp.panel ----\n" + panel0
                                                        let slow0 = jp_slow_jobs_snapshot 12
                                                        let slow = if slow0.IsEmpty then "" else "---- jp slow jobs ----\n" + (slow0 |> String.concat "\n")
                                                        let diag =
                                                            [ msg; panel; slow; snap ]
                                                            |> List.filter (fun s -> not (System.String.IsNullOrEmpty s))
                                                            |> String.concat "\n"
                                                        DiagSidecar.emit diag
                                                        try
                                                            CacheGeneration.requestSequential ()
                                                            ignore (CacheGeneration.invalidate (CacheGeneration.GenerationChangeReasonIdOps.create ("jp_slow_job " + msg)))
                                                            jp_exns.Enqueue(capture_edi (PartEvalTypeError([], msg)))
                                                            ()
                                                        with _ -> ()
                                                if progAge >= jp_stall_abort_ms && not delegatedToExactAcyclicWaits then
                                                    let mutable minStart = System.Int64.MaxValue
                                                    for kv in jobs do
                                                        if kv.Value < minStart then minStart <- kv.Value
                                                    if minStart <> System.Int64.MaxValue then
                                                        let oldestAge = let d = now - minStart in if d < 0L then 0L else d
                                                        if oldestAge >= jp_stall_abort_ms then
                                                            let gen0 = CacheGeneration.current()
                                                            let prev = lock jp_watchdog_started_sync (fun () -> let previous = jp_watchdog_last_trip_gen in jp_watchdog_last_trip_gen <- gen0; previous)
                                                            if prev <> gen0 then
                                                                let inv = CacheGeneration.invalidationCount()
                                                                let msg = FastRuntimeFormat.format "[spiral_compiler] EJP0030: jp_watchdog abort progAge=%dms oldestAge=%dms jobs=%d gen=%d inv=%d last_wait=%s" [| box progAge; box oldestAge; box jobs.Length; box gen0; box inv; box diag_last_wait |]
                                                                let snap = diag_snapshot "jp_watchdog stall"
                                                                let panel0 = try jp_panel_provider () with _ -> ""
                                                                let panel =
                                                                    if System.String.IsNullOrEmpty panel0 then ""
                                                                    else "---- jp.panel ----\n" + panel0
                                                                let slow0 = jp_slow_jobs_snapshot 12
                                                                let slow =
                                                                    if slow0.IsEmpty then ""
                                                                    else "---- jp slow jobs ----\n" + (slow0 |> String.concat "\n")
                                                                let diag =
                                                                    [ msg
                                                                      panel
                                                                      slow
                                                                      snap ]
                                                                    |> List.filter (fun s -> not (System.String.IsNullOrEmpty s))
                                                                    |> String.concat "\n"
                                                                DiagSidecar.emit diag
                                                                // [JP-WD-203-001] Cooperative abort: inject exn + invalidate so outer retry can recover.
                                                                try
                                                                    CacheGeneration.requestSequential ()
                                                                    ignore (CacheGeneration.invalidate (CacheGeneration.GenerationChangeReasonIdOps.create ("jp_watchdog " + msg)))
                                                                    jp_exns.Enqueue(capture_edi (PartEvalTypeError([], msg)))
                                                                    // [JP-INT-211-001] Disabled: Thread.Interrupt causes fatal BigStack Join interruptions (see 210.txt).
                                                                    ()
                                                                with _ -> ()
                                        with _ -> ()
                                with _ -> ()
                            with _ -> ()
                        let watchdogThread = System.Threading.Thread(System.Threading.ThreadStart(thread_body))
                        watchdogThread.IsBackground <- true
                        watchdogThread.Name <- "spiral-jp-watchdog"
                        watchdogThread.Start()
                )

        // MIGRATION: Signal workers to shut down gracefully
        let jp_shutdown_workers () =
            jp_workers_shutdown <- true

        // A typed terminal failure can outrun worker availability. Queued JP work has
        // already been admitted to the semantic/operational ledgers, so simply exiting
        // would strand conserved credit. A dedicated cutover watcher therefore drains
        // only work that is still physically queued and retires it through the normal
        // cancellation transaction. Work already owned by a worker is never stolen.
        // Source identity, source span, symbol names and diagnostic text are deliberately
        // absent from this authority path.
        let jp_terminal_failure_cutover_start_sync = obj()
        let mutable jp_terminal_failure_cutover_started = false
        let jp_terminal_failure_cutover_reason =
            CompilerKernelV2.OperationalReasonIdOps.create "typed_terminal_failure_cutover_before_start"

        let jpTerminalFailureCutoverDrainQueuedWork () =
            let semanticAdmittedBefore, semanticReceiptsBefore = CompilerKernelV2.SemanticWorkLedgerAuthority.counts ()
            let semanticOpenBefore = max 0 (semanticAdmittedBefore - semanticReceiptsBefore)
            let mutable drained = 0
            let mutable semanticOwned = 0
            let mutable keepDraining = true
            while keepDraining do
                match jpSpecializationQueueTryRemoveAny () with
                | JpSpecializationQueueRemoved(work, _) ->
                    drained <- drained + 1
                    if jpWorkAuthorityRoleOwnsSemanticLedger work.authorityRole then
                        semanticOwned <- semanticOwned + 1
                    runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                        (CompilerKernelV2.WorkUnitIdOps.digestText work.workUnit)
                        (jp_cancel_work_item (JpHostRequestedCancellation jp_terminal_failure_cutover_reason) work)
                    |> jpIgnoreAuthorityBoundaryResult
                | JpSpecializationQueueEmpty ->
                    keepDraining <- false
            if drained > 0 then
                let semanticAdmittedAfter, semanticReceiptsAfter = CompilerKernelV2.SemanticWorkLedgerAuthority.counts ()
                let semanticOpenAfter = max 0 (semanticAdmittedAfter - semanticReceiptsAfter)
                DiagJson.emit (
                    FastRuntimeFormat.format
                        "{\"kind\":\"jp_terminal_failure_cutover_queue_drained\",\"drained_count\":%d,\"semantic_owned_count\":%d,\"queue_depth_after\":%d,\"semantic_admitted_before\":%d,\"semantic_receipts_before\":%d,\"semantic_open_before\":%d,\"semantic_admitted_after\":%d,\"semantic_receipts_after\":%d,\"semantic_open_after\":%d,\"semantic_balance_diagnostic_only\":true,\"cancellation_du\":\"HostCancellation(TypedTerminalFailureCutoverBeforeStart)\",\"body_execution_authority\":false,\"semantic_receipt_authority\":\"normal_operational_semantic_cancellation_transaction\",\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"authority\":\"irrevocable_terminal_failure_plus_physical_queue_ownership\",\"next\":\"continue_draining_until_no_unstarted_work_remains\"}"
                        [| box drained; box semanticOwned; box (jpSpecializationQueueDepth ()); box semanticAdmittedBefore; box semanticReceiptsBefore; box semanticOpenBefore; box semanticAdmittedAfter; box semanticReceiptsAfter; box semanticOpenAfter |])
            drained

        let startJpTerminalFailureCutoverWatcher () =
            lock jp_terminal_failure_cutover_start_sync (fun () ->
                if not jp_terminal_failure_cutover_started then
                    jp_terminal_failure_cutover_started <- true
                    let body () =
                        let mutable keepWatching = true
                        while keepWatching do
                            let terminalFailure = DiagJson.terminalFailureExitRequestedNow()
                            if terminalFailure then
                                try
                                    jpTerminalFailureCutoverDrainQueuedWork () |> ignore
                                with error ->
                                    DiagJson.emit (
                                        FastRuntimeFormat.format
                                            "{\"kind\":\"jp_terminal_failure_cutover_queue_drain_failed\",\"exception_type\":%s,\"terminal_authority_preserved\":true,\"source_path_authority\":false,\"diagnostic_text_authority\":false,\"authority\":\"terminal_cutover_drain_diagnostic_only\",\"next\":\"physical_failure_exit_remains_authoritative\"}"
                                            [| box (DiagJson.esc (error.GetType().FullName)) |])
                            let queueDepth = jpSpecializationQueueDepth ()
                            let activeOwnerCount = jp_active_jobs.Count
                            keepWatching <-
                                not jp_workers_shutdown
                                || (terminalFailure && (queueDepth > 0 || activeOwnerCount > 0))
                            if keepWatching then System.Threading.Thread.Sleep 10
                    let thread = System.Threading.Thread(System.Threading.ThreadStart(body))
                    thread.IsBackground <- true
                    thread.Name <- "jp-terminal-failure-cutover"
                    thread.Start())

        let start_jp_workers () =
            if not jp_workers_started then
                lock jp_workers_started_sync (fun () ->
                    if not jp_workers_started then
                        jp_workers_started <- true
                        startJpTerminalFailureCutoverWatcher ()
    
                        // JP work items may still cross synchronous confluence boundaries.
                        // Running those boundaries as Hopac fibers can recursively enter
                        // the scheduler, so execution remains on bounded dedicated workers.
                        // The progress ledger itself is now a local synchronized snapshot;
                        // the queue items retain stable identities and exact-once cells.
                        let executeWorkerItem (work:JpWorkItem) (laneAdmission:JpWorkerLaneAdmission) =
                            let mutable workerExecutionCounted = false
                            try
                                if DiagJson.terminalFailureExitRequestedNow() then
                                    let cancellationRef =
                                        CompilerIdentityKernel.ContentDigest.ofText
                                            "jp-terminal-failure-cutover-before-start"
                                            (CompilerKernelV2.WorkUnitIdOps.digestText work.workUnit
                                             + "|job=" + string work.commitOrdinal)
                                    runJpWorkPlanAtDedicatedWorkerBoundary
                                        work
                                        (work.cancel (JpHostRequestedCancellation jp_terminal_failure_cutover_reason))
                                    |> ignore
                                    JpSpecializationWorklistAuthority.cancel work.workNode cancellationRef
                                    DiagJson.emit (
                                        FastRuntimeFormat.format
                                            "{\"kind\":\"jp_terminal_failure_cutover_before_start_suppressed\",\"work_unit_id\":%s,\"job_id\":%d,\"cancellation_ref\":%s,\"body_execution_authority\":false,\"semantic_receipt_authority\":\"terminal_before_start_operational_transaction\",\"source_path_authority\":false,\"source_span_authority\":false,\"symbol_name_authority\":false,\"diagnostic_text_authority\":false,\"authority\":\"irrevocable_terminal_failure_precedes_worker_body\",\"next\":\"observe_terminal_before_start_receipt\"}"
                                            [| box (DiagJson.esc (CompilerKernelV2.WorkUnitIdOps.digestText work.workUnit)); box work.commitOrdinal; box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text cancellationRef)) |])
                                match JpSpecializationWorklistAuthority.start work.workNode with
                                | JpSpecializationWorkStartTerminal terminalDisposition ->
                                    let terminalRef, continuationResult =
                                        match terminalDisposition with
                                        | CompilerKernelV2.WorkTerminalSucceeded receiptRef ->
                                            receiptRef, Ok()
                                        | CompilerKernelV2.WorkTerminalFailed failureRef ->
                                            failureRef, Error(CompilerKernelV2.WorkResumeProducerFailed failureRef)
                                        | CompilerKernelV2.WorkTerminalCancelled cancellationRef ->
                                            cancellationRef, Error(CompilerKernelV2.WorkResumeCancelled cancellationRef)
                                        | CompilerKernelV2.WorkTerminalSuperseded supersededRef ->
                                            supersededRef, Error(CompilerKernelV2.WorkResumeGenerationSuperseded supersededRef)
                                    let terminalSemanticDisposition =
                                        jpTerminalDispositionSemanticRetirement terminalDisposition
                                    let semanticMutationExpected =
                                        jpWorkAuthorityRoleOwnsSemanticLedger work.authorityRole
                                    let mutable semanticMutationApplied = false
                                    let terminalSemanticMutation =
                                        if semanticMutationExpected then
                                            CompilerKernelV2.WorkUnitReceipt.create work.workUnit terminalSemanticDisposition work.cost
                                            |> jpOperationalSemanticApply
                                        else
                                            jpOperationalNoSemanticMutation
                                    let _, retirementTransitions, suspendedContinuation =
                                        JpWorkOperationalCursor.retireBeforeStart terminalDisposition work.operational
                                    let terminalTransitionIndex = retirementTransitions.Length - 1
                                    retirementTransitions
                                    |> List.iteri (fun transitionIndex transition ->
                                        let transactionAuthorityResult =
                                            runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                                (CompilerKernelV2.WorkUnitIdOps.digestText work.workUnit)
                                                (jp_operational_work_transact
                                                    (JpOperationalWorkTransitionTransaction(
                                                        transition,
                                                        (if transitionIndex = terminalTransitionIndex then terminalSemanticMutation else jpOperationalNoSemanticMutation))))
                                        match transactionAuthorityResult with
                                        | JpAuthorityBoundaryRejected failure ->
                                            jpEmitAuthorityBoundaryResultAbsorbed "terminal_before_start_retirement" failure
                                            raise (PartEvalTypeError([], "terminal-before-start boundary rejected: " + jpAuthorityBoundaryFailureText failure))
                                        | JpAuthorityBoundaryAccepted (Ok receipt) ->
                                            if transitionIndex = terminalTransitionIndex then
                                                semanticMutationApplied <- receipt.semanticMutationApplied
                                        | JpAuthorityBoundaryAccepted (Error rejection) ->
                                            raise (PartEvalTypeError([], "terminal-before-start retirement rejected: " + jpOperationalWorkTransactionRejectionText rejection)))
                                    match suspendedContinuation with
                                    | Some continuation ->
                                        runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                            (CompilerKernelV2.WorkUnitIdOps.digestText work.workUnit)
                                            (CompilerKernelV2.WorkContinuation.resume continuation continuationResult)
                                        |> jpIgnoreAuthorityBoundaryResult
                                    | None -> ()
                                    if semanticMutationExpected then
                                        runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                            (CompilerKernelV2.WorkUnitIdOps.digestText work.workUnit)
                                            (jp_generation_scope_retire work)
                                        |> jpIgnoreAuthorityBoundaryResult
                                    if jpWorkAuthorityRoleParticipatesInRequiredWorkRecovery work.authorityRole then
                                        jp_required_work_slice_progress_forget work.generation work.commitOrdinal
                                    jpRemoveDeclaredEvaluatorContinuationsForJob work.commitOrdinal
                                    jpRemoveActiveWorkTiming work.commitOrdinal
                                    jpWorkAdmissionTimingRemove work.commitOrdinal
                                    DiagJson.emitRecord
                                        ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitTerminalBeforeStartSuppressed
                                           work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText work.workUnit
                                           job_id = work.commitOrdinal
                                           terminal_ref = CompilerIdentityKernel.ContentDigest.text terminalRef
                                           terminal_disposition_du = CompilerKernelV2.WorkTerminalDispositionOps.text terminalDisposition
                                           body_executed = false
                                           retirement_transition_count = retirementTransitions.Length
                                           semantic_mutation_expected = semanticMutationExpected
                                           semantic_mutation_applied = semanticMutationApplied
                                           authority = "worklist_terminal_precedes_worker_execution"
                                           next = "retirement_transaction_committed_without_body_execution;semantic_receipt_only_when_authority_owns_semantic_ledger" }
                                         : JpWorkUnitTerminalBeforeStartSuppressedEvent)
                                    true
                                | JpSpecializationWorkStartAlreadyRunning runningNode ->
                                    let occurrenceCount, shouldEmit =
                                        DiagJson.sparseLogDecision
                                            ("jp_worker_duplicate_active_attempt_suppressed|" + CompilerIdentityKernel.ContentDigest.text runningNode.nodeRef)
                                            64L
                                    if shouldEmit then
                                        DiagJson.emit (
                                            FastRuntimeFormat.format
                                                "{\"kind\":\"jp_worker_duplicate_active_attempt_suppressed\",\"work_unit_id\":%s,\"job_id\":%d,\"work_node_ref\":%s,\"occurrence_count\":%d,\"body_executed\":false,\"active_owner_cleanup_authority\":false,\"semantic_completion_credit\":false,\"authority\":\"specialization_worklist_compare_exchange_single_owner\",\"next\":\"existing_running_owner_retires_work\"}"
                                                [| box (DiagJson.esc (CompilerKernelV2.WorkUnitIdOps.digestText work.workUnit)); box work.commitOrdinal; box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text runningNode.nodeRef)); box occurrenceCount |])
                                    true
                                | JpSpecializationWorkStartAcquired _ ->
                                    let workerStartedAtMs = max 0L (jp_progress_clock())
                                    jp_active_jobs.[work.commitOrdinal] <- workerStartedAtMs
                                    jp_active_job_sites.[work.commitOrdinal] <- work.siteId
                                    ignore (jpWorkLedgerIncrementWorkerActive ())
                                    workerExecutionCounted <- true
                                    jpWithCurrentWorkIdentity work (fun () -> jp_execute_work_item work)
                                    true
                            finally
                                // The queue selector owns lane admission for every attempt. Active-owner
                                // telemetry and timing, however, belong only to the attempt that won the
                                // specialization worklist compare-exchange. A duplicate attempt must never
                                // erase the live owner's identity while it is still executing.
                                if workerExecutionCounted then
                                    let mutable removedStartedAtMs = 0L
                                    let mutable removedSite = Unchecked.defaultof<CompilerIdentityKernel.WorkSiteId>
                                    jp_active_jobs.TryRemove(work.commitOrdinal, &removedStartedAtMs) |> ignore
                                    jp_active_job_sites.TryRemove(work.commitOrdinal, &removedSite) |> ignore
                                    jpWorkAdmissionTimingRemove work.commitOrdinal
                                    ignore (jpWorkLedgerDecrementWorkerActive ())
                                // Dequeue transfers the existing resume-root lease from the queue to
                                // this execution attempt.  A requeue retains its successor before this
                                // finally block releases the old attempt, so pruning never observes a
                                // zero-owner gap for a live semantic resume continuation.
                                jpReleaseWorkItemQueuedResumeRoot work
                                jpWorkerLaneRelease laneAdmission
                                jp_note_progress ()

                        let executeWorkerItemSafely (work:JpWorkItem) (laneAdmission:JpWorkerLaneAdmission) =
                            try
                                executeWorkerItem work laneAdmission
                            with
                            | :? PartEvalTypeError as error ->
                                // The item boundary, not the worker-loop boundary, owns
                                // recoverable failures.  A failed item must not retire the
                                // dedicated worker that can continue draining unrelated work.
                                let failureRef =
                                    CompilerIdentityKernel.ContentDigest.ofText
                                        "jp-worker-item-typed-failure"
                                        (CompilerIdentityKernel.ContentDigest.text work.workNode.nodeRef
                                         + "|message=" + error.Message)
                                let failureReasonId = CompilerKernelV2.OperationalReasonIdOps.create error.Message
                                let workFailure =
                                    JpPartEvalTypeFailure(
                                        jpPartEvalFailureCauseFor error.Message,
                                        failureReasonId,
                                        failureRef)
                                runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                    (CompilerKernelV2.WorkUnitIdOps.digestText work.workUnit)
                                    (jp_fail_work_item
                                        JpFailureDeliveryWorkerOwner
                                        (JpHostRequestedCancellation failureReasonId)
                                        workFailure
                                        work)
                                |> jpIgnoreAuthorityBoundaryResult
                                if jp_exns.IsEmpty then jp_exns.Enqueue(capture_edi error)
                                let occurrenceCount, shouldEmit =
                                    DiagJson.sparseLogDecision
                                        ("jp_worker_item_typed_failure_recovered|" + error.Message)
                                        64L
                                if shouldEmit then
                                    DiagJson.emitRecord
                                        ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkerItemTypedFailureRecovered
                                           work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText work.workUnit
                                           failure_ref = CompilerIdentityKernel.ContentDigest.text failureRef
                                           exception_type = error.GetType().FullName
                                           occurrence_count = occurrenceCount
                                           worker_continues = true
                                           authority = "per_item_failure_isolation"
                                           next = "drain_next_unrelated_work_item" }
                                         : JpWorkerItemTypedFailureRecoveredEvent)
                                true
                            | error ->
                                let exceptionType =
                                    let observedType = error.GetType()
                                    if System.String.IsNullOrWhiteSpace observedType.FullName then observedType.Name
                                    else observedType.FullName
                                let failureRef =
                                    CompilerIdentityKernel.ContentDigest.ofText
                                        "jp-worker-item-boundary-failure"
                                        (CompilerIdentityKernel.ContentDigest.text work.workNode.nodeRef
                                         + "|exception=" + exceptionType
                                         + "|message=" + error.Message)
                                let failureReasonId = CompilerKernelV2.OperationalReasonIdOps.create error.Message
                                let exceptionTypeId = JpExceptionTypeIdOps.create exceptionType
                                let workFailure =
                                    match work.authorityRole with
                                    | JpObserverVerification _ ->
                                        JpObserverVerificationFailure(exceptionTypeId, failureRef)
                                    | JpCodegenBodyProducer _ ->
                                        JpCodegenBodyFailure(exceptionTypeId, failureRef)
                                    | JpSemanticProducer ->
                                        JpSemanticSpecializationFailure(
                                            JpSemanticFailureException exceptionTypeId,
                                            failureRef)
                                runJpAuthorityJobAtDedicatedWorkerBoundaryResult
                                    (CompilerKernelV2.WorkUnitIdOps.digestText work.workUnit)
                                    (jp_fail_work_item
                                        JpFailureDeliveryWorkerOwner
                                        (JpHostRequestedCancellation failureReasonId)
                                        workFailure
                                        work)
                                |> jpIgnoreAuthorityBoundaryResult
                                CompilerConsoleHud88.captureWorkerBoundaryException "jp_worker_item" error
                                jp_exns.Enqueue(capture_edi error)
                                DiagJson.emitRecord
                                    ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkerItemBoundaryFailed
                                       work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText work.workUnit
                                       failure_ref = CompilerIdentityKernel.ContentDigest.text failureRef
                                       exception_type = exceptionType
                                       worker_continues = true
                                       authority = "per_item_failure_isolation"
                                       next = "drain_next_unrelated_work_item" }
                                     : JpWorkerItemBoundaryFailedEvent)
                                true

                        let workerReplacementCounts =
                            System.Collections.Concurrent.ConcurrentDictionary<int,int>()

                        let rec worker (i:int) (initialWork:(JpWorkItem * JpWorkerLaneAdmission) option) =
                            let body =
                                System.Threading.ThreadStart(fun () ->
                                    BigStack.StackBudget.enter (jpWorkerStackBytes jpWorkerStackPolicy)
                                    let current = System.Threading.Thread.CurrentThread
                                    if isNull current.Name then current.Name <- sprintf "jp-worker-%d" i
                                    jp_worker_thread_registry.TryAdd(current.ManagedThreadId, 0uy) |> ignore
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"jp_worker_stack_thread_entered_receipt\",\"worker_index\":%d,\"managed_thread_id\":%d,\"stack_bytes_requested\":%d,\"authority\":\"worker_body_entered_after_thread_start\",\"survival_authority_du\":\"DirectEnvelopeBypassTypedSerializer\",\"next\":\"separate_stack_policy_activation_from_recursive_overflow\"}" [| box i; box current.ManagedThreadId; box (jpWorkerStackBytes jpWorkerStackPolicy) |])
                                    let requestReplacement failureType =
                                        if not jp_workers_shutdown then
                                            let replacementCount =
                                                workerReplacementCounts.AddOrUpdate(i, 1, fun _ previous -> previous + 1)
                                            if replacementCount <= 8 then
                                                DiagJson.emitRecord
                                                    ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkerReplacementStarted
                                                       worker_index = i
                                                       replacement_count = replacementCount
                                                       failure_type = failureType
                                                       replacement_cap = 8
                                                       authority = "bounded_worker_pool_self_heal"
                                                       next = "continue_draining_after_infrastructure_failure" }
                                                     : JpWorkerReplacementStartedEvent)
                                                worker i None |> ignore
                                            else
                                                DiagJson.emitRecord
                                                    ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkerReplacementExhausted
                                                       worker_index = i
                                                       replacement_count = replacementCount
                                                       failure_type = failureType
                                                       replacement_cap = 8
                                                       terminal_authority = false
                                                       authority = "bounded_worker_pool_self_heal"
                                                       next = "surface_worker_capacity_debt" }
                                                     : JpWorkerReplacementExhaustedEvent)
                                    try
                                        try
                                            match initialWork with
                                            | Some (reservedWork, reservedAdmission) ->
                                                executeWorkerItemSafely reservedWork reservedAdmission |> ignore
                                            | None ->
                                                ()
                                            while not jp_workers_shutdown do
                                                let mutable drained = 0
                                                let mutable keepDraining = true
                                                let mutable idleWaitPolicy = jp_worker_idle_empty_queue_policy
                                                while keepDraining && drained < 256 do
                                                    match jpSpecializationQueueTryRemoveRunnable () with
                                                    | JpSpecializationRunnableQueueRemoved(work, depthAfter, laneAdmission) ->
                                                        // The signal wakes one waiter: hand it on while work remains.
                                                        if depthAfter > 0 then jpSignalSpecializationRunnablePotential ()
                                                        if executeWorkerItemSafely work laneAdmission then
                                                            drained <- drained + 1
                                                        else
                                                            keepDraining <- false
                                                    | JpSpecializationRunnableQueueDeferred _ ->
                                                        idleWaitPolicy <- jp_worker_idle_deferred_typed_carrier_policy
                                                        keepDraining <- false
                                                    | JpSpecializationRunnableQueueEmpty ->
                                                        keepDraining <- false
                                                if drained = 0 then
                                                    jp_specialization_runnable_signal.WaitOne(jpSpecializationWorkerIdleWaitTimeoutMs idleWaitPolicy) |> ignore
                                                else System.Threading.Thread.Yield() |> ignore
                                        with
                                        | :? PartEvalTypeError as e ->
                                            // jp_execute_work_item already captured and published typed failures.
                                            // Do not allocate a second multi-hundred-kilobyte stack trace at the
                                            // enclosing worker boundary; only backstop the queue if publication failed.
                                            if jp_exns.IsEmpty then jp_exns.Enqueue(capture_edi e)
                                            let occurrenceCount, shouldEmit =
                                                DiagJson.sparseLogDecision
                                                    ("jp_worker_typed_exception_duplicate_suppressed|" + e.Message)
                                                    64L
                                            if shouldEmit then
                                                DiagJson.emitRecord
                                                    ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkerTypedExceptionDuplicateSuppressed
                                                       exception_type = e.GetType().FullName
                                                       semantic_message = e.Message
                                                       occurrence_count = occurrenceCount
                                                       sparse_policy = "state_first3_power2_every64"
                                                       authority = "inner_work_item_boundary_owns_full_exception_capture"
                                                       next = "unwind_worker_without_duplicate_stack_projection" }
                                                     : JpWorkerTypedExceptionDuplicateSuppressedEvent)
                                            requestReplacement (e.GetType().FullName)
                                        | e ->
                                            CompilerConsoleHud88.captureWorkerBoundaryException "jp_worker_thread" e
                                            jp_exns.Enqueue(capture_edi e)
                                            let observedType = e.GetType()
                                            let failureType =
                                                if System.String.IsNullOrWhiteSpace observedType.FullName then observedType.Name
                                                else observedType.FullName
                                            requestReplacement failureType
                                    finally
                                        let mutable removedRole = 0uy
                                        jp_worker_thread_registry.TryRemove(current.ManagedThreadId, &removedRole) |> ignore
                                        try jp_note_progress () with _ -> ())
                            let th = System.Threading.Thread(body, jpWorkerStackBytes jpWorkerStackPolicy)
                            th.IsBackground <- true
                            try
                                th.Start()
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"jp_worker_stack_thread_started_receipt\",\"worker_index\":%d,\"managed_thread_id\":%d,\"stack_bytes_requested\":%d,\"stack_policy_du\":%s,\"authority\":\"thread_constructor_plus_start_returned\",\"survival_authority_du\":\"DirectEnvelopeBypassTypedSerializer\",\"next\":\"distinguish_stack_policy_installation_from_runaway_recursion\"}" [| box i; box th.ManagedThreadId; box (jpWorkerStackBytes jpWorkerStackPolicy); box (DiagJson.esc (jpWorkerStackPolicyText jpWorkerStackPolicy)) |])
                                true
                            with e ->
                                let stackStartFailureType =
                                    let observed = e.GetType()
                                    if System.String.IsNullOrWhiteSpace observed.FullName then observed.Name else observed.FullName
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"jp_worker_stack_thread_start_failed_receipt\",\"worker_index\":%d,\"stack_bytes_requested\":%d,\"exception_type\":%s,\"authority\":\"thread_start_failure_direct_receipt\",\"survival_authority_du\":\"DirectEnvelopeBypassTypedSerializer\",\"next\":\"do_not_conflate_stack_installation_failure_with_evaluator_recursion\"}" [| box i; box (jpWorkerStackBytes jpWorkerStackPolicy); box (DiagJson.esc stackStartFailureType) |])
                                match initialWork with
                                | Some (reservedWork, reservedAdmission) ->
                                    // Thread creation failed before the reserved lane could run.
                                    // Release the reservation first, then restore the exact item.
                                    jpWorkerLaneRelease reservedAdmission
                                    match jpSpecializationQueueEnqueue reservedWork with
                                    | JpSpecializationQueueAdmitted _ -> ()
                                    | disposition ->
                                        let failureRef =
                                            CompilerIdentityKernel.ContentDigest.ofText
                                                "jp-worker-start-requeue-failed"
                                                (CompilerIdentityKernel.ContentDigest.text reservedWork.workNode.nodeRef
                                                 + "|disposition=" + jpSpecializationQueueAdmissionText disposition)
                                        JpSpecializationWorklistAuthority.fail reservedWork.workNode failureRef
                                | None -> ()
                                CompilerConsoleHud88.captureWorkerBoundaryException "jp_worker_start" e
                                jp_exns.Enqueue(capture_edi e)
                                false

                        let worker_count =
                            if CacheGeneration.isSequentialRequested() then 1
                            else max 1 jp_dop
                        DiagJson.emitRecord
                            ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkerStackPolicyInstalled
                               worker_count = worker_count
                               stack_policy_du = jpWorkerStackPolicyText jpWorkerStackPolicy
                               stack_bytes_per_worker = jpWorkerStackBytes jpWorkerStackPolicy
                               authority = "dedicated_recursive_specialization_workers"
                               next = "execute_join_point_work_on_expanded_native_stacks" }
                             : JpWorkerStackPolicyInstalledEvent)
                        jp_request_blocking_compensation <-
                            fun generation request ->
                                lock jp_blocking_compensation_gate (fun () ->
                                    let currentGeneration = CacheGeneration.current()
                                    let requestText = jpBlockingCompensationRequestText request
                                    let stallEscalation =
                                        jpBlockingCompensationRequestAllowsStallEscalation request
                                    let reasonRef =
                                        CompilerIdentityKernel.ContentDigest.ofText "jp-blocking-compensation-reason" requestText
                                        |> CompilerIdentityKernel.ContentDigest.text
                                    let emitExpansion kindId added reserved total queueDepthBefore queueDepthAfter effectiveLimit exactWaitProducerRescue exactWaitBlockedCount =
                                        DiagJson.emitRecord
                                            ({ kind = DiagJson.typedDiagEventKindText kindId
                                               generation = generation
                                               base_worker_count = worker_count
                                               added_worker_count = added
                                               reserved_work_count = reserved
                                               compensation_worker_count = total
                                               total_worker_count = worker_count + total
                                               effective_compensation_limit = effectiveLimit
                                               exact_wait_producer_rescue = exactWaitProducerRescue
                                               exact_wait_blocked_count = exactWaitBlockedCount
                                               queue_depth_before = queueDepthBefore
                                               queue_depth_after = queueDepthAfter
                                               active_workers = ((jpWorkLedgerRead()).workerActive |> CompilerKernelV2.Measured.value)
                                               reason_ref = reasonRef
                                               scheduler_du = "DedicatedBlockingWorkersWithElasticReserve"
                                               capacity_basis_du = "NormalOnePerCoreOrExactAcyclicProducerRescue"
                                               demand_reservation_du = "QueueItemsDequeuedBeforeWorkerSpawn"
                                               authority = "typed_owned_wait_starvation_recovery" }
                                             : JpBlockingCompensationEvent)
                                    let reserveQueuedWork requestedCount =
                                        let reserved = ResizeArray<JpWorkItem * JpWorkerLaneAdmission>(max 0 requestedCount)
                                        let mutable keepReserving = true
                                        while reserved.Count < requestedCount && keepReserving do
                                            match jpSpecializationQueueTryRemoveRunnable () with
                                            | JpSpecializationRunnableQueueRemoved(work, _, laneAdmission) ->
                                                reserved.Add((work, laneAdmission))
                                            | JpSpecializationRunnableQueueDeferred _
                                            | JpSpecializationRunnableQueueEmpty -> keepReserving <- false
                                        reserved.ToArray()
                                    let queueDepthBefore = (jpSpecializationQueueDepth ())
                                    let activeWorkerCountBefore = int ((jpWorkLedgerRead()).workerActive |> CompilerKernelV2.Measured.value)
                                    let activeJobsSnapshot = jp_active_jobs.ToArray()
                                    let exactWaitBlockedCount =
                                        jpActiveJobsExactAcyclicWaitCount
                                            (jpActiveWorkTimingNowMs())
                                            activeJobsSnapshot
                                    let stalledCapacityDemand =
                                        if stallEscalation then
                                            min queueDepthBefore activeWorkerCountBefore
                                        else 0
                                    let exactWaitProducerRescue =
                                        queueDepthBefore > 0
                                        && (exactWaitBlockedCount > 0 || stalledCapacityDemand > 0)
                                    let parkedWaiterCount =
                                        min activeWorkerCountBefore exactWaitBlockedCount
                                    let runnableWorkerCountBefore =
                                        max 0 (activeWorkerCountBefore - parkedWaiterCount)
                                    let workerPopulationLimit =
                                        if exactWaitProducerRescue then
                                            jp_exact_wait_worker_population_limit
                                        else
                                            jp_worker_population_core_limit
                                    let availablePopulationSlots =
                                        max 0 (workerPopulationLimit - activeWorkerCountBefore)
                                    let availableRunnableSlots =
                                        max 0 (jp_worker_population_core_limit - runnableWorkerCountBefore)
                                    let availableWorkerSlots =
                                        min availablePopulationSlots availableRunnableSlots
                                    let exactWaitCompensationTarget =
                                        min jp_exact_wait_rescue_limit
                                            (max exactWaitBlockedCount stalledCapacityDemand)
                                    let effectiveCompensationLimit =
                                        if exactWaitProducerRescue then
                                            max jp_blocking_compensation_limit exactWaitCompensationTarget
                                        else
                                            jp_blocking_compensation_limit
                                    let requestOccurrence, emitRequest =
                                        DiagJson.sparseLogDecision
                                            (FastRuntimeFormat.format "jp_blocking_compensation_request|%d|%s|blocked=%d|demand=%d|limit=%d" [| box generation; box requestText; box exactWaitBlockedCount; box stalledCapacityDemand; box effectiveCompensationLimit |])
                                            64L
                                    if emitRequest then
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"jp_blocking_compensation_request_evaluated\",\"generation\":%d,\"request_du\":%s,\"queue_depth\":%d,\"total_workers\":%d,\"runnable_workers\":%d,\"parked_exact_waiters\":%d,\"runnable_limit\":%d,\"population_limit\":%d,\"available_worker_slots\":%d,\"exact_wait_blocked_count\":%d,\"stalled_capacity_demand\":%d,\"current_compensation_workers\":%d,\"effective_compensation_limit\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"state_first3_power2_every64\",\"authority\":\"typed_request_plus_runnable_capacity_snapshot\",\"next\":\"reserve_concrete_producer_work_or_report_capacity\"}" [| box generation; box (DiagJson.esc requestText); box queueDepthBefore; box activeWorkerCountBefore; box runnableWorkerCountBefore; box parkedWaiterCount; box jp_worker_population_core_limit; box workerPopulationLimit; box availableWorkerSlots; box exactWaitBlockedCount; box stalledCapacityDemand; box jp_blocking_compensation_worker_count; box effectiveCompensationLimit; box requestOccurrence |])
                                    if currentGeneration <> generation then
                                        JpBlockingCompensationRejectedStale(generation, currentGeneration)
                                    elif queueDepthBefore <= 0 then
                                        // A replacement worker cannot make progress without queued
                                        // producer work. Queue-empty waits need graph recovery, not
                                        // more runnable OS threads.
                                        JpBlockingCompensationNotRequired
                                    elif availableRunnableSlots <= 0 then
                                        if emitRequest then
                                            DiagJson.emit (
                                                FastRuntimeFormat.format "{\"kind\":\"jp_blocking_compensation_refused_at_runnable_capacity\",\"generation\":%d,\"request_du\":%s,\"queue_depth\":%d,\"total_workers\":%d,\"runnable_workers\":%d,\"parked_exact_waiters\":%d,\"runnable_limit\":%d,\"population_limit\":%d,\"exact_wait_blocked_count\":%d,\"installed_compensation_workers\":%d,\"decision_du\":\"RefusedAtRunnableCapacity\",\"authority\":\"runnable_core_cap\",\"next\":\"await_running_producer_or_surface_wait_graph_blocker\"}" [| box generation; box (DiagJson.esc requestText); box queueDepthBefore; box activeWorkerCountBefore; box runnableWorkerCountBefore; box parkedWaiterCount; box jp_worker_population_core_limit; box workerPopulationLimit; box exactWaitBlockedCount; box jp_blocking_compensation_worker_count |])
                                        JpBlockingCompensationRefusedAtRunnableCapacity(
                                            generation,
                                            runnableWorkerCountBefore,
                                            jp_worker_population_core_limit,
                                            activeWorkerCountBefore,
                                            workerPopulationLimit,
                                            parkedWaiterCount,
                                            queueDepthBefore)
                                    elif availablePopulationSlots <= 0 then
                                        if emitRequest then
                                            DiagJson.emit (
                                                FastRuntimeFormat.format "{\"kind\":\"jp_blocking_compensation_refused_at_population_capacity\",\"generation\":%d,\"request_du\":%s,\"queue_depth\":%d,\"total_workers\":%d,\"runnable_workers\":%d,\"parked_exact_waiters\":%d,\"runnable_limit\":%d,\"population_limit\":%d,\"exact_wait_blocked_count\":%d,\"installed_compensation_workers\":%d,\"decision_du\":\"RefusedAtPopulationCapacity\",\"authority\":\"bounded_two_threads_per_core_population\",\"next\":\"surface_parked_rescuer_wait_graph_or_await_release\"}" [| box generation; box (DiagJson.esc requestText); box queueDepthBefore; box activeWorkerCountBefore; box runnableWorkerCountBefore; box parkedWaiterCount; box jp_worker_population_core_limit; box workerPopulationLimit; box exactWaitBlockedCount; box jp_blocking_compensation_worker_count |])
                                        JpBlockingCompensationRefusedAtPopulationCapacity(
                                            generation,
                                            runnableWorkerCountBefore,
                                            jp_worker_population_core_limit,
                                            activeWorkerCountBefore,
                                            workerPopulationLimit,
                                            parkedWaiterCount,
                                            queueDepthBefore)
                                    elif jp_blocking_compensation_generation <> generation then
                                        let requestedFirstWaveRaw =
                                            if CacheGeneration.isSequentialRequested() then
                                                min 1 effectiveCompensationLimit
                                            else
                                                min queueDepthBefore
                                                    (min jp_blocking_compensation_wave effectiveCompensationLimit)
                                        let requestedFirstWave =
                                            min availableWorkerSlots requestedFirstWaveRaw
                                        let reservedWork = reserveQueuedWork requestedFirstWave
                                        let firstWaveCount = reservedWork.Length
                                        let startedWorkerCount =
                                            reservedWork
                                            |> Array.mapi (fun index work ->
                                                worker (worker_count + index + 1) (Some work))
                                            |> Array.filter id
                                            |> Array.length
                                        if startedWorkerCount <= 0 then
                                            JpBlockingCompensationNotRequired
                                        else
                                            jp_blocking_compensation_generation <- generation
                                            jp_blocking_compensation_worker_count <- startedWorkerCount
                                            emitExpansion
                                                DiagJson.TypedDiagJpBlockingCompensationStarted
                                                startedWorkerCount
                                                firstWaveCount
                                                startedWorkerCount
                                                queueDepthBefore
                                                (jpSpecializationQueueDepth ())
                                                effectiveCompensationLimit
                                                exactWaitProducerRescue
                                                exactWaitBlockedCount
                                            JpBlockingCompensationStarted(generation, startedWorkerCount)
                                    else
                                        let currentCompensation = jp_blocking_compensation_worker_count
                                        let installedWorkerCount = worker_count + currentCompensation
                                        if currentCompensation >= effectiveCompensationLimit then
                                            JpBlockingCompensationAtCapacity(generation, currentCompensation)
                                        elif activeWorkerCountBefore >= installedWorkerCount then
                                            let requestedAddedWorkersRaw =
                                                min queueDepthBefore
                                                    (min jp_blocking_compensation_wave
                                                        (effectiveCompensationLimit - currentCompensation))
                                            let requestedAddedWorkers =
                                                min availableWorkerSlots requestedAddedWorkersRaw
                                            let reservedWork = reserveQueuedWork requestedAddedWorkers
                                            let reservedWorkerCount = reservedWork.Length
                                            let addedWorkerCount =
                                                reservedWork
                                                |> Array.mapi (fun index work ->
                                                    worker (worker_count + currentCompensation + index + 1) (Some work))
                                                |> Array.filter id
                                                |> Array.length
                                            if addedWorkerCount <= 0 then
                                                JpBlockingCompensationNotRequired
                                            else
                                                let nextCompensation = currentCompensation + addedWorkerCount
                                                jp_blocking_compensation_worker_count <- nextCompensation
                                                emitExpansion
                                                    DiagJson.TypedDiagJpBlockingCompensationExpanded
                                                    addedWorkerCount
                                                    reservedWorkerCount
                                                    nextCompensation
                                                    queueDepthBefore
                                                    (jpSpecializationQueueDepth ())
                                                    effectiveCompensationLimit
                                                    exactWaitProducerRescue
                                                    exactWaitBlockedCount
                                                JpBlockingCompensationExpanded(generation, addedWorkerCount, nextCompensation)
                                        else
                                            JpBlockingCompensationAlreadyStarted(generation, currentCompensation))
                        DiagJson.emitRecord
                            ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpParallelTopology
                               environment_processor_count = jp_environment_processor_count
                               affinity_observation_du = jpProcessorAffinityObservationText jp_affinity_observation
                               affinity_processor_count = jp_affinity_processor_count
                               base_worker_count = worker_count
                               assist_max_concurrent_leases = jp_assist_max_concurrent_leases
                               blocking_compensation_wave = jp_blocking_compensation_wave
                               blocking_compensation_limit = jp_blocking_compensation_limit
                               exact_wait_rescue_limit = jp_exact_wait_rescue_limit
                               normal_max_worker_count = jp_worker_population_core_limit
                               exact_wait_rescue_max_worker_count = jp_exact_wait_worker_population_limit
                               effective_worker_count = worker_count
                               capacity_authority_du = jpProcessorCapacityAuthorityText jp_processor_capacity_authority
                               sequential_requested = CacheGeneration.isSequentialRequested()
                               scheduler_du = "SingleAuthorityTypedSemanticObserverLanesWithExactProducerDonation"
                               observer_limit_while_semantic_open = 1
                               authority = "jp_worker_start_once" }
                             : JpParallelTopologyEvent)
                        let mutable initialWorkersStarted = 0
                        for i = 1 to worker_count do
                            if worker i None then initialWorkersStarted <- initialWorkersStarted + 1
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"jp_worker_stack_initial_population_receipt\",\"requested_worker_count\":%d,\"started_worker_count\":%d,\"stack_bytes_requested_per_worker\":%d,\"all_requested_workers_started\":%s,\"authority\":\"direct_initial_worker_population_start_receipt\",\"survival_authority_du\":\"DirectEnvelopeBypassTypedSerializer\",\"next\":\"correlate_any_stack_overflow_with_started_expanded_stack_population\"}" [| box worker_count; box initialWorkersStarted; box (jpWorkerStackBytes jpWorkerStackPolicy); box (if initialWorkersStarted = worker_count then "true" else "false") |])
                        

                        start_jp_watchdog ()
                )

        // Terminal ForceReplayDrain is a control-plane request.  If outstanding
        // semantic work is already owned by the JP declared-body scheduler, the
        // correct action is to coalesce with that scheduler rather than poke an
        // empty EvalWorklist replay queue.  This hook does not manufacture progress;
        // it only proves that a live semantic drain owner exists and ensures workers
        // have been started.
        DiagJson.registerSemanticSchedulerDrainRequestHook (fun _reason _attempts ->
            let queuedDeclaredBodies = jpSpecializationDeclaredBodyQueueDepth ()
            let activeDeclaredBodies = jpActiveDeclaredBodyWorkerCount ()
            if queuedDeclaredBodies > 0 || activeDeclaredBodies > 0 then
                start_jp_workers ()
                true
            else
                false)
    
        let jpExecutionContextCreate spawn recursion bigStack =
            { spawn = spawn
              recursion = recursion
              bigStack = bigStack
              contextRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-execution-context"
                    (CompilerIdentityKernel.ContentDigest.text spawn.contextRef
                     + "|depth=" + string (RecursionTracker.currentDepth recursion)) }

        // MIGRATION: jp_start accepts an explicit execution context.  Scheduler
        // migration cannot inherit a name, recursion depth or BigStack nesting
        // from the OS thread that happened to enqueue the job.

        let rec jp_start context (run: unit -> unit) : Job<unit> =
            jp_start_named context "" run

        and jp_start_named context (name:string) (run:unit -> unit) : Job<unit> =
            jp_start_named_with_promise context name None run

        and jp_start_named_with_promise
            context
            (name:string)
            (promiseRegistration:JpPromiseProducerRegistration option)
            (run:unit -> unit)
            : Job<unit> =
            jp_start_named_with_metadata
                context
                name
                promiseRegistration
                JpWorkComputationMetadataUnavailable
                (fun () -> run(); JpWorkExecutionCompleted)

        and jp_start_named_with_metadata
            (context:JpExecutionContext)
            (name:string)
            (promiseRegistration:JpPromiseProducerRegistration option)
            (computationMetadata:JpWorkComputationMetadata)
            (run:unit -> JpWorkExecutionOutcome)
            : Job<unit> =
            let normalizedName =
                if System.String.IsNullOrEmpty name then jpSpawnContextName context.spawn else name
            let siteId = CompilerIdentityKernel.WorkSiteIdOps.create normalizedName
            let shapeId = CompilerIdentityKernel.WorkShapeIdOps.create normalizedName
            let instantiationId =
                CompilerKernelV2.InstantiationIdOps.create
                    (CompilerIdentityKernel.ContentDigest.text context.contextRef)
            let backendId = CompilerKernelV2.BackendIdOps.create "host"
            let generation = CacheGeneration.current ()
            let binding =
                CompilerKernelV2.StableBindingId.createSemantic
                    0
                    "spiral.compiler"
                    normalizedName
                    (CompilerIdentityKernel.ContentDigest.text context.contextRef)
                    "join-point"
                    "host"
            let ownerIdentity =
                CompilerKernelV2.StableBindingId.createSemantic
                    0
                    "spiral.compiler"
                    (normalizedName + ":owner")
                    (CompilerIdentityKernel.ContentDigest.text context.contextRef)
                    "join-point-owner"
                    "host"
            let workUnit =
                CompilerKernelV2.WorkUnitIdOps.create<
                    CompilerKernelV2.ElaboratedPhase,
                    CompilerKernelV2.JoinPointWorkKind>
                    binding
                    generation
                    instantiationId
                    backendId
            let commitOrdinal =
                max 1L (
                    int64 (
                        NativeCutoverStableRef.ref32
                            "jp-work-commit-ordinal"
                            [ CompilerKernelV2.StableBindingId.text binding
                              string generation
                              CompilerIdentityKernel.ContentDigest.text context.contextRef ]))
            let owner = CompilerKernelV2.WorkOwnerCapabilityOps.bind ownerIdentity
            let semanticCost =
                CompilerKernelV2.Measured.create<CompilerKernelV2.SemanticCostUnit>
                    "jpStartCost"
                    1L
            let queued =
                CompilerKernelV2.WorkItemOps.createQueued
                    workUnit
                    owner
                    generation
                    []
                    siteId
                    semanticCost
                    commitOrdinal
            let descriptor =
                match computationMetadata with
                | JpWorkComputationMetadata descriptor -> descriptor
                | JpWorkComputationMetadataUnavailable ->
                    jpWorkDescriptorCreate
                        generation
                        (JpAnonymousComputation(binding, siteId))
                        instantiationId
                        JpComputationMemoNotApplicable
                        JpSemanticProducer
                        JpAnonymousSpecializationIntent
                        JpRuntimeEffectPure
                        JpSpecializationAdmitOwnedCell
            let openSpecializationPlan =
                CompilerKernelV2.JoinPointSpecializationPlan.create
                    workUnit
                    ownerIdentity
                    generation
                    normalizedName
            let loweringBoundaryRef =
                CompilerIdentityKernel.ContentDigest.ofText
                    "jp-specialization-lowering-boundary"
                    (CompilerKernelV2.StableBindingId.text binding
                     + "|generation=" + string generation
                     + "|context=" + CompilerIdentityKernel.ContentDigest.text context.contextRef)
            let specializationPlan, specializationInteractionReceipt =
                CompilerKernelV2.JoinPointSpecializationPlan.lowerPureGraph
                    loweringBoundaryRef
                    openSpecializationPlan
            let cancelWork request =
                CompilerKernelV2.CompilerRuntimeKernel.effect
                    "jp-work-cancel"
                    (job {
                        if jpWorkCancellationRequestCancelsPromise request then
                            let cancellationRef =
                                CompilerIdentityKernel.ContentDigest.ofText
                                    "jp-promise-producer-cancelled"
                                    (CompilerKernelV2.StableBindingId.text binding
                                     + "|reason=" + jpWorkCancellationRequestReason request)
                            match promiseRegistration with
                            | Some registration ->
                                JpPromiseProducerAuthority.cancel registration cancellationRef
                            | None -> ()
                        return ()
                    })
            let declaredBodySliceBasis, declaredBodySliceBudget =
                let basis, maxOperations, checkpointInterval =
                    match descriptor.runtimeEffect with
                    | JpRuntimeEffectRequired witness ->
                        match witness.effectScope with
                        | JpRuntimeEffectProcessStable
                        | JpRuntimeEffectGenerationStable ->
                            JpDeclaredBodyStableRuntimeEffectSlice(witness.effectKind, witness.effectScope), 256, 64
                        | JpRuntimeEffectInvocationVolatile ->
                            JpDeclaredBodyDefaultSlice, 96, 24
                    | JpRuntimeEffectPure ->
                        JpDeclaredBodyPureSlice, 256, 64
                // Declared bodies don't time-slice by default: the budget is out of reach (2^24 operations,
                // a checkpoint every 2^22 bindings; the recovery multiplier, at most 4, can't overflow it).
                // Resuming a yielded body loses or repeats statements: a resume continues in the environments
                // the earlier slice saved, and so in that slice's block, while prefix replay re-evaluates the
                // body and re-emits it (lanes/hopac/FRONTIER.md, fix 22). The budgets above are what the resume
                // path was designed for; SPIRAL_JP_SLICE_OPS=<max>,<interval> (256,64 or 96,24) brings them back.
                let maxOperations, checkpointInterval =
                    match System.Environment.GetEnvironmentVariable "SPIRAL_JP_SLICE_OPS" with
                    | null | "" -> 1 <<< 24, 1 <<< 22
                    | text ->
                        match text.Split ',' with
                        | [| m; i |] -> int m, int i
                        | _ -> invalidOp ("SPIRAL_JP_SLICE_OPS must be <max>,<interval>: " + text)
                let budget =
                    match JpWorkSliceBudgetOps.tryCreate maxOperations checkpointInterval with
                    | Some budget -> budget
                    | None -> invalidOp "declared-body slice budget invariant failed"
                basis, budget
            let executionPolicy =
                match descriptor.workNode.intent with
                | JpVerifyDeclaredMethodBody -> JpWorkExecutionBoundedSlice(declaredBodySliceBasis, declaredBodySliceBudget)
                | _ -> JpWorkExecutionRunToCompletionLegacy
            let executeWork _ =
                CompilerKernelV2.CompilerRuntimeKernel.effect
                    "jp-work-execute"
                    (job {
                        match executionPolicy with
                        | JpWorkExecutionBoundedSlice _ ->
                            try
                                return run ()
                            with
                            | JpDeclaredEvaluatorSliceYield(yieldCause, continuationRef) ->
                                return JpWorkExecutionYielded(continuationRef, yieldCause)
                            | EvalReplayValueStore.PatternMissBreakthroughEscapeTransport escape ->
                                return JpWorkExecutionPatternMissDeferredControl (EvalReplayValueStore.evaluatorPatternMissDeferredEscapeSignal escape)
                            | JpTerminalFailureRunningCutoverCancellation ->
                                return jpTerminalFailureCutoverCancellationOutcome workUnit commitOrdinal
                        | JpWorkExecutionRunToCompletionLegacy ->
                            try
                                return run ()
                            with
                            | EvalReplayValueStore.PatternMissBreakthroughEscapeTransport escape ->
                                return JpWorkExecutionPatternMissDeferredControl (EvalReplayValueStore.evaluatorPatternMissDeferredEscapeSignal escape)
                            | JpTerminalFailureRunningCutoverCancellation ->
                                return jpTerminalFailureCutoverCancellationOutcome workUnit commitOrdinal
                    })
            let executionPlan =
                { specializationPlan = specializationPlan
                  specializationInteractionReceipt = specializationInteractionReceipt
                  computationMetadata = computationMetadata
                  workNode = descriptor.workNode
                  authorityRole = descriptor.authorityRole
                  siteId = siteId
                  shapeId = shapeId
                  executionPolicy = executionPolicy
                  execute = executeWork
                  cancel = cancelWork }
            let workItem =
                { operational = JpWorkOperationalCursor.queued queued
                  executionPlan = executionPlan
                  semanticResumeContinuation = None
                  typedCarrierProofGate = JpTypedCarrierProofGateOpen }
            // A spawn lease is acquired synchronously while the work job is built.
            // Quiescence therefore sees work that has been scheduled but has not yet
            // reached the actor-owned operational graph.  The lease is released only
            // after admission/duplicate/rejection has become explicit.
            let spawnAdmissionLease = jpSpawnAdmissionAcquire workItem
            job {
                try
                    start_jp_workers ()
                    let terminalCutoverSuppressionReason =
                        CompilerKernelV2.OperationalReasonIdOps.create
                            "typed_terminal_failure_cutover_suppresses_new_admission"
                    let! admission =
                        if DiagJson.terminalFailureExitRequestedNow() then
                            Job.result (JpWorkAdmissionTerminalCutoverSuppressed terminalCutoverSuppressionReason)
                        else
                            jp_register_work_item workItem
                    match admission with
                    | JpWorkAdmissionGranted ->
                        // Bind the promise only after canonical graph admission and before
                        // queue exposure.  The binding cell is now exact-once: a conflicting
                        // producer is retired locally and can never overwrite the canonical owner.
                        let! promiseBindingReady =
                            match promiseRegistration with
                            | None -> Job.result true
                            | Some registration ->
                                match JpPromiseProducerAuthority.bind registration commitOrdinal with
                                | JpPromiseProducerBound _
                                | JpPromiseProducerBindingReused _ -> Job.result true
                                | JpPromiseProducerBindingConflict(existing, proposed) ->
                                    let failureRef =
                                        CompilerIdentityKernel.ContentDigest.ofText
                                            "jp-promise-producer-binding-conflict"
                                            (CompilerIdentityKernel.ContentDigest.text existing.bindingRef
                                             + "|proposed=" + CompilerIdentityKernel.ContentDigest.text proposed.bindingRef)
                                    match JpSpecializationWorklistAuthority.tryTerminalDisposition workItem.workNode with
                                    | Some terminalDisposition ->
                                        job {
                                            let! semanticMutationApplied =
                                                jp_retire_terminal_unstarted_admission terminalDisposition workItem
                                            DiagJson.emit (
                                                FastRuntimeFormat.format
                                                    "{\"kind\":\"jp_terminal_redundant_admission_retired_before_queue\",\"work_unit_id\":%s,\"failure_ref\":%s,\"terminal_ref\":%s,\"terminal_disposition_du\":%s,\"queue_exposed\":false,\"body_executed\":false,\"semantic_mutation_expected\":%b,\"semantic_mutation_applied\":%b,\"authority\":\"canonical_terminal_precedes_conflicting_producer_failure_redelivery\",\"next\":\"continue_with_retired_admission_without_queue_exposure\"}"
                                                    [| box (DiagJson.esc (CompilerKernelV2.WorkUnitIdOps.digestText workItem.workUnit)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text failureRef)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text (jpTerminalDispositionRef terminalDisposition))); box (DiagJson.esc (CompilerKernelV2.WorkTerminalDispositionOps.text terminalDisposition)); box (jpWorkAuthorityRoleOwnsSemanticLedger workItem.authorityRole); box semanticMutationApplied |])
                                            return false
                                        }
                                    | None ->
                                        job {
                                            do! jp_fail_work_item
                                                    JpFailureDeliveryUnstartedOwner
                                                    (JpRejectedAdmissionCancellation(
                                                        CompilerKernelV2.OperationalReasonIdOps.create
                                                            "promise_producer_binding_conflict"))
                                                    (JpPromiseProducerBindingConflictFailure failureRef)
                                                    workItem
                                            return false
                                        }
                        if promiseBindingReady then
                            match jpSpecializationQueueEnqueue workItem with
                            | JpSpecializationQueueAdmitted depthAfter ->
                                jpWorkAdmissionTimingRegister commitOrdinal (max 0L (jp_progress_clock()))
                                DiagJson.emitRecord
                                    ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitScheduled
                                       work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText workUnit
                                       producer_work_id = commitOrdinal
                                       generation = generation
                                       queue_depth_after = depthAfter
                                       lane_du = jpSchedulingLaneText (jpSchedulingLaneFor descriptor.authorityRole descriptor.workNode.intent)
                                       execution_policy_du = jpWorkExecutionPolicyText workItem.executionPolicy
                                       authority = "typed_jp_scheduler_queue"
                                       next = "dedicated_worker_executes_then_retires_semantic_receipt" }
                                     : JpWorkUnitScheduledEvent)
                                return ()
                            | JpSpecializationQueueBackpressured(depth, capacity) ->
                                let cancellationRef =
                                    CompilerIdentityKernel.ContentDigest.ofText
                                        "jp-specialization-queue-backpressure"
                                        (CompilerKernelV2.WorkUnitIdOps.digestText workUnit
                                         + "|depth=" + string depth
                                         + "|capacity=" + string capacity)
                                let cancellationReason =
                                    CompilerKernelV2.OperationalReasonIdOps.create "scheduler_queue_full"
                                do! jp_cancel_work_item
                                        (JpQueueBackpressureCancellation(cancellationReason, cancellationRef))
                                        workItem
                                return ()
                    | JpWorkAdmissionDuplicateSuppressed existingState ->
                        DiagJson.emitRecord
                            ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpWorkUnitScheduleDuplicateSuppressed
                               work_unit_id = CompilerKernelV2.WorkUnitIdOps.digestText workUnit
                               producer_work_id = commitOrdinal
                               generation = generation
                               existing_operational_state_du = CompilerKernelV2.operationalWorkGraphNodeStateText existingState
                               authority = "single_operational_graph_exact_once" }
                             : JpWorkUnitScheduleDuplicateSuppressedEvent)
                        return ()
                    | JpWorkAdmissionTerminalCutoverSuppressed reasonId ->
                        do! CompilerKernelV2.CompilerRuntimeKernel.toJob (workItem.cancel (JpHostRequestedCancellation reasonId))
                        DiagJson.emit (
                            FastRuntimeFormat.format
                                "{\"kind\":\"jp_terminal_failure_new_admission_suppressed\",\"generation\":%d,\"commit_ordinal\":%d,\"work_unit_id\":%s,\"semantic_credit_admitted\":false,\"queue_exposed\":false,\"promise_bound\":false,\"reason_du\":%s,\"authority\":\"typed_terminal_failure_cutover_before_semantic_admission\",\"next\":\"await_existing_owner_credit_return_only\"}"
                                [| box generation; box commitOrdinal; box (DiagJson.esc (CompilerKernelV2.WorkUnitIdOps.digestText workUnit)); box (DiagJson.esc (CompilerKernelV2.OperationalReasonIdOps.text reasonId)) |])
                        return ()
                    | JpWorkAdmissionRejected conflict ->
                        let rejectionRef =
                            CompilerIdentityKernel.ContentDigest.ofText
                                "jp-work-scheduler-admission-rejected"
                                (CompilerKernelV2.WorkUnitIdOps.digestText workUnit
                                 + "|" + semanticWorkLedgerConflictText conflict)
                        match promiseRegistration with
                        | Some registration -> JpPromiseProducerAuthority.fail registration rejectionRef
                        | None -> ()
                        return raise (
                            PartEvalTypeError(
                                [],
                                "JP scheduler admission rejected: "
                                + semanticWorkLedgerConflictText conflict))
                finally
                    jpSpawnAdmissionRelease spawnAdmissionLease
            }

        // MIGRATION: force-close cannot ignore explicit worklist replay.  Historical runtime
        // reached a writer-blocked pseudo-BuildOk with pending explicit frames and a replay queue,
        // producing a tiny F# placeholder artifact.  Keep the barrier close decision typed so
        // pending worklist/replay evidence defers the close instead of opening the writer path.

        // Global JP quiescence is a logical wait over both the actor-owned operational graph
        // and the spawn-admission lease set.  A producer acquires its lease synchronously
        // before its Hopac job can be observed, so an empty graph cannot outrun pending admission.
        let jpAwaitCombinedQuiescence () : Job<CompilerIdentityKernel.ContentDigest * int64> =
            job {
                let mutable resolved : (CompilerIdentityKernel.ContentDigest * int64) option = None
                while Option.isNone resolved do
                    let! _ = jpSpawnAdmissionAwaitZero ()
                    let! graphRef = jp_operational_work_await_quiescence ()
                    let spawnSnapshot = jpSpawnAdmissionSnapshot ()
                    if spawnSnapshot.activeCount = 0 then
                        resolved <- Some(graphRef, spawnSnapshot.epoch)
                return Option.get resolved
            }

        let jp_wait () : Job<unit> =
            job {
                let! graphRef, spawnEpoch = jpAwaitCombinedQuiescence ()
                let operationalLedgerState = SemanticWorkLedgerProjection.readOperational ()
                let operationalAdmitted, operationalReceipts, operationalOpen =
                    SemanticWorkLedgerProjection.countsOf operationalLedgerState
                let terminalProtocolAdmitted, terminalProtocolReceipts =
                    CompilerKernelV2.SemanticWorkLedgerAuthority.countsForScope
                        CompilerKernelV2.SemanticWorkTerminalProtocol
                let terminalProtocolOpen =
                    max 0L (int64 terminalProtocolAdmitted - int64 terminalProtocolReceipts)
                let replayQueueSnapshot = EvalWorklist.replayQueueQuiescenceSnapshot ()
                let replayQuiescenceDecision =
                    jpReplayQuiescenceDecisionFor
                        replayQueueSnapshot.queueDepth
                        replayQueueSnapshot.activeDepth
                        operationalOpen
                let replayLivenessNormalization = EvalWorklist.normalizeReplayLivenessForQuiescence ()
                let replayLivenessAtQuiescence = replayLivenessNormalization.after
                let replayLivenessClosed = EvalWorklist.replayLivenessAllEmpty replayLivenessAtQuiescence
                let replayQuiescenceRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-replay-closed-liveness"
                        (CompilerIdentityKernel.ContentDigest.text graphRef
                         + "|spawn_epoch=" + string spawnEpoch
                         + "|liveness=" + EvalWorklist.replayLivenessProofText replayLivenessAtQuiescence)
                let replayCreditReconciliation =
                    match replayQuiescenceDecision with
                    | JpReplayQuiescenceCreditWithoutQueue when replayLivenessClosed ->
                        match CompilerKernelV2.SemanticWorkLedgerAuthority.reconcileQuiescentReplayCredits replayQuiescenceRef with
                        | Ok receipt -> Some receipt
                        | Error conflict ->
                            DiagJson.emit (
                                FastRuntimeFormat.format
                                    "{\"kind\":\"jp_quiescent_replay_credit_reconciliation_rejected\",\"graph_ref\":%s,\"quiescence_ref\":%s,\"conflict_du\":%s,\"authority\":\"typed_closed_replay_liveness_never_overrides_ledger_conflict\",\"next\":\"retain_operational_credit_and_fail_closed_if_terminal_requires_it\"}"
                                    [| box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text graphRef))
                                       box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text replayQuiescenceRef))
                                       box (DiagJson.esc (semanticWorkLedgerConflictText conflict)) |])
                            None
                    | _ -> None
                let replayCreditProjection : JpReplayCreditReconciliationProjection =
                    match replayCreditReconciliation with
                    | Some receipt ->
                        { reconciledCount = CompilerKernelV2.SemanticWorkQuiescentReplayCreditReconciliationOps.cancelledCount receipt
                          openAfterReconciliation = int64 (CompilerKernelV2.SemanticWorkQuiescentReplayCreditReconciliationOps.remainingOperationalOpenCount receipt)
                          reconciliationRef = Some (CompilerKernelV2.SemanticWorkQuiescentReplayCreditReconciliationOps.receiptDigest receipt) }
                    | None ->
                        { reconciledCount = 0
                          openAfterReconciliation = operationalOpen
                          reconciliationRef = None }
                let replayDrainReason =
                    CompilerKernelV2.OperationalReasonIdOps.create "jp_quiescence_queued_replay_without_active_driver"
                let replayDrainScheduled =
                    match replayQuiescenceDecision with
                    | JpReplayQuiescenceDrainQueuedReplay ->
                        EvalWorklist.forceReplayDriverOrphanDrainWorker
                            (EvalWorklist.ReplayTickEventForcedDrain replayDrainReason)
                            replayDrainReason
                    | _ -> false
                let replayQuiescenceAction =
                    jpReplayQuiescenceActionFor
                        replayQuiescenceDecision
                        replayDrainScheduled
                        replayCreditProjection.openAfterReconciliation
                let quiescenceNext = jpReplayQuiescenceActionText replayQuiescenceAction
                DiagJson.emitRecord
                    ({ kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpOperationalGraphQuiescent
                       graph_ref = CompilerIdentityKernel.ContentDigest.text graphRef
                       spawn_admission_epoch = spawnEpoch
                       spawn_in_flight = 0
                       semantic_operational_admitted = operationalAdmitted
                       semantic_operational_receipts = operationalReceipts
                       semantic_operational_open = operationalOpen
                       semantic_terminal_protocol_open = terminalProtocolOpen
                       replay_queue_depth = replayQueueSnapshot.queueDepth
                       replay_active_depth = replayQueueSnapshot.activeDepth
                       replay_quiescence_du = jpReplayQuiescenceDecisionText replayQuiescenceDecision
                       replay_head_work_unit = EvalWorklist.replayQueueQuiescenceHeadWorkUnitText replayQueueSnapshot
                       replay_head_task_id = replayQueueSnapshot.headTaskId
                       replay_head_key = EvalWorklist.replayQueueQuiescenceHeadKeyText replayQueueSnapshot
                       replay_head_driver_du = EvalWorklist.replayQueueQuiescenceHeadDriverText replayQueueSnapshot
                       replay_head_status_du = EvalWorklist.replayQueueQuiescenceHeadStatusText replayQueueSnapshot
                       replay_drain_scheduled = replayDrainScheduled
                       replay_liveness_closed = replayLivenessClosed
                       replay_liveness_pending = replayLivenessAtQuiescence.pending
                       replay_liveness_deferred_cell_present = replayLivenessAtQuiescence.hasDeferredCell
                       replay_liveness_progress_yield_pending = replayLivenessAtQuiescence.hasProgressYield
                       replay_liveness_normalization_du = EvalWorklist.replayQuiescenceLivenessNormalizationText replayLivenessNormalization.decision
                       replay_progress_yield_residue_retired_count = EvalWorklist.replayQuiescenceLivenessRetiredProgressYieldCount replayLivenessNormalization.decision
                       replay_credit_reconciled_count = replayCreditProjection.reconciledCount
                       replay_credit_open_after_reconciliation = replayCreditProjection.openAfterReconciliation
                       replay_credit_reconciliation_ref =
                           replayCreditProjection.reconciliationRef
                           |> Option.map CompilerIdentityKernel.ContentDigest.text
                           |> Option.defaultValue ""
                       authority = "operational_graph_plus_spawn_admission_lease_plus_typed_replay_quiescence"
                       next = quiescenceNext }
                     : JpOperationalGraphQuiescentEvent)
                if jpReplayQuiescenceActionRetriesTerminal replayQuiescenceAction then
                    // The graph can become exactly closed without another semantic progress tick.
                    // Refresh typed operational evidence first so the reducer can mint the closed-work
                    // QAP witness; the heartbeat itself retries any already-indexed closure afterward.
                    CompilerConsoleHud88.invokeTerminalLedgerHeartbeat ()
                return ()
            }


        let rec ty_to_data s x =
            // Structural Ty->Data conversion is intentionally iterative. The mutual-recursion
            // marker remains because nominal_type_apply/ty belong to the evaluator knot, but
            // arbitrarily deep YPair/YRecord trees no longer consume the CLR call stack.
            let frames = System.Collections.Generic.Stack<TyToDataTraversalFrame>()
            let results = System.Collections.Generic.Stack<Data>()
            let popResult context =
                if results.Count = 0 then invalidOp ("Ty->Data postorder invariant: missing result while building " + context)
                results.Pop()
            let pushRuntimeVariable current =
                let result = DV(L(s.i.Value,current))
                s.i.Value <- s.i.Value + 1
                results.Push result
            frames.Push(TyToDataVisit x)
            while frames.Count > 0 do
                match frames.Pop() with
                | TyToDataVisit current ->
                    match current with
                    | YVoid ->
                        // par: The evaluator can transiently demand a term for YVoid during sequencing
                        // or placeholder materialization under parallel retries. Coerce it to unit data (DB) instead of aborting.
                        // Any semantically invalid usage should reappear later as a type mismatch rather than a fatal abort.
                        results.Push DB
                    | YB -> results.Push DB
                    | YPair(left,right) ->
                        frames.Push TyToDataBuildPair
                        frames.Push(TyToDataVisit right)
                        frames.Push(TyToDataVisit left)
                    | YSymbol _ when isJpMethodOrTypePlaceholderType current ->
                        // If the JP placeholder has already resolved, continue iteratively with
                        // the resolved type rather than recursively re-entering this conversion.
                        let resolved = jp_method_deref_rec_placeholder current
                        if resolved <> current then frames.Push(TyToDataVisit resolved)
                        else pushRuntimeVariable current
                    | YSymbol symbol -> results.Push(DSymbol symbol)
                    | YRecord fields ->
                        let entries =
                            fields
                            |> Seq.map (fun (KeyValue(key,child)) -> key, child)
                            |> Seq.toArray
                        frames.Push(TyToDataBuildRecord entries)
                        for entryIndex = entries.Length - 1 downto 0 do
                            frames.Push(TyToDataVisit(snd entries.[entryIndex]))
                    | YForall | YExists | YUnion _ | YLayout _ | YPrim _ | YArray _ | YFun _ | YMacro _ ->
                        pushRuntimeVariable current
                    | YNominal _ | YApply _ ->
                        let normalized = nominal_type_apply s current
                        frames.Push(TyToDataBuildNominal current)
                        frames.Push(TyToDataVisit normalized)
                    | YLit literal -> results.Push(DTLit literal)
                    | YTypeFunction _ -> raise_type_error s "Cannot turn a type function into a runtime variable."
                    | YMetavar _ -> raise_type_error s "Compiler error: Cannot turn a metavar into a runtime variable."
                | TyToDataBuildPair ->
                    let right = popResult "pair/right"
                    let left = popResult "pair/left"
                    results.Push(DPair(left,right))
                | TyToDataBuildRecord entries ->
                    let values = Array.zeroCreate<Data> entries.Length
                    for entryIndex = entries.Length - 1 downto 0 do
                        values.[entryIndex] <- popResult "record"
                    let mutable fields = Map.empty
                    for entryIndex = 0 to entries.Length - 1 do
                        fields <- Map.add (fst entries.[entryIndex]) values.[entryIndex] fields
                    results.Push(DRecord fields)
                | TyToDataBuildNominal original ->
                    results.Push(DNominal(popResult "nominal", original))
            if results.Count <> 1 then
                invalidOp (sprintf "Ty->Data postorder invariant: expected one root result, got %d." results.Count)
            results.Pop()
        and assert_ty_lit s x =
            let mutable current = x
            let mutable finished = false
            let mutable result = YVoid
            while not finished do
                match current with
                | YSymbol _ | YLit _ ->
                    result <- current
                    finished <- true
                | YNominal _ | YApply _ ->
                    current <- nominal_type_apply s current
                | invalid ->
                    raise_type_error s <| sprintf "Expected a type literal or a symbol.\nGot: %s" (show_ty invalid)
            result
        and push_typedop_no_rewrite d op ret_ty =
            if EvalReplayValueStore.replayEmitRefused (box d.seq) then failwith "replay_emit_into_direct_block"
            let ret = ty_to_data d ret_ty
            d.seq.Add(TyLet(ret,d.trace,op))
            ret
        and push_typedop (d: LangEnv) key ret_ty =
            if EvalReplayValueStore.replayEmitRefused (box d.seq) then failwith "replay_emit_into_direct_block"
            // Hopac jobs evaluating in the same scope share its CSE table, so lookup-then-add (and the
            // matching seq entry) must be atomic: otherwise two jobs both miss, both emit the op, and with a
            // plain Dictionary the second Add threw "An item with the same key has already been added"
            // (seen as TyOp (Dyn, [DLit (LitString ...)])).
            lock (List.head d.cse) (fun () ->
                match cse_tryfind d key with
                | Some x -> x
                | None ->
                    let x = ty_to_data d ret_ty
                    d.seq.Add(TyLet(x,d.trace,key))
                    cse_add d key x
                    x)
        and push_op_no_rewrite' (d: LangEnv) op l ret_ty = push_typedop_no_rewrite d (TyOp(op,l)) ret_ty
        and push_op_no_rewrite d op a ret_ty = push_op_no_rewrite' d op [a] ret_ty
        and push_binop_no_rewrite d op (a,b) ret_ty = push_op_no_rewrite' d op [a;b] ret_ty
        and push_triop_no_rewrite d op (a,b,c) ret_ty = push_op_no_rewrite' d op [a;b;c] ret_ty
    

        and push_op' d op a ret_ty = push_typedop d (TyOp(op, a)) ret_ty
        and push_op d op a ret_ty = push_op' d op [a] ret_ty
        and push_binop d op (a,b) ret_ty = push_op' d op [a;b] ret_ty
        and push_triop d op (a,b,c) ret_ty = push_op' d op [a;b;c] ret_ty
        and closure_env (s: LangEnv) (body,annot,gl_term,gl_ty,sz_term,sz_ty) : LangEnv = {
            trace = s.trace
            traceBudget = s.traceBudget
            recursion = s.recursion
            bigStack = s.bigStack
            evalNodePath = s.evalNodePath
            evalKeyPath = s.evalKeyPath
            seq = ResizeArray()
            cse = [System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural)]
            unions = Map.empty
            i = ref 0
            env_global_type = gl_ty
            env_global_term = gl_term
            env_stack_type = Array.zeroCreate<_> sz_ty
            env_stack_term = Array.zeroCreate<_> sz_term
            backend = s.backend
            globals = s.globals
            globals_lock = s.globals_lock
            globals_seen = s.globals_seen
            join_point_method_key_names = s.join_point_method_key_names
            join_point_closure_key_names = s.join_point_closure_key_names
            jp_method_stack = System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>(s.jp_method_stack, HashIdentity.Reference)
            jp_closure_stack = System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>(s.jp_closure_stack, HashIdentity.Reference)
            jp_type_stack = System.Collections.Generic.HashSet<ConsedNode<Ty []>>(s.jp_type_stack, jp_type_key_comparer)
            }
        and closure_convert (s: LangEnv) (body,annot,gl_term,gl_ty,sz_term,sz_ty as args) =
            let closureOwnerIdentity = JpBodyOwnerIdentity.create s.backend body
            let join_point_key, call_args, fun_ty =
                let s : LangEnv = closure_env s args
                let domain, range, fun_ty =
                    match ty s annot with
                    | YFun(a,b,_) as x -> a,b,x
                    | annot -> raise_type_error s <| sprintf "Expected a function type in annotation during closure conversion. Got: %s" (show_ty annot)
                // MIGRATION: IVar-based dict - no separate dict_ev needed
                let (dict: System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<RData [] * Ty [] * Ty>, Hopac.IVar<JpClosureBodyCellPayload>>), hc_table, cache_gen =
                    Utils.memoize join_point_closure (fun _ ->
                        System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<RData [] * Ty [] * Ty>, Hopac.IVar<JpClosureBodyCellPayload>>(HashIdentity.Reference), HashConsTable(), CacheGeneration.current ()
                    ) closureOwnerIdentity
    

                let dict, hc_table =
                    if CacheGeneration.isStale cache_gen then
                        let fresh =
                            (System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Reference),
                             HashConsTable(),
                             CacheGeneration.current ())
                        join_point_closure.[closureOwnerIdentity] <- fresh
                        let (d,h,_) = fresh
                        d,h
                    else dict, hc_table
                let call_args, env_global_value =
                    data_to_rdata s hc_table gl_term
                let join_point_key =
                    lock hc_table (fun () -> hc_table.Add(env_global_value, s.env_global_type, fun_ty))
                let _ =
                    // best-effort, stable-ish label to improve join-point diagnostics
                    let name = sprintf "closure<%d>" join_point_key.tag
                    s.join_point_closure_key_names.TryAdd(join_point_key, JpNameIdOps.create name) |> ignore
                let closureGeneration = CacheGeneration.current ()
                // Tags come from each owner's own hash-cons table, so two closures (different bodies, same
                // environment) both get tag 0; the owner's source and backend keep their promises apart.
                // Without them the second closure's producer failed with a binding conflict that also
                // voided the first's result, and codegen found neither body (EJP0035, `native_closure_branch`).
                let closureOwnerText =
                    let ownerRange = range_of_e_or range0 (JpBodyOwnerIdentity.body closureOwnerIdentity)
                    let (a, b) = ownerRange.range
                    FastRuntimeFormat.format "%s:%d:%d-%d:%d@%s" [| box ownerRange.path; box a.line; box a.character; box b.line; box b.character; box (JpBodyOwnerIdentity.backendText closureOwnerIdentity) |]
                let closureMethodKey = sprintf "JPClosure tag=%d source=%s" join_point_key.tag closureOwnerText
                let closureSiteId = CompilerIdentityKernel.WorkSiteIdOps.create closureMethodKey
                let closureBackendId = JpBodyOwnerIdentity.backendId closureOwnerIdentity
                let closureIdentityBinding =
                    CompilerKernelV2.StableBindingId.createSemantic
                        (max 0 join_point_key.tag)
                        "jp-closure-identity"
                        closureMethodKey
                        closureMethodKey
                        "unspecialized"
                        s.backend.node
                let closureComputationIdentity =
                    JpClosureComputation(JpClosureIdentity closureIdentityBinding, closureSiteId)
                let closureInstantiationId =
                    CompilerKernelV2.InstantiationIdOps.create
                        (FastRuntimeFormat.format "generation=%d|tag=%d|hkey=%d|source=%s" [| box closureGeneration; box join_point_key.tag; box join_point_key.hkey; box closureOwnerText |])
                let closureInstantiationText = CompilerKernelV2.InstantiationIdOps.text closureInstantiationId
                let closureMemoCellIdentity =
                    JpClosureMemoCellIdentity(closureBackendId, s.backend, body, join_point_key, closureGeneration)
                let closureMemoWitness = {
                    backendId = closureBackendId
                    backendNode = s.backend
                    body = body
                    environment = join_point_key
                    annotatedFunctionType = fun_ty
                }
                let closureMemoBinding =
                    CompilerKernelV2.StableBindingId.createSemantic
                        0
                        "jp-closure"
                        closureMethodKey
                        closureInstantiationText
                        "closure-computation"
                        "host"
                let closureMemoResultText (result:JpClosureBodyCellPayload) =
                    match result with
                    | JpClosureBodyCellReadyPayload(data, seq) ->
                        let dataText = show_data data
                        let dataRef =
                            CompilerIdentityKernel.ContentDigest.ofText "jp-closure-memo-result" dataText
                            |> CompilerIdentityKernel.ContentDigest.text
                        sprintf "Ready(data_ref=%s|typed_bind_count=%d)" dataRef seq.Length
                    | JpClosureBodyCellCancelledPayload(JpClosurePatternMissStasisCancellation(cancellationRef, repeatCount, _, stableAgeMs, _, _)) ->
                        FastRuntimeFormat.format
                            "Cancelled(ref=%s|repeat=%d|stable_age_ms=%d)"
                            [| box (CompilerIdentityKernel.ContentDigest.text cancellationRef); box repeatCount; box stableAgeMs |]
                    | JpClosureBodyCellFailedPayload failure ->
                        "Failed(exception_type=" + failure.SourceException.GetType().FullName + ")"
                let currentClosureMemoOwnerIdentity =
                    match jpCurrentWorkIdentity () with
                    | Some (JpWaiterWorkIdentity workId) -> JpClosureMemoWorkOwner workId
                    | None -> JpClosureMemoHostThreadOwner System.Threading.Thread.CurrentThread.ManagedThreadId
                let closureOwnerCapabilityRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-closure-owner-capability"
                        (closureInstantiationText + "|owner=" + jpClosureMemoOwnerIdentityText currentClosureMemoOwnerIdentity)
                let closureVerificationRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-closure-body-verification"
                        closureInstantiationText

                let emitClosureMemoProbe probe =
                    let memoEventKind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpComputationMemo
                    let computationKind = jpComputationIdentityKindText closureComputationIdentity
                    let probeText = jpClosureMemoProbeText probe
                    let occurrenceCount, shouldEmit =
                        DiagJson.sparseLogDecision
                            (memoEventKind + "|" + computationKind + "|" + closureMethodKey + "|" + probeText)
                            64L
                    if shouldEmit then
                        let memoHit =
                            match probe with
                            | JpClosureMemoSharedReadyHit
                            | JpClosureMemoSharedWaitHit
                            | JpClosureMemoWaitHit -> true
                            | JpClosureMemoCellCreated
                            | JpClosureMemoReentrantBypass
                            | JpClosureMemoWitnessConflictBypass
                            | JpClosureMemoMissingCell -> false
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":%s,\"computation_kind_du\":%s,\"computation_key\":%s,\"computation_instantiation_ref\":%s,\"join_point_tag\":%d,\"join_point_hkey\":%d,\"memo_probe_du\":%s,\"memo_hit\":%b,\"generation\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"computation_kind_probe_first3_power2_every64\",\"cell_scope_du\":\"GenerationAffineOwnerIndependentPendingAndCompletedClosureCell\",\"authority\":\"typed_computation_identity_plus_recursive_promise_cell\"}" [| box (DiagJson.esc memoEventKind); box (DiagJson.esc computationKind); box (DiagJson.esc closureMethodKey); box (DiagJson.esc closureInstantiationText); box join_point_key.tag; box join_point_key.hkey; box (DiagJson.esc probeText); box memoHit; box closureGeneration; box occurrenceCount |])
    

                let tryReadSharedCompletedClosure () =
                    match jp_closure_completed_cells.TryGetValue closureMemoCellIdentity with
                    | true, entry when jpClosureMemoWitnessEquivalent entry.witness closureMemoWitness ->
                        match CompilerKernelV2.ConfluentWorkCell.tryValue entry.cell with
                        | Some result -> Some result
                        | None ->
                            emitClosureMemoProbe JpClosureMemoWitnessConflictBypass
                            None
                    | true, _ ->
                        emitClosureMemoProbe JpClosureMemoWitnessConflictBypass
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"jp_closure_memo_witness_collision\",\"computation_key\":%s,\"instantiation_ref\":%s,\"generation\":%d,\"authority\":\"full_structural_closure_witness_guard\",\"next\":\"bypass_shared_cell_without_claiming_equivalence\"}" [| box (DiagJson.esc closureMethodKey); box (DiagJson.esc closureInstantiationText); box closureGeneration |])
                        None
                    | _ -> None

                let publishSharedCompletedClosure result =
                    let completedCell =
                        CompilerKernelV2.ConfluentWorkCell.complete
                            closureMemoBinding
                            (int64 (max 0 join_point_key.tag))
                            (closureMemoResultText result)
                            result
                    let candidate : JpClosureMemoCompletedEntry = { witness = closureMemoWitness; cell = completedCell }
                    let mutable witnessCollision = false
                    let merged =
                        jp_closure_completed_cells.AddOrUpdate(
                            closureMemoCellIdentity,
                            candidate,
                            fun _ current ->
                                if jpClosureMemoWitnessEquivalent current.witness closureMemoWitness then
                                    { current with
                                        cell = CompilerKernelV2.ConfluentWorkCell.merge current.cell completedCell }
                                else
                                    witnessCollision <- true
                                    current)
                    if witnessCollision then
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"jp_closure_memo_witness_collision\",\"computation_key\":%s,\"instantiation_ref\":%s,\"generation\":%d,\"authority\":\"full_structural_closure_witness_guard\",\"next\":\"retain_first_witness_and_preserve_owner_local_result\"}" [| box (DiagJson.esc closureMethodKey); box (DiagJson.esc closureInstantiationText); box closureGeneration |])
                    match CompilerKernelV2.ConfluentWorkCell.conflictDigests merged.cell with
                    | Some digests ->
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"jp_closure_memo_conflict\",\"computation_key\":%s,\"instantiation_ref\":%s,\"conflict_digests\":%s,\"generation\":%d,\"authority\":\"confluent_completed_closure_cell\",\"next\":\"preserve_conflict_as_typed_data\"}" [| box (DiagJson.esc closureMethodKey); box (DiagJson.esc closureInstantiationText); box (digests |> Set.toList |> String.concat "," |> DiagJson.esc); box closureGeneration |])
                    | None -> ()

                match fun_ty with
                | YFun(_,_,FT_Pointer) when call_args.Length <> 0 -> raise_type_error s "Function pointers shouldn't have any runtime free variables in their environment."
                | _ -> ()
    

                // MIGRATION: Check loop specialization guard for closures
                let closure_name = sprintf "closure<%d>" join_point_key.tag
                if not (LoopSpecializationGuard.tryRecordSpecialization closure_name) then
                    DiagSidecar.emit (sprintf "[spiral_compiler] EJP0012: closure specialization cap exceeded for '%s'" closure_name)
                    SuspectCache.mark join_point_key (sprintf "%s jp_closure cap name=%s" DiagnosticClassifier.EJP0012 closure_name)
                    ()
    
                // Recursive closure promises use owner-independent pending and completed
                // cells. The owner-local dictionary remains only a projection for later codegen.
                let jp_ivar = Hopac.IVar<JpClosureBodyCellPayload>()
                let portableClosureCell : CompilerKernelV2.PortableOneShotCell<JpClosureBodyCellPayload> =
                    CompilerKernelV2.CompilerRuntimeKernel.wrapOneShot<JpClosureBodyCellPayload>
                        ("jp-closure-memo:" + closureMethodKey)
                        jp_ivar
                let promiseRegistration =
                    JpPromiseProducerAuthority.registrationFor
                        closureGeneration
                        JpClosurePromiseCell
                        (JpPromiseComputationWitness(closureComputationIdentity, closureInstantiationId))
                        jp_ivar
                let pendingClosureCandidate : JpClosureMemoPendingEntry = {
                    witness = closureMemoWitness
                    cell = portableClosureCell
                    ownerIdentity = currentClosureMemoOwnerIdentity
                    ownerCapabilityRef = closureOwnerCapabilityRef
                }
                let tryReadSharedPendingClosure () =
                    match jp_closure_pending_cells.TryGetValue closureMemoCellIdentity with
                    | true, entry when jpClosureMemoWitnessEquivalent entry.witness closureMemoWitness ->
                        if entry.ownerIdentity = currentClosureMemoOwnerIdentity then
                            JpClosurePendingMemoReentrant entry.ownerCapabilityRef
                        else
                            JpClosurePendingMemoWait(entry.cell, entry.ownerCapabilityRef)
                    | true, entry ->
                        JpClosurePendingMemoWitnessConflict entry.ownerCapabilityRef
                    | _ -> JpClosurePendingMemoAbsent
                let tryClaimSharedPendingClosure () =
                    jp_closure_pending_cells.TryAdd(closureMemoCellIdentity, pendingClosureCandidate)
                let retireSharedPendingClosure () =
                    let mutable entry = Unchecked.defaultof<JpClosureMemoPendingEntry>
                    if jp_closure_pending_cells.TryGetValue(closureMemoCellIdentity, &entry)
                       && CompilerKernelV2.PortableOneShotCellOps.resourceId entry.cell
                          = CompilerKernelV2.PortableOneShotCellOps.resourceId portableClosureCell then
                        let mutable removed = Unchecked.defaultof<JpClosureMemoPendingEntry>
                        jp_closure_pending_cells.TryRemove(closureMemoCellIdentity, &removed) |> ignore
                let projectResultToLocalCell result =
                    let localCell = Hopac.IVar<JpClosureBodyCellPayload>()
                    try jp_fill_ivar JpIvarClosureProjectionFill localCell result with _ -> ()
                    dict.TryAdd(join_point_key, localCell) |> ignore

                let projectPendingClosureCell disposition ownerCapabilityRef (cell:CompilerKernelV2.PortableOneShotCell<JpClosureBodyCellPayload>) =
                    let adapterCell =
                        CompilerKernelV2.CompilerRuntimeKernel.projectOneShotToFSharp cell
                    dict.AddOrUpdate(join_point_key, adapterCell, fun _ _ -> adapterCell) |> ignore
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"jp_closure_synchronous_boundary_projected\",\"computation_key\":%s,\"instantiation_ref\":%s,\"disposition_du\":%s,\"owner_capability_ref\":%s,\"authority\":\"pending_cell_projection_without_sync_wait\",\"next\":\"continue_term_evaluation_then_await_operational_graph_quiescence\"}" [| box (DiagJson.esc closureMethodKey); box (DiagJson.esc closureInstantiationText); box (DiagJson.esc (jpClosureSynchronousProjectionDispositionText disposition)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text ownerCapabilityRef)) |])

                match tryReadSharedCompletedClosure (), tryReadSharedPendingClosure (), dict.TryGetValue(join_point_key) with
                | Some completedResult, _, _ ->
                    emitClosureMemoProbe JpClosureMemoSharedReadyHit
                    projectResultToLocalCell completedResult
                | None, JpClosurePendingMemoWait(sharedIvar, ownerCapabilityRef), _ when not (s.jp_closure_stack.Contains join_point_key) ->
                    emitClosureMemoProbe JpClosureMemoSharedWaitHit
                    projectPendingClosureCell JpClosureSharedPendingCellProjected ownerCapabilityRef sharedIvar
                | None, JpClosurePendingMemoReentrant _, _ ->
                    emitClosureMemoProbe JpClosureMemoReentrantBypass
                | None, _, (true, existingIvar) when not (s.jp_closure_stack.Contains join_point_key) ->
                    emitClosureMemoProbe JpClosureMemoWaitHit
                    projectPendingClosureCell
                        JpClosureOwnerLocalPendingCellRetained
                        closureOwnerCapabilityRef
                        (CompilerKernelV2.CompilerRuntimeKernel.wrapOneShot<JpClosureBodyCellPayload>
                            ("jp-closure-owner-local:" + closureMethodKey)
                            existingIvar)
                | None, pendingObservation, _ ->
                    let closureAdmission =
                        match pendingObservation with
                        | JpClosurePendingMemoAbsent when tryClaimSharedPendingClosure () && dict.TryAdd(join_point_key, jp_ivar) ->
                            JpSpecializationAdmitOwnedCell
                        | JpClosurePendingMemoWitnessConflict existingOwnerCapabilityRef ->
                            JpSpecializationRejectWitnessConflict existingOwnerCapabilityRef
                        | JpClosurePendingMemoAbsent
                        | JpClosurePendingMemoReentrant _
                        | JpClosurePendingMemoWait _ ->
                            JpSpecializationAwaitSharedCell
                    match closureAdmission with
                    | JpSpecializationAdmitOwnedCell ->
                        emitClosureMemoProbe JpClosureMemoCellCreated
                        let run () =
                            try
                                try
                                    let s = rename_global_term s
                                    s.jp_closure_stack.Add(join_point_key) |> ignore
                                    let domain_data = ty_to_data s domain
                                    s.env_stack_term.[0] <- domain_data
                                    let seq,ty = term_scope'' s body (Some fun_ty)
                                    let result = JpClosureBodyCellReadyPayload(domain_data, seq)
                                    let ty =
                                        match ty with
                                        | YRecord a ->
                                            a
                                            |> Seq.map (fun (KeyValue ((i, k), v)) ->
                                                let i =
                                                    match range with
                                                    | YRecord a ->
                                                        a |> Map.tryPick (fun (i', k') _ -> if k = k' then Some i' else None)
                                                    | _ -> None
                                                    |> Option.defaultValue i
                                                (i, k), v)
                                            |> Map.ofSeq
                                            |> YRecord
                                        | _ -> ty
                                    let ty_deref = jp_method_deref_rec_placeholder ty
                                    let ty =
                                        if range = YB && (ty_is_jp_method_rec_placeholder ty || ty_is_jp_type_rec_placeholder ty || ty_is_jp_method_rec_placeholder ty_deref || ty_is_jp_type_rec_placeholder ty_deref) then range
                                        elif range <> ty then
                                            let hasJpPlaceholder x = tryDecodeJpRecPlaceholder x |> Option.isSome
                                            if hasJpPlaceholder ty || hasJpPlaceholder ty_deref || hasJpPlaceholder range then range else ty
                                        else ty
                                    if range <> ty then
                                        raise_type_error s <| sprintf "The annotation of the function does not match its body's type.\nGot: %s\nExpected: %s" (show_ty ty) (show_ty range)
                                    jp_fill_ivar JpIvarClosureProducerFill jp_ivar result
                                    publishSharedCompletedClosure result
                                    JpPromiseProducerAuthority.complete
                                        promiseRegistration
                                        (CompilerIdentityKernel.ContentDigest.ofText
                                            "jp-closure-promise-completed"
                                            (closureInstantiationText + "|result=" + closureMemoResultText result))
                                    JpWorkExecutionCompleted
                                with e ->
                                    match jpPromiseProducerBoundaryDispositionForCodegen JpSemanticProducer closureVerificationRef (jpCurrentWorkJobId ()) e with
                                    | JpPromiseProducerPreservePendingWithoutFailureFill boundaryDisposition ->
                                        DiagJson.emit (
                                            FastRuntimeFormat.format
                                                "{\"kind\":\"jp_closure_body_control_deferred_without_failure_fill\",\"computation_key\":%s,\"instantiation_ref\":%s,\"join_point_key\":%s,\"boundary_disposition_du\":%s,\"promise_state_du\":\"Pending\",\"failure_marker_published\":false,\"operational_completion_required\":true,\"authority\":\"typed_pattern_miss_control_preserves_owner_local_closure_promise\",\"next\":\"scheduler_preserves_required_codegen_body_until_material_progress\"}"
                                                [| box (DiagJson.esc closureMethodKey); box (DiagJson.esc closureInstantiationText); box (DiagJson.esc (jpConsedNodeIdentityText join_point_key)); box (DiagJson.esc (jpPortableEffectBoundaryDispositionText boundaryDisposition)) |])
                                        reraise()
                                    | JpPromiseProducerPublishPatternMissCancellation(boundaryDisposition, repeatCount, repeatLimit, stableAgeMs, stableAgeFloorMs, stasisBasis, cancellationRef) ->
                                        let cancellation =
                                            JpClosurePatternMissStasisCancellation(cancellationRef, repeatCount, repeatLimit, stableAgeMs, stableAgeFloorMs, stasisBasis)
                                        JpPromiseProducerAuthority.cancel promiseRegistration cancellationRef
                                        try jp_fill_ivar JpIvarClosureControlCancellationFill jp_ivar (JpClosureBodyCellCancelledPayload cancellation) with _ -> ()
                                        DiagJson.emit (
                                            FastRuntimeFormat.format
                                                "{\"kind\":\"jp_closure_body_pattern_miss_control_cancelled\",\"computation_key\":%s,\"instantiation_ref\":%s,\"join_point_key\":%s,\"boundary_disposition_du\":%s,\"repeat_count\":%d,\"repeat_limit\":%d,\"stable_age_ms\":%d,\"stable_age_floor_ms\":%d,\"stasis_basis_du\":%s,\"cancellation_ref\":%s,\"promise_state_du\":\"Cancelled\",\"failure_marker_published\":false,\"semantic_failure\":false,\"authority\":\"typed_closure_codegen_body_material_revision_stasis_cancellation\",\"next\":\"worker_result_consumes_operational_cancellation\"}"
                                                [| box (DiagJson.esc closureMethodKey); box (DiagJson.esc closureInstantiationText); box (DiagJson.esc (jpConsedNodeIdentityText join_point_key)); box (DiagJson.esc (jpPortableEffectBoundaryDispositionText boundaryDisposition)); box repeatCount; box repeatLimit; box stableAgeMs; box stableAgeFloorMs; box (DiagJson.esc (JpCodegenPatternMissStasisBasisId.text stasisBasis)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text cancellationRef)) |])
                                        JpWorkExecutionCancelled(JpPatternMissReplaySentinelCancellation cancellationRef)
                                    | JpPromiseProducerPublishFailure boundaryDisposition ->
                                        let failure = capture_edi e
                                        let failureRef =
                                            CompilerIdentityKernel.ContentDigest.ofText
                                                "jp-closure-promise-failed"
                                                (closureInstantiationText + "|exception=" + e.GetType().FullName)
                                        JpPromiseProducerAuthority.fail promiseRegistration failureRef
                                        try jp_fill_ivar JpIvarClosureFailureFill jp_ivar (JpClosureBodyCellFailedPayload failure) with _ -> ()
                                        DiagJson.emit (
                                            FastRuntimeFormat.format
                                                "{\"kind\":\"jp_closure_body_failure_fill_published\",\"computation_key\":%s,\"instantiation_ref\":%s,\"failure_ref\":%s,\"exception_type\":%s,\"boundary_disposition_du\":%s,\"cell_payload_du\":\"Failed\",\"authority\":\"owner_local_closure_cell_failed_payload\"}"
                                                [| box (DiagJson.esc closureMethodKey); box (DiagJson.esc closureInstantiationText); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text failureRef)); box (DiagJson.esc (e.GetType().FullName)); box (DiagJson.esc (jpPortableEffectBoundaryDispositionText boundaryDisposition)) |])
                                        reraise()
                            finally
                                retireSharedPendingClosure ()
                                s.jp_closure_stack.Remove(join_point_key) |> ignore
                        let closureWorkDescriptor =
                            jpWorkDescriptorCreate
                                (CacheGeneration.current())
                                closureComputationIdentity
                                closureInstantiationId
                                (JpClosureMemoObservation JpClosureMemoCellCreated)
                                JpSemanticProducer
                                JpMaterializeClosureBody
                                JpRuntimeEffectPure
                                JpSpecializationAdmitOwnedCell
                        let executionContext =
                            jpExecutionContextCreate
                                (jpSpawnContextCreate closureMethodKey)
                                s.recursion
                                s.bigStack
                        jp_orphan_recompute.[box jp_ivar] <- (fun () -> run () |> ignore)
                        if PevalStallProbe.recoveryActive () then
                            // Placeholder recovery (FRONTIER.md fixes 44-45): evaluate the closure body inline, as
                            // single-flight does. A spawned body can pattern-miss on a placeholder and be retired
                            // with its cell unfilled, which codegen then waits on forever.
                            run () |> ignore
                        else
                            startHopacJob (
                                jp_start_named_with_metadata
                                    executionContext
                                    closureMethodKey
                                    (Some promiseRegistration)
                                    (JpWorkComputationMetadata closureWorkDescriptor)
                                    run)
                    | JpSpecializationRejectWitnessConflict conflictRef ->
                        emitClosureMemoProbe JpClosureMemoWitnessConflictBypass
                        let conflictNode =
                            jpSpecializationWorkNodeCreate
                                closureGeneration
                                JpMaterializeClosureBody
                                closureComputationIdentity
                                closureInstantiationId
                                JpRuntimeEffectPure
                                closureAdmission
                        JpSpecializationWorklistAuthority.register conflictNode |> ignore
                        JpSpecializationWorklistAuthority.fail conflictNode conflictRef
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"jp_closure_specialization_witness_rejected\",\"computation_key\":%s,\"instantiation_ref\":%s,\"conflict_ref\":%s,\"local_recompute\":false,\"authority\":\"typed_witness_conflict_disposition\",\"next\":\"surface_conflict_without_silent_owner_local_equivalence\"}" [| box (DiagJson.esc closureMethodKey); box (DiagJson.esc closureInstantiationText); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text conflictRef)) |])
                    | JpSpecializationAwaitSharedCell ->
                        if s.jp_closure_stack.Contains(join_point_key) then
                            emitClosureMemoProbe JpClosureMemoReentrantBypass
                        else
                            match jp_closure_pending_cells.TryGetValue closureMemoCellIdentity with
                            | true, entry ->
                                emitClosureMemoProbe JpClosureMemoSharedWaitHit
                                projectPendingClosureCell JpClosurePostRacePendingCellProjected entry.ownerCapabilityRef entry.cell
                            | _ -> emitClosureMemoProbe JpClosureMemoMissingCell
                    | JpSpecializationReuseRuntimeEffect _
                    | JpSpecializationRecomputeSuspect _
                    | JpSpecializationCapExceeded _ ->
                        invalidOp "closure specialization received a method-only disposition"
                join_point_key, call_args, fun_ty
            push_typedop s (TyJoinPoint(JPClosure(closureOwnerIdentity,join_point_key),call_args)) fun_ty, fun_ty
        and data_to_ty s x =
            let m = System.Collections.Concurrent.ConcurrentDictionary<Data,Ty>(HashIdentity.Reference)
            let visiting = HashSet<Data>(HashIdentity.Reference)
            let stack = System.Collections.Generic.Stack<DataPostorderTraversalFrame>()
            let lookup source =
                match m.TryGetValue source with
                | true, value -> value
                | false, _ -> invalidOp "Data→Ty postorder invariant: child result missing."
            let commit source value =
                visiting.Remove source |> ignore
                m.TryAdd(source, value) |> ignore
            stack.Push(DataPostorderVisit x)
            while stack.Count > 0 do
                match stack.Pop() with
                | DataPostorderVisit source ->
                    match m.TryGetValue source with
                    | true, _ -> ()
                    | false, _ ->
                        if visiting.Add source = false then
                            raise_type_error s "Compiler error: Cyclic compile-time value detected while converting data to a type."
                        match source with
                        | DPair _
                        | DRecord _ ->
                            stack.Push(DataPostorderBuild source)
                            pushDataPostorderChildren stack source
                        | DSymbol value -> commit source (jp_method_deref_rec_placeholder (YSymbol value))
                        | DUnion(_, unionType) -> commit source (YUnion unionType)
                        | DNominal(_, nominalType)
                        | DV(L(_, nominalType)) -> commit source (jp_method_deref_rec_placeholder nominalType)
                        | DLit value -> commit source (lit_to_ty value)
                        | DTLit value -> commit source (YLit value)
                        | DB -> commit source YB
                        | DFunction(body,Some annotation,captured,typeEnv,termSize,typeSize) ->
                            commit source (ty (closure_env s (body,annotation,captured,typeEnv,termSize,typeSize)) annotation)
                        | DExists _ -> commit source YExists
                        | DForall _ -> commit source YForall
                        | DFunction(_,None,_,_,_,_) ->
                            raise_type_error s "Cannot convert a function that is not annotated into a type."
                        | DHashSet _ -> raise_type_error s "Cannot convert a compile time HashSet into a type."
                        | DHashMap _ -> raise_type_error s "Cannot convert a compile time HashMap into a type."
