                    let converted =
                        match source with
                        | DPair(left, right) -> YPair(lookup left, lookup right)
                        | DRecord fields -> YRecord(Map.map (fun _ child -> lookup child) fields)
                        | _ -> invalidOp "Data→Ty postorder build frame reached a leaf."
