            lookup x |> jp_method_deref_rec_placeholder
        and dyn do_lit s x =
            // Dyn conversion used to maintain two nearly identical recursive walkers.
            // Keep one reference-memoized postorder machine instead: literal mode only
            // changes the leaf policy, while nominal/pair traversal remains identical.
            let memo = Dictionary<Data,Data>(HashIdentity.Reference)
            let visiting = HashSet<Data>(HashIdentity.Reference)
            let stack = System.Collections.Generic.Stack<DynDataTraversalFrame>()
            let mutable dirty = false
            let lookup source =
                match memo.TryGetValue source with
                | true, value -> value
                | false, _ -> invalidOp "Dyn postorder invariant: child result missing."
            let commit source value =
                visiting.Remove source |> ignore
