                match source with
                | DPair(left,right) ->
                    // Preserve the historical long-pair workaround: tail/right is transformed first.
                    stack.Push(DynDataVisit left)
                    stack.Push(DynDataVisit right)
                | DNominal(DForall(_,term,_,_,_),_) -> pushNaturalOrder term
                | DNominal(DExists(_,term),_) -> stack.Push(DynDataVisit term)
                | DNominal(DRecord fields,_) ->
                    fields
                    |> Seq.map (fun (KeyValue(_,child)) -> child)
                    |> Seq.toArray
                    |> pushNaturalOrder
