                        match source with
                        | DPair(left,right) -> DPair(lookup left, lookup right)
                        | DNominal(DForall(body,termEnv,tyEnv,termSize,tySize), nominalTy) ->
                            DNominal(DForall(body, HopacExtensions.S.map lookup termEnv, tyEnv, termSize, tySize), nominalTy)
                        | DNominal(DExists(varsType,term), nominalTy) ->
                            DNominal(DExists(varsType, lookup term), nominalTy)
                        | DNominal(DRecord fields, nominalTy) ->
                            DNominal(DRecord(Map.map (fun _ child -> lookup child) fields), nominalTy)
                        | DNominal(DUnion(DPair(DSymbol tag,value),_), nominalTy) ->
