        and term_scope' s cse x = term_scope'' {s with seq=ResizeArray(); cse=cse :: s.cse} x None
        and term_scope s x = term_scope' s (System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural)) x
