            let siteId = CompilerIdentityKernel.WorkSiteIdOps.create site
            let typeShape0 = evalNodeShapeTy x
            match jpRecordCurrentWorkOperation JpActiveTypeOperation siteId typeShape0 (System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box x)) with
            | JpActiveOperationProfiled -> jpProbeCurrentWorkExecutionBudget siteId
            | JpActiveOperationCounted
            | JpActiveOperationUntracked -> ()
