                        else s.env_global_type.Length
                    let stackTypeLen =
                        if obj.ReferenceEquals(s.env_stack_type, null) then 0
                        else s.env_stack_type.Length
                    if i >= 0 && i < globalTypeLen then
                        EvalReplayValueStore.putTypeValue nodeId s.env_global_type.[i]
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_direct_tv_cell_env_snapshot\",\"event\":\"semantic_cell_attach\",\"node_id\":%d,\"index\":%d,\"env\":\"global\",\"global_len\":%d,\"stack_len\":%d,\"site\":%s,\"single_flight\":1,\"next\":\"type_value_materialized\"}" [| box nodeId; box i; box globalTypeLen; box stackTypeLen; box (DiagJson.esc site) |])
                    elif i >= globalTypeLen && (i - globalTypeLen) >= 0 && (i - globalTypeLen) < stackTypeLen then
