                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_direct_tv_cell_env_snapshot\",\"event\":\"semantic_cell_attach\",\"node_id\":%d,\"index\":%d,\"env\":\"stack\",\"global_len\":%d,\"stack_len\":%d,\"site\":%s,\"single_flight\":1,\"next\":\"type_value_materialized\"}" [| box nodeId; box i; box globalTypeLen; box stackTypeLen; box (DiagJson.esc site) |])
                    elif i >= globalTypeLen && stackTypeLen = 0 then
