                        // Treat this as a free type metavariable, matching the existing
                        // MIGRATION TFun.arg policy, rather than pinning a false env-missing
                        // terminal at top-level replay roots such as spiral.spi:2669.
                        EvalReplayValueStore.putTypeValue nodeId (YMetavar i)
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_direct_tv_cell_free_metavar_snapshot\",\"event\":\"semantic_cell_attach\",\"node_id\":%d,\"index\":%d,\"global_len\":%d,\"stack_len\":%d,\"site\":%s,\"policy\":\"empty_type_env_tv_is_free_metavar\",\"single_flight\":1,\"next\":\"type_value_materialized_from_free_metavar\"}" [| box nodeId; box i; box globalTypeLen; box stackTypeLen; box (DiagJson.esc site) |])
                    else
