                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_direct_tv_cell_env_snapshot_miss\",\"event\":\"semantic_cell_attach\",\"node_id\":%d,\"index\":%d,\"global_len\":%d,\"stack_len\":%d,\"site\":%s,\"single_flight\":1,\"next\":\"explicit_eval_worklist_type_variable_env_required\"}" [| box nodeId; box i; box globalTypeLen; box stackTypeLen; box (DiagJson.esc site) |])
                | _ -> ()
                evalCell EvalWorklist.EvalTy (CompilerIdentityKernel.WorkShapeIdOps.create typeShape0) nodeId (CompilerIdentityKernel.WorkSiteIdOps.create site) s
            let snapshotTypeVariableChildFromEnv (parentNodeId: int) (childNodeId: int) (role: string) (child: TPrepass) =
                match child with
                | TV i ->
                    let globalTypeLen =
                        if obj.ReferenceEquals(s.env_global_type, null) then 0
                        else s.env_global_type.Length
                    let stackTypeLen =
                        if obj.ReferenceEquals(s.env_stack_type, null) then 0
                        else s.env_stack_type.Length
                    match EvalReplayValueStore.putTypeVarEnvSnapshot childNodeId i s.env_global_type s.env_stack_type with
                    | Some (envName, _, _) ->
