                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_fun_tv_child_free_metavar_snapshot\",\"event\":\"type_fun_child_register\",\"parent_node_id\":%d,\"child_node_id\":%d,\"role\":%s,\"index\":%d,\"global_len\":%d,\"stack_len\":%d,\"site\":%s,\"policy\":\"empty_type_env_tv_is_free_metavar\",\"single_flight\":1,\"next\":\"type_value_materialized_from_free_metavar\"}" [| box parentNodeId; box childNodeId; box (DiagJson.esc role); box i; box globalTypeLen; box stackTypeLen; box (DiagJson.esc site) |])
                        else
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_fun_tv_child_env_snapshot_miss\",\"event\":\"type_fun_child_register\",\"parent_node_id\":%d,\"child_node_id\":%d,\"role\":%s,\"index\":%d,\"global_len\":%d,\"stack_len\":%d,\"site\":%s,\"single_flight\":1,\"next\":\"explicit_eval_worklist_type_variable_env_required\"}" [| box parentNodeId; box childNodeId; box (DiagJson.esc role); box i; box globalTypeLen; box stackTypeLen; box (DiagJson.esc site) |])
