                    EvalReplayValueStore.putType nodeId (fun () ->
                        let aTy = childType TPrepassReplayApplyFunction a
                        let bTy = childType TPrepassReplayApplyArgument b
                        match aTy with
                        | YRecord fields ->
                            match bTy with
                            | YSymbol key ->
