                            // variable witness.  Use a YMetavar placeholder, not a concrete Ty,
                            // so downstream annotations can become structured YFun instead of
                            // collapsing to JPMethodUnknownRet(par).
                            EvalReplayValueStore.putTypeValue argNodeId (YMetavar i)
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_tfun_arg_tv_free_metavar_snapshot\",\"event\":\"type_fun_child_register\",\"parent_node_id\":%d,\"child_node_id\":%d,\"role\":\"tfun_arg_free_metavar\",\"index\":%d,\"global_len\":%d,\"stack_len\":%d,\"site\":%s,\"single_flight\":1,\"next\":\"type_value_materialized_from_free_metavar\"}" [| box nodeId; box argNodeId; box i; box globalTypeLen; box stackTypeLen; box (DiagJson.esc site) |])
                    | _ -> ()
                    match b with
                    | TV i ->
                        let globalTypeLen =
                            if obj.ReferenceEquals(s.env_global_type, null) then 0
                            else s.env_global_type.Length
                        let stackTypeLen =
                            if obj.ReferenceEquals(s.env_stack_type, null) then 0
                            else s.env_stack_type.Length
                        if i = globalTypeLen && stackTypeLen = 0 then
                            EvalReplayValueStore.putType bodyNodeId (fun () -> childType (TPrepassReplayFunctionBodyImmediateBinder TPrepassReplayGeneral) a)
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_tfun_body_tv_binder_snapshot\",\"event\":\"type_fun_child_register\",\"parent_node_id\":%d,\"child_node_id\":%d,\"role\":\"tfun_body_immediate_binder\",\"index\":%d,\"global_len\":%d,\"stack_len\":%d,\"arg_node_id\":%d,\"site\":%s,\"single_flight\":1,\"next\":\"type_value_materialized_from_arg_binder\"}" [| box nodeId; box bodyNodeId; box i; box globalTypeLen; box stackTypeLen; box argNodeId; box (DiagJson.esc site) |])
                    | _ -> ()
                    EvalReplayValueStore.putTypeFunSpine nodeId {
                        argNodeId = argNodeId
                        argShape = evalNodeWorkShapeIdTy a
                        bodyNodeId = bodyNodeId
                        bodyShape = evalNodeWorkShapeIdTy b
                        funType = t
                    }
                    EvalReplayValueStore.putType nodeId (fun () -> YFun(childType (TPrepassReplayFunctionArgument TPrepassReplayGeneral) a, childType (TPrepassReplayFunctionBody TPrepassReplayGeneral) b,t))
                | TModule a ->
                    EvalReplayValueStore.putType nodeId (fun () ->
                        YRecord(
                            a
                            |> Seq.mapi (fun i (KeyValue (k, v)) ->
                                let name = TypeNameIdOps.text k
                                (i, name), childType (TPrepassReplayModuleField name) v)
                            |> Map.ofSeq))
                | TRecord(_,a) ->
                    EvalReplayValueStore.putType nodeId (fun () ->
                        YRecord(
                            Map.map (fun (fieldOrder, fieldName) v ->
                                childType (TPrepassReplayRecordField(fieldOrder, fieldName)) v) a))
                | TArray a -> EvalReplayValueStore.putType nodeId (fun () -> YArray(childType TPrepassReplayArrayItem a))
                | TLayout(a,b) -> EvalReplayValueStore.putType nodeId (fun () -> YLayout(childType TPrepassReplayLayoutInner a,b))
                // MIGRATION: conservative replay thunks for complex type forms that the
                // runtime frontier now exposes after active kind-local fuse reset.
                // These stay fail-closed through tryType: if the normal evaluator still
                // trips a JP/fuse cycle, the replay driver keeps the cell partial instead
                // of manufacturing a value.
                | TMacro(r,items) ->
                    // MIGRATION: replay TMacro without re-entering ty_core_impl on the same root.
                    // MIGRATION ran for minutes repeating ty_shape_dispatch_dispatched:TMacro at base.spi:67:
                    // the old thunk was `ty s expr`, so tryType re-entered the same fused type node and
                    // stayed semantic_step_partial forever. Build the macro from already-registered child
                    // type values instead; if a child is still unavailable, tryType remains fail-closed.
                    let macro_s = add_trace s r
                    let macroChildType (role: TPrepassReplayChildRole) child =
                        let childId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box child)
                        registerReplayTy childId child
                        match EvalReplayValueStore.tryType childId with
                        | Some value -> value
                        | None -> failwith ("tmacro_child_missing:" + tPrepassReplayChildRoleText role + ":" + evalNodeShapeTy child)
                    EvalReplayValueStore.putType nodeId (fun () ->
                        YMacro(
                            items
                            |> List.mapi (fun i -> function
                                | TMText text -> PartEvalMacro.Text text
                                | TMType child -> PartEvalMacro.Type(macroChildType (TPrepassReplayMacroTypeItem i) child)
                                | TMLitType child -> PartEvalMacro.TypeLit(macroChildType (TPrepassReplayMacroLiteralTypeItem i) child |> assert_ty_lit macro_s))))
                | TTerm(_,termExpr) ->
                    // MIGRATION: do not make TTerm a self-recursive type thunk.
                    // Register its embedded term as an explicit child and convert
                    // only after term_replay_driver has materialized the term value.
                    let termNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box termExpr)
                    let freshTTermEnv () =
                        { s with seq = ResizeArray(); cse = System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural) :: s.cse }
                    EvalReplayValueStore.putTerm termNodeId (fun () -> term (freshTTermEnv()) termExpr)
                    EvalReplayValueStore.putTypeTermSpine nodeId {
                        termNodeId = termNodeId
                        termShape = evalNodeWorkShapeIdTerm termExpr
                    }
                    EvalReplayValueStore.putType nodeId (fun () ->
                        match EvalReplayValueStore.tryTerm termNodeId with
                        | Some termValue -> data_to_ty (freshTTermEnv()) termValue
                        | None -> failwith ("tterm_term_value_missing:" + evalNodeShapeTerm termExpr))
                | TJoinPoint'(r,scope,body) ->
                    // MIGRATION: replay the type join-point body, not the join-point
                    // wrapper itself.  Historical runtime reached a TJoinPoint' terminal at
                    // core/base.spi:16 because the old thunk re-entered ty s expr and
                    // rebuilt the same JP wait/fuse frontier.  This mirrors the real
                    // evaluator's scoped environment but skips the JP cache wrapper;
                    // failures still flow through tryTypeDetailed fail-closed.
                    let bodyNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box body)
                    let env_global_type = scope.ty.free_vars |> HopacExtensions.S.map (fun i -> vt s i)
                    let env_global_term = scope.term.free_vars |> HopacExtensions.S.map (fun i -> v s i)
                    let s2 : LangEnv =
                        { s with
                            trace = r :: s.trace
                            seq = ResizeArray()
                            cse = [System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural)]
                            unions = Map.empty
                            i = ref 0
                            env_global_type = env_global_type
                            env_global_term = env_global_term
                            env_stack_type = Array.zeroCreate<_> scope.ty.stack_size
                            env_stack_term = Array.zeroCreate<_> scope.term.stack_size }
                    EvalReplayValueStore.putType bodyNodeId (fun () -> ty (rename_global_term s2) body)
                    EvalReplayValueStore.putTypeJoinPointSpine nodeId {
                        bodyNodeId = bodyNodeId
                        bodyShape = evalNodeWorkShapeIdTy body
                    }
                    EvalReplayValueStore.putType nodeId (fun () ->
                        match EvalReplayValueStore.tryType bodyNodeId with
                        | Some bodyTy -> bodyTy
                        | None -> failwith ("tjoinpoint_body_type_missing:" + evalNodeShapeTy body))
                | TTypecase _ | TUnion _ ->
                    EvalReplayValueStore.putType nodeId (fun () -> ty s expr)
                | _ -> ()
            let returnReplayTypeIfComplete (event: string) (nodeIdReturn: int) (frameOpt: EvalWorklist.Frame option) =
                // MIGRATION: runBounded can return the pre-replay continuation_envelope even though
                // the synchronous replay driver committed semantic_root_complete before control
                // returns to the caller.  Trust the canonical EvalWorklist witness as well as the
                // stale local frame, otherwise the catch path burns retry budget on a completed TFun.
                let complete =
                    match frameOpt with
                    | Some frame when EvalWorklist.frameReplayCompleteKindId EvalWorklist.EvalTy frame -> true
                    | Some _ -> EvalWorklist.hasReplayCompleteKind EvalWorklist.EvalTy
                    | None -> EvalWorklist.hasReplayCompleteKind EvalWorklist.EvalTy
                if complete then
                    match EvalReplayValueStore.tryType nodeIdReturn with
                    | Some value ->
                        // MIGRATION: an already stored direct replay value is material only once.
                        // Re-observation returns the value but cannot renew the watchdog forever.
                        let directReplayAuthorityKey =
                            sprintf "direct_ty_replay_return|node=%d|shape=%s" nodeIdReturn (evalNodeShapeTy x)
                        let directReplayRepeat = jp_note_source_value_store directReplayAuthorityKey
                        if directReplayRepeat = 1 then
                            jp_progress_clock_mark peval_sw.ElapsedMilliseconds
                        if jp_should_emit_source_value_store directReplayRepeat then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_root_complete_replay_progress_marked\",\"event\":%s,\"scope\":\"direct_ty_replay_return\",\"status\":\"semantic_root_complete\",\"kind2\":\"ty\",\"shape\":%s,\"repeat_count\":%d,\"watchdog_progress_authorized\":%b,\"single_flight\":1,\"next\":%s}" [| box (DiagJson.esc event); box (DiagJson.esc (evalNodeShapeTy x)); box directReplayRepeat; box (directReplayRepeat = 1); box (DiagJson.esc (if directReplayRepeat = 1 then "watchdog_progress_refreshed_once" else "return_cached_value_without_watchdog_refresh")) |])
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_direct_cycle_replay_return\",\"event\":%s,\"status\":\"semantic_root_complete\",\"shape\":%s,\"single_flight\":1,\"next\":\"return_ty_value\"}"
                                (DiagJson.esc event) (DiagJson.esc (evalNodeShapeTy x)))
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_fuse_clear_after_replay_return\",\"event\":%s,\"status\":\"semantic_root_complete\",\"shape\":%s,\"single_flight\":1,\"next\":\"return_ty_value\"}"
                                (DiagJson.esc event) (DiagJson.esc (evalNodeShapeTy x)))
                        TermCycleFuse.reset ()
                        raise (EvalReplayTyReturn value)
                    | None -> ()
            if TermCycleFuse.isTripped() then
                let fuseVisitKind, _, _, _, _, _, _ = TermCycleFuse.describe()
                let activeFuseDomain = evalFuseDomainOfVisitKind fuseVisitKind
                let activeFuseKind = evalFuseDomainText activeFuseDomain
                if activeFuseDomain <> EvalFuseTyDomain then
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_kind_local_active_reset\",\"event\":\"ty_entry_global_fuse\",\"active_kind\":%s,\"requested_kind\":\"ty\",\"single_flight\":1,\"next\":\"continue_ty_eval\"}"
                            (DiagJson.esc activeFuseKind))
                    EvalWorklist.parkActiveAndSelectKind EvalWorklist.EvalTy |> ignore
                    TermCycleFuse.reset()
                else
                    match EvalReplayValueStore.tryTypeSourceValue typeSourceKey0 with
                    | Some value ->
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_type_source_value_replay_return\",\"event\":\"ty_entry_global_fuse\",\"status\":\"semantic_root_complete\",\"shape\":%s,\"source_key\":%s,\"single_flight\":1,\"next\":\"return_ty_value\"}"
                                (DiagJson.esc typeShape0) (DiagJson.esc (EvalReplayValueStore.semanticSourceKeyText typeSourceKey0)))
                        TermCycleFuse.reset ()
                        raise (EvalReplayTyReturn value)
                    | None ->
                        let nodeId0 = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box x)
                        registerReplayTy nodeId0 x
                        EvalWorklist.ensureCapturedForKindId EvalWorklist.ReplayFrontierTy (CompilerKernelV2.OperationalReasonIdOps.create "ty_entry_global_fuse") |> ignore
                        EvalWorklist.attachSemanticCell EvalWorklist.ReplayTickEventTyEntry (semanticCellForTy nodeId0)
                        let frameOpt = EvalWorklist.ensureCapturedAndRunId (CompilerKernelV2.OperationalReasonIdOps.create "ty_entry_global_fuse") EvalWorklist.ReplayTickEventTyEntry 32
                        let globalReplayComplete =
                            match frameOpt with
                            | Some frame when EvalWorklist.frameReplayCompleteKindId EvalWorklist.EvalTy frame -> true
                            | Some _ -> EvalWorklist.hasReplayCompleteKind EvalWorklist.EvalTy
                            | None -> EvalWorklist.hasReplayCompleteKind EvalWorklist.EvalTy
                        if globalReplayComplete then
                            let shape0 = typeShape0
                            let _, k0, s0, d0, g0, re0, max0 = TermCycleFuse.describe()
                            let replayReturnMsg =
                                FastRuntimeFormat.format "%s: global type replay return suppressed after pinned terminal first_key=%s first_site=%s first_depth=%d gen=%d re=%d/%d" [| box DiagnosticClassifier.EJP0011; box k0; box s0; box d0; box g0; box re0; box max0 |]
                            match EvalWorklist.trySuppressGlobalFuseReplayReturnForPinnedTerminal "ty_entry_global_fuse" EvalWorklist.EvalTy (CompilerIdentityKernel.WorkShapeIdOps.create shape0) replayReturnMsg with
                            | Some msg -> raise_type_error s msg
                            | None ->
                                match EvalReplayValueStore.tryType nodeId0 with
                                | Some value ->
                                    EvalReplayValueStore.putTypeSourceValue typeSourceKey0 value
                                    let semanticAuthorityKey =
                                        EvalReplayValueStore.semanticAuthorityKey typeSourceKey0
                                    let sourceStoreRepeat =
                                        jp_note_source_value_store semanticAuthorityKey
                                    if jp_should_emit_source_value_store sourceStoreRepeat then
                                        DiagJson.emit (
                                            sprintf "{\"kind\":\"eval_worklist_root_complete_replay_progress_marked\",\"event\":\"ty_entry_global_fuse\",\"scope\":\"global_fuse_ty_return\",\"status\":\"semantic_root_complete\",\"kind2\":\"ty\",\"shape\":%s,\"repeat_count\":%d,\"source_value_sampled\":1,\"single_flight\":1,\"next\":\"watchdog_progress_refreshed\"}"
                                                (DiagJson.esc shape0) sourceStoreRepeat)
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_source_value_stored\",\"event\":\"ty_entry_global_fuse\",\"status\":\"semantic_root_complete\",\"shape\":%s,\"source_key\":%s,\"policy\":\"global_fuse_replay_return_store\",\"repeat_count\":%d,\"source_value_sampled\":1,\"single_flight\":1,\"next\":\"return_ty_value\"}" [| box (DiagJson.esc shape0); box (DiagJson.esc (EvalReplayValueStore.semanticSourceKeyText typeSourceKey0)); box sourceStoreRepeat |])
                                    if sourceStoreRepeat = 1 then
                                        let semanticAuthorityAdmission =
                                            DiagJson.noteTerminalSemanticAuthorityDeltaForCanonicalRoot 1
                                        let semanticFactAdmitted =
                                            DiagJson.noteSemanticFactExactOnce semanticAuthorityKey 1L 1L
                                        if semanticFactAdmitted then
                                            DiagJson.emit (
                                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_semantic_fact_exact_once\",\"fact_kind_du\":\"TypeGlobalFuseValue\",\"node_id\":%d,\"shape\":%s,\"source_key\":%s,\"semantic_authority_key\":%s,\"exact_once_ref\":%u,\"single_flight\":1,\"authority\":\"canonical_source_cell_identity_without_trace_or_runtime_node\"}" [| box nodeId0; box (DiagJson.esc shape0); box (DiagJson.esc (EvalReplayValueStore.semanticSourceKeyText typeSourceKey0)); box (DiagJson.esc semanticAuthorityKey); box (DiagJson.semanticFactStableRef "eval-semantic-fact" semanticAuthorityKey) |])
                                            match semanticAuthorityAdmission with
                                            | DiagJson.TerminalSemanticAuthorityAdmitted ->
                                                jp_progress_clock_mark peval_sw.ElapsedMilliseconds
                                            | DiagJson.TerminalSemanticPostRootCacheEnrichment -> ()
                                    else
                                        DiagJson.noteOwnerDebtLiveWorkTieBreakerProceduralDelta 1
                                    if sourceStoreRepeat <= 4 || sourceStoreRepeat % 64 = 0 then
                                        DiagJson.emit (
                                            sprintf "{\"kind\":\"eval_worklist_global_fuse_replay_return\",\"event\":\"ty_entry_global_fuse\",\"status\":\"semantic_root_complete\",\"shape\":%s,\"repeat_count\":%d,\"jsonl_recycle_du\":\"emit_first_then_256_milestones\",\"single_flight\":1,\"next\":\"return_ty_value\"}"
                                                (DiagJson.esc shape0) sourceStoreRepeat)
                                    DiagJson.emit (
                                        sprintf "{\"kind\":\"eval_worklist_fuse_clear_after_replay_return\",\"event\":\"ty_entry_global_fuse\",\"status\":\"semantic_root_complete\",\"shape\":%s,\"single_flight\":1,\"next\":\"return_ty_value\"}"
                                            (DiagJson.esc shape0))
                                    TermCycleFuse.reset ()
                                    raise (EvalReplayTyReturn value)
                                | None ->
                                    raise_type_error s (FastRuntimeFormat.format "%s: global term-cycle fuse completed but replay type value was missing first_key=%s first_site=%s first_depth=%d gen=%d re=%d/%d" [| box DiagnosticClassifier.EJP0011; box k0; box s0; box d0; box g0; box re0; box max0 |])
                        else
                            if EvalWorklist.hasReplayCompleteOtherKind EvalWorklist.EvalTy then
                                DiagJson.emit "{\"kind\":\"eval_worklist_kind_local_fuse_reset\",\"event\":\"ty_entry_global_fuse\",\"completed_kind\":\"other\",\"requested_kind\":\"ty\",\"single_flight\":1,\"next\":\"continue_ty_eval\"}"
                                EvalWorklist.parkActiveAndSelectKind EvalWorklist.EvalTy |> ignore
                                TermCycleFuse.reset()
                            else
                                let _, k0, s0, d0, g0, re0, max0 = TermCycleFuse.describe()
                                let tyLiveReplayPayload =
                                    EvalWorklist.pendingCount() > 0
                                    && (EvalWorklist.replayQueueDepth() > 0
                                        || EvalWorklist.replayDriverActiveDepthValue() > 0
                                        || EvalWorklist.hasProgressYield()
                                        || EvalReplayValueStore.hasDeferredReplayCell()
                                        || EvalWorklist.semanticPayloadIsCell()
                                        || EvalWorklist.semanticPayloadHasFact EvalWorklist.FrontierSemanticPayloadContinuation)
                                let orphanTyGlobalFuseWithLiveReplay =
                                    System.String.IsNullOrWhiteSpace k0
                                    && System.String.IsNullOrWhiteSpace s0
                                    && d0 = 0
                                    && tyLiveReplayPayload
                                let keyedTyParentContinuationFuseWithRunnableReplay =
                                    (not (System.String.IsNullOrWhiteSpace k0))
                                    && (not (System.String.IsNullOrWhiteSpace s0))
                                    && tyLiveReplayPayload
                                if orphanTyGlobalFuseWithLiveReplay then
                                    let orphanKey = FastRuntimeFormat.format "ty|%s|%s|cursor=%d|pending=%d|orphan_global_fuse" [| box typeShape0; box site; box 0; box (EvalWorklist.pendingCount()) |]
                                    let orphanRepeat = jp_note_global_fuse_partial_current orphanKey
                                    let orphanCap = 96
                                    let orphanDecision =
                                        if orphanRepeat > orphanCap then
                                            EvalWorklist.OrphanGlobalFuseBlocked(orphanRepeat, orphanCap)
                                        else
                                            EvalWorklist.OrphanGlobalFuseDeferred(orphanRepeat, orphanCap)
                                    let orphanStatus = EvalWorklist.globalFuseReplayDecisionStatusText orphanDecision
                                    let orphanRepeat = EvalWorklist.globalFuseReplayDecisionRepeat orphanDecision
                                    let orphanCap = EvalWorklist.globalFuseReplayDecisionCap orphanDecision
                                    match orphanDecision with
                                    | EvalWorklist.OrphanGlobalFuseBlocked _ ->
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_ty_orphan_global_fuse_live_replay_repeat_blocked\",\"event\":\"ty_entry_global_fuse\",\"status\":%s,\"shape\":%s,\"site\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"payload_status\":%s,\"repeat\":%d,\"cap\":%d,%s,\"single_flight\":1,\"next\":\"typed_terminal_after_bounded_ty_orphan_global_fuse_replay\"}" [| box (DiagJson.esc orphanStatus); box (DiagJson.esc typeShape0); box (DiagJson.esc site); box (EvalWorklist.pendingCount()); box (EvalWorklist.replayQueueDepth()); box (EvalWorklist.replayDriverActiveDepthValue()); box (DiagJson.esc (EvalWorklist.semanticPayloadStatus())); box orphanRepeat; box orphanCap; box (EvalWorklist.globalFuseTraceJson()) |])
                                        let msg = FastRuntimeFormat.format "%s: global term-cycle fuse already tripped first_key=%s first_site=%s first_depth=%d gen=%d re=%d/%d; aborting ty worker before StackOverflow" [| box DiagnosticClassifier.EJP0011; box k0; box s0; box d0; box g0; box re0; box max0 |]
                                        let msg = EvalWorklist.retargetGlobalFuseAbortMessage "ty_entry_global_fuse" EvalWorklist.EvalTy msg
                                        raise_type_error s msg
                                    | EvalWorklist.OrphanGlobalFuseDeferred _ ->
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_ty_orphan_global_fuse_live_replay_deferred\",\"event\":\"ty_entry_global_fuse\",\"status\":%s,\"shape\":%s,\"site\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"payload_status\":%s,\"repeat\":%d,\"cap\":%d,%s%s,\"policy\":\"orphan_ty_global_fuse_live_replay_has_native_callback_closure_before_fallthrough\",\"single_flight\":1,\"next\":\"native_inline_ty_global_fuse_orphan_callback\"}" [| box (DiagJson.esc orphanStatus); box (DiagJson.esc typeShape0); box (DiagJson.esc site); box (EvalWorklist.pendingCount()); box (EvalWorklist.replayQueueDepth()); box (EvalWorklist.replayDriverActiveDepthValue()); box (DiagJson.esc (EvalWorklist.semanticPayloadStatus())); box orphanRepeat; box orphanCap; box (EvalWorklist.globalFuseTraceJson()); box (EvalWorklist.pendingGraphProofTupleJsonFields (EvalWorklist.proofTupleForTyGlobalFuseParentContinuation (FastRuntimeFormat.format "ty_orphan_global_fuse_live_replay_defer|%s|%s|repeat:%d/%d" [| box typeShape0; box site; box orphanRepeat; box orphanCap |]))) |])
                                        EvalWorklist.parkActiveAndSelectKindKeepingReplay "ty_entry_global_fuse" EvalWorklist.EvalTy |> ignore
                                        EvalWorklist.maybeWakeReplayAfterGlobalFuseDeferral EvalWorklist.ReplayTickEventTyEntryGlobalFuse EvalWorklist.ReplayTickReasonTyGlobalFuseDeferredLiveReplay
                                        TermCycleFuse.reset()
                                    | _ -> ()
                                elif keyedTyParentContinuationFuseWithRunnableReplay then
                                    let parentFuseShape = typeShape0
                                    let parentFuseActiveDepth = EvalWorklist.replayDriverActiveDepthValue()
                                    let parentFuseHighPressure =
                                        parentFuseActiveDepth >= 16
                                        || (BigStack.isActive s.bigStack
                                            && parentFuseActiveDepth >= 1
                                            && EvalWorklist.replayQueueDepth() > 0
                                            && EvalWorklist.pendingCount() > 0)
                                    let parentFuseRepeatKey =
                                        // MIGRATION: mirror MIGRATION's term-side high-pressure key for ty.
                                        // Runtime evidence showed 59 ty global-fuse blocked/deferred events, mostly
                                        // around base/backend continuations, while first_key churn kept typed
                                        // obligations alive after the bounded terminal was already meaningful.
                                        // In the high-pressure band, key by current type shape+site and use cap=2.
                                        if parentFuseHighPressure then
                                            sprintf "ty|%s|%s|active_depth_parent_continuation_global_fuse_site_pressure"
                                                parentFuseShape site
                                        else
                                            FastRuntimeFormat.format "ty|%s|%s|%s|parent_continuation_global_fuse_site_pressure" [| box k0; box s0; box site |]
                                    let parentFuseRepeat = jp_note_global_fuse_partial_current parentFuseRepeatKey
                                    let parentFuseCap =
                                        if parentFuseHighPressure then 2
                                        elif EvalWorklist.replayQueueDepth() > 0 && EvalWorklist.pendingCount() > 0 then 16
                                        else 64
                                    let parentFuseCapExhausted = parentFuseRepeat > parentFuseCap
                                    let parentFuseRunnableReplayStillLive =
                                        parentFuseCapExhausted
                                        && EvalWorklist.pendingCount() > 0
                                        && (EvalWorklist.replayQueueDepth() > 0 || EvalWorklist.replayDriverActiveDepthValue() > 0)
                                        && ((not (EvalWorklist.hasReplayComplete())) || EvalWorklist.hasReplayCompleteWriteWitness())
                                    let parentFuseHighActiveReplayStarved =
                                        parentFuseRunnableReplayStillLive
                                        && parentFuseRepeat > (parentFuseCap * 8)
                                        && EvalWorklist.replayDriverActiveDepthValue() >= 16
                                    let parentFuseLowActiveReplayStarved =
                                        parentFuseRunnableReplayStillLive
                                        && parentFuseRepeat > (parentFuseCap * 4)
                                        && EvalWorklist.replayQueueDepth() <= 1
                                        && EvalWorklist.replayDriverActiveDepthValue() <= 4
                                    let parentFuseMidActiveNoQueueReplayStarved =
                                        parentFuseRunnableReplayStillLive
                                        && parentFuseRepeat > (parentFuseCap * 8)
                                        && EvalWorklist.replayQueueDepth() = 0
                                        && EvalWorklist.replayDriverActiveDepthValue() >= 5
                                        && EvalWorklist.replayDriverActiveDepthValue() <= 8
                                    let parentFuseMidActiveQueuedReplayStarved =
                                        parentFuseRunnableReplayStillLive
                                        && parentFuseRepeat > (parentFuseCap * 4)
                                        && EvalWorklist.replayQueueDepth() <= 2
                                        && EvalWorklist.replayDriverActiveDepthValue() >= 5
                                        && EvalWorklist.replayDriverActiveDepthValue() <= 8
                                    let parentFuseLowCapMidActiveQueuedReplayPlateau =
                                        parentFuseRunnableReplayStillLive
                                        && parentFuseCap <= 2
                                        && parentFuseRepeat >= (parentFuseCap + 1)
                                        && EvalWorklist.replayQueueDepth() <= 2
                                        && EvalWorklist.replayDriverActiveDepthValue() >= 5
                                        && EvalWorklist.replayDriverActiveDepthValue() <= 8
                                    let parentFuseQueuedPlateauReplayStarved =
                                        parentFuseRunnableReplayStillLive
                                        && parentFuseRepeat > (parentFuseCap * 8)
                                        && EvalWorklist.replayQueueDepth() <= 2
                                        && EvalWorklist.replayDriverActiveDepthValue() >= 9
                                        && EvalWorklist.replayDriverActiveDepthValue() <= 15
                                    let parentFuseLowCapHighActiveQueuedReplayPlateau =
                                        parentFuseRunnableReplayStillLive
                                        && parentFuseCap <= 2
                                        && parentFuseRepeat >= (parentFuseCap + 1)
                                        && EvalWorklist.replayQueueDepth() <= 2
                                        && EvalWorklist.replayDriverActiveDepthValue() >= 16
                                    let parentFuseMidActiveQueuedSlowRepeatPlateau =
                                        parentFuseRunnableReplayStillLive
                                        && parentFuseCap >= 16
                                        && parentFuseRepeat >= 4
                                        && EvalWorklist.replayQueueDepth() <= 1
                                        && EvalWorklist.replayDriverActiveDepthValue() >= 5
                                        && EvalWorklist.replayDriverActiveDepthValue() <= 8
                                    let parentFuseRunnableReplayStarved =
                                        parentFuseHighActiveReplayStarved || parentFuseLowActiveReplayStarved || parentFuseMidActiveNoQueueReplayStarved || parentFuseMidActiveQueuedReplayStarved || parentFuseLowCapMidActiveQueuedReplayPlateau || parentFuseQueuedPlateauReplayStarved || parentFuseLowCapHighActiveQueuedReplayPlateau || parentFuseMidActiveQueuedSlowRepeatPlateau
                                    let parentFuseStarvationTerminalDecision =
                                        EvalWorklist.parentFuseStarvationTerminalDecisionFor
                                            parentFuseRunnableReplayStarved
                                            (EvalWorklist.pendingCount())
                                            (EvalWorklist.replayQueueDepth())
                                            (EvalWorklist.replayDriverActiveDepthValue())
                                            (EvalWorklist.hasProgressYield())
                                            (EvalWorklist.hasFreshReplayRootWitness())
                                            (DiagJson.terminalSemanticAuthorityActiveNow())
