                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_ty_reentry_prefetch_replay_drained\",\"event\":\"ty_reentry\",\"key\":%s,\"site\":%s,\"depth\":%d,\"re\":%d,\"max_re\":%d,\"outcome_du\":%s,\"status\":%s,\"cursor\":%d,\"replayCompleteNow\":%b,\"single_flight\":1,\"next\":\"return_or_continue_type_replay\"}" [| box (DiagJson.esc nodeKey); box (DiagJson.esc site); box depth; box reKey; box max_reentry_key; box (DiagJson.esc (EvalWorklist.sidecarPrefetchOutcomeText preflightOutcome)); box (DiagJson.esc (EvalWorklist.semanticStatusToString preflightStatusId)); box preflightCursor; box preflightComplete |])
                            returnReplayTypeIfComplete "sidecar_ty_reentry_prefetch" nodeId frameOpt
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_sidecar_prefetch\",\"event\":\"ty_reentry\",\"key\":%s,\"site\":%s,\"depth\":%d,\"re\":%d,\"max_re\":%d,\"single_flight\":1,\"next\":\"jp_stall_preflight_drained\"}" [| box (DiagJson.esc nodeKey); box (DiagJson.esc site); box depth; box reKey; box max_reentry_key |])
                        with
                        | EvalReplayTyReturn value -> raise (EvalReplayTyReturn value)
                        | EvalVisitBudgetFailure _ as error -> raise error
                        | _ -> ()
                if reKey > max_reentry_key then
                    let hs = hashSnapShort ()
                    let ks = keySnapShort ()
                    let big = BigStack.isActive s.bigStack
                    CacheGeneration.requestSequential ()
                    let genNow = int (CacheGeneration.current())
                    DiagSidecar.emit (FastRuntimeFormat.format "%s ty cycle(key): key=%s depth=%d site=%s gen=%d re=%d/%d big=%b hs=[%s] ks=[%s]" [| box DiagnosticClassifier.EJP0011; box nodeKey; box depth; box site; box genNow; box reKey; box max_reentry_key; box big; box hs; box ks |])
                    let tc_count = TermCycleWatchdog.note ("ty:" + nodeKey) genNow
                    let tc_panic = big || tc_count >= 2
                    let frameOpt =
                        if tc_panic then
                            DiagSidecar.emit (FastRuntimeFormat.format "%s ty cycle watchdog: PANIC key=%s gen=%d count=%d" [| box DiagnosticClassifier.EJP0011; box nodeKey; box genNow; box tc_count |])
                            TermCycleFuse.tripWithTrace EvalVisitType ("ty:" + nodeKey) site depth genNow reKey max_reentry_key (termCycleFuseTraceOf s.trace)
                            EvalWorklist.ensureCapturedForKindId EvalWorklist.ReplayFrontierTy (CompilerKernelV2.OperationalReasonIdOps.create "direct_ty_cycle_key") |> ignore
                            EvalWorklist.attachSemanticCell EvalWorklist.ReplayTickEventTyCycle (semanticCellForTy nodeId)
                            EvalWorklist.ensureCapturedAndRunId (CompilerKernelV2.OperationalReasonIdOps.create "direct_ty_cycle_key") EvalWorklist.ReplayTickEventTyCycle 32
                        else None
                    // MIGRATION: direct keyed cycle replay can be a valid typed value, not just a retry-stop witness.
                    returnReplayTypeIfComplete "direct_ty_cycle_key" nodeId frameOpt
                    DiagJson.termCycle ("ty:" + nodeKey) depth site genNow reKey max_reentry_key big hs ks tc_count tc_panic
                    let errEnv = if depth > 256 then s else (add_trace s r0)
                    let msg = FastRuntimeFormat.format "%s: re-entrant type evaluation cycle detected at %s (key=%s depth=%d gen=%d re=%d/%d big=%b)" [| box DiagnosticClassifier.EJP0011; box site; box nodeKey; box depth; box genNow; box reKey; box max_reentry_key; box big |]
                    let msg = match frameOpt with Some frame -> EvalWorklist.requiredMessage msg frame | None -> msg
                    let msg =
                        msg + "\n"
                        + RunawayUnrollDiagnostic.render
                            "EJP0011"
                            (sprintf "partial evaluation re-entered `%s` more than %d times" site max_reentry)
                            (s.trace |> List.map (fun (r: Range) -> r.path, (fst r.range).line, (fst r.range).character))
                            "the re-entry limit (EvalFallbackPolicy.maxReentry) is not configurable: a deliberately deep recursion over static data should be a join point too"
                    if depth > 256 then
                        raise_type_error_no_trace errEnv msg
                    else
                        raise_type_error errEnv msg
                

            // Maximum recursion depth before triggering BigStack pivot.
            // Parallel/degraded attempts stay conservative, but once MIGRATION+ has forced a
            // sequential fallback we give the old non-parallel path more room. The runtime
            // stack check remains active, so this is bounded legacy compatibility rather than
            // returning to unguarded recursion.
            let max_depth_base = EvalFallbackPolicy.depthBase
            let max_depth_big = EvalFallbackPolicy.maxDepthBig seqNow
            let max_depth = if BigStack.isActive s.bigStack then max_depth_big else max_depth_base

            let deepSitesShort () =
                RecursionTracker.getDeepSites()
                |> List.sortByDescending (fun (_, count) -> count)
                |> List.truncate 8
                |> List.map (fun (site, count) -> sprintf "%s=%d" site count)
                |> String.concat ";"
    

            let stack_check (tag: string) =
                match evalStackProbeDecision () with
                | EvalStackProbeAvailable -> ()
                | EvalStackProbeInsufficient ->
                    let newGen = CacheGeneration.current()
                    jpMismatchAdd (sprintf "%s|ty_insufficient_stack" DiagnosticClassifier.EJP0010) |> ignore
                    let reasons = CacheGeneration.reasonsSnapshot 6 |> String.concat " | "
                    let deepSites = deepSitesShort ()
                    DiagSidecar.emitEnvSnapshotOnce()
                    let tid = System.Threading.Thread.CurrentThread.ManagedThreadId
                    let bigActive = BigStack.isActive s.bigStack
                    let nest = BigStack.getNest s.bigStack
                    let mbTy = BigStack.getMb s.bigStack BigStack.BigStackTy
                    let mem = try System.GC.GetTotalMemory(false) with _ -> 0L
                    DiagSidecar.emit (FastRuntimeFormat.format "%s ty insufficient_stack depth=%d site=%s gen=%d tag=%s tid=%d bigActive=%b nest=%d mb=%d mem=%d deepSites=[%s] reasons=[%s]" [| box DiagnosticClassifier.EJP0010; box depth; box site; box newGen; box tag; box tid; box bigActive; box nest; box mbTy; box mem; box deepSites; box reasons |])
                    raise (EvalCoreStackPivotRequested EvalCoreTyStackProbe)
    

            // Stack guard mais agressivo para evitar StackOverflow (especialmente com lambdas locais grandes).
            // A cadência aumenta com a profundidade: checamos pouco no início e muito quando está ficando perigoso.
            if depth <= 16 then
                if (depth &&& 3) = 0 then stack_check "d<=16"
            elif depth <= 64 then
                if (depth &&& 1) = 0 then stack_check "d<=64"
            else
    
                stack_check "d>64"

            if depth > max_depth then
                let newGen = CacheGeneration.current() // generic: do not invalidate on ty depth exceeded; make it a terminal error
                jpMismatchAdd (sprintf "%s|ty_depth_exceeded" DiagnosticClassifier.EJP0009) |> ignore
                let deepSites = deepSitesShort ()
                let reasons = CacheGeneration.reasonsSnapshot 6 |> String.concat " | "
                let bigActive = BigStack.isActive s.bigStack
                let mbTy = BigStack.getMb s.bigStack BigStack.BigStackTy
                DiagSidecar.emit (FastRuntimeFormat.format "%s ty recursion depth exceeded depth=%d max=%d base=%d bigActive=%b mb=%d site=%s gen=%d deepSites=[%s] reasons=[%s]" [| box DiagnosticClassifier.EJP0009; box depth; box max_depth; box max_depth_base; box bigActive; box mbTy; box site; box newGen; box deepSites; box reasons |])
                let errEnv = if depth > 256 then s else (add_trace s r0)
                if depth > 256 then
                    raise_type_error_no_trace errEnv (FastRuntimeFormat.format "%s: ty recursion depth exceeded (depth=%d max=%d) at %s" [| box DiagnosticClassifier.EJP0009; box depth; box max_depth; box site |])
                else
                    raise_type_error errEnv (FastRuntimeFormat.format "%s: ty recursion depth exceeded (depth=%d max=%d) at %s" [| box DiagnosticClassifier.EJP0009; box depth; box max_depth; box site |])
    

            match x with
            | TPatternRef _ -> failwith "Compiler error: TPatternRef should have been eliminated during the prepass."
            | TForall _ | TArrow _ | TJoinPoint _ -> failwith "Compiler error: Should have been transformed during the prepass."
            | TMetaV i -> YMetavar i
            | TArrow'(scope,i,body) ->
                assert (i = scope.ty.free_vars.Length)
                YTypeFunction(body,HopacExtensions.S.map (vt s) scope.ty.free_vars,scope.term.stack_size,scope.ty.stack_size)
            | TForall' _ -> YForall
            | TExists -> YExists
            | TJoinPoint'(r,scope,body) ->
                let env_global_type = scope.ty.free_vars |> HopacExtensions.S.map (fun i -> vt s i)
                let env_global_term = scope.term.free_vars |> HopacExtensions.S.map (fun i -> v s i)
                let (dict: System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<Ty []>, JPTypeCell<Ty>>), hc_table, cache_gen =
                    Utils.memoize join_point_type (fun _ ->
                        System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<Ty []>, JPTypeCell<Ty>>(jp_type_key_comparer), HashConsTable(), CacheGeneration.current ()
                    ) body
    

                let dict, hc_table =
                    if CacheGeneration.isStale cache_gen then
                        let fresh =
                            (System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<Ty []>, JPTypeCell<Ty>>(jp_type_key_comparer),
                             HashConsTable(),
                             CacheGeneration.current ())
                        join_point_type.[body] <- fresh
                        let (d,h,_) = fresh
                        d,h
                    else dict, hc_table
    

                // Include source range in JP key for better cache uniqueness
                let env_global_type_key =
                    let (sp, ep) = r.range
                    let rk = FastRuntimeFormat.format "jp_type@%s:%d:%d-%d:%d" [| box r.path; box sp.line; box sp.character; box ep.line; box ep.character |]
                    Array.append env_global_type [| YLit (LitString rk) |]
    

                let join_point_key = lock hc_table (fun () -> hc_table.Add(env_global_type_key))
                
                // MIGRATION: Use IVar-based cell for coordination

                let jp_cell = dict.GetOrAdd(join_point_key, fun _ -> { ivar = Hopac.IVar<Ty option>(); owner = JpTypeUnowned })
                let typePromiseRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-type-promise-cell"
                        (FastRuntimeFormat.format "generation=%d|tag=%d|hkey=%d" [| box (CacheGeneration.current()); box join_point_key.tag; box join_point_key.hkey |])
                let promiseRegistration =
                    JpPromiseProducerAuthority.registrationFor
                        (CacheGeneration.current())
                        JpTypePromiseCell
                        (JpPromiseTypeWitness typePromiseRef)
                        jp_cell.ivar
                let typePlaceholder =
                    YSymbol ("JPTypeRecPlaceholder(#" + CompilerIdentityKernel.ContentDigest.text typePromiseRef + ")")
                    |> fun placeholder -> jp_type_register_rec_placeholder placeholder jp_cell

                let deferJpTypeAtSynchronousBoundary disposition =
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"jp_type_synchronous_boundary_deferred\",\"key\":%s,\"promise_ref\":%s,\"disposition_du\":%s,\"placeholder_du\":%s,\"authority\":\"typed_placeholder_until_async_producer_completion\",\"next\":\"continue_type_evaluation_then_dereference_placeholder\"}" [| box (DiagJson.esc (jpConsedNodeIdentityText join_point_key)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text typePromiseRef)); box (DiagJson.esc (jpTypeSynchronousBoundaryDispositionText disposition)); box (DiagJson.esc (show_ty typePlaceholder)) |])
                    typePlaceholder
                

                // Fast path is an Alt probe; no direct IVar readiness polling.
                match jp_ivar_try_read jp_cell.ivar with
                | Some ready ->
                    match ready with
                    | Some ret_ty -> ret_ty
                    | None -> raise_type_error (add_trace s r) "error[EJP0004]: type join point completed with no value"
                | None ->
                    // Recursion guard based on per-evaluation stack
                    if s.jp_type_stack.Contains join_point_key then
                        let cur = trace_to_string_short (r :: s.trace)
                        let first_seen =
                            match jp_type_key_traces.TryGetValue join_point_key with
                            | true, tr -> trace_to_string_short tr
                            | _ -> "<unknown>"
                        let stack_prev = jp_type_stack_preview s.jp_type_stack
                        raise_type_error (add_trace s r)
                            (FastRuntimeFormat.format "error[EJP0001]: recursive join point requires annotation\n  |\n  = kind: type\n  = key: %s\n  = jp_type_stack: %d\n  = stack: %s\n  = first_seen: %s\n  = trace: %s\n" [| box (FastRuntimeFormat.objectText (box join_point_key)); box s.jp_type_stack.Count; box stack_prev; box first_seen; box cur |])
                    

                    let tid = try System.Threading.Thread.CurrentThread.ManagedThreadId with _ -> 0
                    let ownerState = JpTypeCellAuthority.snapshot jp_cell
                    let owner0 =
                        match ownerState with
                        | JpTypeUnowned -> 0
                        | JpTypeOwned ownerThreadId -> ownerThreadId
                    

                    if owner0 = tid && owner0 <> 0 then
                        // par: break same-thread recursion by returning a placeholder instead of failing.
                        // This keeps the type JP cache acyclic during definition and pushes failures to a later, more informative point if needed.
                        record_jp_diag_type join_point_key (r :: s.trace) |> ignore
                        typePlaceholder
                    elif owner0 <> 0 then
                        if SuspectCache.currentCount () > 0 then
                            // Global recovery mode: do not wait on potentially poisoned IVars/cells.
                            CacheGeneration.requestSequential ()
                            record_jp_diag_type join_point_key (r :: s.trace) |> ignore
                            let jp_method_stack = System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>(s.jp_method_stack, HashIdentity.Reference)
                            let jp_closure_stack = System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>(s.jp_closure_stack, HashIdentity.Reference)
                            let jp_type_stack = System.Collections.Generic.HashSet<ConsedNode<Ty []>>(s.jp_type_stack, jp_type_key_comparer)
                            jp_type_stack.Add join_point_key |> ignore
                            let s : LangEnv = {
                                trace = r :: s.trace
                                traceBudget = s.traceBudget
                                recursion = s.recursion
                                bigStack = s.bigStack
                                evalNodePath = s.evalNodePath
                                evalKeyPath = s.evalKeyPath
                                seq = ResizeArray()
                                cse = [System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural)]
                                unions = Map.empty
                                i = ref 0
                                env_global_type = env_global_type
                                env_global_term = env_global_term
                                env_stack_type = Array.zeroCreate<_> scope.ty.stack_size
                                env_stack_term = Array.zeroCreate<_> scope.term.stack_size
                                backend = s.backend
                                globals = s.globals
                                globals_lock = s.globals_lock
                                globals_seen = s.globals_seen
                                join_point_method_key_names = s.join_point_method_key_names
                                join_point_closure_key_names = s.join_point_closure_key_names
                                jp_method_stack = jp_method_stack
                                jp_closure_stack = jp_closure_stack
                                jp_type_stack = jp_type_stack
                                }
                            let s = rename_global_term s
                            let recursion_site = sprintf "JPType.recovery_bypass@%s:%d" r.path (fst r.range).line
                            let recursionEntry = RecursionTracker.enter (CompilerIdentityKernel.WorkSiteIdOps.create recursion_site) s.recursion
                            let s = { s with recursion = RecursionTracker.context recursionEntry }
                            let entry_depth = RecursionTracker.currentDepth s.recursion
                            try
                                BitMamba.recordAccess join_point_key
                                let compute_ty () = ty s body
                                let ret_ty =
                                    if entry_depth > 64 then
                                        match BigStack.tryRun s.bigStack BigStack.BigStackJoinPoint (sprintf "jp_type_recovery_%d" join_point_key.tag) (fun child -> ty (langEnvWithBigStack child s) body) with
                                        | Some v -> v
                                        | None ->
                                            raise_type_error (add_trace s r) (sprintf "%s: JPType evaluation refused after BigStack exhaustion (tag=%d)" DiagnosticClassifier.EJP0010 join_point_key.tag)
                                    else compute_ty ()
                                jp_recursive_array_resolve_obligations typePlaceholder ret_ty
                                ret_ty
                            finally
                                RecursionTracker.exit recursionEntry |> ignore
                        else
                            // Another thread owns the cell and computes the type inline; wait for its result
                            // instead of carrying a placeholder (see the owned case below).
                            ignore (JpTypeDeferredFromForeignProducer owner0)
                            match (HopacExtensions.startAsTask (Hopac.IVar.read jp_cell.ivar)).Result with
                            | Some ret_ty -> ret_ty
                            | None -> raise_type_error (add_trace s r) "error[EJP0004]: type join point producer failed"
                    else
                        // Try to become owner through the typed cell authority.
                        let ownershipDecision = JpTypeCellAuthority.tryAcquire tid jp_cell
                        let ownershipAcquired =
                            match ownershipDecision with
                            | JpTypeOwnershipAcquired _ -> true
                            | JpTypeOwnershipAlreadyHeldBySelf _
                            | JpTypeOwnershipHeldByOther _ -> false
                        if ownershipAcquired then
                            let spawnContext = record_jp_diag_type join_point_key (r :: s.trace)
                            assert (0 = scope.term.free_vars.Length)
                            

                            let run () =
                                let inflight = get_async_local jp_type_inflight mk_jp_type_inflight
                                let inflight_added = inflight.Add join_point_key
                                try
                                    try
                                        let jp_method_stack = System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>(s.jp_method_stack, HashIdentity.Reference)
                                        let jp_closure_stack = System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>(s.jp_closure_stack, HashIdentity.Reference)
                                        let jp_type_stack = System.Collections.Generic.HashSet<ConsedNode<Ty []>>(s.jp_type_stack, jp_type_key_comparer)
                                        jp_type_stack.Add join_point_key |> ignore
                                        let s : LangEnv = {
                                            trace = r :: s.trace
                                            traceBudget = s.traceBudget
                                            recursion = s.recursion
                                            bigStack = s.bigStack
                                            evalNodePath = s.evalNodePath
                                            evalKeyPath = s.evalKeyPath
                                            seq = ResizeArray()
                                            cse = [System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural)]
                                            unions = Map.empty
                                            i = ref 0
                                            env_global_type = env_global_type
                                            env_global_term = env_global_term
                                            env_stack_type = Array.zeroCreate<_> scope.ty.stack_size
                                            env_stack_term = Array.zeroCreate<_> scope.term.stack_size
                                            backend = s.backend
                                            globals = s.globals
                                            globals_lock = s.globals_lock
                                            globals_seen = s.globals_seen
                                            join_point_method_key_names = s.join_point_method_key_names
                                            join_point_closure_key_names = s.join_point_closure_key_names
                                            jp_method_stack = jp_method_stack
                                            jp_closure_stack = jp_closure_stack
                                            jp_type_stack = jp_type_stack
                                            }
                                        let s = rename_global_term s
                                    
                                        // MIGRATION: Simplified evaluation - just evaluate and fill IVar

                                        let recursion_site = sprintf "JPType@%s:%d" r.path (fst r.range).line
                                        let recursionEntry = RecursionTracker.enter (CompilerIdentityKernel.WorkSiteIdOps.create recursion_site) s.recursion
                                        let s = { s with recursion = RecursionTracker.context recursionEntry }
                                        let entry_depth = RecursionTracker.currentDepth s.recursion
                                        BitMamba.recordAccess join_point_key
                                    

                                        let ret_ty = ty s body
                                        jp_recursive_array_resolve_obligations typePlaceholder ret_ty
                                    

                                        // Fill IVar to signal completion
                                        jp_fill_ivar JpIvarTypeProducerFill jp_cell.ivar (Some ret_ty)
                                        JpPromiseProducerAuthority.complete
                                            promiseRegistration
                                            (CompilerIdentityKernel.ContentDigest.ofText
                                                "jp-type-promise-completed"
                                                (CompilerIdentityKernel.ContentDigest.text typePromiseRef
                                                 + "|type=" + show_ty ret_ty))
                                        ()
                                    with e ->
                                        // Fill with None so waiters don't hang
                                        let failureRef =
                                            CompilerIdentityKernel.ContentDigest.ofText
                                                "jp-type-promise-failed"
                                                (CompilerIdentityKernel.ContentDigest.text typePromiseRef
                                                 + "|exception=" + e.GetType().FullName)
                                        JpPromiseProducerAuthority.fail promiseRegistration failureRef
                                        try jp_fill_ivar JpIvarTypeFailureFill jp_cell.ivar None with _ -> ()
                                        reraise()
                                finally
                                    RecursionTracker.exit recursionEntry |> ignore
                                    JpTypeCellAuthority.release tid jp_cell |> ignore
                                    if inflight_added then inflight.Remove join_point_key |> ignore
                            
                            // Compute the type inline, as the single-flight core does. Scheduling it as a Hopac job
                            // and returning a placeholder meant the first use of every type join point carried a
                            // JPTypeRecPlaceholder: `Cons (a, Nil)` was then built as a raw nominal pair instead of a
                            // union (so every later unbox missed, e.g. frontier_try_item), and placeholders reached
                            // codegen (tagged_union_scalar). Recursive references still break on the same-thread
                            // placeholder above, because this thread owns the cell while `run` evaluates the body.
                            ignore spawnContext
                            run ()
                            match jp_ivar_try_read jp_cell.ivar with
                            | Some (Some ret_ty) -> ret_ty
                            | _ -> raise_type_error (add_trace s r) "error[EJP0004]: type join point completed with no value"
                        else
                            // Lost the race - if we're in global recovery, recompute instead of waiting on a potentially poisoned cell.
                            if SuspectCache.currentCount () > 0 then
                                CacheGeneration.requestSequential ()
                                record_jp_diag_type join_point_key (r :: s.trace) |> ignore
                                let jp_method_stack = System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>(s.jp_method_stack, HashIdentity.Reference)
                                let jp_closure_stack = System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>(s.jp_closure_stack, HashIdentity.Reference)
                                let jp_type_stack = System.Collections.Generic.HashSet<ConsedNode<Ty []>>(s.jp_type_stack, jp_type_key_comparer)
                                jp_type_stack.Add join_point_key |> ignore
                                let s : LangEnv = {
                                    trace = r :: s.trace
                                    traceBudget = s.traceBudget
                                    recursion = s.recursion
                                    bigStack = s.bigStack
                                    evalNodePath = s.evalNodePath
                                    evalKeyPath = s.evalKeyPath
                                    seq = ResizeArray()
                                    cse = [System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural)]
                                    unions = Map.empty
                                    i = ref 0
                                    env_global_type = env_global_type
                                    env_global_term = env_global_term
                                    env_stack_type = Array.zeroCreate<_> scope.ty.stack_size
                                    env_stack_term = Array.zeroCreate<_> scope.term.stack_size
                                    backend = s.backend
                                    globals = s.globals
                                    globals_lock = s.globals_lock
                                    globals_seen = s.globals_seen
                                    join_point_method_key_names = s.join_point_method_key_names
                                    join_point_closure_key_names = s.join_point_closure_key_names
                                    jp_method_stack = jp_method_stack
                                    jp_closure_stack = jp_closure_stack
                                    jp_type_stack = jp_type_stack
                                    }
                                let s = rename_global_term s
                                let recursion_site = sprintf "JPType.recovery_bypass@%s:%d" r.path (fst r.range).line
                                let recursionEntry = RecursionTracker.enter (CompilerIdentityKernel.WorkSiteIdOps.create recursion_site) s.recursion
                                let s = { s with recursion = RecursionTracker.context recursionEntry }
                                let entry_depth = RecursionTracker.currentDepth s.recursion
                                try
                                    BitMamba.recordAccess join_point_key
                                    let compute_ty () = ty s body
                                    let ret_ty =
                                        if entry_depth > 64 then
                                            match BigStack.tryRun s.bigStack BigStack.BigStackJoinPoint (sprintf "jp_type_recovery_%d" join_point_key.tag) (fun child -> ty (langEnvWithBigStack child s) body) with
                                            | Some v -> v
                                            | None ->
                                                raise_type_error (add_trace s r) (sprintf "%s: JPType evaluation refused after BigStack exhaustion (tag=%d)" DiagnosticClassifier.EJP0010 join_point_key.tag)
                                        else compute_ty ()
                                    jp_recursive_array_resolve_obligations typePlaceholder ret_ty
                                    ret_ty
                                finally
                                    RecursionTracker.exit recursionEntry |> ignore
                            else
                                // The winner is computing the type inline on its own thread; wait for its result
                                // instead of carrying a placeholder (see the owned case above).
                                ignore JpTypeDeferredAfterOwnershipRace
                                match (HopacExtensions.startAsTask (Hopac.IVar.read jp_cell.ivar)).Result with
                                | Some ret_ty -> ret_ty
                                | None -> raise_type_error (add_trace s r) "error[EJP0004]: type join point producer failed"
    

            | TB _ -> YB
            | TLit(_,x) -> YLit x
            | TV i -> vt s i
            | TPair(_,a,b) -> YPair(ty s a, ty s b)
            | TFun(a,b,t) -> YFun(ty s a, ty s b,t)
            | TModule a ->
                YRecord(
                    a
                    |> Seq.mapi (fun i (KeyValue (k, v)) -> (i, TypeNameIdOps.text k), (v |> ty s))
                    |> Map.ofSeq
                )
            | TRecord(_,a) -> YRecord(Map.map (fun _ -> ty s) a)
            | TUnion(_,(a,b)) ->
                let tags = Dictionary()
                let tag_cases = Array.zeroCreate (Map.count a)
                let mutable is_degenerate = true
                let cases =
                    Map.fold (fun cases (i,k) v ->
                        let v = Option.defaultValue (fst v) (snd v) // If the union case is generalized, use the specialized destructor instead of the constructor to evaluate the type.
                        match ty s v with
                        | YVoid -> cases
                        | v ->
                            is_degenerate <- is_degenerate && match v with YB -> true | _ -> false
                            tags.[UnionTagIdOps.create k] <- i
                            tag_cases.[i] <- (k,v)
                            Map.add (i,k) v cases
                        ) Map.empty a
                YUnion(H {|cases=cases; layout=b; tags=tags; tag_cases=tag_cases; is_degenerate=is_degenerate|})
            | TTypecase(r,a,b) ->
                let s = add_trace s r
                let a = ty s a
                let rec loop = function
                    | (a',b) :: rest -> if is_unify s (a,ty s a') then Some(ty s b) else loop rest
                    | [] -> None
                match loop b with
                | Some r -> r
                | None -> YVoid
            | TSymbol(_,a) -> YSymbol a
            | TApply(r,a,b) ->
                let s = add_trace s r
                match ty s a with
                | YRecord a ->
                    match ty s b with
                    | YSymbol b ->
                        match a |> Map.tryPick (fun (_, k) v -> if k = b then Some v else None) with
                        | Some x -> x
                        | None -> raise_type_error s <| sprintf  "Cannot find key %s in the record." b
                    | b -> raise_type_error s <| sprintf "Expected a symbol in the record application.\nGot: %s" (show_ty b)
                | YMetavar _ | YNominal _ | YApply _ as a -> YApply(a,ty s b)
                | YTypeFunction(body,gl_ty,sz_term,sz_ty) ->
                    let b = ty s b
                    let s = { s with env_global_type = gl_ty; env_global_term = [||]; env_stack_type = Array.zeroCreate<_> sz_ty; env_stack_term = Array.zeroCreate<_> sz_term }
                    s.env_stack_type.[0] <- b
                    ty s body
                | a -> raise_type_error s <| sprintf "Expected a record, nominal or a type function. Or a metavar when in typecase.\nGot: %s" (show_ty a)
            | TPrim a -> YPrim a
            | TTerm(_,a) -> term_real_nominal s a
            | TMacro(r,a) ->
                let s = add_trace s r
                YMacro(a |> List.map (function TMText a -> PartEvalMacro.Text a | TMType a -> Type(ty s a) | TMLitType a -> TypeLit(ty s a |> assert_ty_lit s)))
            | TNominal i -> YNominal env.nominals.[i]
            | TArray a -> YArray(ty s a)
            | TLayout(a,b) -> YLayout(ty s a,b)
        and resume_declared_apply applyFn sliceContext sliceStartOperationCount applyNodeId (frames:JpDeclaredApplyFrame array) initialFrameIndex initialValue initialStage =
            let mutable res = initialValue
            let mutable frameIndex = initialFrameIndex
            let mutable frameStage = initialStage
            let mutable processedInSlice = 0
            if frameIndex >= 0 then
                jpRecordCurrentWorkPhase JpOperationPhaseApplyArgument
            while frameIndex >= 0 do
                let frame = frames.[frameIndex]
                let s' = JpDeclaredApplyFrameOps.environment frame
                let arg = JpDeclaredApplyFrameOps.expression frame
                let argValue =
                    match frameStage with
                    | JpDeclaredApplyHeadPending ->
                        invalidOp "ApplyHeadPending must be satisfied by its direct child result before argument evaluation."
                    | JpDeclaredApplyArgumentReadyDispatchPending value -> value
                    | JpDeclaredApplyBeforeArgument ->
                        let beforeArgumentSafeContinuation =
                            match sliceContext with
                            | Some (JpDeclaredBodySliceContext(jobId, _, _)) ->
                                let continuationRef =
                                    jpStoreDeclaredApplyContinuation
                                        jobId applyNodeId frames frameIndex (Some res) JpDeclaredApplyBeforeArgument
                                Some (JpDeclaredApplySafeContinuation(jobId, applyNodeId, continuationRef))
                            | None -> None
                        match beforeArgumentSafeContinuation with
                        | Some safeContinuation ->
                            let continuationRef = jpDeclaredSafeContinuationRef safeContinuation
                            let value =
                                jpWithDeclaredSafeContinuation safeContinuation (fun () ->
                                    jpWithCurrentDeclaredTailResultBridge JpDeclaredApplyArgumentResultBridge (fun () -> term s' arg))
                            jpRetireDeclaredResumeSnapshot continuationRef
                            value
                        | None -> term s' arg
                let dispatchSafeContinuation =
                    match sliceContext with
                    | Some (JpDeclaredBodySliceContext(jobId, _, _)) ->
                        let continuationRef =
                            jpStoreDeclaredApplyContinuation
                                jobId applyNodeId frames frameIndex (Some res) (JpDeclaredApplyArgumentReadyDispatchPending argValue)
                        Some (JpDeclaredApplySafeContinuation(jobId, applyNodeId, continuationRef))
                    | None -> None
                if (frameIndex &&& 1023) = 0 then
                    jpRecordCurrentWorkPhase JpOperationPhaseApplyDispatch
                res <-
                    match dispatchSafeContinuation with
                    | Some safeContinuation ->
                        let continuationRef = jpDeclaredSafeContinuationRef safeContinuation
                        let value =
                            jpWithDeclaredSafeContinuation safeContinuation (fun () ->
                                jpWithCurrentDeclaredTailResultBridge JpDeclaredApplyDispatchResultBridge (fun () -> applyFn s' (res, argValue)))
                        jpRetireDeclaredResumeSnapshot continuationRef
                        value
                    | None -> applyFn s' (res, argValue)
                processedInSlice <- processedInSlice + 1
                let nextFrameIndex = frameIndex - 1
                frameStage <- JpDeclaredApplyBeforeArgument
                match sliceContext with
                | Some (JpDeclaredBodySliceContext(jobId, maxOperations, checkpointInterval)) when nextFrameIndex >= 0 ->
                    let continuationRef =
                        jpStoreDeclaredApplyContinuation
                            jobId applyNodeId frames nextFrameIndex (Some res) JpDeclaredApplyBeforeArgument
                    let operationDelta = max 0L (jp_current_operation_counter.Value - sliceStartOperationCount)
                    let operationBudgetReached = operationDelta >= int64 (max 1 maxOperations)
                    let checkpointReached = processedInSlice >= max 1 checkpointInterval
                    if checkpointReached || operationBudgetReached then
                        let yieldCause =
                            if operationBudgetReached then JpDeclaredSliceYieldOperationBudget
                            else JpDeclaredSliceYieldCheckpointInterval
                        jpRecordCurrentWorkPhase JpOperationPhaseApplyArgument
                        raise (JpDeclaredEvaluatorSliceYield(yieldCause, continuationRef))
                    else
                        jpRetireDeclaredResumeSnapshot continuationRef
                | Some (JpDeclaredBodySliceContext(jobId, _, _)) ->
                    jpClearDeclaredApplyContinuation jobId applyNodeId
                | None -> ()
                frameIndex <- nextFrameIndex
            res

        and validate_annotated_value (s:LangEnv) (r:Range) (annotation:TPrepass) (value:Data) : Data =
            let valueTy = data_to_ty s value
            let expectedTy = ty s annotation
            let valueTyDeref = jp_method_deref_rec_placeholder valueTy
            let expectedTyDeref = jp_method_deref_rec_placeholder expectedTy
            if ty_eq_allow_jp_placeholders valueTyDeref expectedTyDeref |> not then
                match value, expectedTy with
                | DLit (LitString text), YB ->
                    if s.backend.node = env.backend then globals_add s text |> ignore
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_raw_global_string_unit_annotation_resolved\",\"text_len\":%d,\"site\":%s,\"single_flight\":1,\"next\":\"return_unit_after_raw_global\"}"
                            text.Length (DiagJson.esc r.path))
                    DB
                | DLit (LitString text), expectedTy ->
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_raw_global_string_annotation_residualized\",\"text_len\":%d,\"expected\":%s,\"site\":%s,\"single_flight\":1,\"next\":\"residualize_raw_backend_annotation\"}" [| box text.Length; box (DiagJson.esc (show_ty expectedTy)); box (DiagJson.esc r.path) |])
                    push_op_no_rewrite s Global (DLit (LitString text)) expectedTy
                | _ ->
                    raise_type_error s <| FastRuntimeFormat.format "The body does not match the annotation.\n    Got: %s\n    Expected: %s\n    Got(deref): %s\n    Expected(deref): %s" [| box (show_ty valueTy); box (show_ty expectedTy); box (show_ty valueTyDeref); box (show_ty expectedTyDeref) |]
            else value

        and validate_sequence_first_value observation (s0:LangEnv) (r:Range) (first:E) (seqValue:Data) =
            let seqUnitDecisionId = sequenceUnitCoercionDecisionFor observation first seqValue
            match seqUnitDecisionId with
            | SequenceUnitAlreadyUnit -> ()
            | SequenceUnitPlaceholderAsUnit ->
                if jp_diag_verbose then
                    DiagSidecar.emit (sprintf "ESEQ.placeholder_as_unit got=%s" (show_data seqValue))
            | SequenceApplyReplayWitnessAsUnit
            | SequenceApplyResidualRuntimeValueAsUnit ->
                DiagJson.emit (
                    FastRuntimeFormat.format
                        "{\"kind\":\"eval_worklist_seq_first_witness_discarded\",\"event\":\"term_seq\",\"observation_du\":%s,\"decision_du\":%s,\"first_shape\":%s,\"got\":%s,\"trace_depth\":%d,\"site\":%s,\"policy\":\"typed_sequence_observation_provenance_no_source_path\",\"single_flight\":1,\"next\":\"continue_sequence_body\"}"
                        [| box (DiagJson.esc (sequenceUnitObservationText observation)); box (DiagJson.esc (sequenceUnitCoercionDecisionText seqUnitDecisionId)); box (DiagJson.esc (evalNodeShapeTerm first)); box (DiagJson.esc (show_data seqValue)); box s0.trace.Length; box (DiagJson.esc r.path) |])
            | SequenceUnitRejected ->
                let jobId = jpCurrentWorkJobId ()
                let valueShapeText = seqValue |> replayDataShapeOf |> replayDataShapeText
                let currentSafeContinuation = jpCurrentDeclaredSafeContinuation ()
                let currentSafeContinuationKind =
                    currentSafeContinuation
                    |> Option.map jpDeclaredSafeContinuationKindText
                    |> Option.defaultValue "None"
                let currentSafeContinuationRefText, currentSafeContinuationNodeId, currentSafeContinuationChannel =
                    match currentSafeContinuation with
                    | Some safeContinuation ->
                        let continuationRef = jpDeclaredSafeContinuationRef safeContinuation
                        let channel =
                            match jpTryDeclaredResumeSnapshotByRef continuationRef with
                            | Some snapshot -> snapshot |> jpDeclaredResumeSnapshotResultChannel |> jpDeclaredResumeResultChannelText
                            | None -> "Missing"
                        JpWorkContinuationRefOps.text continuationRef, jpDeclaredSafeContinuationNodeId safeContinuation, channel
                    | None -> "None", 0, "None"
                DiagJson.emit (
                    FastRuntimeFormat.format
                        "{\"kind\":\"eval_worklist_seq_first_rejected\",\"work_job_id\":%d,\"observation_du\":%s,\"first_shape_du\":%s,\"value_shape_du\":%s,\"got\":%s,\"current_safe_continuation_kind_du\":%s,\"current_safe_continuation_ref\":%s,\"current_safe_continuation_node_id\":%d,\"current_safe_continuation_result_channel_du\":%s,\"source_path_authority\":false,\"diagnostic_text_authority\":false,\"control_authority\":false,\"authority\":\"typed_sequence_unit_rejection_observation_only\",\"next\":\"attribute_direct_vs_carrier_result_before_any_unit_widening\"}"
                        [| box jobId; box (DiagJson.esc (sequenceUnitObservationText observation)); box (DiagJson.esc (evalNodeShapeTerm first)); box (DiagJson.esc valueShapeText); box (DiagJson.esc (show_data seqValue)); box (DiagJson.esc currentSafeContinuationKind); box (DiagJson.esc currentSafeContinuationRefText); box currentSafeContinuationNodeId; box (DiagJson.esc currentSafeContinuationChannel) |])
                raise_type_error s0 <|
                    FastRuntimeFormat.format
                        "Expected unit in sequence first expression (observation=%s shape=%s decision=%s).\nGot: %s"
                        [| box (sequenceUnitObservationText observation); box (evalNodeShapeTerm first); box (sequenceUnitCoercionDecisionText seqUnitDecisionId); box (show_data seqValue) |]

        and resume_declared_sequence jobId nodeId (initialEnvironment:LangEnv) (initialExpression:E) =
            let mutable currentEnvironment = initialEnvironment
            let mutable currentExpression = initialExpression
            let mutable result : Data option = None
            while Option.isNone result do
                match currentExpression with
                | ESeq(r, first, rest) ->
                    currentEnvironment <- add_trace currentEnvironment r
                    jpRecordCurrentWorkPhase JpOperationPhaseSequenceFirst
                    let continuationRef =
                        jpStoreDeclaredSequenceContinuation
