                        jpWithDeclaredSafeContinuation safeContinuation (fun () -> term environment rightExpression)
                    jpClearDeclaredBinaryNumericContinuation jobId nodeId
                    result <- Some(leftValue, rightValue)
                jpRetireDeclaredResumeSnapshot continuationRef
            Option.get result

        and term2_declared_binary_numeric operation (s:LangEnv) (expression:E) leftExpression rightExpression =
            match jpCurrentDeclaredBodySliceContext () with
            | Some (JpDeclaredBodySliceContext(jobId, _, _)) ->
                let nodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box expression)
                match jpTryGetDeclaredBinaryNumericContinuation jobId nodeId with
