            | None -> term s leftExpression, term s rightExpression

        and resume_declared_record_type_foldback
                applyFn
                typeApplyFn
                tyRecordFn
                jobId
                nodeId
                f
                initialStateExpression
                recordType
                (initialState:JpDeclaredRecordTypeFoldBackState) =
            let mutable state = initialState
            let mutable result : Data option = None
            while Option.isNone result do
                let continuationRef =
                    jpStoreDeclaredRecordTypeFoldBackContinuation
                        jobId nodeId f initialStateExpression recordType state
                let safeContinuation = JpDeclaredRecordTypeFoldBackSafeContinuation(jobId, nodeId, continuationRef)
                match state with
                | JpDeclaredRecordTypeFoldBackFolderPending environment ->
                    let folder =
                        jpWithDeclaredSafeContinuation safeContinuation (fun () -> term environment f)
                    state <- JpDeclaredRecordTypeFoldBackInitialStatePending(environment, folder)
                | JpDeclaredRecordTypeFoldBackInitialStatePending(environment, folder) ->
                    let initialStateValue =
                        jpWithDeclaredSafeContinuation safeContinuation (fun () -> term environment initialStateExpression)
                    state <- JpDeclaredRecordTypeFoldBackRecordTypePending(environment, folder, initialStateValue)
                | JpDeclaredRecordTypeFoldBackRecordTypePending(environment, folder, initialStateValue) ->
                    let fields =
                        jpWithDeclaredSafeContinuation safeContinuation (fun () ->
                            tyRecordFn environment recordType |> Map.toArray |> Array.rev)
                    state <- JpDeclaredRecordTypeFoldBackFieldPending(environment, folder, fields, 0, initialStateValue)
                | JpDeclaredRecordTypeFoldBackFieldPending(environment, folder, fields, nextFieldIndex, currentState) ->
                    if nextFieldIndex >= fields.Length then
                        jpClearDeclaredRecordTypeFoldBackContinuation jobId nodeId
                        result <- Some currentState
                    else
                        let (_, key), _fieldType = fields.[nextFieldIndex]
                        let typedFolder =
                            jpWithDeclaredSafeContinuation safeContinuation (fun () ->
                                applyFn environment (folder, DSymbol key))
                        state <- JpDeclaredRecordTypeFoldBackKeyApplied(environment, folder, fields, nextFieldIndex, currentState, typedFolder)
                | JpDeclaredRecordTypeFoldBackKeyApplied(environment, folder, fields, nextFieldIndex, currentState, typedFolder) ->
                    let _, fieldType = fields.[nextFieldIndex]
                    let specializedFolder =
                        jpWithDeclaredSafeContinuation safeContinuation (fun () ->
                            typeApplyFn environment typedFolder fieldType)
                    state <- JpDeclaredRecordTypeFoldBackTypeApplied(environment, folder, fields, nextFieldIndex, currentState, specializedFolder)
                | JpDeclaredRecordTypeFoldBackTypeApplied(environment, folder, fields, nextFieldIndex, currentState, specializedFolder) ->
                    let nextState =
                        jpWithDeclaredSafeContinuation safeContinuation (fun () ->
                            applyFn environment (specializedFolder, currentState))
                    state <- JpDeclaredRecordTypeFoldBackFieldPending(environment, folder, fields, nextFieldIndex + 1, nextState)
                jpRetireDeclaredResumeSnapshot continuationRef
            Option.get result

        and term (s : LangEnv) (x:E) : Data =
            // Direct semantic resume must execute inside term_core_impl, where apply/type_apply/ty_record live.
            // The wrapper also owns typed evaluator-parent depth. A safe continuation is a direct parent only
            // for its immediate term child; deeper unmodeled recursion is represented as Opaque rather than
            // being silently attached to that continuation or collapsed to Root.
            if debugTermTrace.Value.IsSome then
                match x with
                | EApply(r, _, _) -> debugTraceAt r "term" (System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode s.seq) s.seq.Count
                | EMacro(r, _, _) -> debugTraceAt r "term macro" (System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode s.seq) s.seq.Count
                | _ -> ()
            let previousTermDepth = jp_current_declared_term_depth.Value
            jp_current_declared_term_depth.Value <- max 0 previousTermDepth + 1
            try
                match evalCoreEntryRun s 32 BigStack.BigStackTerm "term_depth" (fun env -> term_core env x) with
                | EvalCoreStackCompleted value -> value
                | EvalCoreStackBigStackExhausted ->
                    let fallback = match s.trace with | r :: _ -> r | [] -> range0
                    let r0 = range_of_e_or fallback x
                    let site = sprintf "term@%s:%d" r0.path (fst r0.range).line
                    raise_type_error (add_trace s r0) (sprintf "%s: term evaluation refused after BigStack exhaustion at %s" DiagnosticClassifier.EJP0010 site)
            finally
                jp_current_declared_term_depth.Value <- previousTermDepth
    

        and term_core (s : LangEnv) (x:E) : Data =
            // MIGRATION: direct and BigStack execution share one typed stack
            // decision; replay-return remains a separate control result.
            let nodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box x)
            EvalReplayValueStore.enterDirectNode nodeId
            EvalReplayValueStore.enterDirectScope (box s.seq)
            try
                try
                    match evalCoreWithBigStack s BigStack.BigStackTerm "term_emergency" (fun env -> term_core_impl env x) with
                    | EvalCoreStackCompleted value ->
                        EvalReplayValueStore.markDirectNodeCompleted nodeId
                        value
                    | EvalCoreStackBigStackExhausted ->
                        let fallback = match s.trace with | r :: _ -> r | [] -> range0
                        let r0 = range_of_e_or fallback x
                        let site = sprintf "term@%s:%d" r0.path (fst r0.range).line
                        raise_type_error (add_trace s r0) (sprintf "%s: stack overflow in term at %s (BigStack exhausted)" DiagnosticClassifier.EJP0010 site)
                with
                | EvalReplayTermReturn value -> value
            finally
                EvalReplayValueStore.exitDirectScope (box s.seq)
                EvalReplayValueStore.exitDirectNode nodeId
    

        and term_core_impl (s : LangEnv) (x:E) : Data =
    

            let fallback = match s.trace with | r :: _ -> r | [] -> range0
            let r0 = range_of_e_or fallback x
            let site = sprintf "term@%s:%d" r0.path (fst r0.range).line
            let siteId = CompilerIdentityKernel.WorkSiteIdOps.create site
            let termShape0 = evalNodeShapeTerm x
            match jpRecordCurrentWorkOperation JpActiveTermOperation siteId termShape0 (System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box x)) with
            | JpActiveOperationProfiled -> jpProbeCurrentWorkExecutionBudget siteId
            | JpActiveOperationCounted
            | JpActiveOperationUntracked -> ()
            jpYieldCurrentDeclaredBodyAtOperationBoundary ()
            let termSourceKey0 =
                EvalReplayValueStore.termSourceKey site termShape0 s.env_global_term.Length s.env_stack_term.Length s.env_global_type.Length s.env_stack_type.Length s.trace.Length
            let semanticCellForTerm nodeId = evalCell EvalWorklist.EvalTerm (CompilerIdentityKernel.WorkShapeIdOps.create termShape0) nodeId (CompilerIdentityKernel.WorkSiteIdOps.create site) s
            if TermCycleFuse.isTripped() then
                match EvalReplayValueStore.tryTermSourceValue termSourceKey0 with
                | Some value ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_source_value_replay_return\",\"event\":\"term_entry_global_fuse\",\"status\":\"semantic_root_complete\",\"shape\":%s,\"source_key\":%s,\"single_flight\":1,\"next\":\"return_term_value\"}"
                            (DiagJson.esc termShape0) (DiagJson.esc (EvalReplayValueStore.semanticSourceKeyText termSourceKey0)))
                    TermCycleFuse.reset ()
                    raise (EvalReplayTermReturn value)
                | None -> ()
                let nodeId0 = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box x)
                let rec registerReplayTermWithContext (context:BigStackExecutionContext) (nodeId: int) (expr: E) =
                    let pending = System.Collections.Generic.Stack<EvalReplayRegistrationFrame>()
                    let children = System.Collections.Generic.List<EvalReplayRegistrationFrame>()
                    pending.Push(EvalReplayRegistrationTermFrame(nodeId, expr))
                    while pending.Count > 0 do
                        match pending.Pop() with
                        | EvalReplayRegistrationTermFrame(currentNodeId, currentExpr) ->
                            children.Clear()
                            let registerReplayTerm childNodeId childExpr =
                                children.Add(EvalReplayRegistrationTermFrame(childNodeId, childExpr))
                            match
                                evalReplayRegistrationRun
                                    context
                                    BigStack.BigStackRegisterReplayTermGlobalFuse
                                    "register_replay_term_global_fuse_child"
                                    (fun currentContext -> registerReplayTermDirect currentContext registerReplayTerm currentNodeId currentExpr)
                            with
                            | EvalReplayRegistrationCompleted ->
                                for i = children.Count - 1 downto 0 do
                                    pending.Push(children.[i])
                            | EvalReplayRegistrationBigStackExhausted -> evalReplayRegistrationStackFailure s siteId currentNodeId
                and registerReplayTermDirect
                    (context:BigStackExecutionContext)
                    (registerReplayTerm:int -> E -> unit)
                    (nodeId:int)
                    (expr:E) =
                    match expr with
                    | EB _ -> EvalReplayValueStore.putTermValue nodeId DB
                    | EV a -> EvalReplayValueStore.putTerm nodeId (fun () -> v s a)
                    | ELit(_,lit) -> EvalReplayValueStore.putTermValue nodeId (DLit lit)
                    | ESymbol(_,sym) -> EvalReplayValueStore.putTermValue nodeId (DSymbol sym)
                    | EFun'(_,freeVars,i,body,annot) ->
                        EvalReplayValueStore.putTerm nodeId (fun () ->
                            if freeVars.term.free_vars.Length <> i then failwith "Replay function free-var arity mismatch."
                            DFunction(body, annot, HopacExtensions.S.map (v s) freeVars.term.free_vars, HopacExtensions.S.map (vt s) freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                    | ERecursiveFun'(_,freeVars,i,body,annot) ->
                        EvalReplayValueStore.putTerm nodeId (fun () ->
                            if freeVars.term.free_vars.Length <> i then failwith "Replay recursive function free-var arity mismatch."
                            DFunction(body.Value, annot, HopacExtensions.S.map (v s) freeVars.term.free_vars, HopacExtensions.S.map (vt s) freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                    | EForall'(_,freeVars,i,body) ->
                        EvalReplayValueStore.putTerm nodeId (fun () ->
                            if freeVars.ty.free_vars.Length <> i then failwith "Replay forall free-var arity mismatch."
                            DForall(body, HopacExtensions.S.map (v s) freeVars.term.free_vars, HopacExtensions.S.map (vt s) freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                    | ERecursiveForall'(_,freeVars,i,body) ->
                        EvalReplayValueStore.putTerm nodeId (fun () ->
                            if freeVars.ty.free_vars.Length <> i then failwith "Replay recursive forall free-var arity mismatch."
                            DForall(body.Value, HopacExtensions.S.map (v s) freeVars.term.free_vars, HopacExtensions.S.map (vt s) freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                    | EJoinPoint'(_,_,_,_,_,_) ->
                        // MIGRATION: EJoinPoint' is a first-class term value computation.
                        // Register the existing evaluator thunk so the replay driver can
                        // attempt real join-point materialization instead of falling through
                        // to the opaque E* dispatcher and repeating term_shape_dispatch.
                        EvalReplayValueStore.putTerm nodeId (fun () -> term s expr)
                    | EUnbox(r,k,id,a,on_succ,on_fail) ->
                        // MIGRATION: EUnbox is a real evaluator form, not an opaque E* leaf.
                        // The 645 runtime showed an EApply body at resultm.spi:343 scheduling
                        // EUnbox and then repeating child scheduling because no replay thunk
                        // existed for the unbox node.  Register the real evaluator fail-closed.
                        // MIGRATION: also expose the scrutinee and branch children so replay
                        // can drive listm/core unboxes without black-box re-entry.
                        let bindNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box a)
                        let successNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box on_succ)
                        let failNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box on_fail)
                        registerReplayTerm bindNodeId a
                        EvalReplayValueStore.putTerm failNodeId (fun () -> term (add_trace s r) on_fail)
                        EvalReplayValueStore.putTerm successNodeId (fun () ->
                            let s = add_trace s r
                            match term s a with
                            | DNominal(DUnion(DPair(DSymbol k', payload),_),_) when k = k' ->
                                store_term s id payload
                                term s on_succ
                            | _ -> term s expr)
                        EvalReplayValueStore.putUnboxSpine nodeId {
                            bindNodeId = bindNodeId
                            bindShape = evalNodeWorkShapeIdTerm a
                            caseName = UnionTagIdOps.create k
                            binderId = id
                            successNodeId = successNodeId
                            successShape = evalNodeWorkShapeIdTerm on_succ
                            failNodeId = failNodeId
                            failShape = evalNodeWorkShapeIdTerm on_fail
                        }
                        EvalReplayValueStore.putTerm nodeId (fun () -> term s expr)
                    | EAnnot(_,inner,annotTy) ->
                        // MIGRATION: historical runtime ended with current_shape=EAnnot after a
                        // root-complete witness.  Register annotation as a real thunk so
                        // stale-root fallthrough can evaluate the ordinary term/type check.
                        let innerNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box inner)
                        let typeNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box annotTy)
                        registerReplayTerm innerNodeId inner
                        EvalReplayValueStore.putType typeNodeId (fun () -> ty s annotTy)
                        EvalReplayValueStore.putAnnotSpine nodeId {
                            innerNodeId = innerNodeId
                            innerShape = evalNodeWorkShapeIdTerm inner
                            typeNodeId = typeNodeId
                            typeShape = evalNodeWorkShapeIdTy annotTy
                        }
                        EvalReplayValueStore.putTerm nodeId (fun () -> term s expr)
                    | ENominal(_,inner,nomTy) ->
                        let innerNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box inner)
                        let typeNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box nomTy)
                        registerReplayTerm innerNodeId inner
                        EvalReplayValueStore.putType typeNodeId (fun () -> ty s nomTy)
                        EvalReplayValueStore.putNominalSpine nodeId {
                            innerNodeId = innerNodeId
                            innerShape = evalNodeWorkShapeIdTerm inner
                            typeNodeId = typeNodeId
                            typeShape = evalNodeWorkShapeIdTy nomTy
                        }
                        EvalReplayValueStore.putTerm nodeId (fun () -> term s expr)
                    | EType(_,texpr) ->
                        // MIGRATION: EType is not a term value, but EOp has legal raw-type
                        // argument forms.  Register the same node in the type store so the
                        // type-aware op bridge can consume it without scheduling term/EType.
                        // MIGRATION: historical runtime showed EOp can still resume through the generic
                        // term child path for raw EType arguments.  Expose the real typed value as
                        // Data via ty_to_data, fail-closed through the existing type evaluator.
                        EvalReplayValueStore.putType nodeId (fun () -> ty s texpr)
                        EvalReplayValueStore.putTerm nodeId (fun () -> ty_to_data s (ty s texpr))
                    | EPatternMiss scrutinee ->
                        let childNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box scrutinee)
                        registerReplayTerm childNodeId scrutinee
                        EvalReplayValueStore.putPatternMissSpine nodeId {
                            child = EvalReplayValueStore.PatternMissTermScrutinee(childNodeId, evalNodeWorkShapeIdTerm scrutinee)
                        }
                        EvalReplayValueStore.putTerm nodeId (fun () -> term s expr)
                    | ETypePatternMiss scrutineeTy ->
                        let childNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box scrutineeTy)
                        EvalReplayValueStore.putType childNodeId (fun () -> ty s scrutineeTy)
                        EvalReplayValueStore.putPatternMissSpine nodeId {
                            child = EvalReplayValueStore.PatternMissTypeScrutinee(childNodeId, evalNodeWorkShapeIdTy scrutineeTy)
                        }
                        EvalReplayValueStore.putTerm nodeId (fun () -> term s expr)
                    | EDefaultLit(_,_,_) -> ()
                    | ELet _ ->
                        // MIGRATION: conservative replay for let-spines exposed by MIGRATION.
                        // MIGRATION installed a whole-chain thunk, but the 407 runtime log showed
                        // current_shape=ELet staying partial when the canonical frontier was a
                        // type witness.  Pre-register every body/success child and read replay
                        // values first, so the let chain does not re-enter term_core merely to
                        // shuttle already-captured values across the local environment.
                        // MIGRATION: also materialize the child spine so missing bodies are scheduled
                        // explicitly.  MIGRATION ended with replay_let_body_value_missing:EApply at
                        // runtime fixture path:5 and the retry drain kept re-running the same parent let.
                        let letBodyIds = ResizeArray<int>()
                        let letBodyShapes = ResizeArray<CompilerIdentityKernel.WorkShapeId>()
                        let mutable letSuccessId = nodeId
                        let mutable letSuccessShape = CompilerIdentityKernel.WorkShapeIdOps.Known.eLet
                        let mutable letCursor = expr
                        let mutable collectingLetChildren = true
                        while collectingLetChildren do
                            match letCursor with
                            | ELet(_,_,body,on_succ) ->
                                let bodyId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box body)
                                letBodyIds.Add bodyId
                                letBodyShapes.Add (evalNodeWorkShapeIdTerm body)
                                registerReplayTerm bodyId body
                                letCursor <- on_succ
                            | other ->
                                let otherId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box other)
                                letSuccessId <- otherId
                                letSuccessShape <- evalNodeWorkShapeIdTerm other
                                if otherId <> nodeId then registerReplayTerm otherId other
                                collectingLetChildren <- false
                        EvalReplayValueStore.putLetSpine nodeId {
                            bodyNodeIds = letBodyIds.ToArray()
                            bodyShapes = letBodyShapes.ToArray()
                            successNodeId = letSuccessId
                            successShape = letSuccessShape
                        }
                        EvalReplayValueStore.putTerm nodeId (fun () ->
                            let mutable replay_s = s
                            let mutable replay_e = expr
                            let mutable replay_result = DB
                            let mutable replay_done = false
                            while not replay_done do
                                match replay_e with
                                | ELet(rr, bind, body, on_succ) ->
                                    replay_s <- add_trace replay_s rr
                                    let bodyId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box body)
                                    let bodyValue =
                                        match EvalReplayValueStore.tryTerm bodyId with
                                        | Some value -> value
                                        | None -> failwith ("replay_let_body_value_missing:" + evalNodeShapeTerm body)
                                    store_term replay_s bind bodyValue
                                    replay_e <- on_succ
                                | _ ->
                                    let replayId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box replay_e)
                                    match EvalReplayValueStore.tryTerm replayId with
                                    | Some value ->
                                        replay_result <- value
                                        replay_done <- true
                                    | None -> failwith ("replay_let_success_value_missing:" + evalNodeShapeTerm replay_e)
