                                a |> List.map (function
                                    | MText x -> CMText x
                                    | MTerm (_,is_inline) ->
                                        let idx = macroTermIx
                                        macroTermIx <- macroTermIx + 1
                                        CMTerm(cachedTerm MacroReplayCachedTerm idx |> dyn false s2, is_inline)
                                    | MType _ ->
                                        let idx = macroTypeIx
                                        macroTypeIx <- macroTypeIx + 1
                                        CMType(cachedType MacroReplayCachedType idx)
                                    | MLitType _ ->
                                        let idx = macroTypeIx
                                        macroTypeIx <- macroTypeIx + 1
