                            let resultTy =
                                match EvalReplayValueStore.tryType macroResultTypeNodeId with
                                | Some value -> value
                                | None -> failwith "macro_cached_result_type_missing"
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_macro_cached_children_used\",\"event\":\"term_thunk\",\"node_id\":%d,\"shape\":\"EMacro\",\"term_children\":%d,\"type_children\":%d,\"single_flight\":1,\"next\":\"push_typedop_macro\"}" [| box nodeId; box macroTermNodeIds.Length; box macroTypeNodeIds.Length |])
                            push_typedop_no_rewrite s2 (TyMacro(macroItems)) resultTy)
                    | ERecordWith(r,vars,withs,withouts) ->
                        let recordChildTerms =
                            [
                                yield! (vars |> List.mapi (fun i (_, child) -> EvaluatorRecordPath i, child))
                                for i, item in List.indexed withs do
                                    match item with
                                    | RSymbol(_, child) -> yield EvaluatorRecordWithSymbolValue i, child
                                    | RSymbolModify(_, child) -> yield EvaluatorRecordModifySymbolValue i, child
                                    | RVar((_, keyExpr), child) ->
                                        yield EvaluatorRecordWithVariableKey i, keyExpr
                                        yield EvaluatorRecordWithVariableValue i, child
                                    | RVarModify((_, keyExpr), child) ->
                                        yield EvaluatorRecordModifyVariableKey i, keyExpr
                                        yield EvaluatorRecordModifyVariableValue i, child
                                for i, item in List.indexed withouts do
                                    match item with
                                    | WSymbol _ -> ()
                                    | WVar(_, keyExpr) -> yield EvaluatorRecordWithoutVariableKey i, keyExpr
