                            let argNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box arg)
                            registerReplayTerm argNodeId arg
                            match arg with
                            | EV a -> EvalReplayValueStore.putTerm argNodeId (fun () -> v s a)
                            | ELit(_,lit) -> EvalReplayValueStore.putTermValue argNodeId (DLit lit)
                            | ESymbol(_,sym) -> EvalReplayValueStore.putTermValue argNodeId (DSymbol sym)
                            | EType(_,texpr) ->
                                EvalReplayValueStore.putType argNodeId (fun () -> ty s texpr)
                                EvalReplayValueStore.putTerm argNodeId (fun () -> ty_to_data s (ty s texpr))
                            | EDefaultLit(_,_,_) -> ()
                            | _ -> ()
                        let opReplayNodeIds = argArray |> Array.map (fun e -> System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box e))
                        let opReplayName = opStableText op
                        EvalReplayValueStore.putOpContext nodeId (box s)
                        EvalReplayValueStore.putApplyContext nodeId (box s)
                        // MIGRATION: RecordTypeTryFind success replay can need the
                        // same LangEnv through the type-apply bridge.  The runtime
                        // showed only type_apply_context_missing here, so install the
                        // context rather than fabricating the branch result.
                        EvalReplayValueStore.putTypeApplyContext nodeId (box s)
                        EvalReplayValueStore.putOpSpine nodeId {
                            op = op
                            argCount = argArray.Length
                            argNodeIds = opReplayNodeIds
                            argShapes = argArray |> Array.map evalNodeWorkShapeIdTerm
                        }
                        EvalReplayValueStore.putTerm nodeId (fun () ->
                            match EvalReplayValueStore.tryResolvePureOpWithContext nodeId op opReplayNodeIds with
                            | Some value -> value
                            | None ->
                                let allArgsReady =
                                    opReplayNodeIds
                                    |> Array.forall EvalReplayValueStore.tryTermReady
                                if allArgsReady then
                                    match EvalReplayValueStore.tryScheduleTypeAwareOpReplayWithContext nodeId op opReplayNodeIds with
                                    | Some (EvalReplayValueStore.TypeAwareOpResolvedInPlace reason) ->
                                        let reasonText = CompilerKernelV2.OperationalReasonIdOps.text reason
                                        match EvalReplayValueStore.tryTermDetailed nodeId with
                                        | Choice1Of2 value ->
                                            DiagJson.emit (
                                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_op_direct_thunk_type_aware_resolved_in_place\",\"node_id\":%d,\"op\":%s,\"arg_count\":%d,\"reason\":%s,\"disposition_du\":%s,\"single_flight\":1,\"next\":\"return_resolved_value_without_self_child_replay\"}" [| box nodeId; box (DiagJson.esc opReplayName); box argArray.Length; box (DiagJson.esc reasonText); box (DiagJson.esc (EvalReplayValueStore.typeAwareOpReplayScheduleDispositionText (EvalReplayValueStore.TypeAwareOpResolvedInPlace reason))) |])
                                            value
                                        | Choice2Of2 detail ->
                                            failwith (FastRuntimeFormat.format "op_type_aware_resolved_value_missing:%s/%d:%s" [| box opReplayName; box argArray.Length; box detail |])
                                    | Some (EvalReplayValueStore.TypeAwareOpScheduledChild(childNodeId, childShape, reason)) ->
                                        let reasonText = CompilerKernelV2.OperationalReasonIdOps.text reason
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_op_direct_thunk_type_aware_child_scheduled\",\"node_id\":%d,\"op\":%s,\"arg_count\":%d,\"child_node_id\":%d,\"child_shape\":%s,\"reason\":%s,\"single_flight\":1,\"next\":\"schedule_type_aware_op_child_replay\"}" [| box nodeId; box (DiagJson.esc opReplayName); box argArray.Length; box childNodeId; box (DiagJson.esc (CompilerIdentityKernel.WorkShapeIdOps.text childShape)); box (DiagJson.esc reasonText) |])
                                        failwith (FastRuntimeFormat.format "op_type_aware_child_scheduled:%s/%d:%s" [| box opReplayName; box argArray.Length; box reasonText |])
                                    | None ->
                                        failwith (sprintf "op_value_missing:%s/%d" opReplayName argArray.Length)
                                else
                                    failwith (sprintf "op_value_missing:%s/%d" opReplayName argArray.Length))
                    | EIfThenElse(_,cond,onTrue,onFalse) ->
                        let condNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box cond)
                        let trueNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box onTrue)
                        let falseNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box onFalse)
                        // Only the condition is a replay child of this scope. The branches of a runtime `if` run in scopes of
                        // their own (term_scope); registered here, with this scope as their context, the replay driver applied
                        // branch applications in the enclosing block as well (`while_control`: a `break` emitted before the
                        // `if`, on some runs, via tryApplyReplayDataWithContext). A branch cell the probe schedules without a
                        // store falls back to the direct handler, as `While`/`Do`/`Indent` arguments do.
                        // The condition too, unless it is an atom: this registration walks ahead of evaluation, and a
                        // condition that emits code (an array read) replayed from here landed before the statements
                        // preceding the `if` (`set a 0 13` then `if index a 0 = 13`: the read came before the set).
                        if isReplayAtomCondition cond then registerReplayTerm condNodeId cond
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_if_branch_children_registered\",\"event\":\"term_entry_global_fuse\",\"node_id\":%d,\"shape\":\"EIfThenElse\",\"site\":%s,\"condition_node_id\":%d,\"true_node_id\":%d,\"true_shape\":%s,\"false_node_id\":%d,\"false_shape\":%s,\"single_flight\":1,\"next\":\"if_children_ready_for_branch_probe\"}" [| box nodeId; box (DiagJson.esc site); box condNodeId; box trueNodeId; box (DiagJson.esc (evalNodeShapeTerm onTrue)); box falseNodeId; box (DiagJson.esc (evalNodeShapeTerm onFalse)) |])
                        match cond with
                        | EV a -> EvalReplayValueStore.putTerm condNodeId (fun () -> v s a)
                        | ELit(_,lit) -> EvalReplayValueStore.putTermValue condNodeId (DLit lit)
                        | ESymbol(_,sym) -> EvalReplayValueStore.putTermValue condNodeId (DSymbol sym)
                        | _ -> ()
                        match onTrue with
                        | EV a -> EvalReplayValueStore.putTerm trueNodeId (fun () -> v s a)
                        | ELit(_,lit) -> EvalReplayValueStore.putTermValue trueNodeId (DLit lit)
                        | ESymbol(_,sym) -> EvalReplayValueStore.putTermValue trueNodeId (DSymbol sym)
                        | _ -> ()
                        match onFalse with
                        | EV a -> EvalReplayValueStore.putTerm falseNodeId (fun () -> v s a)
                        | ELit(_,lit) -> EvalReplayValueStore.putTermValue falseNodeId (DLit lit)
                        | ESymbol(_,sym) -> EvalReplayValueStore.putTermValue falseNodeId (DSymbol sym)
                        | _ -> ()
                        EvalReplayValueStore.putIfThenElse nodeId {
                            condNodeId = condNodeId
                            condShape = evalNodeWorkShapeIdTerm cond
                            trueNodeId = trueNodeId
                            trueShape = evalNodeWorkShapeIdTerm onTrue
                            falseNodeId = falseNodeId
                            falseShape = evalNodeWorkShapeIdTerm onFalse
                        }
                    | EApply _ ->
                        let args = ResizeArray<E>()
                        let mutable cur = expr
                        let mutable running = true
                        while running do
                            match cur with
                            | EApply(_, a, b) ->
                                args.Add b
                                cur <- a
                            | _ -> running <- false
                        let headNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box cur)
                        registerReplayTerm headNodeId cur
                        match cur with
                        | EB _ -> EvalReplayValueStore.putTermValue headNodeId DB
                        | EV a -> EvalReplayValueStore.putTerm headNodeId (fun () -> v s a)
                        | ELit(_,lit) -> EvalReplayValueStore.putTermValue headNodeId (DLit lit)
                        | ESymbol(_,sym) -> EvalReplayValueStore.putTermValue headNodeId (DSymbol sym)
                        | EFun'(_,freeVars,i,body,annot) ->
                            EvalReplayValueStore.putTerm headNodeId (fun () ->
                                if freeVars.term.free_vars.Length <> i then failwith "Replay apply-head function free-var arity mismatch."
                                DFunction(body, annot, HopacExtensions.S.map (v s) freeVars.term.free_vars, HopacExtensions.S.map (vt s) freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                        | ERecursiveFun'(_,freeVars,i,body,annot) ->
                            EvalReplayValueStore.putTerm headNodeId (fun () ->
                                if freeVars.term.free_vars.Length <> i then failwith "Replay apply-head recursive function free-var arity mismatch."
                                DFunction(body.Value, annot, HopacExtensions.S.map (v s) freeVars.term.free_vars, HopacExtensions.S.map (vt s) freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                        | EForall'(_,freeVars,i,body) ->
                            EvalReplayValueStore.putTerm headNodeId (fun () ->
                                if freeVars.ty.free_vars.Length <> i then failwith "Replay apply-head forall free-var arity mismatch."
                                DForall(body, HopacExtensions.S.map (v s) freeVars.term.free_vars, HopacExtensions.S.map (vt s) freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                        | ERecursiveForall'(_,freeVars,i,body) ->
                            EvalReplayValueStore.putTerm headNodeId (fun () ->
                                if freeVars.ty.free_vars.Length <> i then failwith "Replay apply-head recursive forall free-var arity mismatch."
                                DForall(body.Value, HopacExtensions.S.map (v s) freeVars.term.free_vars, HopacExtensions.S.map (vt s) freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                        | _ -> ()
                        for arg in args do
                            let argNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box arg)
                            registerReplayTerm argNodeId arg
                            match arg with
                            | EB _ -> EvalReplayValueStore.putTermValue argNodeId DB
                            | EV a -> EvalReplayValueStore.putTerm argNodeId (fun () -> v s a)
                            | ELit(_,lit) -> EvalReplayValueStore.putTermValue argNodeId (DLit lit)
                            | ESymbol(_,sym) -> EvalReplayValueStore.putTermValue argNodeId (DSymbol sym)
                            | _ -> ()
                        let replayArgs = args.ToArray()
                        EvalReplayValueStore.putApplySpine nodeId {
                            headNodeId = headNodeId
                            headShape = evalNodeWorkShapeIdTerm cur
                            argCount = replayArgs.Length
                            argNodeIds = Array.rev replayArgs |> Array.map (fun e -> System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box e))
                            argShapes = Array.rev replayArgs |> Array.map evalNodeWorkShapeIdTerm
                        }
                        EvalReplayValueStore.putApplyContext nodeId (box s)
                        // MIGRATION: register a whole-spine thunk without lexically capturing apply.
                        // The real apply function is installed later through EvalReplayValueStore after
                        // its definition.  Until then this thunk fails closed under tryTerm.
                        EvalReplayValueStore.putTerm nodeId (fun () ->
                            // Re-applying runs the application's effects again; only replay what the direct
                            // evaluator neither runs now nor has run (fails closed, like a missing apply).
                            // Also refuse while a direct evaluation is building the block this application would emit
                            // into: the node check alone raced with the direct evaluator under load and duplicated the
                            // call (FRONTIER.md fix 41).
                            if EvalReplayValueStore.isDirectNodeOwned nodeId || EvalReplayValueStore.isDirectScopeOwned (box s.seq) then
                                failwith "replay_apply_spine_owned_by_direct_evaluation"
