                                current)
                    | _ -> ()
                let fuseVisitKind, _, _, _, _, _, _ = TermCycleFuse.describe()
                let activeFuseDomain = evalFuseDomainOfVisitKind fuseVisitKind
                let activeFuseKind = evalFuseDomainText activeFuseDomain
                if activeFuseDomain <> EvalFuseTermDomain then
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_kind_local_active_reset\",\"event\":\"term_entry_global_fuse\",\"active_kind\":%s,\"requested_kind\":\"term\",\"single_flight\":1,\"next\":\"continue_term_eval\"}"
                            (DiagJson.esc activeFuseKind))
                    EvalWorklist.parkActiveAndSelectKind EvalWorklist.EvalTerm |> ignore
                    TermCycleFuse.reset()
                else
                    match BigStack.tryRun s.bigStack BigStack.BigStackRegisterReplayTermGlobalFuse "register_replay_term_global_fuse" (fun childContext -> registerReplayTermWithContext childContext nodeId0 x) with
                    | Some () -> ()
                    | None ->
                        raise_type_error s (
                            sprintf "%s: replay registration refused after BigStack exhaustion site=%s"
                                DiagnosticClassifier.EJP0010
                                site)
                    EvalWorklist.ensureCapturedForKindId EvalWorklist.ReplayFrontierTerm (CompilerKernelV2.OperationalReasonIdOps.create "term_entry_global_fuse") |> ignore
                    EvalWorklist.attachSemanticCell EvalWorklist.ReplayTickEventTermEntry (semanticCellForTerm nodeId0)
                    let frameOpt = EvalWorklist.ensureCapturedAndRunId (CompilerKernelV2.OperationalReasonIdOps.create "term_entry_global_fuse") EvalWorklist.ReplayTickEventTermEntry 32
                    let globalReplayComplete =
                        match frameOpt with
                        | Some frame when EvalWorklist.frameReplayCompleteKindId EvalWorklist.EvalTerm frame -> true
                        | Some _ -> EvalWorklist.hasReplayCompleteKind EvalWorklist.EvalTerm
                        | None -> EvalWorklist.hasReplayCompleteKind EvalWorklist.EvalTerm
                    if globalReplayComplete then
                        let _, k0, s0, d0, g0, re0, max0 = TermCycleFuse.describe()
                        let replayReturnMsg =
                            FastRuntimeFormat.format "%s: global term replay return suppressed after pinned terminal first_key=%s first_site=%s first_depth=%d gen=%d re=%d/%d" [| box DiagnosticClassifier.EJP0011; box k0; box s0; box d0; box g0; box re0; box max0 |]
                        match EvalWorklist.trySuppressGlobalFuseReplayReturnForPinnedTerminal "term_entry_global_fuse" EvalWorklist.EvalTerm (CompilerIdentityKernel.WorkShapeIdOps.create termShape0) replayReturnMsg with
                        | Some msg -> raise_type_error s msg
                        | None ->
                            match EvalReplayValueStore.tryTerm nodeId0 with
                            | Some value ->
                                // MIGRATION: global-fuse term replay returns may repeat while the
                                // drain is alive. Refresh JP progress so EJP0030 does not treat
                                // semantic_root_complete source returns as an idle scheduler.
                                EvalReplayValueStore.putTermSourceValue termSourceKey0 value
                                let semanticAuthorityKey =
