                                    DiagJson.emit (
                                        sprintf "{\"kind\":\"eval_worklist_root_complete_replay_progress_marked\",\"event\":\"term_entry_global_fuse\",\"scope\":\"global_fuse_term_return\",\"status\":\"semantic_root_complete\",\"kind2\":\"term\",\"shape\":%s,\"repeat_count\":%d,\"single_flight\":1,\"next\":\"watchdog_progress_refreshed\"}"
                                            (DiagJson.esc termShape0) sourceStoreRepeat)
                                    DiagJson.emit (
                                        sprintf "{\"kind\":\"eval_worklist_global_fuse_term_replay_return\",\"event\":\"term_entry_global_fuse\",\"status\":\"semantic_root_complete\",\"shape\":%s,\"repeat_count\":%d,\"single_flight\":1,\"next\":\"return_term_value\"}"
                                            (DiagJson.esc termShape0) sourceStoreRepeat)
                                    DiagJson.emit (
                                        sprintf "{\"kind\":\"eval_worklist_fuse_clear_after_replay_return\",\"event\":\"term_entry_global_fuse\",\"status\":\"semantic_root_complete\",\"shape\":%s,\"repeat_count\":%d,\"single_flight\":1,\"next\":\"return_term_value\"}"
                                            (DiagJson.esc termShape0) sourceStoreRepeat)
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_source_value_stored\",\"event\":\"term_entry_global_fuse\",\"status\":\"semantic_root_complete\",\"shape\":%s,\"source_key\":%s,\"repeat_count\":%d,\"single_flight\":1,\"next\":\"return_term_value\"}" [| box (DiagJson.esc termShape0); box (DiagJson.esc (EvalReplayValueStore.semanticSourceKeyText termSourceKey0)); box sourceStoreRepeat |])
                                if sourceStoreRepeat = 1 then
                                    let semanticAuthorityAdmission =
                                        DiagJson.noteTerminalSemanticAuthorityDeltaForCanonicalRoot 1
                                    let semanticFactAdmitted =
                                        DiagJson.noteSemanticFactExactOnce semanticAuthorityKey 1L 1L
                                    if semanticFactAdmitted then
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_semantic_fact_exact_once\",\"fact_kind_du\":\"TermGlobalFuseValue\",\"node_id\":%d,\"shape\":%s,\"source_key\":%s,\"semantic_authority_key\":%s,\"exact_once_ref\":%u,\"single_flight\":1,\"authority\":\"canonical_source_cell_identity_without_trace_or_runtime_node\"}" [| box nodeId0; box (DiagJson.esc termShape0); box (DiagJson.esc (EvalReplayValueStore.semanticSourceKeyText termSourceKey0)); box (DiagJson.esc semanticAuthorityKey); box (DiagJson.semanticFactStableRef "eval-semantic-fact" semanticAuthorityKey) |])
                                        match semanticAuthorityAdmission with
