                                let partialCurrentRepeatCap = 32
                                if partialCurrentRepeat > partialCurrentRepeatCap then
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_global_fuse_root_witness_partial_current_repeat_blocked\",\"event\":\"term_entry_global_fuse\",\"status\":\"semantic_global_fuse_root_witness_partial_current_blocked\",\"shape\":%s,\"first_key\":%s,\"first_site\":%s,\"first_depth\":%d,\"pending\":%d,\"recovery\":%s,\"repeat\":%d,\"cap\":%d,%s,\"single_flight\":1,\"next\":\"typed_terminal_after_bounded_global_fuse_partial_current_repeat\"}" [| box (DiagJson.esc termShape0); box (DiagJson.esc k0); box (DiagJson.esc s0); box d0; box (EvalWorklist.pendingCount()); box (DiagJson.esc recoveryPolicy); box partialCurrentRepeat; box partialCurrentRepeatCap; box (EvalWorklist.globalFuseTraceJson()) |])
                                    EvalWorklist.parkActiveAndSelectKind EvalWorklist.EvalTerm |> ignore
                                    TermCycleFuse.reset ()
                                    raise_type_error s (FastRuntimeFormat.format "%s: global term-cycle fuse kept a root-complete witness while current term stayed partial after %d/%d deferrals first_key=%s first_site=%s first_depth=%d current_shape=%s recovery=%s" [| box DiagnosticClassifier.EJP0011; box partialCurrentRepeat; box partialCurrentRepeatCap; box k0; box s0; box d0; box termShape0; box recoveryPolicy |])
