                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_global_fuse_root_witness_partial_current_deferred\",\"event\":\"term_entry_global_fuse\",\"status\":\"semantic_step_partial\",\"shape\":%s,\"first_key\":%s,\"first_site\":%s,\"first_depth\":%d,\"pending\":%d,\"recovery\":%s,\"repeat\":%d,\"cap\":%d,%s,\"single_flight\":1,\"next\":\"fallthrough_term_eval\"}" [| box (DiagJson.esc termShape0); box (DiagJson.esc k0); box (DiagJson.esc s0); box d0; box (EvalWorklist.pendingCount()); box (DiagJson.esc recoveryPolicy); box partialCurrentRepeat; box partialCurrentRepeatCap; box (EvalWorklist.globalFuseTraceJson()) |])
