                            else
                                raise_type_error s (FastRuntimeFormat.format "%s: global term-cycle fuse has a root-complete witness but current term value is still partial first_key=%s first_site=%s first_depth=%d gen=%d re=%d/%d current_shape=%s" [| box DiagnosticClassifier.EJP0011; box k0; box s0; box d0; box g0; box re0; box max0; box (evalNodeShapeTerm x) |])
                    else
