                                let orphanRepeat = jp_note_global_fuse_partial_current orphanKey
                                let orphanCap = 96
                                if orphanRepeat > orphanCap then
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_orphan_global_fuse_live_replay_repeat_blocked\",\"event\":\"term_entry_global_fuse\",\"status\":\"semantic_orphan_global_fuse_repeat_blocked\",\"shape\":%s,\"site\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"payload_status\":%s,\"repeat\":%d,\"cap\":%d,%s,\"single_flight\":1,\"next\":\"typed_terminal_after_bounded_orphan_global_fuse_replay\"}" [| box (DiagJson.esc (evalNodeShapeTerm x)); box (DiagJson.esc site); box (EvalWorklist.pendingCount()); box (EvalWorklist.replayQueueDepth()); box (EvalWorklist.replayDriverActiveDepthValue()); box (DiagJson.esc (EvalWorklist.semanticPayloadStatus())); box orphanRepeat; box orphanCap; box (EvalWorklist.globalFuseTraceJson()) |])
