                                    raise_type_error s msg
                                else
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_orphan_global_fuse_live_replay_deferred\",\"event\":\"term_entry_global_fuse\",\"status\":\"semantic_step_partial\",\"shape\":%s,\"site\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"payload_status\":%s,\"repeat\":%d,\"cap\":%d,%s%s,\"policy\":\"orphan_term_global_fuse_live_replay_has_native_callback_closure_before_fallthrough\",\"single_flight\":1,\"next\":\"native_inline_term_global_fuse_orphan_callback\"}" [| box (DiagJson.esc (evalNodeShapeTerm x)); box (DiagJson.esc site); box (EvalWorklist.pendingCount()); box (EvalWorklist.replayQueueDepth()); box (EvalWorklist.replayDriverActiveDepthValue()); box (DiagJson.esc (EvalWorklist.semanticPayloadStatus())); box orphanRepeat; box orphanCap; box (EvalWorklist.globalFuseTraceJson()); box (EvalWorklist.pendingGraphProofTupleJsonFields (EvalWorklist.proofTupleForTyGlobalFuseParentContinuation (FastRuntimeFormat.format "term_orphan_global_fuse_live_replay_defer|%s|%s|repeat:%d/%d" [| box (evalNodeShapeTerm x); box site; box orphanRepeat; box orphanCap |]))) |])
                                    EvalWorklist.parkActiveAndSelectKind EvalWorklist.EvalTerm |> ignore
                                    TermCycleFuse.reset()
                            else
                                let keyedParentContinuationFuseWithRunnableReplay =
