                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_tfun_body_tv_binder_snapshot\",\"event\":\"type_apply_arg_register\",\"parent_node_id\":%d,\"child_node_id\":%d,\"role\":\"type_apply_arg_tfun_body_immediate_binder\",\"index\":%d,\"global_len\":%d,\"stack_len\":%d,\"arg_node_id\":%d,\"site\":%s,\"single_flight\":1,\"next\":\"type_value_materialized_from_arg_binder\"}" [| box replayNodeId; box bodyNodeId; box i; box globalTypeLen; box stackTypeLen; box argNodeId; box (DiagJson.esc site) |])
