                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_apply_arg_tv_env_snapshot\",\"event\":\"type_apply_register\",\"scope\":\"post_fuse\",\"node_id\":%d,\"index\":%d,\"env\":\"stack\",\"global_len\":%d,\"stack_len\":%d,\"single_flight\":1,\"next\":\"type_value_materialized\"}" [| box typeNodeId; box i; box globalTypeLen; box stackTypeLen |])
