                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_apply_spine_post_fuse_recursive_children_registered\",\"event\":\"term_entry_post_fuse\",\"node_id\":%d,\"shape\":\"EApply\",\"site\":%s,\"head_node_id\":%d,\"head_shape\":%s,\"arg_count\":%d,\"single_flight\":1,\"next\":\"apply_children_ready_for_replay\"}" [| box nodeId; box (DiagJson.esc site); box headNodeId; box (DiagJson.esc (evalNodeShapeTerm cur)); box replayArgs.Length |])
                    // MIGRATION: direct term-cycle replay must carry the same LangEnv handle
                    // as term-entry capture.  MIGRATION proved VarIs/1 root completion, then
                    // attempt 2 reached EApply at listm.spi:13 and failed solely because the
                    // parent node had no apply context.  Store it here before the whole-spine
                    // thunk so late-bound DFunction body replay can enter the real apply path.
                    EvalReplayValueStore.putApplyContext nodeId (box s)
                    // MIGRATION: register a whole-spine thunk without lexically capturing apply.
                    // The real apply function is installed later through EvalReplayValueStore after
                    // its definition.  Until then this thunk fails closed under tryTerm.
                    EvalReplayValueStore.putTerm nodeId (fun () ->
                        // Re-applying runs the application's effects again; only replay what the direct
                        // evaluator neither runs now nor has run (fails closed, like a missing apply).
                        // Also refuse while the target block is being built directly (fix 41).
                        if EvalReplayValueStore.isDirectNodeOwned nodeId || EvalReplayValueStore.isDirectScopeOwned (box s.seq) then
                            failwith "replay_apply_spine_owned_by_direct_evaluation"
                        match EvalReplayValueStore.tryReplayAppliedValueIn nodeId (box s) with
                        | Some value -> value
                        | None ->
                            // As above: simple heads/arguments from this evaluation's environment (fix 34).
                            let ownValue (e: E) =
                                match e with
                                | EB _ -> Some DB
                                | EV a -> Some (v s a)
                                | ELit(_,lit) -> Some (DLit lit)
                                | ESymbol(_,sym) -> Some (DSymbol sym)
                                | _ -> None
                            let mutable current =
                                match ownValue cur with
                                | Some value -> value
                                | None ->
                                match EvalReplayValueStore.tryTerm headNodeId with
                                | Some value -> value
                                | None -> term s cur
