                                    | Some value -> value
                                    | None -> term s arg
                                current <- EvalReplayValueStore.runApplyAfterDefinition (box s) current argValue
                            EvalReplayValueStore.rememberReplayAppliedValueIn nodeId (box s) current
                            current)
                | _ -> ()
            match BigStack.tryRun s.bigStack BigStack.BigStackRegisterReplayTermNormal "register_replay_term_normal" (fun childContext -> registerReplayTermWithContext childContext nodeId x) with
            | Some () -> ()
            | None ->
                raise_type_error s (
                    sprintf "%s: replay registration refused after BigStack exhaustion site=%s"
                        DiagnosticClassifier.EJP0010
                        site)
            let nextEvalNodePath, reCount = EvalCycleGuard.enter s.evalNodePath nodeObj
            let (a0,b0) = r0.range
            let nodeKey = System.String.Concat(r0.path, ":", a0.line.ToString(), ":", a0.character.ToString(), "-", b0.line.ToString() + ":" + b0.character.ToString())
            let nextEvalKeyPath, reKey = EvalStackDepthGuard.enter s.evalKeyPath nodeKey
            let s = {
                s with
                    evalNodePath = nextEvalNodePath
                    evalKeyPath = nextEvalKeyPath
            }

    

            // Re-entrancy limits: keep them bounded so real cycles fail fast (and avoid multi-minute JP stalls).
            let invNow = CacheGeneration.invalidationCount()
            let seqNow = CacheGeneration.isSequentialRequested()
            let max_reentry_base = EvalFallbackPolicy.maxReentry seqNow invNow depth
            let max_reentry = max_reentry_base // generic/326: no BigStack multiplier; forced sequential gets a centralized legacy budget
            let max_reentry_key = max_reentry
            let warn_reentry = EvalFallbackPolicy.warnReentry max_reentry_base
    

            let hashSnapShort () =
                EvalCycleGuard.snapshotHashes 12 s.evalNodePath |> Seq.map string |> String.concat ","
            let keySnapShort () =
                EvalStackDepthGuard.snapshotKeys 12 s.evalKeyPath |> String.concat " | "
            if reCount > 1 then
                if reCount = 2 then
                    DiagSidecar.emit (FastRuntimeFormat.format "[spiral_compiler] EJP0011W term re-entry (non-fatal): nodeId=%d depth=%d site=%s" [| box nodeId; box depth; box site |])
                if reCount = warn_reentry then
                    let hs = hashSnapShort ()
                    let ks = keySnapShort ()
                    DiagSidecar.emit (FastRuntimeFormat.format "[spiral_compiler] EJP0011W term re-entry hot: re=%d/%d nodeId=%d depth=%d site=%s hs=[%s] ks=[%s]" [| box reCount; box max_reentry; box nodeId; box depth; box site; box hs; box ks |])
                    CacheGeneration.requestSequential ()
