                            EvalWorklist.ensureCapturedForKindId EvalWorklist.ReplayFrontierTerm (CompilerKernelV2.OperationalReasonIdOps.create "direct_term_cycle_node") |> ignore
                            EvalWorklist.attachSemanticCell EvalWorklist.ReplayTickEventTermCycle (semanticCellForTerm nodeId)
                            EvalWorklist.ensureCapturedAndRunId (CompilerKernelV2.OperationalReasonIdOps.create "direct_term_cycle_node") EvalWorklist.ReplayTickEventTermCycle 32
                        else None
                    let errEnv = if depth > 256 then s else (add_trace s r0)
                    let msg = FastRuntimeFormat.format "%s: re-entrant term evaluation cycle detected at %s (nodeId=%d depth=%d gen=%d re=%d/%d big=%b)" [| box DiagnosticClassifier.EJP0011; box site; box nodeId; box depth; box newGen; box reCount; box max_reentry; box big |]
                    let msg = match frameOpt with Some frame -> EvalWorklist.requiredMessage msg frame | None -> msg
                    let msg =
                        msg + "\n"
                        + RunawayUnrollDiagnostic.render
                            "EJP0011"
                            (sprintf "partial evaluation re-entered `%s` more than %d times" site max_reentry)
                            (s.trace |> List.map (fun (r: Range) -> r.path, (fst r.range).line, (fst r.range).character))
                            "the re-entry limit (EvalFallbackPolicy.maxReentry) is not configurable: a deliberately deep recursion over static data should be a join point too"
                    if depth > 256 then
                        raise_type_error_no_trace errEnv msg
                    else
                        raise_type_error errEnv msg
            if reKey > 1 then
                if reKey = 2 then
                    DiagSidecar.emitKeyedSample (sprintf "[spiral_compiler] EJP0011W|term|%s" nodeKey) (FastRuntimeFormat.format "[spiral_compiler] EJP0011W term re-entry (key, non-fatal): key=%s depth=%d site=%s" [| box nodeKey; box depth; box site |])
                    // Mirror the typed prefetch for term keyed warnings.  This is only
                    // enabled after forced-sequential fallback and only seeds a replayable frontier;
                    // it does not treat the warning itself as semantic completion.
                    if CacheGeneration.isSequentialRequested() && depth >= 8 && not (TermCycleFuse.isTripped()) && not (PevalStallProbe.recoveryActive ()) then
                        try
                            let genNow = int (CacheGeneration.current())
                            let termSemanticCell = semanticCellForTerm nodeId
                            let termCellRevision = EvalWorklist.replayCellRevisionText termSemanticCell
                            let termVisitAdmission = TermCycleFuse.observePrefetchVisitWithTrace EvalVisitTerm nodeKey site depth genNow termCellRevision (termCycleFuseTraceOf s.trace)
                            let termVisitCount, termVisitBudget =
                                match termVisitAdmission with
                                | EvalVisitAdmitted(count, budget, _, _) -> count, budget
                                | EvalVisitProductiveRepeat(count, budget, _, _, _) -> count, budget
                                | EvalVisitBudgetExhausted(count, budget, streak, ageMs) -> raise (EvalVisitBudgetFailure(EvalVisitTerm, nodeKey, site, count, budget, streak, ageMs))
                            let termVisitBucket = TermCycleFuse.visitLog2Bucket termVisitCount
                            EvalWorklist.ensureCapturedForKindId EvalWorklist.ReplayFrontierTerm (CompilerKernelV2.OperationalReasonIdOps.create "sidecar_term_reentry_prefetch") |> ignore
                            EvalWorklist.attachSemanticCell EvalWorklist.ReplayTickEventTermReentryPrefetch termSemanticCell
                            let termPrefetchBudget = if depth >= 256 then 4 else 48
                            if termPrefetchBudget < 48 then
                                let occurrenceCount, shouldEmit =
                                    DiagJson.sparseLogDecision ("term_reentry_depth_backpressure|" + nodeKey) 0L
                                if shouldEmit then
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_reentry_prefetch_depth_backpressure\",\"event\":\"term_reentry\",\"key\":%s,\"site\":%s,\"depth\":%d,\"visit_count\":%d,\"full_budget\":48,\"bounded_budget\":%d,\"occurrence_count\":%d,\"authority\":\"host_stack_depth_bounded_prefetch\",\"next\":\"run_small_prefetch_then_return_to_outer_trampoline\"}" [| box (DiagJson.esc nodeKey); box (DiagJson.esc site); box depth; box termVisitCount; box termPrefetchBudget; box occurrenceCount |])
                            let frameOpt = EvalWorklist.ensureCapturedAndRunId (CompilerKernelV2.OperationalReasonIdOps.create "sidecar_term_reentry_prefetch") EvalWorklist.ReplayTickEventTermReentryPrefetch termPrefetchBudget
                            let preflightKindId = EvalWorklist.EvalTerm
                            let preflightOutcome = EvalWorklist.sidecarPrefetchOutcomeForFrame frameOpt
                            let preflightStatusId = match frameOpt with Some frame -> EvalWorklist.frameSemanticStatusId frame | None -> EvalReplayValueStore.SemanticMissingAfterPrefetchBlocked
                            let preflightCursor = match frameOpt with Some frame -> frame.cursor | None -> -1
                            if preflightOutcome = EvalWorklist.SidecarPrefetchMissingAfterPrefetch then
                                EvalWorklist.pinSemanticTerminalContractId
                                    "sidecar_term_reentry_prefetch_missing_after_prefetch"
                                    preflightKindId
                                    preflightStatusId
                                    nodeKey
                                    site
                                    depth
                                    reKey
                                    max_reentry_key
                                    (CompilerKernelV2.OperationalReasonIdOps.create (FastRuntimeFormat.format "%s:missing_node_id=%d:missing_key=%s:missing_site=%s:terminal_payload_outranks_qap" [| box (EvalWorklist.sidecarPrefetchTerminalReasonText EvalWorklist.SidecarTermReentryPrefetchMissingAfterPrefetch); box nodeId; box nodeKey; box site |]))
                                try EvalWorklist.forceReplayDriverDrainPassForTerminalAuthority EvalWorklist.ForcedDrainObservedPinnedTerminalContract "term_reentry_prefetch_terminal_payload_outranks_qap" (CompilerKernelV2.OperationalReasonIdOps.create (FastRuntimeFormat.format "term_reentry_prefetch_terminal_payload_outranks_qap:%s:depth=%d:re=%d" [| box nodeKey; box depth; box reKey |])) 4 |> ignore with _ -> ()
                                let termReentryProofKey = FastRuntimeFormat.format "term_reentry_prefetch|%s|depth:%d|re:%d" [| box nodeKey; box depth; box reKey |]
                                let termReentryProofTuple = EvalWorklist.proofTupleForReentryPrefetchTerminalDriver termReentryProofKey
                                let termReentryGraphSnapshotRef, termReentryGraphSnapshotFirst =
                                    EvalWorklist.tryCommitPendingGraphProofTupleSnapshot termReentryProofTuple
                                let termReentryPayloadOccurrence, termReentryPayloadEmit =
