                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_reentry_graph_snapshot\",\"event\":\"term_reentry\",\"graph_snapshot_ref\":%s,\"snapshot_scope_du\":\"StructuralProofTuplePerBuildGeneration\",\"generation\":%d,\"graph_snapshot_du\":%s,\"full_node_payload_embedded\":false,\"authority\":\"single_structural_graph_snapshot_then_reference\"}" [| box (DiagJson.esc termReentryGraphSnapshotRef); box (CacheGeneration.current()); box (DiagJson.esc (EvalWorklist.pendingGraphProofTupleStructuralSnapshotText termReentryProofTuple)) |])
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_term_reentry_prefetch_terminal_payload_outranks_qap\",\"event\":\"term_reentry\",\"key\":%s,\"site\":%s,\"depth\":%d,\"stack_reentry_depth\":%d,\"visit_count\":%d,\"visit_log2_bucket\":%d,\"visit_budget\":%d,\"guard_scope_du\":\"process_wide_generation_visit_ledger\",\"graph_snapshot_ref\":%s,\"node_proof_ref\":%s,\"occurrence_count\":%d,\"sparse_policy\":\"key_first_only_terminal_transition\",\"pending_graph_authority_rank_du\":\"materialized_terminal_beats_physical_qap\",\"localized_driver_route_du\":\"term_reentry_prefetch_terminal_driver\",\"single_flight\":1,\"next\":\"run_reentry_prefetch_terminal_driver_immediately\"}" [| box (DiagJson.esc nodeKey); box (DiagJson.esc site); box depth; box reKey; box termVisitCount; box termVisitBucket; box termVisitBudget; box (DiagJson.esc termReentryGraphSnapshotRef); box (DiagJson.esc termReentryProofKey); box termReentryPayloadOccurrence |])
                            let preflightComplete =
                                match frameOpt with
                                | Some frame when EvalWorklist.frameReplayCompleteKindId EvalWorklist.EvalTerm frame -> true
                                | Some _ -> EvalWorklist.hasReplayCompleteKind EvalWorklist.EvalTerm
                                | None -> EvalWorklist.hasReplayCompleteKind EvalWorklist.EvalTerm
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_term_reentry_prefetch_replay_drained\",\"event\":\"term_reentry\",\"key\":%s,\"site\":%s,\"depth\":%d,\"re\":%d,\"max_re\":%d,\"outcome_du\":%s,\"status\":%s,\"cursor\":%d,\"replayCompleteNow\":%b,\"single_flight\":1,\"next\":\"return_or_continue_term_replay\"}" [| box (DiagJson.esc nodeKey); box (DiagJson.esc site); box depth; box reKey; box max_reentry_key; box (DiagJson.esc (EvalWorklist.sidecarPrefetchOutcomeText preflightOutcome)); box (DiagJson.esc (EvalWorklist.semanticStatusToString preflightStatusId)); box preflightCursor; box preflightComplete |])
                            if preflightComplete then
                                match EvalReplayValueStore.tryTerm nodeId with
                                | Some value ->
                                    let directReplayAuthorityKey =
                                        sprintf "direct_term_replay_return|node=%d|shape=%s" nodeId termShape0
                                    let directReplayRepeat = jp_note_source_value_store directReplayAuthorityKey
                                    if directReplayRepeat = 1 then
                                        jp_progress_clock_mark peval_sw.ElapsedMilliseconds
                                    if jp_should_emit_source_value_store directReplayRepeat then
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_root_complete_replay_progress_marked\",\"event\":\"sidecar_term_reentry_prefetch\",\"scope\":\"direct_term_replay_return\",\"status\":\"semantic_root_complete\",\"kind2\":\"term\",\"shape\":%s,\"repeat_count\":%d,\"watchdog_progress_authorized\":%b,\"single_flight\":1,\"next\":%s}" [| box (DiagJson.esc termShape0); box directReplayRepeat; box (directReplayRepeat = 1); box (DiagJson.esc (if directReplayRepeat = 1 then "watchdog_progress_refreshed_once" else "return_cached_value_without_watchdog_refresh")) |])
                                    DiagJson.emit (
                                        sprintf "{\"kind\":\"eval_worklist_direct_term_reentry_replay_return\",\"event\":\"term_reentry\",\"status\":\"semantic_root_complete\",\"shape\":%s,\"single_flight\":1,\"next\":\"return_term_value\"}"
                                            (DiagJson.esc termShape0))
                                    TermCycleFuse.reset ()
