                                | None -> ()
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_sidecar_prefetch\",\"event\":\"term_reentry\",\"key\":%s,\"site\":%s,\"depth\":%d,\"re\":%d,\"max_re\":%d,\"single_flight\":1,\"next\":\"jp_stall_preflight_drained\"}" [| box (DiagJson.esc nodeKey); box (DiagJson.esc site); box depth; box reKey; box max_reentry_key |])
                        with
                        | EvalReplayTermReturn value -> raise (EvalReplayTermReturn value)
                        | EvalVisitBudgetFailure _ as error -> raise error
                        | _ -> ()
                if reKey = warn_reentry then
                    let hs = hashSnapShort ()
                    let ks = keySnapShort ()
                    DiagSidecar.emitKeyedSample (sprintf "[spiral_compiler] EJP0011W|term_hot|%s" nodeKey) (FastRuntimeFormat.format "[spiral_compiler] EJP0011W term re-entry hot(key): re=%d/%d key=%s depth=%d site=%s hs=[%s] ks=[%s]" [| box reKey; box max_reentry_key; box nodeKey; box depth; box site; box hs; box ks |])
                    CacheGeneration.requestSequential ()
                if reKey > max_reentry_key then
                    let hs = hashSnapShort ()
                    let ks = keySnapShort ()
                    let big = BigStack.isActive s.bigStack
                    CacheGeneration.requestSequential ()
                    let newGen = int (CacheGeneration.current())
                    // MIGRATION: keyed EJP0011 is also non-retryable. Keep the current generation
                    // so the caller gets one deterministic typed failure instead of retry churn.
                    DiagSidecar.emit (FastRuntimeFormat.format "%s term cycle(key,no_invalidate): key=%s depth=%d site=%s gen=%d re=%d/%d big=%b hs=[%s] ks=[%s]" [| box DiagnosticClassifier.EJP0011; box nodeKey; box depth; box site; box newGen; box reKey; box max_reentry_key; box big; box hs; box ks |])
                    let tc_count = TermCycleWatchdog.note nodeKey (int newGen)
                    let tc_panic = big || tc_count >= 2
                    let frameOpt =
                        if tc_panic then
                            DiagSidecar.emit (FastRuntimeFormat.format "%s term cycle watchdog: PANIC key=%s gen=%d count=%d" [| box DiagnosticClassifier.EJP0011; box nodeKey; box (int newGen); box tc_count |])
                            TermCycleFuse.tripWithTrace EvalVisitTerm nodeKey site depth (int newGen) reKey max_reentry_key (termCycleFuseTraceOf s.trace)
                            EvalWorklist.ensureCapturedForKindId EvalWorklist.ReplayFrontierTerm (CompilerKernelV2.OperationalReasonIdOps.create "direct_term_cycle_key") |> ignore
                            EvalWorklist.attachSemanticCell EvalWorklist.ReplayTickEventTermCycle (semanticCellForTerm nodeId)
                            EvalWorklist.ensureCapturedAndRunId (CompilerKernelV2.OperationalReasonIdOps.create "direct_term_cycle_key") EvalWorklist.ReplayTickEventTermCycle 32
                        else None
                    DiagJson.termCycle nodeKey depth site (int newGen) reKey max_reentry_key big hs ks tc_count tc_panic
                    let errEnv = if depth > 256 then s else (add_trace s r0)
                    let msg = FastRuntimeFormat.format "%s: re-entrant term evaluation cycle detected at %s (key=%s depth=%d gen=%d re=%d/%d big=%b)" [| box DiagnosticClassifier.EJP0011; box site; box nodeKey; box depth; box (int newGen); box reKey; box max_reentry_key; box big |]
                    let msg = match frameOpt with Some frame -> EvalWorklist.requiredMessage msg frame | None -> msg
                    let msg =
                        msg + "\n"
                        + RunawayUnrollDiagnostic.render
                            "EJP0011"
                            (sprintf "partial evaluation re-entered `%s` more than %d times" site max_reentry)
                            (s.trace |> List.map (fun (r: Range) -> r.path, (fst r.range).line, (fst r.range).character))
                            "the re-entry limit (EvalFallbackPolicy.maxReentry) is not configurable: a deliberately deep recursion over static data should be a join point too"
                    raise_type_error errEnv msg
                

            // Maximum term recursion depth. Keep parallel attempts conservative, but give
            // forced-sequential fallback a larger legacy-style budget. This is the bridge toward
            // stack-safe evaluators: enough room for old list folds, still bounded by stack_check.
            let max_depth_base = EvalFallbackPolicy.depthBase
            let max_depth_big = EvalFallbackPolicy.maxDepthBig seqNow
            let max_depth = if BigStack.isActive s.bigStack then max_depth_big else max_depth_base
    

            let deepSitesShort () =
                RecursionTracker.getDeepSites()
                |> List.sortByDescending (fun (_, count) -> count)
                |> List.truncate 8
                |> List.map (fun (site, count) -> sprintf "%s=%d" site count)
                |> String.concat ";"
    

            let stack_check (tag: string) =
                match evalStackProbeDecision () with
                | EvalStackProbeAvailable -> ()
                | EvalStackProbeInsufficient ->
                    let newGen = CacheGeneration.current()
                    jpMismatchAdd (sprintf "%s|term_insufficient_stack" DiagnosticClassifier.EJP0010) |> ignore
                    let reasons = CacheGeneration.reasonsSnapshot 6 |> String.concat " | "
                    let deepSites = deepSitesShort ()
                    DiagSidecar.emitEnvSnapshotOnce()
                    let tid = System.Threading.Thread.CurrentThread.ManagedThreadId
                    let bigActive = BigStack.isActive s.bigStack
                    let nest = BigStack.getNest s.bigStack
                    let mbTerm = BigStack.getMb s.bigStack BigStack.BigStackTerm
                    let mem = try System.GC.GetTotalMemory(false) with _ -> 0L
                    DiagSidecar.emit (FastRuntimeFormat.format "%s term insufficient_stack depth=%d site=%s gen=%d tag=%s tid=%d bigActive=%b nest=%d mb=%d mem=%d deepSites=[%s] reasons=[%s]" [| box DiagnosticClassifier.EJP0010; box depth; box site; box newGen; box tag; box tid; box bigActive; box nest; box mbTerm; box mem; box deepSites; box reasons |])
                    raise (EvalCoreStackPivotRequested EvalCoreTermStackProbe)
    

            if depth <= 32 then
                if (depth &&& 7) = 0 then stack_check "d<=32"
            elif depth <= 128 then
                if (depth &&& 1) = 0 then stack_check "d<=128"
            else
    
                stack_check "d>128"

            if depth > max_depth then
