                let errEnv = if depth > 256 then s else (add_trace s r0)
                if depth > 256 then
                    raise_type_error_no_trace errEnv (FastRuntimeFormat.format "%s: term recursion depth exceeded (depth=%d max=%d) at %s" [| box DiagnosticClassifier.EJP0009; box depth; box max_depth; box site |])
                else
