                    let bodyNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box body)
                    // MIGRATION: do not overwrite an already-resolved forall body child.
                    // MIGRATION proved the child EForall' can resolve before the parent
                    // ETypeApply schedules its body.  Replacing that value with a fresh
                    // term s' body thunk reintroduced the same cyclic type_apply failure.
                    // Keep existing store entries and only install a thunk when the body
                    // is genuinely absent.
                    EvalReplayValueStore.putParentContinuation bodyNodeId { parentKind = EvalReplayValueStore.EvaluatorTermNode; parentShape = CompilerIdentityKernel.WorkShapeIdOps.Known.eTypeApply; parentNodeId = parentNodeId; role = EvaluatorJoinPointBody }
                    EvalReplayValueStore.putTypeApplyBodyNode parentNodeId bodyNodeId
                    if not (EvalReplayValueStore.hasTermValue bodyNodeId) then
                        // A type-apply body can itself be a first-class term value (EForall'/EFun').
                        // Materialize those directly in the concrete type-apply environment instead
                        // of calling term while a fuse is already tripped.  Non-value bodies keep the
                        // old fail-closed thunk path.
                        let s' = { s with env_global_type = gl_ty; env_global_term = gl_term; env_stack_type = Array.zeroCreate<_> sz_ty; env_stack_term = Array.zeroCreate<_> sz_term }
                        s'.env_stack_type.[0] <- typeArg
                        let directBodyValue =
                            try
                                match body with
                                | EB _ -> Choice1Of2 DB
                                | ELit(_,lit) -> Choice1Of2 (DLit lit)
                                | ESymbol(_,sym) -> Choice1Of2 (DSymbol sym)
                                | EFun'(_,freeVars,i,fnBody,annot) ->
                                    if freeVars.term.free_vars.Length <> i then Choice2Of2 "type_apply_body_function_free_var_arity_mismatch"
                                    else Choice1Of2 (DFunction(fnBody, annot, HopacExtensions.S.map (v s') freeVars.term.free_vars, HopacExtensions.S.map (vt s') freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                                | ERecursiveFun'(_,freeVars,i,fnBody,annot) ->
                                    if freeVars.term.free_vars.Length <> i then Choice2Of2 "type_apply_body_recursive_function_free_var_arity_mismatch"
                                    else Choice1Of2 (DFunction(fnBody.Value, annot, HopacExtensions.S.map (v s') freeVars.term.free_vars, HopacExtensions.S.map (vt s') freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                                | EForall'(_,freeVars,i,forallBody) ->
                                    if freeVars.ty.free_vars.Length <> i then Choice2Of2 "type_apply_body_forall_free_var_arity_mismatch"
                                    else Choice1Of2 (DForall(forallBody, HopacExtensions.S.map (v s') freeVars.term.free_vars, HopacExtensions.S.map (vt s') freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                                | ERecursiveForall'(_,freeVars,i,forallBody) ->
                                    if freeVars.ty.free_vars.Length <> i then Choice2Of2 "type_apply_body_recursive_forall_free_var_arity_mismatch"
                                    else Choice1Of2 (DForall(forallBody.Value, HopacExtensions.S.map (v s') freeVars.term.free_vars, HopacExtensions.S.map (vt s') freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                                | ENominal _ ->
                                    // A nominal constructor is not a first-class closure, but when it is the
                                    // immediate body of a type-apply replay we can try it under the already
                                    // materialized type argument before falling back to the old thunk path.
                                    Choice1Of2 (term s' body)
                                | _ -> Choice2Of2 "type_apply_body_not_immediate_value"
                            with ex -> Choice2Of2 ("type_apply_body_direct_value_failed:" + ex.GetType().Name)
                        match directBodyValue with
                        | Choice1Of2 value ->
                            EvalReplayValueStore.putTermValue bodyNodeId value
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_apply_body_direct_value_materialized\",\"event\":\"type_apply_body_register\",\"parent_node_id\":%d,\"body_node_id\":%d,\"body_shape\":%s,\"site\":%s,\"single_flight\":1,\"next\":\"type_apply_body_value_materialized\"}" [| box parentNodeId; box bodyNodeId; box (DiagJson.esc (evalNodeShapeTerm body)); box (DiagJson.esc site) |])
                        | Choice2Of2 detail ->
                            EvalReplayValueStore.putTerm bodyNodeId (fun () -> term s' body)
                            if detail <> "type_apply_body_not_immediate_value" then
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_apply_body_direct_value_blocked\",\"event\":\"type_apply_body_register\",\"parent_node_id\":%d,\"body_node_id\":%d,\"body_shape\":%s,\"site\":%s,\"detail\":%s,\"single_flight\":1,\"next\":\"fallback_type_apply_body_thunk\"}" [| box parentNodeId; box bodyNodeId; box (DiagJson.esc (evalNodeShapeTerm body)); box (DiagJson.esc site); box (DiagJson.esc detail) |])
                    Choice1Of2 (bodyNodeId, evalNodeWorkShapeIdTerm body)
                | DV(L(_,YForall)) -> Choice2Of2 EvalReplayValueStore.ReplayBodyScheduleTypeApplyRuntimeForall
                | a -> Choice2Of2 (EvalReplayValueStore.ReplayBodyScheduleTypeApplyExpectedForall (CompilerKernelV2.OperationalReasonIdOps.create (show_data a))))

            let rec apply s (a0, b0) =
                // MIGRATION: Removed proactive depth-based BigStack spawning
                // Rely only on EnsureSufficientExecutionStack in apply_core for reactive spawning
                apply_core s (a0, b0)
    

            and apply_core s (a0, b0) =
                // MIGRATION: define site/r0 locally for error messages
                let r0 = match s.trace with | r :: _ -> r | [] -> range0
                let site =
                    match s.trace with
                    | r :: _ ->
                        let (a,_) = r.range
                        FastRuntimeFormat.format "apply@%s:%d:%d" [| box r.path; box a.line; box a.character |]
                    | _ -> "apply@unknown"
                jpRecordCurrentWorkPhase JpOperationPhaseApplyCoreEntry
                // ### MIGRATION: stack guard + one-shot big-stack fallback (evita falha em folds profundos no bootstrap/stdlib)
                // apply participates in the term<->apply recursion; guard here too so we never hard-crash.
                let mutable stack_fallback : Data option = None
                match evalStackProbeDecision () with
                | EvalStackProbeAvailable -> ()
                | EvalStackProbeInsufficient ->
                    // MIGRATION: reexecute on BigStack; child exhaustion remains fail-closed below.
                    stack_fallback <- BigStack.tryRunApply s.bigStack (fun child -> apply (langEnvWithBigStack child s) (a0, b0))
                    if stack_fallback.IsNone then
                        let newGen = CacheGeneration.invalidate (CacheGeneration.GenerationChangeReasonIdOps.create (System.String.Format("{0}: apply insufficient_stack site={1}", DiagnosticClassifier.EJP0010, site)))
                        jpMismatchAdd (System.String.Format("{0}|apply_insufficient_stack", DiagnosticClassifier.EJP0010)) |> ignore
                        let depthA = RecursionTracker.currentDepth s.recursion
                        let maxObs = RecursionTracker.getMaxObserved()
                        let deepSites = deepSitesShort ()
                        let reasons = CacheGeneration.reasonsSnapshot 6 |> String.concat " | "
                        let tid = System.Threading.Thread.CurrentThread.ManagedThreadId
                        let bigActive = BigStack.isActive s.bigStack
                        let mbApply = BigStack.getMb s.bigStack BigStack.BigStackApply
                        let traceShort =
                            s.trace
                            |> List.truncate 6
                            |> List.map (fun r -> let (a,_) = r.range in FastRuntimeFormat.format "%s:%d:%d" [| box r.path; box a.line; box a.character |])
                            |> String.concat " <- "
                        DiagSidecar.emit (System.String.Format("{0} apply insufficient_stack gen={1} site={2} depth={3} maxObs={4} tid={5} bigActive={6} mb={7} trace={8} deepSites=[{9}] reasons=[{10}]",
                            DiagnosticClassifier.EJP0010, newGen, site, depthA, maxObs, tid, bigActive, mbApply, traceShort, deepSites, reasons))
                        raise_type_error (add_trace s r0) (System.String.Format("{0}: insufficient execution stack in apply at {1} (gen={2} depth={3} maxObs={4} tid={5} bigActive={6} mb={7})",
                            DiagnosticClassifier.EJP0010, site, newGen, depthA, maxObs, tid, bigActive, mbApply))
    

                match stack_fallback with
                | Some v ->
                    jpMismatchAdd (System.String.Format("{0}|apply_bigstack_ok", DiagnosticClassifier.EJP0010)) |> ignore
                    DiagSidecar.emit (System.String.Format("{0} apply bigstack_ok site={1} depth={2}", DiagnosticClassifier.EJP0010, site, RecursionTracker.currentDepth s.recursion))
                    v
                | None ->
                    let mutable a = a0
                    let mutable b = b0
                    let mutable unwrapping = true
                    while unwrapping do
                        match a with
                        | DNominal(DUnion _, _) -> raise_type_error s "Unions cannot be applied."
                        | DNominal(a', _) -> a <- a'
                        | _ -> unwrapping <- false
    

                    match a, b with
                    | DRecord a, DSymbol b ->
                        jpRecordCurrentWorkPhase JpOperationPhaseApplyRecordLookup
                        match a |> Map.tryPick (fun (_, k) v -> if k = b then Some v else None) with
                        | Some a -> a
                        | None -> raise_type_error s <| sprintf "Cannot find the key %s inside the record." b
                    | DFunction(body,_,gl_term,gl_ty,sz_term,sz_ty), b ->
                        jpRecordCurrentWorkPhase JpOperationPhaseApplyFunctionBody
                        let s : LangEnv = { s with env_global_type = gl_ty; env_global_term = gl_term; env_stack_type = Array.zeroCreate<_> sz_ty; env_stack_term = Array.zeroCreate<_> sz_term }
                        s.env_stack_term.[0] <- b
                        // The DFunction body is the semantic result of the already-installed
                        // ApplyDispatch continuation. The typed tail-result bridge re-anchors
                        // that relation without minting a new PC or replaying the enclosing apply.
                        jpWithCurrentDeclaredTailResultBridge JpDeclaredFunctionBodyResultBridge (fun () -> term s body)
                    | DV(L(_,YForall)), _ -> raise_type_error s "Cannot apply a runtime forall, and not with a term. Foralls have to be known at compile time and applied with a type."
                    | DForall _, _ -> raise_type_error s "Cannot apply a forall with a term."
                    | DV(L(_,YFun(domain,range,t) & a_ty) & a), b ->
                        jpRecordCurrentWorkPhase JpOperationPhaseApplyRuntimeFunction
                        let b = dyn false s b
                        let b_ty = data_to_ty s b
                        let b_ty0 = data_to_ty s b
                        let b_ty = jp_method_deref_rec_placeholder b_ty0
                        if ty_eq_allow_jp_placeholders domain b_ty then push_typedop_no_rewrite s (TyApply(a,b)) range
                        else
                            let argumentTypeText = show_ty b_ty0
                            let parameterTypeText = show_ty domain
                            let functionTypeText = show_ty a_ty
                            let failureSite =
                                match s.trace with
                                | r :: _ ->
                                    let p0, p1 = r.range
                                    FastRuntimeFormat.format
                                        "jp@%s:%d:%d-%d:%d"
                                        [| box r.path; box (p0.line + 1); box (p0.character + 1); box (p1.line + 1); box (p1.character + 1) |]
                                | [] -> "jp@unknown"
                            let failureNodeId =
                                CompilerIdentityKernel.ContentDigest.ofText "jp-apply-failure-node" failureSite
                                |> CompilerIdentityKernel.ContentDigest.text
                            let argumentTypeRef =
                                CompilerIdentityKernel.ContentDigest.ofText "jp-apply-argument-type" argumentTypeText
                                |> CompilerIdentityKernel.ContentDigest.text
                            let parameterTypeRef =
                                CompilerIdentityKernel.ContentDigest.ofText "jp-apply-parameter-type" parameterTypeText
                                |> CompilerIdentityKernel.ContentDigest.text
                            let functionTypeRef =
                                CompilerIdentityKernel.ContentDigest.ofText "jp-apply-function-type" functionTypeText
                                |> CompilerIdentityKernel.ContentDigest.text
                            let failureDetailRef =
                                CompilerIdentityKernel.ContentDigest.ofText
                                    "jp-apply-argument-type-mismatch"
                                    (failureNodeId + "|arg=" + argumentTypeRef + "|parameter=" + parameterTypeRef + "|function=" + functionTypeRef)
                                |> CompilerIdentityKernel.ContentDigest.text
                            DiagJson.emitRecord {
                                kind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpApplyArgumentTypeMismatchObserved
                                current_work_job_id = jpCurrentWorkJobId ()
                                failure_site = failureSite
                                failure_node_id = failureNodeId
                                failure_detail_ref = failureDetailRef
                                argument_type = argumentTypeText
                                argument_type_ref = argumentTypeRef
                                parameter_type = parameterTypeText
                                parameter_type_ref = parameterTypeRef
                                function_type = functionTypeText
                                function_type_ref = functionTypeRef
                                argument_data_shape_du = b |> replayDataShapeOf |> replayDataShapeText
                                authority = "apply_core_structural_type_mismatch_before_raise"
                                next = "correlate_failure_node_with_resume_frame_and_source_span"
                            }
                            raise_type_error s <| sprintf "Cannot apply an argument of type %s to a function of type: %s" argumentTypeText functionTypeText
                    | DV(L(i,YLayout(ty,layout)) as tyv) as a, DSymbol b ->
                        let key = TyLayoutIndexByKey(tyv, LayoutFieldNameIdOps.create b)
                        let ret_ty =
                            match ty with
                            | YRecord r ->
                                match r |> Map.tryPick (fun (i, k) v -> if k = b then Some (i,v) else None) with
                                | Some (_i, a) -> a
                                | None -> raise_type_error s <| sprintf "Cannot find the key %s inside the layout type's record." b
                            | _ -> raise_type_error s <| sprintf "Expected a record inside the layout type.\nGot: %s" (show_ty ty)
                        match layout with
                        | Heap | StackMutable | HeapMutable -> push_typedop_no_rewrite s key ret_ty
                    | DV(L(_,YLayout _)), b -> raise_type_error s <| sprintf "Expected a symbol as the index into the layout type.\nGot: %s" (show_data b)
                    | a, b ->
                        jpRecordCurrentWorkPhase JpOperationPhaseApplyMismatch
                        // ### MIGRATION: Enhanced EJP0007 handling with depth tracking and cache management ###
                        // EJP0007: Apply type mismatch - often indicates cache corruption under concurrent builds.
                        // When we get a primitive (like i32) where a function is expected, it's almost always
                        // due to a race condition in the join point cache.
                        let is_primitive_mismatch =
                            match a with
                            | DV(L(_, YPrim _)) | DLit _ -> true
                            | _ -> false
    

                        let depth = RecursionTracker.currentDepth s.recursion
                        let tid = System.Threading.Thread.CurrentThread.ManagedThreadId
                        let gen0 = CacheGeneration.current ()
                        let site =
                            match s.trace with
                            | r :: _ ->
                                let (a,_) = r.range
                                FastRuntimeFormat.format "%s:%d:%d" [| box r.path; box a.line; box a.character |]
                            | _ -> "unknown"
    

                        let got_ty = data_to_ty s a
                        let got_ty_deref = jp_method_deref_rec_placeholder got_ty
    

                        if is_primitive_mismatch then
                            // Record for pattern learning
                            BitMamba.recordFailure a
    

                            // Mark as suspect in cache
                            SuspectCache.mark a DiagnosticClassifier.EJP0007
    

                            jpMismatchAdd (sprintf "%s|apply_primitive" DiagnosticClassifier.EJP0007) |> ignore
                            let snap = if jp_diag_verbose then diag_snapshot_short (sprintf "%s apply_mismatch site=%s" DiagnosticClassifier.EJP0007 site) else ""
                            DiagSidecar.emit (FastRuntimeFormat.format "%s apply mismatch: expected callable, got %s Got(ty=%s deref=%s) depth=%d site=%s\n%s" [| box DiagnosticClassifier.EJP0007; box (show_data a); box (show_ty got_ty); box (show_ty got_ty_deref); box depth; box site; box snap |])
                            // MIGRATION+: bounded invalidation at shallow depth only.
                            // Deep recursion tends to be deterministic; invalidating here causes a generation storm.
                            let invKey = sprintf "%s|apply_deep_recursion|%s" DiagnosticClassifier.EJP0008 site
                            let invN = jpMismatchAdd invKey
                            if invN <= 1 && depth <= 256 then
                                let wasSeq = CacheGeneration.isSequentialRequested ()
                                CacheGeneration.requestSequential ()
                                // [EJP0008-220-001] Do NOT invalidate on apply mismatch.
                                // SuspectCache.mark already poisons join_point_key so memoization is bypassed.
                                // Invalidation bumps generation and can cascade into BigStack join aborts (EJP0018),
                                // sometimes leaving JP in a liveness-bug state (stage 4/4 stall).
                                let genNow = CacheGeneration.current()
                                if not wasSeq then
                                    DiagSidecar.emit (FastRuntimeFormat.format "%s apply mismatch -> requestSequential (no invalidate; gen=%d) depth=%d site=%s" [| box DiagnosticClassifier.EJP0008; box genNow; box depth; box site |])
                                else
                                    DiagSidecar.emit (FastRuntimeFormat.format "%s apply mismatch -> already sequential (no invalidate; gen=%d) depth=%d site=%s" [| box DiagnosticClassifier.EJP0008; box genNow; box depth; box site |])
                        let is_jp_placeholder_apply =
                            match tryDecodeJpRecPlaceholder got_ty_deref with
                            | Some _ -> true
                            | None -> false
    

                        let liveReplayApplyMismatchHandoff =
                            (try
                                EvalWorklist.pendingCount() > 0
                                || EvalWorklist.replayQueueDepth() > 0
                                || EvalWorklist.replayDriverActiveDepthValue() > 0
                                || EvalWorklist.hasProgressYield()
                             with _ -> false)
                        let recordLikeLiveReplayApplyMismatch =
                            liveReplayApplyMismatchHandoff
                            && (applyMismatchCarrierShapeFor a got_ty_deref
                                |> applyMismatchCarrierIsRecord)
                        let singletonRecordApplyBridge =
                            match a with
                            | DRecord fields when liveReplayApplyMismatchHandoff && fields.Count = 1 ->
                                fields
                                |> Seq.tryHead
                                |> Option.map (fun (KeyValue((_, fieldName), fieldValue)) -> fieldName, fieldValue)
                            | _ -> None
                        if singletonRecordApplyBridge.IsSome then
                            let fieldName, fieldValue = singletonRecordApplyBridge.Value
                            let pendingNow = EvalWorklist.pendingCount()
                            let queueDepthNow = EvalWorklist.replayQueueDepth()
                            let activeDepthNow = EvalWorklist.replayDriverActiveDepthValue()
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_record_singleton_apply_bridge\",\"event\":\"apply_type_mismatch\",\"site\":%s,\"field\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"policy\":\"destructive_graph_mutation_record_singleton_field_is_callable\",\"single_flight\":1,\"next\":\"apply_single_record_field\"}" [| box (DiagJson.esc site); box (DiagJson.esc fieldName); box pendingNow; box queueDepthNow; box activeDepthNow |])
                            apply s (fieldValue, b)
                        elif is_jp_placeholder_apply then
                            SuspectCache.mark a (sprintf "%s apply_jp_placeholder" DiagnosticClassifier.EJP0007)
                            jpMismatchAdd (sprintf "%s|apply_jp_placeholder" DiagnosticClassifier.EJP0007) |> ignore
                            let snap = if jp_diag_verbose then diag_snapshot_short (sprintf "%s apply_jp_placeholder site=%s" DiagnosticClassifier.EJP0007 site) else ""
                            DiagSidecar.emit (FastRuntimeFormat.format "%s apply mismatch: JP placeholder callable (soft), returning arg (no invalidate). got=%s ty=%s deref=%s depth=%d site=%s\n%s" [| box DiagnosticClassifier.EJP0007; box (show_data a); box (show_ty got_ty); box (show_ty got_ty_deref); box depth; box site; box snap |])
                            // MIGRATION: JP placeholder apply is soft; no cache invalidation/sequential request.
                            b
                        elif recordLikeLiveReplayApplyMismatch then
                            let pendingNow = EvalWorklist.pendingCount()
                            let queueDepthNow = EvalWorklist.replayQueueDepth()
                            let activeDepthNow = EvalWorklist.replayDriverActiveDepthValue()
                            let progressYieldNow = EvalWorklist.hasProgressYield()
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_record_apply_type_error_hole_collapsed\",\"event\":\"apply_type_mismatch\",\"site\":%s,\"got\":%s,\"got_ty\":%s,\"got_ty_deref\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"progress_yield_pending\":%b,\"policy\":\"destructive_cycle_break_record_apply_returns_arg_under_live_replay\",\"single_flight\":1,\"next\":\"continue_after_apply_hole\"}" [| box (DiagJson.esc site); box (DiagJson.esc (show_data a)); box (DiagJson.esc (show_ty got_ty)); box (DiagJson.esc (show_ty got_ty_deref)); box pendingNow; box queueDepthNow; box activeDepthNow; box progressYieldNow |])
                            TermCycleFuse.reset ()
                            b
                        else
                            raise_type_error s <| FastRuntimeFormat.format "Expected a function, closure, record or a layout type possibly inside a nominal.\nGot: %s\nGot(ty): %s\nGot(ty_deref): %s" [| box (show_data a); box (show_ty got_ty); box (show_ty got_ty_deref) |]
    
    


            EvalReplayValueStore.installApplyAfterDefinition (fun sObj head arg ->
                apply (unbox<LangEnv> sObj) (head, arg))

            EvalReplayValueStore.installApplyFunctionBodyReplayAfterDefinition (fun sObj parentNodeId head arg ->
                let s = unbox<LangEnv> sObj
                match head with
                | DFunction(body, _annot, gl_term, gl_ty, sz_term, sz_ty) ->
                    let bodyNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box body)
                    EvalReplayValueStore.putParentContinuation bodyNodeId { parentKind = EvalReplayValueStore.EvaluatorTermNode; parentShape = CompilerIdentityKernel.WorkShapeIdOps.Known.eApply; parentNodeId = parentNodeId; role = EvaluatorClosureBody }
                    EvalReplayValueStore.putApplyFunctionBodyNode parentNodeId bodyNodeId
                    let mkBodyEnv () =
                        let s' = { s with env_global_type = gl_ty; env_global_term = gl_term; env_stack_type = Array.zeroCreate<_> sz_ty; env_stack_term = Array.zeroCreate<_> sz_term }
                        s'.env_stack_term.[0] <- arg
                        s'
                    match body with
                    | EPairTest(r, bind, p1, p2, onSucc, onFail) ->
                        let succNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box onSucc)
                        let failNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box onFail)
                        let pairEnvForBind () = add_trace (mkBodyEnv()) r
                        try
                            let bindEnv = pairEnvForBind()
                            EvalReplayValueStore.putPairTestBindValue bodyNodeId (v bindEnv bind)
                        with _ -> ()
                        EvalReplayValueStore.putTerm succNodeId (fun () ->
                            let branchEnv = pairEnvForBind()
                            match v branchEnv bind with
                            | DPair(a,b) ->
                                store_term branchEnv p1 a
                                store_term branchEnv p2 b
                                term branchEnv onSucc
                            | other -> failwith (sprintf "pair_test_success_branch_not_selected:%s" (show_data other)))
                        EvalReplayValueStore.putTerm failNodeId (fun () ->
                            let branchEnv = pairEnvForBind()
                            match v branchEnv bind with
                            | DPair _ -> failwith "pair_test_fail_branch_not_selected:DPair"
                            | _ -> term branchEnv onFail)
                        EvalReplayValueStore.putPairTestSpine bodyNodeId {
                            successNodeId = succNodeId
                            successShape = evalNodeWorkShapeIdTerm onSucc
                            failNodeId = failNodeId
                            failShape = evalNodeWorkShapeIdTerm onFail
                        }
                    | EAnnotTest(_, annotTy, bind, onSucc, onFail) ->
                        let typeNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box annotTy)
                        let trueNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box onSucc)
                        let falseNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box onFail)
                        let annotEnv () = mkBodyEnv()
                        EvalReplayValueStore.putAnnotTestContext bodyNodeId (box (annotEnv()))
                        try EvalReplayValueStore.putAnnotTestBindValue bodyNodeId (v (annotEnv()) bind)
                        with _ -> ()
                        EvalReplayValueStore.putType typeNodeId (fun () -> ty (annotEnv()) annotTy)
                        EvalReplayValueStore.putTerm trueNodeId (fun () -> term (annotEnv()) onSucc)
                        EvalReplayValueStore.putTerm falseNodeId (fun () -> term (annotEnv()) onFail)
                        EvalReplayValueStore.putAnnotTestSpine bodyNodeId {
                            typeNodeId = typeNodeId
                            typeShape = evalNodeWorkShapeIdTy annotTy
                            trueNodeId = trueNodeId
                            trueShape = evalNodeWorkShapeIdTerm onSucc
                            falseNodeId = falseNodeId
                            falseShape = evalNodeWorkShapeIdTerm onFail
                        }
                        EvalReplayValueStore.putTerm bodyNodeId (fun () ->
                            let s2 = annotEnv()
                            let branch, branchNodeId =
                                let bindTy = data_to_ty s2 (v s2 bind)
                                let annotTy2 = ty s2 annotTy
                                if ty_eq_allow_jp_placeholders bindTy annotTy2 then onSucc, trueNodeId
                                else onFail, falseNodeId
                            match EvalReplayValueStore.tryTerm branchNodeId with
                            | Some value -> value
                            | None -> failwith ("annot_test_branch_value_missing:" + evalNodeShapeTerm branch))
                    | EUnitTest(r, bind, onSucc, onFail) ->
                        // MIGRATION: historical runtime reached EUnitTest branches whose selected
                        // child was EAnnotTest, but the function-body replay bridge had only
                        // a direct thunk and no branch-local AnnotTestSpine.  Register the
                        // UnitTest discriminator plus selected branches in the body env, and
                        // materialize nested EAnnotTest spines with the same body env so
                        // term_annot_test_spine_missing cannot repeat as a fingerprint loop.
                        let bindNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box bind)
                        let succNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box onSucc)
                        let failNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box onFail)
                        let unitEnv () = add_trace (mkBodyEnv()) r
                        let registerBodyBranchTerm (branchNodeId: int) (branchExpr: E) =
                            match branchExpr with
                            | EAnnotTest(ar, branchAnnotTy, branchBind, branchOnSucc, branchOnFail) ->
                                let branchTypeNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box branchAnnotTy)
                                let branchTrueNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box branchOnSucc)
                                let branchFalseNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box branchOnFail)
                                let branchEnv () = add_trace (unitEnv()) ar
                                EvalReplayValueStore.putAnnotTestContext branchNodeId (box (branchEnv()))
                                try EvalReplayValueStore.putAnnotTestBindValue branchNodeId (v (branchEnv()) branchBind)
                                with _ -> ()
                                EvalReplayValueStore.putType branchTypeNodeId (fun () -> ty (branchEnv()) branchAnnotTy)
                                EvalReplayValueStore.putTerm branchTrueNodeId (fun () -> term (branchEnv()) branchOnSucc)
                                EvalReplayValueStore.putTerm branchFalseNodeId (fun () -> term (branchEnv()) branchOnFail)
                                EvalReplayValueStore.putAnnotTestSpine branchNodeId {
                                    typeNodeId = branchTypeNodeId
                                    typeShape = evalNodeWorkShapeIdTy branchAnnotTy
                                    trueNodeId = branchTrueNodeId
                                    trueShape = evalNodeWorkShapeIdTerm branchOnSucc
                                    falseNodeId = branchFalseNodeId
                                    falseShape = evalNodeWorkShapeIdTerm branchOnFail
                                }
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_unit_test_branch_annot_spine_materialized\",\"event\":\"apply_function_body_replay\",\"unit_node_id\":%d,\"branch_node_id\":%d,\"type_node_id\":%d,\"true_node_id\":%d,\"false_node_id\":%d,\"branch_shape\":%s,\"single_flight\":1,\"next\":\"native_hopac_annot_test_branch_stepper_direct_required\"}" [| box bodyNodeId; box branchNodeId; box branchTypeNodeId; box branchTrueNodeId; box branchFalseNodeId; box (DiagJson.esc (evalNodeShapeTerm branchExpr)) |])
                                EvalReplayValueStore.putTerm branchNodeId (fun () ->
                                    let s2 = branchEnv()
                                    let selectedBranch, selectedNodeId =
                                        let bindTy = data_to_ty s2 (v s2 branchBind)
                                        let annotTy2 = ty s2 branchAnnotTy
                                        if ty_eq_allow_jp_placeholders bindTy annotTy2 then branchOnSucc, branchTrueNodeId
                                        else branchOnFail, branchFalseNodeId
                                    match EvalReplayValueStore.tryTerm selectedNodeId with
                                    | Some value -> value
                                    | None -> failwith ("annot_test_branch_value_missing:" + evalNodeShapeTerm selectedBranch))
                            | _ ->
                                EvalReplayValueStore.putTerm branchNodeId (fun () -> term (unitEnv()) branchExpr)
                        registerBodyBranchTerm succNodeId onSucc
                        registerBodyBranchTerm failNodeId onFail
                        EvalReplayValueStore.putTerm bindNodeId (fun () -> v (unitEnv()) bind)
                        EvalReplayValueStore.putUnitTestSpine bodyNodeId {
                            bindNodeId = bindNodeId
                            bindShape = CompilerIdentityKernel.WorkShapeIdOps.create "EV"
                            successNodeId = succNodeId
                            successShape = evalNodeWorkShapeIdTerm onSucc
                            failNodeId = failNodeId
                            failShape = evalNodeWorkShapeIdTerm onFail
                        }
                        EvalReplayValueStore.putTerm bodyNodeId (fun () ->
                            let s2 = unitEnv()
                            let branchSelection, branch, branchNodeId =
                                match v s2 bind with
                                | DB -> EvalReplayValueStore.UnitTestSuccessBranchSelected, onSucc, succNodeId
                                | _ -> EvalReplayValueStore.UnitTestFailureBranchSelected, onFail, failNodeId
                            EvalReplayValueStore.putUnitTestBranchSelection bodyNodeId branchSelection
                            match EvalReplayValueStore.tryTerm branchNodeId with
                            | Some value -> value
                            | None -> failwith ("unit_test_branch_value_missing:" + evalNodeShapeTerm branch))
                    | EOp(_, op, args) ->
                        let bodyEnv = mkBodyEnv()
                        let argArray = args |> List.toArray
                        for argExpr in argArray do
                            let argNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box argExpr)
                            match argExpr with
                            | EV a -> EvalReplayValueStore.putTerm argNodeId (fun () -> v bodyEnv a)
                            | ELit(_,lit) -> EvalReplayValueStore.putTermValue argNodeId (DLit lit)
                            | ESymbol(_,sym) -> EvalReplayValueStore.putTermValue argNodeId (DSymbol sym)
                            | EB _ -> EvalReplayValueStore.putTermValue argNodeId DB
                            | _ ->
                                match op with
                                | While | Do | Indent ->
                                    // These ops evaluate their arguments in scopes of their own (term_scope).
                                    // A prefetch in bodyEnv would append the loop body's statements to the
                                    // enclosing sequence as well: `while` bodies ran once before the loop.
                                    // Prefetch into a throwaway scope instead; the op's handler re-evaluates.
                                    EvalReplayValueStore.putTerm argNodeId (fun () ->
                                        let isolated =
                                            { bodyEnv with
                                                seq = ResizeArray()
                                                cse = System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural) :: bodyEnv.cse }
                                        term isolated argExpr)
                                | _ -> EvalReplayValueStore.putTerm argNodeId (fun () -> term bodyEnv argExpr)
                        EvalReplayValueStore.putOpContext bodyNodeId (box bodyEnv)
                        EvalReplayValueStore.putApplyContext bodyNodeId (box bodyEnv)
                        EvalReplayValueStore.putOpSpine bodyNodeId {
                            op = op
                            argCount = argArray.Length
                            argNodeIds = argArray |> Array.map (fun e -> System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box e))
                            argShapes = argArray |> Array.map evalNodeWorkShapeIdTerm
                        }
                    | EApply _ ->
                        // MIGRATION: function-body replay can surface a nested EApply as the
                        // selected child before the normal registerReplayTerm pass has seen it.
                        // Materialize the same ApplySpine here, in the concrete body env, so
                        // term_apply_spine_missing_store becomes a child/arg replay instead of
                        // a replay-fingerprint terminal.  This only records existing syntax and
                        // existing thunks; the eventual value is still produced by apply/term.
                        let bodyEnv = mkBodyEnv()
                        let args = ResizeArray<E>()
                        let mutable cur = body
                        let mutable running = true
                        while running do
                            match cur with
                            | EApply(_, a, b) ->
                                args.Add b
                                cur <- a
                            | _ -> running <- false
                        let headNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box cur)
                        let putReplayTermLeaf nodeId expr =
                            match expr with
                            | EB _ -> EvalReplayValueStore.putTermValue nodeId DB
                            | EV a -> EvalReplayValueStore.putTerm nodeId (fun () -> v bodyEnv a)
                            | ELit(_,lit) -> EvalReplayValueStore.putTermValue nodeId (DLit lit)
                            | ESymbol(_,sym) -> EvalReplayValueStore.putTermValue nodeId (DSymbol sym)
                            | EFun'(_,freeVars,i,body,annot) ->
                                EvalReplayValueStore.putTerm nodeId (fun () ->
                                    if freeVars.term.free_vars.Length <> i then failwith "Replay function-body apply-head free-var arity mismatch."
                                    DFunction(body, annot, HopacExtensions.S.map (v bodyEnv) freeVars.term.free_vars, HopacExtensions.S.map (vt bodyEnv) freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                            | ERecursiveFun'(_,freeVars,i,body,annot) ->
                                EvalReplayValueStore.putTerm nodeId (fun () ->
                                    if freeVars.term.free_vars.Length <> i then failwith "Replay function-body recursive apply-head free-var arity mismatch."
                                    DFunction(body.Value, annot, HopacExtensions.S.map (v bodyEnv) freeVars.term.free_vars, HopacExtensions.S.map (vt bodyEnv) freeVars.ty.free_vars, freeVars.term.stack_size, freeVars.ty.stack_size))
                            | _ -> EvalReplayValueStore.putTerm nodeId (fun () -> term bodyEnv expr)
                        putReplayTermLeaf headNodeId cur
                        for argExpr in args do
                            let argNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box argExpr)
                            putReplayTermLeaf argNodeId argExpr
                        let replayArgs = args.ToArray()
                        EvalReplayValueStore.putApplyContext bodyNodeId (box bodyEnv)
                        EvalReplayValueStore.putApplySpine bodyNodeId {
                            headNodeId = headNodeId
                            headShape = evalNodeWorkShapeIdTerm cur
                            argCount = replayArgs.Length
                            argNodeIds = Array.rev replayArgs |> Array.map (fun e -> System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box e))
                            argShapes = Array.rev replayArgs |> Array.map evalNodeWorkShapeIdTerm
                        }
                    | _ -> ()
                    if not (EvalReplayValueStore.hasTerm bodyNodeId) then
                        EvalReplayValueStore.putTerm bodyNodeId (fun () -> term (mkBodyEnv()) body)
                    Choice1Of2 (bodyNodeId, evalNodeWorkShapeIdTerm body)
                | DV(L(_,YFun _)) ->
                    Choice2Of2 EvalReplayValueStore.ReplayBodyScheduleApplyRuntimeFunction
                | a ->
                    Choice2Of2 (EvalReplayValueStore.ReplayBodyScheduleApplyExpectedFunction (CompilerKernelV2.OperationalReasonIdOps.create (show_data a))))

            EvalReplayValueStore.installDynamicJoinApplyAfterDefinition (fun sObj head arg ->
                // MIGRATION: this bridge now covers both DFunction+dynamic-arg and
                // dynamic-placeholder-head+dynamic-arg.  The latter is the curried
                // continuation exposed by MIGRATION as unsupported_head:DV@arg1.
                let s = unbox<LangEnv> sObj
                let normalizeRetTy (t: Ty) =
                    let t = jp_method_deref_rec_placeholder t
                    match tryDecodeJpRecPlaceholder t with
                    | Some _ -> jpMethodUnknownReturnTy
                    | None -> t
                let retTy =
                    match head with
                    | DFunction(_, Some annot, _, _, _, _) ->
                        try normalizeRetTy (ty s annot)
                        with _ -> jpMethodUnknownReturnTy
                    | DV(L(_, YFun(_, range, _))) ->
                        normalizeRetTy range
                    | _ ->
                        jpMethodUnknownReturnTy
                let retTy =
                    match retTy with
                    | YVoid -> jpMethodUnknownReturnTy
                    | _ -> retTy
                let i = s.i.Value
                s.i.Value <- i + 1
                let placeholder = DV(L(i, retTy))
                DiagSidecar.emit (FastRuntimeFormat.format "[spiral_compiler] EJP0011 dynamic_join_apply replay placeholder ret=%s head=%s arg=%s" [| box (show_ty retTy); box (show_data head); box (show_data arg) |])
                placeholder)

            /// A match (or typecase) that ran into a join-point placeholder can never succeed while that join
            /// point's specialization is pending: the requeued body gets the same placeholder back and spins
            /// (apps/spiral: 96 join points stuck behind `++#?` -> format_real; FRONTIER.md fix 44). Marking a
            /// suspect switches JP methods to the inline recompute path (`RecomputeSuspect`, the pending-cell
            /// bypass) for the rest of the build, so the requeued attempt evaluates the callee directly, as the
            /// single-flight core does.
            let jpPlaceholderPatternMissEntersRecovery (patternNodeId:int) (gotText:string) =
                let mentionsPlaceholder =
                    gotText.Contains "JPMethodRecPlaceholder("
                    || gotText.Contains "JPMethodUnknownRet("
                    || gotText.Contains "JPTypeRecPlaceholder("
                    || gotText.Contains "JPClosureRecPlaceholder("
                    || gotText.Contains "JPArrayElementRecPlaceholder("
                if mentionsPlaceholder then
                    PevalStallProbe.enterRecovery (PevalStallProbe.RecoveryPlaceholderPatternMiss patternNodeId)
                    let firstInBuild = SuspectCache.currentCount () = 0
                    SuspectCache.mark (box patternNodeId) (DiagnosticClassifier.EJP0007 + " pattern_miss_on_jp_placeholder")
                    if firstInBuild then
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"jp_placeholder_pattern_miss_recovery_entered\",\"pattern_node_id\":%d,\"got\":%s,\"authority\":\"suspect_cache_inline_recompute\",\"next\":\"requeued_attempts_evaluate_join_points_inline\"}" [| box patternNodeId; box (DiagJson.esc gotText) |])

            let rec if_ (s: LangEnv) cond on_succ on_fail =
                // MIGRATION: Removed proactive depth-based BigStack spawning
                // Rely only on EnsureSufficientExecutionStack in if_core for reactive spawning
                if_core s cond on_succ on_fail
    

            and if_core (s: LangEnv) cond on_succ on_fail =
                // MIGRATION: emergency stack pivot shares the evaluator stack result lane.
                match evalCoreWithBigStack s BigStack.BigStackIfEmergency "if_emergency" (fun env -> if_core_impl env cond on_succ on_fail) with
                | EvalCoreStackCompleted value -> value
                | EvalCoreStackBigStackExhausted ->
                    let r0 = match s.trace with | r :: _ -> r | [] -> range0
                    raise_type_error (add_trace s r0) (sprintf "%s: stack overflow in if_ (BigStack exhausted)" DiagnosticClassifier.EJP0010)
    

            and if_core_impl (s: LangEnv) cond on_succ on_fail =
                let lit_tr = DLit(LitBool true)
                let lit_fl = DLit(LitBool false)
                let type_bool = YPrim BoolT
                let cond =
                    let visiting = HashSet(HashIdentity.Reference)
                    let mutable current = cond
                    let mutable finished = false
                    while not finished do
                        if visiting.Add current = false then
                            finished <- true
                        else
                            match current with
                            | DV(L(_,YPrim BoolT & type_bool)) as dynamicBool ->
                                match cse_tryfind s (TyOp(EQ, [dynamicBool; lit_tr])) with
                                | Some next when next <> dynamicBool -> current <- next
                                | Some _ | None -> finished <- true
                            | DV(L(v,ty)) when ty_is_jp_method_rec_placeholder ty ->
                                match jp_method_try_key_of_rec_placeholder ty with
                                | Some key -> jp_method_resolve_rec_placeholder key type_bool
                                | None -> ()
                                current <- DV(L(v, type_bool))
                                finished <- true
                            | DV(L(v,ty)) when isJpMethodUnknownReturnType ty ->
                                // A join-point unknown-return placeholder used as an if condition is
                                // constrained by the syntactic context to BoolT.  Do not terminalize it
                                // as a symbolic condition; normalize it into the same dynamic-bool path
                                // already used by unresolved recursive join-point placeholders.
                                current <- DV(L(v, type_bool))
                                finished <- true
                            | _ -> finished <- true
                    current
                match cond with
                | DLit (LitBool true) ->
                    jpWithCurrentDeclaredTailResultBridge JpDeclaredLiteralConditionalBranchResultBridge (fun () -> term s on_succ)
                | DLit (LitBool false) ->
                    jpWithCurrentDeclaredTailResultBridge JpDeclaredLiteralConditionalBranchResultBridge (fun () -> term s on_fail)
                | DV(L(_,YPrim BoolT & type_bool)) ->
                    let add_rewrite_cases is_true =
                        let cse = System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural)
                        let tr,fl = if is_true then lit_tr, lit_fl else lit_fl, lit_tr
                        let inline op op cond' res = cse.TryAdd(TyOp(op,[cond;cond']),res) |> ignore; cse.TryAdd(TyOp(op,[cond';cond]),res) |> ignore
                        op EQ lit_tr tr; op NEQ lit_tr fl; op EQ lit_fl fl; op NEQ lit_fl tr
                        cse
                    let tr, type_tr = term_scope' s (add_rewrite_cases true) on_succ
                    let fl, type_fl = term_scope' s (add_rewrite_cases false) on_fail
                    let type_tr, type_fl =
                        match type_tr, type_fl with
                        | YRecord tr, YRecord fl ->
                            let tr =
                                tr
                                |> Seq.map (fun (KeyValue ((i, k), v)) ->
                                    let i =
                                        fl |> Map.tryPick (fun (i', k') _ -> if k = k' then Some i' else None)
                                        |> Option.defaultValue i
                                    (i, k), v
                                )
                                |> Map.ofSeq
                                |> YRecord
    

                            let fl =
                                fl
                                |> Seq.map (fun (KeyValue ((i, k), v)) ->
                                    k, ((i, k), v)
                                )
                                |> Seq.distinctBy fst
                                |> Seq.map snd
                                |> Map.ofSeq
                                |> YRecord
    

                            tr, fl
    

                        | _ ->
                            type_tr, type_fl
    

                    if type_tr = type_fl then
                        if tr.Length = 1 && fl.Length = 1 then
                            match tr.[0], fl.[0] with
                            | TyLocalReturnOp(_,tr,_), TyLocalReturnOp(_,fl,_) when tr = fl -> push_typedop_no_rewrite s tr type_tr
                            | TyLocalReturnData(tr',_), TyLocalReturnData(fl',_) ->
                                match tr', fl' with
                                | tr, fl when tr = fl -> tr
                                | DLit(LitBool false), DLit(LitBool true) -> push_binop s EQ (cond,lit_fl) type_bool
                                | DLit(LitBool false), fl when cond = fl -> lit_fl
                                | DLit(LitBool true), fl -> // boolean or
                                    match fl with
                                    | DLit (LitBool false) -> cond
                                    | _ -> if cond = fl then cond else push_binop s BoolOr (cond,fl) type_bool
                                | tr, DLit(LitBool false) -> // boolean and
                                    match tr with
                                    | DLit(LitBool true) -> cond
                                    | _ -> if cond = tr then cond else push_binop s BoolAnd (cond,tr) type_bool
                                | _ -> push_typedop_no_rewrite s (TyIf(cond,tr,fl)) type_tr
                            | _ -> push_typedop_no_rewrite s (TyIf(cond,tr,fl)) type_tr
                        else push_typedop_no_rewrite s (TyIf(cond,tr,fl)) type_tr
                    else
                        // MIGRATION: JPMethod recursion placeholders can leak into composite branch types during parallel JP evaluation.
                        // Treat placeholders as unification holes recursively (pairs/arrays/apply/layout/fun/records).
                        let try_resolve_jp_placeholder (a: Ty) (b: Ty) : Ty option =
                            try
                                let k_opt =
                                    match jp_method_try_key_of_rec_placeholder a with
                                    | Some k -> Some k
                                    | None ->
                                        jp_method_rec_placeholders |> Seq.tryPick (fun (KeyValue(k,c)) -> if c.ph = a || c.v = a then Some k else None)
                                k_opt |> Option.map (fun k -> jp_method_resolve_rec_placeholder k b; b)
                            with _ -> None

                        let try_resolve_jp_placeholder_deep (a: Ty) (b: Ty) : Ty option =
                            let pending = System.Collections.Generic.Stack<Ty * Ty>()
                            let mutable changed = false
                            pending.Push((a,b))
                            while pending.Count > 0 do
                                let currentA, currentB = pending.Pop()
                                match try_resolve_jp_placeholder currentA currentB with
                                | Some _ -> changed <- true
                                | None ->
                                    match currentA, currentB with
                                    | YPair(a1,a2), YPair(b1,b2)
                                    | YApply(a1,a2), YApply(b1,b2) ->
                                        // Preserve historical left-before-right resolution order.
                                        pending.Push((a2,b2))
                                        pending.Push((a1,b1))
                                    | YArray a1, YArray b1 ->
                                        pending.Push((a1,b1))
                                    | YLayout(a1,l1), YLayout(b1,l2) when l1 = l2 ->
                                        pending.Push((a1,b1))
                                    | YFun(a1,r1,ft1), YFun(a2,r2,ft2) when ft1 = ft2 ->
                                        pending.Push((r1,r2))
                                        pending.Push((a1,a2))
                                    | YRecord ra, YRecord rb ->
                                        let matched =
                                            ra
                                            |> Seq.choose (fun (KeyValue((_, key), valueA)) ->
                                                rb
                                                |> Map.tryPick (fun (_, keyB) valueB -> if key = keyB then Some(valueA,valueB) else None))
                                            |> Seq.toArray
                                        for index = matched.Length - 1 downto 0 do
                                            pending.Push matched.[index]
                                    | _ -> ()
                            if changed then Some b else None

                        match try_resolve_jp_placeholder_deep type_tr type_fl with
                        | Some ty -> push_typedop_no_rewrite s (TyIf(cond,tr,fl)) ty
                        | None ->
                            match try_resolve_jp_placeholder_deep type_fl type_tr with
                            | Some ty -> push_typedop_no_rewrite s (TyIf(cond,tr,fl)) ty
                            | None ->
                                raise_type_error s <| sprintf "Types in branches of If do not match.\nGot: %s and %s" (show_ty type_tr) (show_ty type_fl)
                | cond -> raise_type_error s <| sprintf "Expected a bool in conditional.\nGot: %s" (show_data cond)
    

            let eq s a b =
                let inline op a b = a = b
                match a,b with
                | DLit a, DLit b ->
                    match a, b with
                    | LitInt8 a, LitInt8 b -> op a b |> LitBool |> DLit
                    | LitInt16 a, LitInt16 b -> op a b |> LitBool |> DLit
                    | LitInt32 a, LitInt32 b -> op a b |> LitBool |> DLit
                    | LitInt64 a, LitInt64 b -> op a b |> LitBool |> DLit
                    | LitUInt8 a, LitUInt8 b -> op a b |> LitBool |> DLit
                    | LitUInt16 a, LitUInt16 b -> op a b |> LitBool |> DLit
                    | LitUInt32 a, LitUInt32 b -> op a b |> LitBool |> DLit
                    | LitUInt64 a, LitUInt64 b -> op a b |> LitBool |> DLit
                    | LitFloat32 a, LitFloat32 b -> op a b |> LitBool |> DLit
                    | LitFloat64 a, LitFloat64 b -> op a b |> LitBool |> DLit
                    | LitString a, LitString b -> op a b |> LitBool |> DLit
                    | LitChar a, LitChar b -> op a b |> LitBool |> DLit
                    | LitBool a, LitBool b -> op a b |> LitBool |> DLit
                    | a, b -> raise_type_error s <| sprintf "The two literals must be equal in type.\nGot: %s and %s" (show_lit a) (show_lit b)
                | DSymbol a, DLit (LitString b)
                | DLit (LitString b), DSymbol a ->
                    op a b |> LitBool |> DLit
                | DV(L(a,a_ty)), DV(L(b,_)) when a = b && is_non_float_primitive a_ty -> LitBool true |> DLit
                | a, b ->
                    let a_ty, b_ty = data_to_ty s a, data_to_ty s b
                    if ty_eq_allow_jp_placeholders a_ty b_ty then
                        match a, b with
                        | DLit (LitBool true), x | x, DLit (LitBool true) -> x
                        | _ ->
                            let prim_ty_opt =
                                if is_primitive a_ty then Some a_ty
                                elif is_primitive b_ty then Some b_ty
                                else None
                            match prim_ty_opt with
                            | Some _ -> push_binop s EQ (a,b) (YPrim BoolT)
                            | None ->
                                raise_type_error s <| sprintf "The type of the two arguments needs to be a primitive type.\nGot: %s and %s" (show_ty a_ty) (show_ty b_ty)
                    else
                        raise_type_error s <| sprintf "The two sides need to have the same primitive types.\nGot: %s and %s." (show_ty a_ty) (show_ty b_ty)
            let default_lit s (a : string) b =
                let inline f string_to_val val_to_lit val_dsc =
                    match string_to_val a with
                    | true, x -> val_to_lit x
                    | false, _ -> raise_type_error s <| sprintf "Cannot parse the literal as: %s" val_dsc
                match b with
                | YPrim Float32T -> f Single.TryParse LitFloat32 "f32"
                | YPrim Float64T -> f Double.TryParse LitFloat64 "f64"
                | YPrim Int8T -> f SByte.TryParse LitInt8 "i8"
                | YPrim Int16T -> f Int16.TryParse LitInt16 "i16"
                | YPrim Int32T -> f Int32.TryParse LitInt32 "i32"
                | YPrim Int64T -> f Int64.TryParse LitInt64 "i64"
                | YPrim UInt8T -> f Byte.TryParse LitUInt8 "u8"
                | YPrim UInt16T -> f UInt16.TryParse LitUInt16 "u16"
                | YPrim UInt32T -> f UInt32.TryParse LitUInt32 "u32"
                | YPrim UInt64T -> f UInt64.TryParse LitUInt64 "u64"
                | b -> raise_type_error s <| sprintf "Expected a numberic type (f32,f64,i8,i16,i32,i64,u8,u16,u32,u64) as the type of literal.\nGot: %s" (show_ty b)
    

            let lit_test s a bind on_succ on_fail =
                let b = v s bind
                match a, b with
                | LitString a', DSymbol b' ->
                    if a' = b'
                    then jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_succ)
                    else jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_fail)
                | _ ->
                    if lit_to_ty a = data_to_ty s b then if_ s (eq s (DLit a) b) on_succ on_fail
                    else jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_fail)
    

            let nan_guardf32 x = if Single.IsNaN x then raise_type_error s "A 32-bit floating point operation resulting in a nan detected at compile time." else x
            let nan_guardf64 x = if Double.IsNaN x then raise_type_error s "A 64-bit floating point operation resulting in a nan detected at compile time." else x
    

            let eforall (free_vars : Scope,i,body) =
                assert (free_vars.ty.free_vars.Length = i)
                DForall(body,HopacExtensions.S.map (v s) free_vars.term.free_vars,HopacExtensions.S.map (vt s) free_vars.ty.free_vars,free_vars.term.stack_size,free_vars.ty.stack_size)
    

            let efun (free_vars : Scope,i,body,annot) =
                assert (free_vars.term.free_vars.Length = i)
                DFunction(body,annot,HopacExtensions.S.map (v s) free_vars.term.free_vars,HopacExtensions.S.map (vt s) free_vars.ty.free_vars,free_vars.term.stack_size,free_vars.ty.stack_size)

            // Union case identity may arrive either as the literal symbol itself or as
            // a runtime value whose type normalizes to the singleton symbol. Keep the
            // normalization typed: wrappers may contribute evidence, rendered text may not.
            let tryDeclaredUnionCaseName caseName =
                match jpUnionCaseSymbolResolution caseName with
                | JpUnionCaseConcreteSymbol symbol -> Some symbol
                | JpUnionCaseResolvedPlaceholder(_,_,resolvedSymbol) -> Some resolvedSymbol
                | JpUnionCasePendingPlaceholder _
                | JpUnionCaseResolvedNonSymbol _ -> None
            let rec tryDeclaredUnionCaseType depth caseTy =
                if depth >= 4 then None
                else
                    let resolvedTy =
                        caseTy
                        |> jp_method_deref_rec_placeholder
                        |> jp_type_deref_rec_placeholder
                    match resolvedTy with
                    | YSymbol caseName -> tryDeclaredUnionCaseName caseName
                    | (YNominal _ | YApply _) as indirectTy ->
                        tryDeclaredUnionCaseType (depth + 1) (nominal_type_apply s indirectTy)
                    | _ -> None
            let rec tryDeclaredUnionCaseHead = function
                | DSymbol caseName -> tryDeclaredUnionCaseName caseName
                | DV(L(_,caseTy))
                | DNominal(_,caseTy) -> tryDeclaredUnionCaseType 0 caseTy
                | DUnion(caseHead, unionType) ->
                    match tryDeclaredUnionCaseHead caseHead with
                    | Some caseName ->
                        match union_case_try_find unionType caseName with
                        | Some expectedPayloadTy when ty_eq_allow_jp_placeholders_exact_nominals expectedPayloadTy YB -> Some caseName
                        | _ -> None
                    | None -> None
                | _ -> None
    

            let enominal (r,a,b) =
                let a = term s a
                let b = ty s b
                let tryCoerceBareSymbolToExpectedUnion expectedTy value =
                    // MIGRATION: Historical runtime reached a real semantic type error at
                    // `Debug |> Some`: the outer Option constructor already knows
                    // that `Some` expects trace_level, but the inner bare union
                    // case can still arrive as DSymbol("Debug") and therefore
                    // type as string.  When the expected payload is a known union
                    // and the symbol is one of its cases, reify the symbol as that
                    // union case instead of fabricating success elsewhere.
                    let expectedTy' = jp_method_deref_rec_placeholder expectedTy
                    let expectedUnion =
                        match expectedTy' with
                        | YUnion caseUnion -> Some (expectedTy', caseUnion)
                        | YNominal _ | YApply _ ->
                            match nominal_type_apply s expectedTy' with
                            | YUnion caseUnion -> Some (expectedTy', caseUnion)
                            | _ -> None
                        | _ -> None
                    match value, expectedUnion with
                    | DSymbol caseName, Some (expectedNominalTy, caseUnion) ->
                        match union_case_try_find caseUnion caseName with
                        | Some casePayloadTy ->
                            let casePayload = ty_to_data s casePayloadTy
                            Some (DNominal(DUnion(DPair(DSymbol caseName, casePayload), caseUnion), expectedNominalTy))
                        | None -> None
                    | _ -> None
                match nominal_type_apply s b with
                | YUnion h ->
                    let buildUnionCase k v =
                        let canonicalPair = DPair(DSymbol k, v)
                        let v_ty = data_to_ty s v
                        match union_case_try_find h k with
                        | Some v_ty' when ty_eq_allow_jp_placeholders v_ty v_ty' ->
                            DNominal(DUnion(canonicalPair,h),b)
                        | Some v_ty' ->
                            match tryCoerceBareSymbolToExpectedUnion v_ty' v with
                            | Some v' when ty_eq_allow_jp_placeholders (data_to_ty s v') v_ty' ->
                                DNominal(DUnion(DPair(DSymbol k, v'),h),b)
                            | _ ->
                                raise_type_error s <|
                                    FastRuntimeFormat.format
                                        "For key %s, The type of the value does not match the union case.\nGot: %s\nGot(deref): %s\nExpected: %s\nExpected(deref): %s"
                                        [| box k; box (show_ty v_ty); box (show_ty (jp_method_deref_rec_placeholder v_ty)); box (show_ty v_ty'); box (show_ty (jp_method_deref_rec_placeholder v_ty')) |]
                        | None ->
                            raise_type_error s <| sprintf "The union does not have key %s.\nGot: %s" k (show_ty b)
                    match a with
                    | DPair(caseHead, v) ->
                        match caseHead with
                        | DSymbol originalCaseName ->
                            let caseName =
                                match jpUnionCaseSymbolResolution originalCaseName with
                                | JpUnionCaseConcreteSymbol symbol -> symbol
                                | JpUnionCaseResolvedPlaceholder(placeholderKind, originalSymbol, resolvedSymbol) ->
                                    DiagJson.emit (
                                        FastRuntimeFormat.format
                                            "{\"kind\":\"nominal_union_case_placeholder_resolved\",\"original_symbol\":%s,\"resolved_symbol\":%s,\"placeholder_kind_du\":%s,\"resolution_du\":%s,\"authority\":\"typed_jp_placeholder_cell_ready_before_union_case_lookup\",\"next\":\"lookup_resolved_union_case\"}"
                                            [| box (DiagJson.esc originalSymbol); box (DiagJson.esc resolvedSymbol); box (DiagJson.esc (jpRecPlaceholderKindText placeholderKind)); box (DiagJson.esc (jpUnionCaseSymbolResolutionText (JpUnionCaseResolvedPlaceholder(placeholderKind, originalSymbol, resolvedSymbol)))) |])
                                    resolvedSymbol
                                | JpUnionCasePendingPlaceholder _
                                | JpUnionCaseResolvedNonSymbol _ -> originalCaseName
                            buildUnionCase caseName v
                        | DV(L(_,YSymbol _)) ->
                            match tryDeclaredUnionCaseHead caseHead with
                            | Some caseName ->
                                let occurrenceCount, shouldEmit =
                                    DiagJson.sparseLogDecision "nominal_union_singleton_case_head_canonicalized" 128L
                                if shouldEmit then
                                    DiagJson.emit (
                                        FastRuntimeFormat.format
                                            "{\"kind\":\"nominal_union_singleton_case_head_canonicalized\",\"case_name\":%s,\"nominal_ty\":%s,\"occurrence_count\":%d,\"terminal_authority\":false,\"authority\":\"singleton_symbol_type_is_typed_union_constructor_identity\",\"next\":\"construct_canonical_union_pair_before_nominal_wrapping\"}"
                                            [| box (DiagJson.esc caseName); box (DiagJson.esc (show_ty b)); box occurrenceCount |])
                                buildUnionCase caseName v
                            | None ->
                                raise_type_error s <| sprintf "Expected a resolved union case symbol.\nGot: %s" (show_data caseHead)
                        | _ ->
                            match tryDeclaredUnionCaseHead caseHead with
                            | Some caseName ->
                                let caseHeadShapeText = caseHead |> jpDeclaredUnionCaseHeadShape |> jpDeclaredUnionCaseHeadShapeText
                                let occurrenceCount, shouldEmit =
                                    DiagJson.sparseLogDecision ("nominal_union_indirect_case_head_canonicalized|" + caseHeadShapeText) 128L
                                if shouldEmit then
                                    DiagJson.emit (
                                        FastRuntimeFormat.format
                                            "{\"kind\":\"nominal_union_indirect_case_head_canonicalized\",\"case_name\":%s,\"case_head_shape_du\":%s,\"nominal_ty\":%s,\"occurrence_count\":%d,\"terminal_authority\":false,\"authority\":\"typed_case_head_type_normalization_before_nominal_union_construction\",\"next\":\"construct_canonical_union_pair_before_downstream_unbox\"}"
                                            [| box (DiagJson.esc caseName); box (DiagJson.esc caseHeadShapeText); box (DiagJson.esc (show_ty b)); box occurrenceCount |])
                                buildUnionCase caseName v
                            | None ->
                                raise_type_error s <| sprintf "Expected a union case symbol.\nGot: %s" (show_data caseHead)
                    | _ -> raise_type_error s <| sprintf "Expected key/value pair.\nGot: %s" (show_data a)
                | b' ->
                    let a =
                        match a with
                        | DRecord a ->
                            a
                            |> Seq.map (fun (KeyValue ((i, k), v)) ->
                                k, ((i, k), v)
                            )
                            |> Seq.distinctBy fst
                            |> Seq.map snd
                            |> Map.ofSeq
                            |> DRecord
                        | _ -> a
    

                    let a_ty = data_to_ty s a
    

                    if ty_eq_allow_jp_placeholders a_ty b' then DNominal(a,b)
                    else raise_type_error s <| sprintf "Type error in nominal constructor.\nGot: %s\nExpected: %s" (show_ty a_ty) (show_ty b')
    

            let tryDeclaredUnionOperand value =
                let tryRawPair nominalTy caseName casePayload pair =
                    match nominal_type_apply s nominalTy with
                    | YUnion unionType ->
                        match union_case_try_find unionType caseName with
                        | Some expectedPayloadTy ->
                            let payloadTy = data_to_ty s casePayload
                            if ty_eq_allow_jp_placeholders payloadTy expectedPayloadTy then
                                let occurrenceCount, shouldEmit =
                                    DiagJson.sparseLogDecision "declared_union_raw_pair_canonicalized" 128L
                                if shouldEmit then
                                    DiagJson.emit (
                                        FastRuntimeFormat.format
                                            "{\"kind\":\"declared_union_raw_pair_canonicalized\",\"case_name\":%s,\"payload_ty\":%s,\"expected_payload_ty\":%s,\"nominal_ty\":%s,\"union_ty\":%s,\"occurrence_count\":%d,\"terminal_authority\":false,\"authority\":\"declared_nominal_type_plus_validated_union_case_payload\",\"next\":\"consume_shared_typed_union_operand_view\"}"
                                            [| box (DiagJson.esc caseName); box (DiagJson.esc (show_ty payloadTy)); box (DiagJson.esc (show_ty expectedPayloadTy)); box (DiagJson.esc (show_ty nominalTy)); box (DiagJson.esc (show_ty (YUnion unionType))); box occurrenceCount |])
                                Some (JpDeclaredUnionStaticOperand(pair, unionType))
                            else None
                        | None -> None
                    | _ -> None
                match value with
                | DNominal(DUnion(payload, unionType), _) ->
                    Some (JpDeclaredUnionStaticOperand(payload, unionType))
                | DUnion(DPair(caseHead, casePayload), unionType) ->
                    match tryDeclaredUnionCaseHead caseHead with
                    | None -> None
                    | Some caseName ->
                        match union_case_try_find unionType caseName with
                        | None -> None
                        | Some expectedPayloadTy ->
                            let payloadTy = data_to_ty s casePayload
                            if ty_eq_allow_jp_placeholders_exact_nominals payloadTy expectedPayloadTy then
                                let occurrenceCount, shouldEmit =
                                    DiagJson.sparseLogDecision "declared_union_raw_static_operand_canonicalized" 128L
                                if shouldEmit then
                                    DiagJson.emit (
                                        FastRuntimeFormat.format
                                            "{\"kind\":\"declared_union_raw_static_operand_canonicalized\",\"case_name\":%s,\"payload_ty\":%s,\"expected_payload_ty\":%s,\"union_ty\":%s,\"occurrence_count\":%d,\"terminal_authority\":false,\"authority\":\"raw_union_object_plus_typed_case_and_exact_payload\",\"next\":\"consume_canonical_typed_union_operand_without_nominal_text_inference\"}"
                                            [| box (DiagJson.esc caseName); box (DiagJson.esc (show_ty payloadTy)); box (DiagJson.esc (show_ty expectedPayloadTy)); box (DiagJson.esc (show_ty (YUnion unionType))); box occurrenceCount |])
                                Some (JpDeclaredUnionStaticOperand(DPair(DSymbol caseName, casePayload), unionType))
                            else None
                | DNominal(DV(L(_,YUnion unionType) & variable), _) ->
                    Some (JpDeclaredUnionRuntimeOperand(variable, unionType))
                | DNominal(DPair(caseHead, casePayload), nominalTy) ->
                    match tryDeclaredUnionCaseHead caseHead with
                    | None -> None
                    | Some caseName ->
                        match caseHead with
                        | DV(L(_,YSymbol _)) ->
                            let occurrenceCount, shouldEmit =
                                DiagJson.sparseLogDecision "declared_union_singleton_case_head_canonicalized" 128L
                            if shouldEmit then
                                DiagJson.emit (
                                    FastRuntimeFormat.format
                                        "{\"kind\":\"declared_union_singleton_case_head_canonicalized\",\"case_name\":%s,\"nominal_ty\":%s,\"occurrence_count\":%d,\"terminal_authority\":false,\"authority\":\"singleton_symbol_type_is_typed_union_case_identity\",\"next\":\"canonicalize_case_head_then_validate_nominal_union_payload\"}"
                                        [| box (DiagJson.esc caseName); box (DiagJson.esc (show_ty nominalTy)); box occurrenceCount |])
                        | _ -> ()
                        let pair = DPair(DSymbol caseName, casePayload)
                        tryRawPair nominalTy caseName casePayload pair
                | _ -> None

            let declaredUnionOperandType = function
                | JpDeclaredUnionStaticOperand(_, unionType)
                | JpDeclaredUnionRuntimeOperand(_, unionType) -> unionType

            let declaredUnionNominalRootTag nominalTy =
                let mutable current = nominalTy
                let mutable rootTag = -1
                let mutable searching = true
                while searching do
                    match current with
                    | YNominal nominal ->
                        rootTag <- nominal.tag
                        searching <- false
                    | YApply(headTy, _) ->
                        current <- headTy
                    | _ ->
                        searching <- false
                rootTag

            let tryDeclaredUnionOperandFromPeer peerValue peerOperand candidateValue =
                let peerUnionType = declaredUnionOperandType peerOperand
                let emit disposition caseName candidateNominalTy peerNominalTy payloadTy expectedPayloadTy =
                    let dispositionText = jpDeclaredUnionPeerNormalizationDispositionText disposition
                    let occurrenceCount, shouldEmit =
                        DiagJson.sparseLogDecision ("declared_union_peer_raw_pair_resolution|" + dispositionText) 128L
                    if shouldEmit then
                        DiagJson.emit (
                            FastRuntimeFormat.format
                                "{\"kind\":\"declared_union_peer_raw_pair_resolution\",\"disposition_du\":%s,\"case_name\":%s,\"candidate_nominal_ty\":%s,\"peer_nominal_ty\":%s,\"candidate_nominal_root_tag\":%d,\"peer_nominal_root_tag\":%d,\"payload_ty\":%s,\"expected_payload_ty\":%s,\"peer_union_ty\":%s,\"occurrence_count\":%d,\"terminal_authority\":false,\"authority\":\"exact_peer_declared_nominal_identity_plus_validated_union_case_payload\",\"next\":\"consume_peer_union_only_when_outer_nominal_identity_and_payload_contract_match\"}"
                                [| box (DiagJson.esc dispositionText); box (DiagJson.esc caseName); box (DiagJson.esc (show_ty candidateNominalTy)); box (DiagJson.esc (show_ty peerNominalTy)); box (declaredUnionNominalRootTag candidateNominalTy); box (declaredUnionNominalRootTag peerNominalTy); box (DiagJson.esc payloadTy); box (DiagJson.esc expectedPayloadTy); box (DiagJson.esc (show_ty (YUnion peerUnionType))); box occurrenceCount |])
                let tryCandidate peerNominalTy candidateNominalTy caseHead casePayload =
                    match tryDeclaredUnionCaseHead caseHead with
                    | None -> None
                    | Some caseName ->
                        let pair = DPair(DSymbol caseName, casePayload)
                        if not (ty_eq_allow_jp_placeholders_exact_nominals candidateNominalTy peerNominalTy) then
                            emit JpDeclaredUnionPeerNominalMismatch caseName candidateNominalTy peerNominalTy "unread" "unread"
                            None
                        else
                            match union_case_try_find peerUnionType caseName with
                            | None ->
                                emit JpDeclaredUnionPeerCaseMissing caseName candidateNominalTy peerNominalTy (show_ty (data_to_ty s casePayload)) "missing"
                                None
                            | Some expectedPayloadTy ->
                                let payloadTy = data_to_ty s casePayload
                                if ty_eq_allow_jp_placeholders_exact_nominals payloadTy expectedPayloadTy then
                                    emit JpDeclaredUnionPeerRecovered caseName candidateNominalTy peerNominalTy (show_ty payloadTy) (show_ty expectedPayloadTy)
                                    Some (JpDeclaredUnionStaticOperand(pair, peerUnionType))
                                else
                                    emit JpDeclaredUnionPeerPayloadMismatch caseName candidateNominalTy peerNominalTy (show_ty payloadTy) (show_ty expectedPayloadTy)
                                    None
                match peerValue, candidateValue with
                | DNominal(_, peerNominalTy), DNominal(DPair(caseHead, casePayload), candidateNominalTy)
                | DNominal(_, peerNominalTy), DPair(caseHead, DNominal(casePayload, candidateNominalTy)) ->
                    tryCandidate peerNominalTy candidateNominalTy caseHead casePayload
                | _ -> None


            let defer_jp_type_placeholder_projection operationId operationExpr typeExpr placeholderTy =
                let operationNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(box operationExpr)
                let typeNodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(box typeExpr)
                let origin = EvalReplayValueStore.EvaluatorPatternMissTypeProducer(operationNodeId, typeNodeId)
                let decision =
                    EvalReplayValueStore.EvaluatorPatternMissDeferredFailure(
                        EvalReplayValueStore.EvaluatorPatternMissUnresolvedJpTypePlaceholder placeholderTy)
                let reservation =
                    EvalReplayValueStore.evaluatorPatternMissReserveDependency
                        (CacheGeneration.current())
                        operationNodeId
                        (EvalReplayValueStore.EvaluatorPatternMissTypeDependency typeNodeId)
                let signal = EvalReplayValueStore.evaluatorPatternMissDeferredSignal origin decision reservation
                let placeholderKind =
                    match tryDecodeJpRecPlaceholder placeholderTy with
                    | Some kind -> jpRecPlaceholderKindText kind
                    | None -> "unknown"
                DiagJson.emit (
                    FastRuntimeFormat.format
                        "{\"kind\":\"jp_type_placeholder_projection_deferred\",\"operation_du\":%s,\"operation_node_id\":%d,\"type_node_id\":%d,\"placeholder_ty\":%s,\"placeholder_kind_du\":%s,\"decision_du\":%s,\"reservation_du\":%s,\"fabricated_union_case\":false,\"terminal_authority\":false,\"authority\":\"typed_pending_jp_type_projection_deferral\",\"next\":\"requeue_until_exact_jp_type_cell_materializes\"}"
                        [| box (DiagJson.esc (jpTypePlaceholderProjectionOperationText operationId)); box operationNodeId; box typeNodeId; box (DiagJson.esc (show_ty placeholderTy)); box (DiagJson.esc placeholderKind); box (DiagJson.esc (EvalReplayValueStore.evaluatorPatternMissDecisionText decision)); box (DiagJson.esc (EvalReplayValueStore.evaluatorPatternMissDeferralReservationText reservation)) |])
                EvalReplayValueStore.evaluatorPatternMissBreakthroughEscapeTransport signal

            let ty_union_cases s operationExpr typeExpr =
                let sourceTy = ty s typeExpr
                let resolvedTy =
                    sourceTy
                    |> jp_method_deref_rec_placeholder
                    |> jp_type_deref_rec_placeholder
                match tryDecodeJpRecPlaceholder sourceTy with
                | Some _ when resolvedTy = sourceTy ->
                    defer_jp_type_placeholder_projection JpTypePlaceholderProjectionUnionToRecord operationExpr typeExpr sourceTy
                | Some _ ->
                    DiagJson.emit (
                        FastRuntimeFormat.format
                            "{\"kind\":\"union_to_record_placeholder_resolved_before_projection\",\"source_ty\":%s,\"resolved_ty\":%s,\"authority\":\"typed_jp_placeholder_cell_ready_before_union_case_projection\",\"next\":\"project_resolved_union_shape\"}"
                            [| box (DiagJson.esc (show_ty sourceTy)); box (DiagJson.esc (show_ty resolvedTy)) |])
                | _ -> ()
                let disposition, cases =
                    match nominal_type_apply s resolvedTy with
                    | YUnion union ->
                        UnionToRecordConcreteUnion, union.Item.cases
                    | (YSymbol symbol as projectedTy) ->
                        match tryDecodeJpRecPlaceholder projectedTy with
                        | Some _ ->
                            // The placeholder can be exposed only after nominal_type_apply even when
                            // sourceTy itself is nominal. Keep projection pending instead of persisting
                            // a synthetic reflection key derived from the producer's temporary shell.
                            defer_jp_type_placeholder_projection JpTypePlaceholderProjectionUnionToRecord operationExpr typeExpr projectedTy
                        | None ->
                            // A genuine resolved type-level symbol is a singleton zero-payload union.
                            let cases = Map.empty |> Map.add (0, symbol) YB
                            UnionToRecordSingletonSymbol symbol, cases
                    | _ ->
                        raise_type_error s <| sprintf "Expected an union.\nGot: %s" (show_ty resolvedTy)
                match disposition with
                | UnionToRecordSingletonSymbol caseName ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"union_to_record_singleton_symbol_normalized\",\"case_name\":%s,\"disposition_du\":%s,\"payload_type_du\":\"Unit\",\"authority\":\"type_level_symbol_is_singleton_degenerate_union\",\"next\":\"apply_union_case_record_to_success_continuation\"}"
                            (DiagJson.esc caseName)
                            (DiagJson.esc (unionToRecordTypeDispositionText disposition)))
                | UnionToRecordConcreteUnion -> ()
                cases
    

            let ty_record s x =
                match ty s x with
                | YRecord l -> l
                | x -> raise_type_error s <| sprintf "Expected a type record.\nGot: %s" (show_ty x)
    

            let to_i32 x =
                try
                    match x with
                    | LitUInt8 x -> Convert.ToInt32(x)
                    | LitUInt16 x -> Convert.ToInt32(x)
                    | LitUInt32 x -> Convert.ToInt32(x)
                    | LitUInt64 x -> Convert.ToInt32(x)
                    | LitInt8 x -> Convert.ToInt32(x)
                    | LitInt16 x -> Convert.ToInt32(x)
                    | LitInt32 x -> Convert.ToInt32(x)
                    | LitInt64 x -> Convert.ToInt32(x)
                    | x -> raise_type_error s <| sprintf "Expected an int convertible to an i32.\nGot: %s" (show_lit x)
                with :? System.OverflowException -> raise_type_error s <| sprintf "The literal cannot be converted to an i32 as it is either too small or to big.\nGot: %s" (show_lit x)
    

            let record2 (a,b) (a',b') = DRecord(Map.empty |> Map.add a b |> Map.add a' b')
            let record3 (a,b) (a',b') (a'',b'') = DRecord(Map.empty |> Map.add a b |> Map.add a' b' |> Map.add a'' b'')

            EvalReplayValueStore.installTypeAwareOpReplayAfterDefinition (fun sObj op argNodeIds ->
                let s = unbox<LangEnv> sObj
                let opText = opStableText op
                let termAt i =
                    if i >= 0 && i < argNodeIds.Length then EvalReplayValueStore.tryTerm argNodeIds.[i]
                    else None
                let typeAt i =
                    if i >= 0 && i < argNodeIds.Length then EvalReplayValueStore.tryType argNodeIds.[i]
                    else None
                let typeLitToData t =
                    let mutable current = t
                    let mutable finished = false
                    let mutable result = Choice2Of2 "type_lit_uninitialized"
                    while not finished do
                        match current with
                        | YLit literal ->
                            result <- Choice1Of2 (DLit literal)
                            finished <- true
                        | YSymbol symbol ->
                            result <- Choice1Of2 (DSymbol symbol)
                            finished <- true
                        | YNominal _ | YApply _ ->
                            current <- nominal_type_apply s current
                        | invalid ->
                            result <- Choice2Of2 (sprintf "type_lit_expected_lit_or_symbol:%s" (show_ty invalid))
                            finished <- true
                    result
                let recordTyAt i =
                    let asRecordType source ty =
                        match ty with
                        | YRecord fields -> Choice1Of2 fields
                        | YNominal _ | YApply _ ->
                            match nominal_type_apply s ty with
                            | YRecord fields -> Choice1Of2 fields
                            | other -> Choice2Of2 (sprintf "expected_record_type_%s:%s" source (show_ty other))
                        | other -> Choice2Of2 (sprintf "expected_record_type_%s:%s" source (show_ty other))
                    match typeAt i with
                    | Some ty -> asRecordType "type_store" ty
                    | None ->
                        match termAt i with
                        | Some value ->
                            try
                                let result = asRecordType "term_store" (data_to_ty s value)
                                match result with
                                | Choice1Of2 fields ->
                                    DiagJson.emit (
                                        sprintf "{\"kind\":\"eval_worklist_record_type_recovered_from_term_store\",\"arg_index\":%d,\"field_count\":%d,\"single_flight\":1,\"next\":\"continue_record_type_op_replay\"}"
                                            i fields.Count)
                                | Choice2Of2 _ -> ()
                                result
                            with ex -> Choice2Of2 (sprintf "type_arg_missing_term_store_uncoercible:%s" (ex.GetType().Name))
                        | None -> Choice2Of2 "type_arg_missing"
                let compactOpExn (ex: exn) =
                    let msg =
                        if isNull ex.Message then ""
                        else ex.Message.Replace("\r"," ").Replace("\n"," ").Replace("\t"," ")
                    let msg = if msg.Length > 180 then msg.Substring(0, 180) + "..." else msg
                    ex.GetType().Name + ":" + msg
                let typeAwareReplayUnwrapNominalData data =
                    let mutable current = data
                    let mutable unwrapped = false
                    while not unwrapped do
                        match current with
                        | DNominal(inner, _) -> current <- inner
                        | _ -> unwrapped <- true
                    current
                let typeAwareReplayTryCompareLiteral (op: Op) a b =
                    let out x = Some (DLit (LitBool x))
                    match op, a, b with
                    | EQ, LitInt8 a, LitInt8 b -> out (a = b)
                    | NEQ, LitInt8 a, LitInt8 b -> out (a <> b)
                    | EQ, LitInt16 a, LitInt16 b -> out (a = b)
                    | NEQ, LitInt16 a, LitInt16 b -> out (a <> b)
                    | EQ, LitInt32 a, LitInt32 b -> out (a = b)
                    | NEQ, LitInt32 a, LitInt32 b -> out (a <> b)
                    | EQ, LitInt64 a, LitInt64 b -> out (a = b)
                    | NEQ, LitInt64 a, LitInt64 b -> out (a <> b)
                    | EQ, LitUInt8 a, LitUInt8 b -> out (a = b)
                    | NEQ, LitUInt8 a, LitUInt8 b -> out (a <> b)
                    | EQ, LitUInt16 a, LitUInt16 b -> out (a = b)
                    | NEQ, LitUInt16 a, LitUInt16 b -> out (a <> b)
                    | EQ, LitUInt32 a, LitUInt32 b -> out (a = b)
                    | NEQ, LitUInt32 a, LitUInt32 b -> out (a <> b)
                    | EQ, LitUInt64 a, LitUInt64 b -> out (a = b)
                    | NEQ, LitUInt64 a, LitUInt64 b -> out (a <> b)
                    | EQ, LitFloat32 a, LitFloat32 b -> out (a = b)
                    | NEQ, LitFloat32 a, LitFloat32 b -> out (a <> b)
                    | EQ, LitFloat64 a, LitFloat64 b -> out (a = b)
                    | NEQ, LitFloat64 a, LitFloat64 b -> out (a <> b)
                    | EQ, LitChar a, LitChar b -> out (a = b)
                    | NEQ, LitChar a, LitChar b -> out (a <> b)
                    | EQ, LitString a, LitString b -> out (a = b)
                    | NEQ, LitString a, LitString b -> out (a <> b)
                    | EQ, LitBool a, LitBool b -> out (a = b)
                    | NEQ, LitBool a, LitBool b -> out (a <> b)
                    | LT, LitInt8 a, LitInt8 b -> out (a < b)
                    | LTE, LitInt8 a, LitInt8 b -> out (a <= b)
                    | GT, LitInt8 a, LitInt8 b -> out (a > b)
                    | GTE, LitInt8 a, LitInt8 b -> out (a >= b)
                    | LT, LitInt16 a, LitInt16 b -> out (a < b)
                    | LTE, LitInt16 a, LitInt16 b -> out (a <= b)
                    | GT, LitInt16 a, LitInt16 b -> out (a > b)
                    | GTE, LitInt16 a, LitInt16 b -> out (a >= b)
                    | LT, LitInt32 a, LitInt32 b -> out (a < b)
                    | LTE, LitInt32 a, LitInt32 b -> out (a <= b)
                    | GT, LitInt32 a, LitInt32 b -> out (a > b)
                    | GTE, LitInt32 a, LitInt32 b -> out (a >= b)
                    | LT, LitInt64 a, LitInt64 b -> out (a < b)
                    | LTE, LitInt64 a, LitInt64 b -> out (a <= b)
                    | GT, LitInt64 a, LitInt64 b -> out (a > b)
                    | GTE, LitInt64 a, LitInt64 b -> out (a >= b)
                    | LT, LitUInt8 a, LitUInt8 b -> out (a < b)
                    | LTE, LitUInt8 a, LitUInt8 b -> out (a <= b)
                    | GT, LitUInt8 a, LitUInt8 b -> out (a > b)
                    | GTE, LitUInt8 a, LitUInt8 b -> out (a >= b)
                    | LT, LitUInt16 a, LitUInt16 b -> out (a < b)
                    | LTE, LitUInt16 a, LitUInt16 b -> out (a <= b)
                    | GT, LitUInt16 a, LitUInt16 b -> out (a > b)
                    | GTE, LitUInt16 a, LitUInt16 b -> out (a >= b)
                    | LT, LitUInt32 a, LitUInt32 b -> out (a < b)
                    | LTE, LitUInt32 a, LitUInt32 b -> out (a <= b)
                    | GT, LitUInt32 a, LitUInt32 b -> out (a > b)
                    | GTE, LitUInt32 a, LitUInt32 b -> out (a >= b)
                    | LT, LitUInt64 a, LitUInt64 b -> out (a < b)
                    | LTE, LitUInt64 a, LitUInt64 b -> out (a <= b)
                    | GT, LitUInt64 a, LitUInt64 b -> out (a > b)
                    | GTE, LitUInt64 a, LitUInt64 b -> out (a >= b)
                    | LT, LitFloat32 a, LitFloat32 b -> out (a < b)
                    | LTE, LitFloat32 a, LitFloat32 b -> out (a <= b)
                    | GT, LitFloat32 a, LitFloat32 b -> out (a > b)
                    | GTE, LitFloat32 a, LitFloat32 b -> out (a >= b)
                    | LT, LitFloat64 a, LitFloat64 b -> out (a < b)
                    | LTE, LitFloat64 a, LitFloat64 b -> out (a <= b)
                    | GT, LitFloat64 a, LitFloat64 b -> out (a > b)
                    | GTE, LitFloat64 a, LitFloat64 b -> out (a >= b)
                    | LT, LitChar a, LitChar b -> out (a < b)
                    | LTE, LitChar a, LitChar b -> out (a <= b)
                    | GT, LitChar a, LitChar b -> out (a > b)
                    | GTE, LitChar a, LitChar b -> out (a >= b)
                    | LT, LitString a, LitString b -> out (a < b)
                    | LTE, LitString a, LitString b -> out (a <= b)
                    | GT, LitString a, LitString b -> out (a > b)
                    | GTE, LitString a, LitString b -> out (a >= b)
                    | LT, LitBool a, LitBool b -> out (a < b)
                    | LTE, LitBool a, LitBool b -> out (a <= b)
                    | GT, LitBool a, LitBool b -> out (a > b)
                    | GTE, LitBool a, LitBool b -> out (a >= b)
                    | _ -> None
                let replayStringIndex () =
                    match termAt 0, termAt 1 with
                    | Some (DLit (LitString str)), Some (DLit idxLit) ->
                        try
                            let idx = to_i32 idxLit
                            if 0 <= idx && idx < str.Length then
                                let value = DLit (LitChar str.[idx])
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_aware_string_index_literal_replay_resolved\",\"context_node_id\":%d,\"index\":%d,\"string_len\":%d,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}" [| box -1; box idx; box str.Length |])
                                Choice1Of2 value
                            else Choice2Of2 (sprintf "string_index_literal_oob:index=%d:length=%d" idx str.Length)
                        with ex -> Choice2Of2 ("string_index_literal_replay_failed:" + compactOpExn ex)
                    | Some a, Some b ->
                        try
                            let at, bt = data_to_ty s a, data_to_ty s b
                            if is_string_allow_jp_placeholders at && is_any_int_allow_jp_placeholders bt then
                                let value = push_binop s StringIndex (a, b) (YPrim CharT)
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_aware_string_index_replay_resolved\",\"context_node_id\":%d,\"lhs_ty\":%s,\"rhs_ty\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}" [| box -1; box (DiagJson.esc (show_ty at)); box (DiagJson.esc (show_ty bt)) |])
                                Choice1Of2 value
                            else Choice2Of2 (sprintf "string_index_expected_string_int:%s:%s" (show_ty at) (show_ty bt))
                        with ex -> Choice2Of2 ("string_index_replay_failed:" + compactOpExn ex)
                    | None, _ -> Choice2Of2 "string_index_string_arg_missing"
                    | _, None -> Choice2Of2 "string_index_index_arg_missing"

                let replayBackendSwitch (unsafeMode: bool) =
                    match termAt 0 with
                    | Some (DRecord l) ->
                        if unsafeMode then
                            try
                                match map_try_find_by_string s.backend.node l with
                                | Some b -> Choice1Of2 (apply s (b, DB))
                                | None -> Choice2Of2 (sprintf "backend_switch_backend_missing:%s" s.backend.node)
                            with ex -> Choice2Of2 ("unsafe_backend_switch_apply_failed:" + compactOpExn ex)
                        else
                            try
                                let mutable t = None
                                let mutable d = None
                                let normalize_backend_switch_ty x =
                                    jp_method_deref_rec_placeholder x
                                let validate_type t' =
                                    let t' = normalize_backend_switch_ty t'
                                    match t with
                                    | Some t0 ->
                                        let t0 = normalize_backend_switch_ty t0
                                        if not (ty_eq_allow_jp_placeholders t0 t') then
                                            raise_type_error s $"The backend switch needs to have the same type for all of its branches.\nGot: {show_ty t'}\nExpected: {show_ty t0}"
                                    | None -> t <- Some t'
                                if lock backend_switch_lock (fun () -> backend_switch_validate_all.Value) = false then
                                    match map_try_find_by_string s.backend.node l with
                                    | Some b ->
                                        let d' = apply s (b, DB)
                                        validate_type (data_to_ty s d')
                                        d <- Some d'
                                    | None -> ()
                                else
                                    l |> Map.iter (fun (_,backend) b ->
                                        if backend = s.backend.node then
                                            let d' = apply s (b, DB)
                                            validate_type (data_to_ty s d')
                                            d <- Some d'
                                        else
                                            let stackDecision = evalStackProbeDecision ()
                                            let gen0 = CacheGeneration.current ()
                                            let doValidation () =
                                                let old = lock backend_switch_lock (fun () -> backend_switch_validate_all.Value)
                                                lock backend_switch_lock (fun () -> backend_switch_validate_all.Value <- false)
                                                try
                                                    let s = {s with seq=ResizeArray(); cse=System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural) :: s.cse; backend=lock backend_strings_lock (fun () -> backend_strings.Add backend)}
                                                    let d' = apply s (b, DB)
                                                    if CacheGeneration.isStale gen0 then
                                                        DiagSidecar.emit (sprintf "BACKEND_SWITCH_REPLAY: Generation changed during backend_switch replay validation for '%s' - skipping type check" backend)
                                                    else
                                                        validate_type (data_to_ty s d')
                                                finally
                                                    lock backend_switch_lock (fun () -> backend_switch_validate_all.Value <- old)
                                            if CacheGeneration.isStale gen0 then
                                                DiagSidecar.emit (sprintf "BACKEND_SWITCH_REPLAY: Skipping backend_switch replay validation for '%s' (generation stale)" backend)
                                            else
                                                match stackDecision with
                                                | EvalStackProbeAvailable -> doValidation ()
                                                | EvalStackProbeInsufficient ->
                                                    match BigStack.tryRun s.bigStack BigStack.BigStackBackendSwitchReplayValidate "backend_switch_replay_validate" (fun _ -> doValidation ()) with
                                                    | Some () -> ()
                                                    | None -> DiagSidecar.emit (sprintf "BACKEND_SWITCH_REPLAY: Skipping backend_switch replay validation for '%s' (stack exhausted, BigStack unavailable)" backend)
                                        )
                                match d with
                                | Some cur -> Choice1Of2 cur
                                | None -> Choice2Of2 (sprintf "backend_switch_backend_missing:%s" s.backend.node)
                            with ex -> Choice2Of2 ("backend_switch_apply_failed:" + compactOpExn ex)
                    | Some other -> Choice2Of2 (sprintf "backend_switch_expected_record:%s" (show_data other))
                    | None -> Choice2Of2 "backend_switch_arg_missing"
                let replayUnionUntag () =
                    let decisionText d = EvalReplayValueStore.typeAwareUnionUntagReplayDecisionText d
                    let emitDecision d detail =
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_union_untag_type_aware_replay_decision\",\"op\":\"UnionUntag\",\"context_node_id\":%d,\"decision_du\":%s,\"detail\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved_or_fail_closed\"}" [| box -1; box (DiagJson.esc (decisionText d)); box (DiagJson.esc detail) |])
                    match typeAt 0, termAt 1, termAt 2, termAt 3 with
                    | Some t, Some tagData, Some onSucc, Some onFail ->
                        match nominal_type_apply s t with
                        | YUnion h ->
                            let h = h.Item
                            let literalTag i =
                                if 0 <= i && i < h.tag_cases.Length then
                                    let k, v = h.tag_cases.[i]
                                    try
                                        let value = type_apply s (apply s (onSucc, DSymbol k)) v
                                        emitDecision EvalReplayValueStore.TypeAwareUnionUntagDirectLiteralTag (sprintf "%s/%d" k i)
                                        Choice1Of2 value
                                    with ex ->
                                        emitDecision EvalReplayValueStore.TypeAwareUnionUntagBranchReplayFailed (compactOpExn ex)
                                        Choice2Of2 ("union_untag_literal_branch_failed:" + compactOpExn ex)
                                else
                                    let detail = sprintf "tag=%d bounds=0..%d" i (h.tag_cases.Length - 1)
                                    emitDecision EvalReplayValueStore.TypeAwareUnionUntagTagOutOfRange detail
                                    Choice2Of2 ("union_untag_tag_out_of_range:" + detail)
                            let runtimeSwitch (tyv: TyV) (tagForKey: Data) =
                                try
                                    let key = TyOp(UnionUntag, [tagForKey])
                                    match cse_tryfind s key with
                                    | Some (DLit (LitInt32 i)) -> literalTag i
                                    | Some other ->
                                        let detail = sprintf "cached_non_i32:%s" (show_data other)
                                        emitDecision EvalReplayValueStore.TypeAwareUnionUntagMalformedTag detail
                                        Choice2Of2 ("union_untag_cached_non_i32:" + detail)
                                    | None ->
                                        let onFailValue, onFailTy =
                                            let sFail = {s with cse = System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural) :: s.cse; seq = ResizeArray()}
                                            let r = apply sFail (onFail, DB) |> dyn false sFail
                                            seq_apply sFail r, data_to_ty sFail r
                                        let onSuccCases =
                                            HopacExtensions.S.mapi (fun i (k, v) ->
                                                let cse = System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural)
                                                cse.TryAdd(key, DLit (LitInt32 i)) |> ignore
                                                let sCase = {s with cse = cse :: s.cse; seq = ResizeArray()}
                                                let r = type_apply sCase (apply sCase (onSucc, DSymbol k)) v |> dyn false sCase
                                                let rTy = data_to_ty sCase r
                                                if onFailTy <> rTy then
                                                    emitDecision EvalReplayValueStore.TypeAwareUnionUntagBranchTypeMismatch (FastRuntimeFormat.format "%s got=%s expected=%s" [| box k; box (show_ty rTy); box (show_ty onFailTy) |])
                                                    raise_type_error sCase <| FastRuntimeFormat.format "Return type of the UnionUntag success case %s does not match the failure one.\nGot: %s\nExpected: %s" [| box k; box (show_ty rTy); box (show_ty onFailTy) |]
                                                seq_apply sCase r
                                                ) h.tag_cases
                                        let value = push_typedop_no_rewrite s (TyIntSwitch(tyv, onSuccCases, onFailValue)) onFailTy
                                        emitDecision EvalReplayValueStore.TypeAwareUnionUntagRuntimeTagSwitch (sprintf "cases=%d" h.tag_cases.Length)
                                        Choice1Of2 value
                                with ex ->
                                    emitDecision EvalReplayValueStore.TypeAwareUnionUntagBranchReplayFailed (compactOpExn ex)
                                    Choice2Of2 ("union_untag_runtime_switch_failed:" + compactOpExn ex)
                            match tagData with
                            | DLit (LitInt32 i) -> literalTag i
                            | DV(L(_, YPrim Int32T) as tyv) as tagForKey -> runtimeSwitch tyv tagForKey
                            | DNominal((DV(L(_, YPrim Int32T) as tyv) as tagForKey), _) -> runtimeSwitch tyv tagForKey
                            | other ->
                                let detail = sprintf "expected_i32_tag:%s" (show_data other)
                                emitDecision EvalReplayValueStore.TypeAwareUnionUntagMalformedTag detail
                                Choice2Of2 ("union_untag_expected_i32_tag:" + detail)
                        | other ->
                            let detail = sprintf "expected_union_type:%s" (show_ty other)
                            emitDecision EvalReplayValueStore.TypeAwareUnionUntagMissingUnionType detail
                            Choice2Of2 ("union_untag_expected_union_type:" + detail)
                    | _ ->
                        emitDecision EvalReplayValueStore.TypeAwareUnionUntagMissingArgs "type/tag/success/fail"
                        Choice2Of2 "union_untag_args_missing"

                let replayPrototypeHas () =
                    let replayContextNodeId = if argNodeIds.Length > 0 then argNodeIds.[0] else -1
                    let emitPrototypeDecision decisionId detail =
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":%s,\"context_node_id\":%d,\"decision_du\":%s,\"detail\":%s,\"single_flight\":1,\"next\":\"prototype_has_replay_decision\"}" [| box (DiagJson.esc (EvalReplayValueStore.typeAwarePrototypeHasReplayDecisionKind decisionId)); box replayContextNodeId; box (DiagJson.esc (EvalReplayValueStore.typeAwarePrototypeHasReplayDecisionText decisionId)); box (DiagJson.esc detail) |])
                    let prototypeFail decisionId detail =
                        emitPrototypeDecision decisionId detail
                        Choice2Of2 ("prototype_has_replay_blocked:" + EvalReplayValueStore.typeAwarePrototypeHasReplayDecisionText decisionId + ":" + detail)
                    let nominalRoot (tyArg: Ty) : Choice<Nominal,string> =
                        let mutable current = tyArg
                        let mutable nominal = None
                        let mutable invalid = None
                        while Option.isNone nominal && Option.isNone invalid do
                            match current with
                            | YNominal value -> nominal <- Some value
                            | YApply(left,_) -> current <- left
                            | other -> invalid <- Some other
                        match nominal, invalid with
                        | Some value, _ -> Choice1Of2 value
                        | _, Some other -> Choice2Of2 ("expected_nominal_type:" + show_ty other)
                        | _ -> Choice2Of2 "expected_nominal_type:unreachable"
                    let prototypeBodyHas (nominal: Nominal) (body: E) : Choice<Data,string> =
                        let mutable current = body
                        let mutable result = None
                        while Option.isNone result do
                            match current with
                            | EForall'(_,_,_,next) -> current <- next
                            | EPrototypeApply(_, protId, _) ->
                                let prototypeKey = (protId, nominal.node.id)
                                let hasPrototype = env.prototypes_instances.ContainsKey(prototypeKey)
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_aware_prototype_has_replay_resolved\",\"context_node_id\":%d,\"decision_du\":%s,\"prototype_id\":%s,\"nominal_id\":%s,\"result\":%b,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}" [| box replayContextNodeId; box (DiagJson.esc (EvalReplayValueStore.typeAwarePrototypeHasReplayDecisionText EvalReplayValueStore.TypeAwarePrototypeHasResolved)); box (DiagJson.esc (globalIdStableText protId)); box (DiagJson.esc (globalIdStableText nominal.node.id)); box hasPrototype |])
                                result <- Some (Choice1Of2 (DLit (LitBool hasPrototype)))
                            | other ->
                                result <- Some (prototypeFail EvalReplayValueStore.TypeAwarePrototypeHasExpectedPrototypeBody (evalNodeShapeTerm other))
                        result.Value
                    match termAt 0, typeAt 1 with
                    | Some (DForall(body,_,_,_,_)), Some tyArg ->
                        match nominalRoot tyArg with
                        | Choice1Of2 nominal -> prototypeBodyHas nominal body
                        | Choice2Of2 detail -> prototypeFail EvalReplayValueStore.TypeAwarePrototypeHasExpectedNominalType detail
                    | Some other, Some _ -> prototypeFail EvalReplayValueStore.TypeAwarePrototypeHasExpectedForallTerm (show_data other)
                    | None, _ -> prototypeFail EvalReplayValueStore.TypeAwarePrototypeHasTermMissing "prototype_term_missing"
                    | _, None -> prototypeFail EvalReplayValueStore.TypeAwarePrototypeHasTypeArgMissing "nominal_type_arg_missing"

                match op with
                | UnionUntag -> replayUnionUntag ()
                | PrototypeHas -> replayPrototypeHas ()
                | StringIndex -> replayStringIndex ()
                | BackendSwitch -> replayBackendSwitch false
                | UnsafeBackendSwitch -> replayBackendSwitch true
                | Global ->
                    match termAt 0 with
                    | Some (DLit (LitString text) as a) ->
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_global_replay_resolved\",\"op\":\"Global\",\"text_len\":%d,\"same_backend\":%b,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                text.Length (s.backend.node = env.backend))
                        if s.backend.node = env.backend then
                            global' text |> ignore
                        Choice1Of2 (push_op_no_rewrite s Global a YB)
                    | Some other -> Choice2Of2 (sprintf "global_expected_string_lit:%s" (show_data other))
                    | None -> Choice2Of2 "global_arg_missing"
                | LayoutIndex ->
                    match termAt 0 with
                    | Some (DV(L(_,YLayout(ty,layout)) as tyv)) ->
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_layout_index_replay_resolved\",\"op\":\"LayoutIndex\",\"context_node_id\":%d,\"layout\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                -1 (DiagJson.esc (show_layout_type layout)))
                        match layout with
                        | StackMutable | HeapMutable -> Choice1Of2 (push_typedop_no_rewrite s (TyLayoutIndexAll tyv) ty)
                        | Heap ->
                            match ty with
                            | YRecord l -> Choice1Of2 (DRecord(Map.map (fun (_,b) ty -> push_typedop s (TyLayoutIndexByKey(tyv,LayoutFieldNameIdOps.create b)) ty) l))
                            | _ -> Choice1Of2 (push_typedop s (TyLayoutIndexAll tyv) ty)
                    | Some other -> Choice2Of2 (sprintf "layout_index_expected_layout:%s" (show_data other))
                    | None -> Choice2Of2 "layout_index_arg_missing"
                | TypeToVar ->
                    match typeAt 0 with
                    | Some t -> Choice1Of2 (push_typedop_no_rewrite s (TyOp(TypeToVar,[])) t)
                    | None -> Choice2Of2 "type_to_var_type_missing"
                | TypeToSymbol ->
                    match typeAt 0 with
                    | Some (YSymbol a) -> Choice1Of2 (DSymbol a)
                    | Some a -> Choice2Of2 (sprintf "type_to_symbol_expected_symbol:%s" (show_ty a))
                    | None -> Choice2Of2 "type_to_symbol_type_missing"
                | TypeLitToLit ->
                    match typeAt 0 with
                    | Some t -> typeLitToData t
                    | None -> Choice2Of2 "type_lit_to_lit_type_missing"
                | RecordTypeLength ->
                    match recordTyAt 0 with
                    | Choice1Of2 fields -> Choice1Of2 (Map.count fields |> LitInt32 |> DLit)
                    | Choice2Of2 detail -> Choice2Of2 detail
                | RecordTypeTryFind ->
                    match recordTyAt 0, termAt 1 with
                    | Choice1Of2 fields, Some (DSymbol key) ->
                        match fields |> Map.tryPick (fun (_, k) v -> if k = key then Some v else None) with
                        | Some tyValue ->
                            match termAt 2, termAt 3 with
                            | Some onSucc, _ -> Choice1Of2 (type_apply s onSucc tyValue)
                            | _, Some onFail -> Choice1Of2 (apply s (onFail, DB))
                            | _ -> Choice2Of2 "record_type_try_find_branch_missing"
                        | None ->
                            match termAt 3 with
                            | Some onFail -> Choice1Of2 (apply s (onFail, DB))
                            | None -> Choice2Of2 "record_type_try_find_fail_missing"
                    | Choice2Of2 detail, _ -> Choice2Of2 detail
                    | _, Some other -> Choice2Of2 (sprintf "record_type_try_find_expected_symbol:%s" (show_data other))
                    | _, None -> Choice2Of2 "record_type_try_find_key_missing"
                | EQ | NEQ | LT | LTE | GT | GTE ->
                    match termAt 0, termAt 1 with
                    | Some a, Some b ->
                        match typeAwareReplayUnwrapNominalData a, typeAwareReplayUnwrapNominalData b with
                        | DLit la, DLit lb ->
                            match typeAwareReplayTryCompareLiteral op la lb with
                            | Some value ->
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_aware_literal_compare_replay_resolved\",\"op\":%s,\"context_node_id\":%d,\"lhs\":%s,\"rhs\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}" [| box (DiagJson.esc opText); box -1; box (DiagJson.esc (show_data a)); box (DiagJson.esc (show_data b)) |])
                                Choice1Of2 value
                            | None -> Choice2Of2 (FastRuntimeFormat.format "type_aware_compare_literal_mismatch:%s:%s:%s" [| box opText; box (show_lit la); box (show_lit lb) |])
                        | _ ->
                            try
                                let aTy, bTy = data_to_ty s a, data_to_ty s b
                                let primTy = if is_primitive aTy then aTy elif is_primitive bTy then bTy else aTy
                                if ty_eq_allow_jp_placeholders aTy bTy && is_primitive primTy then
                                    let opCase = op
                                    let value = push_binop s opCase (a, b) (YPrim BoolT)
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_aware_primitive_compare_replay_resolved\",\"op\":%s,\"context_node_id\":%d,\"lhs_ty\":%s,\"rhs_ty\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}" [| box (DiagJson.esc opText); box -1; box (DiagJson.esc (show_ty aTy)); box (DiagJson.esc (show_ty bTy)) |])
                                    Choice1Of2 value
                                else Choice2Of2 (FastRuntimeFormat.format "type_aware_compare_expected_same_primitive:%s:%s:%s" [| box opText; box (show_ty aTy); box (show_ty bTy) |])
                            with ex -> Choice2Of2 ("type_aware_compare_replay_failed:" + opText + ":" + compactOpExn ex)
                    | None, _ -> Choice2Of2 ("type_aware_compare_lhs_missing:" + opText)
                    | _, None -> Choice2Of2 ("type_aware_compare_rhs_missing:" + opText)
                | _ -> Choice2Of2 ("type_aware_op_unhandled:" + opText))

            EvalReplayValueStore.installTypeAwareOpReplayScheduleAfterDefinition (fun sObj contextNodeId op argNodeIds ->
                let s = unbox<LangEnv> sObj
                let opText = opStableText op
                let termAt i =
                    if i >= 0 && i < argNodeIds.Length then EvalReplayValueStore.tryTerm argNodeIds.[i]
                    else None
                let typeAt i =
                    if i >= 0 && i < argNodeIds.Length then EvalReplayValueStore.tryType argNodeIds.[i]
                    else None
                let recordTyAt i =
                    let asRecordType source ty =
                        match ty with
                        | YRecord fields -> Choice1Of2 fields
                        | YNominal _ | YApply _ ->
                            match nominal_type_apply s ty with
                            | YRecord fields -> Choice1Of2 fields
                            | other -> Choice2Of2 (sprintf "expected_record_type_%s:%s" source (show_ty other))
                        | other -> Choice2Of2 (sprintf "expected_record_type_%s:%s" source (show_ty other))
                    match typeAt i with
                    | Some ty -> asRecordType "type_store" ty
                    | None ->
                        match termAt i with
                        | Some value ->
                            try
                                let result = asRecordType "term_store" (data_to_ty s value)
                                match result with
                                | Choice1Of2 fields ->
                                    DiagJson.emit (
                                        sprintf "{\"kind\":\"eval_worklist_record_type_recovered_from_term_store\",\"arg_index\":%d,\"field_count\":%d,\"single_flight\":1,\"next\":\"continue_record_type_op_replay\"}"
                                            i fields.Count)
                                | Choice2Of2 _ -> ()
                                result
                            with ex -> Choice2Of2 (sprintf "type_arg_missing_term_store_uncoercible:%s" (ex.GetType().Name))
                        | None -> Choice2Of2 "type_arg_missing"
                let compactOpExn (ex: exn) =
                    let msg =
                        if isNull ex.Message then ""
                        else ex.Message.Replace("\r"," ").Replace("\n"," ").Replace("\t"," ")
                    let msg = if msg.Length > 180 then msg.Substring(0, 180) + "..." else msg
                    ex.GetType().Name + ":" + msg
                let typeAwareScheduleUnwrapNominalData data =
                    let mutable current = data
                    let mutable unwrapped = false
                    while not unwrapped do
                        match current with
                        | DNominal(inner, _) -> current <- inner
                        | _ -> unwrapped <- true
                    current
                let typeAwareScheduleTryCompareLiteral (op: Op) a b =
                    let out x = Some (DLit (LitBool x))
                    match op, a, b with
                    | EQ, LitInt8 a, LitInt8 b -> out (a = b)
                    | NEQ, LitInt8 a, LitInt8 b -> out (a <> b)
                    | EQ, LitInt16 a, LitInt16 b -> out (a = b)
                    | NEQ, LitInt16 a, LitInt16 b -> out (a <> b)
                    | EQ, LitInt32 a, LitInt32 b -> out (a = b)
                    | NEQ, LitInt32 a, LitInt32 b -> out (a <> b)
                    | EQ, LitInt64 a, LitInt64 b -> out (a = b)
                    | NEQ, LitInt64 a, LitInt64 b -> out (a <> b)
                    | EQ, LitUInt8 a, LitUInt8 b -> out (a = b)
                    | NEQ, LitUInt8 a, LitUInt8 b -> out (a <> b)
                    | EQ, LitUInt16 a, LitUInt16 b -> out (a = b)
                    | NEQ, LitUInt16 a, LitUInt16 b -> out (a <> b)
                    | EQ, LitUInt32 a, LitUInt32 b -> out (a = b)
                    | NEQ, LitUInt32 a, LitUInt32 b -> out (a <> b)
                    | EQ, LitUInt64 a, LitUInt64 b -> out (a = b)
                    | NEQ, LitUInt64 a, LitUInt64 b -> out (a <> b)
                    | EQ, LitFloat32 a, LitFloat32 b -> out (a = b)
                    | NEQ, LitFloat32 a, LitFloat32 b -> out (a <> b)
                    | EQ, LitFloat64 a, LitFloat64 b -> out (a = b)
                    | NEQ, LitFloat64 a, LitFloat64 b -> out (a <> b)
                    | EQ, LitChar a, LitChar b -> out (a = b)
                    | NEQ, LitChar a, LitChar b -> out (a <> b)
                    | EQ, LitString a, LitString b -> out (a = b)
                    | NEQ, LitString a, LitString b -> out (a <> b)
                    | EQ, LitBool a, LitBool b -> out (a = b)
                    | NEQ, LitBool a, LitBool b -> out (a <> b)
                    | LT, LitInt8 a, LitInt8 b -> out (a < b)
                    | LTE, LitInt8 a, LitInt8 b -> out (a <= b)
                    | GT, LitInt8 a, LitInt8 b -> out (a > b)
                    | GTE, LitInt8 a, LitInt8 b -> out (a >= b)
                    | LT, LitInt16 a, LitInt16 b -> out (a < b)
                    | LTE, LitInt16 a, LitInt16 b -> out (a <= b)
                    | GT, LitInt16 a, LitInt16 b -> out (a > b)
                    | GTE, LitInt16 a, LitInt16 b -> out (a >= b)
                    | LT, LitInt32 a, LitInt32 b -> out (a < b)
                    | LTE, LitInt32 a, LitInt32 b -> out (a <= b)
                    | GT, LitInt32 a, LitInt32 b -> out (a > b)
                    | GTE, LitInt32 a, LitInt32 b -> out (a >= b)
                    | LT, LitInt64 a, LitInt64 b -> out (a < b)
                    | LTE, LitInt64 a, LitInt64 b -> out (a <= b)
                    | GT, LitInt64 a, LitInt64 b -> out (a > b)
                    | GTE, LitInt64 a, LitInt64 b -> out (a >= b)
                    | LT, LitUInt8 a, LitUInt8 b -> out (a < b)
                    | LTE, LitUInt8 a, LitUInt8 b -> out (a <= b)
                    | GT, LitUInt8 a, LitUInt8 b -> out (a > b)
                    | GTE, LitUInt8 a, LitUInt8 b -> out (a >= b)
                    | LT, LitUInt16 a, LitUInt16 b -> out (a < b)
                    | LTE, LitUInt16 a, LitUInt16 b -> out (a <= b)
                    | GT, LitUInt16 a, LitUInt16 b -> out (a > b)
                    | GTE, LitUInt16 a, LitUInt16 b -> out (a >= b)
                    | LT, LitUInt32 a, LitUInt32 b -> out (a < b)
                    | LTE, LitUInt32 a, LitUInt32 b -> out (a <= b)
                    | GT, LitUInt32 a, LitUInt32 b -> out (a > b)
                    | GTE, LitUInt32 a, LitUInt32 b -> out (a >= b)
                    | LT, LitUInt64 a, LitUInt64 b -> out (a < b)
                    | LTE, LitUInt64 a, LitUInt64 b -> out (a <= b)
                    | GT, LitUInt64 a, LitUInt64 b -> out (a > b)
                    | GTE, LitUInt64 a, LitUInt64 b -> out (a >= b)
                    | LT, LitFloat32 a, LitFloat32 b -> out (a < b)
                    | LTE, LitFloat32 a, LitFloat32 b -> out (a <= b)
                    | GT, LitFloat32 a, LitFloat32 b -> out (a > b)
                    | GTE, LitFloat32 a, LitFloat32 b -> out (a >= b)
                    | LT, LitFloat64 a, LitFloat64 b -> out (a < b)
                    | LTE, LitFloat64 a, LitFloat64 b -> out (a <= b)
                    | GT, LitFloat64 a, LitFloat64 b -> out (a > b)
                    | GTE, LitFloat64 a, LitFloat64 b -> out (a >= b)
                    | LT, LitChar a, LitChar b -> out (a < b)
                    | LTE, LitChar a, LitChar b -> out (a <= b)
                    | GT, LitChar a, LitChar b -> out (a > b)
                    | GTE, LitChar a, LitChar b -> out (a >= b)
                    | LT, LitString a, LitString b -> out (a < b)
                    | LTE, LitString a, LitString b -> out (a <= b)
                    | GT, LitString a, LitString b -> out (a > b)
                    | GTE, LitString a, LitString b -> out (a >= b)
                    | LT, LitBool a, LitBool b -> out (a < b)
                    | LTE, LitBool a, LitBool b -> out (a <= b)
                    | GT, LitBool a, LitBool b -> out (a > b)
                    | GTE, LitBool a, LitBool b -> out (a >= b)
                    | _ -> None
                let schedulePrimitiveCompare () =
                    match termAt 0, termAt 1 with
                    | Some a, Some b ->
                        match typeAwareScheduleUnwrapNominalData a, typeAwareScheduleUnwrapNominalData b with
                        | DLit la, DLit lb ->
                            match typeAwareScheduleTryCompareLiteral op la lb with
                            | Some value ->
                                EvalReplayValueStore.putTermValue contextNodeId value
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_aware_literal_compare_replay_resolved\",\"op\":%s,\"context_node_id\":%d,\"lhs\":%s,\"rhs\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}" [| box (DiagJson.esc opText); box contextNodeId; box (DiagJson.esc (show_data a)); box (DiagJson.esc (show_data b)) |])
                                Choice1Of2 (contextNodeId, CompilerIdentityKernel.WorkShapeIdOps.Known.eOp, "type_aware_literal_compare:" + opText)
                            | None -> Choice2Of2 (FastRuntimeFormat.format "type_aware_compare_literal_mismatch:%s:%s:%s" [| box opText; box (show_lit la); box (show_lit lb) |])
                        | _ ->
                            try
                                let aTy, bTy = data_to_ty s a, data_to_ty s b
                                let primTy = if is_primitive aTy then aTy elif is_primitive bTy then bTy else aTy
                                if ty_eq_allow_jp_placeholders aTy bTy && is_primitive primTy then
                                    let opCase = op
                                    let value = push_binop s opCase (a, b) (YPrim BoolT)
                                    EvalReplayValueStore.putTermValue contextNodeId value
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_aware_primitive_compare_replay_resolved\",\"op\":%s,\"context_node_id\":%d,\"lhs_ty\":%s,\"rhs_ty\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}" [| box (DiagJson.esc opText); box contextNodeId; box (DiagJson.esc (show_ty aTy)); box (DiagJson.esc (show_ty bTy)) |])
                                    Choice1Of2 (contextNodeId, CompilerIdentityKernel.WorkShapeIdOps.Known.eOp, "type_aware_primitive_compare:" + opText)
                                else Choice2Of2 (FastRuntimeFormat.format "type_aware_compare_expected_same_primitive:%s:%s:%s" [| box opText; box (show_ty aTy); box (show_ty bTy) |])
                            with ex -> Choice2Of2 ("type_aware_compare_schedule_failed:" + opText + ":" + compactOpExn ex)
                    | None, _ -> Choice2Of2 ("type_aware_compare_lhs_missing:" + opText)
                    | _, None -> Choice2Of2 ("type_aware_compare_rhs_missing:" + opText)
                let scheduleTypeEq () =
                    match typeAt 0, typeAt 1 with
                    | Some aTy, Some bTy ->
                        let result = (aTy = bTy)
                        let value = DLit (LitBool result)
                        EvalReplayValueStore.putTermValue contextNodeId value
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_aware_type_eq_replay_resolved\",\"context_node_id\":%d,\"lhs_ty\":%s,\"rhs_ty\":%s,\"result\":%b,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}" [| box contextNodeId; box (DiagJson.esc (show_ty aTy)); box (DiagJson.esc (show_ty bTy)); box result |])
                        Choice1Of2 (contextNodeId, CompilerIdentityKernel.WorkShapeIdOps.Known.eOp, "type_aware_type_eq_resolved")
                    | None, _ -> Choice2Of2 "type_aware_type_eq_lhs_missing"
                    | _, None -> Choice2Of2 "type_aware_type_eq_rhs_missing"
                let scheduleDyn () =
                    match termAt 0 with
                    | Some arg ->
                        try
                            let value = dyn true s arg
                            EvalReplayValueStore.putTermValue contextNodeId value
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_type_aware_dyn_replay_resolved\",\"context_node_id\":%d,\"arg\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                    contextNodeId (DiagJson.esc (show_data arg)))
                            Choice1Of2 (contextNodeId, CompilerIdentityKernel.WorkShapeIdOps.Known.eOp, "type_aware_dyn_resolved")
                        with ex -> Choice2Of2 ("type_aware_dyn_schedule_failed:" + compactOpExn ex)
                    | None -> Choice2Of2 "type_aware_dyn_arg_missing"
                let scheduleStringIndex () =
                    match termAt 0, termAt 1 with
                    | Some (DLit (LitString str)), Some (DLit idxLit) ->
                        try
                            let idx = to_i32 idxLit
                            if 0 <= idx && idx < str.Length then
                                let value = DLit (LitChar str.[idx])
                                EvalReplayValueStore.putTermValue contextNodeId value
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_aware_string_index_literal_replay_resolved\",\"context_node_id\":%d,\"index\":%d,\"string_len\":%d,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}" [| box contextNodeId; box idx; box str.Length |])
                                Choice1Of2 (contextNodeId, CompilerIdentityKernel.WorkShapeIdOps.Known.eOp, "string_index_literal")
                            else Choice2Of2 (sprintf "string_index_literal_oob:index=%d:length=%d" idx str.Length)
                        with ex -> Choice2Of2 ("string_index_literal_schedule_failed:" + compactOpExn ex)
                    | Some a, Some b ->
                        try
                            let at, bt = data_to_ty s a, data_to_ty s b
                            if is_string_allow_jp_placeholders at && is_any_int_allow_jp_placeholders bt then
                                let value = push_binop s StringIndex (a, b) (YPrim CharT)
                                EvalReplayValueStore.putTermValue contextNodeId value
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_type_aware_string_index_replay_resolved\",\"context_node_id\":%d,\"lhs_ty\":%s,\"rhs_ty\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}" [| box contextNodeId; box (DiagJson.esc (show_ty at)); box (DiagJson.esc (show_ty bt)) |])
                                Choice1Of2 (contextNodeId, CompilerIdentityKernel.WorkShapeIdOps.Known.eOp, "string_index_typed")
                            else Choice2Of2 (sprintf "string_index_expected_string_int:%s:%s" (show_ty at) (show_ty bt))
                        with ex -> Choice2Of2 ("string_index_schedule_failed:" + compactOpExn ex)
                    | None, _ -> Choice2Of2 "string_index_string_arg_missing"
                    | _, None -> Choice2Of2 "string_index_index_arg_missing"

                let scheduleBackendSwitch () =
                    match termAt 0 with
                    | Some (DRecord l) ->
                        match map_try_find_by_string s.backend.node l with
                        | Some branch ->
                            try
                                match EvalReplayValueStore.tryScheduleApplyFunctionBodyReplayAt contextNodeId branch DB with
                                | Choice1Of2 (bodyNodeId, bodyShape) ->
                                    EvalReplayValueStore.putTypeAwareOpResultNode contextNodeId bodyNodeId
                                    EvalReplayValueStore.putParentContinuation bodyNodeId { parentKind = EvalReplayValueStore.EvaluatorTermNode; parentShape = CompilerIdentityKernel.WorkShapeIdOps.Known.eOp; parentNodeId = contextNodeId; role = EvaluatorBackendBranch }
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_backend_switch_branch_replay_scheduled\",\"context_node_id\":%d,\"backend\":%s,\"body_node_id\":%d,\"body_shape\":%s,\"single_flight\":1,\"next\":\"schedule_backend_switch_branch_replay\"}" [| box contextNodeId; box (DiagJson.esc s.backend.node); box bodyNodeId; box (DiagJson.esc (CompilerIdentityKernel.WorkShapeIdOps.text bodyShape)) |])
                                    Choice1Of2 (bodyNodeId, bodyShape, sprintf "backend_switch_branch:%s" s.backend.node)
                                | Choice2Of2 detail -> Choice2Of2 ("backend_switch_branch_schedule_failed:" + detail)
                            with ex -> Choice2Of2 ("backend_switch_branch_schedule_exception:" + compactOpExn ex)
                        | None -> Choice2Of2 (sprintf "backend_switch_backend_missing:%s" s.backend.node)
                    | Some other -> Choice2Of2 (sprintf "backend_switch_expected_record:%s" (show_data other))
                    | None -> Choice2Of2 "backend_switch_arg_missing"
                let scheduleRecordMap () =
                    let tryScheduleRecordMapField mapper (fields: Map<int * string, Data>) orderTag =
                        if fields.IsEmpty then
                            EvalReplayValueStore.putTermValue contextNodeId (DRecord Map.empty)
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_record_map_empty_replay_resolved\",\"context_node_id\":%d,\"order\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                    contextNodeId (DiagJson.esc orderTag))
                            Choice1Of2 (contextNodeId, CompilerIdentityKernel.WorkShapeIdOps.Known.eOp, "record_map_empty:" + orderTag)
                        else
                            let mutable first : (int * string * Data) option = None
                            for KeyValue((i, k), v) in fields do
                                if first.IsNone then first <- Some (i, k, v)
                            match first with
                            | Some (_i, k, v) ->
                                let arg =
                                    DRecord(
                                        Map.empty
                                        |> Map.add (fields.Count, "key") (DSymbol k)
                                        |> Map.add ((fields.Count + 1), "value") v)
                                try
                                    match EvalReplayValueStore.tryScheduleApplyFunctionBodyReplayAt contextNodeId mapper arg with
                                    | Choice1Of2 (bodyNodeId, bodyShape) ->
                                        EvalReplayValueStore.putTypeAwareOpResultNode contextNodeId bodyNodeId
                                        EvalReplayValueStore.putParentContinuation bodyNodeId { parentKind = EvalReplayValueStore.EvaluatorTermNode; parentShape = CompilerIdentityKernel.WorkShapeIdOps.Known.eOp; parentNodeId = contextNodeId; role = EvaluatorRecordMapField }
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_record_map_field_replay_scheduled\",\"context_node_id\":%d,\"field\":%s,\"order\":%s,\"body_node_id\":%d,\"body_shape\":%s,\"single_flight\":1,\"next\":\"schedule_record_map_field_replay\"}" [| box contextNodeId; box (DiagJson.esc k); box (DiagJson.esc orderTag); box bodyNodeId; box (DiagJson.esc (CompilerIdentityKernel.WorkShapeIdOps.text bodyShape)) |])
                                        Choice1Of2 (bodyNodeId, bodyShape, "record_map_field:" + orderTag + ":" + k)
                                    | Choice2Of2 detail -> Choice2Of2 ("record_map_field_schedule_failed:" + orderTag + ":" + detail)
                                with ex -> Choice2Of2 ("record_map_field_schedule_exception:" + orderTag + ":" + compactOpExn ex)
                            | None -> Choice2Of2 "record_map_fields_empty_after_nonempty"
                    match termAt 0, termAt 1 with
                    | Some mapper, Some (DRecord fields) ->
                        tryScheduleRecordMapField mapper fields "mapper_record"
                    | Some (DRecord fields), Some mapper ->
                        // MIGRATION: historical runtime showed this RecordMap site with the
                        // record materialized in arg0 and the mapper function in arg1
                        // (the old branch surfaced record_map_expected_record:? -> ?).
                        // Preserve the same concrete field scheduling path, but accept
                        // the observed operand order instead of pinning a false op impl terminal.
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_record_map_operand_order_repaired\",\"context_node_id\":%d,\"order\":\"record_mapper\",\"single_flight\":1,\"next\":\"schedule_record_map_field_replay\"}"
                                contextNodeId)
                        tryScheduleRecordMapField mapper fields "record_mapper"
                    | Some left, Some right ->
                        Choice2Of2 (sprintf "record_map_expected_mapper_record:left=%s:right=%s" (show_data left) (show_data right))
                    | Some _, None -> Choice2Of2 "record_map_record_arg_missing"
                    | None, Some _ -> Choice2Of2 "record_map_mapper_arg_missing"
                    | None, None -> Choice2Of2 "record_map_arg_missing"
                let scheduleRecordTypeTryFind () =
                    EvalReplayValueStore.putApplyContext contextNodeId sObj
                    EvalReplayValueStore.putTypeApplyContext contextNodeId sObj
                    let scheduleFail onFail =
                        try
                            match EvalReplayValueStore.tryScheduleApplyFunctionBodyReplayAt contextNodeId onFail DB with
                            | Choice1Of2 (bodyNodeId, bodyShape) ->
                                EvalReplayValueStore.putTypeAwareOpResultNode contextNodeId bodyNodeId
                                EvalReplayValueStore.putParentContinuation bodyNodeId { parentKind = EvalReplayValueStore.EvaluatorTermNode; parentShape = CompilerIdentityKernel.WorkShapeIdOps.Known.eOp; parentNodeId = contextNodeId; role = EvaluatorRecordLookupFailure }
                                DiagJson.emit (
                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_record_type_try_find_fail_replay_scheduled\",\"context_node_id\":%d,\"body_node_id\":%d,\"body_shape\":%s,\"single_flight\":1,\"next\":\"schedule_record_type_try_find_fail_replay\"}" [| box contextNodeId; box bodyNodeId; box (DiagJson.esc (CompilerIdentityKernel.WorkShapeIdOps.text bodyShape)) |])
                                Choice1Of2 (bodyNodeId, bodyShape, "record_type_try_find_fail")
                            | Choice2Of2 detail -> Choice2Of2 ("record_type_try_find_fail_schedule_failed:" + detail)
                        with ex -> Choice2Of2 ("record_type_try_find_fail_schedule_exception:" + compactOpExn ex)
                    match recordTyAt 0, termAt 1 with
                    | Choice1Of2 fields, Some (DSymbol key) ->
                        match fields |> Map.tryPick (fun (_, k) v -> if k = key then Some v else None) with
                        | Some tyValue ->
                            match termAt 2 with
                            | Some onSucc ->
                                try
                                    match EvalReplayValueStore.tryScheduleTypeApplyBodyReplayAt contextNodeId onSucc tyValue with
                                    | Choice1Of2 (bodyNodeId, bodyShape) ->
                                        EvalReplayValueStore.putTypeAwareOpResultNode contextNodeId bodyNodeId
                                        EvalReplayValueStore.putParentContinuation bodyNodeId { parentKind = EvalReplayValueStore.EvaluatorTermNode; parentShape = CompilerIdentityKernel.WorkShapeIdOps.Known.eOp; parentNodeId = contextNodeId; role = EvaluatorRecordLookupSuccess }
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_record_type_try_find_success_replay_scheduled\",\"context_node_id\":%d,\"key\":%s,\"body_node_id\":%d,\"body_shape\":%s,\"single_flight\":1,\"next\":\"schedule_record_type_try_find_success_replay\"}" [| box contextNodeId; box (DiagJson.esc key); box bodyNodeId; box (DiagJson.esc (CompilerIdentityKernel.WorkShapeIdOps.text bodyShape)) |])
                                        Choice1Of2 (bodyNodeId, bodyShape, "record_type_try_find_success:" + key)
                                    | Choice2Of2 detail -> Choice2Of2 ("record_type_try_find_success_schedule_failed:" + detail)
                                with ex -> Choice2Of2 ("record_type_try_find_success_schedule_exception:" + compactOpExn ex)
                            | None ->
                                match termAt 3 with
                                | Some onFail -> scheduleFail onFail
                                | None -> Choice2Of2 "record_type_try_find_branch_missing"
                        | None ->
                            match termAt 3 with
                            | Some onFail -> scheduleFail onFail
                            | None -> Choice2Of2 "record_type_try_find_fail_missing"
                    | Choice2Of2 detail, _ -> Choice2Of2 detail
                    | _, Some other -> Choice2Of2 (sprintf "record_type_try_find_expected_symbol:%s" (show_data other))
                    | _, None -> Choice2Of2 "record_type_try_find_key_missing"
                let scheduleRecordTypeFoldBack () =
                    EvalReplayValueStore.putApplyContext contextNodeId sObj
                    EvalReplayValueStore.putTypeApplyContext contextNodeId sObj
                    let scheduleFoldChild role (field: string) (bodyNodeId: int) (bodyShape: CompilerIdentityKernel.WorkShapeId) =
                        let roleText = EvalReplayValueStore.evaluatorDependencyRoleText role
                        EvalReplayValueStore.putTypeAwareOpResultNode contextNodeId bodyNodeId
                        EvalReplayValueStore.putParentContinuation bodyNodeId { parentKind = EvalReplayValueStore.EvaluatorTermNode; parentShape = CompilerIdentityKernel.WorkShapeIdOps.Known.eOp; parentNodeId = contextNodeId; role = role }
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_record_type_fold_back_step_replay_scheduled\",\"context_node_id\":%d,\"field\":%s,\"role\":%s,\"body_node_id\":%d,\"body_shape\":%s,\"single_flight\":1,\"next\":\"schedule_record_type_fold_back_step_replay\"}" [| box contextNodeId; box (DiagJson.esc field); box (DiagJson.esc roleText); box bodyNodeId; box (DiagJson.esc (CompilerIdentityKernel.WorkShapeIdOps.text bodyShape)) |])
                        Choice1Of2 (bodyNodeId, bodyShape, roleText + ":" + field)
                    match termAt 0, termAt 1, recordTyAt 2 with
                    | Some folder, Some state0, Choice1Of2 fields ->
                        if fields.IsEmpty then
                            EvalReplayValueStore.putTermValue contextNodeId state0
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_record_type_fold_back_empty_resolved\",\"context_node_id\":%d,\"field_count\":0,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                    contextNodeId)
                            Choice1Of2 (contextNodeId, CompilerIdentityKernel.WorkShapeIdOps.Known.eOp, "record_type_fold_back_empty")
                        else
                            let mutable folded = Some state0
                            let mutable failed : string option = None
                            let mutable scheduled : Choice<int * CompilerIdentityKernel.WorkShapeId * string, string> option = None
                            for KeyValue((_i, k), tyValue) in fields |> Seq.rev do
                                match folded, scheduled with
                                | Some state, None ->
                                    let keyArg = DSymbol k
                                    let keyedFolderOpt =
                                        try Some (apply s (folder, keyArg))
                                        with ex ->
                                            match EvalReplayValueStore.tryScheduleApplyFunctionBodyReplayAt contextNodeId folder keyArg with
                                            | Choice1Of2 (bodyNodeId, bodyShape) ->
                                                scheduled <- Some (scheduleFoldChild EvaluatorRecordFoldKeyed k bodyNodeId bodyShape)
                                                None
                                            | Choice2Of2 detail ->
                                                failed <- Some ("record_type_fold_back_keyed_folder_schedule_failed:" + k + ":" + detail + ":" + compactOpExn ex)
                                                None
                                    match keyedFolderOpt, scheduled with
                                    | Some keyedFolder, None ->
                                        let typedFolderOpt =
                                            try Some (type_apply s keyedFolder tyValue)
                                            with ex ->
                                                match EvalReplayValueStore.tryScheduleTypeApplyBodyReplayAt contextNodeId keyedFolder tyValue with
                                                | Choice1Of2 (bodyNodeId, bodyShape) ->
                                                    scheduled <- Some (scheduleFoldChild EvaluatorRecordFoldTyped k bodyNodeId bodyShape)
                                                    None
                                                | Choice2Of2 detail ->
                                                    failed <- Some ("record_type_fold_back_typed_folder_schedule_failed:" + k + ":" + detail + ":" + compactOpExn ex)
                                                    None
                                        match typedFolderOpt, scheduled with
                                        | Some typedFolder, None ->
                                            try
                                                folded <- Some (apply s (typedFolder, state))
                                            with ex ->
                                                match EvalReplayValueStore.tryScheduleApplyFunctionBodyReplayAt contextNodeId typedFolder state with
                                                | Choice1Of2 (bodyNodeId, bodyShape) ->
                                                    scheduled <- Some (scheduleFoldChild EvaluatorRecordFoldStep k bodyNodeId bodyShape)
                                                    folded <- None
                                                | Choice2Of2 detail ->
                                                    failed <- Some ("record_type_fold_back_step_schedule_failed:" + k + ":" + detail + ":" + compactOpExn ex)
                                                    folded <- None
                                        | _ ->
                                            folded <- None
                                    | _ ->
                                        folded <- None
                                | _ -> ()
                            match scheduled, folded, failed with
                            | Some scheduledChild, _, _ -> scheduledChild
                            | None, Some value, _ ->
                                EvalReplayValueStore.putTermValue contextNodeId value
                                DiagJson.emit (
                                    sprintf "{\"kind\":\"eval_worklist_record_type_fold_back_replay_resolved\",\"context_node_id\":%d,\"field_count\":%d,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                        contextNodeId fields.Count)
                                Choice1Of2 (contextNodeId, CompilerIdentityKernel.WorkShapeIdOps.Known.eOp, "record_type_fold_back_value_materialized")
                            | None, None, Some detail -> Choice2Of2 detail
                            | None, None, None -> Choice2Of2 "record_type_fold_back_unknown"
                    | None, _, _ -> Choice2Of2 "record_type_fold_back_folder_missing"
                    | _, None, _ -> Choice2Of2 "record_type_fold_back_state_missing"
                    | _, _, Choice2Of2 detail -> Choice2Of2 detail
                let scheduleUnionUntag () =
                    match EvalReplayValueStore.tryTypeAwareOpReplayWithContext contextNodeId UnionUntag argNodeIds with
                    | Some value ->
                        EvalReplayValueStore.putTermValue contextNodeId value
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_union_untag_type_aware_schedule_resolved\",\"context_node_id\":%d,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                contextNodeId)
                        Choice1Of2 (contextNodeId, CompilerIdentityKernel.WorkShapeIdOps.Known.eOp, "type_aware_union_untag_resolved")
                    | None -> Choice2Of2 "type_aware_union_untag_replay_unresolved"

                let schedulePrototypeHas () =
                    match EvalReplayValueStore.tryTypeAwareOpReplayWithContext contextNodeId PrototypeHas argNodeIds with
                    | Some value ->
                        EvalReplayValueStore.putTermValue contextNodeId value
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_prototype_has_type_aware_schedule_resolved\",\"context_node_id\":%d,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                contextNodeId)
                        Choice1Of2 (contextNodeId, CompilerIdentityKernel.WorkShapeIdOps.Known.eOp, "prototype_has_value_materialized")
                    | None ->
                        if argNodeIds.Length > 1 then
                            match EvalReplayValueStore.tryType argNodeIds.[1] with
                            | Some _ -> Choice2Of2 "prototype_has_replay_unresolved_after_type_ready"
                            | None -> Choice1Of2 (argNodeIds.[1], CompilerIdentityKernel.WorkShapeIdOps.Known.eType, "prototype_has_type_arg_missing")
                        else Choice2Of2 "prototype_has_args_missing"

                match op with
                | UnionUntag -> scheduleUnionUntag ()
                | PrototypeHas -> schedulePrototypeHas ()
                | Dyn -> scheduleDyn ()
                | StringIndex -> scheduleStringIndex ()
                | TypeEq -> scheduleTypeEq ()
                | BackendSwitch | UnsafeBackendSwitch -> scheduleBackendSwitch ()
                | RecordMap -> scheduleRecordMap ()
                | RecordTypeTryFind -> scheduleRecordTypeTryFind ()
                | RecordTypeFoldBack -> scheduleRecordTypeFoldBack ()
                | EQ | NEQ | LT | LTE | GT | GTE -> schedulePrimitiveCompare ()
                | ErrorType -> Choice2Of2 "error_type_replay_terminal_requires_message_pin"
                | _ -> Choice2Of2 ("type_aware_op_schedule_unhandled:" + opText))

            EvalReplayValueStore.installReplayScopeKey (fun sObj ->
                match sObj with
                | :? LangEnv as s -> box s.seq
                | _ -> sObj)
            EvalReplayValueStore.installAnnotTestBranchAfterDefinition (fun sObj bindValue annotTy ->
                let s = unbox<LangEnv> sObj
                let bindTy = data_to_ty s bindValue
                Choice1Of2 (ty_eq_allow_jp_placeholders bindTy annotTy))

            // Direct resume belongs to the evaluator scope that owns apply/type_apply/ty_record.
            // The wrapper term function only selects stack/pivot policy; this local corridor owns semantic execution.
            let emitDirectRootResume jobId resumeKind continuationRef =
                let occurrence, shouldEmitDirectResume =
                    DiagJson.sparseLogDecision ("jp_declared_direct_root_resume|" + resumeKind + "|" + string jobId) 64L
                if shouldEmitDirectResume then
                    DiagJson.emit (
                        FastRuntimeFormat.format
                            "{\"kind\":\"jp_declared_direct_root_resume\",\"work_job_id\":%d,\"resume_kind_du\":%s,\"continuation_ref\":%s,\"occurrence_count\":%d,\"authority\":\"typed_root_node_identity_and_immutable_continuation_snapshot\",\"next\":\"measure_prefix_replay_avoided_then_generalize_over_resume_spine\"}"
                            [| box jobId; box (DiagJson.esc resumeKind); box (DiagJson.esc (JpWorkContinuationRefOps.text continuationRef)); box occurrence |])

            let emitDirectSpineYield jobId rootNodeId planKind spineDepth stepIndex stepKind cause yieldedRef =
                let occurrence, shouldEmit =
                    DiagJson.sparseLogDecision ("jp_declared_direct_spine_resume_yielded|" + planKind + "|" + string jobId) 64L
                if shouldEmit then
                    DiagJson.emit (
                        FastRuntimeFormat.format
                            "{\"kind\":\"jp_declared_direct_spine_resume_yielded\",\"work_job_id\":%d,\"root_node_id\":%d,\"plan_kind_du\":%s,\"spine_depth\":%d,\"step_index\":%d,\"step_kind_du\":%s,\"yield_cause_du\":%s,\"yielded_continuation_ref\":%s,\"occurrence_count\":%d,\"authority\":\"direct_resume_executor_step_boundary\",\"next\":\"identify_first_non_retiring_resume_frame_before_expanding_fast_path\"}"
                            [| box jobId; box rootNodeId; box (DiagJson.esc planKind); box spineDepth; box stepIndex; box (DiagJson.esc stepKind); box (DiagJson.esc (jpDeclaredEvaluatorSliceYieldCauseText cause)); box (DiagJson.esc (JpWorkContinuationRefOps.text yieldedRef)); box occurrence |])

            let executeDirectRootLet jobId rootNodeId target (continuation:JpDeclaredLetContinuation) =
                let runChild stageName safeContinuation run =
                    try jpWithDeclaredSafeContinuation safeContinuation run
                    with
                    | JpDeclaredEvaluatorSliceYield(cause, yieldedRef) ->
                        emitDirectSpineYield jobId rootNodeId "RootLet" 1 0 stageName cause yieldedRef
                        reraise()
                emitDirectRootResume jobId ("Let:" + jpDeclaredLetStageText continuation.stage) continuation.continuationRef
                let value =
                    match continuation.stage with
                    | JpDeclaredLetBindingPending ->
                        CompilerConsoleHud88.emitImmediateFailureEvent
                            "jp_root_let_binding_pending_direct_carrier_missing"
                            "BigStack.executeDirectRootLet"
                            ($"job_id={jobId}|root_node_id={rootNodeId}|continuation_ref={JpWorkContinuationRefOps.text continuation.continuationRef}")
                            "root declared Let BindingPending requires its direct typed child result carrier; binding replay is forbidden."
                            "resolve_direct_typed_child_carrier_without_binding_replay"
                        invalidOp "root declared Let BindingPending requires its direct typed child result carrier; binding replay is forbidden."
                    | JpDeclaredLetCheckpointReady ->
                        invalidOp "root Let CheckpointReady is a control cursor and must be routed through the typed mixed cursor plan"
                    | JpDeclaredLetBodyPending ->
                        let safeContinuation = JpDeclaredLetSafeContinuation(jobId, rootNodeId, continuation.continuationRef)
                        runChild
                            "Let:BodyPending"
                            safeContinuation
                            (fun () ->
                                jpWithCurrentDeclaredTailResultBridge JpDeclaredLetBodyResultBridge (fun () -> term continuation.environment continuation.remainingExpression))
                jpConsumeDeclaredResumeTarget jobId target
                jpRetireDeclaredResumeSnapshot continuation.continuationRef
                value

            let executeDirectApplyPlan jobId rootNodeId sliceContext (plan:JpDeclaredApplyResumePlan) =
                let steps = plan.applySteps
                let sliceStartOperationCount = jp_current_operation_counter.Value
                let withOriginalParent index run =
                    if index + 1 < steps.Length then
                        let parent = steps.[index + 1]
                        jpWithDeclaredSafeContinuation
                            (JpDeclaredApplySafeContinuation(jobId, parent.nodeId, parent.continuationRef))
                            run
                    else
                        let previous = jpCurrentDeclaredSafeContinuation ()
                        jpSetCurrentDeclaredSafeContinuation None
                        try run()
                        finally jpSetCurrentDeclaredSafeContinuation previous
                let mutable result : Data option = None
                for index = 0 to steps.Length - 1 do
                    let step = steps.[index]
                    let continuation = step.continuation
                    let continuationRef = step.continuationRef
                    let runStep () =
                        if index = 0 then
                            resume_declared_apply
                                apply
                                (Some sliceContext)
                                sliceStartOperationCount
                                step.nodeId
                                continuation.frames
                                continuation.nextFrameIndex
                                (jpDeclaredApplySeedCurrentValue continuation)
                                continuation.stage
                        else
                            let childResult = Option.get result
                            match continuation.stage with
                            | JpDeclaredApplyHeadPending ->
                                jpClearDeclaredApplyContinuation jobId step.nodeId
                                resume_declared_apply
                                    apply
                                    (Some sliceContext)
                                    sliceStartOperationCount
                                    step.nodeId
                                    continuation.frames
                                    continuation.nextFrameIndex
                                    childResult
                                    JpDeclaredApplyBeforeArgument
                            | JpDeclaredApplyBeforeArgument ->
                                resume_declared_apply
                                    apply
                                    (Some sliceContext)
                                    sliceStartOperationCount
                                    step.nodeId
                                    continuation.frames
                                    continuation.nextFrameIndex
                                    (jpDeclaredApplySeedCurrentValue continuation)
                                    (JpDeclaredApplyArgumentReadyDispatchPending childResult)
                            | JpDeclaredApplyArgumentReadyDispatchPending _ ->
                                jpClearDeclaredApplyContinuation jobId step.nodeId
                                resume_declared_apply
                                    apply
                                    (Some sliceContext)
                                    sliceStartOperationCount
                                    step.nodeId
                                    continuation.frames
                                    (continuation.nextFrameIndex - 1)
                                    childResult
                                    JpDeclaredApplyBeforeArgument
                    let stepResult =
                        try withOriginalParent index runStep
                        with
                        | JpDeclaredEvaluatorSliceYield(cause, yieldedRef) ->
                            emitDirectSpineYield
                                jobId
                                rootNodeId
                                "ApplyOnly"
                                steps.Length
                                index
                                (jpDeclaredApplyStageText continuation.stage)
                                cause
                                yieldedRef
                            reraise()
                    jpRetireDeclaredResumeSnapshot continuationRef
                    result <- Some stepResult
                let occurrence, shouldEmit =
                    DiagJson.sparseLogDecision ("jp_declared_direct_apply_spine_resume_completed|" + string jobId) 64L
                if shouldEmit then
                    DiagJson.emit (
                        FastRuntimeFormat.format
                            "{\"kind\":\"jp_declared_direct_apply_spine_resume_completed\",\"work_job_id\":%d,\"root_node_id\":%d,\"target_ref\":%s,\"spine_depth\":%d,\"occurrence_count\":%d,\"authority\":\"all_apply_immutable_continuation_spine\",\"next\":\"measure_prefix_replay_avoided_and_retirement_latency\"}"
                            [| box jobId; box rootNodeId; box (DiagJson.esc (JpWorkContinuationRefOps.text plan.applyTargetRef)); box steps.Length; box occurrence |])
                Option.get result

            let evalDeclaredBinaryNumericValues (environment:LangEnv) operation leftValue rightValue =
                let opId = jpDeclaredBinaryNumericOperationToOp operation
                try
                    match leftValue, rightValue with
                    | DLit a, DLit b ->
                        match operation, a, b with
                        | JpDeclaredBinaryNumericDiv, LitInt8 a, LitInt8 b -> a / b |> LitInt8 |> DLit
                        | JpDeclaredBinaryNumericDiv, LitInt16 a, LitInt16 b -> a / b |> LitInt16 |> DLit
                        | JpDeclaredBinaryNumericDiv, LitInt32 a, LitInt32 b -> a / b |> LitInt32 |> DLit
                        | JpDeclaredBinaryNumericDiv, LitInt64 a, LitInt64 b -> a / b |> LitInt64 |> DLit
                        | JpDeclaredBinaryNumericDiv, LitUInt8 a, LitUInt8 b -> a / b |> LitUInt8 |> DLit
                        | JpDeclaredBinaryNumericDiv, LitUInt16 a, LitUInt16 b -> a / b |> LitUInt16 |> DLit
                        | JpDeclaredBinaryNumericDiv, LitUInt32 a, LitUInt32 b -> a / b |> LitUInt32 |> DLit
                        | JpDeclaredBinaryNumericDiv, LitUInt64 a, LitUInt64 b -> a / b |> LitUInt64 |> DLit
                        | JpDeclaredBinaryNumericDiv, LitFloat32 a, LitFloat32 b -> a / b |> nan_guardf32 |> LitFloat32 |> DLit
                        | JpDeclaredBinaryNumericDiv, LitFloat64 a, LitFloat64 b -> a / b |> nan_guardf64 |> LitFloat64 |> DLit
                        | JpDeclaredBinaryNumericMod, LitInt8 a, LitInt8 b -> a % b |> LitInt8 |> DLit
                        | JpDeclaredBinaryNumericMod, LitInt16 a, LitInt16 b -> a % b |> LitInt16 |> DLit
                        | JpDeclaredBinaryNumericMod, LitInt32 a, LitInt32 b -> a % b |> LitInt32 |> DLit
                        | JpDeclaredBinaryNumericMod, LitInt64 a, LitInt64 b -> a % b |> LitInt64 |> DLit
                        | JpDeclaredBinaryNumericMod, LitUInt8 a, LitUInt8 b -> a % b |> LitUInt8 |> DLit
                        | JpDeclaredBinaryNumericMod, LitUInt16 a, LitUInt16 b -> a % b |> LitUInt16 |> DLit
                        | JpDeclaredBinaryNumericMod, LitUInt32 a, LitUInt32 b -> a % b |> LitUInt32 |> DLit
                        | JpDeclaredBinaryNumericMod, LitUInt64 a, LitUInt64 b -> a % b |> LitUInt64 |> DLit
                        | JpDeclaredBinaryNumericMod, LitFloat32 a, LitFloat32 b -> a % b |> nan_guardf32 |> LitFloat32 |> DLit
                        | JpDeclaredBinaryNumericMod, LitFloat64 a, LitFloat64 b -> a % b |> nan_guardf64 |> LitFloat64 |> DLit
                        | _ ->
                            raise_type_error environment <| sprintf "The two literals must be both numeric and equal in type.\nGot: %s and %s" (show_lit a) (show_lit b)
                    | a, b ->
                        let aTy, bTy = data_to_ty environment a, data_to_ty environment b
                        let isJpPlaceholder t = ty_is_jp_method_rec_placeholder t || ty_is_jp_type_rec_placeholder t
                        let typeRelation =
                            if aTy = bTy then
                                if is_numeric aTy then JpDeclaredBinaryNumericEqualNumeric
                                else JpDeclaredBinaryNumericEqualNonNumeric
                            elif isJpPlaceholder aTy && is_numeric bTy then
                                JpDeclaredBinaryNumericLeftPlaceholderRightNumeric
                            elif isJpPlaceholder bTy && is_numeric aTy then
                                JpDeclaredBinaryNumericRightPlaceholderLeftNumeric
                            else
                                JpDeclaredBinaryNumericRejectedMismatch
                        match typeRelation with
                        | JpDeclaredBinaryNumericEqualNumeric ->
                            if is_lit_zero b then raise (DivideByZeroException())
                            elif operation = JpDeclaredBinaryNumericDiv && is_lit_one b then a
                            else push_binop environment opId (a,b) aTy
                        | JpDeclaredBinaryNumericEqualNonNumeric ->
                            raise_type_error environment <| sprintf "The type of the two arguments needs to be a numeric type.\nGot: %s" (show_ty aTy)
                        | JpDeclaredBinaryNumericLeftPlaceholderRightNumeric ->
                            push_binop environment opId (a,b) bTy
                        | JpDeclaredBinaryNumericRightPlaceholderLeftNumeric ->
                            push_binop environment opId (a,b) aTy
                        | JpDeclaredBinaryNumericRejectedMismatch ->
                            let jobId = jpCurrentWorkJobId ()
                            let leftShapeText = a |> replayDataShapeOf |> replayDataShapeText
                            let rightShapeText = b |> replayDataShapeOf |> replayDataShapeText
                            let currentSafeContinuation = jpCurrentDeclaredSafeContinuation ()
                            let currentSafeContinuationPresent = Option.isSome currentSafeContinuation
                            let currentSafeContinuationKind =
                                currentSafeContinuation
                                |> Option.map jpDeclaredSafeContinuationKindText
                                |> Option.defaultValue "None"
                            let currentSafeContinuationRefText, currentSafeContinuationNodeId, currentSafeContinuationChannel =
                                match currentSafeContinuation with
                                | Some safeContinuation ->
                                    let continuationRef = jpDeclaredSafeContinuationRef safeContinuation
                                    let channel =
                                        match jpTryDeclaredResumeSnapshotByRef continuationRef with
                                        | Some snapshot -> snapshot |> jpDeclaredResumeSnapshotResultChannel |> jpDeclaredResumeResultChannelText
                                        | None -> "Missing"
                                    JpWorkContinuationRefOps.text continuationRef, jpDeclaredSafeContinuationNodeId safeContinuation, channel
                                | None -> "None", 0, "None"
                            let mixedResumeCompletedForJob =
                                jp_current_declared_mixed_resume_completed_job_id.Value = jobId
                            let resumeSnapshotJobLiveCount = jpDeclaredResumeSnapshotLiveCountForJob jobId
                            DiagJson.emit (
                                FastRuntimeFormat.format
                                    "{\"kind\":\"jp_declared_binary_numeric_type_relation_rejected\",\"work_job_id\":%d,\"operation_du\":%s,\"left_type_du\":%s,\"right_type_du\":%s,\"left_shape_du\":%s,\"right_shape_du\":%s,\"current_safe_continuation_present\":%b,\"current_safe_continuation_kind_du\":%s,\"current_safe_continuation_ref\":%s,\"current_safe_continuation_node_id\":%d,\"current_safe_continuation_result_channel_du\":%s,\"mixed_resume_completed_for_job\":%b,\"resume_snapshot_job_live_count\":%d,\"relation_du\":\"RejectedMismatch\",\"control_authority\":false,\"terminal_stage_authority\":false,\"authority\":\"typed_binary_numeric_relation_diagnostic_only\",\"next\":\"attribute_mismatch_without_widening_numeric_semantics\"}"
                                    [| box jobId; box (DiagJson.esc (jpDeclaredBinaryNumericOperationText operation)); box (DiagJson.esc (show_ty aTy)); box (DiagJson.esc (show_ty bTy)); box (DiagJson.esc leftShapeText); box (DiagJson.esc rightShapeText); box currentSafeContinuationPresent; box (DiagJson.esc currentSafeContinuationKind); box (DiagJson.esc currentSafeContinuationRefText); box currentSafeContinuationNodeId; box (DiagJson.esc currentSafeContinuationChannel); box mixedResumeCompletedForJob; box resumeSnapshotJobLiveCount |])
                            raise_type_error environment <| sprintf "The two sides need to have the same numeric types.\nGot: %s and %s." (show_ty aTy) (show_ty bTy)
                with :? DivideByZeroException ->
                    raise_type_error environment "An attempt to divide by zero has been detected at compile time."

            let executeDirectMixedPlan jobId rootNodeId rootExpressionIdentity sliceContext (plan:JpDeclaredMixedResumePlan) =
                let steps = plan.mixedSteps
                let sliceStartOperationCount = jp_current_operation_counter.Value
                let applyStepCount =
                    steps
                    |> Array.sumBy (function
                        | JpDeclaredMixedApplyCarrierStep _
                        | JpDeclaredMixedApplyStep _ -> 1
                        | _ -> 0)
                let applyCarrierStepCount =
                    steps
                    |> Array.sumBy (function JpDeclaredMixedApplyCarrierStep _ -> 1 | _ -> 0)
                let letStepCount =
                    steps
                    |> Array.sumBy (function
                        | JpDeclaredMixedLetBindingCarrierStep _
                        | JpDeclaredMixedLetStep _ -> 1
                        | _ -> 0)
                let letBindingStepCount =
                    steps
                    |> Array.sumBy (function JpDeclaredMixedLetBindingCarrierStep _ -> 1 | _ -> 0)
                let letBodyStepCount =
                    steps
                    |> Array.sumBy (function
                        | JpDeclaredMixedLetStep step when step.continuation.stage = JpDeclaredLetBodyPending -> 1
                        | _ -> 0)
                let letCheckpointStepCount =
                    steps
                    |> Array.sumBy (function
                        | JpDeclaredMixedLetStep step when step.continuation.stage = JpDeclaredLetCheckpointReady -> 1
                        | _ -> 0)
                let sequenceStepCount =
                    steps
                    |> Array.sumBy (function
                        | JpDeclaredMixedSequenceCarrierStep _
                        | JpDeclaredMixedSequenceStep _ -> 1
                        | _ -> 0)
                let binaryNumericStepCount =
                    steps
                    |> Array.sumBy (function
                        | JpDeclaredMixedBinaryNumericCarrierStep _ -> 1
                        | _ -> 0)
                let foldStepCount =
                    steps
                    |> Array.sumBy (function JpDeclaredMixedFoldStep _ -> 1 | _ -> 0)
                let mixedStepNodeId = function
                    | JpDeclaredMixedApplyCarrierStep step
                    | JpDeclaredMixedApplyStep step -> step.nodeId
                    | JpDeclaredMixedLetBindingCarrierStep step
                    | JpDeclaredMixedLetStep step -> step.nodeId
                    | JpDeclaredMixedSequenceCarrierStep step
                    | JpDeclaredMixedSequenceStep step -> step.nodeId
                    | JpDeclaredMixedBinaryNumericCarrierStep step -> step.nodeId
                    | JpDeclaredMixedFoldStep step -> step.nodeId
                let mixedStepKindText = function
                    | JpDeclaredMixedApplyCarrierStep step -> "Apply:Carrier:" + jpDeclaredApplyStageText step.continuation.stage
                    | JpDeclaredMixedApplyStep step -> "Apply:Seed:" + jpDeclaredApplyStageText step.continuation.stage
                    | JpDeclaredMixedLetBindingCarrierStep _ -> "Let:BindingPending:Carrier"
                    | JpDeclaredMixedLetStep step -> "Let:" + jpDeclaredLetStageText step.continuation.stage
                    | JpDeclaredMixedSequenceCarrierStep step ->
                        match step.continuation.stage with
                        | JpDeclaredSequenceFirstPending _ -> "Sequence:Carrier:FirstPending"
                        | JpDeclaredSequenceTailPending -> "Sequence:Carrier:TailPending"
                    | JpDeclaredMixedSequenceStep step ->
                        match step.continuation.stage with
                        | JpDeclaredSequenceFirstPending _ -> "Sequence:Seed:FirstPending"
                        | JpDeclaredSequenceTailPending -> "Sequence:Seed:TailPending"
                    | JpDeclaredMixedBinaryNumericCarrierStep step ->
                        "BinaryNumeric:Carrier:" + jpDeclaredBinaryNumericOperationText step.continuation.operation
                        + ":" + jpDeclaredBinaryNumericStageText step.continuation.stage
                    | JpDeclaredMixedFoldStep step ->
                        "Fold:" + jpDeclaredRecordTypeFoldBackStateText step.continuation.state
                        + "->" + jpDeclaredDataResultAcceptorText step.resultAcceptor
                let entryNodeId = mixedStepNodeId steps.[0]
                let entryStepKind = mixedStepKindText steps.[0]
                let safeContinuationOfStep = function
                    | JpDeclaredMixedApplyCarrierStep step
                    | JpDeclaredMixedApplyStep step ->
                        JpDeclaredApplySafeContinuation(jobId, step.nodeId, step.continuationRef)
                    | JpDeclaredMixedLetBindingCarrierStep step
                    | JpDeclaredMixedLetStep step ->
                        JpDeclaredLetSafeContinuation(jobId, step.nodeId, step.continuationRef)
                    | JpDeclaredMixedSequenceCarrierStep step
                    | JpDeclaredMixedSequenceStep step ->
                        JpDeclaredSequenceSafeContinuation(jobId, step.nodeId, step.continuationRef)
                    | JpDeclaredMixedBinaryNumericCarrierStep step ->
                        JpDeclaredBinaryNumericSafeContinuation(jobId, step.nodeId, step.continuationRef)
                    | JpDeclaredMixedFoldStep step ->
                        JpDeclaredRecordTypeFoldBackSafeContinuation(jobId, step.nodeId, step.continuationRef)
                let withOriginalParent index run =
                    if index + 1 < steps.Length then
                        jpWithDeclaredSafeContinuation (safeContinuationOfStep steps.[index + 1]) run
                    else
                        let previous = jpCurrentDeclaredSafeContinuation ()
                        jpSetCurrentDeclaredSafeContinuation None
                        try run()
                        finally jpSetCurrentDeclaredSafeContinuation previous
                let mutable result : Data option = None
                let mutable firstUnitResultStepIndex = -1
                let mutable firstUnitResultStepKind : string option = None
                let mutable entryResultShape : ReplayDataShapeId option = None
                let stepResultTrace = ResizeArray<string>()
                for index = 0 to steps.Length - 1 do
                    let runStep () =
                        match steps.[index] with
                        | JpDeclaredMixedApplyCarrierStep step ->
                            let continuation = step.continuation
                            let childResult = Option.get result
                            match continuation.stage with
                            | JpDeclaredApplyHeadPending ->
                                jpClearDeclaredApplyContinuation jobId step.nodeId
                                resume_declared_apply
                                    apply
                                    (Some sliceContext)
                                    sliceStartOperationCount
                                    step.nodeId
                                    continuation.frames
                                    continuation.nextFrameIndex
                                    childResult
                                    JpDeclaredApplyBeforeArgument
                            | JpDeclaredApplyArgumentReadyDispatchPending _ ->
                                jpClearDeclaredApplyContinuation jobId step.nodeId
                                resume_declared_apply
                                    apply
                                    (Some sliceContext)
                                    sliceStartOperationCount
                                    step.nodeId
                                    continuation.frames
                                    (continuation.nextFrameIndex - 1)
                                    childResult
                                    JpDeclaredApplyBeforeArgument
                            | JpDeclaredApplyBeforeArgument ->
                                resume_declared_apply
                                    apply
                                    (Some sliceContext)
                                    sliceStartOperationCount
                                    step.nodeId
                                    continuation.frames
                                    continuation.nextFrameIndex
                                    (jpDeclaredApplySeedCurrentValue continuation)
                                    (JpDeclaredApplyArgumentReadyDispatchPending childResult)
                        | JpDeclaredMixedApplyStep step ->
                            let continuation = step.continuation
                            match continuation.stage with
                            | JpDeclaredApplyBeforeArgument ->
                                resume_declared_apply
                                    apply
                                    (Some sliceContext)
                                    sliceStartOperationCount
                                    step.nodeId
                                    continuation.frames
                                    continuation.nextFrameIndex
                                    (jpDeclaredApplySeedCurrentValue continuation)
                                    continuation.stage
                            | JpDeclaredApplyHeadPending
                            | JpDeclaredApplyArgumentReadyDispatchPending _ ->
                                raise_type_error (JpDeclaredApplyFrameOps.environment continuation.frames.[max 0 continuation.nextFrameIndex]) "A replayable mixed Apply step cannot encode a carrier-required stage."
                        | JpDeclaredMixedLetBindingCarrierStep step ->
                            let continuation = step.continuation
                            match continuation.stage, continuation.remainingExpression with
                            | JpDeclaredLetBindingPending, ELet(r, i, bindingExpression, body) ->
                                let bindingEnvironment = add_trace continuation.environment r
                                let childResult = Option.get result
                                let bindingValue =
                                    match bindingExpression with
                                    | EAnnot(annotationRange, _, annotation) ->
                                        let annotationEnvironment = add_trace bindingEnvironment annotationRange
                                        validate_annotated_value annotationEnvironment annotationRange annotation childResult
                                    | _ -> childResult
                                store_term bindingEnvironment i bindingValue
                                let bodyContinuationRef =
                                    jpStoreDeclaredLetContinuation
                                        jobId step.nodeId bindingEnvironment body (continuation.bindingCount + 1) JpDeclaredLetBodyPending
                                let bodySafeContinuation = JpDeclaredLetSafeContinuation(jobId, step.nodeId, bodyContinuationRef)
                                let bodyValue =
                                    jpWithDeclaredSafeContinuation bodySafeContinuation (fun () ->
                                        jpWithCurrentDeclaredTailResultBridge JpDeclaredLetBodyResultBridge (fun () -> term bindingEnvironment body))
                                jpRetireDeclaredResumeSnapshot bodyContinuationRef
                                jpClearDeclaredLetContinuation jobId step.nodeId
                                bodyValue
                            | _ ->
                                raise_type_error continuation.environment "A mixed Let binding carrier step requires a BindingPending ELet snapshot."
                        | JpDeclaredMixedLetStep step ->
                            let continuation = step.continuation
                            match continuation.stage with
                            | JpDeclaredLetBindingPending ->
                                raise_type_error continuation.environment "A replayable mixed Let step cannot encode BindingPending; the typed carrier step is required."
                            | JpDeclaredLetBodyPending ->
                                if index = 0 then
                                    let safeContinuation = JpDeclaredLetSafeContinuation(jobId, step.nodeId, continuation.continuationRef)
                                    jpWithDeclaredSafeContinuation
                                        safeContinuation
                                        (fun () ->
                                            jpWithCurrentDeclaredTailResultBridge JpDeclaredLetBodyResultBridge (fun () -> term continuation.environment continuation.remainingExpression))
                                else Option.get result
                            | JpDeclaredLetCheckpointReady ->
                                if index = 0 then
                                    match plan.mixedEntryPoint with
                                    | JpDeclaredMixedResumeLetCheckpointCursor ->
                                        jpWithCurrentDeclaredTailResultBridge
                                            JpDeclaredLetBodyResultBridge
                                            (fun () -> term continuation.environment continuation.remainingExpression)
                                    | _ ->
                                        invalidOp "Let CheckpointReady may execute only as the typed mixed cursor entry point"
                                else
                                    raise_type_error continuation.environment "A mixed Let checkpoint cursor cannot consume child Data."
                        | JpDeclaredMixedSequenceCarrierStep step ->
                            let continuation = step.continuation
                            let childResult = Option.get result
                            match continuation.stage with
                            | JpDeclaredSequenceFirstPending(sequenceRange, firstExpression) ->
                                resume_declared_sequence_after_first
                                    jobId step.nodeId continuation.environment sequenceRange
                                    firstExpression continuation.remainingExpression childResult
                            | JpDeclaredSequenceTailPending ->
                                childResult
                        | JpDeclaredMixedSequenceStep step ->
                            let continuation = step.continuation
                            match continuation.stage with
                            | JpDeclaredSequenceFirstPending _ ->
                                invalidOp "Sequence FirstPending cannot be a direct mixed seed; its typed child Data carrier is required."
                            | JpDeclaredSequenceTailPending ->
                                let safeContinuation =
                                    JpDeclaredSequenceSafeContinuation(jobId, step.nodeId, continuation.continuationRef)
                                jpWithDeclaredSafeContinuation safeContinuation (fun () ->
                                    jpWithCurrentDeclaredTailResultBridge JpDeclaredSequenceTailResultBridge (fun () ->
                                        term continuation.environment continuation.remainingExpression))
                        | JpDeclaredMixedBinaryNumericCarrierStep step ->
                            let continuation = step.continuation
                            let childResult = Option.get result
                            match continuation.stage with
                            | JpDeclaredBinaryNumericLeftPending ->
                                jpRetireDeclaredResumeSnapshot continuation.continuationRef
                                let leftValue, rightValue =
                                    resume_declared_binary_numeric_operands
                                        jobId step.nodeId continuation.environment continuation.operation
                                        continuation.leftExpression continuation.rightExpression
                                        (JpDeclaredBinaryNumericRightPending childResult)
                                evalDeclaredBinaryNumericValues continuation.environment continuation.operation leftValue rightValue
                            | JpDeclaredBinaryNumericRightPending leftValue ->
                                jpClearDeclaredBinaryNumericContinuation jobId step.nodeId
                                evalDeclaredBinaryNumericValues continuation.environment continuation.operation leftValue childResult
                        | JpDeclaredMixedFoldStep step ->
                            let continuation = step.continuation
                            if index = 0 then
                                resume_declared_record_type_foldback
                                    apply
                                    type_apply
                                    ty_record
                                    jobId
                                    step.nodeId
                                    continuation.folderExpression
                                    continuation.initialStateExpression
                                    (jpDeclaredRecordTypePrepass continuation.recordTypeSource)
                                    continuation.state
                            else
                                let childResult = Option.get result
                                let nextState =
                                    match continuation.state, step.resultAcceptor with
                                    | JpDeclaredRecordTypeFoldBackFolderPending environment,
                                      JpDeclaredFoldFolderResultAcceptor ->
                                        JpDeclaredRecordTypeFoldBackInitialStatePending(environment, childResult)
                                    | JpDeclaredRecordTypeFoldBackInitialStatePending(environment, folder),
                                      JpDeclaredFoldInitialStateResultAcceptor ->
                                        JpDeclaredRecordTypeFoldBackRecordTypePending(environment, folder, childResult)
                                    | JpDeclaredRecordTypeFoldBackFieldPending(environment, folder, fields, nextFieldIndex, currentState),
                                      JpDeclaredFoldKeyApplyResultAcceptor ->
                                        JpDeclaredRecordTypeFoldBackKeyApplied(environment, folder, fields, nextFieldIndex, currentState, childResult)
                                    | JpDeclaredRecordTypeFoldBackKeyApplied(environment, folder, fields, nextFieldIndex, currentState, _),
                                      JpDeclaredFoldTypeApplyResultAcceptor ->
                                        JpDeclaredRecordTypeFoldBackTypeApplied(environment, folder, fields, nextFieldIndex, currentState, childResult)
                                    | JpDeclaredRecordTypeFoldBackTypeApplied(environment, folder, fields, nextFieldIndex, _, _),
                                      JpDeclaredFoldStateApplyResultAcceptor ->
                                        JpDeclaredRecordTypeFoldBackFieldPending(environment, folder, fields, nextFieldIndex + 1, childResult)
                                    | _ ->
                                        invalidOp "mixed declared Fold resume result channel did not match the saved state"
                                resume_declared_record_type_foldback
                                    apply
                                    type_apply
                                    ty_record
                                    jobId
                                    step.nodeId
                                    continuation.folderExpression
                                    continuation.initialStateExpression
                                    (jpDeclaredRecordTypePrepass continuation.recordTypeSource)
                                    nextState
                    let continuationRef =
                        match steps.[index] with
                        | JpDeclaredMixedApplyCarrierStep step
                        | JpDeclaredMixedApplyStep step -> step.continuationRef
                        | JpDeclaredMixedLetBindingCarrierStep step -> step.continuationRef
                        | JpDeclaredMixedLetStep step -> step.continuationRef
                        | JpDeclaredMixedSequenceCarrierStep step
                        | JpDeclaredMixedSequenceStep step -> step.continuationRef
                        | JpDeclaredMixedBinaryNumericCarrierStep step -> step.continuationRef
                        | JpDeclaredMixedFoldStep step -> step.continuationRef
                    let stepKind = mixedStepKindText steps.[index]
                    let stepResult =
                        try
                            jpWithCurrentDeclaredDirectResumeExecutionRoot
                                continuationRef
                                (fun () -> withOriginalParent index runStep)
                        with
                        | JpDeclaredEvaluatorSliceYield(cause, yieldedRef) ->
                            emitDirectSpineYield
                                jobId
                                rootNodeId
                                "Mixed"
                                steps.Length
                                index
                                stepKind
                                cause
                                yieldedRef
                            reraise()
                    let stepResultShape = replayDataShapeOf stepResult
                    stepResultTrace.Add(stepKind + "=" + replayDataShapeText stepResultShape)
                    if index = 0 then entryResultShape <- Some stepResultShape
                    match stepResult with
                    | DB when firstUnitResultStepIndex < 0 ->
                        firstUnitResultStepIndex <- index
                        firstUnitResultStepKind <- Some stepKind
                    | _ -> ()
                    result <- Some stepResult
                // The work item keeps mixedTargetRef as its resume identity until this
                // whole typed spine commits. Retiring successful prefix snapshots eagerly
                // makes a later carrier block resume through an identity that this executor
                // has already deleted. Keep plan-owned snapshots live across partial mixed
                // execution and retire the committed spine only after every step succeeded.
                let committedStepRefs =
                    steps
                    |> Array.map (function
                        | JpDeclaredMixedApplyCarrierStep step
                        | JpDeclaredMixedApplyStep step -> step.continuationRef
                        | JpDeclaredMixedLetBindingCarrierStep step -> step.continuationRef
                        | JpDeclaredMixedLetStep step -> step.continuationRef
                        | JpDeclaredMixedSequenceCarrierStep step
                        | JpDeclaredMixedSequenceStep step -> step.continuationRef
                        | JpDeclaredMixedBinaryNumericCarrierStep step -> step.continuationRef
                        | JpDeclaredMixedFoldStep step -> step.continuationRef)
                for continuationRef in committedStepRefs do
                    jpRetireDeclaredResumeSnapshot continuationRef
                let finalResult = Option.get result
                jp_current_declared_mixed_resume_completed_job_id.Value <- jobId
                jp_current_declared_mixed_resume_completed_root_node_id.Value <- rootNodeId
                jp_current_declared_mixed_resume_completed_root_identity.Value <- rootExpressionIdentity
                let completedEntryResultShape = entryResultShape |> Option.get
                let stepResultPathText = String.concat ">" stepResultTrace
                let occurrence, shouldEmit =
                    DiagJson.sparseLogDecision ("jp_declared_direct_mixed_spine_resume_completed|" + string jobId) 64L
                if shouldEmit then
                    DiagJson.emit (
                        FastRuntimeFormat.format
                            "{\"kind\":\"jp_declared_direct_mixed_spine_resume_completed\",\"work_job_id\":%d,\"root_node_id\":%d,\"target_ref\":%s,\"entry_ref\":%s,\"entry_authority_du\":%s,\"entry_point_du\":%s,\"entry_node_id\":%d,\"entry_step_du\":%s,\"entry_result_shape_du\":%s,\"spine_depth\":%d,\"apply_step_count\":%d,\"apply_carrier_step_count\":%d,\"let_step_count\":%d,\"let_binding_step_count\":%d,\"let_body_step_count\":%d,\"let_checkpoint_step_count\":%d,\"sequence_step_count\":%d,\"binary_numeric_step_count\":%d,\"fold_step_count\":%d,\"first_unit_result_step_index\":%d,\"first_unit_result_step_kind_du\":%s,\"final_result_shape_du\":%s,\"step_result_path_du\":%s,\"occurrence_count\":%d,\"authority\":\"typed_carrier_producer_to_consumer_mixed_spine\",\"next\":\"preserve_result_carrier_ownership_without_ancestor_replay\"}"
                            [| box jobId; box rootNodeId; box (DiagJson.esc (JpWorkContinuationRefOps.text plan.mixedTargetRef)); box (DiagJson.esc (JpWorkContinuationRefOps.text plan.mixedEntryRef)); box (DiagJson.esc (jpDeclaredMixedResumeEntryAuthorityText plan.mixedEntryAuthority)); box (DiagJson.esc (jpDeclaredMixedResumeEntryPointText plan.mixedEntryPoint)); box entryNodeId; box (DiagJson.esc entryStepKind); box (DiagJson.esc (replayDataShapeText completedEntryResultShape)); box steps.Length; box applyStepCount; box applyCarrierStepCount; box letStepCount; box letBindingStepCount; box letBodyStepCount; box letCheckpointStepCount; box sequenceStepCount; box binaryNumericStepCount; box foldStepCount; box firstUnitResultStepIndex; box (DiagJson.esc (firstUnitResultStepKind |> Option.defaultValue "none")); box (DiagJson.esc (replayDataShapeText (replayDataShapeOf finalResult))); box (DiagJson.esc stepResultPathText); box occurrence |])
                finalResult

            let tryDirectDeclaredResume () =
                match jpCurrentDeclaredDirectResumeSliceContext () with
                | Some (JpDeclaredBodySliceContext(jobId, _, _) as sliceContext) ->
                    let nodeId = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode (box x)
                    let tryDirectMixedAtCurrentNode () =
                        match jpTryBuildDeclaredDirectResumePlan jobId with
                        | Some (JpDeclaredDirectMixedPlan mixedPlan) when jpDeclaredMixedResumePlanRootNodeId mixedPlan = nodeId ->
                            let occurrence, shouldEmit =
                                DiagJson.sparseLogDecision ("jp_declared_direct_mixed_spine_resume_admitted|" + string jobId) 64L
                            if shouldEmit then
                                DiagJson.emit (
                                    FastRuntimeFormat.format
                                        "{\"kind\":\"jp_declared_direct_mixed_spine_resume_admitted\",\"work_job_id\":%d,\"root_node_id\":%d,\"target_ref\":%s,\"entry_ref\":%s,\"entry_authority_du\":%s,\"entry_point_du\":%s,\"opaque_edge_relations_du\":%s,\"spine_depth\":%d,\"occurrence_count\":%d,\"authority\":\"typed_carrier_producer_to_consumer_mixed_spine\",\"next\":\"execute_without_ancestor_or_root_replay\"}"
                                        [| box jobId; box nodeId; box (DiagJson.esc (JpWorkContinuationRefOps.text mixedPlan.mixedTargetRef)); box (DiagJson.esc (JpWorkContinuationRefOps.text mixedPlan.mixedEntryRef)); box (DiagJson.esc (jpDeclaredMixedResumeEntryAuthorityText mixedPlan.mixedEntryAuthority)); box (DiagJson.esc (jpDeclaredMixedResumeEntryPointText mixedPlan.mixedEntryPoint)); box (DiagJson.esc (jpDeclaredMixedResumePlanOpaqueEdgeRelationsText mixedPlan)); box mixedPlan.mixedSteps.Length; box occurrence |])
                            let executionRoots =
                                mixedPlan.mixedSteps
                                |> Array.map (function
                                    | JpDeclaredMixedApplyCarrierStep step
                                    | JpDeclaredMixedApplyStep step -> step.continuationRef
                                    | JpDeclaredMixedLetBindingCarrierStep step -> step.continuationRef
                                    | JpDeclaredMixedLetStep step -> step.continuationRef
                                    | JpDeclaredMixedSequenceCarrierStep step
                                    | JpDeclaredMixedSequenceStep step -> step.continuationRef
                                    | JpDeclaredMixedBinaryNumericCarrierStep step -> step.continuationRef
                                    | JpDeclaredMixedFoldStep step -> step.continuationRef)
                            Some (
                                jpWithDeclaredDirectResumeExecutionRoots executionRoots (fun () ->
                                    // Entry routing may be consumed here because execution roots retain every mixed-step snapshot across return or yield.
                                    jpConsumeDeclaredResumeTarget jobId mixedPlan.mixedTargetRef
                                    executeDirectMixedPlan jobId nodeId (box x) sliceContext mixedPlan))
                        | _ -> None
                    match x with
                    | EApply(r,_,_) ->
                        let p0, p1 = r.range
                        let directResumeSite =
                            FastRuntimeFormat.format "%s:%d:%d-%d:%d"
                                [| box r.path; box (p0.line + 1); box (p0.character + 1); box (p1.line + 1); box (p1.character + 1) |]
                        match jpTryBuildDeclaredDirectResumePlan jobId with
                        | Some (JpDeclaredDirectApplyPlan plan) when jpDeclaredApplyResumePlanRootNodeId plan = nodeId ->
                            let occurrence, shouldEmit =
                                DiagJson.sparseLogDecision ("jp_declared_direct_apply_spine_resume_admitted|" + string jobId) 64L
                            if shouldEmit then
                                DiagJson.emit (
                                    FastRuntimeFormat.format
                                        "{\"kind\":\"jp_declared_direct_apply_spine_resume_admitted\",\"work_job_id\":%d,\"root_node_id\":%d,\"site\":%s,\"target_ref\":%s,\"spine_depth\":%d,\"occurrence_count\":%d,\"authority\":\"all_apply_immutable_continuation_spine\",\"next\":\"execute_without_root_prefix_replay\"}"
                                        [| box jobId; box nodeId; box (DiagJson.esc directResumeSite); box (DiagJson.esc (JpWorkContinuationRefOps.text plan.applyTargetRef)); box plan.applySteps.Length; box occurrence |])
                            let executionRoots = plan.applySteps |> Array.map (fun step -> step.continuationRef)
                            Some (
                                jpWithDeclaredDirectResumeExecutionRoots executionRoots (fun () ->
                                    // Pure Apply spines take the simpler typed plan before mixed-carrier planning.
                                    jpConsumeDeclaredResumeTarget jobId plan.applyTargetRef
                                    executeDirectApplyPlan jobId nodeId sliceContext plan))
                        | _ ->
                            match tryDirectMixedAtCurrentNode () with
                            | Some value -> Some value
                            | None ->
                                let blocker = jpDeclaredDirectResumeBlocker jobId
                                match blocker with
                                | JpDeclaredDirectResumeTargetMissing -> None
                                | _ ->
                                    let occurrence, shouldEmit =
                                        DiagJson.sparseLogDecision ("jp_declared_direct_resume_plan_unavailable|" + string jobId + "|" + jpDeclaredDirectResumeBlockerText blocker) 64L
                                    if shouldEmit then
                                        DiagJson.emit (
                                            FastRuntimeFormat.format
                                                "{\"kind\":\"jp_declared_direct_resume_plan_unavailable\",\"work_job_id\":%d,\"root_node_id\":%d,\"site\":%s,\"blocker_du\":%s,\"opaque_parent_ref\":%s,\"opaque_parent_snapshot_kind_du\":%s,\"opaque_parent_result_channel_du\":%s,\"occurrence_count\":%d,\"authority\":\"typed_direct_resume_blocker_observation_only\",\"next\":\"resolve_typed_carrier_from_opaque_parent_or_preserve_consumer_without_replay\"}"
                                                [| box jobId; box nodeId; box (DiagJson.esc directResumeSite); box (DiagJson.esc (jpDeclaredDirectResumeBlockerText blocker)); box (DiagJson.esc (jpDeclaredDirectResumeBlockerOpaqueParentText blocker)); box (DiagJson.esc (jpDeclaredDirectResumeBlockerOpaqueParentSnapshotKindText blocker)); box (DiagJson.esc (jpDeclaredDirectResumeBlockerOpaqueParentResultChannelText blocker)); box occurrence |])
                                    None
                    | ELet _ ->
                        match tryDirectMixedAtCurrentNode () with
                        | Some value -> Some value
                        | None ->
                            if jp_current_declared_root_resume_quarantine.Value then None
                            else
                                match jpTryDeclaredRootResume jobId nodeId with
                                | Some(target, JpDeclaredRootLetResume continuation) ->
                                    Some (executeDirectRootLet jobId nodeId target continuation)
                                | _ -> None
                    | ESeq _ ->
                        match tryDirectMixedAtCurrentNode () with
                        | Some value -> Some value
                        | None ->
                            if jp_current_declared_root_resume_quarantine.Value then None
                            else
                                match jpTryDeclaredRootResume jobId nodeId with
                                | Some(target, JpDeclaredRootSequenceResume continuation) ->
                                    emitDirectRootResume jobId "Sequence:TailPending" continuation.continuationRef
                                    let safeContinuation =
                                        JpDeclaredSequenceSafeContinuation(jobId, nodeId, continuation.continuationRef)
                                    let value =
                                        jpWithDeclaredSafeContinuation safeContinuation (fun () ->
                                            jpWithCurrentDeclaredTailResultBridge JpDeclaredSequenceTailResultBridge (fun () ->
                                                term continuation.environment continuation.remainingExpression))
                                    jpConsumeDeclaredResumeTarget jobId target
                                    jpRetireDeclaredResumeSnapshot continuation.continuationRef
                                    jpClearDeclaredSequenceContinuation jobId nodeId
                                    Some value
                                | _ -> None
                    | EOp(_, ((Div | Mod) as binaryOp), [_;_]) ->
                        match tryDirectMixedAtCurrentNode () with
                        | Some value -> Some value
                        | None ->
                            if jp_current_declared_root_resume_quarantine.Value then None
                            else
                                match jpTryDeclaredRootResume jobId nodeId with
                                | Some(target, JpDeclaredRootBinaryNumericResume continuation) ->
                                    let operation =
                                        match binaryOp with
                                        | Div -> JpDeclaredBinaryNumericDiv
                                        | Mod -> JpDeclaredBinaryNumericMod
                                        | _ -> invalidOp "binary numeric resume received an unsupported operation"
                                    let leftValue, rightValue =
                                        resume_declared_binary_numeric_operands
                                            jobId nodeId continuation.environment operation
                                            continuation.leftExpression continuation.rightExpression continuation.stage
                                    let value = evalDeclaredBinaryNumericValues continuation.environment operation leftValue rightValue
                                    jpConsumeDeclaredResumeTarget jobId target
                                    jpRetireDeclaredResumeSnapshot continuation.continuationRef
                                    Some value
                                | _ -> None
                    | EOp(_,RecordTypeFoldBack,[_;_;EType _]) ->
                        match tryDirectMixedAtCurrentNode () with
                        | Some value -> Some value
                        | None ->
                            if jp_current_declared_root_resume_quarantine.Value then None
                            else
                                match jpTryDeclaredRootResume jobId nodeId with
                                | Some(target, JpDeclaredRootRecordTypeFoldBackResume continuation) ->
                                    emitDirectRootResume
                                        jobId
                                        ("RecordTypeFoldBack:" + jpDeclaredRecordTypeFoldBackStateText continuation.state)
                                        continuation.continuationRef
                                    let value =
                                        resume_declared_record_type_foldback
                                            apply
                                            type_apply
                                            ty_record
                                            jobId
                                            nodeId
                                            continuation.folderExpression
                                            continuation.initialStateExpression
                                            (jpDeclaredRecordTypePrepass continuation.recordTypeSource)
                                            continuation.state
                                    jpConsumeDeclaredResumeTarget jobId target
                                    jpRetireDeclaredResumeSnapshot continuation.continuationRef
                                    Some value
                                | _ -> None
                    | _ -> None
                | None -> None

            match tryDirectDeclaredResume () with
            | Some value -> raise (EvalReplayTermReturn value)
            | None -> ()

            match x with
            | EPatternRef _ -> failwith "Compiler error: EPatternRef should have been eliminated during the prepass."
            | EB _ -> DB
            | EV a -> v s a
            | ELit(_,a) -> DLit a
            | ESymbol(_,a) -> DSymbol a
            | EFun _ -> failwith "Compiler error: Raw functions should be transformed during the prepass."
            | EFun'(_,free_vars,i,body,annot) -> efun (free_vars,i,body,annot)
            | ERecursiveFun'(_,free_vars,i,body,annot) -> efun (free_vars,i,body.Value,annot)
            | EForall _ -> failwith "Compiler error: Raw foralls should be transformed during the prepass."
            | EForall'(_,free_vars,i,body) -> eforall (free_vars,i,body)
            | ERecursiveForall'(_,free_vars,i,body) -> eforall (free_vars,i,body.Value)
            | ERecursive a ->
                jpWithCurrentDeclaredTailResultBridge JpDeclaredRecursiveTermResultBridge (fun () -> term s a.Value)
            | ERecBlock _ -> failwith "Compiler error: Recursive blocks should be inlined and eliminated during the prepass."
            | EJoinPoint _ -> failwith "error[EJPX003]: internal compiler error\n  |\n  = raw join point survived prepass\n  help: this indicates a missing transformation pass; capture the stack trace and prepass inputs.\n"
            | EJoinPoint'(r,scope,body,annot,backend,jp_name) ->
                let env_global_type = HopacExtensions.S.map (vt s) scope.ty.free_vars
                let env_global_term = HopacExtensions.S.map (v s) scope.term.free_vars
    

                let backend' = match backend with None -> s.backend | Some (_,backend) -> lock backend_strings_lock (fun () -> backend_strings.Add backend)
                let methodOwnerIdentity = JpBodyOwnerIdentity.create backend' body
                // MIGRATION: IVar-based dict - no separate dict_ev needed
                let (dict: System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<RData [] * Ty [] * Ty>, Hopac.IVar<JpMethodBodyCellPayload>>), hc_table, cache_gen =
                    Utils.memoize join_point_method (fun _ ->
                        System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<RData [] * Ty [] * Ty>, Hopac.IVar<JpMethodBodyCellPayload>>(HashIdentity.Reference), HashConsTable(), CacheGeneration.current ()
                    ) methodOwnerIdentity
    

                let dict, hc_table =
                    if CacheGeneration.isStale cache_gen then
                        let fresh =
                            (System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Reference),
                             HashConsTable(),
                             CacheGeneration.current ())
                        join_point_method.[methodOwnerIdentity] <- fresh
                        let (d,h,_) = fresh
                        d,h
                    else dict, hc_table
    

                // An inferred/prepass annotation and the body must observe the exact same
                // renamed global-term witness.  The historical compiler resolved the annotation
                // after rename_global_term and then evaluated the body in that same environment;
                // independently renaming two equivalent environments can split a polymorphic
                // function value from the interface used to verify it under parallel execution.
                let annotationEnvironmentWitness, annot_ty_for_key =
                    match annot with
                    | None -> None, None
                    | Some annotation ->
                        let annotationEnv : LangEnv =
                            { s with
                                trace = r :: s.trace
                                seq = ResizeArray()
                                cse = [System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural)]
                                unions = Map.empty
                                i = ref 0
                                env_global_type = env_global_type
                                env_global_term = env_global_term
                                env_stack_type = Array.zeroCreate<_> scope.ty.stack_size
                                env_stack_term = Array.zeroCreate<_> scope.term.stack_size
                                backend = backend' }
                            |> rename_global_term
                        Some annotationEnv, Some (ty annotationEnv annotation)

                let prepareJoinPointBodyEnv jpMethodStack jpClosureStack jpTypeStack =
                    match annotationEnvironmentWitness with
                    | Some annotationEnv ->
                        { annotationEnv with
                            seq = ResizeArray()
                            cse = [System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural)]
                            unions = Map.empty
                            jp_method_stack = jpMethodStack
                            jp_closure_stack = jpClosureStack
                            jp_type_stack = jpTypeStack }
                    | None ->
                        { s with
                            trace = r :: s.trace
                            seq = ResizeArray()
                            cse = [System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural)]
                            unions = Map.empty
                            i = ref 0
                            env_global_type = env_global_type
                            env_global_term = env_global_term
                            env_stack_type = Array.zeroCreate<_> scope.ty.stack_size
                            env_stack_term = Array.zeroCreate<_> scope.term.stack_size
                            backend = backend'
                            jp_method_stack = jpMethodStack
                            jp_closure_stack = jpClosureStack
                            jp_type_stack = jpTypeStack }
                        |> rename_global_term
                let env_global_type_key =
                    match annot_ty_for_key with
                    | Some t -> Array.append env_global_type [| t |]
                    | None -> env_global_type
    

                let call_args, env_global_value =
                    data_to_rdata s hc_table env_global_term
    

                // Include source range in JP key for cache uniqueness
                let (sp, ep) = r.range
                let rk = FastRuntimeFormat.format "jp@%s:%d:%d-%d:%d" [| box r.path; box sp.line; box sp.character; box ep.line; box ep.character |]
    

                let env_global_value_key =
                    Array.append env_global_value [| ReSymbol rk |]
    

                let  normalize_jp_key_ret (t: Ty) : Ty =
                    let t = jp_method_deref_rec_placeholder t
                    match t with
                    | YVoid | YB | YLit _ | YPrim _ -> t
                    | YSymbol _ ->
                        match tryDecodeJpRecPlaceholder t with
                        | Some JpMethodRecPlaceholder
                        | Some JpTypeRecPlaceholder
                        | Some JpMethodUnknownReturn -> jpMethodUnknownReturnTy
                        | _ -> t
                    | _ -> t
    

                let annot_ty_for_key_norm : Ty =
                    match annot_ty_for_key with
                    | Some t -> normalize_jp_key_ret t
                    | None -> jpMethodUnknownReturnTy
    

                let join_point_key =
                    lock hc_table (fun () -> hc_table.Add(env_global_value_key, env_global_type_key, annot_ty_for_key_norm))
                let _ =
                    // record a stable label for better join-point diagnostics
                    let base_name =
                        match jp_name with
                        | Some n when n <> "" -> n
                        | _ -> sprintf "<anonymous:%d>" join_point_key.tag
                    let name = base_name + " @" + rk
                    s.join_point_method_key_names.TryAdd(join_point_key, JpNameIdOps.create name) |> ignore

                let methodKey = (defaultArg jp_name "<anon>") + " @" + rk
                let methodSiteId = CompilerIdentityKernel.WorkSiteIdOps.create rk
                let methodBackendId = JpBodyOwnerIdentity.backendId methodOwnerIdentity
                let methodBindingIdentity =
                    CompilerKernelV2.StableBindingId.createSemantic
                        (max 0 join_point_key.tag)
                        "jp-method-identity"
                        methodKey
                        rk
                        "unspecialized"
                        backend'.node
                let methodIdentity = JpMethodIdentity methodBindingIdentity
                let methodComputationIdentity = JpMethodComputation(methodIdentity, methodSiteId)
                let valueIdentityRef = jpRDataArrayIdentityRef env_global_value_key
                let typeIdentityRef = jpTyArrayIdentityRef env_global_type_key
                let annotationText = show_ty annot_ty_for_key_norm
                let annotationIdentityRef =
                    CompilerIdentityKernel.ContentDigest.ofText "jp-method-annotation-identity" annotationText
                let instantiationCanonical =
                    FastRuntimeFormat.format "%s|hkey=%d|backend=%s|value_len=%d|value_ref=%s|type_len=%d|type_ref=%s|annotation_ref=%s" [| box methodKey; box join_point_key.hkey; box backend'.node; box env_global_value_key.Length; box (CompilerIdentityKernel.ContentDigest.text valueIdentityRef); box env_global_type_key.Length; box (CompilerIdentityKernel.ContentDigest.text typeIdentityRef); box (CompilerIdentityKernel.ContentDigest.text annotationIdentityRef) |]
                let instantiationId =
                    CompilerKernelV2.InstantiationIdOps.create instantiationCanonical
                let instantiationText = CompilerKernelV2.InstantiationIdOps.text instantiationId
                let memoGeneration = CacheGeneration.current()
                // Program symbols are opaque identities.  Method specialization may only
                // gain effect semantics from explicit compiler/language evidence, never
                // from the spelling of source-level function names.
                let runtimeEffectRequirement = JpRuntimeEffectPure
                let sharedCompletedMemoPolicy = JpMethodSharedCompletedMemoConfluent
                let runtimeEffectClaim = JpRuntimeEffectWitnessAuthority.claim runtimeEffectRequirement
                let runtimeEffectAdmission = JpSpecializationAdmitOwnedCell
                let memoCellIdentity =
                    JpMethodMemoCellIdentity(methodIdentity, instantiationId, memoGeneration)
                let memoWitness = {
                    environmentValues = env_global_value_key
                    environmentTypes = env_global_type_key
                    annotation = annot_ty_for_key_norm
                }
                let memoBinding =
                    CompilerKernelV2.StableBindingId.createSemantic
                        (max 0 join_point_key.tag)
                        "jp-method-memo"
                        methodKey
                        rk
                        instantiationText
                        (string backend')
                let verificationRef =
                    CompilerIdentityKernel.ContentDigest.ofText
                        "jp-method-declared-interface-verification"
                        (methodKey + "|" + instantiationText + "|" + string memoGeneration)
                let declaredInterfaceClaim =
                    match annot_ty_for_key with
                    | None -> JpMethodDeclaredInterfaceAbsent
                    | Some declaredType ->
                        let candidate = {
                            methodIdentity = methodIdentity
                            instantiationId = instantiationId
                            declaredType = declaredType
                            verificationRef = verificationRef
                        }
                        if jp_method_declared_interfaces.TryAdd(memoCellIdentity, candidate) then
                            JpMethodDeclaredInterfaceClaimed candidate
                        else
                            let mutable existing = Unchecked.defaultof<JpMethodDeclaredInterface>
                            if jp_method_declared_interfaces.TryGetValue(memoCellIdentity, &existing) then
                                JpMethodDeclaredInterfaceExisting existing
                            else
                                JpMethodDeclaredInterfaceClaimed candidate

                let jpMethodMemoProbe emitProbe =
                    let memoEventKind = DiagJson.typedDiagEventKindText DiagJson.TypedDiagJpComputationMemo
                    let computationKind = jpComputationIdentityKindText methodComputationIdentity
                    let probeText = jpMethodMemoProbeText emitProbe
                    let occurrenceCount, shouldEmit =
                        DiagJson.sparseLogDecision
                            (memoEventKind + "|" + computationKind + "|" + methodKey + "|" + probeText)
                            64L
                    if shouldEmit then
                        let memoHit =
                            match emitProbe with
                            | JpMethodMemoSharedReadyHit
                            | JpMethodMemoSharedWaitHit
                            | JpMethodMemoReadyHit
                            | JpMethodMemoWaitHit
                            | JpMethodMemoDeclaredInterfaceHit -> true
                            | JpMethodMemoCellCreated
                            | JpMethodMemoSharedReentrantBypass
                            | JpMethodMemoSharedConflictBypass
                            | JpMethodMemoSuspectBypass
                            | JpMethodMemoNotApplicable -> false
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":%s,\"computation_kind_du\":%s,\"computation_key\":%s,\"computation_instantiation_ref\":%s,\"join_point_tag\":%d,\"join_point_hkey\":%d,\"memo_probe_du\":%s,\"memo_hit\":%b,\"generation\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"computation_kind_probe_first3_power2_every64\",\"instantiation_sample_du\":\"ExactDigestOnSparseMethodProbe\",\"cell_scope_du\":\"GenerationAffineOwnerIndependentPendingAndCompletedCell\",\"authority\":\"typed_computation_identity_plus_join_point_method_exact_cell\"}" [| box (DiagJson.esc memoEventKind); box (DiagJson.esc computationKind); box (DiagJson.esc methodKey); box (DiagJson.esc instantiationText); box join_point_key.tag; box join_point_key.hkey; box (DiagJson.esc probeText); box memoHit; box memoGeneration; box occurrenceCount |])

                let emitJpMethodMemoConflict observation digests =
                    let observationText = jpMethodMemoConflictObservationText observation
                    let digestsText = digests |> Set.toList |> String.concat ","
                    let occurrenceCount, shouldEmit =
                        DiagJson.sparseLogDecision
                            ("jp_method_memo_conflict|" + methodKey + "|" + observationText + "|" + digestsText)
                            64L
                    if shouldEmit then
                        let currentWorkJobId = jpCurrentWorkJobId ()
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"jp_method_memo_conflict\",\"current_work_job_id\":%d,\"method_key\":%s,\"instantiation_digest\":%s,\"conflict_digests\":%s,\"conflict_observation_du\":%s,\"generation\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"first3_power2_every64_per_method_origin_digest_set\",\"authority\":\"confluent_completed_cell\",\"next\":%s}" [| box currentWorkJobId; box (DiagJson.esc methodKey); box (DiagJson.esc instantiationText); box (DiagJson.esc digestsText); box (DiagJson.esc observationText); box memoGeneration; box occurrenceCount; box (DiagJson.esc (jpMethodMemoConflictNextText observation)) |])

                let tryReadSharedCompletedMemo () =
                    match sharedCompletedMemoPolicy with
                    | JpMethodSharedCompletedMemoOwnerLocalRuntimeEffect effectKind ->
                        jpMethodMemoProbe JpMethodMemoNotApplicable
                        let occurrenceCount, shouldEmit =
                            DiagJson.sparseLogDecision
                                ("jp_method_memo_effectful_shared_bypass|Read|" + methodKey + "|" + jpRuntimeEffectKindText effectKind)
                                64L
                        if shouldEmit then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"jp_method_memo_effectful_shared_bypass\",\"current_work_job_id\":%d,\"method_key\":%s,\"instantiation_ref\":%s,\"effect_kind_du\":%s,\"memo_policy_du\":%s,\"operation_du\":\"Read\",\"generation\":%d,\"occurrence_count\":%d,\"authority\":\"runtime_effect_identity_excludes_shared_confluent_completed_cell\",\"next\":\"preserve_owner_local_effect_result\"}" [| box (jpCurrentWorkJobId ()); box (DiagJson.esc methodKey); box (DiagJson.esc instantiationText); box (DiagJson.esc (jpRuntimeEffectKindText effectKind)); box (DiagJson.esc (jpMethodSharedCompletedMemoPolicyText sharedCompletedMemoPolicy)); box memoGeneration; box occurrenceCount |])
                        None
                    | JpMethodSharedCompletedMemoConfluent ->
                        match jp_method_completed_cells.TryGetValue memoCellIdentity with
                        | true, entry when jpMethodMemoWitnessEquivalent entry.witness memoWitness ->
                            match CompilerKernelV2.ConfluentWorkCell.tryValue entry.cell with
                            | Some retTy -> Some retTy
                            | None ->
                                match CompilerKernelV2.ConfluentWorkCell.conflictDigests entry.cell with
                                | Some digests ->
                                    jpMethodMemoProbe JpMethodMemoSharedConflictBypass
                                    emitJpMethodMemoConflict JpMethodMemoConflictObservedOnRead digests
                                | None -> ()
                                None
                        | true, _ ->
                            jpMethodMemoProbe JpMethodMemoSharedConflictBypass
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"jp_method_memo_witness_collision\",\"method_key\":%s,\"instantiation_digest\":%s,\"generation\":%d,\"authority\":\"full_structural_witness_guard\",\"next\":\"bypass_shared_cell_without_claiming_equivalence\"}" [| box (DiagJson.esc methodKey); box (DiagJson.esc instantiationText); box memoGeneration |])
                            None
                        | _ -> None

                let publishSharedCompletedMemo typeEvidence =
                    let retTy = jpMethodMemoTypeEvidenceCanonicalType typeEvidence
                    match typeEvidence with
                    | JpMethodMemoVerifiedDeclaredInterfaceType (declaredType, inferredBodyType, verification, verificationRef) ->
                        let verificationText = jpMethodMemoDeclaredBodyVerificationText verification
                        let canonicalNext =
                            match verification with
                            | JpMethodMemoDeclaredBodyEquivalent -> "publish_declared_interface_type_to_shared_confluent_cell"
                            | JpMethodMemoDeclaredBodyMismatch -> "preserve_inferred_body_type_conflict_against_declared_interface"
                        let occurrenceCount, shouldEmit =
                            DiagJson.sparseLogDecision
                                ("jp_method_memo_type_authority|" + methodKey + "|" + verificationText)
                                64L
                        if shouldEmit then
                            let currentWorkJobId = jpCurrentWorkJobId ()
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"jp_method_memo_type_authority_canonicalized\",\"current_work_job_id\":%d,\"method_key\":%s,\"instantiation_ref\":%s,\"verification_ref\":%s,\"verification_du\":%s,\"declared_type\":%s,\"inferred_body_type\":%s,\"canonical_type_authority_du\":%s,\"generation\":%d,\"occurrence_count\":%d,\"sparse_policy\":\"first3_power2_every64_per_method_verification\",\"next\":%s}" [| box currentWorkJobId; box (DiagJson.esc methodKey); box (DiagJson.esc instantiationText); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text verificationRef)); box (DiagJson.esc verificationText); box (DiagJson.esc (show_ty declaredType)); box (DiagJson.esc (show_ty inferredBodyType)); box (DiagJson.esc (jpMethodMemoTypeEvidenceAuthorityText typeEvidence)); box memoGeneration; box occurrenceCount; box (DiagJson.esc canonicalNext) |])
                    | _ -> ()
                    match sharedCompletedMemoPolicy with
                    | JpMethodSharedCompletedMemoOwnerLocalRuntimeEffect effectKind ->
                        let occurrenceCount, shouldEmit =
                            DiagJson.sparseLogDecision
                                ("jp_method_memo_effectful_shared_bypass|Publish|" + methodKey + "|" + jpRuntimeEffectKindText effectKind)
                                64L
                        if shouldEmit then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"jp_method_memo_effectful_shared_bypass\",\"current_work_job_id\":%d,\"method_key\":%s,\"instantiation_ref\":%s,\"effect_kind_du\":%s,\"memo_policy_du\":%s,\"operation_du\":\"Publish\",\"canonical_type\":%s,\"generation\":%d,\"occurrence_count\":%d,\"authority\":\"runtime_effect_identity_excludes_shared_confluent_completed_cell\",\"next\":\"publish_owner_local_effect_result_only\"}" [| box (jpCurrentWorkJobId ()); box (DiagJson.esc methodKey); box (DiagJson.esc instantiationText); box (DiagJson.esc (jpRuntimeEffectKindText effectKind)); box (DiagJson.esc (jpMethodSharedCompletedMemoPolicyText sharedCompletedMemoPolicy)); box (DiagJson.esc (show_ty retTy)); box memoGeneration; box occurrenceCount |])
                    | JpMethodSharedCompletedMemoConfluent ->
                        let completedCell =
                            CompilerKernelV2.ConfluentWorkCell.complete
                                memoBinding
                                (int64 (max 0 join_point_key.tag))
                                (jpMethodMemoResultText retTy)
                                retTy
                        let candidate : JpMethodMemoCompletedEntry = { witness = memoWitness; cell = completedCell }
                        let mutable witnessCollision = false
                        let merged =
                            jp_method_completed_cells.AddOrUpdate(
                                memoCellIdentity,
                                candidate,
                                fun _ (current:JpMethodMemoCompletedEntry) ->
                                    if jpMethodMemoWitnessEquivalent current.witness memoWitness then
                                        { current with
                                            cell = CompilerKernelV2.ConfluentWorkCell.merge current.cell completedCell }
                                    else
                                        witnessCollision <- true
                                        current)
                        if witnessCollision then
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"jp_method_memo_witness_collision\",\"method_key\":%s,\"instantiation_digest\":%s,\"generation\":%d,\"authority\":\"full_structural_witness_guard\",\"next\":\"retain_first_witness_and_preserve_owner_local_result\"}" [| box (DiagJson.esc methodKey); box (DiagJson.esc instantiationText); box memoGeneration |])
                        match CompilerKernelV2.ConfluentWorkCell.conflictDigests merged.cell with
                        | Some digests -> emitJpMethodMemoConflict JpMethodMemoConflictObservedOnPublish digests
                        | None -> ()

                // MIGRATION: Create IVar for this JP specialization

                let jp_ivar = Hopac.IVar<JpMethodBodyCellPayload>()
                let portableJpCell : CompilerKernelV2.PortableOneShotCell<JpMethodBodyCellPayload> =
                    CompilerKernelV2.CompilerRuntimeKernel.wrapOneShot<JpMethodBodyCellPayload>
                        ("jp-method-memo:" + methodKey)
                        jp_ivar
                let promiseRegistration =
                    JpPromiseProducerAuthority.registrationFor
                        memoGeneration
                        JpMethodPromiseCell
                        (JpPromiseComputationWitness(methodComputationIdentity, instantiationId))
                        jp_ivar
                let currentMemoOwnerIdentity =
                    match jpCurrentWorkIdentity () with
                    | Some (JpWaiterWorkIdentity workId) ->
                        JpMethodMemoWorkOwner workId
                    | None ->
                        JpMethodMemoHostThreadOwner System.Threading.Thread.CurrentThread.ManagedThreadId

                let deferJpMethodAtSynchronousBoundary disposition =
                    let jp = defaultArg jp_name "<anon>"
                    let placeholder = jp_method_rec_placeholder join_point_key jp
                    DiagJson.emit (
                        FastRuntimeFormat.format "{\"kind\":\"jp_method_synchronous_boundary_deferred\",\"method_key\":%s,\"instantiation_ref\":%s,\"join_point_key\":%s,\"disposition_du\":%s,\"placeholder_du\":%s,\"authority\":\"typed_placeholder_until_async_producer_completion\",\"next\":\"continue_term_evaluation_then_dereference_placeholder\"}" [| box (DiagJson.esc methodKey); box (DiagJson.esc instantiationText); box (DiagJson.esc (jpConsedNodeIdentityText join_point_key)); box (DiagJson.esc (jpMethodSynchronousBoundaryDispositionText disposition)); box (DiagJson.esc (show_ty placeholder)) |])
                    placeholder
                let pendingMemoCandidate : JpMethodMemoPendingEntry = {
                    witness = memoWitness
                    cell = portableJpCell
                    ownerIdentity = currentMemoOwnerIdentity
                }
                let emitEffectfulPendingSharedBypass operation =
                    let occurrence, emitNow =
                        jp_sparse_decision
                            ("jp_method_memo_effectful_shared_bypass|" + methodKey + "|pending|" + operation)
                            32L
                    if emitNow then
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"jp_method_memo_effectful_shared_bypass\",\"method_key\":%s,\"instantiation_ref\":%s,\"operation\":%s,\"policy_du\":%s,\"occurrence\":%d,\"authority\":\"runtime_effect_owner_local_memo_only\",\"next\":\"retain_owner_local_pending_cell_without_cross_owner_equivalence\"}" [| box (DiagJson.esc methodKey); box (DiagJson.esc instantiationText); box (DiagJson.esc operation); box (DiagJson.esc (jpMethodSharedCompletedMemoPolicyText sharedCompletedMemoPolicy)); box occurrence |])
                let tryReadSharedPendingMemo () =
                    match sharedCompletedMemoPolicy with
                    | JpMethodSharedCompletedMemoOwnerLocalRuntimeEffect _ ->
                        emitEffectfulPendingSharedBypass "PendingRead"
                        JpMethodPendingMemoAbsent
                    | JpMethodSharedCompletedMemoConfluent when SuspectCache.currentCount () > 0 ->
                        // Suspect recovery recomputes inline (RecomputeSuspect) instead of waiting on a pending cell.
                        JpMethodPendingMemoAbsent
                    | JpMethodSharedCompletedMemoConfluent ->
                        match jp_method_pending_cells.TryGetValue memoCellIdentity with
                        | true, entry when jpMethodMemoWitnessEquivalent entry.witness memoWitness ->
                            if entry.ownerIdentity = currentMemoOwnerIdentity then
                                jpMethodMemoProbe JpMethodMemoSharedReentrantBypass
                                JpMethodPendingMemoReentrant
                            else
                                JpMethodPendingMemoWait entry.cell
                        | true, _ ->
                            jpMethodMemoProbe JpMethodMemoSharedConflictBypass
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"jp_method_pending_memo_witness_collision\",\"method_key\":%s,\"instantiation_digest\":%s,\"generation\":%d,\"authority\":\"full_structural_witness_guard\",\"next\":\"allow_owner_local_computation_without_claiming_global_equivalence\"}" [| box (DiagJson.esc methodKey); box (DiagJson.esc instantiationText); box memoGeneration |])
                            JpMethodPendingMemoWitnessConflict
                        | _ ->
                            JpMethodPendingMemoAbsent
                let tryClaimSharedPendingMemo () =
                    match sharedCompletedMemoPolicy with
                    | JpMethodSharedCompletedMemoOwnerLocalRuntimeEffect _ ->
                        emitEffectfulPendingSharedBypass "PendingClaim"
                        true
                    | JpMethodSharedCompletedMemoConfluent ->
                        jp_method_pending_cells.TryAdd(memoCellIdentity, pendingMemoCandidate)
                let retireSharedPendingMemo () =
                    match sharedCompletedMemoPolicy with
                    | JpMethodSharedCompletedMemoOwnerLocalRuntimeEffect _ ->
                        emitEffectfulPendingSharedBypass "PendingRetire"
                    | JpMethodSharedCompletedMemoConfluent ->
                        let mutable entry = Unchecked.defaultof<JpMethodMemoPendingEntry>
                        if jp_method_pending_cells.TryGetValue(memoCellIdentity, &entry)
                           && CompilerKernelV2.PortableOneShotCellOps.resourceId entry.cell
                              = CompilerKernelV2.PortableOneShotCellOps.resourceId portableJpCell then
                            let mutable removed = Unchecked.defaultof<JpMethodMemoPendingEntry>
                            jp_method_pending_cells.TryRemove(memoCellIdentity, &removed) |> ignore
    

                let ret_ty =
                    // Generation-affine completed values and pending owners are shared across
                    // owner-local hash-cons tables. A same-work re-entry bypasses the shared
                    // pending cell so recursive placeholders remain local and cycle-safe.
                    match declaredInterfaceClaim, tryReadSharedCompletedMemo (), dict.TryGetValue(join_point_key), tryReadSharedPendingMemo () with
                    | JpMethodDeclaredInterfaceExisting declaredInterface, _, _, _ ->
                        jpMethodMemoProbe JpMethodMemoDeclaredInterfaceHit
                        DiagJson.emit (
                            FastRuntimeFormat.format "{\"kind\":\"jp_method_declared_interface_hit\",\"method_key\":%s,\"instantiation_ref\":%s,\"verification_ref\":%s,\"declared_type\":%s,\"scheduler_wait\":false,\"semantic_authority_du\":\"DeclaredInterfaceReadyBodyVerificationObserver\",\"next\":\"return_declared_interface_without_waiting_for_body_verification\"}" [| box (DiagJson.esc methodKey); box (DiagJson.esc (CompilerKernelV2.InstantiationIdOps.text declaredInterface.instantiationId)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text declaredInterface.verificationRef)); box (DiagJson.esc (show_ty declaredInterface.declaredType)) |])
                        declaredInterface.declaredType
                    | _, Some sharedRetTy, _, _ ->
                        jpMethodMemoProbe JpMethodMemoSharedReadyHit
                        sharedRetTy
                    | _, None, (true, JpIvarReady (JpMethodBodyCellReadyPayload(_, ret_ty, _))), _ ->
                        jpMethodMemoProbe JpMethodMemoReadyHit
                        ret_ty
                    | _, None, (true, JpIvarReady (JpMethodBodyCellCancelledPayload cancellation)), _ ->
                        jpMethodMemoProbe JpMethodMemoReadyHit
                        match cancellation, annot_ty_for_key with
                        | JpMethodPatternMissStasisCancellation(cancellationRef, repeatCount, repeatLimit, stableAgeMs, stableAgeFloorMs, stasisBasis), Some declaredType ->
                            DiagJson.emit (
                                FastRuntimeFormat.format
                                    "{\"kind\":\"jp_method_pattern_miss_control_type_recovered\",\"join_point_key\":%s,\"cancellation_ref\":%s,\"repeat_count\":%d,\"repeat_limit\":%d,\"stable_age_ms\":%d,\"stable_age_floor_ms\":%d,\"stasis_basis_du\":%s,\"declared_type\":%s,\"semantic_failure\":false,\"exception_roundtrip\":false,\"authority\":\"owner_local_cell_terminal_payload_plus_declared_interface\",\"next\":\"keep_codegen_body_control_cancellation_out_of_build_semantic_failure\"}"
                                    [| box (DiagJson.esc (jpConsedNodeIdentityText join_point_key)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text cancellationRef)); box repeatCount; box repeatLimit; box stableAgeMs; box stableAgeFloorMs; box (DiagJson.esc (JpCodegenPatternMissStasisBasisId.text stasisBasis)); box (DiagJson.esc (show_ty declaredType)) |])
                            declaredType
                        | JpMethodPatternMissStasisCancellation(cancellationRef, _, _, _, _, _), None ->
                            raise_type_error (add_trace s r) ("error[EJP0001]: operational pattern-miss stasis has no declared interface type\n  = key: " + jpConsedNodeIdentityText join_point_key + "\n  = cancellation_ref: " + CompilerIdentityKernel.ContentDigest.text cancellationRef + "\n")
                    | _, None, (true, JpIvarReady (JpMethodBodyCellFailedPayload failure)), _ ->
                        jpMethodMemoProbe JpMethodMemoReadyHit
                        failure.Throw()
                        failwith "unreachable after owner-local JP method failure rethrow"
                    | _, None, (true, existing_ivar), _ ->
                        // In progress - wait for it
                        let jp = defaultArg jp_name "<anon>"
                        if SuspectCache.currentCount () > 0 then
                            jpMethodMemoProbe JpMethodMemoSuspectBypass
                            // Global recovery mode: do not wait on potentially poisoned IVars.
                            // Placeholder pattern-miss recovery is a deterministic inline recompute, not an unstable
                            // retry: it must not mark the run sequential (the write guard refuses unstable outputs).
                            if not (PevalStallProbe.recoveryActive ()) then CacheGeneration.requestSequential ()
                            record_jp_diag_method join_point_key jp_name (r :: s.trace) |> ignore
                            let mutable removed = Unchecked.defaultof<_>
                            dict.TryRemove(join_point_key, &removed) |> ignore
                            let annot_val = annot_ty_for_key
                            let jp_method_stack = System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>(s.jp_method_stack, HashIdentity.Reference)
                            let jp_closure_stack = System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>(s.jp_closure_stack, HashIdentity.Reference)
                            let jp_type_stack = System.Collections.Generic.HashSet<ConsedNode<Ty []>>(s.jp_type_stack, jp_type_key_comparer)
                            jp_method_stack.Add join_point_key |> ignore
                            let s = prepareJoinPointBodyEnv jp_method_stack jp_closure_stack jp_type_stack
                            let recursion_site = sprintf "JPMethod.recovery_bypass@%s:%d" r.path (fst r.range).line
                            let recursionEntry = RecursionTracker.enter (CompilerIdentityKernel.WorkSiteIdOps.create recursion_site) s.recursion
                            let s = { s with recursion = RecursionTracker.context recursionEntry }
                            let entry_depth = RecursionTracker.currentDepth s.recursion
                            try
                                BitMamba.recordAccess join_point_key
                                let compute_term () = term_scope'' s body annot_val
                                let seq, ty =
                                    if entry_depth > 64 then
                                        match BigStack.tryRun s.bigStack BigStack.BigStackJoinPoint (sprintf "jp_method_recovery_%d" join_point_key.tag) (fun child -> term_scope'' (langEnvWithBigStack child s) body annot_val) with
                                        | Some v -> v
                                        | None ->
                                            raise_type_error (add_trace s r) (sprintf "%s: JPMethod evaluation refused after BigStack exhaustion (tag=%d)" DiagnosticClassifier.EJP0010 join_point_key.tag)
                                    else compute_term ()
                                jp_method_resolve_rec_placeholder join_point_key ty
                                // Publish the inline body as a ready cell: codegen reads JP method bodies from this
                                // table, and a recomputed key has no owner left to fill it (FRONTIER.md fix 44).
                                dict.[join_point_key] <- Hopac.IVar<JpMethodBodyCellPayload>(JpMethodBodyCellReadyPayload(seq, ty, jp_name))
                                ty
                            finally
                                RecursionTracker.exit recursionEntry |> ignore
                        elif s.jp_method_stack.Contains join_point_key then
                            let cur = trace_to_string_short (r :: s.trace)
                            let snap = diag_snapshot (sprintf "JPMethod.recursive jp=%s" jp)
                            let first_seen =
                                match jp_method_key_traces.TryGetValue join_point_key with
                                | true, tr -> trace_to_string_short tr
                                | _ ->
                                    match jp_name_traces.TryGetValue(JpNameIdOps.create jp) with
                                    | true, tr -> trace_to_string_short tr
                                    | _ -> "<unknown>"
                            let stack_prev = jp_method_stack_preview s.jp_method_stack
                            jp_method_rec_placeholder join_point_key jp
                        else
                            jpMethodMemoProbe JpMethodMemoWaitHit
                            deferJpMethodAtSynchronousBoundary JpMethodDeferredFromExistingCell
                    | _, None, (false, _), JpMethodPendingMemoWait _ ->
                        jpMethodMemoProbe JpMethodMemoSharedWaitHit
                        deferJpMethodAtSynchronousBoundary JpMethodDeferredFromSharedPendingCell
                    | _, None, (false, _), JpMethodPendingMemoReentrant ->
                        let jp = defaultArg jp_name "<anon>"
                        record_jp_diag_method join_point_key jp_name (r :: s.trace) |> ignore
                        jp_method_rec_placeholder join_point_key jp
                    | _, None, (false, _), pendingObservation ->
                        let annot_val = annot_ty_for_key
                        let mutable sharedPendingClaimed = false
                        let tryClaimSharedOwner () =
                            match pendingObservation with
                            | JpMethodPendingMemoWitnessConflict ->
                                dict.TryAdd(join_point_key, jp_ivar)
                            | JpMethodPendingMemoAbsent ->
                                sharedPendingClaimed <- tryClaimSharedPendingMemo ()
                                if sharedPendingClaimed then
                                    if dict.TryAdd(join_point_key, jp_ivar) then true
                                    else
                                        retireSharedPendingMemo ()
                                        false
                                else false
                            | JpMethodPendingMemoWait _
                            | JpMethodPendingMemoReentrant ->
                                false
                        // Domain migration : compute exactly one exhaustive specialization
                        // disposition before taking any recovery or ownership branch.
                        let jp_name_str = defaultArg jp_name "<anon>"
                        let specializationAdmission =
                            if not (LoopSpecializationGuard.tryRecordSpecialization methodKey) then
                                JpSpecializationCapExceeded(
                                    jpLoopSpecializationClassOfName methodKey,
                                    LoopSpecializationGuard.getCount methodKey,
                                    LoopSpecializationGuard.getCapForName methodKey)
                            else
                                let activeSuspects = SuspectCache.currentCount ()
                                let keyMarked = SuspectCache.isSuspect join_point_key
                                if activeSuspects > 0 || keyMarked then
                                    JpSpecializationRecomputeSuspect(activeSuspects, keyMarked)
                                elif tryClaimSharedOwner () then
                                    JpSpecializationAdmitOwnedCell
                                else
                                    JpSpecializationAwaitSharedCell
                        // Evaluate this specialization inline and publish it as a ready cell (the suspect-recovery path;
                        // also the orphan recompute of fix 50).
                        let recomputeInline () =
                            record_jp_diag_method join_point_key jp_name (r :: s.trace) |> ignore
                            let jp_method_stack = System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>(s.jp_method_stack, HashIdentity.Reference)
                            let jp_closure_stack = System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>(s.jp_closure_stack, HashIdentity.Reference)
                            let jp_type_stack = System.Collections.Generic.HashSet<ConsedNode<Ty []>>(s.jp_type_stack, jp_type_key_comparer)
                            jp_method_stack.Add join_point_key |> ignore
                            let s = prepareJoinPointBodyEnv jp_method_stack jp_closure_stack jp_type_stack
                            let recursion_site = sprintf "JPMethod.suspect_bypass@%s:%d" r.path (fst r.range).line
                            let recursionEntry = RecursionTracker.enter (CompilerIdentityKernel.WorkSiteIdOps.create recursion_site) s.recursion
                            let s = { s with recursion = RecursionTracker.context recursionEntry }
