                | DPair(a,b) ->
                    store_term s p1 a
                    store_term s p2 b
                    jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_succ)
                | _ -> jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_fail)
            | EExistsTest(r,bind,pat_type,pat,on_succ,on_fail) ->
                let s = add_trace s r
                match v s bind with
                | DExists(a,b) ->
                    Array.iter2 (store_ty s) pat_type a
                    store_term s pat b
                    jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_succ)
                | DV(L(_,YExists)) -> raise_type_error s "Runtime existentials cannot be destructured. They are a compile time feature only."
                | _ -> jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_fail)
            | ESymbolTest(r,a,bind,on_succ,on_fail) ->
                let s = add_trace s r
                match v s bind with
                | DSymbol a' when a = a' -> jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_succ)
                | _ -> jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_fail)
            | ERecordTest(r,a,bind,on_succ,on_fail) ->
                let s = add_trace s r
                match v s bind with
                | DRecord l ->
                    // ### MIGRATION: stack-safe RecordTest (avoid recursive loop over long field match lists)
                    let mutable xs = a
                    let mutable i = 0
                    let mutable res : Data option = None
                    while res.IsNone do
                        if i > 0 && (i &&& 255) = 0 then
                            match evalStackProbeDecision () with
                            | EvalStackProbeAvailable -> ()
                            | EvalStackProbeInsufficient -> raise (EvalCoreStackPivotRequested EvalCoreRecordTestBatchStackProbe)
                        match xs with
                        | [] ->
                            res <- Some (jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_succ))
                        | x :: rest ->
                            let (key, bvar) =
                                match x with
                                | Symbol((_,a),b) -> a, b
                                | Var((r,a),b) ->
                                    match term s a with
                                    | DSymbol a -> a, b
                                    | a -> raise_type_error (add_trace s r) <| sprintf "Expected a symbol.\nGot: %s" (show_data a)
                            match l |> Map.tryPick (fun (_, k) v -> if k = key then Some v else None) with
                            | Some v ->
                                store_term s bvar v
                                xs <- rest
                                i <- i + 1
                            | None ->
                                res <- Some (jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_fail))
                    match res with
                    | Some v -> v
                    | None -> failwith "Compiler error: RecordTest loop produced no result."
                | _ -> jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_fail)
            | EAnnotTest(r,a,bind,on_succ,on_fail) ->
                let s = add_trace s r
                if data_to_ty s (v s bind) = ty s a
                then jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_succ)
                else jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_fail)
            | EUnitTest(r,bind,on_succ,on_fail) ->
                let s = add_trace s r
                match v s bind with
                | DB -> jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_succ)
                | _ -> jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_fail)
            | ENominalTest(r,a,bind,p1,on_succ,on_fail) ->
                let s = add_trace s r
                match ty s a with
                | YNominal a ->
                    match v s bind with
                    | DNominal((DUnion _ | DV(L(_,YUnion _))),_) -> raise_type_error s "Got an union in a nominal pattern."
                    | DNominal(v,b) ->
                        let rec loop = function
                            | YNominal b ->
                                if a = b then
                                    store_term s p1 v
                                    jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_succ)
                                else
                                    jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_fail)
                            | YApply(a,_) -> loop a
                            | _ -> raise_type_error s <| sprintf "Compiler error: Expected a deferred type apply or a nominal.\nGot: %s" (show_ty b)
                        loop b
                    | _ -> jpWithCurrentDeclaredTailResultBridge JpDeclaredPatternBranchResultBridge (fun () -> term s on_fail)
                | a -> raise_type_error s <| sprintf "Expected a nominal on the left side of the pattern.\nGot: %s" (show_ty a)
            | ELitTest(r,a,bind,on_succ,on_fail) -> let s = add_trace s r in lit_test s a bind on_succ on_fail
            | EDefaultLitTest(r,a,b,bind,on_succ,on_fail) -> let s = add_trace s r in lit_test s (default_lit s a (ty s b)) bind on_succ on_fail
            | ETypecase(r,a,b) ->
                let s = add_trace s r
                let a = ty s a
                let rec loop = function
                    | (a',b) :: rest ->
                        if is_unify s (a,ty s a')
                        then Some (jpWithCurrentDeclaredTailResultBridge JpDeclaredTypecaseBranchResultBridge (fun () -> term s b))
                        else loop rest
                    | [] -> None
                match loop b with
                | Some r -> r
                | None -> raise_type_error s <| sprintf "Typecase miss.\nGot: %s" (show_ty a)
            | EOp(_,ToFunPtr,[a]) ->
                match term s a with
                | DFunction(body,Some(TFun(domain,range,_)),a,b,c,d) -> DFunction(body,Some(TFun(domain,range,FT_Pointer)),a,b,c,d)
                | DV(L(_,YFun _)) -> raise_type_error s <| sprintf "Cannot convert a runtime function to a closure. The closure conversion should be done on a compile time funciton."
                | a -> raise_type_error s <| sprintf "Expected a function.\nGot: %s" (show_data a)
            | EOp(_,ToFunClosure,[a]) ->
                match term s a with
                | DFunction(body,Some(TFun(domain,range,_)),a,b,c,d) -> DFunction(body,Some(TFun(domain,range,FT_Closure)),a,b,c,d)
                | DV(L(_,YFun _)) -> raise_type_error s <| sprintf "Cannot convert a runtime function to a function pointer. The pointer conversion should be done on a compile time funciton."
                | a -> raise_type_error s <| sprintf "Expected a function.\nGot: %s" (show_data a)
            | EOp(_,PragmaUnrollPush,[a]) ->
                match term s a with
                | DLit (LitInt32 _) as x -> push_op_no_rewrite s PragmaUnrollPush x YB
                | a -> raise_type_error s <| sprintf "Expected an i32 literal.\nGot: %s" (show_data a)
            | EOp(_,PragmaUnrollPop,[]) ->
                push_op_no_rewrite' s PragmaUnrollPop [] YB
            | EOp(_,BackendSwitch,[a]) ->
                let mutable t = None
                let mutable d = None
                let normalize_backend_switch_ty x =
                    // SOTA: join-point placeholders can transiently leak under parallel JP retries/generation churn.
                    // BackendSwitch needs a stable shape check without cementing placeholders as concrete types.
                    jp_method_deref_rec_placeholder x
    

                let validate_type t' =
                    let t' = normalize_backend_switch_ty t'
                    match t with
                    | Some t0 ->
                        let t0 = normalize_backend_switch_ty t0
                        if not (ty_eq_allow_jp_placeholders t0 t') then
                            raise_type_error s $"The backend switch needs to have the same type for all of its branches.\nGot: {show_ty t'}\nExpected: {show_ty t0}"
                    | None -> t <- Some t'
                match term s a with
                | DRecord l ->
                    if lock backend_switch_lock (fun () -> backend_switch_validate_all.Value) = false then
                        match map_try_find_by_string s.backend.node l with
                        | Some b ->
                            let d' = apply s (b, DB)
                            validate_type (data_to_ty s d')
                            d <- Some d'
                        | None -> ()
                    else
                        l |> Map.iter (fun (_,backend) b ->
                            // The reason why we're evaling all the branches intead of just one and in this specific order is because otherwise
                            // compile time hashmaps could make type inference unsound.
                            if backend = s.backend.node then
                                let d' = apply s (b, DB)
                                validate_type (data_to_ty s d')
                                d <- Some d'
                            else
                                // MIGRATION: Stack-aware non-current branch validation
                                // Check stack before validation - use BigStack if low, skip if exhausted
                                let stackDecision = evalStackProbeDecision ()
                                
                                // MIGRATION: Check generation before and after validation

                                // If generation changes during validation, skip remaining branches
                                let gen0 = CacheGeneration.current ()
                                

                                let doValidation () =
                                    let old = lock backend_switch_lock (fun () -> backend_switch_validate_all.Value)
                                    lock backend_switch_lock (fun () -> backend_switch_validate_all.Value <- false)
                                    try
                                        let s = {s with seq=ResizeArray(); cse=System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Structural) :: s.cse; backend=lock backend_strings_lock (fun () -> backend_strings.Add backend)}
                                        let d' = apply s (b, DB)
                                        // MIGRATION: Check generation after apply
                                        if CacheGeneration.isStale gen0 then
                                            DiagSidecar.emit (sprintf "BACKEND_SWITCH_VALIDATION: Generation changed during backend_switch validation for '%s' - skipping type check" backend)
                                        else
                                            validate_type (data_to_ty s d')
                                    finally
                                        lock backend_switch_lock (fun () -> backend_switch_validate_all.Value <- old)
                                
                                // MIGRATION: Skip validation if generation is already stale

                                if CacheGeneration.isStale gen0 then
                                    DiagSidecar.emit (sprintf "BACKEND_SWITCH_VALIDATION: Skipping backend_switch validation for '%s' (generation stale)" backend)
                                else
                                    match stackDecision with
                                    | EvalStackProbeAvailable -> doValidation ()
                                    | EvalStackProbeInsufficient ->
                                        // Stack low - try BigStack pivot
                                        match BigStack.tryRun s.bigStack BigStack.BigStackBackendSwitchValidate "backend_switch_validate" (fun _ -> doValidation ()) with
                                        | Some () -> ()  // Validation succeeded on BigStack
                                        | None ->
                                            // BigStack exhausted - skip validation for non-current branch
                                            // This is safe because non-current branches won't execute at runtime
                                            // Type soundness is preserved as long as current branch is validated
                                            DiagSidecar.emit (sprintf "BACKEND_SWITCH_BIGSTACK_UNAVAILABLE: Skipping backend_switch validation for '%s' (stack exhausted, BigStack unavailable)" backend)
                                            ()
                        )
                | a -> raise_type_error s <| sprintf "Expected an record.\nGot: %s" (show_data a)
                match d with
                | Some cur -> cur
                | None -> raise_type_error s $"Cannot find the backend {s.backend.node} in the backend switch op."
            | EOp(_,UnsafeBackendSwitch,[a]) ->
                match term s a with // Unsafe version of the backend switch. Shouldn't ever be mixed with type level computations and bottom up inference.
                | DRecord l -> // Only use it if the code is backend agnostic.
                    match map_try_find_by_string s.backend.node l with
                    | Some b -> apply s (b, DB)
                    | None -> raise_type_error s $"Cannot find the backend {s.backend.node} in the backend switch op."
                | a -> raise_type_error s <| sprintf "Expected an record.\nGot: %s" (show_data a)
            | EOp(_,UsesOriginalTermVars,[a;b]) ->
                let a = term s a |> data_term_vars'
                let b = term s b |> data_term_vars'
                let c = a.Length = b.Length && HashSet(a,HashIdentity.Reference).SetEquals(b)
                DLit(LitBool c)
            | EOp(_,UsesOriginalNominals,[a;b]) ->
                let a = term s a |> data_nominals
                let b = term s b |> data_nominals
                let c = a.Length = b.Length && HashSet(a,HashIdentity.Reference).SetEquals(b)
                DLit(LitBool c)
            | EOp(_,While,[cond;body]) ->
                // When the condition's join point return type is still a placeholder (its body is being
                // evaluated by another job), the call is bound to a fresh `DSymbol "JPMethodUnknownRet(..)"`,
                // and seq_apply's reference check cannot fuse `TyLet x; TyLocalReturnData x` into the single
                // TyLocalReturnOp that While expects. Fuse it here; the IVar force-read below then resolves
                // the real return type. This was the nondeterministic `EJP0010 ... single join point`.
                // A retried evaluation of the condition can also leave the first attempt's call behind:
                // `TyLet (DSymbol "JPMethodUnknownRet(..)") <- TyJoinPoint ..` followed by the retry's
                // `TyLocalReturnOp TyJoinPoint ..`. A placeholder-bound let defines no runtime variable, so the
                // stale call is dropped instead of being emitted twice.
                let withoutStaleCalls (binds: TypedBind [], ty) =
                    let isPlaceholderCall = function
                        | TyLet(DSymbol symbol, _, TyJoinPoint _) -> (tryDecodeJpRecPlaceholderText symbol).IsSome
                        | _ -> false
                    let placeholderCalls = binds |> Array.indexed |> Array.filter (snd >> isPlaceholderCall) |> Array.map fst
                    if binds.Length < 2 || placeholderCalls.Length = 0 then binds, ty
                    else
                        // Keep the call the condition's value comes from: none when the last bind is the retry's
                        // own `TyLocalReturnOp`, else the last placeholder-bound call (fused below).
                        let keep =
                            match Array.last binds with
                            | TyLocalReturnOp(_, TyJoinPoint _, _) -> -1
                            | _ -> Array.last placeholderCalls
                        binds
                        |> Array.indexed
                        |> Array.filter (fun (index, bind) -> not (isPlaceholderCall bind) || index = keep)
                        |> Array.map snd, ty
                let condScope =
                    match withoutStaleCalls (term_scope s cond) with
                    | [|TyLet(bound,letTrace,(TyJoinPoint _ as call)); TyLocalReturnData(returned,_)|], condTy
                        when Object.ReferenceEquals(bound, returned)
                             || (match bound, returned with DSymbol a, DSymbol b -> a = b | _ -> false) ->
                        [|TyLocalReturnOp(letTrace, call, bound)|], condTy
                    | scoped -> scoped
                match condScope with
                | [|TyLocalReturnOp(_,TyJoinPoint cond_call,_)|], cond_ty ->
                    // SOTA: the join-point fast path can return an annotation before the IVar is filled.
                    // Under retries/generation invalidations this annotation can be stale (e.g. unit) even when the real ret_ty is bool.
                    // While is one of the few ops that *must* see the real bool, so we force-read the JPMethod IVar only when the fast path fails.
                    let cond_ty_deref0 = jp_method_deref_rec_placeholder cond_ty
                    let cond_ty_forced =
                        if ty_eq_allow_jp_placeholders cond_ty_deref0 (YPrim BoolT) then cond_ty
                        else
                            match cond_call with
                            | (JPMethod(ownerIdentity, join_point_key), _) ->
                                let backend' = JpBodyOwnerIdentity.backendNode ownerIdentity
                                let (dict, _, cache_gen) =
                                    Utils.memoize join_point_method (fun _ ->
                                        (System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Reference),
                                         HashConsTable(),
                                         CacheGeneration.current ())
                                    ) ownerIdentity
                                let dict =
                                    if CacheGeneration.isStale cache_gen then
                                        let fresh =
                                            (System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Reference),
                                             HashConsTable(),
                                             CacheGeneration.current ())
                                        join_point_method.[ownerIdentity] <- fresh
                                        let (d,_,_) = fresh
                                        d
                                    else dict
                                match dict.TryGetValue(join_point_key) with
                                | true, ivar ->
                                    DiagSidecar.emit (sprintf "while-cond: skip_force key=%O backend=%O" join_point_key backend')
                                    cond_ty
                                | _ -> cond_ty
                            | _ -> cond_ty
                    let cond_ty_deref = jp_method_deref_rec_placeholder cond_ty_forced
                    if ty_eq_allow_jp_placeholders cond_ty_deref (YPrim BoolT) then
                        if ty_is_jp_method_rec_placeholder cond_ty_forced || ty_is_jp_type_rec_placeholder cond_ty_forced then
                            DiagSidecar.emit (sprintf "while-cond: placeholder/forced got=%s got_deref=%s" (show_ty cond_ty_forced) (show_ty cond_ty_deref))
                        match term_scope s body with
                        | body, YB & ty -> push_typedop s (TyWhile(cond_call,body)) ty
                        | _, ty ->
                            let ty_deref = jp_method_deref_rec_placeholder ty
                            raise_type_error s <| sprintf "The body of a while loop must have unit.\nGot: %s\nGot(deref): %s" (show_ty ty) (show_ty ty_deref)
                    else
                        raise_type_error s <| sprintf "apply mismatch (while-cond-type): expected bool.\nGot: %s\nGot(deref): %s" (show_ty cond_ty_forced) (show_ty cond_ty_deref)
                | binds, cond_ty ->
                    // Case, data and op of each bind, without the traces (which drown the shape).
                    let clip (text: string) = if text.Length > 300 then text.Substring(0, 300) + " ..." else text
                    let shape =
                        binds
                        |> Array.map (function
                            | TyLet(d, _, op) -> clip (sprintf "TyLet %A <- %A" d op)
                            | TyLocalReturnOp(_, op, d) -> clip (sprintf "TyLocalReturnOp %A -> %A" op d)
                            | TyLocalReturnData(d, _) -> clip (sprintf "TyLocalReturnData %A" d))
                        |> String.concat "\n"
                    raise_type_error s (sprintf "error[EJP0010]: while expects the condition to be a single join point (no sequencing or extra binds).\nGot %d binds of type %s:\n%s" binds.Length (show_ty cond_ty) shape)
            | EOp(_,Do,[body]) ->
                match term_scope s body with
                | body, YB & ty -> push_typedop s (TyDo body) ty
                | _, ty -> raise_type_error s <| sprintf "The body of the do binding must be of type unit.\nGot: %s" (show_ty ty)
            | EOp(_,Indent,[body]) ->
                let body, ty = term_scope s body
                push_typedop s (TyIndent body) ty
            | EOp(_,(LayoutToHeap | LayoutToHeapMutable | LayoutToStackMutable as op),[a]) ->
                let x = dyn false s (term s a)
                let ty = data_to_ty s x
                let layout =
                    match op with
                    | LayoutToHeap -> Heap
                    | LayoutToHeapMutable -> HeapMutable
                    | LayoutToStackMutable -> StackMutable
                    | _ -> raise_type_error s "Compiler error: Forgot a case in LayoutTo."
                let ret_ty = YLayout(ty,layout)
                let key = TyToLayout(x,ret_ty)
                push_typedop_no_rewrite s key ret_ty
            | EOp(_,LayoutIndex,[a]) ->
                match term s a with
                | DV(L(i,YLayout(ty,layout)) as tyv) as a ->
                    match layout with
                    | StackMutable | HeapMutable -> push_typedop_no_rewrite s (TyLayoutIndexAll tyv) ty
                    | Heap ->
                        match ty with
                        | YRecord l -> DRecord(Map.map (fun (_,b) ty -> push_typedop s (TyLayoutIndexByKey(tyv,LayoutFieldNameIdOps.create b)) ty) l)
                        | _ -> push_typedop s (TyLayoutIndexAll tyv) ty
                | a -> raise_type_error s <| sprintf "Expected a layout type.\nGot: %s" (show_data a)
            | EOp(_,TypeToVar,[EType(_,a)]) -> push_typedop_no_rewrite s (TyOp(TypeToVar,[])) (ty s a)
            | EOp(_,LitToTypeLit,[a]) ->
                match term s a with
                | DLit x -> DTLit x
                | DSymbol x -> DSymbol x
                | a -> raise_type_error s <| sprintf "Expected a symbol or a type literal.\nGot: %s" (show_data a)
            | EOp(_,LitToSymbol,[a]) ->
                match term s a with
                | DLit x ->
                    match x with
                    | LitInt8 a -> a.ToString("R") |> DSymbol
                    | LitInt16 a -> a.ToString("R") |> DSymbol
                    | LitInt32 a -> a.ToString("R") |> DSymbol
                    | LitInt64 a -> a.ToString("R") |> DSymbol
                    | LitUInt8 a -> a.ToString("R") |> DSymbol
                    | LitUInt16 a -> a.ToString("R") |> DSymbol
                    | LitUInt32 a -> a.ToString("R") |> DSymbol
                    | LitUInt64 a -> a.ToString("R") |> DSymbol
                    | LitFloat32 a -> a.ToString("R") |> DSymbol
                    | LitFloat64 a -> a.ToString("R") |> DSymbol
                    | LitBool a -> a.ToString() |> DSymbol
                    | LitChar a -> a.ToString() |> DSymbol
                    | LitString a -> a.ToString() |> DSymbol
                | a -> raise_type_error s <| sprintf "Expected a symbol or a type literal.\nGot: %s" (show_data a)
            | EOp(_,StringLitToSymbol,[a]) ->
                match term s a with
                | DLit(LitString a) -> DSymbol a
                | a -> raise_type_error s <| sprintf "Expected a string literal.\nGot: %s" (show_data a)
            | EOp(_,SymbolToString,[a]) ->
                match term s a with
                | DSymbol a -> DLit (LitString a)
                | a -> raise_type_error s <| sprintf "Expected a symbol.\nGot: %s" (show_data a)
            | EOp(_,TypeToSymbol,[EType(_,a)]) ->
                match ty s a with
                | YSymbol a -> DSymbol a
                | a -> raise_type_error s <| sprintf "Expected a symbol.\nGot: %s" (show_ty a)
            | EOp(_,TypeLitToLit,[EType(_,a)]) ->
                let rec loop = function
                    | YLit a -> DLit a
                    | YSymbol a -> DSymbol a
                    | YNominal _ | YApply _ as a -> loop (nominal_type_apply s a)
                    | a -> raise_type_error s <| sprintf "Expected a type literal or a symbol.\nGot: %s" (show_ty a)
                loop (ty s a)
            | EOp(_,(TypeToVar | TypeToSymbol),[a]) -> raise_type_error s "Expected a type."
            | EOp(_,Dyn,[a]) -> term s a |> dyn true s
            | EOp(_,Export,[name;f]) ->
                match term s name with
                | DLit (LitString _) as name ->
                    match term s f with
                    | DFunction(body,Some(TFun(domain,range,_)),a,b,c,d) ->
                        let f = DFunction(body,Some(TFun(domain,range,FT_Pointer)),a,b,c,d) |> dyn true s
                        push_op_no_rewrite' s Export [name; f] YB
                    | f -> raise_type_error s $"Expected an annotated compile-time function to export (e.g. `(fun (a, b) => f a b) : i32 * i32 -> i32`).\nGot: {show_data f}"
                | name -> raise_type_error s $"Expected a compile-time string as the export name.\nGot: {show_data name}"
            | EOp(_,StringLength,[EType(_,t);a]) ->
                let t = ty s t
                if is_any_int t = false then raise_type_error s <| sprintf "Expected an int.\nGot: %s" (show_ty t)
                match term s a with
                | DLit(LitString str) ->
                    // Strings are UTF-8 at runtime in every native backend, so static length is the UTF-8 byte
                    // count, like the single-flight core (UTF-16 char counts disagreed on non-ASCII text).
                    let length = System.Text.Encoding.UTF8.GetByteCount str
                    match t with
                    | YPrim Int8T -> try DLit (LitInt8 (Convert.ToSByte length)) with :? OverflowException -> raise_type_error s <| sprintf "Literal conversion to i8 failed as the UTF-8 byte length is too large.\nGot: %i" length
                    | YPrim Int16T -> try DLit (LitInt16 (Convert.ToInt16 length)) with :? OverflowException -> raise_type_error s <| sprintf "Literal conversion to i16 failed as the UTF-8 byte length is too large.\nGot: %i" length
                    | YPrim Int32T -> DLit (LitInt32 length)
                    | YPrim Int64T -> DLit (LitInt64 (int64 length))
                    | YPrim UInt8T -> try DLit (LitUInt8 (Convert.ToByte length)) with :? OverflowException -> raise_type_error s <| sprintf "Literal conversion to u8 failed as the UTF-8 byte length is too large.\nGot: %i" length
                    | YPrim UInt16T -> try DLit (LitUInt16 (Convert.ToUInt16 length)) with :? OverflowException -> raise_type_error s <| sprintf "Literal conversion to u16 failed as the UTF-8 byte length is too large.\nGot: %i" length
                    | YPrim UInt32T -> DLit (LitUInt32 (uint32 length))
                    | YPrim UInt64T -> DLit (LitUInt64 (uint64 length))
                    | _ -> failwith "impossible"
                | DV(L(_,YPrim StringT)) & str -> push_typedop s (TyStringLength(t,str)) t
                | x ->
                    let xs = show_data x
                    if isJpRecPlaceholderData x then
                        push_typedop s (TyStringLength(t,x)) t
                    else
                        raise_type_error s <| sprintf "Expected a string.\nGot: %s" xs
            | EOp(_,StringIndex,[a;b]) ->
                match term2 s a b with
                | DLit(LitString a), DLit b ->
                    let b = to_i32 b
                    let bytes = System.Text.Encoding.UTF8.GetBytes a
                    if 0 <= b && b < bytes.Length then bytes.[int b] |> char |> LitChar |> DLit
                    else raise_type_error s <| sprintf "Cannot index into a UTF-8 string of byte length %i at byte index %i." bytes.Length b
                | a,b ->
                    match data_to_ty s a, data_to_ty s b with
                    | at, bt when is_string_allow_jp_placeholders at && is_any_int_allow_jp_placeholders bt -> push_binop s StringIndex (a,b) (YPrim CharT)
                    | a,b -> raise_type_error s <| sprintf "Expected a string and an int as arguments.\nGot: %s\nAnd: %s" (show_ty a) (show_ty b)
            | EOp(_,StringSlice,[a;b;c]) ->
                match term3 s a b c with
                | DLit(LitString a), DLit b, DLit c ->
                    let b,c = to_i32 b, to_i32 c
                    let bytes = System.Text.Encoding.UTF8.GetBytes a
                    if 0 <= b && b <= bytes.Length && c >= b - 1 && c < bytes.Length then
                        if c < b then DLit(LitString "")
                        else
