                        | None ->
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_codegen_jp_body_dict_recheck_missing\",\"event\":\"closure_codegen_missing\",\"body\":%s,\"key\":%s,\"dict\":%d,\"drained_status\":%s,\"drained_kind\":%s,\"drained_site\":%s,\"drained_key\":%s,\"drained_reason\":%s,\"drained_cursor\":%d,\"drained_trace_lines\":%d,\"drained_cell\":%s,\"ew_pending\":%d,\"replay_queue\":%d,\"active_depth\":%d,\"driver_state\":%s,\"replay_complete\":%b,\"write_witness\":%b,\"write_witness_summary\":%s,\"exact_owner_registry_present\":%d,\"exact_owner_key_present\":%d,\"owner_materialization_resolution_du\":%s,\"exact_owner_registry_non_empty\":%d,\"single_flight\":1,\"next\":\"defer_or_fail_codegen_missing_dict\"}" [| box (DiagJson.esc jp_body_name); box (DiagJson.esc jp_key_text); box jp_dict.Count; box (DiagJson.esc drainedStatus); box (DiagJson.esc drainedKind); box (DiagJson.esc drainedSite); box (DiagJson.esc drainedKey); box (DiagJson.esc drainedReason); box drainedCursor; box drainedTraceLines; box (DiagJson.esc drainedCell); box ewPendingNow; box ewQueueNow; box ewActiveNow; box (DiagJson.esc ewDriverNow); box replayCompleteNow; box writeWitnessNow; box (DiagJson.esc writeWitnessSummary); box (if closureOwnerRegistryPresent then 1 else 0); box (if closureOwnerKeyPresent then 1 else 0); box (DiagJson.esc (codegenJpOwnerMaterializationResolutionText ownerMaterializationAfterDrain)); box (if closureOwnerRegistryNonEmpty then 1 else 0) |])
                            None


                    let rec requireResolvedClosureCell afterReplayDrain jp_dict2 =
                        match resolve_v2_from jp_dict2 with
                        | CodegenJpClosureBodyCellReady(data, body) -> data, body
                        | CodegenJpClosureBodyCellCancelled cancellation ->
                            let cancellationRef, repeatCount, repeatLimit, stableAgeMs, stableAgeFloorMs, stasisBasis =
                                match cancellation with
                                | JpClosurePatternMissStasisCancellation(cancellationRef, repeatCount, repeatLimit, stableAgeMs, stableAgeFloorMs, stasisBasis) ->
                                    cancellationRef, repeatCount, repeatLimit, stableAgeMs, stableAgeFloorMs, stasisBasis
                            let ownerResolution = currentClosureOwnerMaterialization ()
                            match ownerResolution with
                            | CodegenJpOwnerMaterializedReady(data, body, _) ->
                                DiagJson.emit (
                                    FastRuntimeFormat.format
                                        "{\"kind\":\"codegen_jp_closure_body_cell_cancelled_owner_materialization_recovered\",\"body\":%s,\"key\":%s,\"repeat_count\":%d,\"stable_age_ms\":%d,\"stasis_basis_du\":%s,\"cancellation_ref\":%s,\"owner_materialization_resolution_du\":%s,\"semantic_failure\":false,\"authority\":\"stale_captured_cancelled_cell_subordinated_to_current_exact_owner_ready_cell\",\"next\":\"continue_codegen_from_current_owner_materialization\"}"
                                        [| box (DiagJson.esc jp_body_name); box (DiagJson.esc jp_key_text); box repeatCount; box stableAgeMs; box (DiagJson.esc (JpCodegenPatternMissStasisBasisId.text stasisBasis)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text cancellationRef)); box (DiagJson.esc (codegenJpOwnerMaterializationResolutionText ownerResolution)) |])
                                data, body
                            | CodegenJpOwnerRegistryMissing
                            | CodegenJpOwnerCellMissing _
                            | CodegenJpOwnerCellPending _
                            | CodegenJpOwnerCellCancelled _
                            | CodegenJpOwnerCellFailed _ ->
                                DiagJson.emit (
                                    FastRuntimeFormat.format
                                        "{\"kind\":\"codegen_jp_closure_body_cell_cancelled_observed\",\"body\":%s,\"key\":%s,\"repeat_count\":%d,\"repeat_limit\":%d,\"stable_age_ms\":%d,\"stable_age_floor_ms\":%d,\"stasis_basis_du\":%s,\"cancellation_ref\":%s,\"owner_materialization_resolution_du\":%s,\"semantic_failure\":false,\"authority\":\"owner_local_closure_cell_cancelled_payload\",\"next\":\"surface_required_codegen_body_unmaterialized_without_cross_owner_reuse\"}"
                                        [| box (DiagJson.esc jp_body_name); box (DiagJson.esc jp_key_text); box repeatCount; box repeatLimit; box stableAgeMs; box stableAgeFloorMs; box (DiagJson.esc (JpCodegenPatternMissStasisBasisId.text stasisBasis)); box (DiagJson.esc (CompilerIdentityKernel.ContentDigest.text cancellationRef)); box (DiagJson.esc (codegenJpOwnerMaterializationResolutionText ownerResolution)) |])
                                let msg =
                                    FastRuntimeFormat.format
                                        "%s: codegen JP closure body cell cancelled by typed pattern-miss stasis; current exact owner has no material body closure%i body=%s key=%s owner_resolution=%s"
                                        [| box DiagnosticClassifier.EJP0035; box i; box jp_body_name; box (FastRuntimeFormat.pretty (box key)); box (codegenJpOwnerMaterializationResolutionText ownerResolution) |]
                                raise (PartEvalTypeError([], msg))
                        | CodegenJpClosureBodyCellFailed failure ->
                            let failureType = failure.SourceException.GetType().FullName
                            DiagJson.emit (
                                FastRuntimeFormat.format
                                    "{\"kind\":\"codegen_jp_closure_body_cell_failure_observed\",\"body\":%s,\"key\":%s,\"exception_type\":%s,\"authority\":\"owner_local_closure_cell_failed_payload\",\"next\":\"rethrow_original_failure_without_codegen_malformed_reclassification\"}"
                                    [| box (DiagJson.esc jp_body_name); box (DiagJson.esc jp_key_text); box (DiagJson.esc failureType) |])
                            failure.Throw()
                            failwith "unreachable after closure body failure rethrow"
                        | CodegenJpClosureBodyCellPending ivar ->
                            DiagJson.emit (
                                FastRuntimeFormat.format
                                    "{\"kind\":\"codegen_jp_closure_body_cell_pending_wait_started\",\"body\":%s,\"key\":%s,\"dict_count\":%d,\"authority\":\"typed_owner_local_pending_cell\",\"next\":\"await_same_one_shot_terminal_payload\"}"
                                    [| box (DiagJson.esc jp_body_name); box (DiagJson.esc jp_key_text); box jp_dict2.Count |])
                            PevalStallProbe.awaitCodegenCellOrFail ivar (fun () -> sprintf "closure body=%s key=%s" jp_body_name jp_key_text)
                            requireResolvedClosureCell afterReplayDrain jp_dict2
                        | CodegenJpClosureBodyCellMissing ->
                            let generation = CacheGeneration.current()
                            let invalidationCount = CacheGeneration.invalidationCount()
                            let sequentialRequested = CacheGeneration.isSequentialRequested()
                            let replayLive = EvalWorklist.codegenJpBodyDictShouldDefer()
                            let recoveryDecision =
                                if afterReplayDrain then CodegenJpBodyDictRetrySequential(generation, invalidationCount)
                                else codegenJpBodyDictRecoveryDecision replayLive sequentialRequested generation invalidationCount
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"codegen_jp_body_cell_recovery_decision\",\"jp_kind_du\":\"closure\",\"body\":%s,\"key\":%s,\"cell_state_du\":\"NotReady\",\"dict_count\":%d,\"replay_live\":%b,\"after_replay_drain\":%b,\"generation\":%d,\"invalidation_count\":%d,\"sequential_requested\":%b,\"decision_du\":%s,\"authority\":\"typed_codegen_body_cell_resolution\"}" [| box (DiagJson.esc jp_body_name); box (DiagJson.esc jp_key_text); box jp_dict2.Count; box replayLive; box afterReplayDrain; box generation; box invalidationCount; box sequentialRequested; box (DiagJson.esc (codegenJpBodyDictRecoveryDecisionText recoveryDecision)) |])
                            match recoveryDecision with
                            | CodegenJpBodyDictDrainReplay ->
                                match tryRefreshClosureJpDictAfterReplayDrain () with
                                | Some refreshedDict -> requireResolvedClosureCell true refreshedDict
                                | None ->
                                    CacheGeneration.requestSequential ()
                                    let msg = FastRuntimeFormat.format "%s: codegen JP closure body cell not ready after live replay drain closure%i body=%s key=%s" [| box DiagnosticClassifier.EJP0014; box i; box jp_body_name; box (FastRuntimeFormat.pretty (box key)) |]
                                    raise (PartEvalTypeError([], msg))
                            | CodegenJpBodyDictRetrySequential _ ->
                                CacheGeneration.requestSequential ()
                                let msg = FastRuntimeFormat.format "%s: codegen JP closure body cell not ready; sequential generation retry requested closure%i body=%s key=%s" [| box DiagnosticClassifier.EJP0014; box i; box jp_body_name; box (FastRuntimeFormat.pretty (box key)) |]
                                raise (PartEvalTypeError([], msg))
                            | CodegenJpBodyDictFailClosed ->
                                let msg = FastRuntimeFormat.format "CODEGEN JP NOT READY closure%i body=%s key=%s dict=%d authority=typed_closed_world_no_live_producer" [| box i; box jp_body_name; box (FastRuntimeFormat.pretty (box key)); box jp_dict2.Count |]
                                DiagSidecar.emit msg
                                raise_codegen_error' [] (None, msg)

                    let domain_args, body =
                        if jp_dict_missing then
                            let msg = FastRuntimeFormat.format "CODEGEN JP MISSING BODY DICT BLOCKED closure%i body=%s key=%s dict=%d" [| box i; box jp_body_name; box (FastRuntimeFormat.pretty (box key)); box jp_dict.Count |]
                            EvalWorklist.pinCodegenJpBodyDictMissing "fsharp_codegen" EvalWorklist.CodegenClosure jp_body_name jp_key_text jp_dict.Count msg
                            let generation = CacheGeneration.current()
                            let invalidationCount = CacheGeneration.invalidationCount()
                            let sequentialRequested = CacheGeneration.isSequentialRequested()
                            let recoveryDecision =
                                codegenJpBodyDictRecoveryDecision
                                    (EvalWorklist.codegenJpBodyDictShouldDefer())
                                    sequentialRequested
                                    generation
                                    invalidationCount
                            DiagJson.emit (
                                FastRuntimeFormat.format "{\"kind\":\"codegen_jp_body_dict_recovery_decision\",\"jp_kind_du\":\"closure\",\"body\":%s,\"key\":%s,\"dict_count\":%d,\"generation\":%d,\"invalidation_count\":%d,\"sequential_requested\":%b,\"decision_du\":%s,\"authority\":\"typed_codegen_recovery\"}" [| box (DiagJson.esc jp_body_name); box (DiagJson.esc ("jp-key-tag:" + string key.tag)); box jp_dict.Count; box generation; box invalidationCount; box sequentialRequested; box (DiagJson.esc (codegenJpBodyDictRecoveryDecisionText recoveryDecision)) |])
                            match recoveryDecision with
                            | CodegenJpBodyDictDrainReplay ->
                                match tryRefreshClosureJpDictAfterReplayDrain () with
                                | Some refreshedDict ->
                                    DiagSidecar.emit (FastRuntimeFormat.format "CODEGEN JP BODY DICT REFRESHED closure%i body=%s key=%s dict=%d" [| box i; box jp_body_name; box (FastRuntimeFormat.pretty (box key)); box refreshedDict.Count |])
                                    requireResolvedClosureCell true refreshedDict
                                | None ->
                                    let ewPendingNow = EvalWorklist.pendingCount()
                                    let ewQueueNow = EvalWorklist.replayQueueDepth()
                                    let ewActiveNow = EvalWorklist.replayDriverActiveDepthValue()
                                    let ewDriverNow = EvalWorklist.replayDriverStatus()
                                    let replayCompleteNow = EvalWorklist.hasReplayComplete()
                                    let writeWitnessNow = EvalWorklist.hasReplayCompleteWriteWitness()
                                    CacheGeneration.requestSequential ()
                                    let deferMsg = FastRuntimeFormat.format "%s: codegen JP body dict missing after replay-drain recheck while producer work was live; sequential generation retry requested closure%i body=%s key=%s dict=%d ew_pending=%d replay_queue=%d active_depth=%d driver=%s replay_complete=%b write_witness=%b" [| box DiagnosticClassifier.EJP0014; box i; box jp_body_name; box (FastRuntimeFormat.pretty (box key)); box jp_dict.Count; box ewPendingNow; box ewQueueNow; box ewActiveNow; box ewDriverNow; box replayCompleteNow; box writeWitnessNow |]
                                    DiagSidecar.emit deferMsg
                                    raise (PartEvalTypeError([], deferMsg))
                            | CodegenJpBodyDictRetrySequential(retryGeneration, retryInvalidationCount) ->
                                CacheGeneration.requestSequential ()
                                let retryMsg =
                                    FastRuntimeFormat.format "%s: codegen JP body dict missing after generation recovery; retry the build through the sequential JP authority closure%i body=%s key=%s dict=%d generation=%d invalidations=%d" [| box DiagnosticClassifier.EJP0014; box i; box jp_body_name; box (FastRuntimeFormat.pretty (box key)); box jp_dict.Count; box retryGeneration; box retryInvalidationCount |]
                                DiagSidecar.emit retryMsg
                                raise (PartEvalTypeError([], retryMsg))
                            | CodegenJpBodyDictFailClosed ->
                                DiagSidecar.emit msg
                                raise_codegen_error' [] (None, msg)
                        else requireResolvedClosureCell false jp_dict
                    {tag=i; free_vars=rdata_free_vars args; domain_args=data_free_vars domain_args; range=range; body=body}
                | YFun(_,_,_) -> raise_codegen_error "Non-standard functions are not supported in the F# backend."
                | _ -> raise_codegen_error """error[EJPX004]: internal compiler error
      |
      = unexpected type in closure join point
      help: capture the stack trace and the inferred/expected types for the closure join point.
    """
                ) (fun s x ->
                let domain =
                    match x.domain_args |> HopacExtensions.S.map (fun (L(i,t)) -> sprintf "v%i : %s" i (tyv t)) with
                    | [||] -> "()"
                    | [|x|] -> sprintf "(%s)" x
                    | x -> String.concat ", " x |> sprintf "struct (%s)"
                line s (FastRuntimeFormat.format "closure%i (%s) %s : %s =" [| box x.tag; box (args_tys x.free_vars); box domain; box (tup_ty x.range) |])
                binds (indent s) x.body
                )
    

        let main = StringBuilder()
        binds {text=main; indent=0} x
    

        let program = StringBuilder()
        env.globals |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        types |> Seq.iteri (fun i x -> program.Append(if i = 0 then "type " else "and ").Append(x) |> ignore)
        functions |> Seq.iteri (fun i x -> program.Append(if i = 0 then "let rec " else "and ").Append(x) |> ignore)
        program.Append(main).ToString()
    

    /// Reads a join point body cell for codegen. `IVar.Now.get` on a cell that is still being filled returns
    /// null, which crashed codegen with a bare NullReferenceException (closures created in the branches of a
    /// runtime `if`, `native_closure_branch`). Wait for the producer instead, bounded, and name the failure.
    let jpBodyCellAwait (cell: Hopac.IVar<'payload>) : 'payload =
        if Hopac.IVar.Now.isFull cell then Hopac.IVar.Now.get cell
        else
            let pending = HopacExtensions.startAsTask (Hopac.IVar.read cell)
            if pending.Wait(TimeSpan.FromSeconds 3.0) then pending.Result
            else
                raise (PartEvalTypeError([],
                    FastRuntimeFormat.format
                        "%s: join point body cell (%s) was never filled before codegen read it"
                        [| box DiagnosticClassifier.EJP0035; box typeof<'payload>.Name |]))

    let jpMethodBodyCellReadyForBackend
        (backendName:string)
        (payload:JpMethodBodyCellPayload)
        : TypedBind [] * Ty * string option =
        match payload with
        | JpMethodBodyCellReadyPayload(body, bodyType, methodName) ->
            body, bodyType, methodName
        | JpMethodBodyCellCancelledPayload _ ->
            let msg =
                FastRuntimeFormat.format
                    "%s: typed JP method cancellation reached %s codegen without a material body"
                    [| box DiagnosticClassifier.EJP0035; box backendName |]
            raise (PartEvalTypeError([], msg))
        | JpMethodBodyCellFailedPayload failure ->
            let failureType = failure.SourceException.GetType().FullName
            DiagJson.emit (
                FastRuntimeFormat.format
                    "{\"kind\":\"codegen_jp_method_body_cell_failure_backend_observed\",\"backend\":%s,\"exception_type\":%s,\"authority\":\"typed_method_cell_failed_payload\",\"next\":\"rethrow_original_failure\"}"
                    [| box (DiagJson.esc backendName); box (DiagJson.esc failureType) |])
            failure.Throw()
            failwith "unreachable after method body failure rethrow"

    let jpClosureBodyCellReadyForBackend
        (backendName:string)
        (payload:JpClosureBodyCellPayload)
        : Data * TypedBind [] =
        match payload with
        | JpClosureBodyCellReadyPayload(domainData, body) ->
            domainData, body
        | JpClosureBodyCellCancelledPayload _ ->
            let msg =
                FastRuntimeFormat.format
                    "%s: typed JP closure cancellation reached %s codegen without a material body"
                    [| box DiagnosticClassifier.EJP0035; box backendName |]
            raise (PartEvalTypeError([], msg))
        | JpClosureBodyCellFailedPayload failure ->
            let failureType = failure.SourceException.GetType().FullName
            DiagJson.emit (
                FastRuntimeFormat.format
                    "{\"kind\":\"codegen_jp_closure_body_cell_failure_backend_observed\",\"backend\":%s,\"exception_type\":%s,\"authority\":\"typed_closure_cell_failed_payload\",\"next\":\"rethrow_original_failure\"}"
                    [| box (DiagJson.esc backendName); box (DiagJson.esc failureType) |])
            failure.Throw()
            failwith "unreachable after closure body failure rethrow"

#else
    /// ## CodegenFsharp

    /// ### backend_nameFsharp
    let backend_nameFsharp = "Fsharp"

    /// ### litFsharp
    let litFsharp = function
        | LitInt8 x -> sprintf "%iy" x
        | LitInt16 x -> sprintf "%is" x
        | LitInt32 x -> sprintf "%i" x
        | LitInt64 x -> sprintf "%iL" x
        | LitUInt8 x -> sprintf "%iuy" x
        | LitUInt16 x -> sprintf "%ius" x
        | LitUInt32 x -> sprintf "%iu" x
        | LitUInt64 x -> sprintf "%iUL" x
        | LitFloat32 x ->
            if x = infinityf then "infinityf"
            elif x = -infinityf then "-infinityf"
            elif Single.IsNaN x then "nanf"
            else x.ToString("R") |> add_dec_point |> sprintf "%sf"
        | LitFloat64 x ->
            if x = infinity then "infinity"
            elif x = -infinity then "-infinity"
            elif Double.IsNaN x then "nan"
            else x.ToString("R") |> add_dec_point
        | LitString x ->
            let strb = StringBuilder(x.Length+2)
            strb.Append '"' |> ignore
            String.iter (function
                | '"' -> strb.Append "\\\""
                | '\b' -> strb.Append @"\b"
                | '\t' -> strb.Append @"\t"
                | '\n' -> strb.Append @"\n"
                | '\r' -> strb.Append @"\r"
                | '\\' -> strb.Append @"\\"
                | x -> strb.Append x
                >> ignore
                ) x
            strb.Append '"' |> ignore
            strb.ToString()
        | LitChar x ->
            match x with
            | '\b' -> @"\b"
            | '\n' -> @"\n"
            | '\t' -> @"\t"
            | '\r' -> @"\r"
            | '\\' -> @"\\"
            | x -> string x
            |> sprintf "'%s'"
        | LitBool x -> if x then "true" else "false"

    /// ### primFsharp
    let primFsharp = function
        | Int8T -> "int8"
        | Int16T -> "int16"
        | Int32T -> "int32"
        | Int64T -> "int64"
        | UInt8T -> "uint8"
        | UInt16T -> "uint16"
        | UInt32T -> "uint32"
        | UInt64T -> "uint64"
        | Float32T -> "float32"
        | Float64T -> "float"
        | BoolT -> "bool"
        | StringT -> "string"
        | CharT -> "char"

    /// ### type_litFsharp
    let type_litFsharp = function
        | YLit x -> litFsharp x
        | YSymbol x -> x
        | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

    /// ### UnionRecFsharp
    type UnionRecFsharp = {tag : int; free_vars : Map<int * string, TyV[]>}

    /// ### LayoutRecFsharp
    type LayoutRecFsharp = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>}

    /// ### MethodRecFsharp
    type MethodRecFsharp = {tag : int; free_vars : L<Tag,Ty>[]; range : Ty; body : TypedBind[]}

    /// ### ClosureRecFsharp
    type ClosureRecFsharp = {tag : int; free_vars : L<Tag,Ty>[]; domain_args : TyV[]; range : Ty; body : TypedBind[]}

    /// ### codegenFsharp
    let codegenFsharp (env : PartEvalResult) (x : TypedBind []) =
        let types = ResizeArray()
        let functions = ResizeArray()

        let print is_type show r =
            let s = {text=StringBuilder(); indent=0}
            show s r
            let text = s.text.ToString()
            if is_type then types.Add(text) else functions.Add(text)

        let layout show =
            let dict' = Dictionary(HashIdentity.Structural)
            let dict = Dictionary(HashIdentity.Reference)
            let f x : LayoutRecFsharp =
                match x with
                | YLayout(x,_) ->
                let x = env.ty_to_data x
                let a, b =
                    match x with
                    | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                    | _ -> data_free_vars x, Map.empty
                {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (3).\nGot: %s{show_ty x}"
            fun x ->
                let mutable dirty = false
                let r = memoize dict (memoize dict' (fun x -> dirty <- true; f x)) x
                if dirty then print true show r
                r

        let union show =
            let dict = Dictionary(HashIdentity.Reference)
            let f (a : Map<int * string,Ty>) : UnionRecFsharp = {free_vars=a |> Map.map (fun _ -> env.ty_to_data >> data_free_vars); tag=dict.Count}
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print true show r
                r

        let jp f show =
            let dict = Dictionary(HashIdentity.Structural)
            let f x = f (x, dict.Count)
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print false show r
                r

        let args x = x |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "
        let show_w = function WV (L(i,_)) -> sprintf "v%i" i | WLit a -> litFsharp a
        let args' x = x |> data_term_vars |> Array.map show_w |> String.concat ", "

        let global' =
            let has_added = HashSet env.globals
            let preserves_duplicate_fragment (x : string) =
                System.String.IsNullOrEmpty x
                || System.Char.IsWhiteSpace x.[0]
                || x.[0] = '}'
            fun x -> if preserves_duplicate_fragment x || has_added.Add(x) then env.globals.Add x

        let rec tyv x =
            match x with
            | YUnion a ->
                let a = a.Item
                match a.layout with
                | UHeap -> sprintf "UH%i" (uheap a.cases).tag
                | UStack -> sprintf "US%i" (ustack a.cases).tag
            | YLayout(_,lay) as a ->
                match lay with
                | Heap -> sprintf "Heap%i" (heap a).tag
                | HeapMutable -> sprintf "Mut%i" (mut a).tag
                | StackMutable -> raise_codegen_error "Compiler error: The F# backend doesn't support stack mutable layout types."
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameFsharp then Some v else None) with
                | Some x -> tup_ty x
                | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_nameFsharp}' field."
            | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_litFsharp a) |> String.concat ""
            | YPrim a -> primFsharp a
            | YArray a -> sprintf "(%s [])" (tup_ty a)
            | YFun(a,b,FT_Vanilla) -> sprintf "(%s -> %s)" (tup_ty a) (tup_ty b)
            | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
            | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
            | a -> raise_codegen_error $"Type not supported in the codegen.\nGot: %A{a}"
        and args_tys x = x |> Array.map (fun (L(i,t)) -> sprintf "v%i : %s" i (tup_ty t)) |> String.concat ", "
        and binds (s : CodegenEnv) (x : TypedBind []) =
            Array.iter (function
                | TyLet(d,trace,a) -> try op s (Some d) a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) -> try op s None a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) -> try line s (tup d) with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) x
        and tup x =
            match data_term_vars x with
            | [||] -> "()"
            | [|x|] -> show_w x
            | x -> Array.map show_w x |> String.concat ", " |> sprintf "struct (%s)"
        and tup_ty x =
            match env.ty_to_data x |> data_free_vars |> Array.map (fun (L(_,x)) -> tyv x) with
            | [||] -> "unit"
            | [|x|] -> x
            | x -> String.concat " * " x |> sprintf "struct (%s)"
        and op s d a =
            let jp (a, b) =
                let args = args b
                match a with
                | JPMethod(a,b) -> sprintf "method%i(%s)" (method (a,b)).tag args
                | JPClosure(a,b) -> sprintf "closure%i(%s)" (closure (a,b)).tag args
            let free_vars do_annot x =
                let f (L(i,t)) = if do_annot then sprintf "v%i : %s" i (tyv t) else sprintf "v%i" i
                match data_free_vars x with
                | [||] -> "()"
                | [|x|] -> f x
                | x -> Array.map f x |> String.concat ", " |> sprintf "struct (%s)"
            let simple x =
                match d with
                | None -> x
                | Some d -> match free_vars true d with "()" -> x | d -> sprintf "let %s = %s" d x
                |> line s
            let complex f =
                match d with
                | None -> f s : unit
                | Some d -> match free_vars true d with "()" -> f s | d -> line s (sprintf "let %s =" d); f (indent s)
            let layout_vars a =
                let f i x =
                    match x with
                    | WV(L(i',_)) -> sprintf "l%i = v%i" i i'
                    | WLit x -> sprintf "l%i = %s" i (litFsharp x)
                a |> data_term_vars |> Array.mapi f |> String.concat "; "
            let layout_index i x =
                x |> Array.map (fun (L(i',_)) -> sprintf "v%i.l%i" i i')
                |> String.concat ", "
                |> function "" -> () | x -> simple x
            let length (a,b) =
                match a with
                | YPrim UInt8T -> sprintf "System.Convert.ToByte %s.Length" (tup b)
                | YPrim UInt16T -> sprintf "System.Convert.ToUInt16 %s.Length" (tup b)
                | YPrim UInt32T -> sprintf "System.Convert.ToUInt32 %s.Length" (tup b)
                | YPrim UInt64T -> sprintf "System.Convert.ToUInt64 %s.Length" (tup b)
                | YPrim Int8T -> sprintf "System.Convert.ToSByte %s.Length" (tup b)
                | YPrim Int16T -> sprintf "System.Convert.ToInt16 %s.Length" (tup b)
                | YPrim Int32T -> sprintf "%s.Length" (tup b)
                | YPrim Int64T -> sprintf "System.Convert.ToInt64 %s.Length" (tup b)
                | _ -> raise_codegen_error "Compiler error: Expected an int in length"
                |> simple
            match a with
            | TyMacro a -> a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup x) | CMType x -> tup_ty x | CMTypeLit x -> type_litFsharp x) |> String.concat "" |> simple
            | TySizeOf t -> simple $"sizeof<{tup_ty t}>"
            | TyIf(cond,tr,fl) ->
                complex <| fun s ->
                line s (sprintf "if %s then" (tup cond))
                binds (indent s) tr
                match fl with
                | [|TyLocalReturnData(DB,_)|] -> ()
                | _ ->
                    line s "else"
                    binds (indent s) fl
            | TyJoinPoint(a,args) -> simple (jp (a, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The F# backend does not support nesting other backends."
            | TyWhile(a,b) ->
                complex <| fun s ->
                line s (sprintf "while %s do" (jp a))
                binds (indent s) b
            | TyDo a ->
                complex <| fun s ->
                line s "do"
                binds (indent s) a
            | TyIndent a ->
                complex <| fun s ->
                binds (indent s) a
            | TyIntSwitch(L(i,_),on_succ,on_fail) ->
                complex <| fun s ->
                line s (sprintf "match v%i with" i)
                Array.iteri (fun i x ->
                    line s (sprintf "| %i ->" i)
                    binds (indent s) x
                    ) on_succ
                line s "| _ ->"
                binds (indent s) on_fail
            | TyUnionUnbox(is,x,on_succs,on_fail) ->
                complex <| fun s ->
                line s (sprintf "match %s with" (is |> List.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "))
                let union_rec, prefix =
                    let x = x.Item
                    match x.layout with
                    | UHeap -> let u = uheap x.cases in u, sprintf "UH%i" u.tag
                    | UStack -> let u = ustack x.cases in u, sprintf "US%i" u.tag
                let case_index k =
                    union_rec.free_vars
                    |> Seq.map (fun (KeyValue ((_,k'),_)) -> k')
                    |> Seq.tryFindIndex (fun k' -> k = k')
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {k}.")
                Map.iter (fun k (a,b) ->
                    let i = case_index k
                    let cases =
                        a |> List.map (fun a ->
                            match data_free_vars a with
                            | [||] -> ""
                            | x -> sprintf "(%s)" (args x)
                            |> sprintf "%s_%i%s" prefix i
                            )
                        |> String.concat ", "
                    line s (sprintf "| %s -> (* %s *)" cases k)
                    binds (indent s) b
                    ) on_succs
                on_fail |> Option.iter (fun b ->
                    line s "| _ ->"
                    binds (indent s) b
                    )
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let union_rec, prefix =
                    match c.layout with
                    | UHeap -> let u = uheap c.cases in u, "UH"
                    | UStack -> let u = ustack c.cases in u, "US"
                let i =
                    union_rec.free_vars
                    |> Seq.map (fun (KeyValue ((_,k),_)) -> k)
                    |> Seq.tryFindIndex (fun k -> a = k)
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {a}.")
                let vars =
                    match data_term_vars b with
                    | [||] -> ""
                    | x -> Array.map show_w x |> String.concat ", " |> sprintf "(%s)"
                sprintf "%s%i_%i%s" prefix union_rec.tag i vars |> simple
            | TyToLayout(a,b) ->
                let a = layout_vars a
                match b with
                | YLayout(_,layout) ->
                    match layout with
                    | Heap -> if a = "" then sprintf "Heap%i()" (heap b).tag else sprintf "{%s} : Heap%i" a (heap b).tag
                    | HeapMutable -> if a = "" then sprintf "Mut%i()" (mut b).tag else sprintf "{%s} : Mut%i" a (mut b).tag
                    | StackMutable -> raise_codegen_error "The F# backend doesn't support stack mutable layout types."
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (4).\nGot: %s{show_ty b}"
                |> simple
            | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The F# backend doesn't support indexing into stack mutable layout types."
                |> fun x -> x.free_vars |> layout_index i
            | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The F# backend doesn't support indexing into stack mutable layout types."
                |> fun x ->
                    x.free_vars_by_key
                    |> Map.tryPick (fun (_, k) v -> if k = key then Some v else None)
                    |> Option.iter (layout_index i)
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
            | TyLayoutMutableSet(L(i,t),b,c) ->
                let a = List.fold (fun s k ->
                    match s with
                    | DRecord l -> l |> Map.pick (fun (_,k') v -> if k' = k then Some v else None)
                    | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t).data b
                Array.iter2 (fun (L(i',_)) b ->
                    line s (sprintf "v%i.l%i <- %s" i i' (show_w b))
                    ) (data_free_vars a) (data_term_vars c)
            | TyArrayLiteral(a,b) -> simple <| sprintf "[|%s|]" (List.map tup b |> String.concat "; ")
            | TyArrayCreate(a,b) ->
                match b with
                | DLit(LitInt32 _) | DV(L(_,YPrim Int32T)) -> simple (sprintf "Array.zeroCreate<%s> (%s)" (tup_ty a) (tup b))
                | _ -> simple (sprintf "Array.zeroCreate<%s> (System.Convert.ToInt32(%s))" (tup_ty a) (tup b))
            | TyArrayLength(a,b) -> length (a,b)
            | TyStringLength(a,b) -> length (a,b)
            | TyFailwith(a,b) -> simple (sprintf "failwith<%s> %s" (tup_ty a) (tup b))
            | TyConv(a,b) ->
                let b = tup b
                match a with
                | YPrim Int8T -> $"int8 {b}"
                | YPrim Int16T -> $"int16 {b}"
                | YPrim Int32T -> $"int32 {b}"
                | YPrim Int64T -> $"int64 {b}"
                | YPrim UInt8T -> $"uint8 {b}"
                | YPrim UInt16T -> $"uint16 {b}"
                | YPrim UInt32T -> $"uint32 {b}"
                | YPrim UInt64T -> $"uint64 {b}"
                | YPrim Float32T -> $"float32 {b}"
                | YPrim Float64T -> $"float {b}"
                | _ -> raise_codegen_error $"Compiler error: Unexpected type in Conv. Got: {show_ty a}"
                |> simple
            | TyApply(L(i,_),b) -> sprintf "v%i %s" i (tup b) |> simple
            | TyOp(Global, [DLit (LitString x)]) -> global' x
            | TyOp(op,l) ->
                match op, l with
                | Dyn,[a] -> tup a
                | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                | StringIndex, [a;b] -> sprintf "%s.[int %s]" (tup a) (tup b)
                | StringSlice, [a;b;c] -> sprintf "%s.[int %s..int %s]" (tup a) (tup b) (tup c)
                | ArrayIndex, [a;b] -> sprintf "%s.[int %s]" (tup a) (tup b)
                | ArrayIndexSet, [a;b;c] -> sprintf "%s.[int %s] <- %s" (tup a) (tup b) (tup c)

                // Math
                | Add, [a;b] -> sprintf "%s + %s" (tup a) (tup b)
                | Sub, [a;b] -> sprintf "%s - %s" (tup a) (tup b)
                | Mult, [a;b] -> sprintf "%s * %s" (tup a) (tup b)
                | Div, [a;b] -> sprintf "%s / %s" (tup a) (tup b)
                | Mod, [a;b] -> sprintf "%s %% %s" (tup a) (tup b)
                | Pow, [a;b] -> sprintf "%s ** %s" (tup a) (tup b)
                | LT, [a;b] -> sprintf "%s < %s" (tup a) (tup b)
                | LTE, [a;b] -> sprintf "%s <= %s" (tup a) (tup b)
                | EQ, [a;b] -> sprintf "%s = %s" (tup a) (tup b)
                | NEQ, [a;b] -> sprintf "%s <> %s" (tup a) (tup b)
                | GT, [a;b] -> sprintf "%s > %s" (tup a) (tup b)
                | GTE, [a;b] -> sprintf "%s >= %s" (tup a) (tup b)
                | BoolAnd, [a;b] -> sprintf "%s && %s" (tup a) (tup b)
                | BoolOr, [a;b] -> sprintf "%s || %s" (tup a) (tup b)
                | BitwiseAnd, [a;b] -> sprintf "%s &&& %s" (tup a) (tup b)
                | BitwiseOr, [a;b] -> sprintf "%s ||| %s" (tup a) (tup b)
                | BitwiseXor, [a;b] -> sprintf "%s ^^^ %s" (tup a) (tup b)
                | BitwiseComplement, [a] -> sprintf "~~~%s" (tup a)

                | ShiftLeft, [a;b] -> sprintf "%s <<< %s" (tup a) (tup b)
                | ShiftRight, [a;b] -> sprintf "%s >>> %s" (tup a) (tup b)

                | Neg, [x] -> sprintf " -%s" (tup x)
                | Log, [x] -> sprintf "log %s" (tup x)
                | Exp, [x] -> sprintf "exp %s" (tup x)
                | Tanh, [x] -> sprintf "tanh %s" (tup x)
                | Sqrt, [x] -> sprintf "sqrt %s" (tup x)
                | Sin, [x] -> sprintf "sin %s" (tup x)
                | Cos, [x] -> sprintf "cos %s" (tup x)
                | NanIs, [x] ->
                    match x with
                    | DLit(LitFloat32 _) | DV(L(_,YPrim Float32T)) -> sprintf "Single.IsNaN(%s)" (tup x)
                    | DLit(LitFloat64 _) | DV(L(_,YPrim Float64T)) -> sprintf "Double.IsNaN(%s)" (tup x)
                    | _ -> raise_codegen_error "Compiler error: Invalid type in NanIs."
                | UnionTag, [DV(L(i,YUnion h))] ->
                    let h = h.Item
                    let ty =
                        match h.layout with
                        | UHeap -> sprintf "UH%i" (uheap h.cases).tag
                        | UStack -> sprintf "US%i" (ustack h.cases).tag
                    let items =
                        h.cases
                        |> Seq.map (fun (KeyValue ((i, _), _)) ->
                            $"{ty}_{i}, {i}"
                        )
                        |> String.concat "; "
                    $"[ {items} ] |> Map |> Map.find v{i}"
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported" op l.Length
                |> simple
        and heap : _ -> LayoutRecFsharp = layout (fun s x ->
            let b = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "l%i : %s" i (tyv t)) |> String.concat "; "
            if b = "" then line s (sprintf "Heap%i() = class end" x.tag)
            else line s (sprintf "Heap%i = {%s}" x.tag b)
            )
        and mut : _ -> LayoutRecFsharp = layout (fun s x ->
            let b = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "mutable l%i : %s" i (tyv t)) |> String.concat "; "
            if b = "" then line s (sprintf "Mut%i() = class end" x.tag)
            else line s (sprintf "Mut%i = {%s}" x.tag b)
            )
        and uheap : _ -> UnionRecFsharp = union (fun s x ->
            line s (sprintf "UH%i =" x.tag)
            x.free_vars |> Map.iter (fun (i,_) a ->
                match a with
                | [||] -> line (indent s) (sprintf "| UH%i_%i" x.tag i)
                | a -> line (indent s) (sprintf "| UH%i_%i of %s" x.tag i (a |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat " * "))
                )
            )
        and ustack : _ -> UnionRecFsharp = union (fun s x ->
            line s (sprintf "[<Struct>] US%i =" x.tag)
            x.free_vars |> Map.iter (fun (i,_) a ->
                match a with
                | [||] -> line (indent s) (sprintf "| US%i_%i" x.tag i)
                | a -> line (indent s) (sprintf "| US%i_%i of %s" x.tag i (a |> Array.mapi (fun i' (L(_,t)) -> sprintf "f%i_%i : %s" i i' (tyv t)) |> String.concat " * "))
                )
            )
        and method : _ -> MethodRecFsharp =
            jp (fun ((jp_body,key & (C(args,_))),i) ->
                match (fst env.join_point_method.[jp_body]).[key] with
                | Some a, Some range, _ -> {tag=i; free_vars=rdata_free_vars args; range=range; body=a}
                | _ -> raise_codegen_error "Compiler error: The method dictionary is malformed"
                ) (fun s x ->
                line s (sprintf "method%i (%s) : %s =" x.tag (args_tys x.free_vars) (tup_ty x.range))
                binds (indent s) x.body
                )
        and closure : _ -> ClosureRecFsharp =
            jp (fun ((jp_body,key & (C(args,_,fun_ty))),i) ->
                match fun_ty with
                | YFun(domain,range,FT_Vanilla) ->
                    match (fst env.join_point_closure.[jp_body]).[key] with
                    | Some(domain_args, body) -> {tag=i; free_vars=rdata_free_vars args; domain_args=data_free_vars domain_args; range=range; body=body}
                    | _ -> raise_codegen_error "Compiler error: The method dictionary is malformed"
                | YFun(_,_,_) -> raise_codegen_error "Non-standard functions are not supported in the F# backend."
                | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."
                ) (fun s x ->
                let domain =
                    match x.domain_args |> Array.map (fun (L(i,t)) -> sprintf "v%i : %s" i (tyv t)) with
                    | [||] -> "()"
                    | [|x|] -> sprintf "(%s)" x
                    | x -> String.concat ", " x |> sprintf "struct (%s)"
                line s (sprintf "closure%i (%s) %s : %s =" x.tag (args_tys x.free_vars) domain (tup_ty x.range))
                binds (indent s) x.body
                )

        let main = StringBuilder()
        binds {text=main; indent=0} x

        let program = StringBuilder()
        env.globals |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        types |> Seq.iteri (fun i x -> program.Append(if i = 0 then "type " else "and ").Append(x) |> ignore)
        functions |> Seq.iteri (fun i x -> program.Append(if i = 0 then "let rec " else "and ").Append(x) |> ignore)
        program.Append(main).ToString()

#endif
#if SPIRAL_CORE_HOPAC
    /// ## CodegenAdapter
    // What the backends shared by both cores (CodegenRust, CodegenDelphi) need from a partial evaluation
    // result. Hopac interns union tags and layout keys, keys methods with their range type and keeps join
    // point bodies in one-shot cells.
    let codegenMethodKeyArgs (key : ConsedNode<RData [] * Ty [] * Ty>) = let args, _, _ = key.node in args
    /// A table for CodegenUtils' `memo`.
    let codegenMemoTable (comparer : IEqualityComparer<'k>) : System.Collections.Concurrent.ConcurrentDictionary<'k, 'v> =
        System.Collections.Concurrent.ConcurrentDictionary(comparer)
    /// RefCounting's decrement table (read by the C, C++ and Python backends).
    type RefcDecrTable = System.Collections.Concurrent.ConcurrentDictionary<TypedBind, TyV Set>
    let refcDecrTable () : RefcDecrTable = System.Collections.Concurrent.ConcurrentDictionary(HashIdentity.Reference)
    let refcDecrAdd (table : RefcDecrTable) key value = table.TryAdd(key, value) |> ignore
    let codegenMethodBody (env : PartEvalResult) backend jp_body key =
        let jp_dict, _, _ = env.join_point_method.[jp_body]
        jpBodyCellAwait jp_dict.[key] |> jpMethodBodyCellReadyForBackend backend
    let codegenClosureBody (env : PartEvalResult) backend jp_body key =
        let jp_dict, _, _ = env.join_point_closure.[jp_body]
        jpBodyCellAwait jp_dict.[key] |> jpClosureBodyCellReadyForBackend backend

#else
    /// ## CodegenAdapter
    // What the backends shared by both cores (CodegenRust, CodegenDelphi) need from a partial evaluation
    // result, in the names hopac's side uses (it interns union tags and layout keys).
    module UnionTagIdOps =
        let text (tag : string) = tag
    module LayoutFieldNameIdOps =
        let matchesText (fieldId : string) (text : string) = fieldId = text
    let codegenMethodKeyArgs (key : ConsedNode<RData [] * Ty []>) = fst key.node
    /// A table for CodegenUtils' `memo`.
    let codegenMemoTable (comparer : IEqualityComparer<'k>) : Dictionary<'k, 'v> = Dictionary(comparer)
    /// RefCounting's decrement table (read by the C, C++ and Python backends).
    type RefcDecrTable = Dictionary<TypedBind, TyV Set>
    let refcDecrTable () : RefcDecrTable = Dictionary(HashIdentity.Reference)
    let refcDecrAdd (table : RefcDecrTable) key value = table.Add(key, value)
    let codegenMethodBody (env : PartEvalResult) (_ : string) jp_body key =
        match (fst env.join_point_method.[jp_body]).[key] with
        | Some body, Some range, name -> body, range, name
        | _ -> raise_codegen_error "Compiler error: The method dictionary is malformed"
    let codegenClosureBody (env : PartEvalResult) (_ : string) jp_body key =
        match (fst env.join_point_closure.[jp_body]).[key] with
        | Some(domain_args, body) -> domain_args, body
        | _ -> raise_codegen_error "Compiler error: The closure dictionary is malformed"

#endif
    /// ## CodegenRust

    /// ### backend_nameRust
    let backend_nameRust = "Rust"

    /// ### litRust
    let litRust = function
        | LitInt8 x -> sprintf "%ii8" x
        | LitInt16 x -> sprintf "%ii16" x
        | LitInt32 x -> sprintf "%ii32" x
        | LitInt64 x -> sprintf "%ii64" x
        | LitUInt8 x -> sprintf "%iu8" x
        | LitUInt16 x -> sprintf "%iu16" x
        | LitUInt32 x -> sprintf "%iu32" x
        | LitUInt64 x -> sprintf "%iu64" x
        | LitFloat32 x ->
            if x = infinityf then "f32::INFINITY"
            elif x = -infinityf then "f32::NEG_INFINITY"
            elif Single.IsNaN x then "f32::NAN"
            else x.ToString("R") |> add_dec_point |> sprintf "%sf32"
        | LitFloat64 x ->
            if x = infinity then "f64::INFINITY"
            elif x = -infinity then "f64::NEG_INFINITY"
            elif Double.IsNaN x then "f64::NAN"
            else x.ToString("R") |> add_dec_point |> sprintf "%sf64"
        | LitString x ->
            let strb = StringBuilder(x.Length+2)
            strb.Append '"' |> ignore
            String.iter (function
                | '"' -> strb.Append "\\\""
                | '\t' -> strb.Append @"\t"
                | '\n' -> strb.Append @"\n"
                | '\r' -> strb.Append @"\r"
                | '\\' -> strb.Append @"\\"
                | x when Char.IsControl x -> strb.Append(sprintf "\\u{%x}" (int x))
                | x -> strb.Append x
                >> ignore
                ) x
            strb.Append '"' |> ignore
            sprintf "Rc::<str>::from(%s)" (strb.ToString())
        | LitChar x ->
            // Like the C backend, a char is one UTF-8 byte.
            if int x > 127 then raise_codegen_error $"The Rust backend represents chars as bytes; '{x}' is not ASCII."
            match x with
            | '\n' -> @"b'\n'"
            | '\t' -> @"b'\t'"
            | '\r' -> @"b'\r'"
            | '\\' -> @"b'\\'"
            | '\'' -> @"b'\''"
            | x when Char.IsControl x -> sprintf "%iu8" (int x)
            | x -> sprintf "b'%c'" x
        | LitBool x -> if x then "true" else "false"

    /// ### primRust
    let primRust = function
        | Int8T -> "i8"
        | Int16T -> "i16"
        | Int32T -> "i32"
        | Int64T -> "i64"
        | UInt8T -> "u8"
        | UInt16T -> "u16"
        | UInt32T -> "u32"
        | UInt64T -> "u64"
        | Float32T -> "f32"
        | Float64T -> "f64"
        | BoolT -> "bool"
        | StringT -> "Rc<str>"
        | CharT -> "u8"

    /// ### type_litRust
    let type_litRust = function
        | YLit x -> litRust x
        | YSymbol x -> x
        | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

    /// ### codegenRust
    /// Values are shared as in F#: everything that is not a primitive lives behind an `Rc` and is cloned at
    /// each use, arrays and mutable layouts behind `Rc<RefCell<_>>`, closures are `Rc<dyn Fn>`.
    let codegenRust (env : PartEvalResult) (x : TypedBind []) =
        let types = ResizeArray()
        let functions = ResizeArray()
        // `pub fn`s for the program's exports; a program with exports is a library (no `main`).
        let exports = ResizeArray()
        let closure_of_var = Dictionary<int, int>()
        let export_names = HashSet<string>()

        let print is_type show r =
            let s = {text=StringBuilder(); indent=0}
            show s r
            let text = s.text.ToString()
            if is_type then types.Add(text) else functions.Add(text)

        let layout show =
            let dict' = codegenMemoTable HashIdentity.Structural
            let dict = codegenMemoTable HashIdentity.Reference
            let f x : LayoutRecFsharp =
                match x with
                | YLayout(x,_) ->
                let x = env.ty_to_data x
                let a, b =
                    match x with
                    | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                    | _ -> data_free_vars x, Map.empty
                {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (3).\nGot: %s{show_ty x}"
            fun x ->
                let mutable dirty = false
                let r = memoize dict (memoize dict' (fun x -> dirty <- true; f x)) x
                if dirty then print true show r
                r

        let union show =
            let dict = codegenMemoTable HashIdentity.Reference
            let f (a : Map<int * string,Ty>) : UnionRecFsharp = {free_vars=a |> Map.map (fun _ -> env.ty_to_data >> data_free_vars); tag=dict.Count}
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print true show r
                r

        let jp f show =
            let dict = codegenMemoTable HashIdentity.Structural
            let f x = f (x, dict.Count)
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print false show r
                r

        // Set while writing a method that calls itself in tail position (Rust has no guaranteed tail
        // calls; the C compiler turns them into jumps): tail values `return`, the self call reassigns the
        // parameters and `continue`s the loop around the body.
        let mutable self_loop : (int * L<Tag,Ty> []) option = None
        let without_self_loop f = let saved = self_loop in self_loop <- None; f (); self_loop <- saved
        let is_copy = function YPrim StringT -> false | YPrim _ -> true | _ -> false
        let var (L(i,t)) = if is_copy t then $"v{i}" else $"v{i}.clone()"
        let args x = x |> Array.map var |> String.concat ", "
        let show_w = function WV x -> var x | WLit a -> litRust a
        // Macros are target code: their variables are named, not cloned, so `!a = !b` assigns.
        let macro_var = function WV (L(i,_)) -> $"v{i}" | WLit a -> litRust a
        let macro_args x = x |> data_term_vars |> Array.map macro_var |> String.concat ", "

        let global' =
            let has_added = HashSet env.globals
            fun x -> if has_added.Add(x) then env.globals.Add x

        let string_slice () =
            global' "fn string_slice(value: &str, from: i64, to: i64) -> Rc<str> {\n    let bytes = value.as_bytes();\n    let length = bytes.len() as i64;\n    if from < 0 || from > length || to < from - 1 || to >= length { std::process::abort(); }\n    if to < from { return Rc::<str>::from(\"\"); }\n    // A slice that starts or ends inside a code point fails like the C and Delphi backends (abort / Halt(3)).\n    if (bytes[from as usize] & 0xC0) == 0x80 || (to + 1 < length && (bytes[(to + 1) as usize] & 0xC0) == 0x80) { std::process::exit(3); }\n    let slice = &bytes[from as usize..(to + 1) as usize];\n    match std::str::from_utf8(slice) { Ok(text) => Rc::<str>::from(text), Err(error) => Rc::<str>::from(std::str::from_utf8(&slice[..error.valid_up_to()]).unwrap_or(\"\")) }\n}"

        let rec tyv x =
            match x with
            | YUnion a ->
                let a = a.Item
                match a.layout with
                | UHeap -> sprintf "Rc<UH%i>" (uheap a.cases).tag
                | UStack -> sprintf "US%i" (ustack a.cases).tag
            | YLayout(_,lay) as a ->
                match lay with
                | Heap -> sprintf "Rc<Heap%i>" (heap a).tag
                | HeapMutable -> sprintf "Rc<RefCell<Mut%i>>" (mut a).tag
                | StackMutable -> raise_codegen_error "Compiler error: The Rust backend doesn't support stack mutable layout types."
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameRust then Some v else None) with
                | Some x -> tup_ty x
                | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_nameRust}' field."
            | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_litRust a) |> String.concat ""
            | YPrim a -> primRust a
            | YArray a -> sprintf "Rc<RefCell<Vec<%s>>>" (tup_ty a)
            | YFun(a,b,_) -> sprintf "Rc<dyn Fn(%s) -> %s>" (params_ty a) (tup_ty b)
            | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
            | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
            | a -> raise_codegen_error $"Type not supported in the codegen.\nGot: %A{a}"
        and params_ty x = env.ty_to_data x |> data_free_vars |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat ", "
        and param_list x = x |> Array.map (fun (L(i,t)) -> $"mut v{i}: {tyv t}") |> String.concat ", "
        and binds (s : CodegenEnv) (x : TypedBind []) =
            Array.iter (function
                | TyLet(d,trace,a) -> try op s (Some d) a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) -> try op s None a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) -> try line s (if self_loop.IsSome then $"return {tup d};" else tup d) with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) x
        and tup x =
            match data_term_vars x with
            | [||] -> "()"
            | [|x|] -> show_w x
            | x -> Array.map show_w x |> String.concat ", " |> sprintf "(%s)"
        and tup_ty x =
            match env.ty_to_data x |> data_free_vars |> Array.map (fun (L(_,x)) -> tyv x) with
            | [||] -> "()"
            | [|x|] -> x
            | x -> String.concat ", " x |> sprintf "(%s)"
        and op s d a =
            let jp (a, b) =
                match a with
                | JPMethod(a,c) -> sprintf "method%i(%s)" (method (a,c)).tag (args b)
                | JPClosure(a,c) -> sprintf "closure%i(%s)" (closure (a,c)).tag (args b)
            // The binding that receives a value: `let mut v: T =` for one variable, a tuple pattern for several.
            let binding d =
                match data_free_vars d with
                | [||] -> None
                | [|L(i,t)|] -> Some $"let mut v{i}: {tyv t} ="
                | x ->
                    let names = x |> Array.map (fun (L(i,_)) -> $"mut v{i}") |> String.concat ", "
                    let tys = x |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat ", "
                    Some $"let ({names}): ({tys}) ="
            let simple x =
                match d with
                | None -> line s (if self_loop.IsSome then $"return {x};" else x)
                | Some d -> match binding d with Some b -> line s $"{b} {x};" | None -> line s $"{x};"
            // A construct with blocks: `head` opens it, `f` writes its body, and it closes with `}` (plus `;` as a statement).
            let complex head (f : CodegenEnv -> unit) =
                match d with
                | None -> line s head; f s; line s "}"
                | Some d ->
                    match binding d with
                    | Some b -> line s $"{b} {head}"; without_self_loop (fun () -> f s); line s "};"
                    | None -> line s head; without_self_loop (fun () -> f s); line s "};"
            let block s (x : TypedBind []) = binds (indent s) x
            let layout_index i (lay : Layout) x =
                let field = match lay with HeapMutable -> $"v{i}.borrow()" | _ -> $"v{i}"
                x |> Array.map (fun (L(i',_)) -> $"{field}.l{i'}.clone()")
                |> function
                    | [||] -> ()
                    | [|x|] -> simple x
                    | x -> String.concat ", " x |> sprintf "(%s)" |> simple
            let length (a,b) len =
                match a with
                | YPrim (Int8T | Int16T | Int32T | Int64T | UInt8T | UInt16T | UInt32T | UInt64T) -> simple $"({tup b}{len} as {tyv a})"
                | _ -> raise_codegen_error "Compiler error: Expected an int in length"
            let union_case_name prefix tag i = $"{prefix}{tag}::{prefix}{tag}_{i}"
            match a with
            | TyMacro a -> a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then macro_args x else (match data_term_vars x with [|x|] -> macro_var x | _ -> tup x)) | CMType x -> tup_ty x | CMTypeLit x -> type_litRust x) |> String.concat "" |> simple
            | TySizeOf t -> simple $"(std::mem::size_of::<{tup_ty t}>() as i32)"
            | TyIf(cond,tr,fl) ->
                complex $"if {tup cond} {{" <| fun s' ->
                    block s' tr
                    match fl with
                    | [|TyLocalReturnData(DB,_)|] -> ()
                    | _ -> line s' "} else {"; block s' fl
            | TyJoinPoint(JPMethod(a,c),args) when d.IsNone && (match self_loop with Some (tag, _) -> (method (a,c)).tag = tag | None -> false) ->
                let parameters = snd self_loop.Value
                match parameters with
                | [||] -> ()
                | [|L(i,_)|] -> line s $"v{i} = {var args.[0]};"
                | _ ->
                    let names = parameters |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
                    let values = Array.map var args |> String.concat ", "
                    line s $"({names}) = ({values});"
                line s "continue;"
            | TyJoinPoint(JPClosure(a,c) as a',args) ->
                match d with
                | Some (DV(L(i,_))) when args.Length = 0 -> closure_of_var.[i] <- (closure (a,c)).tag
                | _ -> ()
                simple (jp (a', args))
            | TyJoinPoint(a,args) -> simple (jp (a, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The Rust backend does not support nesting other backends."
            | TyWhile(a,b) -> complex $"while {jp a} {{" <| fun s' -> without_self_loop (fun () -> block s' b)
            | TyDo a | TyIndent a -> complex "{" <| fun s' -> block s' a
            | TyIntSwitch(L(i,_),on_succ,on_fail) ->
                complex $"match v{i} {{" <| fun s' ->
                    let s'' = indent s'
                    Array.iteri (fun i x -> line s'' $"{i} => {{"; block s'' x; line s'' "}") on_succ
                    line s'' "_ => {"; block s'' on_fail; line s'' "}"
            | TyUnionUnbox(is,x,on_succs,on_fail) ->
                let x' = x.Item
                let union_rec, prefix =
                    match x'.layout with
                    | UHeap -> uheap x'.cases, "UH"
                    | UStack -> ustack x'.cases, "US"
                let scrutinee (L(i,_)) = match x'.layout with UHeap -> $"&*v{i}" | UStack -> $"&v{i}"
                let case_tag k =
                    union_rec.free_vars
                    |> Seq.tryPick (function KeyValue ((tag, name), _) when name = UnionTagIdOps.text k -> Some tag | _ -> None)
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text k}.")
                let scrutinees = is |> List.map scrutinee
                let head = match scrutinees with [x] -> x | x -> String.concat ", " x |> sprintf "(%s)"
                complex $"match {head} {{" <| fun s' ->
                    let s'' = indent s'
                    Map.iter (fun k (a,b) ->
                        let i = case_tag k
                        let fields = a |> List.map data_free_vars
                        let patterns =
                            fields |> List.map (fun vars ->
                                match vars with
                                | [||] -> union_case_name prefix union_rec.tag i
                                | vars -> vars |> Array.map (fun (L(v,_)) -> $"v{v}") |> String.concat ", " |> sprintf "%s(%s)" (union_case_name prefix union_rec.tag i))
                        let pattern = match patterns with [x] -> x | x -> String.concat ", " x |> sprintf "(%s)"
                        line s'' $"{pattern} => {{ // {UnionTagIdOps.text k}"
                        fields |> List.iter (Array.iter (fun (L(v,t)) -> line (indent s'') $"let mut v{v}: {tyv t} = v{v}.clone();"))
                        block s'' b
                        line s'' "}"
                        ) on_succs
                    match on_fail with
                    | Some b -> line s'' "_ => {"; block s'' b; line s'' "}"
                    | None -> line s'' "_ => unreachable!(),"
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let union_rec, prefix =
                    match c.layout with
                    | UHeap -> uheap c.cases, "UH"
                    | UStack -> ustack c.cases, "US"
                let i =
                    union_rec.free_vars
                    |> Seq.tryPick (function KeyValue ((tag, name), _) when name = UnionTagIdOps.text a -> Some tag | _ -> None)
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text a}.")
                let value =
                    match data_term_vars b with
                    | [||] -> union_case_name prefix union_rec.tag i
                    | x -> Array.map show_w x |> String.concat ", " |> sprintf "%s(%s)" (union_case_name prefix union_rec.tag i)
                match c.layout with
                | UHeap -> $"Rc::new({value})"
                | UStack -> value
                |> simple
            | TyToLayout(a,b) ->
                let fields = a |> data_term_vars |> Array.mapi (fun i x -> $"l{i}: {show_w x}") |> String.concat ", "
                match b with
                | YLayout(_,Heap) -> $"Rc::new(Heap{(heap b).tag} {{ {fields} }})"
                | YLayout(_,HeapMutable) -> $"Rc::new(RefCell::new(Mut{(mut b).tag} {{ {fields} }}))"
                | YLayout(_,StackMutable) -> raise_codegen_error "The Rust backend doesn't support stack mutable layout types."
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (4).\nGot: %s{show_ty b}"
                |> simple
            | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The Rust backend doesn't support indexing into stack mutable layout types."
                |> fun x -> layout_index i lay x.free_vars
            | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The Rust backend doesn't support indexing into stack mutable layout types."
                |> fun x ->
                    x.free_vars_by_key
                    |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)
                    |> Option.iter (layout_index i lay)
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
            | TyLayoutMutableSet(L(i,t),b,c) ->
                let a = List.fold (fun s k ->
                    match s with
                    | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                    | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t).data b
                Array.iter2 (fun (L(i',_)) b -> line s $"v{i}.borrow_mut().l{i'} = {show_w b};") (data_free_vars a) (data_term_vars c)
                if d.IsNone then line s "()"
            | TyArrayLiteral(a,b) -> simple $"""Rc::new(RefCell::new(vec![{List.map tup b |> String.concat ", "}]))"""
            | TyArrayCreate(a,b) -> simple $"Rc::new(RefCell::new(vec![<{tup_ty a}>::default(); {tup b} as usize]))"
            | TyArrayLength(a,b) -> length (a,b) ".borrow().len()"
            | TyStringLength(a,b) -> length (a,b) ".len()"
            | TyFailwith(a,b) -> simple $"{{ eprintln!(\"{{}}\", {tup b}); std::process::exit(1) }}"
            | TyConv(a,b) ->
                match a with
                | YPrim (Int8T | Int16T | Int32T | Int64T | UInt8T | UInt16T | UInt32T | UInt64T | Float32T | Float64T) -> simple $"({tup b} as {tyv a})"
                | _ -> raise_codegen_error $"Compiler error: Unexpected type in Conv. Got: {show_ty a}"
            | TyApply(L(i,_),b) -> simple $"""v{i}({data_term_vars b |> Array.map show_w |> String.concat ", "})"""
            | TyOp(Global, [DLit (LitString x)]) -> global' x
            | TyOp(Export, [DLit (LitString name); DV(L(i,YFun(domain,range,_)))]) ->
                if not (export_names.Add name) then raise_codegen_error $"Duplicate export: {name}."
                let tag =
                    match closure_of_var.TryGetValue i with
                    | true, tag -> tag
                    | _ -> raise_codegen_error $"Compiler error: the exported function {name} is not a closure without captures."
                // Strings cross as `&str` and come back as `Rc<str>`.
                let parameters = env.ty_to_data domain |> data_free_vars
                let decl = parameters |> Array.map (fun (L(k,t)) -> match t with YPrim StringT -> $"v{k}: &str" | t -> $"v{k}: {tyv t}") |> String.concat ", "
                let call = parameters |> Array.map (fun (L(k,t)) -> match t with YPrim StringT -> $"Rc::<str>::from(v{k})" | _ -> $"v{k}") |> String.concat ", "
                exports.Add($"pub fn {name}({decl}) -> {tup_ty range} {{\n    closure{tag}()({call})\n}}\n")
                if d.IsNone then line s "()"
            | TyOp(op,l) ->
                let unary f = match l with [x] -> f $"({tup x})" | _ -> raise_codegen_error $"Compiler error: {op} expects one argument."
                match op, l with
                | Dyn,[a] -> tup a
                | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                | StringIndex, [a;b] -> $"{tup a}.as_bytes()[{tup b} as usize]"
                | StringSlice, [a;b;c] -> string_slice (); $"string_slice(&{tup a}, {tup b} as i64, {tup c} as i64)"
                | StaticStringConcat, [a;b] -> $"Rc::<str>::from(format!(\"{{}}{{}}\", {tup a}, {tup b}))"
                | ArrayIndex, [a;b] -> $"{tup a}.borrow()[{tup b} as usize].clone()"
                | ArrayIndexSet, [a;b;c] -> $"{tup a}.borrow_mut()[{tup b} as usize] = {tup c}"

                // Math
                | Add, [a;b] -> $"{tup a} + {tup b}"
                | Sub, [a;b] -> $"{tup a} - {tup b}"
                | Mult, [a;b] -> $"{tup a} * {tup b}"
                | Div, [a;b] -> $"{tup a} / {tup b}"
                | Mod, [a;b] -> $"{tup a} %% {tup b}"
                | Pow, [a;b] -> $"{tup a}.powf({tup b})"
                | LT, [a;b] -> $"{tup a} < {tup b}"
                | LTE, [a;b] -> $"{tup a} <= {tup b}"
                | EQ, [a;b] -> $"{tup a} == {tup b}"
                | NEQ, [a;b] -> $"{tup a} != {tup b}"
                | GT, [a;b] -> $"{tup a} > {tup b}"
                | GTE, [a;b] -> $"{tup a} >= {tup b}"
                | BoolAnd, [a;b] -> $"{tup a} && {tup b}"
                | BoolOr, [a;b] -> $"{tup a} || {tup b}"
                | BitwiseAnd, [a;b] -> $"{tup a} & {tup b}"
                | BitwiseOr, [a;b] -> $"{tup a} | {tup b}"
                | BitwiseXor, [a;b] -> $"{tup a} ^ {tup b}"
                | BitwiseComplement, [a] -> $"!{tup a}"
                | ShiftLeft, [a;b] -> $"{tup a} << {tup b}"
                | ShiftRight, [a;b] -> $"{tup a} >> {tup b}"

                | Neg, _ -> unary (sprintf "-%s")
                | Log, _ -> unary (sprintf "%s.ln()")
                | Exp, _ -> unary (sprintf "%s.exp()")
                | Tanh, _ -> unary (sprintf "%s.tanh()")
                | Sqrt, _ -> unary (sprintf "%s.sqrt()")
                | Sin, _ -> unary (sprintf "%s.sin()")
                | Cos, _ -> unary (sprintf "%s.cos()")
                | NanIs, _ -> unary (sprintf "%s.is_nan()")
                | StdoutFlush, [] -> "{ use std::io::Write; std::io::stdout().flush().unwrap(); }"
                | MonotonicDelayMs, [a] -> $"std::thread::sleep(std::time::Duration::from_millis({tup a} as u64))"
                | Printf, [DLit (LitString "%s"); b] -> $"print!(\"{{}}\", {tup b})"
                | UnionTag, [DV(L(i,YUnion _))] ->
                    let ty = match d with Some (DV(L(_,t))) -> tyv t | _ -> "i32"
                    $"(v{i}.tag() as {ty})"
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported in the Rust backend" op l.Length
                |> simple
        and heap : _ -> LayoutRecFsharp = layout (fun s x ->
            let fields = x.free_vars |> Array.map (fun (L(i,t)) -> $"l{i}: {tyv t}") |> String.concat ", "
            line s $"struct Heap{x.tag} {{ {fields} }}"
            )
        and mut : _ -> LayoutRecFsharp = layout (fun s x ->
            let fields = x.free_vars |> Array.map (fun (L(i,t)) -> $"l{i}: {tyv t}") |> String.concat ", "
            line s $"struct Mut{x.tag} {{ {fields} }}"
            )
        and union_type prefix (s : CodegenEnv) (x : UnionRecFsharp) =
            let name = $"{prefix}{x.tag}"
            line s "#[derive(Clone)]"
            line s $"enum {name} {{"
            x.free_vars |> Map.iter (fun (i,_) a ->
                match a with
                | [||] -> line (indent s) $"{name}_{i},"
                | a -> line (indent s) $"""{name}_{i}({a |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat ", "}),"""
                )
            line s "}"
            line s $"impl {name} {{"
            line (indent s) "fn tag(&self) -> i32 {"
            line (indent (indent s)) "match self {"
            x.free_vars |> Map.iter (fun (i,_) a ->
                let pattern = match a with [||] -> $"{name}::{name}_{i}" | _ -> $"{name}::{name}_{i}(..)"
                line (indent (indent (indent s))) $"{pattern} => {i},"
                )
            line (indent (indent s)) "}"
            line (indent s) "}"
            line s "}"
        and uheap : _ -> UnionRecFsharp = union (union_type "UH")
        and ustack : _ -> UnionRecFsharp = union (union_type "US")
        and method : _ -> MethodRecFsharp =
            jp (fun ((jp_body,key),i) ->
                let args = codegenMethodKeyArgs key
                match codegenMethodBody env "Rust" jp_body key with
                | a, range, _ -> {tag=i; free_vars=rdata_free_vars args; range=range; body=a}
                ) (fun s x ->
                line s $"fn method{x.tag}({param_list x.free_vars}) -> {tup_ty x.range} {{"
                let saved = self_loop
                if self_tail x.tag x.body then
                    self_loop <- Some (x.tag, x.free_vars)
                    line (indent s) "loop {"
                    binds (indent (indent s)) x.body
                    line (indent s) "}"
                else
                    self_loop <- None
                    binds (indent s) x.body
                self_loop <- saved
                line s "}"
                )
        and self_tail tag (body : TypedBind []) =
            body.Length > 0 &&
            match Array.last body with
            | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) -> (method (a,c)).tag = tag
            | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> self_tail tag tr || self_tail tag fl
            | TyLocalReturnOp(_, TyUnionUnbox(_,_,on_succs,on_fail), _) -> (on_succs |> Map.exists (fun _ (_,b) -> self_tail tag b)) || (on_fail |> Option.exists (self_tail tag))
            | TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _) -> Array.exists (self_tail tag) on_succ || self_tail tag on_fail
            | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> self_tail tag b
            | _ -> false
        and closure : _ -> ClosureRecFsharp =
            jp (fun ((jp_body,key & (C(args,_,fun_ty))),i) ->
                match fun_ty with
                | YFun(domain,range,_) ->
                    match codegenClosureBody env "Rust" jp_body key with
                    | domain_args, body -> {tag=i; free_vars=rdata_free_vars args; domain_args=data_free_vars domain_args; range=range; body=body}
                | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."
                ) (fun s x ->
                let domain_tys = x.domain_args |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat ", "
                let range = tup_ty x.range
                line s $"fn closure{x.tag}({param_list x.free_vars}) -> Rc<dyn Fn({domain_tys}) -> {range}> {{"
                line (indent s) $"Rc::new(move |{param_list x.domain_args}| -> {range} {{"
                without_self_loop (fun () -> binds (indent (indent s)) x.body)
                line (indent s) "})"
                line s "}"
                )

        let main = StringBuilder()
        binds {text=main; indent=4} x

        let program = StringBuilder()
        program.AppendLine("#![allow(unused_mut, unused_variables, unused_imports, unused_parens, unused_braces, unused_assignments, dead_code, non_snake_case, non_camel_case_types, unreachable_patterns, unreachable_code, while_true)]") |> ignore
        // Inner attributes (`#![...]`) must precede every item, so such globals go before the `use`s.
        let inner, globals = env.globals |> Seq.toArray |> Array.partition (fun (x : string) -> x.TrimStart().StartsWith "#![")
        inner |> Array.iter (fun x -> program.AppendLine(x) |> ignore)
        program.AppendLine("use std::cell::RefCell;").AppendLine("use std::rc::Rc;") |> ignore
        globals |> Array.iter (fun x -> program.AppendLine(x) |> ignore)
        types |> Seq.iter (fun x -> program.Append(x) |> ignore)
        functions |> Seq.iter (fun x -> program.Append(x) |> ignore)
        if exports.Count > 0 then
            exports |> Seq.iter (fun x -> program.Append(x) |> ignore)
            program.ToString()
        else
            program.AppendLine("fn spiral_main() -> i32 {").Append(main).AppendLine("}") |> ignore
            // A large stack: mutual tail recursion that the C compiler turns into jumps recurses here.
            program.AppendLine("fn main() {").AppendLine("    let main = std::thread::Builder::new().stack_size(1 << 30).spawn(spiral_main).unwrap();").AppendLine("    std::process::exit(main.join().unwrap());").AppendLine("}").ToString()

    /// ## CodegenDelphi

    /// ### backend_nameDelphi
    let backend_nameDelphi = "Delphi"

    /// ### litDelphi
    let litDelphi = function
        | LitInt8 x -> if x < 0y then sprintf "(%i)" x else sprintf "%i" x
        | LitInt16 x -> if x < 0s then sprintf "(%i)" x else sprintf "%i" x
        | LitInt32 x -> if x < 0 then sprintf "(%i)" x else sprintf "%i" x
        | LitInt64 x -> if x < 0L then sprintf "(%i)" x else sprintf "%i" x
        | LitUInt8 x -> sprintf "%i" x
        | LitUInt16 x -> sprintf "%i" x
        | LitUInt32 x -> sprintf "%i" x
        | LitUInt64 x -> sprintf "%i" x
        | LitFloat32 x ->
            if x = infinityf then "Infinity"
            elif x = -infinityf then "(-Infinity)"
            elif Single.IsNaN x then "NaN"
            else x.ToString("R") |> add_dec_point |> fun x -> if x.StartsWith "-" then $"({x})" else x
        | LitFloat64 x ->
            if x = infinity then "Infinity"
            elif x = -infinity then "(-Infinity)"
            elif Double.IsNaN x then "NaN"
            else x.ToString("R") |> add_dec_point |> fun x -> if x.StartsWith "-" then $"({x})" else x
        | LitString x ->
            // Pascal quotes with '' and spells control characters (and the UTF-8 bytes of the rest) as #n.
            if x = "" then "''" else
            let strb = StringBuilder()
            let mutable quoted = false
            for b in Text.Encoding.UTF8.GetBytes x do
                if b >= 32uy && b < 127uy then
                    if not quoted then strb.Append '\'' |> ignore; quoted <- true
                    if b = byte '\'' then strb.Append "''" |> ignore else strb.Append (char b) |> ignore
                else
                    if quoted then strb.Append '\'' |> ignore; quoted <- false
                    strb.Append('#').Append(int b) |> ignore
            if quoted then strb.Append '\'' |> ignore
            strb.ToString()
        | LitChar x ->
            if int x > 127 then raise_codegen_error $"The Delphi backend represents chars as bytes; '{x}' is not ASCII."
            elif x >= ' ' && x <> '\'' && int x < 127 then sprintf "'%c'" x
            else sprintf "#%i" (int x)
        | LitBool x -> if x then "True" else "False"

    /// ### primDelphi
    let primDelphi = function
        | Int8T -> "ShortInt"
        | Int16T -> "SmallInt"
        | Int32T -> "LongInt"
        | Int64T -> "Int64"
        | UInt8T -> "Byte"
        | UInt16T -> "Word"
        | UInt32T -> "LongWord"
        | UInt64T -> "QWord"
        | Float32T -> "Single"
        | Float64T -> "Double"
        | BoolT -> "Boolean"
        | StringT -> "AnsiString"
        | CharT -> "AnsiChar"

    /// ### type_litDelphi
    let type_litDelphi = function
        | YLit x -> litDelphi x
        | YSymbol x -> x
        | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

    /// ### BindsReturnDelphi
    /// Where a statement's value goes: into these locals, or the function's result (Tail with its type).
    type BindsReturnDelphi = DLocal of TyV [] | DTail of Ty

    /// ### codegenDelphi
    /// Statement-oriented like the C backend: every value is assigned to a local declared in the function's
    /// `var` section. Arrays and strings are Pascal's reference-counted dynamic arrays and AnsiStrings;
    /// heap unions, mutable layouts and closures are classes (FPC 3.2 has no ARC for classes, so they are
    /// not freed); immutable layouts, stack unions and tuples are records.
    let codegenDelphi (env : PartEvalResult) (x : TypedBind []) =
        let forwards = ResizeArray()
        let types = ResizeArray()
        let headers = ResizeArray()
        let bodies = ResizeArray()
        let globals = ResizeArray()

        let memo (f : 'k -> int -> unit) =
            let dict = Dictionary<'k, int>(HashIdentity.Structural)
            fun (k : 'k) ->
                match dict.TryGetValue k with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[k] <- tag
                    f k tag
                    tag
        let memo_ref (f : 'k -> int -> unit) =
            let dict = Dictionary<'k, int>(HashIdentity.Reference)
            fun (k : 'k) ->
                match dict.TryGetValue k with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[k] <- tag
                    f k tag
                    tag
        let global' =
            let has_added = HashSet env.globals
            fun x -> if has_added.Add(x) then globals.Add x

        // Locals of the function being generated, in declaration order.
        let new_locals (parameters : TyV []) =
            let names = HashSet(parameters |> Array.map (fun (L(i,_)) -> i))
            let decls = ResizeArray<string>()
            names, decls
        let text (s : CodegenEnv) = s.text.ToString()

        let is_float = function DV(L(_,YPrim (Float32T | Float64T))) | DLit(LitFloat32 _ | LitFloat64 _) -> true | _ -> false
        let prim_of = function DV(L(_,YPrim t)) -> Some t | DLit (LitInt8 _) -> Some Int8T | DLit (LitInt16 _) -> Some Int16T | DLit (LitInt32 _) -> Some Int32T | DLit (LitInt64 _) -> Some Int64T | _ -> None
        let show_w = function WV (L(i,_)) -> $"v{i}" | WLit a -> litDelphi a
        let args (x : TyV []) = x |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
        let args' x = data_term_vars x |> Array.map show_w |> String.concat ", "

        let string_slice () =
            global' "function StringSlice(const value: AnsiString; from, upto: Int64): AnsiString;\nvar len: Int64;\nbegin\n  len := Length(value);\n  if (from < 0) or (from > len) or (upto < from - 1) or (upto >= len) then Halt(3);\n  if upto < from then Exit('');\n  if ((Ord(value[from + 1]) and $C0) = $80) or ((upto + 1 < len) and ((Ord(value[upto + 2]) and $C0) = $80)) then Halt(3);\n  Result := Copy(value, from + 1, upto - from + 1);\nend;"

        let layout_tags = Dictionary<Ty, LayoutRecFsharp>(HashIdentity.Structural)
        // The method being written when it calls itself in tail position: its body loops, tail values
        // `Exit`, and the self call reassigns the parameters and `Continue`s.
        let mutable self_loop : (int * TyV []) option = None
        let rec tyv x =
            match x with
            | YUnion a ->
                let a = a.Item
                match a.layout with
                | UHeap -> sprintf "TUH%i" (uheap a.cases)
                | UStack -> sprintf "TUS%i" (ustack a.cases)
            | YLayout(_,lay) as a ->
                match lay with
                | Heap -> sprintf "THeap%i" (heap a).tag
                | HeapMutable -> sprintf "TMut%i" (mut a).tag
                | StackMutable -> raise_codegen_error "Compiler error: The Delphi backend doesn't support stack mutable layout types."
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameDelphi then Some v else None) with
                | Some x -> tup_ty x
                | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_nameDelphi}' field."
            | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_litDelphi a) |> String.concat ""
            | YPrim a -> primDelphi a
            | YArray a -> sprintf "TArray%i" (array_type (tup_ty a))
            | YFun(a,b,_) -> sprintf "TFun%i" (fun_type (a, b))
            | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
            | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
            | a -> raise_codegen_error $"Type not supported in the codegen.\nGot: %A{a}"
        and tyvs (x : Ty) = env.ty_to_data x |> data_free_vars
        // "" for unit: such functions are procedures.
        and tup_ty x =
            match tyvs x |> Array.map (fun (L(_,t)) -> tyv t) with
            | [||] -> ""
            | [|x|] -> x
            | x -> sprintf "TTuple%i" (tuple_type x)
        and tup d = data_term_vars d |> Array.map show_w |> String.concat ", "
        // A value of type `range`: one term, or a tuple record built with that type's constructor.
        and tup_as (range : Ty) d =
            match data_term_vars d with
            | [||] -> ""
            | [|x|] -> show_w x
            | x -> sprintf "TupleCreate%i(%s)" (tyvs range |> Array.map (fun (L(_,t)) -> tyv t) |> tuple_type) (Array.map show_w x |> String.concat ", ")
        and param_list (x : TyV []) = x |> Array.map (fun (L(i,t)) -> $"v{i}: {tyv t}") |> String.concat "; "
        and header name (parameters : TyV []) (range : string) =
            let ps = match param_list parameters with "" -> "" | ps -> $"({ps})"
            if range = "" then $"procedure {name}{ps}" else $"function {name}{ps}: {range}"
        // A function (or class method) with the locals it declared.
        and emit_function (name : string) (parameters : TyV []) (range : Ty) (body : TypedBind []) (forward : bool) =
            emit_function' None name parameters range body forward
        and emit_function' (self_tag : int option) (name : string) (parameters : TyV []) (range : Ty) (body : TypedBind []) (forward : bool) =
            let range' = tup_ty range
            let locals = new_locals parameters
            let s = {text=StringBuilder(); indent=2}
            let saved = self_loop
            match self_tag with
            | Some tag when self_tail tag body ->
                self_loop <- Some (tag, parameters)
                line s "while True do begin"
                binds locals (indent s) (DTail range) body
                line s "end;"
            | _ ->
                self_loop <- None
                binds locals s (DTail range) body
            self_loop <- saved
            if forward then headers.Add($"{header name parameters range'}; forward;")
            let decls = snd locals
            let var = if decls.Count = 0 then "" else "var\n" + (decls |> Seq.map (sprintf "  %s;") |> String.concat "\n") + "\n"
            bodies.Add($"{header name parameters range'};\n{var}begin\n{text s}end;")
        and declare (names : HashSet<int>, decls : ResizeArray<string>) (L(i,t)) =
            if names.Add i then decls.Add($"v{i}: {tyv t}")
        and temp (_ : HashSet<int>, decls : ResizeArray<string>) (ty : string) =
            let name = $"tmp{decls.Count}"
            decls.Add($"{name}: {ty}")
            name
        and binds locals (s : CodegenEnv) (ret : BindsReturnDelphi) (stmts : TypedBind []) =
            Array.iter (function
                | TyLet(d,trace,a) ->
                    try let d = data_free_vars d
                        d |> Array.iter (declare locals)
                        op locals s (DLocal d) a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) -> try op locals s ret a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) ->
                    try match ret with
                        | DLocal l -> Array.iter2 (fun (L(i,_)) b -> line s $"v{i} := {show_w b};") l (data_term_vars d)
                        | DTail range ->
                            match tup_as range d with "" -> () | x -> line s $"Result := {x};"
                            if self_loop.IsSome then line s "Exit;"
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) stmts
        and op locals (s : CodegenEnv) (ret : BindsReturnDelphi) a =
            let binds = binds locals
            let return' (x : string) =
                match ret with
                | DLocal [||] -> line s $"{x};"
                | DLocal [|L(i,_)|] -> line s $"v{i} := {x};"
                | DLocal l ->
                    let tmp = temp locals (tuple_type (l |> Array.map (fun (L(_,t)) -> tyv t)) |> sprintf "TTuple%i")
                    line s $"{tmp} := {x};"
                    l |> Array.iteri (fun k (L(i,_)) -> line s $"v{i} := {tmp}.f{k};")
                | DTail range ->
                    if tup_ty range = "" then line s $"{x};" else line s $"Result := {x};"
                    if self_loop.IsSome then line s "Exit;"
            let layout_index (i : int) (fields : TyV []) =
                match ret with
                | DLocal l -> Array.iter2 (fun (L(t,_)) (L(f,_)) -> line s $"v{t} := v{i}.l{f};") l fields
                | DTail _ -> raise_codegen_error "Compiler error: Layout index should never come in end position."
            let jp (a, b) =
                let a' = match b with [||] -> "" | b -> $"({args b})"
                match a with
                | JPMethod(a,c) -> $"method{(method (a,c)).tag}{a'}"
                | JPClosure(a,c) -> $"ClosureCreate{(closure (a,c)).tag}{a'}"
            let unary f = function [x] -> f (tup x) | _ -> raise_codegen_error "Compiler error: Expected one argument."
            match a with
            | TyMacro a -> a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup x) | CMType x -> tup_ty x | CMTypeLit x -> type_litDelphi x) |> String.concat "" |> return'
            | TySizeOf t -> return' $"SizeOf({tup_ty t})"
            | TyIf(cond,tr,fl) ->
                line s $"if {tup cond} then begin"
                binds (indent s) ret tr
                line s "end else begin"
                binds (indent s) ret fl
                line s "end;"
            | TyJoinPoint(JPMethod(a,c),args) when (match ret, self_loop with DTail _, Some (tag, _) -> (method (a,c)).tag = tag | _ -> false) ->
                let parameters = snd self_loop.Value
                // Through temporaries: the new arguments may read the parameters being replaced.
                let temps = parameters |> Array.map (fun (L(_,t)) -> temp locals (tyv t))
                Array.iter2 (fun tmp (L(i,_)) -> line s $"{tmp} := v{i};") temps args
                Array.iter2 (fun (L(i,_)) tmp -> line s $"v{i} := {tmp};") parameters temps
                line s "Continue;"
            | TyJoinPoint(a,args) -> return' (jp (a, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The Delphi backend does not support nesting other backends."
            | TyWhile(a,b) ->
                line s $"while {jp a} do begin"
                binds (indent s) (DLocal [||]) b
                line s "end;"
            | TyDo a | TyIndent a -> binds s ret a
            | TyIntSwitch(L(i,_),on_succ,on_fail) ->
                line s $"case v{i} of"
                on_succ |> Array.iteri (fun k b -> line (indent s) $"{k}: begin"; binds (indent (indent s)) ret b; line (indent s) "end;")
                line (indent s) "else begin"; binds (indent (indent s)) ret on_fail; line (indent s) "end;"
                line s "end;"
            | TyUnionUnbox(is,x,on_succs,on_fail) ->
                let x' = x.Item
                let tag = match x'.layout with UHeap -> uheap x'.cases | UStack -> ustack x'.cases
                let case_index k =
                    x'.cases |> Seq.map (fun (KeyValue ((_,k'),_)) -> k') |> Seq.tryFindIndex (fun k' -> UnionTagIdOps.text k = k')
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text k}.")
                let head =
                    match is with
                    | [L(i,_)] -> $"v{i}.tag"
                    | L(i,_) :: _ ->
                        let tmp = temp locals "LongInt"
                        let same = is |> List.pairwise |> List.map (fun (L(a,_), L(b,_)) -> $"(v{a}.tag = v{b}.tag)") |> String.concat " and "
                        line s $"if {same} then {tmp} := v{i}.tag else {tmp} := -1;"
                        tmp
                    | [] -> raise_codegen_error "Compiler error: Union unbox without a scrutinee."
                line s $"case {head} of"
                on_succs |> Map.iter (fun k (a,b) ->
                    let c = case_index k
                    line (indent s) $"{c}: begin // {UnionTagIdOps.text k}"
                    List.iter2 (fun (L(v,_)) a ->
                        data_free_vars a |> Array.iteri (fun f (L(i,_) as field) ->
                            declare locals field
                            line (indent (indent s)) $"v{i} := v{v}.c{c}_{f};")) is a
                    binds (indent (indent s)) ret b
                    line (indent s) "end;")
                on_fail |> Option.iter (fun b -> line (indent s) "else begin"; binds (indent (indent s)) ret b; line (indent s) "end;")
                line s "end;"
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let tag, prefix = match c.layout with UHeap -> uheap c.cases, "UH" | UStack -> ustack c.cases, "US"
                let i =
                    c.cases |> Seq.map (fun (KeyValue ((_,k),_)) -> k) |> Seq.tryFindIndex (fun k -> UnionTagIdOps.text a = k)
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text a}.")
                let vars = match args' b with "" -> "" | x -> $"({x})"
                return' $"{prefix}{tag}_{i}{vars}"
            | TyToLayout(a,b) ->
                let vars = match args' a with "" -> "" | x -> $"({x})"
                match b with
                | YLayout(_,Heap) -> $"HeapCreate{(heap b).tag}{vars}"
                | YLayout(_,HeapMutable) -> $"MutCreate{(mut b).tag}{vars}"
                | YLayout(_,StackMutable) -> raise_codegen_error "The Delphi backend doesn't support stack mutable layout types."
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (4).\nGot: %s{show_ty b}"
                |> return'
            | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                match lay with
                | Heap -> (heap a).free_vars
                | HeapMutable -> (mut a).free_vars
                | StackMutable -> raise_codegen_error "The Delphi backend doesn't support indexing into stack mutable layout types."
                |> layout_index i
            | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The Delphi backend doesn't support indexing into stack mutable layout types."
                |> fun (x : LayoutRecFsharp) -> x.free_vars_by_key |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None) |> Option.iter (layout_index i)
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
            | TyLayoutMutableSet(L(i,t),b,c) ->
                let a = List.fold (fun s k ->
                    match s with
                    | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                    | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t : LayoutRecFsharp).data b
                Array.iter2 (fun (L(i',_)) b -> line s $"v{i}.l{i'} := {show_w b};") (data_free_vars a) (data_term_vars c)
            | TyArrayLiteral(a,b) ->
                let tag = array_type (tup_ty a)
                let tmp = temp locals $"TArray{tag}"
                line s $"SetLength({tmp}, {b.Length});"
                b |> List.iteri (fun k x -> line s $"{tmp}[{k}] := {tup x};")
                return' tmp
            | TyArrayCreate(a,b) ->
                let tag = array_type (tup_ty a)
                let tmp = temp locals $"TArray{tag}"
                line s $"{tmp} := nil;"
                line s $"SetLength({tmp}, {tup b});"
                return' tmp
            | TyArrayLength(a,b) -> return' $"{tyv a}(Length({tup b}))"
            | TyStringLength(a,b) -> return' $"{tyv a}(Length({tup b}))"
            | TyFailwith(a,b) -> line s $"begin WriteLn(StdErr, {tup b}); Halt(1); end;"
            | TyConv(a,b) ->
                match a, prim_of b with
                | YPrim (Float32T | Float64T), _ -> return' (tup b)
                | YPrim t, Some (Float32T | Float64T) -> return' $"{primDelphi t}(Trunc({tup b}))"
                | YPrim t, _ -> return' $"{primDelphi t}({tup b})"
                | _ -> raise_codegen_error $"Compiler error: Unexpected type in Conv. Got: {show_ty a}"
            | TyApply(L(i,_),b) -> return' (match args' b with "" -> $"v{i}.Invoke" | x -> $"v{i}.Invoke({x})")
            | TyOp(Global, [DLit (LitString x)]) -> global' x
            | TyOp(ArrayIndexSet, [a;b;c]) -> line s $"{tup a}[{tup b}] := {tup c};"
            | TyOp(op,l) ->
                let bin f = match l with [a;b] -> f (tup a) (tup b) | _ -> raise_codegen_error "Compiler error: Expected two arguments."
                match op, l with
                | Dyn,[a] -> tup a
                | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                | StringIndex, [a;b] -> $"{tup a}[{tup b} + 1]"
                | StringSlice, [a;b;c] -> string_slice (); $"StringSlice({tup a}, {tup b}, {tup c})"
                | StaticStringConcat, _ -> bin (sprintf "%s + %s")
                | ArrayIndex, [a;b] -> $"{tup a}[{tup b}]"
                | Add, _ -> bin (sprintf "%s + %s")
                | Sub, _ -> bin (sprintf "%s - %s")
                | Mult, _ -> bin (sprintf "%s * %s")
                | Div, [a;_] -> bin (if is_float a then sprintf "%s / %s" else sprintf "%s div %s")
                | Mod, _ -> bin (sprintf "%s mod %s")
                | Pow, _ -> bin (sprintf "Power(%s, %s)")
                | LT, _ -> bin (sprintf "%s < %s")
                | LTE, _ -> bin (sprintf "%s <= %s")
                | EQ, _ -> bin (sprintf "%s = %s")
                | NEQ, _ -> bin (sprintf "%s <> %s")
                | GT, _ -> bin (sprintf "%s > %s")
                | GTE, _ -> bin (sprintf "%s >= %s")
                | (BoolAnd | BitwiseAnd), _ -> bin (sprintf "%s and %s")
                | (BoolOr | BitwiseOr), _ -> bin (sprintf "%s or %s")
                | BitwiseXor, _ -> bin (sprintf "%s xor %s")
                | BitwiseComplement, _ -> unary (sprintf "not %s") l
                | ShiftLeft, _ -> bin (sprintf "%s shl %s")
                | ShiftRight, [a;_] ->
                    match prim_of a with
                    | Some Int8T -> bin (sprintf "SarShortint(%s, %s)")
                    | Some Int16T -> bin (sprintf "SarSmallint(%s, %s)")
                    | Some Int32T -> bin (sprintf "SarLongint(%s, %s)")
                    | Some Int64T -> bin (sprintf "SarInt64(%s, %s)")
                    | _ -> bin (sprintf "%s shr %s")
                | Neg, _ -> unary (sprintf "-%s") l
                | Log, _ -> unary (sprintf "Ln(%s)") l
                | Exp, _ -> unary (sprintf "Exp(%s)") l
                | Tanh, _ -> unary (sprintf "Tanh(%s)") l
                | Sqrt, _ -> unary (sprintf "Sqrt(%s)") l
                | Sin, _ -> unary (sprintf "Sin(%s)") l
                | Cos, _ -> unary (sprintf "Cos(%s)") l
                | NanIs, _ -> unary (sprintf "IsNan(%s)") l
                | StdoutFlush, [] -> "Flush(Output)"
                | MonotonicDelayMs, _ -> unary (sprintf "Sleep(%s)") l
                | Printf, [DLit (LitString "%s"); b] -> $"Write({tup b})"
                | UnionTag, [DV(L(i,YUnion _))] -> $"v{i}.tag"
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported in the Delphi backend" op l.Length
                |> return'
        and tuple_type : string [] -> int = memo (fun tys tag ->
            let fields = tys |> Array.mapi (fun k t -> $"f{k}: {t}")
            let fields = String.concat "; " fields
            types.Add($"  TTuple{tag} = record {fields}; end;")
            let ps = tys |> Array.mapi (fun k t -> $"f{k}: {t}") |> String.concat "; "
            let assigns = tys |> Array.mapi (fun k _ -> $"Result.f{k} := f{k};") |> String.concat " "
            bodies.Add($"function TupleCreate{tag}({ps}): TTuple{tag};\nbegin\n  {assigns}\nend;"))
        and array_type : string -> int = memo (fun el tag -> types.Add($"  TArray{tag} = array of {el};"))
        and fun_type : Ty * Ty -> int = memo (fun (a, b) tag ->
            forwards.Add($"  TFun{tag} = class;")
            let ps = tyvs a |> Array.mapi (fun k (L(_,t)) -> $"a{k}: {tyv t}") |> String.concat "; "
            let ps = if ps = "" then "" else $"({ps})"
            let decl = match tup_ty b with "" -> $"procedure Invoke{ps}; virtual; abstract;" | r -> $"function Invoke{ps}: {r}; virtual; abstract;"
            types.Add($"  TFun{tag} = class\n    {decl}\n  end;"))
        and layout_rec (x : Ty) : LayoutRecFsharp =
            match x with
            | YLayout(x,_) ->
                let x = env.ty_to_data x
                let a, b =
                    match x with
                    | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                    | _ -> data_free_vars x, Map.empty
                {data=x; free_vars=a; free_vars_by_key=b; tag=0}
            | _ -> raise_codegen_error $"Compiler error: Expected a layout type (3).\nGot: %s{show_ty x}"
        and layout (kind : string) (x : Ty) : LayoutRecFsharp =
            match layout_tags.TryGetValue x with
            | true, r -> r
            | _ ->
                let r = { layout_rec x with tag = layout_tags.Count }
                layout_tags.[x] <- r
                let fields = r.free_vars |> Array.map (fun (L(i,t)) -> $"l{i}: {tyv t};") |> String.concat " "
                let ps = r.free_vars |> Array.mapi (fun k (L(_,t)) -> $"a{k}: {tyv t}") |> String.concat "; "
                let ps = if ps = "" then "" else $"({ps})"
                let assigns = r.free_vars |> Array.mapi (fun k (L(i,_)) -> $"Result.l{i} := a{k};") |> String.concat " "
                if kind = "Heap" then
                    types.Add($"  THeap{r.tag} = record {fields} end;")
                    bodies.Add($"function HeapCreate{r.tag}{ps}: THeap{r.tag};\nbegin\n  {assigns}\nend;")
                else
                    forwards.Add($"  TMut{r.tag} = class;")
                    types.Add($"  TMut{r.tag} = class {fields} end;")
                    bodies.Add($"function MutCreate{r.tag}{ps}: TMut{r.tag};\nbegin\n  Result := TMut{r.tag}.Create; {assigns}\nend;")
                r
        and heap x : LayoutRecFsharp = layout "Heap" x
        and mut x : LayoutRecFsharp = layout "Mut" x
        and union_type (heap : bool) = memo_ref (fun (cases : Map<int * string, Ty>) tag ->
            let name = if heap then $"TUH{tag}" else $"TUS{tag}"
            let prefix = if heap then $"UH{tag}" else $"US{tag}"
            let cases = cases |> Map.toArray |> Array.map (fun (_, t) -> env.ty_to_data t |> data_free_vars)
            if heap then forwards.Add($"  {name} = class;")
            let fields = cases |> Array.mapi (fun c vars -> vars |> Array.mapi (fun f (L(_,t)) -> $"c{c}_{f}: {tyv t};")) |> Array.concat |> String.concat " "
            types.Add(if heap then $"  {name} = class tag: LongInt; {fields} end;" else $"  {name} = record tag: LongInt; {fields} end;")
            cases |> Array.iteri (fun c vars ->
                let ps = vars |> Array.mapi (fun f (L(_,t)) -> $"a{f}: {tyv t}") |> String.concat "; "
                let ps = if ps = "" then "" else $"({ps})"
                let create = if heap then $"Result := {name}.Create; " else ""
                let assigns = vars |> Array.mapi (fun f _ -> $"Result.c{c}_{f} := a{f};") |> String.concat " "
                bodies.Add($"function {prefix}_{c}{ps}: {name};\nbegin\n  {create}Result.tag := {c}; {assigns}\nend;")))
        and uheap_memo = lazy (union_type true)
        and ustack_memo = lazy (union_type false)
        and uheap x = uheap_memo.Force() x
        and ustack x = ustack_memo.Force() x
        and method_memo = lazy (memo (fun ((jp_body,key) : _ * _) tag ->
            let args = codegenMethodKeyArgs key
            match codegenMethodBody env "Delphi" jp_body key with
            | body, range, _ -> emit_function' (Some tag) $"method{tag}" (rdata_free_vars args) range body true))
        and method (a, b) : {| tag : int |} = {| tag = method_memo.Force() (a, b) |}
        and closure_memo = lazy (memo (fun ((jp_body,key & (C(args,_,fun_ty))) : _ * _) tag ->
            match fun_ty with
            | YFun(domain,range,_) ->
                match codegenClosureBody env "Delphi" jp_body key with
                | domain_args, body ->
                    let free_vars = rdata_free_vars args
                    let domain_args = data_free_vars domain_args
                    let parent = fun_type (domain, range)
                    let fields = free_vars |> Array.map (fun (L(i,t)) -> $"v{i}: {tyv t};") |> String.concat " "
                    let invoke = header "Invoke" domain_args (tup_ty range)
                    types.Add($"  TClosure{tag} = class(TFun{parent}) {fields} {invoke}; override; end;")
                    // The body refers to its free variables as the object's fields.
                    let saved = bodies.Count
                    emit_function $"TClosure{tag}.Invoke" domain_args range body false
                    let assigns = free_vars |> Array.map (fun (L(i,_)) -> $"c.v{i} := v{i};") |> String.concat " "
                    let ps = match param_list free_vars with "" -> "" | ps -> $"({ps})"
                    bodies.Add($"function ClosureCreate{tag}{ps}: TFun{parent};\nvar c: TClosure{tag};\nbegin\n  c := TClosure{tag}.Create; {assigns}\n  Result := c;\nend;")
                    headers.Add($"function ClosureCreate{tag}{ps}: TFun{parent}; forward;")
            | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."))
        and closure (a, b) : {| tag : int |} = {| tag = closure_memo.Force() (a, b) |}
        and self_tail tag (body : TypedBind []) =
            body.Length > 0 &&
            match Array.last body with
            | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) -> (method (a,c)).tag = tag
            | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> self_tail tag tr || self_tail tag fl
            | TyLocalReturnOp(_, TyUnionUnbox(_,_,on_succs,on_fail), _) -> (on_succs |> Map.exists (fun _ (_,b) -> self_tail tag b)) || (on_fail |> Option.exists (self_tail tag))
            | TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _) -> Array.exists (self_tail tag) on_succ || self_tail tag on_fail
            | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> self_tail tag b
            | _ -> false

        emit_function "SpiralMain" [||] (YPrim Int32T) x false

        let program = StringBuilder()
        program.AppendLine("program SpiralGenerated;").AppendLine("{$mode delphi}{$H+}").AppendLine("{$MAXSTACKSIZE $10000000}").AppendLine("uses SysUtils, Math;") |> ignore
        if forwards.Count > 0 || types.Count > 0 then
            program.AppendLine("type") |> ignore
            forwards |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
            types |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
        env.globals |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        globals |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        headers |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
        bodies |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
        program.AppendLine("begin").AppendLine("  Halt(SpiralMain);").AppendLine("end.").ToString()

    /// ## CodegenGleam

    /// ### backend_nameGleam
    let backend_nameGleam = "Gleam"

    /// ### litGleam
    let litGleam = function
        | LitInt8 x -> sprintf "%i" x
        | LitInt16 x -> sprintf "%i" x
        | LitInt32 x -> sprintf "%i" x
        | LitInt64 x -> sprintf "%i" x
        | LitUInt8 x -> sprintf "%i" x
        | LitUInt16 x -> sprintf "%i" x
        | LitUInt32 x -> sprintf "%i" x
        | LitUInt64 x -> sprintf "%i" x
        | LitFloat32 x ->
            if x = infinityf then "infinityf"
            elif x = -infinityf then "-infinityf"
            elif Single.IsNaN x then "nanf"
            else x.ToString("R") |> add_dec_point |> sprintf "%s"
        | LitFloat64 x ->
            if x = infinity then "infinity"
            elif x = -infinity then "-infinity"
            elif Double.IsNaN x then "nan"
            else x.ToString("R") |> add_dec_point
        | LitString x ->
            let strb = StringBuilder(x.Length+2)
            strb.Append '"' |> ignore
            String.iter (function
                | '"' -> strb.Append "\\\""
                | '\b' -> strb.Append @"\b"
                | '\t' -> strb.Append @"\t"
                | '\n' -> strb.Append @"\n"
                | '\r' -> strb.Append @"\r"
                | '\\' -> strb.Append @"\\"
                | x -> strb.Append x
                >> ignore
                ) x
            strb.Append '"' |> ignore
            strb.ToString()
        | LitChar x ->
            match x with
            | '\b' -> @"\b"
            | '\n' -> @"\n"
            | '\t' -> @"\t"
            | '\r' -> @"\r"
            | '\\' -> @"\\"
            | '"' -> "\\\""
            | x -> string x
            |> sprintf "\"%s\""
        | LitBool x -> if x then "True" else "False"

    /// ### primGleam
    let primGleam = function
        | Int8T -> "Int"
        | Int16T -> "Int"
        | Int32T -> "Int"
        | Int64T -> "Int"
        | UInt8T -> "Int"
        | UInt16T -> "Int"
        | UInt32T -> "Int"
        | UInt64T -> "Int"
        | Float32T -> "Float"
        | Float64T -> "Float"
        | BoolT -> "Bool"
        | StringT -> "String"
        | CharT -> "String"

    /// ### type_litGleam
    let type_litGleam = function
        | YLit x -> litGleam x
        | YSymbol x -> x
        | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

    /// ### UnionRecGleam
    type UnionRecGleam = {tag : int; free_vars : Map<int * string, TyV[]>}

    /// ### LayoutRecGleam
    type LayoutRecGleam = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>}

    /// ### MethodRecGleam
    type MethodRecGleam = {tag : int; free_vars : L<Tag,Ty>[]; range : Ty; body : TypedBind[]}

    /// ### ClosureRecGleam
    type ClosureRecGleam = {tag : int; free_vars : L<Tag,Ty>[]; domain_args : TyV[]; range : Ty; body : TypedBind[]}

    /// ### codegenGleam
    let codegenGleam (env : PartEvalResult) (x : TypedBind []) =
        let types = ResizeArray()
        let functions = ResizeArray()

        let print is_type show r =
            let s = {text=StringBuilder(); indent=0}
            show s r
            let text = s.text.ToString()
            if is_type then types.Add(text) else functions.Add(text)

        let layout show =
            let dict' = codegenMemoTable HashIdentity.Structural
            let dict = codegenMemoTable HashIdentity.Reference
            let f x : LayoutRecGleam =
                match x with
                | YLayout(x,_) ->
                let x = env.ty_to_data x
                let a, b =
                    match x with
                    | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                    | _ -> data_free_vars x, Map.empty
                {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (3).\nGot: %s{show_ty x}"
            fun x ->
                let mutable dirty = false
                let r = memoize dict (memoize dict' (fun x -> dirty <- true; f x)) x
                if dirty then print true show r
                r

        let union show =
            let dict = codegenMemoTable HashIdentity.Reference
            let f (a : Map<int * string,Ty>) : UnionRecGleam = {free_vars=a |> Map.map (fun _ -> env.ty_to_data >> data_free_vars); tag=dict.Count}
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print true show r
                r

        let jp f show =
            let dict = codegenMemoTable HashIdentity.Structural
            let f x = f (x, dict.Count)
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print false show r
                r

        let args x = x |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "
        let show_w = function WV (L(i,_)) -> sprintf "v%i" i | WLit a -> litGleam a
        let args' x = x |> data_term_vars |> Array.map show_w |> String.concat ", "

        let global' =
            let has_added = HashSet env.globals
            let preserves_duplicate_fragment (x : string) =
                System.String.IsNullOrEmpty x
                || System.Char.IsWhiteSpace x.[0]
                || x.[0] = '}'
            fun x -> if preserves_duplicate_fragment x || has_added.Add(x) then env.globals.Add x

        let mutable while_id = 0

        let rec tyv x =
            match x with
            | YUnion a ->
                let a = a.Item
                match a.layout with
                | UHeap -> sprintf "Uh%i" (uheap a.cases).tag
                | UStack -> sprintf "Us%i" (ustack a.cases).tag
            | YLayout(_,lay) as a ->
                match lay with
                | Heap -> sprintf "Heap%i" (heap a).tag
                | HeapMutable -> sprintf "Mut%i" (mut a).tag
                | StackMutable -> raise_codegen_error "Compiler error: The F# backend doesn't support stack mutable layout types."
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameGleam then Some v else None) with
                | Some x -> tup_ty x
                | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_nameGleam}' field."
            | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_litGleam a) |> String.concat ""
            | YPrim a -> primGleam a
            | YArray a ->
                global' "import gary"
                global' "import gary/array"
                sprintf "gary.ErlangArray(%s)" (tup_ty a)
            | YFun(a,b,FT_Vanilla) -> sprintf "fn(%s) -> %s" (tup_ty a) (tup_ty b)
            | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
            | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
            | a -> raise_codegen_error $"Type not supported in the codegen.\nGot: %A{a}"
        and args_tys x = x |> Array.map (fun (L(i,t)) -> sprintf "v%i :    %s" i (tup_ty t)) |> String.concat ", "
        and binds (s : CodegenEnv) (x : TypedBind []) =
            Array.iter (function
                | TyLet(d,trace,a) -> try op s (Some d) a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) -> try op s None a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) -> try line s (tup d) with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) x
        and tup x =
            match data_term_vars x with
            | [||] -> "Nil      "
            | [|x|] -> show_w x
            | x -> $"""#({x |> Array.map show_w |> String.concat ", "})      """
        and tup_ty x =
            match env.ty_to_data x |> data_free_vars |> Array.map (fun (L(_,x)) -> tyv x) with
            | [||] -> "Nil       "
            | [|x|] -> x
            | x -> String.concat ", " x |> sprintf "#(%s)       "
        and op s d a =
            let a'' = a
            let jp (a, b) =
                let a' = a
                let b' = b
                let args = args b
                match a with
                | JPMethod(a,b) -> sprintf "method%i(%s)" (method (a,b)).tag args
                | JPClosure (a, b) ->
                    let tag = (closure (a, b)).tag
                    let fv =
                        match args with
                        | "" -> "Nil"
                        | xs -> sprintf "#(%s)" xs
                    let code = sprintf "closure%i(%s)" tag fv
                    let comment =
                        $"// args: %A{args} / d: %A{d} / b': %A{b} / b: %A{b}"
                        |> SpiralSm.replace "\r\n" ""
                        |> SpiralSm.replace "\n" ""
                        |> fun c -> $"{c |> SpiralSm.ellipsis 1000}\n"
                    code + " " + comment
            let free_vars do_annot x =
                let f (L(i,t)) = if do_annot then sprintf "v%i :  %s" i (tyv t) else sprintf "v%i" i
                match data_free_vars x with
                | [||] -> "Nil         "
                | [|x|] -> f x
                | x -> Array.map f x |> String.concat ", " |> sprintf "#(%s)         "
            let simple x =
                match d with
                | None -> x
                | Some d ->
                    match free_vars false d |> SpiralSm.trim with
                    | "Nil" -> x
                    | d -> sprintf "let %s = %s" d x
                |> line s
            let complex f =
                match d with
                | None -> f s : unit
                | Some d ->
                    match free_vars false d |> SpiralSm.trim with
                    | "Nil" -> f s
                    | d ->
                        line s (sprintf "let %s =" d)
                        f (indent s)
            let layout_vars a =
                let f i x =
                    match x with
                    | WV(L(i',_)) -> sprintf "l%i :  v%i" i i'
                    | WLit x -> sprintf "l%i :  %s" i (litGleam x)
                a |> data_term_vars |> Array.mapi f |> String.concat ", "
            let layout_index i x =
                x |> Array.map (fun (L(i',_)) -> sprintf "v%i.l%i " i i')
                |> String.concat ", "
                |> function "" -> () | x -> simple x
            let length (a,b) =
                global' "import gleam/string"
                sprintf "string.length(%s)" (tup b)
                |> simple
            let listToArray panic x =
                global' "import gary/array"
                global' "import gleam/option"
                global' "import gleam/list"
                $"{x} " +
                $"|> list.map(option.Some) " +
                $"|> array.from_list(option.None) " +
                $"|> array.map(fn(_, x) {{ " +
                $"     case x {{ " +
                $"       option.Some(x) -> x " +
                $"       _ -> panic as \"{panic}\" " +
                $"     }} " +
                $"   }}) "
            match a with
            | TyMacro a -> a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup x) | CMType x -> tup_ty x | CMTypeLit x -> type_litGleam x) |> String.concat "" |> simple
            | TySizeOf t -> simple $"0"
            | TyIf(cond,tr,fl) ->
                complex <| fun s ->
                // line s (sprintf "if %s then" (tup cond))
                line s (sprintf "case %s {" (tup cond))
                line (indent s) "True -> {"
                binds (indent (indent s)) tr
                line (indent s) "}"
                line (indent s) "False -> {"
                match fl with
                | [|TyLocalReturnData(DB,_)|] ->
                    line (indent s) "Nil"
                | _ ->
                    binds (indent (indent s)) fl
                line (indent s) "}"
                line s "}"
            | TyJoinPoint(a,args) -> simple (jp (a, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The Gleam backend does not support nesting other backends."
            | TyWhile(a, b) ->
                let id = while_id
                while_id <- while_id + 1

                print
                    false
                    (fun s id' ->
                        line s (sprintf "loop%i (v0, v1) {" id')
                        line (indent s) (sprintf "case %s {" (jp a))
                        line (indent (indent s)) "True -> {"
                        binds (indent (indent (indent s))) b
                        global' "import gleam/io"
                        line (indent (indent (indent s))) (sprintf "|> fn(_) { io.debug(\"spiral_compiler.TyWhile\") } loop%i(v0, v1)" id')
                        line (indent (indent s)) "}"
                        line (indent (indent s)) "False -> {"
                        line (indent (indent (indent s))) "v0"
                        line (indent (indent s)) "}"
                        line (indent s) "}"
                        line s "}"
                    )
                    id

                simple (sprintf "let v0 = loop%i(v0, v1)" id)

            | TyDo a ->
                complex <| fun s ->
                line s "{"
                binds (indent s) a
                line s "}"
            | TyIndent a ->
                complex <| fun s ->
                binds (indent s) a
            | TyIntSwitch(L(i,_),on_succ,on_fail) ->
                complex <| fun s ->
                line s (sprintf "case v%i   {" i)
                Array.iteri (fun i x ->
                    line (indent s) (sprintf "%i ->   {" i)
                    binds (indent (indent s)) x
                    line (indent s) "}   "
                    ) on_succ
                line (indent s) "_ -> {"
                binds (indent (indent s)) on_fail
                line (indent s) "}"
            | TyUnionUnbox(is,x,on_succs,on_fail) ->
                complex <| fun s ->
                let case_tags = x.Item.tags
                line s ($"""case {is |> List.map (fun (L(i,_)) -> $"v{i}  ") |> String.concat ",  "}  {{""")
                let prefix =
                    let x = x.Item
                    match x.layout with
                    | UHeap -> sprintf "Uh%i" (uheap x.cases).tag
                    | UStack -> sprintf "Us%i" (ustack x.cases).tag
                Map.iter (fun k (a,b) ->
                    let i = case_tags.[k]
                    let cases =
                        a |> List.map (fun a ->
                            match data_free_vars a with
                            | [||] -> ""
                            | x -> sprintf "(%s)" (args x)
                            |> sprintf "%si%i%s" prefix i
                            )
                        |> String.concat ",  "
                    line (indent s) (sprintf "%s ->  { // %s" cases (UnionTagIdOps.text k))
                    binds (indent (indent s)) b
                    line (indent s) "}  "
                    ) on_succs
                match on_fail with
                | Some on_fail -> on_fail |> Some
                | None ->
                    if on_succs |> Map.count = 1
                    then on_succs |> Map.values |> Seq.tryHead |> Option.map snd
                    else None
                |> Option.iter (fun b ->
                    line (indent s) "_ -> {"
                    binds (indent (indent s)) b
                    line (indent s) "}"
                )
                line s "}"
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let i = c.tags.[a]
                let vars =
                    match data_term_vars b with
                    | [||] -> ""
                    | x -> Array.map show_w x |> String.concat ", " |> sprintf "(%s)"
                match c.layout with
                | UHeap -> sprintf "Uh%ii%i%s" (uheap c.cases).tag i vars
                | UStack -> sprintf "Us%ii%i%s" (ustack c.cases).tag i vars
                |> simple
            | TyToLayout(a,b) ->
                let a = layout_vars a
                match b with
                | YLayout(_,layout) ->
                    match layout with
                    | Heap -> if a = "" then sprintf "Heap%i()" (heap b).tag else sprintf "Heap%i(%s)" (heap b).tag a
                    | HeapMutable -> if a = "" then sprintf "Mut%i()" (mut b).tag else sprintf "Mut%i(%s)" (mut b).tag a
                    | StackMutable -> raise_codegen_error "The F# backend doesn't support stack mutable layout types."
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (4).\nGot: %s{show_ty b}"
                |> simple
            | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The Gleam backend doesn't support indexing into stack mutable layout types."
                |> fun x -> x.free_vars |> layout_index i
            | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The Gleam backend doesn't support indexing into stack mutable layout types."
                |> fun x ->
                    x.free_vars_by_key
                    |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)
                    |> Option.iter (layout_index i)
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
            | TyLayoutMutableSet(L(i,t),b,c) ->
                let a = List.fold (fun s k ->
                    match s with
                    | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                    | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t).data b
                let a_vars = data_free_vars a
                Array.iter2 (fun (L(i',_)) b ->
                    if a_vars |> Array.length > 1
                    then line s (sprintf "let v%i = %s(..v%i, l%i: %s)" i (tup_ty t) i i' (show_w b))
                    else line s (sprintf "let v%i = %s(l%i: %s)" i (tup_ty t) i' (show_w b))
                    ) a_vars (data_term_vars c)
            | TyArrayLiteral(a,b) ->
                $"""[ {List.map tup b |> String.concat ", "} ]"""
                |> listToArray "spiral_compiler..TyArrayLiteral"
                |> simple
            | TyArrayCreate(a,b) -> $"[]" |> listToArray "spiral_compiler..TyArrayCreate" |> simple
            | TyArrayLength(a,b) ->
                global' "import gary/array"
                sprintf "array.get_size(%s)" (tup b)
                |> simple
            | TyStringLength(a,b) -> length (a,b)
            | TyFailwith(a,b) -> simple (sprintf "panic as %s" (tup b))
            | TyConv(a,b) ->
                let t = tyv a |> SpiralSm.to_lower
                let d = tup b
                if t = "int" then
                    global' $"import gleam/float"
                    $"float.truncate({d})"
                elif t = "float" then
                    global' $"import gleam/int"
                    $"int.to_float({d})"
                elif t = "bool" then
                    $"{d} > 0"
                else
                    $"{d} // spiral_compiler.TyConv / t: {t}"
                |> simple
            | TyApply (L(i, t), b) ->
                let arg_code = tup b
                let call =
                  match t with
                  | YFun (domain, _, FT_Vanilla) ->
                      let domain_is_nil =
                        env.ty_to_data domain |> data_free_vars |> Array.isEmpty
                      if arg_code |> SpiralSm.trim = "Nil" then
                        if domain_is_nil then sprintf "v%i( Nil      )" i else sprintf "v%i " i
                      else
                        if domain_is_nil then $"v%i{i}( {arg_code}(      Nil)  ) "
                        else sprintf "v%i( %s  )" i arg_code
                  | _ ->
                      sprintf "v%i( %s  )" i arg_code
                call
                |> fun code ->
                    let comment =
                        $"// tup_ty t: {tup_ty t} / b: %A{b} / d: %A{d} / a'': %A{a''}"
                        |> SpiralSm.replace "\r\n" ""
                        |> SpiralSm.replace "\n" ""
                        |> fun c -> $"{c |> SpiralSm.ellipsis 1000}\n"
                    $"{call} {comment}"
                |> simple
            | TyOp(Global, [DLit (LitString x)]) -> global' x
            | TyOp(op,l) ->
                let dot = function
                    | DV(L(_,YPrim Float32T)) | DLit(LitFloat32 _)
                    | DV(L(_,YPrim Float64T)) | DLit(LitFloat64 _) -> "."
                    | _ -> ""
                match op, l with
                | Dyn,[a] -> tup a
                | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                | StringIndex, [a;b] ->
                    global' "import gleam/string"
                    sprintf "%s |> string.slice(%s, 1)" (tup a) (tup b)
                | StringSlice, [a;b;c] ->
                    global' "import gleam/string"
                    sprintf "%s |> string.slice(%s, %s - %s + 1)" (tup a) (tup b) (tup c) (tup b)
                | ArrayIndex, [a;b] ->
                    global' "import gary/array"
                    $"{tup a} " +
                    $"|> array.get({tup b}) " +
                    $"|> fn(x) -> _ {{ " +
                    $"     case x {{ " +
                    $"       Ok(x) -> x " +
                    $"       Error(_) -> panic as \"spiral_compiler..ArrayIndex / i: {tup b}\" " +
                    $"     }} " +
                    $"   }} "
                | ArrayIndexSet, [a;b;c] ->
                    global' "import gary/array"
                    global' "import gleam/result"
                    $"let {tup a} = {tup a} |> array.set({tup b}, {tup c}) |> result.unwrap({tup a})"

                // Math
                | Add, [a;b] -> $"{a |> tup} +{a |> dot} {b |> tup}"
                | Sub, [a;b] -> $"{a |> tup} -{a |> dot} {b |> tup}"
                | Mult, [a;b] -> $"{a |> tup} *{a |> dot} {b |> tup}"
                | Div, [a;b] -> $"{a |> tup} /{a |> dot} {b |> tup}"
                | Mod, [a;b] -> $"{a |> tup} %%{a |> dot} {b |> tup}"
                | Pow, [a;b] -> $"{a |> tup} **{a |> dot} {b |> tup}"
                | LT, [a;b] -> sprintf "%s < %s" (tup a) (tup b)
                | LTE, [a;b] -> sprintf "%s <= %s" (tup a) (tup b)
                | EQ, [a;b] -> sprintf "%s == %s" (tup a) (tup b)
                | NEQ, [a;b] -> sprintf "%s != %s" (tup a) (tup b)
                | GT, [a;b] -> sprintf "%s > %s" (tup a) (tup b)
                | GTE, [a;b] -> sprintf "%s >= %s" (tup a) (tup b)
                | BoolAnd, [a;b] -> sprintf "%s && %s" (tup a) (tup b)
                | BoolOr, [a;b] -> sprintf "%s || %s" (tup a) (tup b)
                | BitwiseAnd, [a;b] -> sprintf "%s &&& %s" (tup a) (tup b)
                | BitwiseOr, [a;b] -> sprintf "%s ||| %s" (tup a) (tup b)
                | BitwiseXor, [a;b] -> sprintf "%s ^^^ %s" (tup a) (tup b)
                | BitwiseComplement, [a] -> sprintf "~~~%s" (tup a)

                | ShiftLeft, [a;b] -> sprintf "%s <<< %s" (tup a) (tup b)
                | ShiftRight, [a;b] -> sprintf "%s >>> %s" (tup a) (tup b)

                | Neg, [x] -> sprintf " -%s" (tup x)
                | Log, [x] -> sprintf "log %s" (tup x)
                | Exp, [x] -> sprintf "exp %s" (tup x)
                | Tanh, [x] -> sprintf "tanh %s" (tup x)
                | Sqrt, [x] -> sprintf "sqrt %s" (tup x)
                | Sin, [x] -> sprintf "sin %s" (tup x)
                | Cos, [x] -> sprintf "cos %s" (tup x)
                | NanIs, [x] ->
                    match x with
                    | DLit(LitFloat32 _) | DV(L(_,YPrim Float32T)) -> sprintf "Single.IsNaN(%s)" (tup x)
                    | DLit(LitFloat64 _) | DV(L(_,YPrim Float64T)) -> sprintf "Double.IsNaN(%s)" (tup x)
                    | _ -> raise_codegen_error "Compiler error: Invalid type in NanIs."
                | UnionTag, [DV(L(i,YUnion h))] ->
                    let h = h.Item
                    let ty =
                        match h.layout with
                        | UHeap -> sprintf "Uh%i" (uheap h.cases).tag
                        | UStack -> sprintf "Us%i" (ustack h.cases).tag
                    let items =
                        h.cases
                        |> Seq.map (fun (KeyValue ((i, _), _)) ->
                            $"#({ty}i{i}, {i})          "
                        )
                        |> String.concat ", "
                    global' "import gleam/dict"
                    global' "import gleam/result"
                    $"[ {items} ] |> dict.from_list |> dict.get(v{i}) |> result.unwrap(0)"
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported" op l.Length
                |> simple
        and heap : _ -> LayoutRecGleam = layout (fun s x ->
            let b = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "l%i : %s" i (tyv t)) |> String.concat ", "
            if b = "" then line s (sprintf "Heap%i { Heap%i() }" x.tag x.tag)
            else line s (sprintf "Heap%i { Heap%i(%s) }" x.tag x.tag b)
            )
        and mut : _ -> LayoutRecGleam = layout (fun s x ->
            let b = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "l%i : %s" i (tyv t)) |> String.concat ", "
            if b = "" then line s (sprintf "Mut%i { Mut%i() }" x.tag x.tag)
            else line s (sprintf "Mut%i { Mut%i(%s) }" x.tag x.tag b)
            )
        and uheap : _ -> UnionRecGleam = union (fun s x ->
            line s (sprintf "Uh%i {" x.tag)
            let mutable i = 0
            x.free_vars |> Map.iter (fun _ a ->
                match a with
                | [||] -> line (indent s) (sprintf "Uh%ii%i" x.tag i)
                | a -> line (indent s) (sprintf "Uh%ii%i(%s)" x.tag i (a |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat ", "))
                i <- i+1
                )
            line s "}"
            )
        and ustack : _ -> UnionRecGleam = union (fun s x ->
            line s (sprintf "Us%i {" x.tag)
            let mutable i = 0
            x.free_vars |> Map.iter (fun _ a ->
                match a with
                | [||] -> line (indent s) (sprintf "Us%ii%i" x.tag i)
                | a -> line (indent s) (sprintf "Us%ii%i(%s)" x.tag i (a |> Array.mapi (fun i' (L(_,t)) -> sprintf "f%ii%i : %s" i i' (tyv t)) |> String.concat ", "))
                i <- i+1
                )
            line s "}"
            )
        and method : _ -> MethodRecGleam =
            jp (fun ((jp_body,key),i) ->
                let args = codegenMethodKeyArgs key
                match codegenMethodBody env "Gleam" jp_body key with
                | a, range, _ -> {tag=i; free_vars=rdata_free_vars args; range=range; body=a}
                ) (fun s x ->
                let range_ty = tup_ty x.range
                let is_fn = range_ty |> SpiralSm.starts_with "fn(Nil  ) -> "
                let ret =
                    if is_fn
                    then $"{range_ty} {{ fn(_)"
                    else range_ty
                line s $"method{x.tag} ({args_tys x.free_vars}) -> {ret} {{"
                binds (indent s) x.body
                if is_fn
                then line s "(    Nil  )}}"
                else line s "}"
                )
        and closure : _ -> ClosureRecGleam =
            jp
                (fun ((jp_body, key & (C(args, _, fun_ty))), i) ->
                match fun_ty with
                | YFun (domain, range, FT_Vanilla) ->
                    match codegenClosureBody env "Gleam" jp_body key with
                    | domain_args, body ->
                        {   tag = i
                            free_vars = rdata_free_vars args
                            domain_args = data_free_vars domain_args
                            range = range
                            body = body }
                | YFun (_, _, _) ->
                    raise_codegen_error "Non-standard functions are not supported in the Gleam backend."
                | _ ->
                    raise_codegen_error "Compiler error: Unexpected type in the closure join point.")
                (fun s x ->
                let fv_tys =
                    x.free_vars
                    |> Array.map (fun (L(_, t)) -> tyv t)

                let dom_ty =
                    match x.domain_args with
                    | [||] -> "Nil"
                    | [| L(_, t) |] -> tyv t
                    | many ->
                        many
                        |> Array.map (fun (L(_, t)) -> tyv t)
                        |> String.concat ", "
                        |> sprintf "#(%s)"

                let capt_ty =
                    fv_tys
                    |> function
                    | [||] -> "Nil"
                    | [|one|] -> sprintf "#(%s)" one
                    | many -> many |> String.concat ", " |> sprintf "#(%s)"

                let fv_bind =
                    match x.free_vars with
                    | [||] -> None
                    | arr ->
                        let names =
                            arr
                            |> Array.mapi (fun idx (L(i,_)) -> sprintf "v%i" i)
                            |> String.concat ", "
                        Some (sprintf "let #(%s) = capt" names)

                let dom_name =
                    match x.domain_args with
                    | [| L(i, _) |] -> sprintf "v%i" i
                    | _ -> "dom"

                line s (sprintf "closure%i (capt : %s) -> fn(%s) -> %s {" x.tag capt_ty dom_ty (tup_ty x.range))
                line (indent s) (sprintf "fn (%s) {" dom_name)

                match x.domain_args with
                | [||] -> ()
                | [| L(_, _) |] -> ()
                | many ->
                    let names =
                        many
                        |> Array.mapi (fun idx (L(i, _)) -> sprintf "v%i" i)
                        |> String.concat ", "
                    line (indent (indent s)) (sprintf "let #(%s) = dom" names)

                fv_bind |> Option.iter (line (indent (indent s)))

                binds (indent (indent s)) x.body

                line (indent s) "}"
                line s "}"
            )

        let main = StringBuilder()
        binds {text=main; indent=0} x

        let program = StringBuilder()
        env.globals |> Seq.distinct |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        types |> Seq.iteri (fun i x -> program.Append("pub type ").Append(x) |> ignore)
        functions |> Seq.iteri (fun i x -> program.Append("pub fn ").Append(x) |> ignore)
        program.Append($"pub fn main () {{ {main} }}").ToString()

    /// ## CodegenLua

    /// ### backend_nameLua
    let backend_nameLua = "Lua"

    /// ### litLua
    let litLua = function
        | LitInt8 x -> sprintf "%i" x
        | LitInt16 x -> sprintf "%i" x
        | LitInt32 x -> sprintf "%i" x
        | LitInt64 x -> sprintf "%i" x
        | LitUInt8 x -> sprintf "%i" x
        | LitUInt16 x -> sprintf "%i" x
        | LitUInt32 x -> sprintf "%i" x
        | LitUInt64 x -> sprintf "%i" x
        | LitFloat32 x ->
            if x = infinityf then "infinityf"
            elif x = -infinityf then "-infinityf"
            elif Single.IsNaN x then "nanf"
            else x.ToString("R") |> add_dec_point |> sprintf "%s"
        | LitFloat64 x ->
            if x = infinity then "infinity"
            elif x = -infinity then "-infinity"
            elif Double.IsNaN x then "nan"
            else x.ToString("R") |> add_dec_point
        | LitString x ->
            let strb = StringBuilder(x.Length+2)
            strb.Append '"' |> ignore
            String.iter (function
                | '"' -> strb.Append "\\\""
                | '\b' -> strb.Append @"\b"
                | '\t' -> strb.Append @"\t"
                | '\n' -> strb.Append @"\n"
                | '\r' -> strb.Append @"\r"
                | '\\' -> strb.Append @"\\"
                | x -> strb.Append x
                >> ignore
                ) x
            strb.Append '"' |> ignore
            strb.ToString()
        | LitChar x ->
            match x with
            | '\b' -> @"\b"
            | '\n' -> @"\n"
            | '\t' -> @"\t"
            | '\r' -> @"\r"
            | '\\' -> @"\\"
            | '"' -> "\\\""
            | x -> string x
            |> sprintf "\"%s\""
        | LitBool x -> if x then "true" else "false"

    /// ### primLua
    let primLua = function
        | Int8T -> "Int"
        | Int16T -> "Int"
        | Int32T -> "Int"
        | Int64T -> "Int"
        | UInt8T -> "Int"
        | UInt16T -> "Int"
        | UInt32T -> "Int"
        | UInt64T -> "Int"
        | Float32T -> "Float"
        | Float64T -> "Float"
        | BoolT -> "Bool"
        | StringT -> "String"
        | CharT -> "String"

    /// ### type_litLua
    let type_litLua = function
        | YLit x -> litLua x
        | YSymbol x -> x
        | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

    /// ### UnionRecLua
    type UnionRecLua = {tag : int; free_vars : Map<int * string, TyV[]>}

    /// ### LayoutRecLua
    type LayoutRecLua = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>}

    /// ### MethodRecLua
    type MethodRecLua = {tag : int; free_vars : L<Tag,Ty>[]; range : Ty; body : TypedBind[]}

    /// ### ClosureRecLua
    type ClosureRecLua = {tag : int; free_vars : L<Tag,Ty>[]; domain_args : TyV[]; range : Ty; body : TypedBind[]}

    /// ### codegenLua
    let codegenLua (env : PartEvalResult) (x : TypedBind []) =
        let targetLua54 = false

        let types = ResizeArray()
        let functions = ResizeArray()

        let print is_type show r =
            let s = {text=StringBuilder(); indent=0}
            show s r
            let text = s.text.ToString()
            if is_type then types.Add(text) else functions.Add(text)

        let layout show =
            let dict' = codegenMemoTable HashIdentity.Structural
            let dict = codegenMemoTable HashIdentity.Reference
            let f x : LayoutRecLua =
                match x with
                | YLayout(x,_) ->
                let x = env.ty_to_data x
                let a, b =
                    match x with
                    | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                    | _ -> data_free_vars x, Map.empty
                {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (3).\nGot: %s{show_ty x}"
            fun x ->
                let mutable dirty = false
                let r = memoize dict (memoize dict' (fun x -> dirty <- true; f x)) x
                if dirty then print true show r
                r

        let union show =
            let dict = codegenMemoTable HashIdentity.Reference
            let f (a : Map<int * string,Ty>) : UnionRecLua = {free_vars=a |> Map.map (fun _ -> env.ty_to_data >> data_free_vars); tag=dict.Count}
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print true show r
                r

        let jp f show =
            let dict = codegenMemoTable HashIdentity.Structural
            let f x = f (x, dict.Count)
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print false show r
                r

        let args x = x |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "
        let show_w = function WV (L(i,_)) -> sprintf "v%i" i | WLit a -> litLua a
        let args' x = x |> data_term_vars |> Array.map show_w |> String.concat ", "

        let global' =
            let has_added = HashSet env.globals
            let preserves_duplicate_fragment (x : string) =
                System.String.IsNullOrEmpty x
                || System.Char.IsWhiteSpace x.[0]
                || x.[0] = '}'
            fun x -> if preserves_duplicate_fragment x || has_added.Add(x) then env.globals.Add x

        let mutable while_id = 0

        let rec tyv x =
            match x with
            | YUnion a ->
                let a = a.Item
                match a.layout with
                | UHeap -> sprintf "Uh%i" (uheap a.cases).tag
                | UStack -> sprintf "Us%i" (ustack a.cases).tag
            | YLayout(_,lay) as a ->
                match lay with
                | Heap -> sprintf "Heap%i" (heap a).tag
                | HeapMutable -> sprintf "Mut%i" (mut a).tag
                | StackMutable -> raise_codegen_error "Compiler error: The F# backend doesn't support stack mutable layout types."
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameLua then Some v else None) with
                | Some x -> tup_ty x
                | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_nameLua}' field."
            | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_litLua a) |> String.concat ""
            | YPrim a -> primLua a
            | YArray a -> "table"
            | YFun(a,b,FT_Vanilla) -> sprintf "function(%s) -> %s end" (tup_ty a) (tup_ty b)
            | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
            | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
            | a -> raise_codegen_error $"Type not supported in the codegen.\nGot: %A{a}"
        and args_tys x = x |> Array.map (fun (L(i,t)) -> sprintf "v%i" i) |> String.concat ", "
        and binds (s : CodegenEnv) (x : TypedBind []) =
            Array.iter (function
                | TyLet(d,trace,a) -> try op s (Some d) a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) -> try op s None a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) -> try line s $"return {tup d}          " with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) x
        and tup x =
            match data_term_vars x with
            | [||] -> "nil      "
            | [|x|] -> show_w x
            | x ->
                x
                |> Array.mapi (fun i v -> sprintf "[%i]=%s" (i+1) (show_w v))
                |> String.concat ", "
                |> sprintf "{ %s }"
        and tup_ty x =
            match env.ty_to_data x |> data_free_vars |> Array.map (fun (L(_,x)) -> tyv x) with
            | [||] -> "nil       "
            | [|x|] -> x
            | x -> String.concat ", " x |> sprintf "#(%s)       "
        and op s d a =
            let a'' = a
            let jp (a, b) =
                let a' = a
                let b' = b
                let args = args b
                match a with
                | JPMethod(a,b) -> sprintf "method%i(%s)" (method (a,b)).tag args
                | JPClosure (a, b) ->
                    let tag = (closure (a, b)).tag
                    let fv =
                        match args with
                        | "" -> "nil"
                        | xs -> sprintf "{ %s }" xs
                    sprintf "closure%i(%s)" tag fv
            let free_vars do_annot x =
                let f (L(i,t)) = if do_annot then sprintf "v%i" i else sprintf "v%i" i
                match data_free_vars x with
                | [||] -> "nil         "
                | [|x|] -> f x
                | x -> Array.map f x |> String.concat ", " |> sprintf "%s                  "
            let simple x =
                match d with
                | None -> $"return {x}           "
                | Some d ->
                    match data_free_vars d with
                    | [||] -> $"{x}            "
                    | [|_|] ->
                        let names = free_vars false d |> SpiralSm.trim
                        sprintf "local %s = %s" names x
                    | _ ->
                        let names = free_vars false d |> SpiralSm.trim
                        sprintf "local %s = (table.unpack or unpack)(%s)" names x
                |> line s
            let complex f =
                match d with
                | None -> f s : unit
                | Some d ->
                    match free_vars false d |> SpiralSm.trim with
                    | "nil" -> f s
                    | d ->
                        line s $"local get{d} = function()"
                        f (indent s)
                        line s $"end"
                        line s $"local {d} = get{d}()"
            let layout_vars a =
                let f i x =
                    match x with
                    | WV(L(i',_)) -> sprintf "l%i = v%i" i i'
                    | WLit x -> sprintf "l%i = %s" i (litLua x)
                a |> data_term_vars |> Array.mapi f |> String.concat ", "
            let layout_index i x =
                x |> Array.map (fun (L(i',_)) -> $"v{i} ~= nil and v{i}.l{i'}")
                |> String.concat ", "
                |> function "" -> () | x -> simple x
            let length (a,b) =
                sprintf "string.len(%s)" (tup b)
                |> simple
            let listToArray _ x = x
            match a with
            | TyMacro a -> a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup x) | CMType x -> tup_ty x | CMTypeLit x -> type_litLua x) |> String.concat "" |> simple
            | TySizeOf t -> simple $"0"
            | TyIf(cond,tr,fl) ->
                complex <| fun s ->
                line s (sprintf "if %s then" (tup cond))
                binds (indent s) tr
                line s "else"
                match fl with
                | [|TyLocalReturnData(DB,_)|] ->
                    line (indent s) "-- return nil"
                | _ ->
                    binds (indent s) fl
                line s "end"
            | TyJoinPoint(a,args) -> simple (jp (a, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The Lua backend does not support nesting other backends."
            | TyWhile(a, b) ->
                let id = while_id
                while_id <- while_id + 1

                print
                    false
                    (fun s id' ->
                        line s (sprintf "function loop%i(v0, v1)" id')
                        line (indent s) "while true do"
                        line (indent (indent s)) (sprintf "if %s then" (jp a))
                        binds (indent (indent (indent s))) b
                        line (indent (indent (indent s))) (sprintf "v0, v1 = v0, v1")
                        line (indent (indent s)) "else"
                        line (indent (indent (indent s))) "return v0"
                        line (indent (indent s)) "end"
                        line (indent s) "end"
                        line s "end"
                    )
                    id

                simple (sprintf "local v0 = loop%i(v0, v1)" id)

            | TyDo a ->
                complex <| fun s ->
                line s "do"
                binds (indent s) a
                line s "end"
            | TyIndent a ->
                complex <| fun s ->
                binds (indent s) a
            | TyIntSwitch(L(i,_),on_succ,on_fail) ->
                complex <| fun s ->
                line s (sprintf "local __switch = v%i" i)
                Array.iteri (fun i x ->
                    if i = 0 then
                        line s (sprintf "if __switch == %i then" i)
                    else
                        line s (sprintf "elseif __switch == %i then" i)
                    binds (indent s) x
                    ) on_succ
                line s "else"
                binds (indent s) on_fail
                line s "end"
            | TyUnionUnbox(is,x,on_succs,on_fail) ->
                complex <| fun s ->
                let case_tags = x.Item.tags
                let vs =
                    is
                    |> List.map (fun (L(i,_)) -> sprintf "v%i" i)
                    |> String.concat ", "
                line s (sprintf "local __v = { %s }" vs)

                let xUnion = x.Item
                let unionRec, prefix =
                    match xUnion.layout with
                    | UHeap ->
                        let u = uheap xUnion.cases
                        u, sprintf "Uh%i" u.tag
                    | UStack ->
                        let u = ustack xUnion.cases
                        u, sprintf "Us%i" u.tag

                let scrutineeIds =
                    is |> List.map (fun (L(i,_)) -> i)

                let mutable first = true
                Map.iter (fun k (a,bnds) ->
                    let i = case_tags.[k]
                    let guard =
                        is
                        |> List.mapi (fun idx _ ->
                            sprintf "__v[%i] ~= nil and __v[%i].tag == \"%si%i\"" (idx + 1) (idx + 1) prefix i
                        )
                        |> String.concat " and "

                    if first then
                        line s (sprintf "if %s then" guard)
                        first <- false
                    else
                        line s (sprintf "elseif %s then" guard)

                    let body = indent s

                    let payloadArity =
                        match
                            unionRec.free_vars |> Map.tryPick (fun (_, k') v -> if k' = UnionTagIdOps.text k then Some v else None)
                        with
                        | Some arr -> arr.Length
                        | None -> 0

                    let binderIds =
                        a
                        |> List.choose (fun pat ->
                            match pat with
                            | DV (L(j,_)) -> Some j
                            | _ -> None)

                    let handledDirectReturn =
                        match is, bnds, payloadArity with
                        | [_], [| TyLocalReturnData(d,_) |], n when n > 0 ->
                            match data_term_vars d with
                            | [| WV (L(j,_)) |] when not (scrutineeIds |> List.exists ((=) j)) ->
                                line body "return __v[1]._1"
                                true
                            | _ -> false
                        | _ -> false

                    if not handledDirectReturn then
                        match is with
                        | [_] when payloadArity > 0 && binderIds <> [] ->
                            binderIds
                            |> List.mapi (fun idx j ->
                                line body (sprintf "local v%i = __v[1]._%i" j (idx + 1)))
                            |> ignore
                        | _ -> ()

                        binds body bnds

                ) on_succs

                match on_fail with
                | Some b ->
                    line s "else"
                    binds (indent s) b
                    line s "end"
                | None ->
                    line s "end"
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let i = c.tags.[a]
                let vars =
                    match data_term_vars b with
                    | [||] -> ""
                    | x -> Array.mapi (fun _j v -> show_w v) x |> String.concat ", "
                match c.layout with
                | UHeap -> $"Uh{(uheap c.cases).tag}i{i}({vars})"
                | UStack -> $"Us{(ustack c.cases).tag}i{i}({vars})"
                |> simple
            | TyToLayout(a,b) ->
                let a = layout_vars a
                match b with
                | YLayout(_,layout) ->
                    match layout with
                    | Heap -> if a = "" then sprintf "{ __tag = \"Heap%i\" }" (heap b).tag else sprintf "{ __tag = \"Heap%i\", %s }" (heap b).tag a
                    | HeapMutable -> if a = "" then sprintf "{ __tag = \"Mut%i\" }" (mut b).tag else sprintf "{ __tag = \"Mut%i\", %s }" (mut b).tag a
                    | StackMutable -> raise_codegen_error "The Lua backend doesn't support stack mutable layout types."
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (4).\nGot: %s{show_ty b}"
                |> simple
            | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The Lua backend doesn't support indexing into stack mutable layout types."
                |> fun x -> x.free_vars |> layout_index i
            | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The Lua backend doesn't support indexing into stack mutable layout types."
                |> fun x ->
                    x.free_vars_by_key
                    |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)
                    |> Option.iter (layout_index i)
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
            | TyLayoutMutableSet(L(i,t),b,c) ->
                let a = List.fold (fun s k ->
                    match s with
                    | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                    | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t).data b
                let a_vars = data_free_vars a
                Array.iter2 (fun (L(i',_)) b ->
                    line s (sprintf "v%i.l%i = %s" i i' (show_w b))
                    ) a_vars (data_term_vars c)
            | TyArrayLiteral(a,b) ->
                (List.map tup b |> String.concat ", " |> sprintf "{ %s }")
                |> simple
            | TyArrayCreate(a,b) -> "{}" |> simple
            | TyArrayLength(a,b) ->
                sprintf "#(%s)" (tup b)
                |> simple
            | TyStringLength(a,b) -> length (a,b)
            | TyFailwith(a,b) -> simple (sprintf "error(%s)" (tup b))
            | TyConv(a,b) ->
                let d = tup b
                simple d
            | TyApply (L(i, t), b) ->
                let arg_code = tup b
                let call =
                  match t with
                  | YFun (domain, _, FT_Vanilla) ->
                      let domain_is_nil = env.ty_to_data domain |> data_free_vars |> Array.isEmpty
                      if arg_code |> SpiralSm.trim = "nil" then
                        if domain_is_nil then sprintf "v%i(nil)" i else sprintf "v%i" i
                      else
                        if domain_is_nil then sprintf "v%i((%s)(nil))" i arg_code
                        else sprintf "v%i(%s)" i arg_code
                  | _ ->
                      sprintf "v%i(%s)" i arg_code
                call |> simple
            | TyOp(Global, [DLit (LitString x)]) -> global' x
            | TyOp(op,l) ->
                match op, l with
                | Dyn,[a] -> tup a
                | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                | StringIndex, [a;b] ->
                    sprintf "string.sub(%s, (%s)+1, (%s)+1)" (tup a) (tup b) (tup b)
                | StringSlice, [a;b;c] ->
                    sprintf "string.sub(%s, (%s)+1, (%s)+1)" (tup a) (tup b) (tup c)
                | ArrayIndex, [a;b] ->
                    sprintf "(%s)[(%s)+1]" (tup a) (tup b)
                | ArrayIndexSet, [a;b;c] ->
                    sprintf "(%s)[(%s)+1] = %s" (tup a) (tup b) (tup c)

                // Math
                | Add, [a;b] -> sprintf "%s + %s" (tup a) (tup b)
                | Sub, [a;b] -> sprintf "%s - %s" (tup a) (tup b)
                | Mult, [a;b] -> sprintf "%s * %s" (tup a) (tup b)
                | Div, [a;b] -> sprintf "%s / %s" (tup a) (tup b)
                | Mod, [a;b] -> sprintf "%s %% %s" (tup a) (tup b)
                | Pow, [a;b] -> sprintf "%s ^ %s" (tup a) (tup b)
                | LT, [a;b] -> sprintf "%s < %s" (tup a) (tup b)
                | LTE, [a;b] -> sprintf "%s <= %s" (tup a) (tup b)
                | EQ, [a;b] -> sprintf "%s == %s" (tup a) (tup b)
                | NEQ, [a;b] -> sprintf "%s ~= %s" (tup a) (tup b)
                | GT, [a;b] -> sprintf "%s > %s" (tup a) (tup b)
                | GTE, [a;b] -> sprintf "%s >= %s" (tup a) (tup b)
                | BoolAnd, [a;b] -> sprintf "(%s) and (%s)" (tup a) (tup b)
                | BoolOr, [a;b] -> sprintf "(%s) or (%s)" (tup a) (tup b)
                | BitwiseAnd, [a;b] ->
                    if targetLua54 then sprintf "(%s) & (%s)" (tup a) (tup b) else "bit.band(" + (tup a) + ", " + (tup b) + ")"
                | BitwiseOr, [a;b] ->
                    if targetLua54 then sprintf "(%s) | (%s)" (tup a) (tup b) else "bit.bor(" + (tup a) + ", " + (tup b) + ")"
                | BitwiseXor, [a;b] ->
                    if targetLua54 then sprintf "(%s) ~ (%s)" (tup a) (tup b) else "bit.bxor(" + (tup a) + ", " + (tup b) + ")"
                | BitwiseComplement, [a] ->
                    if targetLua54 then sprintf "~(%s)" (tup a) else "bit.bnot(" + (tup a) + ")"
                | ShiftLeft, [a;b] ->
                    if targetLua54 then sprintf "(%s) << (%s)" (tup a) (tup b) else "bit.lshift(" + (tup a) + ", " + (tup b) + ")"
                | ShiftRight, [a;b] ->
                    if targetLua54 then sprintf "(%s) >> (%s)" (tup a) (tup b) else "bit.rshift(" + (tup a) + ", " + (tup b) + ")"

                | Neg, [x] -> sprintf "-(%s)" (tup x)
                | Log, [x] -> sprintf "math.log(%s)" (tup x)
                | Exp, [x] -> sprintf "math.exp(%s)" (tup x)
                | Tanh, [x] -> sprintf "math.tanh(%s)" (tup x)
                | Sqrt, [x] -> sprintf "math.sqrt(%s)" (tup x)
                | Sin, [x] -> sprintf "math.sin(%s)" (tup x)
                | Cos, [x] -> sprintf "math.cos(%s)" (tup x)
                | NanIs, [x] -> sprintf "tostring(%s) == 'nan'" (tup x)
                | UnionTag, [DV(L(i,YUnion h))] ->
                    let h = h.Item
                    let ty =
                        match h.layout with
                        | UHeap -> sprintf "Uh%i" (uheap h.cases).tag
                        | UStack -> sprintf "Us%i" (ustack h.cases).tag
                    let mutable code = StringBuilder()
                    code.Append(";(function () local __tag\n") |> ignore
                    h.cases |> Seq.iteri (fun idx (KeyValue ((ci,_), _)) ->
                        if idx = 0 then
                            code.AppendFormat("if v{0}.tag == \"{1}i{2}\" then __tag = {2}\n", i, ty, ci) |> ignore
                        else
                            code.AppendFormat("elseif v{0}.tag == \"{1}i{2}\" then __tag = {2}\n", i, ty, ci) |> ignore
                    )
                    code.Append("else __tag = 0 end\nreturn __tag end)()") |> ignore
                    code.ToString()
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported" op l.Length
                |> simple
        and heap : _ -> LayoutRecLua = layout (fun s x ->
            let b = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "l%i" i) |> String.concat ", "
            if b = "" then line s (sprintf "Heap%i = function() return { __tag = \"Heap%i\" } end" x.tag x.tag)
            else line s (sprintf "Heap%i = function(%s) return { __tag = \"Heap%i\", %s } end" x.tag b x.tag b)
            )
        and mut : _ -> LayoutRecLua = layout (fun s x ->
            let b = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "l%i" i) |> String.concat ", "
            if b = ""
            then line s (sprintf "Mut%i = function() return { __tag = \"Mut%i\" } end" x.tag x.tag)
            else
                let b' = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "l%i = l%i" i i) |> String.concat ", "
                line s (sprintf "Mut%i = function(%s) return { __tag = \"Mut%i\", %s } end" x.tag b x.tag b')
            )
        and uheap : _ -> UnionRecLua = union (fun s x ->
            let tag = x.tag
            let mutable i = 0
            x.free_vars |> Map.iter (fun _ a ->
                match a with
                | [||] -> line s (sprintf "function Uh%ii%i() return { tag = \"Uh%ii%i\" } end" tag i tag i)
                | a ->
                    let params' = a |> Array.mapi (fun j _ -> sprintf "v%i" j) |> String.concat ", "
                    let fields = a |> Array.mapi (fun j _ -> sprintf " _%i = v%i" (j+1) j) |> String.concat ", "
                    line s (sprintf "function Uh%ii%i(%s) return { tag = \"Uh%ii%i\", %s } end" tag i params' tag i fields)
                i <- i + 1
            )
        )
        and ustack : _ -> UnionRecLua = union (fun s x ->
            let tag = x.tag
            let mutable i = 0
            x.free_vars |> Map.iter (fun _ a ->
                match a with
                | [||] -> line s (sprintf "function Us%ii%i() return { tag = \"Us%ii%i\" } end" tag i tag i)
                | a ->
                    let params' = a |> Array.mapi (fun j _ -> sprintf "v%i" j) |> String.concat ", "
                    let fields = a |> Array.mapi (fun j _ -> sprintf " _%i = v%i" (j+1) j) |> String.concat ", "
                    line s (sprintf "function Us%ii%i(%s) return { tag = \"Us%ii%i\", %s } end" tag i params' tag i fields)
                i <- i + 1
            )
        )
        and method : _ -> MethodRecLua =
            jp (fun ((jp_body,key),i) ->
                let args = codegenMethodKeyArgs key
                match codegenMethodBody env "Lua" jp_body key with
                | a, range, _ -> {tag=i; free_vars=rdata_free_vars args; range=range; body=a}
                ) (fun s x ->
                line s (sprintf "function method%i(%s)" x.tag (args_tys x.free_vars))
                binds (indent s) x.body
                line s "end"
                )
        and closure : _ -> ClosureRecLua =
            jp
                (fun ((jp_body, key & (C(args, _, fun_ty))), i) ->
                match fun_ty with
                | YFun (domain, range, FT_Vanilla) ->
                    match codegenClosureBody env "Lua" jp_body key with
                    | domain_args, body ->
                        {   tag = i
                            free_vars = rdata_free_vars args
                            domain_args = data_free_vars domain_args
                            range = range
                            body = body }
                | YFun (_, _, _) ->
                    raise_codegen_error "Non-standard functions are not supported in the Lua backend."
                | _ ->
                    raise_codegen_error "Compiler error: Unexpected type in the closure join point.")
                (fun s x ->
                let fv_bind =
                    match x.free_vars with
                    | [||] -> "local __capt = nil"
                    | arr ->
                        let names = arr |> Array.mapi (fun _ (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "
                        sprintf "local %s = capt[1], %s" (arr |> Array.mapi (fun _ (L(i,_)) -> sprintf "v%i" i) |> Array.head) (names |> SpiralSm.replace (arr |> Array.mapi (fun _ (L(i,_)) -> sprintf "v%i" i) |> Array.head) "" |> SpiralSm.trim)
                line s (sprintf "function closure%i(capt)" x.tag)
                if x.free_vars.Length > 0 then line (indent s) (sprintf "local %s = (table.unpack or unpack)(capt)" (x.free_vars |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "))
                match x.domain_args with
                | [||] ->
                    line (indent s) "return function(dom)"
                | [| L(i, _) |] ->
                    line (indent s) (sprintf "return function(v%i)" i)
                | many ->
                    line (indent s) "return function(dom)"
                    line (indent (indent s)) "local _ = (table.unpack or unpack)(dom)"
                binds (indent (indent s)) x.body
                line (indent s) "end"
                line s "end"
            )

        let main = StringBuilder()
        binds {text=main; indent=0} x

        let program = StringBuilder()

        if not targetLua54 then
            program.Append("local bit = bit32 or bit\n") |> ignore
        else
            program.Append("-- lua 5.4 ops\n") |> ignore
        types |> Seq.iteri (fun i x -> program.Append(x).Append("\n") |> ignore)
        functions |> Seq.iteri (fun i x -> program.Append(x).Append("\n") |> ignore)
        program.Append(main.ToString()).ToString()

    /// ## RefCounting
    // Here are the reference counting analysis passes.
    open System.Collections.Generic

    /// ### varc_add
    let varc_add x i v =
        let c = Option.defaultValue 0 (Map.tryFind x v) + i
        if c = 0 then Map.remove x v else Map.add x c v

    /// ### varc_union
    let varc_union a b = Map.foldBack varc_add a b

    /// ### varc_data
    let varc_data call_data =
        let mutable v = Map.empty
        let rec f = function
            | DPair(a,b) -> f a; f b
            | DForall(_,a,_,_,_) | DFunction(_,_,a,_,_,_) -> Array.iter f a
            | DRecord l -> Map.iter (fun _ -> f) l
            | DV x -> v <- varc_add x 1 v
            | DExists(_,a) | DUnion(a,_) | DNominal(a,_) -> f a
            | DLit _ | DTLit _ | DSymbol _ | DB -> ()
            | DHashSet x -> Seq.iter f x
            | DHashMap(x,_) -> x |> Seq.iter (fun kv -> f kv.Value)
        f call_data
        v

    /// ### varc_set
    let varc_set x i = Set.fold (fun s v -> Map.add v i s) Map.empty x

    /// ### refc_used_vars
    let refc_used_vars (x : TypedBind []) =
        let g_bind : Dictionary<TypedBind, TyV Set> = Dictionary(HashIdentity.Reference)
        let fv x = x |> data_free_vars |> Set
        let jp (x : JoinPointCall) = snd x |> Set
        let rec binds x =
            Array.foldBack (fun k vs ->
                match k with
                | TyLet(d,_,o) -> vs + op o - fv d
                | TyLocalReturnOp(_,o,_) -> vs + op o
                | TyLocalReturnData(d,_) -> vs + fv d
                |> fun vs -> g_bind.Add(k,vs); vs
                ) x Set.empty
        and op (x : TypedOp) : TyV Set =
            match x with
            | TySizeOf _ -> Set.empty
            | TyMacro l -> List.fold (fun s -> function CMTerm (d,_) -> s + fv d | _ -> s) Set.empty l
            | TyArrayLiteral(_,l) | TyOp(_,l) -> List.fold (fun s x -> s + fv x) Set.empty l
            | TyToLayout(x,_) | TyUnionBox(_,x,_) | TyFailwith(_,x) | TyConv(_,x) | TyArrayCreate(_,x) | TyArrayLength(_,x) | TyStringLength(_,x) -> fv x
            | TyWhile(cond,body) -> jp cond + binds body
            | TyDo body | TyIndent body -> binds body
            | TyLayoutIndexAll(i) | TyLayoutIndexByKey(i,_) -> Set.singleton i
            | TyApply(i,d) | TyLayoutMutableSet(i,_,d) -> Set.singleton i + fv d
            | TyJoinPoint x -> jp x
            | TyBackend(_,_,_) -> Set.empty
            | TyIf(cond,tr',fl') -> fv cond + binds tr' + binds fl'
            | TyUnionUnbox(vs,_,on_succs',on_fail') ->
                let vs = vs |> Set
                let on_fail =
                    match on_fail' with
                    | Some x -> binds x
                    | None -> Set.empty
                Map.fold (fun s k (lets,body) ->
                    let lets = List.fold (fun s x -> s + fv x) Set.empty lets
                    s + (binds body - lets)
                    ) (vs + on_fail) on_succs'
            | TyIntSwitch(tag,on_succs',on_fail') ->
                let vs = Set.singleton tag
                let on_fail = binds on_fail'
                Array.fold (fun s body -> s + binds body) (vs + on_fail) on_succs'
        binds x |> ignore
        g_bind

    /// ### RefcVars
    type RefcVars = {g_incr : Dictionary<TypedBind,TyV Set>; g_decr : RefcDecrTable; g_op : Dictionary<TypedBind,Map<TyV, int>>; g_op_decr : Dictionary<TypedBind,TyV Set>}

    /// ### refc_prepass
    let refc_prepass (new_vars : TyV Set) (increfed_vars : TyV Set) (x : TypedBind []) =
        let used_vars = refc_used_vars x
        let g_incr : Dictionary<TypedBind, TyV Set> = Dictionary(HashIdentity.Reference)
        let g_decr : RefcDecrTable = refcDecrTable ()
        let g_op : Dictionary<TypedBind, _> = Dictionary(HashIdentity.Reference)
        let g_op_decr : Dictionary<TypedBind, TyV Set> = Dictionary(HashIdentity.Reference)

        let add (d : Dictionary<TypedBind, TyV Set>) k x = if Set.isEmpty x then () else d.Add(k,x)
        let add_cd (d : RefcDecrTable) k x = if Set.isEmpty x then () else refcDecrAdd d k x
        let add' (d : Dictionary<TypedBind, Map<TyV,int>>) k x = if Map.isEmpty x then () else d.Add(k,x)
        let fv x = x |> data_free_vars |> Set
        let rec binds (new_vars : TyV Set) (increfed_vars : TyV Set) (k : TypedBind []) =
            Array.fold (fun (new_vars, increfed_vars) k ->
                add g_incr k new_vars
                let increfed_vars = new_vars + increfed_vars

                let used_vars = used_vars.[k]
                let decref_vars = increfed_vars - used_vars
                add_cd g_decr k decref_vars
                let r = increfed_vars - decref_vars
                match k with
                | TyLet(d,_,o) ->
                    op k Set.empty o
                    let new_vars = fv d
                    match o with
                    | TyLayoutIndexAll _ | TyLayoutIndexByKey _ | TyOp(ArrayIndex,_) -> new_vars, r
                    | _ -> Set.empty, r + new_vars
                | TyLocalReturnOp(_,o,_) ->
                    op k r o
                    Set.empty, r
                | TyLocalReturnData(d,_) ->
                    add' g_op k (varc_data d)
                    add g_op_decr k r
                    Set.empty, r
                ) (new_vars, increfed_vars) k
            |> ignore
        and op k increfed_vars (x : TypedOp) : unit =
            let fun_call q = add' g_op k q; add g_op_decr k increfed_vars
            match x with
            | TyApply(a,b) -> varc_add a 1 (varc_data b) |> fun_call
            | TyJoinPoint(_,x) -> Array.fold (fun s x -> varc_add x 1 s) Map.empty x |> fun_call
            | TyArrayLiteral(_,x) -> List.fold (fun s x -> varc_union s (varc_data x)) Map.empty x |> fun_call
            | TyUnionBox(_,x,_) | TyToLayout(x,_) -> varc_data x |> fun_call
            | TySizeOf _ | TyLayoutIndexAll _ | TyLayoutIndexByKey _ | TyMacro _ | TyOp _ | TyFailwith _ | TyConv _
            | TyArrayCreate _ | TyArrayLength _ | TyStringLength _ | TyLayoutMutableSet _ | TyBackend _ -> ()
            | TyWhile(_,body) -> binds Set.empty Set.empty body
            | TyDo body | TyIndent body -> binds Set.empty Set.empty body
            | TyIf(_,tr',fl') -> binds Set.empty increfed_vars tr'; binds Set.empty increfed_vars fl'
            | TyUnionUnbox(_,_,on_succs',on_fail') ->
                Map.iter (fun _ (lets,body) ->
                    binds (List.fold (fun s x -> s + fv x) Set.empty lets) increfed_vars body
                    ) on_succs'
                Option.iter (binds Set.empty increfed_vars) on_fail'
            | TyIntSwitch(_,on_succs',on_fail') ->
                Array.iter (binds Set.empty increfed_vars) on_succs'
                binds Set.empty increfed_vars on_fail'
        binds new_vars increfed_vars x

        {g_incr=g_incr; g_op=g_op; g_decr=g_decr; g_op_decr=g_op_decr}

    /// ## CodegenC
    module CodegenC =
        // open System
        // open System.Text
        open System.Collections.Generic

        let sizeof_tyvC = function
            | YPrim (Int64T | UInt64T | Float64T) -> 8
            | YPrim (Int32T | UInt32T | Float32T) -> 4
            | YPrim (Int16T | UInt16T) -> 2
            | YPrim (Int8T | UInt8T | CharT | BoolT) -> 1
            | _ -> 8
        let order_argsC v = v |> Array.sortWith (fun (L(_,t)) (L(_,t')) -> compare (sizeof_tyvC t') (sizeof_tyvC t))
        let lineC x s = if s <> "" then x.text.Append(' ', x.indent).AppendLine s |> ignore
        let line' x s = line x (String.concat " " s)

        let rec is_heap f x =
            Array.exists (fun (L(i,t)) ->
                match t with
                | YUnion a when a.Item.layout = UStack -> Array.exists (snd >> f >> is_heap f) a.Item.tag_cases
                | YPrim StringT -> true
                | YPrim _ -> false
                | _ -> true
                ) x
        let is_stringC = function DV(L(_,YPrim StringT)) | DLit(LitString _) -> true | _ -> false

        type BindsReturnC =
            | BindsTailEnd
            | BindsLocal of TyV []

        let term_vars_to_tysC x = x |> Array.map (function WV(L(_,t)) -> t | WLit x -> YPrim (lit_to_primitive_type x))
        let binds_last_dataC x = x |> Array.last |> function TyLocalReturnData(x,_) | TyLocalReturnOp(_,_,x) -> x | TyLet _ -> raise_codegen_error "Compiler error: Cannot find the return data of the last bind."

        type UnionRecC = {tag : int; free_vars : Map<int * string, TyV[]>}
        type LayoutRecC = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>}
        type MethodRecC = {tag : int; free_vars : L<Tag,Ty>[]; range : Ty; body : TypedBind[]; name : string option}
        type ClosureRecC = {tag : int; free_vars : L<Tag,Ty>[]; domain : Ty; domain_args : TyV[]; range : Ty; body : TypedBind[]}
        type TupleRecC = {tag : int; tys : Ty []}
        type ArrayRecC = {tag : int; ty : Ty; tyvs : TyV[]}
        type CFunRecC = {tag : int; domain_args_ty : Ty[]; range : Ty}

        let size_t = UInt32T

        let lit_stringC x =
            let strb = StringBuilder(String.length x + 2)
            strb.Append '"' |> ignore
            String.iter (function
                | '"' -> strb.Append "\\\""
                | '\b' -> strb.Append @"\b"
                | '\t' -> strb.Append @"\t"
                | '\n' -> strb.Append @"\n"
                | '\r' -> strb.Append @"\r"
                | '\\' -> strb.Append @"\\"
                | x -> strb.Append x
                >> ignore
                ) x
            strb.Append '"' |> ignore
            strb.ToString()

        let codegenC (env : PartEvalResult) (x : TypedBind []) =
            let globals = ResizeArray()
            let fwd_dcls = ResizeArray()
            let types = ResizeArray()
            let functions = ResizeArray()

            let malloc, free = "malloc", "free"

            let print_decref s_fun name_fun type_arg name_decref =
                line s_fun (sprintf "void %s(%s * x){" name_fun type_arg)
                let _ =
                    let s_fun = indent s_fun
                    line s_fun (sprintf "if (x != NULL && --(x->refc) == 0) { %s(x); %s(x); }" name_decref free)
                line s_fun "}"

            let print show r =
                let s_typ_fwd = {text=StringBuilder(); indent=0}
                let s_typ = {text=StringBuilder(); indent=0}
                let s_fun = {text=StringBuilder(); indent=0}
                show s_typ_fwd s_typ s_fun r
                let f (a : _ ResizeArray) (b : CodegenEnv) =
                    let text = b.text.ToString()
                    if text <> "" then a.Add(text)
                f fwd_dcls s_typ_fwd
                f types s_typ
                f functions s_fun

            let layout show =
                let dict' = codegenMemoTable HashIdentity.Structural
                let dict = codegenMemoTable HashIdentity.Reference
                let f x : LayoutRecC =
                    match x with
                    | YLayout(x,_) ->
                        let x = env.ty_to_data x
                        let a, b =
                            match x with
                            | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                            | _ -> data_free_vars x, Map.empty
                        {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                    | _ -> raise_codegen_error $"Compiler error: Expected a layout type (7).\nGot: %s{show_ty x}"
                fun x ->
                    let mutable dirty = false
                    let r = memoize dict (memoize dict' (fun x -> dirty <- true; f x)) x
                    if dirty then print show r
                    r

            let union show =
                let dict = codegenMemoTable HashIdentity.Reference
                let f (a : Union) : UnionRecC =
                    let free_vars = a.Item.cases |> Map.map (fun _ -> env.ty_to_data >> data_free_vars)
                    {free_vars=free_vars; tag=dict.Count}
                fun x ->
                    let mutable dirty = false
                    let r = memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let jp f show =
                let dict = codegenMemoTable HashIdentity.Structural
                let f x = f (x, dict.Count)
                fun x ->
                    let mutable dirty = false
                    let r = memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let tuple show =
                let dict = codegenMemoTable HashIdentity.Structural
                let f x = {tag=dict.Count; tys=x}
                fun x ->
                    let mutable dirty = false
                    let r = memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let carray' show =
                let dict = codegenMemoTable HashIdentity.Structural
                let f x = {tag=dict.Count; ty=x; tyvs = env.ty_to_data x |> data_free_vars}
                fun x ->
                    let mutable dirty = false
                    let r = memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let cstring' show =
                let mutable dirty = true
                fun () ->
                    if dirty then print show ()
                    dirty <- false

            let cstring_slice' show =
                let mutable dirty = true
                fun () ->
                    if dirty then print show ()
                    dirty <- false

            let cstring_concat' show =
                let mutable dirty = true
                fun () ->
                    if dirty then print show ()
                    dirty <- false

            let cfun' show =
                let dict = codegenMemoTable HashIdentity.Structural
                let f (a : Ty, b : Ty) = {tag=dict.Count; domain_args_ty=a |> env.ty_to_data |> data_free_vars |> Array.map (fun (L(_,t)) -> t); range=b}
                fun x ->
                    let mutable dirty = false
                    let r = memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let args x = x |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "

            let tmp =
                let mutable i = 0u
                fun () -> let x = i in i <- i + 1u; x

            let global' =
                let has_added = HashSet env.globals
                fun x -> if preservesDuplicateGlobalFragment x || has_added.Add(x) then globals.Add x

            let import x = global' $"#include <{x}>"
            let import' x = global' $"#include \"{x}\""

            let tyvs_to_tys (x : TyV []) = Array.map (fun (L(i,t)) -> t) x

            let rec binds_start (args : TyV []) (s : CodegenEnv) (x : TypedBind []) = binds (refc_prepass Set.empty (Set args) x) s BindsTailEnd x
            and return_local s ret (x : string) =
                match ret with
                | [||] -> line s $"{x};"
                | [|L(i,_)|] -> line s $"v{i} = {x};"
                | ret ->
                    let tmp_i = tmp()
                    line s $"{tup_ty_tyvs ret} tmp{tmp_i} = {x};"
                    Array.mapi (fun i (L(i',_)) -> $"v{i'} = tmp{tmp_i}.v{i};") ret |> line' s
            and binds (vars : RefcVars) (s : CodegenEnv) (ret : BindsReturnC) (stmts : TypedBind []) =
                let tup_destruct (a,b) =
                    Array.map2 (fun (L(i,_)) b ->
                        match b with
                        | WLit b -> $"v{i} = {lit b};"
                        | WV (L(i',_)) -> $"v{i} = v{i'};"
                        ) a b
                Array.iter (fun x ->
                    // This complicated looking piece of code is responsible for putting the incref and decref statements at the beginning of every
                    // statement. It's actually the only place where ref counting code is outputted in the codegen.
                    let _ =
                        let incr0 = get_default vars.g_incr x (fun () -> Set.empty)
                        let decr0 = get_default vars.g_decr x (fun () -> Set.empty)
                        let op0 = get_default vars.g_op x (fun () -> Map.empty)
                        let op_decr0 = get_default vars.g_op_decr x (fun () -> Set.empty)
                        let incr, decr, op, op_decr = varc_set incr0 1, varc_set decr0 -1, op0, varc_set op_decr0 -1
                        let incr, decr = varc_union incr decr |> varc_union op |> varc_union op_decr |> Map.partition (fun _ v -> 0 < v)
                        refc_varc incr |> line' s; refc_varc decr |> line' s
                    match x with
                    | TyLet(d,trace,a) ->
                        try let d = data_free_vars d
                            let decl_vars = Array.map (fun (L(i,t)) -> $"{tyv t} v{i};") d
                            match a with
                            | TyMacro a ->
                                let m = a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup_data x) | CMType x -> tup_ty x | CMTypeLit x -> type_lit x) |> String.concat ""
                                let q = m.Split("\\v")
                                if q.Length = 1 then
                                    decl_vars |> line' s
                                    return_local s d m
                                else
                                    if d.Length = q.Length-1 then
                                        let w = StringBuilder(m.Length+8)
                                        let tag (L(i,_)) = i : int
                                        Array.iteri (fun i v -> w.Append(q.[i]).Append('v').Append(tag v) |> ignore) d
                                        w.Append(q.[d.Length]).Append(';').ToString() |> line s
                                    else
                                        raise_codegen_error "The special \\v macro requires the same number of free vars in its binding as there are \\v in the code."
                            | _ ->
                                decl_vars |> line' s
                                op vars s (BindsLocal d) a
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    | TyLocalReturnOp(trace,a,_) ->
                        try op vars s ret a
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    | TyLocalReturnData(d,trace) ->
                        try match ret with
                            | BindsLocal l -> line' s (tup_destruct (l,data_term_vars d))
                            | BindsTailEnd -> line s $"return {tup_data d};"
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    ) stmts
            and refc_change'' (f : int * Ty -> string) count (L(i,t')) =
                let v = i,t'
                let inline g decref =
                    if count = -1 then Some (decref())
                    elif count = 1 then Some $"{f v}->refc++;"
                    elif 1 < count then Some $"{f v}->refc += {count};"
                    else raise_codegen_error $"Compiler error: Invalid count in refc_change''. Got: {count}"
                match t' with
                | YUnion t ->
                    match t.Item.layout with
                    | UStack ->
                        if count = -1 then Some $"USDecref{(ustack t).tag}(&({f v}));"
                        elif 0 < count then Some (String.replicate count $"USIncref{(ustack t).tag}(&({f v}));")
                        else raise_codegen_error $"Compiler error: Invalid count in refc_change''. UStack case. Got: {count}"
                    | UHeap -> g (fun () -> $"UHDecref{(uheap t).tag}({f v});")
                | YArray t -> g (fun () -> $"ArrayDecref{(carray t).tag}({f v});")
                | YFun(a,b,FT_Vanilla) -> g (fun () ->  $"{f v}->decref_fptr({f v});")
                | YPrim StringT -> g (fun () ->  $"StringDecref({f v});" )
                | YLayout(_,Heap) as a -> g (fun () ->  $"HeapDecref{(heap a).tag}({f v});")
                | YLayout(_,HeapMutable) as a -> g (fun () ->  $"MutDecref{(mut a).tag}({f v});")
                | _ -> None
            and refc_change' (f : int * Ty -> string) count (x : TyV []) : string [] = Array.choose (refc_change'' f count) x
            and refc_change f c x = refc_change' (fun (i,t) -> f i) c x
            and refc_varc x =
                let ar = ResizeArray(Map.count x)
                Map.iter (fun k v -> refc_change'' (fun (i,_) -> $"v{i}") v k |> Option.iter ar.Add) x
                ar
            //and refc_incr x : string [] = refc_change (fun i -> $"v{i}") 1 x
            //and refc_decr x : string [] = refc_change (fun i -> $"v{i}") -1 x
            and show_w = function WV(L(i,_)) -> sprintf "v%i" i | WLit a -> lit a
            and args' b = data_term_vars b |> Array.map show_w |> String.concat ", "
            and tup_term_vars x =
                let args = Array.map show_w x |> String.concat ", "
                if 1 < x.Length then sprintf "TupleCreate%i(%s)" (tup (term_vars_to_tysC x)).tag args else args
            and tup_data x = tup_term_vars (data_term_vars x)
            and tup_ty_tys = function
                | [||] -> "void"
                | [|x|] -> tyv x
                | x -> sprintf "Tuple%i" (tup x).tag
            and tup_ty_tyvs (x : TyV []) = tup_ty_tys (tyvs_to_tys x)
            and tup_ty x = env.ty_to_data x |> data_free_vars |> tup_ty_tyvs
            and tyv x =
                match x with
                | YUnion a ->
                    match a.Item.layout with
                    | UStack -> sprintf "US%i" (ustack a).tag
                    | UHeap -> sprintf "UH%i *" (uheap a).tag
                | YLayout(_,lay) as a ->
                    match lay with
                    | Heap -> sprintf "Heap%i *" (heap a).tag
                    | HeapMutable -> sprintf "Mut%i *" (mut a).tag
                    | StackMutable -> raise_codegen_error "Compiler error: The C backend doesn't support stack mutable layout types."
                | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_lit a) |> String.concat ""
                | YPrim a -> prim a
                | YArray a -> sprintf "Array%i *" (carray a).tag
                | YFun(a,b,FT_Vanilla) -> sprintf "Fun%i *" (cfun (a,b)).tag
                | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
                | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
                | a -> raise_codegen_error (sprintf "Compiler error: Type not supported in the codegen.\nGot: %A" a)
            and prim = function
                | Int8T -> "int8_t"
                | Int16T -> "int16_t"
                | Int32T -> "int32_t"
                | Int64T -> "int64_t"
                | UInt8T -> "uint8_t"
                | UInt16T -> "uint16_t"
                | UInt32T -> "uint32_t"
                | UInt64T -> "uint64_t" // are defined in stdint.h
                | Float32T -> "float"
                | Float64T -> "double"
                | BoolT -> "bool" // is defined in stdbool.h
                | CharT -> "char"
                | StringT -> cstring(); "String *"
            and lit = function
                | LitInt8 x -> sprintf "%i" x
                | LitInt16 x -> sprintf "%i" x
                | LitInt32 x -> sprintf "%il" x
                | LitInt64 x -> sprintf "%ill" x
                | LitUInt8 x -> sprintf "%iu" x
                | LitUInt16 x -> sprintf "%iu" x
                | LitUInt32 x -> sprintf "%iul" x
                | LitUInt64 x -> sprintf "%iull" x
                | LitFloat32 x ->
                    if x = infinityf then "HUGE_VALF" // nan/inf macros are defined in math.h
                    elif x = -infinityf then "-HUGE_VALF"
                    elif Single.IsNaN x then "NAN"
                    else x.ToString("R") |> add_dec_point |> sprintf "%sf"
                | LitFloat64 x ->
                    if x = infinity then "HUGE_VAL"
                    elif x = -infinity then "-HUGE_VAL"
                    elif Double.IsNaN x then "NAN"
                    else x.ToString("R") |> add_dec_point
                | LitString x ->
                    cstring()
                    lit_stringC x |> sprintf "StringLit(%i, %s)" (System.Text.Encoding.UTF8.GetByteCount x + 1)
                | LitChar x ->
                    match x with
                    | '\b' -> @"\b"
                    | '\n' -> @"\n"
                    | '\t' -> @"\t"
                    | '\r' -> @"\r"
                    | '\\' -> @"\\"
                    | x -> string x
                    |> sprintf "'%s'"
                | LitBool x -> if x then "true" else "false" // true and false are defined in stddef.h
            and type_lit = function
                | YLit x -> lit x
                | YSymbol x -> x
                | YNominal _ | YApply _ as x -> type_lit (env.nominal_apply x)
                | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."
            and op (vars : RefcVars) s (ret : BindsReturnC) a =
                let binds a b = binds vars a b
                let return' (x : string) =
                    match ret with
                    | BindsLocal ret -> return_local s ret x
                    | BindsTailEnd -> line s $"return {x};"
                let layout_index (x'_i : int) (x' : TyV []) =
                    match ret with
                    | BindsLocal x -> Array.map2 (fun (L(i,_)) (L(i',_)) -> $"v{i} = v{x'_i}->v{i'};") x x' |> line' s
                    | BindsTailEnd -> raise_codegen_error "Compiler error: Layout index should never come in end position."
                let jp (a,b') =
                    let args = args b'
                    match a with
                    | JPMethod(a,b) ->
                        let x = method (a,b)
                        sprintf "%s%i(%s)" (Option.defaultValue "method" x.name) x.tag args
                    | JPClosure(a,b) -> sprintf "ClosureCreate%i(%s)" (closure (a,b)).tag args
                let string_in_op = function DLit (LitString b) -> lit_stringC b | b -> $"{tup_data b}->ptr"
                match a with
                | TySizeOf t -> return' $"sizeof({tup_ty t})"
                | TyMacro _ -> raise_codegen_error "Macros are supposed to be taken care of in the `binds` function."
                | TyIf(cond,tr,fl) ->
                    line s (sprintf "if (%s){" (tup_data cond))
                    binds (indent s) ret tr
                    line s "} else {"
                    binds (indent s) ret fl
                    line s "}"
                | TyJoinPoint(a,args) -> return' (jp (a, args))
                | TyBackend(_,_,r) -> raise_codegen_error_backend r "The C backend does not support nesting of other backends."
                | TyWhile(a,b) ->
                    let cond =
                        match a with
                        | JPMethod(a,b),b' -> sprintf "method_while%i(%s)" (method_while (a,b)).tag (args b')
                        | _ -> raise_codegen_error "Expected a regular method rather than closure create in the while conditional."
                    line s (sprintf "while (%s){" cond)
                    binds (indent s) (BindsLocal [||]) b
                    line s "}"
                | TyDo a | TyIndent a ->
                    binds s ret a
                | TyIntSwitch(L(v_i,_),on_succ,on_fail) ->
                    line s (sprintf "switch (v%i) {" v_i)
                    let _ =
                        let s = indent s
                        Array.iteri (fun i x ->
                            line s (sprintf "case %i: {" i)
                            binds (indent s) ret x
                            line (indent s) "break;"
                            line s "}"
                            ) on_succ
                        line s "default: {"
                        binds (indent s) ret on_fail
                        line s "}"
                    line s "}"
                | TyUnionUnbox(is,x,on_succs,on_fail) ->
                    let case_tags = x.Item.tags
                    let acs = match x.Item.layout with UHeap -> "->" | UStack -> "."
                    let head = List.head is |> fun (L(i,_)) -> $"v{i}{acs}tag"
                    List.pairwise is
                    |> List.map (fun (L(i,_), L(i',_)) -> $"v{i}{acs}tag == v{i'}{acs}tag")
                    |> String.concat " && "
                    |> function "" -> head | x -> $"{x} ? {head} : -1"
                    |> sprintf "switch (%s) {" |> line s
                    let _ =
                        let s = indent s
                        Map.iter (fun k (a,b) ->
                            let union_i = case_tags.[k]
                            let decr = get_default vars.g_decr (Array.head b) (fun () -> Set.empty)
                            line s (sprintf "case %i: { // %s" union_i (UnionTagIdOps.text k))
                            List.iter2 (fun (L(data_i,_)) a ->
                                let a, s = data_free_vars a, indent s
                                let qs = ResizeArray(a.Length)
                                Array.iteri (fun field_i (L(v_i,t) as v) ->
                                    if Set.contains v decr = false then qs.Add $"{tyv t} v{v_i} = v{data_i}{acs}case{union_i}.v{field_i};"
                                    ) a
                                line' s qs
                                ) is a
                            binds (indent s) ret b
                            line (indent s) "break;"
                            line s "}"
                            ) on_succs
                        on_fail |> Option.iter (fun b ->
                            line s "default: {"
                            binds (indent s) ret b
                            line s "}"
                            )
                    line s "}"
                | TyUnionBox(a,b,c') ->
                    let c = c'.Item
                    let i = c.tags.[a]
                    let vars = args' b
                    match c.layout with
                    | UHeap -> sprintf "UH%i_%i(%s)" (uheap c').tag i vars
                    | UStack -> sprintf "US%i_%i(%s)" (ustack c').tag i vars
                    |> return'
                | TyToLayout(a,b) ->
                    match b with
                    | YLayout(_,layout) ->
                        match layout with
                        | Heap -> sprintf "HeapCreate%i(%s)" (heap b).tag (args' a)
                        | HeapMutable -> sprintf "MutCreate%i(%s)" (mut b).tag (args' a)
                        | StackMutable -> raise_codegen_error "The C backend doesn't support stack mutable layout types."
                    | _ -> raise_codegen_error $"Compiler error: Expected a layout type (8).\nGot: %s{show_ty b}"
                    |> return'
                | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                    match lay with
                    | Heap -> heap a
                    | HeapMutable -> mut a
                    | StackMutable -> raise_codegen_error "The C backend doesn't support indexing into stack mutable layout types."
                    |> fun x -> x.free_vars |> layout_index i
                | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                    match lay with
                    | Heap -> heap a
                    | HeapMutable -> mut a
                    | StackMutable -> raise_codegen_error "The C backend doesn't support indexing into stack mutable layout types."
                    |> fun x ->
                        x.free_vars_by_key
                        |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)
                        |> Option.iter (layout_index i)
                | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
                | TyLayoutMutableSet(L(i,t),b,c) ->
                    let q = mut t // `mut t` is correct here, peval strips the YLayout.
                    let a = List.fold (fun s k ->
                        match s with
                        | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                        | _ -> raise_codegen_error "Compiler error: Expected a record.") q.data b
                    Array.map2 (fun (L(i',_)) b -> $"&(v{i}->v{i'}), {show_w b}") (data_free_vars a) (data_term_vars c) |> String.concat ", "
                    |> sprintf "AssignMut%i(%s)" (assign_mut (tyvs_to_tys q.free_vars)).tag |> return'
                | TyArrayLiteral(a,b') ->
                    let b = List.map tup_data b' |> String.concat "," |> sprintf "{%s}"
                    $"ArrayLit{(carray a).tag}({b'.Length}, ({tup_ty a} []){b})" |> return'
                | TyArrayCreate(a,b) ->
                    let a = carray a
                    let is_heap : string = is_heap (env.ty_to_data >> data_free_vars) a.tyvs |> sprintf "%b"
                    $"ArrayCreate{a.tag}({tup_data b}, {is_heap})" |> return'
                | TyFailwith(a,b) ->
                    let fmt = @"%s\n"
                    line s $"fprintf(stderr, \"{fmt}\", {string_in_op b});"
                    line s "exit(EXIT_FAILURE);" // TODO: Print out the error traces as well.
                | TyConv(a,b) -> return' $"({tyv a}){tup_data b}"
                | TyApply(L(i,_),b) ->
                    match args' b with
                    | "" -> $"v{i}->fptr(v{i})"
                    | b -> $"v{i}->fptr(v{i}, {b})"
                    |> return'
                | TyArrayLength(_,b) -> return' $"{tup_data b}->len"
                | TyStringLength(_,b) -> return' $"{tup_data b}->len-1"
                | TyOp(Global,[DLit (LitString x)]) -> global' x
                | TyOp(op,l) ->
                    let float_suffix = function
                        | DV(L(_,YPrim Float32T)) | DLit(LitFloat32 _) -> "f"
                        | _ -> ""
                    match op, l with
                    | Dyn,[a] -> tup_data a
                    | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                    | StringIndex, [a;b] -> sprintf "%s->ptr[%s]" (tup_data a) (tup_data b)
                    | StringSlice, [a;b;c] -> cstring(); cstring_slice(); sprintf "StringSlice(%s, %s, %s)" (tup_data a) (tup_data b) (tup_data c)
                    | StaticStringConcat, [a;b] -> cstring(); cstring_concat(); sprintf "StringConcat(%s, %s)" (tup_data a) (tup_data b)
                    | ArrayIndex, [DV(L(_,YArray t)) & a;b] ->
                        match tup_ty t with
                        | "void" -> "/* void array index */"
                        | _ -> sprintf "%s->ptr[%s]" (tup_data a) (tup_data b)
                    | ArrayIndexSet, [DV(L(_,YArray t)) as a;b;c] ->
                        let a',b',c' = tup_data a, tup_data b, tup_data c
                        match c' with
                        | "" -> "/* void array set */"
                        | _ -> $"AssignArray{(assign_array (tyvs_to_tys (carray t).tyvs)).tag}(&({a'}->ptr[{b'}]), {c'})"
                    // Math
                    | Add, [a;b] -> sprintf "%s + %s" (tup_data a) (tup_data b)
                    | Sub, [a;b] -> sprintf "%s - %s" (tup_data a) (tup_data b)
                    | Mult, [a;b] -> sprintf "%s * %s" (tup_data a) (tup_data b)
                    | Div, [a;b] -> sprintf "%s / %s" (tup_data a) (tup_data b)
                    | Mod, [a;b] -> sprintf "%s %% %s" (tup_data a) (tup_data b)
                    | Pow, [a;b] -> import "math.h"; sprintf "pow%s(%s,%s)" (float_suffix a) (tup_data a) (tup_data b)
                    | LT, [a;b] -> sprintf "%s < %s" (tup_data a) (tup_data b)
                    | LTE, [a;b] -> sprintf "%s <= %s" (tup_data a) (tup_data b)
                    | EQ, [a;b] when is_stringC a -> import "string.h"; sprintf "strcmp(%s->ptr, %s->ptr) == 0" (string_in_op a) (string_in_op b) // TODO: Optimize string structural comparison in the real_core
                    | NEQ, [a;b] when is_stringC a -> import "string.h"; sprintf "strcmp(%s->ptr, %s->ptr) != 0" (string_in_op a) (string_in_op b)
                    | GT, [a;b] when is_stringC a -> import "string.h"; sprintf "strcmp(%s->ptr, %s->ptr) > 0" (string_in_op a) (string_in_op b)
                    | GTE, [a;b] when is_stringC a -> import "string.h"; sprintf "strcmp(%s->ptr, %s->ptr) >= 0" (string_in_op a) (string_in_op b)
                    | EQ, [a;b] -> sprintf "%s == %s" (tup_data a) (tup_data b)
                    | NEQ, [a;b] -> sprintf "%s != %s" (tup_data a) (tup_data b)
                    | GT, [a;b] -> sprintf "%s > %s" (tup_data a) (tup_data b)
                    | GTE, [a;b] -> sprintf "%s >= %s" (tup_data a) (tup_data b)
                    | BoolAnd, [a;b] -> sprintf "%s && %s" (tup_data a) (tup_data b)
                    | BoolOr, [a;b] -> sprintf "%s || %s" (tup_data a) (tup_data b)
                    | BitwiseAnd, [a;b] -> sprintf "%s & %s" (tup_data a) (tup_data b)
                    | BitwiseOr, [a;b] -> sprintf "%s | %s" (tup_data a) (tup_data b)
                    | BitwiseXor, [a;b] -> sprintf "%s ^ %s" (tup_data a) (tup_data b)
                    | BitwiseComplement, [a] -> sprintf "~%s" (tup_data a)

                    | ShiftLeft, [a;b] -> sprintf "%s << %s" (tup_data a) (tup_data b)
                    | ShiftRight, [a;b] -> sprintf "%s >> %s" (tup_data a) (tup_data b)

                    | Neg, [x] -> sprintf "-%s" (tup_data x)
                    | Log, [x] -> import "math.h"; sprintf "log%s(%s)" (float_suffix x) (tup_data x)
                    | Exp, [x] -> import "math.h"; sprintf "exp%s(%s)" (float_suffix x) (tup_data x)
                    | Tanh, [x] -> import "math.h"; sprintf "tanh%s(%s)" (float_suffix x) (tup_data x)
                    | Sqrt, [x] -> import "math.h"; sprintf "sqrt%s(%s)" (float_suffix x) (tup_data x)
                    | Sin, [x] -> import "math.h"; sprintf "sin%s(%s)" (float_suffix x) (tup_data x)
                    | Cos, [x] -> import "math.h"; sprintf "cos%s(%s)" (float_suffix x) (tup_data x)
                    | NanIs, [x] -> import "math.h"; sprintf "isnan(%s)" (tup_data x)
                    | StdoutFlush, [] -> import "stdio.h"; "fflush(stdout)"
                    | MonotonicDelayMs, [duration] -> import "poll.h"; sprintf "poll(0, 0, %s)" (tup_data duration)
                    | Printf, [fmt;str] -> import "stdio.h"; sprintf "printf(%s, %s)" (string_in_op fmt) (string_in_op str)
                    | UnionTag, [DV(L(i,YUnion l)) as x] ->
                        match l.Item.layout with
                        | UHeap -> "->tag"
                        | UStack -> ".tag"
                        |> sprintf "v%i%s" i
                    | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported" op l.Length
                    |> return'
            and print_ordered_args s v = // Unlike C# for example, C keeps the struct fields in input order. To reduce padding, it is best to order the fields from largest to smallest.
                order_argsC v |> Array.iter (fun (L(i,x)) -> line s $"{tyv x} v{i};")
            and method_templ is_while fun_name : _ -> MethodRecC =
                jp (fun ((jp_body,key),i) ->
                    let args = codegenMethodKeyArgs key
                    match codegenMethodBody env "C" jp_body key with
                    | a, range, name -> {tag=i; free_vars=rdata_free_vars args; range=range; body=a; name=name}
                    ) (fun _ s_typ s_fun x ->
                    let ret_ty = tup_ty x.range
                    let args = x.free_vars |> Array.mapi (fun i (L(_,x)) -> $"{tyv x} v{i}") |> String.concat ", "
                    let fun_name = Option.defaultValue fun_name x.name
                    line s_fun (sprintf "%s %s%i(%s){" ret_ty fun_name x.tag args)
                    binds_start (if is_while then [||] else x.free_vars) (indent s_fun) x.body
                    line s_fun "}"
                    )
            and method_while : _ -> MethodRecC = method_templ true "method_while"
            and method : _ -> MethodRecC = method_templ false "method"
            and closure : _ -> ClosureRecC =
                jp (fun ((jp_body,key & (C(args,_,fun_ty))),i) ->
                    match fun_ty with
                    | YFun(domain,range,FT_Vanilla) ->
                        match codegenClosureBody env "C" jp_body key with
                        | domain_args, body -> {tag=i; free_vars=rdata_free_vars args; domain=domain; domain_args=data_free_vars domain_args; range=range; body=body}
                    | YFun(_,_,_)-> raise_codegen_error "Non-standard functions are not supported in the C backend."
                    | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."
                    ) (fun _ s_typ s_fun x ->
                    let i, range = x.tag, tup_ty x.range
                    line s_typ (sprintf "typedef struct Closure%i Closure%i;" i i)
                    line s_typ (sprintf "struct Closure%i {" i)
                    let _ =
                        let s_typ = indent s_typ
                        line s_typ $"int refc;"
                        line s_typ $"void (*decref_fptr)(Closure{i} *);"
                        match x.domain_args |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat ", " with
                        | "" -> $"{range} (*fptr)(Closure{i} *);"
                        | domain_args_ty -> $"{range} (*fptr)(Closure{i} *, {domain_args_ty});"
                        |> line s_typ
                        print_ordered_args s_typ x.free_vars
                    line s_typ "};"

                    line s_fun (sprintf "static inline void ClosureDecrefBody%i(Closure%i * x){" i i)
                    let _ =
                        let s_fun = indent s_fun
                        x.free_vars |> refc_change (fun i -> $"x->v{i}") -1 |> line' s_fun
                    line s_fun "}"

                    print_decref s_fun $"ClosureDecref{i}" $"Closure{i}" $"ClosureDecrefBody{i}"

                    match x.domain_args |> Array.map (fun (L(i,t)) -> $"{tyv t} v{i}") |> String.concat ", " with
                    | "" -> sprintf "%s ClosureMethod%i(Closure%i * x){" range i i
                    | domain_args -> sprintf "%s ClosureMethod%i(Closure%i * x, %s){" range i i domain_args
                    |> line s_fun
                    let _ =
                        let s_fun = indent s_fun
                        x.free_vars |> Array.map (fun (L(i,t)) -> $"{tyv t} v{i} = x->v{i};") |> line' s_fun
                        // A call consumes a reference to the closure, so ClosureDecref can free it here, and with
                        // it the captured values: take a reference to each first and let the body own them
                        // (released at their last use). Without it, `f` capturing an array and called through
                        // its last reference read the freed array (native_closure_array_capture: 40, not 42).
                        x.free_vars |> refc_change (fun i -> $"v{i}") 1 |> line' s_fun
                        line s_fun $"ClosureDecref{i}(x);"
                        binds_start (Array.append x.free_vars x.domain_args) s_fun x.body
                    line s_fun "}"

                    let fun_tag = (cfun (x.domain,x.range)).tag
                    let free_vars = x.free_vars |> Array.map (fun (L(i,t)) -> $"{tyv t} v{i}")
                    line s_fun (sprintf "Fun%i * ClosureCreate%i(%s){" fun_tag i (String.concat ", " free_vars))
                    let _ =
                        let s_fun = indent s_fun
                        line s_fun $"Closure{i} * x = {malloc}(sizeof(Closure{i}));"
                        line s_fun "x->refc = 1;"
                        line s_fun $"x->decref_fptr = ClosureDecref{i};"
                        line s_fun $"x->fptr = ClosureMethod{i};"
                        x.free_vars |> Array.map (fun (L(i,_)) -> $"x->v{i} = v{i};")  |> line' s_fun
                        line s_fun $"return (Fun{fun_tag} *) x;"
                    line s_fun "}"
                    )
            and cfun : _ -> CFunRecC =
                cfun' (fun _ s_typ s_fun x ->
                    let i, range = x.tag, tup_ty x.range
                    line s_typ $"typedef struct Fun{i} Fun{i};"
                    line s_typ (sprintf "struct Fun%i{" i)
                    let _ =
                        let s_typ = indent s_typ
                        line s_typ $"int refc;"
                        line s_typ $"void (*decref_fptr)(Fun{i} *);"
                        match x.domain_args_ty |> Array.map tyv |> String.concat ", " with
                        | "" -> $"{range} (*fptr)(Fun{i} *);"
                        | domain_args_ty -> $"{range} (*fptr)(Fun{i} *, {domain_args_ty});"
                        |> line s_typ
                    line s_typ "};"
                    )
            and tup : _ -> TupleRecC =
                tuple (fun _ s_typ s_fun x ->
                    let name = sprintf "Tuple%i" x.tag
                    line s_typ "typedef struct {"
                    x.tys |> Array.mapi (fun i x -> L(i,x)) |> print_ordered_args (indent s_typ)
                    line s_typ (sprintf "} %s;" name)

                    let args = x.tys |> Array.mapi (fun i x -> $"{tyv x} v{i}")
                    line s_fun (sprintf "static inline %s TupleCreate%i(%s){" name x.tag (String.concat ", " args))
                    let _ =
                        let s_fun = indent s_fun
                        line s_fun $"{name} x;"
                        Array.init args.Length (fun i -> $"x.v{i} = v{i};") |> line' s_fun
                        line s_fun $"return x;"
                    line s_fun "}"
                    )
            and assign_mut : _ -> TupleRecC =
                tuple (fun _ s_typ s_fun x ->
                    let tyvs = Array.mapi (fun i t -> L(i,t)) x.tys
                    let args = Array.mapi (fun i t -> let t = tyv t in $"{t} * a{i}, {t} b{i}") x.tys |> String.concat ", "
                    line s_fun (sprintf "static inline void AssignMut%i(%s){" x.tag args)
                    let _ =
                        let s_fun = indent s_fun
                        refc_change (fun i -> $"b{i}") 1 tyvs |> line' s_fun
                        refc_change (fun i -> $"*a{i}") -1 tyvs |> line' s_fun
                        Array.init tyvs.Length (fun i -> $"*a{i} = b{i};") |> line' s_fun
                    line s_fun "}"
                    )
            and assign_array : _ -> TupleRecC =
                tuple (fun _ s_typ s_fun x ->
                    let tyvs, t = Array.mapi (fun i t -> L(i,t)) x.tys, tup_ty_tys x.tys
                    line s_fun (sprintf "static inline void AssignArray%i(%s * a, %s b){" x.tag t t)
                    let _ =
                        let s_fun = indent s_fun
                        match tyvs with
                        | [||] -> raise_codegen_error "Compiler error: Void types not allowed in assign."
                        | [|t|] ->
                            refc_change (fun i -> "b") 1 tyvs |> line' s_fun
                            refc_change (fun i -> "*a") -1 tyvs |> line' s_fun
                            $"*a = b;" |> line s_fun
                        | _ ->
                            refc_change (fun i -> $"b.v{i}") 1 tyvs |> line' s_fun
                            refc_change (fun i -> $"a->v{i}") -1 tyvs |> line' s_fun
                            $"*a = b;" |> line s_fun
                    line s_fun "}"
                    )
            and layout_tmpl name : _ -> LayoutRecC =
                layout (fun _ s_typ s_fun (x : LayoutRecC) ->
                    let i = x.tag
                    let name' = sprintf "%s%i" name i

                    line s_typ "typedef struct {"
                    let _ =
                        let s_typ = indent s_typ
                        line s_typ "int refc;"
                        print_ordered_args s_typ x.free_vars
                    line s_typ (sprintf "} %s;" name')

                    line s_fun (sprintf "static inline void %sDecrefBody%i(%s * x){" name i name')
                    let _ =
                        let s_fun = indent s_fun
                        x.free_vars |> refc_change (fun i -> $"x->v{i}") -1 |> line' s_fun
                    line s_fun "}"

                    print_decref s_fun $"{name}Decref{i}" name' $"{name}DecrefBody{i}"

                    let args = x.free_vars |> Array.map (fun (L(i,x)) -> $"{tyv x} v{i}")
                    line s_fun (sprintf "%s * %sCreate%i(%s){" name' name i (String.concat ", " args))
                    let _ =
                        let s_fun = indent s_fun
                        line s_fun $"{name'} * x = {malloc}(sizeof({name'}));"
                        line s_fun "x->refc = 1;"
                        Array.init args.Length (fun i -> $"x->v{i} = v{i};") |> line' s_fun
                        line s_fun $"return x;"
                    line s_fun "}"
                    )
            and heap : _ -> LayoutRecC = layout_tmpl "Heap"
            and mut : _ -> LayoutRecC = layout_tmpl "Mut"
            and union_tmpl is_stack : Union -> UnionRecC =
                let inline map_iteri f x = Map.fold (fun i k v -> f i k v; i+1) 0 x |> ignore
                union (fun s_fwd s_typ s_fun x ->
                    let i = x.tag
                    match is_stack with
                    | true  -> line s_typ "typedef struct {"
                    | false ->
                        line s_fwd (sprintf "typedef struct UH%i UH%i;" i i)
                        line s_typ (sprintf "struct UH%i {" i)
                    let _ =
                        let s_typ = indent s_typ
                        match is_stack with
                        | true -> ()
                        | false -> line s_typ "int refc;"
                        line s_typ "int tag;"
                        line s_typ "union {"
                        let _ =
                            let s_typ = indent s_typ
                            map_iteri (fun tag (_, k) v ->
                                if Array.isEmpty v = false then
                                    line s_typ "struct {"
                                    print_ordered_args (indent s_typ) v
                                    line s_typ (sprintf "} case%i; // %s" tag k)
                                ) x.free_vars
                        line s_typ "};"
                    match is_stack with
                    | true  -> line s_typ (sprintf "} US%i;" i)
                    | false -> line s_typ "};"

                    let print_refc name typ q =
                        line s_fun (sprintf "static inline void %s(%s * x){" name typ)
                        let _ =
                            let s_fun = indent s_fun
                            line s_fun "switch (x->tag) {"
                            map_iteri (fun tag k v ->
                                let s_fun = indent s_fun
                                let refc = v |> refc_change (fun i -> $"x->case{tag}.v{i}") q
                                if refc.Length <> 0 then
                                    line s_fun (sprintf "case %i: {" tag)
                                    let _ =
                                        let s_fun = indent s_fun
                                        refc |> line' s_fun
                                        line s_fun "break;"
                                    line s_fun "}"
                                ) x.free_vars
                            line s_fun "}"
                        line s_fun "}"

                    match is_stack with
                    | true  ->
                        print_refc $"USIncrefBody{i}" $"US{i}" 1
                        print_refc $"USDecrefBody{i}" $"US{i}" -1
                    | false -> print_refc $"UHDecrefBody{i}" $"UH{i}" -1

                    match is_stack with
                    | true  ->
                        line s_fun (sprintf "void USIncref%i(US%i * x){ USIncrefBody%i(x); }" i i i)
                        line s_fun (sprintf "void USDecref%i(US%i * x){ USDecrefBody%i(x); }" i i i)
                    | false ->
                        line s_fwd (sprintf "void UHDecref%i(UH%i * x);" i i)
                        print_decref s_fun $"UHDecref{i}" $"UH{i}" $"UHDecrefBody{i}"

                    map_iteri (fun tag (_, k) v ->
                        let args = v |> Array.map (fun (L(i,t)) -> $"{tyv t} v{i}") |> String.concat ", "
                        if is_stack then
                            line s_fun (sprintf "US%i US%i_%i(%s) { // %s" i i tag args k)
                            let _ =
                                let s_fun = indent s_fun
                                line s_fun $"US{i} x;"
                                line s_fun $"x.tag = {tag};"
                                if v.Length <> 0 then
                                    v |> Array.map (fun (L(i,t)) -> $"x.case{tag}.v{i} = v{i};") |> line' s_fun
                                line s_fun "return x;"
                            line s_fun "}"
                        else
                            line s_fun (sprintf "UH%i * UH%i_%i(%s) { // %s" i i tag args k)
                            let _ =
                                let s_fun = indent s_fun
                                line s_fun $"UH{i} * x = {malloc}(sizeof(UH{i}));"
                                line s_fun $"x->tag = {tag};"
                                line s_fun "x->refc = 1;"
                                if v.Length <> 0 then
                                    v |> Array.map (fun (L(i,t)) -> $"x->case{tag}.v{i} = v{i};") |> line' s_fun
                                line s_fun $"return x;"
                            line s_fun "}"
                        ) x.free_vars
                    )
            and ustack : _ -> UnionRecC = union_tmpl true
            and uheap : _ -> UnionRecC = union_tmpl false
            and carray : _ -> ArrayRecC =
                carray' (fun _ s_typ s_fun x ->
                    let i, len_t, ptr_t = x.tag, prim size_t, tup_ty_tyvs x.tyvs
                    line s_typ "typedef struct {"
                    let _ =
                        let s_typ = indent s_typ
                        line s_typ "int refc;"
                        line s_typ $"{len_t} len;"
                        if ptr_t <> "void" then line s_typ $"{ptr_t} ptr[];" // flexible array member
                    line s_typ (sprintf "} Array%i;" i)


                    let print_body p s_fun q =
                        let refcs = x.tyvs |> refc_change (fun i -> if 1 < x.tyvs.Length then $"v.v{i}" else "v") q
                        if refcs.Length <> 0 then
                            p()
                            line s_fun (sprintf "for (%s i=0; i < len; i++){" len_t)
                            let _ =
                                let s_fun = indent s_fun
                                line s_fun $"{ptr_t} v = ptr[i];"
                                refcs |> line' s_fun
                            line s_fun "}"

                    line s_fun (sprintf "static inline void ArrayDecrefBody%i(Array%i * x){" i i)
                    let _ =
                        let s_fun = indent s_fun
                        print_body (fun () ->
                            line s_fun $"{len_t} len = x->len;"
                            line s_fun $"{ptr_t} * ptr = x->ptr;"
                            ) s_fun -1
                    line s_fun "}"

                    print_decref s_fun $"ArrayDecref{i}" $"Array{i}" $"ArrayDecrefBody{i}"

                    line s_fun (sprintf "Array%i * ArrayCreate%i(%s len, bool init_at_zero){" i i len_t)
                    let _ =
                        let s_fun = indent s_fun
                        match ptr_t with
                        | "void" -> line s_fun $"{len_t} size = sizeof(Array{i});"
                        | _ -> line s_fun $"{len_t} size = sizeof(Array{i}) + sizeof({ptr_t}) * len;"
                        line s_fun $"Array{i} * x = {malloc}(size);"
                        line s_fun "if (init_at_zero) { memset(x,0,size); }"
                        line s_fun "x->refc = 1;"
                        line s_fun "x->len = len;"
                        line s_fun "return x;"
                    line s_fun "}"

                    line s_fun (sprintf "Array%i * ArrayLit%i(%s len, %s * ptr){" i i len_t ptr_t)
                    let _ =
                        let s_fun = indent s_fun
                        line s_fun $"Array{i} * x = ArrayCreate{i}(len, false);"
                        if ptr_t <> "void" then
                            line s_fun $"memcpy(x->ptr, ptr, sizeof({ptr_t}) * len);"
                            print_body (fun () -> ()) (indent s_fun) 1
                        line s_fun "return x;"
                    line s_fun "}"
                    )
            and cstring : unit -> unit =
                cstring' (fun _ s_typ s_fun () ->
                    let char = YPrim CharT
                    let size_t, ptr_t, tag = prim size_t, tyv char, (carray char).tag
                    line s_typ $"typedef Array{tag} String;"

                    line s_fun "static inline void StringDecref(String * x){"
                    line (indent s_fun) $"return ArrayDecref{tag}(x);"
                    line s_fun "}"

                    line s_fun (sprintf "static inline String * StringLit(%s len, %s * ptr){" size_t ptr_t)
                    line (indent s_fun) $"return ArrayLit{tag}(len, ptr);"
                    line s_fun "}"
                    )
            and cstring_slice : unit -> unit =
                cstring_slice' (fun _ _ s_fun () ->
                    let tag = (carray (YPrim CharT)).tag
                    line s_fun "static inline String * StringSlice(String * value, int32_t from, int32_t to){"
                    let s_slice = indent s_fun
                    line s_slice "int32_t length = (int32_t)value->len - 1;"
                    line s_slice "if (from < 0 || from > length || to < from - 1 || to >= length) { abort(); }"
                    line s_slice "uint32_t slice_len = to < from ? 0u : (uint32_t)(to - from + 1);"
                    line s_slice "if (slice_len != 0u && ((((uint8_t)value->ptr[from] & 0xC0u) == 0x80u) || (to + 1 < length && (((uint8_t)value->ptr[to + 1] & 0xC0u) == 0x80u)))) { abort(); }"
                    line s_slice $"String * result = ArrayCreate{tag}(slice_len + 1, false);"
                    line s_slice "if (slice_len != 0u) { memcpy(result->ptr, value->ptr + from, slice_len); }"
                    line s_slice "result->ptr[slice_len] = '\\0';"
                    line s_slice "return result;"
                    line s_fun "}"
                    )
            and cstring_concat : unit -> unit =
                cstring_concat' (fun _ _ s_fun () ->
                    let tag = (carray (YPrim CharT)).tag
                    line s_fun "static inline String * StringConcat(String * left, String * right){"
                    let s_concat = indent s_fun
                    line s_concat "uint32_t left_len = left->len - 1;"
                    line s_concat "uint32_t right_len = right->len - 1;"
                    line s_concat $"String * result = ArrayCreate{tag}(left_len + right_len + 1, false);"
                    line s_concat "memcpy(result->ptr, left->ptr, left_len);"
                    line s_concat "memcpy(result->ptr + left_len, right->ptr, right_len + 1);"
                    line s_concat "return result;"
                    line s_fun "}"
                    )

            match binds_last_dataC x |> data_term_vars |> term_vars_to_tysC with
            | [|YPrim Int32T|] ->
                import "stdbool.h"
                import "stdint.h"
                import "stdio.h"
                import "stdlib.h"

                let main_defs = {text=StringBuilder(); indent=0}
                import "string.h" // for memcpy

                line main_defs (sprintf "%s main(){" (prim Int32T))
                binds_start [||] (indent main_defs) x
                line main_defs "}"

                let program = StringBuilder()

                globals |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
                fwd_dcls |> Seq.iter (fun x -> program.Append(x) |> ignore)
                types |> Seq.iter (fun x -> program.Append(x) |> ignore)
                functions |> Seq.iter (fun x -> program.Append(x) |> ignore)
                program.Append(main_defs.text).ToString()
            | _ ->
                raise_codegen_error "The return type of main in the C backend should be a 32-bit int."

#if SPIRAL_CORE_HOPAC
    /// ## CodegenCpp
    module CodegenCpp =
        // open System
        // open System.Text
        open System.Collections.Generic
    

        type backend_type =
            | Cuda of args : L<int,Ty>[] * binds : TypedBind[]
            | Cpp of binds : TypedBind[]
    

        type codegen_env =
            {
                globals : string ResizeArray
                fwd_dcls : System.Collections.Concurrent.ConcurrentQueue<string>
                types : System.Collections.Concurrent.ConcurrentQueue<string>
                functions : System.Collections.Concurrent.ConcurrentQueue<string>
                main_defs : string ResizeArray
                backend_name : string
                __device__ : string
            }
    

            static member Create(backend_name,__device__) =
                {
                    globals = ResizeArray()
                    fwd_dcls = System.Collections.Concurrent.ConcurrentQueue<string>()
                    types = System.Collections.Concurrent.ConcurrentQueue<string>()
                    functions = System.Collections.Concurrent.ConcurrentQueue<string>()
                    main_defs = ResizeArray()
                    backend_name = backend_name
                    __device__ = __device__
                }
    

        let backend_nameCpp = "Cpp"
        let private max_tag = 255uy
    

        let prim = function
            | Int8T -> "char"
            | Int16T -> "short"
            | Int32T -> "int"
            | Int64T -> "long long"
            | UInt8T -> "unsigned char"
            | UInt16T -> "unsigned short"
            | UInt32T -> "unsigned int"
            | UInt64T -> "unsigned long long"
            | Float32T -> "float"
            | Float64T -> "double"
            | BoolT -> "bool" // part of c++ standard
            | CharT -> "char"
            | StringT -> "const char *"
    

        /// Replaces the default types in the corelib.cuh library.
        let replace_default_types (default_env : DefaultEnv) (x : string) =
            let opts = System.Text.RegularExpressions.RegexOptions.Multiline
            System.Text.RegularExpressions.Regex.Replace(x, @"(^using default_int = )(.*?)(;)", $"$1{prim default_env.default_int}$3", opts)
            |> fun x -> System.Text.RegularExpressions.Regex.Replace(x, @"(^using default_uint = )(.*?)(;)", $"$1{prim default_env.default_uint}$3", opts)
    

        let is_stringCpp = function DV(L(_,YPrim StringT)) | DLit(LitString _) -> true | _ -> false
        let sizeof_tyvCpp = function
            | YPrim (Int64T | UInt64T | Float64T) -> 8
            | YPrim (Int32T | UInt32T | Float32T) -> 4
            | YPrim (Int16T | UInt16T) -> 2
            | YPrim (Int8T | UInt8T | CharT | BoolT) -> 1
            | _ -> 8
        let order_args v = v |> Array.sortWith (fun (L(_,t)) (L(_,t')) -> compare (sizeof_tyvCpp t') (sizeof_tyvCpp t))
        let lineCpp x s = if s <> "" then x.text.Append(' ', x.indent).AppendLine s |> ignore
        let lineCpp' x s = line x (String.concat " " s)
    

        type BindsReturnCpp =
            | BindsTailEnd
            | BindsLocal of TyV []
    

        let term_vars_to_tysCpp x = x |> HopacExtensions.S.map (function WV(L(_,t)) -> t | WLit x -> YPrim (lit_to_primitive_type x))
        let binds_last_dataCpp x = x |> Array.last |> function TyLocalReturnData(x,_) | TyLocalReturnOp(_,_,x) -> x | TyLet _ -> raise_codegen_error "Compiler error: Cannot find the return data of the last bind."
    

        type LayoutRecCpp = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>}
        type UnionRecCpp = {tag : int; free_vars : Map<int * string, TyV[]>; is_heap : bool}
        type MethodRecCpp = {tag : int; free_vars : TyV[]; range : Ty; body : TypedBind[]; name : string option}
        type ClosureRecCpp = {tag : int; free_vars : TyV[]; domain : Ty; range : Ty; funtype : FunType; body : TypedBind[]}
        type TupleRecCpp = {tag : int; tys : Ty []}
        type CFunRecCpp = {tag : int; domain : Ty; range : Ty; funtype : FunType}
    

        // Replaces the invalid symbols in Spiral method names for the C backend.
        let fix_method_name (x : string) = x.Replace('\'','_') + "_"
    

        let unroll_pop (s : Stack<int>) = if s.Count > 0 then s.Pop() else -1
        let unroll_peek (s : Stack<int>) = if s.Count > 0 then s.Peek() else -1
    

        let lit_stringCpp x =
            let strb = StringBuilder(String.length x + 2)
            strb.Append '"' |> ignore
            String.iter (function
                | '"' -> strb.Append "\\\""
                | '\b' -> strb.Append @"\b"
                | '\t' -> strb.Append @"\t"
                | '\n' -> strb.Append @"\n"
                | '\r' -> strb.Append @"\r"
                | '\\' -> strb.Append @"\\"
                | x -> strb.Append x
                >> ignore
                ) x
            strb.Append '"' |> ignore
            strb.ToString()
    

        let codegen' backend_handler (part_eval_env : PartEvalResult) (code_env : codegen_env) =
            let print show r =
                let s_typ_fwd = {text=StringBuilder(); indent=0}
                let s_typ = {text=StringBuilder(); indent=0}
                let s_fun = {text=StringBuilder(); indent=0}
                show s_typ_fwd s_typ s_fun r
                let f (a : System.Collections.Concurrent.ConcurrentQueue<string>) (b : CodegenEnv) =
                    let text = b.text.ToString()
                    if text <> "" then a.Enqueue(text)
                f code_env.fwd_dcls s_typ_fwd
                f code_env.types s_typ
                f code_env.functions s_fun
    

            let layout show =
                let dict' = System.Collections.Concurrent.ConcurrentDictionary<Ty, _>(HashIdentity.Structural)
                let dict = System.Collections.Concurrent.ConcurrentDictionary<Ty, _>(HashIdentity.Reference)
                let next_tag = CodegenTagAllocator()
                let f x : LayoutRecCpp =
                    match x with
                    | YLayout(x,_) ->
                        let x = part_eval_env.ty_to_data x
                        let a, b =
                            match x with
                            | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> HopacExtensions.S.collect snd, a
                            | _ -> data_free_vars x, Map.empty
                        {data=x; free_vars=a; free_vars_by_key=b; tag=next_tag.Next()}
                    | _ -> raise_codegen_error $"Compiler error: Expected a layout type (1).\nGot: %s{show_ty x}"
                fun x ->
                    match dict.TryGetValue x with
                    | true, r -> r
                    | _ ->
                        let mutable added = false
                        let r =
                            match dict'.TryGetValue x with
                            | true, r -> r
                            | _ ->
                                let r = f x
                                if dict'.TryAdd(x, r) then added <- true; r else dict'.[x]
                        dict.TryAdd(x, r) |> ignore
                        if added then print show r
                        r
    

            let union show =
                let dict = Collections.Concurrent.ConcurrentDictionary(HashIdentity.Reference)
                let f (a : Union) : UnionRecCpp =
                    let free_vars = a.Item.cases |> Map.map (fun _ -> part_eval_env.ty_to_data >> data_free_vars)
                    {free_vars=free_vars; tag=dict.Count; is_heap=a.Item.layout = UHeap}
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r
    

            let jp f show =
                let dict = System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Structural)
                let f x = f (x, dict.Count)
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r
    

            let tuple show =
                let dict = System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Structural)
                let f x = {tag=dict.Count; tys=x}
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r
    

            let cfun' show =
                let dict = System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Structural)
                let f (a : Ty, b : Ty, t : FunType) = {tag=dict.Count; domain=a; range=b; funtype=t}
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r
    

            let args x = x |> HopacExtensions.S.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "
    

            let tmp =
                let mutable i = 0u
                fun () -> let x = i in i <- i + 1u; x
    

            let global' =
                let has_added = HashSet code_env.globals
                fun x -> if preservesDuplicateGlobalFragment x || has_added.Add(x) then code_env.globals.Add x
    

            let import x = global' $"#include <{x}>"
            let import' x = global' $"#include \"{x}\""
    

            let tyvs_to_tys (x : TyV []) = HopacExtensions.S.map (fun (L(i,t)) -> t) x
    

            let rec binds_start (s : CodegenEnv) (x : TypedBind []) = binds (Stack()) s BindsTailEnd x
            and return_local s ret (x : string) =
                match ret with
                | [||] -> line s $"{x};"
                | [|L(i,_)|] -> line s $"v{i} = {x};"
                | ret ->
                    let tmp_i = tmp()
                    line s $"{tup_ty_tyvs ret} tmp{tmp_i} = {x};"
                    HopacExtensions.S.mapi (fun i (L(i',_)) -> $"v{i'} = tmp{tmp_i}.v{i};") ret |> lineCpp' s
            and get_layout_rec lay a =
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> stack_mut a
            and binds (unroll : Stack<int>) (s : CodegenEnv) (ret : BindsReturnCpp) (stmts : TypedBind []) =
                let tup_destruct (a,b) =
                    HopacExtensions.S.map2 (fun (L(i,_)) b ->
                        match b with
                        | WLit b -> $"v{i} = {lit b};"
                        | WV (L(i',_)) -> $"v{i} = v{i'};"
                        ) a b
                Array.forall (fun x ->
                    match x with
                    | TyLet(d,trace,a) ->
                        try let d = data_free_vars d
                            let decl_vars () = HopacExtensions.S.map (fun (L(i,t)) -> $"{tyv t} v{i};") d
                            let layout_index layout (x'_i : int) (x' : TyV []) =
                                match layout with
                                | Heap | HeapMutable -> HopacExtensions.S.map2 (fun (L(i,t)) (L(i',_)) -> $"{tyv t} & v{i} = v{x'_i}.base->v{i'};") d x' |> lineCpp' s
                                | StackMutable -> HopacExtensions.S.map2 (fun (L(i,t)) (L(i',_)) -> $"{tyv t} & v{i} = v{x'_i}.v{i'};") d x' |> lineCpp' s
                            match a with
                            | TyToLayout(a,YLayout(_,StackMutable) & b) ->
                                match d with
                                | [|L(i,YLayout(_,StackMutable))|] -> // For the regular arrays.
                                    let tag = (stack_mut b).tag
                                    line s $"StackMut{tag} v{i}{{{args' a}}};"
                                    true
                                | _ ->
                                    raise_codegen_error "Compiler error: Expected a stack mutable layout type."
                            | TyLayoutIndexAll(x) ->
                                match x with
                                | L(i,YLayout(_,lay) & a) -> (get_layout_rec lay a).free_vars |> layout_index lay i
                                | _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
                                true
                            | TyLayoutIndexByKey(x,key) ->
                                match x with
                                | L(i,YLayout(_,lay) & a) -> (get_layout_rec lay a).free_vars_by_key |> Map.pick (fun (_, k') v' -> if LayoutFieldNameIdOps.matchesText key k' then Some v' else None) |> layout_index lay i
                                | _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index by key to be a layout type."
                                true
                            | TyMacro a ->
                                let m = a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup_data x) | CMType x -> tup_ty x | CMTypeLit x -> type_lit x) |> String.concat ""
                                match tyMacroControlFor m with
                                | TyMacroPragma ->
                                    line s m
                                    true
                                | TyMacroBreak ->
                                    line s "break;"
                                    false
                                | TyMacroReturn ->
                                    line s $"{m};"
                                    false
                                | TyMacroBody ->
                                    let q = m.Split("\\v")
                                    if q.Length = 1 then
                                        decl_vars() |> lineCpp' s
                                        return_local s d m
                                        true
                                    else
                                        if d.Length = q.Length-1 then
                                            let w = StringBuilder(m.Length+8)
                                            let tag (L(i,_)) = i : int
                                            HopacExtensions.S.iteri (fun i v -> w.Append(q.[i]).Append('v').Append(tag v) |> ignore) d
                                            w.Append(q.[d.Length]).Append(';').ToString() |> line s
                                            true
                                        else
                                            raise_codegen_error "The special \\v macro requires the same number of free vars in its binding as there are \\v in the code."
                            | TyArrayLiteral(a,b') ->
                                let inits = List.map tup_data b' |> String.concat "," |> sprintf "{%s}"
                                match d with
                                | [|L(i,YArray t)|] -> // For the regular arrays.
                                    line s $"%s{tup_ty t} v{i}[] = %s{inits};"
                                    true
                                | _ ->
                                    raise_codegen_error "Compiler error: Expected a single variable on the left side of an array literal op."
                            | TyArrayCreate(a,b) ->
                                match d with
                                | [|L(i,YArray t)|] ->
                                    match tup_ty t with
                                    | "void" -> line s "/* void array create */"
                                    | t -> line s $"{t} v{i}[{tup_data b}];"
                                    true
                                | _ -> raise_codegen_error "Compiler error: Expected a single variable on the left side of an array create op."
                            | TyJoinPoint(JPClosure(a,b),b') ->
                                match d with
                                | [|L(i,_)|] ->
                                    let x = closure (a,b)
                                    match x.funtype with
                                    | FT_Pointer ->
                                        let y = cfun (x.domain,x.range,x.funtype)
                                        line s $"Fun{y.tag} v{i} = FunPointerMethod{x.tag};"
                                    | FT_Vanilla ->
                                        let args = args b'
                                        line s $"Closure{x.tag} v{i}{{{args}}};"
                                    | FT_Closure ->
                                        let y = cfun (x.domain,x.range,x.funtype)
                                        let args = args b'
                                        line s $"Fun{y.tag} v{i}{{new Closure{x.tag}{{{args}}}}};"
                                    true
                                | _ -> raise_codegen_error "error[EJPX005]: internal compiler error\n  |\n  = expected: single variable LHS in closure join point\n  help: capture the stack trace and the offending AST node.\n"
                            | _ ->
                                decl_vars() |> lineCpp' s
                                op unroll s (BindsLocal d) a
                                true
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    | TyLocalReturnOp(trace,a,_) ->
                        try op unroll s ret a
                            true
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    | TyLocalReturnData(d,trace) ->
                        try match ret with
                            | BindsLocal l -> lineCpp' s (tup_destruct (l,data_term_vars d))
                            | BindsTailEnd -> line s $"return {tup_data d};"
                            true
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    ) stmts
                |> ignore
            and show_w = function WV(L(i,_)) -> sprintf "v%i" i | WLit a -> lit a
            and args' b = data_term_vars b |> HopacExtensions.S.map show_w |> String.concat ", "
            and tup_term_vars x =
                let args = HopacExtensions.S.map show_w x |> String.concat ", "
                if 1 < x.Length then sprintf "Tuple%i{%s}" (tup (term_vars_to_tysCpp x)).tag args else args
            and tup_data x = tup_term_vars (data_term_vars x)
            and tup_ty_tys = function
                | [||] -> "void"
                | [|x|] -> tyv x
                | x -> sprintf "Tuple%i" (tup x).tag
            and tup_ty_tyvs (x : TyV []) = tup_ty_tys (tyvs_to_tys x)
            and tup_ty x = part_eval_env.ty_to_data x |> data_free_vars |> tup_ty_tyvs
            and tyv = function
                | YUnion a ->
                    match a.Item.layout with
                    | UStack -> sprintf "Union%i" (unions a).tag
                    | UHeap -> sprintf "sptr<Union%i>" (unions a).tag
                | YLayout(_,lay) as a ->
                    match lay with
                    | Heap -> sprintf "sptr<Heap%i>" (heap a).tag
                    | HeapMutable -> sprintf "sptr<Mut%i>" (mut a).tag
                    | StackMutable -> sprintf "StackMut%i &" (stack_mut a).tag
                | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                    match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameCpp then Some v else None) with
                    | Some x -> tup_ty x
                    | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{code_env.backend_name}' field."
                | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_lit a) |> String.concat ""
                | YPrim a -> prim a
                | YArray a -> sprintf "%s *" (tup_ty a)
                | YFun(a,b,t) -> $"Fun%i{(cfun (a,b,t)).tag}"
                | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
                | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
                | a -> raise_codegen_error (sprintf "Compiler error: Type not supported in the codegen.\nGot: %A" a)
            and lit = function
                | LitInt8 x -> sprintf "%i" x
                | LitInt16 x -> sprintf "%i" x
                | LitInt32 x -> sprintf "%i" x
                | LitInt64 x -> sprintf "%ill" x
                | LitUInt8 x -> sprintf "%iu" x
                | LitUInt16 x -> sprintf "%iu" x
                | LitUInt32 x -> sprintf "%iu" x
                | LitUInt64 x -> sprintf "%iull" x
                | LitFloat32 x ->
                    if x = infinityf then "1.0f / 0.0f"
                    elif x = -infinityf then "-1.0f / 0.0f"
                    elif Single.IsNaN x then "0.0f / 0.0f"
                    else x.ToString("R") |> add_dec_point |> sprintf "%sf"
                | LitFloat64 x ->
                    if x = infinity then "1.0 / 0.0"
                    elif x = -infinity then "-1.0 / 0.0"
                    elif Double.IsNaN x then "0.0 / 0.0"
                    else x.ToString("R") |> add_dec_point
                | LitString x -> lit_stringCpp x
                | LitChar x ->
                    match x with
                    | '\b' -> @"\b"
                    | '\n' -> @"\n"
                    | '\t' -> @"\t"
                    | '\r' -> @"\r"
                    | '\\' -> @"\\"
                    | x -> string x
                    |> sprintf "'%s'"
                | LitBool x -> if x then "true" else "false" // true and false are defined in stddef.h
            and type_lit = function
                | YLit x -> lit x
                | YSymbol x -> x
                | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."
            and op (unroll : Stack<int>)s (ret : BindsReturnCpp) a =
                let binds a b = binds unroll a b
                let return' (x : string) =
                    match ret with
                    | BindsLocal ret -> return_local s ret x
                    | BindsTailEnd -> line s $"return {x};"
                let jp (a,b') =
                    let args = args b'
                    match a with
                    | JPMethod(a,b) ->
                        let x = method (a,b)
                        let method_name = Option.defaultValue "method_" x.name
                        $"{method_name}{x.tag}({args})"
                    | JPClosure(a,b) ->
                        let x = closure (a,b)
                        match x.funtype with
                        | FT_Vanilla -> raise_codegen_error "Compiler error: The vanilla function case should have been blocked elsewhere."
                        | FT_Pointer -> $"FunPointerMethod{x.tag}"
                        | FT_Closure -> $"csptr<ClosureBase{x.tag}>{{new Closure{x.tag}{{{args}}}}}"
                match a with
                | TyMacro _ -> raise_codegen_error "Macros are supposed to be taken care of in the `binds` function."
                | TyIf(cond,tr,fl) ->
                    line s (sprintf "if (%s){" (tup_data cond))
                    binds (indent s) ret tr
                    line s "} else {"
                    binds (indent s) ret fl
                    line s "}"
                | TyJoinPoint(a,args) -> return' (jp (a, args))
                | TyBackend(a,b,c) -> line s $"auto kernel = {backend_handler (a,b,c)};"
                | TyWhile(a,b) ->
                    let cond =
                        match a with
                        | JPMethod(a,b),b' -> sprintf "while_method_%i(%s)" (method_while (a,b)).tag (args b')
                        | _ -> raise_codegen_error "Expected a regular method rather than closure create in the while conditional."
                    match unroll_peek unroll with
                    | -1 -> ()
                    | 0 -> line s $"#pragma unroll"
                    | i -> line s $"#pragma unroll %i{i}"
                    line s (sprintf "while (%s){" cond)
                    binds (indent s) (BindsLocal [||]) b
                    line s "}"
                | TyDo a ->
                    line s "do"
                    binds (indent s) ret a
                | TyIndent a ->
                    binds (indent s) ret a
                | TyIntSwitch(L(v_i,_),on_succ,on_fail) ->
                    line s (sprintf "switch (v%i) {" v_i)
                    let _ =
                        let s = indent s
                        HopacExtensions.S.iteri (fun i x ->
                            line s (sprintf "case %i: {" i)
                            binds (indent s) ret x
                            line (indent s) "break;"
                            line s "}"
                            ) on_succ
                        line s "default: {"
                        binds (indent s) ret on_fail
                        line s "}"
                    line s "}"
                | TyUnionUnbox(is,x,on_succs,on_fail) ->
                    let case_tags = x.Item.tags
                    let acs = match x.Item.layout with UHeap -> ".base->" | UStack -> "."
                    let head = List.head is |> fun (L(i,_)) -> $"v{i}{acs}tag"
                    List.pairwise is
                    |> List.map (fun (L(i,_), L(i',_)) -> $"v{i}{acs}tag == v{i'}{acs}tag")
                    |> String.concat " && "
                    |> function "" -> head | x -> $"{x} ? {head} : {max_tag}"
                    |> sprintf "switch (%s) {" |> line s
                    let _ =
                        let s = indent s
                        Map.iter (fun k (a,b) ->
                            let union_i = case_tags.[k]
                            line s (sprintf "case %i: { // %s" union_i (UnionTagIdOps.text k))
                            List.iter2 (fun (L(data_i,_)) a ->
                                let a, s = data_free_vars a, indent s
                                let qs = ResizeArray(a.Length)
                                HopacExtensions.S.iteri (fun field_i (L(v_i,t) as v) ->
                                    qs.Add $"{tyv t} v{v_i} = v{data_i}{acs}case{union_i}.v{field_i};"
                                    ) a
                                lineCpp' s qs
                                ) is a
                            binds (indent s) ret b
                            line (indent s) "break;"
                            line s "}"
                            ) on_succs
                        line s "default: {"
                        let _ =
                            let s = indent s
                            match on_fail with
                            | Some b -> binds s ret b
                            | None -> line s "assert(\"Invalid tag.\" && false); __trap();"
                        line s "}"
                    line s "}"
                | TyUnionBox(a,b,c') ->
                    let c = c'.Item
                    let i = c.tags.[a]
                    let vars = args' b
                    let tag = (unions c').tag
                    match c.layout with
                    | UHeap -> $"sptr<Union{tag}>{{new Union{tag}{{Union{tag}_{i}{{{vars}}}}}}}"
                    | UStack -> $"Union{tag}{{Union{tag}_{i}{{{vars}}}}}"
                    |> return'
                | TyToLayout(a,b) ->
                    match b with
                    | YLayout(_,layout) ->
                        match layout with
                        | Heap ->
                            let tag = (heap b).tag
                            $"sptr<Heap{tag}>{{new Heap{tag}{{{args' a}}}}}"
                        | HeapMutable ->
                            let tag = (mut b).tag
                            $"sptr<Mut{tag}>{{new Mut{tag}{{{args' a}}}}}"
                        | StackMutable -> raise_codegen_error "The Cpp backend doesn't support stack mutable layout types."
                    | _ -> raise_codegen_error "Compiler error: Expected a layout type (2)."
                    |> return'
                | TyLayoutIndexAll(x) -> raise_codegen_error "Compiler error: TyLayoutIndexAll should have been taken care of in TyLet."
                | TyLayoutIndexByKey(x,key) -> raise_codegen_error "Compiler error: TyLayoutIndexByKey should have been taken care of in TyLet."
                | TyLayoutMutableSet(L(i,t),b,c) ->
                    match t with
                    | YLayout(_,lay) ->
                        match lay with
                        | HeapMutable ->
                            let a =
                                List.fold
                                    (fun s k ->
                                        match s with
                                        | DRecord l -> l |> Map.pick (fun (_, k') v' -> if LayoutFieldNameIdOps.matchesText k k' then Some v' else None)
                                        | _ -> raise_codegen_error "Compiler error: Expected a record.")
                                    (mut t).data b
                            HopacExtensions.S.map2 (fun (L(i',_)) b -> $"v{i}.base->v{i'} = {show_w b};") (data_free_vars a) (data_term_vars c)
                        | StackMutable ->
                            let a = List.fold (fun s k -> match s with DRecord l -> l |> Map.pick (fun (_, k') v' -> if LayoutFieldNameIdOps.matchesText k k' then Some v' else None) | _ -> raise_codegen_error "Compiler error: Expected a record.") (stack_mut t).data b
                            HopacExtensions.S.map2 (fun (L(i',_)) b -> $"v{i}.v{i'} = {show_w b};") (data_free_vars a) (data_term_vars c)
                        | Heap -> raise_codegen_error "Compiler error (1): TyLayoutMutableSet should only be HeapMutable or StackMutable."
                    | _ -> raise_codegen_error "Compiler error (2): TyLayoutMutableSet should only be HeapMutable or StackMutable."
                    |> String.concat " " |> line s
                | TyArrayLiteral(a,b') -> raise_codegen_error "Compiler error: TyArrayLiteral should have been taken care of in TyLet."
                | TyArrayCreate(a,b) ->  raise_codegen_error "Compiler error: TyArrayCreate should have been taken care of in TyLet."
                | TyFailwith(a,b) ->
                    let string_in_op = function DLit (LitString b) -> lit_stringCpp b | b -> raise_codegen_error "In the Cuda backend, the exception string must be a literal."
                    let fmt = @"%s\n"
                    line s $"printf(\"{fmt}\", {string_in_op b});"
                    line s "__trap();" // TODO: Print out the error traces as well.
                | TyConv(a,b) -> return' $"({tyv a}){tup_data b}"
                | TyApply(L(i,_),b) ->
                    let rec loop = function
                        | DPair(a,b) -> tup_data a :: loop b
                        | a -> [tup_data a]
                    let args = loop b |> List.filter ((<>) "") |> String.concat ", "
                    $"v{i}({args})" |> return'
                | TyArrayLength(_,b) -> raise_codegen_error "Array length is not supported in the Cuda C++ backend as they are bare pointers."
                | TyStringLength(_,b) -> raise_codegen_error "String length is not supported in the Cuda C++ backend."
                | TySizeOf t -> return' $"sizeof({tup_ty t})"
                | TyOp(Global,[DLit (LitString x)]) -> global' x
                | TyOp(PragmaUnrollPush,[DLit (LitInt32 x)]) -> unroll.Push(x); line s $"// Pushing the loop unrolling to: {x}"
                | TyOp(PragmaUnrollPop,[]) -> line s $"// Poping the loop unrolling to: {unroll_pop unroll}"
                | TyOp(op,l) ->
                    match op, l with
                    | Dyn,[a] -> tup_data a
                    | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                    | StringIndex, [a;b] -> sprintf "%s[%s]" (tup_data a) (tup_data b)
                    | StringSlice, [a;b;c] -> raise_codegen_error "String slice is not supported natively in the C backend. Use a library implementation instead."
                    | ArrayIndex, [DV(L(_,YArray t)) & a;b] ->
                        match tup_ty t with
                        | "void" -> "/* void array index */"
                        | _ -> sprintf "%s[%s]" (tup_data a) (tup_data b)
                    | ArrayIndexSet, [DV(L(_,YArray t)) as a;b;c] ->
                        let a',b',c' = tup_data a, tup_data b, tup_data c
                        match c' with
                        | "" -> "/* void array set */"
                        | _ -> $"{a'}[{b'}] = {c'}"
                    // Math
                    | Add, [a;b] -> sprintf "%s + %s" (tup_data a) (tup_data b)
                    | Sub, [a;b] -> sprintf "%s - %s" (tup_data a) (tup_data b)
                    | Mult, [a;b] -> sprintf "%s * %s" (tup_data a) (tup_data b)
                    | Div, [a;b] -> sprintf "%s / %s" (tup_data a) (tup_data b)
                    | Mod, [a;b] -> sprintf "%s %% %s" (tup_data a) (tup_data b)
                    | Pow, [a;b] -> sprintf "pow(%s,%s)" (tup_data a) (tup_data b)
                    | LT, [a;b] -> sprintf "%s < %s" (tup_data a) (tup_data b)
                    | LTE, [a;b] -> sprintf "%s <= %s" (tup_data a) (tup_data b)
                    | EQ, [a;b] | NEQ, [a;b] | GT, [a;b] | GTE, [a;b] when is_stringCpp a -> raise_codegen_error "String comparison operations are not supported in the Cuda C++ backend."
                    | EQ, [a;b] -> sprintf "%s == %s" (tup_data a) (tup_data b)
                    | NEQ, [a;b] -> sprintf "%s != %s" (tup_data a) (tup_data b)
                    | GT, [a;b] -> sprintf "%s > %s" (tup_data a) (tup_data b)
                    | GTE, [a;b] -> sprintf "%s >= %s" (tup_data a) (tup_data b)
                    | BoolAnd, [a;b] -> sprintf "%s && %s" (tup_data a) (tup_data b)
                    | BoolOr, [a;b] -> sprintf "%s || %s" (tup_data a) (tup_data b)
                    | BitwiseAnd, [a;b] -> sprintf "%s & %s" (tup_data a) (tup_data b)
                    | BitwiseOr, [a;b] -> sprintf "%s | %s" (tup_data a) (tup_data b)
                    | BitwiseXor, [a;b] -> sprintf "%s ^ %s" (tup_data a) (tup_data b)
                    | BitwiseComplement, [a] -> sprintf "~%s" (tup_data a)
    

                    | ShiftLeft, [a;b] -> sprintf "%s << %s" (tup_data a) (tup_data b)
                    | ShiftRight, [a;b] -> sprintf "%s >> %s" (tup_data a) (tup_data b)
    

                    | Neg, [x] -> sprintf "-%s" (tup_data x)
                    | Log, [x] -> sprintf "log(%s)" (tup_data x)
                    | Exp, [x] -> sprintf "exp(%s)" (tup_data x)
                    | Tanh, [x] -> sprintf "tanh(%s)" (tup_data x)
                    | Sqrt, [x] -> sprintf "sqrt(%s)" (tup_data x)
                    | Sin, [x] -> sprintf "sin(%s)" (tup_data x)
                    | Cos, [x] -> sprintf "cos(%s)" (tup_data x)
                    | NanIs, [x] -> sprintf "isnan(%s)" (tup_data x)
                    | StdoutFlush, [] ->
                        import "cstdio"
                        "std::fflush(stdout)"
                    | MonotonicDelayMs, [duration] ->
                        import "thread"
                        import "chrono"
                        sprintf "std::this_thread::sleep_for(std::chrono::milliseconds(%s))" (tup_data duration)
                    | Printf, [fmt;str] ->
                        match args' str with
                        | "" -> sprintf "printf(%s)" (tup_data fmt)
                        | str -> sprintf "printf(%s,%s)" (tup_data fmt) str
                    | UnionTag, [DV(L(i,YUnion l)) as x] ->
                        match l.Item.layout with
                        | UHeap -> ".base->tag"
                        | UStack -> ".tag"
                        |> sprintf "v%i%s" i
                    | _ -> raise_codegen_error <| sprintf "Compiler error: %s with %i args not supported" (opStableText op) l.Length
                    |> return'
            and print_ordered_args s v = // Unlike C# for example, C keeps the struct fields in input order. To reduce padding, it is best to order the fields from largest to smallest.
                order_args v |> HopacExtensions.S.iter (fun (L(i,x)) -> line s $"{tyv x} v{i};")
            and method_template is_while : _ -> MethodRecCpp =
                jp (fun ((jp_body,key & (C(args,_,_))),i) ->
                    let jp_dict,_,_ = part_eval_env.join_point_method.[jp_body]
                    let a, range, name =
                        jpBodyCellAwait jp_dict.[key]
                        |> jpMethodBodyCellReadyForBackend "Cpp"
                    {tag=i; free_vars=rdata_free_vars args; range=range; body=a; name=Option.map fix_method_name name}
                    ) (fun s_fwd s_typ s_fun x ->
                    let ret_ty = tup_ty x.range
                    let fun_name = Option.defaultValue (if is_while then "while_method_" else "method_") x.name
                    let args = x.free_vars |> HopacExtensions.S.mapi (fun i (L(_,x)) -> $"{tyv x} v{i}") |> String.concat ", "
                    let inline_ =
                        if is_while then "inline "
                        else
                            line s_fwd $"{code_env.__device__}{ret_ty} {fun_name}{x.tag}({args});"
                            if fun_name.StartsWith "noinline" then "__noinline__ " else ""
                    line s_fun $"{code_env.__device__}{inline_}{ret_ty} {fun_name}{x.tag}({args}){{"
                    binds_start (indent s_fun) x.body
                    line s_fun "}"
                    )
            and method : _ -> MethodRecCpp = method_template false
            and method_while : _ -> MethodRecCpp = method_template true
            and closure_args domain count_start =
                let rec loop = function
                    | YPair(a,b) -> a :: loop b
                    | a -> [a]
                let mutable count = count_start
                let rename x = HopacExtensions.S.map (fun (L(i,t)) -> let x = L(count,t) in count <- count+1; x) x
                let mutable i = 0
                loop domain |> List.choose (fun x ->
                    let n = part_eval_env.ty_to_data x |> data_free_vars
                    let x = if n.Length <> 0 then Some(i, tup_ty_tyvs n, n |> rename) else None
                    i <- i+1
                    x
                    )
            and closure : _ -> ClosureRecCpp =
                jp (fun ((jp_body,key & (C(args,_,fun_ty))),i) ->
                    match fun_ty with
                    | YFun(domain,range,t) ->
                        let jp_dict,_,_ = part_eval_env.join_point_closure.[jp_body]
                        let _, body =
                            jpBodyCellAwait jp_dict.[key]
                            |> jpClosureBodyCellReadyForBackend "Cpp"
                        {tag=i; domain=domain; range=range; body=body; free_vars=rdata_free_vars args; funtype=t}
                    | _ -> raise_codegen_error """error[EJPX004]: internal compiler error
      |
      = unexpected type in closure join point
      help: capture the stack trace and the inferred/expected types for the closure join point.
    """
                    ) (fun _ s_typ s_fun x ->
                    let i, range = x.tag, tup_ty x.range
                    let closure_args = closure_args x.domain x.free_vars.Length
                    let args = closure_args |> List.map (fun (i,ty,_) -> $"{ty} tup{i}") |> String.concat ", "
                    let print_body s_fun =
                        let s_fun = indent s_fun
                        x.free_vars |> HopacExtensions.S.map (fun (L(i,t)) ->
                            $"{tyv t} & v{i} = this->v{i};"
                            ) |> String.concat " " |> line s_fun
                        closure_args |> List.map (fun (i'',_,vars) ->
                            HopacExtensions.S.mapi (fun i' (L(i,t)) ->
                                if vars.Length <> 1 then $"{tyv t} v{i} = tup{i''}.v{i'};"
                                else $"{tyv t} v{i} = tup{i''};"
                                ) vars
                            |> String.concat " "
                            ) |> String.concat " " |> line s_fun
                        binds_start s_fun x.body
                    match x.funtype with
                    | FT_Pointer ->
                        $"{code_env.__device__}{range} FunPointerMethod{i}({args}){{" |> line s_fun
                        print_body s_fun
                        line s_fun "}"
                    | FT_Vanilla | FT_Closure ->
                        match x.funtype with
                        | FT_Pointer -> raise_codegen_error "Compiler error: The pointer case have been taken care of (1)."
                        | FT_Closure ->
                            let i' = (cfun (x.domain,x.range,x.funtype)).tag
                            line s_typ $"struct Closure{i} : public ClosureBase{i'} {{"
                        | FT_Vanilla ->
                            line s_typ $"struct Closure{i} {{"
                        let () =
                            let s_typ = indent s_typ
                            let () = // free vars in the environment
                                print_ordered_args s_typ x.free_vars
                            let () = // operator()
                                match x.funtype with
                                | FT_Pointer -> raise_codegen_error "Compiler error: The pointer case have been taken care of (2)."
                                | FT_Vanilla -> line s_typ $"{code_env.__device__}{range} operator()({args}){{"
                                | FT_Closure -> line s_typ $"{code_env.__device__}{range} operator()({args}) override {{"
                                print_body s_typ
                                line s_typ "}"
                            let () = // constructor
                                match x.free_vars with
                                | [||] -> ()
                                | _ ->
                                    let constructor_args =
                                        x.free_vars
                                        |> HopacExtensions.S.map (fun (L(i,t)) -> $"{tyv t} _v{i}")
                                        |> String.concat ", "
                                    let initializer_args =
                                        x.free_vars
                                        |> HopacExtensions.S.map (fun (L(i,t)) -> $"v{i}(_v{i})")
                                        |> String.concat ", "
                                    line s_typ $"{code_env.__device__}Closure{i}({constructor_args}) : {initializer_args} {{ }}"
                            let () = // destructor
                                match x.funtype with
                                | FT_Pointer | FT_Vanilla -> ()
                                | FT_Closure ->
                                    let destructor_calls =
                                        x.free_vars
                                        |> HopacExtensions.S.choose (fun (L(i,t)) ->
                                            if is_numeric t || is_char t then None else
                                            Some $"destroy(v{i});"
                                            )
                                        |> String.concat " "
                                    line s_typ $"{code_env.__device__}~Closure{i}() override {{ {destructor_calls} }}"
                            ()
                        line s_typ "};"
                    )
            and cfun : _ -> CFunRecCpp =
                cfun' (fun s_fwd s_typ s_fun x ->
                    let i, range = x.tag, tup_ty x.range
                    let domain_args_ty = closure_args x.domain 0 |> List.map (fun (_,ty,_) -> ty) |> String.concat ", "
                    match x.funtype with
                    | FT_Vanilla -> raise_codegen_error "Regular functions do not have a composable type in the Cuda backend. Consider explicitly converting them to either closures or pointers using `to_closure` or `to_fptr` if you want to pass them through boundaries."
                    | FT_Pointer -> line s_fwd $"typedef {range} (* Fun{i})({domain_args_ty});"
                    | FT_Closure ->
                        line s_fwd $"struct ClosureBase{i} {{ int refc{{0}}; {code_env.__device__}virtual {range} operator()({domain_args_ty}) = 0; {code_env.__device__}virtual ~ClosureBase{i}(){{}}; }};"
                        line s_fwd $"typedef csptr<ClosureBase{i}> Fun{i};"
                    )
            and tup : _ -> TupleRecCpp =
                tuple (fun s_fwd s_typ s_fun x ->
                    let name = sprintf "Tuple%i" x.tag
                    line s_fwd $"struct {name};"
                    line s_typ $"struct {name} {{"
                    x.tys |> HopacExtensions.S.mapi (fun i x -> L(i,x)) |> print_ordered_args (indent s_typ)
                    let concat x = String.concat ", " x
                    let args = x.tys |> HopacExtensions.S.mapi (fun i x -> $"{tyv x} t{i}")
                    let con_init = x.tys |> HopacExtensions.S.mapi (fun i x -> $"v{i}(t{i})")
                    if args.Length <> 0 then
                        line (indent s_typ) $"{code_env.__device__}{name}() = default;"
                        line (indent s_typ) $"{code_env.__device__}{name}({concat args}) : {concat con_init} {{}}"
                    line s_typ "};"
                    )
            and unions : _ -> UnionRecCpp =
                let map_iteri f x = Map.fold (fun i k v -> f i k v; i+1) 0 x |> ignore
                union (fun s_fwd s_typ s_fun x ->
                    let i = x.tag
                    line s_fwd $"struct Union{i};" // Forward declaration for the union.
                    map_iteri (fun tag k v -> // The individual union cases.
                        line s_typ $"struct Union{i}_{tag} {{ // {k}"
                        // The free vars in the env.
                        print_ordered_args (indent s_typ) v
                        let () = // constructors
                            let s_typ = indent s_typ
                            let concat x = String.concat ", " x
                            let args = v |> HopacExtensions.S.map (fun (L(i,x)) -> $"{tyv x} t{i}")
                            let con_init = v |> HopacExtensions.S.map (fun (L(i,x)) -> $"v{i}(t{i})")
                            if v.Length <> 0 then
                                line s_typ $"{code_env.__device__}Union{i}_{tag}({concat args}) : {concat con_init} {{}}"
                                line s_typ $"{code_env.__device__}Union{i}_{tag}() = delete;"
                        line s_typ "};"
                        ) x.free_vars
    

                    line s_typ $"struct Union{i} {{" // The union definition.
                    let _ = // Union cases inside the union.
                        let s_typ = indent s_typ
                        line s_typ $"union {{"
                        let _ =
                            let s_typ = indent s_typ
                            map_iteri (fun tag k v -> line s_typ $"Union{i}_{tag} case{tag}; // {k}") x.free_vars
                        line s_typ "};"
    

                        if x.is_heap then line s_typ "int refc{0};"
                        if x.free_vars.Count > int max_tag then raise_codegen_error $"Too many union cases. They should not be more than {max_tag}."
                        line s_typ $"unsigned char tag{{{max_tag}}};"
                        line s_typ $"{code_env.__device__}Union{i}() {{}}" // default constructor, the refc and tag have def value so we don't have to do anything here.
    

                        map_iteri (fun tag k v -> // The constructors for all the union cases.
                            line s_typ $"{code_env.__device__}Union{i}(Union{i}_{tag} t) : tag({tag}), case{tag}(t) {{}} // {k}"
                            ) x.free_vars
    

                        line s_typ $"{code_env.__device__}Union{i}(Union{i} & x) : tag(x.tag) {{" // copy constructor
                        let () =
                            let s_typ = indent s_typ
                            line s_typ "switch(x.tag){"
                            let () = // copy constructor cases
                                let s_typ = indent s_typ
                                map_iteri (fun tag k v ->
                                    line s_typ $"case {tag}: new (&this->case{tag}) Union{i}_{tag}(x.case{tag}); break; // {k}"
                                    ) x.free_vars
                            line s_typ "}"
                        line s_typ "}"
                        line s_typ $"{code_env.__device__}Union{i}(Union{i} && x) : tag(x.tag) {{" // move constructor
                        let () =
                            let s_typ = indent s_typ
                            line s_typ "switch(x.tag){"
                            let () = // move constructor cases
                                let s_typ = indent s_typ
                                map_iteri (fun tag k v ->
                                    line s_typ $"case {tag}: new (&this->case{tag}) Union{i}_{tag}(std::move(x.case{tag})); break; // {k}"
                                    ) x.free_vars
                            line s_typ "}"
                        line s_typ "}"
                        line s_typ $"{code_env.__device__}Union{i} & operator=(Union{i} & x) {{" // copy assignment operator
                        let () =
                            let s_typ = indent s_typ
                            line s_typ "if (this->tag == x.tag) {"
                            let () =
                                let s_typ = indent s_typ
                                line s_typ "switch(x.tag){"
                                let () = // copy assignment cases
                                    let s_typ = indent s_typ
                                    map_iteri (fun tag k v ->
                                        line s_typ $"case {tag}: this->case{tag} = x.case{tag}; break; // {k}"
                                        ) x.free_vars
                                line s_typ "}"
                            line s_typ "} else {"
                            let () =
                                let s_typ = indent s_typ
                                line s_typ $"this->~Union{i}();"
                                line s_typ $"new (this) Union{i}{{x}};"
                            line s_typ "}"
                            line s_typ "return *this;"
                        line s_typ "}"
                        line s_typ $"{code_env.__device__}Union{i} & operator=(Union{i} && x) {{" // move assignment operator
                        let () =
                            let s_typ = indent s_typ
                            line s_typ "if (this->tag == x.tag) {"
                            let () =
                                let s_typ = indent s_typ
                                line s_typ "switch(x.tag){"
                                let () = // move assignment cases
                                    let s_typ = indent s_typ
                                    map_iteri (fun tag k v ->
                                        line s_typ $"case {tag}: this->case{tag} = std::move(x.case{tag}); break; // {k}"
                                        ) x.free_vars
                                line s_typ "}"
                            line s_typ "} else {"
                            let () =
                                let s_typ = indent s_typ
                                line s_typ $"this->~Union{i}();"
                                line s_typ $"new (this) Union{i}{{std::move(x)}};"
                            line s_typ "}"
                            line s_typ "return *this;"
                        line s_typ "}"
                        line s_typ $"{code_env.__device__}~Union{i}() {{"
                        let () = // destructor
                            let s_typ = indent s_typ
                            line s_typ "switch(this->tag){"
                            let () = // destructor cases
                                let s_typ = indent s_typ
                                map_iteri (fun tag k v ->
                                    line s_typ $"case {tag}: this->case{tag}.~Union{i}_{tag}(); break; // {k}"
                                    ) x.free_vars
                            line s_typ "}"
                            line s_typ $"this->tag = {max_tag};"
                        line s_typ "}"
                    line s_typ "};"
                    )
            and layout_tmpl is_heap name : _ -> LayoutRecCpp =
                layout (fun s_fwd s_typ s_fun (x : LayoutRecCpp) ->
                    let name = sprintf "%s%i" name x.tag
                    line s_fwd $"struct {name};"
                    line s_typ $"struct {name} {{"
                    let () =
                        let s_typ = indent s_typ
                        if is_heap then line s_typ "int refc{0};"
                        x.free_vars |> print_ordered_args s_typ
                        let concat x = String.concat ", " x
                        let args = x.free_vars |> HopacExtensions.S.map (fun (L(i,x)) -> $"{tyv x} t{i}")
                        let con_init = x.free_vars |> HopacExtensions.S.map (fun (L(i,x)) -> $"v{i}(t{i})")
                        if args.Length <> 0 then
                            line s_typ $"{code_env.__device__}{name}() = default;"
                            line s_typ $"{code_env.__device__}{name}({concat args}) : {concat con_init} {{}}"
                    line s_typ "};"
                    )
            and heap : _ -> LayoutRecCpp = layout_tmpl true "Heap"
            and mut : _ -> LayoutRecCpp = layout_tmpl true "Mut"
            and stack_mut : _ -> LayoutRecCpp = layout_tmpl false "StackMut"
    

            function
            | Cpp x ->
                let ret_ty =
                    let er() = raise_codegen_error "The return type of main function in the Cuda host backend should be a i32."
                    match binds_last_dataCpp x with
                    | DLit(LitInt32 _) | DV(L(_, YPrim Int32T)) -> "int"
                    | _ -> er()
    

                let s = {text=StringBuilder(); indent=0}
                line s $"{ret_ty} main_body() {{"
                binds_start (indent s) x
                line s "}"
                line s $"{ret_ty} main(){{"
                line (indent s) "auto r = main_body();"
                line (indent s) "gpuErrchk(cudaDeviceSynchronize()); // This line is here so the `__trap()` calls on the kernel aren't missed."
                line (indent s) "return r;"
                line s "}"
                code_env.main_defs.Add(s.text.ToString())
            | Cuda(vs,x) ->
                let ret_ty =
                    let er() = raise_codegen_error "The return type of the __global__ kernel in the Cuda backend should be a void type or a record of type {cluster_dims : {x : int; y : int; z : int}}."
                    match binds_last_dataCpp x with
                    | DRecord m when m.Count = 1 ->
                        match m |> Map.tryPick (fun (_, k) v -> if k = "cluster_dims" then Some v else None) with
                        | Some(DRecord m) when m.Count = 3 ->
                            let x = m |> Map.tryPick (fun (_, k) v -> if k = "x" then Some v else None)
                            let y = m |> Map.tryPick (fun (_, k) v -> if k = "y" then Some v else None)
                            let z = m |> Map.tryPick (fun (_, k) v -> if k = "z" then Some v else None)
                            match x, y, z with
                            | Some(DSymbol x), Some(DSymbol y), Some(DSymbol z) ->  $"void __cluster_dims__({x},{y},{z})"
                            | Some(DV _), _, _
                            | _, Some(DV _), _
                            | _, _, Some(DV _) ->  raise_codegen_error "All the variables have to be known at compile time."
                            | _ -> er()
                        | _ -> er()
                    | DB -> "void"
                    | _ -> er()
                let s = {text=StringBuilder(); indent=0}
                let args = vs |> HopacExtensions.S.mapi (fun i (L(_,x)) -> $"{tyv x} v{i}") |> String.concat ", "
                line s $"extern \"C\" __global__ {ret_ty} entry%i{code_env.main_defs.Count}(%s{args}) {{"
                binds_start (indent s) x
                line s "}"
                code_env.main_defs.Add(s.text.ToString())
    

        let codegen (default_env : DefaultEnv) (file_path : string) part_eval_env x =
            let g = System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Structural)
            let host_code_env = codegen_env.Create("Cpp", "")
            let device_code_env = codegen_env.Create("Cuda", "__device__ ")
    

            let cuda_codegen =
                codegen' (fun (jp_body,key,r') ->
                    raise_codegen_error_backend r' $"The Cuda backend does not support nesting of backends."
                    ) part_eval_env device_code_env
            codegen' (fun (jp_body,key,r') ->
                match JpNestedBackendKind.ofOwner jp_body with
                | JpNestedCuda ->
                    Utils.memoize g (fun (jp_body,key & C(args,_,_)) ->
                        let args = rdata_free_vars args
                        let jp_dict,_,_ = part_eval_env.join_point_method.[jp_body]
                        let a, _, _ =
                            jpBodyCellAwait jp_dict.[key]
                            |> jpMethodBodyCellReadyForBackend "Cuda"
                        cuda_codegen (Cuda(args, a))
                        $"Device::entry{g.Count}"
                        ) (jp_body,key)
                | JpNestedUnsupported backendId ->
                    let backendName = CompilerKernelV2.BackendIdOps.text backendId
                    raise_codegen_error_backend r' $"The Python + Cuda backend does not support the {backendName} backend."
                ) part_eval_env host_code_env (Cpp x)
    

            let append_lines (l : string seq) = (StringBuilder(), l) ||> Seq.fold (fun s -> s.AppendLine)
            let indent_lines (x : string) =
                x.Split('\n')
                |> HopacExtensions.S.map (fun x -> if x <> "" then $"    {x}" else x)
                |> fun x -> StringBuilder().AppendJoin("", x)
    

            let aux_library_code =
                let dir f =
                    SpiralFileSystem.get_workspace_root ()
                    + "/deps/The-Spiral-Language/The Spiral Language 2"
                    |> fun x -> System.IO.Path.Join (x, f)
                    |> System.IO.File.ReadAllText
                (dir "corelib.cuh").Replace("__host__", "__host__ __device__")
                |> replace_default_types default_env
    

            let code =
                let file_name = System.IO.Path.GetFileNameWithoutExtension file_path
                StringBuilder()
                    .AppendLine($"#include \"{file_name}.auto.cu\"")
                    .Append(append_lines host_code_env.globals)
                    .Append(append_lines device_code_env.globals)
                    .Append(
                        StringBuilder()
                            .AppendLine("namespace Device {")
                            .Append(
                                StringBuilder()
                                    .AppendJoin("", device_code_env.fwd_dcls)
                                    .AppendJoin("", device_code_env.types)
                                    .AppendJoin("", device_code_env.functions)
                                    .AppendJoin("", device_code_env.main_defs)
                                    .ToString()
                                |> indent_lines
                            )
                    )
                    .AppendLine("}")
                    .AppendJoin("", host_code_env.fwd_dcls)
                    .AppendJoin("", host_code_env.types)
                    .AppendJoin("", host_code_env.functions)
                    .AppendJoin("", host_code_env.main_defs)
                    .ToString()
    

            [
                {|code = aux_library_code; file_extension = ".auto.cu"|}
                {|code = code.ToString(); file_extension = ".cu"|}
            ]
    

#else
    /// ## CodegenCpp
    module CodegenCpp =
        // open System
        // open System.Text
        open System.Collections.Generic

        type backend_type =
            | Cuda of args : L<int,Ty>[] * binds : TypedBind[]
            | Cpp of binds : TypedBind[]

        type codegen_env =
            {
                globals : string ResizeArray
                fwd_dcls : string ResizeArray
                types : string ResizeArray
                functions : string ResizeArray
                main_defs : string ResizeArray
                backend_name : string
                __device__ : string
            }

            static member Create(backend_name,__device__) =
                {
                    globals = ResizeArray()
                    fwd_dcls = ResizeArray()
                    types = ResizeArray()
                    functions = ResizeArray()
                    main_defs = ResizeArray()
                    backend_name = backend_name
                    __device__ = __device__
                }

        let backend_nameCpp = "Cpp"
        let private max_tag = 255uy

        let prim = function
            | Int8T -> "char"
            | Int16T -> "short"
            | Int32T -> "int"
            | Int64T -> "long long"
            | UInt8T -> "unsigned char"
            | UInt16T -> "unsigned short"
            | UInt32T -> "unsigned int"
            | UInt64T -> "unsigned long long"
            | Float32T -> "float"
            | Float64T -> "double"
            | BoolT -> "bool" // part of c++ standard
            | CharT -> "char"
            | StringT -> "const char *"

        /// Replaces the default types in the corelib.cuh library.
        let replace_default_types (default_env : DefaultEnv) (x : string) =
            let opts = System.Text.RegularExpressions.RegexOptions.Multiline
            System.Text.RegularExpressions.Regex.Replace(x, @"(^using default_int = )(.*?)(;)", $"$1{prim default_env.default_int}$3", opts)
            |> fun x -> System.Text.RegularExpressions.Regex.Replace(x, @"(^using default_uint = )(.*?)(;)", $"$1{prim default_env.default_uint}$3", opts)

        let is_stringCpp = function DV(L(_,YPrim StringT)) | DLit(LitString _) -> true | _ -> false
        let sizeof_tyvCpp = function
            | YPrim (Int64T | UInt64T | Float64T) -> 8
            | YPrim (Int32T | UInt32T | Float32T) -> 4
            | YPrim (Int16T | UInt16T) -> 2
            | YPrim (Int8T | UInt8T | CharT | BoolT) -> 1
            | _ -> 8
        let order_args v = v |> Array.sortWith (fun (L(_,t)) (L(_,t')) -> compare (sizeof_tyvCpp t') (sizeof_tyvCpp t))
        let lineCpp x s = if s <> "" then x.text.Append(' ', x.indent).AppendLine s |> ignore
        let lineCpp' x s = line x (String.concat " " s)

        type BindsReturnCpp =
            | BindsTailEnd
            | BindsLocal of TyV []

        let term_vars_to_tysCpp x = x |> Array.map (function WV(L(_,t)) -> t | WLit x -> YPrim (lit_to_primitive_type x))
        let binds_last_dataCpp x = x |> Array.last |> function TyLocalReturnData(x,_) | TyLocalReturnOp(_,_,x) -> x | TyLet _ -> raise_codegen_error "Compiler error: Cannot find the return data of the last bind."

        type LayoutRecCpp = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>}
        type UnionRecCpp = {tag : int; free_vars : Map<int * string, TyV[]>; is_heap : bool}
        type MethodRecCpp = {tag : int; free_vars : TyV[]; range : Ty; body : TypedBind[]; name : string option}
        type ClosureRecCpp = {tag : int; free_vars : TyV[]; domain : Ty; range : Ty; funtype : FunType; body : TypedBind[]}
        type TupleRecCpp = {tag : int; tys : Ty []}
        type CFunRecCpp = {tag : int; domain : Ty; range : Ty; funtype : FunType}

        // Replaces the invalid symbols in Spiral method names for the C backend.
        let fix_method_name (x : string) = x.Replace(''','_') + "_"

        let unroll_pop (s : Stack<int>) = if s.Count > 0 then s.Pop() else -1
        let unroll_peek (s : Stack<int>) = if s.Count > 0 then s.Peek() else -1

        let lit_stringCpp x =
            let strb = StringBuilder(String.length x + 2)
            strb.Append '"' |> ignore
            String.iter (function
                | '"' -> strb.Append "\\\""
                | '\b' -> strb.Append @"\b"
                | '\t' -> strb.Append @"\t"
                | '\n' -> strb.Append @"\n"
                | '\r' -> strb.Append @"\r"
                | '\\' -> strb.Append @"\\"
                | x -> strb.Append x
                >> ignore
                ) x
            strb.Append '"' |> ignore
            strb.ToString()

        let codegen' backend_handler (part_eval_env : PartEvalResult) (code_env : codegen_env) =
            let print show r =
                let s_typ_fwd = {text=StringBuilder(); indent=0}
                let s_typ = {text=StringBuilder(); indent=0}
                let s_fun = {text=StringBuilder(); indent=0}
                show s_typ_fwd s_typ s_fun r
                let f (a : _ ResizeArray) (b : CodegenEnv) =
                    let text = b.text.ToString()
                    if text <> "" then a.Add(text)
                f code_env.fwd_dcls s_typ_fwd
                f code_env.types s_typ
                f code_env.functions s_fun

            let layout show =
                let dict' = Dictionary(HashIdentity.Structural)
                let dict = Dictionary(HashIdentity.Reference)
                let f x : LayoutRecCpp =
                    match x with
                    | YLayout(x,_) ->
                        let x = part_eval_env.ty_to_data x
                        let a, b =
                            match x with
                            | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                            | _ -> data_free_vars x, Map.empty
                        {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                    | _ -> raise_codegen_error $"Compiler error: Expected a layout type (1).\nGot: %s{show_ty x}"
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (Utils.memoize dict' (fun x -> dirty <- true; f x)) x
                    if dirty then print show r
                    r

            let union show =
                let dict = Dictionary(HashIdentity.Reference)
                let f (a : Union) : UnionRecCpp =
                    let free_vars = a.Item.cases |> Map.map (fun _ -> part_eval_env.ty_to_data >> data_free_vars)
                    {free_vars=free_vars; tag=dict.Count; is_heap=a.Item.layout = UHeap}
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let jp f show =
                let dict = Dictionary(HashIdentity.Structural)
                let f x = f (x, dict.Count)
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let tuple show =
                let dict = Dictionary(HashIdentity.Structural)
                let f x = {tag=dict.Count; tys=x}
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let cfun' show =
                let dict = Dictionary(HashIdentity.Structural)
                let f (a : Ty, b : Ty, t : FunType) = {tag=dict.Count; domain=a; range=b; funtype=t}
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let args x = x |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "

            let tmp =
                let mutable i = 0u
                fun () -> let x = i in i <- i + 1u; x

            let global' =
                let has_added = HashSet code_env.globals
                let preserves_duplicate_fragment (x : string) =
                    System.String.IsNullOrEmpty x
                    || System.Char.IsWhiteSpace x.[0]
                    || x.[0] = '}'
                fun x -> if preserves_duplicate_fragment x || has_added.Add(x) then code_env.globals.Add x

            let import x = global' $"#include <{x}>"
            let import' x = global' $"#include \"{x}\""

            let tyvs_to_tys (x : TyV []) = Array.map (fun (L(i,t)) -> t) x

            let rec binds_start (s : CodegenEnv) (x : TypedBind []) = binds (Stack()) s BindsTailEnd x
            and return_local s ret (x : string) =
                match ret with
                | [||] -> line s $"{x};"
                | [|L(i,_)|] -> line s $"v{i} = {x};"
                | ret ->
                    let tmp_i = tmp()
                    line s $"{tup_ty_tyvs ret} tmp{tmp_i} = {x};"
                    Array.mapi (fun i (L(i',_)) -> $"v{i'} = tmp{tmp_i}.v{i};") ret |> lineCpp' s
            and get_layout_rec lay a =
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> stack_mut a
            and binds (unroll : Stack<int>) (s : CodegenEnv) (ret : BindsReturnCpp) (stmts : TypedBind []) =
                let tup_destruct (a,b) =
                    Array.map2 (fun (L(i,_)) b ->
                        match b with
                        | WLit b -> $"v{i} = {lit b};"
                        | WV (L(i',_)) -> $"v{i} = v{i'};"
                        ) a b
                Array.forall (fun x ->
                    match x with
                    | TyLet(d,trace,a) ->
                        try let d = data_free_vars d
                            let decl_vars () = Array.map (fun (L(i,t)) -> $"{tyv t} v{i};") d
                            let layout_index layout (x'_i : int) (x' : TyV []) =
                                match layout with
                                | Heap | HeapMutable -> Array.map2 (fun (L(i,t)) (L(i',_)) -> $"{tyv t} & v{i} = v{x'_i}.base->v{i'};") d x' |> lineCpp' s
                                | StackMutable -> Array.map2 (fun (L(i,t)) (L(i',_)) -> $"{tyv t} & v{i} = v{x'_i}.v{i'};") d x' |> lineCpp' s
                            match a with
                            | TyToLayout(a,YLayout(_,StackMutable) & b) ->
                                match d with
                                | [|L(i,YLayout(_,StackMutable))|] -> // For the regular arrays.
                                    let tag = (stack_mut b).tag
                                    line s $"StackMut{tag} v{i}{{{args' a}}};"
                                    true
                                | _ ->
                                    raise_codegen_error "Compiler error: Expected a stack mutable layout type."
                            | TyLayoutIndexAll(x) ->
                                match x with
                                | L(i,YLayout(_,lay) & a) -> (get_layout_rec lay a).free_vars |> layout_index lay i
                                | _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
                                true
                            | TyLayoutIndexByKey(x,key) ->
                                match x with
                                | L(i,YLayout(_,lay) & a) -> (get_layout_rec lay a).free_vars_by_key |> Map.pick (fun (_, k') v' -> if key = k' then Some v' else None) |> layout_index lay i
                                | _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index by key to be a layout type."
                                true
                            | TyMacro a ->
                                let m = a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup_data x) | CMType x -> tup_ty x | CMTypeLit x -> type_lit x) |> String.concat ""
                                if m.StartsWith("#pragma") then
                                    line s m
                                    true
                                elif m = "break" then
                                    line s "break;"
                                    false
                                elif m.StartsWith("return") then
                                    line s $"{m};"
                                    false
                                else
                                    let q = m.Split("\\v")
                                    if q.Length = 1 then
                                        decl_vars() |> lineCpp' s
                                        return_local s d m
                                        true
                                    else
                                        if d.Length = q.Length-1 then
                                            let w = StringBuilder(m.Length+8)
                                            let tag (L(i,_)) = i : int
                                            Array.iteri (fun i v -> w.Append(q.[i]).Append('v').Append(tag v) |> ignore) d
                                            w.Append(q.[d.Length]).Append(';').ToString() |> line s
                                            true
                                        else
                                            raise_codegen_error "The special \\v macro requires the same number of free vars in its binding as there are \\v in the code."
                            | TyArrayLiteral(a,b') ->
                                let inits = List.map tup_data b' |> String.concat "," |> sprintf "{%s}"
                                match d with
                                | [|L(i,YArray t)|] -> // For the regular arrays.
                                    line s $"%s{tup_ty t} v{i}[] = %s{inits};"
                                    true
                                | _ ->
                                    raise_codegen_error "Compiler error: Expected a single variable on the left side of an array literal op."
                            | TyArrayCreate(a,b) ->
                                match d with
                                | [|L(i,YArray t)|] ->
                                    match tup_ty t with
                                    | "void" -> line s "/* void array create */"
                                    | t -> line s $"{t} v{i}[{tup_data b}];"
                                    true
                                | _ -> raise_codegen_error "Compiler error: Expected a single variable on the left side of an array create op."
                            | TyJoinPoint(JPClosure(a,b),b') ->
                                match d with
                                | [|L(i,_)|] ->
                                    let x = closure (a,b)
                                    match x.funtype with
                                    | FT_Pointer ->
                                        let y = cfun (x.domain,x.range,x.funtype)
                                        line s $"Fun{y.tag} v{i} = FunPointerMethod{x.tag};"
                                    | FT_Vanilla ->
                                        let args = args b'
                                        line s $"Closure{x.tag} v{i}{{{args}}};"
                                    | FT_Closure ->
                                        let y = cfun (x.domain,x.range,x.funtype)
                                        let args = args b'
                                        line s $"Fun{y.tag} v{i}{{new Closure{x.tag}{{{args}}}}};"
                                    true
                                | _ -> raise_codegen_error "Compiler error: Expected a single variable on the left side of a closure join point."
                            | _ ->
                                decl_vars() |> lineCpp' s
                                op unroll s (BindsLocal d) a
                                true
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    | TyLocalReturnOp(trace,a,_) ->
                        try op unroll s ret a
                            true
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    | TyLocalReturnData(d,trace) ->
                        try match ret with
                            | BindsLocal l -> lineCpp' s (tup_destruct (l,data_term_vars d))
                            | BindsTailEnd -> line s $"return {tup_data d};"
                            true
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    ) stmts
                |> ignore
            and show_w = function WV(L(i,_)) -> sprintf "v%i" i | WLit a -> lit a
            and args' b = data_term_vars b |> Array.map show_w |> String.concat ", "
            and tup_term_vars x =
                let args = Array.map show_w x |> String.concat ", "
                if 1 < x.Length then sprintf "Tuple%i{%s}" (tup (term_vars_to_tysCpp x)).tag args else args
            and tup_data x = tup_term_vars (data_term_vars x)
            and tup_ty_tys = function
                | [||] -> "void"
                | [|x|] -> tyv x
                | x -> sprintf "Tuple%i" (tup x).tag
            and tup_ty_tyvs (x : TyV []) = tup_ty_tys (tyvs_to_tys x)
            and tup_ty x = part_eval_env.ty_to_data x |> data_free_vars |> tup_ty_tyvs
            and tyv = function
                | YUnion a ->
                    match a.Item.layout with
                    | UStack -> sprintf "Union%i" (unions a).tag
                    | UHeap -> sprintf "sptr<Union%i>" (unions a).tag
                | YLayout(_,lay) as a ->
                    match lay with
                    | Heap -> sprintf "sptr<Heap%i>" (heap a).tag
                    | HeapMutable -> sprintf "sptr<Mut%i>" (mut a).tag
                    | StackMutable -> sprintf "StackMut%i &" (stack_mut a).tag
                | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                    match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameCpp then Some v else None) with
                    | Some x -> tup_ty x
                    | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{code_env.backend_name}' field."
                | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_lit a) |> String.concat ""
                | YPrim a -> prim a
                | YArray a -> sprintf "%s *" (tup_ty a)
                | YFun(a,b,t) -> $"Fun%i{(cfun (a,b,t)).tag}"
                | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
                | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
                | a -> raise_codegen_error (sprintf "Compiler error: Type not supported in the codegen.\nGot: %A" a)
            and lit = function
                | LitInt8 x -> sprintf "%i" x
                | LitInt16 x -> sprintf "%i" x
                | LitInt32 x -> sprintf "%i" x
                | LitInt64 x -> sprintf "%ill" x
                | LitUInt8 x -> sprintf "%iu" x
                | LitUInt16 x -> sprintf "%iu" x
                | LitUInt32 x -> sprintf "%iu" x
                | LitUInt64 x -> sprintf "%iull" x
                | LitFloat32 x ->
                    if x = infinityf then "1.0f / 0.0f"
                    elif x = -infinityf then "-1.0f / 0.0f"
                    elif Single.IsNaN x then "0.0f / 0.0f"
                    else x.ToString("R") |> add_dec_point |> sprintf "%sf"
                | LitFloat64 x ->
                    if x = infinity then "1.0 / 0.0"
                    elif x = -infinity then "-1.0 / 0.0"
                    elif Double.IsNaN x then "0.0 / 0.0"
                    else x.ToString("R") |> add_dec_point
                | LitString x -> lit_stringCpp x
                | LitChar x ->
                    match x with
                    | '\b' -> @"\b"
                    | '\n' -> @"\n"
                    | '\t' -> @"\t"
                    | '\r' -> @"\r"
                    | '\\' -> @"\\"
                    | x -> string x
                    |> sprintf "'%s'"
                | LitBool x -> if x then "true" else "false" // true and false are defined in stddef.h
            and type_lit = function
                | YLit x -> lit x
                | YSymbol x -> x
                | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."
            and op (unroll : Stack<int>)s (ret : BindsReturnCpp) a =
                let binds a b = binds unroll a b
                let return' (x : string) =
                    match ret with
                    | BindsLocal ret -> return_local s ret x
                    | BindsTailEnd -> line s $"return {x};"
                let jp (a,b') =
                    let args = args b'
                    match a with
                    | JPMethod(a,b) ->
                        let x = method (a,b)
                        let method_name = Option.defaultValue "method_" x.name
                        $"{method_name}{x.tag}({args})"
                    | JPClosure(a,b) ->
                        let x = closure (a,b)
                        match x.funtype with
                        | FT_Vanilla -> raise_codegen_error "Compiler error: The vanilla function case should have been blocked elsewhere."
                        | FT_Pointer -> $"FunPointerMethod{x.tag}"
                        | FT_Closure -> $"csptr<ClosureBase{x.tag}>{{new Closure{x.tag}{{{args}}}}}"
                match a with
                | TyMacro _ -> raise_codegen_error "Macros are supposed to be taken care of in the `binds` function."
                | TyIf(cond,tr,fl) ->
                    line s (sprintf "if (%s){" (tup_data cond))
                    binds (indent s) ret tr
                    line s "} else {"
                    binds (indent s) ret fl
                    line s "}"
                | TyJoinPoint(a,args) -> return' (jp (a, args))
                | TyBackend(a,b,c) -> line s $"auto kernel = {backend_handler (a,b,c)};"
                | TyWhile(a,b) ->
                    let cond =
                        match a with
                        | JPMethod(a,b),b' -> sprintf "while_method_%i(%s)" (method_while (a,b)).tag (args b')
                        | _ -> raise_codegen_error "Expected a regular method rather than closure create in the while conditional."
                    match unroll_peek unroll with
                    | -1 -> ()
                    | 0 -> line s $"#pragma unroll"
                    | i -> line s $"#pragma unroll %i{i}"
                    line s (sprintf "while (%s){" cond)
                    binds (indent s) (BindsLocal [||]) b
                    line s "}"
                | TyDo a ->
                    line s "do"
                    binds (indent s) ret a
                | TyIndent a ->
                    binds (indent s) ret a
                | TyIntSwitch(L(v_i,_),on_succ,on_fail) ->
                    line s (sprintf "switch (v%i) {" v_i)
                    let _ =
                        let s = indent s
                        Array.iteri (fun i x ->
                            line s (sprintf "case %i: {" i)
                            binds (indent s) ret x
                            line (indent s) "break;"
                            line s "}"
                            ) on_succ
                        line s "default: {"
                        binds (indent s) ret on_fail
                        line s "}"
                    line s "}"
                | TyUnionUnbox(is,x,on_succs,on_fail) ->
                    let case_tags = x.Item.tags
                    let acs = match x.Item.layout with UHeap -> ".base->" | UStack -> "."
                    let head = List.head is |> fun (L(i,_)) -> $"v{i}{acs}tag"
                    List.pairwise is
                    |> List.map (fun (L(i,_), L(i',_)) -> $"v{i}{acs}tag == v{i'}{acs}tag")
                    |> String.concat " && "
                    |> function "" -> head | x -> $"{x} ? {head} : {max_tag}"
                    |> sprintf "switch (%s) {" |> line s
                    let _ =
                        let s = indent s
                        Map.iter (fun k (a,b) ->
                            let union_i = case_tags.[k]
                            line s (sprintf "case %i: { // %s" union_i k)
                            List.iter2 (fun (L(data_i,_)) a ->
                                let a, s = data_free_vars a, indent s
                                let qs = ResizeArray(a.Length)
                                Array.iteri (fun field_i (L(v_i,t) as v) ->
                                    qs.Add $"{tyv t} v{v_i} = v{data_i}{acs}case{union_i}.v{field_i};"
                                    ) a
                                lineCpp' s qs
                                ) is a
                            binds (indent s) ret b
                            line (indent s) "break;"
                            line s "}"
                            ) on_succs
                        line s "default: {"
                        let _ =
                            let s = indent s
                            match on_fail with
                            | Some b -> binds s ret b
                            | None -> line s "assert(\"Invalid tag.\" && false); __trap();"
                        line s "}"
                    line s "}"
                | TyUnionBox(a,b,c') ->
                    let c = c'.Item
                    let i = c.tags.[a]
                    let vars = args' b
                    let tag = (unions c').tag
                    match c.layout with
                    | UHeap -> $"sptr<Union{tag}>{{new Union{tag}{{Union{tag}_{i}{{{vars}}}}}}}"
                    | UStack -> $"Union{tag}{{Union{tag}_{i}{{{vars}}}}}"
                    |> return'
                | TyToLayout(a,b) ->
                    match b with
                    | YLayout(_,layout) ->
                        match layout with
                        | Heap ->
                            let tag = (heap b).tag
                            $"sptr<Heap{tag}>{{new Heap{tag}{{{args' a}}}}}"
                        | HeapMutable ->
                            let tag = (mut b).tag
                            $"sptr<Mut{tag}>{{new Mut{tag}{{{args' a}}}}}"
                        | StackMutable -> raise_codegen_error "The Cpp backend doesn't support stack mutable layout types."
                    | _ -> raise_codegen_error "Compiler error: Expected a layout type (2)."
                    |> return'
                | TyLayoutIndexAll(x) -> raise_codegen_error "Compiler error: TyLayoutIndexAll should have been taken care of in TyLet."
                | TyLayoutIndexByKey(x,key) -> raise_codegen_error "Compiler error: TyLayoutIndexByKey should have been taken care of in TyLet."
                | TyLayoutMutableSet(L(i,t),b,c) ->
                    match t with
                    | YLayout(_,lay) ->
                        match lay with
                        | HeapMutable ->
                            let a =
                                List.fold
                                    (fun s k ->
                                        match s with
                                        | DRecord l -> l |> Map.pick (fun (_, k') v' -> if k = k' then Some v' else None)
                                        | _ -> raise_codegen_error "Compiler error: Expected a record.")
                                    (mut t).data b
                            Array.map2 (fun (L(i',_)) b -> $"v{i}.base->v{i'} = {show_w b};") (data_free_vars a) (data_term_vars c)
                        | StackMutable ->
                            let a = List.fold (fun s k -> match s with DRecord l -> l |> Map.pick (fun (_, k') v' -> if k = k' then Some v' else None) | _ -> raise_codegen_error "Compiler error: Expected a record.") (stack_mut t).data b
                            Array.map2 (fun (L(i',_)) b -> $"v{i}.v{i'} = {show_w b};") (data_free_vars a) (data_term_vars c)
                        | Heap -> raise_codegen_error "Compiler error (1): TyLayoutMutableSet should only be HeapMutable or StackMutable."
                    | _ -> raise_codegen_error "Compiler error (2): TyLayoutMutableSet should only be HeapMutable or StackMutable."
                    |> String.concat " " |> line s
                | TyArrayLiteral(a,b') -> raise_codegen_error "Compiler error: TyArrayLiteral should have been taken care of in TyLet."
                | TyArrayCreate(a,b) ->  raise_codegen_error "Compiler error: TyArrayCreate should have been taken care of in TyLet."
                | TyFailwith(a,b) ->
                    let string_in_op = function DLit (LitString b) -> lit_stringCpp b | b -> raise_codegen_error "In the Cuda backend, the exception string must be a literal."
                    let fmt = @"%s\n"
                    line s $"printf(\"{fmt}\", {string_in_op b});"
                    line s "__trap();" // TODO: Print out the error traces as well.
                | TyConv(a,b) -> return' $"({tyv a}){tup_data b}"
                | TyApply(L(i,_),b) ->
                    let rec loop = function
                        | DPair(a,b) -> tup_data a :: loop b
                        | a -> [tup_data a]
                    let args = loop b |> List.filter ((<>) "") |> String.concat ", "
                    $"v{i}({args})" |> return'
                | TyArrayLength(_,b) -> raise_codegen_error "Array length is not supported in the Cuda C++ backend as they are bare pointers."
                | TyStringLength(_,b) -> raise_codegen_error "String length is not supported in the Cuda C++ backend."
                | TySizeOf t -> return' $"sizeof({tup_ty t})"
                | TyOp(Global,[DLit (LitString x)]) -> global' x
                | TyOp(PragmaUnrollPush,[DLit (LitInt32 x)]) -> unroll.Push(x); line s $"// Pushing the loop unrolling to: {x}"
                | TyOp(PragmaUnrollPop,[]) -> line s $"// Poping the loop unrolling to: {unroll_pop unroll}"
                | TyOp(op,l) ->
                    match op, l with
                    | Dyn,[a] -> tup_data a
                    | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                    | StringIndex, [a;b] -> sprintf "%s[%s]" (tup_data a) (tup_data b)
                    | StringSlice, [a;b;c] -> raise_codegen_error "String slice is not supported natively in the C++ backend. Use a library implementation instead."
                    | ArrayIndex, [DV(L(_,YArray t)) & a;b] ->
                        match tup_ty t with
                        | "void" -> "/* void array index */"
                        | _ -> sprintf "%s[%s]" (tup_data a) (tup_data b)
                    | ArrayIndexSet, [DV(L(_,YArray t)) as a;b;c] ->
                        let a',b',c' = tup_data a, tup_data b, tup_data c
                        match c' with
                        | "" -> "/* void array set */"
                        | _ -> $"{a'}[{b'}] = {c'}"
                    // Math
                    | Add, [a;b] -> sprintf "%s + %s" (tup_data a) (tup_data b)
                    | Sub, [a;b] -> sprintf "%s - %s" (tup_data a) (tup_data b)
                    | Mult, [a;b] -> sprintf "%s * %s" (tup_data a) (tup_data b)
                    | Div, [a;b] -> sprintf "%s / %s" (tup_data a) (tup_data b)
                    | Mod, [a;b] -> sprintf "%s %% %s" (tup_data a) (tup_data b)
                    | Pow, [a;b] -> sprintf "pow(%s,%s)" (tup_data a) (tup_data b)
                    | LT, [a;b] -> sprintf "%s < %s" (tup_data a) (tup_data b)
                    | LTE, [a;b] -> sprintf "%s <= %s" (tup_data a) (tup_data b)
                    | EQ, [a;b] | NEQ, [a;b] | GT, [a;b] | GTE, [a;b] when is_stringCpp a -> raise_codegen_error "String comparison operations are not supported in the Cuda C++ backend."
                    | EQ, [a;b] -> sprintf "%s == %s" (tup_data a) (tup_data b)
                    | NEQ, [a;b] -> sprintf "%s != %s" (tup_data a) (tup_data b)
                    | GT, [a;b] -> sprintf "%s > %s" (tup_data a) (tup_data b)
                    | GTE, [a;b] -> sprintf "%s >= %s" (tup_data a) (tup_data b)
                    | BoolAnd, [a;b] -> sprintf "%s && %s" (tup_data a) (tup_data b)
                    | BoolOr, [a;b] -> sprintf "%s || %s" (tup_data a) (tup_data b)
                    | BitwiseAnd, [a;b] -> sprintf "%s & %s" (tup_data a) (tup_data b)
                    | BitwiseOr, [a;b] -> sprintf "%s | %s" (tup_data a) (tup_data b)
                    | BitwiseXor, [a;b] -> sprintf "%s ^ %s" (tup_data a) (tup_data b)
                    | BitwiseComplement, [a] -> sprintf "~%s" (tup_data a)

                    | ShiftLeft, [a;b] -> sprintf "%s << %s" (tup_data a) (tup_data b)
                    | ShiftRight, [a;b] -> sprintf "%s >> %s" (tup_data a) (tup_data b)

                    | Neg, [x] -> sprintf "-%s" (tup_data x)
                    | Log, [x] -> sprintf "log(%s)" (tup_data x)
                    | Exp, [x] -> sprintf "exp(%s)" (tup_data x)
                    | Tanh, [x] -> sprintf "tanh(%s)" (tup_data x)
                    | Sqrt, [x] -> sprintf "sqrt(%s)" (tup_data x)
                    | Sin, [x] -> sprintf "sin(%s)" (tup_data x)
                    | Cos, [x] -> sprintf "cos(%s)" (tup_data x)
                    | NanIs, [x] -> sprintf "isnan(%s)" (tup_data x)
                    | StdoutFlush, [] ->
                        import "cstdio"
                        "std::fflush(stdout)"
                    | MonotonicDelayMs, [duration] ->
                        import "thread"
                        import "chrono"
                        sprintf "std::this_thread::sleep_for(std::chrono::milliseconds(%s))" (tup_data duration)
                    | Printf, [fmt;str] ->
                        match args' str with
                        | "" -> sprintf "printf(%s)" (tup_data fmt)
                        | str -> sprintf "printf(%s,%s)" (tup_data fmt) str
                    | UnionTag, [DV(L(i,YUnion l)) as x] ->
                        match l.Item.layout with
                        | UHeap -> ".base->tag"
                        | UStack -> ".tag"
                        |> sprintf "v%i%s" i
                    | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported" op l.Length
                    |> return'
            and print_ordered_args s v = // Unlike C# for example, C keeps the struct fields in input order. To reduce padding, it is best to order the fields from largest to smallest.
                order_args v |> Array.iter (fun (L(i,x)) -> line s $"{tyv x} v{i};")
            and method_template is_while : _ -> MethodRecCpp =
                jp (fun ((jp_body,key & (C(args,_))),i) ->
                    match (fst part_eval_env.join_point_method.[jp_body]).[key] with
                    | Some a, Some range, name -> {tag=i; free_vars=rdata_free_vars args; range=range; body=a; name=Option.map fix_method_name name}
                    | _ -> raise_codegen_error "Compiler error: The method dictionary is malformed"
                    ) (fun s_fwd s_typ s_fun x ->
                    let ret_ty = tup_ty x.range
                    let fun_name = Option.defaultValue (if is_while then "while_method_" else "method_") x.name
                    let args = x.free_vars |> Array.mapi (fun i (L(_,x)) -> $"{tyv x} v{i}") |> String.concat ", "
                    let inline_ =
                        if is_while then "inline "
                        else
                            line s_fwd $"{code_env.__device__}{ret_ty} {fun_name}{x.tag}({args});"
                            if fun_name.StartsWith "noinline" then "__noinline__ " else ""
                    line s_fun $"{code_env.__device__}{inline_}{ret_ty} {fun_name}{x.tag}({args}){{"
                    binds_start (indent s_fun) x.body
                    line s_fun "}"
                    )
            and method : _ -> MethodRecCpp = method_template false
            and method_while : _ -> MethodRecCpp = method_template true
            and closure_args domain count_start =
                let rec loop = function
                    | YPair(a,b) -> a :: loop b
                    | a -> [a]
                let mutable count = count_start
                let rename x = Array.map (fun (L(i,t)) -> let x = L(count,t) in count <- count+1; x) x
                let mutable i = 0
                loop domain |> List.choose (fun x ->
                    let n = part_eval_env.ty_to_data x |> data_free_vars
                    let x = if n.Length <> 0 then Some(i, tup_ty_tyvs n, n |> rename) else None
                    i <- i+1
                    x
                    )
            and closure : _ -> ClosureRecCpp =
                jp (fun ((jp_body,key & (C(args,_,fun_ty))),i) ->
                    match fun_ty with
                    | YFun(domain,range,t) ->
                        match (fst part_eval_env.join_point_closure.[jp_body]).[key] with
                        | Some(domain_args, body) -> {tag=i; domain=domain; range=range; body=body; free_vars=rdata_free_vars args; funtype=t}
                        | _ -> raise_codegen_error "Compiler error: The method dictionary is malformed"
                    | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."
                    ) (fun _ s_typ s_fun x ->
                    let i, range = x.tag, tup_ty x.range
                    let closure_args = closure_args x.domain x.free_vars.Length
                    let args = closure_args |> List.map (fun (i,ty,_) -> $"{ty} tup{i}") |> String.concat ", "
                    let print_body s_fun =
                        let s_fun = indent s_fun
                        x.free_vars |> Array.map (fun (L(i,t)) ->
                            $"{tyv t} & v{i} = this->v{i};"
                            ) |> String.concat " " |> line s_fun
                        closure_args |> List.map (fun (i'',_,vars) ->
                            Array.mapi (fun i' (L(i,t)) ->
                                if vars.Length <> 1 then $"{tyv t} v{i} = tup{i''}.v{i'};"
                                else $"{tyv t} v{i} = tup{i''};"
                                ) vars
                            |> String.concat " "
                            ) |> String.concat " " |> line s_fun
                        binds_start s_fun x.body
                    match x.funtype with
                    | FT_Pointer ->
                        $"{code_env.__device__}{range} FunPointerMethod{i}({args}){{" |> line s_fun
                        print_body s_fun
                        line s_fun "}"
                    | FT_Vanilla | FT_Closure ->
                        match x.funtype with
                        | FT_Pointer -> raise_codegen_error "Compiler error: The pointer case have been taken care of (1)."
                        | FT_Closure ->
                            let i' = (cfun (x.domain,x.range,x.funtype)).tag
                            line s_typ $"struct Closure{i} : public ClosureBase{i'} {{"
                        | FT_Vanilla ->
                            line s_typ $"struct Closure{i} {{"
                        let () =
                            let s_typ = indent s_typ
                            let () = // free vars in the environment
                                print_ordered_args s_typ x.free_vars
                            let () = // operator()
                                match x.funtype with
                                | FT_Pointer -> raise_codegen_error "Compiler error: The pointer case have been taken care of (2)."
                                | FT_Vanilla -> line s_typ $"{code_env.__device__}{range} operator()({args}){{"
                                | FT_Closure -> line s_typ $"{code_env.__device__}{range} operator()({args}) override {{"
                                print_body s_typ
                                line s_typ "}"
                            let () = // constructor
                                match x.free_vars with
                                | [||] -> ()
                                | _ ->
                                    let constructor_args =
                                        x.free_vars
                                        |> Array.map (fun (L(i,t)) -> $"{tyv t} _v{i}")
                                        |> String.concat ", "
                                    let initializer_args =
                                        x.free_vars
                                        |> Array.map (fun (L(i,t)) -> $"v{i}(_v{i})")
                                        |> String.concat ", "
                                    line s_typ $"{code_env.__device__}Closure{i}({constructor_args}) : {initializer_args} {{ }}"
                            let () = // destructor
                                match x.funtype with
                                | FT_Pointer | FT_Vanilla -> ()
                                | FT_Closure ->
                                    let destructor_calls =
                                        x.free_vars
                                        |> Array.choose (fun (L(i,t)) ->
                                            if is_numeric t || is_char t then None else
                                            Some $"destroy(v{i});"
                                            )
                                        |> String.concat " "
                                    line s_typ $"{code_env.__device__}~Closure{i}() override {{ {destructor_calls} }}"
                            ()
                        line s_typ "};"
                    )
            and cfun : _ -> CFunRecCpp =
                cfun' (fun s_fwd s_typ s_fun x ->
                    let i, range = x.tag, tup_ty x.range
                    let domain_args_ty = closure_args x.domain 0 |> List.map (fun (_,ty,_) -> ty) |> String.concat ", "
                    match x.funtype with
                    | FT_Vanilla -> raise_codegen_error "Regular functions do not have a composable type in the Cuda backend. Consider explicitly converting them to either closures or pointers using `to_closure` or `to_fptr` if you want to pass them through boundaries."
                    | FT_Pointer -> line s_fwd $"typedef {range} (* Fun{i})({domain_args_ty});"
                    | FT_Closure ->
                        line s_fwd $"struct ClosureBase{i} {{ int refc{{0}}; {code_env.__device__}virtual {range} operator()({domain_args_ty}) = 0; {code_env.__device__}virtual ~ClosureBase{i}(){{}}; }};"
                        line s_fwd $"typedef csptr<ClosureBase{i}> Fun{i};"
                    )
            and tup : _ -> TupleRecCpp =
                tuple (fun s_fwd s_typ s_fun x ->
                    let name = sprintf "Tuple%i" x.tag
                    line s_fwd $"struct {name};"
                    line s_typ $"struct {name} {{"
                    x.tys |> Array.mapi (fun i x -> L(i,x)) |> print_ordered_args (indent s_typ)
                    let concat x = String.concat ", " x
                    let args = x.tys |> Array.mapi (fun i x -> $"{tyv x} t{i}")
                    let con_init = x.tys |> Array.mapi (fun i x -> $"v{i}(t{i})")
                    if args.Length <> 0 then
                        line (indent s_typ) $"{code_env.__device__}{name}() = default;"
                        line (indent s_typ) $"{code_env.__device__}{name}({concat args}) : {concat con_init} {{}}"
                    line s_typ "};"
                    )
            and unions : _ -> UnionRecCpp =
                let inline map_iteri f x = Map.fold (fun i k v -> f i k v; i+1) 0 x |> ignore
                union (fun s_fwd s_typ s_fun x ->
                    let i = x.tag
                    line s_fwd $"struct Union{i};" // Forward declaration for the union.
                    map_iteri (fun tag k v -> // The individual union cases.
                        line s_typ $"struct Union{i}_{tag} {{ // {k}"
                        // The free vars in the env.
                        print_ordered_args (indent s_typ) v
                        let () = // constructors
                            let s_typ = indent s_typ
                            let concat x = String.concat ", " x
                            let args = v |> Array.map (fun (L(i,x)) -> $"{tyv x} t{i}")
                            let con_init = v |> Array.map (fun (L(i,x)) -> $"v{i}(t{i})")
                            if v.Length <> 0 then
                                line s_typ $"{code_env.__device__}Union{i}_{tag}({concat args}) : {concat con_init} {{}}"
                                line s_typ $"{code_env.__device__}Union{i}_{tag}() = delete;"
                        line s_typ "};"
                        ) x.free_vars

                    line s_typ $"struct Union{i} {{" // The union definition.
                    let _ = // Union cases inside the union.
                        let s_typ = indent s_typ
                        line s_typ $"union {{"
                        let _ =
                            let s_typ = indent s_typ
                            map_iteri (fun tag k v -> line s_typ $"Union{i}_{tag} case{tag}; // {k}") x.free_vars
                        line s_typ "};"

                        if x.is_heap then line s_typ "int refc{0};"
                        if x.free_vars.Count > int max_tag then raise_codegen_error $"Too many union cases. They should not be more than {max_tag}."
                        line s_typ $"unsigned char tag{{{max_tag}}};"
                        line s_typ $"{code_env.__device__}Union{i}() {{}}" // default constructor, the refc and tag have def value so we don't have to do anything here.

                        map_iteri (fun tag k v -> // The constructors for all the union cases.
                            line s_typ $"{code_env.__device__}Union{i}(Union{i}_{tag} t) : tag({tag}), case{tag}(t) {{}} // {k}"
                            ) x.free_vars

                        line s_typ $"{code_env.__device__}Union{i}(Union{i} & x) : tag(x.tag) {{" // copy constructor
                        let () =
                            let s_typ = indent s_typ
                            line s_typ "switch(x.tag){"
                            let () = // copy constructor cases
                                let s_typ = indent s_typ
                                map_iteri (fun tag k v ->
                                    line s_typ $"case {tag}: new (&this->case{tag}) Union{i}_{tag}(x.case{tag}); break; // {k}"
                                    ) x.free_vars
                            line s_typ "}"
                        line s_typ "}"
                        line s_typ $"{code_env.__device__}Union{i}(Union{i} && x) : tag(x.tag) {{" // move constructor
                        let () =
                            let s_typ = indent s_typ
                            line s_typ "switch(x.tag){"
                            let () = // move constructor cases
                                let s_typ = indent s_typ
                                map_iteri (fun tag k v ->
                                    line s_typ $"case {tag}: new (&this->case{tag}) Union{i}_{tag}(std::move(x.case{tag})); break; // {k}"
                                    ) x.free_vars
                            line s_typ "}"
                        line s_typ "}"
                        line s_typ $"{code_env.__device__}Union{i} & operator=(Union{i} & x) {{" // copy assignment operator
                        let () =
                            let s_typ = indent s_typ
                            line s_typ "if (this->tag == x.tag) {"
                            let () =
                                let s_typ = indent s_typ
                                line s_typ "switch(x.tag){"
                                let () = // copy assignment cases
                                    let s_typ = indent s_typ
                                    map_iteri (fun tag k v ->
                                        line s_typ $"case {tag}: this->case{tag} = x.case{tag}; break; // {k}"
                                        ) x.free_vars
                                line s_typ "}"
                            line s_typ "} else {"
                            let () =
                                let s_typ = indent s_typ
                                line s_typ $"this->~Union{i}();"
                                line s_typ $"new (this) Union{i}{{x}};"
                            line s_typ "}"
                            line s_typ "return *this;"
                        line s_typ "}"
                        line s_typ $"{code_env.__device__}Union{i} & operator=(Union{i} && x) {{" // move assignment operator
                        let () =
                            let s_typ = indent s_typ
                            line s_typ "if (this->tag == x.tag) {"
                            let () =
                                let s_typ = indent s_typ
                                line s_typ "switch(x.tag){"
                                let () = // move assignment cases
                                    let s_typ = indent s_typ
                                    map_iteri (fun tag k v ->
                                        line s_typ $"case {tag}: this->case{tag} = std::move(x.case{tag}); break; // {k}"
                                        ) x.free_vars
                                line s_typ "}"
                            line s_typ "} else {"
                            let () =
                                let s_typ = indent s_typ
                                line s_typ $"this->~Union{i}();"
                                line s_typ $"new (this) Union{i}{{std::move(x)}};"
                            line s_typ "}"
                            line s_typ "return *this;"
                        line s_typ "}"
                        line s_typ $"{code_env.__device__}~Union{i}() {{"
                        let () = // destructor
                            let s_typ = indent s_typ
                            line s_typ "switch(this->tag){"
                            let () = // destructor cases
                                let s_typ = indent s_typ
                                map_iteri (fun tag k v ->
                                    line s_typ $"case {tag}: this->case{tag}.~Union{i}_{tag}(); break; // {k}"
                                    ) x.free_vars
                            line s_typ "}"
                            line s_typ $"this->tag = {max_tag};"
                        line s_typ "}"
                    line s_typ "};"
                    )
            and layout_tmpl is_heap name : _ -> LayoutRecCpp =
                layout (fun s_fwd s_typ s_fun (x : LayoutRecCpp) ->
                    let name = sprintf "%s%i" name x.tag
                    line s_fwd $"struct {name};"
                    line s_typ $"struct {name} {{"
                    let () =
                        let s_typ = indent s_typ
                        if is_heap then line s_typ "int refc{0};"
                        x.free_vars |> print_ordered_args s_typ
                        let concat x = String.concat ", " x
                        let args = x.free_vars |> Array.map (fun (L(i,x)) -> $"{tyv x} t{i}")
                        let con_init = x.free_vars |> Array.map (fun (L(i,x)) -> $"v{i}(t{i})")
                        if args.Length <> 0 then
                            line s_typ $"{code_env.__device__}{name}() = default;"
                            line s_typ $"{code_env.__device__}{name}({concat args}) : {concat con_init} {{}}"
                    line s_typ "};"
                    )
            and heap : _ -> LayoutRecCpp = layout_tmpl true "Heap"
            and mut : _ -> LayoutRecCpp = layout_tmpl true "Mut"
            and stack_mut : _ -> LayoutRecCpp = layout_tmpl false "StackMut"

            function
            | Cpp x ->
                let ret_ty =
                    let er() = raise_codegen_error "The return type of main function in the Cuda host backend should be a i32."
                    match binds_last_dataCpp x with
                    | DLit(LitInt32 _) | DV(L(_, YPrim Int32T)) -> "int"
                    | _ -> er()

                let s = {text=StringBuilder(); indent=0}
                line s $"{ret_ty} main_body() {{"
                binds_start (indent s) x
                line s "}"
                line s $"{ret_ty} main(){{"
                line (indent s) "auto r = main_body();"
                line (indent s) "gpuErrchk(cudaDeviceSynchronize()); // This line is here so the `__trap()` calls on the kernel aren't missed."
                line (indent s) "return r;"
                line s "}"
                code_env.main_defs.Add(s.text.ToString())
            | Cuda(vs,x) ->
                let ret_ty =
                    let er() = raise_codegen_error "The return type of the __global__ kernel in the Cuda backend should be a void type or a record of type {cluster_dims : {x : int; y : int; z : int}}."
                    match binds_last_dataCpp x with
                    | DRecord m when m.Count = 1 ->
                        match m |> Map.tryPick (fun (_, k) v -> if k = "cluster_dims" then Some v else None) with
                        | Some(DRecord m) when m.Count = 3 ->
                            let x = m |> Map.tryPick (fun (_, k) v -> if k = "x" then Some v else None)
                            let y = m |> Map.tryPick (fun (_, k) v -> if k = "y" then Some v else None)
                            let z = m |> Map.tryPick (fun (_, k) v -> if k = "z" then Some v else None)
                            match x, y, z with
                            | Some(DSymbol x), Some(DSymbol y), Some(DSymbol z) ->  $"void __cluster_dims__({x},{y},{z})"
                            | Some(DV _), _, _
                            | _, Some(DV _), _
                            | _, _, Some(DV _) ->  raise_codegen_error "All the variables have to be known at compile time."
                            | _ -> er()
                        | _ -> er()
                    | DB -> "void"
                    | _ -> er()
                let s = {text=StringBuilder(); indent=0}
                let args = vs |> Array.mapi (fun i (L(_,x)) -> $"{tyv x} v{i}") |> String.concat ", "
                line s $"extern \"C\" __global__ {ret_ty} entry%i{code_env.main_defs.Count}(%s{args}) {{"
                binds_start (indent s) x
                line s "}"
                code_env.main_defs.Add(s.text.ToString())

        let codegen (default_env : DefaultEnv) (file_path : string) part_eval_env x : GeneratedFile list =
            let g = Dictionary HashIdentity.Structural
            let host_code_env = codegen_env.Create("Cpp", "")
            let device_code_env = codegen_env.Create("Cuda", "__device__ ")

            let cuda_codegen =
                codegen' (fun (jp_body,key,r') ->
                    raise_codegen_error_backend r' $"The Cuda backend does not support nesting of backends."
                    ) part_eval_env device_code_env
            codegen' (fun (jp_body,key,r') ->
                let backend_name = (fst jp_body).node
                match backend_name with
                | "Cuda" ->
                    Utils.memoize g (fun (jp_body,key & C(args,_)) ->
                        let args = rdata_free_vars args
                        match (fst part_eval_env.join_point_method.[jp_body]).[key] with
                        | Some a, Some _, _ -> cuda_codegen (Cuda(args, a))
                        | _ -> raise_codegen_error "Compiler error: The method dictionary is malformed"
                        $"Device::entry{g.Count}"
                        ) (jp_body,key)
                | x -> raise_codegen_error_backend r' $"The Python + Cuda backend does not support the {x} backend."
                ) part_eval_env host_code_env (Cpp x)

            let append_lines (l : string seq) = (StringBuilder(), l) ||> Seq.fold (fun s -> s.AppendLine)
            let indent_lines (x : string) =
                x.Split('\n')
                |> Array.map (fun x -> if x <> "" then $"    {x}" else x)
                |> fun x -> StringBuilder().AppendJoin("", x)

            let aux_library_code =
                let dir f =
                    SpiralFileSystem.get_workspace_root ()
                    + "/deps/The-Spiral-Language/The Spiral Language 2"
                    |> fun x -> System.IO.Path.Join (x, f)
                    |> System.IO.File.ReadAllText
                (dir "corelib.cuh").Replace("__host__", "__host__ __device__")
                |> replace_default_types default_env

            let code =
                let file_name = System.IO.Path.GetFileNameWithoutExtension file_path
                StringBuilder()
                    .AppendLine($"#include \"{file_name}.auto.cu\"")
                    .Append(append_lines host_code_env.globals)
                    .Append(append_lines device_code_env.globals)
                    .Append(
                        StringBuilder()
                            .AppendLine("namespace Device {")
                            .Append(
                                StringBuilder()
                                    .AppendJoin("", device_code_env.fwd_dcls)
                                    .AppendJoin("", device_code_env.types)
                                    .AppendJoin("", device_code_env.functions)
                                    .AppendJoin("", device_code_env.main_defs)
                                    .ToString()
                                |> indent_lines
                            )
                    )
                    .AppendLine("}")
                    .AppendJoin("", host_code_env.fwd_dcls)
                    .AppendJoin("", host_code_env.types)
                    .AppendJoin("", host_code_env.functions)
                    .AppendJoin("", host_code_env.main_defs)
                    .ToString()

            [
                {|code = aux_library_code; file_extension = ".auto.cu"|}
                {|code = code.ToString(); file_extension = ".cu"|}
            ]

#endif
#if SPIRAL_CORE_HOPAC
    /// ## CodegenPython
    module CodegenPython =
        // open System
        // open System.Text
        open System.Collections.Generic
    

        let backend_namePython = "Python"

        // MIGRATION: enquanto o compilador estiver instável, manter IO de trace desativado (console-only).
        let diag_save_enabled = false
    

        let litPython = function
            | LitInt8 x -> sprintf "%i" x
            | LitInt16 x -> sprintf "%i" x
            | LitInt32 x -> sprintf "%i" x
            | LitInt64 x -> sprintf "%i" x
            | LitUInt8 x -> sprintf "%i" x
            | LitUInt16 x -> sprintf "%i" x
            | LitUInt32 x -> sprintf "%i" x
            | LitUInt64 x -> sprintf "%i" x
            | LitFloat32 x ->
                if x = infinityf then "float('inf')"
                elif x = -infinityf then "float('-inf')"
                elif Single.IsNaN x then "float()"
                else x.ToString("R") |> add_dec_point
            | LitFloat64 x ->
                if x = infinity then "float('inf')"
                elif x = -infinity then "float('-inf')"
                elif Double.IsNaN x then "float()"
                else x.ToString("R") |> add_dec_point
            | LitString x ->
                let strb = StringBuilder(x.Length+2)
                strb.Append '"' |> ignore
                String.iter (function
                    | '"' -> strb.Append "\\\""
                    | '\b' -> strb.Append @"\b"
                    | '\t' -> strb.Append @"\t"
                    | '\n' -> strb.Append @"\n"
                    | '\r' -> strb.Append @"\r"
                    | '\\' -> strb.Append @"\\"
                    | x -> strb.Append x
                    >> ignore
                    ) x
                strb.Append '"' |> ignore
                strb.ToString()
            | LitChar x ->
                match x with
                | '\b' -> @"\b"
                | '\n' -> @"\n"
                | '\t' -> @"\t"
                | '\r' -> @"\r"
                | '\\' -> @"\\"
                | '\'' -> @"\'"
                | x -> string x
                |> sprintf "'%s'"
            | LitBool x -> if x then "True" else "False"
    

        let type_litPython = function
            | YLit x -> litPython x
            | YSymbol x -> x
            | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."
    

        let show_w = function WV(L(i,_)) -> sprintf "v%i" i | WLit a -> litPython a
        let args x = x |> HopacExtensions.S.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "
        let args' b = data_term_vars b |> HopacExtensions.S.map show_w |> String.concat ", "
        let primPython x = show_primt x
        let cupy_ty x =
            match x with
            | [|L(_,x)|] ->
                match x with
                | YPrim x ->
                    match x with
                    | Int8T -> "cp.int8"
                    | Int16T -> "cp.int16"
                    | Int32T -> "cp.int32"
                    | Int64T -> "cp.int64"
                    | UInt8T -> "cp.uint8"
                    | UInt16T -> "cp.uint16"
                    | UInt32T -> "cp.uint32"
                    | UInt64T -> "cp.uint64"
                    | Float32T -> "cp.float32"
                    | Float64T -> "cp.float64"
                    | BoolT -> "cp.bool_"
                    | _ -> "object"
                | _ -> "object"
            | _ -> "object"
    

        type UnionRecPython = {tag : int; tags : Dictionary<UnionTagId, int>; free_vars : Map<int * string, TyV[]>}
        type LayoutRecPython = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>}
        type MethodRecPython = {tag : int; free_vars : L<Tag,Ty>[]; range : Ty; body : TypedBind[]}
        type ClosureRecPython = {tag : int; free_vars : L<Tag,Ty>[]; domain : Ty; domain_args : TyV[]; range : Ty; body : TypedBind[]}
    

        type BindsReturnPython =
            | BindsTailEnd
            | BindsLocal of TyV []
    

        let linePython x s = if s <> "" then x.text.Append(' ', x.indent).AppendLine s |> ignore
    

        let codegen' backend_handler (part_eval_env : PartEvalResult) (code_env : CodegenCpp.codegen_env) =
            let global' =
                let has_added = HashSet code_env.globals
                fun x -> if preservesDuplicateGlobalFragment x || has_added.Add(x) then code_env.globals.Add x
    

            let import x = global' $"import {x}"
            let from x = global' $"from {x}"
    

            let print is_type show r =
                let s = {text=StringBuilder(); indent=0}
                show s r
                let text = s.text.ToString()
                if is_type then code_env.types.Enqueue(text) else code_env.functions.Enqueue(text)
    

            let union show =
                let dict = Collections.Concurrent.ConcurrentDictionary(HashIdentity.Reference)
                let f (a : Union) : UnionRecPython =
                    let tags = a.Item.tags
                    let free_vars = a.Item.cases |> Map.map (fun _ -> part_eval_env.ty_to_data >> data_free_vars)
                    {tags=tags; free_vars=free_vars; tag=dict.Count}
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print true show r
                    r
    

            let layout show =
                let dict' = System.Collections.Concurrent.ConcurrentDictionary<Ty, _>(HashIdentity.Structural)
                let dict = System.Collections.Concurrent.ConcurrentDictionary<Ty, _>(HashIdentity.Reference)
                let next_tag = CodegenTagAllocator()
                let f x : LayoutRecPython =
                    match x with
                    | YLayout(x,_) ->
                        let x = part_eval_env.ty_to_data x
                        let a, b =
                            match x with
                            | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> HopacExtensions.S.collect snd, a
                            | _ -> data_free_vars x, Map.empty
                        {data=x; free_vars=a; free_vars_by_key=b; tag=next_tag.Next()}
                    | _ -> raise_codegen_error $"Compiler error: Expected a layout type (5).\nGot: %s{show_ty x}"
                fun x ->
                    match dict.TryGetValue x with
                    | true, r -> r
                    | _ ->
                        let mutable added = false
                        let r =
                            match dict'.TryGetValue x with
                            | true, r -> r
                            | _ ->
                                let r = f x
                                if dict'.TryAdd(x, r) then added <- true; r else dict'.[x]
                        dict.TryAdd(x, r) |> ignore
                        if added then print true show r
                        r
    

            let jp is_type f show =
                let dict = System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Structural)
                let f x = f (x, dict.Count)
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print is_type show r
                    r
    

            let cupy_ty x = part_eval_env.ty_to_data x |> data_free_vars |> cupy_ty
            let rec binds_start (args : TyV []) (s : CodegenEnv) (x : TypedBind []) = binds (refc_prepass Set.empty (Set args) x).g_decr s BindsTailEnd x
            and binds g_decr (s : CodegenEnv) (ret : BindsReturnPython) (stmts : TypedBind []) =
                let s_len = s.text.Length
                let tup_destruct (a,b) =
                    if 0 < Array.length a then
                        let a = args a
                        let b = HopacExtensions.S.map show_w (data_term_vars b) |> String.concat ", "
                        sprintf "%s = %s" a b |> line s
                HopacExtensions.S.iter (fun x ->
                    let _ =
                        let f (g : System.Collections.Concurrent.ConcurrentDictionary<_,_>) = match g.TryGetValue(x) with true, x -> Seq.toArray x | _ -> [||]
                        match args (f g_decr) with "" -> () | x -> sprintf "del %s" x |> line s
                    match x with
                    | TyLet(d,trace,a) ->
                        try op g_decr s (BindsLocal (data_free_vars d)) a
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                    | TyLocalReturnOp(trace,a,_) ->
                        try op g_decr s ret a
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                    | TyLocalReturnData(d,trace) ->
                        try match ret with
                            | BindsLocal l -> tup_destruct (l, d)
                            | BindsTailEnd -> line s $"return {tup_data' d}"
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                    ) stmts
                if s.text.Length = s_len then line s "pass"
            and tup_data' x =
                match HopacExtensions.S.map show_w (data_term_vars x) with
                | [||] -> ""
                | [|x|] -> x
                | args -> String.concat ", " args
            and tup_data x =
                match HopacExtensions.S.map show_w (data_term_vars x) with
                | [||] -> "None"
                | [|x|] -> x
                | args -> sprintf "(%s)" (String.concat ", " args)
            and tyv = function
                | YUnion a ->
                    match a.Item.layout with
                    | UHeap -> sprintf "UH%i" (uheap a).tag
                    | UStack -> sprintf "US%i" (ustack a).tag
                | YLayout(_,lay) as a ->
                    match lay with
                    | Heap -> sprintf "Heap%i" (heap a).tag
                    | HeapMutable -> sprintf "Mut%i" (mut a).tag
                    | StackMutable -> raise_codegen_error "Compiler error: The Python backend doesn't support stack mutable layout types."
                | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                    match r |> Map.tryPick (fun (_, k) v -> if k = backend_namePython then Some v else None) with
                    | Some x -> tup_ty x
                    | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_namePython}' field."
                | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_litPython a) |> String.concat ""
                | YPrim a -> primPython a
                | YArray a -> "(cp if cuda else np).ndarray"
                | YFun(a,b,FT_Vanilla) ->
                    let a = part_eval_env.ty_to_data a |> data_free_vars |> HopacExtensions.S.map (fun (L(_,t)) -> tyv t) |> String.concat ", "
                    $"Callable[[{a}], {tup_ty b}]"
                | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
                | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
                | a -> raise_codegen_error $"Complier error: Type not supported in the codegen.\nGot: %A{a}"
            and tup_ty x =
                match part_eval_env.ty_to_data x |> data_free_vars |> HopacExtensions.S.map (fun (L(_,t)) -> tyv t) with
                | [||] -> "None"
                | [|x|] -> x
                | x -> String.concat ", " x |> sprintf "Tuple[%s]"
            and op g_decr s (ret : BindsReturnPython) a =
                let return' (x : string) =
                    match ret with
                    | BindsTailEnd -> line s $"return {x}"
                    | BindsLocal ret -> line s (if ret.Length = 0 then x else sprintf "%s = %s" (args ret) x)
                let jp (a,b) =
                    let args = args b
                    match a with
                    | JPMethod(a,b) -> sprintf "method%i(%s)" (method (a,b)).tag args
                    | JPClosure(a,b) -> sprintf "Closure%i(%s)" (closure (a,b)).tag args
                let layout_index i x' =
                    x' |> HopacExtensions.S.map (fun (L(i',_)) -> $"v{i}.v{i'}")
                    |> String.concat ", "
                    |> return'
    

                match a with
                | TySizeOf t -> raise_codegen_error $"The following type in `sizeof` is not supported in the Python back end.\nGot: {show_ty t}"
                | TyMacro a ->
                    // System.Console.WriteLine $"CodegenPython.TyMacro / a: %A{a}"
                    a
                    |> List.map (function
                        | CMText x when x |> SpiralSm.starts_with "$\"" ->
                            let x = x |> SpiralSm.replace "%A{" "{"
                            $"f\"{x.[2..]}"
                        | CMText x -> x
                        | CMTerm (x,inl) -> if inl then args' x else tup_data x
                        | CMType x -> tup_ty x
                        | CMTypeLit a -> type_litPython a
                    )
                    |> String.concat ""
                    |> return'
                | TyIf(cond,tr,fl) ->
                    line s (sprintf "if %s:" (tup_data cond))
                    binds g_decr (indent s) ret tr
                    line s "else:"
                    binds g_decr (indent s) ret fl
                | TyJoinPoint(a,args) -> return' (jp (a, args))
                | TyBackend(a,b,c) -> line s $"kernel = \"{backend_handler (a,b,c)}\""
                | TyWhile(a,b) ->
                    line s (sprintf "while %s:" (jp a))
                    binds g_decr (indent s) (BindsLocal [||]) b
                | TyDo a ->
                    line s "do"
                    binds g_decr (indent s) ret a
                | TyIndent a ->
                    binds g_decr (indent s) ret a
                | TyIntSwitch(L(v_i,_),on_succ,on_fail) ->
                    HopacExtensions.S.iteri (fun i x ->
                        if i = 0 then line s $"if v{v_i} == {i}:"
                        else line s $"elif v{v_i} == {i}:"
                        binds g_decr (indent s) ret x
                        ) on_succ
                    line s "else:"
                    binds g_decr (indent s) ret on_fail
                | TyUnionUnbox(is,x,on_succs,on_fail) ->
                    let case_tags = x.Item.tags
                    line s (sprintf "match %s:" (is |> List.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "))
                    let s = indent s
                    let prefix =
                        match x.Item.layout with
                        | UHeap -> sprintf "UH%i" (uheap x).tag
                        | UStack -> sprintf "US%i" (ustack x).tag
                    Map.iter (fun k (a,b) ->
                        let i = case_tags.[k]
                        let cases =
                            a |> List.map (fun a ->
                                let x = data_free_vars a
                                let g_decr' = Utils.get_default g_decr (Array.head b) (fun () -> Set.empty)
                                let x,g_decr' = Array.mapFold (fun g_decr (L(i,_) as v) -> if Set.contains v g_decr then "_", Set.remove v g_decr else sprintf "v%i" i, g_decr) g_decr' x
                                g_decr.[Array.head b] <- g_decr'
                                FastRuntimeFormat.format "%s_%i(%s)" [| box prefix; box i; box (String.concat ", " x) |]
                                )
                            |> String.concat ", "
                        line s (sprintf "case %s: # %s" cases (UnionTagIdOps.text k))
                        binds g_decr (indent s) ret b
                        ) on_succs
                    line s "case t:"
                    match on_fail with
                    | Some b -> binds g_decr (indent s) ret b
                    | None -> line (indent s) "raise Exception(f'Pattern matching miss. Got: {t}')"
                | TyUnionBox(a,b,c') ->
                    let c = c'.Item
                    let i = c.tags.[a]
                    let vars = tup_data' b
                    match c.layout with
                    | UHeap -> FastRuntimeFormat.format "UH%i_%i(%s)" [| box ((uheap c').tag); box i; box vars |]
                    | UStack -> FastRuntimeFormat.format "US%i_%i(%s)" [| box ((ustack c').tag); box i; box vars |]
                    |> return'
                | TyToLayout(a,b) ->
                    match b with
                    | YLayout(_,layout) ->
                        match layout with
                        | Heap -> sprintf "Heap%i(%s)" (heap b).tag (tup_data' a)
                        | HeapMutable -> sprintf "Mut%i(%s)" (mut b).tag (tup_data' a)
                        | StackMutable -> raise_codegen_error "The Python backend doesn't support stack mutable layout types."
                    | _ -> raise_codegen_error "Compiler error: Expected a layout type (6)."
                    |> return'
                | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                    match lay with
                    | Heap -> heap a
                    | HeapMutable -> mut a
                    | StackMutable -> raise_codegen_error "The Python backend doesn't support indexing into stack mutable layout types."
                    |> fun x -> x.free_vars |> layout_index i
                | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                    match lay with
                    | Heap -> heap a
                    | HeapMutable -> mut a
                    | StackMutable -> raise_codegen_error "The Python backend doesn't support indexing into stack mutable layout types."
                    |> fun x ->
                        x.free_vars_by_key
                        |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)
                        |> Option.iter (layout_index i)
                | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
                | TyLayoutMutableSet(L(i,t),b,c) ->
                    let a = List.fold (fun s k ->
                        match s with
                        | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                        | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t).data b
                    Array.iter2 (fun (L(i',_)) b -> line s $"v{i}.v{i'} = {show_w b}") (data_free_vars a) (data_term_vars c)
                | TyArrayLiteral(a,b) ->
                    let dtype = cupy_ty a
                    if dtype = "object" then
                        return' <| sprintf "[%s]" (List.map tup_data' b |> String.concat ", ")
                    else
                        return' <| sprintf "(cp if cuda else np).array([%s],dtype=%s)" (List.map tup_data' b |> String.concat ", ") dtype
                | TyArrayCreate(a,b) ->
                    let dtype = cupy_ty a
                    if dtype = "object" then
                        return' <| sprintf "[None] * %s" (tup_data b)
                    else
                        return' $"(cp if cuda else np).empty({tup_data b},dtype={dtype})"
                | TyFailwith(a,b) -> line s $"raise Exception({tup_data' b})"
                | TyConv(a,b) -> return' $"{tyv a}({tup_data b})"
                | TyApply(L(i,_),b) -> return' $"v{i}({tup_data' b})"
                | TyArrayLength(a,b) -> return' $"{tup_data b}.__len__()"
                | TyStringLength(a,b) -> return' $"len({tup_data b})"
                | TyOp(Global,[DLit (LitString x)]) -> global' x
                | TyOp(op,l) ->
                    match op, l with
                    | ToPythonRecord,[DRecord x] -> Map.foldBack (fun k v l -> $"'{k}': {tup_data v}" :: l) x [] |> String.concat ", " |> sprintf "{%s}"
                    | ToPythonNamedTuple,[n;DRecord x] ->
                        import "collections"
                        let field_names = Map.foldBack (fun k v l -> $"'{k}'" :: l) x [] |> String.concat ", "
                        let args = Map.foldBack (fun k v l -> tup_data v :: l) x [] |> String.concat ", "
                        $"collections.namedtuple({tup_data n},[{field_names}])({args})"
                    | Dyn,[a] -> tup_data a
                    | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                    | StringIndex, [a;b] -> sprintf "%s[%s]" (tup_data a) (tup_data b)
                    | StringSlice, [a;b;c] -> FastRuntimeFormat.format "%s[%s:%s]" [| box (tup_data a); box (tup_data b); box (tup_data c) |]
                    | ArrayIndex, [a;b] ->
                        let aTy = match a with DV(L(_,t)) -> t | _ -> YB
                        match aTy with
                        | YArray t when cupy_ty t = "object" -> sprintf "%s[%s]" (tup_data a) (tup_data b)
                        | _ -> sprintf "%s[%s].item()" (tup_data a) (tup_data b)
                    | ArrayIndexSet, [a;b;c] ->
                        match tup_data' c with
                        | "" -> "pass # void array set"
                        | c -> FastRuntimeFormat.format "%s[%s] = %s" [| box (tup_data a); box (tup_data b); box c |]
                    // Math
                    | Add, [a;b] -> sprintf "%s + %s" (tup_data a) (tup_data b)
                    | Sub, [a;b] -> sprintf "%s - %s" (tup_data a) (tup_data b)
                    | Mult, [a;b] -> sprintf "%s * %s" (tup_data a) (tup_data b)
                    | Div, [(DV(L(_,YPrim (Float32T | Float64T))) | DLit(LitFloat32 _ | LitFloat64 _)) & a;b] -> sprintf "%s / %s" (tup_data a) (tup_data b)
                    | Div, [a;b] -> sprintf "%s // %s" (tup_data a) (tup_data b)
                    | Mod, [a;b] -> sprintf "%s %% %s" (tup_data a) (tup_data b)
                    | Pow, [a;b] -> sprintf "pow(%s,%s)" (tup_data a) (tup_data b)
                    | LT, [a;b] -> sprintf "%s < %s" (tup_data a) (tup_data b)
                    | LTE, [a;b] -> sprintf "%s <= %s" (tup_data a) (tup_data b)
                    | EQ, [a;b] -> sprintf "%s == %s" (tup_data a) (tup_data b)
                    | NEQ, [a;b] -> sprintf "%s != %s" (tup_data a) (tup_data b)
                    | GT, [a;b] -> sprintf "%s > %s" (tup_data a) (tup_data b)
                    | GTE, [a;b] -> sprintf "%s >= %s" (tup_data a) (tup_data b)
                    | BoolAnd, [a;b] -> sprintf "%s and %s" (tup_data a) (tup_data b)
                    | BoolOr, [a;b] -> sprintf "%s or %s" (tup_data a) (tup_data b)
                    | BitwiseAnd, [a;b] -> sprintf "%s & %s" (tup_data a) (tup_data b)
                    | BitwiseOr, [a;b] -> sprintf "%s | %s" (tup_data a) (tup_data b)
                    | BitwiseXor, [a;b] -> sprintf "%s ^ %s" (tup_data a) (tup_data b)
                    | BitwiseComplement, [a] -> sprintf "~%s" (tup_data a)
    

                    | ShiftLeft, [a;b] -> sprintf "%s << %s" (tup_data a) (tup_data b)
                    | ShiftRight, [a;b] -> sprintf "%s >> %s" (tup_data a) (tup_data b)
    

                    | Neg, [x] -> sprintf "-%s" (tup_data x)
                    | Log, [x] -> import "math"; sprintf "math.log(%s)" (tup_data x)
                    | Exp, [x] -> import "math"; sprintf "math.exp(%s)" (tup_data x)
                    | Tanh, [x] -> import "math"; sprintf "math.tanh(%s)" (tup_data x)
                    | Sqrt, [x] -> import "math"; sprintf "math.sqrt(%s)" (tup_data x)
                    | Sin, [x] -> import "math"; sprintf "math.sin(%s)" (tup_data x)
                    | Cos, [x] -> import "math"; sprintf "math.cos(%s)" (tup_data x)
                    | NanIs, [x] -> import "math"; sprintf "math.isnan(%s)" (tup_data x)
                    | UnionTag, [DUnion(_,l) | DV(L(_,YUnion l)) as x] -> sprintf "%s.tag" (tup_data x)
                    | _ -> raise_codegen_error <| sprintf "Compiler error: %s with %i args not supported" (opStableText op) l.Length
                    |> return'
            and uheap : _ -> UnionRecPython =
                let emit s (x : UnionRecPython) =
                    let cases = Array.init x.free_vars.Count (fun i -> $"\"UH{x.tag}_{i}\"") |> function [|x|] -> x | x -> x |> String.concat ", " |> sprintf "Union[%s]"
                    code_env.fwd_dcls.Enqueue $"UH{x.tag} = {cases}"
                    let by_tag =
                        x.free_vars
                        |> Map.toArray
                        |> HopacExtensions.S.map (fun (k,a) ->
                            let name = snd k
                            k, x.tags.[UnionTagIdOps.create name], a
                        )
                        |> fun arr ->
                            if arr.Length = 0 then arr
                            else
                                let tags = arr |> HopacExtensions.S.map (fun (_,i,_) -> i)
                                let min_tag = tags |> Array.min
                                let max_tag = tags |> Array.max
                                if min_tag <> 0 || max_tag <> arr.Length - 1 || (tags |> Array.distinct |> Array.length) <> arr.Length then
                                    raise_codegen_error $"Compiler error: Non-contiguous union tags in Python codegen. Got min={min_tag} max={max_tag} len={arr.Length}"
                                arr |> Array.sortBy (fun (_,i,_) -> i)
                    by_tag
                    |> HopacExtensions.S.iter (fun (k,i,a) ->
                        line s $"class UH{x.tag}_{i}(NamedTuple): # {snd k}"
                        let s = indent s
                        a |> HopacExtensions.S.iter (fun (L(i,t)) -> line s $"v{i} : {tyv t}")
                        line s $"tag = {i}"
                    )
                union emit
            and ustack : _ -> UnionRecPython =
                let emit s (x : UnionRecPython) =
                    let by_tag =
                        x.free_vars
                        |> Map.toArray
                        |> HopacExtensions.S.map (fun (k,a) ->
                            let name = snd k
                            k, x.tags.[UnionTagIdOps.create name], a
                        )
                        |> fun arr ->
                            if arr.Length = 0 then arr
                            else
                                let tags = arr |> HopacExtensions.S.map (fun (_,i,_) -> i)
                                let min_tag = tags |> Array.min
                                let max_tag = tags |> Array.max
                                if min_tag <> 0 || max_tag <> arr.Length - 1 || (tags |> Array.distinct |> Array.length) <> arr.Length then
                                    raise_codegen_error $"Compiler error: Non-contiguous union tags in Python codegen. Got min={min_tag} max={max_tag} len={arr.Length}"
                                arr |> Array.sortBy (fun (_,i,_) -> i)
                    by_tag
                    |> HopacExtensions.S.iter (fun (k,i,a) ->
                        line s $"class US{x.tag}_{i}(NamedTuple): # {snd k}"
                        let s = indent s
                        a |> HopacExtensions.S.iter (fun (L(i,t)) -> line s $"v{i} : {tyv t}")
                        line s $"tag = {i}"
                    )
                    let cases = Array.init x.free_vars.Count (fun i -> $"\"US{x.tag}_{i}\"") |> function [|x|] -> x | x -> x |> String.concat ", " |> sprintf "Union[%s]"
                    line s $"US{x.tag} = {cases}"
                union emit
            and heap : _ -> LayoutRecPython =
                let emit s (x : LayoutRecPython) =
                    line s $"class Heap{x.tag}(NamedTuple):"
                    let s = indent s
                    if x.free_vars.Length = 0 then line s "pass"
                    else x.free_vars |> HopacExtensions.S.iter (fun (L(i,t)) -> line s $"v{i} : {tyv t}")
                layout emit
            and mut : _ -> LayoutRecPython =
                let emit s (x : LayoutRecPython) =
                    line s "@dataclass"
                    line s $"class Mut{x.tag}:"
                    let s = indent s
                    if x.free_vars.Length = 0 then line s "pass"
                    else x.free_vars |> HopacExtensions.S.iter (fun (L(i,t)) -> line s $"v{i} : {tyv t}")
                layout emit
            and method : _ -> MethodRecPython =
                jp false (fun ((jp_body,key & (C(args,_,_))),i) ->
                    let jp_dict,_,_ = part_eval_env.join_point_method.[jp_body]
                    let a, range, _ =
                        jpBodyCellAwait jp_dict.[key]
                        |> jpMethodBodyCellReadyForBackend "Python"
                    {tag=i; free_vars=rdata_free_vars args; range=range; body=a}
                    ) (fun s x ->
                    let method_args = x.free_vars |> HopacExtensions.S.map (fun (L(i,t)) -> $"v{i} : {tyv t}") |> String.concat ", "
                    line s $"def method{x.tag}({method_args}) -> {tup_ty x.range}:"
                    binds_start x.free_vars (indent s) x.body
                    )
            and closure : _ -> ClosureRecPython =
                jp true (fun ((jp_body,key & (C(args,_,fun_ty))),i) ->
                    match fun_ty with
                    | YFun(domain,range,FT_Vanilla) ->
                        let jp_dict,_,_ = part_eval_env.join_point_closure.[jp_body]
                        let domain_args, body =
                            jpBodyCellAwait jp_dict.[key]
                            |> jpClosureBodyCellReadyForBackend "Python"
                        {tag=i; free_vars=rdata_free_vars args; domain=domain; domain_args=data_free_vars domain_args; range=range; body=body}
                    | YFun _ -> raise_codegen_error "Non-standard functions are not supported in the Python backend."
                    | _ -> raise_codegen_error """error[EJPX004]: internal compiler error
      |
      = unexpected type in closure join point
      help: capture the stack trace and the inferred/expected types for the closure join point.
    """
                    ) (fun s x ->
                    let env_args = x.free_vars |> HopacExtensions.S.map (fun (L(i,t)) -> $"env_v{i} : {tyv t}") |> String.concat ", "
                    line s $"def Closure{x.tag}({env_args}):"
                    let s = indent s
                    let inner_args = x.domain_args |> HopacExtensions.S.map (fun (L(i,t)) -> $"v{i} : {tyv t}") |> String.concat ", "
                    line s $"def inner({inner_args}) -> {tup_ty x.range}:"
                    let _ =
                        let s = indent s
                        if x.free_vars.Length > 0 then
                            let nonlocal_args = x.free_vars |> HopacExtensions.S.map (fun (L(i,t)) -> $"env_v{i}") |> String.concat ", "
                            line s $"nonlocal {nonlocal_args}"
                            x.free_vars |> HopacExtensions.S.map (fun (L(i,t)) -> $"v{i} = env_v{i}") |> String.concat "; " |> line s
                        binds_start x.free_vars s x.body
                    line s "return inner"
                    )
    

            fun (x : TypedBind []) ->
            import "cupy as cp"
            import "numpy as np"
            from "dataclasses import dataclass"
            from "typing import NamedTuple, Union, Callable, Tuple"
            code_env.globals.Add "i8 = int; i16 = int; i32 = int; i64 = int; u8 = int; u16 = int; u32 = int; u64 = int; f32 = float; f64 = float; char = str; string = str"
            code_env.globals.Add "cuda = False"
            code_env.globals.Add ""
    

            let s = {text=StringBuilder(); indent=0}
    

            line s "def main_body():"
            binds_start [||] (indent s) x
            s.text.AppendLine() |> ignore
    

            line s "def main():"
            line (indent s) "r = main_body()"
            line (indent s) "if cuda: cp.cuda.get_current_stream().synchronize() # This line is here so the `__trap()` calls on the kernel aren't missed."
            line (indent s) "return r"
            s.text.AppendLine() |> ignore
    

            line s "if __name__ == '__main__': result = main(); None if result is None else print(result)"
            code_env.main_defs.Add(s.text.ToString())
    

        let codegen (default_env : DefaultEnv) (file_path : string) part_eval_env (x : TypedBind[]) =
            let cuda_kernels = StringBuilder().AppendLine("kernel = r\"\"\"")
            let g = System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Structural)
    

            let host_code_env = CodegenCpp.codegen_env.Create("Python", "")
            let device_code_env = CodegenCpp.codegen_env.Create("Cuda", "__device__ ")
    

            let cuda_codegen =
                CodegenCpp.codegen' (fun (jp_body,key,r') ->
                    raise_codegen_error_backend r' $"The Cuda backend does not support nesting of backends."
                    ) part_eval_env device_code_env
            let python_code =
                codegen' (fun (jp_body,key,r') ->
                    match JpNestedBackendKind.ofOwner jp_body with
                    | JpNestedCuda ->
                        Utils.memoize g (fun (jp_body,key & C(args,_,_)) ->
                            let args = rdata_free_vars args
                            let jp_dict,_,_ = part_eval_env.join_point_method.[jp_body]
                            let a, _, _ =
                                jpBodyCellAwait jp_dict.[key]
                                |> jpMethodBodyCellReadyForBackend "Python+Cuda"
                            cuda_codegen (CodegenCpp.Cuda(args,a))
                            $"entry{g.Count}"
                            ) (jp_body,key)
                    | JpNestedUnsupported backendId ->
                        let backendName = CompilerKernelV2.BackendIdOps.text backendId
                        raise_codegen_error_backend r' $"The Python + Cuda backend does not support the {backendName} backend."
                    ) part_eval_env host_code_env x
    

            let append_lines (l : string seq) = (StringBuilder(), l) ||> Seq.fold (fun s -> s.AppendLine)
    

            let file_name = System.IO.Path.GetFileNameWithoutExtension file_path
    

            let aux_library_code =
                let dir f =
                    SpiralFileSystem.get_workspace_root ()
                    + "/deps/The-Spiral-Language/The Spiral Language 2"
                    |> fun x -> System.IO.Path.Join (x, f)
                    |> System.IO.File.ReadAllText
                let aux_library_code_python = dir "corelib.py"
                let aux_library_code_cuda =
                    (dir "corelib.cuh").Replace("__host__", "__device__")
                    |> CodegenCpp.replace_default_types default_env
    

                StringBuilder()
                    .AppendLine("kernels_aux = r\"\"\"")
                    .AppendLine(aux_library_code_cuda)
                    .AppendLine("\"\"\"")
                    .AppendLine(aux_library_code_python)
                    .ToString()
            let code_main =
                StringBuilder()
                    .AppendLine("kernels_main = r\"\"\"")
                    .Append(append_lines device_code_env.globals)
                    .AppendJoin("", device_code_env.fwd_dcls)
                    .AppendJoin("", device_code_env.types)
                    .AppendJoin("", device_code_env.functions)
                    .AppendJoin("", device_code_env.main_defs)
                    .AppendLine("\"\"\"")
                    .AppendLine($"from {file_name}_auto import *")
                    .AppendLine("kernels = kernels_aux + kernels_main")
                    .AppendLine(
                        part_eval_env.globals
                        |> Seq.append host_code_env.globals
                        |> Seq.distinct
                        |> append_lines
                        |> _.ToString()
                    )
                    .AppendLine("# fwd_dcls")
                    .AppendJoin("\n", host_code_env.fwd_dcls)
                    .AppendLine("# types")
                    .AppendJoin("", host_code_env.types)
                    .AppendLine("# functions")
                    .AppendJoin("", host_code_env.functions)
                    .AppendLine("# main_defs")
                    .AppendJoin("", host_code_env.main_defs)
                    .ToString()
    

            [
                {|code = aux_library_code; file_extension = "_auto.py"|}
                {|code = code_main; file_extension = ".py"|}
            ]
    

#else
    /// ## CodegenPython
    module CodegenPython =
        // open System
        // open System.Text
        open System.Collections.Generic

        let backend_namePython = "Python"

        let litPython = function
            | LitInt8 x -> sprintf "%i" x
            | LitInt16 x -> sprintf "%i" x
            | LitInt32 x -> sprintf "%i" x
            | LitInt64 x -> sprintf "%i" x
            | LitUInt8 x -> sprintf "%i" x
            | LitUInt16 x -> sprintf "%i" x
            | LitUInt32 x -> sprintf "%i" x
            | LitUInt64 x -> sprintf "%i" x
            | LitFloat32 x ->
                if x = infinityf then "float('inf')"
                elif x = -infinityf then "float('-inf')"
                elif Single.IsNaN x then "float()"
                else x.ToString("R") |> add_dec_point
            | LitFloat64 x ->
                if x = infinity then "float('inf')"
                elif x = -infinity then "float('-inf')"
                elif Double.IsNaN x then "float()"
                else x.ToString("R") |> add_dec_point
            | LitString x ->
                let strb = StringBuilder(x.Length+2)
                strb.Append '"' |> ignore
                String.iter (function
                    | '"' -> strb.Append "\\\""
                    | '\b' -> strb.Append @"\b"
                    | '\t' -> strb.Append @"\t"
                    | '\n' -> strb.Append @"\n"
                    | '\r' -> strb.Append @"\r"
                    | '\\' -> strb.Append @"\\"
                    | x -> strb.Append x
                    >> ignore
                    ) x
                strb.Append '"' |> ignore
                strb.ToString()
            | LitChar x ->
                match x with
                | '\b' -> @"\b"
                | '\n' -> @"\n"
                | '\t' -> @"\t"
                | '\r' -> @"\r"
                | '\\' -> @"\\"
                | ''' -> @"\'"
                | x -> string x
                |> sprintf "'%s'"
            | LitBool x -> if x then "True" else "False"

        let type_litPython = function
            | YLit x -> litPython x
            | YSymbol x -> x
            | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

        let show_w = function WV(L(i,_)) -> sprintf "v%i" i | WLit a -> litPython a
        let args x = x |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "
        let args' b = data_term_vars b |> Array.map show_w |> String.concat ", "
        let primPython x = show_primt x
        let cupy_ty x =
            match x with
            | [|L(_,x)|] ->
                match x with
                | YPrim x ->
                    match x with
                    | Int8T -> "cp.int8"
                    | Int16T -> "cp.int16"
                    | Int32T -> "cp.int32"
                    | Int64T -> "cp.int64"
                    | UInt8T -> "cp.uint8"
                    | UInt16T -> "cp.uint16"
                    | UInt32T -> "cp.uint32"
                    | UInt64T -> "cp.uint64"
                    | Float32T -> "cp.float32"
                    | Float64T -> "cp.float64"
                    | BoolT -> "cp.bool_"
                    | _ -> "object"
                | _ -> "object"
            | _ -> "object"

        type UnionRecPython = {tag : int; free_vars : Map<int * string, TyV[]>}
        type LayoutRecPython = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>}
        type MethodRecPython = {tag : int; free_vars : L<Tag,Ty>[]; range : Ty; body : TypedBind[]}
        type ClosureRecPython = {tag : int; free_vars : L<Tag,Ty>[]; domain : Ty; domain_args : TyV[]; range : Ty; body : TypedBind[]}

        type BindsReturnPython =
            | BindsTailEnd
            | BindsLocal of TyV []

        let linePython x s = if s <> "" then x.text.Append(' ', x.indent).AppendLine s |> ignore

        let codegen' backend_handler (part_eval_env : PartEvalResult) (code_env : CodegenCpp.codegen_env) =
            let global' =
                let has_added = HashSet code_env.globals
                let preserves_duplicate_fragment (x : string) =
                    System.String.IsNullOrEmpty x
                    || System.Char.IsWhiteSpace x.[0]
                    || x.[0] = '}'
                fun x -> if preserves_duplicate_fragment x || has_added.Add(x) then code_env.globals.Add x

            let import x = global' $"import {x}"
            let from x = global' $"from {x}"

            let print is_type show r =
                let s = {text=StringBuilder(); indent=0}
                show s r
                let text = s.text.ToString()
                if is_type then code_env.types.Add(text) else code_env.functions.Add(text)

            let union show =
                let dict = Dictionary(HashIdentity.Reference)
                let f (a : Union) : UnionRecPython =
                    let free_vars = a.Item.cases |> Map.map (fun _ -> part_eval_env.ty_to_data >> data_free_vars)
                    {free_vars=free_vars; tag=dict.Count}
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print true show r
                    r

            let layout show =
                let dict' = Dictionary(HashIdentity.Structural)
                let dict = Dictionary(HashIdentity.Reference)
                let f x : LayoutRecPython =
                    match x with
                    | YLayout(x,_) ->
                        let x = part_eval_env.ty_to_data x
                        let a, b =
                            match x with
                            | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                            | _ -> data_free_vars x, Map.empty
                        {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                    | _ -> raise_codegen_error $"Compiler error: Expected a layout type (5).\nGot: %s{show_ty x}"
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (Utils.memoize dict' (fun x -> dirty <- true; f x)) x
                    if dirty then print true show r
                    r

            let jp is_type f show =
                let dict = Dictionary(HashIdentity.Structural)
                let f x = f (x, dict.Count)
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print is_type show r
                    r

            let cupy_ty x = part_eval_env.ty_to_data x |> data_free_vars |> cupy_ty
            let rec binds_start (args : TyV []) (s : CodegenEnv) (x : TypedBind []) = binds (refc_prepass Set.empty (Set args) x).g_decr s BindsTailEnd x
            and binds g_decr (s : CodegenEnv) (ret : BindsReturnPython) (stmts : TypedBind []) =
                let s_len = s.text.Length
                let tup_destruct (a,b) =
                    if 0 < Array.length a then
                        let a = args a
                        let b = Array.map show_w (data_term_vars b) |> String.concat ", "
                        sprintf "%s = %s" a b |> line s
                Array.iter (fun x ->
                    let _ =
                        let f (g : Dictionary<_,_>) = match g.TryGetValue(x) with true, x -> Seq.toArray x | _ -> [||]
                        match args (f g_decr) with "" -> () | x -> sprintf "del %s" x |> line s
                    match x with
                    | TyLet(d,trace,a) ->
                        try op g_decr s (BindsLocal (data_free_vars d)) a
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                    | TyLocalReturnOp(trace,a,_) ->
                        try op g_decr s ret a
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                    | TyLocalReturnData(d,trace) ->
                        try match ret with
                            | BindsLocal l -> tup_destruct (l, d)
                            | BindsTailEnd -> line s $"return {tup_data' d}"
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                    ) stmts
                if s.text.Length = s_len then line s "pass"
            and tup_data' x =
                match Array.map show_w (data_term_vars x) with
                | [||] -> ""
                | [|x|] -> x
                | args -> String.concat ", " args
            and tup_data x =
                match Array.map show_w (data_term_vars x) with
                | [||] -> "None"
                | [|x|] -> x
                | args -> sprintf "(%s)" (String.concat ", " args)
            and tyv = function
                | YUnion a ->
                    match a.Item.layout with
                    | UHeap -> sprintf "UH%i" (uheap a).tag
                    | UStack -> sprintf "US%i" (ustack a).tag
                | YLayout(_,lay) as a ->
                    match lay with
                    | Heap -> sprintf "Heap%i" (heap a).tag
                    | HeapMutable -> sprintf "Mut%i" (mut a).tag
                    | StackMutable -> raise_codegen_error "Compiler error: The Python backend doesn't support stack mutable layout types."
                | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                    match r |> Map.tryPick (fun (_, k) v -> if k = backend_namePython then Some v else None) with
                    | Some x -> tup_ty x
                    | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_namePython}' field."
                | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_litPython a) |> String.concat ""
                | YPrim a -> primPython a
                | YArray a -> "(cp if cuda else np).ndarray"
                | YFun(a,b,FT_Vanilla) ->
                    let a = part_eval_env.ty_to_data a |> data_free_vars |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat ", "
                    $"Callable[[{a}], {tup_ty b}]"
                | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
                | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
                | a -> raise_codegen_error $"Complier error: Type not supported in the codegen.\nGot: %A{a}"
            and tup_ty x =
                match part_eval_env.ty_to_data x |> data_free_vars |> Array.map (fun (L(_,t)) -> tyv t) with
                | [||] -> "None"
                | [|x|] -> x
                | x -> String.concat ", " x |> sprintf "Tuple[%s]"
            and op g_decr s (ret : BindsReturnPython) a =
                let return' (x : string) =
                    match ret with
                    | BindsTailEnd -> line s $"return {x}"
                    | BindsLocal ret -> line s (if ret.Length = 0 then x else sprintf "%s = %s" (args ret) x)
                let jp (a,b) =
                    let args = args b
                    match a with
                    | JPMethod(a,b) -> sprintf "method%i(%s)" (method (a,b)).tag args
                    | JPClosure(a,b) -> sprintf "Closure%i(%s)" (closure (a,b)).tag args
                let layout_index i x' =
                    x' |> Array.map (fun (L(i',_)) -> $"v{i}.v{i'}")
                    |> String.concat ", "
                    |> return'

                match a with
                | TySizeOf t -> raise_codegen_error $"The following type in `sizeof` is not supported in the Python back end.\nGot: {show_ty t}"
                | TyMacro a ->
                    // System.Console.WriteLine $"CodegenPython.TyMacro / a: %A{a}"
                    a
                    |> List.map (function
                        | CMText x when x |> SpiralSm.starts_with "$\"" ->
                            let x = x |> SpiralSm.replace "%A{" "{"
                            $"f\"{x.[2..]}"
                        | CMText x -> x
                        | CMTerm (x,inl) -> if inl then args' x else tup_data x
                        | CMType x -> tup_ty x
                        | CMTypeLit a -> type_litPython a
                    )
                    |> String.concat ""
                    |> return'
                | TyIf(cond,tr,fl) ->
                    line s (sprintf "if %s:" (tup_data cond))
                    binds g_decr (indent s) ret tr
                    line s "else:"
                    binds g_decr (indent s) ret fl
                | TyJoinPoint(a,args) -> return' (jp (a, args))
                | TyBackend(a,b,c) -> line s $"kernel = \"{backend_handler (a,b,c)}\""
                | TyWhile(a,b) ->
                    line s (sprintf "while %s:" (jp a))
                    binds g_decr (indent s) (BindsLocal [||]) b
                | TyDo a ->
                    line s "do"
                    binds g_decr (indent s) ret a
                | TyIndent a ->
                    binds g_decr (indent s) ret a
                | TyIntSwitch(L(v_i,_),on_succ,on_fail) ->
                    Array.iteri (fun i x ->
                        if i = 0 then line s $"if v{v_i} == {i}:"
                        else line s $"elif v{v_i} == {i}:"
                        binds g_decr (indent s) ret x
                        ) on_succ
                    line s "else:"
                    binds g_decr (indent s) ret on_fail
                | TyUnionUnbox(is,x,on_succs,on_fail) ->
                    let case_tags = x.Item.tags
                    line s (sprintf "match %s:" (is |> List.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "))
                    let s = indent s
                    let prefix =
                        match x.Item.layout with
                        | UHeap -> sprintf "UH%i" (uheap x).tag
                        | UStack -> sprintf "US%i" (ustack x).tag
                    Map.iter (fun k (a,b) ->
                        let i = case_tags.[k]
                        let cases =
                            a |> List.map (fun a ->
                                let x = data_free_vars a
                                let g_decr' = Utils.get_default g_decr (Array.head b) (fun () -> Set.empty)
                                let x,g_decr' = Array.mapFold (fun g_decr (L(i,_) as v) -> if Set.contains v g_decr then "_", Set.remove v g_decr else sprintf "v%i" i, g_decr) g_decr' x
                                g_decr.[Array.head b] <- g_decr'
                                sprintf "%s_%i(%s)" prefix i (String.concat ", " x)
                                )
                            |> String.concat ", "
                        line s (sprintf "case %s: # %s" cases k)
                        binds g_decr (indent s) ret b
                        ) on_succs
                    line s "case t:"
                    match on_fail with
                    | Some b -> binds g_decr (indent s) ret b
                    | None -> line (indent s) "raise Exception(f'Pattern matching miss. Got: {t}')"
                | TyUnionBox(a,b,c') ->
                    let c = c'.Item
                    let i = c.tags.[a]
                    let vars = tup_data' b
                    match c.layout with
                    | UHeap -> sprintf "UH%i_%i(%s)" (uheap c').tag i vars
                    | UStack -> sprintf "US%i_%i(%s)" (ustack c').tag i vars
                    |> return'
                | TyToLayout(a,b) ->
                    match b with
                    | YLayout(_,layout) ->
                        match layout with
                        | Heap -> sprintf "Heap%i(%s)" (heap b).tag (tup_data' a)
                        | HeapMutable -> sprintf "Mut%i(%s)" (mut b).tag (tup_data' a)
                        | StackMutable -> raise_codegen_error "The Python backend doesn't support stack mutable layout types."
                    | _ -> raise_codegen_error "Compiler error: Expected a layout type (6)."
                    |> return'
                | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                    match lay with
                    | Heap -> heap a
                    | HeapMutable -> mut a
                    | StackMutable -> raise_codegen_error "The Python backend doesn't support indexing into stack mutable layout types."
                    |> fun x -> x.free_vars |> layout_index i
                | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                    match lay with
                    | Heap -> heap a
                    | HeapMutable -> mut a
                    | StackMutable -> raise_codegen_error "The Python backend doesn't support indexing into stack mutable layout types."
                    |> fun x ->
                        x.free_vars_by_key
                        |> Map.tryPick (fun (_, k) v -> if k = key then Some v else None)
                        |> Option.iter (layout_index i)
                | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
                | TyLayoutMutableSet(L(i,t),b,c) ->
                    let a = List.fold (fun s k ->
                        match s with
                        | DRecord l -> l |> Map.pick (fun (_,k') v -> if k = k' then Some v else None)
                        | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t).data b
                    Array.iter2 (fun (L(i',_)) b -> line s $"v{i}.v{i'} = {show_w b}") (data_free_vars a) (data_term_vars c)
                | TyArrayLiteral(a,b) -> return' <| sprintf "(cp if cuda else np).array([%s],dtype=%s)" (List.map tup_data' b |> String.concat ", ") (cupy_ty a)
                | TyArrayCreate(a,b) -> return' $"(cp if cuda else np).empty({tup_data b},dtype={cupy_ty a})"
                | TyFailwith(a,b) -> line s $"raise Exception({tup_data' b})"
                | TyConv(a,b) -> return' $"{tyv a}({tup_data b})"
                | TyApply(L(i,_),b) -> return' $"v{i}({tup_data' b})"
                | TyArrayLength(a,b) -> return' $"{tup_data b}.__len__()"
                | TyStringLength(a,b) -> return' $"len({tup_data b})"
                | TyOp(Global,[DLit (LitString x)]) -> global' x
                | TyOp(op,l) ->
                    match op, l with
                    | ToPythonRecord,[DRecord x] -> Map.foldBack (fun k v l -> $"'{k}': {tup_data v}" :: l) x [] |> String.concat ", " |> sprintf "{%s}"
                    | ToPythonNamedTuple,[n;DRecord x] ->
                        import "collections"
                        let field_names = Map.foldBack (fun k v l -> $"'{k}'" :: l) x [] |> String.concat ", "
                        let args = Map.foldBack (fun k v l -> tup_data v :: l) x [] |> String.concat ", "
                        $"collections.namedtuple({tup_data n},[{field_names}])({args})"
                    | Dyn,[a] -> tup_data a
                    | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                    | StringIndex, [a;b] -> sprintf "%s[%s]" (tup_data a) (tup_data b)
                    | StringSlice, [a;b;c] -> sprintf "%s[%s:%s]" (tup_data a) (tup_data b) (tup_data c)
                    | ArrayIndex, [a;b] -> sprintf "%s[%s].item()" (tup_data a) (tup_data b)
                    | ArrayIndexSet, [a;b;c] ->
                        match tup_data' c with
                        | "" -> "pass # void array set"
                        | c -> sprintf "%s[%s] = %s" (tup_data a) (tup_data b) c
                    // Math
                    | Add, [a;b] -> sprintf "%s + %s" (tup_data a) (tup_data b)
                    | Sub, [a;b] -> sprintf "%s - %s" (tup_data a) (tup_data b)
                    | Mult, [a;b] -> sprintf "%s * %s" (tup_data a) (tup_data b)
                    | Div, [(DV(L(_,YPrim (Float32T | Float64T))) | DLit(LitFloat32 _ | LitFloat64 _)) & a;b] -> sprintf "%s / %s" (tup_data a) (tup_data b)
                    | Div, [a;b] -> sprintf "%s // %s" (tup_data a) (tup_data b)
                    | Mod, [a;b] -> sprintf "%s %% %s" (tup_data a) (tup_data b)
                    | Pow, [a;b] -> sprintf "pow(%s,%s)" (tup_data a) (tup_data b)
                    | LT, [a;b] -> sprintf "%s < %s" (tup_data a) (tup_data b)
                    | LTE, [a;b] -> sprintf "%s <= %s" (tup_data a) (tup_data b)
                    | EQ, [a;b] -> sprintf "%s == %s" (tup_data a) (tup_data b)
                    | NEQ, [a;b] -> sprintf "%s != %s" (tup_data a) (tup_data b)
                    | GT, [a;b] -> sprintf "%s > %s" (tup_data a) (tup_data b)
                    | GTE, [a;b] -> sprintf "%s >= %s" (tup_data a) (tup_data b)
                    | BoolAnd, [a;b] -> sprintf "%s and %s" (tup_data a) (tup_data b)
                    | BoolOr, [a;b] -> sprintf "%s or %s" (tup_data a) (tup_data b)
                    | BitwiseAnd, [a;b] -> sprintf "%s & %s" (tup_data a) (tup_data b)
                    | BitwiseOr, [a;b] -> sprintf "%s | %s" (tup_data a) (tup_data b)
                    | BitwiseXor, [a;b] -> sprintf "%s ^ %s" (tup_data a) (tup_data b)
                    | BitwiseComplement, [a] -> sprintf "~%s" (tup_data a)

                    | ShiftLeft, [a;b] -> sprintf "%s << %s" (tup_data a) (tup_data b)
                    | ShiftRight, [a;b] -> sprintf "%s >> %s" (tup_data a) (tup_data b)

                    | Neg, [x] -> sprintf "-%s" (tup_data x)
                    | Log, [x] -> import "math"; sprintf "math.log(%s)" (tup_data x)
                    | Exp, [x] -> import "math"; sprintf "math.exp(%s)" (tup_data x)
                    | Tanh, [x] -> import "math"; sprintf "math.tanh(%s)" (tup_data x)
                    | Sqrt, [x] -> import "math"; sprintf "math.sqrt(%s)" (tup_data x)
                    | Sin, [x] -> import "math"; sprintf "math.sin(%s)" (tup_data x)
                    | Cos, [x] -> import "math"; sprintf "math.cos(%s)" (tup_data x)
                    | NanIs, [x] -> import "math"; sprintf "math.isnan(%s)" (tup_data x)
                    | UnionTag, [DUnion(_,l) | DV(L(_,YUnion l)) as x] -> sprintf "%s.tag" (tup_data x)
                    | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported" op l.Length
                    |> return'
            and uheap : _ -> UnionRecPython = union (fun s x ->
                let cases = Array.init x.free_vars.Count (fun i -> $"\"UH{x.tag}_{i}\"") |> function [|x|] -> x | x -> x |> String.concat ", " |> sprintf "Union[%s]"
                code_env.fwd_dcls.Add $"UH{x.tag} = {cases}"
                let mutable i = 0
                x.free_vars |> Map.iter (fun k a ->
                    line s $"class UH{x.tag}_{i}(NamedTuple): # {k}"
                    let s = indent s
                    a |> Array.iter (fun (L(i,t)) -> line s $"v{i} : {tyv t}")
                    line s $"tag = {i}"
                    i <- i+1
                    )
                )
            and ustack : _ -> UnionRecPython = union (fun s x ->
                let mutable i = 0
                x.free_vars |> Map.iter (fun k a ->
                    line s $"class US{x.tag}_{i}(NamedTuple): # {k}"
                    let s = indent s
                    a |> Array.iter (fun (L(i,t)) -> line s $"v{i} : {tyv t}")
                    line s $"tag = {i}"
                    i <- i+1
                    )
                let cases = Array.init x.free_vars.Count (fun i -> $"US{x.tag}_{i}") |> function [|x|] -> x | x -> x |> String.concat ", " |> sprintf "Union[%s]"
                line s $"US{x.tag} = {cases}"
                )
            and heap : _ -> LayoutRecPython = layout (fun s x ->
                line s $"class Heap{x.tag}(NamedTuple):"
                let s = indent s
                if x.free_vars.Length = 0 then line s "pass"
                else x.free_vars |> Array.iter (fun (L(i,t)) -> line s $"v{i} : {tyv t}")
                )
            and mut : _ -> LayoutRecPython = layout (fun s x ->
                line s "@dataclass"
                line s $"class Mut{x.tag}:"
                let s = indent s
                if x.free_vars.Length = 0 then line s "pass"
                else x.free_vars |> Array.iter (fun (L(i,t)) -> line s $"v{i} : {tyv t}")
                )
            and method : _ -> MethodRecPython =
                jp false (fun ((jp_body,key & (C(args,_))),i) ->
                    match (fst part_eval_env.join_point_method.[jp_body]).[key] with
                    | Some a, Some range, _ -> {tag=i; free_vars=rdata_free_vars args; range=range; body=a}
                    | _ -> raise_codegen_error "Compiler error: The method dictionary is malformed"
                    ) (fun s x ->
                    let method_args = x.free_vars |> Array.map (fun (L(i,t)) -> $"v{i} : {tyv t}") |> String.concat ", "
                    line s $"def method{x.tag}({method_args}) -> {tup_ty x.range}:"
                    binds_start x.free_vars (indent s) x.body
                    )
            and closure : _ -> ClosureRecPython =
                jp true (fun ((jp_body,key & (C(args,_,fun_ty))),i) ->
                    match fun_ty with
                    | YFun(domain,range,FT_Vanilla) ->
                        match (fst part_eval_env.join_point_closure.[jp_body]).[key] with
                        | Some(domain_args, body) -> {tag=i; free_vars=rdata_free_vars args; domain=domain; domain_args=data_free_vars domain_args; range=range; body=body}
                        | _ -> raise_codegen_error "Compiler error: The method dictionary is malformed"
                    | YFun _ -> raise_codegen_error "Non-standard functions are not supported in the Python backend."
                    | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."
                    ) (fun s x ->
                    let env_args = x.free_vars |> Array.map (fun (L(i,t)) -> $"env_v{i} : {tyv t}") |> String.concat ", "
                    line s $"def Closure{x.tag}({env_args}):"
                    let s = indent s
                    let inner_args = x.domain_args |> Array.map (fun (L(i,t)) -> $"v{i} : {tyv t}") |> String.concat ", "
                    line s $"def inner({inner_args}) -> {tup_ty x.range}:"
                    let _ =
                        let s = indent s
                        if x.free_vars.Length > 0 then
                            let nonlocal_args = x.free_vars |> Array.map (fun (L(i,t)) -> $"env_v{i}") |> String.concat ", "
                            line s $"nonlocal {nonlocal_args}"
                            x.free_vars |> Array.map (fun (L(i,t)) -> $"v{i} = env_v{i}") |> String.concat "; " |> line s
                        binds_start x.free_vars s x.body
                    line s "return inner"
                    )

            fun (x : TypedBind []) ->
            import "cupy as cp"
            import "numpy as np"
            from "dataclasses import dataclass"
            from "typing import NamedTuple, Union, Callable, Tuple"
            code_env.globals.Add "i8 = int; i16 = int; i32 = int; i64 = int; u8 = int; u16 = int; u32 = int; u64 = int; f32 = float; f64 = float; char = str; string = str"
            code_env.globals.Add "cuda = False"
            code_env.globals.Add ""

            let s = {text=StringBuilder(); indent=0}

            line s "def main_body():"
            binds_start [||] (indent s) x
            s.text.AppendLine() |> ignore

            line s "def main():"
            line (indent s) "r = main_body()"
            line (indent s) "if cuda: cp.cuda.get_current_stream().synchronize() # This line is here so the `__trap()` calls on the kernel aren't missed."
            line (indent s) "return r"
            s.text.AppendLine() |> ignore

            line s "if __name__ == '__main__': result = main(); None if result is None else print(result)"
            code_env.main_defs.Add(s.text.ToString())

        let codegen (default_env : DefaultEnv) (file_path : string) part_eval_env (x : TypedBind[]) : GeneratedFile list =
            let cuda_kernels = StringBuilder().AppendLine("kernel = r\"\"\"")
            let g = Dictionary(HashIdentity.Structural)

            let host_code_env = CodegenCpp.codegen_env.Create("Python", "")
            let device_code_env = CodegenCpp.codegen_env.Create("Cuda", "__device__ ")

            let cuda_codegen =
                CodegenCpp.codegen' (fun (jp_body,key,r') ->
                    raise_codegen_error_backend r' $"The Cuda backend does not support nesting of backends."
                    ) part_eval_env device_code_env
            let python_code =
                codegen' (fun (jp_body,key,r') ->
                    let backend_name = (fst jp_body).node
                    match backend_name with
                    | "Cuda" ->
                        Utils.memoize g (fun (jp_body,key & C(args,_)) ->
                            let args = rdata_free_vars args
                            match (fst part_eval_env.join_point_method.[jp_body]).[key] with
                            | Some a, Some _, _ -> cuda_codegen (CodegenCpp.Cuda(args,a))
                            | _ -> raise_codegen_error "Compiler error: The method dictionary is malformed"
                            $"entry{g.Count}"
                            ) (jp_body,key)
                    | x -> raise_codegen_error_backend r' $"The Python + Cuda backend does not support the {x} backend."
                    ) part_eval_env host_code_env x

            let append_lines (l : string seq) = (StringBuilder(), l) ||> Seq.fold (fun s -> s.AppendLine)

            let file_name = System.IO.Path.GetFileNameWithoutExtension file_path

            let aux_library_code =
                let dir f =
                    SpiralFileSystem.get_workspace_root ()
                    + "/deps/The-Spiral-Language/The Spiral Language 2"
                    |> fun x -> System.IO.Path.Join (x, f)
                    |> System.IO.File.ReadAllText
                let aux_library_code_python = dir "corelib.py"
                let aux_library_code_cuda =
                    (dir "corelib.cuh").Replace("__host__", "__device__")
                    |> CodegenCpp.replace_default_types default_env

                StringBuilder()
                    .AppendLine("kernels_aux = r\"\"\"")
                    .AppendLine(aux_library_code_cuda)
                    .AppendLine("\"\"\"")
                    .AppendLine(aux_library_code_python)
                    .ToString()
            let code_main =
                StringBuilder()
                    .AppendLine("kernels_main = r\"\"\"")
                    .Append(append_lines device_code_env.globals)
                    .AppendJoin("", device_code_env.fwd_dcls)
                    .AppendJoin("", device_code_env.types)
                    .AppendJoin("", device_code_env.functions)
                    .AppendJoin("", device_code_env.main_defs)
                    .AppendLine("\"\"\"")
                    .AppendLine($"from {file_name}_auto import *")
                    .AppendLine("kernels = kernels_aux + kernels_main")
                    .AppendLine(
                        part_eval_env.globals
                        |> Seq.append host_code_env.globals
                        |> Seq.distinct
                        |> append_lines
                        |> _.ToString()
                    )
                    .AppendLine("# fwd_dcls")
                    .AppendJoin("\n", host_code_env.fwd_dcls)
                    .AppendLine("# types")
                    .AppendJoin("", host_code_env.types)
                    .AppendLine("# functions")
                    .AppendJoin("", host_code_env.functions)
                    .AppendLine("# main_defs")
                    .AppendJoin("", host_code_env.main_defs)
                    .ToString()

            [
                {|code = aux_library_code; file_extension = "_auto.py"|}
                {|code = code_main; file_extension = ".py"|}
            ]

#endif
#if SPIRAL_CORE_HOPAC
    /// ## WDiff
    // open System
    open System.IO
    open System.Collections.Generic
    

    // Full name: Microsoft.FSharp.Core.Result<_,_>.Ok
    

    open FSharp.Core
    

    open Hopac
    open Hopac.Infixes
    open Hopac.Extensions
    open Hopac.Stream
    

    /// ### process_errors
    let process_errors line (ers : LineTokenErrors list) : RString list =
        ers |> List.mapi (fun i l ->
            let i = line + i
            l |> List.map (fun (r,x) -> x, ({|line=i; character=r.from|}, {|line=i; character=r.nearTo|}))
            )
        |> List.concat
        |> List.groupBy snd
        |> List.map (fun (k,v) -> k, process_error (List.map fst v))
    

    /// ### tokenize_replace
    /// Replaces the token lines and updates the errors given the edit.
    let tokenize_replace (lines : _ PersistentVector PersistentVector, errors : _ list) (edit : SpiEdit) =
        let toks, ers = HopacExtensions.S.map tokenize edit.lines |> Array.unzip
        let lines = replace edit.from edit.nearTo toks lines
        let errors =
            let adj = edit.lines.Length - (edit.nearTo - edit.from)
            errors |> List.choose (fun ((a : VSCPos,b),c as x) ->
                if edit.from <= a.line && a.line < edit.nearTo then None
                elif edit.nearTo <= a.line && adj <> 0 then Some (add_line_to_range adj (a,b),c)
                else Some x
                )
        let errors = List.append errors (process_errors edit.from (Array.toList ers))
        lines, errors
    

    type [<ReferenceEquality>] TokenizerState = {
        lines_text : string PersistentVector
        lines_token : LineTokens
        blocks : LineTokens Block list
        errors : RString list
        }
    

    /// ### wdiff_tokenizer_init
    let wdiff_tokenizer_init = { lines_text = PersistentVector.empty; lines_token = PersistentVector.empty; blocks = []; errors = [] }
    

    /// ### triple_balance
    let triple_balance (blk : LineTokens) =
        let count_in_line acc (line : LineToken PersistentVector) =
            PersistentVector.fold (fun acc (_, tok) ->
                match tok with
                | TokStringOpen -> acc + 1
                | TokStringClose -> acc - 1
                | _ -> acc) acc line
        PersistentVector.fold count_in_line 0 blk
    

    /// ### append_lines
    let append_lines (a : LineTokens) (b : LineTokens) : LineTokens =
        PersistentVector.fold (fun acc line -> PersistentVector.conj line acc) a b
    

    /// ### merge_triple_blocks
    let merge_triple_blocks (blocks : LineTokens Block list) : LineTokens Block list =
        let rec loop acc pending pendingBal rest =
            match pending, rest with
            | None, [] -> List.rev acc
            | Some p, [] -> List.rev (p :: acc)
            | None, x :: xs ->
                let bal = triple_balance x.block
                if bal = 0 then loop (x :: acc) None 0 xs
                else loop acc (Some x) bal xs
            | Some p, x :: xs ->
                let merged =
                    {   block  = append_lines p.block x.block
                        offset = p.offset }
                let bal = pendingBal + triple_balance x.block
                if bal = 0 then loop (merged :: acc) None 0 xs
                else loop acc (Some merged) bal xs
        loop [] None 0 blocks
    

    /// ### replace'
    /// Immutably updates the state based on the request. Does diffing to make the operation efficient.
    /// It is possible for the server to go out of sync, in which case an error is returned.
    let replace' (state : TokenizerState) (edit : SpiEdit) =
        let lines_text =
            replace edit.from edit.nearTo edit.lines state.lines_text
        // Re-lex the edited range with a fresh lexer state.
        reset_lexical_state ()
        let lines_token, errors = tokenize_replace (state.lines_token, state.errors) edit
        let blocks =
            wdiff_block_all state.blocks (lines_token, edit.lines.Length, edit.from, edit.nearTo)
            |> merge_triple_blocks
        {lines_text=lines_text; lines_token=lines_token; errors=errors; blocks=blocks}
    

    /// ### wdiff_tokenizer_all
    let wdiff_tokenizer_all (state : TokenizerState) text =
        reset_lexical_state ()
        let text = (*Utils.*)lines text
        let text' = state.lines_text |> Seq.toArray
        let rec loop (index,text : string [] as x) i = if i < min text.Length state.lines_text.Length && index text i = index text' i then loop x (i+1) else i
        let from = loop ((fun text i -> text.[i]),text) 0
        if from = text.Length && text.Length = text'.Length then state else
        if from = text.Length then
            replace' state {|from=from; nearTo=text'.Length; lines=[||]|}
        else
            let text = text.[from..]
            let fromRev = loop ((fun text i -> text.[text.Length-1-i]),text) 0
            let mid_len = text.Length - fromRev
            let mid = if mid_len <= 0 then [||] else text.[..mid_len-1]
            replace' state {|from=from; nearTo=text'.Length-fromRev; lines=mid|}
    

    /// ### wdiff_tokenizer_edit
    let wdiff_tokenizer_edit (state : TokenizerState) (edit : SpiEdit) =
        if edit.nearTo <= state.lines_text.Length then
            Ok (replace' state edit)
        else
            Error "The edit is out of bounds and cannot be applied. The language server and the editor are out of sync. Try reopening the file being edited."
    

    /// ### semantic_updates_apply
    let semantic_updates_apply (block : LineTokens) updates =
        Seq.fold (fun (block : LineTokens) (c : VectorCord, l) ->
            if c.row < block.Length then
                let line = block.[c.row]
                if c.col < line.Length then
                    let r, tok = line.[c.col]
                    let tok' =
                        match tok with
                        | TokVar(a,_) -> TokVar(a,l)
                        | TokSymbol(a,_) -> TokSymbol(a,l)
                        | TokOperator(a,_) -> TokOperator(a,l)
                        | TokUnaryOperator(a,_) -> TokUnaryOperator(a,l)
                        | x -> x
                    PersistentVector.updateNth c.row c.col (r, tok') block
                else block
            else block) block updates
    

    let private stableTokenTextField (value: string) =
        value.Length.ToString(System.Globalization.CultureInfo.InvariantCulture) + ":" + value

    let private tokenKeywordStableText (keyword: TokenKeyword) =
        match keyword with
        | SpecIn -> "SpecIn"
        | SpecAnd -> "SpecAnd"
        | SpecFun -> "SpecFun"
        | SpecMatch -> "SpecMatch"
        | SpecTypecase -> "SpecTypecase"
        | SpecFunction -> "SpecFunction"
        | SpecWith -> "SpecWith"
        | SpecWithout -> "SpecWithout"
        | SpecAs -> "SpecAs"
        | SpecWhen -> "SpecWhen"
        | SpecInl -> "SpecInl"
        | SpecForall -> "SpecForall"
        | SpecExists -> "SpecExists"
        | SpecLet -> "SpecLet"
        | SpecInm -> "SpecInm"
        | SpecInb -> "SpecInb"
        | SpecRec -> "SpecRec"
        | SpecIf -> "SpecIf"
        | SpecThen -> "SpecThen"
        | SpecElif -> "SpecElif"
        | SpecElse -> "SpecElse"
        | SpecJoin -> "SpecJoin"
        | SpecJoinBackend -> "SpecJoinBackend"
        | SpecType -> "SpecType"
        | SpecNominal -> "SpecNominal"
        | SpecReal -> "SpecReal"
        | SpecUnion -> "SpecUnion"
        | SpecOpen -> "SpecOpen"
        | SpecWildcard -> "SpecWildcard"
        | SpecPrototype -> "SpecPrototype"
        | SpecInstance -> "SpecInstance"

    let private parenthesisStateStableText (state: ParenthesisState) =
        match state with
        | Open -> "Open"
        | Close -> "Close"

    let private parenthesisStableText (shape: Parenthesis) =
        match shape with
        | Round -> "Round"
        | Square -> "Square"
        | Curly -> "Curly"

    let private macroEnumStableText (kind: MacroEnum) =
        match kind with
        | MacroEnum.MTerm -> "MTerm"
        | MacroEnum.MType -> "MType"
        | MacroEnum.MTypeLit -> "MTypeLit"
        | MacroEnum.MTermInline -> "MTermInline"

    let private literalStableText (literal: Literal) =
        let invariant = System.Globalization.CultureInfo.InvariantCulture
        match literal with
        | LitUInt8 value -> "u8:" + value.ToString(invariant)
        | LitUInt16 value -> "u16:" + value.ToString(invariant)
        | LitUInt32 value -> "u32:" + value.ToString(invariant)
        | LitUInt64 value -> "u64:" + value.ToString(invariant)
        | LitInt8 value -> "i8:" + value.ToString(invariant)
        | LitInt16 value -> "i16:" + value.ToString(invariant)
        | LitInt32 value -> "i32:" + value.ToString(invariant)
        | LitInt64 value -> "i64:" + value.ToString(invariant)
        | LitFloat32 value -> "f32:" + value.ToString("R", invariant)
        | LitFloat64 value -> "f64:" + value.ToString("R", invariant)
        | LitBool value -> if value then "bool:true" else "bool:false"
        | LitString value -> "string:" + stableTokenTextField value
        | LitChar value -> "char:" + (int value).ToString(invariant)

    let private spiralTokenStableText (token: SpiralToken) =
        let invariant = System.Globalization.CultureInfo.InvariantCulture
        let legendText (legend: SemanticTokenLegend) = (int legend).ToString(invariant)
        match token with
        | TokVar(value, legend) -> "var:" + legendText legend + ":" + stableTokenTextField value
        | TokSymbol(value, legend) -> "symbol:" + legendText legend + ":" + stableTokenTextField value
        | TokOperator(value, legend) -> "operator:" + legendText legend + ":" + stableTokenTextField value
        | TokUnaryOperator(value, legend) -> "unary_operator:" + legendText legend + ":" + stableTokenTextField value
        | TokValue value -> "value:" + literalStableText value
        | TokValueSuffix -> "value_suffix"
        | TokDefaultValue value -> "default_value:" + stableTokenTextField value
        | TokComment value -> "comment:" + stableTokenTextField value
        | TokKeyword value -> "keyword:" + tokenKeywordStableText value
        | TokParenthesis(shape, state) -> "parenthesis:" + parenthesisStableText shape + ":" + parenthesisStateStableText state
        | TokStringOpen -> "string_open"
        | TokStringClose -> "string_close"
        | TokText value -> "text:" + stableTokenTextField value
        | TokEscapedChar value -> "escaped_char:" + (int value).ToString(invariant)
        | TokEscapedVar -> "escaped_var"
        | TokUnescapedChar value -> "unescaped_char:" + (int value).ToString(invariant)
        | TokMacroOpen -> "macro_open"
        | TokMacroClose -> "macro_close"
        | TokMacroTermVar(value, isInline) -> "macro_term_var:" + (if isInline then "inline:" else "normal:") + stableTokenTextField value
        | TokMacroTypeVar value -> "macro_type_var:" + stableTokenTextField value
        | TokMacroTypeLitVar value -> "macro_type_lit_var:" + stableTokenTextField value
        | TokMacroExpression(kind, state) -> "macro_expression:" + macroEnumStableText kind + ":" + parenthesisStateStableText state

    let private lineTokensStableIdentityParts (block: LineTokens) =
        let invariant = System.Globalization.CultureInfo.InvariantCulture
        seq {
            yield "line_count=" + block.Length.ToString(invariant)
            for lineIndex in 0 .. block.Length - 1 do
                let line = block.[lineIndex]
                yield "line=" + lineIndex.ToString(invariant) + "|token_count=" + line.Length.ToString(invariant)
                for tokenIndex in 0 .. line.Length - 1 do
                    let range, token = line.[tokenIndex]
                    yield
                        "token=" + lineIndex.ToString(invariant) + ":" + tokenIndex.ToString(invariant)
                        + "|from=" + range.from.ToString(invariant)
                        + "|near_to=" + range.nearTo.ToString(invariant)
                        + "|payload=" + stableTokenTextField (spiralTokenStableText token)
        }

    /// ### parse_block
    let parse_block default_env is_top_down (block : LineTokens) =
        let comments, cords_tokens =
            Array.init block.Length (fun line ->
                let x = block.[line]
                let comment, len =
                    match PersistentVector.tryLast x with
                    | Some (r, TokComment c) -> Some (r, c), x.Length - 1
                    | _ -> None, x.Length
                let tokens = Array.init len (fun i ->
                    let r, t = x.[i]
                    {|row=line; col=i|},
                    (({| line=line; character=r.from |}, {| line=line; character=r.nearTo |}), t))
                comment, tokens
                )
            |> Array.unzip
        let cords, tokens = Array.unzip (Array.concat cords_tokens)
    

        let semantic_updates = ResizeArray()
        let env = {
            tokens_cords = cords; semantic_updates = semantic_updates
            comments = comments; tokens = tokens; i = ref 0; is_top_down = is_top_down
            default_env = default_env
            }
        assert (env.tokens_cords.Length = env.tokens.Length)
        let result = blockParsingParse env
        match result with
        | Ok statement ->
            // Content-keyed identity prevents incremental reparses from double-counting
            // a structurally unchanged block merely because it arrived as a new object.
            let blockRef = NativeCutoverStableRef.ref32 "build-trace-block" (lineTokensStableIdentityParts block)
            statement
            |> parsedAstSeedOfTopStatement
            |> DiagJson.noteParsedAstStructuralSeed blockRef
            |> ignore
        | Error _ -> ()
        {result=result; semantic_tokens=semantic_updates_apply block semantic_updates}
    

    /// ### wdiff_parse_init
    let wdiff_parse_init is_top_down : ParserState = {is_top_down=is_top_down; blocks=[]}
    

    /// ### wdiff_parse
    let wdiff_parse default_env (state : ParserState) (unparsed_blocks : LineTokens Block list) =
        let dict = Collections.Concurrent.ConcurrentDictionary(HashIdentity.Reference)
        // Offset should be ignored when memoizing the results of parsing.
        List.iter (fun (a,b) -> dict.TryAdd(a,b.block) |> ignore) state.blocks
        let blocks = unparsed_blocks |> List.map (fun x ->
            x.block, {block=memoize dict (fun a -> Promise.Now.withValue ((parse_block default_env state.is_top_down) a)) x.block; offset=x.offset}
            )
        {state with blocks = blocks }
    

    /// ### ModuleState
    type ModuleState = { tokenizer : TokenizerState; bundler : BlockBundleState; parser : ParserState }
    

    /// ### wdiff_module_init
    let wdiff_module_init is_top_down = {tokenizer = wdiff_tokenizer_init; bundler = wdiff_block_bundle_init; parser = wdiff_parse_init is_top_down}
    

    /// ### wdiff_module_body
    let wdiff_module_body default_env state tokenizer =
        if state.tokenizer = tokenizer then state else
        let parser = wdiff_parse default_env state.parser tokenizer.blocks
        let bundler = wdiff_block_bundle state.bundler parser
        {tokenizer=tokenizer; parser=parser; bundler=bundler}
    

    /// ### wdiff_module_edit
    let wdiff_module_edit default_env (state : ModuleState) x = wdiff_tokenizer_edit state.tokenizer x |> Result.map (wdiff_module_body default_env state)
    

    /// ### wdiff_module_all
    let wdiff_module_all default_env state x = wdiff_tokenizer_all state.tokenizer x |> wdiff_module_body default_env state
    

    /// ### wdiff_module_init_all
    let wdiff_module_init_all default_env is_top_down x = wdiff_module_all default_env (wdiff_module_init is_top_down) x
    

    /// ### FileState<'input,'result,'state>
    type [<ReferenceEquality>] FileState<'input,'result,'state> = { input : 'input; result : 'result; state : 'state }
    

    /// ### FileFuns<'a,'b,'state>
    type FileFuns<'a,'b,'state> =
        abstract member eval : 'state * 'a -> 'b
        abstract member diff : 'state * 'b * 'a -> 'b
        abstract member init : 'a -> FileState<'a,'b,'state>
    

    /// ### TypecheckerStateValue
    type TypecheckerStateValue = Bundle option * InferResult * TopEnv
    

    /// ### TypecheckerStatePropagated
    type TypecheckerStatePropagated = (bool * TopEnv) Promise
    

    /// ### TypecheckerState
    type TypecheckerState = FileState<PackageId * ModuleId * BlockBundleState, TypecheckerStateValue Stream, TypecheckerStatePropagated>
    

    /// ### typecheck
    let rec typecheck (package_id,module_id,env : TopEnv) x = x >>=* function
        | Cons((_,b : BlockBundleValue), ls) ->
            match b.bundle with
            | Some bundle ->
                let x = infer package_id module_id env bundle
                let adds = match x.top_env_additions with AOpen x | AInclude x -> x
                let env = inferUnion adds env
                Job.result (Cons((b.bundle,x,env),typecheck (package_id,module_id,env) ls))
            | None ->
                typecheck (package_id,module_id,env) ls :> _ Job
        | Nil ->
            Job.result Nil
    

    /// ### diff
    let rec diff (package_id,module_id,env) (result,input : BlockBundleState) =
        let tc () = typecheck (package_id,module_id,env) input
        if Promise.Now.isFulfilled result then
            input >>** fun input ->
            match Promise.Now.get result,input with
            | Cons((b',_,env as x),next), Cons((_,b),bs) when b' = b.bundle -> Promise.Now.withValue (Cons(x,diff (package_id,module_id,env) (next,bs)))
            | _ -> tc()
        else tc()
    

    /// ### funs_file_tc
    let funs_file_tc = {new FileFuns<PackageId * ModuleId * BlockBundleState, TypecheckerStateValue Stream, TypecheckerStatePropagated> with
        member _.eval(state,(pid,mid,x)) =
            state >>=* fun (_,env) ->
            typecheck (pid,mid,env) x
        member _.diff(state,b,(pid,mid,a)) =
            state >>=* fun (_,env) -> diff (pid,mid,env) (b,a)
        member _.init x = {
            input = x
            result = Promise.Now.never()
            state = Promise.Now.never()
            }
        }
    

    /// ### wdiff_file_update_state
    let wdiff_file_update_state (funs : FileFuns<'a,'b,'state>) (state : FileState<'a,'b,'state>) (x : 'state) =
        if state.state = x then state else {state with state=x; result=funs.eval(x,state.input)}
    

    /// ### wdiff_file_update_input
    let wdiff_file_update_input (funs : FileFuns<'a,'b,'state>) (state : FileState<'a,'b,'state>) (x : 'a) =
        if state.input = x then state else {state with input=x; result=funs.diff(state.state,state.result,x)}
    

    /// ### wdiff_file
    let wdiff_file (funs : FileFuns<'a,'b,'state>) (state : FileState<'a,'b,'state>) (a,b) =
        if state.state = a then wdiff_file_update_input funs state b else {state=a; input=b; result=funs.eval(a,b)}
    

    /// ### ProjFilesTree
    type ProjFilesTree =
        | File of module_id: ModuleId * path: string * name: string option
        | Directory of dir_id: DirId * name: string * ProjFilesTree list
    

    /// ### ProjFiles
    type ProjFiles = { tree : ProjFilesTree list; num_dirs : int; num_files : int }
    

    /// ### ProjFileFuns<'a,'state>
    type ProjFileFuns<'a,'state> =
        abstract member file : string option * 'state * 'a -> 'a * 'state
        abstract member union : 'state * 'state -> 'state
        abstract member in_module : string * 'state -> 'state
        abstract member default' : DefaultEnv -> 'state
        abstract member empty : 'state
    

    /// ### ProjFilesState<'a,'state>
    type [<ReferenceEquality>] ProjFilesState<'a,'state> = {
        init : 'state
        uids_file : ('a * 'state) []
        uids_directory : 'state []
        files : ProjFiles
        result : 'state
        }
    

    /// ### proj_files_diff
    let proj_files_diff (uids_file : ('a * 'b) [], uids_directory : 'b [], files) (uids, files') =
        let uids_file' = Array.zeroCreate (Array.length uids)
        let uids_directory' = Array.zeroCreate files'.num_dirs
        // Ref equality is done first for performance. Most of the time the strings will be the same.
        let eq a b = System.Object.ReferenceEquals(a,b) || a = b
        let rec loop = function
            | File(mid,path,name), File(mid',path',name') when mid = mid' && eq path path' && eq name name' ->
                let x = uids_file.[mid]
                if uids.[mid] = fst x then uids_file'.[mid] <- x; true else false
            | Directory(uid,name,l), Directory(uid',name',l') when uid = uid' && eq name name' && list (l,l') ->
                uids_directory'.[uid] <- uids_directory.[uid]; true
            | _ -> false
        and list = function
            | x :: xs, y :: ys -> loop (x,y) && list (xs,ys)
            | _ -> false
        if list (files.tree, files'.tree) then None else Some (uids_file',uids_directory')
    

    /// ### proj_files
    let proj_files (funs : ProjFileFuns<'a,'state>) uids_file uids_directory uids s l =
        let memo (uids : _ []) uid f =
            let x = uids.[uid]
            if isNull (box x) then let x = f() in uids.[uid] <- x; x
            else x
        let rec loop state = function
            | File(mid,_,name) -> memo uids_file mid (fun () -> funs.file(name,state,Array.get uids mid)) |> snd
            | Directory(uid,name,l) -> memo uids_directory uid (fun () -> funs.in_module(name,list state l))
        and list s l =
            List.fold (fun (empty,big) x ->
                let small = loop big x
                funs.union(small,empty), funs.union(small,big)
                ) (funs.empty, s) l |> fst
        list s l.tree
    

    /// ### wdiff_proj_files_update_files
    let wdiff_proj_files_update_files (funs : ProjFileFuns<'a,'state>) (state : ProjFilesState<'a,'state >) (uids,files : ProjFiles) =
        match proj_files_diff (state.uids_file,state.uids_directory,state.files) (uids,files) with
        | Some (uids_file, uids_directory) -> {state with files=files; uids_file=uids_file; uids_directory=uids_directory; result=proj_files funs uids_file uids_directory uids state.init files}
        | None -> state
    

    /// ### wdiff_proj_files_update_packages
    let wdiff_proj_files_update_packages (funs : ProjFileFuns<'a,'state>) (state : ProjFilesState<'a,'state >) (init : 'state) =
        if state.init = init then state else
        let uids_file, uids_directory = Array.zeroCreate state.uids_file.Length, Array.zeroCreate state.uids_directory.Length
        let uids = HopacExtensions.S.map fst state.uids_file
        {state with init=init; uids_file=uids_file; uids_directory=uids_directory; result=proj_files funs uids_file uids_directory uids init state.files}
    

    /// ### wdiff_proj_files
    let wdiff_proj_files (funs : ProjFileFuns<'a,'state>) (state : ProjFilesState<'a,'state >) (init,(uids,files)) =
        if state.init = init then wdiff_proj_files_update_files funs state (uids,files)
        else
            let uids_file, uids_directory = Array.zeroCreate files.num_files, Array.zeroCreate files.num_dirs
            {files=files; init=init; uids_file=uids_file; uids_directory=uids_directory; result=proj_files funs uids_file uids_directory uids init files}
    

    /// ### typechecker_results_summary
    let typechecker_results_summary l =
        Stream.foldFun (fun (has_error,big) (_,x : InferResult,_) ->
            has_error || List.isEmpty x.errors = false,
            match x.top_env_additions with
            | AOpen _ -> big
            | AInclude small -> inferUnion small big
            ) (false,inferTop_env_empty) l
    

    /// ### funs_proj_file_tc
    let funs_proj_file_tc = {new ProjFileFuns<TypecheckerState,TypecheckerStatePropagated> with
        member _.file(name,state,x) =
            let x = wdiff_file_update_state funs_file_tc x state
            let env =
                typechecker_results_summary x.result >>-* fun (has_error,env) ->
                has_error, match name with None -> env | Some name -> inferIn_module name env
            x,env
        member _.union(small,big) = small >>=* fun small -> big >>- fun big -> fst small || fst big, inferUnion (snd small) (snd big)
        member _.in_module(name,small) = small >>-* fun (has_error,env) -> has_error, inferIn_module name env
        member _.default' default_env = Promise.Now.withValue (false,inferTop_env_default default_env)
        member _.empty = Promise.Now.withValue (false,inferTop_env_empty)
        }
    

    /// ### PackageEnv
    type PackageEnv = {
        nominals_aux : Map<PackageId,Map<GlobalId, {|name : NominalNameId; kind : TT|}>>
        nominals : Map<PackageId,Map<GlobalId, {|vars : Var list; body : T|}>>
        prototypes_instances : Map<PackageId,Map<GlobalId * GlobalId, Constraint Set list>>
        prototypes : Map<PackageId,Map<GlobalId, {|name : PrototypeNameId; signature : T; kind : TT|}>>
        ty : Map<TypeNameId,T>
        term : Map<TermNameId,T>
        constraints : Map<ConstraintNameId,ConstraintOrModule>
        }
    

    /// ### union
    let union small big = {
        nominals_aux = Map.foldBack Map.add small.nominals_aux big.nominals_aux
        nominals = Map.foldBack Map.add small.nominals big.nominals
        prototypes_instances = Map.foldBack Map.add small.prototypes_instances big.prototypes_instances
        prototypes = Map.foldBack Map.add small.prototypes big.prototypes
        ty = Map.foldBack Map.add small.ty big.ty
        term = Map.foldBack Map.add small.term big.term
        constraints = Map.foldBack Map.add small.constraints big.constraints
        }
    

    /// ### in_moduleWDiff
    let in_moduleWDiff m (a : PackageEnv) =
        {a with
            ty = Map.add (TypeNameIdOps.create m) (TyModule (typeMapToModuleMembers a.ty)) Map.empty
            term = Map.add (TermNameIdOps.create m) (TyModule (termMapToModuleMembers a.term)) Map.empty
            constraints = Map.add (ConstraintNameIdOps.create m) (M a.constraints) Map.empty
            }
    

    /// ### package_to_file
    let package_to_file (x : PackageEnv) = {
        nominals_next_tag = 0
        nominals_aux = Map.foldBack (fun _ -> Map.foldBack Map.add) x.nominals_aux Map.empty
        nominals = Map.foldBack (fun _ -> Map.foldBack Map.add) x.nominals Map.empty
        prototypes_next_tag = 0
        prototypes_instances = Map.foldBack (fun _ -> Map.foldBack Map.add) x.prototypes_instances Map.empty
        prototypes = Map.foldBack (fun _ -> Map.foldBack Map.add) x.prototypes Map.empty
        ty = x.ty
        term = x.term
        constraints = x.constraints
        }
    

    /// ### add_file_to_package
    let add_file_to_package package_id (small : TopEnv) (big : PackageEnv): PackageEnv = {
        nominals_aux = Map.add package_id small.nominals_aux big.nominals_aux
        nominals = Map.add package_id small.nominals big.nominals
        prototypes_instances = Map.add package_id small.prototypes_instances big.prototypes_instances
        prototypes = Map.add package_id small.prototypes big.prototypes
        ty = small.ty
        term = small.term
        constraints = small.constraints
        }
    

    /// ### package_env_empty
    let package_env_empty = {
        nominals_aux = Map.empty
        nominals = Map.empty
        prototypes_instances = Map.empty
        prototypes = Map.empty
        ty = Map.empty
        term = Map.empty
        constraints = Map.empty
        }
    

    /// ### package_env_default
    let package_env_default default_env =
        let x = inferTop_env_default default_env
        {package_env_empty with ty = x.ty; term = x.term; constraints = x.constraints}
    

    /// ### ProjPackagesState<'a>
    type ProjPackagesState<'a> = {
        packages : (string option * 'a) list
        result : 'a
        }
    

    /// ### ProjState<'file_inputs,'files,'packages>
    type ProjState<'file_inputs,'files,'packages> = {
        package_id : PackageId
        packages : 'packages ProjPackagesState
        files : ProjFilesState<'file_inputs,'files>
        result : 'packages
        }
    

    /// ### TypecheckerStateTop
    type TypecheckerStateTop = (bool * PackageEnv) Promise
    

    /// ### ProjStateTC
    type ProjStateTC = ProjState<TypecheckerState,TypecheckerStatePropagated,TypecheckerStateTop>
    

    /// ### ProjEnvTC
    type ProjEnvTC = Map<PackageId,ProjStateTC>
    

    /// ### ProjPackageFuns<'file,'package>
    type ProjPackageFuns<'file,'package> =
        abstract member unions : DefaultEnv -> (string option * 'package) list -> 'package
        abstract member union : 'package * 'package -> 'package
        abstract member in_module : string * 'package -> 'package
        abstract member package_to_file : 'package -> 'file
        abstract member add_file_to_package : PackageId * 'file * 'package -> 'package
        abstract member default' : DefaultEnv -> 'package
        abstract member empty : 'package
    

    /// ### funs_proj_package_tc
    let funs_proj_package_tc = {new ProjPackageFuns<TypecheckerStatePropagated,TypecheckerStateTop> with
        member funs.unions default_env l =
            let f = function Some name, small -> funs.in_module(name,small) | None, small -> small
            List.fold (fun big x -> funs.union(f x,big)) (funs.default' default_env) l
        member _.union(small,big) =
            Job.delay <| fun () ->
                if Promise.Now.isFulfilled big = false then HopacExtensions.start (big >>- ignore)
                small >>= fun a ->
                big >>- fun b ->
                fst a || fst b, union (snd a) (snd b)
            |> Hopac.memo
        member _.in_module(name,x) = x >>-* fun (has_error,env) -> has_error, in_moduleWDiff name env
        member _.package_to_file(x) = x >>-* fun (has_error,env) -> has_error, package_to_file env
        member _.add_file_to_package(pid,a,b) =
            a >>=* fun (has_error,env) ->
            b >>-* fun (has_error',env') ->
            has_error || has_error', add_file_to_package pid env env'
        member _.default' default_env = Promise.Now.withValue (false, package_env_default default_env)
        member _.empty = Promise.Now.withValue (false, package_env_empty)
        }
    

    /// ### wdiff_proj_init
    let wdiff_proj_init default_env (funs_packages : ProjPackageFuns<'file,'package>) (funs_files : ProjFileFuns<'file_input,'file>) package_id : ProjState<'file_input,'file,'package> =
        let packages = { packages = []; result = funs_packages.default' default_env}
        let files = {
            files={tree=[]; num_dirs=0; num_files=0}
            uids_file=[||]; uids_directory=[||]
            init=funs_files.default' default_env; result=funs_files.empty
            }
        let result = funs_packages.empty
        { package_id = package_id; packages = packages; files = files; result = result}
    

    /// ### wdiff_proj_packages
    let wdiff_proj_packages default_env (funs : ProjPackageFuns<_,'a>) (state : 'a ProjPackagesState) x =
        if state.packages = x then state else {packages = x; result = funs.unions default_env x }
    

    /// ### wdiff_proj_update_packages
    let wdiff_proj_update_packages default_env funs_packages funs_files (state : ProjState<'a,'b,'state>) x =
        let packages = wdiff_proj_packages default_env funs_packages state.packages x
        if state.packages = packages then state else
        let files = wdiff_proj_files_update_packages funs_files state.files (funs_packages.package_to_file(packages.result))
        let result = funs_packages.add_file_to_package(state.package_id,files.result,packages.result)
        {state with packages=packages; files=files; result=result}
    

    /// ### wdiff_proj_update_files
    let wdiff_proj_update_files (funs_packages : ProjPackageFuns<_,_>) funs_files (state : ProjState<'a,'b,'state>) x =
        let files = wdiff_proj_files_update_files funs_files state.files x
        if state.files = files then state else
        let result = funs_packages.add_file_to_package(state.package_id,files.result,state.packages.result)
        {state with files=files; result=result}
    

    /// ### wdiff_proj
    let wdiff_proj default_env (funs_packages : ProjPackageFuns<_,_>) funs_files (state : ProjState<'file_input,'file,'state>) (packages,files) =
        let packages = wdiff_proj_packages default_env funs_packages state.packages packages
        if state.packages = packages then wdiff_proj_update_files funs_packages funs_files state files
        else
            let files = wdiff_proj_files funs_files state.files (funs_packages.package_to_file(packages.result),files)
            let result = funs_packages.add_file_to_package(state.package_id,files.result,packages.result)
            {state with packages=packages; files=files; result=result}
    

    /// ### ProjEnvUpdate<'a>
    type ProjEnvUpdate<'a> =
        | UpdatePackageModule of PackageId * (string option * PackageId) list * ('a [] * ProjFiles)
        | UpdatePackage of PackageId * (string option * PackageId) list
    

    /// ### map_packages
    let map_packages s packages = packages |> List.map (fun (a,b) -> a, (Map.find b s).result)
    

    /// ### wdiff_projenv
    let wdiff_projenv default_env funs_packages funs_files (s : Map<PackageId,ProjState<'a,'b,'state>>) l =
        List.fold (fun s -> function
            | UpdatePackageModule(uid,packages,files) -> Map.add uid (wdiff_proj default_env funs_packages funs_files s.[uid] (map_packages s packages,files)) s
            | UpdatePackage(uid,packages) -> Map.add uid (wdiff_proj_update_packages default_env funs_packages funs_files s.[uid] (map_packages s packages)) s
            ) s l
    

#else
    /// ## WDiff
    // open System
    open System.IO
    open System.Collections.Generic

    // Full name: Microsoft.FSharp.Core.Result<_,_>.Ok

    open FSharp.Core

    open Hopac
    open Hopac.Infixes
    open Hopac.Extensions
    open Hopac.Stream

    /// ### process_errors
    let process_errors line (ers : LineTokenErrors list) : RString list =
        ers |> List.mapi (fun i l ->
            let i = line + i
            l |> List.map (fun (r,x) -> x, (vscpos i r.from, vscpos i r.nearTo))
            )
        |> List.concat
        |> List.groupBy snd
        |> List.map (fun (k,v) -> k, process_error (List.map fst v))

    /// ### tokenize_replace
    /// Replaces the token lines and updates the errors given the edit.
    let tokenize_replace (lines : _ PersistentVector PersistentVector, errors : _ list) (edit : SpiEdit) =
        let toks, ers = Array.map tokenize edit.lines |> Array.unzip
        let lines = replace edit.from edit.nearTo toks lines
        let errors =
            let adj = edit.lines.Length - (edit.nearTo - edit.from)
            errors |> List.choose (fun ((a : VSCPos,b),c as x) ->
                if edit.from <= a.line && a.line < edit.nearTo then None
                elif edit.nearTo <= a.line && adj <> 0 then Some (add_line_to_range adj (a,b),c)
                else Some x
                )
        let errors = List.append errors (process_errors edit.from (Array.toList ers))
        lines, errors

    type [<ReferenceEquality>] TokenizerState = {
        lines_text : string PersistentVector
        lines_token : LineTokens
        blocks : LineTokens Block list
        errors : RString list
        }

    /// ### wdiff_tokenizer_init
    let wdiff_tokenizer_init = { lines_text = PersistentVector.empty; lines_token = PersistentVector.empty; blocks = []; errors = [] }

    /// ### triple_balance
    let triple_balance (blk : LineTokens) =
        let count_in_line acc (line : LineToken PersistentVector) =
            PersistentVector.fold (fun acc (_, tok) ->
                match tok with
                | TokStringOpen -> acc + 1
                | TokStringClose -> acc - 1
                | _ -> acc) acc line
        PersistentVector.fold count_in_line 0 blk

    /// ### append_lines
    let append_lines (a : LineTokens) (b : LineTokens) : LineTokens =
        PersistentVector.fold (fun acc line -> PersistentVector.conj line acc) a b

    /// ### merge_triple_blocks
    let merge_triple_blocks (blocks : LineTokens Block list) : LineTokens Block list =
        let rec loop acc pending pendingBal rest =
            match pending, rest with
            | None, [] -> List.rev acc
            | Some p, [] -> List.rev (p :: acc)
            | None, x :: xs ->
                let bal = triple_balance x.block
                if bal = 0 then loop (x :: acc) None 0 xs
                else loop acc (Some x) bal xs
            | Some p, x :: xs ->
                let merged =
                    {   block  = append_lines p.block x.block
                        offset = p.offset }
                let bal = pendingBal + triple_balance x.block
                if bal = 0 then loop (merged :: acc) None 0 xs
                else loop acc (Some merged) bal xs
        loop [] None 0 blocks

    /// ### replace'
    /// Immutably updates the state based on the request. Does diffing to make the operation efficient.
    /// It is possible for the server to go out of sync, in which case an error is returned.
    let replace' (state : TokenizerState) (edit : SpiEdit) =
        let lines_text =
            replace edit.from edit.nearTo edit.lines state.lines_text
        // Re-lex the edited range with a fresh lexer state.
        reset_lexical_state ()
        let lines_token, errors = tokenize_replace (state.lines_token, state.errors) edit
        let blocks =
            wdiff_block_all state.blocks (lines_token, edit.lines.Length, edit.from, edit.nearTo)
            |> merge_triple_blocks
        {lines_text=lines_text; lines_token=lines_token; errors=errors; blocks=blocks}

    /// ### wdiff_tokenizer_all
    let wdiff_tokenizer_all (state : TokenizerState) text =
        reset_lexical_state ()
        let text = (*Utils.*)lines text
        let text' = state.lines_text |> Seq.toArray
        let rec loop (index,text : string [] as x) i = if i < min text.Length state.lines_text.Length && index text i = index text' i then loop x (i+1) else i
        let from = loop ((fun text i -> text.[i]),text) 0
        if from = text.Length then state else
        let text = text.[from..]
        let fromRev = loop ((fun text i -> text.[text.Length-1-i]),text) 0
        replace' state {|from=from; nearTo=text'.Length-fromRev; lines=text.[..text.Length-1-fromRev]|}

    /// ### wdiff_tokenizer_edit
    let wdiff_tokenizer_edit (state : TokenizerState) (edit : SpiEdit) =
        if edit.nearTo <= state.lines_text.Length then
            let lines_text =
                replace edit.from edit.nearTo edit.lines state.lines_text

            let sb = System.Text.StringBuilder()
            let last = lines_text.Length - 1
            for i = 0 to last do
                if i > 0 then sb.Append('\n') |> ignore
                sb.Append(lines_text.[i] : string) |> ignore
            let full_text = sb.ToString()

            Ok (wdiff_tokenizer_all wdiff_tokenizer_init full_text)
        else
            Error "The edit is out of bounds and cannot be applied. The language server and the editor are out of sync. Try reopening the file being edited."

    /// ### semantic_updates_apply
    let semantic_updates_apply (block : LineTokens) updates =
        Seq.fold (fun (block : LineTokens) (c : VectorCord, l) ->
            if c.row < block.Length then
                let line = block.[c.row]
                if c.col < line.Length then
                    let r, tok = line.[c.col]
                    let tok' =
                        match tok with
                        | TokVar(a,_) -> TokVar(a,l)
                        | TokSymbol(a,_) -> TokSymbol(a,l)
                        | TokOperator(a,_) -> TokOperator(a,l)
                        | TokUnaryOperator(a,_) -> TokUnaryOperator(a,l)
                        | x -> x
                    PersistentVector.updateNth c.row c.col (r, tok') block
                else block
            else block) block updates

    /// ### parse_block
    let parse_block default_env is_top_down (block : LineTokens) =
        let comments, cords_tokens =
            Array.init block.Length (fun line ->
                let x = block.[line]
                let comment, len =
                    match PersistentVector.tryLast x with
                    | Some (r, TokComment c) -> Some (r, c), x.Length - 1
                    | _ -> None, x.Length
                let tokens = Array.init len (fun i ->
                    let r, t = x.[i]
                    vector_cord line i,
                    ((vscpos line r.from, vscpos line r.nearTo), t))
                comment, tokens
                )
            |> Array.unzip
        let cords, tokens = Array.unzip (Array.concat cords_tokens)

        let semantic_updates = ResizeArray()
        let env = {
            tokens_cords = cords; semantic_updates = semantic_updates
            comments = comments; tokens = tokens; i = ref 0; is_top_down = is_top_down
            default_env = default_env
            }
        assert (env.tokens_cords.Length = env.tokens.Length)
        {result=blockParsingParse env; semantic_tokens=semantic_updates_apply block semantic_updates}

    /// ### wdiff_parse_init
    let wdiff_parse_init is_top_down : ParserState = {is_top_down=is_top_down; blocks=[]}

    /// ### wdiff_parse
    let wdiff_parse default_env (state : ParserState) (unparsed_blocks : LineTokens Block list) =
        let dict = Dictionary(HashIdentity.Reference)
        // Offset should be ignored when memoizing the results of parsing.
        List.iter (fun (a,b) -> dict.Add(a,b.block)) state.blocks
        let blocks = unparsed_blocks |> List.map (fun x ->
            x.block, {block=memoize dict (fun a -> Hopac.memo(Job.thunk <| fun () -> (parse_block default_env state.is_top_down) a)) x.block; offset=x.offset}
            )
        {state with blocks = blocks }

    /// ### ModuleState
    type ModuleState = { tokenizer : TokenizerState; bundler : BlockBundleState; parser : ParserState }

    /// ### wdiff_module_init
    let wdiff_module_init is_top_down = {tokenizer = wdiff_tokenizer_init; bundler = wdiff_block_bundle_init; parser = wdiff_parse_init is_top_down}

    /// ### wdiff_module_body
    let wdiff_module_body default_env state tokenizer =
        if state.tokenizer = tokenizer then state else
        let parser = wdiff_parse default_env state.parser tokenizer.blocks
        let bundler = wdiff_block_bundle state.bundler parser
        {tokenizer=tokenizer; parser=parser; bundler=bundler}

    /// ### wdiff_module_edit
    let wdiff_module_edit default_env (state : ModuleState) x = wdiff_tokenizer_edit state.tokenizer x |> Result.map (wdiff_module_body default_env state)

    /// ### wdiff_module_all
    let wdiff_module_all default_env state x = wdiff_tokenizer_all state.tokenizer x |> wdiff_module_body default_env state

    /// ### wdiff_module_init_all
    let wdiff_module_init_all default_env is_top_down x = wdiff_module_all default_env (wdiff_module_init is_top_down) x

    /// ### FileState<'input,'result,'state>
    type [<ReferenceEquality>] FileState<'input,'result,'state> = { input : 'input; result : 'result; state : 'state }

    /// ### FileFuns<'a,'b,'state>
    type FileFuns<'a,'b,'state> =
        abstract member eval : 'state * 'a -> 'b
        abstract member diff : 'state * 'b * 'a -> 'b
        abstract member init : 'a -> FileState<'a,'b,'state>

    /// ### TypecheckerStateValue
    type TypecheckerStateValue = Bundle option * InferResult * TopEnv

    /// ### TypecheckerStatePropagated
    type TypecheckerStatePropagated = (bool * TopEnv) Promise

    /// ### TypecheckerState
    type TypecheckerState = FileState<PackageId * ModuleId * BlockBundleState, TypecheckerStateValue Stream, TypecheckerStatePropagated>

    /// ### typecheck
    let rec typecheck (package_id,module_id,env : TopEnv) x = x >>=* function
        | Cons((_,b : BlockBundleValue), ls) ->
            match b.bundle with
            | Some bundle ->
                let x = infer package_id module_id env bundle
                let adds = match x.top_env_additions with AOpen x | AInclude x -> x
                let env = inferUnion adds env
                Job.result (Cons((b.bundle,x,env),typecheck (package_id,module_id,env) ls))
            | None ->
                typecheck (package_id,module_id,env) ls :> _ Job
        | Nil ->
            Job.result Nil

    /// ### diff
    let rec diff (package_id,module_id,env) (result,input : BlockBundleState) =
        let tc () = typecheck (package_id,module_id,env) input
        if Promise.Now.isFulfilled result then
            input >>** fun input ->
            match Promise.Now.get result,input with
            | Cons((b',_,env as x),next), Cons((_,b),bs) when b' = b.bundle -> Promise.Now.withValue (Cons(x,diff (package_id,module_id,env) (next,bs)))
            | _ -> tc()
        else tc()

    /// ### funs_file_tc
    let funs_file_tc = {new FileFuns<PackageId * ModuleId * BlockBundleState, TypecheckerStateValue Stream, TypecheckerStatePropagated> with
        member _.eval(state,(pid,mid,x)) =
            state >>=* fun (_,env) ->
            typecheck (pid,mid,env) x
        member _.diff(state,b,(pid,mid,a)) =
            state >>=* fun (_,env) -> diff (pid,mid,env) (b,a)
        member _.init x = {
            input = x
            result = Promise.Now.never()
            state = Promise.Now.never()
            }
        }

    /// ### wdiff_file_update_state
    let wdiff_file_update_state (funs : FileFuns<'a,'b,'state>) (state : FileState<'a,'b,'state>) (x : 'state) =
        if state.state = x then state else {state with state=x; result=funs.eval(x,state.input)}

    /// ### wdiff_file_update_input
    let wdiff_file_update_input (funs : FileFuns<'a,'b,'state>) (state : FileState<'a,'b,'state>) (x : 'a) =
        if state.input = x then state else {state with input=x; result=funs.diff(state.state,state.result,x)}

    /// ### wdiff_file
    let wdiff_file (funs : FileFuns<'a,'b,'state>) (state : FileState<'a,'b,'state>) (a,b) =
        if state.state = a then wdiff_file_update_input funs state b else {state=a; input=b; result=funs.eval(a,b)}

    /// ### ProjFilesTree
    type ProjFilesTree =
        | File of module_id: ModuleId * path: string * name: string option
        | Directory of dir_id: DirId * name: string * ProjFilesTree list

    /// ### ProjFiles
    type ProjFiles = { tree : ProjFilesTree list; num_dirs : int; num_files : int }

    /// ### ProjFileFuns<'a,'state>
    type ProjFileFuns<'a,'state> =
        abstract member file : string option * 'state * 'a -> 'a * 'state
        abstract member union : 'state * 'state -> 'state
        abstract member in_module : string * 'state -> 'state
        abstract member default' : DefaultEnv -> 'state
        abstract member empty : 'state

    /// ### ProjFilesState<'a,'state>
    type [<ReferenceEquality>] ProjFilesState<'a,'state> = {
        init : 'state
        uids_file : ('a * 'state) []
        uids_directory : 'state []
        files : ProjFiles
        result : 'state
        }

    /// ### proj_files_diff
    let proj_files_diff (uids_file : ('a * 'b) [], uids_directory : 'b [], files) (uids, files') =
        let uids_file' = Array.zeroCreate (Array.length uids)
        let uids_directory' = Array.zeroCreate files'.num_dirs
        // Ref equality is done first for performance. Most of the time the strings will be the same.
        let eq a b = System.Object.ReferenceEquals(a,b) || a = b
        let rec loop = function
            | File(mid,path,name), File(mid',path',name') when mid = mid' && eq path path' && eq name name' ->
                let x = uids_file.[mid]
                if uids.[mid] = fst x then uids_file'.[mid] <- x; true else false
            | Directory(uid,name,l), Directory(uid',name',l') when uid = uid' && eq name name' && list (l,l') ->
                uids_directory'.[uid] <- uids_directory.[uid]; true
            | _ -> false
        and list = function
            | x :: xs, y :: ys -> loop (x,y) && list (xs,ys)
            | _ -> false
        if list (files.tree, files'.tree) then None else Some (uids_file',uids_directory')

    /// ### proj_files
    let proj_files (funs : ProjFileFuns<'a,'state>) uids_file uids_directory uids s l =
        let inline memo (uids : _ []) uid f =
            let x = uids.[uid]
            if isNull (box x) then let x = f() in uids.[uid] <- x; x
            else x
        let rec loop state = function
            | File(mid,_,name) -> memo uids_file mid (fun () -> funs.file(name,state,Array.get uids mid)) |> snd
            | Directory(uid,name,l) -> memo uids_directory uid (fun () -> funs.in_module(name,list state l))
        and list s l =
            List.fold (fun (empty,big) x ->
                let small = loop big x
                funs.union(small,empty), funs.union(small,big)
                ) (funs.empty, s) l |> fst
        list s l.tree

    /// ### wdiff_proj_files_update_files
    let wdiff_proj_files_update_files (funs : ProjFileFuns<'a,'state>) (state : ProjFilesState<'a,'state >) (uids,files : ProjFiles) =
        match proj_files_diff (state.uids_file,state.uids_directory,state.files) (uids,files) with
        | Some (uids_file, uids_directory) -> {state with files=files; uids_file=uids_file; uids_directory=uids_directory; result=proj_files funs uids_file uids_directory uids state.init files}
        | None -> state

    /// ### wdiff_proj_files_update_packages
    let wdiff_proj_files_update_packages (funs : ProjFileFuns<'a,'state>) (state : ProjFilesState<'a,'state >) (init : 'state) =
        if state.init = init then state else
        let uids_file, uids_directory = Array.zeroCreate state.uids_file.Length, Array.zeroCreate state.uids_directory.Length
        let uids = Array.map fst state.uids_file
        {state with init=init; uids_file=uids_file; uids_directory=uids_directory; result=proj_files funs uids_file uids_directory uids init state.files}

    /// ### wdiff_proj_files
    let wdiff_proj_files (funs : ProjFileFuns<'a,'state>) (state : ProjFilesState<'a,'state >) (init,(uids,files)) =
        if state.init = init then wdiff_proj_files_update_files funs state (uids,files)
        else
            let uids_file, uids_directory = Array.zeroCreate files.num_files, Array.zeroCreate files.num_dirs
            {files=files; init=init; uids_file=uids_file; uids_directory=uids_directory; result=proj_files funs uids_file uids_directory uids init files}

    /// ### typechecker_results_summary
    let typechecker_results_summary l =
        Stream.foldFun (fun (has_error,big) (_,x : InferResult,_) ->
            has_error || List.isEmpty x.errors = false,
            match x.top_env_additions with
            | AOpen _ -> big
            | AInclude small -> inferUnion small big
            ) (false,inferTop_env_empty) l

    /// ### funs_proj_file_tc
    let funs_proj_file_tc = {new ProjFileFuns<TypecheckerState,TypecheckerStatePropagated> with
        member _.file(name,state,x) =
            let x = wdiff_file_update_state funs_file_tc x state
            let env =
                typechecker_results_summary x.result >>-* fun (has_error,env) ->
                has_error, match name with None -> env | Some name -> inferIn_module name env
            x,env
        member _.union(small,big) = small >>=* fun small -> big >>- fun big -> fst small || fst big, inferUnion (snd small) (snd big)
        member _.in_module(name,small) = small >>-* fun (has_error,env) -> has_error, inferIn_module name env
        member _.default' default_env = Promise.Now.withValue (false,inferTop_env_default default_env)
        member _.empty = Promise.Now.withValue (false,inferTop_env_empty)
        }

    /// ### PackageEnv
    type PackageEnv = {
        nominals_aux : Map<PackageId,Map<GlobalId,NominalAux>>
        nominals : Map<PackageId,Map<GlobalId,NominalDef>>
        prototypes_instances : Map<PackageId,Map<GlobalId * GlobalId, Constraint Set list>>
        prototypes : Map<PackageId,Map<GlobalId,PrototypeDef>>
        ty : Map<string,T>
        term : Map<string,T>
        constraints : Map<string,ConstraintOrModule>
        }

    /// ### union
    let union small big = {
        nominals_aux = Map.foldBack Map.add small.nominals_aux big.nominals_aux
        nominals = Map.foldBack Map.add small.nominals big.nominals
        prototypes_instances = Map.foldBack Map.add small.prototypes_instances big.prototypes_instances
        prototypes = Map.foldBack Map.add small.prototypes big.prototypes
        ty = Map.foldBack Map.add small.ty big.ty
        term = Map.foldBack Map.add small.term big.term
        constraints = Map.foldBack Map.add small.constraints big.constraints
        }

    /// ### in_moduleWDiff
    let in_moduleWDiff m (a : PackageEnv) =
        {a with
            ty = Map.add m (TyModule a.ty) Map.empty
            term = Map.add m (TyModule a.term) Map.empty
            constraints = Map.add m (M a.constraints) Map.empty
            }

    /// ### package_to_file
    let package_to_file (x : PackageEnv) = {
        nominals_next_tag = 0
        nominals_aux = Map.foldBack (fun _ -> Map.foldBack Map.add) x.nominals_aux Map.empty
        nominals = Map.foldBack (fun _ -> Map.foldBack Map.add) x.nominals Map.empty
        prototypes_next_tag = 0
        prototypes_instances = Map.foldBack (fun _ -> Map.foldBack Map.add) x.prototypes_instances Map.empty
        prototypes = Map.foldBack (fun _ -> Map.foldBack Map.add) x.prototypes Map.empty
        ty = x.ty
        term = x.term
        constraints = x.constraints
        }

    /// ### add_file_to_package
    let add_file_to_package package_id (small : TopEnv) (big : PackageEnv): PackageEnv = {
        nominals_aux = Map.add package_id small.nominals_aux big.nominals_aux
        nominals = Map.add package_id small.nominals big.nominals
        prototypes_instances = Map.add package_id small.prototypes_instances big.prototypes_instances
        prototypes = Map.add package_id small.prototypes big.prototypes
        ty = small.ty
        term = small.term
        constraints = small.constraints
        }

    /// ### package_env_empty
    let package_env_empty = {
        nominals_aux = Map.empty
        nominals = Map.empty
        prototypes_instances = Map.empty
        prototypes = Map.empty
        ty = Map.empty
        term = Map.empty
        constraints = Map.empty
        }

    /// ### package_env_default
    let package_env_default default_env =
        let x = inferTop_env_default default_env
        {package_env_empty with ty = x.ty; term = x.term; constraints = x.constraints}

    /// ### ProjPackagesState<'a>
    type ProjPackagesState<'a> = {
        packages : (string option * 'a) list
        result : 'a
        }

    /// ### ProjState<'file_inputs,'files,'packages>
    type ProjState<'file_inputs,'files,'packages> = {
        package_id : PackageId
        packages : 'packages ProjPackagesState
        files : ProjFilesState<'file_inputs,'files>
        result : 'packages
        }

    /// ### TypecheckerStateTop
    type TypecheckerStateTop = (bool * PackageEnv) Promise

    /// ### ProjStateTC
    type ProjStateTC = ProjState<TypecheckerState,TypecheckerStatePropagated,TypecheckerStateTop>

    /// ### ProjEnvTC
    type ProjEnvTC = Map<PackageId,ProjStateTC>

    /// ### ProjPackageFuns<'file,'package>
    type ProjPackageFuns<'file,'package> =
        abstract member unions : DefaultEnv -> (string option * 'package) list -> 'package
        abstract member union : 'package * 'package -> 'package
        abstract member in_module : string * 'package -> 'package
        abstract member package_to_file : 'package -> 'file
        abstract member add_file_to_package : PackageId * 'file * 'package -> 'package
        abstract member default' : DefaultEnv -> 'package
        abstract member empty : 'package

    /// ### funs_proj_package_tc
    let funs_proj_package_tc = {new ProjPackageFuns<TypecheckerStatePropagated,TypecheckerStateTop> with
        member funs.unions default_env l =
            let f = function Some name, small -> funs.in_module(name,small) | None, small -> small
            List.fold (fun big x -> funs.union(f x,big)) (funs.default' default_env) l
        member _.union(small,big) =
            Job.delay <| fun () ->
                Hopac.queueIgnore big
                small >>=* fun a ->
                big >>- fun b ->
                fst a || fst b, union (snd a) (snd b)
            |> Hopac.memo
        member _.in_module(name,x) = x >>-* fun (has_error,env) -> has_error, in_moduleWDiff name env
        member _.package_to_file(x) = x >>-* fun (has_error,env) -> has_error, package_to_file env
        member _.add_file_to_package(pid,a,b) =
            a >>=* fun (has_error,env) ->
            b >>-* fun (has_error',env') ->
            has_error || has_error', add_file_to_package pid env env'
        member _.default' default_env = Promise.Now.withValue (false, package_env_default default_env)
        member _.empty = Promise.Now.withValue (false, package_env_empty)
        }

    /// ### wdiff_proj_init
    let wdiff_proj_init default_env (funs_packages : ProjPackageFuns<'file,'package>) (funs_files : ProjFileFuns<'file_input,'file>) package_id : ProjState<'file_input,'file,'package> =
        let packages = { packages = []; result = funs_packages.default' default_env}
        let files = {
            files={tree=[]; num_dirs=0; num_files=0}
            uids_file=[||]; uids_directory=[||]
            init=funs_files.default' default_env; result=funs_files.empty
            }
        let result = funs_packages.empty
        { package_id = package_id; packages = packages; files = files; result = result}

    /// ### wdiff_proj_packages
    let wdiff_proj_packages default_env (funs : ProjPackageFuns<_,'a>) (state : 'a ProjPackagesState) x =
        if state.packages = x then state else {packages = x; result = funs.unions default_env x }

    /// ### wdiff_proj_update_packages
    let wdiff_proj_update_packages default_env funs_packages funs_files (state : ProjState<'a,'b,'state>) x =
        let packages = wdiff_proj_packages default_env funs_packages state.packages x
        if state.packages = packages then state else
        let files = wdiff_proj_files_update_packages funs_files state.files (funs_packages.package_to_file(packages.result))
        let result = funs_packages.add_file_to_package(state.package_id,files.result,packages.result)
        {state with packages=packages; files=files; result=result}

    /// ### wdiff_proj_update_files
    let wdiff_proj_update_files (funs_packages : ProjPackageFuns<_,_>) funs_files (state : ProjState<'a,'b,'state>) x =
        let files = wdiff_proj_files_update_files funs_files state.files x
        if state.files = files then state else
        let result = funs_packages.add_file_to_package(state.package_id,files.result,state.packages.result)
        {state with files=files; result=result}

    /// ### wdiff_proj
    let wdiff_proj default_env (funs_packages : ProjPackageFuns<_,_>) funs_files (state : ProjState<'file_input,'file,'state>) (packages,files) =
        let packages = wdiff_proj_packages default_env funs_packages state.packages packages
        if state.packages = packages then wdiff_proj_update_files funs_packages funs_files state files
        else
            let files = wdiff_proj_files funs_files state.files (funs_packages.package_to_file(packages.result),files)
            let result = funs_packages.add_file_to_package(state.package_id,files.result,packages.result)
            {state with packages=packages; files=files; result=result}

    /// ### ProjEnvUpdate<'a>
    type ProjEnvUpdate<'a> =
        | UpdatePackageModule of PackageId * (string option * PackageId) list * ('a [] * ProjFiles)
        | UpdatePackage of PackageId * (string option * PackageId) list

    /// ### map_packages
    let map_packages s packages = packages |> List.map (fun (a,b) -> a, (Map.find b s).result)

    /// ### wdiff_projenv
    let wdiff_projenv default_env funs_packages funs_files (s : Map<PackageId,ProjState<'a,'b,'state>>) l =
        List.fold (fun s -> function
            | UpdatePackageModule(uid,packages,files) -> Map.add uid (wdiff_proj default_env funs_packages funs_files s.[uid] (map_packages s packages,files)) s
            | UpdatePackage(uid,packages) -> Map.add uid (wdiff_proj_update_packages default_env funs_packages funs_files s.[uid] (map_packages s packages)) s
            ) s l

#endif
#if SPIRAL_CORE_HOPAC
    /// ## WDiffPrepass
    open Hopac
    open Hopac.Infixes
    open Hopac.Extensions
    open Hopac.Stream
    

    /// ### PrepassStateValue
    type PrepassStateValue = InferResult * PrepassTopEnv AdditionType * PrepassTopEnv
    

    /// ### PrepassStatePropagated
    type PrepassStatePropagated = PrepassTopEnv Promise
    

    /// ### PrepassState
    type PrepassState = FileState<PackageId * ModuleId * string * TypecheckerStateValue Stream, PrepassStateValue Stream, PrepassStatePropagated>
    

    /// ### prepass
    let rec prepass (package_id,module_id,path,env) = function
        | Cons((_,r,_) : TypecheckerStateValue, ls) ->
            r.filled_top >>- fun filled_top ->
            let x = (prepassPrepass package_id module_id path env).filled_top filled_top
            let adds = match x with AOpen x | AInclude x -> x
            let env = prepassUnion adds env
            Cons((r,x,env),ls >>=* prepass (package_id,module_id,path,env))
        | Nil ->
            Job.result Nil
    

    /// ### diffWDiffPrepass
    let rec diffWDiffPrepass (package_id,module_id,path,env) (result,input : TypecheckerStateValue Stream) =
        input >>** fun input ->
        let tc () = prepass (package_id,module_id,path,env) input |> Hopac.memo
        if Promise.Now.isFulfilled result then
            match Promise.Now.get result,input with
            | Cons((b',_,env as x),next), Cons((_,b,_),bs) when b' = b -> Cons(x,diffWDiffPrepass (package_id,module_id,path,env) (next,bs)) |> Promise.Now.withValue
            | _ -> tc()
        else tc()
    

    /// ### funs_file_prepass
    let funs_file_prepass = {new FileFuns<PackageId * ModuleId * string * TypecheckerStateValue Stream, PrepassStateValue Stream, PrepassStatePropagated> with
        member _.eval(state,(pid,mid,path,x)) =
            state >>=* fun env ->
            x >>= prepass (pid,mid,path,env)
        member _.diff(state,b,(pid,mid,path,a)) =
            state >>=* fun env -> diffWDiffPrepass (pid,mid,path,env) (b,a)
        member _.init x = {
            input = x
            result = Promise.Now.never()
            state = Promise.Now.never()
            }
        }
    

    /// ### prepass_results_summary
    let prepass_results_summary l =
        Stream.foldFun (fun big (_,x,_) ->
            match x with
            | AOpen _ -> big
            | AInclude small -> prepassUnion small big
            ) (prepassTop_env_empty) l
    

    /// ### funs_proj_file_prepass
    let funs_proj_file_prepass = {new ProjFileFuns<PrepassState,PrepassStatePropagated> with
        member _.file(name,state,x) =
            let x = wdiff_file_update_state funs_file_prepass x state
            let env =
                prepass_results_summary x.result >>-* fun env ->
                match name with None -> env | Some name -> in_modulePrepass name env
            x,env
        member _.union(small,big) = small >>=* fun small -> big >>- fun big -> prepassUnion small big
        member _.in_module(name,small) = small >>-* in_modulePrepass name
        member _.default' default_env = Promise.Now.withValue (prepassTop_env_default default_env)
        member _.empty = Promise.Now.withValue prepassTop_env_empty
        }
    

    /// ### PrepassPackageEnv
    type PrepassPackageEnv = {
        prototypes_instances : Map<int, Map<GlobalId * GlobalId,E>>
        nominals : Map<int, Map<GlobalId,{|body : TPrepass; name : string|}>>
        term : Map<TermNameId,E>
        ty : Map<TypeNameId,TPrepass>
        }
    

    /// ### unionWDiffPrepass
    let unionWDiffPrepass small big = {
        prototypes_instances = Map.foldBack Map.add small.prototypes_instances big.prototypes_instances
        nominals = Map.foldBack Map.add small.nominals big.nominals
        term = Map.foldBack Map.add small.term big.term
        ty = Map.foldBack Map.add small.ty big.ty
        }
    

    /// ### in_module
    let in_module m (a : PrepassPackageEnv) =
        {a with
            ty = Map.add (TypeNameIdOps.create m) (TModule a.ty) Map.empty
            term = Map.add (TermNameIdOps.create m) (EModule a.term) Map.empty
            }
    

    /// ### package_env_emptyWDiffPrepass
    let package_env_emptyWDiffPrepass = {
        prototypes_instances = Map.empty
        nominals = Map.empty
        term = Map.empty
        ty = Map.empty
        }
    

    /// ### package_to_fileWDiffPrepass
    let package_to_fileWDiffPrepass (x : PrepassPackageEnv) = {
        nominals_next_tag = 0
        nominals = Map.foldBack (fun _ -> Map.foldBack Map.add) x.nominals Map.empty
        prototypes_next_tag = 0
        prototypes_instances = Map.foldBack (fun _ -> Map.foldBack Map.add) x.prototypes_instances Map.empty
        ty = x.ty
        term = x.term
        }
    

    /// ### add_file_to_packageWDiffPrepass
    let add_file_to_packageWDiffPrepass package_id (small : PrepassTopEnv) (big : PrepassPackageEnv): PrepassPackageEnv = {
        nominals = Map.add package_id small.nominals big.nominals
        prototypes_instances = Map.add package_id small.prototypes_instances big.prototypes_instances
        ty = small.ty
        term = small.term
        }
    

    /// ### package_env_defaultWDiffPrepass
    let package_env_defaultWDiffPrepass default_env = { package_env_emptyWDiffPrepass with ty = (prepassTop_env_default default_env).ty }
    

    /// ### ProjStatePrepass
    type ProjStatePrepass = ProjState<PrepassState,PrepassStatePropagated,PrepassPackageEnv Promise>
    

    /// ### funs_proj_package_prepass
    let funs_proj_package_prepass = {new ProjPackageFuns<PrepassStatePropagated,PrepassPackageEnv Promise> with
        member funs.unions default_env l =
            let f = function Some name, small -> funs.in_module(name,small) | None, small -> small
            List.fold (fun big x -> funs.union(f x,big)) (funs.default' default_env) l
        member _.union(small,big) =
            Job.delay <| fun () ->
                if Promise.Now.isFulfilled big = false then HopacExtensions.start (big >>- ignore)
                small >>= fun a -> big >>- unionWDiffPrepass a
            |> Hopac.memo
        member _.in_module(name,x) = x >>-* fun env -> in_module name env
        member _.package_to_file(x) = x >>-* package_to_fileWDiffPrepass
        member _.add_file_to_package(pid,a,b) =
            a >>=* fun env ->
            b >>-* add_file_to_packageWDiffPrepass pid env
        member _.default' default_env = Promise.Now.withValue (package_env_defaultWDiffPrepass default_env)
        member _.empty = Promise.Now.withValue package_env_emptyWDiffPrepass
        }
    

