    type private NativeBuildBoundaryErrorId =
        | NativeBuildBoundaryDraftWithoutRootComplete of artifactCount:int
        | NativeBuildBoundaryWriterAuthorizationRejected of reason:CompilerKernelV2.OperationalReasonId
        | NativeBuildBoundaryLegacyFallbackForbidden of reason:CompilerKernelV2.OperationalReasonId

    let private nativeBuildBoundaryWriterAuthorizationRejected (reason: CompilerKernelV2.OperationalReasonId) =
        NativeBuildBoundaryWriterAuthorizationRejected reason

    let private nativeBuildBoundaryLegacyFallbackForbidden reason =
        NativeBuildBoundaryLegacyFallbackForbidden(
            CompilerKernelV2.OperationalReasonIdOps.create reason)

    let private nativeBuildBoundaryErrorText = function
        | NativeBuildBoundaryDraftWithoutRootComplete artifactCount ->
            "NativeBuildBoundaryError(DraftWithoutRootComplete|artifact_count=" + string artifactCount + ")"
        | NativeBuildBoundaryWriterAuthorizationRejected reason ->
            "NativeBuildBoundaryError(WriterAuthorizationRejected|reason="
            + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"
        | NativeBuildBoundaryLegacyFallbackForbidden reason ->
            "NativeBuildBoundaryError(LegacyFallbackForbidden|reason="
            + CompilerKernelV2.OperationalReasonIdOps.text reason + ")"

    let private raiseNativeBuildBoundaryError err =
        raise (PartEvalTypeError([], nativeBuildBoundaryErrorText err))

    type private BuildFileInitializationStageId =
        | BuildFileRuntimeStarted
        | BuildFileTypecheckAwaitScheduled
        | BuildFileTypecheckStateReady
        | BuildFilePrepassAwaitScheduled
        | BuildFilePrepassReady
        | BuildFileBodyEntered
        | BuildFilePartialEvaluationStarted
        | BuildFilePartialEvaluationCompleted
        | BuildFileCodegenCompleted

    let private buildFileInitializationStageText = function
        | BuildFileRuntimeStarted -> "runtime_started"
        | BuildFileTypecheckAwaitScheduled -> "typecheck_await_scheduled"
        | BuildFileTypecheckStateReady -> "typecheck_state_ready"
        | BuildFilePrepassAwaitScheduled -> "prepass_await_scheduled"
        | BuildFilePrepassReady -> "prepass_ready"
        | BuildFileBodyEntered -> "build_body_entered"
        | BuildFilePartialEvaluationStarted -> "partial_evaluation_started"
        | BuildFilePartialEvaluationCompleted -> "partial_evaluation_completed"
        | BuildFileCodegenCompleted -> "codegen_completed"

    // Last stage reached by the current BuildFile, reported by the build-budget stall diagnostic.
    let mutable private lastBuildFileInitializationStage = "not_started"
    /// Last BuildFile stage reached (lock-free read), for hosts that report stalls.
    let buildFileInitializationStageNow () = lastBuildFileInitializationStage

    /// Code generation recurses over nested join points and used to run on the dedicated big-stack thread the
    /// single-flight compiler had; on a Hopac worker's default stack it overflowed for recursive programs.
    /// Run it on its own thread with a large stack (SPIRAL_CODEGEN_STACK_MB, default 512) and rethrow faithfully.
    let private codegenOnLargeStack (generate : unit -> 'a) : 'a =
        let stackMb =
            match System.Int32.TryParse(System.Environment.GetEnvironmentVariable "SPIRAL_CODEGEN_STACK_MB") with
            | true, value when value >= 16 -> value
            | _ -> 512
        let result = ref Unchecked.defaultof<'a>
        let failure : exn ref = ref null
        let worker =
            System.Threading.Thread(
                (fun () -> try result.Value <- generate () with error -> failure.Value <- error),
                stackMb * 1024 * 1024)
        worker.Name <- "spiral-codegen"
        worker.Start()
        worker.Join()
        if not (isNull failure.Value) then
            System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(failure.Value).Throw()
        result.Value
    let private emitBuildFileInitializationStage stage =
        lastBuildFileInitializationStage <- buildFileInitializationStageText stage
        DiagJson.emit (
            sprintf "{\"kind\":\"build_file_initialization_stage\",\"stage_du\":%s,\"launch_mode_du\":\"scheduler_owned_direct_hopac_start\",\"nested_hopac_run\":false,\"authority\":\"typed_build_file_initialization_spine\"}"
                (DiagJson.esc (buildFileInitializationStageText stage)))

    type private ReplayRootReasonId =
        | ReplayRootFinalNoLiveAlternate of eventName:string * attempt:int * pending:int
        | ReplayRootSelectedFrontierHandoff of attempt:int * pending:int * selectedStatus:EvalWorklist.FrameStatusId * pendingClosed:bool
        | ReplayRootPostFinalizationPendingClosed of attempt:int * pending:int
        | ReplayRootSameSiteStaleRootRetargetDemoted of attempt:int * pending:int
        | ReplayRootCore56ParentCycleDemoted of attempt:int * pending:int
        | ReplayRootBase16TypeApplyParentCycleDemoted of attempt:int * pending:int
        | ReplayRootListm27TypeApplyParentCycleDemoted of attempt:int * pending:int
        | ReplayRootCrossModuleParentCycleDemoted of attempt:int * pending:int
        | ReplayRootSameSiteParentCycleDemoted of attempt:int * pending:int
        | ReplayRootFinalHandoff of attempt:int * pending:int
        | ReplayRootAppLeafRootWitnessFinalHandoff of attempt:int * pending:int

    let private replayRootReasonText = function
        | ReplayRootFinalNoLiveAlternate(eventName, attempt, pending) ->
            FastRuntimeFormat.format "BuildFile.replay_root_complete code=[spiral_compiler] EJP0011 source=%s/final_no_live_alternate attempt=%d pending=%d" [| box eventName; box attempt; box pending |]
        | ReplayRootSelectedFrontierHandoff(attempt, pending, selectedStatus, pendingClosed) ->
            FastRuntimeFormat.format "BuildFile.replay_root_complete code=[spiral_compiler] EJP0011 source=stable_root_complete_livelock/post_finalization_selected_frontier_handoff attempt=%d pending=%d selected_status=%s pending_closed=%b" [| box attempt; box pending; box (EvalWorklist.frameStatusToString selectedStatus); box pendingClosed |]
        | ReplayRootPostFinalizationPendingClosed(attempt, pending) ->
            sprintf "BuildFile.replay_root_complete code=[spiral_compiler] EJP0011 source=stable_root_complete_livelock/post_finalization_pending_closed attempt=%d pending=%d" attempt pending
        | ReplayRootSameSiteStaleRootRetargetDemoted(attempt, pending) ->
            sprintf "BuildFile.replay_root_complete code=[spiral_compiler] EJP0011 source=stable_root_complete_livelock/same_site_stale_root_retarget_demoted attempt=%d pending=%d" attempt pending
        | ReplayRootCore56ParentCycleDemoted(attempt, pending) ->
            sprintf "BuildFile.replay_root_complete code=[spiral_compiler] EJP0011 source=stable_root_complete_livelock/core56_parent_cycle_demoted attempt=%d pending=%d" attempt pending
        | ReplayRootBase16TypeApplyParentCycleDemoted(attempt, pending) ->
            sprintf "BuildFile.replay_root_complete code=[spiral_compiler] EJP0011 source=stable_root_complete_livelock/base16_type_apply_parent_cycle_demoted attempt=%d pending=%d" attempt pending
        | ReplayRootListm27TypeApplyParentCycleDemoted(attempt, pending) ->
            sprintf "BuildFile.replay_root_complete code=[spiral_compiler] EJP0011 source=stable_root_complete_livelock/listm27_type_apply_parent_cycle_demoted attempt=%d pending=%d" attempt pending
        | ReplayRootCrossModuleParentCycleDemoted(attempt, pending) ->
            sprintf "BuildFile.replay_root_complete code=[spiral_compiler] EJP0011 source=stable_root_complete_livelock/cross_module_parent_cycle_demoted attempt=%d pending=%d" attempt pending
        | ReplayRootSameSiteParentCycleDemoted(attempt, pending) ->
            sprintf "BuildFile.replay_root_complete code=[spiral_compiler] EJP0011 source=stable_root_complete_livelock/same_site_parent_cycle_demoted attempt=%d pending=%d" attempt pending
        | ReplayRootFinalHandoff(attempt, pending) ->
            sprintf "BuildFile.replay_root_complete code=[spiral_compiler] EJP0011 source=stable_root_complete_livelock/final_handoff attempt=%d pending=%d" attempt pending
        | ReplayRootAppLeafRootWitnessFinalHandoff(attempt, pending) ->
            sprintf "BuildFile.replay_root_complete code=[spiral_compiler] EJP0011 source=post_finalization_app_leaf_root_witness_final_handoff attempt=%d pending=%d" attempt pending

    let private replayRootGenerationReason reason =
        reason
        |> replayRootReasonText
        |> CacheGeneration.GenerationChangeReasonIdOps.create

    type private BuildBackendSelectionId =
        | BuildBackendGleam
        | BuildBackendLua
        | BuildBackendFsharp
        | BuildBackendRust
        | BuildBackendDelphi
        | BuildBackendC
        | BuildBackendPythonCuda
        | BuildBackendCppCuda
        | BuildBackendCudaCppUnavailable
        | BuildBackendPythonUnavailable
        | BuildBackendUpmemPythonCUnavailable
        | BuildBackendHlsCppUnavailable
        | BuildBackendCythonUnavailable
        | BuildBackendUnknown of string

    let private buildBackendSelectionId = function
        | "Gleam" -> BuildBackendGleam
        | "Lua" -> BuildBackendLua
        | "Fsharp" -> BuildBackendFsharp
        | "Rust" -> BuildBackendRust
        | "Delphi" -> BuildBackendDelphi
        | "C" -> BuildBackendC
        | "Python + Cuda" -> BuildBackendPythonCuda
        | "Cpp + Cuda" -> BuildBackendCppCuda
        | "Cuda C++" -> BuildBackendCudaCppUnavailable
        | "Python" -> BuildBackendPythonUnavailable
        | "UPMEM: Python + C" -> BuildBackendUpmemPythonCUnavailable
        | "HLS C++" -> BuildBackendHlsCppUnavailable
        | "Cython*" | "Cython" -> BuildBackendCythonUnavailable
        | backend -> BuildBackendUnknown backend

    [<RequireQualifiedAccess>]
    type private BuildDraft =
        | Provisional of NativeGeneratedArtifact list
        | ErrorTrace of string list * string
        | FatalError of string
        | Skip

    type private BuildResult =
        | BuildOk of NativeAuthorizedBuildOutput
        | BuildErrorTrace of string list * string
        | BuildFatalError of string
        | BuildSkip

    type private BuildTraceOwnerDeadlockMarker =
        | BuildTraceDynamicRecordKeyBridgeTailDead
        | BuildTraceTerminalClosureRepeatFastFinish
        | BuildTraceSemanticFixedPointChurn
        | BuildTraceDeferredExecutableGraphOwnerDeadlock
        | BuildTraceLiveGraphOwnerDeadlock
        | BuildTraceTerminalClosureRepeatDeadlock
        | BuildTraceParentContinuationPhase2NoSemanticCommit
        | BuildTraceJpOwnedSetStall

    let private buildTraceOwnerDeadlockMarkerText = function
        | BuildTraceDynamicRecordKeyBridgeTailDead -> "dynamic record-key bridge tail causal dead after repeated native callbacks"
        | BuildTraceTerminalClosureRepeatFastFinish -> "terminal closure repeat fast-finish"
        | BuildTraceSemanticFixedPointChurn -> "semantic fixed-point churn"
        | BuildTraceDeferredExecutableGraphOwnerDeadlock -> "terminal closure repeat deferred executable graph proved owner deadlock after drain"
        | BuildTraceLiveGraphOwnerDeadlock -> "live graph owner deadlock"
        | BuildTraceTerminalClosureRepeatDeadlock -> "terminal_closure_repeat_deadlock"
        | BuildTraceParentContinuationPhase2NoSemanticCommit -> "parent-continuation phase2 bridge repeated without semantic commit"
        | BuildTraceJpOwnedSetStall -> "JpIvarWaitFailureOwnedButStalled"

    let private buildTraceOwnerDeadlockMarkers =
        [ BuildTraceDynamicRecordKeyBridgeTailDead
          BuildTraceTerminalClosureRepeatFastFinish
          BuildTraceSemanticFixedPointChurn
          BuildTraceDeferredExecutableGraphOwnerDeadlock
          BuildTraceLiveGraphOwnerDeadlock
          BuildTraceTerminalClosureRepeatDeadlock
          BuildTraceParentContinuationPhase2NoSemanticCommit
          BuildTraceJpOwnedSetStall ]

    type private BuildTracePayloadKind =
        | BuildTraceSemanticTerminal of code:DiagnosticClassifier.DiagnosticCodeId
        | BuildTraceNativeTerminal of code:DiagnosticClassifier.DiagnosticCodeId
        | BuildTraceLegacyFallbackForbidden of code:DiagnosticClassifier.DiagnosticCodeId option
        | BuildTraceOwnerDeadlock of marker:BuildTraceOwnerDeadlockMarker
        | BuildTraceProvisionalWatchdog of code:DiagnosticClassifier.DiagnosticCodeId
        | BuildTraceRetryable of code:DiagnosticClassifier.DiagnosticCodeId option

    type private BuildTraceCommitDisposition =
        | BuildTraceObserverOnly
        | BuildTraceFailClosed

    let private buildTraceCodeOptionText = function
        | Some code -> DiagnosticClassifier.codeIdText code
        | None -> "unclassified"

    let private buildTracePayloadKindText = function
        | BuildTraceSemanticTerminal code -> "BuildTracePayload(SemanticTerminal|code=" + DiagnosticClassifier.codeIdText code + ")"
        | BuildTraceNativeTerminal code -> "BuildTracePayload(NativeTerminal|code=" + DiagnosticClassifier.codeIdText code + ")"
        | BuildTraceLegacyFallbackForbidden code -> "BuildTracePayload(LegacyFallbackForbidden|code=" + buildTraceCodeOptionText code + ")"
        | BuildTraceOwnerDeadlock marker -> "BuildTracePayload(OwnerDeadlock|marker=" + buildTraceOwnerDeadlockMarkerText marker + ")"
        | BuildTraceProvisionalWatchdog code -> "BuildTracePayload(ProvisionalWatchdog|code=" + DiagnosticClassifier.codeIdText code + ")"
        | BuildTraceRetryable code -> "BuildTracePayload(Retryable|code=" + buildTraceCodeOptionText code + ")"

    type private BuildTraceMessageSignalId =
        | BuildTraceMessageJpOwnedSetStall
        | BuildTraceMessageOwnerDeadlock of marker:BuildTraceOwnerDeadlockMarker

    let private buildTraceMessageContains (marker:string) (message:string) =
        if System.String.IsNullOrEmpty marker || System.String.IsNullOrEmpty message || marker.Length > message.Length then false
        else
            let mutable found = false
            let mutable index = 0
            let limit = message.Length - marker.Length
            while not found && index <= limit do
                found <- System.String.Compare(message, index, marker, 0, marker.Length, System.StringComparison.OrdinalIgnoreCase) = 0
                index <- index + 1
            found

    let private buildTraceMessageSignals (message:string) =
        let ownerSignals =
            buildTraceOwnerDeadlockMarkers
            |> List.choose (fun marker ->
                if buildTraceMessageContains (buildTraceOwnerDeadlockMarkerText marker) message then
                    Some(BuildTraceMessageOwnerDeadlock marker)
                else None)
        if buildTraceMessageContains "JpIvarWaitFailureOwnedButStalled(" message then
            BuildTraceMessageJpOwnedSetStall :: ownerSignals
        else ownerSignals

    let private buildTracePayloadKindFor (diagnostic:DiagnosticClassifier.DiagnosticIngress) (message:string) =
        let signals = buildTraceMessageSignals message
        match diagnostic with
        | _ when signals |> List.contains BuildTraceMessageJpOwnedSetStall ->
            BuildTraceOwnerDeadlock BuildTraceJpOwnedSetStall
        | DiagnosticClassifier.ClassifiedIngress classification when classification.disposition = DiagnosticClassifier.DiagnosticTerminalSemantic ->
            BuildTraceSemanticTerminal classification.code
        | DiagnosticClassifier.ClassifiedIngress classification when classification.disposition = DiagnosticClassifier.DiagnosticTerminalNative ->
            BuildTraceNativeTerminal classification.code
        | _ when textHasOrdinalPrefix "NativeBuildBoundaryError(LegacyFallbackForbidden|reason=retry_after_native_authority_kernel|" message ->
            // The boundary wrapper owns terminality. Its embedded EJP0019 is historical
            // context, not permission to reopen the legacy retry corridor.
            BuildTraceLegacyFallbackForbidden (diagnostic |> DiagnosticClassifier.tryClassification |> Option.map (fun classification -> classification.code))
        | DiagnosticClassifier.ClassifiedIngress classification when classification.code = DiagnosticClassifier.DiagnosticEJP0019 ->
            BuildTraceProvisionalWatchdog classification.code
        | _ ->
            signals
            |> List.tryPick (function
                | BuildTraceMessageOwnerDeadlock marker -> Some marker
                | BuildTraceMessageJpOwnedSetStall -> None)
            |> function
                | Some marker -> BuildTraceOwnerDeadlock marker
                | None -> BuildTraceRetryable (diagnostic |> DiagnosticClassifier.tryClassification |> Option.map (fun classification -> classification.code))

    type private BuildTraceDiagnosticDisposition =
        | BuildTraceClassifiedDisposition of DiagnosticClassifier.DiagnosticDispositionId
        | BuildTraceUnclassifiedDisposition

    let private buildTraceDiagnosticDispositionFor = function
        | DiagnosticClassifier.ClassifiedIngress classification ->
            BuildTraceClassifiedDisposition classification.disposition
        | DiagnosticClassifier.UnclassifiedIngress _ ->
            BuildTraceUnclassifiedDisposition

    let private buildTraceCommitDispositionForLegacyProjectionOnly disposition payload =
        match disposition with
        | BuildTraceClassifiedDisposition DiagnosticClassifier.DiagnosticRetryAfterCacheInvalidation
        | BuildTraceClassifiedDisposition DiagnosticClassifier.DiagnosticRetryAfterSchedulerRecovery
        | BuildTraceClassifiedDisposition DiagnosticClassifier.DiagnosticRetrySequential ->
            BuildTraceObserverOnly
        | BuildTraceClassifiedDisposition DiagnosticClassifier.DiagnosticTerminalNative
        | BuildTraceClassifiedDisposition DiagnosticClassifier.DiagnosticTerminalSemantic
        | BuildTraceUnclassifiedDisposition ->
            match payload with
            | BuildTraceSemanticTerminal _
            | BuildTraceNativeTerminal _
            | BuildTraceLegacyFallbackForbidden _
            | BuildTraceOwnerDeadlock _ -> BuildTraceFailClosed
            | BuildTraceProvisionalWatchdog _
            | BuildTraceRetryable _ -> BuildTraceObserverOnly

    // Five-round migration, first cut: disposition, payload and commit are no
    // longer three values whose agreement must be reconstructed at the sink.
    // A closed decision carries the dispositive rule and any contradiction.
    // The classified diagnostic disposition wins; payload is authoritative only
    // when the ingress itself is unclassified.
    type private BuildTraceTerminalityRule =
        | BuildTraceRetryDispositionDispositive of DiagnosticClassifier.DiagnosticDispositionId
        | BuildTraceTerminalDispositionDispositive of DiagnosticClassifier.DiagnosticDispositionId
        | BuildTraceUnclassifiedPayloadDispositive of BuildTracePayloadKind

    type private BuildTraceDispositionPayloadConflict =
        | BuildTraceDispositionPayloadAligned
        | BuildTraceRetryDispositionOverridesTerminalPayload of DiagnosticClassifier.DiagnosticDispositionId * BuildTracePayloadKind
        | BuildTraceTerminalDispositionOverridesObserverPayload of DiagnosticClassifier.DiagnosticDispositionId * BuildTracePayloadKind

    type private BuildTraceTerminalityDecision = private {
        disposition : BuildTraceDiagnosticDisposition
        payload : BuildTracePayloadKind
        commitDisposition : BuildTraceCommitDisposition
        rule : BuildTraceTerminalityRule
        conflict : BuildTraceDispositionPayloadConflict
    }

    let private buildTracePayloadIsTerminal = function
        | BuildTraceSemanticTerminal _
        | BuildTraceNativeTerminal _
        | BuildTraceLegacyFallbackForbidden _
        | BuildTraceOwnerDeadlock _ -> true
        | BuildTraceProvisionalWatchdog _
        | BuildTraceRetryable _ -> false

    let private buildTraceTerminalityDecisionFor disposition payload =
        match disposition with
        | BuildTraceClassifiedDisposition diagnosticDisposition ->
            match diagnosticDisposition with
            | DiagnosticClassifier.DiagnosticRetryAfterCacheInvalidation
            | DiagnosticClassifier.DiagnosticRetryAfterSchedulerRecovery
            | DiagnosticClassifier.DiagnosticRetrySequential ->
                { disposition = disposition
                  payload = payload
                  commitDisposition = BuildTraceObserverOnly
                  rule = BuildTraceRetryDispositionDispositive diagnosticDisposition
                  conflict =
                    if buildTracePayloadIsTerminal payload then
                        BuildTraceRetryDispositionOverridesTerminalPayload(diagnosticDisposition, payload)
                    else BuildTraceDispositionPayloadAligned }
            | DiagnosticClassifier.DiagnosticTerminalNative
            | DiagnosticClassifier.DiagnosticTerminalSemantic ->
                { disposition = disposition
                  payload = payload
                  commitDisposition = BuildTraceFailClosed
                  rule = BuildTraceTerminalDispositionDispositive diagnosticDisposition
                  conflict =
                    if buildTracePayloadIsTerminal payload then BuildTraceDispositionPayloadAligned
                    else BuildTraceTerminalDispositionOverridesObserverPayload(diagnosticDisposition, payload) }
        | BuildTraceUnclassifiedDisposition ->
            { disposition = disposition
              payload = payload
              commitDisposition = if buildTracePayloadIsTerminal payload then BuildTraceFailClosed else BuildTraceObserverOnly
              rule = BuildTraceUnclassifiedPayloadDispositive payload
              conflict = BuildTraceDispositionPayloadAligned }

    let private buildTraceTerminalityRuleText = function
        | BuildTraceRetryDispositionDispositive disposition ->
            "RetryDispositionDispositive(" + DiagnosticClassifier.dispositionText disposition + ")"
        | BuildTraceTerminalDispositionDispositive disposition ->
            "TerminalDispositionDispositive(" + DiagnosticClassifier.dispositionText disposition + ")"
        | BuildTraceUnclassifiedPayloadDispositive payload ->
            "UnclassifiedPayloadDispositive(" + buildTracePayloadKindText payload + ")"

    let private buildTraceDispositionPayloadConflictText = function
        | BuildTraceDispositionPayloadAligned -> "Aligned"
        | BuildTraceRetryDispositionOverridesTerminalPayload(disposition, payload) ->
            "RetryDispositionOverridesTerminalPayload(disposition="
            + DiagnosticClassifier.dispositionText disposition
            + "|payload="
            + buildTracePayloadKindText payload
            + ")"
        | BuildTraceTerminalDispositionOverridesObserverPayload(disposition, payload) ->
            "TerminalDispositionOverridesObserverPayload(disposition="
            + DiagnosticClassifier.dispositionText disposition
            + "|payload="
            + buildTracePayloadKindText payload
            + ")"

    let private buildTraceTerminalityDecisionText decision =
        FastRuntimeFormat.format "BuildTraceTerminalityDecision(rule=%s|commit=%s|conflict=%s)" [| box (buildTraceTerminalityRuleText decision.rule); box (match decision.commitDisposition with | BuildTraceObserverOnly -> "ObserverOnly" | BuildTraceFailClosed -> "FailClosed"); box (buildTraceDispositionPayloadConflictText decision.conflict) |]

    let private buildTraceCommitDispositionText = function
        | BuildTraceObserverOnly -> "BuildTraceCommitDisposition(ObserverOnly|terminal_ledger_write=false)"
        | BuildTraceFailClosed -> "BuildTraceCommitDisposition(FailClosed|terminal_ledger_write=true)"

    // Build-file persistence consumes the typed generation-reason ledger directly.
    // Diagnostic reason text is rendered for humans only; it is never reparsed to
    // recover retry/replay authority.
    let private buildFileGenerationReasonsAreReplayOrRetryOnly reasons =
        Set.contains CacheGeneration.GenerationReasonReplayRootComplete reasons
        && reasons
           |> Set.forall (function
               | CacheGeneration.GenerationReasonReplayRootComplete
               | CacheGeneration.GenerationReasonRetry DiagnosticClassifier.DiagnosticEJP0014
               | CacheGeneration.GenerationReasonRetry DiagnosticClassifier.DiagnosticEJP0011
               | CacheGeneration.GenerationReasonRetry DiagnosticClassifier.DiagnosticEJP0019
               | CacheGeneration.GenerationReasonDeadIvarJpWait -> true
               | CacheGeneration.GenerationReasonRetry _
               | CacheGeneration.GenerationReasonUnclassified -> false)
    

    /// ### workspaceRoot
    let workspaceRoot = SpiralFileSystem.get_workspace_root ()
    

    // MIGRATION: hard-disable diag file persistence while the compiler is unstable.
    // Keep everything in console; re-enable later behind a single switch when stable.
    let diag_save_enabled = false
    // let diag_save_enabled =
    //     | null | "" | "0" | "false" | "False" -> false
    //     | _ -> true

    /// ### targetDir
    let targetDir = workspaceRoot </> "target/spiral_Eval"

    /// ### traceDir
    let traceDir =
        if diag_save_enabled then
            targetDir </> "supervisor_trace"
        else
            // Make it extremely unlikely to exist, so the Spiral runtime won't emit retry diag files.
            targetDir </> "supervisor_trace_DISABLED"



    let private supervisorTraceDirectoriesInitialized : unit =
        try
            System.IO.Directory.CreateDirectory(targetDir) |> ignore
            if diag_save_enabled then System.IO.Directory.CreateDirectory(traceDir) |> ignore
        with _ -> ()
    

    /// ### dir
    let dir uri =
        let result = System.IO.FileInfo(System.Uri(uri).LocalPath).Directory.FullName
        let result' = result |> SpiralFileSystem.standardize_path
        trace Verbose (fun () -> $"Supervisor.dir / uri: {uri} / result: {result} / result': {result'}") _locals
        result'
    

    /// ### file
    let file uri =
        let result =
            try
                System.IO.FileInfo(System.Uri(uri).LocalPath).FullName
            with ex ->
                trace Verbose (fun () -> $"Supervisor.file / uri: {uri} / ex: %A{ex}") _locals
                uri
        let result' = result |> SpiralFileSystem.standardize_path
        // let result = result |> SpiralSm.replace "\\" "|"
        // trace Verbose (fun () -> $"Supervisor.file / uri: {uri} / result: {result} / result': {result'}") _locals
        result'
    

    /// ### supervisor_server
    let supervisor_server (default_env : DefaultEnv) atten (errors : SupervisorErrorSources) req =
        let fatal x = BuildDiagnosticsLedger.note "fatal_sent"; HopacExtensions.start (Ch.send errors.fatal x)
        let handle_packages (dirty_packages,s) = HopacExtensions.start (Ch.send atten ([||],dirty_packages,s)); s
        let handle_file_packages file (dirty_packages,s) = HopacExtensions.start (Ch.send atten ([|file|],dirty_packages,s)); s
        let handle_files_packages (dirty_files,(dirty_packages,s)) = HopacExtensions.start (Ch.send atten (dirty_files,dirty_packages,s)); s
        let loop (s : SupervisorState) = req >>- function
            | SupervisorReq.ProjectFileChange x | SupervisorReq.ProjectFileOpen x -> proj_open default_env s (dir x.uri,Some x.spiprojText) |> handle_packages
            | SupervisorReq.FileOpen x ->
                let file = file x.uri
                // trace Verbose (fun () -> $"Supervisor.supervisor_server.loop.FileOpen / x: %A{x} / file: {file}") _locals
                match ModuleEnv.tryFindText file s.modules with
                | Some m -> wdiff_module_all default_env m x.spiText
                | None -> wdiff_module_init_all default_env (is_top_down file) x.spiText
                |> fun v -> proj_revalidate_owner default_env {s with modules = ModuleEnv.addText file v s.modules} file
                |> handle_file_packages file
            | SupervisorReq.FileChange x ->
                let file = file x.uri
                trace Verbose (fun () -> $"Supervisor.supervisor_server.loop.FileChange / x: %A{x} / file: {file}") _locals
                match ModuleEnv.tryFindText file s.modules with
                | None -> fatal "It is not possible to apply a change to a file that is not present in the environment. Try reopening it in the editor."; s
                | Some m ->
                    match wdiff_module_edit default_env m x.spiEdit with
                    | Ok v -> proj_revalidate_owner default_env {s with modules = ModuleEnv.addText file v s.modules} file |> handle_file_packages file
                    | Error er -> fatal er; s
            | SupervisorReq.FileDelete x ->
                trace Verbose (fun () -> $"Supervisor.supervisor_server.loop.FileDelete / x: {x}") _locals
                file_delete default_env s (HopacExtensions.A.map file x.uris) |> handle_files_packages
            | SupervisorReq.ProjectFileLinks(x,res) ->
                let l =
                    match SchemaEnv.tryFindText (dir x.uri) s.packages with
                    | None -> []
                    | Some x ->
                        let mutable l = []
                        x.schema.packages |> List.iter (fun x ->
                            let r,dir = x.dir
                            trace Verbose (fun () -> $"Supervisor.supervisor_server.ProjectFileLinks / x.schema.packages |> List.iter / dir: {dir}") _locals
                            if SchemaEnv.containsText dir s.packages then l <- (r,file_uri (spiproj_suffix dir)) :: l
                            )
                        let rec loop = function
                            | FileHierarchy.Directory(_,_,_,l) -> list l
                            | FileHierarchy.File(_,(r,path),_) ->
                                trace Verbose (fun () -> $"Supervisor.supervisor_server.ProjectFileLinks.loop | SpiProj.FileHierarchy.File(_,(r,path),_) / path: {path}") _locals
                                if ModuleEnv.containsText path s.modules then l <- (r,file_uri path) :: l
                        and list l = List.iter loop l
                        list x.schema.modules
                        l
                HopacExtensions.start (IVar.fill res l)
                s
            | SupervisorReq.ProjectCodeActions(x,res) ->
                let z =
                    match SchemaEnv.tryFindText (dir x.uri) s.packages with
                    | None -> []
                    | Some x ->
                        let mutable z = []
                        let actions_dir (r,path) =
                            match r with
                            | None -> ()
                            | Some r ->
                                if Directory.Exists(path) then
                                    z <- (r,RenameDirectory {|dirPath=path; target=null; validate_as_file=false|}) :: (r,DeleteDirectory {|dirPath=path; range=r|}) :: z
                                else
                                    z <- (r,CreateDirectory {|dirPath=path|}) :: z
                        actions_dir x.schema.moduleDir
                        actions_dir x.schema.packageDir
    

                        let rec actions_module = function
                            | FileHierarchy.Directory(r',(r,path),_,l) ->
                                trace Verbose (fun () -> $"Supervisor.supervisor_server.ProjectCodeActions.actions_module | SpiProj.FileHierarchy.Directory(r',(r,path),_,l) / path: {path}") _locals
                                if Directory.Exists(path) then
                                    z <- (r,RenameDirectory {|dirPath=path; target=null; validate_as_file=true|}) :: (r,DeleteDirectory {|dirPath=path; range=r'|}) :: z
                                else
                                    z <- (r,CreateDirectory {|dirPath=path|}) :: z
                                actions_modules l
                            | FileHierarchy.File(r',(r,path),_) ->
                                trace Verbose (fun () -> $"Supervisor.supervisor_server.ProjectCodeActions.actions_module | SpiProj.FileHierarchy.File(r',(r,path),_) / path: {path}") _locals
                                if ModuleEnv.containsText path s.modules then
                                    z <- (r,RenameFile {|filePath=path; target=null|}) :: (r,DeleteFile {|range=r'; filePath=path|}) :: z
                                else
                                    z <- (r,CreateFile {|filePath=path|}) :: z
                        and actions_modules l = List.iter actions_module l
                        actions_modules x.schema.modules
                        z
                HopacExtensions.start (IVar.fill res z)
                s
            | SupervisorReq.ProjectCodeActionExecute(x,res) ->
                let error, s =
                    match code_action_execute x.action with
                    | Error x -> Some x, s
                    | Ok null -> None, proj_open default_env s (dir x.uri,None) |> handle_packages
                    | Ok path -> None, file_delete default_env s [|path|] |> handle_files_packages
                HopacExtensions.start (IVar.fill res {|result=error|})
                s
            | SupervisorReq.FileTokenRange(x, res) ->
                let v =
                    match ModuleEnv.tryFindText (file x.uri) s.modules with
                    | Some v -> Some v
                    | None when x.uri |> SpiralSm.ends_with ".dib" ->
                        x.uri
                        |> SpiralSm.replace "file:///" ""
                        |> File.ReadAllText
                        |> wdiff_module_init_all default_env (is_top_down x.uri)
                        |> Some
                    | None -> None
    

                match v with
                | Some v ->
                    HopacExtensions.start (semantic_tokens v.parser >>= (vscode_tokens x.range >> IVar.fill res))
                | None ->
                    if x.uri |> SpiralSm.starts_with "vscode-notebook-cell" |> not then
                        trace Debug
                            (fun () -> $"Supervisor.supervisor_server.FileTokenRange")
                            (fun () -> $"module=None / x.uri: {x.uri} / {_locals ()}")
    

                    HopacExtensions.start (IVar.fill res [||])
                s
            | SupervisorReq.HoverAt(x,res) ->
                let file = file x.uri
                let pos = x.pos
                let _locals () = $"x: %A{x} / file: {file} / res: %A{res}"
                trace Verbose (fun () -> $"Supervisor.supervisor_server.HoverAt") _locals
                let go_hover x =
                    match x with
                    | None -> None
                    | Some (x : InferResult) ->
                        x.hovers |> Array.tryPick (fun ((a,b),r) ->
                            if pos.line = a.line && (a.character <= pos.character && pos.character < b.character) then Some r else None
                            )
                    |> (fun x ->
                        let _locals () = $"x: %A{x}"
                        trace Verbose (fun () -> $"Supervisor.supervisor_server.HoverAt.go_hover") _locals
                        x
                    )
                    |> IVar.fill res
                let go_block (x : TypecheckerState) =
                    let rec loop s (x : TypecheckerStateValue Stream) =
                        x >>= function
                        | Nil -> go_hover s
                        | Cons((_,x,_),b) ->
                            let _locals () = $"b: {b}"
                            trace Verbose (fun () -> $"Supervisor.supervisor_server.HoverAt.go_block.loop Cons") _locals
                            if x.offset <= pos.line then loop (Some x) b
                            // If the block is over the offset that means the previous one must be the right choice.
                            else go_hover s
                    HopacExtensions.start (loop None x.result)
                let rec go_file uids_file trees =
                    let rec loop = function
                        | ProjFilesTree.File(uid,file',_) -> if file = file' then go_block (Array.get uids_file uid |> fst); true else false
                        | ProjFilesTree.Directory(_,_,l) -> list l
                    and list l = List.exists loop l
                    list trees
                let rec go_parent (x : DirectoryInfo) =
                    trace Verbose (fun () -> $"Supervisor.supervisor_server.HoverAt.go_parent / x: %A{x}") _locals
                    if x = null then false
                    else
                        let path = x.FullName |> SpiralFileSystem.standardize_path
                        if SchemaEnv.containsText path s.packages then
                            let pid = (fst s.package_ids).[SchemaPathIdOps.create path]
                            match Map.tryFind pid s.packages_infer.ok with
                            | None -> false
                            | Some x -> go_file x.files.uids_file x.files.files.tree
                        else
                            go_parent x.Parent
                if go_parent (Directory.GetParent(file)) = false then HopacExtensions.start (IVar.fill res None)
                s
            | SupervisorReq.BuildFile (x, res) ->
                CompilerConsoleHud88.beginSupervisorBuildRequest ()
                let backend = x.backend
                let file = file x.uri
                let _locals () = $"x: %A{x} / file: {file}"
                // Build budget (always armed): when the request has no result within the budget, publish the
                // evaluator's state as a fatal diagnostic and complete the request, so a stalled parallel evaluation
                // surfaces as an error instead of an unanswered BuildFile. SPIRAL_BUILD_DEADLINE_MS is an absolute
                // Environment.TickCount64 value (the caller's own deadline, which already includes process start and
                // library warm-up); SPIRAL_BUILD_BUDGET_MS is a budget relative to this request. The deadline wins;
                // without either (e.g. polyglot's Supervisor) the budget is 15 minutes, enough for apps/spiral.
                let buildBudgetMs =
                    match System.Int64.TryParse(System.Environment.GetEnvironmentVariable "SPIRAL_BUILD_DEADLINE_MS") with
                    | true, deadline when deadline > 0L -> int (max 500L (deadline - System.Environment.TickCount64))
                    | _ ->
                        match System.Int32.TryParse(System.Environment.GetEnvironmentVariable "SPIRAL_BUILD_BUDGET_MS") with
                        | true, value when value > 0 -> value
                        | _ -> 15 * 60 * 1000
                if buildBudgetMs > 0 then
                    HopacExtensions.start (job {
                        do! Hopac.timeOutMillis buildBudgetMs
                        if not (IVar.Now.isFull res) then
                            let pending = try EvalWorklist.pendingCount () with _ -> -1
                            let active = try EvalWorklist.replayDriverActiveDepthValue () with _ -> -1
                            let drain = try EvalWorklist.replayDrainStateText (EvalWorklist.replayDrainStateSnapshot ()) with _ -> "unknown"
                            let message =
                                sprintf "BuildFile stalled: no result within %d ms (build budget) for %s [%s]; last_stage=%s eval_pending_frames=%d replay_driver_active=%d replay_drain=%s %s"
                                    buildBudgetMs file backend (buildFileInitializationStageNow ()) pending active drain (BuildDiagnosticsLedger.text ())
                            HopacExtensions.start (Ch.send errors.fatal message)
                            CompilerConsoleHud88.completeSupervisorBuildRequestFailed ()
                            do! IVar.tryFill res None
                    })
                trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile") _locals
                let handle_build_result = function
                    | BuildOk authorized ->
                        let l = authorized.artifacts
                        if DiagJson.emitNativeAuthorityDecisionChange
                               "writer:supervisor_boundary"
                               authorized.artifactSetHash
                               ("{\"writer_capability_du\":" + DiagJson.esc authorized.writerCapabilityDu
                                + ",\"root_resolution_du\":" + DiagJson.esc authorized.rootResolutionDu
                                + ",\"work_dag_du\":" + DiagJson.esc authorized.workDagDu + "}") then
                            DiagJson.emit (
                                "{\"kind\":\"native_authority_decision_change\",\"decision_key\":\"writer:supervisor_boundary\",\"decision_hash\":"
                                + DiagJson.esc authorized.artifactSetHash
                                + ",\"writer_capability_du\":" + DiagJson.esc authorized.writerCapabilityDu
                                + ",\"root_resolution_du\":" + DiagJson.esc authorized.rootResolutionDu
                                + ",\"work_dag_du\":" + DiagJson.esc authorized.workDagDu
                                + ",\"policy\":\"emit_only_on_authority_change\"}")
                        // MIGRATION: defensive output writer (generic; avoids clobbering good generated files on unstable runs).
                        let seq = if CacheGeneration.isSequentialRequested() then 1 else 0
                        let inv = CacheGeneration.invalidationCount()
                        let file0 = Path.ChangeExtension(file,null) // null removes the extension from path.
                        let mutable bad : string option = None
                        for x in l do
                            match bad with
                            | Some _ -> ()
                            | None ->
                                let outPath = file0 + x.file_extension
                                let nl = char 10
                                let lineCount = try x.code.Split([| nl |]).Length with _ -> 0
                                let byteCount = try System.Text.Encoding.UTF8.GetByteCount(x.code) with _ -> x.code.Length
                                let oldBytes = try if System.IO.File.Exists(outPath) then int64 (System.IO.FileInfo(outPath).Length) else 0L with _ -> 0L
                                // MIGRATION: WriteGuard + generic output validation (no hardcoded file names).
                                let newBytes = int64 byteCount
                                // Sequential mode and the build retry that placeholder/orphan recovery request are a deterministic inline
                                // recompute, not instability (fixes 44, 51).
                                let unstable = ((seq <> 0) || (inv <> 0L)) && not (PevalStallProbe.recoveryActive ())

                                // WriteGuard:
                                //  - block new outputs on unstable runs (prevents "success" without writing)
                                //  - block large shrink by proportional budget even on stable runs (common truncation symptom)
                                //  - MIGRATION: allow an existing output to be persisted after replay-only recovery
                                //    when the produced text is non-shrinking and the delta is small. MIGRATION reached
                                //    BuildOk after replay commits, but the guard rejected the write solely because
                                //    retry/replay invalidations made the run look unstable.
                                let isNew = oldBytes = 0L
                                let guardScale = max oldBytes newBytes
                                let minDeltaBudget = 8192L
                                let maxDeltaBudget = 1048576L
                                let deltaBudget =
                                    if guardScale <= 0L then minDeltaBudget
                                    else min maxDeltaBudget (max minDeltaBudget (guardScale / 32L))
                                let smallOutputFloor = max 2048L (guardScale / 128L)
                                let growthBig = oldBytes > 0L && newBytes > oldBytes + deltaBudget && newBytes > smallOutputFloor
                                let shrinkBig = oldBytes > 0L && (oldBytes - newBytes) >= deltaBudget
                                let reasonSignals = CacheGeneration.reasonSignalsSnapshot 8 |> Set.ofList
                                let hasReplayCompleteReason =
                                    Set.contains CacheGeneration.GenerationReasonReplayRootComplete reasonSignals
                                let replayCompleteNow = EvalWorklist.hasReplayCompleteWriteWitness()
                                let replayOrRetryOnly =
                                    replayCompleteNow
                                    && buildFileGenerationReasonsAreReplayOrRetryOnly reasonSignals
                                let replayStableExisting =
                                    oldBytes > 0L
                                    && replayOrRetryOnly
                                    && newBytes >= oldBytes
                                    && newBytes <= oldBytes + deltaBudget
                                    && newBytes > smallOutputFloor
                                let persist =
                                    if isNew then (not unstable) // no size floor for a new file: the floor guards truncation of existing outputs, and rejected every small program
                                    else replayStableExisting || (not unstable)
                                let blocked = (not persist) || shrinkBig

                                // Reject obvious truncation/clobber generically: compare against the artifact's own scale, not backend extension.
                                let shrinkRel = oldBytes > smallOutputFloor && newBytes < (oldBytes * 7L) / 10L
                                let shrinkHard = oldBytes > smallOutputFloor && newBytes < smallOutputFloor
                                let tiny = oldBytes > smallOutputFloor && newBytes < smallOutputFloor
                                let reject = tiny || shrinkHard || (unstable && shrinkRel && not replayStableExisting) || blocked
                                if reject && replayCompleteNow && (not hasReplayCompleteReason) && (tiny || shrinkHard || shrinkRel || shrinkBig) then
                                    DiagJson.emit (
                                        FastRuntimeFormat.format "{\"kind\":\"write_guard_replay_shrink_blocked\",\"event\":\"precheck\",\"path\":%s,\"bytes\":%d,\"old_bytes\":%d,\"replayCompleteNow\":true,\"hasReplayCompleteReason\":false,\"shrinkBig\":%b,\"shrinkHard\":%b,\"shrinkRel\":%b,\"tiny\":%b,\"single_flight\":1,\"next\":\"semantic_payload_or_codegen_frontier_required\"}" [| box (DiagJson.esc outPath); box byteCount; box (int oldBytes); box shrinkBig; box shrinkHard; box shrinkRel; box tiny |])
                                if reject then
                                    let reasons = CacheGeneration.reasonsSnapshot 3
                                    let reasonsShort =
                                        if List.isEmpty reasons then ""
                                        else
                                            let trim (s: string) =
                                                if isNull s then ""
                                                elif s.Length > 180 then s.Substring(0, 177) + "..."
                                                else s
                                            " reasons=[" + (reasons |> List.map trim |> String.concat " | ") + "]"

                                    bad <- Some (FastRuntimeFormat.format "WRITE_ABORT: %s (lines=%d bytes=%d old_bytes=%d seq=%d inv=%d unstable=%b isNew=%b persist=%b replayCompleteNow=%b hasReplayCompleteReason=%b replayOrRetryOnly=%b replayStableExisting=%b growthBig=%b shrinkBig=%b shrinkHard=%b shrinkRel=%b tiny=%b deltaBudget=%d smallOutputFloor=%d)%s" [| box outPath; box lineCount; box byteCount; box (int oldBytes); box seq; box (int inv); box unstable; box isNew; box persist; box replayCompleteNow; box hasReplayCompleteReason; box replayOrRetryOnly; box replayStableExisting; box growthBig; box shrinkBig; box shrinkHard; box shrinkRel; box tiny; box (int deltaBudget); box (int smallOutputFloor); box reasonsShort |])
                        match bad with
                        | Some msg ->
                            // MIGRATION: WRITE_ABORT must leave enough telemetry in console to finish SOTA.
                            try
                                let reasons = CacheGeneration.reasonsSnapshot 4
                                let sidecar = DiagSidecar.snapshot 8

                                // MIGRATION: structured + multiplexed diagnostics (safe under Hopac interleaving).
                                let panel = try Progress88.providers.panelf() with _ -> ""
                                let extra = try Progress88.providers.extraf() with _ -> ""

                                let json_escape (s: string) =
                                    if isNull s then ""
                                    else
                                        s.Replace("\\", "\\\\")
                                         .Replace("\"", "\\\"")
                                         .Replace("\n", "\\n")
                                         .Replace("\r", "\\r")

                                let reasons_join =
                                    if List.isEmpty reasons then ""
                                    else reasons |> List.map json_escape |> String.concat " | "

                                let json =
                                    "{" +
                                    "\"kind\":\"write_abort\"," +
                                    "\"msg\":\"" + json_escape msg + "\"," +
                                    "\"reasons\":\"" + reasons_join + "\"," +
                                    "\"panel\":\"" + json_escape panel + "\"," +
                                    "\"extra\":\"" + json_escape extra + "\"" +
                                    "}"

                                // MIGRATION: mirror WRITE_ABORT to the machine JSONL channel as well as the human console.
                                DiagJson.emit json
                                Progress88.ConsoleMux88.writeLine("[spiral_compiler] " + json)
                                Progress88.ConsoleMux88.writeLine("[spiral_compiler] WRITE_ABORT DIAG BEGIN")
                                Progress88.ConsoleMux88.writeLine("[spiral_compiler] " + msg)
                                let term_hot = DiagSidecar.snapshotTopKeyedShort DiagSidecar.DiagReentryHotTerm 8
                                let ty_hot = DiagSidecar.snapshotTopKeyedShort DiagSidecar.DiagReentryHotTy 8
                                if (not (System.String.IsNullOrWhiteSpace term_hot)) || (not (System.String.IsNullOrWhiteSpace ty_hot)) then
                                    Progress88.ConsoleMux88.writeLine("[spiral_compiler] ---- hotkeys ----")
                                    Progress88.ConsoleMux88.writeLine(sprintf "[spiral_compiler] term_hot %s" (if System.String.IsNullOrWhiteSpace term_hot then "(none)" else term_hot))
                                    Progress88.ConsoleMux88.writeLine(sprintf "[spiral_compiler] ty_hot %s" (if System.String.IsNullOrWhiteSpace ty_hot then "(none)" else ty_hot))


                                if not (System.String.IsNullOrWhiteSpace panel) then
                                    Progress88.ConsoleMux88.writeLine("[spiral_compiler] ---- progress panel ----")
                                    Progress88.ConsoleMux88.writeLine("[spiral_compiler] " + panel)

                                if not (System.String.IsNullOrWhiteSpace extra) then
                                    Progress88.ConsoleMux88.writeLine("[spiral_compiler] ---- progress extra ----")
                                    Progress88.ConsoleMux88.writeLine("[spiral_compiler] " + extra)

                                if not (List.isEmpty reasons) then
                                    Progress88.ConsoleMux88.writeLine("[spiral_compiler] ---- recent invalidations ----")
                                    reasons |> List.iteri (fun i r ->
                                        Progress88.ConsoleMux88.writeLine(sprintf "[spiral_compiler] inv[%d]: %s" i r)
                                    )

                                if not (List.isEmpty sidecar) then
                                    Progress88.ConsoleMux88.writeLine("[spiral_compiler] ---- sidecar tail ----")
                                    sidecar |> List.iteri (fun i s ->
                                        Progress88.ConsoleMux88.writeLine(sprintf "[spiral_compiler] side[%d]: %s" i s)
                                    )

                                Progress88.ConsoleMux88.writeLine("[spiral_compiler] WRITE_ABORT DIAG END")
                            with _ -> ()

                            trace Critical (fun () -> $"Supervisor.supervisor_server.BuildFile.handle_build_result / rejected BuildOk: {msg}") _locals
                            job {
                                do! authorized.finalizeArtifacts (BigStack.TerminalFlowArtifactPersistenceRejected(CompilerKernelV2.OperationalReasonIdOps.create msg))
                                do! CompilerConsoleHud88.awaitTerminalReducerRunEndJob ()
                                HopacExtensions.start (Ch.send errors.fatal msg)
                                CompilerConsoleHud88.completeSupervisorBuildRequestFailed ()
                                do! IVar.tryFill res None
                            }
                        | None ->
                            Job.fromAsync (async {
                                let seq = if CacheGeneration.isSequentialRequested() then 1 else 0
                                let inv = CacheGeneration.invalidationCount()
                                let unstable = (seq <> 0) || (inv <> 0L)
                                let mutable wrote = 0
                                let mutable skipped = 0
                                let mutable persistedBytes = 0L
                                let mutable replayStableWrites = 0
                                let replayCompleteNow = EvalWorklist.hasReplayCompleteWriteWitness()

                                let sanitize_utf16_for_utf8 (s: string) : struct(string * int) =
                                    if isNull s then struct("", 0)
                                    else
                                        let sb = System.Text.StringBuilder(s.Length)
                                        let mutable i = 0
                                        let mutable replaced = 0
                                        while i < s.Length do
                                            let c = s.[i]
                                            if System.Char.IsHighSurrogate c then
                                                if i + 1 < s.Length && System.Char.IsLowSurrogate s.[i+1] then
                                                    sb.Append(c) |> ignore
                                                    sb.Append(s.[i+1]) |> ignore
                                                    i <- i + 2
                                                else
                                                    sb.Append('\uFFFD') |> ignore
                                                    replaced <- replaced + 1
                                                    i <- i + 1
                                            elif System.Char.IsLowSurrogate c then
                                                sb.Append('\uFFFD') |> ignore
                                                replaced <- replaced + 1
                                                i <- i + 1
                                            else
                                                sb.Append(c) |> ignore
                                                i <- i + 1
                                        struct(sb.ToString(), replaced)

                                for x in l do
                                    let outPath = file0 + x.file_extension
                                    let struct(codeSafe, repl) = sanitize_utf16_for_utf8 x.code
                                    if repl <> 0 then
                                        trace Warning (fun () -> $"WRITE_SANITIZE: {outPath} (replaced_invalid_surrogates={repl})") _locals
                                    let byteCount = try System.Text.Encoding.UTF8.GetByteCount(codeSafe) with _ -> codeSafe.Length
                                    let nl = "\n"
                                    let lineCount = try codeSafe.Split([| nl |], System.StringSplitOptions.None).Length with _ -> 0
                                    let oldBytes = try if System.IO.File.Exists(outPath) then int64 (System.IO.FileInfo(outPath).Length) else 0L with _ -> 0L
                                    let newBytes = int64 byteCount
                                    // MIGRATION WriteGuard (write phase):
                                    // Mirror the pre-check rules; any block here indicates a race or instability.
                                    let guardScale = max oldBytes newBytes
                                    let minDeltaBudget = 8192L
                                    let maxDeltaBudget = 1048576L
                                    let deltaBudget =
                                        if guardScale <= 0L then minDeltaBudget
                                        else min maxDeltaBudget (max minDeltaBudget (guardScale / 32L))
                                    let smallOutputFloor = max 2048L (guardScale / 128L)
                                    let growthBig = oldBytes > 0L && newBytes > oldBytes + deltaBudget && newBytes > smallOutputFloor
                                    let isNew = oldBytes = 0L
                                    let shrinkBig = oldBytes > 0L && (oldBytes - newBytes) >= deltaBudget
                                    let reasonSignals = CacheGeneration.reasonSignalsSnapshot 8 |> Set.ofList
                                    let hasReplayCompleteReason =
                                        Set.contains CacheGeneration.GenerationReasonReplayRootComplete reasonSignals
                                    let replayOrRetryOnly =
                                        replayCompleteNow
                                        && buildFileGenerationReasonsAreReplayOrRetryOnly reasonSignals
                                    let replayStableExisting =
                                        oldBytes > 0L
                                        && replayOrRetryOnly
                                        && newBytes >= oldBytes
                                        && newBytes <= oldBytes + deltaBudget
                                        && newBytes > smallOutputFloor
                                    let persist =
                                        if isNew then (not unstable) // no size floor for a new file: the floor guards truncation of existing outputs, and rejected every small program
                                        else replayStableExisting || (not unstable)
                                    let blocked = (not persist) || shrinkBig
                                    if blocked then
                                        trace Warning (fun () -> $"WRITE_ABORT: {outPath} (lines={lineCount} new_bytes={newBytes} old_bytes={oldBytes} seq={seq} inv={inv} unstable={unstable} isNew={isNew} persist={persist} replayCompleteNow={replayCompleteNow} hasReplayCompleteReason={hasReplayCompleteReason} replayOrRetryOnly={replayOrRetryOnly} replayStableExisting={replayStableExisting} growthBig={growthBig} shrinkBig={shrinkBig} deltaBudget={deltaBudget} smallOutputFloor={smallOutputFloor})") _locals
                                        skipped <- skipped + 1
                                    else
                                        let tmpPath = outPath + ".tmp"
                                        do! System.IO.File.WriteAllTextAsync(tmpPath, codeSafe) |> Async.AwaitTask
                                        let mutable persisted = false
                                        try
                                            if System.IO.File.Exists(outPath) then
                                                // MIGRATION: no persistent backups. Atomic replace with ephemeral temp-old file.
                                                let oldTmp = outPath + ".replace_old.tmp"
                                                try
                                                    System.IO.File.Replace(tmpPath, outPath, oldTmp, true)
                                                    persisted <- true
                                                finally
                                                    try System.IO.File.Delete(oldTmp) with _ -> ()
                                            else
                                                System.IO.File.Move(tmpPath, outPath)
                                                persisted <- true
                                        with _ ->
                                            // fallback: copy + delete is accepted only when the copy actually completed.
                                            try
                                                System.IO.File.Copy(tmpPath, outPath, true)
                                                System.IO.File.Delete(tmpPath)
                                                persisted <- true
                                            with _ -> persisted <- false
                                        if persisted then
                                            wrote <- wrote + 1
                                            persistedBytes <- persistedBytes + newBytes
                                            if replayStableExisting then replayStableWrites <- replayStableWrites + 1
                                        else
                                            skipped <- skipped + 1
                                            DiagJson.emit (
                                                sprintf "{\"kind\":\"artifact_filesystem_persistence_failed\",\"path\":%s,\"bytes\":%d,\"authority\":\"atomic_replace_or_copy\"}"
                                                    (DiagJson.esc outPath)
                                                    newBytes)

                                trace Info (fun () -> $"WRITE_SUMMARY: wrote={wrote} skipped={skipped} persisted_bytes={persistedBytes} seq={seq} inv={inv} unstable={unstable} replayCompleteNow={replayCompleteNow} replayStableWrites={replayStableWrites}") _locals
                                return struct(wrote, skipped, persistedBytes)
                            })
                            |> Job.bind (fun (struct (wrote, skipped, persistedBytes)) ->
                                if skipped <> 0 || wrote <> l.Length then
                                    let reason = FastRuntimeFormat.format "artifact_filesystem_persistence_incomplete|wrote=%d|expected=%d|skipped=%d|bytes=%d" [| box wrote; box l.Length; box skipped; box persistedBytes |]
                                    job {
                                        do! authorized.finalizeArtifacts (BigStack.TerminalFlowArtifactPersistenceRejected(CompilerKernelV2.OperationalReasonIdOps.create reason))
                                        do! CompilerConsoleHud88.awaitTerminalReducerRunEndJob ()
                                        // A failed build always says why: filling `res None` alone reached the host as
                                        // "BuildFile returned no code and no diagnostic arrived".
                                        HopacExtensions.start (Ch.send errors.fatal (FastRuntimeFormat.format "The generated code was not written to %s: %s (see WRITE_ABORT / artifact_filesystem_persistence_failed in the log)." [| box file; box reason |]))
                                        CompilerConsoleHud88.completeSupervisorBuildRequestFailed ()
                                        do! IVar.tryFill res None
                                    }
                                else
                                    job {
                                        do! authorized.finalizeArtifacts (BigStack.TerminalFlowArtifactPersistenceCommitted(wrote, persistedBytes))
                                        do! CompilerConsoleHud88.awaitTerminalReducerRunEndJob ()
                                        CompilerConsoleHud88.completeSupervisorBuildRequestSucceeded ()
                                        do!
                                            l
                                            |> List.map (fun x -> x.code)
                                            |> String.concat "\n"
                                            |> Some
                                            |> IVar.tryFill res
                                    })
                    | BuildFatalError x as x' ->
                        CompilerConsoleHud88.emitImmediateFailureEvent
                            "build_fatal_error_decision"
                            "Supervisor.supervisor_server.BuildFile.handle_build_result"
                            ("file=" + file)
                            x
                            "await_terminal_reducer_then_publish_fatal"
                        trace Info (fun () -> $"Supervisor.supervisor_server.BuildFile.handle_build_result / BuildFatalError x: %A{x}") _locals
                        job {
                            do! CompilerConsoleHud88.awaitTerminalReducerRunEndJob ()
                            HopacExtensions.start (Ch.send errors.fatal x)
                            CompilerConsoleHud88.completeSupervisorBuildRequestFailed ()
                            do! IVar.tryFill res None
                        }
                    | BuildErrorTrace(a,b) as x' ->
                        let msg_short = if b.Length > 240 then b.Substring(0,240) + " ..." else b
                        let diagnostic = DiagnosticClassifier.classifyIngress b
                        let code, diagnosticCodeId, diagnosticCauseId, diagnosticDispositionId =
                            match diagnostic with
                            | DiagnosticClassifier.ClassifiedIngress classification ->
                                DiagnosticClassifier.codeText classification.code,
                                DiagnosticClassifier.codeIdText classification.code,
                                DiagnosticClassifier.causeText classification.cause,
                                DiagnosticClassifier.dispositionText classification.disposition
                            | DiagnosticClassifier.UnclassifiedIngress _ ->
                                "", "unclassified", "unclassified", "unclassified"
                        let diagnosticFacts =
                            diagnostic
                            |> DiagnosticClassifier.ingressFacts
                            |> Set.toList
                            |> List.map DiagnosticClassifier.factText
                        let ingressEventKind =
                            if DiagnosticClassifier.ingressIsClassified diagnostic then DiagJson.DiagnosticIngressClassified
                            else DiagJson.DiagnosticIngressUnclassified
                        DiagJson.diagnosticEvent ingressEventKind
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldCode code
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticCodeId diagnosticCodeId
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticCause diagnosticCauseId
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticDisposition diagnosticDispositionId
                        |> DiagJson.diagnosticStringListKey DiagJson.DiagnosticFieldDiagnosticFacts diagnosticFacts
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldSource "BuildErrorTrace"
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldPolicy "single_text_ingress_then_typed_kernel"
                        |> DiagJson.renderDiagnosticEvent
                        |> DiagJson.emit
                        let emit (message: string) =
                            let safe = if System.Object.ReferenceEquals(message, null) then "" else message
                            DiagJson.diagnosticEvent DiagJson.DiagnosticBuildErrorTraceConsole
                            |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldMessage safe
                            |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticCodeId diagnosticCodeId
                            |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticCause diagnosticCauseId
                            |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticDisposition diagnosticDispositionId
                            |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldBuildErrorTraceId "build-error-trace:console"
                            |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldAuthority "console_projection_observer_only"
                            |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldPolicy "console_rows_never_mint_terminal_receipts"
                            
                            
                            
                            
                            
                            
                            
                            
                            
                            
                            
                            
                            |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldJsonlValidity "typed_event_builder"
                            |> DiagJson.renderDiagnosticEvent
                            |> CompilerConsoleHud88.writeLine
                        let short_path (p: string) =
                            try
                                let p = p.Replace('\\','/').Trim()
                                let parts = p.Split([|'/'|], System.StringSplitOptions.RemoveEmptyEntries)
                                if parts.Length <= 3 then p else System.String.Join("/", parts.[parts.Length-3..])
                            with _ -> p
                        let try_parse_site (line:string) : string option =
                            // Example: "Error trace on line: 1611, column: 5 in module: c:/.../bar.spi ."
                            try
                                match DiagJson.buildErrorTraceLineId line with
                                | DiagJson.BuildErrorTraceSiteLine moduleTail ->
                                    // Keep only the module path; the line/col pair is already noisy and varies.
                                    Some (short_path moduleTail)
                                | DiagJson.BuildErrorTraceOtherLine -> None
                            with _ -> None
                        // Console digest: keeps the "why" visible without dumping walls of text.
                        // Particularly helpful for EJP0010 (BigStack exhausted) and EJP0014 (scheduler stalled).
                        try
                            emit (FastRuntimeFormat.format "[spiral_compiler] BuildErrorTrace code=%s trace_lines=%d msg=%s" [| box code; box a.Length; box msg_short |])
                            let sites = a |> List.choose try_parse_site
                            if sites.Length > 0 then
                                let counts = System.Collections.Generic.Dictionary<CompilerIdentityKernel.WorkSiteId,int>()
                                for siteText in sites do
                                    let site = CompilerIdentityKernel.WorkSiteIdOps.create siteText
                                    let ok, v = counts.TryGetValue site
                                    counts.[site] <- (if ok then v + 1 else 1)
                                let top =
                                    counts
                                    |> Seq.map (fun kv -> CompilerIdentityKernel.WorkSiteIdOps.text kv.Key, kv.Value)
                                    |> Seq.sortByDescending snd
                                    |> Seq.truncate 6
                                    |> Seq.toList
                                if top.Length > 0 then
                                    emit "[spiral_compiler] BuildErrorTrace hotspots:"
                                    for (k,c) in top do emit (sprintf "  %dx %s" c k)
                                let tail = sites |> List.rev |> List.truncate 6 |> List.rev
                                emit "[spiral_compiler] BuildErrorTrace tail:"
                                for t in tail do emit (sprintf "  %s" t)
                        

                                // MIGRATION: quick hints based on generic hotspot shape, not source-path names.
                                if diagnostic |> DiagnosticClassifier.tryClassification |> Option.exists (fun classification ->
                                    classification.code = DiagnosticClassifier.DiagnosticEJP0010
                                    || DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticStackOverflow classification) then
                                    let repeated_hotspots = top |> List.filter (fun (_,c) -> c >= 5) |> List.length
                                    if repeated_hotspots > 0 then
                                        emit "[spiral_compiler] Hint: stack/deep-recursion failure has repeated hotspots. Prefer a stack-safe evaluator/worklist or memoized fixpoint path over raising recursion budgets."
                        with _ -> ()
                        // MIGRATION: keep BuildErrorTrace JSONL-first.  The detailed trace was
                        // already emitted as build_error_trace_console rows above; sending raw multiline
                        // text to the outer console corrupts JSONL precisely when the run reaches the
                        // semantic frontier.  Preserve the error channel, but compact newlines.
                        let compactTrace =
                            a
                            |> List.truncate 6
                            |> List.map (fun line -> line.Replace("\r", " ").Replace("\n", " "))
                        let compactMessage =
                            b.Replace("\r", " ").Replace("\n", " ")
                        let traceId = System.Guid.NewGuid().ToString("N")
                        let buildTracePayloadKind = buildTracePayloadKindFor diagnostic compactMessage
                        let buildTracePayloadKindDuText = buildTracePayloadKindText buildTracePayloadKind
                        let buildTraceDiagnosticDisposition = buildTraceDiagnosticDispositionFor diagnostic
                        let buildTraceTerminalityDecision = buildTraceTerminalityDecisionFor buildTraceDiagnosticDisposition buildTracePayloadKind
                        let buildTraceCommitDisposition = buildTraceTerminalityDecision.commitDisposition
                        let buildTraceCommitDispositionDuText = buildTraceCommitDispositionText buildTraceCommitDisposition
                        let buildTraceTerminalityDecisionDuText = buildTraceTerminalityDecisionText buildTraceTerminalityDecision
                        let buildTraceDispositionPayloadConflictDuText = buildTraceDispositionPayloadConflictText buildTraceTerminalityDecision.conflict
                        let buildTraceFinishFastTerminal =
                            match buildTraceCommitDisposition with
                            | BuildTraceFailClosed -> true
                            | BuildTraceObserverOnly -> false
                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.handle_build_result / BuildErrorTrace code={code} trace_id={traceId} trace_lines={a.Length} msg={msg_short}") _locals
                        // MIGRATION: do not inject TracedError objects back into the primary JSONL/event stream.
                        // Runtime evidence proved that the raw TracedError envelope can leak into a later
                        // phase2 reason field and corrupt the exact terminal JSON row we need for proof.
                        // Keep the structured build_error_trace_console rows above and emit a compact
                        // sidecar-only receipt here instead of sending raw errors.traced.
                        // The host still needs the error itself: without it a type error in a user program
                        // surfaced only as "BuildFile returned no code and no diagnostic". errors.traced is the
                        // Supervisor's diagnostic channel (single-flight sends the same), not the JSONL stream.
                        Hopac.start (Ch.send errors.traced {|trace=a; message=b|})
                        DiagJson.diagnosticEvent DiagJson.DiagnosticBuildErrorTraceSidecarOnly
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldTraceId traceId
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldCode code
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticCodeId diagnosticCodeId
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticCause diagnosticCauseId
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticDisposition diagnosticDispositionId
                        |> DiagJson.diagnosticIntKey DiagJson.DiagnosticFieldTraceLines a.Length
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldMessage compactMessage
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldJsonlValidity "primary_stream_safe_typed_event"
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldPolicy "raw_traced_error_sidecar_only_typed_transport"
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldNext (if buildTraceFinishFastTerminal then "terminal_collapse_to_build_error_trace" else "observer_only_fill_result_ivar_none")
                        |> DiagJson.renderDiagnosticEvent
                        |> DiagJson.emit
                        let buildTraceRootStatusId =
                            match buildTraceCommitDisposition with
                            | BuildTraceFailClosed -> DiagJson.RootPromiseFailed("BuildErrorTrace", compactMessage)
                            | BuildTraceObserverOnly -> DiagJson.RootPromiseWaiting("BuildErrorTrace", CompilerKernelV2.OperationalReasonIdOps.create ("observer_only|" + compactMessage))
                        let buildTraceHopacVerdictText = DiagJson.hopacRootExitVerdictFor buildTraceRootStatusId |> DiagJson.hopacRootExitVerdictText
                        let buildTraceBypassId =
                            match buildTracePayloadKind with
                            | BuildTraceSemanticTerminal c -> DiagJson.TrampolineBypassedSemanticTerminal(DiagnosticClassifier.codeText c, "semantic_terminal_no_retry")
                            | BuildTraceNativeTerminal c -> DiagJson.TrampolineBypassedNativeTerminal(DiagnosticClassifier.codeText c, "native_promise_terminal_no_retry")
                            | BuildTraceLegacyFallbackForbidden c -> DiagJson.TrampolineBypassedNativeTerminal(c |> Option.map DiagnosticClassifier.codeText |> Option.defaultValue "unclassified", "legacy_fallback_forbidden_after_native_authority")
                            | BuildTraceOwnerDeadlock marker -> DiagJson.TrampolineBypassedSemanticTerminal(code, "owner_deadlock:" + buildTraceOwnerDeadlockMarkerText marker)
                            | BuildTraceProvisionalWatchdog c -> DiagJson.TrampolineStillArmed(CompilerKernelV2.OperationalReasonIdOps.create ("provisional_watchdog_retryable_code=" + DiagnosticClassifier.codeIdText c))
                            | BuildTraceRetryable None -> DiagJson.TrampolineStillArmed(CompilerKernelV2.OperationalReasonIdOps.create "unclassified_build_error_trace")
                            | BuildTraceRetryable (Some c) -> DiagJson.TrampolineStillArmed(CompilerKernelV2.OperationalReasonIdOps.create ("classified_retryable_code=" + DiagnosticClassifier.codeIdText c))
                        let buildTraceBypassText = buildTraceBypassId |> DiagJson.trampolineBypassStatusText
                        DiagJson.diagnosticEvent DiagJson.DiagnosticBuildTerminalityClassified
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldTraceId traceId
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldCode code
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticCodeId diagnosticCodeId
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticCause diagnosticCauseId
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticDisposition diagnosticDispositionId
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldPayloadKind buildTracePayloadKindDuText
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldTerminalityDecision buildTraceTerminalityDecisionDuText
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDispositionPayloadConflict buildTraceDispositionPayloadConflictDuText
                        |> DiagJson.diagnosticBoolKey DiagJson.DiagnosticFieldFinishFastTerminal buildTraceFinishFastTerminal
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldAuthority "typed_build_trace_payload_classifier"
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldPolicy buildTraceCommitDispositionDuText
                        |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldNext (if buildTraceFinishFastTerminal then "durable_terminal_exit" else "fill_result_ivar_none_without_terminal_ledger")
                        |> DiagJson.renderDiagnosticEvent
                        |> DiagJson.emit
                        match buildTraceCommitDisposition with
                        | BuildTraceObserverOnly ->
                            // A retryable/provisional trace is evidence, not request completion.
                            // Keep the taskbar green and the HUD open while semantic replay owns
                            // live work; only a later dispositive Supervisor result may close it.
                            IVar.tryFill res None
                        | BuildTraceFailClosed ->
