                                DiagJson.diagnosticEvent DiagJson.DiagnosticTerminalCollapse
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldTraceId traceId
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldCode code
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldRootPromiseStatus (DiagJson.rootPromiseStatusText buildTraceRootStatusId)
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldHopacRootExitVerdict buildTraceHopacVerdictText
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldTrampolineBypassStatus buildTraceBypassText
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldSemanticErrorPayload compactMessage
                                |> DiagJson.diagnosticBoolKey DiagJson.DiagnosticFieldFinishFastTerminal true
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldTerminalReceiptDurability "TerminalReceiptDurability(DurableFileFlushBeforeExit|source=BuildErrorTrace)"
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldSchedulerOwnedRootTransition (sprintf "SchedulerRootFailClosedAfterOwnerDeadlock(build_error_trace|trace=%s)" traceId)
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldRootCompleteAltAuthority (sprintf "RootCompleteAltAuthority(id=root-complete-alt:build-error-trace:%s|receipt=terminal-root-receipt:build-error-trace:%s|kind=build_error_trace|writer_required=false)" traceId traceId)
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldTerminalRootReceiptGate (sprintf "TerminalRootReceiptGate(id=terminal-root-gate:build-error-trace:%s|root_consumed=true|writer_consumed=true|commit_allowed=true|fail_closed_ms=0)" traceId)
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldBuildErrorTraceAuthority (sprintf "BuildErrorTraceAuthority(trace=build_error_trace|code=%s|root_owned=true|durable_before_exit=true|raw_console_suppressed=true)" code)
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldRootTerminalOutcome "RootTerminalOutcome(FailedClosed|source=BuildErrorTrace|trace=build_error_trace)"
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldFailClosedExitAuthority "FailClosedExitAuthority(ByBuildErrorAuthority|trace=build_error_trace)"
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldArmedWaitGraphSpine "ArmedWaitGraphSpine(id=spine:build-error-trace|qap=terminal|unarmed=0|dropped=0)"
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldSchedulerPushEvent (sprintf "SchedulerPushEvent(PushFailClosed|source=build_error_trace|trace=%s)" traceId)
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldSchedulerPushAuthority (sprintf "SchedulerPushAuthority(id=push:build-error-trace:%s|writer_required=false|renderer=false|metronome=false)" traceId)
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldBreakthroughExitArbiter (sprintf "BreakthroughFailedClosed(contract=exit-contract:build-error-trace:%s|authority=build_error_trace|spine=spine:build-error-trace)" traceId)
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldTerminalAuthorityMigrationStatus "TerminalAuthorityMigration(round=3of5|typed_events=1|raw_json_constructor=0|arbiter=failed_closed)"
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldNativeTerminalExitContract (sprintf "NativeTerminalExitContract(id=exit-contract:build-error-trace:%s|outcome=failed_closed|authority=build_error_trace|exit=1)" traceId)
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldJsonlValidity "primary_stream_safe_typed_event"
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldPolicy "structured_terminal_before_direct_exit"
                                |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldNext "await_native_root_complete_alt"
                                |> DiagJson.renderDiagnosticEvent
                            DiagJson.noteNativePromiseFailureClosed(
                                DiagJson.NativePromiseFailureAuthorityTypedTerminalAction(
                                    traceId,
                                    "BuildErrorTrace",
                                    (if System.String.IsNullOrWhiteSpace code then "unclassified_build_error_trace" else code),
                                    DiagJson.NativePromiseFailureSourceBuildErrorTraceFinishFastTerminal)) |> ignore
                            DiagJson.emitTerminalJsonDurable buildTraceTerminalLine
                            BigStack.terminalFlowGlobalReconcileHostReturnThroughReducerJob () >>= fun reducerExitCode ->
                                let exitCode = defaultArg reducerExitCode 1
                                if Option.isNone reducerExitCode then
                                    DiagJson.emitTerminalJsonDurable (
