                              with ex -> eprintfn "[typecheck-wait] failed: %s" (ex.ToString())) |> ignore
                    | _ -> ()
                    HopacExtensions.start (a.state >>= fun (has_error',_) ->
                        b >>= fun (has_error,_) ->
                        if has_error || has_error' then
