                                        root_complete_yield_retry_count <- root_complete_yield_retry_count + 1
                                        DiagJson.emit (
                                            FastRuntimeFormat.format "{\"kind\":\"eval_worklist_root_complete_yield_retry_budget\",\"event\":%s,\"attempt\":%d,\"next_attempt\":%d,\"base_cap\":%d,\"yield_used\":%d,\"yield_cap\":%d,\"policy\":\"bounded_progress_bearing_root_complete_yield_extension\",\"single_flight\":1,\"next\":\"attempt_selected_frontier\"}" [| box (DiagJson.esc eventName); box attempt; box nextAttempt; box root_complete_replay_attempt_cap; box root_complete_yield_retry_count; box root_complete_yield_retry_cap |])
                                    let rootCompleteReplayExtendedAttemptCap () =
                                        root_complete_replay_attempt_cap + min root_complete_yield_retry_attempt_cap (root_complete_yield_retry_count * root_complete_yield_retry_attempts_per_signal)
                                    let canUseRootCompleteReplayAttempt (attempt: int) =
                                        attempt <= root_complete_replay_attempt_cap
                                        || (attempt <= rootCompleteReplayExtendedAttemptCap()
                                            && root_complete_yield_retry_count > 0
                                            && root_complete_yield_retry_count <= root_complete_yield_retry_cap)
                                    let noteRootCompleteHandoffCapExtension (eventName: string) (attempt: int) =
                                        if attempt > root_complete_replay_attempt_cap then
                                            DiagJson.emit (
                                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_root_complete_handoff_cap_extended\",\"event\":%s,\"attempt\":%d,\"max_attempts\":%d,\"base_cap\":%d,\"yield_used\":%d,\"yield_cap\":%d,\"policy\":\"allow_replay_complete_handoff_after_progress_yield\",\"single_flight\":1,\"next\":\"stable_root_complete_ledger\"}" [| box (DiagJson.esc eventName); box attempt; box max_attempts; box root_complete_replay_attempt_cap; box root_complete_yield_retry_count; box root_complete_yield_retry_cap |])
                                    let mutable preserve_root_complete_frontier_next_attempt = false
                                    let mutable preserve_progress_frontier_next_attempt = false
                                    let mutable preserve_parallel_retry_next_attempt = false
                                    let mutable replay_root_finalization_requested = false
                                    let mutable replay_root_finalization_retry_stop_pending_closed = false
                                    let mutable postFinalizationLeafRetryCount = 0
                                    let postFinalizationLeafRetryCap = 4
                                    let postFinalizationApp2671LeafRetryCap = 8
                                    let mutable postFinalizationApp2671LeafRetryCount = 0
                                    let postFinalizationAppLeafRootWitnessCloseCap = 4
                                    let mutable postFinalizationAppLeafRootWitnessCloseCount = 0
                                    // MIGRATION: historical runtime showed that once stale
                                    // terminals are demoted, the final handoff can keep
                                    // retrying the exact same root-complete frontier
                                    // thousands of times under the extended
                                    // root-complete trampoline budget.  Track only the
                                    // post-finalization BuildFile replay-root handoff
                                    // identity; progress-yield retries keep their own
                                    // separate budget.
                                    let stable_replay_root_final_handoff_repeat_cap = 4
                                    let mutable stableReplayRootFinalHandoffKey = ""
                                    let mutable stableReplayRootFinalHandoffCount = 0
                                    let noteStableReplayRootFinalHandoff (stableRootKey: string) =
                                        if stableReplayRootFinalHandoffKey = stableRootKey then
                                            stableReplayRootFinalHandoffCount <- stableReplayRootFinalHandoffCount + 1
                                        else
                                            stableReplayRootFinalHandoffKey <- stableRootKey
                                            stableReplayRootFinalHandoffCount <- 1
                                        stableReplayRootFinalHandoffCount
                                    let requestReplayRootCompleteFinalization (eventName: string) (attempt: int) (maxAttempts: int) (stableRootCount: int) (stableRootCap: int) (pendingNow: int) (stableRootKey: string) =
                                        if replay_root_finalization_requested then false
                                        elif not (EvalWorklist.hasReplayCompleteWriteWitness()) then false
                                        else
                                            replay_root_finalization_requested <- true
                                            let reasonId = ReplayRootFinalNoLiveAlternate(eventName, attempt, pendingNow)
                                            let reason = replayRootReasonText reasonId
                                            try CacheGeneration.noteReason (replayRootGenerationReason reasonId) with _ -> ()
                                            DiagJson.emit (
                                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_replay_root_complete_finalization_requested\",\"event\":%s,\"status\":\"semantic_root_complete\",\"attempt\":%d,\"next_attempt\":%d,\"max_attempts\":%d,\"stable_count\":%d,\"stable_cap\":%d,\"pending\":%d,\"frontier\":%s,\"reason\":%s,\"policy\":\"record_replay_root_reason_and_clear_volatile_worklist_for_one_final_buildfile_retry\",\"single_flight\":1,\"next\":\"attempt_build\"}" [| box (DiagJson.esc eventName); box attempt; box (attempt + 1); box maxAttempts; box stableRootCount; box stableRootCap; box pendingNow; box (DiagJson.esc stableRootKey); box (DiagJson.esc reason) |])
                                            try EvalWorklist.resetStableRootCompleteLedger () with _ -> ()
                                            try EvalWorklist.reset () with _ -> ()
                                            try TermCycleFuse.reset () with _ -> ()
                                            true
                                    let rejectLegacyReplayRetryAfterNativeCutover attempt =
                                        let nextAttempt = attempt + 1
                                        DiagJson.emit (
                                            FastRuntimeFormat.format
                                                "{\"kind\":\"legacy_replay_retry_signal_rejected\",\"attempt\":%d,\"next_attempt\":%d,\"authority_du\":\"NativeAuthorityKernel\",\"exception_trampoline\":false,\"policy\":\"legacy_retry_request_cannot_escape_as_InvalidOperationException_after_native_authority_cutover\",\"next\":\"surface_typed_native_boundary_failure\"}"
                                                [| box attempt; box nextAttempt |])
                                        raiseNativeBuildBoundaryError
                                            (nativeBuildBoundaryLegacyFallbackForbidden
                                                ("legacy_replay_retry_after_native_authority_cutover|next_attempt=" + string nextAttempt))
                                    let attempt_build (attempt: int) (max_attempts: int) =
                                        // MIGRATION: only attempt zero opens a new build epoch. Retry attempts
                                        // may reset volatile replay state but cannot reopen post-root handoffs.
                                        if attempt = 0 then EvalWorklist.beginBuildEpoch()
                                        // MIGRATION: a tripped EJP0011 fuse is per-attempt, not per server lifetime.
                                        // It suppresses sibling workers in the current attempt; a sequential retry must start clean.
                                        TermCycleFuse.reset ()
                                        if preserve_root_complete_frontier_next_attempt && attempt > 0 then
                                            // MIGRATION: MIGRATION preserved the frontier at the handoff site, but the next
                                            // attempt still began by calling EvalWorklist.reset(), erasing the proof before
                                            // the fresh evaluator could consume it.  Keep the completed root frontier for
                                            // exactly one retry attempt; ordinary retries still reset volatile worklist state.
                                            preserve_root_complete_frontier_next_attempt <- false
                                            DiagJson.emit (
                                                sprintf "{\"kind\":\"eval_worklist_resume\",\"event\":\"attempt_build\",\"status\":\"semantic_root_complete\",\"attempt\":%d,\"max_attempts\":%d,\"policy\":\"preserve_root_complete_frontier_across_attempt\",\"single_flight\":1,\"next\":\"do_build\"}"
                                                    attempt max_attempts)
                                        elif preserve_progress_frontier_next_attempt && attempt > 0 then
                                            preserve_progress_frontier_next_attempt <- false
                                            DiagJson.emit (
                                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_resume\",\"event\":\"attempt_build\",\"status\":\"progress_yield_frontier\",\"attempt\":%d,\"max_attempts\":%d,\"yield_used\":%d,\"yield_cap\":%d,\"policy\":\"preserve_progress_yield_frontier_across_attempt\",\"single_flight\":1,\"next\":\"do_build\"}" [| box attempt; box max_attempts; box frontier_yield_retry_count; box frontier_yield_retry_cap |])
                                        else
                                            EvalWorklist.reset ()
                                        if attempt = 0 then
                                            // MIGRATION: EvalWorklist.reset clears volatile frontier/replay state on every retry,
                                            // but the stable-root ledger must survive retries inside one BuildFile run.
                                            // Clear it only at the beginning of a fresh build transaction.
                                            EvalWorklist.resetStableRootCompleteLedger ()
                                            EvalWorklist.resetDurableTerminalContractLedger ()
                                            PevalStallProbe.resetRecovery ()
                                            CacheGeneration.resetSequentialRequest ()
                                            HopacExtensions.applyEnvForcedConcurrency ()
                                            // If we have active suspect keys from a previous invalidation, start this build deterministically.
                                            if SuspectCache.currentCount () > 0 then CacheGeneration.requestSequential ()
                                        if preserve_parallel_retry_next_attempt then
                                            preserve_parallel_retry_next_attempt <- false
                                            HopacExtensions.clearForcedConcurrencyForRetry ()
                                            CacheGeneration.resetSequentialRequest ()
                                            let retryGenerationPolicyId = DiagJson.RetryGenerationInvalidateLivenessParallel
                                            let retryGenerationPolicyText = DiagJson.retryGenerationPolicyText retryGenerationPolicyId
                                            let retryParallelismReassertDecisionId = DiagJson.RetryParallelismReassertAllCoresAfterLivenessRetry
                                            let retryParallelismReassertDecisionText = DiagJson.retryParallelismReassertDecisionText retryParallelismReassertDecisionId
                                            DiagJson.emit (
                                                FastRuntimeFormat.format "{\"kind\":\"build_retry_parallelism_reasserted\",\"event\":\"attempt_build\",\"attempt\":%d,\"dop_env\":%d,\"dop_forced\":%d,\"sequential_requested\":%b,\"retry_generation_policy_du\":%s,\"retry_parallelism_reassert_decision_du\":%s,\"policy\":\"liveness_retry_parallel_policy_is_attempt_local_not_global_flag\",\"single_flight\":1,\"next\":\"do_build_all_cores\"}" [| box attempt; box (HopacExtensions.envForcedConcurrency()); box (HopacExtensions.peekForcedConcurrency()); box (CacheGeneration.isSequentialRequested()); box (DiagJson.esc retryGenerationPolicyText); box (DiagJson.esc retryParallelismReassertDecisionText) |])
                                        // MIGRATION: Reset loop specialization guard on retry to prevent cascading cap failures
                                        if attempt > 0 then LoopSpecializationGuard.reset ()
                                        try
                                            let build_ok = do_build ()
                                            // Successful build: clear active suspects and stable root-complete ledger so
                                            // the next independent BuildFile run does not inherit this transaction's proof.
                                            SuspectCache.clearForGeneration (CacheGeneration.current ())
                                            EvalWorklist.resetStableRootCompleteLedger ()
                                            build_ok
                                        with
                                            | :? PartEvalTypeError as e ->
                                                let msg = e.Data1
                                                match DiagnosticClassifier.classifyIngress msg with
                                                | DiagnosticClassifier.ClassifiedIngress diagnostic when DiagnosticClassifier.isNoRetry diagnostic ->
                                                    let codeId = diagnostic.code
                                                    let code = DiagnosticClassifier.codeText codeId
                                                    // MIGRATION: native-promise terminal closures and real record_map
                                                    // semantic terminals are not retry codes.  They already represent
                                                    // RootComplete.await collapsing to a structured semantic error, so
                                                    // do not route them through the legacy EJP retry loop just because
                                                    // older context may still carry retryable EJP markers.
                                                    let noRetryKind =
                                                        match diagnostic.disposition with
                                                        | DiagnosticClassifier.DiagnosticTerminalSemantic -> "build_record_map_semantic_terminal_no_retry"
                                                        | DiagnosticClassifier.DiagnosticTerminalNative -> "build_native_promise_terminal_no_retry"
                                                        | _ -> invalidOp "retryable diagnostic reached no-retry branch"
                                                    let rootStatusId = DiagJson.RootPromiseFailed("RootComplete", msg)
                                                    let rootStatusText = DiagJson.rootPromiseStatusText rootStatusId
                                                    let nativeRootBoundaryText = DiagJson.nativeRootBoundaryState() |> DiagJson.nativeRootBoundaryStateText
                                                    let rootAwaitText = nativeRootBoundaryText
                                                    let rootExitText = "NativeRootCompleteExitAuthority(None|boundary=" + nativeRootBoundaryText + ")"
                                                    let rootCollapseText = "NativeRootCompleteCollapseAuthority(AltOnly|boundary=" + nativeRootBoundaryText + ")"
                                                    let nativeJobGraphText = "NativeJobGraph(RootCompleteAlt|boundary=" + nativeRootBoundaryText + ")"
                                                    let nativePromiseFateFinalVerdictText = rootStatusId |> DiagJson.nativePromiseFateFinalVerdictFor |> DiagJson.nativePromiseFateFinalVerdictText
                                                    let semanticDiagnosisText = DiagJson.SemanticDiagnosisNoFurther (CompilerKernelV2.OperationalReasonIdOps.create msg) |> DiagJson.semanticDiagnosisText
                                                    let typedTerminalPayload = DiagJson.minimalTerminalPayloadForBridge DiagJson.MinimalTerminalPayloadNoFurtherDelta msg semanticDiagnosisText msg 0 "terminal_no_retry"
                                                    let richTypedTerminalPayload, typedPayloadStatusId = DiagJson.promoteMinimalTerminalPayloadToRich typedTerminalPayload
                                                    let typedTerminalPayloadText = DiagJson.nativeTerminalPayloadText richTypedTerminalPayload
                                                    let typedPayloadStatusText = DiagJson.minimalToRichPayloadStatusText typedPayloadStatusId
                                                    let hopacRootExitVerdictText = DiagJson.hopacRootExitVerdictFor rootStatusId |> DiagJson.hopacRootExitVerdictText
                                                    let trampolineBypassStatusId =
                                                        match diagnostic.disposition with
                                                        | DiagnosticClassifier.DiagnosticTerminalSemantic -> DiagJson.TrampolineBypassedSemanticTerminal(code, "record_map_semantic_terminal_no_retry")
                                                        | DiagnosticClassifier.DiagnosticTerminalNative -> DiagJson.TrampolineBypassedNativeTerminal(code, "native_promise_terminal_no_retry")
                                                        | _ -> invalidOp "retryable diagnostic reached terminal bypass"
                                                    let trampolineBypassStatusText = trampolineBypassStatusId |> DiagJson.trampolineBypassStatusText
                                                    DiagJson.diagnosticEvent DiagJson.DiagnosticRetryDecision
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldEvent "attempt_build"
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldTerminalKind noRetryKind
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldCode code
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticCodeId (DiagnosticClassifier.codeIdText diagnostic.code)
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticCause (DiagnosticClassifier.causeText diagnostic.cause)
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldDiagnosticDisposition (DiagnosticClassifier.dispositionText diagnostic.disposition)
                                                    |> DiagJson.diagnosticIntKey DiagJson.DiagnosticFieldAttempt attempt
                                                    |> DiagJson.diagnosticIntKey DiagJson.DiagnosticFieldMaxAttempts max_attempts
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldFile file
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldBackend backend
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldRootPromiseStatus rootStatusText
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldRootCompleteAwaitContract rootAwaitText
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldRootCompleteExitPolicy rootExitText
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldRootCompleteCollapseDecision rootCollapseText
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldNativePromiseFateFinalVerdict nativePromiseFateFinalVerdictText
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldNativeJobGraph nativeJobGraphText
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldTypedTerminalPayload typedTerminalPayloadText
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldMinimalToRichPayloadStatus typedPayloadStatusText
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldSemanticDiagnosis semanticDiagnosisText
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldSemanticErrorPayload msg
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldSourceSpanEnrichment "typed_semantic_source_span_bridge|payload_preserved_generic"
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldHopacRootExitVerdict hopacRootExitVerdictText
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldTrampolineBypassStatus trampolineBypassStatusText
                                                    |> DiagJson.diagnosticBoolKey DiagJson.DiagnosticFieldRetrySuppressed true
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldPolicy "typed_terminal_disposition_bypasses_legacy_retry"
                                                    |> DiagJson.diagnosticIntKey DiagJson.DiagnosticFieldSingleFlight 1
                                                    |> DiagJson.diagnosticStringKey DiagJson.DiagnosticFieldNext "BuildErrorTrace_structured_semantic_error"
                                                    |> DiagJson.renderDiagnosticEvent
                                                    |> DiagJson.emit
                                                    raise (partEvalTypeError e.Data0 e.Data1)
                                                | DiagnosticClassifier.ClassifiedIngress diagnostic when DiagnosticClassifier.isRetryable diagnostic ->
                                                    let codeId = diagnostic.code
                                                    let code = DiagnosticClassifier.codeText codeId
                                                    let diagnosticCauseId = DiagnosticClassifier.causeText diagnostic.cause
                                                    let diagnosticDispositionId = DiagnosticClassifier.dispositionText diagnostic.disposition
                                                    // Retry logic: invalidate cache and optionally reduce parallelism
                                                    let gen_before = CacheGeneration.current ()
                                                    let is_gen_wait =
                                                        (codeId = DiagnosticClassifier.DiagnosticEJP0008 && DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticGenerationChangedWhileWaiting diagnostic)
                                                        || (codeId = DiagnosticClassifier.DiagnosticEJP0016 && DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticDeadIvarWhileWaiting diagnostic)
                                                        || (codeId = DiagnosticClassifier.DiagnosticEJP0018 && DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticBigStackGenerationChanged diagnostic)

                                                    let is_term_reentry_fuse =
                                                        codeId = DiagnosticClassifier.DiagnosticEJP0011
                                                        && ([
                                                            DiagnosticClassifier.DiagnosticGlobalTermCycleFuseTripped
                                                            DiagnosticClassifier.DiagnosticJpWaitObservedSequentialTermCycle
                                                            DiagnosticClassifier.DiagnosticReentrantTermCycle
                                                            DiagnosticClassifier.DiagnosticReentrantTypeCycle
                                                        ]
                                                        |> List.exists (fun fact -> DiagnosticClassifier.hasFact fact diagnostic))

                                                    let _term_cycle_kind, term_cycle_key, term_cycle_site, term_cycle_depth, term_cycle_gen, term_cycle_re, term_cycle_max_re =
                                                        if is_term_reentry_fuse then TermCycleFuse.describe ()
                                                        else None, "", "", 0, 0, 0, 0

                                                    let is_term_cycle_after_seq =
                                                        is_term_reentry_fuse
                                                        && attempt > 0
                                                        && CacheGeneration.isSequentialRequested()

                                                    let is_jp_wait_observed_seq_cycle =
                                                        codeId = DiagnosticClassifier.DiagnosticEJP0011
                                                        && DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticJpWaitObservedSequentialTermCycle diagnostic
                                                        && CacheGeneration.isSequentialRequested()
                                                        && EvalWorklistFrontier.isDeepSequentialCycle term_cycle_depth term_cycle_re term_cycle_max_re

                                                    // MIGRATION: BigStack can be the first component to notice a
                                                    // live-lock even though EvalWorklist has already proven a
                                                    // semantic_root_complete frontier.  Treat that as the same
                                                    // bounded root-complete handoff path used by retry_stop, not as
                                                    // a normal cache invalidation.
                                                    let is_bigstack_root_complete_handoff_msg =
                                                        codeId = DiagnosticClassifier.DiagnosticEJP0019
                                                        && ([
                                                            DiagnosticClassifier.DiagnosticBigStackSemanticRootCompleteHandoff
                                                            DiagnosticClassifier.DiagnosticSemanticRootComplete
                                                            DiagnosticClassifier.DiagnosticFrameSemanticRootComplete
                                                            DiagnosticClassifier.DiagnosticReplayComplete
                                                        ] |> List.exists (fun fact -> DiagnosticClassifier.hasFact fact diagnostic))
                                                    let is_bigstack_root_complete_handoff =
                                                        codeId = DiagnosticClassifier.DiagnosticEJP0019
                                                        && (EvalWorklist.hasReplayComplete()
                                                            || is_bigstack_root_complete_handoff_msg
                                                            || EvalWorklist.hasReplayCompleteWriteWitness())
                                                        && (DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticSemanticRootComplete diagnostic
                                                            || DiagnosticClassifier.hasFact DiagnosticClassifier.DiagnosticBigStackJoinObserved diagnostic)

                                                    if is_bigstack_root_complete_handoff && canUseRootCompleteReplayAttempt attempt then
                                                        noteRootCompleteHandoffCapExtension "bigstack_root_complete_handoff" attempt
                                                        let stableRootCount, stableRootKey, stableRootFacts = EvalWorklist.noteRootCompleteHandoff()
                                                        if is_bigstack_root_complete_handoff_msg && stableRootKey = "none" then
                                                            DiagJson.emit (
                                                                FastRuntimeFormat.format "{\"kind\":\"eval_worklist_bigstack_root_complete_message_evidence\",\"event\":\"bigstack_root_complete_handoff\",\"attempt\":%d,\"max_attempts\":%d,\"stable_count\":%d,\"stable_key\":%s,\"pending\":%d,\"write_witness\":%b,\"policy\":\"route_ejp0019_message_root_complete_through_root_handoff_retry_without_invalidating_generation\",\"single_flight\":1,\"next\":\"retry_clean_buildfile_with_preserved_root_frontier\"}" [| box attempt; box max_attempts; box stableRootCount; box (DiagJson.esc stableRootKey); box (EvalWorklist.pendingCount()); box (EvalWorklist.hasReplayCompleteWriteWitness()) |])
                                                        if stableRootCount >= stable_root_complete_handoff_cap then
                                                            match EvalWorklist.tryYieldStableRootCompleteHandoff "bigstack_root_complete_livelock" with
                                                            | Some selected when frameSemanticStatusIs SemanticSelectedFrontierRepeatBlocked selected ->
                                                                DiagJson.emit (
                                                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_root_handoff_terminal_abort\",\"event\":\"bigstack_root_complete_livelock\",\"status\":%s,\"attempt\":%d,\"max_attempts\":%d,\"stable_count\":%d,\"stable_cap\":%d,\"frontier\":%s,\"policy\":\"selected_frontier_repeat_is_terminal_not_retry\",\"single_flight\":1,\"next\":\"abort_without_root_handoff_retry\"}" [| box (DiagJson.esc (EvalWorklist.frameStatusToString selected.status)); box attempt; box max_attempts; box stableRootCount; box stable_root_complete_handoff_cap; box (DiagJson.esc stableRootKey) |])
                                                                raise (PartEvalTypeError([], EvalWorklist.requiredMessage (sprintf "selected frontier repeated under BigStack root-complete handoff count=%d cap=%d" stableRootCount stable_root_complete_handoff_cap) selected))
                                                            | Some selected when frameSemanticStatusIs SemanticReplayFingerprintRepeatBlocked selected && Set.contains EvalWorklist.StableRootSemanticRootComplete stableRootFacts && EvalWorklist.hasReplayCompleteWriteWitness() && EvalWorklist.pendingCount() > 0 ->
                                                                    let pendingNow = EvalWorklist.pendingCount()
                                                                    let witnessSummary = EvalWorklist.replayCompleteWriteWitnessSummary()
                                                                    let retryReason = FastRuntimeFormat.format "generic_root_handoff_fingerprint_repeat_deferred attempt=%d pending=%d site=%s" [| box attempt; box pendingNow; box selected.site |]
                                                                    try CacheGeneration.noteReasonWithSignal CacheGeneration.GenerationReasonUnclassified (CacheGeneration.GenerationChangeReasonIdOps.create retryReason) with _ -> ()
                                                                    DiagJson.emit (
                                                                        FastRuntimeFormat.format "{\"kind\":\"eval_worklist_root_handoff_fingerprint_repeat_deferred\",\"event\":\"stable_root_complete_livelock\",\"status\":%s,\"selected_kind\":%s,\"selected_site\":%s,\"attempt\":%d,\"next_attempt\":%d,\"max_attempts\":%d,\"stable_count\":%d,\"stable_cap\":%d,\"pending\":%d,\"frontier\":%s,\"witness\":%s,\"policy\":\"fingerprint_repeat_under_root_complete_handoff_is_drain_retry_not_terminal_pin\",\"writer_gate\":\"requires_replay_root_reason_and_live_root_witness\",\"single_flight\":1,\"next\":\"retry_clean_buildfile_with_preserved_root_frontier\"}" [| box (DiagJson.esc (EvalWorklist.frameStatusToString selected.status)); box (DiagJson.esc (EvalWorklist.frameKindText selected)); box (DiagJson.esc (EvalWorklist.frameSiteText selected)); box attempt; box (attempt + 1); box max_attempts; box stableRootCount; box stable_root_complete_handoff_cap; box pendingNow; box (DiagJson.esc stableRootKey); box (DiagJson.esc witnessSummary) |])
                                                                    try EvalWorklist.resetStableRootCompleteLedger () with _ -> ()
                                                                    try TermCycleFuse.reset () with _ -> ()
                                                                    preserve_root_complete_frontier_next_attempt <- true
                                                                    rejectLegacyReplayRetryAfterNativeCutover attempt
                                                                | Some selected when not (frameSemanticStatusIs SemanticRootComplete selected) && EvalWorklist.isTerminalContractStatusId (EvalWorklist.frameSemanticStatusId selected) ->
                                                                DiagJson.emit (
                                                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_root_handoff_pinned_terminal_abort\",\"event\":\"bigstack_root_complete_livelock\",\"status\":%s,\"rank\":%d,\"attempt\":%d,\"max_attempts\":%d,\"stable_count\":%d,\"stable_cap\":%d,\"frontier\":%s,\"policy\":\"pinned_terminal_is_not_progress_yield_frontier\",\"single_flight\":1,\"next\":%s}" [| box (DiagJson.esc (EvalWorklist.frameStatusToString selected.status)); box (EvalWorklist.terminalContractRank selected.status); box attempt; box max_attempts; box stableRootCount; box stable_root_complete_handoff_cap; box (DiagJson.esc stableRootKey); box (DiagJson.esc (EvalWorklist.terminalContractNext selected.status)) |])
                                                                raise (PartEvalTypeError([], EvalWorklist.requiredMessage (sprintf "pinned terminal under BigStack root-complete handoff count=%d cap=%d" stableRootCount stable_root_complete_handoff_cap) selected))
                                                            | Some selected ->
                                                                let selectedIsRootComplete = frameSemanticStatusIs SemanticRootComplete selected
                                                                let resumeStatus = if selectedIsRootComplete then "semantic_root_complete" else "progress_yield_frontier"
                                                                let resumePolicy = if selectedIsRootComplete then "yield_repeated_bigstack_root_complete_handoff" else "yield_selected_frontier_without_root_preserve"
                                                                DiagJson.emit (
                                                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_resume\",\"event\":\"bigstack_root_complete_livelock\",\"status\":%s,\"attempt\":%d,\"next_attempt\":%d,\"max_attempts\":%d,\"stable_count\":%d,\"stable_cap\":%d,\"selected_kind\":%s,\"selected_status\":%s,\"frontier\":%s,\"policy\":%s,\"single_flight\":1,\"next\":\"attempt_selected_frontier\"}" [| box (DiagJson.esc resumeStatus); box attempt; box (attempt + 1); box max_attempts; box stableRootCount; box stable_root_complete_handoff_cap; box (DiagJson.esc (EvalWorklist.frameKindText selected)); box (DiagJson.esc (EvalWorklist.frameStatusToString selected.status)); box (DiagJson.esc stableRootKey); box (DiagJson.esc resumePolicy) |])
                                                                DiagJson.emit (
                                                                    FastRuntimeFormat.format "{\"kind\":\"eval_worklist_selected_frontier_progress_retry\",\"event\":\"bigstack_root_complete_livelock\",\"selected_kind\":%s,\"selected_status\":%s,\"selected_site\":%s,\"attempt\":%d,\"next_attempt\":%d,\"single_flight\":1,\"next\":\"preserve_selected_frontier_not_root\"}" [| box (DiagJson.esc (EvalWorklist.frameKindText selected)); box (DiagJson.esc (EvalWorklist.frameStatusToString selected.status)); box (DiagJson.esc (EvalWorklist.frameSiteText selected)); box attempt; box (attempt + 1) |])
                                                                noteRootCompleteYieldRetryBudget "bigstack_root_complete_livelock" attempt (attempt + 1)
                                                                if selectedIsRootComplete then
