                                                                "root_resolved_artifact_projection_reentry|" + rootResolutionText
                                                            let decisionPayload =
                                                                "{\"root_resolution_du\":" + DiagJson.esc rootResolutionText
                                                                + ",\"reason\":\"root_resolved_before_codegen_artifact_projection_is_expected\""
                                                                + ",\"scheduler_push_event_du\":\"SchedulerPushEvent(PushArtifactCommitRequested)\""
                                                                + ",\"scheduler_push_authority_du\":\"SchedulerPushAuthority(id=push:artifact-commit-request|writer_required=true|renderer=false|metronome=false)\""
                                                                + ",\"breakthrough_exit_arbiter_du\":\"BreakthroughErased(replacement=artifact_commit_request_ivar)\""
                                                                + ",\"native_terminal_exit_contract_du\":\"NativeTerminalExitContract(id=exit-contract:artifact-projection-reentry|outcome=pending_artifacts|authority=scheduler_push_actor|exit=none)\"}"
                                                            let artifactReentryDecisionChanged =
                                                                DiagJson.emitNativeAuthorityDecisionChange
                                                                    "writer:artifact_projection_reentry"
                                                                    decisionHash
                                                                    decisionPayload
                                                            if artifactReentryDecisionChanged then
                                                                DiagJson.emit (
                                                                    "{\"kind\":\"native_authority_decision_change\",\"decision\":\"writer_artifact_projection_reentry\",\"authority_hash\":"
                                                                    + DiagJson.esc decisionHash + ",\"payload\":" + decisionPayload + "}")
                                                            let reentryDraft : BuildDraft =
                                                                if artifact_projection_reentry_used then
                                                                    BuildDraft.Skip
                                                                else
                                                                    artifact_projection_reentry_used <- true
                                                                    do_build ()
                                                            buildResult <- reentryDraft
                                                            completed <- true
                                                        | DiagJson.NativeRootCompleteSemanticFailure(_, _, payloadClass, _) ->
                                                            raise (PartEvalTypeError([], "native_root_complete_semantic_failure:" + payloadClass))
                                                        | DiagJson.NativeRootCompleteNoFurther(_, _, reason, _) ->
                                                            raise (PartEvalTypeError([], "native_root_complete_no_further:" + CompilerKernelV2.OperationalReasonIdOps.text reason))
                                                    | None ->
                                                        raise (PartEvalTypeError([], "root_complete_alt_not_armed_before_legacy_handoff_exhaustion|" + semanticRootCompletePayload))
                                                | _ -> reraise ()
                                        buildResult
                                    try
                                        attempt_build 0 max_attempts
                                    finally
                                        HopacExtensions.clearForcedConcurrencyForRetry ()
    

                                with
                                    | :? PartEvalTypeError as e -> BuildDraft.ErrorTrace(show_trace s e.Data0 e.Data1)
                                    | :? CodegenError as e -> BuildDraft.FatalError(e.Data1)
                                    | :? CodegenErrorWithPos as e -> BuildDraft.ErrorTrace(show_trace s e.Data0 e.Data1)
                                    | ex ->
                                        CompilerConsoleHud88.captureBuildBoundaryException "Supervisor.supervisor_server.BuildFile.file_build" ex
                                        if diag_save_enabled && System.IO.Directory.Exists traceDir then
                                            let guid = System.DateTime.Now |> SpiralDateTime.new_guid_from_date_time
                                            let trace_file = traceDir </> $"{guid}_error.json"
                                            HopacExtensions.start (job {
                                                try
                                                    do! Job.fromAsync ($"{ex}" |> SpiralFileSystem.write_all_text_async trace_file)
                                                with ex ->
                                                    trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build / ex: {ex |> SpiralSm.format_exception}") _locals
                                            })
                                        trace Critical (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build / ex: %A{ex}") _locals
                                        // Unexpected .NET exceptions (NullReference, InvalidOperation, ...) carry no Spiral
                                        // trace, so keep the innermost compiler frames: without them a crash like the closure
                                        // NullReferenceException is only reproducible under a debugger.
                                        let frames =
                                            match ex with
                                            | :? NullReferenceException | :? InvalidOperationException | :? ArgumentException
                                            | :? IndexOutOfRangeException | :? InvalidCastException | :? KeyNotFoundException ->
                                                (if isNull ex.StackTrace then "" else ex.StackTrace).Split('\n')
                                                |> Array.map (fun line -> line.Trim())
                                                |> Array.filter (fun line -> line.Contains "Polyglot")
                                                |> Array.truncate 8
                                            | _ -> [||]
                                        if frames.Length = 0 then BuildDraft.FatalError(ex.Message)
                                        else BuildDraft.FatalError(ex.Message + "\n" + String.concat "\n" frames)
                            | _, None -> BuildDraft.FatalError $"Cannot find `main` in file {Path.GetFileNameWithoutExtension file}."
    

                        // DOMAIN MIGRATION : remove the dedicated 1.5GB single-flight
                        // OS thread. The evaluator is now a native Hopac job envelope whose
                        // result is an IVar edge. Recursive evaluator frames must migrate to
                        // explicit continuation nodes instead of buying stack with a thread.
                        let result = IVar()
                        // body() is synchronous and blocks by design: BigStack joins the thread that runs the
                        // evaluator, and that thread runs Hopac jobs. Called on a Hopac worker, the join parked
                        // the very worker the evaluator needed: with one worker every build deadlocked, and with
                        // N workers builds stalled at random once N were parked. Run it on its own thread and
                        // await the result without holding a worker.
                        let bodyOffWorker () : System.Threading.Tasks.Task<BuildDraft> =
                            let completion = System.Threading.Tasks.TaskCompletionSource<BuildDraft>(System.Threading.Tasks.TaskCreationOptions.RunContinuationsAsynchronously)
                            let thread =
                                System.Threading.Thread(
                                    (fun () ->
                                        try completion.SetResult(body ())
                                        with ex -> completion.SetException ex),
                                    256 * 1024 * 1024)
                            thread.IsBackground <- true
                            thread.Name <- "spiral-build-file-body"
                            thread.Start()
                            completion.Task
                        HopacExtensions.start (job {
                            let! buildDraft = HopacExtensions.awaitTask (bodyOffWorker ())
                            let! buildResult =
                                match buildDraft with
                                | BuildDraft.Provisional artifacts ->
                                    job {
                                        let artifactManifestText =
                                            artifacts
                                            |> List.map (fun artifact -> artifact.file_extension + "\u001f" + artifact.code)
                                            |> String.concat "\u001e"
                                        // The artifact commit is a rendezvous with the terminal writer, which only
                                        // arrives once its native root-complete proof and owner-ledger closure succeed.
                                        // When it never does, the generated code was stranded here. Wait a bounded grace
                                        // (SPIRAL_ARTIFACT_COMMIT_GRACE_MS, default 20; 0 waits for the writer forever)
                                        // and then commit locally; WriteGuard and the result boundary still apply.
                                        // The writer has not arrived in any measured frontier/smoke build, so the grace
                                        // is pure latency on every successful compile; keep it short.
                                        let commitGraceMs =
                                            match System.Int32.TryParse(System.Environment.GetEnvironmentVariable "SPIRAL_ARTIFACT_COMMIT_GRACE_MS") with
                                            | true, value when value >= 0 -> value
                                            | _ -> 20
                                        let commitSlot = IVar()
                                        HopacExtensions.start (BigStack.terminalFlowCommitArtifactsFromBuildDraftJob artifactManifestText >>= IVar.tryFill commitSlot)
                                        let localCommit () : Result<BigStack.TerminalFlowBuildDraftCommitReceipt, CompilerKernelV2.OperationalReasonId> =
                                            let hash =
                                                System.Convert.ToHexString(
                                                    System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes artifactManifestText)).ToLowerInvariant()
                                            DiagJson.emit (
                                                "{\"kind\":\"artifact_commit_local_fallback\",\"reason\":\"terminal_writer_absent_after_grace\",\"grace_ms\":"
                                                + string commitGraceMs + ",\"artifact_set_hash\":" + DiagJson.esc hash + "}")
                                            Ok { cellId = "local-commit"
                                                 artifactSetHash = hash
                                                 capabilityText = "LocalCommit(terminal_writer_absent)"
                                                 resolutionText = "LocalCommit"
                                                 workDagText = "LocalCommit"
                                                 terminalSealText = "LocalCommit(terminal_writer_absent)"
                                                 finalize = fun _ -> Job.unit () }
                                        let! commitResult =
                                            if commitGraceMs = 0 then IVar.read commitSlot
                                            else
                                                Hopac.Alt.choose [
                                                    IVar.read commitSlot
                                                    Hopac.timeOutMillis commitGraceMs |> Hopac.Alt.afterFun (fun () -> localCommit ())
                                                ]
                                        match commitResult with
                                        | Ok commitReceipt ->
                                            let decisionPayload =
                                                "{\"cell_id\":" + DiagJson.esc commitReceipt.cellId
                                                + ",\"writer_capability_du\":" + DiagJson.esc commitReceipt.capabilityText
                                                + ",\"root_resolution_du\":" + DiagJson.esc commitReceipt.resolutionText
                                                + ",\"work_dag_du\":" + DiagJson.esc commitReceipt.workDagText
                                                + ",\"terminal_build_ok_seal_du\":" + DiagJson.esc commitReceipt.terminalSealText
                                                + ",\"artifact_set_hash\":" + DiagJson.esc commitReceipt.artifactSetHash
                                                + ",\"artifact_count\":" + string artifacts.Length
                                                + ",\"artifact_persistence_state_du\":\"PreparedAwaitingWriteGuard\""
                                                + ",\"artifact_commit_authority\":\"two_phase_filesystem_persistence\"}"
                                            if DiagJson.emitNativeAuthorityDecisionChange
                                                "writer:build_ok_persistence_prepared"
                                                commitReceipt.artifactSetHash
                                                decisionPayload then
                                                DiagJson.emit (
                                                    "{\"kind\":\"native_authority_decision_change\",\"decision\":\"writer_build_ok_persistence_prepared\",\"authority_hash\":"
                                                    + DiagJson.esc commitReceipt.artifactSetHash + ",\"payload\":" + decisionPayload + "}")
                                            DiagJson.emit (
                                                "{\"kind\":\"writer_build_ok_persistence_prepared\",\"event\":\"prepared\",\"seal_du\":"
                                                + DiagJson.esc commitReceipt.terminalSealText
                                                + ",\"artifact_set_hash\":" + DiagJson.esc commitReceipt.artifactSetHash
                                                + ",\"root_resolution_du\":" + DiagJson.esc commitReceipt.resolutionText
                                                + ",\"work_dag_du\":" + DiagJson.esc commitReceipt.workDagText
                                                + ",\"artifact_commit_authority\":\"two_phase_filesystem_persistence\""
                                                + ",\"next\":\"writeguard_then_finalize_writer_completion\"}")
                                            return BuildOk {
                                                artifacts = artifacts
                                                writerCapabilityDu = commitReceipt.capabilityText
                                                artifactSetHash = commitReceipt.artifactSetHash
                                                rootResolutionDu = commitReceipt.resolutionText
                                                workDagDu = commitReceipt.workDagText
                                                terminalSealDu = commitReceipt.terminalSealText
                                                finalizeArtifacts = commitReceipt.finalize
                                            }
                                        | Error reason ->
                                            return BuildErrorTrace([], nativeBuildBoundaryErrorText (nativeBuildBoundaryWriterAuthorizationRejected reason))
                                    }
                                | BuildDraft.ErrorTrace(traceLines, message) ->
                                    BigStack.terminalFlowRejectArtifactsFromBuildDraft (CompilerKernelV2.OperationalReasonIdOps.create message)
                                    job { return BuildErrorTrace(traceLines, message) }
                                | BuildDraft.FatalError message ->
                                    BigStack.terminalFlowRejectArtifactsFromBuildDraft (CompilerKernelV2.OperationalReasonIdOps.create message)
                                    job { return BuildFatalError message }
                                | BuildDraft.Skip -> job { return BuildSkip }
                            do! IVar.fill result buildResult
                        })
                        IVar.read result >>= handle_build_result
                        )
                let file_find (s : SupervisorState) pdir =
                    trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_find / pdir: {pdir}") _locals
                    let uid = (fst s.package_ids).[SchemaPathIdOps.create pdir]
                    match Map.tryFind uid s.packages_infer.ok, Map.tryFind uid s.packages_prepass.ok with
                    | Some a, Some b ->
                        let rec loop = function
                            | ProjFilesTree.Directory(_,_,l) -> list l
                            | ProjFilesTree.File(mid,path,_) ->
                                trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_find.loop | File(mid,path,_) / path: {path}") _locals
                                if file = path then
                                    // An exception while setting the build up (a null slot of a reset package
                                    // state, ...) used to vanish here and leave BuildFile to the stall budget.
                                    try file_build s mid (a, b)
                                    with ex -> fatal $"BuildFile setup failed for {Path.GetFileNameWithoutExtension file}: {ex.GetType().Name}: {ex.Message}"
                                    true
                                else false
                        and list l = List.exists loop l
                        if list b.files.files.tree = false then fatal $"File {Path.GetFileNameWithoutExtension file} cannot be found in the project {spiproj_suffix pdir}"


                        s
                    | None, None -> fatal $"Owner of file {Path.GetFileNameWithoutExtension file} has an error. Location: {spiproj_suffix pdir}"; s
                    | _ -> failwith "Compiler error: The project status should be the same in both infer and prepass."
                let update_owner pdir =
                    let orderIds,dirtyPackageIds =
                        topological_sort'
                            (fst s.graph)
                            [GraphPathIdOps.create pdir]
                    let order = orderIds.ToArray() |> Array.map GraphPathIdOps.text
                    let dirtyPackages =
                        HashSet<string>(dirtyPackageIds |> Seq.map GraphPathIdOps.text)
                    let packages_prepass =
                        wdiff_projenvr_prepass
                            default_env
                            (fst s.package_ids)
                            s.packages
                            s.packages_infer.ok
                            s.packages_prepass
                            (dirtyPackages, order)
                    file_find {s with packages_prepass = packages_prepass} pdir
                let rec find_owner (x : DirectoryInfo) =
                    if x = null then fatal $"Cannot find the package file of {file}"; s
                    else
                        let x' = x.FullName |> SpiralFileSystem.standardize_path
                        let _diag_bslash = "\\\\"
                        let _diag_pipe = "|"
                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.find_owner / x.FullName: {x.FullName |> SpiralSm.replace _diag_bslash _diag_pipe} / x': {x'}") _locals
                        let x_ = x
                        let x = {| FullName = x' |}
                        if SchemaEnv.containsText x.FullName s.packages then update_owner x.FullName
                        else find_owner x_.Parent
                find_owner (Directory.GetParent(file))
    

        Job.iterateServer {
            packages = Map.empty
            modules = Map.empty
            packages_infer = {ok=Map.empty; error=Map.empty}
            packages_prepass = {ok=Map.empty; error=Map.empty}
            graph = mirrored_graph_empty
            package_ids = Map.empty, Map.empty
            } loop
    

    /// ### ClientReq
    type ClientReq =
        | ProjectFileOpen of {|uri : string; spiprojText : string|}
        | ProjectFileChange of {|uri : string; spiprojText : string|}
        | ProjectFileLinks of {|uri : string|}
        | ProjectCodeActionExecute of {|uri : string; action : ProjectCodeAction|}
        | ProjectCodeActions of {|uri : string|}
        | FileOpen of {|uri : string; spiText : string|}
        | FileChange of {|uri : string; spiEdit : SpiEdit|}
        | FileDelete of {|uris : string []|} // Also works for project files and directories.
        | FileTokenRange of {|uri : string; range : VSCRange|}
        | HoverAt of {|uri : string; pos : VSCPos|}
        | BuildFile of {|uri : string; backend : string|}
        | Ping of bool
        | Exit of bool
    

    /// ### ClientErrorsRes
    type ClientErrorsRes =
        | FatalError of string
        | TracedError of TracedError
        | PackageErrors of {|uri : string; errors : RString list|}
        | TokenizerErrors of {|uri : string; errors : RString list|}
        | ParserErrors of {|uri : string; errors : RString list|}
        | TypeErrors of {|uri : string; errors : RString list|}

    let private clientErrorsResKindText = function
        | FatalError _ -> "fatal_error"
        | TracedError _ -> "traced_error"
        | PackageErrors _ -> "package_errors"
        | TokenizerErrors _ -> "tokenizer_errors"
        | ParserErrors _ -> "parser_errors"
        | TypeErrors _ -> "type_errors"
    

    /// ### Supervisor
    type Supervisor = {
        supervisor_ch : SupervisorReq Ch
        }
    

#else
    /// ## SignalRSupervisor
    // open System
    open System.IO
    open System.Collections.Generic

    open Hopac
    open Hopac.Infixes
    open Hopac.Extensions
    open Hopac.Stream

    // open Common
    open SpiralFileSystem.Operators

    /// ### LocalizedErrors
    type LocalizedErrors = {|uri : string; errors : RString list|}

    /// ### TracedError
    type TracedError = {|trace : string list; message : string|}

    /// ### SupervisorErrorSources
    type SupervisorErrorSources = {
        fatal : string Ch
        tokenizer : LocalizedErrors Ch
        parser : LocalizedErrors Ch
        typer : LocalizedErrors Ch
        package : LocalizedErrors Ch
        traced : TracedError Ch
        }

    /// ### SupervisorReq
    type ProjectFileReq = {|uri : string; spiprojText : string|}
    type UriReq = {|uri : string|}
    type ProjectCodeActionReq = {|uri : string; action : ProjectCodeAction|}
    type ProjectCodeActionResult = {|result : string option|}
    type FileOpenReq = {|uri : string; spiText : string|}
    type FileChangeReq = {|uri : string; spiEdit : SpiEdit|}
    type FileDeleteReq = {|uris : string []|}
    type FileTokenRangeReq = {|uri : string; range : VSCRange|}
    type HoverAtReq = {|uri : string; pos : VSCPos|}
    type BuildFileReq = {|uri : string; backend : string|}
    type SupervisorReq =
        | ProjectFileOpen of ProjectFileReq
        | ProjectFileChange of ProjectFileReq
        | ProjectFileLinks of UriReq * RString list IVar
        | ProjectCodeActions of UriReq * RAction list IVar
        | ProjectCodeActionExecute of ProjectCodeActionReq * ProjectCodeActionResult IVar
        | FileOpen of FileOpenReq
        | FileChange of FileChangeReq
        | FileDelete of FileDeleteReq
        | FileTokenRange of FileTokenRangeReq * int [] IVar
        | HoverAt of HoverAtReq * string option IVar
        | BuildFile of BuildFileReq * string option IVar

    /// ### SupervisorState
    type SupervisorState = {
        packages : SchemaEnv
        modules : ModuleEnv
        packages_infer : ResultMap<PackageId,ProjStateTC>
        packages_prepass : ResultMap<PackageId,ProjStatePrepass>
        graph : MirroredGraph
        package_ids : Map<string,int> * Map<int,string>
        }

    /// ### proj_validate
    let proj_validate default_env s dirty_packages =
        let order,socs = circular_nodes s.graph dirty_packages
        let packages = ss_validate s.packages s.modules (order,socs)
        let packages_infer = wdiff_projenvr_tc default_env (fst s.package_ids) packages s.modules s.packages_infer (dirty_packages, order)
        order, {s with packages_infer = packages_infer; packages=packages}

    /// ### proj_graph_update
    let proj_graph_update default_env s dirty_packages =
        let removed_pids,package_ids = package_ids_update s.packages s.package_ids dirty_packages
        let packages_infer, packages_prepass = package_ids_remove s.packages_infer removed_pids, package_ids_remove s.packages_prepass removed_pids
        let graph = graph_update s.packages s.graph dirty_packages
        proj_validate default_env {s with graph = graph; package_ids = package_ids; packages_infer = packages_infer; packages_prepass = packages_prepass} dirty_packages

    /// ### proj_open
    let proj_open default_env s (dir, text) =
        let packages,dirty_packages,modules = loader_package default_env s.packages s.modules (dir,text)
        proj_graph_update default_env {s with packages = packages; modules = modules} dirty_packages

    /// ### proj_revalidate_owner
    let proj_revalidate_owner default_env s file =
        let rec loop (x : DirectoryInfo) =
            if x = null then [||], s
            else
                let x' = x.FullName |> SpiralFileSystem.standardize_path
                // trace Verbose (fun () -> $"""Supervisor.proj_revalidate_owner / x.FullName: {x.FullName |> SpiralSm.replace "\\" "|"} / x': {x'}""") _locals
                let x_ = x
                let x = {| FullName = x' |}
                if Map.containsKey x.FullName s.packages then proj_validate default_env s (HashSet [x.FullName])
                elif File.Exists(spiproj_suffix x.FullName) then proj_open default_env s (x.FullName,None)
                else loop x_.Parent
        loop (Directory.GetParent(file))

    /// ### file_delete
    let file_delete default_env s (files : string []) =
        let deleted_modules = HashSet()
        let deleted_packages = HashSet()
        files |> Array.iter (fun k ->
            s.packages |> Map.iter (fun k' _ -> if (spiproj_suffix k').StartsWith(k) then deleted_packages.Add(k') |> ignore)
            s.modules |> Map.iter (fun k' _ -> if k'.StartsWith(k) then deleted_modules.Add(k') |> ignore)
            )
        let modules = Seq.foldBack Map.remove deleted_modules s.modules
        let packages = Seq.foldBack Map.remove deleted_packages s.packages
        let dirty_packages = HashSet(deleted_packages)
        let revalidate_parent (x : string) =
            trace Verbose (fun () -> $"Supervisor.file_delete.revalidate_parent.loop / x.FullName: {x}") _locals
            let rec loop (x : DirectoryInfo) =
                if x <> null then
                    let x' = x.FullName |> SpiralFileSystem.standardize_path
                    let x = DirectoryInfo x'
                    if Map.containsKey x.FullName s.packages then dirty_packages.Add(x.FullName) |> ignore
                    else loop x.Parent
            loop(Directory.GetParent x)
        Seq.iter revalidate_parent deleted_modules; Seq.iter revalidate_parent deleted_packages
        Seq.toArray deleted_modules, proj_graph_update default_env {s with modules = modules; packages = packages} dirty_packages

    /// ### AttentionState
    type AttentionState = {
        modules : string Set * string list
        packages : string Set * string list
        old_packages : SchemaEnv
        supervisor : SupervisorState
        }

    /// ### attention_server
    let attention_server (errors : SupervisorErrorSources) (req : _ Ch) =
        let push path (s,o) = Set.add path s, path :: o
        let add (s,o) l = Array.foldBack (fun x (s,o as z) -> if Set.contains x s then z else Set.add x s, x :: o) l (s,o)
        let update (s : AttentionState) (modules,packages,supervisor) = {modules = add s.modules modules; packages = add s.packages packages; supervisor = supervisor; old_packages = s.supervisor.packages}
        let rec loop (s : AttentionState) =
            let clear uri =
                Hopac.start (Ch.send errors.tokenizer {|uri=uri; errors=[]|})
                Hopac.start (Ch.send errors.parser {|uri=uri; errors=[]|})
                Hopac.start (Ch.send errors.typer {|uri=uri; errors=[]|})
            let send_tokenizer uri x = Hopac.start (Ch.send errors.tokenizer {|uri=uri; errors=x|})
            let clear_parse uri = Hopac.start (Ch.send errors.parser {|uri=uri; errors=[]|})
            let clear_typer uri = Hopac.start (Ch.send errors.typer {|uri=uri; errors=[]|})
            let clear_old_package x = Map.tryFind x s.old_packages |> Option.iter (fun x ->
                let rec loop = function
                    | FileHierarchy.File(_,(_,pdir),_) -> clear (file_uri pdir)
                    | FileHierarchy.Directory(_,_,_,l) -> list l
                and list l = List.iter loop l
                list x.schema.modules
                )

            let inline body uri interrupt ers ers' src next =
                Ch.Try.take req >>=* function
                | Some x -> interrupt x
                | None ->
                    if List.isEmpty ers then next ers'
                    else
                        let ers = List.append ers ers'
                        Hopac.start (Ch.send src {|uri=uri; errors=ers|})
                        next ers

            let loop_module (s : AttentionState) mpath (m : ModuleState) =
                let uri = file_uri mpath
                let interrupt x = loop (update {s with modules=push mpath s.modules} x)
                let rec bundler (r : BlockBundleState) ers' = r >>=* function
                    | Cons((_,x),rs) -> body uri interrupt x.errors ers' errors.parser (bundler rs)
                    | Nil -> loop s
                send_tokenizer uri m.tokenizer.errors
                clear_parse uri
                clear_typer uri
                bundler m.bundler []

            let rec loop_package (s : AttentionState) pdir = function
                | (mpath,l) :: ls ->
                    let mpath' = mpath |> SpiralFileSystem.standardize_path
                    let uri = file_uri mpath
                    let pdir' = pdir |> SpiralFileSystem.standardize_path
                    trace Verbose (fun () -> $"Supervisor.attention_server.loop.loop_package / mpath: {mpath} / mpath': {mpath'} / uri: {uri} / pdir: {pdir} / pdir': {pdir'}") _locals
                    let interrupt x = loop (update {s with packages=push pdir s.packages} x)
                    let rec typer (r : TypecheckerStateValue Stream) ers' = r >>=* function
                        | Cons((_,x,_),rs) -> body uri interrupt x.errors ers' errors.typer (typer rs)
                        | Nil -> loop_package s pdir' ls
                    let rec bundler (r : BlockBundleState) ers' = r >>=* function
                        | Cons((_,x),rs) -> body uri interrupt x.errors ers' errors.parser (bundler rs)
                        | Nil -> clear_typer uri; typer l []
                    match Map.tryFind mpath' s.supervisor.modules with
                    | None ->
                        let message = $"Attention server cannot find module state for {mpath'} while processing package {pdir'}."
                        trace Critical (fun () -> message) _locals
                        Hopac.start (Ch.send errors.fatal message)
                        loop s
                    | Some m ->
                        trace Verbose (fun () -> $"Supervisor.attention_server.loop_package.module_ready / mpath: {mpath'}") _locals
                        send_tokenizer uri m.tokenizer.errors
                        clear_parse uri
                        bundler m.bundler []
                | [] -> loop s

            let package s =
                match s.packages with
                | se,x :: xs ->
                    let x' = x |> SpiralFileSystem.standardize_path
                    trace Verbose (fun () -> $"Supervisor.attention_server.loop.package / x: {x} / x': {x'}") _locals
                    let x = x'
                    let s = {s with packages=Set.remove x se,xs}
                    let package_errors =
                        match Map.tryFind x s.supervisor.packages with
                        | Some v -> List.concat [v.errors_parse; v.errors_modules; v.errors_packages]
                        | None -> []
                    Hopac.start (Ch.send errors.package ({|uri=file_uri(spiproj_suffix x); errors=package_errors|}))
                    clear_old_package x
                    match Map.tryFind x (fst s.supervisor.package_ids) with
                    | Some uid ->
                        match Map.tryFind uid s.supervisor.packages_infer.ok with
                        | Some v ->
                            let path_tcvals =
                                let uids_file = v.files.uids_file
                                let rec loop x s =
                                    match x with
                                    | ProjFilesTree.File(mid,path,_) ->
                                        let path' = path |> SpiralFileSystem.standardize_path
                                        trace Verbose (fun () -> $"Supervisor.attention_server.loop | WDiff.File(mid,path,_) / path: {path} / path': {path'}") _locals
                                        (path', (fst uids_file.[mid]).result) :: s
                                    | ProjFilesTree.Directory(_,_,l) -> list l s
                                and list l s = List.foldBack loop l s
                                list v.files.files.tree []
                            loop_package s x path_tcvals
                        | None -> loop s
                    | None -> loop s
                | _, [] -> req >>=* (update s >> loop)

            match s.modules with
            | se,x :: xs ->
                let s = {s with modules=Set.remove x se,xs}
                let x' = x |> SpiralFileSystem.standardize_path
                trace Verbose (fun () -> $"Supervisor.attention_server.loop / x: {x} / x': {x'}") _locals
                match Map.tryFind x s.supervisor.modules with
                | Some v ->
                    let codeDir = x |> System.IO.Path.GetDirectoryName
                    let tokensPath = codeDir </> "tokens.json"
                    if tokensPath |> System.IO.File.Exists |> not
                    then loop_module s x v
                    else
                        trace Verbose (fun () -> $"Supervisor.attention_server.loop / tokens found, skipping / x: {x}") _locals
                        package s
                | None -> clear (file_uri x); package s
            | _,[] -> package s

        (req >>=* fun (modules,packages,supervisor) ->
            loop {modules = Set.ofArray modules, Array.toList modules; packages = Set.ofArray packages, Array.toList packages; supervisor = supervisor; old_packages = Map.empty}
            )

    /// ### show_position
    let show_position (s : SupervisorState) (x : Range) =
        let line = (fst x.range).line
        let col = (fst x.range).character
        let er_code = s.modules.[x.path].tokenizer.lines_text.[line]
        StringBuilder()
            .AppendLine(sprintf "Error trace on line: %i, column: %i in module: %s ." (line+1) (col+1) x.path)
            .AppendLine(er_code)
            .Append(' ',col)
            .AppendLine("^")
            .ToString()

    /// ### show_trace
    let show_trace s (x : Trace) (msg : string) =
        let rec loop (l : Trace) = function
            | (x : Range) :: xs ->
                match l with
                | x' :: _ when x.path = x'.path && fst x.range = fst x'.range -> loop l xs
                | _ -> loop (x :: l) xs
            | _ -> l
        List.map (show_position s) (loop [] x), msg

    /// ### BuildResult
    type BuildResult =
        | BuildOk of GeneratedFile list
        | BuildErrorTrace of string list * string
        | BuildFatalError of string
        | BuildSkip

    /// ### workspaceRoot
    let workspaceRoot = SpiralFileSystem.get_workspace_root ()

    /// ### targetDir
    let targetDir = workspaceRoot </> "target/spiral_Eval"

    /// ### traceDir
    let traceDir = targetDir </> "supervisor_trace"

    /// ### dir
    let dir uri =
        let result = System.IO.FileInfo(System.Uri(uri).LocalPath).Directory.FullName
        let result' = result |> SpiralFileSystem.standardize_path
        trace Verbose (fun () -> $"Supervisor.dir / uri: {uri} / result: {result} / result': {result'}") _locals
        result'

    /// ### file
    let file uri =
        let result =
            try
                System.IO.FileInfo(System.Uri(uri).LocalPath).FullName
            with ex ->
                trace Verbose (fun () -> $"Supervisor.file / uri: {uri} / ex: %A{ex}") _locals
                uri
        let result' = result |> SpiralFileSystem.standardize_path
        // let result = result |> SpiralSm.replace "\\" "|"
        // trace Verbose (fun () -> $"Supervisor.file / uri: {uri} / result: {result} / result': {result'}") _locals
        result'

    /// ### supervisor_server
    let supervisor_server (default_env : DefaultEnv) atten (errors : SupervisorErrorSources) req =
        let fatal x = Hopac.start (Ch.send errors.fatal x)
        let handle_packages (dirty_packages,s) = Hopac.start (Ch.send atten ([||],dirty_packages,s)); s
        let handle_file_packages file (dirty_packages,s) = Hopac.start (Ch.send atten ([|file|],dirty_packages,s)); s
        let handle_files_packages (dirty_files,(dirty_packages,s)) = Hopac.start (Ch.send atten (dirty_files,dirty_packages,s)); s
        let loop (s : SupervisorState) = req >>- function
            | SupervisorReq.ProjectFileChange x | SupervisorReq.ProjectFileOpen x -> proj_open default_env s (dir x.uri,Some x.spiprojText) |> handle_packages
            | SupervisorReq.FileOpen x ->
                let file = file x.uri
                // trace Verbose (fun () -> $"Supervisor.supervisor_server.loop.FileOpen / x: %A{x} / file: {file}") _locals
                match Map.tryFind file s.modules with
                | Some m -> wdiff_module_all default_env m x.spiText
                | None -> wdiff_module_init_all default_env (is_top_down file) x.spiText
                |> fun v -> proj_revalidate_owner default_env {s with modules = Map.add file v s.modules} file
                |> handle_file_packages file
            | SupervisorReq.FileChange x ->
                let file = file x.uri
                trace Verbose (fun () -> $"Supervisor.supervisor_server.loop.FileChange / x: %A{x} / file: {file}") _locals
                match Map.tryFind file s.modules with
                | None -> fatal "It is not possible to apply a change to a file that is not present in the environment. Try reopening it in the editor."; s
                | Some m ->
                    match wdiff_module_edit default_env m x.spiEdit with
                    | Ok v -> proj_revalidate_owner default_env {s with modules = Map.add file v s.modules} file |> handle_file_packages file
                    | Error er -> fatal er; s
            | SupervisorReq.FileDelete x ->
                trace Verbose (fun () -> $"Supervisor.supervisor_server.loop.FileDelete / x: {x}") _locals
                file_delete default_env s (Array.map file x.uris) |> handle_files_packages
            | SupervisorReq.ProjectFileLinks(x,res) ->
                let l =
                    match Map.tryFind (dir x.uri) s.packages with
                    | None -> []
                    | Some x ->
                        let mutable l = []
                        x.schema.packages |> List.iter (fun x ->
                            let r,dir = x.dir
                            trace Verbose (fun () -> $"Supervisor.supervisor_server.ProjectFileLinks / x.schema.packages |> List.iter / dir: {dir}") _locals
                            if Map.containsKey dir s.packages then l <- (r,file_uri (spiproj_suffix dir)) :: l
                            )
                        let rec loop = function
                            | FileHierarchy.Directory(_,_,_,l) -> list l
                            | FileHierarchy.File(_,(r,path),_) ->
                                trace Verbose (fun () -> $"Supervisor.supervisor_server.ProjectFileLinks.loop | SpiProj.FileHierarchy.File(_,(r,path),_) / path: {path}") _locals
                                if Map.containsKey path s.modules then l <- (r,file_uri path) :: l
                        and list l = List.iter loop l
                        list x.schema.modules
                        l
                Hopac.start (IVar.fill res l)
                s
            | SupervisorReq.ProjectCodeActions(x,res) ->
                let z =
                    match Map.tryFind (dir x.uri) s.packages with
                    | None -> []
                    | Some x ->
                        let mutable z = []
                        let actions_dir (r,path) =
                            match r with
                            | None -> ()
                            | Some r ->
                                if Directory.Exists(path) then
                                    z <- (r,RenameDirectory {|dirPath=path; target=null; validate_as_file=false|}) :: (r,DeleteDirectory {|dirPath=path; range=r|}) :: z
                                else
                                    z <- (r,CreateDirectory {|dirPath=path|}) :: z
                        actions_dir x.schema.moduleDir
                        actions_dir x.schema.packageDir

                        let rec actions_module = function
                            | FileHierarchy.Directory(r',(r,path),_,l) ->
                                trace Verbose (fun () -> $"Supervisor.supervisor_server.ProjectCodeActions.actions_module | SpiProj.FileHierarchy.Directory(r',(r,path),_,l) / path: {path}") _locals
                                if Directory.Exists(path) then
                                    z <- (r,RenameDirectory {|dirPath=path; target=null; validate_as_file=true|}) :: (r,DeleteDirectory {|dirPath=path; range=r'|}) :: z
                                else
                                    z <- (r,CreateDirectory {|dirPath=path|}) :: z
                                actions_modules l
                            | FileHierarchy.File(r',(r,path),_) ->
                                trace Verbose (fun () -> $"Supervisor.supervisor_server.ProjectCodeActions.actions_module | SpiProj.FileHierarchy.File(r',(r,path),_) / path: {path}") _locals
                                if Map.containsKey path s.modules then
                                    z <- (r,RenameFile {|filePath=path; target=null|}) :: (r,DeleteFile {|range=r'; filePath=path|}) :: z
                                else
                                    z <- (r,CreateFile {|filePath=path|}) :: z
                        and actions_modules l = List.iter actions_module l
                        actions_modules x.schema.modules
                        z
                Hopac.start (IVar.fill res z)
                s
            | SupervisorReq.ProjectCodeActionExecute(x,res) ->
                let error, s =
                    match code_action_execute x.action with
                    | Error x -> Some x, s
                    | Ok null -> None, proj_open default_env s (dir x.uri,None) |> handle_packages
                    | Ok path -> None, file_delete default_env s [|path|] |> handle_files_packages
                Hopac.start (IVar.fill res {|result=error|})
                s
            | SupervisorReq.FileTokenRange(x, res) ->
                let v =
                    match Map.tryFind (file x.uri) s.modules with
                    | Some v -> Some v
                    | None when x.uri |> SpiralSm.ends_with ".dib" ->
                        x.uri
                        |> SpiralSm.replace "file:///" ""
                        |> File.ReadAllText
                        |> wdiff_module_init_all default_env (is_top_down x.uri)
                        |> Some
                    | None -> None

                match v with
                | Some v ->
                    Hopac.start (semantic_tokens v.parser >>=* (vscode_tokens x.range >> IVar.fill res))
                | None ->
                    if x.uri |> SpiralSm.starts_with "vscode-notebook-cell" |> not then
                        trace Debug
                            (fun () -> $"Supervisor.supervisor_server.FileTokenRange")
                            (fun () -> $"module=None / x.uri: {x.uri} / {_locals ()}")

                    Hopac.start (IVar.fill res [||])
                s
            | SupervisorReq.HoverAt(x,res) ->
                let file = file x.uri
                let pos = x.pos
                let _locals () = $"x: %A{x} / file: {file} / res: %A{res}"
                trace Verbose (fun () -> $"Supervisor.supervisor_server.HoverAt") _locals
                let go_hover x =
                    match x with
                    | None -> None
                    | Some (x : InferResult) ->
                        x.hovers |> Array.tryPick (fun ((a,b),r) ->
                            if pos.line = a.line && (a.character <= pos.character && pos.character < b.character) then Some r else None
                            )
                    |> (fun x ->
                        let _locals () = $"x: %A{x}"
                        trace Verbose (fun () -> $"Supervisor.supervisor_server.HoverAt.go_hover") _locals
                        x
                    )
                    |> IVar.fill res
                let go_block (x : TypecheckerState) =
                    let rec loop s (x : TypecheckerStateValue Stream) =
                        x >>=* function
                        | Nil -> go_hover s
                        | Cons((_,x,_),b) ->
                            let _locals () = $"b: {b}"
                            trace Verbose (fun () -> $"Supervisor.supervisor_server.HoverAt.go_block.loop Cons") _locals
                            if x.offset <= pos.line then loop (Some x) b
                            // If the block is over the offset that means the previous one must be the right choice.
                            else go_hover s
                    Hopac.start (loop None x.result)
                let rec go_file uids_file trees =
                    let rec loop = function
                        | ProjFilesTree.File(uid,file',_) -> if file = file' then go_block (Array.get uids_file uid |> fst); true else false
                        | ProjFilesTree.Directory(_,_,l) -> list l
                    and list l = List.exists loop l
                    list trees
                let rec go_parent (x : DirectoryInfo) =
                    trace Verbose (fun () -> $"Supervisor.supervisor_server.HoverAt.go_parent / x: %A{x}") _locals
                    if x = null then false
                    else
                        let path = x.FullName |> SpiralFileSystem.standardize_path
                        if Map.containsKey path s.packages then
                            let pid = (fst s.package_ids).[path]
                            match Map.tryFind pid s.packages_infer.ok with
                            | None -> false
                            | Some x -> go_file x.files.uids_file x.files.files.tree
                        else
                            go_parent x.Parent
                if go_parent (Directory.GetParent(file)) = false then Hopac.start (IVar.fill res None)
                s
            | SupervisorReq.BuildFile (x, res) ->
                let backend = x.backend
                let file = file x.uri
                let _locals () = $"x: %A{x} / file: {file}"
                trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile") _locals
                let handle_build_result = function
                    | BuildOk l ->
                        Job.fromAsync (async {
                            for x in l do
                                let file = Path.ChangeExtension(file,null) // null removes the extension from path.
                                do! System.IO.File.WriteAllTextAsync(file + x.file_extension, x.code) |> Async.AwaitTask
                        })
                        |> Hopac.start
                        l
                        |> List.map (fun x -> x.code)
                        |> String.concat "\n"
                        |> Some
                        |> IVar.fill res
                    | BuildFatalError x as x' ->
                        trace Info (fun () -> $"Supervisor.supervisor_server.BuildFile.handle_build_result / BuildFatalError x: %A{x}") _locals
                        Hopac.start (Ch.send errors.fatal x)
                        IVar.fill res None
                    | BuildErrorTrace(a,b) as x' ->
                        trace Info (fun () -> $"Supervisor.supervisor_server.BuildFile.handle_build_result / BuildErrorTrace x': %A{x'}") _locals
                        Hopac.start (Ch.send errors.traced {|trace=a; message=b|})
                        IVar.fill res None
                    | BuildSkip ->
                        trace Info (fun () -> $"Supervisor.supervisor_server.BuildFile.handle_build_result.BuildSkip") _locals
                        IVar.fill res None
                let file_build (s : SupervisorState) mid (tc : ProjStateTC, prepass : ProjStatePrepass) =
                    trace Verbose (fun () -> $"""Supervisor.supervisor_server.BuildFile.file_build / modules: %A{s.modules.Keys |> SpiralSm.concat ", "} / packages: %A{s.packages.Keys |> SpiralSm.concat ", "} / package_ids: %A{s.package_ids |> fst |> fun x -> x.Keys |> SpiralSm.concat ", "}""") _locals
                    let a,b = tc.files.uids_file.[mid]
                    let x,_x = prepass.files.uids_file.[mid]
                    trace Verbose (fun () -> "Supervisor.supervisor_server.BuildFile.file_build.wait_type_input") _locals
                    Hopac.start (a.state >>=* fun (has_error',_) ->
                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build.type_input_ready / has_error: {has_error'}") _locals
                        b >>=* fun (has_error,_) ->
                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build.type_path_ready / has_error: {has_error}") _locals
                        if has_error || has_error' then
                            // The editor gets the typer's errors from the attention loop; a batch build only gets this
                            // message, so it carries the package's errors itself.
                            // Every package's files, the entry's first: the error is often in a dependency.
                            let rec files (tc : ProjStateTC) x acc =
                                match x with
                                | ProjFilesTree.File(mid,path,_) -> (path, (fst tc.files.uids_file.[mid]).result) :: acc
                                | ProjFilesTree.Directory(_,_,l) -> List.foldBack (files tc) l acc
                            let states =
                                let seen = HashSet<obj>(HashIdentity.Reference)
                                tc :: (Seq.append s.packages_infer.ok.Values s.packages_infer.error.Values |> List.ofSeq)
                                |> List.filter (fun state -> seen.Add (box state))
                            states |> List.collect (fun state -> List.foldBack (files state) state.files.files.tree [])
                            |> List.map (fun (path,result) ->
                                Stream.foldFun (fun s (_,x : InferResult,_) -> s @ x.errors) [] result >>- fun errors ->
                                errors |> List.map (fun ((a,_),message) -> $"{path}:{a.line + 1}:{a.character + 1}: {message}"))
                            |> Job.seqCollect
                            >>= fun errors ->
                                let details = errors |> Seq.concat |> String.concat "\n"
                                let details = if details = "" then "" else $"\n{details}"
                                fatal $"File {Path.GetFileNameWithoutExtension file} has a type error somewhere in its path.{details}"
                                IVar.fill res None
                        else
                        trace Verbose (fun () -> "Supervisor.supervisor_server.BuildFile.file_build.wait_prepass") _locals
                        // Also note whether the entry file defines `main` itself: an `open` can bring another module's
                        // `main` into scope too (a sub-package whose module `main` opens its dependency's module `main`).
                        Stream.foldFun (fun (own_main,_) ((_,adds,env) : PrepassStateValue) ->
                            own_main || (match adds with AInclude small -> Map.containsKey "main" small.term | AOpen _ -> false), env
                            ) (false,prepassTop_env_empty) x.result >>=* fun (own_main,env) ->
                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build.prepass_ready / terms: {env.term.Count} / own_main: {own_main}") _locals
                        // A block that fails to tokenize or parse is left out of its module and the build goes on, so a
                        // broken `main` would be replaced by an opened module's `main` without a word. When the entry
                        // does not define `main` itself, report its tokenizer and parser errors instead. The bundles are
                        // the ones type checking consumed (complete by now); the parser errors ride on them.
                        let entry_errors =
                            if own_main then Job.result []
                            else
                                let _,_,bundles = a.input
                                let tokenizer_errors = match Map.tryFind file s.modules with Some m -> m.tokenizer.errors | None -> []
                                Stream.foldFun (fun errors (_,bundle : BlockBundleValue) -> errors @ bundle.errors) tokenizer_errors bundles
                        entry_errors >>=* fun entry_errors ->
                        let body() =
                            match backend, Map.tryFind "main" env.term with
                            | "Check", _ -> BuildSkip
                            | _, _ when not (List.isEmpty entry_errors) ->
                                let details = entry_errors |> List.map (fun ((a,_),message) -> $"\n{file}:{a.line + 1}:{a.character + 1}: {message}") |> String.concat ""
                                BuildFatalError $"Cannot find `main` in file {Path.GetFileNameWithoutExtension file}: the file does not define it, and it has errors (a block that fails to parse is left out, so `main` would come from an opened module).{details}"
                            | _, Some main ->
                                let prototypes_instances = Dictionary(env.prototypes_instances)
                                let nominals =
                                    let t = HashConsTable()
                                    let d = Dictionary()
                                    env.nominals |> Map.iter (fun k v -> d.Add(k, nominal_add t k v))
                                    d
                                try
                                    let inline build_many codegen backend =
                                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build.peval_start / backend: {backend}") _locals
                                        let (a,_),b = peval {prototypes_instances=prototypes_instances; nominals=nominals; backend=backend} main
                                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build.peval_ready / backend: {backend}") _locals
                                        let generated = codegen file b a
                                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build.codegen_ready / backend: {backend} / files: {List.length generated}") _locals
                                        BuildOk generated
                                    let build codegen backend file_extension =
                                        build_many (fun file b a -> [generated_file (codegen b a) file_extension]) backend
                                    match backend with
                                    | "Gleam" -> build codegenGleam "Gleam" ".gleam"
                                    | "Lua" -> build codegenLua "Lua" ".lua"
                                    | "Fsharp" -> build codegenFsharp "Fsharp" ".fsx"
                                    | "Rust" -> build codegenRust "Rust" ".rs"
                                    | "Delphi" -> build codegenDelphi "Delphi" ".pas"
                                    | "C" -> build CodegenC.codegenC "C" ".c"
                                    | "Python + Cuda" -> build_many (CodegenPython.codegen default_env) "Python"
                                    | "Cpp + Cuda" -> build_many (CodegenCpp.codegen default_env) "Cpp"

                                    | "Cuda C++" -> BuildFatalError "The host C++ backend originally made for FPGAs, and then ported to Cuda has been removed in v2.10.0 of Spiral. Please use an earlier version to access it." // Date: 5/8/2024
                                    | "Python" -> BuildFatalError "The prototype Python backend has been replaced by the Python + Cuda one in v2.5.0 of Spiral. Please use an earlier version to access it." // Date: 11/3/2023
                                    | "UPMEM: Python + C" -> BuildFatalError "The UPMEM Python + C backend has been replaced by the Python + Cuda one in v2.5.0 of Spiral. Please use an earlier version to access it." // Date: 11/3/2023
                                    | "HLS C++" -> BuildFatalError "The HLS C++ backend has been replaced by the Cuda one in v2.5.0 of Spiral. Please use an earlier version to access it." // Date: 10/17/2023
                                    | "Cython*" | "Cython" -> BuildFatalError "The Cython backend has been replaced by the Python one in v2.3.1 of Spiral. Please use an earlier version to access it." // Date: 12/27/2022
                                    | _ -> BuildFatalError $"Cannot recognize the backend: {backend}"
                                with
                                    | :? PartEvalTypeError as e -> BuildErrorTrace(show_trace s e.Data0 e.Data1)
                                    | :? CodegenError as e -> BuildFatalError(e.Data1)
                                    | :? CodegenErrorWithPos as e -> BuildErrorTrace(show_trace s e.Data0 e.Data1)
                                    | ex ->
                                        if System.IO.Directory.Exists traceDir then
                                            let guid = System.DateTime.Now |> SpiralDateTime.new_guid_from_date_time
                                            let trace_file = traceDir </> $"{guid}_error.json"
                                            async {
                                                try
                                                    do! $"{ex}" |> SpiralFileSystem.write_all_text_async trace_file
                                                with ex ->
                                                    trace Critical (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build / ex: {ex |> SpiralSm.format_exception}") _locals
                                            }
                                            |> Async.Start
                                        trace Critical (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build / ex: %A{ex}") _locals
                                        BuildFatalError(ex.Message)
                            | _, None -> BuildFatalError $"Cannot find `main` in file {Path.GetFileNameWithoutExtension file}."

                        // The partial evaluator is using too much stack space, so as a temporary fix, I am running it on a separate thread with much more of it.
                        // Restored 2026-09-30: commit 1eb2ecf had replaced the thread with an inline call, so peval ran
                        // on a 1.5 MB Hopac worker stack and overflowed on file_system.read_link (apps/spiral's wall).
                        let result = IVar()
                        let thread = new System.Threading.Thread((fun () -> body () |> IVar.fill result |> Hopac.start), 1536 <<< 20)
                        thread.Start()
                        IVar.read result >>= handle_build_result
                        )
                let file_find (s : SupervisorState) pdir =
                    trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_find / pdir: {pdir}") _locals
                    let uid = (fst s.package_ids).[pdir]
                    match Map.tryFind uid s.packages_infer.ok, Map.tryFind uid s.packages_prepass.ok with
                    | Some a, Some b ->
                        let rec loop = function
                            | ProjFilesTree.Directory(_,_,l) -> list l
                            | ProjFilesTree.File(mid,path,_) ->
                                trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_find.loop | File(mid,path,_) / path: {path}") _locals
                                if file = path then file_build s mid (a, b); true else false
                        and list l = List.exists loop l
                        if list b.files.files.tree = false then fatal $"File {Path.GetFileNameWithoutExtension file} cannot be found in the project {spiproj_suffix pdir}"

                        s
                    | None, None ->
                        let ownerErrors =
                            match Map.tryFind pdir s.packages with
                            | Some schema -> schema.errors_parse @ schema.errors_modules @ schema.errors_packages |> List.map snd
                            | None -> []
                        let detail = if List.isEmpty ownerErrors then "" else " " + String.concat " " ownerErrors
                        fatal $"Owner of file {Path.GetFileNameWithoutExtension file} has an error. Location: {spiproj_suffix pdir}.{detail}"
                        s
                    | _ -> failwith "Compiler error: The project status should be the same in both infer and prepass."
                let update_owner pdir =
                    let order,dirty_packages = topological_sort' (fst s.graph) [pdir]
                    let packages_prepass = wdiff_projenvr_prepass default_env (fst s.package_ids) s.packages s.packages_infer.ok s.packages_prepass (dirty_packages, order.ToArray())
                    file_find {s with packages_prepass = packages_prepass} pdir
                let rec find_owner (x : DirectoryInfo) =
                    if x = null then fatal $"Cannot find the package file of {file}"; s
                    else
                        let x' = x.FullName |> SpiralFileSystem.standardize_path
                        trace Verbose (fun () -> $"""Supervisor.supervisor_server.BuildFile.find_owner / x.FullName: {x.FullName |> SpiralSm.replace "\\" "|"} / x': {x'}""") _locals
                        let x_ = x
                        let x = {| FullName = x' |}
                        if Map.containsKey x.FullName s.packages then update_owner x.FullName
                        else find_owner x_.Parent
                find_owner (Directory.GetParent(file))

        Job.iterateServer {
            packages = Map.empty
            modules = Map.empty
            packages_infer = {ok=Map.empty; error=Map.empty}
            packages_prepass = {ok=Map.empty; error=Map.empty}
            graph = mirrored_graph_empty
            package_ids = Map.empty, Map.empty
            } loop

    /// ### ClientReq
    type ClientReq =
        | ProjectFileOpen of ProjectFileReq
        | ProjectFileChange of ProjectFileReq
        | ProjectFileLinks of UriReq
        | ProjectCodeActionExecute of ProjectCodeActionReq
        | ProjectCodeActions of UriReq
        | FileOpen of FileOpenReq
        | FileChange of FileChangeReq
        | FileDelete of FileDeleteReq // Also works for project files and directories.
        | FileTokenRange of FileTokenRangeReq
        | HoverAt of HoverAtReq
        | BuildFile of BuildFileReq
        | Ping of bool
        | Exit of bool

    /// ### ClientErrorsRes
    type ClientErrorsRes =
        | FatalError of string
        | TracedError of TracedError
        | PackageErrors of LocalizedErrors
        | TokenizerErrors of LocalizedErrors
        | ParserErrors of LocalizedErrors
        | TypeErrors of LocalizedErrors

    /// ### Supervisor
    type Supervisor = {
        supervisor_ch : SupervisorReq Ch
        }

