    /// ## new_server
    // #!import ../../../polyglot/apps/builder/Builder.fs
    // #!import ../../../polyglot/apps/spiral/Supervisor.fs
    

    
    open Hopac
    open Hopac.Infixes
    // open Common
    

    let private serializeServerResult (value: 'T) : string =
        match box value with
        | null -> null
        | :? Option<string> as optional -> optional.Value
        | boxed -> FSharp.Json.Json.serialize boxed

    type ServerRuntime(
        errorsStream: FSharp.Control.AsyncSeq<ClientErrorsRes>,
        supervisorChannel: Ch<SupervisorReq>) =

        member _.errors = errorsStream
        member _.supervisor = supervisorChannel

        member _.job_null<'TJob when 'TJob :> Job<unit>>(jobToStart: 'TJob) : Task<string> =
            HopacExtensions.start (jobToStart :> Job<unit>)
            task { return null }

        member _.job_val<'T, 'TJob, 'TJobResult when 'TJob :> Job<'TJobResult>>
            (jobFactory: IVar<'T> -> 'TJob) : Task<string> =
            let resultCell : IVar<'T> = IVar()
            let scheduled : Job<'TJobResult> = jobFactory resultCell :> Job<'TJobResult>
            HopacExtensions.queueAsTask (
                scheduled
                >>=. IVar.read resultCell
                >>- serializeServerResult
            )

    let private newServerCore () : ServerRuntime =
        // A queue, not an Event: Async.AwaitEvent subscribes for one event at a time, so a diagnostic
        // raised between two pulls of the stream was dropped. After a burst of parser errors that was
        // often the FatalError itself, and the host waited for the build until its budget ran out
        // (hopac FRONTIER.md fix 38).
        let pending = System.Threading.Channels.Channel.CreateUnbounded<ClientErrorsRes>()
        let stream =
            FSharp.Control.AsyncSeq.unfoldAsync
                (fun () -> async {
                    let! msg = pending.Reader.ReadAsync().AsTask() |> Async.AwaitTask
                    return Some (msg, ())
                })
                ()
    

        let error_ch_create msg =
            let x = Ch()
            HopacExtensions.server (Job.forever (Ch.take x >>= (
                msg >> fun (x : ClientErrorsRes) ->
                    Hopac.Job.awaitUnitTask (
                        task {
                            pending.Writer.TryWrite x |> ignore
                            BuildDiagnosticsLedger.note ("delivered_" + clientErrorsResKindText x)
                            trace Verbose (fun () -> $"spiral_compiler.new_server / error_ch_create / kind={clientErrorsResKindText x}") (fun () -> "")
                            ()
                        }
                        |> (fun (x : System.Threading.Tasks.Task<unit>) -> x :> System.Threading.Tasks.Task)
                    )
            )))
            x
    

        let errors : SupervisorErrorSources = {
            fatal = error_ch_create FatalError
            package = error_ch_create PackageErrors
            tokenizer = error_ch_create TokenizerErrors
            parser = error_ch_create ParserErrors
            typer = error_ch_create TypeErrors
            traced = error_ch_create TracedError
            }
        let supervisor = Ch()
        let atten = Ch()
    

        do HopacExtensions.server (attention_server errors atten)
    

        let args = [| "--port"; "0" |]
        let env = startupParse args
        do HopacExtensions.start (supervisor_server env atten errors supervisor)
    

        ServerRuntime(stream, supervisor)

    let new_server<'a, 'b, 'c, 'd, 'e when 'd :> Job<'e> and 'a :> Job<unit> and 'b : null> ()
        :
        {|
            errors: FSharp.Control.AsyncSeq<ClientErrorsRes>
            job_null: 'a -> Task<'b>
            job_val: (IVar<'c> -> 'd) -> Task<string>
            supervisor: Ch<SupervisorReq>
        |} =
        let runtime = newServerCore ()
        let jobNull (jobToStart: 'a) : Task<'b> =
            HopacExtensions.start (jobToStart :> Job<unit>)
            task { return null }
        let jobVal (jobFactory: IVar<'c> -> 'd) : Task<string> =
            let resultCell : IVar<'c> = IVar()
            let scheduled : Job<'e> = jobFactory resultCell :> Job<'e>
            HopacExtensions.queueAsTask (
                scheduled
                >>=. IVar.read resultCell
                >>- serializeServerResult
            )
        {|
            errors = runtime.errors
            job_null = jobNull
            job_val = jobVal
            supervisor = runtime.supervisor
        |}
    

